INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26094129', '名侦探柯南：业火的向日葵', '动画', '在美国曼哈顿举行的艺术品拍卖会上，一度被认为毁于二战空袭的梵高亲笔临摹向日葵系列2号画作惊艳登场。财大气粗的铃木财团顾问的铃木次郎吉（富田耕生 配音）一骑绝尘，以三亿美元天价将其收入囊中。在之后的记者招待会上，铃木宣布将联系分散在世界各地收藏家手中的向日葵画作集结在日本，举行一次梦幻展览。为此，他聘请毛利小五郎（小山力也 配音）、展览企划负责人圭子•安德森（榊原良子 配音）、画作鉴定师宫台夏美（荣仓奈奈 配音）等七位专家组成“七武士”团队为展览保驾护航。谁知怪盗基德（山口胜平 配音）从一开始便锁定该画作，他不仅大闹会场，还为了抢夺画作而险些炸毁运送专机。随着画展日期的临近，柯南（高山南 配音）与伙伴们必须尽快越过一座座难以想象的险峰……©豆瓣', '高山南', '静野孔文', 6, 79509, 'tt3737650', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2273435952.jpg', 6.5, 22.1, 45.2, 16.8, 9.5, '-0.208472,-0.104595,-0.447849,0.383751,0.234031,-0.276318,0.200683,0.160303,-0.003827,-0.097693,0.448374,0.715451,-0.384898,0.130283,0.531275,-0.038518,-0.281452,-0.761140,-0.382318,-0.184030,-0.086183,-0.400784,-0.031042,-0.300046,0.042376,-0.097617,0.691123,0.084903,-0.256889,0.534297,0.123279,0.133348,-0.283600,-0.045839,0.078493,-0.325937,0.289860,-0.063064,-0.202872,0.333386,-0.685634,-0.330166,0.025267,-0.001249,0.249951,0.108974,0.685078,-0.077713,0.172349,-0.134009,0.283074,-0.068651,0.056337,0.140912,0.256815,0.385014,-0.048182,0.081984,-0.754310,-0.006053,0.013456,-0.457864,-0.630277,-0.057409,-0.001352,0.131404,-0.234886,0.339400,-0.262349,0.190335,0.111457,-0.270512,0.023668,0.214688,0.281419,0.057918,0.031088,0.282479,-0.136267,0.502487,0.255662,-0.080827,0.210589,0.083315,0.337543,-0.270787,-0.190104,-0.237375,-0.001344,0.041998,0.402574,-0.081596,0.473535,-0.228517,-0.688222,-0.405347,-0.261860,-0.562724,0.082166,0.014874,-0.081218,-1.220443,0.237961,0.086753,-0.052789,-0.135601,0.450697,-0.102925,0.951311,-0.470103,0.081163,0.627956,0.126616,-0.029970,0.320665,-0.071299,-0.244126,-0.235005,-0.284221,-0.201151,0.258897,0.623960,-0.042510,0.155247,-0.036035,-0.413965,-0.340347,0.425614', '2369613', '26788667', '20274039', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26100958', '复仇者联盟4：终局之战', '剧情', '一声响指，宇宙间半数生命灰飞烟灭。几近绝望的复仇者们在惊奇队长（布丽·拉尔森 Brie Larson 饰）的帮助下找到灭霸（乔什·布洛林 Josh Brolin 饰）归隐之处，却得知六颗无限宝石均被销毁，希望彻底破灭。如是过了五年，迷失在量子领域的蚁人（保罗·路德 Paul Rudd 饰）意外回到现实世界，他的出现为幸存的复仇者们点燃了希望。与美国队长（克里斯·埃文斯 Chris Evans 饰）冰释前嫌的托尼（小罗伯特·唐尼 Robert Downey Jr. 饰）找到了穿越时空的方法，星散各地的超级英雄再度集结，他们分别穿越不同的时代去搜集无限宝石。而在这一过程中，平行宇宙的灭霸察觉了他们的计划。注定要载入史册的最终决战，超级英雄们为了心中恪守的信念前仆后继……©豆瓣', '小罗伯特·唐尼', '安东尼·罗素', 8.5, 1018894, 'tt4154796', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2552058346.jpg', 0.9, 2, 15.6, 35.1, 46.4, '-0.053526,0.474335,-0.642087,0.368314,0.032014,-0.228769,0.651564,-0.097612,-0.267958,-0.143115,0.045909,0.709818,-0.331421,-0.029914,0.267827,-0.334576,-0.329248,-0.519117,-0.182821,-0.307178,-0.298302,-0.423342,-0.574891,-0.163990,0.055411,-0.450735,0.853212,0.311578,-0.019162,0.286497,0.043208,0.440190,-0.147568,0.344545,-0.104323,0.110339,0.083213,-0.150238,-0.532497,0.157846,-0.440919,0.070805,-0.085372,0.246735,-0.289312,0.034432,0.756294,-0.536616,0.257148,-0.213490,0.253457,-0.157255,-0.125415,0.012795,0.011360,0.166470,-0.080752,0.101100,0.085372,0.048304,0.350616,0.050605,-0.927222,-0.033253,0.163852,0.209995,-0.435130,0.235933,-0.091443,0.074489,0.035222,-0.338635,0.195487,0.163536,0.424181,0.254920,-0.336111,0.018451,-0.438307,0.012820,0.498488,-0.264063,-0.342998,0.114979,-0.087720,-0.496950,-0.154700,0.086056,-0.268108,-0.303784,0.498155,0.301948,-0.009973,0.443869,-0.830269,-0.108604,-0.235317,-0.286051,-0.117132,-0.343274,0.011952,-0.602853,-0.113352,0.035812,-0.315617,0.310073,0.129593,0.001814,0.825301,-0.609376,0.354617,0.459355,0.045049,-0.347433,0.583151,0.072812,0.242965,-0.429156,0.046984,0.411912,0.080518,0.414842,0.045784,0.204496,-0.152360,-0.027059,-0.477787,0.530942', '26759820', '25774050', '25928048', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26101255', '人类清除计划3', '科幻', '一年一度的国定杀戮日即将到来，与此同时，美国总统大选也到了如火如荼的阶段，一方是创立并推行国定杀戮日的NFFA的代言人艾德维奇•欧文斯，一方则是曾被这个可怕的杀戮夺走家人的女参议员查理·罗恩（伊丽莎白·米切尔 Elizabeth Mitchell 饰）。查理不惜一切代价要将国定杀戮日废止，因此成为了NFFA的眼中钉，对方策划在杀戮之夜夺走她的性命。刚强的查理坚持当晚待在家中，而她的安全主管里奥（弗兰克·格里罗 Frank Grillo 饰）则打起十二分的精神准备应对四面八方的对手。由于内部出现奸细，里奥只能被迫带着罗恩逃离住所，在这一路上，他们得到一些支持者的救助，而对手也决不肯放过这个千载难逢的机会……©豆瓣', '弗兰克·格里罗', '詹姆斯·德莫纳克', 6.3, 36364, 'tt4094724', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2354593136.jpg', 3, 14.4, 54.9, 20.7, 6.9, '-0.020282,0.206139,-0.718014,0.425347,-0.115808,-0.253367,0.441803,0.172961,-0.421150,-0.231732,0.410735,0.750498,0.079504,-0.018569,0.558064,-0.202277,-0.095057,-0.521583,-0.229597,0.068199,-0.147165,-0.352430,-0.252156,-0.251430,-0.174741,-0.405342,0.680844,0.098133,-0.065254,0.450409,0.425957,0.257030,0.252758,0.514490,0.027305,-0.225483,-0.031296,-0.245575,-0.404119,0.550851,0.047210,-0.347412,-0.243495,0.624375,0.040578,0.537475,0.625025,-0.405437,0.140933,-0.282516,0.520869,-0.719226,0.053699,0.336471,0.475973,-0.034845,-0.085805,0.268809,-0.184378,0.116380,0.003693,-0.165007,-1.097803,0.002055,0.182751,0.173245,-0.503042,0.425646,-0.147909,0.068036,-0.034086,-0.447578,0.266782,0.568317,0.186204,0.054673,-0.192152,-0.194828,-0.489115,-0.000644,0.714482,-0.428442,0.070047,0.016626,-0.107759,-0.289792,0.146471,-0.422438,-0.489856,-0.395400,0.545033,0.201305,0.040649,0.322901,-0.569694,-0.153082,-0.429339,-0.222314,0.019563,-0.321302,0.023878,-0.538166,0.028994,-0.110815,-0.024098,0.242894,0.081424,-0.079903,0.630695,-0.808575,0.387153,0.768128,0.488097,-0.489542,0.487071,0.214231,0.341528,-0.246545,-0.030941,0.443555,0.261864,0.303258,-0.106957,0.208108,0.209615,-0.240459,-0.170092,0.557665', '1793491', '26678784', '30163500', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26106958', '喊·山', '剧情', '故事发生在闭塞的山区之中，韩冲（王紫逸 饰）为了捕猎设置了炸药，哪知道这炸药没被动物踩到，却被同村的腊宏（余皑磊 饰）给踩了个正着。炸药爆炸了，腊宏身受重伤，最终不治身亡，留下了可怜的哑巴妻子（郎月婷 饰）和一双儿女。经过全村人民的商议，韩冲决定赔钱将这件事情私聊，可是哑巴媳妇却似乎对赔偿的金额完全没有兴趣，整天疯疯癫癫胡言乱语，大家都认为，丈夫的死对于这个女人来说打击过大，她疯了。无奈之下，韩冲只得背负起了照顾母子三人生活的责任，在此过程中，他渐渐发现了哑巴媳妇的温柔可爱之处，两人渐渐走到了一起。©豆瓣', '郎月婷', '杨子', 8.1, 66952, 'tt4170472', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2373887821.jpg', 0.5, 2.4, 19.1, 48, 30, '0.302566,-0.075333,-0.729241,0.221585,-0.184263,-0.224047,0.772836,0.099193,-0.403046,-0.180405,0.168757,0.430407,-0.114883,0.047350,-0.096510,-0.147500,-0.209677,-0.589067,-0.258074,0.123329,-0.357960,-0.463694,0.087611,0.030015,-0.377970,-0.078962,0.280492,-0.024818,0.080506,0.220199,0.237934,0.314958,0.046691,0.377717,-0.193629,0.354526,-0.115939,0.027938,0.028848,0.096461,0.109591,-0.303051,0.076696,0.200353,-0.002956,0.445863,0.614256,-0.362406,-0.342848,-0.137533,0.250953,-0.350282,0.052903,0.280008,0.184404,-0.031073,0.405284,-0.045548,-0.220674,-0.114996,0.416303,0.064941,-0.413134,0.020959,0.128999,0.156182,-0.766765,0.488612,-0.133114,0.008712,-0.198588,-0.181806,0.562938,0.299357,0.218668,0.374873,-0.377069,0.128526,-0.541200,-0.033171,0.480129,0.016187,0.034066,0.389485,-0.303424,-0.286575,0.126542,-0.293192,-0.352511,-0.032578,0.318553,0.130456,-0.433190,0.242461,-0.369302,-0.028286,-0.001020,-0.166118,-0.198721,-0.380213,-0.190284,-0.058246,-0.087158,-0.378827,-0.361379,0.305935,0.019542,-0.099106,0.519543,-0.545101,0.156419,0.385792,0.187027,-0.530515,0.395749,0.034290,0.147668,-0.042658,0.142726,-0.099637,0.054940,0.239701,0.461850,0.304398,-0.015004,-0.191785,-0.382447,0.262567', '21619567', '3111650', '1299965', '10355329');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26125779', '危城', '剧情', '时值国家内战、军阀割据的乱世时代，军阀少帅曹少璘（古天乐 饰）因杀害三条人命，被普城保卫团团长杨克难（刘青云 饰) 绳之于法。可曹家财雄势大，以强权震慑居民，曹家上校张亦（吴京 饰）得悉事件后，赶来普城取人，在城中遇上多年不见师弟马锋（彭于晏 饰），马锋是位武功高强的浪人，路见不平欲拔刀相助，可是却面临正义与兄弟情之抉择。', '刘青云', '陈木胜', 5.9, 68423, 'tt5842624', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2372098911.jpg', 5.6, 21.2, 49.5, 17.5, 6.1, '-0.176090,-0.195941,-0.059308,0.223638,0.235276,-0.146726,0.395622,0.234282,-0.653490,-0.373399,0.492135,0.104756,0.159814,-0.145561,0.130858,-0.276392,0.018783,-0.475034,0.035703,0.178520,0.085655,-0.206777,-0.233687,-0.005944,-0.266648,0.132184,0.526204,0.501990,-0.354259,0.353153,0.282774,0.369386,-0.303203,0.389656,0.083149,0.007168,-0.030255,-0.040109,-0.618453,-0.246364,-0.175557,-0.326810,-0.449459,0.104555,-0.053074,0.256210,0.464246,-0.249333,0.074557,-0.367466,0.165563,-0.315841,0.104341,-0.118753,0.585475,-0.119779,0.104694,0.254426,0.150705,-0.182330,0.246534,-0.102643,-0.132764,0.014800,0.512001,-0.066818,-0.165423,0.337365,-0.382538,0.015230,-0.074707,-0.324271,0.136546,0.210136,0.393784,0.082474,0.082633,-0.164934,-0.628654,0.231400,0.483511,-0.150266,-0.176729,-0.521418,0.056489,-0.540581,0.073977,-0.577485,-0.375787,0.010639,0.195028,-0.556828,0.089668,0.433350,-0.154568,-0.221142,-0.320161,0.642741,0.020575,-0.181198,0.097942,-0.120276,-0.085735,-0.048764,-0.025033,0.478458,0.440929,-0.111582,0.565576,-0.429632,-0.304734,-0.011414,0.035745,-0.578415,0.396931,0.034323,0.045058,-0.135690,-0.137172,0.080298,0.338301,0.059301,0.100763,-0.032449,-0.364476,-0.181933,0.462052,-0.074291', '1440958', '1306998', '24745500', '1433736');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26140241', '咱们结婚吧', '喜剧', '始终找不到真正想要人生的女孩文艺（郭碧婷 饰）独自踏上路途，前往意大利参加小提琴比赛，在那里她遇到了地陪李想（李晨 饰）。短短几天的相处，令她的内心发生了变化。风流倜傥的副机长凌霄（郑恺 饰）和担任地勤的女友顾小蕾（陈意涵 饰）同居多年，可是面对小蕾及对方父母的结婚要求，他却望而却步。某酒店的烤鸭师傅曹大鹏（王自健 饰）对担任主管的老婆田海心（刘涛 饰）言听计从，海心好不容易得到事业的转机，却发现自己怀孕，这也成为夫妻俩战争的导火索。曾有过一段伤心爱情经历的叶雯雯（高圆圆 饰）是某婚纱店的店长，她拒绝旧爱（明道 饰）的示好，全身心地为新人们准备精美的婚纱，全然没有注意到婚纱设计师陈震轩（姜武 饰）充满挚爱和关怀的目光。繁华的都市中，男男女女为了各自的爱情兀自奔忙……©豆瓣', '高圆圆', '刘江', 5.9, 85058, 'tt4572856', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2232079769.jpg', 5.4, 21.8, 51.6, 16.1, 5.2, '0.190777,0.090526,-0.702338,0.540105,-0.061076,-0.452918,0.691634,0.056698,-0.538267,-0.469848,0.342805,0.490223,-0.379707,0.338560,0.412828,-0.053387,-0.140569,-0.673530,0.079673,0.223294,-0.102856,-0.183176,-0.215803,0.125659,-0.162062,0.110619,0.618205,0.194635,0.063594,0.582878,0.519932,0.180776,0.123652,0.481345,-0.034312,-0.002365,0.058362,0.382942,-0.436783,-0.028787,-0.015733,-0.251769,-0.202546,0.180087,0.023728,0.288721,0.573311,0.074942,-0.165277,0.095457,0.533556,-0.065210,0.135025,-0.063443,0.003849,0.110686,0.066748,0.122186,-0.153207,0.052176,0.105179,0.018619,-0.447359,0.089590,0.155869,0.281501,-0.451069,0.433799,-0.217855,-0.073113,0.156578,-0.434672,0.095072,0.194903,0.286392,0.298500,-0.004338,0.252366,-0.489209,0.475651,0.669719,0.168090,-0.044966,0.274578,-0.258058,-0.348389,0.021795,-0.177470,-0.509009,0.106398,0.021370,0.103592,0.068183,-0.027532,-0.533428,-0.031572,0.028357,-0.134489,0.387621,-0.357305,-0.038189,-0.746412,-0.112191,-0.717828,-0.357647,-0.065671,-0.060767,-0.289266,0.477885,-0.809603,0.082067,0.164346,0.173691,-0.626597,0.715855,0.302171,0.064874,-0.411929,-0.014235,0.519056,-0.346755,0.152117,-0.115303,0.108992,0.050829,-0.074348,-0.364093,0.282861', '1301022', '3033092', '26354526', '25777330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26140265', '新生化危机', '动作', '浣熊市曾是蓬勃发展的制药巨头——伞公司(Umbrella Corporation)的总部所在地，现在却是一个死气沉沉的中西部小镇。该公司的大撤离使这座城市变成了一片荒地，地下蕴藏着巨大的邪恶。当邪恶被释放时，镇上的人们将永远改变，一小群幸存者必须共同努力，揭开保护伞背后的真相，并度过夜晚。', '汉娜·乔恩-卡门', '约翰内斯·罗伯茨', 4.6, 19421, 'tt6920084', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2692391480.jpg', 22.5, 37.8, 29.9, 6.7, 3.2, '0.129219,0.431045,-0.590295,0.293983,0.002561,0.270024,0.702299,0.204049,-0.370991,-0.013287,0.169015,0.686425,0.005460,0.449170,0.012537,0.242115,-0.066948,-0.289685,-0.519890,-0.217042,-0.225694,-0.107323,-0.547535,-0.269665,0.087082,0.107519,0.696722,0.921318,-0.265073,-0.037763,0.238448,0.075836,-0.401815,0.464330,-0.014671,-0.467526,0.028947,-0.227806,-0.281477,0.160798,-0.411268,-0.175524,0.028501,0.235861,-0.035157,0.162974,0.541585,-0.011246,-0.234254,-0.499415,0.348685,-0.143082,-0.179304,-0.136675,0.629313,-0.064784,-0.066024,0.253374,-0.275572,-0.255292,0.135424,-0.421176,-0.918109,0.034291,0.256712,-0.018541,-0.691387,0.059184,0.472812,-0.188771,0.027655,-0.319765,0.473654,0.320854,0.087564,0.369075,0.024752,0.268769,-0.676161,0.234126,0.619139,-0.301842,-0.359898,-0.205809,-0.304548,-0.244418,-0.271249,-0.025570,-0.298072,-0.110306,0.263466,0.019968,-0.225028,0.297662,-0.704868,0.096617,-0.464814,-0.774942,0.240589,-0.330521,-0.356165,-0.442569,0.062911,0.281684,0.068149,0.358477,0.110642,0.248556,0.649444,-0.787127,0.303728,0.674233,0.549302,-0.195070,0.425631,-0.269950,0.401159,-0.286875,-0.096993,0.316114,-0.031154,0.926547,0.003701,0.146453,-0.145105,-0.222825,-0.404008,0.521527', '1292523', '1793491', '6532822', '11810348');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26140405', '爱的成人式', '剧情', 'A面：在某次联谊会上，身体肥胖且其貌不扬的大学生铃木夕树邂逅了美丽女孩茧子（前田敦子 饰）。他帮对方解围，对方似乎也对他有了好感。在此后的日子里，两人见面的次数增多，在茧子的鼓励和建议下，铃木尝试着改变自己的造型，力争成为女孩心目中理想的男性。那一年的圣诞节，他们的爱情走向顶点。B面：大学毕业后，铃木进入职场，并按照公司的安排前往东京进行深造，因此不得不和茧子经历远距离的恋爱。起初一切还好，但随着时间的流逝，两人之间逐渐出现隔阂，而远在东京的铃木又邂逅了美丽的女同事美弥子（木村文乃 饰），爱情的天平进一步倾斜……本片根据乾胡桃的同名原作改编。©豆瓣', '松田翔太', '堤幸彦', 7.7, 43283, 'tt4119590', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2230009009.jpg', 0.5, 2.6, 28.1, 50.5, 18.3, '0.208720,0.120284,-0.533353,0.446258,-0.013245,-0.190259,0.716759,0.232669,-0.398080,-0.174001,0.168539,0.485887,-0.386963,0.232957,0.267776,-0.210726,-0.429927,-0.849640,-0.048259,-0.119668,-0.167919,-0.516278,-0.264342,-0.141932,-0.196245,-0.232825,0.837759,0.115603,-0.254000,0.612457,0.217850,-0.125239,-0.065362,0.372407,-0.065265,0.080098,0.003108,0.202578,-0.302966,0.208883,0.081158,-0.364478,-0.145358,-0.011590,0.029994,0.455022,0.749386,-0.029690,-0.176126,0.135403,0.518216,-0.097754,-0.183128,0.049575,0.428541,0.295791,0.167017,0.266131,-0.243872,-0.039751,-0.209315,-0.299955,-0.443822,0.111353,-0.033842,0.310056,-0.537905,0.659586,0.101072,-0.042052,0.291954,-0.302276,-0.031546,0.397450,0.409195,0.066040,-0.460106,0.178747,-0.035137,0.250128,0.788542,0.193214,-0.282485,0.291153,-0.401350,-0.460362,-0.510060,0.057621,-0.306158,-0.106191,0.047701,0.263395,-0.100515,0.163865,-0.636593,0.079572,-0.084492,-0.137348,0.268120,-0.216001,0.039391,-0.904610,-0.262799,-0.735217,-0.526378,-0.103916,0.054016,-0.327496,0.749127,-0.960976,0.100384,0.493129,0.390888,-0.223250,0.699935,0.290115,0.070627,-0.374499,-0.166862,0.396974,-0.244319,0.162321,-0.033571,0.402324,-0.253845,0.023949,-0.573216,0.444456', '1826173', '3811356', '1316589', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26145033', '乐高蝙蝠侠大电影', '喜剧', '罪恶丛生的哥谭市，疯狂的小丑（扎克·加利凡纳基斯 Zach Galifianakis 配音）带领恶棍军团展开新一波的犯罪活动。对他来说，犯罪以及引来宿敌蝙蝠侠（威尔·阿奈特 Will Arnett 配音）是无比快乐的事情，可是猛男蝙蝠侠不仅轻松解决掉这群小坏蛋，还根本不将小丑放在眼里。蝙蝠侠的无情言语，深深刺痛了小丑的心。在此之后，孤独的蝙蝠侠收养了罗宾（迈克尔·塞拉 Michael Cera 配音），看上了美丽的女警长芭芭拉，只不过他始终拒绝别人走入他的内心世界。另一方面，自尊严重受挫的小丑从天空监狱找来了霸王龙、迅猛龙、索伦、伏地魔、金刚等史上著名的大坏蛋，他要狠狠地打击自高自大的蝙蝠侠……©豆瓣', '威尔·阿奈特', '克里斯·麦凯', 8, 59744, 'tt4116284', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2417949761.jpg', 0.3, 2.1, 21.3, 49.8, 26.5, '0.069981,-0.109333,-0.360286,0.369133,-0.167351,-0.202228,0.719503,0.143579,-0.120982,0.052234,0.365410,0.336209,-0.064364,-0.131861,0.089800,0.186117,-0.430272,-0.438942,-0.218456,0.267654,0.115362,-0.308125,-0.175573,-0.432498,0.113477,-0.176294,0.425688,-0.110163,-0.371496,0.207134,0.444916,0.466607,0.110301,0.354089,0.048698,0.282939,0.088538,-0.291418,0.083225,0.091014,-0.023409,0.156805,-0.010467,0.424342,-0.272848,0.241720,0.551288,-0.442014,0.057737,-0.329993,0.401727,-0.613583,-0.054429,0.203337,0.050762,-0.309288,0.057154,-0.175393,0.333417,-0.031799,0.250645,-0.241597,-0.544174,-0.048382,-0.227273,0.116109,-0.331135,0.454919,-0.226502,0.363352,0.348321,-0.066673,-0.083721,-0.374475,0.241997,0.210919,-0.035249,0.174956,-0.247750,0.228422,0.412427,0.167507,-0.553986,0.005424,-0.134413,-0.400408,-0.198468,-0.299157,-0.327549,-0.193104,0.609679,-0.132691,-0.279489,0.718104,-0.493087,-0.229123,-0.239335,0.032496,-0.278495,-0.363377,-0.118081,-0.448692,-0.219840,-0.196194,-0.030263,-0.320699,-0.030121,-0.208106,0.400622,-0.597017,0.377692,0.646181,0.065635,-0.059017,0.261668,0.072032,-0.166057,0.067513,-0.292062,0.464418,0.388463,0.222123,0.243973,0.161926,-0.091574,-0.094356,0.045004,0.593323', '3005387', '26630714', '1292528', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26147417', '神奇动物：格林德沃之罪', '奇幻', '虽然纽特（埃迪·雷德梅恩 Eddie Redmayne 饰）协助美国魔法部将邪恶的黑巫师格林德沃（约翰尼·德普 Johnny Depp 饰）捉拿归案，但最终格林德沃还是逃脱了禁锢，他来到了法国巴黎，一是为了集结信徒掀起革命，二是为了寻找同样藏匿在这里的克雷登斯（埃兹拉·米勒 Ezra Miller 饰），寄生在克雷登斯身上的默默然是帮助格林德沃实现野心的不可或缺的道具。格林德沃的潜逃在整个魔法世界里都掀起了轩然大波，一时间草木皆兵。邓布利多（裘德·洛 Jude Law 饰）秘密的找到了纽特，希望他能够前往巴黎，先格林德沃一步找到克雷登斯。和纽特一起踏上巴黎之旅的，是麻鸡雅各布（丹·福格勒 Dan Fogler 饰），他此行的目的，是要找回先前因为吵架而来到巴黎投奔姐姐蒂娜（凯瑟琳·沃特森 Katherine Waterston 饰）的恋人奎妮（艾莉森·苏朵儿 Alison Sudol 饰）。', '埃迪·雷德梅恩', '大卫·叶茨', 7, 463022, 'tt4123430', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2538826177.jpg', 1.2, 8.4, 42.7, 34.8, 12.9, '0.226952,-0.024527,-0.499191,0.445590,0.083038,-0.434015,0.527866,-0.026664,-0.245402,-0.428383,-0.044033,0.672891,0.095438,0.221395,0.405731,0.355386,-0.689373,-0.354579,0.357157,-0.267732,-0.356503,-0.686875,-0.545076,-0.454118,-0.003787,-0.599501,0.465286,0.257849,-0.002128,0.352711,0.566245,0.426334,-0.191245,0.167937,0.137158,-0.035904,0.279501,-0.203166,-0.450521,0.361348,0.175187,-0.042732,-0.174795,0.192046,0.325763,0.158745,0.393262,-0.349855,0.511444,-0.067235,0.066379,-0.409772,0.112775,0.201114,-0.062224,-0.367534,-0.054845,0.152734,-0.119880,-0.076479,0.364989,-0.251511,-0.408381,0.225911,0.245784,0.250667,-0.366751,0.052277,-0.140872,0.218258,0.026041,-0.142610,0.012629,0.500355,0.158425,0.084766,0.198254,0.140971,-0.379749,-0.250378,0.281407,-0.337856,0.029577,0.047865,-0.328213,-0.239639,-0.031602,0.045721,-0.100003,-0.240301,0.382297,0.005289,0.333034,0.206308,-0.713132,-0.327412,-0.509013,-0.077751,-0.017586,-0.266522,0.299194,-0.669783,-0.102283,-0.101897,0.013113,0.022063,0.108926,-0.305002,0.259620,-0.544574,0.311461,0.308585,0.281143,-0.420968,0.267235,-0.236192,0.401319,-0.242706,-0.087711,0.774848,0.214235,0.319765,0.134771,0.273052,0.305072,-0.277957,-0.063334,0.455058', '2010975', '3227410', '6517421', '3075921');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26147418', '神奇动物：邓布利多之谜', '奇幻', '阿不思·邓布利多教授（裘德·洛 饰）意识到强大的黑巫师盖勒特·格林德沃（麦斯·米科尔森 饰）正试图夺取魔法世界的控制权。邓布利多了解仅凭他一人之力，将无法阻止格林德沃，于是他委托魔法动物学家纽特·斯卡曼德（埃迪·雷德梅恩 饰）带领一支精良的团队——成员包括男巫、女巫及一位勇敢的麻瓜面包师，来共同执行这项危险任务。一路上他们会遇到各式各样的神奇动物，既有老朋友，也有前所未见的神秘生物；同时他们也随时会与格林德沃不断壮大的追随者发生冲突。这次行动的风险是如此之高……邓布利多还能袖手旁观多久？', '埃迪·雷德梅恩', '大卫·叶茨', 5.9, 179868, 'tt4123432', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2871106106.jpg', 3.7, 23.1, 52.9, 16.5, 3.8, '0.287142,0.048737,-0.541509,0.532878,-0.128503,-0.090846,0.404785,-0.256797,-0.618637,-0.470690,0.006920,0.821633,0.056051,-0.024308,0.249555,-0.104765,-0.277223,-0.160827,0.181630,-0.026453,-0.506050,-0.943245,-0.578315,-0.976138,0.044290,-0.698498,0.184071,0.228133,-0.117226,0.232377,0.223641,0.519111,-0.013791,0.332273,0.162722,-0.211207,0.433918,-0.327768,-0.039360,0.133952,0.280816,0.266980,-0.088182,0.120284,0.219096,0.007164,0.393540,-0.403946,0.050996,-0.309057,0.295256,-0.168572,0.388948,0.143909,0.292172,-0.377171,-0.100082,0.170264,0.153776,0.015380,-0.026327,-0.143489,-0.652367,0.056529,0.072370,0.330591,-0.379248,-0.014169,-0.218355,0.107728,0.108572,-0.153398,-0.386916,0.561488,0.281944,-0.011281,0.424197,-0.091852,-0.393199,-0.270648,0.430942,-0.223714,-0.352858,-0.118325,-0.567184,-0.553576,-0.487203,-0.156267,-0.357151,-0.135406,0.586888,0.181699,0.431409,0.494452,-0.861836,-0.112768,-0.430280,0.235129,-0.025582,-0.131387,0.207349,-0.768963,0.268718,-0.147014,-0.170753,0.252255,0.135701,-0.292557,0.816619,-0.580673,0.147293,0.466237,0.537918,-0.248783,0.319663,-0.337791,0.392263,-0.157167,-0.235180,0.592827,0.401868,0.187797,0.386542,0.430277,0.516077,-0.202067,0.361781,0.258526', '27006407', '1293433', '3154822', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26147706', '花与爱丽丝杀人事件', '喜剧', '就读国中的女孩有栖川彻子（苍井优 配音），因父母离婚而转学来到了石之森学园。令她有些气闷的是，同学们皆以诡异的目光看她，甚至对她敬而远之。从同班同学睦美口中得知，彻子现在所坐的桌子，其前主人曾经陷入一起被称为“犹大及其四位妻子的杀人事件”。而那张桌子后面还有一张桌子，其主人荒井花（铃木杏 配音）长期旷课，花也恰恰是彻子现在的邻居。为了弄清杀人事件的真相，给自己起名“爱丽丝”的彻子壮着胆子进入花的家，进而得知了关于“犹大”的种种往事。以此为契机，这两个性格有些古怪却灵巧可爱的女孩开始了她们伟大的友谊……©豆瓣', '苍井优', '岩井俊二', 8.1, 49538, 'tt4125300', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2220639306.jpg', 0.4, 2.1, 19.4, 46.9, 31.2, '0.474118,0.031876,-0.430154,0.492647,-0.274502,-0.248551,0.687006,0.053991,-0.388130,-0.489070,0.072558,0.855103,-0.241950,0.671595,0.285975,0.166194,-0.010458,-0.591601,-0.248747,-0.289135,-0.308970,-0.339327,-0.080240,-0.212401,-0.213930,-0.065284,0.642674,-0.110765,-0.220259,0.375531,0.392214,0.234358,-0.064347,0.234470,-0.062672,0.089473,-0.262914,0.069867,0.008287,-0.212219,-0.027845,-0.384911,-0.285136,0.293176,0.047848,0.314425,0.662596,-0.197900,-0.193797,-0.192988,0.562170,-0.279882,-0.104210,0.285688,0.525061,0.061408,0.195296,0.132206,-0.208767,-0.072371,0.212097,-0.003326,-0.606968,0.159312,0.019461,0.071961,-0.336459,0.261287,-0.079913,-0.074140,0.438130,-0.023222,0.139485,0.451266,0.196296,0.332549,-0.178074,0.013418,-0.083811,-0.017240,0.395775,0.069650,0.077558,0.247928,-0.261075,-0.296607,0.099680,-0.136730,-0.173146,0.138369,0.194061,0.066753,-0.038936,0.224717,-0.540823,-0.259849,-0.011990,-0.131960,0.189101,-0.458913,-0.354283,-0.509861,-0.232046,-0.385796,-0.155221,-0.059112,0.158946,-0.316244,0.883299,-0.760895,-0.045654,0.420129,0.082407,-0.406768,0.467066,0.173665,-0.023076,-0.203254,-0.238684,0.171568,0.121820,0.319698,0.029258,0.321242,0.059970,-0.000711,-0.304872,0.319016', '3811356', '27602116', '25922902', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26147991', '明月守护者', '动画', '故事讲述爱闯祸的无名小卒缪恩，有一天阴差阳错得成了重要的月亮守护者，而他任职第一天就造成大错，间接导致太阳被偷、月亮消失、世界大乱。于是，他不得不携手太阳守护者和蜡质姑娘茜尔，展开一场大冒险，揪出混乱背后的黑手，拯救世界。', '奥玛·希', '亚历山大·西伯恩', 8.3, 21239, 'tt3858372', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2228888107.jpg', 0.2, 1.4, 16.9, 47.7, 33.8, '-0.208188,0.330926,-0.512061,0.265198,-0.281796,0.290960,0.350523,0.263321,-0.329852,0.303819,0.493351,0.477069,-0.376870,0.127075,0.575534,0.183659,-0.304064,-0.531736,0.479531,-0.217159,-0.285032,-0.472519,-0.416791,-0.486346,-0.013843,-0.538168,0.580974,0.690176,-0.284371,-0.184338,0.197852,-0.099603,-0.249173,0.296230,0.154203,-0.076126,0.023958,0.278214,-0.308763,0.315234,-0.279657,-0.209531,0.017873,0.381085,-0.395016,0.159279,0.754844,-0.684827,-0.082240,-0.713752,0.726682,-0.831625,-0.348213,-0.079070,0.720973,0.233676,-0.100530,0.281271,0.347506,-0.248998,-0.124720,-0.215054,-0.227096,0.170873,0.250114,-0.200786,0.024530,0.190225,0.263843,-0.165391,0.061538,-0.053373,0.282852,0.079903,0.697432,0.165917,-0.043236,-0.048999,-0.373496,0.187240,0.760802,-0.348828,-0.214829,0.373751,0.139899,0.093144,0.028118,-0.135394,-0.206977,0.323999,0.464822,-0.350619,-0.184967,0.548145,-0.344390,0.101262,-0.338900,-0.356601,0.140802,-0.554064,-0.181603,0.079805,-0.294662,0.400002,0.018163,0.272456,-0.098340,-0.132725,0.514614,-0.569277,0.565805,0.742433,0.179578,-0.370523,0.440349,-0.039184,0.135896,-0.503556,0.355974,0.367248,-0.035079,0.241781,0.080712,-0.391201,-0.114333,0.333349,-0.202638,0.006007', '26696639', '10581450', '26709258', '30201138');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26163480', '青春冒险王', '喜剧', '总被班上同学戏称为女孩的青涩男孩丹尼尔·盖雷，与名字老被人联想成汽油的转学生西奥·勒卢瓦尔，老被排挤的哥俩好为自己的苦闷找到出口，突发奇想计划一场疯狂冒险。随着暑假来临，两个小鬼头一点都不想和家人共度无聊的夏天。一台割草机引擎与几片木板，他们以土法炼钢的创意打造自己专属的动力房车， 踏上横跨广大法国城镇的公路旅行。', '安格·达尔让', '米歇尔·贡德里', 8.1, 7209, 'tt3882000', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2253641357.jpg', 0.3, 1, 18.8, 52.7, 27.3, '0.373981,-0.285761,-0.474497,0.306751,-0.187263,-0.313809,0.622830,-0.001865,-0.380969,0.000609,0.013300,0.749627,-0.454517,0.333281,0.312582,0.145369,-0.248937,-0.502021,0.003968,0.049489,-0.192300,-0.548568,-0.042414,-0.150859,-0.020542,-0.205287,0.519069,0.022621,-0.080873,0.343802,0.137340,-0.068971,-0.055704,0.413584,-0.277360,-0.017370,0.076951,-0.214358,-0.121211,-0.232701,-0.342254,0.021542,0.031456,-0.177479,-0.028105,0.215330,0.752345,0.072731,0.051879,-0.196706,0.214303,-0.222064,-0.061558,-0.068351,0.111126,0.314736,0.294366,0.097899,0.051270,-0.039422,0.224334,-0.334152,-0.430410,0.468870,0.108647,-0.365115,-0.589773,0.444514,-0.035688,-0.104018,0.248633,-0.280980,0.240630,0.111870,0.426843,0.585028,-0.383822,0.225326,-0.192175,0.160695,0.902013,-0.131355,-0.315323,0.278293,-0.023323,0.039383,0.209645,-0.154734,-0.455953,-0.068709,0.209867,-0.144760,-0.093599,0.104271,-0.881722,0.215816,-0.293353,-0.259699,0.142612,-0.282267,-0.246215,-0.495967,0.236812,-0.063988,0.014723,0.306295,0.235721,-0.099489,0.736944,-0.469127,0.051795,0.470676,0.397888,-0.335828,0.587793,-0.016647,0.086451,-0.474879,-0.158522,0.093569,-0.067110,0.376771,0.073606,0.498993,-0.226278,-0.082803,-0.518805,0.421319', '3214137', '30162520', '26290398', '2357162');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26163541', '情敌蜜月', '喜剧', '夏小雨（张雨绮 饰）在一家婚恋网站工作，负责替各路单身男女测试他们的配对指数，以此作为撮合他们的凭证。夏小雨有一位交往多年的男友许默（霍建华 饰），两人拥有着98%的匹配度，不啻为天作之合。然而，就当夏小雨等待着和男友步入婚姻殿堂之时，却传来了许默劈腿同富豪千金叶静斯（施予斐 饰）订婚的消息。周云枫（权相佑 饰）是夏小雨的顶头上司，公司财政吃紧令他十分头痛，叶静斯的父亲是周云枫身边最大的金主，于是他决定向叶静斯下手。周云枫和夏小雨假扮情侣，混近许默和叶静斯的身边，企图从中作梗拆散两人，但随着时间的推移，事态的发展逐渐脱离了四人的掌控。©豆瓣', '张雨绮', '张林子', 4.7, 11344, 'tt4950362', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2263349553.jpg', 22.9, 35.5, 29.8, 6.6, 5.3, '0.095852,-0.056838,-0.540988,0.665986,-0.109342,-0.465943,0.494311,0.680118,-0.413993,-0.287421,-0.047582,0.247164,-0.371719,0.193988,0.486184,-0.065415,0.080601,-0.967003,-0.186392,-0.012487,-0.203401,-0.519338,0.189172,-0.342380,-0.137991,-0.012066,0.647152,0.019323,-0.289835,0.319114,0.512096,0.228132,-0.296649,0.452405,-0.025152,-0.194412,0.142600,0.109996,-0.500356,0.316093,0.059976,-0.033451,-0.076664,-0.073155,0.055773,0.220275,0.476509,-0.196763,-0.148209,-0.034733,0.499884,-0.360694,0.148530,-0.069335,0.523401,0.134487,0.181726,-0.055920,-0.228441,-0.141577,0.244035,-0.183845,-0.548411,0.113075,0.048133,-0.056021,-0.725235,0.247268,-0.006353,-0.129101,0.153651,-0.345106,0.332117,0.823875,0.140703,0.224632,-0.298115,0.015378,-0.463978,0.228475,0.497308,0.434290,0.055135,0.078945,-0.280532,-0.516316,-0.227482,0.194446,-0.620591,-0.254474,0.456737,0.029685,0.093832,0.158299,-0.183680,0.024406,-0.111330,-0.118377,0.144116,-0.621365,0.346831,-0.713354,-0.304388,-0.597506,-0.244746,0.032818,0.128444,-0.539275,0.653827,-0.824990,-0.115713,0.211147,0.444931,-0.473911,0.478306,0.085920,0.123195,-0.219816,-0.057009,-0.070233,-0.104281,0.223422,0.251687,0.116209,-0.006224,0.199888,-0.308895,0.280836', '25777330', '1301022', '30345227', '1986338');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26169607', '潘多拉', '动作', '韩半岛6.1级地震之后，引发了位于釜山地区的1号原子能发电站爆炸，核电站陷入了危机。大规模强震引发的爆炸导致核电站出现裂缝，放射性物质泄漏事故发生。毫无预警的灾难，令韩半岛被混乱恐慌笼罩。就连一直坚信可以预警灾难的塔台也处于即将颠覆的状态。核能泄露的恐怖渐渐席卷而来，甚至还可能诱发第二次爆炸。核电站工作人员与居民、消防人员展开救灾行动，然而下一轮爆炸的威胁已经袭来。', '金南佶', '朴正祐', 7.6, 52647, 'tt6302160', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2404938183.jpg', 0.6, 3.4, 29.7, 45.6, 20.7, '-0.012109,0.133965,-1.097826,0.335827,0.628600,0.636936,0.896727,0.129062,-0.202979,-0.015502,0.475492,0.411994,-0.789339,-0.255143,0.274754,-0.495855,0.001107,-0.638902,-0.404798,0.217957,-0.585351,-0.052326,-0.306281,-0.296414,0.166133,-0.837508,0.463862,0.872256,-1.063812,0.107174,-0.028963,0.633684,-0.419763,1.345445,0.329774,-0.196180,-0.394362,-0.154259,-0.345044,0.296793,-0.100534,-0.551466,0.795398,0.528447,-0.090270,0.497374,0.854089,-0.441593,-0.432747,-0.169770,0.677564,-0.409348,0.000673,0.333983,0.717063,0.070744,-0.305839,-0.274059,-0.257134,0.044179,0.485983,-0.063677,-0.185297,-0.000061,-0.072941,-0.052108,-0.188366,0.148564,0.217082,-0.065183,-0.101522,0.304383,0.589863,0.819843,0.184900,0.225167,-0.739934,0.242771,-0.347674,-0.184165,0.771622,-0.593685,-0.976026,0.040194,-0.148970,-0.537502,-0.472952,-0.282677,-0.097886,0.127783,0.336867,0.141306,-0.019242,0.744772,-0.521388,-0.175030,-0.451341,-0.906597,-0.501009,0.054334,-0.419038,-0.857835,-0.116290,0.287157,-0.147685,0.499691,-0.184967,0.246462,0.012349,-0.365930,0.634914,0.608425,0.289276,-0.086315,-0.018562,-0.293155,-0.098002,-0.272992,0.087886,0.208875,-0.249474,0.802503,0.033427,0.040114,-0.105987,-0.084132,0.188366,0.173422', '1308779', '3011051', '30221757', '33454993');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26177735', '皮绳上的魂', '剧情', '《皮绳上的魂》改编自中国魔幻现实主义代表作家扎西达娃的两部短篇小说：《西藏，系在皮绳结上的魂》和《去拉萨的路上》，影片讲述一个背负原罪与世仇，死而复生的猎人经活佛点拨，一路降服心魔，最终将圣物天珠护送进入莲花生大师掌纹地的故事。', '金巴', '张杨', 7.2, 6728, 'tt5974624', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2494811175.jpg', 1.5, 5.6, 36.1, 45.1, 11.7, '0.361293,-0.103297,-0.268361,0.791290,0.295904,-0.293697,0.343992,-0.057063,-0.221837,-0.066028,0.062231,0.889288,-0.076693,-0.198486,0.283344,0.111812,-0.279523,-0.606045,0.084471,0.053965,-0.128289,-0.205701,-0.272196,0.502802,-0.149138,-0.543199,0.725359,0.417938,-0.279437,0.412853,0.179979,0.475089,-0.527227,-0.448837,-0.271678,0.069274,-0.267641,0.022669,-0.065535,0.413121,-0.150778,0.012351,0.257114,0.068301,-0.394475,0.154903,0.496460,-0.748783,0.424888,0.053639,0.391776,-0.378829,-0.143671,-0.225809,0.114780,0.658051,0.252333,0.710067,-0.127572,-0.000552,-0.090937,-0.394394,-0.712880,-0.314739,0.352853,0.328765,-0.686384,0.304688,0.038968,0.304785,-0.133783,-0.524935,0.255242,0.151792,0.331628,0.367207,0.006779,-0.208081,-0.303693,0.214682,0.150529,-0.304877,0.160346,0.059769,-0.044053,-0.584403,-0.324355,-0.007175,-0.217380,0.109858,0.495631,0.064736,-0.115064,0.149428,-0.779307,-0.324564,-0.393086,0.216371,0.247082,-0.291196,0.075474,-0.529162,0.064586,-0.310378,0.200476,-0.394652,0.656086,-0.123388,0.757407,-0.007409,0.470854,0.483090,-0.025031,-0.115865,0.854012,-0.159373,0.232954,-0.308065,0.038728,0.488730,0.346172,0.687150,0.122786,0.308030,-0.184884,0.240172,-0.506923,0.269618', '1302661', '22265121', '26290398', '25837262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26182910', '功夫瑜伽', '喜剧', '考古学教授Jack（成龙 饰）多年没有踏出学校，校长和学生都对他添油加醋的历史半信半疑。一次授课后，一个印度女孩找到Jack，用一张千年地图吸引了Jack的目光。于是Jack和挚友的儿子李琼斯（李治廷 饰）、助教小光（张艺兴 饰）组成“寻宝小分队”，为“神秘宝石”展开冒险，在迪拜和土豪飙车，在冰岛潜入神秘冰穴，在印度大战土狼，和印度贵族斗舞，动作喜剧再升级，打笑全世界。', '成龙', '唐季礼', 5, 177508, 'tt4217392', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2412371389.jpg', 18, 33.1, 35.3, 9.9, 3.6, '0.147615,-0.206512,-0.486496,0.758735,-0.058651,-0.304945,0.652215,-0.220872,-0.284942,-0.130815,0.216920,0.738164,-0.462120,0.103387,0.194218,-0.082996,-0.302903,-0.681071,-0.117088,-0.125197,-0.219308,-0.501172,-0.432017,-0.274089,0.096652,-0.503567,0.526353,-0.029757,-0.433398,0.615867,0.187794,-0.047854,-0.200727,0.054652,-0.226881,-0.071566,0.430445,0.327247,-0.263274,0.317319,-0.047426,-0.143119,-0.356538,0.025525,0.203477,-0.070005,0.783966,-0.273482,0.097385,0.055504,0.108561,-0.335199,-0.366328,-0.045301,0.430002,0.039780,0.143195,0.125693,0.197224,-0.060630,0.005461,-0.073461,-0.232216,0.148077,-0.121586,0.387552,-0.557345,0.538324,-0.115597,0.085513,0.158426,-0.584333,0.162493,0.116915,0.392199,0.266369,0.172103,0.167735,-0.164743,0.456044,0.420535,0.172592,0.023955,-0.151372,-0.119405,-0.529222,0.190134,-0.067533,-0.191679,0.051558,0.362476,-0.401248,0.182227,0.182675,-0.915781,-0.025402,-0.045644,-0.273319,0.201297,-0.284725,-0.115048,-0.902268,-0.028962,-0.365692,-0.048686,0.179936,0.020927,-0.141434,0.831899,-0.680411,0.208182,0.294950,0.300412,-0.467309,0.837891,-0.105488,-0.123727,-0.493466,0.009169,-0.017977,0.187513,0.670538,0.096316,0.456969,0.064544,-0.156333,-0.324589,0.159762', '26365262', '3811356', '26290398', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26184109', '试验', '剧情', '搞怪的父亲和他温柔美丽的女儿一起生活在广阔的哈萨克斯坦大草原上，日子悠闲而又平静。然而两个年轻男人的到来却打破了这一切，因为他们同时爱上了这位温柔的姑娘。影片将不极致的美丽和强烈的社会意义相结合，讲述了一段错综复杂的情感故事。电影《测试》通过对画面的完美设计表现了影片独特的视觉效果。令人意想不到的是，全片无对白，导演亚历山大·科特(Alexander Kott)以无声来处理影片错乱的结构，以沉默来突出影片暗含的讽刺意义。而正是因为全片无对白观众才会更加关注画面所传达的意义，更会注重镜头的美感。而影片最后的结局完全推翻了观众之前的猜测和想像，让人为之一震。值得一提的是，影片是根据1949年哈萨克斯坦大草原发生的真实事件改编而成，导演亚历山大·科特以其独特的电影手法展现了痴痴等待的宿命。亚历山大·科特曾凭处女作在俄罗斯广受好评，此次他全力制作的《测试》展示了其不可多得的才华和对电影的敏感。', '安慧媛', '亚历山大·科特', 8.2, 6829, 'tt4131188', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2208893760.jpg', 0.6, 2.3, 18, 45.3, 33.8, '0.019100,0.053472,-0.680746,1.050358,0.074687,0.095619,0.932835,0.056625,-0.552526,-0.036178,0.300068,0.647176,-0.481102,-0.090087,0.270616,0.003661,-0.227019,-0.781705,-0.231562,0.115992,-0.013730,-0.516789,-0.298026,-0.384558,0.039088,-0.516921,0.666130,0.094062,-0.589916,0.341163,0.230204,0.133470,-0.017419,0.272497,0.004058,-0.157466,-0.100868,0.101022,-0.362636,0.035560,0.172177,-0.405336,-0.295114,0.355943,-0.354901,0.388156,0.691062,-0.326399,-0.544286,0.200922,0.829857,-0.294434,0.012825,0.075312,0.017420,0.126553,0.247014,0.240243,-0.115113,-0.110846,-0.136939,-0.225361,-1.132831,0.026594,0.224337,0.107953,-0.300364,0.737197,-0.065320,-0.337200,0.210912,-0.157319,0.204123,0.107557,0.661917,0.417470,0.069864,-0.043604,-0.070840,0.376080,0.462605,0.145841,-0.544013,0.705503,-0.540116,-0.484891,-0.279380,-0.545858,-0.348530,0.357775,0.263682,0.150187,-0.051294,0.225258,-0.536184,-0.060542,-0.070495,-0.482994,-0.065661,-0.593588,-0.061660,-0.786797,-0.511516,-0.730791,-0.250703,-0.225091,0.083625,-0.362782,1.119956,-0.831400,0.022578,0.512686,0.061791,-0.546931,0.703565,0.093342,-0.286675,-0.205856,-0.111418,0.144905,-0.179841,0.037098,0.085950,0.523421,0.024882,-0.105793,-0.569557,0.731200', '27602116', '1303542', '27666513', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26200627', '爱我就陪我看电影', '喜剧', '姚星杰（吴镇宇 饰）想要挽回旧爱若瑶（余男 饰）的心，为此不惜使出三十六计笑料百出。佳梦（娜扎 饰）是林君（金泛 饰）的超级粉丝，没想到，有一天竟然能够跟自己梦中的偶像走到一起。邱季唐（任达华 饰）和妻子婉华（惠英红 饰）结婚多年，彼此之间感情早已由浓转淡，人生中又出现了新的诱惑，此时邱季唐能否坚守自己的底线？丝雨（张雪迎 饰）性格热情而又奔放，她和邱水（王宗泽 饰）之间的爱情最终会走向何处？牛爷爷（牛犇 饰）在暮年遇见了鲁奶奶（鲁园 饰），活了一辈子的他终于在夕阳红中找到真爱。五对恋人，五段感情，人生的酸甜苦辣尽在荧屏之中。©豆瓣', '吴镇宇', '牛朝阳', 3.6, 3594, 'tt4838364', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2233113686.jpg', 53.1, 25.7, 14, 3.1, 4, '-0.238454,0.121700,-0.598036,0.601277,0.023763,-0.474985,0.479928,0.055241,-0.393595,-0.091784,-0.026695,0.578747,-0.303074,0.446540,0.250284,-0.155345,-0.028679,-0.818077,-0.037097,0.030765,-0.357838,-0.341170,-0.303492,-0.041870,-0.225882,-0.014341,0.534099,0.280703,0.004831,0.323335,0.603523,0.233875,-0.142730,0.319119,-0.018345,0.115918,0.038844,0.306415,-0.378370,-0.004253,0.154397,-0.149513,-0.057519,0.072246,0.011887,0.143373,0.665996,-0.291186,-0.017543,0.113089,0.398555,-0.006012,0.039486,0.113140,0.080340,-0.162628,0.258560,0.040442,-0.301084,0.119345,0.275830,-0.073594,-0.533462,-0.078914,0.130005,-0.054962,-0.579569,0.330406,-0.046081,-0.155187,0.237508,-0.146329,0.177664,0.098235,0.516113,0.209593,-0.241064,-0.147901,-0.336235,0.356971,0.626654,0.119553,-0.038243,0.401686,-0.141348,-0.293103,-0.332146,-0.259030,-0.403808,-0.121008,0.177991,0.190463,0.035402,0.125203,-0.412791,-0.102896,-0.006376,0.415769,0.241679,-0.409239,-0.106400,-0.050115,-0.210017,-0.828019,-0.220606,0.273104,0.040378,-0.430121,0.672251,-0.747346,0.169122,0.125329,0.089311,-0.546300,0.754484,0.201887,-0.150103,-0.185544,0.073662,0.390689,-0.329576,-0.052995,0.222140,0.207810,-0.240670,0.073230,-0.244656,0.350071', '26354526', '25777330', '30389258', '26730542');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26213252', '惊奇队长', '动作', '在围剿斯克鲁人的战斗中，克里人星际战队成员弗斯（布丽·拉尔森 Brie Larson 饰）不幸成为对方的俘虏。斯克鲁人尝试探究弗斯的记忆，最终发现连弗斯本人都不知道的一段往事，进而也得知名为温迪•劳森博士的女子掌握着他们急于得到的时空引擎。趁对方不备，拥有强大超能力的弗斯摆脱束缚，逃到了代号为C-53的地球，而这里也正是她那段失落的记忆的发生地。未过多久，神盾局探员弗瑞特工（塞缪尔·杰克逊 Samuel L. Jackson 饰）找上门来，而紧随其后的斯克鲁人更是引发了地球人前所未见的大骚动。在这一过程中，弗瑞特工意识到事态的严重性，并且帮助弗斯认清本来的自己。倔强的弗斯，终于找到了真正需要保护的东西……©豆瓣', '布丽·拉尔森', '安娜·波顿', 6.8, 482181, 'tt4154664', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2546360443.jpg', 1.4, 8.4, 49.4, 31.7, 9.1, '0.431715,0.257251,-0.709561,0.567166,-0.005107,-0.359192,0.340834,-0.132791,-0.697021,-0.519766,0.466211,0.478942,-0.104547,-0.143623,0.346970,0.133510,-0.353564,-0.487009,-0.062518,-0.244083,-0.485560,-0.548131,-0.517449,-0.316125,0.062146,-0.756511,0.787252,0.219330,-0.130610,0.179650,-0.065685,0.591381,0.221909,0.366102,0.221406,0.189592,0.175416,-0.227766,-0.137073,-0.001189,0.028834,-0.070486,-0.350665,0.107588,-0.023381,0.351707,0.548853,-0.298512,0.025917,0.113686,0.309820,-0.323138,0.028070,-0.286601,0.524195,-0.252680,-0.241368,0.049239,-0.044495,0.094058,-0.040213,0.113032,-0.861373,0.048988,-0.109959,0.220164,-0.281422,0.047662,-0.249781,0.058744,0.142493,-0.226024,-0.003958,0.474009,0.404293,0.158440,-0.205232,-0.184194,-0.631351,-0.083050,0.449754,-0.243650,-0.526474,0.287840,-0.393398,-0.467594,-0.556165,-0.345412,-0.469984,-0.111874,0.363560,0.362364,-0.352994,0.528761,-0.379574,-0.146063,-0.463170,-0.197072,0.034696,-0.560256,-0.056649,-0.666799,-0.326021,-0.008207,-0.223894,0.050987,-0.009545,-0.115415,0.590732,-0.776679,0.183023,0.828358,-0.043973,-0.164508,0.393216,-0.156210,0.128502,-0.284857,-0.122325,0.545619,0.446119,0.305086,0.105969,0.247883,0.009309,-0.115397,-0.473937,0.227474', '1793491', '1294893', '3861846', '10440076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26215216', '将来的事', '剧情', '娜塔莉（伊莎贝尔·于佩尔 Isabelle Huppert 饰）是一名哲学教师，和丈夫汉斯（安德烈·马孔 André Marcon 饰）结婚数十年，两人共同养育了两个孩子，日子过得平静而美满。某日，汉斯忽然和娜塔莉坦白，自己在外面有了情人，不仅如此，他还打算从家里搬出去和情人同居，虽然娜塔莉表面故作镇定，但内心却遭受了强烈的打击。娜塔莉的母亲（爱迪丝·斯考博 Edith Scob 饰）曾是一名当红模特，如今却饱受抑郁症的困扰，三番五次自杀未遂，无奈之下，娜塔莉只得违背了母亲的意愿，将她送进了养老院。与此同时，娜塔莉听从她曾经的学生法比安（罗曼·科兰卡 Roman Kolinka 饰）的建议前往法比安与他朋友们在山上所建立的公社。©豆瓣', '伊莎贝尔·于佩尔', '米娅·汉森-洛夫', 8.2, 52972, 'tt4120176', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2319532864.jpg', 0.2, 1, 15.6, 52.9, 30.2, '0.223787,-0.066747,-0.595373,0.576841,-0.288632,-0.316725,0.753857,0.224469,-0.522297,-0.418507,-0.008197,0.775989,-0.151344,0.567867,0.144766,0.130822,-0.235934,-0.551732,0.133564,-0.120722,-0.016454,-0.486268,-0.172091,-0.175105,-0.326810,-0.427503,0.600053,-0.246945,0.050632,0.512888,0.291062,0.405391,-0.085219,0.422905,-0.313854,0.208244,0.106531,0.047562,-0.276447,0.042149,0.360767,-0.143497,-0.209743,0.135952,0.372302,0.421610,0.399800,-0.119764,-0.034078,0.160924,0.249689,-0.128273,0.079441,0.479808,0.417489,-0.157389,0.081554,0.436399,-0.201435,-0.158249,0.172615,-0.199700,-0.401077,-0.005181,-0.000596,-0.021728,-0.788883,0.474701,-0.257496,-0.065647,0.210124,-0.260201,-0.006197,0.331791,0.005350,0.599878,-0.272743,0.005870,-0.178464,0.220933,0.638074,0.088260,-0.131658,0.248018,-0.526311,-0.377330,0.068503,-0.097447,-0.646173,0.000107,0.195414,0.047908,-0.137648,0.277172,-0.458619,-0.107812,-0.409674,0.028858,0.078319,-0.513899,0.128272,-0.537426,-0.092007,-0.345133,-0.464163,-0.059639,-0.095247,-0.091863,0.646212,-0.754558,0.368780,0.418148,0.459396,-0.517521,0.626239,0.277158,0.347475,-0.083068,0.120808,0.377505,0.006617,0.088460,0.227860,0.387777,0.018792,-0.064149,-0.139246,0.343163', '1292720', '3111650', '1302384', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26219652', '少年班', '剧情', '1998年，来自西安交大的“少年班”导师周知庸（孙红雷 饰），前往全国各处寻找智商超群的天才少年，最终被选出的22个少年将被赋予艰巨的使命。少年吴未（董子健 饰）就是其中的一员，在这个特殊的班级里，他先后认识了有暴力倾向的麦克（王栎鑫 饰）、小天才方厚正（李佳奇 饰）、“神棍”王大法（柳希龙 饰），以及聪明却冷若冰霜的周兰（周冬雨 饰），五位天才少年从此开始了早于同龄人的大学生活，同时还面对着青春期的各种“疑难杂症”。女神江依琳（夏天 饰）的出现扰乱了男生们的心，攻克“世界数学大赛”的压力也从天而降，而导师周知庸也面对着人生中的最大难题，“少年班”该何去何从？天才少年人生的征途才刚刚开始……©豆瓣', '孙红雷', '肖洋', 6, 101090, 'tt4727756', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2247339285.jpg', 5.9, 20, 48.1, 19.3, 6.6, '0.107235,0.064852,-0.435586,0.688574,-0.242425,-0.066251,0.293881,0.032034,-0.428688,-0.418383,0.229345,0.612641,-0.172017,0.481770,0.434236,-0.193151,0.131589,-0.784702,-0.144645,-0.260963,-0.503212,-0.306534,-0.214717,0.076297,-0.116872,-0.323126,0.740628,0.171284,-0.135506,0.437938,0.487294,0.192244,0.032731,0.298076,-0.167520,-0.172345,0.136363,0.106684,-0.003908,-0.070653,-0.014690,-0.130679,-0.274915,-0.011054,-0.083869,0.064939,0.780067,-0.318884,0.097951,-0.193814,0.559956,-0.338342,-0.233714,0.047694,0.492575,0.080058,-0.003536,0.190410,0.165984,0.294412,0.199055,-0.269843,-0.723622,-0.105670,0.322775,0.145010,-0.501602,0.550373,0.126220,-0.179089,0.086124,-0.083083,-0.063229,0.155459,0.329941,0.527834,-0.027248,0.130026,-0.120168,0.396887,0.347742,0.120862,-0.452445,-0.010402,-0.183002,-0.646925,-0.006310,-0.352180,-0.540530,0.093275,0.187609,0.055531,-0.016550,0.242089,-0.489260,0.218138,-0.064074,-0.101399,0.081944,-0.242510,-0.341603,-0.454790,-0.008524,-0.329129,-0.229398,0.268803,0.201946,-0.248881,1.163474,-0.991285,-0.118109,0.271070,0.158264,-0.340898,0.581497,-0.025691,0.131791,-0.376609,-0.320942,0.234780,-0.204836,0.372390,-0.179313,0.515026,-0.271933,-0.383791,-0.292403,0.511016', '27602116', '25922902', '24284209', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26219713', '克隆人', '科幻', '供职于某生物科技公司的生物化学科学家威廉·福斯特（基努·里维斯 Keanu Reeves 饰），长久以来一直致力于克隆技术的研究。虽然科研的道路上困难重重，但他距离最终的成功似乎只有一步之遥。谁知就在关键时刻，一场车祸摧毁了他的幸福人生。车祸中，妻子莫娜（爱丽丝·伊芙 Alice Eve 饰）和三个可爱的孩子命归黄泉，这令威廉痛不欲生。然而，科学家的本能又促使他迅速冷静下来。他找到工作中的伙伴埃德·惠特尔（托马斯·米德蒂奇 Thomas Middleditch 饰）帮忙，决定利用自己的研究“复活”家人。爱让人疯狂，让人不惜一切代价与全世界对抗……©豆瓣', '基努·里维斯', '杰弗利·纳赫马诺夫', 6, 16417, 'tt4154916', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2539946987.jpg', 2.4, 22.3, 52.8, 19, 3.5, '-0.123266,0.023474,-0.685561,0.579579,-0.145931,-0.445116,0.567296,-0.080434,-0.451977,-0.108055,0.232670,0.793160,0.125965,0.069716,0.327397,0.159470,-0.381894,-0.712501,0.188695,0.086780,-0.294416,-0.559514,-0.394938,-0.570535,-0.123065,-0.382264,0.822482,0.176205,0.075029,0.335200,0.033753,0.376801,-0.211289,0.497373,0.185950,0.059827,0.346195,-0.229501,-0.439568,0.100219,0.121027,-0.126687,-0.094409,0.447726,-0.104175,0.369607,0.370900,-0.408401,-0.032966,-0.224069,0.150086,-0.508113,-0.069114,0.113666,-0.057006,-0.018005,0.166173,0.114945,-0.313172,-0.207618,0.130575,-0.011359,-0.860129,-0.121109,0.154190,-0.016838,-0.578803,0.335845,-0.140715,0.146727,0.296107,-0.197299,-0.080309,0.325271,0.449204,0.410219,-0.377143,0.071874,-0.322378,0.094886,0.655402,-0.226464,-0.306891,0.411683,-0.228904,-0.308659,-0.101744,-0.303995,-0.411050,-0.020951,0.160285,0.054043,-0.127711,0.321016,-0.472675,0.019080,-0.663910,-0.041625,-0.217858,-0.341846,0.109333,-0.432329,0.040202,-0.089534,-0.321690,-0.044715,0.005059,-0.565527,0.661642,-0.684630,0.173741,0.651957,0.277908,-0.390661,0.615134,0.046479,0.177562,-0.515090,-0.130152,0.476049,-0.080027,0.190214,0.132642,0.285338,0.215105,0.152313,-0.409074,0.561256', '1303034', '30163500', '25928048', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26219893', '快手枪手快枪手', '喜剧', '市井骗子小庄（林更新 饰）机智却爱耍小聪明，以一双“快手”行走江湖，赌局中被“枪手”李若云（张静初 饰）威胁，踏上找回传国玉玺的寻宝之路。途中二人默契配合，与老顽童石佛（腾格尔 饰）、金三娘（刘晓庆 饰）夫妻二人组成“夺宝者联盟”，与觊觎国宝的宋静之（锦荣 饰）等斗智斗勇，夺宝途中一段段故事让人啼笑皆非……', '林更新', '潘安子', 5.3, 28948, 'tt5882704', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2361644304.jpg', 13.7, 29.8, 39.4, 11.5, 5.6, '0.092858,0.091980,-0.316212,0.695201,0.344897,-0.027847,0.384297,-0.047761,-0.550783,0.049820,0.179615,0.247203,-0.334419,-0.286268,0.353641,-0.353034,-0.164856,-0.780688,0.193270,-0.119551,0.114945,-0.023243,-0.185009,-0.081520,-0.543099,-0.138293,0.228283,0.153693,-0.328772,0.864683,0.310399,0.151917,-0.842463,0.120036,0.016492,-0.266780,0.121996,0.228293,-0.444325,-0.234352,-0.269068,-0.151292,-0.207787,0.020181,-0.270196,0.305423,0.801489,-0.267968,0.102159,-0.346052,0.006090,-0.294032,-0.059222,-0.126606,0.078826,0.093863,0.477553,0.211848,0.327465,0.088012,0.064707,0.020545,-0.275730,0.011255,0.362328,-0.036220,-0.247157,0.124491,-0.119839,-0.027131,-0.102556,-0.058781,0.152926,0.131490,0.817637,-0.060249,0.253858,-0.288424,-0.341453,0.146409,0.161980,-0.031838,0.135747,0.106213,0.334061,-0.451167,0.312408,-0.170631,-0.138769,-0.187722,0.599209,-0.562101,0.272311,0.152016,-0.782682,0.066283,-0.134269,0.603155,-0.077794,-0.586833,0.117105,-0.526335,0.085025,-0.489686,-0.067253,0.472979,0.378198,-0.088208,0.422055,-0.332327,0.015745,0.278071,-0.007769,-0.662985,0.445109,-0.141382,0.089332,-0.484951,-0.003187,-0.094537,-0.003443,0.047640,-0.090052,0.203656,-0.201520,-0.103812,-0.359046,-0.030829', '1292506', '34966198', '21941770', '1432699');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26220650', '雄狮', '剧情', '萨罗（戴夫·帕特尔 Dev Patel 饰）和妹妹、哥哥以及母亲过着相依为命的生活，虽然贫穷艰辛，但一家人在一起相互扶持，日子过得依然温暖而又充满了欢乐。一次偶然中，萨罗同哥哥在火车站走散了，误打误撞之中，萨罗登上了一列开往加尔各答的火车，在那里，萨罗成为了露宿街头的流浪儿，并最终被送进了收容所。幸运的萨罗被来自澳大利亚的约翰（大卫·文翰 David Wenham 饰）和苏（妮可·基德曼 Nicole Kidman 饰）夫妇两收养了，在两人爱的教养下，萨罗成长为了前途无量的有为青年。在学校里，萨罗邂逅了名为露西（鲁妮·玛拉 Rooney Mara 饰）的女生，两人很快走到了一起。某次派对中，来自家乡的食物勾起了萨罗对过去的回忆，他萌生出了回到家乡寻找家人的念头。©豆瓣', '戴夫·帕特尔', '加斯·戴维斯', 7.4, 64268, 'tt3741834', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2333848819.jpg', 0.3, 3.7, 37.7, 44.1, 14.2, '0.485185,-0.099821,-0.712823,0.497169,-0.086171,-0.761133,0.911662,0.184819,-0.665696,0.096090,0.064208,0.867844,-0.049718,0.486742,0.569313,0.205295,-0.440567,-0.581522,0.161633,-0.404581,-0.264211,-0.535641,-0.158492,-0.058518,-0.165101,-0.240262,0.335457,0.176427,0.308345,0.760810,0.154288,0.148887,-0.425684,0.381569,-0.320593,0.269403,0.196008,0.141935,-0.451614,0.466343,0.094609,-0.071378,-0.096973,-0.154584,0.138057,0.062643,0.591098,-0.242177,0.167287,-0.167681,0.073256,0.025533,-0.013472,0.098055,0.239358,0.187287,0.306573,0.105087,-0.262598,0.210048,0.099186,-0.142272,-0.357850,0.082346,0.070152,-0.086424,-0.887321,0.784379,0.135453,-0.260610,0.255152,-0.460612,0.413767,0.371096,0.180415,0.561800,-0.220425,0.192005,-0.417243,-0.057059,0.664283,-0.138412,0.015694,0.164661,-0.329629,-0.251524,0.110683,-0.152028,-0.599784,-0.066900,0.442619,0.048694,-0.203704,0.406149,-0.729070,0.131533,-0.116684,-0.111133,0.045648,-0.271222,-0.065333,-0.597717,-0.059756,-0.458161,-0.185609,0.078663,-0.031013,-0.203713,0.719698,-0.969800,0.391717,0.445113,0.416881,-0.237382,0.552297,0.176170,0.277089,-0.053134,0.037575,0.388613,0.062005,0.384615,0.288355,0.341622,-0.305742,0.050137,-0.547371,0.487712', '3111650', '1292219', '1876765', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26220717', '危机13小时', '剧情', '迈克尔·贝导的这部新片根据米切尔·朱可夫（Mitchell Zuckoff）同名小说改编，是一部政治题材的电影。2012年9月11日，在利比亚班加西的美国领事馆前发生一起反美示威事件，入夜后数十名武装分子冲进领事馆，示威演变为暴力冲突，最终导致包括美国大使约翰·克里斯托弗·史蒂文斯（Christopher J. Stevens）在内的四人死亡，这也是33年以来第一个被恐怖分子杀害的美国大使，影片《危机13小时》就是由这一真实事件取材。', '詹姆斯·戴尔', '迈克尔·贝', 7.8, 71841, 'tt4172430', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2280567620.jpg', 0.5, 2.2, 23.6, 51.6, 22, '0.251077,-0.316095,-0.558053,0.465268,0.568052,0.048108,0.409372,-0.393295,-0.597888,-0.384088,0.211518,0.689951,-0.456221,-0.220765,0.540122,-0.191726,-0.544860,-0.821076,-0.593856,-0.236452,-0.238809,-0.484004,-0.249886,-0.423751,0.028252,-0.339753,0.560262,0.270639,-0.256688,0.502244,0.512239,0.503261,-0.114262,0.114441,0.596012,0.219488,0.300744,-0.352027,-0.648263,0.391554,0.036674,-0.391242,-0.093343,0.034528,-0.011598,0.327510,0.513784,-0.237504,0.072725,-0.448130,0.771261,-0.413309,-0.492374,-0.046666,0.698194,0.199234,0.258108,0.548234,-0.036275,-0.065138,-0.082374,-0.238686,-0.601725,0.147876,-0.112091,0.100731,-0.195503,0.295974,-0.243509,0.326706,0.067754,0.042852,0.096710,0.709616,0.460085,0.354045,0.053460,0.060281,-0.288232,0.422123,0.827863,-0.218580,-0.350640,0.095917,-0.235693,-0.314774,-0.161863,-0.439757,0.011454,0.253566,0.123503,-0.387529,-0.099155,0.320793,-0.455533,0.025555,-0.112904,-0.448093,0.200711,0.036828,-0.115566,-1.072610,-0.314433,-0.348710,0.122923,-0.260010,0.100460,0.096074,0.623627,-0.346458,0.227349,0.714052,0.315863,-0.483517,0.738194,0.290474,-0.193213,-0.039752,0.078563,0.314174,0.043364,0.280197,-0.160888,0.143319,0.431468,-0.537893,-0.029484,0.060109', '24751811', '26718836', '3003137', '1309028');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26220722', '惊天破', '剧情', '在一次离奇的案件行动中，警察马进（谢霆锋 饰）击毙连环杀手“将军”（高伟光 饰），却被对方射穿心脏，命悬一线，意外之下接受了心脏移植手术。时隔一年半，国际上惊现数宗与“将军”作案手法完全一致的惊天大案，康复后的马进主动请缨，与犯罪心理学教授车家伟（刘青云 饰）联手展开调查。随着案情深入，马进发现了车教授身上藏有鲜为人知的秘密，车教授对“换心”后的马进也产生了特别的兴趣。在二人互相试探、智斗暗涌的过程中，马进妻子莫秀（范晓萱 饰）与神秘女子陈相茹（佟丽娅 饰）也逐渐卷入事件，一场危及全港百万人生命的大战悄然引爆……©豆瓣', '谢霆锋', '吴品儒', 3.9, 25677, 'tt5618870', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2390833166.jpg', 35.1, 40.2, 21.5, 2.4, 0.8, '0.114003,-0.043365,-0.510067,0.315777,0.374251,0.124437,0.651318,-0.086741,-0.602547,-0.239664,0.529444,0.291470,-0.588361,-0.384236,0.384675,-0.298989,-0.190706,-0.881757,0.010821,-0.044152,-0.357965,-0.484550,-0.357725,-0.112820,0.083964,-0.346967,0.488092,0.248397,-0.322776,0.801447,0.113885,0.350969,-0.336014,0.426021,0.128433,0.076164,0.178056,0.033446,-0.451510,0.251890,0.078882,-0.449742,0.023669,-0.138668,-0.257082,0.395753,0.754349,-0.245511,-0.289343,-0.131985,0.209584,-0.165435,-0.190685,0.103661,0.431254,0.417445,0.317141,0.415094,-0.232668,-0.013099,0.159866,0.189311,-0.358168,-0.029877,0.154330,0.200160,-0.406683,0.182731,-0.191844,0.052262,-0.146132,-0.215349,0.124080,0.207384,0.479685,0.022645,-0.146304,-0.149680,-0.220939,0.064088,0.474296,-0.139877,-0.089442,0.146625,0.103728,-0.622893,-0.188037,-0.008940,0.000014,0.134889,0.343361,-0.018354,-0.037728,0.443379,-0.393388,-0.094553,-0.471596,0.077269,-0.154775,-0.080246,0.061667,-0.621523,-0.283852,-0.067656,-0.253490,0.021900,0.097827,-0.182980,0.253731,-0.599234,0.269637,0.214303,0.183953,-0.184342,0.286718,0.004532,0.178937,-0.419484,-0.219038,-0.066405,0.124006,0.366609,0.154566,0.338158,-0.133756,-0.191570,-0.276822,-0.043549', '1432699', '25723905', '1307186', '1773217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26220725', '魔宫魅影', '剧情', '故事发生在三十年代的上海，顾维邦（杨佑宁 饰）是一位名不见经传的小导演，一次偶然中，他遇见了名为梦思凡（林心如 饰）的女明星，两人一拍即合，决定拍摄一部爱情惊悚电影，顾维邦为其取名为《夜半歌声》。一切都进行的很顺利，演员们纷纷入驻剧组，只等待开拍。顾维邦将拍摄地点选在了丽宫电影院，虽然很多人告诫他这里曾经发生过耸人听闻的灵异事件，不宜久留，但固执的顾维邦毫不在意。果不其然，没过多久，剧组里就接连发生了许多怪事，直到扮演男主角的演员离奇死亡，众人才发现事情已经如此严重。顾维邦的未婚妻麦丽斯（黄幻 饰）来到剧组想要调查事件的真相，却牵扯出了一段顾维邦和梦思凡之间的尘封旧事。©豆瓣', '林心如', '叶伟民', 4.7, 12302, 'tt5639650', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2331558412.jpg', 19.8, 38.5, 31.8, 6.5, 3.4, '0.272954,-0.061448,-0.603081,0.117224,0.391145,0.081541,0.823695,-0.111269,-0.566137,-0.504433,0.347205,0.651355,-0.787332,0.074161,0.353318,-0.184950,-0.338197,-0.718845,0.090794,-0.266411,-0.108332,-0.153171,-0.273452,0.023385,-0.199514,-0.031562,0.549962,0.255246,-0.208224,0.235135,0.323304,0.167545,-0.335228,0.499791,0.108357,0.126489,0.292765,0.305426,-0.310906,0.076794,-0.170666,-0.285780,-0.374749,0.087860,0.035997,0.310054,0.545973,-0.213999,-0.596383,0.190708,0.485744,-0.333138,-0.180103,-0.031060,0.340026,0.311824,0.491778,0.451451,-0.313065,-0.054826,-0.284175,-0.060648,-0.590162,0.194776,0.174512,0.425441,-0.290665,0.144229,0.066608,0.111274,0.164624,-0.282436,0.200594,0.265332,0.622720,0.128859,-0.003853,-0.093621,-0.231204,0.535915,0.819376,0.034287,-0.204582,0.814165,0.160145,-0.423481,-0.164872,0.083683,-0.415272,0.605979,-0.028799,-0.081527,-0.277910,0.511593,-0.315092,-0.174391,-0.307426,-0.223495,-0.038781,-0.120330,-0.151193,-0.817456,-0.265846,-0.120326,-0.225397,-0.137584,-0.031213,-0.051896,0.534857,-0.600685,0.223331,0.447632,-0.058663,-0.362090,0.431283,0.115151,0.101392,-0.137575,0.230143,0.102273,-0.239126,0.076831,-0.089762,0.278339,-0.014772,-0.550595,-0.428734,0.179219', '10466639', '1788094', '5503303', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26220731', '熊出没之雪岭熊风', '喜剧', '终年被白雪覆盖的白熊山，可爱调皮的熊大和熊二出生在这里。伐木工整齐有力的号子响彻森林，当卡车满载原木离去的时候，熊大和熊二则与他们宿命中的敌人——少年光头强相遇。三个小家伙互相追逐的时候，熊二不小心掉入树洞，随后来到一个五彩斑斓的神秘世界。在碧蓝剔透的湖中央，熊二见到了妈妈故事中的大白熊。转眼时间来到了现代，对白熊念念不忘的熊二弄丢了朋友们过冬的口粮，为此遭到哥哥的痛骂。而就在此时，光头强带着三个行踪诡异的外地人来到森林，他们却无意中吵醒正在雪中休息的大白熊。混乱中，熊二和大白熊再度相逢，而一场意想不到的全新冒险也即将展开……©豆瓣', '张伟', '丁亮', 8, 34797, 'tt4412240', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2222373886.jpg', 1.3, 2.4, 20.5, 44.1, 31.8, '0.269369,0.105347,-0.923379,0.505430,-0.038097,-0.127689,1.036464,0.113978,-0.298809,-0.000888,0.272669,0.609437,-0.095061,0.404613,0.170586,-0.088109,-0.210117,-0.541510,-0.368552,-0.040050,-0.467672,-0.143265,-0.282923,-0.086728,0.028446,-0.146280,0.419794,0.213828,-0.196686,0.747803,0.119871,0.024378,-0.530524,0.479736,-0.450418,0.170908,0.196600,0.161584,-0.088885,0.256563,-0.165818,-0.023760,-0.187154,-0.035277,-0.099227,0.188932,0.969237,-0.555380,-0.308280,-0.194311,0.096141,-0.255809,-0.011694,0.210286,0.487833,-0.134864,0.411562,-0.140133,-0.052130,0.205923,-0.071030,-0.241108,-0.272835,0.306325,-0.056747,0.098049,-0.578798,0.474259,0.342414,-0.247430,0.434118,-0.227525,0.230209,0.242503,0.206551,0.558622,-0.184561,0.162201,-0.272388,-0.170217,0.603093,-0.117085,-0.073598,0.265948,0.027381,-0.273044,0.092993,0.062562,-0.364814,-0.261780,0.662153,0.029823,-0.305652,0.150834,-0.841029,0.288273,-0.144748,-0.313774,-0.208947,-0.295128,-0.659843,-0.375648,0.068144,-0.427152,-0.240173,0.569027,-0.210375,0.016003,0.674000,-0.623650,0.418266,0.334964,0.244219,0.023449,0.582441,-0.354118,0.117199,-0.216878,0.023331,0.042191,0.154096,0.366212,0.307016,0.381563,-0.308803,0.009974,-0.676519,0.479522', '21619567', '1467779', '20451118', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26220735', '喜羊羊与灰太狼之羊年喜羊羊', '喜剧', '在阳光明媚的日子里，灰太狼突然闯入羊村，虽然他被小羊羊们击退，却把村长的变身魔毯打劫回去。表现英勇的喜羊羊受到伙伴们的称赞，而懒羊羊对此反而有些愤愤不平。为了证明自己的实力，他将慢羊羊的时空照相机错认为手枪，将其偷走后闯入狼堡。得知消息的喜羊羊匆匆赶去营救，结果在混乱之中被卷入时空乱流回到了远古时代，灰太狼和懒羊羊更被魔毯互换了身体。灰太狼无意中被原始羊的千金相为驸马，懒羊羊则成为几只笨狼的首领。可怕的是有一条能把任何生物变成石头的恶龙肆虐，为了保卫原始时代的朋友们，喜羊羊他们携手挑战恶龙，懒羊羊更成为了足以改变历史的英雄人物……©豆瓣', '祖晴', '黄伟明', 6.9, 6233, 'tt4539628', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2223542960.jpg', 8.9, 9.5, 33.1, 22.3, 26.1, '0.378452,0.007573,-0.541253,0.367021,-0.195543,0.116638,0.743020,-0.093234,-0.452331,-0.075217,0.080017,0.752783,-0.230750,0.033238,-0.004786,-0.054508,0.082029,-0.423988,-0.184286,-0.121565,-0.135744,-0.108008,-0.497431,-0.084224,-0.073170,-0.262122,0.667333,-0.076369,-0.382739,0.388444,0.312129,0.157559,-0.177745,0.489191,-0.426233,0.231181,-0.114679,0.081097,-0.010222,0.322795,-0.088971,-0.096509,0.173562,0.436792,-0.237337,-0.081488,0.900740,-0.716005,-0.095431,-0.296198,0.432632,-0.316029,0.039180,0.363316,0.428857,0.291935,-0.041113,0.054300,-0.058577,0.172461,0.333034,-0.128601,-0.822557,0.143370,-0.081252,0.131103,-0.493251,0.173612,0.171360,-0.016166,0.310930,-0.296800,0.364085,0.056881,0.383400,0.351893,-0.139758,0.150606,-0.568155,-0.180327,0.716408,-0.283476,-0.166018,-0.000009,0.033340,-0.313128,0.187469,-0.238216,-0.258088,0.000914,0.635423,0.221489,-0.428701,0.313012,-0.772121,-0.159719,-0.392299,-0.292399,-0.330928,-0.429621,-0.283410,-0.301985,0.027592,-0.170506,-0.115797,0.089117,0.087658,-0.407149,0.713061,-0.851752,0.097133,0.430927,0.350447,-0.448496,0.539400,-0.153198,0.175907,-0.137244,0.150275,0.090126,0.576748,0.413652,0.319092,0.221127,-0.092346,-0.270734,-0.392862,0.536298', '25774050', '2032339', '21619567', '1457926');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26220759', '大虎', '动作', '讲述的是朝鲜日据时期，朝鲜最后一只老虎和最出色的名捕手千满德的故事。崔岷植饰演的名捕手千满德是为了捕猎大虎而需要的人物，但是他很早以前就已经放下枪，和老虎一起守护智异山山君。郑万植饰演的捕虎队队长因为日军的命令而必须赌上性命去捕猎大虎。金尚浩饰演的是对于千满德父子 都很有感情的捕手七久一角。和崔岷植搭档出演父子的则是成侑彬，曾在《没关系，是爱情啊》中饰演赵寅成的少年时代，还参演过电影《捉迷藏》。《莫比乌斯》女主角李恩雨和崔岷植搭档出演夫妻，曾出演《女儿》的玄盛敏出演七九的女儿。日本演员大杉涟将出演日本高官，想带着朝鲜的最后一只老虎衣锦还乡回日本，所以下达了捕虎任务。郑锡元将饰演带领捕虎队出征的日本军官，罗美兰饰演七九的妻子，金洪波饰演千满德的药材商朋友。曾在朴勋政导演的《新世界》中出演延边混混的吴正国和朴仁洙则出演捕虎队队员。', '崔岷植', '朴勋政', 7.4, 13533, 'tt5066556', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2283081964.jpg', 0.9, 4.1, 36.9, 42.7, 15.4, '0.100065,-0.432556,-0.402014,0.762953,-0.063037,-0.209010,0.534105,0.147391,-0.235802,-0.217895,0.374054,0.953999,0.085963,0.025579,0.401043,-0.142961,-0.247187,-0.752427,-0.458047,-0.054202,0.133135,-0.495879,-0.288233,0.246379,0.073992,-0.263499,1.112866,-0.343272,-0.202755,0.687962,0.637726,0.204349,-0.194281,0.021847,-0.053005,0.200169,0.008534,-0.073511,-0.615202,0.135455,0.093153,-0.209149,-0.160657,-0.049905,0.070697,0.451219,0.534300,-0.388818,0.134648,-0.098403,0.176412,-0.393197,0.000094,-0.134422,0.389013,0.153480,0.565363,0.348970,0.152072,0.254355,-0.192994,-0.256151,-0.862950,0.015808,0.295044,0.184522,-0.651123,0.307016,0.044300,0.166570,0.389990,-0.109395,0.406913,0.198354,0.228031,0.353226,-0.183450,0.226464,-0.273325,0.513377,0.644063,-0.116183,0.269551,0.245020,0.069367,-0.568549,-0.130945,-0.300714,-0.620282,0.261383,0.006872,-0.201664,-0.216838,-0.087753,-0.530443,0.079807,-0.072465,-0.102491,0.281280,-0.237482,0.255138,-0.766701,-0.120349,-0.469224,0.108718,-0.031210,0.256796,-0.404755,0.836379,-0.823466,-0.089063,0.400653,0.401780,-0.393610,0.851112,0.448070,0.025903,-0.312709,0.208401,-0.035115,0.124318,0.026894,0.179921,0.271353,-0.067446,-0.439714,-0.417341,0.309329', '25880986', '4301278', '1780122', '3014200');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26235315', '落跑吧爱情', '爱情', '纷纷（舒淇 饰）是含着金汤匙出生的千金大小姐，打小过着衣食无忧的富足生活。到了出嫁的年龄，父母对纷纷的终身大事十分关注，无形之中带给了纷纷极大的压力，终于，不堪重负的纷纷决心离家出走。循着歌词里的描绘的美好景象，纷纷来到了澎湃湖。在澎湃湖，纷纷入住了一间民宿，民宿的主人是一位名叫阿武（任贤齐 饰）的男子。纷纷并不知道，这间民宿正面临着生死存亡的紧要关头，阿武的弟弟（李国毅 饰）将房屋抵押出去结果投资失败，不仅血本无归，民宿更是即将被查封。受到阿武一家人的悉心照料，纷纷决定和民宿的大家并肩作战，与此同时，纷纷的家人得知了女儿的下落，正在赶来的路上。©豆瓣', '任贤齐', '任贤齐', 5.6, 6154, 'tt4971480', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2263065870.jpg', 8.9, 26.5, 45.3, 12.6, 6.7, '0.244761,-0.064864,-0.846636,0.396503,0.089467,-0.234083,0.750911,0.327405,-0.519012,-0.054640,0.487385,0.744975,-0.262133,0.529620,0.389924,-0.151952,0.018505,-0.460148,-0.421348,-0.097756,-0.353859,-0.251148,-0.014330,-0.065210,-0.205904,-0.180181,0.318403,0.232461,0.009799,0.613878,0.456154,0.315264,-0.315651,0.488350,-0.349470,0.199903,0.031388,0.000730,-0.360852,0.096607,-0.115503,-0.332312,-0.137860,0.273044,0.141364,0.272284,0.878899,-0.389603,-0.122619,0.025171,0.405493,0.029911,0.152990,0.439474,0.466827,0.262417,0.240032,0.054689,-0.499707,0.019330,0.117340,-0.238258,-0.435450,-0.016466,0.513526,0.148323,-0.845712,0.333161,0.208264,-0.323089,0.226086,-0.375381,0.290781,0.183865,-0.215737,0.635062,-0.270993,0.065954,-0.503200,0.103699,0.813983,0.057109,0.248449,0.133981,-0.268250,-0.257648,-0.089013,0.026892,-0.663485,-0.207169,0.490811,0.412857,-0.009762,0.281644,-0.470744,0.039367,-0.186584,-0.613005,0.238629,-0.372798,-0.247715,-0.729523,-0.135662,-0.327122,0.050850,0.467359,0.036002,0.037744,0.971184,-0.723299,0.026757,0.326099,0.152199,-0.448779,0.430395,-0.180111,0.350844,0.103371,-0.226659,-0.046971,-0.126632,0.501919,0.170152,0.241634,-0.306584,-0.238630,-0.223996,0.461617', '3811356', '21619567', '5977789', '25731805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26235346', '犯罪现场', '悬疑', '《犯罪現場》以通缉犯徐糠伏尸屋事件开始，负责调查的警官林法栋（张继聪 饰）发现涉及一宗一个月前的劫案，当中同谋包括汪新元（古天乐 饰）、红毛（凌文龙 饰）与欧阳（李灿森 饰），而犯罪现场唯一目击证人是一只鹦鹉，林法栋锁定汪新元为嫌犯。不过案情卻不如想像中直接……', '古天乐', '冯志强', 6.2, 93012, 'tt11076480', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2570879785.jpg', 1.3, 13.5, 61.4, 20.4, 3.3, '0.310840,-0.345614,-0.272851,0.341027,0.089577,-0.059654,0.535591,-0.138681,-0.925297,-0.609499,0.063810,0.056335,-0.153934,-0.158366,0.345261,-0.030068,0.008549,-0.665194,-0.295591,-0.042495,-0.372827,-0.889302,-0.190736,-0.324098,-0.063591,0.269438,0.208186,0.126895,-0.335887,0.696410,0.447126,0.360172,-0.505892,0.062743,0.344543,-0.262468,0.238803,0.122765,-0.578973,0.198832,0.182468,-0.148739,0.238924,-0.066474,0.110381,0.372387,0.549079,-0.453718,-0.216917,-0.546455,0.268974,-0.222277,-0.167936,0.068465,0.514714,0.360000,0.502891,0.390385,-0.250671,-0.325017,0.298430,-0.197014,-0.360700,-0.056555,0.224452,0.562185,0.135250,-0.086583,-0.352085,0.115872,0.416740,-0.032259,0.300728,0.095097,0.383853,-0.063931,0.077535,-0.175081,-0.672340,0.420393,0.108572,-0.087096,0.268353,0.047213,0.421924,-0.646735,-0.223265,0.187665,0.330971,0.241833,0.097948,-0.162355,-0.016770,0.043368,-0.283338,-0.347484,-0.299183,0.107093,-0.293995,-0.286078,0.037198,-0.382899,0.010047,-0.271011,-0.170021,0.015297,0.215430,-0.527625,-0.001194,-0.686314,0.110661,0.178528,0.184930,-0.374688,0.317294,-0.050354,0.365866,-0.407502,-0.139925,-0.417401,0.786054,0.260824,0.231858,-0.023005,-0.296467,-0.693819,-0.125421,-0.252205', '1300299', '1296252', '1298493', '3263169');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26235349', '三人行', '剧情', '香港某大型医院，外科主任医师佟倩（赵薇 饰）刚刚完成例行巡视。接二连三的手术让她的神经高度紧张，加上有的患者术后情况并不理想，无形间使她的精神承受了巨大的压力。就在此时，一名遭受枪伤的男子被紧急送到医院。对方名叫张礼信（钟汉良 饰），是一个胆大包天且狡诈非常的高智商罪犯。虽然头部中枪，但幸运的是并未给他造成巨大的创伤。从昏迷中醒来的张拒绝手术，仿佛正耐心等待时机。监视并开枪射伤他的警官陈伟乐（古天乐 饰）高度紧张，他急于知道对方同伙的下落，为此不惜采用非法手段。医患如织的医院内，短短六个小时里，警察、医生和悍匪三方展开了艰苦卓绝的角力……©豆瓣', '赵薇 Wei Zhao', '杜琪峰', 5.9, 93873, 'tt4379728', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2360775241.jpg', 7.6, 22.8, 45.6, 16.2, 7.8, '0.025970,0.024361,-0.577729,0.236706,0.067713,0.180776,0.939453,0.019940,-0.497063,-0.357824,0.557903,0.243125,-0.132186,0.101015,0.011832,-0.146435,-0.068930,-0.647655,-0.178578,0.196558,-0.625102,-0.373254,-0.378961,-0.197422,0.060526,-0.300401,0.296587,0.017342,-0.257357,0.354670,0.046904,0.267912,0.060461,0.685355,0.048212,-0.205438,0.132004,-0.287646,0.029983,0.308860,0.485754,-0.543774,0.135953,0.461634,-0.094228,0.719901,0.695391,-0.014475,-0.375382,-0.158776,0.295198,-0.218176,-0.191032,0.198962,0.338157,0.207029,0.300809,-0.092476,-0.243050,0.235346,0.002929,-0.026759,-0.667896,0.003107,0.060337,0.219952,-0.500396,0.497588,-0.255443,0.028092,0.053389,-0.157579,0.097365,0.230159,0.101476,0.337538,-0.262188,-0.105934,-0.365620,-0.037722,0.445798,-0.131903,-0.431971,0.283530,-0.298412,-0.611738,0.128923,-0.240813,-0.178215,-0.091043,0.191736,0.143334,-0.316406,-0.195973,-0.034818,0.297958,-0.516283,-0.069198,-0.465876,-0.095701,-0.085500,-0.676952,0.118288,-0.326186,-0.272040,0.262590,0.026912,-0.084641,0.433516,-0.534562,0.111712,0.449930,0.221969,-0.195292,0.491525,0.080816,0.018155,-0.137846,-0.196458,0.038647,0.023471,0.499621,0.209859,0.249941,-0.139668,-0.157960,-0.285812,0.222526', '21348112', '1316693', '1578663', '4903581');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26235839', '内在美', '剧情', '家具设计师金禹镇有个不为人知的秘密：他每天一觉醒来都会变成年龄、国籍、性别与前一天截然不同的人，时而年轻帅气、时而老态龙钟，每天都要适应新的自己，这样的他该如何恋爱呢？命运的安排让他遇见了兴趣相投的美丽女孩李秀（韩孝珠 饰），在他神秘莫测的生活中，唯一不变的就是李秀对 他的爱。但两人的爱情，也在每一次禹镇“变身”之后，面临全新的考验。', '韩孝周', '白宗烈', 7.6, 92823, 'tt4273886', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2248466858.jpg', 0.4, 2.7, 31, 46.5, 19.5, '0.159648,0.109364,-0.726636,0.498455,-0.450134,-0.161758,0.801182,0.132477,-0.627491,-0.107381,0.335527,0.775249,-0.095776,0.407613,0.239928,0.210087,-0.244625,-0.666791,-0.074281,-0.136706,-0.378095,-0.225101,-0.517421,-0.326124,0.157792,-0.354937,0.446828,-0.004656,0.074536,0.205999,0.317744,0.082155,0.166216,0.545964,-0.280795,-0.054471,-0.166993,0.297973,0.002857,0.072928,0.076318,-0.103998,-0.293516,0.255817,-0.294249,0.510786,0.699182,0.039570,-0.408867,-0.060485,0.673712,0.005685,-0.424914,0.308763,0.165434,-0.198466,0.229053,0.302036,0.044915,-0.005578,-0.148684,-0.028790,-0.805941,-0.047705,0.166523,0.221534,-0.679729,0.475050,0.079264,-0.378840,0.178353,-0.384223,-0.012306,0.560270,0.557407,0.398646,0.068362,-0.016985,-0.412965,0.297962,0.824407,0.264555,-0.548848,0.503352,-0.651450,-0.398853,-0.321179,-0.392468,-0.596069,0.077078,-0.068694,0.073597,-0.109449,0.005729,-0.664783,0.246211,0.056842,0.016065,-0.081613,-0.565377,-0.263479,-0.328472,-0.192631,-0.833820,-0.517524,0.194007,0.270546,-0.513163,0.893257,-1.043679,0.185696,0.415181,0.020413,-0.843018,0.670865,0.442128,-0.090619,-0.541520,-0.075567,0.159329,-0.305835,0.190404,-0.374666,0.442813,0.208626,0.241308,-0.466178,0.618866', '1303112', '1309161', '26354526', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26245039', '已是香港明日', '喜剧', '卢比（杰米·钟 Jamie Chung 饰）是一名在香港工作的玩具设计师，某日，她邂逅了名为乔什（布莱恩·格林伯格 Bryan Greenberg 饰）的男子。乔什是一名金融工作者，却怀揣着写作梦想，在乔什的带领下，初来乍到的卢比领略了香港独特的美景与风采，在此过程中，两颗心的距离越来越近，然而，一场意外的发生让这段恋情最终无疾而终。一轮春夏秋冬上演过后，卢比和乔什重逢了，此时的卢比已经定居香港，而乔什亦辞职踏上了全新的人生旅途。浪漫的夜幕笼罩下，卢比和乔什都重温了内心里曾经的悸动，可是此时的两人都有了正在交往的恋人，在理智和情感的驱使下，他们会做出怎样的选择？©豆瓣', '郑智麟', '丁怡瑱', 7.2, 10207, 'tt3700804', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2249525185.jpg', 2.3, 7.3, 35.9, 38.2, 16.2, '0.312666,-0.017708,-0.938676,0.633617,0.226649,-0.351371,0.920003,0.190007,-0.445500,-0.216871,0.299559,0.679627,-0.386465,0.514486,0.587476,-0.080752,-0.411079,-0.972143,-0.063702,-0.250222,-0.174518,-0.425673,-0.467604,0.125104,0.002719,-0.214470,0.676989,0.268468,-0.037463,0.674080,0.310214,0.274848,-0.126774,0.588827,-0.245735,-0.068655,0.291718,0.139883,-0.427914,0.248389,0.157767,-0.382898,-0.129027,0.026582,-0.024885,0.353283,0.703734,-0.209546,-0.086804,0.295808,0.207563,-0.266848,0.121552,0.091914,0.065891,0.040963,0.095889,0.068669,-0.287930,-0.048358,0.028567,-0.160294,-0.710257,0.115672,0.022655,0.216522,-0.743545,0.600798,-0.067758,-0.217695,0.111521,-0.291762,0.176304,0.503836,0.527406,0.410518,-0.138156,-0.166636,-0.443324,0.209158,0.820487,0.240016,-0.418742,0.426339,-0.326293,-0.500387,-0.274869,0.055061,-0.545258,-0.202973,0.390706,0.225685,-0.120375,0.245985,-0.852847,0.103388,-0.243983,-0.246720,-0.025277,-0.622642,-0.032305,-0.795157,-0.336245,-0.612596,-0.300989,-0.029207,0.142605,-0.262933,0.652270,-0.880753,0.347273,0.419689,0.213697,-0.174040,0.800768,0.188381,0.166857,0.022747,0.099798,0.294354,-0.143759,0.355633,0.019277,0.399259,-0.046537,0.191190,-0.621850,0.538704', '3111650', '1292211', '3055049', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26245360', '感化院', '剧情', '故事发生在1968年的德国，少年沃尔夫冈（路易斯·霍夫曼 Louis Hofmann 饰）的母亲再嫁，他和继父之间的关系很是紧张，在一场冲突之后，继父将沃尔夫冈送入了感化院之中，沃尔夫冈就此开始了充满了痛苦与折磨的监狱生活。倔强的沃尔夫冈不愿意沦为残暴统治的奴隶，一次又一次的反抗挣扎换来的却只有伤痕累累，唯一支撑着他的，是记忆中来自母亲的温暖。沃尔夫冈决定和同伴安东（Langston Beckford-Uibel 饰）一起逃跑，两人历经千难万险，最终回到了小镇上。可是，当母亲看见沃尔夫冈时，却并未表现得如他所想象的一般高兴，更残酷的是，没过多久，他便再度被继父和母亲重新送回了感化院。©豆瓣', '约纳斯·伯格', '马克·布鲁蒙德', 8.4, 15288, 'tt3127698', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2250072222.jpg', 0.2, 1, 13.8, 50.9, 34.1, '0.040827,0.115339,-0.848652,0.530836,-0.232037,-0.551462,1.091824,0.155768,-0.830385,-0.062266,0.094240,0.864815,-0.043002,0.322505,0.038132,0.009969,-0.244522,-0.824540,-0.146351,-0.093359,-0.297836,-0.508364,-0.090308,-0.041042,-0.151732,-0.401232,0.739276,0.086050,-0.318962,0.427812,0.229670,0.230152,-0.035352,0.789090,-0.205095,0.045209,-0.024742,0.201991,-0.349827,0.125902,0.190109,-0.275136,-0.198248,0.206589,-0.052150,0.366144,0.642321,-0.442319,-0.065229,-0.142606,0.178777,-0.288625,-0.274833,0.294198,0.023176,0.075584,0.192622,0.259435,-0.379232,-0.255010,0.064812,-0.052888,-0.605697,0.011867,0.143352,0.240757,-0.915750,0.720145,-0.092084,0.085976,0.195429,-0.312388,0.180761,0.298756,0.094836,0.618892,-0.284050,0.004364,-0.435549,0.164189,1.076433,-0.086383,-0.328885,0.525950,-0.265654,-0.329320,-0.035780,-0.432279,-0.619163,0.035594,0.282368,0.203923,-0.399001,0.576793,-0.525512,-0.110091,-0.441588,-0.081366,-0.018758,-0.494025,0.045627,-0.255617,-0.280887,-0.385901,-0.410044,0.084631,-0.137229,-0.374822,0.580145,-0.813918,0.418177,0.385860,0.332203,-0.198475,0.536178,0.215029,0.181772,-0.011073,0.343274,0.532581,0.127304,0.178283,0.296548,0.320342,-0.059104,0.106718,-0.363635,0.761466', '25721544', '25723780', '1308755', '3014557');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26252157', '龙三和他的七人党', '喜剧', '年过七十的高桥龙三（藤龙也 饰）曾是名噪一时的黑帮头目，而今他风光不再，委身寄居在儿子龙平（胜村政信 饰）的家中，还得忍受孩子们各种指摘与批评。许是对曾经热血岁月的回忆，让龙三相继和当年的哥们儿阿胜（近藤正臣 饰）、暴恐茂吉（中尾彬 饰）、快枪手马克（品川彻 饰）、拐杖市三（樋浦勉 饰）、五寸钉阿秀（伊藤幸纯 饰）和剃刀阿鹰（吉泽健 饰）等人碰头，老爷爷们把酒言欢，一拍大腿决定干脆再成立个黑帮组织——一龙会。与此同时，以西（安田显 饰）为首的新时代犯罪团伙京滨联合正展开不择手段的敛财行动，而一向看不惯他们的恶行的龙三一伙自然要与之发生冲突。老派的黑帮分子碰上新生代的犯罪团伙，却又是一场义理与金钱的较量……©豆瓣', '藤龙也', '北野武', 7.6, 19027, 'tt4176776', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2224229425.jpg', 0.5, 2.9, 29.6, 47.9, 19.2, '0.026454,-0.276793,-0.495952,0.460970,0.052502,-0.217023,0.537673,0.118666,-0.418085,-0.212005,0.153637,0.499764,-0.200038,0.318754,0.309096,-0.214487,0.047382,-0.952222,-0.088815,0.145032,0.024960,-0.377896,-0.241520,-0.324877,-0.130293,-0.035167,0.447665,0.111597,-0.239902,0.520826,0.487208,0.564664,-0.183136,-0.087909,-0.299143,-0.218053,-0.183983,0.243812,-0.262087,-0.342320,-0.303833,-0.377132,-0.159998,0.126658,0.220620,0.435818,0.550075,-0.373788,0.157796,-0.365639,-0.034909,-0.201130,-0.185894,0.171975,0.441650,-0.163329,0.258848,0.490336,0.013818,0.000745,0.067183,0.018644,-0.603871,0.058469,0.144469,0.040730,-0.635795,0.485468,-0.055463,-0.138963,-0.133924,-0.114463,-0.019551,0.267918,0.125398,0.167414,-0.095520,0.005717,-0.362014,0.245728,0.546680,0.106995,-0.000507,-0.092190,0.249219,-0.377753,-0.289443,-0.381595,-0.060549,-0.320826,0.207682,-0.197207,0.063774,0.181253,-0.907286,-0.133443,-0.018075,0.027254,0.333646,-0.073533,0.131605,-0.630524,-0.035063,-0.650017,-0.277754,0.399156,0.321164,-0.114285,0.655457,-0.643863,-0.068691,0.169661,0.191140,-0.737262,0.446690,0.236685,-0.060336,-0.229313,-0.175785,-0.092706,0.211052,-0.016775,0.203252,0.292581,-0.116380,-0.355231,-0.076976,0.144707', '26730542', '4301278', '1307762', '25777330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26252196', '卫生间的圣母像', '剧情', '园田宏（野田洋次郎 饰）从小就梦想成为一名画家，然而，残酷的现实撞碎了他的艺术梦想，从美大毕业之后，园田成为了一名玻璃清洁工。让园田更加难过的是，曾经和自己一起为了梦想而奋斗的前女友如今已经成为了小有名气的画家，还举办了个人展览。一天，园田忽然晕倒，不愿意将自己生病的事情告诉家人的他拜托偶然邂逅的女高中生真衣（杉咲花 饰）假扮成他的妹妹，陪他去医院做检查。让园田没有想到的是，他患上的是胃癌晚期，生命只剩下三个月左右了。在真衣的陪伴和鼓励之下，本来打算全盘放弃的园田决定入院接受治疗。©豆瓣', '野田洋次郎', '松永大司', 7.7, 10317, 'tt4197480', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2228824410.jpg', 0.4, 3.2, 29.2, 45.3, 21.8, '0.048389,-0.055273,-0.487470,0.190002,-0.362330,-0.399362,0.554411,0.117802,-0.312423,-0.452734,0.160488,0.819981,0.052257,0.456844,0.259890,0.124579,-0.087824,-0.776385,0.031997,-0.114167,-0.414052,-0.513136,0.114291,-0.229943,-0.196092,-0.262599,0.835581,0.129584,-0.005865,0.427377,0.359808,0.508000,0.267083,0.302544,-0.294858,-0.029647,0.123191,0.170374,-0.267090,0.434250,0.084516,-0.228037,-0.065082,0.280908,0.017176,0.185347,0.559002,0.015669,-0.218933,-0.154313,0.443365,-0.415689,-0.165499,0.155382,0.234238,0.045397,0.228605,0.168602,-0.428542,-0.223420,0.061394,-0.073286,-0.746499,0.011347,0.189693,0.093288,-0.793259,0.325808,-0.014256,-0.205491,0.307903,-0.286527,0.263659,0.446264,0.189305,0.450750,-0.402257,0.249296,-0.509196,0.546865,0.920495,-0.083419,-0.103476,0.482737,0.057963,-0.179744,0.060880,-0.361205,-0.363397,0.111840,-0.233261,0.104658,-0.369321,-0.255387,-0.312782,-0.258384,-0.350398,-0.301290,0.221736,-0.362447,0.012782,-0.227095,0.109483,-0.187288,-0.365992,0.034027,0.113050,-0.648181,0.839860,-0.914620,0.306511,0.494192,0.400957,-0.619573,0.777288,0.250232,0.012865,-0.250465,0.277362,0.122678,-0.023545,0.348653,0.131211,0.315416,0.093489,-0.009217,-0.634259,0.422264', '5985887', '35048413', '30345227', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26253737', '非常父子档', '剧情', '顾泰丰（文梅森 饰）是拥有着高超智商的天才少年，他从小生长在单亲家庭之中，对自己的身世充满了疑惑和好奇。终于，某一日，顾泰丰黑进了医院的资料库之中，发现了隐藏在自己身世之中的秘密。原来，他的父亲是一位名为周力岩（李治廷 饰）年轻男子，年少时曾经捐赠过精子，于是在机缘巧合之下成为了顾泰丰生理上的父亲。于是，顾泰丰决定远渡重洋，踏上了前往中国的寻父之旅。面对这个突如其来的“儿子”，周力岩的态度是拒绝的，他根本没有做好做父亲的准备，更别提照顾这样一个古灵精怪的孩子了。紧接着而来的，是顾泰丰的妈妈美艳（金荷娜 饰），她和顾泰丰的出现给周力岩的生活带来了翻天覆地的变化。©豆瓣', '李治廷', '曹溱模', 5.6, 5084, 'tt6389310', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2391176999.jpg', 6.4, 23.4, 58.9, 8.2, 3.2, '0.300794,-0.003366,-0.952470,0.775586,-0.385761,-0.130643,0.791780,-0.007100,-0.669991,-0.326480,0.131335,0.843247,-0.052735,0.408677,0.178086,0.089705,-0.083728,-0.682426,-0.238493,-0.271819,-0.365897,-0.483331,-0.387116,0.001381,-0.026647,-0.399793,0.519774,0.023161,-0.284303,0.458684,0.319633,0.443959,0.107184,0.602891,-0.319234,0.223223,-0.017798,0.083812,-0.014183,0.239643,0.164995,-0.346262,0.027013,0.251268,-0.088497,0.501418,0.645405,-0.302640,-0.385052,-0.209071,0.419449,-0.191871,-0.173455,0.086353,0.104294,0.056204,0.171446,0.097458,-0.301923,0.033599,0.096935,-0.235747,-0.705393,-0.143458,0.326583,0.176209,-0.837832,0.276332,-0.059059,-0.308129,0.189510,-0.542681,0.256607,0.301063,0.047871,0.529312,-0.183970,0.097438,-0.471287,0.217813,0.634473,0.060632,-0.114055,0.370388,-0.236256,-0.330220,0.015030,-0.241323,-0.596219,0.096825,0.149314,0.145973,-0.184028,0.144276,-0.358885,-0.046735,-0.069197,-0.181955,0.013558,-0.540161,-0.163097,-0.197878,-0.246078,-0.644745,-0.421832,0.017718,-0.014747,-0.435949,0.869178,-0.981025,0.199992,0.192154,0.328080,-0.558697,0.659041,0.032802,0.052389,-0.021608,0.037179,0.182635,-0.109455,0.173653,-0.072926,0.336266,0.071230,-0.225549,-0.495551,0.445723', '1301022', '21360412', '35030151', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26253783', '神奇马戏团之动物饼干', '喜剧', '欧文的叔叔在经营着一家以动物表演闻名的马戏团，但一场大火却让叔叔意外去世，马戏团的表演场也全部化为灰烬。此时，继承马戏团的重担落在了欧文身上，但他却显得犹豫不决，而在叔叔的葬礼上，欧文的大伯霍勒肖放话要继承马戏团和宝藏，小丑红鼻头也将一盒贴着“绝对不能吃”的动物饼干交给了欧文，令局势更加混乱……', '艾米莉·布朗特', '托尼·班克罗夫特', 5.7, 4587, 'tt4155534', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2528298973.jpg', 5.8, 27.8, 49.1, 11.7, 5.5, '0.424852,0.105863,-0.503845,0.450478,-0.064471,-0.430511,0.700340,0.650060,-0.583578,-0.024472,0.170985,0.904756,-0.151562,0.138798,0.027540,-0.018266,-0.172254,-0.610111,-0.379070,0.134603,-0.179889,-0.557134,-0.139137,-0.340099,0.235604,-0.453631,0.544893,-0.080210,-0.066967,0.569972,0.312851,-0.057509,-0.026599,0.138680,-0.209216,-0.137084,-0.262651,0.137351,-0.233117,0.267400,0.229896,-0.152182,-0.099327,0.308406,0.257594,0.170179,0.695894,-0.283059,-0.211470,-0.101345,0.014732,-0.382170,0.043110,0.239554,0.248544,-0.165573,0.186265,0.023287,-0.240824,0.190937,0.162177,-0.024292,-0.726140,0.127910,0.245648,0.325225,-0.813048,0.579697,-0.065890,0.043054,0.043416,-0.470736,0.479741,0.204682,0.013479,0.543702,-0.253741,0.111939,-0.674400,0.021337,0.563098,-0.128560,0.019026,0.016565,-0.206390,-0.227468,-0.043857,-0.335194,-0.470631,0.308007,0.292719,-0.006024,-0.072814,0.420949,-0.841068,-0.177515,-0.053871,-0.624101,-0.074106,-0.404047,-0.148874,-0.275272,-0.057801,-0.139261,-0.084825,-0.203475,0.156125,-0.168728,0.502019,-0.656789,0.310528,0.241493,-0.051269,0.158620,0.419656,-0.209260,0.104044,-0.017568,-0.358315,0.042914,0.286322,0.207350,0.378043,0.324333,-0.054787,-0.218666,-0.419861,0.602549', '2032339', '1783461', '3285642', '24698878');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26258752', '仲夏夜魔法', '动画', '故事发生在妖精世界之中，精灵公主玛丽琳（埃文·蕾切尔·伍德 Evan Rachel Wood 配音）即将和她深爱的罗兰德（萨姆·帕拉迪奥 Sam Palladio 配音）步入婚姻的殿堂，可是，一次偶然之中，玛丽琳却发现罗兰德根本不爱自己，和自己结婚不过就是为了得到王位而已。心碎的玛丽琳陷入了悲伤和绝望之中。罗兰德眼看自己的阴谋就要破灭，于是找到了单纯的小精灵阳光（伊利亚·凯利 Elijah Kelley 配音），花言巧语欺骗后者前往黑暗森林，那里住着会制作爱情药水的女巫蜜糖（克里斯汀·肯诺恩斯 Kristin Chenoweth 配音）。得到了爱情药水，阳光决心将它撒在玛丽琳的妹妹多恩（梅尔迪丝·安妮·布尔 Meredith Anne Bull 配音）身上，然而，沼泽大王（艾伦·卡明 Alan Cumming 配音）忽然出现，受到药水的影响，多恩竟然爱上了他。沼泽大王和玛丽琳不打不相识，发现彼此情投意合，与此同时，罗兰德带兵前来攻打城堡，情况十分危急。', '克里斯汀·肯诺恩斯', '嘉里·瑞德斯托姆', 7.3, 8857, 'tt4191054', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2217439993.jpg', 1.3, 6, 35.3, 39.1, 18.3, '0.251102,0.186119,-0.771618,0.548209,0.136964,-0.264472,0.759881,-0.037605,-0.081793,-0.376779,0.362992,0.643048,-0.262018,0.208650,0.226494,0.387135,-0.764717,-0.606962,0.236853,-0.292813,-0.330975,-0.533400,0.073731,-0.188466,-0.096055,-0.503692,0.811596,-0.047409,-0.023713,0.229621,0.107853,0.301623,-0.062328,0.537173,0.295007,0.060352,0.442821,-0.430569,-0.342820,0.318163,0.237239,0.287215,-0.118989,0.491218,0.122302,0.041573,0.604556,-0.717456,0.328777,-0.186837,0.243637,-0.420192,0.425182,0.002046,0.149574,-0.493110,0.272057,-0.032163,-0.091188,-0.209809,0.107471,-0.272003,-0.208318,0.172534,-0.177261,0.259409,-0.190558,-0.070380,0.024480,0.071650,0.243179,-0.260352,0.075412,0.114471,0.428532,0.347774,-0.354760,0.053725,-0.430384,-0.258716,0.543143,-0.040140,-0.314541,0.377559,-0.362600,-0.405555,0.109562,0.048184,-0.639559,0.020395,0.509121,0.056783,-0.097857,0.544147,-0.528255,-0.290028,-0.673515,0.035308,0.079989,-0.364624,-0.260196,-0.443169,-0.346897,0.017283,-0.278306,-0.230133,-0.012452,-0.340776,0.339165,-0.892099,0.303859,0.556904,0.486644,-0.030314,0.384842,-0.068162,0.003767,-0.102911,-0.046108,0.778165,-0.130281,-0.207988,0.231501,0.105889,0.1