INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26258872', '小叮当：永无兽传奇', '动画', '小叮当的朋友芳雯结识了强大又神秘的永无兽，并与它成为了朋友。但是其它仙子并不认可永无兽，芳雯会如何解决这次信任危机呢？', '金妮弗·古德温', '史蒂夫·伦特', 8.2, 9451, 'tt3120408', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2214920830.jpg', 0.2, 1.5, 19.1, 47, 32.2, '0.081371,0.198579,-0.092400,0.771299,-0.285304,-0.081139,0.550700,-0.246039,-0.153069,-0.374210,-0.407559,0.825970,0.366252,0.140790,-0.278354,-0.038939,0.235170,-0.378839,0.494883,-0.099320,-0.405610,-0.309329,-0.485954,-0.037740,-0.158869,-0.403078,0.665778,0.266098,-0.276524,0.227068,0.160906,0.180351,-0.355563,0.955036,-0.207654,-0.144255,-0.023172,0.625285,-0.461948,0.552079,-0.196458,0.289609,0.234530,0.500381,0.020566,-0.105198,0.195756,-0.831632,-0.612196,-0.311885,0.004514,-0.327751,0.259281,0.303718,0.322161,-0.340708,0.351343,0.285281,-0.079480,-0.055323,-0.167251,0.073535,-1.144957,0.297732,-0.134376,-0.088877,-0.010366,0.426316,0.314083,0.035155,-0.059836,0.002789,0.312578,0.785622,0.503171,0.057837,-0.202559,-0.102946,-0.486092,-0.057972,1.297597,0.385119,-0.263429,0.215091,-0.051457,-1.026807,0.134671,-0.092586,-0.032708,0.241499,0.320864,0.897266,-0.391375,0.611493,-0.511363,0.476355,-0.193747,0.364163,0.081377,-1.177749,0.555369,-0.164443,-0.049560,-0.030368,-0.364734,-0.182082,0.481253,-0.440480,0.903070,-1.134468,0.161985,0.526316,0.574324,-0.814770,0.476563,-0.089075,0.028326,-0.288555,-0.244337,0.049030,0.658675,0.534708,0.039057,0.088917,0.292216,-0.325898,-0.279800,0.257695', '25721544', '30163500', '25917239', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26259202', '跑调天后', '剧情', 'Florence Foster Jenkins，为20世纪早期美国女高音歌唱家，以糟糕的唱功，然而绝佳的娱乐才能，得到了观众的欢迎。Jenkins非常自信，将自己与当时著名的女高音家Frieda Hempel和Luisa Tetrazzini相媲美，毫不介意表演时台下观众传出的阵阵嘲笑。她对自己的表演场地有严格的选择，通常是在纽约市的丽嘉宴会厅。演唱会的听众也仅限于自己忠诚的会员和一些邀请嘉宾，甚至自己决定门票的所有人。76岁时，Jenkins要求在卡内基音乐厅进行一次公演，人们很期待这次表演，因此门票早早地售完，然而，Florence Foster Jenkins却在一个月后去世了。', '梅丽尔·斯特里普', '斯蒂芬·弗雷斯', 6.9, 21514, 'tt4136084', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2322114602.jpg', 0.8, 6.1, 48.5, 34.7, 9.8, '0.173034,0.133354,-0.730234,0.778728,-0.109466,0.060012,0.604641,0.154584,-0.667757,-0.010115,0.452995,1.152247,-0.641696,0.321432,0.326145,-0.240905,-0.290295,-0.776456,-0.144031,-0.144307,-0.143331,-0.385538,0.122329,-0.225863,-0.393724,-0.477084,0.648692,0.217344,-0.193617,0.627011,0.271066,0.078799,0.427795,0.553143,-0.171937,-0.435732,0.273191,0.073706,-0.159801,0.305667,-0.054013,-0.234705,-0.400221,0.424029,0.072652,0.368758,0.698854,-0.171896,-0.234229,0.333087,0.859783,-0.315182,0.070350,0.336086,0.212318,0.059494,0.446867,0.094827,-0.258462,0.097507,-0.410731,-0.155582,-1.060002,-0.073043,0.140666,-0.046367,-0.608633,0.838771,-0.092194,-0.045371,0.263224,0.005975,0.221863,0.327130,0.034456,0.430234,-0.328583,0.001465,-0.330125,0.317069,0.871707,0.297617,-0.336051,0.334487,-0.340969,-0.911162,-0.119894,-0.281461,-0.527570,0.192877,0.128216,0.218533,0.070268,-0.157483,-0.500549,-0.142730,0.082771,-0.694400,0.214063,-0.634649,-0.292824,-1.299824,0.063213,-0.306222,-0.040354,-0.180310,0.207130,-0.359714,1.162280,-1.182154,-0.001905,0.417723,0.267740,-0.239116,0.976800,-0.065454,-0.001167,0.001671,-0.310764,-0.220183,-0.193278,0.154839,0.134071,0.436411,0.129112,-0.322396,-0.395930,0.710824', '27602116', '2027945', '3811356', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26259634', '何以笙箫默', '爱情', '曾经，何以琛（黄晓明 饰）拒绝了身边络绎不绝的追求者们，偏偏选择了单纯而又天真的赵默笙（杨幂 饰），然而，赵默笙特殊的家庭背景却让这一对恋人最终走上了陌路。一眨眼七年过去，赵默笙带着一个秘密回到了故地，让她没有想到的是，在那里等待着她的，竟然正是分手后再无联系的何以琛。在何以琛的内心里，一直保留着对赵默笙的感情，可是，此时的赵默笙早已经不是当初的烂漫少女，而是一个离过婚的女人。与此同时，何以琛的父亲和赵默笙的父亲之间有着不可告人的过去和无法调和的矛盾，失去了家人的祝福和支持，这对饱经风霜的恋人能否坚持他们自己的选择？©豆瓣', '黄晓明', '杨文军', 3.8, 160604, 'tt4657764', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2239863767.jpg', 44.9, 29.9, 17.4, 4, 3.9, '0.585091,0.302856,-1.016645,0.898019,-0.204842,-0.402269,0.979181,0.124523,-0.660058,-0.274159,-0.069161,0.712726,-0.076135,0.261990,0.122973,-0.013459,-0.077397,-0.972585,-0.449534,-0.388087,-0.526071,-0.546545,-0.229972,0.112663,-0.185195,-0.093171,0.766035,0.086865,-0.064138,0.653066,0.534167,0.251946,-0.047797,0.643803,-0.321612,-0.101604,0.064462,0.448408,-0.412642,0.338350,0.468336,-0.165461,-0.193393,0.537969,-0.268165,0.465327,0.529827,-0.565839,-0.359853,0.164779,0.149029,-0.241594,0.007472,0.138113,0.317663,-0.093047,0.447295,0.353943,-0.343501,0.001165,0.226005,0.153090,-0.919349,-0.015182,0.027918,0.332675,-0.784138,0.749608,0.019695,-0.445241,0.034057,-0.404051,0.444738,0.589695,0.222621,0.467819,-0.514319,-0.142247,-0.775164,0.024958,0.917161,0.295617,-0.171847,0.414717,-0.282365,-0.247376,-0.116822,-0.200336,-0.742281,-0.008749,0.265001,0.313108,-0.320365,0.044144,-0.494704,0.041805,-0.342964,0.120403,0.128780,-0.848798,-0.075214,-0.131206,-0.119370,-0.752071,-0.539742,0.199388,0.029622,-0.362769,0.850470,-1.328121,0.273693,0.570113,0.646077,-0.731986,0.736427,0.459093,-0.104264,-0.168213,-0.075829,0.227286,-0.193295,0.154506,0.208466,0.276289,0.039919,-0.017149,-0.509575,0.509257', '1301022', '35030151', '1308755', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26259635', '恋人们', '剧情', '筱冢淳（筱原笃 饰）的妻子在数年前死于一场无差别连环杀人案件，凶手虽然被捉拿归案却因为一份精神鉴定报告而拥有了免死金牌。这些年来，筱冢淳努力工作，将全部的积蓄拿出来雇佣昂贵的律师，只为了能够为自己的妻子讨回一个公道，但事与愿违，就连律师都劝他放弃，生无可恋的筱冢淳想到了死。高桥瞳子（城岛瞳子 饰）和丈夫以及婆婆生活在同一屋檐下，丈夫的冷漠，婆婆的轻视，瞳子的每一天都在压抑和孤独之中度过，直到一名个性开朗的男子走进瞳子的生活，两人之间很快就产生了感情。四之宫（池田良 饰）是一名律师，他小心翼翼的隐藏着自己同性恋者的身份，却最终因为小小的误会而失去了自己的恋人。©豆瓣', '筱原笃', '桥口亮辅', 7.4, 6701, 'tt4396074', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2315270637.jpg', 0.7, 4.3, 34.7, 46.7, 13.6, '-0.041472,0.003251,-0.455895,0.557067,-0.363458,-0.366063,0.929137,0.333605,-0.451123,-0.341514,0.303604,0.596698,0.137675,0.198275,0.239331,-0.073177,-0.012348,-0.748736,-0.142794,-0.106353,-0.085853,-0.429604,-0.255604,-0.100234,-0.325603,-0.263266,0.781694,0.010644,-0.044291,0.288437,0.316144,0.297574,-0.041606,0.358210,-0.167089,-0.169591,-0.032922,0.008553,-0.239864,0.189775,0.146947,-0.259474,-0.019542,0.371769,-0.098436,0.395659,0.695716,-0.117878,-0.392609,0.007114,0.387641,-0.254735,-0.187978,0.233867,0.136510,0.092425,0.233020,0.251998,-0.358436,0.022192,0.232602,0.093711,-0.935952,-0.044888,0.174072,0.191367,-0.782918,0.687977,-0.019570,-0.146533,0.083050,-0.221228,0.081388,0.186999,0.150462,0.392120,-0.532201,0.044658,-0.354294,0.331546,0.634332,-0.047374,-0.171395,0.335475,-0.267016,-0.407312,0.042957,-0.250604,-0.671341,-0.071390,0.135862,0.255146,-0.102509,0.196703,-0.563312,-0.016903,-0.242251,0.007952,0.136618,-0.725964,-0.126871,-0.221714,-0.228545,-0.400506,-0.528866,0.303253,0.088196,-0.328178,0.751399,-0.760277,0.302234,0.465181,0.130969,-0.536225,0.614873,0.271684,0.155194,-0.191757,0.066678,0.185256,0.122845,0.341958,0.117556,0.083055,-0.110839,0.230394,-0.368258,0.382714', '6745433', '4847665', '26021055', '4840388');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26259677', '垫底辣妹', '剧情', '长相甜美的高中女孩工藤沙耶加（有村架纯 饰）在家并不受父亲待见，父亲一心要把弟弟培养成棒球手，而疏于对女儿们的呵护。沙耶加所在的高中有内部升学的制度，因此她终日和小姐妹们吃喝玩乐，学习掉到了全年级倒数第一也毫不为意。温柔勤苦的妈妈（吉田羊 饰）经常被校方找去说教，她为女儿的未来焦虑万分，因此将沙耶加送到了坪田（伊藤淳史 饰）所开办的补习班。经过水平测试，沙耶加实际只有小学四年级的水平，不过开朗自信的坪田不以为意，他以特有的方式打开女孩的心防，两人很快成为好朋友。在坪田的帮助下，沙耶加对学习的态度逐渐浓厚，后来更立下了考取庆应大学的宏愿。这是丑小鸭绝地逆袭的真实故事……本片根据《年级倒数第一的辣妹一年内偏差值提升40以上并考入庆应大学的故事》改编，该书取材自真人真事，由担任影片女主角原型小林沙耶加的私塾教师坪田信贵撰写。©豆瓣', '有村架纯', '土井裕泰', 8.3, 410936, 'tt4195368', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2329080834.jpg', 0.3, 1.4, 17.2, 45.7, 35.4, '-0.004041,-0.137573,-0.519744,0.702966,-0.271597,-0.111073,0.214512,0.077561,-0.408176,-0.429354,-0.066786,0.568598,-0.090609,0.612164,0.179679,-0.329671,0.055274,-0.582441,-0.259506,-0.330424,-0.239561,-0.388422,-0.082897,0.033591,-0.271336,-0.229457,0.666433,-0.104720,-0.277368,0.505472,0.187635,0.270687,0.177738,0.005609,-0.243635,-0.153828,-0.152856,0.159439,-0.069877,0.042883,0.091303,-0.074398,-0.092276,-0.282835,0.437059,0.250366,0.947338,0.036416,-0.227326,-0.180566,0.560455,-0.102886,-0.269917,0.088819,0.494677,0.144315,0.191321,0.188774,0.031480,0.377692,-0.109142,-0.693608,-0.585403,-0.243205,0.291133,-0.201405,-0.621446,0.399852,0.005612,-0.302062,0.263830,-0.124798,-0.173650,0.216650,0.046396,0.542212,-0.335403,0.094362,-0.194432,0.480998,0.329318,-0.003438,-0.233704,0.301310,-0.198811,-0.435046,0.082867,-0.509364,-0.254134,0.152844,0.074377,0.131020,0.109842,-0.008666,-0.327159,-0.355130,-0.012806,-0.225426,0.271464,-0.517586,0.017350,-0.588685,0.048927,-0.389748,-0.269779,-0.154385,0.071498,-0.495006,1.035718,-1.054464,0.167817,0.112665,0.304090,-0.549219,0.531015,0.151138,0.256122,-0.354314,-0.130460,0.189812,-0.032295,0.460805,-0.099571,0.392350,-0.168435,-0.462824,-0.423400,0.641143', '25922902', '26219652', '101