INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26260853', '速度与激情8', '动作', '多米尼克（范·迪塞尔 Vin Diesel 饰）与莱蒂（米歇尔·罗德里格兹 Michelle Rodriguez 饰）共度蜜月，布莱恩与米娅退出了赛车界，这支曾环游世界的顶级飞车家族队伍的生活正渐趋平淡。然而，一位神秘女子Cipher（查理兹·塞隆 Charlize T heron 饰）的出现，令整个队伍卷入信任与背叛的危机，面临前所未有的考验。', '范·迪塞尔', 'F·加里·格雷', 7, 325667, 'tt4630562', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2444256500.jpg', 1.7, 7.7, 40.8, 36, 13.8, '0.213905,0.239175,-0.616085,0.604312,0.400023,-0.136665,0.790226,0.334595,-0.490617,-0.585191,0.137696,0.735190,0.015301,0.255534,0.968691,-0.043922,-0.052892,-0.623330,-0.219269,0.135761,-0.271676,-0.449763,-0.229726,-0.152127,-0.049396,-0.619374,0.646070,0.252189,-0.518793,0.756213,0.444098,0.944819,-0.388835,0.210149,-0.028656,-0.208954,0.520067,0.208790,-0.622782,-0.133649,-0.417613,0.032026,-0.206061,0.106988,0.039455,0.066723,0.346311,-0.327073,0.064843,0.020148,0.151551,-0.206227,-0.113917,-0.201315,0.221203,0.046138,0.001696,0.296118,-0.001672,0.139288,-0.005368,-0.227130,-0.741890,0.190348,0.109357,0.113182,-0.494418,0.131860,-0.134611,-0.089685,0.141306,0.261480,0.201268,0.711958,0.287884,0.117497,0.149256,0.107085,-0.481647,-0.099449,0.641759,-0.105090,-0.431580,-0.034162,-0.186158,-0.282846,-0.310730,-0.370465,-0.585360,0.028479,0.245845,0.007813,0.428167,0.664349,-0.713097,0.021750,-0.483078,-0.160656,0.131346,-0.217445,0.077354,-1.194853,-0.268710,-0.390314,-0.254328,0.344618,-0.026885,-0.119966,0.410902,-0.536997,0.397298,-0.005023,0.073503,-0.382420,0.503212,0.211220,0.340356,-0.497062,-0.001250,0.642866,0.210781,-0.240710,-0.178046,0.134511,-0.145911,0.094581,-0.310438,0.389319', '6517421', '1293656', '7916027', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26263417', '一生有你2019', '爱情', '根据经典同名歌曲改编，还原校园民谣时期大学校园里的一段真实故事。当母胎单身的工科男欧洋（谢彬彬饰）邂逅文艺女校花方瑶（徐娇饰），为了毕业前脱单，欧洋阴差阳错地学起了吉他，伙同损友们上演了一出“音乐求爱”的大戏，于是一段充满欢笑眼泪，热血而又遗憾的初恋开始了……', '徐娇', '卢庚戌', 3.9, 6471, 'tt11323144', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2572401707.jpg', 42.5, 31.7, 17.8, 3.1, 5, '0.432038,0.204423,-0.286978,0.486556,0.460068,-0.250848,0.661060,-0.368235,-0.214965,-0.069865,-0.062956,0.298982,-0.545822,0.736433,0.537351,-0.311847,-0.467347,-0.758106,-0.037227,-0.113638,0.166245,-0.010154,0.173221,0.305905,-0.297309,-0.236135,0.449329,0.076401,-0.224364,0.763469,0.733639,0.179483,-0.254069,-0.344867,0.117845,0.152583,0.193283,0.631477,-0.267557,-0.225821,0.045150,-0.239710,-0.266605,-0.341463,-0.311868,-0.105997,0.862145,0.045330,0.378315,0.024978,0.931492,0.094464,-0.315646,-0.156941,0.199301,0.540212,0.511518,-0.005680,0.137731,-0.016485,-0.283803,-0.381120,-0.244645,0.063560,-0.002144,0.013816,-0.039190,0.450556,0.352089,0.190410,0.461566,-0.046395,0.043079,-0.291025,0.978210,0.547974,-0.134406,0.388537,0.076244,1.031092,0.599018,0.004112,-0.253666,0.513669,-0.115432,-0.307013,0.046090,0.071262,-0.569600,0.222312,0.094498,-0.209887,-0.036881,0.189839,-0.699382,-0.105876,-0.031363,0.064696,0.247528,-0.202377,-0.415925,-0.606814,-0.183735,0.243358,0.201248,-0.303290,0.101124,-0.389027,1.096388,-0.619382,-0.082064,0.349199,-0.469136,-0.250023,0.310143,0.455457,0.033448,-0.175327,-0.128046,0.523922,-0.410114,0.064779,-0.007232,0.671796,-0.399553,-0.232457,-0.627231,0.572043', '5403927', '30488584', '27199913', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26263428', '为什么猫都叫不来', '剧情', '光雄（风间俊介 饰）一心想要成为一名拳击手，为此付出了自己全部的精力和时间，希冀有朝一日能够获得世界冠军的荣耀。某日，光雄的哥哥（鹤野刚士 饰）将两只小猫托付给了光雄照顾，它们一只名叫小黑，另一只叫小叽。一心一意精进拳术的光雄从来就没有过照顾小动物的经验，所以刚开始的时候，他完全不能够适应生活里多了这样两个“小捣蛋鬼”。然而，随着时间的推移，再加上“猫咪学者”小梅（松冈茉优 饰）的帮助，光雄和小猫之间的关系越来越亲密起来。在一场比赛中，光雄意外受伤，这严重的伤势令他无法再继续他的拳击梦想，霎时间，光雄的人生失去了全部的希望和意义。©豆瓣', '风间俊介', '山本透', 7.5, 12364, 'tt4202960', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2267508677.jpg', 0.6, 3.7, 34.7, 42.9, 18.1, '-0.056407,0.179012,-0.683673,0.354568,0.066862,-0.432195,0.681525,-0.048151,-0.354610,-0.212172,-0.024898,0.585996,0.034026,0.164979,0.031023,-0.208820,-0.114427,-0.986214,-0.158535,0.142708,-0.450217,-0.409386,-0.247430,-0.148496,-0.263770,-0.492662,0.758487,-0.195176,0.034580,0.575863,0.063495,-0.063077,0.395038,0.243119,-0.278273,0.011105,0.197746,0.259930,-0.129045,0.241382,0.372216,-0.058784,-0.144364,0.409075,0.172492,0.230515,0.715134,-0.321025,-0.326853,-0.410030,0.052155,0.007720,-0.076406,0.097576,0.213514,0.162477,0.385195,0.162226,-0.207908,0.195155,0.090859,-0.166881,-0.838733,-0.092968,0.034682,0.287328,-0.474493,0.482028,-0.036387,-0.275229,0.137838,-0.248172,0.059257,0.402567,0.185564,0.227966,-0.510609,-0.026968,-0.212836,0.110601,0.863411,-0.207682,-0.113884,0.908723,-0.144218,-0.333109,-0.209222,-0.375624,-0.177724,-0.059681,0.205904,0.358476,-0.324551,0.298555,-0.588333,0.210917,-0.183372,-0.131250,-0.183962,-0.256047,0.084878,-0.031937,-0.093860,-0.729110,-0.242620,0.306159,0.262674,-0.492985,0.943177,-0.941235,0.181736,0.516114,0.397407,-0.167790,0.511408,0.086515,0.187919,-0.133501,0.152877,-0.059170,-0.264880,0.302063,0.434037,0.401572,-0.020021,-0.272827,-0.434501,0.452623', '1826173', '26809007', '35030151', '1937946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26263437', '神探驾到', '喜剧', '社会上甚有地位的裘氏一族正准备迎接一场盛大的订婚派对，一位不速之客贾探员（古天乐 饰）却突然到访，并带来少女张小娟一尸两命的自杀命案，划破了裘家欢乐的气氛。裘家上至老爷（曾志伟 饰）太太（毛舜筠 饰）少爷（林家栋 饰）小姐（吴千语 饰），下至管家（罗兰 饰）均表示从不认识张小娟，岂料贾探员竟凭着死者的一本日记和一张照片，将裘家众人的华丽皮囊一一扯下，揭示出每人都跟死者有着莫大的关连！一场华丽的世纪夜宴如期举行，一片欢乐下，这名探员的到访，会彻底影响裘家的世纪盛宴吗？电影改编自英国著名舞台剧《An Inspector Calls》。', '古天乐', '黄百鸣', 4.5, 15826, 'tt4296186', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2221880001.jpg', 29.7, 32.5, 26.7, 7.7, 3.5, '0.212837,0.114605,-0.151598,0.408194,0.189055,-0.195207,0.820431,0.264479,-0.239705,-0.372560,0.624141,0.697686,-0.501800,0.322649,0.552293,-0.112810,-0.255600,-0.460435,-0.180854,0.019758,-0.062693,-0.233362,-0.177140,0.072856,0.058272,-0.079451,0.173674,0.061575,-0.140709,0.584904,0.268238,0.230389,-0.244789,0.241817,0.003648,0.031405,-0.039618,0.150963,-0.409056,-0.148420,-0.028283,-0.227141,-0.043406,0.149153,-0.096507,0.255678,0.524432,-0.501148,0.115875,-0.097163,0.766917,0.143950,0.115827,0.224611,0.326895,0.100419,0.147410,0.277794,0.006605,-0.122583,0.295818,-0.185098,-0.407644,0.190890,0.333283,0.305720,-0.086788,0.498503,-0.091971,-0.041323,-0.088370,-0.221029,0.228777,0.076058,0.392883,0.171795,0.155331,0.199226,-0.352197,0.477799,0.521201,0.163148,0.187532,0.092901,-0.401553,-0.603105,-0.022610,-0.117256,-0.473209,0.073790,0.394076,-0.219382,0.376408,0.124159,-0.435834,-0.096819,-0.361144,-0.099187,0.058936,-0.120696,-0.023388,-0.806746,-0.196433,-0.191608,-0.107373,0.096085,0.430320,-0.024797,0.502699,-0.331230,0.229839,0.024906,0.001113,-0.083861,0.367341,0.059154,0.136002,-0.003804,-0.385455,-0.188875,0.039270,0.158293,-0.094368,0.276514,-0.279812,-0.047200,0.025652,0.221916', '10466639', '34961898', '1301686', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26263443', '恋爱中的城市', '爱情', '这是一个“人越来越多 ，世界却越来越小”的——小世界。佛罗伦萨、布拉格、巴黎、上海、北海道小樽，五座城市，五段不同的爱情故事在这个“小世界”中上演。浪漫的午夜巴黎上演了一段奇幻邂逅；神秘布拉格正经历一场忧伤的偶遇；美丽上海隐藏了一个关于美食与爱的秘密；北海道的唯美见证了一对新婚夫妇的蜜月之行；佛罗伦萨艳阳下的一场疯狂之旅也正拉开序幕……', '杨幂', '文牧野', 5.7, 37588, 'tt4819604', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2260730932.jpg', 8.8, 25, 46.4, 13.9, 5.9, '0.150312,0.461110,-0.785815,0.652907,0.223578,0.124508,1.014656,-0.108861,-0.129081,0.213411,0.356837,0.896824,-0.602995,0.683122,0.474492,-0.111438,-0.320582,-0.709129,0.014274,-0.346220,-0.089023,-0.347231,-0.749810,0.439248,0.099503,0.074630,0.586131,0.667425,-0.124282,0.281548,0.217515,-0.225003,-0.350275,0.265472,-0.373045,-0.276165,0.295534,0.467929,-0.485529,0.013922,-0.044756,-0.020706,-0.316029,-0.080135,-0.188380,-0.099269,1.013590,-0.435678,-0.075363,-0.572364,0.489514,0.009730,-0.383721,-0.109252,0.042965,0.013224,0.196928,-0.105782,-0.106964,-0.165213,-0.020212,-0.472147,-0.496176,0.466013,0.218574,0.188441,-0.035367,0.456840,0.244334,-0.090167,0.243607,-0.249983,0.152013,0.390971,0.753556,0.606857,0.039128,0.056039,-0.051230,0.306269,0.905213,0.138274,-0.304670,0.687345,-0.026837,-0.303741,0.137586,-0.066226,-0.478363,0.269521,0.299235,-0.537991,-0.133006,0.545869,-1.179626,0.474785,-0.352118,-0.436551,0.099775,-0.299227,-0.244772,-0.982380,-0.253071,-0.349330,0.039471,0.363342,0.474270,-0.006377,0.796955,-0.457906,0.333014,0.687000,0.177041,-0.081012,0.657988,0.321270,0.128474,-0.146246,0.029449,0.443470,-0.545918,0.135536,-0.348155,0.602862,-0.362262,0.093484,-0.809268,0.767452', '35161768', '10466639', '26290398', '2357162');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26263504', '我很好，谢谢，我爱你', '喜剧', '普朗（波莉雀娅·彭娜妮可 Preechaya Pongthananikorn 饰）是一名英语老师，她的一名学生想和男友吉姆（Sunny Suwanmethanon 饰）分手，于是用英文录了一段分手宣言，拜托普朗播放给吉姆听。哪想到伤心欲绝的吉姆竟然将过错怪罪到了普朗的头上，他觉得正是因为普朗教了女友英语，女友才会弃他而去。时隔不久，吉姆再度找到了普朗，这一次，他竟然请求普朗教他英语，因为他想要出国挽回女友，于是，两人成为了师生。在相处的过程中，普朗发现了吉姆的善良和坚强，对他渐渐产生了好感，吉姆亦然，与此同时，一位名叫普雷克（Popetorn Soonthornyanakij 饰）的富有商人亦在热烈的追求着普朗。夹在两个男人中间，普朗会做出怎样的选择？©豆瓣', '桑尼·苏瓦美塔农', '梅兹·塔拉', 7.2, 10367, 'tt4222718', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2254428578.jpg', 0.9, 5.6, 40, 39.5, 14, '0.333856,0.019333,-0.639568,0.719763,-0.399987,-0.581246,0.751870,0.194757,-0.297968,-0.252663,0.167273,0.649475,-0.279715,0.145759,0.312176,-0.069535,-0.213790,-0.769835,0.291607,0.008746,-0.141367,-0.629021,-0.019962,-0.024232,-0.004243,-0.365604,0.320509,-0.174787,-0.264576,0.497558,0.481673,0.334484,0.094049,0.478818,0.016052,0.060924,0.162719,0.061635,-0.176322,0.280394,0.241601,-0.269607,-0.123439,0.192107,-0.220845,0.459296,0.526422,-0.044848,-0.244101,0.222764,0.448675,-0.281535,0.165727,0.151897,0.366895,0.102396,0.234385,0.175091,-0.302677,-0.063146,0.153992,0.012183,-0.632313,0.167744,-0.226938,0.160281,-0.747167,0.620237,-0.162943,-0.279637,0.179998,-0.440718,0.162550,0.243242,0.196564,0.429536,-0.175593,-0.008518,-0.228794,0.045407,0.525945,-0.021542,-0.034898,0.376170,0.111409,-0.425850,0.080362,0.067604,-0.512935,-0.034799,0.243145,-0.075820,-0.161933,-0.076324,-0.454742,-0.206106,-0.279895,-0.017615,0.157062,-0.527284,-0.022939,-0.280135,0.003550,-0.115428,-0.379475,-0.136169,-0.000833,-0.210408,0.859950,-0.984346,0.209121,0.562315,0.325173,-0.399840,0.553881,0.205392,-0.081260,-0.190639,0.008381,0.198777,0.010990,0.047491,0.300931,0.470224,0.146044,-0.151211,-0.276877,0.594128', '1292219', '21360412', '35030151', '1298880');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26263919', '谋杀似水年华', '爱情', '田小麦（杨颖 饰）和盛赞（张超 饰）相恋多年，即将携手步入婚姻的殿堂，然而，就在这个节骨眼上，田小麦身为刑警的父亲在工作中不幸因故身亡，悲伤之余，田小麦在父亲的遗物之中发现了一本探案笔记，上面记载了十年前的一桩悬案，同时也让田小麦回想起了自己的初恋秋收（阮经天 饰）。某日，田小麦从好友处得知了一间贩卖世间一切东西的网店，在店中，田小麦买了一条紫色丝巾。之后，诡异的事情接二连三的发生，种种蛛丝马迹均显示，如今下落不明的秋收，和父亲笔记里那宗疑案有着千丝万缕的关联。就这样，田小麦一遍调查着案件，一遍寻找着秋收，试图找到隐藏在乱象之后的真相。©豆瓣', '杨颖', '陈果', 3.9, 18244, 'tt5541542', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2318807517.jpg', 42.8, 31.6, 17, 4.8, 3.8, '-0.168514,0.133976,-0.737375,0.775275,0.064441,-0.423518,0.740342,-0.025424,-0.688624,-0.469673,-0.246575,0.448495,-0.331508,0.670051,0.192357,0.051092,-0.224595,-0.818042,-0.022470,-0.237798,-0.674058,-0.406066,-0.461511,-0.139395,-0.218397,-0.020075,0.252568,0.743313,-0.218782,0.244596,0.242739,0.207596,-0.665041,0.253024,0.135424,0.153349,0.050313,0.480232,-0.402570,-0.086041,0.159168,-0.578898,-0.171665,0.065508,0.210420,0.534697,0.915804,-0.083798,-0.473329,0.046249,0.490262,0.336760,-0.118402,0.213276,0.492874,0.349690,0.046260,0.358898,-0.587720,-0.101615,0.275537,0.058634,-0.551076,-0.430744,-0.050891,0.456609,-0.771515,0.318615,-0.137186,0.203018,0.022461,-0.646212,0.447176,0.497252,0.231794,0.387539,0.042392,-0.106234,-0.574614,0.521549,0.288116,0.085558,0.234691,0.201855,-0.066865,-0.324430,-0.197871,0.557126,-0.405018,0.174676,0.441532,0.177631,-0.158879,0.361335,-0.610526,-0.137149,-0.014937,-0.029674,0.153660,0.044677,-0.323180,-0.446928,-0.111960,-0.285933,-0.729555,0.240496,0.142676,-0.342757,0.461332,-0.493612,0.253089,0.091614,-0.066896,-0.319469,0.336629,-0.127514,0.388016,-0.334078,0.076347,0.110512,0.118212,0.317656,0.525982,0.348429,-0.172580,-0.272791,-0.496861,0.658115', '1805685', '6875615', '27075198', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26264454', '声之形', '剧情', '西宫硝子（早见沙织 饰）生来患有听觉障碍，要依靠助听器和外界交流，口语发音也因此格外的古怪。小学时，硝子转入了一所新的学校，特殊的生理缺陷让她成为了班上引人注目的独特存在，她因此收获了坚实的友情，却也遭到了以男生石田将也（入野自由 配音）为首的小团体的孤立和排挤。随着时 间的推移，无心或有意的恶作剧渐渐升级，最终演变成为了无法挽回的伤害，硝子永远的消失在了众人的眼前。排挤硝子的事情曝光后，将也成为了下一个被欺负的对象，孤独痛苦的他终于理解了硝子的隐忍和温柔，只是他再也没有机会跟硝子道歉了。一次偶然中，将也同硝子重逢了，命运的齿轮重新开始了转动。©豆瓣', '入野自由', '山田尚子', 6.8, 148028, 'tt5323662', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2497136132.jpg', 3.7, 12.1, 38.9, 30.8, 14.6, '0.459771,0.255311,-0.542399,0.637063,-0.258888,-0.273667,0.838027,0.165820,-0.476600,0.074891,0.008905,0.909584,-0.284910,0.279592,0.037049,-0.041660,-0.008761,-0.922397,0.037136,-0.273624,-0.441244,-0.572035,-0.176797,-0.198125,-0.251806,-0.403528,0.712952,0.152836,-0.527068,0.499965,0.149382,0.114556,0.133911,0.670768,-0.025513,-0.111930,-0.007285,0.059358,0.228138,0.044896,-0.040062,-0.554573,0.071842,0.469980,-0.254602,0.561940,0.800105,-0.284154,-0.176052,-0.191532,0.485003,-0.217429,-0.107898,0.341640,0.256538,0.112251,0.004180,0.287992,-0.423819,0.026513,-0.032559,0.257005,-0.867593,-0.064747,0.150800,-0.013976,-0.580620,0.748365,0.262884,-0.355544,0.150521,-0.183490,0.313071,0.396843,0.404243,0.321888,-0.572448,0.087136,-0.172452,0.216437,0.631776,0.042596,-0.643323,0.429043,-0.301028,-0.440110,-0.148436,-0.276918,-0.294750,-0.215053,0.403964,0.550995,-0.311617,0.205361,-0.720906,-0.054025,-0.099682,-0.114377,-0.217602,-0.612489,0.044373,-0.535298,-0.197235,-0.517517,-0.455367,0.098062,-0.045912,-0.292470,0.896368,-0.916636,0.242995,0.713275,0.444497,-0.394429,0.678509,0.101477,0.171779,-0.047545,0.089556,0.141925,-0.180950,0.548956,0.255882,0.609577,-0.015114,0.017909,-0.445176,0.676646', '30162520', '3811356', '2053515', '26809007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26266072', '谍影重重5', '动作', '后斯诺登时代，中情局系统被黑客入侵， 多项特工计划可能泄露。与此同时，中情局还发现了伯恩和好搭档尼基·帕森斯的踪迹。年轻的网络专家海瑟·李自告奋勇追踪伯恩，而伯恩也在寻找着关于自己身世的惊天黑幕。中情局高官杜威是知晓一切幕后秘密的人，他、海瑟·李和伯恩之间的角力让故事充满悬念，不到最后一刻，就无法了解真正的结局。', '马特·达蒙', '保罗·格林格拉斯', 7.5, 187432, 'tt4196776', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2379032162.jpg', 0.9, 3.8, 32.5, 44.8, 18, '0.149129,0.008063,-0.879078,0.521690,-0.125315,0.016179,0.395341,-0.154111,-0.924011,-0.220801,-0.104410,0.522925,-0.203329,-0.060638,0.259311,-0.018120,-0.448795,-0.875322,-0.077946,-0.449413,-0.239382,-0.878099,-0.530250,-0.394492,0.101520,-0.336601,0.568038,0.275551,-0.650474,0.126445,0.314977,0.485747,-0.340992,0.583760,0.175911,0.057382,0.756821,-0.247462,-0.335942,0.148070,0.212047,-0.287717,-0.243248,0.381205,-0.115845,0.400602,0.347326,-0.199148,0.060012,0.062651,0.159892,-0.318012,0.155053,-0.042246,0.686466,-0.225110,0.231211,0.399975,0.000598,-0.524085,0.040856,0.122349,-0.839563,0.105111,0.012860,0.535018,-0.450313,-0.028377,-0.608150,0.057257,0.035049,-0.524829,0.444662,0.335329,0.668097,-0.051563,0.121542,-0.045388,-0.366502,0.149955,0.565194,0.119944,-0.410079,0.133406,-0.007302,-0.496578,-0.446825,-0.190380,-0.439561,0.060221,0.691436,0.224012,-0.036448,0.462650,-0.067537,-0.097843,-0.286158,-0.369647,-0.257574,-0.457931,0.010349,-0.667805,-0.586297,-0.159018,-0.369641,0.020814,0.039154,-0.154170,0.583796,-0.861022,0.449399,0.647505,-0.057157,-0.370869,0.629472,0.039622,0.199602,-0.478196,-0.038009,0.186298,0.298312,0.209338,0.135320,0.229174,0.167563,-0.395204,-0.090186,0.327358', '1307442', '1293434', '1418190', '1308655');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26266085', '三个老枪手', '喜剧', '故事讲述每天到银行确认有没有老人金进帐的3位老人，决定受够这一切，放手一搏、携手抢银行，但他们面临到一个关键问题，他们不太会用枪……', '迈克尔·凯恩', '扎克·布拉夫', 7.8, 80413, 'tt2568862', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2493595992.jpg', 0.2, 1.5, 26.2, 51.5, 20.7, '0.015626,-0.178825,-0.781066,0.151959,-0.452105,-0.349081,0.479397,-0.186426,-0.210808,-0.700073,0.406047,0.348722,0.096163,0.285433,0.575073,-0.216129,-0.266517,-0.065944,0.333169,-0.043407,-0.791537,-0.467748,0.364864,-0.408053,-0.428931,0.441106,0.422574,0.197889,0.106178,-0.040152,0.051349,0.245081,-0.129385,0.221465,-0.110721,0.321393,0.005806,0.198674,-0.641410,0.395866,0.213279,0.209385,-0.592994,0.262181,0.123320,0.257351,0.473403,-0.200484,-0.483813,0.781506,0.207460,-0.582204,-0.244549,0.074738,0.412927,0.172382,0.063910,0.117957,0.010374,-0.329075,-0.398132,-0.273244,-0.321762,-0.194785,0.083233,0.277329,-0.477155,-0.146176,0.039270,0.350955,-0.115950,-0.560966,-0.319960,0.314562,0.399535,0.186123,-0.156004,-0.297859,-0.834477,0.108821,0.997874,0.117934,-0.276759,0.276010,0.369054,-0.146791,-0.479379,-0.282867,-0.233919,0.237376,0.098786,-0.181388,-0.436728,-0.151832,-0.265173,-0.299558,0.250523,-0.237178,0.328476,-0.424943,0.067963,-0.575593,-0.287996,-0.261640,-0.112921,0.412333,0.456601,-0.281183,0.680722,-0.363107,-0.089151,0.594747,0.004804,-0.711982,0.508063,-0.027412,0.248203,-0.650862,-0.011783,-0.033161,0.479084,0.068633,0.049363,-0.047683,-0.157420,0.278204,-0.650053,0.039871', '1306530', '1299182', '35287558', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26266892', '红鳉鱼', '剧情', '1984年，受立川派落语宗师立川谈志（北野武 饰）的感染，平凡高中生佐佐木信行（二宫和也 饰）决定终止学业，拜入立川名下成为一名落语表演演员。作为落语界的异端，立川特立独行的风格让徒弟们也吃不消。他破天荒向徒弟收取学费，平日里支使他们干着各种杂务，一旦不满意就破口大骂。有的人因吃不消而选择离开，有的则以理念不合拜入其他师父门下。得名谈春的信行为了梦想甚至和父母闹僵，好不容易令师父青眼相看又错失良机，被发配到筑地的鱼市修炼。在此期间，天才师弟（滨田岳 饰）脱颖而出，两位师兄谈谈（北村有起哉 饰）和关西（宫川大辅 饰）也各自经历着内心的煎熬。梦想当前，谈春他们全力奔跑……本片根据落语名家立川谈志的人生事迹改编。©豆瓣', '二宫和也', '高畑秀太', 9, 43187, 'tt4396044', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2315734512.jpg', 0.1, 0.3, 6.7, 35.9, 56.9, '0.040600,-0.256501,-0.169778,0.546422,-0.067792,-0.266637,0.115442,0.212014,-0.414672,-0.509242,0.255869,0.655074,0.014794,0.157342,0.342078,-0.198627,-0.082603,-0.559943,-0.113204,-0.147627,0.071629,-0.368025,0.102941,-0.161968,-0.284545,-0.353596,0.634796,0.007190,-0.386606,0.498117,0.326138,0.352074,0.080424,-0.030703,0.003545,0.100815,-0.024382,0.272636,-0.154930,0.019065,-0.281389,-0.197960,-0.169806,-0.075539,0.148498,0.299716,0.490889,-0.022886,-0.245185,-0.141795,0.211051,-0.185579,-0.049113,0.219735,0.256289,0.217987,0.232614,0.356851,-0.172024,0.236693,-0.095003,0.000759,-0.745033,-0.010474,0.476142,-0.044058,-0.448770,0.369399,-0.101168,-0.164532,-0.048089,-0.334150,-0.028242,0.215988,0.356452,0.259679,-0.219668,0.116661,-0.191091,0.332098,0.725717,-0.000461,0.104600,-0.008037,-0.061121,-0.347110,0.086847,-0.612131,-0.394701,-0.078547,-0.171347,0.164682,0.125342,0.110288,-0.191311,-0.015299,0.027943,-0.108873,0.136541,-0.280803,0.316603,-0.517649,0.060189,-0.300594,-0.360211,-0.175799,0.283485,-0.274699,1.004798,-0.575649,0.047463,0.274078,0.341370,-0.542201,0.680970,0.061500,0.095788,-0.220216,-0.197833,0.015345,-0.025676,0.341735,0.111988,0.352891,-0.042559,-0.181808,-0.249130,0.090704', '27602116', '24284209', '3811356', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26266893', '流浪地球', '科幻', '近未来，科学家们发现太阳急速衰老膨胀，短时间内包括地球在内的整个太阳系都将被太阳所吞没。为了自救，人类提出一个名为“流浪地球”的大胆计划，即倾全球之力在地球表面建造上万座发动机和转向发动机，推动地球离开太阳系，用2500年的时间奔往另外一个栖息之地。中国航天员刘培强（吴京 饰）在儿子刘启四岁那年前往国际空间站，和国际同侪肩负起领航者的重任。转眼刘启（屈楚萧 饰）长大，他带着妹妹朵朵（赵今麦 饰）偷偷跑到地表，偷开外公韩子昂（吴孟达 饰）的运输车，结果不仅遭到逮捕，还遭遇了全球发动机停摆的事件。为了修好发动机，阻止地球坠入木星，全球开始展开饱和式营救，连刘启他们的车也被强征加入。在与时间赛跑的过程中，无数的人前仆后继，奋不顾身，只为延续百代子孙生存的希望……本片根据刘慈欣的同名小说改编。©豆瓣', '吴京', '郭帆', 7.9, 1791528, 'tt7605074', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2545472803.jpg', 2.7, 4.8, 21.4, 36.3, 34.9, '-0.243074,0.283005,-0.879660,0.634155,0.071416,0.062704,0.377205,-0.161791,-0.208437,-0.156657,0.052593,0.643550,-0.204802,0.048632,0.151841,-0.007989,-0.226723,-0.471094,-0.184734,-0.029834,-0.377012,-0.320427,-0.131112,-0.217991,-0.113444,-0.239154,0.677213,0.066089,-0.120818,0.404371,-0.022173,0.031152,-0.305083,0.384418,-0.197732,0.054714,-0.043332,-0.118117,-0.264680,0.408869,-0.299035,-0.149927,0.199574,-0.176247,-0.244336,0.190680,0.713160,-0.135408,0.107168,-0.390106,0.358382,-0.407597,-0.023706,0.008240,0.482389,0.242524,-0.197799,0.123098,-0.128454,0.267432,0.080656,-0.063410,-0.534925,-0.127101,0.050547,-0.241977,-0.619884,0.237433,-0.084703,-0.145126,0.026580,-0.316102,0.234536,0.427904,0.252858,0.508710,-0.393496,0.313399,-0.525857,0.089485,0.570769,-0.219295,-0.481267,0.243070,0.211781,-0.282501,-0.105843,-0.116959,-0.170800,-0.263165,0.222026,-0.089522,0.009052,0.505664,-0.639013,0.171984,-0.216531,-0.637131,0.155663,-0.122741,-0.094307,-0.638320,0.097948,-0.141507,0.035447,0.182960,0.006735,-0.316463,0.735515,-0.328689,0.249150,0.370030,0.489734,-0.546277,0.610064,-0.168559,0.250592,-0.241956,-0.016152,0.399119,-0.028277,0.587938,-0.084347,0.111765,-0.160929,-0.076134,-0.362344,0.224717', '1294917', '2159244', '2042279', '1298405');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26266919', '最好的我们', '剧情', '耿耿（何蓝逗 饰）是一名技艺十分精湛的女摄影师，在学生时代，她有过一段无疾而终的青涩恋情，这段恋情至今依然深深的影响着耿耿。时间转回数年前，彼时的耿耿还是身穿校服的懵懂少女，在老师的安排下，她和学校里成绩最好的帅气男孩余淮（陈飞宇 饰）成为了同桌，他们一个是学渣，一个是学霸，互补的性格令两人之间很快就碰撞出了火花。随着时间的推移，耿耿和余淮的感情从最初的友情一步一步的成长，两人许下了美好的约定，约好了考入同一所城市的同一间大学。然而，在约定之日的那一天到来之时，余淮竟然人间蒸发了，从此音信全无。©豆瓣', '陈飞宇', '章笛沙', 5.2, 109700, 'tt10195976', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2557157554.jpg', 15.1, 32.8, 36, 11.8, 4.3, '0.277483,0.025680,-0.648309,0.621201,-0.169899,-0.507093,0.683502,-0.028385,-0.467548,-0.331910,0.112552,0.587631,-0.636915,0.598112,0.380079,-0.312423,-0.054142,-0.948825,-0.180818,-0.549867,-0.341336,-0.311554,-0.279666,0.348111,-0.205119,-0.319629,0.782966,0.051856,-0.044977,0.685976,0.178386,-0.192089,-0.105894,0.446310,-0.254383,-0.160122,0.189041,0.285718,-0.294575,-0.034312,0.141322,-0.324399,-0.034968,-0.119618,-0.169262,0.287474,0.833727,-0.169396,-0.200576,0.042635,0.606771,-0.095010,-0.245522,0.113033,0.601125,0.000009,0.142713,0.244853,-0.070050,0.008490,-0.207389,-0.142390,-0.478739,0.064123,0.022094,0.126854,-0.682302,0.934518,0.135945,-0.206975,0.234360,-0.541806,-0.028639,0.411463,0.291506,0.432745,-0.298145,-0.027534,-0.292678,0.369710,0.807910,0.271017,-0.522244,0.556588,-0.204704,-0.450164,-0.255951,0.207197,-0.537492,-0.084941,0.271530,0.075066,-0.007140,0.289949,-0.507821,0.100766,-0.034237,0.201722,0.157485,-0.609025,-0.170567,-0.520624,-0.076551,-0.746565,-0.507888,0.242135,-0.041371,-0.206548,0.986723,-0.972187,0.046387,0.380965,0.228733,-0.141839,0.807515,0.278344,0.293551,-0.175512,0.117309,0.203956,-0.280760,0.273931,0.027395,0.767427,-0.166856,-0.009349,-0.615668,0.616933', '1826173', '1292219', '26354526', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26268602', '以寡敌众', '剧情', '大盗哈里（连姆·尼森 Liam Neeson 饰）和其同伴在一场抢劫行动中不幸身亡，赃款下落不明。他的妻子维罗妮卡（维奥拉·戴维斯 Viola Davis 饰）不仅要承受丧夫之痛，还要警惕来自当地的黑帮兄弟贾马尔（布莱恩·泰里·亨利 Brian Tyree Henry 饰）和杰特米（丹尼尔·卡卢亚 Daniel Kaluuya 饰）的死亡威胁，他们想要得到那笔赃款。实际上，维罗妮卡拥有一项秘密武器，那就是哈里的秘密笔记，他将自己的所有抢劫计划非常详细的记录了下来，其中还包括他的下一个行动计划。维罗妮卡藏起了笔记，找到了哈里同伴的妻子琳达（米歇尔·罗德里格兹 Michelle Rodriguez 饰）和爱丽丝（伊丽莎白·德比齐 Elizabeth Debicki 饰），三个女人决定靠着笔记为自己搞一大笔钱。©豆瓣', '维奥拉·戴维斯', '史蒂夫·麦奎因', 6.1, 11661, 'tt4218572', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2621772298.jpg', 1.6, 18.1, 59.9, 17.2, 3.2, '0.087101,-0.055567,-0.411652,0.713659,-0.172266,-0.333170,0.682798,0.014619,-0.249783,-0.412757,0.207469,0.748358,-0.105706,0.001569,0.181220,0.226231,-0.580721,-0.731842,0.024533,-0.042395,-0.369046,-0.703263,-0.431323,-0.302393,-0.175059,-0.175819,0.331052,-0.101145,-0.004436,0.122873,0.414734,0.461388,-0.128681,0.037799,-0.052415,0.157904,0.282135,-0.397581,-0.266405,0.169473,0.130141,-0.013230,0.082996,0.323288,0.319636,0.262673,0.630509,-0.220614,0.240054,0.004461,0.009700,-0.172414,0.017700,0.223153,0.191986,-0.036471,0.236322,0.296252,-0.184862,-0.060567,0.436706,-0.095254,-0.901524,-0.180814,0.055084,0.292531,-0.698334,0.468644,-0.571987,0.371939,0.131128,-0.277739,-0.013089,0.290503,0.105582,0.134293,-0.040456,-0.294873,-0.440370,0.198316,0.159506,-0.160930,0.221561,0.208813,-0.196264,-0.540936,-0.164264,0.112340,-0.360057,0.134127,0.677574,-0.100360,0.160031,0.261923,-0.671965,-0.258709,-0.416131,-0.174898,-0.156174,-0.462250,-0.036969,-0.652717,-0.197379,-0.228358,-0.409369,0.085944,0.129550,-0.189481,0.641113,-0.409037,0.036986,0.577936,0.009460,-0.201354,0.005068,0.130585,0.346600,-0.232771,-0.254948,0.059907,0.377729,0.233863,0.326983,0.165538,0.180758,-0.114904,-0.149570,0.521725', '1308585', '1307442', '1422957', '25