INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26269510', '陪安东尼度过漫长岁月', '剧情', '影片是关于一个男生从20岁到23岁、从大学到工作、从国内到国外的生活片段及内心感悟。安东尼（刘畅 饰）是一个不特别、不会说很酷话的普通男生，在20岁的时候从大连留学墨尔本，并遇到了小萱（唐艺昕 饰）、家明（白举纲 饰）、小黑（宋芸桦 饰）、Pierre（布鲁斯 饰）等一众好友。在这漫长岁月里，发生了一系列或浪漫、或甜蜜、或可笑、或感人的故事。而他同时也记挂着远在日本的小樱（白百何 饰），时隔两年后在东京相见的他们，会发生怎样的故事……影片根据安东尼的同名畅销作品改编。', '刘畅', '秦小珍', 6.2, 93276, 'tt4892682', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2283607664.jpg', 6.6, 18.7, 43.8, 21, 9.9, '0.191470,-0.064558,-0.866068,0.510973,0.071015,0.029113,0.904485,-0.064213,-0.521222,-0.162175,0.284334,0.754058,-0.427282,0.504151,0.195337,-0.037796,-0.311907,-0.681083,0.302060,-0.446168,-0.409216,-0.317107,-0.088330,-0.017484,-0.191290,-0.421781,0.429171,0.022521,-0.221938,0.448676,0.200066,0.251811,-0.178497,0.207535,-0.330637,0.058538,0.171105,0.530887,0.057068,0.122611,0.106645,-0.433147,-0.413090,-0.322519,0.021060,0.368555,1.004996,-0.066762,-0.248281,0.494609,0.572949,-0.104600,-0.199076,-0.126297,0.188985,-0.055668,0.244572,0.223275,-0.209101,0.322330,-0.095176,-0.143820,-0.525384,0.201687,-0.101520,0.433467,-0.502058,0.670131,-0.264577,-0.000867,0.478406,-0.440407,-0.027569,0.381846,0.141842,0.481257,-0.080385,0.061083,-0.371670,0.591992,0.749823,0.114549,-0.495484,0.685382,-0.090366,-0.477177,-0.289507,-0.013365,-0.535533,0.152150,0.261661,-0.285851,-0.226478,0.185749,-0.554249,-0.007942,0.151832,-0.104690,0.335500,-0.076269,-0.263054,-0.610013,-0.111126,-0.807842,-0.303581,-0.062325,0.251088,-0.190836,1.135054,-0.884778,0.069520,0.378864,0.104455,-0.432564,0.560458,-0.057716,-0.075748,-0.017572,0.108103,0.289143,-0.102939,0.064405,-0.033615,0.553253,0.081690,-0.425888,-0.690904,0.328485', '3811356', '24839498', '25922902', '26354526');
