INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26270502', '绣春刀II：修罗战场', '剧情', '明天启七年，北镇抚司锦衣卫沈炼（张震 饰）在一次扫除乱党任务中，为救画师北斋（杨幂 饰），将同僚凌云铠（武强 饰）灭口。此后一方面要摆脱来自陆文昭（张译 饰）、裴纶（雷佳音 饰）的质疑与调查，一方面又在神秘女子的要挟下放火烧了锦衣卫经历司。裹挟在乱世，沈炼与北斋情陷其中，却越陷越深。而在这一切的背后，巨大阴谋正暗中布局。众生如蝼蚁囿于修罗场，逆鳞之战，一触即发……', '张震', '路阳', 7.2, 389526, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2561713454.jpg', 0.9, 5.1, 38, 44.9, 11.2, '-0.074680,0.121884,-0.413921,0.412344,0.011457,0.171771,0.659605,0.251028,-0.628954,-0.369295,0.346106,0.349788,-0.006606,-0.189220,0.411916,-0.161589,-0.182442,-0.642000,-0.165766,-0.276383,-0.135274,-0.488889,-0.268512,-0.132718,-0.212276,-0.210970,0.536254,0.462456,-0.081238,0.317591,0.444571,0.275512,-0.607944,0.285110,-0.028720,-0.220271,-0.070438,0.115366,-0.310518,0.007735,0.065131,-0.647472,-0.606732,0.348683,-0.196654,0.214234,0.541463,-0.579145,0.129174,-0.192490,0.131953,-0.360637,-0.016802,-0.050257,0.160950,0.169242,0.029443,0.536570,-0.368410,0.216615,0.214657,-0.107459,-0.545451,-0.257607,0.406827,0.101713,-0.444796,0.366797,-0.034101,0.209958,0.034203,-0.038066,0.088301,0.236966,0.371190,0.265828,-0.071349,-0.158044,-0.540355,0.313788,0.566637,0.076856,0.112286,-0.324352,0.210036,-0.074768,-0.237169,-0.120422,-0.250940,-0.135480,0.292496,-0.129849,-0.014743,0.276804,-0.483180,-0.072099,-0.363113,0.354573,-0.256310,-0.406238,-0.180693,-0.403121,-0.186533,-0.156731,0.004986,0.242503,0.394763,-0.219165,0.227274,-0.750121,0.143044,0.394739,0.111276,-0.508874,0.196732,0.258735,0.107772,-0.338650,-0.072415,-0.263744,0.376202,0.404367,0.174160,0.157821,-0.154987,-0.174324,-0.405545,0.120271', '26348798', '1301022', '1293265', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26270517', '愚人节', '喜剧', '繁华大都会日本东京，迎来了一年一度的愚人节。有交流障碍的医院清洁工新田步（户田惠梨香 饰）鼓起勇气打电话给外科医生牧野亘（松坂桃李 饰），宣布自己已经怀孕的事实。谁知对方矢口否认孩子和自己相关，更当成一个恶劣的玩笑，之后继续招蜂引蝶。新田一气之下，杀到了牧野所在的意大利餐厅，结果引发了难以收场的大混乱。那边厢，自称皇族的樱小路夫妇（里见浩太朗 & 富司纯子 饰）在出租车司机（泷藤贤一 饰）的带领下游览东京，度过他们难得的二人时光。另一头的街上，黑道大哥宇田川勇司（寺岛进 饰）带着小弟（高桥努 饰）劫走了小学生江藤理香（浜辺美波 饰），却并不着急索要赎金。警察局一方，小野刑警（高岛政伸 饰）则与神秘的占卜婆婆（りりィ 饰）相周旋。短暂的一天里，许多人的命运发生翻天覆地的改变……©豆瓣', '户田惠梨香', '石川淳一', 7.8, 34598, 'tt4231508', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2233235589.jpg', 0.5, 2.4, 25.6, 48.4, 23.1, '0.211638,0.107255,-0.436636,0.345002,0.050788,-0.153031,0.546015,0.244555,-0.302858,-0.242124,0.207152,0.540223,-0.145650,0.164985,0.285766,0.178626,-0.374074,-0.575591,0.159903,-0.020573,-0.159725,-0.303249,-0.106709,-0.070964,0.022183,0.227392,0.199869,0.194836,-0.119728,0.639020,0.233866,0.132068,-0.200065,0.228531,0.038796,0.297680,0.274979,0.142083,-0.150174,0.234087,-0.252986,-0.286298,-0.184665,0.262546,0.174662,0.358241,0.536674,-0.112780,-0.119216,-0.111585,0.249838,-0.159357,-0.231479,0.174181,0.407879,-0.064990,0.174001,0.091379,-0.458472,-0.115354,0.011678,0.111444,-0.227958,0.212879,0.098330,0.135007,-0.368846,0.511746,0.030641,-0.228112,0.208546,-0.211950,0.043208,0.217147,0.306308,0.115700,-0.126254,-0.035777,-0.277112,0.147139,0.623670,0.016403,0.050461,0.216953,-0.061180,-0.141732,-0.135614,-0.210942,-0.349512,-0.152100,0.292259,-0.092299,-0.113442,-0.017132,-0.360925,-0.080323,-0.206179,-0.013961,0.026432,-0.099828,-0.090815,-0.714243,0.265176,-0.585093,-0.380286,0.256067,0.274207,0.151482,0.606129,-0.556126,0.039542,0.385198,0.260193,-0.285576,0.403665,0.126527,-0.039181,-0.207654,0.034693,0.069670,0.077148,0.527733,0.087349,0.421926,-0.257065,-0.200022,-0.348253,0.093929', '3811356', '26365262', '3139191', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26271094', '谎言西西里', '爱情', '影片讲述了韩国男孩俊浩（李准基 饰）以隐形方式默默守护心爱女友小悠（周冬雨 饰），并帮助其重启人生和爱情的故事。此次跨国“牵手”不仅发生在摩登都市上海，足迹还将远至充满美丽传说的意大利西西里，上演一场跨越国界和地域的动人恋情。', '李准基', '林育贤', 5.2, 16764, 'tt6234666', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2367900345.jpg', 16.4, 31, 34.8, 10.9, 6.9, '-0.164211,0.207585,-0.602715,0.757756,0.375419,0.101875,0.484932,0.081720,-0.083763,-0.136636,-0.076239,0.531527,-0.353629,0.151534,0.380575,-0.233422,-0.416915,-0.618209,-0.000446,0.236949,0.002144,-0.187750,-0.095013,-0.024882,-0.121647,-0.374303,0.624138,0.176598,-0.376855,0.294014,0.412119,0.266123,-0.771878,0.092908,-0.086443,-0.034841,0.175526,0.503597,-0.909705,0.167011,-0.158298,-0.111724,0.007732,0.165810,-0.385646,-0.250397,0.829143,-0.134714,-0.043634,0.125509,0.525562,-0.343478,-0.047286,-0.117833,0.178030,-0.050850,0.002518,0.301403,0.050977,-0.093819,0.082193,-0.388484,-0.621208,-0.099293,0.228252,-0.028811,0.012660,0.378748,0.070419,0.135342,0.393399,-0.392883,0.157305,0.127486,0.584632,0.321837,-0.138080,0.243198,-0.319689,0.540044,0.520677,0.266016,-0.229645,0.529246,-0.178264,-0.374484,-0.258480,0.029736,-0.564050,0.416126,0.242628,-0.240407,0.048227,0.298341,-0.840252,-0.116134,-0.269087,-0.257121,0.447120,-0.357926,0.080683,-0.945149,-0.065329,-0.695459,-0.142602,-0.074841,0.220133,-0.295836,0.598481,-0.345977,0.280164,0.588912,0.089343,-0.664613,0.564431,0.232228,0.284863,-0.215930,-0.028071,0.748613,-0.193529,-0.008882,-0.347181,0.142759,-0.293627,0.446565,-0.531512,0.466956', '5403927', '22265121', '30229667', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26272363', '卡贾基', '战争', '2006年9月，帕拉斯一个3人组侦查小队从他们的前哨站出发，路上俯瞰着阿富汗南部的卡贾基水库，他们将前去参与打击塔利班基地组织。当他们穿越一个干涸的河床时，其中一个人不幸踩中了地雷，这些地雷其实是在约25年前俄罗斯占领时期留下的。他的战友冲到他的身边，结果却发现他们被数量不明的地雷包围了，他们迈出的每一步都有可能造成重伤甚至死亡。', 'Mark Stanley', 'Paul Katis', 7.3, 5444, 'tt3622120', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2247926864.jpg', 0.8, 4.7, 37.3, 43.7, 13.5, '0.576895,-0.052497,-0.774055,0.440549,0.013866,0.155808,0.849229,-0.313368,-0.300107,0.175389,0.406263,0.416004,-0.065630,-0.026734,0.189827,-0.192003,-0.098984,-0.611508,-0.193618,-0.508262,-0.899330,-0.361165,-0.518808,-0.062539,-0.062178,-0.179178,0.602188,0.507321,0.007254,0.577439,-0.170801,0.257205,-0.076142,0.758828,-0.104733,0.385745,0.347891,-0.515831,0.201119,0.402663,-0.592676,-0.166911,-0.039386,0.145052,0.112442,0.578182,0.849520,-0.234173,-0.044347,-0.357121,0.250345,-0.585275,0.031071,-0.001600,0.688622,0.119768,0.029616,0.231749,0.145694,-0.025629,0.231813,-0.133768,-0.780966,0.077886,-0.091376,0.041935,-0.895307,0.600133,0.117579,0.269792,0.095024,-0.052519,0.462420,0.727116,0.114771,0.077464,-0.274626,0.034228,-0.640437,0.033015,0.854404,-0.262206,-0.455281,-0.167243,-0.054173,-0.453350,-0.014738,0.049223,0.137184,0.004339,0.429649,-0.018670,-0.257300,0.130570,-0.541686,0.418047,-0.260589,-0.469587,-0.069900,-0.533853,-0.355605,-0.537524,0.165603,-0.300673,-0.561084,0.604988,-0.146248,0.111538,0.748335,-0.171255,0.220011,0.852898,0.665685,-0.230561,0.928249,0.045711,-0.117791,-0.012215,0.097051,0.463037,0.132092,0.627664,0.302323,0.327828,-0.285882,0.078447,-0.442003,0.238137', '21619567', '3755531', '26342391', '1306530');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26273481', '境界的彼方 剧场版 未来篇', '动画', '2013年10～12月にテレビアニメが放送された京都アニメーション制作「境界の彼方」の劇場版2部作の後編。テレビ版総集編にあたる前編「過去篇」から1年後を舞台に、ヒロインの栗山未来らに起こる新たな出来事を描いた完全新作の劇場版。戦いが終わり、これまらまた普通の日々が始まると思っていた秋人と未来だったが、未来の記憶が失われてしまう。新学期を迎えても未来の記憶は戻らず、高校3年生に進級した秋人は未来の幸せを願い、彼女を避けるように生活していたが……。', '种田梨沙', '石立太一', 8.1, 8010, 'tt4539114', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2232714370.jpg', 0.5, 2.7, 21.6, 41.1, 34.1, '-0.487329,0.109616,0.480115,-0.155849,0.656019,0.125719,-0.818255,0.098036,-0.141822,-0.747683,-0.501742,0.317794,-0.420194,0.319219,0.390672,-0.019495,-0.461183,-0.514133,0.322800,-0.554969,-0.094043,0.393233,0.193137,0.151073,-0.451952,-0.533491,1.111450,-0.029534,0.331015,0.018125,0.035960,0.550760,-0.169512,-0.482243,0.215085,-0.012887,-0.085311,0.603675,-0.338002,0.264813,-0.759972,-0.415963,-0.445488,-0.232772,0.269114,-0.270602,0.969987,0.010916,-0.045961,-0.549640,0.923434,0.154851,-0.475724,-0.094999,0.649883,0.287407,-0.435553,0.458469,-0.207501,-0.036722,-0.277771,-0.619077,-0.066382,-0.227503,0.112351,-0.355628,-0.113590,-0.049610,-0.254358,0.187710,0.336405,0.090119,-0.284930,0.203587,0.543072,0.318995,-0.215193,0.528661,0.106702,0.418428,0.626466,0.038932,-0.276013,0.316169,0.349018,-0.143467,-0.598246,-0.193414,-0.439061,0.176285,-0.641530,0.491326,0.385856,0.521867,-0.072158,-0.095657,-0.066478,0.222440,0.601826,0.231005,-0.278283,-0.628102,0.083194,-0.205465,-0.264537,-0.299906,0.642408,-0.614641,1.016903,-0.196349,0.022837,0.241657,0.384319,-0.221812,0.876830,-0.061237,0.151481,-0.633557,0.066369,0.373089,-0.700848,0.014350,-0.239040,-0.226758,-0.326841,0.179014,0.102528,0.576110', '1322847', '34810454', '1308146', '27167055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26274810', '侦探：开端', '喜剧', '《侦探》讲述的是具有天才侦查第六感的主人公大万（权相佑饰）与老手刑警（成东日饰）一起解决神秘杀人案件的故事。权相佑饰演的主人公大万是一家之长，开了一个漫画书店维持生计，而他私下实际上是天才侦探，运营着国内未解决案件和犯罪分析的同好会和博客。这也是权相佑自2011年《痛症》之后再度回归韩国大银幕。徐英姬在片中饰演生活能力非常强的妻子。权相佑和徐英姬的合作也让影迷非常期待。', '权相宇', '金郑勋', 6.8, 6751, 'tt5031892', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2285573157.jpg', 0.7, 6.3, 51.4, 33.3, 8.3, '0.105791,-0.386457,-0.216788,0.697906,0.224885,0.078647,0.647941,0.073395,-0.427662,-0.488366,0.067578,0.829550,-0.263691,0.135976,0.305736,-0.210261,-0.436370,-0.819038,-0.302491,0.057065,-0.091152,-0.501571,-0.434552,-0.186304,-0.183370,-0.438636,0.788329,0.031562,-0.335092,0.503512,0.374652,0.266334,-0.232052,0.193365,-0.070375,0.031884,0.141215,0.357369,-0.360012,0.392413,0.225703,-0.164840,-0.057151,-0.031837,0.147227,0.309064,0.398693,-0.051139,-0.355199,0.080032,0.483117,-0.441253,-0.394907,-0.190187,0.459774,0.006615,0.471364,0.420657,-0.109831,-0.199218,-0.258165,-0.154403,-1.061139,-0.112028,0.327317,0.175656,-0.507895,0.153792,-0.044793,-0.146063,0.198717,-0.066314,0.163120,0.306535,0.570934,0.350116,0.053403,0.202901,-0.429915,0.546010,0.443417,0.428066,-0.102325,0.600550,-0.292225,-0.740763,-0.327132,-0.424786,-0.586401,0.133229,-0.064728,-0.045758,-0.156684,0.217606,-0.397851,0.043120,0.018311,-0.076816,0.215195,-0.401348,0.104555,-0.883560,-0.485628,-0.558945,-0.239735,-0.074908,0.171680,-0.512403,1.199585,-1.056958,-0.294415,0.533489,0.170898,-0.539668,0.863945,0.299913,0.051965,-0.376981,0.039450,-0.245727,-0.092888,0.213214,-0.087827,0.390023,-0.051602,-0.480911,-0.541906,0.300022', '27602116', '25880986', '4301278', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26274910', '奔跑吧！兄弟', '喜剧', '有这样一个传说，很久很久以前，雨林在孔雀公主的庇护下，生活着虎人和鹿人两个部落，直到某天黑虎挑起战争。惨烈的搏杀过后，虎人落败，黑虎死亡，但他的仇恨却穿越时空来到了21世纪。新年伊始，脱胎自韩国《Running Man》的大型综艺竞技娱乐节目、并由浙江卫视节目中心和韩国SBS电视台联合制作的《奔跑吧兄弟》创下了超高收视率，此番节目组》向忙着各自事业的团员们发出召集令，熊黛林、王宝强、杨颖、谢依霖、李晨、郑恺、王祖蓝在导游伊一的带领下集结三亚。但是这是一次极为凶险的旅程，跑男团的背叛者隐藏其中，相机而动，时刻准备将所有人的快乐摧毁无形……©豆瓣', '杨颖', '胡笳', 3.5, 58577, 'tt4412218', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2224568933.jpg', 56.2, 22.7, 13, 3.6, 4.5, '0.023672,-0.183238,-0.483924,0.667565,0.427376,0.120780,0.587342,0.258822,-0.256508,-0.050996,0.459920,0.535092,-0.333533,0.287553,0.309986,-0.269457,-0.213541,-0.599740,-0.334532,0.098210,-0.029342,0.085632,-0.098497,-0.101271,-0.044628,-0.023491,0.804033,0.222925,-0.121088,0.513656,0.330432,0.012178,-0.476882,0.523458,-0.121681,-0.049772,-0.038849,-0.074935,-0.278792,0.304436,-0.113439,-0.011748,-0.276961,0.039842,0.046808,0.195903,0.479739,-0.353142,0.109874,-0.233726,0.221960,-0.315367,-0.104395,0.054514,0.371818,-0.062867,0.196343,0.271051,0.173721,0.105810,-0.303890,-0.220095,-0.681203,0.171794,-0.021119,0.036779,-0.615894,0.446295,0.175758,0.109840,0.178476,-0.167423,0.141592,0.526303,0.245567,0.061021,0.003109,0.346445,-0.382829,0.337150,0.819487,-0.080448,-0.166738,-0.073826,0.109770,-0.653351,-0.339862,-0.155417,-0.535355,-0.051992,0.332461,-0.064295,0.125675,0.121234,-0.843615,0.174492,0.053803,-0.468286,0.096920,-0.298960,-0.060397,-0.909273,0.079689,-0.210814,-0.307433,0.098647,0.063582,-0.155512,0.765262,-0.824818,0.021507,0.432874,0.274345,-0.289446,0.556228,-0.091477,0.106554,-0.188001,-0.079883,0.166090,-0.150586,0.492293,0.228407,0.281837,-0.301787,-0.069635,-0.382532,0.473614', '2369613', '20274039', '1294917', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26275494', '橘色', '剧情', '圣丹斯国际电影节上，一部名为 Tangerine （《橘色》）的电影受到了很多关注。这部影片的主题很新颖，讲述的是在好莱坞不那么光鲜的角落里工作的变性妓女；人物性格冷酷、有趣、有从不让人欺负的个性。不过，最令人吃惊的是，这部电影的导演 肖恩·贝克放弃了专业电影拍摄装备，选择 iPhone 5s 拍摄电影。很多业余电影爱好者使用 iPhone 录制电影，不过，Tangerine 是第一步全部使用 iPhone 拍摄并在圣丹斯电影节上展出的电影。肖恩·贝克使用 iPhone 5s 拍摄视频，并使用价值8美元的视频应用 FilmicPro 。肖恩·贝克表示，由于自己的预算有限，才选用了 iPhone 拍摄。当然，使用 iPhone 拍摄有一定的优势，比如无需从洛杉矶市政厅购买电影拍摄许可。', '吉塔娜·罗德里格斯', '肖恩·贝克', 7.7, 12334, 'tt3824458', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2241278738.jpg', 0.8, 2.9, 27.3, 50.5, 18.4, '0.169247,-0.246052,-0.445694,0.680459,0.502894,-0.072192,0.488147,0.034233,-0.019708,-0.334207,0.438533,0.811008,-0.481500,-0.268683,-0.014223,-0.158661,-0.788821,-0.203060,-0.050231,0.006515,0.139693,-0.301594,-0.399921,-0.026605,-0.075962,-0.420503,1.174309,0.068711,-0.891150,0.015785,0.492967,-0.227415,0.291738,0.128062,0.162047,-0.345177,-0.103790,-0.083613,-0.135800,0.690860,0.126611,-0.245546,-0.150538,0.012290,0.397796,0.549015,0.687975,0.061982,-0.386179,0.333312,1.088987,-0.387223,-0.105863,-0.323142,-0.116101,0.277675,0.401634,0.002015,-0.222585,0.358818,-0.422050,-0.368914,-1.236573,0.021805,0.322711,0.136662,-0.368989,0.196280,-0.350792,-0.047818,-0.105024,-0.335709,0.266218,0.168622,0.538832,-0.051488,0.282763,-0.131691,-0.463672,0.712954,0.267907,0.002258,-0.338139,1.018062,-0.262524,-0.570824,-0.401571,-0.501462,-0.456915,0.472245,0.234842,-0.385166,-0.086919,-0.208779,-0.456347,0.122158,0.345366,-0.769380,0.002657,-0.273120,0.332600,-1.803601,-0.161608,-0.282235,-0.211659,-0.807842,0.225623,-0.630186,0.991512,-0.706469,-0.015186,0.517949,0.401191,-0.365230,0.944119,-0.201939,-0.235822,-0.141138,-0.080146,0.126539,0.060585,0.000426,-0.176733,0.329111,0.460870,-0.824358,-0.406400,0.887392', '34961898', '2369613', '30397916', '3318306'