INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26276364', '女巫', '恐怖', '故事发生在17世纪30年代的新英格兰，由于无法苟同教会的做法，虔诚的清教徒威廉（拉尔夫·尹爱森 Ralph Ineson 饰）遭到种植园的驱逐，被迫带着妻子凯瑟琳（凯特·迪基 Kate Dickie 饰）和一众儿女远迁来到一处荒芜所在。他们白手起家，历经艰辛，而尚在襁褓 中的儿子意外失踪则令一家人的心头蒙上挥之不去的阴影。天气恶劣，作物歉收，夫妻二人的关系陷入紧张，凯瑟琳心念下落不明的孩子，精神近于崩溃。在此期间，自感对孩子失踪负有主要责任的长女托马辛（安雅·泰勒-乔伊 Anya Taylor-Joy 饰）心情沉重，此后不久，大弟凯勒布（哈维·斯克林肖 Harvey Scrimshaw 饰）在丛林深处遭遇女巫，心智错乱。一家人的生活彻底陷入混乱，他们能否在信仰中得到救赎？©豆瓣', '安雅·泰勒-乔伊', '罗伯特·艾格斯', 7.1, 33994, 'tt4263482', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2301995564.jpg', 1.8, 7.8, 38.5, 39.2, 12.6, '0.072292,0.000964,-0.856062,0.351606,0.115919,-0.082581,0.717069,0.232472,-0.763658,-0.522330,0.178645,0.536656,-0.073491,0.255799,0.375484,-0.223754,-0.460743,-0.438993,-0.181229,-0.209730,-0.247793,-0.568087,-0.161402,-0.385577,-0.212812,-0.451236,0.516092,0.423021,-0.096543,0.418465,0.201331,0.507437,-0.386143,0.096661,0.035843,0.072879,0.094896,-0.039036,-0.566232,-0.146951,0.025535,-0.103244,-0.025464,0.070792,0.182838,0.260558,0.820642,-0.300856,-0.097086,-0.103540,0.349663,-0.093763,-0.067946,0.151640,0.414432,0.013644,0.016848,0.089158,-0.033550,0.043736,0.198290,-0.258200,-0.401868,0.169385,0.266133,0.088684,-0.477393,0.384466,0.164265,-0.055610,-0.061316,-0.325106,0.176894,0.377075,0.356010,0.626155,-0.002899,0.164599,-0.224536,-0.105195,0.736616,-0.223783,-0.171644,0.071970,-0.636212,-0.356253,-0.133404,-0.218800,-0.690420,-0.082933,0.446762,0.171826,-0.096561,0.860594,-0.189327,0.041340,-0.120620,-0.180701,0.042992,-0.104961,-0.126000,-0.321590,-0.261032,-0.366761,-0.156646,0.276826,-0.060992,-0.186719,0.451555,-0.480680,0.615048,-0.006850,0.190433,-0.327581,0.352764,0.069237,0.386707,-0.328791,-0.081938,0.914694,-0.055860,0.044004,0.270832,-0.227413,-0.393262,0.298919,-0.296889,0.254502', '4889554', '3009079', '27066196', '27055378');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26276387', '桑格莉之夏', '剧情', '2015圣丹斯世界剧情片单元最佳导演奖。17岁的少女珊葛莉梦想有天能开飞机，但却受限于胆怯而内向的个性，还有惧高症。然而当珊葛莉遇上大胆、自由、自我主张的奥丝特，有了一百八十度转变。珊葛莉最后鼓起勇气登上飞机，但令她印象最深刻的是若即若离的关係。全片展现立陶宛的优美风光，藉由诗意的影像叙事，捕捉少女青涩的美感以及追求梦想的年轻力量。', '尤利娅·斯特波娜妮特', '阿兰蒂·卡瓦特', 7.4, 9744, 'tt2994832', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2276780433.jpg', 0.6, 4.1, 37.4, 40.1, 17.7, '-0.018489,0.121064,-0.596893,0.967528,-0.244895,-0.037854,0.726834,0.161478,-0.355250,0.014911,0.201718,0.409527,0.024203,0.162530,0.512039,-0.115161,0.039138,-0.451861,0.088055,0.070105,0.054602,-0.356164,-0.476959,-0.173525,-0.008084,-0.593081,0.993418,0.165361,-0.401363,0.356469,0.339155,-0.119081,-0.095164,0.212975,-0.116375,-0.298845,0.132463,0.175776,-0.090670,0.149290,-0.195423,-0.350655,-0.040614,0.225486,-0.517335,0.497268,0.883152,0.014927,-0.483169,0.328237,0.894660,-0.038247,-0.333182,-0.066568,0.029360,0.015464,-0.206105,-0.070277,0.365428,-0.262257,0.021712,-0.181455,-0.727724,0.188967,0.282868,-0.079789,-0.339383,0.348266,-0.064129,-0.107090,0.107064,-0.204729,-0.214934,-0.116993,0.430777,0.374193,-0.199562,0.305086,-0.138687,0.085537,0.385107,-0.059755,-1.042776,0.830545,-0.817030,-0.586278,0.002690,-0.686273,-0.401130,0.151993,0.026109,0.253415,0.000843,0.040554,-0.527240,0.039790,-0.151296,0.144725,-0.017279,-0.421054,-0.133173,-0.360813,-0.461849,-0.536789,-0.214158,0.026361,-0.025072,-0.246970,0.967712,-0.700572,0.106461,0.733816,0.111541,-0.423445,0.925157,0.142750,-0.394604,-0.262260,-0.079429,0.640680,-0.711611,-0.153945,-0.704078,0.361237,-0.432686,-0.118876,-0.549831,0.601441', '1303542', '22265121', '24499012', '30349667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26277156', '不可思异', '剧情', '人生、事业低谷的唐立果（王宝强 饰）在消沉与悔恨中度日。某日，开普勒星球的“外星生物”为了采集人类样本来到地球，闯入了唐立果的生活中……一系列啼笑皆非的奇幻事情接二连三地发生。唐立果亦兄弟亦老板的王若水（小沈阳 饰）因遭遇竞争对手的吞并阴谋，落入陷阱并欠下巨额高利贷，公司面临倒闭边缘。王若水几度产生轻生念头，唐立果与他的多年客户田静从事故的索赔转化发展为恋人关系，而一切看似峰回路转之时，外星生物的奇功异能被贪婪的反派（董成鹏 饰）发现并企图据为己有，人类贪婪欲望再一次暴露。地球，陷入一场“不可思异”的危机当中……', '王宝强', '孙周', 4.1, 27052, 'tt5114564', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2286216311.jpg', 37.6, 33.4, 20.8, 4.4, 3.8, '-0.004098,0.201120,-0.593455,0.355451,0.006717,-0.045271,0.746627,-0.087030,-0.522613,-0.333601,0.213591,0.669941,-0.218460,0.057333,0.376679,-0.240039,0.040334,-0.539714,0.131110,-0.108233,0.024694,-0.181418,-0.441963,-0.349241,-0.197246,-0.320793,0.954900,0.459459,-0.519740,0.280474,-0.049233,0.369155,-0.535512,0.598455,0.361465,-0.182537,-0.049560,0.285203,-0.671197,-0.021785,-0.147792,-0.309482,0.169050,0.138606,-0.313770,0.064178,0.832718,-0.389834,-0.194334,-0.477195,0.481697,-0.227911,-0.138659,-0.036287,0.335851,0.107168,0.046049,0.381180,-0.211539,0.036445,0.492376,0.003383,-0.877188,-0.269099,-0.007990,0.065568,-0.194541,0.194782,0.244342,0.072728,-0.069223,-0.118217,0.077076,0.344126,0.881108,0.444970,-0.343452,0.009773,-0.099224,-0.061976,0.554907,-0.318447,-0.145319,0.338412,-0.185117,-0.572572,-0.024846,-0.181323,-0.391423,0.144443,0.231757,0.179339,-0.353947,1.118318,-0.916164,0.243142,-0.443807,-0.172957,-0.004730,-0.147545,-0.200932,-0.418078,-0.233602,0.068584,-0.188060,0.296557,0.396990,-0.268626,0.267707,-0.466617,0.027200,0.568393,0.340890,-0.668503,0.228494,-0.116091,0.076905,-0.404823,-0.260887,0.476602,-0.278379,0.379195,-0.307770,-0.298427,-0.065436,0.153553,-0.057605,0.295710', '26759819', '7051375', '10581450', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26277182', '小花的味噌汤', '剧情', '千惠（广末凉子 饰）和脸热安武信吾（泷藤贤一 饰）交往多年，正当他们准备携手步入婚姻殿堂之时，千惠却被确诊患上了乳腺癌，然而，信吾依旧选择了向千惠求婚。婚后，千惠开始积极的接受治疗，在化疗的副作用的折磨之下，夫妻两人依然保持着对生活积极而又乐观的态度，一度，千惠的病情得到了控制。然而，让千惠和信吾没有想到的是，千惠的腹中竟然进驻了一个小小的生命，若想保住这个孩子，那么千惠将不能够再使用药物，这也就意味着，千惠的癌症有很大的可能复发。坚强的千惠决定生下孩子，十个月后，小花呱呱坠地。果不其然，千惠的癌症复发了，面对死神渐渐逼近的脚步，千惠决定给丈夫和孩子留下最宝贵的遗产。©豆瓣', '广末凉子', '阿久根知昭', 7.7, 19928, 'tt5462892', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2265379759.jpg', 1.2, 2.7, 26.8, 46.6, 22.6, '0.048322,0.020298,-0.728301,0.392270,0.006791,-0.516639,0.710442,0.044927,-0.089544,-0.322081,0.276998,0.829260,-0.212538,0.033190,0.085298,-0.076895,-0.158160,-0.686666,-0.126648,0.153991,-0.695224,-0.448750,0.000505,-0.006907,-0.242194,-0.589970,0.800457,0.091535,0.104458,0.406270,0.142091,0.233112,0.316990,0.522702,0.013768,0.085599,-0.161770,0.009736,-0.303400,0.463065,0.554743,-0.334315,0.060456,0.716963,-0.019534,0.448091,0.839470,-0.365141,-0.362766,-0.179458,0.468911,-0.225366,-0.406500,0.198445,-0.064425,-0.036518,0.113115,0.306898,-0.456618,-0.231570,0.140045,-0.000909,-0.496622,-0.051623,0.092765,0.173667,-0.712944,0.226626,0.010044,-0.005920,0.131819,-0.458272,0.343468,0.538788,0.077480,0.678245,-0.644586,0.000371,-0.444672,-0.038346,0.619963,-0.111105,-0.374562,0.571434,-0.428273,-0.512157,0.173330,-0.394189,-0.404845,0.046025,-0.124861,0.322212,-0.481305,-0.028364,-0.007265,-0.115313,-0.512559,-0.074009,0.157657,-0.484957,-0.021824,-0.372319,-0.067067,-0.391042,-0.492346,0.365691,-0.075479,-0.646207,0.884566,-0.862483,0.232761,0.422178,0.696817,-0.660797,0.334776,0.213943,0.148507,-0.076729,-0.011832,0.479883,-0.409956,0.280380,0.364700,0.230013,0.105581,0.112944,-0.477388,0.304884', '5446226', '26593587', '30345227', '1937946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26277313', '西游记之大圣归来', '剧情', '五百年前，由石猴变化而成的齐天大圣孙悟空（张磊 配音）大闹天宫，最终被如来佛祖镇在了五行山下。此去经年，长安城内突然遭到山妖洗劫，童男童女哭声连连，命悬一线。危机时刻，自幼被行脚僧法明（吴文伦 配音）抚养长大的江流儿（林子杰 配音）救下了一个小女孩，结果反遭山妖追杀。经过一番追逐，江流儿无意中解除了孙悟空的封印，齐天大圣自然好好地将山妖教训了一番。因为封印未解开，悟空不得不护送江流儿和小女孩回长安，一路上又遭遇了猪八戒（刘九容 配音）和白龙马。与此同时，妖王（童自荣 配音）绝不甘心失败，他躲在暗中，等待着给孙悟空一行致命一击的良机……©豆瓣', '张磊', '田晓鹏', 8.3, 645723, 'tt4644382', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2255028780.jpg', 0.8, 2.1, 16.9, 42.4, 37.9, '0.036016,0.290456,-0.727741,0.509809,0.343913,-0.309394,0.226963,0.063178,-0.545220,-0.014761,0.125804,0.406248,-0.293573,0.055228,-0.242837,-0.093063,-0.105565,-0.087674,-0.147365,0.086002,-0.040093,0.201234,-0.144470,0.237379,-0.259187,-0.282297,0.532960,0.112675,0.047383,0.421989,0.218521,0.213339,-0.421220,0.412582,-0.228998,0.639834,-0.047689,-0.032294,0.128851,0.446674,-0.034230,-0.332061,-0.110616,-0.004644,-0.127376,0.247731,0.746057,-0.553903,-0.037227,-0.244386,0.010537,-0.379487,0.020459,0.212577,0.447748,-0.115240,0.541912,0.362035,-0.326415,-0.048356,0.082071,-0.260250,-0.071887,-0.110997,0.314329,0.005726,-0.453907,0.189133,0.102318,0.243506,0.028316,-0.497134,-0.054607,0.422919,0.387249,0.327105,-0.261336,-0.098532,-0.243680,0.113217,0.650365,-0.296638,0.216971,0.178970,0.510787,-0.243445,-0.066921,-0.265038,-0.096100,0.085034,0.761434,0.040900,-0.447528,0.142835,-0.207586,-0.337728,-0.517369,0.206659,-0.212085,-0.378193,-0.278208,-0.398669,0.302177,-0.072720,-0.252366,-0.133463,0.104348,0.253184,0.459067,-0.540819,0.224478,0.582437,-0.010319,0.003220,0.360643,-0.277931,0.197408,-0.245039,0.297142,0.039708,0.017980,0.568076,0.491531,0.334050,-0.184217,-0.039855,-0.441571,0.058702', '1438591', '4892342', '26418093', '4832825');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26277361', '黑暗正义联盟', '动作', '不断出现的人类互相伤害事件，让蝙蝠侠意识到背后神秘的魔法力量作祟。为探寻究竟，他联合了康斯坦丁的超自然团队。', '马特·瑞安', '杰伊·欧力瓦', 7.6, 11147, 'tt2494376', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2418038772.jpg', 0.5, 2.7, 32, 47, 17.8, '0.471875,0.245365,-0.675237,0.739385,0.149135,0.435249,0.573111,-0.155814,-0.429754,-0.496636,0.584685,0.663622,-0.121193,-0.066058,-0.170833,-0.165644,0.130248,-0.613412,0.168531,0.100328,-0.637422,-0.505771,-0.739632,-0.171516,0.038170,-0.656898,0.398269,0.220580,-0.766955,-0.017691,0.102129,0.962828,-0.563647,0.661288,0.315398,-0.235279,0.290103,-0.235224,-0.151066,0.216607,-0.025079,-0.644862,0.318661,0.551038,-0.612711,-0.072592,1.086119,-0.488287,0.126565,-0.444002,0.795953,-0.233162,-0.127438,0.104103,0.454572,0.418198,-0.384047,0.109369,0.324428,-0.010528,0.012587,0.378265,-1.152217,-0.094111,0.136340,0.294376,-0.371502,-0.228792,0.320298,-0.320882,0.420447,0.025804,0.211244,0.446050,0.547929,0.120299,-0.472484,0.026591,-0.402382,-0.589522,0.600481,-0.253691,-0.374572,0.054337,-0.570383,-0.628571,-0.625768,-0.189636,-0.033793,-0.180565,0.011373,0.641782,-0.195519,0.737725,-1.131933,-0.019230,0.103033,0.051107,-0.148795,-0.662109,0.036655,-0.826960,-0.945167,-0.019868,0.016910,0.144711,-0.034067,-0.505104,0.661177,-0.742846,0.096371,1.569540,0.585157,-0.685308,0.451892,-0.054502,-0.235304,-0.205022,-0.329332,0.163857,0.212158,0.289711,-0.006556,0.159287,0.226358,0.441941,0.126128,0.378092', '25774050', '26871938', '1309112', '10581450');
