INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26279120', '从天“儿”降', '喜剧', '辰默（陈学冬 饰）和墨涵（姜雯 饰）是交往多年的恋人，彼此之间感情十分要好。两人同另一对恋人乐意（张艺兴 饰）和鹿米嘉（李小璐 饰）住在同一幢公寓里，常常一同聚会玩耍。四人年龄虽已成人，但个性却仍旧像孩子般大大咧咧，整日就是吃喝玩乐，毫无担当，亦从不想未来。某日，一个横空出世的宝宝像一枚陨石般落入了四人之中，引发了一场大爆炸。四个对照顾宝宝毫无经验的大人被迫成为奶爸奶妈，被一个小人儿折腾得焦头烂额。更让四人感到不可思议的是，这个看似不谙世事的小宝宝竟然有着令人咋舌的特异功能。随着时间的推移，四人和宝宝之间建立起了弥足珍贵的亲情。©豆瓣', '陈学冬', '魏楠', 3.8, 26569, 'tt5119546', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2285391089.jpg', 49.5, 25.2, 15.8, 4.1, 5.4, '0.268505,-0.182311,-0.685208,0.480071,-0.121227,-0.125832,0.776704,0.248995,-0.614719,-0.147262,0.014416,0.717545,-0.481264,0.365438,0.072793,-0.178007,0.023118,-0.660277,-0.459072,-0.066656,-0.009371,-0.377785,-0.201988,0.124002,-0.162379,-0.269205,0.522555,-0.309672,0.033984,0.614971,0.401431,0.080172,-0.443193,0.383179,-0.198113,-0.103942,-0.115097,0.373062,-0.126107,0.060576,0.021001,0.129064,0.058601,-0.069122,-0.008075,0.133629,0.691836,-0.388869,-0.287946,-0.202886,0.308170,-0.114846,-0.273089,0.023749,0.330697,0.082334,0.466156,-0.088400,-0.203227,0.214144,0.354151,-0.310212,-0.539276,0.236719,0.313379,0.130923,-0.549257,0.621855,0.220084,-0.322541,0.138793,-0.292602,0.176057,0.329193,0.086385,0.597493,-0.444644,0.095176,-0.502837,-0.048585,0.699508,0.194322,-0.316420,0.482887,-0.296266,-0.161665,0.019488,-0.289840,-0.527878,-0.020190,0.152304,0.005234,-0.092517,0.336449,-0.582479,0.352676,-0.275249,0.074366,-0.023612,-0.604844,0.087910,-0.433038,0.033535,-0.777263,-0.421456,0.328448,0.091006,-0.242577,1.013929,-0.870596,0.078321,0.144724,0.202915,-0.300788,0.643178,0.143226,0.184932,-0.223612,0.213091,0.006638,-0.093152,-0.308430,0.108821,0.405519,-0.289030,0.005808,-0.433970,0.293891', '1292219', '26283288', '26354526', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26279124', '新哥斯拉', '剧情', '平静的东京湾突然发生海难，当人们还在猜想是否海底火山爆发时，一只巨大的怪兽冒出水面并登陆城区。日本政府主导成立了“巨大不明生物灾害部”，网罗了国家中的奇人异士加盟，研究发现怪兽是受到放射性污染而诞生出来的，命名为哥斯拉；尝试了各种办法均宣告失败的“灾害部”最后不得不决定对哥斯拉采取武装攻击。但是这个巨大的怪兽哥斯拉完成了更恐怖的进化，整个东京将要沦为一片人间地狱，一场人类与怪兽的最终决战即将到来……该片是2017年日本票房突破80亿的日本真人电影，并横扫第40届日本电影学院七项大奖；片中的怪兽也被称为整个哥斯拉系列中“最大版本”。©豆瓣', '长谷川博己', '庵野秀明', 6.7, 43967, 'tt4262980', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2371512648.jpg', 3.1, 12.2, 41.5, 32.2, 10.9, '-0.091433,0.137809,-0.694740,0.428112,0.417353,0.238827,0.622611,-0.273468,-0.387857,-0.064485,0.206964,0.660170,-0.474281,-0.028897,0.146597,-0.166705,0.101877,-0.472979,-0.133713,-0.008069,-0.154772,-0.102064,-0.665864,-0.025450,0.053678,-0.205977,0.938923,0.502054,-0.440983,0.229296,0.251037,0.197980,-0.201006,0.505558,0.071712,-0.164299,-0.094611,0.022019,-0.107275,0.346786,-0.362809,-0.284340,0.120366,0.168570,-0.303296,0.346944,0.652924,-0.560001,-0.168137,-0.512210,0.545749,-0.472449,-0.223960,0.120726,0.530062,0.120369,0.040689,0.001107,0.111847,0.319428,-0.027523,-0.154161,-0.798103,-0.216394,-0.055750,0.168079,-0.157679,0.230195,0.197454,0.188619,0.125226,0.039531,0.070397,0.321374,0.415089,0.402101,-0.329642,0.147753,-0.374543,0.239758,0.586060,-0.275479,-0.721718,0.043006,0.062212,-0.716986,-0.112230,-0.511611,0.155912,0.184968,0.107014,0.380414,-0.265485,0.465195,-0.937163,0.135374,-0.438217,-0.611794,-0.180846,-0.113517,-0.070763,-0.811788,0.002371,0.042212,-0.008705,0.228629,0.103740,-0.360414,0.564894,-0.568347,0.119167,0.337997,0.337077,-0.169547,0.273027,-0.197341,-0.071028,-0.120112,0.021875,0.184297,-0.070056,0.536593,-0.171429,0.135927,0.211295,-0.444349,-0.122462,0.433969', '26759819', '7051375', '1578502', '25890017');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26279202', '“吃吃”的爱', '喜剧', '想要在巨星姐姐面前证明自己的18线小演员上官娣娣（徐熙娣 饰），和多年期待真爱却在最后被狠狠出卖的空间站黑鸟面馆老板娘许春梅（徐熙娣 饰），当两个人的世界以想象不到的方式不期而遇，她们的命运会发生什么样的改变?', '徐熙娣', '蔡康永', 5.2, 55135, 'tt6912580', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2459199108.jpg', 13.4, 33.4, 36.9, 10.3, 6, '0.184859,0.403685,-0.463650,0.539280,-0.214942,0.030547,0.810086,0.147413,-0.535705,0.123995,0.502486,0.859328,-0.410439,0.324228,-0.000669,-0.033560,0.207868,-0.809980,-0.080291,0.059248,-0.418435,-0.481134,-0.289126,-0.475097,0.109667,-0.078691,0.721506,0.076464,0.009610,0.041294,0.644732,-0.051996,-0.353094,0.191749,0.073337,0.079364,0.273060,0.381880,-0.219105,0.128093,-0.048198,0.087331,-0.025646,0.452496,-0.470947,-0.088801,0.755294,-0.430214,-0.143700,0.120533,0.288468,-0.210451,0.254281,0.321087,0.066149,-0.441422,0.236433,-0.190704,-0.097197,-0.271441,0.366831,0.018247,-1.196595,-0.058061,0.031770,0.204000,-0.703138,0.419264,-0.004479,-0.254123,0.451205,-0.283020,0.204208,0.406051,0.715188,0.434608,-0.654676,-0.172688,-0.367025,0.343306,0.724799,0.215924,-0.479717,0.240626,-0.275665,-0.029442,-0.333077,-0.330723,-0.445397,0.149959,0.476318,0.086421,-0.441049,0.237459,-0.359849,-0.178785,-0.022757,0.208297,0.591558,-0.706318,-0.013908,-0.472383,-0.014285,-0.544591,-0.336254,0.326352,0.119391,-0.345009,0.724766,-1.059663,0.143972,0.741768,-0.020815,-0.812939,0.699459,-0.085061,-0.448459,-0.406151,-0.039772,0.121207,-0.107145,0.234610,0.183637,0.230378,0.005584,0.130357,-0.210858,0.251475', '26678784', '30163500', '1793491', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26279229', '黑司祭们', '剧情', '讲述了两名天主教司祭被卷入事件中以及由此展开的一系列故事。金司祭（金允石 饰）因总是擅自行动而被教会其他司祭所排挤，更为了拯救因一宗神秘交通事故而陷入危机的少女英申（朴洙垣 饰），在所有人的反对和怀疑中，做出了危险的选择，独自计划着所有的行动。神学院学生出身的崔副祭（姜栋元 饰），虽然曾是作弊又喝酒的不良学生，但具备了可以帮助金司祭的所有条件，于是他也加入到金司祭的计划中，帮助他一起拯救少女。他并不相信金司祭所作的一切，在帮助他的同时也担负起监视他的任务，与金司祭一起进行危险的仪式，却被卷入了意料之外的神秘事件。', '金允石', '张宰贤', 6.6, 9028, 'tt5049302', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2267618116.jpg', 1.5, 10.8, 51.2, 27.5, 8.9, '0.249739,0.177311,-0.622243,0.617324,-0.112395,-0.069291,0.712812,0.114175,-0.526140,-0.423785,0.074030,0.613792,0.092526,0.215882,0.498117,-0.297771,-0.175043,-0.689742,-0.260379,0.088388,-0.321108,-0.799322,0.057762,-0.262122,-0.335188,-0.618564,0.617143,0.471505,-0.536113,0.365228,0.628624,0.480080,-0.343298,0.616863,0.191659,-0.230496,0.070191,0.042610,-0.046281,0.045340,-0.012413,-0.670456,-0.034923,0.648782,0.123452,0.540760,0.686997,-0.693176,-0.213551,-0.194085,0.397983,-0.492270,0.119696,0.232675,0.430642,0.230907,0.124597,0.392215,-0.081303,0.130200,0.072350,-0.139513,-0.931635,-0.211447,0.511672,0.219948,-0.817831,0.250964,0.304497,0.089570,0.096326,0.025379,0.067916,0.428058,0.426463,0.192379,-0.154064,-0.034508,-0.448530,0.084986,0.769108,-0.220192,-0.298505,0.067427,-0.255930,-0.568704,-0.521114,-0.123233,-0.207490,0.156054,0.307721,0.227037,0.100223,0.404990,-0.444799,-0.296603,-0.243703,-0.210568,-0.036414,-0.272374,0.246854,-0.698398,0.126871,-0.231146,-0.431461,0.021693,0.113381,-0.190673,0.745737,-0.874423,0.232068,0.504538,0.352505,-0.685106,0.485260,0.270588,0.399183,-0.179775,-0.221774,0.043006,0.134274,0.240935,0.150816,0.315862,0.168228,-0.270040,-0.146755,0.218723', '1301022', '1793491', '30163500', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26279289', '怒', '剧情', '炎炎夏日，东京八王子郊外社区，一对夫妇惨遭杀害。事后凶手用血在墙上写下大大的“怒”字，随后逃亡，销声匿迹长达一年之久。而在此期间，三个身份不明的男子和身边的人相遇了。曾自甘堕落的爱子（宫崎葵 饰）被父亲（渡边谦 饰）领回海滨小镇，邂逅了不善言辞的哲也（松山研一 饰）。在东京工作的同性恋优马（妻夫木聪 饰）将柔情似水的直人（绫野刚 饰）带回了家，他不相信对方，却又尝试去相信。随母亲搬到冲绳的小泉（广濑铃 饰）跟着同学辰哉（佐久本宝 饰）登上一座荒岛，在废墟中遇到了背包客田中（森山未来 饰），他们短暂成为朋友，而可怕的命运突然降临泉的头上。不久之后，通缉令遍布全国，三个男子的真实身份引人生疑……本片根据吉田修一的同名原作改编。©豆瓣', '渡边谦', '李相日', 7.7, 81112, 'tt4384088', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2399174377.jpg', 0.8, 3.4, 26.3, 48.5, 21, '0.083514,0.024232,-0.478931,0.416611,0.113617,-0.173870,0.379981,0.196643,-0.360921,-0.282712,0.271534,0.866805,-0.229550,0.295679,0.365749,0.235635,-0.144807,-0.688849,-0.115040,-0.584116,-0.307753,-0.480442,-0.031382,-0.106646,0.024035,-0.042852,0.474137,0.247114,-0.049931,0.621379,0.320262,0.357027,-0.416828,0.186859,-0.216357,0.114970,0.005731,0.132558,-0.127863,0.162208,-0.309636,-0.319614,-0.138145,0.048235,-0.088365,0.273234,0.802037,-0.192520,-0.240081,-0.203730,0.293379,-0.180307,-0.196293,0.003191,0.520410,-0.103346,0.140018,0.306949,-0.343925,-0.101223,0.107627,-0.091916,-0.356659,0.142061,0.024074,0.174371,-0.464791,0.432807,-0.140625,-0.322882,0.168555,-0.193270,0.143089,0.144852,0.204639,0.257520,-0.112046,0.022430,-0.179331,0.179370,0.569334,0.020139,0.012453,0.152255,0.144641,-0.246958,-0.109117,-0.173999,-0.183070,0.118346,0.234302,0.014916,-0.081477,-0.045337,-0.459739,-0.130959,-0.349552,0.141160,0.228629,-0.179464,-0.268262,-0.500597,0.054898,-0.287717,-0.234194,0.155090,0.061972,-0.079205,0.526188,-0.645838,0.056414,0.343931,0.367889,-0.377468,0.499565,-0.044308,-0.094709,-0.307325,0.128768,0.187099,0.262885,0.274531,0.194380,0.169951,-0.263111,0.017953,-0.530757,0.170564', '3811356', '1309194', '26365262', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26279353', '与外婆同行', '剧情', '艾利（莉莉·汤普琳 Lily Tomlin 饰）曾经亦是诗坛之中有头有脸的人物，无奈时代变化如此之快，如今，她早已经成为了一名无人问津的过气诗人。偏偏祸不单行，不久之前，艾利刚刚和交往了四个月的女友分手，事业屡遭挫折，感情又如此不顺，此刻的艾利只想一个人安安静静的躲起来，谁都不想搭理。可是，天不遂人愿，艾利那十八岁不省事的孙女赛奇（朱莉亚·加德纳 Julia Garner 饰）来访，向外婆借钱堕胎，然而囊中羞涩的艾利连自己都顾不过来，哪还能拿的出余钱来救济这个闯了祸的姑娘？无奈之下，她只得开车载着赛奇，一一拜访从前的好友和女友们，向他们借钱。©豆瓣', '莉莉·汤姆林', '保罗·韦兹', 7.8, 11767, 'tt4270516', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2255130435.jpg', 0.4, 2, 25.8, 53.1, 18.7, '0.365109,-0.007535,-0.690201,0.371263,-0.331664,-0.707617,0.522755,0.133831,-0.510041,-0.342776,0.092485,0.575426,-0.109810,0.358137,0.175119,0.053319,-0.238259,-0.472715,0.231117,-0.324548,-0.223502,-0.409270,-0.319557,-0.037395,-0.285641,0.086773,0.080802,-0.017514,0.229834,0.362171,0.519623,0.078306,0.002289,0.573250,-0.265069,0.194288,-0.121467,0.230528,-0.069008,-0.072616,0.002843,-0.229373,-0.317123,0.225443,-0.002658,0.462680,0.273182,-0.190125,0.030795,-0.218048,0.405080,-0.189025,0.033464,0.288081,0.262698,-0.308653,0.397228,-0.095179,-0.022348,-0.115635,0.008456,0.191943,-0.473959,0.338276,-0.028029,0.170091,-0.768155,0.192906,-0.250677,-0.195323,-0.105227,-0.451708,0.042580,0.491145,0.060792,0.464746,-0.358512,-0.026930,-0.632747,0.288004,0.664628,0.243094,-0.240134,0.360276,0.128798,-0.212515,0.081844,-0.512302,-0.853611,0.101475,0.073411,0.019517,-0.079978,0.229422,-0.398239,-0.034353,-0.150145,0.051566,-0.025711,-0.374636,-0.092506,-0.268509,-0.051913,-0.389601,-0.464719,0.072516,0.151284,-0.171485,0.617349,-0.571706,0.023874,0.320009,0.490523,-0.495352,0.790545,0.184895,0.015407,0.175264,-0.129449,0.090046,-0.097296,0.327627,0.186621,0.261692,0.297403,-0.360582,-0.125758,0.186066', '1291586', '25900249', '1301221', '24879820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26279433', '剩者为王', '剧情', '盛如曦（舒淇 饰）的年龄眼看着就要突破三十五岁大关，虽然拥有着一份稳定且待遇优厚的工作，但她的感情世界却是一片空白。家人和朋友们都在替盛如曦着急，忙不迭的将各路不靠谱的对象介绍给她相亲，深怕盛如曦再拖下去成为嫁不出去的老姑娘，这令盛如曦感到十分苦恼。汪岚（郝蕾 饰）和章聿（熊黛林 饰）是盛如曦的好友，两人的情况和盛如曦差不多，三个女人坚强的在冰冷的现实社会中拼杀，躲过世俗压迫，躲过流言蜚语却最终躲不过各自内心深处对于感情的渴望。一位名叫马赛（彭于晏 饰）的男子出现在了盛如曦的身边，彻底改变了她的命运。©豆瓣', '舒淇', '落落', 5.8, 86415, 'tt5257730', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2277540557.jpg', 6.8, 23.2, 46.9, 16.8, 6.3, '0.382503,0.042916,-0.592260,0.662401,-0.162818,-0.236532,0.711403,0.268872,-0.337436,-0.189626,0.237062,0.569133,-0.220329,0.288715,0.239540,-0.209749,0.072759,-0.832388,-0.224179,-0.072060,-0.267348,-0.321462,-0.499201,0.038166,-0.278858,-0.374073,0.580783,-0.044371,-0.156732,0.505773,0.391058,0.325544,-0.005741,0.580861,-0.254096,-0.053099,-0.085346,-0.004793,-0.422795,0.032684,0.067180,-0.213845,-0.083411,0.190351,0.050797,0.365041,0.648503,-0.181677,-0.215837,0.272690,0.427878,-0.177792,-0.286081,0.229703,0.234147,-0.036396,0.109080,0.151074,-0.192510,0.215942,0.088317,-0.025240,-0.753000,0.071479,0.242149,0.208625,-0.822359,0.549894,-0.012172,-0.147383,-0.045698,-0.318037,0.018073,0.201694,0.026339,0.467146,-0.466472,0.129471,-0.450875,0.191363,0.506723,0.297046,-0.175728,0.332003,-0.274612,-0.442997,-0.269107,-0.316710,-0.617563,-0.184641,0.086347,0.111119,-0.250131,0.278325,-0.385817,0.012510,-0.044634,-0.195951,-0.007349,-0.698504,-0.039376,-0.313866,-0.236964,-0.601216,-0.557811,0.194675,0.200695,-0.501285,0.748350,-0.651516,0.132488,0.287310,0.246276,-0.655804,0.775122,0.315004,0.167892,-0.157393,-0.147684,0.092109,-0.057303,0.021141,0.180536,0.315932,-0.397877,-0.109679,-0.321274,0.557394', '26021055', '6101834', '3230462', '26259635');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26279449', '蒸发太平洋', '剧情', '《蒸发太平洋》讲述了一个发生于2020年的科幻冒险故事，一架大洋航空新客机在首航中遭遇意外，迫降到怪物肆虐的好运岛上，包括王子、明星、记者在内的乘客随之与机组人员一起陷入了危险中。', '布兰登·罗斯', '周文武贝', 3.2, 10902, 'tt4363250', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2306409195.jpg', 63.8, 20.4, 8.9, 3.3, 3.6, '0.405866,-0.216859,-0.807276,0.463682,0.477169,0.220711,0.828812,-0.443223,-0.770619,0.033947,0.504916,0.765896,-0.425302,-0.017326,0.857005,-0.249927,-0.512381,-0.600929,-0.344318,-0.078946,-0.335897,-0.611259,-0.241031,-0.190598,0.023357,-0.664231,0.583128,0.638758,0.010566,0.729913,-0.105048,0.071215,-0.755756,0.649574,0.154823,0.264519,0.408031,0.231580,-0.289936,0.326713,-0.385943,-0.214058,0.482439,-0.327073,0.176711,0.095368,0.967085,-0.321323,0.086479,-0.194542,0.085213,-0.109770,0.121100,-0.207586,0.609128,0.315271,0.289389,0.076143,-0.008611,0.192884,0.079443,0.271177,-0.191649,-0.253631,0.017857,0.242880,-0.139105,0.248233,-0.063616,0.258775,0.073248,-0.042867,0.590940,-0.002259,0.543702,0.452207,-0.014775,0.361300,-0.157011,0.350131,1.093151,-0.005603,-0.408220,-0.008178,-0.205045,-0.319828,-0.398075,-0.232895,-0.371094,0.239639,0.402358,0.063261,-0.282382,0.882863,-0.803478,0.086171,-0.069673,-0.686159,-0.338252,-0.132947,-0.388786,-0.597290,0.239222,-0.018029,0.294743,0.364433,0.256054,-0.011203,0.587307,-0.440377,0.430421,0.609491,0.296590,-0.075527,0.629678,-0.280553,0.153737,0.000256,0.250874,0.009766,-0.199877,0.378807,-0.214303,0.299658,-0.513321,-0.208503,-0.239123,-0.368645', '3011051', '3147969', '26687241', '1299433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26280528', '从你的全世界路过', '喜剧', '陈末（邓超 饰）被称为全城最贱，每天和王牌DJ小容（杜鹃 饰）针锋相对，谁也不知道他们的仇恨从何而来。陈末的两个兄弟，分别是全城最傻的猪头（岳云鹏 饰），全城最纯的茅十八（杨洋 饰），三人每天横冲直撞，以为可以自在生活，结果都面临人生最大的转折点。陈末相遇了最神秘的幺鸡（张天爱 饰），猪头打造了最惨烈的婚礼，茅十八经历了最悲伤的别离，这群人的生活一点点崩塌，往事一点点揭开。梦想，爱情，友情都离陈末远去。一个失去所有的人，已经弄丢自己的路，直到听到来自全世界的一段语音……', '邓超', '张一白', 5.3, 323746, 'tt6074202', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2382076389.jpg', 15.8, 27.9, 35.8, 14, 6.4, '0.096303,-0.281986,-0.490807,0.550684,0.051517,-0.350329,0.729360,-0.114258,-0.076928,-0.274126,0.364393,0.578847,-0.165867,0.073043,0.160259,-0.275529,0.050985,-0.584106,-0.083600,-0.142458,-0.253360,-0.122272,0.044700,-0.061759,-0.054958,0.138609,0.726362,0.116455,-0.095807,0.243437,0.494896,0.119411,-0.297862,0.212915,-0.231956,0.112445,0.108089,0.058998,-0.313348,-0.179494,-0.304686,-0.113309,-0.035478,0.245210,-0.466377,-0.002321,0.613351,-0.278015,-0.155242,-0.025438,0.378522,-0.512925,-0.297144,0.077647,0.228629,-0.261852,0.325677,0.155710,-0.315896,0.014966,0.150214,0.239537,-0.816520,-0.123777,0.098045,0.127428,-0.387474,0.593118,0.250001,-0.088920,0.365102,-0.200380,0.595701,0.321437,0.282820,0.347701,-0.277251,-0.133507,-0.562092,0.215672,0.813501,-0.364008,-0.026606,0.477247,-0.049768,-0.177422,-0.164907,-0.194711,-0.587401,0.144269,0.121536,-0.004706,-0.191898,0.429166,-0.704348,0.140449,0.125129,-0.393627,0.235794,-0.483873,-0.250802,-0.310249,-0.331402,-0.575810,-0.377438,0.312076,0.127533,-0.178223,0.815593,-0.513254,0.080731,0.202630,-0.097416,-0.402131,0.406388,0.373949,0.019483,-0.379909,0.035565,0.282334,0.145666,0.210360,0.061065,0.218785,-0.177309,-0.047603,-0.423166,0.821166', '26667010', '2053515', '25828589', '24879858');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26280556', '土豪520', '喜剧', '陈百一（吴镇宇 饰）靠着自己早年的智慧和努力终于建立了“帕瓦罗蒂皮革厂”，成为了百万富翁。赵小薇（姚星彤 饰）是厂里新来的设计师，她对皮革设计的热衷和专注吸引了陈百一的注意，随着时间的推移，两人之间渐渐产生了超越了上下级的感情。余海盐（马天宇 饰）是公司里的财务总监，曾经，他深得陈百一的信赖和重用，然而，自从赵小薇来了之后，陈百一渐渐冷落了余海盐，与此同时，余海盐亦爱上了单纯善良的赵小薇。眼看着赵小薇和陈百一渐渐走到了一起，余海盐的不满情绪日益高涨。某日，陈百一被医生告知他患上了不治之症，他对赵小薇隐瞒了病情，独自前往意大利，想要在临死之前干一番惊天动地的大事。©豆瓣', '吴镇宇', '林爱华', 3.7, 4509, 'tt4838290', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2239658370.jpg', 47.7, 29.5, 15.5, 3.9, 3.4, '0.311130,0.058453,-0.628700,0.517603,0.123164,-0.360689,0.564526,0.318901,-0.794036,-0.208272,-0.291592,0.657685,-0.199371,0.212936,0.208291,-0.214529,-0.382379,-0.904175,-0.214649,-0.049795,-0.409002,-0.537712,-0.182890,-0.140029,-0.244172,-0.280500,0.383691,0.191784,-0.232934,0.709026,0.246103,0.256840,0.266403,0.607001,-0.115475,0.166847,0.160908,0.017039,-0.099041,0.059105,0.169352,-0.447490,-0.048476,0.017069,0.054302,0.521650,0.462429,-0.172745,-0.317945,-0.225553,0.485727,-0.323221,0.235431,0.041280,0.265831,0.388386,0.107753,0.313689,-0.706051,0.066177,0.145655,-0.130162,-0.714041,-0.075922,0.136305,-0.225473,-0.871137,0.653467,0.049356,-0.359281,0.299236,-0.183186,0.410178,0.373095,-0.051664,0.314502,-0.020730,0.059521,-0.235319,0.333148,0.700651,0.225749,-0.079213,0.439309,-0.160182,-0.327932,-0.211099,-0.280311,-0.147672,-0.329729,0.289383,0.426516,-0.083989,0.205931,-0.464729,-0.166447,-0.071082,-0.170304,0.047169,-0.318280,-0.154450,-0.327288,-0.373570,-0.851844,0.088121,-0.015510,-0.117153,-0.192208,0.734808,-0.905405,0.137348,0.412581,0.307236,-0.522464,0.738295,0.001601,0.007634,-0.095827,-0.090708,-0.095241,-0.188465,0.202760,0.398705,0.360547,-0.070662,0.034745,-0.253201,0.529100', '35030151', '25810920', '1301022', '35144311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26280561', '大喜临门', '喜剧', '32岁的李淑芬（林心如 饰）终于要结婚了，不料，淑芬的老爸李金爽（猪哥亮 饰）看这憨女婿高飞（李东学 饰）是越看越不爽，不舍女儿外嫁大陆，规矩定得比台湾101大楼还要高！聘金的数字、迎娶的人数、流水席的礼数、婚礼的禁忌，要说到完口水都干了。还好大囍媒婆钱颂伊（林美秀 饰）有专家级手腕、人见人爱；眼看新娘就要娶进门，却突然哭跑了……', '猪哥亮', '黄朝亮', 5.4, 3526, 'tt4674500', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2230150006.jpg', 12, 29.2, 42.1, 10.7, 6.1, '0.043617,-0.155268,-0.521602,-0.075756,0.014501,-0.303719,0.262869,0.339387,0.262964,0.253830,0.166444,0.565923,-0.633068,0.251786,0.147792,0.398931,0.060935,-0.531584,0.116449,-0.269287,-0.164302,-0.194759,0.220715,-0.121624,0.141281,-0.027354,-0.117499,0.068693,0.102573,0.172436,0.536422,-0.450782,0.266593,0.235803,-0.648434,0.120741,-0.092503,0.154143,0.265477,-0.037851,0.071791,0.102828,-0.105974,-0.152284,0.297292,0.401226,0.012122,0.149952,-0.047328,-0.006509,0.461102,-0.035681,-0.250394,0.056815,0.605310,-0.106518,-0.093106,-0.406374,0.030546,-0.208327,0.134388,-0.281858,-0.083816,0.567044,0.240982,-0.015716,-0.883179,0.432990,-0.259255,-0.251667,0.164534,-0.043176,0.011942,0.001038,-0.242306,0.605655,-0.054548,0.205703,-0.581569,0.267943,-0.025947,0.283470,0.281393,0.482698,0.164668,-0.537804,0.162370,-0.415045,-0.231051,0.105672,0.537205,-0.022066,0.173681,-0.035537,-0.032283,-0.153397,-0.228975,-0.041134,0.058577,-0.387472,-0.333328,0.103289,-0.166217,-0.548136,-0.027574,0.348099,0.333548,-0.159264,0.602911,-0.194905,-0.251128,-0.021681,0.519386,-0.803225,0.590424,0.351471,-0.121526,-0.087999,0.055007,-0.158611,-0.392833,0.290114,0.086948,0.345853,-0.006781,-0.730274,-0.187502,0.469529', '1962230', '1293607', '1297710', '1302110');
