INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26280710', '怪物之子', '动作', '9岁的人类少年莲（宫崎葵 配音）痛失母亲，他拒绝亲戚的照顾，独自跑上熙攘的大街，偏巧遇到了偶然来人间寻找弟子的怪物熊彻（役所广司 配音）。怪物界的宗师（津川雅彦 配音）即将转生为神，接任他位置的人选将在猪王山（山路和弘 配音）和熊彻之间产生，但是没有嫡传弟子让熊彻希望渺茫。借此机缘，莲闯入了怪物世界，他和熊彻之间争吵不断，可是在冲突的过程中似乎又渐渐认同彼此。转眼间莲（染谷将太 饰）已成长为武功高强的落落青年，他无意中回到人间，重拾了失落已久的身份和感情。与此同时，决定宗师的日期一天天临近，谁也没有想到的意外却发生了……©豆瓣', '役所广司', '细田守', 7.8, 52688, 'tt4272866', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2238784204.jpg', 0.3, 2.2, 27.3, 48.6, 21.5, '0.136094,0.156271,-0.713930,0.624472,0.006036,-0.134477,0.529197,-0.048156,-0.608545,-0.236900,-0.039552,0.776497,-0.243490,0.159521,0.088612,-0.210754,0.042236,-0.632053,0.178063,-0.297963,-0.337392,-0.282815,-0.153849,-0.131343,-0.277853,-0.342071,0.932789,0.238599,-0.245292,0.389332,0.096752,0.163583,-0.183127,0.587753,-0.220112,0.146767,0.243394,0.432438,0.061411,0.152206,-0.111424,-0.374870,-0.079623,0.182207,0.010496,0.418095,0.632047,-0.331657,-0.210643,-0.027920,0.110070,-0.203140,-0.108711,0.014072,0.545560,-0.070977,0.163031,0.226759,-0.022810,-0.293048,-0.256978,-0.237900,-0.613412,0.235281,0.251084,0.194247,-0.443708,0.510345,0.033589,-0.188052,0.149358,-0.138332,0.281134,0.354140,0.376222,0.183089,-0.302537,-0.211499,-0.270298,0.056142,0.715910,0.038024,-0.042786,0.560786,-0.176860,-0.444189,-0.119796,-0.319595,-0.277865,0.017102,0.170161,0.243976,-0.277255,0.381699,-0.263165,-0.028532,-0.125350,0.151554,0.050737,-0.423814,-0.079117,-0.391343,0.021915,-0.396897,-0.348041,-0.071910,0.066202,-0.434246,0.835535,-1.009010,0.139215,0.410592,0.371240,-0.370429,0.883461,-0.268800,0.157654,-0.379200,0.099072,0.146651,-0.139173,0.290099,0.247430,0.260892,-0.231141,0.110798,-0.329951,0.305951', '35030151', '1308499', '1395231', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26280899', '蜡笔小新：我的搬家物语 仙人掌大袭击', '动画', '新的一年，小新一家决定离开生活了多年的地方，举家前往墨西哥。在新的国度，小新一家遇到了很多新奇的人和事，同时也遭遇到了仙人掌怪物的袭击，小新不得不肩负起了保卫家人的重担。', '矢岛晶子', '桥本昌和', 8.1, 12810, 'tt4691348', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2230985905.jpg', 0.3, 2, 21.8, 43.2, 32.7, '0.423957,-0.161735,-0.671530,0.276519,-0.232632,-0.357102,0.334406,0.109059,-0.795026,-0.340782,0.481552,1.065799,0.179540,0.405475,0.323037,-0.084986,0.102716,-0.399882,0.138325,-0.468950,-0.594523,-0.131471,-0.251791,-0.417100,0.013913,-0.435933,0.374518,0.455905,0.163200,0.319536,-0.067005,0.195588,-0.348926,0.525862,-0.421720,0.090326,0.306582,0.269718,-0.530603,0.321121,-0.026049,-0.332270,-0.330076,0.052173,0.188584,0.155813,0.802585,-0.072149,-0.576313,-0.148313,0.183340,-0.158143,-0.108242,-0.076988,0.681661,0.016732,-0.062886,0.366910,-0.365657,0.245262,-0.006981,-0.362314,-0.467228,-0.054811,0.022030,-0.081864,-0.941206,0.588702,0.102269,-0.008577,-0.022778,-0.902068,0.341159,0.536810,0.208371,0.708152,-0.143072,0.410505,-0.370829,0.119772,1.358075,-0.082236,-0.197815,0.051538,-0.086867,-0.196961,-0.150281,-0.154134,-0.485241,0.156964,0.448138,-0.047093,-0.485986,0.452706,-1.272410,0.203071,-0.478215,-0.591037,0.597740,-0.203764,-0.026872,-0.582603,0.047818,-0.235018,0.121070,0.454063,0.241571,-0.194841,0.897798,-0.987391,0.201590,0.565587,0.311470,-0.903770,0.303347,-0.256586,0.413450,-0.112418,0.340383,0.295176,-0.093767,0.716549,0.101632,0.009400,-0.148654,-0.246294,-0.168973,0.397788', '25721544', '1308035', '34822138', '1298694');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26281899', '解除好友', '惊悚', '2013年，某所高中名叫劳拉·巴恩斯（Heather Sossaman 饰）的女孩自杀，一度引起轰动。劳拉自杀一年后的某个夜晚，她的同学布莱尔·莉莉（雪莱·亨尼格 Shelley Hennig 饰）正与男朋友米奇•卢塞尔（Moses Storm 饰）在网络上调情，这时朋 友圈的亚当·休厄尔（Will Peltz 饰）、肯（Jacob Wysocki 饰）、洁丝（Renee Olstead 饰）等人加入进来，少男少女嬉笑调侃，好不热闹。可是一同加入讨论的还有一个没有头像的神秘用户，他无法被踢出和挂断，更令几人震惊的是对方居然以劳拉的身份和他们说话。起初布莱尔等人认为这是某个黑客的恶作剧，谁知之前曾诅咒过劳拉的另一位辣妹瓦尔（Courtney Halverson 饰）暴走继而惨遭意外。在鬼魂的逼迫下，布莱尔等人不为人知的黑色秘密浮出水面，而他们也不可挽回地走向死亡深渊……', '雪莱·亨尼格', '列万·加布里亚德兹', 6.6, 37616, 'tt3713166', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2222034495.jpg', 2.1, 10.6, 49.4, 29.1, 8.8, '0.473979,-0.108029,-0.772211,0.489730,-0.151247,-0.241051,0.812758,0.114477,-0.539976,-0.295021,0.163227,0.506084,-0.429699,0.226515,0.356178,0.150883,-0.489583,-0.661479,0.120852,-0.274228,-0.277034,-0.387502,-0.315526,-0.296715,-0.019134,-0.282590,0.310405,-0.007944,-0.250616,0.671287,0.477349,0.566000,-0.147447,0.426729,-0.152251,0.131953,0.230037,0.019779,-0.066945,0.154089,0.035333,-0.293548,-0.120873,0.064952,-0.006332,0.434977,0.514560,-0.275173,0.092440,0.081915,0.160596,-0.311305,0.048631,0.200987,0.316572,-0.374630,0.314018,0.078688,-0.128969,0.075111,0.144895,0.126816,-0.438237,0.300320,-0.023665,0.316821,-0.265378,0.335521,-0.202059,0.025567,0.245550,-0.190427,0.143709,0.319539,0.303735,0.198039,0.101938,0.060869,-0.507260,0.038863,0.396146,0.166814,-0.095752,0.062142,-0.077675,-0.288527,-0.188585,0.046033,-0.422528,-0.027798,0.455397,0.145844,-0.087447,0.152022,-0.503560,-0.109259,-0.291355,0.006187,-0.009455,-0.323719,-0.419558,-0.689255,-0.072802,-0.219595,-0.243604,0.255230,-0.024915,-0.068171,0.473678,-0.760617,0.282949,0.226618,0.349334,-0.290732,0.611715,0.092253,-0.065153,-0.231366,-0.124800,0.128063,0.130401,0.114820,-0.022621,0.269805,0.059992,-0.137958,-0.283878,0.128093', '130168