INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26282448', '火影忍者剧场版：博人传', '动作', '漩涡博人（三瓶由布子 Yuko Sanpei 配音）虽然是七代火影漩涡鸣人（竹内顺子 配音）的儿子，但是他并不以父亲为荣，父子间充满了误会。博人为了打败父亲，准备拜师宇智波佐助（杉山纪彰 配音），与此同时，博人与佐助的女儿佐良娜（菊池心 配音）、三月（木岛隆一 饰）组成了小队，共同参加下影的考试。下影考试开始，博人求胜心切，不料考试途中，神秘反派大筒木桃式、金式发动了突然袭击，鸣人为了保护木叶村陷入了危机。博人开始重新认识这个父亲，和佐助、我爱罗等父亲的老朋友开始了拯救鸣人的战斗。©豆瓣', '三瓶由布子', '山下宏幸', 8.3, 68946, 'tt4618398', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2251539632.jpg', 1.1, 2.4, 17.6, 39.5, 39.4, '-0.063030,-0.164198,-0.030727,0.218200,-0.080412,-0.475534,0.314006,0.169879,-0.114597,-0.492506,0.114555,0.639098,-0.183407,0.299119,0.226730,-0.113082,-0.083305,-0.417398,-0.231953,0.136737,-0.103987,-0.222588,0.195590,-0.091383,-0.045988,-0.092000,0.990966,0.143350,-0.018139,0.462685,0.088967,0.313504,-0.066418,0.288294,0.334762,0.323098,-0.101315,0.049449,-0.032274,0.116202,-0.210569,-0.222540,-0.322554,0.393583,-0.005687,0.561457,0.579491,-0.122345,0.038357,-0.440725,0.090796,-0.504028,-0.436018,0.228040,0.476297,0.201251,0.218669,0.196425,0.197144,-0.215326,-0.166778,-0.241539,-0.519990,0.137075,0.056519,-0.155230,-0.055158,0.096367,-0.146588,-0.246682,0.583579,-0.154751,-0.020583,0.338133,0.394796,0.060775,-0.698928,0.184223,0.166394,0.239021,0.653116,-0.535847,0.147273,0.187378,0.059310,-0.313852,0.116079,-0.211121,-0.017762,0.034092,0.208369,0.281583,0.062543,0.125943,-0.504162,-0.216419,-0.010860,-0.063586,0.255188,-0.419028,0.053532,-0.599285,-0.006458,-0.181784,-0.095501,0.167286,-0.039226,-0.358713,0.616073,-1.026054,0.008957,0.598896,-0.036193,-0.212563,0.294931,0.174225,-0.187866,-0.495684,0.039642,-0.120967,-0.178049,0.206951,0.088988,0.234133,0.390281,0.050902,-0.129926,0.320193', '3861846', '2369613', '30345227', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26282530', '再见，在也不见', '剧情', '电影分为三个发生在不同时期、地点但是相互有着关联的故事。《背影》：陈经理（陈柏霖 饰）受公司所托前往广西进行业务考察，在工厂里，他意外的遇见了和自己失散多年的父亲。如今的父亲已然垂垂老矣，他早已经认不出儿子的面庞了，而陈经理也似乎并没有和父亲相认的打算。《湖畔》：陈德明（陈柏霖 饰）刚刚喜为人父，一封来自监狱的信便冲淡了这份喜悦。原来，他曾经的挚友（杨佑宁 饰）即将面临死刑的制裁，他要去新加坡送他最后一程。《再见》：大学教授陈志彬（陈柏霖 饰）前往泰国讲学，在那里邂逅了曾经的大学老师（蒋雯丽 饰），两人重续了一段师生恋。©豆瓣', '陈柏霖', '忻钰坤', 5.9, 19897, 'tt4907174', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2346580342.jpg', 5.2, 22.3, 49, 17.9, 5.6, '0.106610,0.005919,-0.798437,0.662094,0.120132,-0.366734,0.704380,0.309090,-0.465367,-0.297514,0.181981,0.814122,0.049088,0.357922,0.237231,0.027921,-0.269936,-0.673529,0.069774,-0.423063,-0.269568,-0.542171,-0.190535,0.031676,-0.002343,-0.128247,0.677909,0.097230,-0.132365,0.668516,0.328312,0.108402,-0.265045,0.466205,-0.238390,0.130755,0.030527,0.412427,-0.472110,-0.080232,0.317165,-0.225600,-0.067807,0.107097,0.069087,0.506956,0.529287,0.011166,-0.233852,-0.006274,0.283579,-0.094102,0.169690,0.118771,0.233744,0.067151,0.340363,0.333198,-0.205607,-0.091965,0.081899,-0.172329,-0.533053,0.038794,0.095136,0.132379,-0.475328,0.554814,-0.136342,0.079448,0.030272,-0.335067,0.428013,0.458015,0.190904,0.440254,-0.062365,-0.150116,-0.307926,0.425981,0.666102,-0.043024,0.005754,0.429701,-0.210065,-0.361154,-0.197506,-0.014127,-0.411272,0.429621,0.184833,0.065477,-0.333667,0.083104,-0.463892,-0.235228,-0.170669,0.103754,0.093817,-0.338080,0.236619,-0.593401,-0.202384,-0.541332,-0.278382,-0.048770,0.268152,-0.142111,0.414310,-0.648702,0.306883,0.356914,0.242660,-0.675403,0.721093,0.220791,0.069921,-0.347334,0.135034,0.222353,-0.099839,0.334336,0.196133,0.119036,0.071091,-0.097743,-0.456672,0.268610', '1303333', '3111650', '1301022', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26283288', '解语花', '剧情', '故事发生在1940年的朝鲜京城，郑素律（韩孝周 饰）是当时最有名的歌妓，她拥有美艳的容貌和出色的才艺，是风流才子们千金散尽都想要共度春宵的存在。徐妍熙（千玗嬉 饰）是郑素律从小玩到大的好友，同时和郑素律一样亦是一名歌妓。歌妓外表风光无限受万人追捧，实际上却是个充满了艰辛和苦楚的职业，两姐妹在一起相互扶持陪伴，彼此之间情谊十分深厚。金允宇（柳演锡 饰）是一名流行作曲家，在当时深受大众的喜爱，一次偶然之中，郑素律听到了金允宇新创作的一首歌曲，十分喜爱，想让金允宇把这首歌献给她来咏唱，然而，在金允宇的心中，能够完美诠释自己歌曲的人，却是名气不如郑素律的徐妍熙。©豆瓣', '韩孝周', '朴兴植', 7.1, 13783, 'tt5486170', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2347524281.jpg', 1, 5.3, 41.9, 38.8, 12.9, '0.229207,-0.053300,-0.650553,0.939286,-0.054479,0.017163,0.823099,-0.053868,-0.713113,-0.253530,0.210908,0.799219,-0.320888,0.326372,0.169057,-0.219909,0.111108,-0.752181,-0.077642,-0.260385,0.084223,-0.341621,-0.180149,0.066998,-0.424740,-0.412686,0.583473,0.004864,-0.261271,0.578246,0.545037,0.411955,-0.055672,0.094998,-0.605468,-0.251068,0.026373,0.056702,-0.220008,-0.007736,-0.163658,-0.359330,-0.317547,0.090466,-0.037161,-0.083859,0.685802,-0.277857,-0.042397,0.179767,0.474585,0.118434,-0.016936,0.078004,0.150068,0.016562,0.415664,0.122741,-0.195350,0.134907,-0.055165,-0.233897,-1.102157,-0.022039,0.518566,-0.002466,-0.635066,0.702162,0.062380,-0.432497,0.070387,-0.184973,0.320019,0.014038,0.159410,0.643329,0.076337,0.243238,-0.492438,0.469144,0.959730,0.354887,-0.239301,0.498030,-0.606639,-0.495384,-0.212102,-0.488716,-0.529440,0.145538,0.115928,0.093327,0.194799,0.164020,-0.553992,0.136479,0.032221,-0.134677,0.215333,-0.591405,-0.057688,-0.410550,-0.439083,-0.879066,-0.263323,0.063786,0.340405,-0.470596,1.471038,-1.055437,0.002511,0.299998,-0.006039,-0.538035,0.817839,0.420089,-0.112496,-0.017538,-0.432408,0.091842,-0.088083,-0.349759,-0.112101,0.471501,-0.098995,-0.127561,-0.642988,0.509743', '27602116', '24284209', '26348103', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26284593', '圆圈', '剧情', '《圆圈》故事背景设置为未来，爱玛·沃森饰演的的女主人公Mae就职于一家名为“圆圈”的互联网科技巨头公司。该公司将用户的所有个人信息都与其操作系统联系起来，并因此开启了互联网新时代。Mae在公司里遇到了名为Kalden的神秘同事，并与之相恋。而约翰·波耶加扮演的Kalden其真实身份则是公司的创始人之一，他凭借自己的天才创立了这一系统，最终也意识到“圆圈”对个人隐私的侵犯，并希望将其关掉。凯伦·吉兰作为主演之一，与爱玛沃森一样，也在“圆圈”公司上班，她表面上看起来略显笨拙，但实际上拥有超高智商。汤姆·汉克斯目前的角色还未确定，他很有可能扮演圆圈公司的另一幕后老板。影片改编自作家戴夫·艾格斯（《野兽家园》编剧）的同名小说，艾格斯同时也会担任《圆圈》的联合制片人。《圆圈》暂定于2016年上映，具体日期尚未公布。', '艾玛·沃森', '詹姆斯·庞索特', 5.5, 9530, 'tt4287320', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2447253459.jpg', 7.6, 30.6, 43.5, 13.5, 4.8, '0.201989,0.173901,-0.530883,0.666355,0.185402,-0.070990,0.442105,0.272910,-0.323232,-0.470024,0.040911,0.836989,-0.150461,0.181688,0.276829,-0.149857,-0.190363,-0.481642,-0.131201,-0.327028,-0.056975,-0.630053,-0.347359,-0.304587,-0.107116,-0.330546,0.784468,-0.129440,-0.243056,0.006316,0.363194,0.155626,-0.347573,0.187929,0.103326,-0.016643,0.197857,-0.106444,-0.455647,0.236964,-0.090578,-0.077779,0.213427,0.203964,-0.092296,0.323648,0.625147,-0.157595,-0.124840,-0.122268,0.714927,-0.057247,-0.168669,-0.354095,0.498652,0.018044,0.288846,0.347749,-0.013479,0.026114,0.132914,-0.324113,-1.083609,-0.030415,0.388155,0.251607,-0.300470,0.202258,-0.308771,-0.097084,-0.069080,-0.297203,-0.013754,0.267449,0.490628,0.277429,0.129364,0.298581,-0.344081,0.224092,0.146129,0.304697,-0.497360,0.446413,-0.332871,-0.617349,-0.516397,-0.133559,-0.325026,-0.038451,0.149917,0.262643,-0.004080,0.168307,-0.543156,0.024222,-0.089004,-0.175436,0.214346,-0.456384,0.165020,-0.740394,-0.190477,-0.092230,-0.082390,-0.282257,0.174319,-0.215532,0.647096,-0.890091,0.023313,0.587608,0.314761,-0.369410,0.752692,0.188607,0.173927,-0.354411,-0.157239,0.044752,0.186683,0.300304,-0.284711,0.161900,0.110708,-0.460990,-0.309356,0.338748', '1793491', '25880986', '26759820', '26834930');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26284595', '大话西游3', '喜剧', '在《大话西游之大圣娶亲》中死在牛魔王叉下的紫霞仙子（唐嫣 饰），将会通过月光宝盒预先看到这一下场，为了避免惨剧发生，她选择回到从前不让至尊宝（韩庚 饰）爱上自己。而至尊宝又再次重逢一直在等待他的白晶晶（莫文蔚 饰）。前世今生的种种爱恨纠葛再次在九道轮回里最后一次上演。', '韩庚', '刘镇伟', 4, 68600, 'tt4862468', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2377676571.jpg', 48.6, 22.8, 14.9, 5.9, 7.8, '-0.078862,0.336339,-0.902719,0.390199,0.094591,-0.224343,0.887937,-0.259230,-0.390242,-0.026762,0.672394,0.770221,-0.653651,0.378132,0.157322,-0.224883,-0.044863,-0.814230,0.335233,0.036403,-0.123184,-0.142044,-0.078990,0.247845,-0.127201,-0.055984,0.848369,0.008407,0.083304,0.184570,0.377818,0.116051,-0.618278,0.342636,-0.161509,0.376432,-0.389824,0.589979,-0.408401,0.394695,0.252996,-0.505623,-0.269471,0.147309,-0.286118,0.044580,0.688992,-0.745764,-0.219363,0.184908,0.372541,-0.103002,-0.245522,0.076705,0.021264,-0.084003,0.279468,0.316537,-0.325957,0.119707,0.074102,0.184065,-0.161487,-0.154366,0.003801,0.384040,-0.286762,0.504768,-0.003535,0.399566,0.166446,-0.443063,0.104624,0.438092,0.784385,0.285856,-0.599024,-0.345701,-0.232883,0.210862,1.010581,-0.106719,0.279975,0.554382,0.309598,0.012846,-0.235721,0.118213,-0.434740,0.359883,0.512659,0.161931,0.063922,0.608891,-0.478175,-0.208718,-0.153541,0.043538,0.014170,-0.253599,0.041354,-0.555085,-0.166721,-0.059467,-0.307443,0.189975,0.044122,-0.537210,0.232320,-0.945526,0.395424,0.299461,0.096924,-0.423958,0.427406,0.104324,0.388862,-0.138239,0.133596,0.639890,-0.177719,0.445374,-0.129760,0.281166,-0.091852,0.260414,-0.652686,0.288550', '1291835', '25858759', '11615927', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26284621', '追凶者也', '剧情', '一桩残忍凶案悄然发生在偏远的西部村寨，憨包汽修工宋老二（刘烨 饰）被警方推为首要疑凶。这让本来萍水相逢的三人：憨包汽修工宋老二、落魄古惑仔王友全（段博文 饰）、夜总会领班董小凤（张译 饰）命运彼此牵连在一起，在荒蛮西部上演了一场充满嬉笑怒骂的黑色逃杀。©豆瓣', '刘烨', '曹保平', 7.9, 298686, 'tt6067462', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2375882763.jpg', 0.3, 1.5, 22.6, 54.9, 20.8, '0.460802,-0.252618,-0.428077,-0.064579,0.174617,0.006494,0.611292,0.325949,-0.408099,-0.028880,0.703626,0.546966,-0.352907,-0.009951,0.086823,-0.090153,0.097581,-0.460344,-0.155507,-0.179190,0.141669,-0.388290,0.003760,0.065735,0.114128,0.331243,0.189892,0.197738,0.018006,0.537044,0.357953,0.164909,-0.639337,0.011732,-0.038269,0.220614,0.189574,-0.025428,-0.533352,-0.069837,-0.229691,-0.160097,-0.104487,-0.192533,-0.063468,0.143328,0.791044,0.029703,0.035964,0.104866,0.405300,-0.202967,-0.280453,0.125253,0.451006,-0.161694,-0.054447,0.393915,-0.206264,-0.131198,0.382180,0.243827,-0.324839,0.202200,0.165783,0.354361,-0.589856,0.823645,0.322146,-0.248338,0.263551,-0.339733,0.259687,0.343749,0.315732,0.293411,0.226899,0.056611,-0.476685,0.461282,0.602743,-0.050132,0.016561,-0.035185,0.007331,-0.120055,0.028611,-0.052364,-0.515879,-0.017600,0.587623,-0.580284,-0.207777,0.486642,-0.510188,0.029273,-0.020632,0.032126,-0.081258,-0.103385,-0.301227,-0.588357,-0.356222,-0.548205,-0.081114,0.219152,0.189265,0.158681,0.169194,-0.510870,-0.022399,0.349480,-0.105181,-0.196895,0.370362,0.263866,0.253398,-0.002881,-0.251829,-0.164264,0.070336,0.621255,0.389886,0.543914,-0.181915,-0.088912,0.016608,-0.029767', '1466273', '10466639', '1292050', '2295401');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26284955', '如果和母亲一起生活', '剧情', '1945年8月9日，美国向日本投下原子弹。就读医科大的青年浩二（二宫和也 饰）在毫无征兆的情况下死于非命。转眼三年过去，浩二的母亲福原伸子（吉永小百合 饰）似乎渐渐承认了儿子已不在人间的事实，她的丈夫、两个儿子皆已逝去，孤身一人在信仰的支撑下走过艰苦岁月。在某个夜晚，浩二突然在母亲身边现身。伸子喜出望外，和儿子热烈交谈。浩二不改善谈的个性，与妈妈有说有笑，当然他盘桓人间还有一个理由，那就是记挂情投意合的未婚妻佐多町子（黑木华 饰）。町子而今在某个小学担任教员，她念念不忘浩二，为此耽搁了自己的婚事。死去的人，和活着的人，他们之间的羁绊依然紧密……©豆瓣', '吉永小百合', '山田洋次', 7.5, 11834, 'tt4287852', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2241710281.jpg', 0.9, 5, 33.7, 40.4, 19.9, '-0.071706,-0.098718,-0.827155,0.398915,0.032199,-0.380210,0.618639,0.052022,-0.296759,-0.284400,0.381008,0.656109,-0.015105,0.372518,0.201407,-0.110349,-0.185377,-0.716868,-0.077462,-0.204655,-0.367343,-0.453241,-0.071230,-0.140434,-0.187740,-0.148908,0.713196,-0.061100,0.094249,0.509989,0.188873,0.210901,-0.128521,0.320027,-0.204370,0.144239,0.167348,0.290896,-0.402245,-0.033000,0.040845,-0.436726,-0.230556,0.019462,0.066868,0.447349,0.712901,-0.209649,-0.335100,-0.197654,0.109998,-0.180449,-0.185414,0.159796,0.361545,-0.225791,0.134245,0.380133,-0.187963,-0.436336,-0.078545,0.056256,-0.272276,0.189496,0.032234,0.263390,-0.541019,0.787728,-0.028740,-0.109743,0.012875,-0.547161,0.163060,0.475959,-0.213448,0.390373,-0.498815,0.011841,-0.312655,0.282249,0.816069,0.142970,-0.337066,0.448920,-0.224096,-0.109368,-0.150274,-0.048100,-0.539916,-0.231708,0.113213,0.018415,-0.290301,0.279135,-0.243295,0.107481,-0.080016,0.181652,0.199600,-0.638156,-0.154477,-0.264598,-0.087271,-0.474914,-0.439317,0.312978,0.214275,-0.239061,0.913281,-0.617765,0.091695,0.432176,0.509410,-0.316220,0.775828,0.125590,-0.000249,-0.228195,-0.032458,0.318877,-0.028291,0.151273,0.231475,0.264884,-0.188446,0.355261,-0.483989,0.245568', '3212120', '35048413', '1292219', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26284956', '秘密', '科幻', '近未来，科学家研发出可以窥探人类脑中世界的MRI扫描器。借助该扫描仪的帮助，警方可以从死者临终前看到的影像中追查线索。名为科学警察研究所法医第九研究室的机关，正是运用MRI扫描技术的经营机关。作为“第九”室长的警视正薪 刚（生田斗真 饰），曾经见过堪称地狱般的罪犯之脑。这一天，新人研究员青木一行（冈田将生 饰）被分配到“第九”，他很快就接触到一桩诡异的案件。某个男子因涉嫌杀害全家而被判处死刑，薪刚和青木一行对死刑犯露口浩一（椎名桔平 饰）的大脑研究时意外发现，灭门案中失踪的女儿露口绢子（织田梨沙 饰）居然挥舞着利刃刺向家人。以此为契机，连锁事件接连发生，甚至指向了“第九”的禁忌之地——贝沼事件，当初薪刚的好友铃木（松坂桃李 饰）以生命为贝沼事件画上血淋淋的句号，而今黑暗的秘密逐渐浮出水面……本片根据清水玲子于1999—2012期间连载的同名漫画改编。', '生田斗真', '大友启史', 5.4, 7261, 'tt4287848', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2378238479.jpg', 7.5, 33, 44.9, 11.4, 3.2, '0.045279,-0.034986,-0.454255,0.462131,0.132241,-0.149970,0.329878,-0.035553,-0.501916,-0.368049,0.391310,0.328265,-0.156441,0.049625,0.319709,-0.087457,-0.082497,-0.739818,-0.032758,-0.355184,-0.412232,-0.509295,-0.454491,-0.093797,0.139268,-0.428658,0.634416,0.147618,-0.249819,0.214979,0.069698,0.574014,-0.612323,0.023860,0.036298,-0.102040,0.204442,0.092341,-0.381409,0.220130,-0.251489,-0.338751,0.206077,0.034670,-0.367934,0.414784,0.759556,-0.427517,-0.186411,-0.265209,0.475996,-0.173431,-0.340121,0.028765,0.584615,0.360164,0.090988,0.389544,-0.385603,0.056346,-0.012469,-0.215398,-0.737529,-0.366871,0.129300,0.421175,-0.174558,-0.138573,-0.243858,-0.083706,0.269876,-0.099945,0.248199,0.189839,0.554378,0.219976,-0.264161,0.003572,-0.056488,0.236610,0.081579,-0.203721,-0.193671,0.369863,0.012926,-0.328953,-0.274209,-0.077446,0.075330,0.189742,0.149711,0.315621,-0.103369,0.351414,-0.479707,-0.279902,-0.266805,-0.177770,0.262774,-0.010608,-0.230746,-0.711452,-0.108393,-0.018203,-0.284511,0.088272,0.150975,-0.264914,0.440697,-0.714496,0.126961,0.497025,-0.053967,-0.198278,0.356001,-0.068552,-0.057183,-0.307916,-0.105619,0.003388,0.415022,0.641367,-0.143640,0.199071,-0.032812,-0.353482,-0.415550,0.214475', '25723905', '2369613', '10462705', '27126336');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26287783', '不期而遇', '喜剧', '捣蛋大王范小闲（张亮 饰）与正义少女李心（张雨绮 饰）从小就水火不容，一次争执后范小闲诅咒李心一辈子嫁不出去。长大成年后的范小闲虽事业有成，却遭遇婚姻、健康双重危机，李心也如他“诅咒”所说一直单身成为剩女……一对随时爆发、争执不断的冤家，怀揣各自不可告人的目的，挤进同一 辆车，行驶在美利坚美丽的公路上……', '张雨绮', '陈卓', 3.9, 4862, 'tt7074258', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2458370286.jpg', 39, 37.3, 16.9, 2.1, 4.7, '0.125697,-0.108343,-0.511711,0.197311,0.046636,-0.046669,0.789320,0.351827,-0.425085,0.053863,0.620153,0.457860,-0.453667,0.300952,0.095855,-0.113403,-0.102952,-0.355137,0.475704,0.227016,0.065307,-0.302624,-0.141998,0.070533,-0.244032,-0.147137,0.562393,-0.180209,-0.134520,0.582600,0.509600,0.103290,-0.423764,0.201949,-0.099197,-0.295018,0.008233,0.365749,-0.209690,-0.027968,-0.338835,0.271890,0.170835,-0.317476,-0.173993,0.277571,0.669163,-0.222880,0.324851,-0.442854,0.364561,-0.236275,-0.113016,0.504990,0.281840,-0.025063,0.323724,0.136125,-0.251917,0.114489,-0.106403,-0.048657,-0.134602,-0.069426,0.272603,0.048553,-0.389369,0.497450,0.244987,-0.342043,0.500921,0.169706,-0.044183,0.508729,0.430461,0.460708,-0.319818,0.214907,-0.568826,-0.177594,0.792194,-0.090530,-0.195803,0.251345,-0.042597,-0.282657,-0.272101,0.089730,-0.691739,-0.268698,0.200780,-0.098846,-0.420390,0.500825,-0.446265,0.285472,-0.302904,0.357004,0.232021,-0.412445,0.001222,-0.375273,-0.102990,-0.665678,-0.433298,0.467703,0.047492,-0.210025,0.698737,-0.521120,0.172001,0.228691,0.146544,-0.812033,0.326259,0.592534,0.078571,-0.544382,0.040067,0.777785,-0.336143,0.128091,-0.194221,0.107823,-0.175669,0.517246,-0.013739,0.400822', '25721544', '26322928', '30257991', '1296993');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26287884', '魔弦传说', '动画', '独眼男孩久保（阿特·帕金森 Art Parkinson 配音）和身体孱弱的母亲过着相依为命的日子。白天，久保靠着给村民们讲述怪力乱神的精彩故事赚钱，天一黑，他就必须回到家中照顾母亲。一天，久保回家晚了，曾经夺走了久保一只眼睛的邪恶姐妹（鲁妮·玛拉 Rooney Mara 配音）来到久保家，企图夺走他的另一只眼睛。在混战中，久保的母亲死去了，死里逃生的久保被迫离开村庄，在外流亡。久保得知父亲去世之前留下了一副能够保护久保不受到邪恶姐妹和其父亲月神（拉尔夫·费因斯 Ralph Fiennes 配音）侵害的盔甲，于是决定启程寻找它。路上久保偶遇了失忆巫师甲壳虫（马修·麦康纳 Matthew McConaughey 配音），甲壳虫也加入了久保的队伍中。©豆瓣', '查理兹·塞隆', '特拉维斯·奈特', 7.4, 76818, 'tt4302938', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2411608656.jpg', 0.4, 4.1, 34.6, 45.1, 15.8, '0.018158,-0.228573,-0.303025,0.025293,-0.037761,-0.545718,0.964121,0.336816,-0.220125,-0.323809,0.358717,0.438270,0.111540,0.490018,0.323267,-0.013801,-0.473699,-0.497989,-0.013555,-0.093188,0.141548,-0.552691,-0.050116,-0.273459,-0.206338,-0.664670,0.789895,0.002298,0.219430,0.649429,-0.042392,0.226854,-0.245538,0.270082,-0.043191,0.267480,0.149839,-0.013713,-0.210000,0.340777,-0.285804,-0.187486,-0.095293,0.202925,0.161671,0.202361,0.521688,-0.150658,-0.013520,-0.477232,0.450274,-0.170161,-0.315409,0.207373,0.676357,-0.022335,0.462262,0.045795,-0.034151,-0.128798,-0.173253,-0.064661,-0.246190,-0.125289,0.208438,0.138083,-0.944925,-0.077834,-0.112746,-0.024117,0.366984,-0.536280,0.173271,0.136332,0.327548,0.419683,-0.253408,0.638351,-0.239834,-0.085875,0.490042,-0.611357,0.198713,-0.023030,0.024240,-0.382635,0.017638,-0.253432,-0.392243,0.045679,0.388644,-0.082062,-0.360440,0.028308,-0.234640,-0.455646,-0.056826,-0.371510,0.233644,-0.097529,0.082182,-0.525833,0.012976,-0.521086,-0.151994,0.066550,0.147031,-0.115366,0.685494,-0.552563,0.531224,0.728960,0.337046,-0.040627,0.278384,0.200490,0.337699,0.000960,0.250630,0.093354,-0.110836,0.478629,0.393868,0.180550,0.154253,0.268638,-0.279588,0.269156', '21619567', '1467779', '1464907', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26289126', '坏蛋必须死', '喜剧', '假期来临之际，在釜山当中文老师的强子（陈柏霖 饰）和从中国家乡远道而来的好哥们三儿（乔振宇 饰）、大头（丁文博 饰）和弟弟帕帕（杨旭文 饰）相约，一起到济州岛散心。狂飙的小混混、性感的韩国女人（孙艺珍 饰）、执着的老警察（张光 饰）、神秘的尾随者（申贤俊 饰）、不着调的牧师（朴哲民 饰）接连出现在他们身边。期盼已久的旅程，因为这些人的存在而鸡飞狗跳、险象环生，好像每个人都做了坏事。此时一只神秘小黑猪出现让所有人杀红了眼，更将众人推向生死危急的关口……到底怎样才能脱离险境？究竟谁才是那个真正该死的“坏蛋”？©豆瓣', '陈柏霖', '孙皓', 6, 39519, 'tt5157018', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2280537531.jpg', 4.4, 19.9, 52.6, 17.7, 5.4, '0.002629,-0.232356,-0.625970,0.291283,-0.086028,-0.134744,0.687037,0.046009,-0.322892,-0.091409,0.335940,0.466875,-0.332209,0.192662,0.248043,0.086945,-0.165016,-0.679653,-0.093969,-0.157024,-0.302565,-0.025878,-0.314225,0.005051,-0.009583,0.006179,0.281690,0.076463,0.099051,0.379432,0.670968,0.126875,-0.368555,0.279561,-0.126603,-0.063732,0.066168,0.028383,-0.132797,-0.134922,-0.156733,-0.165901,-0.246151,-0.009262,-0.079339,0.129521,0.605965,-0.223798,0.007219,-0.032232,0.148165,-0.350224,-0.130212,0.031552,0.115248,-0.203956,0.284667,-0.124182,0.063870,-0.005170,0.019807,0.032393,-0.548674,0.314163,0.082563,0.204992,-0.518304,0.222654,0.004644,-0.052587,0.306964,-0.338349,0.319075,0.283294,0.107502,0.215738,-0.131295,-0.041541,-0.495389,0.117020,0.589219,0.004041,0.056009,0.026923,0.190121,-0.298422,-0.004021,-0.061013,-0.457069,0.154876,0.277503,-0.100589,-0.131793,0.087106,-0.526074,-0.034307,0.091721,0.005521,-0.069258,-0.421557,-0.345683,-0.398228,0.064888,-0.538868,-0.085315,0.318288,0.176349,0.110676,0.781768,-0.595105,0.172215,0.482099,0.152213,-0.335304,0.447795,0.085129,-0.144551,-0.290190,-0.459686,-0.022928,0.112642,0.258519,0.153709,0.364450,-0.302463,-0.151436,-0.403797,0.329740', '1307146', '3811356', '26926321', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26289138', '李雷和韩梅梅', '剧情', '运动全能的中学女汉子韩梅梅（张子枫 饰），各项成绩尚可，但一提起英语就头疼得要命。在结束了快乐的初中生活后，韩梅梅和魏华（成梓宁 饰）、林涛（李家成 饰）等一起升上了高中，同时还有李雷（张逸杰 饰）。如今的李雷已是脱胎换骨，从一个不起眼的小男生变成了又高又帅的男神，还有一口英伦范的纯正英语。韩梅梅也是不知不觉地喜欢上了李雷，却迟迟不敢开口，于是古灵精怪的她制定出各种作战计划，意图攻陷李雷。然而，天有不测风云，一场又一场的麻烦和变故，接二连三地降落在他们身上……多年后，韩梅梅和李雷，还能牵手吗？', '张子枫', '杨永春', 3.7, 35962, 'tt10314526', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2461589633.jpg', 50.5, 25.9, 16.7, 3.6, 3.3, '0.324779,0.076447,-0.804057,0.615212,-0.164769,-0.578608,0.579225,-0.009884,-0.358058,0.086159,0.081581,0.751990,-0.507991,0.368466,0.226315,-0.021662,-0.311697,-0.934837,-0.010285,-0.164645,-0.251003,-0.420062,-0.124477,-0.004826,-0.160134,-0.283048,0.319394,0.141287,-0.145051,0.529088,0.407044,-0.183254,0.132575,0.483218,-0.217770,0.013530,-0.050675,0.176532,0.145943,0.132488,0.308540,-0.198643,-0.294748,-0.030580,0.257841,0.315410,0.613271,0.103137,-0.099792,0.064003,0.349587,-0.328189,-0.199837,0.162240,0.471284,-0.034787,0.259574,-0.102529,-0.003200,0.059199,0.025114,-0.067019,-0.472166,0.173627,-0.135732,-0.026565,-0.558198,0.556549,0.019805,-0.183056,0.088478,-0.610702,-0.072033,0.344480,0.396911,0.615831,-0.157980,0.060874,-0.268682,0.189413,0.691194,0.120928,-0.497794,0.391483,-0.005870,-0.644189,-0.221705,-0.189156,-0.248615,-0.178289,0.467404,0.080929,-0.069232,-0.005974,-0.611721,0.179574,-0.256882,-0.053153,0.079302,-0.223085,-0.195566,-0.330625,0.050687,-0.587713,-0.459887,0.316455,0.042546,-0.328897,0.746571,-0.855589,0.076403,0.277624,0.029898,-0.304785,0.229406,0.247419,0.123713,0.110769,0.061607,-0.181542,-0.267719,0.429272,0.220105,0.667063,0.008075,-0.387116,-0.391524,0.362336', '1292219', '34429100', '2245683', '3155839');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26289144', '滚蛋吧！肿瘤君', '喜剧', '即将迎来29岁生日的青年漫画家熊顿（白百何 饰），却接二连三遭遇了常人难以想象的打击。工作被炒，男友跳票，还莫名其妙到警察局走了一遭。更糟糕的是，她在聚会上突然晕倒，经检查后才发现自己的身体出了问题。一向乐观开朗的熊顿并未被病魔吓到和打败，她笑嘻嘻地调侃吐槽周遭的人和事，一脸花痴地望着英俊帅气的梁医生（吴彦祖 饰）。最重要的是，身处逆境的她身边还有父母（李建义 & 刘莉莉 饰）以及夏梦（李媛 饰）等一班好友的鼎力支持。无论驶向哪里，熊顿永远不会孤独，不会放弃……本片根据已故漫画家熊顿以自身经历创作的同名漫画改编。©豆瓣', '白百何', '韩延', 7.4, 407799, 'tt4819514', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2259298553.jpg', 1.1, 4.7, 33.9, 43.2, 17.1, '0.062705,-0.277822,-0.567658,0.458822,0.061697,-0.347011,0.818879,0.109224,-0.309914,-0.213769,0.224650,0.495107,-0.384287,0.577571,0.463188,-0.125139,-0.149176,-0.580309,-0.322268,0.112138,-0.432056,-0.358275,-0.276016,0.140720,-0.175978,-0.145077,0.492130,-0.006351,-0.280004,0.404588,0.408236,0.347897,0.057987,0.593216,-0.129132,0.180974,0.107329,0.273431,0.123629,0.042577,0.374126,-0.649551,-0.079104,0.225196,-0.149962,0.200720,0.588806,-0.068274,-0.336445,0.070168,0.722236,-0.231476,-0.155045,0.095853,0.401966,-0.139112,0.167681,-0.087979,-0.086610,0.113161,-0.047878,-0.045503,-0.569864,-0.068871,0.213726,0.246089,-0.597731,0.297781,0.048200,-0.057427,0.380534,-0.376699,0.190846,0.154096,0.266037,0.392127,-0.076195,0.040461,-0.233178,0.365776,0.398439,0.237207,-0.455335,0.315438,-0.261953,-0.303534,0.025511,-0.325030,-0.575709,0.265122,0.146005,0.080057,-0.044776,0.144022,-0.093739,0.021839,-0.012136,-0.217018,-0.031473,-0.221720,-0.139661,-0.520289,-0.176480,-0.541600,-0.175447,0.092670,-0.030428,-0.312067,0.727704,-0.613880,-0.009678,0.245596,0.166136,-0.444518,0.440066,0.015052,-0.183292,-0.215763,0.068957,0.326770,-0.042379,0.233308,0.037800,0.333840,-0.086637,-0.165734,-0.309807,0.384532', '4233625', '26348103', '21348112', '4847665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26290365', '恶棍天使', '喜剧', '查小刀（孙俪 饰）智商极高，但性格软弱怕事，莫非里（邓超 饰）不过是一介混混，但个性嚣张跋扈，一场车祸让两人相遇，莫非里毫无意外的狠狠在查小刀的身上诈了一笔。亲情淡漠，工作受挫，又遭恶人欺压，查小刀心灰意冷，无意之中得知了有一位名为折耳根（梁超 饰）的神医专治各种疑难杂症，于是便起了向他寻求良方的念头。让查小刀没有想到的是，莫非里居然也是折耳根的病人，常年的失眠困扰着他令他痛不欲生。折耳根告诉两人，他们其实正是彼此的“良药”，为了“治病”，查小刀和莫非里结为搭档共同进退，惹出了无数的麻烦和笑话，与此同时，亦结下了深厚的感情。©豆瓣', '邓超', '俞白眉', 4.4, 164212, 'tt5297654', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2298326979.jpg', 34, 29.9, 24.5, 6.8, 4.8, '0.437790,-0.157091,-0.446436,0.429765,-0.274879,-0.187520,0.525516,-0.016589,-0.507149,-0.149474,0.080305,0.546038,-0.165396,0.002384,0.080630,0.036641,0.162508,-0.839544,0.132724,-0.200964,-0.244249,-0.370871,-0.443770,-0.118299,-0.122854,-0.155564,0.126384,0.095219,-0.470222,0.568348,0.198155,0.225167,-0.126160,0.295095,-0.172493,-0.099529,-0.179971,0.236868,0.127576,-0.056345,0.387881,-0.502090,-0.065967,0.418728,0.133508,0.712136,0.447289,-0.172674,-0.314683,-0.051839,0.339238,-0.135973,-0.073789,0.188521,0.200524,0.207599,0.414625,0.176641,-0.414450,-0.161424,0.311511,0.278538,-0.797889,0.177245,0.051019,-0.041129,-0.606178,0.393288,-0.084552,-0.295955,-0.210334,-0.127844,0.619393,0.092189,0.390064,0.129210,-0.197722,-0.376486,-0.300719,0.049476,0.523310,0.055242,-0.044490,0.078717,-0.163366,-0.138727,0.321202,-0.250041,-0.068577,-0.065544,0.201810,-0.126656,-0.366462,0.229423,-0.294797,0.144155,-0.354548,0.252118,-0.284482,-0.352490,-0.118653,-0.086053,-0.466736,-0.463048,-0.455130,0.030396,0.354038,-0.282339,0.413850,-0.776743,-0.074212,0.328083,0.060905,-0.520754,0.584429,0.202357,-0.123670,-0.004508,-0.145437,-0.056574,0.162550,0.000349,0.234331,0.138855,-0.062098,-0.156696,-0.059245,0.060539', '27202765', '1308050', '1301022', '1299195');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26290367', '谁的青春不迷茫', '爱情', '林天娇（郭姝彤 饰）是同学和老师们眼中公认的三好学生，不仅学习成绩优异，道德品质的高洁更是有目共睹。然而，在一场非常重要的考试之中，林天娇因为患上了感冒而发挥不佳，心急如焚的她想到了作弊，然而却因为作弊技术太差而东窗事发。让本以为一切都已经结束了的林天娇没有想到的是，同班同学高翔（白敬亭 饰）竟然替自己背了这个黑锅，要知道，高翔是那种林天娇最瞧不起的捣蛋王讨厌鬼，好吃懒做游手好闲简直一无是处。就这样，林天娇和高翔之间开始产生了奇妙的羁绊，林天娇越想远离高翔，就越是有一股奇妙的力量将两人凑在一次。随着时间的推移，两人都渐渐发现了彼此内心里不为人知的柔软一面。©豆瓣', '白敬亭', '姚婷婷', 6.7, 102298, 'tt5769516', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2332755749.jpg', 3.1, 11.1, 45.6, 28, 12.2, '0.610725,-0.131859,-0.819593,0.679246,-0.065284,-0.211947,0.660685,-0.111365,-0.658100,-0.301735,0.025089,0.479253,-0.500991,0.265996,0.191193,-0.271117,0.149620,-0.820815,-0.127638,-0.287000,-0.324891,-0.479933,-0.305822,-0.002899,-0.312015,-0.270987,0.553814,0.058583,-0.398332,0.370348,0.310152,0.007246,0.292861,0.537900,-0.108325,-0.080339,-0.148078,0.168957,0.186558,-0.103777,0.640591,-0.179546,-0.174668,0.325522,0.010881,0.220019,0.446289,-0.245323,-0.330037,-0.025247,0.517658,-0.488529,-0.317531,0.157140,0.293974,-0.079829,0.189572,0.033061,-0.192699,0.123582,0.235723,0.161308,-0.688979,0.159021,0.079566,-0.088305,-0.415141,0.411273,0.132523,-0.441682,0.265886,-0.375855,0.211543,0.278234,0.140503,0.431201,-0.346482,-0.104594,-0.434365,0.012334,0.758609,0.068274,-0.287849,0.465820,-0.158047,-0.297889,-0.061054,-0.255669,-0.231769,-0.026621,0.042131,0.346450,-0.061823,0.162828,-0.400547,0.144399,-0.057394,-0.150542,-0.262069,-0.611693,-0.160216,-0.208340,-0.466366,-0.616932,-0.269501,0.249638,0.022128,-0.546201,0.668313,-1.116796,0.139149,0.319530,0.051799,-0.492290,0.386480,0.238817,-0.110474,-0.140537,-0.351622,-0.117282,-0.056873,0.200917,0.176553,0.580326,-0.113760,-0.370501,-0.203576,0.738851', '35030151', '1301022', '1870682', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26290390', '精灵王座', '动画', '“人类少年小鱼受邀前往遥远神秘的精灵王国，参加精灵女王的婚礼。借此机会，他终于可以见到阔别已久的精灵女友莉雅。 黑暗精灵携大军突然闯入，胁迫女王交出传说中掌控精灵命脉、拥有至高力量的生命宝玉。在遭到反抗后，黑暗精灵强行劫走了女王。 精灵王国陷入惶恐，被卷入纷争的小鱼为了保护莉雅，毅然同精灵们一起踏上营救女王的冒险，可他没有想到的是，这次征途不仅充满危险，还将是对他以及他们间爱情的巨大考验。', '王梓', '宋岳峰', 7.9, 13238, 'tt5425264', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2372863469.jpg', 1.5, 4.1, 22.9, 39, 32.6, '0.048006,0.444785,-0.850635,0.475293,0.032115,-0.066059,0.942028,-0.284805,-0.536475,-0.049400,0.714435,0.601551,0.176717,-0.239963,0.597134,0.145755,-0.508900,-0.461988,-0.130411,0.006040,-0.226602,-0.170521,-0.409706,-0.007827,-0.189690,-0.882066,0.978691,0.112912,-0.320696,0.462689,-0.014797,0.377583,-0.486389,0.355266,0.017559,-0.386364,0.389801,-0.005284,-0.514746,0.609337,-0.436530,0.322690,-0.195652,0.452695,-0.306734,-0.102408,0.592983,-1.062592,0.288620,-0.507458,0.284692,-0.598121,-0.139801,-0.080276,0.375943,-0.094584,0.127645,-0.013522,-0.020597,-0.122447,0.163382,-0.396896,-0.598012,0.332901,-0.073809,0.321907,-0.537553,-0.059597,0.428085,-0.167542,0.548127,-0.336916,0.003139,0.315898,0.288373,0.326192,0.021233,0.166837,-0.282971,-0.053370,0.907715,-0.304326,-0.324206,-0.281080,-0.491607,-0.723169,0.208818,-0.447676,-0.700041,-0.021498,0.339296,0.309367,0.103819,0.776746,-0.795116,0.074576,-0.412211,-0.087330,0.272762,-0.600940,-0.259202,-0.513488,-0.112072,0.120820,0.072794,0.170919,0.493731,-0.096593,0.630392,-1.012507,0.776255,0.505907,0.656437,-0.614287,0.647290,0.050162,-0.072575,-0.089665,-0.130136,0.567519,0.090274,0.388914,0.033409,-0.273992,0.182602,0.044412,-0.210399,0.202755', '6974439', '4160441', '26759819', '4897786');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26290398', '美食大冒险之英雄烩', '动作', '这是一个美食构成的世界。传说女娲以神通铸成五味石，赋予食物味道和灵魂。在这里山川、湖泊都由美食组成：芝士崖、面包山、洋葱石林、鸡汤湖……形形色色的食物生活在这个世界，有着自己的故事和江湖。武艺平平的包子包强( 杨光普照 配音)，为了实现自己的英雄梦想，加入了面仙国的舰队出海抗击海盗，却遭到了咸鱼海盗伏击。一番混战后，包强和海盗雇佣的赏金浪人寿司武藏（孟宇 配音）流落荒岛，为了找到各自的伙伴，水火不融的两人开启了一段啼笑皆非的冒险。', '杨光普照', '孙海鹏', 6.8, 4352, 'tt8769226', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2569607978.jpg', 1.9, 14.9, 40.3, 26.6, 16.2, '-0.085863,-0.019788,-0.448722,0.801507,0.125646,-0.062483,0.587759,0.348095,-0.366722,0.035122,0.265554,0.888148,0.253109,-0.015682,0.214082,-0.128562,-0.163039,-0.306632,0.093461,-0.200415,-0.208606,-0.162125,-0.300156,-0.191186,-0.058024,-0.345570,0.932807,0.151404,-0.177762,0.067626,-0.027429,-0.122822,-0.328664,0.439224,-0.225538,0.118710,0.056355,0.181075,-0.541720,0.010914,-0.595502,-0.088811,0.004411,0.153210,-0.062306,0.014061,0.856162,-0.428590,-0.128892,-0.305947,-0.114835,-0.321170,-0.115871,-0.369671,0.545544,-0.177403,0.144589,-0.085478,0.178936,0.059770,0.079478,-0.070943,-0.722998,-0.558500,0.200586,-0.027351,-0.300268,0.252966,0.085231,-0.059163,-0.089296,-0.169735,0.096888,0.273142,0.631619,0.406914,-0.134305,0.098563,-0.669796,0.370456,0.566268,-0.090761,0.220543,0.176281,-0.445702,-0.551507,-0.039272,-0.264114,-0.100825,-0.083078,0.334116,0.011014,-0.228656,0.368378,-1.318439,0.111574,0.120603,-0.260303,0.394361,-0.268612,-0.502388,-0.688022,0.061185,0.059921,-0.065220,0.071058,0.289449,0.119137,0.979680,-0.636133,0.112415,0.595148,-0.011960,-0.328115,0.680456,-0.061933,-0.031423,-0.468210,-0.009982,0.398825,-0.026547,0.440691,0.292257,0.440886,-0.064566,0.172635,-0.525680,0.200594', '4181031', '1302661', '24879819', '26839466');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26290642', '致青春·原来你还在这里', '剧情', '外表温柔安静的苏韵锦（刘亦菲 饰）在高中同学程铮（吴亦凡 饰）的深情追求下慢慢爱上了对方，可无奈相爱容易相处难，自小生活环境的差异以及性格的迥异开始成为两人之间的问题，矛盾的不断发现最终还是让感情出现了裂痕最后走到了分手境地。几年后，苏韵锦成为了一个事业有成的职场女强人，但平静的生活因程铮的再次出现而泛起了涟漪，两人剪不断理还乱的感情促使他们又纠缠到了一起，并且这时才知道彼此在这几年中都没有放下，想爱但又怕过去重演……©豆瓣', '刘亦菲', '周拓如', 4.3, 162489, 'tt5011290', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2363083099.jpg', 37.4, 29.7, 20.6, 6.4, 5.9, '0.488904,0.287708,-0.860519,0.636402,-0.096400,-0.420274,0.835527,0.165927,-0.380095,0.051445,-0.015614,0.568986,-0.257587,0.273796,0.022405,-0.140806,-0.204172,-1.127754,0.324722,-0.297777,-0.223330,-0.536022,-0.085617,0.063730,-0.229095,-0.261938,0.621690,0.257390,0.034855,0.633343,0.200776,0.128098,-0.231236,0.665682,-0.217460,-0.012057,-0.087133,0.241963,-0.442085,-0.036475,0.181912,-0.240758,-0.006712,0.231516,-0.019315,0.298022,0.734914,-0.138276,-0.396750,0.479813,0.493297,-0.103281,-0.271363,0.108330,0.453632,0.211816,0.122919,0.075258,-0.342196,-0.187575,-0.082153,0.128738,-0.315411,0.274710,-0.055414,0.257636,-0.644958,0.658870,0.337784,-0.428040,-0.159963,-0.153834,0.218404,0.509906,0.694597,0.370245,-0.410369,0.199619,-0.102891,-0.036037,0.803108,0.279255,-0.547546,0.682084,-0.420035,-0.288678,-0.151734,-0.365330,-0.265988,-0.323227,0.182928,0.298222,-0.330190,0.384900,-0.595862,0.181758,0.058214,0.159305,-0.011937,-0.685954,-0.118753,-0.180093,-0.735815,-0.833654,-0.619664,0.211707,-0.340886,-0.534195,0.539574,-0.902769,0.196629,0.273429,0.250089,-0.626203,0.603151,0.158730,-0.089416,-0.002844,0.146029,0.368864,-0.356284,-0.094388,0.390575,0.478790,-0.207622,0.225157,-0.489997,0.437882', '1302109', '34973399', '25777330', '2027925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26295860', '流浪的迪潘', '剧情', '该片讲述在斯里兰卡，内战已经快要结束，无数难民等待着离开这片被战火摧残的土地。为了更容易申请政治庇护，年轻的女人雅丽妮（Kalieaswari Sriniv饰）、曾经效力泰米尔猛虎组织的战士迪潘（杰苏萨桑·安东尼萨桑饰）和9岁的失去父母的小女孩伊莱娅（Claudine Vinasitha饰）冒充一家人，来到法国巴黎近郊开始了新生活。迪潘在这片贫民聚集的郊区找到了一个公寓管理员的工作，不会法语的雅丽妮也在一户人家做家政，“女儿”伊莱娅则进了附近的学校。生活看起来在往好的方向发展，但充斥着暴力、毒品、犯罪的巴黎郊区，注定不会是他们平静生活的净土，当命运不可逆抗，迪潘只好用自己最熟悉的手段，守护这个由三个陌生人组成的相依为命的“家庭”。', '樊尚·罗蒂埃', '雅克·欧迪亚', 7, 6691, 'tt4082068', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2267673050.jpg', 0.8, 4.6, 45.2, 40.7, 8.6, '0.403527,-0.030036,-0.681059,0.478897,-0.194740,-0.223785,0.688392,0.236504,-0.239319,-0.346026,0.193557,0.748462,0.217883,0.333021,0.269986,0.201457,-0.498416,-0.517003,-0.015357,-0.169409,-0.419229,-0.390753,0.035357,-0.468411,-0.130194,-0.279487,0.555147,0.159010,-0.045738,0.095297,0.109683,0.324365,-0.057704,0.174576,-0.374046,-0.118188,0.101614,-0.063836,-0.396589,0.351440,-0.183362,0.015292,-0.047991,-0.052007,0.206202,0.251544,0.887425,-0.238578,0.056471,-0.024266,0.323266,-0.433066,-0.184140,0.060339,0.274007,-0.284103,0.264097,-0.016756,-0.295124,0.074023,0.001106,-0.390749,-0.588158,-0.079983,0.161097,0.179154,-0.530492,0.526661,0.215145,-0.296273,0.099383,-0.384257,0.306240,0.540863,-0.165445,0.547624,-0.230819,0.154961,-0.511282,0.071427,0.832961,0.020369,-0.148783,0.216122,-0.467573,-0.359749,0.003892,-0.135670,-0.685224,-0.243931,0.204230,-0.186637,-0.155323,0.382895,-0.753852,-0.042589,-0.255350,-0.244913,0.288982,-0.506325,-0.258186,-0.604119,0.020880,-0.352698,-0.203380,0.343240,-0.096257,-0.095931,0.703410,-0.899602,0.162490,0.454214,0.543019,-0.465556,0.502176,-0.057105,0.243435,-0.331342,-0.082622,0.748032,-0.005981,0.577920,0.114703,0.218890,-0.084940,-0.028704,-0.418679,0.641723', '2032339', '27042738', '1292219', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26296258', '胡丽叶塔', '剧情', '胡丽叶塔（阿德丽安娜·尤加特 Adriana Ugarte 饰）和苏安（丹尼尔·格劳 Dani Grao 饰）相识于一列疾行的火车之上，之后两人相爱，结婚，生下了可爱的女儿安蒂亚（布兰卡·帕雷斯 Blanca Parés 饰），一家三口生活在幸福美满之中。某日，胡丽叶塔和苏安发生了争执，苏安一怒之下扬帆出海，却遭遇了风暴丧生海底，绝望的胡丽叶塔患上了抑郁症。安蒂亚和好友碧亚（米歇尔·珍娜 Michelle Jenner 饰）共同照顾着魂不守舍的胡丽叶塔，一晃眼就是很多年过去，虽然胡丽叶塔的病情渐渐好转，但她对女儿的依恋和依赖却越来越深。在十八岁生日那天，安蒂亚不告而别，从此下落不明，胡丽叶塔在愤怒、委屈和惊恐之中疯狂的寻找着有关女儿的蛛丝马迹，但始终都是徒劳。©豆瓣', '埃玛·苏亚雷斯', '佩德罗·阿莫多瓦', 7.5, 15034, 'tt4326444', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2322750048.jpg', 0.4, 2.4, 34, 49, 14.1, '0.082155,-0.084800,-0.960294,0.394762,0.265284,-0.485046,1.074523,0.086849,-0.511088,-0.289575,0.005231,0.716200,-0.207478,0.570791,0.150745,0.156995,-0.272534,-0.775039,0.114153,-0.178873,-0.238844,-0.771024,-0.238645,0.007512,0.033353,-0.467942,0.269927,0.196718,0.065916,0.880775,0.482581,0.186488,-0.406091,0.794353,-0.190952,0.098101,0.001734,0.190111,-0.223047,-0.193802,0.182156,-0.352262,-0.015572,0.022090,0.212121,0.507143,0.735748,-0.104006,-0.225573,-0.122126,0.203008,-0.149103,-0.150120,0.279143,0.410627,0.061212,0.167695,0.059558,-0.365124,-0.184401,-0.109459,0.082183,-0.460467,0.301653,0.147448,0.208423,-0.734836,0.554692,-0.065123,-0.165662,0.129034,-0.398609,0.337421,0.471826,-0.024343,0.484030,-0.319039,0.104676,-0.457905,-0.013593,0.735154,0.014851,-0.120959,0.371249,-0.165155,-0.132849,-0.105244,-0.136376,-0.723883,0.046531,0.259760,0.241142,-0.330636,0.560177,-0.436153,0.103024,-0.298921,-0.107192,-0.108963,-0.302552,-0.045824,-0.372553,-0.179880,-0.667010,-0.478000,0.081826,-0.234455,-0.347060,0.565885,-0.660010,0.435322,0.270628,0.462744,-0.456355,0.639178,0.324834,0.138240,-0.058636,0.113188,0.689877,-0.147140,-0.152291,0.304830,0.304502,0.017398,0.433535,-0.463360,0.478669', '3111650', '1300945', '21348112', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26297388', '这时对，那时错', '剧情', '影片由两部分组成，男主角HaｍChunsu是一位电影导演，他偶然的一次机会下邂逅了女艺术家YoonHeejung。两人通过咖啡、寿司晚餐距离渐进，当YoonHeejung得知HaｍChunsu已经结婚后，十分失望伤心。第二部分展示了一个相通的故事，却有着微妙不同的结局。曾在东京、戛纳、洛迦诺等国际电影节屡获大奖，以独特文艺风格闻名世界影坛的韩国独立电影导演洪尚秀，今年最新力作《这时对，那时错》也将亮相福州。《这时对，那时错》今年一举摘取洛迦诺国际电影节金豹奖、最佳男主角、最佳评委推荐等奖项，一部风格独特的文艺片佳作。', '郑在泳', '洪常秀', 7.6, 27871, 'tt4768776', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2264531221.jpg', 0.9, 3.7, 29.2, 47.6, 18.6, '-0.182746,0.172864,-0.468879,0.843502,0.551500,-0.031823,0.498927,0.137216,-0.434645,-0.137055,0.179389,1.049270,-0.555374,-0.098609,0.407080,-0.233047,-0.280188,-0.551328,-0.072885,-0.231237,0.124653,-0.134162,-0.449494,0.456161,-0.203786,-0.233959,0.857879,-0.025142,-0.508026,0.631524,0.674773,-0.164650,0.004148,-0.006759,-0.020672,-0.108656,0.468078,-0.015598,-0.626967,0.585204,0.080688,-0.319824,-0.125344,0.034571,-0.022658,0.231201,0.678812,-0.054664,-0.303412,0.086516,0.824483,0.077700,-0.211157,-0.068552,0.177934,-0.016047,0.554169,0.111030,0.024063,0.103504,-0.424257,-0.270783,-0.789824,0.049978,0.222903,-0.000689,-0.398536,0.454911,-0.047648,-0.024910,0.036220,-0.065063,0.222284,0.210225,0.746877,0.110893,0.178598,0.311792,-0.122722,0.534110,0.679940,0.180359,-0.179026,0.607280,-0.118802,-0.634949,-0.136746,-0.302619,-0.269793,0.545713,0.352671,-0.025632,0.335019,-0.282353,-0.422423,-0.172665,0.111143,-0.143536,0.252346,-0.154929,0.217904,-0.810275,0.035154,0.079568,-0.031366,-0.318495,0.125092,-0.218088,0.836534,-0.581061,0.172048,0.266821,0.136083,-0.240343,0.940508,0.280182,-0.168734,-0.657466,-0.127188,0.147943,-0.312415,-0.144256,-0.181929,0.430394,0.113119,-0.596309,-0.503921,0.343334', '22265121', '27602116', '25880986', '30397916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26299410', '梦想合伙人', '剧情', '这是一个讲述三个阶层不同性格不同的女人为金钱、家庭、地位共同淘金的故事。留学生卢珍溪（姚晨 饰）在美国卖假包被驱逐回国，商场精英文清（郝蕾 饰）遭遇小三插足，灰姑娘顾巧音（唐嫣 饰）家庭贫寒只想嫁个有钱人。她们从一开始的死对头变成好闺蜜，并在事业导师孟晓骏（郭富城 饰）和卢珍溪的发小俊成(李晨 饰)的支持下，成为追求财富、爱情和地位的合伙人。她们短时间内取得巨大成功。不过好景不长，公司在市场激烈竞争下出现严重问题，陷入困局，同时三人的关系也出现破裂。面对困境，卢珍溪承受严峻考验的同时，为梦想和合伙人走出了坚定的一步……©豆瓣', '姚晨', '张太维', 4.4, 35386, 'tt5190872', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2340134467.jpg', 34.1, 31.6, 20.9, 5.9, 7.5, '0.137941,0.173500,-0.386071,0.517152,0.058406,-0.044785,0.512437,0.309553,-0.306155,-0.295951,0.109884,0.800631,-0.133647,0.141004,0.235010,-0.299239,-0.116813,-0.665354,0.064105,-0.112377,-0.087904,-0.541499,-0.194141,-0.204619,-0.319880,-0.092966,0.740700,0.079002,-0.388331,0.408892,0.486686,0.213440,-0.243254,0.169477,-0.028700,-0.078725,0.217952,0.422383,-0.793536,0.176783,-0.306786,0.221576,0.028966,-0.126190,0.120992,0.009240,0.467602,-0.150837,0.019181,-0.001831,0.499947,0.031102,-0.421619,0.095622,0.340530,0.058956,0.267855,0.296561,-0.172388,0.082107,0.106952,-0.235219,-0.811403,-0.019312,0.320588,0.105198,-0.601186,0.370984,0.100499,-0.288730,0.113452,-0.133234,-0.142015,0.486832,0.482590,0.544347,-0.274677,0.387915,-0.409259,0.114721,0.864866,0.121762,-0.261695,0.309104,-0.278715,-0.330476,-0.275589,-0.191673,-0.367627,-0.219117,0.215838,0.010098,0.011763,0.288718,-0.550762,0.091342,0.081542,-0.202748,0.398841,-0.452289,0.014174,-0.530503,-0.441194,-0.250068,-0.398677,0.252931,0.166107,-0.392433,0.897191,-0.688601,-0.057872,0.133181,0.487894,-0.853466,0.602978,0.191978,0.273471,-0.466983,-0.334592,0.365960,-0.099578,-0.135958,-0.327216,-0.026331,-0.389599,-0.123047,-0.249730,0.218115', '26678784', '4301278', '1308424', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26301582', '微微一笑很倾城', '爱情', '本片讲述了一对大学风云人物肖奈（井柏然 饰）和贝微微（杨颖 饰）在虚拟游戏与真实世界中相识相爱的故事。计算机系花贝微微热爱网络游戏，技术娴熟高超，是游戏排行榜上唯一的女玩家，而她却因为不爆照片被认为是人妖，“惨遭”游戏里的“老公”的抛弃。在“前夫”的婚礼现场，她偶遇了游戏里的第一高手“一笑奈何”，更让她出乎意料的是，这名大神竟然向她求婚。游戏里的高手“一笑奈何”正是现实中著名的计算机系大神肖奈。在一次偶然邂逅里，他无意中见识到贝微微熟练的游戏操作，由此对她产生了不一样的情愫，而贝微微却完全没意识到爱神的降临。闻名于校园的肖奈大神，开始了线上线下、虚拟与现实中全方位地捕猎美人心。一段始于二次元的奇幻网游爱情，悄然开始……本片改编自顾漫的同名小说。©豆瓣', '井柏然', '赵天宇', 4.9, 135154, 'tt6091936', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2358355793.jpg', 22.8, 31.4, 30.9, 9.1, 5.7, '0.511628,0.343253,-0.750723,0.794743,0.142086,-0.116409,0.760120,-0.382244,-0.510647,-0.173918,0.113002,0.828291,-0.630563,0.290283,0.232572,0.047872,-0.149094,-0.672922,-0.376489,-0.310156,-0.305968,-0.193606,-0.561451,0.144561,-0.170756,-0.107808,0.724141,0.092891,-0.557284,0.510458,0.229564,0.166131,-0.165675,0.372498,-0.121301,0.048950,-0.009056,0.248378,-0.174823,0.261946,-0.119512,-0.338501,-0.137216,0.207716,-0.013657,0.138677,0.842781,-0.550802,0.010507,0.131721,0.558949,-0.285672,-0.490390,-0.240300,0.273796,0.097230,0.366786,-0.074566,0.219635,0.092557,-0.013427,-0.265933,-0.787956,-0.043396,0.047105,0.190686,-0.169932,0.264649,-0.278657,-0.100513,0.051004,-0.221870,0.132687,-0.196428,0.738753,0.399732,-0.026626,-0.064694,-0.193585,0.618125,0.435377,0.325193,-0.322002,0.705291,-0.161991,-0.630308,-0.381050,-0.201604,-0.377495,0.009518,0.283234,-0.078257,-0.138426,0.646466,-0.668494,0.194646,0.227650,-0.031419,-0.157475,-0.378387,-0.124982,-0.765241,-0.384449,-0.487676,-0.162629,0.081039,0.185541,-0.553077,0.725345,-1.275570,0.132366,0.554344,0.136156,-0.226220,0.818424,0.215466,0.077336,-0.123980,-0.114286,0.233550,0.048942,0.152278,0.048844,0.594299,-0.223037,-0.198849,-0.598232,0.567340', '1420088', '25880986', '3811356', '2287938');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26301662', '男神时代', '喜剧', '妖子（李菲儿 饰）是车水马龙的大都市中一名平凡的不能再平凡的小白领，某日，公司聚会上喝醉了的她居然误打误撞的和英俊帅气的上司林子松（任言恺 饰）有了一段露水情缘。之后，妖子又在酒店和初恋情人王轩逸（李贤宰 饰）重逢，场面十分尴尬。让妖子没有想到的是，如今已经飞黄腾达家财万贯的王轩逸，竟然还没有忘记和她之间的那一段往事，想要和自己重修旧好，然而，就在两人感情逐渐升温之时，林子松却再次出现在了妖子的身边。就这样，妖子陷入了一段复杂的三角恋情之中，不知该如何选择。与此同时，霸道总裁林子松的追求者众多，她们亦将妖子视为眼中钉肉中刺，想要彻底将她打败。©豆瓣', '任言恺', '徐正超', 3.4, 5250, 'tt5004800', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2263775515.jpg', 61.1, 20.6, 10.6, 3.6, 4.2, '0.558471,0.394092,-0.616342,0.554252,-0.041263,-0.583350,1.052392,0.086563,-0.480134,-0.083457,0.092376,0.569479,-0.483567,0.158523,0.226640,-0.061672,-0.126732,-0.707706,-0.146784,-0.322187,-0.231278,-0.327266,-0.485452,0.263950,-0.240897,-0.179393,0.819452,0.048531,-0.046127,0.469042,0.603886,0.186836,-0.244665,0.608609,-0.334140,0.144860,0.068934,0.488776,-0.218862,0.021059,-0.045897,-0.337344,-0.300845,0.304612,-0.212195,0.154216,0.675960,0.025877,-0.394544,-0.057385,0.268930,-0.141940,-0.144304,0.083283,0.338565,-0.165814,0.321087,0.153525,-0.341465,-0.205784,0.016640,0.225957,-0.578373,0.077395,0.109527,0.148601,-0.545475,0.509338,-0.052650,-0.329854,0.176790,-0.578437,0.405418,0.433384,0.381034,0.300525,-0.067324,-0.045992,-0.528038,0.160550,0.750058,0.354503,-0.255838,0.423762,-0.123306,-0.381141,-0.159420,-0.026913,-0.471419,-0.056123,0.281544,0.198946,-0.419882,0.365926,-0.460538,-0.051535,-0.269452,0.021000,0.006141,-0.515188,-0.069081,-0.249276,-0.433442,-0.511893,-0.399015,0.379822,0.110549,-0.264470,0.514388,-1.062021,0.207384,0.282929,0.234924,-0.274725,0.419313,0.142684,-0.104662,-0.056165,-0.096345,-0.233108,-0.202009,0.367350,0.383570,0.695727,-0.369124,-0.262272,-0.543409,0.537975', '1308755', '4275444', '21766698', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26301701', '你好，我叫多蕾丝', '剧情', '年逾花甲的多蕾丝仍旧有著一颗渴望爱情的少女心，在一场自助会中她遇到了年轻的白马王子！年龄不是问题，多蕾丝决定为了她的真爱展开追爱行动！', '莎莉·菲尔德', '迈克尔·肖沃特', 7.1, 10437, 'tt3766394', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2286292271.jpg', 0.8, 5.7, 44.1, 37.8, 11.5, '0.162193,0.266751,-0.849519,0.401013,-0.717237,-0.104426,1.075083,-0.121188,-0.370440,0.022870,0.401633,0.674765,-0.312854,0.242746,0.161966,-0.006281,-0.199958,-0.429086,0.250331,-0.159116,-0.027230,-0.354593,-0.399821,-0.066182,0.086237,-0.438728,1.057634,0.459867,-0.144657,0.100533,0.670762,-0.149049,0.349188,0.381307,0.007506,-0.471412,0.190763,0.173601,-0.322871,0.363775,0.079743,-0.152822,-0.074419,0.662848,-0.253269,0.159924,0.759202,-0.465760,-0.218746,0.124489,0.509636,-0.033462,0.284256,0.115003,0.225533,0.065841,0.288904,0.125263,0.065399,0.150006,0.191935,-0.236528,-0.622738,-0.300027,0.289881,0.409390,-0.568041,0.433378,-0.352331,-0.371493,0.396146,-0.544443,-0.295952,-0.053609,0.556886,0.223331,-0.134241,-0.000714,-0.487220,0.364268,0.886024,0.275428,-0.221715,0.714305,-0.565820,-0.421852,-0.084194,-0.144732,-0.465997,-0.015554,0.414987,-0.112691,-0.255299,0.342768,-0.446719,0.290601,-0.357306,0.003257,0.051736,-0.240536,-0.349800,0.207124,-0.166072,-0.686187,-0.332148,0.185505,0.136173,-0.387179,1.043680,-1.088662,0.017929,0.893301,0.195738,-0.559182,0.411828,0.515629,-0.057508,-0.307943,-0.151388,0.709279,-1.039257,-0.210675,-0.160763,0.237390,-0.042897,-0.081202,-0.479504,0.349933', '35030151', '3005387', '21619567', '26345159');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26301735', '吉星高照2015', '喜剧', '王祖蓝（王祖蓝 饰）是一位山寨明星经纪人，某日，在带着手下一帮山寨明星参加一位香港土豪的生日宴会时不慎东窗事发，情形十分危急。阿超（温超 饰）是土豪的准女婿，他向王祖蓝伸出了援手，王祖蓝发现阿超的声音和星爷极为相像，于是大力举荐他到香港发展，认定其星途无量。在香港，阿超结识了王祖蓝的妹妹王祖红（陈嘉桦 饰），王祖红是星爷的超级粉丝，平生最恨他人靠模仿星爷赚取眼球，无奈阿超的声音和星爷实在太过相似，为讨王祖红的欢心，阿超只能在她面前装聋扮哑。然而，就在两人的距离渐渐靠近之时，阿超的伪装穿帮了，愤怒的王祖红选择了离开。©豆瓣', '曾志伟', '晴朗', 3.4, 2883, 'tt4483094', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2229854022.jpg', 57.9, 23.9, 12.8, 2.7, 2.7, '0.048267,0.090470,-0.433868,0.689752,0.144265,-0.166520,0.667788,0.421172,-0.412453,-0.153582,0.161666,0.661945,-0.481537,0.375494,0.372948,0.040987,0.222318,-0.528191,-0.259402,0.039809,-0.144519,-0.559492,-0.097858,-0.242488,-0.197451,-0.233918,0.376810,0.167439,-0.336772,0.478115,0.815282,0.164325,-0.173863,0.638604,-0.274258,-0.289545,-0.019545,-0.009270,-0.164948,0.116466,-0.053567,-0.317226,-0.098689,0.101319,-0.125684,0.229668,0.246698,0.082083,-0.069168,0.106995,0.370787,-0.206620,0.109811,-0.003092,0.276927,-0.258069,0.298845,-0.138575,-0.155522,0.043346,-0.024373,0.020845,-0.578830,0.338740,0.127854,0.124564,-0.758386,0.266106,-0.121469,-0.028263,0.153673,-0.360994,0.043643,-0.020575,-0.115571,0.292936,-0.086060,0.172721,-0.259182,0.089884,0.502010,0.141112,0.042715,0.324667,0.275258,-0.561361,-0.141480,-0.155334,-0.377463,0.021046,0.458330,-0.190062,0.150005,-0.086039,-0.465873,-0.263965,0.036533,-0.071517,0.115438,-0.210895,0.019744,-0.391442,-0.079232,-0.505425,-0.438219,0.038837,0.126218,-0.344877,0.799581,-0.823458,-0.107449,0.414348,0.243619,-0.430096,0.700508,-0.073548,-0.244504,-0.324624,-0.128775,0.026758,0.092698,-0.008790,0.274708,0.227052,-0.321317,-0.298505,-0.251301,0.330477', '1292720', '1438708', '1292219', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26303353', '粉与灰', '剧情', '河田大贵（菅田将晖 饰）、铃木真吾（中岛裕翔 饰）和石川纱里（夏帆 饰）是青梅竹马的好友和玩伴，彼此之间感情十分要好。大贵和真吾两人都热爱音乐，共同的爱好让两人的灵魂更加接近。高中毕业之后，机遇找到了大贵和真吾，由于样貌英俊帅气，真吾从最初的读者模特一路走高最终成为了星光闪闪的偶像，还成立了自己的事务所。眼看着自己和好友之间的距离越来越远，仕途不顺的大贵内心里怎么可能会好受，就这样，他们的友情在平静之中慢慢走向破裂，最终，两人失去了联系，踏上了各自的人生道路。一晃眼多年过去，在同学会上，大贵和真吾重逢了。真吾邀请大贵到自己家中做客，哪知道当大贵登门拜访之时，等待着他的却是真吾冰冷的尸体。©豆瓣', '中岛裕翔', '行定勋', 7, 9532, 'tt4360406', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2306406702.jpg', 0.8, 5.6, 45.9, 36.8, 10.9, '0.298887,-0.070731,-0.732193,0.465643,0.213778,-0.468357,0.538265,0.182925,-0.555811,-0.128850,-0.064882,0.787705,-0.366211,0.442987,0.332598,-0.071452,-0.210160,-0.787971,-0.072713,-0.214520,-0.307688,-0.432071,-0.440935,0.312760,-0.399450,-0.210747,0.553980,0.164931,0.147864,0.569370,0.188670,0.049602,-0.159081,0.440880,-0.198596,0.060702,-0.064293,0.352726,-0.247219,0.117537,0.167396,-0.030684,-0.135193,0.015583,-0.046251,0.291866,0.524646,-0.069263,-0.173530,-0.048498,0.162996,-0.136666,-0.029235,0.215290,0.226755,0.013583,0.396509,0.408780,-0.304138,0.018860,-0.125745,0.030351,-0.395006,0.197458,-0.042414,0.148513,-0.610990,0.561739,0.152829,-0.475687,0.309157,-0.416681,0.194263,0.411357,0.210369,0.283180,-0.412799,-0.021579,-0.322216,-0.029472,0.772428,0.295193,-0.157218,0.310795,-0.031179,-0.534595,-0.178092,-0.073588,-0.410961,-0.273330,0.353070,0.379459,0.147723,0.058103,-0.598574,0.053501,0.033882,0.224174,0.129364,-0.465982,0.181672,-0.438159,-0.171993,-0.823066,-0.301405,0.255047,0.110206,-0.381893,0.798113,-0.853285,0.013626,0.374126,0.434241,-0.436229,0.665208,0.174584,-0.074752,-0.194879,-0.052647,0.003984,-0.133019,0.277234,0.300540,0.299341,-0.118850,0.057562,-0.458777,0.505102', '1292219', '26354526', '35030151', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26303622', '大空头', '剧情', '2008年全球金融危机，华尔街几位眼光独到的投资鬼才在2007年美国信贷风暴前就看穿了泡沫假象，通过做空次贷CDS而大幅获益，成为少数在金融灾难中大量获利的投资枭雄。贾瑞德·韦内特（瑞恩·高斯林饰）将一个能把40亿美元单子做成37亿美元收入的德银代理人，迈克尔·布瑞（克里斯蒂安·贝尔饰）是独眼基金管理人，马克·鲍姆（史蒂夫·卡瑞尔饰）是华尔街世家出身，本·霍克特（布拉德·皮特饰）是康沃尔资本退休银行家。', '克里斯蒂安·贝尔', '亚当·麦凯', 8.5, 216792, 'tt1596363', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2283531871.jpg', 0.2, 0.9, 11.9, 46.8, 40.1, '-0.228731,0.137139,-0.268158,0.321695,0.005461,-0.317657,0.224275,0.099295,-0.410577,-0.351811,-0.006706,0.757962,-0.114142,0.214605,0.284821,0.155831,-0.079579,-0.432354,-0.253545,-0.389689,0.061104,-0.743865,-0.608118,-0.571208,-0.204883,-0.378532,0.274498,0.056472,-0.248749,0.107515,0.251107,0.537804,0.247354,0.092530,0.051030,-0.138347,0.354343,-0.335116,-0.502845,0.447587,-0.412376,-0.247937,0.029708,-0.078746,0.543936,0.173238,0.192300,0.016222,0.715481,-0.148231,0.284141,-0.129375,-0.050874,-0.024809,0.293324,-0.151000,0.205278,0.264227,-0.495874,-0.062756,0.252098,-0.425628,-0.793234,-0.206107,-0.289576,0.331978,-0.631578,0.101020,-0.411761,0.182639,-0.434580,-0.178611,-0.233435,0.116140,0.353349,0.205259,0.080381,0.315909,-0.831164,0.341787,0.199363,0.029312,-0.475215,0.044851,-0.211029,-0.435615,-0.148520,-0.348203,-0.066767,-0.228912,0.821466,-0.299068,0.329606,0.627833,-0.612850,-0.152956,-0.413330,-0.370745,0.083892,-0.066340,-0.092015,-0.650108,-0.259268,-0.402539,-0.274568,-0.097929,0.390692,-0.399737,0.713292,-0.232004,-0.241552,0.526230,0.376698,-0.090512,0.771351,-0.487790,0.238742,-0.160429,-0.102958,0.046451,0.249563,-0.155461,0.064741,-0.021907,0.172001,-0.625331,0.622521,0.575413', '1308457', '30387441', '4920389', '2138299');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26303865', '维多利亚', '剧情', '维多利亚（莱阿·科斯塔 Laia Costa 饰）是一个刚刚来到柏林的西班牙少女，某日，她在街上闲逛，邂逅了名叫索恩（弗雷德里克·劳 Frederick Lau 饰）的男孩。索恩的放荡不羁很快就吸引了维多利亚的注意，让她对他平添了一份好感。之后，维多利亚又见到了索恩的三个好友博克斯（弗兰茨·罗戈夫斯基 Franz Rogowski 饰）、布林克（布拉克·伊依特 Burak Yigit 饰）和弗斯（马克思·马福 Max Mauff 饰）。让维多利亚没有想到的是，这群男孩在当晚有一个非常重要的计划要执行——抢劫银行，而本该是四人的小组，却因为其中一人烂醉如泥而急需吸收新鲜血液。就这样，维多利亚成为了他们的最佳选择。©豆瓣', '莱娅·柯丝达', '塞巴斯蒂安·席佩尔', 7.1, 12922, 'tt4226388', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2226445259.jpg', 2.4, 8, 35.2, 39.2, 15.2, '0.416802,0.113446,-0.717583,0.614759,-0.167494,-0.488934,0.924178,0.255985,-0.395254,-0.137733,0.175308,0.867419,-0.209293,0.135004,0.542820,0.126230,-0.383626,-0.572127,-0.127138,-0.144884,-0.317811,-0.626810,-0.185846,-0.196546,-0.175091,-0.473979,0.312447,0.006110,-0.034964,0.544894,0.399097,0.552652,0.210445,0.655914,-0.237177,0.097152,0.438750,-0.195316,0.258162,0.475139,0.158775,-0.213343,-0.158105,0.322828,0.099669,0.477261,0.573826,-0.128082,-0.007815,-0.054864,0.161058,-0.124760,0.157917,-0.120021,0.294111,-0.473638,0.027877,0.032305,-0.347002,-0.057709,0.215514,-0.034124,-0.715403,0.135631,0.049156,0.292237,-0.664884,0.459744,-0.181924,-0.223488,0.138563,-0.265573,0.174721,0.429849,0.097902,0.116081,0.233146,-0.208592,-0.629455,0.118712,0.474954,-0.099825,-0.201892,0.486804,-0.379548,-0.331849,0.136274,-0.014898,-0.281427,-0.074545,0.413785,-0.005750,0.205743,0.062156,-0.721618,-0.014403,-0.504160,-0.269873,0.073568,-0.428550,-0.062684,-0.677307,-0.097777,-0.357692,-0.514128,0.294791,-0.001826,-0.112633,0.776668,-0.886557,0.061086,0.744062,0.113499,-0.349793,0.649891,-0.065653,0.105655,-0.250487,0.100274,0.210905,0.152403,-0.039055,-0.013540,0.598888,0.135060,-0.342415,-0.435031,0.549338', '1301686', '1309172', '1292062', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26304167', '出租车', '剧情', '一辆黄色出租车行驶在德黑兰熙熙攘攘的街道上。各种各样的乘客坐上车，每人都直率坦白地回答了司机的各种问题。而这个司机不是别人就是导演贾法•帕纳西本人。在这个移动摄影棚中，导演将摄像机放在仪表板上，通过这次有趣而戏剧的旅程，记录了伊朗社会的精神风貌。导演说：“我是一名电影工作者，我什么都不做，只拍电影。电影是我的语言和生命的意义。没有什么能阻挡我拍电影。因为当我被推入最深的角落时，我与自我相连。在如此私密之处，尽管限制诸多，创作的需求已超越了欲望。我心系电影艺术。这就是为什么无论如何，我都要继续拍电影。只有这样，我才能尊重自己，感受到我还活着。”', '贾法·帕纳西', '贾法·帕纳西', 8.1, 18813, 'tt4359416', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2236812017.jpg', 0.5, 2, 18.2, 51, 28.4, '0.347338,0.187386,-0.700440,0.645902,-0.310513,-0.184287,0.871027,-0.017430,-0.261312,0.003676,0.174243,0.708184,-0.003026,0.110362,0.015911,0.187413,-0.483302,-0.551388,0.021543,0.106069,-0.385574,-0.593031,-0.131917,-0.112438,-0.191417,-0.016343,0.562230,0.085028,-0.517377,-0.173783,0.185987,-0.102464,0.082562,0.610176,-0.259561,-0.077708,-0.070096,-0.019844,-0.079385,0.040741,0.091948,-0.371806,-0.003983,0.291298,-0.070521,0.240537,0.507110,-0.096207,-0.156501,0.350538,0.316618,-0.449955,0.237671,0.040254,-0.297473,-0.120562,0.236953,0.267579,0.006466,0.056879,-0.136449,0.089175,-0.974304,-0.275236,-0.291283,0.277670,-0.730560,0.437042,-0.211236,-0.329058,0.040208,-0.252876,0.462168,0.194080,0.040506,0.230409,-0.221173,-0.276061,-0.596213,0.377426,0.769708,0.237391,-0.208395,0.723458,-0.227211,-0.583865,-0.248151,0.011102,-0.582215,-0.158498,0.074774,-0.253128,-0.163374,-0.262160,-0.439181,0.155404,0.108968,-0.377781,-0.120051,-0.462973,0.208885,-0.493459,0.117207,-0.567989,-0.223648,-0.137776,0.151445,-0.325684,0.836379,-0.669197,0.148498,0.702224,0.356499,-0.452340,0.990410,0.259799,-0.107118,-0.186582,-0.100047,0.029260,-0.069474,0.532655,-0.058038,0.396824,0.578301,-0.084125,-0.452622,0.737431', '1432669', '3055049', '1456503', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26304201', '妈阁是座城', '剧情', '女叠码仔梅晓鸥（白百何饰）历尽沧桑，在妈阁（澳门）这座赌城中与来历迥异的赌徒打交道，有地产商段凯文（吴刚饰）、有艺术家史奇澜（黄觉饰），也有来自不同阶级的政商人员，连早已堕落低谷的前夫卢晋桐（耿乐饰）都重新卷入她的人生。这些人入赌场就搏杀，出赌场就赖账，女叠码仔过的就是放债和讨债的生活。赌博让人迷失本性，叠码仔与赌徒周旋，也等于与魔鬼打交道，一时假仁假义，一时恩断情绝，赌至终局，谁能寻回本性，谁能鸿运当头？', '白百何', '李少红', 5.7, 61937, 'tt9198974', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2557267786.jpg', 7.3, 26.6, 43.2, 17.7, 5.2, '0.235243,-0.223691,-0.458912,0.131168,-0.350023,-0.454947,0.560216,0.042767,-0.455394,0.198725,0.186046,0.657357,-0.084749,-0.038933,0.184150,-0.171095,0.038149,-0.563952,-0.196559,-0.254959,0.111227,-0.406216,-0.189914,-0.127738,0.011552,0.093458,0.510907,0.054508,-0.473422,0.128693,0.486263,0.180471,-0.312763,0.348958,-0.291136,-0.038084,-0.373171,0.295652,-0.395428,-0.224732,-0.333698,-0.012623,-0.232623,-0.227565,0.082342,0.224769,0.377123,-0.344034,-0.028890,-0.027076,0.290512,-0.112650,-0.370997,0.093582,0.171979,-0.470330,0.136036,0.339642,-0.168721,0.135770,0.028608,0.149073,-0.763819,-0.076458,0.117550,0.091077,-0.394748,0.250522,0.423817,-0.248013,-0.258945,0.150578,0.259974,0.183395,0.379519,0.214775,0.274633,-0.362192,-0.673561,0.403617,0.889206,0.160397,-0.222953,-0.040345,-0.188807,-0.478224,-0.200066,-0.423434,-0.334172,-0.165384,0.205101,-0.221364,-0.301759,0.405424,-0.593397,0.403810,-0.040238,0.120784,0.143399,-0.483517,0.065024,-0.509936,-0.464883,-0.465628,-0.187941,0.017552,0.578387,-0.102123,0.520401,-0.935057,-0.023654,0.598931,0.396039,-0.572034,0.712542,0.227098,-0.113537,-0.087116,-0.252712,0.155580,0.379059,0.382251,-0.157646,0.143194,0.113064,0.051456,0.137407,0.335081', '25721544', '5985887', '4301278', '1308762');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26304268', '致命礼物', '悬疑', '因为找到一份新工作，西蒙·卡勒姆（杰森·贝特曼 Jason Bateman 饰）带着从事绘画设计工作的妻子萝宾（丽贝卡·豪尔 Rebecca Hall 饰）来到加州居住。西蒙的事业小有成就，夫妻俩和谐融洽，生活无忧无虑。在购物时，西蒙偶然重逢高中同学戈多（乔尔·埃哲顿 Joel Edgerton 饰），两人简单交谈后挥手告别。未过几天，戈多不请自来为夫妻带来了小礼物，当晚三个人共进晚餐，不过西蒙感觉并不十分愉快，显然他不太喜欢这个始终那么古怪的同学，相反萝宾倒有些欣赏这个热心的男子。在一次小的波折过后，西蒙终于决定张口要和完全不属于同一个世界的戈多绝交。戈多面带失落，同时一种异样的表情在他脸上浮现……©豆瓣', '杰森·贝特曼', '乔尔·埃哲顿', 6.7, 16598, 'tt4178092', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2260731928.jpg', 1.3, 7.7, 52.7, 32.8, 5.6, '0.229674,-0.069465,-0.601723,0.508377,0.018682,-0.483154,0.892551,0.125067,-0.493100,-0.604392,0.025092,0.816163,-0.298672,0.264863,0.356147,0.046023,-0.561920,-0.216081,0.272556,-0.205950,-0.062625,-0.611879,-0.075258,-0.125296,-0.257105,-0.100998,0.258458,0.018179,0.151471,0.769731,0.278292,0.037364,-0.125497,0.538437,-0.078051,-0.243268,0.340904,0.236422,-0.397437,-0.069634,0.232845,0.310807,-0.282579,0.114579,0.191892,0.301697,0.696428,-0.079658,-0.344976,0.251951,0.214690,-0.023407,0.024755,0.031905,-0.130528,0.037984,0.189652,0.004703,-0.232742,0.171787,0.022883,-0.211739,-0.407125,0.284702,-0.163835,0.279450,-0.264808,0.633555,0.032856,-0.114756,0.081748,-0.250110,0.095558,0.608694,0.435604,0.348456,-0.023497,0.336408,-0.271027,-0.037006,0.613336,0.155714,-0.040803,0.520543,-0.480556,-0.314767,0.164759,0.290478,-0.559286,-0.009935,0.054885,0.158817,0.038841,0.287156,-0.705266,-0.001330,-0.115237,0.147547,0.140784,-0.608804,-0.142234,-0.797868,-0.216935,-0.489460,-0.287566,-0.109845,0.043115,-0.080055,0.451160,-0.919528,0.243912,0.003292,0.103659,-0.185178,0.475843,0.509414,0.008593,-0.648001,-0.213082,0.392405,-0.028237,-0.100533,0.199556,0.452680,-0.025515,-0.038476,-0.366459,0.429127', '1297239', '1309172', '26687241', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26304310', '美国行动', '喜剧', '巴里（汤姆·克鲁斯 Tom Cruise 饰）是隶属于美国航空公司的一名飞行员，长期遭受公司压榨的他被中情局特工蒙迪（多姆纳尔·格里森 Domhnall Gleeson 饰）招募，蒙迪将巴里派往南美洲，进行秘密的任务。某日，大毒枭巴布洛找到了巴里，命令巴里替他运送毒品至美国国境之内，碍于自己的身份和所背负的任务，巴里只得就范。当巴里的运毒行为曝光后，为了保护这位特工，蒙迪挺身而出，将他和他的妻子露西（莎拉·赖特 Sarah Wright 饰）送往位于阿肯色州的一个偏僻小镇保护了起来。巴里的生意越做越大，他不仅继续运送毒品，甚至还做起了贩卖军火的生意。©豆瓣', '汤姆·克鲁斯', '道格·里曼', 7.3, 42185, 'tt3532216', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2495211154.jpg', 0.4, 2.4, 36.9, 50.1, 10.2, '0.121147,-0.119941,-0.612915,0.580875,-0.384461,-0.207928,0.483353,0.346034,-0.402783,-0.183790,0.233214,0.872829,0.230048,-0.036077,0.329092,0.420469,-0.459148,-0.491856,-0.165128,-0.185998,-0.036158,-0.559359,-0.482756,-0.422305,-0.127530,-0.261579,0.293411,-0.190776,-0.202379,0.240896,0.279629,0.382794,0.079490,0.450770,0.020168,-0.141324,0.526975,-0.525979,-0.065882,0.249279,-0.039204,-0.155047,0.098471,0.074231,0.485424,0.572592,0.414462,-0.181182,0.246884,-0.431742,0.038307,-0.585568,0.392043,-0.045845,0.252921,-0.097145,-0.047567,0.131311,-0.539730,0.023328,0.238777,-0.076577,-0.871862,-0.205779,0.140269,-0.047006,-0.728351,0.187684,-0.698377,0.039678,-0.038100,-0.447850,-0.000845,0.535990,0.124467,0.044202,-0.003184,0.221519,-0.709523,-0.069775,0.498141,-0.254474,-0.054295,-0.207791,-0.073712,-0.496663,0.071731,-0.230440,-0.276898,-0.262974,0.488356,-0.313368,0.009368,0.279464,-0.588819,-0.261374,-0.628750,-0.562942,-0.016473,-0.032175,-0.182051,-0.905028,0.084559,-0.075548,-0.042417,-0.058949,0.245044,-0.094731,0.411455,-0.386505,0.130113,0.864567,0.309802,-0.466274,0.133404,0.120937,0.671490,-0.027691,-0.329072,0.234527,0.372149,0.553289,0.223103,0.276075,0.066333,-0.415709,-0.011005,0.249013', '2028645', '1307442', '5973984', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26306656', '醉·生梦死', '剧情', '这一杯酒到下一杯酒之间，就是他们人生的全部。虽醒犹醉，男孩老鼠人生裡无所事事，菜市场裡厮混，好不容易遇上阻街的哑巴少女，生活又有了重心。老鼠崇拜表姊的恋人硕哥，硕哥却是万人迷，酒店挂牌牛郎正当红，连老鼠出了柜的哥哥上禾都心动，是酒让人迷，还是人生越喝越清楚，面对上禾诱引，硕哥生命裡以为永恒不变的定律就要鬆动。当家不成家，模糊爱与性别的分隔，一切都还有可能，逼临生命底线，与死亡贴面跳舞竟激出无比生命，随著母亲的身影呼之欲出，他们是在黑暗中逐光，或是梦裡寻梦一场空？生猛淋漓影像，凶猛议题，青春与情欲饱胀竟无处可洩，张作骥电影集大成之作，从城市和生命的双重边缘回望，成一页废墟美学，也是废人美学。', '李鸿其', '张作骥', 7.2, 11774, 'tt4471428', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2227562379.jpg', 1.2, 5.7, 39.2, 40.8, 13.1, '0.114099,0.069007,-0.514837,0.238818,0.076481,-0.486834,0.810465,0.219018,-0.350276,0.224329,0.131885,0.470103,-0.252751,0.039172,0.198392,-0.226129,-0.037110,-0.757497,-0.367369,-0.068905,-0.119079,-0.200985,-0.094326,0.220241,-0.019689,-0.260971,0.405362,0.114475,-0.275893,0.042392,0.347706,0.113946,-0.371076,0.229799,-0.174889,0.000405,-0.240285,0.071998,-0.386713,-0.212437,-0.039639,-0.128275,-0.035462,0.053884,-0.281463,-0.106178,0.596360,-0.058870,-0.370910,-0.274860,0.301825,-0.149769,-0.362398,-0.038813,0.261837,-0.310136,0.246527,-0.202106,0.171882,-0.135774,0.086112,0.116941,-0.556383,0.143582,-0.113652,0.293263,-0.243813,0.261588,0.119578,-0.059352,0.178576,-0.389796,0.165046,-0.338621,0.336380,0.496356,-0.180661,-0.054626,-0.587675,0.246233,0.665287,0.296122,-0.228569,0.433253,-0.322575,-0.389272,-0.204188,-0.283622,-0.244138,-0.068999,0.140858,0.314454,-0.204115,0.451040,-0.576277,0.221038,-0.137447,-0.027896,0.234187,-0.457211,-0.143332,-0.085848,-0.245253,-0.166597,-0.182268,0.261185,0.297925,-0.304670,0.516588,-0.495158,0.380300,0.609710,0.005441,-0.088856,0.629574,0.133541,-0.165662,-0.085646,0.200394,0.257407,-0.107039,0.133960,-0.083200,0.258252,-0.172083,0.376015,-0.483196,0.538407', '3012033', '3055049', '21619567', '2081098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26306997', '蝙蝠侠大战罗宾', '动作', '一面以光鲜的富豪公子哥面目示人，一面又披上蝙蝠侠的斗篷主持正义，布鲁斯·韦恩（杰森·奥玛拉 Jason O''Mara 配音）在光明和黑暗的道路上孤独奔走。为了防止“刺客联盟”的后代达米安（斯图尔特·艾伦 Stuart Allan 配音）走上歪路，他对达米安进行着艰苦而严格的训练。直到追查变态狂魔Dollmaker的过程中，这个恶棍被猫头鹰Talon（杰瑞米·西斯托 Jeremy Sisto 配音）杀害，蝙蝠侠却一度认为罗宾下此毒手，这令达米安心中的不满和愤懑与日俱增。随着时间的流逝，布鲁斯和达米安之间的分歧与误会似乎越来越深，随着Talon再度出现，少年心中的迷茫更加深了一层。这对孽缘一般的父子，注定要经历最为难耐的一段磨合时期……©豆瓣', '杰森·奥玛拉', '杰伊·欧力瓦', 6.8, 4991, 'tt4324274', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2252741757.jpg', 1.4, 6.9, 50.7, 30.6, 10.4, '0.164653,-0.078585,-0.394475,0.860449,0.228533,-0.338926,0.901463,-0.064718,-0.412900,-0.385266,0.330887,0.503832,-0.224710,0.090917,0.385042,-0.261754,-0.478362,-0.701017,-0.222390,-0.308563,-0.298940,-0.393325,-0.505692,-0.086481,-0.225456,-0.446358,0.644008,0.216606,-0.164265,0.609686,0.376739,0.274089,-0.177683,0.244806,0.054782,-0.116894,0.208532,-0.032668,-0.132011,-0.202552,0.296071,-0.134137,-0.195239,0.193368,-0.228800,0.426998,0.536399,-0.478283,-0.064035,-0.086809,0.373551,-0.384684,-0.041219,0.088868,0.343066,0.058042,0.066949,0.301566,0.006017,-0.090670,-0.157130,-0.018348,-0.771720,0.133831,0.064721,0.186277,-0.364195,0.395626,-0.038096,-0.108736,0.248704,-0.330025,-0.085076,0.208472,0.521877,0.304908,-0.151202,-0.088679,-0.239628,0.019389,0.582748,0.200980,-0.249264,0.123463,-0.392537,-0.251300,-0.080781,-0.180740,-0.530066,-0.369355,0.353427,-0.075967,-0.055079,0.748480,-0.673342,0.191223,-0.313615,-0.118041,-0.174031,-0.268700,-0.044121,-0.552493,-0.401026,-0.661878,-0.025146,0.078314,-0.215268,-0.336628,0.494939,-0.711337,0.300560,0.589303,0.221665,-0.302695,0.396921,0.189141,0.247307,-0.214674,-0.360452,0.437115,0.007747,0.088731,0.079964,0.198993,-0.134564,0.108786,-0.362404,0.432955', '25828589', '26630714', '2988294', '1307311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26307755', '季春奶奶', '剧情', '讲述的是小时候因为遭遇事故而失踪的孙女，十年后再次和奶奶相遇的故事，充满了令人流泪的感动，她们身上的秘密也令人好奇。', '尹汝贞', '尹鸿承', 8.5, 61964, 'tt6135036', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2332222074.jpg', 0.1, 0.7, 12.6, 46.1, 40.5, '-0.055555,-0.546498,-0.734529,0.531703,0.278761,-0.279798,1.102969,-0.490081,-1.064830,-0.245747,0.102731,1.033723,-0.633994,0.633200,0.197203,0.182775,-0.093923,-0.727645,-0.129148,-0.364013,-0.247898,-0.538233,0.396117,-0.328156,0.186428,-0.360450,0.447878,0.316418,-0.132286,0.958239,0.335314,0.462711,-0.357581,0.775010,0.029236,0.230876,-0.130746,0.676269,0.069065,-0.346447,0.495383,-0.128663,-0.081894,0.451754,-0.278623,0.208271,0.556406,-0.150498,-0.603640,-0.199153,0.536763,-0.335909,-0.068245,-0.104873,0.304484,0.252872,0.644821,0.303631,-0.143327,-0.484844,-0.065446,0.365460,-0.640503,0.131294,0.458684,-0.209390,-0.579682,0.166703,0.087701,0.081857,0.610600,-0.133949,0.650054,0.431691,0.552633,0.820655,-0.387246,-0.033333,-0.198579,0.160029,0.756841,-0.449819,0.178565,0.348592,-0.277076,-0.150270,0.065073,-0.190734,-0.560218,0.834788,-0.060974,0.469102,-0.220291,0.811961,-0.639544,-0.219405,-0.157843,-0.206941,0.193970,-0.545918,-0.452063,-0.243802,-0.421379,-0.581641,-0.581452,-0.238887,0.068469,-0.500245,0.630437,-0.791644,0.420302,0.465191,-0.069682,-0.376513,0.751566,0.333999,-0.081802,-0.230410,-0.011767,0.451002,-0.451091,-0.126561,-0.054757,0.279981,-0.159289,0.094929,-0.606945,0.452700', '1296534', '3111650', '2365260', '25881628');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26309788', '金刚：骷髅岛', '动作', '上世纪70年代，一支集结了科考队员、探险家、战地摄影记者、军人的探险队，冒险前往南太平洋上的神秘岛屿——骷髅岛。他们的到来惊扰了岛上之神——史上最大金刚。经过一番惨烈的激战之后，探险队员散落在了岛屿各处。此时，队员们才意识到这次探险并不是一次单纯的科考任务，而是去探索怪兽存在的证明。在这片与世隔绝、危险密布的丛林，无数怪异的史前生物暗藏其中，时刻威胁着他们的生命。队员们还遇到了神秘的原始部落，金刚的身世和其守护岛屿的原因也被逐渐揭开，原来，恐怖阴森的骷髅岛上还蛰伏着更凶狠残暴的怪兽……', '汤姆·希德勒斯顿', '乔丹·沃格特-罗伯茨', 6.5, 224719, 'tt3731562', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2436030518.jpg', 1.9, 11, 52.7, 27.9, 6.5, '0.124353,-0.026454,-0.979656,0.642460,-0.063951,0.237137,0.889809,-0.471068,-0.622000,-0.004036,0.535034,0.581580,0.039701,0.049516,0.058618,-0.000893,-0.214180,-0.295049,-0.408275,-0.140792,-0.539936,-0.149773,-0.561091,-0.185368,0.149406,-0.545128,0.710354,0.453236,-0.291602,0.265316,-0.139795,0.170326,-0.595133,0.623901,-0.207036,-0.274965,0.098061,0.015778,0.016158,-0.005016,-0.324544,-0.079661,-0.208512,0.280651,-0.114663,0.337378,0.925302,-0.623945,-0.171088,-0.266132,0.108702,-0.445637,0.084247,0.061656,0.751984,-0.105963,0.080853,0.137502,0.344542,0.100561,-0.305681,-0.246640,-0.581039,-0.228201,0.224655,0.241581,-0.375354,0.550823,0.243225,-0.040949,-0.012168,-0.218790,0.422077,0.344359,0.144928,0.098103,0.035558,-0.044245,-0.278389,0.310349,0.681170,-0.146108,-0.334806,-0.157331,-0.207978,-0.746756,-0.305723,-0.273359,-0.364256,-0.073257,0.402841,0.183850,-0.352051,0.265701,-1.121792,0.348579,-0.263994,-0.476972,-0.316558,-0.217299,-0.238158,-0.698277,0.194103,-0.095091,-0.183011,0.326978,-0.035753,-0.006071,0.667421,-0.537783,0.454167,0.948948,0.329395,-0.054923,0.485204,-0.442431,0.051393,-0.251954,-0.192031,0.377729,0.027452,0.707096,-0.016543,0.284824,-0.216647,-0.143962,-0.298927,0.520506', '26290398', '3006772', '1856675', '24879819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26309965', '大侦探霍桑', '喜剧', '影片改编自中国侦探小说家程小青的《霍桑探案集》，讲述了在中俄边境有一个富裕而神秘的城市——黄金城，这里发生了一起离奇的谋杀案，扑朔迷离的线索，身份不明的各路人马都让霍桑的探案之旅充满了未知和险阻，而最大嫌疑犯——怪盗江南燕出神入化的易容技巧更是让整个案件变得错综复杂。霍桑究竟能否在一系列的危机之下查明真相并全身而退呢？', '韩庚', '周显扬', 3.3, 6116, 'tt7359998', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2546253802.jpg', 51.7, 35.1, 10.9, 1.3, 1, '0.493144,-0.103307,-0.627052,0.765658,0.486292,0.064846,0.589465,-0.095649,-0.590346,-0.338538,0.098739,0.699112,-0.161500,-0.050969,0.215127,-0.127783,-0.358603,-0.754868,-0.240451,-0.316555,-0.400524,-0.685429,-0.465421,-0.161278,0.019793,-0.002278,0.371587,0.738648,-0.489328,0.346470,0.312351,0.246358,-0.505930,0.346877,-0.158434,-0.019016,0.204028,0.124524,-0.318353,0.152467,0.263621,-0.444144,-0.227033,0.471538,-0.020761,0.325277,0.720954,-0.263312,-0.395433,0.214852,0.475857,-0.230483,-0.099207,-0.024340,0.250264,-0.176370,-0.127551,0.450207,-0.217088,-0.213321,0.053872,0.060518,-0.996490,0.130957,0.388272,0.334670,-0.029194,0.023910,0.173071,-0.060883,0.086658,-0.301902,0.457825,0.621167,0.632331,0.218264,0.063756,-0.219206,-0.584801,0.271687,0.552879,0.091479,-0.333692,0.149443,-0.355085,-0.495756,-0.263511,-0.308536,-0.162286,0.053084,0.467596,0.017779,-0.293103,0.698849,-0.552631,0.215369,-0.271809,-0.254071,-0.408232,-0.349236,0.052903,-0.736678,-0.372490,-0.512337,-0.036264,0.060242,0.187908,-0.313740,0.583864,-0.581087,0.148846,0.544271,-0.089982,-0.521390,0.247463,0.181936,0.183959,0.109261,-0.295538,0.201160,0.128403,0.393825,-0.068682,0.413456,-0.125033,-0.134124,-0.425444,0.309498', '26678784', '25928048', '1295120', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26309968', '消失爱人', '爱情', '凯峰（黎明 饰）的妻子秋捷（王珞丹 饰）在一场意外之中不幸丧生，令凯峰沉浸在悲痛和绝望之中。凯峰找到了灵媒师，希望妻子能够死而复生，然而让凯峰没有想到的是，他的愿望竟然成真，秋捷以幽灵的形式回到了他的身边。灵媒师告诉凯峰，秋捷并不知道自己已经死去，凯峰和儿子沐沐必须保守这个秘密，一旦秋捷识破真相，就会消失。就这样，这个家庭以这样一种诡异的方式破镜重圆。然而某一日，凯峰的表弟吉米（林俊杰 饰）竟然看见了秋捷的魂魄，与此同时，令秋捷丧生的那场雪山事故亦被媒体大肆报道，当一切都濒临崩溃之时，一个更大的秘密渐渐浮出了水面。©豆瓣', '黎明', '黄真真', 5, 13157, 'tt5436486', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2305070844.jpg', 21.5, 30, 31.1, 11, 6.5, '0.226835,0.250709,-0.751729,0.492716,-0.004119,-0.082588,0.681955,-0.100578,-0.644277,-0.398497,0.297646,0.737294,-0.184035,0.545221,0.212650,-0.119476,-0.073467,-0.729563,-0.166448,-0.114172,-0.419479,-0.476364,-0.406761,-0.084169,-0.132732,-0.138195,0.645255,0.388725,-0.131300,0.512131,0.328075,0.440608,-0.224119,0.723360,-0.090116,0.077306,0.126127,0.218330,-0.273891,0.053438,0.147167,-0.191137,0.174389,0.323996,-0.376073,0.131835,0.595270,-0.355014,-0.273773,-0.046809,0.414258,-0.484206,0.014393,0.300256,0.200816,-0.188369,0.317870,0.057897,-0.395915,-0.086721,0.086250,0.123419,-0.830255,0.025160,0.158197,0.123478,-0.418388,0.052613,0.027683,0.076118,0.267994,-0.153160,0.365048,0.422466,0.411885,0.575159,-0.445082,-0.195684,-0.416713,0.083493,0.630266,-0.204326,-0.549565,0.365042,0.257703,-0.269271,-0.075481,-0.055780,-0.257145,0.356188,0.299533,0.262086,-0.261134,0.359181,-0.328451,-0.324165,-0.309538,-0.030354,-0.025806,-0.217568,-0.218280,-0.175427,-0.187225,-0.039667,-0.349134,0.289046,0.019204,-0.310059,0.538941,-0.881059,0.322120,0.190222,0.032676,-0.481312,0.422176,0.127208,0.141072,-0.203075,0.000368,0.228640,-0.216345,0.259354,0.185622,0.269581,0.043390,-0.011404,-0.452633,0.358230', '1301022', '35030151', '30345227', '1308254');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26309969', '新乌龙院之笑闹江湖', '剧情', '取材自敖幼祥的经典漫画IP《乌龙院》。讲述了乌龙院又到新一年招生季，一心想要当坏人的阿威（王宁 饰）和想要“学坏”的程明星（孔连顺 饰）潜入到乌龙院，想要偷师学艺并肩负秘密使命。二人为了骗取了长眉师父（吴孟达 饰）的信任，与小文师兄（郝劭文 饰）、大师兄（梁超 饰）、阳光 （张峻豪 饰）、“蛇蝎美人小师姐”蕊蕊（李欣蕊 饰）等一众徒弟在乌龙院内发生了一系列啼笑皆非的乌龙囧事，随着神秘女子（王智 饰）的出现，斗智斗勇的荒唐囧事也即将发生。©豆瓣', '王宁', '朱延平', 3.5, 19871, 'tt8549902', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2529762680.jpg', 47.9, 33.4, 14.6, 3.2, 0.9, '0.039064,-0.071835,-0.683291,0.407837,0.152327,-0.255954,0.508629,0.056377,-0.510421,-0.382677,0.233374,0.342589,-0.465883,-0.103059,0.388888,0.079170,-0.087555,-0.714704,0.005305,-0.391007,-0.188684,-0.391930,0.016142,-0.066109,-0.120930,-0.102614,0.211023,0.158399,-0.111857,0.314026,0.967276,0.118914,-0.443249,0.079966,-0.099320,0.123958,0.200599,0.522294,-0.218877,-0.078221,0.072821,-0.390057,-0.219099,-0.071724,0.143601,0.088919,0.606086,-0.407495,-0.277219,-0.047039,0.062170,-0.067506,-0.011853,-0.036316,0.249419,0.028676,0.208056,0.086413,-0.136650,0.375530,0.298712,-0.377326,-0.409062,0.123991,0.441513,0.159253,-0.491021,0.079753,-0.062570,-0.053268,0.360358,-0.443460,0.045668,0.128752,0.583889,0.264152,0.050962,0.114146,-0.252301,0.400968,0.289191,-0.068403,0.353788,0.467432,0.094232,-0.235185,-0.249602,0.083851,-0.450973,0.510302,0.481522,-0.181817,0.065155,0.291408,-0.426412,-0.342639,0.208006,0.049760,-0.101789,-0.154143,0.197763,-0.273594,-0.183792,-0.334028,0.089676,0.296229,0.224002,-0.357747,0.596631,-0.614113,0.225783,0.084227,-0.048244,-0.687134,0.189476,0.102636,0.168902,-0.267032,-0.171241,-0.179568,-0.090290,0.243623,0.134042,0.459649,0.248984,-0.516277,-0.196148,-0.063221', '1890558', '1305016', '3074415', '1316525');
