INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26311828', '女主角失格', '喜剧', '一座平凡的高中内，不善与人交流的帅哥寺坂利太（山崎贤人 饰）超受女孩欢迎。不过在超爱幻想的女孩松崎羽鸟（桐谷美玲 饰）眼里，那些女孩都是形同杂鱼般的人物。小学时候，利太因为母亲与人私奔而受到欺负，这时候羽鸟出手相助，两人也因此成为好友。自信的羽鸟相信自己和利太就是命中注定的一对，谁曾想童话般的爱情故事居然朝着意想不到的方向展开。同班其貌不扬的女孩安达未帆（我妻三轮子 饰）被人欺负，利太出面帮助了她，两人竟由此成为男女朋友。眼看自己从女主角沦为杂鱼配角，羽鸟的内心产生前所未有的裂变……本片根据幸田桃子的同名漫画改编。©豆瓣', '桐谷美玲', '英勉', 6.6, 26847, 'tt4396042', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2239732345.jpg', 2.2, 12.6, 49.1, 25.8, 10.2, '0.372007,-0.294627,-0.446143,0.301840,-0.216181,-0.080692,0.669475,0.158315,-0.370305,-0.118569,0.186354,0.661074,-0.324800,0.058588,0.321409,-0.177013,-0.076526,-0.493328,0.006658,-0.284803,-0.108389,-0.229506,-0.043367,-0.033336,-0.074028,-0.284886,0.819984,0.059556,-0.261322,0.403704,0.487886,0.385964,-0.236879,0.143342,0.026724,0.105048,-0.189474,0.292559,-0.034649,0.195396,-0.271772,-0.110042,0.106300,0.160631,-0.390265,0.163452,0.620345,-0.372904,0.005015,-0.408945,0.300678,-0.221718,-0.161012,0.052912,0.307281,-0.198441,0.333820,-0.067520,0.057993,-0.058779,0.156634,-0.124174,-0.570081,0.122345,0.258204,0.185423,-0.411006,0.127427,0.028824,-0.248997,0.313786,-0.085383,0.049941,-0.117165,0.399360,0.270371,-0.342730,0.214548,-0.358355,0.033711,0.566151,0.282845,-0.207255,0.282252,-0.158289,-0.317829,-0.075081,-0.365517,-0.535930,0.249401,-0.045711,-0.049604,-0.127561,0.110225,-0.428080,-0.104688,-0.122621,0.267715,0.161926,-0.460365,-0.083111,-0.443171,-0.004312,-0.346897,-0.083733,0.013184,0.147228,-0.416058,0.990118,-0.882397,0.079655,0.331110,0.364151,-0.324484,0.668149,0.099580,-0.226676,-0.391626,-0.138922,0.007229,0.225833,-0.125224,-0.040828,0.193207,-0.099189,-0.172613,-0.019003,0.272315', '25922902', '3445516', '3811356', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26311973', '唐人街探案', '喜剧', '天赋异禀的结巴少年秦风（刘昊然 饰）警校落榜，被姥姥遣送泰国找远房表舅——号称“唐人街第一神探”，实则猥琐的大叔唐仁（王宝强 饰）散心。不想一夜花天酒地后，唐仁沦为离奇凶案嫌疑人，不得不和秦风亡命天涯……穷追不舍的警探黄兰登（陈赫 饰）、无敌幸运的警察坤泰（肖央 饰）、穷凶极恶的匪帮三人组、高深莫测的唐人街教父、美艳风骚的老板娘阿香（佟丽娅 饰）等悉数登场！七天！唐仁、秦风必须取长补短、同仇敌忾！他们能否躲避警察追捕、匪帮追杀、黑帮围剿，在短短七天内，完成找到失落的黄金并查明真凶，为自己洗清罪名这些逆天的任务？©豆瓣', '王宝强', '陈思诚', 7.7, 787342, 'tt5290882', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2302930556.jpg', 1, 3.1, 25.8, 49.6, 20.5, '-0.055706,-0.128841,-0.342832,0.234989,-0.152512,-0.148016,0.337533,-0.051775,-0.487464,-0.380020,0.229342,0.243235,-0.241311,0.197028,0.309684,0.025002,-0.090298,-0.456981,-0.012267,-0.279928,-0.021389,-0.235348,-0.389272,-0.325072,-0.035622,-0.123850,0.293997,0.313656,-0.021386,0.530745,0.574566,0.201036,-0.450861,0.075500,-0.184075,-0.011488,0.307042,-0.195959,-0.262748,0.147138,-0.028733,-0.195858,0.012608,-0.035338,-0.039609,0.233172,0.486898,0.073498,-0.134528,-0.052879,0.246132,-0.496217,-0.410919,-0.043657,0.486241,-0.235491,0.239408,0.310922,0.055367,-0.123502,0.074981,0.043750,-0.791718,0.128537,0.155281,0.017558,-0.336260,0.359750,-0.188095,0.155199,0.210139,-0.138838,-0.014624,0.230200,0.220900,0.089919,0.173909,0.154558,-0.413080,0.595826,0.324315,-0.008125,0.027493,-0.128741,0.268898,-0.319137,0.340326,-0.292587,-0.138983,0.200725,0.353034,-0.250903,0.023913,0.021255,-0.123572,-0.313171,-0.405038,0.273550,-0.321966,-0.091520,-0.172992,-0.596178,0.046874,-0.262027,0.046606,0.148368,0.104800,0.055477,0.431013,-0.356474,0.066906,0.274542,0.068423,-0.522069,0.196244,0.012937,0.142060,-0.455292,-0.360038,0.026849,0.372785,0.362086,0.243289,0.302606,-0.101610,-0.290161,-0.264278,0.051513', '27073234', '3318306', '26747274', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26311974', '下一任：前任', '爱情', '林心恬（郭采洁 饰）拥有美丽的外表和体面的工作，但让旁人百思不得其解的是，这样优质的女孩却始终是单身。林心恬这辈子其实也遇到过几个和自己心意相通的恋人，但他们的恋情都仿佛不合时宜一般的无法长久。渐渐的，林心恬开始对感情感到失望，她再也不想体会那种失恋的怅然了。就在林心恬决定放弃的这个节骨眼上，一个名叫吾川（郑恺 饰）的男人出现在了林心恬的生活里。林心恬的独立和开朗深深的吸引了吾川的注意，与此同时，林心恬学生时代就暗恋的男子黄克群（李东学 饰）也开始对她展开了追求。一时之间，受宠若惊的林心恬不知该如何选择。©豆瓣', '郭采洁', '陈鸿仪', 2.8, 28044, 'tt10234494', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2572715315.jpg', 73.8, 16.8, 6.8, 1.1, 1.4, '0.489883,0.118020,-0.849299,0.702446,-0.359148,-0.261291,0.828595,0.088228,-0.523066,-0.118140,0.022891,0.837657,-0.273195,0.424349,0.128813,0.084967,-0.011965,-0.818515,-0.004625,-0.145375,-0.142464,-0.369890,-0.350525,-0.108196,-0.193843,-0.168179,0.829083,0.209895,-0.193738,0.507398,0.479375,0.195233,0.123836,0.756749,-0.168237,-0.070844,-0.193960,0.275341,-0.100258,-0.190798,0.098788,-0.219310,-0.020447,0.547613,-0.191728,0.486470,0.674621,-0.282827,-0.594327,0.184714,0.430290,-0.154374,-0.163369,0.235998,0.023543,-0.024641,-0.077378,0.100472,-0.238498,0.009915,-0.087670,0.237236,-0.782541,0.003863,0.194709,0.225564,-0.757247,0.566782,0.043488,-0.474003,-0.211047,-0.219935,0.287386,0.221057,0.340682,0.440500,-0.312103,-0.063959,-0.308387,0.211068,0.918604,0.230718,-0.484240,0.712180,-0.415552,-0.534815,-0.230069,-0.268338,-0.661000,-0.006169,-0.280951,0.355582,-0.320314,0.063878,-0.643907,0.114312,-0.022478,0.029741,-0.168317,-0.751794,-0.001210,-0.184334,-0.298220,-0.714468,-0.576898,0.289206,-0.051250,-0.378356,0.865279,-1.064828,0.091332,0.409760,0.448296,-0.637330,0.927204,0.369117,-0.111765,-0.208578,-0.196572,0.420543,-0.261726,-0.078553,0.020738,0.449609,-0.122062,-0.164178,-0.473684,0.609903', '35030151', '3230462', '1301022', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26313740', '玩命直播', '动作', '一款名为Nerve的真人大冒险直播游戏正席卷纽约城，游戏参与者有两个不同的选择，要么当“观看者”，要么当“玩家”，观看者付费决定玩家去挑战各种冒险游戏。高中女生Vee（艾玛·罗伯茨 Emma Roberts 饰）是个平凡无奇的乖乖女，平日最大的乐趣就是“窥视”学校里的男神JP。她的好友Sydney正沉迷于这个直播游戏里，为了吸引观看者而作出种种大胆行为。受其影响，平日习惯于当旁观者的Vee，也加入了这个直播游戏，成为了“玩家”。她的第一项冒险，就是亲吻一个陌生人。挑战成功后，她才发现这个陌生人Ian（戴夫·弗兰科 Dave Franco 饰）也是游戏玩家之一。他们俩的大冒险直播，从刚开始的好玩刺激，到逐渐走向失控。他们必须携手逃出这场玩命直播……©豆瓣', '艾玛·罗伯茨', '亨利·朱斯特', 6.4, 49834, 'tt3531824', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2410038523.jpg', 1.3, 11, 56.4, 26.6, 4.7, '0.521511,0.011884,-0.378396,0.428553,-0.207552,0.027670,0.468233,-0.049764,-0.485900,0.017599,0.512334,0.836728,-0.467645,0.136788,0.337664,-0.193969,-0.424785,-0.498843,-0.466529,-0.024969,-0.147100,-0.107706,-0.081226,-0.294694,-0.084712,-0.019835,0.844604,-0.152336,-0.644635,0.273751,0.483735,0.052633,-0.169300,0.362826,0.209298,-0.286461,0.198530,0.048391,-0.127169,0.178266,-0.289997,-0.092414,-0.121806,0.174935,0.057823,0.250423,0.895128,-0.510381,-0.172664,0.035379,0.551141,-0.376310,-0.417591,-0.086691,0.093479,-0.130611,0.366723,-0.417796,0.403143,0.291444,-0.402259,-0.064295,-0.961365,-0.022027,0.210321,0.062829,0.154442,0.238928,0.113808,-0.150912,0.101345,-0.070428,-0.120704,0.200001,0.482854,0.120529,-0.156812,-0.243407,-0.105983,0.532502,0.584975,0.119894,-0.290779,0.439489,-0.146539,-0.504331,0.004330,-0.457335,-0.548805,-0.131246,0.357714,-0.129802,-0.120103,0.129238,-0.797878,0.201436,0.125116,-0.505595,0.205515,-0.456475,-0.073947,-1.056164,0.024196,0.003799,0.031169,0.295860,0.080437,-0.655879,0.770670,-1.036197,0.107839,0.915626,0.014974,-0.851578,0.844641,-0.042169,0.111709,-0.285202,-0.091873,0.097458,0.136003,0.304544,-0.368730,0.260346,0.130003,-0.206357,-0.384893,0.480898', '2369613', '26759820', '1420088', '2286642');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26313973', '我是证人', '剧情', '路小星（杨幂 饰）是一位初出茅庐的见习女警，她的弟弟死于一场意外，而作为见证人的路小星则双目失明。尽管失去了视觉，但路小星的其他感官却因此而意外的活跃起来，即便生活在黑暗之中，路小星却依旧能够敏感的感受到周遭的一举一动。一场车祸中，路小星成为了目击者，凭借着自己的特殊能力，她做出了证词，路小星绝佳的感官和记忆力吸引了老刑警鲁力（王景春 饰）的注意。林冲（鹿晗 饰）是车祸的另一位目击者，可奇怪的是，他所做出的证词恰恰和路小星的证词截然不同。一个是五感健全的普通人，一个是双目失明的盲人，究竟应该相信谁的证词？而又是谁在撒谎呢？©豆瓣', '杨幂', '安相勋', 6.3, 180710, 'tt4979652', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2279732402.jpg', 6.2, 15.2, 46.1, 21.8, 10.7, '0.208857,0.090320,-0.580262,0.723959,-0.478303,-0.105261,0.817512,-0.033088,-0.655545,-0.327182,0.307568,0.761932,0.125409,0.152189,0.080423,-0.008587,0.023049,-0.508022,0.010256,0.010442,-0.570314,-0.489199,-0.634989,-0.169854,-0.142666,-0.301865,0.502800,0.186579,-0.485782,0.311953,0.491467,0.240746,-0.081880,0.416958,-0.138108,-0.125919,-0.016374,0.024135,-0.147345,0.003236,-0.042104,-0.351279,-0.215052,0.418886,-0.235697,0.465429,0.645906,-0.281796,-0.475979,0.026846,0.597331,-0.351695,0.079880,0.089747,0.287946,0.057926,0.204502,0.018583,-0.013713,0.139221,0.064475,0.302659,-1.061861,-0.018776,0.340871,0.419035,-0.370608,0.361267,0.075621,-0.442071,0.091194,-0.142960,0.222295,0.035612,0.037340,0.397547,-0.421403,-0.072601,-0.366120,-0.050849,0.716561,0.235857,-0.594103,0.532295,-0.394137,-0.751223,-0.267380,-0.197683,-0.351095,0.294667,0.103751,0.166527,-0.149892,0.076680,-0.243759,0.091654,-0.116285,-0.035456,-0.523544,-0.431103,-0.028116,-0.437725,0.015815,-0.582863,-0.290940,0.274620,0.099249,-0.387375,0.727715,-0.771740,-0.037584,0.615230,-0.130104,-0.626897,0.590420,0.151945,0.071731,-0.204126,-0.291118,0.224759,0.117444,0.048051,-0.071592,0.336578,-0.059669,-0.119716,-0.530638,0.503212', '25932086', '3785918', '1793491', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26314556', '陷阱', '惊悚', '该片是根据真实事件改编，讲述了一对夫妇看到网络上的美食情报，就来到孤岛上寻找这间餐厅，却遭遇了意料之外的重重危机。2015年警察厅公布的统计数据中，2014年网络犯罪多达11万起，大部分是网络金融欺诈、黑客等行为，但也有通过网络而施行的杀人、强奸、连锁杀人等重大刑事犯 罪。特别是对于网上很多没有公信力的情报毫无怀疑而上当受骗的受害者日渐增加。特别是我们对于智能手机和 app 的使用都成为日常生活中不可或缺的一环，所以网络上的犯罪其实离我们每个人都很近。《陷阱》也是出于这样的意图，希望告诉观众，其实每个人都可能会陷入这样的陷阱。影片中赵汉善和金敏京饰演的“俊植”、“素妍”夫妇，为了找到网上有着好口碑的餐厅而来到孤岛上，遇见了亲切地有些过分的餐厅主人，之后却陷入了意想不到的陷阱中。该片导演权炯辰曾凭借《为了霍格沃兹》获得第44届大钟奖新人导演奖，并提名第10届上海国际电影节及亚洲新人奖最佳影片。之前演惯了反派的马东锡最近在影视剧中展现了幽默搞笑的一面而倍受观众喜爱，在这部电影中则又饰演看上去很亲切但却让人觉得有点恐怖的神秘餐厅主人“成哲”一角。', '马东锡', '权炯辰', 6.4, 7348, 'tt4922028', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2259527231.jpg', 1.7, 12.6, 55.5, 21.9, 8.2, '0.391662,-0.091913,-0.661649,0.707623,0.262161,0.114981,0.670712,-0.035944,-0.792162,-0.141176,0.164191,0.777148,-0.438355,0.140041,0.274952,-0.090006,-0.298148,-0.612316,-0.341008,-0.420124,-0.271654,-0.368000,-0.408918,-0.046385,-0.333490,-0.292609,0.644101,0.329049,-0.449371,0.372926,0.355998,0.277523,0.008782,0.487207,0.037724,-0.025801,0.124605,0.189086,-0.286814,0.290376,0.013297,-0.354055,-0.119661,0.369150,0.032466,0.334314,0.495407,-0.241224,-0.482674,0.144913,0.678136,-0.488374,-0.307642,-0.117528,0.469586,0.171220,0.469073,0.232534,-0.196575,0.171685,-0.146252,-0.065128,-1.066621,-0.078665,0.281489,0.144201,-0.330167,0.276345,-0.001538,0.050175,-0.027881,-0.193245,0.371841,0.111318,0.552635,0.230595,-0.013552,-0.014143,-0.440376,0.092110,0.589153,0.063170,-0.351993,0.300850,-0.346196,-0.596527,0.002609,-0.330036,-0.169104,0.281586,-0.055124,0.052750,0.008932,0.044534,-0.479616,0.275446,0.012403,-0.390996,-0.096799,-0.489838,-0.161393,-0.927786,-0.259786,-0.481358,-0.180040,-0.038125,0.096551,-0.452148,0.736632,-0.922223,0.205798,0.455584,0.315184,-0.377850,0.758927,0.122437,-0.179237,-0.159763,-0.359251,-0.083960,-0.012920,0.105898,-0.157976,0.160823,-0.052059,-0.662545,-0.381590,0.473415', '1793491', '26259202', '3318306', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26314816', '九条命', '喜剧', '汤姆（凯文·史派西 Kevin Spacey 饰）是叱咤风云的商场精英，却因为过多的将经历投入到工作中而忽视了自己的家人们。这一天是汤姆的女儿瑞贝卡（玛丽娜·维丝曼 Malina Weissman 饰）的生日，差一点就将这茬给忘了的汤姆匆忙赶到宠物店，打算买一只猫作为送给女儿的礼物。让汤姆没有想到的是，自己竟然被宠物店的老板菲利克斯（克里斯托弗·沃肯 Christopher Walken 饰）施了魔法，灵魂进入了宠物猫的体内。菲利克斯告诉汤姆，他只有学会如何做一位称职的丈夫和父亲，才能够重新回到人类身体之中，然而，猫的寿命是很短暂的，在有限的时间里，汤姆能够完成菲利克斯布置给他的任务吗？©豆瓣', '凯文·史派西', '巴里·索南菲尔德', 6.9, 83178, 'tt4383594', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2378310691.jpg', 0.8, 7.5, 47, 33.5, 11.1, '0.271555,0.171687,-0.643542,0.618328,-0.480678,-0.497035,0.739734,-0.127805,-0.535372,-0.442842,0.099420,0.790804,-0.057992,0.293980,0.268151,0.122721,-0.139203,-0.642356,0.009974,-0.156481,-0.358922,-0.423220,-0.389523,-0.140419,-0.032868,-0.305317,0.462001,0.026395,-0.020258,0.124624,0.243817,0.290915,0.270864,0.461160,-0.305571,0.298922,0.136953,-0.136168,0.047602,0.481877,0.262684,-0.095238,-0.003111,0.396277,0.246790,0.217376,0.753959,-0.392362,-0.230039,-0.070970,0.401694,-0.187542,-0.069392,0.137654,0.055421,0.158083,0.288091,0.044356,-0.303208,0.227918,0.201903,-0.187041,-0.986706,-0.038851,-0.101869,0.033830,-0.875532,0.376931,-0.254035,-0.045768,0.149688,-0.587132,0.250767,0.204808,0.184274,0.484993,-0.122183,-0.037039,-0.642669,0.076611,0.517849,-0.335973,-0.148688,0.553077,-0.204945,-0.421962,0.123139,-0.275267,-0.354815,0.054241,0.078380,0.281752,-0.170640,0.051197,-0.538568,-0.189245,-0.468276,-0.508219,0.101942,-0.460915,-0.114529,-0.455451,-0.045752,-0.404051,-0.312867,-0.067751,0.153302,-0.455321,0.633672,-0.981708,0.239572,0.622725,0.315174,-0.216362,0.749721,-0.145352,0.311817,-0.089406,0.119507,-0.088920,0.167854,0.432298,0.436268,0.407845,0.201819,-0.269154,-0.528019,0.696825', '1793491', '1783461', '1949005', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26315270', '冰河追凶', '动作', '在零下四十度极寒之地，以周鹏（梁家辉 饰）、汪豪（佟大为 饰）为首的“追凶者”深入冰河，追查真凶寻找真相。在暗藏杀机的冷酷冰河，牵一发而动全身，每一个人都无法避免地被卷入一场场错综复杂的事件，成为“追凶”成员。而冰河下的最终真相却颠覆所有人的想象……', '梁家辉', '徐伟', 5.8, 24296, 'tt5714554', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2325669527.jpg', 5, 24.9, 50.7, 14.5, 4.8, '-0.141727,-0.163192,-0.657239,0.647369,0.184715,0.227340,0.809587,0.006139,-0.467165,-0.225753,0.359419,0.562677,-0.411043,-0.351294,0.264578,-0.346764,-0.061855,-0.710806,-0.491622,-0.036642,-0.341323,-0.269277,-0.354362,-0.197519,-0.068565,0.116902,0.871036,0.814146,-0.740203,-0.037908,0.117542,0.655665,-0.458685,0.605753,-0.050748,-0.256253,-0.032413,-0.075537,-0.252763,0.115812,-0.259413,-0.525045,-0.208920,0.354114,-0.372019,0.388636,0.689878,-0.468753,-0.057097,0.139633,0.487747,-0.730801,-0.421896,-0.019982,0.280759,-0.254859,0.029534,0.565917,0.019601,-0.186197,0.287624,0.210290,-1.195620,0.108303,0.557346,0.429425,-0.248495,0.256031,-0.008951,0.321571,0.023466,-0.064739,-0.017349,0.368401,0.378506,0.069559,-0.382636,-0.324245,-0.531013,0.158554,0.697752,0.133592,-0.570714,-0.174626,-0.046006,-0.512595,-0.089644,-0.240247,-0.338613,-0.115594,0.543070,0.441120,-0.140785,0.827617,-0.390104,-0.254224,-0.446337,-0.472240,-0.125136,-0.406892,-0.314221,-0.729030,-0.160625,-0.354006,-0.298807,-0.030868,0.085581,-0.577994,0.343406,-0.399557,0.141016,0.362823,-0.194821,-0.564269,0.370241,0.056990,0.280170,-0.215328,-0.168435,0.601427,0.389396,0.544476,0.000313,0.403116,-0.320149,0.012976,-0.582929,0.084722', '25828589', '26667010', '27073234', '7051375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26315728', '贤妻', '剧情', '根据Meg Wolitzer所著同名小说改编，女主角Joan Castleman是一位文学家的妻子，美丽忠诚、无瑕疵，牺牲了自己的梦想、才华、野心，花费了40年的时间来辅助丈夫，忽略他的不忠，永远表现得体。而随着时间的推移，他们的婚姻也来到破碎的临界点。在诺贝尔文学奖颁奖的前夜，她将面临生命中最大的牺牲，同时也发现了丈夫职业生涯的秘密。', '格伦·克洛斯', '比约恩·荣格', 7.2, 10230, 'tt3750872', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2542440929.jpg', 0.7, 4, 40, 43, 12.4, '-0.397123,0.318458,-0.584452,0.717371,-0.342462,-0.227055,0.903852,0.098076,-0.348273,-0.307507,0.325447,0.777384,-0.021221,-0.067528,0.226104,-0.295746,-0.160048,-0.949970,-0.094789,-0.532790,-0.229250,-0.419412,-0.182364,-0.405639,-0.203399,-0.602393,1.120888,0.099391,-0.265070,0.273810,0.327105,-0.124463,0.136508,0.452279,-0.023666,0.025160,0.127237,0.060996,-0.174743,0.319582,0.063191,-0.317363,0.066872,0.208832,-0.412890,0.417688,0.800601,-0.319467,-0.249726,-0.094518,0.954597,-0.416658,0.086877,-0.044437,0.176604,0.108680,0.107891,0.487556,-0.258916,-0.016055,0.014819,-0.371084,-1.323574,-0.281863,0.270880,0.195729,-0.659932,0.785947,-0.038834,-0.304097,0.097178,-0.318197,0.381083,0.261549,0.394054,0.276980,-0.413090,0.282773,-0.254235,0.559450,0.518397,-0.248904,-0.283600,0.671770,-0.425058,-0.349323,-0.131098,-0.497888,-0.579655,-0.065221,0.132620,0.340929,0.108566,0.436421,-0.429697,0.077972,-0.287929,-0.262738,0.058028,-0.589656,-0.074415,-0.237231,-0.417264,-0.449396,-0.330642,0.022714,0.181797,-0.685918,1.322480,-0.648688,0.149916,0.808723,0.381930,-0.584644,1.120538,0.102613,0.194628,-0.320490,0.153104,0.722431,-0.276254,0.171262,-0.280149,-0.040100,-0.033609,-0.041798,-0.489890,0.810100', '27602116', '30279170', '25880986', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26316956', '密战', '剧情', '淞沪会战后上海沦陷，地下工作者林翔（郭富城 饰）受命来到危机四伏的上海，重建惨遭敌人破坏的地下抗日战线。在这里他遇到单纯却很有正义感的兰芳（赵丽颖 饰），这对临时组成的“地下党夫妇”将在战火纷飞中，携手与日本侵略者及伪政府特务展开惊险刺激的生死较量……', '郭富城', '钟少雄', 4.3, 34372, 'tt7628068', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2502474177.jpg', 27.8, 40.2, 24.9, 4.4, 2.7, '0.483283,-0.017412,-1.015401,0.315937,0.221281,0.164119,0.772341,-0.107875,-0.634004,0.194551,0.395327,0.742403,-0.042086,-0.082700,0.173921,-0.172068,-0.453948,-0.922278,-0.406346,-0.038632,-0.074252,-0.385175,-0.659089,0.059950,-0.282112,-0.003154,0.922412,0.619002,-0.270181,0.519100,0.185825,0.496877,-0.277430,0.475066,-0.173007,-0.029382,0.024739,-0.066878,-0.573761,0.138603,-0.136176,-0.338524,0.079644,0.067398,-0.098852,0.327028,0.736859,-0.339481,0.128893,-0.293823,0.314541,-0.476569,-0.243882,0.209797,0.543824,0.066669,-0.056874,0.363864,-0.193001,0.133176,-0.098017,-0.075113,-0.529598,-0.017167,0.290884,0.204282,-0.630275,0.509115,0.194677,0.169341,0.143571,-0.099000,0.281982,0.829207,0.455613,0.211927,0.002088,0.104056,-0.447347,-0.028270,0.992703,-0.166198,-0.069073,-0.272372,-0.123909,-0.408725,0.277058,-0.312361,0.051717,-0.339424,-0.066307,-0.546933,0.128906,0.152239,-1.056643,0.185372,-0.134488,0.076594,-0.056186,-0.200718,-0.151339,-0.840320,-0.098686,-0.631805,-0.327788,0.382048,-0.082291,-0.048321,0.486111,-1.048912,-0.108746,0.470506,0.630447,-0.347525,0.625229,0.344750,0.161755,-0.178376,0.096718,0.446515,-0.140424,0.579657,-0.069276,0.148289,-0.198471,-0.148904,-0.258474,0.147994', '1507140', '34822138', '1301022', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26318239', '回到火星', '剧情', '火星男友Gardner（阿沙·巴特菲尔德饰）从天而降，一段关于亲情与爱情的寻觅之旅跨星际上演。16岁的火星男孩Gardner回到地球，带着对一切新奇美好的向往冲破科学家及医护人员的防护，与名叫Tulsa（布丽特妮·罗伯森饰）的地球少女，展开了一段动人心弦的历险，一起追寻自己的出生之谜，一起品尝纯真初恋……', '阿萨·巴特菲尔德', '彼德·切尔瑟姆', 5.7, 11752, 'tt3922818', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2501879346.jpg', 5.5, 25.5, 51, 14, 4.1, '0.423992,-0.103015,-0.837618,0.537937,-0.056628,-0.104630,1.012144,-0.296393,-0.244053,-0.035145,0.174914,0.669106,-0.509951,0.772960,0.485053,0.335086,-0.206033,-0.916951,0.188872,-0.158113,0.085166,-0.305611,-0.533629,0.347408,-0.133765,-0.449691,0.715629,0.306241,0.217181,0.839747,-0.057340,0.079864,-0.672685,0.264535,-0.283444,-0.044120,-0.064593,0.500791,-0.756944,-0.222353,0.077286,-0.107307,0.333570,-0.112521,-0.579021,-0.060238,0.904611,-0.589298,0.418829,-0.265398,0.404632,-0.173967,0.077703,0.153376,0.064994,0.437574,-0.125697,0.091931,0.193117,-0.277978,0.142155,-0.245269,-0.422242,-0.399256,0.270350,0.251904,-0.495041,0.343321,0.124408,-0.095283,0.387505,-0.066076,0.038190,0.080958,0.429983,0.793781,-0.159064,0.177677,0.001141,0.272055,0.565563,-0.199687,-0.435345,0.414433,-0.326287,-0.204464,0.119315,0.012229,-0.649389,0.133492,0.282772,-0.026515,0.126777,0.495292,-1.029746,0.310033,-0.154397,-0.139516,0.316284,-0.481740,-0.247999,-0.875269,-0.171070,-0.468650,-0.302302,0.138929,0.376313,-0.283150,0.887620,-0.606689,0.323440,0.450652,0.258982,-0.394760,0.584681,-0.034499,0.150771,-0.589899,0.229911,0.887243,-0.349441,0.206709,-0.350664,0.321101,-0.261235,0.468896,-0.830106,0.543761', '4706257', '1307146', '1467779', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26318896', '育婴室', '恐怖', '元末军阀混战时，曾出现的一支嗜食人肉，尤其是食小儿之肉的“淮右之军”。而紧邻淮河的小镇临塘曾深受其害。当年淮右军被困临塘，一夜之间吃光了镇上婴幼小儿。战乱平息之后，民国年间，临塘镇流行起召唤“婴灵”的巫术，但养婴灵者往往不得善终，而曾经吃幼婴的“淮右之军”后人蒙少晖（朱一龙 饰）误入其镇，一意孤行揭开了镇压邪灵的封印，古镇上开始频频出现恐怖的异象，事件的相关者也一个接一个的死去。似乎有种神秘的力量在守护着以前的某个秘密……', '皮查雅·瓦塔那蒙迪里', '皮查农·塔玛杰拉', 4.7, 7638, 'tt6448704', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2372301645.jpg', 27.7, 29.4, 31.1, 6.8, 5.1, '0.307716,-0.024010,-0.661437,0.580097,0.143739,0.097385,0.611476,0.172707,-0.374242,-0.225584,0.171534,0.561784,0.074247,0.363164,0.148266,-0.075934,0.376643,-0.479895,-0.049699,-0.157605,-0.116518,0.133651,-0.506849,-0.157157,0.069763,-0.537172,0.501332,0.437501,-0.367053,0.173495,0.171917,0.199756,-0.407849,0.277919,-0.431496,-0.081517,-0.357051,0.102657,-0.083633,0.115372,-0.283467,-0.570456,-0.032035,0.179539,-0.319951,0.355268,0.485470,-0.657712,-0.262427,-0.366050,0.469615,-0.391548,-0.248872,0.068439,0.488731,0.210249,0.222661,-0.074441,-0.145659,-0.061829,0.064614,0.060737,-0.509895,-0.296298,0.029787,0.153089,-0.365743,0.260410,0.451095,0.146026,-0.212091,-0.253775,0.389054,0.500925,0.098553,0.296800,0.086366,-0.033303,-0.564257,0.262169,0.809145,-0.608666,-0.344342,-0.044613,0.229785,-0.316364,0.149081,-0.339878,-0.447534,0.211665,0.121019,-0.063386,-0.098402,0.410582,-0.806845,-0.093812,-0.174481,0.044525,0.300375,0.330018,-0.567132,-0.215042,-0.365621,-0.099630,-0.069835,0.122762,0.167601,-0.014965,0.527264,-0.518396,0.419094,0.459160,0.158963,-0.272474,0.264252,-0.014241,0.025452,0.187291,-0.172860,0.358368,0.164481,0.337920,0.032650,0.076009,-0.107353,-0.115955,-0.381763,0.464826', '1308784', '1457926', '26290398', '6982558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26320001', '唐顿庄园：2015圣诞特别篇', '剧情', '二小姐结婚了，大小姐怀孕了，两姐妹也和解了。柯拉在医院的工作得到了丈夫与老太太的认可，亨利和汤姆合开了汽车公司，伊莎贝尔表亲与默顿伯爵准备结婚。安娜生了孩子，卡森半退休，巴罗即将成为庄园的管家，黛西和安德鲁确认了心意。莫斯利辞去男仆的职位，正式做了老师。从此以后，所有人都过上了幸福的生活。', '休·博纳维尔', '迈克尔·恩格勒', 9.5, 15731, 'tt4419112', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2292519115.jpg', 0.1, 0.2, 3.2, 19, 77.5, '0.187628,-0.117380,-0.511172,0.105946,-0.339224,-0.974829,0.330281,0.572986,-0.321745,-0.089998,0.078378,1.034160,-0.238070,0.470921,0.440445,0.316146,-0.583727,-0.583791,0.095170,-0.098740,0.002616,-0.664693,0.448124,-0.270682,0.187030,-0.318485,0.263281,-0.405857,0.393109,0.365154,0.144705,-0.153693,0.282765,0.194950,-0.030821,0.522968,0.489319,-0.000764,-0.827804,0.074578,0.110200,0.252303,0.133117,0.006350,0.670168,0.426198,0.182445,0.006901,-0.140786,-0.295979,0.209726,0.013123,0.225076,0.305162,0.283884,0.071399,0.255329,0.552906,-0.152120,-0.466569,-0.173788,-0.038192,-0.357232,0.358395,0.091852,-0.160721,-0.734691,0.553463,-0.339696,-0.142531,0.015334,-0.520360,0.510151,0.494988,-0.230464,0.265043,-0.304359,0.299752,-0.579193,0.299549,0.628722,-0.036902,-0.117783,0.141705,0.012592,-0.406587,0.117111,-0.115895,-0.544761,0.063909,0.240501,0.144236,-0.211101,0.331816,-0.282442,-0.283821,-0.653978,-0.285292,0.308934,-0.623162,0.091258,-0.540409,-0.265958,-0.175855,-0.380742,-0.309003,0.320183,-0.193509,0.724037,-0.865728,0.183651,0.214094,0.795752,-0.732065,0.712375,0.039695,0.570230,-0.262550,0.329330,-0.220372,-0.326622,0.574905,0.445808,0.437191,0.073075,-0.022604,-0.248855,0.286443', '1306133', '1297239', '1900121', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26320029', '万万没想到', '喜剧', '屌丝小妖王大锤（白客 饰），他生来便与常人不同，两耳尖尖，又有些小法力，总是自诩本地妖王。但让他万万没想到的是，在遇到唐僧师徒四人组后，他的命运发生了逆转；而对于唐僧师徒四人组来说，遇见王大锤也是无比郁闷的第八十二难。双方因此上演了一出相爱相杀，令人捧腹的奇幻冒险。', '白客', '易小星', 5.7, 201334, 'tt5266678', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2291070523.jpg', 10.1, 25, 43.4, 15.2, 6.4, '0.275394,-0.002502,-0.815539,0.410067,0.231752,-0.207611,0.765712,-0.009631,-0.703388,-0.053343,0.199205,0.739710,-0.515603,-0.107651,-0.047290,-0.440754,0.303587,-0.376972,-0.059645,0.064878,0.107041,-0.154970,-0.235670,0.074702,-0.176187,-0.196604,0.257377,0.006459,-0.261321,0.385444,0.486006,0.107062,-0.242322,0.397502,-0.107227,0.258242,-0.190467,0.534186,0.033011,-0.140976,0.062625,0.091728,-0.281175,0.097538,-0.227472,0.316758,0.477402,-0.535064,-0.402692,-0.023881,0.271486,-0.462314,-0.591004,0.171430,0.366206,-0.122043,0.322305,-0.124085,0.121562,0.016421,0.163670,-0.002315,-0.762767,0.513022,0.055832,0.059782,-0.432540,0.121038,0.006779,0.004444,-0.023379,-0.370379,0.179987,0.376120,0.748068,0.200235,-0.080597,-0.400384,-0.452856,0.037152,1.213258,0.322599,-0.588165,0.099266,-0.119763,-0.481537,-0.228822,-0.422320,-0.181115,0.128557,0.395393,0.200211,-0.007487,0.303857,-0.553797,0.156870,-0.291777,0.326800,-0.129140,-0.543366,0.117606,-0.305359,-0.056054,-1.035529,-0.545121,0.072385,0.571906,-0.478795,0.753471,-0.901500,-0.223950,0.215149,-0.014703,-0.443606,0.729534,0.196052,0.002208,-0.120377,-0.089270,0.100330,-0.082213,0.166642,0.281952,0.530559,-0.009561,-0.053928,-0.154200,0.263399', '25721544', '24325798', '1305084', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26321184', '七人乐队', '剧情', '自上世纪五十年代直至未来，七位殿堂级导演各自抽签负责一个年代，执导一个与香港有关的故事。《七人乐队》片名寓意各有风格才华的导演，尤如出色的乐手，走在一起便能合奏出令人共鸣的美妙乐章。其中包括洪金宝的《练功》、许鞍华的《校长》、谭家明的《别夜》、袁和平的《回归》、杜琪峯的《遍地黄金》、林岭东的《迷路》，及徐克的《深度对话》。其中林岭东的《迷路》更是导演的最后遗作。《练功》：50年代，一群拜师学艺的孩子在师父严厉的督导下勤练功夫。徒弟与师父间的默契在呼喝声中形成，而躲懒受罚的那天也可成为一生难忘的转机。《校长》：60年代，社会清贫，但求学者众。一位执笔忘饭的校长与善良淡雅的王老师让一座天台学校成为童年岁月里最温暖的家。《别夜》：叶嘉琳与余雁飞，在80年代香港依然美丽的夕照中相恋。女方一家移民海外，二人无奈承受离别之苦，只余下相爱的记忆。《回归》：90年代，儿子举家移民，孙女却因学业暂时留在香港爷爷家。爷孙两人隔代沟通，妙趣横生。在生活中消解代沟，隔阂打破，亲情更上一层楼。《遍地黄金》：2003年沙士时期，大时代下三个小市民的发达白日梦。三人常胡扯投资大计，妄想一夜致富。一番进退争论后，总是错失发达机会。《迷路》：2018年的新春，丈夫回到香港与妻儿团聚，当他拿着旧照片在日新月异的香港街头追忆当年时，却彻底迷失了方向。最后，回忆不幸化成追忆。《深度对话》：未来，某所精神病医院正在进行一项关于精神分裂的研究。四位参与者投入忘我表演，已然分不清真正身份，到底谁是医生？谁是病人？', '洪天明', '洪金宝', 6.5, 23271, 'tt4431104', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2874685464.jpg', 2, 13.9, 49.2, 29, 5.8, '0.003653,0.110284,-0.526396,0.402855,0.099858,-0.444081,0.530880,0.033972,-0.470670,-0.365548,0.077877,0.559193,0.033954,0.524262,0.222555,-0.360249,-0.121394,-0.616742,-0.029358,-0.099861,-0.162286,-0.396622,-0.117753,0.005046,-0.158451,-0.152104,0.535582,0.273904,-0.233183,0.259427,0.133531,-0.000927,-0.437218,0.065987,-0.246228,-0.124170,0.141549,0.330020,-0.628307,-0.054301,-0.055394,-0.087595,-0.257852,-0.266107,-0.044241,0.041182,0.667504,-0.038205,-0.112616,-0.103453,0.455605,0.114039,-0.283778,-0.014760,0.267738,0.102436,0.323991,0.325898,-0.070836,-0.142513,-0.287895,-0.063860,-0.518147,0.098244,0.262916,0.095989,-0.390126,0.323142,0.214176,-0.183827,-0.086024,-0.259306,0.294325,0.292106,0.495934,0.620765,-0.195453,0.054830,-0.139302,0.348016,0.839846,-0.009953,-0.310716,0.172802,-0.170116,-0.339003,0.010388,-0.205628,-0.474719,0.079975,-0.018345,-0.002066,-0.011693,0.324634,-0.521977,0.161222,-0.125706,0.014222,0.016567,-0.297939,0.022845,-0.640780,-0.097221,-0.271973,-0.238000,-0.043397,0.305688,-0.233040,0.844052,-0.350499,0.249775,0.196509,0.100658,-0.356166,0.826344,0.138518,0.226805,-0.331832,-0.023803,0.377855,-0.134337,0.004652,-0.119743,0.174808,-0.273584,0.027873,-0.333791,0.308534', '26646649', '1945253', '4066127', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26322637', '火星异种', '动作', '2599年，人类酝酿了五百年之久的火星移民计划终于要迈出重要一步了。在此之前，科学家通过向火星投放藻类以及蟑螂以改善火星的生存环境。而今，为了避免死刑的惩罚，小町小吉（伊藤英明 饰）和青梅竹马秋田奈奈绪（武井咲 饰）不得不答应本多博士（小栗旬 饰）的要求，与武藤仁（山下智久 饰）、蛭间一郎（山田孝之 饰）、森木明日香（菊地凛子 饰）、堂岛启介（加藤雅也 饰）等有着不同身份和背景的人们踏入前往火星的飞船。抵达目的地后，他们惊讶地发现蟑螂早已进化成无比健硕高大的生物，并且迅速向他们发起了进攻。在战斗过程中，他们了解到这次火星旅行的真正目的，于是为了回到地球而拼尽全力与洪水般的蟑螂人战斗……©豆瓣', '伊藤英明', '三池崇史', 5.1, 9472, 'tt4433646', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2325212536.jpg', 14.5, 34.1, 38.2, 9.3, 4, '-0.170363,-0.009310,-0.691524,0.368790,0.229294,-0.271984,0.439122,0.030813,-0.208111,-0.330106,0.296361,0.420551,-0.133783,0.024943,0.364546,-0.229804,-0.393877,-0.522882,-0.016633,-0.241575,-0.287683,-0.440879,-0.140503,-0.340947,-0.158622,-0.308408,0.783533,0.365364,-0.126398,0.569874,0.112045,0.387280,-0.153346,0.224101,0.143100,-0.127087,-0.034892,0.089258,-0.581019,0.235528,-0.143436,-0.224253,-0.075484,0.015750,0.062462,0.242990,0.772610,-0.541024,-0.103768,-0.396381,0.036151,-0.370315,0.051994,0.421648,0.411750,-0.090284,0.094438,0.266614,0.094591,0.099197,0.080776,-0.199196,-0.556423,-0.051037,-0.033133,0.153853,-0.318656,0.312339,-0.093437,0.010821,0.229366,-0.395510,-0.056488,0.333906,0.276880,0.209891,-0.541164,0.149819,-0.193672,-0.264520,0.621308,0.100538,-0.056849,0.281790,-0.090936,-0.504043,-0.354367,-0.180498,0.201516,-0.134685,0.240145,0.436876,-0.111638,0.263146,-0.766569,-0.137489,-0.224230,-0.196135,0.208547,-0.141033,-0.003000,-0.760357,0.107154,-0.542390,-0.352016,0.293727,0.048928,-0.136386,0.595184,-0.659552,-0.102467,0.341521,0.427281,-0.510839,0.329505,-0.440594,-0.238966,-0.553852,0.174331,0.120662,0.077793,0.523632,-0.000842,0.201472,-0.053782,-0.247222,-0.520683,0.096224', '2369613', '20274039', '6007281', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26322774', '纯洁心灵·逐梦演艺圈', '剧情', '海亚影视学院（虚构）近些年已经跻身国内著名影视院校的行列，其表演系2013级本科班，学生形象、艺术条件都格外突出，从入校伊始就备受学校师生关注，被誉为“准明星班”。班主任文天阳年青英俊，刚刚硕士毕业留校，认真负责。班里共有17名学生，8男9女，家庭背景、成长经历、性格各异：有的学生家里条件优越，有奢华海边别墅、游艇与跑车；有的学生是普通工薪阶层的子女；还有学生来自落后偏远山区的少数民族；还有学生是单亲家庭的问题子女……能在千军万马中成功杀出而考取表演专业，是备受人们关注的。他们是天之骄子，热情澎湃，都在自己最美好的青春年华，为自己的美好梦想奋斗着。演员是一个相对被动的职业，经常需要见组和推销自己，学习表演专业的学生也难免要比普通专业学生与社会有更多、更早的接触。城市中有着很多诱惑，影视圈也同样复杂，他们的青春美貌也吸引了形形色色的人士们的目光。文老师与自己的学生们在四年的历程中曾经沮丧过、伤心过甚至大痛过，但是青春这趟旅程，含着眼泪也要向前！他们决心闯入演艺圈并有所作为……', '朱一文', '毕志飞', 2.2, 103157, 'tt4986830', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2510130772.jpg', 95.7, 1.8, 0.3, 0.2, 2, '0.291571,-0.313007,-0.509495,0.519361,-0.163780,-0.009818,0.602965,-0.078861,-0.669853,-0.199089,0.116721,0.656663,-0.085384,0.603188,0.179484,-0.403508,-0.258266,-0.567785,-0.066346,-0.366105,-0.147855,-0.286562,-0.117921,-0.167138,-0.362110,-0.541873,0.796611,0.086975,-0.303576,0.461806,0.257972,0.044112,0.070342,0.249818,-0.349200,-0.434320,0.169332,0.370126,-0.167908,-0.092803,-0.151432,-0.060342,-0.311539,-0.135001,0.373313,0.165185,0.624907,0.458644,-0.127130,-0.003682,0.524769,-0.082051,-0.249464,0.018623,0.642473,-0.049520,0.345936,0.134241,0.474181,0.228329,-0.336873,-0.444976,-0.697149,-0.152811,0.586728,-0.008147,-0.658709,0.660500,0.294705,-0.338128,0.114740,0.005832,-0.118025,-0.145753,0.062795,0.408855,0.125913,0.150704,-0.197850,0.858692,0.786332,0.184415,-0.569386,0.152524,-0.735153,-0.730803,0.018628,-0.604008,-0.687763,0.170724,0.006157,0.011973,-0.007651,0.398098,-0.425073,0.391052,0.190335,-0.211937,0.100386,-0.371902,-0.096106,-0.635295,0.062940,-0.560738,-0.409881,0.044649,0.177472,-0.320637,1.491045,-1.093392,-0.129814,0.552160,0.528180,-0.594170,0.989811,0.001518,0.203138,-0.015364,-0.469514,0.190391,-0.273563,0.246587,-0.518874,0.3