INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26322792', '北京遇上西雅图之不二情书', '喜剧', '焦娇（汤唯 饰）15岁就来到了澳门，过着颠沛流离的生活，之后成为了赌场公关。罗大牛（吴秀波 饰）早年来到美国，一番摸爬滚打，如今已经是小有名气的加州房地产经纪人，事业一帆风顺的他在情场上自然步步为赢，是公认的钻石王老五。一本名为《查令十字街84号》的书让这一对生活毫无交集的男女走到了一起，两人通过电子邮件进行交往，透过种种误会和波折，最终发现彼此是自己的灵魂伴侣。在此期间，焦娇徘徊在郑义（陆毅 饰）、邓先生（王志文 饰）和诗人（祖峰 饰）之间不知何去何从，而罗大牛则在同华裔老夫妻林平生（秦沛 饰）和唐秀懿（吴彦姝 饰）的交往当中逐渐发现了人生的道义。©豆瓣', '汤唯', '薛晓路', 6.4, 244173, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2336879398.jpg', 3.7, 16.1, 46.4, 24.4, 9.4, '0.124485,-0.095035,-0.597171,0.566247,0.228972,-0.398757,0.668530,0.218201,-0.591909,-0.215459,0.094452,0.669778,-0.379817,0.340156,0.428748,-0.282605,-0.180141,-0.949354,-0.057701,-0.277348,-0.281210,-0.473389,-0.239182,0.194089,-0.331584,-0.127441,0.676704,0.082434,-0.180624,0.551909,0.426854,0.213768,-0.266929,0.232949,-0.229087,0.113172,0.209147,0.380935,-0.692017,0.029841,-0.104077,-0.301387,-0.048560,-0.189315,0.169130,0.146117,0.775030,-0.135022,-0.214913,0.187279,0.368109,0.017707,-0.160227,-0.050997,0.413091,0.121332,0.261609,0.195269,-0.326821,0.038604,0.075475,-0.035009,-0.551434,-0.058224,0.190042,0.232631,-0.766261,0.489869,-0.001195,-0.301997,-0.137046,-0.341537,0.401021,0.520346,0.315100,0.191331,-0.062976,0.171780,-0.431012,0.303337,0.714123,0.322111,0.135486,0.409248,-0.102386,-0.475472,-0.188881,-0.023688,-0.485414,-0.254579,0.111061,-0.010882,0.050104,0.190356,-0.731535,0.007190,0.069459,-0.060006,0.314053,-0.440303,0.124813,-0.662798,-0.496398,-0.871341,-0.334921,0.380215,0.036101,-0.391157,0.716332,-1.006781,0.123876,0.085826,0.141504,-0.402279,1.000796,0.135428,0.156495,-0.303486,0.034429,0.277438,0.128337,0.151592,-0.020639,0.428529,-0.009668,-0.050208,-0.308626,0.310492', '26354526', '25777330', '3033092', '25962735');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26322809', '杜拉拉追婚记', '喜剧', '30好几的杜拉拉（林依晨 饰）二次归来，一心想与王伟（周渝民 饰）结婚的她遇到劲敌美少女沙当当（林珍娜 饰），而另一名追求者陈丰（陈柏霖 饰），和新上司曲络绎（邬君梅 饰）的出现，让杜拉拉对人生的选择陷入迷惘。面对接踵而来的问题，杜拉拉是否能再次“升职”成功呢？', '周渝民', '安竹间', 5.3, 38657, 'tt5227020', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2279987087.jpg', 11.2, 31.9, 42.6, 10.3, 4, '-0.089390,-0.048866,-0.428322,0.543888,0.052734,-0.086264,0.666178,-0.025686,-0.345482,-0.327002,-0.337959,0.642257,-0.603555,0.612098,0.957544,-0.364476,0.194858,-0.572157,0.131922,0.297679,-0.545112,-0.521059,-0.362151,-0.345091,0.012320,-0.081650,0.573859,0.088872,-0.305072,0.672684,1.025272,0.688385,-0.002639,0.590874,0.109297,0.117229,-0.091418,0.376922,-0.374871,0.240110,0.204786,-0.368696,-0.071123,0.062776,0.065632,0.404346,0.691241,-0.111215,0.174450,0.110676,0.339145,-0.229256,0.360430,-0.128155,0.191373,-0.007825,0.033884,0.019442,-0.119757,0.261859,0.195848,-0.322390,-0.306258,0.238516,0.411952,-0.312260,-0.279402,-0.300709,0.030998,0.073184,0.255679,-0.166458,0.249296,0.650356,0.904395,0.313283,-0.282702,0.157270,-0.372610,0.253972,0.333119,0.278181,0.048082,0.391176,0.009504,-0.796976,-0.412083,-0.060373,-0.384743,0.024575,0.506866,0.221195,0.183965,-0.303880,-0.380398,-0.430230,0.145931,0.004847,0.016925,-0.150995,0.070738,-0.253460,0.101302,-0.501105,-0.440566,0.441603,0.059608,-0.431575,0.366784,-0.641351,0.120603,-0.314640,0.135155,-0.827285,0.608310,0.407920,0.201611,-0.230407,0.046669,0.454060,0.183678,-0.128808,0.265283,0.044644,-0.358388,-0.131975,-0.033400,0.076332', '1305016', '5954505', '26412618', '26309969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26322928', '鬼乡', '剧情', '故事发生在1943年，日军的屡屡侵犯打破了朝鲜国民的宁静生活，一时间硝烟四起，百姓们失去了赖以生存的家园，过着流离失所的悲苦生活。居昌郡的一个小小村落里，生活着名为正敏（姜荷娜 饰）的十四岁少女，正敏出生在一个平凡但恩爱的家庭中，从小到大都沐浴在父母慈祥的关爱之下。战争的到来结束了正敏无忧无虑的生活，某日，日军占领了村庄，不由分说的将正敏掠走送上了开往日本的火车，和她同行的，都是一些和正敏差不多岁数的少女，每个人心中都惴惴不安，不知会有怎样的命运等待着她们。正敏和其他少女们沦为了日军发泄兽欲的对象，过着暗无天日的悲惨生活，然而正敏内心里有一个无比坚定的希望，那就是活下来，重返故乡。©豆瓣', '姜荷娜', '赵正莱', 7.5, 34254, 'tt5503266', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2226663805.jpg', 0.6, 3.6, 33.1, 45.5, 17.2, '0.221104,-0.025825,-0.768751,0.584715,-0.054624,-0.068588,0.965010,-0.043733,-0.330382,-0.131573,0.173702,0.624754,-0.055975,0.687254,0.307185,-0.052274,-0.261880,-0.692879,-0.407129,-0.071728,-0.120548,-0.229544,-0.186018,-0.189555,-0.221731,-0.376886,0.757691,0.348254,0.123806,0.435421,0.152332,0.120602,-0.046443,0.560773,-0.486301,0.336548,-0.073041,-0.117089,-0.218443,0.046910,-0.346632,-0.305552,-0.241174,0.189149,-0.026227,0.252272,0.908362,-0.400804,-0.251647,-0.082651,0.341513,-0.296718,-0.109801,0.352468,0.317165,0.082055,0.060602,0.153127,-0.329581,0.148861,0.189089,0.050190,-0.569199,-0.100314,0.043182,0.178412,-0.763532,0.752438,0.313146,-0.173436,0.059166,-0.289488,0.421465,0.568472,0.033511,0.665702,-0.280463,0.265318,-0.634067,0.352007,1.188911,-0.136467,-0.293588,0.130361,-0.533896,-0.369908,0.052291,-0.462546,-0.810159,-0.310799,0.043142,-0.084134,-0.340513,0.392959,-0.698326,0.312975,-0.066687,-0.469877,0.148812,-0.530081,-0.341097,-0.408711,-0.217445,-0.755530,-0.626950,0.337331,0.105313,-0.153660,1.165235,-0.849348,0.255874,0.469703,0.286555,-0.387565,0.518477,0.415149,0.156522,0.249127,0.071404,0.556389,-0.180267,0.402214,0.120413,0.278999,-0.481648,0.121256,-0.376128,0.552923', '25721544', '26348103', '27040921', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26322972', '邻居大战2：姐妹会崛起', '喜剧', '环球影业今日宣布，将打造2014年暑期档黑马R级喜剧片《邻居大战》的续集，并定档于2016年5月13日在北美上映。影片主演塞斯·罗根、扎克·埃夫隆以及萝丝·拜恩将悉数回归。据《好莱坞报道者》透露，《邻居大战》续集将上演“性别大置换”。在首部曲中，罗根与拜恩饰演一对拥有新生女儿的年轻夫妻，与隔壁新搬来的吵闹的大学兄弟会年轻人展开激烈大战，但在续集中他们将面对的新邻居是一群有过之而无不及的大学姐妹会的女学生。在几轮交锋之后，小夫妻感到力不从心，于是他们请来了外援，这就是在第一部中与他们从敌到友——由恶魔兄弟会会长“从良”为A&F花样男模的扎克·埃夫隆。', '塞斯·罗根', '尼古拉斯·斯托勒', 5.4, 11634, 'tt4438848', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2331062847.jpg', 7.1, 32.2, 46.9, 10.1, 3.9, '0.122883,-0.351476,-0.457804,0.375530,0.297782,-0.044332,0.488504,-0.105185,-0.611841,-0.136061,0.367895,0.956652,-0.678778,0.151094,0.424462,-0.335298,-0.339334,-0.685868,-0.283921,-0.221777,0.042020,-0.095672,-0.365623,-0.029874,-0.158275,-0.363272,0.773657,-0.160641,-0.144580,0.538013,0.473092,0.083775,-0.261276,-0.043726,0.049500,0.125971,0.150328,0.039705,-0.488053,0.423301,-0.039873,-0.077719,-0.314059,-0.337407,0.223264,0.309620,0.933125,-0.292766,0.278681,-0.122860,0.524765,-0.127901,-0.226901,0.156237,0.476018,0.249204,0.250448,0.410199,-0.037397,0.014436,-0.221023,-0.522601,-0.630993,0.307747,0.135054,0.063310,-0.619769,0.495319,-0.085882,0.016553,0.255056,-0.156456,0.202190,0.451901,0.283014,0.404627,0.199738,-0.014372,-0.284398,0.397111,0.660538,-0.053770,-0.133443,0.228879,0.273498,-0.488490,-0.312070,-0.336457,-0.493261,0.075085,0.408362,-0.107493,-0.016956,0.448741,-0.819970,-0.144838,-0.150810,-0.335659,0.229622,-0.212264,-0.136299,-1.014253,-0.216695,-0.213755,0.099226,-0.016915,0.377738,-0.243421,0.883293,-1.001359,0.048108,0.226186,0.589258,-0.147983,0.781102,-0.113683,0.373027,-0.240549,-0.206616,-0.213370,0.026157,0.202573,0.291358,0.309205,-0.140564,-0.304016,-0.233848,0.217575', '3811356', '26365262', '1322847', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26323031', '五十度黑', '剧情', '年度争议大作《五十度灰》即将在2月13日北美上映，近日，导演萨姆·泰勒-约翰逊，主演詹米·多南和达科塔·约翰逊在纽约一场影片粉丝放映会上，向到场的观众宣布了《五十度灰2》和《五十度灰3》已经确定拍摄的消息。据MTV透露，《五十度灰2》和《五十度灰3》将根据E.L.詹姆斯所著的《五十度黑》（《Fifty Shades Darker》）和《五十度飞》（《Fifty Shades Freed》）改编，达科塔·约翰逊饰演女主角安娜斯塔西娅·斯蒂尔也将再次登上大银幕。', '达科塔·约翰逊', '詹姆斯·弗雷', 5.7, 70972, 'tt4465564', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2412519473.jpg', 9.3, 27.6, 41.7, 13.6, 7.9, '-0.366124,0.048493,-0.344987,0.492499,0.541272,-0.211447,0.505470,0.321987,0.048895,-0.144155,-0.086757,0.890411,-1.216455,-0.056747,0.433536,-0.570611,-0.383572,-0.822052,-0.661534,-0.384700,-0.004558,-0.687289,-0.377231,0.072358,0.081834,-0.733528,0.344500,-0.013910,0.121634,0.511429,0.540516,-0.199880,0.213094,0.037923,0.220032,0.053229,0.250396,-0.208061,-0.243441,0.847951,-0.346898,-0.280963,0.125766,-0.236756,-0.139107,0.698728,1.012572,-0.165813,-0.113659,0.318131,0.634222,-0.074883,-0.177533,0.194995,0.552187,0.136873,0.274427,0.541871,0.076443,0.199681,-0.274637,-0.307993,-0.459638,0.466092,-0.103168,0.230763,-0.639230,0.322745,-0.729089,0.075998,0.183203,0.033282,-0.128992,0.076669,-0.231913,0.229235,-0.045092,0.007874,-0.262927,0.348049,0.037805,0.203965,0.067002,0.137394,0.364504,-0.686460,-0.319028,0.266025,-0.186684,0.239068,0.452060,-0.105633,0.446566,0.003941,-0.780566,0.066157,-0.430869,-0.964844,-0.229002,-0.032607,0.106290,-1.038821,-0.191214,-0.245400,-0.035478,-0.291935,0.470253,-0.416058,0.672722,-0.092273,0.334689,0.109437,0.278561,-0.041810,0.677915,-0.180398,-0.115841,-0.337358,0.146058,-0.112466,0.035461,0.091104,0.282185,0.589826,-0.142904,-0.556792,-0.447227,0.719411', '23338330', '2255841', '3003137', '26926703');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26323540', '手机', '动作', '2014年5月16日，在瑞草洞住宅区发生了杀人事件，高东浩（孙贤周饰）的妻子赵妍秀（严智苑饰）被发现惨死家中，而凶手一直未能落网。东浩在妻子被杀害之后生活失意，整日颓废不振难以自拔，他唯一的女儿高景林也因父亲的消沉而备受折磨。一年后的某天，因为磁场异常，东浩发现自己竟然能和一年前的妻子通电话，并且从通话中得到了拯救妻子生命的线索，而给他的时间只有一天。东浩决心一定要抓住这个改变命运的机会，为了救出妻子展开孤军奋战。', '孙贤周', '金奉柱', 6.8, 5109, 'tt5034276', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2266087989.jpg', 1.7, 8.8, 48.5, 31.2, 9.8, '-0.463658,0.019034,-0.568305,0.388765,-0.150469,-0.459645,0.632037,0.064920,-0.950662,-0.510811,0.099095,0.559531,-0.114649,0.442504,0.382303,-0.195331,-0.171783,-0.894412,0.036535,-0.109845,-0.400602,-0.317769,0.110114,-0.326206,0.080508,-0.491486,0.761279,0.185008,0.340940,0.385335,0.160048,0.432493,0.010871,0.502042,-0.122374,-0.108079,-0.062394,0.111311,-0.430259,0.430976,0.291307,-0.429427,-0.042272,0.366607,-0.320914,0.348249,0.807140,-0.037731,-0.380672,-0.475663,0.534940,-0.361209,-0.270740,0.152816,0.328884,0.039190,0.333770,0.494703,-0.496643,-0.284201,0.157312,-0.111224,-0.661860,0.026438,-0.123694,-0.144337,-0.412183,0.343994,-0.021087,0.085483,0.094721,-0.345383,0.392890,0.780991,0.340950,0.348944,-0.705049,-0.035555,-0.543573,0.175141,0.727191,-0.594041,0.123841,0.641920,0.217310,-0.393703,0.086735,-0.571617,-0.449831,0.309121,0.281164,0.418970,-0.586824,0.276614,-0.331438,-0.114789,-0.545366,-0.099446,0.102999,-0.458414,-0.307863,-0.057526,-0.178007,0.018349,-0.278080,0.282038,-0.068252,-0.469232,0.362332,-0.761277,0.631897,0.443319,0.384816,-0.645897,0.737488,0.261823,0.203262,-0.285029,0.219281,0.560803,0.069777,0.268839,0.062696,-0.341540,-0.254935,-0.067602,-0.377146,0.438934', '30345227', '1301022', '1308254', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26325320', '血战钢锯岭', '剧情', '1945年，第二次世界大战接近尾声，作为邪恶轴心重要成员的日本，其嚣张态势已成强弩之末。是年，决定战局走向的冲绳岛战役拉开序幕，成千上万斗志昂扬的美国大兵被派往冲绳，等待他们的则是敌军重兵防守、凶险异常的钢锯岭。在这群人中间，却有一个不愿拿起武器的军医。他名叫戴斯蒙德·道斯（安德鲁·加菲尔德 Andrew Garfield 饰），来自美国的弗吉尼亚。太平洋爆发之际，瘦弱的戴斯蒙德志愿成为救死扶伤的军医而应征入伍。可因童年和家庭的原因，他始终不愿拿起枪支操练，为此宁愿背上拒服兵役的罪名被送上军事法庭。几经周折，戴斯蒙德最终和战友来到了钢锯岭。枪林弹雨，转瞬之间无数人应声倒地。在信仰和信念的支持下，戴斯蒙德仅凭一己之力拯救了数十条濒死的生命……本片根据真人真事改编。©豆瓣', '安德鲁·加菲尔德', '梅尔·吉布森', 8.7, 739561, 'tt2119532', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2398141939.jpg', 0.2, 0.9, 10.8, 41.5, 46.6, '0.093860,-0.006804,-0.623977,0.397579,-0.105977,-0.051036,0.569341,0.112319,-0.279293,0.037914,0.351156,0.788088,0.137423,-0.034710,0.061335,-0.305883,-0.233434,-0.714144,-0.205531,0.065918,-0.407054,-0.259361,-0.368597,-0.093070,-0.168729,-0.442142,0.732269,0.016141,-0.134451,0.541369,0.324887,0.501986,0.015785,0.271702,-0.116999,-0.304299,-0.138176,-0.286028,-0.378820,0.312985,-0.133590,-0.283955,-0.163950,0.354215,-0.162019,0.483747,0.867970,-0.181913,0.299781,-0.230139,0.324317,-0.450993,0.027219,0.021403,0.247188,0.197668,-0.302069,0.174915,-0.102696,-0.047735,0.108045,-0.327540,-0.664848,-0.240364,0.081335,0.218020,-0.614498,0.556913,-0.338419,0.143455,0.070466,-0.415850,-0.034839,0.336079,-0.003618,0.134738,-0.099031,-0.108378,-0.447606,0.227658,0.597873,-0.157818,-0.319161,-0.105926,-0.088794,-0.156342,0.045926,-0.346646,-0.370352,-0.141913,0.317899,-0.101951,0.072891,0.087502,-0.564004,0.031097,-0.350932,-0.356379,0.069974,-0.321358,-0.259137,-0.283784,-0.064506,-0.342054,-0.273519,0.276093,0.188678,0.338649,0.633424,-0.341897,0.095084,0.348488,0.326200,-0.132776,0.594607,0.142128,0.165113,-0.127755,0.105363,0.327543,0.127272,0.371649,0.275878,-0.048373,-0.173338,-0.144585,-0.497232,0.302925', '1478066', '25903033', '21619567', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26326395', '真实魔鬼游戏', '喜剧', '校外旅行途中，乖乖女光子（特林德尔·玲奈 饰）所乘坐的巴士突然被一阵狂风拦腰切成两段，光子刚好俯身捡东西所以幸免于难，但是秋等伙伴全部被齐刷刷地切去了上半身。惊慌失措的女孩夺路狂奔，一路上目睹了无数人被神秘之风杀死的惨状。突然，她仿佛置身于灾难前的时光，惊魂未定的光子和秋等伙伴们一同上学，谁知针对高中女生的大屠杀接踵而至。逃亡途中，光子仿佛穿越了不同的时空，她一会儿是待嫁的新娘启子（篠田麻里子 饰）、一会儿又是参加马拉松大赛的泉（真野惠里菜 饰）。唯一不变的是，针对少女们的追杀从未停止……本片以山田悠介的同名小说为原案改编。©豆瓣', '特林德尔·玲奈', '园子温', 5.8, 31962, 'tt4439120', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2240211848.jpg', 8.3, 25.6, 41.6, 17.5, 7.1, '0.347238,-0.219075,-0.426902,0.179607,0.197293,-0.356638,0.603143,0.198411,-0.341631,-0.341159,0.210379,0.526460,-0.479204,-0.008182,0.291368,-0.051672,-0.224153,-0.773170,-0.415085,-0.132642,-0.475527,0.121375,0.018394,0.060045,0.171801,-0.339394,0.568291,-0.074513,0.068446,0.756111,0.365112,0.436507,-0.422282,0.565063,-0.211888,0.325404,-0.070791,0.056527,-0.048434,0.183576,-0.508096,-0.453283,-0.311248,0.031729,-0.137605,0.424817,0.781816,-0.252079,0.110440,-0.193275,0.179718,-0.256121,-0.034408,0.088769,0.409363,0.081742,0.237584,-0.244743,-0.045130,0.004388,0.304561,-0.055596,-0.382771,0.019694,0.043208,0.080966,-0.609058,0.175374,0.069678,-0.078845,0.268310,-0.043775,0.297158,0.159966,0.319598,0.363051,-0.112999,-0.021260,-0.193641,0.445446,0.702376,-0.006884,-0.199453,0.392027,-0.115748,-0.109063,-0.058721,-0.142277,-0.325809,-0.068934,0.308133,0.206510,-0.153641,0.139915,-0.687112,0.000781,-0.240886,-0.317304,-0.041811,-0.244951,-0.271769,-0.656739,0.240026,-0.151965,-0.084040,0.028702,-0.139452,-0.021632,0.703293,-0.489680,0.292124,0.627250,0.107386,-0.143024,0.419129,-0.290852,-0.080672,0.093318,0.165165,-0.018628,0.241749,0.409564,0.249371,0.556761,-0.056601,-0.102405,-0.385268,0.496125', '3811356', '5403927', '26365262', '35256235');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26328479', '我们都是超能力者！电影版', '剧情', '园子温2015年第五部电影作品。 1313年由园子温主要执导的无节操深夜剧《我们都是超能力者！》除了要在今年春季推出电视特别篇《超能力者上东京》，还将拍摄剧场版《我们都是超能力者！》。主演仍将由染谷将太担任，预计于今年九月上映。 园子温评论：“当时拍电视剧时，电视台很慷慨地给了我从服装、班底到演员的全部决定权，很想拍摄所有集，但因为日程不得不将很多集拜托给了其他导演。因此这次可以全部自己来，十分开心。”', '染谷将太', '园子温', 5.3, 17045, 'tt4473370', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2253404196.jpg', 12.2, 31.8, 39.4, 11, 5.7, '-0.057363,0.164608,-0.324133,0.438688,0.247281,0.032144,0.287092,0.093293,-0.593176,-0.387697,-0.180060,0.530717,-0.575943,0.291593,0.345985,-0.161251,-0.292302,-0.524566,-0.440624,-0.167588,-0.428435,-0.078193,0.130167,-0.023824,-0.486635,-0.303327,0.717587,0.223867,-0.170971,-0.087460,0.384473,0.113457,0.131536,0.319419,-0.036917,-0.163033,-0.250882,-0.132044,-0.199240,0.461623,0.191348,-0.412335,-0.277124,0.012725,0.510929,0.067518,0.941269,0.286336,-0.071448,0.327185,0.766182,-0.200682,0.094889,-0.096117,0.398436,-0.015983,0.097820,0.526491,0.205025,0.311088,-0.130269,-0.614357,-1.001532,0.099441,0.405607,-0.318967,-0.554964,0.451503,-0.345724,0.345067,-0.047893,-0.368365,0.156029,0.171105,0.318545,0.109761,-0.029957,-0.031921,-0.478499,0.784232,0.381177,0.113188,0.141276,0.601457,-0.065785,-0.626077,-0.452366,-0.246329,-0.188530,0.559760,0.052546,0.074804,-0.084044,0.043968,-0.643998,-0.279228,0.180974,-0.788443,0.229972,-0.373644,0.145824,-0.867894,0.231563,-0.172315,0.045517,-0.124371,0.519866,-0.244328,0.950634,-0.636097,0.060529,0.497142,0.094632,-0.369334,0.935706,-0.094080,-0.013803,0.073207,0.251796,-0.344837,0.266527,0.340923,0.449993,0.398597,-0.045354,-0.723795,-0.378073,0.350714', '2027945', '3318306', '22265121', '1473562');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26328481', '昭和64年 前篇', '剧情', '1989年，正值日本的昭和64年，不过这一年份并未持续太久，随着天皇的去世，短暂的昭和64年匆匆落下帷幕。而就在这有限的七天内，某地发生一起幼女绑架案。绑匪索取两千万日元巨额赎金，并与受害者家属和办案人员展开巧妙周旋。虽然受害者的父亲（永濑正敏 饰）按照约定缴纳赎金，但 绑匪还是残忍地将女孩杀害。由于日本上下正处在新旧时代交替的关键时刻，代号为“64”的案件并未引起太多人的关注，即使十多年后，这桩悬而未决的案件依然是许多办案人员难以忘怀的心结。当年作为办案人员的三上义信（佐藤浩市 饰）而今正在群马县警署担任宣传官，终日周旋于上级和媒体中间。“64”的最后时效越来越近，人们仿佛又重新记起了这桩谜一般的案件……本片根据横山秀夫的同名推理小说改编。©豆瓣', '佐藤浩市', '濑濑敬久', 7.3, 7840, 'tt4471630', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2290952646.jpg', 0.9, 5, 38.5, 41.6, 14, '0.246012,-0.106820,-0.467262,0.223984,0.296731,-0.136154,0.643899,-0.120820,-0.640321,-0.552454,0.276946,0.400515,-0.243635,0.025995,0.389159,-0.403945,-0.338152,-0.851413,-0.242022,-0.336140,-0.143376,-0.615804,-0.092129,-0.047591,-0.346297,-0.094420,0.884104,0.184880,0.191189,0.568186,0.172269,0.317179,-0.271681,0.257469,-0.042323,-0.178389,0.155440,0.088927,-0.351634,0.057412,-0.058110,-0.630068,-0.102241,-0.070422,0.162357,0.629784,0.581168,-0.405060,-0.324859,-0.039465,0.472182,-0.274993,-0.229999,-0.070409,0.609704,0.358782,0.327788,0.596247,-0.476471,-0.078763,-0.165547,-0.088556,-0.594020,-0.063098,0.311064,0.211973,-0.325033,0.422524,-0.094260,0.085820,-0.028136,-0.145865,-0.006488,0.584229,0.266467,0.278120,-0.339120,-0.099362,-0.197815,0.306652,0.563976,0.095187,-0.311983,0.099248,-0.157337,-0.512147,-0.033295,-0.362413,-0.109560,0.220012,0.035201,0.143857,0.014619,0.399013,-0.388874,-0.012837,-0.382985,-0.356324,0.195036,-0.228363,-0.153122,-0.805422,-0.107255,-0.487613,-0.246697,0.172855,0.350248,-0.158841,0.509828,-0.613858,0.177139,0.610714,0.189361,-0.407835,0.393661,0.168990,0.242574,-0.306872,-0.208365,-0.097367,0.216190,0.400223,0.091838,0.042753,-0.042591,-0.280779,-0.221062,0.085933', '25723905', '3266509', '2369613', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26328483', '昭和64年 后篇', '剧情', '由于当年办案人员的失误，导致绑匪关键性的电话没有被录下来。相关人员承担责任，警方高层则将其视为禁区只字不提。三上义信（佐藤浩市 饰）与媒体苦苦周旋的同时，竭尽全力试图打破警方的窠臼，同时针对当年的案件展开深入调查。而就在此时，某体育用品商店老板（绪形直人 饰）的女儿遭到绑架，相关手法居然与“64案件”完全一致！难不成是凶手再翻案？三上和同侪全力奔走，警方也投入大量人力展开追查，结果竟然发现令人难以置信的秘密。昭和天皇退出历史舞台，吸引了无数人的眼光。然而即使被时间的尘埃所掩埋，有些事、有些人终究会被人久久铭记……本片根据横山秀夫的同名推理小说改编。©豆瓣', '佐藤浩市', '濑濑敬久', 7.4, 6769, 'tt4471634', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2290868087.jpg', 0.8, 4.8, 33.6, 45.2, 15.7, '0.134971,-0.102508,-0.586100,0.478671,0.205698,0.045022,0.440997,-0.043047,-0.684515,-0.439226,0.200468,0.473668,-0.179055,-0.251642,0.192102,-0.460855,-0.424205,-0.987718,-0.203146,-0.257549,-0.256554,-0.603394,0.033463,-0.292572,0.046012,-0.164577,0.724714,0.109241,-0.375594,0.250468,0.061833,0.448661,-0.451336,0.473618,0.231807,0.154877,0.160760,-0.177625,-0.209310,0.043675,-0.013919,-0.640689,-0.222948,0.234338,-0.218073,0.482539,0.557905,-0.252793,-0.343955,-0.177629,0.410069,-0.565351,-0.017373,0.231869,0.387567,0.144213,0.207212,0.565832,-0.408973,-0.090932,0.262956,0.146900,-0.934689,-0.018508,0.300019,0.236467,-0.238280,0.118275,-0.220248,0.270822,-0.063254,-0.230941,0.089117,0.253369,0.459428,0.046157,-0.191215,-0.086790,-0.298971,0.129127,0.550502,-0.072550,-0.062363,-0.104792,0.011887,-0.269718,-0.140438,-0.221221,-0.118547,0.154009,0.410896,0.195651,-0.033010,0.461699,-0.387316,-0.255011,-0.341701,-0.311570,-0.048780,-0.293409,-0.112068,-0.833459,-0.093795,-0.106744,-0.225186,0.086266,0.207510,-0.169897,0.578035,-0.534890,-0.125090,0.692341,0.084204,-0.516926,0.426529,-0.088433,-0.031454,-0.162868,-0.419928,-0.201624,0.446108,0.550963,0.189990,0.017211,0.035201,-0.380084,-0.140837,-0.112916', '25723905', '1307442', '27126336', '2367213');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26329059', '伟大的愿望', '剧情', 'NEW投资发行，Contents Panda出品，브레인샤워制作。讲述了患上肌萎縮性脊髓側索硬化症的高中生，和朋友、家人度过最后时间的温暖又愉快、令人感动的故事。 2016年4月上映。', '柳德焕', '南大中', 7.5, 20164, 'tt6448982', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2382130301.jpg', 0.5, 3.1, 34.5, 45.9, 15.9, '-0.497495,-0.760012,0.328437,-0.152765,0.534152,-0.088664,0.321295,-0.086947,-0.603764,-0.196176,0.024050,0.228028,-0.543004,0.152435,0.560153,-0.120018,-0.574686,-0.492714,0.400726,-0.371095,0.101471,-0.051643,-0.076854,-0.271244,0.146993,-0.518060,0.649127,0.096849,0.308740,0.567347,-0.242528,-0.095380,-0.064314,0.101303,0.094654,0.171601,-0.101463,0.373387,-0.784384,0.379497,0.216720,0.175306,0.009574,-0.503922,0.405666,0.396925,0.661547,-0.055818,-0.256406,0.050291,0.815351,-0.134316,-0.392249,-0.350518,0.068570,0.855629,0.893114,0.474885,-0.269504,-0.558013,-0.210894,-0.735469,-0.555779,0.323934,0.207222,-0.025510,0.063752,0.479962,-0.099489,0.753922,0.042821,-0.374996,0.007900,0.511832,0.699913,0.812441,-0.060477,0.530681,0.073045,1.143609,0.684114,-0.288622,-0.464902,0.707592,-0.304318,-0.259537,-0.148986,-0.588199,-0.232994,0.304520,0.077564,0.304156,-0.280979,0.452814,-0.371301,0.118513,0.218660,-0.372652,0.656838,-0.201598,-0.045910,-0.760146,-0.208992,0.240741,-0.173296,-0.131784,0.443713,-0.603195,1.060250,-0.440359,0.129793,0.364368,0.897541,-0.190175,1.014303,-0.142150,-0.129590,-0.311063,0.155404,0.715124,-0.578840,0.055444,0.125480,0.186344,-0.232081,0.109735,-0.646445,0.116017', '30488584', '1908036', '22265121', '34947776');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26330955', '熊出没之熊心归来', '喜剧', '雨季降至，为了避免塌方，熊大（张伟 配音）带领着动物们开始加固堤坝，然而，动物们对此很不上心，偷懒的偷懒，逃避的逃避，令熊大很是生气。一场意外中，泥石流袭来，熊大被冲走了，当它醒来之时，发现自己竟然身处一间马戏团之中。熊大利用自己的实力获得了留在马戏团里表演的资格，并且很快就成为了当红的动物明星。随着时间的推移，被名声和荣誉冲昏了头脑的熊大渐渐忘记了想要回到森林之中的念头，他和马戏团团长黑猩猩亦产生了心心相惜的友谊。熊二（张秉君 配音）找到了熊大，希望熊大能够跟它回家，因为森林里的动物们一个接着一个神秘失踪了，然而熊大却拒绝了熊二的请求，继续做着它的明星梦。©豆瓣', '张伟', '丁亮', 7.3, 14792, 'tt5471154', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2303088664.jpg', 4.1, 6.5, 32.8, 32.6, 24, '0.406641,0.353902,-0.707331,0.596211,-0.174745,-0.136212,0.797827,-0.075179,-0.391430,-0.374796,-0.144513,0.575162,-0.270816,0.433432,0.041758,-0.262002,-0.191115,-0.488146,-0.067274,-0.063470,-0.213988,-0.184883,-0.319337,-0.169071,-0.273740,-0.070840,0.631552,0.141894,-0.326313,0.481440,0.101340,0.121352,0.092943,0.633212,-0.011320,0.201124,0.074559,0.012288,0.103187,0.331041,0.022042,-0.079880,0.003306,0.243947,-0.007847,0.225080,0.703363,-0.492181,-0.263442,-0.319676,0.246454,-0.504559,0.151253,0.252682,0.289159,-0.084815,0.282983,-0.109002,-0.137810,0.287033,0.010510,-0.138450,-0.537580,0.202738,-0.084291,0.223345,-0.604386,0.219313,0.264324,-0.136514,0.149593,-0.265012,0.220552,0.231971,0.324018,0.398280,-0.428962,0.011419,-0.448606,0.033467,0.937163,-0.269303,-0.238886,0.391292,-0.089860,-0.557442,0.256054,-0.082368,-0.244615,-0.285405,0.448783,0.343590,-0.376337,0.154123,-0.745760,-0.057095,-0.155179,-0.368917,-0.304916,-0.374560,0.013232,-0.318530,-0.078334,-0.221263,-0.210842,0.018679,-0.180203,-0.433696,0.656115,-0.888604,0.166239,0.680113,0.271101,-0.321134,0.542251,-0.091288,0.103332,0.086292,0.106141,-0.076964,-0.080609,0.328255,0.217730,0.262838,-0.090961,-0.330640,-0.389800,0.564576', '2032339', '3055049', '35030151', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26331185', '离别是美丽的', '爱情', '告别一个阶段、离开一段关係、再见曾经的生活，从来都是漫长的过程。接受需要时间、重生需要勇气，最后的再见，总要一步一步走过去。婚姻来到尽头的母亲跟自己的儿子，来到法国南部的渡假屋作最后执拾，准备向这间满载幸福回忆的大屋诀别。还在哀悼逝去感情的妈妈，跟儿子关係渐变疏离。面对明媚却寂静的风光，一名男子的出现，为二人带来不同程度的震盪，美丽的记下了婚姻的终结、少年时代的告终和一个中产家庭的瓦解。', '茱丽叶特·斯蒂文森', '安德鲁·斯特格奥', 7.5, 11002, 'tt2248739', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2363394711.jpg', 0.5, 3.7, 33.9, 44.8, 17.1, '0.048950,0.022745,-0.468736,0.515015,-0.094384,-0.589408,1.107663,0.061730,-0.183657,-0.329834,0.230517,0.647778,-0.108371,0.406117,0.623934,-0.262272,-0.084884,-0.710872,-0.077568,-0.086099,-0.298032,-0.308034,-0.031730,-0.038981,-0.112240,-0.192521,0.851601,0.368536,-0.064750,0.478845,0.031189,-0.162686,-0.318308,0.257594,-0.269807,-0.034466,-0.295726,0.316203,-0.950911,0.190017,-0.001821,0.016832,-0.293589,-0.150390,-0.027999,0.061678,0.715889,-0.014029,-0.308651,0.177618,0.446637,-0.088293,-0.293448,0.304637,0.027897,0.161621,-0.137172,0.539611,-0.189381,-0.020413,-0.105544,-0.439543,-0.817844,0.141767,-0.120153,0.006761,-0.615641,0.628736,0.301699,-0.033851,0.416899,-0.518106,0.192826,0.418639,0.265347,0.860547,-0.475700,0.362921,-0.245397,0.145293,0.970122,-0.177627,-0.185356,0.587254,-0.195970,-0.218471,-0.107156,-0.033444,-0.785675,0.098933,-0.220733,0.334269,-0.155110,0.206619,-0.650713,0.214443,-0.351090,-0.302983,0.342194,-0.700176,-0.082694,-0.420174,-0.122622,-0.295857,-0.484227,0.531721,-0.073421,-0.312340,0.519554,-0.440499,0.372463,0.148733,0.489867,-0.590162,0.965779,0.439554,0.140216,-0.319414,0.370661,0.894039,-0.267824,0.433235,-0.309851,-0.003393,-0.162159,0.353535,-0.651428,0.505854', '1291835', '34925598', '35225859', '30209018');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26331700', '大轰炸', '动作', '1937年抗日战争爆发，继淞沪战争失利，南京吃紧。中华民族危急存亡之际，国民政府宣布迁都重庆，日军从1938年2月18日至1944年12月19日，对重庆及周边地区实施无差别轰炸，长达六年零十个月。 重庆市民面对日军残酷的狂轰滥炸，依然向死而生、乐观坚强，展现了重庆不死中国不亡的民族气节。为了保卫家园，年轻的中国飞行员在美国飞行教官的帮助下与日本空军展开了一系列惨烈悲壮的空战。虽然飞行装备远远落后于日军，但他们宁愿战死在天上，也不在地上苟活，与敌人在长空进行殊死搏斗......', '刘烨', '萧锋', 2.8, 10912, 'tt4743226', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2530279878.jpg', 71.2, 19.7, 7.8, 1, 0.4, '-0.249353,-0.106695,-0.669864,0.182676,0.353871,-0.064195,-0.029108,-0.408197,-0.128323,0.125330,0.534527,0.424465,-0.008706,-0.363481,0.067260,-0.547014,-0.286275,-0.687034,-0.249442,0.102322,-0.156990,-0.401286,-0.134366,-0.349613,-0.153664,-0.211902,0.921883,0.513646,-0.024303,0.635524,-0.020486,0.177048,0.202994,0.504802,0.014356,-0.390873,-0.288374,-0.198603,-0.473603,0.316037,-0.167882,-0.643466,-0.204775,-0.218230,0.083054,0.146126,0.850054,-0.266795,-0.134644,-0.416426,0.462959,-0.378102,-0.308174,0.262527,0.549521,0.006315,-0.366603,0.340532,0.088749,-0.372626,-0.333853,-0.191364,-0.260128,0.054425,-0.221151,-0.252960,-0.347104,0.730150,-0.260444,0.544178,0.220414,-0.280868,0.078409,0.961583,0.053953,0.593828,-0.557869,0.219551,-0.362617,0.407398,0.817878,-0.083987,-0.652772,-0.380387,0.104531,-0.428591,0.011152,-0.617699,-0.151070,-0.027328,-0.111720,-0.291550,0.089046,0.478117,-0.621248,0.405681,-0.441203,-0.594716,0.072263,0.001974,-0.371954,-0.687714,-0.025407,-0.595388,-0.419937,0.437058,0.194296,0.090588,0.912933,-0.691790,0.238817,0.544998,0.601827,-0.334580,0.539188,0.274477,0.019175,-0.017603,0.116045,0.694461,-0.395619,0.445533,0.180742,0.034503,-0.236883,0.173721,0.049879,0.115812', '3078390', '1826173', '35058077', '1424552');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26331839', '保持沉默', '剧情', '电影《保持沉默》讲述了著名歌星万文芳在密闭的化妆间遇刺，当时在场的只有吉米托马斯（孙睿饰）一个人。端木兰律师（周迅饰）作为吉米的辩护律师，准备为他做无罪辩护，因而在法庭上与该案的检控官吴正为（吴镇宇饰），展开了激烈的争辩，真相在一层层地被揭开。此时又有知情人称，嫌疑人吉米托马斯正是万文芳曾经遗弃的私生子，这个爆料也让案件的性质变成了“弑母”大案。随着本案的关键证人，万文芳的制作人田景程（祖峰饰）的介入，真相愈加扑朔迷离。', '周迅', '周可', 5.2, 56986, 'tt6968118', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2565877341.jpg', 7.6, 36.9, 44.6, 9.2, 1.8, '0.511240,0.011751,-0.514904,0.495779,-0.036914,-0.062855,0.899611,0.277756,-0.394660,-0.260550,0.258587,0.690309,-0.475671,0.104466,0.330688,-0.218145,-0.338469,-0.761181,-0.028030,-0.146670,-0.055978,-0.931762,-0.064880,-0.510503,0.006139,0.041901,0.504391,-0.042816,-0.409952,0.037316,0.736038,0.285681,-0.111682,0.356045,0.144417,-0.049293,0.174435,-0.024184,-0.454723,0.050425,-0.022510,-0.641747,0.091055,0.286179,-0.047153,0.575927,0.426767,-0.385152,-0.131280,0.047487,0.731792,-0.635926,0.132809,0.072695,0.308900,0.203155,-0.021170,0.493625,-0.248491,-0.194998,0.005166,0.044880,-0.899505,-0.004599,0.339981,0.323568,-0.338829,0.278523,-0.281523,0.052267,0.165701,-0.118690,0.363332,0.314295,0.078182,0.357462,0.102366,0.005322,-0.414246,0.378976,0.376762,0.159304,-0.149707,0.167715,-0.013457,-0.460837,-0.046707,-0.133023,-0.222896,-0.078996,0.376978,-0.055780,0.012782,0.232023,-0.328265,-0.349931,-0.123442,-0.211948,0.182819,-0.257223,-0.190602,-0.446107,-0.274361,-0.049924,-0.276808,-0.141711,-0.091282,-0.353691,0.498900,-0.514119,0.074425,0.455301,-0.052794,-0.433194,0.444192,0.438053,0.309341,-0.150430,-0.190813,-0.012933,0.236681,0.367041,0.081644,0.338494,0.101474,-0.335682,-0.450921,-0.008649', '1293989', '25862560', '1296217', '25921830');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26333124', '十七岁', '爱情', '1983年夏日，17岁的林克铭（石知田 饰）和王蕾（程予希 饰）因为一场英文演讲比赛结识，懵懂的情感就此发芽。然而一次年少轻狂的意外，硬生生地将两人分离，也浇灭了初恋热血的悸动，甚至没有来得及告别，还没有开始就要说再见的初恋，就在这首Bee Gees的《First of May》中结束。20多年后，45岁的王蕾（贾静雯 饰）的女儿，同样17岁的白白（程予希 饰）令他们的人生再度交错，45岁的林克铭（任贤齐 饰）收到网上传来的一封信，一封似是迟来的、王蕾的信，让他再度忆起，那份纯情的年少时光、那段属于十七岁的狂妄，还有那份寂寞的遗憾。似乎冥冥之中注定了这个特殊的年纪将会有特殊的意义，17岁的白白，也陷入了一场情感的困惑，面对心仪的男生和最好的姐妹，她不知道该如何选择.....©豆瓣', '任贤齐', '周格泰', 6.9, 13309, 'tt5245630', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2274092981.jpg', 1.9, 9.5, 44.3, 32.4, 11.9, '0.438326,0.339754,-0.751290,0.707774,-0.307112,-0.358616,0.787590,-0.165728,-0.351465,-0.184259,0.008657,0.699188,-0.350862,0.594586,0.322210,-0.060447,0.272018,-0.848857,-0.019253,-0.201853,-0.226009,-0.421329,-0.240394,0.046026,0.092698,-0.397945,0.742469,0.303850,0.058655,0.841963,0.343260,0.089794,0.161598,0.505689,-0.163431,0.100734,0.000954,0.510367,-0.144137,-0.134861,0.220575,-0.396331,0.008000,0.198391,-0.140486,0.622229,0.923581,-0.159152,-0.225653,0.241850,0.669543,-0.094564,-0.192311,0.201431,0.141693,0.062185,-0.035143,0.100221,-0.165820,-0.014864,-0.108272,0.090252,-0.688678,-0.145815,0.108247,0.099503,-0.431459,0.728847,-0.121148,-0.164911,0.100925,-0.100445,0.128256,0.412376,0.348587,0.621012,-0.279609,-0.179374,-0.240450,0.543184,0.733828,0.036041,-0.447873,0.649271,-0.294379,-0.510154,0.018566,-0.140952,-0.658959,0.197519,0.263207,0.277284,-0.409337,0.099343,-0.521145,-0.102533,-0.059627,0.057664,0.234329,-0.602437,-0.189316,-0.132082,-0.397606,-0.661435,-0.421860,0.239970,0.310987,-0.183610,0.874290,-0.601036,0.327264,0.433542,0.158507,-0.223689,0.649304,0.392702,-0.177785,-0.165371,0.153621,0.336525,-0.519551,0.032189,0.236623,0.320046,-0.039077,-0.169200,-0.484068,0.433486', '3811356', '2365260', '3155839', '20390013');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26333560', '疾速追杀2', '动作', '在经历过一系列风波后，约翰·威克（基努·里维斯饰）也重新养了一只健康的狗狗。一心想要退休的约翰·威克再度被自己之前的事业所困扰，他此前的雇主现在正在被追杀，受困于自己之前的承诺，约翰·威克只能飞去罗马帮助他脱围。在罗马这个古老的城市里，约翰·威克遇见了全世界最强的杀手，于是乎他只能拿起枪来保护自己。', '基努·里维斯', '查德·斯塔赫斯基', 7.8, 147411, 'tt4425200', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2406752213.jpg', 0.6, 3.3, 25.8, 45.3, 25, '0.183356,0.080047,-0.745721,0.488510,-0.180512,-0.577825,0.822031,-0.040043,-0.549854,-0.192078,0.341726,0.955201,0.064801,0.387664,0.373115,0.200878,-0.322875,-0.657924,0.014611,-0.000483,-0.162630,-0.552867,-0.615102,-0.362309,-0.150019,-0.200882,0.439257,-0.050963,-0.114228,0.211571,0.041724,0.370827,0.202903,0.376736,-0.172997,0.205400,0.164531,-0.163883,-0.189157,0.151352,0.108845,-0.261742,-0.022832,0.643728,-0.068677,0.424979,0.513898,-0.297767,-0.035523,-0.367031,0.058446,-0.298780,0.148135,0.271487,0.255852,-0.074278,0.273642,0.091429,-0.241043,-0.073443,-0.096554,-0.117293,-0.793720,-0.169168,-0.288021,-0.092397,-0.873018,0.417568,-0.293842,0.073240,0.144148,-0.329316,0.055376,0.556844,0.280386,0.238929,-0.310759,-0.000272,-0.415605,0.310781,0.696720,-0.268486,-0.111191,0.254838,-0.136433,-0.332470,-0.059483,-0.282536,-0.540884,0.009817,0.716190,0.071790,-0.356320,0.291174,-0.567175,-0.013475,-0.602872,-0.416109,-0.246632,-0.157270,-0.126948,-0.321778,-0.021279,-0.398853,-0.357080,-0.324477,-0.126985,-0.075368,0.543511,-0.810074,0.382529,0.715893,0.065934,-0.409844,0.461530,0.200271,0.467966,0.127076,0.022211,0.447280,0.117263,0.720998,0.133774,0.472466,0.515432,-0.294493,-0.188130,0.780837', '1309069', '25763555', '10774184', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26334559', '澳门风云3', '喜剧', '石一坚（周润发 饰）在女儿（童菲 饰）的婚礼上，因误用兄弟小马（张家辉 饰）的“催眠治疗”加上机器人炸弹袭击而变得精神错乱。神秘人物易天行（张学友 饰）一心想要置石一坚于死地，幸亏龙五（向华强 饰）带领儿子龙十五（向佐 饰）及时营救。“赌侠”刀仔（刘德华 饰）与赌神表妹高菲（李宇春 饰）也一起来帮助石一坚恢复记忆，众人终于知道易天行就是幕后黑手，为了调查清楚真相，石一坚与“赌神”（周润发 饰）联手，最后大战一触即发。©豆瓣', '周润发', '王晶', 4.4, 140824, 'tt5237980', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2309171908.jpg', 31.8, 31.8, 25.2, 6.5, 4.7, '-0.395955,-0.234148,-0.406625,0.364317,0.283419,-0.090208,0.365670,0.109863,-0.391462,-0.423640,0.341840,0.402230,-0.218138,0.040023,0.282674,-0.130907,-0.227126,-0.472939,-0.040468,0.306759,-0.147016,-0.458303,-0.397164,-0.118592,0.177387,-0.325294,0.246449,0.072141,-0.153416,0.599126,0.706901,0.289400,-0.498116,0.005314,0.369927,-0.127108,-0.301841,-0.022909,-0.611143,-0.082569,-0.199141,-0.417706,0.004842,0.274004,-0.028782,0.336431,0.562066,-0.204396,0.099419,-0.139906,0.256293,-0.176605,-0.228823,-0.017011,0.198888,0.101169,0.332849,0.086336,-0.092531,0.153132,0.148566,0.057203,-0.631144,0.197548,0.365614,0.026087,-0.223984,-0.076469,-0.152198,0.197024,-0.008466,-0.135318,0.254999,0.248583,0.451755,0.096818,-0.125519,-0.199997,-0.242125,0.329664,0.283253,-0.081162,0.376373,0.243807,0.491174,-0.381997,-0.233669,0.072966,-0.018058,0.200312,0.406241,0.042840,0.012562,0.049828,-0.187661,-0.379617,-0.203532,0.251839,-0.245051,-0.104898,0.227916,-0.370463,-0.151781,-0.075057,0.027334,0.150383,0.003386,-0.219267,0.473149,-0.612471,-0.044312,0.087956,0.193005,-0.491260,-0.001668,-0.073768,0.010223,-0.349230,0.012260,-0.104321,0.002784,-0.325942,0.165926,0.105410,-0.138520,-0.234657,-0.172528,-0.089733', '4301278', '1305016', '26984538', '1433602');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26334996', '雪路', '剧情', '故事发生在1944年，日军残酷无情的铁蹄踏破了朝鲜土地上的宁静，一时间硝烟四起哀鸿遍野，百姓失去了赖以生存的家园，只能在燃烧的熊熊战火和被敌人统治的屈辱之下忍辱偷生。崔钟芬（金香奇 饰）和金英爱（金赛纶 饰）是两名平凡的朝鲜女孩，金英爱十分嫌弃看上去土里土气的崔钟芬，而崔钟芬却对金英爱青睐有加，只因为她喜欢上了金英爱的哥哥。某日，金英爱的哥哥被日本人抓走，为了救哥哥，金英爱毅然决然的坐上了前往日本的火车，崔钟芬亦随她而去。然而，两个女孩没有想到的是，这趟火车的终点竟然是日方慰安所，两朵纯洁无暇的娇花在这里遭受了惨无人道的摧残。©豆瓣', '金香起', '李娜静', 8.3, 18480, 'tt8216024', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2422756815.jpg', 0.2, 1, 15.5, 52.1, 31.1, '0.258857,0.031216,-0.844260,0.401705,-0.128191,-0.170840,0.813077,0.144563,-0.471913,0.200231,0.263035,0.588370,0.028743,0.120112,0.172186,0.183481,-0.063344,-0.638427,-0.227333,-0.095360,-0.251024,-0.302767,-0.072687,-0.126243,-0.141656,-0.338322,0.575642,0.322000,-0.168758,0.511992,0.432100,0.223130,0.010402,0.578599,-0.227689,0.081617,-0.274974,0.013176,0.012107,0.084414,-0.205579,-0.523201,-0.045938,0.175334,-0.282636,0.262261,0.666527,-0.339708,-0.039260,-0.298832,0.246439,-0.554592,0.021579,0.326039,0.275435,-0.218389,0.112442,0.021684,-0.186742,-0.231700,0.254090,-0.102447,-0.471690,0.048977,0.093405,0.143498,-0.687981,0.865244,-0.042066,-0.173297,0.255482,-0.248451,0.496266,0.255951,0.083318,0.535029,-0.253141,-0.087990,-0.496843,0.292129,0.876391,0.019742,-0.063576,0.257656,-0.375618,-0.249390,0.012374,-0.447061,-0.540855,0.007773,0.166990,-0.137312,-0.233321,0.064095,-0.719746,0.122189,-0.228867,-0.364602,-0.094682,-0.356140,-0.266688,-0.138959,-0.049102,-0.644788,-0.260600,0.307748,-0.012398,-0.102967,0.776631,-0.813694,0.329606,0.507673,0.371507,-0.422350,0.589174,0.215954,-0.241194,0.195357,0.041483,0.358007,0.112569,0.401875,0.214753,0.206846,-0.208220,0.132562,-0.307838,0.360222', '35030151', '25721544', '1308755', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26335580', '类人猿行动', '剧情', '杰米·多南与希里安·墨菲加盟二战题材影片《类人猿行动》（Anthropoid）。影片根据真实事件改编，英国训练两名捷克斯洛伐克士兵，刺杀纳粹党卫军头目莱因哈德·海德里希，行动代号”类人猿“。影片由《超市夜未眠》的导演西恩·埃利斯执导，2015年7月捷克布拉格开拍。', '詹米·多南', '西恩·埃利斯', 7.7, 11931, 'tt4190530', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2360052887.jpg', 0.4, 2.1, 28.7, 50.9, 17.8, '-0.262980,-0.323952,-0.257593,0.218338,0.852772,-0.315813,0.320396,-0.229124,-0.247722,-0.511907,0.279387,0.520217,-0.319843,-0.488827,0.725271,-0.002665,-0.958645,-0.712229,-0.385519,0.224176,0.191549,-0.337195,-0.357303,-0.651332,0.246975,-0.455745,0.746068,-0.187776,-0.251133,0.251148,0.323819,0.485556,0.020631,-0.375458,0.633334,0.194679,0.760828,-0.882419,-0.805222,0.192989,-0.186950,0.021574,-0.795250,-0.136315,0.285256,0.267724,0.514604,-0.376495,0.144824,-0.320734,0.497613,-0.309755,-0.238414,-0.533217,0.246376,0.220018,0.304600,0.404611,0.821437,-0.013618,-0.660234,-0.471644,-0.004238,0.370409,-0.118739,0.224969,-0.077114,-0.018640,-0.881226,0.872610,0.044872,-0.229604,-0.294270,0.161576,0.443281,0.205770,0.316993,0.018611,-0.257862,0.582620,0.200616,-0.157023,-0.503423,-0.108056,0.075374,-0.452968,-0.260323,0.035840,0.021122,0.443759,0.341976,-0.748302,0.096282,0.543101,-0.317663,-0.078298,-0.511368,-0.460968,-0.176104,0.192073,0.211591,-1.752002,-0.208969,0.135092,0.208685,-0.527562,0.189576,0.199228,0.335101,-0.356196,0.375641,0.429490,0.241612,0.019755,0.133739,-0.124507,-0.004858,-0.389978,0.006684,0.710938,-0.218788,-0.499223,0.068551,0.295912,0.177587,-0.424211,-0.037717,0.045707', '34961898', '1293572', '6517421', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26336252', '碟中谍6：全面瓦解', '动作', '伊森·亨特（汤姆·克鲁斯饰）和队友们接到了追回三个大杀伤性核武器的任务。眼见任务马上就能完成，但为了挽救其中一位队友卢瑟（文·瑞姆斯饰）的生命，三个核武器被人趁机带走。中情局负责人斯隆女士（安吉拉·贝塞特饰）调来她手下的得意猛将沃克（亨利·卡维尔饰），让他盯着伊森·亨特完成追回核武器的任务。期间，女特工伊尔莎（丽贝卡·弗格森饰）突然出现，伊森·亨特发现，他要面对的并不只是恐怖分子，还有潜藏在政府部门的内鬼。', '汤姆·克鲁斯', '克里斯托弗·麦奎里', 8.1, 484500, 'tt4912910', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2529365085.jpg', 0.3, 1.6, 19.8, 50.9, 27.4, '0.107640,0.040297,-0.417703,0.388804,-0.247103,-0.289338,0.613166,-0.195677,-0.368645,-0.396375,0.257938,0.590437,-0.068790,0.022536,0.367578,0.070024,-0.549428,-0.573045,-0.110285,0.095001,-0.474594,-0.621389,-0.318545,-0.583336,-0.087417,-0.181651,0.510537,-0.228186,0.179639,0.278016,0.351497,0.480544,-0.006710,0.361838,0.110660,0.008322,0.556798,-0.684175,-0.081019,0.504615,0.277702,0.143029,-0.178457,0.220934,0.134322,0.437360,0.358971,-0.164534,0.261778,-0.062113,-0.149269,-0.444792,0.184262,-0.015410,-0.011706,-0.187983,-0.109834,0.043607,-0.128527,0.309808,0.239269,-0.266436,-0.601668,0.165226,-0.009956,0.409110,-0.235401,0.119838,-0.537986,0.313288,0.190241,-0.284038,-0.109199,0.245722,0.432045,0.172796,-0.206712,0.112739,-0.616998,0.045610,0.152921,-0.218583,-0.184113,0.012105,-0.138815,-0.477413,-0.166195,0.004484,-0.220981,0.172953,0.669255,0.012380,0.123482,0.197178,-0.645254,-0.323752,-0.517635,-0.176932,-0.261738,-0.213290,0.012591,-0.868089,0.245230,0.072006,-0.454674,0.409640,0.109044,-0.240057,0.425035,-0.616901,0.114613,0.570410,0.229405,-0.301476,0.182609,0.093135,0.385719,-0.284078,-0.158950,0.237185,0.497284,0.302762,0.195310,0.148037,0.154778,-0.558452,-0.054539,0.264772', '6517421', '2028645', '1298616', '2369549');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26336253', '使徒行者', '剧情', '高级警官康Sir遭人杀害，临死前他销毁了所有卧底的资料，以保护这些游走在生死线上的兄弟。在此之后，警方开始着手恢复数据，与卧底们重新取得联系。女卧底阿钉（佘诗曼 饰）某天收到一条康Sir发明的密码，在刑警男友阿Q（吴镇宇 饰）的指挥下，她尝试与这名神秘卧底进行接触。另一方面，某披着合法公司外皮的黑道组织重要成员阿蓝（张家辉 饰）和邵志朗（古天乐 饰）联手袭击了竞争对手。这二人情同手足，在公司少壮派中风头正劲，如日中天。然而警方对他们行动的预判令阿蓝开始怀疑公司有内鬼存在。经过几番试探，阿钉终于与神秘卧底接头，可是莫大的危险也向她奔涌袭来……©豆瓣', '张家辉', '文伟鸿', 6.9, 198568, 'tt5896962', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2369022569.jpg', 1.6, 9.2, 43.7, 33.6, 11.8, '0.249702,0.019584,-0.515465,0.446139,0.063032,0.131144,0.412664,0.005476,-0.513620,-0.396468,0.278041,0.345785,-0.096089,0.045673,0.113890,-0.191050,-0.314166,-0.850383,-0.169925,-0.273655,-0.312438,-0.338762,-0.335065,-0.190607,-0.054791,-0.035817,0.575109,0.118600,-0.334820,0.357997,0.465717,0.470854,-0.497831,0.169535,-0.160222,-0.056512,0.321759,-0.111771,-0.436424,0.205829,0.097459,-0.206794,-0.108861,0.217117,0.084731,0.445596,0.530467,-0.233099,-0.201788,-0.066942,0.321324,-0.326702,0.040435,0.115051,0.621683,0.438224,0.078287,0.382420,-0.135023,-0.175544,-0.220336,0.035692,-0.880658,-0.247648,0.159481,0.192998,-0.548903,-0.013228,-0.298275,0.174160,-0.064156,-0.218316,0.227362,0.610260,0.081664,0.006429,0.031601,0.132017,-0.424213,0.159434,0.592249,0.083691,-0.025070,-0.194183,0.188642,-0.276143,-0.113323,-0.181666,-0.154413,-0.181963,0.309399,-0.033156,0.132896,0.091860,-0.756623,-0.001904,-0.163491,-0.043111,-0.038755,-0.185581,0.007720,-0.882333,-0.392859,-0.227543,-0.184816,0.223742,0.050263,-0.286942,0.628327,-0.933597,0.148421,0.581798,0.433312,-0.760331,0.367417,-0.027465,0.078850,-0.575419,-0.318775,-0.113689,0.469872,0.342688,0.317200,0.187876,-0.141822,-0.211861,-0.310210,-0.319939', '25723905', '2369613', '1498811', '1307762');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26337866', '路边野餐', '剧情', '在贵州黔东南神秘潮湿的亚热带乡土，大雾弥漫的凯里县城诊所里，两个医生心事重重活得像幽灵。陈升为了母亲的遗愿，踏上火车寻找弟弟抛弃的孩子；而另一位孤独的老女人托他带一张照片、一件衬衫、一盒磁带给病重的旧情人。去镇远县城的路上，陈升（陈永忠 饰）来到一个叫荡麦的地方，那里的时间不是线性的 ，人们的生活相互补充和消解。他似乎经历了过去、现在和未来，重新思索了自己的生活。最终，陈升到了镇远，只是用望远镜远远地看了孩子。把老女人的信物给了她旧情人的儿子。一个人再次踏上火车。分不清这个世界是我的记忆，还是我是这世界的一个浮想……©豆瓣', '陈永忠', '毕赣', 7.9, 157263, 'tt4613272', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2366570716.jpg', 1.5, 3.6, 20.1, 45.7, 29, '0.243089,-0.024457,-0.508530,0.705295,-0.472475,-0.270250,0.979925,0.324349,-0.620460,-0.053773,0.164987,0.894261,0.281527,0.400692,0.156825,0.262267,-0.486153,-0.652476,0.158227,-0.284092,-0.603088,-0.253819,-0.251691,-0.221641,0.117367,-0.152151,0.434975,0.245763,0.126000,0.415314,0.082121,-0.008336,-0.151526,0.527681,-0.580237,0.199008,-0.086677,0.085833,-0.152011,0.059272,0.071001,-0.159920,-0.121044,0.120803,-0.134608,0.317657,0.822235,0.040616,-0.055115,-0.239647,0.036171,-0.230529,-0.145854,-0.163051,0.077150,0.060540,0.109214,-0.005380,-0.207218,-0.232262,-0.064786,0.049233,-0.464742,0.138823,-0.073812,0.114863,-0.641757,0.611189,-0.097935,-0.159615,0.023122,-0.490039,0.439536,0.019976,0.030533,0.594744,-0.343781,-0.055961,-0.666196,0.285736,0.481054,-0.045420,-0.110521,0.549822,-0.205147,-0.224973,-0.092423,-0.026799,-0.723098,0.049680,0.362188,-0.118241,-0.410208,-0.002630,-0.735877,0.102545,-0.188230,-0.290535,0.121615,-0.477780,-0.390663,-0.163309,-0.032870,-0.431304,-0.042049,-0.087079,0.078780,-0.155493,0.712546,-0.359845,0.139015,0.589650,0.210542,-0.662202,0.917969,0.108366,0.230713,-0.295767,0.273288,0.096440,-0.013501,0.559983,0.172930,0.391945,-0.167148,0.225099,-0.644417,0.623153', '26884422', '21619567', '3055049', '26677495');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26339213', '无名女尸', '恐怖', '奥斯丁（埃米尔·赫斯基 Emile Hirsch 饰）和父亲汤米（布莱恩·考克斯 Brian Cox 饰）同为镇上的验尸官，某天晚上，刑警谢尔顿（迈克尔·麦克埃尔哈顿 Michael McElhatton 饰）送来了一具无名女尸，希望汤米和奥斯丁能够在天亮之前弄清楚她身上的秘密。奇怪的是，这具女尸身上没有任何的淤青或伤口，然而她的内脏和骨骼却伤痕累累，很显然生前遭到了残酷的虐待。在解剖的过程中，难以用科学解释的谜团越来越多，挑战着汤米丰富的经验和好奇心，而屋外忽然降下的暴雨亦给这个不平凡的晚上带来了一丝阴森的气氛。行踪诡异的人影，忽近忽远的脚步，似真似幻的可怕光景，很快，父子两人便发现，他们要做的最重要的事情并不是解开女尸之谜，而是尽快的逃离她，逃得越远越好。©豆瓣', '埃米尔·赫斯基', '安德烈·艾弗道夫', 7.6, 111345, 'tt3289956', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2407543903.jpg', 0.5, 3, 30.4, 48.6, 17.5, '0.380709,-0.179261,-0.689853,0.442009,0.039040,-0.293056,1.071541,-0.039730,-0.508861,-0.453777,-0.005900,0.541613,-0.040186,0.108782,-0.181577,0.121192,-0.402873,-0.588948,0.026171,-0.232870,-0.448775,-0.378015,-0.457105,-0.184384,0.102898,-0.278351,0.477870,0.323956,-0.104297,0.390983,0.108561,0.078875,-0.051353,0.767728,-0.328159,-0.144600,-0.087605,-0.108950,-0.070430,0.106772,0.333363,-0.259347,-0.149908,0.455071,-0.199393,0.503444,0.421333,-0.312800,-0.277189,0.118821,0.310218,-0.336301,0.158639,0.052548,0.203381,-0.053937,0.344806,0.298933,-0.103553,-0.107852,0.173042,0.027216,-0.768368,0.136181,0.112057,0.425327,-0.377589,0.465783,-0.093016,0.061854,0.114288,-0.362183,0.334427,0.041635,0.087087,0.370672,-0.379290,-0.182165,-0.470480,0.023877,0.391978,0.197185,-0.179589,0.363278,-0.202728,-0.469123,-0.158941,-0.124178,-0.037575,-0.005838,0.461374,0.511065,-0.307851,0.228893,-0.395438,0.022468,-0.268744,-0.053817,-0.464157,-0.251035,-0.171390,-0.387600,-0.185243,-0.477414,-0.337672,0.016690,0.047407,-0.331174,0.206630,-0.569357,0.283008,0.411828,0.099757,-0.185575,0.220241,0.050947,0.136941,-0.054785,-0.239251,0.085298,-0.045128,0.302610,0.294724,0.547541,-0.018305,-0.109829,-0.448509,0.475411', '25909236', '1417428', '21348112', '1297996');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26339228', '迷失：消失的女人', '悬疑', '讲述女儿被绑架的母亲与绑架孩子的家务助理在4天之中发生的故事的惊悚片。严智苑饰演一人培养女儿的母亲，追踪丢失的女儿的下落。孔晓振饰演与孩子一起消失的家务助理，加重影片的紧张感和悬疑。', '严志媛', '李彦禧', 7, 7173, 'tt6292996', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2392137525.jpg', 1.1, 6.9, 46.9, 33, 12.1, '0.117346,-0.717286,-0.535766,0.829247,-0.146321,-0.102190,1.034778,0.265925,-0.370287,-0.662908,0.312929,0.913313,-0.209545,0.173438,0.744131,-0.066388,-0.274198,-1.014733,-0.455011,0.416600,-0.089484,-0.596726,-0.092924,-0.198566,0.216153,-0.495484,0.837723,-0.280237,-0.188045,0.524178,0.420992,0.047898,-0.839875,0.033552,0.040448,0.650973,-0.243824,0.154438,-0.251470,0.135303,0.380265,0.090425,0.231917,-0.306892,-0.011565,0.344821,0.864177,0.046519,0.026063,-0.252676,0.408508,-0.337977,-0.025744,-0.154384,0.277359,0.373856,0.623852,0.494315,-0.288518,-0.368848,-0.050254,-0.157384,-0.841763,-0.156016,0.456399,0.018175,-0.836723,0.113223,-0.014273,0.126652,0.239007,-0.334225,0.579880,0.417032,0.113880,0.992220,-0.491896,0.135424,-0.330451,0.405788,0.550705,-0.275535,0.313781,0.528703,0.023134,-0.160314,-0.150536,-0.402002,-0.843693,0.366424,-0.037450,0.008534,-0.390535,0.469158,-0.072855,-0.483115,-0.106413,-0.123184,0.214401,-0.670746,-0.176017,-0.377400,-0.203925,-0.114578,-0.128177,-0.114377,0.140982,-0.441432,0.759069,-0.892505,0.606780,0.429822,0.260581,-0.608241,0.678620,0.095930,0.460994,-0.555051,-0.167389,0.091438,0.082784,-0.085832,-0.001423,0.028784,-0.343564,-0.080512,-0.440192,-0.039874', '30401849', '4847665', '30345227', '25890078');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26340301', '被操纵的城市', '动作', '《被操纵的城市》由演员池昌旭、 沈恩敬、吴正世、金相浩、金基天、安在洪、金民教等人出演，导演朴光贤则曾执导过2005年票房突破800万的电影《欢迎来到东莫村》。当天，首次在龙山进行拍摄的池昌旭表示：“紧张、激动，还有着期待。我怀揣着如此复杂的心情进行了拍摄。我确信这是一 部非常有趣的作品。我很期待日后的拍摄。”导演朴光贤则表示：“我写剧本中，脑海中浮现的角色与出演演员们完全一致。因此，我对该作品的期待很大。第一次拍摄的感觉非常棒。我会努力用心拍摄，力求呈现优秀的电影给大众。”《被操纵的城市》是一部犯罪动作电影，讲述了一男子被毫无理由地污蔑为杀人犯之后，与伪造的事件进行正面较量的故事。', '池昌旭', '朴光铉', 7.5, 35267, 'tt6399158', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2428791183.jpg', 1, 4.2, 32.1, 44.3, 18.5, '-0.138777,-0.222801,-0.612704,0.816788,0.416582,0.143953,0.501284,0.021129,-0.421546,-0.070604,0.299769,0.704430,-0.637825,0.105957,0.393052,-0.233933,-0.480327,-0.595127,-0.392413,0.114057,0.081951,-0.292504,-0.245574,-0.197296,-0.239575,-0.405484,0.630631,0.205947,-0.450236,0.339128,0.350777,0.087584,0.014360,0.354319,0.254115,-0.199416,-0.034993,-0.035655,-0.275665,0.379499,0.268518,-0.270022,-0.132811,0.309417,-0.033049,0.418093,0.845178,-0.088160,-0.464461,0.305246,0.595272,-0.388604,0.020389,-0.040604,-0.065195,0.424336,0.220619,0.294598,-0.153125,0.219012,-0.303631,-0.589328,-1.296012,0.000319,0.301249,0.137681,-0.552474,0.221026,-0.183989,0.076498,0.343566,-0.174835,0.085793,0.259451,0.764052,0.292853,0.023351,0.183464,-0.088733,0.663614,0.345732,0.044248,-0.095587,0.523576,-0.194820,-0.552060,-0.219925,-0.095236,-0.558154,0.407777,0.143430,-0.105860,-0.074449,-0.128059,-0.320809,-0.130316,0.081417,-0.444042,-0.083681,-0.514706,0.024582,-0.876427,-0.103679,-0.220065,-0.204390,-0.351301,0.016725,-0.451104,0.958336,-0.804308,0.070525,0.278258,0.290507,-0.463591,0.758068,0.281361,-0.434304,-0.255665,-0.087529,-0.030090,-0.229169,-0.029308,0.196592,0.309403,0.133360,-0.434866,-0.486997,0.523510', '3318306', '27602116', '6844861', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26340302', '请点赞', '喜剧', '《请点赞》围绕三对男女讲述了发生在社交网络和现实生活中的爱情故事。韩文中的“点赞”同时有“喜欢”之意。而片中的三段爱情故事都是由“点赞”这样一个简单的动作发展而来的。', '刘亚仁', '朴贤真', 6.5, 7051, 'tt5358570', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2306039647.jpg', 1.7, 11.3, 54.1, 24.7, 8.2, '0.780356,-0.348821,-0.565532,0.997706,0.179151,0.416432,0.869267,-0.078910,-0.278265,0.183120,0.421894,0.699789,-0.446009,0.012537,0.372627,-0.529850,-0.110461,-0.800506,-0.050845,-0.293018,-0.014075,-0.570717,-0.058671,-0.154636,-0.302899,-0.306304,0.383109,0.086368,-0.466609,0.371750,0.602858,0.154864,0.007411,0.307775,-0.073195,0.354744,-0.109326,0.291771,-0.011838,0.197675,-0.043212,-0.190630,0.234496,0.074965,-0.259934,0.373351,0.887077,-0.290704,0.101491,0.432202,0.789587,-0.229265,-0.004845,0.238446,0.243504,0.461813,0.615675,0.062795,0.119658,-0.090797,-0.149571,-0.114097,-1.177879,-0.202556,0.283998,0.430670,-0.293863,0.317176,0.084850,-0.344707,0.228079,-0.129593,0.398309,0.176724,0.974098,0.442846,0.030859,0.014515,0.062240,0.443583,0.483325,0.281450,-0.774943,0.600036,-0.442492,-0.357608,-0.360944,0.171703,-0.206324,-0.272278,0.081839,0.229777,0.018669,0.479547,-0.798939,0.385497,0.192556,-0.413295,0.161458,-0.820484,-0.463413,-0.753803,-0.254861,-0.918411,-0.021145,-0.056799,0.340173,-0.537369,1.181876,-0.923608,-0.148781,0.302126,0.020894,-0.517516,0.961692,0.479967,0.043882,0.150195,0.059028,-0.028124,-0.063971,-0.152819,-0.401866,0.631006,-0.117203,-0.186962,-0.674658,0.115345', '27602116', '2027945', '2053515', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26340305', '毕业会考', '剧情', '罗密欧（阿德里安·蒂蒂耶尼 Adrian Titieni 饰）和妻子玛格达（莉亚·巴格纳 Lia Bugnar 饰）结婚多年，两人共同养育着女儿艾丽莎（玛丽亚·维多利亚·德拉格斯 Maria-Victoria Dragus 饰），漫长的婚姻生活令罗密欧和玛格达都感到疲惫不堪，对妻子早已经没有感情的罗密欧唯一的指望，就是将艾丽莎送出国留学，希望她能够尽早离开这个陈腐不堪的国家。让罗密欧没有想到的是，艾丽莎竟然在会考前夕遭到了陌生男子的袭击，手臂受伤，导致她在之后的考试之中发挥不佳，为了不影响艾丽莎的前途，罗密欧不惜一意孤行贿赂官员买通阅卷老师，全然不顾妻子和女儿的感受，殊不知，这一连串的举动，令他坠入了万劫不复的深渊之中。©豆瓣', '阿德里安·蒂蒂耶尼', '克里斯蒂安·蒙吉', 7.7, 26255, 'tt4936450', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2352350523.jpg', 0.4, 2.1, 27, 53.7, 16.9, '0.340047,-0.061207,-0.998633,0.707685,0.049285,-0.343965,0.698978,-0.000102,-0.383302,-0.458448,0.127514,0.607661,-0.158763,0.175550,0.300465,0.026899,-0.206447,-0.822652,-0.249442,-0.055807,-0.523045,-0.639306,0.062894,-0.354665,-0.271026,-0.506408,0.598602,0.060609,-0.331005,0.508475,0.235364,0.418751,0.184400,0.405164,-0.018984,0.203747,0.361589,0.023883,-0.410600,0.457488,0.493087,0.028386,-0.045314,0.509110,-0.042996,0.295960,0.692997,-0.432349,0.194590,-0.028637,0.480270,-0.149941,0.093505,0.139534,0.064147,-0.200836,-0.051935,0.186163,-0.463305,0.044003,0.514393,-0.214210,-0.637387,0.071870,0.079584,0.109977,-0.548721,0.364699,-0.157455,-0.122678,0.424238,0.013936,0.249381,0.610126,0.226810,0.468581,0.121374,0.278016,-0.379343,0.121176,0.779576,-0.144155,-0.120865,0.337424,-0.576327,-0.398009,0.213045,-0.217331,-0.763855,0.073547,0.175366,0.203029,-0.097011,0.545706,-0.210887,-0.063179,-0.485276,0.053668,-0.011356,-0.351110,0.014182,-0.238195,-0.333042,-0.265324,-0.238553,0.155622,-0.098417,-0.265852,0.480513,-0.754541,0.399019,0.410470,0.636049,-0.314201,0.754903,0.256617,0.154770,-0.329895,-0.093888,0.349065,0.053273,-0.010139,0.353785,0.107282,0.186251,-0.099883,-0.226201,0.596401', '1292211', '1292338', '1298128', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26340419', '帕丁顿熊2', '喜剧', '露西婶婶（伊梅尔达·斯汤顿 Imelda Staunton 配音）的生日即将到来，帕丁顿（本·威士肖 Ben Whishaw 配音）决定送婶婶一份会让她终生难忘的礼物。最终，帕丁顿选中了一本立体绘本，然而这绘本是世间仅此一份的珍贵宝物，为了存钱购买绘本，帕丁顿决定开始工作，在遭遇了一连串的失败后，帕丁顿终于找到了适合他的工作——清洁玻璃窗。就在帕丁顿的存款即将达标之际，绘本竟然被一名神出鬼没的小偷给偷走了，同时出现在案发现场的帕丁顿被当做嫌疑犯捉拿归案，并最终被关进了监狱。在监狱里，帕丁顿凭借着自己的爱与勇气改变了墙内死气沉沉的氛围，监狱外，布朗一家人亦从来没有放弃过替帕丁顿洗清冤屈的机会。©豆瓣', '本·卫肖', '保罗·金', 8, 252593, 'tt4468740', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2506466229.jpg', 0.2, 1.4, 21.5, 50.1, 26.7, '0.127995,0.269445,-0.762387,0.639813,-0.149271,-0.429264,0.559388,0.091258,-0.366855,-0.254788,-0.049139,0.764771,0.101578,0.129213,0.249780,0.110122,-0.227974,-0.677611,-0.191484,-0.276382,-0.335376,-0.427179,-0.362718,-0.175594,-0.065151,-0.320704,0.477243,0.209362,-0.027409,0.142868,0.382144,0.048993,-0.111230,0.328480,-0.117461,0.004830,0.322269,0.003557,-0.309606,0.290771,0.032399,-0.192449,0.057567,0.430482,0.076811,0.235181,0.644373,-0.172921,-0.271884,-0.043713,0.544111,-0.098066,-0.009886,0.153064,0.048829,-0.042579,0.171100,0.207715,-0.409949,0.133675,0.420396,-0.167387,-0.831426,-0.256838,-0.019883,-0.135977,-0.620831,0.591690,0.066732,0.240344,0.069202,-0.429670,0.290111,0.169749,0.298099,0.329181,-0.174541,0.038361,-0.472387,0.324131,0.454940,-0.461710,-0.131482,0.404761,-0.131827,-0.364110,0.400868,-0.204465,-0.472622,0.198183,0.431498,0.244968,-0.301067,-0.020132,-0.480644,-0.318909,-0.430588,-0.309418,0.153566,-0.325567,-0.190879,-0.442191,-0.069511,0.138245,-0.278557,0.097631,0.016451,-0.277851,0.415315,-0.563437,0.423606,0.544822,0.054569,-0.427936,0.675001,0.088922,0.431494,0.194002,0.162125,-0.065245,0.272703,0.519957,0.208313,-0.029747,0.114991,-0.295182,-0.398695,0.541639', '25928048', '3119246', '34890458', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26340522', '咖啡公社', '剧情', '故事发生在二十世纪三十年代，懵懂青年鲍勃（杰西·艾森伯格 Jesse Eisenberg 饰）前往好莱坞投奔在那里混得风生水起的舅舅菲尔（史蒂夫·卡瑞尔 Steve Carell 饰），在菲尔的引荐下，鲍勃结识了名为瓦妮（克里斯汀·斯图尔特 Kristen Stewart 饰）的可爱姑娘。活泼健谈的瓦妮很快就令鲍勃坠入了爱河，遗憾的是，瓦妮告诉鲍勃自己已经有了男友。一日，伤心欲绝的瓦妮找到鲍勃，原来她的男友是一名有妇之夫，后者因为无法下定决心同妻子离婚而决定与其分手。鲍勃温柔耐心的陪伴失恋的瓦妮，随着时间的推移，两人慢慢走到了一起。让鲍勃没有想到的是，瓦妮的前男友竟然正是菲尔，当菲尔下定决心要娶瓦妮之时，瓦妮亦毫不犹豫的离开了鲍勃。之后，失意的鲍勃返回家乡，在哥哥本（寇瑞·斯托尔 Corey Stoll 饰）经营的俱乐部里当差，并在那里遇见了维罗妮卡（布蕾克·莱弗利 Blake Lively 饰），他们结婚生子，一切看起来都是那样的美好，直到有一天，瓦妮和菲尔再度出现在了鲍勃的身边。', '杰西·艾森伯格', '伍迪·艾伦', 7.2, 83433, 'tt4513674', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2365870567.jpg', 0.5, 3.7, 43.5, 41, 11.2, '0.249317,0.073991,-0.698633,0.336734,-0.240212,-0.688109,0.747559,0.151174,-0.281036,-0.227218,0.137053,0.715534,-0.216307,0.400013,0.617990,0.171262,-0.380900,-0.629670,0.144199,-0.361931,-0.091666,-0.848671,-0.277785,0.014312,-0.108604,-0.536270,0.368052,-0.112652,0.190940,0.465867,0.473449,0.324173,-0.096108,0.311289,-0.024293,0.147704,0.292780,-0.013572,-0.400413,0.241067,0.162045,0.029716,-0.096339,0.010834,0.163844,0.320373,0.316632,-0.124948,0.017397,0.121298,0.215389,-0.026928,0.079087,0.102044,0.231128,-0.173332,0.107835,0.083960,-0.402986,0.077120,0.175747,-0.027308,-0.327972,0.447521,-0.049561,0.220898,-0.654505,0.275142,-0.126295,-0.155480,0.185640,-0.377055,0.061279,0.454522,0.190920,0.237044,0.056622,0.231854,-0.362411,-0.056316,0.583311,0.348214,-0.226720,0.372040,0.051704,-0.160862,-0.041563,0.066906,-0.582251,0.044683,0.161542,0.133300,-0.096192,0.413236,-0.435674,-0.220171,-0.435729,-0.116401,0.094665,-0.202022,-0.185118,-0.494376,-0.171747,-0.322354,-0.331482,-0.011551,-0.158248,-0.288796,0.472612,-0.936516,0.463891,0.459391,0.327578,-0.326052,0.517110,0.120756,0.180965,-0.133472,0.105634,0.442992,0.026868,0.072742,0.137354,0.29978