INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26341137', '摩根', '科幻', '李（凯特·玛拉 Kate Mara 饰）是一名出色的企业问题分析解决专家，专门四处奔波，被陷入了困境的大企业出谋划策。某一日，她接受了一个极度机密的任务，被带到了一个无人知晓的神秘研究室，在那里，关着她需要解决的“问题”，然而，让李没有想到的是，这个人人谈之而色变的难题，竟然是一个叫摩根（安雅·泰勒·乔伊 Anya Taylor-Joy 饰）年轻女孩。摩根虽然看似普通，但实际上却是生物工程学所研究出的杰出作品，她没有父亲，没有母亲，是由单纯的DNA进化而来。摩根拥有着极为敏捷的行动，异常聪慧的头脑，相当惊人的生长速度，这一切让科学家们很快就感受到了强大的威胁。©豆瓣', '凯特·玛拉', '卢克·斯科特', 6.2, 8913, 'tt4520364', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2355765406.jpg', 2.9, 16.4, 53.5, 21.1, 6.1, '0.426107,0.193085,-0.771748,0.758720,-0.594036,-0.151628,1.023489,-0.059704,-0.655760,-0.807319,0.135648,0.536954,-0.072723,-0.022333,-0.030749,-0.135580,0.084193,-0.268917,-0.203145,-0.019678,-0.392035,-0.673857,-0.459541,-0.468162,-0.328834,-0.208429,0.620691,0.126222,-0.480029,0.112945,0.125258,0.550509,0.303854,0.555673,-0.408211,-0.219590,0.269222,0.086035,0.224628,0.279336,0.114870,-0.256477,-0.152640,0.518900,-0.130737,0.371757,0.389371,-0.281441,-0.350416,-0.003051,0.415271,-0.401398,-0.119577,0.021582,0.523780,-0.231609,-0.042198,-0.130959,-0.216243,-0.238236,0.126170,-0.120635,-1.356028,-0.067999,0.295290,0.375098,-0.764012,0.026744,-0.305354,-0.262089,-0.012307,-0.527937,0.072949,0.312340,0.287698,0.500941,0.139087,0.214869,-0.693393,0.067730,0.628474,0.068899,-0.669132,0.315331,-0.628208,-0.687184,-0.081911,-0.498597,-0.260217,0.107654,0.221244,0.149295,-0.035248,0.137373,-0.383701,0.040209,-0.274046,-0.418851,-0.105263,-0.475386,-0.175215,-0.583063,-0.090590,-0.466151,-0.623500,-0.004675,0.055930,-0.415595,1.148310,-1.036157,-0.148466,0.416937,0.031878,-0.658241,0.713522,-0.020049,0.075786,-0.315325,-0.066601,-0.027448,0.080074,0.208049,0.167442,0.602695,0.076778,-0.360215,-0.450673,0.541664', '1793491', '24284209', '25932086', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26341593', '某种女人', '剧情', '荒凉严峻的美国西北小镇，命运交织的平凡人生兀自翻涌著。因为劳工索赔被拒，心有不甘的男子愤而携枪挟持人质，迫使女律师不得不硬著头皮隻身涉险劝说；为了建造新家，一对夫妻努力说服当地老人家出售他囤积多年的沙岩，却也让他们的婚姻裂痕隐隐浮现；为了担任法律课程的讲师，年轻女律师千里迢迢地来到偏远小社区，意外与牧场女工逐渐亲密。', '劳拉·邓恩', '凯莉·莱卡特', 7.5, 7384, 'tt4468634', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2424471447.jpg', 0.9, 4.7, 30.5, 44.9, 18.9, '-0.028001,-0.026638,-0.379850,0.403380,0.018499,-0.289828,0.293916,0.241792,-0.447298,-0.217689,0.656392,0.891145,0.119816,0.305314,0.024839,-0.142393,-0.132568,-0.437982,-0.213747,-0.049452,-0.176693,-0.365982,0.078411,-0.587825,-0.323176,-0.215918,0.788438,0.299289,-0.015815,0.470003,0.102856,0.242083,-0.521999,0.085648,-0.168238,-0.462673,0.278016,0.137453,-0.423383,-0.284596,-0.207322,-0.162121,-0.241877,-0.093770,0.033839,0.727702,0.767929,0.144349,-0.274805,-0.177481,0.235270,-0.262985,0.058881,0.064277,0.073328,0.141792,0.260837,0.246353,-0.377582,-0.406520,0.066178,-0.175783,-0.291326,0.219603,0.290971,-0.225742,-0.474501,0.220012,0.030742,-0.220761,0.116366,-0.249867,-0.111718,0.302446,0.290178,0.329118,-0.029067,0.421875,0.038019,0.365170,0.659752,0.186601,-0.294751,-0.227088,-0.621036,-0.273275,0.281609,-0.273981,-0.670426,-0.312332,0.191025,-0.006750,-0.087518,0.213602,-0.533335,0.009563,-0.461954,0.186430,0.298052,-0.221358,-0.164880,-0.106877,-0.067086,0.026032,-0.018000,0.187753,0.277502,0.242662,0.253625,-0.486443,-0.042907,0.568007,0.495579,-0.504697,0.556371,0.225124,-0.002675,-0.343102,-0.295725,0.212593,-0.199033,0.450320,0.071148,-0.124324,-0.279079,0.100600,-0.293398,0.155203', '26881114', '1780122', '6719716', '1309194');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26341750', '陀地驱魔人', '剧情', '自幼拥有阴阳眼的黄永发（张家辉 饰）时常帮人驱魔除灵，童年的遭遇让他多年来始终和女鬼江雪（郭采洁 饰）相守度日，双方情同母子又有如情侣。在某次和哥们儿阿聪（张继聪 饰）驱魔时，阿发遭遇了一个身形高大的恶鬼。这次驱魔的视频上传网络，引起某媒体的关注，于是女记者紫宁（蔡思贝 饰）被派来采访阿发。虽然遭到阿发的拒绝，可是紫宁还是尝试各种方法见鬼，因此着实吃了不少的苦头。在此期间，江湖上接连有法师遭到杀害，阿发觉察到这一切都与此前遇到的恶鬼有关。他尝试着解开恶鬼伤人之谜，由此将自己和身边的人置于莫大的危险之中……©豆瓣', '张家辉', '张家辉', 6.5, 37553, 'tt5157030', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2366502708.jpg', 1.9, 12.9, 51.2, 26.1, 7.9, '0.382758,-0.142123,-0.571806,0.458560,0.028373,0.043705,0.636208,-0.042669,-0.694292,-0.148192,0.193735,0.635383,-0.453028,0.176911,0.080035,-0.246994,-0.041796,-0.660307,0.136380,-0.019315,-0.163274,-0.173911,-0.252052,0.092311,-0.236410,-0.235958,0.325519,-0.028535,-0.255119,0.473779,0.343966,0.323329,-0.256904,0.430202,-0.115583,0.180573,-0.075823,0.058442,-0.079465,0.138745,0.137048,-0.399630,-0.072636,0.238608,-0.131305,0.255495,0.494288,-0.267383,-0.277236,-0.052775,0.320489,-0.236078,0.078098,0.118697,0.313437,0.139767,0.324325,0.233189,-0.241321,0.054728,0.041476,0.125889,-0.669267,0.036135,0.295009,0.134539,-0.518108,0.217951,0.019066,0.148423,-0.081498,-0.167021,0.215039,0.237159,0.492495,0.075062,-0.005684,-0.095282,-0.352247,0.112426,0.724354,-0.044082,-0.076616,-0.027690,-0.137625,-0.267542,-0.010555,-0.200987,-0.204612,0.170105,0.347759,0.136529,-0.361610,0.275439,-0.725984,0.133017,-0.136676,0.029554,0.000574,-0.189392,-0.057766,-0.931520,-0.144555,-0.526152,-0.393303,0.107548,0.194621,-0.327999,0.799763,-0.680341,0.310461,0.373839,0.320626,-0.429463,0.684116,0.041702,0.053648,-0.009044,-0.218827,0.136370,0.254511,0.340630,0.303072,0.115670,-0.022251,-0.082316,-0.193321,0.124196', '19965431', '3147969', '3318306', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26342391', '紧急救援', '动作', '倾覆沉没的钻井平台，顺流直冲的运油车头，直坠入海的满载客机。交通海上应急反应特勤队队长高谦（彭于晏 饰）、机长方宇凌（辛芷蕾 饰）和绞车手赵呈（王彦霖 饰）一次次带领队伍第一时间抵达，站在水火咆哮的最前面，守在危急撤离的最后面，用生命对抗天灾人祸。但在自然面前，特勤员毕竟没有超能力，血肉之躯踩在死亡边缘，真实的恐惧无数次让这些斗士颤抖、无助和气馁。而海上救援的字典里没有“退缩”。当你听见旋翼的轰鸣、洪亮的汽笛、马达的飞驰，那是他们无惧艰难险阻，舍己为人，谱写的一曲英雄之歌。', '彭于晏', '林超贤', 5.9, 116814, 'tt9283920', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2627025706.jpg', 3.6, 21.5, 54.1, 16.8, 4, '0.134374,-0.004494,-1.060166,0.576427,0.298745,0.017110,1.106326,0.059161,-0.002854,-0.104794,0.596559,0.381489,0.149475,-0.202992,0.072624,-0.376491,-0.018042,-0.716966,-0.258295,0.313182,-0.544504,-0.320233,-0.001024,-0.011342,-0.128417,-0.090523,0.792817,0.262331,-0.206474,0.857741,0.312611,0.122029,-0.183772,0.649775,-0.424098,-0.167096,-0.087968,-0.048060,0.016393,-0.044740,-0.234292,-0.306317,0.119069,0.023423,-0.026185,0.314572,0.566788,-0.341729,0.320047,0.219620,0.090616,-0.402151,0.184706,-0.093513,0.218282,-0.029845,-0.348100,-0.171574,-0.015078,0.029456,-0.052010,0.243383,-0.777147,-0.306441,-0.285137,0.137041,-0.745582,0.011436,-0.097942,0.003765,0.138686,-0.046420,0.564784,0.071441,-0.006527,0.437068,-0.371810,0.195249,-0.496398,0.024043,0.649116,-0.049324,-0.340277,0.081194,-0.087228,-0.563561,-0.279546,-0.255013,-0.526923,-0.426014,0.119947,0.123874,0.047949,-0.115567,-0.333488,0.364451,-0.017556,-0.356579,-0.302441,-0.190812,-0.376635,-0.504268,0.286067,-0.419347,0.159356,0.471854,-0.150756,0.056243,0.454470,-0.414704,0.171156,0.312728,0.106748,0.102935,0.700003,0.310478,-0.167877,-0.051514,0.278930,0.322157,-0.044540,0.695664,0.123042,0.129457,-0.173271,0.252716,-0.404961,0.241066', '21619567', '3011051', '25986180', '4312232');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26345159', '半熟少女', '剧情', '半熟，是对青春期最合理的定义，它是梦开始的地方，没有深思熟虑，只有最单纯的坚定，然而，在这个充满意外的年纪，未来似乎变得很具体，又有着无限的可能性。这个故事里有女汉子与呆萌校草的啼笑初恋，有四朵姐妹花的袍泽之谊，也有学霸乖乖女与双胞胎才子的意乱情迷，他们躁动的热情在循规蹈矩的理智中突围，写成一首欢笑与痛，梦想与爱的青春禁曲。也许，半熟与成熟之间，只差那次铤而走险的“叛逆”。', '黄灿灿', '阿牛', 3.3, 3038, 'tt5483634', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2326378603.jpg', 59.8, 24.1, 9.8, 2.7, 3.6, '0.320905,-0.128652,-0.730172,0.712719,-0.137990,0.045833,1.216483,-0.043536,-0.467778,-0.224057,-0.045938,0.643316,-0.217365,0.284300,0.167888,-0.124758,-0.098251,-0.651779,-0.082291,-0.108937,0.055414,-0.638153,-0.250268,0.096170,-0.246801,-0.318537,0.993153,0.165937,-0.329559,0.505678,0.354291,0.230985,0.145222,0.500242,-0.365004,-0.041590,-0.088737,0.296846,-0.198762,-0.026257,0.154811,-0.047509,-0.105575,0.137333,-0.281269,0.532817,0.599723,-0.440918,-0.486122,0.158612,0.496340,-0.177589,-0.513006,0.185147,0.250758,-0.221675,0.273428,-0.092329,-0.016248,-0.186614,-0.169947,-0.146610,-0.932144,-0.152808,0.487441,0.252914,-0.437439,0.495261,0.315562,-0.244031,0.555525,-0.097784,0.180036,0.230673,0.417248,0.481312,-0.136111,0.020491,-0.435126,0.095780,0.780510,0.304224,-0.577986,0.725806,-0.576895,-0.717746,-0.008952,-0.325564,-0.482422,0.153524,0.006041,0.249046,-0.302687,0.315271,-0.661715,0.295143,0.288648,0.058308,0.143449,-0.745553,-0.312937,-0.147261,-0.450189,-0.920262,-0.420984,-0.050192,0.150775,-0.386336,1.050278,-1.179479,0.118272,0.359837,-0.003386,-0.492500,0.767500,0.435767,-0.169288,-0.419545,-0.165115,0.439897,-0.456897,-0.113343,-0.102358,0.338300,-0.280119,0.084101,-0.705912,0.535712', '26354526', '2053515', '26283288', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26345736', '女汉子真爱公式', '喜剧', '悉尼大学数学统计专业女学霸何修舞（赵丽颖 饰）在硕士论文中推导出了“真爱公式”，坚信自己公式绝对无误的何修舞，却接到了自己第一个实验对象失败自杀的噩耗……为了早点送走可怕的学霸女，叶思逸（张翰 饰）决定亲自帮助她寻觅她的真命天子，只是这个过程中，到底是哪里变的不对了，竟然有了奇怪的化学反应……©豆瓣', '赵丽颖', '郭大雷', 5.6, 26648, 'tt4903518', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2324372895.jpg', 20.3, 24.3, 27.7, 10, 17.7, '0.166192,0.156556,-0.638212,0.567013,-0.380827,-0.132635,0.267266,-0.262002,-0.387811,-0.390515,0.182842,0.514059,-0.195845,0.008766,-0.032018,0.079663,-0.291816,-0.544364,0.086102,-0.332017,-0.623192,-0.510777,-0.400742,-0.184892,0.088255,-0.164116,0.451092,0.177967,-0.307725,0.056792,0.352402,0.417364,0.231483,0.434584,-0.202897,0.080924,0.134394,0.311717,0.077833,0.185634,0.373163,-0.178078,-0.163718,0.420414,-0.075555,0.446539,0.361389,-0.297553,-0.282075,0.000311,0.491441,-0.340666,-0.199669,0.146627,0.088493,-0.112429,0.209300,0.131898,-0.160871,0.063195,-0.141536,-0.026224,-0.927625,-0.256533,0.384522,0.114850,-0.441599,0.096812,-0.260954,-0.195436,0.122347,-0.166942,0.092337,0.249448,0.567825,0.511375,-0.186381,-0.117660,-0.258337,0.393095,0.309117,0.026003,-0.321644,0.359473,-0.248290,-0.643028,0.076045,-0.083957,-0.044318,0.246134,0.113101,0.325934,-0.200565,-0.122499,-0.242511,-0.060328,-0.085143,0.090937,-0.075922,-0.528527,-0.218115,-0.136545,0.159501,-0.048681,-0.389448,-0.159574,0.001886,-0.364660,0.762865,-0.771079,0.108694,0.463216,0.003176,-0.686531,0.361269,0.240064,-0.285233,-0.442428,0.089297,-0.191527,-0.052341,0.305051,-0.093224,0.448921,0.499346,-0.505765,-0.535502,0.623049', '27602116', '30163500', '24284209', '6844861');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26346327', '养家之人', '剧情', '塔利班残酷统治下的阿富汗，平民百姓尤其是女性过着水深火热犹如地狱一般的生活。倔强的小女孩帕瓦娜（莎拉·乔德利 Saara Chaudry 配音）随父亲（Ali Rizvi Badshah 配音）外出挣钱养家，不仅目睹了父亲被昔日的学生辱骂羞辱，更和家人目击了父亲遭到非法逮捕的一幕。家中有病弱的母亲、成年的姐姐以及嗷嗷待哺的弟弟，年幼的帕瓦娜只能剪去秀发，伪装成男孩走出家门，踏上生死未卜的养家之路。在此过程中，她遇到了同样扮成男孩的昔日伙伴，也与一名沉默魁梧的塔利班分子成为朋友。当战争的阴影再度逼近时，帕瓦娜想方设法要找到下落不明的父亲，将他带回家中……本片根据黛博拉·艾里斯的同名小说改编。©豆瓣', '莎拉·乔德利', '诺拉·托梅', 8.3, 126795, 'tt3901826', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2544510784.jpg', 0.1, 1, 14, 51.8, 33.1, '0.211027,-0.203754,-0.499856,0.541726,-0.251967,-0.563342,0.799845,0.149814,-0.469340,-0.253967,0.265323,0.683825,0.146417,0.413269,0.415413,-0.072407,-0.314059,-0.658931,-0.436490,0.022969,-0.236824,-0.309817,-0.262768,-0.025884,-0.108478,-0.480419,0.793239,-0.063570,-0.182997,0.474231,0.216205,0.525833,-0.361838,0.210484,-0.431105,0.023346,0.011150,0.071007,-0.417483,0.137117,-0.017648,-0.141895,-0.108000,-0.041259,-0.109181,0.258395,0.836589,-0.236457,0.004405,-0.414392,0.497221,-0.260768,0.088149,0.160552,0.355988,0.137097,0.292360,0.172183,-0.077432,0.003581,-0.022557,-0.309599,-0.541711,0.005292,0.305691,-0.014585,-0.751050,0.159733,0.083318,0.076253,0.385066,-0.213624,0.230307,0.323283,0.082734,0.558902,-0.244977,0.105929,-0.594085,0.377432,0.598892,0.022623,-0.258569,0.040850,-0.245719,-0.371839,0.399615,-0.443874,-0.579703,0.110161,0.302650,-0.151402,-0.432862,0.514643,-0.390570,-0.140631,-0.398721,-0.097454,0.000350,-0.303003,-0.270390,-0.567183,-0.085058,-0.281678,-0.138378,0.236647,0.063572,-0.305705,0.730180,-0.713425,0.393114,0.456595,0.456065,-0.515764,0.603360,0.067812,0.430220,0.042629,-0.173794,0.527807,0.381102,0.114715,-0.106730,-0.069659,-0.229334,-0.019463,-0.331031,0.373529', '21619567', '3811356', '1417036', '6974439');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26347316', '不速之客', '悬疑', '下属的一个失误令身为上司的郑凯（黎明 饰）事业陷入困境停滞不前，不仅如此，他还得承担下属造成的巨额损失。郁闷至极的郑凯只能借酒消愁，在酩酊大醉之际，一位陌生的黑车司机（耿乐 饰）将郑凯送回了家并且留下了电话，此时的郑凯并不知道，这名神秘的男子，将彻底改变他的一声。黑车司机反常的态度和疯狂的举动令郑凯感到不寒而栗，他并不记得自己和此人说了什么，那一夜两人又经历了什么。没过多久，一直为难郑凯的上司突然惨死，而郑凯则成为了警方重点怀疑的对象，只有郑凯知道，这一切和黑车司机有着脱不清的干系，而随着时间的推移，黑车司机已经在不知不觉中来到了他的身边。©豆瓣', '黎明', '林大雄', 4.6, 3046, 'tt5955834', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2327603714.jpg', 23.2, 38.2, 29.3, 6.1, 3.2, '0.333003,0.190660,-0.732143,0.631262,-0.090605,-0.418179,0.899616,0.087690,-0.758867,-0.419237,0.274221,0.763617,-0.163214,0.238611,0.554853,-0.136378,-0.165836,-0.680263,-0.249916,-0.084778,-0.350007,-0.499275,-0.036962,-0.219238,-0.111234,-0.053477,0.303516,0.110433,-0.171320,0.613028,0.389434,0.145961,0.014474,0.882628,-0.130401,0.265487,0.019268,-0.226572,0.033473,-0.113753,0.269219,-0.456039,0.014478,0.373232,-0.052261,0.450046,0.403387,-0.204479,-0.631222,-0.030777,0.405312,-0.465284,-0.000502,-0.103985,0.319642,0.131892,0.211863,0.041490,-0.266809,-0.039939,0.250233,0.323662,-0.942877,0.172296,-0.316046,0.170967,-0.657305,0.543851,-0.233717,-0.183956,0.174033,-0.331086,0.438008,0.324316,0.095952,0.514904,-0.260948,-0.112185,-0.467806,-0.008967,0.787192,0.156783,-0.073849,0.540672,-0.171943,-0.343923,-0.275462,0.081580,-0.460000,0.000372,0.287932,0.186595,-0.054842,0.048351,-0.235867,-0.089903,0.011218,-0.261769,-0.324067,-0.495478,-0.166803,-0.241404,-0.184099,-0.497725,-0.422301,0.118907,-0.103847,-0.010793,0.467903,-0.803153,0.063755,0.484891,0.344200,-0.477096,0.448968,0.194094,0.185199,-0.097551,-0.347595,0.141374,0.039101,0.435063,0.265350,0.244766,-0.046155,-0.213365,-0.132488,0.247255', '1304977', '1301022', '1308755', '10546747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26348103', '小妇人', '剧情', '马奇夫人（劳拉·邓恩 Laura Dern 饰）有着四个如花似玉的女儿，大女儿梅格（艾玛·沃森 Emma Watson 饰）拥 有着美丽的外表，和对于爱情的天真憧憬。二女儿乔（西尔莎·罗南 Saoirse Ronan 饰）满脑子塞着古灵精怪的念头，整天拿着蘸水笔东写西写，她的故事在全家上下都受到了热烈的欢迎。三女儿艾米（佛罗伦斯·珀 Florence Pugh 饰）渴望成为一名画家。最小的女儿贝斯（伊莱扎·斯坎伦 Eliza Scanlen 饰）虽然个性比起三个姐姐要来的内向的多，却拥有杰出的音乐天赋。在马奇夫人的教导之下，四个姑娘渐渐成长为了拥有独立人格的杰出女性，她们热情、乐观、善良，每个人都在各自的道路上坚强而又坚定的前进着。©豆瓣', '西尔莎·罗南', '格蕾塔·葛韦格', 8, 428651, 'tt3281548', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2572813215.jpg', 0.3, 2.4, 21.5, 49.7, 26.1, '0.036772,0.115923,-0.537651,0.794351,-0.382866,-0.264371,0.758549,0.277143,-0.438713,-0.187650,0.216442,0.649436,-0.049603,0.449501,0.082030,0.059321,-0.084496,-0.411584,-0.070082,-0.047836,-0.009749,-0.543473,-0.114480,-0.329567,0.007899,-0.551706,0.297219,-0.310240,-0.003933,0.354177,0.475989,0.193444,-0.073465,-0.152116,-0.158003,-0.062568,0.034654,-0.030397,-0.137016,-0.036963,-0.148203,0.344895,-0.108351,0.049798,0.071222,0.229292,0.683828,-0.480945,0.181967,0.022947,0.418335,0.026577,-0.077191,0.186212,0.142102,-0.010146,0.166627,-0.068079,-0.056377,-0.083764,0.204281,-0.329769,-0.798028,-0.004745,0.523355,0.223630,-0.724924,0.470751,-0.015556,-0.241855,0.239092,-0.382961,-0.309429,0.054086,-0.041279,0.620565,0.038455,0.232823,-0.241187,-0.134846,0.426289,0.191744,-0.392980,0.190076,-0.678820,-0.265358,0.014730,-0.516467,-1.054550,-0.039256,0.341724,-0.099135,0.267270,0.434775,-0.509021,0.203001,-0.143575,0.027947,0.257476,-0.522738,-0.021020,-0.338275,0.017167,-0.745258,-0.386389,0.118108,0.002746,-0.208523,1.485813,-0.637196,0.273128,0.246971,0.101066,-0.533324,0.581250,0.168236,-0.004057,-0.186974,-0.327051,0.598960,0.030785,-0.259632,-0.090391,0.486455,-0.482708,0.082981,-0.432720,0.534280', '24284209', '27602116', '25882279', '1303010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26348218', '同班同学', '剧情', '林婉静（郭奕芯 饰）是老师和同学眼中的乖乖女，然而只有她自己知道，平日里的温和和顺从不过只是表象，她一直带着沉重的假面生活，深感压抑。苏可怡（麦芷谊 饰）向来我行我素，如同花蝴蝶一般辗转在荷尔蒙气息强烈的帅气男孩之间，是典型的问题学生。陈爱爱（廖子妤 饰）天生内向而羞涩，总是成为众人欺负和排挤的对象。一场意外让三个性格迥异的女孩走到了一起，结下了脆弱但纯真的友谊，然而，陈爱爱援交的消息令这友谊最终四分五裂，三人分道扬镳。之后，三人各自面对苍白而又惨淡的人生，以她们特有的方式与之对抗，当三人再度相聚在一起结成同盟之时，却发现，她们早已经回不到过去。©豆瓣', '郭奕芯', '陆以心', 4.9, 8657, 'tt5097504', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2294958176.jpg', 17.6, 35.3, 34.2, 8.7, 4.2, '0.482470,-0.006255,-0.775922,0.624263,-0.083667,-0.198440,0.985735,0.335433,-0.646509,-0.138205,-0.068648,0.691609,-0.247799,0.381548,0.261656,-0.190359,-0.048117,-0.825527,-0.328770,-0.323139,-0.085193,-0.405127,-0.007523,0.007998,-0.208728,-0.322315,0.737962,0.008310,-0.068199,1.015883,0.456729,0.223529,-0.418933,0.689310,-0.061253,-0.395475,-0.164970,0.213910,-0.289599,-0.119251,0.226130,-0.016439,-0.312805,0.247818,-0.253761,0.536576,0.577572,-0.250672,-0.327351,0.002101,0.161952,-0.085504,-0.213851,0.386079,0.147265,-0.010017,0.641535,0.051602,0.036667,0.119970,0.161967,0.032436,-0.357470,0.324616,0.195395,0.142450,-0.420811,0.706950,0.282581,-0.282133,0.272271,-0.322246,0.154281,0.206719,0.360457,0.555943,-0.254671,0.121230,-0.314908,-0.180894,0.792018,0.267136,-0.569537,0.552518,-0.348392,-0.275612,-0.040541,-0.526749,-0.493174,-0.035111,-0.053998,0.290235,0.002382,0.304937,-0.953201,-0.005535,-0.013791,0.332620,-0.011695,-0.726004,0.096072,-0.556873,-0.500233,-0.798897,-0.558750,0.360850,0.014668,-0.280577,0.776222,-1.121918,0.190456,0.291961,0.200205,-0.472565,0.507729,0.116915,-0.006982,-0.111078,-0.011503,0.191792,0.041270,0.117564,0.165436,0.460421,-0.295724,0.187535,-0.401380,0.395612', '35030151', '25962735', '1292219', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26348414', '追捕', '剧情', '国际律师杜丘（张涵予 饰）清晨醒来，发现一个陌生女子被杀死在枕边，当所有证据皆指向自己就是凶手时，他拒捕逃离，决定自己查出真相。颇有名气的警探矢村（福山雅治 饰）在追捕过程中，察觉案件并不简单。一警一“匪”在交手中竟发展出了一段惺惺相惜的情谊，探明真相的过程中，他们卷入了更大的阴谋，而屡次帮杜丘逃亡的神秘女子真由美（戚薇 饰）也另有隐情……', '张涵予', '吴宇森', 4.5, 31615, 'tt4537986', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2496360864.jpg', 21.4, 42.9, 29.1, 5, 1.6, '0.124569,0.127368,-0.783318,0.186490,-0.045905,0.342267,0.868241,-0.280791,-0.634571,-0.473843,0.381318,0.559939,-0.129295,-0.031624,0.349557,0.056554,-0.148543,-0.822025,-0.001093,-0.371632,-0.221418,-0.732672,-0.462208,-0.221104,0.087155,-0.220355,0.516961,0.446083,-0.508472,0.220941,0.305774,0.003864,-0.633606,0.627713,0.041000,-0.066074,0.208192,0.069273,-0.250604,0.110612,-0.174758,-0.611344,-0.363383,0.211870,-0.348087,0.673871,0.551133,-0.206828,-0.330095,0.107975,0.298834,-0.443789,-0.242267,0.060653,0.369748,0.011978,0.119783,0.541848,-0.224063,-0.016667,-0.030812,0.095904,-0.711166,0.219711,0.247684,0.537535,-0.204854,0.104104,-0.147990,0.005533,0.001777,-0.256303,0.163527,0.265019,0.499637,-0.031402,-0.169272,-0.008787,-0.741736,0.129215,0.615555,-0.003176,0.003009,0.264330,0.063006,-0.420068,-0.138950,0.064516,-0.033025,-0.014875,0.673660,0.063657,-0.368292,0.432169,-0.286878,-0.158366,-0.370126,0.250409,-0.301864,-0.310179,-0.092206,-0.266763,-0.168601,-0.217324,-0.498682,0.153430,0.254956,-0.414599,0.445976,-0.695797,0.104126,0.569665,0.082988,-0.376969,0.301474,0.227738,0.149948,-0.285153,-0.213309,0.307564,0.285534,0.041954,-0.078191,0.342621,-0.207246,-0.420827,-0.499511,-0.113078', '1947080', '35073886', '3263169', '26775933');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26348798', '真相禁区', '悬疑', '费鑫（任达华 饰）和仇乐（霍建华 饰）接下一件案子……区鉴（张赫 饰）的妻子南方（热依扎 饰）生下本不该属于他的孩子，笃定被戴绿帽的他本想查清孩子来路，却遭杀手索命，惶惶度日发现一切都是妻子和奸夫的阴谋。蒙冤入狱5年的谢天佑（霍建华 饰）开始了对区鉴的报复行动，决定利用高智商犯罪夺回本该属于自己的一切。在费鑫查到区鉴与新进职员唐蝉关系微妙同时，南方发现一直为自己鸣不平的好友沈嘉美竟是区鉴前妻。与杀手的对抗，与妻子的周旋，与女职员的邂逅，与前妻的重逢，区鉴深陷危机。每个人的爱里都隐藏着不为人知的秘密……©豆瓣', '任达华', '麦咏麟', 4.5, 7139, 'tt4828680', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2312467173.jpg', 30.1, 32.3, 25.2, 6.9, 5.5, '0.291455,-0.218430,-0.627048,0.534293,-0.211759,-0.153117,0.696262,0.161983,-0.664986,-0.483029,0.274253,0.367129,-0.135644,0.067376,0.268688,-0.070384,0.028720,-0.925408,-0.072209,-0.065982,-0.154758,-0.519921,-0.420151,-0.266688,0.013702,-0.213192,0.588952,0.236574,-0.213455,0.295773,0.473413,0.431252,-0.481827,0.473120,-0.018534,-0.034555,-0.074483,0.186514,-0.588782,-0.006147,0.048457,-0.286536,-0.111882,0.235950,-0.086130,0.471805,0.639474,-0.394540,-0.210244,-0.110670,0.301816,-0.330132,-0.058834,0.204553,0.213552,0.067764,0.111930,0.523625,-0.310180,-0.136934,0.232353,-0.026601,-0.652348,-0.034906,0.393650,0.153855,-0.545778,0.309730,-0.112510,0.095039,0.036914,-0.209030,0.335318,0.275417,0.208304,0.413967,-0.146100,-0.005464,-0.549230,0.323576,0.672761,0.079505,0.236429,-0.033861,0.017655,-0.294474,-0.228746,-0.041828,-0.510182,0.031832,0.255801,0.006993,-0.043851,0.410737,-0.536442,-0.217506,-0.227207,0.197887,0.100646,-0.706026,0.137017,-0.183089,-0.295663,-0.244557,-0.272390,0.233796,0.224859,-0.381596,0.405984,-0.962920,0.127283,0.342217,0.343953,-0.752232,0.498967,0.190958,0.075790,-0.597559,-0.262545,0.150236,0.129730,-0.093014,0.065005,-0.019681,-0.109986,0.070735,-0.218120,0.142587', '1301022', '30345227', '1293265', '1949320');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26348846', '罗宾汉：起源', '动作', '用现代思维重新书写绿林英雄罗宾汉的传奇故事。原本富庶的贵族罗宾为家国大义奔赴战场，见识过战争的残酷与惨烈后回到故乡，不想等待他的竟是心爱的女人被抢走，家产被侵占的噩耗。在逃避现实之时，罗宾曾在战场上救助的神秘男子突然出现，带领他学习无敌箭术，罗宾一边受训一边调查摧毁自己人生的元凶，线索逐渐汇集到诺丁汉郡长身上。于是，那个西方最著名的传奇英雄—罗宾汉就此诞生，用最淋漓的身手，最出神入化的箭术去讨回人间的正义!', '塔伦·埃哲顿', '奥图·巴瑟赫斯特', 5.2, 10364, 'tt4532826', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2578485060.jpg', 8.4, 35.9, 46.4, 7.9, 1.5, '0.135677,0.072432,-0.583291,0.665897,-0.167468,-0.271480,0.607578,-0.185337,-0.294085,-0.323586,0.558024,0.866446,0.149832,0.223192,0.538557,-0.133786,-0.224344,-0.879703,-0.062526,-0.209743,-0.290335,-0.305934,-0.515157,0.010936,-0.075735,-0.318248,0.735048,0.060202,-0.525527,0.281506,0.123561,0.212092,-0.183520,0.354347,-0.709991,-0.205404,-0.123268,0.106919,-0.369744,0.023463,-0.138267,-0.363867,-0.163037,0.233025,-0.426763,-0.067192,0.686777,-0.627077,0.282711,-0.340149,0.439962,-0.301376,-0.199168,0.038143,0.234882,-0.048486,0.098726,0.095927,0.141266,-0.143142,-0.131179,-0.154043,-1.010865,-0.257451,-0.043148,0.068808,-0.507339,0.190860,-0.073838,-0.103214,0.275315,-0.326022,0.349617,0.186078,0.271783,0.280271,-0.059435,0.004697,-0.207367,0.383588,0.666561,-0.080152,-0.055555,0.160809,0.104525,-0.448869,0.199700,-0.713800,-0.371263,-0.168220,0.180357,-0.019817,0.042775,0.592327,-0.813145,0.046943,-0.217086,-0.152547,0.205194,-0.091776,-0.405568,-0.387799,-0.347437,-0.287945,-0.094266,0.115882,0.015271,-0.208459,1.004654,-0.659738,0.114966,0.419607,0.012336,-0.475904,0.447506,0.092377,0.276238,-0.087930,-0.244160,0.763634,0.347696,0.608873,-0.199471,0.202780,-0.258828,-0.042442,-0.535238,0.817084', '27602116', '25928048', '26667010', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26349397', '蛇之拥抱', '剧情', '1909年，一个德国探险家在亚马逊丛林中罹患怪病，求助于族人几乎被屠戮殆尽的巫医，他们沿河蜿蜒而上，试图寻找失散的族人和能治病的神秘植物；1941年，一位美国探险家也踏上雨林土地，偕一位当地老者回溯足迹，雨林中沉睡的记忆逐渐被唤醒，过往留下的疯狂与灾难亦如热带植物般滋长，蔓生成更扭曲的疮疤......根据人物原型在亚马逊流域探险日记而写成的《蛇之拥抱》，是年轻哥伦比亚导演希罗·盖拉写给南美大陆的黑白影像诗，获得戛纳电影节导演双周单元大奖，更代表哥伦比亚角逐奥斯卡最佳外语片。©豆瓣', '扬·贝弗特', '西罗·格拉', 7.9, 6737, 'tt4285496', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2321627914.jpg', 0.9, 3.1, 23, 46.5, 26.5, '-0.032622,-0.180982,-0.392757,0.773742,0.443419,-0.146301,0.615828,-0.245109,-0.415623,-0.003337,0.115500,0.826983,-0.181588,0.067592,0.250705,-0.132772,-0.215347,-0.461058,-0.077282,-0.020810,-0.259426,-0.075806,-0.560327,0.042147,0.019716,-0.621123,0.931548,0.056428,-0.232887,0.702958,0.047449,0.419843,-0.421454,-0.003307,-0.331469,-0.105114,0.190481,0.038704,-0.433907,0.279992,-0.431360,-0.341128,-0.085849,-0.052589,-0.371682,0.201769,0.845558,-0.234685,0.278122,-0.332592,0.329683,-0.431181,0.046223,-0.093883,0.432866,-0.049706,0.374235,0.353163,-0.019549,-0.048068,-0.063642,-0.252300,-0.508922,-0.023515,0.222403,0.688951,-0.225871,0.088479,0.244722,0.159564,-0.134523,-0.289279,0.152609,0.066217,0.276431,0.208091,-0.049235,-0.126929,-0.427111,0.429493,0.369753,-0.230657,-0.434451,0.210139,-0.293603,-0.540744,0.134920,-0.190401,-0.310817,0.053029,0.313152,-0.021127,-0.147834,0.524858,-0.911547,0.079386,-0.175292,-0.578598,-0.009765,-0.054420,-0.243630,-0.721186,-0.266871,0.039321,0.114768,-0.113153,0.248991,-0.199851,0.729718,-0.204555,0.473825,0.380214,0.226371,-0.321050,0.635491,-0.111588,-0.041237,-0.204371,-0.032449,0.680525,0.172685,0.212005,-0.226659,0.042387,-0.195230,0.062208,-0.470859,0.478247', '26290398', '1780122', '24879819', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26350706', '第十二个人', '剧情', '本片根据真实故事改编,第二次大战期间，12名挪威破坏小分队潜入了德国在挪威境内的驻扎港，实施代号为“红色马丁”的破坏计划，11人被捕，第12人得以逃脱，并将秘密文件带回英国……', '乔纳森·莱斯·梅耶斯', '哈罗德·兹瓦特', 8, 13501, 'tt3300980', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2512022748.jpg', 0.4, 1.8, 21.1, 51.5, 25.2, '-0.161043,0.282267,-0.780446,0.689191,0.340276,0.185857,0.035490,-0.306227,-0.713451,-0.097653,0.025686,0.444089,0.207228,-0.503988,0.653248,0.122737,-0.681407,-0.495729,-0.191126,-0.254720,-0.304914,-0.428313,-0.525896,-0.376596,0.413656,-0.715079,0.734853,0.629307,-0.673049,0.240951,0.128950,0.332157,-0.746453,0.341798,0.252281,-0.042376,0.119371,-0.394245,-0.559661,0.493783,-0.756866,-0.353739,0.077245,-0.289161,0.131640,0.692867,1.072982,-0.632360,-0.051951,-0.403208,0.261941,-0.546344,-0.455245,-0.344605,0.238781,0.188196,0.085071,0.778098,-0.316877,0.207154,-0.343372,-0.362312,-0.631628,-0.058720,0.246745,0.037352,-0.322534,0.243943,-0.453484,0.716947,0.135053,-0.107463,0.223433,0.790122,0.417223,0.049872,0.279546,0.238195,-0.482588,0.339024,0.783009,-0.590533,-0.125265,-0.418615,0.186364,-0.212328,0.112699,-0.361046,0.420738,0.250633,0.125133,-0.037283,0.002094,0.168549,-0.806841,-0.372474,-0.674295,-0.548540,0.223836,-0.351452,0.028591,-1.116109,0.132488,0.652327,-0.032494,0.262460,-0.142122,-0.201593,0.384326,-0.489613,0.484467,0.742276,0.458449,-0.433281,0.151566,0.387404,0.248077,-0.688714,-0.184256,0.803457,0.461248,0.372746,-0.136088,-0.048696,-0.269413,-0.572117,-0.426239,-0.006826', '1306809', '3871833', '2369613', '1303447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26351171', '白昼之雨', '惊悚', '冈田进（滨田岳 饰）和安藤勇次（室毅 饰）是东京一家清洁公司的小员工。与毫不自信的阿进不同，安藤哥的感觉似乎格外良好，这一切源于他对爱情的自信。安藤喜欢上了某咖啡馆的服务生阿部由香（佐津川爱美 饰），他要求冈田为其出谋划策。与此同时，他们发现由香似乎被某个男人盯上了。阿进注意到，那名跟踪者是自己的老同学森田正一（森田刚 饰），有着黑暗历史的森田周身散发着黑暗的死亡气息。令阿进意想不到的是，由香居然对他格外中意，两人于是陷入热恋。当阿进发愁如何向安藤哥讲明情况时，双手沾满鲜血的森田则悄然向他们逼近……本片根据古谷实的同名漫画改编。©豆瓣', '森田刚', '吉田惠辅', 7, 7431, 'tt4949100', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2354794567.jpg', 1.2, 5.8, 43.7, 39.6, 9.7, '0.316284,0.029438,-0.710021,0.491919,-0.162440,-0.142195,0.893275,0.302481,-0.520877,-0.448186,0.360603,0.717284,-0.316536,0.145818,0.332266,0.192490,-0.116195,-0.681337,-0.395928,-0.051117,-0.272976,-0.244370,-0.414145,-0.016580,-0.275664,-0.204513,0.539236,0.197287,-0.468214,0.458202,0.373071,0.593004,-0.192176,0.527250,0.042400,-0.033816,-0.093755,-0.200594,-0.069485,-0.074777,-0.086757,-0.183301,-0.221876,0.100201,-0.111086,0.357373,0.684139,-0.116991,-0.373357,-0.201420,0.532047,-0.192024,0.007275,0.280026,0.235135,0.173953,0.202767,0.019948,-0.207290,-0.033191,-0.002781,-0.027462,-0.795870,-0.133762,0.025155,0.511766,-0.280445,0.254185,-0.124423,-0.329917,0.339367,-0.366919,0.009618,0.005518,0.189482,0.118494,-0.163442,0.017019,-0.350762,-0.191638,0.568598,0.174482,-0.145909,0.444474,-0.403736,-0.430578,-0.350204,0.159533,-0.286991,-0.149634,0.353211,0.291638,0.129038,0.018351,-0.576514,-0.126205,0.277654,-0.248456,0.054009,-0.246752,-0.149337,-0.556498,-0.396755,-0.824276,-0.408427,0.090559,0.078957,-0.135007,0.697785,-0.835891,0.048650,0.507012,0.118825,-0.160544,0.520433,-0.033697,-0.184159,-0.204620,-0.260152,0.103907,0.269150,0.277525,0.186966,0.492283,-0.208233,-0.016865,-0.507520,0.383485', '10484041', '1292062', '3005387', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26351526', '幸运是我', '剧情', '一个在城市中游荡的不羁少年阿旭（陈家乐 饰），因一盒鸡蛋而结识了孤独老人芬姨（惠英红 饰），因为工作失意、生活窘迫，无处可去的阿旭利用“计谋”住进了芬姨的老屋，两个完全没有交集的人成为了临时室友。然而，生活在各自主张世界中的两个人，在同一屋檐下无法平静，脾气古怪的芬姨立下规条, 令年少轻狂的阿旭难以接受。从相互制约到彼此理解，从漠不关心到时时牵挂，两人的摩擦逐渐成为了解对方的最好方式。在冰冷的城市里寻找着温暖的陪伴，因为对方的出现，让自己成为了一个幸运儿。©豆瓣', '惠英红', '罗耀辉', 8, 41493, 'tt5805026', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2373839669.jpg', 0.3, 1.3, 19.6, 54, 24.7, '0.487970,0.280210,-0.867624,0.555575,-0.458802,-0.177817,0.922075,0.314657,-0.722846,-0.098355,0.238523,0.769556,0.080769,0.424842,0.135700,-0.312579,0.074681,-0.665065,0.028019,-0.301860,-0.298843,-0.406355,-0.247581,-0.400588,-0.413063,-0.410155,0.722450,0.310064,-0.085596,0.379547,0.002205,0.186300,-0.442115,0.636547,-0.357759,-0.256419,0.045750,0.126653,-0.443349,0.127349,-0.292179,-0.212063,-0.210795,0.248484,-0.146600,0.482039,0.915217,-0.328749,-0.371838,0.099276,0.275423,-0.048017,-0.401713,0.009781,0.186406,0.021121,0.082016,-0.000762,-0.322710,0.185043,0.052681,0.046393,-0.727349,0.038049,0.216907,0.388740,-0.671597,0.832856,0.119506,-0.488190,-0.022385,-0.350838,0.369442,0.313141,0.321707,0.525880,-0.306406,0.174047,-0.265321,0.136744,0.754410,0.025947,-0.523821,0.452780,-0.465865,-0.103477,0.008079,-0.314953,-0.787631,-0.274650,0.167197,0.153566,-0.314916,0.256776,-0.680509,0.132091,0.053015,-0.047180,0.010987,-0.720349,-0.115343,-0.561118,-0.340646,-0.444774,-0.290575,0.250566,0.034172,-0.430156,0.756355,-1.027530,0.166359,0.357348,0.205274,-0.539486,0.712679,0.042514,0.177814,-0.348862,-0.030198,0.428223,0.000810,0.022925,0.198390,0.503766,-0.451676,0.321866,-0.545255,0.462526', '35030151', '4817024', '1301022', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26351812', '欧洲攻略', '喜剧', '《欧洲攻略》是由马楚成执导，梁朝伟、吴亦凡、唐嫣、杜鹃、林子祥等联袂主演的动作电影。影片主要讲述了特工林在风（梁朝伟 饰）与王小姐（唐嫣 饰）多年来亦敌亦友，相互欣赏又互相为敌。上帝右手在CIA被不明身份的苏菲（杜鹃 饰）偷走后，两人同时受CIA委托展开追寻。原本以为只是⼀场谋略较量，但在他们救下顶级黑客洛奇（吴亦凡 饰）后，却发现这背后还隐藏着一个更大的秘密。', '梁朝伟', '马楚成', 3.5, 61877, 'tt5827590', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2528361594.jpg', 49.9, 31.2, 14.3, 2.2, 2.4, '0.134039,0.136916,-0.709602,0.752641,0.339411,-0.261358,0.537084,0.118675,-0.356869,-0.222403,0.337922,0.600408,-0.400467,-0.116719,0.083883,-0.220024,-0.449041,-0.799588,-0.278651,-0.173345,-0.307196,-0.236593,-0.390870,0.104916,-0.083885,-0.104827,0.507250,-0.054364,-0.412327,0.419173,0.643583,0.055947,-0.452224,0.186560,-0.043548,0.017258,0.089200,0.205419,-0.462873,0.349538,0.126036,-0.330568,-0.428543,0.064830,-0.131911,0.443276,0.599123,-0.269141,0.135398,-0.024849,0.276302,-0.253981,0.300430,-0.119255,0.209799,0.128124,0.291338,0.042119,-0.073089,0.293506,0.201265,0.039510,-0.830808,0.285581,0.259817,0.097381,-0.473282,0.307673,-0.218251,-0.057545,-0.014217,-0.265276,0.260498,0.305963,0.506709,0.071402,0.135127,-0.059603,-0.290976,0.243347,0.419934,0.209794,0.112362,0.208699,-0.056449,-0.413203,-0.135329,-0.062525,-0.223032,-0.224555,0.545525,-0.033645,0.245110,-0.117556,-0.462324,-0.069804,-0.082539,0.138438,-0.038726,-0.581581,0.263193,-0.893143,-0.268302,-0.488292,-0.200657,0.121480,0.224180,-0.406034,0.569221,-0.792625,0.153477,0.585333,0.120846,-0.481576,0.476137,0.045037,-0.026584,-0.169693,-0.220204,0.081199,0.047491,0.039948,0.352653,0.316959,0.003863,-0.025493,-0.319086,-0.063872', '4301278', '25723905', '3318306', '26577354');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26351867', '六弄咖啡馆', '剧情', '小绿（董子健 饰）自幼和妈妈过着相依为命的生活，虽然家境贫寒谋生不易，但是小绿凭借着坚强的韧性和乐观向上的精神顺利且快乐的成长着。和好友阿智（林柏宏 饰）一起，小绿度过了美好的高中三年，美丽善良的女孩心蕊（颜卓灵 饰）给小绿的这三年带来了对于爱情美好的记忆和憧憬。一晃眼，毕业季将近，在造化的捉弄之下，小绿和心蕊考进了不同的大学，瞬间拉远的距离让他们之间亲密无间的感情渐渐的发生了变化。尽管小绿一直都在非常积极的维持着这段异地恋，但他还是慢慢的感受到，心蕊对待自己的态度和以前不同了。©豆瓣', '董子健', '吴子云', 6.7, 44200, 'tt5827496', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2367455902.jpg', 3, 11.5, 44.6, 29.9, 10.9, '0.278533,0.034805,-0.818384,0.776599,-0.171159,-0.322623,0.813573,0.031270,-0.480108,-0.160626,-0.206047,0.414583,-0.366350,0.641477,0.172676,-0.029543,-0.037766,-0.840460,-0.237163,-0.057012,-0.278887,-0.615832,-0.431877,0.183304,-0.204338,-0.543619,0.623243,0.049065,0.020201,0.904502,-0.023225,-0.108865,-0.024418,0.427048,-0.298602,0.090715,-0.214663,0.574316,-0.393206,-0.222816,0.371643,-0.171453,-0.051205,0.040054,0.251633,0.258115,0.930227,-0.276184,-0.426117,0.198907,0.428771,-0.038382,-0.198789,0.035625,0.246721,0.082838,0.244457,0.172198,-0.265983,-0.006485,-0.019184,-0.234255,-0.659157,0.100216,0.267034,0.009438,-0.813867,0.908772,0.215912,-0.182048,0.330006,-0.476475,0.005540,0.661506,0.101757,0.724874,-0.499352,0.112438,-0.423315,0.189563,0.951454,0.123309,-0.569805,0.663351,-0.604292,-0.311077,-0.345801,-0.239149,-0.507727,-0.070763,0.067287,0.236573,-0.324392,0.421200,-0.718061,0.221076,0.117102,0.027950,0.212090,-0.753634,0.006009,-0.349517,-0.388042,-1.273962,-0.607316,0.173862,-0.092205,-0.586018,1.125483,-1.058068,0.258253,0.356218,0.464793,-0.434169,0.756711,0.323222,0.140472,-0.128670,-0.038769,0.540051,-0.283648,0.175928,0.283604,0.571498,-0.173017,0.203564,-0.751170,0.806230', '26354526', '1390020', '10833971', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26352306', '诗无尽头', '剧情', '本片是一部围绕智利裔墨西哥籍魔幻现实主义大师亚历桑德罗·佐杜洛夫斯基的传记片。主要讲述其在早年的创作之路。在片中，亚历桑德罗还与很多国内年轻有才但还未成名的年轻人见面交谈。', '亚当·佐杜洛夫斯基', '亚历桑德罗·佐杜洛夫斯基', 8.4, 9356, 'tt4451458', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2345544638.jpg', 0.7, 2.1, 14.3, 42.5, 40.5, '0.037858,-0.510116,-0.979540,0.711119,0.254312,-0.793496,0.726746,-0.064703,-0.395586,-0.556647,0.102881,1.030167,-0.338955,-0.185770,0.418547,-0.126722,-0.433549,-0.359571,0.119914,-0.080961,-0.076627,-0.509334,-0.590827,0.273205,-0.907919,-0.466933,0.528455,0.014855,-0.442869,0.284149,0.266587,0.247843,-0.258055,0.345128,-0.460768,0.178683,0.326042,-0.016289,-0.426578,0.072116,-0.012824,-0.292270,-0.420818,-0.162376,0.047111,0.630038,0.463225,0.032867,0.232746,0.492311,0.245374,-0.052800,0.126004,-0.202986,0.298859,0.112315,0.587073,0.243678,-0.041502,0.031001,-0.487297,-0.171956,-0.566588,0.161169,0.353767,0.306456,-0.656531,0.297356,-0.099878,-0.272070,-0.015464,-0.335933,0.071757,0.406241,0.258270,0.382834,0.630639,-0.141490,-0.435809,0.246021,0.134031,0.007214,-0.548598,0.587529,0.012293,-0.514679,-0.025051,-0.176708,-0.416840,0.133131,0.272831,-0.477302,0.133970,0.140906,-0.508048,0.114001,-0.178379,-0.113810,0.094007,-0.149231,0.123975,-0.953441,-0.240446,-0.489991,0.126864,0.013656,0.570074,-0.331113,0.996083,-0.519197,0.289516,0.526768,0.110195,-0.273750,0.574151,0.142891,0.199685,0.024489,-0.242982,0.660328,0.257655,-0.213254,-0.345389,0.787525,0.233240,-0.416934,-0.203462,0.147986', '1293433', '26611806', '1870681', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26352361', '宝贝当家', '喜剧', '小公主宝儿（王诗龄 饰）在家中不幸遭遇了一波劫匪的袭击......劫匪的头领不是别人，正是她父亲的孪生兄弟金大虎。此人为遗产纷争而来，不想却被手下算计，盗窃计划演变为绑架侄女，大虎后悔不已，而真正的幕后黑手是一个叫残忍哥的狠角色。宝儿的保姆兼保镖琴姐被劫匪放倒，手无寸铁的宝儿只好电话求救之前在闹市布店结识的几位小伙伴。于是，这由宝儿带领的“超级宝贝联盟”与坏蛋团伙展开了一场酣畅淋漓的“小鬼大战”……', '王诗龄', '张敏', 2.9, 2769, 'tt5870806', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2365829734.jpg', 74.8, 13.6, 7.3, 1.5, 2.9, '0.209087,-0.311230,-0.367853,0.436647,-0.520059,-0.319288,0.670299,0.190298,-0.636152,-0.016147,0.670255,0.552219,0.047102,0.087924,0.038120,-0.167579,0.081107,-0.496689,-0.259515,0.137141,-0.098733,-0.269290,-0.055657,-0.202531,0.166006,-0.039301,0.174919,-0.141729,-0.215483,0.223634,0.507592,0.201776,-0.430859,0.258341,-0.053594,0.085970,0.187982,-0.120716,-0.332876,-0.062158,-0.175716,-0.298904,-0.170354,0.105407,-0.011850,0.271711,0.779695,-0.434194,0.200682,-0.552045,0.089714,-0.445005,-0.161272,-0.139366,0.490038,0.007664,0.430026,0.006935,0.170586,-0.326656,0.149659,-0.108383,-0.658870,0.333061,0.140561,-0.092926,-0.635453,0.219845,-0.158812,0.147123,0.168923,-0.204393,0.233139,0.229396,0.170330,0.223723,-0.081189,0.082367,-0.431908,0.220805,0.624840,-0.148006,0.463955,0.187101,0.240967,-0.364174,0.243517,-0.413531,-0.539160,0.202846,0.721005,-0.495175,-0.433208,0.268283,-0.434213,-0.208807,-0.573861,0.116502,-0.081794,-0.529892,-0.316381,-0.240081,-0.013115,0.022156,-0.024370,0.247670,0.231888,0.170098,0.766601,-0.848628,-0.000400,0.652846,0.151972,-0.653453,0.268540,0.155684,-0.009792,-0.224848,-0.169212,-0.383310,0.259221,0.248578,0.337758,0.134946,-0.230034,-0.288816,0.001041,-0.030793', '1877596', '1292829', '24756658', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26352435', '指甲刀人魔', '喜剧', '西恩（张孝全 饰）是一个单纯善良的男孩，和女友拍拖多年，对她的感情十分深厚。然而令他怎么也没有想到的是，自己的耿耿忠心换来的却是对方的无情背叛，愤怒和痛苦之中，西恩选择了离开，与此同时，他内心里对于爱情的信仰永远的破碎了。为了不受伤害，西恩彻底的关闭了心扉。一次偶然中，西恩邂逅了名为艾米丽（周冬雨 饰）的可爱女孩。艾米丽的大大咧咧活泼可爱渐渐治愈了西恩心中的伤痕，他开始想要再度尝试相信艾米丽，相信爱情。然而，这一次，西恩又要失望了，原来，看似单纯的艾米丽隐藏了一个诡异的秘密——她是一个靠吃指甲刀维生的指甲刀人魔。©豆瓣', '周冬雨', '关智耀', 4.3, 10479, 'tt6839248', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2454282762.jpg', 27.5, 39.7, 25.6, 4.9, 2.3, '0.336611,0.254905,-0.717502,0.695517,-0.219294,-0.246442,1.123749,-0.224541,-0.478232,-0.093592,0.078624,0.687830,-0.080911,0.210762,-0.036376,0.315308,-0.053151,-0.612271,0.044694,-0.112862,-0.190383,-0.360785,-0.386810,-0.344440,-0.243112,-0.264633,0.536787,0.296615,0.036333,0.437619,0.474897,0.288050,0.233577,0.578620,-0.137758,0.091337,0.003135,-0.243895,0.020623,-0.016484,0.364405,-0.240042,-0.030473,0.742822,-0.373592,0.549252,0.583291,-0.350005,-0.227502,0.068223,0.295366,-0.241630,-0.211633,0.171982,-0.204966,-0.126281,0.198423,0.150735,-0.250432,-0.149538,0.253060,0.030731,-0.924982,-0.027990,0.140486,0.189905,-0.479628,0.645385,-0.121461,-0.132832,0.196092,-0.234183,0.123865,0.148453,0.593541,0.392455,-0.327191,-0.117187,-0.094391,-0.019359,0.722708,0.005548,-0.496721,0.749776,-0.491422,-0.293178,0.066415,-0.200823,-0.612277,0.077231,0.241778,0.276200,-0.180684,0.249454,-0.579409,0.058990,-0.380488,0.119661,-0.066438,-0.587903,-0.096831,-0.038755,-0.384507,-0.649740,-0.535222,-0.023629,-0.245134,-0.382378,0.752865,-1.081152,0.099588,0.274397,0.268602,-0.402591,0.628904,0.202456,-0.209047,-0.211869,0.207528,0.507308,-0.087605,0.028518,0.258955,0.443497,0.137243,0.147598,-0.229246,0.632704', '24756472', '1296370', '1292062', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26352440', '天亮之前', '爱情', '赌徒高野（郭富城 饰）继承千万资产后输得一干二净，家道也因此中落，就在他一筹莫展时，打扮妖冶的堕落天使茉茉（杨子姗 饰）主动上门提供特殊服务。不料他们却遭遇庄家买凶追杀，蒙眼飙车、女儿被绑一系列意外接踵而至。嗜赌成性的赌徒和用爱洗白的风情女，天亮之前他们该如何选择接下来的路……', '郭富城', '吴中天', 5.9, 20278, 'tt5843056', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2363294351.jpg', 7.7, 23.7, 43.1, 17.9, 7.5, '-0.150130,0.085127,-0.314289,0.014061,-0.317623,-0.147611,0.232673,0.006039,0.033252,0.056806,0.355244,0.527977,0.048102,-0.025600,0.287712,0.025127,-0.247068,-0.321376,0.280646,0.072529,-0.006025,-0.192077,-0.094433,-0.047558,0.031800,-0.044172,0.362870,0.074378,-0.089322,0.541394,0.529558,0.204496,-0.330903,0.407426,0.134146,-0.061862,-0.150050,-0.000094,-0.098012,0.057142,-0.170720,-0.110480,-0.077527,0.042615,0.156943,0.481101,0.462290,-0.181276,-0.249214,-0.341583,0.478963,-0.261139,-0.079819,0.314599,0.227454,-0.107956,0.399917,0.070184,-0.082804,-0.164837,0.172694,0.191218,-0.579973,0.074096,0.197978,-0.059845,-0.428301,0.115741,-0.088002,0.136879,0.136308,-0.185027,0.058919,0.051468,0.566968,0.039186,0.053402,-0.102649,-0.413554,0.236080,0.591272,-0.051997,0.051667,0.227237,0.031391,-0.154548,0.241164,-0.533690,-0.247572,-0.043746,0.438581,0.183252,-0.000046,-0.027124,-0.274726,-0.160303,-0.017414,0.193359,0.020211,-0.299034,-0.186449,-0.465291,0.004969,-0.307826,-0.316709,0.331234,0.179464,-0.216936,0.399216,-0.379117,0.049850,0.621891,0.455867,-0.759154,0.440843,0.035816,0.119531,-0.011215,-0.368452,0.097097,0.174582,0.073755,0.094941,0.056812,-0.183178,-0.001093,0.012678,0.282840', '26678784', '1305915', '25918677', '1304624');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26352445', '反贪风暴2', '剧情', '廉政公署根据调查，发现马会的球赛博彩操盘手（尹子维 饰）涉嫌违法行为。在试图调查此人的时候，此人却遭杀手（周渝民 饰）杀害。廉署首席调查主任陆志廉（古天乐 饰）作为目击证人受到重案组督察刘保强（张智霖 饰）的调查。在此之后，廉署和警方联合展开行动，只不过在这一过程中，双方彼此防备，关系微妙。根据刘保强的线人提供的信息，博彩幕后操盘手是一个被称为华老师的神秘人物。陆志廉顺藤摸瓜，逼近猎物，怎奈对方分外狡猾，被对方三番五次逃脱。在这一过程中，马会中又有前廉署人员遇害。为了金钱利益，人性尽失……©豆瓣', '古天乐', '林德禄', 5.9, 68706, 'tt5998744', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2370795749.jpg', 5.1, 22.1, 50.4, 16.1, 6.3, '0.239100,-0.167673,-0.499322,0.489701,0.072273,0.227464,0.487296,-0.018822,-0.792241,-0.240922,0.374327,0.446740,-0.267470,-0.212182,0.218742,-0.306133,-0.348565,-0.723797,-0.218367,-0.206778,-0.277257,-0.643531,-0.360303,-0.089983,0.139448,-0.028864,0.486665,0.168035,-0.506995,0.484816,0.234404,0.316143,-0.445987,0.329537,0.186127,-0.028306,0.680507,-0.237778,-0.309353,0.234925,-0.056860,-0.492094,-0.100971,0.160189,-0.039190,0.751785,0.521137,-0.295879,-0.210583,-0.468927,0.202414,-0.349649,0.002838,0.080774,0.778036,0.266690,0.250474,0.665093,-0.344964,-0.051683,-0.071433,-0.079415,-1.277334,-0.200144,0.318485,0.477668,-0.100970,-0.133800,-0.377158,0.289137,-0.048024,-0.147599,0.213054,0.322167,0.425171,-0.284036,0.181724,-0.058552,-0.400196,0.100012,0.583293,0.049798,0.068688,0.007241,-0.183913,-0.573926,-0.053849,-0.228624,0.159624,0.006298,0.459418,-0.075166,0.020020,0.095330,-0.406085,-0.085308,0.010773,0.056892,-0.423243,-0.364284,-0.051901,-0.791129,-0.317461,-0.265152,-0.384418,0.089246,0.007612,-0.338178,0.293200,-0.823594,-0.082011,0.626995,0.248913,-0.593655,0.409197,0.065568,0.120814,-0.363702,-0.544743,-0.260280,0.737782,0.367738,0.055941,0.028183,-0.183028,-0.637464,-0.098374,-0.342544', '1297689', '1793491', '1307442', '20388224');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26352462', '老笠', '惊悚', '这夜很离奇，自认废青的阿平来到谜之便利店第一晚上班，先遇上刻薄老板和神经质女同事，转头黑警来借厕所；刚出狱的愤怒老人即兴玩老笠，又有富豪和性感女伴乱入。众人各有故事，各怀鬼胎，一场大龙凤在便利店热闹上演。当炸弹狂徒来袭，最后殊途同归但又意想不到。笑他们太疯癫，只是这个城市病了我们看不穿，导演火火掌控节奏和精警对白非常准确，几位老戏骨交足功课，成就一部港片少见的黑色荒诞困兽斗好戏。', '郭伟亮', '火火', 7.4, 51347, 'tt4840096', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2324635033.jpg', 1.3, 5.1, 31.4, 46.5, 15.6, '0.067859,-0.435686,-0.309120,0.013678,0.057718,0.108115,0.870332,0.126649,-0.336487,-0.195381,0.127486,0.465170,-0.783491,0.029716,0.259847,-0.270590,-0.262218,-0.270224,0.110479,-0.094987,0.163104,-0.153454,-0.036810,-0.102215,0.114473,0.130975,0.207317,-0.043219,-0.221365,0.288750,0.391638,0.069670,-0.222843,0.368984,-0.520976,-0.016955,-0.067123,0.215039,-0.043843,-0.025242,0.112750,0.010660,-0.357152,0.095244,0.032315,0.008458,0.383895,-0.012971,-0.333922,0.145131,0.374298,-0.137096,-0.286031,0.051400,0.325164,0.008620,0.363789,-0.189467,0.233866,-0.182764,-0.197839,-0.082062,-0.445590,0.498236,0.143667,0.153419,-0.236741,0.549046,-0.010286,-0.193740,0.117038,-0.196299,0.079191,0.058717,0.511835,0.339045,0.172732,-0.064718,-0.509538,-0.004547,0.356357,0.377821,-0.093929,0.539031,0.165883,-0.458199,0.092778,-0.343187,-0.359601,0.289659,0.259612,-0.325457,0.150615,0.196269,-0.429500,0.122169,0.161977,-0.020357,-0.179882,-0.481853,-0.284205,-0.680267,-0.082446,-0.161689,-0.094662,0.161496,0.332538,-0.101648,0.623752,-0.551635,-0.227523,0.230612,0.164758,-0.399161,0.538581,0.037781,-0.144308,-0.297685,-0.100735,-0.247860,-0.055142,0.276175,0.283237,0.504625,-0.141895,-0.211770,-0.332402,0.120159', '10466639', '1394176', '1301686', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26353372', '夜行动物', '剧情', '和前夫托尼（杰克·吉伦哈尔 Jake Gyllenhaal 饰）离婚后，苏珊（艾米·亚当斯 Amy Adams 饰）嫁给了名为霍顿（艾米·汉莫 Armie Hammer 饰）的男子，尽管两人的婚姻已经维系了十多年之久，但很显然，这段感情早已经失去了激情，疲态尽显。与此同时，霍顿公司遭遇的危机，亦让这个曾经富裕的家庭走到了濒临破产的边缘，而苏珊严重的失眠问题持续的困扰着她的生活。某日，苏珊收到了一封意外的邮件，托尼将自己新创作尚未出版的小说《夜行动物》寄给了苏珊，他告诉苏珊，这是一本专门为她写就的小说，希望她能够读一读。在阅读小说的过程中，苏珊不断的回忆起自己和托尼自相恋到决裂的过程，在此过程中，一些肮脏而又不为人知的秘密渐渐浮出了水面。©豆瓣', '艾米·亚当斯', '汤姆·福特', 7.4, 102949, 'tt4550098', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2391556881.jpg', 0.9, 4.1, 33.8, 46, 15.2, '0.407457,0.087086,-0.637864,0.667084,0.159710,-0.388691,0.764425,-0.032258,-0.494889,-0.291292,0.106638,0.703065,-0.176480,0.354292,0.254299,0.040311,-0.323023,-0.872378,0.056766,-0.299901,-0.285726,-0.608384,-0.423329,-0.351091,-0.150690,-0.496339,0.639690,0.228887,-0.155000,0.453813,-0.033168,0.273515,-0.107866,0.594451,-0.070767,0.264145,0.100662,0.097167,-0.202038,0.095323,0.359745,-0.379458,0.028249,0.390479,0.100964,0.391748,0.774123,-0.274222,-0.373379,0.256972,0.675095,-0.208653,-0.017324,0.036606,0.269895,0.070323,0.251155,0.257062,-0.290537,-0.088582,0.008580,-0.130912,-0.786703,-0.034354,-0.088225,0.294601,-0.502303,0.613444,-0.326060,0.025158,0.160047,-0.376532,0.071667,0.557284,0.373593,0.322816,-0.173247,0.108390,-0.247960,0.412227,0.274535,0.011044,-0.293989,0.589555,-0.377286,-0.318559,-0.204366,0.050839,-0.596271,-0.046677,0.485283,0.242196,-0.317103,0.427068,-0.600908,0.050867,-0.221788,-0.209879,0.092903,-0.349958,-0.295377,-0.523236,-0.538229,-0.391306,-0.241756,-0.124287,0.131274,-0.348779,0.639498,-0.686072,0.537617,0.508901,-0.013337,-0.393288,0.519779,0.059328,0.049670,-0.062803,0.060370,0.355416,-0.208120,0.318228,0.141273,0.320299,0.199905,-0.038778,-0.527978,0.732265', '1299663', '30401849', '27666513', '3262091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26353884', '公羊', '剧情', '居住在同一个山谷里的一对老年兄弟K和W,因为未说明的原因四十年不曾说过一句话,全靠一条狗传递纸条来交流沟通. 整个山谷并没有多少人居住,但就在全山谷举行的养羊比赛中,K的大公羊以微弱优势获得胜利,W十分不服气,不经意间,他发现K的羊得了瘟疫,于是前去举报,导致包括K和W 家在内的整个山谷的羊都不得不面临被人道主义毁灭的危险.没有了羊,K完全不知道怎么度过漫长的冬季,而受到牵连的W在地窖里悄悄地藏了几只,但这个秘密并没有保守太久......', '西德格尔·西乌尔乔森', '格里莫·哈克纳尔森', 7.4, 6657, 'tt3296658', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2278317807.jpg', 0.5, 2.8, 34.9, 48.7, 13, '0.450916,-0.094518,-1.014507,0.608932,-0.157963,0.069467,0.972279,-0.187734,-0.609848,-0.330206,0.051032,0.610749,-0.156033,-0.055957,-0.273394,-0.159954,-0.007081,-0.341215,-0.197661,-0.343609,-0.624995,-0.616711,-0.176216,-0.097390,-0.184846,-0.035440,0.437294,0.298613,-0.381751,0.444038,-0.076740,-0.057333,-0.119349,0.690597,-0.345560,0.012432,-0.084564,0.258998,0.058440,0.248893,-0.120027,-0.120178,-0.338542,0.387752,0.248528,0.634254,0.490796,-0.566962,-0.342089,0.305564,0.092974,-0.312990,-0.147370,0.228385,0.734619,-0.123525,0.542369,0.272773,-0.282000,0.109875,-0.075005,-0.140393,-0.922288,0.095871,-0.086723,0.433459,-0.513264,0.672609,0.223928,-0.298980,-0.048089,-0.213114,0.415958,0.268812,0.277956,0.351565,-0.120788,-0.098785,-0.795566,-0.156358,0.790096,-0.397948,-0.248106,0.378789,-0.100071,-0.520151,-0.016879,-0.083245,-0.297711,0.010433,0.198149,0.170746,-0.621993,0.181384,-0.595355,0.364788,-0.067785,-0.500156,-0.072877,-0.512357,-0.285948,-0.351357,-0.114291,-0.455359,-0.121545,0.448341,0.290585,0.005242,0.552554,-0.919843,0.456422,0.331684,0.252216,-0.494339,0.624796,0.195650,0.313654,0.038691,-0.026171,0.176933,0.404553,0.451744,0.530840,0.356406,-0.058717,-0.257461,-0.659723,0.380062', '1297996', '1308755', '1947080', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26354336', '爵迹', '动画', '麒零（陈学冬 饰）本来是奥汀大陆一个小镇里的普通男孩，直到有一天他遇见了二度使徒神音（杨幂 饰），见到了传说中的神兽，因此开始了新的命运。原来奥汀大陆被分为四个国家，每个国家都有强大的精通魂术者，最厉害的人被称为王爵，王爵的继承者则被称为使徒。麒零被七度王爵银尘（吴亦凡 饰）找到，成为了他的使徒，在银尘的带领下，麒零开始了修行，并认识了刁蛮的六度使徒天束幽花（林允 饰），身负重要使命的五度使徒鬼山莲泉（范冰冰 饰）、邪魅的二度王爵幽冥（陈伟霆 饰）和四度王爵特蕾娅（郭采洁 饰）等人，苍白少年（王源 饰）的出现，让上代一度王爵吉尔伽美失踪的秘密浮出水面，众人开始了追寻真相的杀戮之战。纷争中，以鬼山莲泉和鬼山缝魂（严屹宽 饰）为代表的使徒和王爵陷入了猎杀中，而银尘则一心想追吉尔伽美的踪迹。©豆瓣', '范冰冰', '郭敬明', 3.8, 151583, 'tt4819576', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2377470803.jpg', 52.7, 20.1, 17.5, 5.6, 4, '0.127127,0.397465,-0.667593,0.637032,0.012787,0.002159,0.607681,0.183066,-0.366111,-0.102037,0.145910,0.759132,-0.125177,-0.088207,0.220493,0.196608,0.149386,-0.606199,-0.149295,-0.368098,-0.348722,-0.218996,-0.383630,0.058627,-0.090595,-0.665746,0.552160,0.128417,0.107909,0.321341,0.424853,0.331025,-0.190587,0.327226,-0.153382,0.015029,0.201323,-0.120326,0.163453,0.313307,-0.378781,-0.162298,0.061764,0.439515,-0.287502,0.466907,0.741625,-0.663541,0.207010,-0.334784,0.223019,-0.309405,-0.502808,-0.072861,0.555430,-0.026863,0.211080,0.602189,0.209421,-0.124157,0.049494,0.108691,-0.915220,0.124350,0.352813,0.293664,-0.238601,0.577867,-0.288616,-0.116973,0.189045,-0.042548,0.598067,0.266600,0.259878,0.227315,0.065478,-0.039339,-0.377006,0.256142,0.417384,0.031597,-0.384547,0.114109,0.074409,-0.557183,-0.268461,-0.260267,-0.028789,0.002166,0.329196,0.186516,0.229296,0.380586,-0.717042,-0.090383,-0.256695,-0.084226,-0.117709,-0.297074,-0.288666,-0.157403,-0.149304,-0.320989,-0.123326,0.088540,0.140569,-0.412459,0.589372,-0.829333,0.276285,0.268549,0.430308,-0.418927,0.622379,-0.103868,0.206766,-0.122666,-0.221487,0.150753,-0.127640,0.374847,0.071906,0.306075,-0.339795,-0.044353,-0.494759,0.297243', '25774050', '26759819', '1793491', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26354526', '睡在我上铺的兄弟', '剧情', '故事开始于沪都大学303宿舍内，个性大大咧咧无畏惧他人眼光的林向宇（陈晓 饰），虽然身为海归富二代但心中只惦记着自己的宠物羊驼的李大鹏（杜天皓 饰），身强体壮但心思细腻温柔的谢训（李现 饰），拥有高超智商但缺少女人缘的学霸管超（刘芮麟 饰），这四位来自天南地北的大男孩们相聚在此，成为了朝夕相处的室友，拉开了有笑有泪的大学生活的序幕。短暂的四年一晃眼就要过去，站在人生的十字路口前，四人会做出怎样的选择？林向宇是否能够追求到他一直心系的“丝帕女生”？谢川和女友高宝镜（蓝盈莹 饰）之间的感情又会迎来怎样的结局呢？©豆瓣', '陈晓', '张琦', 5.6, 50247, 'tt5599016', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2325669261.jpg', 12.6, 25, 39.7, 14.1, 8.5, '0.178111,0.061910,-0.762783,0.543482,-0.166396,-0.142420,0.665931,0.112586,-0.373519,-0.178754,0.128786,0.416690,-0.219629,0.326032,0.120785,-0.216713,-0.052694,-0.753883,0.034471,-0.370613,-0.256131,-0.225651,-0.263099,-0.025843,-0.231174,-0.052376,0.721562,-0.023072,-0.062734,0.396130,0.422778,0.259328,0.021368,0.276333,-0.304641,-0.040216,-0.087725,0.474959,-0.151803,0.031167,0.086189,0.036894,-0.291100,-0.058015,0.000371,0.081210,0.756517,0.011945,-0.260006,0.111618,0.354784,-0.103388,-0.126591,-0.079555,0.395772,0.049630,0.176106,-0.005867,0.192938,-0.037099,0.066688,-0.089740,-0.491915,0.055095,0.075232,0.127616,-0.515410,0.532207,-0.129473,-0.368595,0.079563,-0.424334,-0.065922,0.177796,0.382114,0.503706,-0.144576,0.263352,-0.454336,0.068643,0.598567,0.343924,-0.376192,0.406417,-0.238926,-0.566251,-0.159334,-0.227442,-0.468530,-0.092518,0.067414,0.076556,-0.042845,0.343340,-0.515139,0.239798,0.035711,0.291924,0.243091,-0.451166,-0.212032,-0.317884,-0.202508,-0.916602,-0.421248,0.095477,0.261517,-0.464493,1.028541,-1.044659,0.075785,0.123865,0.256077,-0.492790,0.810587,0.261379,0.088386,-0.053257,-0.085798,0.313131,-0.105795,0.011341,-0.082337,0.279988,-0.238600,0.002422,-0.289879,0.415460', '6963575', '1826173', '3445516', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26354572', '欢乐好声音', '喜剧', '曾拥有过辉煌风光年代的一家歌剧院正逐步走向没落，更面临被银行抵押没收的命运。现任老板考拉巴斯特（马修·麦康纳希 Matthew McConaughey 配音）不愿见父亲毕生的心血就此终结，于是决定策划一场歌唱选秀比赛，却没留神把奖金印成了他根本无力承担的10万美元。受到奖金和歌唱梦想的鼓舞，猪妈妈罗茜塔（瑞茜·威瑟斯彭 Reese Witherspoon 饰）、少女豪猪艾什（斯嘉丽·约翰森 Scarlett Johansson 饰）、老鼠歌手麦克（塞斯·麦克法兰 Seth MacFarlane 饰）、害羞的小象米纳（托瑞·凯利Tori Kelly 饰）、大猩猩强尼（塔伦·埃格顿 Taron Egerton  饰）等音乐爱好者都纷纷前来应征。他们有着各自难以逾越的障碍，而为了各自的梦想，有竭尽全力，追逐哪怕一点点微茫的希望……©豆瓣', '马修·麦康纳', '加斯·詹宁斯', 8.1, 260501, 'tt3470600', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2411622136.jpg', 0.2, 1.8, 20.2, 48.9, 28.9, '-0.227691,-0.119024,-0.540193,0.384075,0.068356,-0.311932,0.360032,0.242790,-0.104846,-0.207387,0.125600,0.670847,-0.112964,0.084191,0.286125,-0.324806,-0.230121,-0.667930,0.221133,-0.064695,-0.012889,-0.325991,-0.014194,-0.115518,-0.275110,-0.189461,0.604271,-0.115046,0.089308,0.501321,0.457766,0.135621,0.118716,0.036575,-0.019687,0.144322,0.322881,0.133564,-0.316399,-0.031263,0.017801,0.005195,-0.275698,0.055298,0.227366,0.133523,0.398086,-0.312411,0.310860,-0.146145,0.173624,-0.044583,0.247153,0.187054,-0.076652,0.047502,0.079612,0.054612,-0.168445,-0.147396,0.290349,-0.288496,-0.737178,0.051326,0.112564,0.307387,-0.242923,0.332675,-0.153769,0.218522,0.071939,-0.046847,-0.212877,0.181756,0.444614,0.266391,0.048584,-0.004417,-0.455194,0.362988,0.431353,-0.210879,-0.109480,0.382320,-0.283118,-0.199815,0.006835,-0.215889,-0.647737,0.082578,0.395999,0.195574,0.246114,0.259372,-0.690267,-0.120831,-0.237279,-0.270817,0.029295,-0.398065,-0.017062,-0.549529,0.072624,-0.072792,0.020100,0.126468,0.163999,-0.232514,0.613596,-0.565032,0.201355,0.318828,0.288945,-0.303531,0.446762,-0.159226,0.270005,-0.121297,0.021056,0.401637,0.051152,0.141375,0.205124,-0.043529,0.107803,-0.343477,-0.020714,0.525341', '4301278', '25928048', '143425