INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26354587', '寻：电影版', '剧情', 'HBO在刚播完第二季后，取消了本季收视下滑的《寻》。不过HBO表示将以一个电视电影特别篇的方式讲清楚所有的故事。这也是之前HBO对之前有几部喜剧被取消采取的作法。帕特里克（乔纳森·格罗夫 Jonathan Groff 饰）重新回到旧金山，他该如何面对昔日的朋友和前男友们，需要面对怎样的选择和决定......', '乔纳森·格罗夫', '安德鲁·海格', 7.9, 13998, 'tt4552118', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2369735987.jpg', 1, 3, 23.6, 42.6, 29.7, '0.352058,0.044344,-0.427808,0.667365,0.106083,-0.080166,0.500898,0.068309,-0.464693,-0.300902,-0.107285,1.010429,-0.345581,0.166904,0.283967,-0.142301,-0.539985,-0.897748,-0.182350,-0.125078,-0.332561,-0.517529,0.011466,0.205088,-0.023691,0.066672,0.796204,-0.064433,-0.179528,0.206238,0.618439,0.444000,0.260706,0.291562,0.091432,0.066073,-0.286540,0.081510,-0.669513,0.644613,0.664213,-0.129578,-0.279316,0.109853,0.076726,0.406887,0.783169,-0.204747,-0.389604,0.253888,0.486320,-0.389215,-0.065994,0.438943,0.102087,0.242895,0.191481,0.388114,-0.209589,0.130150,-0.116074,-0.036277,-1.004509,-0.015746,0.052521,-0.066506,-0.708747,0.216397,-0.078625,-0.001459,0.157261,-0.577038,0.086012,0.522691,0.731851,0.351189,-0.124033,-0.198115,-0.297843,0.125257,0.828261,0.231333,-0.258511,0.601898,0.331000,-0.258022,-0.088178,-0.359805,-0.391585,0.232492,0.060581,0.222338,-0.126836,-0.125752,-0.586267,-0.394361,-0.031275,-0.778390,0.234044,-0.686305,0.022469,-0.779110,-0.037166,-0.342461,-0.274778,-0.304361,0.289138,-0.291893,0.830626,-0.965835,0.168391,0.150401,0.375472,-0.806713,0.545775,0.218629,0.284013,-0.110235,0.231615,-0.264838,0.119441,0.311414,0.221116,0.105123,0.321340,-0.449210,-0.628374,0.549718', '4301278', '26678784', '30345227', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26356321', '莫西干回到故乡', '喜剧', '繁华大都会，有一支辛苦打拼而又名不见经传的摇滚乐队。作为乐队成员的田村永吉（松田龙平 饰）来自位于广岛县濑户内海上的户鼻岛，此时他已经离家整整七年了。前途一片渺茫，加上新近得知女友会泽由佳（前田敦子 饰）怀孕的消息，这个留着莫西干头的小青年终于决定停止乐队活动，回到阔别已久的家中结婚。经过漫长跋涉，永吉总算和由佳踏上了故乡的土地。他的爸爸田村治（柄本明 饰）现担任当地学校交响乐团的指挥，为人十分顽固。忤逆的长子回家，必不可少要爆发一顿争吵。所幸历经艰险，永吉还是熬到了举办婚礼的那一天。偏偏就在喜庆的最高潮，老父亲突然病倒了……不经意间，每个人都要面对生离死别。©豆瓣', '松田龙平', '冲田修一', 7.7, 10207, 'tt4691804', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2294115535.jpg', 0.4, 2, 29.4, 49.8, 18.4, '0.057877,0.007754,-0.589577,0.207585,0.170162,-0.453344,0.479950,0.142768,-0.593763,-0.271791,0.347431,0.536174,-0.180624,0.297705,0.385275,-0.078284,-0.291645,-0.536025,0.083482,-0.251812,-0.117708,-0.122375,-0.004982,0.087543,0.036213,0.031262,0.642013,0.317395,0.228709,0.437400,0.316960,0.193070,0.038431,0.288263,-0.268466,0.044500,0.256209,0.140284,-0.156621,0.023576,-0.142604,-0.285899,-0.221692,0.030375,0.273082,0.376721,0.613132,0.038015,-0.185371,-0.014619,0.402611,-0.193001,-0.228880,-0.007640,0.384837,0.197488,0.250221,0.248920,-0.394622,0.043972,-0.346375,-0.311398,-0.277215,0.145995,0.312215,-0.052062,-0.673183,0.779159,0.078363,-0.232424,0.108692,-0.390585,0.231581,0.574869,-0.000724,0.540620,-0.143915,0.152364,-0.227062,0.226165,0.854656,-0.238103,-0.162377,0.109062,-0.049157,-0.350321,0.139691,-0.456781,-0.436238,-0.012465,0.035970,-0.032858,0.092749,0.113589,-0.489598,0.141895,-0.206839,-0.373132,0.365774,-0.127607,-0.319590,-0.427172,0.078372,-0.218598,-0.140342,0.435394,0.110460,-0.016036,0.611975,-0.791530,0.273479,0.298995,0.085817,-0.231301,0.365771,0.226857,0.066409,-0.411084,0.123484,0.324206,-0.072120,0.486835,-0.076808,0.142119,-0.299521,-0.224453,-0.465674,0.414485', '35030151', '25721544', '1826173', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26356488', '一九四四', '剧情', '1944年……德军与苏联列宁格勒方面军为争夺纳尔瓦地峡进行了一连串战斗。7月，苏军攻占了纳尔瓦，这座古城九百年来一直是俄罗斯和西方世界的分界线。纳尔瓦身后的坦能堡防线是爱沙尼亚首都塔林的最后防线，一群20岁出头的爱沙尼亚青年人志愿加入武装党卫军亲卫队第20师，开始在东线迎头痛击苏军装甲部队，为反抗苏联的占领而战。这不是爱沙尼亚第一次沦为东方和西方、德意志人和斯拉夫人交战的战场。从楚德湖的冰上大战算起，这一战斗已持续了七百多年，夹在中间的爱沙尼亚人也不可避免地被双方裹挟其中，成为历史的牺牲品。……到了9月，由于芬兰宣布停止同德国的军事合作并签订莫斯科停战协定，腹背受敌的德军决定撤出爱沙尼亚。苏军尾随着德军一路前进直至爱沙尼亚的首都塔林，红军中的叶沙尼亚（俄罗斯化的爱沙尼亚人）士兵也亲眼见证了，那面象征着爱沙尼亚民族独立的蓝、黑、白三色旗，于德军撤离的9月18日在塔林市的象征——赫尔曼塔悬挂了四天之后，终于在9月22日被苏联的红旗所取代。……占领塔林，并非苏德双方在爱沙尼亚的最后一战。……11月，在萨雷马岛泥泞、茂密的森林中，叶沙尼亚士兵顶着德军舰艇的炮火，驱逐了爱沙尼亚最后一批德军。大规模的战事终于结束了，但和平和自由仍未降临这片小小的国土，战争给人们带来的伤痛仍难以抚平……这，就是爱沙尼亚人的1944年。', '卡斯帕·威尔伯格', '埃尔莫·纽加农', 8.2, 19919, 'tt3213684', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2331600466.jpg', 0.4, 1.2, 16.5, 51.9, 30.1, '0.069314,0.157701,-0.899431,0.775981,0.216137,-0.266113,0.363358,-0.238778,-0.527254,0.290778,0.134881,0.519543,0.053104,-0.141474,0.464827,-0.163035,-0.341475,-0.857946,-0.348390,-0.217663,-0.525244,-0.375391,-0.353054,-0.191090,-0.044841,-0.302852,0.941594,0.494964,-0.176922,0.254516,0.125303,0.172168,0.087786,0.499546,0.006961,-0.041826,-0.079573,-0.478428,-0.377302,0.204822,-0.442376,-0.264462,-0.298418,0.030291,0.094291,0.507641,0.792157,-0.564653,0.453747,-0.272467,0.248857,-0.442937,0.033819,0.079531,0.580502,0.026959,0.004652,0.183296,0.000669,-0.173363,-0.239408,-0.328604,-0.212993,0.176536,-0.108984,-0.037298,-0.486347,0.923152,-0.120938,0.324443,0.217497,-0.066458,0.126008,1.113740,0.062130,0.371306,-0.382212,-0.083000,-0.709780,0.084409,0.693642,-0.187661,-0.480886,-0.223585,0.030513,-0.376224,-0.067024,-0.371853,0.074132,-0.283524,0.339318,-0.154732,0.111854,0.437245,-0.910550,0.202876,-0.382181,-0.717742,0.165431,-0.148741,-0.089946,-0.803002,-0.154238,-0.528068,-0.097655,0.501469,-0.030834,0.381050,0.691517,-0.621438,0.142029,0.429032,0.462127,-0.079092,0.477521,0.304994,0.181186,-0.043440,0.181819,0.701796,-0.252071,0.644331,0.403053,0.319583,-0.197577,0.116273,-0.115800,0.329635', '35058077', '5361544', '1424552', '26852888');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26356495', '女狙击手', '剧情', '苏联女学生柳德米拉·帕夫利琴科在一次射击游戏中无意间发现了自己的射击天赋，1941年她不顾家人反对毅然参军。帕夫利琴科成长为全苏联最出色的狙击手，同时她被德军视为不惜一切代价也要除掉的巨大的威胁。柳德米拉遇到一名男子并坠入爱河。然而，好景不长，战争过去，厄运却再次降临……', '尤利娅·别列希尔德', '谢尔盖·马克利斯基', 7.6, 26055, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2242291790.jpg', 0.8, 4, 30.5, 45.4, 19.2, '-0.237710,-0.026119,-0.714245,0.279909,-0.260133,-0.477818,0.814345,-0.357662,-0.309696,-0.305098,0.558174,0.677878,0.096603,-0.383479,0.282651,-0.060174,-0.027658,-0.836995,-0.067865,0.051137,-0.466320,-0.168066,-0.064523,-0.244596,-0.189335,-0.433069,0.713596,-0.050634,-0.455904,0.293808,0.378021,0.378465,0.155943,0.728568,-0.014546,0.043413,0.168837,-0.324382,-0.413635,0.372510,-0.399361,-0.305013,-0.302816,0.131259,-0.368512,0.232123,0.644764,-0.283561,0.018182,-0.339137,0.189741,-0.453429,-0.107873,0.284398,0.478277,0.120086,-0.019427,0.207734,0.198266,0.027762,-0.046435,-0.178594,-0.553679,0.117873,-0.119960,-0.026090,-0.412472,0.247342,0.019014,0.320055,0.067659,-0.062174,-0.147040,0.109571,0.270566,0.162019,-0.827533,-0.089496,-0.440351,0.161546,0.730838,-0.198325,-0.266026,0.200181,-0.177746,-0.364121,0.269545,-0.428026,-0.501517,0.132257,0.547845,0.211567,-0.270328,0.771321,-0.364395,0.019553,-0.815631,-0.254947,-0.202770,-0.297904,-0.060917,-0.432660,-0.195178,0.042874,-0.607256,0.454463,-0.124554,-0.269310,0.970046,-0.691166,0.255806,0.597026,0.391419,-0.319671,0.433618,0.278959,0.149609,-0.119290,-0.089692,0.793325,0.133144,0.229715,-0.434897,0.133192,-0.152222,-0.244714,-0.039605,0.273400', '33407124', '10555084', '10486471', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26356631', '伸冤人2', '动作', '麦考尔（丹泽尔·华盛顿 Denzel Washington 饰）一直以来都过着隐姓埋名离群索居的生活，所有人都以为他已经死了，只有苏珊（梅丽莎·里奥 Melissa Leo 饰）还和他保持着联系。一天，苏珊接到任务，要前往布鲁塞尔调查一位CIA特工自杀的案件，之后就失去了联系，麦考尔凭借这本能察觉到，苏珊已经死了。为了调查苏珊死亡的真相，麦考尔不惜重出江湖，他和曾经的搭档戴夫（佩德罗·帕斯卡 Pedro Pascal 饰）取得了联系，然后得知苏珊的死亡和他曾经的同行们有着千丝万缕的关联，如今他们都已经成为了自由职业杀手，而苏珊就是他们的目标之一。所有事件的发源处就是那起特工自杀案件。©豆瓣', '丹泽尔·华盛顿', '安东尼·福奎阿', 7.2, 48624, 'tt3766354', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2529742142.jpg', 0.5, 4.5, 41.9, 39.1, 14.1, '0.085760,-0.230958,-0.772508,0.674576,-0.156172,-0.395630,0.531372,-0.096894,-0.492631,-0.440546,-0.053099,0.750088,-0.150606,0.245904,0.460140,-0.099677,-0.397125,-1.129542,-0.086260,-0.302476,-0.452514,-0.644616,-0.328258,-0.303236,-0.075713,-0.148196,0.555947,-0.097688,-0.237227,0.519885,0.439422,0.411266,-0.203577,0.570528,-0.209326,0.023251,0.374897,-0.251859,-0.481855,0.074904,0.330978,-0.076581,-0.017537,0.307149,0.138521,0.441238,0.426814,-0.300187,-0.148421,-0.068753,-0.017559,-0.332397,0.031957,0.132908,0.464231,-0.122662,0.132239,0.519016,-0.298387,-0.012091,0.196642,0.176759,-0.961164,0.004294,0.047087,0.335915,-0.573321,0.205472,-0.177193,0.167194,0.044598,-0.276077,0.440750,0.574732,0.202602,0.109703,0.020386,-0.208367,-0.605189,0.175554,0.914432,-0.210026,-0.181121,0.116426,-0.037143,-0.512444,-0.311212,0.044375,-0.383512,0.142534,0.234131,0.035190,-0.192510,0.476253,-0.532544,-0.345330,-0.398935,-0.266686,0.016982,-0.277456,0.287288,-0.766213,-0.404238,-0.369445,-0.510827,0.181796,-0.140607,-0.383316,0.507084,-0.938861,0.413137,0.695833,0.346720,-0.655613,0.627589,0.186087,0.344227,-0.431229,-0.042405,0.490292,0.147987,0.417375,0.200784,0.151171,0.227826,-0.219705,-0.301674,0.531707', '1307442', '4301278', '1301022', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26356789', '心房客', '剧情', '故事发生在一幢破旧的老式公寓之中，少年查理（朱尔·本切特 Jules Benchetrit 饰）的对门搬来了一位名叫珍妮（伊莎贝尔·于佩尔 Isabelle Huppert 饰）的新邻居，珍妮曾是一名红极一时的女演员，如今已经过气。查理决定帮助珍妮获得一个对珍妮来说十分重要的角色。某日，一位名叫约翰（迈克尔·皮特 Michael Pitt 饰）的宇航员因为轨道计算错误而在误打误撞之中降落到了公寓的楼顶，他敲响了独居老人哈密达（Tassadit Mandi 饰）家的门，和老人开始了一段为期三天的奇妙的同居生活。孤独的男子伯科威茨（古斯塔弗·德·科文 Gustave de Kervern 饰）因为意外而坐上了轮椅，在外出购物之时邂逅了正在抽烟休息的女护士（瓦莱丽亚·布诺妮-泰特琪 Valeria Bruni Tedeschi 饰），伯科威茨谎称自己是一名周游世界的摄影师，想要为护士拍一张照片。', '迈克尔·皮特', '萨米埃尔·本谢特里', 8.5, 73101, 'tt4357368', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2312758560.jpg', 0.2, 0.9, 11.7, 47.8, 39.4, '0.394469,0.019670,-0.513547,0.468259,-0.059104,-0.452708,0.983783,0.347590,-0.407553,-0.560608,0.293423,0.787373,-0.262553,0.519057,0.722740,0.279615,-0.333568,-0.429850,0.023367,-0.395569,-0.561219,-0.428452,-0.126714,-0.239783,-0.097643,-0.383342,0.389428,-0.164003,-0.086305,0.468354,0.309692,0.449543,-0.076776,0.276158,-0.209130,-0.080937,0.284877,-0.162914,-0.225660,0.114205,-0.035493,-0.260606,-0.036544,0.061304,0.068592,0.322754,0.721821,-0.255216,-0.036126,0.076153,0.205619,0.198748,-0.012413,-0.012808,0.400971,0.054100,0.148759,0.238209,-0.247223,-0.001385,0.131412,-0.412955,-0.407819,0.180422,-0.098768,0.276525,-0.461913,0.556163,-0.246464,-0.042861,0.066605,-0.336595,0.104968,0.322800,0.012231,0.376208,0.056887,0.156320,-0.422139,0.119608,0.393417,-0.011754,-0.037915,0.773990,-0.133428,-0.226302,-0.033629,0.054890,-0.636313,-0.142074,0.249911,-0.243807,0.118376,-0.230776,-0.529988,-0.112136,-0.495701,0.022803,-0.027607,-0.055703,-0.325708,-0.736546,-0.090014,-0.250302,-0.045109,0.018108,-0.108036,-0.096700,0.581173,-0.652515,0.302383,0.382107,0.132640,-0.109085,0.768824,-0.129697,0.293279,-0.211418,-0.083831,0.401027,0.052905,0.241595,-0.027105,0.528543,-0.120813,-0.279853,-0.342488,