INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26357307', '花木兰', '动作', '迪士尼影业荣誉出品《花木兰》由备受赞誉的电影导演妮基·卡罗执导，将中国传奇战士的史诗故事全新呈现。影片讲述了一位无所畏惧的年轻女子义无反顾为家国而战，成为中国史上最著名的伟大勇士之一。当皇帝下令境内每个家庭必须有一位男丁应召出征，抵御北方来犯者入侵，出身军戎之家的长女花木兰，挺身而出，替病痛缠身的父亲应征入伍。她女扮男装化名“花军”，一路历经磨练，驾驭自己内心的力量，激发真正的潜能。通过这段传奇历程，她将成为一名光荣的勇士，不仅赢得国家的认可，更博得父亲的骄傲。', '刘亦菲', '妮琪·卡罗', 4.9, 310343, 'tt4566758', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2590336843.jpg', 17.9, 37.7, 32.6, 7.7, 4.1, '-0.398816,0.092835,-0.261237,0.758630,0.102944,0.053760,0.264473,-0.223611,-0.361201,-0.491457,0.622817,0.947177,0.205206,0.131466,0.508559,-0.357068,0.186169,-0.374990,-0.191720,-0.083387,-0.014363,0.092501,-0.496220,0.006656,-0.419744,-0.697865,1.096513,0.033158,-0.496027,0.290804,0.353633,0.401542,0.248012,-0.017807,-0.090509,-0.134288,0.033685,-0.069918,-0.452947,0.149824,-0.354971,-0.165653,-0.087320,0.145890,-0.290086,-0.086462,0.467868,-0.571396,0.294363,-0.525234,0.794579,-0.335301,0.101907,-0.101909,0.133508,0.397133,0.091277,0.297068,0.281332,-0.168696,-0.242451,-0.364653,-1.197247,-0.422817,0.492238,-0.202926,-0.664168,0.272894,0.035983,-0.075597,0.174634,-0.195490,-0.067401,0.333670,0.209534,0.417201,-0.110956,0.297021,-0.427450,0.645234,0.829386,-0.185072,-0.447763,-0.053472,-0.235327,-0.414996,0.251918,-0.878325,-0.702836,0.077422,0.081228,-0.082944,0.455335,0.336228,-0.426944,-0.067111,-0.327093,-0.175635,0.427996,-0.318512,0.087116,-0.499106,-0.285865,-0.062065,0.078740,-0.103133,0.295465,-0.517967,1.275599,-0.584010,0.005111,0.343414,0.205310,-0.768374,0.585667,0.143088,0.341606,-0.239530,-0.082973,0.751466,0.293545,0.047849,-0.269414,0.044817,-0.507453,-0.067607,-0.320072,0.427679', '27602116', '24284209', '3001114', '30391300');
