INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26359235', '克里斯托弗·罗宾', '喜剧', '罗宾（伊万·麦克格雷格 Ewan McGregor 饰）曾经也是一个拥有着很多奇异朋友的天真无邪的小男孩，但如今，已经长大成人的他在旅行箱公司上班，在挖空了心思完成上司布置的任务外，他还得想方设法的挤出时间来陪伴妻子伊芙琳（海莉·阿特维尔 Hayley Atwell 饰）和女儿玛德琳（勃朗特·卡迈克尔 Bronte Carmichael 饰）。罗宾非常爱自己的家人们，但这样的生活难免让他感到有一丝丝的窒息。一天，罗宾童年时候的玩伴小熊维尼（吉姆·库宁斯 Jim Cummings 配音）忽然再度出现在了他的眼前，并且请求他帮自己一个忙。很显然，维尼依然将罗宾当成是以前那个单纯的男孩，这让罗宾感到有些无所适从。©豆瓣', '伊万·麦克格雷格', '马克·福斯特', 8.1, 38273, 'tt4575576', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2523016274.jpg', 0.4, 2, 21.2, 43.9, 32.5, '0.133059,0.024186,-0.668859,0.688680,-0.411101,-0.450982,0.938768,0.156858,-0.487556,-0.462671,0.095122,0.770185,-0.113628,0.531277,0.278723,0.119827,-0.330113,-0.503925,0.008742,-0.176329,-0.195049,-0.447575,-0.245676,-0.318936,-0.191674,-0.321566,0.469424,-0.101990,0.204296,0.356437,0.184225,0.228435,0.188062,0.647171,-0.200371,0.089588,0.111701,-0.100867,0.177054,0.084392,0.243383,0.081543,-0.187692,0.419338,0.024443,0.442009,0.582394,-0.149217,-0.213922,-0.018536,0.263346,-0.225267,0.060846,-0.013334,-0.023376,-0.159093,0.107361,-0.194279,-0.326182,0.053901,0.319375,-0.088300,-0.733379,0.135595,0.024236,0.157330,-0.629572,0.180459,-0.243096,0.065820,0.194295,-0.486064,0.084214,0.350338,0.130304,0.396645,-0.296588,0.254259,-0.642389,-0.007057,0.526332,0.022420,-0.221516,0.422415,-0.462022,-0.392067,-0.049471,0.062915,-0.704635,0.020271,0.206115,-0.058285,-0.233299,0.259078,-0.575567,-0.050757,-0.209148,-0.109272,-0.031535,-0.624747,0.086244,-0.550056,-0.149888,-0.528624,-0.428997,-0.289750,-0.095562,-0.441378,0.678198,-0.877619,0.215468,0.667601,0.101691,-0.063919,0.658581,0.300146,0.086195,-0.244307,-0.152422,0.377937,0.002823,0.056220,0.205945,0.443900,0.087314,-0.165576,-0.390364,0.782475', '1292062', '24756472', '1309172', '4058933');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26359246', '灵偶契约', '恐怖', '在英国郊外某个安静的角落，耸立着豪华考究的别墅。这幢别墅属于年迈的希夏尔先生（吉姆·诺顿 Jim Norton 饰）和希夏尔太太（黛安娜·哈卡索 Diana Hardcastle 饰）夫妇。这一天，别墅迎来了一个年轻女孩。女孩名叫格丽塔（劳伦·科汉 Lauren Cohan 饰），因某些原因他希望逃离之前的生活，同时也是受雇于希夏尔完成一项奇怪的工作。希夏尔夫妇即将外出度假，他们要求格丽塔在此期间照顾他们的“儿子”布拉姆斯——一个男孩模样的人偶。格丽塔起初感到好笑，但看到夫妇俩一本正经的模样也便尽可能控制自己的好奇心。夫妇为格丽塔规定了不可逾越的条款，但是当他们离开后，格丽塔却最终逾越了戒条。令她难以置信的是，布拉姆斯仿佛真的拥有鲜活的生命……©豆瓣', '劳伦·科汉', '威廉·布伦特·贝尔', 6.2, 12776, 'tt3882082', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2327655150.jpg', 2.8, 16.9, 55.1, 19.9, 5.3, '0.099449,0.066783,-0.702194,0.278119,-0.137102,-0.294582,0.927955,0.313135,-0.513439,-0.432280,0.450313,0.833218,-0.040331,0.357064,0.233383,0.102649,-0.296319,-0.213390,-0.019502,-0.177081,-0.010483,-0.494942,-0.144797,-0.359991,0.169540,-0.409978,0.495799,0.126249,0.009397,0.528042,0.142365,0.211185,-0.202858,0.327577,-0.203168,-0.140589,0.275330,0.054982,-0.151433,-0.117929,-0.135617,0.091616,-0.103372,0.249286,0.101186,0.448875,0.569973,-0.074914,-0.530519,0.064371,0.218998,-0.105227,-0.062098,0.207497,0.066238,-0.108211,0.225683,0.098462,-0.269886,-0.099211,0.081284,-0.076136,-0.611414,0.092938,0.245563,0.097789,-0.507136,0.534938,-0.103036,-0.240881,0.052170,-0.405009,0.348796,0.261590,0.203585,0.585071,-0.111957,0.140084,-0.558099,-0.052549,0.500206,-0.003795,-0.314557,0.327343,-0.500296,-0.419006,0.111083,-0.176604,-0.508398,0.068997,0.095057,0.120485,-0.006786,-0.140486,-0.462536,0.006439,-0.284718,0.005186,-0.056850,-0.655923,-0.112708,-0.565615,0.114644,-0.322961,-0.238315,-0.020290,-0.087522,-0.207714,0.541653,-0.597527,0.305642,0.340972,0.403995,-0.447401,0.722591,0.074496,0.307571,-0.163032,0.001646,0.357269,-0.058268,0.208569,-0.117585,0.307426,-0.058402,-0.114367,-0.353500,0.429239', '3055049', '1292211', '3111650', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26359269', '诺亚方舟漂流记', '喜剧', '世纪之末，一场突如其来的洪水即将席卷Griffin岛。动物们在狮子领袖的带领下登陆一艘空前绝后的大船——诺亚方舟，不过不是所有动物都可以登上方舟。戴夫和芬尼是对呆萌可爱的喜欢旅行的父子俩，由于未在名单内，父子俩被禁止登陆方舟。为了躲避洪水，父子俩只好乔装打扮成小金狼 ，混上了方舟。却乌龙巧合的遇到了金狼母女海泽尔和利亚。好不容易蒙混过关，以为已相安无事，但两个好奇的小宝贝却不慎跌出船外。于是，芬尼和利亚开始了一场寻亲之旅。期间，两个孩子从冤家变成朋友，用勇气和友情战胜洪水和野兽的袭击。与此同时，戴夫和海泽尔为了营救他们的孩子也在和傲慢的狮子船长斗智斗勇……', '卡勒姆·马洛尼', '托比·格恩科尔', 7.4, 5278, 'tt3411432', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2369494747.jpg', 0.7, 3.6, 35.3, 43.1, 17.3, '0.368960,-0.143369,-0.801623,0.440227,0.043419,-0.123030,0.824389,-0.142809,-0.422796,0.192730,0.264990,0.745400,-0.231559,0.040842,0.181346,-0.193113,-0.359227,-0.596720,-0.175542,0.043633,-0.151904,-0.366182,-0.280980,0.012430,0.069041,-0.528168,0.579139,0.069168,0.018656,0.681953,0.288990,0.169725,-0.413891,0.435410,-0.305249,-0.013083,0.024387,0.244923,-0.191392,0.237966,-0.204439,0.115347,-0.166033,0.160828,0.108160,0.241867,0.686608,-0.623870,0.006696,-0.192443,-0.199534,-0.527434,0.014570,0.183583,0.530993,-0.259060,0.359637,-0.030044,-0.106836,0.057288,0.198508,0.103268,-0.461979,0.173886,-0.038729,0.125953,-0.640845,0.450364,0.039585,-0.144844,0.207140,-0.232726,0.039442,0.571384,0.225372,0.576175,-0.078342,0.248431,-0.632068,-0.152742,0.936606,-0.033674,-0.287288,0.353923,0.197541,-0.318445,0.156961,-0.360699,-0.295968,-0.104087,0.385135,0.022377,-0.453666,0.348270,-1.009179,0.258867,-0.539295,-0.309505,-0.059836,-0.673736,-0.257043,-0.715465,0.082043,-0.336183,0.102793,0.349897,0.158991,-0.222700,0.682738,-0.816310,0.200541,0.521793,0.178490,-0.374259,0.588760,0.166517,-0.017775,-0.181593,0.252158,-0.270580,0.015813,0.433030,0.316008,0.385591,0.056763,-0.151354,-0.358242,0.389533', '3626364', '1298694', '11541282', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26361257', '正义联盟：神魔之战', '动作', '本片是完全原创故事，超级英雄们不再是熟悉的样子，超人成为了佐德的儿子，蝙蝠侠成为吸血鬼，神奇女侠是“新神”，正义联盟为了摆脱被诽谤的罪名对科学家遇害事件展开调查。', '本杰明·布拉特', '刘山姆', 7.8, 8256, 'tt4324302', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2256377582.jpg', 0.6, 2.6, 25.5, 47.7, 23.6, '0.248214,-0.087605,-0.108542,0.085141,-0.162720,0.283822,0.508152,-0.350660,-0.804929,-0.332576,0.264988,0.843830,-0.293458,0.116896,-0.073542,-0.064694,-0.263932,-0.845065,-0.102054,-0.167366,0.214797,-0.572460,-0.304259,-0.362688,-0.002855,-0.831427,1.015655,0.039858,-0.805649,-0.115392,0.792767,0.742356,-0.165431,0.047399,-0.213642,-0.045297,0.287866,-0.397536,-0.568586,0.429746,-0.308840,-0.004062,0.058816,0.426435,-0.594962,-0.203577,0.461916,-0.726172,-0.261652,-0.519667,0.635682,-0.794415,-0.284431,-0.040141,0.462222,0.203059,0.176220,0.515464,0.613145,-0.228487,0.000491,-0.289915,-1.152967,-0.135815,0.372817,0.261872,-0.519760,-0.045615,-0.317918,-0.289977,0.498663,-0.177650,0.360357,-0.348666,0.904755,0.409857,0.255605,0.475760,-0.654184,0.217315,0.720377,0.427255,-0.284344,0.078965,0.049219,-0.562009,-0.145641,-0.824617,-0.103904,0.395305,-0.041405,-0.210150,0.211852,0.780188,-0.528726,-0.184984,-0.437691,-0.108666,0.056720,-0.507383,-0.061220,-0.335759,-0.399876,0.061723,-0.033491,-0.200718,-0.060403,-0.786424,1.183555,-1.133110,0.199090,0.531355,0.131694,-0.913956,0.691542,0.309282,-0.176109,-0.466296,-0.095213,0.005682,0.125862,0.098425,0.143668,-0.278434,-0.092533,-0.436393,-0.140103,0.358129', '27602116', '3718665', '24284209', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26362351', '濑户内海', '剧情', '在这个故事里，濑户内海并非地名，而是大阪某男子高中二年级两个男生的名字。濑户小吉（菅田将晖 饰）身形瘦弱高挑，他曾是足球部的一员，但因和前辈关系不睦而退出社团。内海想（池松壮亮 饰）文质彬彬，沉默寡言，却也并非只知道读书的书呆子。不知为何，这两个看起来完全没有交集的“回家部”成了朋友。每当下午放学后，他们便相约来到河边坐下。在内海去补习班前的这段时间里，两个人便海阔天空地闲聊起来。他们的话题无所不包，却又无聊空洞。当那个妖精一般的女孩樫村一期（中条彩未 饰）出现时，不经意间在木讷的大男孩心间激起波澜……本片根据此元和津也的同名漫画改编。©豆瓣', '池松壮亮', '大森立嗣', 8.3, 97000, 'tt4934870', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2318231103.jpg', 0.4, 1.7, 16, 46.4, 35.5, '0.535710,-0.040133,-0.738912,0.394051,0.009271,-0.467194,0.945020,0.158059,-0.366291,-0.423992,-0.222178,0.743217,-0.244448,0.389706,0.222519,0.112321,-0.301625,-0.670345,-0.194856,-0.399220,-0.078006,-0.274416,-0.128199,0.028448,-0.071588,0.026592,0.548612,-0.094541,-0.287709,0.728684,0.408481,-0.037261,-0.201442,0.450473,-0.248448,0.093293,-0.055325,0.363319,0.243674,-0.016972,-0.207398,-0.129971,-0.475350,-0.114686,0.162966,0.404716,0.650490,-0.006192,-0.138176,0.027890,0.092534,0.094829,-0.251702,0.042839,0.588749,0.057775,0.458659,0.029744,-0.128594,0.126091,-0.071513,-0.249649,-0.225266,0.281026,0.064927,0.549212,-0.308324,0.568785,0.144713,-0.399825,0.110540,-0.203161,0.010403,0.102236,0.318574,0.354832,-0.043185,0.046186,-0.134593,0.091577,0.593399,0.248097,-0.328468,0.362007,-0.039366,-0.435955,-0.038060,0.071836,-0.043127,-0.036472,-0.045565,-0.135600,-0.106422,0.071219,-0.549053,0.230627,0.096911,0.288125,-0.198555,-0.194292,-0.217264,-0.483549,0.137032,-0.413947,-0.317928,0.337232,0.107209,0.115491,0.748828,-0.887021,0.131745,0.483163,0.247611,-0.189170,0.636208,0.261589,0.052216,-0.419011,-0.027480,-0.015168,0.063272,0.325920,-0.076564,0.584786,-0.229452,-0.178631,-0.541032,0.346926', '1296534', '1292219', '1296332', '1915403');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26362764', '真实', '动作', '影片讲述亚洲最大规模赌场巨大的阴谋与战争，“和我长得一样的人出现了”。SIESTA赌场开业前，出现在组织老大张泰英（金秀贤饰）面前的暗黑组织老大曹源根（成东镒饰）主张自己拥有赌场的所有权，陷入赌场抢夺危机的张泰英为了解决危机去拜访了投资者。某天，不仅是姓名连外貌也一样的可疑投资者（金秀贤饰）出现了并提出把曹源根一起解决的方案。随着可疑投资者的登场，与曹源根之间争夺赌场的战争开始了，围绕着他们的巨大秘密和阴谋渐渐浮出水面。', '金秀贤', '李沙朗', 4.8, 24923, 'tt6904062', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2460120821.jpg', 20.2, 39.4, 25.3, 9.2, 5.8, '0.333584,0.127557,-0.678785,0.265569,0.188908,-0.018071,0.692382,0.200494,-0.404521,-0.120558,0.310296,0.780316,-0.187946,-0.002086,0.320033,-0.302033,-0.296659,-0.862885,-0.441907,-0.119526,-0.220174,-0.495985,-0.211823,-0.297933,0.087073,-0.262938,0.536142,0.269016,-0.436326,0.416613,0.455377,0.189737,-0.331206,0.507862,-0.059676,-0.396265,-0.115136,0.127848,-0.542467,0.398158,-0.256724,0.005695,0.057559,0.169925,0.015383,0.376486,0.580188,-0.485963,-0.234885,-0.206321,0.413354,-0.443562,-0.047337,0.096631,0.435804,0.114072,0.176115,0.434657,-0.238539,-0.203605,0.044020,-0.348808,-1.005056,0.110062,0.077182,0.432682,-0.523567,0.048681,0.314269,0.046794,0.111032,-0.155189,0.439377,0.656797,0.491676,-0.085888,-0.164978,0.117917,-0.717690,-0.037419,0.667924,-0.136644,-0.121371,-0.105367,-0.085511,-0.320765,-0.275834,-0.262732,0.154427,-0.010617,0.301380,-0.068369,-0.168852,0.325437,-0.885407,0.069223,0.093127,-0.570079,0.306392,-0.398815,-0.155608,-0.877349,-0.479559,-0.090725,-0.393205,0.222392,-0.029014,-0.062588,0.639678,-1.081009,0.002156,0.797360,0.673829,-0.518866,0.821002,-0.065277,-0.006674,-0.412839,-0.390929,-0.149049,0.126544,0.307856,-0.274972,0.050055,-0.028856,-0.136987,-0.160829,0.281543', '1498811', '1793491', '4301278', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26362770', '道士出山', '剧情', '自幼跟随爷爷学习茅山道术的阴十三和史胖子是一对好朋友，他们俩混迹于茅山术吧，十三经常发一些他降妖除魔的事情，只不过很少有人相信罢了。某天他们应邀来到某女子家，对方家里挂紧窗帘，因为一拉开窗帘她就感到有人勒脖子。好不容易解决了这单，他们又被卷入另一起事件。同校女孩穆然一周前经历一场车祸，她的好友蓝珊在车祸中死去，穆然郁郁寡欢，而死去的蓝珊似乎充满怨气，要把朋友也拉入阴间。十三和胖子救下了穆然，回程途中遇到胖子同村的青年大雄、小雄，两人身上浓重的尸气让十三顿感不妙。为了一探究竟，好兄弟和穆然朝向了恶鬼横行的村庄……©豆瓣', '彭禺厶', '张涛', 5, 2943, 'tt4595054', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2237387279.jpg', 22.9, 29.7, 31.2, 9.1, 7.2, '0.287214,-0.437921,-0.436413,0.193310,0.082116,-0.249266,0.591408,0.006065,-0.530372,-0.277219,0.280610,0.805967,-0.187730,0.306756,0.269273,-0.040923,-0.070087,-0.674352,-0.113279,-0.162929,-0.383802,-0.203661,-0.104978,-0.022142,-0.016394,-0.198372,0.385695,-0.033116,-0.071033,0.591720,0.138330,0.331333,-0.398924,0.422421,-0.133902,0.183311,-0.147481,0.094958,-0.100647,0.041335,0.023108,-0.121832,-0.236473,0.110305,0.100608,0.207605,0.523105,-0.013145,-0.151887,-0.146022,-0.124343,-0.090486,-0.357425,-0.098802,0.378527,0.001881,0.578491,0.374091,-0.041838,-0.165895,0.013375,0.103026,-0.287759,0.379488,-0.012186,-0.139956,-0.612562,0.170007,0.073714,-0.047936,0.070401,-0.374366,0.149623,0.368050,0.149903,0.204738,-0.166784,-0.044307,-0.416900,-0.063652,0.744978,-0.176747,0.101208,0.234635,0.018284,0.013955,0.047374,0.012539,-0.301840,0.120500,0.514548,-0.212415,-0.455972,0.288204,-0.461962,-0.044094,-0.269075,0.153927,-0.035289,0.028831,-0.162600,-0.204422,-0.216506,-0.319877,-0.345398,-0.105390,0.139338,-0.159816,0.555703,-0.729749,0.308230,0.386437,0.174763,-0.336613,0.581359,-0.011888,0.285746,-0.207707,-0.150029,-0.271559,-0.018458,0.511563,0.457969,0.350528,-0.111234,-0.040218,-0.241120,0.131015', '1292219', '1308755', '25721544', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26363201', '救命解药', '悬疑', '洛哈特（戴恩·德哈恩 Dane DeHaan 饰）被派往位于阿尔卑斯山的一间疗养院中，接回在此疗养的公司CEO。在回程的路上，洛哈特遭遇了车祸，左腿骨折，无奈之下，他只得在疗养院中暂时停留养病。在疗养院中，洛哈特结识了神秘的少女汉娜（米娅·高斯 Mia Goth 饰）。疗养院中诡异的气氛和洛哈特周围发生的接二连三的科学无法解释的事件让洛哈特开始对疗养院的经营性质产生了怀疑。汉娜和主治医生福尔摩（詹森·艾萨克 Jason Isaacs 饰）之间的暧昧关系更让洛哈特察觉到事件的不单纯。终于，洛哈特识破了隐藏在这间疗养院之中的秘密，与此同时，他的噩梦也开始了。©豆瓣', '戴恩·德哈恩', '戈尔·维宾斯基', 7.1, 31037, 'tt4731136', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2460790542.jpg', 1.2, 6.1, 41.1, 39, 12.6, '0.567895,0.054136,-0.907837,0.719503,0.233101,0.026712,1.143066,0.026253,-0.581148,-0.508186,0.046723,0.700674,-0.363585,0.779325,0.659404,0.062541,-0.177090,-0.627718,-0.172732,-0.311368,-0.722198,-0.867953,-0.316754,-0.620707,-0.043865,-0.188048,0.130609,0.638111,-0.282478,0.467442,0.119199,0.794339,-0.312754,0.899953,0.025628,0.119156,0.228279,-0.169807,0.141200,0.143030,0.616054,-0.481835,0.063481,0.527983,0.546354,0.534576,0.734865,-0.506379,0.129990,0.026863,0.179491,-0.154029,0.320730,0.025880,0.377799,-0.133194,-0.060925,0.140683,-0.442409,0.158103,0.095837,-0.107310,-0.371941,0.136306,0.200639,0.068948,-0.797112,0.408258,-0.063695,0.132530,-0.092905,-0.080556,0.479630,0.310561,0.390764,0.238194,-0.060524,0.010142,-0.453751,-0.320613,0.394877,0.015849,-0.354795,0.292616,-0.380575,-0.563787,-0.467327,0.290499,-0.254333,-0.347694,0.612205,-0.067837,0.153837,0.242727,-0.272562,-0.475344,-0.347230,-0.289982,-0.451624,-0.152522,-0.082201,-0.714608,0.054690,-0.404136,-0.174269,0.073602,-0.262956,-0.188793,0.019236,-0.793172,0.043482,0.233304,0.099713,-0.338277,0.519462,-0.377795,0.429435,0.185143,-0.122223,0.651586,0.254770,0.218604,0.451454,0.606744,-0.127254,-0.006256,-0.399246,0.530412', '21348112', '1421570', '3011051', '1300958');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26363254', '战狼2', '动作', '由于一怒杀害了强拆牺牲战友房子的恶霸，屡立功勋的冷锋（吴京 饰）受到军事法庭的判决。在押期间，亲密爱人龙小云壮烈牺牲。出狱后，冷锋辗转来到非洲，他辗转各地，只为寻找杀害小云的凶手。在此期间，冷锋逗留的国家发生叛乱，叛徒红巾军大开杀戒，血流成河。中国派出海军执行撤侨任务，期间冷锋得知有一位陈博士被困在五十五公里外的医院，而叛军则试图抓住这位博士。而从另一位华侨（于谦 饰）口中得知，杀害小云的凶手正待在这个国家。在无法得到海军支援的情况下，冷锋只身闯入硝烟四起的战场。不屈不挠的战狼，与冷酷无情的敌人展开悬殊之战……©豆瓣', '吴京', '吴京', 7.1, 859989, 'tt7131870', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2494701965.jpg', 5.9, 9.3, 29.8, 32.5, 22.5, '0.037195,-0.078671,-0.751559,0.455184,0.123231,-0.004198,0.518681,-0.003133,-0.311672,-0.195470,0.609801,0.425557,0.280481,-0.002440,0.467563,-0.229255,-0.090358,-0.735336,-0.244497,-0.143502,-0.287325,-0.535684,-0.228990,-0.341920,0.107439,-0.194612,0.884485,0.199448,-0.311535,0.568643,0.272349,0.508834,-0.384500,0.417684,-0.269355,-0.086107,0.373197,-0.064296,-0.499954,0.421875,-0.181074,-0.316457,-0.157100,0.024164,-0.219427,0.418740,0.627511,-0.225539,-0.151030,-0.172875,0.236463,-0.471908,0.025373,-0.029313,0.727231,0.037149,-0.081555,0.414330,-0.114668,0.052919,-0.127859,-0.010252,-0.598083,-0.178705,0.136157,0.134645,-0.419676,0.379265,-0.291375,0.201859,0.171157,-0.273801,0.215643,0.844952,0.050394,0.240918,-0.328686,0.063711,-0.609090,0.064481,0.758285,-0.341773,0.048281,-0.404444,0.233310,-0.273663,0.318467,-0.343459,-0.066429,0.107841,0.265386,-0.162696,-0.146001,0.276460,-0.406593,-0.196697,-0.420458,-0.307848,0.105263,-0.061120,-0.385179,-0.792263,-0.117932,0.040297,-0.136687,0.279547,0.011060,-0.033011,0.489465,-0.726755,0.119802,0.432717,0.345516,-0.792446,0.360085,0.265559,0.177986,-0.085024,-0.078545,0.396093,0.557176,0.557749,0.075706,-0.182613,-0.155796,-0.239614,-0.179699,-0.164639', '4193254', '5157137', '2369613', '3074408');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26363987', '你能原谅我吗？', '剧情', '李（梅丽莎·麦卡西 Melissa McCarthy 饰）曾是一位小有名气的传记作家，所撰写的作品屡屡进入畅销榜。然而，李是一位个性非常固执的作家，她不愿意为了迎合市场而改变自己的创作风格，久而久之，再也没有出版社愿意同她合作了，李的生活渐渐的陷入了窘迫之中。入不敷出的李决定卖出自己珍藏多年的著名影星凯瑟琳赫本的信件，由此获得了一笔不菲的收入，之后，她又在机缘巧合下得到了另一位名人的信件，在经过了精心的改造后，这封信件自然也卖出了个好价钱。梅开二度让李发现了商机，她就此踏上了伪造名人信件牟利的不归路。©豆瓣', '梅丽莎·麦卡西', '玛丽埃尔·海勒', 7.2, 9143, 'tt4595882', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2516537208.jpg', 0.7, 3.8, 41.2, 43.3, 11, '0.142011,0.479963,-0.685337,1.016324,0.003787,-0.450305,0.630543,-0.027077,-0.467833,-0.408792,0.141937,0.762167,-0.192221,0.249459,0.147005,-0.222999,-0.085170,-0.578507,-0.012370,-0.558027,-0.392521,-0.217334,-0.564989,-0.317726,-0.553789,-0.077956,0.778724,0.284643,-0.439386,0.164122,0.490887,0.288880,0.358711,0.444541,-0.273011,0.203649,0.172075,0.350058,-0.064475,0.237621,0.145515,-0.644176,-0.131938,0.124450,0.362934,0.308186,0.649983,-0.336966,-0.203973,0.286022,0.670775,-0.028889,-0.014470,-0.121059,0.090735,0.149765,0.070661,-0.190842,-0.568508,-0.172257,-0.034284,-0.177054,-0.742799,-0.270254,0.164515,0.159895,-0.808775,0.175240,-0.343704,0.087382,-0.391118,-0.542255,0.010521,0.470336,0.482460,0.121578,0.289956,0.283090,-0.572973,0.687672,0.485711,0.335845,-0.274132,0.336515,-0.560105,-0.780799,0.056871,-0.368372,-0.452624,0.128221,0.806444,-0.018678,0.263904,0.044412,-0.673383,-0.269944,-0.128728,-0.274446,0.209001,-0.379125,0.070835,-0.526830,-0.436620,-0.198749,-0.024219,-0.117661,0.024190,-0.571515,0.999552,-0.610967,0.202078,0.210703,-0.049786,-0.776347,0.813545,-0.056987,0.002384,-0.113429,0.163512,0.106494,0.303628,0.403932,0.346227,0.355452,0.233617,-0.449545,-0.284237,0.716073', '27602116', '22265121', '2027945', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26365022', '完美音调3', '喜剧', '《完美音调3》是系列影片《完美音调》的第三部，主要讲述了发生在《完美音调2》之后的故事，贝拉组合在毕业后再战大舞台。然而曾经风光一时的她们如今日子过得也并不顺利，潦倒的合唱团姐妹们一事无成，生活的不如意，工作的不顺心让姐妹们更加急切想要表现自己，重新获得辉煌。趁着美国劳军协会将在欧洲举办劳军表演，大家决定团结起来，争取获得表演的邀请，然而时过境迁她们仿佛不再受欢迎，为了重回大众视野，也为了证明自己，姐妹们必须放手一搏。', '安娜·肯德里克', '翠西·西埃', 6.2, 10181, 'tt4765284', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2467159410.jpg', 2.6, 20.3, 51.2, 17.2, 8.8, '-0.118525,0.019832,-0.560495,0.386716,-0.019184,-0.072457,0.317296,0.081665,-0.339978,-0.238269,0.041851,0.620807,-0.210398,0.251491,0.197967,-0.445638,-0.435838,-0.795216,0.131957,-0.027044,0.179782,-0.365909,0.171801,-0.416674,-0.250660,-0.365384,0.890653,0.088823,-0.120394,0.393176,0.168580,-0.082042,0.061863,0.072563,-0.282369,-0.331219,0.191872,0.330060,-0.680524,0.094765,-0.168766,-0.177746,-0.548844,0.127510,0.428854,-0.014245,0.723658,-0.113396,-0.333531,0.255913,0.589794,-0.134889,0.038275,0.125567,-0.040454,0.179411,0.261793,0.368560,-0.016665,-0.054171,-0.215995,-0.561930,-1.036291,0.432346,0.252619,-0.176692,-0.277158,0.395258,0.141166,-0.050503,0.290483,-0.224424,0.273850,0.622900,0.549831,0.124126,-0.231233,0.363288,-0.258965,0.581490,1.149239,0.046981,-0.474928,0.437885,-0.114249,-0.348583,-0.035195,-0.591798,-0.221876,0.263646,0.166476,0.351333,-0.014006,0.312019,-0.457176,-0.016833,-0.054175,-0.563032,0.317078,-0.543673,0.208298,-0.879045,-0.314488,-0.217876,-0.251888,-0.242281,0.030887,-0.401603,1.008146,-0.806691,0.190552,0.398800,0.165087,-0.816268,0.569414,0.301478,0.310133,-0.052847,-0.100842,0.080129,-0.233082,0.106067,0.133331,0.106076,-0.196221,-0.065568,-0.454460,0.437509', '26678784', '27602116', '4301278', '1308424');
