INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26365262', '花牌情缘 上之句', '剧情', '樱花飞舞的都立瑞泽高中，迎来了热爱花牌的女孩绫濑千早（广濑丝丝 饰）。小学时代，千早受转学生绵谷新（真剑佑 饰）的影响接触了花牌竞技，从此便一发不可收拾。进入高中后，她重逢了当年与她、绵谷一同参加比赛的真岛太一（野村周平 饰），于是两人联手创立了竞技花牌部。除她们二人外，还有大江奏（上白石萌音 饰）、西田优征（矢本悠马 饰）、驹野勉（森永悠希 饰）等成员参加。大家通力合作，一步步朝着全国大赛的目标前进，然而挡在他们前方的，则是有着悠久竞技花牌历史的名门学校北央学园，强大的对手毫不留情对这支成立不久的战队进行了碾压。在此期间，千早得到了绵谷的消息，她满心欢喜，期待这位与久别的好友再度走上竞技花牌的赛场……本片根据末次由纪的同名漫画改编。©豆瓣', '广濑铃', '小泉德宏', 7.3, 16303, 'tt4785440', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2326121380.jpg', 0.6, 3.8, 37.3, 44.1, 14.2, '0.187543,-0.006648,-0.471377,0.527416,0.247295,-0.108047,0.033972,0.034826,-0.229286,-0.057671,0.303956,0.747519,-0.485100,0.135245,0.315835,-0.189697,-0.078675,-0.816963,-0.046468,-0.314728,-0.222026,-0.213633,0.023600,-0.026706,-0.124255,-0.143145,0.815175,-0.016895,-0.262414,0.995610,0.308201,0.119961,-0.129223,0.100691,0.066313,-0.054984,0.097007,0.285040,-0.276002,0.249161,-0.311908,-0.267453,-0.397499,-0.098202,0.309181,0.166587,0.732675,-0.213264,0.191830,-0.147641,0.293155,-0.212397,-0.188567,0.165027,0.599818,0.220531,-0.070923,0.294223,0.027731,0.077055,-0.280220,-0.352244,-0.256993,0.163767,0.108155,0.164172,-0.322614,0.671244,-0.078063,-0.237987,0.207923,0.016458,0.051668,0.384388,0.263108,0.039917,-0.159940,0.073603,-0.000932,0.302171,0.605587,-0.089474,-0.222896,-0.002572,-0.049277,-0.399373,-0.151849,-0.118707,-0.187776,0.056393,0.443458,0.157565,0.224465,-0.029381,-0.713191,0.087621,0.134776,-0.249155,0.250094,-0.190230,0.079109,-0.938813,0.022867,-0.361436,-0.337336,0.036080,0.009405,-0.207980,0.837312,-0.858063,0.132056,0.216556,0.338109,-0.257940,0.549415,-0.047016,0.183999,-0.210238,-0.091574,0.110983,-0.142663,0.483986,0.029817,0.531600,-0.128758,-0.253710,-0.234483,0.351882', '3811356', '26784898', '1826173', '3139191');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26365631', '冲天火', '动作', '宗天保任职护卫员的科学园大火，他舍身救了女研究员高玉。但研究所潘教授在大火中不幸辞世，潘教授的手写笔记在大火中消失。大火引发了灰尘风暴，令整个香港被雾霾卷盖。财阀王耀才投资的“天空一号”，让富人得以远离污染，而己故潘教授的助理唐永章变成他的合作伙伴，唐的发妻高玉继续在天空一号上钻研“超能干细胞”的“再生学”工作，完成潘教授的遗愿。从台湾来的家家带着癌症末期的妹妹小珍来香港求医，怎料两兄妹因此卷入一场“超能力干细胞”的劫案中，而偷走这新科研血清的主脑，竟是已故潘教授的独生子子文，在争夺血清的过程中，子文逐渐发现了令父亲潘教授死亡的真正凶手……', '吴彦祖', '林岭东', 3.5, 13173, 'tt6157600', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2394867674.jpg', 45.1, 38, 14.2, 1.9, 0.8, '0.012721,0.144934,-0.495779,0.540919,-0.077135,-0.371990,0.468991,0.062471,-0.521162,-0.624454,0.110347,0.451146,-0.005897,0.390437,0.290202,-0.165720,0.108650,-0.475955,-0.414506,0.028977,-0.657329,-0.343058,-0.074026,-0.482325,-0.078619,-0.328919,0.514533,0.487181,-0.332028,0.177963,0.041215,0.214486,-0.285375,0.242287,-0.132939,0.189798,0.044945,0.073660,-0.246237,0.403493,0.166751,-0.259458,0.110241,-0.136441,0.192782,0.257427,0.806420,-0.218336,0.222201,-0.195046,0.447003,-0.376801,-0.012563,-0.065966,0.649418,0.281874,-0.106679,0.069818,-0.224449,-0.298015,-0.067843,-0.081430,-0.499312,-0.172272,0.127674,0.135584,-0.584451,0.265334,0.235415,0.166240,-0.084913,-0.047145,0.425396,0.144246,-0.002811,0.410672,-0.019600,0.178356,-0.435207,0.620260,0.379244,-0.337325,-0.199387,0.070771,-0.371693,-0.525404,0.119154,-0.233606,-0.297001,-0.123464,0.649255,-0.152489,0.075161,0.373188,-0.540006,-0.206774,-0.329348,0.040286,-0.165805,0.047119,0.020770,-0.538003,-0.105897,-0.022502,0.133606,0.048921,-0.009016,-0.463043,0.494382,-0.661172,0.379303,0.185173,-0.137112,-0.277191,0.445690,0.025791,0.195394,-0.265977,-0.188956,0.096881,0.297422,0.651735,0.176731,0.195871,-0.055657,-0.296654,-0.200185,0.141644', '25912924', '1292829', '1408130', '1808049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26366465', '我的少女时代', '喜剧', '成功白领林真心（陈乔恩 饰）因被上司压迫、下属吐槽，陷入了少女时代的深深回忆。原来曾是平凡少女（宋芸桦 饰）的真心有着一段爆笑却有充满甜蜜的初恋回忆。少女真心曾经暗恋校草欧阳非凡（李玉玺 饰），却总是不敌校花陶敏敏（简延芮 饰）的魅力，令她苦恼不已，一次意外却让她与校霸徐太宇（王大陆 饰）组成了“失恋阵线联盟”，他们势要夺爱，上演了一幕幕生猛、搞笑的青春趣事，而在相处中两人的情感也发生了微妙的变化……若干年后，来到成人世界的林真心又能否重拾初心呢？©豆瓣', '宋芸桦', '陈玉珊', 7.8, 580679, 'tt4967094', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2285115802.jpg', 0.8, 3, 25.1, 45.7, 25.4, '-0.127671,0.234937,-0.655676,0.680238,0.057438,-0.340896,0.966262,-0.066421,-0.851021,-0.131630,0.058242,0.164172,-0.636231,0.329320,0.280234,-0.286544,0.080599,-0.667662,0.056846,-0.104524,-0.130588,0.060572,-0.431538,-0.125515,-0.255660,-0.268437,0.685969,0.179397,-0.309129,0.312290,0.565327,0.401448,-0.230441,0.702536,-0.012841,0.184524,0.102160,0.703087,-0.357673,-0.368105,0.081129,-0.466526,-0.203300,0.233308,-0.117217,0.059245,0.851917,-0.208313,-0.292155,-0.031883,0.481541,-0.173556,-0.156533,-0.041174,0.118839,0.100158,0.161019,-0.084632,0.061478,-0.131886,0.069846,0.008910,-0.314700,-0.050102,0.250216,0.104676,-0.357573,0.442510,-0.112518,-0.045393,0.260129,-0.002490,0.226193,0.168457,0.852593,0.379181,0.053607,0.062504,-0.177785,0.554445,0.763207,0.455787,-0.409529,0.212643,-0.635210,-0.473118,-0.220628,0.053706,-0.612468,0.192297,0.311620,-0.037739,0.217489,0.552658,-0.521286,-0.203309,-0.019796,0.196486,0.069294,-0.875524,0.019112,-0.321062,-0.467701,-0.658221,-0.227661,-0.081995,0.138440,-0.311767,0.745466,-1.047081,-0.057094,0.057799,0.129233,-0.414534,0.428467,0.400784,-0.348706,-0.392554,0.047900,0.662696,-0.237341,-0.069614,0.031563,0.410106,-0.289545,0.264812,-0.428688,0.602287', '3012033', '35030151', '26354526', '1308745');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26366496', '邪不压正', '剧情', '七七事变前夕，华裔青年小亨德勒（彭于晏 饰）从美国远赴重洋，回到阔别十数年之久的北平从医。然而他真正的名字叫李天然，十三岁那年曾亲眼目睹师父一家遭师兄朱潜龙（廖凡 饰）和日本人根本一郎（泽田谦也 饰）灭门。侥幸逃生的天然被美国人亨德勒医生送往大洋彼岸，接受了极其严苛的训练，而今他怀着绝密的任务踏上故土。亨德勒父子租住神秘男子蓝青峰（姜文 饰）的宅子，蓝是当年辛亥革命的参与者，他与现为警察局长的朱潜龙过从甚密，却又以杀死李天然为筹码，暗中怂恿朱除掉根本一郎。复仇心切的李天然寻找到了仇人，而亨德勒医生则全力阻止养子冒险。在这一过程中，交际花唐凤仪（许晴 饰）与裁缝关巧红（周韵 饰）也卷入了男人的勾心斗角的漩涡里。直到七七事变爆发，所有的矛盾迎来了决断的时刻……本片根据张北海的小说《侠隐》改编。©豆瓣', '彭于晏', '姜文', 7, 670236, 'tt8434380', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2526297221.jpg', 2.3, 8.4, 38.3, 36.7, 14.3, '-0.130051,-0.002807,-0.562566,0.653400,0.032268,-0.489597,0.494751,0.032028,-0.550645,-0.472973,0.076898,0.352044,-0.062949,0.197348,0.382074,-0.097725,-0.125623,-0.541472,-0.150824,-0.164437,-0.177531,-0.381900,-0.189962,-0.187354,-0.091098,0.008829,0.557630,0.405772,-0.309012,0.358505,0.401395,0.329157,-0.265880,0.481063,0.147639,0.091633,0.055342,0.109111,-0.348201,0.083030,0.014063,-0.456208,-0.175637,0.062610,0.112865,0.484713,0.499745,-0.288162,0.032728,-0.209052,0.184313,-0.260320,-0.182897,-0.041356,0.405506,-0.140006,0.107693,0.000059,-0.235626,-0.134812,-0.052124,-0.165042,-0.267645,-0.045814,0.360226,-0.047127,-0.507380,0.171153,-0.208671,0.158363,0.021907,-0.318105,0.014959,0.305143,0.116224,0.174718,-0.050867,0.180853,-0.282492,0.409546,0.631926,-0.068607,-0.050022,-0.216428,-0.002437,-0.567988,-0.061427,-0.208690,-0.319811,0.028945,0.389365,-0.128155,0.123244,0.139047,-0.411275,-0.251921,-0.261267,0.180123,0.092634,-0.048470,0.001885,-0.494364,-0.019211,-0.238679,-0.127760,-0.022905,0.067672,-0.310562,0.467939,-0.527547,0.267606,0.154336,0.120908,-0.409342,0.423595,-0.072068,0.108594,-0.385630,-0.080897,0.382289,0.253540,0.391774,0.090607,0.328543,-0.119521,-0.127102,-0.145189,0.381248', '1301022', '25870679', '1300553', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26367579', '火海凌云', '剧情', '本片翻拍自1980年苏联同名经典影片。极富正义感的飞行员古辛（丹尼拉·科兹洛夫斯基 Danila Kozlovsky 饰），因违抗上级命令而被军队开除，成为民航机组的实习飞行员，并结识了精神导师津琴科（弗拉基米尔·马什科夫 Vladimir Mashkov 饰）和恋人亚历珊德拉（阿格尼·格鲁迪特 Agnė Grudytė 饰）。然而，在一次飞行中，突遇的火山爆发、恶劣的天气状况让机上的一切都失去了控制，机上所有成员命悬一线……', '丹尼拉·科兹洛夫斯基', '尼古拉·列别捷夫', 7.7, 25820, 'tt5653294', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2372484932.jpg', 0.7, 3, 26.5, 49.3, 20.5, '0.273350,-0.142322,-0.507561,0.551244,0.110188,-0.199972,0.600764,-0.058579,-0.422081,-0.192855,0.158344,0.534902,-0.157031,-0.069703,0.538115,-0.057478,-0.570324,-0.753982,0.049330,0.199061,-0.182972,-0.475103,-0.166023,-0.082616,-0.228988,-0.581605,0.701647,-0.117959,0.008018,0.618704,0.215786,0.420642,-0.028736,0.267069,0.046324,-0.065062,0.165057,-0.283250,-0.133894,0.161309,-0.060265,-0.170219,0.083126,-0.080518,0.250084,0.331930,0.459630,-0.280846,0.194489,-0.078095,-0.005769,-0.470455,0.290587,-0.176347,0.328466,0.147794,-0.187058,0.072613,-0.183734,0.218674,0.084508,0.022627,-0.390023,-0.145824,0.003796,-0.059883,-0.408297,0.264757,-0.351020,0.115082,-0.144472,-0.060505,-0.035631,0.156523,0.057914,0.430740,-0.083188,-0.003113,-0.326372,-0.020197,0.338984,-0.277429,-0.456964,0.170927,-0.180485,-0.520640,-0.048597,-0.221671,-0.375540,0.062950,0.201724,0.109317,0.054113,0.429539,-0.564811,-0.045954,-0.498376,-0.119136,-0.324754,-0.357631,-0.022234,-0.805942,0.084239,-0.211823,0.006992,0.104477,0.235415,0.020498,0.556370,-0.520150,0.241836,0.153213,0.045090,-0.215933,0.142452,0.019008,0.319203,-0.084955,0.082436,0.407997,0.207278,0.302721,0.072185,0.332884,-0.341665,-0.249950,0.056516,0.256208', '20274039', '25723905', '1293656', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26367602', '龙牌之谜', '动作', '电影《龙牌之谜》讲述了古老的东方传说——龙王在睡觉的时候睫毛长到地里能够长出茶叶。龙王把法力封印在龙牌里，并把这种力量赋予了替他照料睫毛的白魔法大师（成龙饰）和他的女儿成兰（姚星彤饰）。邪恶的黑魔法师将白魔法大师和成兰关进了异国监狱，龙王也陷入了沉睡，以茶叶为生的广大村民从此生活在水深火热之中……', '成龙', '伊哥·斯坦普陈科', 3.6, 17089, 'tt6218010', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2563494916.jpg', 46, 33.7, 15.8, 3, 1.5, '-0.024823,0.517743,-0.187811,0.653462,-0.132112,-0.235031,0.631533,0.245651,-0.722660,-0.129495,0.072344,0.674494,0.041207,0.241595,-0.051096,0.176350,-0.211432,-0.584911,-0.139506,0.056875,-0.419642,-0.247076,-0.460307,-0.049752,-0.176400,-0.871732,0.483893,0.390881,-0.078166,0.156100,-0.294932,-0.065814,-0.095275,0.190436,-0.394817,-0.042158,-0.174133,0.181771,-0.131085,0.370405,0.039185,-0.291629,0.405780,0.004676,0.111624,-0.119935,0.723790,-0.558034,0.238196,-0.248173,0.145016,-0.478337,-0.395179,0.366182,0.402158,-0.014873,0.265618,0.018077,-0.118271,0.070706,0.100308,-0.186388,-0.767777,-0.157069,0.093401,0.222118,-0.730695,0.604572,0.113440,0.106850,-0.167498,-0.430534,0.434483,-0.209295,0.091582,0.440320,-0.000105,-0.067727,-0.553920,0.435207,0.030335,-0.388496,0.138095,0.030597,-0.349355,-0.677686,-0.241971,-0.161147,-0.215190,-0.091944,0.591549,0.201854,-0.365245,0.378757,-0.923930,-0.214601,-0.112607,-0.120205,0.034322,-0.415311,-0.300775,-0.227235,-0.206524,-0.415186,0.137484,0.021340,0.453206,-0.345758,0.460918,-0.808191,0.334108,0.200957,0.207263,-0.065147,0.637471,-0.379697,0.238391,-0.032260,-0.122791,0.243107,-0.070482,0.930011,0.359902,0.605794,0.072033,0.254799,-0.445009,0.335030', '1293531', '24750460', '26586766', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26369884', '此房是我造', '惊悚', '林间公路，面无表情的杰克（马特·狄龙 Matt Dillon 饰）搭载了一名汽车抛锚的女子。女子自作聪明，聒噪无比，最终被杰克用千斤顶砸死。这起事件仿佛为杰克打开了一扇地狱之门，从此他走上了充满血液和寒冰的魔鬼之路。他对美有着偏执极端的追求，他从物质到精神都有着高度洁癖，他亲手为自己设计完美的房屋，却往往因为不满意而彻底拆掉。在此期间，杀戮让杰克体会到莫大的快感。他自诩为“精致先生”，将女性锁定为所猎杀的目标。他的胆子越来越大，不仅将谋杀现场的照片寄给报社，更游戏般地周旋徘徊在警方和受害者面前。这不仅是残酷血腥的猫捉老鼠的游戏，更是他为了终极目标所做的策划经营！©豆瓣', '马特·狄龙', '拉斯·冯·提尔', 7.3, 69746, 'tt4003440', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2543305779.jpg', 3.5, 6.2, 29.4, 41.1, 19.7, '0.008790,0.069527,-0.689705,0.742463,-0.287256,-0.187555,1.055361,0.235851,-0.212516,-0.002005,0.478159,0.618318,-0.201108,-0.068507,0.205617,-0.111355,-0.039710,-0.536316,-0.291169,-0.067250,-0.320940,-0.185746,-0.357993,-0.206401,-0.011520,-0.316450,0.710938,0.129802,-0.321731,0.067667,0.268196,0.370439,0.017926,0.516204,-0.180186,-0.296885,-0.024541,-0.066797,-0.152029,-0.022547,-0.140461,-0.279615,0.010722,0.368299,-0.558341,0.242835,0.850120,-0.374376,-0.293830,-0.167490,0.400356,-0.454469,0.098002,0.102151,0.078366,0.093430,-0.026235,0.266281,-0.144418,-0.154150,0.254447,-0.033493,-0.918547,-0.003964,-0.053629,0.051421,-0.324524,0.266073,-0.204170,0.141837,0.218993,-0.178484,0.011998,-0.155598,0.363244,0.354489,-0.252025,0.059328,-0.504536,0.023432,0.486777,-0.063634,-0.134513,0.480923,-0.360746,-0.403690,0.083798,-0.331958,-0.331628,-0.333497,0.400532,-0.014272,-0.255126,0.231799,-0.791706,-0.117267,-0.223801,-0.150464,-0.137718,-0.565920,-0.159330,-0.541760,-0.256179,-0.356443,-0.152701,0.034997,0.216702,-0.417110,0.681804,-0.561840,0.105364,0.708919,0.092501,-0.454577,0.520222,-0.144178,-0.156480,-0.038548,-0.322715,0.226897,0.338836,0.544486,0.129762,0.527731,-0.061097,-0.019422,-0.591157,0.820162', '21619567', '1307800', '26667010', '35360296');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26372319', '性别之战', '喜剧', 'Steve Carell与Emma Stone将合作影片《BATTLE OF THE SEXES》，影片会由《阳光小美女》的导演 乔纳森·戴顿与维莱莉·法瑞斯执导。关于1973年女子网球选手比利·简·金与Bobby Riggs的跨性别网球大战，这场比赛以金的获胜结束，比赛有着非常重要的意义，包括让女性获得更大的自尊。', '艾玛·斯通', '乔纳森·戴顿', 6.7, 9630, 'tt4622512', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2481987905.jpg', 1, 8.3, 52.2, 31.1, 7.3, '-0.164861,-0.326502,-0.312199,0.548499,0.455162,-0.334137,0.351187,0.087216,-0.240143,-0.425998,0.007870,0.612574,-0.557936,-0.150441,0.889495,-0.583013,-0.306296,-0.952300,-0.433301,0.335429,-0.367728,-0.658140,-0.071578,-0.292404,-0.155244,-0.682493,1.019514,0.117998,-0.638757,0.515688,0.373163,0.365689,0.311816,-0.080263,0.496766,-0.574470,-0.098242,0.108047,-0.640328,0.507272,0.322238,0.085990,-0.390198,-0.092583,0.414378,0.184307,0.736854,-0.438236,0.341637,-0.098127,0.549813,-0.393435,-0.126523,0.096162,0.082469,0.139849,0.111274,0.722945,0.234271,0.135666,0.201285,-0.724633,-0.829567,0.138324,0.096173,0.200118,-0.041498,0.821682,-0.141808,0.186401,0.241647,0.051742,0.184485,0.258525,0.510045,-0.216442,-0.067093,-0.032322,-0.430875,0.168888,0.607638,0.326039,-0.045581,0.049706,-0.325366,-1.023197,-0.536683,-0.530518,-0.192048,0.725413,0.515113,0.156387,0.485525,0.343575,-0.717647,-0.302488,-0.248636,-0.439013,0.191861,-0.530705,0.288700,-1.070593,-0.189299,-0.529279,-0.508343,-0.177736,0.259242,-0.417806,1.281523,-1.249202,-0.077829,0.293804,0.370739,-0.038992,0.824880,0.170160,0.455226,-0.475127,-0.274550,0.228136,-0.190554,-0.227245,-0.235041,0.319925,0.098692,-0.162746,-0.164784,0.442906', '1826173', '1316589', '4127270', '27201353');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26372545', '野马', '剧情', '初夏，在土耳其北部的一个村庄里，拉蕾和她的四个姐妹走在放学回家的路上，和男孩子们天真烂漫地打闹。然而这种行为却被当成了一桩不检点的丑闻，引发可怕的后果。家庭生活变成监狱，从此告别学校，而是为结婚做准备。五个姐妹都同样向往着自由，她们找到了一种突破这囚牢的方式。', '古内丝·森索伊', '蒂尼斯·艾葛温', 8, 28409, 'tt3966404', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2243553554.jpg', 0.4, 1.2, 19.8, 54.2, 24.5, '0.883794,-0.101287,-0.579901,0.682829,-0.349107,-0.185953,1.007472,0.217301,-0.162896,-0.231518,-0.010828,0.695100,-0.118828,0.517813,0.118879,-0.133313,-0.284727,-0.704577,-0.183913,-0.023819,-0.222518,-0.252849,0.137479,-0.150038,-0.021334,-0.115511,0.567238,0.085054,-0.018915,0.522260,0.099533,0.135952,-0.228313,0.460319,-0.308353,0.111250,0.288156,0.363069,-0.266588,0.319522,-0.240300,0.072202,-0.075585,0.245003,0.081663,0.178202,0.856967,-0.032952,-0.193470,-0.167347,0.522268,-0.228775,-0.178154,0.402061,0.396616,-0.083758,0.301885,0.180885,-0.093586,0.304469,0.146472,-0.208714,-0.806258,0.082254,0.093053,-0.206499,-0.639557,0.474091,0.306474,-0.214790,0.171759,-0.386324,0.346271,0.529265,0.141545,0.858501,-0.505757,0.185386,-0.897182,-0.014984,1.250737,-0.306749,-0.322479,0.275102,-0.198239,-0.178246,0.152607,-0.153674,-0.609344,-0.317692,0.082438,-0.094673,-0.466157,0.117166,-0.705745,0.172178,-0.152815,-0.292365,0.146255,-0.639275,-0.067919,-0.626731,0.117927,-0.523653,-0.718671,0.269668,0.120255,-0.086440,0.760277,-0.536933,0.252394,0.522073,0.426212,-0.786187,0.873111,0.367442,0.403822,-0.146602,0.018388,0.177693,-0.177055,0.333178,0.100111,0.501922,-0.203761,0.233167,-0.571861,0.475614', '25721544', '3055049', '26687241', '1806543');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26373154', '尸忆', '惊悚', '英俊帅气的承皓（吴慷仁 饰）是某电视台的制作人，他事业顺风顺水，生活中又有美丽如花的未婚妻（谢欣颖 饰）相伴，可谓幸福无忧。最近一段时间，承皓正在拍摄一部关于冥婚民俗的纪录片，不知是压力过大还是碰到什么可怕的东西，他在梦中经历了诡异恐怖的梦境，而玄道众人也对其发出了警告。在此之后，诡异的梦境愈演愈烈，甚至让他分不清梦境和现实。万般无奈之下，他只得向高人求助。与此同时，平凡女高中生茵茵（严正岚 饰）突然发现自己身边的灵异事件陡增，她为此惶惶不可终日。一切都指向了沉睡在深山老林中的古宅……©豆瓣', '吴慷仁', '谢庭菡', 6.9, 24207, 'tt5735218', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2301912793.jpg', 1.8, 8.5, 43.2, 35.9, 10.6, '0.049533,0.037662,-0.566824,0.453445,0.184774,0.086409,0.959851,-0.022095,-0.623389,-0.197769,0.396177,0.555200,-0.286631,0.142353,0.191251,0.136485,-0.165225,-0.777853,-0.300647,0.034246,-0.243352,-0.139996,-0.512841,0.083420,-0.070699,-0.212694,0.439679,0.218807,-0.197812,0.380395,0.250762,0.282971,-0.391162,0.452923,-0.225397,0.087677,-0.077870,0.388278,-0.248792,-0.256892,0.022541,-0.577203,-0.423120,0.361844,-0.110405,0.275655,0.569790,-0.171349,-0.547727,-0.014929,0.542234,-0.139986,-0.375905,0.016879,0.149686,0.107946,0.164339,0.025375,-0.170108,-0.102484,-0.103829,0.143152,-0.658847,0.146124,0.136000,0.168922,-0.176877,0.327803,0.084661,-0.143085,0.228185,-0.219213,0.209623,-0.018390,0.453663,0.289556,-0.063038,0.126145,-0.240571,0.510030,0.584990,0.259152,-0.408181,0.563379,-0.444413,-0.208761,-0.218919,-0.222553,-0.613961,0.181292,0.228107,0.120866,-0.294690,0.458359,-0.336001,0.200856,-0.126613,-0.178752,-0.369617,-0.264145,-0.477621,-0.392120,-0.215059,-0.427796,-0.272739,-0.022146,0.016849,-0.241551,0.556870,-0.731033,0.185699,0.583440,0.200356,-0.130894,0.590982,-0.084354,-0.099755,-0.120556,-0.111126,0.208623,-0.232774,0.231590,-0.057676,0.336936,-0.093738,0.082433,-0.532241,0.494348', '4275444', '4233625', '1296370', '25909236');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26373527', '好友请求', '惊悚', '学校里的风云人物劳拉，善于交际，热爱脸书。某日，劳拉与她在脸书上认识的女孩“玛丽娜”发生争执，怒而取关，玛丽娜自杀。从这时起，劳拉的好友开始离奇惨死。', '阿莉西娅·戴柏南·凯里', '西蒙·范霍文', 6.1, 8527, 'tt3352390', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2277065823.jpg', 3.3, 17.6, 54.3, 19.3, 5.5, '0.655466,-0.130989,-0.792677,0.306525,0.039717,-0.149913,0.793078,-0.025393,-0.365735,-0.229416,0.070165,0.847732,-0.581935,0.750956,0.359647,0.094115,-0.283809,-0.822681,-0.090173,-0.449945,0.070546,-0.489296,-0.098531,-0.310477,-0.159993,-0.453902,0.150240,-0.135329,-0.217598,0.753569,0.603449,0.157869,-0.265346,0.286717,0.137000,0.057131,0.002837,-0.025851,-0.261324,-0.123761,0.119024,0.002313,-0.173410,0.015927,0.032513,0.163848,0.648176,-0.106696,0.129981,-0.192882,0.730343,-0.233806,-0.311670,0.239671,0.616628,0.127859,0.563086,-0.152512,0.376408,-0.468813,0.072527,0.020290,-0.129030,0.141940,0.011296,0.219886,-0.563256,0.344979,-0.259390,-0.097492,0.322305,-0.331426,0.080020,-0.186029,0.096045,0.404142,0.423729,-0.080428,0.169499,0.216228,0.572705,-0.094481,-0.118872,0.128483,-0.308420,-0.404654,0.212149,-0.206714,-0.448486,-0.023224,0.249911,-0.547800,-0.248577,0.443825,-0.388699,0.244727,-0.196381,0.333048,-0.030579,-0.079792,-0.428129,-0.715654,-0.489611,-0.602045,-0.007038,-0.187652,-0.056670,-0.500134,0.830397,-1.131001,0.174130,0.397580,0.224395,-0.341243,0.447334,0.486265,0.131984,-0.189567,-0.122081,0.271024,0.385455,0.085056,-0.233872,-0.120979,-0.133940,0.177151,-0.337267,0.273389', '1292219', '3155839', '25922902', '25723081');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26374197', '蜘蛛侠：平行宇宙', '动作', '正就读中学的少年迈尔斯（沙梅克·摩尔 Shameik Moore 配音）意外被一只遭受放射性污染的蜘蛛咬伤，随后身体发生奇特的变化。偶然机缘，他目睹了蜘蛛侠（克里斯·派恩 Chris Pine 配音）和犯罪头目金并（列维·施瑞博尔 Liev Schreiber 配音）的战斗。为了阻止金并利用时空对撞机扰乱宇宙，蜘蛛侠最终壮烈牺牲。可未过多久，来自平行宇宙的颓废的彼德·帕克（杰克·约翰逊 Jake M. Johnson 配音）出现在迈尔斯面前。为了阻止金并的阴谋，并帮助这个帕克返回自己的宇宙，他们闯入金并的老巢。在这一过程中，二人遭到章鱼博士和徘徊者的狙击。与此同时，来自其他宇宙的女蜘蛛侠、暗影蜘蛛侠、蜘猪侠、二次元蜘蛛妹相继出现。他们合力与恶势力展开斗争……©豆瓣', '沙梅克·摩尔', '鲍勃·佩尔西凯蒂', 8.6, 578164, 'tt4633694', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2535851348.jpg', 0.2, 0.9, 12.3, 41.7, 44.9, '0.193479,0.141754,-0.628692,0.348472,0.245420,-0.167512,1.005995,0.102963,-0.124676,-0.332521,0.032109,0.637706,-0.223931,-0.133753,0.202523,-0.281757,-0.344595,-0.407766,-0.161049,0.029415,-0.383276,-0.431262,-0.290641,-0.232422,0.301843,-0.444758,0.644470,-0.000648,-0.439674,0.463496,0.502600,0.314687,-0.453869,0.579746,0.161444,0.089408,0.036064,0.034707,-0.231760,0.188381,-0.249154,-0.107964,0.199848,0.092419,-0.211646,0.123596,0.625957,-0.609673,0.126452,-0.360799,0.133181,-0.211817,0.067632,-0.164723,0.484183,-0.332517,-0.055925,-0.059035,0.250122,0.243518,0.029811,-0.059882,-0.956439,-0.067596,-0.078979,0.317958,-0.052984,0.022938,0.347299,0.184465,-0.090505,-0.014090,0.028517,0.361394,0.623843,0.011244,-0.408772,0.318762,-0.251385,-0.110212,0.358884,-0.112801,-0.392704,0.083165,-0.078206,-0.653864,-0.544671,0.133462,-0.178805,-0.042071,0.507747,0.320650,-0.206065,0.388915,-0.783235,-0.109499,-0.245910,-0.069638,-0.160023,-0.206460,-0.139440,-0.879751,0.132020,-0.099967,-0.237415,-0.161334,-0.048416,-0.236850,0.219068,-0.753034,0.350410,0.721449,0.244412,-0.109309,0.426214,0.025724,0.198336,-0.381197,-0.408779,0.441155,0.366890,0.451408,-0.047272,0.185804,0.152966,-0.075227,-0.127875,0.380672', '1316693', '2988294', '25774050', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26374205', '逗鸟外传：萌宝满天飞', '喜剧', '鹳鸟送子，天经地义……至少以前是这样。现在，他们负责给角落商店送货。朱尼尔（安迪·萨姆伯格 Andy Samberg 配音），是公司里的最佳快递员，即将升职的他在某天值勤时，遇到了宝宝制造厂被意外启动的事件。结果， 一个人见人爱，完全未经授权的宝宝就这样出现了。为了不让老板发现这次意外事故，朱尼尔和他的朋友、鹳鸟山上唯一的人类小郁（凯蒂·克朗 Katie Crown 配音），迫不及待地想把宝宝送走，于是匆匆踏上了他们首次快递宝宝的疯狂惊险之旅。不止一个家庭因此享受到天伦之乐，更重要的是，这次任务的胜利完成将让全球的鹳鸟卷土重来，再续送子的光荣使命。', '安迪·萨姆伯格', '尼古拉斯·斯托勒', 7.5, 42710, 'tt4624424', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2378515005.jpg', 0.3, 4, 35.1, 42.8, 17.8, '0.377722,0.122491,-0.600506,0.391085,-0.136578,-0.175266,0.381736,-0.046515,-0.483907,-0.103571,-0.006546,0.794478,-0.062660,0.318274,0.267550,0.089219,-0.106496,-0.344292,-0.056097,-0.034101,-0.357488,-0.293941,-0.092446,-0.143929,-0.034665,-0.057072,0.309836,-0.051689,0.281888,0.516252,0.290778,0.103819,-0.001677,0.470881,-0.016354,0.080634,0.346943,-0.013814,-0.012296,0.418863,0.067832,0.006507,0.227974,0.355817,0.195155,0.111230,0.705434,-0.367183,-0.340293,-0.330100,0.372668,-0.332696,0.139822,0.018342,0.160156,0.001206,0.263513,-0.093525,-0.222756,-0.148209,0.165178,-0.190692,-0.740751,0.088057,-0.051314,-0.042747,-0.456358,0.085788,-0.171310,0.163091,0.396574,-0.460856,0.472771,0.613052,0.420572,0.386021,-0.133887,0.336049,-0.538030,0.275023,0.701187,-0.113623,-0.073725,0.298017,-0.029039,-0.527523,0.233896,-0.196139,-0.297704,0.174914,0.464865,0.112922,-0.162164,-0.140795,-0.606714,-0.061181,-0.275550,-0.290238,-0.119268,-0.428891,-0.054194,-0.407601,0.334636,-0.045389,-0.220091,0.036343,0.004260,-0.522245,0.596570,-0.789979,0.248024,0.775844,0.239381,-0.384064,0.669055,-0.128624,0.341333,-0.389127,0.202638,-0.050361,0.281530,0.507335,0.154252,0.230847,0.201513,-0.213193,-0.096517,0.622177', '24733428', '1420088', '2032339', '1299628');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26374671', '密探', '剧情', '风起云涌的20世纪20年代，整个世界都笼罩在一场巨大的风暴之中。风云突变的京城，来自各国的势力碰撞角逐，危机一触即发。朝鲜人出身的日本警察李政出（宋康昊 饰）深得老奸巨猾的日本警务局部长东村（鹤见辰吾 饰）的器重，在一次追查义烈团的行动中，曾经的同事金长玉自杀，随后李政出成为了寻找义烈团领导人的急先锋。通过细心排查，李找到了金优进（孔刘 饰）所经营的古董店，而金恰恰是义烈团的干部。最近一段时间，义烈团策划将一批炸药通过火车从上海运往京城，计划炸掉日本警察局。金优进大胆将李政出引荐给义烈团团长郑彩山（李秉宪 饰），希望策反这个朝鲜人，帮助他们完成计划。无论如何，良心未泯的李政出被绑上了一条危机重重的小船，他不得不作出抉择……本片荣获第36届韩国影评奖最佳作品奖。©豆瓣', '宋康昊', '金知云', 6.7, 14700, 'tt4914580', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2376085450.jpg', 1, 8, 53.8, 28.6, 8.5, '-0.114863,0.185972,-0.643819,0.652479,0.025285,0.019294,0.180445,0.050095,-0.409983,-0.103394,0.234167,0.402317,-0.266395,0.029226,0.194072,-0.265463,-0.160552,-0.726105,-0.291915,-0.112993,-0.328654,-0.364286,-0.369879,-0.250382,-0.122714,-0.064182,0.730775,0.564125,-0.250478,0.215549,0.466887,0.345350,-0.202444,0.261188,-0.057062,-0.321031,0.197217,0.000237,-0.426541,0.077091,-0.269009,-0.529167,0.029040,0.114381,0.189386,0.400575,0.589698,-0.268729,-0.002786,-0.180228,0.500595,-0.458341,-0.173983,-0.147343,0.596223,0.236215,-0.173271,0.202862,-0.276330,-0.024776,-0.072255,-0.213093,-0.649477,-0.222761,0.370725,-0.035777,-0.609819,0.097730,0.010815,0.174956,-0.252117,-0.113916,0.278917,0.539591,0.313520,0.179494,0.066409,0.314442,-0.317601,0.324571,0.700334,-0.185682,-0.321006,-0.245904,-0.011641,-0.434114,0.005934,-0.170649,-0.086161,-0.011075,0.418598,-0.334566,0.174815,0.075168,-0.426210,-0.111454,-0.227060,-0.367379,0.226301,-0.161659,0.006922,-0.781073,-0.034086,-0.179880,0.081332,0.205555,0.105377,-0.109809,0.665799,-0.493601,-0.051693,0.443737,0.158371,-0.512358,0.580963,0.028511,0.094447,-0.432956,0.031843,0.042931,0.160023,0.256122,0.078172,0.322489,-0.205430,-0.330134,-0.290253,0.201489', '1307762', '6101834', '3266509', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26375028', '暗杀教室：毕业篇', '剧情', '距离暗杀杀老师（二宫和也 配音）的最后期限越来越近，一直潜伏在三年E班的秘密武器也终于出动。背负莫大仇恨的茅野枫（山本舞香 饰）露出了隐藏已久的触角，向杀老师展开绝命袭击。恰恰借助这一事件，杀老师讲述了自己和E班曾经的代课老师雪村亚久里（桐谷美玲 饰）一段永生难忘的渊源。围绕着暗杀行动是否进行，潮田渚（山田凉介 饰）、赤羽业（菅田将晖 饰）等人截然分成两派。他们一面希望令地球免于毁灭的 ，一面试图拯救杀老师的生命。与此同时，沉默已久的各国政府也开始酝酿最后的行动，而作为一切混乱的肇事者白先生（成宫宽贵 饰）亦将成为决定杀老师命运的重要存在。师生告别的时刻终将到来……本片根据松井优征的超人气漫画改编。©豆瓣', '山田凉介', '羽住英一郎', 6.7, 7027, 'tt4641264', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2297624908.jpg', 2.2, 11, 48.5, 26, 12.2, '-0.126628,-0.206000,-0.206567,0.358064,0.139155,-0.260107,0.308525,0.008076,-0.175224,-0.353708,0.318981,0.466551,-0.049221,0.006541,0.506718,-0.333837,-0.253130,-0.747376,-0.178247,-0.118864,-0.178464,-0.453836,-0.096139,-0.102548,0.099615,-0.280087,0.946053,0.106786,-0.197978,0.555529,0.328891,0.396362,-0.361926,0.228440,0.162010,0.007808,0.032676,-0.034450,-0.579749,0.111109,-0.124154,-0.232537,-0.155261,0.102225,-0.264119,0.291542,0.554875,-0.375740,-0.195099,-0.119894,0.282083,-0.653945,-0.155423,0.117502,0.492244,0.263591,0.141241,0.504982,-0.262412,0.056256,-0.111801,0.059803,-0.825706,-0.058701,0.270835,0.058642,-0.239408,0.377092,0.032778,0.011778,0.404811,-0.148066,0.076764,0.312340,0.433737,0.152316,-0.303187,0.062805,0.019076,-0.024413,0.651258,-0.358582,0.075588,-0.168441,0.103165,-0.082799,-0.137474,-0.200842,-0.105343,0.052081,0.120273,0.163949,0.153184,0.246959,-0.539644,-0.274686,-0.185527,-0.149463,0.330671,-0.588350,0.031210,-0.735455,-0.073979,-0.011719,-0.080243,0.156619,0.284222,-0.242699,0.817959,-0.630917,0.228072,0.378565,0.291662,-0.203388,0.309646,0.230741,-0.068816,-0.401155,-0.099421,0.179835,0.109217,0.521274,0.038322,0.098731,0.140402,-0.079210,-0.358485,0.203699', '2369613', '3861846', '10467125', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26375609', '惊天大逆转', '剧情', '海归华人郭志华（钟汉良 饰）在韩国结识了正在首尔进行学术交流的心理医生杨曦（郎月婷 饰），便委托她为烧伤毁容的哥哥郭志达进行创后心理诊疗辅导。于此同时，首尔正在进行着一场激烈的中韩足球对抗赛，决战之际，中方的队长忽然得知，自己的未婚妻被神秘人绑架，想要救出未婚妻就必须赢得比赛。韩国警方接到报警后，特工组长姜承俊（李政宰 饰）迅速将嫌疑人目标锁定在一个面具人身上，一番斗智斗勇后，警方顺利救出了人质。本以为一切已经结束时，姜承俊却发现面具人的计划才刚刚开始，人质事件只是一切危机的开始，三枚威力惊人的炸弹就被安置在决赛的体育场内，如果不能破解面具人的谜题，现场五万名观众将同体育场一起消失在爆炸中，危险还在继续……©豆瓣', '钟汉良', '李骏', 7, 72822, 'tt6033150', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2363070684.jpg', 2.6, 8.7, 40.3, 34.9, 13.4, '0.015374,0.226055,-0.591909,0.464274,-0.075604,-0.135786,0.457359,-0.071624,-0.411981,-0.259046,0.381201,0.508678,-0.539687,0.203450,0.276445,-0.063486,-0.422006,-1.049731,-0.400232,-0.056707,-0.602311,-0.471870,-0.248121,-0.164821,0.147741,-0.291462,0.598077,0.421477,-0.151437,0.381629,0.255492,0.138157,-0.359205,0.719003,0.028235,-0.258864,0.216055,-0.197852,-0.497008,0.346457,0.128413,-0.484822,-0.035019,0.252271,0.052391,0.204901,0.869199,-0.121072,-0.021194,-0.087058,0.258935,-0.321220,-0.012661,0.329369,0.404020,0.150936,0.334484,0.100218,-0.326119,0.237031,0.077790,-0.227349,-0.530838,0.093527,0.107834,0.083974,-0.267606,0.458288,-0.271810,0.280565,0.188200,-0.182131,0.321801,0.321903,0.319447,0.129450,-0.384673,-0.019460,-0.347028,0.220934,0.656701,-0.175152,-0.023133,-0.098052,0.314194,-0.594937,0.043137,0.115422,0.044718,0.130342,0.491870,0.019397,-0.151513,-0.049604,-0.358767,-0.185502,-0.481229,-0.199848,-0.167527,-0.346020,0.118978,-0.769084,-0.017013,0.205216,-0.098231,0.351777,0.026425,-0.099581,0.575871,-0.731749,0.263341,0.643361,0.176473,-0.200683,0.130012,0.011310,0.316275,-0.288241,-0.227284,-0.196350,0.079675,0.527323,0.168758,0.397202,-0.051434,-0.274623,-0.274111,0.245582', '25723905', '4202326', '6984051', '1305249');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26375689', '橘色奇迹', '剧情', '双叶社「月刊Action」杂志六月号上将宣布由高野莓创作的少女漫画「Orange」确定拍摄真人电影并将于2015年12月在东宝院线上映。高野莓2012年在集英社「别册玛格丽特」上开始连载，2013年移籍到了双叶社的「月刊Action」上连载。「orange」讲述了女主角高宫菜穗，在开学的时候收到了26岁的自己给自己寄来的信，并希望她按照信上的内容作出更好的选择的故事。', '土屋太凤', '桥本光二郎', 7, 23272, 'tt4636298', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2293954725.jpg', 1.4, 8.3, 42.1, 34, 14.3, '0.279058,0.050064,-0.154593,0.506807,0.772362,-0.103307,0.010999,0.212880,-0.468808,-0.249435,-0.175639,0.403782,-0.389628,0.681338,0.529938,0.062451,-0.393964,-0.692182,-0.027973,-0.426149,-0.024780,-0.410746,0.252223,-0.026541,-0.056255,-0.384588,1.048863,0.055555,-0.076398,0.630723,0.336387,-0.239263,0.255540,0.072260,0.381800,0.371055,-0.193026,-0.049085,-0.141073,0.574433,-0.006902,-0.578304,-0.313389,-0.062943,0.461225,0.478006,1.006751,-0.212655,-0.359458,0.279424,0.952964,-0.033264,-0.200624,0.041693,0.518839,0.465025,-0.087401,0.497740,-0.370008,0.019074,-0.505229,-0.606784,-0.259073,-0.106303,-0.024824,0.268390,-0.501786,0.538952,-0.641827,0.526702,0.370668,-0.610620,-0.178477,0.190056,0.337442,0.164874,0.176224,0.111667,-0.141575,0.750198,0.039707,0.152284,-0.187715,0.245310,0.271448,-0.331466,-0.870163,-0.296856,-0.135577,0.535634,0.008438,0.204626,-0.093643,-0.171449,-0.430003,-0.106399,0.201105,-0.854465,0.698424,-0.271696,-0.356097,-0.825938,-0.099432,0.173372,-0.230020,-0.255701,0.419120,-0.673382,1.084223,-0.701648,0.401814,0.558582,0.061920,-0.167300,0.848532,-0.174846,-0.617814,-0.211430,-0.060883,0.216174,0.195751,0.417264,0.190479,0.371324,0.148844,-0.342874,-0.335103,0.284574', '27167055', '5403927', '5920220', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26377370', '只是世界尽头', '剧情', '时隔12年后，一位作家回到了自己出生地，向家人宣告自己即将离世。只有在与家人重逢后，才能感受到就算不断争吵也遮掩不了心中的爱意，而怨恨则以疑虑和孤独的情感所诠释。本片改编自让-吕克·拉戛尔斯的同名戏剧作品。', '加斯帕德·尤利尔', '泽维尔·多兰', 7, 13004, 'tt4645368', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2375642521.jpg', 2.4, 10.7, 36.7, 34.6, 15.6, '-0.346172,-0.121447,-0.769532,0.713378,0.481314,-0.620700,1.031846,0.238274,-0.635022,-0.078214,0.349479,0.667796,-0.087064,0.594627,0.489302,-0.152576,-0.640441,-1.015485,-0.017512,-0.519354,-0.204113,-0.286609,-0.127779,-0.136046,-0.261899,-0.470968,0.937080,0.043806,-0.094874,0.551086,0.354681,0.551397,-0.368847,0.487340,-0.001300,-0.118047,-0.010962,0.252131,-0.875097,0.256672,0.324931,-0.296940,-0.364631,0.146245,-0.359282,0.143117,0.902840,-0.360821,-0.134170,0.015227,0.198281,-0.108674,0.171932,0.386482,-0.296014,-0.029135,0.492876,0.324933,-0.437295,0.217435,-0.192850,0.026755,-1.105963,0.249621,-0.018271,0.163246,-0.553092,0.586199,-0.090648,-0.475025,0.175183,-0.511812,0.064339,0.124663,0.330083,0.834611,-0.847047,0.152910,0.116053,0.079024,0.819728,-0.186903,-0.041462,0.670314,-0.057377,-0.023833,-0.208108,-0.127056,-0.723012,0.043233,0.118961,0.880242,0.091342,0.605053,-0.571611,-0.368659,-0.409615,-0.153986,0.415612,-0.703651,0.045258,-0.221702,-0.470624,-0.154141,-0.091876,-0.173764,0.561932,-0.286123,0.930508,-0.776373,0.563312,0.352464,0.271350,-0.590535,0.544230,0.195482,-0.068445,-0.248424,0.217240,0.709635,-0.222339,0.369555,0.142217,0.266152,-0.014066,0.077773,-0.274844,0.634288', '24743712', '25903033', '26021055', '1308745');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26377674', '二重生活', '剧情', '以小池真理子的小说为基础，讲述读大学哲学科的平凡学生阿珠，被研究生论文导师提议做记录某个专一对象生活和行为的“哲学跟踪”，于是开始跟踪邻居一家的丈夫的故事。', '门胁麦', '岸善幸', 7.2, 8989, 'tt4657460', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2348384426.jpg', 0.7, 4.8, 39.6, 42.1, 12.8, '0.717311,-0.715947,0.052116,1.235240,0.025891,-0.287590,-0.083906,0.049451,-0.526717,-0.909006,-0.216718,0.598166,0.065140,0.385604,0.333657,-0.296967,-0.310757,-0.654557,0.117199,-0.167709,-0.091702,-0.630703,0.461315,-0.356681,-0.196229,-0.365291,0.543583,-0.263742,-0.493782,0.181976,-0.092936,0.520977,0.054811,-0.263654,-0.075454,-0.213861,0.302773,0.104749,-0.317977,-0.239267,0.145474,0.156112,0.046833,-0.376206,0.092116,0.110246,0.981360,0.211509,-0.228370,-0.233562,0.970257,-0.215022,-0.077662,0.063531,0.706395,0.531888,0.317269,0.531710,0.420915,0.166916,-0.405183,-0.642821,-0.660120,-0.568730,0.251545,0.024530,-0.127118,0.314882,-0.008296,0.159275,0.105532,-0.113576,-0.164886,-0.070952,0.651457,0.721086,0.212275,0.030354,0.213389,0.519021,0.239224,-0.037848,0.052931,0.563220,-0.337925,-0.387819,0.336290,0.073688,-0.479668,0.130674,-0.095907,0.095978,-0.513389,0.155793,-0.623003,-0.102145,0.198755,0.004218,0.592412,-0.790035,-0.472683,-0.689262,-0.050728,0.170642,-0.228259,-0.183254,-0.009184,-0.600129,1.174363,-0.812430,-0.050421,0.599812,0.002905,-0.876783,0.877992,0.195992,-0.065165,-0.464942,-0.029637,0.364287,0.017083,0.535897,-0.492226,0.235033,0.141846,-0.423213,-0.358459,0.621741', '22265121', '27602116', '2027945', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26378579', '王牌特工2：黄金圈', '喜剧', '时光飞逝，一转眼，艾格西（塔伦·埃格顿 Taron Egerton 饰）已经成长为了一名出色而又可靠的特工，他和蒂尔德公主（汉娜·阿尔斯托姆 Hanna Alström 饰）之间的感情也愈演愈浓，两人眼看着就要携手步入婚姻的殿堂。就在这个节骨眼上，前特工查理（爱德华·霍尔克罗夫特 Edward Holcroft 饰）杀了回来，如今的他效力于一个名为“黄金圈”的贩毒组织，组织头目波比（朱丽安·摩尔 Julianne Moore 饰）是一个邪恶而又野心勃勃的女人。查理查出了金士曼的所有据点，用导弹将它们全部摧毁。幸存的艾格西和梅林（马克·斯特朗 Mark Strong 饰）千里迢迢远赴美国，向潜伏在那里的联邦特工寻求帮助。波比种植了一种含有毒素的大麻，将它们输送往世界各地，当瘾君子们体内的毒素渐渐发作后，波比以此为筹码，正式向政府宣战。©豆瓣', '塔伦·埃哲顿', '马修·沃恩', 6.8, 328904, 'tt4649466', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2499792043.jpg', 1.3, 8.6, 46.6, 34.4, 9.2, '0.102642,0.103213,-0.520233,0.693878,0.001681,-0.460211,0.832876,0.067861,-0.211783,0.063172,-0.006856,0.436910,0.007889,-0.150296,0.362714,0.081372,-0.422844,-0.656477,-0.211245,-0.301020,-0.425148,-0.382980,-0.464588,-0.507041,-0.147240,-0.389449,0.592835,0.038869,-0.122307,0.350208,0.343073,0.570002,-0.013393,0.142283,-0.043509,-0.211360,0.273325,-0.368945,-0.249078,0.389685,0.105311,-0.278946,-0.069940,-0.017763,-0.091443,0.201283,0.633097,-0.222020,0.309999,-0.414694,0.242807,-0.301565,0.099055,-0.032826,0.406326,-0.021318,-0.138094,0.044018,-0.198844,-0.071584,0.192463,-0.152702,-0.714311,-0.059157,-0.143819,0.191588,-0.507936,0.257730,-0.215914,-0.115769,0.032065,-0.332089,0.031317,0.419616,-0.021309,0.178888,-0.194805,-0.052619,-0.554923,-0.028098,0.358676,-0.087601,-0.262451,0.037618,-0.176048,-0.554033,-0.148679,-0.025076,-0.298339,-0.411945,0.632442,-0.069215,0.255740,0.437681,-0.754068,-0.024982,-0.495158,-0.235475,0.154514,-0.135018,0.102717,-0.686190,-0.164547,-0.171355,-0.244011,0.009075,0.219905,-0.037759,0.742667,-0.415702,0.327890,0.802314,0.325979,-0.389330,0.453374,-0.099457,0.279009,-0.056694,-0.165677,0.271540,0.257384,0.476540,0.353445,0.535934,0.014388,-0.054848,-0.118589,0.408723', '1292680',