INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26379074', '赛尔号大电影5：雷神崛起', '剧情', '几经争战之后，战神联盟在赫尔卡星建立了一座“雷霆守护局”,守护三座圣塔和星球子民。某天赫尔卡星突然出现了一位巨型意外来客，伤害无辜精灵，企图摧毁城市。战神联盟火速集结，在调查幕后真凶的过程中，雷伊与大反派奥古斯塔博士相遇，交战中，雷伊发现了同胞哥哥的遇难之谜，但也中计受伤，被奥古斯塔激发了体内的邪恶力量，陷入痛苦之中，终极一战之际，众战神受召唤雷伊重新崛起，力挽狂澜，击败邪恶，再次守护住了宇宙正义及万众子民的平安……', '罗玉婷', '王章俊', 5.2, 3519, 'tt4885238', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2254962123.jpg', 28.4, 22.2, 24, 12.5, 12.9, '-0.299606,0.290162,-0.650789,0.393451,0.349479,0.115234,0.521231,-0.093615,-0.386266,-0.159906,0.394396,0.689461,0.061030,0.119356,0.517026,-0.166991,-0.261819,-0.659799,-0.079305,-0.165857,-0.158921,-0.130044,-0.492218,-0.149465,0.165073,-0.966886,0.675425,0.517493,-0.245039,0.221649,-0.175233,0.540568,-0.603234,0.306744,-0.009554,-0.143595,0.319552,-0.213605,-0.242690,0.628143,-0.715441,-0.050602,-0.012992,0.546350,-0.349612,0.043267,0.412381,-0.800375,0.112547,-0.644539,0.170349,-0.404013,-0.049083,0.036706,0.534425,0.090517,0.032834,0.152724,-0.068513,-0.220364,0.060799,-0.335859,-0.887340,-0.359686,0.051252,-0.015652,-0.493090,0.355887,0.153344,-0.049945,0.104975,0.122448,0.415582,0.659865,0.646001,0.282201,-0.209185,0.080341,-0.212165,-0.390698,0.774832,-0.545010,-0.364757,-0.365365,0.279600,-0.390857,-0.210929,-0.368805,-0.432157,-0.128318,0.375249,0.283789,0.382087,0.915386,-0.709339,-0.157743,-0.681067,-0.081732,-0.138207,-0.259355,-0.120121,-0.445167,-0.342449,0.489279,0.161817,0.289761,0.032666,-0.044207,0.698853,-0.842869,0.648762,0.414098,0.743124,-0.320561,0.429749,-0.005798,0.253543,-0.226048,0.093733,0.352727,0.294888,0.522234,0.078748,-0.123884,-0.188153,0.064081,-0.258342,0.267757', '27667334', '5308201', '11503382', '1458902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26381255', '潘菲洛夫28勇士', '剧情', '本片讲述了二战中的一个著名故事。1941年德军集结了最精良部队对莫斯科发动了号称“台风”的强大攻势，目标是在冬季来临前攻下这座城市。苏军“潘菲洛夫步兵师”的28名士兵用仅有1门45毫米反坦克炮、几支反坦克步枪、反坦克手榴弹和燃烧瓶阻挡了这支野心勃勃的侵略之军，以整个连队只幸存5人的巨大代价阻止了德军的进攻，保卫了莫斯科。', 'Maksim Abrosimov', '基姆·德鲁日宁', 7.4, 9465, 'tt5207204', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2402661195.jpg', 1.1, 4.2, 34.7, 43.6, 16.4, '-0.007077,-0.316838,-0.853642,0.605800,0.382711,0.373670,0.802181,-0.306807,-0.141220,0.149380,0.463636,0.327938,0.547511,-0.535955,0.016627,-0.357025,-0.093398,-0.559340,-0.348207,-0.179989,-0.590791,-0.294592,-0.452837,-0.421751,0.369546,-0.335983,0.802507,0.281448,-0.506257,0.122071,-0.042007,0.190982,0.475843,0.541837,-0.083770,0.027564,0.078348,-0.718740,-0.135467,0.342472,-0.718128,-0.592329,-0.296528,0.220279,-0.259296,0.642221,0.723477,-0.438834,0.298501,-0.255141,-0.445427,-0.277363,-0.158042,0.020486,0.461924,0.163378,-0.086556,-0.108460,0.094393,0.291108,-0.328213,-0.199870,-0.381184,-0.176955,0.080463,-0.551886,-0.803257,0.680215,-0.522331,0.479512,0.290909,-0.232891,0.462262,0.622649,-0.077980,0.201065,-0.439230,0.157254,-0.729196,0.190374,0.581165,-0.516155,-0.653140,-0.186007,-0.057971,-0.368171,-0.138717,-0.441881,-0.314055,-0.006481,0.377015,-0.416707,0.555451,0.221974,-1.137926,0.364103,-0.541759,-0.502588,-0.053766,-0.182255,-0.213337,-0.788416,0.178780,-0.284709,-0.222357,0.698264,0.024054,0.449403,1.285653,-0.375470,-0.194474,0.479529,0.441156,0.077328,0.333222,-0.012301,0.154395,0.120918,0.546538,0.473545,-0.244452,0.637226,0.175681,0.611439,-0.270476,-0.289775,-0.167765,0.360687', '2977870', '4181031', '25863940', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26382689', '仁川登陆作战', '剧情', '影片讲述朝鲜战争时期，八名韩国士兵秘密完成X-RAY情报计划和八尾岛作战计划，助推美国陆军上将麦克阿瑟指挥成功登陆仁川。', '李政宰', '李宰汉', 5.5, 8599, 'tt4939066', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2353122858.jpg', 11.7, 26.7, 42.3, 13, 6.3, '-0.709993,0.180992,-0.602241,0.699406,0.706971,0.616778,-0.601322,-0.325743,-0.428424,-0.107474,0.163570,0.414609,0.705319,-0.607483,0.563711,-0.281385,-1.328607,-0.795487,0.019929,0.260310,0.090257,-0.501080,-0.132335,-0.588812,0.184811,-1.088754,1.176917,0.516346,-0.478729,0.052229,0.031969,0.264133,-0.465536,0.032850,0.545256,-0.252083,1.048855,-0.755921,-0.781354,0.512545,-0.807473,0.170183,0.022309,-0.003777,0.581436,0.211793,0.903258,-0.035380,-0.358949,-0.466604,-0.351821,-0.621591,0.037516,-0.223508,0.882145,0.643479,0.211414,0.671783,0.260344,0.122583,-0.692933,-0.689917,-0.531250,-0.413509,0.103844,-0.019918,0.376892,-0.408870,-0.783918,1.418089,0.210424,-0.354621,-0.221968,0.930193,0.721460,-0.299147,-0.118706,0.509954,-0.160332,0.537361,0.355465,-0.688816,0.140119,-0.335563,0.578374,-0.346096,-0.325569,-0.135258,0.722026,0.384642,-0.134007,-0.240299,0.105353,0.355204,-0.352461,-0.056673,-0.537901,-0.475934,0.088116,-0.134974,0.127571,-1.462282,0.092828,0.508382,-0.229199,-0.070473,0.227206,0.278264,0.925635,-0.122312,-0.168208,0.104564,0.152159,-0.363486,-0.046335,0.439203,0.215099,-1.148671,0.927411,0.359663,-0.342922,-0.217467,-0.345767,-0.084356,-0.204254,-0.665650,-0.376959,-0.089607', '1293572', '26335580', '1298616', '3010409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26382767', '了不起的菲丽西', '喜剧', '故事发生在风景优美而又浪漫的法国。菲丽西（艾丽·范宁 Elle Fanning 配音）自幼失去了父母，住进了孤儿院。在那里，菲丽西邂逅了名为维克托（戴恩·德哈恩 Dane DeHaan 配音）的男孩，两人之间结下了深厚的友谊。内心里，菲丽西一直希望能够成为一名芭蕾舞者，但是她知道，如果一直待在孤儿院的高墙之内，她的愿望将永远无法实现。维克托的脑袋里总是充斥着古灵精怪的奇思妙想，在他的帮助下，菲丽西找到了从孤儿院逃跑的方法，两人结伴相互扶持踏上了前往巴黎的旅途，并且在经历了千难万险之后顺利抵达目的地。到了巴黎后，菲丽西才发现，属于她的冒险才刚刚拉开序幕。©豆瓣', '艾丽·范宁', '艾瑞克·莎莫', 6.5, 22192, 'tt2261287', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2416009294.jpg', 3.7, 13.3, 46.6, 26.9, 9.5, '0.295557,0.224122,-0.993587,0.604471,0.119217,-0.333036,0.688045,-0.024871,-0.446417,-0.067619,0.117538,0.935011,-0.173680,0.514012,0.512494,0.059965,-0.464888,-0.806965,0.083254,-0.382573,-0.411596,-0.557520,0.048668,-0.063904,-0.062366,-0.284068,0.786631,0.343025,-0.125719,0.431095,0.257145,0.014755,-0.309706,0.336253,-0.382375,0.207515,0.277005,0.057606,-0.272096,0.511533,0.351843,-0.173949,-0.142425,0.136611,0.049174,0.123544,0.718246,-0.269448,-0.060285,0.128195,0.046772,-0.021177,0.064491,0.203782,-0.018502,0.037180,0.194054,0.182925,-0.247797,0.145381,0.211059,-0.245493,-0.567834,0.115638,0.039860,0.021317,-0.830078,0.461398,0.049232,-0.198105,0.106053,-0.490677,0.280367,0.662262,0.351151,0.245340,-0.469013,0.172578,-0.671075,-0.155321,0.911933,-0.189211,-0.322439,0.470406,-0.342007,-0.531513,-0.099299,-0.067655,-0.555561,-0.056449,0.528006,0.244755,-0.259760,0.233068,-0.621989,-0.011133,-0.437826,-0.033611,0.107741,-0.363962,0.114073,-0.674048,-0.072363,-0.427996,-0.266809,0.054912,-0.192606,-0.370812,0.745075,-0.982956,0.432179,0.636819,0.362664,-0.263230,0.719967,-0.045967,0.402193,-0.173227,0.229724,0.740571,-0.363788,0.471259,0.216033,0.360040,-0.103599,-0.025285,-0.657845,0.575921', '1926007', '3055049', '26884892', '1307755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26382888', '一路向前', '喜剧', '牛顿（陈赫 饰）是一位极其平凡的青年，大学毕业后进入公司工作，一年过去，依然混得不温不火，前途暗淡。牛顿暗恋着同事姚姚（姚星彤 饰），但他深知美丽火热的姚姚和默默无闻的自己并不属于同一个世界，况且姚姚已经有了帅气多金的男友，身无长技的牛顿完全没有实力与之抗衡。某日，公司下派了一个前往纽约公干的绝好机会，公司里几乎每个人都野心勃勃，想要得到这个机会，牛顿当然也包括在内。在好友卡耐基（常远 饰）的怂恿和建议之下，牛顿为了得到工作简直厚颜无耻不择手段，与此同时，姚姚的感情却遭遇了危机，在事业上亦陷入了瓶颈。©豆瓣', '陈赫', '侯亮', 4.3, 8311, 'tt4886016', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2256827289.jpg', 38.3, 28.6, 19.4, 5.3, 8.5, '0.043415,0.147447,-0.732685,0.704341,-0.372817,-0.378100,0.523427,0.217979,-0.463931,-0.430466,-0.038603,0.700783,-0.091002,0.272300,0.260637,-0.159165,-0.037413,-0.683750,0.011941,-0.227604,-0.080915,-0.520378,-0.411265,-0.020861,-0.296110,-0.192281,0.733579,0.045168,-0.152022,0.427600,0.195234,0.227247,-0.042066,0.684183,-0.025051,-0.272051,0.273900,0.186485,-0.406241,0.196750,-0.065148,-0.041506,0.221095,0.236075,0.066167,0.380862,0.307943,-0.034273,-0.272488,-0.028208,0.356481,-0.030699,-0.183873,0.147444,0.359705,-0.102044,0.440583,0.330270,-0.086472,0.040223,0.068384,-0.215437,-0.943477,0.023752,0.207430,0.109455,-0.582406,0.476402,0.044156,-0.267555,-0.234078,-0.306397,0.197142,0.380015,0.297589,0.312918,-0.159275,0.242537,-0.461434,0.154537,0.602236,0.200422,-0.201540,0.469836,-0.062117,-0.419658,-0.116879,-0.225150,-0.412607,0.103507,0.019628,0.073003,-0.213712,0.205766,-0.498700,0.173408,-0.040034,0.006848,-0.058332,-0.504822,0.040243,-0.403118,-0.111387,-0.345693,-0.492105,0.192313,0.211443,-0.453431,0.689927,-0.954315,0.045656,0.404634,0.395389,-0.643410,0.879925,0.191593,0.128444,-0.383485,-0.097229,0.259678,0.023733,0.201947,-0.191690,0.207375,-0.212852,-0.430858,-0.378792,0.509876', '1793491', '4301278', '1308499', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26382960', '八月未央', '爱情', '讲述了可爱率真的小乔（谭松韵 饰）遇见了沉默寡言的未央（钟楚曦 饰），小乔的热情开朗使性格迥异的她们迅速成为了“蜜友”，而小乔未婚夫朝颜（罗晋 饰）的出现使得三人的感情产生了微妙的变化，三人关系也由此变得错综复杂的爱情故事。电影改编自庆山（安妮宝贝）同名小说。', '钟楚曦', '李凯', 3.2, 37545, 'tt10080086', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2636651422.jpg', 56.8, 30.1, 11.2, 1.4, 0.5, '0.535994,-0.114772,-0.498478,0.559744,0.306093,-0.088508,0.624954,0.487150,-0.573476,0.061877,0.320430,0.505560,-0.658958,-0.369425,0.170518,-0.089642,-0.239307,-0.727346,-0.167190,0.027714,0.203978,-0.410998,-0.194016,0.015385,0.167012,-0.797355,0.242419,-0.456538,-0.239106,1.036151,0.273629,0.244429,-0.347435,0.291686,0.183493,0.437811,-0.107537,0.177422,-0.299826,0.005742,-0.158807,0.139850,0.165597,0.094969,-0.131718,0.317020,0.951997,-0.149468,-0.620242,0.178342,0.725302,0.335069,-0.105621,-0.012462,0.220883,0.280624,0.211581,-0.078847,-0.248658,0.157515,0.110787,0.026470,-0.451919,0.556332,0.511588,0.313852,-0.244075,0.311792,0.154251,-0.529505,0.162256,-0.425039,0.168013,0.302759,0.617094,0.276283,0.087732,0.279857,-0.088420,0.065268,0.453117,0.091624,-0.557631,0.729173,-0.522890,-0.078003,-0.235776,0.040303,-0.494219,0.259915,0.343091,-0.037362,0.172188,0.591989,-0.766030,-0.071072,0.029095,0.442016,0.158833,-0.410391,-0.053091,-0.545657,-0.644765,-0.613947,-0.341180,-0.363663,-0.294550,-0.267619,1.129471,-0.784784,-0.082210,0.071962,0.126354,-0.679659,0.322136,-0.000687,-0.259271,0.028630,0.026315,0.474785,-0.436174,-0.149432,0.091359,0.527690,-0.245109,-0.068059,-0.294532,0.292680', '3811356', '25922902', '5977789', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26383898', '一锤定音', '剧情', '好男人雅各布坐了10年大牢，刑满获释后被迫参与黑帮枪支倒卖交易，否则家人危在旦夕。然而，10年的监狱磨练，却使他拥有问鼎黑帮老大宝座的实力……', '尼古拉·科斯特-瓦尔道', '里克·罗曼·沃夫', 7.6, 17347, 'tt4633690', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2496044595.jpg', 0.5, 3, 31.6, 47, 17.8, '-0.342486,0.048204,-0.118537,-0.117106,-0.048780,-0.239423,0.160333,0.322690,-1.011812,0.092527,0.567482,0.264555,0.244805,0.024806,0.174675,-0.192131,-0.254531,-0.708623,0.046636,-0.286237,-0.461670,-0.184394,-0.125841,-0.252245,-0.229437,-0.430732,0.862362,-0.058548,0.212857,0.289786,-0.128398,-0.017508,0.251351,0.200885,-0.104483,-0.587480,0.472101,0.027980,-0.608116,0.170477,-0.288130,-0.371694,-0.151776,-0.296045,0.430483,0.010900,0.317797,0.193556,0.114576,-0.446117,0.004872,-0.243835,-0.635078,-0.126394,0.366295,-0.021574,-0.275023,0.888514,-0.083274,-0.538220,0.009086,-0.058640,-0.498389,-0.108389,-0.008728,-0.381153,-0.355931,0.339737,-0.187414,0.506844,-0.331080,0.176971,-0.003479,0.467769,0.081301,-0.002459,-0.091882,0.252980,-0.727788,0.385113,0.497614,-0.657756,-0.212227,-0.072956,0.298180,-0.777352,-0.261458,-0.908891,-0.148567,-0.200859,-0.031774,-0.237733,-0.327644,0.095490,-0.242683,-0.343475,-0.458441,0.072744,0.233570,-0.184456,-0.110581,-0.290823,-0.693842,-0.027964,-0.290067,-0.046379,0.085043,-0.115254,0.655429,-0.274214,0.314768,0.720445,0.400119,-0.839850,0.824466,-0.366542,0.236872,-0.216281,-0.052531,0.319168,0.193751,0.192546,0.228232,-0.070772,-0.379122,-0.278141,0.318937,0.097162', '21354138', '34779692', '10540066', '1295987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26383923', '刺杀盖世太保', '剧情', '青年海德里希（杰森·克拉克饰）在舞会上对女子丽娜（裴淳华饰）一见钟情，并对丽娜的纳粹思想深表赞同。二人婚后，海德里希通过丽娜的帮助成为纳粹党卫军的一员，开始大肆虐杀犹太人，种种暴行让他成为了“类人猿”行动的清除目标。负责执行刺杀任务的扬·库比斯（杰克·奥康奈尔饰）和约瑟夫·加比希克（杰克·莱诺饰）孤身潜入布拉格，在捷克反抗组织的掩护下着手准备，扬还与少女安娜（米娅·华希科沃斯卡饰）产生了一段凄美的爱情，但残酷的现实却提醒着每一个人时不我待。屠杀仍在继续，刺杀行动也终于开始……', '裴淳华', '塞德里克·吉门内兹', 6.6, 8502, 'tt3296908', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2506042953.jpg', 1, 8.4, 57.6, 27.7, 5.4, '0.330859,0.103615,-0.449008,0.391264,-0.154165,-0.371377,0.716999,-0.035815,-0.256032,0.023599,0.399659,0.594416,0.002878,-0.145797,0.559091,-0.006660,-0.841403,-0.626971,-0.067723,0.060375,-0.197864,-0.658419,-0.181291,-0.233434,0.048902,-0.563807,0.492539,-0.113564,-0.308741,0.543251,0.330866,0.398179,-0.083634,0.510855,-0.046635,-0.038442,0.200766,-0.365091,-0.482515,0.178681,-0.040070,-0.155773,-0.357164,0.156704,-0.115852,0.453330,0.481452,-0.552296,0.002481,-0.202461,0.201877,-0.425771,0.052043,0.212386,0.219544,0.058295,-0.133201,0.437261,-0.032461,0.172104,0.019041,-0.147965,-0.780329,0.030815,0.121862,0.217012,-0.542831,0.450472,-0.281133,0.251235,0.203049,-0.257226,-0.314561,0.506275,0.194746,0.074478,-0.109499,-0.046715,-0.480795,0.015325,0.441880,-0.050507,-0.268684,-0.079356,-0.167366,-0.309930,-0.137851,0.071420,-0.299645,-0.251825,0.229786,-0.065624,-0.028197,0.471068,-0.764030,0.121392,-0.550278,-0.274962,0.109722,-0.361274,-0.079432,-1.033829,-0.166932,-0.020635,-0.441147,-0.113613,0.148246,-0.308239,0.520707,-0.954518,0.204114,0.664989,0.346222,-0.278717,0.094046,0.371870,0.183487,-0.272390,-0.282640,0.536831,0.141822,0.201523,0.019831,0.555982,0.085040,-0.215525,-0.182913,0.355297', '3178770', '20274039', '11541282', '3008263');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26384292', '无敌原始人', '喜剧', '《无敌原始人》讲述了原本生活无忧无虑的 “石器时代”部落原始人，遭到了“青铜时 代”部落的攻击和放逐，无家可归的他们在 勇气十足的原始人道格的带领下团结一致， 为了夺回属于自己的家园，用足球赛的形式 向“青铜时代”部落宣战，一场石器时代与 青铜时代两个部落间的世纪对决即将上演……', '汤姆·希德勒斯顿', '尼克·帕克', 6.2, 7980, 'tt4701724', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2537032871.jpg', 2, 16.8, 57.1, 19.7, 4.3, '0.420512,0.061480,-0.416996,0.687245,0.105822,-0.006741,0.572726,-0.138553,-0.095020,-0.113004,0.285419,1.077501,0.219123,0.108163,0.416389,-0.348964,-0.385611,-0.736655,-0.605267,0.071805,-0.318519,-0.004090,-0.140042,-0.361317,-0.034952,-0.491758,0.808468,-0.018171,-0.566321,0.515421,0.036047,0.431233,-0.273826,0.014971,-0.442575,-0.244811,-0.185388,0.191563,-0.694161,0.283187,-0.472444,0.212367,-0.284497,0.475267,-0.187074,0.195127,0.879932,-0.797606,0.317116,-0.609423,0.147887,-0.178214,-0.201522,0.236437,0.799083,-0.031681,-0.058400,0.393579,0.215726,-0.054129,-0.071568,-0.368748,-0.991554,0.003675,0.068965,-0.128773,-0.681250,0.554911,0.606108,0.214330,0.436184,-0.074746,0.421327,1.127491,0.685208,0.613009,-0.027629,-0.137623,-0.519375,0.269129,1.187282,-0.220383,-0.514860,-0.085938,0.138184,-0.621740,-0.228710,-0.310457,-0.607145,-0.281964,0.113410,-0.105737,-0.208657,0.417665,-1.327053,0.217244,-0.184810,-0.689280,0.518732,-0.604069,-0.312816,-0.707255,-0.226289,-0.292710,-0.136595,0.317539,0.099824,0.150583,0.766465,-0.731868,0.215940,0.273476,0.570611,-0.320800,0.723213,-0.160066,-0.120850,-0.154973,0.032540,0.240508,0.085357,0.540866,0.006390,0.181925,-0.274546,0.403191,-0.213892,0.773613', '26290398', '1849026', '1298694', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26384363', '张震讲故事之鬼迷心窍', '悬疑', '英俊的钟宇（张翰 饰）在戏班里拜杨贺天（张皓然 饰）为师，潜心学习唱念做打。某天，和钟宇相识二十多年的美丽女孩晓来（张俪 饰）来戏班找他，而杨贺天从见面第一眼起就迷上了对方。他尝试着让钟宇把晓来找出来，不过却没有成功。他内心的欲望无法抑制，于是想出了歪门邪道的办法接近女孩。 他装鬼吓唬对方，让晓来惊慌失措，从而对及时赶到的杨贺天产生了依赖。谁知这种办法一发不可收拾，晓来和名叫念念（李心艾 饰）的女孩同住，在此之后她们经常被各种可怕的噩梦和幻影幻听所烦扰。晓来内心因沉睡已久的心魔被唤醒，念念的一段黑暗过去也被挖了出来。欲望让男男女女走向万劫不复……©豆瓣', '张翰', '徐正超', 3.3, 5180, 'tt4838194', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2251719698.jpg', 59.5, 25.7, 9.9, 1.9, 3, '0.262171,0.131930,-0.704726,0.331133,-0.239127,-0.284489,0.789365,-0.195252,-0.483677,-0.194625,-0.259161,0.330535,-0.281966,0.420862,0.155645,0.048780,-0.098882,-0.676375,0.037133,-0.094513,-0.097537,-0.053622,-0.150922,0.023661,-0.175152,-0.252222,0.328598,0.086128,-0.257397,0.358416,0.185971,0.344121,-0.018920,0.338969,-0.083247,0.142881,-0.331136,-0.167524,-0.224564,0.265668,0.330792,-0.293038,-0.303998,0.466474,-0.259068,0.166772,0.696353,-0.308173,-0.194673,0.064917,0.175153,-0.255089,-0.129295,0.357106,-0.019161,0.065778,0.119112,-0.102551,-0.310738,0.203499,0.081352,0.234939,-0.632433,0.322097,-0.096670,-0.044400,-0.452070,0.189977,0.027019,-0.017204,0.129324,-0.490416,0.082789,-0.009254,0.176146,0.233669,-0.537899,-0.041005,-0.425303,0.232706,0.661358,0.034139,-0.018229,0.296725,0.053880,-0.169933,0.106538,-0.176055,-0.327021,-0.023085,0.428182,0.234455,-0.512016,0.018336,-0.475565,0.069149,-0.342593,0.154999,-0.055632,-0.369057,-0.242577,-0.248141,-0.367721,0.021799,-0.191980,-0.054526,-0.063565,-0.256428,0.419008,-0.805553,0.316947,0.564037,0.280558,-0.301090,0.463070,-0.007116,-0.266131,-0.085037,0.086211,0.093736,-0.032908,0.477473,0.128291,0.412967,0.041763,0.183796,-0.309611,0.311924', '1301022', '1947080', '21619567', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26384493', '以女儿之名', '剧情', '影片根据法国的一个真故事改编，1982年7月的一天，男主得知了女儿的死讯。他的女儿只有14岁了，在去世之前在德国和妈妈、继父一起度假。不过很快，她的死亡状况出现了疑点。生父为了女儿的真实死因跟法国法院和德国检察院纠缠了30年，但德国一直不肯引渡女儿的继父到法国进行审判，最后还是生父把他绑架到法国，才得以审判。', '丹尼尔·奥特伊', '文森特·贾洪', 8.4, 30120, 'tt4228810', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2555039846.jpg', 0.1, 0.6, 12.4, 53.8, 33.1, '-0.031954,-0.073014,-0.895855,0.650387,-0.239725,-0.611499,0.359477,-0.001601,-0.804777,-0.304212,0.254434,0.941401,-0.214224,0.658756,0.469375,0.153378,-0.491759,-0.792073,0.160434,-0.360995,-0.524463,-0.695387,-0.136385,-0.250814,0.022300,-0.221280,0.579459,-0.008272,0.256126,0.139723,0.203288,0.286972,-0.095743,0.372865,-0.264547,0.166727,0.225234,0.217226,-0.509790,0.415991,0.413834,-0.536573,-0.136843,0.073283,-0.084373,0.446782,0.653454,-0.183762,-0.119473,-0.299187,0.591732,-0.459860,-0.334055,0.105258,0.543789,-0.049499,0.364304,0.635557,-0.357446,-0.409797,-0.254680,-0.269731,-0.262726,0.047300,0.009811,-0.015672,-0.512228,0.369285,-0.444342,0.336842,0.153214,-0.518829,0.247225,0.726940,-0.080361,0.670439,-0.628897,0.016238,-0.656501,0.449671,0.855303,-0.277240,-0.204526,0.216129,0.054631,-0.448148,-0.081800,-0.560961,-0.317989,0.469902,0.218778,0.119012,-0.615196,0.234701,-0.518736,-0.365377,-0.326987,-0.292878,0.251189,-0.393522,0.060299,-0.245774,-0.385967,-0.486878,-0.238570,0.071398,0.092915,-0.133046,0.812031,-0.648119,0.416339,0.750861,0.602384,-0.682237,0.738329,0.324942,0.006441,-0.370876,0.243669,0.279914,-0.058165,0.102579,0.223481,0.084074,0.136737,-0.084851,-0.409538,0.317429', '1299811', '25721544', '1299584', '35461732');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26384515', '这里的黎明静悄悄', '剧情', '故事发生在1942年的夏天，瓦斯柯夫准尉（皮欧特·费奥多罗夫 Pyotr Fyodorov 饰）带领着他的女机枪手们驻扎在一处偏远的村庄中，某日，班长丽达（阿纳斯塔西娅·米库齐娜 Anastasiya Mikulchina 饰）意外的撞破了两个德国士兵要袭击苏联重要军事基地的阴谋，她火速将这一消息带回了部队中。瓦斯柯夫准尉带领着丽萨（索菲亚·列别杰娃 Sofya Lebedeva 饰）、迦尔卡（克里斯蒂娜·阿斯姆斯 Kristina Asmus 饰）、索妮娅（雅戈尼娅·库兹涅佐娃 Agniya Kuznetsova 饰）、冉妮娅（叶夫根尼娅·马拉霍娃 Zhenya Malakhova 饰）和丽达，这五名部队里的精锐人员前往丛林之中一探究竟，等待着姑娘们的，除了狡猾的敌人外，还有非常恶劣的自然环境。©豆瓣', '彼得·费奥多罗夫', '列纳特·达夫列吉亚罗夫', 8, 27412, 'tt4629032', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2262316531.jpg', 0.3, 1.7, 21.9, 50.6, 25.5, '0.539221,0.035959,-0.825694,0.543953,0.180058,0.116064,0.761249,0.038483,-0.454833,-0.213665,0.415260,0.346767,0.121265,-0.061003,0.412687,0.355707,-0.845149,-0.464814,-0.278387,-0.334317,-0.537485,-0.513496,-0.485406,-0.380038,0.029668,-0.479854,0.006868,-0.030444,0.230610,0.301130,0.359727,0.471460,-0.221179,0.180957,0.136086,0.194053,0.667574,-0.495075,0.060262,0.229386,-0.374038,0.029772,-0.280240,-0.131834,0.274179,0.415546,0.631264,-0.486667,0.482546,-0.152662,-0.238486,-0.108388,0.306407,0.221539,0.417002,-0.282069,0.173287,0.069540,-0.128842,0.190676,0.101482,-0.146450,-0.318586,0.065493,0.138235,0.305029,-0.506272,0.235507,-0.274382,0.109080,0.395284,-0.270548,0.127724,0.511196,0.025249,0.145166,0.029961,-0.143052,-0.470456,-0.102606,0.348570,-0.183675,-0.126193,-0.319031,-0.426333,-0.429883,0.015683,-0.050906,-0.516124,-0.194769,0.493092,-0.202300,0.253423,0.289026,-0.752604,0.094738,-0.330982,-0.218860,-0.353425,0.093429,-0.247220,-0.688184,0.210573,-0.424423,-0.356151,0.402418,0.007071,0.317675,0.712821,-0.291182,0.173547,0.604546,0.201999,0.011473,0.383523,-0.028182,0.358457,0.190194,-0.148913,0.340288,0.056295,0.220995,0.010443,0.868009,-0.268971,-0.603534,-0.251380,0.171962', '1297659', '21349734', '4706257', '1394176');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26384741', '湮灭', '剧情', '莉娜（娜塔莉·波特曼 Natalie Portman 饰）是一名生物学家，一年前，她的丈夫凯恩（奥斯卡·伊萨克 Oscar Isaac 饰）在参加一项秘密任务后神秘失踪，这一年间，莉娜一直生活在悲伤之中。某天，失忆的凯恩忽然出现在了莉娜的面前，之后晕倒被送入了医院。在那里，莉娜遇见了文崔斯博士（詹妮弗·杰森·李 Jennifer Jason Leigh 饰）。博士告诉莉娜，凯恩被派往了一块被“闪光”笼罩的未知区域，三年间，无数的队伍被派往区域内进行勘探，只有凯恩一人活着回来了。不仅如此，“闪光”正在不断的扩大。为了查明事情的真相，莉娜自愿加入了下一批被派遣的队伍之中，和她一同前往的，除了文崔斯博士外，还有安雅（吉娜·罗德里格兹 Gina Rodriguez 饰）和乔茜（泰莎·汤普森 Tessa Thompson 饰）。©豆瓣', '娜塔莉·波特曼', '亚历克斯·加兰', 7.2, 344900, 'tt2798920', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2516914607.jpg', 1, 5.7, 38.6, 43.1, 11.6, '0.327603,0.256450,-0.820244,0.561634,0.126540,-0.355394,0.807881,-0.020073,-0.467248,-0.447999,-0.047280,0.626420,-0.287835,0.342174,0.273175,0.109053,-0.520880,-0.740408,-0.257850,-0.520586,-0.685257,-0.604779,-0.090574,-0.022971,-0.153984,-0.416018,0.332253,0.002261,-0.003757,0.500560,0.347089,0.616804,-0.290381,0.308000,0.134642,0.160621,0.708020,-0.197562,-0.143134,0.450081,0.186683,-0.299358,-0.027246,-0.024682,0.196166,0.150233,0.736183,-0.208456,0.263924,-0.314441,-0.050346,-0.069295,0.007130,0.085009,0.427531,0.025799,0.215230,0.239384,-0.284051,0.072590,0.341911,-0.296770,-0.445300,0.181508,0.018009,0.303387,-0.690349,-0.036850,-0.188879,-0.130897,0.113333,-0.409617,0.327826,0.749696,0.105423,0.139437,-0.174783,0.018677,-0.470610,0.088562,0.592914,-0.087077,0.008821,-0.051926,0.036850,-0.341293,-0.040775,0.274383,-0.257927,0.167205,0.668103,0.108228,0.078591,0.300658,-0.682953,-0.059435,-0.470229,-0.428054,-0.173757,-0.186535,-0.311125,-0.820188,0.110010,-0.087031,-0.316852,0.104093,-0.058040,-0.217236,0.354760,-0.627295,0.517280,0.181512,0.278147,-0.364934,0.523481,-0.156482,0.350250,-0.118781,0.105842,0.206070,0.274631,0.360044,0.379742,0.369448,-0.089961,-0.253244,-0.628853,0.267906', '1297659', '21349734', '3735015', '27093707');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26385107', '五十度黑', '喜剧', '汉娜（凯莉·霍克 Kali Hawk 饰）是一名单纯善良的女大学生，一直以来过着平凡而又平静的生活。某日，在阴差阳错之下，汉娜肩负起了一宗采访工作，她所要采访的对象，是名为格雷（马龙·韦恩斯 Marlon Wayans 饰）的企业家，年仅二十七岁的他已经站在了事业的最顶峰，是众人目光和赞美的焦点。实际上，格雷拥有一段十分灰暗的过去，受到童年时代阴影的影响，格雷在恋爱上有着扭曲的认识和癖好，沉迷于调教游戏中无法自拔，享受着身为“主人”的快感。天真直率的汉娜激起了格雷征服的欲望，相互吸引的两人签订了“主仆协议”，而初尝禁果的汉娜亦发现自己在欲望的漩涡之中越陷越深。©豆瓣', '马龙·韦恩斯', '迈克尔·泰兹', 4.8, 5872, 'tt4667094', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2286154000.jpg', 21.6, 33.9, 31.3, 8.3, 4.9, '0.427452,-0.002585,-0.835218,0.673671,-0.253079,-0.326399,0.960518,0.302798,-0.586039,-0.075745,0.186528,0.547475,-0.358560,0.415462,0.472196,0.004481,-0.146040,-0.696358,-0.338320,-0.148138,-0.020422,-0.499696,-0.251919,0.117395,-0.328440,-0.606672,0.819999,-0.069533,-0.319893,0.412286,0.584731,0.426470,-0.043129,0.625903,-0.001600,-0.254046,0.226237,-0.005631,-0.297534,0.095604,-0.112797,-0.222642,-0.110923,0.268296,-0.246549,0.166345,0.736192,-0.302912,-0.049810,-0.109144,0.415401,-0.236075,-0.135579,0.297942,0.331539,-0.033570,0.053491,-0.011697,-0.102701,0.032637,0.000129,-0.083405,-0.712865,-0.294989,-0.030670,0.316830,-0.636687,0.634740,0.237958,-0.243461,0.077425,-0.393065,-0.025816,0.156503,0.233456,0.420280,-0.127403,0.180805,-0.300349,0.212669,0.654449,0.292257,-0.574295,0.499617,-0.653084,-0.590630,-0.198667,-0.237093,-0.725132,-0.348180,0.392407,0.223744,-0.136959,0.572710,-0.667055,0.103674,-0.150077,-0.272317,-0.029262,-0.602457,-0.201271,-0.634927,-0.497942,-0.652013,-0.412608,-0.071523,-0.074139,-0.446882,0.769975,-1.094634,0.436836,0.632533,0.031019,-0.130438,0.714703,0.381714,-0.033800,-0.253249,-0.354133,0.555040,0.020231,0.066988,0.005022,0.370599,-0.236009,0.099062,-0.477309,0.716758', '24708493', '35030151', '26354526', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26385514', '性别为本', '剧情', '鲁斯（菲丽希缇·琼斯 Felicity Jones 饰）渴望成为一名律师，并且凭借着自己的努力考上了哈佛大学的法学院。在法学院里，鲁斯因为身为女性而遭到了来自各方面的歧视和压力，只有他的丈夫马丁（艾米·汉莫 Armie Hammer 饰）坚定的支持着妻子的选择，因为他明白，鲁斯充满了天赋和正义感。马丁被查出患上了癌症，病愈之后，他带着孩子们前往纽约工作。为了能够和自己的家人们生活在一起，鲁斯向学校提出希望能够转去哥伦比亚大学完成学业，却被拒绝了。之后，鲁斯离开了哈佛，成为了罗格斯大学的法学教授，可即便她是这样的优秀，依然没有律师行肯聘用她，只因为她是一个女人。©豆瓣', '菲丽希缇·琼斯', '米密·莱德', 7.8, 15046, 'tt4669788', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2528153937.jpg', 0.4, 2.7, 28.3, 45.4, 23.2, '0.355859,0.109414,-0.783178,0.680500,-0.316560,-0.433131,0.737357,0.249372,-0.697480,-0.210688,0.045350,0.960839,0.239054,0.398704,0.188812,0.088397,-0.330865,-0.675411,0.183450,-0.303696,-0.213331,-0.687183,-0.236877,-0.120372,-0.317576,-0.549053,0.557633,-0.160631,-0.110392,0.556375,0.316856,0.626203,0.496979,0.545364,-0.097703,-0.130746,0.236854,-0.018242,-0.214518,0.557300,0.518897,0.007228,-0.186024,0.080395,0.164228,0.217185,0.531831,0.150791,0.051105,-0.215638,0.320986,-0.418043,-0.041362,0.425151,0.218017,-0.052085,0.325528,0.310954,-0.073742,0.014848,0.149784,-0.033696,-0.776135,-0.139418,0.248812,0.326500,-1.004209,0.545874,-0.191162,-0.369336,0.079699,-0.396202,-0.048732,0.308795,0.058834,0.449882,-0.285048,0.304303,-0.683141,0.151878,0.686103,-0.135171,-0.365677,0.044317,-0.236769,-0.524664,0.074822,-0.303502,-0.575441,-0.021681,0.327301,0.210651,-0.302408,0.112397,-0.458029,-0.227091,-0.334301,-0.345196,-0.177702,-0.558230,0.119130,-0.468626,0.095183,-0.348625,-0.512595,-0.152057,-0.021848,-0.441915,1.050130,-1.152090,0.299411,0.503616,0.717802,-0.609104,0.903520,0.252375,0.271215,-0.131833,-0.065357,0.363867,-0.001345,0.464475,0.178578,0.521127,0.210617,-0.379684,-0.249639,0.699133', '1292720', '35030151', '26387939', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26385940', '坏妈妈', '喜剧', '所有人都以为，艾米（米拉·库妮丝 Mila Kunis 饰）拥有着幸福美满的婚姻生活——恩爱的丈夫，乖巧的孩子，优渥的生活条件，但只有艾米自己知道，为了维系这看似光鲜的表象，她的内心早已经精疲力尽。丈夫把所有的家务事都一股脑的甩在她的头上，在处理这些琐事的同时，艾米还必须兼顾着去讨好她周围其他的妈妈们。终于有一天，艾米再也受不了她的生活了，她离开了家庭，抛弃了丈夫和孩子，带着闺蜜琪琪（克里斯汀·贝尔 Kristen Bell 饰）和卡拉（凯瑟琳·哈恩 Kathryn Hahn 饰），两名同样受到生活疯狂压榨的家庭主妇，三人踏上了一条疯狂的狂欢之路。©豆瓣', '米拉·库尼斯', '乔恩·卢卡斯', 6.5, 10849, 'tt4651520', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2342879096.jpg', 2, 11.4, 52.9, 26.3, 7.5, '0.380200,-0.195984,-0.607909,0.367906,-0.409126,-0.476166,0.735871,0.226358,-0.275379,-0.081597,0.407233,0.563145,-0.102665,0.337877,0.234119,0.079900,-0.590416,-0.701658,-0.070196,-0.058805,-0.093090,-0.326610,-0.052944,-0.146851,-0.253959,-0.311643,0.407831,-0.293278,0.124173,0.343892,0.184026,0.129167,-0.041766,0.383758,-0.279863,0.222308,-0.008142,-0.244734,-0.084356,-0.130097,0.123948,0.041315,-0.104518,0.328306,0.175230,0.274729,0.729830,-0.364068,0.095054,0.033154,0.275256,-0.254297,0.227211,0.432464,-0.059885,-0.025362,0.248658,0.115043,-0.332666,0.039433,0.514167,0.023244,-0.781519,0.001803,0.065301,0.174221,-0.743535,0.613336,0.021050,-0.180994,0.320964,-0.543219,0.071468,0.470366,-0.144067,0.688015,-0.395351,0.135257,-0.619161,0.175336,0.655819,-0.025452,-0.220767,0.244695,-0.480441,-0.143783,-0.105492,-0.288029,-0.968289,-0.407402,0.338802,0.041997,-0.253550,0.513612,-0.620831,0.220971,-0.124347,-0.538248,0.045051,-0.537556,-0.076604,-0.577142,-0.063631,-0.620952,-0.592401,-0.009699,0.002111,-0.261715,0.830223,-0.738251,0.346030,0.593477,0.359296,-0.600604,0.557987,0.040963,0.342281,0.138475,-0.054220,0.429208,-0.017884,0.422969,0.288073,0.457571,0.029785,0.190840,-0.261562,0.843742', '26348103', '34875369', '4058963', '26926321');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26386034', '极寒之城', '动作', '影片根据安东尼·约翰斯顿（Antony Johnston）的同名小说改编，讲述了“冷战”结束前的间谍行动：1989年，民主德国局势发生急剧变化，“柏林墙”面临拆除的命运，但此时也是最黑暗的时刻，各种暗杀行动时有发生。一位英国军情六处的地下官员在柏林遇刺，他掌握了从民主德国带回来的一份间谍名单，但杀手在他身上并未找到。一位名叫洛林·布劳顿（塞隆 饰）的特工，肩负起找回这份间谍名单的任务。此前曾报道，导演雷奇和斯塔尔斯基将会拍摄《疾速追杀》续集，基努·里维斯在内的主演均将回归。但在拍摄该片之前，两人会先着手将这部女性角色挑大梁的动作惊悚片搬上银幕。', '查理兹·塞隆', '大卫·雷奇', 7.2, 66737, 'tt2406566', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2461815940.jpg', 0.8, 5, 39.1, 41.6, 13.6, '0.187902,-0.253546,-0.482287,0.578723,0.369294,0.000057,0.478657,0.098358,-0.383290,-0.516921,0.519471,0.714567,-0.318809,-0.260946,0.597670,-0.291672,-0.636630,-0.763654,-0.306031,-0.124680,-0.263813,-0.447101,-0.394805,-0.190966,-0.105658,-0.366786,1.071491,0.277742,-0.338478,0.342120,0.177427,0.161960,-0.234493,0.262571,0.013173,-0.038174,0.266889,-0.212543,-0.328062,0.349708,0.198653,-0.395349,-0.234433,0.163087,0.259730,0.515607,0.678349,-0.177577,-0.020445,0.098510,0.514322,-0.383193,-0.026412,-0.146832,0.479967,0.345202,0.007566,0.364185,-0.117814,0.192709,-0.141068,-0.360322,-0.748415,-0.075989,0.136996,0.494236,-0.399831,0.087939,-0.369093,0.507045,-0.094537,-0.333786,0.336024,0.438123,0.342046,0.073745,0.122823,0.101317,-0.322906,0.208246,0.551353,-0.246605,0.005201,0.145599,-0.013630,-0.433679,-0.227214,-0.199199,-0.330339,0.268049,0.195185,-0.034084,-0.018337,0.374840,-0.480530,-0.285720,-0.302217,-0.425604,0.052590,-0.321237,-0.003704,-1.105203,-0.361556,-0.057503,-0.013893,-0.057657,0.276938,-0.180648,0.667288,-0.501454,0.148340,0.435445,-0.124904,-0.440092,0.350520,0.107026,0.251057,-0.264418,0.160075,0.236565,0.306843,0.267635,-0.061654,0.227523,-0.025470,-0.457381,-0.293883,0.122505', '2369613', '20274039', '3266509', '26990609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26386434', '告别单身', '剧情', '朱妍（金惠秀 饰）曾经是红极一时的女明星，凭借着自己美丽的外表和精湛的演技虏获了大批粉丝们的芳心。可是，随着时间的推移，衰老的痕迹不可抗拒的爬上了她的眼角，人气渐渐低迷的她不可自持的开始为自己的未来担心起来。更糟糕的是，朱妍的爱情道路一直都障碍重重，她吃过亏、摔过跤，却至今形单影只，这为她又增加了新的一层焦虑。在好友平九（马东锡 饰）的建议和帮助之下，朱妍自导自演了一场“怀孕”事件，哪知道一石激起千层浪，大批的母婴用品商家找到了朱妍想要请她代言，朱妍的事业迎来了第二春。可是，怀孕始终只是一个谎言，朱妍该怎样才能守住她的“小秘密”呢？©豆瓣', '金惠秀', '金泰昆', 6.6, 5028, 'tt6299228', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2355436851.jpg', 1.3, 10.4, 53, 27, 8.3, '0.030308,0.262863,-0.689869,0.571077,-0.074106,-0.262918,0.547752,0.155707,-0.406461,-0.072067,0.046586,0.432038,-0.286973,0.245771,-0.049992,0.005491,-0.264458,-0.696462,0.103733,-0.250110,-0.227890,-0.146718,-0.585320,-0.056575,-0.125685,-0.212331,0.558546,0.285334,-0.290379,0.262905,0.492708,-0.046551,0.314946,0.436277,-0.240026,0.153264,-0.005259,-0.011982,-0.076260,-0.058009,0.284691,-0.586157,-0.214279,0.362609,-0.034113,0.510836,0.470550,-0.101999,-0.246353,0.061146,0.433444,-0.340892,0.184256,0.167296,0.193815,0.030586,0.191945,0.097880,-0.196897,0.139880,0.125389,0.050291,-0.976706,0.005135,0.249594,0.196978,-0.722571,0.460032,-0.227951,-0.125946,-0.041106,-0.388107,0.076200,0.335750,0.047026,0.365386,-0.495974,-0.056056,-0.393770,0.291932,0.612666,0.276820,-0.183087,0.569863,-0.261976,-0.326002,-0.116688,-0.230849,-0.432415,0.076362,0.327090,0.146230,-0.102985,0.262212,-0.616134,0.080593,-0.349882,-0.300914,-0.221802,-0.256395,-0.170620,-0.262877,-0.211677,-0.610802,-0.242416,0.029254,0.134595,-0.321475,0.895776,-0.721020,0.021166,0.562619,0.360110,-0.705729,0.480426,0.316424,-0.095995,0.014840,-0.222372,0.103138,-0.337054,0.223950,0.086705,0.468741,-0.077543,-0.146597,-0.483268,0.539567', '24284209', '30163500', '27602116', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26386465', '亚人1：冲动', '剧情', '“亚人”是1980年代开始渐渐出现在人类视野之中的新人种，他们源自于人类，有着和人类一样的外貌，却有着不老不死的肉身，只有一个人类死亡之后，才能够判断他是否为亚人。人类恐惧亚人身上所蕴藏的强大力量，对他们发起了严酷的追捕和研究。永井圭（宫野真守 配音）是一位平凡的少年，拥有高超的智商和优秀的成绩，某日，在一场交通事故中，永井圭不幸丧生，随后变为亚人，遭到了军方的通缉。在童年好友海斗（细谷佳正 配音）的帮助下，永井圭踏上了逃亡的旅途，期间遇到了身份神秘的帽子男佐藤（大冢芳忠 配音），虽然佐藤和永井圭同为亚人，但不知为何，佐藤将永井圭视为了敌人。©豆瓣', '宫野真守', '濑下宽之', 8.6, 10980, 'tt5234428', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2267694939.jpg', 0.4, 1.1, 11.4, 43, 44.2, '0.169450,0.061277,-0.489641,0.617795,-0.394321,0.029035,0.695213,-0.074320,-0.483671,-0.362971,0.348003,0.950478,0.006734,0.235540,0.062825,-0.125048,-0.242317,-0.580611,-0.208978,-0.211990,-0.456722,-0.509143,-0.503232,-0.088635,-0.216404,-0.628195,0.951943,0.201180,-0.509459,0.351329,0.119610,0.543017,-0.291470,0.392788,-0.279032,-0.147876,0.157101,0.000756,-0.121358,0.301557,-0.118219,-0.237949,-0.022213,0.237255,-0.286629,0.215544,0.739147,-0.361416,-0.224944,-0.317154,0.450382,-0.369649,-0.144281,0.246460,0.558254,0.026514,0.102131,0.112076,0.144260,-0.035260,-0.015733,-0.031719,-1.002732,-0.081878,0.192693,0.219876,-0.377424,0.372161,0.109321,-0.337415,0.329559,-0.270541,-0.016265,0.226960,0.467354,0.399488,-0.076844,0.055541,-0.338120,-0.208702,0.829320,-0.069701,-0.476600,0.315805,-0.285578,-0.767911,-0.322125,-0.378528,-0.481781,0.072129,0.177169,0.290152,-0.154761,0.421503,-0.672747,0.152001,-0.131241,-0.152627,0.046174,-0.310522,-0.164562,-0.372445,-0.314549,-0.788853,-0.455940,0.165722,0.273010,-0.424526,1.049199,-1.109714,0.147837,0.551416,0.243576,-0.337084,0.439039,-0.002435,-0.103173,-0.001157,-0.032465,0.170577,0.226967,0.222392,-0.010732,0.271868,-0.119510,0.144770,-0.301137,0.565771', '24284209', '27602116', '25880986', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26386691', '俺物语', '喜剧', '刚田猛男（铃木亮平 饰）人如其名，是一名拥有两米身高而两百斤体重的魁梧高中生。在学校里，猛男深受社团后背的信赖，是后辈们心目中不可撼动的偶像，可在女孩子眼里，样貌狰狞凶恶的猛男，无意是噩梦般的存在，任谁被他看上一眼就会感觉背后发冷。猛男的身边总是存在着一个非常不和谐的身影，那就是猛男从幼儿园开始就在一起玩耍的青梅竹马砂川诚（坂口健太郎 饰），砂川诚是一位标准的美男子，一个粗犷一个俊美，两人成为校园中一道奇异的风景线。而砂川诚屡屡拒绝女生的告白不为别的，只因为她们都在背后说过猛男的坏话。某日，猛男遇见了名为大和凛子（永野芽郁 饰）的女生，以为凛子也喜欢上了砂川诚的猛男决意撮合两人，却发现凛子真正的目标似乎是自己？©豆瓣', '铃木亮平', '河合勇人', 7.4, 12629, 'tt4681414', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2254977828.jpg', 0.6, 4.6, 36.6, 40.5, 17.6, '0.462945,-0.317704,-0.493448,0.553168,-0.345451,-0.192997,0.983770,0.058272,-0.508769,-0.151471,0.308435,0.718832,-0.297312,0.469270,0.122619,0.215923,0.192396,-0.664706,-0.475914,-0.075720,-0.251668,-0.129282,-0.254249,0.011196,-0.238713,-0.299973,0.562386,-0.178083,-0.357610,0.603132,0.644134,0.143397,-0.061712,0.391729,-0.563076,-0.242132,0.026555,0.048600,0.210912,0.178044,-0.262727,-0.293548,-0.090606,0.311542,-0.364676,0.198980,0.495002,-0.050975,-0.144410,-0.149927,0.343579,0.062853,-0.155449,0.145518,0.434815,-0.251402,0.490472,-0.131702,0.131612,0.053693,0.134225,-0.008995,-0.512631,0.048991,0.154020,0.392333,-0.454255,0.533401,0.050456,-0.445281,0.357975,-0.148619,0.218747,-0.184822,0.266541,0.263287,-0.235102,0.247844,-0.618202,0.164931,0.606488,0.494756,-0.299095,0.085396,-0.387661,-0.496479,-0.276074,-0.277461,-0.547207,-0.081014,-0.090945,-0.047130,-0.064902,-0.031917,-0.457573,0.227919,0.104065,0.144760,-0.217693,-0.461459,-0.292952,-0.245642,-0.205074,-0.620418,-0.333489,0.479459,0.058192,-0.316292,0.937758,-0.906920,-0.010560,0.544408,0.314891,-0.014951,0.973045,0.184876,-0.212146,-0.187879,-0.079707,-0.088564,0.326432,-0.346937,-0.112437,0.650099,-0.324987,-0.183182,-0.441161,0.551657', '1292062', '3055049', '3230462', '2081098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26387939', '摔跤吧！爸爸', '剧情', '马哈维亚（阿米尔·汗 Aamir Khan 饰）曾经是一名前途无量的摔跤运动员，在放弃了职业生涯后，他最大的遗憾就是没有能够替国家赢得金牌。马哈维亚将这份希望寄托在了尚未出生的儿子身上，哪知道妻子接连给他生了两个女儿，取名吉塔（法缇玛·萨那·纱卡 Fatima Sana Shaikh 饰）和巴比塔（桑亚·玛荷塔 Sanya Malhotra 饰）。让马哈维亚没有想到的是，两个姑娘展现出了杰出的摔跤天赋，让他幡然醒悟，就算是女孩，也能够昂首挺胸的站在比赛场上，为了国家和她们自己赢得荣誉。就这样，在马哈维亚的指导下，吉塔和巴比塔开始了艰苦的训练，两人进步神速，很快就因为在比赛中连连获胜而成为了当地的名人。为了获得更多的机会，吉塔进入了国家体育学院学习，在那里，她将面对更大的诱惑和更多的选择。©豆瓣', '阿米尔·汗', '涅提·蒂瓦里', 9, 1473772, 'tt5074352', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2401676338.jpg', 0.2, 0.5, 6.8, 32.9, 59.6, '0.030367,0.137205,-0.772071,0.826776,-0.268418,-0.495860,0.420713,-0.006858,-0.426268,-0.070102,0.210334,1.029391,-0.073629,0.058086,0.072839,-0.342828,-0.280547,-0.788141,-0.006200,-0.157888,-0.589957,-0.475456,-0.181128,-0.041171,-0.431416,-0.529649,0.573727,0.037092,-0.177708,0.406863,0.614774,0.211920,0.409136,0.215986,-0.446871,0.015926,-0.004300,0.009109,-0.152420,0.427279,0.274878,-0.034499,-0.322057,0.248768,0.354113,-0.080093,0.591024,-0.305943,0.086058,-0.114065,0.273945,-0.209142,0.123524,0.115334,0.151253,-0.237011,0.208715,0.123660,-0.137906,0.132541,0.229123,-0.122191,-0.921069,0.137220,0.152490,0.008120,-1.031556,0.631649,-0.010395,-0.433689,0.274380,-0.162739,0.206402,0.615828,0.045304,0.320510,-0.261343,-0.200404,-0.632898,0.097528,0.591880,-0.109571,-0.129458,0.288136,-0.115466,-0.630948,-0.038361,-0.426875,-0.156084,0.133630,0.441883,0.194921,-0.086164,0.143156,-0.361666,0.183925,-0.263262,-0.440406,-0.084708,-0.615505,0.090720,-0.337964,0.068032,-0.386660,-0.346990,0.251214,0.029039,-0.399256,1.009839,-1.079473,0.093696,0.423686,0.484187,-0.454230,0.712340,0.075631,0.273518,-0.116071,-0.032817,0.015376,0.003428,0.370586,0.250286,0.578355,0.057253,-0.183612,-0.384984,0.889726', '1870681', '21360412', '35048413', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26388342', '好邻居', '惊悚', '两高中生恶作剧，潜入一退伍老人房中，安放了一些监控设备及控制房间照明、门窗、音响等的设备。接下来遥控这些设备，给老人造成屋中有鬼等现象，以查看老人反映。而老人的各种反常的行为更是让他们感到事情的异常……', '詹姆斯·肯恩', 'Kasra Farahani', 7.3, 9576, 'tt2262315', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2374050235.jpg', 1.1, 4.7, 37.7, 42.9, 13.6, '0.457066,-0.357601,-0.388190,0.270585,0.019885,0.151229,0.880621,0.060987,-0.849247,-0.860867,0.291383,0.380197,-0.308358,0.116145,-0.164599,-0.379645,-0.766733,-0.230149,-0.420195,-0.049951,-0.938315,-0.217165,0.143749,-0.518974,-0.151108,-0.392409,0.281004,-0.080668,-0.258527,0.235601,-0.440459,0.004395,-0.243138,0.611521,0.259710,-0.324914,-0.076446,-0.070613,-0.059339,0.075033,-0.169762,-0.252162,-0.103768,0.301599,-0.093105,0.390306,0.881030,-0.231919,-0.464029,-0.078386,0.205240,-0.011439,-0.287694,-0.130585,0.221374,0.289049,0.054579,0.006407,-0.666336,0.166984,0.053726,0.224283,-0.547974,-0.210245,0.147855,-0.012102,-0.323189,-0.332636,-0.210537,0.135426,0.001881,-0.253485,0.341284,0.069108,0.370251,0.790253,-0.123789,-0.200798,-0.397027,-0.217428,-0.225059,-0.637776,-0.185095,0.692365,-0.308538,-0.556209,0.050111,0.264894,-0.276878,-0.197635,0.107023,0.050267,0.067047,-0.225029,-0.275922,-0.110054,-0.121252,-0.599079,-0.261676,-0.423630,-0.250797,-1.135411,-0.169345,0.002026,-0.261126,0.147309,0.238821,0.231130,0.506697,-0.448102,-0.175088,0.246340,-0.022456,-0.354148,0.186103,-0.538656,0.302625,-0.102657,-0.406805,-0.498561,0.098495,0.514760,0.088022,0.516989,-0.125818,-0.477501,-0.341706,-0.202508', '10466639', '1297659', '1307897', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26388555', '一万公里的约定', '剧情', '影片讲述了弟弟小崇（黄远饰）为挑战哥哥阿轩（王大陆饰）而踏上跑步之路，中途机缘巧合认识田径部高冷学姐以晴，小崇以晴找到新的奔跑目标，在亲情和爱情的双重激励下勇敢追逐梦想的热血故事。', '黄远', '洪昇扬', 4.6, 5429, 'tt4884914', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2405121017.jpg', 24.7, 38, 23.9, 9.1, 4.4, '-0.320205,-0.121311,-0.450410,0.960139,0.463403,-0.424075,0.156246,0.080868,-0.090387,-0.217528,0.117274,0.395221,0.093690,0.242227,0.393623,-0.429402,-0.110986,-0.586879,0.169011,0.146270,-0.488358,-0.179904,0.055798,0.002192,-0.161134,-0.628159,0.786683,0.209080,-0.548840,0.689318,0.541349,0.139253,-0.264656,0.194257,-0.327790,-0.000458,0.196308,0.569518,-0.844409,-0.064726,-0.262708,-0.055870,0.055950,0.081239,-0.133689,0.037950,0.773050,-0.369299,0.161991,-0.288962,0.327080,-0.491429,0.293192,-0.316816,0.185126,0.107196,0.279341,0.263025,0.505124,-0.241567,-0.257523,-0.357707,-0.560546,-0.053645,0.242287,0.101756,-0.552674,0.180152,-0.058389,0.113561,0.619640,-0.228672,0.011623,0.333865,0.472815,0.327681,-0.338310,-0.055349,-0.016323,0.279293,1.021887,-0.236724,0.001199,0.582341,-0.194784,-0.075453,0.450060,0.140818,-0.573090,-0.095235,0.215013,-0.023690,-0.074279,0.118137,-0.590011,0.011381,0.090148,0.025221,0.325424,-1.000930,-0.028580,-0.329673,0.158384,-0.102386,0.126930,0.127263,-0.119838,-0.712746,1.047865,-0.867235,0.116787,0.698744,0.354050,-0.861719,0.747180,-0.106652,-0.140702,-0.484788,0.359994,0.690533,-0.409064,0.141960,-0.479201,0.107343,-0.237628,0.328969,-0.902231,0.629135', '6963575', '35048413', '26021055', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26389069', '铁道飞虎', '喜剧', '1941年太平洋战争爆发以后，穿过山东境内的津浦铁路成为日军在中国大陆最重要的战略交通线之一。在津浦铁路枣庄段周边，活跃着一支民间抗日游击队，这支游击队主要由枣庄火车站的几名铁路工人组成，队长叫马原，是火车站的搬运工工头。他们白天在日本人占领并管理的火车站干活，晚上出来秘密活动，利用对铁路线的熟悉以及扒火车、开火车的特殊技能，以一支小小的游击队跟大批装备精良的日本正规军周旋较量，造成了非常大的影响，当地老百姓给这支队伍起了一个响亮的名头，叫铁道飞虎队。', '成龙', '丁晟', 5.1, 87818, 'tt4687848', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2404720316.jpg', 20, 25.6, 38.8, 11.5, 4.1, '0.353062,-0.113866,-0.827488,0.737312,-0.032382,0.055227,0.306939,-0.099647,-0.389762,0.186896,0.224042,0.586491,0.422523,-0.132254,0.235941,-0.266042,-0.024017,-0.526648,-0.073136,-0.325016,-0.339645,-0.472288,-0.462438,-0.262394,-0.050448,-0.295296,0.384125,0.482241,-0.580882,0.440242,0.231280,0.142409,-0.008688,0.235249,-0.228630,-0.289457,0.037867,-0.416827,-0.181037,0.049953,-0.474164,-0.154717,-0.143975,-0.097722,0.103335,0.260150,0.711872,-0.223047,-0.040117,-0.234287,0.118141,-0.320350,-0.126054,-0.388150,0.790382,0.262163,0.026280,0.059371,-0.141073,0.299059,-0.363295,0.004615,-0.441813,-0.057688,-0.036951,-0.131120,-0.833307,0.700511,0.118585,-0.008374,0.253980,-0.478803,0.508795,0.848174,-0.129989,0.323356,-0.166493,0.189693,-0.705087,0.279634,0.621095,-0.273004,-0.269960,-0.402203,-0.273592,-0.153354,0.058355,-0.286378,-0.070250,-0.114888,0.074073,-0.764871,0.073053,-0.124356,-0.837446,0.402744,0.046283,-0.702049,0.109545,-0.066257,-0.070203,-0.989824,0.236261,-0.361960,0.086641,0.586749,0.236317,0.420437,1.007686,-0.710630,-0.165550,0.717671,0.369543,-0.501311,0.169553,0.193589,0.339022,-0.222298,-0.197684,-0.141186,0.252071,0.691288,0.265379,0.557743,-0.490244,-0.242475,-0.287933,0.180975', '1307897', '25863940', '1307762', '2294565');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26389148', '赴汤蹈火', '剧情', '两兄弟，一个有前科，另一个是离异的父亲。他们为了应对无法赎回家族农场的窘境，决定联手谋划一连串刺激的盗窃活动。而一位经验丰富的警察开始追踪他们制造的一系列银行抢劫案，决定将他们捉拿归案。英国导演大卫·马肯兹（David Mackenzie）的新作，他曾执导《年轻的亚当》《深狱父子情》等片。本片的背景发生在德克萨斯西部，讲述一位离婚的父亲和他有前科的兄弟，一同为守护家庭农场所战斗的故事。该片被誉为继阿尔·帕西诺《热天午后》之后最好的抢劫银行电影，导演大卫·马肯兹暌违三年，再度回归犯罪题材，克里斯·派恩、本·福斯特、杰夫·布里吉斯主演，编剧是《边境杀手》的编剧泰勒·谢里丹。', '克里斯·派恩', '大卫·马肯兹', 8.1, 61474, 'tt2582782', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2351955874.jpg', 0.2, 1.3, 18.7, 53.5, 26.2, '0.290341,-0.412960,-0.437720,0.634054,0.032793,-0.362176,0.488642,0.357800,-0.428512,-0.482710,0.342244,0.949182,-0.130341,0.029646,0.279299,-0.181431,-0.423880,-0.592682,-0.156319,-0.111210,-0.016387,-0.517887,-0.412502,-0.374600,-0.009638,-0.261547,0.718867,-0.097113,-0.184722,0.174077,0.490908,0.431135,-0.076639,0.025760,0.112974,0.112821,0.388800,-0.218820,-0.729054,0.269149,-0.052522,0.041412,-0.121760,-0.005512,0.175102,0.430904,0.440016,-0.078429,0.046567,-0.120758,0.512311,-0.307837,0.053454,-0.048940,0.330840,0.020465,0.290138,0.564762,-0.165126,-0.392549,-0.135296,-0.231934,-0.891366,0.051107,0.106019,0.146083,-0.505919,0.027429,-0.197432,0.094036,0.154013,-0.166174,-0.000002,0.528154,0.421452,0.180706,0.086241,0.003080,-0.280965,0.477350,0.793714,-0.310488,-0.069001,0.181135,-0.071538,-0.346597,-0.083200,-0.252184,-0.620111,0.114527,0.433697,-0.446897,-0.016140,0.365165,-0.385555,-0.238858,-0.496180,-0.179377,0.003166,-0.190876,0.125702,-0.987289,-0.363658,-0.003467,-0.085923,-0.105251,0.295244,-0.072457,0.655779,-0.583151,0.093738,0.658929,0.188749,-0.444503,0.502231,0.195592,0.227724,-0.371821,-0.035602,0.236860,0.262284,-0.030376,0.003106,0.130621,0.145038,-0.147919,-0.140352,0.193774', '4301278', '2369613', '26990609', '1829654');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26389152', '再见，克里斯托弗·罗宾', '剧情', '故事发生在第一次世界大战结束之后，艾伦（多姆纳尔·格里森 Domhnall Gleeson 饰）完成了自己保家卫国的使命，重新回归了平静的生活之中。艾伦希望执笔重新开始写作，用文字给这个社会带来一份力量，但很快他就发现，自己似乎已经丧失了写作的能力了。与此同时，可怕的战争给艾伦的心灵带来了极大的创伤，导致他一直在被应激症折磨。无奈之下，艾伦带着妻子德芙妮（玛歌特·罗比 Margot Robbie 饰）举家搬到了乡下，希望那里优美的景色能够治愈他受伤的灵魂。儿子比利（威尔·提尔逊 Will Tilston 饰）和他挚爱的玩具小熊带给了艾伦无限的灵感，令他开始创作童书《小熊维尼》。©豆瓣', '多姆纳尔·格里森', '西蒙·柯蒂斯', 7.9, 11060, 'tt1653665', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2461791740.jpg', 0.5, 2, 24.3, 50.6, 22.5, '0.075091,0.366791,-0.615023,0.584902,-0.162313,-0.335778,0.731122,0.196155,-0.508810,-0.208159,-0.009238,0.732642,0.039190,0.310944,0.238024,0.110530,-0.511165,-0.695645,0.147660,0.144775,-0.428011,-0.361674,-0.313140,-0.119080,-0.061379,-0.758326,0.507356,0.097604,-0.155283,0.407165,-0.061378,0.343952,0.257066,0.511978,-0.070662,0.296971,-0.083628,-0.336385,-0.122235,0.232629,0.310634,-0.313189,0.032485,0.535377,-0.190179,0.110414,0.947740,-0.318874,-0.236696,-0.187117,0.570403,-0.137982,0.102869,0.079655,-0.198703,0.226073,0.069899,-0.096920,-0.263761,0.017771,0.223029,-0.094545,-0.825720,-0.255255,-0.136307,0.264009,-0.452173,0.572490,-0.140925,-0.004976,0.177650,-0.353046,0.139245,0.419477,0.358597,0.461170,-0.467716,0.038001,-0.425464,0.141349,0.395108,-0.369512,-0.375315,0.446628,-0.500050,-0.254338,-0.032169,-0.155512,-0.352221,-0.051790,0.522434,0.456229,-0.337523,0.434856,-0.651064,-0.127793,-0.260490,-0.412091,-0.147442,-0.411613,0.023938,-0.513168,-0.327384,-0.198553,-0.247852,-0.160647,0.057252,-0.401800,0.824639,-0.665879,0.538324,0.602887,0.205014,-0.133696,0.210369,-0.118353,0.241712,-0.074231,0.145769,0.458703,-0.198341,0.394106,0.480447,0.350205,0.054418,0.081723,-0.553723,1.105889', '24733428', '1309085', '1303263', '1293399');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26389321', '新变种人', '动作', '当五位拥有特殊能力的青少年被关入秘密机构，有一股超自然恶势力正蠢蠢欲动，他们必须面对过去的罪恶，但内心的恐惧即将成真。神秘的背后似乎有巨大的阴谋正在成形，他们是否能勇敢对抗自身的力量，逃脱这一切枷锁……', '麦茜·威廉姆斯', '约什·布恩', 4.4, 24022, 'tt4682266', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2582165718.jpg', 17.8, 49.5, 28.8, 3.1, 0.8, '0.030422,0.447912,-1.015903,0.326139,-0.149628,0.399099,0.686298,0.008727,-0.566871,-0.521776,0.198017,0.311780,0.132380,0.153096,-0.223406,-0.147210,0.071394,-0.709383,-0.291832,0.014327,-0.442896,-0.245766,-0.804290,-0.075793,0.026667,-0.481975,1.104196,0.543373,-0.398905,-0.248942,0.357014,0.785211,-0.294327,0.639451,-0.299060,-0.436007,0.112416,-0.175130,-0.475641,-0.063924,0.266548,-0.119431,-0.137581,0.509563,-0.319433,-0.011842,0.312134,-0.549481,-0.167415,-0.197847,0.443246,-0.219445,-0.143796,0.485844,-0.025497,0.493677,-0.022278,0.015132,0.083199,0.142191,0.221407,-0.151345,-1.428644,-0.379636,0.151562,0.242718,-0.095393,-0.278608,0.395832,-0.163120,0.302493,-0.125758,-0.227476,0.129656,0.225749,0.526539,-0.384758,0.070281,-0.805411,-0.713683,0.961873,-0.014629,-0.778813,-0.131412,-0.494258,-0.238518,-0.341021,-0.495086,-0.063851,0.021324,0.523526,0.728273,-0.033604,0.417341,-0.612559,-0.029703,-0.037592,0.423968,-0.123215,-0.554506,0.066073,-0.524102,-0.617468,-0.235086,-0.210910,0.102022,0.434580,-0.432431,0.823408,-0.751493,0.274123,0.829784,0.396642,-0.672279,0.163470,0.161790,0.030929,-0.176477,-0.463964,0.244398,-0.285553,0.496170,0.133569,0.192532,0.116636,0.130112,-0.190907,0.658752', '35377026', '30163500', '26667010', '10440076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26389329', '附属美丽', '剧情', '霍华德（威尔·史密斯 Will Smith 饰）是一名事业有成的广告公司经理，和妻子艾米（凯拉·奈特莉 Keira Knightley 饰）结婚多年，两人共同抚养这一个可爱的小女儿。一场意外夺走了小姑娘的生命，也导致了这个幸福家庭的破碎，艾米选择了离开霍华德。接二连三的打击让霍华德陷入了绝望之中，无暇顾及公司里的事情，他整日埋首写信，这些信的收件人是“爱”、“时间”和“死亡”。公司的竞争对手找到了霍华德，希望能够收购他的广告公司，这意味着公司里的每一个人都将因此而得到一大笔钱，但霍华德拒绝了这一要求，依然沉浸于写信之中。霍华德的决定惹恼了公司里的几个同事，他们决定联手策划一个阴谋来证明他们的老板已经疯了。©豆瓣', '威尔·史密斯', '大卫·弗兰科尔', 6.8, 10331, 'tt4682786', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2402462703.jpg', 2.3, 11.1, 43.3, 29.9, 13.4, '0.371677,0.218314,-0.631412,0.555538,-0.274022,-0.481723,0.716562,0.092713,-0.440004,-0.192370,-0.042758,0.901471,-0.046461,0.408160,0.251542,0.056885,-0.150475,-0.714006,-0.089213,-0.283658,-0.052128,-0.648829,-0.229520,-0.448384,0.006935,-0.005483,0.419362,0.109536,0.028582,0.556463,0.335324,0.133971,0.157958,0.497463,0.203455,0.296519,0.316742,-0.167684,-0.318445,0.479985,0.124866,-0.021268,0.107314,0.526293,0.114362,0.537659,0.432553,-0.165998,-0.132007,-0.186809,0.449039,-0.408056,-0.102620,0.313741,0.337017,-0.026004,0.373197,0.167937,-0.560851,-0.043359,0.248372,0.075367,-1.161969,-0.075295,0.006610,0.044722,-0.838965,0.367964,-0.008043,0.067064,-0.081690,-0.478423,0.404632,0.476257,0.298013,0.225099,-0.135638,0.026482,-0.548274,0.106728,0.748788,-0.377425,-0.073190,0.255155,-0.242768,-0.298474,-0.027782,-0.296812,-0.537148,0.009601,0.316534,0.045442,-0.081880,-0.008574,-0.521985,-0.111577,-0.367696,-0.269022,-0.211151,-0.601160,0.010937,-0.305898,-0.180696,-0.092948,-0.524275,0.072778,-0.084659,-0.173284,0.628334,-0.667613,0.106196,0.750439,0.432235,-0.453161,0.779270,0.262111,0.376376,-0.149858,0.067784,-0.051604,0.004270,0.185168,0.145055,0.315926,0.260018,-0.258156,-0.336412,0.340965', '26678784', '1793491', '3785918', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26389331', '阿修罗', '剧情', '身处台风眼的刑警韩度京（郑雨盛饰），夹在朴成裴市长（黄政民饰）和调查他的刑警队之间，为了自己的生存而不择手段。片中最大的反派朴成裴市长，为了追求私利而无所不为。刑警文先模（朱智勋饰），在韩度京的命令下，接近朴市长担任卧底工作。另一方面，特殊监察支队的检察官金车仁（郭道元饰）也在调查着朴成裴市长，是个心狠手辣的角色。韩度京为了取得成功而不惜为市长朴成裴的各种犯罪活动做善后，并从中收取报酬。韩度京得知妻子身患癌症后，以筹措医疗费用为借口，赚钱不计手段，渐渐偏离了警察的职业道德，走上歪路。负责特种案件的检察官金车仁手里攥着韩度京的弱点，刑警调查队队长都昌学（郑万植饰）也为了获取朴成裴的犯罪证据而威胁韩度京。后辈刑警文先模，视韩度京如亲哥哥，打进朴成裴团伙做卧底工作。韩度京处于两种势力之间进退维谷，此时的文先模也慢慢被腐蚀。就这样，几个男人各自为了生存厮杀，他们之间没有最坏，只有谁更坏。', '郑雨盛', '金成洙', 7.5, 52101, 'tt5918028', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2375744186.jpg', 0.7, 3.7, 32.2, 44.5, 19, '0.132679,-0.180371,-0.111438,0.541388,-0.561999,-0.099591,0.465211,0.439015,-0.444098,-0.539083,0.122323,0.344113,0.184883,-0.021630,0.258287,-0.412286,-0.139346,-0.731840,-0.261663,0.101582,-0.227203,-0.905088,0.106110,-0.417894,-0.079914,0.187098,0.687487,0.160572,-0.205680,-0.025087,0.331183,0.193799,-0.087452,0.305472,0.035091,-0.215883,-0.031551,-0.200315,-0.342619,0.203102,0.447808,-0.389941,0.121491,0.153958,0.199702,0.354543,0.438031,-0.153304,-0.010113,-0.268692,0.184027,-0.521132,0.287686,-0.108264,0.419193,0.034102,0.162252,0.076211,-0.194428,-0.246009,0.168923,-0.134201,-0.926391,-0.212195,0.181908,0.025669,-0.280653,0.112314,-0.057756,0.154467,0.152639,-0.043545,0.287078,0.692434,0.414647,0.128915,-0.412967,0.187173,-0.339512,0.158160,0.552945,-0.006435,0.077398,-0.152244,-0.412045,-0.563475,-0.012931,-0.377663,-0.328633,-0.290397,0.073434,-0.129553,0.354629,0.038226,-0.306473,0.055140,-0.021013,0.255358,0.013167,-0.329035,0.090493,-0.318920,-0.002651,-0.098148,0.036665,0.256433,0.265799,-0.590512,0.362121,-0.691257,-0.117486,0.559347,0.117867,-0.892919,0.596069,0.069704,0.241068,-0.502689,-0.099245,0.088866,0.466711,0.567698,0.124162,0.024030,-0.099993,-0.363247,0.184136,-0.090607', '26678784', '1297689', '3670447', '1302110');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26389466', '一句顶一万句', '剧情', '牛爱国（毛孩饰演）是县城里的鞋匠，他姐叫牛爱香（刘蓓饰演）。牛爱国要离婚，牛爱香想结婚。牛爱香年轻时谈恋爱受到伤害，直到快40岁才为了找一个能说话的人，和能说会道的厨师宋解放（范伟饰演）结婚，可是婚后却发现俩人也没话说。弟弟牛爱国因为“说得着”和庞丽娜（李倩饰演）结婚，然而经历了10年婚姻后，他们彻底没话说了。牛爱国继而发现老婆出轨婚纱店的蒋老板（喻恩泰饰演），他上演了一系列追踪、捉奸、拖着不离婚的戏码，内心经历了愤怒、冷静到释然的激烈过程。当牛爱国面临崩溃的时候，其他人压根不在意他，甚至是他最亲的战友和姐姐都无法对他的绝望和耻辱感同身受，只是劝他忍了。最后，牛爱国在偶遇的老同学章楚红（孙茜饰演）那里听来一句话：“过日子是过以后，不是过以前。”他仿佛一下子看到了生活的出路。', '毛孩', '刘雨霖', 6.3, 32134, 'tt6128848', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2389970856.jpg', 2.3, 16.4, 51.4, 24, 5.9, '0.148878,-0.207199,-0.831616,0.339411,-0.203525,-0.408008,0.978935,-0.083216,-0.517011,-0.160114,-0.176536,0.623541,-0.402363,0.410674,0.108532,-0.108652,-0.230004,-0.688449,0.011426,0.089157,-0.103273,-0.387140,0.197656,-0.048286,-0.083451,-0.256466,0.260309,-0.088867,-0.168249,0.430361,0.432882,0.054198,0.087925,0.584498,-0.067123,0.247416,0.026198,0.305770,-0.366728,0.089660,0.273106,0.006439,-0.259410,0.168415,-0.021898,0.482254,0.197365,0.270259,-0.197327,0.153133,0.234262,-0.331190,-0.142276,0.157869,0.207320,-0.176766,0.357347,0.104497,-0.059656,-0.171342,-0.009626,-0.011993,-0.580759,0.216546,-0.002200,0.005664,-0.656071,0.444766,-0.022195,-0.014234,0.201193,-0.214827,0.502255,0.268724,0.407515,0.500166,-0.383603,0.149491,-0.516316,0.384454,0.969667,-0.026276,-0.133396,0.628675,0.047760,-0.395429,-0.082373,-0.384263,-0.594166,0.310822,-0.066891,0.058514,-0.541809,-0.004690,-0.069351,-0.215009,0.033305,-0.060212,0.055285,-0.648762,-0.039253,-0.063598,-0.481013,-0.618713,-0.349821,0.285370,-0.246717,-0.488022,0.477927,-0.639954,0.014146,0.244760,0.547967,-0.655806,0.779373,0.457166,-0.047481,-0.254964,0.413403,0.106450,-0.192030,0.091931,0.386661,0.223658,0.088453,-0.039996,-0.240067,0.408566', '1296370', '25721544', '2071525', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26389601', '猎凶风河谷', '剧情', '科里·兰伯特是美国怀俄明州印第安自留区捕猎者和FBI探员珍·班纳一起调查一宗发生在风河谷的少女谋杀案，一个从自然中汲取生活智慧和信仰的猎人，一个还未熟谙行政痼疾和刑事规律的新人探员，他们俩代表着两种完全不同的文化背景和社会形态，在一宗谋杀案的牵扯下，渐渐走入了充满人性挣扎的迷雾当中，随着更多层身份和复杂脉络的揭开，人物危险处境慢慢升级，愈发紧张激烈，案件的内核也逐渐显现。', '杰瑞米·雷纳', '泰勒·谢里丹', 7.8, 75211, 'tt5362988', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2463178431.jpg', 0.1, 1.4, 24.3, 58.7, 15.5, '0.497602,-0.004606,-0.686829,0.647035,0.132883,0.108734,0.861296,0.108827,-0.482466,-0.137472,-0.038606,0.750278,-0.181794,0.064892,0.185589,-0.346227,-0.512718,-0.700740,-0.201215,0.006632,-0.467031,-0.658543,-0.378226,-0.099869,0.070246,-0.372204,0.783919,0.327888,-0.427133,0.389936,-0.008886,0.309795,-0.840386,0.457609,-0.202058,-0.376559,0.446034,0.136864,-0.181430,-0.040556,0.035451,-0.223897,-0.058021,-0.104958,0.071003,0.466664,0.641281,-0.487480,-0.145989,0.071032,0.295645,-0.142842,-0.287621,0.056423,0.504288,-0.015862,-0.052987,0.490923,-0.034525,0.143912,-0.247662,-0.226313,-0.958268,-0.065708,0.272980,0.598562,-0.240054,0.284321,0.273942,-0.300654,0.066048,-0.193690,0.190240,0.432360,0.060786,0.419611,-0.188937,-0.136736,-0.397011,-0.057127,0.468472,0.030256,-0.518632,0.169641,-0.445869,-0.595193,-0.383675,0.013240,-0.231368,-0.441730,0.365110,0.235373,-0.138186,0.597359,-0.771648,0.229871,-0.054505,-0.322220,-0.215586,-0.364980,0.149428,-0.589886,-0.399988,-0.557140,-0.329341,0.059121,0.121562,-0.166035,0.618423,-0.715765,0.166189,0.268335,0.206247,-0.437554,0.414838,-0.179334,0.239837,-0.423807,-0.233177,0.105996,0.161290,0.185537,0.138493,0.795298,-0.100830,0.167581,-0.065775,0.319124', '25774050', '26667010', '26759819', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26389696', '大闹天竺', '喜剧', '盛唐集团总裁唐宗突然离世并留下遗训,让他的儿子唐森（白客 饰）在穷小子武空（王宝强 饰）的陪同下前往印度寻找遗嘱。在印度巧遇自恋臭美却又忠诚的朱天鹏（岳云鹏 饰）,以及美丽性感却深藏秘密的美女吴静（柳岩 饰）,四人兜兜转转竟结为同盟,而最令四人不解的是为何这次取遗嘱之旅凶险重重,危机四伏,并且遗嘱之所以放在印度，更是隐藏着秘密。', '王宝强', '王宝强', 3.7, 116806, 'tt6152908', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2408307430.jpg', 46.6, 30.5, 16.7, 3.4, 2.7, '-0.250390,0.101918,-0.718158,0.733735,0.050202,-0.297042,0.251359,0.311748,-0.412419,-0.264337,0.426235,0.508417,0.078745,0.122852,0.096844,0.228525,-0.307695,-0.321335,0.054387,-0.154352,0.002300,-0.440719,-0.318000,-0.193334,0.263281,-0.186529,0.559839,0.272884,-0.507275,0.283528,0.501418,0.407728,-0.947980,0.502874,-0.215061,-0.276511,0.166076,0.301213,-0.415404,-0.032370,-0.171294,-0.225579,-0.157697,-0.021245,-0.038844,0.235020,0.254171,-0.226163,-0.331569,0.152004,0.273791,-0.120250,-0.144233,-0.126035,0.235578,-0.131758,0.228306,0.457417,-0.231221,-0.009350,0.369370,-0.203855,-0.532353,0.064324,0.189276,0.321618,-0.425342,0.591109,-0.180923,0.181498,0.118892,-0.284204,0.129914,0.335515,0.237326,0.122194,0.004097,0.504409,-0.041490,0.093046,0.158643,0.013303,0.148566,-0.094923,-0.105644,-0.304333,0.140668,0.185731,-0.239774,-0.005065,0.414397,0.008780,0.329472,0.113419,-0.494251,-0.111578,-0.285460,0.024951,0.362016,-0.403250,-0.145415,-0.322012,0.013882,-0.115536,-0.432865,0.168398,0.262200,-0.054746,0.620674,-0.311434,0.177359,0.389029,0.042305,-0.734665,0.442721,0.211829,-0.169605,-0.212184,-0.469764,0.509461,0.171602,-0.009949,-0.155615,0.047700,-0.174343,-0.016374,-0.375189,0.059725', '1298589', '24751764', '3670447', '1482072');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26389697', '大唐玄奘', '历史', '影片讲述历史上的唐朝高僧玄奘历时17年，不畏艰难险阻，前往天竺取经的传奇故事。大唐贞观盛世，年轻的玄奘法师（黄晓明 饰）为求佛法真谛冒死偷渡出境，一路上遭遇千难万阻，天灾人祸，却也深得民间疾苦。官兵围堵、徒弟背叛、埋身沙海、断水绝粮，玄奘法师一心求法，最终抵达印度，在印度弘扬善念静心修佛，等到从无遮大会辩论成功回国之时，已经是年逾五十的老人了。', '黄晓明', '霍建起', 5.4, 24738, 'tt5684550', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2339564405.jpg', 15.5, 27.8, 36.7, 13.5, 6.6, '-0.466432,-0.199856,-0.445944,0.284705,0.456167,-0.205871,0.089141,-0.323171,-0.577012,-0.392315,0.039861,0.455544,-0.145791,0.027562,0.332090,-0.205509,-0.009037,-0.367541,0.002278,-0.239773,0.009802,-0.058486,-0.129182,0.302673,-0.392768,-0.292163,0.501469,0.573006,-0.057128,0.462656,-0.008154,0.029550,-0.239313,0.335575,-0.346454,0.023263,-0.011627,0.003872,-0.355104,-0.198318,-0.545285,-0.646391,-0.502923,-0.238128,-0.468026,0.172983,0.184337,-0.173148,0.007810,-0.080018,0.193101,-0.061207,-0.276656,0.189866,0.213835,0.357166,0.231000,0.728890,0.282721,0.109535,-0.398280,-0.426934,-0.316001,-0.210705,0.009881,0.005542,-0.426286,0.406085,-0.069864,0.181802,-0.097618,-0.437966,-0.007587,0.517403,0.363564,0.335018,0.156944,-0.100443,-0.435156,0.493474,0.646983,-0.179074,0.137774,0.106806,0.050693,-0.556107,0.492967,-0.392832,-0.212548,0.124306,0.253425,-0.362661,-0.193276,0.459418,-0.303824,-0.015452,-0.363769,0.026838,0.204410,0.453887,-0.144663,-0.507771,-0.069817,-0.571734,-0.173050,-0.088800,0.295244,-0.170375,1.020393,-0.180182,0.402081,0.551756,-0.020708,-0.420281,0.857034,-0.055550,-0.017754,0.004725,0.001849,0.843285,-0.346242,0.714399,-0.316768,0.043053,-0.173407,-0.192289,-0.315326,0.039399', '1483630', '4307000', '1908036', '26646649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26389928', '二十世纪女人', '剧情', '多萝西亚（安妮特·贝宁 Annette Bening 饰）以一己之力独自抚养儿子杰米（卢卡斯·杰德·祖曼 Lucas Jade Zumann 饰）长大，其中的困苦和辛酸只有她自己知道。杰米深深爱恋着名为朱莉（艾丽·范宁 Elle Fanning 饰）的女孩，然而和很多人都发生过肉体关系的朱莉，却偏偏要在杰米的身上寻求精神的依恋，尽管两人常常同床共枕，却依然艰难维持着纯洁的友情，这让杰米感到十分苦恼。渐渐进入青春期的杰米表现出了一些令多萝西亚感到担心的特质，为了帮助儿子顺利的度过这一特殊时期，多萝西亚找到了房客艾比（格蕾塔·葛韦格 Greta Gerwig 饰），希望她能够给杰米一点帮助。与此同时，多萝西亚一直没有放弃希望，她渴望着能够找到一个靠谱的男人，成为自己的丈夫，亦成为杰米的父亲。©豆瓣', '安妮特·贝宁', '迈克·米尔斯', 7.8, 19991, 'tt4385888', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2394211986.jpg', 0.5, 2.9, 27.1, 47.4, 22.1, '0.179247,0.227425,-0.734924,0.626186,-0.023158,-0.493901,0.704500,-0.030130,-0.638156,-0.515255,-0.070894,0.628464,-0.005534,0.322411,0.176714,0.113934,-0.301624,-0.517822,0.018753,0.143168,-0.138302,-0.452485,-0.538540,-0.030608,-0.478236,-0.525316,0.539311,-0.007895,0.093339,0.397057,0.143322,0.412791,0.046379,0.477257,0.068989,-0.045079,0.002487,-0.037971,-0.345043,0.106489,0.156100,0.177442,-0.077343,0.358170,0.200925,0.191335,0.595373,-0.331397,0.047198,0.147421,0.288761,-0.021035,-0.020880,0.057977,-0.189109,-0.079691,0.227692,-0.019693,-0.163345,0.006483,0.458258,0.023044,-0.973625,0.043706,0.069593,0.160817,-0.590543,0.366634,-0.185767,-0.088621,0.310647,-0.445940,0.025554,0.423695,0.187755,0.475677,-0.420538,0.323344,-0.437619,-0.284307,0.705092,-0.100644,-0.199256,0.239250,-0.796320,-0.427563,-0.054551,-0.313742,-0.581847,-0.071531,0.304516,0.545656,-0.165583,0.243630,-0.299628,-0.172429,-0.290266,-0.043746,-0.043339,-0.467211,0.170314,-0.341273,-0.192283,-0.421357,-0.427424,-0.108777,-0.126282,-0.706915,0.543238,-0.873231,0.528939,0.575485,0.385435,-0.138700,0.668274,0.404548,0.288807,-0.240943,-0.425496,0.845965,-0.278236,-0.226004,0.161271,0.241927,-0.004529,0.036425,-0.248852,0.595353', '1793491', '10440076', '4058933', '1308599');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26390631', '总有一天', '剧情', '母亲（松佳·里奇特 Sonja Richter 饰）病重，艾尔玛（Harald Kaiser Hermann 饰）和艾瑞克（Albert Rudbeck Lindhardt 饰）兄弟两人无人照顾，只能被送往由校长赫克（拉斯·米科尔森 Lars Mikkelsen 饰）所开办的寄宿学校之中。赫克是一个信奉暴力的男人，他坚信，唯有通过武力才能够令学校中的孩子们真正信服，才能够引导他们走上正确的道路。兄弟两人在这座名为学校实为监狱的牢笼之中受尽折磨，圣诞节妈妈会来接他们回家的承诺成为了他们生存下去的唯一动力，然而，两人等啊等啊，等来的却是妈妈的死讯。莉莉安（苏菲·格拉宝 Sofie Gråbøl 饰）是学校里新上任的文学教师，她敏锐的察觉到了这所学校里正在发生的惨无人道的暴行，却对这一切无能为力。©豆瓣', '拉斯·米克尔森', '杰斯珀·W·尼尔森', 8.7, 28246, 'tt4659056', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2596147131.jpg', 0.2, 0.6, 9.6, 42.4, 47.3, '0.170190,0.108572,-0.662879,0.499277,-0.226683,-0.239674,0.593359,-0.027871,-0.734029,-0.330098,0.064056,0.612741,-0.020393,0.439086,0.210423,0.203583,-0.455544,-0.646268,-0.075628,-0.289468,-0.293136,-0.343329,-0.294192,-0.098396,-0.139900,-0.090903,0.213756,0.075487,0.030978,0.361941,0.298473,0.557027,-0.085472,0.354885,-0.061256,-0.202645,0.075881,-0.113434,-0.273788,0.189826,0.152936,-0.065835,-0.086345,0.291713,0.286005,0.147777,0.516091,-0.345833,-0.181725,-0.146410,0.241081,-0.326333,-0.063488,0.311835,0.071022,-0.038190,0.321394,0.329615,-0.274514,0.173907,-0.089343,-0.198621,-0.820387,-0.115572,0.177634,0.063751,-0.443834,0.179745,0.083231,-0.374772,0.155247,-0.425309,0.205702,0.242369,0.223727,0.607530,-0.344152,0.000639,-0.363219,-0.056691,0.490288,-0.367330,-0.230644,0.070699,-0.178498,-0.353096,0.266336,-0.094641,-0.577835,0.022515,0.026926,0.334273,-0.087098,-0.065429,-0.460300,-0.025309,-0.499464,-0.275127,-0.026850,-0.438703,-0.017602,-0.520978,0.091458,-0.294576,-0.248702,0.216661,0.028112,-0.175499,0.649439,-0.682360,0.283619,0.286762,0.535840,-0.349522,0.617359,-0.017089,0.332202,-0.141153,0.027951,0.181064,0.025048,0.497523,-0.061427,0.472045,0.359942,-0.156162,-0.560405,0.555416', '1793491', '1783461', '25928048', '30