INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26390938', '私人采购员', '剧情', '莫林，一位在巴黎的年轻美国女孩，她的工作是替一位有名的女士照看衣橱。她讨厌这份工作，却找不到更好的来负担她在巴黎的开销。她等待着，等待着关于她最近消失的双胞胎兄弟——刘易斯的消息。而她的手机突然开始收到一些陌生的匿名消息。', '克里斯汀·斯图尔特', '奥利维耶·阿萨亚斯', 6.2, 13172, 'tt4714782', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2414758267.jpg', 4.3, 19.7, 46.9, 22, 7.1, '0.251968,0.081422,-0.946830,0.684904,-0.440563,-0.233401,0.809897,0.284672,-0.568369,-0.485198,0.246146,0.656540,0.310007,0.555927,0.211878,0.336452,-0.239553,-0.573246,-0.030943,-0.219601,-0.300138,-0.355223,-0.518730,-0.398909,-0.123294,-0.301769,0.230597,0.041970,0.006007,0.416826,0.276350,0.081002,0.130316,0.849160,-0.623606,-0.131507,0.307332,0.079736,-0.050205,0.327402,0.422911,-0.315617,-0.330182,0.331550,0.154163,0.459037,0.601790,0.178369,-0.352889,0.447674,0.545612,-0.139174,0.188961,-0.216208,0.493076,0.068613,0.252848,-0.021671,-0.509683,-0.008139,-0.106842,-0.169800,-0.698801,0.046825,0.063205,0.620652,-0.621996,0.655486,-0.738085,0.018291,0.155185,-0.669564,0.262319,0.424472,-0.462900,0.460499,-0.220160,0.336386,-0.387434,0.499975,0.495885,0.007261,-0.066259,0.387226,-0.249173,-0.374789,-0.057922,-0.010747,-0.900409,-0.035094,0.491319,-0.251866,-0.146219,-0.231199,-0.539962,0.083383,-0.073706,-0.494270,0.059064,-0.437939,-0.417229,-0.717790,-0.023463,-0.168415,-0.255370,0.188445,0.168414,-0.077352,1.011498,-0.823864,0.266979,0.992928,0.076280,-0.694265,0.706076,0.054944,0.306061,-0.368540,-0.285053,0.122177,-0.022819,0.408850,0.015588,0.123142,0.120231,-0.111121,-0.762654,0.410536', '4233625', '3005387', '1298754', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26391916', '杀人者的记忆法', '剧情', '该片根据同名小说改编，讲述患有阿兹海默症的连续杀人犯炳秀(薛耿求饰)金盆洗手，可村庄却再现连环杀人案，这让炳秀陷入混乱记忆之中。于此同时女儿(金雪炫饰)，神秘男子(金南佶饰)也身陷其中。', '薛景求', '元新渊', 7.7, 58149, 'tt5729348', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2502854299.jpg', 0.4, 2.3, 27, 50.1, 20.2, '-0.253817,-0.028235,-0.222937,0.427197,0.606558,-0.025600,0.799128,-0.356652,-0.845571,-0.642600,0.230215,0.379542,-0.144858,-0.053766,0.246168,-0.371623,-0.506771,-0.602144,-0.220946,-0.000933,0.001742,-0.404966,-0.408721,-0.220546,0.052593,-0.316014,0.696357,0.585698,-0.685867,0.141803,-0.068579,0.758576,-1.163683,0.114815,0.166752,0.490000,-0.161662,-0.067841,-0.526865,0.217297,-0.204470,-0.446442,0.346180,-0.106051,-0.263300,0.374902,0.973164,-0.522355,-0.371876,-0.184955,0.971413,0.465810,-0.748469,-0.348698,0.319277,0.417724,0.906084,-0.038296,-0.089984,-0.064758,-0.234951,-0.166038,-0.557155,0.020718,0.556257,0.332978,0.091189,-0.339080,-0.105667,0.084233,-0.242462,0.224536,0.089849,-0.052694,1.123830,0.104620,0.020468,-0.011871,0.045808,0.242858,0.305950,-0.000101,-0.303038,0.148029,-0.163861,-0.391645,-0.104461,-0.070129,-0.057934,0.477029,0.057617,0.091120,0.015405,0.685410,-0.091454,0.105235,-0.153558,0.169668,-0.245290,0.006807,-0.662162,-0.411088,-0.291267,0.535420,-0.164152,-0.308398,0.023728,-0.084777,0.315179,-0.529794,0.524073,0.182802,-0.208834,-0.050157,0.112874,0.029429,0.323948,-0.271396,-0.151108,0.716417,0.142544,0.096109,-0.269359,-0.276788,-0.388838,-0.166068,-0.507019,0.205834', '26767512', '26691509', '25757061', '1296629');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26391951', '跨越栅栏', '剧情', '白岩义男（小田切让 饰）在和妻子离婚后回到了故乡函馆，在那里，他进入了一间职业学校学习木工，全部的生活来源就只依靠着一份失业救济金。白岩不愿意回忆过去，也不对未来抱有期望，只是浑浑噩噩的过着眼前的生活。某日，白岩在同学代岛和久（松田翔太 饰）的带领下来到了一家风俗店中，代岛想跟白岩合作做生意，但白岩对是否要加入犹豫不决。在店里，白岩意外邂逅了名为田村聪（苍井优 饰）的陪酒女。聪白天在一间动物园工作，收入微薄，住的地方连洗澡间都没有，即使这样，聪的周身还是散发出了乐观和开朗的气息，这样的气息渐渐吸引了心如死灰的白岩，两个伤痕累累的人都想在对方的身上找到属于自己的救赎。©豆瓣', '小田切让', '山下敦弘', 6.8, 9409, 'tt4690878', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2399173215.jpg', 1.3, 9.1, 48, 31.8, 9.9, '0.339350,0.002868,-0.858868,0.374354,-0.172857,-0.294071,0.774067,0.248420,-0.391703,-0.313371,-0.055229,0.752482,0.165134,0.488976,0.126827,0.180133,-0.231261,-0.605079,-0.230873,-0.347547,-0.406608,-0.509054,-0.082813,-0.070230,-0.189973,-0.292427,0.542292,0.172025,-0.203963,0.501667,0.275357,0.081660,-0.061354,0.604454,-0.550725,-0.111294,0.027206,0.252849,-0.085216,0.297610,0.128714,-0.204915,-0.369303,0.317810,0.317070,0.225413,0.722447,-0.044242,-0.409196,0.299654,-0.070987,-0.109626,-0.163870,0.157303,0.345354,-0.065794,0.207959,0.189491,-0.396540,0.149862,-0.020438,0.024465,-0.725699,-0.036280,0.110008,0.303724,-0.786256,0.604848,0.055318,-0.365172,0.028536,-0.446817,0.176911,0.288526,-0.079778,0.537495,-0.186291,0.190327,-0.595660,0.193354,0.837182,0.069915,-0.096266,0.593993,-0.331394,-0.237450,-0.349977,0.001759,-0.570180,-0.250160,0.138015,0.208506,-0.253236,-0.207900,-0.723729,-0.016697,0.163263,-0.185850,-0.017752,-0.482753,-0.035502,-0.463856,-0.286995,-0.513262,-0.292297,0.232780,0.117947,-0.281289,0.748420,-0.997133,0.242444,0.456995,0.544602,-0.403170,0.751692,0.097978,0.094459,-0.013244,0.102993,-0.086766,0.160277,0.389320,0.406847,0.517360,-0.106036,-0.048148,-0.503101,0.528104', '1292219', '3055049', '1299965', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26393561', '小萝莉的猴神大叔', '剧情', '电影讲述了一个拥有虔诚宗教信仰的单纯印度男人帮助巴基斯坦哑女与父母重聚的故事。印度教教徒帕万（萨尔曼·汗 饰）在一次机缘巧合下结识了与母亲走失并有语言障碍的穆斯林小女孩沙希达（哈尔莎莉·马尔霍特 饰）。在得知沙希达是巴基斯坦人后，帕万决定帮助她回家，可在回巴基斯坦途中却四处碰壁，遭遇领事馆冲突、被旅游局欺骗之后，帕万立志将不惜一切代价尽其所能带沙希达回到自己的家乡与家人团聚。', '萨尔曼·汗', '卡比尔·汗', 8.4, 458149, 'tt3863552', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2510956726.jpg', 0.4, 1.8, 15.3, 40.4, 42, '0.082305,0.144386,-0.668460,0.488141,0.073749,-0.536798,0.552907,-0.099598,-0.618739,-0.238232,0.154986,1.028526,-0.000225,-0.009635,0.117160,-0.031856,-0.509103,-0.666043,0.362407,-0.137522,-0.227616,-0.574619,0.096174,-0.242048,-0.211612,-0.583981,0.251039,0.168896,-0.191766,0.523106,0.200975,0.363936,-0.205639,0.397447,-0.261759,0.210704,-0.021071,0.079168,-0.605153,0.239959,0.058824,-0.158639,-0.197865,0.058063,0.059047,0.311439,0.686684,-0.389562,0.070511,-0.176465,0.151711,-0.295114,0.077105,0.323219,0.107371,0.104520,0.157302,0.204569,-0.139216,0.021104,0.071121,-0.210638,-0.328793,-0.064463,0.190407,-0.002278,-0.860465,0.435924,-0.140371,0.070000,0.241896,-0.417507,0.254374,0.609624,0.237339,0.333813,-0.133859,-0.040585,-0.473113,0.067512,0.878285,-0.001465,0.166078,0.127854,-0.344977,-0.375179,0.238914,-0.157052,-0.297039,0.231441,0.315176,-0.393608,-0.171379,0.319084,-0.656369,-0.348730,-0.600818,-0.198098,0.113094,-0.459734,0.165882,-0.610586,-0.094510,-0.161589,-0.281658,0.012701,0.030667,-0.158297,0.755469,-0.871603,0.336677,0.714079,0.478111,-0.571413,0.519043,0.089009,0.132973,-0.358925,0.132481,0.716011,0.215331,0.205316,-0.079272,-0.050127,-0.187010,0.305769,-0.291246,0.186918', '25721544', '3285622', '1309069', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26394152', '大黄蜂', '动作', '意图征服一切的霸天虎全员出击，塞伯坦即将陨落，B-127（迪伦·奥布莱恩 Dylan O''Brien 配音）临危受命前往地球。在1987年的加州，B-127不仅遭到特工伯恩斯（约翰·塞纳 John Cena 饰演）的追捕，更被闪电（大卫·索博洛夫 David Sobolov 配音）殴至重伤，语言模块和记忆模块严重受损。B-127变形为大众甲壳虫，被失去了父亲（蒂姆·马丁·格利森 Tim Martin Gleason 饰演）的查莉·沃森（海莉·斯坦菲尔德 Hailee Steinfeld 饰演）发现并开回家。查莉为B-127取名大黄蜂，双方成为亲密无间的好朋友。然而好景不长，反射弹（贾斯汀·塞洛克斯 Justin Theroux 配音）与粉碎（安吉拉·贝塞特 Angela Bassett 配音）追至地球，利用美国军方的卫星网络追踪到大黄蜂，并企图将霸天虎大部队召唤到这里。为了阻止反弹射和粉碎，大黄蜂和他的新朋友一起踏上了保卫这个蓝色星球的征途……', '海莉·斯坦菲尔德', '特拉维斯·奈特', 7, 363259, 'tt4701182', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2541662397.jpg', 1.1, 8, 43.5, 36.7, 10.7, '0.282623,-0.060018,-0.629676,0.522318,0.041337,-0.289012,0.371065,0.041760,-0.110618,-0.304684,-0.068354,0.908858,-0.362563,-0.186973,0.346450,0.080644,-0.368242,-0.505685,-0.016146,0.131639,-0.274153,-0.618061,-0.203572,-0.188112,0.095782,-0.500006,0.677974,-0.176347,-0.190822,0.508948,0.039474,0.490014,-0.170877,0.203465,0.155598,0.311723,0.136070,-0.486306,-0.237932,0.372803,-0.088732,0.037327,0.315539,0.104308,-0.112383,0.314350,0.468732,-0.107985,0.322046,-0.309320,0.094933,-0.590494,0.247228,-0.097193,0.363773,0.051734,-0.174093,-0.003043,-0.051444,-0.021635,0.226651,-0.198770,-0.712376,0.018163,-0.050675,-0.039358,-0.458894,0.141793,-0.385644,0.185182,0.173306,-0.273574,0.262800,0.348175,0.274430,0.125438,-0.116514,0.194781,-0.373931,-0.027764,0.567922,-0.199903,-0.405160,0.017561,-0.052138,-0.327333,-0.170896,-0.166824,-0.235266,-0.106914,0.556138,0.037859,0.129162,0.476209,-0.598233,-0.251305,-0.634536,-0.357695,-0.208433,-0.270104,0.160167,-0.947180,-0.047146,-0.004975,-0.068568,0.054511,-0.071754,-0.060764,0.427162,-0.665500,0.403408,0.486446,0.446550,-0.059695,0.204997,-0.111023,0.208780,-0.310167,0.011885,0.457793,0.572153,0.302948,0.210032,-0.039555,-0.0