INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26394441', '我最好朋友的婚礼', '喜剧', '影片改编自好莱坞同名经典爱情喜剧。顾佳（舒淇 饰）是国内某时尚杂志的新任主编，奉命去米兰参加时装周。一通意外的电话让她刚刚落地就放弃了工作安排飞往伦敦。因为她曾经逃避但其实内心深爱的男人林然 （冯绍峰 饰）马上就要和一位年轻富家女萱萱（宋茜 饰）结婚，她想在婚礼之前把新郎抢回来。在飞往伦敦的飞机上，顾佳邂逅了型男Nick（凤小岳 饰），她一直出糗，令Nick非常尴尬。见面后，林然的准新娘萱萱却待她亲如姐妹。尽管内心矛盾，顾佳还是有意无意的制造着麻烦，并因为一个误会使婚礼无法在英国如期举行，但林然和萱萱情比金坚，顾佳决定安排林然和萱萱去意大利办婚礼。在米兰，顾佳鼓起勇气和林然表白，却意外被萱萱撞见，三人在街头展开了追逐……©豆瓣', '舒淇', '陈飞宏', 4.4, 25973, 'tt5275314', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2365223709.jpg', 25.5, 39.1, 27.4, 4.9, 3, '0.209925,-0.007072,-0.776781,0.518729,0.023419,0.274139,0.720063,-0.045308,-0.120446,0.020898,0.241648,0.945934,-0.615676,0.568272,0.632104,0.348786,-0.329214,-0.759716,0.471493,-0.114936,-0.116375,-0.607599,0.215254,0.238762,-0.031772,0.242540,0.777219,-0.243171,0.056951,1.067252,0.313180,0.123092,-0.296986,0.785613,-0.162601,0.088884,0.024337,0.112290,-0.126262,0.139573,0.478715,-0.273390,-0.144975,0.821161,0.323961,0.296104,0.365588,0.043164,0.181048,0.202446,0.043969,-0.176592,0.389341,0.261714,-0.006089,-0.241615,0.730915,0.191310,-0.309082,0.094707,-0.061015,-0.085782,-0.265462,0.827717,0.239694,-0.187199,-0.612974,0.631347,-0.361172,0.456889,0.060262,-0.146519,0.151295,0.573514,0.207137,0.523297,-0.220934,0.264173,-0.224307,-0.050835,0.656990,0.057202,-0.034081,0.682191,0.402706,0.102753,-0.000323,0.099528,-0.539256,0.221137,0.288559,-0.112693,-0.272923,-0.188952,-0.560110,-0.210702,-0.060612,-0.023809,0.395688,-0.167761,-0.088892,-0.600415,0.096869,-0.217203,-0.690133,-0.171654,-0.153624,-0.389283,0.611611,-0.982704,-0.224090,0.404775,0.543628,-1.009040,0.577824,0.074469,0.206051,-0.014464,0.233780,0.319294,-0.286989,0.062732,0.195321,0.467003,0.096254,-0.251244,-0.414165,0.273037', '1303333', '3111650', '1299556', '1306133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26410593', '王者', '剧情', '影片由《观相》导演韩在林执导，讲述谋求权利成为检察官的男主人公，与黑帮朋友一起，利用有权有势的前辈检察官的故事。', '赵寅成', '韩在林', 7.8, 61791, 'tt5644740', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2413029060.jpg', 0.4, 2.5, 26.9, 48, 22.1, '-0.095567,-0.732334,0.413337,0.734921,0.223310,-0.223997,0.341411,0.408064,-0.360168,-0.469286,0.146608,0.955085,-0.110913,0.064703,0.928898,-0.286397,-0.559056,-0.774005,-0.241448,0.424010,0.587416,-0.743470,-0.147049,-0.141364,-0.189413,-0.443910,1.311461,-0.556439,-0.438503,-0.008936,0.428937,0.045116,-0.552371,-0.547941,0.205358,-0.198842,0.344338,-0.036483,-1.533563,0.375367,0.026535,0.024002,0.319994,-0.354675,-0.096200,0.012530,0.259083,-0.114089,0.090399,-0.107622,0.560792,-0.294526,0.104630,-0.312422,0.167427,0.373606,0.862855,0.802149,0.458723,-0.481730,-0.022286,-0.318580,-0.802058,-0.057073,0.845811,0.253468,0.020255,0.016511,0.373855,-0.028005,0.273669,0.053095,0.212712,-0.102930,0.661007,0.140990,0.107041,0.315076,0.025049,0.933617,0.592269,0.191591,0.119225,0.096889,0.152593,-0.345427,0.083303,-0.334369,-0.922363,0.274762,-0.224640,-0.335888,0.156215,0.330435,-0.411534,-0.363549,0.330206,0.302019,0.765108,-0.554632,0.578340,-0.802118,-0.491917,0.510088,0.569744,-0.383481,0.497114,-0.465151,1.151098,-0.755589,-0.285529,0.497450,0.488548,-0.641665,1.137147,0.208300,0.126630,-0.692972,-0.058583,-0.287077,0.345346,0.008099,-0.204243,-0.216215,-0.154365,-0.378236,-0.049903,-0.381597', '26980827', '1292206', '30349667', '1305441');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26410594', '隧道', '剧情', '汽车销售员李正洙（河正宇饰）结束工作赶赴女儿生日派对时，行经刚开通的河图隧道，突然一阵天摇地动，让他经历此生最孤立无援的三十五天，而此刻的他唯一能做的就是拨打119求救。这则隧道崩塌消息引发各界关注，除了搜救大队，还吸引了大批抢新闻的嗜血媒体，以及逢场作秀只为增添政绩的官员。搜救队长金大庆（吴达洙饰）不仅要研拟救援计划，还需控制现场跟风记者、向作秀官员汇报，恶劣天气的搅局使得救援行动雪上加霜。好不容易终于进行开挖，准备救出受难者时，竟发现隧道是个豆腐渣工程。一连串的重击使得希望一一幻灭，更糟的是搜救行动中救难队组长意外身亡、国库的大量花费，促使舆论审判，迫使李正洙无助的老婆世贤（裴斗娜饰）签下放弃救援同意书。那一天崩塌的不只是隧道，更引爆现代社会形象丑闻。', '河正宇', '金成勋', 7.9, 193635, 'tt5910280', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2370318863.jpg', 0.2, 1.4, 23.8, 53.5, 21.1, '-0.112788,-0.076910,-0.476453,0.243965,0.298262,0.041387,0.332650,-0.011493,-0.344541,-0.107578,0.339198,0.209894,-0.283095,-0.155913,0.345644,-0.346662,-0.407962,-0.628865,-0.251553,0.077326,-0.246537,-0.362321,-0.099148,-0.298404,0.153286,-0.513310,0.653570,0.495757,-0.349512,0.318582,0.121560,-0.014775,-0.040286,0.579362,0.061680,-0.209802,0.091890,0.086953,-0.190652,0.177231,-0.191260,-0.357634,-0.087712,0.370746,-0.005803,0.561175,0.389401,-0.138119,-0.255468,-0.178622,0.495021,-0.510526,0.097172,-0.024714,0.256512,0.123860,0.174089,0.147533,-0.405143,0.083715,-0.063664,-0.007112,-0.528170,-0.030965,0.049946,0.062748,-0.276237,-0.068530,-0.035353,0.186557,0.170056,-0.139155,0.234411,0.564563,0.191620,0.351993,-0.280432,-0.024075,-0.231533,0.287893,0.645261,-0.273258,-0.223367,0.108527,-0.048352,-0.230738,0.279988,-0.015949,-0.228465,-0.107139,0.208042,0.071987,0.093982,0.168978,-0.289969,-0.038212,-0.339715,-0.469206,-0.020870,-0.169378,-0.248178,-0.916872,0.049502,0.392732,0.111444,0.304713,0.152188,-0.035254,0.563312,-0.312957,0.147036,0.578682,0.134679,-0.635823,0.280563,0.057949,-0.066423,-0.233090,0.130150,-0.219504,0.086138,0.468867,-0.147333,-0.135980,-0.214993,-0.601130,-0.192073,0.024006', '26718836', '2369613', '3003137', '2973528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26410683', '赛马皮特', '剧情', '十五岁的男孩查理（查理·普拉默 Charlie Plummer 饰）自幼就失去了母亲，整个童年时代都在不安全感中度过，因此个性极为的内向和胆怯。最近，查理从华盛顿的斯波坎搬到了波特兰，准备在那里开始他全新的生活，希望新的环境能够一扫之前的坏运气。在查理最不如意的时候，他遇见了一匹名为皮特的赛马。身材矫健性格温存的皮特深深的吸引了查理的注意，让查理无法自持的开始接近它。查理将皮特当做是自己最好的朋友，虽然所有人都告诉他，赛马只是赛马，一旦他们不能够再参加比赛了，就将面临被屠宰的命运。在连续输了好几场比赛后，皮特也要走向它马生的终点了，不忍心看到皮特死去的查理决定将它从马场里偷走。©豆瓣', '崔维斯·费米尔', '安德鲁·海格', 7.7, 6853, 'tt5340300', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2497784535.jpg', 0.5, 2.3, 26.7, 51.6, 18.9, '0.271347,0.044662,-0.711863,0.379725,-0.524603,-0.537050,0.776119,0.078313,-0.568010,0.110258,0.189093,0.997586,-0.220815,0.183285,0.439187,0.058877,-0.389641,-0.693080,-0.129973,-0.138529,-0.385252,-0.391294,-0.121906,-0.210756,-0.011070,-0.279747,0.537856,-0.086706,-0.287652,0.483517,0.010863,0.201231,0.342632,0.475280,-0.285030,0.057360,-0.032145,-0.219696,-0.200165,0.376705,0.182056,-0.271174,-0.017579,0.552233,0.199233,0.288034,0.845951,-0.379509,-0.107059,0.027069,0.107739,-0.121207,0.001895,0.281356,0.215458,-0.046092,-0.013025,0.174408,-0.254002,0.213149,-0.127178,0.048236,-0.888824,0.236800,-0.085395,0.309182,-0.720845,0.636712,-0.021654,-0.072544,0.149034,-0.442413,0.381303,0.315209,0.144900,0.195531,-0.153688,-0.099957,-0.489394,0.039476,0.756790,-0.204367,-0.171347,0.452852,-0.143497,-0.449131,0.108219,-0.156576,-0.433979,-0.088673,0.555713,0.323517,-0.388778,0.179092,-0.525353,-0.079645,-0.096227,-0.501647,-0.133828,-0.454632,-0.095667,-0.352265,-0.165711,-0.678925,-0.337422,-0.046263,-0.093450,-0.227025,0.590134,-0.959263,0.343894,0.612052,0.216768,-0.189709,0.621216,0.011323,0.212871,-0.039195,0.238466,0.291375,-0.079342,0.373060,0.231879,0.530910,0.147308,-0.428959,-0.495792,1.044542', '25763555', '1652618', '1481233', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26411201', '追捕野蛮人', '剧情', '里奇（朱利安·迪尼森 Julian Dennison 饰）是一个性格非常恶劣的小男孩，没有人愿意和他一起玩，而他带给别人的也只有无穷无尽的麻烦。终于，里奇因为他的劣迹斑斑而被送到了一座位于大山环绕之下的小村落里，那里住着她彪悍的婶婶宝拉（瑞秋·豪斯 Rachel House 饰）和看起来就不好惹的疤面姨夫海克（山姆·尼尔 Sam Neill 饰）。虽然里奇表现得对这里的生活非常厌恶，屡屡想要逃跑，但宝拉对里奇的关心和爱渐渐融化了后者内心的坚冰，里奇第一次感受到原来被爱是这样一件温暖的事情，和婶婶每天为他准备的暖水袋一样的温暖。然而好景不长，婶婶去世了，里奇将被再度送进福利院。©豆瓣', '朱利安·迪尼森', '塔伊加·维迪提', 8.1, 40632, 'tt4698684', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2371503931.jpg', 0.4, 1.7, 19.3, 51.4, 27.3, '0.586809,-0.203924,-0.892347,0.683487,-0.303424,-0.231287,1.086893,0.364644,-0.713411,-0.151647,0.019846,0.847912,-0.130810,0.405970,0.044311,0.468671,-0.094935,-0.555809,-0.110119,-0.070841,-0.250470,-0.423845,-0.301279,-0.110103,-0.342686,-0.303965,0.377418,0.015704,0.188859,0.526916,0.220974,0.349784,0.389606,0.666642,-0.200726,0.133938,-0.053503,-0.133484,-0.061034,0.435093,0.208846,0.114936,0.041089,0.469274,-0.045921,0.375299,0.568282,-0.279967,-0.076815,-0.030122,0.193312,-0.290817,0.199547,0.381761,0.073983,-0.065939,0.344857,0.052368,-0.534972,0.019787,0.368956,-0.293793,-0.694484,0.260173,0.127782,0.134218,-0.724942,0.322461,-0.158741,-0.245332,0.160232,-0.489515,0.282350,0.119098,0.069364,0.524628,-0.351915,0.026514,-0.427189,-0.076383,0.726501,-0.107826,-0.085186,0.483709,-0.471851,-0.068988,0.092536,-0.424273,-0.693583,0.146205,0.101785,0.079134,-0.283864,0.200756,-0.606167,0.122513,-0.238485,-0.209660,-0.193524,-0.504791,-0.198342,-0.299118,-0.277812,-0.548569,-0.430614,-0.032353,-0.046238,-0.103880,0.650251,-0.897171,0.307337,0.403711,0.328236,-0.086956,0.593673,0.136744,-0.086151,-0.043193,0.004528,0.156993,0.200800,0.183156,0.493807,0.555942,-0.003055,-0.253224,-0.410617,0.663850', '3111650', '24756472', '1296534', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26411219', '变焦', '剧情', '漫画家艾玛（艾丽森·皮尔 饰）正在写关于爱德华（盖尔·加西亚·贝纳尔 饰）的故事。他是艾玛漫画中的主人公，她的梦中情人，一个自大的动作片导演，正在拍摄一部关于米歇尔（玛丽安娜·希梅内斯 饰）的电影。米歇尔是一名巴西模特，正在写一本关于一个名叫艾玛的漫画家的书。这三人都在创作彼此的故事。', '盖尔·加西亚·贝纳尔', '佩德罗·莫雷利', 7.2, 6178, 'tt3763866', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2378591873.jpg', 0.9, 5.2, 38.9, 43.2, 11.8, '0.407374,-0.313124,-0.124596,1.068877,0.430407,-0.411566,0.948600,-0.051182,-0.127560,-0.659066,0.276897,0.804943,-0.493562,0.295049,0.435593,0.359284,-0.651628,-0.884100,-0.042758,-0.044274,0.004133,-0.497877,-0.585691,-0.054531,-0.029036,-0.176255,0.725716,-0.385036,-0.306860,0.124358,0.529740,0.219089,-0.235696,-0.067040,0.222877,0.338340,0.414702,-0.172376,-0.053521,0.011247,0.189110,0.030836,-0.077399,0.030650,0.111258,0.224058,0.793835,-0.503897,0.312870,0.328823,0.623762,0.175505,-0.220113,-0.091445,0.036566,0.023592,0.382363,0.087239,0.186856,0.041179,-0.236864,-0.256845,-1.079547,-0.292329,0.227958,0.872951,-0.175968,0.393624,-0.479445,0.239110,0.408030,-0.218164,-0.140524,-0.097099,0.372749,0.629506,0.295192,-0.072833,-0.228740,0.676995,-0.030229,0.452921,-0.056636,0.882826,-0.197723,-0.405731,-0.325792,0.384859,-0.890440,0.362769,0.323290,-0.588821,0.009364,0.096996,-0.797375,-0.093446,0.061263,-0.349422,0.174740,-0.201487,-0.214627,-0.984425,-0.167761,-0.178003,0.068339,-0.425088,0.077065,-0.404867,1.261129,-0.453393,0.199789,0.657557,-0.540906,0.075070,0.718759,0.295561,-0.045202,-0.073966,-0.285065,0.467406,0.008538,-0.071606,-0.221928,0.404160,0.316557,-0.662293,-0.410475,0.669028', '3318306', '27602116', '22265121', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26411377', '你的婚礼', '剧情', '高中时年少懵懂的纯纯爱恋，经过长达十年的磨合，期间感情不断地变化，从心碎争执、失恋痛苦直到重新恋爱，不断重复纠缠在一起。这是属于一个只看着一个女人的「纯情男子」（金英光 饰），以及猜不透内心想法的「初恋女子」（朴宝英 饰）两人间的爱情故事，恋爱的酸甜苦辣即将展开……', '金英光', '李锡根', 7.3, 41417, 'tt7938092', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2528205132.jpg', 1.2, 5.2, 38, 40.3, 15.3, '0.121208,0.007956,-0.535226,0.506670,0.199682,-0.555242,1.042538,-0.113434,-0.297935,-0.238586,0.081537,0.175292,-0.573224,0.607015,0.230862,-0.392468,-0.002387,-1.192348,-0.297940,-0.147113,-0.132064,-0.383657,-0.075629,0.202865,0.015321,-0.341573,0.942575,-0.124623,0.027640,0.639999,0.445847,0.178554,-0.490425,0.334891,-0.236367,-0.276234,0.203264,0.568992,-0.540217,-0.507055,0.094129,-0.176219,0.051078,-0.407789,-0.424217,0.115670,1.130345,-0.342526,-0.074178,0.024935,0.494466,0.349541,-0.494809,0.204295,0.086718,0.259149,0.330494,0.075972,-0.199687,-0.024264,0.052070,-0.128893,-0.412250,-0.180672,-0.153952,0.471255,-0.330325,0.438510,0.356420,-0.049526,0.615453,-0.034795,-0.270225,0.360814,0.812952,0.750684,-0.572111,0.223835,0.112520,0.312612,0.696585,0.218859,-0.320768,0.946058,-0.173707,-0.262433,-0.292689,0.063294,-0.673032,0.025898,-0.291317,0.172836,-0.177091,0.676012,-0.735541,-0.065146,-0.104883,0.093579,0.336918,-0.477234,-0.518507,-0.294092,-0.556236,-0.546353,-0.352096,0.162731,0.170401,-0.163696,0.692382,-0.704179,0.292326,0.567714,0.009634,-0.305194,0.531154,0.616557,-0.191096,-0.512235,0.006811,0.940942,-0.552356,-0.419161,-0.346711,0.547947,-0.351599,0.539487,-0.502250,0.603117', '2365260', '1417036', '6973376', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26411409', '怦然星动', '喜剧', '欢瑞正式启动以娱乐圈作为题材的都市爱情喜剧《怦然星动》，《怦然星动》是晋江文学网站的热门连载小说，年轻受众不少。此次同名电影由曾打造过《全城热恋》和《全球热恋》的香港导演搭档陈国辉和夏永康执导，讲述了大明星和经纪人之间的爱情故事。有知情人士消息称，影片男女主角分别为人气甚高的“小鲜肉”李易峰和杨幂。如果消息属实，这将是“峰幂”组合继《古剑奇谭》后的第二次银幕合作。预计将于五月底至六月初开机拍摄。', '杨幂', '陈国辉', 4.9, 101830, 'tt4892714', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2287482537.jpg', 31.2, 27.5, 21.2, 6.7, 13.4, '-0.075119,0.124744,-0.450913,0.631915,0.781993,0.036329,0.328587,0.123295,-0.310467,-0.160484,-0.161968,0.670037,-0.905621,0.123081,0.283807,-0.420847,-0.109649,-0.805225,-0.432672,-0.268255,0.026135,-0.190641,-0.224736,0.157978,-0.137498,-0.192725,0.972130,-0.058280,-0.456093,0.489542,0.816293,0.067590,-0.240899,0.120024,-0.053389,0.048158,0.205599,0.268116,-0.863482,0.413001,-0.307237,-0.178251,-0.001810,-0.095895,0.188505,0.158942,0.524434,-0.148039,-0.173432,0.017486,0.986578,-0.030777,-0.165559,-0.293362,0.531834,0.288044,0.773067,0.159771,0.029380,0.051993,-0.334327,-0.437308,-0.800642,0.177159,0.484613,0.052007,-0.388657,0.188773,-0.381974,0.062728,0.049665,-0.144517,0.593107,0.317730,0.432167,0.140740,0.304881,0.133661,-0.035317,0.706059,0.310935,0.382420,-0.154379,0.444443,0.125342,-0.605140,-0.306187,-0.019568,-0.421602,0.381232,0.187294,-0.259330,0.036420,0.140645,-0.299091,-0.177673,0.123111,-0.298373,0.319059,-0.153842,0.030695,-0.888111,-0.353580,-0.507067,0.070740,-0.408154,0.514505,-0.348394,1.059268,-0.941712,-0.012064,0.414689,0.270046,-0.504853,0.876912,0.199053,-0.032833,-0.265853,0.109002,-0.343225,-0.167533,0.141292,-0.002833,0.293312,-0.118844,-0.561832,-0.451759,0.177141', '27602116', '1322847', '3318306', '26890502');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26412106', '电击女孩', '剧情', '阿梅（Punpun Sutatta 饰）样貌平平个性内向成绩普通，是校园里幽灵般不起眼的存在，把她扔进人堆里，保准你再也找不出她来。这样的阿梅，内心里隐藏着一个令她万分苦恼的秘密，那就是她喜欢上了名为费姆（刁•他那博•利拉达那甲春 Tor Thanapob Leeratanakachorn 饰）的男生。费姆是校园里的风云人物，长得英俊帅气，个性更是阳光开朗，站在这样的男生身旁，阿梅连想都不敢想象。更糟糕的是，阿梅拥有着心跳过速便会释放电流的奇怪能力，并因为这能力而遭到了同学们的孤立，阿梅自己亦因为害怕伤害他人，而选择了自我封闭。最终，在好友阿鹏（班•提迪•玛哈裕达鲁 Thiti Mahayotaruk 饰）的鼓励之下，阿梅决定不再隐藏，她的感情能否得到回应呢？©豆瓣', '苏卡达·顾珑希', '查亚诺普·布恩帕拉科布', 7.7, 19247, 'tt5084388', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2266425241.jpg', 0.4, 2.9, 29.6, 47.4, 19.7, '0.381445,0.035953,-0.699124,0.671487,-0.280475,-0.076137,0.723986,0.119307,-0.592502,-0.130442,-0.076691,0.477620,-0.053724,0.423047,-0.189878,0.053523,-0.206887,-0.596363,-0.226656,-0.180284,-0.121393,-0.321346,-0.308478,-0.234069,-0.226473,-0.387513,0.363073,-0.065664,-0.372729,0.213719,0.380283,0.141324,0.099402,0.382232,-0.150679,-0.113620,-0.232689,-0.028362,0.208267,0.187812,0.108877,-0.081876,0.154832,0.390208,0.082134,0.351910,0.527775,-0.235821,-0.285139,-0.008850,0.355744,-0.078127,-0.051211,0.302324,0.183863,-0.180246,0.208728,-0.175263,-0.066278,0.206653,0.095899,-0.000545,-0.657916,0.179658,0.345640,0.205220,-0.394341,0.349064,-0.067577,-0.219210,0.152285,-0.185864,0.035182,-0.270834,0.223604,0.200863,-0.154081,0.079192,-0.296346,-0.014678,0.474784,0.094057,-0.475950,0.335364,-0.628143,-0.384880,-0.129466,-0.249628,-0.655154,0.067246,0.046183,0.269974,-0.002316,0.041837,-0.417786,0.275735,0.007517,0.242693,-0.346056,-0.297140,-0.026454,-0.186447,-0.135744,-0.532469,-0.427642,0.034190,-0.210953,-0.268297,0.724426,-0.707373,0.039232,0.433109,0.467654,-0.217761,0.532710,0.084103,-0.029169,0.028106,-0.180120,0.413410,-0.046772,-0.023594,-0.137615,0.427518,-0.141176,-0.154337,-0.427079,0.420812', '26348103', '24756472', '4058933', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26412618', '六人晚餐', '剧情', '人送外号“厂区终结者”的热血青年丁成功（窦骁 饰）和冰山美人林晓蓝（张钧甯 饰）因为一场厂区青年之间的大战而偶遇并暗生情愫。与此同时，丁成功的父亲——单身爸爸丁伯刚（吴刚 饰）正在与林晓蓝的母亲——单身妈妈苏琴（邬君梅 饰）展开一场中年之恋。随着两个单亲 家庭每周举行的六人晚餐，丁成功和林晓蓝就此开始一段青春飞扬而又充满悲怆的爱情故事。', '窦骁', '李远', 5.5, 4843, 'tt10453114', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2463001905.jpg', 5.6, 35, 42.8, 12, 4.6, '-0.049915,-0.057565,-0.360364,0.412258,0.073637,-0.361178,0.804402,-0.141209,-0.382335,-0.284511,-0.082085,0.548035,-0.403287,0.774497,0.540629,-0.546443,-0.081858,-0.619231,-0.111147,0.311870,-0.112849,-0.219574,0.348628,-0.028640,0.009063,0.160984,0.849891,0.066846,-0.017763,0.920178,0.636346,0.389973,-0.476153,0.382629,0.078370,-0.011084,0.122805,0.296209,-0.623963,0.032459,0.275922,-0.055025,-0.057223,-0.071670,-0.235348,0.191495,0.798782,0.001160,0.004981,-0.124834,0.430906,0.080827,-0.032290,0.074267,0.331908,0.165621,0.362868,0.063788,0.078632,-0.150260,0.047777,-0.336084,-0.061162,0.142165,0.253499,-0.053737,-0.046368,0.477205,0.108135,0.051780,0.289948,0.040985,-0.002145,0.286958,0.600902,0.459071,-0.351986,0.059598,-0.320205,0.320096,0.594359,0.166681,-0.045777,0.381740,0.073412,-0.541747,-0.080376,0.176594,-0.446274,0.183774,0.254741,0.067305,0.175023,0.253720,-0.962971,-0.059319,-0.226466,0.054965,0.272357,-0.256210,-0.080501,-0.723387,-0.101857,-0.448360,-0.212045,0.312595,0.180765,-0.233886,0.408085,-0.778683,0.282166,-0.146392,0.013915,-0.326072,0.408999,0.249886,0.391780,-0.459007,0.017803,0.293850,-0.105374,-0.074588,0.133906,0.360680,-0.333503,0.068514,-0.291399,0.244050', '35256235', '26365262', '10174444', '20390013');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26413089', '火车上的女孩', '剧情', '蕾切尔（艾米莉·布朗特 Emily Blunt 饰）有着严重的酒精依赖症，为此，丈夫汤姆（贾斯汀·塞洛克斯 Justin Theroux 饰）离开了她，和名为安娜（丽贝卡·弗格森 Rebecca Ferguson 饰）结婚，没过多久，两人有了爱情的结晶，这令无法生育的蕾切尔痛彻心扉。每天，蕾切尔都会搭乘火车进城，车窗外一闪而过的画面中，美丽的女子梅根（海莉·贝内特 Haley Bennett 饰）的身影吸引了蕾切尔的注意。年轻美丽的梅根住在舒适的大宅之中，有着英俊的丈夫斯科特（卢克·伊万斯 Luke Evans 饰），两人恩爱有加，她拥有着蕾切尔渴望但无法拥有的一切。然而某日，蕾切尔震惊的发现梅根竟然在和一名陌生男子偷情，而没过多久，报纸上便刊登出了梅根失踪的新闻。©豆瓣', '艾米莉·布朗特', '泰特·泰勒', 6.5, 19348, 'tt3631112', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2368131430.jpg', 1.6, 11.8, 54.3, 27.1, 5.2, '0.572116,0.117521,-0.879060,0.548917,-0.015331,-0.508186,1.118096,0.402883,-0.511059,0.015783,0.345322,0.756892,-0.318820,0.183026,0.478702,0.467105,-0.659570,-0.655354,0.266444,-0.702477,0.011138,-0.614422,-0.185194,-0.017422,0.037221,-0.661090,0.320782,-0.329508,0.355228,0.712530,0.202455,0.489227,0.119728,0.513395,0.254742,0.158382,0.393673,-0.385907,-0.029247,0.162249,0.068883,0.073897,-0.187050,0.234878,0.102739,0.300200,0.578975,-0.352025,0.178335,0.007815,0.403350,0.134387,0.105961,0.081975,0.207632,-0.260009,0.226332,-0.088686,-0.390233,-0.189510,0.315735,0.116627,-0.402324,0.207568,-0.174253,0.345914,-0.445371,0.015642,-0.294938,-0.212279,0.339300,-0.418932,0.085682,0.274986,0.255177,0.528926,0.295996,0.134658,-0.471903,-0.074575,0.282782,0.128287,-0.724166,0.611098,-0.766118,-0.140457,-0.131355,-0.140292,-0.903318,-0.098840,0.782177,0.142941,-0.011141,0.297262,-0.231145,-0.115147,-0.477884,-0.201529,-0.101413,-0.147885,-0.560006,-0.871508,-0.361320,-0.544140,-0.410073,-0.094461,-0.168768,-0.164410,0.600204,-0.682098,0.330554,0.358027,0.261671,-0.093561,0.790564,-0.215414,0.074550,0.237692,-0.358339,0.816686,-0.000652,-0.090115,-0.067025,0.318656,-0.126000,0.244837,-0.308065,0.434543', '1316693', '2269893', '1301686', '1291554');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26413269', '早死早投胎之地狱摇滚篇', '喜剧', '正在修学旅行中的高中生大助（神木隆之介 饰），其班级所乘坐的客车不幸遭遇了车祸，全班仅有两人幸免于难。当大助再度睁开眼，眼前所展开的，是生前只在书中见过的，血与火、疼痛与苦难交织的地狱图景，令大助感到心有不甘的是，他竟然是所有遇难者中唯一一个坠入了地狱的人，不仅如此，他依旧惦念着暗恋的女生广美（森川葵 饰），希望知晓她的安危。在地狱里，大助结识了地狱摇滚乐队“地狱图”的恶鬼主唱KillerK（长濑智也 饰），他同时亦是大助所就读的地狱农业高校音乐部的社团顾问。为了帮助KillerK完成生前的心愿，大助决定向几乎不可能完成的任务“天道轮回”发起挑战，这也就意味着，毫无音乐基础的他，必须在激烈的摇滚对决中战胜强大而可怕的对手。©豆瓣', '长濑智也', '宫藤官九郎', 7.8, 18663, 'tt4717204', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2279313881.jpg', 1.1, 3.8, 24.3, 45.5, 25.3, '0.095054,-0.013140,-0.774009,0.667198,-0.046031,-0.167484,0.674607,-0.086850,-0.331309,-0.150374,0.442981,0.694736,0.041176,0.263330,0.147507,-0.144662,-0.068972,-0.687594,-0.353502,-0.213768,-0.388341,-0.295330,-0.340108,-0.055993,-0.011959,-0.337106,0.966857,0.392645,-0.182522,0.319055,0.388586,0.418503,-0.225230,0.342980,-0.140218,-0.177078,-0.094082,0.342177,-0.168594,-0.012379,-0.125082,-0.290020,-0.249547,0.400834,-0.081100,0.163996,0.659336,-0.526119,-0.039190,-0.243958,0.397479,-0.359671,-0.161690,0.116701,0.151068,0.128738,0.261150,0.268900,0.009751,0.213401,-0.088108,-0.113614,-0.851264,-0.309507,0.179016,0.091159,-0.316926,0.468626,0.069010,-0.084068,0.219096,-0.076663,0.119893,0.049423,0.298776,0.519057,-0.452503,-0.164479,-0.307806,0.314457,0.838978,-0.141032,-0.470967,0.271825,-0.280160,-0.602186,-0.187074,-0.226726,-0.304952,0.104106,0.201023,0.375871,-0.064184,0.244572,-0.532155,0.059291,-0.097435,-0.133823,-0.254684,-0.426167,-0.023715,-0.589057,-0.202539,-0.220065,-0.134182,0.069378,0.209921,-0.411696,0.785595,-0.938461,0.196836,0.586631,0.180096,-0.162082,0.687191,0.078317,0.116869,-0.228407,0.020648,0.344649,-0.007990,0.486743,0.025863,0.278566,0.048635,0.129158,-0.467204,0.544102', '25880986', '26759819', '25928048', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26413306', '致我们终将到来的爱情', '喜剧', '曹文（黄明 饰）和女主梁爽（李菲儿 饰）拥有甜蜜到令人羡煞的爱情，但是，随着梁爽的姐姐（李金铭 饰）和帅且多金的霸道总裁（立威廉 饰）的出现，七年的爱情长跑终究还是要面对现实中的种种难关。在巨大的压力下，两人的感情变得风雨飘摇，在“爱情还是面包”的抉择之间，上演了一场悲喜交加的内心拉锯战。©豆瓣', '李菲儿', '郑来志', 3.7, 3251, 'tt7188858', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2308492063.jpg', 51.4, 25, 16, 3.5, 4.1, '0.165976,0.057904,-0.733304,0.518518,0.166417,-0.283268,1.093691,0.348798,-0.362698,0.077579,0.476480,0.505172,-0.691024,0.190168,0.398873,-0.348357,-0.021457,-0.897956,-0.022797,0.114258,-0.056885,-0.276964,-0.270449,0.147057,-0.123552,-0.104638,0.940422,0.327916,-0.000985,0.331390,0.551887,0.171597,-0.160661,0.502305,-0.030999,-0.081748,-0.053211,0.467176,-0.537595,-0.174382,0.273989,-0.299300,-0.087034,0.259312,-0.067655,0.032350,0.612384,-0.413721,-0.137333,0.349537,0.440648,-0.184391,-0.396407,0.154371,-0.004002,0.097925,-0.074191,0.240595,-0.161491,-0.013573,0.267993,-0.036175,-0.685594,-0.146771,0.223568,0.246415,-0.517794,0.685612,0.048864,-0.169400,0.200374,-0.222867,-0.180988,0.158753,0.555138,0.858448,-0.463682,0.151179,-0.227017,0.062840,0.970449,0.395540,-0.563004,0.286403,-0.269983,-0.383104,-0.172434,-0.196561,-0.797651,-0.174888,0.276575,0.104524,0.051098,0.454166,-1.058021,0.139352,-0.105683,0.077809,-0.010735,-0.569331,-0.182379,-0.392191,-0.443267,-0.921400,-0.336553,0.375226,0.396468,-0.436241,0.736849,-0.808466,-0.156200,0.234569,0.109593,-0.158186,0.416131,0.367904,-0.159868,-0.118866,-0.232816,0.380035,-0.503965,-0.071343,-0.088266,0.413106,-0.197415,0.260915,-0.576842,0.598941', '25828589', '30209018', '21619567', '3053521');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26414979', '丘奇先生', '剧情', '故事发生在1965年的美国，10岁的女孩查莉（布丽特妮·罗伯森 Brittany Robertson 饰）和身患重病的母亲过着相依为命的日子。一天，一位名为丘奇（艾迪·墨菲 Eddie Murphy 饰）的男人敲响了查莉家的大门，他是来这里照顾这对可怜的母女两的，他的任期很短，只有6个月。然而，丘奇先生在查莉家一待就是六年之久，在他的教导之下，本来毫无目标的查莉开始想要成为一名作家。母亲去世之后，查莉渐渐和丘奇先生失去了联系，走上了自己的人生道路。在上大学的第二年，查莉发现自己的怀孕了，六神无主的查莉再度想到了丘奇先生，并且敲响了他家的家门。丘奇先生收留了查莉，并且担负起了照顾查莉母女两人的责任。©豆瓣', '艾迪·墨菲', '布鲁斯·贝尔斯福德', 8.5, 26054, 'tt4196848', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2337103034.jpg', 0.3, 1, 12.7, 43.5, 42.6, '0.274680,-0.164726,-0.697351,0.372056,-0.379546,-0.616645,0.729771,0.102681,-0.558459,-0.366307,0.219105,0.867736,-0.316285,0.689341,0.603552,0.235351,-0.088160,-0.682465,-0.028159,-0.394925,-0.289063,-0.608847,-0.166773,-0.145721,0.066872,-0.693981,0.377158,-0.087666,0.214847,0.509208,0.117469,0.209440,0.268206,0.282395,-0.214352,0.355531,0.168809,0.031582,-0.146361,0.158405,0.221667,-0.303835,-0.088540,-0.063323,0.038716,0.340290,0.459732,-0.145898,-0.308959,0.083868,0.537740,-0.231033,-0.001920,0.034312,0.630016,0.009782,0.126359,0.496492,-0.470460,-0.282176,0.023057,-0.321694,-0.361194,0.183810,-0.039853,0.024321,-0.931026,0.545374,-0.172085,-0.147823,0.068620,-0.523083,0.227598,0.798014,-0.234481,0.625316,-0.344569,0.209858,-0.527677,0.181661,0.721788,-0.195804,-0.258951,0.493749,0.062104,-0.272235,-0.071098,-0.211679,-0.657589,-0.080776,0.301667,-0.028842,-0.272210,0.010446,-0.430577,-0.038084,-0.362037,-0.186782,0.192186,-0.366865,-0.232158,-0.290953,-0.187587,-0.516198,-0.362527,0.143162,-0.056194,-0.374426,0.795774,-0.981709,0.412683,0.444550,0.270966,-0.347480,0.942836,0.160755,0.258954,-0.016907,0.128483,0.251205,-0.066078,0.314552,0.325074,0.436042,-0.006773,0.017568,-0.522355,0.327477', '1302384', '1292720', '1292219', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26415200', '外公芳龄38', '剧情', '38岁的明星主播何志武（佟大为 饰）在家中精心打扮，准备迎接性感女友“临幸”。打开家门时，外面站着的却是一对陌生母子——来自“胡建”的20岁未婚妈妈唐慧茹（陈妍希 饰）带着5岁的儿子唐家栋（吕云骢 饰）上门认亲……面对从天而降的女儿和小萌孙，正值”芳龄“的何志武无法接受， 要求进行亲子鉴定！然而，结局却令人出乎意料……©豆瓣', '佟大为', '安兵基', 4.2, 23981, 'tt5936462', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2394844095.jpg', 30, 39.2, 25, 4.6, 1.2, '0.130845,-0.046816,-0.577487,0.377190,-0.262176,-0.138210,0.737179,0.454547,-0.498667,-0.548034,0.157306,0.489163,-0.577528,0.634067,0.374582,-0.173807,-0.113909,-0.400128,-0.260989,0.115689,-0.103327,-0.016024,0.100589,0.008705,-0.031752,-0.049960,0.408507,-0.242647,0.270496,0.853301,0.653038,0.246715,-0.219544,0.323187,-0.121409,-0.405419,0.109683,0.311890,-0.239676,0.322302,-0.156469,-0.186868,0.002443,0.199246,-0.283504,0.479490,0.647959,-0.363022,-0.008234,-0.119840,0.664605,0.084342,-0.099866,0.456391,0.199978,0.063016,0.267720,-0.137782,-0.012984,0.026286,0.174015,-0.449680,-0.183114,0.259432,0.529939,0.041232,-0.655903,0.065778,-0.445146,0.244732,0.286118,-0.343283,0.040907,0.281161,0.017083,0.816718,-0.162335,0.270584,-0.616752,0.282680,0.271531,0.287188,-0.053613,0.198124,-0.414228,-0.477522,0.400354,-0.251052,-0.918823,0.181539,-0.148613,0.229901,0.209622,-0.341223,-0.319398,-0.139192,-0.232356,0.193187,0.333859,-0.379211,-0.320285,-0.622671,-0.138122,-0.518669,-0.423812,0.437658,0.163273,-0.162318,0.620176,-0.451565,0.046991,-0.089234,0.354155,-0.249574,0.907729,0.122016,0.002849,-0.399712,-0.258475,-0.013735,-0.421137,-0.118257,-0.188743,0.215475,-0.395792,-0.326135,-0.408305,0.186785', '4066127', '1296897', '1304309', '25738406');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26415327', '盲·道', '剧情', '据民政部估计，全国流浪乞讨儿童数量在100万-150万左右。在一些地乡村地区，买卖儿童几近市场化，形成了一个完整的地下黑色利益链。盲人小女孩晶晶（杜函梦 饰）一直被以郭伟（胡明 饰）为头目的犯罪团伙控制下在街头乞讨赚钱。一天，她在地铁通道里遇到了赵亮（李杨 饰）。赵亮是一名落魄摇滚大叔，整天装扮成盲人进行坑蒙拐骗。为了逃脱郭伟残暴的毒打，她在赵亮的带领下到了派出所，但民警王莉莉（于越 饰）根本找不到晶晶的家，晶晶却说赵亮是她的爸爸，万般无奈之下，赵亮只好暂时收留她。最终犯罪团伙还是找到了他们，并以晶晶“监护人”的身份把她带走，晶晶和犯罪团伙之间到底是什么关系？赵亮为了弄清楚这一切，踏上了一场未知的行程。而他和晶晶的故事才刚刚开始……', '李杨', '李杨', 4.9, 6294, 'tt5662662', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2512138549.jpg', 19.3, 35.8, 30.6, 6.9, 7.4, '0.325283,0.093320,-0.409153,0.047032,-0.205920,-0.205582,0.307592,0.061342,-0.526078,-0.237198,0.345461,0.521604,0.112350,0.164696,-0.103990,-0.069264,-0.254657,-0.404394,0.061916,-0.200578,-0.063595,-0.558059,-0.179259,0.168107,-0.157997,0.054619,0.491115,-0.029044,-0.113493,0.254726,0.283720,0.131139,-0.114283,0.207036,-0.207715,0.048349,0.159944,-0.233502,-0.316920,0.156031,0.081958,-0.241367,-0.130937,0.042052,0.078849,0.348689,0.666653,-0.247376,-0.088047,-0.019255,0.110658,-0.462363,-0.234890,-0.148604,0.330380,-0.038613,0.480197,0.222087,-0.317081,0.089538,0.369564,0.146840,-0.510343,0.024256,0.273148,0.303816,-0.588235,0.145403,0.061304,-0.248890,0.223371,-0.519174,0.167333,0.343736,-0.004644,0.332588,-0.354705,-0.133850,-0.746712,0.186612,0.594642,0.057993,-0.084385,0.138438,-0.086514,-0.240063,0.004873,-0.236242,-0.386508,0.020990,0.309809,-0.192463,-0.477991,-0.029425,-0.700342,0.050708,-0.284140,-0.056803,-0.116060,-0.427915,-0.153353,-0.356419,0.073550,-0.368294,-0.185199,-0.019460,0.055070,-0.238142,0.392905,-0.817100,-0.064862,0.673337,0.395512,-0.400891,0.405910,0.102415,0.235173,-0.172425,-0.027640,-0.099194,-0.031240,0.610151,0.017794,0.261171,0.074183,-0.180052,-0.201723,0.381030', '1292829', '30345227', '3044878', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26416062', '侏罗纪世界2', '动作', '自侏罗纪世界的骚乱以来，种类繁多的恐龙在努布拉岛度过了三年无拘无束的时光。然而该岛火山活动频繁，随时有喷发的危险。致力于恐龙保护的克莱尔·戴宁（布莱丝·达拉斯·霍华德 Bryce Dallas Howard 饰）受到班杰明•洛克伍德的邀请。班杰明及其下属伊莱·米尔斯（拉菲·斯波 Rafe Spall 饰）希望她和相关技术人员前往努布拉岛拯救那里的恐龙，并将它们安置在新的栖息地。受到感染的克莱尔设法找来欧文（克里斯·帕拉特 Chris Pratt 饰）一同前往，欧文则希望救出他亲手驯养的迅猛龙小蓝。当他们踏足这座隔绝之岛时，却发现事情没那么简单。火山蠢蠢欲动，随时爆发，而混乱之中丑恶的阴谋悄然酝酿……©豆瓣', '克里斯·帕拉特', 'J·A·巴亚纳', 6.6, 364397, 'tt4881806', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2522069454.jpg', 1.2, 9.4, 52, 30.6, 6.8, '0.018651,0.054616,-0.865778,0.394751,0.193124,-0.001631,0.651895,-0.007431,-0.335099,-0.040391,-0.030580,0.605256,-0.082963,-0.076695,0.118239,-0.024985,-0.524501,-0.377965,0.099818,-0.034322,-0.219667,-0.190768,-0.486924,-0.396278,0.072844,-0.577404,0.477387,0.142187,-0.108943,0.321623,-0.199637,0.522318,-0.284308,0.506298,0.081188,-0.251554,0.114682,0.063040,-0.212210,0.328716,-0.291366,0.196350,-0.211008,0.154250,0.284123,0.335834,0.461326,-0.477872,-0.014200,-0.206939,0.094000,-0.260468,0.317761,0.149984,0.307332,-0.251104,-0.093378,0.100002,-0.519927,0.159876,-0.063593,-0.409416,-0.514954,-0.140887,0.068167,0.197480,-0.510288,0.097541,0.043844,-0.160292,0.318358,-0.227577,0.132940,0.747590,0.190287,0.147621,0.073981,0.028389,-0.342298,-0.065606,0.745305,-0.187233,-0.320143,-0.100020,-0.082974,-0.344429,-0.055293,0.007076,-0.322657,-0.259506,0.367183,0.178836,-0.069703,0.429814,-0.656923,-0.108921,-0.419000,-0.416251,-0.068553,-0.188396,-0.230729,-0.906825,0.069338,0.111205,0.170007,-0.186235,0.072806,-0.063367,0.412312,-0.723859,0.676175,0.476691,0.244514,-0.302397,0.401909,-0.203711,0.100353,-0.414264,-0.256455,0.484125,0.255879,0.387577,-0.032789,0.157489,0.297242,-0.238589,-0.301555,0.515840', '3871833', '3178770', '1453067', '1306723');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26416155', '汽车人总动员', '喜剧', '8岁男孩卡卡聪明活泼，是一个顶尖汽车工程师，他在助手兼玩伴丁丁的帮助下，开发出了名为“K系统”的芯片。K系统可实现高智能操作，实现人车对话。第一辆下线的K1开朗爱说，很快和丁丁打成一片。卡卡并不满足，他再接再厉又开发了冷静淡定的K2和堪称接近完美的K3。未过多久，卡卡收 到了“高级智能汽车大赛”的邀请函，他信心满满，决定带着三辆宝贝车参加比赛，为此他专门为三部车定制了严苛的训练计划。比赛一天天临近，这三部个性十足的智能车会取得怎样的成绩？©豆瓣', '刘馨萱', '卓建荣', 2.8, 21811, 'tt4839424', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2253581205.jpg', 84.8, 3.2, 4.6, 3.6, 3.9, '-0.005909,0.539689,-0.501364,0.558149,-0.421903,-0.250990,0.216383,-0.010322,-0.136672,0.052062,0.205924,0.350364,-0.179341,-0.017766,0.189902,-0.217167,-0.252397,-0.279032,-0.007730,0.180851,-0.303036,-0.419990,-0.091440,-0.203477,0.387528,-0.473438,0.724921,-0.029160,-0.077455,0.448783,0.190232,-0.227334,0.091564,0.213323,-0.126163,-0.101584,0.266146,0.001873,0.087836,0.336925,-0.337747,0.119611,-0.041283,-0.196302,0.128292,0.354076,0.578171,0.030895,-0.491926,0.399813,0.462514,-0.215871,-0.091614,-0.166280,0.126692,0.281851,-0.224271,-0.051250,-0.171867,0.289654,-0.421874,-0.070044,-0.830399,-0.125791,-0.337493,-0.354086,-0.741393,0.413145,-0.488437,-0.136662,0.137251,-0.409716,-0.015902,0.309863,0.027257,0.434669,-0.020439,0.391547,-0.508158,0.260490,0.374376,-0.136549,-0.432433,0.531432,-0.088130,-0.682763,-0.131651,-0.604711,-0.339900,-0.124137,0.364638,-0.079892,0.166360,-0.193370,-0.500946,0.200568,-0.054561,-0.288331,0.118136,-0.396368,0.099131,-0.833230,0.104617,-0.267435,-0.321204,-0.188747,-0.135766,-0.503064,1.127954,-1.028805,-0.053669,0.233306,0.140005,-0.471768,0.552686,0.005091,0.025270,-0.458796,-0.041809,0.019283,-0.193782,0.257532,-0.006572,0.571589,0.060212,-0.324865,-0.627579,0.726973', '24284209', '27602116', '25922902', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26416169', '纯情', '剧情', '电影《纯情》讲述了一封在音乐节目直播过程中收到的来自23年前的信所引发的故事，描述了超越过去与现在的初恋和5名朋友之间的友情。片中，都暻秀饰演性格木讷但一片丹心的范实，金所炫饰演拥有天籁美声的少女秀玉。据了解，《纯情》将在今年夏天拍摄，预计於2016年2月上映，拍摄地点在全罗南道高兴郡。此前都暻秀通过电影《Cart》、电视剧《没关系，是爱情啊》、《记得你》展现精湛演技。而童星出身的金所炫更有着丰富的戏剧经验，主演了电视剧《想你》《Reset》《Who Are You-学校2015》等热播韩剧。2014年金所炫主演KBS一集特别企划剧《不一样的哭泣》，并凭借此剧在年末KBS演技大赏中获得女子部独幕剧奖。此次电影中与EXO D.O.合作主演，是金所炫首次担纲女主角，金所炫也表示感觉演戏很幸福，只要跟着哥哥就对了 。', '都暻秀', '李恩熙', 7.4, 14241, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2314222118.jpg', 0.9, 4.8, 37.4, 38.1, 18.8, '-0.104643,-0.357330,-0.354143,0.747123,0.367624,0.079439,0.275271,-0.013209,-0.158094,-0.276910,-0.022159,0.728378,-0.607687,-0.051250,0.260494,-0.371850,-0.339089,-0.719198,-0.398759,-0.340903,0.227868,-0.235004,-0.131867,0.310632,-0.238601,-0.574772,0.966702,-0.014156,-0.459488,0.578654,0.347754,0.013499,-0.150753,0.047262,0.284491,-0.004291,-0.041442,0.393610,-0.354863,0.376362,0.181395,-0.098881,-0.038916,0.051342,0.273225,0.103513,0.661860,-0.187720,-0.223657,0.188921,0.677223,-0.064712,-0.060253,-0.131010,0.257215,0.175105,0.602548,0.261710,-0.106121,0.142246,-0.316768,-0.403259,-0.852996,0.001609,0.420986,0.076312,-0.413543,0.318434,0.009830,-0.081239,0.193410,-0.202103,0.225706,0.139736,0.642382,0.488961,-0.022834,0.028205,-0.214090,0.719249,0.620830,0.207347,-0.083418,0.774399,-0.075309,-0.699505,-0.428518,-0.124493,-0.621776,0.725256,-0.182371,-0.076919,-0.012402,0.070083,-0.066023,0.053962,0.381885,-0.081817,0.062712,-0.614968,0.088075,-0.920789,-0.438587,-0.316292,0.004487,-0.346052,0.307575,-0.644600,0.994981,-0.788665,0.056483,0.387944,0.342656,-0.341426,0.855160,0.283542,-0.325565,-0.150545,-0.003517,0.096780,0.018551,-0.384716,-0.071243,0.240097,-0.076502,-0.614044,-0.396602,0.504939', '27602116', '1322847', '25880986', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26416603', '萨利机长', '剧情', '影片根据真实事件改编，2009年1月15日，萨利（汤姆·汉克斯 Tom Hanks 饰）在全美航空1549号班担任机长，飞机起飞两分钟后遭到飞鸟攻击，两架发动机全部熄火，萨利决定在哈德逊河上迫降，155人全数生还。但之后的调查显示他做了错误的抉择，认为大可选择返回拉瓜地亚机场。机内到底发生了什么呢？', '汤姆·汉克斯', '克林特·伊斯特伍德', 8.3, 328071, 'tt3263904', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2363503306.jpg', 0, 0.6, 14, 55.2, 30.2, '0.003016,0.029176,-0.544923,0.289899,0.469630,0.103893,-0.053077,-0.137626,-0.442614,-0.230981,0.283011,0.525850,-0.121689,-0.292391,0.539642,-0.107644,-0.852166,-0.604170,0.396018,-0.578801,-0.564467,-0.780841,0.276081,-0.278663,0.481925,-0.038607,0.504236,0.211804,0.135490,0.252683,0.029635,0.044002,-0.069531,0.261307,0.281371,-0.010998,0.090086,-0.142110,-0.077977,0.547924,-0.199515,-0.304950,0.092076,-0.344034,0.407229,0.660530,0.887217,-0.240919,-0.339475,-0.196530,0.234996,-0.194911,0.216673,-0.133264,0.432043,0.147266,-0.389085,0.377711,-0.305730,-0.150726,-0.068401,0.290490,-0.141863,-0.053272,-0.486912,-0.162307,-0.391495,-0.069730,-0.536432,0.155268,0.027722,-0.221139,0.200023,0.404284,0.333776,0.103835,-0.208248,0.045370,-0.406411,-0.076478,0.712215,-0.106465,-0.428368,0.257901,0.567583,-0.492686,-0.352585,-0.346507,0.019104,0.184174,0.132223,0.325953,-0.033860,0.118264,-0.176329,-0.098420,-0.437272,-0.519938,-0.053103,-0.276728,-0.123497,-1.007091,0.335645,0.169005,0.076432,-0.006085,-0.113205,-0.055478,0.374656,-0.594493,0.212178,0.367083,0.193911,-0.428923,0.508783,0.018447,0.035479,-0.478467,0.377932,0.370634,0.130237,0.239792,-0.232334,0.054340,0.084974,-0.351228,-0.035946,-0.206166', '1293572', '3036464', '1293537', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26418093', '错乱的一代', '剧情', '故事发生在爱媛县松山市西部的小港口城市三津滨，失去了父母的内芦原泰良（柳乐优弥 饰）和弟弟将太（村上虹郎 饰）相依为命。对泰良来说，人生仿佛没有任何指望，只有全速奔走直至毁灭而已。在造船厂工作的泰良在一次暴力冲突后，决然地离开了港口。他辗转来到松山市区，一脸戾气的青年随时处于搏杀的状态，凡是看不过眼的人他都敢于挥拳相向，甚至被揍也全部畏惧。在这一过程中，小混混北原裕也（菅田将晖 饰）被泰良狼一般的行径所感染，于是热情过度地跟在了泰良的后边。无差别的殴斗，即使惹上黑社会也在所不惜。这是一段奔向灭亡的危险之旅……本片根据真实事件改编，荣获2016年电影旬报十佳影片第四名。©豆瓣', '柳乐优弥', '真利子哲也', 6.9, 10703, 'tt4912452', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2325862892.jpg', 2.2, 8.8, 41.7, 34.5, 12.8, '0.200448,-0.046401,-0.852386,0.435451,0.305185,-0.164770,0.566790,0.146144,-0.331484,0.064023,0.290362,0.648171,-0.173865,-0.057948,0.261182,-0.269237,-0.090464,-0.670178,-0.262106,-0.110863,-0.272545,-0.270711,0.083316,0.003318,-0.140995,-0.334331,0.633364,0.120121,-0.388639,0.506619,0.159171,0.285463,-0.038179,0.451798,-0.109449,0.161426,-0.077622,0.016069,-0.160319,0.179598,-0.057798,-0.291551,-0.203060,0.311609,0.010225,0.334436,1.004957,-0.396085,-0.152657,-0.084032,0.190752,-0.362414,-0.193830,0.183949,0.361026,-0.119434,0.071242,0.265579,-0.186137,0.071088,0.153627,0.138293,-0.661850,-0.038847,0.042593,0.203428,-0.405539,0.575904,0.114453,-0.190702,0.120049,-0.156942,0.101328,0.287383,0.195473,0.160452,-0.204225,0.224093,-0.397936,0.159815,0.933429,-0.047022,-0.239177,0.330728,-0.067439,-0.257127,-0.411975,-0.374721,-0.388545,-0.148070,0.248293,-0.142691,-0.371708,0.294766,-0.419135,0.040081,-0.037078,-0.299903,-0.059074,-0.199653,-0.280314,-0.510161,0.122528,-0.517508,-0.288061,0.085952,0.113388,0.045481,0.525863,-0.709651,0.204015,0.622976,0.263918,-0.292117,0.484710,0.054167,-0.070723,-0.059746,-0.087363,0.149839,0.227104,0.573633,0.322330,0.270152,-0.185578,-0.163142,-0.101308,0.555641', '2032339', '1870682', '1652618', '1438591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26419635', '高草丛中', '剧情', '贝奇（蕾斯拉·德·奥利维拉 Laysla De Oliveira 饰）和哥哥卡尔（艾弗里·维提德 Avery Whitted 饰）驱车行驶在公路上，半途中，已经怀孕的贝奇感到非常的不舒服，于是下车休息，此时听到路边的高草丛里传来孩子的呼救声，循着声音，贝奇和卡尔先后走进了高草丛中，哪知道就此踏入了地狱的大门内。高草丛仿佛一个有生命的恶魔，吞噬着一切误入其中的生命。在高草丛里，贝奇遇见了同样迷失在此的罗斯（帕特里克·威尔森 Patrick Wilson 饰），这个男人虽然仪表堂堂，却散发着危险的气息。贾维斯（哈里森·吉尔伯特森 Harrison Gilbertson 饰）是贝奇的男友，在女友失踪后，他踏上了寻人之路。©豆瓣', '蕾斯拉·德·奥利维拉', '文森佐·纳塔利', 6.4, 27098, 'tt4687108', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2568737620.jpg', 1.9, 12.4, 53.5, 25.8, 6.3, '0.389600,0.204283,-1.020387,0.670759,0.130809,-0.412647,1.029093,0.333003,-0.340659,-0.227898,0.103272,0.634821,-0.291374,0.111995,0.357039,0.269235,-0.413522,-0.517207,-0.240909,-0.310547,-0.632714,-0.451805,-0.316386,-0.099257,-0.160820,-0.323810,0.208792,0.319983,-0.179756,0.573154,0.243123,0.294977,-0.080140,0.606948,-0.219161,0.052609,0.200576,-0.101197,0.123097,0.056331,0.169508,-0.138299,-0.064331,-0.257568,0.060384,0.343610,0.343666,-0.343913,0.182471,0.154324,0.115610,-0.103196,0.250150,-0.248289,0.290017,-0.284384,0.174250,-0.107191,-0.070993,-0.023038,-0.031677,0.024940,-0.325600,0.182215,-0.214470,0.504627,-0.541919,0.069190,-0.094323,-0.046154,0.271435,-0.401796,0.072731,-0.069534,-0.186714,0.376182,-0.041985,0.095375,-0.822160,-0.667629,0.435849,0.030295,-0.210172,0.176124,-0.209297,-0.696024,-0.125559,0.374164,-0.477008,-0.382646,0.747549,0.163970,0.049537,0.040122,-0.526728,0.055583,-0.300128,-0.007377,-0.312361,-0.219074,-0.467104,-0.484188,0.035653,-0.419278,-0.181873,0.231618,-0.231988,-0.246651,0.353953,-0.573516,0.444637,0.353146,0.366813,-0.006464,0.761385,-0.457053,0.383824,-0.039799,0.053395,0.651428,0.041118,0.307043,0.229958,0.383729,-0.186556,-0.148240,-0.888372,0.503875', '21349345', '30136177', '1302133', '10733357');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26419637', '误杀瞒天记', '剧情', '维杰（阿贾耶·德乌干 Ajay Devgan 饰）和妻子娜蒂尼（施芮娅·萨兰 Shreya 饰）结婚多年，将两个女儿安久（伊西塔·杜塔 Ishita Dutta 饰）和安努（莫伦诺·贾达夫 Mrunal Jadhav 饰）抚养长大，一家人过着宁静的生活，平淡之中自有真味 。某日，安久去参加野营，结识了名为萨姆（Rishabh Chaddha 饰）的男生，此时的她并不知道的是，这位看上去文质彬彬的男孩，会彻底粉碎她的生活。撕下了伪善面具的萨姆竟然想要强暴安久，在激烈的挣扎反抗之中，安久失手杀死萨姆。维杰决定挺身而出保护他无辜的家人，自小热爱看电影的他利用从电影里学到的知识对萨姆的尸体进行了处理和掩埋，但警察的来访让这个家庭再一次陷入了危机之中。©豆瓣', '阿贾耶·德乌干', '尼西卡特·卡马特', 8.6, 215912, 'tt4430212', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2870295964.jpg', 0.2, 0.6, 9.8, 47.3, 42.1, '0.218504,-0.082463,-0.634542,0.461423,-0.279755,-0.310020,0.797063,0.074141,-0.321638,-0.414413,-0.041867,0.601685,-0.115170,0.563409,0.251245,0.167342,-0.284860,-0.822310,-0.130218,0.139713,-0.264916,-0.550349,-0.307112,-0.112065,-0.008857,-0.344428,0.548243,-0.022872,-0.187231,0.518004,0.207228,0.183009,-0.149905,0.419337,-0.086829,0.006480,-0.092373,-0.069479,-0.291577,0.110737,-0.036386,-0.171117,-0.080030,0.129501,0.149180,0.369793,0.688720,-0.328932,0.047204,-0.050652,0.333434,-0.176547,-0.083943,0.409824,0.085254,-0.040219,-0.022565,0.135497,-0.296622,0.051384,0.136097,-0.246504,-0.667684,0.004759,0.094548,0.063191,-0.841151,0.468441,0.067773,-0.159324,-0.156434,-0.165443,0.306879,0.223732,0.219385,0.478724,-0.040497,0.055196,-0.376269,0.174634,0.615981,-0.116608,-0.095211,0.183676,-0.289441,-0.203689,0.158646,-0.405800,-0.481351,-0.022262,0.353522,-0.027048,-0.309224,0.199391,-0.587496,-0.148722,-0.336878,-0.066266,-0.026565,-0.420270,-0.161514,-0.424099,-0.301536,-0.531458,-0.435637,-0.052909,-0.201800,-0.482028,0.679509,-0.744431,0.208080,0.342249,0.325140,-0.239323,0.512958,0.160655,0.270041,0.095726,0.030859,0.378372,0.147645,0.071880,0.167306,0.351720,-0.013386,-0.066724,-0.390385,0.420463', '3111650', '1307146', '1301022', '26809007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26420626', '约翰之子', '剧情', '马蒂厄已经35岁，却从未见过自己的父亲。母亲解释缘由时只推托说他是一夜情的结果。一天，他接到一个陌生来电，这个电话告诉他，他的亲生父亲刚刚过世。于是马蒂厄暂别妻子和孩子，决定飞去加拿大参加葬礼，并见见他那两个素未谋面的兄弟。在蒙特利尔，除了父亲的好友皮埃尔，没人知道他的存在与真实身份。但与此同时，马蒂厄也意识到他似乎进入了一个充满敌意的地方。', '皮埃尔·德隆尚', '菲利普·里奥雷', 8.3, 13343, 'tt4741708', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2363277440.jpg', 0.2, 0.6, 13.7, 53.4, 32.1, '0.222945,0.045490,-0.849390,0.743735,-0.627108,-0.239745,0.962295,0.015064,-0.680350,-0.744460,-0.093400,1.211283,0.094864,0.526242,0.143114,0.261344,-0.048077,-0.587295,0.201191,-0.225048,-0.190124,-0.776737,-0.099607,-0.140169,0.193142,-0.169479,0.281468,-0.105283,-0.239199,0.498388,0.331840,-0.043337,-0.011791,1.034848,-0.234132,0.203568,0.048781,0.406150,-0.174457,0.122214,0.244527,-0.050391,-0.209491,0.449578,-0.172122,0.822118,0.237039,-0.069643,-0.305955,-0.033632,0.207041,-0.246482,-0.139355,0.198678,0.371765,-0.191526,0.282672,0.206042,-0.158944,-0.149671,-0.196901,0.078122,-0.520008,0.178179,-0.214349,0.118828,-0.530115,0.452971,-0.291697,-0.129140,0.004649,-0.485301,0.479264,0.272294,-0.382649,0.425379,-0.337663,-0.038118,-0.522681,0.104689,1.000259,-0.185001,0.053252,0.452925,-0.124267,-0.517786,-0.124749,-0.008029,-0.575772,0.367577,0.055764,0.332784,-0.562124,-0.103147,-0.054413,-0.149778,-0.233939,-0.121840,-0.055924,-0.776117,0.039976,0.041695,-0.295542,-0.220282,-0.579231,-0.021489,-0.046595,-0.239059,0.544873,-0.784755,0.212969,0.477332,0.396102,-0.786295,0.983137,0.580492,0.002079,-0.706316,0.154268,0.435345,0.057934,-0.123947,-0.103135,0.113479,0.141466,0.017051,-0.475218,0.362114', '26718282', '1292064', '1302384', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26420932', '巴霍巴利王2：终结', '剧情', '在旷日持久的大战结束之后，巴霍巴利（帕拉巴斯 Prabhas 饰）最终凭借着他的骁勇善战获得了太后希瓦伽米（拉姆亚·克里希南 Ramya Krishnan 饰）的垂青，太后决定立他为王储，但是，在登基之前，巴霍巴利必须游历他所拥有的国土，学习如何成为一名开明睿智的君主。与此同时，太后还必须小心的平衡巴霍巴利和自己的亲生孩子巴拉拉德夫德斯（拉纳·达格巴提 Rana Daggubati 饰）之间的微妙关系。在经过一个名叫昆达拉的诸侯国时，巴霍巴利邂逅了名为提婆犀那（安努舒卡·谢蒂 Anushka Shetty 饰）的公主，英姿飒爽的公主一下子就俘获了巴霍巴利的心。在将军卡塔帕（挲塞亚拉杰 Satyaraj 饰）的建议之下，巴霍巴利隐姓埋名开始接近公主，随着时间的推移，两颗心渐渐靠近。©豆瓣', '帕拉巴斯', 'S·S·拉贾穆里', 7, 49171, 'tt4849438', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2521118750.jpg', 1.8, 7.8, 39.8, 37.4, 13.1, '0.068279,0.280740,-0.507755,0.734422,0.272226,-0.542453,0.386210,0.554373,-0.166865,-0.248827,0.217671,0.567061,-0.098478,-0.475811,0.511395,0.154930,-0.647758,-0.634979,0.039498,-0.039726,-0.095169,-0.447796,-0.236685,-0.074493,-0.184340,-0.855017,0.363001,-0.337670,0.156267,0.430633,0.387322,0.291233,0.153567,0.135997,-0.008111,0.122216,0.230963,-0.351309,-0.397689,0.133689,-0.081327,0.263465,-0.233760,0.097070,0.320786,0.418760,0.291118,-0.743438,0.485025,0.016542,0.322410,-0.049646,0.151288,0.295346,0.290257,-0.110935,-0.007744,0.298106,-0.317660,0.002525,0.229281,-0.030680,-0.500720,0.094325,0.236229,0.252464,-0.406131,0.398759,-0.184142,-0.139564,0.348550,-0.267437,-0.071351,0.790886,0.070249,0.218572,-0.154277,-0.182024,-0.407749,-0.189225,0.382538,0.036093,-0.430094,-0.162226,0.130535,-0.490595,0.010171,-0.159471,-0.362365,-0.315465,0.247931,-0.016858,0.235288,0.670070,-0.515288,-0.299472,-0.884572,-0.169094,0.258180,-0.373122,-0.238804,-0.236643,-0.188450,-0.287542,-0.158750,-0.148657,0.128160,-0.320597,0.580400,-0.750548,0.286208,0.447219,0.369613,0.005427,0.378106,0.172133,0.175596,-0.074989,-0.322513,0.309613,-0.036009,0.327544,0.044798,0.403584,-0.030532,-0.358421,-0.253447,0.725560', '3285073', '25753326', '3157583', '1858678');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26421474', '埃贡·席勒：死神和少女', '剧情', '二十世纪初，埃贡•席勒是维也纳最受争议的艺术家之一。他的生活与作品常受美丽女子及其所生活的行将末路的时代所驱动。其中两个女人对他产生持续影响——他的妹妹葛尔蒂是他的首位缪斯，而十七岁的瓦莉也逐渐成为其真爱，并在代表作《死神与少女》中留下永恒身影。席勒的极端绘画成为维也纳的丑闻，但诸如古斯塔夫•克里姆特等大胆的艺术家和艺术商却领略到其中的不寻常之处。然而，席勒也准备好翻越自己的痛苦，为艺术牺牲爱情与生命。（小易甫字幕组）', '诺亚·萨维德拉', '迪特尔·贝尔讷', 7.6, 10856, 'tt4558396', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2399988718.jpg', 0.3, 2.4, 31.2, 47.8, 18.3, '0.167603,0.125518,-0.773566,0.728693,-0.073286,-0.131831,1.045937,0.048529,-0.565205,-0.377892,0.139822,1.115428,-0.095541,0.319020,0.446231,0.033834,-0.011132,-0.739897,-0.090508,-0.155007,-0.178492,-0.435047,-0.338133,-0.053160,-0.367395,-0.527289,0.926815,0.276440,-0.362470,0.300706,0.164650,0.389569,0.015458,0.481128,-0.154562,-0.199402,0.006698,0.060881,-0.452676,-0.060791,-0.095499,-0.415125,-0.049310,0.269643,-0.516296,0.151325,0.637148,-0.504197,-0.018929,-0.384644,0.479029,-0.283532,-0.159094,0.087202,0.029711,-0.199042,0.286654,0.294373,0.080252,-0.116841,-0.119001,-0.178347,-0.844482,-0.178020,0.319860,0.205106,-0.536214,0.561131,0.067082,-0.315089,0.125545,-0.164759,0.201204,-0.012880,0.327572,0.396008,-0.176146,-0.163616,-0.386545,0.290851,0.519461,0.223021,-0.699238,0.509414,-0.524291,-0.619876,-0.083371,-0.519653,-0.480827,-0.143511,-0.068466,0.278524,0.109760,0.259035,-0.604051,0.130463,-0.098481,-0.084568,-0.101049,-0.572881,0.052729,-0.607510,-0.243060,-0.660300,-0.295750,-0.166771,0.270452,-0.563900,0.998740,-0.848673,0.336157,0.484053,0.455263,-0.331740,0.829361,0.003652,0.179677,-0.162010,-0.309011,0.458884,-0.234617,-0.044723,-0.317736,0.329455,-0.095244,-0.029431,-0.298971,0.842758', '30162520', '1870681', '1303034', '27666513');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26425002', '阴差阳错的女演员们', '制片国家/地区:', '真木阳子、水川麻美、竹内结子，三位现如今在日本影视界如日中天的青年女演员，其名下各自有一串闪亮光辉的作品名字。不过有没有这样一种可能，如果她们当初都在决定命运的那次试镜中失利，会发生怎样的故事呢？时间为2010年，热爱表演的真木阳子依然只能演些甚至不露脸的小配角，她四处打工，偶然邂逅了某出版社编辑，经对方鼓动准备将画有自己日常的漫画《日刊 真木阳子》拿去发表。水川麻美经常被已经成名的同期白石奈绪所奚落，恼怒之际她结识了真木阳子，两人大吐胸中苦水，烦恼过后却依然四处参加试听，寻找成名的机会。在某出版社担任编辑的竹内结子接到了将《日刊 真木阳子》出版的企划，本并不看好这本书的她不经意间和阳子、麻美产生交集。她们不知不觉间影响着彼此的命运……©豆瓣', '竹内结子', '関和亮', 8, 8366, 'tt4792052', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2400524082.jpg', 0.3, 1.4, 20.3, 52.8, 25.1, '0.250946,0.113311,-0.390332,0.515014,0.106299,-0.311465,0.300068,0.239012,-0.339532,-0.475876,0.163088,0.554063,-0.428245,0.307399,0.116638,-0.153076,-0.372306,-0.748660,0.110666,-0.149951,0.341405,-0.186423,-0.262137,-0.046004,-0.366308,0.008304,0.715399,0.105900,-0.204430,0.278801,0.154309,0.195984,-0.088942,0.286027,0.094323,0.193908,-0.005544,0.085738,-0.061262,0.214454,0.160829,-0.291129,-0.175044,0.207193,0.125124,0.434326,0.533893,-0.016596,-0.302124,-0.083454,0.486862,-0.051197,0.005938,0.284010,0.223438,0.255327,0.317593,0.269582,-0.160208,0.062222,-0.051049,0.005489,-0.511153,0.047034,0.135951,0.390672,-0.158221,0.514471,-0.129013,-0.163629,0.239199,-0.227904,-0.086230,0.374411,0.451903,-0.110885,-0.173258,0.136381,-0.200902,0.443933,0.486260,-0.100001,0.076991,0.328515,0.103351,-0.234428,-0.171467,-0.008094,-0.238325,0.109943,0.228370,0.254292,-0.135033,0.096571,-0.563941,0.141783,0.147727,-0.147953,0.135576,-0.253526,-0.043509,-0.681481,-0.085533,-0.276348,-0.346005,-0.174663,0.288441,-0.166762,0.947020,-0.708488,0.056376,0.471656,0.072404,-0.192231,0.532380,0.274981,-0.291865,0.007766,-0.025249,-0.118683,0.004146,0.584827,0.130822,0.324268,0.208090,-0.189610,-0.181106,0.222484', '3811356', '27602116', '25863940', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26425035', '齐木楠雄的灾难 真人版', '喜剧', '《齐木楠雄的灾难》是根据麻生周一原作漫画改编的真人电影，由福田雄一执导并编剧。由山崎贤人主演、桥本环奈、新井浩文和吉泽亮等共同出演，于2017年10月21日在日本上映。电影《齐木楠雄的灾难》改编自麻生周一的漫画，导演福田雄一，讲述生来就有超能力的主人公高中生齐木楠雄，每天都面临着各种灾难的日常，是一部校园喜剧 。', '山崎贤人', '福田雄一', 5.9, 13555, 'tt4773438', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2485744460.jpg', 7.6, 24.3, 43.6, 16.9, 7.7, '-0.155673,-0.439772,0.057885,0.267723,0.560032,-0.285860,0.380115,0.287768,-0.284612,-0.528772,0.290367,0.730102,-0.523778,0.235456,0.345029,-0.327385,-0.628693,-0.476201,-0.472657,0.245154,0.394252,-0.193252,-0.000030,0.026708,0.000891,-0.452031,0.974682,0.250738,-0.197060,0.225148,0.342682,0.163508,-0.192128,-0.036231,0.485608,0.232804,-0.310103,0.145071,-0.585489,0.613947,-0.218748,-0.178038,-0.315275,0.099311,0.118813,0.337415,0.640084,-0.215094,-0.156364,-0.115377,0.825401,-0.378617,-0.338848,-0.036607,0.501691,-0.024502,0.313623,0.486086,-0.227383,-0.018479,-0.133268,-0.356532,-0.620424,-0.244637,0.069229,0.450321,0.261133,0.516423,-0.001825,-0.112773,0.369602,-0.136888,-0.275332,0.199138,0.753489,0.295165,-0.321189,0.340563,0.021675,0.815334,0.492047,0.093598,0.047429,0.656660,-0.100024,-0.557158,-0.581048,-0.233580,-0.533076,0.429350,0.044465,-0.294596,-0.118618,0.013898,-0.270022,0.012592,0.501215,-0.459661,0.338843,-0.193464,0.230101,-1.201765,0.052661,-0.432375,0.138453,-0.332272,0.802229,-0.414032,1.222358,-0.455782,-0.109909,0.906747,-0.013100,0.033075,0.519555,0.158940,-0.504781,-0.204072,0.126343,0.192777,-0.099081,0.478879,0.041201,0.397402,0.401999,-0.355916,-0.089895,0.178914', '1322847', '2369613', '5403927', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26425062', '武林怪兽', '喜剧', '屈服？反转？逆套路？这是一个超乎你想象的武林爆笑故事！东厂悬赏价值三万两的奶凶怪兽，让各方异士垂涎不已。一波杂烩大侠们临时组队，做起了一夜暴富的白日梦，古天乐郭碧婷貌合神离、陈学冬欺软怕硬、周冬雨威逼利诱、潘斌龙孔连顺颜值狙击，各路大侠花样百出！到底谁能走向人生巅峰呢？', '古天乐', '刘伟强', 3.5, 27994, 'tt9378850', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2540374845.jpg', 50.1, 31.5, 14.8, 1.9, 1.7, '0.065453,-0.090598,-0.083305,0.231125,0.040000,0.099897,0.119549,0.135317,-0.385494,-0.003297,-0.065772,0.280084,-0.328439,0.020831,-0.209366,-0.661944,0.214712,-0.315025,-0.123747,0.089463,0.105440,-0.226426,-0.435101,-0.133781,0.006592,0.272121,0.018592,-0.026269,-0.405724,0.086474,0.942906,0.115672,-0.035903,-0.126048,-0.277191,-0.072355,0.338399,0.166609,-0.286306,0.023602,-0.387102,-0.261978,-0.084463,0.217815,-0.216440,-0.299206,0.221072,-0.250447,0.033481,-0.102262,0.261381,-0.177017,-0.246921,0.066406,0.104689,-0.033314,0.069712,-0.058667,0.216905,0.226739,-0.049608,0.436868,-0.918870,0.019565,0.189172,-0.129022,-0.416262,-0.320266,0.055800,-0.023116,-0.059780,-0.211220,-0.012402,0.233321,0.403535,0.368211,0.150488,-0.153406,-0.699342,0.327013,0.645040,0.086442,-0.100497,0.133778,0.383377,-0.440794,0.091430,-0.518806,-0.371870,-0.018609,0.029876,-0.457726,0.103439,0.326099,-0.479616,0.084770,-0.024487,0.150585,-0.417652,-0.244751,-0.209065,-0.288151,-0.198714,-0.098724,-0.072192,0.165923,0.476940,-0.241688,0.756531,-0.266363,-0.165284,0.158647,-0.122687,-0.536799,0.304984,0.192625,-0.339618,0.154744,-0.093936,-0.173210,0.224703,-0.004193,0.111585,0.125970,-0.247905,-0.135277,-0.107025,0.148195', '3718665', '1438924', '27602116', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26425063', '无双', '剧情', '身陷囹圄的李问（郭富城 饰）被引渡回港，他原本隶属于一个的跨国假钞制贩组织。该组织曾犯下过多宗恶性案件，而首脑“画家”不仅始终逍遥法外，连真面目都没人知道。为了逼迫李问吐露“画家”真实身份，警方不惜用足以判死刑的假罪证使其就范。就在此时，富有的遗孀阮文（张静初 饰）申请保释李问，而警方提出的条件依然是“画家”的真面目。原来早在十数年前，李问和阮文是一对画家情侣，无奈女友的作品受人青睐，李问的画作却被贬得一文不值。就在此困顿期间，他制作假画的才能被“画家”（周润发 饰）发掘，进而成为对方美元假币团伙中的一员……©豆瓣', '周润发', '庄文强', 8, 887052, 'tt7183578', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2535260806.jpg', 0.3, 1.8, 20.2, 52.3, 25.4, '-0.005175,0.119763,-0.388784,0.529267,-0.315872,-0.098632,0.371950,0.161244,-0.586163,-0.333959,0.420771,0.683848,-0.076259,0.189728,0.043313,-0.153410,-0.088095,-0.694041,-0.018602,-0.426569,0.053990,-0.587500,-0.434012,-0.133998,-0.359784,-0.011256,0.646048,-0.020892,-0.179192,0.042979,0.543552,0.281211,-0.215720,0.229806,-0.186063,-0.256682,0.136028,0.101582,-0.452634,0.122880,-0.033286,-0.655186,-0.077995,0.141763,-0.294757,0.309299,0.504713,-0.168260,-0.254863,-0.107799,0.550534,-0.499194,-0.152966,0.300524,0.399674,0.004698,0.486768,0.212305,-0.309140,0.068456,0.217085,0.056716,-0.961250,-0.216912,0.399664,0.165226,-0.435848,0.246558,-0.399707,0.066846,-0.035506,-0.270250,0.311882,0.075288,0.109752,0.242284,0.036381,-0.101491,-0.656756,0.535816,0.279874,-0.102777,-0.245069,-0.009953,-0.143317,-0.505892,0.025107,-0.520546,-0.097465,0.239588,0.233413,-0.213645,-0.105173,0.103873,-0.345207,-0.344702,-0.383739,0.106296,-0.161363,-0.256261,0.023135,-0.396953,-0.214011,-0.268047,-0.017197,0.018142,0.169894,-0.385124,0.501117,-0.619769,0.199282,0.421813,0.227716,-0.604430,0.466219,0.290224,-0.104089,-0.084804,-0.435079,0.021999,0.307899,0.254136,0.012843,-0.054202,0.200551,-0.439555,-0.051792,0.119219', '3670447', '1793491', '27073234', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26425068', '追龙', '动作', '20世纪60年代，中国香港鱼龙混杂，混乱不堪。英国人治下的皇家警察贪婪无度，甚至与黑道相互勾结，搜刮民脂。年轻探长雷洛（刘德华 饰）踌躇满志，小心周旋在英国人和华人上司之间，并瞅准一切机会攀登权力山峰。在某次火并事件中，雷洛看中了敢打敢杀的伍世豪（甄子丹 饰）。来自南洋的伍世豪义字当头，情愿为兄弟两肋插刀。他凭借一股闯劲儿在黑道打出自己的位置，同时借着与雷洛相互帮衬的势头而声名鹊起。最终，刀头舔血的雷洛和伍世豪共同成为分别执掌白道和黑道的重量级人物。而在这一过程中，这对兄弟也渐渐发生分歧。当风暴来临之际，一切即将变化……©豆瓣', '甄子丹', '王晶', 7.2, 333772, 'tt6015328', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2499052494.jpg', 0.9, 5.3, 38.6, 43.5, 11.7, '-0.026182,0.065072,-0.810845,0.328523,0.099950,0.051885,0.430438,0.138753,-0.617674,0.093501,0.237820,0.715043,-0.196007,-0.221890,0.361772,-0.442687,-0.010477,-0.970043,-0.123087,-0.129651,-0.140596,-0.353402,-0.522998,-0.257300,-0.156650,-0.122101,0.622283,0.233951,-0.224732,0.517760,0.394920,0.215159,-0.248989,0.420582,-0.320854,-0.128355,0.079308,0.006404,-0.775432,-0.068428,-0.112733,-0.206047,-0.184737,0.024401,0.003845,0.331779,0.478413,-0.232083,0.172563,-0.131292,0.124905,-0.148144,-0.166066,0.058339,0.510030,0.129033,0.257604,0.366128,0.180667,-0.192652,0.008093,-0.105145,-0.623087,-0.090107,0.199091,0.259102,-0.433790,0.590821,0.173224,-0.286664,-0.082828,-0.020124,0.198957,0.284869,0.303217,0.172888,-0.134791,0.039090,-0.191748,-0.039658,0.657504,0.105948,-0.138792,0.117710,0.032542,-0.122428,-0.224982,-0.382419,-0.085309,-0.411326,0.415555,-0.048594,-0.030859,0.559202,-0.541663,0.006833,0.172849,0.036311,0.174362,-0.345977,-0.073607,-0.400153,-0.534097,-0.501802,0.087025,0.329798,0.198751,-0.013917,0.502623,-0.733963,-0.020480,0.558870,0.361799,-0.432513,0.545967,0.348135,0.097343,-0.310389,-0.437563,-0.044355,0.262312,0.105101,0.028923,0.098033,-0.291265,-0.112330,0.138885,0.168983', '1480318', '1433736', '1293829', '1294713');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26425072', '明月几时有', '剧情', '故事发生在1940年代的香港，妙龄少女方兰（周迅 饰）和母亲（叶德娴 饰）一起过着相依为命的生活，两人将家中的二楼租住给了作家茅盾（郭涛 饰）和其太太孔德沚（蒋雯丽 饰）。方兰十分热爱茅盾的文字，在其中感受到了火热的革命热情和澎湃的民族气节，然而对于身边动荡的时局和紧张的政治氛围，方兰却知之甚少。 刘锦进（彭于晏 饰）是拥有着矫健身手的进步青年，受组织委托，他负责护送滞留在香港的一批重要文人返回大陆，茅盾一家人便在名单之列。在误打误撞之中，方兰被卷入了这一危险的行动之中，并在刘锦进的建议和鼓励之下，加入了革命队伍之中去，母女两人因此被卷入了历史的滚滚洪流之中。©豆瓣', '周迅', '许鞍华', 6.9, 86452, 'tt7075594', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2479605659.jpg', 1.4, 8.6, 44.6, 36.4, 9, '0.373731,0.100754,-1.101432,0.755755,0.063253,-0.059316,0.878402,0.258697,-0.695481,-0.054854,0.156253,0.789452,-0.143720,0.247938,0.370607,-0.089638,-0.113139,-0.814711,-0.243989,-0.114938,-0.232356,-0.428835,-0.217849,0.036473,-0.384777,-0.372143,0.449370,0.320373,-0.376517,0.722240,0.251693,0.375520,-0.547342,0.721216,-0.126918,0.089547,-0.000136,0.083264,-0.446448,0.033650,0.070820,-0.262113,-0.159274,0.129569,0.177397,0.078330,0.828059,-0.288580,-0.051378,0.043357,0.332359,-0.123112,-0.067753,0.109968,0.529860,0.321296,0.348143,0.425511,-0.173762,0.259262,0.038123,-0.252506,-0.636633,-0.010055,0.251957,0.274095,-0.898549,0.711502,0.098562,-0.369566,-0.089308,-0.265268,0.436352,0.399187,0.109026,0.449760,-0.075577,-0.009761,-0.391004,0.217724,0.649700,0.005611,-0.187539,0.177937,-0.452571,-0.410411,-0.196868,-0.180983,-0.302320,-0.231669,0.381885,0.125763,-0.139944,0.194175,-0.643452,0.147337,0.068863,-0.213646,-0.134831,-0.464620,-0.067648,-0.507667,-0.333439,-0.637620,-0.361247,0.143184,0.032809,-0.107857,0.897341,-0.749713,0.153183,0.413453,0.356255,-0.402119,0.726287,0.023032,0.312561,0.027687,-0.040416,0.023495,-0.049281,0.275746,0.281068,0.507302,-0.291824,-0.099303,-0.303332,0.342376', '3111650', '1414808', '21360412', '2364074');
