INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26425081', '合约男女', '喜剧', '保险公司CEO叶瑾（郑秀文 饰），是众人心中不怒而威的霸道女总裁，对爱情感到绝望的她认为只有对孩子的感情才是永恒的，于是决定借精生子。在严格的层层筛选后，帅气不羁的快递员肖博（张孝全 饰）意外成为孩子父亲的最终人选。有苦难言的肖博，义无反顾地签订了“变态”合约。而此时故事才刚刚开始…', '郑秀文', '刘国楠', 4.3, 14616, 'tt6518634', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2449864312.jpg', 24.8, 42.8, 26.1, 4, 2.4, '-0.170923,0.173042,-0.676672,0.692622,-0.264866,-0.244764,0.574974,0.145801,-0.840472,-0.095001,0.478543,0.670327,-0.227168,0.283787,0.304032,0.098234,-0.020744,-0.624489,-0.438386,-0.288553,-0.181186,-0.487163,0.008096,-0.121426,-0.029883,-0.253249,0.985007,0.077568,0.015000,0.372399,0.655909,0.271506,0.060192,0.497108,-0.147409,-0.174609,0.169542,0.139814,-0.466035,-0.096763,0.253946,0.012055,-0.250665,0.269759,-0.071700,0.322589,0.624432,-0.138531,-0.509207,-0.084137,0.629895,-0.103618,-0.261339,0.245909,0.078480,0.212604,0.394802,0.305653,-0.208588,-0.313958,0.105614,0.028185,-0.743749,0.017154,-0.016726,0.058529,-0.391929,0.514867,-0.321136,-0.114763,0.242382,-0.437464,0.091554,-0.043380,0.691039,0.536320,-0.087218,0.324089,-0.006826,-0.000826,0.568315,0.159094,-0.309289,0.594350,-0.437149,-0.540208,-0.067246,-0.291017,-0.555865,0.002555,0.198224,0.469494,-0.032456,0.202556,-0.507572,-0.214101,-0.231013,0.099885,0.046270,-0.665583,-0.092468,-0.006035,-0.366075,-0.338073,-0.376218,0.158947,0.097379,-0.237826,0.852531,-0.793130,0.259182,0.326807,0.331161,-0.694523,0.485636,0.332177,-0.180065,-0.612905,0.061733,0.310899,-0.250614,-0.069850,0.024843,0.254026,-0.074420,-0.048037,-0.164473,0.622822', '4861408', '26759820', '25880986', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26425533', '回到被爱的每一天', '剧情', '艾伶（王佳佳 饰）曾是一名瑜伽教练，有着稳定的收入和令人羡慕的生活，但不知道为什么，她忽然决定放弃所拥有的的一切，返回地处偏远的故乡小城开始新的生活，虽然她的举动招致了周围所有人的反对，但她还是毅然决然的离开了。在小城，艾伶需要面对的是和父亲艾中华（王志文 饰）之间埋藏已久的矛盾，与此同时，她还要处理同男友姜和（张译 饰）的这一段剪不断理还乱的感情。刚开始，早已经习惯了大城市便利生活的艾伶在小城里感到浑身不自在，做什么事情都束手束脚，随着时间的推移，她渐渐找到了人生的新的方向与意义，而她当初选择离开北京的真正缘由也渐渐的浮出了水面。©豆瓣', '王佳佳', '何平', 7.5, 9202, 'tt4940612', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2277006636.jpg', 1, 4.2, 30.2, 45.7, 18.8, '0.259270,0.149493,-0.813528,0.539552,0.088890,-0.206807,0.616535,0.038196,-0.612525,-0.462157,-0.039203,0.600375,-0.033802,0.298546,0.231971,0.000310,-0.263569,-0.755414,0.140376,-0.235679,-0.318370,-0.438518,-0.254416,-0.309652,-0.144292,-0.113568,0.728191,0.344014,-0.278487,0.368129,0.293877,0.112750,-0.023046,0.720011,-0.269261,-0.027053,-0.169028,0.145089,-0.283750,-0.221396,0.331293,-0.276800,-0.196834,0.084150,0.207971,0.582419,0.513856,-0.147541,-0.469324,0.195296,0.289947,-0.337607,-0.069287,0.048965,0.153841,-0.002720,0.101495,0.168021,-0.241218,0.102540,-0.036068,-0.200636,-0.586318,0.072182,0.237849,0.246474,-0.687312,0.340575,0.088326,-0.248257,0.072565,-0.563844,0.250566,0.520701,0.147454,0.473152,-0.325880,-0.058491,-0.379169,0.177279,0.913110,0.174030,-0.316750,0.487596,-0.217096,-0.428032,-0.341718,-0.051546,-0.338192,-0.184526,-0.030048,0.289451,-0.100899,0.325132,-0.658779,0.042152,0.073037,-0.382097,0.194731,-0.498547,0.026397,-0.262862,-0.234828,-0.659546,-0.252053,0.089445,-0.063562,-0.227913,0.651611,-1.053756,0.230046,0.381880,0.400679,-0.741618,0.412010,0.067131,0.194250,-0.167072,0.057898,0.337341,-0.239092,0.371272,0.106679,0.276877,0.017268,-0.195937,-0.434205,0.636777', '1301022', '35030151', '1870682', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26426019', '我们仍未知道那天所看见的花的名字', '剧情', '郁郁葱葱的小树林中，六个天真无邪同时又各怀心事的男孩女孩快乐玩耍。直到某天，有着天使般可爱面容的“面码”本间芽衣子（谷花音 饰）意外身亡，在其他朋友的心田投射了永远无法磨灭的阴影。许多年后，好友们渐行渐远，而为当年事件深感自责的宿海仁太（村上虹郎 饰）则将自己深锁家中。不知为何，仁太突然看到了长大后的面码（滨边美波 饰）的身影，他将此事告诉了偶然见到的久川铁道（高畑裕太 饰），铁道无比兴奋，连忙将松雪集（志尊淳 饰）、安城鸣子（松井爱莉 饰）、鹤见知利子（饭丰万理江 饰）等其他朋友召集在一起，以找出面码尚未实现的心愿。但心中满布创痕的朋友们，能否重新携手上路呢？本片根据同名动画改编。©豆瓣', '村上虹郎', '西浦正记', 7.5, 6337, 'tt4990696', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2265039688.jpg', 1.1, 4.5, 31.2, 42.4, 20.8, '0.137044,-0.075314,-0.274591,0.363366,0.204422,-0.518133,0.531060,0.268667,-0.375694,-0.280180,0.022885,0.649086,-0.149749,0.421113,0.250069,-0.114915,-0.331212,-0.586602,-0.071874,-0.465712,-0.162978,-0.255060,0.124779,-0.027503,-0.260051,-0.054629,0.843063,0.162902,0.280205,0.603136,0.409226,0.358132,-0.337865,0.236081,-0.067167,0.055597,-0.119738,0.176607,-0.018252,-0.112032,-0.309763,-0.161917,-0.045498,0.194454,-0.111210,0.121851,0.849264,-0.210592,-0.194791,-0.157366,0.149840,-0.031031,0.199692,0.212739,0.171214,0.157404,0.195411,0.106359,-0.446840,-0.026930,0.128336,0.095416,-0.390275,0.100371,0.121542,0.095192,-0.398716,0.010452,0.207086,-0.393436,0.469752,-0.213439,0.109361,0.383397,0.376789,0.150997,-0.363943,0.206625,-0.128853,0.193922,0.395162,0.032774,0.200383,0.365411,-0.092011,-0.184790,0.068681,0.082136,-0.218543,0.087043,0.025209,0.346563,-0.101368,0.201149,-0.450938,-0.164913,0.016604,-0.134302,0.109769,-0.416803,-0.262012,-0.585807,-0.123906,-0.266968,-0.271790,0.224175,0.099652,0.131610,0.792561,-0.720013,0.173223,0.211655,-0.012991,-0.118566,0.528724,0.160240,0.024433,-0.187257,0.140707,0.243708,0.035048,0.234337,0.168778,0.244440,-0.328948,0.013366,-0.635335,0.125646', '3811356', '5403927', '10174444', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26426026', '七十七天', '剧情', '电影《七十七天》是以探险作家杨柳松77天孤身穿越羌塘无人区的真实事迹为蓝本创作。电影中，在生活里迷失了自我的男主徘徊在雪域高原独闯无人区，影片女主身体残疾仍然乐观面对生活，她让他坚定了去尝试世人眼里无法完成的无人区奇幻探险之旅……两个非常状态下的真实人物，真诚、勇敢的面对命运选择挑战，不懈的追寻着内心最初的梦想与真正的自我...影片在节奏、画面、张力上会给观众强烈的视觉冲击，让观众跟随主人公经历一场无与伦比的探险之旅。', '江一燕', '赵汉唐', 6.4, 40602, 'tt7853798', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2503551480.jpg', 3.3, 16.1, 45.6, 25.6, 9.4, '-0.330653,0.118458,-0.620965,0.930807,0.419694,0.151035,0.716477,-0.106020,-0.490431,-0.046545,0.382059,0.727675,-0.194616,0.149731,0.510402,-0.214088,-0.270196,-0.466212,-0.320392,0.307117,-0.144276,-0.045133,-0.476966,-0.046024,-0.158088,-0.315151,1.096206,0.441214,-0.586585,0.453954,0.156820,0.213661,-0.212374,0.196802,0.041234,-0.235991,0.027007,0.081984,-0.544604,0.229642,0.017707,-0.277689,-0.245588,0.488634,-0.334316,-0.034526,0.891192,-0.435667,-0.282329,0.223549,0.563533,-0.330903,-0.407954,0.106648,-0.232448,0.051359,0.093771,0.220533,0.267979,0.328099,-0.415439,-0.167255,-1.015101,-0.260018,0.187692,0.072627,-0.405141,0.199634,0.202529,0.054439,0.269337,-0.274385,-0.046524,-0.158845,0.662713,0.522004,-0.254160,-0.024036,0.044694,0.412721,0.921529,0.214518,-0.461576,0.415407,-0.481922,-0.381727,-0.220462,-0.329876,-0.781137,0.158300,0.061380,0.254509,-0.392586,0.537727,-0.656034,0.245880,-0.180779,-0.502444,-0.145113,-0.431064,-0.080962,-0.744602,-0.442584,-0.183566,-0.078253,-0.153686,-0.202428,-0.726309,0.723384,-0.892187,0.187464,0.860960,-0.090706,-0.506544,0.752964,0.210436,-0.270844,-0.311806,0.181696,0.696755,-0.432594,0.402346,-0.270974,0.193949,-0.404684,0.165761,-0.775956,0.891181', '26759820', '26667010', '25880986', '30349667');
