INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26426194', '巨齿鲨', '动作', '一项由中国主导的国际科研项目，正在马里亚纳海沟深处进行时，遭遇未知生物攻击，科研人员被困海底。前美国海军陆战队深海潜水专家乔纳斯·泰勒受命前往营救，再度遭遇数年前曾经在深海给自己留下终身难以磨灭记忆的史前生物巨齿鲨。乔纳斯联手科研项目中的中国女科学家张苏茵成功营救了被困人员，但营救行动却意外造成了巨齿鲨逃离深海。当史前巨兽重返浅海，人类将为自己对大自然的贪婪付出惨重的代价......', '杰森·斯坦森', '乔·德特杜巴', 5.7, 205970, 'tt4779682', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2616427021.jpg', 4.8, 24.5, 54.6, 13.3, 2.7, '-0.302074,0.028303,-0.813455,0.595263,0.263563,0.037318,0.609355,-0.503578,-0.594250,-0.079569,0.299652,0.545209,0.436456,-0.229976,-0.056412,-0.135376,-0.278349,-0.226032,-0.279071,-0.022962,-0.429594,-0.261602,-0.617841,-0.175920,0.059977,-0.366116,0.975423,0.362494,-0.247820,0.394689,-0.237267,0.571096,-0.556401,0.548652,0.146475,-0.204686,0.297958,-0.041916,-0.282308,0.248740,-0.139948,-0.129965,0.132186,0.167106,-0.087152,0.153257,0.746031,-0.612892,-0.147122,-0.778327,0.038771,-0.706039,0.064300,0.186257,0.463181,0.211559,0.050316,0.111737,0.033907,0.085696,0.133617,-0.162643,-0.881457,-0.393420,-0.096366,0.056310,-0.388669,-0.092169,0.110681,0.477936,0.215099,-0.065198,-0.033795,0.275829,0.672216,-0.012360,-0.167319,0.330015,-0.127836,0.098242,0.893057,-0.522233,-0.274241,-0.231506,-0.203625,-0.745249,0.175404,-0.283721,-0.035199,0.154477,0.175051,0.381037,-0.576437,0.746648,-0.842483,0.112703,-0.626230,-0.444389,-0.260453,0.030203,-0.293110,-0.858253,-0.057142,-0.026238,-0.032847,0.048304,0.134653,-0.132221,0.561249,-0.448405,0.215875,0.820570,0.462101,-0.309821,0.851529,-0.299572,0.191364,-0.127313,0.155561,0.637195,-0.094829,0.520204,-0.240445,-0.174690,0.082441,0.011389,-0.269214,0.092755', '24879819', '25827286', '26290398', '1303910');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26429849', '残秽，不可以住的房间', '恐怖', '从少女轻小说到恐怖故事均有涉猎的女性作家（竹内结子 饰），在过去的半年里一直应邀为某杂志撰写短篇怪谈。她的故事均来自读者投稿的个人经历，其中有一位女孩的投稿让她卷入了难以想象的恐怖深渊。女孩（桥本爱 饰）曾租住一间公寓，但是经常会听到衣服摩擦榻榻米的声音。作家按图索骥前去调查，结果发现不仅女孩的房间，整栋公寓其他房间也曾有过离奇的事件。她和作家好友平冈芳明（佐佐木藏之介 饰）、灵异事件爱好者三泽彻夫（坂口健太郎 饰）以及丈夫直人（泷藤贤一 饰）不断追查，甚至跨越长达百年的历史，终于找到了这块土地上所发生的一系列恐怖事件的源头……本片根据《十二国记》的作者小野不由美的原作《残秽》改编。©豆瓣', '竹内结子', '中村义洋', 6.9, 12277, 'tt4842814', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2354077163.jpg', 1.7, 8.8, 43.6, 35.4, 10.5, '0.109710,-0.218384,-0.402633,0.523101,0.335837,-0.021847,0.666933,-0.018852,-0.439188,-0.469363,0.323904,0.619086,-0.503805,0.051271,0.317843,0.091198,-0.230542,-0.579994,-0.080407,-0.419097,-0.272591,-0.311477,-0.401302,-0.264672,0.049903,-0.203383,0.616858,0.116566,-0.349078,0.251151,0.071706,0.319285,-0.394955,0.269817,-0.019196,0.336751,0.058316,0.241699,-0.062493,-0.070695,-0.252857,-0.247672,-0.175671,-0.128243,-0.068571,0.196869,0.600954,-0.327941,-0.410025,0.211655,0.798613,0.292877,-0.211676,-0.020231,0.508715,0.247926,0.560008,0.468538,-0.092484,-0.110061,0.187054,-0.134928,-0.381528,-0.139225,0.280834,0.343001,-0.071496,0.165390,-0.212047,-0.090401,0.304431,-0.217127,-0.018365,0.040408,0.381949,0.328432,-0.123750,0.138833,-0.090215,0.455462,0.188279,0.158497,-0.036182,0.180000,-0.239439,-0.470427,-0.367027,-0.089607,-0.228158,0.296000,0.139120,0.052586,-0.127849,0.101650,-0.596318,-0.184629,0.154433,-0.277234,0.213441,-0.062218,-0.325762,-0.740055,-0.218700,-0.138958,-0.058602,-0.079851,0.273156,-0.265932,0.991425,-0.560059,0.185527,0.605313,0.122088,-0.139184,0.635850,-0.155766,-0.213919,0.098709,-0.105810,0.248294,0.027048,0.403341,-0.071846,0.534869,-0.083263,-0.462018,-0.444790,0.229697', '1322847', '25863940', '3811356', '27602116');
