INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26430636', '狂暴巨兽', '动作', '巨石强森饰演的灵长类动物学家一直与人类保持距离, 却跟极为聪明的银背大猩猩乔治有着深厚的感情。但是一次基因实验出错, 让这只温驯的大猩猩变成狂怒难驯的庞然巨兽。更可怕的是, 其他动物也发生了同样基因异变。他必须阻止这场全球性的灾难, 更重要是要拯救他的好友乔治。', '道恩·强森', '布拉德·佩顿', 6.3, 157492, 'tt2231461', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2516079193.jpg', 1.8, 13.3, 57.7, 22.4, 4.8, '0.047235,-0.342482,-0.659848,0.561145,-0.044206,0.117480,1.134240,-0.269007,-0.396307,-0.257341,0.162886,0.692045,-0.033080,-0.114956,-0.397855,-0.213994,0.125874,-0.250811,-0.017903,0.390213,-0.180330,-0.313956,-0.684212,-0.240596,0.072954,-0.422907,0.810113,-0.134105,-0.445870,0.365621,0.221370,0.296907,-0.012504,0.526087,-0.262301,-0.327175,-0.195553,0.093395,-0.110599,-0.101539,0.433156,0.243708,0.007858,0.396619,-0.167897,0.234186,0.281165,-0.662773,-0.628933,-0.270074,0.435920,-0.685792,-0.002459,0.090027,0.485568,-0.363364,0.018431,0.210175,0.222001,0.066779,0.157242,0.262577,-0.941858,0.081801,-0.087985,0.394407,-0.457060,0.414711,0.221607,0.111460,0.274654,-0.113219,0.027814,0.430985,0.296961,0.230404,-0.212046,-0.090622,-0.434988,-0.314653,0.945390,0.091082,-0.685072,0.343027,-0.639841,-1.006072,-0.228286,-0.754925,-0.199687,0.115258,0.178856,0.344425,-0.298761,0.481247,-0.795774,0.088130,-0.194080,-0.128538,-0.262799,-0.586002,-0.051270,-0.438092,-0.178688,-0.942276,-0.500345,0.003297,0.150857,-0.790386,0.803002,-0.840791,0.072877,0.603998,0.244362,-0.480429,0.515239,-0.024354,-0.027438,-0.218360,0.111871,0.263913,-0.036309,0.016107,-0.250495,0.363590,0.559470,-0.105223,-0.453176,0.737348', '25828589', '3005387', '26667010', '1291577');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26430669', '花牌情缘 下之句', '剧情', '历经了多少挫折和辛酸，成立才刚刚一年的都立瑞泽高中竞技花牌部终于有幸要走向全国大赛的会场。借此机缘，绫濑千早（广濑丝丝 饰）也与儿时的好友绵谷新（真剑佑 饰）完成了久违的会面。只不过由于作为精神支柱的爷爷的去世，绵谷似乎丧失了前进的勇气和目标，早已远离花牌赛场。为他的状态担忧的还有绵谷宿命的强敌——最强女王的若宫诗畅（松冈茉优 饰）。为了打败女王，千早独自展开练习，不知不觉中却与大江奏（上白石萌音 饰）、西田优征（矢本悠马 饰）、驹野勉（森永悠希 饰）、真岛太一（野村周平 饰）等伙伴疏远了距离。大赛在即，少男少女们即将度过一个刻骨铭心的夏天……本片根据末次由纪的同名漫画改编。©豆瓣', '广濑铃', '小泉德宏', 7.3, 11977, 'tt4802214', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2352420568.jpg', 0.5, 3.6, 38.5, 42.7, 14.7, '-0.089070,0.042915,-0.406974,0.541976,0.246345,-0.564927,0.459112,0.018017,-0.272037,-0.295878,0.300317,0.697741,-0.245819,0.213647,0.478336,-0.208146,-0.086198,-0.745592,-0.075212,-0.245270,-0.290092,-0.168229,-0.300760,0.125857,-0.171397,-0.248128,1.016954,0.111764,-0.099976,0.753655,0.341868,0.200284,-0.039380,0.282409,-0.017160,-0.052155,0.094420,0.341582,-0.316241,0.012925,-0.266211,-0.320817,-0.372735,0.113385,0.205381,0.209979,0.781025,-0.377679,-0.084026,-0.107975,0.258259,-0.151911,-0.060838,0.061680,0.306728,0.060242,0.154496,0.355330,-0.132153,0.162793,-0.190932,-0.178393,-0.682317,-0.018612,0.216002,0.033043,-0.286213,0.537608,-0.021646,-0.303966,0.232545,-0.167765,0.029343,0.480593,0.357454,0.326577,-0.510013,-0.009259,-0.059214,0.245415,0.565234,-0.031301,-0.094535,0.367675,-0.018268,-0.470883,-0.127931,-0.133898,-0.292700,0.053545,0.140797,0.094768,0.056963,0.143959,-0.759329,-0.080062,-0.121819,-0.191584,0.249107,-0.326349,0.102565,-0.668897,-0.095067,-0.398359,-0.177943,0.171320,0.266058,-0.263149,0.860782,-0.888287,0.261068,0.386561,0.058899,-0.105904,0.352896,0.179724,0.066979,-0.340872,0.019478,0.241926,-0.271757,0.478307,0.058634,0.439661,-0.153203,-0.169726,-0.474885,0.530809', '1826173', '3811356', '26365262', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26433966', '黑处有什么', '剧情', '故事发生在20世纪90年代初，曾经辉煌一时的中原飞机厂正显露笨重疲惫的姿态。在家属区大院居住的初中生曲靖（苏晓彤 饰），她的父亲曲志诚（郭笑 饰）是一个有些迂腐执拗的法医。曲法医虽然经常遭到妻子的奚落和周围人的嘲笑，却不改自己一根筋的办案作风。与之相对，曲法医的同事张树林（周逵 饰）作风粗犷，破案率极高，但难免出现屈打成招的情况。曲靖和张树林的女儿张雪（陆琦蔚 饰）交好，后者过于出挑张扬的作风让她遭到不少人的白眼。曲靖一次促狭的举动，使得张雪从所有人的面前凭空消失。而就在此之前，当地接连发生多起手段恶劣的强奸杀人案。每个人都形迹可疑，每一处阴冷黑暗所在都隐藏着无限杀机……©豆瓣', '苏晓彤', '王一淳', 6.6, 38476, 'tt5131124', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2387538436.jpg', 2.2, 10.8, 50, 31, 6.1, '0.313218,-0.225570,-0.757616,0.726376,-0.427814,-0.149980,1.048508,0.166132,-0.705083,-0.319078,0.330197,0.508865,-0.325353,0.208871,0.071690,-0.162476,0.039101,-0.454394,-0.296249,-0.126150,-0.109361,-0.461348,-0.167203,-0.183960,-0.004286,-0.160448,0.336772,0.137193,-0.518371,0.304958,0.318792,0.190266,-0.291050,0.675228,-0.225640,-0.166897,-0.291508,0.078673,0.091831,-0.406018,0.001954,-0.472589,-0.299610,0.104301,-0.185386,0.497239,0.714934,0.012955,-0.344936,0.018952,0.497758,-0.145030,-0.087481,0.090578,0.492995,-0.065461,0.153436,0.067821,-0.060113,-0.011111,-0.053393,0.053175,-0.465553,0.184382,0.084603,0.259353,-0.428920,0.448567,0.009914,0.161833,-0.110271,-0.322631,0.172566,-0.092375,0.276819,0.300189,-0.051012,-0.060427,-0.444290,-0.026268,0.484737,0.271989,-0.507973,0.084739,-0.452968,-0.398731,-0.224237,-0.033723,-0.573542,-0.036528,0.285101,-0.358815,-0.118223,0.327928,-0.473228,0.067842,0.000491,-0.022355,-0.028486,-0.260368,-0.305579,-0.594263,-0.106136,-0.642245,-0.430574,0.192706,0.039622,-0.165934,0.441469,-0.740111,0.014577,0.256707,-0.020581,-0.433721,0.478103,-0.104726,-0.137296,0.077789,-0.140987,0.262906,0.263095,0.233929,0.102445,0.470733,-0.312045,-0.170165,-0.133972,0.415330', '21348112', '1417428', '1309297', '1304862');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26437237', '瑞士军刀男', '剧情', '在一个荒无人烟的小岛上，不善于和人沟通的汉克（保罗·达诺 Paul Dano 饰）对人生早已绝望，于是他决定亲手了结自己的性命。就在关键时刻，一具尸体漂到沙滩上。该尸体（丹尼尔·雷德克里夫 Daniel Radcliffe 饰）臭屁连天，虽然苍白浮肿，却似乎有生命一般。汉克大喜过望，为这个不同寻常的朋友其名曼尼。更令他兴奋不已的是，曼尼就好像一把多功能的瑞士军刀，帮他解决了诸如生火、砍树、饮水等诸多现实问题。曼尼的出现为汉克打开新世界的大门，死神似乎就此遁去。失败者汉克拥抱着属于他的奇幻的世界。汉克与曼尼，这对古怪的朋友启程踏上一段不寻常的旅途……©豆瓣', '保罗·达诺', '关家永', 7.8, 100334, 'tt4034354', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2328680655.jpg', 1.1, 3.8, 25.1, 45.9, 24.1, '0.414905,0.099935,-0.616728,0.357910,-0.190471,-0.305682,0.899549,0.080695,-0.372456,-0.104491,0.314702,0.757492,-0.025097,-0.018135,0.132827,0.248759,-0.407219,-0.585739,-0.066306,-0.141424,-0.540557,-0.372246,-0.469728,-0.225181,-0.063342,-0.234217,0.586580,0.079164,0.011536,0.466949,0.150586,0.137917,0.020646,0.590385,-0.372329,-0.042909,-0.082898,0.091352,-0.105822,-0.070136,-0.039815,0.040341,-0.153018,0.241640,-0.174333,0.386647,0.469149,-0.106396,-0.205347,0.049520,-0.034523,-0.375698,0.207072,0.089709,0.074250,-0.222435,-0.130268,-0.000912,-0.203633,-0.065982,0.028021,0.063072,-0.906559,0.005160,-0.097904,0.356794,-0.567688,0.499286,-0.138385,-0.203493,0.011929,-0.395504,0.207899,0.225740,0.294670,0.391575,-0.018123,-0.051218,-0.396312,0.153540,0.519508,0.161999,-0.167971,0.452752,-0.200608,-0.316650,-0.254376,0.123794,-0.420986,-0.342388,0.394848,0.049223,-0.343076,0.155037,-0.649106,0.059920,-0.235690,-0.125272,-0.167925,-0.256234,-0.123095,-0.338747,0.077609,-0.153766,-0.339035,-0.036620,0.257239,-0.126532,0.612472,-0.541911,0.322819,0.363017,0.117814,-0.009753,0.575243,0.060708,0.078888,-0.421553,-0.102745,0.390885,0.222203,0.406885,0.097362,0.454051,0.229923,0.057871,-0.653029,0.733211', '35158375', '25828589', '1297996', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26440017', '启功', '剧情', '在老北京一条胡同里，住着不显山不露水的一代书画名家启功老人（马恩然 饰），他和老伴儿（王馥荔 饰）举案齐眉，相敬如宾，过着平凡安宁的生活。只是在怒涛涌动的时代，小人物无法在暴风雨中独善其身。启功拥有旗人血统，在文革浪潮汹涌澎湃的年代给他带来不少的麻烦。红卫兵们可以长驱直入他的家中搜查封资修的物品，所幸总有倾心传统文化的人暗中相助。运动之中，启功时常回忆起自己初学绘画的情景，与师友坐而论道的往事，和老伴儿相濡以沫的过往，这些都令他感慨唏嘘。饱受过屈辱，也历经荣光，许多事不知不觉便已看透，许多情结慢慢就学会放下，这一切都不自觉地流淌在老人的书画之中……©豆瓣', '马恩然', '丁荫楠', 7.7, 7386, 'tt5004908', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2266308272.jpg', 1, 3.4, 29, 45.4, 21.2, '0.278644,-0.103798,-0.717545,0.466779,-0.032999,-0.335849,0.836437,-0.073772,-0.757742,-0.318213,0.282272,0.705788,-0.095233,0.437129,-0.096657,-0.293738,-0.249701,-0.601245,0.021225,-0.250442,0.027317,-0.208239,-0.380275,0.003607,-0.303862,-0.299941,0.375723,0.187750,-0.205587,0.446974,-0.118182,0.151737,-0.229192,0.556143,-0.652949,0.123121,-0.191566,0.293124,-0.388067,-0.462332,-0.024626,-0.241618,-0.400266,0.164763,-0.085429,-0.049899,0.704479,-0.439756,-0.066500,0.099899,0.163605,0.024907,-0.053956,0.285182,0.174009,0.384775,0.240150,0.405359,-0.307596,0.293616,-0.142274,0.068866,-0.425814,-0.293804,0.197389,0.385487,-0.724918,0.582095,0.276100,-0.236121,-0.280367,-0.390464,0.172432,-0.011525,0.130217,0.616791,-0.265590,-0.106065,-0.590752,0.621891,0.630010,-0.000923,-0.440626,0.384807,-0.458470,-0.117054,-0.023157,-0.301875,-0.700955,-0.335205,0.194540,-0.057164,-0.161765,0.707606,-0.585669,0.344141,0.074775,-0.212777,-0.141035,-0.221305,-0.218180,-0.365267,-0.374762,-0.534196,-0.367132,0.074961,0.263851,-0.239250,0.875199,-0.616613,0.250712,0.370759,-0.003278,-0.205651,0.551799,0.196542,0.039151,-0.007432,-0.243803,0.336445,-0.212395,0.376719,0.064719,0.462699,-0.256839,-0.003864,-0.331452,0.671784', '26348103', '21619567', '30162520', '26677495');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26445216', '军舰岛', '剧情', '影片讲述日本殖民时期，400余名朝鲜难民受到强征来到日本军舰岛，试图逃离以免遭到杀害的故事。1945年，在战争即将结束谣言四起的动荡时期，京城半岛酒店爵士乐团团长李姜煜（黄政民饰）带着他的独生女素姬（金秀安饰）与乐团、称霸钟路的拳手崔七星（苏志燮饰）、在日本统治下受尽苦难的末子（李贞贤饰）等朝鲜人，被可以赚钱发财的谎言所蒙骗，奔赴日本，但是他们抵达的却是朝鲜人 被强行征用的军舰岛。在海底1000米深的矿坑里，他们忍受着瓦斯爆发的危险被迫劳动。李姜煜在军舰岛想尽一切办法保护自己的女儿，崔七星和末子也使用自己的方法熬过痛苦的日子。战争结束后，OSS（美国战略情报军）秘密指示朝鲜独立军要员朴武英（宋仲基饰）去解救潜伏在军舰岛的总统候选人尹学哲（李璟荣饰）。日本人为了掩饰在军舰岛上对朝鲜人犯下的所有罪行，决定将朝鲜人工作的矿坑进行爆破。在千钧一发的状况下，朴武英艰难的救出了尹学哲并表明了自己的身份。以朴武英、李姜煜、崔七星等为首的朝鲜人决心逃出军舰岛，隐约察觉到内情的矿场所长为了掩盖军舰岛所有的秘密而拼命追杀他们。', '黄政民', '柳昇完', 7.9, 70677, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2462745948.jpg', 0.4, 1.7, 24.3, 51, 22.7, '-0.135666,0.180159,-0.796390,0.608320,0.121235,0.284504,0.393395,0.020589,-0.433864,-0.106647,0.275885,0.510893,0.245097,0.024639,0.198685,-0.100447,-0.393122,-0.563211,-0.068146,-0.130873,-0.334467,-0.257820,-0.109101,-0.533564,-0.164043,-0.476825,0.671775,0.683853,-0.330213,0.208141,0.214285,0.411059,-0.174678,0.461002,-0.072757,-0.147339,0.090695,-0.284290,-0.364338,0.190713,-0.313275,-0.419499,-0.094582,0.282671,0.263349,0.414900,0.859718,-0.272670,0.169222,-0.076005,-0.240721,-0.567802,0.096999,0.163015,0.570887,-0.062082,-0.095155,0.355825,-0.403993,0.066935,0.083903,-0.069282,-0.571575,-0.229294,0.232267,-0.117459,-0.465229,0.141419,-0.190651,0.239427,-0.001846,-0.248774,0.276845,0.650625,0.112009,0.257391,-0.231575,0.247754,-0.719885,0.289944,0.803262,-0.312167,-0.181664,-0.208996,0.070299,-0.382175,-0.289552,-0.494452,-0.059106,-0.170609,0.461434,-0.363995,-0.210316,0.269125,-0.612602,-0.245233,-0.296859,-0.572886,0.115271,-0.329905,-0.060250,-0.708008,0.005765,-0.203554,-0.021329,0.256909,0.202574,0.219159,0.677040,-0.503100,0.256911,0.692723,0.362779,-0.719241,0.490661,0.108220,0.081742,-0.303125,-0.122977,0.342739,0.106535,0.569471,0.064683,0.100272,-0.130726,-0.174663,-0.238251,0.202118', '30299515', '2294565', '6007281', '35058077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26457368', '流浪巴黎', '喜剧', '故事发生在位于加拿大的一个小村庄中，菲奥娜（菲欧娜·戈登 Fiona Gordon 饰）是个一辈子都生活在这里的姑娘，同时也是镇上图书馆的管理员。一天，菲奥娜意外的收到了玛莎阿姨（埃玛妞·丽娃 Emmanuelle Riva 饰）的来信，这位九十多岁的年迈亲戚向菲奥娜发起了求助，如果菲奥娜不能够前往巴黎照顾她，那么无依无靠的她将会被送进老人之家。无奈之下，菲奥娜只得踏上了前往巴黎的旅途。在一场意外中，菲奥娜不慎落水，失去了所有的财务包括她的身份证明，更糟的是，当她抵达目的地时，却发现玛莎阿姨失踪了。在这座繁华但冰冷的大城市里无处可去的菲奥娜遇见了境遇和她差不多的流浪汉多姆（多米尼克·阿贝尔 Dominique Abel 饰）。©豆瓣', '菲奥娜·戈登', '多米尼克·阿贝尔', 7.7, 13598, 'tt2936884', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2428486031.jpg', 0.6, 3.2, 28.3, 47.8, 20.2, '0.493477,0.073069,-0.709296,0.308281,-0.107909,-0.253564,0.786971,-0.029391,-0.589569,-0.319288,0.112152,1.036628,-0.073957,0.547848,0.308184,0.235194,-0.290309,-0.424404,0.048403,-0.436014,-0.353355,-0.546767,-0.153219,-0.139415,-0.061572,-0.273340,0.217509,0.237426,-0.012913,0.516119,0.172727,0.225054,-0.148400,0.604416,-0.425563,0.252562,0.151998,-0.169895,0.017932,0.415836,0.110371,-0.116170,-0.073584,0.208418,0.354150,0.465228,0.690787,-0.135763,-0.101244,-0.017033,0.300871,-0.163711,0.101477,0.133948,0.326764,-0.174941,0.122131,0.097541,-0.420857,0.024764,0.187239,-0.150797,-0.415969,0.187394,0.177151,0.265926,-0.856958,0.389765,-0.022951,-0.234284,-0.027213,-0.500839,0.546949,0.402300,-0.012527,0.285749,-0.003625,0.035159,-0.583860,0.013633,0.838837,0.055478,-0.036150,0.308068,-0.193768,-0.402549,0.134265,-0.072204,-0.592324,0.202318,0.293600,-0.072268,-0.166145,0.184404,-0.562477,-0.131202,-0.448410,-0.281261,-0.200473,-0.258090,-0.273253,-0.526682,0.189295,-0.426373,-0.331794,0.148512,0.019085,-0.153704,0.453776,-0.796460,0.268734,0.362395,0.395176,-0.262486,0.710005,-0.019756,0.330610,0.095198,0.110913,0.397691,-0.000815,0.478335,0.155286,0.279844,-0.100461,-0.272550,-0.455686,0.463918', '1302384', '26678509', '1296538', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26469862', '樱桃小丸子：来自意大利的少年', '剧情', '来自英国、中国、美国等五个国家的六个孩子来到了小丸子（Tarako 配音）的家乡清水市。来自意大利的安德烈（中川大志 Taishi Nakagawa 配音）暂住在了小丸子的家里。小丸子他们和外国小朋友们一起在学校里上课，还利用周末一起前往大阪和京都去旅行。一开始，小丸子因安德烈太过热情而感到困扰，但是知道了他来日本的理由后便开始和他和睦相处了。他们俩一起去逛了庙会，并许下了“希望能再次见面”的愿望。然而，这些快乐的日子即将过去，他们将要迎来离别之时。', '鳕子', '高木淳', 7, 22971, 'tt5462882', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2383897820.jpg', 1.4, 6.3, 45.5, 34.6, 12.3, '0.517123,-0.026803,-0.969237,0.333859,0.019520,-0.594814,0.474165,0.226637,-0.431726,-0.053210,-0.417594,0.894935,-0.046097,0.717796,0.307833,-0.077751,-0.356560,-0.650869,0.001314,-0.407277,-0.321812,-0.266896,0.306161,-0.225038,-0.143776,0.145853,0.154483,0.042000,0.402807,1.091295,0.280808,0.011791,-0.251827,0.735002,-0.317038,-0.025418,0.156931,0.123971,-0.456874,0.362955,0.201103,-0.001778,-0.171897,0.321930,0.235935,0.066366,0.717003,0.197777,0.080902,-0.307809,0.048493,-0.133109,-0.063045,0.312110,0.410394,0.143282,0.419939,0.071766,-0.068354,0.139965,-0.030497,-0.240928,-0.397361,0.285889,-0.155755,0.014065,-0.546714,0.487067,0.317731,-0.188147,0.302685,-0.443094,0.538529,0.669965,0.320450,0.381217,-0.189280,-0.032384,-0.348556,0.221143,1.083096,-0.434760,0.068981,0.288730,0.026008,-0.258633,0.162671,0.138080,-0.275805,0.081752,0.031164,0.073617,-0.337236,-0.014050,-0.964003,0.194253,-0.235131,-0.325375,0.159874,-0.464618,0.247989,-0.924098,0.161821,-0.423397,-0.408387,0.257411,0.292806,0.024093,0.929170,-0.813120,0.209979,0.945573,0.640563,-0.597514,0.741370,0.280176,0.274648,-0.009404,0.205743,-0.001912,-0.219572,0.466731,0.053387,0.438781,-0.020370,-0.054436,-0.607448,0.453727', '35256235', '3147969', '1303333', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26474112', '基努猫', '喜剧', '故事讲述鲍伯刚和恋情长跑的女友分手，心碎不已时巧遇一只可爱到不行的流浪猫，而鲍伯好友克拉伦斯更被小猫萌翻，两人给小猫取名‘Keanu’，而‘百炼钢化为绕指柔’大男人从此化身猫奴，每天陪猫、爱猫，与猫为伍。某天鲍伯的家被流氓集团闯空门，更惨的是他们的爱猫‘Keanu’竟然被绑架！为了营救爱猫，两人决定混入贩卖毒品的圈子，为方便接近流氓集团......', '科甘-迈克尔·凯', '彼得·阿特西奥', 5.7, 5090, 'tt4139124', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2357023188.jpg', 6.3, 27.3, 48.5, 12.8, 5.2, '0.374992,-0.459340,-0.541211,0.293602,-0.154692,-0.279434,0.611940,0.217797,-0.356459,0.000943,0.002868,0.839206,-0.483923,0.360730,0.145810,-0.212252,0.306897,-0.677441,-0.177430,0.019544,0.183017,-0.169588,0.197572,-0.066383,0.041036,-0.108161,0.545780,-0.105310,-0.062060,0.607878,0.482608,0.250780,-0.361126,0.153359,-0.291439,0.076355,-0.016567,0.243551,0.058569,0.195278,-0.187297,0.244597,0.126423,-0.006582,-0.410479,-0.109752,0.787622,-0.499815,-0.209980,-0.558945,0.433631,-0.519182,-0.129985,0.139594,0.380448,0.034357,0.671490,-0.250006,-0.124066,0.039570,0.312459,-0.067451,-0.546954,0.227697,0.085351,-0.015839,-0.461067,0.183179,-0.079953,0.149709,0.665437,-0.269751,0.098231,0.247340,0.396536,0.444995,-0.011800,0.147555,-0.593981,-0.021194,0.653405,-0.170812,-0.111604,0.364805,0.083726,-0.024226,0.315838,-0.319358,-0.054400,-0.169961,0.240490,-0.237879,-0.509012,0.388164,-0.812729,-0.307116,-0.443018,0.161112,-0.158121,-0.480101,-0.285764,-0.278962,-0.018691,-0.224844,0.107896,0.399327,0.292990,-0.348210,0.472208,-0.912662,0.346870,0.674049,0.275220,-0.567102,0.625254,-0.009897,-0.072115,-0.384814,0.157007,0.177596,0.461333,-0.031224,0.461753,0.043441,-0.213177,-0.050425,-0.760744,0.249457', '30345227', '1309194', '27191431', '3044878');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26527575', '风风风', '喜剧', '该片翻拍自捷克电影《有希望的男人》。充满热情斗志的济州岛冒险家锡根（李圣旻 饰），外遇经历20年却从未被抓包过，有著风流之神的传说封号。渴望成为顶级大厨的奉秀（申河均 饰）与锡根的妹妹美英（宋智孝 饰）结婚多年，经营着一间意大利餐厅，过着平凡无奇的生活。然而，一名性感神祕女子珍妮（李伊 饰）的出现，即将吹 乱了这一池春水，她将带领奉秀进入「晚风」的世界，「妻管严」的奉秀将就此陷入外遇风暴？！全片于以风多著称的济州岛拍摄完成。', '申河均', '李炳宪', 6.2, 6405, 'tt8108278', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2515589861.jpg', 3.4, 17, 52.1, 19.4, 8.2, '0.142444,0.322407,-0.520208,0.496964,-0.035083,-0.215736,0.581141,0.241528,-0.358282,-0.282125,0.363971,0.624228,-0.271820,0.132319,0.506525,0.080903,0.097957,-0.678781,-0.164179,0.134788,0.123353,0.120481,-0.433812,0.054141,-0.107975,-0.477845,0.755043,0.124542,-0.143364,0.261091,0.304775,0.185436,-0.043236,0.094380,-0.218597,-0.101783,0.097751,0.192598,-0.548562,0.343426,-0.317655,-0.278363,-0.047653,-0.093280,-0.245582,-0.019292,0.736569,-0.189695,0.100391,-0.082334,0.599449,-0.141173,-0.337867,0.032198,0.235544,0.197240,-0.071015,0.217126,-0.114273,-0.092451,0.196056,-0.271680,-0.652688,0.146404,0.127627,0.105579,-0.279320,0.333356,-0.229637,-0.144276,-0.062586,-0.195048,0.153776,0.024721,0.271714,0.439100,-0.105519,0.261795,-0.336463,0.551054,0.565877,-0.097253,-0.310584,0.156498,-0.353915,-0.435212,0.081664,-0.431782,-0.578568,-0.020067,0.133234,-0.119468,-0.159207,0.102208,-0.675647,0.037900,-0.124992,-0.138259,0.081044,-0.174254,-0.316923,-0.531539,-0.257059,-0.381143,-0.306221,-0.071507,-0.007980,-0.072305,0.521647,-0.666156,0.443950,0.361190,0.194914,-0.307021,0.774306,-0.045190,-0.053453,-0.162921,-0.019768,0.590899,-0.185081,0.102948,0.114936,0.381236,-0.332473,-0.102707,-0.098499,0.375582', '26647163', '26759820', '6843843', '1322847');
