INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26528871', '好时光', '剧情', '一起以灾难收场的抢劫案后，劫犯康斯坦丁成功逃走，但他的弟弟尼克却被捕。为了能让自己的弟弟离开监狱，康斯坦丁尝试了去筹集足够的保释金，但他还有另外一个选择，那就是帮助尼克越狱。穷途末路的康斯坦丁别无他法，在纽约的地下世界中，等待着他的只有危机四伏的挑战。一个惊心动魄的漫漫长夜就此拉开序幕，为了拯救自己与尼克，康斯坦丁唯有与时间赛跑，而他也意识到，他和尼克的生命就像是处于平衡木的两端，无法一起全身而退。', '罗伯特·帕丁森', '本·萨弗迪', 7.3, 14838, 'tt4846232', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2499831788.jpg', 1, 5.4, 34.9, 44.9, 13.9, '0.187022,0.246322,-0.797526,0.588767,-0.303745,-0.424662,0.940215,0.034694,-0.480508,0.018176,0.317554,0.895621,0.222204,0.297000,0.212455,0.008270,-0.412501,-0.760731,-0.061999,-0.071830,-0.575867,-0.721478,-0.297779,-0.200256,-0.133211,0.012375,0.944845,0.263452,-0.037322,0.444739,0.196518,0.193113,0.063192,0.776315,-0.252028,-0.107592,-0.070095,-0.130040,-0.430740,0.530331,0.344476,-0.171284,-0.221017,0.508341,0.011434,0.281127,0.601459,-0.396011,0.161969,-0.054658,0.198160,-0.555176,-0.185405,0.225939,-0.035083,-0.264590,0.138484,0.218869,-0.218615,-0.021029,0.186652,0.035975,-1.145046,0.113424,-0.211100,0.212548,-0.589947,0.237894,0.055586,-0.081020,0.379406,-0.247249,0.207900,0.642712,0.361623,0.269385,-0.642630,-0.240012,-0.877470,-0.052195,0.850890,-0.212784,-0.276362,0.278525,-0.072556,-0.495628,-0.179572,-0.552830,-0.280529,-0.204925,0.237295,0.216299,-0.469172,0.004208,-0.484561,0.103705,-0.495218,-0.237853,-0.274310,-0.612696,0.063528,-0.616646,-0.040790,-0.266863,-0.489901,0.197321,0.112192,-0.575950,0.504251,-0.762618,0.106296,0.944694,0.588385,-0.316342,0.897732,0.316615,0.270790,-0.129192,0.073169,0.394888,-0.171823,0.533699,0.229012,0.183552,0.209206,0.176275,-0.540894,0.682621', '1949005', '1793491', '25828589', '1299628');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26546802', '告白实行委员会：从很久以前就喜欢你了', '爱情', '故事发生在一座平凡小镇。樱丘高中三年级学生榎本夏树（户松遥 配音）一直喜欢从小一起长大的好友濑户口优（神谷浩史 配音），虽然两人相处融洽，可是她一直不能鼓起勇气向对方告白。为此夏树常常以优为目标，反复进行告白练习。就在这个关口，优接到了同学绫濑恋雪（代永翼 配音）的约会邀请。危机当前，夏树能否成功完成爱情告白吗？本片是根据视频网站上用户HoneyWorks创作的乐曲改编的动画第一弹。©豆瓣', '神谷浩史', '柳泽哲也', 7.7, 5561, 'tt5889338', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2398431837.jpg', 0.5, 3.7, 29.1, 41.3, 25.3, '0.162163,-0.103073,-0.410702,0.633812,0.359334,-0.156059,-0.029438,-0.044643,-0.172094,-0.328621,-0.106477,0.347816,-0.610696,0.474043,0.332482,-0.037185,-0.275855,-0.763309,0.128377,0.001797,-0.041261,-0.338583,0.236655,-0.127984,-0.096774,-0.142295,0.927719,-0.098951,-0.282412,0.204041,0.299471,0.022625,-0.327935,0.100104,0.041064,-0.033182,0.245949,0.122202,-0.263566,0.298129,-0.258410,-0.210214,-0.204297,-0.227833,0.430972,0.092263,0.807998,0.053927,-0.353745,0.276977,0.728588,-0.078531,0.030247,-0.169497,0.479338,0.057887,0.390708,0.061878,0.010293,0.132705,-0.411141,-0.383358,-0.348162,-0.175217,-0.090542,0.079278,0.015643,0.437686,-0.046126,0.107332,0.175713,-0.147849,-0.166739,0.408190,0.685345,0.103450,-0.532130,0.239818,0.228314,0.295215,0.671741,0.236360,-0.239515,0.464916,-0.102736,-0.372378,-0.175043,0.090439,-0.425716,0.268805,0.091781,-0.010956,-0.146550,-0.042799,-0.235788,-0.265462,0.096083,-0.181974,0.532738,-0.537856,-0.063562,-0.960961,0.000597,-0.353582,-0.330365,-0.308741,-0.001620,-0.527484,0.954086,-0.936765,0.032229,0.634301,0.140224,-0.065233,0.437774,0.405610,-0.264738,-0.289755,0.028104,0.242414,-0.107983,0.230954,0.147915,0.209122,0.181256,0.035722,-0.666022,0.273043', '5403927', '2369613', '1316589', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26550176', '欢乐时光', '剧情', '阿明（田中幸惠 饰）、樱子（菊池叶月 饰）、芙美（三原麻衣子 饰）和纯（川村莉拉 饰）是非常好的朋友，一有空，四人便会结伴出游，彼此之间友情十分坚实。阿明是一名护士，至今未婚，虽然身边并不缺乏追求者，但她似乎还没有做好准备走进一段稳定的关系之中。樱子是一名家庭主妇，和婆婆 一起生活，儿子进入青春期，身体和心理上的变化令她有些措手不及，忙碌的丈夫又总是缺席孩子的教育问题。芙美和身为艺术家的丈夫即是恋人又是工作伙伴，两人虽然生活和工作都在一起，彼此之间却又一种无法言喻的疏离感。纯正在和丈夫打一场离婚的官司，这段失败的婚姻里，纯是过错方，但丈夫显然并不愿意放弃他们的婚姻。©豆瓣', '田中幸惠', '滨口龙介', 8.6, 10557, 'tt4780662', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2298735591.jpg', 0.4, 1.3, 11.2, 41, 46.1, '0.267555,-0.332009,-0.515957,0.553058,-0.121414,-0.375869,0.869855,0.048126,-0.672242,-0.559338,0.009223,0.799156,-0.072621,0.422602,0.209323,-0.005867,-0.170030,-0.701002,-0.039096,0.123039,-0.330136,-0.453068,-0.161698,-0.149860,-0.543479,-0.139886,0.853357,-0.120005,-0.198875,0.643090,0.261792,0.091468,-0.075547,0.704553,-0.002876,-0.096555,-0.232847,0.295583,-0.441580,-0.091289,0.228902,-0.084035,-0.100741,0.345232,0.378204,0.470892,0.455321,-0.086751,-0.107854,-0.084277,0.113562,-0.088690,-0.251468,0.232840,0.341417,-0.087417,0.533555,0.465132,-0.114703,-0.007046,0.066362,-0.076456,-0.492753,0.053572,0.231882,0.223815,-0.549516,0.574075,0.029531,-0.264401,0.065386,-0.342452,0.067643,0.326410,0.213592,0.651651,-0.383449,0.035755,-0.333791,0.138018,0.905870,0.227139,-0.018904,0.434570,-0.706917,-0.518225,-0.169354,-0.074615,-0.543767,-0.175403,-0.156677,0.320352,-0.103022,0.121890,-0.496729,0.269195,-0.091774,0.165674,-0.036867,-0.692333,0.399628,-0.523407,-0.064433,-0.928466,-0.659950,0.274467,0.228226,-0.239515,0.629490,-1.093991,-0.004832,0.263871,0.479589,-0.453372,0.610709,0.696667,0.180415,-0.461966,-0.043853,0.104566,-0.403414,-0.138096,0.117790,0.404589,-0.056009,0.107232,-0.260087,0.350413', '35030151', '25721544', '1308755', '21766698');
