INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26575103', '捉妖记2', '喜剧', '上一集与胡巴分别后，天荫（井柏然 饰）带着小岚（白百何 饰）踏上寻父之路，在义薄云天的天师堂堂主云大哥（杨祐宁 饰）的帮助下，二人得知天荫父亲宋戴天的护妖轨迹；而重回永宁村的胡巴再度被妖王追杀，颠沛流离逃亡时结识大赌徒屠四谷（梁朝伟 饰）和一只妖怪，三人一起过着相依为命的生活，但又因屠四谷欠下的巨额赌债横生诸多波折。与此同时 ，江湖盛传小妖王胡巴的重金悬赏令，妖界大军、天师精英、绿林草莽闻风而动，多方势力为抢夺胡巴在清水镇掀起腥风血雨。千钧一发之际，念子心切的天荫和小岚通过天师堂找到胡巴并一起逃离险境。岂料，一场更大的惊天阴谋尾随而至，伺机而动……', '梁朝伟', '许诚毅', 4.9, 344322, 'tt6170484', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2509643816.jpg', 14.7, 37.8, 37.6, 7.5, 2.4, '0.122005,0.055823,-0.497073,0.529080,0.475145,-0.156885,0.482357,0.260291,-0.668943,-0.066689,0.382324,0.548019,-0.101053,0.062074,0.302921,-0.276174,0.033637,-0.579862,-0.220408,-0.114476,-0.030981,-0.005162,-0.345476,0.276628,-0.323742,-0.363601,0.716154,0.313839,-0.034711,0.930961,0.357013,0.302466,-0.856911,0.190216,-0.201225,0.126253,-0.108675,0.378961,-0.535627,0.309266,-0.214909,-0.364277,-0.162794,-0.079931,-0.163063,0.212775,0.589872,-0.399981,0.200554,-0.149019,-0.005913,-0.226342,-0.047118,-0.003425,0.455919,0.093213,0.369902,0.396222,-0.259449,-0.003255,0.014071,-0.110803,-0.385522,-0.012123,0.271063,0.061396,-0.673077,0.228141,0.123383,-0.016480,0.106307,-0.229073,0.104730,0.649013,0.175047,0.047645,-0.212312,-0.001957,-0.549930,0.033850,0.775703,-0.221989,0.412850,-0.150129,0.400638,-0.167120,0.110699,-0.364214,-0.375116,-0.055559,0.286138,-0.105535,-0.019220,0.463201,-0.549910,0.147499,-0.463171,0.164755,0.028139,-0.108842,-0.174801,-0.642983,-0.133854,-0.035585,0.060634,0.169573,0.323714,-0.135515,0.627488,-0.684126,0.278538,0.424476,0.308248,-0.330967,0.476918,-0.166359,0.230067,-0.172242,-0.341707,-0.078402,0.347992,0.477615,0.221309,-0.118993,-0.385615,-0.163202,-0.119185,-0.078897', '35030151', '35256235', '26365262', '1451563');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26577180', '叛狱无间', '动作', '金来元饰演的刑警因为弟弟被犯罪团伙所害，为了查清事件真相，以囚犯身份进入监狱，接近在监狱里称王称霸的人物。而韩石圭饰演的监狱霸主因为和政府高层有着某种交易，在监狱里也能一手遮天。', '韩石圭', '罗贤', 6.9, 8558, 'tt6589464', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2425038734.jpg', 1, 6.8, 49.8, 31.5, 10.9, '0.319285,0.029037,-0.617213,0.776788,-0.178147,0.354337,0.947724,0.164750,-0.969898,-0.580068,0.219439,0.816428,0.050872,0.293713,0.158045,-0.392567,-0.295754,-0.475093,-0.656827,-0.773198,-0.252635,-0.649999,-0.399302,-0.230843,0.122581,-0.143458,1.194021,0.405513,-0.415712,-0.052075,0.457604,0.539493,-0.779261,0.176681,-0.044362,-0.509821,0.257456,0.072260,-0.510083,0.345018,-0.013520,-0.280720,0.341928,-0.081862,0.301623,0.212481,0.351876,-0.377918,-0.079695,-0.166969,0.192352,-0.659695,-0.357247,0.113116,0.605226,-0.290384,0.318862,0.725463,-0.073553,0.160281,0.053423,-0.516307,-1.105452,-0.361232,0.350483,-0.005992,-0.356961,0.135457,0.196220,0.117535,0.155235,0.147843,0.623762,0.350690,0.131498,0.502830,-0.206552,0.150836,-1.104876,0.286101,0.601089,-0.273197,0.022210,-0.322376,-0.001570,-0.736291,-0.264891,-0.717765,-0.341701,0.030675,0.103744,-0.348579,-0.272647,0.332406,-0.029898,-0.212587,-0.064688,-0.116606,0.061088,-0.421657,-0.066685,-0.467180,-0.242550,-0.098871,0.037330,0.066609,0.007706,-0.448754,0.201621,-1.242085,0.169768,0.651162,0.518897,-0.821503,0.818810,0.091473,0.294262,-0.497060,-0.252772,0.212640,0.829295,0.536128,-0.013105,-0.038601,-0.630155,-0.624319,-0.530042,-0.117260', '1793491', '26834930', '34968329', '1297689');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26577354', '表情奇幻冒险', '喜剧', '由艾里克·西格尔（Eric Siegel）和安东尼·莱昂迪斯（Anthony Leondis）创作剧本，后者还将导演这部电影。根据介绍，《Emoji大电影》有些像《头脑特工队》和《无敌破坏王》，讲述的是一群表情包在你的手机里的冒险。这群表情包住在“Emoji山谷”里，他们的世界通过手机桌面与其他App的世界相连。据悉，索尼已经与很多家知名的App达成协议，将会在电影中用到他们的App，其中包括音乐应用Spotify。', 'T·J·米勒', '安东尼·莱昂迪斯', 5.2, 8510, 'tt4877122', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2473065458.jpg', 13.5, 32, 39.8, 10.7, 4, '0.181203,0.211212,-0.701346,0.670238,0.042379,0.016719,0.705254,-0.012983,-0.197833,-0.261038,-0.296830,0.962426,-0.163589,0.335169,0.110859,-0.246110,-0.562472,-0.907563,-0.563649,-0.106510,-0.080159,-0.397280,-0.498005,-0.273107,0.018321,-0.501274,0.742780,0.022425,-0.807391,0.157821,0.300629,-0.062548,-0.341219,0.109228,-0.122329,0.094265,-0.136842,-0.127560,-0.307308,0.121998,0.130340,0.209270,-0.219507,0.147627,0.322419,0.336702,0.838447,-0.405095,-0.113294,0.134663,0.409778,-0.169671,-0.132068,-0.249130,0.129359,0.225718,0.323947,0.338856,-0.116048,0.245360,-0.085432,-0.164047,-1.183170,-0.145507,0.113299,0.352527,-0.314469,0.116657,-0.088059,-0.100273,0.099528,-0.377300,0.397070,0.203657,0.419264,0.637316,-0.003394,-0.141643,-0.374476,0.201527,0.201420,0.247251,-0.259886,0.273281,-0.083406,-0.338712,-0.581968,0.169520,-0.479117,0.031981,0.495498,-0.228419,0.000038,0.288411,-0.697218,0.078398,0.077765,-0.552317,0.176985,-0.613822,0.126494,-1.245416,-0.265677,-0.419755,-0.096166,-0.257746,0.282602,-0.258363,0.835519,-0.546646,-0.078150,0.115744,0.140012,-0.173877,0.665602,0.115774,0.010533,-0.091329,-0.001421,-0.058126,0.325802,0.236587,0.170888,0.564906,0.105059,-0.186264,-0.665660,0.532479', '3318306', '25928048', '3597344', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26577541', '终极斗士4', '动作', '犯人战士尤里•伯伊卡（斯科特阿金斯 饰）霸气回归!依然要参加格斗赛!然而这一部里，当他把对手解决掉后，对手意外死亡，这也让他重新审视自己参赛的意义，尤其发现遗孀被幕后黑手控制，他要为她的自由而战!不过这次的对手更难对付了!', '斯科特·阿金斯', '托多尔·查卡诺威', 7.2, 11623, 'tt3344680', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2405730763.jpg', 1.2, 6.6, 40.9, 34, 17.3, '0.256689,0.108635,-0.526850,0.558265,-0.205636,-0.371154,0.494537,-0.146288,-0.275879,-0.528462,0.096708,0.795462,0.106826,-0.105670,0.173854,-0.170484,-0.175290,-0.589716,0.072400,-0.044111,-0.330507,-0.344174,-0.442046,-0.336210,-0.017484,-0.045579,0.519194,0.124362,-0.113224,0.387155,0.464037,0.206518,0.540596,0.434923,0.206067,-0.372191,0.019167,-0.189999,0.026571,0.672398,0.240940,-0.092607,0.014755,0.818863,0.126175,0.361657,0.762164,-0.416688,0.225060,-0.238109,-0.038303,-0.619262,0.113254,0.451563,0.139069,-0.038105,-0.243406,0.182470,0.098944,-0.019839,0.174496,-0.215900,-1.204573,0.054117,0.142221,-0.129705,-0.474376,0.367669,-0.058431,0.438605,-0.186760,0.325365,0.342399,0.459165,0.681698,-0.053401,-0.113701,-0.300102,-0.246458,0.114031,0.707658,-0.417567,-0.333604,0.160965,-0.055881,-0.689097,0.240687,-0.810374,-0.229372,0.203440,0.422239,0.488125,-0.033453,-0.096728,-0.418716,-0.182403,-0.358532,0.137134,-0.689933,-0.447488,0.331299,-0.339011,-0.144623,0.004169,-0.298353,0.138668,-0.103409,-0.524020,0.349002,-0.719204,-0.107258,0.744643,0.431734,-0.291775,0.361373,0.008303,0.240924,-0.196910,-0.274816,0.178545,0.326877,0.357876,0.120624,0.218391,0.082590,-0.282279,-0.093090,0.583750', '1293605', '1793491', '27073234', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26578144', '他们先杀了我父亲：一个柬埔寨女儿的回忆录', '剧情', '安吉丽娜·朱莉通过Netflix宣布，她将执导该公司出品的全新电影作品《First They Killed My Father》。影片聚焦红色高棉政权时期的柬埔寨，其养子马多克斯将出演。影片改编自柬埔寨裔美国女性作家Loung Ung的回忆录《First They Killed My Father: A Daugher of Cambodia Remembers》，讲述了她在柬埔寨红色高棉统治时期的悲惨求生经历。Loung Ung出生于1970年的柬埔寨，5年后，红色高棉（即柬埔寨民主党）成为执政党，建立民主柬埔寨政权，并于随后在柬埔寨展开了近四年的管制时期。在此期间，约有两百万柬埔寨人因为政治迫害、饥荒、劳役、疾病等原因非正常死亡。在这场劫难中Loung Ung的家庭破碎，成为孤儿的她被训练为童子军，而她的兄弟姐妹则被送去劳改营。', 'Sareum Srey Moch', '安吉丽娜·朱莉', 7.6, 7787, 'tt4882376', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2494939843.jpg', 1.1, 4.3, 30.2, 44.2, 20.3, '0.045390,0.119207,-0.525719,0.500568,0.238900,-0.115996,0.432283,0.021002,-0.422241,-0.235595,0.149531,0.791627,0.057708,-0.177109,0.387365,-0.180445,-0.228762,-0.891399,-0.284521,-0.013040,-0.253424,-0.214692,-0.167398,-0.225070,-0.429974,-0.521692,0.847575,0.062830,-0.358042,0.135638,0.208987,0.408800,-0.038280,0.085707,0.089697,-0.144635,0.137536,-0.223274,-0.747594,0.409126,-0.070532,-0.584156,-0.169608,0.060333,-0.065124,0.285539,0.757881,-0.349198,0.218002,-0.413628,0.697842,-0.405906,-0.601333,0.049120,0.333483,0.429288,0.091264,0.381091,-0.074339,0.071122,-0.057434,-0.272351,-0.560602,-0.096980,0.092906,0.131696,-0.434589,0.803368,-0.111780,0.001059,-0.005685,-0.301453,0.225192,0.837890,0.194761,0.488479,-0.081618,0.133982,-0.391666,0.529790,0.664769,-0.193875,-0.494757,0.036944,-0.336118,-0.741047,0.097204,-0.476269,-0.181305,0.045192,0.229466,-0.141056,-0.312539,0.620214,-0.806321,-0.147575,-0.252088,-0.626421,0.212603,-0.225010,-0.019433,-0.452894,-0.378311,-0.237389,-0.006952,-0.235024,0.170283,-0.286261,0.792974,-0.594064,0.355116,0.515900,0.525387,-0.529476,0.500111,0.105492,0.095929,-0.077811,0.173274,0.681587,-0.022973,0.270292,-0.021119,-0.082359,-0.060913,-0.237965,0.009755,0.565204', '1780122', '1849026', '1478066', '27040921');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26580108', '所有明亮的地方', '剧情', '西奥多（贾斯提斯·史密斯 Justice Smith 饰）是一位非常忧伤的年轻人，脑子里整天都徘徊着自我了断的糊涂念头，也有几次，西奥多试图将自杀的想法转变成为现实，但每到这个节骨眼上，总会发生一些事情阻碍西奥多踏进另一个世界的步伐。维奥莱特（艾丽·范宁 Elle Fanning 饰）的姐姐去世了，和姐姐感情十分要好的维奥莱特陷入了痛苦和抑郁之中。正在念书的她迫不及待的期盼着毕业季的到来，如此一来，她就可以彻底逃离令她感到窒息的印第安纳小镇，逃离姐姐的死带给她的阴影。这样的两个年轻人，一次偶然之中，他们在钟楼上相遇了。西奥多发现，这个可爱率真的女孩能够令自己卸下假面和心房，维奥莱特亦觉得，和西奥多在一起的每分每秒，时间不再那么令她感到难熬。©豆瓣', '艾丽·范宁', '布雷特·海利', 7.1, 6495, 'tt3907584', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2577021302.jpg', 1, 7.4, 42.1, 32.3, 17.3, '0.305815,0.136220,-0.876621,0.505491,-0.036276,-0.341665,0.934896,0.166610,-0.757188,-0.355381,-0.061981,0.739472,-0.413013,0.531631,0.459433,0.105026,-0.174770,-0.625774,0.029894,-0.203243,-0.216210,-0.502360,-0.279121,-0.281389,-0.206224,-0.420612,0.491005,0.149829,0.078607,0.481628,0.278891,0.331903,0.233639,0.747873,-0.279228,0.001249,0.050047,-0.118606,-0.066856,0.082027,0.400775,-0.121523,0.004520,0.319501,-0.155433,0.020767,0.695797,-0.198534,-0.099295,0.092342,0.275760,-0.293208,-0.028720,0.153947,0.036204,-0.171017,0.072259,-0.002470,-0.296401,0.079583,0.247473,0.035264,-0.525109,0.181162,0.054373,0.298094,-0.728379,0.170908,-0.112917,0.020574,0.215656,-0.463237,0.107365,0.364388,0.439544,0.398920,-0.504969,-0.127058,-0.562150,-0.231097,0.827098,-0.033096,-0.375069,0.206851,-0.268211,-0.289818,-0.191217,-0.065756,-0.559687,0.000320,0.149208,0.140176,-0.296864,0.561473,-0.525971,-0.034566,-0.394114,-0.155207,-0.244364,-0.523400,-0.068456,-0.294692,-0.179783,-0.213070,-0.599749,0.050236,-0.112654,-0.280611,0.520335,-0.782841,0.376244,0.428064,0.393385,-0.139622,0.597978,0.279438,0.123353,-0.191082,0.040505,0.496544,-0.214424,0.111140,0.091195,0.497858,-0.118340,-0.089447,-0.574492,0.832086', '26245360', '1292211', '25723780', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26580232', '看不见的客人', '剧情', '艾德里安（马里奥·卡萨斯 Mario Casas 饰）经营着一间科技公司，事业蒸蒸日上，家中有美丽贤惠的妻子和活泼可爱的女儿，事业家庭双丰收的他是旁人羡慕的对象。然而，野心勃勃的艾德里安并未珍惜眼前来之不易的生活，一直以来，他和一位名叫劳拉（芭芭拉·蓝妮 Bárbara Lennie 饰）的女摄影师保持着肉体关系。某日幽会过后，两人驱车离开别墅，却在路上发生了车祸，为了掩盖事件的真相，两人决定将在车祸中死去的青年丹尼尔联同他的车一起沉入湖底。之后，劳拉遇见了一位善良的老人，老人将劳拉坏掉的车拉回家中修理，然而，令劳拉没有想到的是，这位老人，竟然就是丹尼尔的父亲。©豆瓣', '马里奥·卡萨斯', '奥里奥尔·保罗', 8.8, 1166874, 'tt4857264', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2498971355.jpg', 0.1, 0.5, 9.2, 41.7, 48.5, '0.202534,-0.019379,-0.743877,0.494245,-0.176304,-0.582130,0.985320,0.176484,-0.414231,-0.480700,0.172502,0.699286,-0.173468,0.553539,0.449709,0.167303,-0.289474,-0.635054,-0.195051,0.029171,-0.114129,-0.440486,-0.247968,-0.214899,-0.198381,-0.278602,0.514953,0.107113,0.047029,0.391308,0.333104,0.305973,-0.192292,0.569876,-0.147680,0.137787,0.147242,0.048455,-0.373194,0.182522,0.198062,-0.169936,-0.060909,0.134666,0.190315,0.178081,0.675045,-0.078117,-0.101963,-0.172207,0.275801,-0.007196,0.133058,0.021777,0.360599,-0.052052,0.149519,0.189081,-0.342360,-0.315852,0.382121,-0.186765,-0.376005,-0.093742,0.292199,0.060155,-0.773050,0.386788,-0.017657,-0.162227,0.093579,-0.435224,0.346335,0.418753,0.439178,0.466459,0.037947,0.312787,-0.502264,0.133415,0.740716,0.037015,-0.213900,0.490395,-0.358531,-0.378714,-0.061293,-0.072468,-0.807373,-0.091092,0.310342,-0.032475,-0.100369,0.214670,-0.268860,-0.107813,-0.429057,-0.051168,-0.040518,-0.251887,-0.146499,-0.643949,-0.100672,-0.506034,-0.451770,0.019306,-0.232498,-0.315702,0.636862,-0.902164,0.172948,0.359540,0.315395,-0.426705,0.827595,-0.023420,0.276538,-0.273198,-0.085058,0.356257,0.054803,-0.000672,-0.077352,0.213158,-0.199889,0.053497,-0.304718,0.492115', '1302384', '4275444', '1308755', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26580936', '午夜阳光', '剧情', '凯蒂（贝拉·索恩 Bella Thorne 饰）自幼便患上了罕见的着色性干皮症，对于常人来说非常普通的紫外线，照在凯蒂的身上将会对她造成致命创伤。无奈之中，凯蒂只能在白天太阳还没落山的时候待在家中，靠着一把吉他弹奏谱曲为乐，但是一旦夜晚降临，凯蒂的时间就开始了，带着她心爱的吉他，凯蒂来到火车站，站在路边上自弹自唱。一天，一位名叫查理（帕特里克·施瓦辛格 Patrick Schwarzenegger 饰）的男子被凯蒂的歌声所吸引驻足观看，开朗活泼的凯蒂令他坠入了情网。让凯蒂没有想到的是，查理竟然是自己曾经暗恋过的人，为了能够抓住这段感情，凯蒂决定隐瞒自己的病情。©豆瓣', '贝拉·索恩', '斯科特·斯皮尔', 7.5, 7826, 'tt4799066', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2506115971.jpg', 1, 5.3, 33.8, 36.9, 23, '0.268564,0.110841,-0.796305,0.514830,-0.351077,-0.062424,1.014299,0.181118,-0.541715,-0.227203,0.331694,0.561754,-0.266609,0.416136,0.268640,0.147062,-0.381610,-0.618117,0.061012,-0.103076,-0.369509,-0.466098,-0.163140,-0.143753,-0.341028,-0.527743,0.383271,-0.135225,-0.245123,0.476137,0.243419,0.321227,0.107791,0.534120,-0.344976,-0.069217,0.008447,-0.044390,-0.027270,0.333319,0.235551,-0.458312,-0.030027,0.513978,-0.024519,0.235620,0.711511,-0.378062,-0.195415,-0.016164,0.269484,-0.168273,0.031016,0.139203,0.298594,-0.006905,0.245149,0.053794,-0.362605,0.078136,0.115568,-0.125854,-0.626621,0.208950,0.078888,0.061165,-0.700942,0.376753,-0.110659,-0.326804,0.113643,-0.466676,0.263949,0.129122,0.161210,0.426879,-0.134889,0.065413,-0.307816,0.048924,0.621969,0.043480,-0.294720,0.628651,-0.348780,-0.368497,-0.184264,-0.093102,-0.513104,0.040275,0.298491,0.123564,-0.181253,0.162164,-0.283126,0.103437,-0.260896,-0.298937,-0.073311,-0.265326,-0.278931,-0.507717,-0.013120,-0.630319,-0.353439,0.056827,0.061244,-0.299452,0.735259,-0.816092,0.557000,0.563710,0.125433,-0.094380,0.537855,0.011712,0.055267,0.149812,-0.200603,0.528524,-0.150294,0.142445,0.123419,0.415273,-0.007096,-0.098908,-0.362805,0.782099', '1309172', '4058933', '1292211', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26581083', '毛骨悚然', '剧情', '前警视厅搜查一课刑警高仓（西岛秀俊 饰），在一次意外后转行成为某大学犯罪心理学教授。不久前，他和妻子康子（竹内结子 饰）搬到新家居住。不过新家周围的邻居似乎过于冷漠，特别是姓西野（香川照之 饰）的男子，总感觉拒人千里之外。当然不久后西野便向高仓夫妇展现他们友好的一面，这让鲜少与人交流的康子颇感欣慰。与此同时，高仓和搜查一课的旧同事野上（东出昌大 饰）对一桩三人失踪案展开调查。随着不断地深入，他们发现了令人震惊的事实。黑暗不断吞噬着试图接近它的人，高仓回首望去，惊讶地意识到从搬到新家开始，他便不知不觉落入了贪婪蚁狮所精心布下的死亡陷阱……本片根据前川裕的同名原作改编。©豆瓣', '西岛秀俊', '黑泽清', 5.9, 8576, 'tt4900708', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2280273970.jpg', 7, 20.4, 46.8, 20.7, 5.1, '0.337552,-0.269202,-0.610836,0.607063,-0.116027,-0.167852,0.676142,0.099430,-0.586255,-0.326907,0.340469,0.463346,-0.354266,0.144264,0.374411,0.101092,-0.309577,-0.584976,-0.238521,-0.308783,-0.345785,-0.425462,-0.251484,-0.320855,-0.066880,-0.198467,0.505645,0.187649,-0.304124,0.613926,-0.003931,0.253629,-0.468944,0.459938,-0.079181,0.163702,0.182801,0.105628,-0.164001,0.049898,-0.173523,-0.287402,-0.280267,0.048342,-0.007483,0.311506,0.929130,-0.211260,-0.391201,-0.064395,0.331042,-0.027326,0.013980,0.346222,0.330638,0.382965,0.140150,0.198480,-0.300463,-0.169237,-0.174293,0.113708,-0.543780,0.115073,0.119653,0.104975,-0.374748,0.373714,0.140505,-0.171839,0.152010,-0.433639,0.231718,0.162876,0.224533,0.276792,-0.192351,0.177258,0.005417,-0.023478,0.469732,0.012032,-0.099841,0.244462,-0.031082,-0.240086,0.051251,0.155999,-0.147841,-0.056128,0.154236,0.267831,0.041805,0.167037,-0.598428,-0.176453,-0.084512,-0.168404,0.161092,-0.311138,-0.114602,-0.658862,-0.324047,-0.364464,-0.364695,0.191677,-0.084721,-0.266800,0.547671,-0.629748,0.164582,0.583525,0.263987,-0.153984,0.470740,-0.184736,-0.039397,-0.392161,-0.237634,0.108113,0.302304,0.638599,0.301420,0.545964,-0.220559,-0.215210,-0.505258,0.329158', '1309194', '3811356', '5403927', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26581206', '正义的慈悲', '剧情', '毕业于哈佛法学院的布兰恩（迈克尔·B·乔丹 Michael B. Jordan 饰）正在经营一个非营利性的组织，该组织致力于为被判死刑的囚犯提供法律援助。在伊娃（布丽·拉尔森 Brie Larson 饰）的帮助下，布兰恩的美好愿景落地生根，他拥有了属于自己的办公室，也收获了第一个委托人。沃尔特（杰米·福克斯 Jamie Foxx 饰）曾经被判处死刑锒铛入狱，尽管他有着非常充分的不在场证明。一晃眼6年过去，当布兰恩见到沃尔特时，发现他的精神早已经被漫长的牢狱生活折磨的破碎不堪。布兰恩决定帮助沃尔特上诉，但他的热血举动在新上任的检察官那里遇冷。在失去了支持的情况下，布兰恩还是坚持为沃尔特翻案。©豆瓣', '杰米·福克斯', '德斯汀·克里顿', 7.8, 10054, 'tt4916630', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2577145347.jpg', 0.8, 2.3, 26.4, 50.9, 19.6, '0.143430,0.082666,-0.515530,0.358651,-0.259472,-0.480721,0.558902,0.237741,-0.478184,-0.426724,0.085444,0.387912,-0.018125,0.185290,0.567923,0.028326,-0.356894,-0.501508,0.051047,-0.143911,-0.279257,-0.627113,-0.278564,-0.345940,-0.196873,-0.594732,0.545131,-0.004699,0.009961,0.253928,0.156815,0.467134,0.380426,0.234405,-0.035709,-0.202770,0.285669,0.101466,-0.324102,0.367422,0.038335,-0.095833,-0.035130,-0.010143,0.057247,0.232083,0.172633,-0.119467,-0.308071,-0.245208,0.297373,-0.308224,0.075916,0.388000,0.305581,0.166979,0.104103,0.231212,-0.270526,-0.021531,0.043614,-0.241796,-0.861128,-0.134132,0.116561,0.006619,-0.573272,0.491679,-0.330435,-0.027255,0.127719,-0.599622,-0.032388,0.499201,0.242667,0.455304,-0.162933,0.102039,-0.511124,-0.076959,0.607980,0.085342,-0.233533,0.062906,-0.426405,-0.656042,-0.110671,0.084339,-0.239419,0.011914,0.053851,0.049501,-0.101425,0.199256,-0.364010,-0.203255,-0.171600,-0.482693,-0.226685,-0.434131,0.035652,-0.392469,-0.281619,0.015352,-0.489993,-0.071508,0.062489,-0.405331,0.680078,-0.918663,0.555027,0.431153,0.131558,-0.471268,0.548094,0.331440,0.160922,-0.154295,0.088969,0.381695,0.162818,0.227877,0.118899,0.233508,0.036490,-0.301131,-0.422925,0.718250', '1793491', '10440076', '1811755', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26581774', '永远的托词', '剧情', '衣笠幸夫（本木雅弘 饰）是一位小有名气的作家，和妻子夏子（深津绘里 饰）结婚多年，感情早已经由最初的炙热走向了平淡。尽管夏子一直以自己的温柔和坦诚包容着幸夫，但幸夫不仅不为所动，甚至以冷漠和粗暴回应，只因为幸夫的心里已经有了另外一个女人福永（黑木华 饰）。某日，夏子和 好友（堀内敬子 饰）结伴出游，哪知道乘坐的大巴半路上遭遇了车祸，两人不幸遇难。得知了妻子死去的消息，幸夫虽然内心里没有一丝波动，却还是在表面上装作悲痛的模样。之后，幸夫的生活陷入了混乱之中，负责他的编辑唾弃他，福永也离开了他，直到有一天，夏子好友的丈夫找到了幸夫，拜托他帮忙照顾自己的两个孩子，在此过程中，幸夫渐渐学会了正视自己的软弱和不堪，重新找到了人生的意义。©豆瓣', '本木雅弘', '西川美和', 7.6, 7592, 'tt4837062', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2362603905.jpg', 0.4, 2.3, 29.5, 52.8, 15.1, '0.179908,0.046176,-0.730186,0.582449,-0.167848,-0.406103,0.855788,0.030002,-0.742726,-0.371869,0.053110,0.728346,-0.012782,0.402112,0.187606,0.163298,-0.322300,-0.660018,0.044694,-0.024528,-0.118137,-0.683597,-0.180701,-0.156292,-0.137962,-0.191296,0.528880,0.210674,0.030379,0.740889,0.069224,0.213376,-0.078982,0.721753,-0.037291,0.237940,0.093481,0.205338,-0.072711,0.080581,0.006062,-0.503165,-0.078301,0.193625,0.009853,0.665036,0.571099,-0.058651,-0.317267,0.207643,0.169290,-0.330577,-0.320463,0.436980,0.094345,0.057926,0.443910,0.063048,-0.417962,-0.106336,0.027272,0.111113,-0.591638,-0.101177,0.102250,0.138383,-0.505324,0.581995,-0.154955,-0.320808,0.222789,-0.425451,0.357962,0.293907,0.132507,0.486506,-0.418111,0.156788,-0.144478,-0.029406,0.755758,0.083658,-0.050973,0.357823,-0.156265,-0.468740,-0.091864,-0.162993,-0.424336,-0.044319,0.062891,0.347514,-0.221552,0.043339,-0.425955,-0.003786,-0.163896,-0.098418,0.034413,-0.522248,0.019920,-0.315899,-0.114748,-0.676839,-0.556234,0.066438,-0.011774,-0.368790,0.793111,-0.828135,0.372105,0.332023,0.301258,-0.446719,0.607118,0.204030,0.030150,-0.166187,0.250594,0.286140,-0.262057,0.317025,0.348864,0.488795,-0.188198,0.040313,-0.361385,0.481333', '35030151', '3111650', '1292219', '34433857');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26581837', '上海堡垒', '爱情', '未来世界外星黑暗势力突袭地球，上海成为了人类最后的希望。大学生江洋（鹿晗饰）追随女指挥官林澜（舒淇饰）进入了上海堡垒成为一名指挥员。外星势力不断发动猛烈袭击，林澜受命保护击退外星人的秘密武器，江洋和几个好友所在的灰鹰小队则要迎战外星侵略者，保卫人类的最后一战最终在上海打响……', '鹿晗', '滕华涛', 2.9, 254008, 'tt6628322', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2564170314.jpg', 69.9, 20.5, 6.4, 1.5, 1.6, '-0.226303,0.272863,-0.513419,0.472602,0.066420,0.253988,0.310164,-0.173667,-0.019747,-0.187593,0.528422,0.628533,0.585992,-0.095918,0.338577,-0.280730,-0.211133,-0.388317,-0.218513,-0.139874,-0.296487,-0.099760,-0.704749,-0.318281,0.200423,-0.379781,1.116647,0.259359,-0.532146,0.174392,0.004974,0.490392,-0.533260,0.200422,-0.146569,-0.231429,0.483708,-0.245063,-0.629700,0.466430,-0.715784,0.116796,-0.024476,0.124658,-0.385938,-0.030097,0.724185,-0.322335,0.327483,-0.751629,0.035690,-0.454953,-0.122114,-0.230550,0.707710,0.013103,-0.076459,0.012015,0.520556,-0.039502,-0.051704,0.096313,-0.717779,0.012976,0.196035,-0.147665,-0.421636,0.171705,0.025641,0.350272,0.150046,-0.035166,0.300435,0.760532,0.400059,0.135219,-0.280508,0.631091,-0.238916,-0.041155,0.935918,-0.241656,-0.277764,-0.389755,0.216096,-0.329786,0.089513,-0.301125,-0.331388,-0.215217,0.086993,0.106672,0.113120,0.447408,-1.080763,0.020373,-0.411423,-0.184698,0.236008,-0.252795,0.100683,-0.827689,0.100932,0.102533,0.042902,0.437948,0.058320,0.198152,1.121144,-0.668402,-0.026621,0.730324,0.661244,-0.692537,0.570447,0.177878,0.096491,-0.487826,0.426324,0.307686,0.300033,0.460134,-0.225733,-0.023963,-0.369465,-0.137754,0.021059,0.194436', '26290398', '2369613', '2977870', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26582438', '哥', '剧情', '《哥哥》电影讲述了已经分离15年的两兄弟在不得已共同生活后所发生的故事。曹政奭在片中饰演没有廉耻之心的哥哥斗植，因诈骗罪服役中的他以国家级柔道选手弟弟为借口获得了假释，而都暻秀则饰演本来是成绩优异的柔道选手，却在国家代表选拔赛前因事故导致人生产生了翻天覆地变化的弟弟。朴信惠将饰演对都暻秀像亲姐姐一样珍惜给予疼爱，与突然出现的曺政奭争吵不休的角色 。', '都暻秀', '全秀庆', 7.6, 21499, 'tt6388082', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2393994340.jpg', 0.5, 3.5, 32.8, 41.7, 21.5, '-0.249327,-0.299376,-0.552852,0.628432,0.191807,-0.199410,0.600846,0.300148,-0.407952,-0.264639,0.458268,0.655511,-0.293302,-0.063767,0.323242,-0.558114,-0.173424,-1.079331,-0.289828,-0.257213,-0.198280,-0.425447,0.059406,0.144578,-0.086949,-0.594798,0.862482,-0.281595,-0.287529,0.514015,0.125346,0.307337,-0.113197,0.297468,0.161810,0.049868,-0.016611,0.539652,-0.608541,0.095266,0.108770,-0.243932,-0.184719,-0.028440,0.070513,0.421739,0.858075,-0.458866,-0.125241,-0.302590,0.492188,-0.180264,-0.138976,0.014624,0.257282,0.161896,0.537856,0.360867,-0.059874,0.140171,-0.054173,-0.393408,-0.880465,-0.115510,0.505533,0.127655,-0.442063,0.807205,0.053577,-0.273710,0.310128,-0.083257,0.315632,0.334698,0.470097,0.568121,-0.392092,0.248979,-0.053156,0.339993,0.629654,-0.153332,-0.139717,0.558361,-0.249237,-0.499199,-0.192602,-0.534237,-0.485859,0.208100,-0.054778,0.043256,-0.123911,0.440415,-0.171812,-0.226593,0.093658,-0.104711,0.240783,-0.490530,0.049376,-0.278806,-0.138711,-0.359804,-0.138553,0.116898,0.007668,-0.639954,0.900192,-1.047161,0.255980,0.442774,0.320894,-0.734590,0.593418,0.256430,0.117837,-0.354458,-0.146113,0.077940,0.058331,-0.081182,-0.160772,0.099651,-0.035120,-0.197175,-0.242602,0.433434', '30345227', '26809007', '4127270', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26584797', '重生', '动作', '小店店员敏郎和小女孩早智住在石川县的乡下。一天在小镇上发生了一场神秘的谋杀，随后发现这其实仅仅是对敏郎之后遭遇的警示。原来敏郎曾效忠于一个神秘的组织，然而他却亲手摧毁了这个组织，仅留下长官幽灵一个活口。幽灵于是带着杀手们前来复仇，决心处决这个叛徒。敏郎也为了他所爱的人们而与幽灵决一生死。', '坂口拓', '下村勇二', 6.3, 7372, 'tt5678110', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2461982063.jpg', 3.2, 17.6, 49, 21.5, 8.8, '0.170667,0.102201,-0.850435,0.602412,-0.524809,-0.073300,0.962967,-0.065032,-0.446393,-0.466521,0.420577,0.948277,0.279062,0.141753,0.451240,-0.151081,-0.117100,-0.637254,-0.161118,-0.547803,-0.244667,-0.434288,-0.398503,-0.410039,0.095797,-0.122675,0.504329,0.324898,-0.023896,0.383972,0.553619,0.415391,-0.280701,0.397238,-0.316800,-0.090248,0.138258,-0.055018,-0.303217,0.103070,-0.329983,-0.309035,-0.186834,0.264690,-0.428567,0.580179,0.483932,-0.740380,-0.427784,-0.448324,0.150260,-0.595316,-0.011995,0.056156,0.329473,-0.032599,0.066589,0.145192,-0.000180,-0.199466,0.084202,0.003231,-0.804730,-0.250619,0.023283,0.267834,-0.521732,0.471602,0.008358,0.001259,0.004034,-0.075400,0.191822,0.317204,0.308606,0.053702,-0.364764,0.121710,-0.600892,-0.028242,0.913632,-0.146152,-0.092676,0.220011,0.140193,-0.516630,-0.052371,-0.134364,-0.318316,0.236860,0.252298,0.041158,-0.411689,0.141328,-0.878360,-0.166258,-0.315784,0.042732,-0.039452,-0.501126,-0.415914,-0.574680,-0.112006,-0.218266,-0.331648,0.201991,0.150430,0.016158,0.771040,-1.065843,0.536753,0.743507,0.212992,-0.660633,0.572034,0.400682,0.126389,-0.108595,0.090256,0.071520,0.374638,0.583791,0.085205,0.194210,-0.116437,-0.100907,-0.321786,0.197502', '1308755', '25721544', '3005387', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26585014', '希特勒回来了', '喜剧', '二战结束70年后，沉睡的希特勒（奥利佛·马萨奇 Oliver Masucci 饰）竟然苏醒了。再度走上德国柏林的街头，眼前的一切已经和当年大相径庭，而他的一帮拥簇也早已经不再身边，希特勒陷入了迷惘之中。让他没有想到的是，在这个网络时代里，自己因为“长得太像希特勒”而一跃成为了网红，接踵而至的聚光灯和赞誉令希特勒内心里建造帝国的梦想死灰复燃。于是，希特勒决定利用新时代的高科技产物——网络来实现自己的理想。然而，现在已经是二十一世纪了，希特勒的计划在刚开始似乎进行的非常顺利，但渐渐的，分歧产生了，他无法掌控的事情接二连三的发生。©豆瓣', '奥利弗·马苏奇', '大卫·韦恩特', 7.8, 47983, 'tt4176826', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2329535697.jpg', 0.6, 3.1, 24.4, 47.3, 24.6, '0.491385,0.361060,-1.223458,0.614619,-0.129737,-0.352344,0.755507,-0.242025,-0.666758,-0.271322,0.042257,0.883121,-0.285035,0.410905,0.339232,-0.028628,-0.466389,-1.083777,-0.171920,-0.219237,-0.358047,-0.573750,-0.421999,-0.365251,-0.375459,-0.255256,0.961692,0.318962,-0.123828,0.386029,0.366741,0.280080,0.511675,0.770550,-0.256579,-0.006039,0.307358,-0.020653,-0.218667,0.119839,0.159577,-0.499904,-0.076758,0.659412,-0.258467,0.377081,0.470114,-0.602620,-0.190079,-0.137066,0.564179,-0.502570,-0.291086,0.256403,0.369793,0.293627,-0.082827,0.137204,-0.313043,-0.115019,-0.197084,-0.179658,-0.709038,0.018160,-0.096477,0.046620,-0.456092,0.222463,0.018067,-0.030579,0.114020,-0.402897,0.333460,0.607513,0.592679,0.519902,-0.322078,-0.150382,-0.561742,0.143142,0.936638,0.048334,-0.656417,0.558612,-0.158748,-0.435444,-0.174224,-0.143363,-0.215139,-0.107991,0.130135,0.276277,-0.337813,0.531763,-0.562691,0.214764,-0.395474,-0.451080,-0.019335,-0.329965,-0.187640,-0.498436,-0.629876,-0.583989,-0.271416,-0.000663,-0.019014,-0.210627,0.717929,-1.046688,0.313436,0.286177,0.189843,-0.422551,0.553504,-0.021064,-0.038236,-0.103001,0.188983,0.173447,-0.608172,0.468579,0.018289,0.346181,0.080386,-0.229319,-0.369644,0.795294', '1870682', '1301022', '4853478', '1302109');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26586432', '契克', '剧情', '麦克（特里斯坦·勾贝尔 Tristan Göbel 饰）是一个性格非常内向的男孩，他喜欢上了班上最受欢迎的姑娘塔迦娜（阿妮娅·文德尔 Aniya Wendel 饰）。麦克当然是不敢讲自己的喜爱之情对塔迦娜流露半分的，他只能将这强烈的悸动努力的隐藏在心底。在塔迦娜的眼里，麦克只是一个默默无闻的陌生人而已，这也难怪她没有将自己的生日宴邀请函给他，这令麦克感到非常的郁闷。同样没有收到邀请的，还有班上新来的转学生契克（阿南德·巴特比勒格·楚隆巴特尔 Anand Batbileg Chuluunbaatar 饰），这个行为举止放荡不羁，但是成绩却惊人的优异的怪人刚来没多久就受到了全班人的孤立。在机缘巧合之下，麦克和契克一拍即合，两人偷了一辆车，踏上了自驾之旅。©豆瓣', '特里斯坦·勾贝尔', '法提赫·阿金', 8.4, 50194, 'tt4911940', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2369390663.jpg', 0.2, 0.9, 13.6, 48.2, 37.1, '0.732243,-0.260667,-0.845937,0.960225,-0.370381,-0.205690,0.846924,0.185638,-0.644111,-0.015952,0.197292,0.817519,-0.359227,0.229616,0.206394,-0.003789,-0.149467,-0.437774,-0.175689,-0.240934,-0.077901,-0.471645,-0.287729,-0.059463,-0.298494,-0.072944,0.355409,-0.043754,-0.208209,0.737277,0.499664,0.369079,0.435928,0.637490,-0.232629,0.082531,0.086239,-0.136787,0.288134,0.067426,0.159604,-0.219713,-0.215557,0.510827,0.107284,0.634999,0.507256,-0.141939,-0.079783,0.192369,0.323311,-0.202602,-0.005295,0.149596,0.230633,-0.046030,0.115481,-0.123571,-0.176859,0.067319,0.183330,-0.063069,-0.816774,0.206108,0.082645,0.130271,-0.528960,0.600606,-0.285655,-0.179533,0.116708,-0.223781,0.043805,0.064629,0.029358,0.248244,0.098276,0.044439,-0.311362,-0.117372,0.484759,0.066904,-0.354969,0.418216,-0.585872,-0.502764,0.024110,-0.301764,-0.564007,0.009667,0.289096,0.045296,0.011868,0.043963,-0.503605,0.074371,-0.084267,-0.170958,-0.049180,-0.525841,-0.222183,-0.468851,-0.190436,-0.612637,-0.558443,-0.009356,0.069603,-0.195910,0.783657,-1.008599,0.084032,0.525554,0.055622,-0.173386,0.798907,0.211442,-0.247081,-0.083724,-0.200644,0.029333,0.105815,0.092538,0.130139,0.696128,0.152066,-0.339969,-0.269996,0.727767', '24756472', '35144311', '1769507', '4058933');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26586488', '红衣小女孩', '惊悚', '房产经纪人何志伟（黄河 饰）与奶奶（刘引商 饰）共同生活，他一心想要买属于自己的房子好跟交往5年的电台DJ女友怡君（许玮宁 饰）结婚，而怡君似乎还没有准备好。一天早上，阿伟发现奶奶离奇失踪了，通过门卫阿坤伯（张柏舟 饰）的帮忙，他发现奶奶疑似被一名诡异的红衣小女孩给带走了，这可能与山中传说有关，而危险正在步步靠近着自己。事故的几天后，失魂落魄的奶奶回来了，而阿伟却失踪了，无奈之下怡君开始了惊心动魄的找寻之旅，恐怖的真相也在接近着她。©豆瓣', '许玮甯', '程伟豪', 5.9, 14209, 'tt5078188', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2366463273.jpg', 4.3, 21.5, 53.1, 16, 5.1, '0.213646,-0.042396,-0.870982,0.326854,0.022983,-0.349405,0.719847,0.056287,-0.520320,-0.417405,-0.000978,0.414223,-0.072233,0.341844,0.153706,0.310620,-0.157803,-0.566750,-0.025042,-0.073796,-0.381489,-0.334731,-0.209828,-0.130136,0.229716,-0.394784,0.044723,0.075633,0.072926,0.583466,0.340914,0.018798,-0.121326,0.588617,-0.421867,0.171586,0.059252,0.032315,-0.266276,0.171394,0.298455,-0.230305,-0.147770,0.263458,0.117685,0.365551,0.509446,0.023950,-0.399784,0.283728,0.404665,-0.104009,-0.063768,0.179674,0.414751,0.023516,0.389301,0.154225,-0.278757,-0.111760,0.175522,0.073011,-0.330968,0.267042,0.045577,0.097295,-0.701475,0.286192,-0.056467,0.017900,0.242946,-0.539597,0.377679,0.497393,0.155170,0.367624,-0.152697,-0.016077,-0.625214,0.418782,0.669866,-0.124932,0.189118,0.472437,0.308293,-0.192391,-0.083815,-0.061901,-0.478363,0.184389,0.341448,0.076302,-0.304694,-0.089287,-0.671628,-0.064023,-0.116252,-0.119797,-0.136201,-0.335523,-0.198149,-0.229049,-0.187403,-0.341608,-0.449785,0.306331,-0.066580,-0.130512,0.449046,-0.561757,0.438083,0.666498,0.453815,-0.555115,0.632301,-0.067771,0.016154,-0.140998,0.029525,-0.163137,-0.189302,0.423027,0.362510,0.446723,0.071117,-0.278128,-0.486568,0.196125', '10355329', '1866424', '25837175', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26586766', '勇敢者游戏：决战丛林', '喜剧', '斯宾塞、“冰箱”弗里奇、贝瑟尼和玛莎是某高中的问题学生，这一日他们因不同的错误而被留校劳动。在一间堆满陈旧废弃物的储藏室内，斯宾塞发现一台年代久远的游戏机。四人原本想放松一下，谁知却被吸进了游戏机中。在凶险的尤曼吉热带丛林里，少男少女分别变成了勇石博士（道恩·强森 Dwayne Johnson 饰）、毛子·芬巴（凯文·哈特 Kevin Hart 饰）、奥伯伦教授（杰克·布莱克 Jack Black 饰）和铁拳露比（凯伦·吉兰 Karen Gillan 饰），他们必须遵照游戏规则，突破邪恶博士的阻挠，将宝石放回原处，恢复尤曼吉的和平，而这也是他们重返现实世界的唯一途径。毒蛇、猛兽以及纠缠不休的暴徒，为四个玩家带来了永生难忘的冒险体验……©豆瓣', '道恩·强森', '杰克·卡斯丹', 6.8, 195457, 'tt2283362', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2506258944.jpg', 0.9, 7.6, 50.2, 34.4, 6.8, '0.492008,0.055002,-0.409025,0.365588,-0.139421,-0.265597,1.036783,0.088079,-0.480670,-0.184143,0.150671,0.613712,-0.160360,0.046015,0.212194,0.089330,-0.419890,-0.402264,0.063367,-0.316548,-0.183502,-0.527568,-0.345885,-0.242811,0.107640,-0.286036,0.590327,0.009312,0.020573,0.531943,-0.056424,0.186333,-0.161465,0.224512,0.073394,0.060186,0.009059,-0.169330,-0.332797,0.083289,0.128163,-0.180450,0.052512,0.077946,0.128459,0.243970,0.676927,-0.356927,0.088626,-0.102314,0.239310,-0.202242,-0.333348,0.204093,0.155781,0.145994,0.003496,0.141476,-0.079429,0.263539,0.383475,-0.053058,-0.585841,-0.048810,0.004398,0.273474,-0.405778,0.685568,-0.044248,-0.110168,-0.027981,-0.101813,0.204105,0.100768,0.255802,0.362117,-0.013397,-0.076266,-0.453715,0.019514,0.297554,-0.327538,-0.109295,0.133208,-0.251177,-0.486452,0.093596,-0.113593,-0.275196,-0.165516,0.399285,0.116657,-0.216988,0.067389,-0.836506,0.120404,-0.204790,-0.299142,-0.214344,-0.228832,-0.281005,-0.586185,-0.016370,-0.112129,-0.264525,0.003907,0.071492,-0.202877,0.566146,-0.747920,0.036672,0.372769,0.414731,-0.066137,0.651928,-0.162761,0.305062,-0.215603,-0.103636,0.113666,0.000683,0.633923,0.309407,0.438001,0.090234,-0.232492,-0.483781,0.362636', '21619567', '1467779', '3005387', '1394176');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26586806', '塔洛', '剧情', '孤儿塔洛牧羊维生，他是记忆世界的国王，记得所有的事情，但他却是真实生活的边缘人，没人记得他，连他的名字都忘记了，只唤他小辫子。直到他遇到理髮馆女孩，第一次被人记得，第一次爱，那就是存在的开始。塔洛开始一场爱情，很多惊奇，大多失望，见天地，望众生，然后回到自己。辫子失去了还会长回来，那关于这个世界呢？总是需要一次离开，然后才知道归来。改编自导演万玛才旦短篇小说，聚焦藏人生活景况，以黑白影像粗粝质感勾勒出西藏大地的苍凉，更缩影这一代藏族青年的内心迷惘。在心灵的高原上壮游，以为走得那麽远，其实仍踌躇传统原生文化与现代文明间，欲离何曾离，云空未必空。', '西德尼玛', '万玛才旦', 7.7, 17747, 'tt4923042', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2401749567.jpg', 0.3, 2.3, 23.8, 58.9, 14.6, '0.202095,0.173235,-0.909068,0.495836,-0.158306,-0.258862,0.649003,-0.178184,-0.576729,-0.396487,-0.047609,0.682083,-0.021292,0.190576,0.227631,0.127470,-0.154075,-0.516583,0.011641,-0.273153,-0.220221,-0.130328,-0.282555,0.019597,-0.172119,-0.260532,0.478538,0.399754,-0.127212,0.356485,-0.014928,-0.041414,-0.081726,0.404671,-0.494853,0.005779,-0.236476,0.184746,-0.305241,-0.246800,0.020276,-0.062606,-0.243031,0.143575,-0.342276,0.066414,0.380129,-0.290030,-0.293973,0.035743,0.268857,-0.052255,-0.124609,0.152712,0.137531,0.084854,0.286762,0.047697,0.011597,-0.008677,0.012518,-0.010115,-0.500594,0.216418,0.020263,0.428042,-0.380424,0.472566,-0.005578,-0.186291,-0.023484,-0.251096,0.286801,-0.012709,0.395830,0.500782,0.027641,-0.008294,-0.304616,0.108281,0.660599,-0.125252,-0.351918,0.458385,-0.176205,-0.327188,-0.112711,-0.059806,-0.429396,0.328521,-0.052238,0.109404,-0.291060,0.195622,-0.427450,0.111928,0.026778,-0.188388,0.041346,-0.364104,-0.379167,-0.040126,-0.270511,-0.363375,-0.241636,0.075558,0.028702,-0.262081,0.472601,-0.819655,0.377645,0.389832,0.253031,-0.354967,0.612525,0.153714,-0.143812,-0.382816,-0.103425,0.630897,-0.154795,0.286605,-0.063773,0.161640,0.011266,-0.010481,-0.354263,0.543184', '1292211', '25858759', '4275444', '1298128');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26588017', '哈姆雷特', '剧情', '丹麦王子哈姆雷特（本尼迪克特·康伯巴奇 Benedict Cumberbatch 饰）被传召回家参加父亲的葬礼以及自己母亲和叔父克劳迪斯的婚礼。父亲的突然离世，加上母亲的改嫁，使哈姆雷特终日郁郁寡欢。一次哈姆雷特在半夜里来到城堡高台上，与父亲的鬼魂相会，得知父王被叔父克劳迪斯毒死。鬼魂要求哈姆雷特向那个篡夺王位、霸占王妃的凶手复仇。背负了复仇任务的哈姆雷特决定用假装发疯的办法来掩饰自己，以窥探克劳迪斯的一举一动。随后他安排了一场宫廷戏，将国王被害一幕以戏剧形式表演出来。叔父看后原形毕露，而哈姆雷特却误杀了恋人（珊·布鲁克 Sian Brooke 饰）的父亲，导致恋人发疯死去。随后哈姆雷特的母亲也饮毒酒死亡，最终哈姆雷特愤怒杀死叔父。©豆瓣', '本尼迪克特·康伯巴奇', '罗宾·洛', 8.4, 6956, 'tt4476736', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2546253901.jpg', 0.3, 1.3, 14.7, 46, 37.7, '-0.059570,0.005895,-0.501326,0.595148,-0.087104,-0.464390,0.855783,0.135538,-0.426133,-0.272736,0.541513,0.938033,-0.173136,0.378741,0.292871,-0.101871,-0.138456,-0.603537,-0.177410,-0.035673,-0.057672,-0.509177,0.121167,-0.421056,0.211071,-0.481519,0.516903,-0.309931,-0.078161,0.386117,0.508247,0.363551,-0.190663,0.404025,0.136289,0.067955,-0.158454,-0.251594,-0.381025,0.240995,0.221432,-0.129830,-0.141215,0.259005,-0.163954,0.335403,0.654374,-0.597721,-0.029122,-0.417801,0.564623,-0.511265,0.061059,0.321510,0.119289,0.041276,0.065701,0.487190,-0.093636,-0.211356,-0.102440,0.154070,-0.423110,-0.008411,0.113473,-0.013039,-0.624556,0.375612,-0.217460,0.145580,0.186156,-0.196351,0.283955,0.308936,0.055387,0.519108,-0.419796,-0.179720,-0.535317,0.361484,0.638910,-0.272590,0.172997,0.073697,0.211523,-0.153967,0.231267,-0.390861,-0.396827,0.289571,0.480598,-0.127568,-0.132782,0.351293,-0.163444,-0.885157,-0.541871,0.062193,0.184375,-0.545772,-0.021240,-0.412580,-0.039330,0.286338,-0.086893,-0.295772,0.132798,-0.316475,0.354514,-0.326679,0.349642,0.363438,0.259830,-0.660030,0.277893,0.092089,0.063336,-0.191345,-0.029687,0.326604,0.145673,-0.005685,0.003179,-0.122753,0.178861,0.087315,-0.566831,0.347917', '1301717', '1296390', '1292217', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26588308', '死侍2：我爱我家', '喜剧', '拥有不死之身的死侍韦德·威尔森（瑞恩·雷诺兹 Ryan Reynolds 饰）继续在惩恶扬善、毒舌嘴贱的路上绝命狂奔，与此同时他和女友瓦内莎（莫蕾娜·巴卡林 Morena Baccarin 饰）的爱情逐渐升华，两人全新期待新生命的到来。谁知命运难测，因瓦内莎意外身亡，韦 德万念俱灰，绝望地渴求生命的终结。在他最失落的时候，钢力士和少年弹头等将他领走，成为X战警中的一员。在某次行动中，死侍因袒护暴走的14岁变种人拉塞尔（朱利安·迪尼森 Julian Dennison 饰）而随同对方被关入冰盒监狱。没过多久，来自未来的电索（乔什·布洛林 Josh Brolin 饰）闯入监狱，意图杀死在未来引起无数灾难的拉塞尔。为了阻止电索，逃离监狱的死侍找到一群战友与之对抗，而拉塞尔则朝着黑暗渐渐远去……©豆瓣', '瑞安·雷诺兹', '大卫·雷奇', 7.3, 414313, 'tt5463162', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2545479945.jpg', 0.9, 4.9, 37, 43.3, 13.9, '-0.117975,0.228271,-0.615122,0.296946,-0.074643,-0.070368,0.966822,0.214466,-0.147899,-0.331351,0.257005,0.620698,-0.190551,0.185275,0.339609,-0.347150,-0.137861,-0.562946,-0.300091,-0.070427,-0.555286,-0.288716,-0.148669,-0.262176,0.110163,-0.592259,0.844360,0.315587,-0.133649,0.434965,0.473236,0.809692,-0.334873,0.396133,-0.094983,0.184651,0.116653,-0.195612,-0.197727,0.234618,-0.006732,-0.144453,-0.159538,0.194507,-0.146051,-0.011709,0.761959,-0.373190,0.210107,-0.281423,0.063855,-0.469679,-0.117792,0.105135,0.001368,-0.200464,-0.129301,0.136897,-0.054460,0.013394,0.145517,0.002672,-0.930853,0.095020,-0.079699,0.141480,-0.394067,0.037438,-0.005312,0.231687,0.212575,-0.164622,0.172929,0.289309,0.251488,0.442296,-0.245158,0.110184,-0.595245,0.037512,0.627539,-0.190268,-0.189374,0.076886,0.024495,-0.209391,-0.115303,0.046274,-0.508375,-0.295147,0.657337,0.184748,0.089937,0.451160,-0.532845,-0.180983,-0.280592,0.115569,0.000501,-0.358120,-0.195230,-0.432031,-0.024492,-0.038741,-0.117484,0.129431,-0.170116,-0.161325,0.487085,-0.491039,0.474385,0.271949,0.333881,-0.408691,0.566821,-0.065272,0.188818,-0.434323,0.026039,0.806737,0.534403,0.101227,0.196553,0.012986,-0.222072,0.176681,-0.615463,0.573959', '25828589', '1292528', '10440076', '2988294');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26588314', '伯德小姐', '剧情', '女孩克里斯汀（西尔莎·罗南 Saoirse Ronan 饰）跟随着家人来到了位于加州的一间教会学校开始了她的高中生涯，虽然心中有百般的不愿意，但克里斯汀尚且没有足够的力量来反抗家人和生活的安排。在学校里，克里斯汀最好的朋友是朱丽（比妮·费尔德斯坦 Beanie Feldstein 饰），三观相近的两人无话不谈。克里斯汀参加了舞台剧比赛，并因此结识了名为丹尼（卢卡斯·赫奇斯 Lucas Hedges 饰）的男孩，相互吸引的两人很快就走到了一起。然而，这段感情最终以分手告终。为了和校园交际花珍娜（奥德娅·拉什 Odeya Rush 饰）套近乎，克里斯汀不惜撒谎，遗憾的是，谎言并不能换来真正的友谊。当克里斯汀身陷同凯尔（提莫西·查拉梅 Timothée Chalamet 饰）的感情纠葛之中时，她的家庭也在经历着艰难时期。©豆瓣', '西尔莎·罗南', '格蕾塔·葛韦格', 7.9, 304573, 'tt4925292', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2505925363.jpg', 0.3, 1.8, 25, 50.4, 22.6, '0.627581,-0.000158,-0.479655,0.621121,-0.009743,-0.327770,0.758067,0.117109,-0.700109,-0.209547,0.129107,0.815918,-0.173764,0.306230,0.371333,0.075321,-0.627489,-0.717203,0.198487,-0.300937,-0.266262,-0.805706,0.122700,-0.023992,-0.360218,-0.322121,0.437154,-0.143386,0.007032,0.614152,0.261200,0.135905,-0.009133,0.330034,0.349584,0.127082,0.122606,-0.073652,-0.340952,0.268152,0.073223,-0.001293,-0.281419,0.142791,0.568863,0.429072,0.580568,-0.148156,0.336919,0.150875,0.179516,-0.114107,0.164952,0.206492,0.000834,-0.423298,0.464723,0.233222,-0.192453,-0.027416,0.196008,-0.291640,-0.764253,0.460186,0.120543,0.173398,-0.655187,0.620857,-0.089294,-0.263569,0.124955,-0.112112,-0.086093,0.480412,0.312801,0.219710,-0.155622,-0.076782,-0.243255,-0.023714,0.746294,0.161351,-0.276437,0.365452,-0.526698,-0.217902,-0.281743,-0.024750,-0.594021,-0.169853,0.355636,0.192266,-0.189122,0.363759,-0.649338,-0.132465,-0.288918,0.052252,0.309846,-0.413969,0.081437,-0.754936,-0.132690,-0.740206,-0.458782,0.012966,-0.108132,-0.361921,0.582978,-1.096924,0.055302,0.445813,0.434734,-0.088261,0.647967,0.075088,0.149949,-0.259272,0.054344,0.648698,-0.041041,0.042914,0.297296,0.463148,0.209288,-0.056509,-0.234397,0.562414', '20277433', '35030151', '1292219',