INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26588783', '冰雪女王3：火与冰', '动画', '不断遇到麻烦可算是凯与格尔达这对姐弟的特点了，毕竟他们是在冰雪的国度被矮人们养大的。随着他们长大成人，等待他们的麻烦也升级了。这一次，格尔达与新认识的小伙伴罗兰去寻找传说中的许愿球，不想却召唤出封印在许愿球中的邪恶力量，这对姐弟是否能够逢凶化吉，还世界一个和平？', '迪·布拉雷·贝克尔', '阿列克谢·特斯蒂斯林', 4.5, 2802, 'tt4685554', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2517033932.jpg', 26.2, 29.1, 37.9, 5.8, 1, '0.135497,0.224441,-0.858070,0.622995,-0.530123,-0.182728,0.834580,-0.127598,-0.519504,-0.007791,0.060332,0.752140,-0.150330,-0.025542,-0.080810,-0.067291,-0.187387,-0.382241,0.211361,-0.237969,-0.472166,-0.286477,-0.500854,-0.179921,-0.045278,-0.495671,0.481612,0.346916,-0.182360,0.239011,0.125931,0.196325,-0.170364,0.468672,-0.766799,0.162917,-0.202172,0.329465,-0.276248,0.380896,-0.012474,0.045056,-0.030022,0.199170,0.107919,0.141309,0.772452,-0.567264,-0.087622,-0.101552,0.183604,-0.434656,-0.121186,0.014080,0.273516,-0.084528,0.268605,0.028194,0.135041,-0.173557,-0.196839,-0.277854,-1.189132,0.201385,0.155009,0.083770,-0.613706,0.548773,0.181172,-0.313427,-0.036822,-0.213735,0.353682,0.627017,0.348538,0.534454,-0.461634,0.036408,-0.446667,-0.179554,0.773670,-0.247967,-0.312924,0.650635,-0.281725,-0.465325,-0.215627,-0.112415,-0.327570,0.046758,0.502673,0.352667,-0.220779,0.232312,-0.813545,0.185801,-0.250752,-0.245510,0.325098,-0.790415,-0.074222,-0.338589,-0.081903,-0.419853,-0.398805,0.288314,0.165468,-0.263797,1.095030,-0.865238,0.227247,0.873488,0.690653,-0.549311,0.891866,0.287535,0.254624,-0.478995,-0.111868,-0.003768,0.015060,0.598499,0.258119,0.459173,0.312925,0.046581,-0.611663,0.407996', '24284209', '25928048', '3755531', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26589957', '守护者：世纪战元', '动作', '一直从事兵器研究的邪恶的克拉托夫教授欲用生物兵器达成自己的野心，在俄罗斯境内的各大城市制造了一系列大规模爆炸恐怖袭击。为了消灭邪恶势力，拯救面临生物兵器毁灭的国家，俄罗斯国防部派出了冷战时期创建的名为“爱国者”的超级英雄团队，各个英雄异于常人，身怀特技，与号称统 治世界的邪恶教授展开了一场殊死较量。', '塞巴斯蒂安·斯萨克', '萨里·奥德赛耶', 3.8, 16105, 'tt4600952', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2459069346.jpg', 33, 46, 17.9, 2.3, 0.8, '-0.008528,-0.085676,-0.451522,0.356566,0.173878,0.435740,0.149998,-0.275315,-0.109024,-0.461655,0.530007,0.795561,0.127374,-0.612450,0.201021,-0.481255,-0.090366,-0.677480,-0.188302,0.222053,-0.172240,-0.270093,-0.872692,-0.504160,0.085793,-0.746028,0.897714,0.151867,-0.596229,0.133082,-0.052552,0.669283,-0.310787,0.198042,0.110519,-0.613933,0.109892,-0.115542,-0.799532,0.249346,-0.312285,0.091249,-0.007045,0.170390,-0.333982,0.098456,0.525052,-0.757294,0.309245,-0.769150,0.440113,-0.375457,-0.294120,-0.293641,0.553177,0.252604,-0.104050,0.105783,0.262475,-0.049903,0.267230,-0.035144,-1.123902,-0.449845,0.482640,-0.170420,-0.341892,0.429433,0.097478,0.144352,-0.084128,0.047378,0.315917,0.515401,0.457191,0.490711,0.162549,0.096950,-0.405859,0.077555,0.445855,-0.420150,-0.502403,-0.261913,-0.146309,-0.692080,-0.325750,-0.925593,-0.381332,-0.112815,-0.031687,-0.218386,0.055786,0.798868,-1.283947,0.115175,-0.169826,-0.072354,0.353056,-0.126559,0.044714,-0.905626,0.008595,0.035883,-0.094662,0.263240,0.396243,-0.110644,0.999650,-0.817276,-0.152596,0.557790,0.261815,-0.684517,0.548899,0.048251,0.237836,-0.401983,-0.233953,0.213333,0.039536,0.474215,-0.060485,0.264719,0.278108,0.030762,-0.062296,0.536288', '7155241', '25890017', '26290398', '1308248');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26591649', '一路向南', '悬疑', '1）米奇与杰克开车来到一家加油站，四周围逡巡着骷髅一样的怪物，他们想要逃离，却总会回到加油站门口。2）三个爵士乐女孩的汽车路上遇到故障，她们搭乘了一对夫妇的车并来到对方的家里。然而这户人家弥漫着古怪的气息。3）驱车夜归的男人卢卡斯不慎撞到了其中一名逃出来的爵士女孩。他报警求救，却不知自己身在何处。万般无奈下，他载着女孩前往附近的城镇治疗，但医院空无一人。4）破旧的酒吧中，突然闯进一名持枪男子要寻找失踪的妹妹，他心急如焚，但他完全没意识到这是一个多么诡异的所在。5）一家三口回到家中，这时突然有几名戴着面具的人闯了进来。衣冠楚楚的男主人，不知将要为何付出代价。©豆瓣', '查德·威利亚', '罗克珊·本杰明', 6.2, 9454, 'tt4935334', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2306945663.jpg', 4, 16.6, 50.1, 22.8, 6.5, '0.585824,-0.049289,-0.701101,0.140453,-0.166464,-0.274065,1.121499,0.190352,-0.521310,-0.524063,0.677945,0.840045,0.016628,0.554213,0.371569,0.259334,-0.182601,-0.200594,0.020921,-0.360879,-0.374404,-0.085200,-0.286791,-0.115418,0.082752,0.161733,0.351536,0.213619,-0.079908,0.524468,0.290035,0.201769,-0.659373,0.788083,-0.540437,0.117073,0.242699,-0.079771,0.155350,0.257182,-0.075282,-0.364070,-0.267930,-0.031134,-0.189996,0.431033,0.668186,-0.127994,-0.202300,0.144680,0.148681,-0.068100,-0.099741,0.199357,0.428225,-0.060107,0.131764,-0.268371,-0.164504,0.023101,-0.093591,0.091020,-0.114905,0.398378,-0.154566,0.341730,-0.821324,0.114037,-0.087908,-0.140151,0.194533,-0.531750,0.347053,0.082113,-0.078555,0.402624,-0.142077,-0.028532,-0.886264,-0.467319,0.813599,-0.045608,-0.050778,0.306725,-0.071035,-0.394857,0.109824,0.057602,-0.567361,-0.149684,0.474662,0.229028,-0.211295,-0.434388,-0.483517,0.107097,-0.293464,0.000907,-0.268067,-0.117684,-0.433563,-0.763412,0.218235,-0.092393,-0.148780,0.427257,-0.312742,0.184570,0.224080,-0.791070,0.122850,0.432172,0.391169,-0.392769,0.752784,-0.352321,0.158737,-0.129755,-0.306374,0.254092,0.328513,0.608042,-0.134189,0.502559,-0.497516,-0.071321,-0.432446,0.231717', '10466639', '21619567', '1296534', '26694497');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26591654', '地雷区', '剧情', '电影改编自真实的历史事件。故事发生在第二次世界大战结束之后，德国战败，大批被捕的德国士兵成为了俘虏。战争期间，德军曾在丹麦西海岸埋下了超过一百五十万枚地雷，而其中一些被俘虏的年轻德国士兵，则被迫成为了活体地雷探测器。在丹麦军官卡尔（罗兰德·莫尔 Roland Møller 饰）的带领下，那些尚且只是孩子的俘虏们开始了排雷行动，他们用双手，用双脚，甚至用生命，一步一步的净化着长长的海岸线。然而，当任务结束之后，当幸存的孩子们满心欢喜的以为他们终于逃脱了死神的手掌可以回到故乡之时，等待着他们的，却是另一项同样残酷的任务。©豆瓣', '罗兰·默勒', '马丁·赞里维特', 8.7, 75135, 'tt3841424', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2273266824.jpg', 0.1, 0.4, 8.6, 47.1, 43.9, '0.240674,0.134227,-0.700835,0.489767,0.018432,-0.145963,0.622359,-0.286689,-0.307116,-0.087718,0.442752,0.511241,0.034977,0.071157,0.287141,-0.378065,-0.437768,-0.855540,-0.244363,-0.331120,-0.685163,-0.260362,-0.249385,-0.126361,-0.093876,-0.372441,0.990156,0.380137,-0.002756,0.307048,0.201959,0.369061,0.047932,0.268017,-0.331827,0.035206,0.315216,-0.535697,-0.310364,0.249534,-0.194261,-0.306900,-0.241320,0.156137,-0.075365,0.194220,1.006224,-0.626746,-0.017939,-0.374560,0.158501,-0.394700,0.087301,0.156039,0.287745,0.511393,0.246294,0.144370,0.084539,0.185088,0.273116,-0.109215,-0.627577,0.009564,-0.348851,0.222742,-0.684262,0.237925,-0.181828,0.271651,0.211171,-0.319827,0.221068,0.617136,0.122902,0.260130,-0.418110,-0.028265,-0.618491,0.326748,0.638194,-0.121776,-0.485197,0.112818,0.191429,-0.580229,-0.052070,-0.202718,-0.123191,0.187268,0.573937,0.036760,-0.115799,0.539079,-0.642617,0.115376,-0.440484,-0.610845,0.125268,-0.329870,-0.223619,-0.776146,0.221229,0.043396,-0.364603,0.399500,0.203939,0.022809,0.949915,-0.451709,0.321782,0.653862,0.195086,-0.317094,0.179875,0.085748,0.355137,-0.052738,0.181108,0.368634,0.018712,0.562135,0.456473,0.333702,-0.256849,-0.005015,-0.386568,0.511077', '10467125', '5403927', '1292444', '35058077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26593587', '天才少女', '剧情', 'Chris Evans将参演马克·韦布（超凡蜘蛛侠系列）执导新片《Gifted》。该片讲述美队扮演一名原本波士顿大学助教现在是修船工的Frank Adler在姐姐自杀后领养了外甥女Mary——一位智力过人的天才少女。Mary刚一入学就表现得与众不同，然而舅舅Frank只想让孩子过普通人生活。Mary的外婆得知了少女的天赋，出现在二人的生活里，要将Mary培养成数学天才。于是一场抚养权之争开始了。', '克里斯·埃文斯', '马克·韦布', 8.3, 246285, 'tt4481414', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2394315478.jpg', 0.1, 0.6, 15.5, 51.8, 32, '0.031886,-0.148242,-0.348985,0.723504,-0.443614,-0.339083,0.352625,0.186105,-0.585610,-0.350170,0.220658,0.961586,-0.142507,0.458620,0.434294,-0.179935,-0.115097,-0.618543,-0.179157,-0.215809,-0.120249,-0.456250,-0.208572,-0.114858,-0.181010,-0.804436,0.848048,-0.435933,-0.207265,0.223237,0.089539,-0.205387,-0.010901,0.024060,-0.261330,0.041391,0.199373,0.193695,-0.187199,0.470088,0.210427,-0.098456,0.003605,-0.071791,0.122794,-0.022402,0.805409,-0.139930,0.070575,-0.170711,0.483349,-0.194809,-0.171859,0.148951,0.411733,0.082374,0.375930,0.198236,0.118584,0.161543,-0.208804,-0.455098,-0.614668,-0.032393,0.250637,-0.106292,-0.845570,0.194311,0.030777,-0.265353,0.135010,-0.353936,0.008987,0.099653,0.128144,0.582634,0.057592,0.122108,-0.316069,0.693339,0.711945,-0.182032,-0.224024,0.561925,0.137907,-0.536364,-0.055821,-0.451147,-0.674881,0.295240,0.058494,-0.116774,-0.284441,0.259172,-0.324552,-0.142200,-0.484575,0.066733,-0.120069,-0.306181,-0.067623,-0.237881,-0.260134,-0.013244,-0.332884,-0.232873,0.060635,-0.575931,1.270093,-1.098858,-0.021403,0.244857,0.065030,-0.379923,0.612642,-0.177323,0.411559,-0.150816,0.148132,0.106630,-0.157356,-0.005449,-0.206425,0.554857,-0.175566,-0.370925,-0.322740,0.429101', '27602116', '25922902', '3445516', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26593732', '清水里的刀子', '剧情', '影片讲述在十年九旱的宁夏西海固，一个偏远的农村里，一个穆斯林老头的老伴去世了，老人和儿子举意要在老伴祭日那天宰掉陪伴老人十多年的老牛来搭救亡人。在接下来的日子里，老人和儿子对牛精心照料，并且也流露出对牛的不舍和对老伴的思念。在祭日的前三天，这头牛在饮它的水里看到了将要宰它的那把刀子，于是开始不吃不喝，为了以一个清洁的内里来结束自己的生命，之后老人就陷入了对生命和死亡的思考之中。', '杨生仓', '王学博', 6.5, 5240, 'tt6312872', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2516999755.jpg', 1.7, 12.6, 53.5, 25.7, 6.5, '0.060021,-0.050541,-0.785029,0.609495,-0.368589,-0.554429,1.056620,-0.039841,-0.465918,-0.019428,0.316164,0.986390,-0.037196,0.599913,0.205660,-0.105672,-0.201890,-0.730101,-0.456989,0.024448,-0.459949,-0.195693,-0.070495,-0.167980,-0.203602,-0.260932,0.150901,0.133771,0.232387,0.503786,0.125305,-0.062367,0.267964,0.431830,-0.474755,0.192887,-0.371721,0.021530,-0.124537,0.319761,0.527107,-0.317254,0.013423,0.229182,0.056160,0.462705,0.920070,-0.372199,-0.194021,-0.078792,0.316960,-0.399683,-0.205310,0.426250,0.437595,0.002489,0.159936,0.125965,-0.453824,-0.014149,-0.176897,-0.204531,-0.782446,-0.164469,-0.105456,0.159548,-0.977904,0.727010,0.192817,-0.074467,0.133578,-0.503523,0.513682,0.386326,-0.093295,0.855043,-0.286097,-0.144631,-0.388936,0.364140,0.546139,-0.446104,0.045092,0.392888,-0.070087,-0.395790,-0.017412,-0.071194,-0.579253,-0.206981,0.351093,-0.016025,-0.641812,0.224427,-0.620347,0.038080,-0.146568,-0.270977,0.031899,-0.362803,-0.541443,-0.130725,-0.046466,-0.639119,-0.159307,0.310173,0.386043,-0.168894,0.712708,-0.720713,0.458598,0.335416,0.300434,-0.188969,0.803161,0.072976,0.236975,-0.292277,0.187076,0.142674,-0.042529,0.556054,0.311951,0.490518,-0.036728,0.181182,-0.639261,0.592344', '21619567', '26884422', '3111650', '25731805');
