INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26596158', '魔轮', '悬疑', '白富美刘晨晨（林心如 饰）和男友小川（金世佳 饰）在机缘巧合下登上了气氛诡异的“天涯号”游轮，并与其他四位身份不明的中奖者一起进入到紧张刺激的夺宝游戏中。然而，意外频发却让这场诱人的夺宝游戏演变成置人于死地的疯狂杀戮。在与世隔绝的茫茫公海上，失魂落魄的几人开始相互猜忌，事情的走向也更加扑朔迷离，而死神却步步紧逼。黑暗的背后，究竟是谁在操纵一切，这对误入魔轮的甜蜜爱人，又将逃向何处？©豆瓣', '林心如', '王早', 4.5, 3036, 'tt5187548', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2362787215.jpg', 29.8, 31.5, 26.3, 7.2, 5.2, '0.483135,0.091707,-0.826826,0.449082,0.223800,0.041677,0.861091,0.077221,-0.406429,0.247572,0.302048,0.675912,-0.380179,-0.040141,0.210281,0.127950,-0.301935,-0.726606,-0.344633,-0.098586,-0.144796,-0.440078,-0.478767,0.021810,0.076994,-0.043827,0.671898,0.441393,-0.377001,0.572294,0.603742,0.273635,-0.875910,0.694206,-0.044580,-0.139057,-0.098454,0.234226,-0.360048,-0.043846,-0.108767,-0.699482,-0.426117,0.334218,-0.052465,0.352179,0.776755,-0.331339,-0.230124,0.199327,0.279980,-0.511733,-0.245754,0.261995,0.036776,0.056564,-0.097270,0.163280,-0.119875,0.298757,-0.024515,0.192020,-0.915903,0.217213,-0.042572,0.376796,-0.166400,0.229793,0.128875,-0.247710,0.148633,-0.284512,0.178337,0.233983,0.157781,0.368138,-0.434800,-0.289076,-0.370301,-0.053516,0.876753,0.220985,-0.184406,0.275325,0.235828,-0.385495,-0.275182,-0.129209,-0.467681,-0.359437,0.402856,0.384996,-0.001229,0.503752,-0.832549,0.331502,0.029211,-0.058499,-0.475623,-0.499571,-0.183186,-0.530574,-0.171756,-0.333499,-0.269937,0.170477,0.138815,-0.323369,0.380878,-0.703490,0.321104,0.626061,0.180303,-0.556051,0.353954,0.280436,0.032633,-0.001594,-0.315452,0.160614,0.051945,0.426162,0.016472,0.298026,-0.142005,0.212935,-0.438862,0.390435', '25828589', '10581450', '20380318', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26596361', '布兰卡和弹吉他的人', '剧情', '女孩布兰卡偷窃乞讨露宿街头，家对她而言只是妄想。当她在电视上看到领养的新闻，灵光乍现想要买个妈妈。于是她努力存钱，还找街头走唱的盲眼吉他手老皮帮忙。她成为老皮的眼睛，两人一起离开贫民窟，来到大城市打拼流浪。一路上遇见形形色色的人物，经历大大小小的冒险，布兰卡真的能够如愿买到心中理想的妈妈吗？', '西德乐·盖贝特罗', '长谷井宏纪', 8.2, 19102, 'tt4679144', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2266083622.jpg', 0.1, 1, 17, 52.7, 29.2, '0.409764,-0.177279,-0.463898,-0.012516,-0.122852,-0.430929,0.489805,0.084369,-0.271029,-0.147978,0.050802,0.689998,0.100161,0.764808,0.191720,0.030117,-0.377289,-0.582390,0.411754,-0.243006,0.046013,-0.167025,-0.086484,-0.061395,-0.083730,-0.070235,0.399582,0.137630,-0.052764,0.361907,0.414548,-0.177978,-0.137495,0.205691,-0.629905,-0.180368,-0.117470,0.305555,-0.270074,0.211430,0.027621,-0.135082,-0.210353,-0.428089,0.288074,-0.204341,0.482020,0.238155,0.017642,0.207254,0.209718,-0.226507,-0.056620,-0.086757,-0.257641,0.084717,0.308744,-0.094258,0.067491,0.106857,0.109821,-0.118594,-0.490951,0.133923,0.022821,0.154537,-0.865647,-0.027228,0.235931,-0.105755,0.337815,-0.343694,0.339173,0.045900,0.054585,0.401566,-0.113518,0.336947,-0.677172,0.157298,0.665541,-0.142749,0.103248,0.163893,-0.017594,0.004396,0.474376,-0.129341,-0.509156,0.177201,-0.120633,-0.277378,-0.448097,0.044044,-0.433212,0.299156,-0.018505,-0.176925,0.326987,-0.169424,-0.170433,-0.597072,-0.210638,-0.139957,-0.281488,0.226328,-0.089231,-0.479068,0.373541,-0.278147,0.154720,0.493738,0.552611,-0.509372,0.943419,-0.282472,-0.100494,-0.134738,0.005487,0.327463,-0.010131,0.523219,-0.200017,-0.162143,0.118669,0.074938,-0.367674,0.404052', '2080130', '30206431', '3055049', '1306505');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26596486', '名侦探柯南：纯黑的恶梦', '动画', '漆黑的夜晚，一名间谍悄然潜入日本警方某机构，盗走了记载着各国谍报机构重要数据的绝密文件的绝密数据。日本警方和FBI探员赤井秀一（池田秀一 配音）旋即与间谍展开追逐。最后，逃亡者的车辆坠落悬崖。第二天，柯南（高山南 配音）和伙伴们来到东都水族馆观光，结果发现一名受伤的美丽女子（天海佑希 配音）。该女子处于失忆状态，身上的手机也破损无法使用。柯南等人答应要帮她恢复记忆，当他们七嘴八舌之际，藏在暗处的黑衣组织成员贝尔摩德（小山茉美 配音）冷冷地注视着这一切。在相处过程中，女子非凡的身手和奇怪的言行举止让灰原哀（林原惠美 配音）对其真实身份产生怀疑。刚刚还一派祥和的水族馆，沉浸在快乐之中的人们，根本会想到随着那名神秘女子技艺的恢复，自己马上就要被卷入黑暗组织的杀戮和混乱之中……©豆瓣', '高山南', '静野孔文', 6.1, 75700, 'tt4954660', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2398143099.jpg', 4.3, 18.8, 49.2, 21.5, 6.3, '0.247416,0.062311,-0.726286,0.547036,0.079630,0.035249,0.740227,-0.033731,-0.536950,-0.459262,0.330062,0.638966,-0.178771,0.041861,0.343301,0.014503,-0.661335,-0.801668,-0.474929,-0.096844,-0.382605,-0.372301,-0.289024,-0.157585,-0.124153,-0.380679,0.520485,0.145784,-0.385956,0.571481,0.009429,0.309918,-0.597206,0.428676,-0.017751,-0.236008,0.215791,-0.283304,-0.175714,0.223065,-0.088096,-0.279061,-0.129267,0.107860,-0.117716,0.198711,0.787581,-0.184137,-0.144689,0.025858,0.146900,-0.198506,-0.140520,0.091274,0.531981,0.010511,0.100986,0.160917,-0.136749,-0.002623,-0.193663,-0.079917,-0.776713,-0.041828,0.018383,0.435914,-0.159772,0.176976,-0.035388,0.032667,0.180264,-0.270845,0.251709,0.154377,0.211251,0.358774,-0.015568,0.107783,-0.344766,0.122518,0.282412,0.042823,-0.360289,0.324818,-0.117009,-0.468784,-0.385062,-0.030832,-0.227579,-0.072795,0.358247,0.218026,-0.112284,0.253503,-0.511907,0.082317,0.013793,-0.413406,-0.227190,-0.243592,-0.480288,-0.629501,-0.178417,-0.236932,-0.351051,0.089348,-0.117391,-0.016697,0.722818,-0.905047,0.157581,0.578517,0.075830,-0.357751,0.424128,-0.133347,0.052031,-0.189183,-0.317945,0.070743,0.211142,0.444448,0.042277,0.199686,-0.225119,-0.169315,-0.522083,0.027415', '25928048', '20274039', '3811356', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26598021', '航海王之黄金城', '剧情', '路飞（田中真弓 配音）和他的草帽海贼团在新世界展开全新的冒险，这一次他们来到了世界上最大的娱乐城——古兰·泰佐罗。这里云集了世界各地的富豪、海盗、海军，同时也是政府承认的独立国家和非武装地带，是世界政府不可轻易染指的“绝对圣域”。被称作“黄金帝”的吉尔德·泰佐罗（山路和弘 配音）是绝对圣域的至高领导，据说吃过金金果实的他拥有常人难以想象的神奇能力，此时有条不紊地实施着雄霸天下的计划。另一方面，原打算狠捞一笔的路飞一伙落入了吉尔德·泰佐罗的金钱陷阱，他们进而被卷入了裹挟着奉献给天龙人的“天上金”以及对抗政府的革命军的巨大漩涡之中。新的争斗在所难免……本片是经典漫画作品《海贼王》第13部剧场版动画。©豆瓣', '田中真弓', '宮元宏彰', 7.6, 57861, 'tt5251328', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2392493260.jpg', 0.7, 3.9, 32.8, 38.9, 23.7, '0.033918,0.226436,-0.959825,0.778282,0.151020,-0.061223,0.373097,0.185665,-0.441528,0.223890,0.139593,0.693423,0.019839,-0.128941,0.243704,-0.002248,-0.236395,-0.539226,-0.460601,-0.180261,-0.338497,-0.261868,-0.440341,-0.224792,-0.282035,-0.237043,0.657369,0.250138,-0.454590,0.116876,0.393065,0.393579,-0.129041,0.275822,-0.178168,0.027522,0.167612,-0.106821,-0.275797,0.196155,-0.187683,-0.108231,-0.057002,0.328792,0.028342,0.172448,0.642388,-0.520359,0.108997,-0.245962,0.338710,-0.502701,-0.149546,-0.225715,0.571436,-0.099680,-0.100635,0.356874,0.145740,0.012482,0.001552,-0.183655,-0.955698,-0.195910,0.122849,0.042721,-0.394879,0.383210,0.082551,-0.088547,0.110856,-0.127178,0.108470,0.315805,0.289093,0.073687,0.055773,0.160513,-0.611854,0.258445,0.595130,0.128632,-0.373525,-0.044993,-0.263115,-0.427866,-0.369746,-0.463242,-0.250282,-0.171174,0.558110,-0.094817,0.034285,0.347158,-0.695611,0.063040,-0.316096,-0.361935,-0.053770,-0.242842,-0.110950,-0.633871,-0.011837,-0.444026,-0.130742,0.176444,0.191708,-0.120028,0.780869,-0.539053,0.006543,0.651283,0.391028,-0.250859,0.706943,-0.253940,0.032411,-0.263185,-0.306159,0.132068,0.141944,0.464679,0.246494,0.275364,0.052970,-0.171779,-0.178364,0.502362', '25928048', '25932086', '30163500', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26599076', '四月是你的谎言', '剧情', '原作曾在2011年5月至2015年3月在《月刊少年MAGAJIN》上连载，单行本全11卷累计发行部数超过400万册的人气作品，曾获得了第37届讲谈社漫画奖大奖。2014年漫画被改编成电视动画，讲述因母亲的去世而开始无法弹钢琴的天才钢琴少年有马公生遇见了任性奔放的小提琴手宫园薰，钢琴与母亲的回忆涌现，同时宫园薰身上的秘密也让二人的青春生活发生了变化。', '广濑铃', '新城毅彦', 6.3, 13509, 'tt5672048', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2366688354.jpg', 3.3, 17, 49.8, 21.6, 8.3, '0.061923,-0.179230,-0.418935,0.423600,0.307030,-0.319430,0.380080,-0.062069,-0.700821,-0.239289,0.119634,0.313457,-0.669849,0.278257,0.589621,-0.323067,0.001117,-1.044044,0.043678,-0.540367,0.015328,-0.297052,0.222653,0.240843,-0.207411,-0.555485,0.868733,-0.167951,0.058018,0.441771,0.169701,0.052641,-0.205220,-0.120980,-0.098196,0.222197,-0.055866,0.153990,-0.102139,0.157660,-0.225074,-0.592900,-0.301763,-0.429769,0.004368,-0.053239,1.128482,-0.102756,-0.091837,0.141102,0.997123,0.159846,-0.391894,-0.552501,0.549011,0.565152,0.202893,0.409540,-0.006923,-0.095724,-0.386933,-0.519711,-0.344445,0.096232,0.005885,0.191038,-0.431799,0.292296,-0.275320,0.458193,0.105927,0.023480,-0.076436,-0.035129,0.349632,0.534748,0.090001,0.331647,-0.303850,0.829498,0.220507,-0.017478,-0.409105,0.391913,-0.005620,-0.213380,-0.519728,-0.607502,-0.519036,0.656561,-0.009853,0.305905,-0.160078,0.474506,-0.528883,0.039899,0.009347,-0.603040,0.508406,0.111592,-0.528359,-0.557349,-0.522893,-0.106349,0.120030,-0.334279,0.165435,-0.708668,0.987512,-0.650442,0.493039,0.181931,0.191096,-0.214827,0.776639,-0.087678,-0.299434,0.221493,0.045982,0.402476,-0.365465,-0.004770,0.109358,0.155070,-0.074872,0.017853,-0.273157,0.627874', '27621192', '4268598', '5920220', '27167055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26599156', '为什么是他？', '喜剧', '内德（布莱恩·科兰斯顿 Bryan Cranston 饰）是一位传统意义上的老父亲，将女儿斯蒂芬妮（佐伊·达奇 Zoey Deutch 饰）视为人生的意义，掌中的瑰宝。假期来临，内德兴致勃勃的携全家上下前往女儿所在的斯坦福，想要重温一下久违的阖家欢乐的时光，然而让内德没有想到的是，女儿的男友莱尔德（詹姆斯·弗兰科 James Franco 饰）从中插了一脚，彻彻底底的毁掉了这次假期旅行。莱尔德是一名硅谷科技新贵，整日里和网络与最新的科技设备打着交道，他整天捣鼓的一切对于老派而又保守的内德来说无异于天方夜谭，而莱尔德的不善言辞与古古怪怪亦加剧了他和准岳父之间关系的裂痕。©豆瓣', '佐伊·达奇', '约翰·汉博格', 6.5, 12166, 'tt4501244', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2363682612.jpg', 2.3, 13.4, 50.6, 25.6, 8.1, '0.373080,0.058864,-0.656056,0.787081,0.338631,-0.494119,0.621809,0.038141,-0.617736,-0.532387,-0.269675,0.438769,-0.355586,0.267751,0.513735,0.217706,-0.372703,-0.745133,-0.020002,-0.299977,-0.323351,-0.575912,-0.509552,-0.331383,-0.114832,-0.336992,0.459907,-0.042773,-0.187810,0.334022,0.236845,0.665221,0.180030,0.242167,-0.192173,-0.015578,0.060670,-0.076766,-0.449447,0.156923,0.215921,0.049996,-0.063082,0.125895,0.054469,0.340420,0.538591,-0.424791,0.234647,-0.215556,0.152650,-0.209059,-0.168837,0.143006,0.118855,0.003696,0.134326,0.388318,-0.158923,0.076252,0.445573,-0.459328,-0.720684,-0.221151,-0.020680,0.285036,-0.459711,0.650687,-0.270464,-0.161106,-0.185876,-0.146507,0.277329,0.331739,0.154610,0.551358,-0.060682,0.151620,-0.286811,-0.075145,0.510047,0.167673,-0.311214,0.497175,-0.160492,-0.127461,-0.102297,-0.124340,-0.463471,-0.184860,0.113485,0.101273,0.134489,0.540635,-0.649901,0.000950,-0.442716,-0.118672,0.168852,-0.323463,-0.069329,-0.629444,-0.054609,-0.607026,-0.351404,0.078697,0.161153,-0.213752,0.467997,-0.678083,0.050646,0.200927,0.147504,-0.235477,0.734733,-0.075018,0.322531,-0.387946,-0.132786,-0.070877,0.275033,0.146093,0.089372,0.318723,-0.026124,-0.394330,-0.079527,0.668067', '3006892', '1303449', '2998373', '1301689');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26599752', '蝙蝠侠：血脉恩仇', '动作', '布鲁斯·韦恩失踪了。夜翼和罗宾替他在哥谭市巡逻的时候，阿尔弗雷德为他打掩护。一位新成员，蝙蝠女侠，在调查蝙蝠侠的失踪事件。', '杰森·奥玛拉', '杰伊·欧力瓦', 7.1, 6974, 'tt4870838', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2324554917.jpg', 0.7, 4.7, 44.7, 36.4, 13.5, '0.113779,-0.591305,-0.450918,0.127858,-0.325033,-0.567940,0.652660,-0.077476,-0.448860,-0.594565,0.533165,1.005677,-0.099918,-0.096420,0.518741,0.047186,-0.709333,-0.856372,0.075096,-0.268578,-0.188403,-0.409418,-0.409193,-0.578141,0.389517,-0.525651,0.275183,-0.103882,-0.012481,0.412544,0.315881,0.485993,-0.511285,0.387735,-0.232016,0.221277,0.971477,-0.017096,0.107378,0.388458,0.018291,-0.277255,-0.071879,0.141796,0.202560,0.364412,0.498193,-0.260092,0.008593,-0.050933,-0.036134,-0.448793,0.414869,-0.165418,0.848532,-0.274370,0.043091,0.403338,-0.025953,-0.345046,-0.474245,-0.047939,-0.685769,-0.028308,-0.060223,0.382663,-0.888540,0.486899,-0.576972,0.087476,0.556484,-0.427726,0.319136,0.513488,0.066507,-0.050532,-0.074322,0.103172,-0.523052,0.322238,0.396479,0.075658,0.321453,-0.228764,0.251252,-0.304606,-0.480793,0.438934,-0.484172,-0.154773,0.606441,-0.885315,-0.231877,0.652063,-0.671932,-0.445573,-0.427617,-0.159421,-0.578430,-0.080025,-0.171135,-0.854946,-0.030167,-0.132477,0.007008,-0.120731,-0.155884,-0.241011,0.518510,-0.992484,0.432862,0.711520,0.068037,-0.643736,0.477729,0.255764,0.185618,-0.464457,0.041297,-0.087042,0.456427,0.407358,0.491477,0.353248,0.121581,-0.299804,-0.524395,-0.112596', '25833539', '1309069', '25723905', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26600660', '分裂', '悬疑', '凯西（安雅·泰勒-乔伊 Anya Taylor-Joy 饰）是一个显得和同龄人格格不入的怪女孩，某日，她和同学克莱尔（海莉·路·理查森 Haley Lu Richardson 饰）、玛西亚（杰西卡·苏拉 Jessica Sula 饰）一起准备坐车回家，哪知道遭到了一神秘男子的袭击和绑架，三人被囚禁在灰暗阴冷的地下室中，面临着未知的凶险命运。绑架三个女孩的，是一个名叫凯文（詹姆斯·麦卡沃伊 James McAvoy 饰）的男人，实际上，他是一位多重人格患者，支配着他的身体的人格，竟有23种之多。弗莱彻（贝蒂·巴克利 Betty Buckley 饰）是凯文的主治医生，她发现，凯文体内的人格之间产生了分歧，更糟糕的是，第24种人格正在慢慢形成，这个人格强壮、邪恶、残忍，一旦他获得了凯文身体的主导权，不仅三个女孩要遭殃，就连凯文本身都将性命不保。©豆瓣', '詹姆斯·麦卡沃伊', 'M·奈特·沙马兰', 7.4, 121859, 'tt4972582', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2412064264.jpg', 0.6, 4, 34.5, 44.4, 16.4, '0.338794,-0.025757,-0.687464,0.493102,-0.309347,-0.243584,1.076729,0.214432,-0.328966,-0.114376,0.331472,0.718861,-0.210361,0.329744,0.294328,0.311679,-0.151795,-0.567950,-0.209573,0.023994,-0.608878,-0.624194,-0.271881,-0.195384,0.114109,-0.526897,0.361369,-0.114467,-0.318409,0.315493,0.284477,0.391325,-0.087860,0.481492,0.029373,0.191217,0.228781,-0.450711,-0.061960,0.205512,0.177608,0.002875,0.015480,0.366063,-0.208062,0.419788,0.674851,-0.278966,-0.147368,-0.183284,0.556475,-0.106316,-0.292194,0.111762,0.312796,-0.168253,0.046516,0.156041,-0.086711,0.109038,0.379389,0.014376,-0.657120,0.088107,0.059836,0.433805,-0.400274,0.332516,-0.000383,-0.149217,0.284683,-0.314489,0.028632,0.148665,0.189279,0.378300,0.018755,-0.157738,-0.459541,-0.177803,0.537041,0.090760,-0.337590,0.252263,-0.513532,-0.266851,-0.150896,-0.060134,-0.589565,-0.034427,0.471795,-0.020162,-0.066864,0.295641,-0.525241,0.036852,-0.197790,0.034467,-0.297183,-0.384678,-0.050567,-0.358219,-0.209258,-0.501249,-0.368774,0.192237,-0.072017,-0.189876,0.711044,-0.752106,0.310879,0.727623,0.490119,-0.336045,0.353663,0.129978,0.092259,-0.184930,-0.098713,0.234309,0.002853,0.053224,0.135851,0.581201,-0.014919,0.174766,-0.360001,0.574043', '1292062', '3005387'