INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26600786', '希斯特斯兄弟', '犯罪', '艾利（约翰·C·赖利 John C. Reilly 饰）和查理（华金·菲尼克斯 Joaquin Phoenix 饰）是一对杀手兄弟，某日，他们接到了一项任务，去暗杀一名淘金者。于是，两个男人火速从俄勒冈前往旧金山，一路上，两个人遇到的麻烦可不少，但他们凭借着智慧和勇气将它们一一化解，最终安全的抵达了目的地。当他们见到了他们的目标时才发现，这个名叫沃姆（里兹·阿迈德 Riz Ahmed 饰）的男人是一名化学家，他发明出了一种神奇的药剂，可以帮助人们更快速的寻找到金矿的所在。两利相权取其重，艾利和查理当即决定辞去杀手这份工作，转而成为来钱更快的淘金汉，哪知道他们为这个鲁莽的决定付出了沉重的代价。©豆瓣', '约翰·C·赖利', '雅克·欧迪亚', 7.7, 15623, 'tt4971344', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2532760814.jpg', 0.4, 2.2, 25, 54.8, 17.5, '0.264839,-0.089501,-0.584136,0.570652,-0.399657,-0.417172,0.490214,0.110672,-0.424981,-0.365141,0.226925,0.914963,0.212604,-0.218874,0.397273,-0.086672,-0.248913,-0.444880,0.281996,-0.322140,-0.385597,-0.510616,-0.182584,-0.363606,-0.082138,-0.182906,0.355945,0.188756,-0.030208,0.560247,0.462043,0.341381,0.115022,0.583452,-0.100275,-0.029608,0.282275,-0.419758,-0.166071,0.543198,0.061009,0.008796,-0.208339,0.297315,-0.094815,0.322538,0.567097,-0.223429,-0.259429,-0.034418,0.244124,-0.322344,0.020524,0.077607,0.228329,-0.026311,-0.002514,-0.028382,-0.412110,0.127802,0.028210,-0.052636,-0.898747,-0.117028,0.048120,0.095167,-0.743097,0.080238,-0.203670,-0.125344,0.137793,-0.609258,0.190427,0.422582,0.098786,0.148504,-0.281613,-0.206231,-0.555599,-0.041949,0.895169,-0.207200,0.140847,0.259634,0.135913,-0.591063,-0.078236,-0.068719,-0.268955,0.106589,0.519840,0.175991,-0.050635,0.004958,-0.792280,-0.127956,-0.441785,-0.240327,-0.036414,-0.476973,0.172346,-0.527692,-0.010791,-0.135084,-0.209286,0.226061,0.025255,-0.202952,0.874727,-0.639412,0.009254,0.650921,0.203856,-0.564963,0.562538,-0.191572,0.357807,-0.294044,-0.045574,0.044506,0.308659,0.433958,-0.006736,0.422711,0.200128,-0.230803,-0.223110,0.303462', '30163500', '26678784', '1793491', '30162520');
