INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26602933', '绑架者', '动作', '重案组警察林薇（白百何 饰）的女儿突然失踪，唯一嫌疑人杨念（黄立行 饰）却在案发当夜横遭车祸并失去记忆。在追踪线索和回忆的逃亡路上，杨念不断遭人暗杀，一心找回女儿的林薇也不惜代价对他步步紧追，重案组组长陆然（明道 饰）在关键时刻对林薇施以援手。真相一层层剥开……', '白百何', '徐静蕾', 4.8, 34637, 'tt4823122', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2445601403.jpg', 15.8, 39.2, 35.9, 7.4, 1.8, '-0.313271,-0.171984,-0.530496,0.319718,0.054061,-0.115944,0.892192,0.075839,-0.505106,-0.408613,0.569692,0.644978,-0.107510,0.071861,0.136127,-0.108161,-0.526896,-0.639973,0.439347,0.097676,-0.287116,-0.274954,-0.024210,-0.233735,0.257031,0.100542,0.706195,0.350380,-0.186655,0.400470,0.256137,0.369536,-0.675459,0.541856,-0.161312,0.385723,0.051068,-0.074101,-0.043999,-0.207360,0.058830,-0.789669,-0.283892,0.208505,-0.044754,0.530229,0.801530,-0.119337,-0.078221,0.000299,0.169787,-0.746102,0.028483,-0.274058,0.440052,0.048498,0.001084,0.439676,-0.262081,-0.006315,0.038888,0.026819,-0.688685,-0.048464,0.333998,0.405523,-0.348145,0.137651,-0.511459,0.258729,0.370621,-0.296508,0.201587,0.478483,0.086463,-0.135583,-0.462836,-0.142238,-0.432213,0.149408,0.264449,-0.056138,0.376580,0.331671,0.160423,-0.363445,-0.307578,0.238209,-0.121965,-0.023807,0.446592,0.152752,-0.234086,0.078990,0.014428,-0.170359,-0.036350,0.054142,-0.168284,-0.440476,-0.050730,-0.444217,-0.109854,-0.041414,-0.470670,0.162469,-0.252532,-0.269936,0.181842,-0.412141,0.236971,0.509813,0.095578,-0.670445,0.047584,0.128364,-0.051540,-0.727859,-0.053546,0.473286,0.376906,0.501673,0.264718,0.064826,-0.274700,-0.043130,-0.281204,-0.023404', '4280770', '26816090', '4903581', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26603666', '妈妈咪鸭', '喜剧', '小黄鸭大电影《妈妈咪鸭》讲述了雁群往南方迁徙的途中，“最棒飞行家”大鹏桀骜不驯爱捣乱，和他的女友晶晶调情时不慎撞散了一群赶路的小鸭子。不服管教的大鹏决定单飞，不得已和两只落单的小鸭子淘淘、憇憇组成了“临时父子档”，踏上了一路乌龙的寻亲和南迁之旅。他们经历了一连串惊险、刺激又有趣的冒险。划过壮美的梯田，爬过冷峻的山脉，遇上好心收留他们的母鸡和妻管严公鸡、搭乘春运卡车的猪群、半瓶子中医技能的松鼠。路途中要时刻抵御想吃掉他们的恶猫，还险些成为“盘中烤鸭”。大鹏与淘淘姐弟两的命运紧紧关联，孤傲的大鹏也逐渐学会了责任与耐心。最后，焕然一新的大鹏得到了女友晶晶的原谅，和两只小鸭子组成了爱意满满的小家庭。', '赵路', '赵锐', 7, 33900, 'tt4940416', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2515018270.jpg', 0.9, 6.8, 43, 38.5, 10.8, '0.377028,-0.270234,-0.543805,0.460942,0.117124,-0.228988,0.484362,0.303659,-0.134949,0.386601,0.312509,0.705296,-0.046819,0.089801,0.098568,-0.169284,-0.024324,-0.541497,0.086150,0.203952,0.105042,-0.246452,-0.263413,0.034785,0.325405,-0.138808,0.426347,-0.142349,-0.035287,0.830826,0.048523,-0.160015,-0.410097,0.168065,-0.275360,0.319567,-0.003373,0.127304,-0.077888,0.025105,-0.133642,0.108232,-0.009246,-0.066473,-0.023263,0.286496,0.851742,-0.410458,-0.292001,-0.398099,-0.051873,-0.383739,-0.052537,0.036912,0.279277,0.101273,0.438836,0.124147,0.084199,0.096910,0.012481,-0.019566,-0.439540,0.040017,-0.115153,0.044060,-0.688530,0.418499,0.146452,0.122791,0.452357,-0.364756,0.109872,0.250237,-0.055724,0.523763,-0.097085,0.227932,-0.513511,0.113434,0.461386,-0.167230,-0.016799,0.225489,-0.004957,-0.208024,0.295278,-0.324148,-0.223202,-0.148138,0.531506,0.064006,-0.528695,0.280131,-0.901748,0.164372,-0.241203,-0.021526,-0.177522,-0.403600,-0.149448,-0.313858,0.139081,-0.487040,-0.194405,0.127331,0.135968,-0.011404,0.578279,-0.562691,0.169052,0.435841,0.240411,-0.164662,0.606026,-0.070283,0.014896,-0.103253,0.226695,-0.253802,-0.246318,0.354038,0.443265,0.433397,-0.048098,-0.055695,-0.439320,0.277848', '25785314', '35256235', '1309194', '3155839');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26605028', '幸福路上', '动画', '小琪 (桂綸鎂 聲演) 生於蔣介石逝世當天，成長過程正是台灣社會經歷最劇烈轉變的時期。 小琪六歲那年舉家搬到新北市幸福路，為了滿足父母期望，她力爭上游，但也許幸福本來就沒有捷徑。 她一步步走上當初沒預期的路，到美國工作、結婚，走到人生的瓶頸，因外婆去世，重返老家，回首童年過程中，慢慢思索自己走過的路：「長大了，我有成為理想中的大人嗎？」', '桂纶镁', '宋欣颖', 7.7, 5825, 'tt7543904', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2510158803.jpg', 0.9, 3.3, 27.8, 47.9, 20.1, '0.161468,-0.055956,-0.734630,0.304085,-0.125588,-0.840495,0.585310,0.017423,-0.197718,0.068444,0.298289,0.721497,0.555581,0.905775,0.425394,0.207367,-0.288997,-0.423338,0.368210,-0.157431,-0.687102,0.064840,-0.010918,0.130108,-0.434201,-0.173569,0.493793,0.452129,0.235803,0.595377,-0.327533,0.037249,-0.324758,0.356557,-0.204075,0.712443,-0.041938,0.465817,-0.381747,0.048338,0.065220,-0.473928,-0.463495,0.145911,0.166568,0.382245,0.621294,-0.016816,-0.276198,0.277724,0.447891,-0.442974,-0.177166,0.043422,0.233005,0.432080,-0.388316,0.145197,-0.646933,-0.114031,-0.299589,-0.365229,-0.107408,-0.246760,-0.321069,0.088914,-0.749221,0.279393,0.249043,-0.656432,0.795789,-0.678905,-0.009441,-0.040421,-0.303450,0.448921,-0.472124,0.102348,-0.375930,0.261549,0.787709,-0.346651,-0.130341,0.313829,-0.070750,-0.167077,0.277685,-0.253726,-0.515778,-0.017054,0.409158,0.191020,-0.240180,0.173611,-0.081844,0.176930,-0.172076,-0.174346,0.127180,-0.177318,-0.165696,0.052618,-0.072467,-0.506228,0.061690,0.310375,-0.036839,-0.774186,0.540075,-0.251826,0.402598,0.670266,0.164425,-0.798144,0.856043,-0.113461,0.329421,-0.256360,0.548257,0.577412,-0.574844,0.290536,0.069793,0.156975,-0.265748,0.441909,-0.667937,0.895375', '2080130', '1297606', '1292718', '1292207');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26605946', '毒。诫', '剧情', '六、七十年代的香港，警察贪污，黑道横行，正是陈华（刘青云饰）与喇叭（林家楝饰）、猫仔（张晋饰）及一班兄弟最风光的日子。陈华被视为「慈云山十三太保」之首，气焰高涨；还结识了一生至爱可柔（江一燕饰），共度人生最甜蜜的时光。可惜好景不常，陈华因私下贩毒而被帮会追杀，幸好在亦敌亦友的扫毒组组长哈雷（古天乐饰）帮助下，逃出生天，但却终究法网难逃。出狱后，遭逢父亲病逝及女友可柔失踪，无比自责的陈华，顿然觉悟前非，立志重新做人。他不但积极参与青少年戒毒工作，获得十大杰青荣誉；更把喇叭与猫仔拉回正途，又经常出手调停江湖纠纷，因而深受黑白两道所敬重。某次于日本出席戒毒讲座后，陈华与可柔在街头重遇。他一心再续前缘，但又能否轻易为自己的感情拆弹？', '刘青云', '刘国昌', 4.9, 21607, 'tt6900380', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2457738034.jpg', 14, 38.6, 36.6, 7.6, 3.2, '-0.251717,-0.079792,-0.534597,0.475391,0.227921,-0.467402,0.345517,0.097468,-0.535105,-0.236355,0.126214,0.478330,-0.023616,0.249636,0.205971,-0.515830,0.038660,-0.623287,0.221925,0.053280,0.125763,0.008995,-0.015553,0.202626,-0.295925,-0.158798,0.645780,0.172947,0.008189,0.654525,0.239019,0.277643,-0.218719,0.321694,-0.207080,-0.131580,0.041018,0.314116,-0.595940,-0.258317,-0.171383,-0.382937,-0.126051,0.166052,-0.047447,0.025839,0.552494,-0.128853,-0.146432,-0.316582,0.282328,-0.310131,-0.159120,-0.001868,0.497805,0.149344,0.294199,0.601648,-0.094905,0.033505,0.120878,0.048124,-0.619902,0.076816,-0.011595,-0.112404,-0.374182,0.290367,-0.233547,0.009633,-0.138696,-0.016942,0.079447,0.299494,0.265274,0.082711,-0.316119,0.065149,-0.411220,0.293513,0.706049,-0.145032,-0.028918,0.148952,0.155247,-0.444772,0.395681,-0.417987,-0.213486,-0.116459,0.335264,-0.273962,-0.139108,0.391636,-0.342690,-0.124566,-0.244444,0.071856,0.101257,-0.285513,0.080726,-0.490965,-0.098053,-0.150871,-0.345022,-0.016095,0.512404,-0.460780,0.658197,-0.759778,0.227816,0.294828,0.023731,-0.707921,0.420219,0.292319,0.407784,-0.061779,-0.305068,0.379498,0.175299,0.231224,-0.142581,-0.123174,-0.382089,-0.266057,-0.179560,0.133618', '1293265', '35030151', '30345227', '3230460');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26605967', '狼少女与黑王子', '爱情', '平凡女孩筱原绘里香（二阶堂富美 饰）在升入高中后，经常与时尚的朋友们凑到一起聊些关于男朋友的话题。虽然夸夸其谈，但是绘里香却从来没交过男友。为了圆谎，她只得拜托好友三田亚由美（门胁麦 饰）帮忙。为了打消朋友们的疑虑，绘里香在大街上偷拍了某位帅哥的照片，并谎称是自己的男友。意想不到的是，这个帅哥居然正是绘里香所在学校的头号帅哥佐田恭也（山崎贤人 饰）！为了将谎继续编下去，她只能哀求恭也假扮男友。幸运的是恭也居然一口答应了，然而看似温柔阳光的恭也，实则是个促狭腹黑的大男孩。他提议让绘里香变成他的忠犬，以作为假冒男友的报酬。已是骑虎难下的女孩，只能违心地向恭也摇尾乞怜……本片改编自八田鲇子于2011—2016期间在《別冊マーガレット》上连载的同名漫画改编。©豆瓣', '二阶堂富美', '广木隆一', 6.3, 24472, 'tt5224834', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2321440840.jpg', 3.1, 15.9, 51.7, 21, 8.4, '0.295040,0.008998,-0.360921,0.711133,-0.284732,-0.209710,0.416778,0.266811,-0.186810,-0.274235,0.162631,0.670647,-0.245849,0.555047,0.482481,0.246296,0.051287,-0.694436,0.108409,-0.253797,-0.035023,-0.465245,-0.205614,-0.014656,-0.291143,-0.136619,0.563416,-0.177023,-0.112172,0.215445,0.870607,0.145892,-0.113853,0.483263,-0.172626,0.042448,-0.113977,0.163986,-0.115135,0.038060,-0.075766,-0.421503,-0.083425,-0.010497,0.311456,0.345204,0.533399,-0.224458,-0.293302,0.144388,0.283558,-0.247026,0.021491,0.062247,0.443411,-0.246072,0.493408,0.099670,0.026081,0.054786,0.131513,-0.001964,-0.643825,0.184165,0.107661,0.056613,-0.360415,0.570336,-0.064630,-0.185033,0.178580,-0.164144,0.046253,0.070776,0.115480,0.322839,-0.081722,0.335193,-0.098085,0.135523,0.152968,0.612550,0.002172,0.575486,-0.288374,-0.181127,-0.017863,-0.181935,-0.356814,0.136489,-0.115845,-0.094850,-0.197199,-0.139443,-0.601555,-0.289700,-0.119772,0.130521,0.344463,-0.354422,-0.093071,-0.438773,0.209965,-0.369423,-0.199097,-0.048206,0.286286,-0.444905,0.852880,-0.782990,-0.220750,0.658687,0.133807,-0.490441,0.474530,0.383398,-0.340776,-0.201896,-0.324482,0.210767,0.126095,0.166231,0.249312,0.421837,-0.058281,-0.354826,-0.382452,0.174238', '4301278', '27602116', '1418179', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26606242', '冈仁波齐', '剧情', '普拉村村民尼玛扎堆在父亲去世后决定完成父亲的遗愿，带着叔叔去拉萨和神山冈仁波齐朝圣。时正马年，正好是神山冈仁波齐百年一遇的本命年，小村里很多人都希望加入尼玛扎堆的朝圣队伍。这支队伍里有即将临盆的孕妇、家徒四壁的屠夫、自幼残疾的少年，每个人都有着不同的故事也怀揣着各自的希望。为了去冈仁波齐，这支十一人的队伍踏上了历时一年，长达2000多里的朝圣之路......', '尼玛扎堆', '张杨', 7.7, 137674, 'tt4957446', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2462387248.jpg', 1.3, 3.5, 25.7, 45.6, 23.8, '-0.061848,-0.302900,-0.699542,0.340115,0.034067,-0.393971,0.335565,0.083517,-0.425480,-0.079090,0.488662,0.812872,0.116011,0.318286,0.507894,-0.133274,-0.320897,-0.347873,-0.329840,-0.548597,-0.323288,-0.065101,0.088778,-0.010445,-0.062951,-0.381771,0.299693,0.233184,0.270228,0.566857,0.150620,0.142463,-0.205038,0.094420,-0.356087,0.263040,-0.006853,0.084681,-0.218942,-0.052838,-0.246819,0.224191,-0.434437,-0.012698,0.014571,0.408760,0.709558,-0.545386,0.029163,-0.098318,0.012730,-0.273118,-0.190912,0.018187,0.452269,-0.048080,0.234044,0.368439,0.095831,-0.111585,-0.311775,-0.341105,-0.669058,-0.100045,0.262448,0.224359,-0.793204,0.561218,0.097042,-0.122064,0.284576,-0.364499,0.292381,0.480761,-0.050290,0.580601,-0.165867,-0.390745,-0.536867,0.147670,0.683106,-0.193330,-0.140521,-0.013884,-0.338539,-0.430398,-0.059119,-0.148903,-0.452186,0.116948,0.159789,-0.219639,-0.219101,0.095002,-0.544723,0.276996,-0.077865,-0.245875,0.074724,-0.262944,-0.025849,-0.614460,0.565863,-0.322492,-0.139266,0.325894,0.238985,0.027978,0.852056,-0.531587,0.654342,0.558706,0.475620,-0.308361,0.796056,0.001373,0.146417,-0.481800,-0.123445,0.062623,-0.105540,0.605044,0.121318,0.284692,-0.469212,-0.152093,-0.354231,0.534147', '1308609', '3718457', '1292001', '25731805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26606743', '嫌疑人X的献身', '剧情', '在刑警学院任职的物理天才唐川（王凯 饰）与中学教师石泓（张鲁一 饰）年少相识，因彼此对数学的共同兴趣而惺惺相惜，多年后唐川在调查一桩杀人案时， 身为石泓邻居的陈婧（林心如 饰）被列入警方的“嫌疑人”之中，石泓与唐川因此再度重逢，而唐川却在调查中发现了更大的秘密……被迫站在对立面的唐川、石泓由此展开了一场高智商对决，一步步推动故事走向既震撼人心又令人扼腕的结局。', '王凯', '苏有朋', 6.3, 283776, 'tt3401392', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2448676053.jpg', 2.4, 13.9, 54.6, 23.7, 5.4, '0.490830,-0.150436,-0.608884,0.576912,0.209738,-0.242054,0.610816,0.060627,-0.791227,-0.157159,0.288561,0.709305,-0.500943,0.293401,0.190746,-0.542610,0.043502,-0.828479,0.025256,-0.242641,-0.165839,-0.439227,-0.284489,-0.134540,-0.053450,-0.142509,0.704858,0.181771,-0.391929,0.655787,0.408322,0.260086,-0.569137,0.360487,0.223282,-0.214881,0.326169,0.496086,-0.390392,0.282112,-0.187531,-0.454299,-0.443582,0.015032,-0.307684,0.365432,0.543731,-0.303169,-0.354625,-0.171421,0.376453,-0.415756,-0.132142,0.237236,0.503072,0.197093,0.028920,0.495279,-0.307749,-0.165097,0.167203,0.048001,-0.534989,-0.048958,0.230702,0.262543,-0.433582,0.631350,-0.035513,-0.242184,0.029315,-0.277078,0.034719,0.517944,0.439531,0.205333,-0.108303,-0.158918,-0.101161,0.259181,0.599451,0.036292,-0.117623,0.257404,0.089668,-0.716624,-0.230992,-0.059070,-0.314186,-0.169862,0.263916,0.049662,0.071300,0.524940,-0.573818,-0.022860,-0.279858,0.255506,-0.137569,-0.388293,0.034506,-0.518341,-0.389631,-0.365870,-0.433408,0.317766,0.110440,-0.420036,0.659283,-0.743048,0.068470,0.388468,-0.027349,-0.259929,0.389522,0.253577,0.232365,-0.263348,-0.150187,0.183370,-0.002731,0.220339,0.013823,0.309108,-0.224097,-0.327389,-0.459675,0.253996', '35030151', '26615753', '3230460', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26607693', '敦刻尔克', '剧情', '故事改编自著名的二战军事事件“敦刻尔克大撤退”。二战初期，40万英法盟军被敌军围困于敦刻尔克的海滩之上，面对敌军步步逼近的绝境，形势万分危急。英国政府和海军发动大批船员，动员人民起来营救军队。英国士兵汤米（菲昂·怀特海德 Fionn Whitehead 饰）在逃离海滩的过程中相继结识吉布森与亚历克斯，同时民用船主道森先生（马克·里朗斯 Mark Rylance 饰）与儿子彼得、17岁少年乔治也离开英国，去往敦刻尔克拯救士兵。三人陆续搭救了海军（基里安·墨菲 Cillian Murphy 饰）、飞行员柯林斯及汤米一行人，而战斗机飞行员法瑞尔（汤姆·哈迪 Tom Hardy 饰）则在被敌人双面夹击的艰难情形下顽强战斗。影片的故事从陆、海、空三个角度讲述，在德国军队的包围下，每个人不得不为自己的命运背水一战，才有可能活着回家。©豆瓣', '菲恩·怀特海德', '克里斯托弗·诺兰', 8.4, 667717, 'tt5013056', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2494950714.jpg', 0.3, 1.2, 14, 45.7, 38.7, '-0.045435,-0.233300,-0.692609,0.553554,0.401967,-0.112928,0.564809,-0.086820,-0.423229,-0.084364,0.450899,0.663867,0.137908,-0.138910,0.480523,-0.164799,-0.611204,-0.674060,-0.233921,0.132260,-0.391077,-0.469261,-0.458526,-0.622460,0.062062,-0.289635,0.685001,0.436309,-0.191379,0.392347,0.116483,0.487041,-0.230582,0.371044,0.086678,0.101621,0.287089,-0.602487,-0.510816,0.228400,-0.467383,-0.215855,-0.306027,0.033962,0.088706,0.242603,0.817483,-0.397800,0.338087,0.004033,-0.126664,-0.312258,0.116080,0.118327,0.407522,-0.099633,0.045899,-0.031912,0.164027,0.025641,-0.134022,0.032384,-0.277503,0.122374,-0.132842,-0.002011,-0.436949,0.163646,-0.368878,0.413637,0.245625,-0.315610,-0.207454,0.515227,0.097316,0.185708,-0.118567,-0.044158,-0.619103,-0.034964,0.642694,-0.036973,-0.215006,-0.274397,-0.049545,-0.376565,-0.198603,-0.353465,-0.243870,-0.109950,0.541759,-0.272267,0.078504,0.355566,-0.451304,0.166663,-0.488998,-0.450977,-0.214438,-0.011505,-0.017966,-0.876999,0.227112,-0.206661,-0.231347,0.379269,0.035822,0.335121,0.842997,-0.228723,0.031391,0.433640,0.259243,-0.183670,0.447808,0.033032,0.185787,-0.112140,0.162655,0.453585,-0.073522,0.199634,0.168353,0.198562,-0.347993,-0.053887,-0.159140,0.239786', '21349734', '2159244', 