INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26607739', '极限挑战之皇家宝藏', '喜剧', '“极限男人帮”黄渤、孙红雷、黄磊、罗志祥、王迅、张艺兴在拍摄《极限挑战》时，意外被雷“劈”回到几百年前的大明朝，六人得到皇帝恩宠，却因为一个失误造成皇帝驾崩。六人跌跌撞撞穿越回现代后，却发现历史已经被改写，他们也变成了没有身份的“黑户”。为找回身份，他们被迫根据皇帝留下的“圣火令”寻找黄家宝藏，踏上玩命之旅。', '黄渤', '任静', 4.6, 44716, 'tt5465996', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2309603103.jpg', 30, 31.5, 23.5, 6.8, 8.3, '-0.194540,0.446787,-0.564301,0.551300,-0.012635,-0.202991,0.597814,-0.077735,-0.490405,-0.434682,0.399996,0.792260,-0.268307,-0.043564,0.206984,-0.354881,-0.213297,-0.410723,0.213963,-0.185532,-0.294911,-0.230744,-0.205707,-0.018877,-0.392607,-0.320919,0.882486,0.176181,-0.492202,0.320835,0.362205,0.036441,0.001287,0.443338,-0.168538,0.468747,0.100167,0.134743,-0.138997,0.445801,-0.098062,-0.550828,-0.072299,0.333205,-0.283174,0.229603,0.372019,-0.382998,-0.179345,-0.399378,0.576432,-0.228297,-0.539073,0.171610,0.398486,0.163273,-0.038027,0.175722,0.073561,0.082533,-0.170204,-0.054076,-0.775644,0.096523,-0.039411,0.075042,-0.488563,0.402577,-0.134252,-0.076075,-0.066768,-0.424011,0.377560,0.517850,0.525823,0.218030,-0.449481,0.177567,-0.443750,0.002073,0.838734,-0.148092,-0.189737,0.229901,0.182324,-0.442774,0.126090,-0.375307,0.069147,0.297695,0.136996,0.423022,-0.077837,0.226129,-0.086695,-0.081172,-0.562698,-0.276156,0.006049,-0.279483,-0.184488,-0.500176,-0.091265,-0.061498,-0.243268,0.098200,-0.089085,-0.481632,0.221666,-0.371856,0.386321,0.340455,0.411357,-0.747628,0.549108,-0.208063,0.071657,-0.511816,0.071544,0.377069,-0.015151,0.574235,0.070079,-0.219029,-0.411770,-0.299342,-0.311215,0.521344', '26678784', '25721544', '25828589', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26607969', '未择之路', '剧情', '无边的戈壁滩上，欠下高利贷的二勇（王学兵 饰）意外与来历不明的孩子尕娃（朱耕佑 饰）踏上了一段凶险的追妻之旅，笔直又狭长的公路上，二勇和尕娃与忧郁暴躁的女卡车司机小眉（马伊琍 饰）相遇，三个性格迥异的人因故临时结伴而行，在穿越戈壁的三天两夜里，三个孤独的人度过了一段恍若家人的时光。随着旅途的继续，他们邂逅的人和遭遇的事，使得每个人命运发生了重大改变，人的命，路的头，在苍茫天地之下都变得微不足道……©豆瓣', '王学兵', '唐高鹏', 6.7, 17282, 'tt9020130', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2533833822.jpg', 0.9, 8.6, 53.1, 31.6, 5.9, '0.261387,-0.249070,-0.689722,0.620661,0.111139,-0.232248,0.928099,0.074126,-0.558081,0.099279,0.266916,0.566399,-0.075700,-0.006372,0.521427,-0.183076,-0.330396,-0.626833,-0.013108,-0.001612,-0.385078,-0.326429,0.017423,-0.063771,0.202940,-0.388943,0.544442,0.345646,0.082626,0.753095,0.112669,0.044859,-0.537578,0.320455,-0.362723,0.337666,-0.205284,0.331530,-0.043578,-0.270881,-0.328793,-0.169940,-0.283318,-0.184351,-0.044088,0.296488,0.889156,-0.349494,-0.391213,-0.177677,0.208008,-0.188003,-0.277942,-0.049157,0.159313,0.026869,0.396319,0.477199,-0.161728,-0.180421,0.192809,-0.037322,-0.458914,0.243717,-0.040917,0.114087,-0.664590,0.522024,0.183231,-0.379785,0.149856,-0.482175,0.205008,0.321852,0.299411,0.476847,-0.122715,-0.276739,-0.400882,0.110842,1.005540,0.116177,-0.359619,0.109864,-0.196623,-0.257694,-0.257575,-0.048901,-0.510650,0.094875,0.464810,-0.135036,-0.247588,0.547933,-0.735208,0.440102,-0.031327,-0.165989,-0.292938,-0.522370,-0.323532,-0.377094,0.154639,-0.553738,-0.435511,0.605906,0.288747,-0.250922,0.477958,-0.422286,0.281978,0.421609,0.178694,-0.287939,0.907646,0.037614,0.386749,-0.315872,-0.023568,0.205453,-0.222723,0.390062,0.262192,0.466546,-0.611961,0.498346,-0.445694,0.440505', '26687241', '21619567', '3055049', '30209018');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26608800', '梅格雷的陷阱', '剧情', '故事发生在上世纪五十年代的巴黎，四名女性在蒙马特的街道上被人谋杀，案情看似毫无关联，但探长麦格雷却怀疑这四起案件为同一名连环杀手所为。麦格雷面临破案的巨大压力，于是他利用罪犯的虚荣心精心设计了一个抓捕计划。随着调查的深入，麦格雷将嫌疑人名单缩小到三人范围。最终的结果令人震惊。', '罗温·艾金森', '阿什利·皮尔斯', 7.4, 9618, 'tt5012394', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2413974312.jpg', 0.5, 3.1, 38.7, 43.5, 14.2, '0.520396,-0.015537,-0.778193,0.595267,0.093766,0.126411,1.079464,0.189254,-0.588311,-0.272227,0.613321,0.492287,-0.334602,-0.324218,0.487411,-0.263778,-0.429981,-0.819252,0.021830,-0.167580,-0.441362,-0.634521,-0.323806,-0.370006,-0.032987,-0.244493,0.653505,0.344485,-0.447389,0.063769,0.205001,0.472029,-0.336342,0.409161,-0.069166,-0.171608,0.486394,-0.173296,-0.188671,0.305719,-0.220548,-0.561147,-0.001041,0.258279,-0.449861,0.503918,0.878836,-0.222739,-0.360810,0.073112,0.657126,-0.344565,0.022535,0.117019,0.674746,0.297170,-0.031014,0.418198,-0.178062,-0.298087,0.122242,-0.241346,-0.927561,-0.003708,0.294501,0.381444,-0.432222,0.291936,-0.141463,0.082132,-0.082516,-0.130354,-0.014564,0.393983,0.371071,0.111718,-0.204548,0.045596,-0.570134,-0.166601,0.790881,-0.050234,-0.308700,-0.011225,-0.246724,-0.526507,-0.360459,-0.212470,0.034230,-0.033335,0.336232,0.082818,-0.340670,0.251101,-0.472855,-0.077717,-0.460167,-0.285486,-0.432568,-0.403530,-0.252225,-0.662330,-0.228342,-0.018556,-0.363996,0.119926,0.112122,-0.353019,0.511622,-0.495474,0.107232,0.858372,0.077963,-0.312577,0.581335,0.046670,0.168657,-0.196024,-0.324517,0.033627,0.185856,0.260208,0.040502,0.402349,-0.116267,-0.368670,-0.242677,0.357444', '25828589', '4023433', '2988294', '1298197');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26610229', '方形', '喜剧', '克里斯蒂安（克拉斯·邦 Claes Bang 饰）和妻子离婚后，带着小女儿（Lilianne Mardon 饰）开始了全新的生活。克里斯蒂安在一间艺术馆里担任策展人的职位，最近，他正在筹划一项名为“方形”的装置展览，希望宣扬一种人人平等互助的积极向上的理念。一场意外中，克里斯蒂安的手机被偷了，通过GPS定位，克里斯蒂安找到了偷手机的小偷所居住的公寓，深夜里，克里斯蒂安向该大楼的每一户居民家的门缝里塞进了一张指控书，哪知道这不经思考的举动，为他惹出了大麻烦。为了宣传展览，克里斯蒂安找来了传媒公关公司的代理人，哪知道这两个不靠谱的男人，很快就将这个展览搅成了一锅粥。祸不单行，克里斯蒂安和女记者安妮（伊丽莎白·莫斯 Elisabeth Moss 饰）之间的一段露水情缘让安妮对他展开了猛烈的攻势。©豆瓣', '克拉斯·邦', '鲁本·奥斯特伦德', 7.7, 41961, 'tt4995790', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2495377597.jpg', 1.1, 3.9, 24.5, 48.7, 21.8, '0.470711,0.089256,-0.537241,0.593228,0.029208,-0.095318,0.531373,0.295556,-0.405142,-0.207554,0.084848,0.694588,-0.261478,0.192961,0.298147,0.156083,-0.327068,-0.736059,-0.143096,-0.343837,-0.331765,-0.315322,-0.366805,-0.212420,0.030875,0.003954,0.201869,0.074476,-0.173568,0.190823,0.381442,0.114254,-0.110591,0.145072,-0.034901,0.090905,0.140138,0.025919,-0.160004,0.192041,0.050231,-0.175862,-0.075512,0.195702,0.139117,0.525716,0.621542,-0.102182,-0.056649,-0.125065,0.331485,-0.022759,0.040345,0.186104,0.199153,0.255039,0.216947,0.005028,-0.473439,-0.016403,0.310049,-0.178400,-0.795147,-0.046762,0.012425,0.163534,-0.553617,0.445255,-0.266929,-0.103437,0.091574,-0.232441,0.296530,0.361582,0.292696,0.559235,-0.025687,0.039801,-0.432028,0.104639,0.198841,-0.166850,-0.076247,0.373974,-0.169864,-0.165073,-0.024973,0.103587,-0.488828,-0.357502,0.522550,-0.078973,-0.042252,0.039099,-0.773978,0.052719,-0.160116,-0.223781,0.176826,-0.502556,-0.185718,-0.696725,-0.048017,-0.049158,-0.041373,0.131254,0.038905,-0.069593,0.586365,-0.668261,0.000682,0.556418,0.249209,-0.341529,0.630922,0.010896,0.233951,-0.186916,-0.011212,-0.205410,0.207563,0.505618,0.207618,0.503325,0.127639,-0.448986,-0.437874,0.329249', '25928048', '1308585', '3285642', '19965431');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26610786', '战犬瑞克斯', '剧情', '改编自真人真事，以伊拉克战争为背景，讲诉海军陆战队下士梅根·利维和她的军犬瑞克斯一起拯救了多人生命的故事。在经历生死与相互救赎后，一人一犬建立深厚情感的故事。 它在真实的背景下以一种特殊的方式升华了人与狗的情感。狗不再是宠物，而是以战友身份与人相处；它们不再生活在人类的庇护下，而是反过来，用自己的身躯保护人类。 该片以“军犬”这个新奇的角度还原伊拉克战争，首次全面展现军犬在战区排爆、救人的惊心动魄的画面，真实刻画了女兵梅根·利维与军犬瑞克斯在战场上紧张、勇猛的状态。', '凯特·玛拉', '加芙列拉·考珀斯维特', 6.8, 11588, 'tt4899370', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2520197352.jpg', 0.4, 7.1, 53.3, 31.1, 8.1, '0.211529,-0.118325,-0.550328,0.889111,-0.056741,0.063795,0.768401,-0.021077,-0.655593,0.112934,0.431235,0.685407,0.241300,-0.045210,0.180972,-0.335038,-0.567555,-0.685996,-0.102493,0.219562,-0.305740,-0.383254,-0.444382,-0.545716,-0.005415,-0.606364,0.971056,-0.180726,-0.429365,0.263612,-0.005451,0.076829,-0.256439,0.161707,-0.179658,-0.063992,-0.153780,0.091270,-0.592101,-0.096825,-0.083067,-0.168780,-0.274484,0.320800,-0.201480,0.069888,0.763152,-0.691325,-0.148267,-0.121629,0.333019,-0.138399,0.132314,-0.023466,0.014825,-0.088472,0.245062,0.100615,0.305902,0.194526,-0.023424,-0.052549,-1.072629,-0.365207,-0.127769,0.190902,-0.350249,0.584128,-0.198685,-0.002105,0.334431,-0.222358,-0.154795,0.293641,0.365217,0.394265,-0.326105,-0.221463,-0.360432,0.296751,0.635372,0.140032,-0.676749,0.392772,-0.615192,-0.525424,-0.403210,-0.453247,-0.355231,-0.224349,0.245443,0.083572,-0.320446,0.496609,-0.890531,0.044452,-0.046682,-0.095831,-0.123363,-0.503521,0.133491,-0.575157,-0.481190,-0.670352,-0.205759,-0.138712,0.157722,-0.336105,0.882087,-0.904119,0.041016,0.629642,0.154984,-0.341437,0.471203,0.056818,0.159208,-0.376126,0.003380,0.427450,-0.077362,0.214906,0.133439,0.347465,-0.019736,0.517710,-0.455226,0.641401', '26667010', '26759819', '1303542', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26611076', '溺水小刀', '剧情', '小有名气的15岁平面模特满月夏芽（小松菜奈 饰）不得不跟随父母回到老家，帮助年迈的爷爷打理旅店。美丽的女孩很快结识了新朋友，同时也认识了那个周身闪着白色光芒的长谷川航一朗（菅田将晖 饰）。阿航是当地神主一族的孩子，但是他无拘无束，经常干一些出格的事。他时不时戏耍夏芽，而夏芽则对这个坏男孩颇有好感。在阿航的鼓励下，女孩重拾信心，继续自己的艺能事业。在某个祭典之夜，一桩意外降临在少男少女的头上。失落的夏芽和阿航分手，阿航则堕落成街头混混。在此期间，两人的同学大友胜利（重冈大毅 饰）鼓舞着夏芽，两人越走越近……本片根据ジョージ朝倉发表在《别册Friend》（讲谈社）上的同名漫画改编。©豆瓣', '小松菜奈', '山户结希', 7.6, 141880, 'tt5108912', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2390682933.jpg', 1.3, 5.6, 29, 39.4, 24.7, '0.328060,-0.236074,-0.560863,0.369537,-0.021595,-0.205469,0.513523,0.348158,-0.289000,-0.283884,0.451110,0.715704,-0.315994,0.435383,0.226393,-0.086169,-0.334437,-0.520095,0.059478,-0.130400,-0.060014,-0.396691,-0.323278,0.050614,-0.268280,-0.214889,0.573547,0.055692,0.019898,0.776981,0.487653,0.197082,-0.165962,0.257189,-0.164951,0.143272,0.034791,0.356091,-0.067151,0.076865,-0.140069,-0.204184,-0.029872,-0.108732,0.142354,0.297936,0.719504,-0.071055,-0.311465,-0.070637,0.447613,-0.106715,0.002241,0.150978,0.452511,0.266741,0.218311,0.053410,-0.240075,-0.107991,-0.117139,-0.133566,-0.276582,-0.032839,0.127382,0.348725,-0.571062,0.527922,0.114432,-0.309369,0.338059,-0.318206,0.107568,0.174916,-0.002907,0.244064,-0.218134,0.385938,-0.204204,0.254865,0.600282,0.233043,0.103788,0.327031,-0.322489,-0.113479,-0.180649,0.005805,-0.407411,-0.132837,0.103256,-0.133262,0.049561,0.113712,-0.488958,-0.069655,0.152854,0.140186,0.021117,-0.360635,0.066232,-0.430234,-0.025366,-0.420845,-0.299369,0.049375,0.179363,-0.206962,0.839243,-0.959401,0.148195,0.514069,0.385854,-0.238055,0.486884,0.122738,0.028343,-0.200342,-0.271647,0.224306,-0.077813,0.101957,-0.101185,0.396147,-0.080846,-0.239109,-0.380193,0.323689', '1292219', '25922902', '35030151', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26611083', '在世界中心呼唤爱', '爱情', '柯达（欧豪 饰）收到了来自于20年前一个包裹。唤起了他无限回忆，从而令他踏上了重回故乡之路。沿着记忆的路线，柯达一路辗转回到高中时期的母校。尘封的往事、埋藏在心底的岁月、天使般的少女夏叶（张慧雯 饰）……那些关于青春与初恋的回忆涌上心头。那时的他们一同上学，一起去冒险， 共同约定要前往世界的中心，单纯的爱让他们倍感幸福。然而残酷的现实无法逃避……但相知相爱的两颗心却也更加坚定。这趟回忆之旅让徘徊在往事迷宫中的柯达敞开了封闭已久的心，他重新看见过去，也发现未来。柯达想起他和夏叶的约定，继续找寻夏叶生前最掛念的世界中心。', '欧豪', '郭在容', 5, 9771, 'tt7034918', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2374756671.jpg', 26.6, 26.4, 27, 9, 11, '0.206772,0.256370,-0.864492,0.767206,0.117113,-0.408981,0.947889,-0.083588,-0.590402,0.001059,-0.103761,0.718119,-0.024573,0.592581,0.492240,-0.012660,-0.354855,-0.743039,0.038805,-0.528405,-0.145216,-0.235847,-0.235622,0.058138,-0.186493,-0.185882,0.976820,0.444883,0.103645,0.641820,-0.088364,0.375043,-0.586634,0.438728,-0.121777,-0.055217,-0.074007,0.436141,-0.558740,-0.118277,0.161373,-0.109087,-0.065931,0.237444,-0.418254,0.131972,0.814353,-0.291865,-0.071949,0.118522,0.257087,-0.162528,-0.191068,-0.027560,-0.057254,0.413769,-0.142027,0.325615,-0.317924,-0.025019,-0.105547,-0.148433,-0.494151,-0.227113,0.255274,0.113274,-0.474926,0.334735,0.208609,0.188722,0.273053,-0.384403,0.169741,0.133939,0.524844,0.403551,-0.246994,-0.246635,-0.083025,0.377250,0.958650,-0.216616,-0.189702,0.449426,-0.338657,-0.150507,-0.047029,0.112961,-0.649285,0.053809,0.224710,0.474456,-0.358606,0.484781,-0.743888,0.061118,-0.221897,-0.129286,0.217306,-0.570950,0.016575,-0.421636,-0.467577,-0.412064,-0.071788,0.069368,-0.005032,-0.347092,0.530569,-0.711582,0.327183,0.755128,0.192892,-0.379653,0.753547,-0.005067,0.103725,-0.226999,0.463261,0.982910,-0.191120,0.504495,-0.331902,0.166601,-0.300386,0.342030,-0.962107,0.689734', '1291835', '1297598', '35287908', '35225859');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26611458', '分手再说我爱你', '喜剧', '王志強（方力申 饰）和钟家宝（邓丽欣 饰）结婚十周年，决定到瑞士滑雪庆祝，但在出发前，华重遇几年前的老友琪琪（盛朗熙 饰），二人发觉对对方的情愫从未减退。那边，阿宝竟突然提出不去瑞士，而她对阿华原来也有一个不可告人的秘密。', '方力申', '叶念琛', 6.6, 14435, 'tt5370376', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2295428089.jpg', 2.5, 12.3, 48.6, 27.1, 9.5, '0.365414,-0.241800,-1.042440,0.379825,0.339832,-0.201132,0.723019,-0.004369,-0.448287,-0.526498,0.074487,0.623770,-0.310188,0.299986,0.404798,0.042083,-0.089164,-0.870808,0.326890,-0.345801,-0.410989,-0.520436,-0.381013,0.144375,-0.126815,0.060505,0.157775,0.107610,0.042095,0.913647,0.502742,0.020291,-0.041516,0.599109,-0.094313,-0.071995,0.131916,0.700467,-0.510062,0.276162,0.609190,-0.182838,-0.472935,0.075208,0.040398,0.686588,0.374722,0.052023,-0.267441,0.109666,0.053124,-0.010774,0.013491,0.122866,0.301379,0.140405,0.169036,0.375067,-0.310820,0.162688,-0.023587,-0.089054,-0.052247,0.465852,0.121612,-0.034822,-0.370184,0.372497,-0.136202,-0.099386,0.120740,-0.703949,0.251412,0.631959,0.225651,0.127706,-0.140075,-0.087208,-0.565477,-0.081234,0.569865,-0.132400,0.281885,0.455615,0.131508,-0.298741,-0.074583,0.154842,-0.404813,0.074925,-0.123501,0.122836,-0.283881,-0.115179,-0.829656,-0.101004,-0.065306,0.213703,0.215227,-0.241217,0.161007,-0.517526,-0.325018,-0.532964,-0.260035,0.212438,0.135426,-0.347653,0.311046,-1.082889,0.387924,0.295850,0.468530,-0.739579,0.648993,0.174302,-0.182564,-0.357986,0.140259,-0.026548,-0.214584,0.024053,-0.133573,0.068479,0.214596,-0.196760,-0.374007,0.029685', '2230893', '25856453', '25723081', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26611801', '一念天堂', '喜剧', '从很小的时候起，热爱表演的沈默（沈腾 饰）就将成为一名演员当做是自己的唯一理想，然而，年纪轻轻的他却被诊断出身患绝症，时日无多。人生尚未开始就即将结束，这一噩耗令平日里大大咧咧的沈默开始认真的思考起了人生的意义，并且决定奉献出自己仅剩的时间，为社会做一些实事。沈默和好兄弟杜宇（杜晓宇 饰）联手，乔装打扮混入了当地的一个犯罪团伙之中，想要获取他们的犯罪证据，然而，杜宇却偏偏喜欢上了黑帮老大龙哥（林雪 饰）的情人小薇（王子子 饰），气得龙哥派出了冷酷杀手，要将杜宇和小薇除之而后快。与此同时，沈默结识了单纯善良的女主播马晓丽（马丽 饰），两人亦被卷入了杜宇制造的风波之中。©豆瓣', '沈腾', '张承', 6.1, 108445, 'tt5396872', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2298762068.jpg', 7.8, 20.7, 41.3, 20.4, 9.8, '0.415004,0.369856,-0.551908,0.494635,-0.350379,-0.435756,0.664535,0.010664,-0.605359,-0.090029,0.121181,0.424370,-0.022303,0.179107,0.339338,0.064249,-0.171763,-0.784234,-0.276762,-0.083306,-0.021932,-0.406164,-0.319599,-0.002482,-0.270231,-0.113783,0.506268,-0.003735,-0.157925,0.398887,0.507037,0.214813,0.035812,0.449171,0.042812,0.022738,0.019193,0.057726,-0.194486,0.162508,0.027854,-0.237928,-0.143341,0.368058,-0.225902,0.571756,0.606221,-0.276557,-0.060573,-0.196942,0.489078,-0.313526,-0.064962,0.259503,0.050168,0.305364,0.230390,0.149082,-0.252057,-0.007155,0.121066,-0.065626,-0.762087,-0.039462,0.151354,0.018565,-0.523544,0.473555,-0.257091,-0.112098,0.228103,-0.285705,0.330966,0.292304,0.484905,0.274920,-0.286357,0.001264,-0.314092,0.449555,0.649298,-0.042333,-0.158688,0.151117,-0.123630,-0.569031,-0.018214,-0.299626,-0.118514,-0.164031,0.555946,-0.015314,-0.208963,0.100179,-0.508302,-0.050356,-0.146205,-0.051558,0.062515,-0.288345,-0.092595,-0.271947,-0.155940,-0.150877,-0.380202,0.017873,-0.019212,-0.357260,0.874046,-0.844651,0.024020,0.475923,0.049175,-0.464623,0.442664,0.056400,0.071997,-0.155031,0.081887,-0.013391,-0.052125,0.337147,0.167603,0.479671,-0.213342,-0.316365,-0.381744,0.445326', '27602116', '35030151', '4127270', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26611804', '三块广告牌', '剧情', '米尔德雷德（弗兰西斯·麦克多蒙德 Frances McDormand 饰）的女儿在外出时惨遭奸杀，米尔德雷德和丈夫查理（约翰·哈克斯 John Hawkes 饰）之间的婚姻因此走到了尽头，如今，她同儿子罗比（卢卡斯·赫奇斯 Lucas Hedges饰）过着相依为命的生活。一晃眼几个月过去了，案件仍然没有告破预兆，而警方似乎早已经将注意力从案子上转移了开来。被绝望和痛苦缠绕的米尔德雷德租下了高速公路边上的三块巨型广告牌，在上面控诉警方办案无能，并将矛头直接对准了警察局局长威洛比（伍迪·哈里森 Woody Harrelson 饰）。实际上，威洛比一直隐瞒着自己身患绝症命不久矣的事实。因为这三块广告牌，米尔德雷德和威洛比的生活发生了翻天覆地的变化。©豆瓣', '弗兰西斯·麦克多蒙德', '马丁·麦克唐纳', 8.7, 771850, 'tt5027774', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2510081688.jpg', 0.2, 0.7, 8.9, 43.4, 46.8, '0.361752,-0.222372,-0.692763,0.190739,-0.097867,-0.402617,1.177149,0.341994,-0.577639,-0.019047,0.142271,0.567547,-0.328198,-0.033359,0.178819,0.094783,-0.577842,-0.846583,0.050462,-0.257071,-0.331385,-0.861045,-0.240143,-0.040624,-0.127392,-0.286559,0.309804,-0.133269,0.001984,0.468683,0.183978,0.293979,-0.079515,0.523394,0.020894,0.284694,0.226968,-0.054370,-0.239228,0.227819,-0.046751,-0.209619,-0.024913,0.175561,0.044413,0.476782,0.456689,-0.193331,-0.010816,-0.079894,0.094444,-0.193998,0.088018,0.338052,0.473506,0.142248,0.200818,0.372700,-0.373576,-0.205115,0.344177,-0.234917,-0.508792,0.388837,-0.086028,0.320910,-0.674350,0.517087,-0.527941,-0.046976,-0.073995,-0.608305,0.381653,0.342030,-0.010253,0.099488,-0.326987,-0.084367,-0.692730,-0.082238,0.436368,0.116546,-0.137841,0.309864,0.010456,-0.036433,-0.473403,0.045833,-0.257661,-0.035814,0.494550,0.110561,-0.306199,0.585698,-0.385423,-0.056167,-0.430350,-0.227835,-0.122082,-0.313488,-0.295750,-0.476511,-0.145267,-0.553063,-0.416562,-0.185784,-0.118594,-0.165601,0.320147,-0.420959,0.358203,0.448280,0.262148,0.024967,0.381398,-0.025511,0.412366,-0.041417,-0.110202,0.339375,0.192962,0.611253,0.398540,0.258465,0.027810,-0.159454,-0.260749,0.782757', '1578663', '1301582', '21348112', '27093707');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26611806', '贝拉的奇幻花园', '剧情', '《欢迎光临贝拉的奇幻花园》是一则可爱的现代童话，剧情围绕梦想成为童书作家的强迫症女孩、与个性古怪的园艺大师在伦敦相遇，为了创造一座奇幻花园而发展出一段动人的友情。电影由拍摄广告与摄影闻名的英国导演赛门艾布执导，让英式花园特有的花团锦簇与浪漫在大银幕上盛开。《欢迎光临贝拉的奇幻花园》由气质出众的英国女星杰西卡·布朗·芬德利（Jessica Brown Findlay）饰演每天生活按部就班、却有一堆眉角的怪女孩，英国金奖影帝汤姆威金森（Tom Wilkinson）则饰演个性机车的园艺大师。本片还找来了《新世纪福尔摩斯》（Sherlock）的大反派安德鲁史考特（Andrew Scott），饰演片中的暖男厨师，以及《战马》的帅哥杰瑞米尔文（Jeremy Irvine）扮演一位可爱的理工宅，集结几位英国实力派演员同台竞飙演技，精采可期！', '杰西卡·布朗·芬德利', '西蒙·阿布德', 7.5, 11335, 'tt4560008', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2446464626.jpg', 0.5, 4, 34, 42.9, 18.5, '0.180127,-0.087141,-0.349232,0.733905,0.103896,-0.169495,0.769740,0.322574,-0.108175,-0.243373,0.332566,1.001607,-0.459771,0.070774,0.540175,0.150749,-0.400212,-0.483674,-0.201075,0.078803,0.207670,-0.254839,-0.361688,0.009957,0.046578,-0.474642,0.681561,0.036661,-0.226108,0.422572,0.359622,0.062310,-0.256439,-0.304788,-0.056344,-0.128918,0.371367,-0.001013,-0.324401,0.220461,-0.158254,-0.048552,-0.084112,-0.306141,-0.020336,0.011142,0.595391,0.071366,0.000313,0.060546,0.623412,-0.056283,-0.003278,-0.094891,0.176509,-0.197795,0.363872,-0.115021,0.116224,-0.097086,-0.141139,-0.631019,-0.744422,0.266718,0.308606,0.159857,-0.314826,0.327522,-0.013083,-0.236799,0.165190,-0.106071,0.027234,-0.284919,0.379910,0.404058,0.343072,0.469635,-0.185435,0.536629,0.198339,0.341056,-0.368345,0.471754,-0.437624,-0.371975,-0.074877,-0.293611,-0.767182,0.161033,0.084085,-0.585732,0.089716,-0.005110,-0.682680,0.191252,-0.163298,-0.029899,0.031410,-0.088803,-0.145963,-1.184444,0.086112,-0.258880,0.182819,-0.240001,0.324188,-0.247662,1.076898,-0.608818,0.082350,0.414188,0.054368,-0.159399,0.879752,-0.093442,-0.006636,-0.151898,-0.353311,0.306501,-0.142019,-0.140894,-0.234026,0.653294,-0.136385,-0.338211,-0.516828,0.357550', '1322847', '3318306',