INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26611891', '欢乐满人间2', '喜剧', '故事发生在上一作的20年之后，此时的简（艾米莉·莫迪默 Emily Mortimer 饰）与迈克尔（本·威士肖 Ben Whishaw 饰）已经长大成人，两人都经历了人生的种种酸甜苦辣。妻子过世之后，迈克尔肩负起了养家和照顾孩子的职责，无奈安娜贝尔（皮格茜·戴维斯 Pixie Davies 饰）、约翰（纳撒内尔·萨利赫 Nathanael Saleh 饰）和乔治（乔尔·道森 Joel Dawson 饰）都颇有他们老爹当年的风范，调皮的可怕，令迈克尔一想起来就头皮发麻，只得召唤姐姐简前来帮忙。某日，孩子们在公园玩耍，一阵大风带来了从天而降的魔法保姆玛丽（艾米莉·布朗特 Emily Blunt 饰） ，她的回归给这个岌岌可危的家庭带来了新的希望。©豆瓣', '艾米莉·布朗特', '罗伯·马歇尔', 6.7, 10958, 'tt5028340', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2534409705.jpg', 1.2, 9.7, 51.2, 27.8, 10.1, '0.166476,-0.099689,-0.567251,0.443895,-0.109732,-0.478653,0.649178,0.211984,-0.530421,-0.428661,-0.102650,0.785616,-0.367979,0.418261,0.573714,0.009998,-0.489432,-0.545281,-0.049076,-0.106655,-0.314008,-0.560750,-0.248840,-0.335333,-0.037280,-0.465221,-0.012972,-0.232460,0.118499,0.464907,0.192287,0.350267,0.008067,0.235732,-0.007394,0.499837,0.018551,0.250966,-0.069896,-0.270291,0.054786,-0.049084,-0.189350,0.043498,0.399820,0.225179,0.491661,-0.269500,0.007857,-0.284655,0.147555,0.049878,0.288264,0.099828,-0.044995,-0.022796,0.235255,0.017881,-0.260868,-0.050725,0.233655,-0.200041,-0.619359,0.110707,0.086626,-0.016323,-0.596323,0.281737,-0.269944,0.018332,0.159494,-0.389741,0.042930,0.414639,0.211498,0.537648,-0.196226,0.235244,-0.415537,0.090898,0.546545,0.022541,-0.255124,0.082855,-0.302881,-0.124940,-0.008888,0.093997,-0.644596,-0.022104,0.460109,0.099907,0.051682,0.305896,-0.563011,-0.367044,-0.322331,-0.249661,-0.032990,-0.221369,0.051038,-0.578471,-0.155441,-0.492238,-0.377489,-0.094555,0.089553,-0.231569,0.763460,-0.497811,0.526380,0.121413,0.068767,-0.257511,0.441361,0.012771,0.543354,-0.147516,-0.001668,0.385487,0.011304,0.065667,0.368011,0.410600,-0.028536,-0.061317,-0.133977,0.456843', '30162520', '26348103', '1292720', '3563200');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26612258', '霹雳娇娃', '动作', '讲述了新一代火辣美女天使克里斯汀·斯图尔特、娜奥米·斯科特、埃拉·巴林斯卡霸气组队强势打击危险势力的故事。本片由好莱坞实力派导演及演员伊丽莎白·班克斯执导，高空跳伞、狂野飙车、拳脚肉搏、激燃枪战等惊险动作场面接连不断，肾上腺素飙升。三大天使特工技能高超，大玩变身诱惑上演温柔杀机。', '克里斯汀·斯图尔特', '伊丽莎白·班克斯', 5.3, 62403, 'tt5033998', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2572654905.jpg', 8.1, 32.9, 46.1, 9.7, 3.2, '-0.190434,-0.307733,-0.409609,0.480290,0.617577,0.337568,0.628100,0.303321,0.059671,-0.016112,0.870640,0.369489,-0.571504,-0.486721,0.522784,-0.298271,-0.512687,-0.470881,0.171170,0.439662,0.466453,-0.152106,-0.279989,-0.161936,0.400883,-0.844362,0.175698,-0.493538,-0.433884,0.479858,0.395726,-0.100580,-0.137448,0.117667,0.437886,-0.211240,0.598059,-0.444643,-0.274637,0.412265,-0.251992,-0.009660,-0.087956,-0.085461,0.093641,-0.190217,0.335315,0.000402,0.609603,-0.169595,0.283474,-0.108032,0.185830,-0.019510,0.331736,-0.514637,0.423059,-0.413374,0.631315,-0.195355,-0.255603,-0.134837,-0.762137,0.489766,-0.223492,0.027013,-0.198839,-0.047647,-0.296374,0.440021,0.328799,0.378795,-0.542400,-0.656669,0.668740,-0.015646,0.244519,0.536596,0.442074,0.234935,0.338302,0.081755,-0.628185,0.111416,-0.315602,-0.472080,-0.482378,-0.557452,-0.306497,-0.061744,0.597632,-0.168246,0.422738,0.606343,-0.416203,-0.279889,-0.306099,0.063189,-0.580355,0.046475,-0.299395,-1.237806,-0.293014,-0.006572,0.055501,-0.278064,0.119201,0.248717,0.772439,-0.237259,-0.229867,0.764946,-0.018848,-0.014201,0.065941,-0.079050,-0.284241,-0.124460,-0.168927,0.737629,-0.118352,-0.514792,0.131430,0.556527,-0.316748,0.388167,0.276723,0.353513', '34961898', '6517421', '4014397', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26612285', '谜巢', '动作', '生物科技公司研究员卢克·李（吴尊 饰）深入一座古墓随即失去音讯，剧毒生物学博士嘉·李（李冰冰 饰）得知弟弟卢克失踪的消息，随即与医药集团总裁梅森·伯罗斯（凯尔希·格兰莫 饰）组建一支专业的搜救队，在救援队长杰克·雷德利（凯南·鲁兹饰）的带领下，一行人前往卢克·李失踪的地点搜寻，却意外闯入神秘地下世界，一段意想不到冒险之旅就此展开……', '李冰冰', '金波·兰道', 3.4, 21899, 'tt4915672', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2510144625.jpg', 47.5, 36.6, 13.2, 1.9, 0.7, '-0.173736,0.241641,-0.871750,0.558186,0.412258,-0.605115,0.529816,-0.133455,-0.383061,-0.726299,-0.019514,0.233039,-0.126783,0.158184,0.327515,-0.218530,-0.394281,-0.228825,-0.164692,-0.360646,-0.606286,-0.558385,-0.198902,-0.554189,0.115842,-0.202930,0.454005,0.361821,-0.463519,0.492626,0.187004,0.586076,-0.269252,0.491008,0.376026,0.202476,0.776261,0.034487,-0.428348,-0.040747,0.106045,-0.069806,-0.095124,-0.226679,0.572915,0.169415,0.728287,-0.343573,0.279887,-0.349641,-0.228042,-0.117511,0.100830,-0.560710,0.635380,-0.039267,-0.362197,0.005068,-0.173283,-0.228334,-0.223212,-0.282176,-0.347194,-0.080518,0.353040,0.403420,-0.297152,-0.439433,-0.583367,0.321404,-0.118754,-0.662251,0.031543,0.448291,0.663191,-0.092555,0.411483,0.644195,-0.123263,-0.104398,0.606354,0.091656,-0.256721,-0.514328,-0.131354,-0.677863,-0.158084,0.611285,-0.245702,0.132573,0.654559,-0.409620,0.677831,0.262875,-0.262024,-0.369395,-0.587186,0.032054,-0.023255,-0.001932,0.013236,-1.083969,0.438879,0.398287,0.062969,0.238249,-0.160708,-0.012221,0.121915,-0.271099,0.396815,0.108323,0.030139,-0.353219,0.280096,-0.383728,0.388536,-0.765469,0.094091,0.886691,0.487986,0.278709,0.237560,0.179054,-0.029051,-0.238826,-0.116366,-0.050841', '1293572', '2002741', '3871833', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26613692', '哥斯拉大战金刚', '动作', '这两位宛如神衹一般强大的对手于一场壮观的战争中相遇，彼时世界命运正悬于一线。为了找到真正的家园，金刚与他的保护者们踏上了一次艰难的旅程。与他们一道前行的还有一个年轻的孤儿女孩——吉雅，这个女孩与金刚之间存在着一种独特而强大的紧密联系。但意想不到的是，他们在前行的航道上与愤怒的哥斯拉狭路相逢，也由此在全球引起了一系列破坏。一股无形的力量造成了这两只巨兽之间的巨大冲突，深藏在地心深处的奥秘也由此揭开。', '亚历山大·斯卡斯加德', '亚当·温加德', 6.3, 280186, 'tt5034838', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2634745654.jpg', 2.2, 14.6, 55.4, 23.5, 4.3, '0.321012,0.207489,-1.068812,1.021954,-0.027782,-0.027896,1.305332,-0.116161,-0.389748,-0.008327,0.294439,1.091363,-0.311331,-0.049551,0.183290,-0.211395,0.320810,-0.716494,-0.199155,-0.116737,-0.372540,-0.212272,-0.712590,-0.058659,0.008534,-0.284711,0.879645,0.459467,-0.436922,0.594009,0.134020,0.192150,-0.453454,0.504143,-0.288623,-0.164480,-0.245624,0.298072,-0.187090,0.120392,-0.101798,-0.154699,-0.126983,0.435668,-0.589015,0.215230,0.687311,-0.848585,-0.309785,-0.152201,0.381287,-0.531364,-0.015644,0.209511,0.258002,0.082236,0.080139,0.072893,-0.085366,0.053831,0.065296,-0.207008,-1.012766,-0.251646,-0.058133,0.110121,-0.411709,0.631022,0.434194,-0.498387,0.089296,-0.304768,0.163109,0.526893,0.336611,0.442195,-0.404576,-0.042292,-0.388531,-0.149216,1.079882,-0.062677,-0.657731,0.255357,-0.435722,-0.303536,-0.525269,-0.307288,-0.616244,-0.336082,0.657366,0.393774,-0.077650,0.468766,-0.980398,0.299191,-0.334005,0.055890,-0.432502,-0.518621,0.041648,-0.517239,-0.393659,-0.752778,-0.304084,0.394383,0.268266,-0.398584,0.814461,-0.782362,0.359568,0.744456,0.371345,-0.140952,0.688325,0.003907,0.260270,-0.278205,-0.270309,0.155974,-0.002110,0.415872,0.046852,0.589683,-0.132511,0.384993,-0.508874,0.674767', '25828589', '34461680', '24756472', '6875863');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26614893', '完美陌生人', '剧情', '三对处于各个婚姻阶段的伴侣和一个宅男，七人聚在一起吃晚餐。女主人提议下拍板决定当夜所有人分享每一个电话、每一条短信、邮件的内容,由此许多秘密开始不再是秘密，他们之间的关系也开始发生波动。无数疮痍在这场“坦白局”中被揭开，复杂的男女情感让所有人陷入困局，什么是婚姻感情中最不可触碰的底线？众人遭遇是难言的禁忌还是隐藏的真心，月食过后，谎言能否继续？', '马可·贾利尼', '保罗·杰诺维塞', 8.5, 497170, 'tt4901306', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2522331945.jpg', 0.2, 0.8, 12, 46.9, 40.1, '0.403868,0.095482,-0.554031,0.503595,0.026349,0.408349,0.687419,-0.123219,-0.788626,-0.340221,-0.100825,0.616981,-0.616237,0.255935,0.082854,-0.355653,-0.488902,-0.792734,0.021330,-0.223597,-0.060356,-0.489103,0.143530,0.024736,-0.186753,0.097048,0.728299,0.309154,-0.338801,-0.188755,0.441592,0.564357,-0.598432,0.518760,0.042699,-0.086017,0.010949,-0.192015,-0.693114,-0.090687,-0.114107,-0.133585,-0.142893,0.591413,-0.081225,0.332318,0.586123,-0.255855,-0.459843,0.132230,0.361452,-0.216710,-0.293655,0.423092,0.201512,0.252019,0.696798,0.506269,0.077034,0.089524,-0.063685,0.115009,-0.893121,-0.244991,0.190040,0.468322,-0.068861,0.183216,-0.002419,-0.042081,0.020033,-0.110604,0.274555,0.456975,0.641729,0.078655,-0.323558,-0.123825,-0.089160,-0.368580,1.125501,0.222234,-0.255530,0.262465,-0.175614,-0.372799,-0.106655,0.261030,-0.217802,0.217654,0.208412,0.663252,-0.079036,0.621580,-0.796199,0.058897,-0.039085,-0.447119,0.313161,-0.799982,-0.140102,-0.570195,-0.319474,-0.402120,-0.733274,0.183939,0.263499,-0.138661,0.486880,-0.849200,0.020664,-0.000077,0.129295,-0.370220,0.650958,0.422443,0.261360,-0.452191,0.406718,0.070037,-0.188216,0.005879,-0.205681,0.202126,-0.105792,0.328600,-0.514838,0.407911', '1293265', '4301278', '25828589', '25721544');
