INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26615748', '追忆迷局', '爱情', '尼克·班尼斯特（休·杰克曼 饰）是一名私家侦探。他的工作主要是帮助客户重拾遗忘的记忆，沉湎于幽暗诱人的逝去时光。尼克生活在因海平面上升而已经半淹没的迈阿密，然而当他接手了新客户梅（丽贝卡·弗格森 饰）之后，他的生活永远改变了。一次简单的寻回失物之任务，演变成一出危机重重的惊天迷局。尼克努力寻找着梅的失踪真相，而与整座城市存亡息息相关的巨型阴谋也逐渐浮现。他必须争分夺秒，破解回忆迷局，但他真的能在阴谋将自己吞噬前，找到梅失踪的真相吗？同时尼克也必须直面一个终极难题：为了留住你最爱的人，你到底愿意付出什么？', '休·杰克曼', '丽莎·乔伊', 6.2, 13638, 'tt3272066', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2654959196.jpg', 2.7, 18, 52.1, 20.9, 6.3, '-0.142300,0.142000,-0.589370,0.413856,-0.068893,-0.277483,0.666779,-0.115499,-0.205812,-0.319915,-0.062159,0.672856,0.217852,0.299950,0.436846,-0.008118,-0.201347,-0.709394,0.259040,-0.231468,-0.252895,-0.782997,-0.246251,-0.478878,0.048558,-0.193930,0.803822,0.523769,-0.133835,-0.044398,0.360742,0.461890,-0.167178,0.540063,0.043761,-0.259943,0.069451,-0.082102,-0.325830,0.057620,0.125314,-0.288092,-0.153489,0.267242,0.038755,0.253250,0.500224,-0.385865,-0.178692,-0.066712,0.300273,-0.520132,-0.015254,-0.113873,-0.116315,-0.046716,-0.135951,0.488559,-0.416296,-0.183698,0.043085,-0.335050,-0.912727,-0.179746,0.147132,0.107864,-0.405733,0.115139,0.157030,0.108420,0.170616,-0.117202,0.314140,0.540589,0.311844,0.139146,-0.239742,-0.059726,-0.622660,0.202818,0.682128,-0.215727,-0.222324,0.417831,-0.188308,-0.198407,-0.209242,-0.235978,-0.255893,0.051654,0.268193,0.143485,-0.139836,0.348761,-0.387496,-0.263500,-0.408767,-0.244517,-0.095337,-0.511507,-0.127160,-0.165087,-0.221311,-0.056786,-0.367982,-0.069977,-0.151879,-0.465030,0.591627,-0.904632,0.230892,0.679044,0.046239,-0.505325,0.503789,0.136006,0.267392,-0.442584,0.049558,0.556675,-0.048739,0.325493,-0.042062,0.027920,0.380129,0.136727,-0.477839,0.600430', '30345227', '3187790', '30163500', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26615753', '黑子的篮球·终极一战', '动画', '黑子哲也 及 火神大我 加入了诚凛高中篮球队。相对于有着绝佳球感的火神，黑子却是一名在场上“几乎没有存在感”的球员。但其实，黑子曾是篮球强校帝光国中篮球队的一员，曾与被称为“奇迹时代”的5位天才并肩战斗，以“梦幻的第6人”的称号活跃在篮球场上。“影”与“光”的二人搭档成为校队主力，带领诚凛高中成功打进了冬季选拔赛，并在选拔赛中击败其他拥有“奇迹时代”成员的各路强队，获得了全国冠军。 就在二人升上高二后的那个暑假末尾，由一批18岁左右的美国篮球天才组成的街球队伍“Jabberwock”来访日本，并与日本男篮国家队进行友谊赛。他们以压倒性的实力让日本队惨败，还嘲笑了他们一番。 此举激怒了诚凛高中篮球队教练丽子的父亲景虎。这位曾经的日本篮球国手决定集结黑子与火神，以及“奇迹时代”的其他成员，临时组建梦幻球队“VORPAL SWORDS”，誓言向“Jabberwock”复仇！ 一场最激烈的决战，就此打响!', '小野贤章', '多田俊介', 6.4, 13178, 'tt6728390', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2531651342.jpg', 4.1, 16.1, 47.7, 22.8, 9.4, '0.016821,0.054517,-0.514343,0.695432,-0.068032,-0.339030,0.139422,-0.078525,-0.502951,-0.181967,0.149870,0.907104,-0.271683,0.250544,0.410896,-0.722233,0.218647,-1.138903,-0.238995,-0.189303,-0.325067,-0.465972,-0.328257,0.155096,0.044957,-0.301937,1.306607,0.062829,-0.511343,0.765554,0.208968,0.297697,0.296422,-0.001327,-0.208348,-0.227995,0.177825,0.274317,-0.515557,0.307875,-0.508062,-0.119513,-0.434313,0.092279,0.237928,0.113086,0.574069,-0.348237,0.157950,-0.282721,0.123301,-0.432529,-0.412692,0.168291,0.709845,0.052846,0.048216,0.238688,0.575133,0.294204,-0.498073,-0.387039,-0.737049,0.098372,0.041126,0.092433,-0.309155,0.898808,0.016859,0.014540,0.342875,0.098080,0.062854,0.403938,0.177711,0.081723,-0.335418,0.031064,-0.185719,0.172215,0.866745,0.025123,-0.449301,-0.211107,0.000822,-0.617264,-0.164166,-0.435794,-0.246496,0.409309,0.124663,0.049338,0.354473,0.303021,-0.700523,0.182569,-0.047428,-0.330253,0.103769,-0.373847,0.304154,-0.857271,0.164506,-0.267625,-0.408504,0.208402,0.040304,-0.090275,1.061715,-1.123435,-0.127163,0.472088,0.231608,-0.181115,0.493103,0.120507,0.253769,-0.285144,-0.339354,0.048285,-0.087716,0.323592,-0.187234,0.565002,-0.284397,-0.243290,-0.420025,0.400976', '1826173', '4202326', '26365262', '1457219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26616145', '共助', '动作', '朝鲜一座国家秘密工厂对美元的仿制度超过了百分之九十九，朝鲜特种部队首长车奇成，在之前的行动失去了妻子，因而对国家产生不满，决定带领一众手下脱北出逃。并且在走之前要抢走工厂最宝贵的伪钞模板。车奇正的手下，一个行动小组的组长林哲令（玄彬饰）率领自己的组员，与车奇正一伙发生了激烈交火。最后除林哲令一人幸存，其余工人和保安人员全部被杀害，其中就包括林哲令的妻子。朝鲜军政高层下令必须将伪钞模板追回，而林哲令也下定决心天涯海角也要追杀车奇正为妻报仇。朝鲜情报部门得到情报，车奇正出逃之后，辗转中国几座城市最终逃到了韩国首尔。朝鲜军界高层借南北高层会谈之际，以随从身份带林哲令一同前往首尔，并通知韩国警方展开一次共助行动，一起抓捕车奇正。韩国警方对车奇正的真实身份和朝鲜官方的实际目的一无所知，于是派出打酱油的刑警姜镇泰(柳海真饰）协助林哲令，实则敷衍和监视朝方行动。此时车奇正和原朝鲜特种部队的手下已经全部偷渡到了首尔，敌强我弱力量对比悬殊，看似不可能完成的共助行动就此展开。@秀山鲤鱼', '玄彬', '金成勋', 7.3, 33798, 'tt5606538', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2410842166.jpg', 0.6, 4.5, 40.5, 37.9, 16.5, '0.202710,0.046591,-0.725605,0.683320,0.142280,-0.016677,0.076706,0.271504,-0.505914,-0.140812,0.268731,0.476458,0.322808,-0.285684,0.411792,-0.299034,-0.545455,-0.767697,-0.375431,-0.101709,-0.401154,-0.565616,0.014029,-0.484553,-0.065917,-0.007745,0.613483,0.194017,-0.181802,0.600033,0.243429,0.201976,-0.382536,0.280097,0.080170,-0.187264,0.469497,-0.315545,-0.561795,0.243827,-0.183861,-0.164760,-0.008990,0.167528,0.301360,0.345934,0.632943,-0.016008,-0.108869,-0.155085,-0.103149,-0.423666,-0.136046,-0.045393,0.705162,0.225019,0.077662,0.484036,-0.163510,0.074673,-0.108218,0.076343,-0.709711,0.016286,0.215182,-0.043553,-0.475043,0.186526,-0.276368,0.237915,0.087158,-0.266861,0.259015,0.776257,0.174697,-0.038033,0.002936,0.082342,-0.656204,0.096736,0.754608,-0.176251,0.061736,-0.312226,0.037670,-0.349796,0.009683,-0.236110,0.049493,0.021859,0.247731,-0.052483,-0.023228,-0.014113,-0.441897,-0.103097,-0.425761,-0.383206,0.167870,-0.284656,0.295005,-0.781489,-0.056821,-0.149500,-0.033824,0.279854,0.199452,0.389137,0.756725,-0.511914,-0.105036,0.426238,0.597772,-0.855874,0.439627,0.147050,0.181231,-0.384993,0.159421,-0.197921,0.312815,0.630984,-0.009512,0.043678,-0.1314