INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26616436', '我们的世界', '剧情', '十岁的女孩李善（崔秀英 饰）因为家境贫穷而在学校遭到了以女孩宝拉（李秀仁 饰）为首的女生团体的孤立和排挤。在放暑假的前一天，李善在放学后的学校走廊遇见了即将在新学期转学来的女生韩智雅（薛惠 饰），两个女孩虽然刚刚相识不久，却迅速成为了好朋友，李善更是邀请韩智雅来自己家里居住。韩智雅和奶奶过着相依为命的生活，两人住在豪华的大房子里，虽然拥有着充足的零花钱和时髦的手机，但韩智雅显然并不享受这种孤独的生活，和李善一起奔跑在大街小巷里的日子成为了她最美好的回忆。然而，没过多久，两个女孩的友谊便出现了细微的裂痕，这裂痕在韩智雅认识宝拉之后有愈演愈烈之势。新学期的第一天，当韩智雅对李善的招呼视而不见时，李善心中宝贵的东西碎裂了。©豆瓣', '崔秀英', '尹佳恩', 8.4, 28008, 'tt5502816', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2385418547.jpg', 0.2, 0.8, 13, 51.8, 34.1, '0.395657,-0.075504,-0.816760,0.570211,-0.260135,-0.342516,0.941459,0.447220,-0.565983,-0.200332,0.207544,0.665343,-0.279351,0.506969,0.346188,-0.141897,-0.200221,-0.734875,-0.033424,-0.216523,-0.406728,-0.285001,-0.060125,-0.102369,-0.204875,-0.316740,0.336305,0.111045,0.050252,0.887908,0.174635,-0.042442,-0.078771,0.711167,-0.392237,0.023518,0.040645,0.369675,-0.209730,-0.002441,-0.111820,-0.293726,-0.153587,-0.067823,0.154555,0.373850,0.757157,0.004274,-0.042047,0.126021,0.351960,-0.036056,-0.357481,0.123263,0.624007,0.145974,0.511123,-0.015208,-0.276828,0.078408,0.015567,-0.227705,-0.416405,0.110321,0.112081,0.025188,-0.614257,0.948416,0.152840,-0.379436,0.288238,-0.480468,0.230530,0.386711,-0.006184,0.622401,-0.235301,0.175726,-0.422846,0.206465,0.660621,-0.028782,-0.233077,0.459212,-0.328294,-0.522804,-0.126731,0.011312,-0.589867,-0.064958,0.282877,0.055684,-0.437506,0.090788,-0.720417,0.226479,0.134124,-0.057295,0.159866,-0.637519,-0.424840,-0.627592,-0.193988,-0.695028,-0.433516,0.201668,-0.119305,-0.063707,0.926341,-1.087810,0.352126,0.257874,0.405565,-0.347612,0.775122,0.088751,0.170155,0.063716,0.004497,0.141782,-0.102943,0.436216,0.002354,0.602030,-0.229803,-0.101744,-0.532812,0.698824', '1292219', '1390020', '1301562', '1306544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26616690', '非凡任务', '剧情', '国境边陲云来市，卧底林凯（黄轩 饰）在随老大程毅（王砚辉 饰）交易时，遭到缉毒警突袭。危急时刻，林凯救下对方毒品贩子，随后一路被挟持到金三角，来到了狡猾狠毒的毒枭老鹰（段奕宏 饰）的巢穴。老鹰恼羞成怒，派儿子和林凯回到云来市，要查清究竟是谁吞了自己的钱和货。几番交手过后，林凯占据主动，要求老鹰将大中华地区的毒品经营权交给自己，实则是为了更进一步接近老鹰，以将这群犯罪分子一网打尽。从走出警校那一天，他便将自己的性命交给了国家和人民，所以必须抛弃原来的身份，以毒贩的嘴脸在这个罪恶横生的世界穿行。没有回头之路，国法的捍卫者只有勇往直行……©豆瓣', '黄轩', '麦兆辉', 6.2, 68442, 'tt6690310', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2453197648.jpg', 1.9, 16, 55.1, 21.7, 5.2, '0.205514,0.056081,-0.671474,0.462974,-0.293453,-0.170215,0.480482,0.024799,-0.339078,0.086995,0.378040,0.650685,0.192189,-0.219464,0.147012,-0.036258,-0.110751,-0.683685,-0.287909,-0.308138,-0.202661,-0.350356,-0.167772,-0.129574,0.045327,-0.023860,0.545059,0.141743,-0.304985,0.291541,0.371350,0.280794,-0.362385,0.302074,-0.385252,-0.045664,0.092371,-0.290725,-0.431021,0.365832,0.054623,-0.305443,-0.206726,0.168813,-0.072542,0.334931,0.796308,-0.207335,-0.126756,-0.153333,0.222811,-0.705586,-0.133023,0.038909,0.239901,-0.156092,-0.003390,0.254441,-0.253909,0.190199,0.173236,-0.105226,-0.634176,-0.233994,-0.175490,0.035517,-0.777369,0.095376,-0.231146,0.121088,0.281701,-0.440595,0.361582,0.366852,0.178353,0.309519,0.040801,0.042960,-0.737817,-0.159134,0.762989,-0.173534,0.098176,-0.105902,0.319852,-0.418319,0.155952,-0.287109,-0.042712,-0.173958,0.701899,-0.104346,-0.309206,0.050133,-0.590597,-0.253259,-0.136183,-0.175730,0.257791,-0.426763,-0.244871,-0.199218,-0.114275,-0.367058,-0.148400,0.333322,0.100622,-0.118922,0.394178,-0.635206,-0.020152,0.621373,0.377628,-0.632979,0.305925,-0.048866,0.086610,-0.210494,-0.005957,-0.069137,0.623824,0.816101,0.233444,0.138005,-0.035291,-0.347239,-0.209968,0.207518', '26747274', '1300857', '25908042', '20497559');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26616719', '弗兰兹', '剧情', '法国导演弗朗索瓦·欧容在沉寂两年后，终于带着皮埃尔·尼内、葆拉·贝尔主演的《弗兰兹》杀回影坛。影片将以一战后的法国为背景，聚焦贝尔饰演的德国女人正因未婚夫的惨死而悲痛欲绝，尼内饰演的神秘法国男子却悄然出现，默默为其未婚夫墓碑致哀、献花，两人也就此揭开一段匪夷所思的往事。', '皮埃尔·尼内', '弗朗索瓦·欧容', 8.4, 39810, 'tt5029608', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2383307897.jpg', 0.2, 0.8, 13.1, 50.7, 35.2, '-0.047053,0.055167,-0.496798,0.673096,0.146070,-0.532593,0.852352,0.215306,-0.355929,-0.078309,0.574388,1.067585,-0.412723,0.294480,0.617680,0.171674,-0.559777,-0.874595,-0.038148,-0.116469,-0.110575,-0.302179,-0.407052,-0.176825,-0.109376,-0.490003,0.847392,0.044336,0.205559,0.532365,0.578470,0.364940,-0.275030,0.365559,0.049537,0.144059,0.027335,-0.030020,-0.430904,0.100030,0.037277,-0.586320,-0.317857,-0.023051,-0.448036,0.270223,0.585285,-0.108153,0.333186,-0.081096,0.420808,-0.367648,-0.085807,0.019246,0.254132,-0.156845,0.297157,0.277353,-0.483353,-0.335308,-0.058302,-0.079845,-0.461227,0.226945,0.053722,0.248844,-0.645208,0.389578,-0.188836,-0.056263,0.249954,0.011655,0.044909,0.322580,0.281967,0.294258,-0.106508,0.112846,0.079579,0.404698,0.123627,-0.080038,-0.121066,0.416743,0.136209,-0.272266,-0.079228,-0.146878,-0.546221,0.023610,0.236864,0.017190,0.241460,0.316862,-0.499023,-0.409649,-0.395525,-0.276020,0.143942,-0.364838,-0.270194,-0.664959,-0.243357,-0.081051,0.131597,-0.081492,0.102813,0.008172,0.580609,-0.384343,0.321072,0.268563,0.079354,-0.281404,0.632403,-0.011091,0.140779,-0.241887,-0.246007,0.623509,-0.104458,-0.033396,0.054047,0.322726,-0.190158,-0.043696,-0.380208,0.592464', '1299663', '1780122', '34795703', '1298095');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26617314', '我唾弃你的坟墓：复仇在我', '惊悚', '一晃眼数年过去，珍妮弗（莎拉·巴特勒 Sarah Butler 饰）却依然深陷之前的阴影之中无法自拔，惨不忍睹和回忆和梦魇纠缠着她，她唯有寻求心理医生的帮助。珍妮弗参加了一个女性互助小组，在那里，她结识了一名特立独行的新朋友马拉（Jennifer Landon 饰）。马拉的一言一行影响和改变着珍妮弗，在互助小组中所听到的那一个个悲惨的故事亦深深震撼着珍妮弗。在马拉的带领之下，珍妮弗和她一起展开了针对男人的报复行动，起初只是威胁和恶作剧，之后却慢慢演变成为了彻底的暴力，在此期间，珍妮佛逐渐发现了内心里对于男性的仇恨。某日，马拉死了，死前受到了非人的折磨和虐待，珍妮弗怀疑这一切同她那身强体壮的前男友有关。©豆瓣', '莎拉·巴特勒', 'R.D. Braunstein', 5.8, 8157, 'tt4530884', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2271690456.jpg', 7.9, 27, 41.3, 15, 8.8, '0.400506,0.031502,-0.738408,0.671531,0.047729,-0.287956,0.987745,0.028253,-0.545179,-0.214048,0.123986,0.599862,-0.278644,0.375815,0.404678,-0.170466,-0.442122,-0.829550,-0.399047,-0.007163,-0.457536,-0.454710,-0.410687,-0.003041,-0.061859,-0.413280,0.551060,0.081718,-0.347460,0.758094,0.321769,0.336390,-0.182778,0.551355,0.032026,0.112861,0.140791,-0.007230,-0.141840,-0.018917,0.163780,-0.346007,0.054261,0.212696,-0.278728,0.471080,0.689735,-0.524165,-0.114229,-0.231723,0.144527,-0.302176,-0.043308,0.258699,0.146792,0.011570,0.354105,0.228245,-0.237122,-0.035677,0.006619,0.179038,-0.866950,0.010072,0.133081,0.213480,-0.688767,0.485040,0.159129,0.009302,0.142547,-0.053762,0.176466,0.235859,0.278261,0.414918,-0.323409,-0.044439,-0.424677,0.185730,0.767513,0.061200,-0.331282,0.095372,-0.300590,-0.266447,-0.083036,-0.144995,-0.447361,-0.176883,0.237299,0.324925,-0.299345,0.282181,-0.587587,0.038878,-0.089017,-0.088472,-0.157915,-0.635552,0.045329,-0.637768,-0.332021,-0.533690,-0.269317,0.056138,-0.044048,-0.280942,0.628613,-0.815850,0.295981,0.554771,0.439981,-0.390857,0.615829,0.192793,0.225894,-0.148026,-0.133347,0.288961,-0.121706,0.206215,0.275770,0.495330,0.001903,0.123711,-0.493443,0.631316', '3111650', '1308755', '1292211', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26627736', '边境杀手2：边境战士', '剧情', '在第一部《边境杀手》电影事件发生三年后，这部续集在德克萨斯州的美墨边境附近开幕。随着一名恐怖分子试图通过卡特尔贩毒集团从墨西哥偷渡到美国失败后自爆和之后在堪萨斯城发生的自杀式炸弹袭击，美墨边境的毒品战争升级，联邦特工马特·格拉弗（乔什·布洛林饰）与善变的亚历杭德罗（本尼西奥·德尔·托罗饰 ）重新开始了合作。', '本尼西奥·德尔·托罗', '斯特法诺·索利马', 6.6, 36510, 'tt5052474', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520296878.jpg', 0.7, 8.9, 55.9, 28.9, 5.6, '0.281719,-0.121857,-0.880376,0.407578,0.627615,-0.015491,0.662237,0.009095,-0.297978,0.079730,0.155114,0.787696,-0.389679,-0.471507,0.533543,-0.063225,-0.923195,-0.752367,0.036753,-0.419537,-0.271343,-0.360168,-0.550188,-0.141853,0.086705,-0.645623,0.583151,0.146143,-0.319304,0.397315,0.305569,0.704735,-0.154419,0.376298,0.200848,0.111830,0.640614,-0.330687,-0.553003,0.608188,0.095666,-0.177587,-0.294988,-0.141989,0.328602,0.450703,0.612328,-0.287125,0.400464,-0.072958,0.284311,-0.196190,-0.039402,-0.175794,0.560101,-0.026207,-0.064224,0.288870,-0.242103,0.063998,0.088275,-0.308905,-0.397915,0.056820,-0.232309,0.273702,-0.400842,0.186635,-0.577694,0.308710,0.145855,-0.426059,0.132553,0.974578,0.376408,-0.114373,-0.061241,0.065363,-0.564093,0.147622,0.897505,-0.157830,-0.401946,-0.035678,0.445379,-0.477123,-0.247599,-0.158768,-0.209580,0.115499,0.763973,-0.585127,-0.197511,0.586324,-0.907856,-0.237999,-0.573116,-0.502350,0.150529,0.278941,-0.075578,-1.250318,-0.236169,-0.331329,0.072062,-0.021122,-0.054345,0.099666,0.164998,-0.627233,0.377522,0.637345,0.435625,-0.120261,0.046716,-0.116031,0.402185,-0.101103,0.047464,0.398558,0.329407,0.592755,0.203138,0.515464,0.501092,-0.294722,0.112115,0.312587', '3871833', '2075345', '6517421', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26627754', '普通女人', '剧情', '玛丽娜（丹妮拉·维加 Daniela Vega 饰）是一名跨性别主义者，和一位名叫奥兰多（弗兰西斯科·雷耶斯 Francisco Reyes 饰）的男子正在同居之中。奥兰多虽然年长玛丽娜许多，但他包容而又善良，给予了玛丽娜许多快乐的回忆。然而，某一天夜里，奥兰多因为突发疾病被送往医院，最终不治身亡。此时的玛丽娜并不知道，比起失去爱人，她将要面的是比这残忍的多的事情。玛丽娜想要参加奥兰多的葬礼，却被奥兰多的前妻严令禁止。与此同时，因为身份不明，她也将失去自己和奥兰多居住的房子。更糟的是，一名私家侦探被雇佣开始调查玛丽娜的隐私，因为她被怀疑和奥兰多的死有牵连。©豆瓣', '丹妮拉·维加', '塞巴斯蒂安·莱里奥', 7.3, 12479, 'tt5639354', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2427410190.jpg', 0.7, 3.2, 38.7, 46.7, 10.6, '0.679188,-0.036648,-0.616860,0.290199,-0.285531,-0.150265,1.125748,0.085336,-0.498182,-0.589320,0.132642,0.997159,-0.217308,0.348411,0.147261,-0.052174,-0.093724,-0.639062,0.008495,-0.041186,-0.382330,-0.613106,-0.258881,-0.039117,-0.268118,-0.403009,0.715081,0.178842,-0.254095,0.472299,0.406680,0.780432,0.230394,0.596557,-0.269146,-0.064431,0.178547,-0.097372,0.108398,0.299847,0.314414,-0.297653,-0.049022,0.527868,-0.126971,0.607338,0.430474,-0.094529,-0.164716,-0.187048,0.406528,-0.373605,0.053820,0.335811,0.372348,0.037549,-0.054842,0.375910,-0.438627,-0.086400,0.135572,-0.021263,-0.922723,0.154578,0.387141,0.320954,-0.788156,0.403789,-0.305234,-0.162869,0.182175,-0.105049,0.406146,0.388654,0.012756,0.417933,0.001175,-0.204422,-0.618675,-0.052700,0.870018,-0.133076,-0.155127,0.389057,-0.406925,-0.380595,0.149278,-0.260480,-0.429375,0.181161,0.110087,0.094577,-0.117870,0.216958,-0.311620,-0.010143,-0.279099,-0.335045,-0.257312,-0.391014,-0.144613,-0.456433,-0.143138,-0.527644,-0.347804,-0.045244,0.036230,-0.234016,0.704764,-0.976189,0.353455,0.448400,0.351124,-0.713017,0.640223,0.347329,0.274114,-0.104502,-0.050600,0.434751,0.308221,-0.092688,0.106510,0.170395,-0.053753,-0.360460,-0.352215,0.643459', '25721544', '1308755', '10546747', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26628282', '宠儿', '剧情', '故事发生在十八世纪早期的英格兰，安妮（奥莉薇娅·柯尔曼 Olivia Colman 饰）是大不列颠王国的女王，她和自己的青梅竹马莎拉公爵夫人（蕾切尔·薇兹 Rachel Weisz 饰）一直保持着秘密的情人关系。阿比盖尔（艾玛·斯通 Emma Stone 饰）是莎拉的远方亲戚，一直渴望融入以皇室为代表的上流社会，她来到了莎拉身边，想要谋得一份职务，哪知道莎拉对她十分冷淡。凭借着自己的聪慧和计谋，阿比盖尔吸引了安妮女王的注意，得以在她的身边侍奉。很快，阿比盖尔便得知了安妮女王和莎拉之间的“小秘密”，对权谋充满了欲望的阿比盖尔开始希望自己能够取代莎拉的位置，得到女王的宠幸。©豆瓣', '奥利维娅·科尔曼', '欧格斯·兰斯莫斯', 7.5, 79273, 'tt5083738', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2532012274.jpg', 0.3, 2.3, 33.3, 50.2, 13.8, '0.449856,0.261239,-0.711597,0.885698,-0.151059,-0.107716,0.771221,0.191927,-0.453789,-0.132034,0.319556,0.887971,-0.342379,0.058510,0.429788,0.578142,-0.585360,-0.868299,0.089575,-0.341563,0.019149,-0.919639,-0.453434,0.005016,-0.325077,-0.632632,0.376396,-0.395094,0.088376,0.404058,0.389292,0.338843,0.232095,0.449629,-0.037644,0.081201,0.169247,-0.476480,-0.345406,0.181928,0.174586,0.105930,-0.261053,0.300518,0.210119,0.179676,0.421722,-0.638422,0.407593,-0.188981,0.093177,-0.054346,0.527995,0.072385,0.307582,-0.383812,0.274560,0.295590,-0.229961,-0.254423,0.256022,0.112222,-0.745355,0.158042,0.063394,0.495205,-0.676743,0.107580,-0.297869,-0.188826,0.490035,-0.229720,0.137072,0.557519,0.040997,0.444416,-0.014884,0.121651,-0.501708,-0.241652,0.383744,-0.003800,-0.440006,0.369417,-0.354993,-0.338806,-0.170572,-0.112067,-0.680256,-0.279768,0.344927,0.134751,0.031911,0.564930,-0.521552,-0.178338,-0.301820,-0.260829,0.411691,-0.598240,-0.055474,-0.568092,-0.452943,-0.726818,-0.305306,-0.305706,0.003542,-0.347024,0.778700,-1.103471,0.358589,0.694152,0.366390,-0.517151,0.668222,0.186114,0.095099,-0.289004,-0.303671,0.544365,-0.145659,0.050397,0.086327,0.320376,0.111552,-0.140378,-0.321954,0.728043', '1299556', '20277433', '1783461', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26628329', '南极之恋', '爱情', '南极，一场坠机，婚庆公司老板吴富春（赵又廷 饰）和高空物理学家荆如意（杨子姗 饰）相遇，两个毫无共同语言的男女在南极腹地无人区冒险生存75天。在酷寒、没有物质供应、随处都是绝境的环境中，活下去已经变成每一天的最大愿望。在寻找救援的过程中，这对性格水火不容但命运却又相濡以沫的人，敬畏了自然，领悟了爱情。', '赵又廷', '吴有音', 6.6, 104967, 'tt7962598', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2518028103.jpg', 2.5, 12.9, 45.4, 29.4, 9.8, '-0.218893,-0.056703,-0.897464,0.578034,0.002106,-0.041768,0.771340,0.163858,-0.307650,0.018332,0.163455,0.709615,-0.063633,-0.100432,0.138621,-0.132579,-0.336513,-0.597537,-0.226200,-0.086907,-0.378713,-0.360427,-0.537840,-0.251945,-0.010372,-0.206779,0.760571,0.462809,-0.398500,0.273199,-0.030340,0.027234,-0.221320,0.629151,-0.421648,-0.170347,0.104286,0.477077,-0.531783,0.195166,-0.320810,0.020924,-0.274647,0.296985,-0.008960,0.396790,0.643815,-0.404646,-0.265473,0.031355,0.191708,-0.404069,-0.299527,-0.000968,0.312767,-0.362940,0.099844,0.181549,-0.078793,-0.088393,0.144500,0.030775,-0.850097,-0.055345,0.020470,0.208379,-0.359038,0.614624,0.336857,-0.366333,-0.255357,-0.387001,0.388775,0.268052,0.485415,0.186389,-0.310420,-0.271273,-0.526753,0.246966,1.058867,-0.033759,-0.412820,0.451304,-0.461596,-0.565367,-0.213910,-0.300168,-0.506514,-0.306060,0.079878,0.232058,-0.215905,0.366376,-0.645371,0.528372,-0.046806,-0.231314,-0.136410,-0.536860,-0.001248,-0.610262,-0.210132,-0.633477,-0.521620,0.150863,0.322573,-0.290405,0.755450,-0.668480,0.182780,0.680049,0.319319,-0.472909,1.040130,0.251450,0.103826,-0.380344,0.071882,0.263229,-0.264691,0.324446,-0.069361,0.360114,-0.128742,0.448844,-0.361815,0.535098', '3055049', '30162520', '25721544', '1309177');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26628357', '一个叫欧维的男人决定去死', '剧情', '欧维（罗夫·拉斯加德 Rolf Lassgård 饰）是一个刻板而又固执的老头，他的妻子半年前死于疾病，留他一人生活在这个混乱不堪的世界之中。每天早晨，欧维都会定时在社区里进行巡视，确认所有的车辆都停在应停的位置，呵斥违反规定私自驶入社区的车辆，赶走四处乱转破坏环境的猫狗，在社区居民眼里，欧维是“来自地狱的恶邻”，可每个人都明白，这其实是欧维对于社区爱之深刻的表现。某一日，欧维遭到了上司的解雇，离开了恪守了几十年的工作岗位，心灰意冷对现世了无牵挂的欧维决定自杀。然而，就在这个节骨眼上，一位名为帕维娜（巴哈·帕斯 Bahar Pars 饰）的女子和丈夫带着两个孩子搬到了欧维的隔壁，成为了欧维自杀计划的绊脚石。©豆瓣', '罗夫·拉斯加德', '汉内斯·赫尔姆', 8.9, 428016, 'tt4080728', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2406624993.jpg', 0.1, 0.5, 7.5, 37.9, 54, '0.324052,0.019723,-0.819553,0.410350,-0.376018,-0.180107,0.886493,0.182040,-0.499002,-0.085195,0.357179,0.799058,-0.150752,0.218904,0.461450,0.050908,-0.174710,-0.435937,0.005484,-0.264872,-0.119463,-0.403438,-0.049393,-0.419442,-0.168189,-0.332394,0.444316,0.141838,-0.076932,0.147217,0.104756,0.313826,-0.252055,0.312867,-0.211336,-0.020617,0.007801,-0.115857,-0.053380,0.212069,-0.274477,-0.153742,-0.074630,0.012795,-0.084763,0.399277,0.696113,-0.153833,-0.298919,-0.098907,0.181584,-0.342631,-0.149576,0.252806,0.312195,-0.240587,-0.030176,0.354868,-0.336180,0.065263,0.148523,0.094654,-0.565424,-0.119736,0.038386,0.198786,-0.725752,0.739921,-0.122212,-0.126619,-0.224802,-0.428333,0.444183,0.143327,0.096789,0.719301,0.054168,-0.031816,-0.609459,-0.147850,0.332580,-0.027462,-0.247356,0.323069,-0.208831,-0.382762,0.146160,-0.113705,-0.634028,-0.357053,0.127641,-0.139510,-0.500294,0.128073,-0.568745,0.214473,-0.152962,-0.450873,-0.110326,-0.543271,-0.275591,-0.479225,0.127387,-0.389451,-0.124753,0.330092,0.106422,-0.080848,0.510246,-0.819312,0.452431,0.426499,0.178195,-0.673944,0.789162,0.248768,0.143181,0.029845,0.118880,0.242455,0.204286,0.425999,-0.075729,0.379585,-0.138464,-0.139673,-0.558728,0.498840', '1302384', '3055049', '21619567', '1908318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26628382', '小羊肖恩2：末日农场', '喜剧', '宁静祥和的农场里，小羊肖恩和伙伴们大开脑洞，做着各种挑战生命极限的游戏。这可气坏了牧羊犬，他接二连三制定禁令，防止羊们兴风作浪。肖恩哪能随便被人摆布？他想出鬼点子，通过电话订购了披萨，谁知却引来了一个始料未及的不速之客。来者是一个名叫噜啦的外星宝宝。虽然语言不通，但通过肢体语言，肖恩终于弄清噜啦想要找到飞船回到自己的家乡。经过一番缜密的策划，肖恩终于和这个新朋友踏上寻找飞船的征途。与此同时，不明飞行物的造访在小镇引起轰动，同时也惊动了一个专门追寻外星生物的政府机构。本来一波三折的寻找飞船之旅，如今又加入了气势汹汹的对手，肖恩他们将面临前所未有的考验……©豆瓣', '贾斯汀·弗莱彻', '威尔·比彻', 7.5, 23680, 'tt6193408', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2576481506.jpg', 0.3, 2.6, 32.1, 50.3, 14.7, '0.403782,0.072740,-0.503866,0.570425,-0.245139,-0.024283,0.543477,-0.075035,-0.371155,-0.024941,0.016502,0.559320,-0.178095,0.206320,0.319708,-0.084664,-0.315972,-0.296307,0.105998,-0.087239,-0.249375,-0.322297,-0.436607,-0.224979,0.140599,-0.104085,0.400414,0.161353,-0.251956,0.248740,0.076520,0.182088,-0.192358,0.487686,-0.154275,-0.062949,0.227393,0.018079,0.058160,0.109476,-0.127201,-0.131179,-0.104317,0.298835,-0.026380,0.319133,0.607645,-0.556934,-0.131300,-0.151614,0.269408,-0.359336,0.053339,-0.110069,0.154671,0.089360,-0.088810,0.066821,-0.103367,0.085274,0.058772,-0.051491,-0.867881,0.119011,-0.189028,-0.195620,-0.235266,0.019627,-0.042378,0.036410,0.018367,-0.374690,0.314656,0.655184,0.304699,0.462226,-0.209450,0.282187,-0.491688,-0.089991,0.667348,0.009478,-0.158006,0.245248,-0.108909,-0.450195,0.258689,-0.210290,-0.248318,-0.272371,0.436262,0.111369,-0.406671,0.114384,-0.699326,0.182684,-0.334292,-0.527242,0.095811,-0.468674,-0.263939,-0.778098,0.031187,0.083561,-0.048885,0.290761,-0.044264,-0.136565,0.782755,-0.842365,-0.061743,0.699818,0.162669,-0.478207,0.554532,-0.202148,0.010947,-0.250754,-0.004991,0.039088,0.129401,0.606221,0.031840,0.366952,0.165584,-0.218414,-0.499607,0.338928', '1420088', '3769423', '1793491', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26630714', '精灵旅社3：疯狂假期', '喜剧', '子孙满堂，亲朋和睦，吸血鬼伯爵德古拉（亚当·桑德勒 Adam Sandler 配音）在享受生命中最美好的一段时光。只不过喧嚣过后，他也陷入深深的落寞中，似乎冷酷的伯爵也开始期待美好的爱情了。善解人意的梅菲丝（琳娜·戈麦斯 Selena Gomez 配音）看透了老爸的心思，于是带着家人和朋友们踏上了一段充满惊喜的意外之旅。在百慕大的怪兽游轮上，德古拉邂逅了美丽的人类船长艾丽卡（凯瑟琳·哈恩 Kathryn Hahn 配音），他对这个美人一见钟情，却没有意识到对方来自死对头的范·海辛一族。与怪兽们缠斗上百年的亚伯拉罕·范·海辛（吉姆·加菲根 Jim Gaffigan 配音），意图利用这次千载难逢的机会将死对头德古拉以及他的伙伴们一网打尽……©豆瓣', '亚当·桑德勒', '格恩迪·塔塔科夫斯基', 6.6, 128406, 'tt5220122', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2530591543.jpg', 1, 10, 52.9, 27.8, 8.3, '0.294964,0.156030,-0.672575,0.705520,-0.056190,-0.426458,1.133513,-0.235742,-0.504046,-0.139673,0.142977,0.691500,-0.201452,0.328889,0.508913,-0.004553,-0.633445,-0.548043,-0.055933,-0.001420,-0.099673,-0.336647,-0.474261,-0.282896,-0.015552,-0.337868,0.573659,0.138678,-0.083456,0.577307,0.188018,0.368706,-0.128723,0.523227,0.015599,0.241565,0.354459,0.034246,-0.354411,-0.027041,-0.007426,0.019408,-0.216990,0.357144,-0.030339,0.309034,0.652474,-0.483677,0.172191,-0.019111,0.065433,-0.299823,0.208517,0.244960,0.072556,-0.216096,0.096084,0.116757,0.123337,-0.151221,-0.125716,-0.106719,-0.900894,0.022427,-0.017731,0.290254,-0.306966,0.580038,0.094481,-0.105941,0.127475,-0.135975,0.054023,0.208036,0.439087,0.332049,-0.123971,0.197846,-0.277407,0.199817,0.657081,0.133781,-0.284670,0.357456,-0.441075,-0.617211,-0.156665,-0.057217,-0.626619,-0.293630,0.626399,0.066965,-0.009258,0.725090,-0.842789,-0.155862,-0.245992,-0.045271,-0.080482,-0.426965,-0.115119,-0.728053,-0.157748,-0.489500,-0.256323,0.102355,0.192690,-0.280648,0.740446,-0.692008,0.121808,0.452870,0.118583,-0.091335,0.651837,0.083167,-0.026904,-0.390938,-0.209770,0.510106,0.032334,-0.050126,0.400099,0.261581,-0.161502,0.052638,-0.362116,0.768369', '3005387', '1316693', '25828589', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26630781', '我不是潘金莲', '剧情', '一个普通的农村妇女李雪莲（范冰冰 饰），为了纠正一句话，与上上下下、方方面面打了十年交道。打交道的过程中，她没想到一件事变成了另一件事，接着变成了第三件事。十年过去，她没有把这句话纠正过来，但她饱尝了世间的人情冷暖，悟明白了另外一个道理。李雪莲要纠正的这句话是她前夫说的。她前夫说：你是李雪莲吗？我咋觉得你是潘金莲呢？李雪莲要告诉大家的是：我不是潘金莲。©豆瓣', '范冰冰', '冯小刚', 6.7, 252030, 'tt5918090', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2408342182.jpg', 3.7, 10.1, 42.1, 34.6, 9.5, '0.176536,0.189134,-0.541638,0.630968,-0.557024,-0.309689,0.895388,-0.708720,-0.414455,-0.329027,-0.541934,0.195226,-0.481022,0.061766,-0.298433,0.512237,0.121865,-0.351621,0.219456,-0.356908,-0.439448,-0.519924,0.038677,-0.068763,-0.341926,0.376857,-0.122162,-0.110958,-0.527349,-0.326520,0.358275,0.291645,0.858367,0.368413,-0.264553,0.398756,-0.380559,0.695554,-0.187301,0.108269,0.472630,-0.376238,-0.347897,0.382426,0.047147,0.248809,0.039428,0.119956,-0.100325,0.252995,0.163568,-0.465397,0.084164,0.094369,0.338037,0.001374,0.142096,-0.157712,-0.131491,-0.551359,0.289628,-0.050324,-0.488263,-0.107152,-0.359735,0.387771,-0.675028,0.036527,-0.303347,0.134511,0.056948,-0.673568,0.463225,0.105357,0.517480,0.382058,0.100285,-0.207719,-0.786222,0.699317,1.119144,0.152071,-0.101034,0.563696,-0.012671,-0.583419,0.034461,0.295993,-0.184967,0.318086,0.061635,-0.486514,-0.048577,0.046290,-0.057758,-0.302315,0.217174,-0.270070,-0.289476,-0.465862,0.133904,0.618231,-0.029988,-0.593916,-0.368209,0.039816,0.326257,-0.350594,0.718773,-0.654653,0.094961,0.022737,0.207325,-0.913317,0.528185,0.498290,0.176397,-0.269563,0.626499,-0.121642,0.047529,-0.057191,0.685554,0.669752,0.568949,-0.064746,-0.148322,0.301440', '25721544', '26320029', '1298272', '1301376');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26631663', '尼斯·疯狂的心', '剧情', '尼斯·达·西尔维拉（Nise da Silveira）医生回到里约热内卢郊区的精神病医院工作。她拒绝采用新型高强度电击疗法来治疗精神分裂症患者。其他医生对其冷嘲热讽，她不得不使用医院已被废弃的作业治疗区开展工作。尼斯用图画、小狗和爱来帮助病人，开启了一场“革命”。', '格劳瑞·皮尔丝', '罗伯托·柏林厄', 8.1, 6374, 'tt2168180', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2509401725.jpg', 0.3, 1.4, 19.9, 52.3, 26.1, '-0.093355,-0.579785,0.040088,-0.139371,-0.124768,0.006609,0.512410,0.105386,-0.467976,-0.469225,0.600270,0.364055,0.129154,-0.065357,0.048186,-0.097798,-0.626518,-0.249483,0.344041,0.356959,-0.504165,-0.405489,-0.098010,-0.276776,0.106951,-0.476368,-0.065005,-0.626869,-0.323571,0.100301,-0.508681,0.519544,0.167565,0.194828,0.525926,-0.330621,0.091717,-0.778398,-0.418879,0.461057,0.703963,0.160557,-0.089758,0.236691,0.509989,0.379475,0.572520,0.134489,-0.087269,-0.626496,0.284741,-0.185919,-0.182579,0.370758,-0.131223,0.279807,0.401006,-0.004320,-0.258800,0.091580,-0.036755,-0.208552,-0.372093,-0.214213,-0.257739,0.171060,-0.085138,0.218199,-0.659450,0.104447,-0.240014,-0.569529,-0.021142,0.412434,-0.064121,0.649216,-0.319182,-0.325552,-0.584791,0.041672,0.144131,-0.278182,-0.448976,0.215068,-0.349710,-0.556874,0.444855,-0.356244,-0.126825,0.052582,-0.028099,0.015912,-0.541580,-0.164881,-0.618969,-0.249449,-0.664221,-0.607110,-0.189270,0.126326,0.222146,-1.345266,0.605140,0.360519,-0.455918,-0.530082,0.227907,-0.213318,0.456890,-0.935324,0.196709,0.362069,0.641938,-0.301730,0.185444,-0.341961,0.282962,-0.038246,0.039107,0.657820,-0.140899,1.205182,0.140544,0.430893,0.304987,0.092535,-0.407539,0.271769', '2369613', '1306809', '34961898', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26631751', '下众之爱', '剧情', '铁男（涩川清彦 饰）对外宣称自己是一名独立片导演，实际上出道这么多年能拿的出手的作品只有一部。平日里，他靠着导演的身份潜规则那些想要成名的女演员，四处骗吃骗喝，做导演的初心早已经淹没在了声色犬马的颓废生活之中。某日，铁男面试了一位名叫小南（冈野真也 饰）的新人女演员，这位看上去羞涩保守的女孩，在训练之时却爆发出了惊人的演技。像往常一样，铁男想要潜规则小南，但遭到了后者的强烈拒绝，之后，小南离开了铁男，加入了著名商业片导演门下，一举成名。受到小南的影响，铁男决定开足马力拍出好电影证明自己，一直暗恋着铁男的副导演阿守（细田义彦 饰）为了帮助铁男实现梦想，被卷入了黑道的纷争之中。©豆瓣', '涩川清彦', '内田英治', 7.2, 9530, 'tt4771704', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2407129507.jpg', 1.9, 6.2, 36.4, 42.8, 12.7, '-0.191257,0.115789,-0.550203,0.330990,-0.104193,-0.171909,0.645498,0.219551,-0.395939,-0.297900,0.095400,0.574671,-0.289489,0.105347,0.316462,-0.095538,-0.137555,-0.614158,-0.404915,-0.217801,0.041125,-0.065743,-0.201418,0.086776,-0.398806,-0.329554,0.789986,-0.184636,-0.543837,-0.044869,0.749553,0.157666,0.084858,0.018544,0.105670,-0.211712,0.020577,0.062828,-0.259606,0.330866,-0.033600,-0.075408,-0.105872,0.055365,-0.018262,0.495880,0.426694,-0.221323,-0.291835,0.020217,0.514183,-0.128978,-0.198254,0.037744,0.198701,0.149887,0.176131,-0.044687,0.171149,0.038074,0.232675,-0.208614,-0.356160,-0.062752,0.310408,0.069519,-0.583218,0.579242,0.173795,-0.148103,-0.147330,-0.354335,0.058209,-0.127932,0.336727,0.066178,0.026263,0.404263,-0.343176,0.723623,0.755030,0.362920,-0.411186,0.179745,-0.126481,-0.374673,-0.305591,-0.455087,-0.665790,0.010360,0.358515,-0.075808,-0.228018,0.029205,-0.319993,0.041135,0.023954,0.295494,-0.112468,-0.106055,0.101549,-0.771423,-0.049040,-0.308735,-0.000557,-0.126268,0.031167,-0.435452,0.903594,-0.809590,0.018306,0.216540,0.352197,-0.309941,0.581080,0.016849,-0.114275,-0.124397,-0.083481,-0.084631,0.217691,0.146419,0.288347,0.421218,-0.257736,-0.528914,-0.152815,0.266097', '1316589', '1908036', '3811356', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26633257', '地球最后的夜晚', '剧情', '罗紘武（黄觉 饰）因父亲离世再次回到贵州。12年前，好友白猫（李鸿其 饰）被杀，罗紘武在追查凶手左宏元（陈永忠 饰）的过程中，被凶手的情人万绮雯（汤唯 饰）所利用。从此以后，这个神秘的女人构成了他所有的记忆、欲望、信念和梦魇，一段追寻之旅让他发现了被隐藏多年的秘密……', '汤唯', '毕赣', 6.9, 209280, 'tt8185182', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2522256119.jpg', 6.8, 10.8, 31.2, 35, 16.1, '-0.044893,0.283971,-0.676734,0.609187,-0.223422,-0.209778,0.585668,-0.068066,-0.736417,-0.815888,-0.220801,0.621160,-0.194492,0.124876,-0.005082,-0.186484,0.100785,-0.887315,-0.144476,-0.143043,-0.257471,-0.236015,-0.067197,-0.144659,-0.174999,-0.218750,0.470785,0.557551,-0.167696,0.039872,0.359459,0.778542,-0.444377,0.210656,0.082746,0.155487,0.074557,-0.044999,-0.300618,0.123116,-0.117166,-0.674981,0.360315,0.431713,-0.491048,0.168942,0.877680,-0.389581,-0.005165,-0.256455,0.199220,-0.257765,-0.219827,-0.032287,0.218709,0.108890,-0.117010,0.302960,-0.331314,-0.164093,0.103946,-0.170630,-0.812319,-0.436991,0.271287,0.138841,-0.366381,0.118237,-0.167566,0.314093,0.045189,-0.191328,0.240082,0.224725,0.344562,0.214548,-0.138045,0.062450,-0.365558,0.299546,0.513258,-0.321638,0.265815,0.163492,-0.051801,-0.492313,-0.032496,-0.052803,-0.224536,0.305671,0.675130,0.155191,-0.163760,0.333157,-0.565952,-0.318703,-0.196781,0.346889,0.038409,-0.242847,-0.158325,-0.209902,-0.216548,-0.392037,0.004486,-0.002996,-0.079504,-0.487378,0.442278,-0.645124,0.628772,0.407543,0.105289,-0.700150,0.424409,-0.248856,0.104693,-0.467450,0.336971,0.704974,0.326042,0.066381,0.236781,0.036980,-0.161312,0.015876,-0.522975,0.368547', '2988294', '4881604', '1301022', '3670447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26634179', '刀剑神域：序列之争', '科幻', '2022年，天才编程者茅场晶彦所开发的世界最早的完全潜行专用装备设备《NERvGear》。这个革命性的机器给VR（假想现实）世界带来了无限的可能性。那之后经过了4年。。。。。《NERvGear》的后继品VR机为了对抗《AmuSphere》（第二代民用完全潜行机），发售了一个次世代的可穿戴设备《Augma》替换了完全潜行机能，是一个对AR（增强现实）功能进行了最大限度扩大的最先进机种。由于《Augma》在觉醒状态下也可以安全和便利地使用，因此一瞬间便在玩家当中传开了。这个杀手级内容，被叫做《Ordinal Scale序列之争（OS）》，是《Augma》专用的ARMMO RPG。亚斯娜和伙伴们会玩的这个游戏，桐人也准备参战了。。。。', '松冈祯丞', '伊藤智彦', 7, 38182, 'tt5544384', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2498371582.jpg', 1.1, 8.9, 41.5, 34.2, 14.3, '0.334167,0.480052,-0.471931,0.556103,-0.155007,0.084852,0.354073,-0.144827,-0.433846,-0.388438,0.219895,0.839951,-0.035725,-0.102506,0.147968,-0.159366,-0.497279,-0.411606,-0.157644,-0.302298,-0.749948,-0.271008,-0.291171,-0.258883,-0.130552,-0.662341,0.922706,-0.175266,-0.597648,0.146610,-0.016707,0.157680,0.166425,0.410508,-0.119131,-0.275538,0.205095,-0.318139,-0.068730,0.716071,-0.415007,-0.120704,0.353630,0.089228,0.050617,0.250837,0.980268,-0.431818,-0.198315,0.096031,0.435585,-0.231471,-0.206641,-0.216252,0.219586,-0.095664,-0.131379,0.068550,-0.032152,0.310666,-0.145557,-0.170635,-1.321713,-0.300773,0.070570,-0.529697,-0.328170,0.391559,-0.231840,-0.054587,-0.208727,-0.128992,0.362319,0.411280,0.424001,0.441235,-0.493864,-0.175198,-0.531123,0.359733,0.107571,-0.242647,-0.605644,0.660467,-0.223019,-0.817318,-0.562986,-0.479382,-0.144497,-0.299662,0.479730,0.379500,-0.256961,0.251713,-1.090422,0.437854,-0.122160,-0.601028,-0.031890,-0.258860,-0.058673,-0.684902,-0.096736,-0.479988,-0.274932,0.171276,0.139913,-0.282051,1.009796,-1.001662,0.017433,0.627132,0.215202,-0.706678,0.566884,-0.131666,0.286539,-0.361284,0.047530,-0.126445,-0.148760,0.620719,0.076519,0.543865,0.093962,-0.328213,-0.569581,0.547900', '26759820', '24284209', '25774050', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26635319', '伤物语2：热血篇', '喜剧', '物语系列唯一男主角，阿良良木历和三位吸血鬼猎人的战斗一触即发！阿良良木历接受忍野咩咩的建议，答应姬丝秀忒替她取回力量，但他必须面对阻挡在他面前三位强大的吸血鬼猎人，他能否在强敌环伺中生存，达成使命？', '神谷浩史', '新房昭之', 8.6, 7479, 'tt5084196', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2364765328.jpg', 0.7, 1.8, 12.6, 35.6, 49.3, '0.115872,0.220616,-0.356196,0.283624,-0.215635,0.053011,0.396644,-0.213147,0.005216,-0.257996,0.572382,0.696803,0.252861,-0.192653,0.242652,-0.380268,-0.011472,-0.331596,0.151981,0.420576,-0.128999,-0.352079,-0.581446,-0.093368,-0.233247,-0.339764,1.281310,0.045325,-0.352762,0.013527,0.344674,0.529451,-0.364137,0.068687,0.001136,-0.598382,-0.025865,-0.064868,-0.632447,0.532675,-0.276535,-0.141149,0.013940,0.689063,0.263994,0.116329,0.341398,-0.953840,-0.058323,-0.171735,-0.141470,-0.516588,-0.055402,0.345874,0.046215,-0.362571,0.014947,0.337536,0.253423,-0.151027,-0.191908,-0.185512,-0.915581,-0.000666,0.127917,0.066473,-0.413056,0.227371,-0.023208,-0.012835,0.422948,0.032806,-0.007341,0.386009,0.403092,0.207107,-0.427819,0.142407,-0.221792,-0.061661,0.787308,-0.179914,-0.083422,-0.135457,0.033512,-0.686899,-0.249819,-0.644462,-0.482332,0.109110,-0.166045,0.531595,-0.335107,0.330865,-0.889121,-0.349896,-0.011247,-0.189718,-0.171166,-0.598579,0.231437,-0.552265,-0.003281,0.069957,-0.076994,0.033537,0.294193,-0.826905,0.913046,-0.668391,0.127580,0.449091,0.651399,-0.339402,0.598916,0.441560,0.437213,-0.375690,-0.015858,0.201322,0.170261,-0.086375,0.669667,0.066218,0.096039,0.132362,-0.320570,0.615106', '26759819', '3001114', '26759820', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26635321', '伤物语3：冷血篇', '喜剧', '怪異の専門家・忍野メメの助力も得て、3人の強敵との戦いに勝ち抜いた阿良々木暦。吸血鬼キスショットの四肢を奪い返すことに成功し、再びキスショットの元を訪れるが、そこで暦は吸血鬼の恐るべき本質を知る。暦は取り返しのつかない自分の行為を悔やみ……『魔法少女まどか☆マギカ』の新房昭之総監督と、アニメーション制作会社・シャフトのタッグで、西尾維新の原作小説をアニメ映画化。『I鉄血篇』『II熱血篇』に続き、第3弾となる本作でついに物語は完結する。人間の体に戻るため3人の強敵と戦ってきた主人公・阿良々木暦に待ち受ける残酷な運命とは？ 声の出演は神谷浩史、坂本真綾ら。', '神谷浩史', '新房昭之', 8.8, 7269, 'tt5084198', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2449813668.jpg', 0.6, 1.9, 10.6, 32.6, 54.2, '-0.277606,-0.126511,0.223879,-0.215602,0.459718,0.041859,-0.071095,0.671042,-0.021904,-0.268879,-0.045747,0.350960,-0.150772,-0.071328,0.122407,0.052397,-0.120298,0.030968,-0.193040,0.027817,0.078091,0.347370,0.373389,0.377912,-0.306214,-0.565841,0.885331,0.177477,0.134837,-0.422154,0.224634,0.602861,-0.514810,-0.563421,0.576426,0.500731,-0.116269,0.004485,0.141313,0.063440,-0.553257,-0.430534,-0.114208,-0.121000,0.517288,-0.120443,1.020781,-0.113875,0.177829,-0.523121,0.397718,0.270544,-0.397701,0.068360,-0.207595,-0.092322,0.006148,0.187720,0.185162,-0.168524,0.144384,0.318041,-0.148085,0.046837,0.182135,-0.065825,0.069445,0.294842,-0.322389,0.370943,0.135230,0.166060,-0.380191,-0.249931,0.261881,-0.158645,-0.053288,0.037763,0.496869,-0.178915,0.404269,-0.354306,-0.361530,0.268929,0.259395,-0.672941,-0.178974,-0.253003,-0.097465,-0.140505,0.143179,0.229360,0.412511,-0.332244,-0.065867,-0.202952,-0.150679,0.486517,0.200958,0.372604,0.192708,-0.267935,0.140893,0.006373,-0.330002,0.119320,0.805646,-0.101566,0.733507,-0.155963,-0.066410,0.614440,0.072737,-0.010510,-0.044181,-0.305971,-0.001683,-0.222476,0.353509,0.050553,0.134075,0.533054,0.715859,0.022390,-0.307158,0.274935,-0.315888,-0.236864', '26817016', '27167055', '35307624', '2977870');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26635323', '无限之住人', '剧情', '传说中的百人斩万次（木村拓哉 饰），曾经经历了失去妹妹的痛苦，此后失去升至希望的他，被一个神秘的老婆婆赋予了不死之身的能力。可是永世的伴随永恒的痛苦，万次始终不忘寻找终结永恒的机缘。这一日，少女浅野凛（杉咲花 饰）找上门来。原来，凛是无天一流师父的女儿，不久之前，被逐出师门的天津影久率领他的剑客集团对凛的一家展开了残酷的屠杀。为了替家人报仇，凛只得求助万次。在此之后，黑衣鲭人（北村一辉 饰）、乙橘槙绘（户田惠梨香 饰）等剑客集团高手相继袭来。不死万次以一己之力对抗豪强剑客……本片根据沙村广明的同名漫画改编。©豆瓣', '木村拓哉', '三池崇史', 6, 6803, 'tt5084170', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2395534781.jpg', 3.9, 21, 50.9, 17.6, 6.7, '-0.123271,0.192108,-0.344803,0.440484,-0.017273,-0.281086,0.332277,0.013909,-0.304749,-0.341330,0.324840,0.677978,0.175175,-0.040985,0.201315,-0.013332,0.290792,-0.626219,-0.154534,-0.077902,-0.106941,-0.080783,-0.202736,0.209764,-0.063251,-0.322266,0.797021,0.193195,-0.018355,0.349399,0.256245,0.407048,-0.152896,0.162482,-0.199169,0.192151,0.115761,-0.046642,-0.228718,0.420175,-0.100999,-0.272120,0.139534,0.312015,-0.503907,0.220461,0.489770,-0.283826,-0.056529,-0.364372,0.346335,-0.238263,-0.336697,0.166258,0.281125,0.033109,0.046071,0.315439,-0.153117,-0.322773,-0.000660,0.030303,-1.086720,-0.037731,0.562713,0.006981,-0.327034,0.608032,-0.194483,0.098220,0.005259,0.007750,0.041231,0.197660,0.268080,0.115015,-0.161897,-0.019493,-0.429246,0.533032,0.701469,-0.348974,-0.061665,0.052785,0.063764,-0.115015,-0.187576,-0.583811,-0.546238,0.117869,0.151790,0.181003,-0.068057,0.136030,-0.417656,-0.124950,-0.389841,0.150937,-0.055002,-0.123888,-0.207152,-0.169990,-0.129782,-0.157648,-0.097839,0.045707,0.266938,-0.309387,0.746256,-0.711482,0.223476,0.377642,0.349028,-0.388774,0.750543,-0.035787,0.040927,-0.326650,0.127002,0.329531,0.153493,0.207113,0.195177,0.058676,0.133761,0.035667,-0.248319,0.280548', '26678784', '27602116', '1793491', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26636537', '巴比龙', '剧情', '影片翻拍自1973年史蒂夫·麦奎因与达斯汀·霍夫曼主演的同名经典越狱电影，讲述了查理·汉纳姆饰演的职业扒手亨利被人陷害杀害一名皮条客，从而流放至大海环绕的法属圭亚那的监狱服刑，因为胸前有一处蝴蝶纹身，所以同窗狱友都叫他“巴比龙”。在踏入监狱的那一天开始，巴比龙就策划越狱，但 越狱是需要用金钱去贿赂看守，同时购买逃跑船只的，于是他将目光投向了同时服刑的伪造专家，同时是百万富翁，由拉米·马雷克饰演的Louis，用保证德加安全的方式获得其金钱资助，两人结成同盟……', '查理·汉纳姆', '迈克尔·诺尔', 7.4, 43264, 'tt5093026', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2561899354.jpg', 0.1, 2.7, 37.8, 47.3, 12.1, '0.059709,-0.363413,-0.377926,0.668148,-0.079568,-0.220050,0.684035,0.066310,-0.176487,-0.153422,0.407761,0.599431,-0.076065,0.090307,0.283203,0.017871,-0.396935,-0.791519,-0.097127,-0.201412,-0.198036,-0.522788,-0.171780,-0.415819,-0.055843,-0.464686,0.666036,-0.070005,-0.306193,0.208905,0.352042,0.441935,-0.188020,0.035355,-0.083742,0.028857,0.177571,-0.187431,-0.334389,0.367972,-0.024200,-0.237052,-0.154295,-0.127947,0.089324,0.440207,0.653062,-0.106147,0.162299,-0.019539,0.402912,-0.423588,0.046363,0.076189,0.129312,0.088319,0.130784,0.200722,-0.236816,0.148217,0.036186,-0.154810,-0.737784,-0.111688,-0.000684,0.001916,-0.424166,0.163380,-0.130568,0.170867,0.156973,-0.137818,0.078427,0.077784,0.170250,0.284382,0.013680,-0.001649,-0.583457,0.361363,0.405044,-0.161359,-0.102701,0.013889,-0.032956,-0.571394,-0.008497,-0.075311,-0.052736,-0.139969,0.585293,-0.028893,-0.125807,0.253903,-0.627276,-0.213661,-0.276071,-0.170590,0.144854,-0.279313,-0.011589,-0.820879,-0.111359,-0.126188,0.006707,-0.031042,0.092984,-0.403735,0.540224,-0.476663,0.177266,0.679675,0.354493,-0.424305,0.796153,-0.070347,0.163849,-0.075411,-0.120496,0.082336,0.440328,0.391006,0.313332,0.152234,0.114711,-0.222725,-0.260100,0.303460', '1294917', '4301278', '3597344', '1293433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26636712', '蚁人2：黄蜂女现身', '动作', '由于在“内战”中站到了美国队长一方，蚁人斯科特·朗（保罗·路德 Paul Rudd 饰）遭到了FBI的禁足惩罚。眼看离真正的自由还有几天功夫，偏偏麻烦找上门来。原来初代蚁人汉克·皮姆（迈克尔·道格拉斯 Michael Douglas 饰）通过研究发现，他的妻子黄蜂女（米歇尔·菲佛 Michelle Pfeiffer 饰）一定还活在量子领域，而斯科特是能够将妻子带回现实世界的唯一希望。不由分说，汉克的女儿霍普（伊万杰琳·莉莉 Nicole Lilly 饰）将斯科特带出房间。此后不久，他们不仅要躲避FBI的纠缠，更要提防来自神秘势力的袭击，而“幽灵”的出现更将斯科特等人带向前所未有的混乱当中。斯科特能否顺利获得自由？初代黄蜂女是否还存活在量子领域的某处？©豆瓣', '保罗·路德', '佩顿·里德', 7.3, 427781, 'tt5095030', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2529389608.jpg', 0.4, 4.1, 39.2, 45, 11.3, '-0.013767,0.136548,-0.712407,0.368165,-0.217663,-0.136270,0.471251,0.199988,-0.532520,-0.277818,0.335887,0.524778,-0.077452,-0.210321,0.373725,-0.033644,-0.332539,-0.303894,0.103498,-0.222636,-0.445568,-0.466504,-0.407120,-0.252422,0.109731,-0.742788,0.417837,-0.007167,-0.014923,0.202855,0.143854,0.581204,-0.304701,0.438317,-0.178199,-0.129330,0.255043,-0.083853,-0.409450,0.473668,0.039477,-0.158728,-0.137325,-0.124572,-0.081228,0.274629,0.633828,-0.390112,0.097946,-0.213538,0.104560,-0.355175,-0.092156,0.237629,0.220550,-0.256919,-0.144380,0.224677,-0.152706,0.189265,0.013088,-0.168954,-0.614324,0.256097,0.056054,0.206326,-0.409712,0.210164,-0.067201,-0.025988,0.142369,-0.214720,0.080272,0.351746,0.177020,0.262405,-0.107204,0.180640,-0.451220,-0.242149,0.319518,-0.471754,-0.227369,0.218459,0.103550,-0.387869,-0.156988,-0.109680,-0.405155,-0.224912,0.525457,0.257089,-0.098624,0.237782,-0.607695,-0.008941,-0.438134,-0.322380,0.089997,-0.534554,-0.081758,-0.716027,-0.081992,-0.059596,0.042434,0.166678,-0.033094,-0.308427,0.639753,-0.631583,0.333133,0.542622,0.437753,-0.412919,0.394799,0.041511,0.285145,-0.313597,-0.122997,0.331248,0.524884,0.277089,0.086444,0.146177,0.102531,-0.176887,-0.118126,0.310791', '1307897', '1420088', '4014396', '1293656');
