INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26639958', '春娇救志明', '剧情', '2009年，春娇志明后巷邂逅，演绎烟火世界中的极致浪漫。2017年，饮食男女分分合合，志明仍未长大，春娇急需爱情救火。相恋多年的春娇与志明，渐渐从“可遇不可求”的惊涛骇浪变成了普通的情侣。面临“中女危机”的春娇，深感颜值危机，可志明却还如同孩子一般无法长大。不仅两人平日生活磕磕绊绊不断，让春娇更为担心的是，家里的神秘来访者Flora不仅年轻漂亮，神经大条，还要跟志明借精生子。想要修补二人关系的春娇策划了一场“重燃爱火”的台湾行，在台湾，两人的矛盾才刚刚开始……八年爱情紧急SOS！世间红男绿女，且看春娇志明。“志明与春娇”系列第三部温暖回归，好久不见，好救不贱！', '余文乐', '彭浩翔', 7, 204083, 'tt5956006', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2456056900.jpg', 1.7, 8.2, 40.8, 35.4, 13.9, '0.225609,-0.054214,-0.576078,0.064077,0.143271,-0.287701,0.707589,0.124498,-0.494239,-0.105799,0.114855,0.508628,-0.378642,0.062385,-0.150763,-0.157171,-0.135438,-0.671748,0.058583,-0.026186,0.113360,-0.118135,-0.307960,0.332000,-0.199295,-0.357630,0.562993,0.200578,0.099267,0.476732,0.021007,0.146875,-0.310790,0.318896,-0.186244,0.010485,0.085592,0.467147,-0.861858,-0.203901,0.062520,-0.039267,-0.180152,0.014988,-0.172740,0.047846,0.679361,-0.099991,-0.076466,-0.105474,0.533611,0.081982,-0.332453,0.034526,0.040569,-0.251660,0.419613,0.485464,-0.193346,0.002564,-0.065328,-0.211939,-0.614711,0.269824,0.491253,0.107309,-0.362847,0.439697,0.145782,-0.142583,0.176725,-0.366087,0.116718,0.543704,0.428743,0.666901,-0.327746,-0.120783,-0.280216,0.419694,0.781047,0.145010,-0.483254,0.631455,-0.227603,-0.224854,0.074996,-0.315262,-0.681357,0.076755,0.061008,0.324321,-0.550553,0.700287,-0.588791,0.341694,-0.253406,0.120319,0.158300,-0.287274,-0.139850,-0.413606,-0.509917,-0.646959,-0.206115,0.185044,0.206039,-0.207299,0.689725,-0.409600,0.214052,0.249236,0.060469,-0.499112,0.565129,0.378605,-0.089065,-0.367235,0.052891,0.209584,-0.574927,0.108454,0.255012,0.261669,-0.282019,0.237271,-0.168699,0.287087', '30301264', '26321184', '1294713', '3715144');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26640371', '犬之岛', '喜剧', '故事发生在未来的时空之中，犬流感的肆虐让市长（野村训市 配音）颁布的狗狗流放法案，将城市里的所有犬类都投放到了“垃圾岛”之上，任它们自生自灭，市长家的护卫犬点点（列维·施瑞博尔 Liev Schreiber 饰）首当其冲。就这样，本来被养在家中锦衣玉食的狗狗们，都成为了要在垃圾堆里找食物吃的流浪狗。首领（布莱恩·科兰斯顿 Bryan Cranston 配音）、君主（爱德华·诺顿 Edward Norton 配音）、老板（比尔·默瑞 Bill Murray 配音）、公爵（杰夫·高布伦 Jeff Goldblum 配音）和国王（鲍勃·巴拉班 Bob Balaban 配音）是岛上的五只流浪狗，它们通常结伴行动。一天，市长的养子阿塔里（科宇·兰金 Koyu Rankin 配音）忽然驾驶着飞机降落在了岛上，他要在这里寻找他一生的挚友点点。©豆瓣', '布莱恩·科兰斯顿', '韦斯·安德森', 8.2, 224254, 'tt5104604', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2499734013.jpg', 0.3, 1.3, 16.4, 49.5, 32.5, '0.221959,-0.169188,-0.538252,0.546005,-0.007046,-0.168227,0.423919,0.235138,-0.317483,-0.026193,0.343192,0.747288,-0.055299,0.411215,0.319453,0.080926,-0.455756,-0.289767,-0.049745,-0.252296,-0.031757,-0.288983,-0.307361,-0.332483,0.091210,-0.240527,0.514265,-0.195942,0.064953,0.142396,0.170438,-0.024551,-0.199397,0.253147,-0.208833,0.242012,0.298945,-0.274146,0.180412,0.200703,-0.065310,0.021439,0.070286,-0.143684,0.535481,0.149541,0.698855,-0.485083,0.072239,-0.400067,-0.017929,-0.291426,0.280741,0.115312,0.641712,-0.097119,0.181381,0.497581,-0.161421,0.125687,0.051234,0.017916,-0.361516,-0.247985,-0.165838,0.378321,-0.553566,0.228431,-0.038001,0.046384,0.162328,-0.215671,0.597473,0.052002,0.017862,0.489732,0.162928,0.147649,-0.366473,0.407481,0.502750,-0.130628,-0.277942,-0.064139,-0.074738,-0.405176,0.113454,-0.034392,-0.561201,-0.383983,0.087311,-0.169958,-0.280788,0.476261,-0.641215,0.183602,-0.175054,-0.344639,-0.194810,-0.223117,-0.116818,-0.666068,0.281674,-0.193897,0.243177,-0.002650,0.219260,0.024998,0.477287,-0.565513,0.177519,0.564314,0.312293,0.024985,0.585293,-0.260237,0.296608,-0.119581,0.075026,-0.065327,0.293791,0.537971,0.192879,0.411759,0.123002,-0.211202,-0.356502,0.419126', '1294917', '3178770', '35