INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26640849', '黑执事：豪华客船篇', '剧情', '19世纪的英国，名门贵族凡多姆海威家的执事塞巴斯蒂安·米卡利斯跟随着13岁的主人夏尔·凡多姆海威作为“女王的番犬”每天都背负着黑社会的肮脏工作。有天，在一次煞有介事的私语中他们得知了关于「死者复生」的传闻。为了调查事情真相，塞巴斯蒂安他们进到了豪华客船「坎帕尼亚号」，等待他们的到底是——（转自百度百科）', '小野大辅', '阿部记之', 8.6, 11889, 'tt5476944', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2497235921.jpg', 0.4, 1.3, 12.6, 38.1, 47.6, '0.358813,-0.288139,-0.271740,0.185016,0.052320,-0.020666,0.534655,-0.063312,-0.675640,-0.383263,0.326609,0.630977,-0.184011,0.273518,0.405272,0.123440,-0.654225,-0.464954,0.143045,-0.453092,0.065991,-0.475162,-0.265788,-0.291215,-0.010388,-0.299416,0.161477,-0.030254,0.096898,0.290761,0.168238,0.466195,-0.221871,-0.010877,-0.358081,0.014061,0.423281,-0.022758,-0.119263,0.005746,0.048613,0.015506,-0.046579,0.191467,0.494073,0.487832,0.601630,-0.699585,-0.087211,0.016747,0.223266,-0.093959,0.074832,0.088499,0.519580,-0.041790,0.237144,0.740276,-0.050471,-0.079508,-0.259466,0.198733,-0.537479,-0.361060,0.179654,0.319270,-0.469626,0.322546,-0.264565,0.080967,0.186110,-0.106815,0.193457,0.440403,-0.008314,0.454704,0.206535,0.050567,-0.548785,-0.016350,0.568212,0.265536,-0.034497,0.142270,-0.013746,-0.667882,-0.237569,-0.183429,-0.409147,0.028125,0.269128,-0.225508,-0.052895,0.512802,-0.333991,-0.103353,-0.285705,-0.542094,0.021325,-0.035967,-0.377249,-0.605917,-0.015301,-0.241441,0.075251,0.066754,0.051837,-0.344449,0.436747,-0.732200,0.232732,0.602587,0.238438,-0.422485,0.619071,-0.102851,0.111711,-0.384806,-0.187626,0.221013,0.325976,0.594221,-0.148129,0.288032,0.466314,-0.301077,-0.217618,0.281863', '3178770', '5384590', '25662329', '2297262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26642033', '小黄人大眼萌：神偷奶爸前传', '喜剧', '影片是2015年推出的小黄人独立电影《小黄人大眼萌》的直接前传。作为《神偷奶爸》的衍生作品，讲述了小黄人们在“前格鲁”时代为其他主人服务的经历，不过少年格鲁曾经出现在这部衍生电影里，续集将围绕他与小黄人们结缘的过程展开。', '史蒂夫·卡瑞尔', '凯尔·巴尔达', 7.1, 101812, 'tt5113044', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2877522569.jpg', 0.7, 5.9, 44.3, 36.1, 13, '-0.144036,-0.027664,-0.360614,0.612441,0.203692,0.156075,0.654792,-0.038645,-0.454712,-0.322770,0.105126,0.559587,-0.543730,0.264736,0.156453,-0.267909,-0.454390,-0.609058,-0.445480,-0.025371,0.011939,-0.078949,-0.322161,-0.438300,-0.346630,-0.500783,0.840270,-0.107721,-0.666385,-0.204427,0.522787,-0.133541,-0.316160,-0.228761,-0.028717,0.296871,-0.255895,0.038523,-0.253922,0.298198,-0.080627,-0.434193,-0.421748,-0.590364,0.128082,0.189532,1.068684,-0.621508,-0.062770,-0.204366,0.738571,-0.210380,-0.180885,-0.450732,-0.137681,0.501766,0.412519,-0.092564,0.066608,-0.019961,0.009889,-0.711843,-0.685295,0.118011,0.210906,0.231796,-0.504288,0.140307,-0.032234,0.163990,0.364890,-0.582157,-0.070419,-0.109250,0.575424,0.238410,0.152727,0.256914,-0.216567,0.609429,0.508420,0.010340,-0.322490,0.487177,-0.083047,-0.675065,-0.616008,-0.067002,-0.629422,0.185203,0.319464,-0.119748,-0.035808,0.540392,-0.856186,0.059071,0.174124,-0.496788,0.236514,0.057930,-0.069849,-0.837522,-0.281171,-0.355862,0.148600,-0.383045,0.209166,-0.452358,1.323537,-0.897755,0.470866,-0.014700,0.182745,-0.393713,1.108563,-0.219905,0.124771,-0.268216,0.047135,0.011003,0.002578,0.258371,0.251325,0.288253,-0.189413,-0.350123,-0.388412,0.468159', '27167055', '25863940', '1322847', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26642163', '父亲与伊藤先生', '剧情', '三十三岁的山中彩（上野树里 饰）一直过着形单影只的独居生活，一次偶然中，她结识了名为伊藤（中川雅也 饰）的男子，尽管伊藤比彩年长二十岁，没有一分正式的工作，整日里过着得过且过的随意生活，但他身上散发出的温柔和魅力依然捕获了彩的心，两人开始了同居生活。彩的父亲（藤龙也 饰）是一个倔强而又强硬的老头子，在一场矛盾中，他竟然以离家出走的方式进行抗议，在彩并不知情的情况下大刺刺的搬进了她家，就此知道了女儿一直隐瞒的恋情。对于这个年纪比自己小不了几岁的准女婿，老头子是各种的看不上，他和彩之间的隔阂，亦因为距离的拉近而濒临爆发的边缘。©豆瓣', '上野树里', '棚田由纪', 7.7, 10223, 'tt5461596', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2365303540.jpg', 0.4, 1.4, 28.3, 53.2, 16.7, '0.295569,0.113785,-0.756311,0.713213,-0.328676,-0.187467,0.903837,0.153410,-0.537281,-0.220744,0.068713,0.704821,-0.128822,0.551825,-0.043070,-0.091968,-0.097966,-0.841985,-0.112912,-0.097539,-0.187476,-0.522352,-0.326309,0.087750,-0.393458,-0.297647,0.432429,0.220566,-0.197410,0.662983,0.464177,-0.013845,0.090123,0.633917,-0.236160,-0.216501,-0.216366,0.383787,-0.077263,0.077741,0.087571,-0.400555,-0.154115,0.224122,0.289155,0.730969,0.674073,-0.426929,-0.323564,-0.008046,0.342730,0.045979,-0.264528,0.317794,0.462133,-0.007161,0.350757,0.124121,-0.265519,0.072620,0.004300,-0.116340,-0.674520,0.170638,0.040403,0.087567,-0.684958,0.777756,0.021274,-0.250921,0.004192,-0.280562,0.197715,0.123288,0.059018,0.305576,-0.447613,-0.028800,-0.378567,0.029086,0.718669,0.273329,-0.360290,0.427819,-0.444465,-0.388753,-0.405936,-0.468735,-0.519878,-0.055107,0.116039,0.136248,-0.366289,0.265604,-0.564651,0.290540,-0.196416,0.034669,-0.093234,-0.443374,-0.009238,-0.303358,-0.277227,-1.014039,-0.536843,0.181175,0.033697,-0.423204,0.603264,-1.072366,0.159095,0.464627,0.378586,-0.432402,0.532541,0.359725,0.053921,-0.155342,-0.228935,0.234934,-0.393231,0.122876,0.238474,0.592015,-0.123340,-0.099610,-0.368856,0.667263', '1304989', '21766698', '1390020', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26644002', '傲娇与偏见', '喜剧', '唐楠楠（迪丽热巴 饰）是一个满脑子都塞着各种奇奇怪怪的念头的北漂写手，苦苦挣扎在温饱线上的她渴望着有一天能够成为拥有众多粉丝的网文大佬。一场意外中，唐楠楠邂逅了名为朱侯（张云龙 饰）的男人，两人最初的相识并不愉快，但是在阴差阳错之下，唐楠楠和朱侯竟然住进了同一屋檐下，成为了室友。萧见君（高伟光 饰）是朱侯的好友，他深深的被唐楠楠的古灵精怪吸引，对她展开了热烈的攻势。然而，萧见君对唐楠楠的追求，却三番五次的遭到朱侯的阻挠，在朱侯的心里，又在打着怎样的算盘呢？不知不觉中，一场惊心动魄的三角恋情拉开了帷幕。©豆瓣', '迪丽热巴', '李海蜀', 4.7, 89920, 'tt6857276', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2455810613.jpg', 25.4, 31.3, 30.5, 8.8, 4, '0.575046,0.217565,-0.690063,0.710414,0.171991,-0.009815,0.703464,-0.041518,-0.484488,-0.011714,0.163564,0.645069,-0.671365,0.545688,0.172310,-0.145071,0.078632,-0.899320,-0.181592,-0.041987,-0.230143,-0.293530,-0.443724,-0.004743,-0.139250,-0.088638,0.629767,0.251431,-0.239365,0.347943,0.723586,0.205109,-0.266763,0.752305,-0.154136,0.253727,0.072929,0.136481,-0.095327,0.133830,0.089214,-0.443283,-0.187761,0.491475,-0.152180,0.397436,0.784442,-0.567093,-0.078171,0.313431,0.342237,-0.497565,-0.161092,0.225798,0.377395,0.240341,0.115961,-0.050233,-0.137010,0.089243,0.292667,0.075211,-0.671107,-0.015667,0.233610,0.252944,-0.662997,0.877468,0.077885,-0.019084,-0.042888,-0.164658,0.192661,0.347992,0.197796,0.403196,-0.271771,-0.019898,-0.413837,0.163222,0.710414,0.302536,-0.191999,0.553836,-0.384722,-0.353439,-0.195546,-0.161561,-0.697058,-0.350222,0.444740,0.061437,-0.153302,0.352859,-0.691628,0.194642,-0.132810,0.081252,0.028321,-0.559874,-0.149565,-0.354178,-0.197655,-0.712311,-0.321072,0.311683,-0.174247,-0.453689,0.841527,-1.107092,-0.054663,0.462191,0.360991,-0.096027,0.647259,0.225920,-0.025528,0.077621,-0.168498,0.083171,-0.125227,0.012461,0.343521,0.555053,-0.297741,0.030467,-0.376879,0.520076', '21766698', '1292219', '35030151', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26644205', '安娜贝尔2：诞生', '悬疑', '美国中西部某个小镇，玩偶制作师塞缪尔·穆林斯（安东尼·拉帕格利亚 Anthony LaPaglia 饰）和妻子埃丝特·穆林斯（米兰达·奥图 Miranda Otto 饰）女儿安娜贝尔（萨马拉·李 Samara Lee 饰）过着幸福无忧的生活，然而突如其来的车祸夺走了安娜贝尔的生命，穆林斯一家的生活从此陷入黑暗之中。12年后，一辆老旧的大巴拉来了修女夏洛特（斯黛芬妮·西格曼 Stephanie Sigman 饰）及其收养的孩子，从此之后，穆林斯的房子便成为了她们暂时落脚的新的孤儿院。此时的塞缪尔面色阴郁，他引领孩子们参观这座房子，却独独禁止女孩们步入安娜贝尔的房间。好奇心颇重的琳达和珍妮丝没有听从塞缪尔的话，她们由此打开了恐怖的大门……©豆瓣', '斯黛芬妮·西格曼', '大卫·F·桑德伯格', 6.8, 48113, 'tt5140878', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2465524814.jpg', 1.2, 8.3, 48.7, 30.8, 10.9, '0.441246,0.097323,-0.597234,0.445182,-0.115368,-0.514393,0.889745,0.310783,-0.377149,-0.349611,0.226929,0.758690,-0.055085,0.414772,0.263530,0.435917,-0.659517,-0.413010,-0.154281,-0.339750,-0.258387,-0.306007,-0.065748,-0.284233,-0.030794,-0.344789,0.446662,-0.151228,0.078181,0.372411,0.013063,0.488385,0.104249,0.232151,-0.043006,0.368427,0.303415,-0.291612,-0.079865,0.015891,-0.167506,0.186329,-0.152664,0.144426,0.301549,0.228465,0.766450,-0.377514,0.244324,-0.226268,0.123431,0.154958,0.234811,0.108771,0.067093,-0.265045,0.366397,0.061610,-0.412521,-0.203764,0.259849,-0.257696,-0.309757,0.350334,0.015255,0.038278,-0.428594,0.357718,-0.252764,-0.099644,0.085749,-0.331269,0.065984,0.282721,0.114251,0.439279,-0.079322,0.076973,-0.409605,-0.060538,0.389475,-0.233517,-0.365781,0.277307,-0.533447,-0.255484,-0.049919,-0.043049,-0.658765,-0.054988,0.551131,0.187281,0.026130,0.405161,-0.649419,-0.249264,-0.619134,-0.181953,0.097791,-0.225158,-0.160514,-0.865099,0.095128,-0.146846,-0.193198,-0.117633,-0.149525,0.071759,0.591084,-0.600895,0.361503,0.209773,0.355810,-0.210078,0.562707,-0.357947,0.518669,-0.007140,-0.006535,0.679638,-0.043565,0.380452,0.283488,0.615783,-0.024595,0.001112,-0.168876,0.623211', '1316693', '10466639', '1297659', '1302133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26646360', '一周的朋友', '剧情', '拥有美丽外表的藤宫香织（川口春奈 饰）是班上品学兼优的优等生，但奇怪的是，她的周围竟然一个朋友都没有，香织对待任何人都是冷若冰霜的态度，忧愁的气氛也似乎总是围绕在她的周身。这样的香织吸引了长谷佑树（山崎贤人 饰）的注意，他找到了香织，软磨硬泡死缠烂打，总算令香织答应成为他的朋友。充满了欢声笑语的一周很快就过去了，真实的香织其实并不像看上去的那么冷漠。可新一周刚开始，香织却对长谷视而不见，仿佛过去的一周什么事情都没发生过一样。在长谷的不断追问之下，他终于知道，香织因为一场意外而患上了短期失忆症，她的记忆只能够维持一个礼拜。©豆瓣', '川口春奈', '村上正典', 6.8, 10963, 'tt5167966', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2369481108.jpg', 1.5, 9.1, 48.8, 29.2, 11.4, '0.312184,-0.130298,-0.579333,0.545094,-0.338188,-0.220790,0.843000,-0.004157,-0.291921,-0.446697,0.162418,0.448801,-0.445578,0.325247,0.020331,0.166171,-0.209590,-0.757304,-0.077854,-0.226302,-0.118758,-0.385229,-0.198922,0.001147,-0.102428,-0.169078,0.684457,0.137703,-0.077982,0.556695,0.072981,0.063115,0.364959,0.861707,-0.025187,0.169762,-0.174887,0.369412,0.244095,0.058795,-0.023600,-0.388594,-0.306143,0.675278,0.138780,0.637139,0.518393,-0.214851,-0.408402,0.240175,0.206892,-0.124657,-0.070093,0.245113,0.547323,-0.077249,0.106001,0.192954,-0.223475,-0.016525,-0.013731,0.238144,-0.588817,0.131589,0.010317,0.393468,-0.259789,0.662235,0.160337,-0.313040,0.103051,-0.316384,0.015575,0.064443,0.128649,0.393352,-0.376796,0.151755,-0.502105,0.053942,0.675046,0.100277,-0.634906,0.823583,-0.466464,-0.301122,-0.395338,-0.192093,-0.366360,-0.019517,-0.123184,0.236112,-0.446082,0.063087,-0.274679,-0.002183,-0.002277,-0.333172,-0.083173,-0.683772,0.005270,-0.374862,0.055996,-0.667381,-0.511800,0.187315,-0.094614,-0.316411,0.887451,-0.919516,0.024387,0.577975,0.040303,-0.336376,0.371774,0.335852,-0.391570,-0.022363,-0.062986,0.247221,0.136719,0.399757,0.302268,0.565114,0.129325,0.056306,-0.493337,0.532282', '1389971', '3059036', '1466907', '1937946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26646649', '山炮进城', '喜剧', '《山炮进城》讲述的是几个农村人进城奋斗的故事，人人都有一部血泪史，其实也是一部励志史，四个东北“山炮”程野、宋晓峰、唐娜、张笑菲，或为真爱或为名利勇闯北京，一路上遭遇各种奇葩的不靠谱旅程，最后终于找到生活真谛。据悉，《山炮进城》将于10月27日在爱奇艺全网独播。', '程野', '崔俊杰', 4, 8325, '4 Idiots', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2277798017.jpg', 39.7, 32.5, 19.8, 4.3, 3.6, '-0.008976,-0.251880,-0.249345,0.433406,0.251046,-0.066681,0.160975,-0.429394,-0.232323,-0.280371,-0.183420,0.377272,-0.085972,0.323480,0.019969,-0.239350,-0.061855,-0.494991,0.038304,-0.210388,-0.027475,-0.252937,0.015993,-0.016785,-0.101080,-0.122251,0.623799,0.347727,-0.038993,0.310288,0.440725,0.190272,-0.158233,-0.011235,-0.254516,0.148273,-0.242134,-0.036818,-0.348432,-0.148284,-0.390057,-0.245665,-0.303186,-0.244508,0.160304,-0.045009,0.690287,-0.087392,-0.001578,0.090285,0.310430,-0.104154,-0.338089,-0.213566,0.235840,0.070951,0.326877,0.459164,-0.038566,0.311162,-0.086584,-0.145695,-0.761072,-0.041348,-0.075043,-0.269881,-0.520413,0.273191,-0.074959,-0.099880,0.167167,-0.282460,0.369473,0.248974,0.456278,0.590838,-0.068352,-0.034818,-0.549276,0.439993,0.845935,0.013845,0.217095,0.377696,0.057145,-0.226347,-0.075857,-0.137205,-0.417568,0.166550,0.139857,-0.318960,0.059089,0.034363,-0.468752,0.420608,0.027434,-0.284597,0.375574,-0.388128,-0.209473,-0.892816,0.274720,-0.351409,-0.095981,0.126908,0.337008,-0.377687,1.067102,-0.582408,0.037086,0.240830,-0.093186,-0.949007,0.925179,0.230910,-0.025783,0.045737,0.368353,0.331832,-0.030584,-0.007351,0.061755,0.198898,-0.283550,-0.149698,-0.244980,0.512150', '1308424', '4301278', '1296770', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26647117', '暴裂无声', '剧情', '故事发生在偏僻贫瘠的山村之中。张保民（宋洋 饰）是一名矿工，一天，他被妻子翠霞（谭卓 饰）叫回了家，原来，他们的儿子失踪了。带着儿子的照片，不会说话的张保民踏上了寻子之路，途中，他遇见了大资本家昌万年（姜武 饰）的爪牙，两方人马起了冲突，昌万年骗张保民自己知道他儿子的下落，实际上，他隐藏了一个黑暗的秘密。昌万年一直靠着行贿非法收购煤矿以牟取暴利，身为他的律师，徐文杰知道了太多不可告人的秘密。公检法机构开始着手调查昌万年的公司，徐文杰在这个节骨眼上玩起了失踪。为了逼迫徐文杰就范，昌万年绑架了他的女儿。©豆瓣', '宋洋', '忻钰坤', 8.2, 458630, 'tt6389316', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2517333671.jpg', 0.3, 1.7, 16.1, 50.8, 31.1, '0.069979,0.137153,-0.746209,0.526440,-0.186849,0.054319,0.354085,0.060646,-0.542904,-0.294279,0.055470,0.783199,0.034319,0.282132,-0.013316,0.113053,0.013444,-0.531044,0.020114,-0.499347,-0.163035,-0.514847,-0.125114,-0.063078,-0.025535,-0.106403,0.269888,0.319881,-0.175915,0.125484,0.388686,0.139080,-0.015018,0.263339,-0.280454,0.251374,0.095132,0.078578,-0.022266,-0.155943,0.132059,-0.545091,-0.253443,0.169890,0.108041,0.424403,0.484690,-0.048258,-0.152383,-0.218422,0.196215,-0.419200,-0.134044,-0.300606,0.633310,-0.186903,0.032320,0.550462,-0.374379,-0.245565,0.212158,-0.041608,-0.697628,-0.005152,-0.051001,0.275891,-0.708437,0.298734,-0.095664,0.095175,-0.234127,-0.434394,0.432887,0.523180,0.006993,0.142213,-0.159404,-0.160960,-0.748248,0.422245,0.656747,-0.173622,0.150191,0.088948,-0.075955,-0.249444,-0.093702,-0.303853,-0.566305,-0.157858,0.611499,-0.335767,-0.387510,0.053596,-0.389091,-0.097836,-0.318249,0.078277,0.120519,-0.222094,-0.278175,-0.169093,-0.086795,-0.297279,-0.022545,0.336531,-0.126056,-0.392676,0.517357,-0.608028,0.006114,0.505208,0.478859,-0.797471,0.590268,0.155986,0.001387,-0.365694,0.044735,-0.117636,0.057706,0.290331,0.372722,0.036409,-0.056223,-0.283943,-0.182892,0.163073', '1297710', '35461732', '3215099', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26647163', '童年的许诺', '爱情', '改编全法国中学生指定重点读物《我答应》。《贝礼一家》王牌监製群操刀，又一喜泪交织的亲情暖心之作，坎城影后夏绿蒂甘丝柏格，动人演出全欧洲的母亲典范；横跨五个国家、耗时十四个星期、深入20至50年代历史核心的史诗钜作。罗曼加里(皮耶尼内 饰演)的人生可说是精彩非凡，在波兰 度过的贫困童年、法国尼斯阳光下的青少年时期，乃至于二次世界大战时担任飞行员，在非洲立下的彪炳战功。他为了成为一位伟大的男人与著名作家，艰辛尝尽人生的酸甜苦辣，全都是为了他的母亲妮娜(夏绿蒂甘丝柏格 饰演)。这个可爱又特立独行的妇人，对儿子的强烈母爱，令加里的人生充满波折、热情与神秘，也令他成为二十世纪的重要作家。只是，如此无止无尽的母爱，也终将成为他生命的负担…。电影《黎明的承诺》（Promise at Dawn）改编自法国文学巨擘罗曼加里1960年出版的自传小说《我答应》，描述罗曼加里成为法国文学巨擘的传奇故事，他与母亲之间至情至性的动人回忆，一部横跨二十世纪的史诗钜作、喜泪交织的亲情暖心电影。', '皮埃尔·尼内', '埃里克·巴比尔', 8.3, 12484, 'tt5061360', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2519406644.jpg', 0.3, 0.8, 13.4, 53.1, 32.4, '-0.140977,0.098567,-0.653141,0.754376,0.257865,-0.300348,0.625843,-0.153968,-0.340666,-0.015873,0.170521,0.828655,-0.145867,0.282694,0.548521,-0.070811,-0.171961,-0.720507,-0.132432,-0.142014,0.076984,-0.191572,-0.449144,-0.037067,-0.100075,-0.352845,0.717262,0.303738,-0.237603,0.249237,0.266096,0.343079,-0.078271,-0.037392,-0.071038,0.023724,0.080261,0.170044,-0.582243,-0.031265,-0.114145,-0.084685,-0.180563,0.046864,-0.174983,-0.005186,0.411675,-0.184247,0.124354,-0.235804,0.726819,-0.084850,-0.215063,-0.094083,-0.040888,0.159321,0.253631,0.374201,0.033638,0.113215,-0.038524,-0.283476,-1.054589,-0.246597,0.139170,0.039507,-0.314198,0.409858,-0.050127,-0.062116,0.240496,-0.178312,0.066120,0.025416,0.347825,0.507660,0.019562,0.327176,-0.152356,0.804439,0.565985,-0.038517,-0.461770,0.063451,-0.443380,-0.505251,0.020576,-0.562783,-0.534324,0.132971,0.155774,-0.082233,0.143448,0.535350,-0.679331,0.158412,-0.083133,-0.188016,0.134740,-0.212691,-0.095688,-0.446073,-0.188867,-0.405682,-0.282152,-0.183171,0.317720,-0.402884,1.122646,-0.335663,0.219140,0.299132,0.152930,-0.201263,0.875448,0.293751,0.105768,-0.173516,0.008228,0.739491,-0.135715,0.021089,-0.243522,0.109760,-0.214678,0.096566,-0.297652,0.607584', '27602116', '22265121', '24284209', '3603547');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26648249', '月光男孩', '剧情', '奇伦（艾什顿·桑德斯 Ashton Sanders 饰）的母亲宝拉（娜奥米·哈里斯 Naomie Harris 饰）吸毒成瘾根本无心照顾孩子，奇伦从小在孤独中长大，因为过于瘦小的身材而时常遭到周围人的欺侮和作弄。一次偶然中，奇伦结识了毒贩胡安（马赫沙拉·阿里 Maher shala Ali 饰），从此，胡安和其女友特蕾莎（加奈儿·梦奈 Janelle Monae 饰）的住处成为了奇伦的第二个家。凯文（贾雷尔·杰罗姆 Jharrel Jerome 饰）是奇伦唯一的朋友，随着时间的推移，两人之间的感情渐渐超越了友谊。然而，为了隐藏自己的性取向，凯文不得不在同伴的怂恿下对奇伦大打出手，之后，两人再也没有见过面。一晃眼多年过去，奇伦忽然接到了凯文打来的电话，两人终于决定正视各自心中真正的感情。©豆瓣', '崔凡特·罗兹', '巴里·詹金斯', 7.4, 144482, 'tt4975722', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2373594741.jpg', 0.9, 3.7, 35.1, 44.3, 16.1, '0.417770,-0.075344,-0.663105,0.476343,-0.117679,-0.649837,0.713411,0.187552,-0.639885,-0.413689,-0.027875,0.863649,-0.295127,0.272519,0.257145,-0.006407,-0.422356,-0.785270,0.180699,-0.230121,-0.203056,-0.573584,-0.032825,-0.171483,-0.140007,-0.252913,0.477199,-0.278374,0.014649,0.591803,0.290736,0.247403,-0.065760,0.449990,0.045255,0.335829,0.243130,-0.136751,-0.394952,0.139046,0.104950,-0.041851,-0.044793,0.207892,0.042324,0.394621,0.432155,-0.405547,0.003221,-0.186760,0.150869,-0.009161,0.117739,-0.033915,0.321239,-0.065978,0.427037,0.270414,-0.368041,0.027984,0.012671,-0.024768,-0.366919,0.255525,0.063539,-0.019332,-0.435940,0.413372,-0.055358,-0.347871,0.197125,-0.340946,0.097476,0.412612,0.145142,0.320302,-0.375684,-0.129156,-0.130136,-0.082138,0.574949,0.164811,-0.150520,0.460563,0.038598,-0.143265,0.025683,-0.123921,-0.293957,-0.058594,0.306369,0.349681,-0.137400,0.466205,-0.569324,0.060169,-0.438177,-0.026469,0.119844,-0.557121,-0.143657,-0.446699,-0.411064,-0.608409,-0.315957,0.149812,-0.166775,-0.048662,0.567696,-0.902414,0.329307,0.270787,0.257252,-0.264929,0.364980,0.119530,0.083159,-0.169895,0.134017,0.599219,0.026592,0.007709,0.118099,-0.007278,-0.198428,0.011181,-0.263482,0.194593', '1299556', '1292219', '1308755', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26648284', '母亲！', '剧情', '他（哈维尔·巴登 Javier Bardem 饰）是一名作家，却遭遇了职业瓶颈期，一个字都写不出来。她（詹妮弗·劳伦斯 Jennifer Lawrence 饰）是一名主妇，每天忙于将两人的安乐窝修缮一新。一天，一个男人（艾德·哈里斯 Ed Harris 饰）敲响家门，这个男人是作家的超级粉丝，接着，男人的妻子（米歇尔·菲佛 Michelle Pfeiffer 饰）也登门拜访，这两人在家中随意穿梭肆意的打听着男女主人的隐私，这让她感到十分不快。尽管她三番五次的想要将这对粗鲁的夫妇请出门外，可他却对两人的拜访展现出了由衷的热情。之后，男人和女人的两个儿子也闯入家中，一场争执最终演变成为了流血事件。崩溃的她此时并不知道，这一流血事件仅仅只是失控和崩坏的开始。©豆瓣', '詹妮弗·劳伦斯', '达伦·阿伦诺夫斯基', 6.6, 29472, 'tt5109784', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2495457265.jpg', 4.8, 12.6, 40.8, 30.4, 11.5, '0.576204,0.123366,-0.750716,0.555307,-0.300014,-0.175795,1.092976,0.079804,-0.590669,-0.216731,0.304201,0.845613,-0.540019,0.329837,0.382546,0.006364,-0.088256,-0.640342,-0.002743,-0.112484,-0.184787,-0.199138,-0.301260,-0.233137,-0.351003,-0.144885,0.336242,0.009833,-0.249605,0.472395,0.468568,0.226261,0.118341,0.769634,-0.266092,0.270192,0.185440,-0.017605,0.150401,0.064152,0.091415,-0.342898,-0.151348,0.365490,-0.234433,0.440008,0.599019,-0.271281,-0.146923,-0.009054,0.446142,-0.227090,-0.071051,0.304346,0.384265,-0.088648,0.151904,0.061310,-0.078356,-0.118451,0.011169,-0.034437,-0.797947,0.189569,0.092058,0.207611,-0.700306,0.458798,-0.196635,-0.125568,-0.025508,-0.230836,0.115816,0.387110,0.043472,0.310231,-0.266032,-0.150071,-0.641451,0.193705,0.610057,0.129471,-0.184328,0.384797,-0.341943,-0.461748,-0.082387,-0.271384,-0.671285,-0.187814,0.184904,0.125352,-0.104158,-0.058888,-0.511417,0.009470,-0.260075,-0.181385,-0.142735,-0.553162,-0.227077,-0.467583,-0.023404,-0.486920,-0.572208,0.020849,-0.012053,-0.131836,0.832503,-0.822606,0.005890,0.604152,0.370702,-0.408151,0.871519,0.121032,0.168947,-0.175266,-0.136169,-0.068756,0.008457,0.187850,0.181941,0.731328,-0.033800,0.005358,-0.281143,0.603585', '1783772', '1292062', '1296370', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26649095', '恐吓运动', '恐怖', '艾玛（梅根·沃纳 Meegan Warner 饰）是一档恐怖恶搞类综艺节目的制作人，对于这个靠欺骗和伪造愚弄嘉宾的节目，艾玛感到十分厌倦，她打算在做完最后一期节目后就辞职不干。近期，网络上出现了一些更血腥更暴力更真实却也拥有更多观众的恐怖节目，老板要求艾玛和她的同事兼男友马库斯（伊恩 麦杜思 Ian Meadows 饰）做出能够超越这些节目的作品，否则就要炒掉整个制作组。马库斯将下一期节目的地点选在了一座废弃的疯人院之中，这一次，艾玛负责扮演在医院里工作的护士，以招募园丁之名找来了名为罗汉（乔什·邝·塔特 Josh Quong Tart 饰）的男子。罗汉表面看来安静而又老实，但之后他的种种诡异作为让艾玛开始怀疑，罗汉根本就是一个彻头彻尾的疯子。©豆瓣', '梅根·沃纳', '卡梅伦·凯恩斯', 7.1, 16874, 'tt4467626', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2357224248.jpg', 1.1, 5.8, 42.3, 39.8, 11, '0.213736,-0.107966,-0.539207,0.680130,-0.135421,-0.021448,0.723317,0.048403,-0.462297,-0.148402,0.147940,0.685101,-0.460946,0.301622,0.428813,0.052141,-0.313230,-0.523092,-0.080541,-0.093108,-0.117294,-0.436424,-0.237613,-0.274449,-0.047987,-0.064823,0.582547,0.016977,-0.198653,0.069504,0.520524,0.125307,0.294878,0.398075,0.141252,-0.091090,0.016538,-0.134063,0.072725,0.244438,0.213229,-0.106884,-0.019271,0.327463,0.010069,0.225170,0.525356,-0.233320,-0.424903,-0.147641,0.741825,-0.267982,-0.103692,0.042996,0.212512,0.109240,0.427296,0.040526,-0.111909,0.236025,0.072374,-0.150208,-0.951910,0.273596,0.073355,0.038538,-0.549546,0.203580,-0.148381,0.032920,0.044800,-0.293137,0.115364,0.067509,0.486315,0.267783,0.071825,-0.172752,-0.079574,0.328614,0.401787,0.198400,-0.230990,0.385434,-0.182715,-0.403412,-0.101429,-0.227711,-0.245680,0.161558,-0.045574,-0.155320,0.086333,0.018323,-0.549063,-0.098049,-0.047783,-0.234944,-0.195685,-0.449252,-0.109131,-0.886209,-0.054823,0.152954,-0.113219,-0.081947,0.312290,-0.471651,0.617823,-0.711290,0.164363,0.429403,0.205000,-0.313563,0.531945,0.030408,0.094860,-0.044609,-0.165261,-0.229491,-0.037166,0.303439,0.022716,0.442603,0.191162,-0.506844,-0.263779,0.484952', '3318306', '1793491', '2027945', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26649604', '比得兔', '喜剧', '远离伦敦的英国乡村，比得兔（詹姆斯·柯登 James Corden 配音）和家人以及朋友们过着快乐的生活，当然除了那个侵占了他自由土地并杀害他父亲的邻居麦格雷戈先生。每天，比得兔都要闯入麦格雷戈的院子偷吃水果蔬菜，顺带和这个顽固凶残的老家伙对决一番。可就在某天，麦格雷戈意外身亡。快乐的兔子们带着郊外的野生动物闯入没有住人的房子大吃八喝，好不自在。然而好景不长，麦格雷戈的侄子托马斯（多姆纳尔·格里森 Domhnall Gleeson 饰）——一个在伦敦闯荡的精英——刚刚丢了工作，偏巧继承了这幢位于乡下的房子。托马斯来到乡下，毫不留情将野生动物们赶了出去，而比得兔他们一刻也不忘要夺回属于自己的土地……©豆瓣', '詹姆斯·柯登', '威尔·古勒', 7, 98935, 'tt5117670', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2515434674.jpg', 1.1, 5.9, 43.8, 37.7, 11.4, '0.380429,-0.204058,-0.589293,0.478989,-0.235593,-0.314008,0.645449,0.295154,-0.260952,-0.087271,-0.070514,0.672958,0.042745,0.326971,0.116395,0.190195,-0.290481,-0.286145,0.018829,-0.072984,-0.277061,-0.275391,-0.209932,-0.439321,-0.094552,-0.142437,0.159625,0.063601,-0.179562,0.447627,0.164378,0.097980,0.015615,0.394216,-0.608977,0.214996,0.283467,-0.068872,-0.158758,0.178830,-0.083815,0.081361,-0.206436,0.087268,0.428580,0.192092,0.655442,-0.173768,-0.138804,-0.026619,0.056005,-0.068195,0.119667,0.211298,0.259122,-0.316786,0.054737,0.088937,-0.104541,0.165284,0.208954,-0.279513,-0.621974,-0.005571,0.007677,0.012755,-0.757558,0.548114,0.045938,0.102206,0.024381,-0.319074,0.191536,0.191384,-0.166926,0.576273,0.072579,0.147486,-0.850834,0.204813,0.694678,-0.292452,-0.004709,0.185267,-0.227606,-0.417885,0.131807,-0.176288,-0.651954,-0.210241,0.378617,-0.339063,-0.280087,0.291518,-0.644921,-0.135560,-0.096869,-0.444748,0.070234,-0.345764,-0.170837,-0.501658,0.106555,-0.437090,-0.227730,0.218152,-0.049599,-0.104625,0.574648,-0.834078,0.488139,0.663000,0.266740,-0.397859,0.636748,0.035192,0.295834,-0.143622,-0.273192,0.203320,0.506528,0.352566,0.554755,0.388288,-0.028693,-0.262582,-0.440221,0.610870', '3055049', '10774184', '1907966', '1291586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26649627', '超能泰坦', '科幻', '《超能泰坦》是一部发生在未来的科幻电影。那时的地球人口严重过剩，处于危险边 缘。战争盛行，资源正急剧减少。十年后，地球就将变成一片废墟，人类面临前所未有的挑战。在这个宇宙中，只有一个地方适合人类居住——土星的最大行星，泰坦。为了移民到泰坦星，科学家们推出一项军事实验项目：他们秘密计划将人类改造为适应泰坦星球恶劣生存环境的物种。 萨姆·沃辛顿 饰演的里克·詹森中尉成为实验对象之一。但这个实验也充满了未知和危险。随着试验强度的提升，一切已经进入了未知领域。里克的身体也逐渐发生变化，妻子（泰勒·席林 饰）和儿子（诺亚·尤佩 饰）陷入恐慌。原本承载人类希望的里克，就这样变成了人类的噩梦？', '萨姆·沃辛顿', '伦纳特·拉夫', 4.5, 10303, 'tt4986098', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2534696059.jpg', 18.4, 44.7, 29.9, 5.5, 1.5, '-0.025216,0.231991,-0.815850,0.452468,-0.090301,0.079784,0.655046,0.002918,-0.438804,-0.342051,0.307486,0.718286,-0.001153,-0.173276,0.245140,-0.061793,-0.362237,-0.276446,-0.185681,-0.010702,-0.580204,-0.466687,-0.620510,-0.395554,-0.065427,-0.710497,1.038702,0.306598,-0.388948,-0.033966,-0.314470,0.432570,0.084243,0.292478,-0.152085,-0.127321,0.147665,-0.130246,-0.469641,0.405832,-0.216252,0.291320,0.220493,0.197680,-0.301312,0.080494,0.655108,-0.453987,-0.195219,-0.431052,0.413690,-0.380802,-0.285131,-0.088656,0.577327,-0.153375,-0.233168,-0.124362,-0.047608,0.103916,0.062038,-0.119296,-1.089213,-0.191132,-0.102882,0.168504,-0.261421,0.205168,0.143990,-0.159306,0.054154,-0.116102,0.178049,0.662299,0.309574,0.525176,-0.370198,0.073494,-0.328913,0.037717,0.601194,-0.153377,-0.657133,0.318780,-0.473211,-0.696474,-0.364513,-0.480450,-0.335993,-0.265974,0.098017,0.202798,-0.134472,0.820443,-0.827340,0.242172,-0.243201,-0.747115,0.305048,-0.088174,-0.113998,-0.586146,-0.202762,-0.069486,-0.148485,0.060144,0.133301,-0.459340,0.849107,-0.861162,0.388966,0.615666,0.419184,-0.648128,0.446333,-0.197692,0.302316,-0.540689,-0.024870,0.454220,-0.214418,0.437856,-0.264632,0.008821,0.156058,-0.026749,-0.433835,0.664898', '26667010', '35377026', '26759819', '26759820');
