INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26650037', '秘果', '爱情', '十七岁的男生段柏文（陈飞宇 饰）自幼丧母，与继母矛盾剧烈，敏感坎坷的少年爱上了特立独行的老师“小耳朵”李珥（米咪 饰），这也成为了他心里的秘密。元气少女于池子（欧阳娜娜 饰）心里也有一个秘密，她暗恋着自己的青梅竹马段柏文。可是有一天她发现自己的闺蜜、个性校花斯嘉丽（邹元清 饰）秘密经营着与段柏文的特殊关系，愤怒的她开始了自己的复仇计划……', '陈飞宇', '连奕琦', 4.6, 22387, 'tt7726702', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2482856848.jpg', 22.3, 38.5, 27.8, 8.2, 3.2, '0.143640,0.057051,-0.782158,0.650909,-0.206473,-0.031318,0.719887,0.026457,-0.859125,-0.247530,0.111586,0.473315,-0.366609,0.400078,0.201673,0.423889,0.240419,-0.827775,0.193952,-0.153670,-0.088956,-0.648258,-0.567071,-0.355070,-0.108386,-0.399343,0.621653,0.053943,-0.202770,0.350166,0.252260,-0.045383,0.035827,0.525093,-0.028544,0.098532,0.148046,0.123384,0.120022,-0.234293,0.137232,-0.205236,0.043141,0.083499,0.055967,0.481255,0.702099,-0.073399,-0.180472,-0.121840,0.291630,-0.236517,-0.236791,0.067219,0.366472,-0.043829,0.368548,0.151550,-0.033428,-0.276100,0.361742,-0.102174,-0.253035,-0.183851,0.385291,0.142757,-0.473320,0.655139,-0.486330,-0.236139,0.317644,-0.450939,-0.074450,0.139150,0.347343,0.268071,-0.452711,0.197515,-0.386567,0.223596,0.636736,0.156333,-0.080324,0.164551,-0.480583,-0.491153,-0.401574,-0.016539,-0.669481,-0.085191,0.558216,0.091273,-0.217095,0.506316,-0.422724,0.032868,0.128887,0.443930,0.106533,-0.668943,0.003745,0.126020,-0.500474,-0.805768,-0.408085,-0.056149,-0.025736,-0.301702,0.931010,-0.957268,0.200649,0.578674,0.288205,-0.558237,0.592978,0.201798,0.048771,-0.341374,0.048148,0.347464,-0.580965,-0.099683,0.035256,0.658344,-0.002164,0.067547,-0.323832,0.359843', '3445516', '26354526', '35030151', '1390020');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26651353', '超级快递', '喜剧', '超级快递员马力（陈赫 饰）在一次派件途中，偶然卷入一起神像争夺事件。他做梦都没想到，遇见了一位神秘性感女郎（宋智孝 饰）却反遭对方胁迫，共同对付国际大盗加里（大卫·贝利 David Belle 饰）。小马凭借平时送快递对路线的熟悉，和使命必达的轴劲，终于成功获得神像，不料事件却突然变得扑朔迷离……', '陈赫', '宋啸', 4.5, 22333, 'tt5187816', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2399994997.jpg', 22.5, 40.5, 30, 5.5, 1.5, '-0.058671,0.066645,-0.646225,0.500118,0.071962,-0.246484,0.373344,0.106545,-0.367310,-0.302817,0.409480,0.619852,-0.266134,-0.203668,0.250168,-0.060092,-0.043784,-0.448723,0.344274,-0.003379,-0.199392,-0.254223,-0.552090,0.016476,0.217261,-0.392837,0.339893,0.027058,-0.199799,0.677737,0.357629,0.259103,-0.325884,0.520904,-0.014587,-0.154657,0.563012,0.147969,-0.109562,0.012231,-0.339193,-0.166820,-0.113314,0.131803,0.008657,0.284093,0.276188,-0.270134,-0.222995,0.054829,0.210124,0.057207,-0.122428,-0.305908,0.340310,0.268673,0.339077,0.140205,-0.198830,-0.179439,0.444162,-0.084819,-0.510247,0.259572,0.156960,0.004628,-0.158011,0.012664,-0.166921,0.223400,0.100947,-0.160380,-0.116510,0.152644,0.722250,0.096989,0.183834,0.098206,-0.348240,0.026231,0.513102,-0.144358,-0.198059,0.380285,0.171580,-0.169318,0.068991,-0.240017,-0.040102,0.372927,0.489759,-0.049345,0.209924,0.182337,-0.670164,-0.119261,-0.407552,0.332242,0.072485,-0.116991,-0.016443,-0.625620,0.028480,-0.009203,-0.005825,0.265136,0.010510,-0.064819,0.350488,-0.481963,0.272471,0.742925,-0.008436,-0.446558,0.422559,0.054628,-0.107010,-0.435317,-0.194747,-0.162110,0.157418,0.195239,-0.070125,0.054757,0.138610,-0.199591,-0.100048,0.345886', '34461680', '3147969', '4301659', '1306723');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26653833', '生吃', '剧情', '贾斯汀（加朗斯·莫里利尔 Garance Marillier 饰）生长在一个素食主义家庭之中，严格遵守着饮食上的戒律，从未尝过荤腥。贾斯汀进入了一间兽医学校就读，作为校园里的“菜鸟”，她受到了来自老生们的无情的压榨和排挤，森严的等级制度让贾斯汀倍感压抑，而她和亦在这里就读的姐姐埃里克西亚（艾拉·朗夫Ella Rumpf 饰）之间的关系也十分紧张。没有了父母的管制，贾斯汀决定尝一尝肉的滋味，然而随着时间的推移，她渐渐发现熟肉已经无法再满足她，她的内心里滋生出了对生肉和鲜血的渴望。这日益强烈的渴望折磨着贾斯汀，而埃里克西亚对于妹妹的异样竟然毫无意外。一场意外中，埃里克西亚的手指被剪刀剪下，面对着眼前的断指，贾斯汀再也无法压抑内心的欲望。©豆瓣', '加朗斯·马里利埃', '朱利亚·迪库诺', 7.1, 76534, 'tt4954522', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2436355743.jpg', 1.5, 6.3, 39.5, 39.5, 13.2, '0.455977,0.138553,-0.876744,0.877855,0.127009,-0.528264,1.118923,0.295042,-0.783444,-0.045701,-0.164555,0.382470,-0.329346,0.352013,0.244999,0.037738,-0.212948,-0.647782,-0.292677,-0.236901,-0.332399,-0.419166,-0.323663,-0.232854,-0.181803,-0.346975,0.361821,0.098221,-0.250578,0.472126,0.375707,0.349761,0.168904,0.773567,0.285295,-0.064019,0.322787,-0.036818,0.047016,-0.004324,0.410834,-0.237448,-0.082611,0.315995,0.170183,0.484932,0.465077,-0.360578,0.068481,-0.299400,0.114239,-0.075250,-0.015192,0.366795,-0.016525,-0.007756,0.146480,-0.026141,-0.273556,0.313164,0.218973,-0.101638,-0.775884,-0.035868,0.088998,0.321798,-0.735978,0.556989,-0.050400,-0.340344,-0.050673,-0.451997,0.227811,0.104834,0.278111,0.412813,-0.300836,-0.182602,-0.440490,-0.088543,0.517704,-0.020119,-0.485170,-0.014469,-0.954911,-0.512179,0.041466,-0.092343,-0.564789,-0.400236,0.401493,0.369985,-0.290573,0.505262,-0.611389,-0.100350,-0.166638,-0.273724,-0.190517,-0.342609,0.122784,-0.515565,-0.239710,-0.744882,-0.470353,0.010403,0.187475,-0.231057,0.532878,-0.870350,0.321929,0.407566,0.353256,-0.000842,0.346324,0.223776,0.170554,0.200461,-0.387498,0.683835,-0.090857,0.478023,0.360640,0.646447,-0.044105,-0.000431,-0.326841,0.893938', '1417428', '3742987', '1303555', '1298442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26654145', '天际行者', '剧情', '1965年，正值美国和俄罗斯先后准备向太空发射载人飞船之际，指挥官谢尔盖·科罗廖夫决定选派飞行员阿列克谢•列昂诺夫和帕维尔·贝尔耶夫执行首飞任务，提前于原计划两年执行。于此过程中，无论是两名宇航员还是指挥官和无数参与者，都面临着极大的压力和风险。万众瞩目之下，媒体同步播出了发射过程，当阿列克谢打开舱门迈出太空第一步之际，整个苏联都为之沸腾。然而在阿列克谢准备返回的时候太空服失灵，紧接着飞船舱门无法自动关闭……让他险些命丧太空…….', '叶甫盖尼·米罗诺夫', '德米特里·基谢廖夫', 7.8, 16693, 'tt6673840', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2458609703.jpg', 0.1, 2.5, 25.1, 51.3, 21, '0.067206,0.189810,-1.086193,0.411933,0.245202,-0.228114,0.489135,0.078437,-0.166418,-0.152445,0.058359,0.624427,-0.269622,-0.238217,0.628849,-0.276394,-0.670436,-0.572711,-0.319757,-0.062138,-0.429652,-0.477241,-0.054534,-0.374322,-0.024209,-0.605205,1.079863,0.231990,0.000198,0.411909,0.018666,0.414138,-0.133965,0.629239,0.096707,-0.422427,0.501426,-0.352018,-0.345318,0.286784,-0.213434,-0.298424,0.036362,-0.051675,0.006388,0.271634,0.443053,-0.153537,0.148589,-0.384000,-0.126470,-0.372724,0.208316,-0.054345,0.355671,0.315557,-0.227835,0.121958,-0.100531,0.136761,0.154267,-0.148528,-0.503713,-0.193143,-0.082143,-0.251062,-0.401286,-0.030609,-0.731628,0.664801,0.044555,-0.315718,0.180997,0.606586,0.365974,0.390396,-0.510240,0.071631,-0.389768,-0.032651,0.647041,-0.316409,-0.642448,0.172667,0.253833,-0.311786,0.131731,-0.041111,-0.267606,-0.209823,0.261868,0.412864,-0.030552,0.440738,-0.253569,0.359907,-0.591439,-0.737457,-0.383864,-0.270996,-0.018724,-1.031204,0.285927,0.114858,-0.309739,0.644706,-0.085765,0.279392,0.617127,-0.427196,0.404933,0.340625,0.088088,-0.205777,0.615862,-0.028891,0.427698,-0.400986,0.440205,-0.175463,-0.209755,0.509142,-0.190379,0.364539,0.053875,-0.331621,-0.276882,0.142013', '3871833', '1301444', '27073291', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26654146', '解忧杂货店', '剧情', '改编自东野圭吾原著同名小说《解忧杂货店》，讲述了在一家僻静街道旁的杂货店，只要写下烦恼投进店前门卷帘门的投信口，第二天就会在店后的牛奶箱里得到回答。某个夜晚，三个身在迷途的年轻人阿杰、小波、彤彤无意闯入，没想到开启了时光隧道，从收到来自过去的第一封咨询信开始，在不断的回信和收信过程中，过去链接了未来，犹豫是否该坚持音乐梦想的秦朗、是否该和家人因逃债远走他乡的浩博、是否应该放弃舞女工作的晴美都从他们的回信建议做出了选择，找到了心灵的方向，不经意间也串联了所有人的人生。同时这三个年轻人也收到了对于自己困惑的解答。', '王俊凯', '韩杰', 5, 185025, 'tt7645502', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2503544593.jpg', 18.3, 33.3, 34.1, 9.9, 4.4, '0.384468,0.301845,-0.519289,0.366231,0.101388,-0.323493,0.373170,0.177956,-0.343933,-0.208533,0.068297,0.547376,-0.074796,0.165939,0.313393,0.053004,-0.458407,-0.445534,0.015664,-0.427179,-0.361151,-0.436270,0.116483,-0.285489,0.119596,0.037622,0.369474,0.064046,-0.233310,0.310819,0.072305,0.210378,-0.409916,0.352283,-0.336814,0.236533,0.024817,0.203862,-0.314790,0.328800,0.159023,-0.187417,-0.205790,0.048721,0.086046,0.318570,0.733238,-0.126740,-0.487405,0.563260,0.352593,0.054974,-0.084946,0.098959,0.152390,0.200249,0.178308,0.113213,-0.339041,0.077299,-0.273739,0.064117,-0.660642,-0.136360,0.001259,0.269714,-0.396715,0.205981,0.065556,-0.124078,0.210512,-0.602424,0.158378,0.306608,0.273297,0.346502,-0.237004,-0.147522,-0.270740,-0.031063,0.363726,-0.069306,-0.140406,0.431695,0.100966,-0.294894,0.075163,0.495977,-0.441988,0.116150,0.461041,0.356280,-0.276465,0.007770,-0.542888,-0.040077,-0.112034,-0.326762,0.441011,-0.505975,-0.427549,-0.562887,0.043829,0.190084,-0.167564,0.131533,0.125849,-0.071554,0.758247,-0.776061,0.207250,0.598902,0.146883,-0.361887,0.736445,-0.074821,0.028491,-0.154492,0.277108,0.035923,0.230877,0.629453,-0.065632,0.150562,-0.080865,-0.193995,-0.671243,0.121136', '3044878', '3811356', '25928048', '1418179');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26654269', '瞒天过海：美人计', '喜剧', '桑德拉·布洛克饰演的Debbie Ocean是《十一罗汉》集团头目乔治·克鲁尼饰演的Danny Ocean的妹妹，曾因盗窃入狱服刑。而黛比刚一出狱就策划惊天大案，与凯特·布兰切特饰演的好友一起网罗顶尖高手，准备在一年一度的时尚盛会Met Gala（纽约大都会艺术博物馆慈善舞会）上盗取由安妮·海瑟薇饰演的大明星所佩戴，价值一亿五千万美金的卡地亚钻石项链。', '桑德拉·布洛克', '盖瑞·罗斯', 6.7, 259096, 'tt5164214', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2508259902.jpg', 0.8, 8.1, 54, 30.4, 6.7, '-0.140231,-0.199860,-0.604688,0.482318,0.188020,-0.227644,0.577904,0.242580,-0.264905,-0.319097,0.535727,0.869465,-0.644323,0.268741,0.760207,0.372913,-0.376670,-0.553928,-0.283219,-0.268820,0.205738,-0.491278,-0.538406,0.115540,0.168646,-0.376553,0.455474,-0.223409,0.035383,0.700306,0.820679,0.454608,-0.193041,-0.228350,0.115755,-0.296370,0.462953,0.170109,-0.517455,0.196886,-0.271977,-0.213797,0.075017,-0.251974,0.212316,0.250918,0.252951,0.007053,0.432719,-0.237867,0.590810,-0.048480,0.079299,-0.192756,0.357875,0.152129,0.492307,0.329681,-0.290159,-0.208458,0.391228,-0.673969,-0.808584,-0.039968,0.463907,0.130346,-0.436078,0.332347,-0.399037,0.222980,0.117390,-0.052760,-0.033744,0.375121,0.142869,0.084097,0.437607,0.123952,-0.319121,0.703873,0.281190,-0.022155,0.284379,0.153666,-0.036773,-0.448315,-0.240885,-0.374406,-0.368839,0.255210,0.255098,-0.579355,0.430936,0.201521,-0.451918,-0.342195,-0.201579,-0.168942,0.436765,0.189885,0.105766,-1.117686,-0.117379,-0.019500,-0.072401,-0.096233,0.486426,-0.239984,0.553373,-0.755047,0.336578,0.652717,0.211442,-0.292830,0.666869,0.051465,0.146980,-0.285267,-0.344084,-0.142365,0.251594,0.001772,-0.243160,0.270898,0.096453,-0.495286,-0.333513,0.303117', '24751811', '34961898', '3077791', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26654498', '爱你，西蒙', '喜剧', '每个人都值得拥有一个伟大的爱情故事。但是对一个17岁的高中生「赛门」来说这一切却是件超複杂的事：第一、没有人知道他是同性恋；第二、他也搞不清楚自己爱上跟他一样有同样困扰的不具名网友到底是何方神圣？？？为了解决这两个大麻烦，赛门展开一段爆笑又吓人的解答过程，但他没料到的是，最后得到的答案却从此改变了自己的人生。', '尼克·罗宾森', '格里格·伯兰蒂', 8.3, 217713, 'tt5164432', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2523592367.jpg', 0.3, 1.2, 16.6, 47.3, 34.6, '0.507916,-0.185477,-0.767757,0.610701,-0.427442,-0.000982,1.007701,-0.523444,-0.451052,-0.614768,0.073640,0.777535,-0.070409,-0.083069,-0.112444,0.125885,-0.024156,-0.516096,0.215492,-0.251226,-0.352440,-0.653785,-0.457712,-0.225403,-0.125783,-0.004878,0.569153,0.159016,-0.276965,0.112371,0.656524,0.170375,0.576122,0.667623,-0.349661,0.266432,-0.025570,0.490698,0.295205,0.056944,0.057253,-0.058070,-0.350375,0.778386,-0.293525,0.605633,0.174083,-0.335707,-0.597791,0.263889,0.587147,-0.681793,-0.258467,-0.030542,0.210099,-0.234609,0.062144,-0.031617,-0.084999,-0.318582,0.099731,0.279636,-1.403696,-0.076345,0.235372,0.221272,-0.602551,0.472124,-0.092201,-0.343482,-0.027487,-0.343822,0.148967,0.473667,0.557075,0.358216,-0.103073,-0.142292,-0.764504,0.172159,1.174754,0.156083,-0.629222,0.646043,-0.601976,-0.537623,-0.356883,-0.459949,-0.501119,0.358108,-0.215739,0.192783,-0.319835,0.040816,-0.117607,0.241603,-0.218024,-0.303990,-0.139965,-0.815357,-0.234056,0.125242,-0.244911,-0.471016,-0.657850,0.095953,0.160994,-0.658114,1.069997,-0.910571,-0.038795,0.618683,0.150159,-0.933802,1.080682,0.657800,-0.149566,-0.458026,-0.113334,-0.127432,0.057770,-0.087496,-0.065045,0.393707,0.379948,-0.285588,-0.454496,0.419670', '30163500', '26678784', '3785918', '6874741');
