INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26657126', '不成问题的问题', '剧情', '1940年代的大后方重庆，一间物产丰富却总是赔钱的树华农场，一场明争暗斗在新旧两个农场主任之间上演。这部根据老舍小说改编的影片似乎叙述了一个永不过时的人间寓言。', '范伟', '梅峰', 8.1, 98872, 'tt6128782', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2504993947.jpg', 0.3, 1.2, 16.5, 56.1, 25.9, '0.568554,0.054240,-0.442896,0.555185,0.600073,-0.169804,0.645568,0.172558,-0.101956,-0.143682,0.165301,0.670626,-0.255438,0.117414,-0.201342,-0.298793,-0.376170,-0.382944,-0.399863,-0.034909,0.320595,-0.172515,-0.536396,0.176303,-0.123873,0.138875,0.626332,0.303111,-0.556588,0.300586,-0.058113,-0.188304,-0.337354,-0.037894,-0.019567,0.109196,0.443464,0.315631,-0.473541,0.065505,0.056080,0.001621,-0.197201,-0.320580,-0.133565,0.328988,0.797741,-0.218512,-0.247527,0.361444,0.815205,0.155811,-0.361612,-0.299962,0.459346,0.196693,0.271091,0.430177,-0.301538,0.064152,-0.348226,-0.160203,-0.838123,-0.250698,0.234256,0.428562,-0.067453,0.456752,0.283518,0.109870,-0.291351,-0.331849,0.266261,0.344140,0.886197,0.834815,-0.176163,-0.133525,-0.394389,0.659726,0.658674,0.026694,-0.455163,0.494903,-0.109017,-0.072647,0.056570,0.183687,-0.729451,0.052145,0.339782,-0.816236,-0.040610,0.289857,-0.873051,0.319798,-0.286317,-0.432867,0.153055,-0.311076,-0.071526,-0.983268,-0.302133,-0.300914,0.233100,-0.163571,0.557621,-0.186903,0.575129,-0.257190,-0.059099,0.402606,-0.101860,-0.254388,0.575780,0.331516,0.223209,-0.141894,0.116234,0.032274,-0.007761,0.300591,-0.196881,0.518116,0.124579,-0.076305,-0.503121,0.706872', '3318306', '22265121', '1322847', '35116325');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26657283', '局外人', '剧情', '《放牛班的春天》法国导演克里斯托夫·巴拉蒂执导，凯萨奖男星亚瑟·杜彭主演。电影改编自真实事件，九年前震惊全球的「500亿欧元交易弊案」，描述2008年时，31岁的巴黎交易员杰宏柯维耶在未经授权下进行金融买卖，涉及的投资金额高达500亿欧元，几乎导致法国兴业银行（Société Générale）倒闭，更引发全球金融大暴泻。这位人称「魔鬼交易员」的柯维耶，如何偷天换日、秘密进行500亿欧元的交易？由于金额太过庞大，让人怀疑内情不单纯，不仅国际议论纷纷，更成为金融机构的职训教材。拜该案知名度之赐，《巴黎交易员》各国版权狂卖，不仅电影获伊斯坦堡金桔奖提名最佳影片，导演巴拉蒂更获好莱坞报导讚誉「挖掘出事件的娱乐性」。剧情讲述，杰宏来自布列塔尼，他幸运挤身法兴银行，在获主管同侪欣赏下，摇身成为巴黎交易员。人生鲤跃龙门，眼界自此大开，而他在股价期货交易赚到的钱，更远超过父亲几十个劳碌的人生。杰宏的父亲是个锅炉工人，母亲则是理髮师。顶著金融硕士头衔的他，彷彿有弹指魔法，总能帮银行赚进惊人利润，却也逐渐沉迷于一场场的金钱游戏。杰宏每投必中宛若神助，在银行默许下，他越发大胆展开最疯狂交易，不仅买卖金额逐步超越权限，投资金额更超乎银行股本，导致不可收拾局面，引发那斯达克、道琼欧盟指数崩盘暴泻，银行跟著摇摇欲坠。银行愤怒对杰宏提出控告，使他面临49亿欧元的天价求偿！这位「魔鬼交易员」如何能瞒天过海、暗地进行500亿欧元的投资？他坚持没有私吞一毛钱，但凭空消失的钜款，究竟去了哪裡？一场关乎人性与欲望的金钱游戏于是登场。', '亚瑟·杜彭', '克里斯托夫·巴拉蒂', 7.5, 6411, 'tt5114984', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2358639819.jpg', 0.3, 2.6, 32.9, 48.4, 15.8, '-0.338326,0.123386,-0.564370,0.292908,0.191817,-0.034830,0.327881,0.191780,-0.153765,-0.111620,0.200280,0.545894,-0.223653,-0.142838,0.316100,-0.219145,0.010249,-0.327580,-0.135716,-0.384940,0.275565,-0.537594,-0.289754,-0.090259,-0.294656,-0.105982,0.494737,0.124764,-0.272337,0.151203,0.240942,0.132355,0.122391,0.242846,0.096400,0.013633,0.378622,0.162827,-0.377647,0.355768,-0.085760,-0.135581,-0.026603,0.000627,0.134019,0.107306,0.308296,-0.038381,-0.068074,-0.079302,0.735298,-0.187083,-0.148390,-0.204103,0.276202,0.156746,0.277686,0.091043,-0.359507,0.014969,0.139175,-0.175911,-0.895118,-0.146900,0.155399,0.074615,-0.434645,-0.051056,-0.379098,0.241843,-0.326415,0.086708,-0.376809,0.314417,0.369603,0.190667,-0.080074,-0.069155,-0.651047,0.386061,0.363990,0.002219,-0.277636,0.349438,-0.170300,-0.509400,-0.177760,-0.448174,-0.026847,0.116949,0.169645,-0.152304,0.164263,0.539418,-0.526192,0.005342,-0.067897,-0.455073,-0.073717,-0.184005,-0.049428,-0.641680,-0.282285,-0.077643,0.012422,-0.079116,0.460260,-0.333212,0.517476,-0.153519,-0.154700,0.624845,0.648233,-0.263559,0.570691,-0.238802,-0.015208,-0.233581,-0.273887,-0.000607,0.106655,0.205743,-0.096353,-0.253571,0.061127,-0.325990,0.254938,0.407246', '3318306', '1793491', '1468527', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26657439', '爸爸是女儿', '剧情', '一部充满家庭温馨情感的作品，主要讲述了父亲和女儿奇幻般的交换了身体，不得不使用对方的身体生活，在现实中遭遇各种不便的同时，也逐渐更深刻地理解对方，重新找回被遗忘的亲情的故事', '尹宰文', '金惠荣', 7.2, 8285, 'tt6770758', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2440973463.jpg', 0.5, 4, 41.8, 40.6, 13, '0.572754,0.212578,-0.438347,1.124226,0.101659,-0.193335,0.944399,-0.073186,-0.647810,-0.358919,0.225819,0.807902,-0.029001,0.494084,0.070949,-0.182484,-0.306940,-0.674907,-0.081350,0.060285,-0.321194,-0.608292,-0.279011,-0.099413,-0.373402,-0.244081,1.056166,0.233740,-0.513548,0.195769,-0.230516,0.448742,0.128883,0.553899,-0.189932,0.299947,-0.390339,0.195307,-0.544071,-0.096698,0.441642,-0.255076,-0.009971,0.552383,-0.323601,0.265150,1.059774,-0.298590,-0.432491,0.023630,0.919187,0.077019,-0.235580,-0.005779,-0.234260,0.535710,0.331531,0.245702,-0.346080,0.087007,0.044436,0.058938,-1.062397,-0.193648,0.388724,-0.105087,-0.313249,0.223200,0.116778,0.073760,0.276260,-0.198727,0.031263,0.061403,0.672969,0.585792,-0.547305,-0.068079,0.027137,0.484902,0.741516,-0.221594,-0.409979,0.655191,-1.045731,-0.188514,-0.150264,-0.360287,-0.484143,-0.085160,0.349900,0.645844,-0.413297,0.914250,-0.734587,-0.052978,-0.119857,-0.480032,0.086198,-0.839661,0.175684,-0.585460,-0.880403,-0.596118,-0.115696,-0.340593,0.294782,-0.352648,1.022657,-0.868832,0.194542,0.445375,0.120285,-0.352371,0.209156,0.318222,0.068518,-0.313882,0.102969,0.616863,-0.131561,0.030840,0.013703,0.357443,-0.159361,0.410600,-0.811830,0.966008', '26667010', '1303542', '26759820', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26658568', '28岁未成年', '喜剧', '二十八岁的凉夏（倪妮 饰）本以为一定能够和相恋了十年之久的男友茅亮（霍建华 饰）一起携手步入婚礼的殿堂，并且一直为了迎接两人盛大的婚礼而做着各种各样的准备，心中充满了对婚后生活的美好幻想。茅亮的公司正在进行着紧张的第二轮融资，事情进行的并不是非常顺利，凉夏对婚姻的渴望带给了茅亮巨大的压力。某日，两人一起参加了凉夏闺蜜白晓柠（马苏 饰）的婚礼，经受不住婚礼上浪漫热烈的氛围，凉夏向茅亮逼婚了，让凉夏没有想到的是，茅亮竟然提出了分手的要求，巨大的打击之下，凉夏崩溃了。一场意外的发生让凉夏的心智返回到了十七岁的年纪，此时外表成熟内心却极为幼稚的她遇见了名为严岩（王大陆 饰）的男子。©豆瓣', '倪妮', '张末', 5.7, 103320, 'tt5665040', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2402824160.jpg', 9.4, 26, 42.3, 16.6, 5.8, '0.362183,0.270026,-0.939059,0.576113,-0.084288,-0.211046,0.784331,0.237205,-0.451130,-0.155389,0.284803,0.494985,-0.460307,0.382470,0.369090,-0.086428,-0.079524,-0.742457,-0.236330,0.102253,-0.220418,-0.344382,0.027520,0.066829,-0.076720,-0.449968,0.585016,0.237540,-0.059921,0.762586,0.379035,0.144825,0.172396,0.584443,-0.132963,-0.246579,0.090176,0.448402,-0.541198,0.293214,0.088694,-0.139609,-0.153912,0.507533,-0.106324,0.136928,0.689099,-0.287528,-0.316245,-0.056041,0.459916,-0.256604,-0.108906,0.344706,0.160025,0.258487,0.274551,0.261184,-0.406995,0.042518,0.338816,-0.190216,-0.666816,0.290408,0.093292,0.088931,-0.511960,0.605659,0.018494,-0.183946,0.260987,-0.420055,0.106284,0.643586,0.561031,0.465074,-0.235458,0.147095,-0.474129,0.200598,1.021780,0.076547,-0.109310,0.306622,-0.478310,-0.376886,-0.043275,-0.211379,-0.482903,0.096912,0.098649,0.031013,-0.291253,0.429681,-0.473412,0.093336,-0.207561,-0.209890,0.182681,-0.691387,-0.138747,-0.659529,-0.374205,-0.501040,-0.359826,-0.019834,0.093300,-0.312290,0.572199,-0.972934,0.312280,0.380462,0.466444,-0.288556,0.513823,0.343462,-0.114791,-0.110183,-0.036502,-0.022093,-0.692186,0.212068,0.067004,0.368144,0.042781,-0.020214,-0.400489,0.680317', '35030151', '1870682', '25721544', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26660834', '蜡笔小新：梦境世界大突击', '喜剧', '每天入夜，当春日部的居民们酣然入睡之后，他们都会来到一个神奇而又美丽的梦中世界中。在那里，他们可以实现一切想要实现的愿望，满足一切渴望满足的要求，这个梦中的世界充满了快乐和幸福。某日，一个名为贯庭玉崎的女孩跟父母一起搬来了春日部市，成为了这个城市中的新的一份子。然而，从那一天开始，大家就再也没有做过美梦了。那个曾经温暖的梦中世界，如今充满了痛苦、悲哀和恐惧，而梦境中的灾难亦渐渐延续到了现实之中。这一切的发生，显然和玉崎有着脱不清的干系。为了弄清事件的真相，小新（矢岛晶子 配音）联手风间（真柴摩利 配音）和妮妮（林玉绪 配音）等小伙伴们展开了调查。©豆瓣', '矢岛晶子', '高桥涉', 7.3, 25596, 'tt5526456', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2393770821.jpg', 0.7, 5.5, 38.3, 38.8, 16.8, '0.240746,0.427584,-0.781425,0.493842,-0.172048,-0.254030,0.922753,-0.161893,-0.592479,-0.247624,-0.210591,0.680360,-0.154537,0.670648,0.288468,0.090285,-0.450983,-0.962758,-0.163478,-0.268393,-0.357144,-0.260093,-0.193165,-0.339096,-0.217047,-0.187321,0.821193,0.521671,0.086982,0.447631,0.302421,0.198526,-0.264725,0.619791,-0.014335,0.004843,0.193610,0.326816,-0.463889,0.291522,-0.241606,0.031166,-0.173864,0.386734,-0.114937,0.003207,0.688459,-0.564585,-0.453742,-0.219910,0.432481,-0.267529,-0.205227,0.270828,0.011444,0.040480,0.193888,0.162844,-0.244881,-0.200455,-0.044988,-0.157645,-1.016130,-0.215239,0.169303,0.234314,-0.268996,0.209567,0.263951,-0.152663,0.386581,-0.139815,0.500894,0.401097,0.455311,0.656362,-0.372844,0.086340,-0.368327,0.336562,0.816908,-0.229827,-0.261917,0.518815,-0.365386,-0.207001,-0.141069,0.085424,-0.438415,0.203778,0.154217,0.328492,-0.329077,0.391436,-0.603924,-0.018951,-0.103776,-0.327741,-0.099843,-0.666924,-0.142035,-0.505920,-0.307164,-0.400088,-0.324419,0.091173,0.178679,-0.430495,0.774308,-1.059231,0.367955,0.499426,0.203855,-0.066540,0.532698,0.183345,0.136460,-0.304251,0.247876,0.358510,-0.346435,0.307217,0.026434,0.358778,-0.190461,0.395688,-0.730728,0.735555', '25928048', '30345227', '26021055', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26661183', '抢红', '动作', '朝不保夕的司机张水（张涵予 饰），受上司方长方（王耀庆 饰）利诱，答应亲赴法国邀请义弟韦力（黎明 饰）帮忙参加天价红酒的竞拍。张水谎称为国家执行秘密任务骗得韦力的信任，一同前往品酒大会。拍卖现场，张水意外的发现指使自己来参加拍卖会的老板方长方也在现场，而此时的方长方好像从没认识过张水...品酒会的主持者利芳（杜鹃 饰）与各路买家逐一品酒，只有通过考验的人才可以参与到竞拍环节。利芳同父异母的哥哥LK此时在众人之外静静的看着所发生的一切，谁也想不到，拍卖会的真正目的根本不是卖酒……', '张涵予', '黎明', 3.2, 7337, 'tt3699104', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2458368616.jpg', 63, 22.8, 10.1, 1.5, 2.6, '-0.037340,0.182390,-0.709768,0.373947,-0.268623,0.067978,0.256627,-0.013227,-0.530343,-0.421557,0.435247,0.654968,-0.280410,0.187306,0.512694,-0.384259,-0.013313,-0.416425,-0.127608,-0.243466,-0.334643,-0.649426,0.045126,-0.317036,-0.020363,-0.105872,0.391589,0.322593,-0.258432,0.481292,0.607294,0.094201,-0.149338,0.505470,0.116915,-0.577653,0.273499,0.497383,-0.509316,0.207797,-0.372036,-0.331948,-0.454577,0.127638,0.346783,0.396202,0.411499,-0.417559,-0.151074,0.074898,0.052929,-0.331406,0.445136,-0.047435,0.245359,0.125290,0.279631,0.196406,-0.218767,0.219956,0.011686,-0.169034,-0.678379,0.070926,0.395469,0.235497,-0.329594,0.257921,-0.135736,-0.129090,-0.203937,-0.163570,0.390020,0.633936,0.447284,0.162401,0.010072,0.012757,-0.621318,0.289277,0.776666,0.086694,0.162823,0.185112,0.137604,-0.631641,0.200868,-0.366098,-0.119499,0.426398,0.012677,0.104453,0.218007,-0.449351,-0.474911,-0.232024,0.070205,-0.356329,0.290578,-0.147620,0.097283,-0.991830,0.046759,-0.013213,-0.035311,-0.049840,0.128707,-0.454494,0.457964,-0.682567,0.201573,0.265449,0.133785,-0.658124,0.662297,0.179773,-0.166263,-0.476278,-0.334754,-0.357383,0.397435,0.126140,-0.098202,0.049021,0.309766,-0.326561,0.015752,0.001102', '24751811', '3147969', '25833539', '1498811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26661189', '脱单告急', '喜剧', '一次偶然，让单身四年的气筒哥何晓阳(董子健 饰)和校园大姐大关欣(钟楚曦 饰)成为了绯闻情侣。为了摆脱何晓阳，关欣决定帮助他追求女神李舒舒(春夏 饰)。在关欣的指导下，何晓阳拥有了追求女神的完美公式，并距离脱单之日越来越近。但是面对真爱，何晓阳却分不清追爱公式到底有没有用⋯⋯', '董子健', '柯孟融', 5.4, 20517, 'tt8319694', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2517694523.jpg', 9.9, 31.5, 41.3, 13.2, 4, '0.074761,0.113535,-0.300155,0.420623,0.138140,-0.373723,0.312256,-0.091945,0.121336,-0.489893,0.054044,0.138311,-0.174856,0.158294,0.138054,-0.260903,0.056466,-0.696987,0.501345,-0.216282,-0.189833,-0.396065,-0.038877,0.331263,-0.118588,-0.461743,0.825105,-0.001068,-0.202352,0.156268,0.386816,0.166867,-0.074124,0.147022,-0.097800,-0.356541,0.029420,0.502018,-0.614491,0.250718,0.090196,-0.115394,-0.140585,0.228468,-0.117221,0.053942,0.570138,-0.489467,-0.222379,-0.024257,0.451979,-0.121504,-0.057316,-0.105261,0.130514,-0.189193,0.225158,0.376265,0.065383,0.033689,0.158633,0.000118,-0.604375,-0.012601,0.106519,-0.264463,-0.396217,0.113547,-0.060393,-0.147001,0.307182,-0.293963,-0.030734,0.345787,0.505301,0.478709,-0.369430,-0.145647,-0.349275,0.216039,0.589684,0.338879,-0.121929,0.711023,-0.262369,-0.398579,-0.091800,-0.256013,-0.437550,0.252201,-0.203888,0.139703,-0.038477,-0.039918,-0.546942,0.102665,-0.198504,0.215339,0.197843,-0.660270,-0.085391,-0.230586,-0.004671,-0.128384,-0.089159,0.145400,0.113108,-0.883346,0.473682,-0.969575,0.166323,0.458619,0.499882,-0.755043,0.748083,0.392612,-0.462832,-0.530985,-0.086356,0.207272,-0.209790,-0.037220,-0.261714,0.114207,-0.152074,-0.129725,-0.513546,0.385923', '30345227', '5985887', '2124718', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26661191', '奇门遁甲', '动作', '新上任的捕快刀宜长（李治廷 饰）奉旨判案，误打误撞救下了精通“奇门遁甲”之术的江湖组织“雾隐门”女弟子铁蜻蜓（倪妮 饰）。铁蜻蜓受门派老大（伍佰 饰）之托，调查神秘的天外来物踪迹，当众人惨败之际，二师兄诸葛青云（大鹏 饰）却带着神秘少女小圆圈（周冬雨 饰）归来，并称此人是新任掌门，铁蜻蜓与诸葛青云陷入芥蒂，另一边老大与其它几大门派长老也因为抢夺神器而开始厮杀。因为“天外来客”的降临，各大门派对雾隐门进行了追杀，因为小圆圈身世不明，门派内也争执不断，眼看大敌当前，正邪之战即将爆发，一场天地浩劫即将来临……©豆瓣', '大鹏', '袁和平', 4.4, 125205, 'tt6814080', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2507566212.jpg', 24.7, 40.4, 27.1, 5.9, 1.8, '-0.165104,0.064962,-0.344116,0.235157,0.327994,0.093813,0.223763,0.374316,-0.583766,-0.542220,0.206486,0.369960,-0.109993,0.043946,0.208905,-0.190597,0.106129,-0.571120,-0.279656,-0.068345,-0.165314,0.097944,-0.032449,-0.013937,0.074798,-0.243044,0.456718,0.361693,-0.362084,0.509795,0.303476,0.182844,-0.849577,0.165124,0.120440,-0.356304,0.250191,0.361554,-0.455820,0.016131,-0.622254,-0.159145,-0.196828,0.130978,-0.120537,0.414668,0.307767,-0.531387,0.058998,-0.457201,-0.141574,-0.318511,-0.208088,0.026270,0.736510,0.387808,0.232594,0.261613,0.207134,-0.134478,-0.215853,-0.150697,-0.256310,0.183701,0.372440,0.235535,-0.344564,0.464107,-0.148214,-0.091323,-0.293885,-0.182086,0.193391,0.199191,0.284023,-0.204297,-0.094790,-0.288000,-0.436813,0.111131,0.401439,-0.041568,0.189210,-0.282555,0.480637,-0.314054,-0.101559,-0.165398,-0.018138,0.013845,0.738893,-0.004599,0.159002,0.488148,-0.377239,-0.052545,-0.265239,0.198050,-0.139605,-0.102928,-0.023030,-0.697263,0.013042,-0.237398,-0.194600,-0.203584,0.357123,0.236389,0.585848,-0.672298,0.349349,0.029126,-0.067908,-0.425140,0.274088,0.003415,0.121578,-0.350812,-0.309115,-0.203963,0.076877,0.531461,0.158261,0.259398,-0.134344,-0.136974,0.137050,-0.232711', '25723905', '2369613', '26365262', '26863060');
