INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26661194', '脱皮爸爸', '剧情', '中年失意的儿子田力行（古天乐饰）在生活上遇到了重重危机：母亲病逝、工作不顺、妻子要求离婚。正处在这苦不堪言的困境中时，田力行79岁的痴呆父亲田一雄（吴镇宇饰）却突如一只再生的蝉，接二连三地脱皮并且不断变年轻——60岁、52岁、37岁、28岁、19岁。父亲一生中的六个阶段再现，也使得田力行穿梭了“六个爸爸”的六个年代，从未与父亲认真相处过的田力行重新认识了这六个阶段的父亲，从父亲波折的一生中，他似乎找到了自己的出路和重新起步的方向……', '吴镇宇', '司徒慧焯', 5.4, 6214, 'tt6135054', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2516154772.jpg', 7.4, 34.2, 43.1, 10.5, 4.8, '-0.255588,0.026571,-0.668863,0.383197,-0.509181,-0.717931,0.747431,0.002854,-0.513330,-0.617330,-0.007715,0.685465,-0.229989,0.906732,0.350130,-0.234413,0.359017,-0.764150,-0.317113,0.155769,-0.373566,-0.188716,-0.298498,-0.070860,-0.294261,-0.338190,0.361267,0.098007,0.133939,0.528811,0.174768,0.364183,0.070674,0.148486,-0.164171,0.150332,0.152510,0.431483,-0.197402,-0.057051,-0.217873,-0.425151,-0.094179,0.050487,-0.105445,0.926413,0.846823,0.081826,-0.380356,-0.350104,0.554510,0.150153,-0.558820,0.293694,0.549969,0.116279,0.196326,0.070810,-0.180508,-0.140247,-0.448708,-0.165031,-0.655456,-0.221079,0.062319,-0.094964,-0.717628,0.094991,0.067194,-0.091262,0.113164,-0.204830,0.063699,0.684155,0.054436,0.576664,-0.652125,-0.044448,-0.429458,0.360154,0.561221,0.085374,-0.538048,0.282447,-0.170408,-0.526557,0.063100,-0.184933,-0.531333,-0.017973,0.195189,0.065937,-0.262095,0.141168,-0.284548,0.158185,-0.257836,0.099033,-0.044948,-0.178921,-0.270821,-0.003142,0.022105,-0.755852,-0.459158,0.297184,-0.200662,-0.399444,0.672877,-0.323917,0.272516,0.109576,0.218019,-0.291039,0.633109,0.212515,0.348329,-0.611435,0.301870,0.286572,-0.448989,0.091852,0.212587,0.332807,-0.270616,-0.062621,-0.581293,0.570449', '2122766', '1292207', '26871465', '1306020');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26661229', '隧道尽头', '惊悚', '华金（莱昂纳多·斯巴拉格利亚 Leonardo Sbaraglia 饰）是双腿瘫痪的残疾人，终日要与轮椅相伴。然而，华金同时也是一位经验非常丰富的工程技术人员，精通机械学，还拥有着比常人灵敏数倍的听力，凭借着自己出类拔萃的专业知识，华金将自己的生活安排的井井有条。一天，一位美丽的单身母亲波塔（克拉拉·拉戈 Clara Lago 饰）带着她6岁的小女儿贝蒂（Uma Salduende 饰）前来投宿，母子两人的到来让华金原本苍白的生活变得生动鲜活起来。一次偶然中，华金得知了自己的房子里住着一伙劫匪，他们正打算利用在房子地下挖隧道的方式来实行他们抢劫银行的计划。©豆瓣', '莱昂纳多·斯巴拉格利亚', '罗德里戈·格兰德', 7, 44636, 'tt5133308', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2563538599.jpg', 0.2, 4.4, 46.1, 41.7, 7.6, '0.116327,-0.025264,-0.755898,0.686718,-0.437257,-0.256296,0.733539,0.134117,-0.636620,-0.267218,0.292967,0.601343,0.029116,0.267668,0.120247,0.076594,-0.177634,-0.527069,-0.083016,-0.061366,-0.232349,-0.540809,-0.475965,-0.246634,-0.280012,-0.464705,0.328601,-0.124973,0.068123,0.423993,-0.058246,0.051535,0.136279,0.222965,-0.326673,-0.206309,-0.000408,-0.197689,-0.128894,0.192356,-0.042343,0.006924,-0.239986,0.086840,0.094624,0.304149,0.585391,-0.002260,0.034094,-0.028159,0.259208,-0.040559,0.034013,0.256423,0.398711,-0.043213,0.197764,0.144613,-0.455571,0.127440,0.259363,-0.249017,-0.713199,0.062963,0.173509,0.097379,-0.779445,0.268714,-0.148328,-0.049123,0.102725,-0.574180,-0.165927,0.318095,0.212182,0.434001,0.071622,-0.024545,-0.617536,0.019828,0.450737,-0.034438,-0.152092,0.332898,-0.402008,-0.373879,-0.056273,-0.236713,-0.519975,-0.163710,0.330438,-0.131916,-0.228461,0.275822,-0.509837,0.296674,-0.338084,-0.061592,-0.319973,-0.217209,-0.073524,-0.887474,-0.072141,-0.476742,-0.208250,0.270208,0.094004,-0.327256,0.641521,-0.513999,-0.094630,0.539550,0.170296,-0.178066,0.537719,-0.214838,0.262413,-0.087964,-0.287408,0.186335,-0.075422,0.195112,0.066709,0.540582,-0.132593,0.060363,-0.482719,0.670468', '4924694', '1307897', '26677495', '26951746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26661608', '恶魔蛙男', '剧情', '大雨瓢泼的都市，邪恶欲望肆意横行。不经意间残忍而血腥的猎奇案件接连发生，有的人被饿犬撕咬而死，有的人被割掉和出生时同样重量的肉而死掉，有的被平均切成两半分送给妻子与情人，有的则被冻在冰柜中永葆不老的青春，更有人嘴里被塞满了大大小小的钉子。正为家庭矛盾所苦恼的搜查一课刑警泽村久志（小栗旬 饰）受命追查此事，随着调查的深入，他发现凶手全系一人所为，而且热衷在雨天行凶作案，之后他更发现所有死者全与许多年前的一起案件有关，偏偏泽村离家出走的妻子（尾野真千子 饰）也被卷入其中。争分夺秒的追查，凶手已对泽村亮出獠牙……本片根据日本漫画家巴亮介的同名原作改编。©豆瓣', '小栗旬', '大友启史', 6.4, 13792, 'tt5227140', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2325706844.jpg', 2, 12.6, 54.6, 24.6, 6.2, '0.349300,-0.246377,-0.645487,0.186042,0.028574,-0.001598,0.851377,0.081443,-0.417175,-0.157579,0.194946,0.524148,-0.441961,-0.035670,0.038495,-0.255089,0.017068,-0.653122,-0.124462,-0.172926,-0.387688,-0.391995,-0.141145,-0.167072,-0.002072,-0.099205,0.661990,0.136099,-0.117629,0.269196,0.359873,0.389007,-0.287107,0.437404,-0.271406,0.028337,-0.008020,-0.071199,0.098099,0.051494,0.064745,-0.369773,0.134761,-0.092417,-0.367702,0.508211,0.742954,-0.163109,-0.242777,-0.328753,0.552970,-0.404591,-0.119106,0.332540,0.619461,0.272251,0.018457,0.393335,-0.297051,-0.026193,0.384363,-0.027992,-0.870851,-0.106807,0.287089,0.245236,-0.408483,0.384874,0.008856,0.024022,0.141907,-0.017227,0.379872,0.330467,0.296786,0.190376,-0.090399,-0.084640,-0.526552,0.156709,0.621446,-0.272111,-0.042969,0.086995,-0.087697,-0.329716,0.193475,-0.364280,-0.170026,0.045589,0.351075,0.219015,-0.447845,0.407955,-0.610155,-0.072570,-0.071757,-0.116905,-0.109544,-0.257772,-0.412711,-0.374160,-0.373492,-0.334772,-0.210772,0.083668,0.241159,-0.199018,0.427384,-0.559368,0.244324,0.533028,0.197701,-0.326890,0.473119,-0.001964,-0.026114,-0.031813,-0.253011,0.225743,0.547623,0.142751,0.361011,0.271589,-0.111721,-0.189423,-0.412470,0.141872', '25828589', '2988294', '21619567', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26662159', '海绵宝宝：营救大冒险', '喜剧', '《海绵宝宝：营救大冒险》讲述了海绵宝宝心爱的宠物小蜗被绑架后，海绵宝宝和派大星前往失落的大西洋城展开营救冒险的故事。在这场充满危险又妙趣横生的营救行动中，海绵宝宝和他的朋友们用实际行动证明了友谊的力量无限大！', '基努·里维斯', '蒂姆·希尔', 6.1, 12261, 'tt4823776', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2574153046.jpg', 4.2, 18.8, 52.4, 18.2, 6.3, '0.157672,-0.176487,-0.425009,0.537578,-0.144492,0.076239,0.573850,0.173635,-0.266946,0.360663,0.174927,0.879868,-0.130549,0.229136,-0.090198,-0.078141,-0.382157,-0.806944,-0.365189,0.132200,-0.301281,-0.405740,-0.102529,-0.025185,0.463802,-0.390417,0.496405,-0.166113,-0.344030,0.648689,-0.012734,0.181048,-0.308371,0.403818,0.002953,0.035516,0.139062,0.546532,-0.198129,0.398230,0.268668,0.249314,0.226576,0.571303,-0.084060,0.277880,0.946018,-0.539280,0.255097,-0.077109,-0.012907,-0.693629,0.052245,0.241359,-0.044288,0.406532,0.134526,0.058727,-0.093390,0.257364,0.177964,-0.242886,-0.742414,-0.232016,0.149263,0.060856,-0.664504,0.137088,0.148957,0.249917,0.508326,-0.394057,0.293535,0.471550,0.015627,0.563002,-0.475376,0.036206,-0.387830,0.157217,0.645340,-0.244632,0.203059,0.088438,-0.391638,-0.204190,0.425980,-0.169953,-0.254255,-0.065814,0.844050,0.133745,-0.552073,0.491194,-1.016575,-0.238341,-0.212200,-0.181418,-0.027006,-0.523504,0.335667,-0.727704,0.051866,-0.117691,0.042287,-0.083465,0.281853,-0.129089,1.047764,-0.604945,0.065179,0.882168,0.214019,-0.518800,0.514891,0.249032,-0.024708,-0.462159,0.432115,0.092350,-0.089500,0.357458,0.107119,0.480238,0.072190,0.221208,-1.008273,0.416762', '4181031', '3811356', '27069070', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26662168', '独家新闻', '剧情', '影片是根据原田真人担当导演编剧的电影《盗写 1/250秒》为原作改编，讲述了昔日小报记者都城静（福山雅治饰）目前担当八卦专门杂志的狗仔，在沉迷于酒精赌博中混混度日的他因一件小事和被分配到同部门的新人记者行川野火（二阶堂富美饰）一起成为搭档。二人在捕获到独家新闻之后，引起一场更大事件的发生。', '福山雅治', '大根仁', 7, 11312, 'tt5194226', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2401343730.jpg', 0.7, 5.3, 46, 39.3, 8.7, '0.416564,-0.073061,-0.297413,0.331378,0.248224,0.213691,0.452685,0.188779,-0.433498,-0.297081,0.359117,0.487348,-0.761110,0.075951,0.515531,-0.478043,-0.259489,-0.657230,-0.016350,0.113267,0.133126,-0.185300,-0.101464,-0.173984,-0.323453,-0.354267,0.876275,-0.038470,-0.332331,0.228999,0.320734,0.162178,-0.136228,0.084900,0.515706,0.364437,0.141800,0.079558,-0.326399,0.422778,-0.014108,-0.314577,-0.113101,-0.173807,0.149439,0.239687,0.654659,-0.168614,-0.355830,0.037595,0.588186,-0.377800,-0.032061,-0.150374,0.483563,0.228919,0.311277,0.312904,-0.159833,0.225568,-0.088435,0.010253,-0.442893,0.021283,0.308744,0.398166,-0.153032,0.544073,-0.206239,0.109325,0.070417,-0.094209,0.187071,0.064516,0.386899,0.275382,0.142682,0.117968,-0.324617,0.821550,0.686778,0.159201,-0.059131,0.298872,0.010034,-0.352656,-0.185638,-0.431506,-0.319911,0.193123,0.326403,-0.352605,-0.003706,0.397989,-0.515210,-0.159073,0.214229,-0.248068,0.297402,-0.312990,-0.041056,-1.063479,-0.126542,-0.155155,0.116515,-0.060188,0.522978,-0.584608,0.870149,-0.734138,-0.177035,0.729075,-0.188421,-0.413904,0.555132,-0.354165,0.223450,-0.066345,-0.079413,-0.320275,0.473509,0.365022,0.085329,0.227022,-0.152256,-0.485614,-0.141204,-0.004048', '1322847', '2369613', '5403927', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26662192', '王牌逗王牌', '喜剧', '囧探宝爷（刘德华 饰）与侠盗洛家豪（黄晓明 饰）强强联手，与世界恐怖组织抢夺“上帝种子”，所谓“上帝种子”是一种神奇的种子，无论丢在哪里，只需要一点水，就可以迅速长出参天大树。而唯恐天下不乱的恐怖组织居然拿到了这种神奇的“上帝种子”，试图改变甚至掌控这个世界。为了维护世界和平，宝爷和家豪在A梦（王祖蓝 饰）、洛家欣（欧阳娜娜 饰）等人的帮助下，冒险夺宝拯救世界的故事。', '刘德华', '王晶', 3.3, 41803, 'tt5425144', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2380681527.jpg', 55.6, 29.1, 12.1, 1.9, 1.3, '-0.171898,0.684164,-0.377555,0.366642,-0.329873,0.318635,0.168154,0.025729,-0.413460,0.098854,-0.128370,0.399717,-0.080498,-0.146483,0.142814,0.273922,-0.188825,-0.517653,-0.012915,0.087254,-0.523426,-0.361323,-0.842832,-0.520675,-0.282685,-0.429945,0.837394,0.300270,-0.362835,0.011114,0.281442,0.324502,-0.317504,0.046514,-0.286819,-0.190014,0.015164,0.563366,-0.610150,0.186974,-0.130189,0.081195,-0.079443,0.198617,-0.200008,-0.167214,0.342346,-0.636474,-0.103415,-0.427650,0.333655,-0.295359,-0.220669,-0.288710,-0.055033,-0.368650,0.244842,0.184607,0.121157,0.041804,0.476921,-0.143788,-0.966073,-0.336530,0.332367,0.153141,-0.403754,0.112643,-0.040635,-0.051087,0.172685,-0.272536,0.304616,0.289569,0.721992,0.406700,-0.336517,-0.620318,-0.470217,0.262160,0.402565,-0.183748,-0.255136,0.376557,-0.060472,-0.212293,-0.550572,0.129478,-0.338960,0.125499,0.259433,0.114815,-0.019846,0.176681,-0.713068,-0.093078,0.026957,0.010082,0.428782,-0.654647,-0.094686,-0.214905,-0.128981,-0.036331,-0.152501,0.163305,0.433111,-0.296643,0.904695,-0.786331,0.329742,0.421640,0.087480,-0.588022,0.528331,-0.009151,-0.307966,-0.758454,-0.170441,0.279549,0.107329,0.176790,-0.079162,0.160451,-0.088505,0.145971,-0.253979,0.363658', '35377026', '24284209', '7155241', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26662193', '前任3：再见前任', '喜剧', '一对好基友孟云（韩庚 饰）和余飞（郑恺 饰）跟女友都因为一点小事宣告分手，并且“拒绝挽回，死不认错”。两人在夜店、派对与交友软件上放飞人生第二春，大肆庆祝“黄金单身期”，从而引发了一系列好笑的故事。孟云与女友同甘共苦却难逃“五年之痒”，余飞与女友则棋逢敌手相爱相杀无绝期。然而现实的“打脸”却来得猝不及防：一对推拉纠结零往来，一对纠缠互怼全交代。两对恋人都将面对最终的选择：是再次相见？还是再也不见？', '韩庚', '田羽生', 5.6, 375915, 'tt7830888', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2508926717.jpg', 13, 24.9, 39.6, 16.3, 6.1, '0.256365,-0.118923,-0.329476,0.286069,0.363340,-0.382471,0.660772,0.131137,-0.071366,0.003569,-0.005529,0.532519,-0.680816,-0.024804,0.248225,-0.503378,-0.007461,-0.933780,0.240609,0.140157,0.062271,-0.407905,-0.087796,0.167833,-0.265225,0.084560,0.641412,-0.163645,-0.143001,0.597985,0.664724,-0.109571,-0.483413,0.301352,0.052489,-0.022424,-0.033215,0.695652,-0.655735,-0.054330,-0.099274,0.024542,0.010165,0.153428,0.031652,0.408783,0.752519,-0.334787,-0.352411,0.213337,0.297949,-0.206691,-0.248885,0.113290,0.120396,0.009109,0.379390,0.378178,-0.114470,-0.165322,0.201044,0.102857,-0.459692,0.414650,0.149555,-0.151110,-0.223782,0.551200,-0.070384,-0.017318,0.131032,-0.079587,0.176314,0.680461,0.657963,0.399598,-0.222144,-0.061235,-0.118051,0.341031,0.783204,0.194934,-0.207789,0.414838,0.087521,-0.221819,-0.080130,-0.102553,-0.416110,-0.127644,0.078787,0.206093,-0.067541,0.400898,-0.719851,-0.071199,-0.352252,0.126022,0.147793,-0.567277,0.185045,-0.546625,-0.058136,-0.304392,-0.499865,0.357910,0.411612,-0.317449,0.385320,-0.864605,-0.035418,0.134929,0.290898,-0.827059,0.704025,0.518094,0.047185,-0.344675,0.132232,0.249763,-0.006923,-0.319599,0.121087,0.105128,-0.119397,0.224238,-0.467598,0.307497', '30345227', '25777330', '1293265', '3078390');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26662282', '神奇乐园历险记', '喜剧', '一位极富创造力的女孩小六月，偶然间发现了一座神奇的乐园。在乐园里，有着各式各样惊险刺激的游乐设施和形形色色的动物朋友。在这个奇幻的世界里，将会发生怎样意想不到的故事呢？', '索菲亚·玛丽', '迪兰·布朗', 6.1, 3687, 'tt6428676', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2552076937.jpg', 2.3, 17, 58.1, 18.1, 4.5, '0.362037,0.024951,-0.990070,0.685763,-0.090390,0.470600,1.334416,-0.247514,-0.762021,-0.318308,0.348205,0.999012,-0.571285,0.448220,0.377361,-0.107902,-0.317968,-0.324340,-0.200611,-0.592762,-0.570682,-0.353431,-1.010250,-0.084667,0.222199,-0.256929,0.454640,0.220847,-0.385570,0.157769,0.050326,-0.028958,-0.582483,0.315665,-0.528176,-0.031573,0.326939,0.587874,-0.080378,0.186758,-0.215458,-0.192503,-0.085853,-0.207499,-0.217923,-0.278166,1.028700,-0.795520,-0.594778,0.166560,0.695831,0.225563,0.029033,0.117262,0.346189,0.072690,0.146041,-0.026210,-0.257449,0.115160,0.323066,-0.366880,-0.931035,-0.171760,0.266906,0.325570,-0.299659,0.448699,0.630101,-0.356922,0.259540,-0.390817,0.551560,0.240239,0.680464,0.830636,0.301134,0.260245,-0.378906,0.013361,0.745970,0.027074,-0.377707,0.518921,-0.384843,-0.595239,-0.187104,-0.104874,-0.739957,0.209175,0.163379,-0.242926,-0.568590,0.538786,-1.279393,0.633787,0.192689,-0.126626,-0.193530,-0.010261,-0.566892,-0.790102,0.097539,-0.528456,0.123276,0.434378,0.167229,-0.198942,1.377519,-1.157774,0.452158,0.463033,0.044138,-0.227138,0.823407,-0.217300,0.023857,-0.005501,-0.537929,0.343555,0.031510,0.334434,-0.633734,0.748030,-0.035405,-0.502899,-0.757499,0.496928', '3005387', '4181031', '24284209', '2357162');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26662331', '图兰朵：魔咒缘起', '爱情', '大汗国派兵出征，军队意外带回小国王后（苏菲·玛索 饰）祖传的三色镯，一个侵蚀帝国上下的魔咒由此开启。骄傲的帝王（姜文 饰）为解救被魔咒附身的女儿图兰朵（关晓彤 饰），遍寻天下能人破局。自小流浪到汗国的孤儿卡拉夫（迪伦·斯普罗斯 饰）与公主相遇并互相倾慕。因同情图兰朵的痛苦境遇，卡拉夫不惜以性命为代价解救心上人，然而却不知那魔咒与自己神秘的身世密切相关。此时的帝国王室因为魔咒掀起一场腥风血雨，嗜杀的将军（胡军 饰）欲凭借三色镯的力量谋权，君臣倾轧一触即发。每个人都面临着艰难选择，几方势力因为魔咒逐渐卷进了旋涡中心。', '关晓彤', '郑晓龙', 3.1, 29106, 'tt6703486', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2697608977.jpg', 58.2, 30, 9.7, 1.5, 0.6, '-0.140664,0.268401,-0.612710,0.635784,0.373024,0.059777,0.622957,0.218142,-0.348949,-0.436526,0.440729,0.508434,0.131657,-0.107399,0.230965,-0.104691,-0.060926,-0.571471,-0.002307,-0.125321,-0.015232,-0.261798,-0.225292,-0.136277,-0.190264,-0.655110,0.620127,0.069456,-0.136775,0.354357,0.355915,0.533699,-0.258202,0.299593,0.195485,-0.114692,-0.109093,0.004546,-0.389008,0.058484,-0.245401,-0.110414,-0.144004,0.229519,-0.300858,0.377410,0.562632,-0.740074,0.454563,-0.472206,0.338212,-0.389259,-0.020049,0.168522,0.177000,0.101740,0.142052,0.039292,-0.163920,-0.131191,0.247110,-0.196923,-0.729859,-0.118265,0.365392,0.191297,-0.356178,0.372985,-0.088873,-0.084121,0.094562,-0.109951,0.192904,0.541098,0.410552,0.327097,-0.306167,0.139077,-0.392564,-0.068416,0.717901,-0.192080,-0.277908,-0.145110,-0.172764,-0.335217,0.144865,-0.507962,-0.553761,-0.018197,0.426947,0.152823,0.260603,0.769374,-0.478828,-0.246383,-0.518677,0.116350,0.268208,-0.532192,0.108744,-0.297983,-0.325656,-0.110422,-0.076612,0.146786,0.272701,-0.063416,0.455830,-0.525188,0.105595,0.448773,0.248404,-0.466166,0.204733,-0.024121,0.045461,-0.231281,-0.361649,0.609484,0.165851,0.193523,0.091732,0.000485,0.051710,0.246913,-0.220806,0.256627', '10791575', '26667010', '4889554', '5308201');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26662345', '神战：权力之眼', '动作', '故事发生在繁荣昌盛的尼罗河畔，在天神荷鲁斯（尼古拉·科斯特-瓦尔道 Nikolaj Coster-Waldau 饰）的和平统治之下，百姓们安居乐业，生活在一片祥和之中。然而好景不长，邪恶的黑暗之神赛特（杰拉德·巴特勒 Gerard Butler 饰）利用阴谋诡计夺走了荷鲁斯的王座和双眼，将他驱逐囚禁，赛特生性残暴而好战，很快，整个国家陷入了混乱之中。贝克（布兰顿·思怀兹 Brenton Thwaites 饰）只是一介平凡的人类窃贼，却在意外之中成为了拯救人类的唯一希望。为了对抗强大的赛特，他千里迢迢找到了荷鲁斯，向他寻求帮助。就这样，一人一神的奇怪组合成立了。为了重新获得力量，荷鲁斯必须夺回他的眼睛，以此为目标，一行人踏上了旅途。©豆瓣', '尼古拉·科斯特-瓦尔道', '亚历克斯·普罗亚斯', 6.6, 49910, 'tt2404233', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2324130130.jpg', 2.7, 14.6, 51, 24.4, 7.3, '0.200634,0.540516,-0.676744,0.679271,-0.075846,-0.193965,0.671862,0.199062,-0.414307,-0.232152,0.248644,0.665169,0.180958,-0.108813,0.447066,0.102745,-0.397217,-0.541833,0.030799,-0.201179,-0.127571,-0.271415,-0.613886,-0.291007,-0.160305,-0.725187,0.814212,0.416969,-0.290536,0.341631,0.043663,0.579961,-0.055942,0.270751,-0.178800,-0.243930,-0.104152,-0.170950,-0.290920,0.323324,-0.439777,-0.285966,-0.264209,0.488452,-0.295919,0.126037,0.644167,-0.741413,0.060116,-0.340220,0.286039,-0.483403,-0.146012,0.091059,-0.075392,-0.147212,-0.005835,0.132203,-0.180121,0.009061,0.336780,-0.191801,-1.192569,-0.079676,-0.110434,0.253298,-0.589788,0.384078,0.106824,-0.293039,0.222358,-0.225065,0.179684,0.593012,0.334468,0.519664,-0.073060,0.091822,-0.406595,-0.058280,0.873805,-0.206297,-0.578478,0.077558,-0.281367,-0.387486,0.035492,-0.379078,-0.372169,-0.352349,0.505742,-0.004481,0.174225,0.702433,-0.783711,0.043974,-0.274267,-0.292231,0.158012,-0.451022,0.024654,-0.355598,-0.272798,0.097663,-0.192758,0.004000,-0.109672,-0.305646,0.749158,-0.843278,0.407443,0.562098,0.388580,-0.381545,0.476588,-0.001709,0.296513,-0.168728,-0.104535,0.252579,0.385436,0.655164,0.208990,-0.043681,-0.125238,0.247177,-0.366821,0.594011', '26667010', '35377026', '3213270', '10440076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26662798', '京城81号2', '剧情', '《京城81号2》取材自东方四大鬼宅之首的京城81号地宫真实故事。民国末期，正逢乱世，京城军阀哗变，少帅张骘生（张智霖 饰）被逼迎娶大军阀之女纪金翠（钟欣潼 饰），随即府内怪事丛生，人心惶惶。不久后京城涌现大批“尸婴案”，一切矛头指向少帅原配夫人钮梦鹤（梅婷 饰），随后 钮梦鹤离奇失踪，一夜之间京城81号惨遭灭门，留下一座破败鬼宅。百年后，文物修复师宋腾在修复古宅过程中挖出大量婴儿尸骨与诡异符咒，一桩桩血淋淋的旧事似乎要将所有人拉进深渊，前世今生的恩怨情仇都一一浮现，而地宫冤魂鬼门索命的故事也就此拉开……©豆瓣', '张智霖', '钱人豪', 3.7, 28055, 'tt7627782', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2471580153.jpg', 39.8, 39.4, 17.1, 2.2, 1.5, '-0.201402,0.176279,-0.314793,0.037016,0.540396,0.293543,0.616603,0.005186,-0.729599,-0.162502,0.228233,0.523343,-0.318487,0.242730,-0.102639,0.127448,-0.007771,-0.619651,-0.180566,-0.490503,-0.225320,0.090521,-0.042650,-0.208389,-0.068171,-0.173412,0.394336,0.462967,0.071519,0.295580,0.073482,0.300601,-0.770752,-0.042897,-0.127062,0.199422,0.045069,0.230226,-0.247046,-0.084706,-0.614094,-0.232260,-0.201728,-0.162448,-0.267945,0.150970,0.595419,-0.117974,0.115867,-0.317167,0.275884,0.064396,-0.357996,0.113837,0.598028,-0.032537,0.201006,0.608204,-0.256862,-0.504769,0.185247,-0.212208,-0.156580,-0.282493,0.333107,0.047858,-0.299580,0.086249,-0.025993,0.202116,-0.083145,-0.070144,0.366612,0.252350,0.360725,0.022198,-0.142119,-0.105012,-0.455936,0.463086,0.276649,-0.382720,-0.186449,0.085092,0.470994,-0.219733,-0.165268,-0.168469,-0.036607,0.211331,0.416322,-0.091770,0.099457,0.850521,-0.421899,-0.459642,-0.410999,0.007688,0.298474,0.172244,-0.388165,-0.285667,-0.410762,0.328049,-0.060438,-0.112666,0.282924,0.403262,0.330759,0.005005,0.391818,-0.079411,-0.289290,-0.373326,0.152863,-0.355381,0.385970,-0.038111,0.045602,0.149978,0.248472,0.684765,-0.015515,0.154826,-0.504996,-0.274890,-0.516097,0.186579', '5996801', '30423193', '30219670', '26767512');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26665435', '护航父母', '喜剧', '丽莎（莱斯利·曼恩 Leslie Mann 饰）、米切尔（约翰·塞纳 John Cena 饰）和亨特（艾克·拜瑞豪兹 Ike Barinholtz 饰）本是八竿子打不到一起去的三人，却因为他们的孩子——朱莉（凯瑟琳·纽顿 Kathryn Newton 饰）、山姆（吉第安·艾朵 Gideon Adlon 饰）和凯拉（杰拉尔丁·维斯瓦纳森 Geraldine Viswanathan 饰）而被紧紧的联系到了一起。三个姑娘在学校里是最要好的朋友，即将面临毕业的三人秘密制定了一个计划，那就是在毕业舞会那天晚上破处。三名家长在一次偶然之中知晓了这个秘密，他们的内心里立刻响起了警钟，于是，三人决定联手阻止三个女孩愚蠢的计划，可是，这些大人们拟定的方案似乎也没有那么高明。©豆瓣', '莱斯利·曼恩', '凯·加农', 6.5, 6387, 'tt2531344', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2513652639.jpg', 1.7, 11.8, 52.7, 26.5, 7.4, '0.396745,-0.183780,-0.930456,0.474431,-0.205526,-0.437291,0.668983,0.051334,-0.498799,-0.403497,-0.004886,0.626710,-0.248815,0.273189,0.258493,-0.034277,-0.392083,-0.866883,0.101989,-0.397771,-0.287829,-0.572362,0.071549,-0.240519,-0.098680,0.020467,0.311929,-0.166064,0.170066,0.596493,0.388951,0.175824,-0.152007,0.350700,-0.069926,0.063919,0.457771,-0.163432,-0.260931,0.418415,0.067057,0.191537,-0.152722,0.242927,0.277872,0.591237,0.424296,-0.229618,0.021465,0.035716,0.036241,-0.091924,-0.091482,0.368159,0.511152,-0.127196,0.387910,0.058457,-0.208094,0.021390,0.138191,-0.106139,-0.538055,0.272687,0.158167,0.132103,-0.714965,0.351788,-0.106739,-0.164665,0.086246,-0.416026,0.249039,0.456274,0.315756,0.155737,-0.138064,-0.124442,-0.540091,-0.058845,0.684996,-0.061661,0.185607,0.136022,0.069345,-0.286243,-0.153903,0.206499,-0.319031,0.102859,0.574218,-0.028926,-0.129450,0.144764,-0.525460,-0.218430,-0.288718,-0.103021,-0.130908,-0.418969,0.153154,-0.628987,0.012834,-0.180001,-0.456697,0.404521,-0.011501,-0.028497,0.683242,-0.850912,0.146878,0.384393,0.340922,-0.317372,0.435659,0.271390,0.482373,-0.184501,0.169684,-0.227348,-0.075440,0.110773,0.249412,0.651507,0.123014,-0.256727,-0.492424,0.344997', '1301022', '34429100', '1293829', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26665875', '老千3：独眼杰克', '剧情', '神级老千异耳的儿子道日出（朴正民饰）结识了一只眼睛失明的神秘老千独眼（柳承范饰），从而进入了真正的高手世界。以独眼为首的众多技能派赌徒纷纷接到了能够改变命运的邀请牌“独眼杰克”，开始了一场生死赌博。', '朴正民', '权五光', 6.4, 15225, 'tt10927906', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2565181699.jpg', 1.6, 13.3, 55.1, 22.2, 7.8, '0.147257,0.258198,-0.123346,0.649429,-0.325143,-0.230707,0.379564,0.072848,-0.260771,-0.107736,0.529885,0.950987,-0.226544,0.472365,0.220916,-0.271964,0.306308,-0.674017,-0.417449,-0.296638,-0.368187,-0.169050,-0.499561,0.070078,0.208438,-0.278944,0.468283,0.109756,-0.433277,0.401818,0.443295,0.431882,0.070348,0.157624,-0.573173,-0.421430,0.324515,-0.538231,-0.151712,0.457972,-0.315666,-0.129483,-0.082242,0.400877,-0.383638,0.153799,0.889999,-0.545422,-0.061203,-0.385380,0.378638,-0.212815,-0.237599,0.086829,0.582707,-0.032209,0.292923,-0.128736,0.680261,0.129141,0.040730,0.166737,-1.037666,0.073251,-0.025380,0.153291,-0.626626,-0.021435,-0.007489,-0.387117,-0.043597,0.129072,0.209008,0.335921,0.276729,0.147848,0.049006,-0.089760,-0.443376,0.322428,0.529445,-0.076506,-0.190808,0.325082,0.275314,-0.871118,-0.132490,-0.283524,0.062334,-0.040559,1.271578,0.000853,-0.292050,0.217740,-0.620995,0.074279,-0.203770,-0.105791,0.019517,-0.174765,-0.182203,-0.816030,-0.461794,-0.136744,-0.298801,0.194473,0.111976,0.027761,0.928161,-0.759317,0.094098,0.595786,0.050614,-0.120196,0.637578,-0.059597,0.014347,-0.371629,0.009722,-0.288791,0.238815,0.755930,0.210144,0.141377,-0.204547,-0.117128,-0.071698,0.442606', '24756658', '27602116', '25928048', '1300324');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26666177', '杀戮都市：O', '动作', '高中生加藤胜（小野大辅 配音）和弟弟过着相依为命的生活，某日，加藤胜所在的地铁站遭到了无差别杀人犯的袭击，为了救人，加藤胜身中数刀不幸身亡，而当他再度睁开双眼之时，却发现自己完好无损的站在一个陌生的房间里，眼前是一个黑色的诡异圆球。和加藤胜在一起的，还有下平蕾佳（早见沙织 配音）、西丈一郎（郭智博 配音）和铃木良一（池田秀一 配音）三人，他们和加藤胜一样，都是已死之人。蕾佳告诉满头雾水的加藤胜，黑色的圆球名叫“GANTZ”，而他们所要做的，是等待圆球下达的命令。这一次，四人被传送到了大阪，他们所要面对的，是叫做“滑瓢”的怪物以及一场盛大的百鬼夜行，只有在GANTZ所规定的时间内杀掉所有的怪物，加藤胜才能够得到再次回到弟弟身边的机会。©豆瓣', '小野大辅', '佐藤敬一', 8.2, 52993, 'tt5923962', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2388010000.jpg', 0.7, 2.6, 18.2, 43.6, 34.9, '0.071843,-0.164924,-0.670284,0.572924,-0.287445,-0.215020,0.791960,0.126537,-0.118877,-0.427405,0.252607,0.691462,-0.250915,0.347195,0.225389,-0.091338,-0.095435,-0.892900,-0.572260,-0.319348,-0.224893,-0.567664,-0.022478,0.014066,0.006541,-0.139084,0.748197,0.181115,0.080556,0.576010,0.424728,0.345685,-0.306618,0.386299,-0.056567,-0.089918,-0.035908,-0.141553,-0.001883,0.414246,-0.045600,-0.225529,-0.076426,0.360082,-0.130490,0.333770,0.623007,-0.373937,-0.089458,-0.358340,0.080720,-0.285876,-0.246731,0.218698,0.472429,-0.323452,0.236904,0.094814,-0.152584,0.097769,0.113004,-0.010765,-0.724377,-0.059108,0.020381,0.339126,-0.395697,0.367414,-0.071587,-0.168175,0.355022,-0.299403,0.147703,0.231093,0.337506,0.248858,-0.474119,0.057572,-0.379786,-0.116085,0.761377,0.042545,0.023262,0.269849,-0.049040,-0.420088,-0.095099,-0.222313,-0.204735,-0.004690,0.287442,0.418433,-0.233924,-0.190875,-0.426889,-0.043227,-0.153040,-0.102499,-0.090439,-0.321396,-0.245834,-0.733313,-0.055710,-0.521687,-0.318699,0.715798,-0.081281,-0.363215,0.699111,-0.918159,0.065518,0.457193,0.364403,0.053366,0.458847,0.068550,0.043954,-0.074552,0.033596,-0.179286,0.320366,0.548125,0.089449,0.403912,-0.093753,-0.108002,-0.722089,0.300073', '25938113', '25723905', '3811356', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26667010', 'X战警：黑凤凰', '动作', '影片剧情围绕X战警中最受欢迎成员之一的琴·葛蕾展开，讲述她逐渐转化为黑凤凰的故事。在一次危及生命的太空营救行动中，琴被神秘的宇宙力量击中，成为最强大的变种人。此后琴·葛蕾不仅要设法掌控日益增长、极不稳定的力量，更要与自己内心的恶魔抗争，她的失控让整个X战警大家庭分崩离析，也让整个星球陷入毁灭的威胁之中。《X战警：黑凤凰》是迄今为止气氛最紧张、情感最丰富的一部《X战警》电影，是《X战警》系列20年来的集大成之作，大家非常熟悉和热爱的变种人大家庭即将面对最为强大的敌人——而她恰恰还是他们中的一员。', '苏菲·特纳', '西蒙·金伯格', 5.7, 231747, 'tt6565702', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2555886490.jpg', 4.5, 25.8, 51, 15.2, 3.5, '0.009687,0.176683,-0.796404,0.870024,0.123114,0.227639,1.014845,-0.105608,-0.538775,-0.363484,0.344395,0.758296,0.019718,0.000288,0.330328,0.020401,-0.024399,-0.436299,-0.363004,0.174870,-0.323560,-0.056387,-0.489018,-0.112349,-0.193368,-0.562621,1.075100,0.334064,-0.673801,-0.031246,0.092453,0.525577,-0.132899,0.356804,0.109944,-0.291431,-0.275382,-0.206218,-0.258300,0.129984,-0.145096,-0.278769,-0.083713,0.562325,-0.359075,-0.036134,0.924095,-0.482829,0.144358,-0.426473,0.559505,-0.595814,-0.520708,-0.261303,0.283162,0.012715,0.201013,0.111829,-0.130718,0.162944,-0.318183,-0.240856,-1.451869,0.012497,0.328743,0.164848,-0.286531,0.324254,0.170568,0.097923,0.164354,-0.058278,0.321282,0.148562,0.240511,0.345115,-0.160538,-0.075265,-0.279021,0.052526,0.922179,-0.255942,-0.563971,0.283669,-0.440038,-0.475830,-0.479333,-0.640625,-0.507800,-0.107657,0.203780,0.425099,0.107544,0.738577,-0.972422,0.173513,-0.091992,-0.418515,0.019506,-0.536541,0.101470,-0.604581,-0.475661,-0.336120,0.017496,-0.117495,0.196789,-0.415439,1.203390,-0.845660,0.105680,0.356737,0.142658,-0.392340,0.428385,-0.019131,0.127368,-0.497138,-0.112954,0.358741,-0.003396,0.151332,-0.023082,0.205477,-0.136526,-0.088476,-0.469958,0.784254', '27602116', '3001114', '24284209', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26667056', '逆时营救', '动作', '单亲妈妈夏天（杨幂 饰）作为物理研究所的高级研究员，与所长共同研究出可使生物体穿越虫洞进行时间旅行的技术，当研究有了突破性进展时，儿子豆豆（张艺瀚 饰）却被神秘绑匪崔琥（霍建华 饰）绑架，为了挽救豆豆的生命，夏天冒险用未完成的粒子技术 返回1小时50分钟前，却令事情变得更加复杂，更遭遇到意想不到的困局：要去面对三个自己在时空旅行中的变异互博。而崔琥的背后故事也渐渐浮出水面……', '杨幂', '尹鸿承', 4.7, 73844, 'tt5342650', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2472784892.jpg', 22.5, 35.5, 30.6, 8, 3.4, '-0.046292,-0.045681,-0.391194,0.280266,0.005419,-0.298919,0.505291,-0.180857,-0.526831,-0.338480,0.044601,0.198342,-0.072591,-0.099119,0.054616,-0.317215,-0.462570,-0.283993,0.145069,-0.129139,-0.640800,-0.434039,-0.444059,-0.227618,0.154761,-0.329781,0.600039,0.064876,-0.195516,0.321978,0.036188,0.335292,-0.234349,0.422950,0.038815,-0.157442,0.200576,0.216330,-0.276932,0.304510,0.267162,-0.095217,-0.056016,-0.038805,-0.102417,0.230952,0.824754,-0.249020,-0.279358,-0.398899,0.375341,-0.229349,-0.240112,-0.186803,0.419870,0.345600,0.124618,0.215794,-0.158716,0.108211,0.134140,-0.168353,-0.695172,0.170197,0.098288,0.169787,-0.283270,-0.300093,-0.092152,0.053739,0.375007,-0.359327,0.046684,0.542379,0.319137,0.337819,-0.453503,-0.019340,-0.332470,0.311360,0.459688,-0.132438,-0.181914,0.325792,-0.165818,-0.501536,0.039735,-0.211651,-0.001379,0.077582,0.176221,0.272601,-0.200832,0.338060,-0.595575,0.207115,-0.187780,-0.048846,-0.070138,-0.200973,-0.125436,-0.768250,0.049932,0.025023,-0.248210,0.199506,0.120948,-0.413400,0.612745,-0.645324,0.176082,0.304011,0.412285,-0.272902,0.440400,-0.204166,0.198137,-0.507856,-0.069046,0.079237,-0.456774,0.551155,-0.120510,0.375234,0.107669,-0.251841,-0.498591,0.375464', '2369613', '5403927', '1307897', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26668750', '完美有多美', '喜剧', '《完美有多美》讲述了汽车修理工程天乐（姜武 饰）落魄无助，无意中从一位老者手中获得一把能穿越不同世界的钥匙，这把钥匙可以带他通往有钱有权、与校花卓彦妮（蒋勤勤 饰）拥有美满婚姻的新世界。频繁穿梭于两个世界的程天乐，一边享受A世界家庭的温馨，另一边享受B世界富豪的奢华生活，可是却逐渐对自己所追求的完美生活开始迷茫......', '姜武', '梁栋', 5.5, 3612, 'tt6435124', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2428993870.jpg', 10.3, 27.2, 45.6, 13, 3.8, '0.108693,0.649020,-0.412451,0.412660,-0.378031,0.032542,0.895795,0.099650,-0.544615,-0.015408,0.203243,0.749486,0.050428,0.405316,0.434848,0.288897,-0.047504,-0.632692,0.095085,-0.012240,-0.233446,-0.212000,-0.460291,-0.315993,-0.243277,-0.307104,0.691150,0.307274,-0.294244,0.331008,0.084260,0.161668,-0.600769,0.335864,-0.902242,-0.428352,0.399550,0.376065,-0.626222,0.187484,-0.301542,0.087104,-0.005012,0.213830,-0.210440,-0.328218,0.853181,-0.131507,-0.076700,-0.033418,0.534244,0.506164,-0.395193,-0.144789,-0.059808,0.266540,0.033304,-0.118110,-0.066947,0.097565,0.173497,-0.466580,-0.950276,-0.280093,0.073283,-0.012094,-0.157353,0.395380,0.090327,-0.474461,0.304663,-0.112015,0.288737,0.032519,0.614880,0.765061,-0.194208,0.265720,-0.249696,0.476587,0.188048,-0.016378,-0.323516,0.888925,-0.598516,-0.227350,-0.267368,-0.155820,-0.884251,-0.118906,0.423925,0.259069,0.015902,0.329385,-0.746304,0.438320,-0.208417,-0.152667,0.318377,-0.474278,-0.561461,-0.229952,-0.231726,-0.463345,-0.212584,0.024072,0.015299,-0.322991,0.871827,-0.755291,0.082774,0.144843,0.193359,-0.494021,0.884564,0.131654,0.194198,-0.581153,0.054354,0.527997,-0.131554,0.346671,-0.235804,0.489807,-0.432478,0.144607,-0.485897,0.891923', '1303077', '30279170', '3927750', '30401849');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26670584', '特工次世代', '科幻', '世界观故事发生在时间和地点皆无法判明的超未来。世界由高度发达的网络（软件）和作为其现实载体的超构造体（硬件）所构成。本该是得益于科技繁荣发展的人类却由于一场灾难丧失了连接网络的资格和能力（相当于公民权）。没有了支配者的AI依据管理规定开始排斥失去了网络连接资格的人类。而忘却了曾经的繁荣的人们，只能在管理系统的阴影下苟且偷生。本作的舞台就被设定在这样一个人类日渐衰亡的世界。都市构造体作为舞台的世界就像一个巨大的高楼或者说是连接了所有建筑的巨大都市。大部分为超构造体所遮蔽，形成了阶梯结构。由于建设者的失控，都市构造体正在无止境地扩大之中，就本作故事发生的时间为止至少已抵达木星轨道面。根据统治局描述，正是都市的这样漫无目的地成长从根本上导致了波及全世界的混乱。其结果毋庸置疑的人口密度极度下降。环境就都市构造体所涉及的范畴由于其间散布的纳米机器人的作用保证了生物学上的病毒的排除实现了无菌状态。而这一成果则是由曾经机能正常运转时候的网络球给予统治局的指示所实现的。同一作者的《BIOMEGA》和《DEADHEADS》作品主体中的由于强力病毒引发的传染病在本作中原则上是不可能发生的。从这些设定中可以推断作为网络終端遗传因子的变异原因的“感染”不等同于其字面上的感染，很有可能是由于系统逻辑上的分歧所引起的。故事大纲探索者雾亥流浪在数千层无边无际的巨大阶梯都市之中。手持可以贯穿一切物质的重力子放射线射出装置追寻着网络終端遗传因子。', '樱井孝宏', '濑下宽之', 7.8, 8849, 'tt6574146', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2453080653.jpg', 0.7, 3.1, 27.5, 44.4, 24.3, '0.263306,0.353496,-0.797829,0.695923,-0.196064,0.363411,0.638793,0.067180,-0.367455,-0.128358,0.241157,0.543545,-0.050501,0.026903,0.168897,-0.293424,-0.158973,-0.438071,-0.261362,-0.267388,-0.651622,-0.528766,-0.475957,-0.201174,-0.182002,-0.731322,1.047763,0.216242,-0.771538,-0.301353,-0.090416,0.402024,-0.251989,0.340829,-0.066785,-0.214790,-0.163548,-0.135541,-0.229169,0.198152,-0.295177,-0.116277,0.378275,0.334004,-0.234787,0.160184,0.919157,-0.729214,-0.227625,-0.237786,0.690840,-0.167968,-0.208015,-0.116425,0.463896,0.180190,0.020512,0.331235,-0.120218,0.118335,0.082741,-0.195105,-1.159541,-0.429769,0.253293,0.303039,-0.224016,0.409343,0.085493,-0.476545,-0.264945,-0.200793,0.164535,0.391230,0.427727,0.656684,-0.214440,-0.110978,-0.409406,0.067664,0.495418,0.063673,-1.117377,0.553974,-0.613378,-0.543970,-0.666957,-0.213263,-0.132207,-0.166373,0.092780,0.396827,-0.278841,0.630791,-0.741294,0.386409,-0.192593,-0.572337,-0.005542,-0.299278,-0.075272,-0.741382,-0.260698,-0.439529,0.071415,0.014277,0.074280,-0.292265,0.763170,-0.948513,0.100962,0.455324,0.259319,-0.491673,0.597010,0.049010,0.057160,-0.317053,0.078634,0.083143,-0.206101,0.660961,-0.195884,0.296984,0.187931,-0.234008,-0.569906,0.804651', '26759820', '26759819', '26667010', '1292347');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26670686', '数码宝贝大冒险tri. 第2章：决意', '科幻', '奥尔法兽事件过后，随着时间流逝，御台场地区也渐渐复兴著。“回到日本之后，我就决定一定要去大大的澡堂泡澡！”因为美美这句话，加上为了欢迎新加入的伙伴芽心和缅因猫兽，大家前往附近的温泉主题公园。虽然度过了一段开心的时光，但是这儿并没有阿丈的身影。面对高考临近的事实，他在高考和“被选召的孩子们”的使命之间产生了烦恼。“为什么又必须是我们去面对啊？”这个时候，在御台场再度出现了感染的数码宝贝、这是拥有着高傲灵魂的奥加兽。而看着电视中奥加兽的暴走，美美和巴鲁兽决定出击。“必须要让人们知道，也有好的数码宝贝！”然而，美美和巴鲁兽无视光子郎而参与的战斗，却造成了意想不到的结果。各自怀揣烦恼的阿丈与美美。在月岛综合高中文化祭当天，一个男人出现在了他们面前。如今，冒险再度进化……', '花江夏树', '元永庆太郎', 6.9, 5153, 'tt5216534', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2437663318.jpg', 3.2, 10.1, 43.1, 26.9, 16.7, '0.147007,0.043545,-0.731557,0.420374,-0.068736,-0.153064,0.725929,0.080317,-0.348349,-0.197181,0.062689,0.726205,-0.106533,0.366462,0.297565,-0.278551,-0.172201,-0.555844,0.034026,-0.236243,-0.350738,-0.335092,-0.019426,0.040228,0.048664,-0.410822,0.599316,0.036440,-0.079452,0.612265,0.250601,0.213616,-0.110534,0.783346,-0.022079,-0.096342,0.035379,0.092367,-0.066688,0.322361,0.250975,-0.102122,-0.157932,0.268612,0.145142,-0.020505,0.857892,-0.687645,-0.416579,-0.131411,0.150280,-0.504616,-0.120162,0.218700,0.416673,0.009719,0.220446,0.145265,-0.109022,0.024428,-0.053895,-0.011966,-0.665418,0.114136,-0.075293,0.051191,-0.604866,0.509711,0.247160,-0.052954,0.481391,-0.342662,0.282545,0.806599,0.377726,0.537980,-0.261056,0.087579,-0.438954,-0.086942,0.883983,-0.020638,-0.205550,0.282981,-0.033856,-0.428369,-0.125682,-0.165526,-0.231880,-0.052297,0.169711,0.378349,-0.366581,0.301708,-0.584284,0.152421,-0.159948,-0.635988,0.082490,-0.445037,-0.118183,-0.452434,0.058576,-0.197037,-0.207077,0.271905,0.064275,-0.169410,0.882391,-1.133079,0.395990,0.539356,0.641255,-0.543547,0.623980,0.068422,0.164640,-0.144218,0.034722,-0.048305,0.032881,0.555901,0.159376,0.416655,0.115639,-0.024122,-0.632252,0.654927', '1292219', '35030151', '21360412', '3044878');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26671361', '喜丧', '剧情', '鲁南张庄，86岁老人林郭氏，身体硬朗，在农村老宅独自生活。林郭氏突发脑血栓，身体状况逐渐恶化。子女积极为老人操作敬老院入住事宜。敬老院床位紧张，只有等待敬老院有老人去世，按照老人的意愿，开始了到子女家轮流居住的短暂旅程。这一过程中，林郭氏中风摔倒，脑神经损伤，得了笑病。 敬老院终于有老人亡故，空出床位。却在去敬老院的前夕，林郭氏怀揣着全家福老照片溘然长逝。按照老风俗，儿孙们给她办了一场轰轰烈烈的喜丧。 生活重新开始，又是在重复昨天的故事……', '郁凤云', '张涛', 8.8, 23239, 'tt7162392', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2361586020.jpg', 0.2, 0.9, 9.6, 39.1, 50.2, '-0.214668,0.203713,-0.717950,0.029733,0.039640,-0.477247,0.787080,0.380629,-0.840451,-0.379422,0.255574,0.197878,-0.048304,0.899735,0.193109,-0.397764,-0.320280,-0.149528,-0.270400,0.223597,-0.710814,-0.216621,0.671539,-0.522677,-0.334586,-0.314838,-0.008055,0.049047,-0.016553,-0.055654,-0.049850,0.297827,0.003141,0.104061,-0.382437,0.345791,-0.299132,0.042924,-0.449683,0.055708,0.485824,-0.162147,-0.436240,-0.183052,0.362005,0.388270,0.896061,0.227395,-0.425903,-0.105437,0.540759,0.348320,-0.398834,0.009617,0.815853,0.233977,0.018608,-0.164083,-0.085138,-0.015159,-0.067607,-0.436752,-0.081962,0.012489,0.193321,0.421045,-0.687716,0.352788,0.089255,0.044497,-0.161372,-0.593632,0.318935,0.727773,0.052987,0.507454,-0.146932,0.257248,-0.358409,0.625048,0.631046,0.158384,-0.217095,0.239686,-0.567325,-0.428288,0.303407,-0.191294,-0.304989,-0.078690,0.227171,-0.161356,-0.111642,0.302775,0.077792,-0.003968,-0.022147,-0.387290,0.157794,-0.350374,0.003731,-0.636535,-0.119209,-0.148038,0.074657,0.245315,0.026322,-0.196602,0.542681,-0.443551,0.261004,0.146040,0.113350,-0.276772,0.197717,-0.239729,0.400016,-0.169700,0.264673,0.150401,-0.146418,0.551504,0.262146,0.092997,-0.491278,0.287447,-0.272317,0.459107', '2122766', '1293143', '10508879', '26527937');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26673282', '冷血狂宴', '动画', '为了完成前六度王爵西流尔的遗愿，银尘、麒零、天束幽花等人决定一起前往，解救被白银祭司封印的前一度王爵吉尔伽美什。当克服重重阻碍赶到囚禁之地，却不幸遇上白银祭司派出的最强杀手阵容：幽冥、特蕾娅、漆拉，一场正面交锋在所难免，整个亚斯蓝帝国最阴暗的秘密也将逐渐浮出水面。', '吴亦凡', '郭敬明', 3.8, 46779, 'tt10701926', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2627806003.jpg', 46.5, 27.1, 18.3, 4.8, 3.4, '-0.271106,0.393144,-0.496699,0.644295,0.335077,-0.263797,0.540694,0.048054,-0.276156,-0.450755,0.381717,0.492767,0.180658,-0.315397,0.635318,-0.117557,-0.321105,-0.456175,-0.154213,-0.453418,-0.578520,-0.270382,-0.302754,0.099321,-0.149510,-0.460789,0.998765,0.111261,0.048292,0.198325,0.360574,0.430876,-0.490454,0.236089,0.204758,-0.352344,0.154535,-0.115075,-0.442963,0.491480,-0.405494,-0.162193,0.184217,0.171510,0.019231,0.268904,0.570627,-0.737035,0.446447,-0.349324,-0.279752,-0.602202,-0.271866,-0.087433,0.355494,-0.060719,0.030445,0.577738,-0.013342,-0.243210,-0.106245,-0.267141,-0.630870,0.284920,0.378122,0.056841,-0.125124,0.223418,0.045728,0.427277,0.046599,-0.194659,0.123238,0.450544,0.231882,0.104312,-0.339484,0.038188,-0.254251,-0.207551,0.752019,-0.380198,-0.141395,-0.385526,0.254851,-0.366463,0.139825,-0.314633,0.125284,0.171981,0.150445,0.252889,0.391875,0.724831,-0.664629,-0.407642,-0.686558,-0.102609,0.168357,-0.144996,0.060470,-0.238840,0.122558,0.351427,-0.104527,0.118312,0.095736,-0.296234,0.190421,-0.620728,0.338749,0.358072,0.552764,-0.237025,0.287200,-0.087391,0.530175,-0.106150,-0.094300,0.334140,0.140067,0.728160,0.118812,-0.007307,-0.143675,-0.082290,-0.345158,0.206106', '26759819', '7051375', '3861846', '10480973');
