INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26674021', '爱情冻住了', '喜剧', '在单身家庭长大的都市女性梅宝（林依晨 饰）相信冷冻食品可以安慰许多即使忙碌也希望享受新鲜食物的人，她期待着爱情能像冷藏食品那样永远新鲜。然而，32岁的梅宝竟遭遇事业和爱情的低谷。她决定冷冻卵子，为自己的青春和真命天子，与时间赛跑。因为工作的关系，梅宝结识推崇新鲜、拒绝冷冻的人气主厨阿始（凤小岳 饰）。当“冷冻”的深情遇上“新鲜”的热情，一场关于爱情的浪漫论战就此展开！', '林依晨', '傅天余', 5.3, 3328, 'tt6072662', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2455285837.jpg', 10, 36.7, 37.2, 12.9, 3.2, '0.058799,0.174221,-0.562880,0.242907,-0.038439,-0.079863,0.803211,0.343123,-0.226742,-0.213001,-0.002902,0.415556,-0.098436,0.217631,0.275837,-0.247670,-0.156808,-0.592623,0.084147,0.201593,0.033453,-0.179528,-0.369311,-0.118006,-0.068058,-0.392530,0.568081,0.205420,-0.072280,0.572968,0.252984,-0.144822,0.107518,0.435050,-0.071195,-0.282900,-0.059692,0.429335,-0.807918,0.043665,-0.058571,0.163066,0.180230,-0.014522,0.224971,0.230327,0.596013,-0.040368,-0.549831,0.033332,0.317637,-0.223860,0.158344,0.211744,0.010599,0.188332,0.191974,0.054899,-0.150403,0.216993,-0.056228,-0.164710,-0.832589,-0.304643,0.021977,0.027582,-0.358812,0.650406,0.235172,-0.096922,0.161716,-0.045779,0.168619,0.201130,0.553595,0.701258,-0.078563,0.299958,-0.365330,0.529690,0.780541,-0.100272,-0.388343,0.648291,-0.613906,-0.238970,0.173345,-0.348031,-0.686890,0.034127,-0.018400,0.368746,-0.170095,0.468539,-0.769495,0.181560,0.153530,0.052431,0.448691,-0.489590,0.001512,-0.507182,-0.062328,-0.596140,-0.372416,0.005414,0.208007,-0.520577,0.868104,-0.548495,0.200888,0.437275,0.322734,-0.655783,0.604744,0.288118,-0.110467,-0.305582,-0.146522,0.708514,-0.327795,-0.312652,-0.048575,0.256179,0.068131,0.095761,-0.580058,0.214170', '1308424', '4181031', '26678784', '1303173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26675512', '恋妻家宫本', '剧情', '本片根据家族小说的拿手作家重松清的作品《家庭餐厅》来做改编，聚焦了一对孩子已经独立生活只剩下两人的50岁中年夫妇，他们该如何适应这样的生活而引发幽默又温情的故事。面临中年离婚危机的中学老师宫本阳平（阿部宽饰）苦恼的同时，通过中学学生和料理教室的伙伴们的关系再度认识家庭，与妻子美代子（天海佑希饰）踏出新的一步。', '阿部宽', '游川和彦', 7.3, 7942, 'tt5240878', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2416230805.jpg', 0.4, 3.4, 38.8, 43.4, 14, '0.372740,-0.385389,-0.140981,0.406953,0.033605,-0.219823,0.437024,0.418593,-0.193976,-0.358050,0.328994,0.739322,-0.022116,0.449185,0.259895,-0.133164,-0.225043,-0.803772,0.060361,-0.006863,0.051922,-0.335978,0.052848,-0.182384,0.018663,-0.287804,0.731257,-0.033616,0.033941,0.552200,0.111747,0.269176,-0.262749,0.045947,0.036879,0.105292,0.118569,0.234841,-0.645748,-0.014565,-0.175750,0.050360,-0.202243,-0.009546,0.059515,0.191927,0.833868,0.117019,-0.180231,-0.130353,0.719441,0.008141,-0.264311,0.135890,0.570395,0.102278,0.339882,0.129807,0.006445,-0.130777,-0.191412,-0.136730,-0.735729,0.032241,0.323191,0.070459,-0.432693,0.325190,0.183512,-0.284234,0.458184,-0.042148,-0.051539,0.511778,0.554094,0.683169,-0.288404,0.263219,-0.050656,0.293637,0.664408,-0.054644,-0.317434,0.514050,-0.318950,-0.462463,-0.265607,-0.214413,-0.498025,0.004889,-0.025439,0.077659,-0.071568,0.126665,-0.416917,-0.013886,0.016797,-0.116514,0.515319,-0.663871,-0.106738,-0.702599,-0.242324,-0.271464,-0.322775,0.026419,0.092765,-0.255502,1.017566,-0.540473,-0.219203,0.277546,0.306030,-0.532967,0.644565,-0.014255,0.112837,-0.386064,-0.137097,0.222922,-0.113122,0.052816,-0.066047,0.308782,-0.118030,0.117999,-0.386541,0.173799', '3811356', '27602116', '5403927', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26676350', '我的叔叔', '喜剧', '松田龙平饰演的叔叔是一个性格古怪的兼职哲学讲师，整日无所事事躺在哥哥家里看漫画。喜欢强词夺理，也偶尔语出惊人。一旦对什么事着迷，就会展现出非人的能量与干劲。故事以侄子雪男（大西利空饰）视角展开，雪男本对这位叔叔毫无好感，但一次偶然让叔叔遇到了一见钟情的女神（真木阳子饰），女神要返回夏威夷接管祖母留下的咖啡庄园，叔侄二人于是向夏威夷出发，踏上了追寻女神之旅。影片改编自北杜夫1972年的同名儿童文学。', '松田龙平', '山下敦弘', 7.1, 17072, 'tt5242898', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2365584691.jpg', 0.5, 4.3, 46, 39.2, 10, '0.163348,-0.242585,-0.307152,0.641308,0.163997,-0.325520,0.410225,0.246011,-0.544514,-0.412011,0.080587,0.650786,-0.163097,0.303942,0.394819,0.231629,-0.416868,-0.408965,-0.042300,0.070449,-0.127455,-0.395525,0.064953,-0.125007,0.077786,-0.563082,0.397444,-0.174825,-0.302917,0.662204,0.295843,0.199514,-0.288465,0.221525,-0.142134,-0.152651,-0.170154,0.346079,-0.491178,0.420612,0.197672,0.065279,-0.197572,-0.085572,0.126179,-0.016202,0.678407,-0.228044,-0.525146,-0.150918,0.431307,-0.304270,0.083421,0.076848,0.243823,-0.027933,0.260987,0.157399,0.068671,-0.174165,-0.146728,-0.209894,-0.204003,0.066274,0.097522,0.110314,-0.351307,0.449441,0.090597,-0.230717,0.235932,-0.453488,-0.011112,0.044039,0.333669,0.331546,-0.065478,0.265078,-0.199778,-0.045196,0.559010,0.158795,0.059153,0.638340,0.273926,-0.036886,-0.117454,-0.102956,-0.481941,0.346769,-0.141470,-0.101764,0.059445,0.148454,-0.696097,-0.043946,-0.008371,-0.052198,0.252323,-0.342802,-0.042959,-0.301100,-0.084182,-0.298648,0.026715,0.099374,0.281507,-0.206285,0.822056,-0.802725,0.278743,0.360118,0.256104,-0.726883,0.746816,0.170680,-0.474058,-0.436352,0.152300,0.083234,0.097426,-0.049211,-0.150109,0.273845,0.101533,-0.258342,-0.140793,0.141206', '3445516', '6963575', '25922902', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26677495', '帕特森', '剧情', '帕特森（亚当·德赖弗 Adam Driver 饰）居住在新泽西州帕特森市，这个和故乡有着相同名字的男人是一名巴士司机，和女友劳拉（歌什菲·法拉哈尼 Golshifteh Farahani 饰）以及一只牛头犬一起过着平淡的同居生活，每天开着巴士重复着相同的路线和波澜不惊的人生。帕特森喜欢写诗，他随身携带着一本笔记本，把脑海中跃动的诗句记录在本子上，但从来都没有想过将自己的诗句出版成册，他的唯一读者只有劳拉。和帕特森截然相反，劳拉是一位天生的艺术家，每天脑袋里都闪现着五花八门的古怪念头，她在窗帘、墙壁甚至自己的衣服上画各种黑白图腾、学吉他、做美味的杯子蛋糕，乐观开朗的她全心全意的热爱着生活。终于，帕特森答应劳拉将自己的作品印刷成册，他的生活是否会因此发生改变呢？©豆瓣', '亚当·德赖弗', '吉姆·贾木许', 8.1, 50733, 'tt5247022', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2385215679.jpg', 0.6, 2.5, 18.8, 48.2, 30, '0.539509,-0.045935,-0.588259,0.908932,-0.038367,0.076459,0.940221,0.206487,-0.282258,-0.236882,0.150249,0.829895,0.049201,0.387424,0.116230,0.086527,-0.333347,-0.785674,0.085255,0.066361,-0.313788,-0.522459,-0.251203,-0.231380,-0.047072,-0.266607,0.407810,-0.155414,0.027127,0.458878,0.130003,-0.122367,-0.119229,0.322254,-0.392387,0.047409,-0.155866,0.116449,0.133997,-0.065060,0.191397,-0.095625,-0.197726,0.145491,0.079465,0.200018,0.771316,-0.260852,-0.196747,0.277867,0.336468,0.144620,-0.066064,0.084455,0.026244,0.342416,0.099791,0.086694,-0.051694,0.121973,0.111339,-0.211612,-0.708426,-0.333764,-0.161641,0.363548,-0.785927,0.507335,-0.317370,-0.047849,0.054272,-0.470292,0.270377,-0.025033,0.285413,0.311485,-0.104812,0.116006,-0.587746,0.512508,0.171065,0.251766,-0.230219,0.271832,-0.559698,-0.163795,-0.287773,-0.020939,-0.764211,-0.095709,0.047756,-0.077860,-0.225211,0.052406,-0.719300,0.244320,0.136303,-0.281503,0.149254,-0.382039,-0.341095,-0.517090,0.025154,-0.493090,-0.314834,-0.130298,-0.089633,-0.309639,0.911062,-0.690253,0.283160,0.368744,0.121458,-0.088628,0.832349,0.076647,-0.009574,-0.022807,-0.237278,0.382310,0.184981,0.159585,-0.022200,0.587837,0.308719,0.212721,-0.404776,0.866683', '1307146', '30162520', '26348103', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26677981', '夏天19岁的肖像', '爱情', '19岁少年康乔（黄子韬 饰）遭遇交通意外后，在医院休养时偷窥到了对面别墅的美丽少女夏颖颖（杨采钰 饰）。他偶然目睹了少女“弑父”的过程，却无法抑制自己对她的迷恋，一段矛盾而又惊险的恋爱故事在夏天上演。充满悬念和纠结的情节发生在19岁的夏天，只有在那样的年纪可以这样奋不顾身，这样无惧真相的为爱恋的人付出一切。', '黄子韬', '张荣吉', 4.8, 9984, 'tt5801026', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2460008994.jpg', 24, 33, 27.2, 12.4, 3.4, '0.161453,0.124254,-0.882658,0.152765,-0.197323,-0.114254,1.382027,0.137776,-0.577839,-0.095058,0.517037,0.486041,-0.454484,0.224008,0.221692,-0.228787,-0.078131,-0.701408,0.037926,-0.106949,-0.321321,-0.320603,-0.156679,-0.341555,0.035864,-0.504085,0.720495,0.381029,-0.292021,0.408689,0.273127,0.207546,0.088315,0.968340,-0.380939,0.005855,0.064476,0.567333,-0.109585,0.028151,0.108932,-0.493808,-0.359300,0.263450,-0.407454,0.193431,1.109642,-0.080329,-0.588037,0.245840,0.477126,-0.189435,-0.144898,0.136616,0.270707,-0.320456,0.085645,-0.229082,-0.060096,-0.536448,0.054259,0.016047,-0.637733,-0.128572,0.176202,0.449969,-0.678535,0.704716,-0.179033,0.222650,0.406979,-0.348118,-0.181651,0.385299,0.529756,0.379455,-0.280585,-0.137361,-0.503756,0.446433,0.821736,0.036451,-0.372035,0.765517,-0.507172,-0.474469,-0.371690,-0.288172,-0.730720,0.221144,0.285187,-0.230643,-0.483268,0.297167,-0.223442,-0.323431,0.040331,-0.037717,-0.199330,-0.623188,-0.376261,-0.292898,-0.286997,-0.559924,-0.486104,0.022238,0.158790,-0.398713,0.538695,-0.887052,0.313157,0.580257,0.110144,-0.287900,0.807458,0.184757,-0.127559,-0.287056,-0.107858,0.589739,-0.332459,0.113262,-0.122915,0.694003,-0.087206,0.268221,-0.876412,0.529568', '21348112', '21619567', '2377539', '1307561');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26678509', '希望的另一面', '剧情', '一个叫做哈立德的年轻叙利亚难民几乎失去了所有的家人。近乎偶然之下，他藏在一艘运煤船里流落到赫尔辛基成了一个偷渡客，并在当地寻求政治庇护。维克斯特伦是一个旅行推销员，他在牌桌上赢了一大笔钱之后在赫尔辛基的一条后街买了一家不赚钱的餐馆。在当地政府作出要将哈立德遣返回阿勒颇的判决后，他决定非法留在这个国家。最终，维克斯特伦发现哈立德睡在他餐馆的内院里，并聘请他到自己餐馆里做清洁工和洗碗工。生活会短暂地向我们展示它光明的一面，然而命运很快就会插手其中。', '韦勒·维坦恩', '阿基·考里斯马基', 7.9, 15843, 'tt5222918', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2409401871.jpg', 0.4, 1.5, 21.3, 57.5, 19.2, '0.452356,0.224532,-0.784973,0.506762,-0.347449,-0.258587,0.729676,0.196857,-0.461298,-0.048062,0.281323,1.190638,0.175407,0.190599,0.344883,0.221837,-0.385536,-0.628490,0.006373,-0.308673,-0.345173,-0.461254,-0.261242,-0.441412,-0.284159,0.031092,0.308559,0.130637,-0.089443,0.197367,0.097224,0.056400,0.062117,0.532538,-0.335374,0.055151,0.170549,-0.239635,-0.090890,0.605581,-0.042101,-0.417777,-0.100853,0.132603,0.228965,0.410123,0.558346,-0.154961,-0.067077,-0.021953,0.100012,-0.222037,-0.149811,0.124352,0.184907,-0.132368,0.030168,0.111004,-0.658903,0.253435,0.240620,0.009003,-0.607420,-0.335624,-0.169766,0.206297,-0.816306,0.520837,0.155495,-0.073119,0.002029,-0.618841,0.265665,0.392292,-0.102335,0.224963,0.042084,-0.008963,-0.883965,0.253752,0.730491,-0.296938,-0.210071,0.248605,0.016654,-0.297590,0.122224,-0.198319,-0.415643,-0.320680,0.438057,0.006644,-0.240455,-0.090210,-0.715159,0.093776,-0.304799,-0.530933,0.086661,-0.235261,-0.063391,-0.696442,-0.033625,-0.273809,-0.283811,0.208254,0.043178,-0.079999,0.489514,-0.830986,0.141168,0.588230,0.318372,-0.483394,0.637721,0.008785,0.457058,0.091521,0.141333,0.032982,0.191481,0.754595,0.065870,0.314044,0.154726,-0.092569,-0.369065,0.387125', '1309069', '3430271', '1291574', '3285642');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26678784', '夺金四贱客', '喜剧', '三个不同背景、性格迥异的男人为了各自毕生的梦想和美好的未来，多年辛苦存钱，他们拥有一个共同的神经质投资顾问。不幸的是，三人账户惨遭清零，投资顾问也因被嫁祸而遭到解雇。四个大男人一同陷入了绝望境地，为此他们结为同盟，实施了一个疯狂的计划…', '蒂尔·施威格', '沃尔夫冈·彼德森', 6.5, 10396, 'tt5173166', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2506043017.jpg', 0.7, 9.1, 57.8, 27.5, 4.9, '0.176336,0.157564,-0.568382,0.590520,-0.407500,-0.212307,0.587663,0.220979,-0.465587,-0.336211,0.238400,1.160061,0.120199,0.122185,0.249079,-0.222612,0.287285,-0.836768,-0.283269,-0.009807,-0.175167,-0.700096,0.009987,-0.474932,-0.167499,-0.318912,0.705441,0.080548,-0.195458,0.495527,0.441368,0.317863,-0.427315,0.096152,0.127529,-0.124691,0.467617,-0.000273,-0.613327,0.217476,-0.325597,-0.022213,0.123415,0.088766,-0.335552,0.309661,0.919005,0.146392,-0.445289,-0.361723,0.490116,-0.288011,-0.436988,0.289097,0.357199,0.132860,0.091745,0.393393,-0.456664,-0.262127,0.211466,-0.140134,-1.716654,-0.014025,0.316468,-0.270011,-0.584489,0.729618,0.112379,-0.182012,0.074181,-0.207595,-0.036215,0.718187,0.763892,0.576575,-0.151519,0.070973,-0.236140,0.118667,1.141638,-0.092252,-0.189025,0.202032,-0.303011,-0.054508,0.048834,-0.399741,-0.441268,-0.060034,0.418925,-0.157107,-0.170982,0.484784,-0.789418,0.345898,-0.405616,-0.314617,0.011370,-0.696394,-0.043269,-0.322385,-0.405625,-0.342711,-0.382828,0.362764,0.098041,-0.174489,1.093934,-0.671473,0.056581,0.635906,0.449426,-1.258257,0.741965,0.297265,0.190896,-0.472567,0.086653,0.106474,0.095634,-0.064985,0.332920,-0.211461,-0.332629,0.340029,-0.330612,0.252891', '30163500', '35096844', '1304382', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26680247', '最爽的一天', '剧情', '名不见经传的钢琴家安迪（马提亚斯·施维赫夫 Matthias Schweighöfer 饰）和从未干过什么正经事整天游手好闲的本诺（弗洛里安·大卫·菲茨 Florian David Fitz 饰），这两个个性迥异似乎永远都不会有交集的人，相识于病房之中，两人都患上了无法治愈的绝症，时日无多。在本诺的怂恿之下，安迪决定和他一起逃出病房，来一趟充满了阳光和激情的非洲之旅，他们要尽情享受轰轰烈烈毫无顾忌的人生，才能甘心接收死亡的终结。就这样，两个“亡命之徒”踏上了他们的旅途，一路上，疯狂的两人制造了数不清的麻烦和笑料，而他们糟糕的健康状况，亦令两人屡屡同死神擦肩而过。最终，当他们抵达了目的地时，又会有怎样的一番景象在等待着两人呢？©豆瓣', '马提亚斯·施维赫夫', '弗洛里安·大卫·菲茨', 7.8, 37315, 'tt5154896', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2396328652.jpg', 0.3, 2.1, 26.6, 48.7, 22.3, '0.409882,-0.111560,-0.761161,0.450732,0.014805,-0.361171,0.708186,0.129099,-0.550951,-0.110709,0.059815,0.861665,-0.400712,0.257170,0.314765,-0.219974,-0.354358,-0.765009,-0.059345,-0.167694,-0.386547,-0.499728,-0.220795,-0.289557,0.060582,-0.152726,0.309429,0.173616,0.004747,0.658741,0.337706,0.159874,-0.291127,0.561720,-0.299636,-0.054361,0.121738,0.294540,-0.420796,0.127696,0.141238,-0.125642,-0.221957,0.144086,0.021703,0.089059,0.763872,-0.294413,-0.051605,0.125374,0.162817,-0.171666,0.100443,0.266579,0.102890,-0.248361,0.214281,0.253794,-0.084920,0.000296,0.061903,0.134383,-0.819235,-0.030961,0.040187,0.083648,-0.448890,0.463396,0.354345,-0.122321,0.173769,-0.153615,0.252300,0.555431,0.313107,0.361657,-0.057835,-0.301251,-0.511357,0.262233,0.939420,0.027899,-0.297695,0.330380,-0.323349,-0.251615,-0.273618,-0.355910,-0.703584,-0.164726,0.342078,0.152837,-0.326280,0.306177,-0.580337,0.077776,-0.214456,-0.109958,-0.172516,-0.346467,0.122669,-0.669298,-0.087160,-0.559720,-0.435926,0.463074,-0.162701,-0.027866,0.497552,-0.656451,0.328824,0.535980,0.159409,-0.435381,0.741399,0.169586,0.054049,-0.142334,0.030482,0.184640,0.074526,0.318326,0.396480,0.401874,-0.092054,0.317837,-0.403984,0.414095', '30162520', '26687241', '11541282', '4604803');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26680558', '一拳超人：英雄之路', '喜剧', '故事发生在琦玉老师头发还没有掉光的时候，这一天身穿蓝色运动服的他在追捕偷东西的箭毒蛙怪人，谁知期间不慎刮坏了自己的裤子。万般无奈，在打败箭毒蛙之后，他带着破损的衣服求助于相识的和服店老板。老板见他反反复复穿着同一套运动服，所以热心地向他推荐极具视觉冲击力的和服礼服套装。琦玉绞尽脑汁，总算推脱掉了。与此同时，残存于衰败商业街的和服店正面临不法分子蚕食的危险。从老板口中，琦玉得知这群不法之徒的存在，更惊讶地发现自己居然和他们住在同一座公寓中……本片根据ONE、村田雄介的同名漫画改编，是同系列TV动画版的OAD动画。©豆瓣', '古川慎', '山冈实', 8.2, 6802, 'tt5254328', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2572282719.jpg', 0.3, 1.3, 19.1, 45.9, 33.3, '0.186759,-0.009674,-0.467652,0.384888,-0.013511,-0.019715,0.494324,0.196167,-0.197116,-0.553169,0.439817,0.523915,-0.305008,-0.174226,0.252314,0.006538,-0.292161,-0.666563,-0.007722,0.086960,-0.579146,0.057597,-0.292288,0.131001,0.066511,-0.501116,0.582218,0.267769,-0.538525,0.528627,0.504486,0.447935,-0.308924,0.293665,-0.373379,-0.071009,-0.061234,0.189621,0.222126,0.186448,0.054178,-0.341589,0.145569,0.216674,-0.020936,0.393669,0.891119,-0.417168,-0.119933,0.273111,0.476846,0.026375,-0.166747,-0.051730,0.416900,0.053770,0.188835,0.060847,-0.129799,0.128385,0.302594,-0.021331,-0.557763,0.027990,0.172115,0.389032,-0.525447,0.567098,-0.238909,0.096664,0.128335,-0.501054,-0.054120,0.122372,0.077805,0.361955,0.069031,0.118582,-0.829321,0.369373,0.251965,0.127748,0.079948,0.376622,-0.351236,-0.003947,-0.144404,0.033741,-0.233937,-0.097445,0.411855,-0.065561,-0.284416,-0.162827,-0.977202,-0.174909,-0.111990,-0.278286,0.195794,-0.082161,-0.470200,-0.375054,-0.156962,-0.467015,0.085950,0.014495,-0.077813,-0.123457,0.427123,-0.562091,-0.002066,0.196713,0.223153,-0.234806,0.618696,-0.264994,0.216746,0.060537,-0.338163,-0.017701,0.167165,0.180182,0.385735,0.655989,0.042320,-0.326574,-0.624010,0.036129', '26290398', '1394470', '6877520', '1293531');
