INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26681656', '冰雪大作战', '喜剧', '本片故事取材于1984年加拿大家喻户晓的经典电影《La Guerre des Tuques（阻止战争的狗）》，本片在30年前上映时曾轰动一时，在全球超过125个国家上映，获得18种全球奖项。《冰雪大作战》还是首部引入中国的加拿大动画片，同时也是2015年加拿大本土制作的 电影票房冠军。电影讲述一群生活在加拿大小镇的孩子，在寒假来临时，为了打发无聊的时间，小男孩卢克和刚到搬到镇子上的小女孩索菲亚成为对立两派的首领，约定了一场超大规模的雪仗。雪仗的规模在两方孩子们的挑衅、误会等碰撞中不断升级，进而演变成雪堡保卫战，最后导致了意想不到的事故发生。这个事故最终停止了孩子们的战争，并让孩子们认识到了自己的错误，找到了游戏的真谛，即友情和快乐才是游戏的目的，于是，所有的孩子都在这个过程中醒悟并得到了成长。', '安吉拉·嘉鲁皮', '让-弗朗索瓦·波略特', 6, 2772, 'tt5143700', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2443765210.jpg', 6, 18.9, 49.8, 19.4, 6, '-0.016112,0.049950,-0.821230,0.337936,0.120865,-0.087416,0.563407,-0.202765,-0.412638,-0.103774,0.209610,0.777390,-0.479956,0.130080,0.297738,-0.293709,-0.215808,-0.673146,-0.189263,-0.195800,-0.392168,-0.282517,-0.268952,-0.228034,-0.097292,-0.290734,0.675326,0.153146,-0.403518,0.374899,0.305058,0.005451,-0.188950,0.380986,-0.267504,0.141455,0.038355,0.110881,-0.352738,0.332638,-0.264186,-0.263841,-0.389309,-0.072278,0.173766,0.175891,1.000326,-0.320928,-0.049068,0.027486,0.445258,-0.454535,-0.360513,-0.154571,0.509298,0.017200,0.277666,0.181258,-0.033083,0.178608,-0.191617,-0.312844,-0.767666,0.110895,-0.025734,0.092725,-0.572800,0.610767,0.255459,-0.141278,0.093411,-0.323949,0.255096,0.636257,0.294383,0.511948,-0.312756,0.044127,-0.543860,0.389928,0.833407,-0.237459,-0.341730,0.489729,0.000640,-0.513357,-0.341480,-0.414692,-0.333944,0.169608,0.317789,-0.150115,-0.337383,0.431266,-0.782997,0.021578,-0.148904,-0.744955,0.299442,-0.389908,0.013008,-0.806814,-0.180262,-0.263943,-0.253630,0.094028,0.113655,-0.197214,0.989119,-0.757450,0.278560,0.758352,0.194497,-0.589511,0.553395,0.174925,0.229282,-0.259275,0.011759,0.172874,-0.169512,0.299776,0.014165,0.241432,-0.056685,-0.198151,-0.434871,0.582311', '3811356', '25928048', '5403927', '24733428')