INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26682565', '在西伯利亚森林中', '冒险', 'Pour assouvir un besoin de liberté, Teddy décide de partir loin du bruit du monde, et s’installe seul dans une cabane, sur les rives gelées du lac Baïkal.Une nuit, perdu dans le blizzard, il est secouru par Aleksei, un Russe en cavale qui vit caché dans la forêt sibérienne depuis des années.Entre ces deux hommes que tout oppose, l’amitié va naître aussi soudaine qu’essentielle.', '拉斐尔·佩尔索纳', '萨菲·奈布', 8.6, 6995, 'tt4643432', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2358629857.jpg', 0.1, 0.8, 11.7, 46.1, 41.4, '0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000', '10001432', '10047547', '10174444', '10342838');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26682875', '贞子大战伽椰子', '恐怖', '女大学生为了帮父母准备结婚纪念日的礼物，女大学生上野夏美（佐津川爱美 饰）拜托好友仓桥有里（山本美月 饰）帮忙将结婚录影带刻录成DVD光盘。谁知在购买中古录像机的过程中，她们却意外入手了传说中的诅咒录影带。看过录像后，夏美遭到贞子的诅咒。二人连忙求助于专门研究都市传说的教授森繁（甲本雅裕 饰），然而事态朝着意想不到的方向发展。与此同时，高木铃花（玉城蒂娜 饰）随父母搬到了佐伯家的对面。小学生失踪事件让铃花十分在意，她因此成为伽椰子和俊雄的猎物。为了解除两大女鬼的诅咒，异端法师常盘经藏（安藤政信 饰）决定让贞子和伽椰子来一场史无前例的恶鬼大对决……©豆瓣', '山本美月', '白石晃士', 4.7, 8015, 'tt5309954', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2321834530.jpg', 21.8, 38.4, 29.1, 6.8, 3.9, '0.264364,-0.202099,-0.206921,0.082366,0.096547,-0.038970,0.391353,0.050015,-0.310081,-0.561953,0.067247,0.511205,-0.089019,0.031538,0.264992,-0.000117,-0.468287,-0.435383,-0.032044,-0.160620,-0.268554,-0.342457,0.073868,0.056157,0.032564,-0.219839,0.525670,-0.115729,-0.211414,0.453180,0.209577,0.574601,-0.457050,-0.008068,0.125330,-0.006921,0.268348,0.121375,-0.278770,0.535243,-0.221629,-0.053037,0.020669,0.295576,0.167097,0.123455,0.577648,-0.315867,0.068734,-0.232389,0.311335,0.013937,-0.168080,0.231760,0.268461,0.195485,0.240376,0.042712,-0.156773,-0.194944,0.273900,-0.332348,-0.462154,0.148756,0.246428,0.207475,-0.348502,0.206525,-0.033733,0.097574,0.367798,-0.279408,0.270529,0.099008,0.588331,0.210674,-0.229747,0.061593,-0.101506,0.178646,0.314036,-0.051268,0.196980,0.245038,0.043019,-0.325260,-0.071783,0.011722,-0.349076,0.182314,0.244516,0.189614,-0.130361,0.248914,-0.542889,-0.357768,-0.160254,0.010911,0.172734,-0.085036,-0.166528,-0.656978,0.086225,0.067206,-0.088786,-0.055014,0.237877,-0.245137,0.687259,-0.500155,0.324647,0.400425,0.350158,-0.205977,0.323361,-0.135449,0.001677,-0.458906,-0.186463,-0.037317,0.235633,0.334927,0.035835,0.042225,0.014937,-0.454689,-0.306717,0.048533', '2369613', '5403927', '3811356', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26682880', '过境', '剧情', '德国军队就在巴黎城外。格奥尔在最后一刻逃到了马赛。他的行李中带着一个叫Weidel的作家的遗产，这个作害怕遭受迫害而选择了自尽。这些遗产中有一份手稿，一些信件，和墨西哥大使馆对签证的一份担保。只有这些才能证明他们已被允许从这座港口城市离开，离开这里意味着还需要一份来自潜在东道国的入境许可。以Weidel的假身份，格奥尔试图获取船上的一些稀缺通道。难民之间的会谈在他小旅馆的走廊上，领事馆的等候室里，以及港口边上的咖啡厅和酒吧中进行着。格奥尔帮忙照顾着他已逝战友海因茨的儿子，海因茨在逃亡时不幸过世。但他的计划在遇见那个神秘姑娘玛丽时改变了。《过境》基于德国女作家安娜·西格斯撰写的二战同名小说改编，电影以现代马赛为背景，来自过去的人们在这里四处出现。因此，过去的难民会与今日的难民相遇，历史与今生相遇，他们所有的故事融合在一起构成一个永恒的过境空间。', '弗兰茨·罗戈夫斯基', '克里斯蒂安·佩措尔德', 7.4, 5560, 'tt6675244', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2512965888.jpg', 0.9, 4.3, 33.3, 46.2, 15.2, '0.432852,0.197619,-0.783956,0.722342,0.096473,-0.211717,0.790975,0.037536,-0.476746,-0.176980,0.195360,1.077931,0.144973,0.216670,0.220069,-0.016666,-0.569133,-0.570749,-0.262481,-0.395343,-0.453549,-0.608102,-0.231763,-0.107962,-0.272047,-0.307700,0.557721,0.278505,-0.183189,0.483944,0.139424,0.179272,-0.347345,0.343615,-0.242492,-0.062559,0.026084,0.007288,-0.466099,0.290213,0.049984,-0.093730,-0.144999,-0.001684,0.078171,0.174373,0.814088,-0.211491,-0.153057,-0.068916,0.538206,-0.125438,0.141015,0.199421,0.300368,0.095575,0.161684,0.198181,-0.368926,0.123509,-0.042554,-0.027044,-0.821986,-0.266864,-0.034673,0.285853,-0.634198,0.340476,-0.081499,-0.042804,0.195507,-0.529632,0.438311,0.564364,0.106624,0.411163,-0.214037,-0.110823,-0.699142,0.111219,0.631341,-0.205077,-0.132690,0.112904,-0.124890,-0.357698,-0.041951,0.021281,-0.567772,-0.015370,0.210039,-0.082230,-0.270975,0.206856,-0.752405,0.043528,-0.193392,-0.408006,0.115275,-0.313662,-0.152313,-0.936410,-0.133458,-0.268458,-0.215555,0.250423,0.198225,-0.077226,0.815655,-0.610673,0.311608,0.763355,0.555108,-0.417486,0.778056,0.096145,0.284419,0.003985,-0.000337,0.304645,0.238267,0.449488,0.007285,0.263201,0.028371,-0.073431,-0.503650,0.354161', '25928048', '30162520', '3055049', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26683290', '你的名字。', '剧情', '在远离大都会的小山村，住着巫女世家出身的高中女孩宫水三叶（上白石萌音 配音）。校园和家庭的原因本就让她充满烦恼，而近一段时间发生的奇怪事件，又让三叶摸不清头脑。不知从何时起，三叶在梦中就会变成一个住在东京的高中男孩。那里有陌生的同学和朋友，有亲切的前辈和繁华的街道，一切都是如此诱人而真实。另一方面，住在东京的高中男孩立花泷（神木隆之介 配音）则总在梦里来到陌生的小山村，以女孩子的身份过着全新的生活。许是受那颗神秘彗星的影响，立花和三叶在梦中交换了身份。他们以他者的角度体验着对方的人生，这期间有愤怒、有欢笑也有暖心。只是两人并不知道，身份交换的背后隐藏着重大而锥心的秘密……本片为2016年度日本本土影片票房冠军。©豆瓣', '神木隆之介', '新海诚', 8.5, 1297180, 'tt5311514', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2395733377.jpg', 0.4, 1.6, 15.9, 38.6, 43.5, '0.250450,-0.028024,-0.618836,0.652900,0.007320,0.145753,0.658891,0.139878,-0.613684,-0.166693,0.314197,0.673321,-0.134777,0.588013,0.396924,0.307523,-0.177819,-0.556620,-0.274527,-0.333900,-0.193766,-0.487899,-0.378500,0.049822,-0.107432,-0.380665,0.781997,0.138654,-0.326434,0.395329,0.328568,0.317929,-0.316014,0.380692,-0.364485,0.013771,-0.022226,0.412207,-0.351371,0.209543,0.012055,-0.356940,-0.254507,0.118729,0.041779,0.302657,0.686646,-0.272698,-0.422597,0.099519,0.457209,-0.043326,-0.161829,-0.112828,0.441030,0.090537,0.223077,0.082949,-0.212467,0.168135,0.067879,-0.164353,-0.552928,0.215736,0.373815,0.426649,-0.542294,0.653573,0.041606,-0.434144,0.345138,-0.323096,0.243368,0.230370,0.339966,0.335916,-0.398136,0.107543,-0.400712,0.135665,0.887499,0.263763,-0.355456,0.270999,-0.574685,-0.483238,-0.216589,-0.189586,-0.531175,0.012605,0.122229,-0.013045,-0.264521,0.262023,-0.399247,0.190983,0.156520,-0.116081,0.192932,-0.403583,-0.318261,-0.400034,-0.173834,-0.554971,-0.310719,-0.051612,0.062993,-0.307851,0.812420,-1.247177,0.213437,0.739661,0.384963,-0.043820,0.619706,0.072395,0.009359,-0.213204,-0.269532,0.157250,-0.142923,0.279990,-0.130645,0.339911,-0.302336,0.084725,-0.469804,0.480156', '35030151', '1292219', '1826173', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26683353', '何者', '剧情', '拓人（佐藤健 饰）在大学时代参加了话剧社团，一心想要在舞台上做出一番建树。然而毕业后，他和大部分应届生一样，放弃了表演，穿上西装打上领带，奔赴在各大公司的面试会场之间。瑞月（有村架纯 饰）和光太郎（菅田将晖 饰）是拓人的同窗兼好友，两人曾是一对恋人后来分手，而如今的拓人依旧默默的爱慕着瑞月。瑞月的肩上背负着赡养家庭的重担，因此在找工作上格外拼命，而光太郎曾是乐队的主唱，过惯了自由散漫的生活的他如今亦加入了求职的队伍之中。巨大的压力，无数的竞争者，稀少的内定名额，眼看着瑞月和光太郎等人一个接着一个的拿到了名额，拓人的内心渐渐产生了微妙的扭曲。©豆瓣', '佐藤健', '三浦大辅', 7.4, 17103, 'tt5264056', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2350582168.jpg', 0.6, 4.2, 35.8, 44.6, 14.8, '0.437429,0.026949,-0.497108,0.416630,0.112204,-0.381496,0.507019,0.443395,-0.523944,-0.066780,0.170376,0.761463,-0.159330,0.455915,0.283515,-0.191138,-0.160666,-0.779738,-0.238635,0.002175,-0.300022,-0.547296,-0.063000,0.197265,-0.186068,-0.322469,0.831815,-0.014714,0.044575,0.861110,0.506267,0.218262,0.216597,0.239631,-0.179424,-0.115980,0.020688,0.220337,-0.073799,0.112780,-0.314785,-0.371678,-0.285767,0.137042,0.062776,0.454184,0.752601,-0.065633,-0.000705,-0.170470,0.359694,-0.164758,-0.308369,0.238259,0.382438,0.368279,0.169588,0.323290,-0.203438,-0.077971,0.250765,-0.226612,-0.605699,-0.006476,0.179832,0.387814,-0.654701,0.725564,-0.009806,-0.187995,0.092924,-0.287647,0.101262,0.318164,-0.030131,0.297261,-0.327720,0.149206,-0.198078,0.527861,0.801801,0.152875,-0.058344,0.194463,-0.271248,-0.142045,-0.349654,-0.152466,-0.416680,-0.372508,0.230878,-0.062220,-0.063318,-0.127300,-0.653523,0.143389,0.061770,-0.121841,0.141287,-0.512582,-0.055964,-0.638160,-0.123245,-0.623947,-0.444590,0.242822,0.139631,-0.176297,0.778784,-0.932562,0.004068,0.365222,0.240970,-0.041113,0.697832,-0.051257,0.042598,-0.034106,-0.057066,-0.202006,-0.111222,0.234934,0.158808,0.581306,-0.193095,-0.054759,-0.324282,0.446831', '35030151', '1826173', '26365262', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26683354', '精灵宝可梦：波尔凯尼恩与机巧的玛机雅娜', '动画', '小智和皮卡丘等一行伙伴在旅途中前行。某日，宝可梦波尔凯尼恩从天而降并被迫与小智锁在了一起。波尔凯尼恩与被人类伤害过的宝可梦们共同生活，因此非常讨厌人类，但这条神奇的锁链却让他们无法分开，奇妙的故事就此开始。小智与皮卡丘又将一起开始新的冒险…… 另一方面，在超级机关城市阿佐特王国，大臣贾维斯得到了常年追求的终极发明——500 年前诞生于阿佐特王国的人造宝可梦玛机雅娜。据说在玛机雅娜体内，有被称为 “魂心”的未知力量，贪婪又邪恶的贾维斯企图利用这股力量来统治王国。小智和波尔凯尼恩将会如何化解彼此的嫌隙？波尔凯尼恩与玛机雅娜又有着怎样的渊源？他们要如何共同对抗贾维斯拯救阿佐特王国？玛机雅娜的最终命运又将如何结局？一场精灵宝可梦史上最伟大的战役即将展开！©豆瓣', '松本梨香', '汤山邦彦', 6.1, 6290, 'tt5889204', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2503056709.jpg', 2.5, 21.8, 49.8, 19.1, 6.9, '0.249591,0.286764,-0.568924,0.752353,0.098849,-0.327154,0.596874,0.030982,-0.550735,-0.109237,0.038514,0.828883,-0.102739,0.109747,0.227471,0.022255,-0.381241,-0.433326,0.163496,0.021809,-0.400183,-0.602352,-0.380722,-0.134977,-0.094273,-0.519979,0.720310,0.057688,-0.162981,0.229131,0.315993,0.607818,-0.359876,0.543772,-0.039939,-0.091419,0.185538,0.002819,-0.539666,0.018490,0.008294,0.012605,-0.107372,0.336371,0.041357,0.010846,0.523544,-0.809816,0.327847,-0.382490,0.273268,-0.281807,0.175632,0.118061,0.296579,-0.041274,0.222628,0.187592,-0.029174,-0.157178,0.155991,-0.056413,-0.900209,-0.064870,0.350978,0.014619,-0.558867,0.239849,0.076248,-0.284696,0.131424,-0.323190,0.046452,0.842936,0.609694,0.358963,-0.154097,-0.173628,-0.414343,-0.361233,0.875669,-0.054709,-0.442515,0.066333,-0.185870,-0.562241,-0.281379,-0.304046,-0.377104,-0.231041,0.489996,0.359748,-0.027770,0.690505,-1.169137,0.081514,-0.418085,-0.107759,0.188776,-0.695333,0.151011,-0.584811,-0.203419,-0.440118,-0.309818,0.063367,0.274276,-0.227947,0.802539,-0.912419,0.335103,0.600538,0.449011,-0.224084,0.446026,0.166957,0.346346,-0.319080,-0.077419,0.383489,0.054920,0.348867,0.221947,0.355512,0.345479,0.186664,-0.256177,0.857252', '26290398', '35377026', '1308585', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26683421', '特工', '剧情', '1990年代中期，暗号「黑金星」的南韩「国家安全企划部」情报员，假扮成南韩商人跟北韩进行商业交易，藉此渗透北韩军事单位，打探核开发情报，他得在最危险的地方，赢得敌方的信任，没想到一心只想完成任务的他，却在不自觉中陷入南北韩权力高层间的恐怖阴谋。', '黄政民', '尹钟彬', 8.7, 168970, 'tt8290698', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2528281606.jpg', 0.2, 0.6, 9.9, 43.5, 45.7, '0.145282,0.555252,-0.743893,0.712113,-0.100308,0.374723,-0.113201,0.084685,-0.396210,-0.219648,0.179072,0.431414,0.202592,-0.436244,0.137290,-0.231739,-0.086510,-0.676738,-0.384229,-0.424105,-0.070495,-0.676286,-0.755184,-0.584921,-0.292384,-0.404306,0.622235,0.667659,-0.534314,-0.279263,0.022109,0.326798,-0.453427,0.500572,0.247797,-0.607661,0.711089,-0.207247,-0.575288,0.122684,-0.150950,-0.029040,-0.024931,0.196151,0.183618,0.469262,0.384231,-0.060390,-0.065965,-0.309772,0.201459,-0.236176,-0.116927,-0.286178,0.517278,0.062504,0.146145,0.118433,-0.004357,0.229444,0.191809,-0.280520,-0.882127,-0.364850,0.344724,0.488298,-0.160740,0.307139,-0.353346,0.181375,0.014474,-0.318506,0.312150,0.604672,0.271447,0.031673,0.057762,0.468899,-0.521505,0.229315,0.784664,-0.144331,-0.335454,-0.153691,-0.131290,-0.709528,-0.174671,-0.434519,0.049057,-0.274793,0.213329,-0.075647,-0.090437,0.222219,-0.524721,-0.003725,0.017208,-0.216513,-0.012561,-0.249937,0.204898,-0.728999,-0.290241,-0.425341,-0.211724,0.246860,0.141727,-0.169912,0.541508,-0.690109,-0.183721,0.741547,0.348000,-0.671057,0.514178,0.169986,0.097516,-0.757924,-0.261964,-0.116388,0.111491,0.317136,0.071458,-0.049010,-0.390847,-0.381800,-0.308998,0.168139', '4767216', '27009869', '1297689', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26683723', '后来的我们', '剧情', '大学生林见清（井柏然 饰）与同乡方小晓（周冬雨 饰）在春运的火车上相识，两个北漂青年开始了共同的奋斗生活。东北小城的除夕夜、中关村的电脑配件城、下雪的北京街道、地下通道的小贩、出租屋的各色租客都见证了他们的喜怒哀愁，在情感上屡次被骗的小晓终于与刚毕业的见清走到了一起，一年又一年，不管生活再不如意他们都一起回家，在见清父亲（田壮壮 饰）开的小餐馆里吃年夜饭，亲密的就像一家人。可是随着时间的消逝，两个人开始有了分歧，恋爱、分手、错过、十年后重逢.......后来的他们再也回不去了。©豆瓣', '井柏然', '刘若英', 5.9, 353970, 'tt8033592', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2520456502.jpg', 8.4, 21.8, 42.7, 19.8, 7.2, '0.496908,-0.074203,-0.681152,0.348179,0.207081,-0.711432,0.637184,0.161995,-0.340995,0.074762,-0.205461,0.686825,-0.422480,0.787070,0.333231,-0.181919,-0.290519,-0.816789,-0.006505,-0.443601,-0.485239,-0.282169,0.229315,0.015979,-0.108849,0.161920,0.429405,0.240981,0.253632,0.727626,0.352332,-0.552460,-0.183331,0.408113,-0.464589,0.176362,-0.052139,0.452092,-0.564884,-0.135898,0.003114,-0.299643,-0.305143,-0.200203,0.368108,0.373318,0.674753,0.124739,-0.131826,0.175484,0.207614,0.059347,-0.172779,-0.050533,0.590676,0.115289,0.205135,0.338883,-0.163394,0.034791,-0.203432,-0.016148,-0.089305,0.337281,-0.093925,-0.092706,-0.695061,0.630624,0.421909,-0.219865,0.041258,-0.298439,0.385087,0.588445,0.047017,0.557258,-0.116917,-0.004075,-0.693415,0.523167,1.017779,-0.037549,-0.191284,0.489456,0.112395,-0.399412,-0.145611,-0.163778,-0.393591,-0.003420,0.126359,-0.123784,-0.480028,0.244709,-0.900023,0.229243,-0.026273,-0.140829,0.245442,-0.159261,-0.130352,-0.795027,-0.121122,-0.620332,-0.411286,0.621391,0.009836,-0.013103,0.550582,-0.750902,0.185755,0.284508,0.554186,-0.481787,0.933582,0.045283,0.206526,-0.025196,0.214373,0.187242,-0.184485,0.474133,0.458344,0.518322,-0.276642,0.212686,-0.578203,0.538228', '26687241', '1926007', '3055049', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26684564', '关灯后', '恐怖', '瑞贝卡（泰莉莎·帕尔墨 Teresa Palmer 饰）早早离开了母亲索菲（玛丽亚·贝罗 Maria Bello 饰），独自生活，之后索菲和保罗（比利·伯克 Billy Burke 饰）结婚，瑞贝卡有了一位名为马丁（加布里埃尔·贝特曼 Gabriel Bateman 饰）的同母异父的弟弟。然而，保罗在一场事故中死于非命，索菲因此陷入了悲伤和绝望之中，与此同时，马丁发现，妈妈常常会对着黑暗窃窃私语，似乎那里隐藏着一位“不速之客”。精神备受折磨的马丁向瑞贝卡求助，瑞贝卡因此想起了自己童年时代发生过的与此极为相似的事件。经过调查，这位隐藏在黑暗之中的神秘人物名为戴安娜（艾丽西娅·维拉-贝利 Alicia Vela-Bailey 饰），曾是母亲住院其间最好的朋友，之后死于一场医疗事故，如今，戴安娜的亡魂再度回到了索菲的身边，她要这位她最好的朋友永远的和她在一起，任何企图接近的人都将面临死亡的威胁。', '泰莉莎·帕尔墨', '大卫·F·桑德伯格', 6.8, 54955, 'tt4786282', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2327225597.jpg', 1.2, 8.7, 48.8, 32.1, 9.2, '0.250719,-0.029480,-0.820312,0.484848,-0.040259,-0.338749,1.012815,0.032536,-0.770175,-0.597236,0.274594,0.936427,-0.365838,0.456990,0.491807,0.054529,-0.399338,-0.707716,-0.208817,-0.152209,-0.365335,-0.584386,-0.381438,-0.105076,-0.117134,-0.400116,0.266832,0.021028,-0.127601,0.508154,0.229401,0.772219,-0.151820,0.420554,0.040806,0.040538,0.149307,-0.073905,-0.471519,0.268926,0.289261,-0.217322,-0.084256,0.341368,0.031265,0.252409,0.624012,-0.404045,-0.083704,-0.083419,0.230735,-0.137124,0.146650,0.249236,0.266011,-0.052515,0.176163,0.256425,-0.327448,-0.037400,0.098783,0.053072,-0.554866,0.168039,0.029906,0.375600,-0.559669,0.375494,-0.016530,-0.012284,0.233563,-0.135074,0.478656,0.387016,0.144805,0.246302,-0.259523,-0.065051,-0.449498,-0.050199,0.758573,0.030652,0.007807,0.121182,-0.216728,-0.334408,-0.053547,-0.059765,-0.637793,0.157807,0.407789,0.192564,-0.127833,0.449693,-0.576178,-0.340974,-0.225709,-0.113380,-0.150972,-0.303042,-0.142986,-0.550238,-0.070471,-0.433091,-0.388812,0.084517,-0.278555,-0.166440,0.530302,-0.867079,0.610607,0.413509,0.287045,-0.304876,0.553700,0.036551,0.447199,-0.082394,0.024613,0.489864,0.084660,0.056906,0.125203,0.106298,0.004234,0.039041,-0.411765,0.419305', '1296534', '1300958', '30137576', '3014557');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26685451', '流浪猫鲍勃', '剧情', '电影改编自真实事件。家庭的破裂令詹姆斯（卢克·崔德威 Luke Treadaway 饰）遭受了巨大的打击开始自暴自弃，他染上了毒瘾，身无分文，成为了一名流连在街头的卖艺者。瓦尔（琼安·弗洛加特 Joanne Froggatt 饰）是负责詹姆斯的戒毒所医生，在她的帮助下，詹姆斯终于有了一个能够遮风挡雨的家，瓦尔坚信詹姆斯能够凭借自己的意志，彻底摆脱毒品的诱惑。某日，一只流浪猫闯进了詹姆斯的家，詹姆斯收养了它，给它取名鲍勃，当詹姆斯离开家走上街头卖艺的时候，鲍勃跟在他的身边寸步不离。很快，这一人一猫的组合便吸引了过路人的注意， 詹姆斯的经济状况因此得到了巨大的改善，与此同时，詹姆斯结识了住在隔壁的女子贝拉（鲁塔·盖德敏塔斯 Ruta Gedmintas 饰），在贝拉的身上，詹姆斯重新燃起了对爱的渴望。©豆瓣', '卢克·崔德威', '罗杰·斯波蒂斯伍德', 7.9, 195603, 'tt3606888', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2535524955.jpg', 0.3, 2.1, 24.4, 47.9, 25.4, '0.413766,0.225303,-0.616299,0.430341,-0.228060,-0.474975,0.660553,0.443326,-0.340859,0.038876,0.292149,0.815033,-0.126842,0.262813,0.159219,0.166624,-0.318092,-0.642703,-0.008755,-0.133268,-0.379576,-0.430929,-0.320967,-0.308079,-0.091258,-0.427366,0.330874,-0.003920,-0.309117,0.440176,0.368032,0.435671,0.242168,0.307074,-0.271157,0.277743,0.194792,-0.238553,-0.190039,0.459419,0.128423,-0.227816,-0.124992,0.173040,0.039312,0.340482,0.671976,-0.319934,0.018136,-0.078885,0.374104,-0.057448,0.158555,0.199610,0.097555,-0.042321,0.026477,-0.052166,-0.388057,0.133185,0.212438,-0.022280,-0.697870,-0.027856,-0.008695,0.185376,-0.733692,0.381358,0.006305,-0.114861,0.201451,-0.248803,0.061366,0.391493,-0.044154,0.452298,-0.160295,0.091930,-0.565884,-0.018296,0.588082,-0.066120,-0.374455,0.241524,-0.397004,-0.204414,-0.010888,-0.112242,-0.439573,-0.311207,0.774147,0.083599,-0.309525,0.243932,-0.539183,-0.091393,-0.457055,-0.196733,-0.124740,-0.423172,-0.171327,-0.602281,-0.208024,-0.264565,-0.154586,0.051434,-0.115200,-0.302165,0.660873,-0.780336,0.409458,0.748688,0.259949,-0.103247,0.565083,-0.114209,0.234411,0.008070,-0.057798,0.332946,0.078517,0.412814,0.358082,0.465675,-0.154244,0.040979,-0.467142,0.751655', '1309069', '30162520', '1949005'