INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26687241', '仓皇一夜', '喜剧', '杰西是一位准新娘，前往迈阿密和她的四位大学好闺蜜们聚会。她们在迈阿密租下了一所海滨别墅，为杰西举行单身派对。毕业后各自忙碌的生活让闺蜜之间聚少离多，只要五个女人一相聚，就有一种回到十八岁的感觉。这种久违的放肆和青春撞上酒精和可卡因，就演变成一场乐极生慌的闹剧。正当五个女人在海滩别墅里尽情享受着妙不可言的单身派对时，雇来的脱衣舞男杰伊却意外身亡。', '斯嘉丽·约翰逊', '露西亚·安尼洛', 5.7, 13927, 'tt4799050', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2456953348.jpg', 5.9, 27, 49.1, 13.7, 4.2, '0.309918,-0.161932,-0.807311,0.239177,-0.104146,-0.288833,1.069876,0.206177,-0.379633,-0.024191,0.265319,0.953666,-0.703145,0.789408,0.753730,0.127169,-0.148808,-0.758378,-0.083097,-0.113695,-0.303553,-0.183254,-0.080077,0.017520,0.060260,-0.196123,0.283418,0.081094,-0.054308,0.891237,0.320039,0.004142,-0.150598,0.565895,-0.435534,-0.291806,0.365887,0.258016,-0.338557,0.353089,-0.069174,0.073959,-0.166094,-0.083362,0.180238,0.075748,0.996254,0.164265,-0.156196,-0.058304,0.084978,0.094705,-0.371622,0.338863,0.302320,-0.132627,0.397655,-0.031818,-0.264523,0.122802,0.113584,-0.103056,-0.477398,0.213133,-0.174757,-0.086337,-0.475363,0.861938,0.164643,-0.328346,0.284474,-0.210094,0.282423,0.469581,0.139335,0.588053,-0.075167,0.213090,-0.470342,0.225668,1.235308,0.107508,-0.121083,0.378336,-0.077850,-0.240131,0.108211,0.094805,-0.479169,-0.324709,0.032907,-0.266776,-0.144624,-0.129198,-0.675771,0.133830,-0.112902,-0.272337,0.214001,-0.313347,-0.110950,-0.995689,-0.071153,-0.155020,-0.334434,0.168952,0.229468,-0.167654,0.573915,-0.987186,0.361568,0.376609,0.305571,-0.440017,0.974066,0.396936,0.305447,-0.056706,-0.150756,0.013799,-0.041291,0.183419,0.007465,0.754930,-0.518931,0.180803,-0.469715,0.589797', '11541282', '1291992', '1303333', '3139191');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26688480', '逃出绝命镇', '悬疑', '黑人小伙克里斯（丹尼尔·卡卢亚 Daniel Kaluuya 饰）和白人女孩露丝（艾莉森·威廉姆斯 Allison Williams 饰）相恋，虽然两人之间的感情十分要好，但克里斯一直为自己的肤色心存芥蒂。某日，两人相约前往露丝家做客，在那里，克里斯见到了露丝的父母迪恩（布莱德利·惠特福德 Bradley Whitford 饰）和米西（凯瑟琳·基纳 Catherine Keener 饰），除了露丝的弟弟吉瑞米（卡莱伯·兰德里·琼斯 Caleb Landry Jones 饰）对克里斯展现出了一丝敌意外，一切都堪称完美。隔日，克里斯参加了露丝家举办的派对，在派对中，克里斯遇见了旧友安德鲁（凯斯·斯坦菲尔德 Keith Stanfield 饰），让克里斯百思不得其解的是，安德鲁的穿着、谈吐和举止和先前大相径庭，判若两人。种种诡异的蛛丝马迹让克里斯渐渐察觉，自己似乎陷入了一个阴谋之中。', '丹尼尔·卡卢亚', '乔丹·皮尔', 7.8, 348348, 'tt5052448', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2508604641.jpg', 0.5, 2.4, 25.9, 49.6, 21.5, '0.599824,-0.103884,-0.593639,0.739317,0.085057,-0.701655,0.789186,0.305110,-0.712654,-0.526190,-0.092819,0.715435,-0.647766,-0.134048,0.457110,0.204084,-0.649707,-0.660460,-0.211774,-0.183223,-0.118570,-0.671634,-0.410962,-0.246088,-0.215039,-0.321793,0.172588,-0.081063,0.067177,1.031151,0.352822,0.223310,0.051482,0.425677,0.271850,-0.073056,0.176816,-0.059141,-0.331868,0.220407,-0.004220,0.187326,-0.392206,0.119498,0.199705,0.532501,0.610790,-0.231398,0.013472,-0.123707,-0.200476,0.264535,0.289845,0.454613,-0.007260,-0.274466,0.392066,0.148999,-0.144742,0.168024,0.526725,-0.098131,-0.409195,0.404008,-0.077761,0.456013,-0.373982,0.472032,-0.339852,-0.292513,0.504414,-0.497988,0.106277,0.119185,0.317116,0.182205,0.058607,-0.273658,-0.389886,-0.155430,0.542397,0.109292,-0.254915,0.192440,-0.564274,-0.127421,-0.200904,0.061526,-0.499404,0.172873,0.172424,-0.044937,0.186503,0.512198,-0.577570,-0.230257,-0.584495,-0.130498,-0.446524,-0.354111,0.103954,-1.079760,-0.355979,-0.758457,-0.396731,-0.206284,-0.154872,-0.193309,0.229504,-1.142669,0.380680,0.202849,0.072780,-0.085283,0.419229,0.361896,0.063154,-0.363778,-0.444928,0.286480,0.140893,-0.162619,-0.056997,0.574030,-0.020140,0.067934,-0.028520,0.547830