INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26688846', '金融决战', '动作', '《MASTER》由《绝密跟踪》导演曹义锡执导，围绕一起韩国建国以来最大规模的诈骗案件展开，讲述智能犯罪搜查队和高智商诈骗团伙之间一场侦查与反侦察的智勇博弈。最近在《局内人》中展现绝佳演技的李秉宪将再演反派，在片中饰演领导完美作案计划并拥有出色口才的OneNetwork 公司陈会长一角，他是这起大规模网络诈骗案件的幕后操控者。而姜栋元饰演追查案件的智能犯罪搜查队队长金宰明，凭借高智商和无懈可击领导能力，与陈会长展开正面对垒。值得一提的是，这将是姜栋元出道以来首次扮演警察角色。此外，新生代人气男星金宇彬将在片中出演陈会长的头号智囊“朴将军”，是一个聪明绝顶，在警察和陈会长之间活动自如游刃有余的角色。', '李秉宪', '曹义锡‍', 6.7, 12467, 'tt5735464', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2405700781.jpg', 1.2, 8.9, 53, 28.4, 8.6, '0.052208,-0.134721,-0.332491,0.702871,0.028243,0.341876,0.441252,-0.044169,-0.644108,-0.407935,0.122201,0.318093,-0.399253,-0.114333,0.369807,-0.794401,-0.325878,-0.806735,-0.439092,0.109086,-0.064374,-0.717130,-0.481671,-0.124896,-0.147725,-0.330209,0.850720,-0.112627,-0.710891,0.211013,0.690681,0.272028,-0.399005,0.110927,0.143674,-0.317814,0.414702,-0.059702,-0.610038,0.457174,0.058010,-0.433513,0.121065,-0.091043,0.194590,0.220341,0.720238,-0.240049,0.018413,-0.073137,0.434386,-0.588719,-0.015494,-0.106287,0.705210,0.249607,0.120254,0.331736,0.074433,-0.091844,-0.185122,-0.325377,-1.220990,-0.226010,0.478792,0.186961,-0.440262,-0.289680,-0.083961,0.179259,0.142102,0.004705,0.266929,0.313749,0.532455,0.012084,0.317772,0.205235,-0.154729,0.445821,0.418341,0.029588,-0.298797,0.031390,0.011759,-0.815259,-0.298691,-0.400460,-0.095306,0.032157,-0.028799,-0.547142,0.531265,0.082393,-0.430424,-0.052024,0.046786,0.216045,0.017111,-0.366920,0.182866,-1.040905,-0.226357,-0.439606,0.131674,0.237779,0.041832,-0.597719,0.570586,-0.908567,-0.290699,0.509828,0.072274,-0.559108,0.592637,0.212784,0.185504,-0.709944,-0.068382,-0.277754,0.539815,0.071241,0.030142,0.429495,-0.025609,-0.424831,-0.082620,-0.101258', '27073234', '20388224', '2369613', '1293989');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26689198', '同船爱歌', '剧情', '西奥和雨果在肉欲横陈的性爱夜店裡天雷勾动地火，汗水淋漓交缠过后，他们心旷神怡地携手离开，正当骑车徜徉在凌晨的空旷大街上时，残酷的真相却顿时将他们拉回现实，但也为他们的关係开启另一扇窗。在震撼心灵平复后，两人才在随意交谈中逐渐认识彼此，黎明破晓前的短短90多分钟内，他们能否缔造一夜情的完美结局？《巧克力男孩》导演奥立维耶杜卡斯第和贾克马帝纽令人脸红心跳又心花怒放的同志新作，开场20分钟性爱场面令人瞠目结舌，之后又急转直下从心理惊悚到浪漫纯爱，在真实时间中带领观众经历云霄飞车般的情感风暴，宛若《爱在週末邂逅时》加上《维多莉亚》，两人邂逅时四周无人的超现实场景，堪称《傲慢与偏见》唯美交际舞的性爱版。', '杰弗瑞·古艾', '奥利维耶·杜卡斯泰尔', 7.6, 11799, 'tt5096628', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2494910891.jpg', 0.9, 4.2, 31, 43.9, 20, '0.146792,0.254909,-1.056333,0.385540,0.341671,-0.211994,0.992064,0.094258,-0.458786,0.110208,0.165636,0.438060,-0.771637,0.250607,0.646136,-0.151222,-0.549151,-0.829308,-0.050698,-0.196663,-0.092880,-0.048636,-0.204239,-0.039136,0.143447,-0.248965,0.380884,0.320216,-0.131060,0.550785,0.161572,0.062182,-0.389862,0.483035,0.015115,-0.045419,0.225891,0.350345,-0.493160,-0.076026,-0.086790,-0.255648,-0.247531,0.007707,-0.384570,0.057714,0.873371,-0.533683,-0.263684,0.266523,0.316279,-0.022130,-0.339144,0.216287,-0.076801,0.119428,0.243050,-0.109034,-0.184192,0.303574,-0.305676,0.133147,-0.500749,0.254444,-0.129611,-0.015595,-0.208911,0.558914,0.028856,-0.227917,0.380435,-0.117923,0.079344,0.181987,0.502953,0.671118,-0.176555,-0.149660,-0.039447,-0.015827,0.675014,0.356481,-0.598262,0.600858,-0.331861,-0.420646,-0.136707,-0.080935,-0.157388,-0.163716,0.401088,0.361294,0.041032,0.389954,-0.770194,0.046952,-0.202289,-0.093751,-0.243135,-0.391239,-0.339304,-0.728013,-0.279303,-0.395164,-0.082148,0.031835,0.021598,-0.306108,0.521729,-0.401848,0.214137,0.292310,0.155764,0.206208,0.537920,0.145750,0.023970,-0.036085,-0.053012,0.355801,-0.161795,0.505308,0.123264,0.654360,-0.484197,0.370488,-0.640066,0.486190', '21339377', '3011051', '2269893', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26691320', '帝一之国', '剧情', '生长于政治世家的赤场帝一（菅田将晖饰），从小就以当上日本总理为目标，为了建立自己的王国，他必须在孕育出多位政治领袖，人称「超精英学校」的海帝高校展露头角，只有当过海帝高校学生会长的人，未来才有机会角逐总理的宝座。「我一定打败所有竞争对手，站在顶点！为此我会不择手段！」比谁都早开始计划的帝一，将要面对意想不到的陷阱和试炼！斗个你死我活的学生会长选举战争即将华丽展开！', '菅田将晖', '永井聪', 8.1, 40450, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2456938774.jpg', 0.4, 1.7, 19.3, 48.9, 29.6, '-0.493017,0.051379,-0.823094,0.616881,-0.174882,-0.164637,-0.129343,0.200186,-0.228480,-0.249732,0.480639,0.772347,-0.201753,0.035683,0.425481,-0.601955,-0.063634,-0.746018,-0.355523,0.069726,-0.385840,-0.188004,-0.246997,-0.393096,-0.063931,-0.282497,1.264006,0.022479,-0.466750,-0.130937,0.488344,0.403070,0.095987,0.284887,-0.365567,-0.546050,0.200588,0.227899,-0.701765,0.168332,-0.325088,-0.179703,-0.324088,0.129956,0.286463,-0.094101,0.154002,-0.316542,0.202960,-0.437740,0.314613,-0.491256,-0.147133,-0.024012,0.748741,-0.107829,0.064996,0.804822,0.108156,-0.118155,-0.104634,-0.582932,-1.092103,-0.178725,0.214770,0.009410,-0.184958,0.506481,0.190330,-0.118381,0.323103,0.154335,0.136598,0.927577,0.331013,0.009785,-0.171169,0.240722,-0.528208,0.026755,0.669529,-0.004697,-0.311798,-0.207034,0.285221,-0.530238,0.075989,-0.644167,-0.101979,-0.041407,0.122581,-0.242478,0.306654,0.454351,-0.349232,-0.131114,-0.248518,-0.344788,0.691752,-0.484039,0.145421,-0.393871,-0.227073,-0.065891,-0.100151,0.205243,0.187816,-0.268619,0.918949,-0.964207,0.018133,0.433319,0.327814,-0.840427,0.533551,0.245463,0.108510,-0.568552,-0.429120,0.157305,-0.135654,0.539413,-0.281813,0.180255,0.140157,-0.290335,-0.082787,0.544171', '3861846', '25880986', '24875409', '6519585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26691361', '21克拉', '喜剧', '刘佳音（迪丽热巴 饰）是挥金如土的购物狂，当然，她花的全都是富二代男朋友的钱。终于有一天，男友向刘佳音提出了分手，刘佳音因此正式宣告破产，为了能够继续生活，完全没有独立生活技能的刘佳音只得开始变卖她之前的“存货”。王继伟（郭京飞 饰）是一名话剧演员，虽然做着体面的工作，但在金钱上，王继伟是出了名的抠门。为了省钱，他无所不用其极，无论是装独立电表还是破解邻居家无线密码，只要最终的目的能够省钱，王继伟都干得出来。就是这样两个消费观大相径庭的人，在误打误撞之中住进了同一屋檐下，等待着他们的会是怎样有趣的生活呢？©豆瓣', '郭京飞', '何念', 4.5, 67204, 'tt8320654', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2518945837.jpg', 26.5, 36.3, 27.7, 6.3, 3.3, '0.190160,0.205652,-0.422575,0.459208,-0.524680,-0.388067,0.512312,0.012068,-0.461090,-0.380197,0.024272,0.373428,0.078955,0.346866,-0.032542,-0.104730,-0.248799,-0.426617,0.018216,-0.218890,-0.172944,-0.520998,-0.047903,-0.186975,-0.233543,0.134366,0.353864,-0.026403,-0.093381,-0.111065,0.730371,0.059022,0.258612,0.344532,-0.224003,-0.128824,-0.129486,-0.004543,-0.315074,0.164725,0.033236,-0.240240,-0.183466,0.144864,0.421688,0.327076,0.428536,-0.106002,-0.093599,0.241329,0.282553,-0.086758,-0.096640,-0.030450,0.150025,-0.222826,0.485695,-0.166289,-0.146211,0.186061,0.152197,-0.090019,-0.909796,-0.157957,0.145068,0.061866,-0.459353,0.238976,0.124468,-0.091799,-0.019254,-0.469831,0.232742,0.335208,0.428429,0.448323,-0.241904,0.209322,-0.715295,0.513389,0.668563,0.183854,-0.120186,0.480966,-0.338633,-0.567225,0.004452,-0.254683,-0.712421,-0.093591,0.141501,0.011874,-0.055106,-0.016836,-0.582409,0.161939,0.148512,-0.007504,0.186733,-0.475282,0.100248,-0.452768,-0.020438,-0.639443,-0.303891,0.124391,-0.055004,-0.566625,0.768011,-1.009011,-0.208404,0.417484,0.213598,-0.688896,0.653249,0.166782,0.216305,0.025331,0.061927,-0.123104,-0.016189,0.434333,0.276915,0.415421,0.184866,-0.335977,-0.085454,0.508507', '1877596', '1793491', '4301278', '5985887');
