INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26692647', '毕业作品', '剧情', '警校学生殷浩（张一山 饰）和自己的女朋友——电影编导系学生小暖（丁丁 饰）为完成小暖的毕业作品登上了隔离岛拍摄纪录片。殷浩在拍摄纪录片之外，还有自己的小心思，他希望与小暖在岛上进一步巩固恋人关系。二人在岛上偶遇了大商人丁子楚，丁子楚为寻找失踪的女儿娜娜来到岛上却意外丧命，三十年前的大火，让众人都卷入了一场漩涡之中。殷浩发挥警校学生的特长探案追凶，而小暖拍摄的纪录片也成为了殷浩搜寻真相的重要证据。命案在岛上接连发生，小暖也陷入危机，殷浩探明真相后为爱勇闯险境成功救出小暖，二人感情升温的同时，也交出了真正的毕业作品，完成了一次成长的蜕变。', '张一山', '许斌', 3.3, 3804, 'tt10476336', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2518260554.jpg', 50.2, 37.4, 10.8, 1.5, 0, '-0.082609,0.027745,-0.606097,0.394191,0.046547,-0.192596,0.445515,-0.084430,-0.398574,-0.235486,0.278865,0.484693,-0.289949,0.187443,0.081015,-0.103543,-0.458292,-0.828411,0.046903,-0.141308,-0.264593,-0.173305,-0.475227,-0.052875,-0.110440,-0.400961,0.854564,0.416219,-0.369668,0.297333,0.200569,-0.288904,-0.333472,0.408176,0.281436,0.110994,0.092006,0.242656,-0.425120,0.303483,-0.128382,-0.216781,-0.081144,-0.076589,0.385974,0.300424,0.916386,0.121394,-0.202458,-0.187769,0.450945,-0.514695,-0.079294,-0.089705,0.177775,0.296819,0.330059,0.333392,-0.213487,0.040603,-0.198303,-0.289391,-0.598521,0.063186,0.448364,-0.068861,-0.370260,0.367197,-0.145083,-0.071679,0.236322,-0.307795,0.116042,0.549710,0.391113,0.424655,-0.247858,0.148667,-0.285039,0.361450,0.732665,-0.415950,-0.118314,0.193036,0.173320,-0.452634,-0.217467,-0.068403,0.035102,0.223592,0.241596,0.095729,-0.176408,0.428131,-0.383247,-0.045791,-0.200931,-0.127964,-0.074289,-0.455206,0.022447,-0.693684,-0.081426,0.134742,-0.271673,-0.167174,0.078004,-0.578220,0.678072,-0.559086,0.287464,0.397509,0.429650,-0.548582,0.622875,0.146228,0.249710,-0.489500,0.043739,0.306827,-0.197179,0.371868,-0.070869,0.043730,-0.083997,-0.314986,-0.711112,0.170495', '5403927', '3667102', '1302050', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26692652', '蝙蝠侠：致命玩笑', '动画', '他是蝙蝠侠最不共戴天的宿敌，是丧心病狂的犯罪大师，他怪异的狂暴行径就连世界最佳侦探也琢磨不透。然而小丑并非天生如此。在他成为犯罪界的小丑王子之前，在那命定的一天将他面容尽毁、心灵永久扭曲之前，他也曾是黑暗骑士愿意献出生命去保护的对象——一个平凡人 。是什么导致了这个平凡公民堕落成了哥谭有史以来最强反派？蝙蝠侠能阻止小丑把戈登局长和他的女儿芭芭拉拖入疯狂深渊的计划吗？这对死敌能及时为他们之间无尽的对决画下一个句号吗？', '凯文·康瑞', '刘山姆', 6.9, 11189, 'tt4853102', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2368910000.jpg', 1.8, 10.8, 43.8, 29.8, 13.8, '0.107909,0.236413,-0.404265,0.672035,-0.422503,-0.055449,0.713874,-0.043548,-0.518464,-0.142552,0.240729,0.929813,-0.080618,-0.017288,0.138674,0.072343,0.081671,-0.622121,-0.379119,-0.150099,-0.261919,-0.380814,-0.368351,-0.141756,0.004917,-0.312034,0.853804,0.035063,-0.317409,0.069775,0.553571,0.271508,0.077401,0.379128,-0.423273,0.066140,-0.153473,-0.120988,-0.349387,0.257500,0.102622,0.047084,0.209047,0.560878,-0.572920,0.059611,0.511665,-0.483129,-0.161061,-0.319635,0.542720,-0.561881,-0.127968,0.386606,0.224347,-0.452024,0.104615,0.132296,0.148812,-0.260136,0.214864,0.002832,-1.286903,-0.201139,-0.029704,0.102551,-0.476783,0.292648,0.148243,-0.101935,0.259956,0.017655,0.341472,0.115196,0.398104,0.298733,-0.034415,-0.241853,-0.495710,0.387299,0.801266,0.140208,-0.447496,0.460755,-0.239046,-0.477005,-0.299649,-0.490615,-0.548263,0.046087,0.242466,-0.139446,-0.224224,0.337585,-0.604824,-0.075945,-0.210324,0.299717,-0.152746,-0.736490,-0.022884,-0.056151,-0.218849,-0.235592,-0.117039,0.119743,-0.000630,-0.436745,0.561230,-0.922254,0.300286,0.831626,0.245767,-0.383836,0.716075,0.437343,-0.083929,-0.337670,0.084623,0.205722,0.400916,0.478050,0.066956,0.177431,0.267125,0.243889,-0.248758,0.705522', '1793491', '27098364', '30163500', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26693110', '老人日记', '剧情', '魁北克住着一位极有名望的教授，尼古拉·吉蒙。如今他年事已高，记忆减退，弯腰驼背。身为医生，是无法对自己的身体状况撒谎的。如果有人问他，今天的日子有什么特别之处时，他会说，失眠，十一点准时入睡，两个小时之后再次醒来，如此反复。面对生活琐事他感到一丝厌倦，然而，他热爱教学。这一天，一个女人的忽然拜访，拿出了十分具有纪念意义的物件，让吉蒙教授想到了他...', 'Paul Savoie', '贝尔纳·埃蒙', 8.2, 6168, 'tt4737582', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2303850444.jpg', 0.2, 1.3, 16.9, 53.2, 28.4, '0.172553,0.004197,-0.527162,0.274685,-0.118900,-0.203390,0.824259,-0.059070,-1.008954,-0.830679,0.192241,0.718829,-0.351213,0.526471,0.320658,-0.011093,-0.312299,-0.349225,0.389143,-0.102723,-0.293069,-0.471105,-0.005733,-0.329441,-0.044134,-0.279091,0.184228,0.085976,0.016301,0.288681,-0.145877,0.135611,0.727159,0.832952,-0.228867,-0.340328,-0.074308,0.123873,0.105374,0.300431,0.597221,-0.214966,-0.446232,0.232568,-0.338199,0.178693,0.245117,-0.007263,-0.571865,-0.063452,0.535207,-0.229949,-0.212447,-0.026432,0.291224,0.062024,0.024843,0.393156,-0.229272,0.070532,0.037781,0.067219,-0.469167,0.054494,-0.272496,0.299635,-0.508412,0.075380,-0.307286,-0.151784,-0.155537,-0.479718,0.219335,0.517147,0.080364,0.245379,-0.066370,0.034079,-0.621130,-0.018999,0.606752,-0.156854,-0.242196,0.393122,-0.170080,-0.548207,0.248065,-0.297769,-0.462246,0.147145,-0.375200,0.243967,-0.182847,-0.110848,-0.377102,0.259782,-0.250194,-0.322683,-0.048589,-0.281360,-0.271745,-0.266643,-0.035778,-0.286868,-0.507330,-0.059825,0.184072,-0.319589,0.712515,-0.968859,0.286536,0.371219,0.297614,-0.354789,0.763993,0.307396,-0.232731,-0.330764,0.048179,0.238329,-0.331784,0.228875,-0.011427,0.225549,0.234895,-0.073367,-0.244995,0.467743', '1302384', '2052978', '22555690', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26694497', '酒吧', '喜剧', '普通的一个白天，11个普通人被困在一个简陋的酒吧里。里面有老板厨子，有熟客，有偶然进去寻找充电器的陌生人。但是突然之间，大家发现出去的人就要被杀死，而酒吧内部也渐渐危机四伏。', '布兰卡·苏亚雷斯', '艾利克斯·德·拉·伊格莱希亚', 6.4, 19856, 'tt5121816', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2494819969.jpg', 2.4, 13.2, 53.9, 24.5, 6, '1.049055,-0.002247,-0.607795,0.200354,-0.168477,-0.097816,1.449797,-0.080167,-0.615532,-0.635258,0.147851,1.039128,-0.059389,0.171733,-0.110558,0.148274,-0.129062,-0.116092,-0.043135,-0.590619,-0.559666,-0.262434,-0.605697,-0.433213,-0.305683,0.410628,0.271778,0.199972,0.057044,0.429008,0.033021,-0.167485,-0.210266,0.772273,-0.369525,-0.040343,0.052922,0.077694,0.131998,0.683690,-0.315460,0.120470,-0.086168,-0.076744,0.170479,0.611956,0.170485,-0.255665,-0.369560,0.412049,0.438435,0.047030,-0.518113,-0.026531,0.716078,0.050003,0.426834,-0.417819,-0.413969,0.232610,-0.038136,-0.242319,-0.478462,0.225645,0.275512,0.257786,-0.340524,0.312560,0.689326,-0.286325,0.059387,-0.274840,0.561682,0.064877,0.380626,0.129949,0.076197,-0.125231,-0.887443,-0.448357,0.885919,-0.026666,-0.395801,0.337992,-0.329323,-0.218972,0.385541,-0.302017,-0.460092,0.125631,0.118195,-0.112819,-0.511051,-0.387372,-0.847245,0.540488,0.137676,0.174431,-0.312040,-0.152845,-0.328423,-0.704055,-0.176866,-0.079652,-0.323857,0.422905,0.009052,-0.114392,0.576019,-1.078839,0.231384,0.846750,0.274671,-0.232755,1.098501,-0.511251,0.191580,0.279495,-0.053255,-0.264802,0.494209,0.586024,-0.184695,0.695551,-0.456762,-0.204648,-0.328876,-0.076724', '1296534', '1301686', '1297192', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26694926', '狼行者', '动画', '讲述了11岁女孩萝宾的神奇经历。萝宾作为一个年轻的学徒猎人，她和父亲一起来到爱尔兰，准备消灭最后一批在那里的狼，但是改变她的事情来了，她发现了狼行者，此后一连串的古怪故事就发生了……', '霍纳·妮芙茜', '汤姆·摩尔', 7.7, 36201, 'tt5198068', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2654733189.jpg', 0.1, 2.1, 27, 52.7, 18.1, '0.512385,-0.035074,-0.529222,0.559997,-0.266006,-0.264267,1.043156,-0.316961,-0.404562,-0.489367,0.243769,0.702557,-0.113120,0.246598,0.424057,-0.057720,-0.114686,-0.649543,0.151210,-0.213825,-0.483013,-0.345537,-0.409024,-0.323830,0.114469,-0.317251,0.401276,0.025631,0.013370,0.516787,0.248095,-0.016206,-0.074513,0.398015,-0.218273,0.343513,0.322123,0.228090,0.156880,0.215310,-0.074678,-0.306175,0.021645,0.075873,-0.124212,0.486858,0.663989,-0.352114,-0.411684,-0.077937,0.399909,-0.162711,-0.075667,0.158235,0.550872,0.349176,0.074874,0.090138,0.024943,-0.257183,-0.374830,0.068558,-0.651714,0.107346,-0.090290,0.328166,-0.951123,0.413042,0.136385,0.184436,0.132319,-0.493860,0.187210,0.329444,0.378930,0.535659,0.132739,0.018661,-0.431979,0.360170,1.031515,-0.227604,-0.258601,0.379624,0.000195,-0.621290,-0.014000,-0.228137,-0.323264,0.295328,0.216833,0.005054,-0.546843,0.256807,-0.622346,-0.106689,-0.260817,-0.200237,-0.030594,-0.218459,-0.248350,-0.346008,-0.164024,-0.298985,-0.545402,0.293010,-0.109317,-0.258157,0.967751,-0.845738,0.384932,0.721867,0.215297,-0.435184,0.519633,-0.314156,0.304690,-0.175747,0.306553,0.110762,-0.086089,0.315681,0.221260,0.635904,0.023424,-0.176737,-0.433717,0.430755', '5262027', '1464907', '21619567', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26694988', '比海更深', '剧情', '邋遢潦倒的中年大叔筱田良多（阿部宽 饰）是一名私家侦探，早年间他作为作家出道，然而自从处女作之后就再也没有令人称道的作品问世。他满腹牢骚，自视清高，绝不愿为了钱去创作没有“灵魂”的作品。现实生活中处处为钱发愁，拿到钱后又转瞬扔进赌场，全然没有指望。母亲淑子（树木希林 饰）独自住在团地，在老人家的眼里，再差劲的儿子也有别人无可比拟的优点。良多原本拥有美满的家庭，只不过前妻白石响子（真木阳子 饰）再也无法忍受他的作为，离婚后带着儿子真吾（吉泽太阳 饰）另外过活。好不容易与儿子见上一面，良多父子以及随后赶到的响子在淑子家中团聚。台风袭来，他们被迫留在充满着往昔回忆的奶奶家过夜。喧闹却又平静的夜晚，有些事情悄然改变……©豆瓣', '阿部宽', '是枝裕和', 8.8, 187449, 'tt5294966', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2454274023.jpg', 0.1, 0.4, 8.2, 43.4, 47.9, '-0.056613,0.046345,-0.587787,0.384753,-0.230651,-0.667445,0.802340,0.233396,-0.499275,-0.374066,0.096237,0.680889,0.194410,0.434511,0.103550,-0.191376,-0.336717,-0.420004,0.016891,-0.183875,0.056028,-0.169384,0.075527,0.004782,-0.364393,-0.185776,0.567431,0.089839,-0.080795,0.337911,0.257003,0.226119,-0.035966,0.388254,-0.262917,0.224348,-0.323394,0.427067,-0.368544,0.123197,0.072981,-0.198870,-0.341297,0.161446,0.069350,0.253428,0.547732,-0.121130,-0.191634,0.071535,0.490775,0.117157,-0.009396,-0.032261,-0.033094,-0.043010,0.151069,0.094417,-0.297429,-0.065865,0.184968,-0.025891,-0.466905,0.122830,0.180206,0.082519,-0.490279,0.425713,-0.038910,-0.214614,0.359373,-0.341219,0.076028,0.021788,0.105283,0.364904,-0.203930,0.220568,-0.426594,0.538893,0.386808,0.091841,-0.116081,0.342928,-0.277640,-0.125610,0.191943,-0.522552,-0.512361,-0.070096,0.140580,0.271009,-0.030660,0.195026,-0.342345,0.147688,0.065385,-0.085980,0.243310,-0.213586,-0.047862,-0.484346,-0.082623,-0.356974,-0.374572,0.150401,0.086134,-0.287484,0.516805,-0.650345,0.246783,0.358631,0.185637,-0.291545,0.625213,0.094750,0.052477,-0.079622,-0.077164,0.181480,-0.026879,0.414933,0.125784,-0.005272,-0.049450,-0.117661,-0.156457,0.350886', '4233625', '1302384', '3111650', '1309080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26695000', '迪丽丽的奇幻巴黎', '动画', '十九世纪末正是巴黎的“美好年代”，新艺术百花齐放，新技术层出不穷，在这黄金盛世的背后却传出一连串女童被拐骗的声音，见义勇为的混血小公主迪丽丽和好友快递员踏上幻险旅程，穿梭于巴黎的各处名筑和大街小巷，拯救被困女童，途中邂逅居里夫人，毕加索，马蹄斯，罗特利特，莫奈，普鲁斯特，莎拉·波恩沙特，等众多时代天才名人，并得以慷慨相助。被誉为‘色彩魔术师’的法国动画大师米歇尔·欧斯洛继《叽里咕和女巫》、《夜的神话》、《王子与公主》等动画片大获成功之后，又一部经典之作问世。《迪丽丽的奇幻巴黎》勾勒了一幅绝美的巴黎风情画和群英谱。展示出现实题材和原创动画的可能性。本片《迪丽丽的奇幻巴黎》首次呈现真景与动漫结合的创作风格，实现了一场先锋动画革命。', '普鲁内尔·查尔斯·安布隆', '米歇尔·欧斯洛', 7.6, 9287, 'tt7169514', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2575736329.jpg', 0.8, 2.6, 29.9, 48.8, 18, '0.119504,0.162771,-0.485460,0.648660,0.748696,-0.306524,0.451334,0.021928,-0.208352,-0.297932,0.000972,0.865052,-0.473597,0.111991,0.605423,0.019923,-0.577222,-0.675364,-0.135428,-0.199739,0.065823,-0.067538,-0.239960,0.043043,-0.041515,-0.429083,0.604638,0.184355,-0.343511,0.612042,0.247965,0.105058,-0.364166,-0.140558,-0.101552,0.114308,0.343261,0.068287,-0.526175,0.377290,-0.046772,-0.038842,-0.066076,-0.133314,-0.203558,-0.144677,0.769844,-0.624852,0.287996,0.045571,0.660524,-0.113174,-0.153101,-0.102948,-0.045073,-0.162707,0.251862,0.079693,0.093954,-0.388983,0.009887,-0.458222,-0.672381,0.024115,0.146446,0.108727,-0.172087,0.216946,-0.043607,0.106566,0.197916,-0.240428,0.218235,0.028773,0.546720,0.354976,0.279251,0.128921,-0.297889,0.611874,0.221862,0.247331,-0.455012,0.291000,-0.221056,-0.449114,-0.178222,-0.383396,-0.529201,0.254530,0.266561,-0.354213,0.104822,0.329098,-0.804051,0.045117,-0.571947,-0.093025,0.111387,-0.137294,-0.198236,-1.007866,-0.129927,-0.208696,0.144773,-0.093425,0.335855,-0.153445,0.800899,-0.702431,0.197020,0.252470,0.059898,0.075119,0.620220,-0.134092,-0.094244,-0.210184,-0.275101,0.199073,-0.026060,0.145394,-0.363134,0.479357,0.039030,-0.216094,-0.573194,0.385745', '3318306', '1322847', '26611806', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26695145', '发条城市', '喜剧', '三个性格迥异却情同手足的兄弟，在一家电影制作公司做道具师：老大宋戈（王自健 饰），比猴还精；老二小风（王宁 饰），单纯正直；老三阿正（修睿 饰），幽默感性。三兄弟因财务纠纷与电影投资人的相好骄阳（王鸥 饰）共同陷入了一起无厘头谋杀案，并发生了一连串歪打误撞、笑料百出的故事。©豆瓣', '王宁', '江涛', 5.8, 10339, 'tt6447734', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2364302622.jpg', 8.2, 23, 45.3, 16.8, 6.7, '0.098938,-0.110869,-0.035538,0.115403,0.260411,-0.167968,0.523046,0.580643,-0.377946,-0.470075,0.117798,0.364985,-0.355467,-0.020726,-0.032564,-0.308732,-0.050503,-0.422052,-0.063203,0.187183,0.286102,-0.487792,0.144269,0.032342,0.076102,-0.119558,0.264135,-0.317800,-0.264850,0.279700,0.473365,-0.100006,-0.521461,-0.203679,0.107454,0.126513,0.111720,0.247170,-0.507847,-0.449391,-0.245345,0.194472,-0.025646,-0.303784,0.201193,0.186496,0.723237,-0.138213,-0.330724,-0.168548,0.193109,0.256418,-0.095064,-0.133592,0.131765,-0.043939,0.605759,0.334488,0.228167,0.083292,0.151531,-0.040886,-0.904160,0.441417,0.188345,0.145936,-0.186891,0.409835,-0.004119,-0.076250,-0.021765,-0.332943,0.107160,0.147702,0.696921,0.396175,-0.115938,0.119483,-0.121203,0.381115,0.427860,0.235133,-0.115759,0.448716,0.027588,-0.211814,-0.199418,-0.036515,-0.320286,0.238638,0.414267,-0.569276,-0.046411,0.374024,-0.726689,0.099770,0.151925,0.293916,0.191481,-0.217330,0.232740,-0.636306,-0.040018,-0.383745,-0.335102,-0.079690,0.270873,-0.048625,0.691443,-0.460422,-0.196423,0.452368,0.002910,-0.526822,0.348765,0.148651,-0.060024,-0.325423,-0.280961,-0.316945,-0.074982,-0.107294,0.319815,0.432712,-0.139451,-0.202056,0.034625,-0.247756', '25918677', '3318306', '26678784', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26696639', '正义联盟大战少年泰坦', '动作', '罗宾因自己冒失的行为搞砸了正义联盟的任务，之后他被送往少年泰坦。在那里达米安遇见了星火、野兽小字、蓝甲虫和乌鸦。而乌鸦神秘的身世竟然引发了一场危机。乌鸦的父亲恶魔三宫控制正义联盟并威胁要征服世界，少年泰坦必须面对这个危机。', '斯图尔特·艾伦', '刘山姆', 6.8, 5527, 'tt5091548', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2574848677.jpg', 1.2, 7.2, 52.5, 29.5, 9.6, '0.117099,0.463957,-0.537777,0.519856,-0.174382,0.048350,0.750714,0.085585,-0.294827,-0.116880,0.549263,0.550232,-0.017357,-0.004318,0.480766,0.038447,-0.015409,-0.562006,0.119984,0.027124,-0.260623,-0.356286,-0.417828,-0.571768,0.161706,-0.340306,0.873344,0.458466,-0.350288,0.198429,0.233828,0.337920,-0.346394,0.501908,-0.011970,-0.320303,0.193272,-0.027316,-0.013718,0.060731,-0.143683,-0.080897,0.128258,0.828682,-0.669348,0.174497,0.595790,-0.861913,0.018420,-0.924532,0.273942,-0.680130,0.166248,0.054417,0.771411,-0.503141,0.082316,-0.011256,0.448917,-0.040820,0.052946,-0.090975,-0.841784,-0.048204,-0.141104,0.515528,-0.216634,0.613358,0.034943,0.503377,0.201999,0.157690,-0.200418,0.055101,0.586181,0.418015,-0.207581,0.078955,-0.214098,-0.208207,0.600798,-0.373514,-0.204983,0.071184,-0.069866,-0.555025,-0.194408,-0.195921,-0.305512,0.111671,0.587326,0.132631,-0.403534,0.599386,-1.016472,-0.134845,-0.411262,0.054219,-0.131000,-0.277029,-0.133342,-0.231745,-0.098496,-0.083705,-0.318599,0.022232,0.197870,0.145889,0.669366,-0.966861,0.154696,0.908982,0.428663,-0.546878,0.115916,0.165413,0.089992,-0.366833,0.149276,0.100194,0.073359,0.600516,0.179999,-0.117102,0.183606,-0.201628,0.176168,0.579298', '1305071', '3213270', '26759819', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26696871', '天生不对', '喜剧', '秦瑞（周渝民 饰）仪表堂堂，英俊潇洒，但总遇不到适合自己的女人，恋爱一波三折，他有些灰心，感觉自己这辈子都不会遇见可以白头到老的女人了。直到有一天，他遇见了佩佩（薛凯琪 饰），真正的爱情才逐渐开始，而他也开始明白什么叫天生一对。', '周渝民', '谷德昭', 4, 8230, 'tt7672188', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2503848298.jpg', 31.8, 43, 20.3, 2.9, 2, '0.137205,-0.182627,-0.668280,0.144041,-0.394896,-0.242750,0.603915,-0.117235,-0.670807,-0.048572,0.181440,1.065953,-0.318191,0.434151,0.102667,0.449444,0.071541,-0.708504,0.481210,-0.179820,-0.286033,-0.386906,-0.079020,0.016077,0.049553,-0.183850,0.593437,0.142660,-0.011258,0.159763,0.461875,-0.331520,0.592219,0.680694,-0.401566,0.127917,-0.075214,0.347658,-0.000932,-0.216873,0.318557,-0.039234,-0.249187,0.431255,-0.418283,0.099840,0.382027,-0.078308,-0.400569,0.223650,0.538885,-0.012248,-0.132242,-0.021922,-0.135304,-0.293246,0.283228,0.264042,-0.016954,-0.159344,-0.152355,0.415682,-0.290291,0.356455,-0.088206,0.121940,-0.215777,0.169626,0.105916,-0.357218,0.331629,-0.256565,0.268524,0.328854,0.721026,-0.024973,-0.314927,-0.217375,-0.664716,0.250883,0.892993,0.139311,-0.468950,1.002205,0.051579,-0.419289,-0.160291,-0.207667,-0.625132,0.210171,-0.217456,0.174166,-0.499974,-0.054548,-0.336474,0.418005,-0.059470,0.170738,-0.143654,-0.455156,-0.004117,0.298730,-0.461075,-0.862123,-0.474547,0.151601,-0.168739,-0.536755,0.556006,-1.018703,0.181080,0.713292,0.129265,-0.686628,0.659891,0.451740,-0.452476,-0.288817,0.172368,0.292743,-0.435815,-0.131846,0.093673,0.424088,0.185670,-0.068729,-0.156169,0.562077', '4275444', '21766698', '1389971', '26718282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26696875', '最萌身高差', '喜剧', '摄影系研究生张潇（高以翔 饰）拥有着傲人的196厘米身高，站在人群中总是最为扎眼的那一个。某日，张潇邂逅了名为夏汐泠（王水林 饰）的女孩，虽然生来娇小的夏汐泠身高只有156厘米，但张潇还是一眼就认定，夏汐泠是他一直在寻找的模特，一高一矮的两人站在一起，成为了校园里一道独特的风景线。一场意外让夏汐泠对张潇产生了误会，然而，随着时间的推移，夏汐泠发现人高马大外表粗犷的张潇，其实拥有一颗柔软温暖的内心，而张潇亦早就喜欢上了古灵精怪的夏汐泠。经过一番精心策划，张潇鼓起勇气向夏汐泠表白了，可是让他没有想到的是，夏汐泠果断的拒绝了他的追求。©豆瓣', '高以翔', '马侃', 3.8, 3957, 'tt6446772', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2398176331.jpg', 43, 31.7, 19.3, 4, 2, '0.632895,-0.056603,-0.622564,0.832646,-0.027847,-0.393229,0.942530,0.130827,-0.420444,-0.120848,0.276962,0.284947,-0.331597,0.365061,0.406828,0.273656,0.144399,-0.754907,-0.183393,-0.317085,-0.178090,-0.484922,-0.019702,0.265559,-0.256492,-0.240275,0.897362,-0.231088,-0.187625,0.860660,0.580981,0.042466,-0.045732,0.659004,-0.331025,-0.360851,0.028672,-0.079251,0.235699,0.367753,0.301185,-0.130829,-0.312935,0.368661,-0.476683,0.376892,0.333946,-0.175964,-0.179623,0.102834,0.590617,-0.280179,-0.147582,-0.106324,0.275404,-0.175311,-0.006632,-0.253838,-0.451294,0.297851,0.254562,0.177811,-0.186914,-0.062073,0.049676,0.068485,-0.806428,0.635789,0.113475,-0.355295,0.200736,-0.250720,-0.248018,-0.007301,0.161203,0.274997,-0.057063,-0.034027,-0.047936,-0.178536,0.391384,0.390846,-0.524144,0.506106,-0.112765,-0.537503,-0.411962,0.117253,-0.389536,0.071170,0.116637,0.209724,-0.102238,-0.040443,-0.700158,0.263401,-0.164760,-0.103877,0.085470,-0.294005,-0.348412,-0.345878,-0.413442,-0.609458,-0.797348,-0.042069,-0.176802,-0.554344,0.728365,-0.888368,-0.006542,0.475209,0.304428,-0.040335,0.538539,-0.017468,-0.088437,-0.005208,-0.145635,0.102404,-0.319894,0.126049,0.072032,0.740183,-0.129419,-0.102332,-0.600895,0.547041', '2131640', '21442760', '25911595', '20020577');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26696879', '你好，疯子！', '剧情', '七个互不认识的正常人莫名奇妙被关进了疯人院，为了逃脱这七个人费尽了心思：能把“死人说活”的话唠律师马睿（王自健 饰）、出口成章但性格懦弱的历史老师萧乃恩（金士杰 饰）、“混不吝”的记者李正（周一围 饰）、一心只想回家见女儿的兽医韩沐山（刘亮佐 饰）、脾气暴躁的出租司机杨猛（李虹辰 饰）、貌美圆滑的公关莉莉（莫小棋 饰），外加一个失忆了的奇怪女人安希（万茜 饰）。这七个人想方设法证明自己不是疯子，为了逃出疯人院做出了一系列令人捧腹大笑的荒唐事，然而这一切都被疯人院里监控摄像记录下来……©豆瓣', '万茜', '饶晓志', 6.7, 96260, 'tt6605830', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2408394301.jpg', 2.2, 11.9, 44.7, 32.3, 8.9, '0.226098,-0.109227,-0.438423,0.323807,-0.340318,-0.057227,0.537916,0.012835,-0.692831,-0.310970,0.043105,0.395051,-0.355878,0.043052,0.118150,0.042853,-0.161772,-0.430480,-0.116889,0.001724,0.027515,-0.353698,-0.030464,-0.335052,-0.076297,-0.089107,0.104833,-0.096912,0.154317,0.221293,0.361088,0.231586,-0.003532,0.031942,-0.061466,0.371181,-0.051298,-0.186037,0.137592,-0.072852,0.040903,-0.035920,0.107796,0.275975,-0.089299,0.343903,0.544565,-0.088669,-0.228269,-0.078085,0.330803,-0.182598,-0.367367,0.338518,-0.047901,-0.000904,0.300630,0.083049,-0.242355,0.035639,0.397956,0.132048,-0.628211,0.156369,0.041347,0.097902,-0.424037,0.186412,-0.190293,0.033343,-0.042674,-0.193079,0.214745,-0.181191,0.376766,0.343104,0.035492,-0.059643,-0.501571,0.343353,0.446750,-0.036103,-0.269903,0.406611,-0.127384,-0.311832,0.064792,-0.356028,-0.366771,0.143873,0.258882,-0.253132,-0.358055,-0.152037,-0.359044,0.035441,-0.077085,0.295776,-0.350228,-0.470232,-0.217315,-0.218555,-0.220117,-0.267234,-0.358702,-0.091023,-0.148086,-0.144734,0.698634,-0.567510,-0.131986,0.418462,-0.024502,-0.547302,0.527037,-0.018460,0.011517,-0.161022,-0.010227,-0.025664,0.269741,0.351747,0.094109,0.561013,-0.184297,-0.308632,-0.154193,0.070051', '1877596', '1296770', '24284209', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26698000', '心理罪', '动作', '一杯人血牛奶，为何会对人产生致命诱惑？什么样的扭曲心理才会为之痴狂，甚至不惜接二连三，连环杀人？非同寻常的杀手，超越常理的罪案，需要非同一般的警探。年轻气盛的犯罪心理学高材生方木（李易峰 饰）出手相助，却被卷入其中；身手不凡的野兽派刑警队长邰伟（廖凡 饰）嫉恶如仇，却难以走出内心泥沼。两人联手，却成绝妙拍档！一场身手的较量，心智的角逐，随之展开……', '廖凡', '谢东燊', 4.9, 145686, 'tt7232860', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2492869971.jpg', 15.3, 39.2, 34.5, 8, 3, '0.164788,-0.119243,-0.642055,0.536202,-0.272361,-0.016754,0.760803,-0.053957,-0.779410,-0.193048,0.612293,0.571015,-0.417437,-0.272552,0.216131,-0.558701,0.499282,-0.667265,-0.317507,-0.015810,-0.338671,-0.186278,-0.618606,0.044658,-0.007744,-0.071476,0.467816,0.149680,-0.679203,0.273947,0.327547,0.492824,-0.156309,0.337976,0.013336,-0.335464,-0.064495,-0.304136,-0.313736,-0.059208,0.203397,-0.394924,0.035387,0.399675,-0.544291,0.240162,0.593820,-0.287367,-0.262554,-0.214667,0.608517,-0.561132,-0.001404,0.232784,0.204907,0.100215,0.133701,0.150580,0.081317,0.113972,0.058125,-0.023273,-0.987826,0.137956,0.328886,0.074659,-0.398860,0.111035,-0.187083,-0.223465,-0.072344,0.135199,-0.401496,0.070670,0.702784,0.269150,0.004406,-0.216314,-0.344197,-0.278290,0.700050,0.136376,-0.438554,0.061418,-0.367666,-0.492683,-0.032722,-0.677545,-0.148839,-0.203429,0.438780,0.050245,0.184621,0.370694,-0.383035,-0.009220,-0.537482,0.497992,-0.164742,-0.192461,-0.057317,-0.412464,-0.406642,-0.412528,-0.402815,0.057152,0.345390,-0.181341,0.652097,-0.864567,-0.113400,0.446195,0.078867,-0.333394,0.223809,0.074661,-0.427875,-0.124175,-0.229367,0.228242,0.084020,-0.060458,-0.235862,0.428171,0.155863,-0.041140,-0.094904,0.095916', '1874704', '1793491', '3718665', '26667010');
