INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26698601', '快乐结局', '剧情', '洛朗(Laurent)家是一个富裕的上层中产阶级家庭。80多岁的老人乔治·洛朗(George Laurent)逐渐陷入老年痴呆。他和两个已婚的儿女托马斯(Thomas)和安妮(Anne)一起，正不自在地分享他在加莱(Calais)富丽堂皇的庄园。离异而冷漠的安妮，不得不承受因儿子皮埃尔(Pierre)的失职而导致的灾难性工作场所事故的影响。与此同时，托马斯的前妻因一场神秘的中毒而被紧急送进医院，导致他13岁的郁郁寡欢的女儿艾芙(Ève)与父亲和他的新婚妻子安娜伊思(Anais)生活在一起。毫无疑问，在这个家庭中，每个人都有不可告人的秘密，而随着洛朗家的命运与持续而不光彩的欲望交织在一起，一种特殊而又令人不安的联盟就会形成。但最终，有些更大的秘密即将揭晓……', '伊莎贝尔·于佩尔', '迈克尔·哈内克', 7.3, 9381, 'tt5304464', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2496674847.jpg', 0.6, 3.5, 37, 47.2, 11.7, '0.507917,-0.046186,-0.814550,0.589193,-0.182800,-0.210110,1.132644,0.473211,-0.569909,-0.311530,0.304837,1.074335,-0.038728,0.517899,0.399196,0.113735,-0.079959,-0.663326,-0.129871,-0.030812,-0.460960,-0.763019,-0.025358,-0.380441,-0.167352,-0.327438,0.717325,0.052607,-0.019809,0.447075,0.334028,0.513214,-0.135177,0.553352,-0.169875,-0.001720,0.164049,-0.008569,-0.261949,0.183081,0.332791,-0.097457,-0.086712,0.379614,-0.093349,0.404694,0.727682,-0.224517,-0.090646,-0.240226,0.500030,-0.159022,-0.266949,0.123715,0.428172,-0.079629,0.296296,0.242335,-0.418278,-0.139383,0.218269,0.075761,-0.756973,0.120904,0.408351,0.255449,-0.482387,0.687675,0.115064,-0.396345,0.239393,-0.116789,0.178225,0.834109,0.166079,0.599936,-0.394548,-0.016262,-0.502239,-0.075951,0.823289,-0.029854,-0.334210,0.390137,-0.613320,-0.191976,-0.038122,-0.323659,-0.892007,-0.143742,0.225913,0.216050,-0.241646,0.606818,-0.615962,0.155022,-0.381741,-0.086623,-0.008719,-0.550871,-0.087631,-0.652311,-0.360402,-0.681474,-0.377624,0.128551,0.163568,-0.040547,0.640566,-0.813315,0.427673,0.597675,0.233261,-0.580858,0.627199,0.251940,0.363670,-0.242806,-0.209274,0.250277,-0.097367,0.098889,0.051654,0.309569,-0.040575,0.172500,-0.267654,0.557080', '4301215', '2002744', '4275444', '1296534');
