INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26700276', '我去哪儿？', '喜剧', '意大利2016年票房奇迹。意大利著名喜剧演员凯科·扎罗内的作品第四部曲。38岁青年凯科·扎罗内实现了自己生活中所有的梦想：和父母一起生活避免独立生活的花销，和女朋友持续交往避免婚姻和家庭的责任，狩猎与垂钓许可办公室的铁饭碗工作避免工作风险，这些他都做到了，他的生活轻松得让人嫉妒，连老天爷也看不过眼了..', '切柯·扎罗内', '热纳罗·努基阿德', 8.1, 17409, 'tt5290524', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2433080603.jpg', 0.3, 1.3, 18.6, 51.5, 28.3, '-0.217958,-0.133535,-0.548784,0.400796,-0.290973,-0.297598,0.617061,0.187228,-0.546276,-0.174141,-0.149991,0.728125,0.109120,0.429960,0.477604,-0.112364,-0.352493,-0.930980,-0.047305,0.093212,-0.361575,-0.206726,-0.318419,-0.645555,-0.670215,-0.301093,0.638711,0.199938,0.047608,0.421391,-0.026852,-0.115908,0.134346,0.242842,-0.039026,-0.218579,0.211657,0.424449,-0.499139,0.168403,-0.306753,0.146492,-0.206011,0.083268,0.441147,0.142473,0.348826,0.053875,-0.222319,-0.159228,0.192242,-0.405803,-0.163155,0.152942,0.055686,-0.274085,0.377331,0.471652,-0.318789,-0.224901,-0.276477,-0.262901,-0.756550,-0.206412,-0.001230,-0.170635,-0.431109,0.639310,-0.107738,-0.025591,-0.129207,0.007724,0.143926,0.395082,0.517411,0.515446,-0.568273,0.141332,-0.483124,0.660546,0.934749,-0.103943,-0.402097,0.218516,-0.742296,-0.328106,-0.352909,-0.466656,-0.675291,-0.092094,-0.386426,-0.032550,-0.022277,0.526432,-0.684788,0.090536,-0.173783,-0.079777,-0.096461,-0.477734,0.238357,-0.789138,-0.292192,-0.583837,-0.542093,-0.063810,0.110615,-0.610687,0.823361,-0.570195,0.063502,0.697967,0.500943,-0.364631,1.037756,0.304244,0.720500,-0.119108,0.347233,0.335946,-0.299925,0.151065,-0.154454,0.166673,0.039493,-0.075109,-0.252643,0.799115', '30162520', '1437204', '1432669', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26700688', '阴影之下', '剧情', '故事发生在两伊战争期间，业已成家生子的Shideh（Narges Rashidi  饰）渴望回到大学校园完成学业，然而历史问题使她的学业之梦彻底破灭。她的丈夫Iraj（Bobby Naderi	饰）是一名事业有成的医生，Iraj不久前接到征兵通知，这让本来心情烦乱的Shideh愈加焦躁不安。令人不快的争吵过后，一家三口凄凄诀别。他们的小女儿Dorsa（Avin Manshadi 饰）夜晚无法安然入睡，Dorsa从小伙伴那里听说了巨灵的恐怖故事，这让她心有惴惴，时刻担心恐怖降临。战火里家门口越来越近，死亡时刻威胁着这对孤单的母女，而超自然的现象也相继在风雨飘摇的家中发生……©豆瓣', '阿米德·加瓦丹', '巴巴克·安瓦里', 6.4, 5970, 'tt4273292', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2304802483.jpg', 3, 12.3, 51.8, 27, 6, '0.121382,0.159914,-1.100400,0.206284,0.226440,-0.049469,0.755127,0.232832,-0.706203,-0.366934,0.204239,0.471471,-0.314415,0.401284,0.308774,-0.269065,-0.121846,-0.503479,0.188010,0.015923,-0.050147,-0.078200,-0.226885,-0.253496,0.046493,-0.476507,0.516042,0.607564,-0.000304,0.659706,0.032171,0.436460,-0.211019,0.713973,-0.036349,-0.011346,0.017881,0.345990,-0.337823,-0.099673,0.225371,-0.201279,-0.155569,0.262031,-0.042942,0.162502,0.574631,-0.288088,-0.533355,0.001893,0.543779,-0.293960,-0.363604,0.196555,0.336521,0.077547,-0.039012,0.074593,-0.305950,-0.181467,-0.140679,0.236129,-0.572247,0.307829,-0.031067,0.236473,-0.496508,0.491929,-0.011455,0.013483,0.315253,-0.183057,0.636158,0.587354,0.176307,0.585322,-0.240370,0.017677,-0.465608,0.139934,0.908780,-0.148310,-0.312624,0.312136,-0.397537,-0.066668,0.077829,-0.272181,-0.688514,0.006932,0.035315,0.436902,-0.282983,0.324505,-0.292219,0.048734,-0.087043,-0.083567,-0.121366,-0.458564,-0.282100,-0.418426,-0.216318,-0.300549,-0.388673,0.010359,0.024814,-0.056785,0.650597,-0.646745,0.504933,0.396661,0.281933,-0.353558,0.448333,0.282146,0.325433,-0.190204,0.021988,0.341975,-0.460741,0.323638,0.137579,0.078412,-0.330431,0.029786,-0.448335,0.486841', '3626364', '25870679', '25721544', '10733357');
