INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26701196', '无主之作', '剧情', '库尔特（汤姆·希林 Tom Schilling 饰）的姨母曾经被关进过集中营，最终在纳粹医生卡尔（塞巴斯蒂安·科赫 Sebastian Koch 饰）的折磨下不幸死去。虽然库尔特幸运的在柏林墙建成之前逃往了西德，但他的整个童年时代都生活在纳粹的阴影之下，这给他的人格带来了极大的创伤。之后，库尔特进入了杜塞道夫美术学院就读，无法走出过去阴影的他将内心的绝望和伤痛都挥洒在了画布之上。一次偶然中，库尔特邂逅了名为艾利（葆拉·贝尔 Paula Beer 饰）的女孩，美丽活泼的艾利渐渐的治愈了库尔特内心的伤痕，当两人鼓起勇气想要将关系再推进一步时，却遭到了艾利父亲的强烈反对。©豆瓣', '汤姆·希林', '弗洛里安·亨克尔·冯·多纳斯马尔克', 8.6, 75188, 'tt5311542', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2554483719.jpg', 0.2, 0.8, 10.7, 43.7, 44.5, '0.300198,0.166457,-0.818504,0.598747,-0.107240,-0.482152,1.166377,0.241467,-0.568237,-0.035260,0.323629,0.690445,-0.218756,0.406978,0.184559,0.223707,-0.343736,-0.780412,-0.019314,-0.213133,-0.521454,-0.444337,-0.340243,0.016885,-0.162530,-0.465156,0.508709,0.122017,-0.127867,0.484133,0.127584,0.449603,0.191005,0.626038,-0.188765,0.282944,0.159069,-0.282661,-0.157356,0.161518,0.289676,-0.507209,0.043776,0.388327,-0.023281,0.389128,0.766585,-0.428070,0.210835,0.082710,0.313481,-0.138166,0.072307,0.439259,-0.023297,0.049688,0.131919,0.196641,-0.302063,-0.085801,0.196179,0.036558,-0.648423,-0.014699,-0.005418,0.163852,-0.781774,0.764608,-0.093505,-0.045145,0.117427,-0.344166,0.073170,0.197430,0.089174,0.434476,-0.387500,0.158713,-0.322053,-0.006170,0.598203,-0.116556,-0.410372,0.273698,-0.568250,-0.331777,-0.089132,-0.089154,-0.312432,-0.035806,0.708155,0.210543,-0.284838,0.488276,-0.673750,-0.246547,-0.516383,-0.168452,-0.333427,-0.283542,-0.244834,-0.364002,-0.398447,-0.289593,-0.414033,0.036729,-0.176530,-0.141156,0.516192,-0.723289,0.503122,0.488058,0.287788,-0.028292,0.478187,0.143704,0.146606,0.219435,0.049190,0.770217,0.032782,0.660566,0.380797,0.601444,-0.008912,-0.058661,-0.439984,0.797755', '21619567', '21348112', '1578663', '1301464');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26703121', '黑白魔女库伊拉', '喜剧', '影片改编自道迪·史密斯的小说，故事设定在20世纪70年代朋克摇滚革命时期的伦敦，讲述了一个名叫艾丝黛拉（艾玛·斯通 饰）的年轻骗子的故事。艾丝黛拉是一个聪明又有创意的女孩，她决心用自己的设计让自己出名。她和一对欣赏她的恶作剧嗜好的小偷交上了朋友，并能够一起在伦敦的街道上建立自己的生活。有一天，艾丝黛拉的时尚品味吸引了冯·赫尔曼男爵夫人（艾玛·汤普森 饰）的眼球，她是一位时尚界的传奇人物，拥有毁灭性的时尚和可怕的高雅，但他们的关系引发了一系列事件，导致艾丝黛拉去拥抱她的邪恶一面，成为了兼具疯狂、时尚和报复心的库伊拉。', '艾玛·斯通', '克雷格·吉勒斯佩', 6.8, 183697, 'tt3228774', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2653946775.jpg', 0.7, 7.1, 49.3, 35.4, 7.5, '0.508993,-0.015618,-0.547804,0.814606,-0.243141,-0.062591,0.872900,0.117213,-0.366547,-0.098608,0.254101,0.838122,-0.453464,0.042173,0.279744,0.311557,-0.242761,-0.759308,0.068479,0.119777,-0.189125,-0.413397,-0.527397,-0.433046,0.019315,-0.466130,0.324505,0.043856,-0.387656,0.373374,0.493359,0.274413,0.173037,0.272659,-0.396627,0.030204,0.227959,0.044447,-0.008748,0.232315,-0.032803,-0.194959,0.002127,0.435242,-0.196912,0.353913,0.720175,-0.220677,-0.008054,0.070222,0.664247,-0.201670,-0.057407,-0.039312,0.206523,-0.028223,0.198173,0.050796,-0.081194,-0.179620,0.192268,-0.185740,-0.779356,-0.081861,0.251478,-0.006820,-0.450380,0.497620,0.036609,-0.192950,0.125416,-0.255807,0.157135,-0.024087,0.592861,0.384091,0.346756,0.124266,-0.445354,0.422816,0.642318,0.088389,-0.404296,0.516253,-0.673090,-0.589807,-0.450675,-0.327844,-0.632512,-0.088675,0.482020,-0.363585,-0.100447,0.177236,-0.899078,-0.064753,-0.151016,-0.025616,0.019705,-0.374451,-0.025859,-0.638708,-0.374294,-0.679689,-0.212409,-0.075047,-0.080230,-0.407980,1.130117,-0.665348,0.136701,0.845708,0.047067,-0.600299,0.844478,0.151112,-0.129198,-0.034425,-0.140446,0.462511,-0.127183,-0.171782,-0.026961,0.655381,-0.083658,-0.099053,-0.379211,0.934217', '30162520', '27602116', '1302661', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26703158', '斯隆女士', '剧情', '在华盛顿呼风唤雨的政治说客斯隆女士，在美国枪击事件接连发生的情况下，不惜牺牲自己的职业生涯，以督促政府实施更严格的联邦法律规范枪支。', '杰西卡·查斯坦', '约翰·马登', 8.8, 89773, 'tt4540710', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2356912156.jpg', 0.2, 0.7, 8.2, 41.4, 49.5, '0.062341,0.008136,-0.803010,0.720571,0.256836,0.154507,-0.018307,0.248203,-0.234945,-0.192281,1.157098,0.582154,0.079145,-0.315115,0.313846,-0.490740,-0.528524,-0.819864,0.026459,0.388031,-0.520227,-0.823636,-0.220772,-0.730819,-0.317675,-0.335450,0.641243,-0.134409,-0.763594,-0.219181,0.135088,0.336580,0.287384,0.204914,-0.265757,-0.400916,0.334875,-0.122350,-0.805572,0.015454,0.284407,-0.570310,-0.263550,-0.002525,0.248590,0.378894,0.256303,-0.269716,-0.422646,-0.154265,1.006821,-0.542102,-0.135705,0.179648,0.649824,0.110108,-0.483550,0.691036,0.033720,0.093027,0.028230,-0.217974,-0.643437,-0.373715,-0.035812,0.405070,-0.541769,0.392715,-0.568208,0.276314,0.062018,-0.318310,-0.095016,0.799065,-0.003503,0.202911,-0.298448,0.233215,-0.528120,0.267560,0.584323,-0.042772,-0.731892,-0.118804,-0.597682,-0.690292,-0.130329,-0.443582,-0.203435,-0.116282,0.087651,-0.898558,-0.120396,0.906710,-0.414331,0.117248,-0.194261,-0.814981,-0.050311,-0.246686,0.004494,-0.950520,-0.101718,-0.453623,-0.388920,0.046631,0.173738,-0.045393,0.653584,-0.874732,-0.195137,0.820515,0.217995,-0.710429,0.302717,0.156017,0.430334,-0.107489,-0.578837,0.204605,0.341951,0.781546,-0.374204,0.102679,0.457553,-0.018964,0.202898,0.050695', '3099221', '25821498', '27126336', '35173737');
