INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26703946', '岁月忽已暮', '剧情', '《岁月忽已暮》原著小说讲述了学霸之间在美国留学期间，发生的种种让人温暖和流泪的故事，从不同类型的留学生入手，讲述了不同性格的男生女生在留学期间的不同经历，贴近生活，被无数留学生喜爱。最励志暗恋故事，最温暖学霸题材，倾力打造最励志学霸纯美爱情。一经出版人气十分之高，几度登上销量排行榜。', '张子枫', '秦小珍', 3.1, 7047, 'tt5957694', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2606359859.jpg', 58.4, 29.6, 10.5, 1.2, 0.4, '0.276379,-0.381208,-0.368997,0.734746,0.616159,0.063001,0.799491,-0.049759,-0.818900,-0.463803,0.134796,0.483151,-0.490473,0.075289,0.518726,-0.490806,-0.139554,-0.628526,-0.153166,-0.325551,-0.032974,-0.313586,-0.222178,0.518290,-0.216760,-0.634345,0.966788,-0.194757,-0.621550,0.441884,0.028261,0.321787,-0.177174,0.165449,-0.196555,-0.131813,0.190105,0.640666,-0.316115,-0.100159,0.048601,-0.355719,-0.072501,-0.204833,-0.178844,-0.069953,0.933490,-0.079503,-0.064711,0.247839,0.909656,-0.013382,-0.376767,-0.177099,0.231830,0.326144,0.609384,0.483830,0.260709,0.067378,-0.317220,-0.315659,-0.626441,-0.025137,0.475304,0.181630,-0.240887,0.413163,-0.033634,0.131339,0.139864,-0.299428,0.161317,0.052496,0.460503,0.540306,0.153919,0.203001,-0.056581,0.764602,0.963850,0.220313,-0.364357,0.753483,-0.600828,-0.287777,-0.136122,-0.276863,-0.643143,0.357306,-0.001466,-0.022026,-0.155701,0.607433,-0.868695,0.247841,0.502507,-0.258994,0.394927,-0.405023,-0.250682,-0.676068,-0.744704,-0.315331,-0.087140,-0.333511,0.250846,-0.613389,1.579388,-0.943695,-0.053339,0.157167,-0.137866,-0.354325,0.790572,0.078024,-0.203804,-0.119683,0.207789,0.821242,-0.000950,-0.143934,-0.786225,0.403281,-0.227947,-0.405409,-0.578966,0.895396', '27602116', '25922902', '26790961', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26704137', '茉莉牌局', '剧情', '著名编剧艾伦·索金（Aaron Sorkin）即将转行做导演，而他导演的第一部电影是《茉莉的牌局》（Molly’s Game），该片根据真人真事创作，讲述了“扑克公主”茉莉·布鲁姆（Molly Bloom）的故事。茉莉·布鲁姆（Molly Bloom）年轻时专注滑雪，水平在世界上排在前列。然而在奥运会选拔中她不幸名落孙山，之后她决定在读法律学院之前给自己一年的假，于是就跑去洛杉矶当了女招待，结果迷上了开设赌局，凭借自己的聪明头脑，茉莉在八年间通过开设赌局赚了数百万美元。来她赌局的都是一些好莱坞巨星和富豪巨贾，包括本·阿弗莱克、莱奥纳多·迪卡普里奥等。《茉莉的牌局》将根据茉莉·布鲁姆本人2014年出版的回忆录改编，索尼公司将负责制作和发行。', '杰西卡·查斯坦', '艾伦·索金', 7.2, 42546, 'tt4209788', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2499148863.jpg', 0.3, 3.4, 44, 42, 10.2, '0.117992,0.208995,-0.482651,0.439850,0.091803,-0.380661,0.325499,0.017661,-0.313979,-0.189006,0.057077,0.935854,-0.396589,0.009405,0.407958,0.047551,-0.352582,-0.749368,-0.165020,-0.382219,0.059763,-0.627201,-0.132268,-0.156301,-0.044922,-0.464709,0.585642,-0.115912,-0.227137,0.366442,0.325135,-0.022777,0.128153,0.115866,-0.027401,0.131791,0.435216,-0.074518,-0.274742,0.441101,0.197373,-0.236056,-0.380368,-0.093672,0.476650,0.357904,0.575465,-0.246887,0.079274,0.073568,0.583142,-0.147045,-0.247161,-0.053077,0.260573,0.164933,0.315260,0.256905,-0.219938,0.095005,-0.202666,-0.370594,-0.599212,-0.092691,0.129678,0.061357,-0.780109,0.272669,-0.204429,0.061717,0.130324,-0.249652,0.071744,0.250321,0.425692,0.195685,0.224442,0.017792,-0.478163,0.747633,0.482420,0.222433,-0.164310,0.406679,0.017309,-0.424665,-0.155913,-0.322313,-0.404487,0.201535,0.321662,-0.352646,0.025400,-0.039757,-0.437253,-0.053172,-0.102735,-0.445272,0.098804,-0.323743,-0.139258,-0.755462,-0.172287,-0.120605,-0.082787,-0.493802,0.149277,-0.357810,0.916910,-0.752643,0.057656,0.664343,0.090058,-0.188115,0.827594,-0.023778,-0.017498,-0.173948,-0.097943,-0.024742,-0.062124,0.324844,0.082590,0.509659,0.256157,-0.538734,-0.212657,0.676534', '1870681', '1908036', '27602116', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26704590', '一念无明', '剧情', '患有躁郁症的阿东（余文乐 饰）因为当年误杀饱受痛症折磨的妈妈（金燕玲 饰）被判入住青山医院，康复出院后住在当陆港司机的爸爸黄大海（曾志伟 饰）的板间房里。黄大海试图关心儿子，但阿东却并不领情，原来阿东一直对爸爸当年抛弃家庭的事耿耿于怀。阿东重投社会，却遭到身边的朋友歧视，唯然他尝试平复自己，同时阿东也想尽方法希望找回当天谈到近乎订婚的Jenny（方皓玟 饰），没想到当找到Jenny时，却有着另一番滋味。', '曾志伟', '黄进', 7.9, 103167, 'tt6041030', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2452970761.jpg', 0.2, 1.6, 22.6, 56.1, 19.5, '-0.089816,0.001984,-0.561178,0.248525,0.020720,-0.549680,0.771762,0.220731,-0.521425,-0.536984,0.016738,0.275611,0.032869,0.593274,0.002336,-0.074049,-0.371724,-0.406634,0.241488,0.320522,-0.373359,-0.396243,0.013233,0.120310,-0.121363,-0.095991,0.406826,-0.007295,-0.157819,0.556285,0.270374,0.337128,0.111613,0.518886,0.129090,0.033881,-0.130098,0.361775,-0.617556,0.089878,0.451345,0.150444,0.086695,0.152264,0.080490,0.334228,0.349744,0.130879,-0.344918,-0.131866,0.276738,-0.015896,0.042427,-0.019717,0.213236,0.112999,0.316040,0.068193,-0.339278,-0.125870,0.160317,0.200511,-0.288938,0.198550,0.329406,-0.020107,-0.313476,0.188217,0.010918,0.142922,0.075098,-0.225801,0.097422,0.249153,0.171618,0.511283,-0.509898,0.301241,-0.402340,0.056142,0.490402,-0.316682,0.192073,0.196562,-0.125204,-0.048051,0.482472,-0.012374,-0.466436,0.133229,-0.147362,0.096870,-0.525857,-0.033766,0.041447,-0.210960,-0.295274,0.174516,-0.003784,-0.329156,-0.058850,-0.202453,-0.005489,-0.247167,-0.326186,-0.041749,-0.052839,-0.188233,0.409179,-0.639896,0.613238,0.199067,0.414558,-0.703189,0.515613,0.460295,-0.018644,-0.487046,-0.084568,0.512794,0.044767,0.196041,0.128907,-0.266259,0.013124,-0.062047,-0.193648,0.258494', '2122766', '1303485', '25858759', '1305703');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26704620', '屏住呼吸', '惊悚', '洛奇（简·莱维 Jane Levy 饰）、艾利克斯（迪兰·米内特 Dylan Minnette 饰）和摩尼（丹尼尔·祖瓦图 Daniel Zovatto 饰）是三名擅长“闯空门”的惯偷，这一次，他们将目标锁定在了一位盲眼的退伍老兵身上。老兵的女儿刚刚在一场车祸中丧生，老兵因此获得了巨额的赔偿金，洛奇希望能够拿着这笔钱，金盆洗手，带女儿远走高飞。三人潜入了老兵位于底特律的如同鬼宅一般的老房子中，没想到却就此打开了地狱的大门。老兵拥有着高于常人的嗅觉和听力，以及极为敏捷的行动力，很快就发现了三名不速之客的行踪。在他的枪口之下，洛奇一行人犹如瓮中之鳖，无处可逃。在紧张而又激烈的追逃之中，洛奇和艾利克斯误打误撞跌落到了地下室中，却因此发现了一个可怕的秘密。©豆瓣', '史蒂芬·朗', '费德·阿尔瓦雷兹', 7.2, 99848, 'tt4160708', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2373595901.jpg', 1.3, 5.5, 39.1, 42, 12.1, '0.450919,0.069696,-0.919541,0.644830,-0.241758,-0.345702,0.915023,0.003780,-0.619214,-0.155814,0.362676,0.879621,-0.112946,-0.118924,0.252838,-0.212756,-0.163760,-0.770636,-0.349999,-0.433102,-0.467616,-0.368750,-0.484820,-0.127576,-0.127832,-0.351639,0.303264,0.171568,-0.128405,0.663722,0.095665,0.250998,-0.110116,0.398661,-0.148730,0.103862,0.088986,-0.126822,0.016747,0.472859,-0.002556,-0.182639,-0.171336,0.162623,0.025051,0.476089,0.668578,-0.462513,-0.005435,0.041220,0.017918,-0.353529,-0.036196,0.180155,0.397905,0.000867,0.209641,-0.045367,-0.256288,0.075296,0.136885,-0.179901,-0.677792,-0.065838,0.098232,0.174029,-0.709297,0.350970,-0.180149,0.022703,0.144449,-0.284774,0.036056,0.114547,0.045967,0.456086,-0.174230,-0.163406,-0.625045,-0.019214,0.492884,-0.278797,-0.258438,0.163250,-0.098831,-0.562356,-0.173957,-0.205968,-0.471579,-0.083374,0.784157,0.237408,-0.106498,0.306754,-0.565344,-0.017751,-0.515882,-0.015185,-0.563928,-0.380724,-0.213344,-0.547315,-0.213185,-0.405948,-0.147140,0.427751,-0.116233,-0.106196,0.562951,-0.696967,0.175032,0.539114,0.341715,0.067664,0.486490,-0.434276,0.315470,0.116540,-0.091247,-0.034449,0.370563,0.522145,0.490944,0.616333,-0.288215,-0.150753,-0.267796,0.412547', '1805685', '1309069', '3111650', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26704621', '辣手保姆', '喜剧', '科尔（尤达·刘易斯 Judah Lewis 饰）是一个个性十分懦弱的男孩，在学校里备受欺凌，回到家中又得不到父母的重视，只有平日里常常来照看他的保姆比（萨玛拉·维文 Samara Weaving 饰）是他最信任和亲近的人，两人之间有着深厚而又惺惺相惜的友谊。科尔十分好奇比在自己睡着了之后会干些什么，于是在某夜偷偷溜下了床，躲在暗中窥视。让科尔感到震惊的是，比带了一群男男女女来到他家的客厅，玩起了真心话大冒险的游戏。随着时间的推移，这场轻佻火辣的游戏开始慢慢变味，突如其来的血腥屠杀让科尔明白，这并不是一场游戏，而比，也绝不是表面看上去的那么简单。©豆瓣', '犹大·刘易斯', '约瑟夫·麦克金提·尼彻', 6.7, 24942, 'tt4225622', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2500890954.jpg', 1.9, 9.6, 47.4, 31.5, 9.5, '0.609565,-0.104656,-0.834463,0.519251,-0.320120,-0.066935,1.000486,0.265530,-0.829958,-0.078386,0.144484,0.720413,-0.419822,0.110486,0.130970,-0.046138,-0.262896,-0.427123,-0.194894,-0.389125,-0.136169,-0.571747,-0.193827,-0.262315,-0.136234,-0.420034,0.283973,-0.000893,-0.271905,0.546156,0.414892,0.332177,0.206844,0.724401,-0.217821,-0.031453,-0.200542,0.085197,0.173952,-0.011378,0.154176,-0.082166,-0.261767,0.103988,0.086426,0.326673,0.550165,-0.123266,-0.227993,0.057322,0.343605,-0.214189,-0.231550,0.059068,0.482251,-0.155216,0.168280,0.021970,-0.194733,0.248624,0.096729,0.019308,-0.782148,0.313982,0.094989,0.292881,-0.645830,0.519710,0.000224,-0.255744,0.194507,-0.362145,0.152286,0.346288,0.221956,0.463992,0.130271,-0.128045,-0.594905,-0.098881,0.757052,0.112534,-0.068952,0.648915,-0.335969,-0.265932,0.002650,-0.354605,-0.525207,-0.255303,0.215864,-0.044368,-0.082141,0.193145,-0.580144,0.239279,0.009272,-0.303815,-0.000691,-0.870337,-0.045046,-0.652366,-0.420101,-0.826382,-0.311957,0.064612,-0.011692,-0.462772,0.668153,-1.169067,0.090921,0.597347,0.124069,-0.305960,0.546299,0.319461,0.008613,0.124138,-0.105606,0.122013,0.154717,0.057227,0.038151,0.633296,-0.051671,-0.096798,-0.531186,0.503816', '1308755', '1296370', '3059036', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26705107', '豆福传', '动画', '西汉武帝年间，淮南王刘安崇尚仙法，广集豆类练取仙丹，仙丹未炼成，豆子却幻化为人形有了生命，成为了“豆族”。 主人公豆福和刘安一样痴迷于仙术，但是苦修多年也未能得道成仙。青梅竹马的豆香及志同道合的好友皆怀疑仙术，劝其放弃，但是豆福一直苦苦坚持。一次机缘巧合，豆福在神经病院碰上了神经兮兮的神经豆，在神经豆的指点下，豆福的仙术突飞猛进，而修仙背后的阴谋，也开始逐渐浮出水面……', '陈佩斯', '邹燚', 5.7, 7965, 'tt7320156', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2494279975.jpg', 6.8, 26.5, 44.7, 17.8, 4.2, '-0.158390,0.126819,-0.353154,0.769221,0.225822,-0.225179,0.373617,0.216518,-0.350892,-0.077810,-0.105926,0.434668,-0.263755,-0.059228,-0.345321,-0.425481,0.135564,-0.547299,0.288715,-0.118975,-0.158479,-0.285569,-0.328979,0.019644,-0.459420,-0.778991,0.663825,0.363480,0.093822,0.294975,0.250512,-0.131253,0.076793,0.188069,-0.326954,-0.053027,0.024368,0.382912,0.030859,0.085078,0.073567,-0.566792,-0.061674,0.079854,-0.061588,0.075660,0.351747,-0.136328,0.068060,-0.268743,0.324272,0.023308,-0.232721,-0.122683,0.459386,0.323489,0.336280,-0.083430,0.054306,0.173979,0.180803,0.149239,-0.730488,-0.208674,0.171282,-0.017440,-0.470053,0.189129,0.297257,-0.127961,-0.241693,-0.459527,0.148323,0.393344,0.284313,0.297162,-0.443272,-0.070327,-0.588849,0.237796,0.391386,-0.023076,-0.225894,0.563607,-0.174142,-0.381861,0.084838,-0.450308,0.047489,-0.241927,0.074643,0.217564,-0.237408,0.464097,-0.256284,0.120245,-0.197410,0.219931,-0.007671,-0.147894,-0.175768,-0.212080,-0.193619,-0.364609,-0.114461,0.151306,0.258352,-0.489767,0.910410,-0.722264,0.244374,0.165156,-0.107940,-0.549924,0.740900,0.066412,-0.199977,-0.212170,-0.091922,0.254242,-0.123995,0.392298,0.200765,0.431261,0.069967,0.489356,-0.487877,0.269996', '27602116', '35262731', '24284209', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26705567', '征途', '动作', '故事发生在虚构的中原大陆。十国之中，南赵国与北燕国比邻而居。为了防御日益强大的北燕，南赵举办比武大会，选拔将才。消息传到偏僻的清源村，村民东一龙想成为家族的举旗人，代表清源村家族出赛，村民们却质疑他的资格，经过一番努力，一龙终于踏上了与武士楚魂的征途……', '刘宪华', '陈德森', 5.1, 22948, 'tt10508838', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2613925251.jpg', 12.9, 38, 36.4, 8.2, 4.5, '-0.049230,0.209414,-0.377468,0.644728,0.577127,0.251349,-0.193426,-0.054243,-0.894022,-0.127608,0.121011,0.745058,0.106633,0.138186,0.177249,-0.515565,-0.116587,-0.583355,0.016339,-0.365633,0.035277,-0.222428,0.225576,-0.355875,-0.015903,-0.293441,0.684619,0.463286,-0.532231,0.450074,0.057173,0.219067,-0.480027,0.168558,-0.316436,-0.229280,0.296704,0.148516,-0.703703,0.119968,-0.789539,0.066176,-0.589302,0.092715,0.337780,0.169337,0.344391,-0.494902,0.190307,-0.241859,0.131889,-0.067502,-0.173196,-0.041292,0.823357,0.215867,0.403480,0.887454,0.240843,-0.293121,-0.262332,-0.432047,-0.711263,0.094552,0.485190,0.174002,-0.443825,0.796268,0.238391,-0.300120,-0.117306,-0.178983,0.392174,0.906097,0.113841,-0.119000,-0.041407,-0.013269,-0.239179,0.124108,1.079294,-0.187538,-0.256440,-0.476308,0.363413,-0.426841,0.114924,-0.674478,-0.266736,0.045295,0.084863,-0.076169,0.228290,0.228863,-0.326163,-0.004341,-0.371984,-0.601578,0.641099,0.050412,0.015665,-0.635017,0.009528,-0.041358,-0.118149,0.003562,0.238098,-0.004825,0.694793,-0.731671,-0.014735,0.341444,0.644630,-0.670174,0.327385,0.050612,0.218306,-0.230876,-0.571681,0.105908,-0.139575,0.437933,-0.149085,-0.073687,-0.427721,-0.471938,-0.272323,0.127893', '25721544', '3230460', '1849026', '26852888');
