INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26707472', '明日的我与昨日的你约会', '剧情', '美术大学学生南山高寿与福寿爱美电车相遇，他鼓起勇气向女孩表白。在一起后，高寿慢慢发现两人原是旧识，而女孩身上，也隐藏着诸多秘密。', '福士苍汰', '三木孝浩', 7.7, 61353, 'tt5338222', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2390682054.jpg', 0.5, 3.8, 28.9, 42.8, 24, '0.097481,-0.535931,-0.718949,0.536140,-0.077801,-0.338740,0.668647,-0.107549,-0.887021,-0.152396,0.300181,0.679529,-0.395326,0.741445,0.414832,0.207641,-0.385948,-0.888338,0.005233,-0.591383,-0.546589,-0.725522,0.076032,0.355912,-0.057923,-0.379749,0.674505,-0.019373,-0.012188,0.806464,0.425528,-0.082524,-0.497453,0.358871,-0.526185,-0.080862,0.004194,0.126963,-0.304114,0.193228,-0.098441,-0.184909,-0.728326,-0.266624,-0.096135,-0.173654,0.757634,0.181003,0.047640,-0.201164,0.094045,0.207562,0.021166,-0.010122,0.596525,0.184286,0.521553,0.192650,0.232849,0.023028,-0.230569,0.059973,0.356641,0.192909,-0.043159,0.315985,-0.676553,0.630240,0.196493,-0.344625,0.194285,-0.615517,0.084071,0.033739,0.284797,-0.026306,-0.365329,0.055909,-0.256018,0.008235,0.480245,0.256248,0.267376,0.357005,0.006923,-0.263517,0.162187,0.253010,-0.537064,0.082789,-0.122177,0.285187,-0.188726,0.254617,-0.363621,-0.009231,-0.008149,0.207821,0.372463,-0.329009,-0.134423,-0.500791,-0.328307,-0.400558,-0.429369,-0.031256,-0.068130,-0.248602,1.048382,-0.992906,0.266576,0.807138,0.610841,-0.178574,0.987188,-0.256224,0.100887,-0.275928,-0.214767,0.131920,-0.088395,0.274526,-0.129042,0.449116,-0.393176,-0.037741,-0.495001,0.148577', '1306544', '25922902', '3445516', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26709258', '罗小黑战记', '动作', '在熙攘的人类世界里，很多妖精隐匿其中，他们与人类相安无事地生活着。猫妖罗小黑因为家园被破坏，开始了它的流浪之旅。这场旅途中惺惺相惜的妖精同类与和谐包容的人类伙伴相继出现，让小黑陷入了两难抉择，究竟何处才是真正的归属？', '山新', '木头', 8, 495177, 'tt10734928', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2568288336.jpg', 0.7, 3.3, 21.6, 42.2, 32.3, '0.393727,0.232008,-0.665929,0.381981,-0.146471,-0.054697,0.814303,-0.240326,-0.667673,0.148448,0.214425,0.758708,-0.023645,0.259483,0.328448,-0.167600,-0.231378,-0.648019,-0.287981,-0.148119,-0.418363,-0.048590,-0.695801,-0.118230,-0.365789,0.042116,1.026166,0.453910,-0.296240,0.201846,-0.099032,0.370659,-0.677473,0.463012,-0.170008,-0.073638,0.032735,0.186394,-0.402675,-0.086900,-0.236647,-0.030388,-0.113298,0.345837,-0.451764,-0.092279,1.201535,-1.025195,-0.222820,-0.444826,0.170537,-0.425264,-0.231180,0.054673,0.348326,-0.078292,0.248585,0.068080,0.202880,0.059450,-0.127052,0.155614,-0.670490,-0.005175,0.101274,0.327722,-0.260692,0.440904,0.536301,-0.112454,0.156628,-0.233548,0.270264,0.671662,0.865623,0.451370,-0.000469,-0.235857,-0.383357,-0.216984,1.028119,-0.210869,-0.536296,0.236566,-0.459870,-0.799675,-0.059395,-0.285978,-0.613068,-0.440083,0.281896,0.372456,-0.545128,0.846156,-1.217343,0.553767,-0.210258,-0.139010,-0.199949,-0.700870,-0.217870,-0.452176,-0.253572,-0.596044,-0.046154,-0.014199,0.149444,-0.296992,0.878595,-1.137128,0.269588,0.782253,0.320266,-0.281693,0.602901,-0.172493,0.335674,-0.374255,0.117100,0.370635,0.032392,0.272432,0.142611,0.047241,-0.091017,0.638659,-0.707409,0.653908', '4160441', '26759819', '26290398', '10581450');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26710112', '十年一品温如言', '剧情', '除非黄土白骨，守你百岁无忧，你是否遇见十年羁绊百年奉陪的那个人？十年前，寄养在江南水乡的温衡（任敏 饰）第一次被接回北方温家，命运的安排让她遇见了言希（丁禹兮 饰），这一遇见，便是十年纠缠。一个是低眉顺眼的温家女孩，一个是张扬跋扈的言家长孙，他们的人生道路不停交汇又分离，终于发现，两人心中所愿，不过是“永远在一起”。十年后的重逢，伴随着亲朋好友的陪伴与见证，似乎是命运的轮回，给这个“只羡温言不羡仙”的故事画上句点。', '丁禹兮', '赵非', 2.8, 45246, 'tt17023780', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2867299847.jpg', 68.6, 24.4, 5.8, 0.8, 0.4, '0.125146,0.048960,-0.416824,0.505616,-0.151103,-0.526462,0.631693,-0.054160,-0.509943,-0.118565,-0.052021,0.811467,-0.222850,0.565552,0.208375,-0.002170,0.119227,-0.855372,-0.117758,-0.369697,-0.266361,-0.210514,0.131321,-0.123648,0.045801,-0.134520,0.563840,0.115996,0.340626,0.457843,0.204323,0.083390,-0.297751,0.163746,-0.737128,0.066314,-0.326587,0.283395,-0.507410,0.051233,-0.220519,-0.469834,-0.133205,-0.116870,-0.246931,0.129419,0.563323,-0.228410,-0.262681,-0.092026,0.389493,-0.357326,-0.064312,0.062178,0.229694,-0.120027,0.064669,0.508119,-0.435130,-0.083016,-0.033244,0.016074,-0.531965,-0.124346,-0.004802,0.153508,-0.710145,0.562543,0.350446,-0.129659,-0.091001,-0.036197,0.271906,0.337269,0.224809,0.262680,-0.278854,-0.224035,-0.356939,0.294792,0.866933,0.018157,-0.198802,0.363123,0.102903,-0.240325,-0.080751,-0.048471,-0.693065,0.069288,-0.038776,0.047345,-0.154607,0.299360,-0.549517,-0.117656,-0.267441,0.180978,0.186619,-0.515758,-0.013239,-0.436626,-0.331675,-0.424606,-0.525515,0.390427,0.153647,-0.386570,0.555325,-0.673417,0.434620,0.277370,0.260758,-0.440762,0.957369,0.502905,0.312736,-0.145993,0.484377,0.443090,-0.095501,-0.039017,-0.051251,0.297855,0.032657,0.400610,-0.576533,0.398779', '30162520', '2080130', '3212120', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26710371', '酒会', '剧情', '珍妮特（克里斯汀·斯科特·托马斯 Kristin Scott Thomas 饰）在政府部门打拼了那么多年，总算坐上了卫生部部长的位子。为了庆祝晋升，她在家中设置了一场聚会，邀请好友们参加。玛莎（切莉·琼斯 Cherry Jones 饰）和金妮（艾米莉·莫迪默 Emily Mortimer 饰）是相恋多年的同性情人，金妮通过试管婴儿手术怀上了三胞胎，这让她和恋人都感到异常兴奋。聚会在尚且平和的气氛中进行着，在这个节骨眼上，珍妮特的丈夫比尔（蒂莫西·斯波 Timothy Spall 饰）忽然宣布，自己患上了不治之症，命不久矣。这一消息犹如一枚重磅炸弹让众人炸开了锅，与此同时，每个人隐藏在内心的秘密亦因为这枚炸弹制造的冲击而纷纷浮出水面。©豆瓣', '基里安·墨菲', '莎莉·波特', 7.3, 16900, 'tt5814592', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2435181930.jpg', 0.9, 5, 35.9, 44, 14.1, '0.063095,-0.114828,-0.723480,0.420263,-0.154894,-0.149162,0.598977,0.313344,-0.494502,-0.022360,0.212553,0.834896,-0.579131,0.319625,0.344904,-0.051271,-0.450384,-0.565819,0.113630,-0.285009,-0.161230,-0.387703,-0.288489,-0.373081,0.081525,-0.507010,0.346866,-0.212495,0.141242,0.424812,0.355252,0.419791,-0.037666,0.487323,0.072332,0.059570,0.362492,0.195377,-0.120940,0.215053,-0.160909,-0.335516,-0.000762,0.226468,0.239265,0.560176,0.501641,-0.175246,0.088705,-0.081525,0.115367,-0.271143,0.060385,0.159618,0.243711,0.048331,0.106514,0.292885,-0.437506,0.237618,0.363144,-0.178956,-0.567143,0.101053,0.045232,0.279597,-0.496967,0.443242,-0.200557,-0.048020,-0.084873,-0.028832,0.386908,0.497544,-0.044120,0.249441,-0.243412,-0.085044,-0.349738,0.171327,0.672132,-0.014308,-0.370330,0.345211,-0.282589,-0.300044,0.130433,0.011718,-0.325156,-0.197911,0.507442,0.006939,0.007711,0.348350,-0.357772,-0.114555,-0.250720,-0.188719,0.042773,-0.207553,-0.119384,-0.821407,-0.041566,-0.218204,-0.426497,-0.094688,-0.130604,-0.206222,0.652665,-0.743732,0.115028,0.204282,-0.100621,-0.226382,0.378770,0.143379,0.223774,-0.314214,0.010112,0.019197,-0.037649,0.232671,0.187305,0.334195,-0.163329,0.067007,-0.441368,0.398761', '11541282', '26259202', '30162520', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26710657', '芬妮的旅程', '剧情', '1943年法国维希政府时期，一群犹太儿童在儿童庇护所生活了几年后必须避开德国纳粹的逮捕逃往瑞士，为了避开逮捕不得不与他们信任的成年人分开。这一群犹太孩子踏上了一条一切靠自己的逃亡之旅。 本片根据真人真事《芬妮的回忆录》改编，真实刻画了二战时 期犹太儿童的处境，这群犹太儿童们面对着成年人都不知所措的艰险逃亡，又将如何？这群孩子是否能成功逃到瑞士呢？ ©海德文', '莱奥尼·西索德', '萝拉·多尔伦', 8.6, 35779, 'tt5038372', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2457733322.jpg', 0.2, 0.5, 10.4, 49, 40, '0.355993,-0.267061,-0.628839,0.431226,-0.102287,-0.383300,0.147789,-0.266837,-0.288814,-0.174540,0.284304,0.686774,0.178339,0.196066,0.088517,-0.088079,-0.557025,-0.583972,-0.346384,-0.086063,-0.393829,-0.397741,-0.295133,-0.185871,-0.266988,-0.272795,0.752588,0.133374,-0.087372,0.258456,0.094410,0.412962,-0.344203,-0.128624,-0.434225,0.001342,0.328549,-0.150620,-0.378194,0.277587,-0.093141,-0.177884,-0.337195,-0.015918,-0.079850,0.204512,0.905257,-0.314782,0.113390,-0.217036,0.399345,-0.507890,-0.336338,0.362383,0.294503,0.025120,0.132180,0.190196,-0.129330,0.209743,-0.113321,-0.087611,-0.549116,-0.127577,-0.068836,0.041391,-0.712552,0.053556,0.091319,0.165724,0.172737,-0.404771,-0.064318,0.827705,-0.036718,0.538783,-0.129061,0.120264,-0.591303,0.250382,0.990258,-0.116729,-0.553930,-0.009560,-0.146754,-0.303232,0.068372,-0.377744,-0.450615,-0.113672,0.342509,-0.202110,-0.587704,0.461255,-0.622211,-0.012023,-0.560000,-0.394925,0.002190,-0.268942,-0.143910,-0.633659,0.034640,-0.390475,-0.315424,-0.020029,0.107693,-0.234822,1.040058,-0.364536,0.225488,0.750978,0.233837,-0.610629,0.420292,0.046361,0.267574,-0.090160,-0.141981,0.553426,0.236333,0.285105,0.027340,0.192218,-0.197190,-0.066521,-0.326965,0.405418', '3811356', '2977870', '1306530', '34822138');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26711487', '决战食神', '剧情', '影片主要讲述了高天赐是广州一个小厨师，和来自法国拥有米芝莲三颗星荣誉的名厨安保罗，厨艺各有千秋，从一开始的争锋相对，到成为惺惺相惜的好友，并联手参加‘全球美食之王’大赛夺得冠军的故事。', '谢霆锋', '叶伟民', 4.6, 36132, 'tt6315750', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2417948347.jpg', 18, 42.1, 31.9, 5.6, 2.5, '-0.029186,0.212468,-0.799093,0.828391,0.207826,-0.108471,0.189889,0.235593,-0.302075,0.063684,0.072900,1.415351,-0.486129,0.190955,0.458177,-0.364467,0.309953,-0.619202,-0.002559,-0.411456,-0.239638,-0.519841,-0.197667,0.072952,-0.145700,-0.231672,0.594315,-0.073839,-0.695442,0.652116,0.568778,-0.147834,0.005346,0.188072,-0.276754,-0.436585,0.318541,0.198083,-0.819384,0.456101,-0.208534,0.100249,-0.164612,-0.057718,0.300617,0.010192,0.478360,-0.481371,0.232489,-0.153348,0.465518,-0.248726,-0.433770,-0.331076,0.467120,0.293300,-0.004113,0.152245,0.362836,0.368760,0.060797,-0.513801,-1.078005,0.077507,0.242867,-0.211873,-0.338021,0.560364,0.289476,0.003389,0.055979,-0.121854,0.444703,0.352509,0.040596,0.292677,0.305218,0.275633,-0.345704,0.451076,0.978255,0.215638,0.012926,0.093445,0.201977,-1.012665,0.018009,-0.647996,-0.102859,0.284279,0.358241,-0.028737,0.809743,0.198052,-0.884451,0.106226,0.056727,-0.572309,0.659055,-0.259571,0.216557,-0.600398,-0.173994,-0.253246,-0.179698,-0.070500,0.409802,-0.770186,1.549874,-1.144241,-0.031633,0.371331,0.334340,-0.421726,0.774128,0.007524,0.324986,-0.349386,-0.509800,0.256625,0.180686,0.091254,-0.285064,0.395211,-0.026763,-0.219172,-0.515317,0.428107', '27602116', '24284209', '1870681', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26712235', '我的妈呀', '剧情', '电影《我的妈呀》讲述了因姨妈过世，时隔20多年回到故土的姜思年，在丧礼上见到了感情疏离的亲生母亲李好。短暂相处，得知母亲患病已时日无多。于是放下过往心结，协助母亲完成年轻时许下的“愿望清单”的笑泪暖心喜剧。', '鲍起静', '李勇昌', 7, 4856, 'tt6405384', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2500041403.jpg', 0.4, 7.5, 43.8, 36.5, 11.9, '-0.071016,0.079099,-0.578872,0.265321,0.053847,-1.045347,0.712737,-0.181381,-0.696252,-0.501699,0.202365,0.824544,-0.177242,0.781746,0.122796,-0.237658,-0.380197,-0.733466,0.061924,-0.134651,-0.004519,-0.210953,0.158869,0.112624,-0.118445,-0.612471,0.392796,0.048958,0.293607,0.463342,0.054936,0.210481,-0.333640,0.085219,-0.063385,0.148751,-0.226115,0.552678,-0.933381,-0.113791,0.072799,0.026497,0.205688,-0.047817,-0.109944,0.252482,0.749426,0.039328,-0.470686,-0.142094,0.756336,-0.187554,0.128950,0.020997,0.117840,0.817562,-0.014051,0.544699,-0.678534,-0.294357,-0.608012,-0.481170,-0.213935,-0.060017,-0.029856,-0.155934,-0.671971,0.577304,-0.339962,0.152718,-0.030453,-0.634861,0.307527,0.610037,0.248116,0.812539,-0.251403,0.497619,0.044380,0.344107,0.754638,-0.395971,-0.053565,0.507399,-0.032041,-0.213652,0.425919,-0.419159,-0.349519,0.468131,-0.069762,0.096766,-0.098550,0.392756,-0.165747,-0.379166,-0.231199,0.232140,0.831308,-0.398511,-0.241929,-0.255824,-0.607445,-0.199563,-0.589436,-0.272932,-0.066083,-0.575522,0.722472,-0.456168,0.505804,-0.099214,0.208566,-0.461427,0.613797,0.456894,0.194438,-0.419331,0.694191,1.087283,-0.268135,-0.100356,0.148785,-0.540418,-0.372658,0.239288,-0.688458,0.181102', '35225859', '4728342', '1844413', '26331185');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26713504', '酒神小姐', '剧情', '老妓患淋病求医，遇上医生被菲律宾情妇刺伤，他们的私生子逃避警察追捕，她看着可怜，便把他带回家中。卖身不忘慈爱，布施自有尊严。随着镜头逐渐揭开其生活帷幔，观众也进入了南韩社会中、老年人的情色国度，主角普渡的不只欲海，还有老主顾好死的渴求。李在容秉承前作《挑情宝鉴》、《六美八阵图》（34 届）中一贯的身体关注，于大胆主题和冷静戏剧性中谋取平衡，把生活磨人的个体悲情和都市人的终极寂寞，一一渗入每刻每寸的画面经营中。各各心灵之蔽，没有观世音菩萨便似无法超脱，无尽恻然。南韩影后尹汝贞演技炉火纯青，将与李在容出席香港首场放映。', '尹汝贞', '李在容', 8.3, 24142, 'tt5628012', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2376084941.jpg', 0.2, 0.8, 14, 54.9, 30, '0.096569,0.155999,-0.332565,0.557445,-0.141485,0.152841,0.717026,0.016391,-0.278886,-0.065673,-0.030829,0.701873,-0.031505,0.174388,0.216872,-0.208876,-0.107216,-0.865149,-0.450029,0.083166,0.057097,-0.246701,-0.287809,-0.069725,-0.371321,-0.209766,0.579480,0.161030,-0.279522,0.263743,0.192391,0.267443,-0.411047,0.277084,-0.268444,-0.043506,-0.073630,-0.058787,-0.087578,0.048355,0.081575,-0.373155,-0.035037,0.194125,-0.022836,0.026643,0.589505,-0.297805,-0.017900,-0.204677,0.399760,-0.155435,-0.316630,0.346129,-0.154137,0.198447,0.334980,0.242398,-0.255918,0.124907,0.059691,-0.222443,-0.741894,-0.105408,0.259788,0.189024,-0.257092,0.351543,0.062662,-0.262457,-0.083458,0.016730,0.305750,-0.098032,0.493477,0.494731,-0.023667,-0.069446,-0.035812,0.512651,0.429197,-0.055292,-0.420620,0.243416,-0.351495,-0.296222,0.255202,-0.384174,-0.419720,-0.158155,0.063743,0.246132,-0.132899,0.484779,-0.393913,0.040316,-0.067316,-0.240256,-0.241884,-0.390112,0.060024,-0.474252,-0.392365,-0.455281,-0.078190,0.027346,0.295937,-0.215467,0.774951,-0.647098,0.180404,0.433629,0.308365,-0.320317,0.883860,-0.010811,0.096462,-0.062157,0.027973,0.254240,-0.089019,0.373222,0.075507,0.332118,-0.244341,0.268108,-0.192669,0.324915', '30162520', '27602116', '4301278', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26715617', '双生', '爱情', '电影《双生》讲述了艺术学校学生李品（刘昊然饰），在一次偶然的机遇下获得了一份为期一个月的兼职工作，工作内容是为马上迎来自己生日的女孩涛（陈都灵）画肖像画，为此他来到了一处偏僻的豪宅。素不相识的两位年轻人因此结缘，一段青春的邂逅就此展开，然而在朝夕相处的过程中，李品逐渐发现了这栋房子里似乎还隐藏着一些不为人知的秘密，而他与涛之间的关系也逐渐变得微妙起来。', '刘昊然', '金振成', 3.4, 14978, 'tt10098374', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554892284.jpg', 51.8, 32.6, 10.8, 2.8, 2, '0.268774,0.115678,-0.691976,0.855106,0.096267,-0.312906,0.661586,0.063846,-0.515308,-0.364215,0.243382,0.552823,-0.454088,0.385273,0.209212,-0.291320,-0.389623,-0.782111,-0.130523,-0.426866,-0.395720,-0.617397,-0.207955,-0.100702,-0.118029,-0.369375,0.592625,0.392691,-0.122350,0.333427,0.002457,0.001942,-0.190488,0.461750,-0.134963,-0.006879,0.149250,0.261468,-0.283258,0.134321,0.165443,-0.401734,-0.388976,0.072136,0.073082,0.472246,0.927569,0.136354,-0.415436,0.108593,0.474929,0.233936,-0.191892,-0.237637,0.490397,0.248909,0.206104,0.189758,-0.463585,0.082226,-0.154341,-0.447533,-0.362743,0.074868,0.025806,0.303553,-0.362867,0.678409,0.147471,-0.019200,0.105140,-0.404685,0.114330,0.454722,0.447932,0.404435,-0.003319,0.114461,-0.413813,0.195419,0.890223,0.044103,-0.022844,0.714457,-0.459280,-0.410887,-0.175407,0.153224,-0.429117,0.000563,0.398341,-0.128060,-0.045621,0.195399,-0.877667,0.032223,-0.088734,0.020908,0.040500,-0.384019,0.009746,-0.785280,-0.252885,-0.209033,-0.108109,0.027373,0.043739,-0.590541,0.781639,-0.807572,0.374045,0.506327,0.060376,-0.282396,0.660125,-0.152439,0.400370,-0.133462,-0.055816,-0.005384,-0.057047,0.338954,0.185040,0.411304,-0.253772,-0.130073,-0.423612,0.605803', '3041753', '3811356', '5403927', '5977789');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26715636', '地久天长', '剧情', '影片讲述患难与共的两个家庭因为一场有隐情的意外被迫疏远，他们在时代洪流下历尽伤痛与不安，人生起伏跌宕，最终选择面对真相，坦荡向前的故事。年轻的刘耀军和沈英明两家人本是挚友，两家儿子沈浩和刘星在郊外嬉戏中，耀军的儿子刘星意外身亡，此事彻底改变了两家人的命运。刘家夫妇远赴南方。多年后，容颜已老的他们再次相聚，隐藏的真相终将因为年轻一代人的坦荡而揭开。岁月流逝，生命滚滚向前……', '王景春', '王小帅', 8, 344747, 'tt9581076', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2550208359.jpg', 0.7, 3.1, 21.6, 46.6, 28, '0.063472,0.027926,-0.816315,0.451434,0.245320,-0.296644,0.886613,0.029138,-0.756755,-0.210771,0.139134,0.833630,-0.047049,0.325230,0.227294,-0.279442,-0.187213,-0.719295,-0.092786,-0.062075,-0.147716,-0.433909,-0.149662,-0.423967,-0.072108,0.012141,0.728910,0.560006,-0.188709,0.585209,0.243428,0.220104,-0.626863,0.371689,-0.064538,0.210929,0.003075,0.420784,-0.746945,-0.208857,0.042188,-0.313378,-0.436536,0.180226,-0.227708,0.392744,0.552146,-0.077424,-0.455435,-0.076400,0.122520,-0.458353,-0.117470,0.050668,0.342524,-0.023441,0.360892,0.607734,-0.018848,-0.488713,-0.190966,0.017672,-0.641775,0.060127,0.291491,0.135887,-0.498917,0.579552,0.193023,-0.161002,0.081730,-0.453419,0.145175,0.434451,0.617875,0.268328,-0.317003,-0.034680,-0.317532,0.176019,1.148685,0.182234,-0.502161,0.172443,-0.218920,-0.078659,-0.153313,-0.366022,-0.710289,0.118471,0.589255,0.194584,0.026649,0.712553,-0.300363,-0.073172,-0.298635,0.182339,0.159150,-0.513842,0.079764,-0.103703,-0.462024,-0.656580,-0.521665,-0.013604,0.143136,-0.300037,0.657459,-0.312784,0.256636,0.180111,0.003301,-0.746686,0.646012,0.192732,0.363709,-0.285899,0.222838,0.326670,-0.225046,-0.108780,0.022061,-0.012107,-0.359828,0.272807,-0.378901,0.160168', '25721544', '1294713', '4145476', '1765127');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26715845', '黑暗迷宫', '悬疑', '影片故事由一次旅途展开，七个互不相识的人，冥冥之中上了同一辆车。在车辆进入黑暗的隧道后，却永远开不到尽头。经过多种尝试，他们依然无法逃离。莫名出现的尸体，死而复生的故人以及突如其来的凶杀接踵而至。和这没有尽头的隧道一样恐怖的，是每个人在黑暗中逐渐暴露的人性……', '聂远', '温河', 5.2, 6912, 'tt9479806', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2537871355.jpg', 11.4, 35.5, 39.6, 11.4, 2.1, '0.385059,0.135180,-1.023056,0.816301,0.243216,-0.031403,1.469520,-0.145722,-0.814258,-0.114411,0.357075,0.713943,-0.303297,0.025443,0.026474,-0.251353,-0.304080,-0.531447,-0.461389,-0.242494,-0.782866,-0.320771,-0.310309,0.053296,-0.151459,-0.106657,0.811391,0.515005,-0.276721,0.371447,0.048123,0.113122,-0.615904,0.592987,-0.441162,0.107994,-0.020763,0.220508,-0.245101,-0.002304,-0.234837,-0.296973,-0.050056,0.033724,-0.502187,0.403811,0.694163,-0.539757,-0.174557,0.338011,0.351056,-0.164425,-0.333383,0.048181,0.165358,0.144159,0.302867,0.088489,-0.157561,-0.157176,-0.452199,0.235407,-0.966535,0.031417,-0.203516,0.522795,-0.442070,0.415104,0.338515,-0.283160,0.090943,-0.546990,0.276780,-0.090207,0.410569,0.164243,-0.219443,-0.197877,-0.730426,-0.221696,1.263070,0.161914,-0.728409,0.498663,-0.230055,-0.310948,-0.317506,-0.079347,-0.414662,0.189857,0.576434,0.446794,-0.480791,0.311853,-0.928708,0.302076,-0.268355,-0.273253,-0.223489,-0.423792,-0.321158,-0.718346,-0.079635,-0.473057,-0.362006,0.629377,-0.207494,-0.333423,0.304639,-0.852586,0.555140,0.467449,0.114460,-0.286385,0.975020,-0.072490,0.167649,-0.219848,0.092431,0.396248,0.069602,0.741755,0.270509,0.466597,-0.204340,0.344306,-0.887620,0.486908', '10733357', '1293515', '20380318', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26715965', '衣柜里的冒险王', '喜剧', '靠骗取游客钱财为生的印度街头小混混阿贾，一直努力攒钱想带母亲去巴黎，可惜母亲没能等到这一天便去世了。于是，身上只有100欧元的阿贾带着母亲的骨灰踏上巴黎穷游之旅。为了省去住宿费阿贾藏在宜家的衣柜里，不料阴差阳错被运到英国，而后辗转流落到西班牙、意大利、利比亚……一段精彩非凡的冒险之旅由此展开。', '丹努什', '肯·斯科特', 7, 10888, 'tt5371168', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2573630982.jpg', 1.5, 7.7, 43.1, 33.9, 13.8, '0.215025,0.100891,-0.787294,0.411735,0.073053,-0.855973,0.318712,-0.181661,-0.480772,-0.049202,0.149699,0.752091,0.171129,0.240025,0.366584,0.216946,-0.438329,-0.503988,-0.150803,-0.454558,-0.323285,-0.274359,-0.247496,0.019580,-0.463037,-0.007818,0.263609,0.437533,0.098216,0.615721,0.224184,0.243626,-0.176187,0.313518,-0.280866,0.213864,-0.046912,0.102491,-0.313701,0.415518,0.289929,-0.441918,-0.166119,-0.128702,0.249096,0.073725,0.935709,0.074262,0.432541,-0.163643,0.297899,0.067399,-0.108353,0.089774,0.185398,0.315821,0.413901,0.003551,-0.365301,-0.020404,0.302630,-0.321639,-0.247946,-0.058385,-0.046177,-0.226569,-0.616402,0.275802,-0.183731,0.046685,0.214583,-0.669600,0.165011,0.615547,0.097826,0.344892,-0.023311,0.097307,-0.525810,0.587058,0.672854,-0.266674,0.141788,0.217060,0.106805,-0.205809,0.565204,-0.622273,-0.266610,0.007477,0.449782,-0.085549,-0.126788,-0.005982,-0.763134,0.252922,-0.385821,-0.370060,0.206418,0.060318,-0.069140,-0.485249,0.036816,-0.112395,0.174349,0.412765,0.112423,-0.078839,0.468966,-0.368960,0.244655,0.854865,0.518957,-0.203259,0.565081,-0.390378,0.321072,0.039139,-0.017755,0.330877,-0.043693,0.619655,0.182297,0.057017,-0.109992,-0.036537,-0.493581,0.293968', '1303723', '1299433', '26469862', '1309194');
