INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26717012', '导火新闻线', '剧情', '电视剧《导火新闻线》原班人马拍摄电影版，更加入吴孟达，前主播方健仪等增加新鲜感。影片讲述囧报及闪报为了点击率的媒体斗争，却无意陷入了寻仇者闯入电视台用炸弹挟持人质，向政府高层请愿通过恢复二次申诉，作为媒体正邪两方是如何站在各自立场斗智斗勇，事态不断升级揭露出官商勾结等隐情，人质与寻仇者命悬一线......', '吴孟达', '方浤酌', 6.9, 6318, 'tt6090588', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2367720439.jpg', 2, 8.5, 43.9, 34.7, 10.9, '-0.282640,-0.103359,-0.170869,0.225318,0.630721,0.345210,0.400894,0.349946,-0.517747,-0.109901,0.332808,0.184208,-0.712671,-0.308879,0.038657,-0.688524,-0.694381,-0.723230,0.186184,0.090133,0.007358,-0.070901,0.043597,-0.185161,-0.296094,-0.021276,1.047204,0.023680,-0.714482,-0.059146,0.467011,0.240122,-0.503357,0.129815,0.220933,-0.258418,0.175850,-0.103534,-0.613623,0.306343,-0.024240,-0.443041,-0.313834,-0.141842,-0.081972,0.308299,0.497765,0.178835,-0.055754,0.119095,0.337306,-0.531391,-0.046929,0.251014,0.399787,0.127951,0.300490,0.091686,0.048116,0.218746,-0.358216,0.041274,-0.796971,-0.250326,0.043937,0.569372,-0.010415,0.162146,-0.223917,0.250348,-0.112605,0.007671,-0.119333,0.502641,0.417698,-0.064219,-0.070948,-0.384434,-0.390236,-0.032956,0.513556,0.054913,-0.011965,0.053035,0.325389,-0.346079,-0.117009,0.062404,-0.086206,-0.087662,0.576513,-0.362761,0.257327,0.691517,-0.463789,-0.138944,-0.075438,-0.398410,0.307667,-0.525313,0.132272,-0.942309,-0.052398,0.340235,0.137827,0.076984,0.383363,-0.268174,0.743172,-0.428717,-0.074385,0.621447,0.257361,-0.930555,0.361201,-0.027226,0.249039,-0.582504,0.071268,-0.297560,0.239969,0.342480,0.206475,-0.513826,-0.217481,-0.279841,-0.164103,-0.313879', '2369613', '26946510', '1322847', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26717795', '健忘村', '剧情', '《健忘村》的故事发生在一片世外桃源般的村落里，传说此地风水有帝王之相，石员外（曾志伟 饰）觊觎村中龙脉，企图与土匪联合屠村。有一天，一声惨叫打破了裕旺村的宁静，村民朱大饼意外中毒身亡，大饼的妻子秋蓉（舒淇 饰）成为了最大嫌疑人，这时“天虹真人”田贵（王千源 饰）手持神秘宝器“忘忧”路过村子。据说“忘忧”可以洗去人的记忆，控制人格。从此裕旺村变成了健忘村。荒诞爆笑，阴谋不断，其乐融融的世外桃源背后隐藏着一场血雨腥风。', '舒淇', '陈玉勋', 6.7, 90027, 'tt6461526', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2412370372.jpg', 2.5, 11.2, 45.1, 33.4, 7.7, '0.047231,0.023349,-0.279584,0.108887,0.180372,0.314489,0.688611,0.241709,-0.826008,-0.333066,0.289669,0.315343,-0.275785,0.205182,0.028468,-0.084642,-0.038418,-0.236279,-0.082437,-0.248912,-0.078385,-0.137292,-0.245590,-0.169945,0.037784,-0.443094,0.167456,0.505211,-0.313560,0.204869,0.059701,0.471556,-0.519293,0.070952,-0.188280,0.209712,0.076144,0.058699,-0.447768,0.025988,-0.475595,-0.030672,0.048098,-0.023194,-0.281970,0.136269,0.675367,-0.328779,-0.328341,-0.099770,0.289441,0.036474,-0.203917,-0.009600,0.423623,-0.239284,0.175506,0.199169,-0.186500,-0.369282,0.222803,-0.186198,-0.199174,0.080967,0.392433,0.274834,0.033988,0.303522,0.459733,-0.006908,-0.002719,-0.024157,0.510692,0.077707,0.629562,0.195186,0.042626,0.111818,-0.596392,0.443013,0.663352,-0.176009,-0.156136,0.213142,-0.114362,-0.260081,-0.044184,-0.272240,-0.195130,0.194553,0.359949,-0.078929,-0.125320,0.285714,-0.392633,0.055397,-0.039813,0.255159,0.126366,0.217279,-0.541688,-0.397469,-0.114635,0.233473,0.002005,0.012197,-0.127116,0.082188,0.515525,-0.270186,0.394639,0.398286,0.083616,0.047038,0.362263,-0.272250,-0.002502,-0.262250,-0.109718,0.194834,0.227757,0.385910,0.150723,-0.074732,-0.429313,0.004833,-0.110187,0.088573', '10508879', '10466639', '11501396', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26718282', '独自在夜晚的海边', '剧情', '某外国城市，来自韩国的女演员英熙，正因为和国内一个已婚男子的恋情而备受压力，她放弃了一切，甘受千夫所指以此表明心迹。他说会去找他，但她并不相信。在熟识的朋友家吃过饭，她去了海边。她认为朋友不会理解这段感情，但还是问道：“他会像我思念他一样思念我吗”韩国江陵。几个老朋友的聚会。起初气氛有点尴尬，喝了些酒之后，英熙想吓吓他们。她表现得冷漠又不近人情，但他们反而喜欢这样。酒终人散，英熙独自去了海滩，发泄重重心事似雾般消散。她想知道，爱在生命中到底有多重要？', '金敏喜', '洪常秀', 7.6, 47664, 'tt6412864', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2443574154.jpg', 0.9, 3.6, 30.7, 44.4, 20.4, '0.087113,-0.050794,-0.824397,0.448500,-0.211136,-0.064226,0.846901,0.089168,-0.325169,-0.114190,-0.178269,0.942885,0.083709,0.399371,-0.038647,0.290849,-0.242923,-0.392063,0.211504,-0.354404,0.100623,-0.344892,0.022042,-0.375697,-0.155468,0.093787,0.242190,0.048870,-0.206188,0.279327,0.220088,0.083189,0.281362,0.998556,0.000342,-0.035830,-0.186123,0.267435,-0.081940,-0.016974,0.278725,-0.191932,-0.199036,0.498284,0.134132,0.273587,0.221617,0.177828,-0.441244,0.110393,0.277708,-0.365103,0.160140,0.239845,0.197202,-0.275343,0.182896,0.006431,-0.155087,0.001656,-0.101836,0.283978,-0.316515,0.211634,-0.091844,0.044423,-0.629193,0.606419,0.046202,-0.196831,-0.041091,-0.200529,0.271477,0.168225,0.307798,0.147518,-0.021715,-0.101799,-0.557186,0.260622,0.981852,0.013570,-0.183491,0.503906,-0.487459,-0.202189,-0.042226,-0.076829,-0.377189,-0.061928,0.038873,-0.003310,-0.498818,0.070210,-0.059688,0.074069,0.030968,0.046286,-0.300986,-0.634883,0.101396,-0.107960,-0.280741,-0.482560,-0.345061,-0.274370,0.071821,-0.156678,0.673991,-0.600050,0.018247,0.960438,0.567842,-0.911736,0.572759,0.710695,-0.361356,-0.119129,0.072332,0.304255,-0.300245,0.009182,0.355132,0.264424,0.150263,0.095031,-0.264283,0.117654', '1292064', '1309116', '21447058', '26420626');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26718799', '官方机密', '剧情', '故事发生在2003年的英国，凯瑟琳（凯拉·奈特莉 Keira Knightley 饰）是服务于英国情报机构的政府通讯翻译官，某日，她收到了一封加密邮件，该邮件揭露了美国国安局串通英国政府，企图入侵伊拉克发动战争的阴谋。凯瑟琳过着人人羡慕的安稳生活，领着不菲的薪水，有着无量的前途。这封邮件让她陷入了纠结之中，究竟是视若无睹还是勇敢的站出来检举揭发，最终，正义感战胜了私欲，凯瑟琳和律师本（拉尔夫·费因斯 Ralph Fiennes 饰）联手将这封邮件公之于众，很快就引起了群情激奋。紧接着，凯瑟琳就因为违反了《国家机密法》而被指控为叛国罪。©豆瓣', '凯拉·奈特莉', '加文·胡德', 7.8, 16339, 'tt5431890', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2566591073.jpg', 0.5, 1.7, 25.9, 53.1, 18.9, '0.285911,0.121444,-0.531213,0.568609,0.081837,0.011594,0.337290,0.207000,-0.507076,0.017500,-0.039808,0.520812,-0.223749,0.068170,0.245652,-0.004192,-0.521953,-0.773910,-0.118011,-0.413072,-0.102570,-0.666775,-0.191381,-0.473628,0.008536,-0.506936,0.340224,-0.081319,-0.327307,0.135094,0.370872,0.522233,-0.179111,0.471209,0.078815,0.045110,0.224166,-0.203270,-0.229915,0.143469,0.103039,-0.504021,0.011069,0.330848,0.147764,0.317518,0.324525,-0.138769,-0.174509,-0.010197,0.591468,-0.523159,-0.118869,0.131462,0.322237,0.183380,-0.141598,0.398886,-0.293831,-0.122395,0.273461,0.093173,-0.728476,-0.187199,-0.172412,0.336676,-0.190827,0.400547,-0.607924,0.089846,-0.072977,-0.309342,0.318379,0.516477,0.177740,0.203274,0.091399,0.054070,-0.538446,0.132848,0.336504,-0.020209,-0.039699,-0.056050,-0.367865,-0.434732,0.246720,-0.108539,-0.324898,-0.038606,0.528023,-0.028887,0.032690,0.224927,-0.634173,-0.337723,-0.420298,-0.289894,-0.087251,-0.655082,-0.094530,-0.483062,-0.420695,-0.184776,-0.390075,0.087698,0.143658,-0.050284,0.755528,-0.680255,0.172723,0.624113,0.449608,-0.689197,0.499261,0.297652,-0.043600,0.216747,0.123236,-0.012258,0.326364,0.442227,0.042375,-0.039526,0.266060,-0.339245,-0.072657,0.246828', '1307442', '4301278', '25932086', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26718828', '勇往直前', '剧情', '本片根据“格拉尼特山高手”消防队英勇事迹改编。影片讲述在“格拉尼特山高手队”创建之初，队里既有失足青年也有人面临婚姻危机等各种生活问题。队长埃里克·马什却始终充满热情，督促队员刻苦训练。这支看似由失意者组成的团队也逐 步成为城镇的荣誉象征……然而这一切被突如其来的森林大火所打破。面对近在咫尺的灾难，作为尖兵部队的他们勇往直前，却在阻止火势蔓延时被困火海、命悬一线。整个团队的安危与荣誉也面临巨大考验。', '乔什·布洛林', '约瑟夫·科辛斯基', 8.3, 89742, 'tt3829920', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2506348908.jpg', 0.1, 0.9, 13.7, 52.6, 32.6, '-0.234843,-0.012933,-0.607898,0.432492,0.500866,0.107258,0.508999,0.101386,-0.498854,-0.326326,0.504612,0.440363,0.289605,-0.213766,0.329898,-0.595991,-0.394833,-0.542197,-0.145541,0.138584,-0.099661,-0.031729,-0.174571,-0.134800,-0.003447,-0.615414,1.141348,0.313959,-0.408056,0.288666,0.024458,0.467676,-0.244100,0.393144,0.243657,-0.189962,0.290938,-0.052899,-0.516995,0.141271,-0.502115,0.115534,-0.468038,0.011464,0.028752,0.306125,0.470003,-0.379604,-0.136859,-0.036566,0.040583,-0.773364,0.160742,-0.185669,0.588146,-0.163531,0.095340,0.326671,0.167491,0.045156,-0.485334,-0.496817,-0.855999,-0.204110,0.500883,0.001721,-0.630844,0.251480,0.075618,-0.016130,0.320570,0.210637,-0.196523,0.502085,0.476922,0.287128,-0.291852,-0.054734,-0.411405,-0.000122,0.708450,-0.382888,-0.602079,-0.112968,-0.287291,-0.346196,-0.201906,-0.464934,-0.350649,-0.040215,-0.159986,0.061800,0.199558,0.383228,-0.513082,0.316166,-0.354731,-0.451582,-0.058448,-0.692098,-0.173178,-0.670818,0.057130,0.078407,-0.358812,0.173765,-0.022972,0.080791,0.667243,-0.488382,0.283941,0.283031,-0.061163,-0.287652,0.341269,0.000210,0.306680,-0.353910,-0.045531,0.505824,0.113871,0.476259,-0.126108,0.079367,-0.022777,-0.100637,-0.111012,0.478029', '7051375', '3861846', '26375028', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26718836', '底特律', '剧情', '《拆弹部队》（The Hurt Locker）和《刺杀本拉登》（Zero Dark Thirty）女导演凯瑟琳·毕格罗（Kathryn Bigelow）即将和《拆弹部队》编剧马克·鲍尔（Mark Boal）再度合作，拍摄一部讲述1967年底特律黑人骚乱的电影。该片目前暂无片名，计划三月开始选角，今年夏天开机拍摄。1967年的底特律黑人骚乱是美国历史上破坏性最大的种族骚乱之一，起因是警察7月23日凌晨进入黑人区一家酒馆逮捕黑人。这次执法行动引发黑人不满，他们闻讯而来向警察投掷石块和砖头。后来警方增援到来，强行驱散黑人，但适得其反，黑人越聚越多最终引发波及全城的大规模骚动。这场骚乱持续了五天，造成43人死亡，许多建筑被毁、许多人受伤。骚乱还蔓延到伊利诺伊、北卡罗来纳、田纳西、马里兰州。这部电影计划在这场骚乱50周年，也就是2017年上映。', '约翰·博耶加', '凯瑟琳·毕格罗', 7.8, 20806, 'tt5390504', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2455077133.jpg', 0.7, 1.8, 22.4, 55, 20.1, '-0.182247,-0.278792,-0.488072,-0.159059,0.461047,0.260223,0.764998,-0.107610,-0.356457,-0.243260,0.305273,0.306754,-0.709638,-0.204860,0.352385,-0.449051,-0.592944,-0.556018,-0.179784,-0.180407,-0.167326,-0.216792,-0.226943,-0.575673,-0.017016,-0.616365,0.578914,0.454097,-0.477747,0.453609,0.192407,0.192240,-0.105566,0.433137,0.510384,0.038017,0.244827,-0.468312,-0.397039,0.257869,-0.325768,-0.586485,-0.297916,-0.008471,0.047514,0.678805,0.595913,0.273593,0.001659,-0.328216,0.463387,-0.544121,-0.409298,0.002144,0.909845,0.078007,0.080747,0.278309,-0.039268,-0.114709,-0.471517,-0.347594,-0.081836,0.530245,-0.095040,0.133565,-0.173246,0.182943,-0.267271,0.371294,-0.094202,-0.001916,0.144556,0.564079,0.380271,0.037943,0.068553,0.105153,-0.286941,0.217937,0.935931,-0.302563,-0.218750,-0.116222,0.049001,-0.426174,-0.166952,-0.169492,-0.211192,0.234355,0.396492,-0.301264,-0.016136,0.383554,-0.434492,0.145445,-0.254019,-0.759391,-0.127476,0.052020,0.044889,-1.403097,-0.097491,0.070265,0.035798,-0.054183,0.127074,0.079978,0.742345,-0.220917,0.190705,0.618913,0.508400,-0.212292,0.225345,-0.121410,0.185507,-0.073139,0.060110,0.012944,0.014241,0.270276,0.047955,0.108224,0.000451,-0.545597,0.149768,0.056334', '3003137', '34961898', '2369613', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26718838', '异星觉醒', '科幻', '大卫（杰克·吉伦哈尔 Jake Gyllenhaal 饰）、米兰达（丽贝卡·弗格森 Rebecca Ferguson 饰）、罗里（瑞安·雷诺兹 Ryan Reynolds 饰）、秀（真田广之 饰）和休（阿利安·巴克瑞 Ariyon Bakare 饰）是在同一艘太空船上工作的宇航员们。一次偶然之中，他们在火星上发现了一个尚未成熟的生命体。休将这个生命体带回了实验室，让大家没有想到的是，这个小小的细胞在外界的刺激之下竟然开始了飞速的成长。随着生命体的长大，事态的发展开始失去了控制，该生命体展现出了强大的攻击力和高超的智力，先后杀死了数名船员。不仅如此，大卫发现生命体似乎想随着飞船一起降落地球，而一旦它的阴谋得逞，地球上的人类势必将要面临灭顶之灾。©豆瓣', '杰克·吉伦哈尔', '丹尼尔·伊斯皮诺萨', 6.5, 144678, 'tt5442430', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2456571580.jpg', 2.8, 11.4, 50.6, 29.1, 6.1, '0.483017,0.198738,-0.904995,0.630240,-0.133037,-0.206437,0.848424,0.058160,-0.429876,-0.102452,0.188916,0.737845,-0.315827,0.144074,0.029050,-0.048907,-0.428025,-0.532596,0.056309,-0.071887,-0.693371,-0.496389,-0.407974,-0.228251,0.054302,-0.463808,0.711349,-0.019019,-0.202694,0.484423,-0.009328,0.357366,-0.013770,0.411859,-0.113900,0.150740,0.113592,-0.168178,-0.112052,0.238537,-0.105842,-0.125406,0.178725,0.252476,-0.133155,0.316027,0.738330,-0.469484,-0.035942,-0.368400,0.306249,-0.188884,0.024667,0.085267,0.438148,-0.061683,-0.129709,-0.079486,-0.094014,0.112677,0.208484,-0.001360,-0.833089,-0.067549,0.055720,0.197848,-0.487369,0.200811,0.071463,-0.046415,-0.107255,-0.213032,0.146934,0.449136,0.084703,0.277087,-0.144355,-0.068414,-0.599096,-0.008559,0.586213,-0.018127,-0.718983,0.344128,-0.046661,-0.424282,-0.451823,-0.284661,-0.391096,-0.109924,0.324947,0.383033,-0.163901,0.444656,-0.687381,0.183318,-0.444493,-0.169674,-0.187276,-0.179949,-0.083031,-0.649209,-0.189044,-0.531809,-0.317655,0.283658,-0.137674,-0.187320,0.758131,-0.716464,0.112719,0.628734,0.365904,-0.362171,0.412966,-0.228913,0.104898,-0.226344,0.024741,0.004369,-0.119952,0.207764,0.146205,0.469482,0.155882,0.065656,-0.339694,0.565536', '3005387', '26667010', '25928048', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26719781', '他和她的故事', '喜剧', '在一架飞机上，基雅（卡琳娜·卡普尔 Kareena Kapoor 饰）邂逅了名为卡比尔（阿琼·卡普尔 Arjun Kapoor 饰）的男子。让基雅感到意外的是，这个看上去铁骨铮铮的硬汉，竟然眼泪汪汪的害怕的簌簌发抖。原来，卡比尔害怕坐飞机，每次坐飞机的时候都是母亲安抚着他的情绪，然而故人已逝，卡比尔不禁触景生情。为了安慰卡比尔，基雅紧紧的握住了他的手，一段浪漫的恋情就此拉开序幕。没过多久，基雅和卡比尔就决定携手步入婚姻的殿堂，可是，他们在家庭里所扮演的角色却仿佛调了个个儿，基雅每日出门工作赚钱养家，而卡比尔则坐镇家中主持家务。他们的朋友和家人们会怎样看待这段逆转的关系呢？©豆瓣', '阿琼·卡普尔', 'R·巴尔基', 7.7, 6705, 'tt4744086', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2315574510.jpg', 0.5, 2.5, 27.7, 47.7, 21.6, '0.414677,-0.102080,-0.598618,0.401846,-0.155407,-0.468178,0.682992,0.243141,-0.360876,-0.376142,0.198055,0.699999,-0.220961,0.297098,0.379462,0.214247,-0.219861,-0.590610,-0.172058,-0.163350,-0.083013,-0.386652,-0.352732,-0.149003,-0.050984,-0.318231,0.277836,-0.108356,-0.051154,0.621218,0.380212,0.227619,-0.096874,0.328142,-0.085416,-0.235377,-0.044732,0.313184,-0.102329,-0.104644,0.053246,-0.163911,-0.118539,0.151295,-0.056787,0.466541,0.414009,-0.120898,0.047566,0.147124,0.206725,-0.420691,0.187294,0.081616,0.244112,-0.204359,0.306707,-0.048270,-0.286921,-0.124417,0.323978,-0.149037,-0.524795,0.094540,0.111037,0.102850,-0.876706,0.445473,-0.022321,-0.263240,0.094320,-0.268306,0.385217,0.483591,0.100494,0.678888,-0.262855,0.007491,-0.373914,0.340323,0.535142,0.046055,-0.122057,0.433804,-0.247059,-0.322901,0.128178,-0.203829,-0.536960,-0.169516,0.056613,0.059401,-0.155036,0.232242,-0.432603,0.073061,-0.199164,-0.106364,-0.143238,-0.536573,-0.033520,-0.412042,0.055163,-0.409498,-0.207387,0.012732,0.010181,-0.209847,0.585926,-0.697232,0.326256,0.427470,0.144014,-0.227202,0.633245,0.373139,0.314885,-0.090553,0.013113,0.241276,-0.153803,0.051555,0.123873,0.218531,-0.144939,0.103657,-0.269667,0.612020', '1299965', '3111650', '24698878', '1850797');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26720627', '报告老师！怪怪怪怪物！', '剧情', '《怪物》描述邓育凯饰演的好学生长期被班上风云人物三人组作弄，某天四个人意外发现吃人的人形小怪物，进而延伸出“霸凌”议题，此主题也是九把刀十多年前看完瑞典电影《邪恶》受到启发后，一直想探讨的主题。原本他想以1500万台币低成本拍成“霸凌伪纪录片”，后期转变成剧情特效片，不但在中影搭棚，也特地在西门钉封街拍动作戏，制作费提高到一亿台币，大部份成本投入特效制作。九把刀透露，原本电影设定走写实暴力路线，但自己和素人演员无法掌握，最后决定做自己走回黑色幽默风格。', '邓育凯', '九把刀', 6.7, 18840, 'tt6648404', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2460047543.jpg', 4.3, 10.8, 40.7, 32.3, 11.8, '-0.022778,-0.079295,-0.248104,0.449334,0.122720,0.048834,0.475199,0.106137,0.041788,-0.162467,0.179943,0.433005,-0.413075,-0.135543,0.250622,-0.310866,-0.551367,-0.437589,0.031092,-0.139550,0.007623,-0.224673,-0.050496,-0.254443,-0.089605,-0.255278,0.567579,-0.021533,-0.560483,-0.039494,0.260044,-0.129727,-0.132923,-0.013219,0.202399,0.112539,-0.161367,-0.234261,-0.080334,0.366364,0.049167,-0.171584,-0.184794,-0.072215,0.120101,0.332261,0.636628,0.033470,-0.129380,0.122285,0.392988,-0.087831,-0.274774,0.025059,0.096713,0.201783,0.572513,-0.179867,-0.028288,0.253486,0.021875,-0.428529,-0.681699,-0.018997,-0.123670,-0.159714,-0.307310,0.286884,0.160270,0.148579,0.096102,-0.424590,-0.096696,0.002309,0.725208,0.211797,0.109360,0.037755,-0.189028,0.567748,0.394872,-0.068695,-0.338952,0.484846,0.192334,-0.419797,-0.401536,-0.486844,0.228889,0.144550,0.224365,0.052152,-0.154224,-0.198788,-0.416483,-0.022896,0.095496,-0.288315,-0.112926,-0.302503,-0.116912,-0.840533,-0.140743,-0.157039,-0.078530,-0.180297,0.111731,-0.498828,0.534605,-0.293896,0.005578,0.252692,0.217448,-0.502177,0.656423,-0.249322,-0.409137,-0.124934,-0.274105,-0.055044,-0.218313,0.367343,0.405725,0.196940,-0.057685,-0.387187,-0.319406,0.312928', '26275494', '3318306', '1322847', '25918677');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26721322', '龙拳小子', '喜剧', '影片讲述了从小在美国长大的林秋楠（林秋楠 饰）带着“超级英雄梦”回到中国，和舅舅袁来（刘芮麟 饰）共同生活并一直相信自己可以照顾好“脆弱舅舅”。但他独特的思维方式和一身的功夫反而给自己的校园生活和舅舅的恋情添乱。他又在不知觉中卷入一桩国际罪案，一场惊心动魄的对决难以避免 ……', '刘芮麟', '陶声', 4.5, 2843, 'tt6150988', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2369079478.jpg', 37.6, 24.5, 21, 9.2, 7.7, '-0.103193,-0.005846,-0.600959,0.737759,-0.101485,-0.054785,0.809922,0.245349,-0.582302,-0.324645,-0.070975,0.937984,0.010052,0.139359,0.186989,-0.083780,-0.267735,-0.799344,-0.000185,0.325765,-0.117333,-0.483827,-0.126304,-0.178340,0.000911,-0.378412,0.536960,-0.075996,-0.448439,0.521815,0.208487,-0.059062,-0.154198,0.463949,-0.336118,0.010879,-0.102271,0.430040,-0.392987,0.134008,0.291679,-0.101175,-0.020583,0.229307,-0.038587,0.009884,0.656035,-0.142694,-0.157487,0.078501,0.275192,-0.280703,-0.130151,0.098654,0.030386,-0.019361,0.496826,0.236583,-0.111143,0.218822,-0.029780,-0.252479,-0.820958,-0.007113,0.326745,0.047992,-0.725357,0.832217,0.193409,-0.192706,0.019745,-0.220825,0.201770,0.422885,0.319601,0.524796,-0.379977,0.213758,-0.439830,0.390942,0.780579,-0.129590,-0.080906,0.552171,-0.162457,-0.364596,-0.257405,-0.331370,-0.574765,-0.020430,0.153942,-0.222968,-0.476291,0.419457,-0.696155,0.104359,0.061373,-0.195161,-0.149245,-0.706144,0.406590,-0.327735,-0.324793,-0.947540,-0.378849,0.126093,0.066277,-0.230862,0.661719,-0.865200,0.148027,0.425405,0.149854,-0.502668,0.652400,0.425215,0.154438,-0.302875,0.002881,0.179396,-0.166806,0.038603,0.202271,0.406463,0.054013,0.049988,-0.547066,0.389735', '24756472', '30162520', '1301516', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26721478', '鲁滨逊漂流记', '喜剧', '故事开始于一座孤岛之上，在这里，居住着一群动物们，其中，十分勇敢对于新鲜事物有着无尽好奇心的鹦鹉麦克（大卫·霍华德·桑顿 David Howard Thornton 配音）对小岛外面的世界十分的向往，可是其他的动物们却并不这么想，小岛是他们的安乐窝，小岛以外对于他们来说就是致命的危险地带。一天，一艘遇难的商船冲向了小岛，为小岛带来了他们唯一的一位人类客人鲁滨逊（马提亚斯·施维赫夫 Matthias Schweighöfer 配音），鹦鹉最先跟鲁滨逊成为了朋友。起初，鲁滨逊因为和其他动物们无法沟通导致了双方产生了小小的误会，但很快，他们之间就产生了真挚的友谊。©豆瓣', '马提亚斯·施维赫夫', '文森特·凯斯特鲁特', 5.7, 6341, 'tt4731008', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2384412081.jpg', 6.3, 27.3, 45.5, 15.8, 5.2, '0.558205,-0.198482,-0.884916,0.839226,-0.077250,0.231173,1.004220,-0.043381,-0.687085,-0.259937,-0.072983,0.941220,-0.106230,0.310342,-0.038492,-0.180236,-0.316763,-0.319047,-0.087935,-0.365567,-0.393473,-0.409773,-0.320510,-0.509376,-0.523459,-0.212799,0.678628,0.146496,-0.204643,0.391546,-0.051794,0.430306,-0.113663,0.511094,-0.393426,-0.082362,0.215131,-0.116146,-0.292014,0.018779,-0.238711,0.369359,-0.017967,0.611180,-0.182111,0.117736,0.731805,-0.599659,-0.434599,-0.281470,-0.088114,-0.147521,0.439557,0.010680,0.572370,-0.390664,0.317562,0.095083,-0.082420,0.069636,0.214863,-0.107952,-0.399011,0.090612,-0.041682,0.322176,-0.318521,0.192943,0.245489,-0.411074,0.000427,-0.100079,0.234513,0.291289,0.419282,0.271347,-0.161807,-0.019814,-0.464583,-0.270221,0.841376,0.170371,-0.338167,0.430945,-0.628025,-0.481051,-0.219272,-0.154977,-0.324015,-0.036438,0.233721,0.200320,-0.268046,0.277878,-0.978807,0.367955,0.096427,-0.471837,-0.167817,-0.641717,-0.111627,-0.804081,0.169497,-0.446507,-0.333223,0.063307,0.205287,0.007329,1.114588,-0.834495,0.241646,0.680931,0.302847,-0.430850,0.859099,0.006976,-0.046292,-0.193667,0.062184,0.108537,-0.166786,0.075211,0.168775,0.351295,-0.045071,-0.158306,-0.181237,0.701737', '2053515', '3055049', '30162520', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26721644', '鬼故事', '剧情', '英国知名舞台剧《鬼故事》将被搬上大银幕，新片主演马丁·弗瑞曼、乔治·麦凯、安迪·尼曼等。尼曼继续出演他在剧中的角色古德曼教授。古德曼是一位心理治疗师，从不相信鬼怪之说；然而三个病人的“见鬼实录”让他对原有信念产生了怀疑。作为最受欢迎的惊悚戏剧之一，该剧曾在全球多地进行巡演。', '安迪·尼曼', '杰瑞米·德桑', 7.2, 27004, 'tt5516328', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2528217984.jpg', 1, 5.4, 39.1, 42.6, 12, '0.050821,-0.123668,-0.749306,0.782029,0.059256,0.152414,0.798083,-0.149379,-0.287899,-0.453032,0.169699,1.002751,-0.515806,0.126269,0.117140,-0.189083,-0.031032,-0.465169,-0.272858,0.100572,0.208462,-0.521868,-0.216413,-0.041735,-0.271079,-0.412320,0.510542,-0.051488,-0.373760,0.195504,0.737201,0.339882,0.172015,0.044649,0.195147,0.043765,0.390628,-0.485301,-0.258154,0.263666,0.511756,-0.294182,-0.074789,0.275365,-0.274254,0.017618,0.540118,-0.127465,-0.207701,0.311083,0.707287,-0.500355,-0.007116,0.173143,0.160849,0.100569,0.151164,0.275740,0.026807,0.293576,-0.024343,-0.050153,-0.969805,0.039188,0.046676,0.575192,-0.439572,0.187377,-0.270799,-0.242337,0.113593,-0.150107,0.246208,-0.163800,0.683448,0.395549,0.128249,0.217563,0.002341,0.466892,0.359058,0.031896,-0.371336,0.501632,-0.106549,-0.560009,0.011120,-0.157384,-0.595961,0.286106,0.174592,-0.412738,-0.047374,0.089061,-0.387109,-0.091733,0.011165,-0.539012,-0.076118,-0.312796,0.186888,-0.957534,-0.264393,-0.065193,0.160708,-0.387411,0.151893,-0.589574,1.014587,-0.715356,0.286880,0.576104,0.076232,-0.615800,0.646351,0.312291,-0.125030,-0.021545,-0.041776,0.273103,0.045445,-0.047498,-0.062385,0.383399,0.237771,-0.456756,-0.232010,0.410794', '3318306', '27602116', '2027945', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26721646', '柯莱特', '剧情', '故事发生在19世纪末的英国，单纯美丽的女孩柯莱特（凯拉·奈特莉 Keira Knightley 饰）嫁给了身为作家的男子威力（多米尼克·威斯特 Dominic West 饰）。在丈夫的支持和鼓励之下，柯莱特拿起了笔，开始以自己学生时代的经历为蓝本进行创作，并且最终完成了她的第一本小说。让柯莱特没有想到的是，威力竟然将小说冠上了自己的名字出版，这部小说一经出版就在文坛中引起了轰动，威力一举成名。自此之后，威力发现了妻子身上出色的文学天赋，于是开始逼迫她继续做自己的枪手，当柯莱特忍无可忍拒绝了丈夫的无理要求后，威力竟然暴力相向。威力有了外遇，而柯莱特也发现，自己虽然身为女性，但是对女性有着强烈的吸引力。©豆瓣', '凯拉·奈特莉', '沃什·韦斯特摩兰', 7.5, 16250, 'tt5437928', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2539643023.jpg', 0.4, 2.2, 34, 47.1, 16.3, '0.235008,0.249500,-0.733496,0.872163,-0.060815,0.029090,0.719000,-0.021989,-0.359669,-0.236250,0.090922,0.719730,-0.419507,0.274204,0.247693,-0.070922,-0.172628,-0.878503,0.328505,-0.166044,-0.309831,-0.671699,-0.304267,-0.335908,-0.190333,-0.726767,0.422599,0.133753,-0.379603,0.116288,0.389713,0.296835,0.339659,0.697433,0.043717,0.233163,0.138132,-0.179363,-0.069327,0.574441,0.312243,-0.436675,-0.112170,0.463129,-0.057376,0.220578,0.690739,-0.380404,-0.078963,-0.054290,0.896059,-0.122325,0.002628,0.097790,0.362036,0.115068,0.086713,-0.063388,0.074523,0.007357,0.111211,-0.259534,-0.754750,0.039314,0.311768,-0.132407,-0.679221,0.184906,-0.426318,-0.014309,-0.098548,-0.266737,0.120705,0.034852,0.485135,0.324020,-0.068593,0.392069,-0.256194,0.195842,0.368957,-0.087901,-0.522241,0.436665,-0.352978,-0.515841,-0.326530,-0.484460,-0.377089,-0.012419,0.258199,0.252851,0.145765,0.069996,-0.431601,-0.173386,-0.076026,-0.073934,0.105911,-0.190860,-0.205515,-0.346405,-0.302077,-0.421567,-0.259979,-0.306059,-0.081410,-0.671441,1.226410,-0.701889,0.021061,0.429055,0.399704,-0.388696,0.706396,-0.098664,-0.102541,0.316359,-0.055902,0.223998,0.049189,0.037749,0.164471,0.371009,0.499584,-0.267287,0.201930,0.916945', '27602116', '24284209', '26348103', '1303263');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26722224', '匿名者', '科幻', '故事发生在并不遥远的未来2030年，为了降低高居不下的犯罪率，所有出生的婴儿都被政府强制性的在瞳孔里植入了晶片，虽然这一做法有效了防止了犯罪事件的发生，但这也意味着，所有的人终生都生活在政府的监视之下，毫无隐私可言。在这样一个时代里，出现了一批黑客，他们能够通过高超的技术远程修改晶片所收录的影像，这群人被大家称为“匿名者”。一级首都发生的多起谋杀案让当地居民陷入了恐慌之中，负责调查此案的侦探萨尔（克里夫·欧文 Clive Owen 饰）发现一位神秘的匿名者成员（阿曼达·塞弗里德 Amanda Seyfried 饰）和这起案件有着千丝万缕的关联。©豆瓣', '克里夫·欧文', '安德鲁·尼科尔', 6.4, 8641, 'tt5397194', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2519789189.jpg', 1.8, 12.3, 54.6, 24.7, 6.5, '0.517883,0.116482,-0.817044,0.704897,-0.024350,0.286729,0.771560,-0.104445,-0.752862,-0.418304,0.170823,0.660741,-0.208832,-0.036280,0.169881,-0.270461,-0.384189,-0.730552,-0.140716,-0.540563,-0.489297,-0.604976,-0.416478,-0.267145,-0.204859,-0.439006,0.624842,0.107047,-0.472734,0.078984,0.111018,0.509075,-0.236304,0.337892,0.037445,-0.134188,0.224831,-0.203376,-0.087007,0.239222,-0.127791,-0.278412,0.165450,0.109854,0.023654,0.378597,0.656984,-0.468709,-0.501291,0.023943,0.556113,-0.316404,-0.184919,0.085950,0.477211,0.130133,0.027433,0.333267,-0.224034,0.129958,0.178040,0.122350,-1.148909,-0.224886,0.251305,0.580629,-0.326824,0.500081,-0.159564,0.005261,-0.115212,-0.313180,0.305346,0.487460,0.312106,0.279948,-0.112247,-0.039458,-0.716917,0.080220,0.688210,-0.147497,-0.542955,-0.000345,-0.430747,-0.611192,-0.277414,-0.140295,-0.297027,0.120958,0.400732,0.160203,-0.232158,0.608320,-0.678918,0.046714,-0.082055,-0.449636,-0.189489,-0.363237,-0.105790,-0.682138,-0.190227,-0.438459,-0.450201,0.081304,0.236247,-0.470776,0.774651,-0.883646,0.220468,0.639526,0.204844,-0.442413,0.475619,-0.006005,0.373795,-0.015034,-0.370492,-0.018826,0.449611,0.602998,-0.032495,0.266596,0.036920,-0.375447,-0.225441,0.193222', '1793491', '1874704', '25932086', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26724235', '再见瓦城', '剧情', '忧郁的热带，女孩莲青（吴可熙 饰）遇见少年阿国（柯震东 饰），都是从缅甸跋涉至曼谷的偷渡客，他们连边界都穿过了，却迟迟等不到一纸身分。想新生他方为人，如今却飘荡城市边缘成鬼，日子剩下反覆的劳动，小吃店、成衣厂、工厂熔炉，无处可洩的闷热，高烧一般的爱。当连呐喊也瘖哑，吸毒、残身，贩卖身体⋯⋯。一切不是旧，只是逐渐败坏，不是没有期望，而是竟然还有期望。探底了，又还不够底，少年少女眼神纯真，身强志坚，就此一步一步通往无光的所在。银幕再见柯震东，赵德胤续《冰毒》后持续以影像射击，大量真实移工入镜，长镜头视野，近距离人生，写实影像锤打底层生活成炽烫影像，触目都生烟，偏又有爱情浇铸其中，卑微又仰望，炼成钢，更成绕肠柔，所求无非一点馀温，经过便都是馀生。', '柯震东', '赵德胤', 6.9, 8567, 'tt5974402', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2376837451.jpg', 2.3, 6.5, 44.2, 37.6, 9.5, '-0.374485,-0.034659,-0.527196,0.379323,0.130373,-0.196411,0.699855,0.156982,-0.169191,-0.241636,0.136375,0.064427,-0.069799,0.057912,-0.257877,-0.158025,-0.227451,-0.393647,-0.144109,-0.314049,-0.221990,-0.131684,-0.159424,-0.005216,-0.160793,-0.258273,0.629111,0.340739,-0.267833,0.023291,0.088220,-0.172455,-0.016220,0.431278,-0.312875,-0.198509,-0.126555,0.188400,-0.081886,-0.191581,-0.128928,-0.370070,-0.171221,-0.080014,-0.061980,0.546906,0.635804,-0.164877,-0.060880,-0.004472,0.147744,0.035175,-0.036128,0.033291,0.256280,-0.219302,0.061625,-0.078850,-0.164260,-0.113437,0.061236,0.109722,-0.451318,0.102001,0.194229,0.206368,-0.205350,0.398299,-0.020932,-0.222259,0.061156,-0.222806,0.059386,-0.277158,0.245251,0.495253,-0.039244,-0.081851,-0.288377,0.360281,0.336090,0.117357,-0.483775,0.593164,-0.371045,-0.593432,-0.005376,-0.113226,-0.281052,-0.103285,0.077374,0.276440,-0.150983,0.339374,-0.376823,0.264090,-0.134233,-0.149137,0.148247,-0.289999,-0.160351,-0.208733,0.049998,-0.196422,-0.096927,0.285569,-0.028305,0.002027,0.259088,-0.150353,0.244291,0.589968,0.167105,-0.274461,0.589141,-0.052293,-0.247195,-0.010629,-0.002692,0.400207,0.086227,0.451182,0.102199,0.217831,-0.109375,0.321672,-0.234631,0.352327', '21619567', '1307991', '3534824', '1417428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26724807', '24小时：末路重生', '动作', '永远不要点燃一个职业杀手的怒火，就算面临重重包围，他也能杀个片甲不留！杀手特拉维斯（伊桑∙霍克 饰）得知了犯罪组织“红山”的惊天阴谋，他在国际刑警“琳”（许晴 饰）的影响下，决定重整目标、直捣红山“老巢”。可是，特拉维斯只能存活24个小时，他能否阻止邪恶计划、救赎自我？时间愈发紧迫了……', '伊桑·霍克', '布莱恩·斯莫兹', 5.1, 7659, 'tt5442456', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2510056332.jpg', 8.5, 39.4, 43.6, 7.5, 1.1, '-0.196997,0.191358,-0.536658,0.232622,-0.050499,0.019302,0.038146,-0.137279,-0.326935,0.007171,0.300219,0.301763,0.312482,-0.095476,0.353935,-0.133449,-0.458493,-0.516600,0.344040,-0.324921,-0.226267,-0.535042,-0.280057,-0.322580,0.529977,-0.080389,0.649024,0.227794,-0.083523,-0.053077,0.243829,0.620160,0.143269,0.461249,0.132072,-0.279352,0.162045,-0.685880,-0.259324,0.476732,-0.046107,-0.032078,-0.138575,0.408692,-0.088190,0.364279,0.403149,-0.463130,-0.110139,-0.160923,0.119919,-0.592260,-0.084623,0.077780,0.166937,-0.649928,0.016869,0.357151,-0.261814,-0.284280,0.015872,-0.072636,-0.824880,-0.053187,0.160427,0.079020,-0.550543,0.093164,0.049042,0.302924,0.080791,0.289543,-0.065849,0.457757,0.167835,0.109411,-0.169886,-0.173418,-0.571879,0.095235,0.353509,-0.181933,-0.118699,-0.101535,-0.008906,-0.087207,-0.194032,-0.172930,-0.206905,-0.428989,0.610192,0.000192,-0.137382,0.303752,-0.259280,-0.175834,-0.674428,0.118649,-0.039168,-0.502804,0.087278,-0.311355,-0.231379,0.406152,-0.130113,0.279403,0.112787,0.042839,0.337441,-0.515286,-0.148547,0.704148,0.222157,-0.248491,-0.014858,0.432079,-0.014229,-0.407736,-0.016088,0.374448,0.014638,0.373237,0.328005,0.065425,0.179047,-0.352663,-0.300716,0.294730', '1307442', '1293605', '1292573', '25662337');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26724989', '圣鹿之死', '剧情', '史蒂芬（科林·法瑞尔 饰）是名优秀的心脏科权威，和同为医生的太太安娜（妮可·基德曼 饰）育有两个孩子，家庭十分富裕美满，史蒂芬最近和一名十六岁的少年马丁成为好友，两人无话不谈，十分亲近宛如父子，也时常邀请他来家裡作客，希望常常看起来有心事的马丁能跟孩子们成为朋友，让他打起精神来。然而，理当和睦的日常生活，却因为马丁的走入而产生变卦，一连串怪事和找不出病因的疾病接连发生，一股说不出的诡谲及恐惧开始笼罩着这一家，究竟马丁的真面目是什么？史蒂芬该如何挽救这逐渐被侵蚀的家庭生活？', '妮可·基德曼', '欧格斯·兰斯莫斯', 6.8, 25193, 'tt5715874', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2460265520.jpg', 2.6, 9.4, 42.6, 35.7, 9.6, '0.213619,-0.393650,-0.569296,0.485307,-0.287331,-0.152381,0.923225,0.227006,-0.776458,-0.535179,0.049835,1.070174,-0.332759,0.518456,0.267880,-0.027721,0.090332,-0.511806,0.221660,-0.051161,-0.022927,-0.362033,-0.256982,-0.153549,0.002432,-0.309240,0.369291,0.042415,-0.067054,0.469406,0.155536,0.604380,-0.017222,0.306324,-0.142147,0.067844,0.029801,0.232147,-0.392001,0.003029,0.196156,0.041586,-0.293463,0.123287,-0.079685,0.319482,0.478403,-0.007237,-0.215144,0.033702,0.466605,-0.198838,-0.027620,0.257664,0.150573,0.053489,0.193553,0.186870,-0.022269,-0.209802,-0.036734,0.029568,-0.757727,0.412740,0.268258,0.267921,-0.585187,0.243633,-0.035058,-0.471906,0.103112,-0.220563,0.248357,0.566490,-0.058101,0.586089,-0.216670,0.242332,-0.614257,-0.069895,1.014936,-0.076660,-0.497836,0.282014,-0.612215,-0.353244,0.150571,-0.356592,-0.574706,-0.114283,-0.006066,0.189490,0.043747,0.290588,-0.365954,0.005388,-0.261020,-0.027565,-0.002949,-0.530695,0.223891,-0.490224,-0.300729,-0.694544,-0.360456,-0.098282,-0.024736,-0.236231,0.883497,-0.793248,0.103704,0.237163,0.141409,-0.551857,0.619236,0.481823,0.235341,-0.234219,-0.278529,0.148649,0.054469,-0.234242,-0.027104,0.309303,0.073466,0.008718,-0.105719,0.137058', '25721544', '30162520', '2137060', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26725031', '是，大臣 1984圣诞特辑', '喜剧', 'Sir Humphrey Appleby receives his just reward when he''s told by Sir Arnold Robinson that he is to be his successor as Cabinet Secretary. Jim Hacker has mixed feelings about the whole thing and while he appreciates all of the advice he''s received from Sir Humphrey over the years, they have also had their fair share of disagreements. When the Prime Minister suddenly announces his resignation, Hacker decides to take a run at the party leadership. His primary campaign issue is new regulations from Brussels on the content of sausages which point to the demise of the British banger.', '保罗·爱丁顿', 'Peter Whitmore', 9.8, 10386, 'tt0751812', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2397258764.jpg', 0.5, 0.1, 0.9, 6.5, 92, '0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000