INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26725678', '解除好友2：暗网', '恐怖', '马迪亚斯（科林·伍德尔 Colin Woodell 饰）的女友阿玛雅（斯蒂芬妮·诺格拉斯 Stephanie Nogueras 饰）是一名聋哑人，为了能够和阿玛雅顺利的交流，马迪亚斯煞费苦心，然而两人之间的关系却还是每况愈下，这让马迪亚斯的内心有着隐隐的不安。一天，马迪亚斯在一家咖啡店里捡到了一台笔记本电脑，鬼使神差之下，马迪亚斯将电脑带回了家，通过电脑里保存的用户名和密码，马迪亚斯登录了电脑主人的个人主页，发现这似乎是一个不学无术的花花公子。马迪亚斯通过这台电脑和好友莎伦娜（瑞贝卡·瑞滕豪斯 Rebecca Rittenhouse 饰）、达蒙（安德鲁斯·李斯 Andrew Lees 饰）、娜丽（贝蒂·加布里埃尔 Betty Gabriel 饰）等人联机视频，随着时间的推移，他们渐渐发现了隐藏在这台电脑里的可怕的秘密。©豆瓣', '科林·伍德尔', '斯蒂芬·苏斯科', 7.9, 196282, 'tt4761916', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2528012421.jpg', 0.8, 2.5, 22.2, 49.9, 24.7, '0.451618,0.339993,-0.589642,0.779733,0.076808,-0.399152,0.673781,0.036477,-0.734593,-0.431875,-0.067798,0.591844,-0.384447,0.091895,0.212393,-0.027874,-0.687222,-0.591673,0.112033,-0.370996,-0.450762,-0.443080,-0.457572,-0.323485,-0.110322,-0.107873,0.310989,-0.112346,0.168204,0.538013,0.146574,0.226957,-0.289104,0.312625,0.081259,0.258065,0.365681,-0.369744,0.085748,0.135156,0.118349,0.055527,0.110780,-0.113625,0.541829,0.247087,0.578244,-0.268423,0.105229,0.131151,0.089559,0.141556,-0.015104,-0.009814,0.150262,0.107436,0.017240,-0.147293,-0.412602,0.023308,0.302569,0.017651,-0.710960,-0.039187,-0.369609,0.307641,-0.488357,0.373878,-0.710243,-0.109619,-0.001597,-0.356319,0.332134,0.309860,0.177790,0.341938,0.130817,-0.127722,-0.477897,-0.234956,-0.001083,0.103781,-0.122174,0.421518,-0.097707,-0.325033,-0.201168,0.163857,-0.536567,-0.270268,0.645066,0.032133,0.065363,0.214331,-0.642245,-0.006888,-0.244068,-0.077781,-0.222143,-0.454941,0.024545,-0.903506,-0.232712,-0.486262,0.168947,0.160518,-0.091288,-0.170430,0.470810,-0.752945,0.042407,0.174408,0.271360,-0.012736,0.424745,-0.222144,0.254625,-0.166378,-0.077974,0.097474,0.380693,0.310354,0.331809,0.561630,0.081393,-0.178736,-0.442220,0.643142', '3178770', '26577354', '24753477', '1297659');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26726098', '他是龙', '爱情', '冰寒大地，恶龙肆虐。每到特定日子，人们必须献祭出美丽的女孩，让其成为恶龙的 “新娘”。勇敢的屠龙者历经千辛万苦，凭着对女孩的真爱找到龙的巢穴，将恶龙杀死，这 片土地也因此恢复平静。数十载后，残暴恶龙与勇敢屠龙者的故事已经成为传说。这天，美丽的公爵小女儿米拉（玛利亚·波兹哈娃 Mariya Poezzhaeva 饰）即将举行盛大婚礼。屠龙者族人们在婚礼上唱起了龙之歌，不料此举竟唤醒了恶龙。新娘米拉被恶龙掳走，遗落在荒无人烟的遗骸岛。在岛上，她遇到一个神秘人阿尔曼（马特维·雷科夫 Matvey Lykov 饰），然而米拉发现，这个有着人类躯体的男子，竟然就是掠夺自己的恶龙。随后米拉与阿尔曼在岛上开始 生活，米拉渐渐的改变了阿尔曼的龙性。不料阿尔曼怕自己变成龙伤害米拉，假装赶走米拉，米拉在海上漂泊被未婚夫救走，婚礼即将再次举行。©豆瓣', '马特维·雷科夫', '英达尔·珍杜巴耶夫', 7.6, 220093, 'tt4057376', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2374045871.jpg', 0.9, 4.5, 30.3, 41.7, 22.6, '-0.140932,0.231940,-0.664075,0.390027,-0.164041,0.057223,0.867472,-0.127898,-0.272268,-0.025087,0.426608,0.617008,-0.123878,0.297749,0.705060,0.254390,-0.294665,-0.469230,0.112871,0.086232,-0.209149,-0.048921,-0.465577,-0.016966,0.097500,-0.714621,0.757475,0.245717,0.040627,0.426965,0.099067,0.364485,-0.258722,0.476580,-0.362619,-0.009677,0.041676,-0.030897,-0.114863,0.200896,-0.355273,-0.227625,-0.097746,0.246449,-0.338349,0.217749,0.528668,-0.585110,0.173542,-0.378197,0.502353,-0.468801,0.058250,0.190699,0.310547,-0.225038,0.079103,0.101058,-0.092343,-0.111468,0.242308,-0.354559,-0.510389,0.109039,0.108747,0.096356,-0.514090,0.434530,0.121968,0.147877,0.248443,-0.152272,0.198445,0.270071,0.181049,0.277058,-0.080056,0.119815,-0.570161,-0.010080,0.650991,-0.242857,-0.344841,-0.014706,0.164935,-0.463479,0.180310,-0.379007,-0.193540,-0.057603,0.508536,0.162626,-0.366166,0.414616,-0.827427,-0.436485,-0.409624,-0.208041,0.178524,-0.315129,-0.588776,-0.564120,-0.105445,-0.183462,-0.102250,-0.129276,-0.077513,-0.294016,0.607986,-0.828981,0.529927,0.542220,0.147388,-0.282893,0.475800,-0.213382,0.201523,-0.055937,0.078465,0.460693,0.320062,0.490125,0.109718,0.188716,0.036896,0.301406,-0.285060,0.755153', '6866928', '21619567', '1