INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26726261', '丛林', '剧情', '影片改编自冒险家贝纳·金斯伯格同名畅销冒险小说，讲述他及其两位伙伴深入亚马逊丛林寻找失落黄金，险象环生的三周真实求生之旅。', '丹尼尔·雷德克里夫', '克瑞格·麦克林恩', 7, 6444, 'tt3758172', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2498434192.jpg', 0.9, 6.6, 46, 34.9, 11.7, '-0.385846,-0.384533,-0.531386,0.599281,1.140770,-0.182628,0.490483,-0.337660,-0.225949,-0.448146,0.300868,0.422956,0.151701,-0.412980,0.012774,0.252348,-0.463901,0.080028,-0.123453,0.066571,0.205077,-0.155129,-0.617491,-0.333607,0.108636,-0.333074,0.713151,0.335930,-1.046743,0.391868,0.381693,0.346708,-0.520678,-0.515803,0.156736,-0.000724,0.568914,0.212898,-0.503410,0.047932,-0.049927,0.323170,-0.172137,-0.283983,0.538776,0.105561,0.713079,-0.219126,0.094650,0.376421,0.689407,0.016695,-0.087386,-0.368988,-0.043577,0.026497,0.088294,-0.160852,0.468283,0.015466,-0.575056,-0.108848,-0.873110,0.309605,0.126167,0.265052,-0.408685,-0.374455,0.278946,0.166280,0.256251,-0.204249,-0.456346,-0.070592,0.473590,-0.309492,0.583783,0.075133,0.319411,0.954625,0.437355,-0.167212,-0.310374,0.099160,-0.269610,-0.467128,-0.265439,-0.125782,-0.732332,-0.102205,0.806129,0.233369,-0.211445,0.499959,-0.728879,0.082436,-0.122261,-0.494921,-0.028528,0.106490,-0.088418,-0.907127,-0.027384,0.251376,0.021217,-0.712950,0.169170,-0.684847,0.843174,0.074337,0.312551,0.966810,-0.153322,-0.455673,0.689316,0.003308,-0.214966,-0.212906,0.317557,1.540742,0.110556,-0.121380,0.096789,-0.161956,-0.379465,0.224550,-0.794586,0.268149', '26917393', '1303074', '26649687', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26727890', '女教师', '剧情', '故事发生在1983年的捷克斯洛伐克，玛丽（苏珊娜·莫拉利 Zuzana Maurery 饰）是这里的一间小学新来的老师，她格外严厉的行事风格和对学生的铁腕统治手段令她刚到这所学校没多久，就已经惹上了不少的麻烦。玛丽对待学生非常的严苛，甚至会对他们进行体罚，她毫无顾忌的发泄着自己的情绪，完全不顾及教师的身份，只因为她有着很硬的后台和灵活的社交手腕。在玛丽的影响之下，一件轰动校园的学生自杀事件让校长决定再也不能对她坐视不管，他联合了家长委员会，试图牵制玛丽的权利。但很显然，善良又有些软弱的校长完全不是玛丽的对手。©豆瓣', '苏珊娜·莫拉利', '扬·霍布雷克', 8.1, 9935, 'tt5061162', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2512791657.jpg', 0.3, 1.3, 17.1, 56.8, 24.4, '0.672544,-0.147908,-0.617654,0.651668,-0.375024,-0.010156,0.766876,0.213963,-0.712915,-0.242730,0.339207,0.795237,-0.267120,0.210649,0.267233,0.018160,-0.221710,-0.619929,-0.008167,0.022370,-0.268392,-0.492659,-0.072165,-0.292927,-0.246077,-0.438974,0.526963,-0.073598,-0.522593,0.214084,0.100743,0.397773,0.437985,0.722557,-0.027847,-0.204752,0.099382,0.066239,0.207040,-0.045635,0.335548,-0.392791,-0.190821,0.596054,0.071432,0.507674,0.608786,-0.333058,-0.396031,-0.009108,0.504088,-0.525057,-0.013637,0.388523,0.523888,-0.287785,0.089766,0.495103,-0.145492,0.078826,-0.080855,-0.202857,-0.716948,0.038192,0.200839,0.151565,-0.653656,0.666432,-0.185106,-0.016432,0.031813,-0.298726,-0.012299,0.258806,-0.026561,0.388955,-0.303454,-0.165465,-0.475218,0.019953,0.647643,0.134147,-0.376623,0.193517,-0.763729,-0.504809,-0.021502,-0.485994,-0.645105,-0.151213,0.145901,-0.023611,-0.268694,0.197598,-0.502404,-0.082580,-0.160908,-0.225204,-0.094998,-0.725587,0.105967,-0.569254,-0.206337,-0.763522,-0.331049,-0.279729,0.068151,-0.150982,0.867224,-1.235967,-0.113392,0.584591,0.392772,-0.487015,0.540311,0.341628,-0.023245,-0.049232,-0.342243,-0.056190,0.017028,0.358318,0.146904,0.690532,0.391145,-0.412356,0.097775,0.696214', '35030151', '1303112', '7065238', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26728641', '苏丹', '剧情', '来自印度北方小镇的苏丹遇见了摔角教练的女儿，苏丹为了心仪女孩，不仅开始学起摔角，在短时间内就获得地方冠军，展现了他的决心和天分。他不但娶得美人归，还和妻子一起代表印度参加奥运，但就在苏丹获得奥运金牌的同时，他却因为骄傲自大而失去了挚爱的家庭，唯一能赢回妻子芳心的办法，就是站回属于他的舞台。', '萨尔曼·汗', '阿里·阿巴斯·札法', 6.7, 15943, 'tt4832640', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2529570494.jpg', 1.5, 10, 47.8, 31.2, 9.5, '-0.109575,0.085137,-0.857257,0.724183,-0.608268,-0.400657,0.194945,0.050772,-0.352828,0.168150,0.072601,0.930933,0.130510,0.224439,0.306641,0.108563,-0.046520,-0.854884,0.071528,-0.106029,-0.117816,-0.440097,-0.171720,-0.190438,-0.147959,-0.530032,1.019118,0.089939,-0.198472,0.199474,0.312997,-0.081586,0.369393,0.387703,-0.495807,-0.217775,-0.035747,0.192494,-0.499405,0.666044,0.123447,0.055031,-0.251640,0.238368,0.041059,0.036375,0.489949,-0.317238,0.278003,-0.352937,0.225071,-0.053018,-0.031298,0.199837,-0.044864,-0.139844,0.220475,0.170599,-0.054227,0.017648,0.252645,-0.103640,-0.498765,0.150620,0.244366,-0.129628,-0.605606,0.686632,-0.158963,-0.308457,0.229213,-0.203234,0.306983,0.229202,0.033510,0.304307,-0.379083,0.021012,-0.797004,0.215923,0.736501,-0.103660,-0.051066,0.218107,-0.045473,-0.717794,0.130095,-0.474442,-0.376145,0.115936,0.233713,0.124286,-0.176573,-0.071547,-0.365359,0.304871,-0.314581,-0.333449,0.370091,-0.550182,0.247009,-0.341934,-0.062029,-0.013780,-0.086206,0.004820,0.031538,-0.626567,0.978472,-0.968046,0.133926,0.753272,0.640281,-0.558341,0.630813,0.321769,0.274899,-0.224075,-0.333657,0.349801,-0.311954,0.322621,-0.207358,-0.023852,-0.110877,-0.190810,-0.204763,0.798004', '1870681', '1295804', '1303034', '26387939');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26728669', '风中有朵雨做的云', '剧情', '城建委主任唐奕杰（张颂文 饰）在动员钉子户搬迁现场坠楼身亡，年轻警官杨家栋（井柏然 饰）负责调查此案，因此结识了唐奕杰的妻子林慧（宋佳 饰）和女儿唐小诺（马思纯 饰）。通过唐小诺，杨家栋得知唐奕杰和林慧之间的感情并不和睦，不仅如此，林慧还曾患有精神分裂症。唐奕杰生前和紫金企业的负责人姜紫成（秦昊 饰）交往甚密，而林慧亦曾是姜紫成的女友，除此之外，姜紫成的合伙人连阿云（陈妍希 饰）一直下落不明，这一切都和唐奕杰一家人有着密不可分的关联。在林慧和姜紫成的算计之下，杨家栋不仅身败名裂还背负上了杀人的罪名无奈逃亡香港，但他对凶手的追踪却并没有画上休止。©豆瓣', '井柏然', '娄烨', 7.2, 380634, 'tt8071308', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2552495737.jpg', 1.4, 6.3, 36.4, 42.6, 13.3, '0.262660,-0.205361,-0.699028,0.430953,0.069454,-0.291150,0.625115,0.213648,-0.647716,-0.394833,0.252786,0.505710,-0.030947,0.323999,0.113154,-0.081390,-0.298141,-0.723096,-0.014717,-0.039909,-0.100511,-0.754569,-0.241580,-0.065444,0.044701,-0.077087,0.460905,0.114703,-0.188253,0.659439,0.444625,0.260298,-0.486620,0.411097,-0.172953,0.151956,-0.049037,0.296854,-0.499875,-0.174525,0.101661,-0.224299,0.002525,0.132711,0.203146,0.778484,0.326925,-0.121944,-0.176136,0.006395,0.155349,-0.162605,-0.035155,0.230590,0.556990,0.070283,0.462770,0.787449,-0.330920,-0.117366,0.175643,0.078712,-0.769801,-0.058604,0.469344,0.208266,-0.426794,0.563230,-0.125432,0.061561,-0.110223,-0.053102,0.453624,0.526006,0.076605,0.327232,-0.121361,0.093336,-0.514856,0.294942,0.545688,0.044933,0.090655,0.018733,-0.096664,-0.393778,-0.292685,-0.069574,-0.334077,0.251291,0.061598,0.081542,0.011818,0.070189,-0.408347,-0.062458,-0.240663,0.290399,0.097996,-0.218720,0.160941,-0.634646,-0.071113,-0.545534,-0.479456,0.089641,0.176841,-0.315378,0.267334,-0.681928,-0.123295,0.051204,0.471486,-0.751470,0.631337,0.237834,0.100494,-0.342737,-0.489317,0.016130,0.106057,0.139572,0.022428,0.167717,0.061023,-0.462331,-0.102570,0.048448', '1291864', '1410695', '3263169', '35073886');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26729194', '那般良夜', '剧情', '影片根据N·J·克里斯普的舞台剧改编。 拉尔夫是一名年逾七十的过气编剧，如今身患疾病的他还有两个最后的心愿：和被自己遗弃多年的儿子迈克和解；确保自己没有成为年轻的太太安娜的累赘，毕竟他已经开始走入人生的“良夜”。可是，拉尔夫与迈克和解的心愿却因为他与迈克女友发生争执而被打破。不久后，孤身一人的拉尔夫雇佣了一位神秘的“到访者”，希望对方能让他走得不那么痛苦。然而，这位到访者却设下了一个惊人的陷阱。', '约翰·赫特', '埃里克·斯泰尔斯', 7.9, 5141, 'tt5271794', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2419811273.jpg', 0.3, 1.8, 23, 50.9, 23.9, '0.415333,0.207100,-0.529196,0.764314,-0.261347,-0.592643,1.053843,0.104036,-0.448115,-0.456060,0.288701,1.040331,-0.189918,0.331116,0.198502,0.017786,0.025488,-0.680799,-0.069043,-0.133675,-0.349247,-0.439068,-0.351056,-0.129353,-0.357092,-0.326425,0.856065,0.092889,-0.080055,0.280169,0.279156,0.313014,0.226420,0.459961,-0.285550,0.081877,0.274966,-0.024725,-0.219456,0.390880,0.052263,-0.303280,-0.299081,0.365145,-0.339789,0.591101,0.442388,-0.275630,-0.154029,-0.086537,0.449001,-0.420540,0.058679,0.136958,0.218284,-0.180881,0.290735,0.271745,-0.140623,-0.069546,-0.072364,-0.165147,-1.142765,0.128487,0.072180,0.100662,-0.700705,0.380507,-0.339684,-0.123749,-0.062220,-0.264693,0.060301,0.554522,0.274446,0.400846,-0.368911,0.076910,-0.670958,0.036355,0.982022,-0.109833,-0.495225,0.429872,-0.192633,-0.508107,0.046540,-0.408682,-0.679113,0.174023,0.371344,0.033634,-0.118402,0.047025,-0.466838,-0.031581,-0.702668,0.041800,-0.197457,-0.507707,-0.115990,-0.427703,-0.223917,-0.433235,-0.340474,-0.013090,0.163957,-0.490954,0.848070,-0.752732,0.222142,0.449390,0.086829,-0.706043,0.911440,0.405212,0.184384,-0.238129,0.001299,0.145017,-0.005657,0.255576,0.431671,0.434771,-0.039346,-0.124660,-0.390370,0.437353', '26678784', '30163500', '1308976', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26729533', '洛杉矶捣蛋计划', '喜剧', '落魄经纪人黄伯伦（夏雨 饰）来到美国洛杉矶寻找一位失踪艺人（杨紫 饰）不幸滞留在美国，却意外地成为了五名不同肤色的美国萌娃的爸爸。黄伯伦一边要继续寻找失踪艺人，一边还要照顾5个青春期的孩子。在经历一系列波折之后，这个不负责任的“临时奶爸”却逐渐成长为一个真正的好爸爸，得到了他人生的二次成长。', '夏雨', '郑潇', 5.5, 7170, 'tt4694440', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2323980819.jpg', 13.9, 25.9, 39.3, 12, 8.9, '0.151876,0.039994,-0.396405,0.643985,-0.167089,-0.564950,0.634496,0.276031,-0.581210,-0.448467,0.339406,0.660388,-0.109179,0.523882,0.183555,-0.067965,-0.334777,-0.561584,0.109646,0.245742,-0.373249,-0.230743,-0.593407,-0.113282,-0.393490,-0.128329,0.789408,0.052407,-0.042950,0.661467,0.339917,0.016568,0.032695,0.301261,-0.423573,0.014648,0.403785,0.339037,-0.139188,0.496190,0.093491,-0.200410,0.049646,-0.061609,0.164401,0.257453,0.672283,0.283531,-0.134446,-0.240612,0.630064,-0.335043,-0.233871,0.085352,0.438674,0.093988,0.334367,-0.045372,-0.341743,0.010930,-0.083042,-0.187079,-1.001337,-0.133455,0.304875,0.291254,-0.681589,0.267293,-0.068320,-0.159744,0.384927,-0.493616,0.034896,0.881436,0.296672,0.564222,-0.364856,0.301443,-0.223541,0.475510,0.858069,-0.091976,-0.106534,0.391654,0.112823,-0.453447,0.062355,-0.191355,-0.627582,0.213943,0.110058,-0.083560,-0.226098,0.280650,-0.648323,0.116061,-0.360669,-0.345288,-0.013926,-0.402346,-0.084900,-0.482710,0.066560,-0.387270,-0.421362,0.142750,-0.166606,-0.245145,0.981560,-0.692895,0.476327,0.711149,-0.003379,-1.078516,0.360874,0.279580,0.373405,-0.543905,0.119835,0.570364,-0.261299,0.298527,-0.359892,0.280851,-0.077346,-0.216519,-0.569339,0.056588', '26678784', '1877596', '1308424', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26729868', '机器之血', '剧情', '2007年，Dr.James在半岛军火商的支持下研究生化人。研究过程中，生化人安德烈发生基因突变大开杀戒，将半岛军火商杀害，并控制其组织，接管生化人的研究。Dr.James侥幸逃生，只好寻求警方的保护。特工林东（成龙 饰）不得以离开生命垂危的小女儿西西，接受证人保护任务...十三年后，一本科幻小说《机器之血》的出版引出了黑衣生化人组织，神秘骇客李森（罗志祥 饰）（被杀害的半岛军火商的儿子），以及隐姓埋名的林东，三股力量都开始接近一个“普通”女孩Nancy（欧阳娜娜 饰）的生活，想要得到她身上的秘密。而黑衣人幕后受伤隐藏多年的安德烈也再次出手，在多次缠斗之后终于抓走Nancy。林东和李森，不得不以身犯险一同前去解救，关键时刻却发现李森竟然是被杀害的半岛军火商的儿子，生化人的实验记录也落入了李森之手......', '成龙', '张立嘉', 4.6, 48336, 'tt5813366', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505785547.jpg', 19.2, 40.4, 32.7, 5.6, 2.2, '0.049651,-0.082458,-0.538892,0.450670,-0.273752,-0.159645,0.334647,-0.229492,-0.500674,-0.215251,0.511211,0.545877,0.142822,-0.020538,0.135032,-0.034195,-0.224197,-0.698844,-0.055727,-0.036437,-0.557604,-0.236787,-0.424885,-0.454142,0.085237,-0.470898,0.677137,0.237788,-0.332692,0.229217,0.151552,0.382610,-0.475166,0.394500,-0.021351,-0.067495,0.119294,-0.271131,-0.310816,0.415756,-0.071813,-0.258029,-0.009150,0.252315,0.102160,0.373745,0.728096,-0.403034,0.122774,-0.403207,0.172405,-0.463782,-0.195311,-0.066451,0.306326,0.170341,0.079449,0.275696,-0.195090,-0.119172,0.157652,0.077555,-0.851143,-0.158319,0.192475,0.063808,-0.556362,0.158375,-0.195910,0.241748,-0.070940,-0.384219,0.186893,0.358287,0.226213,0.267210,-0.014289,0.209891,-0.480576,0.205320,0.671274,-0.254501,-0.150216,-0.156958,0.076974,-0.441885,-0.124318,-0.384430,-0.049694,0.007888,0.365487,0.028536,-0.250928,0.127723,-0.574693,-0.171356,-0.479758,-0.032432,0.056665,-0.289139,-0.060290,-0.672468,-0.146995,0.236310,-0.120972,0.197186,0.075797,-0.273906,0.659937,-0.621690,0.233049,0.709430,0.527484,-0.627421,0.387697,0.038319,0.128728,-0.221042,-0.266815,0.377940,0.400320,0.382002,-0.019776,0.103935,-0.108138,-0.193175,-0.278040,0.012895', '25928048', '26678784', '25774050', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26730129', '猫脸老太太', '悬疑', '传说中，猫脸老太太死后被黑猫附身，半人半猫，极为凶残。然而，并没有人真正的见过此人，又或许，见过她的人，都已经不在这个世上了。小春（吴曦 饰），小秋（王翀 饰）、小夏（田淼 饰）和小冬（王聃葳 饰）是周家的四兄妹，他们的母亲在一个寒冬的夜晚冻极而死，纷飞的大雪和神出鬼没的黑猫带来了极为不祥的预感。古镇之中，有关猫脸老太太的传闻死灰复燃，幽静的大宅里，接连发生着令人毛骨悚然科学无法解释的灵异事件。死亡的诅咒笼罩在周家四兄妹的周围，对此毫无办法的四人只有逃！逃！逃！可是，他们能够短暂逃脱死亡的纠缠，但又是否能够逃脱良心的谴责和因果的轮回呢？©豆瓣', '王翀', '赵小溪', 5.2, 5239, 'tt6448978', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2320543567.jpg', 15.6, 29.1, 38.9, 10.5, 5.9, '0.296834,-0.284888,-0.876271,0.604926,-0.037711,-0.014812,1.061204,0.105272,-0.680324,-0.322741,0.220563,0.547674,-0.396350,0.256321,-0.006295,-0.125623,0.149706,-0.458122,-0.126030,-0.220400,-0.361392,-0.185658,-0.361450,-0.236871,-0.021991,-0.016754,0.431315,0.271861,-0.203366,0.373724,0.180191,0.149097,-0.405654,0.508796,-0.451246,0.146242,-0.224980,0.281891,0.018870,0.076233,0.046244,-0.216469,-0.278479,0.377232,-0.218289,0.309655,0.606315,-0.742761,-0.283096,-0.195796,0.225589,-0.350477,-0.309550,0.269826,0.282712,-0.177832,0.313470,0.218274,0.003158,-0.191637,0.177528,0.350938,-0.735183,0.338352,0.037426,0.378579,-0.502458,0.382988,0.094634,-0.145084,-0.099928,-0.199829,0.506752,0.021089,0.140109,0.435628,-0.128730,-0.184300,-0.892630,0.035611,0.677976,-0.195465,-0.297860,0.286062,-0.306007,-0.519168,-0.199943,-0.187410,-0.437330,0.037291,0.336815,0.240893,-0.506009,0.232894,-0.593484,0.343454,-0.234126,-0.040625,-0.489776,-0.440880,-0.094062,-0.306314,-0.293313,-0.658863,-0.543735,0.213620,0.103709,-0.312911,0.474247,-0.653292,0.301823,0.305286,0.259630,-0.333979,0.526193,0.295344,0.012649,0.114178,-0.161674,0.270730,0.113646,0.421198,0.372110,0.282389,-0.072581,-0.086160,-0.286855,0.426810', '1297996', '21619567', '1293515', '1428054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26730542', '有五个姐姐的我就注定要单身了啊！！', '喜剧', '一个懵懂的10岁男孩李狂龙被同班女同学小姚抛弃，他的五个姐姐告诉他，我们李家就像七里否的五片花，会永远保护花中间宛如花蕊一般的小狂龙。没有任何女人可以欺负狂龙，六人勾勾手指定下海誓山盟。没想到，长大后的李狂龙（蔡凡熙 饰）悔不当初！狂龙生命里的每一分每一秒，都只属于五个姐姐们！想谈恋爱的狂龙马上就被姐姐们识破。姐姐们见狂龙不顾小时候的承诺，执意想要追求班上的转学生小梦（项婕如 饰），决定展开非常手段，执行一系列“姐姐永远是对的”之守护弟弟计划。想要成为狂龙的女朋友，得兼目大姐（谢金燕 饰）的温柔，二姐（刘奕儿 饰）的优雅，三姐（张墨锡 饰）的智慧，四姐（高隽雅 饰）的机智，五姐（张垚 饰）的美貌？史上最幸运的热血转学生小梦杠上史上最怕姐姐的弟弟李狂龙，有五个姐姐的狂龙就注定要单身了吗？', '蔡凡熙', '苏文圣', 4.2, 3174, 'tt9249158', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2539777749.jpg', 27.5, 40, 26.4, 4.5, 1.5, '0.087598,-0.243182,-0.323879,0.680881,-0.390540,-0.360486,0.510011,-0.223947,-0.223603,-0.041103,0.123585,0.403406,0.035980,0.545094,0.133396,0.175418,0.199827,-0.816675,-0.199340,0.036355,-0.084818,-0.192236,-0.019572,0.113295,-0.103616,0.006725,0.398465,-0.192924,0.207031,0.433019,0.342612,0.075984,-0.142769,-0.025223,-0.254925,-0.011790,-0.236977,0.243982,-0.108270,0.031209,-0.070270,0.144271,0.195443,0.257807,-0.024459,0.095736,0.505000,-0.458820,0.118923,-0.418555,0.366176,-0.198684,0.112217,0.329245,0.156367,-0.081170,0.334342,-0.043733,-0.120606,0.096401,0.104397,-0.355712,-0.594137,0.033571,0.311801,0.074969,-0.711895,0.313928,0.073471,0.062484,0.397778,-0.160992,0.069711,0.002576,-0.024606,0.192377,-0.307199,0.059840,-0.367287,0.290121,0.486478,-0.118783,-0.073375,0.142620,0.190382,-0.191270,0.049194,-0.155646,-0.323475,0.227136,0.042213,0.010005,-0.037185,0.116825,-0.664693,-0.111350,0.000634,0.111347,-0.057873,-0.578326,-0.037816,-0.159990,0.257543,-0.587527,-0.188971,0.544992,0.018096,-0.255422,0.945961,-0.912085,0.179885,0.069858,0.304395,-0.744174,0.450685,0.224098,-0.033362,-0.224974,0.158231,0.025905,0.061686,-0.065868,0.122465,0.308548,0.112219,-0.117309,-0.202872,0.451662', '4127270', '6963575', '25922902', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26731238', '安全邻域', '喜剧', '血腥版《小鬼当家》，口碑还不错的儿童恐怖新片，“小飞侠”莱维·米勒扮演的男主角，父母假期出门，家中留下他、好友和父母找来看管他的保姆。这晚闯入者来找小保姆麻烦，却被逮到还被残酷的折磨...', '奥利维亚·德容格', '克里斯·佩寇维', 6.5, 9433, 'tt4443658', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2509723818.jpg', 3.4, 12, 50.3, 26.9, 7.5, '0.070161,-0.166400,-0.472629,0.103021,-0.359250,-0.253794,0.653359,0.004675,-0.434308,-0.247497,-0.173946,0.602188,-0.112445,0.237609,0.466344,0.055778,-0.172076,-0.496267,0.036712,0.368703,0.118737,-0.053340,-0.419730,-0.056266,-0.000993,-0.209739,0.076909,-0.243364,-0.100139,0.350139,0.332234,0.067628,-0.232811,0.508133,-0.268878,0.236398,-0.158191,0.076566,-0.136498,0.224816,0.417224,-0.139780,0.025701,-0.197948,0.177271,0.649406,0.466436,0.503145,-0.213251,-0.031030,0.594726,-0.359912,-0.080203,0.193257,0.210342,-0.103180,0.416348,-0.113808,0.183975,0.129993,-0.239100,-0.278414,-0.892118,0.309310,0.207622,-0.317501,-0.487846,0.544053,-0.103586,-0.019440,0.145487,-0.119015,0.360551,-0.052454,0.035767,0.583140,-0.070916,0.227875,-0.119367,0.545251,0.419160,-0.254998,-0.023203,0.097316,-0.029839,-0.082039,0.689334,-0.670897,-0.636144,0.319407,0.335637,-0.254992,-0.401003,-0.204654,-0.450892,-0.081182,-0.321771,0.022278,-0.226988,-0.512691,-0.129137,-0.956398,0.045642,0.056317,-0.184952,0.148724,0.212106,-0.419658,0.277260,-0.270925,0.308046,0.622659,0.535790,-0.583624,0.800859,-0.082124,0.211917,-0.072342,-0.008938,0.167816,0.294650,0.178581,0.116289,0.110744,0.208903,-0.156672,-0.308657,0.083614', '3318306', '24751811', '34961898', '1299166');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26731376', '天上再见', '喜剧', '演而优则导的法国演技派男星亚伯杜庞蒂自导自演的《天上再见》，改编自犯罪小说大师皮耶勒梅特的同名小说，讲述两名因目睹长官犯罪而惨遭惩处的军人，没想到退役后长官飞黄腾达，自己却一贫如洗，为不让小人得志，他们决定要为自己讨回公道。影片精采刻画第一次世界大战过后法国社会，从血肉横飞的泥泞战场到纸醉金迷的华美派对，但即便面具绚丽华美，也掩盖不住背后的人生伤痛。', '纳威尔·佩雷兹·毕斯卡亚特', '阿尔贝·杜邦泰尔', 8, 37557, 'tt5258850', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554018955.jpg', 0.2, 1.5, 21.9, 49.9, 26.5, '-0.036665,-0.041100,-0.535287,0.713338,0.171347,-0.228645,0.747542,0.117730,-0.258881,-0.216493,0.614149,0.717988,-0.162580,0.061517,0.289442,-0.022970,-0.284834,-0.689626,-0.081497,0.053393,-0.132011,-0.009233,-0.229663,-0.136688,-0.159668,-0.389692,0.929486,0.344729,-0.213162,0.387618,0.528797,0.198588,-0.049536,-0.056676,-0.136784,-0.185462,-0.173690,0.108879,-0.414449,0.077608,0.068333,-0.324998,-0.293121,0.175520,-0.246651,0.155280,0.687068,-0.033972,-0.065948,-0.117657,0.816725,-0.482233,0.258551,0.221036,0.089240,0.052857,0.115062,0.282825,0.166249,-0.019053,-0.066086,0.060511,-0.804619,0.090033,0.204771,0.083582,-0.440094,0.391546,-0.177716,-0.109009,0.115103,0.040209,0.113492,0.010844,0.542610,0.332529,-0.041424,0.156457,-0.482963,0.701867,0.392220,0.056200,-0.153649,0.319847,-0.305907,-0.153364,0.245452,-0.522557,-0.623334,0.138545,0.025322,-0.277193,-0.203254,0.414633,-0.385910,-0.159369,-0.281285,-0.173273,-0.270306,-0.217617,-0.268498,-0.543815,-0.449568,0.013130,0.002941,0.082353,0.218771,-0.005595,0.547091,-0.398589,0.169234,0.435061,-0.147483,-0.483595,0.545169,0.234758,-0.181309,0.117407,-0.113423,0.355026,0.173147,0.236541,-0.150179,0.113799,-0.057698,-0.219970,-0.177307,0.439574', '26759820', '3603547', '25731059', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26737505', '数码宝贝大冒险tri. 第3章：告白', '科幻', '太一等人因为狮子兽的死产生了动摇，而光子郎则提议找出缅因猫兽被感染的真相。但作为缅因猫兽主人的芽心却想不到为何缅因猫兽会被感染。为了防止其他数码宝贝被感染，光子郎在办公室建立了隔离区，然而巴达兽却已经出现了被感染的征兆……此时，数码宝贝们告知了大家一个有关数码宝贝世界的重大秘密。面对秘密的真相以及再度出现的缅因猫兽，太一等人陷入了苦恼当中，而在各自的想法碰撞中，他们也做出了自己的决断……“如果总是想着总有一天会怎么样的话，那么就不知不觉要成为大人了哦。”现在，冒险再度进化。', '田村睦心', '元永庆太郎', 7.4, 5109, 'tt5468014', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2437659932.jpg', 2.8, 6.4, 31.5, 35.7, 23.5, '0.410585,0.143201,-0.757713,0.361051,-0.241218,0.018837,0.717719,-0.096229,-0.541576,-0.229074,0.208042,0.646579,-0.251255,0.154114,0.016366,-0.283089,0.229072,-0.297147,0.203886,-0.133936,-0.377764,-0.106718,-0.113692,-0.228550,0.056814,-0.455627,0.634418,0.109039,-0.289875,0.225368,0.213413,0.641091,-0.039833,0.665503,0.242615,0.129564,0.220434,-0.059608,0.413699,0.185144,-0.128459,-0.063721,0.218542,0.521518,-0.352222,0.067902,0.832340,-0.884728,-0.519127,-0.537392,0.193285,-0.511631,0.078626,0.211085,0.566895,-0.128194,0.078030,0.136270,-0.207250,0.105694,-0.002217,0.352022,-0.791595,0.113030,-0.064016,0.433784,-0.380527,0.028987,0.147663,0.212638,0.156377,-0.001970,0.274833,0.558769,0.646053,0.286111,-0.119241,-0.072148,-0.521494,-0.444404,0.928188,-0.371807,-0.439342,0.160018,-0.199634,-0.585277,-0.036231,-0.113108,-0.193020,-0.092943,0.235728,0.409463,-0.664615,0.619368,-0.627723,-0.040004,-0.260965,-0.258312,-0.160726,-0.553072,-0.070324,-0.172569,-0.007074,-0.127424,-0.235385,0.117711,0.122345,-0.223508,0.589706,-0.956562,0.445234,0.484170,0.355397,-0.578450,0.378069,-0.154666,-0.065300,-0.064301,0.335022,0.017396,0.348400,0.283676,0.281909,0.103127,0.062547,-0.343586,-0.556634,0.649164', '2032339', '26670686', '3213270', '35377026');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26738204', '村戏', '剧情', '1982年，隆冬时节，苍茫大地，人们在渴望春天的到来（包产到户）。王支书要村里恢复演出老戏。“戏篓子”路老鹤，安排杨志刚演男主角，女儿路小芬不情愿。女儿的意中是奎疯子的儿子王树满。在奎疯子眼里，花生是他的“图腾”。有人偷了九亩半的花生，急得他满街乱转。他发现，不止一人拿着花生去路老鹤家……人见人怕的奎疯子，却对路小芬言听计从。整日像个孩子跟在小芬身后走动。这晚，队部秘密开会，整出一份分地计划。不想，计划还没捂热乎就被杨志刚连夜从抽屉里偷了出来，公布于众。王支书被打了个措手不及。奎疯子和霸占了十年的“九亩半”成了“分地”的焦点。“唱戏”“分地”交织中，牵出一段历史悲剧。电影《村戏》剧本改编自《贾大山小说精品集》中的前半部“梦庄生态”部分，主要是《村戏》、《花生》和《老路》等三篇。', '李志兵', '郑大圣', 8, 14099, 'tt7424828', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2516300806.jpg', 0.4, 2.3, 17, 57, 23.3, '0.105797,-0.092928,-0.516714,0.311032,0.051931,-0.230780,0.476374,0.100550,-0.365501,0.003692,-0.160735,0.281899,-0.377166,0.052673,0.041719,-0.157111,-0.311305,-0.466387,-0.336584,-0.146762,-0.088171,-0.063043,-0.017689,-0.223011,-0.134712,0.009119,0.239348,0.137612,-0.101406,0.161222,0.310268,0.077923,-0.180551,0.085183,-0.204325,0.408759,-0.138743,-0.092844,-0.157750,0.189019,0.024742,-0.193585,-0.444622,0.047046,0.238205,0.386067,0.752969,-0.299824,-0.011979,-0.030449,0.169724,-0.333857,-0.339202,-0.059919,0.590609,-0.096788,0.276067,0.092410,0.108960,0.036528,0.201887,-0.292705,-0.416846,-0.089411,0.120286,0.275765,-0.675047,0.349908,0.044417,0.215011,-0.019748,-0.337040,0.422072,-0.095163,0.149689,0.584599,0.111992,-0.129972,-0.773439,0.383838,0.323333,-0.046704,0.129696,0.398882,-0.141874,-0.189753,-0.127542,-0.300779,-0.421423,0.012979,0.483432,-0.300197,-0.228127,0.018724,-0.264226,0.025277,-0.000590,-0.096641,0.093233,-0.394463,-0.414511,-0.178293,0.144020,-0.331294,-0.022755,0.176669,-0.021658,-0.238536,0.474403,-0.233603,0.096587,0.442303,0.065831,-0.191745,0.682227,-0.003075,-0.067574,-0.404960,0.211886,-0.520963,0.046827,0.168831,0.668838,0.415898,-0.273218,-0.165746,-0.231400,0.403807', '1306505', '10527288', '1303637', '1301996');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26739551', '光灵', '动作', '在另一个现今世界里，人类、兽人、精灵和仙子自创世以来一直和平共处。《光灵》这部跨领域的动作电影讲述两个背景截然不同的警探：Ward（威尔·史密斯 Will Smith 饰）和 Jakoby（乔尔·埃哲顿 Joel Edgerton 饰），在一次例行夜间巡逻中，遇上了将会改变未来和他们所处世界的黑暗势力。', '威尔·史密斯', '大卫·阿耶', 6.4, 15996, 'tt5519340', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2504474084.jpg', 2.8, 15.1, 51, 23.6, 7.5, '0.171671,0.194733,-0.628628,0.856520,0.128119,0.245169,0.829550,-0.000027,-0.634467,-0.335053,0.159419,1.039098,-0.114652,0.081539,0.411465,-0.162508,-0.434190,-0.640973,-0.125781,-0.242104,-0.335095,-0.340405,-0.813818,-0.448362,-0.200208,-0.740834,0.757059,0.141696,-0.385503,0.143449,0.053783,0.100485,-0.631392,0.337557,0.022614,-0.157327,0.383322,0.129957,-0.300163,0.450681,-0.321779,0.048108,-0.192500,0.321139,-0.317304,0.202570,0.690130,-0.870222,0.190581,-0.568805,0.221050,0.012844,-0.206649,-0.137321,0.576074,-0.126225,0.540900,0.672852,0.089406,0.105778,-0.162974,-0.193487,-0.801008,-0.078180,0.088259,0.353642,-0.683447,0.231739,0.205108,-0.072461,0.158554,-0.218876,0.256824,0.376809,0.652272,0.351152,-0.049723,-0.170115,-0.328605,0.122722,0.715622,0.076851,-0.425898,0.450757,-0.151960,-0.602152,-0.637251,0.081041,-0.644752,0.019525,0.190388,0.091080,0.034383,0.474538,-0.883573,0.411886,0.054117,-0.063214,-0.163247,-0.587815,-0.157346,-0.792296,-0.044861,-0.469312,-0.415374,0.084518,0.096947,-0.084931,0.701255,-0.865841,0.170171,0.369522,0.327164,-0.349838,1.139976,-0.013957,0.387712,-0.445527,0.086754,0.296973,0.159194,0.317126,-0.206823,0.411928,-0.040489,0.074663,-0.376012,0.549119', '3055049', '19899707', '25890017', '1292925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26741061', '胡桃夹子和四个王国', '奇幻', '克拉拉（麦肯芝·弗依 Mackenzie Foy 饰）的母亲在她很小的时候就离开了她，留给女儿的唯一一样东西是装有无价之宝的盒子。德罗赛尔梅耶（摩根·弗里曼 Morgan Freeman 饰）是克拉拉的教父，在他举办的一场聚会上，一根神秘的金线指引着克拉拉找到了可以打开盒子的钥匙，然而，克拉拉却因此而被传送到了一个神秘的平行世界之中。这是一个克拉拉的母亲一手打造的魔法世界，四位国王分别掌管着他们的国度，而克拉拉梦寐以求的钥匙，就掌握在其中最邪恶的一位——姜母女王（海伦·米伦 Helen Mirren 饰）的手上，她的存在让这个本来和平繁盛的世界逐渐走向分崩离析。克拉拉必须和她在这里结识的善良朋友们合作，夺回钥匙，粉碎姜母女王的统治和野心。©豆瓣', '麦肯吉·弗依', '拉斯·霍尔斯道姆', 5.9, 90016, 'tt5523010', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2537214991.jpg', 2.9, 21.3, 56.4, 15.7, 3.7, '0.365510,0.442954,-0.768649,0.871188,-0.411634,-0.201557,0.968826,0.154889,-0.339316,-0.372821,0.179310,0.934691,0.021039,0.292217,0.256789,0.338083,-0.142389,-0.538112,-0.185646,-0.327589,-0.517051,-0.525999,-0.514348,-0.239646,-0.067638,-0.314461,0.618863,0.059716,-0.195257,0.116968,0.342055,0.248569,-0.171545,0.357240,-0.438314,-0.081762,0.086488,0.021856,-0.271343,0.177607,-0.126193,-0.145901,0.065407,0.369512,0.056861,0.165998,0.504512,-0.644320,0.385351,-0.003929,0.244961,-0.316473,-0.121366,-0.018631,0.291258,0.006223,-0.012019,-0.000113,-0.500981,-0.073462,0.446866,-0.395355,-0.854058,-0.077402,0.099224,0.297982,-0.818828,0.589063,-0.115790,-0.122279,0.048808,-0.443416,0.719821,0.391210,0.093274,0.341190,-0.159784,-0.057777,-0.711529,0.025887,0.496239,-0.043581,-0.092050,0.171458,-0.307824,-0.526492,-0.373124,-0.042089,-0.701956,-0.221535,0.659705,-0.088685,0.225431,0.198762,-0.830149,-0.156592,-0.313182,-0.110555,0.394189,-0.546307,0.007264,-0.498605,-0.064456,-0.357817,-0.393019,0.134788,0.036560,-0.400315,0.961030,-0.717889,0.166267,0.370232,0.218977,-0.324727,0.746542,0.003363,0.379346,-0.463068,-0.237419,0.471050,0.365170,0.371588,0.123790,0.536552,0.032162,-0.011319,-0.403419,0.833338', '26884422', '26677495', '1481233', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26741632', 'X特遣队：全员集结', '喜剧', '关押在美梦监狱的X特遣队成员获得一项可以减轻刑罚的新任务，前往南美洲的科托马耳他岛国，摧毁纳粹时期遗留的约顿海姆监狱和实验室，它当前用于关押该国的政治犯并施行人体实验。执行任务期间，X特遣队遭遇巨型外星生物海星斯塔罗，并与它发生冲突。', '玛格特·罗比', '詹姆斯·古恩', 8, 241699, 'tt6334354', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2662309551.jpg', 0.8, 2.7, 20.9, 47.4, 28.2, '0.061863,0.009914,-0.443840,0.472123,-0.087961,0.064193,0.624927,-0.072973,-0.240431,-0.416779,0.277060,0.417305,0.246273,-0.305593,0.226504,-0.055151,-0.767257,-0.277138,-0.261420,-0.381867,-0.740546,-0.535093,-0.150258,-0.506708,0.294605,-0.541915,0.933614,0.164607,-0.530827,0.110291,-0.058746,0.787906,-0.448980,0.265807,-0.176697,-0.456486,0.476452,-0.290452,-0.370283,0.305031,-0.313536,0.169256,-0.009579,-0.065802,0.427923,0.228590,0.531031,-0.210906,-0.158146,-0.656912,-0.148432,-0.380841,-0.048069,-0.231826,0.452747,-0.049926,-0.258287,0.414665,-0.030797,0.329312,0.075045,-0.450150,-0.677682,-0.579159,0.156161,-0.035242,0.173627,0.243146,-0.043201,0.727657,-0.014923,-0.092288,0.030282,0.814964,0.230096,0.486355,0.192937,0.158875,-0.611011,0.268902,0.288618,-0.716086,-0.441903,-0.277229,-0.207915,-0.831960,0.031995,0.007792,0.289183,-0.067470,0.125920,0.016797,-0.198054,0.671447,-0.913171,-0.041494,-0.477573,-0.576984,0.139320,-0.177938,0.100499,-1.291151,0.181069,0.237280,-0.088316,0.334492,0.379625,-0.084364,0.191537,-0.599014,0.674008,0.782213,0.427856,-0.319636,0.056033,0.169730,0.406522,-0.349210,0.029524,0.503490,0.584541,0.804510,-0.264120,-0.117283,0.229868,-0.432104,-0.582014,0.118175', '1306809', '2369613', '1293572', '2973528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26742730', '浪矢解忧杂货店', '剧情', '2012年的一个夜晚，自幼在某孤儿院长大的敦也（山田凉介 饰）、翔太（村上虹郎 饰）和幸平（宽一郎 饰）对某女企业家实施了抢劫，由于汽车意外抛锚，他们仓皇逃到了一家早已关张的杂货店内躲藏。这家名为浪矢杂货店的铺子此前由风趣和善的老人浪矢雄治（西田敏行 饰）经营，数十年前他出于玩笑帮小朋友们解答各种困扰，后来名气越来越大，以至于有人专程向他咨询人生中的难题。本来从1980年就该沉寂的店铺，却在三人闯进来后收到了烦恼咨询信。随后敦也等人发现，这些信件竟然来自遥远的过去。神秘的夜晚，迷途青年执笔为他人排忧解难，他们的命运和这家解忧杂货店紧紧联系在了一起……本片根据日本人气推理作家东野圭吾的同名原作改编。©豆瓣', '山田凉介', '广木隆一', 7.1, 84665, 'tt6298600', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2511434383.jpg', 0.8, 6.5, 42.1, 36.9, 13.7, '0.227233,0.008576,-0.408437,0.231940,0.203312,-0.334625,0.425543,0.183181,-0.558508,-0.525456,0.098555,0.607997,-0.078534,0.201172,0.289833,-0.077705,-0.273417,-0.493463,-0.120463,-0.311509,-0.132758,-0.320406,-0.074129,-0.260693,-0.240565,0.028471,0.245290,0.157019,0.001628,0.527030,0.034563,0.303147,-0.325600,0.250793,-0.171410,0.053213,0.076567,0.213423,-0.227928,-0.067022,-0.275972,-0.382569,-0.165605,-0.115731,0.177120,0.389790,0.611051,-0.031773,-0.463991,0.020230,0.113538,0.023761,-0.083526,-0.105766,0.386181,-0.061198,0.191125,0.092802,-0.386213,-0.015437,-0.330072,-0.017014,-0.581409,0.077507,0.034182,0.058443,-0.470340,0.318241,0.039783,-0.129830,-0.071282,-0.369132,0.062206,0.283904,0.198994,0.246504,-0.023852,0.270802,-0.158539,0.208536,0.451162,-0.060090,-0.075041,0.292916,-0.274195,-0.231271,0.012589,0.070452,-0.459690,-0.002643,0.251720,-0.030083,-0.107809,0.096067,-0.669999,-0.036926,-0.087409,-0.062221,0.278311,-0.112975,-0.267748,-0.678343,0.074476,-0.218409,-0.124539,0.066404,0.146507,-0.068414,0.738201,-0.602561,0.053264,0.469788,0.297174,-0.428217,0.592589,-0.221777,-0.002131,-0.138404,-0.219527,-0.029276,0.058936,0.389454,0.058154,0.216038,0.045095,-0.392887,-0.395412,0.044152', '3811356', '1294009', '26926321', '1418179');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26743490', '民王特别篇：新的阴谋', '剧情', '历经千辛万苦，好不容易和儿子阿翔（菅田将晖 饰）换回身体的日本第一百位首相武藤泰山（远藤宪一 饰），谁知竟在出国访问的途中再度与阿翔交换了灵魂，与此同时国会中许多议员也突然和某幼儿园的孩子交换了身体，场面打乱。这桩意外让秘书贝原（高桥一生 饰）焦虑不已，他们连忙准备小抄让阿翔背熟。出人意料的是，假冒首相居然在外事活动中表现的极为出色。在日本坐镇的泰山喜出望外，只有跟随在首相身边的贝原觉察出其中的异状，那就是有第三个人夺走了泰山的身体。为了查明真相，泰山在特工豪德寺义经（大仓孝二 饰）和中田薰（门胁麦 饰）的协助下追查制造了这一连串混乱的真凶。真相渐次浮出水面……©豆瓣', '远藤宪一', '本桥圭太', 6.8, 8809, 'tt5535204', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2326320640.jpg', 1.1, 9.3, 51.1, 27.3, 11.3, '-0.012150,-0.115744,-0.719541,0.514564,-0.199444,-0.248477,0.432759,0.220460,-0.655982,-0.247863,0.408756,0.776075,-0.325242,0.028268,0.385586,-0.139105,-0.227018,-0.830025,-0.347774,-0.207175,-0.254784,-0.310438,-0.418177,-0.221730,-0.128650,-0.272484,0.663019,0.187957,-0.023910,0.640769,0.326415,0.421150,-0.154640,0.285187,-0.150740,0.139830,0.148706,-0.026331,-0.033551,0.077444,-0.163576,-0.498981,-0.059603,0.350868,0.066112,0.399796,0.473552,-0.200773,-0.229120,-0.102491,0.183087,-0.196118,-0.041968,-0.034969,0.368749,0.050948,0.113695,0.335653,-0.435806,0.002684,0.289588,0.019739,-0.566194,0.092581,0.089203,0.324639,-0.591530,0.118045,-0.130057,-0.245865,0.297081,-0.135379,0.223384,0.600837,0.130791,0.294483,-0.323037,-0.002379,-0.258583,0.159075,0.328765,-0.081840,0.012140,0.096555,-0.076694,-0.372027,0.168588,-0.226607,0.014711,-0.113484,0.268011,0.156799,-0.098381,0.113259,-0.221841,-0.166546,-0.205749,-0.121145,-0.122935,-0.300467,0.017789,-0.523129,-0.217143,-0.325933,-0.113395,0.052802,0.171804,0.025482,0.749760,-0.646028,0.114572,0.457862,0.140753,-0.089612,0.207973,0.143592,-0.111629,-0.143912,0.015223,-0.295148,0.179845,0.485708,0.070739,0.418917,-0.048459,-0.194453,-0.579073,0.161605', '3811356', '26784898', '10467125', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26744597', '云南虫谷', '动作', '胡八一等人由于之前探险，身上出现了眼球印记，这印记带着诅咒，会危及众人性命，传闻雮尘珠能解开诅咒，而它曾经作为陪葬品安放在古滇国献王的陵墓中，胡八一等人只能深入瘴疠之地，再探古墓奇险。胡八一、王胖子、Shirley杨等人穿过遮龙山下古滇国秘密地下水道，不料遭遇千年痋术机关，成千上万个奴隶制成的“痋俑”像炸弹一样倒悬在洞顶。深入丛林之中，更是不断遭遇重重考验，但唯有冲破障碍取得雮尘珠，才能破解众人身上的诅咒……终于，在历经层层凶险，众人终于来到献王墓入口，然而更大的挑战也接踵而至… …', '蔡珩', '非行', 3.2, 45319, 'tt9490414', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2542212636.jpg', 57.2, 29.6, 10.7, 1.6, 0.9, '-0.210517,0.131436,-0.651325,0.470123,0.301598,0.231213,0.608431,-0.253595,-0.557700,-0.062087,0.367646,0.255253,-0.323364,0.023748,-0.200873,-0.076205,-0.302937,-0.386416,-0.064830,-0.462435,-0.766997,0.008739,-0.355108,-0.085616,-0.135541,-0.387398,0.644658,0.575509,-0.281684,-0.140091,0.035885,0.446045,-0.535336,0.454660,-0.466499,-0.021904,-0.150225,-0.043876,-0.146928,0.216944,-0.218827,-0.447526,-0.221132,0.044272,-0.182114,0.092542,0.355441,-0.504221,-0.048930,-0.008013,0.080790,-0.273342,-0.136990,0.051671,0.270200,0.057437,0.357417,0.328576,-0.188899,0.139800,0.283794,-0.278402,-0.339238,-0.085700,0.110831,0.219998,-0.317362,-0.169472,0.427296,0.030916,-0.205483,-0.415008,0.375847,0.056834,0.438664,0.119219,-0.454654,-0.116075,-0.222973,-0.175769,0.339877,-0.476260,-0.195219,-0.089100,0.139594,-0.400922,0.101038,0.033023,0.156477,0.007189,0.533684,0.382422,-0.390607,0.324229,-0.534662,0.104521,-0.357482,-0.101210,-0.088453,0.005542,-0.349812,-0.525500,-0.416512,0.031055,-0.192550,0.431276,-0.047395,-0.161444,0.207338,-0.205238,0.433659,0.271898,0.183141,-0.152922,0.447658,-0.198301,0.126982,-0.060183,0.038550,0.398715,0.052034,0.658718,0.095728,0.176458,-0.196997,-0.117214,-0.424388,0.225038', '24827406', '3011051', '10733357', '26715845');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26746559', '每分钟120击', '剧情', '故事发生在九十年代初期，彼时艾滋病肆虐，一个名为“ACT UP”的民间公益组织走到了公众的视线之前，其中汇聚的除了同性恋群体外，还有身患艾滋病等待着医疗救助的病人们。组织希望能够通过一些过激的社会活动来激起民众和政府医药部门的关注。内森（阿诺德·瓦卢瓦 Arnaud Valois 饰）是刚刚加入了组织的新人，在这里，他结识了名为西恩（纳威尔·佩雷兹·毕斯卡亚特 Nahuel Pérez Biscayart 饰）的活跃成员。随着时间的推移，两人之间渐渐产生了感情。西恩身患重病，病情在不断的恶化，但即便如此，他还是积极的投入到了抗争的潮流之中。在此过程中，内森的角色从一个情人渐渐向照拂者转变，他对西恩，以及对ACT UP组织的感情也经历着翻天覆地的变化。©豆瓣', '纳威尔·佩雷兹·毕斯卡亚特', '罗宾·坎皮略', 8.4, 49388, 'tt6135348', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2476693368.jpg', 0.4, 1.4, 14.7, 46.9, 36.5, '0.255421,-0.006501,-0.713430,0.586664,0.189950,0.121833,0.955932,0.189571,-0.745180,-0.108712,0.211119,0.508175,-0.319819,0.025153,0.427260,-0.432356,-0.284184,-0.749719,-0.118575,-0.108563,-0.455582,-0.539815,-0.412111,-0.358972,-0.402300,-0.712670,0.566204,0.218157,-0.422338,0.346811,0.112087,0.592556,-0.163224,0.527514,-0.016989,-0.057731,0.209902,-0.248103,-0.265326,0.219214,0.224522,-0.359959,-0.120694,0.127834,0.102212,0.506141,0.763429,-0.292123,-0.134602,0.025719,0.465117,-0.072114,0.038209,-0.091365,0.434259,0.114087,0.178493,0.435008,-0.069706,-0.081304,-0.356215,-0.131267,-0.746217,-0.116715,0.117425,0.638853,-0.671630,0.431325,0.000372,-0.277843,0.044524,-0.159745,0.174250,0.825339,-0.011528,0.324880,-0.321217,0.050436,-0.317736,0.152386,0.623195,0.151195,-0.591462,0.491596,-0.478864,-0.443031,-0.343972,-0.021338,-0.380522,-0.410338,0.179381,0.092488,-0.091514,0.669783,-0.517046,0.127907,0.090702,-0.444438,0.241015,-0.209152,0.003525,-0.803007,-0.231715,-0.460257,-0.190441,0.027423,-0.037722,-0.284030,0.911505,-0.989148,0.190097,0.607551,0.220874,-0.507246,0.544051,-0.073128,0.265624,-0.074294,-0.277073,0.197680,-0.001034,0.372425,0.029939,0.466176,0.009579,-0.099573,-0.206787,0.249850', '3005387', '3811356', '4079119', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26746958', '阿修罗', '动作', '自创世以来，世间万物，按善恶法则在天界、阿修罗界、人界、魔兽界、恶灵界和炼狱界六界轮回。生命不息，轮回不止，直至数百年前，长有三头的阿修罗王（梁家辉饰欲望之头、刘嘉玲饰谋略之头）发起攻天之战，以欲望取代善恶。阿修罗王战败，失去洞察之头（吴磊饰），被打入炼狱界。百年后，阿修罗王重新回到阿修罗界，找到轮回至人界的洞察之头——牧羊少年如意（吴磊饰），并欲与他合体打天。一面是至善、至爱，一面是至恶、极欲。一面是人类家园，一面是阿修罗界。不谙世事的牧羊少年如意将会抉择，轮回六界又将如何变化…', '吴磊', '张鹏', 3, 17967, 'tt5671298', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2525586876.jpg', 69.7, 17.2, 8.2, 2.1, 2.7, '-0.355359,0.828268,-0.331993,0.315842,0.154144,0.018426,0.265400,-0.168947,-0.416411,0.048623,-0.066954,0.174013,0.191852,0.205784,0.031299,-0.151756,0.267038,-0.451933,-0.014265,0.000403,-0.066047,0.422978,-0.559513,0.415083,-0.113744,-0.724843,0.866613,0.143961,-0.061226,-0.446409,0.212400,0.421341,-0.657078,0.203178,-0.504876,-0.109246,-0.606768,0.411330,-0.484714,0.184036,-0.469734,-0.091177,-0.307555,0.267291,-0.726658,-0.298706,0.303575,-1.107376,0.001791,-0.763487,0.580492,-0.091879,-0.589779,0.089982,0.608566,-0.070851,0.007855,0.498046,0.287397,0.046270,0.199029,-0.076989,-0.825623,-0.595329,0.088085,0.227772,-0.297660,-0.156801,0.166316,0.079413,-0.064236,-0.249500,-0.170429,0.130954,0.474859,0.246837,0.207218,-0.527565,-0.205155,0.213678,0.735859,-0.259107,-0.359298,-0.090372,0.408164,-0.772968,-0.433901,-0.389356,-0.289037,-0.047291,0.277997,0.233045,0.508999,0.836897,-0.638686,-0.082842,-0.385835,0.220917,0.087401,0.113597,-0.061855,-0.167149,-0.208800,-0.155443,-0.143836,-0.047162,0.576818,-0.119568,0.622710,-0.876722,0.567885,0.341964,0.345087,-0.350729,0.859482,-0.076839,0.432890,-0.809121,0.277260,0.855131,-0.069262,0.645351,-0.311483,-0.047664,-0.086511,0.547185,-0.297162,0.508453', '25958704', '1873750', '25713420', '34779692');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26747274', '狂兽', '剧情', '重案督察西狗（张晋 饰）与搭档阿德（吴樾 饰）到某渔村追捕涉嫌多桩凶案的歹徒江贵成，却意外发现大量被虐杀的帮派分子尸体和数额惊人的黑市黄金，一场各怀鬼胎的混战因西狗和阿德的闯入变成了整个江湖针对两个警察的困兽之斗，随着调查，西狗发现拥有超高犯罪才智的江贵成竟然嚣张到要借十号风球的天威，谋划跨国掠夺一批价值超过五亿的海底黑金，自己和阿德竟也成了他计划中的棋子，不仅得不到警方支援还被通缉，就在此时，阿德被帮派绑架为人质，贵成已经出海，西狗必须独闯狂风怒海，当狂性被绝境激发，当兽性被贪欲操控，真相和善恶哪个更重？唯有血战八方才能力挽狂澜！', '张晋', '李子俊', 4.9, 13815, 'tt7223050', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2502374737.jpg', 9.5, 44, 40.2, 4.5, 1.8, '0.053241,0.093360,-0.756308,0.245405,-0.161278,-0.100948,0.653428,0.036260,-0.398704,-0.106849,0.399873,0.448892,-0.269936,-0.228875,0.192570,-0.179838,0.071230,-0.907033,-0.386142,-0.077696,-0.182709,-0.312706,-0.599920,0.053406,-0.022166,-0.138248,0.557217,0.305919,-0.341771,0.348755,0.418196,0.510752,-0.300611,0.456051,-0.261998,-0.143591,0.292120,-0.102845,-0.220564,0.206093,-0.392956,-0.364986,0.061102,0.123108,-0.207807,0.296632,0.692491,-0.199369,-0.028597,-0.154810,0.288200,-0.530036,-0.094733,0.216007,0.595157,0.037204,0.134623,0.163273,-0.279242,0.134278,0.116381,0.061658,-1.200622,-0.123561,0.093520,0.136243,-0.617809,0.073027,-0.038024,-0.091212,0.031275,0.028466,0.084102,0.278128,0.141813,0.322770,-0.146693,-0.199159,-0.835248,-0.127691,0.580638,-0.357598,-0.119287,-0.051611,0.340261,-0.380891,-0.045502,-0.528089,0.037731,-0.049085,0.582485,-0.152609,-0.039418,0.187406,-0.712173,-0.079984,-0.449395,-0.266523,-0.335102,-0.222600,-0.151548,-0.617473,-0.282774,-0.068570,-0.252148,0.426263,0.420017,-0.119573,0.313354,-0.580228,0.178372,0.680194,0.295271,-0.726424,0.042322,0.124109,-0.086304,-0.117837,-0.181740,-0.182468,0.628031,0.566627,0.182625,0.124942,0.118885,-0.344672,-0.183550,0.353574', '1857099', '26678784', '1793491', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26747836', '喵星人', '喜剧', '千百年来，地球上一直住着一种外星生物，名叫喵星人。它们从遥远的喵星来到地球，化身为猫科动物，分散在世界每个角落。萌萌的外表，加上机智聪明的头脑，轻易就得到人类的宠爱。不愁吃喝的它们桀骜不驯，活像饱经沧桑的江湖大佬。犀犀利就是他们中的一员，作为一名正牌的喵星来客，它肩负使命长途跋涉来到地球，却意外遇到了吴守龙（古天乐饰演）一家，上演了一幕相运相生，喵趣横生的人猫奇遇记。', '古天乐', '陈木胜', 4.4, 13830, 'tt7070496', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2492868791.jpg', 32.5, 31.9, 24.8, 6.1, 4.7, '0.239589,0.509343,-0.760504,0.529254,-0.301143,0.308434,0.328290,0.067384,-0.248991,0.160595,0.223645,0.593038,0.105771,0.068179,0.214654,0.088286,0.303890,-0.110242,-0.176123,-0.095278,0.053417,0.236616,-0.487706,-0.335013,-0.039310,-0.505350,0.672625,0.111632,-0.322585,0.446949,0.285110,0.366056,-0.436881,0.435608,-0.486446,-0.255200,0.046460,-0.050128,0.239298,0.194518,-0.388804,0.474443,0.253916,0.132728,-0.167112,-0.133532,0.741966,-0.895560,-0.432520,-0.278953,0.315465,-0.072005,-0.125162,-0.191701,0.605803,-0.040829,-0.067469,-0.190696,0.339097,0.149717,0.135043,-0.029592,-0.636016,-0.378544,0.004293,0.345375,-0.399238,0.371581,0.040552,-0.095223,0.032773,-0.327472,0.049941,-0.096599,0.252379,0.518418,0.226754,0.574792,-0.354100,-0.173352,0.610104,0.003628,-0.757377,0.254632,-0.170725,-0.646112,-0.017379,-0.400783,-0.520389,-0.009327,0.406279,-0.189044,-0.466219,0.420909,-0.797003,0.541865,-0.188448,-0.144940,0.270939,-0.352040,-0.259491,-0.457080,0.097754,-0.438863,-0.033515,0.173236,0.136699,-0.195272,1.004746,-0.767257,0.205116,0.693042,0.053149,-0.219821,0.840345,-0.267250,-0.228646,-0.296038,-0.029150,0.524538,0.358717,0.293291,-0.145425,0.298064,-0.269483,0.339460,-0.278617,0.571874', '24284209', '1302661', '2977870', '1457926');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26747869', '真·三国无双', '动作', '电影根据同名游戏改编，讲述了动荡的东汉末年，汉室摇摇欲坠，董卓入京霸占朝野，引起天下动荡，身怀绝世武艺的曹操、吕布、刘备、关羽、张飞等各路英雄豪杰纷纷崛起，一场群雄逐鹿的大混战正式拉开序幕。在乱世中，到底谁才是真正的无双英雄……', '古天乐', '周显扬', 3.9, 40175, 'tt7587604', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2644869903.jpg', 36.2, 39.9, 19.8, 2.9, 1.2, '-0.054647,0.211080,-0.801183,0.171675,0.758559,0.193502,-0.103828,0.092799,-0.584876,-0.380056,0.478581,0.661616,-0.469944,-0.112111,-0.212973,-0.409661,-0.207188,-1.055275,-0.240186,0.008236,0.308318,0.257193,-0.668840,0.341637,-0.275014,0.152222,0.829554,0.145240,-0.519276,0.277523,0.256045,-0.004086,0.006774,0.439037,-0.105952,0.167558,-0.300226,0.246234,-0.680998,0.070267,-0.583978,-0.761848,-0.734035,0.020059,-0.416220,-0.115536,0.213575,-0.414528,0.394187,-0.039848,0.715755,-0.171142,-0.580623,-0.292913,0.562338,0.049741,0.034124,0.128393,0.305057,0.015159,-0.648655,0.090842,-0.617166,-0.173989,0.257653,0.032224,-0.175449,0.278064,0.237255,-0.562266,-0.099315,-0.135644,0.335513,0.796043,0.774603,0.072748,0.245230,-0.161478,-0.311401,0.495138,0.455011,-0.075018,-0.372980,-0.086943,0.616427,-0.335431,-0.015613,-0.468425,-0.773335,0.087257,0.521976,-0.393181,0.373315,0.879159,-0.120308,-0.006401,-0.278870,-0.278509,0.202725,0.259545,-0.196030,-0.345723,-0.574508,-0.102022,-0.088840,-0.210922,0.702675,0.038696,0.985514,-0.780929,-0.332396,0.132839,-0.373713,-0.803342,-0.166026,0.159759,0.203530,0.125859,-0.272797,0.012905,0.237433,0.009605,-0.244757,0.038755,-0.439925,-0.138603,-0.364347,0.570471', '27602116', '1308989', '1433736', '30465281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26748223', '失眠', '恐怖', '著名大學醫學院教授林惜家（黃秋生　飾），專門研究人類可以長時間不需睡眠的方法。一天，前女友丘夢熙（吳俐璇　飾）突然現身求助，原來她的家人全部患上失眠症，病情去到末期，病人更會陷入失常狀態、極具攻擊性！為探究真相，林惜家開始連串恐怖實驗：潛入停屍間偷取病人大腦，又把丘夢熙關在密室軟禁，藉此研究睡眠和大腦蛋白質之間的關係…隨著實驗愈深入，蹊蹺的事情不斷在丘夢熙身上發生；就連林惜家也看似受感染，心底開始出現吃人肉的慾望… 原來一切牽涉到45年前，孿生姐妹侯文媛和侯文禎（衛詩雅　分飾）的一宗倫常慘案有關！', '黄秋生', '邱礼涛', 6.2, 15125, 'tt6754750', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2497145485.jpg', 3.6, 17.9, 49.1, 21.5, 8, '0.342967,-0.213032,-0.446100,0.147299,-0.166043,-0.077129,0.722520,0.042918,-0.617192,-0.386042,0.259978,0.367658,-0.239279,0.082304,0.207287,-0.051046,-0.399123,-0.574476,-0.087528,0.018016,-0.684735,-0.522345,0.006004,-0.527365,0.094294,-0.544251,0.586477,0.203955,-0.237022,0.044079,-0.590235,0.652720,-0.095098,0.496494,-0.098589,-0.047061,0.046980,0.056060,-0.177255,0.371759,0.780181,-0.518864,-0.295623,0.351582,0.176153,0.063341,0.743727,0.089743,-0.457049,0.233177,0.164907,-0.257366,-0.048174,0.171916,0.561230,0.035627,0.379988,0.278884,-0.530938,0.219850,-0.415684,0.146942,-0.551836,-0.321690,0.222380,0.150178,-0.306175,0.376429,-0.058284,-0.255433,0.027763,-0.567971,0.234259,0.191181,-0.095213,0.879808,-0.096008,-0.200704,-0.360609,-0.061269,0.495733,-0.233121,-0.054913,0.567616,0.006699,-0.358568,-0.147470,-0.337448,-0.380836,0.008149,0.414640,0.420188,-0.526863,0.591505,-0.320174,-0.105747,-0.178460,-0.546376,0.065370,-0.157858,-0.067227,-0.081524,-0.332810,-0.209038,-0.166919,0.103769,0.485691,-0.336870,0.484620,-0.631752,0.320959,0.505200,0.136148,-0.494044,0.335839,-0.226432,-0.021224,-0.233481,-0.197931,0.088643,0.008178,0.566880,0.083482,0.276167,0.137365,0.301881,-0.741045,0.300100', '10508879', '1908318', '21619567', '1298214');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26748673', '拆弹专家', '动作', '章在山（刘德华 饰）是香港警队“爆炸品处理科”的一名高级督察。七年前，他潜伏到头号通缉犯火爆（姜武 饰）的犯罪团伙中，在一次打劫金库的行动中，章在山表露了其拆弹组卧底的身份，与警方里应外合，成功阻止炸弹引爆，并将火爆及其弟的犯罪组织一网打尽，可惜在千钧一发之间，火爆逃脱并扬言誓要报仇。复职后的章在山很快被晋升为警队的拆弹专家。七年后，香港接二连三遭遇炸弹恐怖袭击，警方更收到线报大批爆炸品已偷运入港，一切迹象显示香港将有大案发生。就在香港人心惶惶之际，城中最繁忙的红磡海底隧道被悍匪围堵拦截，数百名人质被胁持，终于现身的火爆威胁警方炸毁隧道。章在山唯有将火爆绳之于法，才能拆解这场反恐风暴背后的惊天阴谋。', '刘德华', '邱礼涛', 6.2, 170889, 'tt5847286', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2465858820.jpg', 2.3, 15.2, 56.7, 21.3, 4.4, '0.286874,0.108650,-0.633477,0.216562,0.358781,0.478005,0.364844,-0.146124,-0.486081,0.066216,0.375196,0.406023,-0.124346,-0.009396,0.254078,-0.386199,-0.194411,-0.815680,-0.304177,-0.265055,-0.305962,-0.230313,-0.358124,0.092586,-0.027832,-0.326963,0.607558,0.288432,-0.441994,0.456666,0.476910,0.389380,-0.336972,0.530259,-0.270121,-0.302771,0.337558,-0.207456,-0.158436,0.236249,-0.131748,-0.622998,0.137922,-0.021197,0.277898,0.502807,0.674027,-0.171746,-0.175131,0.087498,0.393837,-0.501612,-0.036207,0.041591,0.898717,0.052611,-0.348917,0.489774,-0.605708,0.004312,0.142854,-0.182081,-0.708409,-0.034197,0.294373,0.035226,-0.339438,-0.054887,-0.114483,0.330679,0.037481,-0.076246,0.296896,0.574414,0.085270,0.006880,-0.103417,0.032300,-0.534551,0.296751,0.743991,-0.378274,-0.317711,-0.242157,0.623024,-0.396988,-0.074903,-0.312519,-0.002346,-0.043785,0.718546,-0.232882,-0.175596,0.251522,-0.438754,-0.221711,-0.564682,-0.095480,-0.165006,-0.201702,-0.349024,-0.916815,-0.071242,0.183520,0.015242,0.630815,0.176372,0.133880,0.266981,-0.528927,0.276228,0.568617,-0.036936,-0.454452,0.213485,0.040987,0.144445,-0.233786,-0.186189,-0.019467,0.646386,0.621631,0.065001,0.357746,-0.177011,-0.493251,-0.120824,-0.116074', '25723905', '3387546', '5151890', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26748688', '恋爱谈', '剧情', '学美术的允珠（李尚熙）在准备毕业展示时遇到了一名经常引起她注意的人。允珠从对方和自己偶然相撞的眼神中感受到了温暖，渐渐地被对方吸引了。一边打零工一般寻找梦想的智书（柳善英）在某个寒冷的冬日里遇到了用温暖的眼神看着自己的某人。不久后，再次邂逅那个人的智书遵从内心向她伸出了手。', '李尚熙', '李贤珠', 7.8, 28521, 'tt6129730', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2392975783.jpg', 0.4, 2.5, 26.4, 46.4, 24.3, '0.619264,0.058710,-0.841931,0.647205,-0.285342,-0.169020,1.083219,0.296257,-0.286011,-0.086569,0.447614,0.927479,-0.483885,0.449088,0.322565,0.191070,-0.195714,-1.053466,-0.238043,-0.185315,-0.377096,0.011889,-0.372700,0.158013,-0.159537,-0.135576,0.573800,0.204710,-0.567407,0.624482,-0.083059,0.218885,0.313567,0.829287,-0.527202,-0.181803,-0.203803,-0.032930,0.270548,0.433257,0.401865,-0.534480,-0.476177,0.153808,-0.261885,0.528061,0.906672,-0.182657,0.065125,0.034668,0.359383,-0.134991,0.128472,0.382215,-0.050583,0.320209,-0.140054,-0.153189,-0.316592,0.201318,0.145404,-0.018025,-0.705211,-0.057595,-0.244503,0.293636,-0.494550,0.153785,0.165362,-0.106947,0.431151,-0.453208,0.376001,0.170533,-0.062040,0.443243,-0.393040,0.068919,-0.156802,0.139193,0.669945,-0.162883,-0.154693,0.475956,-0.232791,-0.338483,0.194017,0.158576,-0.285029,-0.205916,0.589885,0.391126,-0.280305,0.161622,-0.666856,-0.035504,0.228982,-0.376387,-0.112999,-0.494909,-0.412991,-0.718692,-0.336824,-0.555744,-0.329369,0.153311,-0.181962,-0.245509,0.624861,-0.914850,0.292712,0.853936,0.415580,0.104480,0.722088,-0.341623,-0.134030,0.042592,-0.123872,0.228837,0.042512,0.738398,0.436651,0.756490,-0.376312,0.145706,-0.489913,0.590906', '1309172', '1296534', '3027015', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26751772', '无声夜', '惊悚', '在一个远离城市喧嚣的寂静所在，迷离中央的木屋中，居住着美丽的聋哑女作家麦蒂·杨（凯特·西格尔 Kate Siegel 饰）。她的世界寂静无声，而在写作时心底又会有个声音充满她那静谧的内心世界。当此时的写作陷入僵局时，麦蒂起身去厨房收拾餐具，就在此时不久前才刚见过的好友莎拉（Samantha Sloyan 饰）残忍杀害。可惜任凭莎拉百般呼救，却无法引起麦迪的注意。一无所知的麦蒂回到电脑前继续工作，而那个男人则悄悄潜入室内。这时麦蒂突然收到从自己的手机上发来的短信，里面则是蒙面男子用手机拍下来的照片。当这个女子意识到危险降临之际，她已成为任凭猎人玩弄的笼中之鸟……©豆瓣', '小约翰·加拉赫', '迈克·弗拉纳根', 6.3, 8644, 'tt5022702', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2327006860.jpg', 3.3, 15.5, 51, 23.4, 6.9, '0.487422,0.446770,-0.763190,0.605492,-0.174251,-0.292129,1.204904,0.152898,-0.377388,-0.434609,0.182321,0.588489,-0.090325,0.509310,0.366372,0.108236,-0.478336,-0.753164,-0.414024,-0.237638,-0.409711,-0.231543,-0.338335,-0.037429,0.028019,-0.122271,0.475839,0.094412,-0.256684,0.539601,0.215277,0.163641,-0.206233,0.693573,-0.057930,0.029364,0.019557,0.120903,-0.044213,0.263984,-0.035510,-0.500755,-0.289443,0.217297,-0.148796,0.236947,0.834106,-0.369040,-0.058889,0.073820,0.506605,0.081475,-0.139061,0.080497,0.274851,-0.103640,0.004748,-0.265193,-0.313595,0.220272,-0.068829,0.037029,-0.529216,0.153174,-0.241502,0.370952,-0.242647,0.128389,-0.266104,0.078869,0.186869,-0.425187,0.454340,-0.014814,0.033289,0.640095,-0.303221,0.119567,-0.277559,0.005720,0.323022,0.278083,0.117574,0.342672,-0.142118,-0.386403,0.135140,0.194142,-0.596899,-0.399087,0.413183,0.383831,-0.100589,-0.001131,-0.408110,-0.003747,0.015140,-0.348404,-0.053985,-0.427565,-0.681376,-0.675536,-0.206304,-0.084211,-0.080334,0.414971,-0.301936,-0.030296,0.502041,-0.776327,0.283631,0.387953,0.035116,0.116356,0.517660,-0.124414,0.193514,-0.076423,-0.228261,0.484473,0.228336,0.585945,-0.018091,0.233502,-0.364457,-0.104125,-0.902000,0.509086', '20451118', '1296534', '30136177', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26751899', '愚行录', '剧情', '夏原友希会（松本若菜 饰）从中学时代起就是班上人人瞩目的焦点人物，毕业后，她嫁人生子，美满幸福的生活堪称典范。然而，厄运毫无征兆的降临在了她头上，她和她的家人成为了一场血腥残暴的灭门凶杀案中的受害者，种种迹象表面，凶手并非谋财，而更像是一种报复。田中武志（妻夫木聪 饰）是一名报社记者，他决定挖掘案件背后隐藏的真相。武志有一个名叫光子（满岛光 饰）的妹妹，因为虐待亲生女儿致死而锒铛入狱，被判定为拥有精神方面的障碍。武志走访了夏原生前的校友和朋友们，她所拥有的一段不为人知的黑暗历史渐渐浮出了水面，而这段历史竟然和光子有着千丝万缕的关联。©豆瓣', '妻夫木聪', '石川庆', 7.8, 32087, 'tt5560592', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2373212772.jpg', 0.3, 2.1, 26.1, 52.3, 19.2, '0.112223,-0.176385,-0.500509,0.614127,-0.181654,0.069765,0.842523,0.023077,-0.571381,-0.372988,0.223873,0.748701,-0.222357,0.373578,0.271794,-0.119270,0.096983,-0.802928,0.086262,-0.332479,-0.313593,-0.418273,-0.622378,-0.153896,-0.144504,-0.318223,0.962695,0.186205,-0.381066,0.439710,0.318813,0.472151,-0.196900,0.304771,-0.081758,-0.117203,-0.135361,0.263361,-0.272655,-0.132777,-0.111964,-0.394627,-0.039317,0.363668,-0.347903,0.400003,0.693624,-0.199329,-0.101394,-0.393322,0.641639,-0.503941,-0.146326,0.397556,0.487554,0.041858,0.161034,0.540147,-0.015237,-0.310016,0.228510,-0.077999,-0.818568,-0.351470,0.218639,0.269451,-0.426057,0.382654,-0.074525,-0.232084,0.116057,-0.119993,0.244250,0.308952,0.297766,0.377614,-0.388437,-0.118605,-0.461572,0.328781,0.613613,-0.095703,-0.375621,0.383941,-0.218029,-0.254236,-0.208027,-0.161243,-0.358465,0.001832,0.179531,0.151131,-0.288860,0.583134,-0.489226,-0.076002,-0.195354,-0.007897,0.014297,-0.457349,-0.128542,-0.463819,-0.382652,-0.478613,-0.386219,-0.027176,0.080958,-0.424265,0.800882,-0.838529,0.216602,0.451558,0.048176,-0.595839,0.368034,0.259169,0.136759,-0.272409,-0.044188,0.198822,0.101206,0.224872,-0.086008,0.255502,-0.106369,-0.009427,-0.269829,0.544018', '25880986', '26759820', '26667010', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26752337', '春梦', '剧情', '《春梦》最初定名“三人行”，讲述了三个恋爱方式完全不同的男人与一个女人之间发生的爱情故事。三位男主人公在片中将展现一种既相互竞争又相互慰藉的奇妙关系。', '梁益准', '张律', 7.7, 7894, 'tt6066538', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2382802813.jpg', 1, 3.2, 27, 48.8, 20.1, '0.749416,-0.346473,-0.210666,0.947574,0.057226,0.203328,1.064914,-0.002781,-0.360255,-0.306136,0.086337,0.789470,-0.824041,0.094056,0.666893,-0.643347,0.174716,-1.046003,-0.238864,0.054071,-0.063697,-0.535605,-0.033195,0.104077,-0.107166,-0.289307,0.830322,-0.580764,-0.461825,0.318859,0.430558,0.022540,-0.912090,0.210690,0.031354,-0.149656,0.262584,0.520393,-0.570302,0.033329,-0.150183,-0.063321,0.193874,0.168939,-0.673713,0.360120,1.129014,-0.425616,-0.349476,0.103374,0.635260,0.637553,-0.358091,0.255959,0.026353,0.051809,0.268664,0.353401,0.228295,-0.172055,0.211480,0.136453,-0.666549,0.150612,0.077401,0.163443,0.212168,0.591201,0.608043,-0.305228,0.222770,-0.255862,0.098061,0.265759,1.088754,0.617792,-0.176050,-0.178216,-0.201777,0.190223,1.192433,0.293798,-0.790211,0.889771,-0.192183,-0.418852,-0.587074,0.291104,-0.503115,0.091783,0.131956,0.145754,-0.219889,0.507030,-1.274509,0.013101,-0.112877,0.324227,0.163656,-0.748822,0.461060,-0.738280,-0.715685,-0.550056,-0.394596,-0.057804,0.470590,-0.488857,0.720000,-0.810237,-0.135126,0.412580,-0.089533,-0.739542,0.564906,0.598561,0.248331,-0.788801,-0.109328,0.208556,0.198498,-0.408805,-0.235404,0.778782,-0.501205,0.770123,-0.488558,0.380103', '10581450', '2212281', '1792922', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26752547', '催眠·裁决', '悬疑', '轰动全港的林氏家族凶杀案踏入审讯最后一天，陪审团准备退庭商议时，成员之一许立生（张家辉饰）突然收到女儿茵茵（艾米饰）被绑架的消息，神秘人要求曾为国际催眠权威的立生通过催眠术令陪审团裁定被告谋杀罪名成立，否则其女儿将被撕票，这也就意味着立生必须在狭小的空间内、众目睽睽之下，不用专业工具隐秘地催眠至少4个人。立生偷偷将茵茵被绑架的讯息转发给曾为国内特种部队成员的小舅杨凯（张翰饰）后，进入了退庭商议室…', '张家辉', '黎兆钧', 5.7, 53432, 'tt10098494', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2569044398.jpg', 3, 25.5, 55.5, 13.4, 2.6, '0.341404,0.016052,-0.643245,0.445760,-0.148758,-0.014619,0.004151,0.276945,-0.793004,-0.405009,0.382293,0.439965,-0.361762,0.086262,0.311188,-0.105818,-0.321303,-0.792838,-0.212508,-0.435554,-0.351484,-0.656141,0.087077,-0.230719,0.065694,-0.284579,0.460329,-0.060658,-0.325245,-0.072359,0.201836,0.348621,-0.259610,0.048353,-0.007586,-0.084397,0.465402,-0.154924,-0.549342,0.279970,-0.211867,-0.432377,0.128794,-0.156968,0.078235,0.290939,0.437172,-0.243624,-0.271048,-0.444079,0.551582,-0.183066,-0.224288,0.196355,0.542399,0.299050,0.392220,0.800201,-0.451398,0.127943,0.141617,-0.181128,-0.869148,0.147214,0.248770,-0.219790,-0.252207,0.175175,-0.234474,0.216139,-0.042324,-0.017619,0.341744,0.384816,0.179386,0.389665,-0.103634,0.165899,-0.152724,-0.066040,0.453171,-0.388028,0.040749,-0.354161,0.044636,-0.469293,0.301877,-0.220333,-0.023945,0.183459,0.339123,0.343819,-0.053330,0.078502,-0.324745,-0.187798,-0.577838,-0.187843,0.014949,-0.395670,-0.122263,-0.527274,0.031335,0.643238,-0.217600,0.216431,0.200949,-0.055821,0.569848,-0.594715,0.237562,0.178199,0.541320,-0.664487,0.361974,0.023033,0.430885,-0.179819,0.117523,-0.179825,0.249567,0.652134,0.168936,0.074199,-0.002057,-0.378478,-0.163155,-0.253400', '1750027', '26678784', '6557030', '1297862');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26752558', '非分熟女', '剧情', '小敏（蔡卓妍 饰）在满怀期待之中终于走入了婚姻的殿堂，然而，令她没有想到的是，等待着她的，将是长达5年的无性婚姻。丈夫的冷漠让小敏感到异常的压抑，起初她仍然相信一切都会好转，但随着时间的推移，她只觉得自己陷入了生活的流沙之中，正在慢慢窒息。终于，小敏下定了离婚的决定。她失去了婚姻、工作和对未来的希望。小敏家里经营着一家破旧的餐厅，徘徊在随时倒闭的边缘。离婚后的小敏决定接手餐厅的运营工作，并且招聘了名叫家豪（吴慷仁 饰）的神秘厨师。家豪和小敏的前夫是完全相反的人，他热烈、大胆，无论做任何事情都充满了激情。©豆瓣', '蔡卓妍', '曾翠珊', 5, 11265, 'tt9838372', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2553664192.jpg', 11.6, 38.8, 40.8, 7, 1.7, '0.102027,0.128610,-0.918928,0.425048,-0.022254,-0.320206,0.871777,0.185568,-0.650450,-0.260760,0.189918,0.535714,-0.180526,0.456264,0.180496,0.069347,-0.191917,-0.977555,-0.374448,-0.057041,-0.332846,-0.562610,-0.032819,-0.111888,-0.158605,-0.112736,0.682573,0.284414,-0.041756,0.383615,0.156898,-0.065176,0.129041,0.816568,-0.111028,0.002468,0.112084,0.133746,-0.253982,-0.001817,0.475333,-0.134610,-0.121057,0.428105,0.152281,0.499861,0.548980,-0.232541,-0.410881,0.268488,0.292464,-0.268326,-0.195602,0.290687,0.060674,0.173034,0.106423,0.286162,-0.757626,0.021621,0.048864,0.046908,-0.669584,0.130021,-0.027148,0.156959,-0.777026,0.533812,0.081111,-0.061343,0.370664,-0.479887,0.253556,0.367288,0.302454,0.573442,-0.233169,0.053143,-0.439487,0.088039,0.779618,0.152472,-0.274571,0.489998,-0.399256,-0.365992,-0.206305,-0.063476,-0.562459,-0.267973,0.085898,0.497059,-0.257499,0.273829,-0.451163,-0.028837,0.037178,-0.501291,0.095436,-0.611260,-0.147251,-0.456048,-0.337781,-0.426731,-0.328766,0.207311,-0.144523,-0.346326,0.691309,-1.107041,0.374774,0.532274,0.407818,-0.514576,0.731164,0.028756,0.050732,-0.144719,-0.010115,0.263725,-0.412580,0.345868,0.258671,0.266660,-0.125978,0.011854,-0.508574,0.706586', '1301022', '1308755', '35030151', '1937946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26752564', '小伟', '剧情', '一家三口的生活因父亲伟明被查出末期肝癌而改变。表面上平静的家庭被阴霾笼罩。妈妈慕伶扛起家，却得不到父子的体谅。儿子一鸣收到美国的大学录取通知书，但不敢告诉爸妈。他知道母亲不易，却不愿表现过多关心。父亲伟明则在迷雾之中暗自做出一个改变家庭命运的选择。', '彭杏英', '黄梓', 7.5, 35890, 'tt10488406', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2631157729.jpg', 0.3, 2.2, 29.7, 56.4, 11.3, '0.431275,-0.030691,-0.768826,0.613251,-0.144138,-0.296169,0.556588,0.245696,-0.625969,-0.356478,0.092564,0.771238,0.264883,0.771831,0.037120,-0.137153,-0.036983,-0.395044,0.338816,0.017515,0.108972,-0.590610,0.089449,0.106031,-0.246346,-0.165740,0.853096,0.120876,0.211107,0.637548,-0.095067,0.465742,-0.043623,0.437566,0.161380,0.012122,-0.407080,0.368197,-0.566427,0.072773,0.266045,-0.018463,0.065875,0.511821,0.200747,0.599361,0.564833,0.082007,-0.511704,-0.222615,0.789704,-0.224504,-0.220226,0.299502,0.322665,0.123492,-0.158038,0.296498,-0.311003,-0.244876,0.026918,0.152821,-0.664540,-0.107549,0.541823,0.224655,-0.576562,0.498127,-0.151863,-0.232278,-0.209403,-0.454590,0.257771,0.350372,0.263732,0.533377,-0.478470,0.357070,-0.434597,-0.063514,0.833082,-0.345908,-0.295300,0.166333,-0.781791,0.234585,0.406370,-0.635187,-0.861940,0.356051,-0.415350,0.540241,-0.402006,0.275329,0.252700,-0.285252,-0.351292,-0.223041,0.142731,-0.850909,-0.163432,-0.069733,-0.284306,-0.082848,-0.567323,0.159869,-0.208664,-0.509762,0.480914,-0.774215,0.198062,0.021926,0.564983,-0.665184,0.880015,0.299888,0.178583,-0.326811,0.148223,0.430708,0.158764,-0.169023,-0.105442,-0.157211,-0.004920,-0.214573,-0.148369,0.221100', '1494897', '1397550', '1308047', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26752852', '水形物语', '剧情', '故事发生在1963年，时值冷战期间，哑女艾丽莎（莎莉·霍金斯 Sally Hawkins 饰）在政府实验室里工作，是那里的一名清洁女工。年幼时，一场大病夺走了艾丽莎的声音，之后一直至今，她都在沉默之中过着形单影只的生活，全部的朋友就只有画家老头（理查德·詹金斯 Richard Jenkins 饰）和同事塞尔达（奥克塔维亚·斯宾瑟 Octavia Spencer 饰）。一天，实验室里拉响了高度戒备的警报，一个神秘的装满了水的罐子被送了进来，艾丽莎震惊的发现，罐子里关着一个半人半鱼的怪异生物。在理查德（迈克尔·珊农 Michael Shannon 饰）的带领下，科学家团队想要在这怪物身上提炼出能够制造生物武器的物质，可是在艾丽莎眼中，它不过是一个和自己一样的孤独的生命体。随着时间的推移，艾尔莎和怪物之间竟然产生了感情。©豆瓣', '莎莉·霍金斯', '吉尔莫·德尔·托罗', 7.2, 421136, 'tt5580390', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2506388632.jpg', 1.2, 5.8, 38.1, 40.8, 14.1, '0.295810,0.074130,-0.674715,0.416053,-0.012755,-0.344572,1.019306,-0.054590,-0.451237,-0.403586,0.007575,0.379317,-0.367664,0.315248,0.025435,-0.049424,-0.421486,-0.672130,-0.310030,-0.420712,-0.530509,-0.473794,-0.316400,-0.409731,-0.048354,-0.574111,0.440710,-0.035128,0.040744,0.366118,0.125521,0.303981,-0.021877,0.456954,-0.007331,0.028712,0.422248,-0.107182,-0.133331,0.385116,0.200082,-0.068267,0.028875,0.160519,0.202028,0.110016,0.769924,-0.446322,0.125813,0.012864,0.202814,-0.005273,0.011247,-0.151290,0.605750,0.079614,0.060189,-0.013034,-0.225315,0.167653,0.340246,-0.105657,-0.481111,-0.045362,-0.104275,0.327892,-0.643838,0.516970,0.059546,0.078746,0.135607,-0.321308,0.359845,0.153932,0.351605,0.658494,-0.109123,0.100010,-0.515167,0.111309,0.305531,-0.148484,-0.311683,0.505241,-0.439618,-0.712989,-0.277390,0.063777,-0.541667,-0.223485,0.315589,0.057597,-0.151577,0.476832,-0.826759,0.245924,-0.155686,-0.122764,-0.097114,-0.206863,-0.185997,-0.397869,-0.229306,-0.385236,-0.227111,0.263152,-0.123106,-0.096519,0.589946,-0.613955,0.478598,0.590086,0.161635,0.171543,0.680482,-0.097459,0.104045,-0.075788,0.040976,0.149339,0.052636,0.268234,0.314430,0.535213,0.012791,-0.013836,-0.427105,0.380790', '21619567', '1467779', '1578663', '26586766');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26753020', '空天猎', '剧情', '一场空天战场的猎杀传奇。霸天狼，一支神秘的空军顶级团队，每一名飞行员都是“金头盔” 级别的王牌飞行员，吴迪（李晨 饰）、亚莉（范冰冰 饰）、巴图（郭洺宇 饰）、高原（李晨浩 饰）通过层层考核，成为了霸天狼秘密基地的一员。可谁也没有想到，吴迪的好友浩辰（李佳航 饰）却在任务中陷入一场境外战乱的阴谋。更大的威胁接踵而至，恐怖势力突 发其来的导弹危机和人质危机，空前地挑战着中国空军的实战能力!十万火急之下，最新式 的中国战机和最顶级的飞行员，与掌握导弹密码和先进战机的敌人，在境外天空展开一场生死对决......', '李晨', '李晨', 5, 65213, 'tt6908536', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2499163778.jpg', 23, 28, 32.6, 10.7, 5.7, '-0.096790,0.106938,-0.759198,1.025143,0.242188,0.256099,0.467595,-0.221132,-0.312898,-0.248405,0.568172,0.556243,0.137594,-0.305829,0.256130,-0.455865,-0.065037,-0.618274,-0.199790,-0.063938,-0.532156,-0.422483,-0.734742,-0.060468,0.313867,-0.305379,0.938094,0.279539,-0.482746,0.281508,0.362557,0.429960,-0.131057,0.446969,-0.180034,-0.442386,0.400948,0.098784,-0.406279,0.307273,-0.419360,0.005773,-0.281496,0.397725,-0.118307,0.012569,0.746121,-0.571618,0.190035,-0.097005,-0.041880,-0.360249,-0.032622,-0.227093,0.737459,-0.076992,0.007427,0.041784,0.367725,0.361034,-0.017332,0.277214,-1.016486,-0.103825,-0.001101,-0.059613,-0.311624,0.433735,-0.524754,0.293736,0.023700,-0.036032,0.244741,0.487553,0.187237,0.190145,-0.487630,0.159312,-0.659997,0.252875,0.540407,-0.015534,-0.276709,-0.094423,0.101877,-0.598045,-0.490723,-0.585267,-0.280803,-0.020966,0.634532,-0.073541,0.066477,0.372451,-0.919125,0.291969,-0.252037,-0.399108,-0.119310,-0.181834,-0.123289,-0.866671,0.047683,-0.528453,-0.494039,0.371933,0.223414,0.000997,0.947597,-0.683665,-0.094169,0.284094,-0.078124,-0.239449,0.406372,0.113959,0.106459,-0.417168,-0.258962,-0.118863,-0.038392,0.346796,0.065720,0.433906,-0.036450,-0.317917,0.080550,0.232321', '10467125', '26290398', '25880986', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26754095', '火车司机日记', '剧情', '每个火车司机在职业生涯中会撞死20多人，这些死者通常是因为寻死、失误、酒醉或仅仅是一不小心而丧生。伊利亚是一名即将退休的火车司机，他共撞死了28人。他19岁的养子西玛继承了他的工作，西玛非常担心自己也会撞死人，而老司机们都安慰他说，一周内就会发生，但是几周过去后，没有发生一起撞人事故，而这也使得他精神极度紧绷。伊利亚为了帮助他，找到了许多想要自杀的人，让他们跳到车轨上自杀，但是最终这些人都放弃了自杀的念头。无奈之下，伊利亚自己躺在了车轨上想用自身的死来拯救西玛…', '拉扎尔·里斯托夫斯基', '米洛什·拉多维奇', 7.8, 6912, 'tt2948166', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2482781791.jpg', 0.3, 1.8, 25.5, 53.7, 18.7, '0.175085,-0.110769,-0.925783,0.272889,-0.387702,-0.311115,0.849161,-0.025530,-0.656573,-0.110086,0.419484,0.863380,-0.007940,0.370737,0.257486,0.078895,-0.313147,-0.542042,0.277576,-0.035735,-0.736149,-0.412016,-0.001774,-0.505438,-0.319353,-0.090220,0.423522,-0.041280,-0.116703,0.155500,0.401103,0.306367,0.396520,0.617426,-0.170371,0.269044,-0.323641,-0.311403,0.341752,0.179391,0.096106,-0.510227,-0.066794,0.293155,0.006990,0.464307,0.473098,0.063373,-0.233712,-0.135440,0.167367,-0.646389,-0.087673,0.123016,0.250373,-0.171325,0.243271,0.257387,-0.225449,-0.089141,0.240983,0.521235,-0.752949,0.175916,-0.298162,0.000645,-0.836822,0.239347,0.061407,0.074873,-0.017784,-0.361112,0.476922,0.495180,0.103522,-0.010516,-0.271904,-0.328844,-0.564316,0.083569,0.940157,-0.080281,-0.295353,0.331463,-0.224757,-0.150464,-0.089807,-0.290750,-0.300462,-0.006076,0.212907,0.154475,-0.552860,0.036328,-0.144789,0.031779,-0.361436,-0.299600,-0.552944,-0.224560,-0.002457,-0.220905,0.039720,-0.343600,-0.471041,0.000213,0.039159,-0.274715,0.475184,-0.595719,0.133525,0.666041,0.422464,-0.562955,0.614285,0.035343,-0.091794,0.229993,0.082096,0.194945,-0.140918,0.393137,0.101426,0.141177,0.103954,0.076511,-0.308218,0.507311', '1292064', '1309116', '1306801', '1292584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26754233', '八佰', '剧情', '1937年淞沪会战的最后一役，“八百壮士”奉命坚守上海四行仓库，以少敌多顽强抵抗四天四夜。电影《八佰》由管虎导演，是亚洲首部全片使用IMAX摄影机拍摄的商业电影，将于2020年8月21日全国影院上映。', '王千源', '管虎', 7.5, 772896, 'tt7294150', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2615992304.jpg', 1.6, 4.3, 30, 45.4, 18.7, '-0.788167,0.025708,-0.178128,0.108626,1.257639,0.158487,-0.043048,-0.338659,-0.306646,-0.038207,0.392155,0.251130,-0.565034,-0.226809,0.172858,-0.519201,-0.246448,-0.644117,-0.493987,-0.122829,0.316907,-0.051229,-0.418729,0.135719,0.037393,-0.149927,0.965297,0.882294,0.154099,0.278005,0.115666,-0.186031,0.015492,-0.148497,0.709050,-0.197492,-0.277271,-0.415161,-0.597529,0.731462,-0.327053,-0.606984,-0.623169,-0.485980,0.445226,0.138285,0.959933,0.172091,-0.006827,-0.134864,0.690108,-0.259419,-0.593330,-0.320910,0.491878,0.258599,0.331832,0.602129,-0.162410,-0.012975,-0.410356,-0.422756,-0.358547,0.107283,-0.176617,-0.255199,-0.455364,0.754334,-0.424967,0.802748,-0.099340,-0.355733,0.001156,0.437020,0.394085,0.280944,0.126929,0.118266,-0.349226,0.865617,0.297882,-0.394855,0.041304,-0.045581,0.653074,-0.744098,-0.256738,-0.671680,-0.244148,0.618986,-0.093682,-0.520431,-0.029332,-0.259712,-0.442672,0.100928,-0.252130,-0.814168,0.374447,0.075682,0.022832,-1.385009,0.000089,-0.225792,0.217372,-0.109308,0.359441,0.226795,0.667118,-0.578130,0.054733,0.525245,0.399009,-0.081628,1.256427,0.067939,-0.175889,0.077936,0.620336,0.134978,-0.401967,0.226321,0.279110,0.260021,-0.371512,-0.152472,-0.068387,0.254434', '24751811', '34961898', '30397916', '1294413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26754513', '人生密密缝', '剧情', '友子（柿园玲佳 饰）和母亲过着相依为命的生活，母亲常常徘徊在不同的男人之间，每天都喝到深夜才回来，友子虽然年幼，却早已经习惯了这样的生活。某日，母亲在丢下了生活费后又不知所踪，无奈之下，友子只能找到舅舅政男（桐谷健太 饰），暂时住在他的家里。在舅舅家，友子见到了政男的同居“女友”伦子（生田斗真 饰），伦子虽然拥有着柔软的胸脯，却是个货真价实的男人。在友子面前，伦子展现出了无限的温柔和体贴，渐渐让友子找回了缺失的母爱，三个人组成了一个奇异却充满了温暖的家庭。可爱乖巧的友子让伦子渐渐产生了想要将她永远留在身边的念头，可就在此时，友子的母亲回来了。©豆瓣', '生田斗真', '荻上直子', 8.5, 52141, 'tt5633706', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2385400300.jpg', 0.2, 0.9, 12.4, 48.2, 38.3, '-0.007224,0.283677,-0.878171,0.449907,-0.146591,-0.594327,0.958572,0.219975,-0.446629,-0.183806,0.122713,0.594893,-0.082509,0.754862,0.065484,-0.009850,-0.198795,-0.664634,-0.070277,-0.186425,-0.392947,-0.322929,-0.081706,0.143213,-0.147673,-0.287369,0.507451,-0.034810,0.077105,0.381867,0.196643,0.110475,-0.162005,0.764818,-0.540991,0.316281,-0.101949,0.120947,-0.024987,0.099863,0.227473,-0.271986,-0.068035,0.236118,0.128148,0.264205,0.907126,-0.333104,-0.314776,0.267727,0.223698,0.051941,-0.232532,0.142112,0.224699,-0.010774,0.231368,-0.139551,-0.501728,0.066417,0.244616,0.059702,-0.536094,0.070401,-0.011335,0.155018,-0.867709,0.585187,0.082533,-0.331961,0.295446,-0.668811,0.249860,0.248677,-0.180390,0.673892,-0.539942,0.402447,-0.359866,0.099918,0.724005,0.073224,0.043935,0.459013,-0.414600,-0.240588,-0.085589,-0.242462,-0.521320,-0.094855,0.096509,0.192480,-0.291435,0.121081,-0.634959,-0.112138,0.214495,0.009215,0.122686,-0.746762,-0.078536,-0.094592,-0.077455,-0.657568,-0.619892,0.531952,0.061421,-0.226298,0.878680,-1.027437,0.326619,0.664280,0.401042,-0.133053,0.430447,0.076597,0.039517,-0.136096,0.076911,0.385441,-0.178861,0.330131,0.561472,0.536523,-0.292520,0.118653,-0.634677,0.696492', '1292219', '1299965', '21360412', '11611021');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26754643', '少年', '悬疑', '电影讲述的是一个经历残酷青春的少年为爱复仇不惜付出生命的故事。成长于福利学校的少年苏昂（欧豪 饰）与女孩林巧（郭姝彤 饰）相依为命，彼此取暖，然而受尽欺凌与屈辱。当少年一路野蛮成长，蜕变成为电脑天才，坏人也并未变老，于是苏昂开始编织自己的复仇计划。一具被发现的白骨引 起小镇的轰动，刑侦队长张建宇（张译 饰）接手此案，展开调查。在案件的艰难推进中，一个个身份各异的人也被卷入此案：稀里糊涂的酒鬼，一心想发横财的屠夫申哥（周一围 饰），风流倜傥的音乐家李志民（郭晓东 饰），性感的脑科医生韩云（余男 饰）......当迷局浮出水面，谁是真正的罪人？©豆瓣', '欧豪', '杨树鹏', 5.7, 22421, 'tt6419442', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2403546172.jpg', 5.8, 26.4, 48.1, 16.1, 3.6, '0.008413,-0.238239,-0.215501,0.304764,-0.241431,-0.236547,0.758957,0.083886,-0.507962,-0.075682,0.350437,0.506097,-0.143119,0.138428,0.328227,-0.089109,-0.119760,-0.767443,-0.089157,0.144260,-0.084120,-0.251703,-0.260381,-0.286897,0.039443,-0.308852,0.757149,0.156062,-0.167429,0.393620,0.563774,0.106961,-0.372688,0.183022,-0.117250,-0.038518,0.066625,0.133367,-0.275415,-0.053942,-0.268179,-0.405495,-0.138492,0.001699,-0.496792,0.153622,0.932616,-0.164584,-0.083421,-0.466197,0.596943,-0.403478,-0.143649,-0.024557,0.170498,0.286504,0.135993,0.269620,-0.003494,0.016092,0.153462,-0.230538,-0.692876,-0.138617,0.210436,0.170707,-0.469408,0.299321,-0.007132,0.047179,0.244780,-0.210725,0.050026,0.085791,0.436621,0.405759,-0.181910,0.006851,-0.366411,0.511105,0.446260,0.058850,-0.241575,0.324682,-0.271576,-0.362659,-0.133179,-0.205944,-0.541652,-0.039661,0.166140,-0.015364,-0.166079,0.395420,-0.483120,-0.103068,-0.316665,-0.017095,0.081954,-0.188424,-0.301053,-0.285434,-0.361450,-0.148704,-0.251692,0.016976,-0.002832,-0.392159,0.816157,-0.539690,0.054368,0.285637,0.027245,-0.568057,0.457005,0.045197,0.080104,-0.376212,-0.087529,0.419874,-0.043099,0.163363,-0.039578,0.213149,-0.331080,0.009967,-0.332755,0.242208', '26759820', '3811356', '10467125', '4268598');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26754675', '行走距离', '剧情', '因身体肥胖而行动困难的费德每天只能待在家里过着单调乏味的生活，真到有一天他的姐夫拉蒙给他看了他们外出旅游时拍的照片。这激发起费德对摄影的浓厚兴趣。在相片冲洗店里，费德遇到了店主的儿子，一个酷爱漫画书的孤独少年保罗。费德慢慢地发现摄影对他来讲已经不只是一个爱好，而是成了他生命的寄托。三个人的友谊也在交往中不断深化，并彻底改变了他们的生活。', '卢卡·奥尔特加', '亚历山卓·古兹曼·阿尔瓦雷斯', 8.4, 16779, 'tt5048966', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2326535463.jpg', 0.2, 0.9, 14.1, 49, 35.8, '0.405154,-0.172170,-0.700989,0.683753,-0.458086,-0.484719,1.118307,0.193335,-0.229842,-0.153891,0.124861,0.897229,0.040937,0.396956,0.206063,0.108677,-0.277734,-0.759191,0.004072,0.039695,-0.464947,-0.254990,-0.040905,-0.497640,-0.191687,-0.337349,0.365082,-0.010124,-0.178268,0.365536,0.104500,-0.142570,0.281885,0.738080,-0.486535,0.058736,-0.208875,0.097212,-0.059161,0.161838,0.316095,-0.354510,-0.212151,0.289104,-0.046798,0.363568,0.814371,0.011769,-0.255169,0.040388,0.277116,-0.177574,-0.146288,-0.030437,0.200428,-0.023800,0.136212,-0.044627,-0.177811,0.026293,-0.008435,-0.013276,-0.806351,-0.089617,-0.141113,0.274042,-0.736226,0.999708,0.075007,-0.122586,-0.105732,-0.411811,0.084993,0.313345,0.057900,0.393349,-0.155255,-0.076489,-0.536353,0.336737,0.465158,0.035094,-0.380692,0.823733,-0.492994,-0.293906,-0.068515,-0.014171,-0.554301,-0.237733,0.275749,-0.009871,-0.517692,0.138027,-0.677148,0.198729,-0.019082,-0.404326,-0.085908,-0.546265,-0.015973,-0.593208,-0.300283,-0.739183,-0.510013,0.206076,0.133546,-0.381323,0.738221,-0.729466,0.120638,0.869935,0.193197,-0.425082,0.845310,0.248358,-0.009342,-0.076765,-0.130390,0.300894,-0.061740,0.478109,0.255301,0.600172,0.231878,0.023743,-0.451791,0.785777', '1309172', '3534824', '1783772', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26754831', '绝世高手', '喜剧', '一个先天没有知觉，挨揍不疼却冒充高手的小混混（卢正雨 饰），一个人称女张飞的暴力少女（郭采洁 饰），一个醉心于织毛衣的过气大师（范伟 饰），一个只会做黑暗料理的美食大亨（蔡国庆 饰），一个可以用汤操纵情绪的当代孟婆（陈冲 饰），一个身患强迫症的日本武士（仓田保昭 饰），为了一本失传的秘笈，引发了一场绝世高手的爆笑对决。', '卢正雨', '卢正雨', 5.9, 81321, 'tt7121588', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2462744662.jpg', 8.6, 22.2, 42.6, 19.6, 7, '0.435093,-0.139480,-0.062450,0.795936,-0.189469,0.011972,0.899390,0.163520,-0.118779,-0.663865,0.590192,0.803351,-0.051389,0.025325,0.065072,-0.372444,0.487082,-0.545804,0.210122,0.121575,-0.158255,0.143826,-0.701323,-0.097277,-0.307199,-0.345522,0.562236,-0.083689,-0.467342,0.237208,0.540949,0.030727,0.298910,-0.164001,-0.168924,-0.252106,0.290745,-0.220596,0.085605,0.379366,-0.277158,-0.271987,0.263745,0.228776,-0.468960,0.249906,0.584486,-0.257551,0.316197,-0.235993,0.288802,-0.146076,-0.335400,0.032617,0.151403,-0.097992,0.217758,-0.297860,0.015763,0.040086,0.416221,0.075098,-1.068132,-0.238161,0.448903,0.305898,-0.034922,0.427248,-0.109731,-0.187346,-0.521001,-0.227783,0.054378,-0.120418,0.438384,0.402521,-0.033943,0.009719,-0.439156,0.832865,0.277905,-0.032214,-0.074390,0.504704,-0.014468,-0.439383,-0.142400,-0.649195,-0.625384,-0.130841,0.351113,-0.521548,-0.022135,-0.266636,-0.581083,-0.090238,-0.177991,0.097826,-0.272365,0.062528,-0.155662,-0.271850,0.200045,-0.164088,-0.171714,0.134222,0.449797,0.031073,1.043820,-0.462595,-0.004602,0.235041,-0.277657,-0.301926,0.464005,0.176813,-0.178955,-0.100568,-0.261152,0.218361,0.100754,-0.058042,-0.019397,0.728996,-0.097489,-0.159606,-0.272690,0.071494', '27602116', '24284209', '4267948', '3603547');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26755037', '拍得不错', '剧情', '由五個單元故事組成的GOOD TAKE，是香港電影新一代導演的創新作品，包括導演曾國祥《水泥》，講述警員9413（周柏豪）前往報案地點查案，最後只留下電話鈴聲卻不見其人，令人毛骨悚然；導演黃智亨的《囍宴》，一個小孩跟著跟爸爸（張兆輝飾）一起前赴媽媽新婚囍宴的故事，童真與成年人的無奈都盡在心頭；導演黃進的《Good Take》，透過甘草演員泰勒(盧海鵬飾)的生活是向資深電影從業員致敬的故事；導演楊龍澄的《不一定》，以型格對比色彩重構暴力血腥鏡頭；導演黃精甫的《嚇鬼》，Charlene（蔡卓妍飾）挑戰鬼屋一夜遊，遇上中國殭屍、長髮貞子和辮子姑娘，過程又驚又笑！五個故事各自有著不同風格及不同戲味！', '方中信', '曾国祥', 6.1, 6853, 'tt5798738', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2357779538.jpg', 4.2, 17.9, 54, 19, 4.9, '0.292190,-0.616925,-0.454587,0.528268,0.264569,-0.129370,0.886034,0.283137,-0.278543,-0.135739,0.119004,0.736057,-0.366125,0.423426,0.374523,-0.148909,-0.322919,-0.643338,-0.357138,-0.163474,-0.108773,-0.501079,0.314488,0.086028,0.127343,-0.344450,0.337935,-0.202335,-0.228259,0.548212,0.394928,0.160184,-0.536570,0.281848,-0.410515,-0.007297,-0.206039,0.361272,-0.568360,-0.188918,0.271356,-0.115230,-0.322422,-0.156257,-0.004531,0.078375,0.595485,-0.344153,-0.036055,-0.085173,0.205190,0.015643,0.009659,0.019980,0.152149,0.137282,0.534035,0.412488,0.215850,-0.131972,0.091172,-0.213263,-0.527707,0.225558,0.513872,0.345677,-0.409034,0.490471,0.026300,-0.195958,0.275525,-0.214044,0.377003,0.085088,0.277691,0.695507,0.100063,0.186846,-0.607429,0.099576,0.725508,0.546860,0.092552,0.544168,-0.191448,-0.517718,-0.120540,-0.057136,-0.440349,0.458556,-0.228113,-0.178760,0.082870,0.423210,-1.000693,0.106121,0.052006,-0.110146,0.229137,-0.365136,-0.070031,-0.661581,0.023170,-0.499727,-0.136733,0.013956,0.409699,-0.242496,0.813008,-0.559293,0.168923,0.297375,0.153741,-0.412614,0.817160,0.294621,-0.085335,-0.088333,0.007448,-0.120616,0.046747,-0.101525,-0.057063,0.574746,0.117618,-0.163359,-0.654266,0.548362', '1394176', '1309101', '3055049', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26755583', '西尔玛', '剧情', '一名从乡下搬到奥斯陆展开大学新鲜人生活的挪威女孩席玛，单纯而天真的她，内心有着坚强的信仰与管教严格爸妈的谆谆教诲。在入学后，与非常美丽的同学安雅有着深厚友谊，但却在一次图书馆癫痫事件后，她开始发现自己拥有令她爸妈向来畏惧已久的超能力。随着学期持续， 席玛对安雅的好感也越来越强烈，但突如其来的神秘事件越来越多，席玛开始发现她的超能力与家族的祕密有关，必须被迫去面对她过去悲剧性的秘密，以及那骇人超能力的后果。', '艾丽·哈尔博', '约阿希姆·提尔', 6.7, 6434, 'tt6304046', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2498381107.jpg', 2.1, 10.2, 48.5, 29.9, 9.2, '0.128354,0.133860,-1.018621,0.743335,-0.131780,0.061948,0.835648,-0.023792,-0.732872,-0.357652,0.093097,0.601066,-0.049332,0.298565,0.218250,-0.225722,-0.109629,-0.395903,0.206116,-0.309969,-0.376906,-0.370291,-0.112669,-0.210836,-0.074699,-0.689431,0.675063,0.069359,-0.363648,0.438225,0.075630,0.434019,-0.021589,0.644152,-0.197589,-0.294426,0.073390,0.272530,-0.261832,-0.035993,0.448350,0.009964,-0.334473,0.199698,-0.085382,0.155810,0.490657,-0.218048,-0.591139,-0.022434,0.701999,-0.093117,-0.374509,0.152486,0.502800,0.225684,0.097826,0.308808,0.024823,0.012858,-0.089890,-0.086333,-0.428122,0.051735,0.215036,-0.027151,-0.525938,0.497233,0.079794,-0.166357,0.164598,-0.375115,-0.156169,0.325237,-0.074697,0.410022,-0.304247,0.129618,-0.330098,-0.227125,0.837599,-0.002898,-0.490834,0.442073,-0.425464,-0.411275,-0.114878,-0.354904,-0.340790,0.147895,0.147015,0.181326,-0.318961,0.536455,-0.729040,0.145279,-0.017372,-0.119860,-0.010478,-0.536219,-0.151562,-0.478423,-0.365588,-0.561695,-0.370266,0.144936,0.071281,-0.413405,0.988984,-1.037854,0.279082,0.632914,0.246790,-0.530092,0.352223,0.108098,-0.008633,-0.133236,-0.451719,0.365107,-0.039864,0.348361,-0.129652,0.485679,-0.067160,0.045456,-0.210764,0.737778', '1870682', '35030151', '21360412', '5977789');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26756049', '我，花样女王', '剧情', '托尼亚（玛歌特·罗比 Margot Robbie 饰）成长在一个破碎的家庭之中，和母亲（阿丽森·詹尼 Allison Janney 饰）过着相依为命的日子。托尼亚的母亲是一个冷若冰霜而又独断专行的女人，她在年仅3岁的托尼亚身上看到了她成为一名花滑运动员的潜力，就这样，小小的女孩被送往了由戴安（朱丽安妮·尼科尔森 Julianne Nicholson 饰）执教的花滑队里，开始了训练。托尼亚的全部童年几乎都是在冰上度过的，直到有一天她在溜冰场遇见了名为杰夫（塞巴斯蒂安·斯坦 Sebastian Stan 饰）的男子，两人很快就坠入了爱河。杰夫改变了托尼亚的人生，却也成为了她的灾难，从此托尼亚要面对的，除了日益艰巨的训练外，还有来自杰夫的拳脚。在一场比赛中，托尼亚完成了冰上三圈半的跳跃动作，成为了美国第一个完成了这个动作的运动员，托尼亚因此名声大噪。©豆瓣', '玛格特·罗比', '克雷格·吉勒斯佩', 7.9, 67932, 'tt5580036', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2508862676.jpg', 0.2, 1.2, 19.7, 59.6, 19.3, '0.258649,0.175390,-0.509619,0.289180,-0.281809,-0.489608,0.739599,0.221885,-0.437764,0.063490,0.557211,0.793212,-0.306527,0.178115,0.480187,0.099402,-0.376433,-0.821234,-0.198836,-0.021050,-0.586657,-0.322129,-0.297907,0.118031,-0.127875,-0.619607,0.440982,-0.033995,0.023990,0.518837,0.185301,0.239291,0.182827,0.157976,-0.286267,0.069432,0.239245,0.051241,-0.032546,0.458428,-0.045292,-0.232679,-0.208925,0.009994,0.041549,0.490674,0.619871,-0.266611,0.244685,-0.160657,0.098916,-0.301755,-0.025768,-0.040920,0.261501,0.060815,-0.028566,0.269144,-0.468852,0.165709,0.187861,-0.197646,-0.597291,0.095111,0.246920,0.239778,-0.919209,0.610730,-0.132844,-0.300764,-0.020746,-0.383516,-0.070025,0.485102,-0.172163,0.568976,0.001983,0.212431,-0.603702,0.173608,0.559484,-0.216088,-0.577080,0.169365,-0.171330,-0.444424,-0.252212,-0.369371,-0.318585,-0.061044,0.335389,0.016220,-0.015754,0.574043,-0.674018,0.339591,-0.372507,-0.389574,-0.004407,-0.419475,-0.272957,-0.543528,0.124943,-0.353057,-0.312331,0.079874,0.140445,-0.234446,0.706414,-0.823784,0.453705,0.559964,0.130555,0.020841,0.568628,0.160822,0.243350,-0.258406,-0.006122,0.524264,-0.119400,0.360264,0.052118,0.559400,0.020603,-0.183449,-0.520097,0.860036', '4301274', '26