INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26756258', '狐步舞', '剧情', '以色列军人敲开一个中产阶级家庭的门，宣布他们的士兵儿子阵亡，妻子晕倒，丈夫陷入无处躲避、只有依靠自残来发泄的悲痛中，夫妻俩伤心欲绝，方寸大乱，正在接受现实、安排葬礼的时候，军方又发来通知，刚才通知错了家庭，牺牲的另一个和他们儿子同名同姓的战士。悲极生乐，父亲却没有彻底放心，动用关系让军方赶紧把自己儿子从边境撤回来。没想到，回家途中又生变数，然而事情却又一波三折，发生意想不到的转折。', '利奥尔·阿什肯纳齐', '塞缪尔·毛茨', 7.8, 8162, 'tt6896536', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2497789022.jpg', 0.7, 2.4, 24.5, 52.4, 19.9, '0.054927,-0.094060,-0.637189,0.359070,-0.154741,-0.166624,0.657216,0.063227,-0.503384,-0.565406,0.166279,0.621246,0.162098,0.111860,0.318766,-0.413032,-0.282384,-0.690675,0.027507,-0.027451,-0.334942,-0.355449,0.177742,-0.380653,0.111963,-0.172416,0.607635,0.012540,-0.251628,0.376484,0.218036,0.286367,-0.198401,0.623993,0.125904,0.310189,-0.056152,0.124264,-0.360311,0.093737,0.046961,-0.013915,-0.003536,0.425997,-0.014158,0.519466,0.353931,-0.129164,-0.158074,-0.250434,0.289754,-0.227168,-0.160310,0.205379,0.266089,-0.041878,0.076363,-0.019185,-0.220455,-0.377337,0.130768,0.236200,-0.851774,0.159930,0.168265,-0.086583,-0.653087,0.252547,-0.194072,0.155449,0.266444,-0.175564,0.382255,0.693693,0.335213,0.617204,-0.386974,0.141471,-0.312790,-0.089335,0.943913,-0.389554,-0.111587,-0.014521,-0.273283,-0.259760,0.402669,-0.473127,-0.424412,0.224049,0.112618,0.178799,-0.330373,0.113998,0.079939,-0.120476,-0.467513,-0.208486,-0.053425,-0.642382,-0.019638,-0.295790,-0.007196,0.468127,-0.376768,0.281049,0.026237,-0.011000,0.622360,-0.363308,0.125444,0.379368,0.452845,-0.792212,0.475660,0.226571,0.233693,-0.429136,0.269287,0.152646,0.102886,0.313830,0.049047,-0.289426,-0.336213,-0.126083,-0.134790,-0.053959', '26678784', '1877596', '25721544', '4145476');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26756259', '二十岁', '剧情', '刘达（屈楚萧 饰）、林一木（叶子诚 饰）、符号（孔垂楠 饰）是高中三人组死党,随着高考的结束, 平静的生活开始有了不同。高考分数公布的当天,刘达偷了老爸的车和林一木四处寻找落跑的符号,偶遇烧烤摊老炮, 开启了各自的青春启蒙, 誓要让自己的20岁闪耀人群。日子就这样过去,三人就这么走过了20岁,纵然人生和计划完全相反,甚至乱七八糟,可是又滋生出新的生活养料,鼓舞他们走向更远的人生。', '屈楚萧', '刘畅', 3.8, 2692, 'tt7827390', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2541193765.jpg', 43.7, 32.9, 16.5, 3.2, 3.8, '0.256585,-0.259031,-0.379305,0.505979,-0.057441,-0.352536,0.408229,0.162082,-0.204754,-0.103202,-0.004534,0.371232,-0.496160,0.497971,0.360088,-0.345839,-0.262403,-0.818701,0.072787,-0.152858,-0.228230,-0.368489,0.227964,-0.130761,0.076508,-0.107245,0.731649,0.235179,0.071542,0.684423,0.043578,-0.048577,0.115714,0.224215,-0.408934,0.178448,-0.124350,0.425403,0.018152,-0.118320,0.067620,-0.398660,-0.050982,0.072598,0.061992,0.297274,0.891717,0.096643,-0.126865,0.126643,0.548977,-0.277926,-0.273947,0.148803,0.329549,0.211689,0.020340,-0.111516,-0.020399,0.145333,-0.366704,-0.301669,-0.380395,0.084597,-0.026466,0.048955,-0.355172,0.485682,0.189185,0.001574,0.253337,-0.073453,0.194113,0.413609,0.226782,0.426950,-0.281050,-0.081048,-0.480256,0.345162,0.508978,-0.240923,-0.256241,0.436260,-0.271075,-0.283295,-0.173569,0.033523,-0.196804,-0.174587,0.213949,0.155862,-0.068472,0.110159,-0.713634,0.077345,-0.014703,-0.165000,0.373072,-0.404023,-0.184917,-0.592852,-0.097499,-0.289507,-0.428980,0.346399,0.015017,-0.363390,0.801996,-0.595329,0.200335,0.122882,0.161977,-0.494532,0.462629,-0.199028,0.004989,-0.327816,0.260800,0.313103,-0.143540,0.355499,-0.106824,0.455186,-0.005262,-0.042155,-0.546413,0.662475', '5403927', '3811356', '26365262', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26757373', '捉迷藏', '悬疑', '城市里流传着一个奇怪的传言。有一些流浪在外居无定所的人会偷偷潜入别人的家里，把自己隐藏起来，然后生活下去……张家伟（霍建华 饰）是一家咖啡厅的老板，和妻女居住在一个高档小区里，生活富足，家庭和睦，不过他却患有严重的洁癖和强迫症，终日饱受心理疾病的折磨，一天，他接到了哥哥失踪询问电话，神经一下子紧张起来。到旧公寓寻找哥哥未果的家伟结识了跟哥哥居住在同一层的苏红（秦海璐 饰）母女，苏红对张家伟的哥哥表现出异常的恐慌和反感，失踪案件变得扑朔迷离。与此同时，张家伟的妻女和家忽然间成为一个“神秘人”的袭击目标，张家伟一边抵挡着“神秘人”对家人的袭击，一边寻找哥哥，由此一步步揭开了一个隐藏在他心中多年的秘密……', '霍建华', '刘杰', 5.4, 44429, 'tt5662906', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2392969596.jpg', 11, 28.1, 44.3, 12.5, 4.1, '0.345967,-0.165985,-0.695414,0.633365,-0.032526,-0.020220,0.977400,0.199919,-0.577218,-0.361824,0.100336,0.809991,-0.047199,0.600403,0.167807,0.035484,-0.283702,-0.523901,-0.098436,-0.109699,-0.309436,-0.421556,-0.356547,-0.483518,-0.001359,-0.349863,0.063018,0.380946,-0.373951,0.466792,0.102449,0.465831,-0.501832,0.500557,-0.328936,0.095652,0.088474,0.214216,-0.199390,0.075870,0.236580,-0.224955,-0.129041,0.362947,0.261788,0.415335,0.610331,-0.048157,-0.479577,0.034643,0.203005,-0.147502,-0.340544,-0.131677,0.451654,0.013505,0.313390,0.272000,-0.354219,-0.050238,-0.033163,-0.019177,-0.594204,0.042474,0.322504,0.183943,-0.620985,0.389781,-0.036820,-0.119800,-0.108009,-0.476352,0.559607,0.388463,-0.105468,0.475753,-0.230704,0.250852,-0.557594,0.075504,0.907680,-0.131737,0.093115,0.010981,-0.205738,0.023604,0.006409,-0.017241,-0.853365,-0.266480,0.312694,-0.229421,-0.257997,0.051361,-0.452810,0.098701,-0.170692,0.015645,0.211882,-0.423308,-0.293151,-0.349585,-0.144959,-0.397660,-0.227963,0.323098,-0.122888,-0.333461,0.528229,-0.758366,0.239245,0.310732,0.378499,-0.763634,0.387497,-0.142752,0.086805,-0.124656,-0.115176,0.046907,0.187737,0.188948,0.043365,0.283138,-0.322883,0.067202,-0.404797,0.285733', '1296534', '25721544', '1308755', '2002744');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26757826', '花芯', '剧情', '在父母亲的安排之下，园子（村川绘梨 饰）嫁给了名为雨宫（林遣都 饰）的青年，从此告别了少女时代，步入了家庭主妇的行列。然而，园子的内心里对于雨宫没有丝毫的感情，她的丈夫对于她来说，不过是和自己住在同一屋檐下的陌生人而已。即便如此，园子还是和雨宫发生了肉体关系，并且怀上了雨宫的孩子。十个月之后，园子成为了母亲。之后，工作上的变动让雨宫一家人来到了京都生活。一次偶然中，园子结识了雨宫的上司越智（安藤政信 饰）。在一来二去的交往之中，园子被风度翩翩温文尔雅的越智所吸引，而越智亦在园子的身上发现了寂寞的气息，最终，两人越过了伦理道德的那条界限。©豆瓣', '村川绘梨', '安藤寻', 6.1, 7221, 'tt5741848', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2378200165.jpg', 4.3, 19.5, 49.3, 19.3, 7.6, '0.708530,0.193367,-0.477961,0.527276,-0.177825,-0.351814,0.836310,0.508668,-0.832070,-0.227025,0.056926,0.572649,-0.273284,0.504864,0.090130,-0.141787,-0.163988,-0.670445,-0.329869,-0.407880,-0.518411,-0.389154,-0.065968,0.107645,-0.317230,-0.177427,0.723519,0.238031,0.002207,0.411770,0.247827,0.161722,-0.173187,0.483626,-0.256802,0.107964,0.127709,0.299871,-0.157671,0.383615,-0.190118,-0.301888,-0.174612,0.218627,0.320232,0.406985,0.840206,-0.141486,-0.210030,-0.141155,0.373867,0.156143,0.149006,0.238152,0.414623,-0.092872,0.350207,0.416981,-0.153763,0.009286,0.171643,-0.154318,-0.390993,0.161394,0.221229,-0.082652,-0.713518,0.701769,0.251293,-0.464627,0.066766,-0.396106,0.285373,0.350530,0.439974,0.321162,-0.390374,0.206040,-0.438042,0.114456,0.684188,0.175293,-0.176685,0.632113,-0.422177,-0.486722,-0.429199,-0.276153,-0.370626,-0.201056,0.081707,0.365380,-0.379360,0.004996,-0.413823,-0.052658,-0.074725,-0.180128,0.069112,-0.628453,0.037852,-0.561148,-0.281097,-0.674871,-0.719704,0.259858,0.220023,-0.115348,0.591144,-0.978910,0.263375,0.502726,0.281150,-0.230816,0.871885,0.008670,0.034058,-0.006582,0.323166,0.221820,0.057632,0.358011,0.219129,0.625303,-0.445592,-0.003909,-0.595510,0.521715', '1302384', '1306544', '2052978', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26757945', '一天', '剧情', '因事故而痛失女儿的父亲将这“一天”不断重复，只为能挽救女儿。一天之中有哪些秘密尚待揭开，寻踪觅迹的故事尽在影片《一天》。金明民饰演世界知名胸部外科专家“金俊明”。只为救助一人生命都会用尽全力却是“零分老爸”。亲眼目击女儿因事故死去的场景后，为能收回覆水，循环往复的“一天”中誓死拼争。卞耀汉饰演救护车司机“李民哲”，申惠善饰“民哲”妻子“美京”，赵恩亨饰演“金俊明”女儿“恩静”。', '金明民', '赵善浩', 7.1, 14572, 'tt6890376', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2459290922.jpg', 0.9, 4.6, 42.2, 41.3, 11, '-0.783851,0.187631,-0.300099,0.230731,0.130734,-0.085206,0.513224,-0.025359,-0.624563,-0.294978,0.434214,0.533439,0.109926,0.308078,0.340001,-0.143475,-0.014895,-0.538091,-0.050007,-0.095362,-0.331007,-0.176903,-0.205052,-0.329439,0.141997,-0.402171,0.546142,0.125012,0.099509,0.020800,0.238192,0.157303,-0.460864,0.096879,-0.029425,0.142192,-0.119457,0.029868,-0.467877,0.250502,0.278253,-0.265770,-0.185133,0.080006,-0.487721,0.226266,0.880045,-0.081294,-0.157767,-0.465517,0.428796,-0.041214,0.105035,0.001288,0.065844,0.177589,0.646300,0.531207,-0.131152,-0.103925,0.106868,0.070700,-0.644411,-0.434147,0.174131,0.042057,-0.511204,-0.026859,-0.077764,-0.026027,0.191241,-0.080213,0.192695,0.064944,0.348077,0.511151,-0.394776,-0.034476,-0.115967,0.529745,0.388615,-0.229626,0.287797,0.622105,-0.080667,-0.256611,-0.019377,-0.413583,-0.635356,0.374136,0.134318,0.180297,-0.236290,0.097135,0.101769,-0.222096,-0.335499,-0.088691,0.009583,-0.150126,0.011458,-0.054695,0.296533,0.339923,0.039741,0.087734,0.048066,-0.362221,0.708174,-0.274498,0.328282,0.478221,0.046821,-0.286816,0.583666,0.359362,0.288055,-0.300682,0.196191,0.298943,-0.140913,-0.006500,-0.134668,-0.306522,-0.126864,0.078965,-0.408220,0.435101', '25738406', '26754643', '4151284', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26757951', '会痛的十七岁', '爱情', '夏远远（徐娇 饰）是一名十七岁的高中生，因为患有先天性痛觉是绝症，所以性格非常的孤僻和古怪，不爱交际的她成绩在班上也是吊车尾的水平，只有同样融入不到集体中去的二次元男孩罗涛（鲁诺 饰）稍微和她走的近一点。班上来了一位新的班主任名叫李米（蔡卓妍 饰），她似乎有着和前任大相径庭的教育理念。在李米的坚持之下，夏远远和名为顾明耀（胡夏 饰）的男生成为了同桌，顾明耀品学兼优，是班上无数人眼中的天之骄子，这两个八竿子打不到一起的人走到一起后，会发生那些有趣的故事呢？©豆瓣', '徐娇', '彭发', 3.1, 5233, 'tt10393846', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2496403125.jpg', 66.5, 20.7, 7.6, 2.5, 2.5, '0.282700,-0.336206,-0.724064,0.741719,-0.460965,-0.124609,0.751130,0.178627,-0.663454,-0.313816,-0.183763,0.775389,-0.271825,0.575471,0.247021,-0.254335,0.003607,-0.820876,-0.272199,-0.443877,-0.604998,-0.420224,-0.042592,-0.085087,-0.301108,-0.224039,0.540519,-0.198849,-0.333873,0.513119,0.516489,0.335734,0.015622,0.319709,-0.367517,-0.004801,-0.101744,-0.027029,0.249556,0.243592,0.047883,0.138806,-0.195168,-0.015404,0.065566,0.454916,0.567693,-0.009833,-0.256679,-0.037952,0.453333,0.004471,-0.305391,0.089953,0.686203,-0.081638,0.478247,-0.063866,0.144231,0.091705,0.061130,0.031685,-0.663162,0.167608,0.167887,0.186888,-0.804617,0.416852,0.260446,-0.491346,0.272753,-0.333133,0.355407,0.247042,0.100933,0.404848,-0.128677,0.004182,-0.592420,0.164426,0.719266,0.373106,-0.394230,0.376314,-0.268327,-0.529126,-0.452569,-0.339476,-0.491865,0.088386,0.146911,0.007713,-0.019100,-0.021089,-0.513015,0.036462,0.196365,-0.009020,-0.123806,-0.471710,0.044056,-0.422399,-0.011491,-1.078625,-0.423841,0.207878,-0.061776,-0.532427,1.081495,-0.953949,0.047035,0.410817,0.125069,-0.382606,0.817161,0.142256,-0.016028,-0.085346,-0.131741,-0.030164,-0.062051,0.123872,0.056792,0.716531,-0.044574,-0.307638,-0.477610,0.571374', '26354526', '26283288', '1438708', '1390020');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26759539', '十万个冷笑话2', '喜剧', '拥有着强大力量的创世神杖被四大神之一的埃及神拉（李璐 配音）盗走。为了令宇宙免于被毁灭的悲惨命运，希腊神宙斯（藤新 配音）派出了自己的女儿雅典娜（山新 配音）追踪神杖的下落。小金刚（皇贞季 配音）是自幼生长在孤儿院里的平凡少年，常年凭借着机灵的脑瓜靠着坑蒙拐骗赚钱度日，只为了有朝一日身患重病的青梅竹马小青（C小调 配音）能够康复。一次偶然中，小金刚得到了藏有创世神杖下落的藏宝图，随后遭到了雷神托尔（李姝洁 饰）的伏击，在争抢之中，藏宝图被破坏，就这样，小金刚成为了唯一一个知道创世神杖在哪里的凡人。就这样，小金刚、雅典娜、托尔，再加上一个来自东方的脱线河神（郝祥海 饰），一行四人踏上了寻找创世神杖的旅途。©豆瓣', '山新', '卢恒宇', 7.3, 97471, 'tt7490280', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2492917402.jpg', 1.7, 6, 33.9, 41.5, 16.9, '0.136755,0.349729,-0.593593,0.747269,-0.229595,-0.108672,0.436350,0.040112,-0.307990,-0.262429,0.373836,0.891611,0.049631,0.159380,0.064614,0.244593,0.107269,-0.382501,-0.051488,0.093704,-0.356736,-0.110458,-0.476764,0.086208,-0.281846,-0.500960,0.508044,0.030582,-0.176552,0.112407,0.251386,0.341052,-0.407938,0.017689,-0.432968,0.092029,-0.080632,0.040215,0.180198,0.570106,0.007274,-0.209636,0.169282,0.305305,-0.376411,0.181458,0.605940,-0.567990,0.299576,-0.486522,0.366254,-0.249743,-0.314957,-0.002693,0.238301,0.071856,-0.005720,-0.000869,-0.283591,0.173429,0.332904,0.033587,-1.025221,-0.165544,0.097716,0.049830,-0.614523,0.224031,0.089958,-0.319529,0.105295,-0.357987,0.423496,0.360467,0.341390,0.379003,-0.267873,-0.116641,-0.500822,0.295878,0.471675,-0.401896,-0.271076,0.188129,0.041154,-0.463001,-0.039695,-0.481962,-0.293648,-0.111047,0.665547,0.143345,0.126212,0.125032,-0.630566,0.082077,-0.265980,-0.128235,-0.205030,-0.400027,-0.090442,-0.344037,-0.104043,-0.160226,-0.055504,-0.030247,0.213539,-0.378971,0.633310,-0.749196,0.360954,0.612810,0.189390,-0.239423,0.509299,0.042350,0.129350,-0.264168,0.042864,0.384821,0.250867,0.395818,0.089386,0.076367,0.147129,-0.079429,-0.469861,0.544426', '1793491', '1308585', '27098364', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26759783', '救僵清道夫', '喜剧', '香港開埠以來，一直有殭屍出沒。城市隱藏著一個捉殭屍的秘密組織— 食環署特別行動組，簡稱VCD。半夜掃街的清道夫其實是殭屍獵人，巨大的垃圾桶裡藏著剛收伏的殭屍，旁人避而遠之的垃圾房…正正就是他們秘密基地！善心宅男張春天（蔡瀚億飾）偶然被VCD打救，組織領頭（吳耀漢飾）發現他的血能抗屍毒，認定其潛力無限，要武功高強的打手葉之秋（錢小豪飾）、技術支援組老姜（袁祥仁飾）與大舊駒（羅莽飾）向他傳授畢生所學，繼承組織使命﹗一次組織行動，張春天不忍傷害漂亮女殭屍小夏（林明禎飾），違反命令與她共住一室，引來百年老殭屍王的致命攻撃……', '钱小豪', '甄栢荣', 5.5, 9282, 'tt6270524', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2432744632.jpg', 9, 30.8, 43.4, 11.7, 5.2, '-0.100775,-0.157840,-0.547935,0.244383,-0.471846,0.253187,0.542215,0.221757,-0.460391,-0.058005,0.417991,0.465584,0.119949,0.073401,-0.479750,0.434717,0.125011,-0.358958,-0.281562,-0.089315,-0.386487,0.145847,-0.303964,-0.243410,0.300612,-0.133658,0.205451,0.220310,-0.166538,-0.273136,0.506615,0.290385,-0.222582,0.487847,-0.267137,-0.120019,0.068455,-0.213314,0.046070,0.015263,-0.277437,-0.518302,-0.385466,0.064443,-0.106005,0.364031,0.593981,0.160827,-0.143725,-0.492052,0.051977,-0.316821,-0.048426,-0.070859,0.337219,-0.405579,0.169884,0.135189,0.389940,-0.398655,0.072536,-0.183786,-0.434397,0.141223,0.172251,-0.004668,-0.260917,0.439392,-0.186375,0.249199,0.023401,-0.178508,-0.273105,-0.199284,0.146787,0.203430,-0.186979,0.065342,-0.408741,0.253209,0.352916,0.029702,-0.231889,0.374547,-0.266073,-0.450761,0.300855,-0.315590,-0.475595,-0.087720,0.723555,0.065925,-0.334735,0.036015,-0.566296,0.214162,-0.331085,-0.017358,0.006535,-0.023948,-0.126222,-0.522887,0.049273,-0.155103,-0.423970,0.339628,0.511061,0.217055,0.735924,-0.315703,0.110314,0.923342,0.275889,-0.472020,0.692394,-0.305775,-0.238392,0.035668,0.174935,0.019653,0.022176,0.604847,0.303000,0.290122,-0.235136,-0.200037,-0.560902,0.255697', '27069070', '1300324', '4233625', '1303989');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26759819', '命运之夜——天之杯Ⅱ：迷失之蝶', '剧情', '本片改编自TYPE-MOON出品的文字冒险类游戏《Fate/stay night》，是该游戏最终路线“HF线”动画剧场版全三部作品中的第二章。通过女主角间桐樱的视角，讲述了御主和英灵为了得到可以实现一切愿望的圣杯而相互厮杀的一场战争。时隔10年在冬木市爆发的这场“圣杯战争”中，因被称为“圣杯战争”御三家之一的间桐家的当家·间桐脏砚的参战而变得更畸形、扭曲和恶化。作为御主参战的卫宫士郎也在战斗中负伤还失去了英灵Saber，尽管如此士郎为了守护间桐樱，并没有从战斗中引身退出。而担心士郎身体的樱，自己也无法逃离魔法师的宿命……', '杉山纪彰', '须藤友德', 7.6, 29932, 'tt8091892', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2561910374.jpg', 1.2, 5.1, 30.3, 40.1, 23.2, '0.188155,0.147222,-0.388602,0.429055,0.284333,-0.297111,0.695986,-0.298000,-0.160299,-0.427054,0.216532,0.974083,-0.132446,-0.088911,0.246062,-0.276920,-0.128787,-0.794603,-0.276248,-0.054364,-0.280678,-0.295292,0.154566,-0.132295,-0.355455,-0.542448,1.430689,0.279434,-0.438688,0.210080,0.400634,0.201197,-0.343891,0.185876,0.237629,-0.225798,-0.318174,-0.060699,-0.422270,0.446719,-0.015537,-0.201820,-0.387436,0.601435,-0.020677,0.363091,0.996687,-0.955516,0.243482,0.030048,0.311218,-0.560783,-0.295347,0.057501,0.401525,0.215051,-0.001204,0.449222,0.025526,-0.024777,-0.184091,-0.254252,-1.237914,-0.037475,0.175897,0.334481,-0.114950,0.389213,0.152425,0.161827,0.261559,-0.083365,0.211090,0.493720,0.633712,0.157681,-0.570464,-0.116961,-0.281780,0.175596,0.563657,-0.241371,-0.560918,0.511292,-0.244369,-0.626120,-0.494253,-0.350747,-0.418317,-0.041585,0.224169,0.377596,0.126017,0.531744,-1.023489,0.077440,-0.243368,-0.503442,0.095955,-0.293612,0.131579,-0.616461,-0.410676,-0.300082,0.073779,0.043789,0.136642,-0.555176,0.613153,-1.208029,-0.090523,0.502245,0.248937,-0.260694,0.341901,0.362721,0.154369,-0.151037,-0.097991,0.286449,-0.117313,0.325090,0.144742,0.116813,0.225484,0.201104,-0.436264,0.586723', '26759820', '7051375', '3861846', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26759820', '命运之夜——天之杯Ⅲ：春之歌', '剧情', '本片改编自TYPE-MOON出品的文字冒险类游戏《Fate/stay night》，是该游戏的Heaven''s Feel路线，简称“HF”或“樱线”，是该系列作品动画剧场版全三部作品中的最终章。在剧场版作品第二章黑化之后的樱吸收了众多Servant的灵魂后，被世间 所有的恶控制，成为黑色圣杯的化身。最终，得知一切的士郎放弃了成为正义的伙伴，选择了保护樱...', '杉山纪彰', '须藤友德', 8.5, 15243, 'tt8092118', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2616507920.jpg', 0.7, 2, 15.1, 35, 47.3, '0.020167,0.409705,-0.146377,0.641449,0.476120,0.008181,0.091639,-0.091074,-0.174746,-0.116371,0.135382,0.837901,-0.130499,0.015007,0.251685,0.050559,-0.155594,-0.734894,-0.392081,-0.172494,-0.338969,-0.127714,0.001896,0.198947,-0.327991,-0.513004,1.488235,0.216671,-0.244976,0.021757,0.681574,0.613987,-0.297351,-0.174648,0.116480,0.178654,-0.062202,-0.474986,-0.209114,0.565899,-0.132726,-0.127368,0.007199,0.154902,-0.063186,0.059226,1.295709,-0.627878,-0.118663,-0.027610,0.995919,-0.467347,-0.162637,-0.158506,0.089991,0.343966,0.177155,0.329916,-0.158537,0.227723,0.112145,-0.006543,-1.315554,-0.501531,0.423797,0.101656,-0.472035,0.175072,-0.022022,-0.026111,0.106881,-0.222117,0.402459,-0.113371,0.639066,0.098777,-0.103371,-0.179221,-0.244069,0.442131,0.369772,-0.119694,-0.589924,0.642228,0.000732,-0.257336,-0.607611,-0.444071,-0.384807,0.099145,0.375925,0.679012,-0.049994,0.380525,-0.997902,-0.505623,-0.101657,-0.430435,0.314832,-0.404333,0.021136,-0.646492,-0.094717,0.001522,0.278287,-0.199006,0.122462,-0.469136,1.052216,-1.060468,0.135789,0.463143,-0.034989,-0.676939,0.715499,0.117783,0.194295,0.152001,0.329848,0.208557,0.144160,0.063387,-0.006393,0.340344,0.223222,-0.206545,-0.573895,0.680892', '25880986', '26759819', '24499012', '22265687');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26759825', '一日情人', '剧情', '让娜（艾斯特·加莱尔 Esther Garrel 饰）是一个二十岁的年轻女孩，在刚刚结束了一段失败的恋情之后，她决定回到阔别已久的父亲吉勒（埃里克·卡拉瓦卡 Eric Caravaca 饰）家里，重新热络一下疏远的父女感情。吉勒和妻子分手多年，一直都辗转在不同的女人之间。令让娜没有想到的是，当她回到家中时，竟然见到了一个年纪和自己差不多大的女孩阿丽亚娜（露易丝·谢维洛特 Louise Chevillotte 饰），这个女孩是父亲的现任情人。刚开始，阿丽亚娜的存在令让娜觉得非常的不舒服，因为这个女孩虽然年轻，但感情经历却极为丰富，并且目前正在同多位男子交往。但随着时间的推移，让娜、吉勒和阿丽亚娜之间渐渐产生了一种奇妙的关系。©豆瓣', '埃里克·卡拉瓦卡', '菲利普·加瑞尔', 7.4, 15929, 'tt5642124', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2456370696.jpg', 0.5, 3.4, 36.3, 46.9, 12.8, '0.365789,-0.184010,-0.891050,0.603093,-0.119268,-0.411844,1.025996,0.009546,-0.698027,-0.501292,0.001783,0.963573,-0.488083,0.531858,0.306828,0.161095,-0.573077,-0.753185,0.076426,-0.332767,-0.361790,-0.781227,0.002826,0.010158,-0.094087,-0.500939,0.641313,-0.141189,-0.125894,0.540315,0.200917,-0.023528,0.106224,0.773044,-0.025163,0.063573,0.397672,0.029753,-0.106261,-0.007515,0.287102,0.186430,-0.104002,0.273509,0.034128,0.527745,0.683851,-0.502424,-0.248504,0.040125,0.417962,0.095354,-0.026891,-0.061239,0.289368,0.034735,0.268139,0.105442,-0.430162,-0.080302,0.116445,-0.229276,-0.690401,0.691658,0.214819,-0.061243,-0.518097,0.583013,-0.122316,-0.161974,0.228131,-0.411629,0.373002,0.678510,0.383639,0.499894,-0.308520,0.134627,-0.468446,-0.141670,0.968174,0.299465,-0.220249,0.678455,-0.312244,-0.477316,-0.306241,-0.078315,-0.560933,-0.100210,0.135332,0.249499,-0.100166,0.406058,-0.520071,0.020520,-0.389140,0.078698,0.372585,-0.509189,-0.263676,-0.271085,-0.489317,-0.813096,-0.466270,0.162835,-0.109249,-0.342465,0.829436,-1.083387,0.226036,0.355707,0.289823,-0.503545,0.725844,0.253555,0.062181,-0.274984,-0.169536,0.437509,-0.038080,-0.160266,0.253660,0.328768,-0.079181,0.156594,-0.205255,0.629586', '4275444', '1308755', '25721544', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26760160', '破·局', '动作', '这是高见翔警官生命中最艰难的一天：母亲去世，工作遇阻，还在奔丧时意外撞死了一个人。他本以为可以瞒天过海，没想到一个惊天阴谋在前方等待，令他身陷迷局......', '郭富城', '连奕琦', 6.1, 70420, 'tt7180392', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2496288510.jpg', 2.6, 16.7, 55.6, 21.4, 3.8, '-0.288948,0.026078,-0.772923,0.320960,0.115324,-0.097374,0.538496,0.021222,-0.689263,-0.576457,0.316628,0.603239,-0.032050,0.029660,0.502109,-0.163233,-0.272576,-0.455682,-0.015822,-0.133524,-0.246799,-0.616913,-0.371811,-0.168111,-0.075802,-0.331844,0.436443,0.500350,0.137058,0.364598,0.010774,0.262889,-0.225765,0.608800,-0.327706,-0.048417,0.379579,0.135133,-0.082286,0.149766,0.044218,-0.480989,-0.124549,0.531816,-0.373348,0.182286,0.496827,-0.382180,-0.412235,-0.071035,0.017403,-0.236577,-0.292229,0.108649,0.129495,-0.682312,0.318201,0.447384,-0.414007,0.298358,0.332463,0.026219,-1.007437,-0.265858,-0.403145,0.086547,-0.313886,-0.048403,0.161996,0.072392,0.262633,-0.483611,0.351617,0.429403,0.302022,0.199596,-0.486716,0.246455,-0.389992,0.195685,0.903609,-0.087301,-0.004287,0.527982,0.293383,0.105553,0.327352,0.074712,-0.491151,0.153134,0.092435,-0.019640,-0.376277,-0.031897,0.038500,0.144260,-0.561245,0.340810,-0.344801,-0.319013,-0.684860,0.219177,0.069851,0.624668,-0.133727,0.393499,-0.269457,-0.245157,0.273797,-0.465402,0.399632,0.336647,-0.006972,-0.105354,0.634884,0.306573,-0.011442,-0.363110,-0.098471,-0.176796,-0.246841,0.176647,-0.158892,-0.122662,-0.006740,-0.122261,-0.284702,0.117804', '1292064', '26678784', '5296286', '1295318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26761256', '钢之炼金术师', '动作', '悲伤的爱德华和阿尔冯斯两兄弟，试图利用炼金术中最大的禁忌——人体炼成术救活撒手人寰的母亲，谁知却遭遇巨大的灾难。失去身体的阿尔冯斯，其灵魂被封禁在铠甲中，爱德华则以自己的右臂和左脚为代价，迫使弟弟止步冥国门前。许多年后，爱德华（山田凉介 饰）成长为这个国家中最年轻的钢之炼金术师，他与弟弟（水石亚飞梦 配音）上下一心，共同奔跑在寻找贤者之石的道路上。与此同时，神秘的人造人拉丝特（松雪泰子 饰）、恩维（本乡奏多 饰）盘桓这个国家的角落，她们策划者恐怖的勾当，一时间上空阴云密布……本片根据荒川弘的原作漫画改编。©豆瓣', '山田凉介', '曾利文彦', 4.8, 7811, 'tt5607028', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2498172067.jpg', 19.1, 36.3, 34.3, 6.7, 3.5, '0.040555,0.001764,-0.696251,0.812018,0.037070,-0.245545,0.847509,0.088244,-0.345869,-0.463643,0.429047,0.773253,-0.057066,0.042778,0.198235,0.131937,-0.119300,-0.813319,-0.141626,0.013931,-0.503891,-0.280970,-0.363209,-0.054253,-0.439915,-0.410642,0.876814,0.067616,-0.102650,0.195709,0.156749,0.397862,-0.203768,0.176897,0.112711,0.124421,-0.008306,-0.212470,-0.139595,0.056528,-0.194480,-0.336796,0.000716,0.291057,-0.205691,0.237434,0.624429,-0.536266,0.314982,-0.548252,0.388868,-0.141424,-0.116124,0.129784,0.182498,-0.027374,0.205770,0.062133,-0.241676,-0.103683,0.157482,-0.135533,-0.966838,-0.390938,0.177132,0.009631,-0.522539,0.198179,-0.049086,-0.185898,0.303883,-0.198521,0.153550,0.232986,0.240753,0.366154,-0.340117,-0.008514,-0.146999,-0.024751,0.255345,-0.066533,-0.319086,0.044766,-0.262056,-0.437797,-0.104712,-0.376188,-0.177785,-0.151487,0.311237,0.241799,0.178945,0.526105,-0.633959,0.069912,-0.267319,-0.108674,0.006145,-0.106270,-0.144201,-0.573788,-0.078546,-0.443967,0.010853,0.000510,0.088708,-0.322685,0.673939,-0.594524,0.066814,0.473134,0.293425,0.014513,0.345127,-0.099531,0.299977,-0.350821,-0.377458,0.283992,0.082920,0.451962,0.012786,0.217126,0.234343,0.162599,-0.608352,0.644580', '25880986', '26667010', '10467125', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26761325', '牡丹花下', '剧情', '故事发生在南北战争期间，教会学校的女学生马莉（艾蒂森·里克 Addison Riecke 饰）在无意之中遇见了身负重伤的北方士兵迈克伯尼（柯林·法瑞尔 Colin Farrell 饰），善良的马莉将迈克伯尼带回了寄宿学校之中，丝毫没有考虑到迈克伯尼的存在会让这所由玛莎小姐（妮可·基德曼 Nicole Kidman 饰）一人苦苦支撑维系的女子寄宿学校带来怎样的威胁。身为学校里唯一的男性，迈克伯尼的出现犹如一颗石子投入了平静的水面，掀起了阵阵涟漪。不仅仅是语文老师艾德维娜（克尔斯滕·邓斯特 Kirsten Dunst 饰）无法自持的受到前者的吸引，就连情窦初开的懵懂女生艾丽西亚（艾丽·范宁 Elle Fanning 饰）亦按耐不住内心的躁动。©豆瓣', '科林·法瑞尔', '索菲亚·科波拉', 6, 18836, 'tt5592248', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2462195488.jpg', 2.5, 20.8, 54.6, 18.3, 3.8, '0.445161,-0.044931,-0.624202,0.486529,-0.320094,-0.249938,0.758942,0.270426,-0.567915,-0.257804,0.245811,0.385684,-0.253581,0.170063,0.386698,0.092132,-0.253543,-0.502679,-0.111120,-0.164552,-0.063419,-0.512074,-0.262824,-0.171964,-0.174950,-0.480886,0.451116,-0.123287,-0.212565,0.430893,0.202221,0.586085,0.034968,0.310193,0.174193,0.074252,0.177183,-0.086317,0.048695,0.346428,0.251367,-0.072596,0.042118,0.120291,0.102450,0.415665,0.626897,-0.224508,0.208032,-0.029576,0.367713,-0.063010,0.143344,-0.059909,0.262701,-0.110401,-0.090513,-0.042636,-0.221063,0.061065,0.490601,-0.006276,-0.270559,-0.059550,0.187787,0.505772,-0.520609,0.391875,-0.099332,-0.173352,0.130180,-0.079443,-0.129613,0.213590,0.138903,0.294803,-0.011699,0.120569,-0.235699,0.091620,0.453224,-0.061216,-0.469684,0.092612,-0.594813,-0.406644,0.027980,-0.056193,-0.838368,-0.109580,0.252530,0.188564,0.089705,0.361894,-0.350906,-0.279368,-0.309585,-0.207367,-0.072957,-0.337610,-0.238990,-0.552514,-0.097269,-0.272116,-0.202668,-0.176559,0.021067,-0.102414,0.733415,-0.915049,0.306306,0.379922,0.224334,0.232653,0.432601,-0.081593,0.159071,-0.015920,-0.185924,0.528035,0.131690,0.243496,0.069867,0.428779,-0.029109,-0.142350,-0.273469,0.429973', '3445516', '3626365', '25922902', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26761334', '我心雀跃', '剧情', '高二女生刘唯唯（孙伊涵 饰）在学校结识了美术老师邹野（宋宁 饰），邹野独特的气质和举止让她第一次有了怦然心动的感觉，纵使这份藏不住的懵懂情愫无法抑制，青春期少女特有的大胆和自以为是让刘唯唯沉浸在自己想象中的感情互动里无法自拔……在那一年夏天，她就像一个闪亮的发光体，无所顾忌地去做自己喜欢的事，去爱自己喜欢的人。', '孙伊涵', '刘紫微', 6.7, 16811, 'tt7243868', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2461628402.jpg', 1.7, 9.4, 48.9, 31.9, 8.1, '0.382658,0.112055,-0.940099,0.836715,-0.767756,-0.091922,0.981592,0.124087,-0.508990,-0.129445,-0.134670,0.720459,-0.365724,0.474234,-0.013789,0.115881,0.013400,-0.805514,-0.149306,-0.203033,0.055325,-0.352131,-0.097079,-0.237327,0.063436,-0.300969,0.542862,0.139724,-0.473364,0.636917,0.333192,0.183711,0.242242,0.696033,-0.192157,-0.139805,0.017275,0.464802,-0.032453,-0.200138,0.282621,-0.136964,-0.119450,0.318393,-0.029799,0.167816,0.830731,-0.156737,-0.362230,0.165711,0.454356,0.086098,-0.063121,0.390635,0.003825,-0.038529,-0.015885,-0.346434,-0.231082,0.129151,0.177421,0.190984,-0.554980,-0.129165,0.153469,0.038288,-0.589959,0.423153,0.009905,-0.223265,0.438599,-0.332248,0.010528,-0.272773,0.210703,0.687608,0.093163,-0.100101,-0.489380,0.518790,0.751472,0.177331,-0.379920,0.505297,-0.673635,-0.426994,-0.257548,-0.261680,-0.640002,0.089077,0.150804,-0.046554,-0.390207,0.141568,-0.306054,0.040480,0.470670,0.169738,-0.199851,-0.814474,-0.227233,-0.184536,-0.294925,-0.788544,-0.471567,-0.156460,0.044942,-0.349458,0.938022,-1.049660,0.222080,0.693259,0.246415,-0.525840,1.067276,0.444283,-0.293636,-0.186624,-0.126410,0.323162,-0.338474,0.031784,0.279914,0.972299,-0.309864,0.198100,-0.372392,0.567696', '3230462', '24756472', '26354526', '1309161');
