INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26764514', '末日重启', '动作', '近未来，奥特普能源公司研发出一种利用平行宇宙获取新能源的方法，并盛情邀请飞行员兼物理学家威廉·波特（丹·史蒂文斯 Dan Stevens 饰）协助。因为要照顾身为单亲妈妈的妹妹米娅和患有心理疾病的侄子东尼，威廉婉拒了奥特普的邀请，后抱着强烈的使命感和好奇心，决定投身新计划。不料，就在威廉穿越至另一个宇宙时，系统不稳定导致宇宙即将坍塌。面对机甲和反叛组织的追逐，威廉必须拼尽全力，为了保护心爱的家人和真实宇宙，尽快解决如同末日来临般的大危机。', '丹·史蒂文斯', '提姆·斯密特', 4.2, 6347, 'tt5464234', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505644718.jpg', 24.1, 48.8, 23.4, 2.8, 0.9, '-0.133733,0.312728,-0.698094,0.467385,0.111611,-0.173146,0.343973,0.340422,-0.243464,-0.377574,-0.039410,0.651525,0.199190,0.178172,0.504663,0.001470,-0.433300,-0.313074,-0.251873,0.258573,-0.602606,-0.593151,-0.225065,-0.421167,0.072841,-0.688292,0.569126,0.007218,-0.370352,0.217866,0.003345,0.851183,-0.129456,0.332283,0.207317,-0.412050,0.212303,0.018977,-0.858776,0.418047,-0.130728,0.224721,0.190948,0.191004,-0.166421,0.236309,0.208928,-0.358343,0.149920,-0.410981,0.390846,-0.262210,0.032344,-0.233185,0.072348,0.018664,-0.076093,0.081838,-0.178365,0.026890,0.199594,-0.497952,-1.136057,-0.172385,0.149811,-0.229991,-0.388675,-0.004251,-0.050835,-0.005970,0.268496,-0.193992,0.073563,0.557553,0.072398,0.491221,-0.469246,0.439211,-0.300819,-0.140350,0.582216,-0.222075,-0.215301,0.161400,-0.203565,-0.194271,0.000938,-0.360383,-0.331057,-0.093102,0.250061,0.438875,-0.055056,0.412028,-0.511352,-0.131153,-0.619123,-0.063655,0.238226,-0.369170,0.143878,-0.554176,0.205134,0.102244,0.110664,0.124839,0.228015,-0.264354,0.789992,-0.682646,0.375163,0.732040,0.371117,-0.666662,0.570652,0.218343,0.183090,-0.673856,0.166912,0.127037,0.001451,0.360583,-0.165869,0.037805,0.355828,0.037307,-0.126194,0.362235', '26678784', '27009869', '30163500', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26766760', '与君相恋100次', '爱情', '日向葵海（miwa 饰）和长谷川陆（坂口健太郎 饰）是青梅竹马的好友，两人同朋友松田直哉（龙星凉 饰）和中村铁太（泉泽佑希 饰）一起组建了一支乐队。直哉一直默默喜欢着葵海，他决定在夏日祭上表白自己的心意。然而，葵海的目光却一直追随着冷傲孤僻的陆，在他的温柔和冷漠之中，葵海无法确定自己在他的心中究竟存在于怎样的位置。夏日祭当天，乐队登台演出，心不在焉的葵海在搞砸了整场演出之后死于交通意外。然而当她再度睁开双眼，发现自己竟然回到了一周之前，这不可思议的经历让她发现了陆一直隐藏着的秘密，也令两人之间的关系有了突飞猛进的发展。然而，无论怎样努力，葵海终究会在夏日祭那天傍晚死去，为了将心爱的人留在身边，陆一遍又一遍的穿越着时空。©豆瓣', 'miwa', '月川翔', 6.2, 48781, 'tt5614984', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2471315752.jpg', 3.4, 19.2, 48.1, 21.5, 7.8, '0.055506,0.253570,-0.811133,0.742580,0.001266,-0.323585,0.674477,-0.030344,-0.576071,-0.341504,-0.012501,0.595148,-0.252852,0.524630,0.404687,-0.104721,-0.210635,-0.835729,-0.201750,-0.011518,-0.243535,-0.697792,-0.207790,-0.030358,-0.089450,-0.147992,0.567972,0.371559,-0.083414,0.411604,0.616407,0.080236,-0.171257,0.601765,-0.154900,-0.052614,-0.024047,0.351364,-0.013121,0.347985,0.132323,-0.570724,-0.347879,0.323382,0.129861,0.224945,0.717997,-0.132255,-0.398029,0.068996,0.344235,-0.272972,0.030579,0.268888,0.220033,0.280549,0.134577,-0.017445,-0.174430,-0.076403,0.170959,0.024318,-0.407546,0.021336,0.156666,0.109241,-0.787194,0.515299,-0.151157,-0.070864,0.205451,-0.356626,0.329136,0.574155,0.406883,0.422790,-0.267390,0.081382,-0.255066,0.158003,0.746233,0.189815,-0.147932,0.321588,-0.083508,-0.433468,-0.489796,0.018633,-0.397980,-0.107483,0.303981,0.378431,-0.078004,0.265727,-0.384287,-0.062734,0.403850,-0.084801,0.118228,-0.479251,0.041876,-0.421669,-0.049248,-0.731775,-0.425781,0.337320,-0.150928,-0.435362,0.465724,-0.828684,0.272589,0.348907,0.246189,-0.094682,0.584059,0.174612,-0.086749,-0.103244,0.107713,0.240569,0.053364,0.426078,0.469700,0.423537,-0.121333,0.219004,-0.705354,0.529969', '25853727', '1301022', '21766698', '1850797');
