INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26769449', '维京：王者之战', '剧情', '第10世纪末，基辅罗斯的最高统治者斯维亚一世暴毙后，王国震动，朝野纷争。三个王子在各自公国贵族的支持下，争夺王位继承权。弗拉基米尔本是三位王子中年纪最小且生性柔弱的一个，并且因为是父亲与女仆的“私生子”而不被家族器重。在父王暴毙、大王子谋害二王子夺下王位之后，这个胆小的王子在父亲谋臣尼尔德的帮助下，从家族的故乡组织起一支野蛮狂暴的维京海盗战队，开始了对哥哥以及杀害他父亲的异族人的复仇。等待他的是大王子的铁血武士、坚不可摧的波洛茨克城堡、突厥铁骑的劲弩和邪恶的异教诅咒；罗斯公国绝世美人罗格涅达和暧昧神秘的大王妃以及权谋、色诱、暗杀、绝望和背叛，更要面对强大的拜占庭帝国……铁血大帝弗拉基米尔将如何上演“王子复仇记”？', '丹尼拉·科兹洛夫斯基', '安德列·克拉夫丘克', 5.8, 7531, 'tt5157456', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2505620560.jpg', 5.6, 24.8, 48.9, 15, 5.6, '0.093543,0.254860,-0.587173,0.977693,0.085684,-0.066353,0.636766,0.226486,-0.525469,-0.295595,0.581681,0.823246,0.155800,0.066095,0.332991,0.111730,-0.070800,-0.590683,-0.539375,0.025275,-0.090997,-0.450145,-0.283411,-0.306692,-0.081734,-0.770256,0.709277,-0.037253,-0.176660,0.155639,0.381196,0.489976,0.032485,0.193744,-0.133787,-0.234595,0.260183,-0.262403,-0.302256,0.292680,-0.155300,-0.013035,-0.068222,0.293807,-0.099326,0.161935,0.378950,-0.854856,0.659517,-0.627400,0.327547,-0.269174,-0.092238,0.155183,0.676810,-0.354169,0.069922,0.486329,0.184350,-0.580678,-0.029400,-0.062557,-0.828860,-0.007781,0.149412,0.106420,-0.786962,0.575587,-0.436962,-0.109252,0.426973,0.044839,0.365177,0.820636,0.112442,0.255448,-0.098477,0.079516,-0.517642,-0.115147,0.730975,0.059605,-0.428733,-0.570323,-0.028837,-0.505183,0.072612,-0.820860,-0.579592,-0.165647,0.502997,-0.379409,0.427826,0.930092,-0.689117,-0.180989,-0.643746,-0.099564,0.525491,-0.631954,-0.167612,-0.443776,-0.116360,-0.226722,0.019933,0.226917,0.532052,-0.013332,0.917403,-0.795702,0.291046,0.387339,0.426216,-0.651009,0.337826,0.075100,-0.086636,-0.078179,-0.355166,0.416767,0.383945,0.013685,-0.037295,0.212720,-0.225038,-0.111912,-0.184277,0.378484', '1308837', '5308201', '1811755', '3036473');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26769480', '一路顺风', '剧情', '纳豆是一位送货的小弟，从小到大就没有做过任何正经事，偷拐抢骗，最擅长偷。这个送货的工作，是他立定志向好好做人之后第一个工作。工作很单纯，就是几个礼拜一次把货送到南部。他从事这个工作已经有一段时间了，通常是一早出发，中午到达，不到傍晚的时候回到台北。南部的收货人，名字叫庹哥，是老板大宝非常好的朋友，纳豆所送的货就是来自泰国金三角的海洛英，而且有海洛英界的LV之称的双狮地球牌。他送货的方式非常特别，就是在路边随手拦计程车，一路上就在计程车里，到达目的地下来，把东西交给客人，再坐着原车回来。这次他搭的计程车虽然有一些破旧，但是看到司机一副乐观没有心机的样子，最后还是上了车，没多久他发现，司机带着浓浓的广东腔，原来这位司机先生是在很久以前来台的香港人。老许在90年代来到台湾，早先来台时，他不知道会待多久，但一天一天过去，不知不觉已经来台25年。就在他们把货送到目的地的时候，现场发生了黑吃黑的事情，庹哥当下中枪身亡，货品及现款被洗劫而去，纳豆也被流弹所伤，老许跟纳豆甚至被关到一台宾士车的后车厢，深陷重围。一路顺风是一个祝福，也是一种期待。但是一条长长的人生路，哪有可能顺风到底，常常转个弯，风向就变了。这支片子是希望在人生短短的一条路上，能重拾我们遗忘的风景，或是拾回一点点，我们身为人曾经拥有的情感。', '许冠文', '钟孟宏', 7.7, 21839, 'tt5952306', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2505096603.jpg', 0.9, 3.3, 27.4, 48.3, 20.1, '0.262470,0.017881,-0.532173,0.372674,-0.358904,-0.137870,0.480988,-0.046924,-0.579417,-0.282923,0.117420,0.695679,0.052230,0.204719,0.351777,0.160429,-0.221099,-0.379152,0.105936,-0.392190,-0.576249,-0.384925,-0.069365,0.072050,0.005180,-0.128848,0.352506,0.162537,-0.035858,0.435362,0.059293,-0.074045,0.017198,0.655242,-0.516763,-0.013666,-0.043356,-0.045527,-0.043743,0.266702,0.039699,-0.277834,-0.071572,0.021338,0.154018,0.284395,0.473143,0.149222,-0.408607,0.303712,0.071824,-0.177932,-0.135370,-0.104648,0.410748,-0.036065,0.179590,0.142950,-0.376374,0.112915,-0.053417,0.022359,-0.486469,-0.012948,-0.370300,-0.000902,-0.935068,0.414681,-0.126812,-0.120019,-0.054306,-0.633064,0.508109,0.213128,0.030671,0.262679,0.088381,-0.010200,-0.781057,0.042807,0.851290,-0.071468,0.134630,0.549806,0.091200,-0.271430,-0.006773,-0.101966,-0.405046,0.117160,0.225611,-0.100073,-0.387026,-0.254584,-0.518737,0.171225,-0.083666,-0.407113,0.144358,-0.348297,-0.092565,-0.439245,0.161676,-0.416072,-0.151084,0.240275,0.180503,-0.064735,0.580042,-0.776197,0.353369,0.456606,0.141883,-0.456240,0.807786,0.111924,-0.048306,-0.191657,0.080768,-0.191438,0.117229,0.446748,0.134787,0.344402,0.027473,-0.318479,-0.305540,0.559998', '1299965', '1926007', '2124718', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26770697', '骗子', '剧情', '为了逮捕涉及4万亿韩元、造成3万名受害者的稀世大骗子，诈骗犯（玄彬饰）和检察官展开较量的诈骗犯罪。玄彬将在片中饰演设下完美骗局的诈骗犯黄智成，是一位专挑诈骗犯行骗的天才诈骗犯；刘智泰在片中饰演劣性检察官朴熙洙，为抓住稀世大骗子而制定计划招揽黄智成，表面正义内里却是对权力有无尽欲望的人。电影新颖、烧脑的故事令人耳目一新，而两位演技派演员的互相飙戏也引发众多期待。电影计划于2016年下半年拍摄。', '玄彬', '张昌原', 7.5, 40588, 'tt7243686', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2503067864.jpg', 0.3, 2.6, 34.6, 45.9, 16.5, '-0.143195,-0.320391,-0.399848,0.495110,-0.006056,0.364317,0.666622,-0.018291,-0.392562,-0.165596,0.446796,0.534331,-0.577027,-0.268693,0.425888,-0.200700,-0.208229,-0.744251,-0.355820,-0.039840,0.324086,-0.453441,-0.549094,-0.132857,0.064228,-0.530961,0.894737,0.143761,-0.671359,0.158014,0.704693,0.325524,-0.200425,-0.098557,0.009727,-0.322820,0.139289,-0.107779,-0.587342,0.336175,-0.242783,-0.270851,-0.161747,-0.072087,-0.306165,0.293841,0.653906,-0.164148,-0.133490,-0.084321,0.729212,-0.549406,-0.104019,0.027300,0.079408,0.174257,0.371631,0.493036,0.100869,-0.017201,0.256002,-0.395611,-1.225435,-0.022549,0.402418,0.122783,-0.223255,0.237713,-0.039728,-0.111746,0.124522,0.082398,0.049319,0.002048,0.762830,0.434308,0.163076,0.151925,-0.252050,0.382229,0.388015,0.154680,-0.046424,0.371951,-0.245284,-0.583372,-0.040359,-0.493259,-0.247437,-0.020245,0.150206,-0.335366,-0.024264,0.237520,-0.541624,-0.049184,0.114838,0.024623,0.092098,-0.580819,-0.001420,-0.717806,-0.391726,-0.066439,-0.107722,-0.086437,0.297328,-0.564160,0.902091,-0.516376,-0.020867,0.662336,0.080582,-0.731537,0.736843,0.339336,-0.371465,-0.351335,-0.455739,-0.144045,0.155118,0.050903,0.007150,0.146499,-0.260570,-0.349268,-0.159998,0.160682', '25918677', '27602116', '1468527', '1293989');
