INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26773744', '相爱相亲', '剧情', '岳惠英（张艾嘉 饰）的母亲去世之后，惠英最大的念想就是将远葬在乡下的父亲的坟迁回城里，和母亲葬在一起，这个念头让她和父亲的原配姥姥（吴彦姝 饰）之间爆发了巨大的矛盾。迁坟的事成为了惠英的心结，亦让她和丈夫孝平（田壮壮 饰）之间的感情产生了裂痕。惠英的女儿薇薇（朗月婷 饰）是电视台的栏目记者，对姥姥的过去充满了好奇的她将这场“家庭矛盾”搬上了电视，展现在了大众面前，虽然出发点是善意的，可整个事件却愈演愈烈最后变成了一出闹剧。与此同时，薇薇和男友阿达（宋宁峰 饰）之间的感情因为阿达的青梅竹马的出现而遭遇了信任危机，这让她对等了外公一辈子也孤独的生活了一辈子的姥姥产生了莫名的亲近之感。©豆瓣', '张艾嘉', '张艾嘉', 8.3, 160318, 'tt7479718', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2502311890.jpg', 0.4, 1.7, 15.6, 47.4, 35, '0.424156,-0.148163,-0.789148,0.772979,-0.056689,-0.140371,0.913421,0.347542,-0.637315,0.045830,0.193331,1.053233,-0.494575,0.471089,-0.059892,0.037822,-0.068940,-1.061476,-0.162786,-0.272283,-0.262913,-0.504907,0.113077,0.153920,-0.131810,-0.088422,0.497846,-0.053914,-0.061184,0.588645,0.364028,0.270503,-0.026703,0.640365,-0.139730,0.305311,-0.202454,0.148820,-0.159798,-0.095968,0.344303,-0.268104,0.165403,0.560130,-0.114434,0.321361,0.717618,-0.281430,-0.172667,0.005602,0.435452,-0.194072,0.066312,0.207171,0.289092,0.037959,0.200509,0.322643,-0.510014,-0.326785,0.267905,0.113826,-0.827689,0.241168,0.062937,-0.135458,-1.066627,0.715815,0.186468,-0.278018,0.177868,-0.004219,0.597531,0.411658,0.184000,0.547871,-0.445324,-0.002278,-0.141296,0.174157,0.777342,-0.218979,-0.137994,0.499557,-0.405718,-0.129864,-0.276871,-0.120496,-0.637069,-0.063594,0.217906,-0.069276,-0.326766,0.352222,-0.707628,-0.148514,-0.128461,-0.102605,0.116806,-0.426887,-0.046259,-0.122718,-0.597916,-0.633520,-0.566180,-0.098902,-0.068852,-0.299910,0.806444,-0.864507,0.267322,0.430585,0.526697,-0.700243,0.822864,0.183565,0.099100,-0.082500,0.088312,0.102126,-0.439506,0.157797,0.387256,0.263403,0.071982,0.090665,-0.331272,0.744311', '3111650', '30162520', '1306916', '26958479');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26774017', '最佳男友进化论', '喜剧', '情场老司机范凡（郑恺 饰）在机缘巧合之下决定开办一个“男神训练营”，用自己独到的恋爱心得助那些在爱情里苦求不得的单身狗们进化成“最佳男友”。一场婚礼上的“实践教学”让伴娘女神（张雨绮 饰）被套路之下的真心打动，几个徒弟都拥有了梦寐以求的爱情。但作为“专家”范凡自己的感情生活却是剪不断理还乱……', '郑恺', '林子聪', 2.5, 4863, 'tt10488040', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2553207098.jpg', 80.8, 14, 3.5, 0.9, 0.9, '0.210606,0.168084,-0.313318,0.685714,-0.384848,-0.180427,0.329159,-0.270309,-0.304562,-0.123522,0.382413,0.381698,-0.227397,0.501652,0.234953,-0.196253,-0.155334,-0.724564,0.180791,0.135499,-0.147710,-0.353921,-0.549369,0.209734,-0.465126,-0.114580,0.819618,-0.150190,-0.278506,0.152025,0.598608,0.032781,0.152621,-0.004844,-0.211778,-0.045764,0.212903,0.174293,-0.162249,0.136969,0.015880,-0.101966,-0.052526,0.115845,-0.028069,0.299747,0.638911,-0.321485,-0.000669,-0.135892,0.605904,-0.117925,-0.076301,0.312827,0.028065,0.226796,0.449258,0.111793,0.073221,0.203172,0.164814,0.062230,-0.903980,-0.172599,0.329573,-0.274497,-0.701491,0.344677,0.089304,-0.107608,-0.013134,-0.379023,-0.028131,0.123303,0.353976,0.507340,-0.507835,-0.010493,-0.255984,0.707113,0.542355,0.155004,-0.064006,0.416879,-0.185449,-0.410351,0.146575,-0.277963,-0.604412,-0.208203,0.014076,-0.251663,0.026104,0.059330,-0.682554,0.108507,-0.116174,-0.035317,-0.064327,-0.533468,0.129554,-0.478258,-0.096706,-0.232761,-0.514206,0.043493,0.336456,-0.653116,0.845860,-0.890074,0.011735,0.343456,-0.080579,-0.605523,0.707067,0.415823,0.122657,-0.114353,-0.423035,0.270146,-0.010726,0.267722,-0.105343,0.539786,0.093785,-0.292513,-0.541925,0.447943', '6101834', '25880986', '26759820', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26774033', '幕后玩家', '剧情', '坐拥数亿财产的钟小年(徐峥 饰)意外遭人绑架，不得不在一位神秘人的操控下完 成一道道令人两难的选择题。在选择的过程中，钟小年落入陷阱，不仅巨额财产被盗取、 濒临身败名裂的边缘，还将妻子魏思蒙(王丽坤 饰)牵扯进一个个险境。为了洗脱罪名， 救回爱人，钟小年在重重危机中与神秘人展开了一场关乎生死和救赎的金钱游戏…', '徐峥', '任鹏远', 5.6, 173410, 'tt8366766', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2520543845.jpg', 5.2, 26.9, 51.5, 13.5, 2.9, '-0.043722,0.303205,-0.622428,0.305325,-0.260720,0.147944,0.705907,0.128074,-0.575274,0.060612,0.590070,0.838858,-0.271759,-0.141681,0.589013,-0.017400,0.093252,-0.893325,-0.254599,-0.180899,-0.568209,-0.579265,-0.511363,-0.094989,-0.123410,-0.417726,0.692552,0.700498,-0.467905,0.023033,0.353873,0.612914,-0.666526,0.464709,-0.193795,0.060522,-0.216180,-0.035253,-0.488350,0.193571,-0.184473,-0.657508,0.024485,0.419555,-0.335995,0.146368,0.883896,-0.616771,0.043333,-0.160422,0.409190,-0.459702,-0.321394,0.224310,0.044107,0.018514,0.182552,0.512566,-0.551477,0.081777,0.643521,-0.111826,-1.150633,-0.305847,0.389565,0.112397,-0.538193,0.371383,0.065414,0.094747,0.147376,-0.198119,0.163494,0.176318,0.401834,0.513829,-0.372443,-0.273089,-0.615285,0.023760,0.842015,-0.251171,0.032814,-0.185229,0.189198,-0.131203,-0.124905,-0.546690,-0.241807,0.092046,0.623078,0.227515,-0.154079,0.490392,-0.451672,-0.004538,-0.305458,-0.039741,-0.268030,-0.740058,-0.348308,-0.191824,-0.160727,0.249136,-0.303404,0.497631,-0.030384,-0.403339,0.263660,-0.486368,0.507458,0.617993,0.116767,-0.485559,0.439010,0.250052,0.538057,-0.204171,-0.386170,0.165312,0.357699,0.279781,0.243003,-0.209867,-0.510998,0.004504,-0.260140,0.081965', '26678784', '2988294', '26747274', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26774722', '心理罪之城市之光', '动作', '一起连环凶杀案掀起了城市的狂欢与躁动，数起案件中受害者均遭虐待致死，且充满仪式感，所有线索都与一个人有关——精通犯罪心理学的天才神探方木（邓超 饰）。在与同事米楠（刘诗诗 饰）调查案件时，方木发现曾经是自己高中同学的江亚（阮经天 饰）似乎深藏很多秘密。此时网络上出现名为“城市之光”的用户，以发起投票的方式让大众决定律师任川（郭京飞 饰）的生死，方木、米楠等警察虽然用尽一切办法，依然无法阻止这场“以暴制暴”的黑暗审判，这座城市陷入了混乱的旋涡。紧要关头，方木觉察到江亚的妻子魏巍（林嘉欣 饰）竟然是解锁江亚秘密的重要证人，就在真相即将大白的关键时刻，一场惊人变故突如其来.....', '邓超', '徐纪周', 5.9, 152670, 'tt7286908', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2506228506.jpg', 4.5, 23.5, 51.1, 16.4, 4.4, '0.175788,0.008567,-0.546208,0.403334,0.025454,0.130459,0.643043,-0.015621,-0.715529,-0.326613,0.512002,0.339127,-0.366286,0.036229,0.165714,-0.204146,-0.287350,-0.773373,-0.009986,-0.032384,-0.291687,-0.522539,-0.239290,-0.071652,-0.032289,-0.229451,0.610059,0.301349,-0.351984,0.143212,0.290067,0.452156,-0.540116,0.502443,0.391970,-0.307604,0.316741,0.045404,-0.532735,0.019084,-0.119617,-0.322687,-0.109567,0.368476,-0.305295,0.243346,0.571209,-0.282797,-0.275744,0.018387,0.484700,-0.302629,-0.212510,0.166708,0.322874,0.053210,0.425949,0.251486,-0.113514,-0.211319,0.223503,0.105718,-0.591243,-0.130219,0.370919,0.219302,-0.228143,0.228539,-0.157813,0.243775,0.107539,-0.302732,0.193754,0.124453,0.510331,0.224873,-0.176220,-0.106114,-0.131393,0.066785,0.526001,0.041617,-0.178312,0.143240,-0.170601,-0.467483,-0.268068,-0.007119,-0.299781,0.289002,0.115715,0.157487,-0.188072,0.446809,-0.459174,-0.208095,-0.171549,-0.133150,-0.026427,-0.245953,-0.130577,-0.618653,-0.276398,-0.127264,-0.184172,0.150926,0.224342,-0.134109,0.526012,-0.569751,0.255953,0.496521,-0.118583,-0.233321,0.429331,0.052011,-0.094935,-0.360346,-0.200521,-0.122632,-0.106648,0.368536,-0.054375,0.068516,-0.040897,-0.208192,-0.297153,0.365226', '25723905', '1302050', '4023433', '26328483');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26774772', '情况不妙', '喜剧', '摩的司机牛大伟（李菁 饰）与怀孕的婷婷（马丽 饰）进城寻找婷婷的老公阿狗（林雪 饰），却阴差阳错卷进周阳（曹云金 饰）与Lily（周韦彤 饰）策划的一场敲诈案。国华证券的董事长杜剑锋（秦沛 饰）正因为诈骗案件准备带着女儿杜小米（盛朗熙 饰）逃往美国，就是这个时候，婷婷马上又要生了，惊魂一夜，爆笑上演……每个人的命运都在向着不可预知的方向发展着……©豆瓣', '李菁', '王莉', 6.4, 8477, 'tt6448318', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2364921137.jpg', 4.2, 14.1, 48.7, 24.9, 8, '0.007220,-0.215994,-0.541902,0.067666,0.073962,-0.395540,0.661301,0.536360,-0.122773,-0.087627,0.401382,0.386949,-0.213692,0.094342,0.303373,0.359697,-0.418099,-0.680571,0.078084,0.227275,0.148866,-0.145032,-0.047246,0.006694,0.323207,0.098892,0.133698,-0.280794,-0.241205,0.625571,0.417138,0.205783,-0.378167,0.346556,0.114493,0.394233,0.219950,0.165321,-0.451148,-0.025723,0.307784,-0.244106,-0.279848,-0.060776,-0.058687,0.356889,0.616589,-0.346578,-0.026328,-0.128699,0.208133,-0.496316,-0.167763,-0.005135,0.099665,0.061937,0.175063,0.216453,-0.223328,0.167947,0.442204,0.206845,-0.554781,0.176565,0.235009,0.332868,-0.408669,0.316756,-0.175085,-0.070952,0.209605,-0.644028,0.256192,0.317957,0.051431,0.435222,-0.315453,-0.040591,-0.596398,0.338994,0.407227,0.192838,0.495053,0.120401,0.160104,-0.226419,0.027199,0.306842,-0.685089,0.074738,0.485981,-0.152134,-0.131184,0.061020,-0.502638,0.204891,-0.261506,-0.170140,-0.127632,-0.333199,-0.238177,-0.511430,0.034274,-0.447366,-0.320009,0.082308,0.126711,-0.000710,0.405304,-0.599224,-0.038115,0.361169,0.197232,-0.526124,0.262954,0.151641,-0.042385,-0.412545,-0.090863,-0.196049,-0.472672,0.608683,0.090075,0.494479,0.040175,-0.305090,-0.297440,0.236142', '1310167', '4312232', '2004482', '4249355');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26775933', '暴雪将至', '剧情', '故事发生在二十世纪九十年代的一座小城之中，接连发生的杀人案表明，有一个凶恶而又冷血的连环杀手潜伏在这座阴雨连绵的城市之中，而且此人极有可能是当地一座工厂里的内部人员。余国伟（段奕宏 饰）是工厂保卫科干事，因为多次破获了工厂里的盗窃案件而被人们称为“余神探”。杀人案发生后，余国伟感到自己有责任为了调查案件的真相而贡献出一份力量，殊不知在刑侦队队长老张（杜源 饰）和李警官（郑楚一 饰）眼中，余国伟只是一个笑话一样的存在。余国伟决定凭借自己的力量调查案件的真相，并在一场意外中结识了名叫燕子（江一燕 饰）的女子。余国伟和燕子之间产生了压抑而又微妙的感情。©豆瓣', '段奕宏', '董越', 7, 141485, 'tt7649320', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2505160594.jpg', 0.8, 5.1, 45, 41.4, 7.7, '0.393599,-0.239651,-0.796876,0.603351,-0.057701,0.119709,0.950960,-0.054247,-0.766074,-0.435009,0.368896,0.606619,-0.137349,0.117604,0.266129,-0.133646,-0.087143,-0.798191,-0.002916,-0.460775,-0.187598,-0.615253,-0.409745,-0.387470,0.042505,-0.092126,0.490800,0.438352,-0.283015,0.315518,0.283816,0.376472,-0.263718,0.536019,0.123004,-0.096984,0.162678,0.222723,-0.133229,0.252756,0.016337,-0.445338,0.029809,0.212814,-0.084031,0.526894,0.639127,-0.351904,-0.492923,-0.148607,0.385021,-0.274512,-0.113301,-0.038924,0.560857,0.128465,0.143241,0.373780,-0.488247,-0.125111,0.286190,-0.127221,-0.795427,-0.087467,0.257037,0.432885,-0.392175,0.183179,0.044655,-0.031136,-0.011587,-0.243643,0.332103,0.267525,0.728082,0.358253,-0.140812,0.006843,-0.512772,0.113013,0.769932,-0.201572,-0.296144,0.190849,-0.249967,-0.447034,-0.266219,0.006233,-0.266705,0.103035,0.083233,-0.108235,-0.153468,0.333213,-0.577438,-0.067106,-0.138552,0.070518,-0.286476,-0.277262,-0.159411,-0.443167,-0.322647,-0.422005,-0.164678,-0.120600,0.141464,-0.370652,0.366634,-0.881704,0.130766,0.495364,0.126067,-0.320491,0.489561,-0.030917,0.155714,-0.174839,0.003406,-0.124720,0.015860,0.245621,-0.059533,0.381581,-0.099671,-0.490275,-0.068790,0.150117', '3263169', '1301022', '10546747', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26778069', '老爸当家2', '喜剧', '在续集中，亲爹沃尔伯格和继父法瑞尔决定把他们的分歧放在一边，携手为孩子们打造一个完美的圣诞节，这时候，孩子们的两个爷爷也到了（也就是两个爸爸的爸爸）。这一次，性格好强的爷爷吉布森遇到了极度敏感的爷爷利高特，一场大战也将掀起。', '威尔·法瑞尔', '西恩·安德斯', 6.5, 4438, 'tt5657846', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2503839802.jpg', 1.7, 12.9, 53.3, 22.5, 9.5, '0.307749,-0.283601,-0.855607,0.824330,-0.596151,-0.659942,0.883894,-0.028823,-0.368053,-0.207445,0.192008,1.139741,-0.247719,0.647251,0.144550,-0.175229,0.045430,-0.681103,-0.169167,0.173762,-0.408068,-0.449235,-0.179688,0.049776,-0.144802,-0.171581,0.368264,-0.540164,-0.052463,0.527112,0.583789,0.200850,-0.033542,0.219064,-0.262067,0.182339,-0.094146,-0.021806,-0.508997,0.232380,0.506078,0.274622,-0.006736,0.366545,0.235615,0.093101,0.710593,-0.579858,-0.148251,-0.021560,0.339144,-0.329889,-0.281454,0.334571,0.340485,-0.022525,0.213115,0.411623,-0.424823,0.252266,-0.092828,0.040018,-0.677799,0.066490,-0.056540,-0.064472,-0.884335,0.475792,0.271677,-0.438561,0.218903,-0.566200,0.371934,0.561127,-0.021829,0.541291,-0.585320,-0.064147,-0.340885,-0.122006,0.949977,-0.267204,0.148412,0.262444,0.094512,-0.180435,0.082035,-0.268740,-0.728939,0.263696,0.277571,-0.421747,-0.092029,0.390120,-0.868780,0.017685,-0.126590,-0.502238,0.000458,-0.482640,-0.009084,-0.286519,-0.089217,-0.425277,-0.398988,0.192054,0.019697,-0.247479,1.072377,-0.648086,0.238356,0.371644,0.066056,-0.466732,0.483080,0.310636,0.476282,-0.243550,-0.020586,-0.309137,0.150266,0.010071,0.314070,0.715931,0.081202,0.014761,-0.433060,0.700695', '30162520', '1292219', '1481233', '25731805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26778790', '佛罗里达乐园', '剧情', '魔法城堡旅店坐落于破败的弗罗里达州基西米县，在这个经济萧条的小县城距离奥兰多迪士尼主题乐园只有25-30分钟的车程 。莫妮是一个早熟的六岁女孩，她和年轻失业的妈妈海莉住在魔法城堡旅店的一个廉价单间里，过着艰难的生活。她们靠垃圾食品、慈善捐助为生，有时还不得不对源源不断地去往迪士尼乐园的游客进行乞讨或者小偷小骗。在暑假里，莫妮和她的朋友们展开了一系列冒险 。', '布鲁克琳·普林斯', '肖恩·贝克', 8.1, 106269, 'tt5649144', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2496148493.jpg', 0.4, 1.7, 18.4, 51.8, 27.6, '0.581795,-0.004903,-0.597936,0.457735,-0.265512,-0.106575,0.886108,0.165836,-0.395501,-0.246027,0.302205,0.892109,0.007162,0.658902,0.020995,0.039192,-0.427101,-0.191072,-0.342660,-0.361597,-0.315919,-0.422077,-0.333056,-0.478000,-0.358602,-0.116014,0.065969,0.180016,0.030641,0.308805,0.002393,-0.147873,-0.326129,0.218063,-0.526147,-0.054144,0.285628,-0.091059,-0.178779,0.349309,-0.182550,0.012253,-0.180154,-0.428037,0.475728,0.390758,0.982969,0.015830,-0.058886,0.044725,0.255805,-0.121248,-0.297609,0.234637,0.357586,-0.271925,0.466862,-0.265446,-0.410878,0.169563,0.182477,-0.590619,-0.498599,-0.016872,0.037528,-0.112263,-0.725016,0.726138,0.072929,-0.210794,0.293660,-0.598185,-0.033883,0.151393,-0.193174,0.700196,-0.238992,0.161153,-0.579908,0.260697,0.538554,0.035110,-0.385724,0.244703,-0.336161,-0.599215,0.030848,-0.371053,-0.745668,-0.262521,0.257335,-0.522142,-0.216425,0.155222,-1.063175,0.332645,-0.238395,-0.519840,0.098333,-0.013232,-0.325824,-0.865556,0.296925,-0.600588,-0.107629,0.282588,0.078138,0.042520,0.710569,-0.817445,0.284192,0.792506,0.621441,-0.165227,0.763158,-0.166079,0.458081,0.071990,-0.247724,0.271549,-0.199474,0.760646,0.059761,0.673671,-0.087766,-0.147969,-0.450072,0.642231', '2134285', '1309101', '30205667', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26779401', '民王番外篇：恋爱总选举', '剧情', '尽心辅佐武藤泰山（远藤宪一 饰）登上政坛顶点的首席秘书贝原茂平（高桥一生 饰），当年也有一段刻骨铭心的经历。五年前，内阁总理大臣突然辞职，以国土交通大臣乡田刚（升毅 饰）为代表的数名政客围绕首相宝座展开激烈竞争。贝原时任乡田的秘书，他的父亲曾经也效力乡田麾下，甚至不惜替主人背上罪名死去。在竞选过程中，乡田团队加入了一名美女雪野诗音（相武纱季 饰），对方居然正是贝原学生时代曾深深喜欢的学姐。随着竞选的白热化，针对乡田的攻击日趋激烈，雪野展现出迥异于过去的一面，而乡田也变得越来越让贝原感到陌生和心寒。在人生和政途的岔路口，贝原茂平完成了和武藤泰山的邂逅……©豆瓣', '高桥一生', '山本大辅', 8.1, 6925, '', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2391272985.jpg', 0.3, 1.2, 21.3, 48.7, 28.5, '-0.062561,0.030044,-0.517168,0.722369,-0.004206,-0.318919,0.431356,0.321920,-0.668557,-0.267487,0.381642,0.742829,-0.102348,-0.026996,0.653144,-0.354370,0.094550,-0.737295,-0.273757,0.039864,-0.074960,-0.407303,-0.275188,-0.197493,-0.280413,-0.403633,0.955707,0.142044,-0.158138,0.640335,0.436643,0.323630,-0.018910,0.290842,0.113825,-0.162778,0.140055,0.216676,-0.497064,-0.171843,-0.283136,-0.386964,-0.078562,-0.070075,0.131827,0.025956,0.376850,-0.143975,-0.188061,-0.355315,0.534655,-0.117124,-0.031167,0.049083,0.501852,0.354765,0.177464,0.451998,-0.137310,-0.051427,-0.128183,-0.146737,-0.578884,0.050626,0.105592,0.069947,-0.346068,0.367764,-0.168586,-0.344224,0.414868,-0.236084,-0.052898,0.332336,0.284303,0.295345,-0.364996,0.028603,-0.052227,0.252882,0.654608,0.087287,-0.183409,-0.090790,0.032216,-0.446035,-0.201719,-0.413371,-0.230214,-0.038174,-0.123700,0.037191,0.010665,0.313681,-0.351185,-0.165384,-0.077331,-0.217203,0.320955,-0.263985,-0.097893,-0.406983,-0.177600,-0.306505,0.011513,-0.049770,0.135823,-0.282663,0.778794,-0.856192,0.276113,0.299565,0.394983,-0.300035,0.551290,0.336645,0.112708,-0.303807,-0.150246,0.119854,0.096474,0.375655,-0.096473,0.161138,-0.367999,-0.120556,-0.259311,0.232140', '26615753', '35030151', '25880986', '1780122');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26781703', '上帝之国', '剧情', '约翰尼（乔什·奥康纳 Josh O''Connor 饰）是一位24岁的青年，和父亲马丁（伊恩·哈特 Ian Hart 饰）、祖母戴德利（盖玛·琼斯 Gemma Jones 饰）过着相依为命的日子。约翰尼家中经营着一间农场，因为父亲中风瘫痪，所以农场里大大小小的事情都要约翰尼来完成。约翰尼有一个秘密，他是一名同性恋者，为了保守这个秘密，约翰尼不断的压抑自己的情感，积攒了非常多的压力。一天，一个名叫格奥尔基（亚力克·塞克雷亚努 Alec Secareanu 饰）的工人来到农场做帮手，这个年长的男人教会了约翰尼很多事情，随着时间的推移，约翰尼和格奥尔基之间的关系越来越亲密起来。©豆瓣', '乔什·奥康纳', '弗朗西斯·李', 8.4, 52559, 'tt5635086', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2510209986.jpg', 0.3, 1.2, 15.6, 45.6, 37.3, '-0.083160,-0.253500,-0.571978,0.503311,-0.289934,-0.244971,1.161584,0.093402,-0.688402,-0.655346,0.021034,0.714033,-0.055362,0.369581,0.290458,0.089684,-0.486763,-0.540294,0.048170,-0.374922,-0.214936,-0.614852,-0.323193,-0.339831,-0.240702,-0.400615,0.317950,-0.122912,0.120245,0.304150,0.411462,0.214371,0.196785,0.301060,-0.162313,0.027813,0.559682,-0.248110,-0.090128,0.106035,0.123869,0.160204,-0.040389,-0.023427,0.214344,0.440434,0.336505,0.059610,-0.162732,0.022028,0.091907,-0.046194,0.022963,0.027555,0.426299,-0.034112,0.275920,0.372149,-0.348570,0.009181,0.037856,-0.238996,-0.572901,0.030664,0.190137,0.283196,-0.755754,0.320815,-0.228816,-0.260951,-0.172307,-0.508849,-0.074192,0.489178,0.049773,0.313730,-0.363534,0.006588,-0.512465,0.109983,0.600854,-0.096700,0.011804,0.390820,-0.438903,-0.290531,-0.205190,0.014268,-0.672263,-0.251405,0.126776,-0.301061,0.167998,0.387730,-0.608336,-0.000646,-0.227785,-0.319674,-0.084604,-0.052208,-0.004308,-0.489113,-0.282854,-0.559729,-0.223236,0.156482,0.046633,-0.211549,0.763239,-0.430678,0.252863,0.574714,0.345727,-0.229539,0.510371,0.140401,0.415850,-0.299007,-0.117290,0.311640,-0.134841,-0.062498,0.003966,0.421659,0.164108,-0.394101,-0.255137,0.587304', '4301215', '2002744', '1578663', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26781921', '跆拳道', '剧情', '费尔南多（卢卡斯·帕帕 Lucas Papa 饰）决定和班上的同学们前往布宜诺斯艾利斯度假，这是一场特殊的狂欢，因为到场的都是男生，女生们被拒之门外，如此一来，男孩子们便可以聚在一起，毫无顾忌的说说他们的心里话，甚至可以脱个精光，在岸边晒太阳。卢克（尼古拉斯·巴索夫 Nicolás Barsoff 饰）、里奥（弗朗西斯科·贝尔坦 Francisco Bertín 饰）、马克西（阿图罗·弗鲁托斯 Arturo Frutos 饰）和胡安（安德烈斯·加瓦达 Andrés Gavaldá 饰）等人都加入了这场派对，但费尔南多还感觉不够，他邀请了跆拳道班的格曼（加布里埃尔·爱泼斯坦 Gabriel Epstein 饰）加入了他们的队伍，哪知道格曼是一名同性恋者，他的到来给这些男孩之间的关系带来了微妙的变化。©豆瓣', '加布里埃尔·爱泼斯坦', '马可·伯格', 7.5, 9635, 'tt5643380', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2414137671.jpg', 1.3, 5.5, 33.2, 39.3, 20.7, '0.456940,-0.338984,-0.472634,0.319682,-0.235918,-0.160018,0.510992,0.202908,-0.365609,-0.142803,-0.089171,0.723666,-0.428760,0.224167,0.390895,-0.067267,-0.615380,-0.768960,0.052180,-0.259736,-0.285701,-0.631943,-0.069563,-0.242352,-0.025836,-0.217275,0.117893,-0.253936,-0.203346,0.706101,0.540316,0.355019,0.319182,0.578496,-0.120131,0.051142,0.199637,-0.082848,-0.008533,0.043547,-0.246644,0.131721,-0.369948,0.188810,0.439985,0.387212,0.463476,-0.150350,0.328718,0.059784,-0.105694,-0.037299,0.322430,0.360354,0.369581,-0.101946,0.322003,0.088126,0.192022,0.105573,0.102650,0.006191,-0.635993,0.351358,0.101190,0.240243,-0.472337,0.450752,0.053378,-0.274917,0.142819,-0.075665,0.199001,0.394775,0.071542,0.179675,0.097680,-0.267828,-0.658583,-0.020161,0.664958,-0.144115,-0.079330,0.229209,-0.440123,-0.354683,-0.175627,0.128838,-0.246400,-0.077044,0.203892,-0.152694,0.206922,0.296580,-0.722399,-0.091006,-0.116210,-0.225918,-0.202472,-0.357725,0.209460,-0.854194,0.035138,-0.346046,-0.341467,0.142131,0.090059,0.017070,0.874054,-0.643384,0.117879,0.451585,0.413985,-0.351309,0.731305,0.179265,0.226074,-0.114887,-0.367451,-0.002890,0.164357,-0.015413,0.187210,0.778320,0.173792,-0.261019,-0.122259,0.282319', '34429100', '30162520', '3811356', '314796