INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26782656', '栋笃特工', '喜剧', '陳先生(黃子華 飾)本來是最頂尖的特工，但因夥伴一次無心之失慘被停職，同時還得罪了女警佘香(佘詩曼 飾)，欠下情債。二十年後，城中名人相繼失常。陳先生再被委以重任，以為可大展身手，誰知此案與宅男圈內的藥物有關。為了社會安寧，陳先生只好化身不修邊幅的宅男查案，引發各種難題和笑彈。', '黄子华', '张家杰', 5.2, 7345, 'tt7759626', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2509642867.jpg', 10.3, 36.1, 38.6, 12, 3, '0.405393,-0.292771,0.207646,0.112976,-0.242435,-0.635712,0.205680,-0.027529,-0.615194,-0.243919,0.203102,0.690019,-0.357610,0.126204,0.323955,0.028276,0.430500,-0.541367,0.199581,-0.182522,0.129269,-0.463587,0.166271,0.561554,-0.206666,-0.435035,0.392033,-0.061966,0.051134,0.180437,0.158481,0.491698,0.086393,0.312109,-0.060595,0.049143,0.021502,-0.480678,-0.152766,0.148074,0.363371,-0.497925,0.008036,0.139174,0.126514,0.450686,0.355777,-0.093412,-0.624085,-0.139649,0.657931,-0.508799,-0.121410,0.329437,0.414027,0.014077,0.192926,0.529699,-0.005077,-0.419284,0.142338,-0.093838,-0.170811,0.177192,0.146456,-0.233356,-0.646534,0.272972,-0.336127,-0.374192,-0.413203,0.132042,0.493154,0.213830,0.192451,0.074465,0.213483,0.014941,-0.335838,0.290764,0.592180,0.291183,-0.374485,0.100417,0.546961,-0.790991,0.316926,-0.706307,-0.624672,0.387317,0.015578,-0.205685,-0.411697,0.019753,-0.516020,0.094840,-0.668718,0.376441,-0.169292,-0.361372,-0.107927,-0.192678,-0.473426,-0.046560,-0.096989,0.206597,0.619043,-0.185092,0.211409,-0.962649,-0.079169,0.435650,0.319144,-0.710240,0.991960,0.078845,-0.087262,0.189951,0.070662,-0.519901,0.499857,0.608857,0.362121,0.429852,-0.073682,-0.736859,-0.428795,-0.284093', '1419416', '1302384', '22964524', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26784898', '花牌情缘：结', '剧情', '精彩纷呈的全国大赛名人战上，绫濑千早（广濑铃 饰）无缘对战女王若宫诗畅（松冈茉优 饰），她立志在来年击败女王。与此同时，永世名人周防久志（贺来贤人 饰）力挫原田老师（国村隼 饰），其卓绝表现使绵谷新（真剑佑 饰）重燃对花牌的热情。在此之后，新向千早表白，彼此在各自的学校为接下来的全国大赛积极备战。已经三年级的千早和部员们网罗新人加入，而真岛太一（野村周平 饰）在得知新的表白后，仿佛失去了对花牌的热情，进而缺席了十分重要的东京预选赛。慢慢看清自己的心意后，太一得到周防的认同，得以跟随对方学习。各怀心事的年轻人，朝着新一年的圣殿奋力前行……本片根据末次由纪的同名漫画改编。©豆瓣', '广濑铃', '小泉德宏', 7.9, 10252, 'tt6821870', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2507984247.jpg', 0.6, 2.1, 25.1, 46.3, 25.9, '-0.000758,0.090571,-0.464673,0.500275,0.184495,-0.254439,0.164120,0.015539,-0.383280,-0.114304,0.286709,0.653954,-0.371656,-0.010923,0.404262,-0.309180,-0.127298,-0.772671,-0.228789,-0.218722,-0.205826,-0.311470,-0.038954,0.151929,-0.284709,-0.286736,0.782064,-0.087272,-0.069057,0.864237,0.471468,0.270423,0.164285,0.171617,0.104633,0.004248,0.151112,0.220177,-0.279810,0.247458,-0.304633,-0.222633,-0.543198,0.144145,0.113740,0.211811,0.751723,-0.289122,-0.073672,-0.089844,0.588859,-0.152648,-0.103277,0.181645,0.454087,0.298348,0.017337,0.205390,-0.192626,0.161834,-0.251064,-0.085734,-0.496573,-0.040254,0.219841,0.176312,-0.394431,0.523550,0.048539,-0.050221,0.393324,-0.253310,-0.176288,0.500196,0.286228,-0.050369,-0.110306,0.142138,-0.078950,0.409832,0.543063,0.028746,-0.100299,0.121290,-0.041134,-0.450443,-0.042277,-0.224594,-0.328138,-0.161164,0.193394,0.206670,0.268865,-0.086618,-0.399280,-0.220100,0.055974,-0.358226,0.382407,-0.483046,0.063388,-0.789564,-0.169506,-0.397873,-0.221467,0.011419,0.129087,-0.302457,1.113276,-1.094480,0.067246,0.267822,0.004378,-0.247141,0.454595,0.075505,-0.041136,-0.334755,-0.246436,0.135821,0.065109,0.452015,-0.054636,0.564572,0.014231,-0.305440,-0.541851,0.282060', '25922902', '3811356', '1826173', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26785137', '无手的少女', '剧情', '在生活窘困之时，一位磨坊主将女儿卖给了魔鬼。受到纯洁之心的保护，女孩从恶魔手中逃出，却被剥夺走了一双手。', '阿娜伊斯·德穆斯蒂埃', '塞巴斯蒂安·劳德巴克', 7.8, 12816, 'tt5698496', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2388623931.jpg', 0.5, 1.6, 24.7, 53.3, 20, '-0.049170,0.327074,-0.809720,0.407212,-0.871591,-0.252386,1.232618,0.135355,-0.191261,0.200470,0.213787,1.152397,-0.240402,0.225115,0.495998,0.161875,0.432860,-0.892338,-0.287765,-0.088750,-0.307864,0.024325,-0.315739,0.399309,-0.249495,-0.793711,0.491949,0.109924,-0.161170,0.242638,-0.070014,0.292169,-0.215099,0.517770,-0.488387,-0.286534,-0.106926,-0.427126,0.141871,0.584319,-0.018525,-0.537008,0.186340,0.512500,-0.349559,0.123668,1.132714,-0.740345,-0.018951,-0.563838,0.119459,-0.156334,-0.217104,0.512028,-0.259992,-0.078268,-0.182181,-0.112980,-0.322010,0.009516,0.989198,-0.775509,-0.879341,-0.286166,-0.284516,0.059136,-1.020606,0.023370,-0.312223,0.049252,-0.006790,-0.356603,0.545812,0.116682,0.156978,0.690012,-0.312351,0.232629,-0.379933,0.072964,0.744940,-0.283522,-0.019792,0.241561,-0.383821,-0.418431,0.212165,-0.155396,-0.736435,-0.208798,0.916096,0.130894,-0.461482,0.244108,-0.772758,-0.148053,-0.480737,-0.115563,0.241116,-0.685449,-0.560058,0.340648,-0.105624,0.186405,-0.271820,0.215704,0.237022,-0.324824,1.155480,-0.813829,0.645211,0.669373,0.593664,-0.406185,0.259166,-0.296313,0.433604,0.339115,0.242026,0.338141,0.701631,0.867293,0.500885,0.227379,-0.549818,-0.037445,-0.350448,0.619636', '21619567', '10486471', '1464907', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26785590', '无爱可诉', '剧情', '故事发生在一个支离破碎的家庭之中，珍亚（玛丽安娜·斯皮瓦克 Maryana Spivak 饰）和鲍里斯（阿列克谢·罗津 Aleksey Rozin 饰）结婚多年，时间和无休无止的争吵早就磨光了两人对于彼此仅存的感情，是这个家庭走到了分裂的边缘，不仅如此，这两人都在外面找到了新的伴侣，这更加速了这个家庭消亡的进度。珍亚和鲍里斯两人有一个12岁的儿子阿廖沙（马特威·诺维科夫 Matvey Novikov 饰），都想要投奔自由生活的两人都不愿意继承阿廖沙的抚养权，为了儿子的归属问题，夫妻两人又再度陷入了无止尽的骂战之中。就在这场战争进行到白热化的境地时，阿廖沙失踪了，作为他唯二的监护人，珍亚和鲍里斯开始意识到，他们必须收起各自的武器，共同寻找这个孩子。©豆瓣', '玛丽安娜·斯皮瓦克', '安德烈·兹维亚金采夫', 7.4, 10621, 'tt6304162', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2459651426.jpg', 0.5, 2.9, 34, 50.3, 12.3, '0.438627,0.018646,-0.884472,0.527296,-0.111491,-0.418613,0.746745,-0.016746,-0.336151,-0.259098,0.085153,0.872877,-0.170791,0.363805,0.353704,-0.155377,-0.541115,-1.044981,-0.115457,-0.088806,-0.509281,-0.646319,-0.081598,-0.046588,-0.222520,-0.101169,0.692559,-0.104044,-0.157599,0.332793,0.218798,0.206146,-0.034079,0.467002,-0.114557,0.267936,0.230809,0.051506,-0.396581,0.161312,0.059414,-0.001828,0.047603,0.219537,0.041490,0.430842,0.765083,-0.377189,-0.019424,0.014883,0.279304,-0.224544,-0.390448,0.315187,0.439087,-0.113073,0.169834,0.249540,-0.281169,0.000663,-0.014044,-0.038794,-0.907004,0.070336,0.040132,0.156553,-0.550357,0.646308,0.119043,-0.233088,0.137961,-0.323863,0.358266,0.933945,0.081043,0.486431,-0.575351,-0.294418,-0.569256,0.038722,0.852471,-0.124662,-0.392700,0.352121,-0.186139,-0.428839,-0.264543,-0.160438,-0.329950,-0.407751,0.419015,0.409958,-0.247189,0.516295,-0.722497,0.181583,-0.121239,-0.368888,0.201109,-0.583848,-0.070606,-0.457759,-0.487136,-0.710341,-0.368725,0.347816,-0.098096,-0.285535,0.810001,-0.733157,0.144602,0.315400,0.370575,-0.500344,0.639398,0.253012,0.501424,-0.452013,0.155864,0.122513,-0.248470,0.217501,0.246771,0.262213,0.058875,0.199774,-0.450592,0.539667', '25978126', '26678784', '30162520', '1478066');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26786317', '银湖之底', '剧情', '导演大卫·罗伯特·米切尔新作《银湖之底》，讲述一个发生在现代洛杉矶的犯罪惊悚黑色故事，33岁的Sam（安德鲁·加菲尔德 Andrew Garfield 饰）住在洛杉矶，虽然没有正职，却依然渴望出人头地。当年轻且神秘的女邻居Sarah（丽莉·克亚芙 Riley Keough 饰）突然失踪之后，Sam决定寻找这个女人，并在城里展开了一段调查。这段调查使他不得不直面天使之城最为黑面的一面，理清与丑闻和阴谋有关的失踪及神秘谋杀。', '安德鲁·加菲尔德', '大卫·罗伯特·米切尔', 6.5, 10816, 'tt5691670', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2520302442.jpg', 4, 14.4, 42.9, 29.8, 8.9, '0.293698,-0.214505,-0.710292,0.635289,0.065113,-0.108838,0.982203,-0.074903,-0.455845,-0.690056,0.260298,0.586605,-0.423998,0.428302,0.309235,-0.139705,-0.278750,-0.634269,0.197957,-0.458149,-0.094809,-0.640680,-0.510955,0.069641,-0.025846,-0.182527,0.485112,0.023441,-0.202435,0.413494,0.542627,0.427449,-0.299724,0.521352,-0.144982,-0.207840,0.293538,0.217703,-0.324886,0.106987,0.120153,-0.182492,-0.188692,0.306434,0.103569,0.460991,0.488791,-0.583985,-0.306624,-0.054685,0.384720,-0.145653,-0.010352,-0.033853,0.401253,-0.070073,0.165010,0.533944,-0.220224,-0.350763,-0.134441,-0.089693,-0.651282,0.224505,0.326676,0.285173,-0.523348,-0.045996,-0.077696,0.022639,0.062259,-0.206651,0.163141,0.581842,0.162242,0.416498,0.201288,0.239660,-0.236229,0.284536,0.497978,0.074236,-0.339555,0.306633,0.226698,-0.214078,0.027052,-0.026186,-0.320056,0.223536,0.298778,-0.051734,-0.114135,0.246194,-0.510669,-0.113288,-0.367860,-0.113846,0.147231,-0.388090,-0.256053,-0.738677,-0.358251,-0.279406,-0.118860,-0.043524,0.044148,-0.145652,0.422715,-0.754875,0.175537,0.564538,0.143251,-0.640641,0.330931,0.300696,0.103601,-0.365119,-0.263548,0.522201,0.257076,0.251097,-0.259692,0.304422,0.009064,-0.322564,-0.610757,0.391307', '1316693', '1301686', '25909236', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26786642', '摘金奇缘', '喜剧', '《摘金奇缘》改编自新加坡作家关凯文畅销全球的小说《疯狂的亚洲富豪》，讲述了美国出生的华裔经济学教授朱瑞秋（吴恬敏 饰）与男友杨尼克（亨利·戈尔丁 饰）一起参加他的好友婚礼时，竟惊讶地发现男友原来是亚洲“钻石王老五”。惊魂未定的瑞秋不仅要面临尼克身边前赴后继的美女攻势，还要直面男友背后错综复杂的豪门恩怨，更有杨紫琼饰演的高傲富家婆婆进行百般阻挠。当朱瑞秋误入名车、派对、珠宝、豪宅萦绕的纸醉金迷的亚洲富豪世界，爱情突现阶级鸿沟，作为现代版“高知灰姑娘”，她能否打好这场爱情保卫战？', '吴恬敏', '朱浩伟', 6, 113765, 'tt3104988', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2540295055.jpg', 4.6, 19.3, 51.4, 20.1, 4.6, '0.061920,0.035892,-0.431124,0.449812,0.376392,-0.178948,0.454621,0.007032,-0.394273,-0.188739,0.290552,0.560221,-0.482349,0.186088,0.350224,0.055403,-0.209836,-0.772841,-0.109527,0.013478,0.085647,-0.146587,-0.369372,-0.020424,0.059173,-0.015358,0.588733,-0.072795,-0.202764,0.507494,0.529853,0.401717,-0.046134,0.134181,-0.193824,-0.055617,0.442316,0.330843,-0.751301,0.153038,-0.161867,-0.002132,0.151072,-0.091812,0.061029,-0.050630,0.388682,0.087785,0.310725,-0.175071,0.534883,0.003870,-0.097547,0.000661,0.459605,-0.079570,0.440233,-0.039139,0.275099,-0.181446,0.289931,-0.274857,-0.430155,0.110691,0.480026,0.201014,-0.253014,0.218232,-0.065486,0.119511,0.071719,0.121642,-0.000319,-0.008452,0.499331,0.222422,0.200982,0.293218,-0.296081,0.625252,0.389146,0.183223,-0.277565,0.117450,-0.400311,-0.299832,0.172441,-0.383920,-0.760218,0.092876,0.305449,-0.298003,0.040504,0.546954,-0.549069,-0.139949,-0.072029,0.008061,0.319222,-0.332872,-0.037248,-0.749723,-0.347664,-0.353869,0.129849,-0.154255,0.233186,-0.171575,0.833292,-0.529319,0.008100,0.440233,0.375130,-0.306291,0.806368,0.233127,-0.081234,-0.198342,-0.273476,0.302119,-0.254266,0.035166,-0.560683,0.090152,-0.062753,-0.195234,-0.053925,0.448441', '1322847', '4301278', '1908036', '2338019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26786669', '决战中途岛', '剧情', '电影讲述的是第二次世界大战太平洋战争重要转折点——中途岛海战：经此一役，日本海军受到“降维打击”，美日海上实力反转，从而扭转了整个太平洋战场的局势。影片通过参战士兵和飞行员一个个鲜活的故事，带领观众逐步进入1942年6月初发生在太平洋中途岛附近那场令人难以置信的战争……', '艾德·斯克林', '罗兰·艾默里奇', 7.5, 225728, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2558678036.jpg', 0.5, 3.1, 31.6, 49.2, 15.7, '-0.344674,-0.132007,-0.855835,0.520156,0.947108,0.269597,0.271583,-0.324978,-0.740410,0.240155,0.340604,0.658501,-0.288519,-0.367562,0.426049,-0.249708,-0.504444,-0.897345,-0.182250,0.348501,-0.095636,-0.252771,-0.468537,-0.351496,0.141708,-0.779786,1.047043,0.628106,-0.909086,0.429436,-0.086506,0.170478,-0.013024,0.359826,0.372669,-0.102560,-0.096526,-0.398016,-0.763563,0.184537,-0.668838,-0.326643,-0.062068,0.097804,-0.129585,0.005044,1.053495,-0.264053,-0.219672,-0.133694,0.600078,-0.671840,-0.449113,0.067407,0.728723,0.054229,-0.184697,0.205448,0.326484,-0.096969,-0.463237,-0.165131,-0.320863,-0.006976,-0.102084,0.165309,0.075252,0.595420,-0.153741,0.705051,0.211993,0.101726,0.197308,0.983626,0.460171,0.186355,-0.166436,0.232844,-0.223179,0.224829,0.974536,-0.314392,-0.367995,-0.050442,0.025852,-0.363627,-0.442095,-0.718860,0.282025,0.702824,0.306208,-0.396362,-0.023572,1.057508,-0.419812,0.398666,-0.444302,-1.187429,0.018619,0.079494,-0.085372,-1.068714,-0.475159,-0.363532,-0.039114,-0.043714,-0.119812,0.073980,0.980549,-0.188640,-0.125589,0.526816,0.019461,-0.229683,0.207486,0.235504,0.333805,-0.212963,0.376537,0.368705,-0.492035,0.297300,-0.282692,0.035336,-0.341466,0.100930,0.237499,0.023653', '1291824', '1298911', '26718836', '1293626');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26787124', '青禾男高', '剧情', '在一所名为青禾男高的学校里，荆浩（欧豪 饰）和阿屁、谭嘉木、幺鸡、二饼四位少年在特别的校园环境中结成了生死与共的挚友兄弟，并成为这所男高里唯一对抗校园霸凌的团体，压制了柴田（林遣都 饰）等人横行霸道的校园恶行。在特殊的时代氛围里，两方势力保持着微妙的平衡，直到女教师柳禾（景甜 饰）的出现，平衡被打破，这所男高里的少年们将何去何从，就此展开的激战如箭在弦。', '景甜', '蒋卓原', 3.9, 23198, 'tt7619402', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2460295681.jpg', 38.4, 36, 20.8, 3.9, 0.8, '0.496996,0.142608,-0.569907,0.389785,0.058937,-0.084440,0.607849,0.394562,-0.456967,-0.112080,0.450313,0.365554,-0.160054,0.343147,0.397411,-0.445158,0.020629,-0.892371,-0.307131,-0.161037,-0.137303,-0.193821,-0.502610,0.143347,-0.322052,-0.425948,0.782202,0.136822,-0.468470,0.299285,0.129061,0.309834,-0.493911,0.296782,-0.039442,-0.099318,0.248571,0.013690,-0.334247,0.061695,-0.333877,-0.271994,-0.199936,0.025307,-0.020153,0.352312,1.063827,-0.520277,-0.014751,-0.025567,0.215627,0.005957,-0.577496,0.354901,0.436686,0.025085,0.085248,0.287524,-0.271958,0.280388,0.077165,-0.087371,-0.400849,0.012077,0.304837,0.229714,-0.494026,0.980701,0.456627,-0.505067,0.258895,-0.047652,0.056401,0.200943,0.355239,0.358819,-0.160019,0.228991,-0.358309,0.004907,0.662670,-0.071208,-0.407317,-0.113820,-0.244462,-0.472703,-0.426305,-0.317122,-0.504009,-0.448422,0.174074,0.021384,-0.040721,0.176687,-0.848543,0.004999,0.033078,-0.034324,-0.030090,-0.478382,-0.067596,-0.920504,-0.025677,-0.349460,-0.172036,0.199762,0.161830,-0.183899,0.884233,-1.006893,0.069653,0.272108,0.269170,-0.281535,0.581793,0.218367,0.476966,-0.119857,-0.534522,-0.089736,0.106967,0.330403,0.201398,0.542695,-0.561992,-0.070913,-0.380729,0.472845', '1826173', '3811356', '5403927', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26787574', '奇迹男孩', '剧情', '奥吉（雅各布·特瑞布雷 Jacob Tremblay 饰）是一个10岁的男孩，除了头戴一个巨大的太空头盔外，他和其他的同年龄孩子别无二致。头盔下隐藏了奥吉因为各种手术而伤痕累累的脸庞，它不仅完美的隐藏起了奥吉脆弱自卑的内心，也成功的防止了奥吉的模样吓到别的孩子。奥吉没有上过学，他的所有文化知识都是母亲伊莎贝尔（朱莉娅·罗伯茨 Julia Roberts 饰）在家教授给他的。然而，伊莎贝尔渐渐感觉到，家庭课堂无法满足奥吉的成长需要，除了学习知识，奥吉还必须学会的，是如何同除了家人以外的人交流。在忧虑重重之中，伊莎贝尔将奥吉送入了一间公立学校里，在那里，奥吉面临的是他人生中必须要战胜的挑战。©豆瓣', '雅各布·特伦布莱', '斯蒂芬·卓博斯基', 8.6, 523616, 'tt2543472', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2507709428.jpg', 0.1, 0.7, 11.9, 44.3, 43, '0.314372,0.034127,-0.820484,0.709533,-0.483473,-0.318774,0.799678,0.068891,-0.494743,-0.227417,0.083702,0.658711,0.136952,0.355336,0.087372,0.096793,-0.309371,-0.623173,-0.188596,-0.120482,-0.555128,-0.559665,-0.363078,-0.166008,-0.318184,-0.598819,0.569176,-0.017922,-0.253731,0.238996,0.165827,0.099353,0.037768,0.362492,-0.113916,-0.089498,-0.046316,-0.310217,0.021921,0.006844,0.101831,-0.099320,-0.082195,0.308555,0.098318,0.426862,0.607254,-0.256971,0.073813,0.014694,0.301293,-0.039488,-0.108925,0.301632,0.056916,-0.143169,0.120399,0.074728,-0.136433,0.217724,0.349970,-0.061248,-0.875986,-0.226757,0.119914,0.148540,-0.753182,0.576440,-0.064678,-0.208234,0.233493,-0.310807,0.164838,0.155656,-0.068557,0.682109,-0.259151,-0.112340,-0.562941,0.208999,0.413690,-0.016936,-0.377238,0.207659,-0.515353,-0.382600,-0.110491,-0.316890,-0.452751,-0.041709,0.341709,0.160205,-0.374494,0.223283,-0.413532,0.198438,-0.328518,-0.343263,-0.196681,-0.373885,-0.053416,-0.575572,-0.151231,-0.733765,-0.301908,-0.082403,0.069278,-0.393190,0.881297,-0.968383,0.120688,0.440083,0.233698,-0.138365,0.561073,0.135412,0.396803,0.137317,-0.080199,0.277345,-0.028814,0.238100,0.020558,0.637565,0.069473,-0.070318,-0.399270,0.625169', '1793491', '26283288', '35144311', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26787585', '猫', '音乐', '韦伯经典音乐剧《猫》将拍电影版，演员定为詹妮弗·哈德森、泰勒·斯威夫特、詹姆斯·柯登、伊恩·麦克莱恩。歌手出身、曾凭《追梦女郎》获奥斯卡最佳女配的哈德森饰演“魅力猫”葛丽兹贝拉，历尽沧桑的她将唱出经典歌曲《Memory》，别的演员角色尚未公布。汤姆·霍伯(《国王的演讲》《悲惨世界》《丹麦女孩》)执导，Lee Hall(《跳出我天地》)编剧，Working Title影业出品，11月在英国开拍。', '詹妮弗·哈德森', '汤姆·霍伯', 4.2, 5074, 'tt5697572', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2575205014.jpg', 42.3, 25.7, 18.8, 7, 6.2, '0.028814,-0.015661,-0.302336,0.467438,0.141924,-0.143580,0.286819,0.162488,-0.121780,-0.066904,0.322061,0.786635,-0.753201,-0.097641,0.575791,-0.035064,-0.409249,-0.579706,-0.054017,-0.157757,0.723283,-0.178683,-0.244355,0.028077,-0.161851,-0.427086,0.875121,-0.520455,-0.079996,0.035768,0.785245,-0.030390,0.165247,-0.507249,0.220585,0.494268,0.369845,-0.404717,-0.449459,0.627948,0.146165,-0.020484,-0.114118,-0.296828,-0.179653,0.071790,0.326992,-0.253675,0.614580,0.045934,0.836160,0.000332,0.082565,-0.235038,-0.218685,-0.138546,0.225211,0.074353,0.325244,-0.011889,-0.035455,-0.490004,-0.217794,0.360314,-0.118911,0.386227,-0.257670,0.155662,-0.449948,0.585811,0.187858,-0.094798,-0.349235,-0.513846,0.409745,0.011349,0.440980,0.600387,-0.110302,0.791687,0.015443,-0.090120,-0.244223,0.237790,-0.154713,-0.561275,-0.164725,-0.167720,-0.597908,0.269527,0.588928,-0.338600,0.192133,-0.098693,-0.021425,-0.242943,-0.036082,-0.185719,-0.031724,-0.154150,0.082425,-1.184388,0.088767,0.314572,0.498661,-0.829984,0.328287,-0.475688,0.729147,-0.485581,0.154490,0.493465,-0.010427,0.106719,0.658727,-0.082995,0.035976,-0.345389,-0.077521,0.628249,-0.046397,-0.364201,0.122308,0.281831,-0.075461,-0.160832,-0.028777,0.424616', '34961898', '30397916', '30373716', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26788605', 'P与JK', '喜剧', '女高中生本谷歌子（土屋太凤 饰）天真烂漫，有一次她虚报年龄和好友矢口三门（玉城蒂娜 饰）及其他姐妹参加了联谊活动。酒席上，不善言辞的冷面帅哥佐贺野功太（龟梨和也 饰）帮她解了围，事后借着酒劲儿，功太向身边的女孩表达了希望更进一步交往的想法。可当歌子把真实年龄说出来时，攻太却转热为冷，扬长而去。次日，歌子和好友遭到一名警察的盘问。令歌子她们惊讶的是，对方居然正是佐贺野功太。功太现年23岁，是音尾警察局地域课的巡查长。他刻意和未成年的歌子保持距离，并且警告女孩们要注意附近出没的变态。未过多久，歌子果然遭到变态纠缠。危机时刻，功太出手相助。似乎借着这件事，歌子开始转变对功太无情冷漠的看法，她无可救药落入了爱河之中。本片根据三次真纪的同名漫画改编。©豆瓣', '龟梨和也', '广木隆一', 5.3, 6500, 'tt5701132', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2390673514.jpg', 10.5, 33.7, 41.1, 10, 4.7, '0.429199,-0.016434,-0.254098,0.289138,-0.128389,0.013932,0.518785,0.047500,-0.511999,-0.211483,0.145144,0.353753,-0.336196,0.041564,0.220042,-0.278396,-0.162366,-0.571990,-0.024425,-0.023924,-0.128348,-0.313794,-0.098593,0.190959,-0.230774,-0.381053,0.347926,-0.072896,-0.230927,0.464954,0.451863,0.158004,-0.061506,0.561465,-0.016787,-0.110021,0.024857,0.111395,0.118495,0.217254,-0.159901,-0.131891,-0.088766,0.079531,-0.029252,0.520097,0.536652,-0.066637,-0.326182,-0.254323,0.211986,-0.017930,-0.101474,0.256469,0.551916,-0.117564,0.330620,0.081233,-0.144596,-0.120622,-0.295881,0.064729,-0.231525,0.244360,0.146736,0.051121,-0.447232,0.083245,-0.175421,-0.172740,0.148086,-0.136229,-0.066393,0.136908,0.341576,0.073634,-0.179450,-0.016584,-0.173859,-0.007449,0.506566,-0.002632,-0.154371,0.160217,-0.077445,-0.298198,-0.149129,-0.207913,-0.234304,0.098365,-0.070244,-0.084451,-0.232283,0.004826,-0.442321,-0.295718,-0.100409,-0.031532,0.146729,-0.433551,-0.246307,-0.550285,-0.027387,-0.363315,-0.136676,-0.105225,0.274885,-0.242580,0.711846,-0.719320,0.029094,0.274560,0.296329,-0.331781,0.680093,0.338538,-0.192456,-0.277615,-0.121896,0.002483,-0.035737,-0.141890,0.165795,0.501203,-0.034758,-0.317073,-0.239957,0.219436', '1316589', '25922902', '3445516', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26788667', '名侦探柯南：唐红的恋歌', '动画', '阳光明媚的一天，柯南（高山南 配音）、小兰（山崎和佳奈 配音）以及少年侦探团的伙伴们随同毛利小五郎（小山力也 配音）来到大阪，参加在当地举行的“高中生皋月杯”百人一首和歌大赛。期间，他们还见到了彼此的好友服部平次（堀川亮 配音）和远山和叶（宫村优子 配音）。就在比赛进行中途，一封爆炸预告信送到电视台，警方迅速行动起来组织疏散。疏散一半时，爆炸突然发生，结果平次与和叶被困在建筑物中。而在一连串的混乱过后，一位皋月杯相关人员的尸体突然出现在众人面前。迷离的案情再度引起柯南的注意……本片根据青山刚昌的超人气漫画改编，系“名侦探柯南系列”第21部电影版。©豆瓣', '高山南', '静野孔文', 6.9, 63783, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2461296240.jpg', 1.5, 9.3, 45.2, 30.3, 13.7, '0.055445,-0.139072,-0.596537,0.320744,0.360518,-0.078760,0.366950,0.004052,-0.283074,-0.284494,0.191655,0.787462,-0.557372,0.280197,0.624714,-0.307845,-0.563720,-0.917695,-0.170279,-0.242101,-0.151379,-0.361391,0.081917,-0.100947,0.205370,-0.277467,0.581964,-0.047755,-0.268319,0.708019,0.126476,0.103367,-0.486216,0.369647,0.264717,0.313722,0.279160,-0.128509,-0.073455,0.327893,-0.302820,-0.245583,-0.481361,-0.392659,0.358387,0.262567,0.853334,-0.115108,-0.297028,0.176007,0.471916,-0.221803,-0.143492,-0.016250,0.654582,0.172881,0.179594,0.290010,-0.278183,0.168225,-0.115340,-0.267513,-0.282328,0.324152,0.047071,0.404204,-0.134457,0.489096,-0.093250,0.007115,0.293640,-0.085636,0.265526,0.428372,0.277817,0.240800,-0.357056,0.098020,-0.057741,0.240767,0.234089,0.072330,-0.207719,0.106588,0.254052,-0.525021,-0.559321,0.142069,-0.093540,0.047577,0.251713,0.100492,-0.032520,-0.033551,-0.719151,-0.296522,0.026566,-0.580970,-0.020498,0.055540,-0.305717,-1.267718,0.216678,0.014334,0.011929,0.119749,0.232395,-0.197574,0.929763,-0.679060,0.034344,0.348969,0.027301,0.040344,0.179295,0.006116,-0.096177,-0.145464,-0.182355,-0.225623,0.249757,0.548382,0.262166,0.490924,-0.228814,-0.115545,-0.346239,-0.105436', '5403927', '20274039', '26094129', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26790961', '闪光少女', '喜剧', '陈惊（徐璐饰）是一个古灵精怪、敢爱敢恨的姑娘，江湖人称“神经”。作为音乐附中的奇葩人物，陈惊人缘欠佳只有男闺蜜“油渣”（彭昱畅饰）甘愿为她鞍前马后。自信满满的陈惊恋上了校草师哥，不料却遭到校草的嘲笑和奚落，还引起了校园两大院系之间的大混战。为了向师哥证明自己，陈惊联手“502宿舍”神秘人物组成2.5次元乐团，挑战权威、破除成见，上演了一幕幕生猛搞笑的青春趣事。一个懵懂怪力的少女，一场默默守护的爱恋，一群奇葩义气的小伙伴，“神经女孩”如何逆袭成为“闪光少女”？2017年暑期《闪光少女》放肆揭晓——不一样，又怎样！', '徐璐', '王冉', 7.2, 279516, 'tt7013194', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2494275431.jpg', 1.8, 6.9, 34.3, 41.5, 15.6, '0.138961,0.087502,-0.403652,0.490081,-0.073822,-0.009842,0.625212,-0.001600,-0.292773,0.026554,0.336114,0.251455,-0.538698,0.373852,0.137336,-0.259818,0.215780,-0.709697,-0.296412,0.140439,-0.013200,-0.175879,-0.280543,0.132842,0.145888,-0.412496,0.519323,0.065864,-0.314898,0.255609,0.606762,0.132236,-0.266278,0.238259,-0.052264,-0.141658,0.169647,0.375442,-0.021698,-0.026354,-0.181062,-0.304244,-0.027297,0.002033,-0.310533,-0.039014,0.597836,-0.143342,-0.090889,-0.216064,0.593429,-0.263940,-0.328013,0.167581,0.312202,-0.108344,0.254549,-0.388756,0.416976,-0.174050,-0.053281,-0.185855,-0.553078,0.053689,0.267984,-0.037272,-0.377953,0.501378,0.105049,-0.186562,0.297482,-0.066232,-0.166919,-0.257706,0.640897,0.344072,-0.114781,0.331313,0.047780,0.202256,0.818078,0.268736,-0.372697,0.088953,-0.082790,-0.147331,0.047141,-0.462639,-0.540274,0.104332,0.028938,-0.369122,0.367577,0.376529,-0.511465,-0.016324,-0.185844,0.275295,0.121848,-0.586242,-0.191754,-0.291195,-0.132381,-0.170801,-0.146261,0.218420,0.275067,-0.300281,1.289846,-0.753728,0.024245,0.565393,0.092963,-0.357506,0.643174,0.167042,-0.159743,-0.270074,-0.249182,0.025482,0.121384,-0.197623,-0.091526,0.469542,-0.295648,-0.004669,-0.197293,0.189341', '27602116', '24284209', '25922902', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26791452', '塔利', '剧情', '马洛（查理兹·塞隆 Charlize Theron 饰）是三个孩子的母亲，这三个孩子中还有一个是刚刚出生没多久，嗷嗷待哺的婴儿。生活被家务和照料孩子完全填满的马洛感到非常的窒息，在这个节骨眼上，她又接到了学校的电话，通知她她的大儿子不能够继续就读普通学校了，需要转到特殊教育学校上学。在弟弟格雷格（马克·杜普拉斯 Mark Duplass 饰）的建议之下，濒临崩溃的马洛请了一位名叫塔利（麦肯兹·戴维斯 Mackenzie Davis 饰）的夜班保姆来帮忙，刚开始，马洛并不信任这个看上去没多大岁数的女人，但随着时间的推移，塔利所展现出的能力和体贴俘获了马洛的心。马洛的人生，因为塔利的出现而产生了翻天覆地的变化。©豆瓣', '查理兹·塞隆', '贾森·雷特曼', 7.7, 27821, 'tt5610554', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2543801665.jpg', 0.3, 1.9, 27.9, 53.1, 16.8, '0.364099,0.001082,-0.752804,0.511294,-0.506818,-0.442520,0.867858,0.470407,-0.541509,-0.510050,-0.125353,0.692382,-0.207491,0.449402,0.272258,0.031961,-0.288058,-0.616290,-0.187200,-0.145439,-0.401884,-0.540169,-0.026025,-0.204261,-0.081713,-0.497540,0.275645,-0.202342,0.162492,0.476131,0.190830,0.416305,0.418290,0.512755,-0.158163,0.223503,0.099515,-0.080082,0.157806,0.126141,0.354255,0.090460,-0.082588,0.123866,0.135112,0.456251,0.518781,0.052907,-0.119619,-0.242299,0.572425,-0.178612,0.038777,0.093606,0.410886,-0.206510,0.151013,-0.085918,-0.286797,0.116434,0.161882,-0.291721,-0.598372,0.172297,-0.016185,0.136061,-0.844398,0.288216,-0.181690,-0.318595,0.100531,-0.443298,0.216114,0.564624,-0.156896,0.562508,-0.237313,-0.122681,-0.602755,-0.090123,0.486772,-0.134683,-0.377846,0.493745,-0.244457,-0.494153,-0.141734,-0.013548,-0.447364,0.054387,0.295023,0.079527,-0.272925,0.148748,-0.339234,-0.137001,-0.358130,-0.468451,-0.105781,-0.621704,-0.219263,-0.469355,-0.223363,-0.360501,-0.361800,0.061010,0.115871,-0.198548,0.750772,-1.038566,0.231889,0.525556,0.131849,-0.288834,0.556870,0.089455,0.199165,-0.254392,0.082459,0.206110,0.048264,0.298210,0.109247,0.534462,-0.010234,-0.060383,-0.485462,0.798383', '1783461', '21360412', '3230121', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26791455', '你从未在此', '剧情', '乔（华金·菲尼克斯 Joaquin Phoenix 饰）有着非常悲惨的过去，他的父亲是一个暴力狂，总是无端对乔和他的母亲（朱迪思·罗伯茨 Judith Roberts 饰）施以拳脚。如今，乔和母亲过着相依为命的生活，有过参军经历的他在退伍之后成为了联邦调查局的探员，之后又开始干杀手的勾当，“经纪人”约翰（约翰·道曼 John Doman 饰）打理着涉及到乔工作的方方面面。某日，一位州参议员找到了乔，希望他能够去拯救他的女儿妮娜（叶卡特琳娜·萨姆索诺夫 Ekaterina Samsonov 饰）。刚开始，乔只把它当做是一个寻常的任务，但随着时间的推移，乔渐渐在其中发现了猫腻，并且开始怀疑起了州参议员的真正动机。©豆瓣', '华金·菲尼克斯', '琳恩·拉姆塞', 6.9, 14609, 'tt5742374', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2518558081.jpg', 2.4, 9.2, 41, 35.8, 11.6, '0.151791,-0.050847,-0.654284,0.846357,-0.272213,-0.288946,0.814427,0.020090,-0.623580,-0.571715,-0.222747,0.787733,-0.182023,0.765256,0.386160,-0.036613,-0.165275,-0.836898,0.042553,-0.215987,-0.567881,-0.689019,-0.140112,-0.467567,-0.030042,-0.034189,0.315357,0.308577,-0.224796,0.251983,0.332677,0.207172,0.202315,0.754784,-0.149317,0.241862,0.120720,-0.068045,-0.078651,-0.022016,0.529689,-0.126864,-0.089993,0.211692,0.280921,0.469606,0.530371,-0.337179,0.060222,0.021660,0.463905,-0.201784,0.288629,0.003032,0.477193,0.123894,-0.113450,-0.022090,-0.252303,0.174177,0.286129,-0.244233,-0.620576,0.016500,-0.107157,-0.005098,-0.810636,0.288589,-0.082116,0.240183,-0.059710,-0.380899,0.217739,0.609197,-0.014045,0.172370,-0.165466,0.005559,-0.627406,0.433411,0.694444,0.115579,-0.154654,0.336999,-0.264003,-0.734621,-0.309571,-0.405545,-0.276919,-0.280062,0.705351,-0.021511,-0.068737,0.087770,-0.332418,-0.312875,0.136013,-0.176155,0.019536,-0.294378,0.008554,-0.362172,-0.246092,-0.634227,-0.350185,0.130814,-0.334965,-0.626408,0.723952,-1.026865,0.045241,0.584499,-0.002709,-0.690874,0.561624,-0.012948,0.277679,0.003516,0.116426,0.475745,0.288919,0.180412,0.484177,0.462560,-0.015985,-0.010944,0.017723,0.533498', '1301022', '1303112', '7065238', '27042738');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26791627', '克莱尔的相机', '剧情', '影片故事讲述的是万熙（金敏喜饰）因性格耿直在咖啡馆遭到解雇，在海边遇见酷爱摄影的中学教师克莱尔（伊莎贝尔·于佩尔饰），在电影之城戛纳，完全陌生的两个人经历了相同的人事物。克莱尔相信摄影具有神秘力量甚至改变人生，而与克莱尔短暂的相处中万熙猜测到自己被解雇的原因。最后两个人一起朝着万熙被解雇的咖啡馆走去。', '伊莎贝尔·于佩尔', '洪常秀', 6.6, 9896, 'tt5989220', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2520122045.jpg', 1.8, 11.8, 49.3, 28.6, 8.5, '0.369964,0.001763,-0.685034,0.564698,0.049025,0.001592,0.925846,0.291499,-0.519550,-0.572909,0.238554,0.906451,-0.280358,0.276247,0.512685,-0.112814,-0.070142,-0.518307,-0.080990,0.056426,-0.292045,-0.476792,0.300190,-0.211373,0.107305,-0.487256,0.550503,0.013220,-0.548061,0.500659,0.186747,0.326278,-0.308575,0.418201,0.070544,0.211520,0.054006,-0.004468,-0.387806,0.087753,-0.005436,-0.132352,-0.128891,0.050865,-0.206775,0.198657,0.757510,0.011257,-0.483725,0.019331,0.473198,-0.211060,-0.081688,0.024376,0.289382,0.012930,0.175829,0.237038,-0.065908,-0.084620,0.189084,0.038114,-0.662388,0.320826,-0.002517,0.192868,-0.442046,0.481566,0.072728,-0.194635,0.028808,-0.232982,0.218012,0.120909,0.406444,0.300093,0.090744,0.049037,-0.410061,-0.016835,0.929039,-0.021627,-0.462242,0.630265,-0.381483,-0.239075,-0.358457,-0.164136,-0.450290,0.319997,0.294414,-0.025770,-0.248154,0.060477,-0.577912,-0.017323,0.150552,-0.148162,0.219180,-0.604712,-0.144035,-0.917411,-0.285730,-0.416244,-0.429349,-0.062039,-0.118858,-0.251897,0.669055,-0.702204,0.088790,0.661607,0.274299,-0.764396,0.888351,-0.138566,0.007681,-0.223451,0.094507,0.464860,0.262548,0.010383,0.097129,0.396492,-0.176186,0.063110,-0.655441,0.530118', '30162520', '3055049', '26687241', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26791910', '吃货宇宙', '喜剧', '这是一部上百位中外面食明星出演的好吃好玩的动画电影。面粉星球上，脑袋里包着一枚硬币的幸运饺子，却因为这个“幸运”而不开心，渴望变得和大家一样的她，接受了来自通吃星球的完美改造邀请，而憨厚暖男包子似乎预感到了什么，一路相随，一场阴谋正在等待着她（他）们......生死之间，为了朋友，包子会作何选择？毁灭之际，饺子又如何力挽狂澜？吃货宇宙见证自我和友谊的奇迹。除了饺子和包子，还有人格分裂的中年油条、偏执男大饼卷一切、互不服“硬”的法棍与五仁月饼、追逐梦想的方便面、快板不离身的麻花.....他们又将上演一出怎样有味道的喜剧呢？', '张鹤来', '陈廖宇', 5.7, 3165, 'Foodiverse', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2522682953.jpg', 7.3, 28.9, 41.8, 17.2, 4.7, '0.277726,0.015483,-0.474058,0.392516,0.000968,0.064852,0.708115,0.571605,-0.210205,0.344366,0.126247,0.642567,-0.386573,-0.045577,0.180231,0.032206,-0.097508,-0.594217,-0.149390,0.027726,-0.303210,-0.069984,-0.542065,-0.163820,0.000883,-0.013214,0.468287,0.113644,0.083445,0.124142,0.595010,-0.113292,-0.267836,0.354523,-0.200139,-0.049096,0.056427,0.213946,-0.409464,0.018314,0.107464,-0.059960,0.102123,0.460065,-0.201050,0.228200,0.534770,-0.431135,-0.170149,-0.104769,0.103069,-0.248487,-0.290470,0.197786,0.101221,0.127775,0.293259,-0.419789,0.239776,0.112540,0.225215,-0.238469,-0.700949,-0.269471,0.090074,0.315115,-0.282097,0.327776,0.001879,-0.048279,0.179403,-0.102174,0.170497,0.225190,0.547125,0.636841,-0.073508,0.141010,-0.489050,0.279984,0.856135,0.169646,-0.097257,0.288070,-0.303841,-0.317622,-0.052697,-0.286798,-0.572146,0.096586,0.288149,0.170081,-0.097602,0.189743,-0.910015,0.322182,0.041439,0.043832,0.395781,-0.418843,-0.303612,-0.316835,0.180352,-0.395853,-0.230264,-0.084291,0.477200,-0.228351,1.057305,-0.550473,0.162924,0.472942,0.075511,-0.209863,0.575385,0.130033,-0.232614,-0.400666,-0.094505,0.061092,-0.047125,-0.176732,0.216251,0.522075,-0.057145,0.229719,-0.387190,0.482702', '4181031', '24284209', '1302661', '26790961');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26792822', '我叫MT之山口山战记', '喜剧', '经验值一级的牛头人哀木涕（奶茶 配音）怀抱着勇斗一百级恶龙的英雄梦，却时时遭受被抓去“炖土豆”的威胁。他和同样初级的小伙伴傻馒（YOYO 配音）、劣人（CBI 配音）意外获得了一本名叫《山口山战记》的宝书，拯救世界的重任落在了他的肩上，斗恶龙从梦想变成了现实。虽然跌跌撞撞，哀木涕和小伙伴们还是勇敢踏上了成长之路。', '葛张君', '周彬', 5.1, 2880, 'tt6449912', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2359518939.jpg', 20.5, 29.3, 31.8, 10.2, 8.2, '0.066241,0.141468,-0.336711,0.569728,-0.246259,-0.287746,0.550707,0.330651,0.111807,0.244191,0.314478,0.840511,-0.108135,0.100474,0.076521,-0.085850,-0.007018,-0.498699,-0.191557,0.054105,-0.407603,0.079175,-0.344764,0.140873,-0.186722,-0.261215,0.802676,-0.122042,-0.316255,0.352775,0.524962,0.072494,-0.284635,0.434922,-0.386978,0.306767,0.272628,-0.131115,0.108516,0.136787,-0.280812,-0.238211,0.003296,0.113725,0.106614,-0.034863,0.890482,-0.413367,0.008484,-0.053899,0.281992,-0.425325,-0.113167,-0.141100,0.422637,0.042991,0.015823,-0.146894,0.420563,-0.030412,0.130579,-0.403005,-0.978714,-0.160978,-0.027387,0.035368,-0.795214,0.294920,-0.029141,0.174540,0.438563,-0.056679,-0.037405,-0.055628,0.169196,0.605151,-0.354751,0.016020,-0.286652,0.386358,0.372047,-0.211903,-0.058837,0.231110,0.147785,-0.598567,-0.185034,-0.209616,-0.311755,-0.287660,0.612304,0.017046,-0.432888,0.213968,-0.874273,0.221866,-0.155600,-0.372138,-0.030584,-0.401164,-0.378624,-0.092276,0.173276,-0.186534,-0.313926,0.095898,0.194966,-0.353484,1.020992,-0.538556,0.175959,0.726741,0.294450,-0.042340,0.718572,-0.012100,-0.013402,0.056826,0.306658,0.339201,0.027088,0.631639,0.603696,0.432460,-0.369338,0.111369,-0.604872,0.923815', '27602116', '1302661', '24733428', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26793385', '飓风奇劫', '动作', '影片讲述财务部女监察探员(格蕾斯饰)负责押运一批6亿美元残旧货币到碎钞厂处理，然而当地罕见的飓风灾难即将来临，一群全副武装的盗贼想在居民全部疏散后“乘风打劫”，而当飓风达到致命的5级之后，所有精心计划都被打乱，他们发现需要一个金库密码，而这个密码只有女监察探员知道，她和所被劫持人质的生命面临威胁，在和滞留当地气象学家（凯贝尔饰）结盟后，后者的弟弟也被盗贼绑架，两人不得不联袂面对飓风和匪徒，在历经惊险刺激后最终战胜了盗贼和飓风灾难。', '托比·凯贝尔', '罗伯·科恩', 5.8, 14460, 'tt5360952', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2537693782.jpg', 2.5, 24.2, 56.9, 14.1, 2.2, '0.157697,-0.137377,-0.651605,0.180986,0.010938,0.081368,0.850534,0.030875,-0.322470,-0.451281,0.442333,0.740340,-0.073584,-0.178943,0.436751,-0.367888,-0.252211,-0.710115,-0.385695,-0.376034,-0.578935,-0.375496,-0.102114,-0.113189,0.031197,-0.486526,0.559968,0.301828,-0.035946,0.387605,0.224213,0.582520,-0.285509,0.361661,-0.119315,-0.076127,0.317835,-0.214908,-0.384532,0.290582,-0.310996,-0.168315,-0.038558,0.092049,-0.076619,0.376751,0.762288,-0.321567,-0.076233,0.073342,0.129846,-0.667004,0.048516,0.163014,0.545013,0.146514,0.163387,-0.039085,-0.193128,-0.052606,0.079939,-0.125811,-1.018196,-0.019494,-0.026115,0.080582,-0.407871,0.214234,-0.061401,0.186478,0.004834,-0.159986,0.312839,0.540351,0.423168,0.328294,-0.258918,-0.051032,-0.583014,0.297023,0.769900,-0.272488,-0.314362,0.163505,-0.050316,-0.320747,-0.043225,-0.482872,-0.177189,0.072477,0.345997,0.268440,0.016728,0.018227,-0.831163,-0.110640,-0.432538,-0.378784,-0.216303,-0.440102,-0.368945,-0.759938,-0.112202,-0.244358,-0.274673,0.372742,0.414084,-0.032918,0.574061,-0.731885,0.098939,0.568558,0.443284,-0.646826,0.328142,-0.291785,0.151847,-0.049732,0.088456,-0.179035,0.623082,0.696261,0.124436,0.282105,-0.001420,-0.359998,-0.044704,0.074198', '2988294', '25774050', '26747274', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26793852', '信笺故事', '剧情', '詹妮弗（劳拉·邓恩 Laura Dern 饰）是一名纪录片制作人，她正在制作一档关于世界各地女性生活状况的纪录片。一天，詹妮弗意外的收到了母亲奈特（艾伦·波斯蒂恩 Ellen Burstyn 饰）的来电。奈特告诉詹妮弗，自己发现了她在13岁的时候写的日记，日记中记录了当时的詹妮弗和骑马教练G夫人（伊丽莎白·德比齐 Elizabeth Debicki 饰）以及跑步教练比尔（杰森·雷特 Jason Ritter 饰）在夏令营中一起度过的时光。詹妮弗幼稚的记录暴露了一些让奈特感到非常不安的消息，在奈特，以及未婚夫马丁（科曼 Common 饰）的鼓励之下，詹妮弗决定找到G夫人和比尔，询问当时到底发声了什么事情。哪知道这个举动打开了詹妮弗记忆力紧锁的潘多拉魔盒。©豆瓣', '劳拉·邓恩', '珍妮芬·福克斯', 8.2, 30190, 'tt4015500', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2511250973.jpg', 0.3, 1.1, 15.1, 55, 28.6, '0.289027,-0.247673,-0.338171,0.593745,0.046668,-0.264217,0.678384,-0.004701,-0.550980,-0.577639,0.011626,0.814628,-0.533999,0.332055,0.497222,0.143843,-0.636831,-0.576976,0.090029,-0.158475,-0.125753,-0.667205,-0.323861,-0.254340,0.196700,-0.516575,0.432142,-0.208112,-0.112203,0.505758,0.264310,0.284799,-0.002210,0.182622,0.179482,0.247775,0.371604,-0.130217,-0.040476,0.150779,0.302010,-0.079378,-0.069926,0.210539,0.345943,0.411368,0.426370,-0.272089,0.104318,0.335429,0.421548,-0.076997,0.256519,0.180211,0.146454,0.055487,0.099538,0.122393,-0.177511,0.004384,0.166092,0.200681,-0.449517,0.020960,0.148586,0.440745,-0.502789,0.166999,-0.430053,0.086770,0.193563,-0.368214,0.217374,0.396864,0.166802,0.258349,0.163617,-0.117814,-0.263515,0.070767,0.155039,-0.064028,0.123572,0.327344,-0.227389,-0.375573,-0.211411,0.219949,-0.666552,0.226736,0.204295,0.041799,0.021207,0.143028,-0.561058,-0.256877,-0.080042,-0.395611,-0.218916,-0.330986,-0.225079,-0.754659,-0.089949,-0.304753,-0.409166,-0.279248,0.044519,-0.235142,0.592169,-0.816627,0.258115,0.433480,0.008072,-0.108670,0.472887,0.222880,-0.019060,-0.144881,0.032643,0.136406,0.044043,0.018984,-0.196817,0.456696,0.166125,-0.596966,-0.446916,0.490141', '10763928', '3178770', '1793922', '27089612');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26794435', '哪吒之魔童降世', '剧情', '天地灵气孕育出一颗能量巨大的混元珠，元始天尊将混元珠提炼成灵珠和魔丸，灵珠投胎为人，助周伐纣时可堪大用；而魔丸则会诞出魔王，为祸人间。元始天尊启动了天劫咒语，3年后天雷将会降临，摧毁魔丸。太乙受命将灵珠托生于陈塘关李靖家的儿子哪吒身上。然而阴差阳错，灵珠和魔丸竟然被掉包。本应是灵珠英雄的哪吒却成了混世大魔王。调皮捣蛋顽劣不堪的哪吒却徒有一颗做英雄的心。然而面对众人对魔丸的误解和即将来临的天雷的降临，哪吒是否命中注定会立地成魔？他将何去何从？', '吕艳婷', '饺子', 8.4, 1738528, 'tt10627720', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2563780504.jpg', 0.8, 2.2, 15.5, 39.1, 42.4, '-0.160203,0.458621,-0.359785,0.635893,-0.144384,0.079055,0.323576,0.189804,-0.487476,0.099686,-0.008797,0.528490,-0.324846,-0.157517,0.037698,0.271040,0.599183,-0.379688,-0.055479,0.257178,-0.180095,0.144068,-0.404056,0.158969,-0.165508,-0.829888,0.701212,0.360444,0.472076,-0.442376,0.226701,0.524672,-0.060434,0.260048,-0.021800,0.140568,-0.640699,0.256771,0.273200,0.642368,-0.212879,-0.382232,0.285476,0.381277,-0.242398,-0.052980,0.407511,-0.608334,0.010545,-0.812388,0.437663,-0.229590,-0.249343,0.352595,0.135790,0.331456,0.290797,0.075454,-0.250987,-0.026393,0.159831,-0.128513,-1.010199,-0.243168,-0.127071,-0.255496,-0.036171,0.327203,0.197909,0.345922,-0.030166,-0.224804,0.357309,0.422099,0.310107,0.331639,-0.620647,-0.763518,-0.274256,-0.180492,0.652843,-0.507723,0.044864,0.368301,0.220146,-0.291506,-0.281004,-0.337534,-0.041046,0.027799,0.371475,0.488469,0.193413,0.783805,-0.501565,-0.330277,-0.567043,0.364481,0.004981,-0.061245,-0.210556,0.244047,0.066600,0.023340,-0.254245,-0.097130,0.482051,-0.034384,1.084386,-0.715848,0.401684,0.267237,0.190559,-0.259263,0.689344,-0.480045,-0.037135,-0.707001,0.088908,0.204905,0.130774,0.696792,0.283855,0.141759,0.085545,0.284119,-0.136088,0.035155', '27602116', '24284209', '3001114', '2051813');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26794701', '孟买酒店', '剧情', '影片真实再现震惊世界的“印度9·11”孟买恐袭事件，2008年11月，著名的泰姬陵酒店意外遭到恐怖分子入侵，恐怖分子无差别行凶，让整个酒店陷入绝望之境，百余名酒店住客及员工被困，无人得知何时能等来救援，一场与死神的赛跑就此开启…', '艾米·汉莫', '安东尼·马拉斯', 8.4, 187392, 'tt5461944', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2545020183.jpg', 0.2, 0.9, 12.9, 51.2, 34.8, '-0.021070,0.307210,-0.690307,0.029273,0.461528,0.217606,0.687694,-0.379875,-0.552882,-0.472204,0.365554,0.619466,-0.709956,-0.082277,0.488997,-0.240778,-0.137237,-0.519836,-0.233375,-0.447010,-0.079911,-0.097210,-0.139543,-0.346930,0.323904,-0.357614,0.552729,0.733165,-0.235091,0.527114,-0.070798,0.631785,-0.571031,0.547364,0.216346,-0.161287,0.373740,-0.233092,-0.692664,0.338339,-0.522143,-0.119479,-0.029562,0.081622,-0.299092,-0.109471,0.792674,-0.156521,-0.391782,-0.138623,0.683467,-0.375034,-0.481106,0.169269,0.776448,-0.223116,-0.004479,0.199060,-0.051078,-0.101001,0.040373,-0.037463,-0.629862,0.074508,0.157733,-0.221331,0.084268,0.104420,-0.279432,0.339641,0.229706,0.179744,0.313813,0.523536,0.786357,0.650008,0.292564,0.115721,-0.477220,-0.070159,1.047473,-0.493189,-0.283009,-0.242586,0.356921,-0.542824,-0.135866,-0.449812,-0.177540,0.368236,0.082286,-0.069638,-0.292646,0.324968,-0.314273,-0.290049,-0.535948,-0.680695,-0.062870,0.116111,-0.415579,-1.303186,-0.038348,0.421040,-0.082727,0.021403,0.205681,0.330874,0.102200,-0.522782,0.638974,0.513618,0.476489,-0.364165,0.809798,-0.290655,0.032608,-0.131391,-0.198739,0.555403,0.345877,0.707121,-0.080735,-0.100438,-0.658403,0.326836,-0.265883,-0.244489', '10466639', '3871833', '24751811', '26718836');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26796664', '叶问外传：张天志', '剧情', '作为《叶问》系列影片，电影《叶问外传：张天志》延续了《叶问3》的故事，讲述了同为咏春传人的张天志在比武惜败叶问后，决意放下功夫、远离江湖纷争，但面对接踵而至的连番挑衅，面对家国大义遭受的恶意侵犯，决定重拾咏春惩戒毒贩、“以武之道”捍卫民族道义尊严的故事。', '张晋', '袁和平', 5.5, 51982, 'tt7262882', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2542380253.jpg', 5.2, 30, 50.4, 11.9, 2.5, '-0.119227,0.248757,0.105161,0.464780,0.409811,-0.117573,-0.176520,0.271071,-0.264037,-0.450601,0.784649,0.509016,0.234375,-0.369503,0.229500,-0.644792,-0.019558,-0.575360,0.093367,0.112107,0.275067,-0.394438,0.108690,0.018508,-0.399470,-0.080178,0.661477,0.023304,-1.199209,0.257397,0.466048,0.196513,0.005579,0.225583,0.170159,-0.096960,-0.500092,0.236934,-0.905038,0.012833,0.041917,-0.450284,-0.371827,0.195992,-0.294914,0.536148,0.244044,-0.086897,-0.028260,-0.461219,0.646074,-0.395940,-0.405523,0.239224,0.031287,0.419309,0.067805,0.728681,0.558943,0.038748,0.108576,-0.122491,-0.670159,-0.318113,0.449281,0.040488,-0.303181,0.598933,-0.158093,-0.024645,0.132112,0.200543,0.016357,0.014992,0.880234,0.224917,0.215957,0.009479,-0.124064,0.146322,0.398283,-0.449889,0.032179,0.014703,0.209584,-0.100668,0.321322,-0.640357,-0.130230,-0.312135,0.070502,-0.296086,-0.102867,0.714212,-0.448846,-0.024505,0.222045,-0.127318,0.243625,-0.520215,0.291812,-0.506387,-0.272874,-0.245386,0.058833,-0.099974,0.239379,-0.403200,1.213920,-0.473362,0.148590,0.246894,0.262445,-0.514070,0.445426,0.423482,-0.007242,-0.114438,0.010568,0.861140,0.104132,0.228907,-0.386513,-0.288558,0.069699,0.035664,-0.123498,0.294430', '27602116', '30465281', '26790961', '5996800');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26796665', '九龙不败', '剧情', '警探九龙(张晋 饰) ，查案方式奇异狠辣却屡建奇功，是叱咤香港警界的精英干探, 但他处事独断爆裂，又被警队视为“偏执狂人”。九龙奉命调查一桩妙龄女警连环被凶杀案，用尽手段后不仅毫无线索, 他的警花未婚妻方宁（邓丽欣 饰）竟然也在这场抓捕行动中意外失踪。在爱与痛的边缘挣扎的九龙，突然发现女警连环遇害只是第一步，凶手还有着更加血腥的阴谋，自己和未婚妻竟然也被算计其中。此时澳门再度发生女警被杀案，这次的作案手法更加令人发指，但凶手好像故意留下了线索，是危险陷阱还是复仇曙光？九龙义无反顾出发，在好友王梦奇（刘心悠 饰）及国际拳王冼力山（Anderson The Spider Silva 饰）的协助下, 与澳门警司曹志德（郑嘉颖 饰）联手展开调查。魔高一丈，道高几何！血债血偿之前，就算流干最后一滴血，也要誓不罢休。', '张晋', '陈果', 3, 9667, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2560169035.jpg', 61.7, 28, 8.7, 0.9, 0.6, '-0.202891,-0.095196,-0.622392,0.445083,0.112237,-0.054193,0.535415,-0.122397,-0.621791,-0.167586,0.530353,0.538311,-0.145234,-0.363723,0.099024,-0.160439,-0.205301,-0.853405,0.037263,-0.084622,-0.254870,-0.370513,-0.434750,0.151969,0.056791,-0.076088,0.309375,0.519577,-0.202710,0.435206,0.543492,0.360478,-0.409333,0.519299,-0.089236,-0.258849,0.228321,-0.088854,-0.134215,0.079765,0.268258,-0.564374,-0.101569,0.385851,-0.154327,0.691101,0.274119,-0.146354,-0.094620,-0.129255,0.212436,-0.449839,-0.038408,0.196729,0.414957,-0.035083,0.327769,0.433283,-0.130731,-0.115101,0.232708,-0.060895,-0.900934,0.033698,0.250381,0.012088,-0.373642,0.028443,-0.324511,0.201790,0.065676,-0.291069,0.168278,0.151602,0.513910,-0.111194,-0.240497,-0.102168,-0.501576,0.043760,0.592137,-0.025703,-0.007499,0.111953,0.095779,-0.403799,-0.165048,-0.390393,0.226184,0.138936,0.472656,0.152775,-0.075567,0.221600,-0.455196,-0.181434,-0.366226,0.295728,-0.440801,-0.059707,-0.118621,-0.472523,-0.283974,-0.155120,-0.271215,0.061301,0.079117,-0.136254,0.181029,-0.652647,0.217434,0.488229,0.226238,-0.477433,0.318001,0.193608,-0.247057,-0.268658,-0.293232,0.038657,0.260423,0.347119,0.135412,0.252585,-0.077453,-0.368850,-0.244395,0.159003', '1307442', '26747274', '3811342', '26352445');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26796845', '莫斯科陷落', '科幻', '难得一见的流星雨即将在俄罗斯上空出现，青年男女们兴奋非常，纷纷走上街头见证着历史性的一刻。美丽女孩尤利娅（伊琳娜·斯达森保姆 Irina Starshenbaum 饰）不顾身为军官的父亲的反对，执意和特姆（亚历山大·佩特罗夫 Alexander Petrov 饰）交往。在流星雨来的这天，他们躲在一隅偷欢，却不知莫大的危机正在袭来。一艘外星飞船遭到意外，结果又被俄罗斯空军击中。它在迫降的过程中给莫斯科造成毁灭性的打击，而尤利娅的闺蜜也在灾难中丧生。在此之后，尤利娅和朋友们闯入禁区，遭遇了外星人。阴差阳错，她决定救治受重伤的外星飞行员汉克（林奈·穆罕默托夫 Rinal Mukhametov 饰），而特姆等憎恶外星人带来的灾难，对汉克恨之入骨。跨越时空的爱情在此过程中产生……©豆瓣', '伊琳娜·斯达申鲍姆', '费奥多尔·邦达尔丘克', 4.8, 16579, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2412059661.jpg', 14.9, 42.1, 34.2, 6.7, 2.1, '0.145845,-0.103774,-0.883395,0.372256,-0.000842,0.105770,0.970134,-0.029082,-0.410364,-0.072286,0.506860,0.719969,-0.289678,0.080686,0.558417,-0.118260,-0.387716,-0.464840,-0.154204,-0.029566,-0.427687,-0.322696,-0.336597,-0.134760,-0.020742,-0.463692,0.499423,0.060054,-0.375709,0.604459,0.311576,0.748185,-0.231375,0.706866,-0.226435,0.101134,0.168201,0.047097,-0.279833,0.279309,-0.261343,-0.363396,-0.079891,0.425119,-0.291598,0.078242,0.769921,-0.515589,0.029061,-0.277955,0.359781,-0.423650,0.195204,0.151422,0.479911,0.067750,-0.074953,-0.202155,-0.036733,-0.018447,0.337375,-0.037996,-0.320464,0.151085,-0.080620,0.174174,-0.563636,0.480603,0.085685,0.057568,0.110303,-0.222913,0.188696,0.326251,0.224341,0.385474,-0.381237,0.037777,-0.466705,-0.037741,0.766765,-0.117801,-0.315039,0.045701,-0.332472,-0.334358,0.043923,-0.251477,-0.543486,-0.062648,0.443329,-0.013300,-0.153352,0.595345,-0.593436,0.191908,-0.520118,-0.398105,-0.329483,-0.268466,-0.311455,-0.909436,-0.026056,-0.245561,-0.485272,0.403942,0.036667,-0.061845,0.659948,-0.640409,0.370858,0.589083,0.246514,-0.220153,0.621654,0.201603,0.084302,-0.171126,-0.215280,0.407835,0.136208,0.159922,-0.133923,0.164038,-0.007442,0.164448,-0.106402,0.301847', '3011051', '2269893', '10466639', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26797419', '二代妖精之今生有幸', '喜剧', '身负巨债的动物饲养员袁帅（冯绍峰 饰），为了还清百万巨债，他四处与富家女相亲，却误打误撞爱上来人间报恩的狐妖白纤楚（刘亦菲 饰）。妖怪管理局局长云中鹤为阻止人妖相恋，派魔都小分队洪思聪队长捉拿违规狐妖白纤楚，袁帅为了寻回爱人狐妖，勇闯妖界……', '冯绍峰', '肖洋', 5.4, 144593, 'tt7787418', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2507022339.jpg', 11.4, 28.4, 41.3, 14.1, 4.8, '-0.340927,0.310892,0.015822,0.392891,0.038074,-0.159686,0.350380,-0.419034,-0.162930,-0.251720,0.033319,0.041337,0.425336,-0.063631,0.118720,0.039393,0.637669,-0.136864,0.128686,0.215623,0.185243,0.524811,-0.427615,0.014929,-0.630771,-0.099519,0.671671,0.063804,0.205830,0.433749,0.702377,0.338066,-0.849162,-0.150235,0.181797,0.044252,-0.096778,0.153420,-0.304711,0.285869,-0.405991,0.229638,0.226788,0.263040,-0.322324,0.235634,0.623940,-0.586982,-0.037813,-0.521388,-0.064171,-0.445431,-0.157062,0.070528,0.557343,-0.289375,0.643661,0.184608,0.167021,-0.219184,0.017089,0.211605,-0.341725,-0.250537,0.276216,0.261118,-0.233172,-0.100252,-0.159187,0.864238,0.412846,0.143189,-0.358657,0.204404,0.340231,0.183092,0.193240,-0.065840,-0.191174,0.322480,0.766564,-0.286302,0.533865,-0.078646,0.080998,-0.831453,0.330486,-0.150193,0.115676,0.157693,-0.186648,-0.536197,-0.008393,0.484549,-0.980186,-0.297263,-0.257267,0.826507,-0.314213,-0.348024,0.259673,-0.013866,0.147337,0.040499,0.151415,0.091715,0.336620,-0.329433,-0.034600,-0.730512,0.142715,0.638479,0.262133,-0.852563,0.613729,-0.246625,0.123086,-0.646877,-0.174342,0.112332,0.749356,0.482908,0.133001,-0.415735,0.103891,-0.122612,-0.155788,-0.334265', '19944106', '7056398', '3041614', '22939161');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26798032', '大骚乱', '动作', '剧本由马蒂亚斯·卡鲁索创作，故事讲述一种病毒感染了一个公司的法务部，而在同一天律师德里克·桑德斯被同事陷害并且被不公平地开除。这种感染会使人们表现出最原始和野性的冲动。被困在被隔离的大楼里，我们的英雄主人公只能竭尽全力通过野蛮地拼斗，夺回属于自己的工作和人生。', '史蒂文·元', '乔·林奇', 6.5, 10949, 'tt4348012', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2504652246.jpg', 2.2, 11.9, 51.5, 26.3, 8.2, '0.467097,-0.226734,-0.489514,0.711058,-0.381393,-0.190132,0.843812,0.150240,-0.498692,-0.218796,0.305007,0.887129,-0.221215,0.387642,0.503435,-0.301177,-0.124814,-0.736546,-0.242013,-0.006770,-0.188063,-0.446777,-0.013823,-0.307901,-0.047304,-0.388952,0.837066,0.045921,-0.562659,0.058428,0.056792,0.635816,-0.059418,0.262019,0.123675,-0.113803,0.060930,-0.372561,-0.141663,0.335426,0.142404,-0.139666,0.085311,0.278459,-0.162349,0.258215,0.787817,-0.422789,-0.094227,-0.017826,0.708726,-0.462707,0.097100,0.274532,0.287845,0.064117,0.214668,0.401648,-0.484955,-0.031186,-0.026298,-0.052573,-1.066263,-0.239884,-0.130419,0.084372,-0.595169,0.340269,0.141478,0.247121,0.271643,-0.050385,0.164526,0.189404,0.419635,0.628764,-0.012373,-0.001329,-0.472543,0.029211,0.654074,-0.409949,-0.314394,0.242232,-0.344640,-0.253596,-0.174021,-0.369402,-0.670304,-0.112590,0.336266,-0.071906,-0.215570,0.364403,-0.788472,-0.211879,-0.214228,-0.126772,-0.097913,-0.603962,-0.149408,-0.726392,-0.243873,0.121605,0.081778,-0.139396,0.156533,-0.082558,0.743544,-0.945874,0.024351,0.724190,0.203796,-0.450500,0.475241,0.310091,0.165104,-0.097657,0.010083,0.206530,0.395744,0.557649,0.148289,0.591191,0.200131,-0.129991,-0.676838,0.461761', '1793491', '25928048', '1308585', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26798437', '深夜食堂2', '剧情', '小小的深夜食堂，迎来送往这个喧嚣都市内奔波疲惫的人们。他们漫无目的，或者迷失方向，却往往不经意间在这个蕞尔角落找到前行的希望。每当在工作中遇到烦心事，赤冢范子（河井青叶 饰）便穿着丧服在大街上游荡。偶然机缘，她在葬礼上结识了一名男子（佐藤浩市 饰），干涸的心田便为爱情所滋润。经营荞麦面生意的高木圣子（木村绿 饰）与儿子清太（池松壮亮 饰）相依为命，清太和年龄长于自己的木村纱织（小岛圣 饰）相恋，而一直与圣子好姐妹相称的圣子却全不知情。年逾古稀的老太太夕起子（渡边美佐子 饰）被诈骗电话骗到了东京，食堂的热心人们担心她的钱被人骗走，老奶奶则不以为意。这趟前来，她仿佛有个未了的心愿。本片根据同名漫画改编，为同名深夜剧的第二部电影版。©豆瓣', '小林薰', '松冈锭司', 8, 49129, 'tt5741902', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2494842674.jpg', 0, 1.6, 20.6, 52.7, 25, '0.146587,0.181761,-0.530257,0.321652,0.124749,-0.311047,0.600849,0.273273,-0.278191,-0.493447,0.366289,0.619796,-0.077632,0.232777,0.324325,0.086683,-0.327986,-0.591174,0.093082,-0.220044,-0.013166,-0.081529,-0.203658,-0.084874,-0.375045,-0.132024,0.536565,0.390693,-0.039298,0.540538,0.226268,0.149811,-0.364692,0.255954,-0.190575,0.174231,-0.025876,0.217301,-0.055620,-0.199263,-0.383088,-0.285466,-0.270576,-0.070965,0.156400,0.470899,0.688641,-0.190916,-0.121964,-0.059549,0.226168,-0.116929,0.097970,0.102591,0.391204,0.055481,0.274219,0.094755,-0.298614,-0.023466,-0.113873,-0.050768,-0.434831,0.062829,0.151370,0.342082,-0.386178,0.541288,-0.029788,-0.193157,-0.001394,-0.166301,0.124094,0.030059,0.099356,0.202393,-0.194052,0.090582,-0.362118,0.394051,0.474189,0.132378,0.120105,0.421023,-0.217257,-0.269421,-0.056977,-0.129001,-0.341387,-0.127411,0.177423,-0.196496,-0.006151,0.194886,-0.419961,0.060883,-0.023570,0.061679,0.008194,-0.116754,-0.197096,-0.690083,0.141784,-0.352849,-0.268219,0.165463,0.180814,-0.126106,0.628051,-0.498510,0.177910,0.532497,0.151204,-0.291062,0.707712,-0.016442,0.137024,-0.242977,-0.423946,0.259166,0.008336,0.309447,0.177740,0.324459,-0.292027,0.129123,-0.498517,0.209155', '3811356', '10466639', '1418179', '26926321');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26799731', '请以你的名字呼唤我', '剧情', '故事发生在八十年代的意大利里维埃拉，每年夏天，十七岁的少年艾力奥（提莫西·查拉梅 Timothée Chalamet 饰）都会跟家人一起来此地度假。今年，和他们共享假日时光的，还有来自美国的奥利弗（艾米·汉莫 Armie Hammer 饰），高大英俊热情开朗的奥利弗很快就获得了艾力奥一家人的喜爱。随着时间的推移，艾力奥和奥利弗之间渐渐产生了致命的吸引力，但性别和年龄的桎梏让他们迟迟无法跨出那关键的一步，与此同时，单纯善良的少女马奇娅（艾斯特·加莱尔 Esther Garrel 饰）也向艾力奥奉献着自己的感情和身体。最终，汹涌的激情冲破了艾力奥和奥利弗之间的防线，两人开始了一段注定不会有结果的恋情。©豆瓣', '艾米·汉莫', '卢卡·瓜达尼诺', 8.9, 667675, 'tt5726616', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2505525050.jpg', 0.4, 1, 9.3, 33.1, 56.1, '0.574409,0.025017,-0.957093,0.634687,0.136731,-0.533153,0.903529,0.250622,-0.049692,-0.138295,-0.157345,0.667767,-0.445601,0.245963,0.432908,-0.063387,-0.426241,-0.619324,0.032999,-0.363017,-0.206903,-0.616219,-0.170624,-0.118128,-0.089490,-0.411383,0.353285,0.008029,-0.198531,0.615613,0.291063,0.284129,0.222964,0.477916,0.055051,0.048961,0.380549,-0.264678,-0.219520,0.200086,0.365426,0.024633,-0.010600,0.392678,0.076541,0.445682,0.748434,-0.414300,0.055536,0.175027,0.389520,0.016994,0.186061,-0.044667,0.300748,-0.077050,0.019813,0.272288,-0.082647,-0.087510,0.236292,-0.373502,-0.458614,0.115662,0.212208,0.090911,-0.483315,0.492822,0.110022,-0.094124,0.246822,-0.345898,0.077362,0.616576,0.350910,0.261494,-0.067961,-0.025234,-0.526084,-0.047334,0.854480,0.088776,-0.527350,0.408046,-0.675416,-0.538824,-0.389625,-0.063726,-0.512799,-0.309823,0.484336,0.167236,0.040458,0.698736,-0.614336,0.160166,-0.108512,-0.076106,-0.068004,-0.319417,0.168028,-0.404020,-0.371600,-0.727327,-0.217221,0.275553,-0.209056,-0.034896,0.886912,-0.599433,0.429647,0.664948,0.637487,-0.035369,0.784036,0.098625,0.120274,-0.071345,0.013471,0.345158,-0.099765,0.053079,0.363489,0.478142,0.108008,0.036671,-0.238815,0.784715', '34461680', '30162520', '1309161', '1292338');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26800978', '南汉山城', '剧情', '《南汉山城》根据2007年出版的韩国同名畅销历史小说改编拍摄。以1636年仁祖14年的丙子胡乱为背景，讲述后金（清）攻打朝鲜，仁宗国王（朴海日饰）和他的大臣，包括崔鸣吉（李秉宪饰）和金尚宪（金允石饰）被逼至南汉山城，在紧迫的47日里，他们与外界隔绝，进退维谷。在强大的清军攻势下，崔鸣吉为了百姓的身家性命力主求和；金尚宪主张与后金（清）继续战斗。', '李秉宪', '黄东赫', 7.9, 27478, 'tt7160176', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505021598.jpg', 0.5, 2, 22.7, 51.1, 23.6, '0.179958,0.065459,-0.422635,0.826768,0.742662,0.003956,0.122496,0.326542,-0.522914,-0.385921,-0.023138,0.218005,-0.189280,-0.255543,0.327346,-0.304955,-0.287777,-0.873496,-0.244995,0.010309,0.044901,-0.546987,-0.076765,-0.307403,-0.523312,-0.380154,0.847521,0.216678,-0.264400,0.508059,0.119301,0.207412,-0.050960,0.381865,0.326054,0.161910,-0.420832,-0.347975,-0.578657,0.058803,-0.228921,-0.501887,-0.409295,0.084625,0.241632,0.245854,0.579302,-0.723238,0.309981,0.032140,0.429420,-0.146822,-0.295576,0.218995,0.364520,0.215838,0.013649,0.552467,-0.244160,0.052183,-0.413390,0.066623,-0.833446,-0.426245,0.084104,-0.040871,-0.340220,0.662902,-0.049368,0.069325,0.113127,-0.589134,0.035034,0.729180,0.053379,0.489613,-0.107836,-0.128096,-0.240156,0.493025,0.596826,0.034322,-0.209397,-0.191010,-0.057458,-0.240060,-0.150022,-0.235350,-0.343180,0.095205,0.300196,-0.268270,0.149973,0.292781,-0.351145,-0.298060,-0.146418,-0.263478,0.395629,0.007809,-0.044530,-0.483832,-0.311440,-0.679138,-0.128815,0.014065,0.318540,0.010894,0.670089,-0.643979,-0.109573,0.759181,0.665183,-0.492714,0.331982,0.339007,-0.050964,0.048472,-0.465795,-0.028210,0.194046,0.509756,0.272759,0.013709,-0.170047,-0.329129,-0.409270,0.077130', '25917239', '6101834', '26809007', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26801782', '缉枪', '剧情', '一次普通的车辆剐蹭事故里，俞苗老公刘明义拿枪打死了徐天的女朋友，被警察当场击毙。徐天找俞苗赔钱，二人去找卖枪给刘明义的枪贩子马三叹，却遇上了马三叹被警察连广阔抄了老窝。马三叹跳桥重伤，俞苗和徐天被马三叹的弟弟小马绑架，小马用徐天的生命要挟俞苗，要她去医院杀马三叹灭口。俞苗到医院，在连广阔的帮助下蒙混过关，警方根据俞苗的线索追查小马下落，警方设卡在山路围捕抢匪，双方展开了最后的较量。', '白举纲', '徐兵', 6.2, 6872, 'tt6096894', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2461747793.jpg', 7.6, 18.9, 39.2, 26.5, 7.9, '0.170233,-0.215085,-0.412571,0.218613,-0.487468,-0.327937,0.483471,-0.080965,-0.341113,0.342539,0.224405,0.379831,0.200197,-0.122379,0.142486,-0.110945,-0.227762,-0.583388,0.204641,0.286139,-0.522411,-0.413982,-0.446322,-0.174920,0.133107,0.249814,0.107666,-0.008837,-0.335872,0.447339,0.190173,0.163563,-0.345030,0.471779,-0.407811,0.133711,-0.031663,-0.556078,0.002878,0.465409,0.054024,-0.406652,0.110783,0.009617,-0.020006,0.775446,0.679688,0.248389,-0.184962,0.017891,0.340411,-0.461667,0.022820,0.024903,0.402092,0.038113,-0.015161,-0.042722,-0.181597,-0.131290,0.403683,0.255638,-0.497513,-0.045568,0.004961,-0.177275,-1.011944,0.282832,-0.262019,0.284580,0.059981,-0.288618,0.615617,0.198383,-0.047927,0.115754,-0.040213,-0.308605,-0.797605,0.133231,0.458123,-0.447416,0.530944,-0.399968,0.123808,-0.215782,0.152553,-0.206468,-0.048176,0.093744,1.009154,-0.357949,-0.571106,-0.321111,-0.247326,-0.355465,-0.331718,-0.137353,-0.262964,-0.397868,-0.230210,-0.528956,0.404450,0.002386,-0.365321,0.092255,0.131363,0.020563,0.077094,-0.082112,-0.123240,0.712042,0.301153,-0.398176,0.567208,-0.207463,-0.039382,0.179970,0.064884,-0.362950,0.684663,0.950558,0.786912,0.140009,0.268346,-0.120473,-0.280253,0.195173', '1754628', '1303462', '1293908', '1432825');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26803711', '阿唐奇遇', '动画', '在南方一座热闹城市里的一间茶叶店中，生活着一群陶瓷茶宠。他们以被浇茶变色为荣。而阿唐是其中唯一一个怎么浇茶都不会变色的茶宠。有一天，一个来自未来的神奇机器人小来，意外飞进了茶叶店，为阿唐带来一丝希望。为了找到让自己颜色变漂亮的方法，中华小茶宠阿唐决定为美大步走，与机器人小来一起出发，踏上一段寻找未来的历险旅程。', '石磊', '王微', 7, 9673, 'tt6903084', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2482761924.jpg', 1.3, 8, 41.5, 35.9, 13.4, '0.043318,0.075817,-0.404238,0.801374,-0.241960,-0.094595,0.666640,0.029701,-0.296514,-0.346617,0.018751,1.013249,-0.074487,0.029094,0.152397,0.237199,0.056619,-0.366725,-0.201560,-0.216694,-0.391260,-0.143521,-0.309838,-0.258711,-0.020721,-0.087592,0.324648,0.230114,-0.023858,0.539008,0.032116,-0.185636,-0.326183,0.310903,-0.175979,-0.248293,0.023973,0.047199,-0.250562,0.321060,-0.176286,-0.129344,-0.072180,0.173057,-0.218768,0.032529,0.667928,-0.140148,-0.181474,-0.273137,0.075900,-0.198852,-0.137626,-0.090938,0.135555,0.083826,-0.060931,-0.030678,-0.429974,0.207063,0.204095,-0.252806,-0.786012,-0.042148,0.202070,-0.039200,-0.537411,0.371536,0.155647,-0.356667,0.311718,-0.403853,0.380144,0.142132,0.668866,0.680741,-0.060942,0.515270,-0.497723,-0.305492,0.938312,-0.281948,0.075765,0.310718,-0.146508,0.003632,0.327665,0.066711,-0.397551,-0.094483,-0.049040,0.172081,0.125798,-0.001666,-0.785547,0.549196,-0.179564,-0.327539,0.146971,-0.167502,-0.187537,-0.383034,0.206838,-0.230514,-0.114182,0.222417,0.044120,-0.371861,0.696896,-0.306147,0.326366,0.159296,0.207983,-0.642927,0.947893,0.121938,0.238019,-0.435734,0.131415,0.022777,-0.049429,0.127522,-0.045067,0.333502,-0.230142,-0.035790,-0.440245,0.385665', '30162520', '26678784', '3055049', '1456503');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26804147', '摩天营救', '动作', '在香港市中心，世界上最高、结构最复杂的摩天大楼遭到破坏，危机一触即发。威尔·索耶（道恩·强森 饰）的妻子萨拉（内芙·坎贝尔 饰）和孩子们在98层被劫为人质，直接暴露在火线上。威尔，这位战争英雄、前联邦调查局救援队员，作为大楼的安保顾问，却被诬陷纵火和谋杀。他必须奋力营救家人，为自己洗脱罪名，关乎生死存亡的高空任务就此展开。', '道恩·强森', '罗森·马歇尔·瑟伯', 6.3, 163071, 'tt5758778', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2527484082.jpg', 1.7, 12.7, 60, 21.3, 4.2, '0.185746,0.117009,-0.665517,0.322776,0.159783,0.054685,0.782430,0.271821,-0.298994,0.043162,0.833771,0.824330,0.155088,-0.279808,0.504058,0.121855,-0.516947,-0.744727,-0.118546,-0.098634,-0.575590,-0.816419,-0.224019,-0.054820,-0.237759,-0.152106,0.664366,0.163129,-0.312087,0.191887,0.303505,0.585511,-0.209347,0.429387,0.182667,-0.383714,0.233911,-0.379404,-0.372586,0.133401,-0.383163,-0.377059,0.068303,0.304461,-0.010108,0.284576,0.511493,-0.384066,0.230886,-0.440903,0.175112,-0.442736,0.240812,0.071239,0.275380,-0.210099,0.198249,0.413343,-0.247443,-0.275123,0.144418,-0.185075,-0.817734,-0.082421,0.169922,-0.044956,-0.659845,0.372301,-0.308165,-0.011645,0.358182,-0.218762,0.039073,0.605258,-0.013138,0.047462,-0.536300,0.033621,-0.491708,-0.188597,0.313421,0.040970,-0.001913,-0.377561,0.208138,-0.129515,-0.034703,-0.359465,-0.271586,-0.216095,0.277481,-0.069204,-0.012873,0.482741,-0.558756,-0.127352,-0.449693,-0.338305,-0.180526,-0.368483,-0.106676,-0.734147,0.080420,0.117287,-0.540329,0.021533,0.056566,-0.114329,0.348833,-0.784490,0.357013,0.623000,0.341477,-0.540859,0.465527,0.255438,0.646710,-0.328657,-0.467023,0.116974,0.145467,0.659854,0.123391,0.200326,-0.025075,-0.228704,-0.201765,0.386789', '1307442', '6790253', '1986338', '2367213');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26804584', '这个男人来自地球：全新纪', '科幻', '凡妮莎·威廉斯加盟《这个男人来自地球：全新纪》(The Man From Earth: Holocene，暂译)。该片是2007年科幻片《这个男人来自地球》的续集。首部主演大卫·李·史密斯、威廉姆·卡特回归。首部中，看似平常的历史系教授约翰实际是史前石器时代的穴居人！首部导演理查德·沙因克曼回归执导续集。', '大卫·李·史密斯', '理查德·沙因克曼', 4.9, 11499, 'tt5770864', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2511020287.jpg', 18.9, 34.8, 33.2, 8.4, 4.6, '0.171192,0.002382,-0.590199,0.432868,-0.112436,-0.108518,0.626059,-0.319328,-0.505812,-0.737079,0.187985,0.840210,-0.360523,0.180675,0.426003,0.444081,-0.570812,-0.149087,-0.316480,-0.027378,-0.081622,-0.242195,-0.476833,-0.241748,-0.277175,-0.043458,0.796480,-0.026744,-0.344048,0.216850,0.412378,0.544431,0.280690,0.299643,0.239235,0.668127,0.075682,-0.428202,-0.228495,0.503651,0.282739,0.308435,-0.102141,0.135170,0.080776,0.337584,0.257232,-0.279165,0.441548,-0.013294,0.746681,-0.144262,-0.463001,-0.276149,0.314045,-0.083591,-0.022139,-0.032787,0.287346,0.100173,-0.350542,-0.494639,-0.426520,-0.072651,0.034017,0.432592,-0.280756,-0.199651,-0.282662,0.249255,-0.160551,-0.199490,0.129025,-0.141383,0.851340,0.394793,0.439005,0.243771,-0.012135,0.643871,0.430368,0.467053,-0.502594,-0.055221,-0.607743,-0.653591,-0.603483,0.054926,-0.953669,0.186670,0.152553,-0.480814,0.338453,0.568815,-0.666264,-0.018033,-0.178091,-0.051217,-0.145807,-0.040373,0.035252,-0.962417,0.017302,-0.269766,0.432134,-0.547810,0.013029,-0.612128,0.941529,-0.650691,0.140356,0.121242,0.465886,0.264593,0.732808,-0.155820,0.021879,-0.700304,0.098581,1.050870,0.104782,-0.115961,-0.380630,0.177736,0.352804,-0.575765,-0.114207,0.725531', '1322847', '26611806', '30397916', '27002812');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26806528', '一呼一吸', '剧情', '阳光开朗，热爱冒险的罗宾（安德鲁·加菲尔德 Andrew Garfield 饰）邂逅了温柔美丽的戴安娜（克莱尔·福伊 Claire Foy 饰），两人坠入了情网并且很快便决定携手步入婚姻的殿堂。可是，在罗宾二十八岁那一年，一场可怕的疾病带走了他人生的全部可能和希望，患上了小儿麻痹症的罗宾丧失了全部了行动力，甚至连呼吸都要依靠着机器维系，医生预言，罗宾最多能活三个月。让众人都没有想到的是，在如此糟糕的情境之下，戴安娜却并没有放弃希望。她将罗宾接回家精心照料，不仅仅是在身体上，亦是在精神上给于了罗宾继续活下去的理由和动力。在真爱面前，哪怕是残酷无情的病魔都退缩了。©豆瓣', '安德鲁·加菲尔德', '安迪·瑟金斯', 8, 35529, 'tt5716464', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2493495877.jpg', 0.2, 1.5, 23.3, 48, 26.9, '0.021018,0.113779,-0.767800,0.460958,-0.346090,-0.513335,0.708221,0.095988,-0.352335,0.054460,0.117640,0.596673,-0.022328,0.102125,0.097246,-0.282110,-0.327602,-0.695762,-0.132373,-0.029175,-0.489572,-0.602614,-0.174548,-0.300532,-0.022628,-0.576889,0.594768,0.179634,-0.243400,0.286175,0.238724,0.065104,0.290856,0.515064,-0.186979,-0.028046,-0.154034,-0.026891,-0.380713,0.337761,0.019055,-0.241607,-0.111954,0.476216,0.086413,0.222660,0.527767,-0.415947,-0.281578,0.063701,0.260275,-0.286075,-0.149833,0.293357,0.033489,-0.125596,0.151910,0.347201,-0.148184,-0.117675,0.458316,0.053282,-1.016852,0.202618,-0.008668,0.148735,-0.711324,0.606295,-0.097342,-0.221327,0.118964,-0.267236,0.130130,0.258050,0.145708,0.396559,-0.254679,0.068672,-0.466178,0.265843,0.646968,0.027608,-0.650777,0.535184,-0.314034,-0.486110,-0.229191,-0.205812,-0.352435,0.017664,0.364690,0.395980,-0.275132,0.302989,-0.420488,0.068323,-0.307719,-0.303613,-0.129203,-0.513411,0.009500,-0.461024,-0.107743,-0.286222,-0.398903,0.130772,0.058178,-0.333575,0.778903,-0.719538,0.420278,0.644198,0.322185,-0.377585,0.697686,0.258378,0.133678,0.105967,0.127459,0.340322,-0.168054,0.385346,0.535028,0.327309,-0.037354,0.294573,-0.416603,0.527945', '30163500', '1793491', '25917239', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26806780', '忍之国', '喜剧', '群雄并起的战国时代。第六天魔王织田信长逐一击溃强劲对手，离雄霸天下仅仅一步之遥。在此之前，他将次子织田信雄（知念侑李 饰）送到伊势的北畠当女婿，借着信雄之手，当地大名北畠具教（国村隼 饰）被彻底打倒。然而颇令织田信长感到棘手的是，伊势的邻国伊贺是一个藏龙卧虎、杀机四伏的凶险之地。在那里潜伏着被世人称为“虎狼之族”的伊贺忍者。有超级忍者之称的无门（大野智 饰）隶属于百地三太夫（立川谈春 饰）麾下，虽然武功高强，傲慢无比，却只贪图老婆阿国（石原里美 饰）的温柔乡。为了对抗外族入侵，伊贺各族忍者结为军师联盟。直到某一天，织田大军终于踏上伊贺的土地，无门再也无法安享太平……本片根据和田龙于2008年的同名小说改编。©豆瓣', '大野智', '中村义洋', 7.1, 12128, 'tt5769414', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2455420497.jpg', 2.6, 8.4, 38.7, 34.3, 16, '-0.145958,-0.011692,-0.461142,0.457832,0.285773,0.030457,-0.006879,-0.057583,-0.455007,-0.731206,0.119940,0.504876,0.256578,-0.032929,0.240754,-0.108085,0.295898,-0.569739,-0.216464,-0.358311,0.248195,0.008306,-0.329899,-0.246063,-0.281598,-0.089760,0.887321,0.424992,-0.265652,0.333103,0.129721,0.614291,-0.308659,0.228679,-0.076611,-0.031703,0.041160,-0.192770,-0.275658,0.508360,-0.721240,-0.261138,-0.127243,0.221901,-0.066298,0.161494,0.248462,-0.587672,-0.004707,-0.389793,-0.013002,-0.199113,-0.499096,0.202135,0.681312,-0.240403,0.041044,0.204028,-0.028969,-0.129383,0.108071,0.007941,-0.663252,-0.287308,0.234646,0.104414,-0.259719,0.617206,-0.141639,-0.344445,0.111482,-0.287790,-0.073359,0.088233,0.294718,-0.099013,-0.047881,0.167531,-0.122158,-0.003045,0.609716,-0.029283,0.077191,-0.301527,0.214307,-0.454820,0.057828,-0.586299,-0.221523,-0.168410,0.247345,-0.101080,0.349848,0.346510,-0.296163,-0.204156,-0.164298,0.096024,0.194200,-0.037723,0.271716,-0.364194,0.075343,-0.372941,-0.194615,0.421167,0.484619,0.017545,0.743049,-0.723574,0.068455,0.460727,0.458270,0.047162,0.172455,0.170267,-0.223355,0.079872,-0.257315,0.257499,0.635013,0.303749,0.123041,0.147704,-0.452820,-0.300619,-0.278462,0.181687', '3861846', '26615753', '30255079', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26808466', '提着心吊着胆', '剧情', '杨百万（陈玺旭 饰）和妻子马丽莲（高叶 饰）共同经营着名为仙客来的饭店。马丽莲样貌出众个性泼辣，让杨百万很没有安全感，整日疑神疑鬼，担心头上不知什么时候就多了一顶绿帽子。某日，杨百万撞见马丽莲和一陌生男子共处一室，愤怒中，他暴打了该男子，却反而遭到了妻子的一顿修理。认定了自己遭到背叛的杨百万找到了神医毕见效（曹瑞 饰），花费巨款委托后者找杀手做掉马丽莲以解自己的心头之恨。约定当晚，杨百万药倒了马丽莲后离开，却在无意之中发现了妻子的清白，而彼时杀手已经默默的来到了马丽莲的身边。心急如焚的杨百万赶回家，没想到眼前出现的竟然是毕见效的“尸体”和昏倒的马丽莲。©豆瓣', '陈玺旭', '李雨禾', 6.7, 38093, 'tt6892250', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2456976809.jpg', 1.2, 7.5, 51, 34.5, 5.9, '0.123238,0.403555,-0.731659,0.394807,-0.228824,-0.489323,0.850554,-0.006367,-0.449764,-0.536971,-0.023472,0.366378,-0.483483,0.115089,0.202728,-0.128473,0.371104,-0.533046,-0.410571,-0.258999,-0.434904,-0.337531,-0.319957,-0.189765,-0.303814,-0.019761,0.017518,0.190407,-0.099133,0.462752,0.471682,0.263611,0.188631,0.653054,-0.373037,0.238057,0.035111,0.101906,0.049403,0.303956,0.283147,-0.537503,0.034222,0.142779,-0.146497,0.312198,0.623678,0.058534,-0.400203,0.014181,0.298564,-0.175676,-0.071088,0.086614,0.422600,-0.227205,0.151547,-0.469502,-0.295989,-0.257740,0.251062,0.094321,-0.475715,-0.072024,0.167358,-0.033061,-0.978139,-0.049620,-0.333655,0.114177,0.000382,-0.456130,0.363485,0.271925,0.473046,0.401187,-0.020592,0.042871,-0.755401,0.354513,0.708805,0.145446,0.245457,-0.046951,-0.275542,-0.403705,0.211336,-0.091494,-0.376015,-0.135884,0.440794,-0.226941,0.140451,-0.172624,-0.193799,-0.228989,-0.256955,0.001927,-0.112920,-0.397352,-0.061878,-0.033442,-0.244339,-0.439437,-0.216167,0.442460,0.123935,-0.208846,0.510633,-0.668964,0.404643,0.028612,0.535543,-0.558752,0.576725,0.048237,0.146229,0.085146,0.259148,0.081775,0.377439,0.165977,0.340264,0.361762,-0.172556,-0.290074,-0.300095,0.358148', '1299965', '10355329', '25837175', '1306505');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26809007', '奇迹，那天如此重要', '剧情', '仁（松坂桃李 饰）和秀（菅田将晖 饰）出生于医生世家，他们的父亲是一位德高望重的医生，希望两个儿子长大后能够继承自己的事业。然而，叛逆桀骜的仁却并没有那份医者的仁心，热爱音乐的他组建了一支乐队，并且在演出中被音乐经纪人相中，他决定正式出道成为一名歌手。仁的决定让他和父亲之间爆发出了激烈的争吵，最终，仁决绝的离开了家。在哥哥和父亲的关系降到冰点的那段日子里，温柔的秀正在艰苦的进行着备考，成绩不算优异的他最终选择了牙科大学作为奋斗的目标。仁的音乐道路走得十分不顺利，各种利益的冲突让他和队友们之间亦产生了隔阂。而顺利考入了大学的秀，在某日拿起哥哥的吉他之后忽然发现了音乐带给他的抚慰和力量。©豆瓣', '松坂桃李', '兼重淳', 7.7, 21590, 'tt5778092', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2397621888.jpg', 0.3, 2.4, 29, 46.9, 21.5, '0.243642,0.189998,-0.698703,0.863509,-0.018074,-0.437974,0.549999,0.291191,-0.309651,-0.321987,0.023229,0.845977,-0.046238,0.393566,0.180193,-0.334586,-0.002645,-1.097156,-0.187414,-0.225934,-0.196528,-0.486818,0.070298,0.038471,-0.394246,-0.270002,0.777937,0.066040,-0.196195,0.674204,0.220915,0.166719,0.055802,0.336793,-0.257874,-0.036869,0.023384,0.271500,-0.441552,0.121741,0.415083,-0.226532,-0.307061,0.256970,0.096096,0.373671,0.857287,-0.296017,-0.051778,0.104978,0.389223,-0.280076,-0.154568,0.174660,0.303215,0.217957,0.130313,0.414307,-0.155588,0.138912,-0.186710,-0.202606,-0.944646,-0.143511,-0.007231,0.101477,-0.693682,0.833423,0.107307,-0.328970,0.281905,-0.211955,0.304710,0.330949,0.161728,0.581426,-0.546131,0.137603,-0.271078,0.161006,0.845784,-0.060541,-0.266648,0.437074,-0.504630,-0.479796,-0.067852,-0.374765,-0.558296,-0.166929,0.261338,0.066326,-0.031620,0.069114,-0.577206,-0.155656,-0.214170,-0.021820,0.155385,-0.417840,0.060921,-0.532179,-0.101451,-0.600260,-0.283784,0.216954,-0.061725,-0.456143,1.112167,-1.164033,-0.110339,0.455243,0.464604,-0.484593,0.606287,0.174386,0.233983,-0.134026,-0.167129,-0.171465,-0.173725,0.144296,0.275804,0.512110,-0.121099,-0.167011,-0.466035,0.386479', '1826173', '4127270', '3811356', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26809592', '魅影缝匠', '剧情', '故事发生在二十世纪五十年代的伦敦，雷诺兹（丹尼尔·戴-刘易斯 Daniel Day Lewis 饰）和妹妹西丽奥（莱丝利·曼维尔 Lesley Manville 饰）一起经营着名为“伍德科克之家”的制衣所，在伦敦当时的上流社会之中，能够穿上雷诺兹亲手缝制的礼服是每一个王公显贵和明星名流的愿望。一次偶然中，雷诺兹在餐馆里遇见了名为阿尔玛（薇姬·克里普斯 Vicky Krieps 饰）的女服务生，两人一见钟情。雷诺兹将阿尔玛领入了五光十色的花花世界，但阿尔玛眼中却一直凝望着雷诺兹的身影。在生活中，雷诺兹是一个特别难缠和挑剔的怪人，朝夕相处之下，他和阿尔玛之间屡屡产生矛盾。眼看着雷诺兹的态度越来越冷淡，阿尔玛知道，自己必须采取行动，来捍卫她的爱情。©豆瓣', '丹尼尔·戴-刘易斯', '保罗·托马斯·安德森', 7.5, 92633, 'tt5776858', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2506487968.jpg', 0.8, 4.1, 32.1, 45, 18.1, '0.399891,-0.066266,-0.678633,0.662361,-0.117353,-0.149624,0.904810,0.105256,-0.416361,-0.353552,0.074637,1.035467,-0.313088,0.389277,0.449685,0.194567,-0.279829,-0.828430,-0.154106,-0.377939,-0.036311,-0.579830,-0.420076,0.036448,-0.131576,-0.173263,0.266111,0.037083,0.031394,0.538679,0.509328,0.246378,-0.014052,0.435802,-0.291890,-0.181866,0.134880,-0.130844,-0.182241,0.156712,0.084743,-0.258681,-0.096451,0.273696,0.152251,0.320534,0.521586,-0.608874,0.271191,-0.090183,0.309418,0.000269,0.241648,0.239313,0.173118,-0.174630,0.312783,0.252675,-0.231529,-0.153352,0.225174,-0.290922,-0.510088,0.144949,0.167692,0.233470,-0.827597,0.494771,0.005109,0.046115,0.124584,-0.310097,0.269880,0.031487,0.404396,0.269097,0.027093,-0.026707,-0.560225,0.079337,0.538494,0.264734,-0.215826,0.247257,-0.464538,-0.224163,-0.191188,-0.097113,-0.802776,-0.137250,0.335300,-0.052500,0.027488,0.241573,-0.598630,-0.132655,-0.069309,-0.047580,0.082157,-0.246968,-0.105385,-0.742660,-0.045157,-0.878890,-0.368026,0.037036,-0.139467,-0.325801,0.440830,-0.818837,0.082260,0.445560,0.415895,-0.094993,0.935898,0.065559,0.386074,0.087831,-0.311599,0.219199,0.112560,-0.027752,0.071604,0.563358,-0.032383,0.057556,-0.278573,0.611701', '30162520', '1895119', '1292207', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26810068', '冷血追击', '剧情', '内尔森（连姆•尼森 饰）是基欧滑雪场的扫雪车司机，身为荣誉市民的他终日勤恳工作，以保证这座宁静小镇交通的顺畅。有天突然传来儿子身亡的消息。为了追查出杀害儿子的真凶，怒火中烧的内尔森不惜以身犯险，卷入重重杀人案，踏上了歼灭贩毒团伙的道路。复仇路上，狂妄冷血的毒枭“海盗哥”、残暴的印第安帮派首脑“白牛”等浮出水面，错综复杂的凶狠敌军、险象环生的黑帮对峙、以及枪林弹雨下的生死大战，一场冤冤相报的血雨腥风席卷了这座雪白安宁的小镇……', '连姆·尼森', '汉斯·皮特·莫朗', 6.7, 28192, 'tt5719748', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2567214398.jpg', 0.8, 8.3, 54.1, 30.8, 5.9, '-0.110692,-0.102140,-0.470796,0.365349,0.259827,-0.026445,0.609879,0.227632,-0.421119,0.143572,0.603136,0.496157,0.016099,-0.077823,0.359828,-0.111457,-0.294219,-0.645110,-0.408399,0.073439,-0.064241,-0.202078,-0.207706,-0.392563,0.217412,-0.105217,0.606528,0.507749,-0.153571,0.398054,0.207747,0.368132,-0.431675,0.312001,-0.304445,-0.135026,-0.155295,-0.135337,-0.507604,-0.134392,-0.330704,-0.249961,-0.110396,-0.095826,-0.062549,0.500479,0.493962,-0.192053,-0.065645,-0.154004,0.236453,-0.495769,-0.034045,-0.116107,0.494101,-0.342837,-0.112455,0.343198,-0.111064,-0.330345,0.069975,-0.137296,-0.664310,-0.129252,-0.068997,0.209189,-0.563854,0.299200,-0.122083,-0.017874,0.023272,0.033923,0.173505,0.325564,0.207848,0.176055,0.069923,0.332011,-0.376606,-0.111035,0.702293,-0.272380,-0.126143,-0.316124,-0.279925,-0.273659,0.333100,-0.481220,-0.246242,-0.313683,0.694175,-0.618686,-0.033027,0.547847,-0.465512,-0.270681,-0.460618,-0.237048,-0.163885,-0.011256,-0.531107,-0.512147,-0.086230,0.021917,0.137336,0.293271,-0.257704,0.013692,0.160832,-0.537839,0.152945,0.616065,0.085505,-0.325775,0.301167,-0.025136,0.345570,-0.038303,-0.244458,0.531253,0.171443,0.505854,0.111531,0.117113,-0.215666,-0.107179,0.003302,0.150068', '25828589', '1293829', '26747274', '1294941');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26810318', '阿尔法：狼伴归途', '剧情', '故事开始于两万年前的欧洲北部，彼时正直冰川时期，科达（科迪·斯密特-麦菲Kodi Smit-McPhee 饰）是部落首领的儿子，在一次集体狩猎行动中，他不幸跌落了悬崖，音信全无。所有人都以为科达已经死了，但不幸中的万幸是，洪水卷走了他，使得他保住了一命，然而，水流将科达送往了离部落非常遥远的漫漫荒野之中，在异常恶劣的天气和极度匮乏的资源的威胁下，科达踏上了归家之旅。在旅途中，科达和一匹孤狼邂逅了，狼成为了他的旅伴，他给它起名为阿尔法。阿尔法是狼群的首领，在和阿尔法的相处之中，科达学习到了许多在荒野之中生存的技巧，同时也被唤醒了内心的狼性。©豆瓣', '柯蒂·斯密特-麦菲', '艾尔伯特·休斯', 6.4, 42105, 'tt4244998', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2530871439.jpg', 1.7, 13.3, 55, 23.3, 6.8, '0.386017,0.083052,-0.844013,0.615106,0.042793,-0.193167,0.712642,0.097267,-0.608447,0.194673,0.267242,0.808862,0.104595,0.153165,0.420184,-0.014600,-0.142004,-0.535838,-0.284201,-0.245233,-0.396208,-0.383336,-0.522319,0.069556,-0.252919,-0.556172,0.730653,0.414470,-0.176104,0.531189,-0.187230,0.346846,-0.087005,0.673609,-0.574360,0.027983,-0.023678,-0.223225,0.011114,0.395339,-0.099237,-0.340132,-0.085803,0.346083,0.144284,0.433819,0.709207,-0.496242,0.028849,-0.153079,0.174470,-0.433246,-0.092576,0.092445,0.457518,-0.228326,0.226449,0.321931,-0.148370,0.023010,-0.062599,0.030358,-0.679303,-0.004020,-0.120054,0.168559,-1.022212,0.648466,0.002088,-0.222362,0.194283,-0.407795,0.374376,0.271101,0.120872,0.403502,-0.061795,-0.204373,-0.529399,0.002049,0.920282,-0.185764,-0.368644,0.104004,-0.125865,-0.604754,0.007350,-0.207088,-0.278597,-0.369264,0.612855,0.122921,-0.236187,0.561914,-0.900850,0.313359,-0.313338,-0.412840,-0.348755,-0.354790,-0.294015,-0.206027,-0.191449,-0.571445,-0.251240,0.095460,0.058253,-0.188714,0.615575,-0.845618,0.323246,0.632175,0.208318,-0.036845,0.534701,-0.020360,0.275233,0.204736,0.310774,0.257700,-0.027757,0.448637,0.360711,0.559415,-0.179470,-0.157046,-0.516591,0.703046', '2032339', '21360412', '1866424', '1293952');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26810837', '为你取名的那一天', '剧情', '电视制作人久野佳奈美目睹日本311大地震之後，看到被弃养在福岛核电厂境內20公里內的貓狗，深深受到冲击。所幸采访途中，她认识了許多“不畏殘酷现实，能救的生命都不该放弃”的愛心人士。看到他们认真的态度，像是躲过大地震摧殘的狗和饲主之间的情谊，记录老人与狗狗得以重生，互相扶持的温馨生活……而我們在被拯救的生命中，看見未來的希望。', '小林聪美', '山田茜', 8.4, 12256, 'tt5167942', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2264955151.jpg', 0.4, 1, 14, 46.7, 37.9, '0.443979,-0.170366,-0.831418,0.491060,0.030071,-0.061065,0.827585,-0.047932,-0.447142,0.023299,0.252182,0.959823,-0.471176,0.311129,0.108407,-0.472099,0.050761,-0.743724,-0.460577,0.164674,-0.192615,-0.218992,-0.447362,-0.156647,-0.051476,-0.453206,0.580091,0.369658,-0.132384,0.775880,-0.042518,0.269577,-0.314676,0.452565,-0.185285,0.015377,-0.216240,0.174395,-0.483288,-0.003883,-0.108673,-0.280108,0.159947,0.302963,-0.184131,0.322149,0.739524,-0.443060,-0.490316,-0.241508,0.255486,-0.247825,0.065362,0.306778,0.193002,0.231704,0.241014,0.015756,0.131355,0.001066,0.085172,0.047796,-0.693320,-0.153005,0.043646,0.354429,-0.501454,0.704579,0.086702,-0.199453,0.209527,-0.178596,0.266302,0.361757,0.473524,0.656196,-0.430319,0.106623,-0.604554,0.008496,0.902663,-0.284845,-0.428801,0.582052,-0.333040,-0.472159,0.027689,-0.506020,-0.423759,0.060357,0.233370,0.013316,-0.514130,0.564767,-0.627329,0.226624,-0.198178,-0.248963,0.008178,-0.599796,-0.124327,-0.668772,-0.200695,-0.504236,-0.199794,0.595614,0.105051,-0.680686,0.789358,-0.700228,0.331907,0.541320,0.459166,-0.453652,0.851849,0.064929,-0.147404,-0.095636,0.107134,0.322383,0.277269,0.495055,0.149360,-0.042266,-0.154134,0.029272,-0.637922,0.426675', '30162520', '3055049', '25721544', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26811367', '疯狂特警队', '喜剧', '特警队教官欧仁近来诸事不顺，而偏偏警队又突然空降了一个培训生乔汉娜，这个一心想成为法国特警队第一位女警官的培训生就像一颗定时炸弹，她给特警队惹了千奇百怪、层出不穷的麻烦，但每次都歪打正着，和队友一起出色完成各类高难度任务……', '丹尼·伯恩', '丹尼·伯恩', 5.6, 4347, 'tt5736696', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2505519671.jpg', 6.4, 26.3, 52.5, 11.5, 3.3, '0.364888,-0.356486,-0.518982,0.507774,-0.157257,-0.535666,0.220369,0.023141,-0.487632,0.071824,0.066590,0.858220,-0.425623,-0.004302,0.464136,0.017579,-0.137849,-0.612031,-0.145185,0.060770,-0.370256,-0.295346,-0.130882,-0.105281,0.332324,-0.035743,0.310567,-0.253190,0.127564,0.672353,0.451189,0.238908,0.192163,0.351791,-0.398446,-0.145032,0.493935,0.038591,0.506518,-0.049642,0.124707,-0.258886,-0.097849,-0.009643,0.229616,0.410343,0.273750,0.267987,-0.495675,-0.419969,0.395411,-0.439284,-0.019558,-0.146411,0.539124,0.026672,0.036577,-0.230049,-0.136918,0.163655,0.150072,-0.233350,-0.820866,-0.061704,-0.085867,-0.124250,-0.569141,0.007950,-0.144943,0.279971,0.044640,0.016602,0.396392,0.410334,0.335064,0.266650,-0.415399,-0.139842,-0.324945,0.420384,0.522702,-0.091055,-0.465396,0.043641,-0.203313,-0.436910,0.313442,-0.404542,-0.173375,0.027887,0.107678,-0.353366,-0.076427,-0.099172,-0.307809,0.429959,-0.214717,-0.080573,-0.310621,-0.472355,-0.116888,-0.430270,0.217246,0.069457,-0.400009,0.465488,0.223582,0.135052,0.971783,-0.727255,0.118462,0.770485,-0.325633,-0.769552,0.254378,0.513835,0.278689,-0.207251,0.162778,-0.550757,0.135439,0.655372,0.086804,1.012228,0.022627,-0.632064,-0.278931,-0.119207', '27602116', '24284209', '34429100', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26811587', '大护法', '喜剧', '为了寻找下落不明的太子（图特哈蒙 配音），大护法（小连杀 配音）来到了一个诡异而又古怪的小镇上，在那里居住着一群不会说话的花生人，它们夜夜点燃来路不明的油灯，将天上漂浮的巨大花生熏得黑漆漆的。大护法在镇上找到了藏匿在此的太子，并遇见了一直在保护着太子的小鸣（幽舞越山 配音）和会说话的花生人小姜（李兰陵 配音），在大护法的威逼利诱之下，太子同意跟他回去继承王位，却在半路上遭到了绑架。在解救太子的过程中，大护法渐渐解开了这个小镇上隐藏的骇人谜团，与此同时，他的强大宿敌亦在身后步步紧逼，企图将他置于死地而后快。©豆瓣', '小连杀', '不思凡', 7.8, 345638, 'tt7146054', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2490948849.jpg', 1.1, 3.9, 24.2, 45.9, 24.9, '0.126034,0.242946,-0.943842,0.838532,-0.119072,-0.107025,0.893745,0.365898,-0.435000,-0.009112,0.408826,0.721654,-0.126751,0.099418,0.123838,0.059127,-0.038379,-0.448051,-0.415112,-0.115139,-0.411401,-0.527560,-0.476666,-0.294605,-0.086063,-0.198932,0.408551,0.042607,-0.195853,0.320206,0.489260,-0.099876,-0.400206,0.454873,-0.243726,0.002739,-0.103330,-0.116147,0.154077,0.316995,-0.098822,-0.662742,-0.222323,0.032854,0.076487,0.397517,0.443573,-0.409341,-0.041756,-0.069286,0.096933,-0.451971,0.036866,0.056264,0.248263,-0.085871,0.029838,0.106745,-0.282800,-0.085214,0.059019,-0.068083,-0.598064,0.204444,0.043037,0.384434,-0.736695,0.538037,0.188239,-0.216259,0.141388,-0.520963,0.438418,0.177877,-0.149391,0.189073,-0.190795,0.063619,-0.632682,0.113002,0.457106,-0.046132,-0.037751,-0.187418,0.146923,-0.088305,-0.118187,-0.140164,-0.478689,-0.374080,0.653959,0.083894,-0.246629,0.290447,-0.380076,0.113546,-0.253689,-0.110108,0.011723,-0.276329,-0.099577,-0.363254,0.072260,-0.137843,-0.173949,0.385808,0.155094,-0.279982,0.703210,-0.681827,0.294352,0.682396,0.465584,-0.193098,0.326759,-0.090846,0.113280,0.147039,-0.450610,-0.120013,0.157447,0.612564,0.505663,0.533636,-0.231461,0.105017,-0.867945,0.143516', '21619567', '1866424', '1783772', '1421570');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26811605', '相声大电影之我要幸福', '剧情', '冯前程（郭麒麟 饰）为了哄郭壕（郭德纲 饰）的女儿郭佳林（黎心韵 饰）开心，从车行将郭壕的车开出来，不料却将豪车后备箱里郭壕装结婚大钻戒的保险箱遗失，冯前程为了找箱子听了算命先生（张鹤伦 饰）的指引，阴差阳错地相信失忆的岳强男（岳云鹏 饰）肯定知道箱子的下落。几经周折箱子终被找到，婚礼现场却“另起事端”……', '郭德纲', '张栾', 3.1, 6679, 'Our Happiness', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2506165789.jpg', 65.2, 22, 8.8, 1.9, 2.1, '-0.012586,0.362090,-0.352024,0.229279,-0.262492,-0.209877,0.722847,0.074866,-0.311797,-0.288429,-0.352779,0.378410,-0.483885,0.082971,0.062786,0.187575,-0.181230,-0.434960,0.055270,0.005726,-0.331428,-0.055028,0.052226,-0.302008,0.145389,0.339648,0.167738,0.568306,0.041421,0.275930,0.734561,0.000199,-0.279440,0.108661,-0.198485,0.066684,-0.668793,0.409560,0.212422,-0.150454,-0.018676,-0.461213,0.186333,0.130232,0.293435,0.200946,0.595845,0.269798,0.157569,0.259322,0.239421,0.195455,0.242030,-0.213807,0.081702,0.489262,-0.230742,-0.087394,-0.352469,-0.145143,0.806628,-0.148075,-0.415384,0.352987,0.129535,-0.262283,-0.649480,0.100023,-0.366958,0.096446,-0.003471,-0.082264,0.484643,0.065083,0.550631,0.149219,-0.145418,0.182527,-0.868899,0.232624,-0.251193,-0.455491,0.611967,0.241620,0.098184,-0.493486,0.087037,0.115247,-0.335358,0.056017,0.698776,-0.005475,-0.016377,-0.425650,-0.312193,-0.191589,-0.348726,0.118255,0.232126,-0.273021,0.013374,-0.101282,0.228264,0.187602,-0.045415,0.228114,-0.082254,0.076467,0.632156,0.071772,-0.003188,0.161648,0.159521,-0.719594,0.535397,-0.165003,0.062193,-0.446969,0.296819,0.174698,0.380994,0.206150,0.249694,0.168684,-0.173083,-0.268954,-0.261387,0.150454', '1292440', '10527288', '2978951', '1302110');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26811844', '是爱非友', '剧情', '马提亚斯（Ignacio Rogers 饰）和杰罗尼莫（Esteban Masturini 饰）是青梅竹马的邻居加好友，两人之间的感情非常的要好。随着年龄的增长，性方面渐渐觉醒的两人最终发生了逾越了友谊的关系，当这段关系被家长们发现后，马提亚斯的父亲带着儿子离开了小镇，马提亚斯和杰罗尼莫之后再也没有联系过。一晃眼十年过去了，马提亚斯早就经历了社会的“改造”，成为了普世意义中的“正常人”，不仅如此，他还结交了一位漂亮的女朋友。这一天，他带着女友重新返回故乡小镇参加嘉年华活动，哪知道在这里，他和杰罗尼莫重逢了。压抑已久的感情火山般的爆发了。©豆瓣', 'Ignacio Rogers', 'Papu Curotto', 7.7, 7017, 'tt5883632', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2422911035.jpg', 0.4, 3, 29.1, 45.1, 22.5, '0.526859,0.067668,-0.879520,0.595642,0.045513,-0.453140,0.571105,-0.042147,-0.506372,-0.364394,-0.252236,0.839370,-0.580644,0.272286,0.090525,-0.137766,-0.325894,-0.893180,0.044330,-0.640538,-0.475028,-0.439303,-0.224134,-0.004580,-0.241136,-0.429614,0.469456,-0.072393,0.010710,0.584390,0.206055,-0.040582,0.224409,0.462302,-0.361292,0.192924,0.100709,0.246136,-0.348046,0.105287,0.261856,0.251753,0.145226,0.124693,0.186343,0.426965,0.634864,-0.163498,-0.012740,-0.014228,0.155956,0.180922,0.181270,0.087905,0.535059,-0.100741,0.027849,0.432725,-0.203831,-0.415211,-0.031906,-0.084505,-0.215301,0.075700,-0.063470,0.023739,-0.690615,0.407444,0.106088,-0.220774,0.076169,-0.143402,0.192824,0.787153,0.219071,0.476916,0.152593,-0.078010,-0.306373,0.109898,0.914758,-0.076682,-0.416994,0.518833,-0.451564,-0.460704,-0.248876,-0.175229,-0.340739,-0.054178,0.353685,0.151401,-0.246764,0.418524,-0.715451,-0.108813,-0.129114,0.031984,0.098271,-0.474064,0.156116,-0.794848,-0.464070,-0.692247,-0.229405,0.170517,-0.124547,-0.058082,0.640932,-0.821037,0.272620,0.425735,0.584984,-0.433903,0.813698,0.022922,0.064693,-0.273629,0.394419,0.315718,-0.151083,0.090040,0.416497,0.423566,-0.053970,0.147315,-0.347141,0.645615', '30162520', '1303333', '11541282', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26813286', '幸福马上来', '喜剧', '家住在山城重庆的马尚来（冯巩 饰）干了一辈子调解员，虽然工作中经历过各种险情和挫折，但他依然满腔热情，乐此不疲。眼看到了退休的年龄，马尚来非但不想回家享享清福，反而要开一个工作室继续为人民服务。他的老婆（牛莉 饰）为此大为光火，想方设法要阻止丈夫再就业。与此同时，名叫茅雪旺（涂松岩 饰）的男人抢注了马尚来的名字，名义上也干调节工作，但为了钱不择手段。在与茅雪旺对抗的过程中，马尚来偶然结识了弟子（张小斐 饰）的好哥们儿金珍（毛俊杰 饰）。金珍对马尚来过分热情，这不仅让追求她的茅雪旺醋意大发，更令马妻火冒三丈。人过中年，马尚来的人生似乎变得愈加精彩起来……©豆瓣', '冯巩', '冯巩', 3.7, 12027, 'tt8443434', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2521514148.jpg', 41.6, 37.4, 16.8, 2.1, 2.1, '-0.041476,-0.010979,-0.589523,0.380388,-0.150625,-0.368731,0.453528,0.379263,-0.583585,-0.051010,-0.103006,0.467916,-0.174343,0.198773,0.280699,-0.235399,-0.174348,-0.499632,0.121688,0.159538,-0.055801,-0.154851,-0.006448,-0.113670,-0.368098,-0.280909,0.321602,0.110809,0.041669,0.545082,0.296191,0.001032,0.326334,0.448182,0.039037,-0.019935,-0.030076,0.261118,-0.199125,-0.021750,0.019914,-0.330648,-0.119516,0.257211,0.216105,0.283505,0.510932,0.143454,-0.351365,-0.099307,0.251441,-0.152056,-0.066137,0.016553,-0.014475,0.024045,0.374934,0.139976,-0.271462,0.031414,0.147548,-0.156192,-0.772614,0.186437,0.231545,-0.092634,-0.541107,0.494368,-0.108374,-0.043506,-0.113330,-0.186738,0.093957,0.328843,0.231129,0.355650,-0.459270,0.181184,-0.392527,0.575320,0.631335,0.126858,0.144185,0.232120,-0.214106,-0.164074,0.091508,-0.371727,-0.469394,-0.161500,-0.011427,-0.025642,-0.219472,0.085293,-0.541061,0.112543,-0.095879,-0.062486,-0.064444,-0.366205,-0.052968,-0.286020,-0.050927,-0.387624,-0.208012,0.084724,0.144648,-0.345139,0.532469,-0.695079,0.030782,0.411569,0.318164,-0.634610,0.593108,0.486522,0.210740,-0.116172,-0.341347,0.067519,-0.041994,0.236589,-0.051571,0.127882,-0.073059,-0.385092,-0.163736,0.386482', '1877596', '1308805', '26678784', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26815162', '生存家族', '喜剧', '《生存家族》讲述了这么一个故事，突然有一天家里的电器全部无法运转，车，自来水，电池，手机和电视等等都不能使用了，在东京生活的铃木一家决定骑自行车去乡下，逃离东京…', '小日向文世', '矢口史靖', 8, 117689, 'tt5890000', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2525716036.jpg', 0.3, 1.5, 19, 55.2, 24, '0.204848,-0.064839,-0.427611,0.541441,-0.023328,-0.153194,0.209183,0.474642,-0.162684,-0.748039,0.104411,0.710263,0.342813,0.179108,-0.051391,-0.315310,-0.665473,-0.413361,0.190714,0.021574,-0.474010,-0.191735,0.205578,-0.452067,0.213979,0.099430,0.432638,0.123132,-0.178519,0.414750,-0.277680,-0.117517,-0.104979,0.340964,-0.774252,0.035516,-0.200121,0.242307,0.203965,0.324547,-0.077924,-0.099786,0.252231,0.045259,0.798170,-0.201783,0.604091,0.377256,-0.092667,0.063605,-0.063560,0.384813,-0.267558,-0.377869,0.495411,-0.051030,0.171072,0.071055,-0.533325,-0.052908,0.182429,0.299730,-0.742298,-0.337635,-0.525425,-0.179875,-0.813838,0.105757,-0.328304,-0.120832,-0.127713,-0.426192,0.375441,0.387688,0.537768,0.613365,-0.222363,0.118817,-0.889614,0.318235,0.617702,-0.367614,0.044950,0.795147,0.093521,0.010045,-0.555685,-0.163381,-0.776760,-0.210733,0.107396,0.062944,-0.691798,0.275942,-0.746512,-0.055550,-0.072853,-0.702191,0.565550,-0.416087,-0.140363,-0.717859,0.043586,0.156452,0.191245,0.423924,0.173576,0.166406,0.913100,-0.626398,-0.055191,0.345278,0.347815,-0.597030,0.682989,0.005666,0.236295,0.045794,0.613829,-0.005801,0.065488,1.029576,-0.069834,0.480427,0.021432,0.178423,-0.689800,0.509091', '1302661', '1308842', '1307811', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26815856', '疯岳撬佳人', '喜剧', '李帅亭（岳云鹏 饰）是一个单纯善良的小伙子，大学四年间，他一直默默的喜欢着名为张子墨（袁姗姗 饰）的姑娘，然而李帅亭深知自己和对方之间的差距过大，只得将这份感情深深埋藏在心底。然而，最终，李帅亭还是鼓起了勇气，向张子墨坦白了爱意，哪知道非但没有感动女神，还遭到了嘲讽和奚落。受伤的李帅亭来到了一家养老院上班，每日沉迷于工作之中，以此逃避惨淡的现实。李帅亭负责照料一位名叫老朱（石小满 饰）的老人，在他无微不至的关怀下，本已经是植物人的老朱竟然奇迹般的康复了。康复后的老朱给了李帅亭一大笔酬金，拿着钱，李帅亭来到了爱情战略中心，来实现他长久以来的愿望。©豆瓣', '岳云鹏', '钟少雄', 3.3, 11825, 'tt6857260', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2426231159.jpg', 56.4, 29, 10.1, 2.5, 2, '-0.003175,0.408629,-0.758380,0.728484,-0.146049,-0.587593,0.712981,0.325637,-0.393199,-0.049425,-0.033732,0.311855,0.026405,0.437806,0.093085,0.096913,-0.073788,-0.442101,-0.478098,-0.029142,-0.204416,-0.667425,-0.118161,-0.201009,-0.318385,-0.136226,0.149957,0.039825,-0.350306,0.437729,0.632930,0.320854,0.123736,0.617366,-0.095073,0.036708,-0.083632,0.022448,-0.292746,-0.087584,0.234059,-0.403589,-0.346554,0.144659,0.020502,0.157797,0.819609,-0.012736,-0.302559,0.221249,0.414577,-0.435117,0.179343,-0.078936,0.257291,-0.129675,-0.036972,-0.005312,-0.213573,-0.107495,0.205167,-0.203353,-0.558217,-0.218063,-0.053488,-0.087990,-0.803877,0.868570,0.050449,0.018366,0.160501,-0.289941,0.096575,0.025960,0.138304,0.299826,-0.461394,-0.259507,-0.405985,0.381776,0.468319,0.164137,-0.204697,0.395870,-0.193781,-0.540989,-0.198544,0.180171,-0.324042,-0.081654,0.425701,-0.016655,-0.161377,-0.035984,-0.366008,-0.028063,-0.284916,-0.112578,0.109296,-0.542950,0.086271,-0.489901,-0.094307,-0.433925,-0.678769,0.165296,0.052162,-0.125079,0.647288,-0.769837,0.232903,0.373395,0.189368,-0.409880,0.834204,0.037259,-0.059673,-0.013224,-0.209889,0.397508,-0.249228,0.242584,0.427247,0.497704,-0.297678,0.127659,-0.577083,0.376829', '1298880', '1304989', '1917323', '1292211');
