INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26816076', '“大”人物', '动作', '名不见经传的小刑警孙大圣（王千源 饰）出生入死在追查案件的第一线，在平凡无奇的一天，他突然听说与之有交情的汽车修理工赵勇强跳楼自杀了。赵勇强此前租住一处拆迁房，但拆迁房一夜被人强拆，他和儿子不仅被赶了出来，连预付的租金都打了水漂。在此之后，赵带着儿子找到地产开发商泰华集团总经理赵泰（包贝尔 饰），结果却遭受了殴打和羞辱。在此之后，孙大圣试图调查此事，却遭到泰华集团乃至警方内部的阻挠，而赵泰试图收买他的行为更激怒了耿直倔强的孙大圣。专横跋扈的赵泰为了摆平这件事，不惜采用各种龌龊肮脏的手段，正邪之战正式拉开帷幕……©豆瓣', '王千源', '五百', 6.4, 213266, 'tt9596638', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2544988187.jpg', 2.3, 12.4, 53.4, 26.2, 5.8, '0.071541,-0.012249,-0.655788,0.355725,-0.187551,-0.214434,0.380829,0.257763,-0.533979,-0.293396,0.299005,0.453610,-0.191041,0.015976,0.242234,-0.071675,0.046041,-0.554591,-0.021728,-0.056750,-0.001599,-0.481406,-0.064042,-0.338978,-0.016930,-0.076708,0.397802,0.325882,-0.381203,0.153524,0.386720,0.264188,-0.124036,0.470632,-0.005194,0.098425,0.092816,-0.000091,-0.304385,-0.076193,-0.087556,-0.441305,-0.047736,0.116051,-0.006725,0.669495,0.339322,-0.009692,-0.220787,-0.232676,0.261583,-0.313506,0.059291,0.212120,0.510660,0.160038,0.312011,0.528418,-0.380458,-0.282919,0.403445,-0.066349,-0.874465,0.047134,0.066482,-0.018802,-0.662412,0.599179,-0.174523,0.339259,-0.178075,-0.269580,0.202899,0.477046,0.157848,0.137027,-0.111149,0.022270,-0.613007,0.264703,0.804660,-0.133628,0.020381,0.105937,0.071843,-0.157569,-0.001656,-0.578296,-0.354047,-0.013166,0.461233,-0.228399,-0.260759,0.269606,-0.612757,-0.137907,-0.394167,-0.055510,0.060828,-0.341424,-0.002992,-0.464142,-0.104593,-0.286584,-0.289115,0.134614,0.150270,-0.098068,0.246823,-0.705808,-0.099615,0.469303,0.456812,-0.713502,0.409579,0.066949,0.100643,0.109765,-0.247762,-0.200080,0.363900,0.538415,0.244440,0.212915,0.005646,-0.377538,-0.073308,0.178894', '1877596', '26678784', '25917239', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26816086', '银魂', '喜剧', '这是一个外星人和地球人混居的时代，在外星移民的压迫和统治下，流传百年的武士道精神已然没落，然而，在一片倾颓之势面前，依然有一群人默默的遵守着他们的准则和正义。家道中落的青年志村新八（菅田将晖 饰）在一场意外中结识了万事屋老板坂田银时（小栗旬 饰）和天人少女神乐（桥本环奈 饰），三人成为好友。他们共同的朋友桂小太郎（冈田将生 饰）无故失踪，经过调查，一个名叫冈田似藏（新井浩文 饰）的男人和一把名为“红缨”的妖刀浮出水面。冈田似藏是曾经的攘夷志士高杉晋助（堂本刚 饰）的手下，高杉恨透了这个堕落的世界，一直都企图将它破坏殆尽。随着红缨的力量越来越强大，整个大江户被笼罩在越来越浓重的阴云之下。©豆瓣', '小栗旬', '福田雄一', 6.9, 124375, 'tt5805470', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2497751588.jpg', 2.4, 9.7, 41.4, 33.9, 12.7, '0.138540,0.129680,-0.593002,0.493511,-0.063927,-0.008833,0.687854,0.131009,-0.427962,-0.325144,0.233822,0.845196,-0.122742,0.119522,0.400950,-0.137617,-0.067919,-0.727278,-0.298417,0.025047,-0.151380,-0.440695,-0.443051,-0.018377,-0.362066,-0.299577,0.836394,0.331979,0.005823,0.510922,0.337462,0.580980,-0.333703,0.242324,-0.200385,-0.049435,0.060541,-0.079042,-0.004915,0.091513,-0.364026,-0.401693,-0.064254,0.222211,-0.366095,0.248079,0.585859,-0.401428,0.002578,-0.433083,0.155351,-0.168189,-0.371612,0.225176,0.533295,-0.009138,0.040341,0.299250,-0.169059,-0.102225,0.213419,-0.039753,-0.567117,-0.065476,0.186803,0.302059,-0.448079,0.458153,0.140583,-0.350475,0.160244,-0.180877,0.114976,0.236820,0.303519,0.262727,-0.298650,0.060547,-0.378163,0.066718,0.500805,-0.000239,-0.158238,0.072359,-0.227324,-0.325091,-0.372178,-0.090408,-0.391210,-0.380974,0.260574,0.081109,-0.134076,0.314324,-0.811536,0.096869,-0.000477,-0.142968,0.071578,-0.277973,-0.091446,-0.565479,-0.280862,-0.558846,-0.110957,0.531940,0.166185,-0.094965,0.965825,-0.788866,0.140155,0.198737,0.241731,-0.161563,0.357696,0.026892,-0.033034,-0.101018,-0.214885,0.078546,0.240010,0.337325,0.242037,0.438882,-0.155314,0.052986,-0.300057,0.363141', '3811356', '1826173', '25880986', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26816090', '沉默的证人', '动作', '雨夜，香港法医中心遭遇一伙训练有素的悍匪的洗劫。来者挟持陈嘉豪（张家辉 饰）乔琳（杨紫 饰）两位法医，逼迫他们寻找一具特殊尸体并找出尸体体内的一颗子弹。法医在解剖的过程中发现，子弹事关一场黑帮血拼的大案，而匪首SANTA（任贤齐 饰）的身份也另有蹊跷。为了保护证物揭开真相，手无寸铁的陈嘉豪乔琳，利用身边一切可以利用的器械，和法医中心的特殊地势进行布局反击。逐渐被激怒的匪徒越发狂躁嗜血，陷入绝境的法医们，无畏楼毁人亡的危机，决心硬刚到底！', '张家辉', '雷尼·哈林', 5.3, 125619, 'tt7937440', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2564369311.jpg', 10.1, 32.8, 44, 10.1, 2.9, '0.217261,-0.414103,-0.353917,0.153491,-0.098409,0.314107,0.853650,-0.158377,-0.480876,-0.486802,0.682972,0.251257,0.139073,-0.206485,-0.026519,-0.163127,-0.133618,-0.646396,-0.300168,0.158714,-0.450982,-0.553870,-0.711141,-0.280863,0.283851,-0.186939,0.694311,0.229598,-0.312933,0.458855,0.277395,0.471111,-0.324059,0.277326,0.049230,-0.419846,-0.014662,-0.218315,-0.302152,0.124231,-0.135481,-0.436770,0.009848,0.181015,-0.199580,0.550290,0.835177,-0.153442,0.060814,-0.282289,0.276247,-0.441147,0.141200,0.152406,0.483784,0.108780,0.045461,0.250200,-0.218370,-0.124172,0.263278,0.085487,-0.930020,-0.223153,0.275795,0.232099,-0.228229,0.057139,0.140696,0.314972,0.174054,0.002887,0.398442,0.141034,0.377216,0.033700,-0.300663,-0.322676,-0.392677,0.032870,0.462560,-0.244968,-0.000645,-0.036962,-0.013300,-0.332718,0.111155,-0.222534,-0.042234,-0.072931,0.386695,0.235436,-0.307429,0.012401,-0.502564,-0.001555,-0.428158,0.090346,-0.258113,-0.120438,0.027665,-0.676123,-0.380328,-0.019936,-0.240959,0.029544,0.011102,-0.075284,0.440969,-0.364322,-0.018811,0.483290,-0.072652,-0.597706,-0.016176,0.099895,0.053636,-0.222853,-0.255500,0.161228,0.409842,0.465874,-0.184249,0.232383,-0.089995,-0.140782,-0.248414,-0.053684', '2988294', '26747274', '4280770', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26816372', '古剑奇谭之流月昭明', '动作', '长安少侠乐无异（王力宏 饰），为追寻偃甲大师谢衣（高圣远 饰）的下落，与富家公子夏夷则（高以翔 饰）和百草谷天罡战士闻人羽（宋茜 饰）在海市博卖行相遇，并意外牵涉进流月城大祭司沈夜（张智霖 饰）与心魔企图毁灭人类的惊天交易中。欲消灭心魔，必重铸昭明神剑，乐无异、闻人羽、夏夷则在谢衣的提示下，找到封印在画中的神秘少女阿阮（吴千语 饰），并同她一起踏上寻剑之旅。一场斩杀心魔，拯救苍生的正义之战就此展开……', '王力宏', '雷尼·哈林', 4.1, 8475, 'tt5806792', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2535268700.jpg', 35.5, 37.2, 18.4, 3.6, 5.3, '-0.001655,0.449396,-0.204604,0.475637,0.128037,-0.224386,0.415853,-0.066628,-0.162214,-0.210758,0.145894,0.290711,-0.050246,0.144146,0.328385,-0.016060,0.090577,-0.692034,-0.085448,-0.308291,-0.102938,-0.140430,-0.060623,0.034146,-0.103692,-0.358542,0.722696,0.453784,-0.120448,0.416690,0.227663,0.397831,-0.779212,0.511787,0.098775,0.110913,-0.263666,-0.004494,-0.411054,0.297721,-0.418188,0.047933,-0.389321,0.360672,-0.112101,0.201926,0.645485,-0.709472,0.302727,-0.510703,0.049460,-0.001074,0.168117,-0.034997,0.156416,0.202205,0.153853,0.233191,-0.246414,0.050800,0.339127,-0.190461,-0.316617,-0.084144,0.396522,0.042508,-0.109785,0.327213,-0.059979,0.402985,0.035488,-0.165484,0.219311,0.475526,0.669717,-0.049599,-0.095371,-0.223334,-0.273700,0.438161,0.491331,-0.116212,0.110137,-0.028130,0.286016,-0.479486,-0.363185,-0.031894,-0.143131,-0.176562,0.448404,0.004538,0.348563,0.441197,-0.441418,-0.329170,-0.238315,0.673791,-0.084006,-0.073884,0.055251,-0.461264,-0.011224,-0.072414,0.025120,-0.017356,0.291622,-0.351283,0.362287,-0.725962,0.230934,0.058833,0.229692,-0.238906,0.266969,-0.203057,-0.121503,-0.346020,-0.243823,0.555108,0.091494,0.458053,0.057287,0.141547,0.148319,0.284767,-0.309455,0.087389', '26759819', '1427947', '26767512', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26816376', '超级的我', '奇幻', '如果睡觉能赚钱，如果做梦能致富，但是要付出代价，你加入吗？18线小编剧桑榆（王大陆 饰）原本生活困顿拮据，但一夜之间却拥有了梦中取物的神奇能力，通过将梦中的宝物变现，潦倒落魄的他成为人生赢家，甚至一掷千金追求到暗恋多年的花儿（宋佳 饰），然而在梦中快意掠取的桑榆却逐渐发现，这场躺赢美梦竟将他的生活推向了失控的边缘……', '王大陆', '张翀', 4.8, 11414, 'tt10097544', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2639382329.jpg', 17, 38.7, 35.3, 7, 2, '-0.002730,0.551495,-0.505533,0.504767,-0.354856,-0.344071,0.500627,-0.159100,-0.524297,-0.193227,0.051056,0.537327,0.091619,0.312882,0.077671,0.162103,0.056587,-0.780245,0.215935,0.161193,-0.240629,-0.207985,-0.638404,-0.169332,-0.325325,-0.159227,0.803391,0.381890,-0.266451,0.154300,-0.001927,-0.083328,-0.010793,0.378632,-0.204366,-0.247095,-0.101311,0.664253,-0.465655,0.166181,-0.229111,-0.209169,-0.106679,0.098062,0.227291,-0.196447,0.430563,-0.453481,-0.032334,0.029948,0.437365,-0.382991,-0.333886,0.247703,-0.171537,0.135027,0.384993,-0.109937,-0.273633,-0.006999,0.174179,-0.040536,-1.062275,-0.092660,0.132214,-0.102574,-0.438796,0.184652,0.301321,0.015731,0.114104,-0.012783,0.324361,0.344443,0.591887,0.321331,-0.245814,-0.045397,-0.662935,0.460087,0.789102,-0.191899,-0.552424,0.543143,0.055643,-0.227595,-0.086525,-0.405025,-0.385080,0.125630,-0.069837,0.060238,-0.238211,0.421308,-0.369874,0.133966,-0.208572,0.109313,-0.139202,-0.392598,-0.428926,0.015765,-0.220468,-0.126501,-0.227571,0.108731,0.168552,-0.762170,0.495553,-0.741755,0.188205,0.446419,0.211539,-0.226012,0.512638,0.084019,0.008451,-0.054279,-0.130925,0.437170,-0.412920,0.143393,0.002719,-0.103809,-0.279484,0.124502,-0.435071,0.772855', '27098364', '6844861', '1793491', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26816383', '喜欢你', '喜剧', '一场意外让平凡的厨师顾胜男（周冬雨 饰）结识了霸道总裁路晋（金城武 饰）。之后，路晋入住了顾胜男所在的酒店，在并不知晓对方真实身份的情况下，顾胜男用一道“女巫汤”征服了路晋挑剔的味蕾，一位厨师和一位食客，两人在美食的联结下产生了奇妙的缘分。路晋的失眠症日益严重，一次偶然中，他发现自己竟然在顾胜男家的沙发上酣然入睡，从此，这张沙发便成为了他的专属床位。随着时间的推移，在一餐一饭之中，顾胜男和路晋之间渐渐产生了懵懂的感情。然而路晋在父亲严苛而又独裁的教育下长大，顾胜男则向来大大咧咧毛手毛脚，个性和身份迥异的他们压抑着内心的感情，由此生出了诸多的误会。©豆瓣', '金城武', '许宏宇', 6.7, 312265, 'tt6772874', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2455926001.jpg', 2.1, 10.8, 45.7, 32.5, 8.9, '0.519315,0.289940,-0.641178,0.648058,-0.288997,-0.223125,0.843533,0.273265,-0.408091,-0.301045,0.273981,0.758503,-0.351019,0.505777,0.383900,0.059750,-0.072501,-0.685722,-0.100221,-0.072023,-0.379925,-0.356848,-0.266096,-0.132861,-0.015995,-0.157222,0.546667,-0.021180,-0.269630,0.219327,0.380690,-0.098042,-0.193508,0.655503,0.016992,0.153659,0.174321,0.038780,-0.109024,-0.124097,0.173661,-0.444478,-0.037396,0.319701,-0.179242,0.178060,0.646389,-0.248086,-0.433577,-0.009900,0.380471,0.025462,-0.229988,0.338908,0.273439,-0.010483,0.007981,0.074305,-0.254027,0.131963,0.027886,0.337532,-0.439541,-0.026813,-0.261018,0.114579,-0.337484,0.574142,-0.069934,-0.329392,-0.172080,-0.247343,-0.080355,0.199636,0.359018,0.542359,-0.119023,0.125165,-0.245031,-0.034933,0.561802,0.550122,-0.260626,0.535504,-0.450897,-0.604199,-0.087319,-0.083022,-0.453641,-0.452372,0.318657,0.386322,-0.161666,0.211076,-0.529015,-0.003941,0.068844,0.029405,-0.104831,-0.125120,-0.142571,-0.479962,-0.364417,-0.594208,-0.420868,0.035095,0.159272,-0.231856,0.748091,-0.794660,0.079208,0.432492,0.191072,-0.250227,0.664427,0.100980,0.184135,-0.041938,-0.121495,0.060143,-0.097970,0.182470,0.269569,0.719446,-0.411372,0.126446,-0.365580,0.518763', '30162520', '1292062', '24756472', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26817016', '东京食尸鬼 真人版', '剧情', '性格内向只知道一门心思读书的大学生金木研（洼田正孝 饰），与偶然邂逅的美丽女孩神代利世（苍井优 饰）兴趣相投。谁知一段时间交往过后，利世竟露出可怕的面容，意图生吃掉金木。原来利世是一种名叫“喰种”的变异人种，他们将人类作为唯一食物。关键时刻，利世死于意外，而重伤的金木则被移植了来自利世的部分器官，却由此也变成了“喰种”的一员。康复后的金木再也无法摄入人类的食物，饱受饥饿困扰之际，他被在咖啡馆工作的董香（清水富美加 饰）介绍栖身于“喰种”群集的安全区。与此同时，CCG上等搜查官真户吴绪（大泉洋 饰）和部下全力追查“喰种”的行踪。人类和食尸鬼的战争一触即发……本片根据同名漫画改编。©豆瓣', '洼田正孝', '萩原健太郎', 5.8, 14066, 'tt5815944', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2480765579.jpg', 6.8, 25, 46.9, 15.2, 6.1, '0.192865,-0.217166,-0.380596,0.240150,-0.164189,-0.060215,0.514273,0.055909,-0.416603,-0.197627,-0.047776,0.590784,-0.022291,-0.045717,0.121612,-0.235582,-0.078353,-0.385490,-0.083735,0.020140,-0.194524,-0.091983,-0.390322,-0.254025,0.087105,-0.446466,0.768243,0.048645,-0.233493,0.439351,0.145461,0.565595,-0.291982,0.200556,-0.002850,0.020579,0.048540,0.029904,-0.123269,0.271217,-0.171315,-0.381591,-0.041384,0.000714,-0.015091,0.387130,0.968706,-0.354958,-0.483191,-0.335953,0.248654,-0.183978,-0.048509,0.168097,0.321796,-0.077273,0.024899,0.021169,-0.255529,0.097065,0.245852,0.087179,-0.669095,-0.201915,0.069839,0.189248,-0.197582,0.474278,0.236069,-0.086537,0.099398,-0.261669,0.150815,0.340342,0.376241,0.221194,-0.126048,0.028440,-0.312886,0.055654,0.548986,-0.114687,-0.314062,0.326007,-0.356015,-0.708480,-0.108508,-0.221901,-0.191516,0.025994,0.095103,0.482720,-0.334023,0.187371,-0.809911,-0.071633,-0.097197,-0.203974,0.179327,-0.114311,-0.187771,-0.502305,-0.193135,-0.178911,-0.316867,0.047006,0.387856,-0.151754,0.683804,-0.795071,0.225858,0.424908,0.264294,-0.349132,0.374050,-0.067205,-0.010049,-0.215864,-0.196894,0.297146,0.426287,0.252860,0.153645,0.415702,0.120824,-0.002563,-0.529316,0.160196', '25774050', '26759820', '10174444', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26817018', '今天的吉良同学', '喜剧', '高中女生冈村妮诺（饭丰万理江 饰）虽然渴望成为一个开朗乐观的女孩，然而现实生活中她始终无法与人顺畅自如交往。除了父母外，似乎只有那站在肩头假装标本并被她称为“老师”的鹦鹉（高桥茂树 配音）才是唯一说话对象。紧邻妮诺家的住宅里，住着一个帅气风趣的男孩，那就是与妮诺就读同一所学校的明星学生吉良悠二（中川大志 饰）。即便两人住得如此至今，但是性格有着巨大反差的两个人却从来没说过一句话，妮诺更不敢奢望与对方发生点儿什么。某天，妮诺从父母（安田显 & 三浦理惠子 饰）口中得知，吉良居然只剩下一年的生命了！紧接两人竟然阴差阳错成为了情侣。最后的365天，妮诺陪伴吉良同学一同走过……本片根据みきもと凜的同名漫画改编。©豆瓣', '中川大志', '川村泰祐', 6.8, 11421, 'tt5874398', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2390426887.jpg', 1.8, 9.6, 46.6, 29.2, 12.7, '0.331204,-0.108487,-0.522267,0.525511,0.048341,-0.316395,0.710656,0.080772,-0.492997,-0.501910,-0.050068,0.450287,-0.251278,0.340174,0.220283,-0.237325,-0.214775,-0.512665,0.008681,-0.093180,-0.084073,-0.479641,-0.091216,0.123716,-0.186859,-0.235966,0.621495,-0.026539,-0.040777,0.283113,0.160260,0.102644,-0.314060,0.366094,-0.107873,-0.000913,0.111338,0.308598,-0.142416,-0.022214,-0.216461,-0.051495,-0.227722,0.117137,-0.057203,0.268694,0.384851,-0.421229,-0.229557,0.035691,0.290526,0.112382,-0.191999,0.147701,0.252916,-0.279381,0.623117,0.076267,0.064255,0.071501,0.075987,0.062028,-0.549101,0.007421,-0.124653,0.264190,-0.269384,0.488043,0.135618,-0.245182,0.057197,-0.347565,0.011918,-0.011886,0.175804,0.249443,-0.551516,0.075323,-0.316147,0.134961,0.674528,0.199403,-0.356418,0.501207,-0.228085,-0.485155,-0.101782,-0.162380,-0.438520,0.287281,-0.193365,0.208484,-0.012057,-0.012219,-0.357238,0.029530,-0.091774,0.057455,0.196221,-0.448229,-0.114128,-0.423700,0.086532,-0.493386,-0.408199,0.133056,0.160280,-0.236345,0.797882,-0.882776,-0.017575,0.280884,0.272613,-0.031155,0.501220,0.232036,0.040084,-0.221524,-0.292238,0.311446,0.038974,-0.058551,0.148255,0.419707,-0.155773,-0.182124,-0.223691,0.249915', '35030151', '1395231', '1292219', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26818312', '情遇曼哈顿', '喜剧', '在《情遇曼哈顿》中，王丽坤饰演女一白淇，一名在纽约挣扎找机会的年轻演员。百老汇大制作《木兰歌剧》公开征选女主角，白淇面试非常出色，让白淇惊讶万分的是，与她争夺女主角的唯一对手，竟然是之前多次邂逅、颇有好感的宋苇东（高以翔 饰），一场竞争就此展开。', '王丽坤', '李巨源', 3.7, 5946, 'tt6518886', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2500046039.jpg', 41.1, 38.3, 16.2, 2.2, 2.2, '-0.140991,-0.126079,-0.803162,0.644560,0.126742,-0.109919,0.555533,-0.181076,-0.452200,-0.280363,0.373827,0.950836,-0.522445,0.025302,0.284832,-0.335584,-0.127908,-0.536307,-0.139554,0.113299,-0.042293,-0.290856,-0.633996,0.063441,-0.122387,-0.212891,0.995884,-0.050040,-0.535380,0.688119,0.685914,0.122747,-0.135915,0.235410,-0.062357,-0.223484,0.442708,0.492400,-0.316999,0.494095,-0.037144,-0.213893,-0.464019,0.194530,0.081905,0.546049,0.440516,-0.125208,-0.251149,0.266119,0.461414,-0.344594,-0.138374,0.032728,0.107337,-0.105128,0.373493,0.084631,-0.147484,-0.205012,-0.219056,-0.125985,-0.887606,0.425119,0.500970,0.186546,-0.558038,0.515994,0.048971,-0.112022,0.040056,-0.196621,0.145505,0.090993,0.291650,0.016633,-0.020221,0.057851,-0.327088,0.375239,0.695441,0.262911,-0.113680,0.423482,-0.049510,-0.504791,0.115716,-0.266764,-0.526575,0.289503,0.170395,-0.115079,0.289712,-0.083913,-0.461517,0.044008,-0.201057,0.057175,0.135329,-0.061769,0.328029,-0.913843,-0.138114,-0.309322,-0.269509,-0.290275,0.049991,-0.421429,0.735444,-1.027300,-0.059927,0.338447,0.352503,-0.513124,0.607357,0.514188,0.128368,-0.280143,-0.248782,-0.106398,-0.330404,-0.389288,-0.188222,0.227354,-0.149616,-0.584141,-0.492504,0.361999', '25880986', '4301278', '2369613', '24875409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26818314', '猛虫过江', '喜剧', '东北农村青年沈福（小沈阳 饰）与大雷（潘斌龙 饰）遇见南方姑娘静香（宋芸桦 饰），机缘巧合来到陌生大城市，面对从天而降的巨额遗产和随之而来的种种危机，两人接连施展令人意想不到的“独门秘籍”，引发了一连串爆笑喜剧故事。', '小沈阳', '小沈阳', 3.7, 42905, 'tt8793220', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2523437699.jpg', 44.6, 33.7, 16.1, 2.9, 2.8, '0.053348,-0.359280,-0.472301,0.511939,0.502582,0.413136,0.469050,0.036280,-0.627608,-0.509177,0.332677,0.817193,-0.564105,0.176641,0.310617,-0.310514,0.024383,-0.253096,0.051473,0.063676,-0.183272,0.021918,-0.179261,-0.132068,-0.189503,-0.173268,0.225053,0.433219,-0.705388,0.670016,0.315806,0.594251,-0.760197,0.091794,-0.268191,0.337567,-0.105287,0.483840,-0.227570,0.030932,0.040280,-0.371066,-0.094077,0.156427,-0.049536,0.083655,0.715338,-0.321295,0.009844,-0.094693,0.427804,-0.005926,-0.334471,-0.173231,-0.171659,0.156338,0.557812,0.000129,-0.144499,-0.228519,0.289716,-0.112734,-0.169901,0.340018,0.358791,-0.146260,-0.041616,0.158088,0.020142,-0.232725,0.306798,-0.396847,0.061250,0.252179,0.531824,0.444034,-0.365524,0.058036,-0.176830,0.281314,0.425600,-0.254604,-0.318840,0.221771,-0.007909,-0.462587,0.109993,-0.192751,0.021910,0.474588,0.364764,0.085465,0.230334,0.344619,-0.690954,0.124064,-0.254717,0.038844,-0.093804,-0.107767,-0.695098,-0.747933,-0.139401,-0.184136,-0.178526,0.401342,0.222329,0.406574,0.752354,-0.368963,-0.128011,-0.163094,0.356009,-0.063154,0.046730,-0.507658,0.079561,-0.354103,-0.165594,0.046905,0.053833,0.037541,-0.190369,0.107283,-0.300441,-0.023351,-0.097841,0.157273', '10466639', '5403927', '3811356', '26788667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26818326', '西游记之再世妖王', '动作', '混沌初开之时，世上的第一只妖降世，名元蒂（张磊 配音），被奉为妖祖。千百万年后，昔日妖王孙悟空（边江 配音）被唐僧（苏尚卿 饰）从五行山下救出，悟空答应保护唐僧，前往西天取经。而传说中的妖祖元蒂再次现世，三界岌岌可危。两代妖王注定终极一战，但这次，孙悟空遇上了真正的劲敌。', '边江', '王云飞', 5.3, 20543, 'tt14391088', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2673991933.jpg', 9.1, 30.9, 47.6, 9.7, 2.7, '-0.155941,0.559132,-0.752995,0.589329,0.100915,-0.202010,0.098999,-0.240051,-0.503566,-0.204894,0.067980,0.888178,-0.211450,0.006668,0.233502,0.022438,0.598199,-0.269805,-0.009096,-0.189599,0.100670,0.347820,-0.428024,0.466232,-0.404235,-0.407816,0.841061,0.135926,0.190526,0.142770,0.175658,0.075292,-0.371656,0.396705,-0.241288,0.085651,-0.367435,0.246275,0.045593,0.431125,-0.354741,-0.165639,-0.041800,0.515965,-0.599543,0.102894,0.047091,-0.932859,-0.017917,-0.605928,0.416922,-0.586246,-0.358033,0.144901,0.657713,-0.125628,0.366157,0.609224,0.208744,-0.152856,-0.121292,-0.116617,-0.551053,-0.021892,-0.101321,-0.134152,-0.300277,-0.075354,0.275405,0.249093,0.155685,-0.155133,0.526096,0.443073,0.727107,0.116539,-0.055298,-0.285971,-0.319217,0.158765,0.834748,-0.428064,0.256084,0.158155,0.826868,-0.601377,0.044657,-0.359033,-0.039057,0.525234,0.471710,0.078273,0.124816,0.337445,-0.667923,-0.434277,-0.461513,0.328147,-0.330582,-0.218523,-0.030886,-0.326907,0.106130,0.224295,-0.096097,-0.413032,0.647299,-0.157965,0.736659,-0.691121,0.281466,0.170301,-0.095312,-0.311416,0.798718,-0.249252,0.526190,-0.445094,0.344574,0.200401,0.226240,0.738701,0.050147,0.076399,-0.166708,0.247321,-0.306462,0.127357', '19899707', '25827286', '26290398', '34779692');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26820450', '我被爸爸绑架了', '剧情', '一年一度的暑假终于到来了，小学生们欢天喜地，规划着多姿多彩的假期生活。不过女孩小春（丰岛花 饰）却有些闷闷不乐，两个月前妈妈（木南晴夏 饰）和吊儿郎当的窝囊废爸爸（妻夫木聪 饰）大吵一架，夫妻处于分居冷战状态。白天妈妈还要上班，虽然有时会将小春托付给妹妹裕子（夏帆 饰）照看，但多数时候还是小春孤零零一个人打发无聊漫长的时光。就在暑假第一天，发生了一件了不得的事。久未谋面的爸爸突然出现，带着女儿四处玩耍，并且半开玩笑半认真地说要绑架女儿。小春打心眼里瞧不起一事无成的废柴老爹，不过她还是和爸爸踏上了多姿多彩的绑架之旅……本片根据角田光代的原作改编。©豆瓣', '妻夫木聪', '岸善幸', 7.7, 9841, 'tt5815946', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2376420827.jpg', 0.2, 2, 29.5, 49.6, 18.7, '-0.069768,-0.324047,-0.527014,0.003148,-0.203802,-0.559022,0.474251,0.088987,-0.495513,-0.379477,0.106962,0.432676,-0.359462,0.535076,0.374722,0.174151,-0.528393,-0.516659,-0.059882,-0.058904,-0.128708,-0.436445,0.063873,0.043489,-0.113144,-0.005778,0.232175,-0.194856,0.282656,0.583894,0.055448,-0.076326,-0.221285,0.380268,-0.244536,0.042677,0.118108,0.333564,-0.195966,-0.089852,0.027722,0.062162,-0.316066,-0.232189,0.459026,0.122329,0.690346,-0.145807,-0.269939,0.022268,0.316953,-0.250042,-0.449490,-0.033692,0.361075,0.142591,0.590434,-0.055292,-0.102966,0.015617,0.040063,-0.344003,-0.205376,0.481593,0.184907,-0.037614,-0.464584,0.604068,0.218664,0.110025,0.356163,-0.585391,0.196904,0.584303,0.073348,0.658491,-0.108758,0.217998,-0.281921,0.281904,0.343504,-0.093918,-0.093966,0.512450,-0.012555,0.196379,0.258506,-0.277892,-0.697369,0.102657,-0.113602,-0.187902,-0.357397,0.233048,-0.496599,0.229645,0.026007,-0.023936,0.198362,-0.371227,-0.272714,-0.230770,0.224080,-0.600478,-0.454080,0.096113,0.143941,-0.219939,0.570639,-0.778325,0.446529,0.275329,0.236431,-0.301201,0.455487,0.345058,0.038756,-0.306447,0.159833,-0.039669,-0.321674,0.343815,0.209592,0.295483,0.067227,-0.066062,-0.460163,0.335794', '1292219', '1306544', '1304942', '3041753');
