INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26820769', '红鞋子和七个小矮人', '喜剧', '该片由韩国导演宋浩宏自编自导。影片是个现代版白雪公主的故事，她会遇到七个丑陋的小矮人，而实际上他们原本是几个虚荣又傲慢的王子。', '科洛·莫瑞兹', '宋浩宏', 7.6, 18377, 'tt4429160', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2593734431.jpg', 0.5, 2.4, 29.4, 50.6, 17.1, '0.222665,-0.120742,-0.427212,0.922643,-0.244833,0.114913,1.283725,0.100423,-0.352091,-0.232924,0.521745,0.943360,-0.197898,0.410728,-0.166652,0.164607,-0.231511,-0.191142,-0.417833,-0.060995,0.207888,-0.200690,-0.303615,-0.452323,-0.189375,-0.363361,0.520010,-0.411909,-0.371357,0.247607,1.131765,0.031117,0.150596,-0.058494,-0.283223,0.261861,0.002720,-0.214567,0.398873,0.146994,-0.026042,-0.109056,-0.353232,0.075826,-0.244778,0.529971,0.866983,-0.082867,-0.058840,-0.184164,0.598578,-0.540220,-0.355360,0.090691,0.283991,-0.353724,0.679436,0.139617,0.077111,-0.035787,0.175959,-0.237384,-0.813755,0.466493,0.049688,0.444049,-0.385329,0.406219,0.149855,-0.159798,0.303386,-0.284304,-0.001570,-0.245778,0.573645,0.355484,0.321645,-0.119812,-0.540644,0.499665,0.931708,0.367241,-0.614878,0.611902,-0.161481,-0.642259,-0.033769,-0.527589,-0.511072,0.442355,0.248800,-0.789353,-0.076059,0.150710,-0.824124,0.203780,-0.309605,0.123572,-0.118895,-0.574540,-0.047105,-0.409973,-0.180983,-0.486345,-0.058013,0.002795,0.125559,-0.123469,1.219564,-0.488181,-0.027509,0.713973,-0.087147,-0.833586,0.631767,0.411196,-0.389551,-0.066252,0.055575,-0.164990,-0.120103,-0.268557,-0.193233,0.482894,-0.203019,-0.558763,-0.552321,0.492954', '4181031', '2053515', '1299767', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26820833', '中邪', '惊悚', '大学生丁鑫和刘梦为拍摄农村风俗纪录片进入一个村落，在目睹了充满诡异气息的 “还人”仪式后，两人跟随“高人”王婆夫妇来到一处偏远的山庄拍摄驱邪过程。然而 事情却向更加诡异的方向发展，驱邪四人组经历着人性的考验，生命岌岌可危，而所发 生的一切都被丁鑫和刘梦的摄影机默默记录着......©豆瓣', '董天文', '马凯', 6.8, 62440, 'tt5938816', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2517482882.jpg', 2.9, 9.6, 41.1, 38, 8.4, '0.155486,-0.363684,-0.588155,0.768048,0.210456,0.079805,0.726134,0.124414,-0.488130,-0.337975,0.251601,0.603145,-0.393433,0.150163,0.335506,-0.159510,-0.331971,-0.560096,-0.437626,0.086766,-0.309334,-0.187930,0.146767,-0.236879,0.016928,-0.477111,0.586393,0.496191,-0.183881,0.316105,0.014624,-0.065164,-0.853643,0.458423,-0.291841,-0.019503,0.050376,0.100272,-0.263952,0.176922,0.008923,-0.289087,-0.459328,0.139555,-0.188771,0.271640,0.855071,-0.119921,-0.443547,0.036552,0.254431,-0.330160,-0.155586,0.186357,0.202414,0.092889,0.259258,0.338937,0.034637,0.075537,-0.085555,-0.436086,-0.596704,0.080939,0.052155,0.237976,-0.616305,0.596144,0.133151,-0.168497,0.005279,-0.640051,0.456413,0.163227,0.214798,0.549331,-0.395836,-0.180803,-0.446763,0.214947,0.630929,-0.021659,-0.395058,0.430645,-0.069700,-0.672791,-0.314533,0.128386,-0.625349,0.127376,0.225959,0.116852,-0.207752,0.204095,-0.778632,0.207526,0.078162,-0.427482,0.055844,-0.473503,-0.196636,-1.107905,-0.128316,-0.173812,-0.420035,0.148616,-0.074217,-0.274214,0.679101,-0.527088,0.240999,0.393429,0.055379,-0.364937,0.649206,-0.362086,0.182586,-0.376888,-0.415040,0.247945,-0.035076,0.679550,0.112417,0.388081,-0.544061,-0.016517,-0.311027,0.484081', '10466639', '1307897', '1294917', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26820836', '八月', '剧情', '九十年代初的西部小城，结束了小升初考试的张小雷（孔惟一 饰）终于迎来了盼望已久的没有作业的暑假。然而这个自由的，炎热的夏天并不是想象中那样红火热烈，更多是平常反复的家庭生活和大把闲工夫。恰逢那一年国家开始实施国有单位转型，铁饭碗被打破，张小雷父亲（张晨 饰）的单位也受到改革冲击，他们生活的家属院 里每一个家庭的生活都被改革影响着。孩子们整日百无聊赖，而看似平静的大人们，心却像烈日炙烤着那般燥热。张小雷就那么静静的耗着，感受着身边隐隐发生的一切。直到父亲为了生活同其他人远走他乡，家里只剩下了母子俩，张小雷才着实感觉到时间过去了，生活不一样了。立秋那天夜里，张小雷家的昙花在院子里悄然开放，像是意味着什么……', '孔维一', '张大磊', 7.1, 36933, 'tt6118258', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2448419180.jpg', 0.7, 5.8, 41.9, 42.2, 9.3, '0.316445,0.059919,-0.882687,0.356014,-0.097281,-0.158398,0.692120,0.324645,-0.635213,-0.389972,-0.097988,0.415821,-0.339690,0.487795,-0.026895,-0.069908,-0.225832,-0.683894,-0.242093,0.054099,-0.129675,-0.288049,-0.004772,0.067627,-0.162535,-0.011011,0.460181,0.313340,-0.003107,0.310478,0.014047,-0.216749,0.268618,0.687897,-0.299368,-0.212296,-0.039735,0.283684,-0.131145,-0.044243,0.096637,-0.153358,-0.266923,0.148649,0.248186,0.262135,0.530600,-0.185719,-0.349836,-0.327398,0.548042,-0.114230,-0.246761,0.112693,0.364559,0.231780,0.217993,0.166341,-0.100484,0.170876,-0.059412,-0.409712,-0.397403,0.223731,0.039517,0.317481,-0.477025,0.628856,0.255505,-0.222391,-0.015459,-0.261900,0.369780,0.469692,0.140102,0.612765,-0.525169,-0.087040,-0.695973,0.315258,0.887277,-0.060587,-0.630480,0.540401,-0.411404,-0.224670,-0.050452,-0.157668,-0.448597,-0.188043,-0.068919,0.177972,-0.584244,0.440459,-0.451915,0.548360,-0.010224,-0.471537,0.060744,-0.462990,-0.160547,-0.653554,0.043963,-0.512954,-0.520079,0.326081,-0.012077,-0.330072,0.711971,-0.741707,0.287355,0.493419,0.588579,-0.129594,0.400465,0.059926,0.274459,0.133426,0.250825,0.192587,-0.287419,0.467370,0.300880,0.332483,-0.457880,0.016167,-0.212100,0.750123', '1870682', '25721544', '4275444', '21447058');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26822230', '摩天轮', '剧情', '哈姆迪（吉姆·贝鲁什 Jim Belushi 饰）和妻子金妮（凯特·温丝莱特 Kate Winslet 饰）一起在游乐场生活和工作，金妮有过一段婚姻，两人共同抚养着金妮和前夫所生的孩子。一天，哈姆迪的女儿卡洛琳娜（朱诺·坦普尔 Juno Temple 饰）找到了父亲，她曾经执意嫁给黑帮大佬，如今正在遭受黑帮的追杀。虽然女儿从前的所作所为令哈姆迪十分生气，但卡洛琳娜的浪子回头显然让哈姆迪开始想要修复这段破碎的父女关系。与此同时，金妮邂逅了海滩救生员米奇（贾斯汀·汀布莱克 Justin Timberlake 饰），两人之间碰撞出了爱情的火花。金妮想要抛弃一切同米奇在一起，然而，在看到了卡洛琳娜之后，米奇不可自持的移情别恋了。©豆瓣', '凯特·温丝莱特', '伍迪·艾伦', 7.2, 30317, 'tt5825380', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2504864722.jpg', 0.5, 4.1, 41.9, 41, 12.5, '0.328180,-0.147029,-0.731655,0.455599,-0.057224,-0.638106,0.781423,0.296360,-0.715190,-0.202417,0.054974,0.562119,-0.308137,0.349753,0.414818,0.224722,-0.453877,-0.715263,0.024261,-0.306425,-0.091202,-0.865801,-0.198055,-0.119015,-0.116668,-0.490383,0.266195,-0.397287,0.225581,0.665191,0.359556,0.187536,-0.207253,0.270804,0.215369,0.177358,0.245751,0.223838,-0.619408,-0.008145,0.282711,0.162733,-0.057677,-0.036878,0.177878,0.170592,0.447780,-0.292066,0.443396,-0.334285,0.266204,-0.082866,0.213499,0.207886,0.353114,-0.311602,0.252957,0.166419,-0.130817,-0.211092,0.440913,0.037940,-0.406593,0.046767,0.083802,0.197501,-0.776810,0.453646,-0.204427,-0.088080,0.465007,-0.439433,0.027048,0.553657,0.251624,0.313842,-0.172618,-0.060665,-0.602218,-0.015874,0.730939,0.112920,0.027541,0.152227,-0.410209,-0.167505,-0.333305,0.009286,-0.649979,0.023856,0.602240,0.061109,-0.154700,0.684533,-0.469354,-0.453048,-0.273399,-0.020469,0.175812,-0.559748,0.100429,-0.806804,-0.182639,-0.538944,-0.223924,-0.047089,-0.209646,-0.278297,0.497923,-0.837075,0.341879,0.385934,0.305544,-0.002000,0.410737,0.352591,0.454519,-0.222801,0.044299,0.431911,0.148256,-0.027919,0.236371,0.136299,0.218341,0.253585,-0.376645,0.383080', '1291856', '26971054', '33441781', '1297239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26822683', '勇士', '动作', '电影《勇士》以红军长征途中强渡大渡河，飞夺泸定桥的英雄史实为原型，展现勇士们在敌人的围追堵截中大智大勇，挑战生死关口的非凡经历。李东学在片中饰演率领22名突击队员的黄开湘团长，他与战士们穿越枪林弹雨的围剿，突破天险飞夺泸定桥，以血肉之躯粉碎了国民政府的阴谋，在中国革命史上谱写了不朽的一页篇章。在勇士们心中，黄开湘团长不但是并肩作战的战友，更是带领他们击败困难的“战神”。', '李东学', '宁海强', 5.2, 4106, 'tt7730204', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2390260819.jpg', 23.4, 24.5, 28.1, 15.6, 8.3, '0.244844,-0.353436,-0.534542,0.741202,0.360377,-0.060004,0.347773,-0.130867,-0.287797,0.244693,0.931783,0.702490,0.261415,-0.422618,0.369273,-0.704747,-0.242675,-0.952421,-0.179148,0.016163,-0.205109,-0.201437,-0.544481,0.158531,0.047110,-0.426061,1.021946,-0.026882,-0.348757,0.502419,0.101770,0.252038,-0.202624,0.235297,-0.199697,0.146831,0.107630,-0.387696,-0.400636,0.044493,-0.554482,-0.273541,-0.489006,0.037331,-0.314091,-0.011621,0.675567,-0.622014,0.187131,-0.039307,0.078663,-0.562403,0.137681,0.106676,0.320362,0.224985,0.121989,0.247178,0.613882,0.001092,-0.418015,-0.140238,-1.056399,-0.370608,0.207591,0.248288,-0.834601,0.546706,-0.016969,0.401541,0.316965,0.081043,0.089767,0.383562,0.088180,0.231574,-0.372704,-0.216556,-0.567518,0.541867,0.896007,-0.026944,-0.221876,-0.298973,0.015377,-0.349788,-0.124664,-0.441552,-0.626565,0.182650,0.081864,-0.255320,0.233149,0.360857,-0.959182,-0.016622,-0.511021,0.030162,-0.205894,-0.069775,-0.143702,-0.526736,-0.324853,-0.118133,-0.185890,0.127752,0.065040,-0.178136,1.249127,-0.708435,-0.145345,0.181540,0.249488,-0.086377,0.955964,0.336823,-0.096180,0.006933,0.230098,0.195986,-0.176000,0.459130,0.091973,0.441534,-0.431927,0.008089,-0.324674,0.413822', '27602116', '6101834', '1302661', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26823502', '隐秘的生活', '剧情', '泰伦斯·马力克继1998年《细细的红线》后，将再次执导二战题材影片。新片取材自真实历史事件，讲述奥地利士兵弗兰茨·杰格斯泰德(奧古斯特·迪赫饰)因在二战时期拒绝为纳粹德国而战，最终被判死刑。据称这将是一部与《细细的红线》风格完全不同的二战影片。该片今夏德国开机。', '奥古斯特·迪赫', '泰伦斯·马力克', 7.7, 11184, 'tt5827916', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2565607356.jpg', 1, 4.8, 27.1, 43.3, 23.7, '-0.245731,0.242184,-0.218615,0.705928,0.992737,-0.141945,0.543552,-0.341650,-0.422611,-0.368413,0.068200,0.876178,-0.485935,-0.373142,0.305004,0.019275,-0.776679,-0.850637,-0.041396,-0.080892,-0.154353,-0.453306,-0.155984,-0.049058,-0.044104,-0.270247,1.054138,-0.049773,-0.269690,0.537066,0.434379,0.352854,-0.073767,-0.220020,0.200962,0.233618,-0.024719,-0.409362,-0.607125,-0.037276,0.072956,-0.446062,-0.086114,0.069174,-0.104703,0.395357,0.658923,-0.508576,0.133979,-0.166342,0.758994,-0.224420,-0.173163,0.181164,0.218642,0.574857,0.286912,0.523668,0.126983,0.003760,-0.277693,-0.462698,-0.304986,-0.133941,-0.116162,0.168539,0.096910,0.318744,-0.526144,0.234094,-0.297989,-0.178278,0.102516,0.101850,0.792387,0.338981,-0.134854,-0.054837,-0.154627,0.571939,0.238499,0.010475,-0.151765,0.333769,-0.078295,-0.228820,-0.181472,-0.416101,-0.022355,0.460873,0.316232,-0.218528,0.049239,0.462911,-0.760642,-0.250614,-0.490577,-0.358904,0.234664,-0.083602,-0.017356,-0.716762,-0.478615,-0.212099,-0.225338,-0.422866,0.053842,-0.252042,0.383678,-0.227266,0.113722,0.397055,0.082875,-0.022950,0.494325,0.153717,0.154298,-0.067458,0.298995,0.738409,-0.013726,-0.124225,0.051239,0.190546,0.026726,-0.252790,-0.157509,0.215048', '1780122', '1303390', '26990609', '26979208');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26823520', '日常幻想指南', '喜剧', '改编自网络同名人气连载漫画，电影讲述了男主角阿震（王彦霖 饰）在一次意外后竟获得了和静物沟通的超能力，这个能力让他的生活发生了翻天覆地的变化，就在这时阿震重逢了学生时代的初恋草莓（焦俊艳 饰）……生活陷入混乱的阿震为了回归原本的生活，与静物们展开了一段精彩故事……', '王彦霖', '梁栋', 4.9, 12828, 'tt15465908', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2681329662.jpg', 14.6, 39.3, 35.8, 8.4, 2, '0.098813,0.082913,-0.598017,0.742757,0.397067,-0.248037,0.952732,0.235021,-0.529941,-0.293052,0.002489,0.688274,-0.580393,0.118402,0.345207,-0.341419,-0.640045,-1.060989,0.222853,-0.022266,-0.202767,-0.075568,-0.384507,-0.271683,0.029288,-0.702543,0.900609,0.109144,-0.583692,0.601561,-0.045135,-0.117623,-0.247686,0.239772,-0.162704,0.302755,0.090129,0.456734,-0.587843,0.155938,-0.083229,-0.339340,-0.127829,0.186177,0.031597,-0.068585,1.256810,-0.311257,-0.554838,0.260002,0.840062,-0.080027,-0.288018,-0.150813,0.121793,0.173464,0.208025,0.030101,-0.110481,0.269191,-0.204699,-0.294395,-0.866438,0.082131,-0.053262,0.362422,-0.548110,0.443814,0.077534,-0.212135,0.021767,-0.114926,0.295914,0.606875,0.908642,0.485761,-0.056677,0.202201,-0.170987,0.554079,0.838469,-0.019379,-0.449623,0.932905,-0.267172,-0.276866,-0.740060,0.039069,-0.443678,0.203550,0.271920,-0.009878,-0.311071,0.596547,-0.833451,0.048999,0.137456,-0.443613,0.065650,-0.243705,-0.255394,-0.883492,-0.485845,-0.220214,-0.220546,-0.196348,-0.003718,-0.573047,1.181833,-0.795461,0.179670,0.326491,0.009656,-0.685585,0.672284,0.257162,-0.045162,-0.210333,0.258823,0.253775,-0.306456,0.215353,0.014001,0.339599,-0.028993,-0.043580,-0.603270,0.767473', '3811356', '5403927', '26759820', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26825482', '月球陨落', '科幻', '月球开始偏离轨道，离撞上地球的时间线越来越近，危机时刻，美国国防部提出使用核弹，来让月球重新回到正常轨道。但“假冒博士”（约翰·布莱德利饰）发现，月球内部是空的，显然是有外星文明在操控着月球的轨迹。这个计划逐渐被两位宇航员（帕特里克·威尔森和哈莉·贝瑞饰）接受，但前者因为多年前的一起太空事故，已被美国国家航空航天局开除，关键时刻，已经升为负责人的后者拍板，决定用一台被废弃在博物馆中的航天飞船再次升空飞往月球，借助前者超强的驾驶经验，深入月球地心完成任务。', '哈莉·贝瑞', '罗兰·艾默里奇', 5.4, 101966, 'tt5834426', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2869422067.jpg', 9.3, 30.7, 43.2, 13, 3.8, '0.286582,0.597498,-1.069446,0.498436,-0.090073,-0.094101,0.434451,-0.255598,-0.343509,0.021987,0.049969,0.777330,-0.243399,0.031939,0.220619,0.280449,-0.535332,-0.318328,0.003018,-0.121446,-0.686713,-0.781528,-0.191787,-0.136871,-0.083729,-0.289065,1.012248,0.295617,-0.042085,0.260368,-0.117968,0.369963,0.001358,0.416797,-0.151886,-0.244856,0.011768,-0.213613,-0.249877,0.383692,-0.136963,-0.053783,0.301463,0.055838,-0.072160,0.523922,0.715574,-0.045246,-0.144140,-0.291689,0.347733,-0.368846,0.025537,-0.111017,0.676534,0.563130,-0.628760,0.024938,-0.283640,0.216054,0.175446,-0.203581,-0.506400,-0.079394,-0.243515,-0.259290,-0.423142,0.067439,-0.435140,-0.047834,-0.190769,-0.453408,0.397568,0.367117,0.368476,0.131955,-0.366925,0.210010,-0.253002,-0.319438,0.497881,0.102449,-0.726509,0.426505,0.104429,-0.324696,-0.299680,-0.301027,0.162269,-0.261129,0.125626,0.225988,-0.160783,0.305123,-0.651177,0.388991,-0.568843,-0.340915,-0.095160,-0.291417,-0.105931,-1.062777,0.058849,-0.215452,-0.167947,0.084286,-0.133982,-0.357244,0.420034,-0.550935,0.241897,0.554160,0.321926,-0.330459,0.625932,-0.103997,0.196580,-0.532624,0.331590,0.016145,-0.142845,0.660063,-0.193980,0.182786,0.033209,-0.156496,-0.420906,0.434502', '3871833', '2369613', '27073291', '1303447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26825664', '修女', '悬疑', '远在罗马尼亚乡间的一所修道院发生修女自杀事件。为此，梵蒂冈委派伯克神父（德米安·比齐尔 Demián Bichir 饰）和见习修女艾琳（泰莎·法米加 Taissa Farmiga 饰）前去调查。抵达目的地后，他们首先找到了定期给该修道院运送物资的法国青年弗兰切（乔纳斯·布洛凯 Jonas Bloquet 饰），而他正是第一个发现修女尸体的目击人。三人进入修道院，里面的气氛阴森鬼魅，修女们则飘忽不定，有如幽灵。看不见面容的修道院长称修女们正在静默祈祷，第二天才能回答他们的问题。无奈之下，伯克神父一行只好暂时在修道院落脚。可是随着夜幕降临，真正的恐怖开始浮现，恶魔对虔诚的信仰展开了毫无差别的狙杀……©豆瓣', '德米安·比齐尔', '科林·哈迪', 6.1, 54475, 'tt5814060', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2528357976.jpg', 3.2, 20.8, 52.2, 17.6, 6.2, '0.251434,-0.129208,-0.469675,0.325318,0.199769,-0.180481,0.846392,0.095835,-0.222007,-0.528879,0.278110,0.723884,-0.136791,0.136847,0.501774,-0.014159,-0.707934,-0.511088,-0.186539,-0.453831,-0.268148,-0.544123,0.066764,-0.439089,0.065735,-0.427848,0.368138,0.216103,0.182815,0.401931,0.251320,0.484964,-0.471757,0.178243,-0.000502,-0.311790,0.404553,-0.319329,-0.143777,0.121851,-0.085241,-0.057739,-0.291143,0.149786,0.035883,0.430584,0.655810,-0.310763,-0.156363,0.006828,0.041724,-0.175699,0.179146,0.365853,0.283788,-0.025771,-0.071458,0.013676,-0.000143,0.212735,-0.109968,-0.183830,-0.359991,0.195909,0.149576,0.253813,-0.456451,0.235395,0.182892,-0.091047,0.411413,-0.295099,0.334296,0.185652,0.096957,0.478745,0.021348,0.018329,-0.512247,-0.017326,0.263745,-0.042879,-0.339052,0.121769,-0.161447,-0.537118,0.133643,0.119881,-0.056156,-0.029035,0.247407,0.222568,-0.016831,0.022644,-0.609880,-0.383065,-0.470546,-0.375439,-0.220754,-0.168810,-0.238130,-1.014153,0.150392,-0.053893,-0.098865,0.258049,-0.237088,0.211732,0.431875,-0.655175,0.518313,0.496922,0.207197,-0.134050,0.442246,-0.219039,0.212794,-0.150700,-0.073463,0.409294,0.269276,0.685821,0.066025,0.168329,-0.173084,-0.145767,-0.163585,0.171115', '1297659', '10466639', '6517421', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26826330', '刺杀小说家', '动作', '异世界皇都，天神赤发鬼残暴统治，滥杀无辜。少年空文因被赤发鬼追杀，决定奋起反击。在黑甲（郭京飞 饰）的指引下，踏上了凡人弑神之路。这是小说家路空文（董子健 饰）笔下的奇幻世界。没想到小说的进程，竟然影响着现实世界。这时一名男子（雷佳音 饰）接下了刺杀他的任务……', '雷佳音', '路阳', 6.5, 617977, 'tt9685342', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2628440875.jpg', 3.1, 13.1, 44.9, 32.1, 6.7, '-0.007812,0.499956,-0.284538,0.496594,0.089252,0.079639,0.219906,0.337666,-0.241748,-0.350013,0.657386,0.322575,-0.099738,-0.332424,0.516224,-0.221608,-0.038060,-0.263463,-0.202102,-0.165235,-0.397850,-0.037948,-0.458376,0.084268,0.011504,-0.787808,0.571125,0.447468,-0.440802,0.148638,0.422767,0.538713,-0.347303,0.335412,-0.096394,-0.048807,0.169245,-0.102657,-0.032158,0.288775,-0.563446,0.010014,-0.217906,0.632866,-0.821123,0.037984,0.613609,-0.651161,-0.172775,-0.612447,0.509013,-0.209458,-0.107565,-0.258793,0.200473,-0.124797,0.085569,0.487202,0.383967,0.165249,-0.101291,-0.079913,-0.558951,0.149184,0.236398,0.322164,-0.380771,0.114580,-0.160321,0.224697,-0.110075,-0.261605,-0.238882,-0.036729,0.947727,0.235551,0.161818,0.056471,-0.336347,0.271140,0.248624,-0.010637,-0.322367,0.163367,0.115284,-0.167999,-0.504304,-0.008752,-0.245572,-0.213501,0.343946,-0.021547,-0.455367,0.439814,-0.317536,-0.064922,-0.236882,0.330741,-0.139647,-0.139131,-0.551884,-0.273734,0.245952,0.094626,-0.120959,0.103662,-0.119383,0.097742,0.781341,-0.414683,0.226196,0.713248,0.327821,-0.410759,0.667478,-0.063732,-0.386554,-0.432004,0.059216,0.354389,0.288414,0.537911,-0.007446,0.108365,-0.336367,-0.061293,-0.287760,0.758469', '6844861', '26944582', '27607392', '1292347');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26826398', '杀破狼·贪狼', '剧情', '香港警察李忠志（古天乐 饰）得知女儿芝（陈汉娜 饰）于泰国旅游间莫名失踪，即亲赴泰国报警求助。负责案件的华人探员崔杰（吴樾 饰），应允让他一同调查，却想不到李忠志利用媒体呼吁市民提供线索。 一条意外拍下芝被捉走的片段上载至警方网站，却被神秘删除。崔杰即连同好友兼同袍Tak（托尼·贾 饰）同赴寻找片主，却遇神秘人马截足灭证，狭路相逢，展开追截并与之搏斗。李忠志与崔杰两人逐步调查，却发现案中有案，并开始意识凶手背后神秘势力非他们能对付……', '古天乐', '叶伟信', 7, 164924, 'tt7245176', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2494948513.jpg', 1, 6.6, 43, 39.4, 9.9, '0.241665,-0.129743,-0.394363,0.334306,0.387519,0.104098,0.393071,-0.056366,-0.554036,-0.380981,-0.223234,0.378127,-0.251398,-0.043862,0.111339,-0.328624,-0.170278,-0.710674,0.143990,-0.107684,-0.010781,-0.328453,-0.380468,-0.281217,0.029507,0.047525,0.365827,0.305499,-0.308070,0.737707,0.255443,0.444614,-0.949264,0.643652,0.130802,-0.327946,0.301876,0.168258,-0.415272,0.023403,-0.114816,-0.561568,0.116901,0.002868,-0.108527,0.479797,0.509315,-0.051237,-0.101457,-0.224150,0.177621,-0.151325,0.126785,-0.007911,0.357535,0.247050,0.135530,0.381895,-0.066756,-0.261926,0.044813,0.041058,-0.526938,0.182241,0.306592,0.318170,-0.067748,-0.191003,-0.383429,0.318381,-0.178496,-0.100813,0.323862,0.283473,0.222204,-0.012860,0.262396,-0.081277,-0.223413,0.226349,0.475128,-0.134400,0.204173,-0.288687,0.041672,-0.497369,0.356401,0.224415,0.156025,0.171850,0.312818,0.111280,0.072947,0.052991,-0.286204,-0.257460,-0.513273,0.263574,-0.077262,-0.347765,0.193724,-0.893452,-0.080489,0.137686,-0.148052,0.288686,0.151949,-0.228395,0.141497,-0.490472,-0.122061,0.633723,0.403609,-0.890051,0.374624,0.037007,0.032429,-0.501907,-0.097932,0.149415,0.463504,0.220934,0.096498,-0.177572,-0.257377,-0.339488,-0.216618,-0.379488', '1295106', '1301257', '4190211', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26827040', '英雄本色2018', '剧情', '周凯（王凯 饰）参与走私，被身为缉毒警察的弟弟周超（马天宇 饰）逮捕入狱。三年后，周凯出狱，改过自新。曾经的手下阿仓（余皑磊 饰）已为毒贩头目，为获取周凯的海外客户资料，设计加害周凯。江湖中的好兄弟马柯（王大陆 饰）为了替周凯报仇，失去一条腿。自己的亲弟弟周超不相信哥哥周凯已金盆洗手，不断搜集证据，欲亲手逮捕周凯。最终，周凯与警方合作，逮捕了阿仓，两兄弟重归于好。', '王凯', '丁晟', 4.5, 39575, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2508615612.jpg', 22.5, 42, 26.9, 4.2, 4.4, '-0.182795,-0.005312,-0.302766,0.500973,-0.141257,-0.530735,0.263763,-0.165489,-0.493132,-0.203563,0.193449,0.313915,0.291625,0.061860,0.290650,-0.126376,-0.163221,-0.802999,-0.049278,-0.057384,-0.231766,-0.455238,-0.168365,-0.230314,-0.202967,0.138989,0.646554,-0.054419,0.123623,0.592386,0.273836,0.092436,-0.086367,0.110368,-0.102041,0.063651,0.161013,-0.115077,-0.780070,-0.131937,-0.047539,-0.084046,0.186771,-0.036103,0.093595,0.345724,0.353586,-0.093769,-0.007898,-0.593276,0.324722,-0.476671,0.325725,-0.163391,0.397877,0.291805,0.295532,0.488395,-0.252392,-0.407359,0.197431,-0.110085,-0.697027,-0.079156,0.277167,-0.128282,-0.391548,0.136363,-0.606444,0.261311,0.179993,-0.025170,0.106363,0.639075,0.223357,-0.037404,-0.157938,0.019708,-0.345063,0.401331,0.584796,-0.241191,0.554882,-0.473387,0.199843,-0.148700,0.332976,-0.142116,0.020140,0.075432,0.480284,-0.254173,-0.177957,0.149196,-0.206357,-0.521051,-0.235499,0.238189,0.040003,-0.363659,0.082121,-0.343098,-0.153100,0.034459,0.079984,0.069614,0.197758,-0.232966,0.263546,-0.620568,-0.029172,0.152287,0.391791,-0.888752,0.209061,0.178365,0.221040,-0.535547,-0.062797,-0.152401,0.512188,0.179895,0.327613,-0.001641,0.086249,-0.241053,-0.037065,-0.293312', '1297574', '1302110', '1484760', '1297862');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26828019', '有完没完', '剧情', '老范（范伟 饰）出生的那一天刚好是愚人节，他自己也觉得，自己的一生很可能就是一个笑话。早年间，妻子离开了老范，留下了儿子小范（刘俊昊 饰）和老范过着相依为命的生活。父子两人之间虽然感情十分亲密，但拮据的经济和困顿的生活让老范始终对小范怀有着愧疚的情绪。这一天，老范似乎来到了人生的低谷，先是工作上出了纰漏被上司（范湉湉 饰）处罚，又在误打误撞之中惹恼了广场舞一哥（隋凯 饰），遭到了后者的报复和戏弄。之后遇见小范的班主任（贾静雯 饰），在这个美女面前闹了好大一个笑话。更糟糕的是，老范发现自己似乎跌入了时间的漏洞之中，被困在了这糟糕的一天之内。©豆瓣', '范伟', '王啸坤', 5.3, 22933, 'tt6857280', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2450444730.jpg', 11.6, 31.5, 42.3, 10.5, 4.1, '0.250187,-0.159062,-0.862628,0.490669,-0.160439,-0.431945,0.845579,0.164772,-0.799527,-0.081016,0.171483,0.726485,-0.357448,0.539464,0.192545,-0.071416,-0.165313,-0.751692,-0.000022,-0.216939,-0.286499,-0.456034,-0.245810,-0.044981,-0.132204,-0.216580,0.199112,0.228373,-0.175588,0.473547,0.247996,0.020701,0.162450,0.694598,-0.268142,0.300600,0.057466,0.284206,-0.028458,0.061262,0.299071,-0.219762,0.063638,0.344296,0.006033,0.490624,0.539018,-0.169135,-0.679043,-0.064143,0.421732,-0.371797,-0.225384,0.128402,0.436783,-0.097040,0.255687,0.073924,-0.408549,0.133727,0.095193,-0.004966,-0.620858,0.147699,-0.110669,0.011319,-0.733856,0.748530,0.218137,-0.295108,-0.124197,-0.190510,0.461000,0.564331,0.350663,0.420263,-0.396802,0.114504,-0.488712,0.106414,0.673781,-0.055574,-0.185468,0.499973,-0.155275,-0.374418,-0.066875,-0.085425,-0.421706,-0.050125,0.307647,-0.020924,-0.327302,0.146181,-0.458269,0.261923,-0.123868,0.038430,-0.262047,-0.551577,-0.089074,-0.165804,-0.184064,-0.691826,-0.702071,0.241031,-0.069797,-0.306600,0.523148,-0.811422,0.180831,0.433896,0.415861,-0.447032,0.709601,0.413366,0.136026,-0.042622,0.013434,0.083152,-0.285656,0.213772,0.349217,0.376542,-0.013295,-0.215181,-0.363267,0.530233', '34433857', '3111650', '1308755', '10355329');
