INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26832363', '借口公司', '喜剧', '格雷（菲利普·拉肖 Philippe Lacheau 饰）是“借口.com”公司的创始人，专门为需要“打掩护”的客户制造各种各样的借口和谎言。因为特殊的性质和高需求，公司的经营蒸蒸日上。一次偶然中，格雷邂逅了名为弗洛（艾罗娣·方坦 Élodie Fontan 饰）的女子，弗洛的天真和单纯深深的吸引着格雷，令后者坠入情网。格雷深信，她就是他命中注定要寻找的另一半。然而，令格雷头疼的是，弗洛是一个对“撒谎”零容忍的的人，如果告诉了她自己的真实身份，她一定会愤怒的拂袖而去。无奈之下，格雷只得用谎言将自己重重包装，在虚伪的假面下，格雷终于和弗洛走到了一起，可是当他到弗洛家做客时才发现，弗洛的父亲竟然就是自己的客户。©豆瓣', '菲利普·拉肖', '菲利普·拉肖', 7.2, 7630, 'tt5657028', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2511732277.jpg', 0.7, 4.1, 42.6, 40, 12.7, '0.349095,0.044138,-0.722381,0.664497,-0.548737,-0.359036,0.741771,0.211457,-0.630169,0.018960,0.205854,0.766839,-0.006041,0.244770,0.359020,0.402278,-0.321892,-0.702666,-0.117659,-0.330888,-0.142797,-0.744543,-0.494897,-0.261860,-0.133231,-0.359233,0.217368,-0.211434,-0.294782,0.184193,0.442477,0.726612,0.027674,0.489693,0.064374,-0.303330,0.106719,0.052764,-0.055356,0.258363,0.264090,0.003776,-0.230251,0.256159,-0.066025,0.587647,0.198748,-0.412633,-0.187910,-0.039922,0.417315,-0.344090,0.175889,0.275448,-0.004855,-0.243656,0.402194,0.195377,-0.457386,0.034564,0.259221,0.184033,-1.043778,-0.107677,0.236367,-0.121123,-0.900174,0.506918,-0.209526,-0.534111,0.353318,-0.585821,0.225819,0.293730,0.574542,0.286201,-0.149807,-0.224969,-0.482286,0.036642,0.286053,0.290866,-0.360238,0.057471,-0.236603,-0.150304,-0.017845,-0.244871,-0.430656,-0.042982,0.437004,0.087243,0.026317,0.166470,-0.622486,-0.290528,-0.661953,-0.354888,-0.027363,-0.540199,-0.086289,-0.429741,-0.008434,-0.414339,-0.325180,-0.213656,0.302277,-0.298145,0.626984,-0.983290,0.279177,0.833980,0.487387,-0.226514,0.569271,0.155425,0.026432,-0.299484,-0.293555,0.020283,0.081297,0.258578,0.107635,0.450068,0.395658,-0.102533,-0.359479,0.716546', '1783461', '1793491', '1307442', '3006892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26834930', '海贼王特别篇：黄金之心', '动画', '《海贼王》为了纪念播出第17年，同时也为了今年夏天上映的电影版造势，决定在电影上映前于电视上播出SP《One Piece Heart of Gold》。另外，小栗旬将作为客串声优参与。本次的SP将围绕神秘的宝藏“Pure Gold”讲述一个关于亲子之间羁绊的融合了感动和冒险的故事。小栗旬将为被称为史上最凶恶的宝藏猎人配音，这是一个实力超群，可以自由操纵身体中锁链的角色。从前就是《海贼王》粉丝的小栗旬表示，曾经收到过一次配音的邀约，但当时他觉得自己并不适合那个人物，所以就婉拒了，而这次他觉得宝藏猎人的角色真是与自己很搭，终于遇到了合适的角色。对于人物角色，小栗旬也表示：“虽然他被称作是最凶恶的宝藏猎人，但对于宝藏充满纯粹的欲望和执着，从这一点上看，意外地对这个人物恨不起来。”《One Piece Heart of Gold》将于7月16日晚21点在富士电视台播出。', '田中真弓', '长峰达也', 7.2, 6210, 'tt6425816', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2386161084.jpg', 1.4, 7.6, 40.3, 30.7, 20, '0.355010,0.015084,-0.486712,0.885746,-0.027388,0.055426,0.770261,-0.314422,-0.609727,-0.276930,0.113427,1.028916,-0.394614,0.027575,0.232655,-0.043612,-0.155211,-0.601653,-0.154503,-0.270571,-0.094904,-0.477880,-0.421046,0.016822,-0.179142,-0.233645,1.096025,0.072456,-0.338390,0.247144,0.573641,0.356519,0.142641,0.398867,-0.150796,-0.246401,-0.136316,0.159270,-0.284655,0.338654,0.012256,-0.345846,0.032351,0.399371,-0.060886,0.254642,0.504815,-0.446155,-0.249188,-0.106036,0.482111,-0.452020,-0.252939,-0.050763,0.219855,0.263856,0.408411,0.365764,-0.064973,0.108393,-0.158622,-0.464035,-1.221364,0.023305,0.383716,0.249969,-0.365398,0.381893,-0.161328,-0.119695,0.104700,-0.353687,0.280949,0.108543,0.610917,0.271098,-0.182604,0.139084,-0.166416,0.280332,0.535434,-0.011455,0.037431,0.655701,-0.056383,-0.716361,-0.177919,-0.296620,-0.311185,0.216074,0.021489,0.186625,-0.095143,0.135125,-0.685319,0.052885,0.096344,-0.349569,0.198827,-0.636917,0.018632,-0.571898,-0.191001,-0.284961,-0.113542,-0.082714,0.306097,-0.709633,0.957018,-1.031342,-0.024902,0.659442,0.384593,-0.492352,0.867355,0.333593,-0.077725,-0.368343,0.033893,0.147484,0.069029,0.071451,0.044903,0.173054,-0.009654,-0.708017,-0.409838,0.653964', '25880986',