INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26835471', '大侦探皮卡丘', '喜剧', '好莱坞真人电影《大侦探皮卡丘》（暂译）讲述了蒂姆·古德曼（贾 斯 提·史密斯饰） 为寻找下落不明的父亲来到莱姆市，意外与父亲的前宝可梦搭档大侦探皮卡丘相遇，并惊讶地发现自己是唯一能听懂皮卡丘说话的人类，他们决定组队踏上揭开真相的刺激冒险之路。探案过程中他们邂逅了各式各样 的宝可梦，并意外发现了一个足以毁灭整个宝可梦宇宙的惊天阴谋。该电影改编自任天堂3DS同名游戏，由罗伯·莱特曼导演，瑞安·雷诺兹为大侦探皮卡丘配音，贾斯提斯·史密斯、凯瑟琳·纽顿等主演。', '瑞安·雷诺兹', '罗伯·莱特曼', 6.4, 367915, 'tt5884052', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2555538168.jpg', 2.1, 14.5, 52.6, 24.5, 6.4, '0.154451,0.097270,-0.614740,0.395205,0.470945,-0.519288,0.401634,-0.055072,-0.419357,-0.599642,-0.024972,0.836470,-0.621602,-0.111412,0.338566,0.052857,-0.406956,-0.374943,-0.021835,-0.025932,0.075929,-0.349507,-0.166809,-0.359848,0.035319,-0.063216,0.407932,0.003824,-0.256112,0.366327,0.590140,0.194203,-0.146999,0.027011,0.336592,0.384531,0.257003,-0.150567,-0.424584,0.283124,0.000075,0.396672,-0.069750,0.144193,0.123173,0.295572,0.384310,-0.405971,-0.046111,-0.033795,0.344004,-0.130549,0.120526,-0.175614,0.018239,-0.085003,0.073227,-0.056147,0.275550,-0.020533,-0.051311,-0.148045,-0.614999,0.277429,-0.023100,0.391346,-0.042886,-0.081039,-0.059138,0.021155,0.220314,-0.184808,-0.020683,0.148444,0.833027,0.100319,0.286718,0.192834,-0.001320,0.191466,0.260393,-0.270103,-0.147723,0.655337,-0.149188,-0.564502,-0.384629,-0.143536,-0.519452,0.295338,0.349187,-0.017805,-0.061123,0.455917,-0.308614,-0.241234,-0.378243,-0.000185,-0.125815,-0.167768,0.206291,-0.729723,0.082801,0.085206,-0.049293,-0.010730,0.035688,-0.410911,0.323071,-0.482321,0.041800,0.587415,0.043558,0.031557,0.407666,-0.140857,-0.002216,-0.435949,0.124387,0.460773,0.214565,0.149410,0.039511,0.065665,0.314807,-0.304915,-0.494898,-0.050200', '1829654', '1484091', '4301659', '30382416');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26835911', '22年后的自白', '剧情', '1995年，东京发生了连环绞杀案，五人被害，凶手无影无踪，该案成为悬案。2017年，就在该案早已过了诉讼有效期之时，一位名叫曾根崎雅人（藤原龙也饰）的男子出版了一本《我是杀人犯》的告白书，声称自己是22年前连环杀人案的凶手，并嘲笑警方无能。此举震惊了整个日本社会，面对受害者家属的愤怒，警方却束手无策。作为当年调查案件的刑警，牧村航（伊藤英明饰）多年来从未放弃追捕真凶，对于曾根崎雅人的话他将信将疑，一场激烈的猫鼠游戏在两人之间展开。', '藤原龙也', '入江悠', 7.1, 28392, 'tt5882982', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2543712822.jpg', 0.2, 4, 43.4, 44.9, 7.4, '-0.095637,-0.303367,-0.430731,0.284965,0.081420,0.007338,0.633651,-0.310295,-0.767472,-0.559658,0.299072,0.531988,-0.237489,0.249490,0.188007,-0.100538,0.024496,-0.965220,0.033604,-0.286254,0.068702,-0.531637,-0.222589,-0.318613,-0.068021,-0.020591,0.432947,0.243327,-0.208216,0.368987,0.404379,0.566978,-0.580649,0.433543,0.074090,-0.021100,0.307242,0.235910,-0.368825,-0.020996,-0.254674,-0.672635,-0.125239,0.326397,-0.109452,0.313236,0.447996,-0.299166,-0.478230,-0.179345,0.308663,-0.434332,-0.246012,0.380847,0.821038,-0.013004,0.262972,0.579907,-0.137380,-0.327458,-0.040994,-0.016362,-0.710327,-0.116651,-0.089998,0.218051,-0.229074,0.324540,-0.450102,0.433755,-0.123476,-0.105636,0.069201,0.090689,0.362029,0.233364,-0.015912,0.049325,-0.164797,0.441101,0.598774,0.100019,-0.310447,0.023365,0.080610,-0.506695,-0.281715,-0.161630,-0.008317,0.368325,0.372363,-0.020662,-0.336026,0.445777,-0.246146,-0.284264,-0.508161,0.008420,0.055509,-0.029703,-0.168307,-0.325069,-0.054268,-0.292160,-0.330437,0.020853,0.120396,-0.325142,0.320999,-0.674349,0.226384,0.503977,-0.141357,-0.672887,0.245444,0.176534,-0.233007,-0.025259,0.016797,0.036010,0.265829,0.402906,0.290832,0.056529,0.174664,-0.278571,-0.014846,0.050481', '3263169', '5279640', '3136507', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26837951', '最后的食谱 麒麟之舌的记忆', '剧情', '影片改编自人气小说，集结了西岛秀俊、宫崎葵、绫野刚、竹野内丰等豪华阵容。二宫与西岛都饰演了不同时代，拥有绝对味觉“麒麟舌”的厨师。电影将于明年秋天在日本上映。', '二宫和也', '泷田洋二郎', 7.3, 7365, 'tt5894876', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2523382449.jpg', 1.7, 5.1, 37.4, 40.1, 15.6, '-0.211108,0.049639,-0.547694,0.462519,0.457079,0.070288,0.401215,0.666806,-0.188454,0.020949,0.113072,0.768721,-0.568432,-0.231795,0.296852,-0.263049,-0.284988,-0.599639,-0.064666,-0.183270,0.268239,-0.168683,-0.200046,0.013418,0.181998,-0.506167,0.941805,0.012795,-0.392977,0.314008,0.089491,-0.189201,-0.182921,-0.153382,0.093075,-0.043047,0.251973,-0.071457,-0.292123,0.832832,-0.518346,-0.145550,0.022729,0.023776,0.170198,0.085910,0.747035,-0.180431,-0.081693,-0.262292,0.315853,0.080906,-0.354584,0.310861,0.366880,-0.189618,0.304151,0.172423,0.070748,0.324759,-0.211985,-0.328510,-0.890975,0.140558,0.280406,-0.011279,-0.109705,0.463407,-0.293976,-0.469136,0.080933,-0.433347,-0.123987,0.049618,0.900172,0.333032,0.106544,0.309392,-0.314944,0.224521,0.156411,0.149492,0.133822,0.465723,0.188522,-0.786896,-0.736950,-0.279384,-0.308217,0.249281,0.175506,-0.131677,-0.013853,0.053019,-0.602633,0.172578,0.367119,-0.772971,0.324692,-0.075307,0.171317,-1.062137,0.088333,-0.436518,0.081585,-0.317294,0.773330,-0.202109,1.218952,-0.353678,-0.061141,0.677980,0.252412,-0.304242,0.561385,-0.124285,-0.330155,0.060881,0.358482,0.396060,-0.097864,0.231800,0.340092,0.605770,-0.334954,-0.195295,-0.413265,0.644266', '3318306', '1322847', '27602116', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26837952', '游戏人生 零', '爱情', '距今超过六千年的远古世界，天地割裂的凄惨战争持续不断，毫无还手之力的人类被拥有强大力量的各个种族逼入绝境，濒临灭亡。此时率领人类的年轻领袖里克，与机凯种少女休比偶然相遇。被同伴抛弃的休比，为了修复故障，拜托里克把“人类的心”告诉自己。机凯种少女的单纯与真诚，使得里克对休比逐渐放下戒备、敞开心扉，二人感情亦日渐升温。最终二人带领人类共同面对终极一战，少女休比也将面临恋人与生命的残酷抉择。末日来临，在251秒的时间里，赌上一场深情告白。', '松冈祯丞', '石塚敦子', 7.7, 30725, 'tt5914996', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2561782374.jpg', 1.4, 5.9, 29, 34.1, 29.6, '-0.116613,0.351668,-0.580978,0.279234,-0.020208,0.119038,0.776563,-0.251882,-0.306440,-0.130979,0.223516,0.670334,-0.132998,-0.049803,0.413177,-0.615098,0.018207,-0.718211,-0.186835,0.196095,-0.089847,-0.416294,-0.439964,0.074985,-0.233459,-0.638877,1.043725,0.200707,-0.311671,0.511769,-0.345742,0.387973,-0.239596,0.316868,0.166830,-0.347995,-0.154222,-0.137346,-0.685232,0.198283,-0.190537,0.141548,0.196129,0.256322,-0.608596,0.223455,0.660219,-0.735779,-0.119469,-0.443903,0.328190,-0.323289,-0.301403,0.450985,0.268067,0.139487,0.022256,0.162144,-0.056298,-0.123258,0.120964,-0.158582,-0.911773,-0.046134,0.088674,-0.173690,-0.221669,0.549354,0.168481,0.009471,0.287660,-0.125734,-0.035274,0.494802,0.633480,0.507051,-0.418390,-0.260902,-0.209622,-0.356065,0.718578,-0.338614,-0.551910,0.204543,-0.123408,-0.396441,-0.196096,-0.713746,-0.574302,-0.036601,0.069881,0.525901,0.151247,0.959028,-0.811223,0.029156,-0.435614,0.026830,0.054165,-0.620374,-0.149961,-0.298320,-0.537008,-0.113250,-0.226150,0.327899,0.263743,-0.362470,0.794703,-0.653349,0.298225,0.229287,0.617799,-0.276877,0.433389,0.037923,0.236538,-0.316670,0.098663,1.071874,0.113367,0.075383,0.081193,0.030210,-0.260176,0.823676,-0.309847,0.590800', '1763916', '26759819', '5308201', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26838236', '超能敢死队', '喜剧', '一对年幼的兄妹跟随母亲来到了乡下，然而这个偏僻宁静的小镇，却发生了一连串奇异的怪事，一名声称研究超自然现象的神秘男子悄悄现身。', '菲恩·伍法德', '贾森·雷特曼', 6.1, 13419, 'tt4513678', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2685536675.jpg', 3, 17.8, 55.1, 18.6, 5.5, '0.779689,-0.095288,-0.934114,0.543029,-0.166853,0.046399,1.019002,0.160330,-0.764924,-0.905450,0.730935,0.826877,-0.318312,0.063291,0.312287,-0.068555,0.259018,-0.250440,0.175923,-0.264095,-0.227619,0.033598,-0.433663,-0.266080,-0.103901,-0.252413,0.226787,0.616017,-0.298888,0.744536,-0.115053,0.530392,-0.841924,0.312075,-0.586420,-0.114069,0.327978,0.334594,-0.109570,0.047045,-0.408909,-0.424259,-0.103598,0.072626,-0.152177,0.470706,0.779212,-0.415688,-0.869035,0.081187,0.639646,-0.090228,-0.303130,0.052856,0.456207,0.251375,-0.090370,-0.135977,-0.211671,-0.207051,-0.405412,-0.220256,-0.063306,0.451978,-0.063322,0.388623,-0.564707,0.364664,0.266813,-0.865468,0.069857,-0.372110,0.645677,0.387590,0.083753,0.403783,0.063561,0.348735,-0.270644,-0.122324,0.708778,-0.120791,-0.562376,0.593196,-0.354206,-0.693501,-0.021032,0.002615,-0.619918,0.378662,0.175918,0.065037,-0.389240,0.114033,-0.593131,0.035846,-0.324576,0.270776,-0.091738,-0.192641,-0.738063,-0.736114,-0.140842,-0.298326,-0.449136,0.512334,-0.342185,0.113055,0.547370,-0.532571,0.393885,0.596770,-0.071463,-0.591782,0.355996,-0.394522,0.298300,-0.342258,-0.224796,0.410603,0.118044,0.289287,-0.397841,0.451184,-0.233630,-0.121343,-0.644524,0.045288', '20380318', '10466639', '1296534', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26838395', '真事改编', '剧情', '德芙妮（艾玛纽尔·塞尼耶 Emmanuelle Seigner 饰）刚刚出版了她的处女作，没想到一夜爆红，采访签售接踵而至。在成名的喜悦渐渐冷却之后，德芙妮开始筹备起下一部作品来，可让她感到窒息的是，灵感似乎已经抛弃了她，空白的文档前，她迟迟无法打出第一个单词。弗朗西斯（文森特·佩雷斯 Vincent Perez 饰）是一名节目主持人，两人之间若即若离的关系也成为了德芙妮的另一个压力来源。在德芙妮最苦闷的这个节骨眼上，一个名为爱丽（爱娃·格林 Eva Green 饰）的神秘女子出现在了她的生活里。爱丽自称是一名传记影子作家，因为家里出事了，所以希望能够借住在德芙妮家中。爱丽的出现成为了德芙妮的救命稻草，这个奇妙的女人不但在事业上，也在生活里成为了德芙妮坚强的后盾。©豆瓣', '艾玛纽尔·塞尼耶', '罗曼·波兰斯基', 6.4, 5642, 'tt5893264', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2546455631.jpg', 1.5, 13.7, 55.4, 24, 5.4, '0.330083,0.366411,-0.830705,0.582226,0.161663,-0.589583,0.781635,0.402503,-0.417096,-0.245717,-0.143369,0.421274,-0.405506,0.101433,0.316867,0.017794,-0.502711,-0.789110,0.050882,-0.437416,-0.254488,-0.151824,-0.352269,-0.180001,-0.109359,-0.538668,0.589736,0.041170,-0.261705,0.336702,0.512960,0.385064,0.108638,0.468712,0.043575,0.130271,0.419676,-0.043372,-0.127264,0.390043,-0.092638,-0.159924,0.084318,0.275692,0.054426,0.361602,0.491369,-0.255863,-0.160622,0.030288,0.599197,-0.165372,-0.174713,-0.160272,0.087704,-0.103500,0.112921,-0.348403,-0.413365,0.070981,0.307462,-0.205147,-0.829847,-0.081663,-0.278083,0.549642,-0.768831,0.388084,0.004218,-0.382858,0.096959,-0.440736,0.412557,0.339852,0.081685,0.216875,-0.194729,0.300189,-0.423574,0.212397,0.534000,0.247613,-0.065657,0.556872,-0.296546,-0.516649,-0.019634,0.082457,-0.629692,-0.131890,0.313040,0.020760,-0.026581,0.075905,-0.451750,-0.129848,-0.423442,-0.008353,-0.241359,-0.585886,-0.156221,-0.507194,-0.105268,-0.254917,-0.476784,-0.051478,0.107312,-0.464413,0.825265,-0.907679,0.420679,0.510644,0.183417,0.157025,0.485880,0.175647,0.045399,-0.320173,-0.040151,0.358999,-0.204471,0.049954,0.011311,0.388645,0.032297,0.074696,-0.521391,0.970687', '4058933', '21360412', '3230462', '1308763');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26839466', '哆啦A梦：大雄的南极冰冰凉大冒险', '动画', '为了躲避夏日的酷暑，哆啦A梦（水天葵 配音）带着大雄（大原惠美 配音）、静香（嘉薮由美 配音）、胖虎（木村昴 配音）和小夫（关智一 配音）来到了漂浮在南太平洋中的一座冰山上。他们利用道具“冰雕工艺组”打造了惊险刺激而又妙趣横生的游乐园，小伙伴们乐而忘返。可就在此时，乐园突然垮塌，大雄则偶然从冰层中捡到了一枚金环。根据调查发现，金环居然是十万年前的产物。为了寻找它的主人，哆啦A梦一行穿越时空。在古老的南极，他们见到了一座神秘都市，并发现了奇怪的生物。而他们此次的冒险，将与自身以及地球的命运息息相关……©豆瓣', '水田山葵', '高桥敦史', 6.5, 27898, 'tt5912470', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2459265598.jpg', 2.1, 11.9, 53.3, 24, 8.6, '0.218751,-0.037171,-0.581734,0.537921,-0.026244,-0.141998,0.705694,0.087620,-0.357994,-0.215933,0.216111,0.745988,-0.365408,0.126432,0.053594,0.165401,-0.180047,-0.427616,-0.320626,-0.175318,-0.509069,-0.252856,-0.306329,-0.103216,-0.067669,-0.154003,0.562936,0.084968,-0.206072,0.424873,0.126249,0.104143,-0.538439,0.199927,-0.258462,-0.141304,-0.029940,0.363353,-0.006754,0.356388,-0.432190,-0.183474,-0.033506,0.113091,0.001473,0.233688,0.783903,-0.569948,-0.045788,0.012220,0.251854,-0.277142,-0.052000,-0.029610,0.273499,0.006716,-0.051109,-0.062310,-0.301355,0.086171,0.088238,-0.332401,-0.782575,0.143367,0.010103,0.169296,-0.311362,0.355954,0.227628,-0.245507,0.300548,-0.375811,0.467215,0.279290,0.442296,0.476148,-0.248854,-0.015240,-0.147908,0.305071,0.421406,-0.082908,-0.070002,0.503450,-0.044883,-0.521684,-0.102808,0.064869,-0.098302,-0.038685,0.333786,0.166060,-0.172961,0.060561,-1.087103,0.094053,0.061920,-0.357949,-0.158496,-0.187905,-0.231972,-0.638368,0.080548,-0.229257,-0.113141,0.201810,0.062391,-0.187892,0.611054,-0.769937,0.261128,0.797565,0.108781,-0.064080,0.514653,-0.253105,-0.155150,-0.059244,-0.030248,0.032000,0.206433,0.563152,0.168098,0.488152,-0.036268,-0.124364,-0.737793,0.350873', '26290398', '25774050', '5322572', '1309194');
