INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26842503', '啊，荒野 前篇', '剧情', '作品改编自寺山修司的同名原著，将时间改为了近未来的2021年，但仍聚焦于年轻人的迷惘和焦躁。', '菅田将晖', '岸善幸', 8.4, 29007, 'tt5905008', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2493381063.jpg', 0.3, 1.1, 13.7, 48.1, 36.8, '-0.100038,-0.280005,-0.418810,0.589649,0.657561,-0.509015,0.493296,-0.073141,-0.609377,-0.436175,-0.142177,0.498183,-0.204157,0.296317,0.414227,-0.238242,-0.276902,-0.904586,-0.386762,-0.128620,0.009530,-0.586602,-0.375880,-0.388587,-0.491847,-0.706805,0.868867,0.292740,0.157632,0.519833,0.327161,0.279309,-0.388157,0.294310,0.089557,-0.240854,0.053191,0.207417,-0.397346,0.231613,0.210051,-0.469410,-0.535786,-0.474591,-0.053492,0.557205,0.778014,0.032135,-0.636099,0.484273,0.370576,-0.017786,-0.530082,-0.131607,0.133646,0.210250,0.012594,0.197342,-0.204205,0.029762,-0.137681,-0.136601,-0.651191,0.357042,0.222370,0.044926,-0.377330,1.238873,-0.228596,-0.086245,-0.139559,-0.426230,0.119050,0.040292,0.623815,0.187207,-0.394395,0.145963,0.117007,0.254143,-0.003975,0.239881,-0.569436,0.751478,-0.322877,-0.600568,-0.729867,-0.332070,-0.494689,0.214681,0.274644,0.513470,-0.184300,0.785070,-0.667935,-0.349475,-0.136258,-0.483219,0.034079,-0.440514,-0.275870,0.111434,0.001216,-0.826124,-0.247035,-0.359806,0.681176,-0.501594,1.128789,-0.518877,0.191417,0.475253,0.103935,-0.151016,1.252278,-0.267923,-0.039715,0.080688,-0.114166,0.480171,-0.210444,0.107302,0.491292,0.505175,-0.672879,-0.237129,-0.754880,0.661649', '1850942', '1296044', '26315728', '1291564');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26842702', '燃烧', '剧情', '目标成为作家的青年李钟秀（刘亚仁 饰），平日里靠兼职养活自己。经营畜牧业的父亲不谙人情，官司缠身，迫使钟秀又要为了搭救父亲而四处奔走。这一日，钟秀在某大型卖场重逢了当年的同学申惠美（全钟淑 饰）。惠美计划近期前往非洲旅行，于是拜托钟秀照看爱猫Boil。不久后惠美回国，与之一同下飞机的还有名叫本（史蒂文·元 饰）的男子。本驾驶保时捷，居住在高级公寓内，优哉游哉，不见工作，四处玩乐，和钟秀相比有如天上地下。不知为何，本走入平民钟秀和惠美的生活，更向新朋友讲述了他奇特的癖好。在钟秀家小聚的那个晚上过后，惠美仿佛人间蒸发了一般无影无踪……本片根据村上春树的短篇小说《烧仓房》改编。©豆瓣', '刘亚仁', '李沧东', 8, 339680, 'tt7282468', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520095279.jpg', 1, 2.6, 19.4, 47.4, 29.7, '0.115347,-0.148636,-0.523103,0.110846,0.162148,-0.215261,0.422174,0.481269,-0.371301,-0.396032,0.171210,0.554877,-0.093621,0.131081,0.435916,-0.054051,-0.535587,-0.386947,-0.053261,-0.457715,0.103756,-0.375834,-0.160298,-0.030137,0.161354,-0.225201,0.358161,-0.186434,0.013211,0.634076,0.054944,0.294029,-0.336320,0.067945,-0.265415,-0.001677,-0.117680,0.344040,-0.307883,0.360541,-0.195329,-0.122275,0.032403,-0.473844,0.149365,0.214945,0.566989,-0.075681,-0.156035,-0.364235,0.205034,0.101738,0.107692,0.005504,0.107017,0.091276,0.394181,0.194600,-0.406289,0.160661,0.107441,-0.295990,-0.375987,0.342410,0.312357,0.028120,-0.652609,0.231770,0.078962,-0.111355,0.145105,-0.243337,0.271879,0.442698,0.100874,0.435933,0.014869,0.342082,-0.452437,0.308860,0.455531,0.052381,0.105319,0.441293,0.234393,-0.022220,0.280355,-0.078306,-0.206307,-0.173402,0.038996,-0.041405,-0.024941,0.069641,-0.671137,0.146691,-0.008484,-0.017591,0.108626,-0.035482,-0.218760,-0.724095,0.076719,-0.232688,0.056922,-0.015121,0.133104,-0.244361,0.742464,-0.719502,0.224575,0.249939,0.378694,-0.675531,0.559269,0.005523,0.386174,-0.123427,-0.026437,0.082696,0.151139,0.597361,-0.115094,0.101177,-0.169545,-0.178288,-0.478167,0.064096', '3811356', '1294009', '1418179', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26843352', '无处为家', '剧情', '露丝（梅兰妮·林斯基 Melanie Lynskey 饰）是在康复中心上班的护士，实际上，她自己也患有抑郁症，正在服药进行治疗。在经历了非常倒霉的一天后，露丝疲惫的回到家中，震惊的发现自己的家遭到了歹徒的洗劫，值钱的笔记本电脑不翼而飞。巨大的压力让露丝感到，自己离崩溃不远了。第二天，露丝撞见了那个经常让狗狗在自己家院子里方便的可恶男人托尼（伊利亚·伍德 Elijah Wood 饰），之后，露丝的手机搜索到了绑定的电脑所发出的信号。露丝报了警，警方却不愿意帮她，无奈之下，露丝只得找到托尼帮忙，想不到托尼一口答应下来，并且很快就付诸了行动。©豆瓣', '梅兰妮·林斯基', '梅肯·布莱尔', 7.2, 6216, 'tt5710514', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2434272900.jpg', 1.1, 5.2, 40, 42.5, 11.2, '0.417429,0.168243,-0.884822,0.144134,-0.136408,-0.390559,0.675229,0.209026,-0.464363,-0.270419,0.267576,0.538650,-0.080261,0.358772,0.139314,0.148459,-0.467298,-0.515089,0.108745,-0.267652,-0.534509,-0.393851,-0.015055,-0.478896,0.084970,-0.469655,0.055416,0.009394,-0.121542,0.335187,0.066931,0.197291,0.012588,0.763697,-0.091439,0.279408,0.227231,-0.229938,0.107069,0.331944,0.449144,-0.208369,0.009501,0.307514,0.183853,0.442316,0.604289,-0.031228,-0.389713,0.081645,0.386437,-0.223384,-0.109757,0.086225,0.286248,-0.008147,0.084541,-0.347957,-0.515297,0.106961,0.280897,0.230209,-0.517339,0.109603,-0.085430,0.085768,-0.633666,0.423906,-0.517074,0.089855,0.141322,-0.559356,0.263869,0.467377,-0.069794,0.404595,-0.155879,0.261231,-0.533205,-0.045801,0.474589,-0.085690,0.008224,0.330225,-0.187429,-0.264723,0.067087,-0.038479,-0.562491,-0.150168,0.633745,0.139491,-0.306496,-0.130222,-0.457781,-0.224743,-0.564401,-0.332685,-0.186946,-0.222891,-0.156160,-0.719181,0.012322,-0.159232,-0.273444,0.101276,-0.116080,-0.233135,0.485545,-0.681361,0.206254,0.598680,0.210364,-0.229343,0.317598,-0.190514,0.086149,-0.057313,0.055892,0.045017,0.168787,0.622818,0.452693,0.435303,0.113691,-0.201091,-0.618724,0.416164', '3735015', '25837175', '2078159', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26844764', '困斗99号囚室', '动作', '曾是拳击手与运毒贩的 Bradley Thomas 迫于家庭生计重操旧业，眼看生活重回正轨却因一桩擦枪走火的交易而将遭受牢狱之灾。与此同时，面对上家针对妻女的威胁，身陷囹圄的 Bradley 又将进行怎样的挣扎与反抗？本片由 S·克雷格·扎勒 (S. Craig Zahler) 执导，作为非竞赛作品参映第74届威尼斯电影节，并获提名第42届多伦多国际电影节“午夜疯狂”单元观众选择奖、第44届土星奖最佳惊悚影片，主演文斯·沃恩 (Vince Vaughn) 则获得同届土星奖最佳男演员提名。', '詹妮弗·卡朋特', 'S·克雷格·扎勒', 6.7, 6788, 'tt5657856', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2496993137.jpg', 3.2, 11.2, 42.3, 31.8, 11.6, '-0.207231,-0.073148,-0.540963,0.466438,0.530738,-0.303415,0.265436,0.167307,-0.282352,0.012180,0.250991,0.889004,-0.393459,-0.050072,0.343060,-0.488644,-0.151718,-0.802560,-0.211992,-0.008342,0.138195,-0.128494,-0.120456,0.534394,-0.130748,-0.213564,1.002671,-0.055215,-0.352521,0.612859,1.015217,0.391966,0.057101,0.129361,0.196462,-0.212053,0.187432,0.219088,-0.749373,0.468850,-0.082204,-0.539878,-0.281270,-0.143752,0.410328,0.385420,0.729050,-0.080551,0.085019,-0.319665,0.760499,-0.599477,-0.373921,-0.006437,0.279522,0.251430,-0.078108,0.349022,0.136760,0.321476,0.031141,-0.333150,-0.924263,-0.116524,0.523233,-0.042106,-0.424657,0.215824,-0.190011,0.316117,-0.147968,0.275963,0.200421,0.335029,0.404302,0.165350,-0.009669,0.133385,-0.152054,0.367361,0.446286,-0.071935,-0.351822,-0.074095,-0.016162,-0.638149,0.290137,-0.679131,-0.273717,0.181597,0.197132,0.151587,0.220624,0.238909,-0.262556,0.032482,-0.260051,-0.547968,0.143354,-0.310062,0.072880,-1.072201,0.342552,0.170714,0.065929,-0.149889,0.213038,-0.596474,0.393088,-0.343010,0.340306,0.530275,0.507564,-0.226982,0.589330,0.425191,0.276416,-0.295506,-0.309989,0.283297,-0.218270,0.148586,-0.319639,-0.263362,-0.282477,-0.214040,-0.135592,0.406211', '27073234', '26990609', '1780122', '30397916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26844922', '杰出公民', '剧情', '小说家丹尼尔（奥斯卡·马丁内兹 Oscar Martínez 饰）从刚出道起事业就顺风顺水，如今更是获得了诺贝尔文学奖的殊荣，攀登上了职业的顶峰，然而这荣誉却并未带给他满足，恰恰相反，丹尼尔担心名声和财富会夺走他文学创作上的灵感与锋芒。一晃眼五年过去，丹尼尔热度不减，邀约和奖项不断，可冷淡而又避世的他只教助手一一回绝。一封来自小镇萨拉斯的信吸引了丹尼尔的注意，萨拉斯是他阔别已久的故乡，如今邀请他踏上故土，接受“杰出公民”的奖项，在未告知媒体和朋友们的情况下，丹尼尔独自踏上了返乡的旅途，在那里，他再度见到了曾经的恋人艾琳（安德丽娅·弗里杰里奥 Andrea Frigerio 饰），如今的艾琳早已经嫁为人妻，而她的丈夫正是丹尼尔的旧友安东尼奥（达迪·布列瓦 Dady Brieva 饰）。©豆瓣', '奥斯卡·马丁内兹', '加斯顿·杜帕拉特', 8.4, 93796, 'tt4562518', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2441383861.jpg', 0.3, 1.1, 12.8, 49.5, 36.3, '0.217294,0.171634,-0.684403,0.636003,0.007652,-0.562624,0.519233,0.159848,-0.419450,-0.077787,0.059979,0.895539,-0.096134,0.229136,0.483647,0.056960,-0.316908,-0.697862,0.122958,-0.434674,-0.112184,-0.446564,-0.339307,-0.093595,-0.242469,-0.359983,0.704445,0.070615,-0.172733,0.652692,0.335890,0.200485,0.128389,0.574661,-0.246218,0.098127,0.220202,0.155761,-0.426219,0.242064,-0.021224,-0.308078,-0.342572,0.279351,0.023818,0.345637,0.389074,-0.188241,-0.041927,-0.039710,0.370616,-0.265942,0.242016,0.012191,0.189565,0.013078,0.093542,0.158196,-0.032644,-0.093350,-0.029779,-0.202084,-0.577968,0.126503,-0.096180,0.161017,-0.613975,0.536579,-0.333593,0.001921,-0.121508,-0.337686,0.174443,0.281109,-0.184607,0.253765,-0.209674,0.070946,-0.350156,0.366494,0.506726,0.084115,-0.251293,0.290414,-0.333463,-0.408271,0.080840,-0.363878,-0.652379,-0.069767,0.349284,0.341974,0.094031,0.376863,-0.349841,-0.045840,-0.399610,-0.103613,0.096649,-0.458219,-0.151505,-0.581764,-0.213402,-0.240794,-0.426852,-0.107550,0.069572,-0.290269,0.748518,-0.725328,0.367223,0.491908,0.195757,-0.387484,0.761276,0.014518,0.077572,-0.107619,-0.111147,0.347400,0.018235,0.184564,0.092358,0.179793,-0.098775,-0.258243,-0.239775,0.719659', '1870681', '1292720', '30162520', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26845362', '鲨海', '惊悚', 'Lisa（曼迪·摩尔 Mandy Moore 饰）和Kate（克莱尔·霍尔特 Claire Holt 饰）两姐妹在墨西哥海岸度假，她们在海底观鲨铁笼中潜水观赏鲨鱼时，牵连铁笼的绳子突然断裂，观鲨笼掉落到47米深的海底。由于所存氧气不多，她们只有一个小时的时间逃脱牢笼回到水面。而此时，大白鲨也在她们周围游弋着。47米深的海底一片漆黑，只能通过手电筒观察铁笼外面的情况。水面上工作人员的声音时有时无，救援队也迟迟不见踪影，姐妹俩都非常害怕。面对仅剩的氧气，她们必须马上做出选择才有一线生机。为了避开鲨鱼活着游出水面，姐妹两人与鲨鱼之间展开了一场斗智斗勇扣人心弦的生死较量……', '曼迪·摩尔', '约翰内斯·罗伯茨', 5.6, 25288, 'tt2932536', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2504892832.jpg', 5.8, 25.4, 52.6, 14, 2.2, '0.007711,-0.225649,-0.758093,0.348773,0.208246,-0.045946,0.975006,0.032604,-0.321915,0.049355,0.272358,0.367667,-0.322128,0.026134,-0.179045,-0.311767,-0.791472,-0.626830,-0.211647,-0.202563,-0.592075,-0.187020,-0.430463,-0.030528,0.041188,0.072036,0.517319,0.325200,0.027612,0.315291,-0.005814,-0.330572,-0.545791,0.682357,-0.067701,-0.369120,-0.149245,0.015429,-0.099004,0.061629,-0.113080,-0.196596,-0.157462,-0.046224,0.166474,0.474334,0.838536,-0.482867,-0.001178,0.120775,-0.174729,-0.237603,0.184209,-0.028769,0.408399,-0.187326,0.182183,-0.064025,-0.287675,0.091022,0.163560,-0.004400,-0.103256,0.245146,-0.141400,0.342143,-0.200473,0.066931,0.097290,-0.193258,0.189466,-0.378121,0.024210,0.092625,0.068707,0.201975,-0.802034,-0.043967,-0.639344,-0.135311,0.605339,0.072235,-0.225308,-0.029745,-0.022891,-0.510655,-0.088383,0.044979,0.048869,-0.583305,0.729467,0.283308,-0.284288,0.242884,-0.612073,0.249826,-0.298925,-0.401108,-0.252788,-0.361787,-0.231492,-0.632855,0.029054,-0.294648,-0.100310,0.339779,-0.111347,-0.158704,0.455583,-0.322755,0.139278,0.515154,0.301331,0.184589,0.781550,-0.274132,0.298569,-0.035779,0.007030,0.319293,-0.065999,0.358818,0.235287,0.479903,-0.069072,0.254024,-0.463328,0.117341', '3011051', '20497633', '10466639', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26847068', '狂野生活', '剧情', '故事发生在1960年的美国，珍妮特（凯瑞·穆丽根 Carey Mulligan 饰）和丈夫杰瑞（杰克·吉伦哈尔 Jake Gyllenhaal 饰）结婚多年，两人的儿子乔伊（艾德·奥克森宝德 Ed Oxenbould 饰）都已经14岁了，一家三口平静度日。最近，一家人搬家来到了蒙大拿州，在这里，杰瑞找到了一份高尔夫球教练的工作。一场意外让杰瑞不幸丢掉了工作，这让整个家庭都陷入了经济危机之中。失业后，杰瑞整天无所事事的游荡在街头，后来给自己整了个临时消防员的职位，自此之后，他在家里的时间更少了。珍妮特渐渐看清了丈夫的无能和懦弱，决定外出找工作自己养活自己，在此过程中，她邂逅了名为沃伦（比尔·坎普 Bill Camp 饰）的汽车经销商。©豆瓣', '杰克·吉伦哈尔', '保罗·达诺', 7.2, 11724, 'tt5929754', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2528816969.jpg', 0.7, 3.8, 40.3, 45.5, 9.7, '0.110666,-0.078547,-0.669656,0.154852,-0.254801,-0.669626,0.595260,0.297406,-0.594498,-0.327433,0.014162,0.958839,-0.142317,0.431139,0.393031,0.128027,-0.599765,-0.786309,0.099431,-0.062677,-0.119812,-0.422504,-0.207211,-0.345509,-0.046749,-0.219791,0.109444,0.014243,0.350451,0.505262,0.093042,0.113565,0.121470,0.402965,-0.092272,0.369152,0.430539,0.002929,-0.166681,0.254758,0.044406,-0.175256,-0.072174,0.061482,0.416952,0.460798,0.756700,0.097113,-0.214283,0.009929,0.162898,-0.128933,-0.160507,-0.039387,0.357812,-0.209372,0.243977,0.103045,-0.567845,0.059863,0.043777,0.003643,-0.495895,0.078865,-0.175735,0.073692,-0.740961,0.684385,-0.108861,0.013487,0.018064,-0.403125,0.321486,0.639457,0.221902,0.309486,-0.148051,0.055272,-0.386609,0.394677,0.600829,-0.065060,-0.080948,0.442636,-0.264243,-0.221499,-0.010979,-0.210965,-0.493944,-0.262506,0.385263,-0.119058,-0.246896,0.280069,-0.629155,-0.099084,-0.160217,-0.355690,-0.032645,-0.356848,-0.182848,-0.497056,-0.073643,-0.287764,-0.449188,0.008360,-0.085187,-0.040807,0.400982,-0.622139,0.325773,0.515801,0.038326,-0.271047,0.630185,-0.043645,0.527936,-0.053557,0.231070,0.108994,-0.055538,0.560494,0.279773,0.297704,0.002158,-0.115870,-0.454060,0.519244', '6128003', '26678509', '3567857', '1297628');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26847445', '夜空总有最大密度的蓝色', '剧情', '日间她是医院护士，见尽生死，晚间兼职酒吧，对生活意兴阑珊。他在地盘打散工，左眼失明，只看见世界的一半。在分崩离析的现代都市，两个半边人，是否就能凑成一个整体？渴望爱同时不相信爱，死亡阴影总是挥之不去，就算天空再深蓝，抬头只见密云，什么都有预感，怕回头已是百年身。原田美枝子女儿石桥静河首度担正，伙拍池松壮亮，并有松田龙平助阵。改编畅销女诗人诗集，石井裕也（《字里人间》，37届）以「最高密度」的蓝色爱情，换个角度看他最爱的古怪男女。', '石桥静河', '石井裕也', 7.5, 24369, 'tt5931802', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2507511312.jpg', 0.6, 4.1, 32.1, 45.7, 17.5, '-0.090234,0.023858,-0.323902,0.255327,0.050148,-0.154594,0.567375,0.246261,-0.112826,-0.133319,0.156643,0.585597,0.009278,0.258789,-0.050259,0.218643,-0.013385,-0.494949,0.044700,-0.253118,-0.121868,-0.258409,-0.307350,-0.059857,-0.010572,-0.209718,0.704498,0.278893,-0.271335,0.171399,0.336841,0.086755,-0.157963,0.315502,-0.230635,-0.254767,-0.072407,0.191124,-0.217186,0.008452,-0.126243,-0.193592,-0.232586,0.135213,-0.118162,0.002458,0.510778,0.048601,-0.402036,-0.047152,0.380470,-0.069584,-0.251994,-0.047719,0.353549,-0.255510,-0.011307,-0.131636,0.072199,-0.242133,-0.059966,0.309733,-0.438843,-0.001361,-0.046691,0.263971,-0.234447,0.180942,0.033138,-0.574492,0.084473,0.245589,0.049980,-0.060887,0.261828,0.356511,-0.319285,0.002455,-0.315608,0.267916,0.413756,0.200028,-0.201748,0.469507,-0.307333,-0.395452,-0.036704,-0.063093,-0.213165,0.071447,0.050214,0.010634,-0.107772,-0.074871,-0.263347,0.421040,0.188608,-0.045456,0.133017,-0.443914,-0.117098,-0.284549,-0.148235,-0.378087,-0.267280,0.188289,0.359804,-0.032250,0.594042,-0.514363,0.323279,0.480222,0.294219,-0.235279,0.810892,0.421854,-0.213894,-0.316512,0.197935,0.386120,-0.186353,0.268652,-0.039038,0.102421,-0.032684,0.158316,-0.394665,0.592675', '30349667', '25880986', '5416009', '1308499');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26848167', '爱宠大机密2', '喜剧', '《爱宠大机密2》将延续2016年夏天轰动一时的《爱宠大机密》的故事，讲述宠物在我们每天离家工作或上学后的生活。照明娱乐创始人兼首席执行官克里斯·梅勒丹德利和他长久以来的合作伙伴珍娜·海莉将共同制作这部续集。《爱宠大机密》是当时开画成绩最好的原创电影，不论是动画片还是其他类型。《爱宠大机密2》继续由布莱恩·林奇（《小黄人大眼萌》）编剧，并再一次由克里斯·雷纳德（《神偷奶爸》系列，《老雷斯的故事》）执导。', '帕顿·奥斯瓦尔特', '克里斯·雷纳德', 6.8, 122302, 'tt5113040', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2555923582.jpg', 0.8, 7.3, 50.2, 32.2, 9.5, '0.008938,-0.195806,-0.311693,0.620742,0.293125,-0.060759,0.160763,0.104240,-0.523385,-0.431974,-0.125886,0.762682,0.005456,0.154814,-0.027111,0.166547,-0.388123,-0.411422,0.031584,-0.174952,0.396636,-0.391749,-0.242429,-0.338623,-0.190016,-0.269033,0.771614,-0.252908,-0.234442,0.069106,0.467024,0.061868,-0.076787,-0.238077,0.250435,-0.245750,0.231269,0.003106,-0.618701,0.441241,-0.074322,0.197312,-0.212411,-0.311182,0.474735,-0.015249,0.382190,-0.394556,-0.175407,-0.205718,0.379790,-0.389794,-0.137703,-0.368163,0.113724,0.121921,0.416074,0.642638,-0.134401,0.179465,-0.152879,-0.362228,-0.974339,-0.281033,0.165087,0.089090,-0.355319,0.519671,-0.503492,-0.017750,0.233672,-0.374188,0.089214,0.021804,0.390026,0.368552,0.127248,0.441940,0.167226,0.651699,0.398805,-0.059441,-0.130248,0.527020,-0.209302,-0.155178,-0.187053,-0.617385,-0.607102,0.281592,0.045163,0.038035,0.030876,0.285484,-0.552756,-0.016066,0.253973,-0.360658,0.241917,-0.449811,0.052511,-0.682151,0.114863,-0.077723,0.031555,-0.481570,0.204746,-0.551577,1.037688,-0.750397,0.278848,0.578680,0.068069,-0.676659,0.704055,0.286010,0.097057,-0.345685,-0.037286,0.280707,0.113374,0.104753,-0.126399,0.009947,0.378660,-0.535460,-0.226851,0.377511', '27602116', '24284209', '1308424', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26848504', '家族之苦2', '喜剧', '在平田周造（桥爪功 饰）与妻子富子（吉行和子 饰）闹离婚后的数年，长男幸之助夫妇担心高龄者的危险驾驶，计划让老爸周造还掉自己的驾照，然而顽固的周造偏不还，让平田家族里再次蒙上不安的氛围。某日，周造与居酒屋女老板和开车回到故乡广岛的同级生丸田吟平偶遇，丸田已经变成落寞的孤 寡老人，周造组织了场同学聚会设法让丸田过得快乐，丸田在感动之余倾诉了他这些年的遭遇，当晚在睡梦中离世。……', '桥爪功', '山田洋次', 8.4, 33132, 'tt5934564', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2458687725.jpg', 0.2, 0.8, 12.5, 50.5, 36.1, '-0.047025,0.155041,-0.754458,0.313670,0.021006,-0.473643,0.496945,0.278674,-0.610929,-0.262952,-0.084607,0.700598,-0.170189,0.658825,0.353812,0.166645,-0.142348,-0.614013,-0.062337,-0.052380,-0.233451,-0.232771,0.159619,-0.247708,-0.296057,-0.239769,0.403339,0.267902,0.030956,0.450689,0.045168,0.459928,-0.152794,0.516051,-0.195112,0.104957,-0.132637,0.346175,-0.149736,0.038985,0.006054,-0.286168,-0.159740,-0.039167,0.222341,0.350762,0.768848,0.088489,-0.293184,-0.149498,0.189375,-0.202119,-0.226399,0.238841,0.382034,0.000160,0.150740,0.154691,-0.420221,-0.051864,0.037663,0.125541,-0.476654,0.042796,0.130146,-0.122754,-0.557870,0.622459,-0.209579,-0.021427,0.180433,-0.213562,0.227861,0.450739,0.118689,0.491866,-0.286607,0.023484,-0.313383,0.183257,0.754187,-0.199513,0.011465,0.200293,0.199919,-0.339699,-0.001720,-0.182044,-0.371916,-0.213081,0.266205,-0.029703,-0.191116,0.212756,-0.480615,-0.219501,-0.306974,0.101585,0.120267,-0.238494,-0.055117,-0.276615,-0.095156,-0.474881,-0.290343,0.285967,0.343317,-0.178258,0.338074,-0.663719,0.395809,0.287089,0.285116,-0.249504,0.622851,0.091015,0.034172,-0.191638,0.056305,0.102227,0.000428,0.348107,0.238558,0.389098,-0.213828,-0.063470,-0.469861,0.088617', '26687241', '2365260', '1292219', '1297628');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26848640', '教授与疯子', '剧情', '影片故事根据真实事件改编，詹姆斯·默里博士（梅尔·吉布森饰演）领导下的编委会要进行新版本的《牛津英语字典》的编辑，以当时的人力科技水平，完成字典的编撰要一个世纪才能完成，詹姆斯·默里博士开创性的采用了全民参与的方式，让全英使用英语的人一起为字典收集词条定义，并通过寄信的方式发送给编撰组。在收集定义过程中，他们发现了一个叫W.C.迈纳（西恩·潘饰演）的医生独自贡献了一万多条引语，这是一个专业语言学者都很难完成的工作量。当编委会决定向他致敬时，一个惊人的事实曝光了：原来迈纳医生，是美国内战时期部队的一个军医，因为患有精神分裂症而犯杀人罪，被禁闭在精神病院，是一个被认为是疯子的人。一位教授、一个疯子，人类历史上最早的英语大词典就这样在两个迥然不同的人手中诞生。', '梅尔·吉布森', '法尔哈德·撒夫尼亚', 7.6, 19255, 'tt5932728', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2577347230.jpg', 0.2, 2.6, 31.4, 49, 16.8, '0.417250,0.004231,-0.075997,0.971331,-0.220574,-0.140723,0.500524,-0.131544,-0.429747,-0.460051,0.200568,0.746309,0.020516,0.116638,0.272320,-0.201214,-0.358571,-0.589908,-0.077903,-0.170068,-0.526616,-0.802234,-0.009948,-0.430287,-0.027148,-0.395962,0.536226,-0.195194,-0.413179,0.204547,0.055713,0.337853,0.104714,0.057847,0.003105,-0.035406,0.446826,-0.332471,-0.129311,0.406812,0.110601,0.036537,0.054280,0.161342,-0.313881,0.246812,0.555943,-0.135230,-0.142171,-0.067026,0.710801,-0.253036,-0.300112,0.013387,0.509281,0.036079,0.247505,0.389753,0.143011,0.096437,-0.075176,-0.217384,-1.308665,-0.301502,0.159766,0.181715,-0.437411,0.167529,-0.213937,0.071636,-0.148581,-0.375670,0.041333,0.243577,0.587811,0.555271,-0.025004,-0.136720,-0.406070,0.570013,0.385850,-0.178070,-0.545985,0.330846,-0.291220,-0.639222,-0.023563,-0.181911,-0.398921,0.228087,0.082045,-0.255428,-0.212208,-0.032311,-0.554509,0.145832,-0.231531,-0.285563,0.109871,-0.374860,0.001368,-0.596984,-0.013054,0.029182,-0.244879,-0.087366,0.065829,-0.291806,1.024984,-0.545660,0.049871,0.615815,-0.038477,-0.276949,0.719000,0.091888,-0.100902,-0.406014,0.133870,-0.076980,0.174079,0.441875,-0.036969,0.571321,0.382461,-0.337852,-0.455098,0.582731', '27602116', '6844861', '24284209', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26850326', '欢乐喜剧人', '喜剧', '岳云鹏、艾伦、潘斌龙、张小斐、张泰维等一班国内最顶尖的喜剧人排练新春特别节目，因为争当主角导致排练失败。郭德纲老师为了新春特别版的《欢乐喜剧人》能顺利录制，带他们到澳门，一起封闭排练。可岳云鹏等人却各自为政的狂欢，晚饭时分，因为两个美女的出现导致郭德纲人间蒸发！众人在找郭德纲的时候，更恐怖的事情陆续发生，团队中的成员一个接一个的被抓！而抓人的人竟是郭德纲！到底是对头人从中作梗，还是发生了灵异现象？这帮认真搞笑的谐星又要如何应付即将到来的大事件？', '郭德纲', '黎继强', 2.6, 28584, 'tt6421362', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2449680079.jpg', 79.8, 14.5, 4.1, 0.8, 0.8, '0.328311,-0.356137,-0.632084,0.094333,0.007283,0.139783,0.704376,0.157003,-0.577710,-0.164619,0.434817,0.569194,-0.713680,0.214911,0.506798,-0.320238,-0.448082,-0.824760,0.128228,0.069021,-0.285896,0.151428,0.003681,-0.341772,0.146203,-0.046264,0.333904,0.252960,-0.064291,0.454694,0.443663,-0.026841,-0.289818,0.415887,0.058685,-0.031258,0.191456,0.208823,0.036461,0.147157,-0.094980,-0.463347,-0.419483,0.105213,-0.046581,0.378150,0.500556,-0.085546,-0.065042,-0.115123,0.234374,-0.682222,-0.356515,-0.040247,0.513354,-0.099233,0.352490,0.110549,-0.021717,0.141293,-0.325800,-0.146294,-0.901507,0.436324,0.094520,0.325820,-0.134573,0.581767,0.297602,0.007609,0.153707,-0.203493,0.423124,0.382571,0.475485,0.314138,0.106707,-0.112997,-0.168188,0.348702,0.820760,-0.316521,-0.181251,0.279896,0.076688,-0.452565,-0.040014,-0.435928,-0.363491,0.300853,0.173321,0.019294,-0.178009,0.086267,-0.513858,0.056277,0.062145,-0.250789,-0.295336,-0.514526,-0.100248,-0.875928,0.154565,-0.190211,-0.001123,0.331721,0.095212,-0.040727,0.684854,-0.571414,0.094661,0.435841,0.184139,-0.557263,0.508392,0.012432,0.040179,-0.203547,-0.125380,-0.474727,-0.032124,0.295299,0.114043,0.376025,-0.095188,-0.274279,-0.325403,0.275307', '3318306', '11541282', '4301278', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26850330', '欲念游戏', '科幻', '《欲念游戏》讲述在2020年，一代叱咤智能科技领域的风云人物郭实（郭涛饰），在经历丧女之痛后决定远离尘嚣，终日与智能机器人相伴。但一次意外的发生，郭实莫名沦为“杀人逃犯”，并一步步落入对方所设的陷阱中。为证清白，郭实重拾“化蝶系统”，与爱徒飞凡（姜潮饰）和机械发烧友萌萌（张子枫饰）联手追查真凶。在探寻真相的过程中，郭实发现妻子宁雪（梅婷饰）和好兄弟老查（范伟饰）与此事有着千丝万缕的联系，但逐渐被视觉致幻的他开始难辨真假虚实，一场有关科技的烧脑战役呼之欲开。', '郭涛', '郭涛', 2.9, 6475, 'tt10192308', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2551984168.jpg', 66, 24.1, 8.6, 1, 0.3, '0.181535,0.156817,-0.561508,0.441468,0.088977,0.079419,0.594764,-0.188775,-0.901659,-0.366914,0.057233,0.586924,-0.213125,-0.130938,0.143255,-0.494951,0.022915,-0.675424,0.239859,-0.189849,0.040552,-0.701755,-0.322860,-0.106915,-0.084948,-0.279992,0.888469,0.132456,-0.344799,0.388244,0.067197,0.303835,-0.738772,0.464164,0.030734,-0.105828,-0.000993,0.038928,-0.614273,0.081685,0.051839,-0.248613,-0.044693,-0.032228,-0.348711,0.118609,0.709175,-0.434803,-0.291154,0.050272,0.281012,-0.264002,-0.212828,0.123933,0.144236,0.422414,-0.015055,0.524071,-0.089251,-0.161453,0.044092,0.162168,-0.613044,-0.208606,0.212405,0.256751,-0.177237,0.168348,-0.230003,-0.023489,0.033715,-0.179712,0.267868,0.371734,0.849883,0.306800,-0.160823,0.106793,-0.316594,0.157654,0.664486,0.056957,-0.167951,0.392487,0.236924,-0.516549,-0.287282,-0.210272,-0.329859,0.123127,0.238896,0.317547,-0.412970,0.795415,-0.616261,0.107050,-0.217795,0.012804,-0.087594,-0.391856,0.078181,-0.509852,-0.590734,-0.346585,-0.270257,-0.045250,0.214288,-0.552751,0.435812,-0.978354,0.189963,0.238393,0.093305,-0.431652,0.474467,0.100591,0.127804,-0.237819,-0.149546,0.308655,0.179244,0.274146,-0.214349,0.217951,-0.006517,0.027100,-0.499995,-0.010906', '1293265', '26759819', '30345227', '35030151');
