INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26857170', '西谎极落之太爆太子太空舱', '喜剧', '狮子山下的香港，是一个谎言也被美化成「语言艺术」的荒谬都市，要骗得到别人，先要骗到自己，在这繁华都市的一个贫困角落，是一个个比劏房更非人道的「太空舱」，在这些六迟x四迟的棺材式住宅中，住一班快要连自己也骗不下去的人。网客子轩，网上是人气爆灯的楼市评论家，现实中却是欠负 累累，屋租也交不起的网路打手，为了省钱还债，骗女友到纽约实习，实情是搬到「太空舱」，在网上装著「纽约客」的生活，子轩却在这个环境恶劣的「太空舱」中认识更多「太空人」…年少时抱著热血江湖梦的古惑仔阿锋，却遇上回归后社团事业转形型，十多年来越混越差，竟沦为水货客，江湖变作罗湖，鬱鬱不得志阿锋等待机会多年，却在一次为维稳活动中，错手重创高官，成为人民英雄！释囚瑞昌为糊口，重操故业持械行劫，一次犯案中无意中竟让昔日狱友强姦犯阿全成为救得美人的英雄，突然正义的瑞昌决定为自己作孽赎罪！神神化化，常胡言乱语，在太空舱开设骨灰龛生意的阿成，有著一套异于常人的生活哲学，却遇上一头身价二百万的失犬！疼爱女友的货van司机阿明，为找一个可以和女友好好亲热的安乐蜗历尽千辛万苦，甚至将货van改装成「浪漫车床」旅居郊野公园，本意为万事俱备温馨之夜，却变成一场枪战飞车大逃亡！这群「来自太空舱的男人」为著心中的理想生活，在一个又一个谎话之中挣扎求存，体现真正的香港精神：自欺欺人！向著堕落的轨迹，跌进极度荒谬境地！', '周柏豪', '吴汉邦', 6, 8063, 'tt7375556', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2498904492.jpg', 4.6, 18.3, 53.7, 18.7, 4.8, '0.126257,0.087566,-0.458308,0.407689,-0.276113,-0.304946,0.803360,-0.086071,-0.398758,-0.103487,0.233554,0.752660,-0.042296,0.302976,0.162218,0.045815,-0.109407,-0.463919,-0.032010,-0.076480,-0.086149,-0.186904,-0.268736,-0.022192,-0.229956,-0.030996,0.505313,0.245971,-0.184124,0.138507,0.189022,0.136138,-0.076903,0.247967,-0.350250,-0.070382,-0.079914,0.097365,-0.241407,0.188584,-0.256530,-0.276300,-0.182269,0.072744,-0.132829,0.063664,0.600125,-0.016360,-0.216057,-0.155730,0.450754,-0.261462,-0.344781,-0.107909,0.177861,-0.132475,0.262172,-0.035498,-0.044731,0.207231,0.094489,-0.049024,-0.818179,-0.085974,0.031976,0.048729,-0.598979,0.279800,-0.057732,-0.124149,-0.194463,-0.275716,0.097837,-0.002449,0.099182,0.547071,-0.292923,0.107429,-0.488697,0.313091,0.718099,0.087935,-0.214404,0.266197,-0.056104,-0.296058,0.219182,-0.318988,-0.445122,-0.272887,-0.028579,-0.271337,-0.229172,0.314412,-0.534552,0.123757,-0.222739,-0.058053,-0.068179,-0.290892,-0.166201,-0.323761,-0.112687,-0.211346,-0.067376,0.143817,0.300024,-0.