INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26857654', '转型团伙', '喜剧', '过气影帝宇哥（吴镇宇饰）与当红童星费曼（费曼饰）因一场拍摄意外而陷入黑帮纷争的故事。失忆的宇哥意外“入戏”，以为自己就是真正的社团大哥，为了赚钱照顾儿子决定重出江湖，殊不知时代已经改变，引发一连串令人啼笑皆非的乌龙事件，更上演了险象环生的黑帮纷争……', '吴镇宇', '吴镇宇', 3.3, 5484, 'tt7618402', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2553741576.jpg', 54, 30.1, 12.2, 2.6, 1.1, '-0.016908,-0.308382,-0.288595,-0.038670,0.322347,-0.015876,0.579054,0.117646,-0.751824,-0.512028,0.293552,0.450670,-0.535809,-0.022079,0.511073,-0.592454,-0.158406,-0.617937,0.093374,0.247577,0.260887,-0.273398,-0.492969,-0.048226,-0.076182,-0.397760,0.668899,0.273249,-0.614740,0.485206,0.505627,0.125995,-0.179682,0.238706,0.370305,0.058715,-0.125394,0.541418,-0.657948,-0.234524,0.026637,-0.276911,-0.253850,0.459296,0.014624,0.158617,0.343472,-0.133936,-0.174308,-0.371022,0.575537,-0.612297,-0.208598,-0.078835,0.173897,0.101153,0.542236,0.103291,0.024287,-0.090423,0.108717,-0.015305,-0.683270,0.287581,0.605412,0.082814,-0.262935,0.151555,-0.207993,-0.294565,0.110358,0.085952,0.080380,0.509392,1.186769,0.360832,-0.361157,0.266034,-0.133234,0.186239,0.799317,-0.288236,-0.255116,0.393803,0.384032,-0.209500,-0.130074,-0.406128,-0.276907,0.522785,0.015016,-0.559727,-0.172111,0.786278,-0.346217,-0.252364,-0.073535,-0.365618,-0.058676,-0.282898,-0.097874,-0.298503,-0.329077,0.082160,-0.068788,-0.208586,-0.033462,-0.233581,0.393298,-0.527048,0.221362,0.661185,-0.237849,-0.705286,0.239199,0.324003,-0.020598,-0.465449,-0.163562,0.068712,-0.305056,-0.183143,-0.215416,-0.055570,0.049259,-0.491635,0.072128,-0.000993', '26277156', '30168032', '1291546', '30204413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26857793', '原谅他77次', '爱情', 'Eva（蔡卓妍 饰） 与Adam（周柏豪 饰）拍拖十年多，却因一件小事突然分手。莫名被分手的Adam酒后与学生Mandy（ 卫诗雅 饰）发生了关系。可随后Mandy却在Adam家中意外发现了一本Eva所写的77次心碎记录，记事簿里Eva一次次的被伤害纪录历历在目⋯Adam愧疚不已，鼓起勇气在众目睽睽之前向Eva道歉。岂料，Eva却在Adam家中发现了Mandy的物品⋯到底她可否原谅Adam第78次呢？', '蔡卓妍', '邱礼涛', 6.4, 56585, 'tt6608132', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2464315908.jpg', 2.8, 14.5, 50.5, 25.2, 6.9, '0.315992,0.095482,-0.800403,0.369239,0.341603,-0.363172,0.841775,-0.113443,-0.670543,-0.548867,0.092181,0.726838,-0.702856,0.314883,-0.012325,-0.373110,0.136037,-0.846076,0.435984,-0.380381,-0.441253,-0.336811,-0.222906,0.193730,-0.073295,-0.478874,0.151901,0.199820,-0.091827,0.625545,0.481515,0.233619,-0.231219,0.603665,0.166666,0.176276,0.020375,0.658647,-0.196972,-0.183694,0.120365,-0.749001,-0.277424,0.144413,0.105656,0.530515,0.799857,-0.098765,-0.626523,0.260263,0.687442,0.082417,-0.012353,0.268303,0.105495,0.393754,-0.054219,0.305704,-0.294078,0.034220,0.400696,0.286662,-0.518965,0.058329,-0.060736,0.264604,-0.620618,0.677474,-0.433688,0.204447,0.040009,-0.223837,0.232795,0.387793,0.444043,0.481846,-0.458209,-0.305276,-0.340415,0.235801,0.530444,0.183384,0.204271,0.613824,-0.015335,-0.411731,0.128292,0.043750,-0.359373,0.451409,0.201926,0.373884,-0.268093,0.297772,-0.497946,-0.299701,-0.276820,-0.091314,-0.379730,-0.572999,-0.075862,0.042522,-0.228645,-0.193770,-0.520293,0.263240,-0.111339,-0.260340,0.223599,-0.600585,0.263174,0.452753,0.516052,-0.485005,0.481064,0.579541,-0.299798,0.383135,0.021355,0.116198,0.094012,0.096363,0.221870,0.135959,0.212208,-0.202088,-0.375467,0.252322', '21348112', '1773217', '2365260', '1309297');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26857860', '余波', '剧情', '故事发生在1946年的德国，第二次世界大战刚刚结束，战火让大地满目疮痍，家庭妻离子散。英俊上校刘易斯（杰森·克拉克 Jason Clarke 饰）和他的妻子瑞秋（凯拉·奈特莉 Keira Knightley 饰）在战争中失去了他们的大儿子，瑞秋因此非常的痛恨德国人，但是让她没有想到的是，战后，她和她剩下的家人们，要和一个名为史蒂芬（亚历山大·斯卡斯加德 Alexander Skarsgård 饰）的男人住在同一屋檐下。史蒂芬也在战争中失去了妻子，这让他对瑞秋没什么好脸色，两个人天天争锋相对。丧子之痛让刘易斯选择将大部分的时间和经历放在工作中，备受冷落的瑞秋每天的相处对象就只有史蒂芬，渐渐的，两人之间的关系开始转变。©豆瓣', '亚历山大·斯卡斯加德', '詹姆斯·肯特', 6.6, 6508, 'tt5977276', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2537193081.jpg', 1.6, 11.2, 49.3, 29.2, 8.6, '0.377497,-0.151486,-0.914095,0.456849,-0.113287,-0.403599,1.158839,0.068715,-0.609384,-0.197910,0.039113,0.947151,-0.352872,0.151766,0.236160,-0.094748,-0.387090,-0.973753,-0.089979,-0.033480,-0.286254,-0.551523,-0.055872,-0.176556,-0.356194,-0.396445,0.695840,-0.223139,0.178908,0.466798,0.100703,0.275689,0.330135,0.609659,-0.158314,0.226573,-0.073146,-0.288080,-0.435248,0.267396,0.195334,-0.051781,-0.314854,0.415145,0.166844,0.350629,0.649692,-0.271003,0.007500,0.027928,0.242593,-0.221081,-0.272222,0.149716,0.346950,-0.295342,0.228931,0.305436,-0.322523,-0.140581,0.099495,0.112681,-0.726642,0.274294,-0.001779,0.258801,-0.630715,0.830383,-0.081799,-0.101718,0.180200,-0.375354,0.453099,0.597672,0.255179,0.399588,-0.279324,-0.129074,-0.457823,0.145232,0.986496,0.085056,-0.296533,0.342301,-0.455609,-0.255707,-0.135714,-0.454690,-0.665715,-0.088220,0.186753,-0.079744,-0.043147,0.520569,-0.663454,0.099765,-0.160862,-0.440062,-0.008774,-0.501634,-0.121641,-0.496960,-0.590502,-0.907793,-0.605125,0.120608,-0.122666,-0.400297,0.698464,-1.053129,0.254984,0.501372,0.367844,-0.251758,0.802320,0.362390,0.442715,-0.072469,0.016517,0.261840,-0.151036,0.096760,0.228275,0.362942,-0.002577,0.112958,-0.163820,0.636391', '1308755', '4275444', '3111650', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26858510', '克劳斯：圣诞节的秘密', '喜剧', '贾斯帕（詹森·舒瓦兹曼饰）被认为是邮政学院最差的学生，他驻扎在北极圈内的一个冰冻岛屿上，那里的当地人之间几乎不交流，更不用说写信了。当贾斯帕准备放弃之时，他找到了自己的盟友阿尔娃（当地的一名教师，拉什达·琼斯饰），并发现了克劳斯（奥斯卡奖得主 J·K·西蒙斯饰），克劳斯是一个神秘的木匠，独自住在一个满是手工玩具的小屋里。这几段不可思议的友谊让斯密伦斯堡又重新充满了欢声笑语，创造出了新的故事，这里有慷慨的邻居、神奇的传说和小心翼翼挂在烟囱上的长袜。《克劳斯：圣诞节的秘密》是一部节日喜剧动画片，由《神偷奶爸》联合创剧人塞尔希奥·巴勃罗斯担任导演，由琼·库萨克、威尔·萨索和诺曼·麦克唐纳徳联袂主演。', 'J·K·西蒙斯', '塞尔希奥·巴勃罗斯', 8.7, 50688, 'tt4729430', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2570825762.jpg', 0.1, 0.6, 10, 40.7, 48.6, '0.496826,-0.184101,-0.584278,0.664022,-0.033358,-0.359139,0.735765,0.231211,-0.476402,-0.213847,0.093579,0.978582,-0.243292,0.116598,0.109127,0.220122,-0.553229,-0.464840,-0.124086,-0.356881,-0.182547,-0.449144,-0.384173,-0.124757,-0.062706,-0.252102,0.361917,-0.247876,-0.079066,0.348510,0.426204,0.250512,0.139226,0.242010,-0.102024,0.070521,0.385147,-0.130711,-0.001234,0.320968,-0.239378,0.109666,-0.027397,0.002044,0.055259,0.373787,0.437308,-0.161296,0.142317,-0.049711,0.208280,-0.150556,0.112199,0.021396,0.271188,-0.098319,0.183812,0.121144,-0.248102,-0.198670,0.127543,-0.241199,-0.753481,0.114746,0.135431,0.297036,-0.493730,0.532108,-0.121854,-0.252050,0.097655,-0.457657,0.290072,0.244988,0.208648,0.355290,0.000076,-0.069749,-0.561624,0.281865,0.314807,0.001204,-0.135314,0.155523,-0.247695,-0.535829,0.076351,-0.205577,-0.540891,-0.134237,0.483551,-0.212153,0.257224,0.104975,-0.773021,-0.100919,-0.173936,-0.207956,0.031857,-0.341980,0.038804,-0.751777,0.025350,-0.195252,-0.302790,-0.048822,0.132968,-0.120544,0.696592,-0.629895,0.284060,0.563913,0.244477,0.147344,0.797019,-0.082477,0.296533,-0.086549,-0.061184,0.144972,0.300946,0.435057,0.217606,0.674180,-0.014712,-0.255503,-0.437238,0.511118', '4944008', '30162520', '10763928', '35161768');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26858594', '哥斯拉：怪兽行星', '动作', '二十世纪最后的夏天。那一天，人类终于知道自己并非地球这颗行星唯一的统治者。巨型生物「怪兽」，以及驱逐怪兽的终极存在「哥斯拉」出现了。经历与怪兽之间长达半个世纪的战争，人类屡战屡败，最终计划逃出地球。2048年，经过中央政府管理的人工智能筛选，一部分人类乘坐跨恒星移民飞船「阿拉特拉姆」号踏上了前往11.9光年之外的「鲸鱼座τ星e」的旅程。然而，人类花费20年所抵达的星球与地球之间的环境差距远超预期，不适宜人类生存。移民飞船上有一名青年——晴雄。4岁的时候，他亲眼目睹父母被哥斯拉杀害。20年来他始终想着回到地球消灭哥斯拉。移民的可能性已经灰飞烟灭，飞船内的生存环境也越发恶劣，以晴雄为中心的「重返地球派」成为主流，他们决定经过危险的长距离亚空间航行返回地球。然而，地球经过2万年的演化已经形成了以哥斯拉为顶端的生态体系，完全成为了一个未知世界。最终人类能否夺回地球？晴雄的命运又将如何？', '宫野真守', '静野孔文', 6.2, 11785, 'tt5979874', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2512149603.jpg', 1.7, 16.9, 57.2, 20, 4.3, '-0.051583,0.501566,-0.771434,0.571984,0.046978,0.003649,0.449394,-0.324382,-0.204525,-0.261229,0.075330,0.765987,0.013968,0.017310,0.305142,-0.127471,-0.135812,-0.159580,0.046375,-0.378935,-0.496914,-0.405536,-0.607514,-0.253911,0.040049,-0.478482,1.220833,0.401840,-0.115075,0.105025,-0.409773,0.175244,-0.184240,0.472507,-0.313313,-0.274250,0.089319,0.005739,-0.405955,0.233884,-0.550919,0.155413,0.501022,-0.009268,-0.404402,0.083566,0.802554,-0.700357,0.037372,-0.639761,0.390469,-0.376272,-0.201021,-0.151916,0.833312,-0.014341,-0.423431,0.231104,0.020191,0.192875,0.104635,-0.318862,-0.764244,-0.252660,-0.116720,-0.175886,-0.380838,0.294143,0.107045,-0.016930,-0.153970,-0.115559,0.151404,0.795722,0.508733,0.455538,-0.214152,0.179259,-0.456221,-0.210864,0.868485,-0.152666,-0.714840,0.217593,-0.190421,-0.861972,-0.410555,-0.697334,-0.162429,-0.039500,-0.073865,0.290411,-0.417316,0.592069,-1.007503,0.318042,-0.501412,-0.558224,0.318721,-0.247964,-0.176545,-0.536310,-0.156129,-0.369159,-0.184708,0.128722,0.082299,-0.355289,0.793348,-0.553090,0.216354,0.583288,0.676495,-0.630163,0.874207,-0.202010,0.159912,-0.617553,0.268082,0.649770,-0.224270,0.670837,-0.353437,-0.019473,0.051638,0.017287,-0.297007,0.559334', '26290398', '25827286', '26873582', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26858970', '杀人优越权', '动作', '李钟硕将加盟朴勋政执导新片[VIP]。故事讲述朝鲜某高官儿子在世界各国连续杀人，韩朝两国警方以及国际刑警对其进行追捕。李钟硕在片中饰演被追捕的连环杀人犯，这也是欧巴首次挑战反派角色。在最新电视剧《W-两个世界》杀青后，他将进入剧组进行拍摄。', '张东健', '朴勋政', 7.2, 36165, 'tt6413410', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2524177703.jpg', 1.2, 6.2, 39.2, 37.7, 15.7, '-0.249345,0.088700,-0.644904,0.498761,0.534676,0.477983,0.326084,0.088537,-0.349185,-0.011938,0.243794,0.802981,-0.640203,-0.088592,0.217111,-0.367177,-0.542889,-0.929575,-0.351906,-0.228056,0.093321,-0.268595,-0.128101,-0.207587,-0.021933,-0.199973,1.010629,-0.176685,-0.428140,0.156284,0.615449,0.306464,-0.350122,0.402766,-0.242868,0.101974,0.566038,-0.270151,-0.587245,0.631513,0.109510,-0.348196,-0.060679,0.230055,-0.047851,0.169135,0.897138,-0.338859,0.014735,-0.214118,0.666743,-0.588684,-0.472186,-0.187543,0.608406,0.219573,0.280457,0.743106,0.189126,0.141935,-0.145391,-0.405614,-0.934289,-0.061220,0.202551,0.119786,-0.524639,0.061090,-0.225445,0.258965,-0.055779,0.005840,0.332805,0.549902,0.569217,0.072321,-0.054775,0.393332,-0.007172,0.543182,0.507307,-0.160430,-0.072405,0.272984,0.385920,-0.443551,-0.195121,-0.180617,-0.134509,-0.003377,0.435906,-0.658693,-0.136596,-0.060145,-0.302039,-0.181503,-0.244700,-0.302912,0.145445,-0.305945,-0.181941,-1.313210,-0.219809,0.107008,-0.108774,-0.286109,0.338361,-0.371185,0.828502,-0.722383,-0.086488,0.687277,0.452318,-0.515201,0.638821,0.474463,-0.008873,-0.467792,-0.027948,0.023366,0.326833,0.176009,0.010149,0.349782,-0.297841,0.048255,-0.334735,0.152581', '2369613', '1322847', '24751811', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26860031', '不可抗力爱上你', '剧情', '经过了一番波折，谢炎（孟瑞 饰）和舒念（王博文 饰）总算化解了误会，重修旧好，然而，谢炎很明确的感受到，舒念对自己的态度改变了，曾经的亲密无间再也不在，取而代之的是遮遮掩掩的欲言又止。一次偶然之中，舒念和名为柯洛（周骏超 饰）的男子相遇了，和舒念一样，柯洛也是在孤儿院长大的，相似的经历很快拉近了两人之间的距离。然而，在舒念的心里，他只将柯洛当成是一个需要心疼和照顾的小弟弟，但柯洛想向舒念索取的，却是比这要多得多。终于，柯洛向舒念表白了，惊惶无措的舒念再度选择了逃避。与此同时，对现状忍无可忍的谢炎找到了舒念，坦白了自己的感情。©豆瓣', '孟瑞', '孙承志', 6.8, 8038, 'tt8937972', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2375434705.jpg', 4.4, 12.5, 38.7, 25.4, 19, '0.480932,-0.130415,-0.711847,0.537511,-0.156508,-0.561444,0.945881,0.002144,-0.549312,-0.223716,0.013610,0.605497,-0.301707,0.212530,0.226721,0.213861,0.076963,-0.710208,-0.107981,-0.099696,-0.191398,-0.681321,-0.409889,-0.128364,-0.232226,-0.137680,0.590872,0.000479,-0.514900,0.490448,0.394163,-0.067223,0.066475,0.960995,-0.448648,0.131344,-0.103055,0.204134,-0.148287,0.103481,0.319373,-0.322506,-0.323936,0.307272,-0.030765,0.493271,0.613812,-0.252966,-0.284312,0.530925,0.180158,-0.475539,-0.147054,0.125437,0.102704,0.201900,0.337821,0.097816,-0.413632,0.150329,0.145033,0.172379,-0.512450,0.060841,0.257503,-0.000274,-0.691747,0.948985,0.115721,-0.301532,0.236711,-0.481001,0.311744,0.501518,0.336645,0.437866,-0.496124,-0.059744,-0.342736,-0.002841,0.797660,0.333596,-0.167267,0.563398,-0.229474,-0.590648,-0.241584,-0.038545,-0.312228,-0.010798,0.447739,0.347738,-0.392423,0.338787,-0.627797,-0.148845,-0.074979,-0.201501,0.050569,-0.720690,0.066528,-0.251656,-0.575668,-1.041334,-0.519810,0.070365,0.008106,-0.385290,0.597142,-1.015512,0.091135,0.220103,0.278927,-0.501369,0.575255,0.353795,-0.036933,-0.011377,0.354752,0.306046,-0.004153,0.309412,0.184271,0.448109,0.066722,0.003633,-0.574037,0.644035', '1307561', '21766698', '25810920', '1304989');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26861685', '红海行动', '动作', '中东国家伊维亚共和国发生政变，武装冲突不断升级。刚刚在索马里执行完解救人质任务的海军护卫舰临沂号，受命前往伊维亚执行撤侨任务。舰长高云（张涵予 饰）派出杨锐（张译 饰）率领的蛟龙突击队登陆战区，护送华侨安全撤离。谁知恐怖组织扎卡却将撤侨部队逼入交火区，一场激烈的战斗在所难免。与此同时，法籍华人记者夏楠（海清 饰）正在伊维亚追查威廉·柏森博士贩卖核原料的事实，而扎卡则突袭柏森博士所在的公司，意图抢走核原料。混战中，一名隶属柏森博士公司的中国员工成为人质。为了解救该人质，八名蛟龙队员必须潜入有150名恐怖分子的聚集点，他们用自己的信念和鲜血铸成中国军人顽强不屈的丰碑！本片根据也门撤侨事件改编。©豆瓣', '张译', '林超贤', 8.2, 982029, 'tt6878882', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2514119443.jpg', 1, 2.5, 17.3, 41.4, 37.8, '-0.070026,-0.104694,-0.338450,0.445773,0.114847,0.005603,0.201861,-0.126323,-0.000834,-0.144778,0.602141,0.518503,0.420627,-0.253049,0.523459,-0.025625,-0.509500,-0.517696,-0.225223,-0.000199,-0.127851,-0.550621,-0.115115,-0.465942,0.179343,-0.240515,0.976868,0.211950,-0.250992,0.352620,0.218464,0.545037,-0.416505,0.327040,0.367304,-0.303295,0.725248,-0.615910,-0.365614,0.233299,-0.325992,-0.033853,0.084296,0.170321,0.397004,0.521090,0.742927,-0.390508,0.367721,-0.346950,0.032904,-0.473980,0.301123,-0.323289,0.475012,0.267428,0.000244,0.141511,0.044421,-0.001972,-0.157530,-0.205694,-0.462951,-0.349079,0.251880,0.242802,-0.174142,0.162787,-0.475291,0.537308,0.121535,-0.083121,0.099524,0.784374,0.274937,0.061275,-0.121192,0.147752,-0.455847,0.187262,0.616066,-0.397669,0.060533,-0.316243,0.167775,-0.598261,0.106053,-0.112315,0.083532,-0.107702,0.293912,-0.233934,0.259400,0.369985,-0.618724,-0.180205,-0.521669,-0.461745,0.046259,0.021734,-0.081940,-0.866865,0.438496,0.174430,-0.060918,0.223239,0.130367,0.300526,0.583028,-0.572659,-0.088639,0.590008,0.307676,-0.412011,-0.140699,-0.081808,0.240115,-0.557862,-0.014420,0.333486,0.197907,0.464750,0.133507,0.140932,0.079962,-0.458792,-0.158347,-0.041325', '2369613', '1300371', '1306809', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26862259', '乘风破浪', '剧情', '赛车手阿浪（邓超 饰）一直对父亲（彭于晏 饰）反对自己的赛车事业耿耿于怀，在向父亲证明自己的过程中，阿浪却意外卷入了一场奇妙的冒险。他在这段经历中结识了一群兄弟好友，一同闯过许多奇幻的经历，也对自己的身世有了更多的了解。', '邓超', '韩寒', 6.8, 558107, 'tt6461514', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2408407697.jpg', 3.5, 10.3, 40.7, 33.1, 12.4, '0.230823,-0.122317,-0.823868,0.690678,-0.134691,-0.215788,1.075287,-0.400424,-0.836917,-0.209182,0.431488,0.854132,-0.287685,0.128110,0.240464,-0.023739,-0.019992,-0.785847,0.132612,-0.037295,-0.290356,-0.610919,-0.534369,-0.000491,-0.264671,-0.259269,0.612977,0.358149,-0.426885,0.578066,0.234593,-0.071421,-0.147742,0.684641,0.011336,0.379979,-0.001483,0.636749,-0.320690,-0.274519,0.271967,-0.382893,-0.328641,0.317719,0.241731,0.333204,0.668186,-0.241799,-0.543365,0.214462,0.443083,-0.368052,0.056431,-0.113225,0.248282,0.349244,0.064877,0.303851,-0.053800,0.109285,-0.287457,0.138841,-0.845532,-0.022964,0.183648,0.019249,-0.979671,0.715372,0.028114,-0.146671,0.120795,-0.127135,0.125100,0.470677,0.245661,0.307521,-0.358430,-0.113007,-0.076703,0.514163,1.090064,-0.031020,0.026234,0.465658,-0.440004,-0.382493,-0.351057,-0.081696,-0.546598,0.119526,0.440795,-0.223675,-0.350857,0.584131,-0.279711,0.281691,0.028517,-0.051921,-0.030719,-0.438957,0.292629,-0.365942,-0.281128,-0.821648,-0.372347,-0.097242,-0.039718,-0.705312,0.667106,-0.710871,0.178007,0.449372,0.359929,-0.704153,0.835905,0.326015,0.151405,-0.126247,0.033860,0.306425,-0.010039,-0.026060,0.045304,0.420947,0.382052,-0.168493,-0.396600,0.265038', '25721544', '26245360', '3111650', '1292329');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26862829', '芳华', '剧情', '故事发生在上世纪七十年代，寄人篱下的少女何小萍（苗苗 饰）经过重重试炼终于加入了梦寐以求的文工团，哪知道这里和她曾经待过的那些地方并无不同，她依然得忍受遭人唾弃和欺侮的生活。唯一给过她温暖的，是刘峰（黄轩 饰），不仅仅是对何小萍，被称为“活雷锋”的刘峰把自己的爱情和温暖无私的奉献给每一个人。实际上，刘峰一直爱慕着美丽活泼的林丁丁（杨采钰 饰），当他选择将这份感情勇敢的表达出来时，却让自己的人生走向了完全不同的方向。战争开始了，刘峰、何小萍和萧穗子前赴后继的走上了前线，在枪弹和炮火之中，每一个人都在用生命和热血绽放着属于他们的芳华。©豆瓣', '黄轩', '冯小刚', 7.7, 767799, 'tt6654316', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2507227732.jpg', 1, 3.9, 27.8, 45.5, 21.8, '0.373984,0.087066,-0.866397,0.797866,-0.450359,-0.240630,1.165485,-0.088207,-0.488829,0.058778,0.111535,0.668879,-0.126452,0.410773,0.154327,0.083230,-0.179620,-0.878315,-0.301158,-0.034659,-0.438123,-0.312889,-0.258051,-0.068701,-0.165923,-0.110044,0.739322,0.204823,-0.308257,0.392693,0.269803,0.261414,0.133355,0.677470,-0.470649,0.166147,-0.238447,0.245498,-0.250344,-0.008433,0.073709,-0.406993,-0.285403,0.353424,-0.159724,0.340856,0.615706,-0.563160,-0.118393,0.003731,0.282483,-0.293875,0.055007,0.160143,-0.018590,0.101861,0.194549,0.159259,-0.057315,0.074590,0.226099,-0.078140,-0.932934,-0.132528,0.250738,0.163260,-0.809615,0.772013,0.015806,-0.122529,0.177193,-0.280601,0.415955,0.193384,0.164964,0.454553,-0.474895,-0.107156,-0.602745,0.405879,0.951818,0.204985,-0.344033,0.280854,-0.456282,-0.416370,-0.085697,-0.253872,-0.478744,-0.047597,0.142970,0.156675,-0.140772,0.108134,-0.698662,0.327895,0.150078,-0.293971,-0.020098,-0.770194,-0.110049,-0.415064,-0.178226,-0.891391,-0.634024,0.190307,-0.050451,-0.333284,0.963915,-0.975348,0.283838,0.409295,0.428880,-0.518345,0.909988,0.195622,-0.050696,-0.117225,0.048505,0.486534,-0.021668,0.477066,0.285928,0.553046,-0.126731,0.162831,-0.457399,0.876059', '24756472', '3230462', '1304641', '1417428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26862893', '极恶非道3', '剧情', '枪杀刑警片冈后，大友（北野武 饰）在韩国代理人张会长（金田时男 饰）的庇护下亡命济州岛。这个远离日本江湖的极道，却因某起事件和花菱会少壮派花田（皮埃尔泷 饰）起了冲突。此时花菱会由前任会长的女婿野村（大杉涟 饰）统领，作为若头的元老西野（西田敏行 饰）则根本不买这个外行老大的账。故而，怀恨在心的野村密谋借此次“济州岛事件”除去西野，并嫁祸张会长，谁知却很快演变成互相追杀彼此首脑的大战争。战争期间，没落的山王会图谋再起，而为给小弟报仇的大友也带着市川（大森南朋 饰）等人来到东京。秉承着仁义之心的大友，将为这个利欲熏心的黑道修罗场带来一场血腥风暴……本片为北野武“极恶非道”系列三部曲的最终章。©豆瓣', '北野武', '北野武', 7.6, 26780, 'tt6293042', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2574519850.jpg', 0.5, 3.2, 33, 44.3, 19, '-0.053776,0.118742,-0.387044,0.405993,0.179205,-0.296718,0.390253,0.283392,-0.273796,-0.383173,0.370954,0.554953,-0.030563,0.104893,0.489909,0.109107,-0.218146,-0.550898,-0.220945,-0.118688,0.082516,-0.291481,-0.248842,0.048442,-0.276774,0.125330,0.787144,0.173611,-0.232340,0.636884,0.567556,0.415368,0.035642,0.194435,0.208073,0.107121,-0.135083,0.006174,-0.416874,0.177671,-0.254290,-0.340203,-0.305356,0.054041,0.037495,0.462645,0.587294,-0.463152,-0.009142,-0.511246,0.291369,-0.429025,-0.006475,0.142782,0.504590,-0.018940,0.075639,0.404400,-0.337429,-0.021402,0.078717,0.058131,-0.639416,0.116319,0.296250,0.144789,-0.405207,0.430696,-0.010973,-0.247806,0.098803,0.045371,-0.027927,0.425676,0.314238,0.054381,-0.202239,0.179233,-0.257822,0.126108,0.473682,-0.115474,0.215688,-0.104034,0.213332,-0.378450,-0.073787,-0.366436,-0.211197,-0.204755,0.296483,-0.266479,0.258619,0.261928,-0.607156,-0.062155,-0.173160,-0.054890,0.298098,-0.072194,-0.015877,-0.661709,-0.144517,-0.302675,-0.112450,0.243427,0.320215,0.011563,0.528864,-0.685448,0.055364,0.457780,0.228592,-0.541684,0.258205,0.316989,-0.089765,-0.229786,-0.437400,-0.228769,0.216427,0.504273,0.241106,0.121426,0.119429,-0.371294,0.067198,-0.106213', '2369613', '3266509', '3861846', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26863060', '愤怒的小鸟2', '喜剧', '十年“欢喜冤家”猪鸟依旧如往常一样“互相拆台”。然而，“不速之客”发射冰球袭击了小鸟岛和猪猪岛，令双方不得不放下芥蒂，小鸟岛昔日英雄胖红联合小鸟伙伴们与曾经的对手“捣蛋猪”雷纳德一行组建了临时联盟，他们将前往全新冰封岛屿上阻止神秘反派的灭世计划。', '杰森·苏戴奇斯', '图鲁普·范·奥尔曼', 6.9, 43075, 'tt6095472', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2565068596.jpg', 0.8, 6.9, 48.1, 34.9, 9.4, '0.222026,-0.075329,-0.460427,0.348662,0.237913,0.131453,0.190788,0.020806,-0.326920,0.198420,0.127968,0.586115,-0.175644,0.233544,0.014335,-0.426630,-0.223899,-0.495346,-0.241064,-0.105616,0.098220,-0.313672,-0.442813,-0.184554,0.120331,-0.216352,0.723166,-0.224563,-0.183670,0.476442,0.229354,0.176322,-0.734792,0.168614,-0.101846,-0.159524,0.068234,0.302338,-0.603889,0.121323,-0.636091,0.341257,-0.126761,0.126841,0.065219,0.457985,0.682836,-0.957729,-0.155276,-0.842854,-0.118168,-0.436707,0.040789,0.108879,0.449279,0.124979,0.156775,0.225065,0.401338,-0.182706,-0.044970,-0.529373,0.011087,0.266354,0.260363,-0.208295,-0.368270,0.251061,0.113690,0.282817,0.319028,0.015977,0.161318,0.434246,0.542485,0.114968,-0.093943,0.217209,-0.306938,0.025239,0.799992,0.149333,-0.345549,-0.016976,0.371927,-0.211787,-0.220685,-0.374070,-0.050208,0.076069,0.329953,0.128591,-0.195160,0.400646,-1.029536,-0.044269,-0.358558,0.086368,0.052972,-0.653051,0.140107,-0.937098,0.247958,-0.065322,-0.070575,0.292646,0.213363,0.222185,0.726222,-0.781650,0.199361,0.297282,0.505291,-0.235702,0.203159,0.053993,-0.174492,-0.536314,0.297580,0.008341,0.220119,0.419542,0.369608,-0.097065,-0.498379,-0.054073,-0.280548,0.085233', '30290068', '26290398', '1458910', '1303910');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26863778', '铁雨', '动作', '原朝鲜侦察总局特工严铁雨(郑雨盛 饰)受到征召前去位于朝韩边境的开城工业园区刺杀意图政变的朝鲜高官，不料却在开城遇袭，迫使他带着重伤昏迷的朝鲜最高领导人逃往韩国，局势突变，朝鲜半岛站在了核战争的边缘，中美日皆卷入乱局，他只能与韩国外交安全首席秘书郭哲宇(郭度沅 饰)合作，将半岛从核战边缘拉回', '郑雨盛', '杨宇硕', 8.2, 120355, 'tt6769508', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2505050710.jpg', 0.3, 1.2, 17, 50.3, 31.2, '-0.015460,0.205707,-0.872862,0.477071,0.459618,0.115085,0.142621,0.575350,-0.434206,0.002674,0.406379,0.695400,0.054371,-0.501937,0.456540,-0.071948,-0.368851,-0.773359,-0.367649,0.137150,-0.345845,-0.237621,-0.226169,-0.103666,-0.156959,-0.182849,0.810836,0.351759,-0.704189,0.505168,0.324785,0.489734,-0.527544,0.686457,-0.058537,-0.416133,-0.021730,-0.485395,-0.621640,0.380927,-0.063701,-0.761564,-0.274785,-0.019791,0.348030,0.448953,0.655810,-0.442759,0.315944,-0.011210,0.121903,-0.677809,-0.136142,0.090369,0.619696,0.070118,-0.540841,0.093232,-0.274701,0.286834,0.215024,-0.132682,-0.268169,0.033831,-0.143965,0.229394,-0.483460,0.595127,-0.207811,0.099952,0.122022,-0.125817,0.418760,1.086632,-0.390391,-0.000282,0.089057,0.459840,-0.426379,-0.086569,0.610902,-0.012961,-0.051239,-0.431636,0.163357,-0.590058,-0.085789,-0.327930,-0.059587,-0.095755,0.469941,-0.495980,0.051660,0.224928,-0.360693,-0.204254,-0.394063,-0.473367,0.140157,0.108014,0.076398,-0.723764,-0.027952,-0.198045,0.017695,0.227215,0.082019,0.647059,0.290846,-0.467058,-0.172707,0.490164,0.568700,-0.613516,0.223606,0.431683,0.374632,-0.237272,-0.172408,0.296651,0.219414,0.982058,0.105856,-0.040869,-0.380481,-0.332366,-0.283715,-0.277843', '25900819', '1307201', '4193254', '1424552');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26864096', '亚人 真人版', '剧情', '在一场车祸中，永井圭（佐藤健 饰）意外发现自己竟然是一名“亚人”。亚人，拥有着和人类一样的外貌，却有着惊人的自愈能力和不死之身，为了获得亚人神秘的力量，政府逮捕并监禁了现今已经发现的亚人们，包括永井圭，在他们身上进行残忍的活体实验，然而对外，政府却声称这一行为是在保护亚人。同样身为亚人的佐藤（绫野刚 饰）救出了永井圭，希望后者能够加入自己的阵营。佐藤依靠着进行恐怖活动来威胁政府，提出建立亚人自治区的诉求。永井圭知道佐藤生性贪婪邪恶，不愿意就范，因此亦被佐藤视为敌人。身处漩涡的中心，永井圭知道，这并不单单只是佐藤和自己的战争，而是人类和亚人之间的博弈。©豆瓣', '佐藤健', '本广克行', 6.8, 15614, 'tt6215712', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2497206856.jpg', 1.8, 8.8, 45.6, 33.4, 10.4, '0.393622,0.201406,-0.662781,0.615503,-0.284226,0.010299,0.594316,-0.071247,-0.396039,-0.552449,0.157806,0.779165,0.284664,-0.058680,-0.055226,-0.023274,-0.155486,-0.510335,-0.349702,0.084963,-0.169508,-0.857803,-0.371742,-0.224731,-0.246556,-0.506569,0.846001,0.206060,-0.641793,0.567706,0.297526,0.599809,-0.051628,0.455807,0.193012,-0.182615,-0.124107,-0.177255,-0.305197,0.284532,-0.169847,-0.114805,-0.002366,0.587202,-0.001659,0.412391,0.387743,-0.647893,-0.096776,-0.430128,0.372224,-0.583325,-0.061395,0.353549,0.417686,-0.204606,0.145676,0.260800,0.017109,0.159393,0.314231,0.015187,-1.309564,-0.120923,0.030526,0.339040,-0.392064,0.493219,-0.017514,-0.184111,0.246655,0.027557,0.043585,0.511893,0.242553,0.353849,-0.310499,0.105433,-0.640767,-0.357287,0.845734,-0.140849,-0.299345,0.289356,-0.490135,-0.803128,-0.437636,-0.645838,-0.160562,-0.163802,0.012574,0.319722,-0.045082,0.284123,-0.528055,-0.001187,0.048161,-0.093043,0.141197,-0.366750,0.212923,-0.462754,-0.129620,-0.559041,-0.597030,0.335242,-0.056173,-0.556219,0.634703,-1.182765,0.083753,0.758033,0.528605,-0.587790,0.461576,0.324087,-0.120424,-0.161179,-0.434849,0.324213,0.503628,0.264102,0.041293,0.050075,0.235257,-0.083100,-0.218681,0.299663', '1793491', '1811755', '1294893', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26864182', '一纸婚约', '剧情', '叶子（刘熙阳 饰）为了买房和男朋友（张一山 饰）结婚，不惜与大学教授王枫（张辉 饰）假结婚，看似一切进展顺利的时候，却遭遇男友移情别恋，这令叶子万念俱灰，只能靠酒精来麻痹自己，与此同时，王枫因为一场意外成为了植物人，而此时婚约还未解除，面对瘫痪在 床的“半路夫妻”年轻迷茫的叶子将何去何从？', '刘熙阳', '张辉', 2.7, 7368, 'tt9496844', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2524311102.jpg', 77.9, 11.6, 8.1, 0.6, 1.7, '-0.004673,0.206659,-0.793800,0.162657,-0.442305,-0.051902,0.536876,0.253511,-0.603993,-0.343797,0.202892,0.321079,-0.218912,0.130873,0.151760,-0.099318,-0.018485,-0.745677,0.324839,0.152575,-0.428371,-0.491370,-0.395550,-0.153431,-0.307726,-0.476899,0.783422,0.300701,0.006251,0.738828,0.292743,0.001582,-0.211289,0.673731,0.157406,-0.100688,0.051307,0.404341,-0.396864,0.012504,0.019309,-0.331432,0.199382,0.168902,-0.067701,0.473877,0.678322,0.069458,-0.087636,-0.265663,0.271433,-0.298129,-0.027366,0.505230,0.453745,-0.201664,0.463592,-0.072536,-0.317286,-0.225455,0.388459,0.001394,-0.673802,0.333398,0.012413,0.082049,-0.576414,0.452970,-0.460902,0.125873,0.247121,-0.499572,0.254465,0.684910,0.647556,0.553487,-0.532033,0.055232,-0.396168,-0.019162,0.814696,0.146151,0.012535,0.457707,-0.225184,-0.100127,-0.120070,0.187023,-0.231656,0.159397,0.162279,0.111321,-0.223727,0.204056,-0.309850,-0.170537,-0.317551,0.217050,0.152799,-0.689585,-0.333286,-0.045967,-0.063687,-0.189585,-0.370201,0.083478,0.220941,-0.358966,0.312723,-0.779385,0.144831,0.243013,0.298057,-0.552234,0.249025,0.188751,0.048785,-0.402524,-0.182886,0.232959,-0.234270,0.194379,0.331161,0.050912,-0.101694,0.262576,-0.145161,0.182129', '1301022', '35030151', '30345227', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26868553', '深夜食堂', '剧情', '在上海一条不起眼的小弄堂里，有一家只在深夜营业的小餐馆，老板是一位50岁左右的大叔，他会为每一个到访的食客做一份只属于他（她）的食物，一碗饭一个故事，一碟菜一段人生，暖心抚慰都市夜归人。大叔随着食堂的夜晚一起经历人来人往，满足食客们的味蕾，也见证了各式人生。而无论夜多深、路多远，大叔还会在食堂里继续倾 听大家的故事。', '梁家辉', '梁家辉', 4.9, 32257, 'tt10904418', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2566158271.jpg', 14.2, 40.1, 35.6, 8.1, 2, '0.374597,0.009509,-0.035623,0.342114,-0.022045,-0.200451,0.957172,0.513524,-0.364629,-0.022434,0.366104,0.865842,-0.026258,0.561074,0.374359,-0.104642,-0.166019,-0.398042,0.033216,-0.286791,-0.120053,-0.167083,-0.125284,-0.308568,-0.211630,0.265815,0.062134,0.127170,0.135787,0.221484,0.245990,-0.571914,-0.086481,0.247234,-0.447497,-0.048414,0.351641,-0.066720,-0.225481,0.002765,-0.152918,-0.437924,-0.409762,-0.122235,0.130101,0.086995,0.723415,-0.020921,-0.518372,0.029492,0.264151,0.236360,-0.100666,-0.143094,0.215542,0.101031,0.569409,0.037446,-0.234993,0.281545,-0.159329,-0.202647,-0.664090,-0.290930,-0.164370,0.221980,-0.550690,0.501723,0.375081,-0.062374,0.364460,-0.457996,0.165998,-0.086726,0.157356,0.737521,0.090459,-0.054652,-0.518998,0.292033,0.846830,0.125798,0.074171,0.427900,-0.283881,-0.249437,0.057084,0.158301,-0.718845,0.123801,-0.262763,-0.143745,-0.176241,0.168855,-0.879830,0.540397,-0.078569,-0.591902,0.345744,-0.059751,-0.606612,-0.726762,0.170760,-0.023497,0.061521,0.507975,0.364290,0.107493,0.940468,-0.577862,0.286012,0.334013,0.001879,-0.048642,1.074827,0.089945,0.109641,-0.152681,-0.016981,0.004229,-0.253911,0.002745,0.123338,0.735530,-0.209617,-0.009320,-0.794323,0.253626', '1309101', '1306860', '2081098', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26869119', '念念手纪', '剧情', '由于高中时代同班同学山内樱良（滨边美波 饰）的一席话，我（小栗旬 饰）最终成为母校的一名教师。在和学生栗山聊天的时候，我不经意想起了与樱良共度的那几个月时光。当年，我（北村匠海 饰）偶然发现樱良的秘密。她罹患了严重的胰脏疾病，不知何时起她动笔写下了抗病日记。疾病并没有击倒这个活泼开朗的女孩，她反而展露出愈加灿烂的笑容。与之相对，我更多地活在自己的世界中，鲜少与人交往。在日记的帮助下，我们的人生轨迹短暂地交回到了一起。我与她共度有限的每一天，直到那份快乐自在戛然而止……本片根据住野夜的同名小说改编。©豆瓣', '滨边美波', '月川翔', 6.6, 24780, 'tt6078840', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2531648684.jpg', 1.9, 12.7, 46.6, 28.9, 10, '0.111814,-0.054042,-0.729892,0.645354,-0.194494,-0.348703,0.943280,0.057263,-0.240106,-0.129654,0.116511,0.867802,-0.204954,0.489295,0.196451,-0.144564,-0.241048,-0.680434,0.169304,-0.392040,-0.191011,-0.225923,-0.261539,-0.018735,0.048138,-0.469967,0.649750,0.123775,-0.085723,0.425843,-0.012358,0.093784,-0.264869,0.511066,-0.295644,0.185605,-0.139551,0.309707,-0.238424,0.033411,0.142771,-0.434651,-0.325259,-0.009056,-0.034333,0.133044,0.801084,-0.279270,-0.452415,0.120424,0.476924,-0.002463,-0.079778,-0.048225,0.164653,0.036175,0.224322,0.360237,-0.285070,0.032740,0.017881,-0.133135,-0.672362,-0.098256,0.095024,0.253581,-0.416181,0.665542,-0.024015,-0.024491,0.178390,-0.315676,0.046604,0.494252,0.191592,0.257510,-0.306932,-0.053917,-0.277257,0.456075,0.605919,0.104680,-0.420148,0.582911,-0.170294,-0.421134,-0.067740,0.028528,-0.312741,0.153838,0.300829,0.007107,-0.282251,0.268402,-0.531390,0.134102,0.190763,-0.039107,0.081832,-0.401465,-0.104578,-0.522716,-0.194905,-0.442495,-0.518417,0.107685,-0.000826,-0.401666,0.987035,-0.999121,0.380410,0.491554,0.331661,-0.256298,0.632054,0.284953,0.030478,-0.145301,-0.041686,0.373176,0.064062,0.428339,0.187471,0.410971,-0.102660,0.205586,-0.733811,0.607270', '1292219', '3811356', '1307755', '4724586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26870023', '换季期', '剧情', '韩国演员裴宗玉、李源根及池允浩出演的影片，影片《换季》主要讲述一位母亲得知儿子与朋友之间的秘密后，三人之间的故事。演员裴宗玉将在影片中饰演母亲美婧，池允浩将饰演儿子秀贤，李源根则饰演秀贤的朋友勇俊', '裴宗玉', '李东恩', 7.7, 6932, 'tt6165466', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2512189868.jpg', 0.4, 2.6, 28.8, 48, 20.2, '0.087605,-0.327636,-0.112580,0.882888,0.554907,-0.108865,0.580711,0.110238,-0.386292,-0.454841,0.227289,0.915833,-0.328842,0.159192,0.583158,-0.228114,-0.370530,-0.732131,-0.521743,0.039635,0.046797,-0.280381,-0.153160,0.057444,-0.340865,-0.389246,0.957489,-0.463372,-0.062040,0.314390,0.577636,0.074055,-0.663286,-0.270599,0.452188,0.481221,0.376958,0.108418,-0.789752,0.353014,0.148304,-0.144473,0.000666,0.147664,-0.056179,0.380590,0.692497,0.002198,0.206268,-0.096566,0.507874,-0.128225,0.169713,-0.139071,0.091034,0.410231,1.045688,0.470975,0.021902,-0.038395,-0.321672,-0.423937,-0.597000,-0.013251,0.471984,-0.106014,-0.199502,0.198460,0.022918,-0.011908,0.535892,-0.320129,0.476926,0.122578,0.493364,0.232826,-0.348984,0.147073,0.234199,0.650126,0.478487,-0.002830,0.461945,0.735198,-0.129828,-0.479434,-0.328302,-0.078456,-0.725844,0.508950,0.103257,0.004712,-0.186273,0.255356,-0.140658,-0.427776,0.243469,0.157205,0.397217,-0.240526,0.196170,-0.600617,-0.375935,-0.050502,0.125626,-0.466619,0.129923,-0.513763,1.052938,-0.505730,0.044857,0.407429,0.151134,-0.376886,0.849132,0.050460,0.389060,-0.727387,0.158375,0.076776,0.093241,-0.503612,-0.079446,0.010726,-0.605899,-0.255644,-0.522900,0.022027', '26980827', '30488003', '1322847', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26870196', '散步的侵略者', '剧情', '在设计公司上班的加濑鸣海（长泽雅美 饰）早就和丈夫真治（松田龙平 饰）的爱情走向破裂，可是在丈夫走失再回来的时候，她却发现对方似乎丧失了记忆，对周遭一切都懵懂无知。与此同时，城市内姓立花的人家发生血腥的杀人案，作为重要嫌疑人的学生妹立花明（恒松佑里 饰）则下落不明。周刊记者樱井（长谷川博己 饰）受命前往案发现场，却遇到了举止怪异的青年天野（高杉真宙 饰）。天野自称来自外星，他和包括立花在内的同类们正筹划入侵地球。半信半疑的樱井随其踏上寻找立花的旅途，而另一边的鸣海也对丈夫的真实身份产生了质疑……本片根据劇団イキウメ的负责人前川知大2005年首演的舞台剧、并于2007年出版的小说改编。©豆瓣', '长泽雅美', '黑泽清', 6.2, 6936, 'tt5999530', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2539021264.jpg', 3.2, 18.4, 50.4, 21.8, 6.2, '0.262065,-0.122564,-0.458978,0.126412,-0.022698,-0.044379,0.529492,0.041104,-0.364163,-0.551276,0.340051,0.591522,-0.174591,0.273172,0.325108,0.140455,-0.335257,-0.662490,-0.089132,-0.145546,0.022746,-0.373969,-0.223078,-0.053795,-0.017374,-0.249498,0.781466,0.057791,-0.286950,0.594308,0.235578,0.371866,-0.350374,0.220658,0.108139,0.194422,0.034622,0.189632,-0.113185,0.037075,-0.308639,-0.212948,-0.214759,0.092236,0.028081,0.545913,0.684523,-0.148632,-0.325497,-0.012620,0.433122,-0.231841,0.019828,0.215785,0.479604,0.113602,-0.070778,0.294235,-0.302442,-0.034544,-0.024911,0.102496,-0.581772,0.011209,0.128072,0.384888,-0.239505,0.390923,-0.107089,-0.287136,0.328791,-0.434978,-0.022023,0.176336,0.343421,0.286627,-0.151477,0.161155,-0.091789,0.136515,0.368878,0.120268,-0.142486,0.250598,-0.162484,-0.285161,-0.359366,-0.223346,-0.398252,0.045530,0.015056,0.222590,-0.058373,0.251161,-0.469667,-0.065083,0.006796,-0.325408,0.165178,-0.273237,-0.296162,-0.728077,-0.036216,-0.517921,-0.323988,0.015722,0.255200,-0.268982,0.786305,-0.773328,0.136543,0.559326,0.269363,-0.546024,0.383674,0.156483,-0.259480,-0.243596,-0.202683,0.377346,0.082889,0.416394,-0.080282,0.132622,-0.103401,-0.373758,-0.452639,0.243726', '3811356', '2369613', '25922902', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26871465', '抵达之谜', '剧情', '上世纪90年代长江边的小城里，反骨叛逆的男孩赵小龙（李现 饰）遇上心爱女孩冬冬（顾璇 饰）及其好友小梅（张绮烟 饰）后，随着初心萌动，与几位好友：方圆（董博睿 饰）、大四（林晓凡 饰）、三皮（刘韦伯 饰）、武义（李宗雷 饰）走过肆意张扬的青春时光。这段青春最终因为冬冬的失踪戛然而止，十几年后，当兄弟们都面目模糊的走向中年时，只有小龙还固执地要为下落不明的冬冬讨个说法。聚会上，步入中年的四人回忆往昔，小龙却突然逼大四说出冬冬 “失踪”的真相，被尘封的“真相”，令他们永远无法抵达自己的内心……', '李现', '宋文', 4.7, 42687, 'tt9081510', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2614691271.jpg', 21.4, 40.1, 25.3, 6.8, 6.4, '0.200395,0.219357,-0.546088,0.258313,-0.047692,-0.576409,0.694459,-0.143573,-0.641902,-0.270223,0.008614,0.206976,-0.418118,0.618639,0.320791,-0.119168,-0.133130,-0.675130,-0.183756,-0.219875,-0.141575,-0.167043,-0.099987,0.235881,-0.325313,0.053705,0.536183,-0.027171,-0.000108,0.670614,0.354458,0.252899,-0.148601,0.107106,-0.062297,0.139355,0.167532,0.084874,-0.189602,-0.295456,-0.057808,-0.335391,0.004676,-0.091109,-0.214266,0.237284,0.943117,-0.123702,0.028703,-0.152741,0.271208,0.046002,-0.288489,0.220819,0.172578,0.186052,0.352009,0.173797,-0.143439,0.074875,-0.060459,-0.080995,-0.242819,0.310579,0.202127,0.072359,-0.391894,0.073054,0.060918,-0.027755,0.409987,-0.559232,0.111228,0.107906,0.193097,0.469515,-0.209787,0.029599,-0.351526,0.414952,0.552309,0.100852,-0.205666,0.173572,-0.090615,-0.259721,0.123715,0.064418,-0.477938,0.184509,0.193176,0.141099,-0.045699,0.277296,-0.473936,-0.062033,-0.261273,0.190264,0.103143,-0.057697,-0.519449,-0.352093,-0.209946,-0.684702,-0.214020,0.192116,-0.062264,-0.066926,0.723732,-0.571431,0.250782,0.047648,0.180580,-0.172998,0.516857,0.161914,0.313838,-0.300367,0.131065,0.505104,-0.226062,0.221950,-0.087366,0.171825,-0.410792,-0.066143,-0.371598,0.369586', '24839498', '2365260', '5977789', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26871669', '如影随心', '剧情', '小提琴家陆松（陈晓 饰）与室内设计师文罂（杜鹃 饰）巴黎邂逅，不打不相识，彼此迷恋越陷越深。爱情之名怂恿着他们为爱再大胆一次，走出各自问题满满的情感关系。仿佛只要现任变前任，幸福就唾手可得。然而前任们也都是战士，文罂的前任郑可（华少 饰）是个理性至极的医生，陆松的前任刘娟（马苏 饰）则在情感社区开启了喋喋不休的骂战，是继续坚持对爱的信仰，还是选择放下与原谅重新开始？现代都 市情感危机在北京与巴黎街头上演。越是深爱的，往往也正是痛苦的源头，爱情，像是影子，抓不住却也离不开，如影随心…©豆瓣', '陈晓', '霍建起', 4.7, 22737, 'tt10126628', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2553279350.jpg', 23.4, 35.6, 27.8, 9.5, 3.7, '0.165639,0.171137,-0.685123,0.541591,-0.002669,-0.351760,0.629989,0.028051,-0.324958,-0.088458,0.044207,0.505775,-0.028836,0.519575,0.240617,-0.161485,-0.197007,-0.785220,0.147514,-0.123722,0.050130,-0.361218,-0.041771,-0.073267,-0.044921,-0.289104,0.664939,0.287097,-0.240457,0.368418,0.621309,0.446220,-0.083783,0.468835,0.014425,-0.206775,-0.067054,0.225488,-0.617930,-0.120877,0.017821,-0.116112,-0.097028,0.247458,-0.127980,0.099769,0.554541,-0.289444,-0.246742,-0.192589,0.303451,-0.243744,0.043343,0.045748,0.053142,0.094846,0.174905,0.371298,0.015416,0.089579,-0.015943,0.034829,-0.620062,-0.007298,0.213278,0.185794,-0.471782,0.413484,-0.125698,-0.055605,0.022817,-0.135166,0.235147,-0.021464,0.474089,0.494874,-0.468413,0.069212,-0.399208,0.168097,0.666827,0.301613,-0.344728,0.458741,-0.192902,-0.318724,-0.014717,-0.203122,-0.376707,-0.118753,-0.120990,0.255473,-0.005124,0.229619,-0.618790,0.240256,0.131324,0.087491,0.252217,-0.537677,0.178569,-0.440010,-0.143225,-0.491407,-0.058233,0.155566,0.024777,-0.310575,0.712269,-0.557535,0.263638,0.295905,0.376461,-0.741583,0.683743,0.577246,-0.123187,-0.279900,-0.044638,0.582842,-0.121058,0.026712,-0.102259,0.135000,-0.009367,0.098573,-0.283813,0.562360', '4301278', '25777330', '1418613', '26021055');
