INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26871938', '灭绝', '科幻', '一位未来的工薪阶层父亲反复梦到被未知力量摧毁。当他的噩梦开始影响自己与家人的关系时，他便很快意识到，外星人的无情攻击开始摧毁地球，而这些噩梦也许是骇人现实的关键线索。随着入侵者一波又一波的凌厉攻击，他必须寻找保护家人的力量，并弄清自己的真实身份。', '迈克尔·佩纳', '本·扬', 5.5, 19089, 'tt3201640', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2579512247.jpg', 5.5, 31, 48.7, 12.2, 2.6, '0.269582,0.314228,-0.514510,0.657603,-0.365465,0.070932,0.957677,-0.024032,-0.504175,-0.542991,0.433295,0.559128,0.148675,0.157856,-0.070986,0.071086,0.165841,-0.764019,0.195279,0.034584,-0.513486,-0.475640,-0.506353,-0.162509,0.427726,-0.417232,0.643960,0.211966,-0.547166,0.083169,0.042447,0.204378,-0.149447,0.998980,-0.090783,-0.114196,-0.257580,-0.068672,-0.489724,0.026807,0.033003,-0.362363,0.067202,0.795781,-0.656270,0.501242,0.666800,-0.306819,-0.158414,-0.212616,0.445386,-0.398475,0.017183,0.319106,0.499519,0.196695,0.013575,0.138355,0.091104,0.007162,-0.242483,0.292050,-1.210335,-0.247242,0.219842,-0.007671,-0.226498,-0.042435,0.106498,0.136719,0.016433,-0.148532,0.220179,0.384316,0.234948,0.495376,-0.734081,-0.050213,-0.226030,0.041708,1.113662,-0.390944,-0.461335,0.531927,-0.073186,0.028076,-0.152663,-0.284813,-0.253033,0.171761,0.344812,0.771234,-0.357543,0.747359,-0.600191,0.033683,-0.514881,-0.209601,-0.330967,-0.664531,-0.049944,-0.303830,-0.288245,-0.325192,-0.185307,0.054150,0.004541,-0.104181,0.708199,-0.539649,0.181430,1.274600,0.382066,-0.653272,0.045727,0.133535,-0.022749,-0.410162,0.068636,0.454069,0.111448,0.481908,-0.152415,-0.021989,0.128874,0.339710,-0.123192,0.970952', '4820775', '30368448', '25828589', '27186354');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26873577', '昼行闪耀的流星', '爱情', '与谢野雀（永野芽郁 饰）自幼无拘无束的生长在乡间，性格天真而又开朗。雀考上了位于东京的高中，这也就意味着，她要离开父母，前往这座繁华而又时尚的城市，独自开始新的生活。然而这生活在一开始似乎就并不顺利，在前往叔叔家的路上，雀晕倒了，幸运的是，她遇见了名为狮子尾五月（三 浦翔平 饰）的男子。雀惊讶的发现，狮子尾的后颈上有一颗似曾相识的痣。第二天来到学校，雀发现，狮子尾竟然就是自己的班主任。之后，她还和邻座的马村大辉（白滨亚岚 饰）结下了一段友谊。随着时间的推移，雀和狮子尾以及大辉之间的关系渐渐暧昧起来，夹在两个男人之间，雀不知道该做出怎样的选择。©豆瓣', '永野芽郁', '新城毅彦', 6.4, 7764, 'tt6078842', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2403282874.jpg', 2.6, 15, 52, 21.8, 8.6, '0.434191,0.056800,-0.586033,0.704152,0.225557,-0.193486,0.651239,0.209088,-0.304963,0.008466,-0.046934,0.624325,-0.200253,0.444024,0.339819,0.163074,-0.108001,-0.680408,0.172339,-0.241330,-0.327471,-0.399226,-0.041728,0.069312,0.145120,-0.146091,0.700914,0.164116,0.000804,0.815151,0.314065,0.002286,-0.166375,0.274062,-0.470581,0.031881,0.089271,0.314907,0.325796,-0.052953,0.184645,-0.274890,-0.098848,0.097139,0.090544,0.265608,0.790477,-0.281302,-0.373225,-0.038915,0.350894,-0.014860,-0.034733,0.178826,0.642117,-0.125294,0.147018,0.047062,-0.249388,0.149204,-0.085102,-0.188511,-0.222692,0.286192,-0.212663,0.210761,-0.592476,0.670223,0.306979,-0.278930,0.342491,-0.460659,0.155685,0.656891,0.195797,0.430603,-0.189739,-0.020071,-0.334993,-0.085224,0.944216,-0.032448,-0.170471,0.498461,0.003667,-0.551063,-0.236153,0.003692,-0.084466,-0.298280,0.281203,0.237781,-0.265734,0.157079,-0.732020,0.266382,-0.009634,-0.003341,0.182549,-0.325919,-0.214902,-0.354266,-0.155559,-0.816310,-0.231180,0.422969,-0.060126,-0.372376,0.597385,-1.175431,0.349446,0.318604,0.376503,-0.347757,0.625721,-0.111829,0.126880,-0.247496,0.086415,0.212557,0.068272,0.310672,0.191704,0.404094,-0.043856,-0.191855,-0.446913,0.587163', '1292219', '35030151', '21766698', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26873582', '侏罗纪世界3', '动作', '影片为《侏罗纪世界》系列的完结篇，故事的开篇设定在纳布拉尔岛被摧毁的四年后。如今，恐龙在世界各地与人类共同生活、共同捕猎。这一脆弱的平衡将重塑未来，并最终决定人类能否与史上最可怕生物共享这颗星球，并继续站在食物链的顶端。', '克里斯·帕拉特', '科林·特莱沃若', 6.1, 210919, 'tt8041270', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2873135507.jpg', 3.6, 19.4, 52.8, 19.5, 4.8, '0.067027,0.509519,-0.735071,0.737077,0.228717,0.001558,0.634517,-0.071991,-0.404729,0.075390,-0.088083,1.017114,-0.145425,0.235264,0.294261,-0.103894,-0.445068,-0.248759,-0.132847,-0.175824,-0.515504,-0.426935,-0.506423,-0.222493,-0.243393,-0.489272,1.358281,0.135215,-0.486197,-0.073861,-0.087593,0.300639,-0.427566,0.226903,-0.155827,-0.412087,-0.140888,-0.061119,-0.819553,0.169079,-0.330231,-0.004439,0.256573,0.309900,-0.339416,-0.265805,0.828533,-1.086070,-0.187059,-0.508992,0.436924,-0.166629,0.064102,-0.125454,0.419206,-0.311496,0.070242,0.497250,0.072004,0.161268,0.168732,-0.455673,-1.160162,-0.423240,0.119303,-0.077486,-0.418624,0.664061,0.314346,-0.071968,0.151733,-0.279632,0.218973,0.768041,0.615724,0.326323,-0.247013,0.073931,0.011854,0.156249,0.500862,0.110930,-0.543273,0.515445,0.015239,-0.854249,-0.745258,-0.286799,-0.320839,-0.139666,0.156057,0.490055,-0.420455,0.749223,-1.217409,0.356815,-0.108380,-0.521439,0.347144,-0.540686,-0.143699,-0.670505,-0.030119,-0.095686,0.071880,0.102897,0.147215,-0.412150,0.988993,-0.742602,0.421939,0.549633,0.290336,-0.496349,0.631542,-0.045439,0.246453,-0.691988,-0.063392,0.666661,0.109278,0.605661,-0.134625,0.014981,0.062961,0.208509,-0.858279,0.959158', '26759819', '26759820', '26290398', '25890017');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26873799', '龙之战', '动作', '1885年，法军进攻越南凉山，驻守清军不战而退，清朝政府的统治地位遭到威胁，慈禧召集众臣商讨派谁挂帅，最终启用了年近七旬的退隐老将冯子材（刘佩琦 饰），但当时广西军民已被法军的残忍手段吓破胆，有严重畏战情绪。为了激励军民，冯子材出奇兵成功伏击攻克龙临镇的北非雇佣军，生擒黑人上尉克拉克，并当众与其决斗，刀斩悍敌，振奋军心。冯子材亲自勘察地形，修建关前隘，率领人马伏击尼格里的炮弹运输船，不料落入尼格里的陷阱，损失惨重。依南也遭法军生擒，所幸法军驻地的越南女子阮月偷偷放走了她，还给她指引了去找黑旗军将领刘永福的道路。被激怒的尼格里，不等炮弹和援军到来，就对关前隘发动了全面攻击，冯子材持刀率先杀敌，全军振奋，猛烈出击，与法军进行一场惨烈的白刃格斗……', '刘佩琦', '高峰', 6.4, 8720, 'tt7345928', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2495031914.jpg', 4, 13.6, 48.5, 25.2, 8.7, '-0.103814,-0.213597,-0.666267,0.466159,0.226879,0.301091,0.132587,-0.052343,-0.255392,0.067297,0.412957,0.190333,0.321403,-0.601583,0.132471,-0.351739,-0.164795,-0.735425,-0.133964,0.115010,-0.114784,-0.133003,-0.127663,-0.352377,0.151297,-0.349918,0.596943,0.434956,-0.352962,0.449080,0.062552,0.275442,0.171240,0.588004,0.278970,0.082533,-0.112787,-0.687394,-0.285515,0.269368,-0.503411,-0.524828,-0.329063,0.094005,-0.096050,0.526135,0.532146,-0.178090,0.022289,0.032515,-0.212180,-0.504328,0.199782,0.312084,0.561646,0.151599,-0.368298,-0.095954,-0.046594,0.070125,-0.428933,-0.052748,-0.448426,0.060872,-0.045577,-0.432644,-0.319592,0.478326,-0.238750,0.509957,0.034115,-0.152791,-0.008581,0.716309,0.245892,-0.166356,-0.225843,-0.090494,-0.379778,0.032680,0.669423,-0.387988,-0.073610,-0.684037,0.086949,-0.319998,0.340679,-0.439637,-0.084354,0.159049,0.480772,-0.322951,0.143700,0.143570,-0.407201,-0.008036,-0.758095,-0.079940,-0.101477,0.013802,-0.000841,-0.648377,0.025108,-0.113544,-0.180219,0.363082,0.114673,0.593503,0.406276,-0.323452,-0.276472,0.459943,0.449226,-0.613727,0.163361,0.205790,-0.055603,0.286584,0.221587,0.340650,0.217791,0.517809,0.297239,0.077147,-0.305960,-0.275785,-0.040774,-0.047432', '1307201', '34906611', '1434172', '27063335');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26874517', '哥哥太爱我了怎么办', '剧情', '橘濑户花（土屋太凤 饰）是一名活泼可爱的高中女生，一天，她鼓足了勇气向剑道部的铃木告白，谁知道遭到了对方的拒绝。截止到目前为止，这已经是橘濑户花第12次告白失败了，百思不得其解的橘濑户花决定向铃木问个明白，才知道原来自己一直差劲到底的桃花运，和自己的哥哥橘遥（片寄凉太 饰）有关。一天，橘濑户花和名为芹川高岭（千叶雄大 饰）的男子重逢了，高岭是橘濑户花曾经的初恋对象， 如今他再度出现在她的身边，还对她展现出了别样的热情，这一切让橘濑户花的内心开始骚动起来。与此同时，橘遥震惊的发现，自己和妹妹其实并没有血缘关系。©豆瓣', '土屋太凤', '河合勇人', 6.4, 35497, 'tt6075764', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2446655373.jpg', 3.9, 16.1, 48.3, 21.4, 10.3, '0.040719,0.101095,-0.818281,0.458308,-0.129743,-0.512621,0.652968,-0.164661,-0.363854,-0.401767,0.044177,0.408620,-0.360312,0.347081,0.465273,0.337292,0.179021,-0.898507,-0.165296,-0.326706,-0.289634,-0.515315,-0.230411,0.088563,-0.147562,-0.055351,0.551739,0.143386,0.027067,0.546378,0.904268,0.268906,0.496572,0.498558,0.141141,0.410557,-0.190204,0.332844,0.116871,0.138847,-0.099735,-0.477399,-0.516435,0.303711,0.279107,0.297345,0.495912,-0.079870,-0.238453,0.054778,0.400204,-0.185026,-0.122540,0.237995,0.481247,-0.374592,-0.030997,-0.273768,-0.390598,-0.210302,0.108263,0.131659,-0.535317,0.037281,0.090149,0.139989,-0.570688,0.444161,-0.037046,-0.110854,0.294965,-0.457888,-0.084897,0.233770,0.427283,0.181618,-0.338641,-0.211927,-0.161326,0.007202,0.784096,0.039836,-0.099676,0.503466,-0.222756,-0.401186,-0.695756,-0.029749,-0.094453,0.077298,0.026410,0.325183,-0.131996,-0.045069,-0.547302,-0.313326,0.090879,-0.206359,0.222057,-0.505775,-0.053209,-0.164376,-0.143444,-0.825835,-0.447237,0.278493,-0.018684,-0.430108,0.920810,-1.102945,0.028769,0.563003,0.275493,-0.276201,0.402339,0.252496,-0.606890,-0.142752,-0.197699,0.277356,0.104356,0.286785,0.346408,0.485974,0.050965,-0.121158,-0.564077,0.091511', '1826173', '35030151', '26354526', '1292219');
