INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26876180', '年少轻狂', '喜剧', '两个行事冲动的爱尔兰年轻人偷了一辆自行车前往海边，想从走私者翻覆的船里找到一包可卡因。', '亚历克斯·墨菲', '彼得·福特', 8.1, 13536, 'tt4714568', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2387703467.jpg', 0.3, 1.5, 21.2, 47.3, 29.6, '0.581040,0.263649,-0.448424,0.411396,-0.237384,-0.678606,0.919807,-0.057282,-0.358250,0.281414,0.021008,0.823203,0.368193,0.025854,0.756914,0.367460,-0.394575,-0.041817,0.077512,0.057149,-0.340502,-0.165076,-0.375155,-0.019723,0.375343,0.205855,0.253212,0.344931,-0.157668,0.388872,0.312095,-0.097033,-0.703549,0.285720,-0.826670,-0.445579,-0.120830,-0.099879,0.257328,0.289178,-0.256246,-0.372091,0.051158,-0.539487,0.322900,0.261250,0.769840,0.081519,-0.051146,0.008337,-0.183450,0.259646,-0.215558,-0.371797,-0.014920,0.440836,-0.350413,-0.382463,-0.256912,0.099332,0.316645,0.253332,-0.182734,0.037795,-0.572267,-0.265092,-0.928852,-0.089144,-0.380144,-0.309832,0.201175,-0.312634,0.398384,0.166614,-0.110172,0.296914,0.213585,-0.210127,-0.967973,-0.210023,0.745806,-0.425535,0.520379,0.264628,0.269772,-0.115835,0.345199,0.074380,-0.382819,-0.396727,0.759825,-0.500847,-0.637704,-0.659917,-1.171560,0.148613,-0.264515,-0.142397,0.180947,0.241453,-0.201528,-0.345807,0.337420,0.195180,0.254775,0.068157,0.086137,0.186013,0.353656,0.176570,0.079801,0.723835,-0.004619,-0.732385,0.529146,-0.437369,-0.214002,-0.135466,0.134704,-0.045833,0.526802,0.390348,-0.174814,0.886555,-0.155740,-0.526894,-0.536069,-0.026914', '1394470', '21619567', '1309101', '1306505');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26876342', '生化危机：复仇', '动作', '隶属于BASS的佣兵克里斯（凯文·道尔曼 Kevin Dorman 配音）奉命前往某处洋馆调查武器走私案件，哪知道在那里遇见了国际通缉犯格伦（约翰·德米塔 John DeMita 配音），两人交手数回合之后，格伦夺路而逃。大学教授瑞贝卡（艾琳·卡希尔 Erin Cahill 配音）正在研究死者复活伤人时间，由此发现了新型病毒的存在，并且迅速研制出了针对这种病毒的解药，哪知道在这个节骨眼上，研究所遭到恐怖分子的袭击，好在关键时刻克里斯赶到了，救出了瑞贝卡。之后，两人同美国总统直属部队DSO的成员里昂（马修·默瑟 Matthew Mercer 配音）汇合，三人发现，格伦真正的目标正是新型病毒，他想要制造一场破坏性极强的生化危机。©豆瓣', '艾琳·卡希尔', '辻本贵则', 6.8, 20674, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2460545282.jpg', 1.8, 10, 47.8, 28.7, 11.7, '0.173097,-0.031593,-0.748984,0.301826,0.187341,-0.116819,0.147990,-0.230523,-0.350945,-0.505964,0.336901,0.447838,-0.193360,-0.307910,0.309005,-0.065988,-0.424710,-0.332861,0.021341,-0.415508,-0.588282,-0.518303,-0.509154,-0.420153,0.371223,-0.439636,0.436015,-0.044112,-0.276089,0.201927,0.251255,0.661159,-0.222426,0.265951,0.262452,0.084334,0.474245,-0.449075,-0.389291,0.516588,0.181850,-0.104910,-0.160079,-0.214780,0.227408,0.396556,0.515894,-0.207693,0.091186,-0.316180,0.230940,-0.371478,0.128268,-0.125536,0.504054,-0.163981,-0.070116,-0.070102,0.092127,-0.014115,-0.134642,0.172556,-0.623559,-0.009426,-0.288668,0.395128,-0.326438,0.048453,-0.451349,0.277483,0.030544,-0.116801,0.295400,0.590161,0.277734,0.046146,0.031134,-0.025489,-0.538923,-0.155941,0.661416,-0.413025,-0.224090,0.258836,0.035920,-0.477408,-0.160748,-0.152028,0.023565,0.011516,0.406926,0.067213,-0.141806,0.088165,-0.480128,-0.074151,-0.453978,-0.067140,-0.079627,0.050275,-0.007695,-1.140510,0.035784,0.120623,-0.159730,-0.122444,-0.202927,-0.231878,0.399032,-0.745236,0.064200,0.657037,0.419484,-0.341312,0.174076,-0.091349,0.106735,-0.339060,-0.077715,0.176980,0.457168,0.423750,0.279087,0.389266,0.120058,-0.320660,-0.229538,0.084135', '2369613', '4014397', '1306809', '2973528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26876595', '那年夏天你去了哪里', '悬疑', '袁宁静（宋佳 饰）是一名心理医生，她曾有一个妹妹名叫袁宁樱（颜卓灵 饰），不幸的是，袁宁樱遭到了绑匪的绑架，下落不明，这巨大的打击让袁家崩溃了。一晃眼十二年过去，某日，已经长大成人的袁宁樱毫发无损的回到了袁家，在开心和庆幸之余，袁宁静隐隐的感到其中有些不对劲的地方。果不其然，虽然归来的袁宁樱表面看来人畜无害，但她的内心已经腐坏了。她此次归来只有一个目的，就是对袁家进行复仇。敏感的袁宁静洞悉了一切，却找不到一个可以相信的人，只有男友邓Sir（林家栋 饰）站在她的这一边，两人随即对袁宁樱失踪的这十二年展开了缜密的调查。©豆瓣', '宋佳', '周隼', 4.7, 19033, 'tt6464252', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2402705389.jpg', 20.7, 37.4, 30.7, 8, 3.2, '0.340217,0.073913,-0.874384,0.640055,-0.342433,-0.211484,1.122677,-0.027619,-0.936746,-0.471967,-0.031868,0.600666,-0.346001,0.476344,0.168132,0.101724,0.052502,-0.563935,-0.319139,-0.299451,-0.387073,-0.475712,-0.445332,-0.424497,-0.141473,-0.052614,0.413668,0.649709,-0.184771,0.588772,0.507986,0.330139,0.122757,0.855133,-0.398795,0.119952,-0.284540,0.058178,0.055174,-0.035450,0.321840,-0.480671,-0.052511,0.506638,-0.081285,0.765018,0.583182,-0.085525,-0.445930,0.089978,0.431080,-0.459264,0.015373,0.279134,0.467650,-0.126157,0.046426,-0.163047,-0.400615,-0.153094,0.005670,-0.018228,-1.007405,0.065223,0.236754,0.072365,-0.666050,0.506661,-0.020677,-0.022060,0.014016,-0.282393,0.316539,0.667527,0.068796,0.501148,-0.000921,0.076079,-0.474673,0.025654,0.882127,0.067627,-0.259093,0.372736,-0.174711,-0.664896,-0.176403,-0.120490,-0.319558,0.028853,0.573903,0.154591,0.117054,-0.208848,-0.402165,-0.076534,-0.088984,-0.076860,-0.089245,-0.670458,-0.178584,-0.199984,-0.263125,-0.659597,-0.473204,0.321781,-0.082360,-0.466919,0.626080,-0.985417,0.258409,0.325215,-0.015263,-0.712448,0.634844,0.215091,-0.023063,-0.277423,0.205011,0.396466,-0.037819,0.309919,0.309849,0.462865,-0.088968,-0.161972,-0.659652,0.421952', '1301022', '1296370', '1308755', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26877106', '昼颜', '剧情', '离婚后恢复单身的纱和（上户彩饰）在海滨小镇的餐馆打工度日。一个偶然的机会，纱和与北野（斋藤工 饰）再次相遇，约定了不再见面的两人，在四目相对的那一瞬间感情被重新点燃。然而这段禁忌之恋很快被北野的妻子（伊藤步 饰）发现，并与二人产生了激烈的冲突。与此同时，餐厅老板杉崎（平山浩行 饰）的出现，也让四个人的情感走向更加扑朔迷离，一边是复燃的旧情，一边是“永不再相见”的约定，几个主人公的命运再次纠缠在一起。©豆瓣', '上户彩', '西谷弘', 6.4, 88012, 'tt6106802', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2521625065.jpg', 2.6, 15.9, 50.2, 24.3, 7.1, '0.639417,-0.160724,-0.617282,0.652514,0.141028,-0.478801,0.992973,0.449170,-0.409833,-0.199402,0.042123,1.064044,-0.538791,0.311768,0.308230,-0.374802,-0.060263,-0.984292,0.048175,-0.132608,-0.186742,-0.576163,0.157622,-0.044029,-0.175565,-0.107328,0.759311,-0.020469,-0.105018,0.937440,0.378584,-0.043075,-0.432667,0.607635,-0.199480,-0.012878,-0.097260,0.247905,-0.653984,0.396339,-0.117560,-0.212650,0.061001,0.076699,-0.111727,0.226263,0.903835,-0.101115,-0.299460,0.121815,0.259187,-0.034865,-0.047161,0.404966,0.405027,-0.013285,0.099440,0.383100,-0.621108,0.012532,0.100047,0.153299,-0.471127,0.328902,0.075919,0.199134,-0.588428,0.882096,0.202019,-0.483910,0.311319,-0.058886,0.284237,0.743926,0.598709,0.314240,-0.338631,-0.224473,-0.525349,-0.090130,0.693844,0.153562,0.137108,0.710476,0.081170,-0.355124,-0.329740,0.247795,-0.208637,-0.182335,0.355258,0.262753,-0.203697,0.280792,-1.060438,0.029303,0.041769,-0.071033,0.246811,-0.597238,0.071133,-0.802553,-0.440277,-0.672029,-0.545976,0.692203,0.069282,-0.125980,0.410350,-1.057595,0.145916,0.406962,0.544274,-0.380405,0.677115,0.480820,0.165207,-0.081032,0.090651,0.249254,0.088117,0.525023,0.316485,0.604104,-0.095842,0.328341,-0.464055,0.350082', '26365262', '20390013', '11541282', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26877237', '29+1', '剧情', '《29+1》改编自彭秀慧执导的香港大热同名舞台剧，主要讲述即将进入三十岁的两位女性，在面对大部分同龄女性都会面对的困扰时，选择了截然不同的人生态度。一个是即将踏入三十岁的林若君，面对压力升级的工作挑战、双亲病重、仿如鸡肋的爱情关系......突然来袭的这些不安，令她感到前所未有的恐惧。另一个同样是即将迎来三十岁的黄天乐，却永远乐天知命，不为生活所困扰，身患癌症却坚持环游世界，寻找爱情，甚至从未因为微胖身型错过美食。她们互不认识，性格各异，因缘际会林若君却搬进了黄天乐的家，没想到二人竟是同年同月同日出生，林若君通过黄天乐的日记阅读着对方人生点滴，两个女子在空气中互相融合，观照，影响……到底是谁闯进了谁的世界？', '周秀娜', '彭秀慧', 7.1, 39188, 'tt6095004', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2458020487.jpg', 0.9, 6, 41, 40.1, 12.1, '0.123566,-0.062793,-0.492240,0.412154,-0.071954,-0.381825,0.682331,0.151481,-0.412944,-0.635807,0.234488,0.708906,-0.227049,0.331087,0.048194,-0.420594,0.159086,-0.405725,-0.241484,0.006637,-0.232203,-0.139120,-0.393491,0.007756,-0.070279,-0.249185,0.721434,0.234848,-0.392895,0.357018,0.442218,0.297715,-0.155506,0.548831,-0.203251,-0.283074,0.073385,0.237340,-0.353977,0.053979,-0.225342,-0.160397,0.035581,0.188605,-0.201643,0.344958,0.702915,-0.257902,-0.343865,-0.100117,0.749395,0.016120,-0.271840,0.149685,0.238767,0.088592,0.145204,0.077361,-0.109826,0.168101,-0.112789,-0.034828,-0.864538,0.248895,0.259544,0.408748,-0.304166,0.075405,0.260205,-0.204750,0.091547,-0.047136,0.089370,0.523617,0.192648,0.595385,-0.216813,0.122066,-0.270726,0.128950,0.977392,-0.024359,-0.457745,0.356489,-0.501100,-0.253944,0.051596,-0.245282,-0.600723,0.073673,-0.179823,0.371025,-0.087049,0.312055,-0.387675,0.242982,-0.092659,-0.040869,0.187625,-0.444974,-0.095153,-0.532430,-0.179505,-0.478456,-0.473340,-0.023067,0.113236,-0.405672,0.885231,-0.691339,0.181937,0.302934,0.149548,-0.729800,0.832157,0.429286,-0.075874,-0.436913,0.145050,0.710330,-0.119485,0.042993,-0.397276,0.226416,-0.011479,0.166864,-0.252917,0.630763', '1308424', '26678784', '30140231', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26877406', '名侦探柯南：章节ONE 变小的名侦探', '动画', '据日本媒体报道，人气动漫《名侦探柯南》的全新特别篇作品《名侦探柯南：章节ONE 变小的名侦探》预计将于今年冬季播放。据悉，该剧由漫画原作者青山刚昌全面把关，对1996年1月8日播出的TV版第一话“云霄飞车杀人事件”未详尽描述的细节部分，例如各个角色的举动以及内心活动等进行了进一步的展开，并埋下了关系到之后800多话剧情的伏笔，是一篇全新的“起始章节”。《名侦探柯南》是一部讲述小学生侦探柯南解决众多疑难案件的人气漫画，1994年开始连载于《周刊少年Sunday》（小学馆发行）。TV版动画于1996年开始播放，次年开始制作剧场版动画。在TV版动画第一话“云霄飞车杀人事件”中，高中生侦探工藤新一和青梅竹马的女友毛利兰在多罗碧加乐园约会时遇到了杀人事件。身为侦探的新一揭穿了这场杀人事件的骗局，不料却在目睹了行动诡异的黑衣男子的交易场景之后，遭到背后袭击并被灌下神秘组织新研发的毒药Apoptoxin 4869，醒来时身体便回到了孩童状态。据介绍，本次的全新作品《章节ONE》是纪念TV版动画播放20周年的2小时特别篇。剧中，听从黑衣组织命令研发出Apoptoxin 4869的灰原哀等人将重新登场，而尚未和柯南相遇的少年侦探团、阿笠博士以及柯南尚未寄居到小兰家时的毛利小五郎也将会悉数亮相。此外，剧中还会解开新一与小兰去多罗碧加乐园约会的理由等谜底。据悉，《章节ONE》凸显了主要角色的魅力，解释了与黑衣组织的关系等，将《名侦探柯南》的整体设定清晰明了地呈现在观众面前。', '山口胜平', '山本泰一郎', 8.4, 20548, 'tt8051722', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505885669.jpg', 0.4, 1.2, 15.4, 42.8, 40.2, '0.256815,-0.045101,-0.291899,0.359646,0.460672,-0.208362,0.253027,-0.026004,-0.286293,-0.377345,0.169245,0.628201,-0.713734,0.149757,0.401003,-0.258188,-0.536947,-0.844692,-0.340632,-0.238866,-0.142600,-0.311597,-0.082012,-0.138354,0.051292,-0.433611,0.782179,0.098857,-0.401889,0.405964,0.221139,0.147347,-0.272631,0.193950,0.153676,-0.000220,0.277032,-0.177424,-0.231092,0.464145,-0.150663,-0.413158,-0.080884,-0.064422,-0.092265,0.362864,0.990438,-0.428195,-0.246395,0.054655,0.829708,-0.115783,-0.378833,-0.053813,0.535236,0.288969,0.122060,0.345966,-0.082305,0.208651,-0.227814,-0.461669,-0.704049,-0.135380,0.075768,0.388986,-0.145554,0.151406,-0.465239,0.089303,0.334500,-0.195479,0.027811,0.010918,0.726413,0.268484,0.030545,0.255002,-0.061224,0.513014,0.010352,0.172406,-0.189598,0.570634,0.177075,-0.600532,-0.554060,-0.077865,0.094377,0.319136,0.185171,0.059692,-0.274634,0.251327,-0.698242,-0.170199,-0.122564,-0.487157,0.026106,-0.074522,-0.487190,-0.988