INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26877492', '小森林', '剧情', '改编自五十岚大介的日本同名漫画的韩国新片《小森林》将由林顺礼导演执导，金泰梨主演，这也是她继《小姐》之后的下一部主演作。《小森林》也已经在日本被改编成两部电影作品。电影讲述女主人公放下城市生活来到农村老家感受农村生活的故事，将通过林顺礼导演特有的温情视角描绘韩国的美丽 自然风景和多样的食物，因为春夏秋冬都要有所以拍摄周期约一年。林顺礼对于选择金泰梨也表达了自己的观点“金泰梨在20代女演员中演技实力和自然的魅力是很吸引人的，这个角色很适合她。”', '金泰梨', '林顺礼', 7.5, 39668, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2512152196.jpg', 0.9, 4.3, 34.3, 41.8, 18.8, '0.170004,0.049267,-0.406429,0.805526,-0.013675,0.138997,0.654589,0.250865,-0.432058,-0.084142,0.213252,0.753727,-0.235297,0.242082,0.262040,-0.120730,-0.559696,-0.547211,-0.313709,-0.228907,0.051808,-0.258257,-0.171626,0.136562,-0.227735,-0.347899,0.945219,-0.174802,-0.315392,0.080425,0.402096,-0.057278,-0.027121,0.115050,-0.024945,0.120039,0.065369,-0.010954,-0.439226,0.586023,-0.075634,-0.341866,-0.112808,0.125464,-0.020732,0.327221,0.979975,-0.031463,-0.230979,0.027675,0.649937,-0.237145,-0.092804,-0.129574,0.217877,-0.082744,0.510603,0.127585,-0.220804,0.197237,-0.317977,-0.375704,-0.915789,0.283266,0.583912,0.121420,-0.643026,0.179995,0.127871,-0.294004,0.087144,-0.434021,0.221991,0.113526,0.767610,0.437753,0.032186,0.220255,-0.250631,0.624801,0.606314,0.127728,-0.218352,0.599034,-0.362838,-0.764755,-0.248818,-0.194902,-0.578244,0.214601,-0.061881,-0.072459,-0.165818,-0.091069,-0.718659,0.233937,0.177324,-0.603603,0.323936,-0.481498,0.134466,-0.926397,-0.314608,-0.562788,-0.156928,-0.420109,0.502608,-0.361566,1.200255,-0.642137,-0.093478,0.390487,0.410147,-0.203662,0.957618,0.148788,-0.441358,-0.114578,0.166989,0.238202,-0.080844,-0.046722,-0.066546,0.610888,-0.074054,-0.514527,-0.638288,0.711411', '1322847', '22265121', '27602116', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26877505', '空白的13年', '剧情', '好赌的父亲欠下一屁股债说买烟一去就是13年，13年后父亲现身，“我”却被哥哥告知父亲得了癌症，余命3个月...父亲的告别仪式上，从前来祭拜父亲的人们口中了解了真实的父亲，填补了13年的空白', '高桥一生', '斋藤工', 7, 6317, 'tt6640390', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2507785541.jpg', 0.9, 6, 46.2, 37.5, 9.4, '-0.058186,0.000222,-0.365381,0.210279,-0.275571,-0.766976,0.437117,-0.074495,-0.664327,-0.205920,0.089146,0.647784,0.086593,0.635671,0.369994,0.133258,0.077017,-0.671508,0.134581,-0.636619,-0.364603,-0.441353,-0.097047,-0.060600,-0.137258,-0.359368,-0.109866,0.109918,0.347236,0.378267,-0.071866,-0.065356,0.308583,0.344899,-0.171969,0.267506,-0.536191,0.350156,-0.109835,0.083916,0.173568,-0.512694,0.045046,-0.091941,0.161318,0.703590,0.280643,-0.263157,-0.071517,-0.200461,0.627755,-0.036196,-0.151186,0.171324,0.103621,0.375282,0.227076,0.521181,-0.512120,-0.465503,-0.487971,-0.380026,-0.448768,0.086412,-0.244276,-0.061822,-1.024440,0.622126,-0.428109,0.407212,-0.192950,-0.421252,0.552655,0.523502,-0.112276,0.779259,-0.360059,0.026805,-0.151760,0.632800,0.781883,-0.536989,0.217281,0.065556,-0.193682,-0.338691,0.204917,-0.229281,-0.384378,0.402877,0.038376,0.025324,-0.499551,0.052748,-0.130633,-0.290521,-0.285353,0.039455,0.434850,-0.185924,-0.588677,0.243528,-0.576022,-0.186751,-0.091386,-0.297960,0.077087,-0.359673,0.928844,-0.310405,0.337861,0.631741,0.414449,-0.585981,0.859363,-0.320181,-0.202217,-0.148379,0.319043,0.372905,0.144043,0.227397,0.328332,-0.117640,0.297682,-0.166026,-0.076235,-0.022325', '1293607', '1291565', '1306505', '2080130');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26878605', '我们的故事2', '剧情', '本片以上世纪六十年代的本地家庭为主轴，通过成员的际遇，带出早期的甘榜生活以及后来的组屋生活，剧情横跨数十年。电影也将体现新加坡如何从一个以方言为主流语言的社会演变成华语到现今英语的过程，从中回顾流失的方言。它也会融入导演的许多亲身经历，并将安插多首怀旧歌曲。After the 1969 nationwide floods, Zhao Di takes over her father''s family farm with the help of reformed gangster Ah Long. As Singapore''s economy prospers, the Singaporean mindset is also forced to change with the times. Osman catches his teenage son, Ahmad practicing with his rock band. As a conservative man, Osman believes rock music will have a negative influence on Ahmad. Father and son argue over their different opinions, causing Ahmad to run away. Meanwhile, Ah Hee and Rani decide to get married. But their traditional parents disapprove of their marriage. In 1', '陈丽贞', '梁智强', 8.4, 8516, 'tt5531934', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2382579428.jpg', 0.4, 1.6, 14.9, 46.4, 36.8, '0.065813,0.091157,-0.121828,0.976312,0.057121,-0.126857,0.637353,-0.159067,-0.637609,-0.377567,0.167377,0.868209,-0.192721,-0.125862,0.252356,-0.355821,-0.188224,-0.729928,0.067870,-0.042161,-0.170196,-0.267978,-0.116097,-0.064481,-0.446727,-0.305945,0.879012,0.313692,-0.801258,0.096731,-0.283587,0.250168,-0.186464,0.004686,-0.233620,-0.118322,-0.267671,0.115477,-0.379750,0.301595,0.177665,-0.228877,-0.162314,-0.215214,-0.323894,0.117784,0.934546,0.132637,0.168520,0.239359,0.807778,-0.109900,-0.401640,-0.293938,0.341222,0.198882,0.124530,0.429752,0.005157,0.445475,-0.471233,-0.080203,-1.248248,-0.169765,0.055668,0.015792,-0.528677,0.337362,0.198684,-0.347475,-0.200291,-0.275052,0.047303,0.650961,0.417604,0.671974,-0.284049,0.233033,-0.422132,0.398910,0.691513,-0.084083,-0.583613,0.414674,-0.399151,-0.858823,-0.401180,-0.401779,-0.189532,-0.109183,-0.113569,0.107364,-0.148811,0.378727,-0.884273,0.160994,-