INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26878883', '野梨树', '剧情', '司南（岛吾·德米尔考 Doğu Demirkol 饰）是一个土耳其男孩，刚刚从大学毕业的他正在准备出版自己的第一部小说。然而，出版小说需要启动资金，这是目前司南最缺乏的东西，无奈之下，他只得返回故乡恰纳卡莱省的乡下，在那里，居住着和司南久未联系的父亲伊德里斯（穆拉特·杰姆吉尔 Murat Cemcir 饰）。司南本来有一个非常幸福的家庭，然而伊德里斯染上了赌博的恶习，这个恶习让他的家庭最终走向了分崩离析，这也是司南记恨自己父亲的最大原因。伊德里斯本来是一名德高望重的教师，赌博令他失去一切，还背负上了巨额债务，儿子的回归让伊德里斯不得不再度面对自己失败的过去。©豆瓣', '岛吾·德米尔考', '努里·比格·锡兰', 8.1, 18373, 'tt6628102', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2546455482.jpg', 0.6, 2.1, 17.8, 49.2, 30.3, '0.357154,0.158428,-0.548572,0.549706,-0.110334,-0.549564,0.622754,0.259889,-0.554576,-0.389311,0.259759,0.910085,0.340817,0.252095,0.204609,0.339370,-0.399271,-0.487805,-0.132992,-0.079373,-0.190490,-0.577087,-0.374783,0.018808,-0.340203,-0.193042,0.781561,0.036029,-0.124628,0.281956,0.317843,0.397049,0.330855,0.452817,-0.136672,0.275658,-0.060165,-0.077302,-0.177197,0.300085,0.286036,-0.109559,-0.293378,0.305348,0.101683,0.371787,0.434170,-0.129269,-0.070696,-0.271790,0.465638,-0.412079,-0.209013,0.136487,-0.124553,-0.021538,0.221620,0.244021,-0.442090,0.095108,0.050978,-0.002289,-0.720033,-0.265973,0.028749,0.142074,-0.637428,0.451407,-0.215989,-0.176975,0.199374,-0.478987,0.179574,0.618091,0.068048,0.395064,-0.376116,-0.027145,-0.644455,0.191528,0.546501,0.022265,-0.146398,0.374056,-0.385480,-0.409722,-0.078391,-0.351661,-0.446839,0.011111,0.361026,0.134329,-0.078871,0.193847,-0.598921,0.021458,-0.005986,-0.384099,0.090888,-0.352344,-0.198797,-0.318909,-0.265142,-0.354187,-0.442289,-0.139816,0.023488,-0.359951,0.770044,-0.697658,0.071892,0.534933,0.368479,-0.461179,0.661646,0.254734,0.143393,-0.065532,-0.048171,0.367121,-0.088514,0.511990,-0.063017,0.124667,0.168345,-0.448055,-0.377169,0.768316', '1870681', '1783461', '1308976', '24875409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26879060', '情圣', '喜剧', '肖瀚（肖央 饰）和妻子沈红（代乐乐 饰）结婚多年，感情早已经归于平淡，在两人漫长的婚姻生活中，肖瀚一直保持着对妻子的忠诚，直到某日，一位名叫yoyo（李成敏 饰）的美丽女子出现在了肖瀚的身边，令肖瀚再也无法忽略内心里的悸动，他决定正视自己的感情，不再受道德和舆论的约束，大胆追求自己真正渴望的爱情。为了成功抱得美人归，肖瀚找到了好友艾木（艾伦 饰）、汤怀（乔杉 饰）和刘磊（小沈阳 饰）等人，几人策划了一个看似万无一失的计谋，胜利的果实势在必得。哪知道在执行计划的过程中，肖瀚的老板玛丽莲（闫妮 饰）几度搅局，闹出了一堆的笑料，不仅如此，敏感的沈红亦预感到丈夫正在“搞事情”。©豆瓣', '肖央', '宋晓飞', 6, 158848, 'tt6398666', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2409022364.jpg', 6.9, 18.7, 46.5, 21.5, 6.5, '0.083638,0.225581,-0.709269,0.560410,-0.150564,-0.151132,0.649328,0.072922,-0.494564,-0.245211,0.271113,0.478635,-0.282539,0.219362,0.253129,-0.000594,-0.185508,-0.816770,-0.064646,0.039321,-0.017096,-0.470765,-0.375579,-0.136670,-0.228712,-0.275046,0.528551,0.118256,-0.091345,0.441879,0.468002,0.128160,-0.134162,0.439387,0.050955,-0.055952,0.134312,0.276582,-0.505361,0.098139,0.030192,-0.147413,-0.137745,0.207209,-0.147385,0.238671,0.547416,-0.378342,-0.307344,0.126293,0.271002,-0.285665,-0.058404,0.200567,0.181333,0.094745,0.180776,0.235627,-0.384708,0.085521,0.234810,-0.032571,-0.710235,-0.094849,0.086613,0.189534,-0.420652,0.572083,-0.041443,-0.059276,0.244223,-0.440386,0.090155,0.180411,0.295206,0.439813,-0.387138,0.012711,-0.263206,0.142051,0.531135,-0.067100,-0.111183,0.307445,-0.181901,-0.290353,-0.122514,-0.072614,-0.518773,-0.074347,0.222504,0.187578,-0.213942,0.195886,-0.243237,0.093138,-0.070431,0.133116,0.164264,-0.547043,0.025088,-0.248256,-0.303015,-0.517316,-0.349546,0.260574,0.077961,-0.387294,0.622847,-0.757788,0.190629,0.338840,0.193165,-0.572250,0.357881,0.405641,0.018506,-0.396850,-0.080498,0.295821,-0.407406,0.046504,0.086798,0.263692,-0.144706,-0.030584,-0.362469,0.397548', '1301022', '1418613', '26809007', '35030151');
