INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26882327', '血狼犬', '剧情', '电影根据“西北犬王”的真实事迹改编。中国西北天山林场，护林员朱广生（黄宏 饰）驯养勇猛的狼犬来防止偷木盗猎，为此倾尽家产、维继艰难。一只流浪小狗（哈雷 饰）无意间走进了老朱的生活，老朱为它取名“蓝波”，并开始训练它成为护林犬。极通人性的蓝波很快成为了老朱的好帮手。因老朱举报其盗猎野狼而入狱的张彪（刘向京 饰）刑满释放后，开始找老朱寻仇、不断威胁老朱两个女儿和蓝波的安危，张彪的几次下毒、猎杀都被机智的蓝波化解，张彪狗急跳墙带人强行将蓝波抢走，老朱与派出所刘所长（孙涛 饰）找到张彪，看到桌上一盆狗肉悲愤不已。而真相是蓝波被劫后与歹徒斗智斗勇，在厨房中寻机逃走，胖子（肥龙 饰）和厨子（秦伟 饰）率众人各路围追堵截，蓝波翻墙越顶、“飞檐走壁”最终成功的逃脱。为了让蓝波有个好归宿，姐妹二人含泪将蓝波送到城里被人收养，而忠犬蓝波挣脱锁链长途奔行几十公里又回到了老朱身边。张彪对老朱女儿朱丛（赵婷婷 饰）心生爱慕，将她“绑架”到情人谷，发誓痛改前非、真心示爱。老朱与小女儿朱林（朱琳 饰）进山寻找遭遇车祸，被狼群围攻。蓝波冒死冲出狼群回去报信，并率领群犬返回深山营救老朱。一场惨烈的狼犬大战震撼上演……', '黄宏', '刘建华', 5.5, 5104, 'tt7123882', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2452142083.jpg', 12.9, 23, 45.6, 11.9, 6.6, '-0.136718,-0.140755,-0.378537,0.269167,-0.094727,-0.214861,0.526255,-0.055095,-0.272062,-0.179769,-0.135408,0.279300,-0.130590,0.463895,0.115094,-0.294026,0.032758,-0.406773,-0.209829,0.157493,-0.143510,-0.068488,-0.053076,-0.323368,-0.059142,0.136691,0.318535,0.123946,-0.182006,0.680069,0.417718,0.198480,-0.254484,0.367822,-0.140330,0.380479,0.030063,-0.121678,-0.050072,0.082890,0.003883,-0.267183,0.012105,-0.033250,0.209155,0.187662,0.714885,-0.284397,-0.038198,-0.380357,0.144605,-0.463557,0.154660,0.207235,0.454777,0.156201,-0.155292,-0.034752,-0.128410,0.035089,0.093324,-0.078932,-0.340606,0.191110,0.035283,-0.228013,-0.585388,-0.188426,0.125676,0.390179,0.310627,-0.292041,0.219988,0.160376,0.167791,0.221812,-0.214705,0.168392,-0.546544,0.145013,0.651785,-0.526948,0.349142,-0.345938,0.367235,-0.366196,0.561628,-0.055335,-0.085791,-0.078776,0.717140,-0.149832,-0.105958,-0.029296,-0.381128,-0.297557,-0.397790,-0.023407,-0.130805,-0.138636,-0.050300,-0.520762,0.107259,-0.267416,-0.146870,0.081636,-0.003935,-0.202053,0.344218,-0.308382,0.083469,0.311294,0.104535,-0.534194,0.341927,-0.124588,0.099786,-0.08523