INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26882347', '最臭兵器', '动作', '供职于制药公司的小职员田中信男拖着病体赶回公司，无意中服用了公司与军方合作的实验药品。自此信男成为了制造致命臭气的肉身工厂，对此毫不自知的信男却按照上司命令将药品样本送往东京总部，一路上引起大面积恐慌，军方不得不派出大批军队半路截杀信男', '堀秀行', '冈村天斋', 8.4, 9279, 'tt6266826', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2508668372.jpg', 0.6, 1.4, 13.2, 46.1, 38.7, '-0.280787,0.277134,-0.438542,0.248998,0.215581,0.150181,-0.008974,0.296015,-0.683764,-0.464421,-0.104635,0.367329,0.325276,0.041473,0.159032,-0.454114,-0.133339,-0.061815,-0.599508,-0.138014,-0.269951,-0.319696,0.007966,-0.476999,-0.270132,-0.512799,0.834721,0.217375,-0.729960,0.368323,0.104628,0.691674,-0.501373,0.374871,0.129984,-0.120632,0.380904,-0.224298,-0.537263,0.425028,0.072395,-0.367595,0.136708,-0.023107,0.440750,0.479982,0.649687,0.157199,-0.352887,-0.459870,0.415824,-0.357525,0.218757,-0.239276,0.582076,0.473259,0.047611,0.315873,-0.509581,-0.139714,0.275915,0.002257,-0.732746,-0.230986,0.147136,0.065961,-0.444749,-0.006418,-0.261321,0.383150,-0.031098,-0.435458,0.233548,0.400104,0.117365,-0.144517,0.045635,0.339074,-0.704227,0.161605,0.554820,-0.084402,-0.009372,-0.130128,-0.079453,-0.296270,0.003152,-0.359516,-0.246857,0.000444,0.087985,0.211215,0.063535,0.157608,-0.468879,-0.099983,-0.521666,-0.309522,0.462476,0.059754,0.312750,-1.158609,0.375916,0.230290,-0.217726,0.180674,0.518641,0.288501,0.514701,-0.593496,-0.171209,0.518917,0.676649,-0.765928,0.130217,-0.232839,0.093962,-0.174673,0.041639,-0.180045,0.794939,0.605257,0.400937,0.283187,-0.201680,-0.682381,-0.275025,-0.377365', '2369613', '1300371', '1306809', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26882457', '断片之险途夺宝', '喜剧', '故事发生在某大型海洋世界，卖鱼大叔牙叔（葛优 饰）、海豚训练员阿乐（岳云鹏 饰）和海洋馆保安杜治国（杜淳 饰）因工作结识，因境遇相怜。他们奋力挣扎，却最终遭受情感的挫折。这一晚，三人相约聚餐，借酒浇愁，在晕头转向、不省人事的时候，一辆汽车来到海洋馆。醉眼迷蒙的牙叔稀里糊涂在货单上签了字，第二天醒来却发现海洋馆的明星海豚宝宝被他卖到了国外。这桩意外顿时把三人的酒都吓醒了，而他们也成为盗售海豚的重要嫌疑人。在此之后，他们匆匆忙忙踏上寻找海豚的征程，一路上更是闹出了无数的笑话……©豆瓣', '葛优', '罗登', 2.9, 22204, 'tt6547728', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2541553709.jpg', 70, 20, 7.7, 1.2, 1.1, '0.324962,0.011276,-0.774499,0.012688,0.349953,-0.173088,0.759172,0.197266,-0.538125,-0.002862,0.290056,0.616912,-0.483480,0.310501,0.564865,-0.264063,-0.173193,-0.476017,0.302792,0.064328,-0.185627,-0.278931,-0.059491,-0.054207,0.079451,-0.036167,0.294728,0.137775,-0.001500,0.681969,0.083252,-0.097748,-0.442432,0.631553,-0.086243,0.219020,0.252133,0.159594,0.035989,-0.036277,-0.175528,-0.342886,-0.135114,-0.216747,0.068822,0.207544,0.836717,-0.126635,-0.273790,-0.036398,0.168472,-0.337717,-0.013671,-0.111110,0.266890,0.103616,0.070315,-0.091188,0.061851,-0.089049,0.190890,0.086203,-0.185594,0.195826,0.026770,0.224272,-0.511445,0.443027,-0.046821,0.083898,0.046825,-0.295183,0.290577,0.198929,0.120345,0.438205,0.059052,0.284518,-0.636850,0.325052,0.596126,-0.127830,0.032057,0.446898,-0.085184,-0.389725,0.008890,-0.095268,-0.169734,-0.029293,0.756393,0.066354,-0.465013,-0.034541,-0.642862,-0.043200,0.070927,-0.415208,-0.013114,-0.156653,-0.171657,-0.556347,0.136232,-0.178928,-0.097345,0.217014,-0.022027,-0.065080,0.557695,-0.387891,0.110430,0.524421,0.112860,-0.306503,0.739335,-0.183289,0.129908,-0.017854,0.104616,0.137795,0.055099,0.403064,0.209501,0.179482,-0.150082,0.226961,-0.297543,0.198141', '3011051', '4919019', '2159244', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26884354', '狮子王', '剧情', '广袤无垠的非洲大草原，祥和奋进的荣耀王国迎来了光辉时刻。威严而勇敢的狮子国王木法沙（詹姆斯·厄尔·琼斯 James Earl Jones 配音）与王后沙拉碧（阿尔法·伍达德 Alfre Woodard 配音），终于迎来了他们的儿子——王国未来的王者辛巴（唐纳德·格洛弗 Donald Glover 配音）——的诞生。在所有的动物都心悦诚服跪拜辛巴王子之际，只有木法沙的弟弟刀疤（切瓦特·埃加福 Chiwetel Ejiofor 配音）妒火中烧。他久久觊觎哥哥的王位，而今更是将辛巴视为眼中钉肉中刺。经过一番策划，刀疤害死了木法沙，并将罪名推给了侄子，进而将王位攫取到自己手中。荣耀王国从此被黑暗笼罩，而遭到流放的辛巴是否还能回到这个他度过快乐童年的国度呢？©豆瓣', '唐纳德·格洛弗', '乔恩·费儒', 7.2, 341621, 'tt6105098', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2549283092.jpg', 1, 5.7, 39.5, 39.2, 14.7, '-0.268229,0.309375,-0.651837,0.883795,0.008503,-0.369241,0.498807,0.409627,-0.334192,0.029591,0.234157,0.654372,0.104039,0.327451,0.496829,0.195103,-0.265405,-0.702604,-0.175098,0.068071,-0.057850,-0.216420,-0.140733,-0.393219,0.011068,-0.444648,0.739151,-0.107637,0.042232,0.136348,0.272811,0.124790,-0.046157,0.472752,-0.264884,0.261492,0.219891,-0.128342,-0.405385,0.055576,-0.247010,-0.074209,-0.058580,0.309127,-0.017068,-0.076491,0.633652,-0.662097,0.205796,-0.598246,0.333760,-0.590472,0.104761,0.221628,0.283291,-0.175356,-0.117775,0.391387,0.126257,-0.185426,0.118246,-0.371413,-0.738859,0.026316,-0.153084,0.081547,-0.371966,0.448876,-0.024477,0.008117,0.249489,-0.120009,0.356491,0.270070,0.214330,0.315555,-0.138677,0.309704,-0.401482,0.083558,0.578614,-0.268126,-0.134385,-0.121048,-0.047560,-0.507321,0.074917,-0.263686,-0.453001,-0.279387,0.616204,0.076548,0.014207,0.650650,-0.839821,-0.159757,-0.424513,-0.490031,0.329018,-0.658507,-0.154760,-0.174662,-0.043043,-0.236984,-0.125368,0.073957,0.301982,-0.283847,0.671158,-0.482604,0.438429,0.511499,0.177014,-0.235150,0.427935,-0.055818,0.139923,-0.179261,-0.171088,0.551461,0.443961,0.329353,0.116307,-0.020508,-0.228562,0.083832,-0.425371,0.636432', '26290398', '26667010', '19899707', '1308837');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26884373', '违命', '剧情', '罗尼特（蕾切尔·薇兹 Rachel Weisz 饰）是一位小有名气的摄影师，这一天，她意外的收到了父亲的死讯，因此赶回了阔别已久的故乡——一个位于纽约郊区的正统犹太教社区。实际上，罗尼特曾经被从社区里给驱逐了出去，因为她和同性女友的艾斯提（瑞秋·麦克亚当斯 Rachel McAdams 饰）的恋情曝光了，在东正教里，这是绝对不被允许的。一晃眼多年过去，这些年间，罗尼特和艾斯提之间没有任何的联系，当罗尼特再度回到社区时，发现艾斯提已经和当地的教会继承人结婚了。久别重逢的两人虽然在言谈举止之中有着明显疏离，但隐藏在两人心中的爱火很快就再度熊熊燃烧起来。©豆瓣', '瑞秋·麦克亚当斯', '塞巴斯蒂安·莱里奥', 7, 11523, 'tt6108178', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2517784872.jpg', 1, 7.8, 43.7, 33.4, 14.1, '0.718105,0.220999,-1.001452,0.804018,0.138278,-0.466080,0.884752,-0.032455,-0.735410,-0.526876,-0.230112,0.893604,-0.446667,0.338211,0.296792,0.031580,-0.354699,-0.850694,-0.079375,-0.753049,-0.307472,-0.501912,-0.251846,-0.032854,-0.286528,-0.221595,0.435830,0.141090,-0.098714,0.581611,0.401866,0.343184,-0.011582,0.611692,-0.031764,0.177018,0.198076,-0.043495,-0.233029,0.412048,0.242804,-0.121574,-0.005850,0.159747,0.298069,0.624537,0.343200,-0.352397,-0.087347,0.142959,0.357878,-0.117845,-0.129103,0.231468,0.629413,-0.195245,0.199089,0.119860,-0.450924,0.003008,0.074061,-0.188416,-0.536370,0.062520,-0.056574,0.202787,-0.743299,0.636900,-0.125964,-0.176566,0.069030,-0.156196,0.378921,0.543959,-0.021603,0.528736,0.148106,0.077679,-0.481401,-0.021595,0.695084,0.146211,-0.368858,0.308288,-0.307435,-0.360213,-0.192572,0.022260,-0.427140,-0.241650,0.610027,0.030812,0.005865,0.363101,-0.584185,-0.167148,-0.281909,-0.045012,0.108389,-0.382120,0.002343,-0.716488,-0.208971,-0.652936,-0.190955,0.092210,-0.018539,-0.175722,0.494086,-1.113593,0.544432,0.128146,0.353442,-0.289466,0.565012,-0.045950,0.300552,-0.104728,0.069647,0.405780,0.354849,0.498726,0.344841,0.397213,-0.059308,-0.225572,-0.290527,0.581260', '1296332', '1301022', '1308755', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26884422', '关于无尽', '剧情', '无尽之中，我们被一个女人温柔的声音引导着整个世界。那是一种神话般的声音，一首Scheherazade给我们讲述了人类生活和奋斗的永恒故事：“我看到一个孩子在雨下走着去参加生日聚会……”“我看到一个还没有找到爱的男孩……”“我看到一个不再信任银行的男人……”我们从一系列显而易见的琐碎瞬间，看到男人和生活的平凡和宏伟，这些琐碎的时刻反映了生活的辉煌：一个女孩第一次握住一个心爱的男孩的手；一个父亲在倾盆大雨中系住他女儿的鞋带；一个年轻的女人等待她的ap。点睛之笔——但也包括人类残忍表现在平庸中的时刻——一个人拖着十字架；一个残废的战争老兵坐在路边；一个父亲把死去的儿子抱在怀里——就像生命的号角一样，关于永无尽头，向我们展示了祢的宝贵和美丽。R存在，唤醒我们希望保持这永恒的宝藏并传递它。', 'Bengt Bergius', '罗伊·安德森', 7.4, 8359, 'tt6817944', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2602868922.jpg', 1.4, 4.6, 32.7, 46.2, 15.1, '0.219849,0.148703,-0.656785,0.915305,-0.676863,-0.072690,1.349063,0.027465,-0.075602,-0.067616,0.268497,1.131810,-0.003113,0.443047,0.197081,0.070716,-0.105979,-0.821023,-0.279596,0.181136,-0.418710,-0.279294,-0.154199,-0.159531,-0.045159,-0.210992,0.770518,0.071908,-0.087212,0.490342,0.071616,-0.186861,-0.111371,0.486026,-0.679869,-0.291494,-0.060477,0.188396,-0.051485,0.392707,-0.160512,-0.154282,-0.037858,0.275386,-0.477485,-0.025899,0.698982,-0.621439,-0.079247,0.085520,0.371067,-0.271261,-0.191176,0.121205,-0.095510,-0.143141,0.064409,0.169999,-0.336494,-0.172937,0.126378,-0.301963,-1.037475,-0.214805,-0.220308,0.440803,-0.717056,0.698483,0.156638,-0.049175,0.393628,-0.461779,0.520626,0.140616,0.076379,0.768399,-0.453462,0.191700,-0.492990,0.263797,0.680170,-0.232073,-0.366604,0.469657,-0.230313,-0.338613,-0.103121,0.013349,-0.905731,-0.097723,0.254143,-0.191587,-0.468595,0.011279,-0.619167,0.307568,-0.030443,-0.357595,0.011108,-0.752391,-0.319534,-0.152042,-0.202935,-0.348646,-0.465090,0.302536,-0.019708,-0.330719,1.083195,-0.619535,0.340437,0.723222,0.291101,-0.241604,1.001245,0.221931,0.131260,-0.295759,0.027430,0.447014,0.100368,0.289502,0.030405,0.560067,-0.230110,0.411266,-0.515073,0.636466', '1303077', '4847665', '3119246', '3016252