INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26884892', '大病', '喜剧', '库马尔（库梅尔·南贾尼 Kumail Nanjiani 饰）出生在一个非常传统的巴基斯坦家庭之中，成年后，他选择成为了一名喜剧演员。在一场单口表演中，库马尔邂逅了名为艾米丽（佐伊·卡赞 Zoe Kazan 饰）的女孩，本以为的一夜激情竟然从暗夜蔓延到了白天，最终，他们发现彼此就是一直在寻找的另一半，两人走到了一起。然而，库马尔的家人要求他遵循巴基斯坦包办婚姻的传统，为他相中了一个穆斯林女孩，催他回老家结婚。与此同时，一场诡异的怪病袭击了艾米丽，令她陷入了昏迷之中。库马尔选择和艾米丽的家人们站在一起，共同度过这难关，与此同时，他还要抵御来自自己父母的步步紧逼。©豆瓣', '库梅尔·南贾尼', '迈克尔·肖沃特', 7.5, 19133, 'tt5462602', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2495329684.jpg', 0.6, 3.3, 32.5, 48.3, 15.4, '0.343025,-0.023244,-0.887314,0.477485,-0.236840,-0.243138,0.704669,0.061373,-0.440568,-0.309537,0.268488,0.912892,-0.217179,0.284824,0.461997,-0.073789,-0.222224,-0.769870,-0.092480,-0.036887,-0.391779,-0.307946,-0.078531,-0.083336,-0.158206,-0.268974,0.639216,0.088615,-0.064985,0.500397,0.126953,0.267123,-0.214289,0.500027,-0.257283,-0.011416,0.133440,-0.087966,-0.345010,0.529545,0.055061,-0.295253,-0.113093,0.182944,-0.113051,0.282775,0.643647,-0.402071,0.145078,-0.093462,0.124730,-0.256748,-0.393975,0.310090,0.243831,-0.103397,0.238620,0.119264,-0.246695,-0.041376,0.081137,-0.018145,-0.480817,0.126260,0.048380,0.159097,-0.679963,0.558222,0.234302,-0.152564,0.139460,-0.361938,0.168450,0.485142,0.098971,0.443810,-0.347940,-0.061624,-0.552075,0.023911,0.921094,-0.122857,-0.233957,0.310497,-0.148958,-0.313931,0.087146,0.006893,-0.470850,-0.235712,0.345522,0.142762,-0.258991,0.180241,-0.667391,0.002172,-0.126910,-0.220712,-0.033119,-0.509346,-0.143966,-0.583045,-0.199460,-0.412000,-0.234296,0.342330,-0.126957,-0.348027,0.586605,-0.796203,0.252368,0.457887,0.347413,-0.299114,0.701920,0.211441,0.327877,-0.090551,0.075042,0.303720,-0.103491,0.186042,0.149066,0.291751,-0.155626,0.275102,-0.505329,0.586600', '25721544', '30162520', '26687241', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26885074', '叶问4：完结篇', '剧情', '因故来到美国唐人街的叶问，意外卷入一场当地军方势力与华人武馆的纠纷，面对日益猖狂的民族歧视与压迫，叶问挺身而出，在美国海军陆战队军营拼死一战，以正宗咏春，向世界证明了中国功夫。', '甄子丹', '叶伟信', 6.8, 279741, 'tt2076298', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2577578115.jpg', 1.7, 9.8, 45.5, 33.5, 9.4, '-0.061635,0.326115,-0.665506,0.542071,0.374483,0.031721,0.227093,0.398928,-0.611683,-0.148396,0.456876,0.812233,0.403146,-0.195452,0.451823,-0.770346,0.084778,-0.738370,-0.201247,-0.038328,-0.101906,-0.358766,-0.205047,-0.430426,-0.347979,-0.575676,0.621208,0.423136,-1.025594,0.602828,0.374316,0.564257,-0.451165,0.524689,-0.012924,-0.527042,0.324965,0.282637,-1.077077,0.035169,-0.205438,-0.550205,-0.379832,0.106479,-0.049818,0.146062,0.469805,0.295209,-0.180216,-0.623045,0.165181,-0.334023,-0.476886,0.163365,0.771791,-0.164678,0.182334,0.277815,0.482033,0.009638,-0.045942,0.035441,-0.373659,0.039264,0.587349,-0.127128,-0.601127,0.573664,-0.100784,-0.493110,-0.308525,-0.242169,0.064933,0.819100,0.269685,0.457316,0.070284,0.375806,-0.521745,0.061224,0.951833,-0.328825,-0.410776,-0.318812,0.297644,-0.280302,0.021623,-0.558671,-0.007095,-0.130310,0.294197,-0.890675,-0.053700,0.596673,-0.888090,0.094552,-0.050173,-0.588837,0.215063,-0.418783,0.468292,-0.887202,-0.314483,-0.247750,0.092114,0.299092,0.394488,0.266327,0.994356,-0.610117,-0.058193,0.645106,0.567879,-0.577028,0.516130,0.084460,-0.008433,-0.293101,-0.322693,0.393511,0.321094,0.184325,-0.171558,0.219458,-0.080964,0.095948,0.104299,0.002923', '1316511', '3230460', '1849026', '34822138');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26886204', '匹诺曹', '奇幻', '改编自经典童话《木偶奇遇记》，讲述老木匠（罗伯托·贝尼尼 Roberto Benigni 饰）雕刻的木偶机缘巧合下获得生命，被木匠当作自己的儿子，并取名“匹诺曹”（费德里科·伊帕迪 Federico Ielapi 饰）。木匠耐心地教导匹诺曹，可贪玩的匹诺曹却跑到马戏团看木偶戏，并因此开启了一段离家之旅。', '费德里科·伊帕迪', '马提欧·加洛尼', 6.2, 13435, 'tt8333746', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2642645574.jpg', 2.7, 15.6, 55.8, 21.5, 4.4, '0.163914,-0.153259,-0.173144,0.450362,-0.065796,-0.607479,0.583071,0.099595,-0.378598,-0.536019,0.095479,0.663269,-0.352892,0.159021,-0.201763,-0.146954,-0.340557,-0.359233,-0.004792,0.390626,0.016962,-0.559245,0.120245,-0.245441,0.273537,-0.071430,0.279872,-0.018285,-0.139143,0.487423,0.027366,-0.267636,0.169393,-0.273989,-0.145986,0.838568,0.002896,0.095991,0.181761,-0.261260,-0.158909,0.008085,-0.150436,-0.262572,0.089749,0.035003,0.626924,-0.504001,0.178171,-0.104891,0.267903,-0.076972,0.047122,-0.108699,-0.159616,0.391644,0.048748,0.050252,-0.181647,0.400151,0.062645,-0.596824,-0.671551,0.031339,0.260640,0.233132,-0.700550,0.052071,0.464318,0.126663,-0.303381,-0.526641,-0.023531,-0.119645,0.653754,0.397681,-0.064714,0.092787,-0.241181,0.803829,-0.326689,-0.315133,-0.271912,0.713980,0.039845,-0.602057,0.099746,-0.190000,-0.345663,0.189311,0.534940,-0.076924,-0.071533,-0.087635,-0.643997,-0.322895,-0.359407,0.283413,0.125019,-0.444476,0.062335,-0.673051,0.279665,-0.153900,-0.044757,-0.233265,0.296368,-0.483764,0.165709,-0.208617,0.295461,0.302948,-0.463088,-0.011711,0.379186,-0.056663,0.097761,-0.233969,0.087921,0.824332,0.150516,0.661178,0.173877,0.022238,-0.159637,-0.472616,-0.357151,0.608292', '1302193', '25797778', '3155961', '4135443');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26886408', '儿童法案', '剧情', '一位声名显赫的高等法院法官Fiona Maye，她和教授丈夫的婚姻来到破碎的临界点，而一项棘手的案件又摆在她面前：是否应该强迫一位未满18岁、拒绝接受输血治疗的白血病患者活下去？Maye前去医院探望患病男孩Adam，这起谈话带给了两人深远的影响，不仅让Adam产生全新的强烈感受，也将Maye内心深藏的情感激发出来。', '菲恩·怀特海德', '理查德·艾尔', 7.9, 8627, 'tt6040662', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2525016253.jpg', 0.2, 1.8, 23.9, 52.6, 21.5, '-0.124690,-0.109881,-0.522238,0.578550,-0.467129,-0.069650,0.928039,0.204453,-0.278529,-0.371736,0.446208,0.808383,-0.143099,0.467577,0.479476,-0.116643,0.104400,-0.487792,0.011127,0.214378,-0.576580,-0.562976,-0.135483,-0.122275,0.046977,-0.482153,0.806741,-0.036162,-0.654059,0.352164,-0.048033,0.566357,0.013836,0.618361,0.066100,-0.279099,0.003690,0.073475,-0.242391,0.256992,0.614440,-0.348263,0.182545,0.369565,-0.305557,0.303700,0.750051,-0.181097,-0.465320,0.116216,0.911499,-0.179125,0.060611,0.358962,0.085949,0.435102,-0.121854,0.333300,-0.414676,-0.021686,-0.118226,0.117415,-0.836698,-0.190857,0.140604,0.030146,-0.287302,0.274789,0.024747,-0.196484,0.127197,-0.025760,0.140778,0.394357,-0.187168,0.727545,-0.680739,-0.041319,-0.501723,0.008897,0.553953,-0.249140,-0.427898,0.132553,-0.617411,-0.507978,0.025315,-0.222464,-0.453460,0.017563,0.052414,0.347344,-0.485204,0.186278,-0.097683,-0.251461,-0.657835,-0.241961,0.208144,-0.300955,0.029249,-0.587640,-0.447948,0.167525,-0.399578,-0.282998,0.378528,-0.595288,0.913497,-0.450908,0.281966,0.544004,0.232483,-0.586756,0.727810,0.138358,0.214161,-0.364322,-0.210567,0.511263,0.005634,0.342362,-0.152873,0.165379,-0.260264,0.441918,-0.434956,0.381845', '27602116', '26315728', '2027945', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26887153', '冥王星时刻', '剧情', '导演王准前往著名演员高丽的拍摄现场探班，尽管与高丽已经分居，但王准仍希望高丽尽快确认为自己新片拍摄的档期，高丽却反过来讽刺王准剧本遥遥无期。带着现实的压力，王准结伴丁宏敏、白金铂和度春一行四人，来到湖北深山采风，为拍摄一部关于当地丧歌《黑暗传》的剧情电影做前期的勘景和素材搜集。丁宏敏是这部电影的制片人，她带着年轻的男演员白金铂随行。度春是电影学院大三的学生，也是王准的粉丝。尽管有当地向导老罗带队，四人却仍在深山中迷路。行住的艰难，使四人的心理备受煎熬，亲疏关系发生了变化，致使他们渐渐模糊了此行的目的。山林中的遭遇，与上海都市的现实犹如梦幻般的呼应，王准内心的黑暗和茫然也显露无遗。他们在暴风雨中偶遇质朴的山民、执着的村妇春苔，并终于聆听到年迈歌师在葬礼上夜唱丧歌《黑暗传》。第二天，王准在凌晨的山谷醒来，这似乎是他一直在追寻的光明。', '王学兵', '章明', 6.5, 14875, 'tt7628080', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2519560628.jpg', 2.7, 12.3, 48.6, 30.5, 5.8, '0.208228,0.072513,-0.710196,0.584696,0.316432,0.010199,0.690541,0.276959,-0.379478,-0.348086,0.323649,0.524222,-0.265812,0.213618,0.264919,-0.205752,-0.593482,-0.595176,-0.306303,0.041645,0.068688,-0.274073,-0.208781,0.038476,-0.126238,-0.215060,0.673560,0.375081,-0.244876,0.614259,0.249322,0.042678,-0.305938,0.472272,-0.145326,-0.036413,0.118310,0.098808,-0.322529,0.082161,0.096343,-0.433022,-0.427441,0.022093,-0.003889,0.637130,0.597479,0.043926,-0.100824,0.447586,0.408891,-0.327507,-0.024921,-0.033620,0.287453,0.113598,0.144774,0.117313,-0.054499,0.210039,-0.510433,-0.068195,-0.840819,0.229515,0.327023,0.304277,-0.358063,0.529410,0.107564,-0.125652,0.278353,-0.179057,0.303589,0.261354,0.031045,0.473819,-0.009540,0.060809,-0.392596,0.409524,0.581833,-0.033812,-0.208507,0.259701,-0.325377,-0.570076,-0.055987,0.027130,-0.454465,-0.016107,0.358168,0.014068,-0.243738,0.046589,-0.512295,0.045299,0.059532,-0.383372,-0.120410,-0.246808,-0.043911,-0.835550,-0.184925,-0.563148,-0.165887,-0.063970,0.343493,-0.001867,0.554965,-0.576439,0.262219,0.569833,0.129874,-0.331764,0.703926,0.064294,-0.042510,-0.194349,0.018129,0.143795,-0.186827,0.396999,0.149565,0.284981,-0.107915,-0.154891,-0.713257,0.505014', '30234315', '26577354', '25928048', '