INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26888905', '完美陌生人(西班牙版)', '喜剧', '西班牙版《完美陌生人》，翻拍自2016大热的意大利同名影片《完美陌生人》。七个常年的好朋友聚在一起吃晚餐。忽然他们决定与对方分享每一个短信的内容，包括他们收到的电子邮件和电话，由此许多秘密开始公布而他们之间的关系开始发生波动。', '贝伦·鲁埃达', '艾利克斯·德·拉·伊格莱希亚', 8.4, 65269, 'tt6101820', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2502448373.jpg', 0.2, 0.9, 13.8, 49.7, 35.4, '0.618221,-0.111166,-0.588727,0.736772,0.219696,0.225199,0.408910,0.050421,-0.544758,-0.432674,-0.467050,0.963161,-0.713615,0.191905,0.135546,-0.602616,-0.619990,-0.926007,0.294982,-0.200728,0.061642,-0.388842,-0.159930,-0.343048,0.013862,-0.013029,0.366301,-0.229196,-0.122046,0.338224,0.384863,0.027853,-0.636426,0.496007,-0.169024,0.148140,-0.042100,0.075207,-0.737430,0.057034,-0.072689,0.176792,-0.015526,0.210316,0.181783,0.617673,0.499639,0.046013,-0.563647,0.175209,0.490506,0.190148,-0.243926,0.039850,0.154320,0.722299,0.908049,0.307950,-0.009591,0.006435,-0.289321,0.013759,-0.501660,0.162169,0.123877,0.385239,0.429668,0.207825,-0.194937,0.133372,0.324722,-0.260106,0.287946,0.559337,0.335019,0.096546,0.083876,0.143101,-0.186537,0.068278,0.935942,-0.058639,-0.332046,0.350937,0.022405,-0.357972,0.067707,0.183996,0.083587,0.480501,0.241436,0.279967,0.055227,0.323380,-1.070393,0.214219,0.260181,-0.262894,0.260787,-0.671591,-0.023751,-1.241820,-0.415769,-0.375756,-0.527745,0.335748,0.041501,0.035799,0.789321,-0.597273,0.209536,0.138758,0.184745,-0.624353,0.617962,0.182282,0.026212,-0.521749,0.188268,-0.012299,0.211838,-0.038142,-0.084895,0.041689,-0.053420,0.366490,-0.576446,0.182942', '11541282', '3147969', '4301278', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26890502', '推理笔记', '剧情', '南洋大学的数学天才少女夏早安（陈都灵饰演）因一场换心手术后，被卷入了疑似器官买卖和蓄意杀人的悬案之中。与此同时，心脏原主人的好友——热血机车少年李小崇（林柏宏饰演）和夏早安倾慕的精英学长秦一凡（汪铎饰演），也和这场命案牵扯出千丝万缕的联系。救命的心脏竟成了锥心的利刃，真 情与真相的抉择背后，还隐藏着更疯狂的阴谋——一个通过数学计算就可以掌控生杀的“拉普拉斯妖”！。到底是谁实施了这场猎取心脏的完美谋杀？这场关于探寻真相与推导真爱的天才智商角逐战，始于人心，终于人心。本片改编自早安夏天所著的同名畅销小说《推理笔记》，作为一部二次元气质浓郁的校园推理小说而受到年轻书粉推崇。坐拥众多新潮IP的乐视影业此番又将该小说的电影版正式立项，由新锐导演张天辉执导，陈都灵、林柏宏、汪铎等实力年轻演员主演，更有金士杰、王刚等老戏骨倾力加盟。本片将于2017年10月20日在全国各大院线上映。', '陈都灵', '张天辉', 4.4, 9225, 'tt7326858', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2506041645.jpg', 25.8, 40.8, 26.2, 4.7, 2.6, '-0.152201,-0.019964,-0.472743,0.611775,0.281354,-0.031234,0.309981,0.015443,-0.265152,-0.194425,-0.048004,0.491462,-0.555513,0.105605,0.333031,-0.371764,-0.021978,-0.795957,-0.407096,-0.044749,-0.133020,-0.247311,-0.328110,0.041682,-0.084902,-0.216604,0.861673,0.344521,-0.463379,0.142084,0.573542,0.309581,-0.241015,0.038168,-0.007208,-0.130460,0.068956,0.197321,-0.338785,0.175860,0.090057,-0.287930,-0.039813,-0.029812,-0.063146,0.198064,0.505487,-0.180771,0.054260,-0.171195,0.689412,-0.272512,-0.106206,0.058533,0.313521,0.175708,0.229010,0.210721,0.004957,0.073869,-0.093896,-0.298520,-0.889331,-0.185233,0.228171,0.120697,-0.339409,0.122122,-0.118027,0.048533,0.045094,-0.110754,0.176721,0.161483,0.414624,0.222993,-0.040782,0.015065,-0.193079,0.388659,0.628441,0.136650,-0.201310,0.043519,0.029406,-0.771050,-0.209253,-0.170286,-0.416652,0.190910,0.388653,-0.070016,0.217817,0.411153,-0.348481,-0.137184,0.044691,-0.027057,0.132423,-0.407340,0.152511,-0.635815,-0.380622,-0.205914,0.181901,-0.134663,0.453633,-0.288029,0.882878,-0.688465,-0.002476,0.474900,0.089318,-0.363581,0.473465,0.112834,0.096128,-0.204398,0.000115,0.153757,0.080267,0.040099,0.052916,0.439445,-0.001081,-0.120875,-0.268846,0.220233', '27602116', '258