INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26891256', '阿拉丁', '爱情', '故事发生在充满了异域风情的阿拉伯王国阿格拉巴，阿拉丁（梅纳·马苏德 Mena Massoud 饰）出生在一个贫穷的家庭之中，但这并没能够妨碍他成长为一个善良而有乐观的青年。一次偶然中，阿拉丁邂逅了茉莉公主（娜奥米·斯科特 Naomi Scott 饰），茉莉公主不满足于父亲为她安排的政治联姻，想要接替国王的宝座，亲手带领国家走向富强。与众不同的茉莉公主一下子就吸引了阿拉丁的注意，两人在经历了几次意外之后渐渐的走到了一起。贾方（马尔万·肯扎里 Marwan Kenzari 饰）是一名巫师，同时也是一国之首相，他通过计谋威逼利诱阿拉丁，迫使他踏上了为自己寻找能够实现三个愿望的神灯的旅途。©豆瓣', '梅纳·玛索德', '盖·里奇', 7.4, 298015, 'tt6139732', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2553992741.jpg', 0.5, 3.7, 36.1, 45.5, 14.2, '0.333730,0.348197,-0.572655,0.808702,-0.109266,-0.353461,0.769913,0.065628,-0.521516,-0.187482,0.236428,0.771474,-0.079025,0.006069,0.366547,0.252984,-0.234897,-0.607792,0.121394,-0.145883,-0.283752,-0.475953,-0.190467,-0.338255,-0.414283,-0.489930,0.704659,0.026519,-0.018447,0.327547,0.342161,0.111487,0.070442,0.461160,-0.232956,0.035035,0.251312,-0.110691,-0.255833,0.462074,-0.112502,-0.376672,-0.238597,0.282965,-0.103420,0.196623,0.569664,-0.584893,0.082562,-0.334552,0.280307,-0.160664,0.024698,0.171936,0.172817,-0.180191,-0.031758,0.197197,-0.196544,-0.170929,0.224478,-0.223384,-0.803353,-0.008667,0.047693,0.288629,-0.686137,0.436177,0.059807,-0.274874,0.314298,-0.244887,0.352543,0.654225,0.356527,0.276693,-0.050612,0.014487,-0.517700,0.122205,0.771792,-0.084309,-0.331994,0.491598,-0.495344,-0.593015,0.079224,-0.089717,-0.551899,0.055462,0.390475,0.067985,0.026747,0.269104,-0.554835,-0.067903,-0.528228,-0.114530,0.177214,-0.644761,0.172391,-0.276473,-0.302656,-0.377446,-0.127811,0.078557,-0.025737,-0.298720,0.785343,-0.851114,0.155232,0.559633,0.201506,-0.534024,0.738063,0.161306,0.111777,-0.206713,0.086873,0.369987,-0.222564,0.129767,-0.117068,0.521013,0.122533,-0.107106,-0.352395,0.336063', '2053515', '1296569', '3230462', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26892281', '青年警察', '喜剧', '《青年警察》讲述了两位警校搭档目睹了一场绑架事件并卷入其中的故事。今日曝光预告片中，展现了朴徐俊和姜河那饰演的"行动派"基俊和"学霸"熙烈在警察学校相识相交，并一起执行任务的过程。', '朴叙俊', '金周焕', 7.5, 40317, 'tt7056732', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2496271058.jpg', 0.6, 2.9, 34.3, 45.4, 16.8, '0.344630,-0.379853,-0.225369,0.659922,-0.157367,-0.060461,0.558680,0.004038,-0.286368,-0.465636,0.172822,0.625011,-0.501561,0.198717,0.850380,-0.718346,-0.369671,-1.036399,-0.408258,0.055113,-0.347824,-0.583628,0.340334,-0.084679,0.157673,-0.285937,0.849936,0.045405,-0.608521,0.929083,0.534300,0.017415,-0.951387,0.354996,0.271308,0.085083,0.349918,0.475885,-0.409697,0.108657,-0.197935,-0.359439,0.050437,0.064266,0.095081,0.462153,0.465048,0.151293,0.076684,-0.102176,0.286930,-0.397195,0.037226,-0.273775,0.635321,0.192214,0.353691,0.494467,0.191640,-0.158726,-0.237634,-0.257684,-0.619762,-0.063039,0.288277,0.119306,-0.358731,0.373979,0.337272,0.340843,-0.006482,0.434676,0.030681,0.423081,0.607248,0.110567,0.217173,0.055307,-0.106139,0.542726,0.563696,-0.376345,-0.041172,0.411421,0.067400,-0.530259,-0.252642,0.184739,-0.099507,0.485863,0.272003,-0.058776,-0.253346,0.337651,-0.312841,-0.415225,-0.074340,-0.004544,-0.074222,-0.450639,0.194123,-1.133352,-0.523668,-0.339306,-0.455623,0.093278,-0.010204,-0.308257,0.413962,-0.645731,-0.033844,0.501683,-0.036648,-0.417897,0.643094,0.730782,0.257177,-0.593680,0.051696,-0.019785,0.271685,0.066100,-0.068213,0.469090,-0.050741,-0.288178,-0.840261,0.122355', '25723905', '2369613', '20274039', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26892546', '双面情人', '剧情', '女孩克洛伊（玛丽恩·瓦斯 Marine Vacth 饰）胃痛寻医无果，医生推断她的病情乃心病所致，推荐她去看心理医生，就这样，克洛伊成为了保罗（杰瑞米·雷乃 Jérémie Renier 饰）的患者。在保罗的循循善诱之下，克洛伊逐渐敞开心扉，向保罗坦白了她曾经的灰暗遭遇，随着时间的推移，保罗和克洛伊之间产生了超越了医患关系的感情。最终，克洛伊和保罗走到了一起，两人开始了同居生活，奇妙的事，自此之后，克洛伊再也没有胃痛过。某日，克洛伊在保罗的行李里发现了一张护照，护照上的照片虽然是保罗，可名字那一栏却写着“路易斯”，克洛伊顿时对保罗的身份产生了深深的怀疑，噩梦再一次降临了。©豆瓣', '玛丽恩·瓦科特', '弗朗索瓦·欧容', 6.7, 16409, 'tt6367558', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2458352184.jpg', 1.1, 8.1, 50.5, 33.1, 7.1, '0.347038,-0.032912,-0.591092,0.502776,0.014242,-0.508953,0.910308,0.323050,-0.661403,-0.235537,-0.017712,0.667093,-0.481721,0.224082,0.239513,0.036186,-0.539803,-0.903544,0.058048,-0.339415,-0.472274,-0.587308,-0.187489,-0.118119,0.049373,-0.486702,0.351727,-0.154790,-0.125035,0.429595,0.077633,0.170233,0.145592,0.644907,-0.039810,0.371413,0.100191,0.099900,-0.228900,0.184259,0.524265,-0.320878,0.003424,0.347743,0.011957,0.416171,0.464584,-0.160984,-0.096364,0.069385,0.284132,0.033396,-0.030275,0.255209,0.301445,0.170398,0.123266,0.132215,-0.330744,-0.164618,-0.028949,0.129347,-0.385554,0.123297,-0.251073,0.478635,-0.581829,0.492323,-0.449639,-0.232088,-0.081035,-0.369724,0.132735,0.218040,0.245834,0.320160,-0.110769,-0.062361,-0.187589,0.026335,0.495673,0.172208,-0.178515,0.566039,-0.366610,-0.285132,-0.129614,0.154162,-0.360069,-0.077306,0.364610,0.212608,-0.142817,0.395635,-0.625191,-0.200539,-0.280507,-0.306159,-0.205720,-0.223492,0.159946,-0.505024,-0.550177,-0.331606,-0.384626,-0.014063,-0.076372,-0.207786,0.524038,-0.711914,0.454274,0.433658,0.365820,-0.181626,0.561154,0.233470,0.137718,-0.023050,0.057931,0.411303,-0.096800,0.421286,0.371989,0.455257,0.310624,0.068980,-0.293084,0.704661', '1309172', '21348112', '1301582', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26892558', '叛徒', '剧情', '本片根据意大利真实事件改编而成。上世纪80年代初期，黑帮首脑多玛索·布西达从意大利移居巴西，然而远在意大利的自己的哥哥与孩子却相继被黑帮团伙杀害。为了惩治凶手，他开始与意大利警方合作，在两方的不断努力下，多玛索·布西达不仅抓住了杀害自己亲人的幕后黑手，并将意大利盘根错节的黑帮团伙连根拔起……', '皮耶尔弗兰切斯科·法维诺', '马可·贝洛基奥', 7.2, 6827, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2556201145.jpg', 1, 4.9, 37.2, 45, 11.9, '0.197945,0.201352,-0.774621,0.461144,0.101789,0.093774,0.435212,-0.018251,-0.551096,-0.054737,0.022972,0.803582,0.065910,-0.078675,0.113249,-0.117960,-0.378859,-1.018324,-0.108161,-0.279458,-0.242863,-0.527578,-0.648791,-0.275124,-0.057256,-0.104605,0.654451,0.273894,-0.359944,0.224038,0.244722,0.650965,-0.465739,0.017448,-0.205262,-0.105721,0.323603,-0.269820,-0.653190,0.250554,-0.176113,-0.462443,-0.075152,0.175667,-0.055095,0.571878,0.455999,-0.286952,0.382142,-0.291889,0.231440,-0.344976,-0.211993,0.122420,0.701722,-0.036091,0.275339,0.621604,-0.133403,-0.292864,0.199619,-0.216880,-0.779489,-0.003481,0.510167,0.077979,-0.615424,0.384315,-0.190499,0.201534,0.038872,-0.382157,0.184743,0.628414,0.271533,0.238340,-0.053929,0.112090,-0.672945,0.132779,0.907196,-0.085663,0.083553,-0.335058,0.192022,-0.374390,-0.230342,-0.568196,0.053706,-0.102463,0.656516,-0.424366,-0.303161,0.440631,-0.562157,-0.184898,-0.263131,-0.174485,0.123190,-0.286792,0.149000,-0.588796,-0.294714,-0.210082,-0.098238,-0.054739,0.028432,-0.175243,0.569624,-0.617798,0.203479,1.067618,0.349714,-0.407492,0.242372,-0.072199,0.242183,-0.262416,-0.615921,0.143273,0.580305,0.146242,0.250259,0.199952,-0.316078,-0.175357,0.078529,0.108149', '1293829', '1294181', '1307442', '1306454');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26894593', '蜡笔小新：宇宙人来袭', '喜剧', '某一天，宇宙人西里里来到小新家中，并使用特使光线把变爸爸野原广志和妈妈野原美伢回了小孩子模样，如果想恢复现状，必须帮助西里里找回自己的父亲，就这样大家踏上了寻找之旅……', '矢岛晶子', '桥本昌和', 7.5, 9950, 'tt6809936', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2441976102.jpg', 1.1, 5.1, 36.4, 33.8, 23.6, '-0.063383,0.131620,-0.272684,0.075738,-0.150240,-0.671325,0.357772,0.135357,-0.576817,-0.175168,-0.306119,0.594293,0.128984,0.700880,0.363944,0.550879,-0.847008,-0.290290,0.447026,-0.174246,0.387265,-0.399072,-0.174726,0.073082,0.081020,-0.351764,0.345915,0.033347,-0.121752,0.233729,-0.419092,-0.086092,0.013686,0.516586,0.119983,0.188897,-0.267555,-0.102468,-0.361478,0.506859,0.144147,0.388303,0.166257,0.333710,0.433816,0.076115,0.495606,-0.608049,-0.140817,-0.299097,-0.098778,-0.073807,-0.406095,0.416555,-0.025844,0.109241,0.517448,0.259140,-0.348556,0.075773,-0.155636,-0.203453,-0.091050,0.275691,0.090332,0.009423,-0.746788,-0.126109,0.089296,-0.146871,0.441485,-0.364379,0.161302,0.348350,0.216191,0.332490,-0.225511,0.092237,-0.212902,-0.342670,0.661201,-0.378200,0.126778,0.185259,0.477922,-0.153979,0.308715,0.176038,-0.187564,0.197815,-0.266342,-0.036784,-0.225081,0.070810,-0.669594,0.406198,-0.675157,-0.168432,-0.013333,-0.234900,-0.191286,-0.315137,0.364356,0.245421,-0.138333,-0.115135,-0.032303,-0.448057,0.628969,-0.788114,0.133556,-0.006044,0.640064,-0.248854,0.212374,-0.226239,-0.023370,-0.635014,0.362785,0.243701,-0.207457,0.847447,-0.041999,-0.042280,-0.056397,-0.000583,-0.297248,0.445815', '2976111', '1926007', '1408130', '26280899');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26894602', '冷战', '剧情', '故事开始于1949年的波兰，第二次世界大战刚刚结束，资本主义和社会主义的对立抵达了白热化的状态。维克多（托马斯·科特 Tomasz Kot 饰）是一名音乐家，他正在筹建一个青少年民族音乐演出团，靠演出传统波兰歌舞来输出国家的文化，制作人伊雷娜（阿伽塔·库雷斯扎 Agata Kulesza 饰）和监督官员卡奇马雷克（波利斯·席克 Borys Szyc 饰）也参与进了这一计划中。一个名为祖拉（乔安娜·库里格 Joanna Kulig 饰）的女孩吸引了维克多的注意，虽然卡奇马雷克并不认为这个身世复杂的女孩是参加演出团的合适人选，但维克多还是义无反顾的认定了她。随着时间的推移，两个人坠入了情网之中。©豆瓣', '尤安娜·库里克', '帕维乌·帕夫利科夫斯基', 7.8, 29013, 'tt6543652', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2526989708.jpg', 0.3, 2.3, 24.3, 50.7, 22.3, '0.295860,0.151014,-0.574552,0.557750,-0.107989,-0.131689,0.595576,-0.135226,-0.461141,-0.375410,-0.012147,0.794426,-0.195283,0.115458,0.593209,0.077892,-0.441767,-0.823098,-0.164834,-0.147308,-0.278611,-0.607810,-0.217097,-0.281413,-0.203863,-0.216461,0.552981,0.128116,-0.284019,0.557385,0.352287,0.142689,0.064451,0.281219,0.133694,-0.158749,0.528807,-0.466831,-0.039455,0.112120,-0.049184,-0.226927,-0.150580,0.081289,0.099292,0.488461,0.614394,-0.310343,0.363922,-0.117528,0.337415,-0.219323,-0.232168,0.123502,0.340350,0.028162,-0.035458,0.050980,-0.194585,0.113474,-0.195601,-0.465960,-0.654194,0.130495,0.097316,0.197938,-0.468217,0.576731,-0.013675,-0.091586,-0.103467,-0.260628,0.177943,0.387630,0.289321,0.522371,-0.120953,-0.184600,-0.228216,0.160281,0.588325,0.082275,-0.401543,0.253228,-0.279099,-0.685016,-0.190629,-0.090062,-0.125805,-0.272588,0.352997,0.046425,0.064104,0.142406,-0.708294,0.086512,-0.125067,-0.418170,0.020948,-0.344732,-0.032215,-0.628554,-0.242473,-0.579880,-0.217294,0.041704,-0.027032,-0.129925,0.908473,-0.723392,0.053043,0.572077,0.265945,-0.263670,0.729824,0.145346,0.324503,-0.201388,-0.062665,0.236830,-0.201379,-0.014689,-0.051766,0.581262,-0.000149,-0.484472,-0.345989,0.392698', '3811356', '30162520', '2997404', '1292943');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26895438', '神探狗笨吉', '剧情', '“笨吉”原本是一只吃百家饭的流浪狗。它最喜欢一对兄妹，因为他俩经常瞒着妈妈悄悄陪它玩耍，喂它美食。某天，这对兄妹被坏人绑架。在妈妈和警方都惶恐不安而又无所适从之时，聪明勇敢的“神探狗”笨吉克服险阻，用自己的方式救出了这对兄妹，也找到了梦寐以求的家。笨吉的故事提醒我们，身边的宠物或许就是拯救人类的英雄。', '费尔菲尔德', '布兰登·坎普', 6.7, 5169, 'tt1799516', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2541725145.jpg', 1, 9.4, 55.4, 23.5, 10.7, '0.279314,-0.549121,-0.414360,0.368335,-0.113469,-0.251202,0.613902,0.014512,-0.273415,-0.075703,0.046816,0.725612,0.139313,0.325490,0.107375,0.030494,-0.228012,-0.406262,0.156548,-0.053335,-0.158499,-0.101200,-0.247711,-0.055046,0.045507,-0.062989,0.291495,-0.149244,-0.159638,0.621537,0.175887,-0.075594,-0.053916,0.148261,-0.438046,0.046444,-0.092342,0.396380,-0.303022,-0.036404,0.193842,-0.009331,0.136026,0.415294,-0.025000,-0.006307,0.552785,-0.721997,-0.340461,-0.283147,-0.278044,-0.710931,0.055372,0.125786,0.201958,-0.259451,0.375260,-0.081655,-0.024631,-0.020012,0.018724,0.128333,-1.000017,-0.113893,0.017627,-0.077512,-0.445368,0.254738,0.237495,0.056055,0.408175,-0.307099,0.422491,0.470532,0.173230,0.504119,-0.435220,0.055355,-0.668059,-0.019796,0.730843,-0.247978,0.275839,0.353167,-0.220933,-0.236668,0.545747,-0.404348,-0.496318,-0.058350,0.065523,0.054600,-0.598651,0.171663,-0.631022,0.218459,0.110874,0.049725,0.228233,-0.868120,-0.133775,-0.163516,0.169132,-0.588267,-0.040311,0.217387,0.207658,-0.381119,0.956845,-0.693514,0.342061,0.664932,0.383888,-0.712331,0.943086,0.190686,-0.084872,-0.358631,-0.116513,0.008746,0.241037,0.270411,0.203682,0.265724,0.334715,0.068777,-0.691942,0.371041', '30163500', '24284209', '26678784', '3755531');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26897427', '引爆者', '动作', '本片讲述了矿上的爆破工人赵旭东（段奕宏 饰）在一次矿难中侥幸逃生，却发现了这是一个巨大的阴谋。随着调查的深入，他也被逐渐卷入了漩涡中心。他的女友萧红（余男 饰）因此受到牵连成为人质，他的旧友徐警官（王景春 饰）也在追捕他的同时越陷越深。最后赵旭东在警方追捕下与当地幕后煤矿老板程飞（成泰燊 饰）及其手下，在危机重重的废弃工厂展开殊死搏斗！我的命，我说了算！', '段奕宏', '常征', 6.3, 28916, 'tt7509586', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2503142311.jpg', 1.8, 14.7, 56, 22.5, 5, '-0.038897,0.046953,-0.687344,0.441915,-0.100070,-0.326616,1.038143,0.152916,-0.578825,-0.124985,0.452993,0.432595,-0.041312,-0.046411,-0.096832,-0.182355,-0.244188,-0.497129,-0.269206,-0.003744,-0.304424,-0.484908,-0.311417,-0.168409,-0.062574,0.083175,0.455674,0.384647,-0.288592,0.205456,0.369760,0.310278,-0.238826,0.721619,-0.018183,0.315186,0.196820,-0.128237,-0.217549,0.055259,-0.003737,-0.661330,-0.088753,0.033061,-0.002376,0.652048,0.707832,0.018504,-0.020732,-0.182091,0.359043,-0.469447,0.014036,-0.025260,0.448060,0.139420,-0.050598,0.139285,-0.498746,-0.121820,0.242380,0.187479,-0.684931,-0.017417,0.254171,0.285526,-0.739535,0.141113,0.137449,0.097367,0.008419,-0.300871,0.344235,0.316148,0.200447,-0.172079,-0.233928,0.107354,-0.618260,0.596292,0.730728,0.033285,0.067300,-0.227960,-0.072799,-0.579848,-0.094676,0.125489,-0.327780,-0.270177,0.767948,-0.181104,-0.016247,0.074828,-0.454161,-0.189410,-0.258953,-0.019715,-0.425409,-0.382915,-0.051692,-0.518702,-0.129478,-0.287736,-0.065704,0.193613,-0.122692,-0.289903,0.325536,-0.577105,0.032965,0.669305,0.238217,-0.415129,0.478232,0.139887,0.225320,-0.299969,-0.052168,-0.095085,0.168855,0.535100,0.325718,0.495879,0.060840,-0.260562,-0.202894,0.073232', '21619567', '1947080', '3011051', '1578663');
