INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26898747', '父子雄兵', '喜剧', '梦想靠大项目咸鱼翻身的范小兵（大鹏 饰）始终无法摆脱一个阴影，那就是退伍军人出身的老爹范英雄（范伟 饰）。小兵油嘴滑舌爱忽悠，英雄刚正不阿会武术，小兵斗英雄，天雷勾地火。卤煮店小老板刘雯（张天爱 饰）与小兵相识十年，两人友达之上恋爱未满，她是小兵唯一愿意吐露真心的港湾。范小兵欠下大老板OK哥（任达华 饰）的钱，被追债小弟方健（乔杉 饰）一路折磨，倒霉不断，还面临凶狠狗哥（梁龙 饰）的生命威胁。范小兵不得已将弄钱对象转向老爹，不知情的范英雄此时正躲闪着邻居邬仙仙（邬君梅 饰）如狼似虎的猛烈追求，殊不知儿子范小兵已经针对自己开启了一个搞笑又荒唐的惊天计划……', '大鹏', '袁卫东', 4.6, 35964, 'tt6186248', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2492957074.jpg', 19.9, 40.3, 31.3, 6, 2.5, '-0.078282,-0.197042,-0.102431,0.278677,-0.176646,-0.150022,0.430447,0.083841,-0.312556,-0.204268,0.405943,0.270595,0.056358,0.273049,0.113428,-0.287445,0.203324,-0.342967,-0.031057,0.330998,-0.110538,-0.422022,-0.201635,-0.364527,-0.239146,0.079423,0.344487,0.119985,-0.198779,0.049326,0.716821,-0.013767,-0.081169,0.179984,0.064607,0.196968,0.148815,-0.037698,-0.226063,-0.047978,-0.061143,-0.219744,0.061360,0.055923,0.060391,0.304324,0.472315,-0.089960,0.084614,-0.201867,0.307510,-0.226582,0.030199,-0.102267,-0.006306,-0.038317,0.194903,-0.356563,0.354875,-0.039833,0.200905,-0.287783,-0.340096,0.026729,0.165741,-0.272720,-0.532498,0.240160,0.145853,0.220057,0.086909,-0.022897,-0.227048,-0.154803,0.494723,0.196436,-0.167462,0.271056,-0.398868,0.605261,0.320213,0.197533,-0.105725,0.278595,-0.090518,-0.227081,-0.107457,-0.285841,-0.588971,-0.012683,0.336739,-0.039912,0.023164,0.168369,-0.214295,0.040223,-0.146290,0.699210,-0.018910,-0.187812,-0.197843,-0.179456,0.013221,-0.133507,-0.054724,0.523543,0.090122,-0.021752,0.471286,-0.432327,-0.147835,0.299293,0.439128,-0.181197,0.545314,0.116538,-0.276862,-0.522542,0.108129,0.099515,0.081210,-0.058141,0.448638,0.053580,-0.447492,-0.248499,0.050408,0.214738', '1304309', '7161707', '1307320', '1316525');
