INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26899146', '雪暴', '动作', '电影《雪暴》讲述了在一座极北的边陲小镇，一伙穷凶极恶、作案手法老到的悍匪为抢夺黄金，打劫运金车，并借助大雪掩盖了所有犯罪痕迹。为了探求真相，警察王康浩暗地里搜集证据，熟悉地形，终于在一场灾难级的暴雪降临时，与谋财害命的悍匪发生了惊心动魄的正面对决……', '张震', '崔斯韦', 6.1, 61271, 'tt9742422', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2551995600.jpg', 1.9, 18.5, 57.9, 18.3, 3.4, '0.203481,-0.397010,-0.620015,0.472521,0.050777,0.212485,0.604553,-0.286459,-0.322874,-0.352945,0.579974,0.240561,-0.124014,-0.409183,0.242796,-0.355772,-0.283355,-0.601957,0.088440,-0.056552,-0.319611,-0.190883,-0.611382,-0.266087,0.224951,-0.335601,0.497431,0.714877,-0.733586,0.142598,0.130053,-0.036321,-0.551020,0.189404,-0.311630,-0.563320,-0.268589,0.072404,-0.418394,0.275522,-0.645326,-0.530985,-0.202773,0.035868,-0.154789,0.531535,0.783818,-0.457916,-0.134246,0.119865,0.284136,-0.565989,0.089550,0.115779,0.551086,-0.027277,-0.251627,0.405383,-0.093135,-0.262189,-0.109502,-0.105387,-1.014009,-0.089205,0.003892,0.147412,-0.217002,0.366747,0.231662,0.141213,-0.021193,-0.027269,0.365339,0.350231,0.329988,0.175176,0.168441,-0.217638,-0.513840,0.209871,0.842770,-0.244793,0.148245,0.186850,-0.068820,-0.422258,-0.048299,-0.345659,-0.042422,0.245468,0.396891,-0.246014,-0.365861,0.425880,-0.982972,-0.002205,-0.326655,-0.284216,-0.270561,-0.035387,-0.308537,-0.820800,-0.381452,0.021791,-0.036658,0.040885,0.200566,-0.125406,0.280238,-0.441203,0.194419,0.845276,0.104276,-0.318603,0.068531,-0.156498,-0.105935,0.055643,-0.210161,0.165690,0.465360,0.751063,-0.066816,0.083079,0.046236,-0.157012,0.035841,0.262255', '4014397', '7155241', '26747274', '1308784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26900949', '天使陷落', '动作', '美国总统（摩根·弗里曼饰）在遭遇无人机恐怖袭击后身受重伤陷入昏迷，随行人员在多次爆炸中全军覆没，唯一的幸存者——总统多年贴身保镖迈克·班宁（杰拉德·巴特勒饰）却成最大嫌疑犯，被FBI控告企图暗杀总统。班宁必须给自己洗刷冤屈，同时阻止真正的刺杀总统计划，在多方势力围追堵截下，走投无路的他只能寻求一名神秘人的保护……曾经的英雄保镖如今变为通缉犯，班宁将如何脱离险境、保护总统，破解背后的阴谋？', '杰拉德·巴特勒', '里克·罗曼·沃夫', 6, 46936, 'tt6189022', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2556827040.jpg', 1.6, 16.8, 64.1, 15.2, 2.3, '-0.206955,-0.086422,-0.440799,0.376449,-0.295114,-0.048063,0.376574,-0.020709,-0.772102,-0.623986,0.873378,0.762076,0.136108,-0.053063,0.420165,-0.052427,-0.358202,-0.678136,-0.304025,0.013522,-0.472756,-0.590994,-0.560291,-0.423505,0.093039,-0.424913,0.871292,0.270107,-0.236359,-0.053981,0.342679,0.661833,-0.325493,0.294117,0.126459,-0.092638,0.638491,-0.573158,-0.701078,0.573335,-0.094209,-0.545629,-0.084438,0.222169,-0.202288,0.304953,0.253577,-0.439391,0.131626,-0.218475,0.157181,-0.714877,0.037403,0.229622,0.464209,-0.067125,0.075165,0.258980,-0.178729,-0.169246,0.185100,0.099946,-0.867057,-0.049460,0.066610,-0.056240,-0.515592,0.201323,-0.468727,0.459127,-0.068644,0.038371,0.144572,0.542157,0.046542,0.063388,-0.210929,0.503722,-0.546720,-0.103663,0.899590,-0.135139,0.060548,-0.609134,-0.022115,-0.108360,0.137988,-0.764332,-0.270109,-0.022312,0.470980,-0.174263,-0.125202,0.311425,-0.108562,-0.179058,-0.977936,-0.007459,-0.315353,-0.187055,0.049946,-0.686516,-0.200045,0.341981,0.089288,-0.012504,0.002036,-0.127819,0.391533,-0.457378,0.418917,0.707763,0.168888,-0.428612,0.114275,0.309524,0.351309,-0.502532,-0.234712,0.355249,0.474931,0.427503,0.260294,-0.272474,-0.085262,-0.209525,-0.037207,-0.098140', '25662337', '27073234', '1482099', '1482063');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26902245', '相爱一天', '剧情', '德查（辰塔维·塔纳西维 Chantavit Dhanasevi 饰）是一个性格非常腼腆的小伙子，平日里在职场上就犹如隐形人一般的存在。只有当同事的电脑发生故障时，他们才会想到这里还有一个会修电脑的德查存在。一次偶然中，德查邂逅了名为努伊（尼塔莎·吉拉尤吉恩 Nittha Jirayungyurn 饰）的女孩。努伊的单纯和善良一下子击中了德查，令她坠入情网之中。然而，害羞的德查当然不会将自己汹涌的感情告诉努伊，而是选择将一切都默默的藏在心底。一场车祸中，努伊头部受伤，竟然患上了暂时性失忆症，仅仅失去了一天的记忆。德查得到了一个千载难逢的机会，他谎称自己是努伊的男朋友，两人之间的关系终于有了进展。©豆瓣', '辰塔维·塔纳西维', '班庄·比辛达拿刚', 7.4, 8012, 'tt6168298', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2377982803.jpg', 1, 5, 33.4, 41.8, 18.8, '0.366448,-0.017682,-0.664187,0.612270,-0.143647,-0.209360,0.879410,-0.077155,-0.479224,-0.336992,-0.028346,0.683831,-0.451078,0.083273,0.117213,0.049550,-0.138686,-0.808805,-0.027140,-0.301001,-0.398925,-0.451523,-0.483371,-0.033131,-0.003114,-0.329988,0.281155,0.063909,-0.183026,0.183305,0.171464,0.412334,0.093259,0.684114,-0.055322,-0.020696,0.035023,0.084116,0.195039,0.243814,0.095852,-0.244476,0.246365,0.494520,0.038285,0.489310,0.574982,-0.431626,-0.226836,-0.084926,0.202685,-0.056430,-0.006334,0.049999,0.290376,-0.186457,0.303815,0.066213,-0.319788,-0.030964,0.342434,-0.097415,-0.747945,-0.149286,0.097932,0.019970,-0.426677,0.242723,0.188005,-0.280712,0.029298,-0.203617,0.297669,0.293542,0.445945,0.288929,-0.130442,-0.150209,-0.473115,-0.102813,0.591407,-0.062555,-0.376846,0.725522,-0.183808,-0.416057,-0.061731,-0.085587,-0.464538,0.226852,0.231424,0.135752,-0.265608,0.272795,-0.328679,0.025643,-0.310730,-0.005923,-0.243624,-0.448525,0.007325,-0.209970,-0.145491,-0.302398,-0.297658,0.086172,-0.210859,-0.212751,0.592803,-0.779468,0.292361,0.481644,0.208493,-0.105349,0.599548,0.053522,-0.112993,-0.158854,0.271542,0.192908,0.023743,0.044605,-0.038088,0.278324,-0.092064,-0.095308,-0.166262,0.766677', '24756472', '25763555', '4275444', '3059036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26905469', '金蝉脱壳2：冥府', '动作', '越狱专家布雷斯林（史泰龙 饰）有三个学生：周树（黄晓明 饰）、卢克和金布罗，三人性格迥异，行事风格大相径庭。在保护表弟马雨声的一次行动中，周树和表弟被一起抓进一座名为“冥府”的超级监狱。布雷斯林为了营救爱徒，在逃出海上监狱“坟墓”之后再陷 “冥府”。这一次监狱难度更高，困难升级，对抗一触即发。师徒几人在监狱中艰难保命。监狱外，同样在追查这座地下监狱的同行德罗萨（戴夫·巴蒂斯塔 饰）与他们并肩作战。最终在狱友和团队的帮助下，三人与人工智能狱长几大反派展开殊死决战，一场大战即将开启。', '西尔维斯特·史泰龙', '史蒂芬·C·米勒', 3.2, 42949, 'tt6513656', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2524134770.jpg', 56.1, 31.1, 10.8, 1.5, 0.6, '0.033782,0.069257,-0.769942,0.714638,0.238677,-0.215228,0.878482,0.046037,-0.475943,-0.246387,0.213788,0.678926,-0.197430,0.020009,0.117942,-0.661306,-0.510523,-0.445902,-0.477001,-0.071662,-0.509315,-0.689981,-0.240487,-0.286914,-0.052561,-0.247924,0.633733,0.289532,-0.240907,0.372707,0.480588,0.295069,-0.577409,0.029803,0.003567,-0.163799,0.352468,0.159146,-0.549214,0.234555,-0.102077,0.197387,-0.156687,-0.120678,0.495126,0.092677,0.514690,-0.359928,-0.023576,-0.043343,0.048472,-0.105629,-0.241499,0.092328,0.479779,-0.291215,0.167820,0.218935,-0.042121,0.001793,-0.049099,-0.264168,-0.581687,0.050731,0.296440,-0.245531,-0.543097,0.144485,0.160907,0.219014,0.112809,-0.136697,0.017369,0.641208,0.691586,0.172060,-0.120105,-0.036044,-0.511197,-0.108060,0.910820,-0.184062,0.144169,-0.260820,0.095477,-0.490714,-0.395371,-0.181566,-0.312509,-0.081836,0.499401,-0.393451,0.034208,0.216165,-0.577311,-0.182683,-0.310210,0.050836,-0.201424,-0.211685,0.186373,-0.944379,0.020887,-0.279920,-0.140352,0.313170,-0.023097,-0.205935,0.359737,-0.669045,0.200708,0.270014,0.311599,-0.277476,0.648108,0.060979,0.553140,-0.350290,0.153952,0.162495,0.432129,0.325363,0.330572,0.579612,-0.074935,0.085944,-0.523350,0.230440', '10466639', '11541282', '3147969', '3606973');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26905717', '人类清除计划4', '科幻', '电影聚焦于导致清除计划发生的原因，讲述了由于人口膨胀，社会问题加剧，一个名为New Founding Fathers of America的组织进行了一种社会学理论测试，即在某一孤立的社区进行为时一晚的发泄、攻击、侵略，促成社区人们之间的相互残杀。这一制度在全美推广，一时间马路街道都成为了杀戮的战场。故事的荒谬性吸引了大量观众，第一年的杀戮日就要降临，恶魔们都已经准备好了。', '伊兰·诺尔', '杰拉德·麦克穆雷', 5.7, 19958, 'tt6133466', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2525919199.jpg', 6.9, 28, 46.2, 13.3, 5.6, '0.071975,-0.001592,-0.605009,0.445506,0.234434,0.030950,0.481592,0.087007,-0.138797,0.012364,0.414682,0.324941,-0.477285,-0.048996,0.662375,-0.607507,-0.142368,-0.827601,-0.103990,-0.045456,-0.490782,-0.272728,-0.179258,-0.581745,-0.040900,-0.676643,0.700873,0.388489,-0.750509,-0.047475,-0.030441,0.138369,-0.052596,0.600574,0.138820,-0.356614,0.098744,-0.037069,-0.279691,0.165033,-0.358525,-0.349340,-0.166977,0.141631,-0.296300,0.419848,1.019144,-0.332269,-0.193470,-0.435887,0.503779,-0.315774,-0.133045,0.033181,0.654711,0.136001,-0.041081,0.444007,-0.187696,0.152580,0.006515,-0.022356,-1.047292,-0.294533,-0.012375,0.045847,-0.233553,0.588203,0.344436,-0.074002,-0.203940,-0.012742,0.068108,0.713415,0.397021,0.496217,-0.079592,-0.114187,-0.128960,0.354550,0.758444,-0.255867,-0.537438,0.390945,-0.454373,-0.325712,-0.214272,0.125800,-0.057449,-0.541992,0.385057,0.110115,-0.448769,0.661890,-1.000834,-0.225874,0.020359,-0.879943,0.347944,-0.345606,-0.138052,-0.990225,-0.244135,-0.013239,0.089164,0.117062,0.232174,0.097783,1.074477,-0.747577,0.092989,0.720797,0.192389,-0.824535,0.440970,0.163436,0.224247,-0.001244,-0.166583,0.011725,-0.125460,0.655579,0.020992,0.402455,-0.079588,-0.027129,-0.501024,0.700269', '4181031', '26946510', '3318306', '1292444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26907450', '麻烦家族', '喜剧', '一对老夫妇结婚50周年前夕，丈夫问妻子想要什么生日礼物，得到的答案却是“离婚协议书”。老夫妻闹离婚的事件在家族里引起了轩然大波，家族中的每个人都借此事宣泄心中积攒的怨气，导致家里“乱成一团”。', '黄磊', '黄磊', 4.5, 18645, 'tt6349844', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2457986350.jpg', 24.6, 38.9, 27.2, 6.9, 2.4, '-0.101106,-0.028054,-0.846754,0.286432,0.232341,-0.206937,0.305821,-0.073657,-0.504511,-0.421862,-0.216549,0.712348,-0.299985,0.782152,-0.157098,-0.077315,-0.192709,-0.595424,0.213788,-0.334352,0.132807,-0.417830,0.328072,-0.030312,-0.199116,0.182599,0.393301,0.038844,0.062398,0.294011,0.625714,0.276788,-0.261822,0.378171,0.485377,0.017991,0.056903,0.488019,-0.693815,-0.045029,0.150061,0.153666,-0.040492,0.366329,0.289719,0.515587,0.157857,0.061012,0.063590,-0.002801,0.567182,-0.169258,-0.303819,0.422282,0.660510,0.415810,0.551799,0.643068,-0.774432,-0.304198,0.092290,0.216969,-0.168500,-0.038797,0.383203,0.225059,-0.576911,0.266818,0.006312,0.113241,0.119840,0.160685,0.711116,0.674145,0.062479,0.524083,-0.345405,0.234796,-0.574102,-0.086313,0.940295,-0.573585,0.310373,-0.281330,-0.143424,0.106671,0.244478,0.002060,-0.425315,0.248085,-0.019344,0.119330,-0.087743,0.819349,-0.139409,-0.158860,-0.436808,-0.044596,0.368530,-0.549892,-0.200314,-0.440515,-0.522106,0.267508,-0.303128,0.044421,0.366422,-0.134184,0.629647,-0.158526,-0.107688,0.075720,0.552316,-0.856118,0.216214,0.249845,0.446243,-0.615367,-0.061887,-0.230157,-0.105313,-0.262231,-0.137902,-0.471060,0.287416,-0.122943,0.182738,0.267902', '1428876', '1765127', '4145476', '1292869');
