INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26908280', '美国动物', '剧情', '斯宾塞（巴里·基奥汉 Barry Keoghan 饰）和沃伦（伊万·彼得斯 Evan Peters 饰）是从小玩到大的青梅竹马，总有古灵精怪的念头出现在他们的脑海里，这么多年，他们不知道联手惹过多少麻烦。大学枯燥的课业生活令两个男孩感到窒息，他们急需找点乐子。一次偶然中，他们发现大学图书馆里收藏了价值不菲的奥杜邦版画原作，以及一些同样非常昂贵的原版画册，一个糟糕的念头应运而生，这或许能够成为他们的财富密码。说干就干，斯宾塞和沃伦找到了另外两个朋友做帮手，一行四人制定了一个他们看起来天衣无缝，实际上漏洞百出的偷窃计划，在执行计划的过程中更是意外频频。©豆瓣', '埃文·彼得斯', '巴特·雷顿', 7, 17440, 'tt6212478', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2511158398.jpg', 1, 5.8, 44.9, 39.6, 8.7, '0.509413,-0.143142,-0.794912,0.618536,-0.131274,-0.166746,0.641392,-0.021340,-0.760125,-0.592976,-0.142007,0.768507,-0.184061,0.156872,0.168434,-0.349353,-0.273251,-0.379181,0.084263,-0.510690,-0.091811,-0.669585,-0.412053,-0.408465,-0.124947,-0.272071,0.418326,0.213663,-0.008584,0.443315,0.169758,0.354294,-0.029122,0.221904,-0.179417,-0.082360,0.388181,-0.077731,-0.108916,0.098292,-0.031896,0.126667,0.075895,0.239366,0.170917,0.240193,0.646390,-0.008124,-0.318328,0.114487,0.432278,-0.015738,-0.274691,-0.146166,0.206515,0.051921,0.341229,0.033603,-0.122682,0.043114,0.085965,-0.241594,-1.004318,0.046736,0.260486,0.223693,-0.773604,0.205300,-0.012783,-0.118591,-0.138908,-0.279299,0.162420,0.401227,0.688588,0.203373,-0.038971,0.166417,-0.516955,0.004399,0.713326,-0.167601,-0.073404,0.391236,-0.276457,-0.315533,0.121837,-0.094132,-0.204166,0.095857,0.354014,-0.111015,-0.118170,0.080775,-0.545098,0.262271,-0.150707,-0.077449,-0.069479,-0.533443,-0.059355,-0.664934,-0.205809,-0.264083,-0.500237,0.296587,-0.001255,-0.323540,0.861967,-0.622078,0.097996,0.505444,0.187191,-0.348774,0.516361,0.196040,0.124823,-0.279258,-0.008489,-0.088406,-0.002855,-0.022419,0.047149,0.360738,0.165385,-0.200349,-0.362774,0.490262', '1793491', '25928048', '26678784', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26909423', '路过未来', '剧情', '耀婷（杨子姗 饰）是在深圳出生长大的甘肃人，除了办理身份证外她再没去过甘肃。如今在深圳打工二十多年的父母决定返回甘肃农村老家生活，耀婷看到父母在村子里生活并不如意，她想通过自己的努力把父母重新接回深圳生活。小混混新民（尹昉 饰）的出现，彻底改变了她的生活......', '杨子姗', '李睿珺', 6.5, 6749, 'tt6838570', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2519031460.jpg', 2.1, 14.6, 47.3, 26.6, 9.4, '0.199974,-0.203347,-0.706266,0.413750,-0.436005,-0.218722,0.408261,0.214439,-0.734289,-0.438990,-0.206688,0.757195,0.447638,0.771695,-0.029305,-0.141227,-0.585999,-0.561409,0.540012,-0.313462,-0.234699,-0.206655,0.214982,-0.285199,-0.111933,-0.108509,0.318604,0.082871,0.197572,0.366655,-0.214913,-0.144059,-0.435698,0.328962,-0.541467,0.270281,-0.408014,0.397985,-0.548572,0.200793,0.113909,-0.321829,-0.122932,-0.147932,0.650144,0.259565,0.675268,0.415774,-0.193644,-0.065803,0.120437,0.183158,-0.525842,0.150741,0.130857,-0.086143,0.059998,0.190698,-0.432472,-0.044667,-0.050346,-0.241444,-0.107763,0.075446,-0.099513,0.143769,-0.894962,0.427628,0.121130,0.007017,-0.153909,-0.721772,0.276787,0.597342,-0.319611,0.572746,-0.161446,0.397846,-0.410215,0.977036,0.983328,-0.394874,-0.039538,0.063344,-0.019328,-0.211722,0.290176,-0.066199,-0.497493,0.134092,-0.163063,-0.047267,-0.566992,-0.083483,-0.410036,0.170861,0.100789,-0.439086,0.395239,-0.186726,-0.226521,-0.509222,-0.092155,-0.497246,-0.373608,0.098237,-0.140591,-0.338676,0.242048,-0.990067,0.078691,0.182725,0.855970,-0.923275,0.821253,-0.051793,0.389224,-0.245418,0.424972,0.588965,0.029066,0.649117,-0.135650,-0.096547,-0.270116,-0.004178,-0.360339,0.608580', '1308035', '2080130', '1926007', '6890343');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26909787', '三重威胁之跨国大营救', '动作', '东南亚的热带丛林，龙飞（陈虎饰）正与搭档帕于（托尼·贾饰）参加一项秘密任务，配合一个突击小队进行人道主义救援，但没想到，他们拼死救下的却是一个做恶多端令人闻风丧胆的犯罪头子柯林斯（斯科特·阿金斯饰）。柯林斯被救后，把所有知情人都锁在秘密基地的地牢里，临走时一炸了之，龙飞与帕于在生死关头逃了出来。逃出生天的二人秘谋报仇，但想报仇的不止他们，扎卡（伊科·乌艾斯饰）的妻子在这次行动中无辜殒命，扎卡在地下拳馆见到龙飞，误认为他是凶手，以死相搏，却因伤不敌，被龙飞打昏。龙飞和帕于好心把扎卡接到住处里休息，三人把酒言欢，没想到第二天一早，扎卡不见了，全副武装的警察却找上门来，原来扎卡举报他俩参加地下拳赛，两人被带到警察局关了起来。中国富商的女继承人田小娴（卢靖姗饰）来到马哈扎雅推动贫民窟改造计划，但她的计划侵犯了当地黑帮的利益进而遭到追杀，田小娴被迫逃入警局，没想到警局也不是安身之地，柯林斯带着他的雇佣兵突袭警局，田小娴再度处于危险之中。正好被关在警局的龙飞识破了黑帮的计谋，和帕于一起带田小娴逃走。黑帮血洗警局，然后栽赃给龙飞和帕于，无奈之下龙飞和帕于只好带着田小娴开始了逃亡之旅。因为黑帮的高额赏金，三人无处藏身，而这时扎卡也加入了柯林斯的队伍，敌友不明。一路历险，田小娴对龙飞和帕于建立起信任关系，扎卡也发现追杀龙飞和帕于的恶势力都是被一个姓苏的女人暗中操控着，她才是他真正的仇人。决战时刻，扎卡加入了龙飞的阵营，三人联手对抗全部武装的柯林斯一伙……', '陈虎', '杰西·约翰逊', 4.5, 3830, 'tt6643972', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2551252121.jpg', 18.4, 44.5, 32.6, 2.7, 1.8, '0.355662,-0.180960,-0.784124,0.549796,-0.030170,-0.266735,0.526802,-0.105476,-0.420767,-0.192084,0.315856,0.649370,0.090927,0.181703,0.312688,-0.193654,-0.278395,-0.660096,-0.252012,-0.198807,-0.362300,-0.595671,-0.194577,-0.197834,0.018163,-0.080430,0.323340,0.155895,-0.266883,0.627516,0.348106,0.360390,-0.421385,0.603036,-0.114919,0.062520,0.330816,-0.306569,-0.272649,0.361286,-0.028289,-0.236068,-0.305318,0.280436,0.089770,0.492769,0.550950,-0.276489,0.046923,-0.243975,0.044066,-0.628681,-0.034448,0.101397,0.590446,-0.233874,0.084586,0.262718,-0.118388,-0.028095,0.068541,0.087561,-0.780415,0.222847,0.168511,-0.015885,-0.581649,0.145744,-0.101090,0.268684,0.136799,-0.180869,0.250899,0.439641,0.206281,0.142495,0.052029,0.004659,-0.757979,-0.287535,0.762670,-0.422057,0.084378,-0.217096,0.237046,-0.262511,0.163060,-0.132746,-0.102282,-0.260684,0.477268,-0.106045,-0.073355,-0.046431,-0.475779,-0.044090,-0.444160,-0.037005,-0.092998,-0.386608,-0.088525,-0.749223,-0.089892,-