INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26909790', '疾速追杀3', '动作', '约翰·威克经历了前两次的追杀、特攻之后，由于执意破坏酒店规矩，因而遭到悬赏通缉，全球杀手闻风而至、一路追杀。这次他又将如何杀出重围，终结这场逃亡之旅。', '基努·里维斯', '查德·斯塔赫斯基', 7.9, 171906, 'tt6146586', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2551393832.jpg', 0.8, 3.3, 23.6, 44, 28.3, '-0.442852,0.251587,-0.524437,0.269503,0.526504,-0.314938,0.211355,-0.355798,-0.265796,-0.141607,0.560323,0.354803,0.034429,-0.112530,1.075531,-0.375066,-0.333668,-0.245555,0.054317,-0.282076,-0.398773,-0.004346,-0.117311,0.179317,0.305657,-0.195575,0.628875,0.607726,-0.564211,0.751656,0.307233,0.371982,-0.518053,0.474345,0.478730,0.089450,0.636505,0.221516,-0.398539,0.343816,-0.197024,-0.636416,-0.059674,-0.127434,-0.058244,0.530872,0.391162,-0.364820,0.050829,-0.796009,0.205517,-0.756091,-0.133792,0.093301,0.732837,0.247305,0.264795,0.451851,0.111625,-0.238078,-0.191543,0.024105,-0.779200,0.111690,0.230887,-0.484463,-0.489827,0.185648,-0.355723,0.751104,-0.530128,0.030630,-0.068106,0.879765,0.890263,-0.434055,0.077527,-0.009810,-0.430781,0.003911,1.435691,-0.481838,0.190109,-0.298946,0.503946,-0.173806,0.490566,-0.758611,-0.369058,0.456480,0.345089,0.176775,-0.325670,0.454822,-0.411128,-0.100476,-0.965861,-0.245400,0.036100,-0.040528,-0.139926,-1.038403,0.253915,0.134756,-0.190026,-0.358716,-0.197616,0.003370,-0.038789,-0.355182,0.413922,0.780201,0.367212,-0.682589,0.037183,0.278380,0.423155,0.297926,0.269024,0.150724,0.576859,0.848579,0.075749,-0.190015,0.208101,-0.354338,0.264137,0.350374', '30425219', '34861178', '1292846', '35287558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26910820', '灵魂摆渡·黄泉', '悬疑', '黄泉八百里沙海，寂寞荒凉，无花无叶。少女三七作为这黄泉中的最后一任孟婆，被冥王阿茶指婚给鬼差赵吏。三七性格憨傻，样貌枯槁，情窦未开，遭到了赵吏的拒绝。她日日独守在空旷的土堡内，熬着苦涩的孟婆汤，只与一株将死未死的曼珠沙华相伴。直到那一日，一个名叫长生的少年，误打误撞闯进了孟婆庄……', '于毅', '巨兴茂', 7, 127677, 'tt7959042', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2512204463.jpg', 2.6, 8.3, 37.8, 37.2, 14.1, '0.001150,0.384820,-0.736951,0.387299,-0.469192,-0.320825,0.817376,0.192903,-0.405318,0.054788,0.131092,0.552212,-0.007359,0.337493,0.178594,0.235841,0.457414,-0.223625,-0.486441,-0.400382,-0.196875,-0.113968,-0.396429,0.294073,-0.087350,-0.049793,0.588532,0.237618,0.288425,0.400048,0.022680,0.015294,-0.184063,0.373419,-0.680839,0.234270,-0.138148,-0.354260,0.317979,0.477375,-0.056325,-0.449766,-0.088906,-0.109958,-0.401036,0.563144,0.537104,-0.648224,-0.277720,-0.256383,0.213807,-0.092099,-0.355616,0.313682,0.324436,-0.277500,0.050280,0.220091,-0.600462,-0.038038,0.017725,-0.051582,-0.463653,0.175631,-0.131429,0.286001,-0.646190,0.615900,0.110648,-0.095890,0.112173,-0.170487,0.305917,0.052215,0.352111,0.388833,-0.302341,-0.188930,-0.556180,0.188800,0.490685,0.057271,-0.246385,0.497066,-0.005085,-0.357408,0.099791,-0.285986,-0.418790,0.108171,0.406388,0.069807,-0.055160,0.208595,-0.607621,0.084433,-0.244956,0.254688,-0.478746,0.105710,-0.810807,0.033655,-0.189627,-0.012578,-0.347001,-0.095820,0.004865,-0.013037,0.543563,-0.386740,0.634716,0.252819,0.294028,-0.041660,0.842566,0.295267,0.267849,0.106402,0.027068,0.678504,0.143318,0.645482,0.448166,0.412176,-0.209332,0.190129,-0.648074,0.178364', '21619567', '1302133', '26920017', '1293515');
