INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26911450', '山2', '剧情', '讲述一个秘密的特种部队的故事；呼叫信号“风暴使者”。在第一部电影（山 Dağ）的巴吉尔和奥古兹事件之后，不一定有把握的最好的朋友，已经报名参加世界闻名，永远艰苦的土耳其特种部队训练。他们的第一次任务是六年后开始的——渗透到现代伊拉克最野蛮的地区进行救援。', '欧赞·艾贾', '阿尔珀·卡格拉', 6.6, 13228, 'tt5813916', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2448817847.jpg', 2.7, 11.2, 47.4, 30.1, 8.6, '0.203018,-0.214037,-0.690820,0.984189,0.126707,0.120838,0.206002,-0.320218,-0.343273,-0.488440,0.178658,1.005204,0.177869,-0.031763,0.216564,-0.132356,-0.380559,-0.742648,-0.387512,-0.352961,-0.610938,-0.477786,-0.020607,-0.206509,0.273219,-0.466621,0.777240,0.179474,-0.502371,0.356358,0.248481,0.209987,0.044697,0.294614,-0.034163,-0.550622,0.626462,0.113135,-0.378804,0.241260,-0.058561,-0.169872,-0.097551,0.396382,0.150523,0.391218,0.565188,-0.470043,0.036801,0.008118,0.239669,-0.567741,-0.047072,-0.148874,0.550335,-0.190016,0.389050,0.447818,0.072027,-0.078535,-0.585188,-0.444487,-0.868241,-0.214529,0.187908,-0.019612,-0.523035,0.262501,-0.002385,0.369833,0.234233,-0.247437,0.219755,1.033586,0.242073,0.352370,-0.041249,-0.091156,-0.291887,0.543251,0.959601,-0.341945,-0.373357,0.229077,0.030786,-0.695133,-0.168851,-0.204395,-0.490321,0.403495,0.272407,-0.284933,-0.414500,0.312587,-0.835138,0.063506,0.012502,-0.627566,0.203221,-0.257251,-0.012845,-1.163343,-0.152089,-0.204646,-0.142056,0.175377,0.028626,0.120053,0.911273,-0.884068,0.273269,0.698537,-0.080509,-0.505190,0.547949,0.171151,0.077332,-0.602356,0.454686,0.246205,0.184920,0.478821,0.133979,0.536333,0.173856,-0.475362,-0.508501,0.493269', '2369613', '1420088', '11541282', '1307762');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26915029', '意外杀手', '动作', '麦克·福隆（斯科特·阿金斯饰），号称意外杀手的他，是位冷血杀手。就他从事的职业来讲，他是顶尖的，无论是条理多样的刺杀技巧，还是瞒天过海躲过警察视线，他的每次任务都使雇主满意高兴。但是有一天他挚爱的人却卷入了伦敦的地下杀手世界，并惨遭自己同组织的人杀害。而福隆不得不打破自己长久以来井然有序，条理安排的生活，开始向实施这一切的人展开复仇这部电影改编自90年代的一本漫画 作者是帕特·米尔斯，《特警判官》（95年电影版由史泰龙主演）也是他的作品', '斯科特·阿金斯', '杰西·约翰逊', 6.4, 7405, 'tt6237612', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2506841854.jpg', 2.1, 12.3, 55, 23.7, 6.9, '0.165053,-0.191298,-0.439776,0.569904,-0.298139,0.043800,0.508461,-0.073913,-0.677583,-0.158283,0.556833,0.688001,0.194033,-0.104651,0.416836,0.274599,-0.332846,-0.695347,-0.014085,-0.120833,-0.107389,-0.386052,-0.466857,-0.615967,0.021687,-0.404666,0.640910,0.211997,-0.284707,0.031552,0.358403,0.186974,0.049583,0.555543,0.028672,0.069225,0.120428,-0.369268,-0.168637,0.068892,-0.147447,-0.337625,-0.588734,0.249722,-0.064804,0.623492,0.501177,-0.078801,-0.220932,0.082696,0.420420,-0.663708,-0.328786,-0.172767,0.344751,-0.038597,0.059095,0.367290,0.335882,-0.079734,-0.160569,-0.152327,-1.125198,-0.003897,0.270245,0.080438,-0.472404,0.480224,-0.326364,0.362488,-0.237088,-0.346996,-0.101829,-0.271405,0.479801,0.214051,0.061980,-0.129882,-0.307626,0.502662,0.647300,0.036155,-0.478055,0.270748,-0.330152,-0.607880,-0.313803,-0.442666,-0.406360,0.195040,0.292974,0.066086,-0.199297,0.221988,-0.379302,0.107481,-0.172115,-0.301356,-0.164022,-0.448425,0.011703,-0.681284,-0.099867,-0.337046,-0.273267,-0.223127,-0.001992,-0.375086,0.896887,-0.676318,0.017187,0.702113,0.025409,-0.479743,0.857022,0.124838,-0.055322,-0.191066,-0.217187,0.150310,0.048166,0.197263,0.000656,0.329265,0.154182,-0.151632,-0.031890,0.530675', '27602116', '1793491', '25932086', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26915921', '屏住呼吸2', '惊悚', '《屏住呼吸1》编剧罗多·赛亚格斯执导，并同前作导演费德·阿尔瓦雷兹一起写剧本，史蒂芬·朗、罗奇·威廉姆斯、斯蒂芬妮·阿西拉、鲍比·斯科菲尔德、亚当·扬等主演。故事发生在最初致命的入室抢劫之后的几年，眼盲的退伍老兵诺曼过着平静的生活，直到过去的罪恶开始找上他。', '史蒂芬·朗', '罗多·赛亚格斯', 6.5, 25055, 'tt6246322', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2675211748.jpg', 1.4, 11.4, 55.3, 24.2, 7.7, '0.306835,-0.000459,-0.612627,0.359608,0.233827,-0.940455,0.840411,0.081407,-0.106849,-0.430334,-0.138815,0.303096,-0.464000,0.119122,0.595447,0.071546,-0.834727,-0.754123,-0.174327,-0.002155,-0.046205,-0.477490,-0.115579,-0.092673,-0.152946,-0.522693,0.116531,-0.361168,0.157682,0.235795,0.452931,0.171554,0.167395,-0.071894,0.289470,0.389287,0.182985,-0.407484,-0.543604,0.042372,0.383293,0.044409,-0.399511,-0.248141,0.373899,0.191485,0.304112,0.018289,0.216776,0.096232,0.105253,-0.092475,0.019363,-0.210448,0.231421,0.095911,-0.140697,0.268403,0.206311,-0.046908,-0.293431,0.001204,-0.234691,0.260186,-0.258562,0.656892,-0.366715,0.283722,-0.376115,0.159748,-0.188694,-0.425613,-0.198208,0.333620,0.329095,0.077487,0.220531,0.208386,-0.158292,0.234499,0.364964,-0.056387,-0.197952,0.089530,-0.269382,-0.432493,-0.058193,0.135712,-0.640591,0.239110,0.356438,-0.319383,0.003183,0.536062,-0.164336,-0.180367,-0.243107,-0.081700,-0.244311,-0.139368,-0.141674,-1.140577,-0.296593,-0.134336,-0.034059,-0.189083,-0.138905,-0.289284,0.133115,-0.203874,0.280979,0.535368,0.029247,0.516171,0.069577,-0.117144,0.010952,-0.105738,0.067814,0.478957,0.220424,0.227009,0.448026,0.564950,0.116424,0.160323,0.012579,0.558393', '6517421', '34961898', '2075345', '2364001');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26916229', '镰仓物语', '剧情', '祖辈相传的民俗作家一色正和（堺雅人 饰）与仰慕他的青年编辑亚纪子（高畑充希 饰）结为夫妇，新婚燕尔，夫妇俩亲昵无间，携手返回一色的出生地镰仓。回到镰仓不久，单纯的亚纪子就被眼前走过的河童小人吓了一跳。原来镰仓自古是妖气很重的一座城市，妖怪、幽灵毫无忌惮，随意现身；而当地人也见怪不怪，与异类和平相处，分外融洽。开朗的亚纪子很快就适应了这种新生活，她接纳着丈夫的怪癖，见证着幽灵和人类的牵绊，甚至还把一尊贫穷之神接纳家中。可是就是这么善良的亚纪子，却遭到一个妖怪的暗算。她失去了身体，以灵体的状态游离世间，等同于死亡，这可急坏了一色……©豆瓣', '堺雅人', '山崎贵', 6.9, 122935, 'tt6493648', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2532008868.jpg', 1, 8.6, 46.4, 33.3, 10.8, '0.616150,0.060252,-0.447526,0.656742,-0.043416,-0.177748,0.713073,0.078139,-0.473997,-0.356123,0.064719,0.769428,-0.277578,0.314931,0.453650,0.261004,-0.076722,-0.472374,-0.322462,0.029114,-0.181100,-0.353220,-0.312962,-0.047951,-0.343127,-0.315117,0.650781,0.241675,-0.041020,0.521293,0.103246,0.089377,-0.306548,0.362851,-0.146049,0.037226,-0.192705,0.104581,-0.056366,-0.011148,-0.455892,-0.047715,0.090206,0.437565,-0.185767,0.218551,0.631505,-0.647324,-0.098738,-0.322371,0.333999,-0.347843,-0.169802,0.307547,0.303992,-0.163779,0.136948,0.043243,-0.135979,-0.044507,0.027844,-0.074054,-0.347959,0.070469,0.160731,0.110351,-0.406896,0.441597,0.267645,-0.176478,0.054617,-0.245324,0.109325,0.226719,0.317942,0.526598,-0.075064,0.035888,-0.366807,0.075379,0.674731,0.051978,-0.489920,0.317718,-0.565930,-0.680257,-0.178806,-0.357361,-0.600200,-0.347217,0.002790,0.045168,-0.138349,0.381765,-0.714041,0.143916,-0.200746,0.242291,0.151723,-0.366421,-0.023029,-0.549549,-0.155428,-0.545584,-0.263604,0.269912,0.021683,-0.279282,0.776857,-0.691352,0.312431,0.449502,0.411537,-0.291859,0.676994,0.014265,-0.087997,-0.171077,-0.196583,0.549844,0.318863,0.260113,0.171765,0.264106,-0.286382,0.106858,-0.354752,0.318501', '3811356', '1309161', '5938000', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26917393', '错误教育', '剧情', '“超杀女”科洛·莫瑞兹携手萨莎·莱恩参演《卡梅伦的错误教育》(The Miseducation of Cameron Post，暂译)，戴思睿·阿卡万自编自导。影片根据艾米丽·丹弗斯的同名小说改编，讲述同性恋少女卡梅伦(莫瑞兹饰)的成长历程。青春本疼痛，而挫折历练却让卡梅伦不断成长。', '科洛·莫瑞兹', '戴思睿·阿卡万', 6.6, 7221, 'tt6257174', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2528152105.jpg', 1, 9.4, 54, 28.1, 7.5, '-0.453913,-0.074644,0.055467,0.753824,0.274012,-0.443613,0.503782,0.363701,-0.096465,-0.175201,0.280966,0.493192,-0.213423,0.062866,0.522882,-0.083693,-0.790395,-0.523251,0.114516,0.174660,0.295704,-0.464445,-0.102470,-0.431872,-0.027142,-0.895653,0.689007,-0.172417,-0.388031,0.256467,0.290519,0.308316,0.001835,-0.116037,0.162991,0.399324,0.417953,0.087178,0.007436,-0.156527,-0.118198,-0.306401,-0.101084,-0.198740,0.268010,0.228266,0.629307,-0.194367,0.237327,-0.347516,0.746377,0.212768,-0.273054,-0.273404,-0.197294,-0.061155,0.458785,-0.097359,0.343791,-0.006940,-0.394538,-0.348912,-0.743665,-0.236080,-0.083681,0.204674,-0.198767,-0.074071,-0.003674,0.168310,0.348498,0.043523,-0.689886,0.250874,0.669838,-0.093816,-0.337321,-0.059620,0.028957,0.622036,0.171411,0.005826,-0.373578,0.524593,-0.669071,-0.492919,-0.088270,0.100448,-0.726388,0.229768,0.195319,-0.142311,-0.128102,0.819077,-0.345662,-0.306735,-0.451409,-0.186121,-0.224139,-0.356405,0.004191,-1.025079,-0.516144,0.152782,-0.094171,-0.667323,0.002721,-0.642694,1.011220,-0.084603,0.216946,0.684181,-0.245090,-0.528076,0.206033,0.166924,0.063394,-0.299738,0.028971,1.215780,-0.223119,0.216420,-0.131124,0.263752,0.119272,0.128988,-0.509782,0.677771', '26726261', '2364001', '1907465', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26918603', '原以为命中注定的恋爱不会发生在我身上', '剧情', '白野莉子（多部未华子 饰）是一名恋爱养成游戏设计师，专职撰写恋爱养成游戏的剧本，因此脑海里塞满了对恋情的天马行空不切实际的幻想，并且对现实里的不成器的男人们以及同他们的恋爱充满了失望。黑川壮一郎（高桥一生 饰）是APP公司的社长，他找到了莉子，委托她制作一款手机恋爱游戏。壮一郎虽然样貌一表人才，却丝毫不懂得女性心里的弯弯绕，过于耿直的他和莉子之间自然产生了不少的矛盾，甚至爆发了激烈的争吵。实际上，壮一郎一直暗恋着下属桃濑（大政绚 饰），苦于不懂得如何表达感情的他委托莉子做自己的“恋爱指导”。在莉子的帮助下，壮一郎和桃濑之间的距离越来越近，与此同时，内心里深深的失落让莉子意识到，自己似乎已经爱上了壮一郎。©豆瓣', '多部未华子', '波多野贵文', 7.4, 10611, 'tt6264864', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2409843340.jpg', 0.6, 4.6, 36, 40.5, 18.3, '0.426998,0.166797,-0.604606,0.642765,-0.111629,-0.153856,0.675780,-0.179825,-0.406821,-0.596179,0.020747,0.614490,-0.254983,0.220971,0.142388,-0.039498,-0.284719,-0.774876,-0.180297,0.082630,-0.011043,-0.594779,-0.171788,-0.025481,-0.404031,-0.026033,0.911322,0.113578,-0.382862,0.373331,0.257888,0.387770,0.037685,0.394693,0.106468,0.118998,0.298774,0.110053,-0.045374,-0.325507,0.072330,-0.083428,-0.036105,0.378381,0.051515,0.555288,0.610488,-0.056233,-0.402157,0.142559,0.446105,-0.013786,-0.289139,0.017759,0.112553,0.426145,0.131094,0.158323,-0.141455,0.052822,-0.161710,0.047709,-0.773972,-0.130062,0.134030,0.114521,-0.266593,0.311411,-0.046664,-0.289402,0.110994,-0.089696,0.019352,0.090050,0.457071,0.201259,-0.406668,0.269165,-0.325243,0.208943,0.709352,0.131155,-0.213047,0.501905,-0.583153,-0.481308,-0.487007,-0.131497,-0.623158,-0.256164,-0.163754,0.201141,-0.231729,0.425227,-0.438509,-0.031999,0.034447,-0.056377,0.304736,-0.617799,0.053145,-0.470631,-0.464464,-0.758817,-0.567747,-0.132079,0.189377,-0.303729,0.775401,-1.085874,-0.088766,0.333557,0.087680,-0.468535,0.579236,0.377392,-0.257082,-0.382990,-0.138040,0.273277,-0.143484,-0.223543,0.056265,0.358636,0.114279,-0.231110,-0.623248,0.664303', '35030151', '25880986', '1395231', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26920017', '鬼魅浮生', '剧情', 'M（鲁妮·玛拉 Rooney Mara 饰）和C（卡西·阿弗莱克 Casey Affleck 饰）是一对十分恩爱的恋人，在一场车祸中，C不幸死去，将心碎欲绝的M孤零零的留在这个世界之中。然而，C却并没有真正的离开，他依然以灵魂的形式留在他和M一起生活过的那幢房子里，留在M的身边，沉默而又深情的看着他生前的恋人的一举一动。C的离开让M陷入了绝望和痛苦之中，她哭泣、抑郁、自闭，仿佛生活在真空里。M决定从房子里搬出去，可是C无法离开，他只能继续的等待着等待着，支持着C的，是M曾经留在墙缝里的一张字条。新的住客来了又走，无限的时间永恒的流逝着，某日，拆迁队将C所在的屋子拆除了，一片废墟之中，C发现，原来被困在无尽的等待中的，并非只有他一个。©豆瓣', '卡西·阿弗莱克', '大卫·洛维', 7.6, 43182, 'tt6265828', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2497252402.jpg', 1.7, 5.3, 27.4, 42.5, 23.1, '0.226214,0.222496,-0.941526,0.813808,-0.215186,-0.279227,1.603082,0.129226,-0.560289,-0.264685,0.188005,0.808647,0.056181,0.685694,0.088687,0.034895,-0.348829,-0.799569,-0.588842,-0.339009,-0.374560,-0.619032,-0.311436,0.060187,-0.114140,-0.114887,0.916036,0.388742,0.098846,0.515733,0.158766,0.142386,-0.384152,0.784429,-0.346697,-0.029398,-0.145433,0.027428,-0.209244,0.363990,0.277834,-0.335469,-0.156212,0.307744,-0.001460,0.108722,0.891653,-0.761125,-0.072098,0.316966,0.180377,-0.416217,-0.299035,0.401026,0.063260,-0.041123,0.452807,0.149323,-0.759351,0.315950,0.165520,-0.053943,-0.848599,-0.027618,-0.072930,0.452543,-0.937311,0.822984,0.243341,-0.346422,0.272882,-0.390407,0.722072,0.245242,0.239738,0.794573,-0.522956,-0.023543,-0.580415,-0.029029,0.679207,-0.207065,-0.094224,0.410392,-0.010053,-0.266746,-0.105697,-0.025739,-0.842748,-0.340487,0.116410,0.328064,-0.217049,0.064357,-0.864693,0.234131,-0.226307,-0.509622,-0.232794,-0.689789,-0.299078,-0.475798,-0.195352,-0.413308,-0.292136,0.342269,-0.188766,-0.371592,0.490626,-0.926389,0.396742,0.336549,0.461601,-0.260376,0.811139,0.118566,0.346413,0.047868,-0.096377,0.622732,0.064067,0.624021,0.235130,0.312347,-0.189665,0.283684,-0.875978,0.850139', '21619567', '1467779', '25917973', '1302133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26920842', '副总统', '剧情', '曾拍《大空头》（The Big Short）聚焦美国次贷危机的导演亚当·迈凯（Adam McKay）日前与派拉蒙签约，将导演一部讲述美国前副总统迪克·切尼（Dick Cheney）故事的传记片。而布拉德·皮特的“B计划”制片公司也将继《点球成金》、《大空头》后再次与迈凯合作，制作这部电影。迪克·切尼号称是美国历史上最有权势的副总统，他也是现任美国副总统彭斯（Mike Pence）的效仿对象。布什当政八年时间里，表面上切尼是美国的二号人物，但实际上小布什总统（George W. Bush）的很多决定，包括阿富汗战争、入侵伊拉克等都是由他定夺的。切尼本人是一个充满争议的矛盾体。他一直都是保守党派，曾为尼克松、福特、老布什政府做过幕僚，后进入哈利伯顿公司当了几年CEO，然后和小布什一起入主白宫；但他对于同性恋婚姻却持支持态度，因为他的女儿是一名女同性恋。此外，切尼五次拖延不愿去越战战场，却是个不折不扣的主战鹰派。亚当·迈凯说：“我一直觉得切尼是个有意思的人物，很想搞清楚究竟是什么在驱动他、他到底信仰什么。所以我们就做了深挖调查，结果令人震惊，切尼堪称是美国现代史上最有权力的政治人物，他在很大程度上塑造了美国现在的国际地位，而他为了攫取权力所采取的方式也令人瞠目结舌。”亚当·迈凯希望能在2017年春拍摄本片，并在年底上映。目前他正在物色合适的演员人选。亚当·迈凯拍摄《切尼传》，意味着他之前接手的《坏血》（Bad Blood）项目要往后推迟了。', '克里斯蒂安·贝尔', '亚当·麦凯', 6.9, 18145, 'tt6266538', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2535858294.jpg', 1, 6.8, 46.1, 36.5, 9.6, '0.092114,0.039206,-0.615474,0.651770,-0.146323,-0.158557,0.360756,0.072296,-0.645204,-0.333398,0.189982,0.952150,-0.097437,0.028641,0.079337,0.221289,-0.361551,-0.637781,-0.091985,-0.143716,0.010729,-0.713358,-0.402192,-0.279159,-0.059602,-0.106346,0.755681,-0.044485,-0.292838,-0.002713,0.628034,0.178315,0.368468,0.390960,0.083110,-0.229337,0.077731,-0.210800,-0.460001,0.236718,0.235687,-0.306324,-0.180407,0.212086,0.324719,0.443507,0.045567,-0.140153,-0.024962,-0.150918,0.364335,-0.390324,-0.087356,0.042281,0.378498,0.060193,0.194457,0.503095,-0.164409,-0.195032,-0.131755,-0.009543,-0.771646,0.125389,-0.188286,0.317469,-0.580192,0.442814,-0.262341,0.013822,0.002103,-0.324573,0.197588,0.537881,0.227523,0.054308,0.033068,0.050193,-0.417360,0.258977,0.638797,0.088928,-0.314407,0.359906,-0.110660,-0.391439,-0.104951,-0.441767,-0.259040,0.046084,0.037521,-0.198620,0.033285,0.279959,-0.254367,0.021771,-0.360431,-0.446716,0.014010,-0.400954,0.277879,-0.632051,-0.268017,-0.392359,-0.250731,-0.280543,0.246658,-0.373341,0.724860,-0.647216,-0.068601,0.495911,0.323919,-0.558128,0.786525,0.362198,0.061335,-0.316249,-0.044706,0.072802,-0.059849,0.060725,-0.138454,0.188377,0.395367,-0.555055,-0.084212,0.537260', '4301278', '35262731', '1870681', '24875409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26921076', '舞出我人生之舞所不能', '剧情', '本片讲述了一起在煤渣胡同长大的铁猴（黄景行 饰）和铁蛇（敖犬 饰）兄弟情深，大哥铁蛇为人仗义有担当，是这帮胡同串子的依靠。铁猴爱街舞胜过爱生命，在小飞（孟美岐 饰）家寄养长大。害羞默默守护一起长大的妹妹小飞多年。富二代何川（余建波 饰）因父亲阻挠失去自己的舞团和战友，不得不回到父亲的公司上班继承家业，但是内心却无法放弃对街舞的热爱。一次偶然的机会，何川与铁猴相遇，他们一个是自我感觉良好，追求更高艺术表达，决不妥协的街舞富二代。一个是出身底层，玩世不恭，不喜表达感情，在舞蹈中充满感性和爆发力，本性无拘无束的天才少年。出生迥异的两个人，就这样介入了各自的生活，两个人因舞蹈结缘，一起面对最黑暗的对手..', '孟美岐', '袁文忠', 4.6, 2781, 'tt4060544', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2562665382.jpg', 30.6, 27.9, 27.9, 9, 4.5, '0.278112,-0.262487,-0.442219,0.710592,-0.371221,-0.272409,0.625488,0.159743,-0.550770,-0.219453,0.096681,0.771996,0.278777,0.400023,-0.138309,-0.310721,-0.061543,-0.535796,0.134269,0.114024,0.080637,-0.401003,0.125514,-0.083688,-0.290896,-0.229591,0.810284,-0.046011,-0.198627,0.745292,0.383932,0.164898,-0.159781,-0.014714,-0.354162,-0.061579,-0.069154,0.390023,-0.562133,-0.010638,-0.172805,0.076632,-0.040112,0.038528,0.100163,-0.094501,0.673556,-0.067796,-0.149722,-0.279858,0.286920,-0.200806,-0.232967,0.073552,0.203387,0.001143,0.348368,0.232357,0.072985,0.063860,-0.200360,-0.003073,-0.782980,-0.100455,0.322780,-0.119755,-0.792060,0.569480,0.271962,-0.441677,0.137367,-0.291788,0.086020,-0.012464,0.331642,0.504928,-0.220649,0.253773,-0.283711,0.025826,0.904200,-0.121224,-0.081117,0.205827,-0.345274,-0.339930,0.189818,-0.435925,-0.601007,-0.187322,-0.119872,0.020039,-0.200182,0.160579,-0.461863,0.184143,0.169009,0.188574,0.375143,-0.774262,0.105461,-0.400613,-0.369514,-0.789939,-0.282929,0.277535,0.029856,-0.427520,0.880655,-1.076101,0.175850,0.259355,0.380572,-0.716449,0.867244,0.372249,-0.005274,-0.422619,0.090767,0.390247,-0.032959,-0.370436,-0.215950,0.097738,-0.098779,0.240068,-0.402992,0.415990', '35030151', '3445516', '6963575', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26921827', '大卫贝肯之倒霉特工熊', '喜剧', '人类对大自然的过渡开采导致地球的生态被完全的破坏了，北极熊因此而灭绝，彼时，整个地球上只剩下最后一只北极熊了，它被善良的人类女孩杰西卡（徐佳琪 配音）收养，取名为贝肯（汤水雨 配音）。杰西卡是一名在安全部工作的优秀特工，同时也是贝肯的偶像，贝肯希望自己有朝一日也能够变成和杰西卡一样厉害的特工，但生来笨手笨脚的他常常惹出一堆的麻烦，最终，他只能去安全部的清洁部门报道。一天，一个神秘的北极熊组织出现在了人类的视野之中，他们声称要报复人类，在世界各地设置了危险的炸弹。安全部派出的特工们全部都被北极熊基地的人类探测仪发现了，为了根除这个恐怖组织，安全部最终决定启用贝肯这名秘密成员。©豆瓣', '汤水雨', '李清舫', 4.5, 5203, 'tt6437820', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2408893200.jpg', 30.1, 26, 34.3, 7.3, 2.4, '0.309620,0.255244,-0.720015,0.474059,-0.362210,-0.034298,0.566193,-0.045708,-0.465555,-0.129517,0.279768,0.901385,0.104810,0.075734,-0.043752,-0.060600,-0.151188,-0.495970,-0.244771,-0.169367,-0.429765,-0.347267,-0.498372,-0.373767,0.038328,-0.292646,0.800443,0.040348,-0.268757,0.059784,0.160746,0.292190,0.084154,0.305778,-0.214707,-0.083867,0.237795,-0.271626,0.130782,0.242645,-0.292999,-0.029384,0.113596,0.361377,-0.210120,0.325738,0.684992,-0.250716,-0.199929,-0.460708,0.435876,-0.594177,-0.009750,0.039339,0.667219,-0.044271,-0.003448,-0.067655,-0.113902,0.011183,0.155582,0.078559,-1.081651,-0.228717,0.025398,0.277963,-0.457479,0.388020,0.063250,0.042542,-0.026259,-0.316384,0.280551,0.332388,0.270507,0.311749,-0.112321,0.239406,-0.502286,0.177158,0.622448,-0.229929,-0.477885,0.211947,-0.324570,-0.557691,-0.204271,-0.498882,-0.320224,-0.109850,0.468192,-0.098512,-0.313615,0.167336,-0.927393,-0.024636,-0.301416,-0.453006,-0.254785,-0.337537,-0.045293,-0.572641,-0.004988,-0.231841,-0.306400,0.186175,0.028268,-0.104764,1.037052,-0.792741,0.182379,0.946628,0.165815,-0.723049,0.543990,0.082656,0.183557,-0.129317,0.018268,0.199871,0.350952,0.518051,0.144186,0.402246,0.012008,-0.363903,-0.363634,0.174150', '24284209', '27602116', '25928048', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26923111', '必是天堂', '喜剧', '苏雷曼从巴勒斯坦逃离，渴望前往新的家园生活，却意识到自己的故土如影随形。对新生活的期待很快沦为一个荒谬的笑话：从巴黎到纽约，不管他走到哪里，总有些地方让他想起祖国。在这一部关于探索身份、国籍和归属感的喜剧故事里，苏雷曼提出了一个本质性的问题：我们能够真正称之为家的地方到底在哪儿？', '伊利亚·苏雷曼', '伊利亚·苏雷曼', 7.6, 9408, 'tt8359842', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2575505515.jpg', 0.7, 3.6, 27.4, 51.4, 16.9, '0.235675,0.320986,-0.849165,0.731623,-0.078072,-0.224175,0.719947,-0.150390,-0.370672,-0.358244,-0.137909,1.011013,0.121285,0.687800,0.573084,0.182451,-0.102660,-0.394093,0.320957,-0.678537,-0.766216,-0.484944,-0.493414,-0.413638,-0.041396,0.068570,0.433227,0.483459,-0.568901,0.077105,0.267253,0.184042,-0.313866,0.760888,-0.405297,-0.106697,0.203307,0.570802,-0.316921,0.286212,0.279740,-0.192989,-0.477257,0.269174,-0.032390,0.178581,0.566156,-0.262396,-0.169254,0.294116,0.245748,-0.022737,-0.150026,-0.107838,0.108478,-0.227138,-0.338209,0.074305,-0.110340,0.072421,-0.037146,-0.219995,-0.892824,-0.033299,-0.073385,0.315474,-0.571685,0.015392,0.114712,-0.132331,0.213164,-0.482091,0.269366,0.441605,0.392664,0.723400,-0.328021,0.315526,-0.471394,-0.046573,1.029045,-0.141902,-0.470396,0.314324,-0.083008,-0.294242,-0.057922,0.056240,-0.418032,-0.331273,0.009765,0.122755,-0.304160,0.057566,-0.660072,0.092665,0.145602,-0.259570,0.164907,-0.605515,0.196118,-0.273963,-0.358580,-0.358753,0.132028,0.068572,0.167604,-0.336658,0.762849,-0.642878,0.133794,0.510210,0.195337,-0.972399,0.467822,0.216760,-0.038048,-0.484673,-0.014524,0.592684,0.197232,0.533098,-0.150150,0.125355,-0.028526,-0.017387,-0.390621,0.824381', '26678784', '30163500', '1292064', '1304977');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26923506', '我的青春都是你', '剧情', '改编自小说《北大差生》，讲述了学渣周林林和“隔壁家的学霸”方予可之间的酸甜爱情故事。本以为高考结束就可以分道扬镳，没想到阴差阳错，两人一同考进了全国最高学府的最冷门专业——畜牧系。为了弥补曾经无意间给方予可造成的“初恋创伤”，周林林千方百计帮方予可追回“校花初恋”，自己却在不知不觉中掉进了青春的陷阱…毕业季即将来临，深藏你青春回忆深处的那个 TA 是否还在你的身边？', '宋芸桦', '周彤', 3.7, 10489, 'tt10452036', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2553778873.jpg', 40.7, 39, 16.6, 2.3, 1.4, '0.318049,0.095880,-0.609962,0.721276,-0.146647,-0.560410,0.287048,-0.132537,-0.342977,-0.421798,-0.300548,0.466653,-0.303673,0.412579,0.167523,-0.175328,-0.137020,-0.573997,-0.020686,-0.472256,-0.387783,-0.385368,-0.182818,0.320247,-0.030649,-0.105569,0.769648,0.175055,-0.487943,0.402242,0.286496,-0.044777,-0.073046,0.316107,-0.359240,0.060773,0.153430,0.463321,-0.256216,0.176340,0.372037,-0.472541,-0.034478,-0.127472,0.126072,-0.077111,0.583207,0.123646,0.056854,0.067171,0.520054,-0.383744,-0.243693,0.046386,0.343602,-0.020256,0.344225,-0.011771,0.077944,0.045371,0.062202,-0.462217,-0.382162,-0.198878,0.023156,-0.167000,-0.338969,0.465415,0.355054,0.164449,0.425669,-0.033935,0.055447,0.217367,0.413586,0.376458,-0.473340,-0.040444,-0.403479,0.547204,0.576380,-0.319305,-0.119980,0.397922,0.042125,-0.524746,0.216868,-0.147105,-0.435479,0.416507,0.097240,0.092511,-0.275229,0.326582,-0.540735,-0.056390,-0.037964,0.056945,0.013581,-0.606809,-0.019473,-0.409628,-0.268562,-0.144038,-0.165355,0.203982,0.204691,-0.505453,0.806196,-0.856740,0.262228,0.540540,0.149274,-0.445627,0.551056,0.416449,0.166843,-0.096195,-0.043881,0.249536,-0.020757,0.468881,0.020267,0.422053,-0.080608,-0.264943,-0.496902,0.496420', '25922902', '1826173', '1308499', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26924141', '低压槽：欲望之城', '剧情', '孤城，一座浮华却堕落的罪恶之城，这里充斥着金钱与利益的争夺。然而，在这个亡命之徒的乐园里，仍有少数人坚持着自己心中的正义……警方卧底于秋在上司阿占的运筹帷幄下，多次成功打入当地帮派，斡旋于多方黑色势力之中。于秋在黑帮生活中却好像渐渐迷失自我，他开始怀疑，是否只有“非常”的手段才能主持公正，这让阿占也开始质疑。一次卧底行动中，于秋冒着行动失败的风险和帮派老大激战，结果全体命丧当场。在道德和江湖道义的双重质疑下，于秋选择了自我放逐，他逃离了孤城。然而，于秋内心对惩治罪恶的欲望从未消减，他重整旗鼓回到孤城，而这一次，阿占给他的任务竟然是调查罪恶之城背后最邪恶也最神秘的黑手、人人闻之色变的首脑——“老板”。从一宗离奇的小童绑架案开始，于秋和阿占查出老板的身份和他背后的犯罪网络。神秘的老板控制了商界和黑道，只有毁灭老板才能拯救这座堕落之城。事实上，于秋在追查过程中已经踏入了老板设下的重重圈套。虽然阿占拼死守着法律的底线，老板的势力却渗透了警方权力的高层，于秋渐渐失去了支持，原本要保护的小童也受到生命威胁。在接踵而至的迷局里，坚持正义的于秋好像被推向更深的绝望里……', '张家辉', '张家辉', 4.4, 16422, 'tt6871634', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2520457270.jpg', 27.5, 39.7, 23.6, 6, 3.2, '0.216958,0.494886,-0.794821,0.605098,-0.134499,-0.251902,0.617599,0.133365,-0.505121,-0.129838,0.497290,0.536089,0.029909,0.056850,0.232234,-0.188672,-0.200803,-0.757020,-0.169718,-0.252105,-0.112055,-0.418753,-0.361315,-0.248512,-0.233959,-0.079848,0.736174,0.617485,-0.470143,0.118209,0.220512,0.340129,-0.212629,0.716590,-0.086868,-0.134918,0.137180,-0.176651,-0.406715,0.152818,0.065178,-0.438362,-0.190729,0.475636,-0.153462,0.529295,0.503346,-0.538849,-0.280094,-0.198979,0.241264,-0.619922,-0.286980,0.190101,0.403596,0.033691,0.127988,0.457744,-0.181717,-0.002438,0.011773,0.057208,-1.050495,-0.356076,0.331832,0.292108,-0.500504,0.354290,-0.012886,0.026522,-0.176852,-0.165290,0.203784,0.285104,0.223989,0.241901,-0.275601,0.042318,-0.528716,-0.086791,0.786289,-0.199839,-0.156633,-0.111115,-0.106378,-0.492384,-0.075463,-0.336258,-0.373701,-0.298272,0.233651,-0.037549,-0.151906,0.430459,-0.713296,0.151511,-0.152121,-0.076403,-0.193190,-0.524697,-0.023179,-0.380285,-0.421464,-0.162318,-0.149116,0.171866,0.171644,-0.137737,0.599802,-1.010682,0.180876,0.647895,0.484193,-0.493978,0.390719,0.214363,0.060229,-0.276601,-0.360367,0.216955,-0.017987,0.642782,-0.009319,0.129779,0.052027,-0.226985,-0.289237,0.385090', '1793491', '25917239', '3213270', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26924143', '阳光姐妹淘', '喜剧', '当年陪你走过青春的好朋友，后来还有联系吗？大家又各自过得好吗？家庭主妇张丽君在医院重逢了病重的高中好姐妹林青，林青希望离世前能跟当年的姐妹们重聚。于是，张丽君开启了寻找姐妹的旅程，这一路，大家找回了青春，也重新审视了当下生活。时间好快，人已长大，好想和你再相聚。', '殷桃', '包贝尔', 4.4, 44372, 'tt14849368', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2646380991.jpg', 26, 36.3, 31.2, 5.3, 1.1, '-0.115578,-0.712829,-0.271681,0.320437,0.022060,-1.001552,0.427210,0.052634,-0.697160,0.077713,-0.258946,0.422235,-0.034657,0.669818,0.412319,0.074871,-0.790662,-0.778235,0.404825,-0.121672,-0.230123,0.084574,-0.006551,-0.111181,-0.093630,-0.138682,0.315370,0.010774,0.738659,0.618903,-0.148679,-0.592898,-0.074159,0.473050,-0.459118,0.400709,-0.310111,0.714058,-0.831211,0.095790,0.295791,0.224632,-0.108696,-0.266710,0.613410,0.158922,0.441453,0.569885,-0.203210,-0.088469,-0.068629,0.138373,0.032889,0.011873,-0.049253,0.124468,0.577087,0.100142,-0.193134,-0.067682,-0.721332,-0.103049,-0.366663,0.353877,0.130142,-0.607992,-0.605491,0.627521,0.237670,-0.215552,0.115102,-0.347323,0.360055,0.976557,0.287957,0.032943,-0.223080,-0.072447,-0.045979,0.560598,0.946743,-0.184097,-0.130954,0.503224,0.229642,-0.399130,-0.022450,0.075422,-0.257719,0.125610,0.173250,0.331814,-0.362587,0.272861,-0.631949,-0.096015,0.086396,-0.129562,0.512783,-0.762903,0.321194,-0.310637,-0.152504,-0.334410,-0.547716,0.056242,-0.113344,-0.199044,0.955835,-0.755641,0.354152,0.283881,0.534963,-0.787005,0.656688,0.436449,0.376621,-0.200357,0.143790,0.330799,-0.415282,0.798750,0.380043,0.213069,-0.113312,0.184437,-0.789196,0.240023', '30362186', '1292289', '3447595', '27041519');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26925317', '动物世界', '剧情', '在游戏机厅做着兼职“小丑”的郑开司（李易峰 饰），幼时父亲突然失踪，母亲重病住院，使得郑开司的生活非常拮据。发小“大虾米”（曹炳琨 饰）借口买房骗下了郑开司父亲留下的房产，还给他带来了巨额的欠债。神秘人物（迈克尔·道格拉斯 Michael Douglas 饰）出现，告诉郑开司，只要参加“命运号”游轮上的神秘游戏，就有机会偿还完所有欠款，一无所有的郑开司为了给青梅竹马的护士刘青（周冬雨 饰）和母亲更好的生活，只得登上游轮，开始了生存游戏，一场以“剪刀、石头、布”展开的生死较量即将登场……©豆瓣', '李易峰', '韩延', 7.2, 529248, 'tt7946836', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2525528688.jpg', 1.5, 5.7, 37.2, 44, 11.5, '-0.211734,0.024850,-0.414169,0.446328,-0.304176,-0.373180,0.457347,0.325691,-0.265385,-0.328369,0.292021,0.658487,-0.001495,0.305125,0.314221,-0.226005,-0.312338,-0.589850,-0.150405,0.098338,-0.467453,-0.520505,-0.020048,-0.149715,-0.012526,-0.033784,0.382675,-0.069664,-0.099794,0.184191,0.440375,0.298236,-0.212886,0.102364,-0.306443,-0.126185,-0.200890,0.354686,-0.658187,0.044250,-0.086453,-0.096659,0.124224,0.014110,0.226017,0.145614,0.633487,-0.088659,-0.119455,-0.112653,0.419859,-0.031890,-0.037715,-0.145044,0.091412,0.344184,0.197805,-0.017476,-0.296340,-0.039106,0.322961,-0.373084,-0.560648,-0.016308,-0.040682,-0.037183,-0.552550,0.300591,-0.127736,0.143909,0.051002,-0.290178,0.235814,0.464986,0.405227,0.287588,-0.222995,0.153575,-0.465783,0.543812,0.453898,0.000321,0.114738,0.345897,0.025558,-0.222191,0.153096,-0.307903,-0.436415,0.158281,0.429901,-0.143430,-0.158351,0.222157,-0.640843,-0.127710,-0.136319,-0.415128,0.450576,-0.292783,-0.021769,-0.683433,-0.163253,-0.007467,-0.350402,0.199163,0.162970,-0.430748,0.524312,-0.598352,0.411516,0.391544,0.183110,-0.432414,0.383972,-0.101373,0.402750,-0.205216,0.129732,0.060451,0.012193,0.320292,0.118869,-0.227803,-0.119888,-0.006399,-0.258523,0.545754', '6858739', '4301278', '11541282', '4904026');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26926304', '摇曳的心', '剧情', '经营西点咖啡店的青年亮介（松坂桃李 饰）即将和心爱的女孩千绘（清野菜名 饰）结为夫妇，可就在风光得意之时，千绘突然失踪，父亲洋介则罹患胰脏癌，去日无多。在帮助整理杂物时，亮介偶然翻出几本旧的笔记本，封面题写着“百合心（摇曳的心）”。笔记本中用铅笔写满了一名女子的独白，她 自称从小对外界感到恐惧，一次意外的杀人却让她无依无靠的心得到慰藉。笔记中极其真实的描写令亮介甚为恐惧，却又欲罢不能。与此同时，自称千绘朋友的细谷女士（木村多江 饰）找上门来，向他透露千绘失踪的原委。在阅读笔记的过程中，亮介似乎紧紧被这个名叫光子（吉高由里子 饰）的女子攫住，而其中更隐藏的莫大的秘密……本片根据沼田真帆香留的同名小说改编。©豆瓣', '吉高由里子', '熊泽尚人', 7.2, 8647, 'tt6289898', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2457076551.jpg', 1.2, 6, 37, 41.4, 14.4, '0.197596,-0.023233,-0.515784,0.673145,-0.006919,-0.155752,0.774134,0.249348,-0.381000,-0.379708,0.102484,0.607598,-0.192546,0.339765,0.186491,0.178776,-0.134970,-0.726572,-0.051813,-0.265493,-0.248548,-0.249210,-0.247102,-0.038833,-0.175059,-0.176869,0.657435,0.117893,-0.325833,0.383391,0.156453,0.365088,-0.300517,0.198875,-0.195767,0.074034,-0.053750,0.039880,0.023801,0.020067,-0.016842,-0.408505,-0.281181,0.321595,-0.175359,0.460814,0.869489,-0.281030,-0.304274,-0.058666,0.424728,0.086289,-0.070595,0.076217,0.144386,0.379122,0.141384,-0.032005,-0.421774,0.081933,0.224459,-0.007498,-0.622940,-0.124013,0.277815,0.434830,-0.408757,0.409078,-0.356633,-0.052905,0.282707,-0.301885,0.112672,-0.112795,0.191378,0.383680,-0.168423,0.083033,-0.184210,0.275151,-0.077531,0.080313,0.044786,0.567378,-0.204495,-0.305498,-0.022425,0.110301,-0.454185,0.048853,0.271567,0.110149,0.045082,0.311219,-0.566688,-0.115804,-0.068508,0.028499,0.137690,-0.299993,-0.376791,-0.468088,-0.246778,-0.156364,-0.266413,0.061056,0.352940,-0.298847,0.844773,-0.615555,0.149445,0.352338,-0.201109,-0.114172,0.190086,0.075934,-0.119289,-0.016019,-0.275458,0.316512,0.305860,0.203322,-0.050757,0.338700,-0.071815,-0.090851,-0.511537,0.352574', '3811356', '1307146', '10467125', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26926321', '缝纫机乐队', '喜剧', '坐落于东北的集安市曾因破吉他乐队成为全国著名的摇滚都市，也激发无数年轻人和儿童们的音乐热情。只是二十年过去，摇滚逐渐没落，连集安著名的标志大吉他都面临拆除的命运。为了守护这里的摇滚灵魂，修车行小老板胡亮（乔杉 饰）从北京请来前破吉他乐队的经纪人程宫（董成鹏 饰），希望对方帮他组建乐队，策划一场守卫大吉他的演出。在胡亮的软磨硬泡下，程宫他们东拼西凑找来了美丽的女贝斯手丁建国（古力娜扎 饰）、背对观众的鼓手炸药（李鸿其 饰）、年事已高的医生吉他手老杨（韩童生 饰）和未成年的小学生键盘手希希（曲隽希 饰）。他们克服各自的困难，携手朝着音乐梦想前进，心中永远保持着最初的激情……©豆瓣', '大鹏', '大鹏', 6.6, 342814, 'tt7339584', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2498558511.jpg', 4.1, 13.8, 43.3, 27.3, 11.5, '-0.064772,-0.073491,-0.461042,0.402883,-0.070384,0.056852,0.566388,0.183746,-0.172038,-0.257480,0.270304,0.568997,-0.017234,0.300448,0.281996,-0.219034,-0.261340,-0.747089,0.063982,0.279045,-0.049994,-0.069116,-0.029648,-0.164892,-0.165068,-0.002639,0.585086,0.138563,-0.046254,0.584713,0.362573,0.045558,-0.121587,-0.081285,-0.141361,0.002942,0.117320,-0.212935,-0.280949,-0.021972,-0.141193,-0.270686,-0.118524,-0.078448,0.003354,0.181896,0.644229,-0.124608,0.412104,0.086687,0.254939,-0.174939,0.020144,-0.032653,0.088873,0.339684,0.187245,0.060094,-0.076843,-0.016654,-0.085172,-0.171790,-0.623236,0.191031,0.286321,0.120907,-0.584651,0.522315,0.100242,0.115872,0.149340,-0.148889,0.217457,0.159329,0.239319,0.258633,-0.177462,0.212971,-0.383088,0.383799,0.581189,0.041968,-0.180123,0.089625,-0.236184,-0.337302,-0.326861,-0.051680,-0.674217,-0.151129,0.189504,-0.133703,0.252512,-0.243319,-0.664578,-0.188029,0.148638,-0.133852,0.227986,-0.171496,-0.032140,-0.778420,0.110591,-0.342838,0.034153,-0.044934,0.101937,-0.133023,0.964206,-0.649789,0.001412,0.398522,0.070044,-0.270665,0.556693,0.022451,0.057932,-0.166592,-0.188439,0.259411,-0.119797,0.407099,0.041064,0.445998,-0.142493,-0.125400,-0.360954,0.440949', '3811356', '25922902', '5403927', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26926703', '超感猎杀：圣诞特别篇', '剧情', 'Netflix近日公布了让冬歇期苦等剧集的观众们感到惊喜的消息——由沃卓斯基姐妹执导的科幻剧集《超感猎杀》将在12月23日推出长达两小时的圣诞特别篇。第一部的人马大部分会回归，阿梅尔·艾米恩的角色将由托比·奥伍梅尔替代。', '裴斗娜', '拉娜·沃卓斯基', 8.7, 33613, 'tt5031232', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2407641505.jpg', 0.5, 1.5, 12, 34.6, 51.4, '-0.112818,-0.435311,-0.338094,0.248151,0.469718,-0.049442,0.201655,0.073790,-0.601660,-0.049137,0.031785,0.600748,-0.912628,0.049032,0.668109,-0.105146,-0.371199,-0.579854,-0.478003,-0.603375,-0.080400,-0.324942,-0.108335,-0.341195,0.075629,-0.696543,0.737028,0.011761,0.254953,0.437117,0.316211,-0.079429,0.024467,0.168888,0.301078,0.311855,-0.010010,-0.346688,-0.269044,0.654591,-0.056653,-0.246102,-0.322035,-0.002601,0.024606,0.259299,1.052091,-0.096563,0.039368,-0.062636,0.908007,-0.425063,-0.250374,-0.402219,0.213715,0.182242,0.216261,0.413203,-0.454043,0.340461,-0.093157,-0.353880,-0.723473,0.348584,0.132413,-0.094349,-0.734521,0.511534,-0.273128,0.294767,0.273698,-0.063941,-0.034922,0.511856,0.041583,0.712973,0.265213,0.246898,-0.155825,0.433371,0.393077,-0.512660,-0.221909,0.068108,0.060276,-0.454353,-0.304682,-0.150573,-0.368086,0.086170,0.580100,0.355928,0.048655,0.235851,-0.536098,-0.107533,-0.093612,-0.623634,0.308210,-0.384926,-0.080476,-1.249036,0.040663,0.209267,0.102285,-0.034891,0.566739,-0.208222,0.907137,-0.550450,0.253241,0.423119,0.374823,-0.119500,0.837957,0.040161,0.146983,-0.204271,0.238522,0.130406,-0.230318,0.010375,0.536762,0.261074,-0.086136,-0.204627,-0.541027,0.281773', '3318306', '1322847', '24751811', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26928125', '沙滩鼠', '剧情', '一个漫无目标的青少年 Frankie 在夏天时面临父亲去世，试图摆脱无聊的生活及负面的自我质疑，因此结交了新的女友，并在网路上认识了一个老男人。', '哈里斯·迪金森', '伊丽莎·希特曼', 6.6, 7457, 'tt6303866', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2493593820.jpg', 1.2, 10, 51.3, 30.4, 7, '0.483835,-0.037183,-0.572931,0.524265,-0.245204,-0.203270,0.681885,0.286331,-0.683551,-0.566749,-0.003227,0.796128,0.126085,0.523558,0.241891,-0.521908,-0.085355,-0.493408,0.207183,-0.095495,-0.287449,-0.508124,-0.077744,-0.209884,-0.408298,-0.513321,0.750819,0.061047,-0.321683,0.552599,0.333324,0.318882,0.200636,0.961646,-0.109208,-0.106760,0.208964,0.058766,-0.227883,0.430892,-0.023952,-0.304105,0.329721,0.183832,-0.413978,0.408819,0.904511,-0.334302,-0.475236,-0.048720,0.836782,-0.082368,-0.252514,0.167766,0.521605,-0.035439,-0.102933,0.042842,-0.429111,0.247198,-0.149855,-0.122506,-0.794181,-0.085029,-0.025602,0.029409,-0.510788,0.564653,0.238849,-0.106324,0.119736,-0.262331,0.234830,0.589267,0.080018,0.447840,-0.524537,0.227639,-0.109998,0.441499,0.631993,-0.004436,-0.409917,0.342235,-0.256276,-0.144561,-0.125169,-0.208694,-0.748227,-0.170030,0.196063,0.031853,-0.809045,0.392797,-0.556054,0.149104,-0.195552,0.039627,0.344835,-0.573304,-0.444183,-0.600295,-0.247401,-0.052838,0.020573,-0.119481,-0.021888,-0.479718,0.822913,-1.126285,0.347607,0.792210,0.259434,-1.004924,0.690352,0.249193,0.308495,-0.534811,-0.198990,0.653662,0.140126,0.274504,-0.337891,0.149239,-0.264642,0.052193,-0.374478,0.390224', '3445516', '1293265', '1301022', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26928198', '红衣小女孩2', '惊悚', '整日奔波处理许多个案的社工师李淑芬（杨丞琳 饰），某天接获通报到一桩虐童案件，正盘查女童母亲林美华（高慧君 饰）时，突然接到女儿雅婷下午失踪于校园的消息，心急如焚的淑芬查看学校监视器后，竟发现雅婷跟着一名穿着红衣、身影诡异的小女孩离去，这个小女孩是谁？她们要去哪里？循着 线索，淑芬随着救难队在山区的废弃医院发现疑似雅婷的踪影，但找回的却是失踪已久的广播主持人沈怡君（许玮宁 饰）。无计可施的淑芬只好先将精神不稳定的怡君带回家，希望能从中问到女儿的下落，没想到带回家的可能不只是怡君…', '杨丞琳', '程伟豪', 6.6, 16387, 'tt6295898', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2506659316.jpg', 2.4, 11.6, 48.7, 29.1, 8.2, '0.339507,-0.080446,-0.554478,0.034752,-0.010660,-0.298997,0.482492,0.055581,-0.543873,-0.607796,0.083680,0.250568,-0.069693,0.466297,0.291014,0.076823,-0.327753,-0.456830,-0.139979,-0.239705,-0.495221,-0.285206,-0.082745,-0.182028,0.108472,-0.272843,0.426407,0.227781,-0.069027,0.427674,0.381673,0.325143,-0.522918,0.491181,-0.348422,0.120444,0.211135,0.249883,0.025057,0.228377,0.241474,-0.245775,-0.327659,0.024187,0.024752,0.262252,0.566327,0.190140,-0.246333,0.218766,0.511737,0.053164,0.085971,-0.157271,0.375087,-0.049855,0.267766,0.080840,-0.311202,-0.076059,-0.045567,0.000554,-0.077675,0.360478,0.141722,0.421068,-0.419292,-0.135229,-0.291537,-0.080315,0.175438,-0.659094,0.323455,0.390078,-0.268338,0.439369,-0.218770,0.114626,-0.498652,0.099777,0.294796,0.001509,0.042047,0.362291,0.189695,-0.363874,0.154706,0.054715,-0.228724,0.100863,0.180956,0.262093,-0.151958,-0.313306,-0.200796,-0.267920,-0.379130,-0.177609,0.084875,-0.188018,-0.434800,-0.476765,0.100865,-0.082338,-0.318193,0.433014,-0.044698,0.046314,0.472110,-0.730654,0.261565,0.458560,-0.125007,-0.619624,0.434680,-0.155306,0.142710,-0.247591,0.069688,-0.080473,0.202451,0.334078,-0.012293,0.123945,-0.236309,-0.447032,-0.640954,-0.198714', '1303485', '2052978', '30241301', '1292371');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26928478', '东北虎', '剧情', '美玲（马丽 饰）即将临盆，她的丈夫徐东（章宇 饰）只好将家中心爱的狗托朋友寄养到别处。马千里（张志勇 饰）是债务缠身的建筑商，他在穷途末路之际，偶然接收了徐东的宠物。不幸的是，这只狗的死亡让两个站在人生岔路口的失意者狭路相逢，满腔怒火的徐东在复仇的道路上屡战屡败，但却发现了马千里不为人知的一面。与此同时，美玲也意外的发现了徐东的秘密……不易熄灭的仇恨之火被点燃，熄灭仇恨的灭火器迟迟没有打开。东北虎在动物园里晒着太阳发呆，它似乎已经习惯了每天被饲养员扔下食物的生活。', '章宇', '耿军', 5.9, 35867, 'tt10097312', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2812275146.jpg', 4.8, 22.7, 48.7, 20.2, 3.6, '0.416206,0.212187,-0.768139,0.351388,-0.060601,-0.348142,0.938954,0.144148,-0.391667,0.053613,0.350814,0.541058,-0.091810,0.324308,-0.083899,0.015722,0.045180,-0.618455,-0.069819,-0.015889,-0.221406,-0.153551,-0.393969,-0.088538,-0.112263,-0.151741,0.563020,0.190957,-0.015467,0.457593,0.306248,0.027638,-0.055325,0.728881,-0.268455,0.303018,-0.091873,-0.117517,0.106038,0.150509,-0.013355,-0.416764,-0.089799,0.252883,-0.114218,0.513711,0.727578,-0.303669,-0.234238,0.087855,0.219515,-0.608100,0.034756,0.240704,0.490350,-0.020860,-0.172097,-0.130185,-0.280235,0.021793,0.153363,0.291193,-0.527347,-0.105180,-0.158426,0.320046,-0.751604,0.847339,-0.070538,-0.008475,0.215114,-0.464126,0.367849,-0.112729,-0.174401,0.366375,-0.274927,-0.030755,-0.814825,0.186320,0.538928,-0.353884,0.003763,0.443304,-0.388483,-0.296481,-0.006061,-0.005783,-0.533718,-0.413620,0.747611,0.268785,-0.537829,0.166253,-0.808887,0.164054,-0.137756,0.063168,-0.080330,-0.320227,-0.289112,-0.259958,0.053707,-0.412147,-0.318423,0.369316,0.051979,-0.121444,0.479024,-0.532432,0.262433,0.596407,0.062567,-0.102646,0.783570,-0.132249,0.140205,0.038642,-0.003155,0.227758,-0.043242,0.696728,0.460998,0.456298,-0.191326,-0.057594,-0.761378,0.634519', '21619567', '1293515', '3074533', '1394470');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26929010', '雪人奇缘', '喜剧', '珠穆朗玛峰的雪人是传说吗？不是！不仅不是传说，它还拥有令人着迷的魔力！少女小艺在天台上目睹了雪人大毛即将被抓的惨况，决定亲自护送大毛回家，她的小伙伴阿俊和鹏鹏也加入了护送队伍。一路上冒险小分队路经了千岛湖、黄山、乐山大佛等著名的中国景点，雪人大毛为了躲避抓捕者，也逐一展现了自己神奇的魔力。巨大化的蒲公英，一秒变大的蓝莓，油菜花海浪，还有什么是雪人大毛的魔力做不到的？而抓捕者也早已在他们的目的地珠峰等待着冒险小分队步入早已设好的圈套…', '汪可盈', '吉尔·卡尔顿', 7.1, 48172, 'tt6324278', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2616427110.jpg', 0.6, 6, 42.5, 38.5, 12.4, '-0.006960,-0.269728,-0.883776,0.449995,-0.131219,0.093646,0.227208,0.377249,-0.467942,0.078095,0.497493,0.366718,-0.177929,0.038940,0.056175,0.124970,-0.214149,-0.337341,-0.304757,0.040227,-0.659725,-0.121954,-0.161377,-0.241168,0.274312,-0.363245,0.446589,0.295079,-0.188566,0.393070,0.179360,-0.148430,-0.104739,0.286857,-0.513401,-0.122667,0.010809,-0.023888,0.135351,0.078466,-0.322647,-0.230735,-0.357650,-0.077463,-0.048520,0.328321,0.627288,-0.435693,-0.049346,-0.080076,0.056834,-0.792323,0.289128,-0.389456,0.370880,-0.227502,0.135510,-0.078549,0.107463,0.141346,0.187369,-0.336966,-0.736175,0.227648,0.221986,0.163542,-0.334097,0.494729,0.120365,0.055348,0.220483,-0.294709,-0.073550,-0.101116,-0.133618,0.292818,-0.133461,-0.148872,-0.613777,0.291741,0.655732,-0.024945,-0.220875,0.264564,0.100435,-0.374274,-0.440080,-0.079291,-0.166983,0.129320,0.550737,0.119487,-0.204593,0.211289,-0.786744,0.050933,-0.499724,-0.239704,-0.008039,-0.294356,-0.354208,-0.406866,0.183178,-0.025510,-0.011825,0.215711,0.254713,-0.027752,0.689560,-0.594722,0.125034,0.815818,-0.026024,-0.564919,0.497337,-0.456656,-0.204295,0.061784,-0.103830,-0.000539,0.085499,0.614523,0.400174,0.411802,-0.134583,-0.002512,-0.364043,0.130145', '26921827', '1438591', '3755531', '1457926');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26929835', '跨越8年的新娘', '剧情', '在某修车行工作的西泽尚志（佐藤健 饰）看起来像个寡然无味的年轻人，他和其他男生参加了一次联谊，阴差阳错和联谊会上的女孩中原麻衣（土屋太凤 饰）熟稔。麻衣快人快语，开朗阳光，和尚志形成了完美的互补。在接下来的一段时间，两人越走越近，尚志终于鼓起勇气向麻衣求婚，一切看似美好。可是毫无征兆，麻衣身上出现了各种奇怪的症状。经诊断发现，她罹患了十分棘手的疑难杂症——抗NMDA受体脑炎。最终，麻衣陷入长久的昏迷，饱受折磨。女孩的遭遇令她的父母伤痛欲绝，而尚志则不离不弃，始终坚守在女友身边，等待他醒来那一天。终于，麻衣张开了紧闭多年的双眼，可是更多的考验还等在前面……本片根据真实事件改编。©豆瓣', '佐藤健', '濑濑敬久', 6.8, 11424, 'tt6313348', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2536466873.jpg', 0.5, 7.3, 53.7, 28.9, 9.6, '0.134220,-0.229331,-0.484152,0.123501,0.004823,-0.396670,0.595729,0.152586,-0.401904,-0.395920,0.403169,0.552052,-0.401503,0.228758,0.086674,-0.130835,-0.167325,-0.628236,-0.101805,0.150428,-0.375209,-0.157857,-0.040290,-0.013376,-0.040175,-0.450858,0.589042,0.178278,0.055091,0.532023,0.172577,0.267231,-0.142057,0.468680,-0.062953,-0.139314,0.003131,0.093841,-0.257656,0.193920,0.140136,-0.301780,-0.280191,0.238049,-0.409456,0.339653,0.488681,-0.294320,-0.616538,0.128249,0.502166,-0.252112,-0.387202,0.158363,0.284683,0.127230,0.248956,0.084483,-0.321088,0.048013,-0.075445,0.126048,-0.290727,-0.020714,0.053648,0.517824,-0.540682,0.628641,0.124900,-0.181593,0.067827,-0.668948,-0.067116,0.376771,0.194014,0.230437,-0.279577,0.133074,-0.371754,0.156488,0.433734,0.202680,-0.352882,0.425219,-0.193590,-0.294091,0.162825,-0.110488,-0.319982,0.064144,0.177370,0.008646,-0.319089,0.001919,-0.356705,0.242039,-0.128156,-0.053921,-0.229076,-0.148711,-0.312640,-0.632370,-0.112732,-0.493561,-0.269301,0.129103,-0.167381,-0.247522,0.618115,-0.642590,0.248058,0.382338,0.044646,-0.085441,0.565177,0.270149,0.007187,-0.143441,-0.179127,0.368284,-0.234015,0.212354,0.211672,0.569752,-0.197650,0.369272,-0.477031,0.387280', '3811356', '1826173', '5262027', '1915403');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26930056', '汪星卧底', '喜剧', '影片讲述了纽约警局警犬麦克斯（卢达克里斯 Ludacris 配音）与它的人类搭档FBI探员弗兰克（威尔·阿奈特 Will Arnett 饰）联手破案的惊险经历。本互不相识且性格迥异的一人一犬，因为一宗珍稀动物偷盗案被强行组队。随后更被派遣到拉斯维加斯参加全球知名犬展，通过卧底行动缉拿罪魁祸首。而此次行动对于“厌狗”的探员弗兰克和不修边幅的麦克斯，远比想象中的艰难…', '威尔·阿奈特', '拉加·高斯内尔', 6, 3446, 'tt5691024', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2526399205.jpg', 4.2, 14.2, 60.4, 17.7, 3.5, '0.675969,-0.248102,-0.347869,0.482900,0.215838,-0.259330,0.370697,-0.010270,-0.454528,-0.184390,0.062445,0.721771,-0.248602,-0.274782,0.370172,-0.454394,-0.322594,-0.550864,-0.293401,-0.043477,-0.066820,-0.631430,-0.152516,-0.198070,0.039251,-0.206777,0.578945,0.070565,-0.391831,0.766031,0.117785,0.377525,-0.303613,0.077178,0.261229,-0.295263,0.550148,0.054170,-0.372097,0.280182,0.087819,-0.229541,0.113128,0.057741,0.092307,0.381741,0.504044,-0.323402,-0.018086,-0.307918,0.172935,-0.314059,0.083477,0.093425,0.375793,0.237751,0.186681,0.459199,0.161663,0.040442,0.017855,-0.338696,-0.874832,0.305200,0.109039,0.166558,-0.119006,-0.074654,-0.249657,0.280832,0.204942,-0.099054,-0.025765,0.405823,0.552628,0.009948,0.143645,-0.035583,-0.345166,0.099286,0.643588,0.040402,-0.176612,-0.142875,-0.102032,-0.733724,0.006671,-0.451512,-0.208457,0.284274,0.440339,-0.204807,-0.070739,0.444997,-0.506343,-0.073566,-0.252757,-0.123278,-0.316873,-0.196627,0.201827,-1.136413,-0.244885,-0.286066,-0.171721,-0.271166,0.269409,-0.317174,0.198846,-0.669686,0.045552,0.651699,0.219381,-0.326029,0.303457,-0.016889,0.412827,-0.348356,-0.203351,0.257206,0.600483,0.192420,0.061286,0.268370,0.063260,-0.109988,-0.406742,0.050269', '2369613', '2028645', '25723905', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26930375', '凭空而来', '剧情', '卡嘉（黛安·克鲁格 Diane Kruger 饰）曾经有一个非常幸福的家庭，然而，一场可怕的恐怖袭击让她在瞬间失去了丈夫奴里（努曼·阿卡尔 Numan Acar 饰）和年幼孩子。爆炸的始作俑者是一对“新纳粹分子”情侣艾达（汉娜·希尔斯多夫 Hanna Hilsdorf 饰）和安德烈（乌尔里奇·布兰德霍夫 Ulrich Brandhoff 饰），两人很快就遭到了逮捕等待庭审。在庭审中，艾达和安德烈的律师指出卡嘉夫妇曾经参与过贩毒活动，同时他们自己也曾经吸食过毒品，这一劣迹的曝光直接影响了法官对案情的判断，最终，这对情侣因为证据不足而被无罪释放。悲愤和绝望之中，卡嘉决定通过自己的双手来为家人们报仇。©豆瓣', '黛安·克鲁格', '法提赫·阿金', 7.4, 14513, 'tt5723272', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2507115038.jpg', 1, 3.1, 33.5, 50.5, 12, '0.416929,-0.161550,-0.683392,0.427330,-0.095204,-0.292150,1.048518,0.056865,-0.532047,-0.224912,0.185917,0.896460,-0.471666,0.065789,0.351919,0.090037,-0.487639,-0.851865,0.049531,-0.099491,-0.231094,-0.814818,-0.201054,-0.296576,-0.111897,-0.246101,0.442668,-0.074248,-0.073178,0.578520,0.296745,0.513107,-0.048239,0.500924,0.108229,0.128794,0.324821,-0.068416,-0.337377,0.073781,0.242893,-0.226643,-0.051456,0.333592,-0.039038,0.356054,0.526014,-0.658102,-0.122823,-0.296826,0.186600,-0.443986,0.070094,0.397135,0.351881,-0.037085,0.263819,0.219001,-0.291620,-0.245760,0.190835,0.068948,-0.704712,-0.122940,0.122774,0.159395,-0.437400,0.377079,-0.210930,-0.042476,0.264331,-0.087005,0.188131,0.463702,0.288748,0.330733,-0.350598,-0.240530,-0.468003,0.079606,0.642256,-0.087750,-0.226406,0.175666,-0.426936,-0.405124,-0.103755,-0.012453,-0.451440,0.109915,0.479424,0.081862,-0.092134,0.461196,-0.552059,-0.293105,-0.513480,-0.162019,-0.234453,-0.404097,-0.043041,-0.625950,-0.271837,-0.339874,-0.287522,0.052371,-0.010678,-0.261290,0.483834,-0.811631,0.263961,0.404282,0.361717,-0.399062,0.386106,0.145906,0.267005,-0.264374,-0.165971,0.170741,0.237833,0.089017,0.291903,0.303537,0.281817,-0.052652,-0.085930,0.425497', '1301686', '1296534', '1293145', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26930504', '烟花', '剧情', '炎炎夏日，茂下町的烟花大会即将举行。就读于当地高中的及川奈砂（广濑铃 配音）并未沉浸在愉快祥和的气氛之中，她即将随母亲（松隆子 配音）搬家到另一个城市，心中满是失落。在某次即兴的游泳比赛时，奈砂击败同班同学岛田典道（菅田将晖 配音）和安昙祐介（宫野真守 配音）。随后她坦白喜欢祐介，希望烟花大会时能与对方一同游玩。可是祐介、典道随后卷入和朋友们关于“烟花到底是圆是扁”的争论中，大家约好当晚一起去某地见证。祐介因此爽约，而同样偷偷喜欢着奈砂的典道因此发觉了女孩的秘密和心思。他为此责怪好友，也渴望时光重来，迎得当初那场比赛……本片根据岩井俊二的同名电视剧改编。©豆瓣', '广濑铃', '新房昭之', 5.5, 63514, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2504455660.jpg', 10.1, 31.3, 39.9, 12.9, 5.8, '0.160732,0.099271,-0.609006,0.414618,0.391410,-0.083820,0.344573,0.110432,-0.255206,-0.191691,-0.135854,0.675231,-0.321193,0.507798,0.322295,-0.167296,-0.280010,-0.703108,-0.155886,-0.053268,-0.080521,-0.307316,0.121518,0.108856,0.011956,-0.166027,0.458470,0.168315,-0.103139,0.803134,0.419362,0.392425,-0.337960,0.445265,0.060753,-0.194437,-0.089112,0.389215,-0.426688,0.104580,-0.070323,-0.181352,-0.440065,0.026421,0.438944,0.275318,0.695496,-0.019213,-0.230836,0.117607,0.235690,-0.056528,0.007848,0.020615,0.217093,0.116107,0.367315,0.068357,-0.177938,0.285057,-0.139358,-0.364969,-0.328687,0.171261,0.208612,-0.019473,-0.280833,0.520368,0.272192,-0.107211,0.209175,0.006510,0.336535,0.339946,0.333614,0.127572,-0.045579,-0.012979,0.013568,0.364661,0.880952,-0.053430,0.159308,0.427049,-0.118609,-0.181262,-0.007472,-0.111815,-0.294837,0.333571,0.064655,-0.016724,-0.058112,0.157877,-0.438709,-0.166592,0.083944,-0.032370,0.250409,-0.262560,0.132998,-0.691822,-0.034277,-0.219165,-0.189691,-0.248179,0.101885,-0.285329,0.665659,-0.963629,0.262534,0.624829,0.254937,-0.192805,0.561133,0.337602,0.041246,-0.199672,0.015599,-0.095721,-0.071216,-0.013846,-0.051276,0.274427,0.069677,-0.227753,-0.577252,0.225848', '3139191', '3091208', '1292219', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26931155', '给19岁的我自己', '剧情', '莫晓枫在一次冒险中出了意外去世，在暗恋了10年的莫晓枫的葬礼上阳艺雪得到了他留给自己的遗物，一个装有满满书信的“神秘木盒”，捧着这些倾注爱意的信笺，阳艺雪思绪纷飞，尘封的记忆被打开，她后悔当年与爱人失之交臂。而“神秘木盒”具有神奇穿越功能，可与过去时空连接，阳艺雪通过不断地与19岁的自己鸿雁传书，欲追回错失的爱。', '林柏宏', '黄朝亮', 4.9, 3647, 'tt8734578', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2521030550.jpg', 17.9, 37.9, 29.2, 10.3, 4.6, '0.172298,0.477855,-0.919597,0.760633,-0.277921,-0.335137,1.131085,-0.221998,-0.584218,-0.119983,-0.142194,0.834693,-0.051201,0.330357,0.031503,0.218272,0.194887,-1.040482,-0.043846,-0.409835,-0.376138,-0.485320,-0.540236,-0.091165,0.023100,-0.706828,0.806486,0.312523,-0.125854,0.554439,0.243436,0.433432,-0.399737,0.416267,-0.503373,0.053805,-0.367925,0.273369,-0.315440,0.130560,0.110423,-0.430748,0.002030,0.371645,-0.328619,0.120013,0.912053,-0.400790,-0.158207,0.217188,0.767854,-0.285957,-0.364086,-0.095482,0.008689,0.763297,-0.273717,0.119836,-0.545573,-0.027033,0.254319,-0.291862,-0.675626,-0.394763,-0.035333,0.167707,-0.855678,0.540513,-0.264824,0.137115,0.083081,-0.451581,0.273692,0.181045,0.195188,0.500446,-0.385811,-0.046718,-0.366682,0.272816,0.273210,-0.407828,0.007907,0.437007,-0.080551,-0.347361,-0.085087,-0.121646,-0.655690,0.426835,0.661931,0.332043,-0.056630,0.190990,-0.771560,0.006445,-0.127115,0.053483,0.445056,-0.402524,-0.450311,-0.195997,-0.599691,-0.151531,-0.602903,-0.100013,-0.021201,-0.311468,0.785037,-0.457297,0.636347,0.696870,-0.038958,-0.504406,0.858494,0.213303,-0.049840,-0.180767,0.073597,0.385681,0.083658,0.355233,0.187516,0.148793,-0.034674,0.164276,-0.884960,0.353999', '1467779', '21619567', '1307146', '10742456');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26931786', '蜘蛛侠：英雄远征', '动作', '在与灭霸史诗般的战争结束后，地球似乎暂时回归和平。皮特（汤姆·赫兰德 Tom Holland 饰）回到了校园生活之中，他和好友相谈甚欢，并且有了心仪的女孩，然而内心最深处依然放不下对钢铁侠的追悼缅怀。去往欧洲游学的路上，皮特试图找机会和个性女孩米歇尔（赞达亚 Zendaya 饰）表白，谁知接连出现的元素怪兽打乱了他的表白计划。在这一过程中，与神盾局合作的神秘客（杰克·吉伦哈尔 Jake Gyllenhaal 饰）挺身而出，击退怪兽。自感不堪大任的皮特谢绝了尼克·弗瑞（塞缪尔·杰克逊 Samuel L. Jackson 饰），情愿将钢铁侠继承者的重任交到神秘客手中。令他意想不到的是，更可怕的危机接二连三袭来……©豆瓣', '汤姆·赫兰德', '乔·沃茨', 7.6, 567158, 'tt6320628', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2558293106.jpg', 0.7, 3.6, 30, 46.1, 19.6, '0.137551,0.247795,-0.619169,0.405306,0.121673,-0.144678,0.664763,0.082466,-0.448531,-0.276387,0.182210,0.778406,-0.208848,0.027204,0.475843,-0.046889,-0.268932,-0.647586,-0.083092,-0.119088,-0.153272,-0.321361,-0.374998,-0.136411,-0.028422,-0.544239,0.376698,0.125725,-0.169967,0.601319,0.288580,0.444950,-0.153850,0.558919,-0.129550,0.014979,0.141268,0.142972,-0.523939,0.267060,0.090962,-0.139310,0.002257,0.540452,-0.134684,0.290353,0.514398,-0.475294,0.124515,0.006562,0.230596,-0.205965,-0.012832,0.115544,0.197626,0.114257,0.017182,0.033526,-0.068864,-0.098586,0.268534,-0.202723,-0.504576,0.153339,-0.041767,0.223431,-0.449883,0.406593,-0.173491,0.257024,0.051206,-0.272585,0.137842,0.150454,0.497360,0.041366,-0.007313,0.023713,-0.149586,0.068516,0.560961,-0.045273,-0.334495,0.062287,-0.161389,-0.300930,0.023608,-0.130963,-0.381029,-0.207682,0.464061,0.234503,0.065560,0.283667,-0.820344,-0.057827,-0.519549,0.169902,-0.029269,-0.386858,-0.154592,-0.609071,-0.100137,-0.247796,-0.137089,0.215052,-0.019272,-0.109798,0.492682,-0.761850,0.268438,0.519449,0.294115,-0.090618,0.558025,0.074587,0.055771,-0.376065,0.037561,0.275879,0.050134,0.198806,-0.006373,0.235929,0.020818,-0.233819,-0.329033,0.365954', '11541282', '1292050', '1299556', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26932875', '今天开始世界属于你', '剧情', '小沼真实（门胁麦 饰）曾经也是一个活泼开朗的女孩，但现如今，她成为大门不出二门不迈的家里蹲已经五年之久了。在这五年里，足不出户的真实一直都靠着临摹喜欢的插画作品来排解压力逃避现实。在父亲的介绍之下，真实终于鼓起勇气进入了一家游戏公司上班。然而，毫无社会经验的真实在工作中漏洞百出，做出来的游戏全是漏洞，本以为要被骂的她，却意外的得到了同事矢部辽太郎（三浦贵大 饰）的认可。辽太郎认为真实拥有绘画的天赋，在他的建议和鼓励之下，真实成为了游戏原画师，并且开始尝试不再模仿，去创造属于自己的独一无二的角色。©豆瓣', '门胁麦', '尾崎将也', 7.2, 5241, 'tt6323858', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2521709521.jpg', 1.2, 7, 39.1, 37.6, 15.1, '0.260798,0.399822,-0.611081,0.630618,-0.347058,-0.063926,0.392587,-0.035816,-0.419789,-0.400984,0.181457,0.635521,0.061202,0.154018,0.192508,-0.068663,-0.146402,-0.559040,-0.027027,-0.338845,0.057655,-0.582327,-0.370379,-0.258811,-0.314603,-0.283342,0.650393,0.170306,-0.435610,0.203716,0.267956,0.189087,0.138425,0.294645,-0.208752,0.085293,0.131778,0.162913,-0.142810,0.120474,0.064478,-0.335409,-0.097926,0.365948,0.081139,0.259935,0.439009,-0.344083,-0.456939,0.285362,0.697326,-0.038802,-0.282633,0.153099,0.299900,0.146742,0.207729,0.145937,-0.198142,0.239118,-0.018960,-0.032338,-1.046640,-0.259548,0.393058,0.010088,-0.617315,0.430049,-0.061018,-0.333164,0.116028,-0.354774,0.146051,0.232236,0.340320,0.385659,-0.210765,0.226969,-0.566531,0.395226,0.495033,-0.013020,-0.238884,0.513790,-0.169173,-0.277269,-0.263281,-0.529427,-0.333743,-0.060077,-0.172851,0.122278,-0.397803,-0.136418,-0.463945,-0.016916,-0.069993,-0.132102,0.217672,-0.528456,-0.160609,-0.399430,-0.241440,-0.362505,-0.185209,-0.098514,-0.029353,-0.670666,0.756649,-1.133152,0.140093,0.550619,0.191318,-0.456138,0.837460,0.190580,-0.119500,-0.255219,0.006272,0.167774,0.020957,0.402574,-0.092022,0.504682,0.102153,-0.215789,-0.637234,0.573091', '1793491', '24284209', '25880986', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26933210', '蜘蛛侠：英雄无归', '动作', '《蜘蛛侠：英雄无归》是英雄系列三部曲的完结篇，也标志着漫威多元宇宙的正式开启。此次，蜘蛛侠（汤姆·赫兰德 饰）与奇异博士（本尼迪克特·康伯巴奇 饰）继《复联4》后再度联手打响时空混战。蜘蛛侠借助奇异博士操控时空的能力打开了时空通道，引发了前所未见的危机。', '汤姆·赫兰德', '乔·沃茨', 6.6, 294782, 'tt10872600', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2730024046.jpg', 2.1, 13.6, 44.8, 29.4, 10, '0.193559,0.572005,-0.519204,0.340355,0.589659,-0.163644,0.495708,-0.090838,-0.321522,-0.178357,0.020198,0.692781,-0.439652,-0.289081,0.337933,0.030972,-0.459815,-0.310091,-0.285288,-0.174159,-0.352174,-0.263862,-0.529108,0.000293,0.177369,-1.044786,0.947227,0.031430,-0.336533,0.039561,0.184298,0.598266,-0.537284,0.161114,-0.027709,0.059134,0.183719,0.048402,-0.673622,0.581888,-0.346690,0.090029,0.210503,0.410294,-0.456459,-0.017332,0.794627,-0.852267,0.244340,-0.136302,0.722232,-0.203730,-0.472329,-0.615105,0.217359,0.256872,-0.162414,0.338658,0.219821,0.221082,0.023978,-0.318342,-0.683199,-0.292629,0.220636,0.187344,0.160321,0.101678,-0.339473,-0.306218,0.114266,-0.055350,0.111674,0.149916,1.014625,0.114363,0.072418,0.040068,-0.298600,0.136974,0.220123,-0.280310,-0.674984,0.296841,-0.052457,-0.383180,-0.315622,-0.183691,-0.343777,-0.044227,0.484337,0.464850,0.377332,0.609724,-0.882880,0.159792,-0.480683,0.172103,0.070909,-0.064667,-0.041420,-0.931706,-0.262241,0.132017,0.099320,0.041564,0.264819,-0.245332,0.316331,-0.915630,0.316131,0.649793,0.290905,0.219317,0.758646,-0.332224,0.195665,-0.640717,0.218195,-0.210562,-0.092770,0.445123,-0.057851,0.589411,0.187580,-0.252374,0.007648,0.457161', '26759820', '26759819', '30382416', '25925764');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26933356', '无巧不成婚', '剧情', '继高分神片"触不可及 "之后，奥利维埃·纳卡什与埃里克·托莱达诺两位法国导演合作执导的又一部法式温情喜剧：满是灾难的婚礼筹备，漏洞百出的活动现场，加上一个温馨收尾的意外结局...暖心而励志。在刚刚公布的第43届法国凯撒电影奖提名名单中，本片荣获最佳影片、最佳导演、最佳男主等10项提名...', '让-皮埃尔·巴克里', '奥利维埃·纳卡什', 7.3, 6542, 'tt5699154', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2515609231.jpg', 0.8, 3.4, 38.9, 44, 12.9, '-0.112896,-0.080156,-0.659540,0.888299,0.516180,-0.385922,0.656891,0.339218,-0.007131,-0.081357,0.138730,0.855833,-0.827834,0.104914,0.797570,-0.328833,-0.429423,-0.717782,-0.087468,-0.149433,0.157906,-0.193048,-0.516813,-0.057188,0.008591,-0.238642,0.876823,0.357042,-0.333030,0.473568,0.980252,0.097057,-0.165920,0.271530,0.285962,0.006213,0.606676,-0.112482,-0.673505,0.686239,0.227397,-0.186677,-0.209182,0.177158,0.084857,0.543596,0.738142,-0.249986,0.199018,0.140014,0.823539,-0.238487,-0.043057,-0.027025,0.141340,0.126016,0.396397,0.232223,-0.076622,0.369022,-0.049509,-0.316998,-0.953021,0.142539,0.132591,0.242788,-0.168757,0.366315,-0.055320,0.368817,-0.008306,0.257581,0.196147,0.459149,0.775294,0.114053,0.067326,0.174828,0.159369,0.765457,0.254851,0.000926,-0.385178,0.615288,0.122900,-0.836519,0.286791,-0.273881,-0.368342,0.310134,0.555873,-0.189810,0.579823,-0.036406,-0.238371,-0.345708,-0.221041,-0.443037,-0.151835,-0.051234,0.244014,-1.118363,-0.103428,0.106756,-0.079907,0.077097,0.258178,-0.270321,0.448890,-0.230082,0.240361,0.169781,-0.153839,-0.153949,0.743663,0.415283,0.161604,-0.403394,-0.103324,0.170335,-0.323929,-0.143069,0.088938,0.309961,0.058358,-0.347054,-0.381738,0.388363', '3318306', '30397916', '1292759', '3275168');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26933588', '圣母', '剧情', '故事改编自真实事件，发生在17世纪位于意大利的一家修道院内。本尼蒂塔（维吉妮·艾菲拉 Virginie Efira 饰）出生在一个富裕而又虔诚的基督教家庭之中，在很小的时候，她就被父母送进了修道院深造，将她作为一名修女培养。在那个年代，进修道院对于一个女孩来说，是何等幸运的事情。一晃眼多年过去，贝尼蒂塔已经出落成为了大姑娘了，并且成为了修道院院长福利西塔（夏洛特·兰普林 Charlotte Rampling 饰）的得力助手。某日，一个衣衫褴褛的女孩冲进修道院求助，她的名字叫巴托洛梅阿（达芙妮·帕塔基亚 Daphne Patakia 饰），在本尼蒂塔的帮助之下，这个可怜的，遭受了父亲和哥哥虐待的女孩进入了修道院，成为了见习修女。可是，巴托洛梅阿就像一匹野马一样的难以驯服和管教，她的出现很快就让本尼蒂塔感到棘手和难以招架。©豆瓣', '维尔日妮·埃菲拉', '保罗·范霍文', 7.8, 45374, 'tt6823148', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2713726815.jpg', 0.5, 2.3, 25, 52.1, 20, '0.493732,0.074917,-0.581419,0.625493,-0.261692,-0.406679,0.814362,0.101958,-0.285281,-0.466969,0.048974,0.881203,-0.091042,0.316954,0.329486,0.207954,-0.138190,-0.730295,-0.060497,-0.452116,-0.394856,-0.437496,0.034807,-0.266819,-0.064749,-0.582809,0.362007,-0.041399,-0.199407,0.256011,0.353416,0.490368,-0.014424,0.201612,-0.432639,0.131765,0.412076,0.010359,0.019663,0.442152,-0.027610,-0.013333,0.102411,0.002315,-0.008816,0.044593,0.639686,-0.553360,0.144837,-0.082348,0.335921,-0.158288,-0.060489,0.267416,0.576532,-0.196271,0.018359,-0.138164,-0.316467,0.109405,0.204554,-0.490097,-0.607444,0.028927,0.211904,0.056887,-1.018450,0.370531,0.030575,-0.146782,0.237915,-0.361726,0.119204,0.242991,0.022969,0.793138,-0.010496,0.221472,-0.646693,0.006934,0.679430,-0.034521,-0.410476,0.157388,-0.321336,-0.551824,0.048919,-0.183557,-0.521346,-0.006311,0.324563,-0.262710,-0.145978,0.402625,-0.465482,-0.007191,-0.643258,-0.267256,0.051240,-0.286367,-0.142251,-0.335611,-0.202561,-0.273152,-0.279966,0.099425,-0.135824,-0.151865,0.746546,-0.818783,0.512414,0.440387,0.348150,-0.197841,0.842811,0.024219,0.286206,-0.121317,0.054109,0.606999,0.121766,0.261378,0.196535,0.369725,-0.124754,-0.239485,-0.245843,0.565895', '1299965', '1292720', '3055049', '