INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26934399', '毒战', '动作', '韩国最大规模贩毒组织的神秘BOSS李先生气焰嚣张，他新近通过一起爆炸案除掉了无用的干部，甚至连侥幸逃生的骨干也被害死在警局之中。缉毒组组长赵元浩（赵震雄 饰）从爆炸案现场救出在组织内担任联络工作的徐永乐（柳俊烈 饰），经过审讯得知，徐原本负责与盘踞在国外的毒枭霖（金柱赫 饰）接洽，因提前回国而误卷入组织清洗之中。赵组长将计就计，决定周旋在李先生和霖中间上演双簧，以将贩毒组织连根拔起。这一过程险象环生，危机不断，而真正的李先生却还未显现出他真实的用心……本片翻拍自杜琪峰的同名原作。©豆瓣', '赵震雄', '李海暎', 6.6, 19239, 'tt7095654', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2522806962.jpg', 1.8, 11, 50.2, 27.4, 9.6, '0.102531,0.233373,-0.894692,0.508614,0.070287,-0.160974,0.471682,-0.029989,-0.542009,-0.367789,0.136056,0.137259,-0.092161,0.036561,0.175920,-0.508871,-0.326301,-0.617849,-0.310011,-0.105792,-0.427695,-0.668028,-0.336077,-0.239377,-0.198127,0.012533,0.615169,0.289977,-0.461091,0.285324,0.402519,0.459968,-0.562917,0.432475,-0.001978,-0.233610,0.163940,-0.004370,-0.489352,0.069252,0.116075,-0.724207,0.015465,-0.107923,0.292848,0.553627,0.624884,-0.179759,0.018389,-0.222414,0.294392,-0.379071,-0.072815,-0.191496,0.684322,0.219390,0.031341,0.367195,-0.417199,-0.038816,-0.041384,-0.196728,-0.797654,-0.108578,0.363969,0.140998,-0.454688,-0.065547,0.159557,0.346820,0.056325,-0.187286,0.393728,0.656424,0.269126,-0.055676,0.097406,0.249947,-0.411377,0.431999,0.714447,-0.203729,-0.019089,-0.242025,0.176567,-0.352138,0.060425,-0.213638,0.028176,-0.057237,0.244634,-0.339010,0.154012,0.070439,-0.403379,-0.272847,-0.086768,-0.014404,-0.016296,-0.193077,0.298794,-0.889401,-0.309501,0.028054,-0.055843,0.082654,0.023735,-0.258383,0.333912,-0.759394,0.144715,0.426142,0.176308,-0.600677,0.282542,0.101386,0.372757,-0.326822,-0.183925,0.028758,0.608301,0.291479,0.261234,0.345971,-0.193401,-0.282451,-0.301889,-0.195874', '5157137', '25870679', '4193254', '26336253');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26935251', '春宵苦短，少女前进吧！', '喜剧', '古色古香的京都，奇妙的恋爱之旅正在展开。春天，黑发少女踏上寻找伪电气白兰地的夜之旅，学长却被从天而降的锦鲤砸晕；夏天，少女在旧书市寻找心爱的童年绘本，学长则面临残酷的火锅地狱；秋天，身背红鲤鱼的少女化身不倒翁公主，与拼死出演顽固王的学长相遇在学园祭的舞台；冬天，手持梦幻感冒药的少女打倒感冒之神，与学长一起向京都的天空飞去……', '星野源', '汤浅政明', 8.7, 117991, 'tt6335734', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2418455758.jpg', 0.5, 1.4, 11, 36, 51.1, '0.191651,0.137531,-0.267341,0.430158,0.201771,-0.153708,0.690316,0.324825,0.268620,-0.144662,0.470458,0.404804,-0.110468,0.512138,0.686113,0.033334,-0.080126,-0.649747,-0.401046,0.205239,-0.269228,0.029382,-0.078145,0.312805,0.105497,-0.346216,0.978995,0.190643,-0.087614,0.549647,0.187144,0.140906,-0.473205,0.251710,-0.495054,-0.304198,-0.006597,0.427495,-0.341256,0.385680,-0.157694,-0.226295,0.154304,-0.186794,0.070024,-0.119131,0.895383,-0.431296,0.108344,-0.383265,0.551770,-0.462464,-0.179217,0.250782,0.521366,0.170813,-0.001822,-0.515498,0.412700,-0.470781,0.090981,-0.577629,-0.075993,0.119683,0.339181,0.067760,-0.375631,0.304781,0.146120,0.212842,0.448500,-0.097962,0.087211,0.094392,0.263071,0.444882,0.005368,0.191095,-0.245697,0.401681,0.684779,0.066375,-0.391241,-0.073530,-0.174238,-0.236016,-0.029711,0.066940,-0.226622,-0.055279,0.464714,-0.272714,0.093503,0.365385,-0.886619,0.135117,-0.127876,-0.079853,0.187347,-0.160634,-0.732255,-0.474958,0.322911,-0.132592,0.019344,0.228505,0.419631,0.006731,0.450134,-0.689561,0.478812,0.518870,0.292955,0.247751,0.769089,-0.135279,-0.216918,-0.422918,-0.202594,0.546751,-0.117620,0.381820,-0.219471,0.451892,-0.426150,0.330557,-0.755866,0.256380', '1467779', '26290398', '10174444', '1417036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26935281', '郊区的鸟', '剧情', '郊区某处突发地面沉降，一队工程师前往调查原因。队员夏昊每天背着沉重的测量设备，在已经撤空的郊区里游荡。一日，他进入一间无人的小学，读到一本日记，里面记载了少年隐秘的成长和一个团体的破裂，随着调查的进行，夏昊发现，日记预言了一切。', '李淳', '仇晟', 6.3, 7963, 'tt8747304', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2631489608.jpg', 3.6, 15.6, 48.9, 28.3, 3.6, '0.489275,-0.383961,-0.825547,0.507774,0.036789,0.119880,0.774285,-0.199096,-0.557078,-0.680869,0.396995,0.598126,-0.035063,0.389308,0.083729,-0.049712,-0.380283,-0.577342,-0.096783,-0.481214,-0.582798,-0.666900,-0.522404,-0.285950,0.057682,-0.353001,0.613387,0.526151,-0.417604,0.214173,-0.493586,-0.180176,-0.713113,0.239278,-0.279688,-0.331279,0.158180,-0.082230,0.324562,0.228618,0.064985,-0.317057,-0.093565,-0.276842,0.167134,0.591001,0.903260,-0.125647,-0.201654,0.239851,0.539579,0.057878,-0.559575,0.069987,0.605821,0.472434,-0.007025,0.264557,-0.506054,0.070514,-0.549031,-0.373606,-0.547782,-0.585878,0.136605,0.428507,-0.621512,0.577358,-0.088134,0.071711,0.097313,-0.591714,0.363170,0.249130,0.004764,0.575894,0.049082,-0.117834,-0.245836,0.001179,0.325218,-0.420249,-0.018078,0.062789,0.103781,-0.380494,-0.137297,0.319709,-0.515979,0.241115,0.099096,0.078882,-0.223078,-0.071654,-0.595574,0.282997,-0.344797,-0.573093,-0.122051,-0.086813,-0.488476,-0.943267,0.053171,0.346888,-0.035768,0.194318,-0.125538,-0.350965,0.688672,-0.605548,0.239627,0.333574,0.002178,-0.368733,0.447749,-0.565927,0.425024,-0.255362,0.173251,0.325774,0.168584,0.934409,-0.073140,0.626032,-0.215716,-0.328767,-0.755388,0.215533', '1307897', '2357703', '26951746', '5247058');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26935283', '侍神令', '奇幻', '穿行于人妖两界的阴阳师晴明（陈坤 饰），因与一众妖怪缔结契约，酿成大祸，深陷危机。而与此同时，妖皇势力正卷土重来，一场恶战一触即发。在风云突变、局势动荡的危急时刻，晴明恍然发现，自己人妖混血的身份，竟是这一切灾祸的关键......', '陈坤', '李蔚然', 5.3, 180956, 'tt12151820', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2629260713.jpg', 8.7, 33.1, 44.6, 11, 2.6, '-0.106779,0.223445,-0.660598,-0.044980,0.445576,0.200308,0.697496,0.070880,-0.332472,-0.595271,0.846390,0.668381,-0.431869,-0.283013,0.351008,-0.527164,0.274623,-0.833902,-0.146750,0.572499,0.082006,0.198149,-0.741382,-0.041686,-0.092323,-0.658509,0.900549,0.821800,-0.417132,0.143011,0.270290,0.487858,-1.113303,0.558254,0.026881,-0.176955,-0.173371,0.190493,-0.827272,-0.123306,-0.404302,-0.568043,-0.249613,0.353949,-0.280137,0.349943,0.657744,-0.757681,-0.246038,-0.212753,0.416721,-0.677309,-0.543319,0.561661,0.746385,-0.305059,0.101546,-0.086758,0.053180,-0.295772,-0.187591,0.200041,-0.469644,0.116187,0.009691,0.588906,0.143117,0.401721,0.309909,-0.047475,-0.050344,0.006493,0.170646,0.822353,0.627541,0.142285,-0.072870,-0.129081,-0.306124,-0.724337,0.822974,-0.371688,-0.172785,0.222021,0.204267,-0.625345,-0.376857,-0.375821,-0.315775,0.015450,0.619155,-0.141295,0.152190,0.981939,-0.646328,-0.128646,-0.306835,-0.065258,-0.036407,-0.103457,-0.269289,-0.104036,-0.380689,-0.392571,-0.342018,0.317096,0.255150,-0.012783,0.337063,-0.647380,0.007668,0.493522,0.020378,-0.448538,0.198625,0.348006,0.462471,-0.542472,-0.460561,0.459024,-0.371001,0.100718,-0.015689,-0.128747,0.028845,0.330575,0.005818,0.058644', '26767512', '30201138', '26277156', '30284141');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26935296', '花椒之味', '剧情', '夏如树（郑秀文饰）有一天突然得知父亲（钟镇涛饰）死讯，并由此发现原来自己在台北、重庆两地各有一个同父异母的妹妹如枝（赖雅妍饰）及如果（李晓峰饰）。来自三个不同地域、性格迥异的三姐妹，在父亲的葬礼上首次碰面，明明陌生却有着血缘的牵绊，同样面对着父母离异的创口与生活的惶惑；如树毅然决定继续经营父亲留下的火锅店，获得重新认识父亲的契机。三姐妹因上一代人的爱恨纠缠，在破碎家庭关系中成长，也因此相遇相知，互相依存，重拾修复关系的勇气，成长创口得以疗愈。', '郑秀文', '麦曦茵', 7.1, 42165, 'tt10551420', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2567382116.jpg', 0.6, 6.2, 42, 41.5, 9.6, '0.116206,-0.068547,-0.713298,0.624521,0.122183,-0.407252,0.758290,0.393371,-0.523548,-0.336848,0.226771,0.702582,-0.138281,0.414602,0.028415,-0.472533,0.086373,-0.850574,0.235089,-0.189396,-0.301838,-0.599347,-0.224839,0.031707,0.055052,-0.385060,0.871982,-0.000818,-0.185207,0.682684,0.061654,0.006504,-0.683128,0.372299,-0.266321,-0.091219,-0.315635,0.702316,-0.817628,-0.154765,-0.222742,0.117384,0.195915,-0.165609,-0.108408,0.539570,0.707584,-0.266542,-0.175869,-0.159222,0.341041,0.430904,-0.144290,0.048409,0.326949,0.045501,0.396545,0.554510,-0.253927,-0.159349,-0.134326,-0.035180,-0.597692,-0.017770,0.423355,0.129608,-0.568978,0.573158,0.261083,-0.494439,-0.100043,-0.285168,0.122696,0.755041,0.256413,0.663837,-0.367221,0.148249,-0.274316,-0.154561,0.874174,-0.104693,-0.129705,0.325358,-0.305814,-0.240436,-0.076818,-0.163049,-0.425686,0.070780,-0.035094,0.261789,-0.029457,0.350172,-0.717819,0.075921,-0.068168,0.181618,0.446629,-0.463445,0.469963,-0.528417,-0.336385,-0.416027,-0.455986,0.196531,0.198436,-0.545776,0.808862,-0.880109,0.172905,0.220500,0.542023,-0.770393,0.643527,0.489701,0.279152,-0.666610,-0.174199,0.771139,0.061401,-0.361319,-0.140840,-0.164666,-0.309738,0.393792,-0.444671,0.296471', '1293265', '25721544', '10876425', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26935675', '肉与灵', '剧情', '安德（格扎·莫桑伊 Géza Morcsányi 饰）在一家屠宰场担任着财务总监的职位，他没有朋友，没有恋人，每天独来独往，早已经习惯了这样孤单的生活。一天，安德的屠宰场里新来了一名质检员名叫玛利亚（亚历山德拉·博尔贝伊 Alexandra Borbély 饰），虽然安德自认为自己的性格已经足够内向了，但玛利亚比他还要“社恐”，她不仅有着交流障碍，还患有强迫症，对除了工作以外的人际交往避之而不及。随着时间的推移，玛利亚渐渐吸引了安德的注意，因为表面看似疏离的两人，共同保守着一个秘密——每天夜里，他们都会做同样的梦，这个秘密的存在渐渐拉近了他们之间的距离。©豆瓣', '亚历山德拉·博尔贝伊', '伊尔蒂科·茵叶蒂', 7.6, 16495, 'tt5607714', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2426269453.jpg', 0.7, 3.8, 30, 45.8, 19.7, '0.387355,-0.189440,-0.692650,0.667805,-0.230019,-0.109362,0.876187,0.391027,-0.523920,-0.658560,-0.072960,0.563156,-0.073723,0.018118,0.200721,-0.222580,-0.218876,-0.700150,-0.234456,-0.507967,-0.298217,-0.868005,-0.438018,-0.340955,-0.334004,-0.334312,0.445365,-0.052254,-0.074436,0.446813,0.202242,-0.024107,0.200511,0.715008,-0.373239,-0.262500,0.276122,-0.174530,0.019703,-0.063872,0.065534,-0.016463,0.138256,0.180401,0.099308,0.667667,0.467769,-0.247803,-0.313255,-0.059654,0.209231,-0.062025,0.118640,0.008882,0.607193,-0.189243,0.356083,0.230237,-0.314851,0.021024,-0.010803,-0.152685,-0.828524,0.224127,0.201088,0.340856,-0.547139,0.549946,0.048712,-0.218956,0.128134,-0.232463,0.304212,0.514316,0.276250,0.401108,-0.039402,-0.017745,-0.457290,-0.027039,0.744743,0.177044,-0.598970,0.827132,-0.543515,-0.198407,-0.320359,-0.203520,-0.576222,-0.137993,-0.012536,0.137409,-0.238409,0.339019,-0.544982,0.218440,0.159945,-0.178034,0.010096,-0.441669,0.084879,-0.628758,-0.184053,-0.936037,-0.424376,-0.000345,-0.138495,-0.155876,0.935926,-1.009799,0.361740,0.678605,0.310501,-0.529887,0.816975,0.290774,0.072629,-0.122935,0.072550,0.333074,-0.078842,0.180503,0.201322,0.495264,0.005819,-0.159095,-0.198322,0.764218', '1303112', '20277433', '24756472', '27185563');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26935777', '玛丽与魔女之花', '动画', '夏日的一天，红发女孩玛丽（杉咲花 配音）被送到阿姨夏洛特所在的乡间小屋度假。初来乍到，玛丽对周遭的一切还不那么适应，特别是调皮男孩彼得（神木隆之介 配音）有意和她对着干，令玛丽实在高兴不起来。偶然一次的林间探险，玛丽见到了传说中的魔法之花“夜间飞行”，还找到了一柄破扫帚。偏偏这把魔法扫帚载着玛丽飞上天空，来到了专门培养魔法师的恩德学园。在这个神奇的所在，玛丽受到曼布勒切克女士（天海佑希 配音）的殷勤接待，还邂逅了怪模怪样的D博士（小日向文世 配音）。虽然女孩懵懵懂懂成为了魔法学员，可是他很快发现了这里所隐藏的秘密……本片根据改编自玛丽·斯图尔特的英国儿童文学小说改编，是米林宏昌离开吉卜力工作室后制作拍摄的第一部动画长片。©豆瓣', '杉咲花', '米林宏昌', 6.2, 35856, 'tt6336356', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2521033758.jpg', 1.7, 14.1, 59.5, 19.9, 4.8, '0.291290,-0.145406,-0.413591,0.400999,0.092608,-0.181273,0.459742,-0.026360,-0.219507,-0.444340,0.305633,0.782426,-0.464213,0.269999,0.241184,0.543927,-0.561709,-0.269879,-0.127600,-0.140272,-0.154889,-0.447246,-0.149196,0.058197,-0.039508,-0.454298,0.393701,-0.129565,-0.212679,0.396539,0.005541,-0.003036,-0.113312,0.336187,-0.146967,0.177881,0.268602,-0.100585,0.081784,0.251703,0.032214,-0.291134,-0.073018,0.072178,0.140666,0.185326,0.691141,-0.370388,0.041834,-0.080993,0.452755,-0.409441,-0.033894,-0.057165,0.281867,-0.000258,0.134994,-0.228093,-0.201457,0.059680,-0.182851,-0.433983,-0.443920,0.150061,0.100241,0.193098,-0.620785,0.220018,-0.145063,-0.190717,0.260684,-0.403078,0.165078,-0.149580,0.215712,0.317109,-0.113810,0.119767,-0.358553,0.114662,0.420269,-0.086053,-0.194304,0.506509,-0.196255,-0.421394,-0.039233,0.143499,-0.588192,0.071327,0.384214,-0.096945,0.197013,-0.009338,-0.695016,0.031547,-0.229770,-0.265214,0.117261,-0.221599,-0.380472,-0.655250,0.069135,-0.203852,-0.230755,-0.309132,0.071924,-0.381437,0.625449,-0.855121,0.208268,0.532292,0.176505,0.026709,0.501469,-0.113391,-0.002638,-0.101716,-0.243666,0.139488,0.126028,0.528701,0.255479,0.557026,0.152756,-0.318717,-0.299165,0.409097', '1420088', '3044878', '3178770', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26936217', '一袋弹子', '剧情', '故事发生在第二次世界大战期间，法国被德军占领，纳粹主义在当地横行。莫里斯（巴蒂斯特·弗勒里埃尔 Batyste Fleurial 饰）和乔（多里安·勒·克利奇 Dorian Le Clech 饰）是一对生活在法国的犹太人兄弟，父亲靠经营一家理发店养活孩子们，虽然生活得很 辛苦，但是一家人之间的感情非常的亲密。德军要求每一个犹太人在外衣上缝上黄色的六角星，与此同时，社会对犹太人的忍耐度也在急剧下降，兄弟两人因为他们的血统在学校遭到了同学们的排挤。眼看着势头不对，父亲决定让莫里斯和乔两人先行逃往自由区避难，自己随后就跟上，一家人在尼斯汇合。就这样，两个孩子踏上了逃往的旅途。©豆瓣', '多里安·勒·克利奇', '克里斯丁·杜瓦', 8.3, 12834, 'tt5091612', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520545137.jpg', 0.3, 0.9, 14, 52, 32.8, '0.406723,-0.382377,-0.755994,0.498144,0.081857,-0.253210,0.676233,0.342605,-0.393188,-0.072835,0.111788,0.928052,-0.112899,0.075885,0.175460,-0.042597,-0.442184,-0.724576,-0.008773,-0.088293,-0.391713,-0.490386,0.050596,-0.349577,-0.244058,-0.398008,0.458092,0.131571,-0.086350,0.353724,0.000835,0.307838,-0.141297,0.265279,-0.461635,0.011639,0.159610,-0.008655,-0.286797,0.207773,-0.141129,-0.003405,-0.151398,0.044109,0.316839,0.153778,0.755397,-0.223319,-0.063309,0.052640,-0.090438,-0.461738,-0.121802,0.247736,0.448219,-0.244627,0.206938,0.330108,-0.247333,0.103172,0.040164,-0.169674,-0.509593,0.203238,0.085940,0.112477,-1.014615,0.823110,-0.026199,-0.134435,0.031371,-0.611934,0.091597,0.852926,-0.062835,0.544628,-0.139498,0.183655,-0.730746,-0.096636,0.919292,-0.086912,-0.122854,0.224209,-0.360437,-0.193582,-0.182179,-0.008332,-0.527860,-0.480378,0.240911,-0.312974,-0.132771,0.417628,-0.839418,0.102538,-0.112200,-0.371395,0.201641,-0.465020,0.102210,-0.682113,-0.143242,-0.706234,-0.396272,0.312703,0.061200,-0.045799,0.796439,-0.759134,0.099965,0.323053,0.502777,-0.543665,0.788160,0.248593,0.215103,-0.185073,0.066676,0.325939,0.303035,-0.001497,0.278505,0.416467,-0.022004,0.041930,-0.192241,0.532140', '1293303', '27060077', '30162520', '1305182');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26937474', '精灵宝可梦：就决定是你了', '动画', '小智（松本莉香 配音）来自真新镇，他的目标是要成为神奇宝贝顶级训练师。在即将展开训练师旅程的一天，因为迟到，他并没有拿到初始的小精灵。大木博士（石冢运昇 配音）见状，便送了一只不愿进精灵球和非常调皮的皮卡丘给这位失落的年轻人。于是，他们俩便踏上了精灵宝可梦的旅程。在旅途中，他们的之间的隔阂逐渐打破，并认识了同行的伙伴诚子（佐藤刊里 配音）与宗次（本乡奏多 配音），并听到了有关凤王的传说。“受到虹色之羽的引导，见到凤王的人，就会成为彩虹勇士...”本部剧场版是《神奇宝贝》动画系列的第二十部电影。该部电影的剧情是系列动画第一集《神奇宝贝！就决定是你了！》的改编，描述小智与皮卡丘踏上成为宝可梦大师的冒险之旅。', '松本梨香', '汤山邦彦', 7.9, 10386, 'tt6595896', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2509833353.jpg', 0.7, 3.6, 25.2, 41.6, 28.8, '0.118667,-0.184403,-0.430401,0.506872,0.117936,-0.246700,0.437541,-0.113438,-0.399093,-0.159570,0.231121,0.797132,-0.236548,0.062597,0.349340,0.134508,-0.237535,-0.480655,-0.149395,-0.154974,-0.060589,-0.265918,-0.144351,-0.103335,0.097886,-0.673594,1.017268,0.012477,-0.493627,0.462584,0.311685,0.017794,-0.243536,0.234432,-0.139907,0.181101,0.167746,0.162510,-0.182273,0.278471,-0.197525,0.088266,-0.012922,0.039323,0.187697,0.053051,0.701437,-0.484293,-0.136506,0.075095,0.387826,-0.312468,-0.095161,-0.271019,0.265261,0.217123,0.162120,0.139924,0.074192,0.252686,-0.257120,-0.374600,-0.848438,0.128138,0.078682,0.206202,-0.487925,0.339078,0.013620,-0.099443,0.447017,-0.392257,0.285423,0.107370,0.522613,0.328541,0.027637,0.023105,-0.007114,0.439348,0.506932,-0.184890,-0.212773,0.499512,-0.063595,-0.680704,-0.286440,-0.138153,-0.326973,0.218450,0.379843,0.258683,0.058400,0.215560,-0.773350,0.077471,-0.018001,-0.457595,0.217015,-0.372447,0.266736,-0.738757,0.249540,-0.240931,-0.314460,0.045312,0.223156,-0.462185,1.032571,-0.970190,0.208766,0.578480,0.148053,-0.298253,0.664187,-0.046839,-0.141402,-0.292487,0.235358,0.002157,-0.081385,0.352178,0.215346,0.393629,0.243205,-0.245945,-0.492907,0.393757', '25880986', '27602116', '10174444', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26937563', '惊涛飓浪', '爱情', '塔米（谢琳·伍德蕾 Shailene Woodley 饰）和未婚夫理查德（山姆·克拉弗林 Sam Claflin 饰）都非常热爱极限运动，两人正驾驶着帆艇，准备完成横渡太平洋的宏伟任务。让两人没有想到的是，在途中，他们遭遇了飓风袭击，猛烈的风暴破坏了帆艇，还导致理查德身受重伤。在理查德的不断鼓励和支持下，塔米决定振作起来，利用两人全部的野外生存知识进行自救。海上的生存环境极为的恶劣，不仅没吃没喝，理查德的伤也继续药物的治疗。在这样紧急的情况下，塔米还必须驾驶着已经损坏的帆艇驶往陆地。如果继续这样随波逐流下去，那么他们将会顺着洋流漂流进空无一人的太平洋。©豆瓣', '山姆·克拉弗林', '巴塔萨·科马库', 6.7, 14743, 'tt6306064', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2541197052.jpg', 0.4, 8.4, 54.7, 30.7, 5.8, '0.156054,-0.059783,-0.927723,0.629581,0.060893,-0.238884,0.719353,0.093434,-0.227406,-0.070653,0.320058,0.525933,0.052013,-0.249323,0.320316,-0.144866,-0.692296,-0.334908,-0.086542,0.251750,-0.550072,-0.700367,-0.365169,-0.090567,-0.049457,-0.372478,0.552563,0.061543,-0.367651,0.294371,-0.094361,0.079491,0.015923,0.841257,-0.349127,0.100238,-0.271396,-0.064320,-0.193693,0.424385,0.272397,-0.266591,-0.007405,0.147238,0.316480,0.410843,0.622366,-0.388561,-0.102269,-0.073396,-0.029706,-0.522496,0.260301,0.123103,0.363428,-0.167714,0.097665,-0.073117,-0.194453,0.057218,0.179045,0.093854,-0.666850,-0.110314,-0.128935,0.116103,-0.677513,0.292439,-0.079977,-0.144994,-0.006951,-0.423969,0.074385,0.616855,0.268009,0.302624,-0.306865,-0.020937,-0.585165,-0.014004,0.770037,0.055356,-0.156556,0.190837,-0.137985,-0.339769,-0.082504,-0.309556,-0.363302,-0.421261,0.274104,0.366756,-0.213356,0.245554,-0.501665,0.346303,-0.326932,-0.666946,-0.264376,-0.292679,0.077247,-1.076906,0.313153,-0.250784,-0.151971,0.265735,0.031589,-0.368043,0.502553,-0.594135,0.312182,0.559143,0.410452,-0.248685,0.270790,0.218672,0.199867,0.140108,-0.118458,0.159924,-0.107455,0.607781,0.440320,0.600763,0.281140,-0.085278,-0.221724,0.448022', '3178770', '3735015', '2079017', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26939444', '死亡半径', '科幻', '利亚姆从车祸中醒来，却不记得他是谁。当他走进小镇寻求帮助时，他发现只有死人，所有的人都有着奇怪苍白的眼睛。利亚姆的第一感应是，一种病毒出现在空气中。但他很快就发现了可怕的真相：“任何一个在离他50英尺半径范围内的人都会立刻死亡。”', '迪亚哥·克莱特霍夫', '卡罗琳·拉布里奇', 6.4, 7622, 'tt6097798', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2506346623.jpg', 2, 12.1, 54.7, 24.6, 6.5, '0.266989,0.177199,-1.248519,0.337469,-0.272740,0.237562,1.169052,-0.316391,-0.644963,-0.471129,0.251846,0.961217,-0.325438,0.256720,-0.147327,0.375203,0.003975,-0.710789,-0.295286,-0.495107,-0.783620,-0.374005,-0.445836,-0.500057,0.104506,-0.413223,0.422656,0.457725,-0.389729,0.081132,-0.053795,0.036277,0.006438,1.207038,-0.344484,-0.015411,-0.033593,-0.333253,0.424141,0.272886,-0.049803,-0.347739,-0.229553,0.347818,-0.362306,0.557336,0.601010,-0.271037,-0.619937,0.329175,0.367651,-0.293410,-0.205718,0.208437,0.206972,-0.419180,0.170403,0.032369,-0.180666,0.049685,-0.138643,0.242003,-0.794590,0.123452,-0.122215,0.663984,-0.465623,0.286247,-0.193297,-0.445106,0.401541,-0.112824,0.426886,0.298836,-0.081290,0.363810,-0.518810,-0.042405,-0.817644,-0.336776,0.814933,-0.133627,-0.763859,0.444568,-0.310485,-0.608247,-0.306798,0.206925,-0.284361,0.118873,0.258303,0.542658,-0.297462,0.209845,-0.352357,0.170417,-0.174307,-0.229112,-0.138338,-0.278192,-0.412423,-0.323940,-0.296410,-0.473206,-0.564823,0.297674,-0.207941,-0.437610,0.489335,-0.847938,0.441206,0.588699,0.275338,-0.127775,0.918790,-0.213836,-0.200074,-0.128212,-0.075176,0.398895,0.149276,0.646185,0.041141,0.477673,0.195587,-0.092710,-0.298925,0.619562', '1292064', '10733357', '27617348', '35073565');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26942631', '起跑线', '剧情', '一对印度的中产阶级夫妇:服装店老板拉吉（伊尔凡·可汗 Irrfan Khan 饰）与太太米塔（萨巴·卡玛尔 Saba Qamar 饰）为了让女儿皮娅（蒂希塔·塞加尔 Dishita Sehgal 饰）接受更好的教育想尽了各种办法。而当他们费劲心思终于要将女儿送进名校时,事情却又发生了意想不到的变化……', '伊尔凡·可汗', '萨基特·乔杜里', 7.9, 204089, 'tt5764096', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2517518428.jpg', 0.3, 1.8, 23.5, 53, 21.6, '0.300433,-0.117732,-0.339549,0.421974,0.171474,-0.772061,0.566526,0.328466,-0.511899,-0.421686,-0.055935,0.451237,-0.078525,-0.074764,0.483973,0.299016,-0.877343,-0.632512,0.538514,-0.274972,-0.049338,-0.468721,-0.129464,-0.326784,0.033895,-0.216973,0.116288,-0.026613,0.216758,0.369319,0.473581,0.345418,0.077401,0.271544,-0.078631,-0.015199,0.019823,0.151842,-0.400740,-0.024867,0.282433,-0.066665,-0.338466,0.446078,0.322394,0.223138,0.509059,-0.443563,0.238298,-0.154217,-0.052811,-0.002196,0.223641,0.443376,-0.114638,-0.241534,0.367763,0.192918,-0.314668,-0.026173,0.334195,0.065179,-0.463300,0.288868,0.235862,-0.126416,-0.779545,-0.146362,-0.179521,-0.188932,0.133899,-0.461507,0.153745,0.415505,0.233767,0.371368,-0.372656,-0.013260,-0.515398,-0.171297,0.501021,-0.331994,0.129588,0.183948,-0.299959,-0.561569,0.175464,-0.283713,-0.283580,0.187700,0.405233,0.069220,0.167021,0.113495,-0.521650,-0.427644,-0.528718,-0.330050,0.121500,-0.344723,0.249828,-0.221330,0.156789,-0.154969,-0.360217,-0.159601,0.330155,0.107359,0.527809,-0.441949,0.056918,0.422497,0.187838,-0.776377,0.514857,-0.108564,0.313290,-0.390353,-0.447381,-0.257261,-0.166400,0.342155,-0.028119,0.350746,0.316992,-0.380014,0.217911,0.372625', '2005723', '1947719', '1292067', '1302110');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26942645', '厕所英雄', '剧情', '家里经营自行车行的科沙夫（阿克谢·库玛尔 Akshay Kumar 饰）是一个大龄单身青年，他的老板专横独大，出于迷信要求儿子必须娶一个一只手上有两根拇指的妻子，而为了所谓的黄道吉日还专门安排科沙夫娶了一头母牛为妻。科沙夫虽然唯唯诺诺，可是无时无刻不期待美好爱情的出现。偶然机缘，他邂逅了婆罗门出身的知识女性贾娅（布米·佩德卡尔 Bhumi Pednekar 饰）。最初的龃龉和误会过后，这对身份地位和生活背景都有着巨大差异的男女越走越近，最终喜结连理。然而好景不长，新婚次日贾娅就发现一个严重问题。出于宗教信仰，科沙夫的家里根本没有厕所，包括女性在内必须要去很远的野外解决问题。为了自己的合法权益，贾娅和丈夫以及其家人展开了旷日持久的战争……©豆瓣', '阿克谢·库玛尔', '什里·那拉扬·辛', 7.1, 98498, 'tt5785170', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2523632248.jpg', 0.8, 5.6, 42.5, 39.8, 11.3, '0.324390,-0.034507,-0.617066,0.593906,-0.125662,-0.126031,0.670247,0.219372,-0.308742,-0.558866,-0.014079,0.731363,0.085448,-0.008141,0.214594,0.095193,-0.161284,-0.344615,-0.014723,-0.078243,-0.319831,-0.450149,-0.201531,-0.198879,-0.313321,-0.045559,0.426407,-0.080095,-0.154562,0.464092,0.461066,0.228434,0.057698,0.402512,-0.396045,-0.184683,0.013260,0.255166,-0.265035,0.067014,0.033946,0.035368,0.080115,0.069138,-0.139637,0.381878,0.351153,-0.173667,-0.215547,-0.282365,0.297148,-0.134922,-0.070336,0.192912,0.437173,-0.147004,0.281985,0.243465,-0.027622,-0.067790,0.181250,-0.289381,-0.659388,-0.111911,0.287024,0.049985,-0.643892,0.500927,0.122434,-0.327602,0.153200,-0.183359,0.144611,0.408020,0.202689,0.265704,-0.207680,0.040151,-0.622658,0.154699,0.539965,0.128324,-0.156567,0.383584,-0.486668,-0.562746,0.065022,-0.191225,-0.553087,0.000986,0.050911,0.201626,-0.244466,0.072897,-0.376821,0.110794,-0.082384,-0.011318,0.128868,-0.621011,0.076015,-0.196685,-0.177704,-0.722956,-0.435659,-0.025709,0.203064,-0.223314,0.751126,-0.699693,0.146325,0.394157,0.418542,-0.689390,0.799633,0.518057,0.303882,-0.373330,-0.191323,0.092087,-0.223780,-0.053371,-0.265021,0.166864,0.124116,-0.231947,-0.065116,0.492218', '1456503', '1303112', '1917323', '1301465');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26942674', '神秘巨星', '剧情', '少女伊西亚（塞伊拉·沃西 Zaira Wasim 饰）拥有着一副天生的好嗓子，对唱歌充满了热爱的她做梦都想成为一名歌星。然而，伊西亚生活在一个不自由的家庭之中，母亲娜吉玛（梅·维贾 Meher Vij 饰）常常遭到性格爆裂独断专横的父亲法鲁克（拉杰·阿晶 Raj Arjun 饰）的拳脚相向，伊西亚知道，想让父亲支持自己的音乐梦想是完全不可能的事情。某日，母亲卖掉了金项链给伊西亚买了一台电脑，很快，伊西亚便发现，虽然无法再现实里实现梦想，但是网络中存在着更广阔的舞台。伊西亚录制了一段蒙着脸自弹自唱的视屏上传到了优兔网上，没想到收获了异常热烈的反响，著名音乐人夏克提（阿米尔·汗 Aamir Khan 饰）亦向她抛出了橄榄枝。©豆瓣', '塞伊拉·沃西', '阿德瓦·香登', 7.7, 399685, 'tt6108090', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2508925590.jpg', 0.7, 3.7, 27.5, 44.4, 23.6, '0.085957,0.385399,-0.607187,0.739632,0.076517,-0.193898,0.582497,-0.019208,0.095892,-0.101704,-0.316125,0.850973,-0.346933,0.335032,0.127037,0.233281,-0.651691,-0.682074,-0.082436,-0.054397,-0.223083,-0.516694,0.070309,-0.484367,0.046205,-0.376574,0.553963,0.059703,-0.362283,0.181196,0.388992,0.273411,-0.001871,0.615687,0.152440,0.126320,0.255984,-0.021819,-0.037558,0.413554,-0.099186,-0.070110,0.213734,0.771324,0.083790,0.193971,0.602144,-0.678599,0.234801,-0.053426,0.403342,0.015561,0.080151,-0.033771,0.117099,0.119283,0.179575,0.035355,-0.340666,0.018465,0.172280,-0.360269,-0.550840,-0.088789,0.080314,0.276851,-0.447249,0.329942,-0.281808,-0.349203,0.003065,-0.022421,0.317583,0.189300,0.508332,0.300770,-0.004485,0.153270,-0.543809,-0.060055,0.371281,0.071521,0.016552,0.638039,-0.640938,-0.540428,-0.076842,-0.178461,-0.396136,-0.315068,0.177647,-0.163736,0.009483,0.210273,-0.438560,0.082278,-0.297865,-0.174486,-0.263392,-0.577529,-0.146668,-0.061843,0.098658,-0.585941,-0.439867,-0.137555,0.110821,-0.335150,0.715755,-0.787761,0.106891,0.514753,0.517273,-0.021678,0.526717,-0.021713,-0.153070,-0.070642,-0.165081,0.595403,0.050119,0.074660,0.346339,0.262577,0.093502,-0.417880,-0.321731,0.930706', '3882427', '24756472', '1870681', '3001472');
