INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26944076', '泡芙小姐', '剧情', '影片讲述了一对身份天差地别的姐弟恋情侣甜蜜又热辣的爱情故事。海归泡芙（张歆艺 饰）在闺蜜Party上邂逅了外卖小哥顾上（王栎鑫 饰），在混乱中两人逃离现实，共同度过了奇妙的一夜。随后大胆果敢的泡芙对好学生顾上展开了疯狂的追求，短暂接触后，二人秘密闪婚，开始了一场惊险刺激的童话冒险。', '张歆艺', '张歆艺', 3.6, 9241, 'tt8002356', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2508918510.jpg', 50.8, 27.4, 16.6, 2.8, 2.4, '0.700596,0.109836,-0.508896,0.422016,0.419558,0.008965,0.876322,0.116022,-0.500578,0.145906,0.478352,0.431388,-0.593856,0.042320,0.607634,0.123790,-0.481890,-0.840124,0.149425,-0.108667,-0.152224,-0.429283,-0.205069,0.059683,-0.024109,-0.265586,0.306494,-0.243448,-0.007245,0.774435,0.424781,-0.387880,-0.424335,0.291520,0.043692,0.239461,0.304947,0.414011,-0.717297,0.179172,0.094910,-0.220787,-0.105947,0.085696,-0.089439,0.123193,0.869155,-0.227092,-0.144366,0.207983,0.489763,0.080000,-0.318417,0.098833,0.014551,0.064109,0.549826,0.023754,-0.110461,0.210911,-0.092721,0.008492,-0.254598,0.375097,0.223293,-0.122359,-0.379718,0.666570,0.236641,-0.172875,0.224002,-0.060858,-0.219085,0.297810,0.541522,0.552575,0.135927,0.175203,-0.000903,0.567098,0.704070,0.145059,-0.229787,0.828860,-0.073146,-0.331128,-0.260300,-0.043378,-0.518484,-0.070550,0.480381,-0.072857,-0.176054,0.546607,-1.120737,0.295287,-0.236318,0.098211,0.124500,-0.185393,-0.222698,-0.589841,-0.476630,-0.317868,-0.508440,-0.112240,-0.044891,-0.176828,0.803097,-0.766493,-0.147138,0.511141,-0.090174,-0.197462,0.487227,0.215965,-0.014173,-0.203375,0.134598,0.321957,-0.296193,0.053839,0.289743,0.706321,-0.491260,0.467529,-0.564762,0.267435', '3041753', '5977789', '1292050', '1394176');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26944582', '雪怪大冒险', '喜剧', '《雪怪大冒险》是一部囊括巨星阵容及美妙原创音乐的全年龄段冒险动画片。当一只年轻活泼的雪人发现了之前本认为不存在的人类，大脚怪传奇自此乱了套。影片讲述了一个关乎友情、勇气与探索之趣的动人故事。关于人类这个“小脚怪”的消息让原本单纯的雪人族群陷入了骚乱之中，他们开始好奇，在雪村之外，究竟存在着一个怎样的世界？', '查宁·塔图姆', '凯瑞·柯克帕特里克', 7.3, 28372, 'tt6182908', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2535550507.jpg', 0.3, 3.2, 39.6, 44.7, 12.2, '0.519463,0.336895,-0.677623,0.642702,-0.002344,0.303602,0.699401,-0.227471,-0.488321,-0.267813,-0.054782,0.679327,-0.139241,0.047308,0.063481,-0.166886,-0.098826,-0.442497,-0.176254,-0.217461,-0.174376,-0.374574,-0.547633,-0.268661,0.110516,-0.420702,0.686481,0.203541,-0.644245,0.356176,0.232907,-0.087487,-0.414257,-0.047897,0.109317,-0.066979,0.283567,0.278673,-0.127008,0.163235,-0.413664,0.027906,-0.085188,0.300544,-0.559508,0.053530,0.797748,-0.682552,-0.235099,-0.075671,0.571438,0.009579,-0.201835,0.015921,0.213680,-0.185209,0.216586,0.053790,0.281082,0.196178,0.084212,-0.247647,-0.981204,-0.056217,0.121469,0.505299,-0.192784,0.237829,0.170840,-0.146323,0.134461,-0.037330,0.312549,0.158522,0.615608,0.520029,0.086382,0.246722,-0.344265,0.320264,0.668088,0.118670,-0.438595,0.415877,-0.156902,-0.577233,-0.452373,-0.373468,-0.563368,0.155188,0.165882,0.069911,-0.220818,0.327143,-0.784069,0.297502,0.280290,-0.277900,-0.198221,-0.485844,-0.302288,-0.258638,-0.301312,-0.256700,-0.121016,-0.135330,0.055880,-0.406982,1.279037,-0.666662,0.063506,0.666860,-0.038832,-0.551102,0.827608,0.059954,0.020994,-0.195752,-0.021010,0.380796,-0.096562,-0.169328,-0.071023,0.125141,-0.198231,-0.247227,-0.667255,0.485159', '24284209', '27602116', '4181031', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26945085', '昆池岩', '恐怖', '原名南营神经精神医院的昆池岩精神病院，最早建立于20世纪60年代。在特殊的时代它曾经历了无比的辉煌，然而更为人熟知的则是该医院身上所发生的各类恐怖事件。现如今，早已废弃的昆池岩医院被CNN票选为全球七大恐怖之地之一，更由此吸引无数寻求刺激的青年男女来此探险。三个月前，两名青少年来此探险，结果在直播中遭遇诡异事件，下落不明。此后，《恐怖世代》剧组在魏河俊的召集下，网罗了吴雅妍、朴智贤、夏洛特（文艺媛 饰）、李丞旭、朴成勋、刘帝允等人前往昆池岩，更试图打开备受诅咒的402室。夜幕降临，全球网友一道观看这场恐怖盛宴……©豆瓣', '魏嘏隽', '郑范识', 6.2, 180341, 'tt8119752', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2513360824.jpg', 4.3, 17.1, 48.4, 22.9, 7.3, '0.153627,0.122246,-0.597430,0.349619,0.436325,0.262646,0.475620,-0.076653,-0.768815,-0.301946,0.190776,0.465925,-0.509495,0.292993,0.445052,-0.338533,-0.095168,-0.456436,-0.549954,-0.338688,-0.432791,-0.034799,-0.289250,-0.006628,0.033114,-0.347514,0.604158,0.287098,-0.215859,0.270862,0.253833,0.658801,-0.423868,0.257488,-0.133666,-0.209816,0.222873,0.113516,-0.258989,-0.000908,-0.158685,-0.535145,-0.191328,0.233889,-0.049967,-0.153726,0.606546,-0.151208,-0.196793,-0.477084,0.601306,0.028370,-0.291367,-0.119363,0.574135,0.271257,0.494012,0.299179,0.091826,0.056614,-0.034316,-0.190386,-0.716702,0.194015,0.375194,0.015133,-0.278025,0.231543,-0.017494,0.014454,0.057893,-0.173311,0.334255,0.543358,0.184489,0.321666,0.114487,-0.191166,-0.055810,0.419042,0.890460,-0.276172,-0.345753,0.050067,-0.246929,-0.263288,0.006843,-0.247910,-0.296136,0.211686,0.222821,0.160001,-0.112483,0.405396,-0.438728,0.173041,-0.131301,-0.364860,0.007884,-0.019465,-0.287317,-1.084904,-0.209092,-0.019640,0.142622,0.238887,0.141460,-0.056527,0.635710,-0.569847,0.331592,0.332173,0.181292,-0.459042,0.574352,-0.245556,0.203047,-0.007834,-0.277453,0.347969,-0.018210,0.379366,-0.343808,0.292049,-0.303283,-0.214621,-0.463662,0.239849', '2369613', '24751811', '3318306', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26945122', '麻药王', '剧情', '《麻药王》以上世纪70年代的韩国釜山为背景，讲述了宋康昊饰演的李头森从一个毫无底线的走私犯崛起为传奇毒枭的故事。故事原型是上世纪70年代靠走私起家，后跻身毒品制造和贩卖行业并崛起的一代毒枭，导演表示，李头森虽然是虚构人物，但是利用实际存在过的大毒枭作为原型，经过几年的资料调查才完成了剧本。', '宋康昊', '禹民镐', 6, 12953, 'tt6914542', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2539781943.jpg', 2.9, 22.1, 52.8, 16.2, 5.9, '0.018037,0.149243,-0.252586,0.681060,-0.092530,0.094982,0.385267,-0.396529,-0.821377,-0.600786,0.064462,0.881001,-0.162267,-0.073087,0.054994,-0.164789,-0.290684,-0.620779,-0.030423,-0.249073,-0.206638,-0.553100,-0.688646,-0.102145,-0.232625,-0.301606,0.977899,0.141177,-0.781801,-0.024288,0.075853,0.106651,-0.108037,0.032806,-0.255236,-0.287987,0.280977,0.224906,-0.503628,0.307750,-0.268968,-0.488485,0.089559,-0.121929,-0.029186,0.481096,0.251184,-0.244062,-0.018085,-0.218336,0.683331,-0.365591,-0.598821,-0.506979,0.677146,0.211028,0.369593,0.637106,0.314713,-0.308616,-0.036287,-0.428756,-1.339476,-0.352642,0.347373,0.089116,-0.887683,0.217961,-0.200784,-0.099232,-0.201595,-0.201347,0.445845,0.315473,0.761705,0.415578,0.049474,0.459208,-0.538686,0.708367,0.497520,0.145654,-0.386964,0.439028,0.180647,-0.912239,-0.393006,-0.590619,-0.022331,0.232102,-0.144775,-0.099099,-0.184240,0.269693,-0.563069,0.002599,-0.267476,-0.452497,0.519918,-0.259408,-0.225006,-0.650708,-0.510327,-0.405868,0.068114,-0.115563,0.494521,-0.565354,0.920232,-0.618714,-0.047739,0.383585,0.158437,-0.554348,0.656534,-0.015377,-0.131480,-0.646904,-0.074311,0.193258,-0.007768,-0.020968,-0.293853,0.107558,-0.229094,-0.693578,-0.083545,0.576656', '27602116', '27098364', '6844861', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26945132', '一定要抓住', '惊悚', '电影讲述了追踪未结案事件凶手的故事。杀人案再次发生，犯罪手法竟然与30年前一起未结案事件一模一样。非常了解小区的老人和非常了解事件的前职刑 警用直觉与感觉开始追踪凶手....', '白润植', '金泓善', 6.9, 7885, 'tt8088944', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2503047561.jpg', 0.9, 7, 49.3, 33, 9.7, '0.276390,-0.667742,-0.437257,0.680001,0.436226,0.470763,0.830532,-0.408987,-0.924527,-1.226808,0.026579,0.514930,-0.497370,-0.224316,0.320566,-0.425155,-0.712971,-0.658041,-0.220855,-0.183383,-0.559652,-0.931194,-0.305775,0.013429,-0.020281,-0.004980,0.506444,0.194707,-0.837652,0.788959,-0.125645,0.787183,-0.713789,0.376978,-0.282326,-0.348503,0.281641,0.430191,-0.691402,0.110602,0.483318,-0.210191,0.486612,0.235525,-0.116913,0.269167,0.909763,-0.586914,-0.742386,-0.258144,0.497029,0.053553,-0.069511,0.202952,0.749227,0.664808,0.948082,0.881015,-0.070513,-0.873001,-0.182758,-0.014958,-0.667932,0.369502,0.250973,0.229271,0.026781,-0.652449,-0.669783,0.665576,0.288078,-0.252503,0.470146,0.556608,1.157346,0.285381,0.099208,-0.352998,-0.736706,-0.343024,0.766170,-0.093048,0.152478,0.909948,0.135446,-0.748259,-0.466723,0.183962,0.481365,0.917706,-0.216097,0.280437,-0.563637,0.620773,0.024866,-0.274346,-0.169473,0.132892,0.157392,-0.136995,-0.630651,-0.897096,-0.654780,-0.194758,-0.729728,-0.286180,-0.306436,-0.351641,0.044813,-0.724120,-0.056086,0.421565,-0.079831,-0.588684,0.676215,0.161702,-0.284896,-0.650991,-0.115579,0.043350,0.044454,0.274535,0.182201,0.358267,-0.118766,-0.704427,-0.395322,0.450361', '26391916', '1309145', '27031237', '26850330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26946450', '最终幻想女孩', '爱情', '来自雪国的年轻女孩江藤良香（松冈茉优 饰）独自在东京打拼，至今从未谈过恋爱的她日常喜欢灭绝动物，关于爱情她念念不忘的是学生时代的帅气男孩阿一（北村匠海 饰）。她将心中所爱所想说给身边的检票员、超市收银员、钓鱼大叔、公交乘客，看起来是那么开朗无忧。在一次公司聚会上，看起来十分不靠谱的男生阿二（渡边大知 饰）主动搭话，之后更向其表白。良香敷衍着这个神经兮兮的男生，心中一直放不下阿一。于是，她鼓起勇气，以其他同学的名义策划了同学聚会。经过一番努力，同学会如期召开，良香朝思暮想的阿一也终于到会，只不过随后的发展却事与愿违……本片根据绵矢莉莎的小说改编。©豆瓣', '松冈茉优', '大九明子', 7.4, 17230, 'tt6782708', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2497090967.jpg', 1, 5.4, 35, 41.7, 16.9, '0.286951,-0.002274,-0.439918,0.537202,-0.117476,-0.381980,0.563256,-0.056284,-0.557109,-0.171333,0.247839,0.550930,-0.224235,0.520166,0.350398,0.046900,-0.357300,-0.515287,-0.139107,-0.060024,-0.112463,-0.363790,-0.048624,0.013874,-0.255717,-0.132752,0.523254,-0.080698,0.004094,0.330640,0.481360,0.031048,0.054388,0.441288,-0.223013,-0.097212,-0.052297,0.171496,-0.132668,0.067800,0.037099,-0.225008,-0.399468,0.221843,0.041036,0.269562,0.556970,0.004611,-0.269431,-0.015199,0.515592,0.100061,-0.048613,-0.109039,0.309804,0.166486,0.366093,0.040422,0.041038,-0.056639,0.056142,-0.060714,-0.218636,0.068765,0.145696,0.293802,-0.501598,0.343264,-0.074636,0.103638,0.178720,-0.538137,-0.171442,0.250981,0.423794,0.173717,-0.095883,0.174436,-0.155865,0.393971,0.586814,0.307203,-0.091366,0.450231,-0.289351,-0.323162,-0.000998,-0.040263,-0.611015,0.139747,-0.024653,-0.069326,-0.200388,0.117516,-0.573157,0.053961,0.060335,-0.028635,0.239367,-0.393592,-0.105440,-0.533968,-0.034353,-0.453432,-0.226877,-0.145465,0.115013,-0.282373,0.829794,-0.991744,-0.024215,0.680572,0.331174,-0.333977,0.476828,0.147517,-0.279735,-0.338648,-0.121634,0.335230,-0.160354,0.301869,-0.209658,0.436882,0.092499,-0.296238,-0.479364,0.429739', '25922902', '1292219', '1316589', '3445516');
