INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26946600', '甲铁城的卡巴内瑞：海门决战', '剧情', '全世界被产业革命的波澜推动，自近世变迁至近代之时，不死的怪物突然出现。被钢铁的皮膜包覆，只要心脏不被破坏就不会消灭，被它啃咬的人似乎也会在死过一次之后复生，并开始袭击人类。之后被称为卡巴内的这些怪物爆发性地增殖，并覆盖了全世界。在远东岛国日本，与卡巴内的威胁对抗，并在穿越前线、被厚重装甲覆盖的蒸汽机车（通称骏城）之一的甲铁城上生还的生驹等人，在卡巴内与人的攻防战地、面向日本海的废弃驿“海门”，与玄路、虎落、海门的人民组成“联合军”，谋划着击退卡巴内的策略。此时，生驹发现海门一带的卡巴内拥有受到统领、集团行动的特征。生驹将此事报告给联合军，但却不被理会，反而因为自己是卡巴内利的缘故而遭到联合军的虐待。因愤怒而失去冷静的生驹决定独自深入敌境。另一方面，无名开始对一直以来支持着自己的生驹产生了与之前有所不同的感情。但就在此时，她得知了生驹打算独自深入敌境的消息——。与新的卡巴内的战斗，以及无名和生驹的命运将会——！？', '畠中祐', '荒木哲郎', 7.3, 6043, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2550293795.jpg', 1.3, 6, 37.5, 37.5, 17.7, '0.450774,0.126993,-1.011132,0.566945,0.143909,-0.045128,0.808797,0.124711,-0.585374,-0.125217,0.123923,0.658736,-0.064551,-0.007168,0.010958,0.013395,-0.093802,-0.793373,-0.215788,-0.081575,-0.283924,-0.341672,-0.272141,-0.173780,-0.130441,-0.405667,0.758095,0.263367,-0.498952,0.446731,-0.029993,0.520969,0.039090,0.772357,0.028935,-0.076643,-0.142085,-0.279684,0.051381,0.357813,-0.054687,-0.280477,0.158153,0.432841,-0.289329,0.487807,0.705243,-0.786027,-0.009044,-0.437275,-0.050831,-0.547377,0.050990,0.426215,0.515365,0.071500,0.176150,0.445745,-0.410688,0.162077,-0.017500,-0.071839,-0.749362,-0.098874,0.064631,0.213930,-0.670410,0.543934,-0.066111,-0.223419,-0.083135,-0.348034,0.352644,0.560958,0.289867,0.397366,-0.403784,-0.021941,-0.525358,-0.261509,0.840140,-0.260242,-0.373010,-0.067707,0.090811,-0.546774,-0.234622,-0.525448,-0.265888,-0.195505,0.178850,0.492332,-0.099071,0.397878,-0.838656,0.237042,-0.450069,-0.437621,-0.141002,-0.281252,-0.134425,-0.538889,-0.076171,-0.434175,-0.151567,0.389649,0.156534,-0.074325,0.519247,-0.958880,0.178803,0.354861,0.497521,-0.536785,0.468595,0.145296,0.112312,0.096545,-0.085211,0.235805,0.281977,0.682824,0.244498,0.314039,0.041210,-0.330996,-0.39095