INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26949264', '深海越狱', '动作', '中情局特工维勒（尚格·云顿 饰）与美女搭档梅尔在保护一份机密文件的任务中被神秘组织追杀，梅尔牺牲，维勒被逮捕。醒来时维勒发现自己被囚禁在一艘核潜艇内，这里是CIA设在深海的一座与世隔绝的黑狱，他自己也变成了出卖国家机密的叛徒身份。 除了拷打维勒的探员帕特里克，潜艇上还有维勒的恩师爱德华、女见习生凯茜和被关押的德国特工马可（杜夫·龙格尔 饰），他们当中谁是盟友，谁是敌人？有人对维勒手中的机密文件感兴趣，有人却对离开深海恢复自由更感兴趣。维勒必须寻找队友，携手逃出生天，并自证清白……', '尚格·云顿', '帕夏·帕特里基', 4.2, 10390, 'tt5622412', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2521514516.jpg', 23.6, 47.1, 25.1, 2.5, 1.8, '0.246029,-0.310358,-0.584095,0.471125,-0.328647,-0.193368,0.919550,-0.152850,-0.677431,-0.144925,0.257182,0.854486,0.121386,-0.083399,0.165651,0.447460,-0.561708,-0.689135,-0.089811,-0.366557,-0.201414,-0.758933,-0.614832,-0.152837,-0.110908,-0.344742,0.499239,0.071613,-0.317395,0.057316,0.214687,0.359322,-0.331505,0.324699,-0.060761,-0.191552,0.502914,-0.377827,-0.157181,0.233755,-0.408364,-0.170976,0.072166,0.076943,0.003347,0.418823,0.278292,-0.300880,-0.016658,-0.321982,0.033504,-0.610769,0.096109,0.150401,0.389784,-0.256259,-0.047177,0.247357,-0.234336,-0.003030,-0.039334,-0.179964,-0.691314,-0.130273,0.189211,0.234046,-0.354641,0.268482,-0.476528,0.061375,0.086586,-0.131931,0.256119,0.085268,0.102459,0.200401,0.004068,0.142291,-0.685060,-0.263164,0.544218,-0.235406,-0.043968,-0.170015,0.133553,-0.553461,-0.000135,-0.155434,-0.371848,-0.029971,0.246324,-0.039707,0.089519,0.219609,-0.557928,0.081572,-0.728787,-0.123618,-0.341407,-0.257730,-0.113687,-0.675098,0.025349,-0.110430,-0.259222,0.006396,0.042538,-0.276185,0.433769,-0.712083,0.335578,0.695684,0.488075,-0.318802,0.483394,0.058497,0.324884,-0.249271,-0.144246,0.338976,0.674722,0.311744,0.021555,0.063664,0.155617,-0.081754,-0.089939,0.090367', '1293145', '4132395', '1307442', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26949852', '徐福', '剧情', '濒临死亡的前情报局特工闵基宪（孔刘 饰），偶然遇见拥有人类不死秘密的「永生人」徐福（朴宝剑 饰），闵基宪的最后一场任务是誓死守护徐福到安全之地，途中想占有永生人的庞大财团与各方恶势力展开大规模猎杀，让他们的逃亡过程卷入惊天动地的危险局面....', '孔刘', '李勇周', 5.9, 23058, 'tt13316722', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2625736779.jpg', 4.1, 23.4, 52, 14.5, 6.1, '-0.509392,0.371705,-0.885510,0.445037,0.239752,0.532924,0.554610,-0.146780,-0.710086,-0.174729,0.280082,0.546392,0.162172,-0.212221,0.358298,-0.284877,0.040344,-0.491919,-0.219968,0.251683,-0.748271,0.046211,-0.295767,-0.839586,-0.071099,-0.256214,0.811703,0.901102,-0.637154,-0.029158,0.129787,0.694808,-0.626548,0.535322,-0.004902,-0.207843,0.203406,0.121394,-0.555956,0.214000,-0.174929,-0.283838,-0.220411,0.320752,0.074072,-0.000748,0.379182,-0.377880,-0.067337,-0.390465,0.013872,-0.529795,-0.136377,-0.128035,0.443458,-0.165658,0.119519,-0.041583,-0.059696,-0.130412,0.220101,-0.237648,-1.029569,-0.230627,0.336395,-0.074671,-0.103366,0.321197,0.183989,0.497702,0.245143,-0.166308,0.227180,0.711906,0.488033,-0.297181,0.184646,-0.106906,-0.636550,0.323430,1.054467,-0.287822,-0.478517,-0.285379,-0.188054,-0.607940,-0.553393,-0.698465,-0.264856,0.159477,0.712440,0.066852,-0.019312,0.342314,-0.637121,-0.356399,-0.177339,0.104812,-0.126030,-0.265924,0.009047,-0.532201,-0.061785,-0.118790,-0.225341,0.542708,0.023885,-0.317382,0.619701,-0.460009,0.387141,0.916665,0.107573,-0.588396,0.628810,0.015010,0.494050,-0.413901,0.229843,0.535260,0.198158,0.446553,0.186222,-0.282716,-0.125375,0.201001,-0.105153,0.176572', '3001114', '1294941', '4767216', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26951692', '阿德尔曼夫妇', '喜剧', '当著名作家维克托·阿德尔曼逝世时，一位记者联系上了他的妻子莎拉，希望能抢先报道这位伟大作家的一生。随着记忆的帘幕被缓缓拉开，维克托和莎拉这场近半个世纪的爱恋过程终于呈现在世人眼前。然而在甜蜜生活的背后，这对世人眼中的模范夫妻究竟埋藏着多少不为人知的秘密？丈夫背后的神秘女子又究竟是谁？ 当浪漫的爱情遭遇不忠的背叛，当真爱背后是熊熊燃烧的野心，他们究竟该如何解决婚姻的种种危机？', '多莉亚·蒂利耶', '尼古拉斯·贝多斯', 8.3, 38868, 'tt6095616', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2598060872.jpg', 0.3, 1.2, 14.6, 50.1, 33.8, '0.142908,0.239835,-0.639641,0.475828,0.159343,-0.253199,0.712722,-0.229996,-0.389115,-0.350193,0.247806,0.369343,-0.099619,0.343288,0.206080,0.102760,-0.279279,-0.839192,-0.207984,-0.330121,-0.243875,-0.416149,-0.700869,-0.073652,0.152412,-0.160472,0.731002,0.213044,-0.062426,0.007818,0.728056,0.621912,-0.246709,0.222706,-0.115574,0.009970,0.330642,0.327951,-0.609856,-0.142578,-0.029558,-0.369044,-0.123910,0.173355,-0.556852,-0.021133,0.435146,-0.375886,-0.211831,0.042191,0.547977,-0.170121,0.237276,0.276182,0.053567,-0.151709,0.109821,0.426742,-0.059543,-0.430854,-0.047746,0.077202,-0.787918,-0.244331,0.088808,0.217354,-0.537370,0.252184,-0.039698,-0.078537,0.298726,-0.059297,0.260034,0.412629,0.353586,0.530913,-0.271139,-0.042062,-0.392729,0.093389,0.826118,0.134879,-0.144910,0.353803,-0.444729,-0.261804,-0.230610,-0.054892,-0.727512,0.117248,0.363995,0.184520,-0.036767,0.811609,-0.256748,-0.039219,-0.227807,0.288320,0.365276,-0.604575,-0.109495,-0.060682,-0.585591,-0.429886,-0.358225,-0.055953,0.040895,-0.287296,0.822084,-0.576635,0.359506,0.646704,-0.045502,-0.301554,0.719980,0.499514,0.022126,-0.359354,-0.143198,0.421436,-0.043418,-0.121397,-0.285622,0.040038,0.164502,0.088101,-0.358116,0.488470', '5985887', '26021055', '1306795', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26951746', '大炮之街', '动画', '在一座由蒸汽驱动的城市中，一家三口展开了一天的生活。母亲去制造炮弹的工厂上班，父亲在炮台担任装填手，小儿子在学校里学习与大炮相关的知识。炮台不停开炮，但敌人的身影却始终没有出现……', '林勇', '大友克洋', 8.4, 8022, 'tt6264824', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2870445463.jpg', 0.2, 1.2, 14.7, 47, 36.8, '0.191640,-0.225777,-1.013784,0.691096,-0.105018,0.085307,1.055993,0.140153,-0.246077,-0.293358,0.344464,0.722783,0.388947,0.206099,-0.371562,-0.409619,-0.171763,-0.539241,0.112127,-0.080273,-0.361461,-0.644609,0.004049,-0.417979,0.211015,-0.240334,0.764165,0.086906,0.160066,0.196665,-0.474475,-0.230067,-0.174604,0.488415,-0.543938,-0.176533,-0.036157,-0.005091,0.023465,0.456274,-0.094819,-0.424438,-0.120279,-0.168499,0.341760,0.260295,0.987918,0.083664,-0.003522,-0.072848,-0.033128,-0.012754,-0.013918,0.036698,0.342837,0.136680,-0.165931,-0.249481,-0.336884,0.109287,0.167512,-0.315295,-0.355491,-0.382312,0.018318,-0.114776,-0.958989,0.576683,-0.263174,0.050175,-0.147809,-0.715488,0.419259,0.271089,-0.051131,0.610376,-0.720911,0.445227,-0.720860,0.249317,0.324324,-0.257266,-0.282774,0.309049,-0.227635,0.106365,-0.211529,-0.080569,-0.521628,-0.656313,0.073794,0.087001,-0.232360,0.183975,-0.825995,0.324778,-0.200972,-0.482277,0.205572,-0.295579,-0.285330,-1.290884,0.399066,-0.297794,-0.161833,0.436584,-0.098181,-0.052305,0.675218,-0.964960,0.172494,0.399668,0.611869,-0.045653,1.025096,-0.064546,0.330844,-0.088018,0.297553,0.022815,0.049533,0.713565,0.015542,0.411997,-0.063990,-0.061995,-0.497104,0.498844', '1307897', '1294917', '1297659', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26952704', '巴斯特·斯克鲁格斯的歌谣', '剧情', '《巴斯特·斯克鲁格斯的歌谣》是由六个部分组成的西部题材选集电影，乔尔·科恩和伊桑·科恩利用他们独树一帜又无与伦比的视角，讲述了关于美国边境的系列故事。电影的每一章都讲述了一则独特的美国西部故事。', '哈利·米尔林', '伊桑·科恩', 8.5, 122738, 'tt6412452', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2539127687.jpg', 0.2, 0.8, 11.5, 48, 39.5, '0.722272,-0.364073,-0.619417,1.159880,1.025374,-0.207466,0.152367,0.007499,-0.341496,-0.305137,0.113129,0.973243,-0.279726,-0.108258,-0.004924,-0.054761,-0.646870,-0.739346,-0.241203,-0.183356,-0.203635,-0.446388,-0.136617,-0.274085,0.025190,-0.396988,0.412156,-0.130375,-0.525388,0.199495,-0.074073,0.476844,0.154769,-0.193810,0.021721,0.342200,0.319899,-0.433956,-0.093904,0.412883,0.120598,0.238838,-0.138469,0.342979,0.036883,0.573260,0.890384,-0.502160,0.349989,0.111176,0.694123,-0.153688,0.017034,-0.407036,0.228360,0.039807,0.475542,0.529339,-0.210758,-0.311660,-0.295386,-0.334112,-0.870066,-0.101916,0.179064,0.468571,-0.265493,0.147543,-0.139552,0.030972,0.426445,-0.260577,0.296365,0.229721,0.762227,0.525718,0.480127,-0.264466,-0.091765,0.453226,0.459056,0.194353,-0.559896,0.208346,-0.482720,-0.399937,-0.413934,-0.375339,-0.304261,0.286153,0.273148,-0.298039,0.257870,0.790485,-1.050684,0.140512,-0.049262,-0.569884,0.140966,-0.452972,0.218469,-1.218401,-0.280510,-0.129774,0.311120,0.001311,0.343889,0.016020,1.123497,-0.136607,0.133286,0.605465,0.006380,-0.210215,0.771003,0.149364,-0.005987,-0.203227,0.331040,0.510076,0.251049,-0.176936,-0.079225,0.607235,0.311840,-0.297235,-0.677799,0.709768', '3318306', '22265121', '2027945', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26952994', '马丁·伊登', '剧情', '马丁（卢卡·马里内利 Luca Marinelli 饰）出生在贫穷的家庭之中，没有上过几年的学，如今和姐姐过着相依为命的日子，并且成为了一名终日漂泊在茫茫大海之上的水手。一天，马丁邂逅了名为爱莲娜（杰西卡·塞西 Jessica Cressy 饰）的千金大小姐，爱莲娜将法国诗人波德莱尔的诗集借给马丁看。马丁这辈子从来都没有看过这样的文字，一下子便被深深的吸引了，在海上漂泊的漫长时光里，他如饥似渴的吸收着这些知识，并且渐渐开始产生了自己写作的念头。马丁失业了，借此机会，他决定正式走上写作的道路。他不断的投稿，又不断的遭遇退稿，唯一没有想过的就是放弃。最终，马丁的小说被出版了，这令他收获了无数的名誉和财富。©豆瓣', '卢卡·马里内利', '皮耶特罗·马切罗', 8, 14649, 'tt4516162', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2578760530.jpg', 0.4, 1.8, 20.7, 52.3, 24.8, '0.397198,0.031064,-0.785068,0.879043,-0.159360,-0.560906,0.868655,-0.158299,-0.562512,-0.123579,-0.032182,0.867663,-0.244731,0.369964,0.194874,0.071602,-0.338779,-0.788731,-0.127282,-0.137726,-0.258393,-0.634105,-0.351750,-0.057345,-0.263191,-0.417694,0.651667,0.120595,0.114638,0.484694,-0.026076,0.152798,0.240421,0.454954,-0.376776,0.412680,0.151100,0.142315,-0.128184,0.206766,0.191756,-0.501302,-0.053225,0.201738,-0.053722,0.176531,0.664190,-0.340844,0.054667,0.047902,0.452286,-0.164427,0.000470,0.146037,0.160241,0.193606,0.243541,0.294497,-0.308598,-0.152494,0.102294,-0.076211,-0.554750,-0.170438,0.023173,0.223663,-0.830984,0.508656,-0.187127,-0.192812,-0.106409,-0.364794,0.211620,0.230037,0.141870,0.320648,-0.193969,0.084546,-0.485749,0.612028,0.653485,-0.162652,-0.248970,0.360877,-0.255776,-0.160198,0.025392,-0.362248,-0.573703,-0.177416,0.401858,0.167115,-0.454365,0.350779,-0.773690,0.322544,-0.202559,-0.576750,-0.006820,-0.316657,-0.226353,-0.489494,-0.180363,-0.539939,-0.346411,0.037792,0.033776,-0.455971,1.035280,-0.806224,0.517072,0.660869,0.311197,-0.347503,0.815056,0.083946,0.030979,0.243778,0.093646,0.449032,-0.127615,0.439356,0.225444,0.430943,0.162924,-0.112355,-0.289521,0.988138', '30162520', '26677495', '1870681', '1292001');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26954003', '大世界', '剧情', '南方小城，大雨将至。工地司机小张为了挽救和女友的爱情，抢劫了老板的巨款，引发连锁反应。几股势力纷纷对小张展开追逐。原本没有关系的他们，命运产生了交集。在一番阴差阳错、啼笑皆非的交手之后，他们迎来了意想不到的结局，命运和他们开了一个大大的玩笑。历时三年，导演刘健一人身兼多职，用独特的画风描绘了在一个发生在一天之内的黑色幽默故事，呈现出一幅独特的时代风景画和社会众生相。', '朱昌龙', '刘健', 6.9, 53519, 'tt6451304', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2508258043.jpg', 1.2, 7, 44.4, 39.6, 7.8, '0.213099,0.037129,-0.669731,0.663364,-0.053922,0.114972,0.968211,0.264054,-0.538628,-0.125606,0.285892,0.805594,-0.616779,-0.044425,0.442658,-0.630208,-0.143763,-0.731101,0.064256,-0.154458,-0.169178,-0.406109,-0.305395,-0.319861,-0.041802,-0.298373,0.473907,0.114134,-0.273392,0.482792,0.260208,-0.029509,-0.310131,0.470746,-0.259825,0.192951,0.118313,0.312240,-0.525903,0.259863,-0.084265,-0.317521,-0.185860,0.101439,-0.523635,0.146879,0.888605,-0.273658,-0.408342,-0.049986,0.370268,-0.209440,-0.191910,-0.014007,0.542219,0.074903,0.101720,0.206597,-0.314176,-0.223589,0.287748,-0.013343,-0.722626,0.144612,-0.010529,0.169065,-0.445502,0.650997,0.156367,-0.395671,-0.101041,-0.350858,0.244772,0.559283,0.756332,0.505596,-0.033729,-0.010055,-0.610832,0.110845,0.928929,-0.132526,-0.356759,0.695650,-0.414598,-0.149679,-0.368818,-0.254285,-0.383828,0.087704,0.442821,-0.231609,-0.234868,0.176363,-0.879846,-0.016840,-0.101195,-0.234182,-0.044920,-0.506075,-0.066278,-0.513029,-0.380227,-0.302150,-0.250486,0.160611,0.106527,-0.013731,0.744287,-0.752353,-0.009640,0.466340,0.274660,-0.536577,0.762754,0.189467,0.010939,-0.364145,0.124819,-0.073432,-0.119835,0.405335,0.228235,0.457248,0.015641,0.113490,-0.015956,0.498875', '30162520', '2053515', '26687241', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26954268', '道高一丈', '剧情', '宋朝、刘海洋、黄天成是警校同窗，宋朝因犯错被开除，警察梦破灭。刘海洋、黄天成顺利毕业成为了真正的警察。被警校开除的宋朝受刘海洋之父刘守义之托，混进贯宇集团调查一桩纵火案。刘守义在跟宋朝接头时，被贯宇集团手下胡龙带人杀害，胡龙则在行凶时被刘守义开枪击伤后逃跑下落不明，宋朝被当成杀人疑凶而被迫踏上逃亡之路。刘海洋跟宋朝不仅是同学，更是妻子楚洁的前男友，新仇旧恨让刘海洋发下毒誓要将宋朝绳之以法。而此时，宋朝也在为脱罪积极调查真相，并找到昔日同窗黄天成寻求帮助，不料却在追逃过程中陷入更危险的境地，命悬一线之际，他们才发现这一切竟是一名叫胡紫薇的女人所为，而胡紫薇的背后隐藏着更大的阴谋与罪恶。光明与黑暗，正义与邪恶，扑朔迷离，环环相扣，最终“魔高一尺、道高一丈”。', '聂远', '姜凯阳', 4.7, 8005, 'tt7683896', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2530863118.jpg', 16.7, 41.2, 34.7, 4.9, 2.6, '0.008603,0.174183,-0.499403,0.410753,-0.050038,-0.455893,0.597422,0.110037,-0.476109,-0.459134,-0.056706,0.412567,-0.159700,0.094861,0.220209,-0.310220,-0.131580,-0.758613,-0.156439,-0.029548,-0.122208,-0.647758,0.015491,-0.124162,-0.078616,0.034547,0.556618,0.356075,-0.437010,0.336640,0.369304,0.440605,-0.166112,0.669771,-0.030077,0.077174,0.190361,-0.081144,-0.440960,-0.026138,-0.010272,-0.646266,-0.147605,0.230471,-0.251543,0.231321,0.403791,-0.139030,-0.178478,-0.441216,0.476635,-0.556683,-0.102309,0.102649,0.646374,-0.041754,0.121348,0.285978,-0.097746,-0.177835,0.187015,-0.089487,-0.842911,0.028735,0.268154,-0.046796,-0.409000,-0.112254,0.082281,0.200548,0.269806,-0.281001,0.386888,0.518674,0.462793,0.134288,-0.174958,0.088180,-0.620457,0.122370,0.776330,-0.209834,0.054318,-0.203971,0.219563,-0.333081,0.235294,-0.087808,-0.094763,0.057850,0.596001,-0.103563,-0.023688,0.213104,-0.253625,-0.350535,-0.348831,0.227362,-0.085834,-0.388935,-0.179812,-0.236778,-0.202672,-0.218425,-0.409800,0.045191,0.209853,-0.236182,0.325421,-0.695454,0.234396,0.410336,0.171028,-0.715557,0.458329,0.227385,0.245558,-0.084946,-0.079839,-0.045798,0.410987,0.573543,0.188533,0.122176,-0.314531,-0.044291,-0.005515,0.089672', '1419985', '3811342', '35073886', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26954859', '兰心大剧院', '剧情', '电影根据虹影《上海之死》及横光利一《上海》改编。1941年。著名演员于堇返回孤岛时期的上海，表面上是为了出演她的旧爱执导的话剧《礼拜六小说》。但是她真正的目的是什么？是为了救出她的前夫？为了给盟军搜集情报？为了给养父工作？还是为了和自己的爱人一起逃离战争？她真正的使命是什么?随着她着手执行任务，敌我越来越难以分辨，一个女人的命运被时代紧紧牵引，她又如何做出改变世界格局的选择? 戏里戏外，谁能幸免?', '巩俐', '娄烨', 7.2, 121627, 'tt8499638', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2681336608.jpg', 0.7, 5.6, 37.9, 45, 10.7, '-0.021927,0.193603,-0.591101,0.689592,-0.360101,-0.029552,0.311533,-0.132647,-0.357010,-0.292480,0.114553,0.993916,0.183871,-0.124243,-0.040538,0.141316,-0.121116,-0.747511,0.075845,0.062054,-0.188923,-0.370638,-0.370761,0.006728,-0.092528,-0.034556,0.999077,0.227436,-0.221435,-0.096391,0.573232,0.382385,-0.316896,0.298584,0.013001,-0.239578,-0.408882,-0.093579,-0.578378,0.254018,0.117177,-0.258944,-0.413902,0.320427,-0.319008,0.322369,0.675896,-0.206913,-0.096581,-0.356110,0.427628,-0.487527,-0.077628,-0.146460,0.039229,-0.156469,0.208129,0.442720,-0.067440,-0.147912,0.048059,-0.169308,-0.962144,-0.311206,0.425161,0.306556,-0.594543,0.115468,-0.376586,-0.132747,0.024144,-0.312430,0.243517,0.664148,0.564285,0.349768,-0.547142,-0.108690,-0.424668,0.361149,0.857390,0.167291,-0.119451,0.396133,-0.324489,-0.191636,-0.128645,-0.528451,-0.540990,0.251170,-0.038557,0.006955,-0.411113,0.081018,-0.324718,-0.085142,-0.109416,-0.354402,0.135672,-0.832358,0.278625,-0.315370,-0.107878,-0.290157,-0.164658,-0.404883,0.175270,-0.537548,0.688118,-0.904606,-0.004301,0.794936,0.382443,-0.671664,0.626185,0.445650,0.029636,-0.414192,0.161302,0.139754,-0.120049,0.224176,-0.123938,0.132567,0.294721,-0.145723,-0.426814,0.734350', '30345227', '26678784', '30163500', '1296569');
