INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26957500', '老兽', '剧情', '老杨曾是财富激荡时代的乍富阶层，如今已破产多年，赋闲在家。某日他挪用老婆的救命手术费让子女们忍无可忍，一出儿子绑架老子的荒诞闹剧上演，老杨怒其不念养育之恩，毅然把不孝子告上法庭……这出现代家庭闹剧终以悲剧收场。', '涂们', '周子阳', 7, 28496, 'tt7481246', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2507370070.jpg', 0.7, 6.6, 43.5, 39, 10.3, '-0.391823,0.292111,-0.330712,-0.215209,-0.368901,-0.433675,0.253317,-0.124263,-0.559912,-0.255160,0.467581,0.490200,-0.495189,0.509119,0.081203,-0.317890,0.220811,-0.635579,-0.151388,0.263515,0.164725,-0.481416,-0.000605,-0.316309,-0.440738,0.058553,0.108495,0.150567,-0.147494,-0.004680,0.859860,0.472642,-0.004599,-0.115718,-0.215821,0.240236,0.022889,0.469819,-0.524035,-0.265519,-0.049976,0.017539,-0.205331,-0.216262,0.001238,-0.081772,0.274700,0.003964,0.065010,-0.398340,0.906012,-0.445659,-0.498204,0.360260,0.225744,-0.003199,0.149432,0.260738,-0.332414,-0.656210,0.117158,-0.063335,-0.225050,0.087559,-0.120764,-0.283963,-0.417816,0.105438,0.160638,0.228059,-0.229260,0.012164,0.217447,0.026402,0.519321,0.904016,-0.141382,0.272182,-0.165693,0.713502,0.828725,-0.221003,-0.196094,-0.209358,-0.197798,0.199972,0.518581,-0.816626,-0.560052,0.082015,0.231130,-0.609692,-0.053601,0.809508,0.014258,-0.234757,-0.385557,0.196348,0.389730,-0.130901,-0.188285,-0.035951,-0.265423,0.038147,-0.099638,0.258812,0.181580,-0.252116,0.539603,0.238444,0.078266,0.038992,0.076170,-0.846759,0.608336,0.312808,-0.023715,-0.117748,0.078515,-0.037878,-0.103604,-0.019068,0.141411,-0.391106,0.053173,-0.100601,0.346654,0.643281', '7161707', '1305915', '24879820', '1296218');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26958479', '浅田家！', '剧情', '幸宏（妻夫木聪 饰）和政志（二宫和也 饰）出生在一个幸福的家庭之中，他们的父亲（平田满 饰）非常喜欢摄影，每一年，父亲都会给兄弟两人拍一张照片，制作成贺卡。在政志12岁生日那一天，父亲将珍藏的尼康相机作为生日礼物送给了政志，希望他也能够在摄影中找到乐趣。带着父亲的相机，政志来到了大阪摄影专业学校学习。然而，政志的学习之路并非一帆风顺，懒惰和怠慢让他成为了学校里的问题学生，但与此同时，政志也展现出了过人的摄影天赋。毕业之后，政志没有和同龄人一样走上职场，而是回到了老家成为了家里蹲。但即便是这样，政志也没有放弃过摄影的梦想，他以家人和梦想为题材拍摄了一系列的作品，并且想要以《浅田家》为名，将作品集结出版。©豆瓣', '二宫和也', '中野量太', 8.3, 27357, 'tt9860350', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2614188527.jpg', 0.3, 1.1, 15.2, 48.6, 34.8, '0.232615,-0.129496,-0.527465,0.766388,-0.110486,-0.259492,0.565852,0.019751,-0.467296,-0.370576,-0.032789,1.106017,0.048536,0.462088,0.186100,-0.139316,-0.283007,-0.854466,0.014760,-0.213544,-0.263676,-0.396051,-0.093379,-0.060027,-0.358876,-0.337939,0.713040,0.002284,-0.008203,0.645391,0.116806,0.046265,0.089160,0.271657,-0.239061,-0.014668,-0.060606,0.213043,-0.353938,0.440464,-0.034684,-0.320021,-0.078968,0.284413,0.231152,0.147798,0.818035,0.005833,-0.242465,0.045015,0.376418,-0.203622,-0.283869,0.209350,0.144091,0.223122,0.409766,0.282571,-0.210524,0.236545,0.030600,-0.316037,-0.789876,-0.208538,0.230418,-0.062390,-0.937065,0.511733,-0.207443,-0.323862,0.161745,-0.359218,0.300233,0.123583,0.092315,0.443055,-0.223749,0.196295,-0.522198,0.510708,0.497139,-0.183582,-0.005500,0.535081,-0.136376,-0.417511,0.027328,-0.336844,-0.426775,0.089750,0.008543,0.127550,-0.100941,-0.185649,-0.585826,0.063423,0.038769,-0.306324,0.120738,-0.502716,-0.109593,-0.604515,0.082422,-0.424339,-0.509962,0.081381,0.144445,-0.602959,0.930728,-0.930211,0.232115,0.294552,0.373992,-0.478382,1.020744,0.024609,0.059239,-0.118128,0.132320,-0.122955,0.119949,0.251358,-0.048670,0.278790,0.098331,-0.460867,-0.557420,0.678014', '1870681', '35048413', '30162520', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26958485', '逆流大叔', '剧情', '男人，就是要逆流而上。阿龙(吴镇宇饰)、淑仪(潘灿良饰)、泰哥(黄德斌饰)、威廉(胡子彤饰)，四个高不成低不就、做事得过且过的宽频网络公司员工，见公司掀起了裁员风暴，为表对公司忠诚以「保饭碗」，误打误碰地加入了公司新成立的龙舟队！面对男人之苦，这班本来选择逃避的大叔们，坐到只许前进不许后退的龙舟之上，竟重拾了人生久违了的冲劲。一鼓作气的他们，不但参与了难度更高的长途龙舟大赛，更借着重新燃起的斗志，迈步去迎接自己人生里一道又一道的逆流…', '吴镇宇', '陈咏燊', 6.6, 7779, 'tt7767874', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2560920854.jpg', 1, 10.1, 52.7, 30.1, 6.1, '0.064456,0.107074,-0.409542,0.505485,-0.105755,-0.421139,0.500902,0.344922,-0.145367,0.332563,0.385183,0.665089,0.024294,0.060524,0.238602,-0.243868,0.045747,-0.505558,-0.120876,0.009229,-0.192453,-0.096556,0.094094,0.071619,-0.134522,0.041811,0.641575,0.030211,-0.208359,0.537278,0.423189,-0.144372,0.198112,0.610472,-0.007984,-0.186269,-0.213766,0.109450,-0.092366,0.154316,0.111352,-0.382493,-0.304485,0.118890,0.009420,0.211256,0.394813,-0.028509,-0.019274,-0.358383,0.398536,-0.221019,0.014148,-0.050046,0.210176,0.089917,-0.054524,0.212590,-0.022223,0.100948,-0.119663,-0.166709,-0.631844,0.098733,-0.130560,-0.196530,-0.838701,0.098266,-0.067578,-0.237144,0.249484,-0.122172,-0.117278,0.267972,0.055436,0.179066,-0.304771,0.166819,-0.464316,0.175891,0.619435,-0.065251,-0.276176,0.115233,-0.029202,-0.047935,0.007377,0.006204,-0.281928,-0.443782,0.349900,-0.097763,0.107239,0.061028,-0.715113,0.258808,-0.339405,-0.351655,-0.073067,-0.295559,0.030158,-0.444061,0.012517,0.151766,-0.025657,0.250711,0.171517,-0.176301,0.452764,-0.511401,-0.019157,0.551486,0.363396,-0.622188,0.640165,0.018436,0.289263,-0.188514,-0.119578,-0.002617,-0.257661,0.638892,-0.006697,0.419592,-0.088846,-0.282529,-0.236288,0.391541', '25908042', '1292584', '4604803', '1316560');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26959074', '柔情史', '剧情', '刚和男友分⼿的小雾，因一笔意外的稿费而在北京胡同里租了一套房⼦，期待⾃己⼀个人的世界。不料母亲因无法与家中的⽼人相处，搬来与她同住。奇特的战争开始了。 每天⼀睁眼，在屋子的每⼀个角落，母亲荒谬的生活规则与偏执的行为方式折磨着小雾。小雾也被母亲的思维逻辑潜移默化的影响着。两个极度缺乏安全感的女人，在饭桌， 尿盆，碗筷中互相攻击，防御。在战争高潮，她们已无法面对彼此。母女各自开始了一场恋爱，获得了暂时的平衡， 但最终都失败了。', '耐安', '杨明明', 6.6, 7065, 'tt7955712', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2561819560.jpg', 2.2, 12, 45.8, 33.4, 6.5, '0.495510,0.206599,-0.834293,0.556603,-0.174497,-0.273033,0.893048,0.414184,-0.713295,-0.197901,0.138650,0.741032,-0.085037,0.231623,0.193540,-0.274587,-0.167973,-0.656141,-0.198178,0.022096,-0.408557,-0.446963,-0.068436,-0.366224,-0.151231,-0.278911,0.431436,0.078757,-0.113052,0.393187,0.096283,0.105624,-0.155920,0.625139,-0.145563,-0.022858,-0.035095,0.115817,-0.413857,-0.061974,0.056237,-0.247589,-0.195709,0.449559,-0.081302,0.314502,1.030751,-0.433800,-0.249948,0.020561,0.358027,0.063639,-0.373014,0.271264,0.432877,0.033724,0.482495,0.160111,-0.084493,0.140096,0.247058,-0.143884,-0.817637,0.006086,0.001395,-0.013534,-0.487954,0.952424,0.165632,-0.073863,-0.089662,-0.190566,0.081304,0.443839,0.378618,0.653024,-0.524014,-0.263100,-0.442445,-0.012904,0.596617,-0.128609,-0.345614,0.732558,-0.614644,-0.423329,-0.211789,-0.403975,-0.492779,-0.225211,0.333403,0.277263,-0.490030,0.221301,-0.831481,0.385891,0.010370,-0.108001,-0.017987,-0.729910,-0.047163,-0.539333,-0.285973,-0.495483,-0.430682,0.230520,0.104217,0.021541,0.650909,-0.932144,0.118524,0.604933,0.238217,-0.552303,0.773934,0.228302,0.285587,-0.226429,0.189479,0.054409,-0.453442,0.368472,0.384937,0.481964,-0.191753,0.462811,-0.493020,0.761432', '1459368', '4817024', '24756472', '26754675');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26959115', '小小乔', '剧情', '爱丽丝，是一个单身母亲，也是一家新品种植物开发公司的高级植物培育员，工作非常勤奋。她设计了一种非常特别的暗红色花朵，不仅外观让人注目，其健康价值更是出众：如果气温合适，营养足够，人们能时常跟它说话，这棵植物就可以让它的所有者开心起来。爱丽丝违反了公司规定，带了一株回家送给自己的青少年儿子，乔。他们给这朵花起名“小小乔”。但随着花朵生长，爱丽丝越来越怀疑“小小乔”也许并不像它的名字那么无邪。', '艾米丽·比查姆', '杰茜卡·豪丝娜', 6.3, 6414, 'tt9204204', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2569367878.jpg', 3.3, 16.6, 48.1, 26.3, 5.8, '-0.085356,-0.075029,-0.422246,0.697217,-0.475736,0.036485,0.457189,0.244278,-0.577495,-0.184499,-0.412050,0.523297,-0.042345,0.259788,-0.195931,0.129897,-0.101934,0.129473,0.330265,-0.078506,-0.280773,-0.273921,-0.170390,-0.460452,-0.043830,-0.033028,0.672190,-0.000771,-0.227520,0.302120,-0.310928,-0.198535,0.398547,0.373027,-0.511379,-0.321008,-0.007667,-0.063033,0.218638,0.041662,0.028894,0.005109,0.243581,0.178771,0.260515,0.157458,0.580789,-0.164101,-0.468855,-0.412171,0.456756,-0.156501,0.397625,-0.053591,0.323655,-0.245897,0.317363,-0.237087,-0.290198,0.283278,0.174841,-0.348478,-0.691355,0.040717,0.037331,-0.015851,-0.562020,0.217957,0.305371,-0.042705,0.009235,-0.358271,0.203261,0.086320,0.095506,0.195476,-0.208910,-0.256069,-0.763524,0.206402,0.288507,-0.069448,-0.455816,0.772018,-0.855213,-0.863209,-0.211296,-0.062342,-0.329017,0.076435,0.294228,0.229638,-0.003786,-0.291008,-0.702004,0.122075,0.066529,-0.222538,-0.086034,-0.542602,0.044311,-0.235617,0.067555,-0.360798,-0.386889,-0.130432,0.115106,-0.542277,0.877988,-0.586146,-0.078058,0.251355,0.289780,-0.751756,0.191076,-0.105534,-0.053694,-0.236471,-0.317957,0.240098,0.123426,0.000695,0.049443,0.361817,0.499414,-0.195386,-0.223496,0.316996', '25882279', '1302661', '1303542', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26961002', '常在你左右', '悬疑', '罹患不治之症的David（张智霖 饰），醉驾失控冲向隔邻行车线，休班警员Sam（古天乐 饰）和妻子阿思（佘诗曼 饰）于两车相撞前及时扭軚，避过一劫。David的车和跟在Sam车后的一辆车迎头相撞，司机Patrick无辜惨死。失恋寻死的小红从天台一跃而，恰巧堕到Patrick车顶。此时，新晋歌手Jamie与舅父驾车经过，好奇查看时，遭重型货车撞死。负责处理小红尸体的仵工志强（林家栋 饰），因想还清赌债而偷走了陪葬的龙凤镯，却一直不能将其变卖。Patrick未婚妻雨欣（蔡卓妍 饰），为完成丈夫的遗愿经营渡假屋，却接连发生怪事，David为了赎罪前来暗中帮忙。Jamie的黑胶唱片被扔掉后仍不断重回到Sam和阿思家中，涉及车祸的人无不遇怪事……', '古天乐', '邱礼涛', 5, 11571, 'tt7469972', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2499790488.jpg', 10.4, 38.6, 42.3, 6.4, 2.3, '-0.038971,-0.149034,-0.564315,0.046066,0.005836,-0.353832,0.835268,0.281568,-0.182257,-0.260147,0.493600,0.658305,-0.174248,-0.016454,0.279422,-0.088965,0.004666,-0.548664,0.236946,0.197010,-0.425765,-0.121229,-0.075112,-0.107871,-0.061060,-0.265507,0.438569,0.029653,-0.100090,0.741732,0.461979,0.389712,-0.625746,0.196776,-0.200300,0.202402,-0.235840,0.188852,-0.182637,-0.006957,-0.055706,-0.530700,0.105525,-0.405556,0.175294,0.194808,0.817557,-0.091777,-0.069471,-0.267843,0.112260,-0.141077,0.205546,0.000771,0.182199,0.486326,0.189354,0.264394,-0.449596,-0.081143,0.393312,0.108405,-0.306221,-0.060399,-0.002707,-0.144701,-0.848428,0.393513,-0.451101,0.083567,0.158511,-0.271071,0.452141,0.571976,-0.033105,0.299675,-0.313158,0.083728,-0.488714,-0.012165,0.520188,-0.118603,0.308865,0.427803,0.292146,-0.132731,0.077188,0.005784,-0.159644,0.045970,0.551789,0.032975,-0.152438,-0.167716,-0.138461,-0.372945,-0.583742,-0.133727,-0.324580,-0.121246,-0.257785,-0.300805,0.299616,-0.048954,-0.140679,0.125428,0.074893,0.026101,0.176398,-0.261286,0.198070,0.216031,0.376876,-0.331536,0.500386,-0.217136,0.184148,0.076427,-0.347186,-0.024056,0.194774,0.552850,0.019852,-0.016977,-0.217042,0.036929,-0.405701,-0.098564', '21619567', '1578663', '1294252', '1773217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26961821', '马柔本宅秘事', '剧情', '为了躲避一些未知的东西，母亲带着四个孩子住进了一个偏僻的房子里。母亲病故后，在兄弟四人的努力下，他们争取到了房子的产权。最大的孩子也开始找到了自己的爱情，但一帆风顺的生活下，实则暗藏凶机。最小的弟弟一直声称房间里面存在鬼魂，其他三人也似乎承认此事，但都没人点破。故事的开头要从四人的父亲说起，这其中包含很多阴暗和不愉快的事情。虐童、弑父、藏尸、禁闭，其中的隐情终究会被他人打破……', '乔治·麦凯', '塞尔希奥·G·桑切斯', 7.5, 29783, 'tt5886440', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2456908524.jpg', 0.8, 3.4, 31.4, 46.7, 17.7, '0.549206,-0.068309,-0.750450,0.559550,-0.258908,0.023335,1.139106,-0.003652,-0.730394,-0.463458,0.211407,0.661259,0.046777,0.238560,-0.175372,0.085911,-0.295602,-0.257892,-0.117820,-0.349304,-0.414143,-0.547013,-0.079164,-0.218901,-0.277744,0.154275,0.483028,0.374159,0.023096,0.039037,0.028800,0.006156,-0.360913,0.442745,-0.111688,0.195402,-0.163292,0.181524,-0.149703,0.161240,0.192880,-0.197773,-0.319432,0.346723,0.008788,0.533473,0.603805,-0.189067,-0.258368,0.206763,0.107595,-0.204445,-0.302236,0.214663,0.181134,-0.144312,0.492211,0.514513,-0.168541,0.051802,-0.020407,-0.043830,-0.717176,-0.231859,0.223433,0.110073,-0.571603,0.578269,0.147160,-0.062579,0.021156,-0.310092,0.329196,0.310738,0.119257,0.354541,-0.431270,-0.036801,-0.801616,-0.058236,0.647726,-0.420347,0.015355,0.302445,-0.369791,-0.286909,-0.093968,-0.213544,-0.551806,-0.014788,0.360668,0.289028,-0.394960,0.148630,-0.490265,0.037332,0.047778,-0.150523,-0.079976,-0.783229,-0.110244,-0.153400,-0.083246,-0.308353,-0.398775,0.092500,0.163557,-0.304655,0.737944,-0.634008,0.211092,0.497423,0.244539,-0.654753,0.638916,0.031593,0.508787,-0.186754,-0.053500,0.024622,-0.002939,0.184461,0.197502,0.353914,-0.157678,-0.245090,-0.561407,0.396553', '21619567', '1297192', '1861411', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26962981', '欢乐好声音2', '喜剧', '今年年底佳节，照明娱乐全球卖座动画电影系列的全新篇章即将展开，有更伟大的梦想和更多超夯流行金曲。野心勃勃的无尾熊巴斯特穆恩，以及他旗下的全明星动物艺人，即将呈献史上最华丽耀眼的舞台大秀…而且是在绚烂夺目的世界娱乐之都举行。但是有一个难关：他们必须先说服全世界最孤僻的摇滚巨星－由音乐传奇人物波诺首度为动画片献声演出－加入他们的表演行列。巴斯特（金奖影帝马修麦康纳 配音）以及他旗下的艺人将他的新穆恩剧院，转变成当地最火红的表演场地，但是他现在有一个更大的野心，那就是在光芒万丈的红滩市的克里斯托塔剧院，举办一场全新歌舞大秀的首演会。完全没有任何娱乐圈的人脉可言，巴斯特和他旗下的艺人－包括总是忧心忡忡的猪妈妈萝希坦（金奖影后瑞丝薇斯朋 配音）、摇滚女豪猪爱希（史嘉蕾乔韩森 配音）、认真努力的大猩猩强尼（泰隆艾格顿 配音）、内向害羞的大象米娜（托蕾凯莉 配音），当然还有爱现猪仔刚特（尼克克罗尔 配音）－必须偷偷溜进由一匹冷血无情的娱乐大亨野狼吉米克里斯托（艾美奖得主巴比卡纳佛 配音）一手打造经营，举世闻名的克里斯托娱乐公司的办公室。为了得到克里斯托先生的注意被逼到狗急跳牆的刚特，突然灵光一闪，给了巴斯特一个超浮夸的点子，巴斯特也逼不得已採用了这个点子，那就是向克里斯托先生挂保证，他们全新的歌舞大秀将由传奇摇滚狮子歌王柯雷卡洛威（波诺 配音）领衔主演。但问题是，巴斯特从来没见过柯雷，而且这名传奇摇滚歌王早就在十几年前，因为痛失爱妻从音乐界引退，独自隐居了十几年，再也没有人见过他。当刚特正在帮助巴斯特设计出一场举世无双的舞台歌舞秀经典杰作，来自克里斯托先生的压力（以及可怕的威胁）也越来越大，', '马修·麦康纳', '加斯·詹宁斯', 7.1, 32480, 'tt6467266', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2732782860.jpg', 0.7, 6.1, 44.2, 37.6, 11.5, '0.141362,-0.071542,-0.521532,0.419823,0.224155,-0.236307,0.473632,0.182871,-0.269894,-0.086009,0.397404,0.828857,-0.281404,-0.059319,0.284475,-0.147388,-0.279206,-0.581554,-0.013514,-0.112696,0.110824,-0.231754,-0.157792,0.068217,-0.068846,-0.365923,0.578557,-0.223566,-0.145150,0.320964,0.569452,0.117550,0.166871,0.170675,-0.020156,-0.096707,0.447102,-0.119111,-0.173750,0.268592,-0.024578,0.075354,-0.246799,0.138201,-0.004929,0.148381,0.386043,-0.414434,0.054390,-0.154902,0.492718,-0.229483,-0.033082,-0.101498,0.130204,-0.168621,0.333534,0.123954,-0.073063,0.037925,-0.093627,-0.274103,-0.912811,0.137226,0.140004,0.309323,-0.404782,0.355095,-0.097127,-0.294792,0.193159,-0.147286,0.318909,0.133351,0.335599,0.129708,0.016289,0.408509,-0.377341,0.416582,0.436833,0.219084,-0.404005,0.325544,-0.129015,-0.347734,-0.117709,-0.397982,-0.508591,-0.022219,0.206621,-0.226291,0.112500,0.134726,-0.746971,-0.02984