INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26965165', '马斯顿教授与神奇女侠', '剧情', '神奇女侠创造者、著名心理学家威廉·马斯顿博士是位拥有两位长期伴侣的BDSM爱好者，一位是同为心理学家的妻子，另一位是他从前的学生。这一段关系是马斯顿博士创造神奇女侠的关键原因，神奇女侠也注入了两位女性的形象。三人关系和睦，甚至在他去世后，两位女性还在一块抚养孩子。', '卢克·伊万斯', '安吉拉·罗宾森', 7.9, 22581, 'tt6133130', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2502244869.jpg', 0.8, 2.2, 23.2, 49, 24.9, '0.065917,-0.218485,-0.252401,0.616635,-0.425765,-0.224501,0.655000,-0.045338,-0.684781,-0.637727,0.607056,1.071124,0.003530,0.292696,0.285369,0.230302,0.053089,-0.412356,0.053395,-0.101981,-0.167655,-0.603186,-0.614787,-0.237340,-0.070825,-1.007385,0.555468,-0.365376,-0.550172,0.186291,0.153467,0.249546,-0.388667,-0.034425,-0.469274,0.045815,0.574280,0.123710,-0.524919,0.197898,-0.172176,0.091723,0.140449,-0.003942,0.030544,0.195506,0.348297,-0.134654,-0.204089,-0.023812,0.462903,0.167252,-0.078478,0.067724,0.646380,-0.044863,0.462018,0.364441,0.186826,-0.277355,0.000432,-0.246987,-0.820084,-0.176260,0.299312,0.102002,-0.640405,0.517574,0.085453,-0.713786,-0.019504,-0.348589,0.221584,0.006382,-0.164390,0.489689,0.265222,0.178533,-0.077553,0.500700,0.798901,-0.026758,-0.526438,0.424834,-0.374117,-0.678973,-0.206687,-0.389772,-0.687924,0.223789,0.188420,-0.105807,0.146280,0.329319,-0.405091,0.322430,-0.309556,0.395783,0.164085,0.012099,0.265385,-0.276954,0.130901,-0.421175,-0.326959,-0.295482,0.237187,-0.640457,1.489874,-0.634066,0.198923,0.410947,-0.073140,-0.544616,1.091702,0.312125,0.224794,-0.520999,-0.434017,0.214086,-0.111214,-0.182916,-0.151341,0.452366,0.092904,0.028378,-0.199598,0.186420', '27602116', '24284209', '26348103', '26593587');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26966580', '妖铃铃', '喜剧', '无良地产商父子徐大富（沈腾 饰）和徐天宇（岳云鹏 饰）一心想争夺豪华CBD中一幢破旧居民楼“萌贵坊”的产权，但萌贵坊内仍存四户怪咖不愿搬出—神医王保健（张译 饰）和他的儿子鸡丁（李亦航 饰）、民间发明家夫妇李菊花（Papi 饰）和金三（潘斌龙 饰）、网红主播阿萍（焦俊艳 饰）以及 过气古惑仔阿仁（方中信 饰）和阿明（吴镇宇 饰）。某个月黑风高的夜晚，怪事接连发生，僵尸，丧尸，吸血男爵，红衣女鬼接踵而至，陷入恐慌的“留守怪咖”请来江湖上人称“万能大师”的铃姐（吴君如 饰）帮他们化解危难，没想到铃姐却带来了更大的麻烦……', '吴君如', '吴君如', 4.2, 142278, 'tt7743588', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2506825662.jpg', 29.3, 40.7, 24.1, 4.3, 1.6, '0.003653,-0.058766,-0.309702,0.120826,0.305141,-0.162215,0.907836,0.116291,-0.486911,-0.550100,0.160208,0.347879,-0.291502,0.157348,0.145216,-0.063178,0.054014,-0.183522,0.001845,0.227932,-0.106810,-0.174447,-0.449078,-0.305377,-0.011617,-0.038623,0.028822,0.376379,-0.205634,0.402788,0.528955,0.406772,-0.172857,0.085691,0.052457,0.217369,-0.040374,0.189167,-0.193258,-0.044012,-0.161565,-0.154711,0.191246,-0.044713,0.193637,0.232325,0.406784,-0.430966,-0.028902,-0.224896,0.279930,0.014251,-0.143093,0.133828,0.275417,-0.104540,0.508229,-0.009143,-0.193296,-0.001508,0.325277,-0.048266,-0.367076,0.205723,0.396267,0.037100,-0.428736,0.236366,-0.052796,0.011779,-0.012316,-0.187755,0.316986,-0.088999,0.361589,0.130432,-0.037103,0.017010,-0.526822,0.349503,0.308345,-0.074956,0.161788,-0.146377,0.085850,-0.315429,-0.014504,-0.122985,-0.265704,0.052370,0.442266,-0.250681,0.144885,-0.094695,-0.585360,-0.279572,-0.005253,0.214350,-0.118239,0.130548,-0.109635,-0.406378,0.133237,-0.526181,-0.014481,0.188249,0.145024,-0.111692,0.388603,-0.482425,-0.003317,-0.227365,0.297479,-0.304253,0.499275,-0.205521,0.292696,-0.079099,-0.280865,-0.217617,0.148081,0.118397,0.307776,0.215190,-0.274559,-0.367788,0.146115,-0.201139', '1301686', '1578663', '1295674', '30257386');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26967920', '遇见你真好', '剧情', '当遇见爱情的时候才会发现，它就像万有引力，苹果总归会落地。在被称为“高四”的紫荆复读学校是一所爱情集中营，梦想成为作家的张文生和珊妮在互损中萌生情愫，好友陈奇误认为文生横刀夺爱，与“坏学生”青龙在小酒馆相遇并商议各自的复仇计划。不料陈奇带去的巨型烟花被青龙向酒馆发泄中引发火灾，带出人命。于是，这所学校里的一个又一个神秘搞笑的爱情故事浮出水面，一群热血而欢乐的男女演绎了另类的青春和爱情……', '白客', '顾长卫', 4.5, 25491, 'tt8209632', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2516082047.jpg', 28.4, 34.6, 24.3, 8.4, 4.2, '0.532488,-0.151089,-0.766713,0.333750,-0.009747,-0.288317,1.064372,0.055145,-0.273461,0.085359,0.172255,0.883322,-0.468072,0.555583,0.365899,-0.087037,-0.226093,-0.812631,0.050237,-0.232958,-0.027752,-0.087973,-0.052786,0.014246,0.074392,-0.054542,0.632904,0.193418,-0.257535,0.744420,0.310918,0.412574,-0.380079,0.245556,-0.239070,-0.033489,0.055377,0.341946,-0.156075,0.265131,-0.113221,-0.303748,-0.110619,-0.098268,-0.325709,0.287949,0.830797,-0.079649,-0.093064,-0.136216,0.456712,-0.346533,-0.190319,0.039670,0.279053,0.090603,0.045781,-0.008370,-0.147735,0.262723,0.077869,-0.320106,-0.560861,-0.052149,-0.007339,0.224335,-0.444916,0.567923,0.576975,-0.239516,0.447632,0.101393,0.166196,-0.094704,0.422781,0.580582,-0.343111,0.231662,-0.512962,0.082695,0.625484,-0.272386,-0.209346,0.361243,-0.159006,-0.210961,0.182258,0.022391,-0.413474,-0.204140,0.460230,0.088790,-0.207384,0.208242,-0.828029,-0.015836,-0.207890,0.122792,0.140837,-0.326015,-0.247183,-0.703462,-0.121642,-0.149178,-0.293598,0.087722,0.185417,-0.091165,0.826103,-0.907266,0.248825,0.546604,0.182413,-0.584839,0.513869,0.378983,0.051390,-0.100271,0.149505,0.050856,-0.052323,0.329334,-0.070317,0.380379,-0.097335,-0.106887,-0.570071,0.537047', '1296534', '21619567', '3811356', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26968024', '我是你妈', '剧情', '影片讲述了一对形同姐妹又骨肉情深的别样母女，不按套路出牌的单身辣妈秦美丽（闫妮 饰）与正处于叛逆期的女儿赵小艺（邹元清 饰）之间相“碍”相亲、陪伴成长，一系列欢脱又不失温情的故事笑中带泪，感动人心。', '闫妮', '张骁', 4.8, 13992, 'tt8399698', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2520372116.jpg', 17.8, 39.1, 31.9, 8.7, 2.5, '0.256835,0.057675,-0.312400,0.720797,0.075863,-0.228467,0.797666,0.360293,-0.207492,0.174612,0.001724,0.053879,-0.647970,0.576580,0.054500,-0.257679,-0.216432,-0.457826,-0.271376,0.360999,0.028455,-0.267342,-0.036886,0.108143,-0.134196,0.067137,0.366795,-0.039166,-0.232534,0.641698,0.334916,0.197604,-0.578312,0.283428,0.020350,0.065476,-0.253323,0.441013,-0.324763,-0.422904,0.123186,-0.360002,0.025536,-0.097633,-0.078388,0.396804,0.786880,-0.275020,0.079998,-0.070634,0.358838,0.126253,-0.350009,0.011542,0.329117,0.019055,0.336770,-0.282503,-0.048594,-0.074836,-0.278090,-0.422693,-0.651909,0.018403,0.414870,-0.009525,-0.088594,0.378698,0.035394,-0.094737,0.323128,-0.238122,0.000952,0.023933,0.709812,0.803809,0.088866,0.094398,-0.263722,0.414971,0.297108,0.398990,-0.113632,0.725622,-0.521029,-0.616700,0.005864,-0.308520,-0.548004,-0.007185,0.334001,-0.218246,0.299144,0.466163,-0.235256,0.118600,-0.090754,0.425169,-0.156490,-0.921420,0.104388,-0.245834,-0.410609,-1.132611,-0.452582,0.288783,0.363778,-0.203570,0.758483,-0.702692,0.084076,-0.178865,-0.151029,-0.765647,0.714948,0.567423,0.163944,-0.281964,-0.162311,0.540392,-0.492160,-0.600134,0.191815,0.382386,-0.654426,0.407955,-0.339569,0.082115', '26354526', '10833971', '25928069', '30389258');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26968495', '最后的诗句', '剧情', '对于阿施来说，千禧年夏天是最美好的年代。他遇见青春绽放的晓萍，一同牵手走过那缤纷的年纪，写下生命之诗的开头。面对未来的不确定性，两人总是乐观且有计画性的面对。直至一次阿施父亲到军营中的探访，改变了长久相处的共识，陷落○六年那躁动不安的时代氛围中。出社会后，现实的压力却磨损了原本美好的爱情，使阿施的离去成为不得不的现实，阿施与晓萍在艳阳下相爱，在日落时分开，再拥抱已是四年的时光飞逝，两人清澈的双眸已被岁月折磨地悄然黯淡，距离当年灿烂的身影已越发遥远……。历经波折后的重逢，能使他们再念起那首描述岁月静好的生命之诗吗？', '傅孟柏', '曾英庭', 7.7, 6385, 'tt6533250', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2433854930.jpg', 0.5, 3.1, 28.2, 49.7, 18.5, '0.290126,0.379319,-0.618981,0.505065,0.099346,-0.412673,1.023462,0.128178,-0.254868,-0.027534,0.153090,0.309594,-0.281110,0.403716,0.358523,-0.263398,-0.104958,-0.730549,-0.161977,-0.342763,-0.036789,-0.361620,-0.189649,0.177756,-0.077625,-0.395564,0.931573,0.613088,0.037445,0.554104,-0.063297,-0.060306,-0.050227,0.415455,-0.330169,-0.127812,-0.113527,0.573378,-0.577051,0.001366,0.060200,-0.432869,-0.166943,-0.026351,-0.457474,0.109865,0.836651,-0.328599,-0.272546,0.059807,0.639892,-0.120006,-0.243617,-0.012128,0.137968,0.069556,-0.008148,0.249562,-0.099741,-0.190777,-0.301439,-0.031074,-0.561308,0.211551,0.114691,0.084675,-0.510675,0.349998,0.319633,-0.136221,0.127333,-0.336316,0.226262,0.341489,0.585330,0.570990,-0.241419,0.099174,-0.314972,0.290743,0.891196,-0.056170,-0.817802,0.648381,-0.824456,-0.396813,-0.054796,-0.158905,-0.503103,0.007355,0.285913,0.113083,-0.210907,0.642896,-0.587737,0.273993,-0.129125,-0.043347,0.108224,-0.513053,-0.297962,-0.380362,-0.501647,-0.732924,-0.543843,0.312846,0.022926,-0.271656,0.661558,-0.477486,0.469333,0.387507,0.161930,-0.048853,0.793583,0.327674,0.047091,-0.062507,0.238734,0.965532,-0.456745,0.249837,-0.103912,0.171164,-0.290658,0.471369,-0.684447,0.693423', '1436768', '1296992', '1472510', '6039412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26969115', '霸主', '动作', 'J·J·艾布拉姆斯监制的科幻片、他的坏机器人制片公司的首部R级电影《霸王行动》发布海报，伞兵降落带着血腥。该片被很多影迷戏称为“《使命召唤》的僵尸模式”，讲述二战时期的诺曼底登陆遇上生化丧尸：诺曼底“霸王行动”前夕，美国伞兵深入敌人后方，执行一项对入侵的成功至关重要的任务。但当接近目标时，他们开始意识到，在这个纳粹占领的村庄里发生的事情比简单军事行动要复杂许多，他们将与超自然力量斗争，而这些是纳粹实验的一部分。', '约翰·艾德坡', '朱利叶斯·艾弗里', 6.6, 22221, 'tt4530422', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2533977336.jpg', 2.1, 11.4, 50.8, 28.5, 7.3, '0.487440,-0.161788,-0.654459,0.634113,0.040045,0.255953,0.701581,-0.285066,-0.308500,-0.223111,0.355970,0.794599,-0.091295,-0.416404,0.040774,-0.210768,-0.208127,-0.532622,-0.138314,0.092371,-0.229911,-0.327082,-0.457811,-0.329987,0.008632,-0.359589,0.996588,0.429167,-0.487609,0.235513,0.240683,0.286766,-0.189673,0.453013,0.059255,-0.212876,0.180460,-0.484161,-0.175394,0.487760,-0.201821,-0.069667,0.025007,0.223638,-0.154988,0.436703,0.858474,-0.233572,-0.344549,-0.278287,0.478132,-0.644783,-0.013131,0.237043,0.479138,0.498559,-0.179084,0.109320,0.240066,0.288529,-0.355314,-0.177332,-1.095483,-0.275285,-0.048583,0.188129,-0.527415,0.193378,-0.184632,0.476680,0.146445,-0.270423,0.275433,0.529605,0.333416,0.282609,-0.123411,0.194547,-0.572499,0.217854,0.750135,-0.409788,-0.308811,0.367523,-0.014303,-0.485340,-0.193375,-0.266435,-0.180143,0.033905,0.163637,-0.007643,-0.222459,0.383454,-1.007743,0.063068,-0.160132,-0.539633,-0.231160,-0.212698,-0.005418,-1.046705,-0.180082,-0.278771,-0.064602,0.147911,0.102998,-0.289407,0.835456,-0.853417,0.086374,0.801526,0.375562,-0.509349,0.306730,0.136389,0.144486,-0.360426,0.097393,0.097258,0.040871,0.484708,0.021399,0.299852,0.064789,-0.522635,-0.323045,0.487487', '2369613', '25928048', '25774050', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26969120', '你的鸟儿会唱歌', '剧情', '在郊外一家书店打工的“我”，与“我”同住一屋的静雄，以及“我”的同事佐知子。往来间，佐知子与“我”渐生暧昧，静雄对佐知子亦暗生情愫……互为朋友和恋人的三个年轻人，和一段带着夏日燥动的肆意青春。', '柄本佑', '三宅唱', 7.7, 20981, 'tt6515458', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2524186967.jpg', 0.5, 2.8, 27.7, 50.6, 18.4, '0.536051,-0.406324,-0.442314,0.693437,0.116168,-0.327325,0.969988,0.310650,-0.299724,-0.050086,-0.166792,0.827616,-0.341791,0.741395,0.323008,-0.188096,-0.088917,-0.863455,-0.174145,-0.173979,0.236872,-0.393076,-0.029886,0.097773,-0.237269,-0.194710,0.510568,0.057149,0.077565,0.820335,0.038338,0.189174,-0.913782,0.324800,-0.247516,-0.350771,-0.012202,0.481936,-0.631971,-0.134349,0.344246,-0.218293,-0.267014,-0.431706,0.099948,0.405169,0.814489,0.217727,-0.207233,0.272555,-0.051564,0.291225,0.143237,0.197731,-0.005713,-0.249275,0.299113,0.544956,-0.249105,-0.228867,-0.025678,0.099788,-0.297149,0.080689,0.003667,-0.178121,-0.313458,1.148308,0.272616,-0.226815,0.545634,-0.231637,0.102081,0.271007,-0.201954,0.577763,-0.323764,-0.168429,-0.298406,0.162448,0.688633,0.142870,0.193805,0.261346,-0.465208,-0.204372,-0.242372,0.558570,-1.018760,-0.331710,0.259167,-0.354893,-0.157548,0.093974,-1.195809,-0.095662,0.379614,0.172784,0.399143,-0.524079,0.203954,-0.658299,-0.055704,-0.945736,-0.326352,0.363856,0.802859,0.013630,0.665891,-1.085871,0.112124,0.650002,0.497032,-0.453373,0.886765,0.303283,0.227475,-0.196188,-0.389055,-0.025069,0.038224,0.234464,0.599822,0.707628,-0.326505,0.758268,-0.570553,-0.041536', '24839498', '3139191', '5279593', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26969244', '亲吻亭', '喜剧', '艾尔和李是实打实的发小，感情要好得不得了，不过艾尔喜欢上了李的哥哥，天下可能要大乱。影片是童星乔伊·金的转型之作，卡司还包括雅各布·艾洛蒂、乔尔·科特尼，莫利·林沃德也在本片客串。', '乔伊·金', '文斯·马塞洛', 6.7, 15731, 'tt3799232', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520915398.jpg', 2.3, 11.5, 46.5, 28, 11.6, '0.052603,-0.061073,-0.862255,0.553823,0.305992,-0.722188,0.612334,0.027002,-0.292013,-0.129801,-0.436561,0.450089,-0.270485,0.202457,0.323252,0.229731,-0.540885,-0.516552,-0.385584,-0.217032,-0.244113,-0.532157,-0.319356,-0.429645,-0.515000,-0.313171,0.125916,0.044117,-0.329626,-0.034474,1.052585,0.190248,0.511037,0.107759,0.073709,0.169099,-0.134801,-0.058555,-0.283864,0.280419,0.533262,-0.068766,-0.152489,0.283351,0.558515,0.160052,0.271187,0.094846,0.319536,0.301403,0.190160,-0.273662,0.319676,-0.199355,0.315662,-0.601874,0.210883,-0.377651,0.103327,-0.286807,0.181363,-0.344771,-0.611620,-0.067527,0.396209,0.133835,-0.793366,0.237183,-0.152984,-0.050987,-0.037811,-0.285755,0.095462,0.379836,0.548228,0.154000,0.237764,0.158514,-0.601970,0.375024,0.506355,0.344911,-0.138402,0.116064,-0.332745,-0.889834,-0.521346,-0.246470,-0.703749,0.005433,0.799086,-0.454214,0.544139,0.416530,-0.113623,-0.189046,-0.071174,-0.110536,-0.464621,-0.221529,0.673342,-0.390302,-0.097116,-0.723824,-0.101162,0.023669,0.102235,-0.526566,0.750023,-0.848648,0.461325,0.353120,0.095940,-0.268696,0.588778,0.355085,0.148057,-0.407054,-0.190562,0.082967,0.343541,-0.426416,0.438561,0.508779,0.361413,-0.503440,-0.266420,0.610089', '1306755', '26301735', '3074415', '26387939');
