INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26970964', '惊涛迷局', '科幻', '贝克（马修·麦康纳 Matthew McConaughey 饰）是一名渔船船长，生活在风平浪静的海边，每天都过着规律而重复的生活。曾经，贝克有过一段失败的婚姻，时至今日，这段婚姻还如同乌云一般笼罩在他的头上，他始终都没能够忘记前妻凯伦（安妮·海瑟薇 Anne Hathaway 饰）。让贝克没有想到的是，有一天，自己朝思暮想的凯伦竟然真的出现在了自己的眼前。可是，凯伦却提出了一个让贝克大跌眼镜的请求，那就是委托贝克杀死自己的现任丈夫弗兰克（杰森·克拉克 Jason Clarke 饰）。原来，弗兰克是一个性格恶劣脾气爆裂的男人，凯伦实在无法忍受日日受欺压的生活了，才出此下策。面对前妻声泪俱下的请求，贝克会做出怎样的回答呢？©豆瓣', '马修·麦康纳', '斯蒂文·奈特', 6, 19666, 'tt6476140', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2577342316.jpg', 2.8, 20.6, 55.8, 18.1, 2.9, '0.158809,-0.149161,-0.835908,0.748842,-0.347054,-0.407993,0.967097,0.051001,-0.523507,-0.360505,0.456653,0.687142,-0.374709,0.344108,0.226105,0.201454,-0.083071,-0.660308,0.033761,-0.168792,-0.183842,-0.653723,-0.329111,-0.167821,-0.013977,-0.415561,0.412653,-0.233811,-0.004967,0.216086,0.464416,0.286313,0.357952,0.508472,-0.250488,0.118268,0.184777,0.260719,-0.053883,0.007701,0.144835,-0.202210,-0.038418,0.375576,-0.025926,0.446456,0.427165,-0.306818,-0.392142,0.039390,0.305863,-0.366569,0.074022,0.164816,0.261449,-0.344468,0.037142,0.285323,-0.305036,-0.115136,0.220520,0.191108,-0.796666,0.130617,-0.184893,0.192279,-0.817253,0.352922,-0.062824,-0.171020,-0.056695,-0.502083,0.071753,0.292405,0.340475,0.439672,-0.175343,0.101729,-0.607925,0.208016,0.882865,0.024362,-0.579309,0.390594,-0.531573,-0.063648,-0.021653,-0.198339,-0.822465,0.027373,0.036212,-0.069535,-0.382065,0.246977,-0.305190,0.074118,-0.421794,-0.370457,-0.016339,-0.338229,-0.252012,-0.458670,-0.133675,-0.625968,-0.408817,-0.035473,-0.208313,-0.305173,0.486796,-0.785303,0.379277,0.547129,0.266851,-0.491755,0.686047,0.764713,-0.180667,0.000848,-0.053176,0.439911,0.172821,0.103162,0.132798,0.071901,0.427129,0.069674,-0.148791,0.654736', '4275444', '25763555', '2075721', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26971054', '为家而战', '剧情', '拉亚（佛罗伦斯·珀 Florence Pugh 饰）和哥哥扎克（杰克·劳登 Jack Lowden 饰）生活在一个美满而幸福的家庭之中，兄妹两人之间的感情也十分要好。父母对兄妹两人最大的期望就是他们有朝一日能够参加WWE比赛，让这家人想不到的是，他们的梦想竟然有朝一日成真的。WWE的教练哈奇（文斯·沃恩 Vince Vaughn 饰）邀请拉亚和扎克去参加选拔赛，在比赛现场，两人遇见了他们的偶像巨石强森（道恩·强森 Dwayne Johnson 饰）。比赛结果出来了，拉亚被选中，而扎克不幸落选。就这样，拉亚改名为佩奇，前往弗罗里达州开始了训练，可是，高强度的练习和个性迥异的队友们让拉亚感到非常的不适应，甚至萌生了放弃的念头。©豆瓣', '道恩·强森', '斯戴芬·莫昌特', 6.3, 8164, 'tt6513120', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2580002742.jpg', 1.2, 12.3, 60.4, 21.9, 4.1, '0.254875,-0.319219,-0.700165,0.687276,-0.107549,-0.523511,0.483717,0.067940,-0.724427,-0.201891,0.111431,1.016068,-0.351484,0.057735,0.415948,0.147700,-0.320502,-0.821207,-0.040253,-0.164123,-0.136589,-0.580788,-0.044012,-0.266498,-0.175311,-0.307058,0.548983,-0.019657,-0.052368,0.696259,0.185768,0.326170,0.271091,0.254952,-0.005228,-0.048287,0.180251,0.127797,-0.502981,0.377269,0.029447,0.269395,-0.285104,0.252285,0.189133,0.166759,0.460112,-0.219480,0.056555,0.034701,0.031077,-0.429284,0.067798,0.312314,0.084923,-0.180001,0.427342,0.123311,-0.211054,0.068994,0.136441,-0.128273,-0.634147,0.319471,0.110508,0.045841,-0.666614,0.528911,-0.062119,-0.288431,0.252139,-0.307413,0.126738,0.465556,0.334659,0.399168,-0.229429,-0.339070,-0.497816,-0.122219,1.026966,-0.134279,-0.150057,0.111798,-0.196832,-0.427262,-0.072492,-0.070229,-0.487874,0.018317,0.194895,0.112396,-0.099849,0.367191,-0.746265,0.068276,-0.397560,-0.139305,-0.063441,-0.589673,0.269718,-0.947008,0.029061,-0.320352,-0.499218,0.127577,-0.074839,-0.527699,0.807410,-1.134529,0.249811,0.317629,0.356090,-0.361478,0.638757,0.185960,0.146512,-0.203265,-0.015249,-0.002982,-0.035505,-0.098999,0.209506,0.503374,0.149517,-0.138091,-0.353778,0.662428', '11541282', '35030151', '1292219', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26971645', '蓝色生死恋', '爱情', '电影《蓝色生死恋》根据经典IP电视剧改编，二十年之后以电影形式重回大众视野，讲述了两个同天出生的女孩儿因无意间被掉包，从而牵连出几位主角间命运的错位和爱情的纠葛的故事。', '许凯', '王才涛', 2.7, 13719, 'tt9626928', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2545498793.jpg', 73, 19.4, 5.8, 1.2, 0.6, '0.349754,0.377737,-0.252521,0.752918,0.696650,-0.138083,1.032027,0.182564,-0.339427,-0.497659,0.064456,0.764482,-0.650287,0.137787,0.385818,-0.240396,-0.345854,-1.070462,-0.310818,-0.163289,-0.145544,-0.189002,-0.274645,0.158013,0.092651,-0.600140,0.897212,0.158257,-0.737284,0.160057,0.310901,0.186655,-0.647199,-0.576997,0.156011,0.266636,-0.225836,0.301012,-0.574846,0.023300,-0.242400,-0.371576,0.158929,-0.147261,-0.766125,0.342489,1.168744,-0.403224,-0.283455,-0.073332,1.105996,0.070998,-0.429192,-0.130494,0.303958,0.297869,0.674398,0.419461,-0.011724,0.061485,-0.325237,-0.113161,-0.900821,-0.113577,0.006200,0.387071,-0.314944,0.390361,0.187855,-0.043585,0.209815,-0.104854,0.158864,0.156779,0.953649,0.620642,-0.240913,-0.113413,-0.158565,0.736692,0.615466,0.056698,-0.299139,0.763779,-0.033487,-0.234992,-0.442075,-0.021830,-0.379667,0.655371,0.813273,-0.123926,-0.230414,0.822736,-0.670951,-0.107444,-0.079165,-0.215607,0.416793,-0.474695,0.128917,-1.005047,-0.558408,-0.249626,-0.237762,-0.213926,-0.005983,-0.366876,0.949260,-0.348023,0.160249,0.484830,-0.371740,-0.813349,0.823612,0.142531,0.256395,-0.285227,0.301707,0.202718,-0.041396,0.021104,0.088913,0.221766,-0.120424,-0.021314,-0.493513,0.439512', '1322847', '22265121', '26823520', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26972258', '江湖儿女', '爱情', '故事开始于2001年的山西大同，巧巧（赵涛 饰）和斌斌（廖凡 饰）相恋多年，巧巧一心希望能够和斌斌成家过安稳的生活，但斌斌身为当地的大佬，有着自己更高远的志向。一场意外中，斌斌遭人暗算危在旦夕，巧巧拿着斌斌私藏的手枪挺身而出救了斌斌，自己却因为非法持枪而被判处了五年的监禁。一晃眼五年过去，出狱后的巧巧发现整个世界都发生了翻天覆地的变化，唯一不变的是她对斌斌真挚的感情。巧巧跋山涉水寻找斌斌的下落，但此时的斌斌早已经失去了往日的锋芒，而且身边已有了新的女友。身无分文的巧巧靠着自己的智慧摸爬滚打，终于为自己挣得了一片天地。©豆瓣', '赵涛', '贾樟柯', 7.6, 278331, 'tt7298400', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2533283770.jpg', 0.6, 3.3, 29, 50.1, 17, '0.203404,0.035692,-0.800183,0.418839,-0.126537,-0.299751,0.503781,-0.001830,-0.282263,-0.292964,0.023608,0.671162,-0.128878,0.452283,0.033966,-0.128535,-0.068160,-1.102706,-0.113473,-0.394860,-0.438819,-0.417400,-0.169089,0.069933,-0.248412,0.081184,0.594874,0.167189,0.203183,0.697166,0.116827,0.219353,0.081795,0.455351,-0.352565,0.142589,-0.183846,0.212230,-0.249289,-0.170387,0.377718,-0.439270,-0.241545,0.738157,-0.140833,0.393259,0.652058,-0.256927,-0.303895,0.001578,0.361958,-0.195264,-0.224406,-0.350339,0.418317,-0.051709,-0.062717,0.456179,-0.099196,0.036471,-0.162638,-0.161293,-0.682415,-0.186921,0.049052,-0.016262,-0.641373,0.496841,0.172547,0.149162,-0.065190,-0.215757,0.234686,0.504233,-0.106941,0.483208,-0.319586,0.260159,-0.469586,0.177223,0.568639,-0.249598,-0.419761,0.667249,-0.247659,-0.032096,-0.065235,-0.248839,-0.507819,0.098405,0.166642,-0.009412,-0.180605,0.200673,-0.463424,0.040346,-0.419039,0.115600,0.057668,-0.091765,-0.305645,0.045871,-0.270735,-0.608565,-0.406326,0.174344,-0.192491,-0.593264,0.792455,-0.756982,0.119976,0.132372,0.139061,-0.679323,0.479254,-0.194279,0.274245,-0.071146,0.125983,0.178002,-0.112283,0.189017,0.394643,0.152439,-0.303770,-0.123779,-0.419303,0.298783', '26809007', '26263428', '1307146', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26972275', '恋爱回旋', '喜剧', '富田多满子（新垣结衣 饰）的母亲是一名十分优秀的乒乓球运动员，在母亲的严厉教导下，多满子的整个童年都在天才乒乓球少女的荣光之下度过。然而，多满子却并不是真心喜爱这项运动，于是，母亲过世后，她便彻底放飞了自我，就此远离了球桌。随着时间的推移，多满子平凡的长大成为了一名OL，并且遇见了名为江岛晃彦（濑户康史 饰）的男子，两人走到了一起。然而，美梦是短暂的，第三者的出现让多满子和江岛之间的恋情画上了句号，与此同时，多满子辞掉了工作，灰头土脸的返回家乡，在那里，母亲留下的经营不善的乒乓球俱乐部等待着她的接手。©豆瓣', '新垣结衣', '石川淳一', 7, 78844, 'tt4265596', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2515437624.jpg', 0.8, 6.3, 47.6, 35.1, 10.4, '0.277688,0.210271,-0.635928,0.607087,-0.242852,-0.461513,0.682520,0.270826,-0.493943,-0.254252,0.200322,0.841473,-0.148701,0.555861,0.324694,-0.013428,-0.179194,-0.863016,-0.271760,-0.120509,-0.341482,-0.502876,-0.012004,-0.044578,-0.196035,-0.282561,0.856637,0.097335,0.054025,0.598709,0.207412,0.062448,-0.055808,0.446856,-0.327233,0.268873,0.136437,0.125358,-0.131297,0.216722,0.019025,-0.390209,0.030091,-0.011350,-0.060515,0.116908,0.728182,-0.237724,-0.092804,-0.088595,0.465434,-0.335252,-0.157664,0.119548,0.366989,0.112747,0.183667,0.222451,-0.406059,0.162020,0.032761,-0.123842,-0.530653,0.063802,0.047969,0.273661,-0.793261,0.694395,0.020041,-0.300862,0.135039,-0.409724,0.274110,0.354758,0.091372,0.437790,-0.302481,0.274476,-0.214219,0.245018,0.796996,0.186215,-0.394596,0.406119,-0.204059,-0.377764,-0.097050,-0.335990,-0.238036,-0.261465,0.247426,0.287848,-0.095959,0.108329,-0.540371,0.105202,-0.264505,-0.282984,0.163588,-0.506409,-0.116444,-0.481194,0.039404,-0.509031,-0.587465,0.206988,-0.192996,-0.301282,0.908583,-0.899608,0.343918,0.517924,0.159133,-0.279874,0.601838,0.103861,0.385498,-0.056831,0.136848,0.228077,-0.127327,0.502943,-0.026840,0.336467,-0.301732,-0.064895,-0.651050,0.508754', '1826173', '35030151', '1292219', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26974334', '追凶十九年', '剧情', '1999 年始的数年内，一向安宁平静的弘州市先后发生多起针对年轻女性的强奸命案，受害者的皮肤均遭凶手割下奇异的血雏菊形状。负责侦破这场惊天连环凶杀案件的重任，则交到了警察刘一波，和搭档何晨的肩上。而这场斗智斗勇的追凶之旅，一追就是十九年……', '王龙正', '徐翔云', 5.5, 11944, 'tt11151764', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2572147897.jpg', 8.2, 29, 45.5, 13.1, 4.3, '0.132781,-0.281436,-0.470609,0.310827,-0.105234,0.013341,0.609709,0.027163,-0.173489,-0.041129,0.549591,0.501238,-0.255301,-0.004905,0.470211,-0.097945,-0.006893,-0.856338,-0.493277,-0.012856,-0.462705,-0.356969,-0.296802,0.051803,0.176854,-0.104593,0.505290,0.120482,-0.137033,0.598902,0.671861,0.291821,-0.484206,-0.024655,0.092369,-0.184022,0.023910,0.141793,-0.343590,0.049235,0.064074,-0.459783,-0.058734,0.089576,-0.105757,0.475088,0.760330,-0.302385,-0.017264,-0.387557,0.585250,-0.314359,-0.181644,-0.122103,0.720921,0.255268,0.231096,0.491471,-0.261710,-0.161537,0.216408,-0.168069,-0.708965,-0.101464,0.237713,0.255741,-0.290811,0.207847,0.024252,0.211865,0.116981,-0.226229,0.227536,0.437286,0.225118,0.321460,-0.147235,0.022329,-0.126967,0.272875,0.802776,0.009946,-0.222085,-0.145001,-0.117662,-0.197842,-0.078627,-0.286049,0.011036,0.094256,0.446055,-0.265669,-0.055073,0.424746,-0.323969,0.084122,-0.336459,-0.015329,-0.004429,0.079071,-0.364839,-0.462380,-0.178245,-0.397222,-0.235920,0.110387,0.268365,-0.261007,0.143209,-0.467714,0.059720,0.474216,-0.182473,-0.208009,0.073415,0.238024,0.350124,-0.059526,-0.365148,-0.101317,0.261904,0.450732,-0.002137,0.364711,-0.098950,-0.264696,-0.302249,0.055163', '1306449', '1306454', '25919961', '30347029');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26976399', '拍栗得', '剧情', '该片由拉斯·克莱夫博格执导，讲述一个高中女生无意间发现了一台老式“拍立得”相机中隐藏的黑暗秘密：任何接触这台相机的人都会离奇死亡。', '凯瑟琳·普雷斯科特', '拉尔斯·克列夫伯格', 5.7, 6069, 'tt5598292', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2557233502.jpg', 4.7, 25.4, 55, 11.5, 3.5, '0.388848,-0.159535,-0.426621,0.240519,0.063354,0.206479,1.105062,-0.127085,-0.580942,-0.239613,0.708923,0.568887,-0.227228,-0.271037,0.106861,0.090316,-0.786150,-0.607642,-0.147244,0.082453,-0.482648,-0.257087,-0.770415,-0.377942,0.111463,-0.170675,0.256414,-0.228587,-0.417836,-0.011203,0.169415,0.079781,-0.576793,0.134264,0.260930,-0.121399,0.283583,-0.298465,0.120821,0.328379,-0.636773,-0.193349,0.193421,0.176287,-0.283222,0.608880,0.493378,-0.180066,-0.097668,-0.031398,0.446645,0.173378,-0.106039,-0.120627,0.057140,0.398267,0.158933,-0.020006,-0.326199,0.151677,-0.082388,0.149396,-0.798827,-0.109400,-0.063915,0.334589,-0.161390,0.221924,-0.132155,-0.047919,0.036577,-0.079093,0.425413,-0.070579,0.387412,0.045482,0.182391,-0.145196,-0.136256,0.401185,-0.116471,-0.729411,-0.286965,0.304384,0.150416,-0.440084,-0.504556,-0.036737,-0.799465,0.247982,0.609858,0.325654,-0.121202,0.305607,-0.437549,0.178792,-0.350654,-0.111642,-0.046366,-0.291841,-0.131799,-0.897022,-0.231556,0.038150,-0.292918,-0.191181,0.040812,-0.299450,0.365875,-0.233946,0.315226,0.355158,-0.057603,0.386857,0.478035,-0.241029,-0.127278,0.049588,0.047207,0.719859,0.403185,0.270494,-0.412062,0.292459,0.257855,-0.304136,-0.064734,0.483483', '1316693', '10466639', '1578663', '1291554');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26979007', '九三年夏天', '剧情', '故事发生在1993年的夏天，女孩弗里达（莱娅·阿蒂加斯 Laia Artigas 饰）的母亲因病不幸去世，留下可怜的小姑娘无人照顾。弗里达的舅舅埃斯特维（大卫·维达古尔 David Verdaguer 饰）和舅母玛尔加（布鲁娜·库希 Bruna Cusí 饰）收留了无家 可归的弗里达，但这也意味着，弗里达必须离开出生成长的大城市，习惯乡村的生活。弗里达很快就融入了多姿多彩的有趣乡村生活中，善良的埃斯特维和温柔的玛尔加渐渐让弗里达重新感受到了家庭的温暖。可是即便如此，弗里达还是非常的想念自己的母亲，她将所有的思念之情都寄托在了神像上，希望神像能够重新恢复她和母亲之间的联结。©豆瓣', '莱娅·阿蒂加斯', '卡拉·西蒙', 7.9, 14418, 'tt5897636', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2447442755.jpg', 0.5, 1.5, 21.4, 55.2, 21.5, '0.303214,-0.242318,-0.490042,0.302475,-0.196711,-0.528120,0.695491,0.668521,-0.773146,-0.236363,0.119511,0.720746,-0.102584,0.156241,0.243546,0.216087,-0.588116,-0.617251,0.025288,-0.308076,0.098110,-0.467548,-0.238269,0.133875,-0.201220,-0.482753,0.337566,-0.038234,0.220311,0.374671,-0.209546,0.484663,0.077786,0.637696,-0.243388,-0.060778,-0.189876,-0.266702,-0.216207,0.050598,0.005489,0.254328,0.230255,-0.239233,-0.084429,0.271664,0.587021,-0.235445,-0.063146,-0.145113,0.411953,0.326408,0.004939,0.093019,0.036034,-0.137904,-0.163208,0.282249,-0.496814,-0.213887,-0.001688,-0.214564,-0.677427,0.139507,0.113786,0.109694,-0.674764,0.292751,0.025979,-0.354899,0.348837,-0.132833,-0.022829,0.414107,-0.046351,0.544228,-0.224387,0.159630,-0.700130,-0.117782,0.580207,-0.245918,-0.189665,0.281319,-0.453365,-0.382714,-0.046137,-0.290544,-0.600340,0.086512,-0.213061,0.276829,-0.111469,0.524791,-0.544539,0.089208,-0.450897,-0.243503,0.244769,-0.403142,-0.035988,-0.391769,-0.305693,-0.460101,-0.841466,-0.656883,-0.065002,-0.356676,0.877235,-0.636232,0.462487,0.554739,0.548192,0.210688,0.674859,0.007872,0.081931,-0.115449,-0.010521,0.883702,-0.109003,0.355836,0.315063,0.160286,-0.034608,-0.023109,-0.020070,0.880236', '1291852', '1460341', '1292720', '3504940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26979199', '喜欢，轻吻，快跑', '剧情', '雅克（皮埃尔·德·兰登尚朴 Pierre de Ladonchamps 饰）是一名风格放荡不羁的作家，奉行着享乐主义的人生信条。一次偶然中，他结识了名为亚瑟（文森·拉寇斯 Vincent Lacoste 饰）的男孩，虽然亚瑟比雅克要年轻很多，但这并不妨碍两人度过了浪漫的一晚。经过这一晚，单纯的亚瑟深深的爱上了雅克，然而，雅克经历过太多的感情上的挫折了，他根本不相信这个年轻的小伙子对自己是真爱。一天，雅克震惊的得知自己的前男友死于艾滋病，这也就意味着他很可能也被传染上了，病痛的折磨之下，脆弱的雅克卸下心防，同意了亚瑟搬来照顾他的请求。©豆瓣', '文森特·拉科斯特', '克里斯托夫·奥诺雷', 7.8, 25333, 'tt7534054', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2527725378.jpg', 0.6, 2.7, 25.2, 47.9, 23.6, '0.581550,0.089807,-0.669306,0.394413,-0.258964,-0.498794,1.019847,-0.110915,-0.568848,-0.158672,0.152881,0.650911,-0.097563,0.328748,0.313556,0.155231,-0.336122,-0.456888,0.009116,-0.092046,-0.320786,-0.549701,-0.392469,-0.102819,-0.166403,-0.342198,0.357447,0.190706,-0.095821,0.416729,0.390022,0.389586,0.539251,0.643231,-0.141527,0.024307,0.042128,0.026335,0.011158,0.116019,0.106280,-0.295133,0.051991,0.540032,-0.154929,0.425629,0.347715,-0.309916,-0.290686,-0.110516,0.369880,-0.262646,-0.032053,0.249754,0.098433,-0.116681,0.118255,0.338768,-0.060229,0.004727,0.047905,0.044750,-0.696491,-0.134167,0.126898,0.204377,-0.777763,0.778568,-0.098507,-0.220316,-0.289914,-0.229683,0.065617,0.294112,0.234290,0.320042,-0.081816,-0.001480,-0.626845,0.167899,0.824584,0.016337,-0.408440,0.507524,-0.536086,-0.492930,-0.051052,-0.326473,-0.690250,0.109868,0.241977,-0.019547,-0.338816,0.156619,-0.439575,0.144323,-0.313563,0.005662,-0.334242,-0.284245,0.048274,-0.318516,-0.219149,-0.892627,-0.705374,-0.128486,0.003732,-0.451298,0.740920,-0.843071,0.280388,0.590865,0.225320,-0.310620,0.694672,0.536093,-0.004252,-0.076816,0.019179,0.486448,-0.123580,0.024456,0.109416,0.593964,0.213656,-0.169887,-0.307145,0.834499', '1307561', '3443074', '3742987', '1292062');
