INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26980827', '那就是我的世界', '剧情', '执笔过电影《逆鳞》的崔成贤作家的导演处女作，讲述已经风采不再的拳击选手出身的哥哥和有着肢体障碍的天才钢琴家弟弟之间的故事，李秉宪饰演哥哥，朴正民饰演弟弟，尹汝贞饰演妈妈一角，韩志旼将帮助朴正民的角色。电影由CJ投资发行，5月末开拍。', '李秉宪', '崔成贤', 7.9, 8474, 'tt6985200', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2508367896.jpg', 0.4, 1.8, 26.6, 47.2, 24, '-0.329165,-0.518241,-0.027380,0.789274,0.402493,-0.026321,0.485825,0.517893,-0.177368,-0.436114,0.419230,0.703465,-0.260519,0.108716,0.456554,-0.379675,-0.262860,-0.793064,-0.111907,0.131199,0.325037,-0.228333,-0.214573,0.349310,-0.057781,-0.675947,1.380275,-0.623252,-0.398434,0.475786,0.560257,-0.054371,-0.217648,-0.267743,0.285951,0.164167,0.131965,0.276648,-0.857033,0.483535,0.014417,0.072487,-0.010842,-0.182908,-0.125818,0.206932,0.575798,-0.000198,0.205208,-0.036206,0.737453,-0.077276,0.128487,-0.300151,0.310442,0.338225,1.113903,0.294219,0.362691,0.030394,-0.365865,-0.676995,-0.750798,-0.023403,0.748088,0.247689,-0.480378,0.304285,-0.209494,0.055888,0.125617,-0.254503,0.178935,-0.110780,0.474244,0.430019,-0.227655,0.366692,-0.002933,0.637627,0.332251,0.169224,0.149089,0.716712,0.154073,-0.409766,-0.414088,-0.407755,-0.464744,0.546022,-0.117858,-0.305924,-0.017242,0.244441,-0.326051,-0.163274,0.342990,0.146452,0.376901,-0.332317,0.323445,-0.634021,-0.214541,-0.131618,0.487000,-0.204053,0.224359,-0.530121,1.167585,-0.728999,0.112924,0.130151,0.377032,-0.187310,1.027162,0.276078,-0.098329,-0.546191,0.179384,0.055012,-0.215542,-0.367965,-0.255449,-0.002226,0.013418,-0.543066,-0.266294,0.303626', '25880986', '1322847', '30391300', '30349667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26981165', '宝莱坞机器人2.0：重生归来', '动作', '印度某市，所有人的手机突然被来自天空的神秘力量席卷吸走，手机销售大亨、电信运营老板、国家电信部高官等与手机相关的许多人相继离奇死去；城市上空，巨型变异鸟怪（阿克谢•库玛尔 饰）突然出现，大开杀戒，向所有手机用户宣战，民众陷入恐慌……危机时刻，科学家瓦西博士（拉吉尼坎塔 饰）在美女助理妮娜（艾米•杰克逊 饰）的帮助下，一路追踪事件真相，但后果已无法挽回，能够拯救人类的唯一方法只有——重启机器人“七弟”，他将如何变身新一代超级英雄，与这股亦正亦邪的势力开启昏天黑地、脑洞大开的鏖战？......', '拉吉尼坎塔', 'S·尚卡尔', 5.4, 14225, 'tt5080556', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2565512707.jpg', 9, 32.7, 42.9, 12.3, 3.1, '-0.040146,0.134507,-0.427030,0.195709,0.247569,0.038200,0.446973,0.175933,-0.483971,-0.290165,0.261980,0.475104,-0.239851,-0.244461,0.274305,-0.047033,-0.323591,-0.683153,-0.143892,-0.007901,-0.139330,-0.126049,-0.310898,-0.323937,0.142713,-0.400939,0.659753,0.163478,-0.273510,0.011501,-0.004606,0.486718,-0.506951,0.632632,-0.078964,-0.127723,0.087735,-0.314396,-0.351490,0.288796,-0.285969,-0.134115,0.057798,0.195392,-0.259898,-0.108190,0.378524,-0.379459,-0.016134,-0.327911,0.330186,-0.084849,-0.199680,0.034056,0.496261,0.200267,0.223344,-0.213706,-0.089612,-0.292966,0.133777,0.067767,-0.555807,-0.137179,-0.090744,0.229077,-0.278182,-0.163085,-0.283198,0.175082,0.132238,-0.227260,0.143290,0.312785,0.256594,0.350044,-0.067125,0.196230,-0.351629,-0.039705,0.322564,0.000699,-0.455070,-0.126458,0.030011,-0.478728,-0.328471,-0.056670,-0.465943,-0.030186,0.380711,0.111123,0.097173,0.637963,-0.716648,0.111218,-0.378974,-0.475387,-0.070651,-0.276770,-0.287094,-0.670526,-0.286512,0.189583,0.041175,0.129721,0.335517,0.088232,0.721940,-0.663973,0.059554,0.395478,0.218719,-0.128679,0.346316,-0.356250,-0.014142,-0.370006,-0.168760,0.219535,0.128517,0.675317,-0.091121,-0.026931,-0.068863,-0.128124,-0.093435,0.167263', '20274039', '25723905', '2369613', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26981174', '你好布拉德', '剧情', '布拉德（本·斯蒂勒 Ben Stiller 饰）一直以来都是一名坚定的理想主义者，如今，他和妻子梅兰妮（珍娜·费舍 Jenna Fischer 饰）共同抚养着儿子特洛伊（奥斯汀·艾布拉姆斯 Austin Abrams）饰，与此同时，他还在经营着一家非营利性的组织，该组织专门在有需要的人和资本家之间牵线搭桥，帮助这些人获得资本的支持。某日，布拉德开始审视自己的这大半辈子，忽然产生了自己一文不值的感觉。他觉得他这么多年来所有的理念，所做出的的全部努力都没有任何的意义。他不能给人带来实质性的帮助，同时也无法给家人带来更优渥的生活条件，而和他同龄的那些大学同学们现在都成为了各领域内的中坚分子。布拉德的整个人生都被自己否定了。©豆瓣', '本·斯蒂勒', '麦克·怀特', 7.8, 16120, 'tt5884230', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2497190395.jpg', 0.4, 2.2, 26.3, 49.4, 21.7, '0.268128,0.086503,-0.953910,0.917264,-0.427179,-0.232249,0.627706,0.179940,-0.676434,-0.269528,0.012476,0.825945,0.176381,0.208001,0.086276,-0.088025,-0.272326,-0.882355,-0.200006,-0.265445,-0.306137,-0.560869,-0.331383,-0.410516,-0.388748,-0.362487,0.482649,-0.139437,-0.195232,0.153601,0.345591,0.412615,0.463180,0.591283,-0.268075,0.194859,0.107170,-0.085046,-0.223528,0.093720,0.072311,-0.078984,-0.171621,0.544135,-0.020965,0.246762,0.572473,-0.203765,-0.257035,-0.226089,0.245161,-0.217519,0.133529,0.240184,0.195143,0.005394,0.301779,0.362471,-0.170809,0.118153,0.341718,-0.096608,-1.295838,-0.267830,0.093980,0.253644,-0.868431,0.594848,0.036897,-0.200913,-0.024739,-0.317163,0.116630,0.526236,0.087628,0.321310,-0.431848,-0.022862,-0.617256,0.412135,1.008848,-0.063577,-0.346621,0.213728,-0.573460,-0.327413,-0.110096,-0.257439,-0.528422,-0.147217,0.208627,0.268447,-0.136762,0.418407,-0.642754,0.171964,-0.050023,-0.398696,0.126035,-0.805381,0.297168,-0.573687,-0.283557,-0.668690,-0.439009,0.292378,0.168231,-0.421784,1.056222,-1.034775,0.128468,0.493057,0.481880,-0.674195,0.725932,0.177065,0.250092,-0.049234,-0.411496,0.043917,0.029620,0.474137,0.209257,0.333941,0.307977,-0.034684,-0.131311,0.569534', '30163500', '25917239', '1793491', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26981442', '深海异兽', '动作', '一场惊天动地的大地震，让设在海平面下的实验室危在旦夕！一场毁灭性的地震，让6名驻扎于海底的研究人员受困于即将被淹没的研究设施，唯一的生存之路竟然只剩下徒步经由海底平面走到遥远的废弃钻井台。在这充满挑战的旅途中，他们很快就意识到，除了得依靠简陋装备克服缺氧危机，某种前所未见、致命的海底掠食者已被唤醒，并将他们当作猎物般的追击扑杀…', '克里斯汀·斯图尔特', '威廉·尤班克', 6, 22754, 'tt5774060', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2566250216.jpg', 3.6, 21.7, 52.5, 16.6, 5.5, '0.143842,-0.005559,-1.032111,0.586504,0.005388,0.192264,0.940597,-0.131075,-0.109329,-0.091030,0.520542,0.728969,-0.188173,-0.188471,0.288699,-0.423008,0.003979,-0.502751,-0.507801,-0.041602,-0.753685,-0.180883,-0.514125,0.008981,0.007440,-0.316151,0.829490,0.622218,-0.577747,0.333261,-0.323320,0.280264,-0.371545,0.717618,-0.202266,-0.224912,-0.311971,0.070236,-0.228740,0.268723,-0.287933,-0.277544,0.044421,0.223650,-0.201247,0.325804,0.783092,-0.570584,-0.136498,0.068611,0.154519,-0.537849,0.015684,0.097218,0.339812,0.022427,-0.284416,-0.145102,-0.543238,0.265458,0.251705,-0.075521,-0.831463,-0.171431,-0.052427,0.018336,-0.400443,0.367357,0.357632,-0.137467,0.005176,-0.189943,0.176793,0.233001,0.134670,0.708404,-0.399167,-0.015793,-0.403723,-0.043705,0.830440,-0.302310,-0.499330,0.135157,0.050280,-0.474872,0.095968,-0.329883,-0.069849,-0.313348,0.415779,0.379559,-0.304013,0.315137,-0.855818,0.304657,-0.333323,-0.732404,-0.264283,-0.391218,-0.347702,-0.835519,0.119118,-0.151172,0.061632,0.479878,0.309617,-0.244063,0.353040,-0.337355,0.288605,0.788664,0.074435,-0.200091,0.463289,-0.301019,0.244262,0.125256,0.028219,0.285244,0.026536,0.973435,0.177698,0.421409,-0.221304,0.021590,-0.773777,0.616871', '1473795', '3011051', '1295292', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26984538', '卧底巨星', '喜剧', '动作巨星元豹（陈奕迅 饰）走红二十余载却从未得到过最佳男主角，因与泰国黑帮老大“八面佛”交好而被怀疑参与跨国贩毒犯罪，铁杆迷弟铁柱（李荣浩 饰）通过擅长“潜规则”的副导（崔志佳 饰）潜入元豹新电影的剧组，努力配合警方收集证据想为偶像洗脱嫌疑。在经历了恋上女一号童童（李一桐 饰），得罪元豹经纪人泰格（陈国坤 饰），晋升成为男二号，目睹偶像用替身、耍大牌等一系列啼笑皆非的“娱乐圈初体验”之后，铁柱也终于离案件更近了一些……', '陈奕迅', '谷德昭', 3.5, 19383, 'tt7263974', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2508908269.jpg', 47.8, 34.7, 14.6, 1.9, 1.1, '-0.039827,-0.098845,-0.328498,0.261089,0.261431,-0.060923,0.214609,0.130196,-0.482219,-0.344218,0.223777,0.431916,-0.428509,-0.369451,0.207942,-0.399523,-0.174499,-0.679081,0.311806,-0.086077,0.186882,-0.199688,-0.438563,0.150236,-0.301989,-0.290596,0.782000,-0.129465,-0.424698,0.409617,0.739979,0.111293,-0.118487,-0.220112,0.094127,0.015938,0.287857,0.030915,-0.755802,0.322436,-0.041045,-0.193857,-0.067138,0.136846,-0.016678,0.212854,0.312113,-0.001310,-0.134220,-0.021812,0.380444,-0.340006,0.004818,0.058270,0.365767,0.382170,0.359573,0.519114,-0.133103,0.082647,0.019391,0.027449,-1.033950,0.099105,0.403213,0.165790,-0.239305,0.013185,-0.201080,-0.075177,0.122955,-0.074711,0.170084,0.197100,0.596738,0.027355,-0.104004,0.286699,-0.025889,0.582834,0.473497,0.107334,0.177596,0.313268,0.368465,-0.193442,-0.084126,-0.306215,-0.221947,0.238164,0.009771,-0.201211,-0.020475,0.102066,-0.434191,-0.134071,-0.254382,0.082192,0.221588,-0.128754,0.093447,-0.696513,-0.278365,0.067085,0.034155,-0.286584,0.042025,-0.519648,0.466556,-0.664764,0.115624,0.578212,0.259348,-0.763307,0.482669,0.084262,-0.062310,-0.451117,-0.208614,-0.037292,0.103276,0.108147,-0.106349,0.008470,-0.143859,-0.761254,-0.113569,-0.239155', '27073234', '1468527', '25918677', '4301278');
