INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26985839', '魔发精灵2', '动画', '讲述Poppy和Branch有了一个惊人的发现——除了他们之外，还有其他的魔发精灵世界，各部落的明显差异导致了巨大的冲突。当一种神秘的邪恶力量让所有的精灵世界都面临危险时，Poppy和Branch以及朋友们将踏上一段史诗般的探寻旅程，在长期不和的各精灵族群中创造和谐氛围，让大家团结起来对抗某种厄运。这部片的音乐风格将更加多样化，流行音乐、乡村音乐、嘻哈音乐、硬摇滚、骤停打击乐、电子舞曲等都有。', '安娜·肯德里克', '沃尔特·道恩', 6.4, 12258, 'tt6587640', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2616436093.jpg', 1.6, 15.4, 53.1, 23.6, 6.3, '0.411686,-0.014263,-0.607534,0.840538,0.150753,0.325120,0.974107,-0.033763,-0.441745,-0.041917,0.043033,0.935463,-0.219503,-0.057546,0.146656,-0.486010,-0.183349,-0.699344,-0.342615,-0.024766,-0.476374,-0.311460,-0.434476,-0.251414,-0.190383,-0.617781,0.715103,0.127230,-0.653448,0.468936,0.026349,0.227320,-0.440743,0.381254,-0.215761,-0.301395,0.167409,0.069335,-0.194385,0.120945,-0.064955,0.095580,-0.018905,0.364111,-0.381610,0.143759,0.753926,-0.713799,0.092854,-0.029682,0.432404,-0.021057,-0.205602,-0.114969,0.287003,0.161935,0.124598,0.430271,-0.206772,0.201112,-0.107478,-0.086742,-1.183347,0.179109,0.298610,0.216221,-0.248197,0.245219,0.545239,-0.463453,0.312636,-0.010631,0.477399,0.423152,0.739878,0.648391,-0.038012,0.059508,-0.228185,0.061352,0.975530,-0.145158,-0.725329,0.151285,-0.634388,-0.473591,-0.511761,-0.289881,-0.488501,-0.141232,0.351021,0.435308,0.160087,0.301014,-1.213894,0.250911,0.324255,-0.607779,-0.036375,-0.680609,0.015607,-1.004103,-0.259254,-0.433212,0.131494,0.197316,0.550247,-0.053630,1.353726,-0.740799,0.277565,0.507514,0.369997,-0.508825,0.716198,-0.019690,0.133670,-0.022227,-0.132007,0.115262,0.030912,0.092526,0.003697,0.599446,-0.035232,0.189961,-0.378763,0.607434', '27602116', '4181031', '2053515', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26985857', '巨额来电', '剧情', '派出所年轻民警丁小田抓捕电信诈骗罪犯，与警方电信诈骗专案组不谋而合，专案组已经派出女特警小兔，混入远在泰国阿海与阿芳的骗子团队搜集证据，丁小田与卧底女特警小兔密切配合，与阿海、阿芳诈骗集团展开扣人心弦的反诈智斗，逐步掌握了犯罪团伙的诈骗各个环节机密与证据，但同时阿海也与人立下30天骗下1亿人民币惊天赌约，多位商业巨贾及大量老百姓卷入其中……', '陈学冬', '彭顺', 5.6, 40442, 'tt7039862', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505456879.jpg', 5.9, 25.5, 52.7, 12.6, 3.3, '0.130111,-0.155881,-0.436839,0.311365,0.108789,0.154048,0.225725,-0.165447,-0.570686,0.110789,0.083398,0.360234,-0.017284,-0.106868,0.425293,-0.295507,-0.472083,-1.023582,-0.147066,-0.396678,0.114933,-0.744897,-0.337571,-0.327526,0.051349,0.110352,0.516349,0.283418,-0.375243,0.357028,0.060014,0.237258,-0.937834,0.116467,-0.068357,-0.061472,0.774207,-0.215104,-0.570985,0.053499,-0.130820,-0.174584,-0.128692,-0.230478,0.166223,0.473355,0.251718,-0.145846,-0.113750,-0.259612,0.014713,-0.347547,-0.148752,-0.316674,0.456150,0.227346,0.448672,0.624092,-0.170482,-0.297863,0.022467,-0.161796,-0.952668,-0.223888,0.224583,-0.049638,-0.288074,0.017378,-0.425552,0.428581,0.034783,-0.126301,0.133220,0.614739,0.156591,0.172042,0.123479,0.054069,-0.785410,0.375640,0.283789,0.144101,-0.095802,-0.441577,-0.075105,-0.575141,-0.177126,-0.136285,0.200299,-0.030426,0.436143,-0.345386,0.026915,0.197512,-0.660229,-0.141927,-0.164819,0.098066,-0.043853,-0.362995,0.023874,-0.742689,-0.355235,-0.203771,-0.342547,0.291820,0.616862,-0.065996,0.449677,-0.586746,-0.370059,0.622833,0.418921,-0.628294,0.366457,-0.178186,0.096857,-0.419598,-0.447362,-0.644399,0.454372,0.656590,0.503158,-0.053117,-0.216287,-0.486182,0.167210,-0.548015', '1307442', '1295157', '26996640', '26352445');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26985996', '私人生活', '剧情', '理查（保罗·吉亚玛提 饰）和瑞秋（凯瑟琳·哈恩 饰）因不孕而饱受煎熬。这对夫妻一心投入辅助生育和领养安排，在这个狭小领域中愈陷愈深，同时还要为维系婚姻付出努力。他们尝试了试管婴儿，情绪和财务都受到严重影响，眼看中年就要步入尾声，感觉山穷水尽之际，刚从大学辍学的莎蒂（凯丽·卡特 饰）出现并再次进入了他们的生活，一切也终于开始好转......', '凯瑟琳·哈恩', '塔玛拉·詹金斯', 7.5, 8165, 'tt5536610', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2532561115.jpg', 0.5, 2.4, 31.1, 52.9, 13.1, '-0.226706,-0.140406,-0.733088,0.090791,-0.041239,-0.363480,0.855276,0.349280,-0.364694,-0.432581,0.143699,0.684293,-0.371653,-0.004954,0.225281,-0.122975,-0.563244,-0.836131,0.221990,0.138382,-0.284086,-0.296303,0.165628,-0.202223,-0.285121,-0.448601,0.685261,0.272706,-0.231416,0.619866,-0.060414,0.209467,0.126314,0.524930,0.163148,0.009234,0.036953,-0.120323,-0.452031,0.117617,0.362757,-0.178129,0.132150,0.092148,0.225195,0.303192,0.696858,-0.083894,-0.171931,-0.039698,0.387650,-0.250369,-0.300274,0.388688,0.110650,0.230906,-0.181040,0.181600,-0.429649,0.186532,-0.283459,-0.392753,-0.956361,0.101686,-0.125754,0.001775,-0.418947,0.372149,-0.145667,-0.157503,0.141663,-0.017200,0.011284,0.681378,0.140014,0.557703,-0.552869,0.048852,-0.092500,-0.047854,0.783884,-0.174795,-0.290849,0.585460,-0.149509,-0.422050,-0.021313,-0.047714,-0.185463,-0.376322,0.017141,0.694877,-0.190399,0.410571,-0.302572,0.345450,-0.354176,-0.369944,0.223915,-0.248473,-0.151087,-0.699664,-0.360675,-0.556080,-0.416532,0.222973,-0.189066,-0.401758,0.511732,-0.666864,0.571294,0.173031,0.620216,-0.740500,0.687138,0.129898,0.433937,-0.216758,-0.065054,0.711385,-0.605913,0.526760,0.152335,-0.167747,-0.056369,0.024835,-0.247633,0.322564', '26678784', '25828589', '30140231', '1295284');
