INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26990609', '华盛顿邮报', '剧情', '关于“五角大楼文件”泄密案（Pentagon Papers）的新片《The Post》，将史蒂文·斯皮尔伯格、汤姆·汉克斯与梅丽尔·斯特里普聚到了一起。斯皮尔伯格将作为导演与制片人身份参与制作，而影片的男女主角分别是汉克斯与梅姨。这部吸引好莱坞三巨头首次合作的电影将在银幕上重现著名的“五角大楼文件”泄密案。1971年，一名国防部官员将美国政府卷入越南战争的机密文件通过《纽约时报》《华盛顿邮报》等媒体曝光，而在文件公开之前，美国国防部曾试图阻挠文件的曝光并以失败告终。“五角大楼文件”事件标志着尼克松领导的联邦政府名誉扫地的开始，随后爆发的水门事件直接导致尼克松政府倒台。《The Post》的主人公为“五角大楼文件”事件中发挥关键作用的《华盛顿邮报》的编辑本·布拉德利与出版人凯·格拉汉姆。汉克斯将饰演布拉德利，这个角色曾在讲述水门事件的经典影片《总统班底》中出现过，而格拉汉姆则由梅姨出演。斯皮尔伯格的安培林娱乐与20世纪福斯将共同负责融资制作。影片是斯皮尔伯格与汉克斯的第五次银幕合作，斯导现在正忙于《玩家一号》的后期制作，《The Post》何时开始制作还是未知数。', '梅丽尔·斯特里普', '史蒂文·斯皮尔伯格', 8.3, 111399, 'tt6294822', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505577378.jpg', 0.3, 1, 14.9, 51.2, 32.7, '0.298383,-0.047776,-0.440384,0.710030,0.358140,-0.128088,0.544397,0.237667,-0.374040,-0.377490,0.127212,1.075926,-0.503284,0.147423,0.427978,-0.280506,-0.571312,-1.042211,-0.409743,0.049564,0.019043,-0.606236,-0.285484,-0.408337,-0.277142,-0.284624,1.075276,-0.048020,-0.450896,0.141449,0.615710,0.232317,-0.376720,0.233791,0.354171,-0.079570,0.256186,-0.323114,-0.730901,0.353931,0.325512,-0.483871,-0.100993,0.023239,0.312989,0.262736,0.397034,-0.331285,0.051785,-0.067301,0.738356,-0.333883,-0.040453,0.129904,0.408422,0.502964,0.118583,0.527186,-0.316074,0.001194,0.059368,-0.276036,-0.819888,-0.165735,-0.130486,0.389892,-0.421410,0.301961,-0.472904,0.302211,0.024056,0.010773,0.134263,0.430776,0.349737,0.051318,0.104197,0.203449,-0.213979,0.345924,0.314671,0.139387,-0.071461,0.217056,0.147765,-0.508528,-0.331082,-0.224410,-0.231790,0.267569,0.512462,-0.201036,0.269971,0.504374,-0.661004,-0.357076,-0.238880,-0.433316,0.058355,-0.240995,-0.138653,-1.304641,-0.404491,0.010632,0.020747,-0.226434,0.192712,-0.181542,0.711388,-0.449818,0.053129,0.338573,0.062532,-0.220399,0.719370,0.050880,0.263069,-0.266775,-0.18