INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26991880', '热血合唱团', '剧情', '国际知名合唱团铁血指挥家严梓朗（刘德华饰），为帮助昔日恩师（卢冠廷饰）返回香港，带领一群因闯祸而被迫参加“热血合唱团试验计划”的废柴学生们，从零起步学习合唱。众人共同面对生活的挫折与挑战，最终在音乐中找回了自我，而严梓朗身上的秘密也逐步被揭开……', '刘德华', '关信辉', 4.5, 11819, 'tt13322146', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2623500688.jpg', 25.1, 38.2, 27.1, 6, 3.6, '-0.027650,0.004644,-0.447276,0.432897,0.005705,-0.175456,0.103516,0.190597,-0.604091,-0.494337,0.064192,0.703250,0.174661,0.298786,0.265414,-0.766443,-0.090112,-0.956179,0.023949,0.027302,-0.055122,-0.103247,0.063935,-0.040957,-0.237963,-0.490098,0.819868,0.242627,-0.356933,0.912253,0.657092,0.362981,-0.202017,-0.041507,-0.034857,-0.478422,0.503889,0.305999,-0.320405,0.120398,-0.252645,-0.545531,-0.117713,-0.046478,-0.065212,0.267143,0.885277,-0.279533,0.396156,-0.354656,0.211512,-0.446283,-0.112904,0.184801,0.153695,0.465363,0.129099,0.422006,0.127087,0.368893,-0.380547,-0.364359,-0.703993,-0.184469,0.301657,-0.059335,-0.667038,0.219675,0.260171,-0.007860,0.176333,0.190094,0.024357,0.181416,0.546645,0.263027,-0.321218,0.024926,0.038680,0.309950,0.797099,-0.300658,-0.065355,0.096964,-0.066211,-0.244739,0.234799,-0.445125,-0.221634,-0.115375,-0.082451,0.274731,0.094205,0.084967,-0.771662,-0.048026,-0.206526,-0.482232,0.152811,-0.413421,0.113498,-1.075268,-0.171643,0.085280,0.146088,-0.031085,0.045799,-0.338771,0.984324,-0.928947,0.221265,0.285190,0.178465,-0.814049,0.361026,0.070613,0.273847,-0.231928,0.051664,0.257644,-0.139884,0.116653,-0.361203,0.024240,-0.492539,-0.186759,-0.480688,0.223857', '3811356', '5403927', '2369613', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26992114', '孤狼之血', '剧情', '《孤狼之血》的故事背景为1988年施行《黑社会对策法》之前的广岛。被派到当地警署的日冈秀一，与传闻中跟黑社会有勾结的刑警大上章吾一起，负责调查金融公司员工失踪案。日冈因为大上异于常人的调查手段困惑不已。而同时，以失踪案为开端，对立的黑社会团体之间的抗争激化了，此时大上却 想出了一个大胆的计划……《孤狼之血》的原著作者柚月裕子曾获得第69届日本推理作家协会奖，这部小说则被业界评价为“警察小说x‘无仁义之战’”。戏骨大叔役所广司和人气小生松坂桃李在片中分别饰演大上和日冈，一老一少的警探组合颇具看点，配角阵容中还不乏江口洋介、真木阳子等大腕。', '役所广司', '白石和弥', 7.9, 17620, 'tt6622902', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2514406992.jpg', 0.4, 1.9, 23.6, 51.9, 22.2, '0.229655,-0.231326,-0.393119,0.761186,0.321765,-0.083755,0.410894,0.147180,-0.577478,-0.382529,0.038754,0.732929,-0.359370,-0.041497,0.072683,-0.552259,-0.331747,-0.714444,-0.289365,-0.017429,0.008511,-0.463918,-0.362918,0.104671,-0.229001,-0.264140,0.621728,0.069195,-0.282335,0.397189,0.427041,0.310128,-0.199765,-0.064648,0.071096,-0.051231,0.269105,0.184927,-0.415252,0.317670,0.019075,-0.152391,-0.233268,-0.143855,-0.079443,0.410363,0.441924,-0.051682,-0.227793,-0.181718,0.479393,-0.285935,-0.280750,-0.009898,0.502543,0.172809,0.309340,0.360235,0.025138,0.092633,0.003985,-0.255729,-0.999636,-0.110640,0.582205,0.147720,-0.312307,0.186609,-0.178455,0.056847,0.049593,-0.029077,-0.004167,0.183812,0.659329,0.177398,0.095496,-0.001667,-0.324346,0.300297,0.549686,0.327588,-0.084720,0.065440,-0.007872,-0.718972,-0.249194,-0.336747,-0.069735,0.134615,0.205376,-0.214812,0.010061,0.384875,-0.576599,-0.133040,0.025909,-0.023927,0.012390,-0.097065,-0.016610,-0.675896,-0.366012,-0.301946,0.118566,0.039287,0.602963,-0.318824,1.006742,-0.774349,-0.165058,0.478917,0.231269,-0.624222,0.544316,0.057875,-0.206758,-0.202712,-0.222653,-0.283189,0.106824,0.204930,-0.049416,0.189009,-0.177146,-0.547633,-0.347902,0.080921', '27602116', '30465281', '4301278', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26992383', '龙虾刑警', '喜剧', '话唠杜宇飞（王千源 饰）处于半退休状态的能叔（刘桦 饰）、恨嫁女花姐（袁姗姗 饰）以及新人陈笠（周游 饰）组成的不靠谱缉毒刑警小队，为了更隐蔽地监视毒贩，他们盘下隔壁的龙虾店。却不料生意火爆起来。在一边经营龙虾店一边搜寻线索时闹出一系列荒唐笑话，而围绕这家龙虾店，还隐藏 着一个更大的阴谋……', '王千源', '李昕芸', 4.8, 74278, 'tt8489090', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2523437806.jpg', 13.3, 42.8, 36.9, 5.8, 1.2, '0.213135,-0.263266,-0.314782,0.481827,0.209664,0.003100,0.464241,0.558008,-0.589954,-0.094764,0.312486,0.194868,-0.060913,0.073684,0.041049,0.068406,-0.167796,-0.200229,0.087366,0.244988,0.007550,-0.443197,-0.342258,-0.411955,-0.322705,0.311043,-0.005056,0.122325,-0.272900,0.121239,0.458299,-0.050834,-0.365659,0.123910,-0.298122,-0.166705,0.098127,-0.165337,-0.239496,0.038237,-0.201176,-0.286502,-0.154055,-0.050523,0.336893,0.320616,0.612393,0.089562,-0.081543,-0.036801,0.021544,0.066375,-0.199167,-0.185042,0.458421,-0.013035,0.440224,-0.161679,-0.249618,0.066415,0.277413,-0.164481,-0.593994,0.041953,0.277939,0.182314,-0.376197,0.170709,-0.050152,0.293566,0.260083,-0.135584,-0.113363,-0.050627,0.214878,0.405818,0.211708,0.132321,-0.716231,0.303050,0.140290,-0.128929,0.104986,0.159719,0.059068,-0.228648,-0.270634,0.008229,-0.086652,-0.396515,0.207214,-0.125274,0.153361,-0.073848,-0.524819,0.168567,0.172677,-0.019982,0.170456,-0.229881,-0.325918,-0.734746,0.294431,-0.021425,-0.066776,0.393003,0.060359,0.049865,0.388494,-0.431907,0.028768,0.488209,0.087355,-0.339455,0.278740,-0.190110,0.217639,-0.371206,-0.668998,-0.152405,-0.097633,0.099550,0.303649,0.254417,-0.143505,-0.494795,-0.233826,-0.022572', '1307897', '26703844', '20388224', '1300080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26994321', '角头2：王者再起', '剧情', '《角头2：王者再起》故事描述仁哥（王识贤 饰演）面对曾经的好兄弟，如今却“走味”变成‘最换帖的敌人’的刘健（邹兆龙 饰演）重现江湖，不断挑起纷争与冲突，破坏仁哥的忍耐与努力维持的和平。看着刘健的事业版图逐渐扩大，身边的兄弟为了情义有所牺牲，仁哥终究按耐不住释放出心中的猛兽，与亦敌亦友的刘健正式开战，为江湖掀起腥风血雨的厮杀。', '王识贤', '颜正国', 6.7, 11412, 'tt8324576', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2510687913.jpg', 2.2, 11.5, 47.3, 27.8, 11.1, '0.021398,0.034896,-0.368017,0.656762,0.360717,-0.194022,0.852382,0.229320,-0.284432,-0.046608,0.340425,0.553282,-0.200374,-0.040164,0.403222,-0.795478,-0.085576,-0.876112,-0.306002,0.353188,0.220940,-0.147222,-0.439760,0.179230,-0.392936,-0.134091,1.183489,0.227773,-0.460844,0.580026,0.220294,0.034539,-0.307574,0.217070,-0.007658,-0.173313,-0.665736,0.365354,-0.905692,-0.242164,0.152929,-0.109548,-0.279081,-0.065540,-0.169267,0.284515,0.417842,-0.486748,0.061480,-0.216769,0.297949,-0.522765,-0.063221,-0.154364,0.156468,0.143101,0.045657,0.408079,-0.049484,-0.176690,-0.394913,0.101416,-0.825042,-0.100288,0.202144,0.002505,-0.368611,0.399478,0.257299,-0.114449,0.135162,0.114454,0.082565,0.736764,0.537958,0.150491,-0.422613,0.220148,-0.289506,-0.235975,0.753887,-0.084045,-0.112984,-0.075664,-0.022086,-0.105739,0.203378,-0.683441,-0.273042,-0.477295,-0.090224,0.140875,0.140073,0.763596,-0.588955,-0.058733,0.013548,-0.259746,0.526634,-0.575316,0.042577,-0.459917,-0.803376,-0.308610,0.019215,0.160810,0.230961,-0.303970,0.690630,-0.867246,-0.058205,0.146821,0.323210,-0.593666,0.429909,0.433860,0.133966,-0.387109,-0.291788,0.438655,-0.189755,0.192548,-0.045202,-0.077599,-0.257047,0.114841,-0.335724,0.275916', '26759819', '35087486', '26615753', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26994789', '天气预爆', '喜剧', '号称“自杀干预大师”的心理医生马乐，专靠别人生活的不如意发财，一日天降“寿星”砸中了马乐，误吸仙气的马乐被告知世界正在崩溃边缘，只有找齐被贬入凡间的风雨雷电四神才能改变一切，于是众神与凡人一同踏上了一段爆笑奇幻又紧张刺激的旅程....', '肖央', '肖央', 3.8, 72742, 'tt9409854', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2543353290.jpg', 43.1, 33.4, 17.5, 3.9, 2.2, '0.190811,0.172760,-0.228698,0.049464,0.050195,-0.260602,0.442318,0.073992,-0.302344,0.081375,0.043743,0.422765,-0.413683,0.295749,0.640867,0.030770,-0.164665,-0.550486,0.071195,-0.140678,-0.223723,-0.245802,-0.195513,-0.020693,-0.138112,-0.510311,0.536988,0.336525,-0.277567,0.141950,-0.015273,-0.061829,-0.365060,0.358483,-0.194687,-0.042943,-0.267567,0.062625,-0.261655,-0.053194,-0.058001,-0.327850,0.031537,0.108468,-0.308337,0.159424,0.260274,-0.509011,0.037587,-0.284301,0.508963,-0.334257,-0.416750,0.135228,0.167078,0.125320,-0.111488,0.173345,-0.082183,-0.096936,0.026027,0.001248,-0.506372,-0.133875,0.130405,-0.093335,-0.214781,0.226136,0.637980,0.034022,-0.195131,-0.291959,0.284092,0.289556,0.400700,0.496299,-0.208259,-0.348345,-0.043676,0.479969,0.840975,-0.160113,-0.409495,0.115314,0.164292,-0.265947,0.026860,-0.233512,-0.344074,-0.018673,0.355052,0.281954,-0.066162,0.387969,-0.298033,0.130670,-0.439545,-0.292718,-0.357012,-0.071227,-0.113537,-0.488078,-0.053408,0.184738,-0.065069,-0.099492,0.323131,-0.307060,0.279693,-0.398558,0.492187,0.460524,0.084503,-0.356489,0.691711,-0.065014,0.051435,-0.212705,0.116259,0.360684,-0.232031,0.772082,-0.050858,0.026607,-0.153218,0.347672,-0.179222,0.337430', '30154537', '1307200', '2080130', '30402056');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26995137', '忠爱无言', '剧情', '电影改编自真实事件。一场意外让老于（高强 饰）失去了双腿，漫长的余生都将在床上度过，母亲死后，老于由姐姐秋红（于月仙 饰）接手照顾。老于一直因为觉得自己拖累了母亲和姐姐而陷入自责的情绪之中，他潜心于设计一款能够载着他走出家门的交通工具，然而并没有人相信那复杂的图纸会转化成为实物。一次偶然中，一只可爱的拉布拉多犬在误打误撞之中来到了老于的家中，虽然口中常常抱怨这个小家伙不听话爱惹麻烦，但随着时间的推移，老于和小狗之间早已经建立了信赖和友谊。经过不懈的努力，老于的代步车终于完成了，小狗每天充当车夫的角色拉着老于来到镇上摆摊修电器，傍晚再拉着老于回家。©豆瓣', '高强', '谈宜之', 7.3, 32930, 'tt6081412', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2459193246.jpg', 2.2, 8.9, 32.4, 36.4, 20, '0.201687,0.116658,-0.635110,0.413163,-0.004573,-0.392817,0.659900,-0.104929,-0.708861,-0.251408,0.031011,0.587191,-0.014532,0.453164,0.154224,-0.125568,-0.237306,-0.497698,0.000740,-0.032858,-0.191906,-0.426341,-0.323576,-0.248716,-0.166070,-0.194598,0.426824,-0.003274,-0.064340,0.789553,0.112864,0.014887,-0.130066,0.325739,-0.031699,0.096659,0.023319,0.099733,-0.108509,-0.031799,0.269959,-0.180177,0.180544,-0.043255,0.171723,0.106861,0.691466,-0.346051,-0.303438,-0.191296,0.308138,-0.320950,-0.019075,-0.012263,0.105992,0.317002,0.356978,0.179588,-0.380887,0.295476,-0.077645,-0.253938,-0.623919,0.071542,0.049373,-0.077043,-0.770779,0.522756,0.009789,-0.079989,0.128822,-0.533952,0.357158,0.317523,0.323411,0.692145,-0.259989,0.103912,-0.383982,0.086836,0.652820,-0.259737,-0.062921,0.584598,-0.003671,-0.180254,0.128574,-0.254939,-0.433155,0.028480,0.114600,0.184320,-0.268389,0.088000,-0.391141,0.190207,-0.223834,-0.159540,-0.060424,-0.293361,-0.095293,-0.201993,-0.001991,-0.446923,-0.204072,0.093136,-0.085287,-0.409253,0.523740,-0.726344,0.229921,0.334410,0.328445,-0.366419,0.754369,-0.168675,0.380483,-0.202472,0.199441,0.244832,-0.240446,0.319544,0.347568,0.208636,-0.131465,0.059998,-0.583352,0.354696', '1299965', '35030151', '34841067', '24698878');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26995532', '监护风云', '剧情', '当米里亚姆（蕾雅·德吕盖 饰）跟丈夫安托万·北松（德尼·梅诺谢 饰）离婚后，她希望12 岁的儿子朱利安（托马斯·吉奥利亚）能够远离拥有暴力倾向的父亲，故向法庭申请单独扶养权。然而安托万成功在庭上说服法官，法官最终判处双方拥有共同监护权。大受打击的米里亚姆除了要接受未如所愿的裁判外，还要提防前夫别有用心的父亲。面对水火不容的双亲，身处夹缝中的朱利安不得不想尽一切办法，阻止家庭危机。', '蕾雅·德吕盖', '泽维尔·勒格朗', 7.2, 9687, 'tt6002232', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2560052923.jpg', 0.7, 3.2, 37.1, 52.2, 6.8, '-0.108348,0.354760,-0.499751,0.486137,-0.039139,-0.230371,0.417259,0.363140,-0.284371,-0.346216,0.061799,0.691580,0.090180,0.305364,0.386061,-0.089286,-0.404739,-0.668827,0.138516,0.117568,-0.194330,-1.035849,-0.107712,-0.230782,-0.563834,-0.208585,0.491146,-0.117786,-0.006055,0.151421,0.373295,0.391241,-0.129730,0.017860,0.226311,-0.198007,0.186357,-0.067434,-0.929875,0.289882,0.236080,0.317952,-0.106471,0.298778,0.198535,0.313763,0.521595,-0.339960,0.257081,-0.158563,0.260668,-0.109240,-0.110002,0.570213,0.029207,-0.190324,0.100585,0.385393,-0.234833,-0.102758,0.208212,-0.091609,-0.462056,-0.113359,0.228778,-0.069655,-0.283883,-0.063923,-0.120012,0.279732,0.336158,-0.013706,-0.297649,0.353026,0.092065,0.508182,-0.375833,-0.074501,-0.319589,-0.236156,0.621078,-0.065637,-0.348029,-0.077358,-0.445313,-0.202651,0.236033,-0.620691,-0.645911,0.019219,0.046827,0.289292,-0.139867,0.295283,-0.125782,-0.352137,-0.580467,0.241206,-0.012993,-0.477933,0.219583,-0.374867,-0.151150,-0.153236,0.006196,0.347393,-0.192972,-0.474849,0.365657,-0.505267,0.247904,0.274750,0.830983,-0.539344,0.533229,0.367374,0.391321,-0.349789,-0.117227,0.474997,0.059122,-0.109506,-0.254245,-0.252959,0.254456,-0.328990,-0.311017,0.052997', '27202818', '25687245', '3447595', '27624661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26995719', '金钱世界', '剧情', '电影《金钱世界》改编自一起曾轰动世界的豪门绑架事件：世界首富保罗·盖蒂（克里斯托弗·普卢默 饰）之孙遭遇黑帮绑架，绑匪向其母盖尔（米歇尔·威廉姆斯 饰）索要1700万美元赎金，已经与丈夫离婚的盖尔无力支付这笔高昂的赎金，只能向盖蒂家族求救，但富可敌国却无比吝啬的老盖蒂却拒绝为孙子（查理·普拉默 饰）支付赎金，拿不到钱的绑匪丧心病狂的割下了人质的耳朵邮寄给盖蒂家族，心碎的盖尔在前CIA特工弗莱彻·蔡斯（马克·沃尔伯格 饰）的协助下，试图撼动这一僵局，解救自己的儿子……', '米歇尔·威廉姆斯', '雷德利·斯科特', 7, 43475, 'tt5294550', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2539675056.jpg', 0.4, 4.3, 48.7, 39.9, 6.6, '-0.180023,0.161844,-0.550260,0.465280,-0.113839,-0.493448,0.543160,0.221221,-0.175604,-0.055018,0.142075,0.696911,0.119397,-0.074534,0.419627,0.239617,-0.327129,-0.633765,0.076596,-0.246480,-0.203528,-0.899184,-0.192191,-0.501131,-0.069695,0.028057,0.390428,-0.219274,-0.237434,0.404305,0.396744,0.604177,0.264817,-0.001312,-0.150457,0.180586,0.300226,-0.066151,-0.550331,0.144877,-0.131558,0.228094,-0.216032,0.157783,0.144866,0.515315,0.192524,-0.165265,0.322743,-0.247876,0.141363,-0.142655,0.160109,-0.057237,0.146458,-0.149922,0.351591,0.213208,-0.366860,-0.228481,0.380162,0.024069,-0.867566,0.086550,0.120156,0.137004,-0.644284,0.142485,-0.565511,0.310046,-0.179013,-0.231669,-0.050604,0.246351,0.213381,0.377662,-0.195161,0.042620,-0.426598,0.128994,0.113782,-0.059565,-0.058119,0.004824,-0.199501,-0.239742,0.006517,-0.396638,-0.651986,0.060128,0.566636,-0.259882,0.076661,0.424386,-0.375569,-0.557736,-0.476529,-0.410242,0.230464,-0.444670,-0.213275,-0.581373,-0.228262,0.132763,-0.119957,0.150155,0.466785,-0.011794,0.292803,-0.002113,0.042882,0.804531,0.343562,-0.277922,0.494980,-0.154234,0.048751,-0.184793,-0.246786,0.210103,0.569738,0.166129,0.158110,-0.285262,0.221383,-0.165897,0.164200,0.370374', '1307442', '5973984', '3006781', '1309121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26995893', '神探大战', '动作', '连环命案、私刑执法、预告杀人、以暴制暴...一群号称“神探”的团伙掀起了一场香港有史以来最邪恶的犯罪！患有精神疾病的“癫佬神探”李俊（刘青云 饰）为查真凶独闯犯罪现场！以“神探夫妇”陈仪（蔡卓妍 饰）和方礼信（林峯 饰）为首的重案组也开启了与杀戮赛跑的缉凶之路！敌友之间，正邪边缘，死亡审判的真相究竟是什么？真正的“神探”到底是谁？', '刘青云', '韦家辉', 6.8, 224315, 'tt10283270', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2875702766.jpg', 1.4, 8.1, 46.2, 37.4, 6.8, '0.105625,-0.197376,-0.360102,0.370156,0.099641,0.059451,0.507340,0.009416,-0.406608,-0.318101,0.458530,0.437292,-0.217786,-0.059614,0.195637,-0.175750,-0.005054,-0.579375,-0.361042,-0.195427,-0.327500,-0.305718,-0.554183,0.229660,0.346208,0.224360,0.405282,0.197348,-0.441266,0.175921,1.009313,0.488282,-0.585011,-0.004725,0.121721,-0.286460,0.282805,0.169192,-0.499351,-0.042443,-0.102685,-0.484269,-0.181320,0.107578,-0.346746,0.355729,0.440956,-0.523969,-0.022482,-0.356274,0.553004,-0.755250,-0.529221,0.045235,0.676757,-0.275007,0.043125,0.517415,0.194408,0.017951,-0.085379,0.190534,-0.935567,-0.210540,0.315281,0.342318,-0.149687,-0.230598,-0.245747,-0.279941,0.181722,0.101950,0.510776,0.341229,0.421954,0.013415,-0.002284,-0.434916,-0.532458,0.176025,0.625267,0.120946,0.037039,-0.187997,0.042528,-0.884617,-0.394040,-0.408280,-0.052418,-0.011579,0.110076,-0.307995,0.152708,0.285623,-0.527820,-0.303158,0.034105,0.251426,-0.388779,-0.177739,0.181080,-0.658606,-0.107777,-0.378232,-0.069254,0.036498,0.270006,-0.306328,0.186313,-0.551542,0.069965,0.390454,-0.155897,-0.398863,0.180753,0.569283,-0.126880,-0.420463,-0.288130,-0.016166,0.598146,0.481217,-0.152384,0.367871,0.143061,-0.255350,-0.068695,0.320488', '27073234', '26425062', '25921830', '25819726');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26996524', '760号犯人', '剧情', '影片改编自Mohamedou Ould Slahi的回忆录《关塔那摩日记》，讲述Slahi（塔哈·拉希姆 饰）被美国政府俘虏，在毫无指控与判决的情况下被关进了监狱，经受长达14年监禁与折磨。在即将失去希望之际，Slahi寻得辩护律师南希·霍兰德尔（朱迪·福斯特 饰）与助手特瑞·邓肯（谢琳·伍德蕾 饰）的帮助，他们在面对无数障碍的情况下，一同追求正义。在富有争议的主张及斯图尔特·库奇中校（本尼迪克特·康伯巴奇 饰）揭露的证据下，一个令人震惊的阴谋露出水面。', '塔哈·拉希姆', '凯文·麦克唐纳', 7.3, 11996, 'tt4761112', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2877962846.jpg', 0.2, 3, 38.3, 47.7, 10.9, '0.277810,-0.108026,-0.505034,0.472557,0.366557,-0.056869,0.815503,0.203289,-0.251890,-0.265290,0.362803,0.457243,-0.300754,0.073300,0.351003,-0.263901,-0.629902,-0.906982,-0.049781,-0.115119,-0.274743,-0.737999,-0.251684,-0.321971,0.131479,-0.680868,0.728167,0.013854,-0.266528,0.382235,0.428337,0.595191,-0.113503,0.225974,0.164250,0.050651,0.260024,-0.079038,-0.623281,0.360373,-0.021283,-0.340149,-0.213939,0.083993,-0.128468,0.362153,0.580418,-0.628928,-0.066878,0.043400,0.237845,-0.413467,0.307843,0.362413,0.134036,-0.038010,-0.005768,0.594178,-0.381255,0.112296,0.382319,-0.326959,-0.726395,-0.392449,0.000893,0.371869,-0.423590,0.425793,-0.311496,0.319634,0.169423,-0.214808,-0.133049,0.241720,0.165546,0.556058,-0.068555,-0.018163,-0.510390,0.099114,0.150629,-0.090777,-0.250377,-0.028105,-0.254821,-0.350585,-0.046005,-0.288435,-0.331932,-0.140446,0.418043,-0.053030,-0.133299,0.389351,-0.349367,-0.281721,-0.519227,-0.160081,-0.042202,-0.375412,-0.230927,-0.578038,-0.224766,-0.089107,-0.361168,0.238448,0.065229,-0.176231,0.458025,-0.614639,0.435519,0.435686,0.068330,-0.269360,0.529569,0.318289,0.118114,-0.016543,0.000400,0.404167,0.281076,0.199430,0.245113,0.075661,-0.049906,-0.051950,-0.272970,0.244568', '1316693', '1307442', '1293989', '26636537');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26996619', '古董局中局', '剧情', '一尊价值连城的佛头，牵扯出古玩界惊天骗局！民国年间文物界权威组织“五脉”掌门许一城，将武则天明堂佛头送至海外，被定罪为汉奸。半个世纪后，佛头归还，指明要许一城的后人，许家第三代许愿（雷佳音 饰）出面接收。许愿虽有一身鉴古本事，却因父亲许和平当年抛下自己而一蹶不振，混迹市井，如今佛头现世，五脉黄家后人黄烟烟（辛芷蕾 饰）又为他带来父亲离奇死亡的消息，许愿被卷入古董界的漩涡之中。寻宝重任、家族冤屈、五脉天才药不然（李现 饰）的步步紧逼、祖父故交付贵（葛优 饰）的追随和神秘人老朝奉的追击……许愿必须摆脱各方势力的纠缠，还要赶在回归仪式开始之前，查明佛头的真相。', '雷佳音', '郭子健', 5.9, 197947, 'tt11482948', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2734316987.jpg', 2.6, 19.7, 59.8, 15.7, 2.1, '-0.003108,0.434079,-0.390940,0.417956,-0.077958,0.245007,0.129530,0.197862,-0.561314,-0.319163,0.160436,0.617697,0.101338,0.050214,0.154449,0.089303,0.022007,-0.509424,0.098606,-0.193387,-0.112311,-0.167593,-0.151958,-0.093574,-0.140689,-0.100718,0.519176,0.327466,-0.238300,0.139139,0.209706,0.355488,-0.382571,0.032600,-0.292693,-0.016714,-0.046701,0.306747,-0.347851,-0.055914,-0.295808,-0.401140,-0.072073,0.189226,-0.052881,0.120705,0.149545,-0.172702,0.128870,-0.425507,0.401864,-0.182500,-0.165917,0.015430,0.368128,0.311611,0.096542,0.724162,-0.120339,-0.051499,0.236649,-0.103159,-0.601990,0.020278,0.480524,0.124596,-0.486490,0.190000,-0.015888,0.240788,-0.423466,-0.141526,0.276171,0.379163,0.286195,0.033108,-0.119995,-0.053283,-0.586612,0.456756,0.409711,-0.426537,0.064222,-0.272741,0.328489,-0.247490,0.155018,-0.336400,-0.156256,0.038962,0.435992,0.021029,0.245275,0.560693,-0.407768,-0.238046,-0.372377,0.048985,0.202546,-0.050408,-0.159576,-0.303418,-0.202255,0.008542,-0.056540,-0.031450,0.381592,-0.105454,0.588736,0.079870,0.161161,0.323121,0.217662,-0.625366,0.567085,-0.099368,0.203557,-0.482600,-0.172444,0.116930,0.164879,0.320376,-0.099808,-0.191824,-0.035893,-0.120202,0.050027,-0.013864', '1438924', '26678784', '34779692', '6557030');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26996640', '反贪风暴3', '剧情', '大陆某部级高官涉嫌指派情妇来港洗钱，且金额巨大。为此，ICAC（廉政公署）陆志廉（古天乐 饰）和JFIU（联合财富情报组）刘保强（张智霖 饰）联合展开调查。可就在此时，陆被指控巨额财产来路不明，遭到廉政公署L组（内部纪律调查组）程德明（郑嘉颖 饰）的调查，并最终得到停职的处分。为证明自己清白，陆志廉千方百计找到举报自己的女孩Eva（邓丽欣 饰），发现这一切都与正在调查的洗黑钱案件息息相关。未过多久，中国反贪局侦查处处长洪亮（丁海峰 饰）也来到香港，其矛头正是洗钱案的幕后首脑张部长（冯雷 饰）。两岸联动，多部合作，与黑恶势力展开殊死较量……©豆瓣', '古天乐', '林德禄', 5.7, 115457, 'tt8031554', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2531887203.jpg', 4.3, 26.6, 52.8, 13.1, 3.2, '-0.163306,0.007743,-0.545140,0.386228,0.015009,0.208823,0.223470,0.158602,-0.451632,-0.291488,0.199170,0.196432,0.054379,0.033480,0.111356,-0.366873,-0.412422,-0.840029,0.008749,-0.151166,-0.223678,-0.648155,-0.076002,-0.129186,0.071333,0.049702,0.659973,0.155007,-0.456713,0.087167,0.528365,0.243272,-0.514480,0.130998,0.037007,-0.257571,0.455898,0.059985,-0.490755,0.056479,-0.126271,-0.322623,-0.115399,-0.037796,0.150938,0.539001,0.391560,-0.161995,-0.121383,-0.307340,0.368000,-0.429441,0.159499,0.039073,0.720099,0.520767,0.196923,0.578748,-0.539666,0.025874,0.014993,-0.149218,-0.742964,-0.107294,0.357815,0.101582,-0.276269,-0.041048,-0.353182,0.215164,-0.026838,-0.023104,0.243444,0.624196,0.378104,0.096084,0.174606,0.234631,-0.427786,0.328331,0.319858,0.021767,0.191604,-0.405766,0.156657,-0.711317,-0.142802,-0.243689,0.292301,0.046115,0.163637,-0.163812,0.367066,0.215838,-0.678496,-0.156311,-0.172243,0.025238,-0.020940,-0.208659,0.177128,-1.006178,-0.352798,-0.001084,-0.090827,0.258118,0.262940,-0.253959,0.082541,-0.423148,-0.156795,0.235869,0.295393,-0.857881,0.242410,0.156696,0.092991,-0.520505,-0.314261,-0.154777,0.761917,0.227422,0.112908,-0.114577,0.062967,-0.620078,0.017198,-0.289849', '25723905', '2973528', '26336253', '1300371');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26996734', '一个母亲的复仇', '剧情', '本片改编自震惊印度的“德里黑公交案”。艾莉亚（萨佳·阿里 饰）在一次派对活动后遭到强暴，面对凿凿证据，四名罪犯却被法庭判为无罪。艾莉亚的继母，戴维琪（希里黛玉 饰）伤心欲绝，在走投无路后愤然决定亲手为女儿寻求正义。一场高能高智商的复仇大戏拉开序幕。正义到不了的地方，还有母亲！', '诗丽黛玮', '拉维·德耶瓦尔', 6.8, 96014, 'tt5690142', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2554613277.jpg', 1, 9, 50.2, 30.8, 9.1, '-0.122834,0.149450,-0.588482,0.365437,0.029476,-0.293027,0.712418,0.310372,-0.317501,-0.069977,0.669654,0.559888,-0.207301,0.054941,0.293915,-0.079028,-0.399433,-0.735548,0.025476,-0.230918,-0.226921,-0.470550,-0.009556,-0.190161,-0.202742,-0.401267,0.423440,0.071209,0.062562,0.255424,0.776945,0.521974,-0.051248,0.239775,0.192101,-0.163021,0.142192,-0.220388,-0.669128,0.300333,0.099557,-0.092988,-0.391322,0.180737,-0.275225,0.285663,0.585630,-0.215437,0.135460,-0.492886,0.253436,-0.491001,0.054503,0.657603,0.418902,-0.060726,0.102874,0.317021,-0.234745,0.095904,0.515072,0.024082,-0.806305,-0.031545,0.098004,0.196874,-0.331230,0.594331,-0.654400,-0.157352,0.143924,-0.247408,-0.073038,0.302669,0.539666,0.351404,-0.230168,0.136820,-0.337053,0.111236,0.455119,0.007083,0.071914,0.168358,0.121614,-0.190822,0.366038,-0.562786,-0.330736,0.070613,0.478523,-0.320750,-0.273504,0.276400,-0.502385,-0.601439,-0.482650,-0.152298,-0.195016,-0.280438,-0.165563,-0.512040,0.070037,0.317382,-0.147415,0.273582,0.324175,-0.238594,0.424111,-0.679116,0.357148,0.383927,0.145088,-0.573370,0.209503,0.400264,0.121330,-0.034678,-0.145221,0.118117,0.111534,0.518346,0.203803,-0.034308,0.066466,-0.255160,-0.163900,0.413689', '2988294', '26678784', '1921686', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26996783', '大嫂', '剧情', '年轻漂亮的左兰本是个纯洁善良的女孩，有着相恋多年的男友。因为父亲嗜赌成性，被追债的过程中左兰惨遭凌辱。本以为对自己不离不弃的男友，却为了自己上位将左兰送上老板的床，左兰心如死灰。九龙寨的老大罪哥，救下了想轻生的左兰，左兰为了报复毁掉自己人生的人，决心跟随罪哥，在罪哥的一次次历练中，左兰手刃九龙寨叛徒，成长为名副其实的江湖大嫂。左兰接手九龙寨生意后，设计杀死贪污黑警和所有伤害过自己的人，大仇得报。跟随罪哥多年的手下陈杰，暗恋着左兰，看到左兰的变化，内心痛苦，想劝她回头。罪哥在弥留之际想正式传位于左兰，并告知陈杰是警方卧底。此刻香港廉政公署已着手清理九龙寨，外忧内患，左兰将如何抉择······', '徐冬冬', '阚家伟', 3.4, 4185, 'tt7763834', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2507396499.jpg', 49, 36.4, 11.2, 2.4, 1, '-0.038560,-0.002988,-0.557099,0.511576,-0.390477,-0.331614,0.679309,-0.024054,-0.623205,-0.124951,0.401622,0.577669,0.121307,0.441021,0.141557,0.036709,0.039394,-0.652117,-0.153249,0.077009,-0.216525,-0.297092,-0.287802,-0.256704,-0.092584,-0.333082,0.612412,0.267011,-0.133701,0.198185,0.421116,0.274924,-0.164795,0.306066,-0.111197,-0.067356,-0.154634,0.001821,-0.432734,0.190282,-0.101169,-0.361733,-0.120813,0.339159,-0.058541,0.310857,0.492361,-0.351548,-0.142319,-0.227394,0.312274,-0.490859,-0.076250,0.199552,0.226647,0.049052,0.169146,0.445822,-0.491545,-0.366426,-0.018977,-0.131670,-0.938056,-0.145573,0.169525,-0.118208,-0.824511,0.366630,-0.142710,0.219572,0.055034,-0.224074,0.114273,0.384844,0.223226,0.165272,-0.259753,0.097029,-0.350478,0.148163,0.880817,-0.348718,0.170751,-0.030421,0.123141,-0.080630,0.106284,-0.355477,-0.230209,-0.121065,0.317499,-0.114530,-0.171220,0.174282,-0.150333,-0.080206,-0.434301,0.078378,0.088007,-0.401438,-0.244197,-0.013787,-0.380040,-0.082702,-0.242588,-0.047906,0.033576,-0.274262,0.554912,-0.766268,0.318203,0.477480,0.267360,-0.863306,0.505294,0.278641,-0.013052,-0.339091,-0.279919,0.307553,0.182404,0.227187,0.097330,0.015496,-0.039537,-0.182658,-0.420291,0.327223', '26678784', '1877596', '3811342', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26997663', '寂静之地', '惊悚', '一个大规模的入侵行动发生，让地球几乎全灭，幸存的这一家人过着安静无声的生活，一发出声音就会被怪物抓走。《寂静之地》中的家庭必须时时保持安静，这一家人必须搞清楚哪些声音可以发出，哪些不行。父亲铺了沙子路来消音，全家人必须使用手语，还有用来沟通的照明系统…等，才能避免可怕的事情发生，因为猎杀他们的怪物无所不在，这是真正的挑战，他们必须克服生死难关，想尽办法活下去。保持安静是生存唯一法则，它们无法听到你，就无法追捕你。', '艾米莉·布朗特', '约翰·卡拉辛斯基', 6.3, 290765, 'tt6644200', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2518852413.jpg', 3.2, 15.3, 50.1, 25.9, 5.5, '-0.093730,0.096432,-0.564790,0.472612,-0.298394,0.313823,0.696838,-0.250020,-0.129286,-0.294850,0.075839,0.402610,0.090285,-0.074990,-0.082826,-0.514649,-0.243001,-0.390224,0.094680,0.131599,-0.611604,-0.188648,-0.285235,-0.431391,-0.046600,-0.221552,0.662554,0.250063,-0.278737,-0.270294,-0.202681,0.111979,-0.229566,0.287250,-0.247010,-0.564438,-0.223177,0.000524,-0.585694,0.117508,-0.169478,-0.109424,-0.052904,0.304158,0.182044,0.208723,0.268925,-0.531254,-0.349412,0.169295,-0.076728,-0.480896,-0.140985,0.316312,0.046956,-0.269687,0.264106,0.551348,-0.108082,0.057397,-0.095551,0.324003,-1.210602,-0.100124,0.085919,0.170068,-0.253613,-0.060845,0.387089,-0.063690,0.136380,-0.147480,0.484242,0.726945,0.502821,0.367576,-0.443284,-0.009516,-0.675463,-0.126428,1.063085,-0.616522,-0.570047,0.227356,-0.229606,-0.437731,0.171374,-0.519843,-0.384692,-0.115320,0.097452,0.267768,-0.453889,0.114145,-0.344622,0.017743,-0.140136,-0.819829,-0.119907,-0.504078,-0.044713,-0.450752,0.001186,-0.286692,-0.346217,0.604788,0.030251,-0.375146,0.767302,-0.700821,-0.055754,0.739933,0.446279,-0.559716,0.283426,0.343819,0.448269,-0.210297,0.214692,0.067995,0.021418,0.791585,0.136946,0.138651,0.396733,0.400754,-0.556606,0.508990', '30163500', '1811755', '26678784', '25917239');
