INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26999591', '牵牛花与加濑同学。', '爱情', '根据日本漫画家高嶋博美创作的百合漫画《牵牛花与加濑同学》改编的剧场版动画。主角山田结衣是位个性内向、喜欢植物的高中2年级学生，班上的园艺股长；在她隔壁班的加濑同学是田径队的王牌及校内风云人物。某一天，山田与加濑她们两人因山田种的牵牛花而相识，并成为好朋友。', '高桥未奈美', '佐藤卓哉', 8.1, 6987, 'tt7197430', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2450467970.jpg', 0.7, 3.4, 22.7, 38.1, 35.2, '0.326644,-0.623602,-0.078956,0.634907,-0.212553,-0.183290,0.347919,0.253975,-0.391530,-0.430140,0.011387,0.617600,-0.239550,0.726328,0.270448,-0.173252,-0.089519,-0.768365,-0.234018,-0.302865,0.034887,-0.307108,0.031056,-0.139771,-0.203692,-0.180387,1.085134,-0.110692,-0.142371,0.934053,0.144368,0.196180,-0.225133,-0.270153,0.185846,0.041580,0.244807,0.168813,-0.197483,0.204711,-0.327190,0.022484,-0.254368,-0.516742,0.468957,0.174766,0.835290,0.156597,-0.154561,-0.177173,0.594057,-0.139895,-0.206581,-0.139698,1.098833,-0.140874,0.525301,0.113485,0.332592,0.351022,-0.245073,-0.162804,-0.304986,-0.103678,0.184721,0.250486,-0.251602,0.981945,0.019285,-0.372937,0.595876,0.032762,-0.234547,-0.147170,0.406263,0.251445,0.008980,0.318360,0.031236,0.223928,0.334696,0.137245,-0.306289,0.342062,-0.332975,-0.674697,-0.265751,-0.262029,-0.323874,0.295180,-0.217455,-0.176160,0.205570,-0.085620,-0.623243,0.010068,0.376515,0.105422,0.341307,-0.379313,0.079762,-0.913459,0.094879,-0.439327,-0.242286,-0.261227,0.324470,-0.480924,1.355811,-1.211834,-0.143816,0.472502,0.203332,-0.211783,0.661194,0.360141,-0.204125,-0.345242,-0.199971,-0.202363,0.056160,0.341155,-0.096574,0.474732,-0.100036,-0.561110,-0.538422,0.036198', '25922902', '1826173', '10174444', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27000061', '我能说', '剧情', '热血老奶奶罗玉粉（罗文姬饰）性格耿直，爱打抱不平，多年来专注于举报社区里发生的不法行为的，被周围的人叫做“鬼怪奶奶”。她的“对手”是信访办新来的基层公务员朴民载（李帝勋饰）。二人吵吵闹闹未分胜负。某天，罗奶奶忽然“死皮赖脸”要求朴民载成为自己的英语老师。因为她有一个弟弟生长在美国，一句韩语也不懂，罗奶奶只有学会了英语，才能跟他交流。在学习过程中，朴民载与罗奶奶的感情变得越来越融洽。但是，民载得知罗奶奶的弟弟其实根本不想和她通话。在一次冲突中，他不小心对奶奶说出了实情。然而，这时候，罗奶奶有了更迫切的学习英语的理由，她要到美国，向全世界讲述自己做慰安妇的经历，迫使日本政府为践踏人伦的行为道歉。', '罗文姬', '金炫锡', 8.8, 93763, 'tt7342204', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2498433749.jpg', 0.1, 0.6, 9, 39.8, 50.5, '0.298009,-0.040825,-0.781149,0.689243,-0.326775,-0.427205,0.551764,-0.179508,-0.589416,-0.402990,-0.094497,0.403141,-0.117095,0.241240,-0.009350,-0.287971,0.008914,-0.575090,0.095700,0.089998,-0.184102,-0.774453,0.136684,-0.451536,-0.361160,-0.234092,-0.046552,-0.069610,-0.439653,-0.088762,0.240524,0.186023,0.210043,0.641166,-0.028914,0.110637,-0.019314,0.317271,-0.243096,-0.004595,0.402797,-0.200482,-0.137224,0.125820,0.264392,0.393785,0.474970,-0.142094,-0.134543,-0.070407,0.366454,-0.289348,-0.066946,0.269679,0.401228,0.070467,0.370106,0.184358,-0.072961,0.031724,-0.137445,-0.146874,-0.400347,-0.035447,0.025326,0.274875,-0.484674,0.278412,-0.104208,-0.004193,0.160352,-0.475188,0.282689,0.361557,0.327804,0.392066,-0.117769,-0.122181,-0.362874,0.184878,0.953600,0.138298,-0.101486,0.267266,-0.435432,-0.409475,0.252338,-0.266416,-0.407407,0.062951,0.068581,-0.205812,-0.259249,0.297700,-0.235814,-0.196496,0.361900,-0.070827,-0.022664,-0.658304,0.189697,-0.106353,-0.098051,-0.735501,-0.074210,0.063496,-0.083402,-0.313217,0.865209,-0.894562,0.160487,0.195034,0.499858,-0.475022,0.630025,0.350322,-0.149561,-0.218734,0.167497,0.004758,0.048895,0.196473,0.251833,0.321171,0.309972,-0.083066,-0.093215,0.310383', '1303112', '25721544', '1292219', '1301022');
