INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27000981', '多力特的奇幻冒险', '喜剧', '故事发生在英国维多利亚女王（杰西·巴克利 Jessie Buckley 饰）统治时期，多力特（小罗伯特·唐尼 Robert Downey Jr. 饰）拥有着能够和动物交谈的特殊能力，和妻子一起在老家经营着一家动物医院。一场意外夺走了多力特妻子的生命，这巨大的打击让多力特封闭起了心门，拒绝和任何人类接触。一天，一个名叫汤姆（哈里·科莱特 Harry Collett 饰）的男孩闯入了多力特的家，带来了一只受伤的松鼠，希望多力特能够救它。与此同时，维多利亚女王患上了一种怪病，于是派出了侍女萝丝（卡梅尔·拉尼亚多 Carmel Laniado 饰）去拜访多力特，请他出山。多力特所拥有的动物庄园归属于女王的名下，如果女王去世了，那么多力特将失去他和动物们这唯一的乐园。©豆瓣', '小罗伯特·唐尼', '斯蒂芬·加汉', 5.7, 56082, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2614594787.jpg', 5, 26.4, 50.3, 14.9, 3.4, '0.265558,0.168055,-0.569121,0.406377,-0.155039,-0.211617,0.992721,0.199332,-0.469024,-0.237178,-0.047774,0.703601,0.034779,0.328805,0.098188,0.130376,-0.313013,-0.068776,-0.025254,-0.035569,-0.091497,-0.471582,-0.330028,-0.305613,0.054514,-0.706171,0.453070,-0.113101,-0.071306,0.286427,0.239745,0.134963,-0.082782,0.202448,-0.176901,0.072699,0.168568,-0.030470,-0.334716,0.459544,0.051275,0.435823,-0.072678,0.273529,0.175967,-0.037349,0.218217,-0.494426,-0.228897,-0.449293,0.490376,0.003571,0.318068,0.104584,0.003209,-0.050988,0.291216,0.232640,-0.180214,0.076384,0.185432,0.205221,-0.856597,0.060006,-0.002193,0.107198,-0.769145,0.209331,-0.195697,-0.310216,0.027773,-0.404837,0.187655,0.682270,-0.000812,0.081944,0.052424,0.298195,-0.707616,-0.018894,0.586253,-0.448928,-0.300640,0.278354,-0.060557,-0.382994,-0.112525,-0.311188,-0.233791,-0.074776,0.367079,0.082763,-0.219234,0.247182,-0.653848,0.140065,-0.578364,-0.406115,0.090811,-0.187188,-0.041534,-0.382098,0.015254,-0.276241,-0.270984,0.099305,0.315974,-0.331652,0.855631,-0.683719,0.551549,0.749917,0.805397,-0.108931,0.405502,0.209597,0.123132,-0.071656,-0.117286,0.397220,0.153334,0.301004,0.199559,0.273925,0.176061,-0.177056,-0.303480,0.522207', '3005387', '1308784', '1793491', '6030611');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27002371', '最长一枪', '剧情', '从没失过手的杀手老赵（王志文 饰），得了帕金森，准备退休，却同时接到两个订单。同一时间，同一地点。一个订单的目标，却是另一订单的委托人。为了弥补心中一个久远的愧疚，老赵决定利用这最后的机会，倾力一搏，把两笔钱全挣了。而一个巨大而复杂的深渊，在静静地等候着他……', '王志文', '徐顺利', 6, 16100, 'tt7638330', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2568284825.jpg', 4, 20.7, 53.5, 17.6, 4.3, '0.275493,0.178982,-0.962970,0.889368,-0.101573,-0.797821,0.825975,0.070228,-0.217432,-0.270792,0.385090,0.712638,0.057376,0.255145,0.216268,-0.146847,0.171630,-0.507217,-0.276374,-0.228638,-0.411326,-0.550776,-0.512208,-0.274299,-0.273309,0.233660,0.614876,0.185710,0.315449,0.627776,0.634033,-0.026247,0.217358,0.254871,-0.317888,-0.208724,0.033679,-0.206136,-0.171025,0.334356,0.101655,-0.219924,-0.062518,0.387869,-0.036788,0.811266,0.520687,-0.226835,-0.171813,0.107569,0.317012,-0.168793,-0.140820,0.090901,0.129348,0.110657,0.000321,-0.139376,-0.705930,-0.104084,0.425878,-0.098532,-1.272930,-0.139829,-0.266592,0.210273,-0.846530,0.558542,-0.216754,0.065097,-0.250476,-0.408932,0.017342,0.493529,0.184776,0.239777,-0.533559,-0.029501,-0.238260,0.429428,0.564715,-0.113218,0.070543,0.319951,-0.196820,-0.481427,-0.061304,0.087661,-0.326419,-0.164558,0.732867,0.083728,-0.166079,-0.143794,-0.619548,0.227610,-0.417133,-0.041546,-0.136751,-0.592072,-0.304593,-0.282398,-0.161174,0.354483,-0.381395,0.633145,0.229967,0.086670,0.778342,-0.661726,0.012798,0.707130,0.328893,-0.307238,0.464031,0.179892,0.360399,-0.181127,0.253186,-0.238448,-0.191523,0.513885,0.367585,0.207442,-0.021067,-0.111607,-0.358119,0.423796', '3785918', '1793491', '30396443', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27002635', '唐顿庄园', '剧情', '电影版《唐顿庄园》讲述了新的故事：一向暗流涌动的唐顿庄园突然接到一封意外信件，英国皇室即将造访。当象征着大不列颠最高权力的国王夫妇来到这座偏安一隅的乡间宅邸，等待唐顿庄园主人们的将会是怎样的挑战；当两种都以高冷优雅、荣誉体面为毕生追求的人群相遇，又将发生怎样意想不到的碰撞？《唐顿庄园》携经典演员阵容回归，首度通过大银幕演绎一段镌刻着浓郁英伦气息的全新贵族篇章。', '米歇尔·道克瑞', '迈克尔·恩格勒', 8, 93784, 'tt6398184', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2575400017.jpg', 0.3, 2.2, 23.2, 47.3, 27.1, '0.164943,0.341652,-0.579166,0.983505,0.348139,0.101786,0.654116,0.283253,-0.521062,-0.304668,0.536637,0.961880,-0.235898,0.159306,0.533511,-0.006580,-0.207570,-0.525451,-0.304252,-0.091105,0.027163,-0.253053,-0.351022,-0.060746,0.171715,-0.381627,0.619049,0.217207,-0.451216,0.273565,0.448846,0.496631,-0.362513,0.174002,-0.420539,-0.179026,0.217677,0.048079,-0.417176,-0.126605,-0.159717,-0.451747,-0.103931,0.285370,-0.091064,-0.080178,0.747586,-0.394713,0.052377,0.068821,0.861531,0.116582,0.027606,0.056747,0.229842,0.313414,-0.073119,0.461164,-0.018655,-0.180117,-0.147548,-0.381548,-0.683488,-0.109906,0.068806,0.246914,-0.429662,0.427369,0.183506,-0.389988,0.322056,-0.086245,0.166694,0.347479,0.342312,0.449572,0.020317,0.130022,-0.379786,0.155217,0.567561,-0.251712,-0.469563,0.208585,-0.339929,-0.402545,0.091429,-0.213859,-0.704718,-0.158274,0.243860,0.205945,0.326401,0.390443,-0.741205,-0.053273,-0.418856,-0.393078,0.587242,-0.489612,-0.402504,-0.963093,-0.272626,-0.042820,0.028775,0.022726,0.133364,0.164094,0.761310,-0.506373,0.318858,0.423410,0.081972,-0.391424,0.514645,-0.254994,0.070728,-0.183358,-0.183510,0.353664,0.268486,0.308400,-0.194666,0.135746,-0.078941,0.069831,-0.409583,0.651010', '22265121', '2027945', '26611806', '1416898');
