INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27003543', '与神同行2：因与缘', '动作', '故事接上集，为了完成阎罗王（李政宰 饰）开出的条件，解怨脈（朱智勋 饰）与德春（金香起 饰）与凶悍的城主神（马东锡 饰）展开决斗。江林（河正宇 饰）也力劝一等兵（都暻秀 饰）公开秀鸿意外死亡的真相，就在阴间使者们试图完成任务的同时，千年前，他们生前的悲剧也将被逐一揭开…', '河正宇', '金容华', 7.6, 112164, 'tt8116428', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2527205786.jpg', 0.6, 3.4, 30.6, 45.5, 19.9, '0.033953,0.298558,-0.309055,0.350235,0.198635,0.052950,0.335447,-0.207589,-0.000580,-0.118817,0.204854,0.603070,-0.437153,-0.054602,0.276328,-0.230167,-0.426097,-0.783331,0.004655,-0.192090,-0.399146,-0.244782,-0.045822,-0.157741,-0.093590,-0.257012,0.583504,0.068340,-0.091123,0.294105,0.693560,0.492222,-0.525624,0.153202,0.101276,0.024128,-0.134135,0.139080,-0.370821,0.040950,-0.263786,-0.230971,-0.101458,0.304954,0.084482,0.447912,0.815325,-0.611885,-0.207104,-0.091323,0.087108,-0.456490,-0.000402,0.354444,0.144612,0.258845,0.206599,0.870427,-0.169723,0.194250,0.264777,-0.270258,-0.914965,0.069084,0.452487,-0.108881,-0.266715,0.457274,-0.131302,0.087586,0.063428,-0.408389,0.192628,0.477323,0.459361,0.130582,-0.375140,-0.232005,-0.338310,0.597691,0.391382,-0.041337,-0.148382,0.032205,0.219381,-0.621231,-0.250093,-0.202036,-0.054771,0.242620,0.244925,0.201345,0.274452,0.057513,-0.677968,-0.457274,-0.409128,0.032861,-0.021210,-0.072066,0.093496,-0.553802,0.056688,-0.134454,-0.557999,0.252056,0.201091,-0.158291,0.347541,-0.358288,0.126666,0.197429,0.522945,-0.355541,0.431691,0.119640,0.181652,-0.510422,-0.247638,0.157503,0.226111,0.258678,0.146274,0.159910,-0.131009,-0.242857,-0.260385,0.363128', '26759820', '25774050', '26759819', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27004088', '夫妻之间', '喜剧', '安德烈（皮尔弗朗西斯科·法维诺 Pierfrancesco Favino 饰）是一名出色的脑科医生，而他的妻子苏菲（卡西娅·史穆特妮亚克 Kasia Smutniak 饰）是一档两性节目的主持人，安德烈正醉心于一项非常前沿的研究，而苏菲亦将全部的经历都投入到了工作中，希望能够在竞争压力非常大的行业内闯出一片属于自己的天地。久而久之，安德烈和苏菲之间的感情开始出现了裂痕。就在两人决定离婚分道扬镳之际，安德烈请求苏菲参与他的研究实验，哪知道在这场实验里，两人的灵魂和身体发生了互换。虽然进入到了彼此的肉体之中，但生活还是要继续，于是两个人以对方的身份开始了新的旅程，在此过程中，他们体会到了彼此的不易，亦感知到了两人之间坚如磐石的羁绊。©豆瓣', '卡夏·斯穆特尼亚克', '西蒙尼·加达诺', 7.6, 6489, 'tt5753552', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2450980199.jpg', 1.5, 2.7, 30.1, 47, 18.8, '0.531658,0.176616,-0.941321,0.700835,-0.057462,-0.386499,0.703791,0.100275,-0.646860,-0.050739,0.199530,0.646360,-0.239194,0.149872,0.459646,-0.113434,-0.301400,-0.994472,0.052697,-0.280780,-0.535836,-0.590741,-0.286158,-0.096529,-0.301320,-0.365093,0.680486,0.099159,-0.171629,0.229496,0.188730,0.165236,-0.067380,0.649413,0.059682,-0.068703,0.165013,-0.011787,-0.405012,0.233894,0.281631,-0.070941,-0.254070,0.291586,0.156454,0.300393,0.729263,-0.265582,0.043623,0.161232,0.320144,-0.106470,0.080069,0.188972,0.296081,0.139572,0.225580,0.262719,-0.165841,0.223204,-0.019298,0.025801,-0.860657,0.027797,-0.047649,0.390235,-0.658663,0.513332,0.052835,-0.258131,-0.081994,-0.365188,0.071173,0.582079,0.303288,0.360051,-0.289882,-0.219568,-0.386342,-0.078257,0.667479,0.009418,-0.424171,0.507695,-0.252135,-0.596020,-0.527342,0.063836,-0.346922,-0.363479,0.356871,0.340653,-0.243592,0.487869,-0.735938,0.088048,-0.290264,-0.259223,-0.109256,-0.446457,0.175100,-0.815920,-0.360362,-0.618087,-0.420154,0.063222,0.165354,-0.490158,0.760064,-1.046294,0.044786,0.420775,0.180230,-0.196133,0.558151,0.141362,0.414159,-0.368002,-0.085532,0.205651,-0.156009,0.286769,0.228140,0.628516,0.144563,0.129703,-0.486404,0.683068', '1301022', '21360412', '20277433', '26809007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27005769', '禁闭男童', '恐怖', '在影片《禁闭男童》中，因患上未知疾病，一名男童（查理·肖特韦尔饰）必须过与世隔绝的生活，并日渐衰弱。 他的父母（凯利·蕾莉和马克斯·马蒂尼饰 ）在用尽一切办法之后，将儿子的生命托付给一位医生（莉莉·泰勒饰 ）。这位医生在她洁净的房屋设施中试验的前沿治疗也许是男童伊莱最后的希 望。在接受那些可能治愈他的激烈治疗时，伊莱开始感到焦虑不安，他的经历让他自问可以相信谁，这座房子里到底隐藏着什么。', '凯利·蕾莉', '夏兰·福伊', 6.4, 8755, 'tt5294518', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2568659361.jpg', 2.3, 13.3, 53.3, 24.6, 6.5, '-0.050577,0.117063,-0.605021,0.324532,-0.278529,-0.285701,1.064578,-0.098205,-0.668638,-0.480148,0.319955,0.579137,0.094988,0.153978,0.069525,0.002659,-0.290473,-0.391691,-0.113381,0.010631,-0.629528,-0.453591,-0.375768,-0.309356,-0.164630,-0.516435,0.466231,-0.108132,-0.128528,0.146580,-0.081564,0.335348,-0.018191,0.308573,0.054532,-0.133115,0.020518,-0.142048,-0.401558,0.227343,0.409008,-0.199084,-0.136680,0.328494,-0.087686,0.301794,0.671962,-0.300638,-0.101896,-0.016356,0.228761,0.046879,-0.039750,0.378760,0.065198,0.055319,-0.038517,0.080449,-0.316177,-0.032797,-0.093202,0.240993,-0.822513,-0.390085,0.119928,0.447951,-0.535483,0.462669,0.056783,-0.128305,-0.025941,-0.485160,0.081373,0.182569,-0.124574,0.465013,-0.346611,-0.087524,-0.548886,0.180826,0.424635,-0.146651,-0.220985,0.397222,-0.390022,-0.388021,-0.075006,0.022159,-0.868800,0.126924,0.056364,0.172978,-0.391432,0.244591,-0.276663,-0.086419,-0.536775,-0.373673,-0.281393,-0.144036,-0.117926,-0.540873,0.074292,-0.437893,-0.191297,-0.222727,-0.068909,-0.480108,0.615666,-0.912314,0.408873,0.539535,0.328731,-0.225233,0.339735,0.130353,0.463442,-0.088456,-0.389628,0.644131,-0.103215,0.266566,0.134783,0.399184,0.218382,0.006482,-0.442634,0.553785', '1428054', '4301215', '3005387', '1305666');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27006407', '红海潜水俱乐部', '剧情', '《红海潜水俱乐部》改编自著名的真实营救任务，讲述了一群国际特工与英勇的埃塞俄比亚人的传奇故事：在 80 年代初，他们使用苏丹的一座废弃度假别墅作为掩护，将成千上万的难民偷运到以色列。富有魅力的阿里·基德隆（克里斯·埃文斯饰演）与勇敢的当地人卡比迪·宾诺（迈克尔·肯尼斯·威廉姆斯饰演）一起领导了这次卧底任务。其他著名演职人员还包括海莉·贝内特、亚历桑德罗·尼沃拉、米契尔·哈思曼、克里斯·乔克、格雷戈·金尼尔和本·金斯利。', '克里斯·埃文斯', '吉迪恩·拉夫', 6.7, 5959, 'tt4995776', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2564653267.jpg', 1.3, 8, 52.8, 29.2, 8.7, '0.289714,-0.201202,-0.666620,0.746812,0.148607,-0.344735,0.398426,0.185397,-0.116509,-0.406680,0.055316,0.853489,-0.115819,-0.199817,0.630770,-0.025408,-0.551913,-0.406504,-0.319306,-0.187076,-0.100875,-0.828659,-0.418977,-0.573482,-0.060724,-0.393177,0.267852,-0.126704,-0.125753,0.412399,0.418461,0.572621,-0.200636,-0.185133,-0.016299,0.161051,0.759375,-0.255340,-0.423243,0.207100,-0.272841,0.180241,-0.210302,-0.107716,0.418313,0.423022,0.452612,-0.310513,0.261821,0.071381,-0.094424,-0.169708,0.276531,-0.011565,0.218979,-0.535559,0.098298,0.184874,0.042367,-0.036199,0.087429,-0.384890,-0.695458,-0.217107,-0.026029,0.027298,-0.303378,0.072689,-0.285390,0.091539,0.329483,-0.229892,0.024396,0.202658,0.080911,0.204736,0.349552,0.030386,-0.335023,0.250670,0.528104,-0.031444,-0.254419,0.061193,-0.298872,-0.454831,-0.231498,-0.125556,-0.590417,0.077972,0.531252,-0.376221,0.136423,0.352184,-0.699528,-0.334076,-0.446320,-0.282707,-0.070223,-0.002783,0.117876,-1.088024,-0.030082,-0.148663,0.142210,-0.136182,-0.028333,-0.051364,0.722187,-0.516719,0.305122,0.738183,0.111818,-0.030013,0.321629,-0.042104,0.311401,-0.197413,-0.249341,0.487442,0.435135,0.188556,-0.004926,0.566340,-0.052701,-0.245397,-0.356965,0.364626', '6517421', '2075345', '2028645', '1293433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27006896', '世界奇妙物语 2017年春季特别篇', '剧情', '《梦男》女大学生绿翠（中条彩未 饰）每晚都在噩梦中惊醒，之后她将梦中见到的男人画了下来放在推特中，谁知引起极大反响。很多人都宣称梦到了“梦男”，世界很快陷入末日的混乱之中。《少了一把》家庭主妇风见绫子（永作博美 饰）拥有完美的生活，为了守护重要的一切她不惜一切代价。近 一段时间丈夫和儿女对她极其冷淡，而家里的菜刀突然少了一把，这让绫子没来由地担心起来。《变色龙演员》首次担任主演的青年演员工藤圭太（菅田将晖 饰）亚历山大，在经纪人的帮助下，他决定注射一种类似变色龙的液体，这能让他随心所欲融入各种角色。他有一个必须超越的目标。《妻子的记忆》在女儿的婚礼上，成田阳一郎（远藤宪一 饰）讲述了一件离奇的事。在妻子葬礼的第二天，他突然看见妻子的身影在房间内出现。接下来的三年里，他与亡妻的残像相守度日，同时也发现了妻子不为人知的点点滴滴。©豆瓣', '中条彩未', '松木创', 7.2, 10263, 'tt6758636', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2457464479.jpg', 0.6, 5.1, 40.3, 39.8, 14.3, '0.010221,0.043304,-0.492225,0.500859,-0.194462,-0.158714,0.931016,0.086695,-0.506935,-0.377005,0.350985,0.965058,-0.260839,0.192881,0.486660,-0.003219,-0.314953,-0.806817,-0.252376,-0.198138,-0.431865,-0.237628,-0.081625,-0.180595,-0.116769,-0.438027,0.736357,0.042605,0.039244,0.214199,0.244557,0.147734,-0.050501,0.449622,-0.163717,0.126445,-0.131378,0.218138,-0.159251,0.117909,-0.024424,-0.280231,-0.103950,0.341229,-0.214473,0.130720,0.714383,-0.380419,-0.355025,-0.041029,0.455438,-0.114389,-0.195113,-0.106727,0.165467,0.144781,0.309422,-0.003510,-0.366186,-0.198675,0.133910,-0.036318,-0.617512,-0.034413,0.232160,0.201949,-0.454587,0.417006,0.000725,0.146450,0.335636,-0.274326,0.101184,0.261639,0.273521,0.334002,-0.345412,0.127402,-0.284610,0.531050,0.604453,-0.010549,-0.056134,0.541125,-0.307777,-0.261355,-0.308659,-0.219192,-0.435804,-0.033906,0.194223,0.108752,-0.298082,0.402876,-0.394350,-0.077496,0.006066,-0.112441,0.014459,-0.356238,-0.265333,-0.323475,-0.153924,-0.241686,-0.165746,0.095637,0.088830,-0.364623,0.681904,-0.846731,0.221672,0.487228,0.169205,-0.163603,0.518095,-0.054638,0.157229,-0.406758,-0.048494,0.175600,0.049498,0.251553,0.125970,0.309824,-0.228470,0.091749,-0.480198,0.513695', '1303034', '301