INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27008393', '不老奇事', '剧情', '一开始就心动的人，会心动一辈子。电影讲述了郭小鲁（王传君 饰）与苏凌芳（王珞丹 饰）这对青梅竹马的一生故事，因小时候的一场变故被迫分开，未曾抵达的书信让两人踏上不同的人生轨迹。校园中的久别重逢，青春的激情让分别许久的爱情再度重燃，之后的人生里这对恋人经历了一次又一次爱而不得的错过。学医的郭小鲁在绝望之间发现了青春不老的秘密，但随着身边的爱人老去，青春时留下的默许承诺，却成为他奇幻人生的难舍遗憾，就让时间来证明，我有多爱你。', '王传君', '徐超', 6.2, 26815, 'tt11193838', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2719097587.jpg', 6, 18.3, 44.6, 23.5, 7.6, '0.119793,0.209056,-0.842421,0.847876,0.054983,-0.664108,1.041126,-0.299443,-0.693534,-0.008967,-0.054689,0.762443,-0.313444,0.382592,0.217246,-0.107183,-0.070913,-0.946263,0.088299,-0.366440,-0.325117,-0.277163,-0.047858,-0.064114,-0.036380,-0.460604,0.654999,0.461421,0.036741,0.854186,0.414500,-0.167317,0.075964,0.455826,-0.059438,0.211277,-0.049489,0.612199,-0.692958,0.000771,0.267184,-0.236154,-0.193192,0.318307,-0.377187,0.183360,0.765877,-0.217154,-0.423908,-0.206913,0.515471,-0.113520,-0.073263,-0.008945,-0.085305,0.258452,0.339247,0.316334,-0.311047,-0.168581,-0.121602,0.163111,-0.873464,-0.041006,0.019197,0.038117,-0.520632,0.487299,0.133696,-0.141024,0.158652,-0.170424,0.302866,0.373955,0.932841,0.364549,-0.305162,-0.029435,-0.146232,0.421770,1.273390,-0.082842,-0.170351,0.784927,-0.280303,-0.317714,-0.116869,-0.135435,-0.612863,0.343837,0.106570,0.342666,-0.277325,0.341153,-0.629795,0.127773,-0.173523,0.024652,0.166414,-0.689936,-0.008301,-0.149544,-0.323006,-0.510309,-0.512985,0.313516,0.123498,-0.397558,0.749520,-0.647958,0.481479,0.532850,0.250842,-0.581260,1.008885,0.505830,0.016062,-0.246128,0.384343,0.537060,-0.327755,0.132588,0.091948,0.168791,-0.104635,0.166090,-0.698087,0.659926', '2365260', '3014557', '34281687', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27008562', '爱上谎言的女人', '剧情', '某大型饮料公司的OL川原由加利（长泽雅美 饰）和男友小出桔平（高桥一生 饰）是一见钟情。原本生活平静，简单幸福，但是这一切都被突如其来的事件所打乱。某天，桔平因蛛网膜下出血突然昏倒，可是随后被医护人员发现，他所持有的驾照、医师执照居然全是伪造的。得知消息的由加利十分震惊，对于这个相处五年之久的男友，竟然自己完全感到陌生。在此之后，由加利请来私家侦探调查桔平，更从男友一份未完成的小说手稿中找到了蛛丝马迹。他是谁？他又为何甘心让自己和爱人活在谎言之中？本片故事取材自真实事件。©豆瓣', '长泽雅美', '中江和仁', 6.5, 8319, 'tt6733368', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2497881869.jpg', 1.6, 12.6, 54.2, 24.8, 6.8, '-0.059607,0.147187,-0.440517,0.423761,-0.016549,-0.119006,0.525538,-0.231350,-0.635857,-0.679059,0.003762,0.648207,-0.190172,0.190315,0.191636,0.116765,-0.336206,-0.557974,-0.037792,-0.206303,-0.134995,-0.448744,-0.209718,-0.050216,0.038051,-0.279771,0.653428,0.099390,-0.160971,0.360154,0.251308,0.509377,-0.328214,0.304685,0.166840,0.172427,0.178736,0.131619,-0.210357,0.088479,-0.013434,-0.165732,-0.017150,0.436362,-0.284102,0.390762,0.450571,-0.195726,-0.635460,-0.069092,0.579914,-0.303990,-0.261646,0.161478,0.036874,0.126918,0.311840,0.294615,-0.350123,-0.165672,0.213093,0.055084,-0.844939,0.028794,-0.003786,0.315116,-0.240375,0.127575,-0.373670,-0.020184,0.138104,-0.243330,0.078272,0.290739,0.602954,0.407273,-0.427438,0.086646,-0.250997,0.185339,0.597588,-0.057625,-0.164612,0.488656,-0.200002,-0.427203,0.149422,-0.238830,-0.241661,0.425949,-0.050423,0.259300,0.121845,0.228703,-0.190280,-0.112500,-0.277389,-0.206224,0.095985,-0.485618,-0.426886,-0.368979,-0.281978,-0.055013,-0.593899,-0.180443,0.212788,-0.478037,0.564540,-0.790377,0.211580,0.424110,-0.124317,-0.329663,0.207201,0.130263,-0.188641,-0.162314,-0.076677,0.063988,0.272607,0.315632,0.104588,0.074361,-0.000526,-0.149596,-0.281592,0.372749', '6844861', '1793491', '35280911', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27009869', '永生守卫', '动作', '一个名叫安迪（查理兹·塞隆饰）的战士领导了一个关系紧密的秘密雇佣兵团体，他们具有神秘的不死之身，为了保护凡人世界而战斗了几个世纪。但团队在受雇执行紧急任务时突然暴露了他们不寻常的能力，他们要依靠安迪和新加入的士兵奈尔（琪琪·莱恩饰），帮助团队消除那些不择手段要复制他们的能力并从中获利的人所带来的威胁。', '查理兹·塞隆', '吉娜·普林斯-拜斯伍德', 6.3, 27134, 'tt7556122', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2613387966.jpg', 2.3, 14.9, 52.9, 22.6, 7.2, '0.346082,0.005992,-0.333892,0.648121,-0.673586,-0.025863,0.556627,0.130972,-0.451972,-0.420133,0.167994,0.907558,0.472239,-0.241868,-0.008149,-0.103595,-0.300159,-0.566789,0.122211,-0.158938,-0.411902,-0.619806,-0.286158,-0.771334,-0.194067,-0.499613,0.832118,-0.069908,-0.313294,0.262451,0.013227,0.340031,-0.307102,0.438731,-0.024771,-0.376587,0.506166,-0.358531,-0.262041,0.346661,-0.323701,0.244911,-0.039259,0.469082,-0.203134,0.301127,0.514640,-0.377043,-0.102555,-0.313984,0.113263,-0.356971,0.110795,-0.055929,0.324334,-0.288268,0.318431,0.407890,0.207520,0.022835,0.005810,-0.059044,-1.481048,-0.203456,0.408192,0.154308,-0.493769,0.431313,-0.051332,-0.126035,-0.005121,0.089302,0.165990,0.741130,0.295274,0.176959,-0.209204,-0.124634,-0.723734,0.009223,0.753233,-0.308233,-0.393745,0.239647,-0.518649,-0.460878,-0.345540,-0.251969,-0.450671,-0.016444,0.380757,0.164751,-0.071232,0.100959,-0.862837,0.081219,-0.151781,0.098854,-0.326599,-0.509506,0.241518,-0.647640,-0.221724,-0.187919,-0.345096,0.133435,0.154160,-0.174868,0.978866,-0.989827,-0.010641,0.999364,0.525427,-0.778036,0.604516,-0.055017,0.279719,-0.509662,-0.042989,-0.079180,0.126339,0.187588,0.124117,0.310403,0.119341,-0.105636,0.046550,0.368815', '26678784', '1793491', '30163500', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27010768', '寄生虫', '剧情', '基宇（崔宇植 饰）出生在一个贫穷的家庭之中，和妹妹基婷（朴素丹 饰）以及父母在狭窄的地下室里过着相依为命的日子。一天，基宇的同学上门拜访，他告诉基宇，自己在一个有钱人家里给他们的女儿做家教，太太是一个头脑简单出手又阔绰的女人，因为自己要出国留学，所以将家教的职位暂时转交给基宇。就这样，基宇来到了朴社长（李善均 饰）家中，并且见到了他的太太（赵汝贞 饰），没过多久，基宇的妹妹和父母也如同寄生虫一般的进入了朴社长家里工作。然而，他们的野心并没有止步于此，基宇更是和大小姐坠入了爱河。随着时间的推移，朴社长家里隐藏的秘密渐渐浮出了水面。©豆瓣', '宋康昊', '奉俊昊', 8.8, 1281189, 'tt6751668', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2561439800.jpg', 0.3, 0.6, 8.1, 42, 49, '0.309933,-0.040079,-0.550054,0.472314,-0.310651,-0.429947,0.667196,0.349687,-0.622274,-0.519741,-0.112853,0.775653,0.003444,0.445647,0.162776,-0.082602,-0.127060,-0.690895,-0.015202,-0.144591,-0.141569,-0.480527,-0.076873,-0.232715,-0.076406,-0.166946,0.258837,0.155378,0.116604,0.463030,0.241127,-0.046641,-0.016011,0.547822,-0.133596,0.152782,-0.081731,0.202635,-0.236182,0.045050,0.249865,-0.012922,0.040009,0.038078,0.388201,0.453106,0.445652,-0.040154,-0.075481,-0.110675,0.274576,-0.096912,-0.040634,0.233261,0.278887,0.007309,0.547576,0.323857,-0.525294,0.126513,0.139967,-0.236923,-0.523836,0.148975,0.121562,0.024698,-0.599874,0.332537,0.067934,-0.323141,-0.167770,-0.380771,0.270289,0.303897,-0.105461,0.333821,-0.250558,0.106373,-0.390989,0.330050,0.498819,-0.100722,-0.054291,0.245932,-0.059033,-0.415783,-0.043103,-0.218140,-0.532700,-0.136823,0.232736,0.059356,-0.267749,0.017382,-0.501851,0.091325,-0.173033,-0.046474,0.104609,-0.504542,-0.133905,-0.284410,0.064639,-0.319772,-0.389332,0.161371,0.150708,-0.143098,0.782383,-0.871676,0.195374,0.326666,0.487448,-0.500213,0.828499,0.059415,0.285999,-0.119276,0.046450,-0.074049,0.083443,0.297324,-0.009297,0.368075,-0.002647,-0.270984,-0.353344,0.306083', '1302384', '1292720', '1292219', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27011205', '圣诞奇妙公司', '喜剧', '每当圣诞节临近，圣诞老人就会让他的精灵助手们用魔法为地球上的孩子们准备礼物。但是地球上的孩子越来越多，在这次圣诞节即将来临的时候，精灵们渐渐忙不过来集体病倒了。为了救助精灵，圣诞老人决定去地球上寻找解药，却在巴黎遭到雷暴而迫降。圣诞老人自己都不知道，他已经开始了一场奇幻的冒险。', '格什菲·法拉哈尼', '阿兰·夏巴', 6.6, 5175, 'tt7018010', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2505778884.jpg', 0.4, 12.2, 54.1, 24.8, 8.5, '0.293678,0.136280,-0.746878,0.284325,-0.159999,-0.093230,0.635914,-0.296144,-0.348344,-0.038977,0.250986,1.015946,-0.014274,0.376328,0.242153,0.136527,-0.703066,-0.479950,0.137284,-0.214710,-0.765905,-0.344277,-0.186543,-0.320802,-0.092812,-0.307004,0.428879,0.143353,0.239971,0.356332,0.202456,-0.077436,0.311972,0.714079,-0.215539,-0.318026,-0.004005,0.028756,0.142103,0.343567,0.053495,-0.405706,-0.229161,0.538919,0.038131,0.257758,0.761051,-0.476528,0.136521,-0.722532,0.425949,-0.386909,0.114975,0.153747,0.415277,0.093925,0.066422,-0.178551,-0.050626,0.102652,-0.158968,-0.187173,-0.449155,0.517149,-0.052261,0.101341,-0.860025,0.212595,0.109642,0.147240,0.246010,-0.735030,0.382417,0.518336,0.179421,0.295664,-0.229027,-0.254913,-0.331690,0.230957,0.969945,-0.098548,0.134383,0.486779,-0.470013,-0.460644,0.055389,-0.224571,-0.688491,-0.012482,0.168853,0.180943,-0.377248,0.343517,-0.840652,0.258190,-0.179856,-0.722312,-0.214439,-0.197671,-0.014679,-0.810844,0.214302,-0.103443,-0.253360,0.364504,0.436602,-0.104503,1.142646,-0.884703,0.500575,0.926665,0.444996,-0.625459,0.642904,0.171889,0.106977,-0.056330,0.109839,-0.147826,-0.181454,0.546245,0.120469,0.309443,0.158712,-0.027849,-0.157776,0.781936', '30162520', '3811356', '1458900', '26280899');
