INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27012731', '噩梦娃娃屋', '悬疑', '贝斯（艾米莉亚·琼斯 Emilia Jones 饰）和维拉（泰勒·希克森 Taylor Hickson 饰）是个性大相径庭的两姐妹，两人跟随母亲前往亲戚家留下的别墅居住，谁知道一家人却被两个变态盯上了。在母亲的奋勇抗争下，贝斯和维拉逃过一劫，长大后，贝斯将自己的这一段经历 写成了一本小说，并因此一炮而红，成为了畅销作家榜上的常客。与此同时，这段恐怖的回忆带给维拉的却是毁灭性的打击，她整日将自己锁在房间里，被恐惧包围与折磨。得知姐姐的境况十分糟糕，贝斯决定返回故乡，殊不知，从她打开记忆尘封的大门的那一刻起，她将再度陷入噩梦之中。©豆瓣', '克里斯塔尔·里德', '巴斯卡·劳吉哈', 7.3, 31938, 'tt6195094', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2514997577.jpg', 1.6, 6.2, 35, 41.3, 15.9, '0.530433,0.138310,-0.720412,0.583259,0.044669,-0.245237,1.149700,0.069494,-0.770707,-0.272891,0.248294,0.921225,-0.316625,0.270656,0.216540,0.128014,-0.276527,-0.848261,-0.189722,-0.315338,-0.185295,-0.311145,-0.448846,0.081564,0.294875,-0.458908,0.572824,0.190290,-0.297801,0.604560,0.124078,0.557506,-0.296351,0.346828,-0.040586,0.422571,-0.086802,-0.108262,-0.181492,0.054405,0.087501,-0.169006,0.000978,0.215979,0.245796,0.016875,0.669538,-0.467394,0.021435,0.141750,0.250748,-0.263795,-0.353813,0.337251,0.033402,0.038776,0.111898,0.318402,-0.529841,0.162346,-0.175461,-0.029273,-0.770003,0.108153,0.077334,0.065743,-0.844443,0.493521,-0.157793,-0.079426,0.129086,-0.339353,0.254598,0.353080,0.165732,0.597864,-0.079294,-0.045708,-0.536237,-0.099048,0.722037,-0.492601,0.017213,0.043027,-0.175008,-0.103896,-0.193460,-0.252502,-0.503274,-0.062725,0.470949,0.182420,-0.175621,0.320094,-0.576648,-0.137178,-0.487112,-0.338190,-0.017367,-0.593365,-0.403896,-0.562551,-0.331616,-0.216900,-0.403342,-0.153131,-0.132808,-0.347048,0.648606,-0.731580,0.525297,0.365756,0.187065,-0.188779,0.519778,0.021755,0.263122,0.055625,0.032601,0.648039,0.392548,0.333917,0.237849,0.382126,-0.095383,0.041051,-0.705385,0.747655', '1296534', '3111650', '21619567', '26245360');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27013111', '抓人游戏', '喜剧', '杰瑞米·雷纳和汉尼拔·布勒斯有望加盟影片《抓人游戏》(Tag)，艾德·赫尔姆斯已确定参演，Jeff Tomsic(《一路绕行》)执导，改编自《华尔街时报》报道，讲述一群成人毕业后仍继续读书时的游戏"tag"(你捉我赶，追到人后用手触碰)，尽管他们从事各种职业，但每年二月都专门空出来一起抓人，一抓23年。而且比读书时玩得难度更大，因为活动区域不再是操场，而是整个美国。', '杰瑞米·雷纳', '杰夫·汤姆西奇', 6.8, 14434, 'tt2854926', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2520435820.jpg', 1.8, 9.9, 46.9, 31, 10.4, '0.185586,-0.214765,-0.465983,0.165647,0.297832,-0.107101,0.189844,-0.062655,-0.027540,-0.294439,-0.405099,0.518461,-0.149555,0.059326,0.156555,-0.114780,-0.428361,-0.495129,0.197870,-0.184950,-0.168779,-0.302839,-0.110913,-0.114513,-0.064695,-0.118409,0.436410,-0.087275,-0.299198,0.569663,0.162265,-0.119827,-0.078462,0.088575,0.038812,-0.301718,0.225582,0.152173,-0.230883,0.395930,-0.087322,-0.068848,-0.365505,-0.471371,0.402387,0.220605,0.306928,0.123622,0.087479,-0.130576,0.414405,-0.218018,-0.209841,-0.048354,0.342153,0.090688,0.396588,0.257128,0.096009,0.274794,-0.178461,-0.545630,-0.251188,0.184015,0.107153,-0.056023,-0.315626,-0.079076,-0.032294,0.146607,-0.222532,-0.271287,-0.139544,0.292159,0.123304,-0.030168,0.075745,-0.087252,-0.236894,0.274492,0.477645,-0.263720,-0.073366,0.057511,0.436805,-0.241525,0.057128,-0.224662,-0.049137,0.123108,-0.209447,0.001058,-0.369324,-0.021699,-0.265139,0.187893,-0.087165,-0.359617,-0.001814,-0.146554,0.031525,-1.042096,0.346226,-0.104596,-0.193651,-0.087221,0.213599,-0.298466,0.270465,-0.362532,0.318892,0.569652,0.157612,-0.511599,0.759089,-0.109488,0.099803,-0.183668,0.008267,0.179862,0.218493,0.250158,0.091895,0.199694,0.052941,-0.600366,-0.066779,0.448413', '34961898', '24751811', '25833539', '3003137');
