INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27016691', '乡下人的悲歌', '剧情', '杰德（加布里埃尔·巴索 Gabriel Basso 饰）是在耶律大学法学院攻读法律的天之骄子，在深造之前，他还是一名杰出的海军陆战队队员，如此出色的履历表令无比璀璨的未来在前方等待着他的到来。可就在这个节骨眼上，杰德收到了来自故乡南俄亥俄州的消息，他不得不返回家乡处理复杂的家庭事务，要是到，当初杰德可是费了好大的劲才从那个一团乱麻的家庭之中挣脱出来。回到家乡后，杰德再度见到了自己喜怒无常、毒瘾缠身的母亲贝芙（艾米·亚当斯 Amy Adams 饰），这唤醒了他关于过于的糟糕的回忆，与此同时，杰德家族中另一位坚强的女性——他的姥姥（格伦·克洛斯 Glenn Close 饰）的形象也鲜活起来。©豆瓣', '艾米·亚当斯', '朗·霍华德', 7.7, 6882, 'tt6772802', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2624443564.jpg', 0.8, 3.7, 27.8, 46.3, 21.5, '0.260363,0.239536,-0.944013,0.653505,-0.167636,-0.472142,0.791429,0.091917,-0.537699,-0.157189,0.144314,0.755495,-0.006774,0.455767,0.473448,0.432929,-0.329700,-0.644977,-0.173833,-0.317255,-0.367293,-0.508503,-0.385549,-0.047632,-0.014053,-0.461555,0.411345,0.036357,-0.081386,0.305246,0.269343,0.248103,0.104693,0.458216,-0.300268,0.190596,0.097794,0.165639,0.033122,0.022108,0.358810,-0.190318,-0.261702,0.367063,0.246713,0.279615,0.416921,-0.232494,-0.080369,0.101452,0.381637,-0.177195,-0.135773,0.000431,0.270439,-0.156876,-0.050785,0.082565,-0.285735,0.059870,-0.200270,-0.059839,-0.655330,-0.077258,0.035956,0.168915,-0.856689,0.367230,-0.137763,-0.070207,0.102162,-0.521254,0.086963,0.386252,-0.272457,0.440627,-0.199041,0.026726,-0.461360,0.261338,0.482526,0.029878,-0.494696,0.019801,-0.232355,-0.335576,-0.038403,-0.240169,-0.547541,-0.219637,0.603702,-0.073701,-0.198643,0.373119,-0.389314,-0.075500,-0.236693,-0.178610,-0.161272,-0.166205,-0.246552,-0.420747,-0.028214,-0.388778,-0.356971,0.096228,-0.011414,-0.123828,0.952353,-0.891421,0.338258,0.499490,0.075306,-0.234615,0.404375,0.096126,0.250865,-0.058095,-0.276965,0.458937,0.126216,0.351756,-0.061159,0.489768,-0.115629,-0.406944,-0.573622,0.661803', '21360412', '4058933', '26253737', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27017288', '小公女', '剧情', '“就算没有房，也依然要有明确的思想和喜好”做了三年家政帮佣的微笑（李絮饰）人生中只要有一杯威士忌、一口烟和心爱的男友就足矣，可随着新年到来，房租不断攀升，威士忌和烟的价格也不断上涨，薪水却依然毫无波动，既然自己的喜好变得越来越贵，那么便只有放弃房子。可爱的现代版小公主微笑的城市漂流生活就此开始，就算没有房子，生活还是照着自己喜爱的方式继续着…', '李絮', '全高云', 7.9, 17595, 'tt8191502', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2513982852.jpg', 0.4, 2.2, 23.9, 49.7, 23.8, '0.026037,0.426914,-0.576092,0.712443,-0.444362,-0.288996,1.034145,0.291889,-0.133561,-0.050901,0.000385,0.692387,0.213725,0.187407,-0.083717,-0.258380,-0.271576,-0.717618,-0.239503,-0.106236,-0.121479,-0.474142,-0.013758,0.035213,-0.174146,-0.084367,0.288488,0.002231,-0.070648,0.183118,0.114191,-0.127707,0.207048,0.755221,-0.603614,-0.171948,-0.244590,0.169329,-0.106309,0.005838,0.458816,-0.227930,-0.111398,0.131979,0.689603,0.296100,0.612618,-0.070420,-0.581877,0.105241,0.062179,0.099007,-0.017708,-0.057171,0.171762,0.139812,0.511546,0.126277,-0.242512,-0.048402,-0.177322,-0.409530,-0.837897,0.212500,0.106289,0.011812,-0.492937,0.450281,-0.063106,-0.336353,0.143105,-0.344713,-0.062703,0.307655,0.402857,0.471194,-0.606979,0.133434,-0.740581,0.138187,0.498973,0.380806,-0.378063,0.481261,-0.468500,-0.298742,0.014631,-0.190807,-0.488490,-0.208655,-0.092919,0.461186,0.005985,0.252170,-0.660794,0.349382,-0.084563,-0.622258,0.635039,-0.648293,-0.196948,-0.338792,-0.073504,-0.514640,-0.088921,0.197851,0.298405,-0.256974,0.772697,-0.652386,0.163792,0.300590,0.402375,-0.579305,0.692288,0.111008,-0.307326,-0.003889,0.150121,0.165953,-0.295605,0.161619,0.276970,0.416958,0.159854,-0.036937,-0.232185,0.778668', '24756472', '26884422', '1303077', '1417428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27017673', '犬舍惊魂', '剧情', 'Marcello（马尔切洛·丰特 饰）在贫穷的城郊地区生活，是位宠物狗梳毛工。他生性低调，人们都很喜欢他。一天，他遇到了刚刚出狱的好友Simoncino（爱德华多·佩谢 饰）。后者是位吸食可卡因成瘾的前拳击手。出狱后，他开始在街区内敲诈勒索，很快便扰乱了当地的平静。出于对好友的信任，Marcello也被慢慢卷入犯罪的漩涡。在经历背叛和抛弃之后，他决定展开复仇……', '马尔切洛·丰特', '马提欧·加洛尼', 6.8, 5926, 'tt6768578', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520156309.jpg', 1.7, 8.1, 46.2, 36.4, 7.7, '0.190927,0.088318,-0.689988,0.491207,-0.270122,-0.110598,0.976757,0.028079,-0.520097,-0.000700,0.121168,0.735730,-0.087169,0.262028,0.549619,0.055676,-0.242174,-0.674107,-0.057305,-0.329739,-0.377646,-0.394966,-0.157992,-0.159448,-0.078735,-0.344956,0.447922,0.353406,-0.227374,0.408402,0.249934,0.375609,0.112836,0.746912,-0.211382,0.092343,-0.095276,-0.048028,-0.103104,0.033611,0.054614,-0.414612,-0.059449,0.137732,0.091864,0.319527,0.761641,-0.270966,-0.306358,-0.291281,0.254165,-0.358082,-0.066422,0.092692,0.545487,0.169460,0.121437,0.324998,-0.386382,0.002791,-0.145890,-0.062641,-0.377712,-0.161005,0.042120,0.075156,-0.513413,0.631524,0.117475,-0.011629,-0.054141,-0.230349,-0.017301,0.435811,0.081841,0.135616,-0.039993,0.010903,-0.447849,0.144038,0.853160,-0.053903,-0.433613,0.362891,-0.329799,-0.416961,0.055972,-0.310421,-0.345639,-0.324414,0.456345,0.100525,-0.348130,0.402379,-0.564609,-0.064653,-0.061517,-0.167089,0.106783,-0.401531,-0.111045,-0.458956,-0.238345,-0.537658,-0.242496,0.076324,-0.359667,-0.409490,0.464788,-0.999903,0.375988,0.611792,0.271091,-0.701153,0.589565,0.134727,0.070885,-0.076231,0.165500,0.537268,0.304720,0.342894,0.025916,0.300169,0.004319,0.064752,-0.262241,0.719886', '1308755', '1309172', '1301022', '4275444');
