INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27018296', '之后', '剧情', '已婚男奉完（权海骁 饰）与在出版社工作的女人相爱，但最近两人分开了，他感到十分痛苦。这一天，奉完也像平时一样在夜色深沉的凌晨出了家门，到出版社去工作。但妻子发现了他的恋爱信件，追到了出版社。恰好雅凛（金敏喜 饰）到了出版社工作，奉完的妻子错以为雅凛就是那位与老公交往的女人。', '赵允熙', '洪常秀', 7.6, 15423, 'tt6462506', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2465600801.jpg', 0.6, 2.6, 27.8, 52.4, 16.5, '0.134836,-0.147395,-0.892537,0.535959,-0.039607,-0.560185,0.622448,0.240598,-0.436394,-0.217986,-0.013816,0.555984,-0.186013,0.391002,0.636499,0.046183,-0.114664,-0.762246,0.042583,-0.542346,-0.302849,-0.312230,0.286670,-0.170291,-0.060645,-0.282968,0.557356,-0.020303,0.175960,0.477804,0.329522,-0.102742,0.028768,0.685820,-0.135142,0.337364,-0.266531,0.099897,-0.496655,0.147726,0.329966,0.070975,-0.278461,0.087344,0.323271,0.351989,0.616019,0.051202,-0.536089,0.326946,0.772583,-0.010180,-0.102968,0.181162,0.606656,0.247299,0.282220,0.270209,-0.375036,0.059696,-0.121983,0.025310,-0.267398,0.170595,-0.145506,0.196264,-0.729932,0.555750,-0.208904,-0.085404,-0.007084,-0.726639,0.222610,0.310234,-0.060679,0.589573,-0.088741,0.177519,-0.845850,0.378411,0.586050,0.363925,-0.028080,0.754546,0.207797,-0.375706,-0.410951,-0.085728,-0.328153,0.096239,0.257932,-0.134856,-0.382794,0.038858,-0.729628,-0.467391,0.339652,-0.105552,0.120799,-0.720918,-0.136914,-0.471246,-0.178330,-0.397476,-0.464457,0.327338,0.197821,-0.351452,0.456311,-1.021128,0.264243,0.803623,0.266676,-0.521860,0.920355,0.300272,0.005510,-0.021102,-0.044439,0.119701,0.342423,0.427682,0.520176,0.340164,-0.086867,-0.179703,-0.735825,0.145675', '2052978', '1302384', '2124718', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27018354', '金蝉脱壳3：恶魔车站', '动作', '某香港科技大亨的女儿失踪，Breslin发现罪犯是自己一个老对手的疯狂儿子，他还绑架了Breslin的爱人Abigail，并把她关在名为“恶魔车站”的巨大监狱里。 Breslin将和自己的团队硬闯虎穴，试图劫狱。', '西尔维斯特·史泰龙', '约翰·赫兹菲尔德', 3.7, 12304, 'tt6772804', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2567213292.jpg', 36.2, 45.4, 14.9, 2.3, 1.2, '0.165283,-0.017406,-0.620743,0.534546,-0.443001,-0.005978,1.020692,0.015274,-0.602298,-0.136006,0.371397,0.942124,0.225716,0.641301,-0.023642,0.384097,0.003598,-0.714417,-0.242885,-0.127735,-0.389496,-0.389893,-0.546703,-0.231046,0.350220,0.072033,0.472231,-0.041331,-0.288973,-0.026865,0.314270,0.232031,-0.397106,0.594955,-0.400615,0.318874,0.331243,-0.165465,0.062169,0.243123,-0.048598,-0.227255,0.263986,0.347888,-0.179213,0.415244,0.526209,-0.312745,0.030367,-0.479458,0.332890,-0.670325,-0.373189,0.258095,0.314131,-0.201321,0.070836,0.313869,-0.157101,-0.021282,0.242415,-0.186095,-1.069829,0.048909,0.057318,-0.252345,-0.650983,0.318194,0.057568,0.268085,0.289711,-0.030137,0.251452,0.075078,-0.032895,0.346611,-0.388368,-0.007687,-0.631963,0.302838,0.475601,-0.526527,-0.135153,0.077739,0.252738,-0.336465,0.228220,-0.309983,-0.542445,-0.159631,0.386864,-0.090545,-0.630247,0.176280,-0.456719,0.173078,-0.629889,0.044649,-0.042473,-0.467529,-0.076439,-0.373181,-0.192768,-0.204939,-0.325695,0.062655,0.010350,-0.137501,0.273302,-0.545734,-0.079205,1.153524,0.597154,-0.465618,0.819527,-0.187781,-0.170002,-0.036160,-0.177293,0.134867,0.401201,0.776247,0.110368,0.268984,-0.050930,-0.152983,-0.356731,0.463744', '1299628', '30368448', '5339081', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27019527', '嘉年华', '剧情', '小米（文淇 饰）在位于风景区的一间酒店里打工。一天，正值小米当班，一个男人带着两个看上去还是小学生的女孩子来开房，虽然心中所有顾虑，但小米秉着多一事不如少一事的念头替他们开了两间房。之后，在监控录像里，小米看到男人在半推半就之下进入了两个女孩的房间，心中隐隐觉得不安的小米将这一幕用手机录了下来。两个女孩一个叫孟小文（周美君 饰），一个叫张新新（蒋欣悦 饰），那个男人是他们的“干爹”。东窗事发之后，小文的母亲报警并找到了律师郝洁（史可 饰），希望法律能够还他们一个公道。然而事与愿违，证据的缺乏让嫌疑人迟迟不能定罪，而最最关键的证据，正掌握在小米的手中。©豆瓣', '文淇', '文晏', 8.2, 270813, 'tt7205208', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2503644828.jpg', 0.3, 1.5, 16, 52.2, 30, '0.394132,0.358774,-0.748874,0.441500,-0.302798,-0.435606,0.855039,0.239683,-0.491357,-0.340064,0.053187,0.500151,-0.075252,0.295185,0.218083,0.136838,-0.201512,-0.546225,0.042620,-0.386309,-0.248611,-0.306399,-0.046689,-0.151426,-0.053352,0.127536,0.358810,0.029555,0.014212,0.238839,0.353889,-0.194323,-0.076502,0.507653,-0.215611,-0.115780,0.195175,-0.332620,-0.038657,0.391342,0.315635,-0.210180,-0.142476,0.368884,-0.027963,0.307931,0.706349,-0.210827,-0.350015,0.246332,0.222172,-0.055730,-0.368644,0.039006,-0.000918,-0.106220,0.331105,-0.052989,-0.429496,0.182100,0.475962,0.064726,-0.623126,0.047871,-0.096040,0.361021,-0.542619,0.303590,-0.336535,-0.056275,0.139673,-0.639563,0.438340,0.049278,0.078882,0.582364,-0.314422,0.022905,-0.669830,-0.158804,0.296576,-0.087092,0.150305,0.338754,-0.186668,-0.330651,0.104495,0.289595,-0.688988,0.000112,0.366675,-0.076025,-0.293577,-0.405381,-0.628647,0.182555,-0.284400,0.004412,-0.179432,-0.646899,-0.145827,-0.142035,-0.043648,-0.013248,-0.481671,0.246128,0.154024,-0.108420,0.737702,-0.716993,0.031450,0.402761,0.175193,-0.286296,0.582249,0.310320,0.181189,-0.209023,0.011985,-0.286779,0.111415,0.520675,0.055662,0.591439,-0.262477,-0.291199,-0.484260,0.194405', '21619567', '2081098', '3796613', '1292211');
