INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27021609', '超大号美人', '喜剧', 'Renee（舒默饰）一直因为缺乏安全感而感到困扰。然而，一起意外过后，她开始相信自己是这世上最美的女人。她重获自信，并开始充实自己的生活，但如果她发现自己的外貌一直没有改变，又将发生什么呢？', '艾米·舒默', '艾比·科恩', 6.3, 13952, 'tt6791096', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2512993242.jpg', 2.6, 15, 54.6, 22, 5.8, '0.401280,0.331651,-1.224389,0.440919,-0.422216,-0.009618,1.136417,-0.391559,-0.926946,-0.534371,-0.067294,0.557653,-0.047829,0.272344,0.006280,0.382948,0.003456,-0.810644,0.537083,0.170763,-0.092673,-0.405833,-0.241899,-0.435940,-0.268550,-0.475808,0.677818,0.416130,0.068230,0.619962,0.343266,-0.204397,0.506011,1.193511,0.153891,0.014708,-0.457352,0.376761,0.145935,-0.148006,0.633653,-0.237437,-0.289687,1.069830,-0.148129,0.381187,0.320368,-0.200146,-0.863122,0.084500,0.693583,-0.247790,-0.032528,0.100610,-0.215659,0.067950,-0.096566,0.156826,0.040383,-0.124872,0.058851,0.342669,-0.759420,0.086031,0.122810,0.244391,-0.250471,0.293250,0.159598,-0.203913,-0.058690,-0.231879,0.177498,0.466684,0.803540,0.091360,-0.580762,-0.006137,-0.532004,0.036923,1.093384,-0.368961,-0.743636,0.760639,-0.672062,-0.354250,-0.131837,-0.210798,-0.443143,0.232832,-0.703491,0.623179,-0.468317,-0.161198,-0.356762,0.642211,-0.080823,-0.092283,-0.346027,-0.634443,0.107744,0.156147,-0.226413,-0.681044,-0.885718,-0.205124,-0.249835,-0.980251,0.479552,-1.274983,0.444469,0.861497,0.533409,-0.800679,0.643417,0.277865,-0.288530,-0.181174,-0.299837,0.847533,-0.403752,-0.164017,-0.330141,0.040780,0.096420,0.060861,-0.254635,0.823563', '1292064', '35441371', '35073886', '3059036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27024903', '天才枪手', '剧情', '影片根据2014年轰动一时的亚洲考场作弊案改编，讲述了天才学霸利用高智商考场作弊牟取暴利的故事。出生平凡的天才少女Lynn（茱蒂蒙·琼查容苏因 饰）在进入贵族学校后，结识了富二代同学Grace（依莎亚·贺苏汪饰）与Pat（披纳若·苏潘平佑饰），从此开始了考场作弊生涯，与此同时，另一名记忆力极佳的天才学霸Bank（查侬·散顶腾古 饰）发现了Lynn不为人知的“交易”。经过多场险象环生的“作弊战争”后，Lynn接下最后一单在国际考场上为富家子弟作弊的天价委托。一场横跨两大洲的完美作弊方案横空出世，然而一切并不像他们想的那么简单……©豆瓣', '茱蒂蒙·琼查容苏因', '纳塔吾·彭皮里亚', 8.2, 681739, 'tt6788942', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2501863104.jpg', 0.3, 1.1, 16.8, 54.1, 27.6, '0.329176,0.050297,-0.254185,0.516983,0.100801,0.056603,0.146645,-0.091417,-0.638554,-0.351107,0.094600,0.661223,-0.508059,-0.006050,0.421804,-0.290838,-0.219387,-0.744343,-0.025833,-0.487898,-0.297483,-0.492548,-0.124726,-0.073353,-0.074771,-0.366927,0.645128,0.094128,-0.388998,0.479220,0.343285,0.063928,-0.056288,-0.148355,-0.205409,-0.292885,0.289570,0.619352,-0.332549,0.188691,-0.258772,-0.103172,-0.028373,-0.075034,0.048570,0.159758,0.572295,-0.159785,-0.026657,0.011235,0.643826,-0.315639,-0.334112,-0.062891,0.557841,0.230919,0.431804,0.403687,0.248763,0.113795,-0.073926,-0.273242,-0.798746,-0.316523,0.270648,-0.146785,-0.398715,0.586521,0.074441,-0.005565,-0.122109,0.009148,-0.201480,0.232241,0.600265,0.234082,0.087710,0.143298,-0.424772,0.680446,0.397008,0.047776,-0.304463,0.529280,0.243671,-0.705253,-0.075733,-0.466255,-0.073384,0.302244,0.292346,0.020835,-0.246520,0.219468,-0.406257,0.020129,-0.249595,-0.035611,0.082768,-0.352736,-0.378123,-0.557142,-0.188304,0.030203,-0.398724,0.044047,0.011200,-0.484149,0.701286,-0.975159,-0.118284,0.380785,0.042461,-0.283794,0.591268,0.028652,0.093444,-0.344153,-0.244136,-0.176631,0.124429,0.423357,-0.205951,0.459862,-0.095266,-0.569430,-0.262901,0.528471', '27602116', '25880986', '1920765', '22964524');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27024959', '绝杀慕尼黑', '剧情', '电影根据体育历史中著名的传奇真实事件改编，讲述了1972年慕尼黑奥运会篮球决赛中，前苏联篮球队打败了保持了36年全胜纪录的美国队的传奇故事。在决赛结束前三秒钟，美国队以一分优势领先。美国队已经开始提前庆祝比赛的胜利了，因为他们相信比赛结果已成定局。然而，一位来自苏联的不知名篮球教练，率领着艰难、困苦、贫穷中的苏联国家队，比赛结果发生逆转，整个篮球历史也发生了改变。', '弗拉基米尔·马什科夫', '安东·梅格尔季切夫', 8.1, 163618, 'tt5987402', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2556883031.jpg', 0.2, 1.5, 18.2, 51.9, 28.3, '-0.228272,0.446176,-0.486822,0.484962,0.276416,-0.197710,0.095820,-0.489061,-0.192122,-0.102593,0.025212,0.696326,-0.609250,-0.042139,0.575363,-0.927970,-0.049493,-1.218589,-0.219445,-0.127869,-0.436304,-0.470632,-0.523312,0.034150,-0.069543,0.097083,1.072100,0.414860,-0.330902,0.836762,0.011289,-0.013930,0.476332,-0.120453,0.198818,0.080382,0.282537,0.188514,-0.557306,0.482884,0.068570,-0.303953,-0.368820,0.147796,0.191966,0.263087,0.535671,-0.399720,0.099364,-0.133276,0.588543,-0.207475,-0.532479,0.306534,0.644245,0.444003,-0.094654,0.565592,0.225016,0.371627,-0.608382,-0.368588,-0.565625,0.189091,-0.156718,0.358340,-0.191422,1.044034,-0.205667,0.389629,0.175608,0.097502,0.246991,0.563927,0.696714,0.099733,-0.049897,-0.118933,-0.323328,0.409941,0.913242,-0.252433,-0.812305,0.053990,-0.035665,-0.460607,-0.156997,-0.660629,-0.272938,0.645990,0.213344,0.106853,0.194327,0.435837,-0.345358,0.242304,0.099274,-0.549696,-0.123959,-0.184344,0.048214,-0.638254,-0.402727,-0.391166,-0.312882,-0.139557,-0.330497,-0.249389,0.969248,-0.728773,0.010366,0.646323,0.079102,0.069118,0.452497,0.139802,0.555005,-0.108021,0.101196,0.433303,-0.567381,0.177608,-0.496399,0.567257,-0.029987,-0.509291,-0.328788,0.682716', '26615753', '4202326', '1826173', '1457219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27026997', '德黑兰禁忌', '剧情', '强制披戴的头纱下，是三个伊朗女性的暗黑命运。一个因丈夫吸毒坐牢，要独力照顾不能说话的幼儿，不获批淮离婚再嫁，只好卖淫为生。一个怀孕后好不容易找到工作，丈夫却拒签同意书让她上班。一个情不自禁与年轻乐手发生关系，却因为失去处女身而一身蚁。充满禁忌的父权国度，到处是性别歧视、 虚伪做假、滥权渎职。一个恶作剧电话，更凸显女性面对的巨大压力。如此故事，只能用动画呈现，以绿幕拍下真人演出，再利用转描技术做出栩栩如生又带强烈控诉的德黑兰风情画。入选康城影展影评人周及安锡国际动画电影节。', '法拉德·阿巴丁尼贾德', '阿里·苏赞德', 8.2, 8284, 'tt5584796', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2460231338.jpg', 0.2, 0.9, 16.3, 55, 27.6, '-0.217012,-0.029211,-0.182701,0.628686,-0.063785,0.066757,0.745899,0.101322,-0.154410,-0.276642,0.172788,0.806560,-0.128571,0.206058,-0.068813,-0.273372,-0.124045,-0.508910,0.043393,0.349338,-0.136981,-0.125244,0.093743,0.111153,-0.197069,-0.145945,0.703277,-0.175485,-0.373878,0.293866,0.404797,0.141932,-0.200400,0.193577,-0.056395,-0.303532,-0.071394,0.047136,-0.151101,0.282322,0.165406,-0.052569,-0.140025,0.158423,-0.234251,0.350757,0.494927,0.077963,-0.207818,-0.466917,0.728990,-0.278820,-0.207915,0.208202,-0.003178,-0.006056,0.283023,0.076694,-0.282997,0.082493,0.189052,-0.051553,-0.688461,0.112882,0.021630,0.204577,-0.135237,0.044729,-0.103896,0.058947,0.048029,-0.205884,0.175377,0.110902,0.124175,0.479732,-0.107330,0.301935,-0.419481,0.210295,0.427281,-0.038717,-0.304249,0.307989,-0.355502,-0.290671,0.241419,-0.447370,-0.355158,0.057205,-0.070251,-0.192293,-0.194072,0.061000,-0.448326,-0.279488,-0.260303,-0.220770,-0.004971,-0.415488,0.073413,-0.424950,-0.166954,0.015007,-0.297763,0.252316,0.280389,-0.172985,0.433214,-0.426903,0.184931,0.353385,0.368215,-0.678896,0.444830,0.374520,0.126717,-0.095934,-0.028659,0.424126,-0.004456,0.025549,-0.262916,0.049470,0.064114,-0.041161,-0.253724,0.337583', '25731059', '34890458', '3119246', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27027913', '忌日快乐', '悬疑', '9月18日星期一，是放纵张扬的高校女孩泰莉·格尔布曼（杰西卡·罗德 Jessica Rothe 饰）的生日，同时也是她亡母的生日。前一晚她烂醉如泥，睡在了有一面之缘的男生卡特的房间。她醒来后回到宿舍，匆匆赶去上课。夜幕降临，姐妹们为她准备了惊喜的生日派对。谁知在赶赴派对的途中，泰 莉遭到蒙面男的杀害。吊诡的是，当她再度醒来时，发现自己又回到了9月18日的早上，十数个小时前经历的一切又不得不重新经历一遍，其中包括被杀的遭遇。就这样，抓狂的泰莉不断尝试改变命运，又一次次被神秘男人所杀害。她仿佛落入了永世轮回的诅咒之中，无法超生……©豆瓣', '杰西卡·罗德', '克里斯托弗·兰登', 7, 248264, 'tt5308322', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2510057340.jpg', 0.6, 5, 44.4, 41.9, 8.2, '0.048073,0.012274,-0.831070,-0.011017,-0.102493,-0.422000,0.646564,-0.052912,-0.610178,-0.187872,0.194517,0.477926,-0.510531,0.652779,0.609986,-0.146401,-0.298003,-0.819732,0.065008,-0.375344,-0.544724,-0.151820,0.237848,-0.035186,0.333355,-0.378272,0.251208,0.007853,0.175767,0.323422,0.217706,0.182828,-0.101067,0.837519,-0.331316,0.304564,-0.070186,-0.165918,0.005748,0.418805,0.023154,-0.538717,-0.268765,0.132556,-0.177656,0.339656,0.920202,-0.239633,-0.228431,-0.315973,0.659656,-0.269502,-0.473185,0.110170,0.456968,0.337678,0.022687,0.208939,-0.168018,-0.217442,0.069481,-0.175097,-0.299162,0.236820,0.055749,-0.117000,-0.667091,0.564938,-0.065416,0.291056,0.258663,-0.247060,0.177220,0.341203,-0.007900,0.455785,0.057479,-0.073425,-0.381620,0.335113,0.783840,-0.059750,0.112092,0.381152,0.093623,-0.341816,0.207131,-0.240966,-0.407247,0.120028,0.391745,0.337838,-0.350709,0.060028,-0.293405,-0.169187,-0.428918,-0.332591,0.020203,-0.229835,-0.324942,-0.574669,-0.010948,-0.060755,-0.158451,0.294191,-0.130987,-0.062944,0.441107,-0.923083,0.474378,0.627428,0.475481,-0.345639,0.721956,-0.032405,0.078333,0.184202,0.174098,0.382399,-0.014764,0.451710,0.104143,0.389270,-0.129699,0.295540,-0.576382,0.383108', '26687241', '25837175', '21348112', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27029495', '法外之王', '剧情', '本片讲述罗伯特·布鲁斯鲜为人知的真实故事。他昔日是战败的贵族，后来不情愿地当上国王，然后在曲折离奇的一年成为法外英雄。为了拯救家人、人民和国家，让中世纪的苏格兰脱离英格兰的暴虐佔领，罗伯特被迫投入战役。他夺得苏格兰国王之位，并召集一批乌合之众，抵抗世界上最强大的军队，而率领这支愤怒的军队的，是凶残的英格兰国王爱德华一世和他喜怒无常的儿子威尔斯亲王。', '克里斯·派恩', '大卫·马肯兹', 7.5, 8137, 'tt6679794', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2537410854.jpg', 0.5, 3.1, 35, 45.9, 15.5, '0.132426,0.355039,-0.491898,0.841033,-0.112318,-0.045282,0.510235,-0.084878,-0.728861,-0.060394,0.495842,0.935252,0.331299,-0.088355,0.296524,0.059385,-0.259897,-0.629239,-0.254438,0.089756,0.030267,-0.502142,-0.456993,-0.664463,-0.060735,-0.694772,1.003232,0.222608,-0.323339,0.377027,0.393082,0.442782,0.273127,0.345655,-0.076528,-0.092009,0.103674,-0.065741,-0.302371,0.282834,-0.236714,-0.179667,-0.248515,0.554218,-0.008966,0.101471,0.329645,-0.545338,0.375158,-0.444989,0.276065,-0.513026,-0.246413,0.130455,0.302445,-0.027606,-0.048622,0.574150,0.259162,-0.235051,-0.325272,-0.051528,-0.938282,-0.141669,0.008759,0.121808,-0.649681,0.749621,-0.281327,0.058043,0.195338,-0.168256,0.173714,0.442541,0.186508,0.341600,0.100240,0.086438,-0.568381,0.432302,0.870971,-0.259592,-0.400303,-0.247293,-0.295170,-0.485546,-0.009585,-0.827653,-0.661252,0.049901,0.220468,-0.269090,0.164434,0.683202,-0.662829,-0.120108,-0.505891,-0.396661,0.321378,-0.505457,0.160312,-0.354970,-0.158918,-0.307234,-0.003007,-0.100398,0.234158,-0.204439,0.910339,-0.615695,0.157801,0.602496,0.199206,-0.665136,0.572671,0.295758,0.054770,-0.279384,-0.129685,0.595040,0.268557,0.034295,-0.032178,0.022416,-0.239052,-0.095513,-0.310327,0.610160', '3001114', '1308837', '27602116', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27030639', '啊，荒野 后篇', '剧情', '菅田将暉×ヤン・イクチュンW主演作『あゝ、荒野』が、10月7日（土）と10月21日（土）に、前後篇2部作連続で公開されることが決定。あわせてイメージビジュアルが公開された。本作は、1960年代後半、激動の時代において、演劇、映画、文学とマルチに活躍した寺山修司が、唯一遺した長編小説を実写化した青春ストーリー。', '菅田将晖', '岸善幸', 8.6, 23066, 'tt6835806', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2500978171.jpg', 0.3, 0.9, 11.6, 40.3, 46.8, '-1.004770,-0.190572,-0.198180,-0.344721,0.585784,-0.036964,-0.563971,0.320689,-0.107622,-0.759842,0.031823,-0.139343,-0.348900,0.132260,0.594056,-0.099497,-0.567693,0.034272,-0.240413,-0.561543,-0.409226,0.118797,0.268020,0.481698,-0.813499,-0.624003,1.156990,0.306780,1.317693,-0.304202,-0.058745,0.056814,-0.068388,-0.820096,0.402748,0.344721,-0.245685,0.118475,-0.363621,0.529370,-1.036793,0.112267,-0.969188,-1.127448,0.532355,-0.106564,1.190138,-0.252828,-0.019247,-0.803393,0.965206,-0.044259,-0.748325,-0.305516,0.164067,-0.073742,0.468222,0.583756,0.125195,-0.595191,0.695212,-0.843417,0.591721,0.705420,-0.505875,-0.318620,0.219064,0.370118,-0.012507,-0.171168,0.383146,-0.294536,-0.587381,-0.388977,0.391632,0.109883,-0.038358,0.430172,0.576317,0.547369,-0.128223,0.027353,-0.388102,0.452947,0.472909,-0.290708,-0.599129,-0.466372,0.303974,0.001898,-0.115043,0.224427,-0.368643,0.071751,-0.073043,0.521069,0.549042,0.400155,0.723032,0.440025,-0.263332,-0.621171,-0.003156,-0.410916,0.399102,-0.307032,1.543617,0.114193,1.013718,-0.370519,0.402857,0.541168,0.555869,0.556460,0.418180,0.244613,-0.239991,-0.207476,-0.137579,0.415036,-0.305020,0.301562,0.615559,0.261183,-0.601083,0.531653,0.272202,-0.412211', '26635321', '25918693', '27121232', '3993632');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27030640', '卖房子的女人：回来了', '剧情', '北川演じる天才不動産営業ウーマン・三軒家万智が顧客の事情に首をつっこみながらも問題を解決、華麗に家を売りまくる痛快ストーリー。続篇となる今回は最終回から2年後を舞台に、仲村トオルや工藤阿須加、イモトアヤコ、千葉雄大らおなじみのキャストも勢ぞろいする。', '北川景子', '猪股隆一', 7.7, 7053, '房仲女王回來了(台)', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2459894544.jpg', 0.1, 1.8, 32.2, 45.9, 20, '-0.638661,-0.593749,0.192855,-0.457700,0.552763,-0.045536,-0.505018,0.513433,-0.587857,-0.581597,-0.098091,0.404643,0.265364,-0.212349,0.131292,0.413912,-0.680689,-0.155695,0.869243,-0.696529,0.000001,0.063533,0.568485,-0.495480,0.334704,0.047730,-0.079269,-0.189605,0.277147,0.570513,0.644812,0.152715,0.374461,-0.621604,0.555456,0.419574,0.093334,0.797975,-0.151016,0.696731,-1.287093,0.116798,-1.300737,-0.565420,1.054288,-0.239745,-0.308072,0.310012,-0.240403,0.087845,0.277942,-0.695872,-0.992462,0.010237,0.205454,0.193283,0.139461,0.611885,-0.450323,-0.073452,0.144474,-0.499999,-0.128010,0.232583,-0.294437,-0.342622,-0.262705,0.792107,0.079133,-0.556408,0.316797,0.229343,-0.499024,-0.698400,0.549012,0.059198,-0.126210,0.521927,0.257105,0.002109,0.331516,0.308702,0.084272,0.203082,0.703599,-0.089940,-0.559379,-0.542309,0.079757,0.506010,-0.461788,-0.019033,0.140539,0.544641,0.322055,-0.507162,-0.093766,0.178230,0.446456,0.148357,-0.442707,-0.032215,-0.426641,0.074437,-0.119160,0.000672,0.485884,0.002333,1.242608,0.046090,-0.300519,0.796228,0.351716,-0.557300,0.440973,0.185341,-0.330388,-0.140008,-0.095559,-1.119721,-0.573464,0.199777,0.577711,-0.215905,-0.940534,-0.298688,0.067165,-0.030760', '26389697', '35303777', '3821067', '3993632');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27031237', '玻璃先生', '悬疑', '故事讲述玻璃先生（塞缪尔·杰克逊 饰）发现大卫·杜恩（布鲁斯·威利斯 饰）正在追捕凯文·温德尔·克鲁伯（詹姆斯·麦卡沃伊 饰）的人格分裂化身之一“野兽”，而他手中则掌握对二者来说至关重要的秘密......', '詹姆斯·麦卡沃伊', 'M·奈特·沙马兰', 6.5, 26917, 'tt6823368', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2541258858.jpg', 2.5, 14, 49, 25.8, 8.7, '0.100177,-0.311639,-0.266362,0.437742,0.116305,-0.161685,0.830769,0.301956,-0.120730,-0.888503,0.204962,0.428922,0.017525,-0.077756,0.472108,0.188650,-0.419999,-0.609360,0.139500,-0.249072,-0.220751,-1.014269,-0.301670,-0.414618,0.215240,-0.307312,0.250449,-0.366559,-0.279511,0.285056,0.296137,0.717570,-0.027313,0.114794,0.430834,-0.025897,0.202277,-0.223998,-0.561059,0.009786,0.078571,0.350965,0.160866,0.414724,0.191427,0.290061,0.407716,-0.900145,0.280485,-0.131931,0.303013,-0.153358,0.383671,-0.075247,0.307298,0.207423,0.104182,0.275250,0.092340,-0.088856,0.398834,-0.206677,-0.586184,0.020241,0.172583,0.572544,0.074580,-0.006129,-0.426587,0.271622,-0.034816,-0.199474,0.009125,0.102736,0.697480,0.075130,0.171445,-0.037518,-0.441568,-0.324141,-0.190082,-0.010049,-0.122996,0.183165,-0.145554,-0.095440,-0.207324,0.264700,-0.245912,-0.189348,0.326902,0.144110,0.403802,0.421983,-0.260701,-0.240848,-0.234088,0.215009,-0.113037,-0.260912,-0.051534,-0.843080,-0.029528,-0.204688,-0.324189,-0.205508,0.077974,-0.211583,0.409667,-0.536080,0.203597,0.306813,-0.051641,0.215358,0.143671,-0.154998,0.100892,-0.613991,-0.226913,0.913187,0.319133,-0.141808,0.006773,0.199334,0.146818,-0.310095,-0.176136,0.405499', '6517421', '1296217', '3541415', '2334904');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27031463', '山海经之再见怪兽', '喜剧', '昆仑之虚，掩于山海之中，滋养了无数生灵。这里的昆仑医馆医术精湛，但却有一种病千百年来无药可医——黑灵。医师白泽致力对抗黑灵，却自以为是毁了整个大岛，被逐出医馆。七年后，白泽的医术突飞猛进却受人白眼无法行医，想借医馆选举一雪前耻，却在阴差阳错之下，与自卑的麒麟男孩羿一起踏上了荒芜的大岛，进行一场救赎之旅。黑灵爆发危机在即，他们能否解开黑灵背后的秘密，拯救万物天地，又是否能点亮昆仑众生心中的那束光？', '刘琮', '黄健明', 6.5, 8181, 'tt9563330', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2877497897.jpg', 3.6, 16.4, 45.6, 24.3, 10, '-0.190592,0.293054,-0.366573,0.494962,0.066862,-0.337329,0.398985,-0.062222,-0.668051,-0.061391,0.035199,0.418077,0.059909,0.003483,0.064282,0.111726,0.023101,-0.383578,-0.070149,-0.124711,-0.278803,0.078894,-0.451696,-0.041221,-0.288863,-0.155687,0.817925,0.465142,-0.267815,0.046426,-0.194202,0.257874,-0.252540,0.311109,-0.256667,0.015539,-0.177360,0.133287,-0.162820,0.257030,-0.022658,-0.565309,-0.385244,0.517030,-0.347887,0.163278,0.372091,-0.099170,0.028081,-0.618561,0.157744,-0.094592,-0.282322,0.167160,0.083422,0.080889,0.286252,0.063023,-0.041767,-0.323286,-0.031707,0.047643,-0.625664,-0.260386,0.218257,-0.132843,-0.273709,0.389014,0.143974,0.029120,-0.417904,-0.445287,-0.115286,0.059666,0.304227,0.361021,-0.145832,-0.199940,-0.488482,-0.029811,0.696191,-0.363318,-0.168408,0.195391,-0.321591,-0.335122,-0.107338,-0.241115,-0.303688,-0.217689,0.441073,0.169523,0.084302,0.428125,-0.294948,0.048351,-0.462386,0.140229,-0.308479,-0.020590,0.014748,-0.181293,-0.125616,-0.014130,-0.326625,-0.089831,0.577764,-0.069518,0.595340,-0.668968,0.413968,0.189550,0.286477,-0.051483,0.582680,0.027462,0.184973,-0.115505,-0.217132,0.344019,-0.196918,0.794551,0.221170,0.210585,0.047500,0.363174,-0.370573,0.283765', '3001114', '3861846', '6519585', '34779692');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27035334', '检察方的罪人', '剧情', '正义感十足的新人检察官冲野启一郎（二宫和也 饰）十分敬仰当初的导师最上毅（木村拓哉 饰）。经过数年的历练，冲野终于如愿以偿调到东京地方检察厅刑警部，与成为最上麾下的一名得力干将。与此同时，橘沙穗（吉高由里子 饰）也加入刑警部，成为冲野的事务官，但她真正的身份是卧底，其目的是获取检察官为了争取顶罪而使用非常乃至违法手段的铁证。不久后，一起夫妇谋杀事件将犯罪嫌疑人松仓重生（酒向芳 饰）带到冲野面前。松仓是23年前一起花季少女杀人案的嫌疑人，但因缺乏证据无法将其定罪，此案最终过了追诉期。愤恨不已的最上执拗地要将松仓绳之於法，为此他不惜授意冲野拼尽全力朝着预设的方向推进。人性当前，谁也无法保持100%的正义。本片根据雫井脩介2013年发表的同名小说改编。©豆瓣', '木村拓哉', '原田真人', 6.8, 42362, 'tt6857956', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2566170919.jpg', 0.4, 6.6, 51.4, 33.9, 7.6, '0.183496,-0.078208,-0.241083,0.665785,-0.077245,-0.150896,0.345042,0.022259,-0.610082,-0.466111,0.245183,0.584291,0.062174,0.090718,0.418319,-0.291411,-0.213693,-0.713669,-0.231289,-0.243343,-0.259128,-0.629525,-0.063325,0.003215,-0.428122,-0.182815,0.972871,-0.086251,-0.147716,0.199491,0.569290,0.591856,-0.214295,0.147824,0.112326,-0.300874,0.117371,-0.136552,-0.398732,0.303013,0.013367,-0.582509,-0.096737,0.290722,-0.114588,0.213235,0.586615,-0.263846,-0.043158,-0.289888,0.359466,-0.439438,-0.175404,0.148641,0.372701,0.170413,0.261000,0.734508,-0.246660,-0.076737,0.136389,-0.240032,-0.940931,-0.343912,0.374121,-0.033814,-0.298145,0.090611,-0.154219,0.002933,0.173787,-0.182114,0.096565,0.318236,0.244911,0.075589,-0.301673,-0.115245,-0.357980,0.135370,0.513230,-0.043752,0.037107,0.039385,-0.056422,-0.585440,0.104736,-0.674899,-0.132023,0.079329,-0.098739,0.330031,0.104266,0.108331,-0.448441,-0.143948,-0.388288,-0.071304,0.085776,-0.248684,0.295676,-0.416147,-0.100583,-0.349925,-0.203869,0.076758,0.309146,-0.331146,0.610247,-0.705555,-0.157354,0.453528,0.258448,-0.426432,0.538838,0.023670,-0.001710,-0.450905,-0.166326,0.005589,0.382556,0.403174,0.002702,0.114301,-0.078644,-0.520190,-0.352084,0.270984', '25880986', '27073234', '26759820', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27035542', '花生酱猎鹰', '剧情', '无亲无故的扎克（扎克·高察根 Zack Gottsagen 饰）是一名唐氏综合症患者，政府不得不将他安置到了一家养老院中，在这里，善良的扎克非常讨人喜欢，与此同时，他亦和在这里工作的名叫爱丽诺（达科塔·约翰逊 Dakota Johnson 饰）的护工之间结下了深厚的友谊。扎克是一个摔角迷，每天，他都要看一段摔跤比赛的录像，这段录像是由一个化名“咸水乡巴人”的人录制的。扎克的人生理想就是能够前往录像中所记录的摔跤学校。在室友卡尔（布鲁斯·邓恩 Bruce Dern 饰）的建议下，扎克开始尝试“越狱”，并且最终成功，就这样，他踏上了圆梦之旅。©豆瓣', '希亚·拉博夫', '泰勒·尼尔森', 7.4, 8343, 'tt4364194', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2562073170.jpg', 0.4, 3.6, 35.4, 46.2, 14.4, '0.396835,-0.178151,-0.446348,0.603763,-0.309087,-0.481070,0.571032,0.001819,-0.499900,-0.051076,0.289636,0.766912,-0.122230,0.111395,0.299971,0.085087,-0.474572,-0.700397,-0.114148,-0.274536,-0.287279,-0.571096,-0.372817,-0.058796,0.000689,-0.228920,0.555141,-0.050401,-0.009143,0.356755,0.155017,0.262004,0.018855,0.242502,-0.145700,0.140322,0.177288,-0.247135,-0.055304,0.304992,0.130579,-0.156981,-0.138714,0.106960,0.207065,0.372988,0.595045,-0.047237,-0.018326,0.050408,0.289637,-0.208331,-0.045547,0.173033,0.397670,-0.140420,0.329696,0.281121,-0.396192,0.051298,0.088035,-0.051517,-0.769155,-0.162636,0.026178,0.189602,-0.724544,0.515988,-0.044946,-0.103609,0.035939,-0.480250,0.063175,0.392250,0.211486,0.384553,-0.001529,-0.336791,-0.188063,0.407751,0.653874,0.069650,-0.071127,0.321426,-0.238269,-0.565650,-0.140148,0.000143,-0.616320,-0.099950,0.606089,-0.132456,-0.153233,0.100524,-0.664252,0.113491,-0.259142,-0.277945,-0.203198,-0.339004,-0.016240,-0.867010,0.010580,-0.304129,-0.112161,-0.055217,0.039026,-0.343187,0.623924,-0.953386,0.169611,0.715667,0.011561,-0.137777,0.757668,0.275379,0.281347,-0.075423,-0.038324,0.035831,0.012601,0.392382,-0.030029,0.557516,0.164732,-0.251121,-0.656968,0.562207', '10763928', '11541282', '1793491', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27036366', '猴子', '剧情', '讲述了八个哥伦比亚游击队少年在山区基地中看守一名美国俘虏的故事，他们经历的一系列事件让人开始反思成长、反叛、规训等主题。雨林、山丘、激流的壮丽背景与叙事的残酷相辅相成，精彩的配乐和变幻莫测的剪辑同样令人赞叹。本片获第35届圣丹斯电影节评审团特别奖。', '索非娅·布埃纳文图拉', '阿莱汉德罗·朗德思', 7.2, 13204, 'tt6062774', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2562774107.jpg', 1.8, 5.8, 35.2, 43.2, 14, '0.057652,-0.380302,-0.775898,0.956792,0.461002,0.048983,0.701946,-0.082576,-0.577022,0.279014,0.321253,0.669173,-0.471050,0.011155,0.381098,-0.555552,-0.558102,-0.557208,-0.409122,-0.145109,-0.191806,-0.125220,-0.215213,-0.307774,0.066478,-0.295109,0.868434,0.292458,-0.312991,0.643820,0.332838,0.050247,-0.483924,-0.025150,-0.019309,0.030975,0.490377,0.139429,-0.404528,-0.094329,-0.458328,-0.368314,-0.397673,0.046169,-0.172325,0.228823,1.023875,-0.098088,-0.112633,-0.051959,0.612043,-0.406314,-0.164175,-0.039415,0.462569,0.053604,0.050781,0.651062,0.086705,0.075447,-0.553696,-0.294524,-0.909347,-0.158960,0.336358,0.171748,-0.318153,0.269357,0.215739,-0.076484,0.049526,0.088196,0.101750,0.255417,0.799587,0.489532,0.333365,-0.138518,-0.049006,0.626159,0.519058,-0.249861,-0.545622,0.164359,-0.143409,-0.595837,-0.061168,-0.234794,-0.275239,0.207671,0.339714,-0.276035,-0.126517,0.286110,-0.659962,0.098548,-0.207995,-0.630431,-0.330811,-0.283009,-0.177479,-1.065907,-0.123751,-0.259529,-0.241917,-0.036225,0.080360,0.006263,0.914116,-0.279531,0.068452,0.511784,-0.005205,-0.284072,0.392498,0.105664,0.206690,-0.268140,-0.071710,0.215896,-0.100456,0.090472,-0.170860,0.713864,-0.332382,-0.136843,-0.496437,0.227755', '3318306', '5403927', '1322847', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27036483', '北极', '剧情', 'Bleecker Street拿下麦斯·米科尔森主演，乔·佩那自编自导影片[北极]的北美发行权以及国际部分地区发行权，该片故事讲述一个被困在北极的男子(麦斯·米科尔森饰)要做出艰难的决定，他是要待在安全的营地，还是冒着被冻死的危险而踏入禁区。该片已经在戛纳电影节亮相。', '麦斯·米科尔森', '乔·佩那', 7.3, 7561, 'tt6820256', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2539146420.jpg', 0.7, 4.1, 38.5, 41.9, 14.8, '-0.307246,0.025304,-0.870003,0.903042,0.389873,0.059854,0.601851,0.408274,-0.105891,0.163835,0.351751,0.935027,-0.426992,-0.191593,0.490006,0.240431,-0.212361,-0.638559,-0.347740,-0.342293,-0.057343,-0.446217,-0.182341,-0.306553,-0.115985,-0.339704,0.576296,0.284912,-0.504665,0.063602,0.584724,0.189099,-0.148098,0.453002,-0.330447,0.047252,0.140390,-0.392487,-0.253309,0.593985,0.279658,-0.221412,-0.187533,0.037442,0.487625,0.433796,0.799552,-0.048533,0.110442,0.510270,0.373414,-0.795329,0.020362,-0.153983,0.489026,-0.438511,0.098449,0.029595,-0.207383,0.307492,0.318130,-0.664862,-0.586115,0.117728,0.075605,0.356681,-0.511348,0.334771,-0.248583,0.246064,0.121497,-0.233632,0.250178,0.436802,0.288016,0.101889,0.096424,0.190482,-0.597450,0.272469,0.491963,-0.293296,-0.203556,-0.015119,0.044004,-0.691347,-0.320381,-0.198621,-0.656713,-0.083195,0.727701,-0.364032,-0.121087,0.162895,-0.386044,-0.278265,-0.249738,-0.579339,0.020131,-0.329865,-0.033211,-0.779016,-0.029033,-0.010604,0.103189,0.233597,-0.133499,-0.051770,0.493205,-0.301052,0.248813,0.615696,0.563569,-0.005964,0.714413,-0.032598,0.256846,-0.095613,-0.220359,0.588856,0.032658,0.375223,0.179978,0.647654,0.062107,-0.231841,-0.679807,0.314151', '1829654', '4206468', '3606973', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27037053', '夜以继日', '剧情', '自从初恋失踪以后，朝子便失去了生活的目标。两年后，她遇到了一个外形与恋人几乎一模一样的男人。她被这种奇妙的相似所吸引，却逐渐感受到这个年轻男人拥有截然不同的性格。', '东出昌大', '滨口龙介', 7.6, 44474, 'tt7112154', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2518349518.jpg', 1.2, 4.5, 27.8, 44.3, 22.2, '0.619211,0.092888,-0.927703,0.815470,-0.725721,-0.314230,1.281541,-0.187847,-0.633589,-0.486110,0.280658,1.093723,-0.614448,0.297061,0.336014,0.176621,0.289205,-0.781813,-0.192843,-0.054574,-0.464244,-0.185934,-0.500977,0.210716,-0.261780,-0.444627,1.043547,-0.141076,-0.304669,0.661994,-0.037612,0.132573,-0.009492,0.668455,-0.554899,0.141899,0.074691,0.393271,0.035521,0.088561,0.048279,0.000986,0.376811,0.281182,-0.665704,0.324212,0.894942,-0.301506,-0.638436,-0.118377,0.667827,0.308894,-0.419740,0.353409,0.445402,0.014396,0.069447,-0.145836,-0.491404,-0.408457,-0.313149,0.127680,-0.688853,0.097979,0.254781,0.004674,-0.201679,0.161208,0.163110,-0.297368,0.258325,-0.231167,0.068451,0.408289,0.363683,0.504975,-0.287973,0.089743,-0.295133,0.039905,1.353762,0.063081,-0.964665,0.746607,-0.430392,-0.365659,-0.362961,-0.419110,-0.357678,0.495204,0.150494,0.405572,-0.381168,0.386743,-0.769179,0.130134,0.009182,0.329120,0.255944,-0.621846,-0.328293,-0.425145,-0.694047,-1.011831,-0.383643,0.257264,0.123356,-0.407602,0.914429,-0.955129,0.312321,0.515999,0.278243,-0.680493,0.579044,-0.139049,-0.064356,-0.587185,0.103463,0.863154,0.105054,0.084931,-0.180678,0.716920,-0.236680,0.388664,-0.612669,1.102883', '25721544', '30162520', '1291877', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27038183', '羞羞的铁拳', '喜剧', '堕落沉沦的MMA选手艾迪生（艾伦 饰）依靠打假拳度日，早已忘记昔日的雄心壮志。某次他和假拳掮客马东（田雨 饰）商议打假赛的时候，不慎被正义感爆棚的体育记者马小（马丽 饰）听到并录音。在追赶马丽的过程中，艾迪生和对方一同跌入游泳池，并遭到雷电的电击。当他们从医院醒来后，发现两人居然互换了身体。在所有复原的办法都失败后，艾迪生只能请求马小代替他去和拳王吴良（薛皓文 饰）——同时也是马小的未婚夫——去打比赛。然而，娘娘的艾迪生和汉子力爆表的马小却闹出了一连串的笑话。而在这一过程中，两人渐次发现了当年艾迪生遭遇惨败和黑幕的真相……©豆瓣', '艾伦', '宋阳', 6.8, 676353, 'tt7431894', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2499793218.jpg', 2.5, 10, 43.2, 33.3, 11, '0.004947,-0.140454,-0.730372,0.302218,-0.125436,-0.484524,0.670138,0.124537,-0.458197,-0.193174,0.051395,0.647940,-0.599460,0.164153,0.364163,-0.408905,-0.292732,-0.763182,-0.073540,0.180186,-0.345325,-0.303294,0.217766,-0.012698,0.062757,-0.136735,0.466173,-0.081042,-0.294883,0.443559,0.400627,0.140998,-0.081590,0.420473,-0.055477,0.338586,-0.288826,-0.053131,-0.028777,0.250338,0.195098,-0.148724,-0.290824,-0.125877,0.180180,0.354295,0.577382,-0.228447,0.163087,-0.183397,0.260615,-0.171740,-0.031204,0.244014,0.105699,-0.036491,0.115055,-0.007527,-0.052632,0.013027,0.416074,-0.017966,-0.708735,0.236876,-0.117665,-0.111352,-0.443995,0.410901,-0.011886,0.046861,0.091703,-0.184600,0.221407,0.269232,0.177273,0.363924,-0.455474,-0.119813,-0.366940,-0.055813,0.516289,-0.088914,-0.246713,0.242758,0.021364,-0.639890,-0.216947,0.004212,-0.169434,-0.035090,0.627532,0.382586,-0.420119,0.131297,-0.472940,-0.112003,-0.182681,-0.252621,-0.294460,-0.219538,-0.154957,-0.492630,-0.048810,-0.187430,-0.351309,0.155147,0.043745,-0.017155,0.477792,-0.772887,0.236787,0.421215,0.117875,-0.240505,0.421045,0.121690,0.143525,0.057601,-0.173347,0.241905,0.169336,0.445611,0.237990,0.424771,-0.109472,-0.230788,-0.365626,0.348688', '1301022', '1947080', '21360412', '34429100');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27038228', '王牌特工：源起', '动作', '影片讲述的是，随着历史上最恶劣的暴君和犯罪策划者的聚集，他们展开了一场足以消灭数百万人的战争。此时，一个男人和他的徒弟挺身而出并必须与时间赛跑，以阻止恶人们的野心。本片由马修·沃恩自编自导，马修·古迪、杰玛·阿特登、亚伦·泰勒-约翰逊、拉尔夫·费因斯、哈里斯·迪金森出 演，故事将是王牌特工系列的前传。', '拉尔夫·费因斯', '马修·沃恩', 5.3, 49237, 'tt6856242', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2614322167.jpg', 9.2, 34, 43.3, 11.5, 2.1, '0.198805,-0.152603,-0.480446,0.805008,0.060779,-0.127927,1.028398,-0.071923,-0.356877,0.057695,0.183157,0.779832,-0.214793,-0.206095,0.589691,-0.200867,-0.636452,-0.786022,-0.384848,-0.113576,0.102914,-0.547722,-0.390540,-0.433559,-0.058482,-0.546187,0.655337,-0.315644,-0.326468,0.397488,0.736922,0.290292,-0.074284,0.423913,0.171750,-0.067384,-0.019115,-0.389434,-0.409161,0.170261,0.111027,-0.192768,-0.099117,0.030217,-0.134084,0.321890,0.347912,-0.605994,0.256325,-0.315765,0.380757,-0.512061,-0.145632,-0.104797,0.145091,-0.167193,0.218857,0.563035,0.166354,-0.202619,-0.135441,-0.219607,-1.016691,-0.058727,0.008614,0.253611,-0.471179,0.405087,-0.163358,0.081913,0.112527,-0.187305,0.100371,0.266485,0.510618,-0.027252,-0.101488,-0.124780,-0.578100,0.093084,0.609263,-0.074495,-0.145450,0.210431,-0.043996,-0.557931,-0.283093,-0.311974,-0.503319,0.186482,0.360885,-0.306446,0.108489,0.467708,-0.588403,-0.218336,-0.466520,-0.416015,0.047531,-0.447826,-0.206036,-0.838809,-0.272643,-0.272640,-0.258167,-0.190071,-0.023607,-0.414272,0.891137,-0.592621,-0.077392,0.593924,0.209773,-0.028011,0.494950,0.049884,0.348416,-0.245119,-0.244283,0.354100,0.069881,0.360222,0.076996,0.470446,0.168493,-0.191523,-0.139151,0.785814', '3318306', '1793922', '4820775', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27038235', '薄荷', '剧情', '故事聚焦在一位母亲的身上。一次在外游玩的过程中，她的孩子和丈夫被黑帮悉数杀害。原本遵纪守法的她希望借助于法律的力量制裁这些罪犯，但整个城市的警察和司法系统已经完全腐败。最后，这位失去一切的母亲，只好自己拿起了枪和武器，展开了复仇。', '詹妮弗·加纳', '皮埃尔·莫瑞尔', 6.7, 13346, 'tt6850820', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2523586097.jpg', 1.2, 9.4, 53.1, 28.2, 8.1, '0.155896,0.075440,-0.646811,0.714803,-0.505808,-0.277063,0.815204,-0.132030,-0.557067,-0.316764,0.190653,1.036420,0.146031,0.351418,0.052518,-0.061507,-0.380219,-1.146456,-0.385356,0.107638,-0.511510,-0.500117,-0.196048,-0.085130,-0.340328,-0.255368,0.737587,-0.002880,-0.232462,0.059592,0.188722,0.121266,-0.225042,0.557681,-0.321585,-0.173141,-0.087156,-0.181376,-0.409927,0.206792,0.148794,-0.403825,-0.089077,0.688081,-0.157461,0.274877,0.781053,-0.400793,-0.029060,-0.416025,0.393522,-0.463587,-0.078734,0.194318,0.297630,0.118937,0.283220,0.215226,-0.068411,-0.173715,0.256144,-0.209468,-0.928412,-0.463617,-0.067786,-0.010070,-0.652473,0.470045,-0.283951,0.203882,-0.171148,-0.331117,0.439251,0.140948,0.024706,0.456486,-0.733410,-0.082532,-0.627784,0.151128,0.512315,-0.276485,-0.348645,0.179102,-0.368894,-0.426680,-0.288590,-0.271098,-0.384475,-0.080742,0.440912,0.254849,-0.490660,0.547706,-0.711566,-0.179812,-0.239516,-0.435253,-0.085265,-0.518585,-0.054966,-0.273400,-0.070526,-0.369337,-0.315379,0.037789,0.282073,-0.056995,0.793166,-0.718927,0.243987,0.520957,0.130031,-0.712719,0.360375,0.174781,0.536367,0.031285,-0.216661,-0.014420,0.397450,0.701492,0.468162,0.352700,-0.089651,-0.043957,-0.359296,0.617278', '30345227', '25928048', '30163500', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27038968', '蚯蚓', '剧情', '得了脑瘫的父亲李元术（金正均饰）和女儿李子若（吴艺雪饰）相依为命，住在江华岛。李元书为女儿考上首尔的贵族艺术高中兴奋不已，和女儿开心搬家到首尔。不料噩梦也就此开始。子若因为在唱诗班长大，音域很高，很快在学校展露头角，也因此被以惠善为首的女同学们嫉恨。子若坚强好胜，反抗着校园暴力，却不断遭到更加残酷的回击，最后受不了无休止地折磨而自杀。父亲元术为查明事情的真相，在社会各界伸冤，但这个社会不理会弱者的呻吟，于是元术决定用自己的方式惩治了这些欺负过女儿的人们。', '金正均', '尹学烈', 7.3, 28984, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2458429082.jpg', 0.9, 5.1, 37.6, 39.4, 16.9, '0.159368,0.021510,-0.788172,0.542018,-0.279339,-0.146629,0.679686,0.191172,-0.588674,-0.115573,0.071620,0.640085,-0.088701,0.530674,0.014902,-0.230662,-0.118681,-0.598476,0.122829,0.052934,-0.185257,-0.342658,0.311165,-0.381808,-0.216725,-0.297422,0.573108,0.178164,-0.166230,0.343853,0.272266,0.283296,0.234954,0.465672,-0.242337,-0.064815,-0.150431,0.194610,-0.138497,0.082317,0.119920,-0.217759,-0.302004,0.346726,-0.050883,0.113775,0.684268,-0.085917,-0.131086,-0.230325,0.509452,-0.566151,-0.106066,0.480394,0.395027,-0.223680,0.270022,0.018551,-0.089651,0.203005,0.004636,0.065116,-0.590084,0.056974,0.259217,-0.159039,-0.758179,0.430341,-0.084433,-0.161019,-0.004641,-0.378016,0.045642,0.484519,-0.058884,0.491286,-0.623238,0.209824,-0.462336,0.143401,0.804150,0.044931,-0.124743,0.075360,-0.131737,-0.382833,0.104561,-0.606796,-0.566255,-0.187219,0.209834,-0.054078,-0.524742,0.278096,-0.311540,-0.288567,-0.023334,-0.137308,-0.036761,-0.643715,-0.203672,-0.316739,-0.024322,-0.288956,-0.284241,-0.059430,0.012176,-0.220392,0.797278,-0.893233,0.278851,0.576878,0.312573,-0.679646,0.379436,0.376986,0.031177,0.000578,-0.281938,0.228937,0.018548,0.331863,0.065497,0.242075,0.074829,-0.190793,-0.322052,0.441765', '1877596', '35030151', '1301022', '4861627');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27039069', '宝贝儿', '剧情', '残疾女孩江萌（杨幂 饰）与年迈的养母相依为命，为了不让养母流落养老院，江萌进城打工，没想到在医院碰到了与自己同病相怜的无肛女婴，引起了江萌的怜爱。江萌发现，无肛女婴的父亲（郭京飞 饰）匆匆带出医院，意图放弃治疗。就在无肛女婴生死存亡之际，江萌踏上了拯救生命的征程，到处打听孩子的下落，在这个寻找的过程中女护士的身世之谜也逐渐被揭开。', '杨幂', '刘杰', 5.3, 45969, 'tt8846198', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2531326284.jpg', 13, 29.8, 40.9, 12.1, 4.1, '0.196506,0.024112,-0.696447,0.184095,-0.302079,-0.355501,0.912077,0.070215,-0.559787,-0.139402,0.211749,0.662253,-0.034848,0.405644,0.043957,0.107590,-0.109907,-0.482270,-0.098259,-0.010981,-0.542823,-0.196328,-0.016328,-0.038471,-0.348410,-0.414064,0.695266,0.258333,-0.214198,0.500268,0.265339,0.468539,-0.569533,0.370636,-0.389168,0.216706,-0.180822,0.352387,-0.143440,0.410054,0.371141,-0.465795,-0.124024,0.207736,-0.422558,0.553369,0.993707,-0.084745,0.146443,-0.157676,0.461146,-0.185599,-0.115704,-0.083291,0.280402,-0.098566,0.105294,0.099710,-0.280110,-0.099442,0.300418,-0.042327,-0.369452,0.161540,0.438386,0.426847,-0.744479,0.320083,-0.196894,-0.209389,0.311305,-0.608749,0.636976,0.621311,0.031675,0.448510,-0.293876,0.240047,-0.505678,0.098835,0.352102,-0.357023,0.185531,0.410544,-0.140335,-0.391181,0.325836,-0.228083,-0.513899,0.101544,0.288437,0.277005,-0.627454,0.116626,-0.295073,-0.126294,-0.503760,-0.227446,0.208072,-0.271838,-0.117323,-0.317732,-0.092780,-0.129509,-0.275807,0.117507,0.140817,-0.303558,0.606402,-0.842312,0.362361,0.591890,0.294131,-0.661498,0.762211,-0.190543,0.235997,-0.395865,0.206682,0.395868,0.178381,0.415171,0.102481,0.147950,-0.450816,0.069274,-0.479125,0.190229', '21619567', '1302384', '1417036', '1908318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27039358', '蜂鸟计划', '剧情', '影片讲述纽约的一对兄弟文森特（杰西·艾森伯格）与安东（亚历山大·斯卡斯加德），他们是高风险高频次交易操作员，梦想建造从堪萨斯州到新泽西州之间的直线光纤电缆，以赚取百万财富，然而他们以前的老板伊娃·托雷斯——一个强大又有极强控制欲的女人的紧逼让他们的计划充满了挫折和挑战。', '杰西·艾森伯格', '阮金', 7, 16104, 'tt6866224', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2630378196.jpg', 0.3, 3.8, 47.8, 41.6, 6.5, '0.165873,-0.381304,-0.713441,0.643490,-0.061549,-0.392655,0.938812,0.213658,-0.352077,0.211189,0.322156,0.801947,-0.128058,-0.294642,0.245789,0.008368,-0.157609,-0.512714,0.046102,-0.250523,-0.080036,-0.705778,-0.382969,-0.324026,-0.085655,-0.375994,0.558049,-0.242781,-0.155898,0.488703,0.081978,0.367696,0.052503,0.527453,-0.086901,0.083204,0.248800,-0.016859,-0.495922,0.437246,-0.042880,0.231291,-0.249002,0.191429,-0.012124,0.434477,0.364551,-0.274098,0.220098,0.186759,0.101483,-0.145973,-0.104399,-0.031200,-0.010737,-0.079364,-0.012769,0.117906,-0.284912,-0.235846,0.118955,-0.022950,-0.856537,-0.119940,-0.146366,-0.054546,-0.503499,0.221185,-0.208348,-0.062244,0.255932,-0.329835,-0.232211,0.261284,0.154018,0.372091,-0.229078,-0.173788,-0.691496,0.093195,0.569736,-0.086988,-0.325103,0.114905,-0.308972,-0.482137,-0.279723,-0.338509,-0.692844,-0.128575,0.557093,-0.093890,0.119161,0.569828,-0.765466,0.018456,-0.293720,-0.169683,-0.006752,-0.500699,-0.122940,-0.865794,-0.390747,-0.342107,-0.109348,0.202495,0.241218,-0.215124,0.712869,-0.880415,0.154825,0.872874,0.480546,-0.336766,0.544110,-0.115698,0.150442,-0.384028,-0.187403,-0.038900,0.030842,0.282279,0.139120,0.371945,0.193488,0.146570,-0.184227,0.869459', '10774184', '1292000', '3005387', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27039378', '今夜在浪漫剧场', '爱情', '大电影制片厂即将步入黄昏时代之际，在某电影厂担任副导演的青年健司（坂口健太郎 饰）经历了人生刻骨铭心的邂逅。此前他在某座电影院内发现一卷被废弃的胶片，胶片中的电影女主角男人头公主（绫濑遥 饰）令他神魂颠倒，痴迷非常。当得知这卷胶片即将卖给他人时，健司无比怅然。最后一次的放映过程中，令人意想不到的事情发生了，那位公主竟然从大银幕中走了出来。在此之后，刁蛮公主将健司视为仆人，暂时徘徊人间，体会这个多彩的世界。与此同时，健司得到了可以升为导演的机会，为此他以自己和公主为蓝本努力撰写剧本。在这一过程中，他渐渐喜欢上了公主，可是却也得知公主身上一个令他怅然的秘密……©豆瓣', '绫濑遥', '武内英树', 7.1, 37971, 'tt6908760', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2546938024.jpg', 0.6, 5.4, 44.1, 36.5, 13.4, '-0.109198,0.527511,-0.607970,0.740328,0.253265,-0.181371,0.952936,0.083058,-0.601458,-0.265530,0.314030,0.660736,-0.442976,0.236855,0.530828,0.079151,-0.421122,-0.723111,-0.252674,-0.365374,-0.201673,-0.050406,-0.252870,-0.060887,-0.232604,-0.360847,0.932461,0.359808,-0.139903,0.217070,0.407605,-0.118038,-0.056917,0.612381,0.128696,0.211541,0.197283,0.016948,0.012193,0.358262,0.105883,-0.518248,0.002598,0.177355,-0.178130,0.177278,0.827147,-0.410356,-0.139054,-0.193304,0.527934,0.106640,-0.228113,0.122718,-0.006969,0.154899,0.275154,-0.059728,-0.276105,-0.237262,0.144788,-0.181106,-0.589956,0.063297,-0.052996,0.149074,-0.502209,0.119042,-0.190060,0.173313,0.324457,-0.245871,0.283049,0.048255,0.557161,0.211482,-0.374620,-0.062089,-0.253695,0.514338,0.487223,0.126139,-0.118634,0.490347,-0.081923,-0.466664,-0.060742,-0.321532,-0.409395,0.310534,0.138425,0.180069,-0.032831,0.346880,-0.201682,-0.166992,-0.313554,-0.153229,0.238560,-0.531673,-0.142814,-0.333837,-0.127273,-0.173177,-0.153600,-0.108352,0.084881,-0.410892,0.717180,-0.703263,0.032330,0.483153,0.060906,-0.096075,0.834387,-0.021799,-0.111925,-0.258818,-0.066488,0.022712,-0.173119,0.427967,-0.034056,0.476464,-0.122227,-0.252261,-0.490675,0.474630', '5416009', '1467779', '1417036', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27040157', '教授', '剧情', '故事讲述一位厌世的大学教授被诊断癌症，得知只有6个月的生命后决定抛弃一切伪装，从而改变自己人生的故事。他要求自己尽可能的大胆而自由的生活，并且幽默而从容，不计后果，甚至有点接近疯狂……', '约翰尼·德普', '韦恩·罗伯茨', 7.6, 17365, 'tt6865690', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2554535140.jpg', 0.7, 3.9, 30.3, 44.7, 20.3, '-0.133171,0.035582,-0.179337,0.875439,-0.560313,-0.060358,0.498528,-0.128999,-0.597231,-0.421970,0.205173,0.570404,0.074996,0.203484,0.482988,-0.407709,-0.216116,-0.645698,0.005243,0.206542,-0.430383,-0.778222,0.057814,-0.617402,-0.174420,-0.443864,0.749844,0.125409,-0.196770,0.141799,-0.119868,0.321668,0.125164,0.244108,-0.092429,-0.141939,-0.050810,0.139171,-0.279803,0.103151,0.012723,-0.087868,0.062504,0.681884,-0.626820,0.305869,1.005166,-0.502843,-0.752919,-0.162503,1.078016,-0.299933,-0.066724,0.341089,-0.192925,0.392676,0.288713,0.290741,-0.239134,-0.351393,0.003894,-0.184344,-1.057063,-0.125032,-0.179066,-0.095622,-0.274949,-0.189563,0.285128,0.470740,0.265408,-0.347544,-0.232471,0.398387,0.739027,0.307652,-0.718476,0.064744,-0.215335,0.418675,0.762278,-0.300585,-0.776456,0.804026,-0.324975,-0.031864,0.068819,-0.356826,-0.613285,0.000509,-0.219754,0.287934,-0.294003,0.484267,-0.120109,-0.367675,-0.392503,-0.216904,0.296511,-0.488456,-0.190985,-0.287729,-0.456672,0.037395,0.023447,-0.340853,0.015311,-0.438216,1.027635,-0.653379,0.308475,0.593896,-0.147560,-1.028156,0.179246,0.080505,0.095452,-0.358331,0.151414,0.977455,-0.116681,-0.000138,-0.180409,0.212452,-0.253342,0.283445,-0.472374,0.591423', '6844861', '24284209', '27602116', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27040349', '二次初恋', '喜剧', '叶兰（朱茵 饰）和路建国（王志飞 饰）结婚多年，最初的激情早已经被时间磨灭暗淡，夫妻两人之间常常因为鸡毛蒜皮的小事产生争吵。在二十周年结婚纪念日那天，叶兰和丈夫之间发生了一场前所未有的激烈争吵，叶兰忍不住提出了离婚，一气之下，路建国竟然选择了离家出走。某日，一个年轻人敲响了叶兰家的门，他说自己叫路大民（杜天皓 饰），是路建国的侄子。路大民的出现改变了叶兰苍白无助的生活，他不仅和叶兰的儿子成为了朋友，还狠狠捉弄了一把企图追求叶兰的萧峰（黄征 饰）。随着时间的推移，叶兰渐渐开始对路大民的身份产生了怀疑，因为他实在是太像年轻时候的路建国了。©豆瓣', '朱茵', '戴玮', 4.2, 4664, 'tt7505208', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2497757292.jpg', 33.1, 35.2, 22.9, 5.1, 3.6, '0.364949,0.099914,-0.886804,0.280149,-0.171548,-0.724394,0.661452,0.105547,-0.523891,-0.229690,0.223706,0.495288,-0.447006,0.186835,0.390534,-0.263156,-0.159333,-0.763447,0.322294,-0.059408,-0.155703,-0.250627,0.156594,-0.019284,-0.237230,-0.299233,0.394769,-0.148584,-0.116124,0.761397,0.302714,-0.119597,0.034743,0.608830,0.255241,0.377556,0.132529,0.378946,-0.417209,-0.279593,0.001386,-0.073669,-0.064184,0.058976,-0.123134,0.667758,0.251821,0.162900,-0.270397,-0.234756,0.432311,-0.325488,-0.233644,0.210871,0.470947,0.343651,0.254534,0.209927,-0.446348,-0.183888,0.002078,0.083830,-0.135325,0.511185,0.069556,0.187995,-0.396404,0.524989,-0.148070,-0.412302,0.386047,-0.588143,0.356713,0.563682,0.402938,0.383356,-0.527201,-0.218967,-0.370326,0.099115,0.730904,0.042499,-0.079638,0.375406,-0.148264,-0.103883,0.010215,0.132978,-0.373156,-0.059797,0.449266,-0.124230,-0.439900,0.601033,-0.501171,-0.113807,0.009482,-0.126173,0.256288,-0.563280,0.020382,-0.232249,-0.370409,-0.583047,-0.342089,0.143121,-0.095518,-0.513804,0.599169,-0.686940,0.260925,0.367625,0.563912,-0.526949,0.369119,0.164572,-0.030932,-0.069132,0.397187,0.153308,-0.497557,0.274219,0.059590,0.412011,-0.043624,0.036140,-0.077932,0.540048', '1292869', '3111650', '26611458', '25856453');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27040735', '消失的夜晚', '悬疑', '该片翻拍西班牙电影《女尸谜案》。围绕国立科学搜查院遗失的一具尸体而展开的故事。 丈夫（金刚于饰）计划了一场杀死妻子（金喜爱饰）的完美犯罪，可短短几个小时后，妻子的尸体就在国科搜的停尸间里不翼而飞，丈夫也在此时收到了一封信“我会在埋葬了我们的秘密的地方等你”。警方怀疑这一切都是丈夫所为，而丈夫却坚称这全都是妻子的自导自演，她究竟死了吗？', '金相庆', '李昌熙', 6.8, 8006, 'tt6955298', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2512145234.jpg', 1.1, 8, 49.8, 31.4, 9.7, '-0.201478,-0.285390,-0.677325,0.458079,-0.102254,-0.254088,0.733902,-0.035048,-0.509839,-0.231660,0.412297,0.496614,0.109024,-0.025778,-0.009655,0.164925,-0.413682,-0.792413,-0.232772,-0.482646,-0.387922,-0.217498,-0.221667,-0.518407,0.304909,-0.235707,0.569579,0.122771,0.121839,-0.067896,0.382401,-0.002167,-0.355372,0.156891,-0.205596,0.225444,0.093069,0.074075,-0.116719,0.354290,0.215709,-0.406958,0.141625,0.208071,-0.234364,0.376208,0.882295,-0.247059,-0.237540,-0.158866,0.373844,-0.381201,-0.043313,0.210322,0.333766,-0.121414,0.280841,0.462826,-0.399345,-0.266423,0.195066,0.054180,-0.816305,-0.233034,0.085708,0.208969,-0.549728,0.643371,-0.093934,0.200300,-0.102075,-0.192991,0.453531,0.212575,0.028255,0.412597,-0.153093,-0.158602,-0.421135,0.560375,0.254464,-0.245828,0.172688,0.486175,0.170247,-0.425507,-0.150224,0.047818,-0.353792,0.086882,0.266015,-0.033059,-0.240644,0.000766,-0.485136,-0.251821,-0.452629,-0.066750,-0.163452,-0.556972,0.011271,-0.207896,-0.175281,0.109397,-0.093112,0.068626,0.125213,-0.209867,0.438194,-0.320582,0.425417,0.524958,0.006106,-0.703235,0.449112,0.181027,0.125766,-0.146849,0.042001,0.157333,0.234562,0.472448,0.176916,0.180686,0.180371,-0.170773,-0.706978,0.465541', '21619567', '25928048', '26678784', '33415943');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27040737', '祈祷落幕时', '剧情', '位于东京都葛饰区的一座公寓内，一具高度腐烂的尸体被人发现。经警方初步查明，死者是来自滋贺县的押谷道子，她的死亡实属他杀。警视厅搜查一课刑警松宫（沟端淳平 饰）调查发现，押谷此次上都是为了拜访并观看学生时代的好友浅居博美（松岛菜菜子 饰）的舞台剧的。虽然浅居有充分的不在场证明，不过她和加贺恭一郎（阿部宽 饰）的合影依然引起松宫的注意。与此同时，在道子遇害公寓的附近，一具焚烧后的尸体被人发现。现场的一件遗物令加贺激动万分，因为这与他多年未曾谋面的母亲有着千丝万缕的关系。两起案件，以及失踪的人，将浅居和加贺再度连接在一起……本片根据日本著名推理作家东野圭吾的同名小说改编。©豆瓣', '阿部宽', '福泽克雄', 7.9, 158924, 'tt7080138', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2552073598.jpg', 0.1, 1.4, 22.8, 54.3, 21.4, '0.542932,-0.240499,-0.598051,0.465979,0.063216,0.084265,0.739297,0.003903,-0.771287,-0.541775,0.387568,0.750476,-0.297252,0.129755,0.060677,-0.046000,-0.201483,-0.677466,-0.252945,-0.281492,-0.414502,-0.434459,-0.269952,-0.060961,-0.118354,-0.217712,0.762804,0.180827,-0.017567,0.652119,0.112621,0.283463,-0.350507,0.432682,0.080749,0.108755,0.172159,0.088895,0.037815,0.203640,-0.242760,-0.391596,0.133924,0.124938,-0.040821,0.563697,0.782798,-0.082238,-0.312767,-0.052563,0.363870,-0.093763,0.083711,0.234515,0.630782,0.019869,0.145951,0.557772,-0.514086,-0.227114,0.112857,0.141046,-0.669596,-0.065264,0.482969,0.336396,-0.341139,0.651069,-0.098176,-0.003817,0.061065,-0.209941,0.440681,0.239531,0.247260,0.313047,0.011478,-0.054578,-0.264131,0.258292,0.595699,-0.124215,0.157192,-0.033727,-0.213799,-0.551051,-0.189949,-0.081636,-0.125631,0.139530,0.001647,0.205291,-0.113432,-0.039494,-0.547020,-0.152889,-0.171323,-0.241281,0.110670,-0.184574,-0.021231,-0.801276,-0.284936,-0.306391,-0.125814,0.052599,0.200264,-0.460630,0.577549,-0.574032,0.028899,0.436630,0.153141,-0.235903,0.745109,-0.064892,-0.238478,-0.252461,-0.250788,0.162620,0.440628,0.339936,0.082384,0.313314,-0.129328,-0.309271,-0.537007,0.156578', '3811356', '1302050', '26365262', '10466639');
