INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27040921', '音乐家', '剧情', '《音乐家》根据冼星海在阿拉木图的经历改编，赞颂人民音乐家在异国他乡遭受苦难却仍心系祖国的伟大精神。战时艰苦，冼星海在哈萨克斯坦隐姓埋名，却不忘寻找机会回到祖国。同时他的音乐《黄河大合唱》在遥远的延安时刻鼓舞着艰苦抗战的人民，激励无数有志青年为祖国顽强斗争。而在阿拉木图，他的音乐才华使他结识了当地音乐家拜卡达莫夫。两人建立了深厚友谊，正是他的音乐让不同的民族凝聚在一起，共同克服困难。他所作的《阿曼盖尔德》便是这样文化互相影响包容后的一个成果，对当地人民产生深刻影响，为两国的友谊发展奠定了坚实基础。', '胡军', '西尔扎提·亚合甫', 6.8, 4422, 'tt7014404', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2556763879.jpg', 1.6, 8.5, 49.8, 28.3, 11.7, '-0.060556,0.068533,-0.853655,0.865465,0.124318,-0.305739,0.488855,0.126966,-0.316921,0.117443,0.348053,0.763464,0.172815,-0.114996,0.048488,-0.269922,-0.328578,-1.064804,-0.025014,0.279626,0.010414,-0.319515,-0.379290,-0.109755,-0.591670,-0.398612,0.611307,0.321319,-0.430510,0.456859,-0.143501,0.038215,0.143655,0.404055,-0.347192,0.011751,0.185624,0.098879,-0.557356,-0.150842,0.084338,-0.439388,-0.422766,0.330745,-0.204791,0.054569,0.667538,-0.352426,0.013382,-0.211930,0.585911,-0.269074,0.164518,0.035345,0.180614,0.254311,-0.015338,0.158213,-0.110459,-0.152018,-0.169416,-0.214473,-0.775881,-0.289821,0.220900,0.172439,-0.703904,1.162082,0.205356,-0.414491,0.238075,-0.161638,-0.024451,0.737110,0.303012,0.699173,-0.191774,0.200856,-0.087256,0.318002,1.228813,-0.303454,-0.578364,0.087533,-0.783966,-0.465496,0.150478,-0.144984,-0.641066,-0.581994,0.148432,-0.276221,0.150895,0.464560,-0.784783,0.163720,-0.228413,-0.181154,0.267618,-0.506843,0.107484,-0.604019,-0.371822,-0.491674,-0.004660,0.108664,0.163313,-0.308725,1.397138,-0.936503,0.124029,0.767636,0.126161,-0.495037,0.602912,0.265924,0.126898,-0.113062,-0.175480,0.686902,-0.317983,0.400261,-0.071697,0.229724,-0.026653,0.354650,-0.405112,0.634877', '27602116', '26283288', '1826173', '26809007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27041519', '哀乐女子天团', '剧情', '山山、宫和leo，三个坚持音乐梦想的女孩误打误撞来到殡葬现场，被迫和刘翠、春花同台唱丧。在她们搞砸的葬礼上，女孩们开始发现生死的重量、告别的意义，于是开始认真对待唱丧这件事，五个女孩也从陌生敌意相处成惺惺相惜的好姐妹。当一切走向正轨的时候，山山她们三个却突然接到经纪公司的电话可以包装她们出道，但需要她们与殡葬行业划清界限。一边是她们向往的真正舞台，一边是患难与共的哀乐姐妹们，她们该何去何从？', '杨小兰', '桑木天', 6.6, 6688, 'tt9685774', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2472861613.jpg', 2.3, 12, 48, 30.6, 7.2, '0.343776,0.207090,-0.725068,0.384587,-0.048553,-0.158659,0.660522,0.064490,-0.438679,-0.168733,0.114687,0.671619,-0.121073,0.850154,0.200350,-0.175849,-0.434857,-0.953643,-0.032287,-0.279298,-0.340276,-0.197267,0.440969,-0.218939,-0.383003,0.141948,0.582297,-0.006181,-0.000451,0.480440,0.582800,-0.008289,-0.373555,0.338613,-0.226166,0.034168,-0.022120,0.046406,-0.866853,-0.120499,-0.177332,0.458860,-0.542868,0.054677,0.381260,0.023693,0.577047,-0.076576,-0.367837,0.041273,0.234714,-0.047616,0.136836,0.135511,0.445622,0.108849,0.331650,0.282324,-0.045905,-0.103011,-0.072301,-0.215610,-0.341748,0.331881,0.030401,0.240356,-0.571433,0.227567,0.108920,-0.182718,0.072410,-0.391417,0.152423,0.499298,0.216462,0.572571,-0.186358,0.027241,-0.430396,0.063672,1.101358,0.110581,-0.161370,0.603057,0.226036,-0.377426,-0.246261,0.079902,-0.286820,0.073333,0.242277,0.198476,0.025770,-0.119851,-0.702039,-0.074119,0.046987,-0.248550,0.239631,-0.853788,0.080571,-0.582051,-0.186517,-0.418306,-0.691117,0.249999,-0.001697,0.046320,0.863967,-0.797887,0.086076,0.311892,0.176470,-0.606609,0.453930,0.034983,0.306536,-0.321203,-0.140446,0.008494,-0.300393,0.331723,0.040730,0.353749,-0.190253,0.119739,-0.566497,0.040440', '25721544', '4301278', '1294713', '3212120');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27041677', '人间，空间，时间和人', '剧情', '《人，空间，时间和人》讲述了一艘老军舰上不同年龄和职业的人之间发生的故事， 强奸，谋杀，兵变， 金基德没有给予片中的人物丝毫的放松时间。 电影中的所有人物既没有名字也没有背景，唯一重要的只有让人喘不过气来的“当下”。在一个戏剧性的人际关系的漩涡之中，一场关于食物和生存的斗争完全转向了荒诞。', '安圣基', '金基德', 6.4, 15789, 'tt6927316', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2512170420.jpg', 6.7, 16.8, 39.4, 24.6, 12.6, '0.593006,0.013794,-0.992230,0.969363,-0.141512,0.123154,1.129507,-0.082482,-0.839298,-0.368576,0.109751,0.768626,-0.164657,-0.454387,0.188243,-0.460058,-0.558201,-0.937105,-0.335686,-0.016846,-0.604735,-0.681152,-0.195238,-0.334680,-0.076723,-0.479958,0.670570,0.082850,-0.304595,0.286270,0.111108,-0.159338,-0.077988,0.660557,0.017396,0.135990,0.232119,0.334276,-0.176539,0.083810,-0.062601,-0.290011,-0.221855,0.355548,-0.055881,0.710415,0.531436,-0.580167,-0.373628,0.135072,0.133266,-0.324319,-0.298667,-0.306172,0.251881,-0.279157,0.472862,0.259916,-0.032879,-0.178361,0.143674,0.000269,-1.192371,-0.100821,0.377086,0.388457,-0.178921,0.741636,-0.040107,-0.294968,-0.187850,-0.180444,0.446328,0.271717,0.551788,0.322473,-0.180188,0.058291,-0.481836,0.313220,0.943774,0.125334,-0.666208,0.661041,-0.531348,-0.518385,-0.711774,-0.665325,-0.289954,0.143304,0.168397,0.396289,-0.544223,0.387553,-0.692413,0.143810,0.075906,-0.355433,-0.044681,-0.613610,-0.144636,-0.528421,-0.351681,-0.654692,-0.280677,-0.000314,0.243187,-0.404042,0.931456,-0.690372,-0.028543,0.360188,0.152505,-0.357942,1.096877,0.101817,0.120998,-0.256980,0.032886,-0.103482,-0.032540,0.189352,-0.048649,0.380994,-0.154749,-0.262958,-0.197835,0.518040', '35360296', '1417428', '25932086', '1303542');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27042405', '大坏狐狸的故事', '喜剧', '电影分为三个可爱的小故事。一天，在风景怡人的农场里，小猪、兔子和鸭子见到了一个人类的小宝宝。负责护送小宝宝的鹈鹕拜托三只小动物将宝宝平安的送到他的人类母亲的手中，就这样，三只有些脱线的动物踏上了旅途。大坏狐狸一心想要将肥美的母鸡当做自己的盘中餐，无奈母鸡太过强大，狐狸根本不是她的对手。既然打不过母鸡，狐狸将“魔爪”伸向了母鸡正在孵的三枚鸡蛋，狐狸决定将这三只小鸡孵出来养大之后再把他们一一吃掉。然而，三只小鸡似乎将狐狸当成了他们的妈妈，亦以为他们自己也是狐狸。圣诞节就快要来了，农场里的动物们都欢天喜地的准备迎接圣诞老人的到来。然而，鸭子和兔子却在一场意外之中“杀死”的圣诞老人。©豆瓣', '纪尧姆·达尔诺', '本杰明·雷内', 8.3, 86744, 'tt5851904', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2515632084.jpg', 0.2, 0.7, 15.6, 49.6, 33.9, '0.444842,-0.197517,-0.455396,0.436232,-0.283244,-0.132474,0.746018,0.129144,-0.110505,0.370751,0.100365,0.646502,-0.141232,0.430147,-0.064946,-0.010377,0.083236,-0.438253,-0.382447,0.042044,-0.046208,-0.028660,-0.479261,-0.102669,0.420364,0.060417,0.495145,-0.334483,0.172364,0.524747,0.128122,-0.341554,-0.237408,0.094264,-0.408179,0.150318,-0.070968,-0.010842,0.282533,0.248301,0.055488,0.239531,0.075052,0.251020,0.047948,0.163131,0.992835,-1.037100,-0.332275,-0.557057,-0.076834,-0.439909,0.010226,0.480646,0.292679,-0.058395,0.337445,-0.476616,-0.114168,0.393615,0.366241,-0.256529,-0.588072,0.041640,-0.370581,0.202556,-0.498300,0.317578,0.229200,0.363084,0.512161,-0.484674,0.250182,0.105722,0.037163,0.716909,-0.015851,0.319745,-0.726419,0.047444,0.400154,-0.289063,-0.005417,0.407187,0.172038,-0.506515,0.198849,-0.160502,-0.263310,-0.078371,0.604399,0.117040,-0.906274,0.259088,-1.011119,0.162175,-0.234394,-0.259430,-0.103421,-0.423487,-0.165462,-0.020081,0.427547,-0.301110,-0.334803,0.257475,0.524453,-0.239353,0.754252,-0.521358,0.359773,0.482010,0.066827,-0.018963,0.397959,-0.489177,0.199315,-0.075327,0.214552,-0.355146,0.282801,0.365806,0.819395,0.571536,-0.082383,-0.262210,-0.564341,0.688117', '1458910', '3012819', '7056398', '1294457');
