INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27042526', '胡杨的夏天', '喜剧', '故事讲述了摄影师胡杨为了扩大经营，找到一位艺术商人开了家高端工作室，但条件是必须让时尚美食女主播夏天答应与艺术商人签约。于是，胡杨开始接近夏天，两人渐生情愫。没想到，夏天的追求者徐金宝从中捣乱，让他们一路窘迫，并揭穿了胡杨的骗局。夏天伤心地回到家乡新疆，没想到在新疆两人再次偶遇并相爱……', '朱一龙', '朱时茂', 5.1, 9553, 'tt10449234', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2502172705.jpg', 16.5, 34.5, 35, 8.3, 5.8, '0.254533,0.140722,-0.436085,0.277057,0.032047,-0.323474,0.213481,0.005050,-0.672512,-0.259168,-0.059016,0.567791,-0.364880,0.246645,0.397217,0.116366,-0.444270,-0.347634,0.254194,-0.245920,0.194482,-0.406745,0.095673,-0.210135,-0.268987,0.014726,0.491755,0.290231,-0.290939,0.484010,0.048501,-0.124547,-0.363092,0.462487,-0.018470,-0.329156,0.241808,0.250646,-0.758011,0.394997,-0.221890,-0.152408,-0.177131,-0.060205,0.098078,0.261451,0.263946,0.120549,-0.114633,0.084512,0.398237,-0.119552,-0.179192,-0.139624,0.338028,-0.023100,0.493556,0.183506,-0.034221,-0.147279,0.022517,-0.287720,-0.231106,0.447413,0.096818,-0.257241,-0.365301,0.188534,0.208207,-0.062514,0.082343,-0.527848,0.102801,0.267012,0.859492,0.304358,0.140115,0.305287,-0.484446,0.068389,0.743966,0.138490,0.117110,0.452026,-0.350889,-0.376578,0.196379,-0.013985,-0.062022,0.236192,0.159946,0.190749,-0.108540,0.075247,-0.844755,-0.049082,-0.231967,0.052910,0.458607,-0.419556,-0.131122,-0.634093,-0.094917,0.069223,-0.024249,-0.117060,0.130897,-0.396283,0.551893,-0.758649,0.002584,0.723093,0.588435,-0.638331,0.356568,-0.046859,-0.172554,-0.461329,-0.098738,0.219507,-0.135005,0.226079,0.024247,0.204604,-0.318869,-0.358932,-0.129444,0.049523', '26290398', '26280899', '25856453', '10606939');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27042738', '世界新闻', '剧情', '故事发生在美国内战结束不久之后，曾经在前线奋勇杀敌的军官基德上尉（汤姆·汉克斯 Tom Hanks 饰）如今成为了一名读报人。他辗转于一个又一个小镇，为生活在那里的居民们带来来自世界各地的最新的消息。一天，基德在德州遇见了一个名叫乔安娜（海伦娜·泽格尔 Helena Zengel 饰）的小女孩，这个可怜的姑娘在6年前被印第安人掳走抚养，如今，重新获得了自由的她将要回到叔叔和阿姨的身边开始正常人的生活，虽然这并不是乔安娜真正想要的。基德和乔安娜之间产生了一种奇妙的联结，于是，基德答应护送乔安娜去她应该去的地方，两人要共同面对的，除了险恶的自然环境外，还有叵测的人心。©豆瓣', '汤姆·汉克斯', '保罗·格林格拉斯', 7.2, 7225, 'tt6878306', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2623549939.jpg', 0.6, 3.8, 44.2, 40, 11.4, '0.297043,0.063012,-0.713226,0.660025,-0.268269,-0.189554,0.843281,0.028272,-0.464761,-0.468049,0.029833,1.012414,-0.026882,0.471343,0.492820,0.015963,-0.402633,-0.688014,-0.052713,-0.235224,-0.474627,-0.448274,-0.192349,-0.239571,0.001281,-0.157187,0.446396,0.098784,-0.144822,0.619377,0.166343,0.280956,-0.028734,0.570166,-0.322083,0.216137,0.190126,-0.131906,-0.366710,0.087374,0.211994,-0.148626,-0.051235,0.085858,0.209625,0.080110,0.723609,-0.499055,-0.043460,-0.018690,0.296618,-0.033133,0.158324,-0.020471,0.249022,-0.136087,0.048720,-0.039791,-0.255287,0.225837,0.146571,-0.200428,-0.680578,0.105230,0.070240,0.082929,-0.439477,0.366425,0.080025,-0.021651,0.202399,-0.390556,0.259711,0.844479,0.075031,0.478947,-0.138050,0.038503,-0.596731,0.060787,0.959322,0.084897,-0.168310,0.144049,-0.153787,-0.530884,-0.110950,-0.124171,-0.528300,0.084331,0.420421,-0.023179,-0.257577,0.222160,-0.685313,0.077107,-0.073290,-0.147227,0.183594,-0.392143,-0.229533,-0.672886,-0.006189,-0.450897,-0.065644,0.090358,-0.126365,-0.261634,0.843579,-0.939112,0.194607,0.418732,0.254847,-0.681724,0.599950,0.149850,0.262377,-0.067765,0.115406,0.414093,0.228269,0.552753,0.226845,0.357036,-0.100294,0.024563,-0.323848,0.509612', '25721544', '1292219', '30162520', '11541282');
