INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27043260', '绝密档案', '科幻', '提奥·詹姆斯加盟[绝密档案](Archive，暂译)。该片是[月球]的概念设计者加文·罗瑟里的导演处女作。故事设置在近未来，提奥饰演的科学家，创造出一款与人类十分接近的机器人，他的科研成果背后，却隐藏着不可告人的目的。[摩天大楼]摄影师劳里·罗斯将为本片掌镜。', '西奥·詹姆斯', '加文·罗瑟里', 6.9, 6859, 'tt6882604', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2608156973.jpg', 2.3, 8.8, 43.6, 33, 12.4, '0.180805,-0.105832,-0.714127,0.942464,0.173811,0.116296,0.826624,-0.200656,-0.409989,-0.495719,0.469733,0.619268,-0.206808,-0.068449,0.314003,0.228884,-0.439509,-0.384581,-0.315233,-0.258946,0.046118,-0.702894,-0.853215,-0.260142,-0.267366,-0.408691,0.923584,-0.166565,-0.480245,-0.365978,0.380289,0.294311,-0.271111,-0.043248,0.080976,-0.070153,0.276299,-0.373434,-0.396990,0.180599,-0.157150,0.001066,-0.286255,-0.054742,-0.340715,0.362397,0.584257,-0.277599,0.167359,0.075453,0.523824,-0.427970,0.156866,-0.431099,-0.044680,0.085755,0.034829,0.335192,0.135163,0.195932,0.170785,-0.402443,-1.138848,-0.151496,0.212628,0.283981,-0.450798,0.198518,-0.620556,-0.096407,0.168367,-0.550119,0.268879,0.004165,0.394754,0.340034,-0.016473,0.374922,-0.640153,0.169963,0.110723,0.036222,-0.260024,0.132355,-0.536008,-0.674377,-0.466652,-0.165214,-0.528674,-0.014444,0.362743,-0.318586,0.279029,0.356361,-0.726190,-0.088294,-0.274828,-0.222361,0.028404,-0.413519,0.065706,-0.860729,-0.029370,0.066957,0.052457,-0.250710,-0.026902,-0.770134,0.869009,-0.505978,-0.034794,0.710500,0.106195,-0.107831,0.685321,-0.074179,0.150649,-0.524672,-0.228003,0.149555,0.033811,0.029103,-0.175049,0.231481,0.200066,-0.443946,-0.529307,0.457478', '3318306', '1293433', '25932086', '4267948');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27045442', '钢铁飞龙之再见奥特曼', '动作', '保护地球、维护和平，奥特曼对于地球人来说曾经是神一样的存在，但是近几十年，他却消失不见行踪成谜……随之取替他的是钢铁飞龙精锐小分队——隶属于GSB地球安全保卫组织。而GSB近期不断收到地球能源异常报告，全球各地纷纷出现巨大灾难。GSB组织派出钢铁飞龙，查明能源异常原因，却意外发现事件与奥特曼有关系……新旧两代地球守护者的意外相见，却成为你死我活的敌对双方。到底，这是一场意外还是一场阴谋，是谁看到了最后的事实真相？', '侯勇', '王巍', 2.6, 5859, 'tt7476652', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2500046429.jpg', 84.8, 7.6, 2.3, 2.3, 3, '-0.288820,0.150932,-0.892464,0.297212,0.167804,0.421601,0.524074,-0.360298,-0.698649,-0.451774,0.311044,0.752455,-0.032429,-0.357728,-0.180300,-0.213723,-0.126430,-0.625991,0.106454,-0.333355,-0.287109,-0.345314,-0.675717,-0.330088,0.012123,-0.412264,0.784453,0.289460,-0.247994,0.572272,0.073482,0.445085,-0.476668,0.665110,-0.069723,-0.197208,0.194180,0.268139,-0.443887,0.060957,-0.403909,0.058288,-0.236605,0.457401,-0.237530,0.419053,0.178116,-0.465008,-0.352109,-0.312373,0.262051,-0.604133,-0.267047,-0.204169,1.020087,0.066014,0.051862,0.167095,0.209426,-0.158284,0.100444,0.215092,-0.765319,-0.005805,0.224457,0.566071,-0.390191,0.211894,-0.175195,-0.197511,-0.039198,-0.032780,0.464969,0.508271,0.714996,0.178688,-0.093651,0.325861,-0.420689,-0.306321,0.975751,-0.054607,-0.673217,0.094184,-0.218420,-0.418656,-0.156307,-0.461386,0.066571,0.313445,-0.108092,0.060612,0.249963,0.568376,-0.723355,0.133498,-0.304241,-0.358034,-0.107497,-0.377489,0.099883,-0.675573,-0.355978,-0.428695,-0.402061,0.381361,0.040868,-0.053078,0.615233,-0.835193,0.138025,0.515160,0.319366,-0.767764,0.424575,0.178176,-0.101549,-0.583297,0.148448,-0.004188,0.016569,0.131342,-0.202122,-0.292312,0.200564,-0.093211,-0.138249,0.220150', '1306983', '1293265', '5157137', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27045860', '原钻', '剧情', '影片讲述了一位纽约钻石店老板Howard Ratner（亚当·桑德勒 饰），他嗜赌成瘾，婚姻岌岌可危，还有一个对他不忠的女友（茱莉娅·福克斯 饰）。Howard Ratner欠Arno（埃里克·博高森 饰）钱，而打手们也一直威胁着让他还钱。当他买了一块价值数百万美元的稀有的未切割埃塞俄比亚蛋白原石，他觉得自己的霉运会就此终结。这块原石本来是打算拿去拍卖的，但当波士顿凯尔特人超级球星凯文·加内特走进宝石店，希望借走这块石头——它可以给他在NBA总决赛上带来好运——的时候，事态也就越发复杂了起来。', '亚当·桑德勒', '本·萨弗迪', 7.2, 33442, 'tt5727208', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2581160716.jpg', 2.2, 6.9, 33.7, 41.8, 15.4, '-0.038166,0.369469,-0.420436,0.322037,-0.288788,-0.334190,0.644429,0.210228,-0.166666,0.266542,0.184254,0.887315,0.001670,0.022059,0.040271,0.532176,-0.314894,-0.296228,0.183116,-0.241958,-0.234750,-0.305496,-0.466304,-0.130253,-0.127141,-0.029781,0.313876,0.031468,-0.170291,0.382855,0.470924,-0.003603,0.562292,0.414959,-0.209708,0.004305,0.027921,0.178931,-0.147180,0.327356,0.074165,-0.179547,-0.096855,0.441138,0.419120,0.226086,0.364326,-0.067185,0.129667,0.094362,0.131231,-0.171110,0.015099,0.082135,-0.198756,0.097276,0.074081,-0.147419,-0.432660,0.228339,0.491282,-0.175752,-0.614474,0.040457,-0.236816,0.232025,-0.669706,0.481980,-0.146026,0.247237,-0.021674,-0.365433,0.255872,-0.007560,0.081892,0.067011,-0.199924,-0.439508,-0.728790,0.525541,0.293625,-0.233417,0.089288,0.315893,-0.205287,-0.415930,-0.023225,-0.019120,-0.496362,-0.160343,0.818201,0.005175,0.067408,-0.203602,-0.862607,0.134492,-0.053098,-0.384042,0.040516,-0.283275,0.198192,-0.217402,-0.082437,-0.326447,-0.527885,0.030369,0.089626,-0.281761,0.604775,-0.108492,0.213265,0.814039,0.417785,-0.419592,0.513227,0.004497,-0.158336,-0.184835,-0.336364,-0.049757,-0.085058,0.266669,0.157368,0.277754,0.378444,-0.294862,-0.162434,0.694950', '4944008', '1304374', '6753166', '5973984');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27046450', '我的爸爸是森林之王', '喜剧', '亚当,一个十三岁的、不合群的男孩,为了发现父亲失踪背后的秘密,踏上了一段惊心动魄、令人难忘的征程。他很快发现他的父亲正是传说中的大脚怪,他多年来一直躲藏在森林里,以保护他自己和家人不被大型公司 HairCo. 纠缠。该公司渴望用他的特殊 DNA 进行科学实验。就当这对父子开始弥补失去的时光时,亚当很快发现自己也赋有超乎想象的超能力。但他们不知道的是,HairCo. 正沿着亚当留下的踪迹紧追过来......', '帕皮·福克纳', '本·斯塔森', 6.2, 5006, 'tt5715410', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2502185773.jpg', 2.1, 15.1, 57.9, 19.3, 5.6, '0.446931,0.125828,-0.940873,0.532942,-0.161388,-0.268636,0.860482,-0.459759,-0.606434,-0.347627,0.108465,0.767207,0.071505,0.157934,-0.110571,0.217077,-0.395219,-0.568588,-0.062920,-0.172524,-0.387505,-0.437720,-0.453640,-0.120270,-0.076567,-0.225475,0.762552,0.074655,-0.383413,0.435277,0.221019,0.208160,0.013447,0.697535,-0.284607,0.137990,0.127450,0.191533,-0.097068,0.132703,0.308272,-0.385754,-0.152316,0.369805,-0.291856,0.313665,0.521983,-0.223120,-0.307903,-0.169984,0.255542,-0.353862,-0.037409,-0.033304,0.374855,0.054926,0.139741,0.163476,-0.349345,-0.066412,-0.274305,-0.045260,-0.844747,0.000914,0.161022,0.151191,-0.577984,0.236081,-0.038710,-0.322135,0.375527,-0.567401,0.234540,0.486500,0.301226,0.270071,-0.282462,-0.123784,-0.623344,0.008899,0.958267,-0.268324,-0.241853,0.584055,-0.115546,-0.356931,-0.074599,-0.284740,-0.421559,-0.010452,0.174619,0.366053,-0.431427,0.201214,-0.362062,0.115352,-0.217552,-0.200155,-0.056120,-0.591844,-0.206652,-0.287355,-0.251376,-0.616977,-0.341555,0.192411,-0.199640,-0.507667,0.489802,-0.997958,0.385337,0.638976,0.321942,-0.430144,0.887589,-0.081625,-0.016356,-0.383127,-0.038051,0.279072,0.047075,0.247370,0.208386,0.148021,0.214944,-0.075075,-0.494467,0.566002', '1296370', '1308755', '2990737', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27046645', '雷米奇遇记', '剧情', '雷米（玛勒姆·帕坎 Maleaume Paquin 饰）自幼就失去了父母沦为孤儿，10岁那一年，贪婪的养父为了一点点的蝇头小利将雷米卖给了街头艺人维塔利斯（丹尼尔·奥图 Daniel Auteuil 饰），就这样，年幼的雷米开始了和维塔利斯，以及他的马戏团一起的流浪演艺生涯。幸运的是，维塔利斯是一个善良的男人，他非常同情雷米不幸的遭遇，不仅供他吃穿住宿，还教会了他念书识字。一次偶然中，维塔利斯在雷米的身上发现了极高的唱歌天赋，于是他悉心培养，想要保护并发扬雷米这份脆弱的天赋。随着年龄的增长，雷米逐渐开始对自己的过去产生了好奇心，内心里流淌的一首神秘的摇篮曲成为了牵引雷米找回过往的重要线索。©豆瓣', '丹尼尔·奥特伊', '安托万·布勒西耶', 7.4, 8846, 'tt6741368', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2573288026.jpg', 0.3, 3.6, 35.9, 45.5, 14.6, '0.524398,0.045886,-0.618411,0.742803,-0.324398,-0.526479,0.511203,0.046431,-0.372857,-0.332447,0.078751,0.991801,-0.034283,0.270469,0.131594,0.080161,-0.216692,-0.723947,0.064124,-0.308879,-0.285886,-0.404994,-0.322370,-0.138396,-0.392827,-0.470099,0.340698,-0.005295,0.005613,0.538882,0.146016,0.223387,0.500865,0.177847,-0.335059,0.236439,-0.075798,-0.121787,0.285820,0.188922,0.286940,0.018183,0.006957,0.047476,0.151793,0.399009,0.645262,-0.116017,0.062679,-0.312380,0.543749,-0.174286,0.176981,0.155789,0.196815,0.059275,0.206310,0.030764,-0.368383,-0.048249,-0.089770,-0.161952,-0.857293,-0.406268,0.107740,-0.153356,-0.657532,0.236847,0.068598,-0.204820,0.246697,-0.166254,-0.106314,0.158411,0.139312,0.396156,0.032163,-0.178897,-0.243228,0.093131,0.488250,-0.248663,-0.361252,0.473752,-0.475235,-0.346003,0.074168,-0.382593,-0.514869,-0.077549,0.449986,0.205250,-0.030135,0.464429,-0.524781,0.230546,-0.308921,-0.172219,-0.083779,-0.310371,0.097199,-0.305517,-0.373100,-0.304955,-0.143780,-0.016617,-0.037469,-0.522532,0.920103,-0.582417,0.365602,0.776275,0.240670,-0.319403,0.448857,0.012874,0.173259,-0.027736,-0.147389,0.587307,0.139276,0.009449,0.009140,0.360390,-0.034148,-0.125716,-0.290601,0.692629', '27602116', '1870681', '30162520', '25928048');
