INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27047871', '记忆之夜', '悬疑', '《记忆之夜》是一部讲述兄弟故事的惊悚片，哥哥因绑架事件失去了记忆，弟弟则一直在为哥哥找寻记忆 。', '姜河那', '张恒准', 7.5, 31424, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2500345435.jpg', 0.5, 2.6, 32.9, 48.3, 15.8, '-0.641986,-0.578970,0.048887,0.682691,0.484353,-0.492542,0.759557,-0.213740,-1.083570,-1.209352,0.023029,0.356276,0.434177,0.185898,0.350945,-0.072903,-0.665039,-0.491416,-0.228436,0.390716,-0.066289,-0.710191,0.185160,0.105455,0.298280,-1.165918,1.090724,-0.117622,-0.485243,0.382203,-0.084339,0.216535,-0.853626,-0.067949,0.275945,0.579732,-0.139778,0.462042,-0.999262,-0.065796,-0.048487,-0.648547,0.584348,-0.304105,-0.060079,-0.247997,1.280187,-0.171963,-0.199447,0.053172,0.421717,-0.298550,-0.173176,-0.587014,0.344619,0.433352,0.945454,0.534346,-0.202295,-0.819394,-0.225878,-0.425820,-0.758020,-0.189382,0.869794,0.382245,-0.364407,0.243892,-0.263814,0.689013,0.494758,-0.256661,0.662238,0.009461,0.667663,0.731151,-0.327139,-0.101662,-0.010199,0.333376,0.886052,-0.678244,0.959158,0.967582,0.231718,0.100298,-0.293131,0.128183,-0.332533,1.190459,-0.163195,-0.006122,-0.693216,1.339734,-0.079963,-0.423187,0.244693,-0.283487,0.663359,-0.711614,0.040545,0.024139,-0.492986,0.546880,0.251338,-0.304778,-0.165992,-0.307846,0.764659,-0.857903,0.738838,0.683559,-0.211994,-0.751217,0.585627,0.273150,-0.006062,-0.778972,0.778950,0.816628,0.158153,-0.417325,-0.366060,-0.581591,0.016827,0.062556,-0.870255,0.347921', '25757061', '27621192', '26850330', '30204413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27047918', '同义词', '剧情', '约亚夫（汤姆·梅西尔 Tom Mercier 饰）是一名以色列退伍军人，他非常向往法国浪漫而又开放的风气，于是只身一人来到了巴黎，结果却惨遭打劫，身上的财物被洗劫一空，就在这个紧要关头，一对艺术家情侣卡洛琳（昆汀·多尔马尔 Quentin Dolmaire 饰）和艾米勒（露易丝·谢维洛特 Louise Chevillotte 饰）向约亚夫伸出了援手，令他免于流落街头的厄运。经此一劫，约亚夫决定彻底放弃自己的国籍和身份，做一个彻头彻尾的法国人。他拒绝再说母语，通过背同义词的方式学习法语。很快，约亚夫就发现，卡洛琳和艾米勒虽然对自己表面友善，但其实是在利用他。约亚夫在战场上的悲惨经历成为了艾米勒创作的养分，而卡洛琳则试图通过约亚夫强壮的身体来满足自己无穷无尽的性欲。©豆瓣', '汤姆·梅西耶', '那达夫·拉皮德', 6.9, 9938, 'tt7016254', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2552351956.jpg', 1.9, 7.9, 44.5, 36.6, 9.2, '0.275950,0.174313,-0.621203,0.609656,-0.173940,-0.362679,0.715061,-0.045769,-0.296646,-0.179726,0.000955,0.774397,-0.160006,0.181401,0.350035,0.062869,-0.220135,-0.754533,0.152811,-0.114341,-0.403279,-0.378594,-0.196068,-0.413385,-0.235310,-0.252695,0.413737,0.154881,-0.393720,0.375140,0.396092,0.516954,0.270193,0.417880,-0.202334,-0.071923,-0.085589,-0.073721,-0.088845,0.355997,0.087269,-0.404616,-0.155068,0.296134,-0.059017,0.467709,0.790607,-0.310108,-0.059731,-0.015878,0.364734,-0.462800,0.112324,0.216968,0.180343,-0.083035,-0.080553,-0.072220,-0.147700,0.124175,0.288357,-0.215771,-0.726274,-0.115846,-0.060455,0.029069,-0.602392,0.380589,-0.091127,-0.014997,-0.047585,-0.512455,0.130778,0.384545,0.274398,0.350483,-0.098582,0.113671,-0.443995,0.007993,0.602796,0.148941,-0.310475,0.237882,-0.512104,-0.575718,0.150251,-0.143660,-0.253677,-0.298598,0.432150,-0.103811,-0.056959,0.141486,-0.621300,-0.011281,-0.343237,-0.187561,-0.176463,-0.358418,0.297219,-0.573110,-0.272863,-0.493707,-0.233294,0.018052,-0.041682,-0.220335,0.627813,-0.633234,0.218104,0.606263,0.330422,-0.376503,0.488243,0.146165,0.073056,-0.112826,-0.104367,0.562581,0.275824,0.122638,0.234594,0.353331,0.236630,-0.114377,-0.189998,0.604273', '30162520', '24733428', '25928048', '2032339');
