INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27050259', '妈妈咪呀2', '喜剧', '《妈妈咪呀2》由美国环球影业制作出品，是2008年歌舞喜剧电影《妈妈咪呀》的续篇，此次第一部的原班人马将悉数回归，而片中舞台剧的改编将会以瑞典著名乐队ABBA的歌曲为基础。续篇将围绕Sophie（阿曼达·塞弗里德 饰演）以及她的妈妈Donna（梅丽尔·斯特里普 饰演）年轻时的爱情故事展开---怀孕的Sophie一直自我质疑能否独自抚养孩子长大，直到她知道了Donna孤身一人将自己养育成人的经历，受到了极大鼓舞。年轻时的Donna将由莉莉·詹姆斯饰演，雪儿也将现身影片，饰演Sophie的外婆Ruby。', '莉莉·詹姆斯', '欧·帕克', 6.9, 26471, 'tt6911608', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2528272481.jpg', 1.2, 9.4, 45.4, 32.2, 11.7, '-0.035532,-0.157909,-0.412957,0.638549,0.152246,-0.348169,0.218866,0.168054,-0.475337,-0.164321,0.097121,0.994002,-0.197576,0.154120,0.180387,0.030158,-0.299129,-0.722996,-0.370811,0.032352,0.123576,-0.350258,-0.160555,0.208467,-0.175674,-0.545777,0.711694,-0.507729,-0.061633,0.499575,0.517931,0.247867,-0.037809,-0.168228,0.148631,0.227728,0.021250,-0.139965,-0.326165,0.433699,0.355164,-0.198838,0.066703,-0.091008,0.015143,0.144632,0.922712,-0.349871,0.232167,-0.278976,0.767140,-0.362118,0.144250,0.085386,-0.056875,0.372383,0.184030,0.472004,-0.448539,0.142990,-0.096280,-0.625100,-0.795697,-0.060679,0.447733,-0.277949,-0.664373,0.174710,-0.150232,-0.052503,0.541590,-0.174442,0.149799,0.417552,0.394727,0.597689,-0.105865,0.168305,-0.132892,0.402429,0.401819,-0.363032,-0.050600,0.417536,-0.084538,-0.324255,-0.049402,-0.535679,-0.747918,0.359182,0.038158,0.199398,-0.023354,0.191567,-0.488508,-0.185079,-0.343431,-0.414793,0.276506,-0.399144,-0.181515,-0.635080,-0.194582,-0.242064,0.229285,-0.329917,-0.035050,-0.345153,1.139889,-0.608967,0.396944,0.444213,0.316157,-0.283250,0.764235,-0.032167,0.213528,-0.119964,0.048831,0.420593,-0.182054,-0.038323,0.109776,0.136337,-0.005532,-0.188183,-0.473498,0.315610', '27602116', '3811356', '1908036', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27053945', '我们', '悬疑', '一对名为阿德莱德和盖博的夫妻带着孩子到海滨度假，这里曾经是阿莱德莱童年的娱乐场所。在海滨与泰勒一家玩了一天之后，阿德莱德愈发地无法从往昔的伤痛中走出，他越来越觉得自己的家庭将要发生灾难。到了晚上，他们一家甚至看到有四个人手拉手在行车道上站立，似乎有更多诡异的事情等待着他们。', '露皮塔·尼永奥', '乔丹·皮尔', 6.4, 78103, 'tt6857112', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2551094671.jpg', 2.5, 14, 51.8, 26.9, 4.9, '0.569434,-0.281583,-1.099349,0.577290,0.100117,-0.508450,1.245922,0.354018,-0.658774,-0.194817,0.287972,0.941601,-0.385670,0.635654,0.498508,-0.084184,-0.612138,-0.815864,-0.055151,-0.386247,-0.390666,-0.618835,-0.042991,-0.164349,-0.057858,-0.195391,0.232427,0.289340,0.204402,0.472978,-0.031342,0.095430,-0.259548,0.782181,-0.505504,0.004378,0.101956,0.327549,-0.154212,0.329729,0.457546,-0.246725,-0.405208,0.108631,0.079931,0.173531,0.795905,-0.435940,-0.150256,0.116879,-0.076203,-0.156866,-0.112316,0.149091,0.293720,-0.307239,0.233155,0.093453,-0.506177,0.110518,0.160141,-0.091121,-0.475032,0.160436,-0.079961,0.511463,-0.702000,0.597222,0.196712,-0.215935,0.412087,-0.506361,0.438609,0.517158,0.041639,0.503008,-0.098187,-0.038074,-0.994482,-0.199576,1.190045,-0.013191,-0.013064,0.361052,-0.273544,-0.356030,-0.421284,-0.021856,-0.706288,-0.048041,0.383332,0.100911,-0.132769,0.374419,-0.842430,0.312120,0.079475,-0.279949,-0.120112,-0.420943,-0.041345,-0.783195,-0.066528,-0.800654,-0.187893,0.418482,0.043378,-0.266957,0.535916,-0.941411,0.163819,0.365361,0.525977,-0.118581,0.843409,-0.104242,0.317292,-0.090783,-0.167417,0.124641,-0.163877,0.422254,0.346604,0.536467,-0.228630,0.204043,-0.327419,0.761160', '3055049', '26687241', '1308755', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27054613', '每天回家都会看到老婆在装死', '喜剧', '曾有过一次失败婚姻的上班族加贺美淳（安田显 饰）和第二任妻子千惠（荣仓奈奈 饰）已经结婚三年了，对他来说“三年之痒”近在眼前，他和妻子都必须好好考虑一下是否有必要继续维持这段婚姻。某晚下班回家，加贺美恐惧地发现千惠倒在血泊之中，但他很快发现，原来妻子在用这种方法逗他开心。原本以为只是一时兴起而为之，谁知此后每天千惠都要花样百出地死在加贺美面前。加贺美一面费尽心力配合老婆的演出，一面还要苦苦思索千惠这番作为背后的真意。为此他向职场好友佐野（大谷亮平 饰）大吐苦水，然而对方看似美满的婚姻也有着无法逾越的鸿沟。妻子的表演仍在继续，他们的婚姻将何去何从……电影取材自2010年在日本雅虎知惠袋上的提问，提问者写下的妻子奇特行为当时在网络上引起很大反响。©豆瓣', '荣仓奈奈', '李斗士男', 6.8, 10691, 'tt6939372', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2517449456.jpg', 1.3, 9.1, 48.2, 31.4, 10.1, '-0.021489,0.071088,-0.748278,0.523334,0.056456,-0.362139,0.567406,-0.132290,-0.484154,-0.388777,0.171178,0.473599,-0.387881,0.357757,0.191689,0.073952,-0.138867,-0.675897,-0.002239,-0.002466,-0.149160,-0.488103,-0.085717,0.005765,-0.302639,-0.256957,0.716985,0.048312,0.063103,0.335240,0.245262,0.178412,0.040933,0.466037,0.094730,-0.010896,-0.169983,0.264266,-0.506587,0.027584,0.172722,-0.364165,-0.206664,0.246760,-0.029548,0.274102,0.541060,-0.138341,-0.369191,0.155295,0.466580,-0.215476,-0.036878,0.272275,0.279126,-0.044487,0.219361,0.197711,-0.243451,-0.134518,0.054071,-0.023521,-0.524961,-0.090475,0.020698,0.010674,-0.453495,0.546651,-0.139116,-0.091819,0.196442,-0.371342,-0.024780,0.484412,0.490402,0.345209,-0.400444,0.272100,-0.413073,0.237715,0.734288,0.363936,-0.047536,0.465084,-0.130169,-0.288051,-0.197218,-0.395087,-0.405443,-0.016335,-0.090315,0.074122,-0.335660,0.090317,-0.276460,0.107057,-0.184084,-0.034755,0.210865,-0.475239,0.017102,-0.461315,-0.071884,-0.534552,-0.464088,0.108487,0.074939,-0.580130,0.628859,-0.781113,0.223003,0.488180,0.411570,-0.355281,0.731523,0.589989,-0.082448,-0.130899,-0.119414,0.235702,-0.025493,0.044143,0.083069,0.011911,0.229092,-0.018643,-0.516417,0.343491', '26354526', '26280710', '1870682', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27055378', '白小姐', '剧情', '由真实故事所改编，讲述有杀人未遂前科的白向雅（韩志旼 饰演），小时候遭母亲虐待、遗弃，长大后的她，不相信任何人、对凡事漠不关心，过着孤独疏离的生活。某个冬天，她遇到一个小女孩智恩（金诗雅 饰演），穿着破旧衣服、颤抖著瘦小的身体，无助地站在街头，她不禁想起当年幼小的自己。当她发现小女孩饱受父亲和继母虐待时，让她无法对这个与自己相像的孩子坐视不管，决心要帮助她逃出残酷的现实，即使要与世界对抗也在所不惜。', '韩智敏', '李智媛', 7.4, 10365, 'tt6479534', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2534235010.jpg', 0.5, 3.1, 36.5, 44.2, 15.7, '0.061257,-0.012894,-0.854227,0.401609,-0.366741,0.116809,1.058409,0.096341,-0.671121,-0.393144,0.432361,0.994700,0.097511,0.587950,-0.089867,0.112651,-0.190931,-0.587119,-0.198344,0.175248,-0.341622,-0.320181,-0.098422,-0.200484,-0.236958,-0.445900,0.585170,-0.049800,-0.458447,0.231901,0.297232,0.355825,-0.114267,0.345931,-0.332403,-0.097342,-0.318806,0.343567,-0.151159,-0.112713,0.132757,0.069716,-0.128539,0.275429,-0.313932,0.252755,0.729727,-0.337194,-0.492959,-0.165585,0.560317,-0.352006,-0.108686,0.340114,-0.098913,-0.086797,0.173609,0.201751,-0.073273,-0.007363,-0.101235,-0.056983,-0.679863,-0.167691,0.366126,0.112562,-0.772646,0.309905,-0.138928,-0.016923,0.261752,-0.288704,0.056225,0.258488,0.362957,0.727505,-0.219190,-0.004743,-0.406424,0.264186,0.892678,0.081331,-0.222057,0.499694,-0.525992,-0.036117,-0.022818,-0.468325,-0.953481,0.308960,-0.048373,-0.224258,-0.610280,0.492870,-0.188049,-0.115664,-0.186746,0.139633,0.018189,-0.408763,-0.293677,0.101330,-0.349244,-0.687747,-0.398093,0.058682,-0.165443,-0.564721,0.540788,-0.842306,0.421978,0.541369,0.520856,-0.573030,0.519173,0.410043,-0.001963,-0.176770,0.113593,0.931387,-0.063375,-0.170116,-0.071829,0.082373,-0.025811,0.242238,-0.527652,0.431527', '3001149', '2075721', '4275444', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27056299', '那一场呼啸而过的青春', '剧情', '1997年的东北，旧工业正面临告别的时代，18岁的技校女孩杨北冰（卜冠今 饰）意气风发，仗义行事，常带着一帮姐妹四处干架，在一次闯入男澡堂作战后，杨北冰撞见了正在洗澡的发小于一（刘畅 饰），对他心动不已，悄悄展开暗示和追求。没想到于一却爱上了南方女孩紫薇（李梦 饰），杨北冰斗气不成，却也被紫薇成熟独特的气质吸引。然而危险却在悄然萌芽，杨北冰和于一在迪厅打工，意外目睹了老板雷管的杀人现场。杨北冰在恐惧中，又发现发现紫薇和雷管（黄觉 饰）发生了亲密关系……年轻的欲望夹杂着危险，将杨北冰和于一推向成人世界的残酷，遍体鳞伤后，紫薇意外身亡，杨北冰离开东北。多年后杨北冰和于一重逢，回望那场呼啸而过的青春，两人渐渐放下伤痛……', '卜冠今', '韩天', 6, 7820, 'tt10443764', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2499365735.jpg', 4.8, 21.3, 48.7, 19.3, 5.8, '0.277839,0.167605,-1.074581,0.245265,-0.126151,-0.375261,0.979937,-0.076250,-0.454536,0.089982,0.090611,0.917221,-0.463917,0.205934,0.471869,-0.220918,-0.025521,-0.749977,-0.289120,-0.051600,-0.229568,-0.457525,-0.433850,-0.028139,-0.105502,-0.666206,0.331570,-0.011016,-0.222255,0.930490,0.355380,0.045587,-0.364889,0.720270,-0.082435,-0.116544,0.135556,0.313751,-0.463619,0.183897,0.030344,-0.542466,-0.302127,0.025905,-0.282648,0.310979,0.763188,-0.236736,-0.119927,-0.099104,0.341289,0.063098,-0.371635,0.105821,0.340639,0.032101,-0.021726,0.060294,-0.293726,0.018511,0.176503,-0.062450,-0.407466,0.039538,0.123078,0.263218,-0.514002,0.449127,0.119019,-0.030527,0.200262,-0.515394,0.182844,0.080349,0.393613,0.667681,-0.249334,0.082791,-0.223932,0.125181,0.758830,-0.017315,-0.206835,0.442349,-0.128576,0.029396,-0.019028,-0.066607,-0.501338,-0.198323,0.528402,0.031298,-0.222303,0.066968,-0.661645,-0.015925,-0.020650,-0.209235,0.000105,-0.074073,-0.379296,-0.311252,-0.219436,-0.634317,-0.508041,0.370746,0.250464,-0.040455,0.656864,-0.909705,0.367736,0.457035,0.352213,-0.486897,0.584267,0.129768,0.061447,0.020360,-0.129319,0.211360,-0.186929,0.343796,0.152471,0.638287,-0.501842,-0.179541,-0.451566,0.226957', '3111650', '1296534', '1300958', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27056396', '宝贝老板2', '喜剧', '设定在首部多年之后，邓普顿兄弟蒂姆和泰德长大成人，两人关系也逐渐疏远。蒂姆已婚已育，泰德是对冲基金的首席执行官，两人将因为一个有着先进方式和积极进取态度的新任“宝贝老板”重新联系在一起，激发出新的家族企业。蒂姆和有“超级妈妈”之称的妻子卡罗尔及异常聪慧的7岁女儿塔比莎、刚出生超级可爱的婴儿蒂娜住在郊区，塔比莎是一所有威望的教育机构的尖子生，将叔叔泰德视为偶像，想成为他那样的人，但蒂姆担心她太过用功，导致无法过一个正常的童年。当蒂娜作为宝贝集团最高机密特工的真实身份曝光，目的是为了揭开塔比莎学校及其神秘创始人阿姆斯特朗博士背后的黑暗秘密时，邓普顿兄弟将以一种意想不到的方式重聚，两人重新审视家庭的意义，明白什么才是最重要的。', '亚历克·鲍德温', '汤姆·麦格拉思', 6.8, 10485, 'tt6932874', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2651996671.jpg', 1.5, 8.8, 48.4, 28.8, 12.4, '0.295077,-0.107663,-0.600734,0.654594,-0.363788,-0.112819,0.519238,0.204278,-0.776849,-0.546419,0.089157,0.980040,0.040099,0.411776,0.238205,0.101993,-0.041453,-0.649542,-0.184185,-0.338051,-0.134106,-0.692367,-0.304296,-0.068887,-0.010054,-0.604065,0.596969,-0.289195,-0.260611,0.137389,0.380800,0.310947,-0.097256,0.150294,-0.121308,-0.314670,0.313862,0.049532,-0.603525,0.175337,0.032340,0.127295,0.049930,0.135720,0.001102,0.090797,0.458470,-0.288247,-0.213354,-0.059082,0.431008,-0.149866,-0.129477,0.006538,0.510978,-0.009293,0.269536,0.309068,-0.105107,-0.102541,0.010268,-0.173674,-1.149636,-0.101146,0.347071,0.040833,-0.610668,0.250496,-0.139247,-0.310225,0.155367,-0.449039,0.265360,0.388581,0.235164,0.457950,-0.147593,0.272571,-0.222819,-0.038352,0.647663,-0.073892,-0.277716,0.222228,-0.375845,-0.275127,0.026685,-0.483503,-0.477674,-0.004632,0.266640,0.139051,0.025788,0.392716,-0.443866,-0.107088,-0.333533,-0.122070,0.251921,-0.537531,0.137444,-0.251403,-0.128793,-0.486353,-0.183989,-0.093053,0.015521,-0.357017,0.958666,-0.985725,0.157728,0.434428,0.311683,-0.524407,0.617562,0.046873,0.143434,-0.580412,-0.128149,0.132311,0.160179,-0.083974,-0.077865,0.244700,0.050903,-0.220091,-0.200804,0.343842', '1793491', '24284209', '26678784', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27059080', '幼儿园教师', '剧情', '幼儿园教师丽莎参加了诗社，却苦于无法写出好诗。当她发现班级里的少年吉米拥有超群的诗歌创作灵感，她希望用尽全力保护吉米的天赋。', '玛吉·吉伦哈尔', '萨拉·科朗吉洛', 7.5, 6829, 'tt6952960', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2530579813.jpg', 0.5, 3, 30.1, 52.4, 14, '0.314986,0.225295,-0.472164,0.687401,-0.252992,-0.321770,0.388099,-0.216586,-0.536781,-0.510518,0.056542,0.470612,0.096130,0.617544,-0.024335,-0.287490,-0.053844,-0.757195,0.536587,0.019168,-0.158429,-0.480490,-0.437627,0.293226,-0.294583,-0.559800,0.432110,-0.273670,-0.260158,0.586457,-0.285882,0.143506,0.340279,0.115350,0.298765,-0.401901,0.039189,-0.103106,0.070721,0.359239,0.370614,0.030557,-0.488328,0.157496,-0.109045,0.190801,0.704058,0.167501,0.289767,-0.116318,0.380719,0.035275,-0.043311,-0.005371,-0.090728,0.132549,0.225845,-0.006934,0.177192,-0.169772,-0.122114,-0.141631,-0.901245,-0.046479,0.518582,0.159785,-0.555364,0.198895,-0.283068,0.135199,0.084827,-0.404780,-0.486953,-0.290612,0.206832,0.494816,-0.369394,0.311685,-0.381381,0.224265,0.329271,-0.331741,-0.501764,0.320490,-0.400338,-0.412549,0.453110,-0.391215,-0.370878,0.288542,-0.052764,0.285673,-0.197839,-0.732011,-0.314769,-0.193601,-0.370581,0.141425,0.000173,-0.523950,-0.002534,-0.579721,0.105266,0.309449,-0.338837,-0.197139,0.025026,-0.567912,1.377564,-0.975447,-0.008721,0.799633,0.365482,-0.153231,0.912025,-0.082161,0.100672,0.128755,-0.416078,0.113736,-0.336864,0.263324,-0.013704,0.354874,0.243852,-0.417789,-0.737217,0.852918', '24284209', '27602116', '25922902', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27059130', '大佛普拉斯', '剧情', '菜埔（庄益增 饰）是一家雕塑厂的夜间保安，家中有一位重病的老母亲需要照顾。肚财（陈竹昇 饰）是菜埔唯一的朋友，菜埔经常在值夜班的时候把肚财叫过来和他作伴。一天，两人突发奇想决定看一看菜埔的老板黄启文（戴立忍 饰）的行车记录仪里记录了哪些影像，希望向来风流的老板能够贡献出一些精彩的片段以解两个独身男人内心里的寂寞之苦。行车记录仪所记录的影像果然没有让菜埔和肚财失望，但与此同时，两人也发现了黄启文的许多不可告人的秘密。实际上，菜埔和肚财的一举一动皆没有逃过黄启文的眼睛，为了保住自己的地位和名声，他决定采取一些必要的行动。©豆瓣', '庄益增', '黄信尧', 8.7, 413275, 'tt7010412', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2505928032.jpg', 0.3, 0.8, 8.9, 41.8, 48.2, '0.267657,-0.003329,-0.592431,0.596622,-0.081067,-0.137307,0.674369,0.104308,-0.584330,-0.496999,0.080636,0.617830,0.003958,0.288910,0.075060,-0.243798,-0.195860,-0.398049,-0.089202,-0.362443,-0.280955,-0.512780,-0.536039,-0.192691,-0.167047,-0.237806,0.505657,0.248649,-0.038967,0.334644,0.165010,-0.049535,-0.065747,0.210406,-0.350797,-0.286602,-0.120548,-0.041910,-0.197978,0.058097,0.058686,-0.137788,-0.168311,0.209204,0.170284,0.487341,0.611283,-0.193349,-0.532365,0.235961,0.220272,-0.001505,0.123314,0.031423,0.022436,0.031102,0.350229,0.216595,-0.397451,-0.007450,0.042095,0.271687,-0.997130,-0.175336,0.385210,0.229788,-0.671411,0.349562,-0.232303,-0.304898,-0.012897,-0.275350,0.415452,0.265833,0.247486,0.385564,-0.164257,0.046072,-0.466615,-0.016927,0.620384,-0.136079,0.080002,0.448957,-0.228662,-0.170779,-0.049284,-0.137689,-0.367629,0.112804,0.164708,-0.005920,-0.172065,-0.000719,-0.501517,0.067330,-0.197273,-0.130401,-0.100091,-0.378825,0.044617,-0.535993,0.008285,-0.375119,-0.258868,0.224788,0.243904,-0.276858,0.828010,-0.769325,0.059716,0.379014,0.102644,-0.638736,0.791037,0.264074,0.137025,-0.257744,0.006395,-0.304683,0.241521,0.152556,-0.158371,0.301510,0.069202,-0.429637,-0.317830,0.133239', '1793491', '26678784', '30163500', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27060077', '绿皮书', '剧情', '托尼（维果·莫腾森 Viggo Mortensen 饰）是一个吊儿郎当游手好闲的混混，在一家夜总会做侍者。这间夜总会因故要停业几个月，可托尼所要支付的房租和生活费不会因此取消，所以他的当务之急是去寻找另一份工作来填补这几个月的空缺。在这个节骨眼上，一位名叫唐雪莉（马赫沙拉·阿里 Mahershala Ali 饰）的黑人钢琴家提出雇佣托尼。唐雪莉即将开始为期八个星期的南下巡回演出，可是，那个时候南方对黑人的歧视非常的严重，于是托尼便成为了唐雪莉的司机兼保镖。一路上，两人迥异的性格使得他们之间产生了很多的矛盾，与此同时，唐雪莉在南方所遭受的种种不公平的对待也让托尼对种族歧视感到深恶痛绝。©豆瓣', '维果·莫腾森', '彼得·法雷里', 8.9, 1516170, 'tt6966692', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2549177902.jpg', 0.1, 0.4, 7.1, 37.5, 54.8, '0.413933,-0.083096,-0.574070,0.424624,-0.420949,-0.107603,0.753442,0.302209,-0.584578,-0.264478,0.184165,0.856283,-0.103879,0.175447,0.381499,-0.062058,-0.071693,-0.514578,-0.263816,-0.411524,-0.338602,-0.503213,0.040005,-0.296483,-0.237183,-0.071568,0.335392,-0.045898,-0.080450,0.482080,0.409925,0.363892,0.176284,0.470456,-0.097822,-0.117730,0.193777,-0.189030,-0.034347,0.236415,0.028078,-0.146667,-0.078883,0.117476,0.079811,0.607888,0.621947,0.042130,-0.388563,-0.112463,0.598248,-0.196239,-0.225267,-0.124902,0.359134,0.050806,0.127428,0.178523,-0.492451,0.034419,-0.008629,-0.208716,-0.826559,0.181083,0.027693,0.112731,-0.856970,0.591382,0.036670,-0.201730,0.054664,-0.283671,0.147068,0.689334,0.164253,0.411945,0.007914,0.049483,-0.587272,0.038650,1.004101,0.104289,-0.241519,0.143628,-0.233227,-0.276946,-0.026219,-0.204444,-0.309791,-0.128122,0.016914,-0.069972,-0.078242,-0.136589,-0.646314,0.121871,-0.100679,-0.351640,0.125872,-0.354494,-0.278789,-0.834552,0.068552,-0.480039,-0.217773,0.141638,0.307288,-0.020531,0.781719,-0.938116,0.119726,0.588906,0.445706,-0.623442,0.790090,0.249440,0.127571,-0.212984,-0.197017,-0.139719,0.190484,0.170761,-0.067026,0.323267,0.114251,-0.191303,-0.052718,0.377338', '25721544', '2990737', '3285642', '1299062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27061510', '娼年', '爱情', '该片改编自同名小说，讲述 森中领（松坂桃李 饰）是个平凡的20岁男大生，每天过着平凡无趣的生活。某天，他认识了经营会员制BOYS CLUB的老板——御堂静香（真飞圣 饰），在她的诱惑下 ，森中领 决定以「娼夫（男妓）」的身份在她的店里工作。随着和各式各样的女性 接触 ，森中领 温柔地释放了 她们内心所蕴藏的欲望，疗愈她们受伤的心，自己也渐渐有所成长。', '松坂桃李', '三浦大辅', 6, 20652, 'tt7529650', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2515826373.jpg', 5.4, 23.7, 44.8, 18.1, 7.9, '0.188956,-0.047404,-0.578603,0.424785,-0.110742,-0.060215,0.699851,0.264997,-0.379814,-0.290209,0.232845,0.641516,-0.266793,0.382184,0.208808,0.135370,-0.216790,-0.392209,-0.226104,-0.031254,0.115991,-0.042581,-0.132100,-0.032564,-0.229027,-0.254948,0.607458,-0.035467,-0.168243,0.411150,0.261835,0.324064,0.190016,0.183521,-0.358510,0.062757,-0.232899,-0.050299,-0.045265,0.129240,-0.029236,-0.203478,-0.106314,0.059538,0.040309,0.299214,0.778300,-0.167781,-0.335354,0.007656,0.597158,0.030833,-0.126760,0.187904,0.144648,0.144431,0.113802,0.130651,-0.396853,0.129125,-0.109491,0.042577,-0.842879,-0.214937,0.234092,0.085108,-0.536073,0.312657,0.157494,-0.057729,0.037795,-0.433461,-0.117939,0.015828,0.029840,0.280234,-0.069160,0.093117,-0.299361,0.381337,0.730389,0.304289,-0.348813,0.466590,-0.580704,-0.352280,-0.342816,-0.091371,-0.679885,-0.300328,0.114532,0.283129,-0.056859,0.135850,-0.517423,0.082398,0.098386,-0.222748,0.190900,-0.373987,-0.156758,-0.407137,-0.470992,-0.740840,-0.474319,-0.230927,0.222608,-0.338863,0.895281,-1.054158,0.084213,0.836532,0.340799,-0.437670,0.563764,0.084898,-0.162744,-0.074610,-0.323144,0.390399,-0.190315,0.347098,-0.062529,0.639849,-0.019954,0.193151,-0.417659,0.493348', '24284209', '1309161', '35030151', '4817024');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27062637', '利兹与青鸟', '剧情', '故事发生在北宇治高中的管乐团中。铠塚霙（种崎敦美 配音）和伞木希美（东山奈央 配音）分别负责双簧管和长笛的演奏。铠塚霙从小就性格内向胆小害羞，在国中时一直过着非常孤独的生活，希美的出现和靠近让铠塚霙第一次感受到了友情带来的温暖，因此将希美视为自己最珍贵的宝物，没想到眷恋和依赖带来的却是患得患失的不安全感。在高中最后一次音乐比赛中，铠塚霙和希美决定选择《莉兹与青鸟》为参赛曲目。这首出自悲伤童话的歌让铠塚霙不可避免的将自己和希美之间的关系带入其中。随着比赛日期的日渐接近，铠塚霙和希美之间的间隙却越来越大。©豆瓣', '种崎敦美', '山田尚子', 8.8, 30827, 'tt7089878', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2515806508.jpg', 0.4, 1.6, 11.6, 30.7, 55.6, '0.222545,0.015488,-0.831110,0.974313,0.125535,-0.030893,0.978126,0.041261,-0.395186,-0.362461,-0.144810,0.937397,-0.381945,0.332223,0.325525,-0.223561,-0.023548,-1.055285,-0.213224,-0.033167,-0.373832,-0.570838,0.003415,0.136367,-0.188708,-0.396945,0.866849,0.048878,-0.503178,0.808916,0.309328,0.240409,-0.389138,0.494397,-0.147153,-0.268594,0.000378,0.411721,-0.222314,0.055630,0.099500,-0.195599,-0.206186,0.233633,0.228778,0.117239,1.066553,-0.361122,-0.171681,0.128410,0.288945,-0.139781,-0.233939,-0.201268,0.150416,0.318279,0.264039,0.327163,-0.469817,0.265880,-0.228101,-0.157588,-0.896363,0.272741,0.140458,0.226236,-0.442979,0.661837,0.118870,-0.193040,0.508307,-0.409146,0.503764,0.247184,0.273830,0.532614,-0.495486,0.134081,-0.210601,-0.006961,0.981570,-0.033860,-0.131805,0.502955,-0.291055,-0.281258,-0.090017,-0.202420,-0.448508,0.093790,-0.083466,0.390700,0.054401,0.353583,-0.764698,-0.029714,0.330872,-0.299317,0.308979,-0.784708,0.047126,-0.414708,-0.213749,-0.593885,-0.358965,0.215952,0.058051,-0.527822,1.001399,-0.994534,0.321175,0.459418,0.336658,-0.191027,0.652463,0.446214,0.074883,-0.002749,-0.254876,0.365170,-0.170711,0.059895,0.181133,0.319258,-0.125899,-0.169988,-0.579376,0.646132', '26809007', '3811356', '1292219', '35030151');
