INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27063335', '捍卫者', '剧情', '一九三七年八月三十一日淞沪会战中，姚子青奉命率部五百余人守卫宝山县城。日军为扩大登陆地域，对宝山进行了海陆空协同的疯狂攻击。在装备落后，地势不利，没有援军的情况下，智勇双全的姚子青带领全营以寡敌众坚守孤城，灵活运用战术战略，从主动出击攻袭敌军到固守阵地顽强抵御，七日内击退了日军一次又一次的进攻，全营五百余人先后战死沙场。九月七日日军破城，姚子青率残部二十余人在城内展开激烈巷战，最终壮烈殉国。', '白恩', '廖希', 7.4, 18966, 'tt7176170', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2515803508.jpg', 1.6, 6.8, 31.7, 41.8, 18.1, '-0.314688,0.114794,-1.050850,0.569948,0.368933,0.311847,0.171887,-0.124880,-0.445047,0.314267,0.813652,-0.005808,0.401028,-0.831397,-0.174713,-0.413665,-0.265037,-0.683329,0.067083,-0.123560,-0.399699,-0.119687,-0.157877,-0.185205,0.309025,-0.290369,0.591183,0.638739,-0.109895,0.336962,-0.189051,0.093603,0.210275,0.774648,0.418411,0.082238,-0.150094,-0.722875,-0.439317,0.548428,-0.783471,-0.448559,-0.755525,-0.175815,0.131699,0.720882,1.221327,-0.323726,-0.242668,0.007842,-0.270337,-0.394324,-0.170133,0.293725,0.728939,0.029936,-0.000207,-0.100703,-0.128177,0.008449,-0.759787,0.138791,-0.209920,-0.102934,0.103976,-0.309252,-0.326426,0.724054,-0.370547,0.489323,0.231631,-0.548223,-0.555166,0.868885,0.112170,-0.096910,-0.227926,-0.105185,-0.262534,-0.030102,0.731122,-0.122503,-0.220379,-0.559657,0.296018,-0.314476,0.197083,-0.434314,-0.063773,-0.139826,0.196894,-0.225500,0.174664,0.084982,-0.570172,0.496388,-0.594344,-0.306663,-0.035429,0.147953,-0.099625,-0.907809,0.225686,-0.109589,-0.401711,0.624653,0.183015,0.566687,0.500449,-0.457652,-0.163592,0.424127,0.598697,-0.177928,0.077255,0.348361,-0.190528,0.197417,0.447131,0.144842,-0.275869,0.809474,0.467132,0.394530,-0.504680,0.134243,-0.441234,0.340895', '1434172', '1464618', '30454698', '1464540');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27063867', '逗爱熊仁镇', '喜剧', '电影讲述了同在一间银行ATM部门中工作的何必（朱亚文饰）与蒙小鲜（张榕容饰），由于公司禁止办公室恋情，正秘密的谈着地下恋爱。与此同时300公里以外的熊仁镇一个ATM机出现故障，取一倍的钱吐两倍的现金，造成银行财产损失。于是蒙小鲜和何必约定，谁先找到被多取得钱谁就可以留在银行，另一个必须辞职。于是一场争钱斗爱的游戏在小镇迅速展开。', '朱亚文', '查慕春', 4.5, 5314, 'tt10757456', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2566979232.jpg', 25.4, 33.8, 31.2, 8.7, 0.9, '0.246685,0.234373,-0.402557,0.543623,-0.172854,-0.266788,0.612660,0.407610,0.208289,-0.227239,-0.051324,0.587243,0.182731,0.112097,-0.042850,-0.341295,-0.301737,-0.493295,-0.127792,-0.367699,-0.372038,-0.598894,0.192381,-0.131122,-0.050260,-0.038656,0.350107,-0.004256,-0.267087,0.018863,0.282824,0.021527,-0.711883,0.292405,0.037856,-0.240264,0.238004,0.410590,-0.511271,0.424462,0.024868,-0.108248,-0.097587,-0.073416,0.467302,0.330105,0.590458,0.301613,-0.360652,-0.026734,0.500210,-0.002515,-0.139288,-0.298686,0.246389,0.210664,0.396188,0.262897,-0.656190,0.481833,0.300945,-0.241106,-0.785032,-0.285567,-0.096353,-0.005583,-0.611387,0.296044,-0.201805,-0.062092,0.053122,-0.105903,-0.042009,0.686366,0.324346,0.063399,-0.285218,0.019745,-0.976542,0.079189,0.524529,-0.146653,0.116542,0.383867,0.484829,-0.364547,-0.267018,0.237788,-0.173340,-0.085477,0.339291,-0.289233,-0.168858,-0.074433,-0.781151,-0.064260,-0.170228,-0.576022,0.322207,-0.443601,-0.174412,-0.592517,0.006639,0.100373,-0.127097,0.404741,0.422179,-0.085264,0.394391,-0.382404,-0.143375,0.576896,0.575543,-0.669446,0.545129,0.020109,0.245639,-0.234166,0.281600,-0.407777,0.320031,0.653865,0.156477,-0.008088,-0.063163,-0.158188,-0.368702,0.470910', '30387441', '4300640', '1299932', '26703844');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27064658', '致所有我曾爱过的男孩', '爱情', '劳拉（拉娜·孔多尔 Lana Condor 饰）是一个16岁的女孩，无论是外貌还是性格，劳拉都只能算是最普通的那一挂，把她扔在人堆里，下一秒钟你就绝对再也无法注意到她。然而，劳拉的心思细腻情感丰富，让她特别容易对男孩产生好感，但她总是将这份爱慕隐藏在心底，只是通过写信的方式来抒情，一段时间下来，劳拉积攒了不少的情书，她将这些情书藏了起来，并决定将它们当做自己永远的秘密。可让劳拉没有想到的是，自己的这些私房信竟然在某一天被统统公之于众。信件带来的巨大反响很快就令她的生活发生了天翻地覆的改变，面对各方的声音，无论是嘲讽和还是善意的，勇敢的劳拉都以一颗平常心面对。©豆瓣', '拉娜·康多', '苏珊·约翰逊', 7.4, 44547, 'tt3846674', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2529112058.jpg', 0.7, 4.1, 35.5, 43.2, 16.6, '0.399630,0.222714,-0.697766,0.758335,-0.592684,0.096124,0.849755,-0.098688,-0.508242,-0.004270,0.050177,0.727471,-0.184614,0.154640,-0.118469,-0.080362,-0.141410,-0.645529,0.010368,-0.202373,-0.219222,-0.460762,-0.360818,-0.097325,-0.213979,-0.163292,0.412596,0.011784,-0.304132,0.173735,0.370240,0.218546,0.253404,0.775057,-0.215225,0.005431,-0.341071,-0.123873,0.115242,0.087659,0.170022,-0.474627,-0.101313,0.633808,0.099561,0.273082,0.688184,-0.230094,-0.446234,0.374588,0.389111,-0.142851,-0.008299,0.250832,0.059921,-0.040053,0.023866,0.234047,-0.388850,0.119933,0.414358,0.150005,-0.897423,-0.010766,0.000058,0.174224,-0.696843,0.316183,-0.039852,-0.035204,-0.017365,-0.486598,0.193499,0.136535,0.094371,0.240261,-0.406942,-0.088995,-0.489753,0.112382,0.648804,-0.010579,-0.445787,0.319097,-0.396823,-0.424363,-0.096355,-0.200832,-0.393030,0.060985,0.290795,0.297872,-0.395536,0.188754,-0.566965,0.053741,-0.077533,-0.435509,0.095071,-0.863310,0.031305,-0.388366,-0.372688,-0.610037,-0.672040,-0.026303,0.238287,-0.321780,1.097094,-0.642600,0.236466,0.629211,0.088302,-0.524231,0.423444,0.141490,-0.069530,0.208052,-0.064790,0.365348,0.108780,0.214858,0.096607,0.468974,0.128581,-0.190496,-0.281553,0.767892', '30163500', '25932086', '3318473', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27065129', '眩：北斋之女', '剧情', '本剧原作为描述葛饰北斋的三女「荣」的半生的小说『眩』。描述回到北斋身边的「荣」，看着父亲的背影而开始研究色彩以及暗恋北斋弟子-画家「善次郎」的姿态。', '宫崎葵', '加藤拓', 8.6, 12878, 'tt7168760', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2500149919.jpg', 0.2, 0.7, 11.7, 44, 43.4, '0.077060,-0.307035,-0.025567,1.094698,0.197756,-0.501783,0.393384,0.156877,-0.195703,-0.818788,0.041156,1.182149,-0.014697,0.952024,0.567936,0.083519,0.018652,-0.935116,-0.851886,-0.324911,0.227682,-0.917973,0.283616,-0.277843,-0.022350,-0.146279,0.861533,0.297852,-0.132583,0.346687,0.363460,0.374221,-0.386838,-0.293250,-0.011545,0.033496,-0.166031,0.130322,-0.156216,-0.142622,0.213321,-0.500011,-0.082395,0.269669,-0.069251,-0.074275,0.997900,-0.544915,-0.059242,-0.114913,0.660865,-0.049574,0.021605,-0.098041,0.198010,-0.007830,0.550382,0.038259,-0.023737,-0.162371,-0.255959,-0.018801,-0.783872,-0.222088,0.457112,0.414225,-0.436497,0.197028,0.258883,0.244683,0.126824,-0.233026,0.321099,-0.070331,0.299393,0.485204,-0.333673,0.133635,0.172782,0.194177,0.163936,0.038681,0.142678,0.594182,-0.299258,-0.208604,-0.160786,-0.427573,-0.517640,0.014706,-0.044153,0.154765,0.333015,-0.204280,-0.459151,-0.299653,0.036344,0.169900,0.432986,-0.099149,-0.242058,-1.029789,-0.153713,-0.909914,-0.258823,-0.184440,-0.000841,-0.684939,0.914288,-0.730533,-0.116230,-0.009701,-0.136815,-0.556238,0.643963,-0.244678,-0.284327,-0.170261,0.025267,0.649194,-0.012271,0.233153,-0.485188,0.320349,-0.201173,-0.159499,-0.504744,0.477852', '30434174', '25880986', '3811356', '4109746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27065898', '神探蒲松龄', '喜剧', '隐居深山老林的蒲松龄（成龙 饰）不仅是一名文采飞扬的文学家，更是一个身怀绝技的捉妖高手。在某次珠宝盗窃案中，蒲松龄和金华县菜鸟捕快严飞（林柏宏 饰）结识。在此之后，被衙门提出来的严飞找上山来，死乞白赖要拜蒲松龄为师。适值此时，金华县初县令（潘长江 饰）的独女被女妖聂小倩（钟楚曦 饰）摄走，中途虽有法师宁采臣（阮经天 饰）阻拦，但是小姐却下落不明。得知此讯，蒲松龄带着严飞和一众早已收伏的小妖下山捉妖，结果遭遇小倩的姐姐镜妖（林鹏 饰）阻挠。一番混战过后，虽然镜妖被除，但是宁采臣和聂小倩之间仍有一段宿缘未了……©豆瓣', '成龙', '严嘉', 3.8, 67544, 'tt7587984', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2545389067.jpg', 36.5, 42.2, 18.1, 2.3, 0.9, '0.312175,-0.012227,-0.267753,0.447049,0.172765,-0.206471,0.542571,-0.039143,-0.504204,-0.475479,0.271469,0.504402,-0.291608,0.055652,0.088849,-0.045994,0.115752,-0.329370,0.053062,-0.105658,0.035388,-0.192062,-0.130860,0.295235,-0.360168,-0.190921,0.456179,-0.049868,-0.065875,0.598593,0.374244,0.210471,-0.521648,0.423436,-0.185230,0.145982,0.102277,0.212432,-0.152682,0.328879,-0.099259,-0.218081,-0.238569,-0.250902,-0.201560,0.364404,0.587409,-0.193849,-0.068355,0.007195,0.109428,-0.090484,0.001693,0.098548,0.515554,0.065420,0.244226,0.337526,0.095182,0.111090,0.095832,0.022410,-0.297755,0.347568,0.678469,0.048229,-0.444571,0.168154,0.065971,0.091079,-0.163544,-0.339637,0.090628,0.120606,0.074634,0.198658,-0.008997,0.017893,-0.615325,0.437762,0.391378,-0.010695,0.408580,0.019886,0.245699,-0.562519,0.172075,-0.154656,-0.262704,0.258868,0.185824,-0.270598,-0.282378,0.063043,-0.579086,-0.121093,-0.405364,0.345478,-0.189535,-0.055169,-0.127031,-0.495506,0.058376,-0.322671,-0.219524,-0.143585,0.411162,-0.129645,0.545568,-0.745255,0.033317,0.158910,0.059537,-0.273548,0.553867,0.093003,0.100492,-0.048421,-0.269731,-0.102191,0.071689,0.359555,0.152714,0.358345,0.024272,-0.300868,-0.155865,-0.096774', '3445516', '35030151', '1294009', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27066172', '8号警报', '剧情', '曾经的“未来之城”林肯城，4%人口具有超能力，其中大多数却在自动化潮流中陷入贫困与歧视的泥沼，日渐成为社会负担甚至隐患，康纳·里德（罗比·艾梅尔 饰）便是这样一名青年临时工——面对母亲的天价医疗费，债台高筑的他不得不铤而走险，直面铁面无情的机械军警卫士。影片由杰夫·陈（Jeff Chan）创作执导、克里斯·帕雷（Chris Paré）撰写剧本，改编自两人2016年同名科幻短片，并与主演艾梅尔兄弟等人执行制片。', '斯蒂芬·阿梅尔', '杰夫·陈', 5.8, 6095, 'tt6259380', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2572545203.jpg', 3.3, 24.9, 55.4, 12, 4.4, '-0.090373,0.068094,-0.359266,0.531557,0.208789,-0.214440,0.787404,0.146677,-0.548584,-0.630233,0.358305,0.830759,0.114569,0.024850,0.351982,-0.537314,-0.367431,-0.540914,-0.306468,0.013086,-0.187485,-0.175589,-0.230230,-0.300290,-0.545555,-0.276922,0.982424,0.311322,-0.392143,0.182123,0.168464,0.447252,-0.198817,0.207219,0.197527,0.036503,0.267030,-0.261029,-0.698387,0.023355,-0.163103,-0.027971,-0.239447,-0.106374,0.019151,0.157342,0.615581,-0.367461,-0.079267,-0.260696,0.280970,-0.302861,-0.072621,-0.121225,0.054357,0.004085,0.420611,0.313351,0.062773,-0.036976,-0.091605,-0.313633,-0.865960,0.054077,0.111148,0.240270,-0.535331,0.128559,-0.294125,-0.020852,-0.107227,-0.158470,-0.225714,-0.096792,0.483188,0.489944,-0.127219,0.024629,-0.193832,0.618248,0.421322,0.090391,-0.680187,0.088310,-0.364635,-0.580564,-0.268597,-0.380338,-0.648764,0.122968,0.195048,-0.169336,0.105710,0.372933,-0.547117,0.011521,-0.220723,-0.309812,-0.001704,-0.253021,0.011766,-0.765830,-0.015730,-0.096337,-0.043773,-0.090438,0.426202,-0.026108,0.641252,-0.520639,0.136631,0.161135,0.402386,-0.573829,0.420792,-0.094651,0.121953,-0.353983,-0.188180,0.444752,0.064240,0.152828,-0.015036,-0.049523,0.023160,-0.196609,-0.012619,0.382091', '1482099', '1322847', '7051375', '30391300');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27066184', '被抹去的男孩', '剧情', '乔尔·埃哲顿将自编自导新片[被清除的男孩](Boy Erased，暂译)，主演卢卡斯·赫奇斯，妮可·基德曼、罗素·克劳有望加盟。影片改编自杰拉德·康利同名自传，故事讲述阿肯色一个保守小镇的牧师之子(赫奇斯饰)因同性恋性取向而遭到家庭的排斥，基德曼、克劳饰其父母。影片将于今秋开拍。故事简介：在阿肯色州一座封建保守的小城，浸信会牧师19岁的儿子向父母出柜。男孩却被迫参加教会支持的同性恋矫正项目来“治愈”同性恋，否则将会付出失去亲人、朋友和宗教信仰的代价。他起初参与了含有12个步骤的残酷治疗，但最终鼓起勇气逃跑，选择拥抱真正自我。', '卢卡斯·赫奇斯', '乔尔·埃哲顿', 7.4, 21657, 'tt7008872', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2536682459.jpg', 0.5, 3.1, 36.6, 44.7, 15.1, '0.100590,-0.147455,-0.194828,0.515219,-0.113168,0.010288,0.579656,0.230834,-0.169541,-0.352394,0.193526,0.924277,0.077538,-0.031839,0.407223,-0.153703,-0.177146,-0.358287,0.127642,0.183606,-0.141176,-0.546977,0.003005,-0.345297,-0.338347,-0.573325,0.869287,-0.099062,-0.380679,0.125566,0.458007,0.223849,0.025658,-0.128557,0.236635,0.139545,0.170645,-0.131748,-0.459673,0.501489,0.075718,0.039932,-0.014694,0.198490,-0.146130,0.440108,0.747158,-0.076182,-0.016878,-0.215475,0.722866,-0.219950,-0.120695,0.131642,0.039917,0.135942,0.350683,0.360287,0.170540,-0.200573,0.074532,-0.351660,-0.542935,-0.051135,0.402529,0.092675,-0.382399,0.442830,-0.271248,0.095116,-0.025373,-0.320601,-0.167727,0.221722,0.473893,0.314326,-0.180401,0.272792,-0.112744,0.324733,0.390182,-0.185882,-0.317766,0.233520,-0.463002,-0.499948,-0.121085,-0.278635,-0.757895,0.190295,0.286163,-0.153301,-0.221661,0.421132,-0.427553,-0.303243,-0.361551,-0.270575,0.234552,-0.344834,0.080182,-0.657015,-0.162336,0.289441,-0.028914,-0.288330,0.035022,-0.430591,0.876370,-0.503757,0.193893,0.743957,0.309114,-0.548593,0.635792,0.234265,0.335447,-0.396649,0.144154,0.793923,0.084095,-0.139824,-0.118655,-0.021362,0.012101,-0.137252,-0.220710,0.370903', '30349667', '1322847', '3811356', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27066196', '找到你了', '剧情', '海伦·亨特加盟亚当·兰道([奇机少年])执导恐怖片[找到了](I See You，暂译)。一位儿童诱拐调查员忍受着妻子出轨的痛苦，妻子也因内疚逐渐变得情绪失常。邪恶之力渐渐入侵他们的家庭，两人的儿子也因此陷入了致命危险当中。本作将于今夏在克利夫兰开机。', '海伦·亨特', '亚当·兰道', 6.7, 12344, 'tt6079516', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2572133393.jpg', 1.4, 8.6, 49.8, 32.9, 7.3, '0.053925,0.100148,-0.541731,0.287473,0.113752,-0.203926,0.864882,0.192137,-0.522575,-0.366326,0.306286,0.819509,-0.232210,0.354504,0.259090,-0.254905,-0.086131,-0.555954,-0.071208,0.256726,0.009213,-0.300864,-0.404544,-0.390726,0.062351,-0.758384,0.784674,0.243435,-0.254048,0.189794,0.101287,0.674844,-0.162366,0.493917,0.362846,0.148033,-0.020884,-0.443191,-0.318982,0.123096,0.153953,-0.409087,0.236935,0.247306,-0.051359,0.400143,0.972342,-0.155201,-0.327690,-0.218095,0.569317,-0.151240,-0.296018,0.196438,0.050128,0.019755,-0.019684,0.109588,-0.224074,0.029967,-0.086103,0.004278,-0.711010,0.161050,0.043198,0.282968,-0.004565,0.265312,-0.239146,-0.085284,0.016814,-0.212274,0.120802,0.155303,0.154803,0.580619,-0.373811,0.207656,0.164146,0.043243,0.525848,-0.147162,-0.241354,0.308326,-0.421654,-0.304219,-0.037682,-0.349501,-0.764736,0.051025,0.594409,0.242052,-0.284758,0.643433,-0.417455,-0.191872,-0.190755,-0.084428,-0.409730,-0.194694,0.121476,-0.450716,-0.225176,0.164382,-0.087287,-0.192069,-0.062927,-0.297156,0.574463,-0.566522,0.463895,0.567887,0.408911,-0.431488,0.051013,-0.084365,0.280743,-0.068811,0.113341,0.755539,-0.193845,-0.075152,0.320899,0.091037,-0.358542,0.367116,0.071626,0.360119', '1307884', '1297735', '5327463', '3001149');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27066203', '曼蒂', '动作', '影片故事发生在1983年，樵夫雷德·米勒（尼古拉斯·凯奇 饰）与老婆曼蒂（安德丽亚·瑞斯波罗格 饰）居住在深山林里的一栋木屋。老婆曼蒂被一个价值观扭曲的宗教组织“新黎明之子”（The Children of the New Dawn）看上。该组织的领头杰瑞马雅（莱纳斯·罗彻 饰）欲收纳曼蒂入会未果，就在雷德面前活活把曼蒂烧死。雷德一度精神错乱，最终踏上复仇之路。', '尼古拉斯·凯奇', '帕诺斯·科斯马图斯', 5.4, 13535, 'tt6998518', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2543801251.jpg', 11.9, 31.1, 38.3, 14.5, 4.2, '0.342756,-0.073953,-0.544866,0.214540,0.235836,-0.577160,0.803247,0.161970,-0.273830,-0.303674,0.368241,0.457401,-0.155455,0.109666,0.612793,0.285507,-0.575277,-0.404270,0.151048,-0.015764,-0.216901,-0.393918,-0.257614,-0.004967,-0.233172,-0.464203,0.357997,-0.246941,0.130179,-0.055123,0.104369,0.796373,0.076315,-0.128673,0.359080,0.236190,0.611471,-0.614780,-0.138994,0.036904,-0.467747,0.017927,-0.340945,0.013835,-0.180189,0.165577,0.450729,-0.105631,0.235665,-0.249703,0.148985,-0.108895,0.233673,0.384224,0.219124,-0.120215,0.002409,0.483982,-0.053482,-0.179302,0.188630,-0.221228,-0.198782,0.344777,-0.028065,0.406340,-0.387216,0.189257,-0.235142,-0.093869,0.108471,-0.494465,-0.231067,0.275171,0.491006,0.244162,-0.113507,-0.206840,-0.323125,-0.246264,0.236677,0.075704,-0.255655,-0.002045,0.021199,-0.282920,-0.100906,0.329363,-0.502177,-0.355573,0.602415,-0.115900,-0.092488,0.734064,-0.786966,-0.218206,-0.583120,-0.228896,-0.091131,-0.086493,-0.227833,-0.631723,-0.112023,0.023926,-0.073656,-0.150048,0.113235,-0.053203,0.190897,-0.289689,0.573859,0.542121,0.013647,-0.113883,0.259321,-0.227710,0.100514,0.093764,0.074457,0.667095,0.386954,0.328589,-0.018267,0.400492,0.108185,0.037163,-0.216199,0.631715', '6311303', '6040982', '3227410', '26915921');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27067713', '曾经相爱的我们', '爱情', '曾经一起打拼的日子，让两个陌生男女Alan（陈柏霖 饰）和梦婕（郭采洁 饰）相识相爱，他们渐渐学会了一起哭，一起笑，养成一样的习惯。相爱简单，但相处太难，随着生活的磨炼，最初的爱情却走到被消磨殆尽最后的边缘。分开的日子里，他和她要面对的是无人应答的失落，是得不到回应的心痛，所有曾经的甜蜜美好，都成了在记忆里被反复拉扯的孤独。面对不期而至再次重逢的机会，两个人该一笑而过着遗憾，还是勇敢再爱一次？成全了你，也许只有最伤的我才懂，我们曾经相爱过。', '陈柏霖', '张小磊', 2.8, 6239, 'tt8702944', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2753056989.jpg', 69.2, 22.7, 6.6, 0.7, 0.7, '0.315686,0.016147,-0.741996,0.396757,-0.130841,-0.539899,1.020559,-0.276119,-0.383891,0.021885,-0.144175,0.518704,-0.078362,0.642887,-0.095572,-0.061519,-0.025826,-0.924045,0.076656,-0.176189,-0.252658,-0.350546,-0.052360,0.071068,-0.284322,-0.117605,0.605036,0.212967,0.152304,0.724281,0.424765,-0.083842,-0.091158,0.513024,-0.414918,-0.150332,-0.046731,0.412064,-0.618099,-0.189198,0.118140,-0.152560,-0.058277,0.030538,-0.157087,0.103235,0.462133,-0.146978,-0.162230,0.280842,0.146693,-0.221483,-0.265094,0.294072,-0.061036,0.148722,0.274895,0.272982,-0.250280,-0.092187,-0.128931,0.177038,-0.775489,0.132263,0.119219,0.042904,-0.717497,0.705376,0.456746,-0.233645,0.178070,-0.170872,0.282082,0.319876,0.738695,0.447891,-0.226889,-0.023718,-0.212571,0.324486,1.324542,-0.120617,-0.347573,0.601400,-0.399015,-0.198124,0.115524,-0.521862,-0.609866,0.145529,-0.178966,0.128495,-0.397034,0.244571,-0.659009,0.382204,-0.080779,0.038674,0.115801,-0.750507,0.217801,-0.305066,-0.585811,-0.861146,-0.651216,0.480390,-0.309687,-0.493093,0.799730,-0.794473,0.461783,0.545098,0.531902,-0.662272,0.786674,0.765607,-0.131567,-0.139968,0.520290,0.762574,-0.232908,-0.008669,0.413128,0.284369,0.018490,0.538503,-0.717060,0.536767', '27008393', '30209018', '25721544', '1308804');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27069070', '哆啦A梦：大雄的金银岛', '动画', '炎炎夏日，出木杉君向朋友们讲述了《金银岛》的故事。大雄（大原惠美 配音）兴致盎然，又在胖虎（木村昴 配音）、小夫（关智一 配音）以及静香（嘉数由美 配音）面前吹嘘要找到海盗的宝藏。当然，最终他还是要依赖忠实的好朋友哆啦A梦（水田山葵 配音）。哆啦A梦拿出了秘密道具“金银岛地图”，大雄则极其巧合地在太平洋中心找到了一座藏有金银财宝的新的岛屿。在此之后，好伙伴们扬帆远航，一路朝着太平洋中心前行。当最初的快乐刺激过后，一群神秘海盗将众人拦了下来。经过一番混战，静香还被对方当成另外一个女孩抢走。与此同时，大雄等人则救下了来自那座岛屿的男孩弗洛克（山下大辉 配音）。为了救回静香，他们追踪着海盗的踪迹，穿越茫茫大海……©豆瓣', '水田山葵', '今井一晓', 6.4, 38477, 'tt8098546', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2523364763.jpg', 2.9, 13.3, 51.7, 24.1, 8.1, '-0.141885,-0.245536,-0.402869,0.495271,0.149399,-0.138561,0.607935,0.024353,-0.150627,-0.080281,0.147998,0.510759,-0.083562,0.158338,0.222336,0.330777,-0.545411,-0.452804,-0.367084,-0.109810,-0.364284,-0.278769,-0.247685,-0.290792,-0.052022,-0.077866,0.509508,-0.051902,-0.187645,0.216669,0.358909,0.099661,-0.473464,0.175278,-0.245643,0.194332,0.087501,-0.021534,-0.278594,0.230106,-0.427339,-0.094203,-0.144397,0.090411,0.151245,0.087380,0.864691,-0.267579,0.023996,-0.004904,-0.018487,-0.242779,0.169241,-0.312914,0.324540,-0.140979,0.091670,-0.014476,-0.011631,-0.066399,-0.059084,-0.180613,-0.469457,0.013449,0.035123,0.084594,-0.250626,0.184690,0.209685,0.057818,0.315625,-0.353222,0.264426,0.123366,0.349976,0.180512,-0.140407,0.290211,-0.062340,0.147760,0.503809,0.108905,0.307920,0.230266,-0.113130,-0.329214,0.073316,0.071705,-0.148938,-0.076505,0.565193,0.034081,-0.127294,0.101475,-0.634242,-0.083112,-0.033237,-0.248033,0.081669,-0.381762,-0.220165,-0.592225,0.312876,0.054024,-0.027002,0.119909,-0.162657,-0.034039,0.917248,-0.370607,0.129462,0.857363,0.185646,-0.081298,0.406906,-0.130166,0.001972,-0.169967,0.027971,0.041635,0.147331,0.440249,0.278664,0.126606,-0.263327,-0.254446,-0.626432,0.138412', '5403927', '4181031', '3811356', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27069377', '淡蓝琥珀', '剧情', '故事的女主人公荷洁的丈夫意外死于交通事故，得到赔偿却失去一切亲人的她因为一块价值不菲的琥珀陷入了对生命价值的困惑。她在接连靠近肇事者家庭的失控后终释怀，以温柔姿态接受宿命归属。', '王真儿', '周劼', 6.2, 4032, 'tt8384298', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2548082317.jpg', 2.5, 17.5, 53.2, 23.3, 3.5, '-0.176773,0.418166,-0.460984,0.151598,-0.258220,-0.124314,1.169873,0.041016,-0.510061,-0.112479,0.355723,0.893033,-0.031820,-0.054968,0.017393,-0.098416,-0.022197,-0.445523,0.036905,0.053283,0.004682,-0.622577,-0.269208,-0.163311,-0.132546,-0.403073,1.082025,0.334134,-0.436307,0.393861,0.255948,0.413082,-0.125541,0.440412,0.011749,-0.051341,-0.350520,0.047416,-0.605876,-0.033314,0.002922,-0.058848,0.122371,0.436949,-0.257145,0.192833,0.916378,-0.473885,-0.843275,0.197093,0.506079,-0.476182,-0.045935,0.181325,-0.189193,0.253954,-0.059362,0.014480,-0.418848,-0.268047,0.628413,0.262194,-0.829109,-0.402104,0.347704,0.457376,-0.501869,0.720972,-0.180181,0.214568,0.035247,-0.265895,0.178691,0.212269,0.430974,0.595767,-0.614850,0.015997,-0.299384,0.148764,0.822989,-0.048283,-0.289948,0.485120,-0.638518,-0.715537,-0.352933,-0.448953,-0.682865,0.370928,0.331528,0.425567,0.026470,0.286425,-0.300624,-0.395854,-0.111631,-0.259388,-0.212348,-0.754233,-0.141879,0.051955,-0.206735,-0.010352,-0.731184,-0.058913,0.144316,-0.530615,0.682619,-0.546582,0.510271,0.627136,0.253947,-0.676856,0.376102,0.000618,-0.019610,-0.584134,-0.210606,0.917336,0.018750,-0.119128,-0.129011,-0.487961,-0.204802,0.414051,-0.378472,0.595668', '35287908', '1307884', '21619567', '3001149');
