INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27071217', '抱歉打扰', '喜剧', '卡修斯（勒凯斯·斯坦菲尔德 Lakeith Stanfield 饰）是一名落魄但自尊心非常强的青年，他住在叔叔的车库里，从事着毫无前途的电话销售的工作，还拖欠了四个月的房租，前途可谓是一片灰暗。在同事的点拨之下，卡修斯发现了提升业绩的小妙招，那就是将自己的声音伪装成白人，这让他在公司的境遇稍微好了那么一点。同事们因为种族歧视和寒碜的薪资待遇发起了罢工运动，虽然卡修斯在精神上表示支持同胞们的反抗，但实际上他更在乎的是能否利用这次机会升官发财。最终，卡修斯获得了晋升的机会，将那些反叛的同事们远远甩在身后，但随着职位的升高，他亦触摸到了公司里黑暗的秘密核心。©豆瓣', '勒凯斯·斯坦菲尔德', '布茨·赖利', 7, 9109, 'tt5688932', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2522624830.jpg', 1.3, 7.7, 40.8, 39.6, 10.5, '0.159227,0.084135,-0.532152,0.581690,-0.430683,-0.322333,0.613293,0.460693,-0.413628,-0.072542,0.074044,0.622322,0.051291,0.107063,0.163629,-0.155682,-0.109032,-0.604765,-0.121737,-0.140757,-0.197861,-0.516461,-0.404992,-0.149565,-0.392056,-0.413711,0.596189,0.083461,-0.370283,0.120963,0.322330,-0.008821,0.389014,0.560249,-0.304167,-0.061054,0.177780,-0.158288,-0.011543,0.282720,0.061121,-0.222078,-0.100918,0.287014,0.188970,0.535049,0.399553,-0.036253,-0.337035,0.134189,0.471939,-0.307758,0.017711,0.030597,0.326461,0.175030,0.204880,0.276639,-0.152885,0.061655,0.057514,-0.020748,-0.896522,0.176315,0.020804,0.031830,-0.852867,0.520587,0.009175,-0.184680,-0.076798,-0.331597,0.159908,0.483008,-0.191908,0.262476,-0.354713,0.053012,-0.647796,0.090482,0.509835,-0.088865,-0.279798,0.257336,-0.356996,-0.508389,-0.247455,-0.222979,-0.365629,-0.332041,0.343346,0.194481,-0.120985,0.089300,-0.602305,0.165457,-0.151223,-0.406746,-0.385603,-0.468811,0.007295,-0.548404,-0.083448,-0.378020,-0.511290,0.064764,0.259475,-0.392456,0.846257,-0.893027,-0.046594,0.601379,0.653344,-0.512265,0.733614,0.209471,0.189075,0.156007,-0.379914,-0.030995,0.098264,0.289644,0.244019,0.333151,-0.145184,-0.478117,-0.225768,0.555957', '1793491', '1783461', '1877596', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27072795', '幸福的拉扎罗', '剧情', '拉扎罗（阿德里亚诺·塔尔迪奥洛 饰）是一位内心单纯的年轻农民，坦克雷迪（卢卡·奇科瓦尼 饰）则是一位骄横的年轻贵族。他在Inviolata这座与世隔绝的小城内生活，这个城镇则由侯爵夫人阿诺西纳·德·卢娜（尼可莱塔·布拉斯基 饰）所统治。年轻的农民和年轻的贵族相遇并成为好友。某天，坦克雷迪自导自演了一场绑架戏码，希望骗到母亲的赎金，不料最终引来了警察……', '阿德里亚诺·塔尔迪奥洛', '阿莉切·罗尔瓦赫尔', 8.5, 105523, 'tt6752992', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2521583093.jpg', 0.5, 1.5, 11.9, 42.4, 43.6, '0.177229,-0.299431,-0.432141,0.436344,-0.332829,-0.303606,0.873191,0.208280,-0.175316,-0.361387,0.285049,0.736732,-0.039547,0.464482,0.692899,0.127585,-0.653684,-0.367775,-0.058711,0.014911,-0.126039,-0.510423,-0.193307,-0.357702,0.006148,-0.327561,0.597695,-0.037625,-0.011934,0.519146,0.317194,0.510136,-0.077148,-0.183983,-0.156005,0.045085,0.338940,-0.127310,-0.192087,0.081737,-0.619797,0.163883,-0.304080,0.137813,0.097498,0.379011,0.327892,-0.396054,0.358550,0.041172,-0.023721,-0.128593,0.298291,0.065114,0.192760,-0.553687,0.014291,-0.059731,0.012518,0.168927,0.172953,-0.205559,-0.456569,0.139795,0.094920,-0.001553,-0.196852,0.585497,-0.150296,-0.075645,-0.193127,-0.214298,-0.270157,0.278819,0.231135,0.438387,-0.086962,0.432237,-0.487725,-0.147468,0.440363,0.172797,-0.302464,0.240785,-0.321781,-0.382657,0.019331,-0.338513,-0.663664,-0.075348,0.414352,-0.352530,0.350387,0.522782,-0.626671,-0.304204,-0.618792,0.057618,0.148018,0.075623,-0.458839,-0.525789,-0.001417,-0.502572,-0.127905,0.153313,0.095208,0.077521,0.739895,-0.534180,0.056310,0.493946,0.193718,-0.333069,0.295703,0.022510,0.271959,0.072116,-0.338696,0.486442,0.310377,0.070758,0.041955,0.193221,-0.169287,-0.381734,-0.067418,0.393278', '35161768', '1301686', '1298095', '26630714');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27073057', '鼠胆英雄', '喜剧', '三十年代的上海滩，胆小如鼠的青龙帮小弟闫大海发现自己身患绝症之际，竟阴差阳错当上了警察。为了给梦中女神--飞乐门舞女杜卿挣赎身钱，他计划在自己生命中所剩不多的时间里因公殉职，从而拿到抚恤金拯救女神。然而，在他疯狂执行铲除“黑帮”、“毒枭”任务以身赴死期间，却总是事与愿违求死不得死，反而得到屡屡升迁。然而，纸醉金迷的上海滩，还隐藏着更大的危机……', '岳云鹏', '束焕', 5.2, 73044, 'tt10394802', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2564458983.jpg', 11.6, 32.7, 43.7, 9.3, 2.7, '-0.386221,0.526255,-0.537773,0.179733,-0.410653,-0.458324,0.428284,-0.149737,-0.392833,-0.184793,0.261378,0.188731,0.205709,0.173969,0.322137,-0.214422,-0.211267,-0.634272,-0.177402,0.101104,-0.025201,-0.173541,-0.565924,-0.258049,-0.297158,-0.160197,0.667159,0.612037,0.028636,0.004276,0.297275,-0.032349,-0.135488,0.636740,-0.273032,0.100138,0.082971,0.042424,-0.262628,0.266884,0.131133,-0.463839,-0.320315,0.255644,-0.053167,0.405769,0.406658,-0.264447,-0.011291,-0.335606,0.430590,-0.475647,-0.336138,-0.275800,0.084924,-0.147138,0.160822,0.064708,-0.192430,-0.022586,0.257729,-0.333028,-0.736361,-0.123404,0.067794,0.170949,-0.481450,0.030301,-0.133659,0.540814,0.130202,-0.150840,-0.027783,0.123063,0.269888,0.190886,-0.520340,-0.184643,-0.699424,0.772177,0.642104,-0.394368,-0.212071,0.125311,-0.108641,-0.384063,0.166406,-0.507760,-0.329857,-0.086325,0.136434,-0.064329,-0.214290,0.460767,-0.340061,-0.015545,-0.368571,0.096024,-0.231609,-0.363157,-0.186841,-0.265311,-0.102907,0.269101,-0.115833,0.540802,0.263417,-0.417668,0.396901,-0.412506,0.286159,0.715316,0.399273,-0.427191,0.590232,0.157239,0.246827,-0.080099,-0.244302,0.179766,0.114058,0.292628,0.102351,-0.335407,-0.535209,-0.243589,-0.104135,0.414072', '1917313', '26389321', '5985887', '4840388');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27073079', '碟仙', '惊悚', '梦瑶（黄奕 饰）是一位单亲妈妈，和女儿雯雯（程小夏 饰）过着相依为命的生活，为了赚钱养家，梦瑶从事着网络女主播的工作，日子过得虽然非常的辛苦，但只要能够和女儿在一起，梦瑶觉得吃再多的苦都无所谓。雯雯马上就要到上学的年纪了，梦瑶带着她搬到了一处便宜的离谱的学区房里，也就是从这一刻起，母女两人的命运被改变了。新家里的气氛十分的诡异，常常出现科学无法解释的奇怪现象。一天，梦瑶震惊的得知，雯雯竟然在是梦里玩了碟仙游戏，在传说中，所有玩了这个游戏的人，都无法活过7日。为了拯救女儿的性命，梦瑶开始调查起这间屋子的过去。©豆瓣', '黄奕', '廉涛', 4.8, 6305, 'tt10368970', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2559111658.jpg', 19.8, 32.9, 36.2, 8.6, 2.5, '0.505789,-0.140779,-0.724126,0.164154,-0.329925,-0.390061,0.536401,0.185891,-0.611600,-0.009519,0.330260,0.658364,-0.074599,0.600537,0.248713,0.364443,-0.346726,-0.467324,0.005121,-0.438319,-0.206625,-0.277111,-0.085453,0.080846,0.014296,-0.322061,0.328533,-0.153772,0.079690,0.527406,0.154034,-0.122443,-0.100131,0.515613,-0.243885,0.121922,-0.012459,0.173662,-0.335001,0.096812,0.244756,-0.012224,-0.184821,0.275458,0.120060,0.000704,0.676506,-0.126647,-0.366117,0.213682,0.404929,-0.099971,-0.256873,-0.002323,0.380929,0.004392,0.396276,0.225426,-0.314682,0.263195,0.053651,-0.046663,-0.819816,0.331092,0.175954,0.148578,-0.678023,0.463097,0.060369,-0.320890,0.025913,-0.613253,0.256390,0.373617,-0.050052,0.787215,-0.433305,0.070140,-0.697690,0.395536,0.635103,-0.250904,-0.104716,0.598101,0.039536,-0.078289,-0.069317,-0.375672,-0.647955,0.109134,0.083311,0.020417,-0.584481,0.186416,-0.671472,0.572548,-0.015977,-0.230152,0.101561,-0.417174,-0.315566,-0.321187,-0.283657,-0.507559,-0.369303,0.118043,0.088349,-0.331664,0.875673,-0.957832,0.096088,0.590134,0.334869,-0.482538,0.661367,0.282314,0.107775,-0.049208,-0.064420,-0.194393,-0.395778,0.479994,0.305836,0.508793,0.172799,-0.157981,-0.454058,0.508910', '1292219', '1877596', '24284209', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27073179', '邻里美好的一天', '剧情', '影片根据真实事件改编，聚焦美国著名电视主持人罗杰斯先生（汤姆·汉克斯 饰）与记者罗伊德·沃格尔（马修·瑞斯 饰）之间的友情故事。一心想要揭露社会阴暗丑恶的新闻记者罗伊德被安排采访罗杰斯先生，作为杂志新一期的英雄人物专题报道。试图借机挖掘罗杰斯先生阴暗面的罗伊德，也正因自己与父亲的矛盾面临着家庭问题和个人困境。而在采访过程中，他被罗杰斯言行一致的真诚善良慢慢影响，与父亲、与儿子、与妻子的关系也正在发生变化……', '汤姆·汉克斯', '玛丽埃尔·海勒', 6.6, 15634, 'tt3224458', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2620261010.jpg', 2.1, 11.6, 50.5, 27.8, 8.1, '0.185228,-0.151937,-0.307301,0.506311,0.202259,-0.138355,0.721915,0.173660,-0.494444,-0.313475,0.115771,0.899159,-0.422368,0.240396,0.509550,-0.056273,-0.694215,-0.891934,-0.119198,0.193073,0.091614,-0.878956,-0.328943,-0.338199,-0.039685,-0.394181,0.612791,-0.145005,-0.438899,0.337657,0.186105,0.540783,-0.368571,0.439187,0.370829,-0.072425,0.316336,0.044740,-0.767183,-0.084192,0.315138,-0.141433,-0.150765,0.263615,-0.169406,0.281034,0.440695,-0.240939,-0.173656,0.133439,0.399981,-0.188491,0.225410,0.358051,0.356395,0.081445,0.452194,0.595666,0.075239,-0.142266,-0.060710,-0.222303,-0.709487,-0.245147,0.026036,0.326800,-0.288292,0.445741,-0.164950,-0.174320,0.256391,-0.107550,0.222068,0.224872,0.664715,0.237336,-0.151736,-0.108955,0.058326,0.173342,0.272740,0.298099,-0.207017,0.280546,-0.389532,-0.275280,-0.168761,-0.053224,-0.596874,0.164237,0.414836,-0.117052,-0.271578,0.689526,-0.462993,-0.190136,-0.226952,-0.244674,0.014971,-0.490036,0.055862,-0.594589,-0.356985,-0.157610,-0.094837,-0.256080,0.121634,-0.190812,0.826537,-0.693592,0.143211,0.547153,0.156470,-0.409650,0.654408,0.250097,0.045964,-0.534663,-0.321044,0.026069,-0.016800,0.088415,-0.060483,0.118733,0.214408,-0.336531,-0.287156,0.313258', '4301278', '1303034', '3597344', '35134764');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27073234', '憨豆特工3', '喜剧', '《憨豆特工3》是憨豆特工系列喜剧的第三部作品，罗温·艾金森再度回归，继续扮演大受欢迎的阴差阳错入行的特工强尼。这次的新冒险由一场黑客攻击拉开序幕，所有在职的特工都被暴露了身份，使得强尼成为情报处最后的救命稻草。因此获得“返聘”的强尼第一个出勤任务便是要找出这位超强 黑客 。木头木脑、技能堪忧的强尼将如何应对现代科技的挑战，成功完成任务呢？', '罗温·艾金森', '大卫·科尔', 6.3, 82319, 'tt6921996', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2538352472.jpg', 2, 13.4, 56.3, 22.5, 5.9, '0.140825,0.004367,-0.061301,0.454251,-0.124584,-0.225297,-0.040801,-0.373460,-0.257326,-0.380397,0.460794,0.887715,-0.124729,-0.053073,0.401258,-0.423277,-0.259030,-0.686174,-0.317500,-0.072720,-0.316465,-0.411616,-0.293614,-0.009720,0.132945,-0.283656,1.046915,0.262619,-0.454324,0.113791,0.606026,0.490263,-0.125143,0.143373,0.015027,-0.173694,0.456133,-0.309647,-0.293204,0.392725,0.220379,-0.251056,0.009570,0.157009,0.075425,0.243964,0.559605,-0.250537,0.034932,-0.172922,0.702442,-0.780012,-0.150661,-0.216454,0.210278,0.018398,-0.264361,0.136418,0.099476,0.165820,-0.092839,-0.394503,-1.385834,-0.219077,0.175741,0.089052,-0.328216,-0.041225,-0.285292,0.149135,0.022400,-0.146072,0.209089,0.440469,0.629850,0.103143,-0.166132,0.268888,-0.188364,0.387674,0.514362,-0.091459,-0.324487,0.180650,0.094222,-0.701392,0.153490,-0.677732,-0.136708,0.215444,0.262756,0.249246,0.048323,0.178447,-0.635085,-0.261355,-0.541342,-0.259531,-0.163359,-0.391971,-0.079073,-1.051544,0.051791,0.256834,0.060922,0.104775,0.090012,-0.727919,0.630930,-0.822332,0.162859,0.634550,-0.067191,-0.499518,0.262280,0.070152,0.431899,-0.438395,0.001228,0.018386,0.373683,0.362853,0.107903,0.315553,0.061281,-0.593709,-0.082434,0.176204', '2369613', '3861846', '1793491', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27073245', '反叛的童谣', '动画', '童话新编，将多个儿时的童话故事杂糅在一起，形成了一段崭新的童话故事，想法大胆，别具一格，当小红帽、白雪公主、灰姑娘、三只小猪、杰克与豌豆等出现在同一个故事，该是多么精彩呢？本片提名2018年奥斯卡最佳动画短片。该短片IMDb分为Part1、Part2，豆瓣电影将二者合并收录为一个条目，标记前请知悉。', '罗伯·布莱顿', '扬·拉豪尔', 8.7, 42572, 'tt11714896', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2507016491.jpg', 0.1, 0.5, 9.8, 44, 45.6, '0.175232,-0.015212,-0.231853,0.671553,0.664938,0.099262,0.740385,-0.062052,-0.207341,-0.089247,0.045670,0.776533,-0.847403,0.171168,0.241458,-0.179674,-0.386320,-0.670624,-0.202954,-0.293962,-0.217858,-0.445231,-0.182951,-0.007457,0.326096,-0.083273,0.865019,-0.455029,-0.035845,0.162582,0.549394,-0.071676,-0.601685,-0.557441,-0.180044,0.299090,0.140753,0.234840,-0.363204,0.184763,-0.197807,-0.058843,0.064624,-0.347522,-0.268081,-0.339506,1.102505,-0.538904,-0.102227,0.202070,0.688297,0.181370,-0.253861,0.078125,0.009570,0.160475,0.226883,0.128705,0.141813,0.418086,-0.132219,-0.442867,-0.819334,0.004266,-0.023929,0.358581,-0.460632,0.138735,0.064020,-0.108308,0.474288,-0.232090,-0.029185,0.257991,0.767670,0.517149,0.107054,0.146246,-0.252462,0.650891,0.198083,0.096258,-0.343899,0.677432,0.064578,-0.418121,-0.140745,0.153594,-0.252726,0.316755,0.410644,-0.213711,-0.003966,0.203638,-0.877189,-0.247577,0.010909,-0.127531,0.335942,-0.436954,-0.205843,-0.520984,-0.258682,0.218466,-0.196888,-0.036706,0.213906,-0.167046,1.076421,-0.360078,0.495119,0.199099,-0.207661,-0.118466,0.629873,0.263658,0.082230,-0.216739,0.470154,-0.001803,0.027366,-0.110134,0.196561,0.315671,-0.048676,-0.075501,-0.898386,0.449543', '26759820', '5403927', '4181031', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27073291', '太空救援', '动作', '位于外太空的“礼炮7号”空间站意外与地球失去联系，工程师维克托·阿约金和退役宇航员弗拉基米尔·费奥多罗夫临危受命，搭乘联盟号T-13寻找“礼炮7号”的踪迹，当经历宇宙空间对接、太空舱寒流、空间站失火、太阳能充电系统失灵等一系列危机准备返航之时，却被告知空间站即将被击落，一场更大的太空灾难正在袭来......', '弗拉季米尔·弗多维琴科夫', '克里姆·斯彭科', 7.6, 66952, 'tt6537238', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2508922375.jpg', 0.2, 2.3, 30, 51.3, 16.3, '-0.040146,0.420481,-0.978954,0.190459,0.421667,-0.026984,0.622736,-0.083582,-0.068591,-0.338532,-0.027247,0.489206,-0.206970,0.018751,0.341614,-0.083207,-0.514559,-0.357275,-0.126998,0.031224,-0.569866,-0.458266,-0.138807,0.128967,0.380488,-0.430476,0.714106,0.090058,-0.279711,0.511673,0.051059,0.381792,-0.371070,0.826525,-0.307687,-0.356024,0.272235,-0.055115,-0.313667,0.091776,-0.441989,-0.106139,0.447252,-0.015170,-0.019976,0.305659,0.794495,-0.138073,0.045882,-0.562510,0.176792,-0.119099,0.368071,-0.256944,0.593105,0.320964,-0.660174,-0.065600,-0.022796,0.004647,0.126795,-0.044118,-0.365172,-0.110675,-0.211772,-0.317536,0.096132,-0.048640,-0.522697,0.403306,-0.086015,-0.040269,0.612094,0.829397,0.502529,0.499058,-0.507766,0.365713,-0.125231,-0.024336,0.720371,-0.288330,-0.588496,0.267946,0.513139,-0.340943,0.021423,0.104225,-0.201477,0.028021,0.690173,0.247005,0.127559,0.498300,-0.864149,0.273148,-0.709508,-0.769558,0.053329,-0.196495,-0.153569,-1.497904,0.134440,0.325161,-0.107843,0.600612,0.184582,0.249173,0.318976,-0.394570,0.488807,0.519663,0.128069,-0.245014,0.515662,-0.184608,0.228017,-0.730885,0.614406,0.145139,0.039840,0.857860,-0.430607,-0.017163,-0.071124,-0.108406,-0.349355,-0.073663', '3871833', '34961898', '1293572', '1300868');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27073752', '神奇女侠1984', '动作', '故事背景设定在五光十色、充满诱惑的80年代，神奇女侠戴安娜在华盛顿的自然历史博物馆过着与普通人无异的生活，然而在阻止了一场看似平常的劫案后，身边的一切都发生了变化。在强大的神力诱惑下，两位全新劲敌悄然出现——与神奇女侠“相爱相杀”的顶级掠食者豹女， 以及掌控着能改变世界力量的麦克斯·洛德，一场惊天大战在所难免。另外一边，旧爱史蒂夫突然“死而复生”，与戴安娜再续前缘，然而浪漫感动之余，史蒂夫的回归也疑窦丛生。新时代大幕开启，面对两位强大的邪恶反派和神秘归来的史蒂夫，神奇女侠要如何才能再次拯救世界？', '盖尔·加朵', '派蒂·杰金斯', 6.1, 244168, 'tt7126948', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2626959989.jpg', 3.4, 20.8, 49.6, 20.7, 5.4, '0.122779,0.443527,-0.675409,0.408423,0.100216,-0.073961,0.827476,-0.020369,-0.402534,-0.150154,0.247860,0.645305,-0.309657,0.067711,0.455701,-0.141595,-0.125492,-0.609272,-0.095753,0.009406,-0.238501,-0.379503,-0.744944,-0.029393,0.039238,-0.735204,0.563085,0.344257,-0.357225,0.269025,0.311648,0.276987,-0.646529,0.619467,-0.253137,-0.198874,0.123459,0.390155,-0.854375,0.155465,-0.010841,-0.023280,-0.203717,0.304890,-0.363255,-0.158913,0.510669,-0.715897,-0.281709,0.012612,0.611630,0.050663,-0.151500,-0.019142,0.061182,0.077297,0.112180,0.198596,0.170031,-0.154632,0.101339,-0.062837,-0.857244,-0.037216,0.182132,0.103469,-0.453472,0.254956,0.040453,-0.247812,0.087797,-0.229450,0.130376,0.352735,0.644506,0.553589,-0.120428,0.003769,-0.306921,0.022154,0.860434,0.263589,-0.763839,0.446750,-0.022472,-0.328822,-0.376711,-0.350468,-0.547839,0.102657,0.312790,0.285812,-0.039624,0.655007,-0.692253,0.089641,-0.193628,0.180664,-0.017400,-0.397876,-0.217361,-0.642671,-0.312856,-0.322693,-0.325497,0.090353,0.295487,-0.401885,0.894272,-0.866588,0.298308,0.528962,0.080217,-0.263106,0.470544,-0.001892,0.103039,-0.409866,-0.325755,0.297714,-0.259224,0.233509,0.048569,0.404217,-0.191560,0.307114,-0.336920,0.737776', '24284209', '1874704', '3769423', '26667010');
