INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27074301', '德鲁大叔', '喜剧', '达克斯（里尔·莱尔·哈瓦瑞 饰）为了一圆自己的篮球梦，参加在洛克公园举办的街头篮球锦标赛。在他输给对手穆奇后，自己的运势不断地走下坡路，直到达克斯遇见了前街头霸主——德鲁大叔（凯里·欧文 饰），希望获得他的助力，而德鲁大叔提出建立自己的球队。为此，两人共同出发去寻找德鲁大叔的老队员们（沙奎尔·奥尼尔、克里斯·韦伯、雷吉·米勒、内特·罗宾逊），之后一场场精彩绝伦的比赛不断上演，也发生了一系列趣味横生的故事。', '凯里·欧文', '查尔斯·斯通三世', 6.3, 30452, 'tt7334528', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2544791864.jpg', 3.8, 15.7, 49.4, 22.8, 8.3, '0.047237,-0.127940,-0.530185,0.344005,0.074925,-0.463629,0.609207,0.200772,-0.315667,0.054032,0.395539,0.839013,-0.321651,0.004755,0.673483,-0.264525,-0.478728,-0.770724,0.299151,0.052205,0.009523,-0.671870,-0.368471,-0.265201,0.080398,-0.226706,0.541874,-0.135759,0.064749,0.576231,0.199379,0.287941,0.433699,0.005403,0.014716,0.388864,0.398983,0.035162,-0.262203,0.439374,0.126490,0.269708,-0.707932,-0.148196,0.349679,0.177284,0.480593,-0.111421,0.410796,-0.224183,0.101234,-0.148299,0.374053,0.349504,0.051262,-0.155567,0.119575,0.166725,0.166485,0.047104,0.168186,-0.192655,-0.532163,0.412487,-0.220615,0.314914,-0.390702,0.545791,-0.134197,0.047566,0.277372,-0.256425,-0.169709,0.562500,0.521271,-0.192243,-0.047324,-0.150170,-0.323571,-0.179420,0.482321,-0.197967,-0.106735,-0.002885,-0.004251,-0.039848,-0.031142,-0.176729,-0.680961,-0.053671,0.611522,-0.097795,0.127843,0.393197,-0.560100,-0.103922,-0.242106,-0.631230,-0.033412,-0.088884,-0.144824,-1.063925,0.074221,-0.171527,-0.166031,-0.450442,-0.227354,-0.260589,0.421685,-0.808608,0.238455,0.771897,-0.041713,0.052215,0.205240,-0.012829,0.537687,-0.168627,-0.477648,0.228052,0.026826,0.373083,0.018928,0.491643,0.216348,0.115015,-0.075025,0.874078', '34961898', '3178770', '11541282', '2075345');
