INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27075198', '深红累之渊', '剧情', '著名话剧演员渊透世（檀丽 饰）去世前，将一支口红交到女儿小累的手中。这支口红是她和女儿一生幸福与痛苦的源头。长大以后，脸上留着恐怖疤痕的渊累（芳根京子 饰）见到了曾为母亲担任经纪人的羽生田（浅野忠信 饰）。羽生田带着唯唯诺诺的女孩来到剧场，观看了美丽的女孩丹泽妮娜（土屋太凤 饰）的表演。高傲的妮娜怎么也想不到，丑陋的累竟然可以用那支口红和她交换容颜。原来妮娜身体不佳，且演技进入瓶颈，所以羽生田提出让有着蓬勃表演欲望的小累担任妮娜的替身。在此之后，顶着美丽容颜的小累在舞台上飞速成长，而妮娜隐隐感觉到自己有将被取代的危险……本片根据漫画《累》改编。©豆瓣', '土屋太凤', '佐藤祐市', 7.4, 16680, 'tt7058612', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2527797980.jpg', 0.7, 3.9, 33.9, 45.7, 15.7, '-0.099046,0.248514,-0.610377,0.599181,-0.231484,-0.323690,0.645607,0.205096,-0.319044,-0.174425,0.280611,0.588885,-0.272104,0.311853,0.295632,0.088396,0.008514,-0.695451,-0.132475,0.008328,-0.362299,-0.297179,-0.356793,-0.058594,-0.057683,-0.492555,0.734926,0.036749,-0.222310,0.471108,0.390314,0.214013,-0.105709,0.052950,-0.124071,-0.068636,-0.110232,0.054720,-0.104453,0.071141,0.263405,-0.245373,-0.068243,0.020827,-0.053323,0.081905,0.956289,-0.074272,-0.204833,-0.076479,0.353158,-0.168675,-0.006647,0.133646,0.027580,0.207098,0.063060,-0.165001,-0.346683,0.036173,0.065683,-0.244658,-0.667430,0.090116,0.188354,0.274736,-0.617178,0.308537,-0.279755,-0.395295,0.414781,-0.448489,0.233027,0.044160,0.117065,0.407838,-0.177751,0.296723,-0.298238,0.325856,0.256064,0.175690,-0.123446,0.245696,-0.320533,-0.214627,-0.068403,-0.253898,-0.451794,0.226254,0.065851,0.029962,0.059604,-0.129078,-0.542442,-0.212563,-0.166265,0.041162,0.128953,-0.231942,-0.170579,-0.364219,-0.218022,-0.433797,-0.357209,-0.069046,0.012205,-0.373542,0.818195,-0.668808,0.329891,0.296751,0.287997,-0.077742,0.472934,0.054051,0.011124,-0.138417,-0.213758,0.352736,-0.154660,-0.003192,0.250714,0.400912,-0.272163,-0.027059,-0.428447,0.552914', '3811356', '10467125', '5416009', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27077266', '米花之味', '剧情', '小津安二郎以茶泡饭之味悠然细说夫妻生活的平淡是福，鹏飞则以米花之味轻盈道来母女心灵的亲疏远近。城市打工的妈妈返回云南傣族乡间，女儿跟所有留守儿童的问题并无二致：爱撒谎，玩手机，与同学争执，跟老师唱反调，还偷寺庙的钱。女儿好友之死打破隔阂，母女走进深幽钟乳洞，佛像前起舞，哀悼亡灵，也连系彼此灵魂。城乡差异、传统与现代的对碰、发展与保育的冲突，在诗意影像与禅意感悟中化解； 就烧一锅油，炸一盘米花，把生活的甜酸苦辣，调制成团圆的祝福。', '英泽', '鹏飞', 7.3, 23721, 'tt7022720', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2518728250.jpg', 0.7, 3.9, 34.9, 48.9, 11.6, '0.277639,-0.328972,-0.372183,0.402944,-0.035990,-0.265104,0.677755,0.434490,-0.126509,0.164138,-0.067100,0.512499,-0.040445,0.175583,0.261112,-0.150168,-0.153956,-0.706639,0.129409,-0.004622,0.135417,-0.411515,0.029385,-0.090847,-0.031314,-0.147779,0.136524,-0.299002,-0.271088,0.543400,-0.140735,0.009558,-0.659993,0.118275,-0.219519,0.124514,-0.433728,0.366814,-0.708078,-0.113575,-0.128693,0.047095,-0.032625,-0.324532,0.218339,0.232161,0.612752,-0.134813,-0.151220,-0.027314,0.079103,0.015625,-0.143471,0.157110,0.112890,0.129914,0.332762,0.347921,-0.088440,0.038090,-0.127135,-0.139941,-0.261505,0.061699,0.163112,0.019689,-0.391640,0.552642,0.358798,-0.253016,0.090419,-0.000843,0.448754,0.232086,0.218465,0.842119,-0.271080,-0.067369,-0.277566,0.115102,0.486178,-0.184305,0.012596,0.266027,-0.393639,0.009030,0.160699,0.047171,-0.389413,-0.162078,-0.281072,0.005550,0.096857,0.416012,-0.921866,0.053497,-0.091471,0.127600,0.439244,-0.460309,0.095241,-0.593918,-0.256650,-0.402987,-0.465894,-0.067147,0.418150,-0.067786,0.505418,-0.417392,0.184019,0.128898,0.555423,-0.275428,0.654504,0.091118,0.115424,-0.408331,0.047671,0.114328,-0.003373,0.249114,-0.055742,0.298699,0.043370,0.364676,-0.493000,0.056488', '1292050', '3439354', '26969120', '1394176');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27077479', '招魂3', '悬疑', '故事取材自1981年轰动全美的真实谋杀案，凶手亚恩·夏安·约翰逊杀死房东后声称自己是被邪灵附体才会行凶，是美国历史上首个被告以「鬼上身」作抗辩理由的案例，因此称为「恶魔谋杀案」。11岁男孩大卫被邪灵附体，陷入混沌状态，经常看见怪兽恶魔坐在他喜欢的摇椅上，而他身上更出现 离奇伤痕…受惊且束手无策的家人请来沃伦夫妇介入调查，他们发现大卫被43只恶魔缠身，使乖巧的他行为变得异常，例如像野兽般在地上爬行、胡言乱语甚至背诵他没有读过的圣经及《失乐园》章节…沃伦夫妇遂安排神父为大卫驱魔，可惜未见起色，而更诡异的事情接踵而来，大卫姐姐的未婚夫亚恩也开始行为异常，数月后，亚恩更以利刀刺死了房东。华伦夫妇认为亚恩行凶时被恶灵附身，原来大卫进行驱魔时，亚恩也在现场……', '帕特里克·威尔森', '迈克尔·查维斯', 6.4, 56536, 'tt7069210', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2641811991.jpg', 1.9, 13.5, 55.4, 22, 7.2, '0.203427,-0.197710,-0.390101,0.298181,0.103500,-0.144443,0.704556,0.041578,-0.601038,-0.425623,0.269041,0.568102,-0.317782,0.099791,0.182171,0.085561,-0.164837,-0.609384,0.033318,-0.000489,-0.256948,-0.350044,-0.162072,-0.432276,0.000198,-0.614659,0.259898,-0.180532,-0.248108,0.356663,0.083582,0.507172,0.040068,0.372077,-0.124367,-0.070850,0.049689,-0.027579,-0.072109,0.193588,-0.077530,-0.238658,-0.067067,0.244232,-0.321954,0.207629,0.506542,-0.425236,-0.404437,-0.449784,0.556118,-0.310556,-0.056365,0.309528,0.520830,-0.037567,0.372147,0.286529,-0.048996,-0.074739,0.165913,0.034340,-0.584841,0.204038,-0.147311,0.417390,-0.207010,0.101527,-0.159373,0.383008,-0.031690,-0.219929,0.212006,-0.061114,0.254717,0.095599,0.030759,-0.251977,-0.341953,-0.025738,0.379140,-0.115777,-0.319634,0.250598,-0.094652,-0.343802,-0.051784,-0.163446,-0.062867,0.173966,0.144487,0.083792,-0.261778,0.532080,-0.391905,-0.390098,-0.344590,0.092076,-0.448704,-0.053246,-0.399960,-0.560029,-0.206630,-0.048093,-0.243578,-0.153674,0.075233,-0.382776,0.379635,-0.585670,0.484449,0.363787,0.210660,-0.164169,0.385674,-0.120819,-0.094622,-0.206639,-0.167985,0.272608,0.228459,-0.015968,0.248665,-0.017268,-0.141021,-0.086079,-0.148131,0.440558', '30143939', '1298214', '24750534', '3231742');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27078344', '黑森灵', '惊悚', '故事讲述大学里的四个老朋友徒步穿越斯堪的纳维亚的荒野，然而错误的决定让他们深入北欧神话传说中的神秘黑森林，一个古老邪恶的生物也盯上几个人。', '拉菲·斯波', '大卫·布鲁克纳', 6.3, 8559, 'tt5638642', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2512008984.jpg', 2.2, 13.5, 54.9, 23.7, 5.7, '0.666738,-0.104099,-0.460885,1.329286,-0.026972,0.254223,0.982344,-0.541489,-0.526126,-0.356925,0.110621,1.057374,0.069682,0.321055,0.372821,0.329707,-0.215309,-0.304883,-0.035331,-0.468153,-0.459458,-0.375150,-0.677989,-0.680320,0.086916,-0.074639,0.475362,0.430535,-0.588076,0.685332,-0.206477,0.175537,-0.889264,0.113516,-0.403525,-0.103997,0.400908,0.209865,-0.111029,0.084330,-0.611600,0.219858,0.005056,0.351087,-0.366030,0.448335,0.632489,-0.483179,-0.190746,-0.122125,0.526028,-0.290452,-0.621473,0.045931,0.740965,0.017512,0.224542,0.482301,0.164459,0.230739,-0.447827,0.079005,-0.881740,-0.211074,-0.079636,0.120071,-0.440472,0.312211,0.834574,-0.252772,0.024339,-0.122638,0.481586,-0.385461,0.558092,0.631824,0.320920,-0.139667,-0.209684,0.147142,0.678723,-0.373548,-0.426475,0.038740,-0.129963,-0.578324,0.006694,-0.038542,-0.388750,0.115616,0.076417,-0.158941,-0.548959,0.455223,-1.201152,0.242141,0.077310,-0.232536,-0.234168,-0.485207,-0.371615,-0.584014,-0.283412,-0.036045,-0.297415,0.354294,-0.048590,0.087676,0.869742,-0.154309,0.394949,0.936282,0.065960,-0.491263,0.891906,0.049763,0.145231,-0.264350,0.187253,0.572234,0.180484,0.107922,-0.215062,0.568979,-0.431840,-0.300021,-0.655600,0.620564', '26290398', '25837262', '24879819', '19899718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27080656', '普罗米亚', '剧情', '因突变而产生操作火焰的变种人“燃烧者”，让半个世界被大火烧成焦土，陷入前所未见的惨状。在那之后的30年，当中一群激进份子“疯狂燃烧者”再次对世界发动攻击。为了镇压他们引发的火灾，普罗米波利斯自治共和国司政官古雷，组织了针对“燃烧者”而设置的高机动救命消防队“烈焰救火队”。效命于“烈焰救火队”，并拥有灭火之魂的消防队新人加洛，碰上了被通缉中的纵火恐怖份子，“疯狂燃烧者”的首领里欧，两人发生了激烈的冲突，当两个炙热灵魂彼此冲撞，这场对决将走向什么结局？', '松山研一', '今石洋之', 7.8, 62967, 'tt9116358', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2652044770.jpg', 0.5, 3, 26.5, 46.5, 23.5, '0.292975,0.206520,-0.902099,0.276856,0.158458,0.521293,1.031016,-0.078088,-0.479218,-0.082985,0.312827,0.459830,-0.523911,-0.224024,0.221578,-0.506806,0.266838,-0.782586,-0.223147,0.158905,-0.407938,-0.164124,-0.270966,-0.419993,-0.199954,-0.615083,0.700782,0.251925,-0.330528,0.244075,0.253400,0.409141,-0.070409,0.520952,0.144912,-0.233849,-0.242944,-0.235498,-0.027056,0.449728,-0.128473,-0.241308,0.153473,-0.028225,-0.369985,0.299004,0.848357,-0.607061,0.173017,-0.723510,0.230897,-0.727552,-0.012029,0.237907,0.538184,0.100830,-0.044142,-0.023169,0.057001,-0.187408,-0.200872,-0.003724,-0.868766,-0.009466,0.234106,0.064441,-0.179621,0.382372,0.308274,0.052030,0.165072,0.361657,0.185808,0.246055,0.378660,0.470756,-0.337813,-0.429112,-0.338508,-0.166422,0.748059,-0.444024,-0.741657,0.161106,-0.307192,-0.097156,-0.283900,-0.118391,-0.261299,-0.316694,0.489954,0.179432,0.212712,0.582166,-1.099497,-0.160155,-0.354054,-0.269393,-0.090930,-0.233863,-0.283648,-0.512154,-0.026976,0.129374,0.020744,0.231450,0.000340,-0.062952,0.516478,-0.657999,0.297040,0.433942,0.174503,-0.381281,0.125505,-0.270153,0.150192,-0.076493,0.029177,0.195661,0.511093,0.518238,0.326376,0.250777,-0.227902,0.424748,-0.070563,0.321165', '1578502', '10581450', '25774050', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27083561', '朝花夕誓', '动画', '故事发生在一座名为伊奥鲁夫的城市中，在这里出生的人们拥有无限的寿命，外表却会定格在15岁的模样，玛奇亚（石见舞菜香 配音）就是这样一个土生土长的伊奥鲁夫少女。一天，为了抢夺永生之血，梅萨蒂军乘坐着古代神兽对伊奥鲁夫发动了空袭，造成了惨重的损失，玛奇亚的好友蕾莉亚（茅野爱衣 配音）被掠走了，和蕾莉亚一起失踪的，还有玛奇亚暗恋的少年克里姆（梶裕贵 配音）。在黑暗的森林里，幸存的玛奇亚捡到了一名男婴，他的双亲在之前的袭击中丧生了。玛奇亚以母亲的身份收养了他，给他取名为艾瑞尔（入野自由 配音）。©豆瓣', '石见舞菜香', '冈田麿里', 6.9, 65051, 'tt7339826', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2545561196.jpg', 2.3, 11, 38.7, 33, 14.9, '0.112911,0.154417,-0.871717,0.671297,-0.298070,-0.088218,0.921819,0.057572,-0.247711,-0.198380,0.377335,0.906671,-0.050866,0.481055,0.325515,0.008677,-0.045273,-0.423130,-0.165625,-0.372651,-0.355190,-0.245714,-0.371701,-0.142298,-0.029682,-0.677019,0.665037,0.162754,-0.306571,0.234380,0.226925,0.290449,-0.039919,0.190647,-0.441685,0.262774,0.056625,-0.051535,0.275969,0.529989,-0.355505,-0.425623,0.183755,0.157567,-0.121798,0.398434,1.015669,-0.499344,-0.048671,-0.127469,0.389897,-0.337794,0.017408,-0.005855,0.584907,-0.138002,0.104239,0.029004,-0.356646,-0.036603,0.106871,-0.176077,-0.780901,-0.183784,0.093929,0.315856,-0.710001,0.690551,0.122305,-0.077977,0.193314,-0.203934,0.322941,0.368640,0.061375,0.587866,-0.190745,0.061120,-0.619040,0.269553,0.747431,-0.340518,-0.297915,0.429444,-0.230780,-0.516063,-0.104195,-0.298202,-0.548983,-0.163150,0.382811,-0.152478,-0.119382,0.327034,-0.678802,0.045490,-0.164930,-0.191802,-0.061304,-0.269139,-0.235797,-0.459847,-0.153325,-0.465264,-0.160013,0.186219,0.103863,-0.213472,0.956786,-0.760233,0.404262,0.729690,0.400329,-0.186424,0.550636,0.070855,0.221088,0.122042,0.137550,0.455320,0.201205,0.311854,0.177312,0.203722,-0.074253,0.039765,-0.557059,0.542629', '21619567', '25928048', '3005387', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27087724', '好莱坞往事', '剧情', '故事在1969年瞬息万变的洛杉矶展开，在那个风起云涌的变革时代，嬉皮文化盛行，好莱坞大制片厂制度瓦解，新的好莱坞明星纷纷崛起。电视明星里克·道尔顿（莱昂纳多·迪卡普里奥 Leonardo DiCaprio饰）与他长期合作替身搭档克里夫·布斯（布拉德·皮特 Brad Pitt 饰）如何在逐渐陌生的娱乐圈里，找到自己的一席之地。他们正力图扬名电影圈，却发现这个行业早已不是他们想象的样子了…… 这是昆汀自编自导第9部影片，汇集星光闪闪的卡司与交错的情节，纪念好莱坞不再复返的黄金年代。', '莱昂纳多·迪卡普里奥', '昆汀·塔伦蒂诺', 7.3, 220721, 'tt7131622', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2551119672.jpg', 1.2, 5.1, 36.9, 43.2, 13.7, '0.122740,0.135825,-0.751036,0.629658,0.433575,-0.203922,0.686121,0.268670,-0.194670,-0.227858,0.026673,0.766397,-0.316656,0.061320,0.173929,-0.064374,-0.485253,-0.730197,-0.290450,-0.134882,0.245221,-0.329464,-0.843855,-0.080209,-0.087265,-0.432696,0.903903,0.005446,-0.413969,0.126209,0.540256,0.234742,0.033654,0.232319,0.113376,0.129046,0.387296,0.082489,-0.530016,0.031045,-0.245457,-0.108757,-0.371920,-0.013167,0.021046,0.172958,0.414875,-0.172750,0.376767,-0.012629,0.672903,-0.106489,-0.400566,-0.230516,0.256124,-0.268945,0.114743,0.054442,0.016579,-0.128245,-0.323653,-0.302523,-0.672171,-0.012771,0.236246,0.604261,-0.522704,0.289051,-0.223666,-0.216727,-0.124232,-0.265309,0.064149,0.390008,0.520839,0.189765,0.216183,0.158604,-0.420951,0.497350,0.441805,0.498047,-0.594396,0.372998,-0.131731,-0.524886,-0.358813,-0.167843,-0.473743,-0.333925,0.419781,-0.454698,-0.026913,0.579186,-0.607811,0.032189,-0.141729,-0.313839,0.170850,-0.154106,-0.079057,-1.007598,-0.328299,-0.393641,-0.053751,-0.213216,-0.084220,-0.064537,0.709151,-0.661393,0.168029,0.523435,0.173425,-0.175782,0.737207,-0.077767,-0.024506,-0.310671,-0.435682,0.055341,0.113275,0.211711,-0.057302,0.398301,-0.022655,-0.381296,-0.288509,0.697619', '1293433', '1322847', '3318306', '26275494');
