INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27087882', '亿万懦夫', '喜剧', '王亿万背负着父亲寄予厚望的名字，却碌碌无为，胆小懦弱，在接到初恋女友陆小圈的请柬后前往泰国，取钱时竟偶遇丢失银行卡的⼩圈。婚礼前夜，两⼈被⿊哥劫匪团伙持枪困在银⾏中，陷⾝于⼀场真假劫匪的⻛波。', '张子栋', '沙海龙', 3.8, 6729, 'Billion Coward', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2621021428.jpg', 37.4, 38.2, 22.1, 0.8, 1.5, '-0.146259,0.336623,-0.467191,0.455983,0.008689,-0.180349,0.933428,-0.137343,-0.437046,-0.257985,-0.085700,0.476294,-0.094828,0.342439,0.381164,-0.387175,0.090745,-0.646800,-0.421135,0.077464,-0.405244,-0.220201,0.083045,-0.315812,-0.072432,0.036316,0.451135,0.401845,-0.429434,0.062693,0.667637,0.491345,-0.903067,0.276118,-0.345561,0.147851,-0.156748,0.235068,-0.249763,0.184368,-0.307368,-0.141659,0.147561,-0.123148,0.366237,0.220689,0.968562,-0.195910,0.106547,0.107863,0.342609,-0.065404,-0.687196,-0.068669,0.246546,0.307262,0.205074,-0.149231,-0.219760,-0.009918,0.460257,-0.246937,-0.224305,-0.084687,0.304407,0.164267,-0.889268,0.382504,-0.432543,0.371719,-0.120439,0.039477,0.165379,0.437820,0.047515,0.286086,0.391566,0.135557,-0.250362,0.179216,0.654068,-0.030163,-0.292565,-0.488428,0.115844,-0.478935,0.133181,0.163209,-0.042932,0.290073,0.736694,-0.517396,0.046451,0.126918,-0.454075,-0.369571,-0.059253,0.121577,0.228397,-0.366462,-0.616030,-0.293439,0.297099,-0.188717,-0.134462,0.617518,0.116712,0.270005,0.078650,-0.418312,0.371630,0.422715,-0.046576,-0.274183,0.598752,0.317282,-0.031138,-0.237100,0.018805,0.203623,0.753516,0.384646,0.313728,-0.125400,-0.527480,-0.147135,0.111088,0.216587', '21619567', '20451118', '26961002', '10777687');
