INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27089580', '恐惧街', '悬疑', '1994 年，一群青少年发现，发生在小镇几代人身上的恐怖事件之间可能存在某种关联，并且他们恐怕就是下一个牺牲品。《恐惧街》改编自 R·L·史坦恩的畅销恐怖系列，本剧揭开了荫城的险恶历史，这段长达 300 年的历史已成为小镇人漫长的梦魇。', '基亚娜·马德拉', '丽恩·贾尼埃克', 5.9, 12736, 'tt6566576', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2665617507.jpg', 4.5, 20.9, 52.8, 16.4, 5.3, '0.197588,0.120507,-0.672835,0.398769,0.545743,0.351105,0.716344,-0.437952,-0.613946,-0.405763,0.388464,0.384565,-0.342183,0.053713,0.368200,-0.293820,0.093976,-0.744532,-0.034562,-0.947086,-0.456074,0.043297,-0.803943,-0.237553,0.110715,-0.419838,0.715704,0.890622,-0.250796,0.344787,0.296939,0.358694,-0.390181,0.207774,-0.220703,0.076060,0.223939,-0.184977,-0.282974,-0.254989,-0.407118,0.142620,-0.015274,-0.270929,-0.171369,-0.050177,0.661173,-0.427017,-0.490477,-0.141544,0.734926,-0.259356,-0.189897,-0.036421,0.814927,0.006611,0.022954,0.726672,-0.194502,-0.312635,-0.017391,-0.152654,-0.965581,0.165663,-0.102040,0.396284,-0.312662,0.479524,0.377675,-0.382397,-0.187014,0.026270,0.363877,0.421920,0.754937,0.421046,0.079446,0.104594,-0.472203,0.230979,0.900228,-0.273400,-0.759804,0.096923,-0.264557,-0.269117,-0.587910,-0.440404,-0.401668,0.237131,0.254517,0.021598,-0.535316,0.511845,-0.459565,0.164528,-0.250482,-0.045417,0.337003,-0.214511,-0.505504,-0.396073,-0.286924,-0.429027,-0.256266,-0.010911,0.192401,-0.333087,0.583495,-0.238657,0.514074,0.770892,0.359838,-0.154478,0.884549,-0.285232,-0.100683,-0.225087,-0.103122,0.665931,-0.295721,0.391590,-0.105857,0.311864,-0.183589,-0.044200,-0.073966,0.609373', '6844861', '30368448', '26315728', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27089612', '纽约的一个雨天', '喜剧', '盖茨比（提莫西·查拉梅 Timothée Chalamet 饰）和艾什莉（艾丽·范宁 Elle Fanning 饰）是一对年轻的情侣，盖茨比浑身散发着文艺气息，对浪漫有着无限的向往和幻想，艾什莉则野心勃勃，一心想要在影视界里打拼出一片属于自己的天地。某个周末，两人相约前往曼哈顿度假，在那里，艾什莉意外遇见了自己挚爱的导演罗兰（列维·施瑞博尔 Liev Schreiber 饰）和编剧泰德（裘德·洛 Jude Law 饰），更由此得到了和大明星弗朗斯西科（迭戈·鲁纳 Diego Luna 饰）独处的机会。那边厢，盖茨比在充当群众演员的过程中邂逅了名为茜（赛琳娜·戈麦斯 Selena Gomez 饰）的女孩，一个半真半假的法式热吻点燃了盖茨比心里激情的火焰。©豆瓣', '蒂莫西·柴勒梅德', '伍迪·艾伦', 7.3, 189968, 'tt7139936', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2868674760.jpg', 0.5, 4, 37.3, 45.8, 12.3, '0.323759,-0.114451,-0.832602,0.609887,0.266835,-0.461649,1.022087,0.294292,-0.108082,-0.238327,-0.115914,0.846053,-0.826365,0.139580,0.591190,0.076246,-0.391611,-0.713316,0.063205,-0.172480,-0.002324,-0.620800,-0.412143,-0.139025,-0.106018,-0.351525,0.315099,-0.093456,-0.045143,0.583670,0.445110,0.366834,0.115207,0.366651,-0.259059,-0.040765,0.146275,-0.079286,-0.232999,0.305774,0.112661,0.023893,-0.067055,0.084386,-0.006994,0.175596,0.530730,-0.356363,0.365762,0.106053,0.165931,0.037601,0.001159,-0.120291,0.013200,-0.342473,0.195948,-0.117915,-0.180900,-0.025584,0.440266,-0.487716,-0.577239,0.115460,0.189262,0.407468,-0.553131,0.348033,-0.091018,-0.060067,0.376261,-0.102436,0.152550,-0.096680,0.036222,0.387178,0.255794,-0.001815,-0.528270,0.173405,0.382101,0.224289,0.024345,0.476491,-0.584536,-0.324932,-0.121443,0.025263,-0.735339,-0.096010,0.326505,-0.213766,0.344140,0.173014,-0.745982,-0.030585,-0.190224,0.098245,-0.103835,-0.333904,-0.102331,-0.844314,-0.361404,-0.528812,-0.128994,0.142607,0.007323,-0.305884,0.774657,-0.986521,0.032484,0.508066,0.265651,0.027113,0.584366,-0.017548,0.321756,-0.123481,-0.156875,0.285926,-0.114729,-0.226558,0.073428,0.648004,-0.119460,0.018167,-0.282990,0.515707', '1301686', '1394176', '1296534', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27090753', '秦明·生死语者', '悬疑', '影片根据法医秦明小说《尸语者》改编。讲述被誉为“鬼手佛心”的“尸语者”秦明（严屹宽饰）解剖过 1000 多具尸体，从未出错，因意外发现泡在福尔马林里6年的“无语体师”死于他杀，引发媒体质疑误判，被舆论推至风口浪尖之上。在尸体留下的线索指引下，秦明在实习助手嘉嘉（代斯饰）和刑警队长林涛（耿乐饰）的协助调查下发现了尘封 16 年的雪灾杀人案、误判 6 年的“无语体师”他杀案、悬而无果的 IT 男肺炸案背后的秘密。经历了这一系列变故的秦明最终成为了一名“为死者言，为生者权”的“生死语者”。', '严屹宽', '李海蜀', 4.1, 16803, 'tt10423912', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2558290293.jpg', 31, 40.6, 24.2, 3.1, 1.2, '0.236691,-0.177846,-0.486919,0.351168,0.234628,-0.029841,0.696805,-0.260177,-0.589557,-0.474621,0.322481,0.164120,-0.252403,-0.025337,0.274506,-0.628700,-0.059084,-0.797376,-0.134842,-0.322820,-0.404336,-0.467858,-0.525154,-0.168498,-0.216809,-0.386471,0.687882,0.042513,-0.325019,0.288249,0.152947,0.363386,-0.199522,0.155992,-0.002421,0.284951,0.000469,0.092889,-0.225429,0.272501,0.028602,-0.629440,-0.151998,-0.155338,-0.124994,0.405445,0.594751,-0.239599,-0.398427,-0.239455,0.564184,-0.316084,-0.020017,-0.152802,0.686756,0.227952,0.168771,0.556734,-0.258670,-0.156648,0.078805,0.141922,-0.764767,-0.381598,0.035301,0.510235,-0.428001,0.399299,-0.336154,0.253739,-0.283870,-0.194313,0.295341,0.162947,0.547806,0.284322,0.020754,-0.160922,-0.029864,0.434941,0.447292,-0.039999,-0.196657,-0.052739,0.054743,-0.499170,-0.082083,-0.238721,-0.112090,0.322964,0.313314,0.058945,-0.316404,0.364508,-0.255069,-0.396884,-0.171341,-0.135690,-0.097265,0.050556,-0.169066,-0.508546,-0.331489,-0.026031,-0.209336,-0.091099,0.068179,-0.532574,0.378071,-0.523089,0.426762,0.305388,-0.036033,-0.387029,0.463356,0.069284,0.132300,0.007274,-0.053779,0.109038,0.224470,0.523251,0.324124,0.198474,-0.059349,-0.371802,-0.369401,-0.198460', '3263169', '25799475', '4023433', '26328483');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27090813', '蝙蝠侠：煤气灯下的哥谭', '动作', 'DC动画电影，改编自《煤气灯下的歌谭市》，《蝙蝠侠：煤气灯下的哥谭》是DC“异世界”系列作品，而且是该系列第一部作品，同系列还有“西部蝙蝠侠”。《蝙蝠侠：煤气灯下的哥谭》处于“夏洛克福尔摩斯”的背景，除了设定为19世纪外，仍然是土豪布鲁斯韦恩与管家阿福的配置，蝙蝠侠最大的对手就是令伦敦警局闻风丧胆的“开膛手杰克”。本作与原版漫画一样，设定为19世纪，讲述蝙蝠侠追踪“开膛手杰克”的故事，充满了蒸汽朋克风。', '布鲁斯·格林伍德', '刘山姆', 6.9, 5993, 'tt7167630', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2508472121.jpg', 1.3, 7.8, 48.4, 32.1, 10.5, '-0.000462,-0.183806,0.057367,0.749367,0.389908,0.023136,0.562496,-0.048076,-0.372809,-0.649653,0.113211,0.934166,-0.317156,0.048772,0.325084,0.132809,-0.761943,-0.421294,-0.462010,0.007088,-0.128709,-0.489777,-0.344863,-0.281203,0.160961,-0.140499,0.691828,0.119652,-0.495624,-0.044378,0.467792,0.500136,-0.321625,0.152707,-0.288605,0.061664,-0.145286,-0.264218,-0.522471,0.371683,0.162223,0.186828,0.051966,0.040660,-0.208167,0.038521,0.561730,-0.354994,0.120774,-0.141736,0.678764,0.126161,-0.185269,-0.671444,0.308646,-0.198339,0.215841,0.290554,0.677698,0.175396,-0.155712,-0.239523,-0.987205,0.211876,0.277683,0.058953,-0.475080,-0.042182,-0.448036,0.271124,0.335831,-0.074868,0.181774,-0.515400,0.798206,0.557565,0.183582,0.189438,-0.485113,0.494635,0.199090,0.444093,-0.292913,0.420619,-0.190830,-0.447437,-0.749946,-0.004146,-0.491470,0.120956,0.153865,-0.063260,0.104705,0.340672,-0.668897,-0.041617,0.108104,-0.350229,0.042517,-0.198524,-0.100302,-1.105814,-0.054662,-0.336626,0.368579,-0.255117,0.168392,-0.485605,0.604036,-0.603186,0.055521,0.296659,-0.181738,-0.195190,0.736877,0.079727,-0.241406,-0.418741,-0.130254,0.404491,-0.054354,0.010837,-0.031717,0.245326,-0.011859,-0.455243,-0.172780,0.766266', '26275494', '3318306', '26577354', '30397916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27092648', '蒙上你的眼', '剧情', '当一股神秘力量要歼灭人类，大家只知道一个法则：万一你看到它，就要奉上自己的性命。面对一切未知，梅乐莉找着爱与希望，以及可以瓦解这股力量的新转机。她别无选择，只好带着两个孩子渡过危机四伏的河流，逃往唯一可能安全的地方避难。为了生存下去，他们必须蒙上双眼，踏上长达两天的危险旅程。', '桑德拉·布洛克', '苏珊娜·比尔', 7.2, 49494, 'tt2737304', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2537908150.jpg', 0.9, 5, 39.4, 42.4, 12.4, '-0.215673,0.213478,-0.679747,0.583831,-0.070926,0.009786,0.555251,-0.058656,-0.145487,-0.152493,-0.041659,0.612627,0.461220,0.361625,0.055934,0.045550,-0.152322,-0.450882,-0.120427,-0.336789,-0.486945,-0.217913,-0.495853,-0.098740,0.061928,-0.429038,0.634813,0.770383,-0.311395,0.008337,0.253252,0.037789,-0.274079,0.539139,-0.231807,-0.643172,-0.589911,-0.213519,-0.607611,0.293543,0.289077,0.018389,-0.046383,0.313908,-0.083834,-0.049676,0.525301,-0.350582,-0.165980,-0.124444,0.120904,-0.606790,0.142989,0.050052,-0.159377,-0.277559,0.224612,0.193116,-0.078230,-0.039713,0.220130,-0.244343,-1.031506,-0.085385,-0.181562,0.267403,-0.539539,-0.111147,0.321045,-0.210015,0.076051,-0.582985,-0.089932,0.430082,0.161229,0.371071,-0.469757,0.112520,-0.542043,-0.391856,1.055893,-0.498432,-0.115165,0.086756,-0.019584,-0.080149,-0.141914,-0.260444,-0.487159,0.130526,0.394026,0.518828,-0.081248,0.052017,-0.516477,0.296787,-0.350122,-0.404842,0.007259,-0.431682,0.229436,-0.128502,0.080016,0.108545,-0.249839,0.724094,0.457792,-0.356172,0.527799,-0.184165,0.378818,0.941840,0.596270,-0.767345,0.489866,0.407314,0.262470,-0.576792,0.245186,0.241148,-0.244692,0.511986,0.234947,0.114623,-0.045853,0.323136,-0.518083,0.522923', '26678784', '30163500', '30368448', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27092785', '李茶的姑妈', '喜剧', '貌不惊人的李茶（宋阳 饰）希望和土豪之女结为夫妇，他从未谋过面的姑妈（卢靖姗 饰）成为他婚姻的最大支柱。土豪的公司经营陷入困境，因此急于攀附李茶那位有钱的姑妈。土豪大女婿梁杰瑞（艾伦 饰）也是个见钱眼开的家伙，得知自己老爹破产时，他甚至建议老爹去向李茶的姑妈求婚。一群厚 颜无耻之人翘首以盼，谁曾想姑妈却迟迟未来。众人愁眉苦脸，却独独乐坏了梁杰瑞公司的小人物黄沧海（黄才伦 饰）。沧海跑进原本为姑妈准备的别墅好好享受一番，结果阴差阳错被众人当做姑妈捧上云霄，得知内情的李茶和梁杰瑞干脆将计就计。另一方面，姑妈不顾随从（王成思 饰）的阻拦，隐藏身份偷偷潜入海岛，更将这场闹剧引向了不可预测的方向……©豆瓣', '黄才伦', '吴昱翰', 4.6, 306263, 'tt8299800', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2533384240.jpg', 22.2, 37.7, 30.6, 7.1, 2.4, '0.061604,0.230021,-0.560099,0.500396,-0.322997,-0.288845,0.283366,0.150894,-0.544389,-0.511985,0.091459,0.418836,-0.283361,0.269840,0.220042,0.047678,-0.074061,-0.332204,0.126419,0.174182,-0.048033,-0.363038,-0.251394,-0.392369,-0.155954,0.412328,0.123275,0.209338,-0.244975,0.078265,0.575133,0.172832,-0.246980,0.331942,-0.034445,0.258644,0.092379,0.195633,-0.433826,-0.084489,-0.039965,-0.154087,-0.136730,0.217353,0.146750,0.212543,0.278597,-0.195898,-0.026740,-0.115333,0.237597,-0.098351,0.096310,0.246899,0.166036,-0.243475,0.135569,-0.067914,0.022049,-0.193263,0.349960,-0.152251,-0.322999,0.308470,0.228909,-0.148075,-0.498440,0.244648,-0.100721,0.058505,-0.168945,-0.301023,-0.056112,0.252844,0.061081,0.210802,-0.091927,0.297269,-0.381872,0.324196,0.355336,0.094344,0.324951,0.146483,-0.044009,-0.186826,0.148707,-0.165297,-0.516020,-0.057348,0.413087,-0.058985,0.006987,0.228341,-0.257824,-0.214506,-0.248060,0.055111,0.342132,-0.392247,0.055678,-0.266914,0.012105,-0.266455,-0.123457,0.071162,0.102569,-0.231862,0.495765,-0.408589,-0.191653,0.093476,0.158294,-0.787816,0.538612,-0.075527,0.014703,-0.296617,-0.076338,-0.056085,0.421817,0.090221,0.350324,-0.014463,-0.032565,-0.357232,-0.032101,0.221524', '1421278', '1302110', '1301221', '1297710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27093500', '氧气危机', '科幻', '《氧气》是一部求生题材法国惊悚片，由亚历山大·阿嘉执导。这部电影讲述了一名年轻女子（梅拉尼·罗兰饰，《鬼影特攻：以暴制暴》《无耻混蛋》）在低温舱中醒来，她不记得自己是谁，为何出现在这里。由于氧气即将耗尽，她必须重建自己的记忆，以逃离这噩梦般的场景。', '梅拉尼·罗兰', '亚历山大·阿嘉', 6.5, 7692, 'tt6341832', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2642895723.jpg', 2.5, 11.7, 52.1, 26.6, 7, '-0.160739,0.283377,-0.769450,0.350372,-0.124318,-0.149699,0.799370,-0.414292,-0.308526,-0.572456,0.409094,0.619543,-0.080004,0.039195,-0.034261,0.097069,-0.497776,-0.279281,-0.174889,0.153520,-0.307998,-0.081920,-0.491088,-0.033894,0.149757,-0.486595,0.754246,0.237500,-0.485074,-0.246053,0.347809,0.302967,-0.134845,0.401593,0.136838,0.040763,0.097504,-0.357193,-0.197914,0.252564,0.053026,-0.607905,-0.097112,0.121258,-0.129215,0.154832,0.435021,-0.189892,-0.088614,0.061136,0.507508,-0.354851,-0.201757,0.017812,-0.041284,-0.171319,0.201215,-0.106908,-0.106352,0.106016,-0.383991,-0.378967,-0.720166,-0.072740,0.101528,0.343496,-0.490696,-0.015841,-0.522914,0.096532,0.152921,-0.174720,0.044493,-0.012508,0.445566,0.399276,-0.218183,-0.240536,-0.630795,0.396570,0.635812,0.035150,-0.491734,0.552472,-0.069845,-0.331519,-0.142504,-0.044707,-0.579822,0.263692,0.203420,-0.226589,-0.111077,-0.010411,-0.330111,-0.079449,-0.116753,-0.218001,-0.207920,0.224633,-0.401104,-0.495968,-0.181970,-0.301270,-0.051184,-0.348862,-0.160856,-0.394301,0.658630,-0.687626,0.116932,0.600077,0.212560,-0.311675,0.493566,0.049439,-0.118225,-0.189892,0.252740,0.589337,-0.060315,-0.001143,0.139560,0.259610,0.247462,0.182309,-0.366173,0.732791', '25763555', '1304641', '10440076', '2078398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27093707', '升级', '动作', '格雷（罗根·马歇尔-格林 Logan Marshall-Green 饰）和女友艾莎（梅拉里·沃列何 Melanie Vallejo 饰）相恋多年，两人之间感情非常要好。一天，格雷带着艾莎去拜访一位名叫艾伦（哈里森·吉尔伯特森 Harrison Gilbertson 饰）的科学家，艾伦设计了人工智能芯片STEM，令艾莎叹为观止。在回去的路上，格雷和艾莎所乘坐的无人驾驶汽车发生了故障，将两人带往了一处暴徒聚集的贫民窟，在那里，两人遭到了袭击，艾莎不幸丧生，而格雷身受重伤下半身瘫痪。心中充满了痛苦和绝望的格雷想为恋人报仇，于是找到了艾伦，将STEM芯片植入了大脑，在STEM的操纵下，格雷重新站了起来。让格雷没有想到的是，STEM的智慧远远超乎他的想象，而他亦被卷入了一个巨大的阴谋之中。©豆瓣', '罗根·马歇尔-格林', '雷·沃纳尔', 8.2, 152101, 'tt6499752', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2531034314.jpg', 0.2, 1.1, 18, 52.3, 28.4, '0.429320,-0.093854,-0.843158,0.401275,-0.062219,-0.473190,1.140314,0.159379,-0.643332,-0.043604,0.055088,0.748840,-0.379665,0.217674,0.263092,0.146210,-0.547863,-0.707752,-0.150797,-0.062174,-0.409019,-0.715486,-0.269360,-0.128512,-0.042880,-0.568896,0.415624,-0.156136,-0.044901,0.521063,0.239042,0.570883,-0.250893,0.442581,-0.134134,0.127765,0.251444,-0.279399,-0.008560,0.425630,0.226069,-0.168267,0.087511,0.258193,-0.226844,0.230560,0.681046,-0.233987,0.038883,-0.113160,0.152179,-0.348168,0.150364,0.270029,0.168033,-0.032579,-0.157908,0.040073,-0.434422,0.053361,0.461629,0.313556,-0.838461,-0.044021,-0.113838,0.161342,-0.998135,0.454114,-0.141358,-0.137125,0.278579,-0.410324,0.265133,0.342833,0.302571,0.243962,-0.116845,-0.121649,-0.602375,-0.226689,0.605370,-0.150282,-0.298930,0.137799,-0.186798,-0.322103,-0.217761,0.148200,-0.478503,-0.280994,0.614901,0.033081,-0.225604,0.357270,-0.628810,-0.065460,-0.704061,-0.265768,-0.412441,-0.367435,-0.136571,-0.681608,-0.212333,-0.442527,-0.265196,-0.055202,-0.044335,-0.161162,0.484677,-0.743594,0.290703,0.362050,0.274955,-0.018490,0.379123,-0.139765,0.167978,0.014877,0.167542,0.177939,0.123925,0.300938,0.412253,0.448458,0.068854,0.100591,-0.719440,0.502251', '1578663', '21619567', '3111650', '1421570');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27094896', '方法派', '剧情', '實力派演員載夏與人氣偶像英佑在共演的舞台劇中飾演一對同志情侶。英佑的態度傲慢不用心，讓總是全心投入表演的載夏氣憤不已，兩人在排練時常常爭吵。某次排演時，載夏的精湛演出感動了英佑，他開始認真投入表演，兩人漸漸地互生情愫，陷入虛實難辨的愛恨糾纏之中…', '朴成雄', '方银振', 6.8, 22482, 'tt7022402', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2502082901.jpg', 1.3, 9.6, 46.7, 31.1, 11.3, '0.136899,-0.205778,-0.844023,0.893371,-0.413639,-0.154370,0.635219,0.211469,-0.107312,-0.022324,0.413394,0.737314,-0.876431,0.123115,0.439905,-0.213130,-0.039182,-1.145259,-0.551515,0.267697,0.260640,-0.489341,0.251950,-0.317437,-0.102164,-0.278115,0.701867,0.265530,-0.394905,0.292646,0.422599,0.358880,-0.251965,0.610100,0.070971,-0.069645,0.264365,-0.067165,0.069758,0.262028,0.255366,-0.349885,-0.441822,-0.131321,0.088073,0.054941,1.095692,-0.078704,-0.435814,0.260184,0.820819,-0.301572,-0.073920,0.051198,0.233431,0.062036,-0.263119,-0.161258,-0.296458,0.339222,-0.131738,-0.033497,-1.000172,-0.193347,0.311118,0.001596,-0.740607,0.876670,0.144953,-0.111515,-0.212318,0.042148,0.348467,0.228464,0.244585,0.422539,0.271485,-0.218379,-0.382974,0.582887,0.756877,0.210169,0.183079,0.300321,-0.308913,-0.689155,0.105812,-0.139978,-0.600962,-0.127078,0.176018,-0.309851,0.126564,0.233808,-0.206740,-0.063795,0.431702,-0.313053,-0.069855,-0.627877,0.110383,-0.960142,-0.443571,-0.793341,-0.226566,-0.433601,0.069462,-0.415545,0.786389,-1.021481,0.239241,0.551564,-0.296062,-0.042962,0.992355,0.528410,-0.531162,0.050227,-0.452249,0.016957,-0.344106,-0.025576,0.438446,0.669062,0.119890,0.056603,-0.683503,0.486877', '2027945', '26259202', '3811356', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27097816', '罪途1之死亡列车', '剧情', '本片是《罪途》三部曲的第一部，后两部是《罪途2之救赎代价》与《罪途3之正义规则》，三集共同讲述了一个故事：2005年，一列绿皮火车因暴雨引发泥石流而被停在半路。一节车厢中的八名乘客，全部陷入了不明原因的昏迷当中。调查结果则更让人心惊，其中一位乘客已经成为了冰冷的尸体……', '含笑', '马小刚', 6.6, 19146, 'tt10260370', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2521612839.jpg', 1.3, 10.2, 51.9, 30.2, 6.5, '0.223817,0.069906,-0.742940,0.498920,0.119068,-0.019469,1.185561,-0.201224,-0.445806,-0.330140,0.421700,0.970148,-0.393351,0.168194,0.565619,-0.380915,-0.018135,-0.613434,-0.626087,-0.303703,-0.475589,-0.209221,-0.089938,0.083472,-0.242968,-0.385938,0.735941,0.488250,0.004972,0.584719,0.439473,0.385881,-0.508360,0.320961,0.108969,-0.033399,0.244143,-0.381726,0.053481,0.129118,-0.243921,-0.925346,-0.068617,0.290267,-0.719473,0.416532,0.963093,-0.272259,0.006836,-0.154409,0.232780,-0.318348,-0.149638,-0.138844,0.649689,0.147631,0.417746,0.555321,-0.093117,0.170809,0.070375,0.165874,-0.924147,-0.318990,-0.124865,0.339786,-0.416479,0.481985,0.034186,-0.060805,0.065642,-0.130451,0.587963,0.088472,0.613533,0.636461,-0.131637,-0.448385,-0.284038,0.092439,0.676980,-0.167555,-0.320642,0.596095,-0.110690,-0.478141,-0.020624,-0.044042,-0.416792,0.136263,0.732723,0.343663,0.050510,0.406529,-0.800835,0.097259,-0.327124,-0.546321,-0.521283,-0.226107,-0.188080,-0.339445,-0.213168,-0.028602,0.128057,0.289771,0.270436,-0.150153,0.878041,-0.376085,0.202801,0.179262,-0.262236,-0.341876,0.393882,-0.080425,0.454015,0.241516,0.553125,-0.039286,-0.098686,0.386140,0.025499,0.453628,-0.470342,-0.093760,-0.535280,0.478479', '21619567', '1467779', '1299767', '1307800');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27098016', '急速逃脱', '惊悚', '卡尔是一名建筑商人，某天送儿女上学时突然接到一通陌生电话，说车上安放了炸弹，一离开座椅炸弹就会爆炸，如果报警就摇控炸车。狭小的车内空间顿时将三人的不安和紧张感无限放大…中途剧情紧凑反转不断，而警察调查结果竟将犯罪嫌疑人锁定为卡尔自己，随着时间流逝，卡尔面临即将失去所有财富、性命甚至家庭的多重危机将如何解决？最终结局又会出现怎样的反转？', '克里斯蒂安娜·保罗', '克里斯蒂安·阿瓦特', 6, 5046, 'tt6686700', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2568928751.jpg', 3.6, 19.4, 54.9, 18.9, 3.3, '0.060632,0.290518,-0.545120,0.266404,0.139127,-0.094355,0.837664,0.084234,-0.343565,-0.091469,0.344724,0.563434,-0.489027,0.021279,0.281432,0.016383,-0.403104,-0.877570,-0.188829,0.167669,-0.675904,-0.528610,-0.182742,-0.444286,0.427256,-0.271958,0.493194,0.177807,-0.186970,-0.022066,0.119812,0.320722,-0.405636,0.834442,-0.050625,0.066077,-0.095710,-0.163897,-0.242911,0.260531,0.182767,-0.435853,0.247718,0.170185,-0.291664,0.136542,0.604690,0.050003,-0.246861,-0.009360,0.448870,-0.367653,-0.300104,-0.060011,0.298940,0.163210,0.122883,0.020169,-0.532955,0.076777,0.333485,0.015328,-0.552292,0.151775,-0.308564,0.151083,-0.287865,-0.271247,-0.240669,0.078795,0.131474,-0.022315,0.347109,0.298035,0.579961,0.240758,-0.581161,-0.028066,-0.141762,-0.292137,0.388539,-0.410065,-0.338843,0.190171,-0.098191,-0.177279,0.023514,0.246901,-0.288005,-0.256294,0.581130,0.491666,-0.081369,0.268485,-0.218691,-0.117014,-0.710179,-0.435509,0.007123,-0.558426,-0.448509,-0.197425,0.044926,0.320777,-0.303630,0.422937,0.266453,0.183104,0.736247,-0.266370,0.127557,0.547628,0.295982,-0.208227,-0.081335,-0.284801,0.167415,-0.198878,0.278535,-0.061246,0.040052,0.428993,0.041947,-0.079820,-0.328350,0.038488,-0.255612,0.566626', '21348112', '10486471', '1307146', '1309297');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27098363', '自杀小队：严厉惩罚', '动作', 'DC动画电影《自杀小队：严厉惩罚》(Suicide Squad: Hell to Pay)发布预告，小丑女、死射、冰霜杀手、铜头蛇、回旋镖队长、铜虎组成小队，阿曼达·沃勒派遣他们去找回一个神秘物件——为此他们愿意牺牲性命，而小队很快发现他们面临着其他团伙的挑战。克里斯汀·史莱特、C·托马斯·豪威尔、塔拉·斯特朗、连姆·麦肯泰尔、比利·布朗、克里斯汀·鲍尔、凡妮莎·威廉姆斯、丹妮亚·拉米雷兹等参与配音，Sam Liu(《蝙蝠侠：致命玩笑》《绿灯侠》动画系列)执导，今春发行数字版、DVD和蓝光碟。', '克里斯蒂安·史莱特', '刘山姆', 7.4, 15404, 'tt7167602', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2519085369.jpg', 0.8, 3.6, 34, 45.6, 15.9, '-0.020722,-0.328126,-0.065715,0.218604,0.022759,0.167133,0.497540,0.202488,-0.026433,-0.266763,0.543535,0.643644,0.019173,-0.394800,0.250725,-0.032757,-0.652957,-0.196390,0.098013,-0.132825,0.001691,-0.421561,0.165035,-0.245538,0.146911,-0.210584,0.328031,-0.510799,-0.028149,0.606112,0.471115,0.556815,-0.180160,-0.073096,0.701682,0.299353,0.561469,-0.793219,-0.125645,0.198470,-0.234654,0.489259,-0.219988,0.060481,0.154016,0.351979,0.410784,-0.159272,0.488578,-0.380050,0.012604,-0.282354,0.352189,-0.301371,0.209356,-0.241460,0.165487,0.038401,0.329808,-0.109956,-0.063237,-0.152436,-0.703538,0.418360,-0.177487,0.352380,-0.411185,0.066746,-0.655485,0.430788,0.281961,0.101264,-0.183360,0.068300,0.497001,-0.199703,0.069765,0.046342,-0.263988,-0.008179,0.121521,-0.323056,-0.413112,-0.150723,0.066002,-0.215917,-0.212307,-0.056282,-0.237256,-0.030351,0.625494,-0.116828,0.185289,0.146475,-0.483049,-0.150606,-0.416669,-0.150612,-0.054117,-0.168240,-0.027216,-1.211458,0.286134,0.256722,-0.141864,-0.266130,-0.168631,-0.256175,0.347384,-0.211888,0.193929,0.451051,0.316250,-0.159748,0.267767,-0.112726,0.028937,-0.293032,0.184377,0.564097,0.455485,0.053721,0.316354,-0.079895,0.148573,-0.093601,0.160203,0.223330', '6517421', '34961898', '26335580', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27098364', '超人之死', '动作', '最新DC动画电影，“该来的时候，甚至是神也必须要死！”今年是超人诞生80周年，这发生在1993年的故事，今天仍然是漫画界中最浓重的一笔。影片讲述超人与“毁灭日”这个劲敌战斗之后被杀的故事，随着之后的超人复活还将引出超人的接班人“小超（Superboy）”，其中超人的另一个反派版本“机械超人”同样将亮相。超人的死去活来，本有成为经典超人故事的潜力。然而DC在这个题材面前却屡次以平庸收场。这次能成功么？', '杰瑞·奥康奈尔', '杰克·卡斯托雷纳', 7.5, 15963, 'tt7167658', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2526823875.jpg', 0.7, 3.4, 33.8, 45.4, 16.7, '-0.149274,0.281755,-0.287063,0.495084,0.175603,-0.050102,0.612120,-0.301052,-0.502340,-0.356055,0.057629,1.035223,-0.381100,0.100900,0.332835,-0.262338,-0.238674,-0.646543,-0.139942,-0.022072,-0.277855,-0.231704,-0.442850,0.246004,-0.016164,-0.425278,0.846157,0.072807,-0.380652,0.373617,0.421026,0.215575,0.102307,0.224030,-0.285256,-0.078339,0.023154,0.283508,-0.003346,0.509558,0.117755,-0.242237,0.137402,0.279016,-0.557984,-0.032786,0.439621,-0.577094,-0.186023,-0.204819,0.815646,-0.522194,-0.545919,0.004302,0.186464,-0.205063,0.333755,0.331707,0.215912,-0.058402,-0.133423,-0.147550,-1.481387,-0.280968,0.096361,-0.049954,-0.475667,0.003553,0.040288,0.155578,0.256739,0.025500,0.349475,0.326449,0.641276,0.472106,-0.274312,0.071317,-0.674577,0.418120,0.639834,0.180147,-0.456687,0.358652,0.157632,-0.514401,-0.113626,-0.682220,-0.119598,0.488794,0.243066,0.183129,-0.050480,0.314071,-0.713889,0.039669,-0.081869,-0.049619,0.036325,-0.402710,-0.389507,-0.494864,-0.229133,-0.233792,-0.120866,-0.020445,0.120709,-0.559944,1.091214,-0.795393,0.198037,0.474374,0.042493,-0.270917,0.761050,0.163735,0.034357,-0.338546,0.074171,-0.009270,-0.099621,0.257109,-0.174121,0.289179,0.156888,-0.392800,-0.468202,0.843130', '27602116', '6844861', '1793491', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27098365', '超人王朝', '动作', '本片作为《超人之死》的续集，主要讲述了超人与“毁灭日”这个劲敌战斗死去之后，超人的遗体却意外消失无踪，同时出现了四位超人头衔的竞争者，分别是： 超人的DNA制造出的復制超人——小超人、使用自制高科技裝甲的钢铁人——钢铁超人、半人半机械的生化人——机械超人、以及对罪犯毫不留情的神秘氪星人——歼灭者。在卢特公司的新品发布会上，四位超人相继出现在大都会，展开了一场别开生面的超人大混战。所有人似乎都在争夺成为下一代的钢铁英雄。同时这世界依然动荡不安，黑暗势力似乎已经开始在暗处酝酿着什么，一切都只是时间问题……在超人死后的世界，这四位超人在世间的定位到底是什么，又是为何而生，背后又隐藏着怎样的阴谋？……', '杰瑞·奥康奈尔', '刘山姆', 6.9, 7550, 'tt7167686', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2545769995.jpg', 0.8, 6.8, 49.7, 32.8, 9.9, '-0.085979,0.160291,-0.697698,0.437948,-0.070779,0.045659,0.761732,-0.008110,-0.390696,-0.301025,0.558234,0.679736,-0.220676,-0.096487,0.101036,-0.299794,-0.338402,-0.719355,-0.390726,-0.145440,-0.543221,-0.355818,-0.663961,-0.172658,0.337877,-0.510219,0.680035,0.151033,-0.329342,0.044494,0.498289,0.243261,-0.319658,0.422772,-0.349671,-0.084023,0.024897,0.101842,-0.201841,0.102902,-0.241579,-0.122841,-0.113360,0.331136,-0.475105,0.136897,0.483977,-0.682682,-0.080605,-0.200490,0.351709,-0.509106,-0.014710,-0.173261,0.469764,-0.056027,-0.034075,0.087635,0.191860,0.034240,0.120776,0.225760,-1.202882,-0.203684,0.075446,0.300492,-0.529165,0.459499,0.082635,-0.065112,0.086519,-0.035129,0.233543,0.285390,0.264969,0.431664,-0.105132,0.103219,-0.683552,0.296541,0.525978,0.066565,-0.826765,0.216827,0.221415,-0.484261,-0.691319,-0.425756,-0.253707,-0.128433,0.263985,0.114788,0.013693,0.527303,-0.858585,0.024005,-0.034666,-0.146278,-0.030498,-0.367862,-0.163993,-0.746949,0.035796,-0.215198,-0.133117,0.096472,0.221610,-0.280024,1.002876,-1.035667,0.150240,0.571413,0.106451,-0.405119,0.531713,-0.176580,0.044480,-0.334736,-0.285107,-0.018272,0.210487,0.291879,-0.084169,0.364932,0.117036,0.006356,-0.417428,0.640913', '24284209', '1793491', '3769423', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27098888', '羞辱', '剧情', '一人是黎巴嫩基督徒，另一人是巴勒斯坦难民，两人因口角摩擦走上法庭。这场斗争在媒体的推动下引发了全国范围的大动荡。看似两人之间的小事，实际上牵扯出整个中东的政治及信仰问题，由此影片引发人们有关真相、信仰、人性与和平的思考。男主卡梅尔·巴沙凭借此片夺得威尼斯电影节沃尔皮杯最佳男演员。', '阿德尔·卡拉姆', '齐德·多尔里', 8.3, 19957, 'tt7048622', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505204599.jpg', 0.3, 1.1, 14.6, 52.7, 31.2, '0.352758,0.383278,-0.747273,0.360316,0.395863,0.353306,0.657439,0.228666,-0.547854,0.082711,0.320840,0.595559,-0.718519,-0.417604,0.320445,-0.434088,-0.478646,-0.922244,-0.194027,0.232444,-0.003910,-0.589622,-0.275326,-0.243340,-0.813661,-0.259831,0.821293,0.349184,-0.768638,0.174001,0.369554,0.164378,-0.338970,0.102883,0.288845,-0.119902,-0.120303,-0.040390,-0.654933,0.071239,0.008577,-0.413821,-0.226900,0.267808,-0.288314,0.506070,0.407397,-0.306701,0.257296,-0.258705,0.644496,-0.392784,-0.166040,0.049046,0.417583,-0.060604,0.116974,0.506270,-0.026339,-0.129728,0.210599,-0.042056,-0.422643,-0.209340,0.072403,0.480199,-0.262894,0.522295,0.174840,-0.188042,-0.060843,0.057134,0.027916,0.707982,0.404233,0.092280,0.012064,-0.298925,-0.192836,0.011890,0.830704,-0.188464,-0.573887,0.038270,-0.613068,-0.548167,-0.403051,-0.422818,-0.112221,-0.163451,0.347788,-0.196295,0.243050,0.990808,-0.606605,0.224939,-0.123164,-0.561464,0.299180,-0.059626,0.271815,-0.904671,-0.412918,-0.359343,-0.180510,-0.146828,0.215124,-0.184983,0.697728,-0.664075,-0.172355,0.710086,0.291179,-0.392003,0.510406,0.098116,0.484474,-0.290119,-0.114121,0.119269,-0.230652,0.105311,-0.133517,0.065654,0.113308,-0.093886,-0.056940,0.181214', '1302050', '26990609', '25978126', '33454993');
