INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27102476', '第一炉香', '剧情', '电影根据张爱玲的同名中篇小说改编。葛薇龙（马思纯 饰）是一位单纯而又善良的女学生，为了躲避战火，她和家人逃难来到了香港，之后，受生活所迫，葛薇龙的家人决定返回故乡，打算继续求学的葛薇龙只身一人留在了异乡，并且投靠了生活在这里，在很早之前就和家族断绝了关系的姑母梁太太（俞飞鸿 饰）。虽然外头对于梁太太的流言蜚语满天飞，但是葛薇龙自认为并不会被这个神秘的女人所影响。可随着时间的推移，在梁太太的带领之下，葛薇龙品尝到了奢靡生活所带来的甜头，并且逐渐沉迷无法自拔。在梁太太毁灭了她对于爱情的美好幻想之后，一位名叫乔琪乔（彭于晏 饰）的公子哥出现在了葛薇龙的身边，令葛薇龙重新燃起了对于爱情的渴望。©豆瓣', '马思纯', '许鞍华', 5, 120402, 'tt10415576', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2700127550.jpg', 11.4, 39.4, 38.7, 8.9, 1.6, '0.289108,0.152686,-0.682292,0.598151,-0.128548,-0.231074,0.753981,0.287118,-0.735837,-0.405840,0.040258,0.706614,-0.020025,0.391900,0.391691,-0.155679,-0.354051,-0.725507,-0.098151,-0.272089,-0.206001,-0.319313,-0.089440,-0.131211,-0.268840,-0.457096,0.817039,0.350843,-0.319101,0.603618,0.260303,0.312204,-0.193235,0.583912,-0.332822,0.030985,-0.019544,0.222227,-0.533117,0.196275,0.199751,-0.450543,0.060587,0.180533,0.002824,0.018866,0.794238,-0.508725,-0.273327,-0.102439,0.336445,-0.256329,-0.029281,0.241173,0.212528,-0.038813,0.344887,0.309254,-0.354587,0.145338,-0.109967,-0.114924,-0.777207,0.062345,0.173546,0.048415,-0.702381,0.584003,0.237242,-0.333241,-0.001783,-0.219602,0.402201,0.454121,0.295259,0.361824,-0.387119,0.027448,-0.345511,0.327692,0.920040,-0.010725,-0.185675,0.560752,-0.284730,-0.220763,-0.114062,-0.120597,-0.604079,-0.018034,0.144254,0.300103,-0.189499,0.418226,-0.689403,0.076373,-0.147470,-0.311489,0.291155,-0.602908,-0.214533,-0.366774,-0.331722,-0.371868,-0.109182,0.140795,0.061374,-0.263612,0.882363,-1.067961,0.514816,0.530029,0.323713,-0.987310,0.544201,0.045568,0.032294,-0.162339,0.010892,0.488482,0.056790,0.379284,0.094771,0.179637,-0.196092,-0.235664,-0.349919,0.541348', '35030151', '1293265', '1301022', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27102505', '去年冬天与你分手', '剧情', '知名摄影师木原坂雄大（斋藤工 饰）之前因一起火灾而陷入诉讼。火灾中，他所聘请的盲眼模特不幸身亡，木原坂本人也深受重伤。事后，他因涉嫌诱拐、监禁和谋杀而被起诉，但在律师的帮助下最终逃脱了制裁。此后，自由撰稿人耶云恭介（岩田刚典 饰）找到某周刊编辑主任小林良树（北村一辉 饰）。希望该周刊能够支持他对木原坂黑暗的一面展开调查。在获得周刊的同意后，耶云拜访了木原坂，得以近距离观察这位神秘摄影师的工作状态，了解其内心所想，并走访与他生命中息息相关的人，却没有料到自己正步步走入对方的陷阱……本片根据芥川赏作家中村文则的小说改编。©豆瓣', '岩田刚典', '泷本智行', 7.7, 23403, 'tt7210252', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2511323383.jpg', 0.3, 2.5, 27.3, 51.2, 18.7, '0.015392,0.011346,-0.272158,0.422737,0.303755,-0.154021,0.386346,0.324072,-0.457576,-0.512282,0.195831,0.402438,-0.146842,0.251804,0.204350,-0.019006,-0.347775,-0.529713,-0.231839,0.090220,-0.180082,-0.369797,-0.282877,-0.115677,-0.212568,-0.123010,0.806335,0.261503,-0.257962,0.328831,0.133238,0.574170,-0.170116,0.243624,0.256632,0.158354,0.212831,0.027969,-0.486297,0.555360,-0.115527,-0.403519,-0.197013,0.317635,0.211835,0.244087,0.574866,-0.268636,-0.400175,-0.168678,0.451304,-0.217095,0.063659,0.447552,0.260816,0.207902,0.248250,0.230521,-0.327777,0.018423,0.003965,0.125444,-0.810425,-0.216964,0.043592,0.286383,-0.305991,0.179779,-0.120011,0.026808,0.207036,-0.189433,-0.015453,0.166792,0.425897,-0.179648,-0.197876,0.112357,-0.089577,0.291197,0.436698,-0.040152,-0.101113,0.120841,-0.361644,-0.438379,-0.101305,-0.045470,-0.106899,-0.054468,0.152664,0.395165,-0.094349,-0.056961,-0.165006,-0.214645,-0.245515,0.018800,-0.136563,-0.391066,-0.013240,-0.807927,-0.160448,-0.161057,-0.212647,-0.052715,0.152437,-0.539592,0.603805,-0.717339,0.212163,0.629246,0.219462,-0.438073,0.485413,0.289356,-0.235339,-0.204609,-0.095305,0.131590,0.351427,0.440095,0.029494,-0.076999,0.172184,-0.488771,-0.310228,0.016433', '2369613', '3861846', '27073234', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27102569', '悲伤逆流成河', '剧情', '多组校园欺凌事件，打破了5位主角本应该美好的青春校园生活。齐铭（赵英博 饰）清俊帅气，是人人称颂的优等生，而易遥（任敏 饰）却是大家口中的“赔钱货”。两人一同长大，感情很好。而这一切，在转学生唐小米（朱丹妮 饰）出现之后发生了翻天覆地的变化。流言成了毁人利器，处处对易瑶进行刁难，易遥的生活开始陷入黑暗，遭受各类残酷欺凌。顾森西（辛云来 饰）教会易瑶对校园暴力进行反击，他的出现给了易遥一丝曙光。可阴差阳错，顾森湘（章若楠 饰）的意外却将她再度推入黑暗。当受害者变成施暴者，当看客变成助推，在这一场名为“玩笑”的闹剧中，没有旁观者，只有施暴者……', '赵英博', '落落', 5.8, 245850, 'tt9036926', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2616327870.jpg', 10.2, 24.7, 37.9, 19.5, 7.6, '0.259492,0.137960,-0.478994,0.336986,-0.061344,-0.087259,1.086016,0.130042,-0.539428,-0.130486,0.258433,0.438628,-0.576383,0.015556,0.317085,-0.096628,-0.349509,-0.724478,-0.214945,-0.010408,-0.100400,-0.172471,-0.149910,-0.201506,0.078918,-0.218825,0.609674,0.308427,-0.439902,0.204102,0.349940,0.384006,-0.044337,0.517452,-0.228436,0.110564,-0.229890,0.206326,-0.369551,0.044637,-0.333317,-0.458029,-0.298734,0.182152,-0.196572,0.060487,0.844386,-0.345130,-0.283191,-0.134298,0.620532,-0.516149,-0.333224,0.067725,0.223764,0.134144,0.181933,-0.141261,0.086320,0.010774,0.165670,-0.142897,-0.453985,0.043865,0.115937,0.218552,-0.294996,0.599863,0.280214,-0.053836,0.204652,-0.085200,0.157349,-0.017996,0.491470,0.172297,-0.155277,0.110508,-0.475638,0.208984,0.726449,-0.094164,-0.668006,0.407263,-0.355350,-0.249402,0.042214,-0.354106,-0.387640,0.024844,0.223998,-0.041822,-0.154961,0.630398,-0.375789,-0.171985,-0.073490,-0.194739,-0.053153,-0.552803,-0.340730,-0.483986,-0.397574,-0.438773,-0.533185,0.168602,-0.204039,-0.225420,0.479341,-0.873126,0.278619,0.016426,-0.144878,-0.485466,0.387821,0.195373,0.010460,-0.095982,-0.166732,0.145074,-0.059557,0.420728,0.071416,0.117016,0.004898,0.086320,-0.211471,0.357736', '21348112', '2377539', '1308755', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27102739', '中国蓝盔', '剧情', '我国首部维和军事题材电影《中国蓝盔》讲述了当下中国维和部队官兵在非洲坚决执行习主席指示的“构建人类命运共同体”的大国方针、严格履行联合国赋予的使命，派出了以“兵王”杜峰为首的作战小组冒着生命危险，从恐怖分子手中救出联合国调查组，从而阻止了一场一触即发的战争，维护了难民营的生活秩序、保障了难民们的生活权益。但是年轻的战士也在这次行动中为了维护非洲的和平而献出了宝贵的生命……', '徐洪浩', '宁海强', 3.5, 7296, 'tt10443424', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2536557304.jpg', 50.7, 30, 13.8, 2.8, 2.8, '-0.092384,0.232046,-0.471377,0.693134,-0.022556,-0.008899,0.160884,0.036112,-0.224074,0.091351,0.552458,0.840287,0.530406,-0.378152,0.399018,-0.238840,-0.495609,-0.817028,-0.630263,0.199084,-0.311870,-0.448737,-0.115614,-0.553751,-0.244864,-0.461575,0.909822,0.101945,-0.435144,0.409939,0.038115,0.057501,-0.141526,0.128289,0.077025,-0.491215,0.402658,-0.152521,-0.581016,0.034018,-0.111350,-0.228789,-0.246018,0.512225,-0.008654,0.559889,0.515612,-0.565981,0.006566,-0.531531,0.433964,-0.776547,0.002591,-0.153109,0.372496,0.323180,-0.137686,0.395146,0.239736,0.109039,-0.091975,-0.472558,-0.972591,-0.401191,0.105512,0.169787,-0.649600,0.598914,-0.061206,0.122475,0.147560,-0.014836,0.313231,0.875830,0.288539,0.353148,-0.187617,0.168332,-0.476596,0.517619,0.595905,-0.498399,-0.566470,-0.174139,-0.641609,-0.581661,-0.029024,-0.450941,-0.428067,-0.421782,0.129741,-0.311947,-0.111323,0.203522,-0.878917,0.275803,-0.187885,-0.467463,0.074198,-0.387790,0.248543,-0.825597,-0.206520,-0.278393,-0.109406,0.256034,0.187301,0.048275,1.192417,-0.630836,-0.288675,0.672116,0.361759,-0.739329,0.418965,0.456164,0.289459,-0.355388,0.087707,0.302605,-0.079346,0.745179,0.066714,0.055473,-0.028480,-0.124309,-0.062151,0.162062', '27602116', '1292444', '25863940', '6424814');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27107140', '我想吃掉你的胰脏', '爱情', '“没有名字的我，没有未来的她”对他人毫无兴趣，总是独自一人读书的高中生“我”。这样的“我”有一天，偶然捡到一册写着《共病文库》的文库本。那是，天真烂漫的班上人气王·山内樱良私下记录的日记本。里面记载着她身患胰脏的疾病，已经时日无多……。隐藏自己的疾病度过日常的樱良，与知晓其秘密的“我”。——两人的距离，还没有名字。', '高杉真宙', '牛岛新一郎', 6.9, 102761, 'tt7236034', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2545571306.jpg', 2, 9.8, 42.5, 32.4, 13.2, '0.452233,-0.052813,-0.914413,0.940616,-0.319013,-0.090905,0.871532,-0.055643,-0.486089,-0.482632,0.085887,0.577261,0.004607,0.406003,-0.287390,0.224563,-0.176579,-0.627414,-0.039336,-0.181880,-0.529812,-0.427782,-0.563903,-0.368818,-0.420416,-0.244584,0.478010,0.105480,-0.505889,0.001937,-0.096650,0.050994,-0.048676,0.646574,-0.679819,0.272873,-0.251063,0.213422,0.265894,0.142206,0.403202,-0.306468,-0.438050,0.203649,0.215503,0.615889,0.708573,-0.277002,-0.373036,0.251783,0.445556,-0.220438,-0.083346,0.011259,0.354063,-0.272453,0.197844,0.292745,-0.210800,-0.186534,0.059649,-0.200086,-0.888159,-0.505743,0.106740,0.717045,-0.304524,0.774311,-0.561874,-0.133871,0.207996,-0.266049,0.186238,0.446135,-0.076116,0.092016,0.016160,-0.296791,-0.802196,0.512436,0.493697,-0.091817,-0.469646,0.400662,-0.402776,-0.448713,-0.225922,-0.230329,-0.739239,0.183933,0.183139,0.004143,-0.467270,-0.013942,-0.389768,0.166413,0.306761,-0.155088,0.014274,-0.269043,-0.085307,-0.283616,-0.152891,-0.588468,-0.659087,-0.171806,0.207230,-0.410623,1.017019,-0.838060,0.374906,0.451492,0.116455,-0.510237,0.889448,0.238484,-0.081326,0.057837,-0.127802,0.068005,-0.095876,0.471004,0.175981,0.417551,0.508952,-0.070066,-0.538689,0.702608', '1303077', '25932086', '1303542', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27108740', '家族之苦3', '喜剧', '此次的故事将围绕 “妻子”展开。史枝（夏川结衣饰）作为家庭主妇，与丈夫幸之助（西村雅彦饰）、2个儿子以及公婆住在一起。某天下午，家里遭小偷，藏在冰箱里的私房钱被洗劫一空。在丈夫的抱怨中，史枝决心离家出走，而平田家也因此陷入混乱。因为富子（吉行和子饰）身体不好，周造（桥爪功饰）开始与打扫、洗衣、做饭展开“恶战”，并深切体会到史枝的不易。然而史枝并没有回家的意思，平田家不得不再次召开紧急家庭会议……', '桥爪功', '山田洋次', 8, 21604, 'tt7493808', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2515706733.jpg', 0.2, 1.3, 21.5, 51.5, 25.5, '0.366897,-0.125474,-0.761231,0.075201,-0.031259,-0.108869,0.848421,0.336327,-0.536440,-0.664992,0.052813,0.409033,-0.025654,0.459769,0.210944,-0.268873,-0.390415,-0.761917,-0.050425,0.166259,-0.148125,-0.317425,0.324849,-0.024900,-0.185195,-0.010985,0.259577,0.095265,0.105544,0.270672,0.139739,0.286708,-0.169634,0.486495,-0.102657,0.182590,-0.345413,0.091456,-0.263794,0.151243,0.088283,-0.000561,-0.236557,0.159395,0.493614,0.481192,0.725981,-0.191564,-0.161935,-0.243661,0.238138,-0.011584,-0.268205,0.486230,0.561796,0.265461,0.208756,0.491530,-0.206339,0.260115,0.086805,-0.354063,-0.520928,0.006039,0.154739,-0.191069,-0.431511,0.263722,-0.016344,-0.093197,0.003317,-0.341696,0.214953,0.399364,0.179535,0.497507,-0.430826,0.326503,-0.363185,-0.012641,0.563715,-0.116331,0.403085,0.247759,0.197103,-0.131587,0.264788,-0.237427,-0.256130,-0.221507,0.025724,0.296235,-0.213267,0.311550,-0.476534,-0.030644,-0.089151,-0.371258,0.312624,-0.164448,-0.336993,-0.388579,-0.074027,-0.226184,-0.281260,0.326773,0.104893,0.017076,0.282234,-0.825167,0.311696,0.125589,0.227943,-0.436864,0.375994,0.100161,0.358370,-0.346526,-0.020680,-0.041787,0.137777,0.372020,0.198788,-0.009636,-0.290422,-0.217278,-0.299517,0.126597', '1304665', '1301022', '20514902', '1308755');
