INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27109435', '最后一件外套', '剧情', '亚伯拉罕是一个88岁的犹太裁缝，他准备离开布宜诺斯艾利斯前往波兰，在那里找寻在纳粹占领时期救过他一命的恩人。面对种种困难，在将近70年没有任何关于恩人的消息后，亚伯拉罕还是竭尽一切试图找到他的老朋友，并履行他的承诺：当他们终有一天见面时，亚伯要告诉他精彩的一生', '安吉拉·莫利纳', 'Pablo Solarz', 8.1, 7684, 'tt5991974', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2495690599.jpg', 0.4, 1.4, 18.3, 51.2, 28.7, '-0.070827,0.005162,-0.936166,0.258522,-0.191146,-0.481935,0.697219,-0.555116,-0.803166,-0.438260,0.073383,0.882336,0.202259,0.167359,0.284009,0.013737,-0.305506,-0.669612,0.136081,-0.189468,-0.230586,-0.641800,-0.266614,-0.201842,-0.195710,-0.350759,0.566399,0.258009,0.078216,0.390514,0.188938,-0.007727,0.153733,0.624329,-0.573868,-0.186206,0.099513,0.085837,-0.633565,0.431366,0.132252,-0.266255,-0.303755,0.251374,-0.035146,0.556874,0.197264,-0.185352,-0.409842,0.191694,0.218828,-0.333450,0.059440,0.239780,0.125894,-0.150832,0.105280,0.551568,-0.289764,-0.241243,-0.208959,-0.303294,-0.809415,-0.287499,0.125848,0.190193,-0.790660,0.440591,-0.238450,0.259012,0.190898,-0.581890,0.141330,0.605988,0.020643,0.115811,-0.163258,-0.005074,-0.533117,0.144899,1.097635,-0.190417,-0.023352,0.148544,0.084688,-0.258535,0.242488,-0.144061,-0.436817,0.512941,0.121274,0.100786,-0.373206,0.020062,-0.477544,-0.346936,-0.442685,-0.404497,0.415301,-0.354625,-0.075181,-0.377805,0.012360,-0.257860,-0.321117,0.245388,0.001258,-0.421538,0.688510,-0.884023,0.559269,0.595160,0.586936,-0.528528,0.986547,0.248205,0.159972,-0.370351,0.317665,0.551948,0.105187,0.411815,-0.101353,-0.152015,0.498018,0.034501,-0.430847,0.431734', '25721544', '2990737', '25908042', '1292064');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27109501', '复仇战姬', '动作', '理查德（凯文·詹森斯 Kevin Janssens 饰）、斯坦（文森特·科隆布 Vincent Colombe 饰）和迪米特里（纪尧姆·布谢德 Guillaume Bouchède 饰）每年都要在荒漠中集结，进行打猎活动，今年亦是如此，和往年不同的是，这一次，理查德把自己的情妇珍（玛蒂尔达·鲁茨 Matilda Anna Ingrid Lutz 饰）也带来了。珍是一个风情万种美艳不可方物的女人，她的一举一动都让斯坦和迪米特里感到心里痒痒的。第二天早晨，斯坦终于按捺不住强暴了珍。当珍将这件事情告诉理查德之后，后者非但没有替她主持公道，还将她推下悬崖想要毁灭证据包庇好友。命大的珍并没有死，鬼门关里走了一遭之后，她痛定思痛，决心复仇。©豆瓣', '玛蒂尔达·鲁茨', '科拉莉·法尔雅', 5.9, 13007, 'tt6738136', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2517754729.jpg', 5.5, 22.4, 49, 17.5, 5.5, '0.134960,-0.109268,-0.900881,0.607510,-0.034403,-0.414476,0.619905,0.025525,-0.501340,-0.035904,-0.170614,0.612101,-0.530867,0.098857,0.115193,0.259441,-0.712988,-0.701274,-0.091260,-0.270234,-0.342858,-0.513654,-0.135276,-0.069624,-0.142142,-0.099984,0.211087,-0.066274,-0.063726,0.612039,0.338675,0.462332,0.398318,0.443757,-0.181726,0.082902,0.021461,-0.191229,0.157065,0.141965,0.413982,-0.082179,-0.184154,0.585767,0.165911,0.554983,0.392778,-0.389994,0.274019,-0.167557,0.076506,-0.253722,0.330671,0.262471,0.064143,-0.348316,-0.098563,0.461475,-0.375651,-0.057153,0.300961,-0.095011,-0.800969,0.023430,0.091760,0.021869,-0.562260,0.313913,-0.243832,0.241884,-0.059994,-0.180185,0.236873,0.314123,0.149275,0.107854,-0.044757,-0.213893,-0.614650,0.047953,0.579520,-0.051031,0.227116,0.258920,-0.218230,-0.237208,0.211499,-0.048769,-0.508536,0.091840,0.309943,0.161842,0.051617,0.250411,-0.489367,-0.162183,-0.761357,-0.092573,-0.171796,-0.276456,-0.068357,-0.332524,-0.098036,-0.282009,-0.496019,0.158158,0.046070,-0.204689,0.397077,-0.443814,0.201660,0.400766,0.434177,-0.183260,0.579049,-0.092383,-0.004614,-0.075334,0.003511,0.087677,0.042236,0.308405,0.350191,0.412659,0.192150,-0.322784,-0.361351,0.518433', '1306801', '1309115', '1920730', '30344474');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27109633', '终结者：黑暗命运', '动作', '《终结者2：审判日》发生的27年后，由于未来天网派来T-800成功杀死年幼的约翰，以致令未来产生变化，一个全新进化的液态金属终结者从未来派出，目的是追杀持有关键讯息的丹妮·拉莫斯、半生化人葛蕾丝和她的朋友。这使莎拉·康纳以及成功杀死约翰的T800终结者前来帮助她们一行人，以共同为了人类的未来而战。', '麦肯兹·戴维斯', '蒂姆·米勒', 6.8, 161977, 'tt6450804', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2571762536.jpg', 1, 8.7, 48.3, 34.3, 7.7, '-0.280845,0.088500,-0.383904,0.481267,-0.007557,-0.076746,0.436774,-0.217333,-0.320766,-0.607457,0.381165,0.370473,0.198714,-0.084754,0.517766,-0.402731,-0.135564,-0.334008,-0.093192,-0.000076,-0.649776,-0.492486,-0.567929,-0.463177,0.260254,-0.732979,0.784473,-0.135126,-0.265377,0.456227,0.270411,0.747915,-0.294949,0.172840,0.207143,-0.185811,0.367498,0.021869,-0.640703,0.388782,-0.301133,0.036200,0.193924,0.227750,-0.472646,0.353871,0.643021,-0.731056,-0.045295,-0.635284,0.408754,-0.560249,0.081548,-0.083945,0.503421,0.265392,-0.026947,0.415066,0.006116,0.058436,0.042698,-0.024070,-1.277518,-0.211140,0.045010,-0.080634,-0.235608,0.132908,-0.110598,0.038040,0.502715,-0.279641,0.148496,0.902599,0.343744,0.287444,-0.276609,0.171318,-0.482625,-0.204130,0.918781,-0.309818,-0.538687,0.088563,-0.130487,-0.308027,-0.065473,-0.293018,-0.276874,0.248560,0.229836,0.481117,0.143203,0.522573,-0.724020,-0.260451,-0.482358,-0.131950,0.544997,-0.262074,0.138082,-0.580684,-0.148610,-0.120067,-0.363420,-0.268397,-0.131525,-0.455069,0.804354,-0.561940,0.351539,0.582916,0.432336,-0.668622,0.625701,0.036331,0.381058,-0.494133,-0.253545,0.282605,0.223587,0.223999,-0.281146,-0.008301,0.111821,0.072452,-0.306791,0.197200', '26678784', '35377026', '1811755', '27009869');
