INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27110296', '无名之辈', '剧情', '来自乡村的笨贼眼镜（章宇 饰）和大头（潘斌龙 饰）抢了一家手机店，慌乱之中逃进坐着轮椅的单身女子嘉旗（任素汐 饰）的家中。嘉旗早已失去活着的欲望，她强横地要求俩笨贼杀死自己。另一边，某楼盘老板资金链断裂跑路，留下保安马先勇（陈建斌 饰）与讨债者周旋。马曾经是立功无数的协警，可就在转正的关头因为一场车祸毁了原本看似美好的一切。不久前他挖到一把喷子，原本打算交给当初的警察好友立功，却发现喷子被换成了水枪。而成为了新闻的手机抢劫案，让马先勇意识到喷子正在劫匪的手上。漫长的一天，所有与之相关的老老少少都在纠结煎熬。他们是渺小的无名之辈，却真真切切感受到来自命运的重压……©豆瓣', '陈建斌', '饶晓志', 8, 972815, 'tt9282616', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2539661066.jpg', 0.5, 2.7, 20.6, 47.6, 28.6, '0.214770,0.003447,-0.591714,0.280562,-0.320758,-0.287888,0.802144,0.089283,-0.371351,-0.196902,0.373575,0.459513,-0.130690,0.291884,0.325548,-0.038333,0.035547,-0.756826,-0.130235,0.125361,-0.299102,-0.281604,-0.258085,-0.132847,-0.119533,-0.101472,0.641681,0.336905,-0.191107,0.441562,0.202691,0.135259,-0.350297,0.543916,-0.275110,0.060143,0.009429,-0.100567,-0.114161,0.022380,-0.000876,-0.401170,-0.045220,0.226002,-0.005256,0.300419,0.669974,-0.221161,-0.128887,0.139607,0.348029,-0.315837,-0.195788,-0.008290,0.338799,0.026555,0.165030,-0.059807,-0.205577,-0.020796,0.357856,0.075803,-0.643850,-0.066440,-0.132268,0.226017,-0.632965,0.470585,-0.000536,0.137124,0.112692,-0.212626,0.322252,0.008035,0.042433,0.501026,-0.141458,-0.125686,-0.619353,0.222186,0.607868,-0.107374,-0.024561,0.234876,0.065014,-0.283358,-0.041721,-0.088198,-0.415955,-0.044057,0.526025,0.102650,-0.275161,0.200552,-0.512583,0.134032,-0.182322,0.004052,0.030348,-0.490463,-0.274089,-0.367218,-0.110880,-0.216646,-0.133249,0.334899,0.121608,-0.190593,0.456813,-0.500396,0.061500,0.486744,0.156735,-0.336924,0.491069,-0.182804,0.053823,-0.067175,-0.117506,0.039657,0.175898,0.593492,0.310135,0.066226,-0.277468,-0.189128,-0.306222,0.432336', '21619567', '26342391', '1428054', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27110314', '圣何塞谋杀案', '爱情', '故事由女子Yanny（蔡卓妍 饰）为了逃避自己在香港的失败恋情，前往美国探望多年不见的女友Ling（郑秀文 饰）展开。Ling与丈夫Tang（佟大为 饰）在圣荷西过着仿佛宁静无忧的理想生活。但就在短短五天的探访中，Yanny竟揭发了这对夫妇背后隐藏的身份真相。三个人各自有着不可告人的历史，更重演着一场凶案的轨迹，冲向你死我亡的结局。异乡人的美国梦，孤寂与怀疑累积成沉重的代价。', '郑秀文', '潘源良', 4.6, 8024, 'tt7271190', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2619633802.jpg', 15.4, 46.4, 32.5, 4.5, 1.2, '-0.174602,-0.008737,-0.704504,0.708209,0.017406,-0.071350,0.917147,0.032810,-0.454924,-0.407414,0.309515,0.816178,-0.174350,0.164918,0.443034,-0.215162,-0.138474,-0.819878,-0.182335,-0.232268,-0.013757,-0.469738,-0.239905,-0.459099,-0.017974,-0.296672,0.652674,0.356601,-0.198167,0.417878,0.603051,0.294075,-0.632218,0.218309,-0.055890,-0.061205,-0.196119,0.493457,-0.632062,0.073117,0.200313,-0.407253,-0.122437,0.161983,-0.347630,0.138613,0.840815,-0.419725,-0.210765,-0.063960,0.228225,-0.395911,-0.340212,0.137555,0.255905,-0.039910,0.194512,0.703701,-0.268003,-0.026258,0.078478,-0.143396,-0.858751,0.069893,0.254191,0.329587,-0.509269,0.643874,-0.103504,0.067040,0.068753,-0.232567,0.320386,0.673435,0.323205,0.271407,-0.198638,-0.147717,-0.599738,0.367443,0.877549,0.091458,-0.032190,0.241309,-0.300471,-0.214427,-0.213507,-0.172912,-0.430203,0.072867,0.184753,-0.063787,-0.233159,0.491884,-0.676189,0.083105,-0.219858,0.028200,-0.145278,-0.621151,0.092495,-0.445077,-0.242676,-0.553695,-0.323163,0.057454,0.016231,-0.431651,0.440008,-0.710368,0.332759,0.363354,0.139193,-0.596936,0.557935,0.303276,0.077784,-0.383528,-0.002601,0.419029,-0.294271,0.044892,-0.120503,0.011722,-0.057504,0.131597,-0.636809,0.506860', '25828589', '26678784', '25721544', '27062637');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27110363', '名侦探柯南：零的执行人', '动画', '东京峰会召开在即，为了确保会议顺利进行，日本警方出动约两万名警力对位于东京湾的超大设施“海洋边缘”进行安保工作。可就在严密的防控下，此地已然发生了爆炸案。令柯南（高山南 配音）等人始料未及的是，现场居然留下了对毛利小五郎（小山力也 配音）极其不利的证据。在此之后，小五郎 遭到逮捕。柯南则发现安室透曾出现在爆炸现场，并且负了伤。为了还毛利叔叔的清白，柯南和阿笠博士以及少年侦探团的小伙伴们联合起来勘察现场，搜集证据。随着调查的深入，柯南发现这起爆炸案隐藏着包括恐怖分子、公安在内多方的复杂关系，而真相更令所有人瞠目结舌……本片是“名侦探柯南系列”第22部动画剧场版，票房总收入超过90亿日元。©豆瓣', '高山南', '立川让', 5.7, 112466, 'tt7880466', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2537694239.jpg', 5.6, 26.9, 49.5, 13.1, 4.9, '-0.113829,-0.244577,-0.717843,0.167743,0.279043,0.158750,0.179177,0.009834,-0.535566,-0.304585,0.353482,0.356699,-0.391654,-0.100684,0.055726,-0.274776,-0.609950,-0.772241,-0.418619,-0.213910,-0.031961,-0.548377,-0.073927,-0.028816,0.091172,-0.319257,0.337370,0.257725,-0.255178,0.331102,0.070834,0.273460,-0.481189,0.320485,0.411549,-0.045428,0.352982,-0.283342,-0.312502,0.261224,-0.226833,-0.258045,0.013162,-0.114300,0.135669,0.499807,0.685478,0.057847,-0.445236,0.032285,0.434285,-0.380586,-0.061194,0.081208,0.818469,0.218100,0.038627,0.425385,-0.349201,0.099784,-0.000209,-0.032587,-0.832611,0.004164,0.264009,0.314775,-0.097996,0.236829,-0.284753,0.055918,0.268014,-0.111437,0.229658,0.442421,0.269023,0.051217,-0.019799,0.236407,-0.255273,0.014463,0.433995,-0.078525,0.000973,-0.069376,0.001353,-0.466121,-0.410327,-0.113163,0.081171,0.288837,0.109086,-0.099389,0.062035,0.064779,-0.483261,-0.196427,-0.242321,-0.634992,-0.217511,-0.074227,-0.009312,-1.086676,0.069183,0.019864,-0.187579,0.150317,0.149146,-0.333526,0.572586,-0.506644,-0.087717,0.626004,0.354518,-0.343689,0.162379,0.080122,-0.156143,-0.028596,-0.352328,-0.180296,0.310530,0.658026,0.177257,0.013088,-0.103300,-0.617128,-0.300182,-0.172990', '3003137', '25723905', '6984051', '3387546');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27110448', '告诉蜜蜂', '剧情', '故事发生在20世纪50年代的英格兰，莉迪亚（荷丽黛·格兰杰 Holliday Grainger 饰）是生活在那里的一位非常平凡的主妇，在遭到丈夫的无情抛弃后，莉迪亚无奈之下和儿子查理开始了相依为命的拮据生活。因为家庭的原因，查理在学校里饱受欺凌，母子两人生活屡屡走入绝境。正当两人最绝望的时候，一位名为简（安娜·帕奎因 Anna Paquin 饰）的女医生搬到了莉迪亚家隔壁。简温柔而又善良，她不仅治好了查理的伤，还在莉迪亚和查理险些遭遇流落街头的命运的时候向两人敞开了家里的大门。就这样，莉迪亚住进了简的家，随着时间的推移，两人之间产生了别样的感情，与此同时，有关两人的流言蜚语在小小的村庄里疯狂的传播着。©豆瓣', '安娜·帕奎因', '安娜贝尔·杨科尔', 7.5, 8579, 'tt7241926', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2550440855.jpg', 0.5, 3.4, 32.4, 45.6, 18.1, '0.315000,-0.019974,-0.770120,0.535756,-0.147255,-0.312451,1.101748,0.246169,-0.614187,-0.261508,0.026418,0.791899,-0.292067,0.523212,0.503351,-0.079044,-0.203625,-0.828927,-0.253721,-0.246934,-0.408823,-0.436644,-0.111718,-0.409077,-0.147816,-0.328033,0.438430,0.135949,-0.406585,0.360783,0.073243,0.412836,-0.330004,0.479140,-0.321215,0.203980,0.044042,0.199088,-0.312623,-0.006371,0.213716,-0.293810,-0.097157,0.073608,0.092204,0.189792,0.879125,-0.325748,-0.041744,-0.166418,0.307770,0.019671,-0.225567,0.139510,0.504551,-0.080294,0.309900,0.187112,-0.236263,-0.024072,0.224454,-0.117033,-0.610959,0.152047,0.016299,0.196842,-0.651603,0.703960,0.120111,-0.117087,0.162564,-0.476863,0.451984,0.383555,0.268124,0.606452,-0.319138,-0.096787,-0.494118,0.036800,0.786445,0.057662,-0.216654,0.356290,-0.472816,-0.178530,-0.080945,-0.016604,-0.850497,-0.281419,0.407390,0.153511,-0.367999,0.595202,-0.537717,0.082165,-0.190755,-0.105596,0.133472,-0.446137,-0.215216,-0.842300,-0.209194,-0.799137,-0.461476,0.162524,-0.176730,-0.187239,0.707613,-0.815008,0.385308,0.245140,0.357627,-0.292080,0.738574,0.090573,0.369789,0.072026,-0.056042,0.512382,-0.103475,0.242394,0.291545,0.327346,-0.421003,0.075191,-0.211057,0.799325', '24639908', '1296534', '26687241', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27113517', '血观音', '剧情', '《血观音》描述在女人组成的棠府里，住着3位不同世代但一样懂人心的女性，由棠夫人（惠英红饰）主持大局，穿梭权贵间，靠着高超手腕与柔软身段，在复杂的政商关系中生存取利；个性如刺猬般的大女儿棠宁（吴可熙饰）为求母亲肯定，勉力配合；乖巧的小女儿棠真（文淇饰）多半静静观察，唯母命是从。直到某天，棠家亲密友人惨遭灭门事件爆发，三人各自被牵扯其中，一向以大局为重的棠夫人，为了守护一切，费尽心机，却让三人走向不同的命运。', '惠英红', '杨雅喆', 8.5, 373435, 'tt7479784', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2505008756.jpg', 0.2, 0.9, 12.1, 47.7, 39.1, '0.139319,0.167869,-0.607137,0.440461,0.079796,0.105902,0.326266,0.286347,-0.564135,-0.310235,0.369398,0.484343,-0.115875,0.028427,-0.039485,-0.261152,0.153997,-0.738250,-0.577526,-0.023752,0.030371,-0.426290,-0.068480,0.146995,-0.133583,-0.321565,0.330667,-0.097088,-0.199332,0.211762,-0.033601,0.347681,-0.666138,-0.066493,-0.186090,-0.507102,-0.385117,0.130352,-0.421361,-0.118254,0.045830,-0.225926,-0.212862,-0.031756,0.066250,0.394392,0.721484,-0.993894,-0.099596,-0.214977,0.178492,0.060214,-0.262308,0.261764,0.301016,0.070322,0.451749,0.287931,0.019858,-0.030802,0.243091,-0.081861,-0.625426,-0.168578,0.460396,0.324352,-0.601827,0.275287,0.153084,-0.229445,-0.184302,-0.468571,0.459664,0.062832,0.192247,0.092920,-0.283940,0.199235,-0.248098,-0.077827,0.743619,0.391948,-0.191108,0.243425,-0.365673,-0.121374,0.194106,-0.331862,-0.562723,-0.100469,0.049402,-0.075638,0.229051,0.491353,-0.113226,-0.055980,-0.149880,0.349717,0.032971,-0.583941,0.050554,-0.409013,-0.303834,-0.508222,0.065292,0.187874,0.125466,-0.331384,0.729997,-0.671492,-0.119451,0.123236,0.198938,-0.435415,0.528369,-0.204183,0.540402,-0.042150,-0.505376,0.135945,0.030690,-0.148610,0.015470,0.232941,-0.463218,0.050383,-0.197276,0.050996', '4127270', '1877596', '26730542', '1309161');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27113810', '暗数杀人', '剧情', '影片故事讲述一个变态杀人狂（朱智勋 饰）藏匿了7起杀人案，他将和调查这些案件的刑警（金允石 饰）展开正面交锋。', '金允石', '金泰均', 6.8, 15735, 'tt8119680', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2533909043.jpg', 0.6, 6.6, 51.9, 32.4, 8.6, '0.336870,-0.651803,0.006759,0.679651,-0.017257,0.281117,1.087726,-0.097136,-0.294587,-0.396993,0.261175,0.448880,-0.552456,-0.386417,-0.052355,-0.284657,-0.351194,-1.170721,-0.077654,-0.013167,0.023808,-0.682081,-0.348753,-0.235941,0.193959,0.070336,0.403002,-0.128861,-0.557111,0.313348,0.728617,0.435015,-0.605943,-0.106850,-0.172319,-0.011662,0.031610,0.148280,-0.244253,0.299694,-0.000244,-0.360810,0.025578,0.277880,-0.089397,0.351286,1.184676,-0.610426,-0.351800,-0.352019,0.715020,-0.592212,-0.230419,0.119408,0.393605,0.782686,0.155700,0.562892,-0.129045,-0.090149,-0.033495,0.015258,-0.847053,-0.239453,0.176570,0.427837,-0.533364,-0.399819,-0.367523,0.427065,0.013934,-0.096819,0.248910,0.212688,0.612815,-0.126328,0.252152,-0.177138,-0.418316,0.826201,0.129347,-0.179404,0.166302,0.242172,0.304317,-0.737181,-0.710283,0.303567,-0.233159,0.113994,0.463940,-0.815054,-0.050437,0.324028,-0.524020,-0.509525,-0.015002,-0.070138,-0.066502,-0.249199,-0.229674,-0.857209,-0.445439,0.070661,-0.631837,-0.248090,-0.123750,-0.331782,0.559433,-0.403805,-0.151505,1.060688,-0.094860,-0.460396,-0.056750,0.012986,0.154318,-0.320681,0.052754,0.235437,0.217777,0.204051,0.350643,0.681117,-0.150025,-0.330575,-0.633681,0.088295', '1467779', '4135443', '1298197', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27114240', '冒牌上尉', '剧情', '德国二战题材影片。影片根据真实故事改编，讲述了一名十九岁的普通国防兵威利赫罗德在二战最后两周内成为所谓的“埃姆斯兰德刽子手”的故事。他凭借捡到的上尉制服而假冒军官，将溃散的其他士兵聚集起来组成特别任务小组，一路抢掠地在行将陷落的纳粹帝国大地上为所欲为，并以元首为榜样掌握起逮捕和生杀大权。该片获得了去年圣塞巴斯蒂安国际电影节的最佳摄影奖。', '麦克斯·胡巴赫', '罗伯特·斯文克', 8.6, 71593, 'tt6763252', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2516702580.jpg', 0.2, 0.5, 9.4, 48.9, 41, '0.149656,0.027722,-0.495498,0.691228,0.178067,-0.117898,0.438553,-0.098227,-0.265138,-0.214562,0.468054,0.863812,0.003940,-0.297998,0.522360,-0.079317,-0.512773,-0.804927,-0.478971,-0.188902,-0.171156,-0.564718,-0.438305,-0.189772,-0.333161,-0.499845,1.004327,0.027851,-0.446722,0.307828,0.437650,0.083522,0.101608,-0.133906,-0.142586,-0.050610,0.206901,-0.310220,-0.432267,0.405912,-0.268685,-0.165858,-0.203638,-0.025975,-0.001154,0.171229,0.784408,-0.498598,0.209921,-0.270101,0.562185,-0.483128,-0.184883,-0.247566,0.410700,0.466221,0.091866,0.241020,0.154476,0.289910,-0.092302,-0.196903,-0.640771,-0.290279,0.154626,0.142251,-0.429983,0.333223,-0.204245,0.148121,0.201790,-0.259694,0.031127,0.509185,-0.014926,0.352682,-0.048264,-0.011289,-0.710534,0.581069,0.478531,-0.166964,-0.437906,-0.063422,0.009239,-0.468220,-0.125277,-0.563815,-0.001427,-0.058432,0.159756,-0.110282,0.210870,0.422296,-0.617281,0.052596,-0.177365,-0.471282,0.036067,-0.264897,-0.058786,-0.829699,0.061586,0.122652,-0.055291,-0.007770,0.159406,-0.127653,0.998783,-0.517778,0.176457,0.586406,0.297233,-0.097333,0.203525,0.196918,0.297345,-0.334799,-0.422046,0.251353,0.200107,0.546742,0.110368,0.197373,-0.467663,-0.510136,-0.472656,0.370809', '25880986', '25863940', '27602116', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27114416', '廉政风云', '剧情', '经过多年的追查，香港廉政公署准备对理达贸易集团负责人陈超群以及海关官员钟嘉玲（袁咏仪 饰）就非法内销行贿行为进行起诉。可是在开庭前夕，作为举报人和证人的理达的前任财务总监许植尧（张家辉 饰）临时改变出庭打算，启程前往澳洲。法庭给出七天限期，为此，该案负责人陈敬慈（刘青云 饰）和同在廉政公署供职的妻子江雪儿（林嘉欣 饰）联合展开调查。陈倾尽全力追查陈超群走私行贿的实证，并试图揪出其背后的大老虎。江雪儿则远赴澳洲，力劝许植尧回港作证。短短的七天，一切争分夺秒，而在这一过程中，更多的真相交替浮现水面……©豆瓣', '刘青云', '麦兆辉', 5.4, 93271, 'tt9575160', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554020294.jpg', 5.3, 34.7, 48.6, 9.4, 2, '-0.243043,0.001383,-0.686181,0.636357,0.236698,-0.074384,0.280230,-0.050491,-0.462838,-0.496698,-0.092574,0.328808,-0.218287,0.168610,0.320464,-0.329162,-0.325704,-0.672130,-0.090133,-0.097315,-0.324759,-0.824042,0.022614,-0.499926,-0.119096,0.331379,0.535379,0.374755,-0.218791,0.322453,0.468804,-0.038108,-0.431244,0.287297,0.163981,-0.333079,0.184582,0.231011,-0.605808,0.116378,0.453491,-0.618436,0.012669,-0.219274,0.436183,0.443172,0.373353,-0.025744,-0.209099,-0.086706,0.331417,-0.540055,0.130210,-0.092207,0.561265,0.227713,-0.080535,0.607184,-0.646913,-0.288635,-0.013522,-0.351610,-0.697816,-0.154552,0.234625,0.033912,-0.380854,-0.152058,-0.426878,0.343316,0.053389,-0.360038,-0.043232,0.666432,-0.024468,0.090929,0.187765,0.157522,-0.410508,0.547008,0.392013,0.278712,-0.032226,-0.395984,0.169152,-0.518490,-0.006905,0.058780,0.277142,-0.095134,0.225492,-0.133309,0.191447,0.053837,-0.221615,-0.319920,-0.311081,-0.183150,0.129801,-0.008343,0.058260,-0.834517,0.128978,-0.235511,-0.020487,0.274485,0.362998,-0.142035,0.113105,-0.648528,0.206213,0.169297,0.398591,-0.862711,0.356854,0.193774,0.359845,-0.499020,-0.096331,-0.056348,0.404621,0.351938,0.217829,-0.030706,0.056992,-0.222670,-0.336545,-0.115437', '26996640', '26934399', '1299250', '3006781');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27114417', '祖宗十九代', '喜剧', '一个在现实中失意的青年作家小贝（岳云鹏 饰），在现实碰壁而低落的夜晚，经历穿越20世纪初拯救陷入帮派麻烦的祖先、清朝和参加科举考试的先祖共事、明朝与祖先共同御敌、晋朝和祖先一起救世济人、上古与女娲和夸父探讨生命的本源和意义的奇幻旅程。一路见证爱情、收获自信和担当，经历人性的转变而自我成长，奇幻之旅实则他的新书发布，这本书献给他未见过的母亲和祖辈们。', '岳云鹏', '郭德纲', 4.2, 110786, 'tt8443556', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2511436594.jpg', 31.1, 37.4, 23.4, 4.5, 3.5, '0.308729,0.120120,-0.595103,0.814834,0.122553,-0.236923,0.756583,-0.175203,-0.525594,-0.323371,0.071125,0.911508,-0.021055,0.235039,0.675844,-0.437230,-0.449664,-0.643553,0.095983,0.229521,-0.184446,-0.296669,-0.322358,-0.013996,-0.297521,-0.565207,1.102760,0.336789,-0.136363,1.095842,0.119614,0.109532,-0.428268,0.254196,-0.428564,-0.066653,-0.064191,0.796375,-0.698463,-0.146964,-0.088372,-0.292771,-0.249574,0.284263,-0.201790,0.015271,0.340344,-0.532824,-0.068360,-0.203531,0.589853,-0.236803,-0.418368,0.035544,0.253490,0.391894,0.274898,0.599529,0.508981,-0.119759,-0.372446,-0.409730,-1.083904,-0.265826,0.260197,0.138463,-0.552392,0.542804,0.313671,-0.022985,0.001688,-0.125587,0.402973,0.532647,0.496727,0.663637,-0.221558,-0.113000,-0.218759,0.565922,0.782739,-0.522985,-0.386641,0.268430,-0.058770,-0.626508,-0.093714,-0.299259,-0.631173,0.270838,-0.100081,0.014993,-0.234389,0.615330,-1.194866,0.299716,-0.111952,-0.094273,0.306972,-0.267772,-0.108449,-0.574957,-0.445835,-0.586350,-0.298639,-0.077721,0.355274,-0.511507,1.103407,-0.758987,0.282008,0.318764,0.364454,-0.704933,1.200257,0.292210,0.155540,-0.593099,0.086880,0.470674,-0.430791,0.180835,-0.357648,0.104263,0.041486,0.434078,-0.569932,0.550017', '1292206', '26647163', '25880986', '27602116');
