INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27115166', '好小子们', '喜剧', '麦斯（雅各布·特瑞布雷 Jacob Tremblay 饰）、托尔（布雷迪·诺恩 Brady Noon 饰）和卢卡斯（基思·L·威廉姆斯 Keith L. Williams 饰）是三个青春懵懂的男孩，三人从很小的时候起就在一起玩了，是感情十分要好的青梅竹马的玩伴。一天，麦斯以外的收到了邻家酷男孩的邀请，邀请三人去参加“亲吻派对”，这三个连女孩子的手都没有摸过的男孩，决定去弄清楚究竟应该怎样接吻。三个孩子将研究对象的目标放在了邻居姐姐的身上，因为她会在家里和男友亲热。一行人偷偷拿了麦斯爸爸的无人机，利用无人机潜入了邻居家中。结果当然只有一个，那就是阴谋败露，不仅如此，昂贵的无人机还被弄坏了，这下可急坏了三个男孩。©豆瓣', '雅各布·特伦布莱', '吉恩·斯图普尼兹基', 7.2, 22192, 'tt6977338', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2550223943.jpg', 0.8, 5.7, 38.7, 40.8, 14, '0.496410,-0.293075,-0.603137,0.490258,-0.369907,-0.457770,0.695647,0.060807,-0.388296,-0.156450,-0.068516,0.655794,-0.155583,0.394893,0.211030,0.158237,-0.242678,-0.717003,-0.130654,-0.120139,-0.502507,-0.599244,-0.125228,0.024906,0.142953,-0.313671,0.240247,-0.353179,0.019061,0.402003,0.598268,-0.047566,-0.284282,0.380901,-0.422912,-0.029110,0.199660,-0.064584,-0.068629,0.522117,0.109805,-0.040531,0.144637,0.112624,0.134337,0.463235,0.669850,-0.240609,0.111675,0.014610,0.020735,0.002735,-0.186101,0.185093,0.375742,-0.246027,0.278146,-0.139589,-0.166631,0.034192,0.349083,-0.025029,-0.426081,0.145267,0.147613,0.049081,-0.929912,0.527704,-0.108681,-0.182341,0.220318,-0.446319,0.478061,0.431158,-0.117318,0.376049,-0.067702,-0.064842,-0.544351,0.095669,0.487478,-0.082120,0.255946,0.436558,-0.092072,-0.251178,-0.003434,-0.179241,-0.519548,0.256565,0.500102,-0.114291,-0.268966,-0.097393,-0.729009,-0.057098,-0.226516,-0.232532,0.027043,-0.650412,-0.033304,-0.543102,0.034080,-0.437076,-0.356732,0.174666,-0.048233,-0.214318,0.771904,-0.889381,0.172110,0.582854,0.211073,-0.285203,0.588698,0.214420,0.005079,-0.243909,0.050073,-0.176838,0.254791,-0.042785,0.211470,0.601819,0.102798,-0.304935,-0.415108,0.410234', '1292219', '3155839', '1299965', '21360412');
