INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27119586', '谁先爱上他的', '剧情', '宋正远（陈如山 饰）因为癌症去世了，留下了老婆刘三莲（谢盈萱 饰）独自拉扯着儿子宋呈希（黄圣球 饰）。让刘三莲无法原谅的是，宋正远人生的最后一段旅程是和一个名叫高裕杰（邱泽 饰）的男人一起度过的。高裕杰是宋正远从前的恋人，只不过最终宋正远选择了结婚生子去过正常人的生活，而高裕杰则对他一直恋恋不忘。更让刘三莲无法忍受的是，宋正远竟然将自己的保险金全部留给了高裕杰，不仅如此，自己叛逆的儿子竟然也选择了抛弃自己，赖在高裕杰的家里不肯走，这个男人到底是有什么魔力？！在宋呈希的眼中，高裕杰是一个吊儿郎当的男人，他沉默着凝视着这个男人，仿佛想要从他的身上看到另一个熟悉的身影。©豆瓣', '邱泽', '徐誉庭', 8.6, 365840, 'tt8443704', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2546961193.jpg', 0.4, 0.8, 10.3, 44.3, 44.2, '0.241060,-0.174140,-0.693429,0.862282,-0.558962,-0.408950,1.038213,0.100444,-0.422956,-0.260294,0.126215,0.937451,0.076845,0.556361,0.096001,0.239965,0.028476,-0.770802,-0.274348,-0.003651,-0.547708,-0.617747,-0.082498,0.000648,-0.094451,-0.034285,0.827379,0.002893,0.001623,0.316651,0.597028,0.106838,-0.067562,0.723298,-0.514726,0.125610,-0.184540,0.109731,0.004125,0.145380,0.248623,-0.393507,0.057173,0.473487,-0.194531,0.334047,0.655550,-0.213590,-0.104135,0.027413,0.339902,-0.268744,-0.220210,0.229258,-0.043088,-0.249305,0.325289,0.147827,-0.228596,-0.166198,0.338866,0.175947,-0.778724,-0.029772,0.127319,0.210985,-0.944417,0.598953,-0.092184,-0.204262,0.179839,-0.366787,0.469342,0.357175,0.139674,0.483470,-0.402145,0.026802,-0.671617,0.144636,0.567581,0.103721,-0.184132,0.597942,-0.328622,-0.262142,-0.194622,-0.105376,-0.727036,-0.055258,-0.010225,0.301827,-0.421361,0.038463,-0.423771,0.034564,0.025124,-0.048526,0.154223,-0.670326,-0.302895,0.039884,-0.147119,-0.667699,-0.472368,0.399562,-0.183887,-0.409816,0.597456,-0.834980,0.132603,0.513259,0.450146,-0.606123,0.974801,0.295824,0.052421,-0.137706,0.252106,0.286959,-0.115186,0.021190,0.196314,0.413363,0.078214,0.044971,-0.495236,0.685303', '26884422', '1456503', '1302384', '1306916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27119724', '小丑', '剧情', '湿冷无望的哥谭市，卑微的亚瑟·弗兰克（华金·菲尼克斯 Joaquin Phoenix 饰）依靠扮演小丑赚取营生。与之相依为命的母亲患有精神疾病，而亚瑟深记母亲的教诲，无论遭受怎样的挫折都笑对人生，却因此让自己背负着莫大的压力，濒临崩溃。他梦想成为一名脱口秀演员，怎奈生活一次次将失望狠狠地砸在他的头上。不仅如此，他因意外丢掉了工作，偶然瞥见母亲的秘密，又使他心中燃起对那个与之地位悬殊却从未谋面的父亲的殷切渴望。命运习惯了事与愿违，空荡荡的地铁内，悲伤的小丑在无法自已的癫狂笑声中大开杀戒……本片荣获第76届威尼斯电影节金狮奖。©豆瓣', '华金·菲尼克斯', '托德·菲利普斯', 8.7, 939301, 'tt7286456', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2567198874.jpg', 0.6, 1.2, 10.2, 37.9, 50.1, '-0.141355,0.178622,-0.734814,0.579775,-0.133047,-0.339009,0.926416,0.284944,-0.451242,-0.047088,0.537329,0.938147,-0.060489,0.338547,0.009987,-0.204355,0.047437,-0.904970,-0.031874,-0.070975,0.131279,-0.240387,-0.544566,-0.067294,-0.290464,-0.274610,0.725244,0.115290,-0.264214,0.453081,0.405045,0.524076,0.029418,0.677188,-0.260087,-0.016186,0.052223,0.215241,-0.201633,-0.147124,0.212799,-0.424185,0.016325,0.419850,-0.209078,0.326694,0.704613,-0.353865,-0.107088,-0.249525,0.441824,-0.295080,-0.001468,0.402765,-0.004966,0.015145,-0.123143,0.025467,-0.039994,0.012207,0.160705,0.059794,-0.960160,-0.111929,0.132355,0.276433,-0.714256,0.500048,-0.078668,0.079535,0.077269,-0.054102,0.058594,0.147801,0.360580,0.530281,-0.465612,0.145640,-0.155555,0.203700,0.717837,-0.188516,-0.385435,0.289538,-0.569153,-0.244508,0.188920,-0.484763,-0.844289,-0.138416,0.309966,0.134701,-0.082240,0.512963,-0.296304,0.006372,-0.107546,-0.135834,-0.244973,-0.442853,-0.093444,-0.337792,-0.136215,-0.298616,-0.281096,-0.105784,0.179312,-0.511529,0.533661,-0.607403,0.475437,0.483284,0.195365,-0.368553,0.592100,0.288058,0.134231,-0.113619,-0.205235,0.720121,-0.330726,0.267504,-0.022369,-0.057904,-0.223035,0.161959,-0.402926,0.696619', '25828589', '34890458', '25763555', '1303034');
