INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27124695', '智齿', '悬疑', '《智齿》改编自雷米小说。讲述从学堂毕业的任凯，因一宗连环凶杀案，与刚复职的展哥开始搭档。案子破不了反倒引发连串事故，展哥重遇杀妻儿的街童王桃，被激发的恨意一发不可收拾；任凯大意失枪，误被凶手所获。凶手潜伏在城市之中，危机逐步逼近。', '林家栋', '郑保瑞', 7.2, 44017, 'tt14032696', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2706359781.jpg', 0.5, 4.4, 37.5, 48.2, 9.3, '0.229235,-0.309650,-0.375632,0.053724,0.213852,0.161589,0.564389,-0.007409,-0.142539,-0.116603,0.256296,0.304153,-0.529929,-0.018493,-0.108772,-0.506895,0.122607,-0.721816,0.100858,-0.172385,-0.200455,-0.371380,0.097665,-0.049100,-0.015281,-0.237091,0.570348,0.388068,-0.502233,0.390047,0.033178,0.632031,-0.364740,0.326802,0.078561,0.158940,-0.044802,0.014109,-0.243330,0.410666,0.168732,-0.599924,0.042280,0.175876,-0.179806,0.395480,0.822286,0.159648,0.050911,-0.357757,0.522856,-0.161297,-0.166921,0.223962,0.784573,0.170577,-0.117738,0.395306,-0.173702,-0.139439,0.017360,-0.265609,-0.424300,-0.078504,0.249352,-0.228704,-0.334391,0.058552,-0.391098,0.175116,0.074266,-0.186666,0.129073,0.455122,0.441206,0.256452,-0.419513,0.112467,-0.359388,0.058211,0.538307,-0.732994,-0.077878,0.224196,0.597392,-0.192193,-0.076000,-0.112358,-0.242309,0.154584,0.692926,0.075146,-0.346385,0.762425,-0.133322,-0.259551,-0.462808,-0.056883,-0.201061,-0.008097,-0.398603,-0.119728,-0.385338,0.460500,-0.073229,0.077212,0.087380,-0.049431,0.066031,-0.384531,0.435935,0.479659,-0.184093,-0.395038,-0.000537,0.067163,0.074046,-0.309681,-0.132411,0.297761,0.242846,0.623725,0.265768,0.110372,-0.135575,-0.387694,-0.143911,0.218086', '26974334', '3531406', '30249076', '3148064');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27125208', '欢迎来北方II', '剧情', '瓦伦丁（丹尼·伯恩 Dany Boon 饰）是当今巴黎最为炙手可热的设计师，实际上，他出生于一个非常偏僻的小镇里，并且原生家庭的经济条件十分堪忧，全靠着父母坚韧的精神支撑着瓦伦丁前往大都市打拼，才成就了他的今天。可是，瓦伦丁却将自己的出身视为是难以启齿的秘密，为了摆脱原生家庭，瓦伦丁甚至捏造了自己的履历，声称自己是孤儿。让瓦伦丁没有想到的是，某一天，一直待在老家的母亲竟然决定来巴黎探亲，这也就意味着，瓦伦丁的身世之谜即将曝光。与此同时，一场意外让瓦伦丁失去了记忆，使得他忘记了自己一直苦心联系的城里口音，乡音一展无余。©豆瓣', '丹尼·伯恩', '丹尼·伯恩', 6.7, 5267, 'tt6859418', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2555472985.jpg', 0.8, 8.1, 52.2, 31.5, 7.4, '0.141550,0.066226,-0.802051,0.560340,-0.247053,-0.253244,0.431482,0.087148,-0.800079,-0.435796,0.147923,0.883737,0.096440,0.276126,0.256010,0.301841,-0.114038,-0.527960,0.051497,-0.231370,-0.172038,-0.534281,-0.427092,-0.059764,-0.198864,-0.315793,0.538736,0.184709,-0.389180,0.177122,0.048428,0.320076,0.052344,0.437039,-0.296761,0.074411,0.078688,0.026110,-0.156611,0.187416,0.092235,-0.331086,0.002966,0.497660,0.050354,0.414668,0.395353,-0.158943,-0.224605,-0.099786,0.318259,-0.193890,-0.175049,0.066134,0.304557,-0.212590,0.242004,0.441527,-0.428124,-0.070160,0.302861,-0.153248,-0.968484,0.007890,0.333193,0.027521,-0.776076,0.445302,-0.118845,-0.381646,-0.067016,-0.469240,0.296356,0.492684,0.146659,0.302702,-0.037414,0.087020,-0.446508,0.143512,0.803785,-0.133376,-0.339244,0.403028,-0.307212,-0.278275,-0.041060,-0.256566,-0.446185,0.014226,0.042834,0.165770,-0.103373,0.276716,-0.368738,0.077275,-0.333699,-0.165415,0.143647,-0.324677,-0.037434,-0.220997,-0.160981,-0.303520,-0.248865,-0.121533,0.044601,-0.229473,0.718400,-0.880835,0.142265,0.594993,0.054558,-0.618010,0.582851,0.134560,0.249200,-0.176151,0.036809,0.355841,-0.017704,0.269112,-0.151658,0.075669,0.036798,-0.393528,-0.186539,0.787972', '1793491', '30163500', '34968329', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27126336', '假面饭店', '剧情', '刑警（木村拓哉）扮成服务生混入酒店，与酒店前台（长泽雅美 饰演）一起追查连续杀人事件的故事。鈴木雅之执导。东京都内发生了三起杀人事件。警方从所有案发现场都遗留有的无法解释的数列推断出这是一系列带有预告信息的连环杀人案，并就此展开了侦查。警视厅搜查一课的精英刑警新田浩介（木村拓哉 饰）破译出该数字预示着下一次作案的场所，他由此推测东京柯尔特西亚酒店将会成为第4起命案现场。然而凶手是谁却毫无线索。警方因此决定潜入东京柯尔特西亚进行调查，新田则要扮作前台人员追查凶手。受命指导他的是东京柯尔特西亚的优秀前台员工山岸尚美（长泽雅美 饰）。面对接连出现的来历不明的住客，作为刑警的新田“以逮捕犯人为第一要务”，试图剥下来客的“假面”，而作为酒店工作人员的尚美则从“以确保客人的安全为第一要务”的原则出发，希望保护来客的“假面”，两人势如水火。新田和尚美因为彼此的立场差异数次发生冲突，然而随着潜伏调查的推进，他们逐渐理解了彼此作为专业人士的价值观，两人之间开始萌生出不可思议的信赖关系。在这个过程中，案情迅速发展。警方和酒店都被逼入窘境无路可退。', '木村拓哉', '铃木雅之', 6.3, 73189, 'tt7502322', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2616924633.jpg', 1, 12.6, 61.3, 21.9, 3.3, '0.230299,-0.056127,-0.476364,0.368473,0.015168,-0.005037,0.389466,-0.008141,-0.362901,-0.352152,0.478670,0.511447,-0.123369,-0.065321,0.374196,-0.108459,-0.453235,-0.860837,-0.239072,-0.272543,-0.227503,-0.501992,-0.125959,-0.250068,0.147761,0.017824,0.549226,0.229536,-0.365678,0.355132,0.239915,0.474816,-0.619146,0.305184,0.188243,-0.261887,0.332128,-0.120397,-0.559459,0.360255,-0.186791,-0.274414,-0.096555,0.105289,0.036192,0.577659,0.648763,-0.238407,-0.408130,-0.026038,0.432896,-0.262344,-0.087464,0.016667,0.604960,0.185263,0.044604,0.435557,-0.187763,-0.035751,-0.071963,0.101044,-0.870746,-0.042354,0.256056,0.344044,-0.283442,0.055673,-0.283692,0.009443,0.214413,-0.200414,0.133328,0.427748,0.524515,-0.088033,-0.101812,0.046286,-0.320800,-0.092676,0.565872,0.001732,-0.164012,-0.062906,-0.264621,-0.475877,0.114087,-0.069800,0.065163,0.015850,0.109510,0.079863,-0.071658,0.079954,-0.325453,-0.320244,-0.522079,-0.297579,-0.017524,-0.283984,-0.015726,-1.052717,-0.048634,-0.094024,-0.257764,0.047969,0.119698,-0.119992,0.465449,-0.694527,-0.021322,0.698028,0.203853,-0.546486,0.373115,0.094913,0.128694,-0.334683,-0.284618,-0.081169,0.353813,0.683764,-0.057668,0.274496,-0.151242,-0.251587,-0.465015,-0.085603', '25723905', '2369613', '4014397', '6984051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27126349', '哥斯拉：决战之都', '动作', '21世纪初，人类将多数人留在被哥斯拉蹂躏的地球上，仅使被选中的人们乘上恒星间移民船·阿拉特拉姆，前往能够移居的“约定之地·τ星e”。但这一计划失败，人类只得再度返回地球。而长距离亚空间航行所引发的时空歪曲，导致人类回到的地方变成了“两万年后的地球”。在这个地球，主人公·晴男等人在遭受哥斯拉袭击的同时，与埃克西弗、比尔沙尔德两种族的异星人共同实行谋划了20年的“对哥斯拉战术”，通过殊死战斗成功击倒了哥斯拉。但喜悦并未持续多久，深藏地下的真正哥斯拉“哥斯拉·地球”现身了。两万年间持续成长生存、身高300米、质量超过10万吨，在进化成这种姿态的超巨大哥斯拉压倒性的破坏力面前，晴男等人落花流水。拯救了晴男的是被视为人类的残存者“弗图亚”之民，米亚娜。弗图亚是他们在这个地球首次遇到的人型生命种族。他们会是人类的子孙吗——。“弗图亚的神也被哥斯拉击破，如今只剩下卵。挑战者、抗争者，全部被火焰吞噬而消失了”面对这样的他们，晴男回应道“这是以人类的双手夺回地球的最后机会了”。另一方面，比尔沙尔德的指挥官·加尔格，注意到弗图亚使用的箭头是由“自律思考金属体·纳米金属”所制造而欢喜。这和21世纪他们在富士山麓作为“对哥斯拉决战兵器”所开发、在启动前遭到破坏的“机械哥斯拉”由同种物质所构成。这正是当时的开发设备至今仍然残存的证明——。', '宫野真守', '静野孔文', 6.7, 6634, 'tt8015080', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2519232908.jpg', 2.1, 9.7, 47.3, 30.5, 10.3, '0.012755,0.194591,-0.727314,0.419142,-0.086379,0.087372,0.613296,-0.083291,-0.218972,-0.024709,0.079124,0.700739,-0.237930,-0.172299,0.154917,-0.089274,-0.231191,-0.405925,-0.113433,-0.262801,-0.476080,-0.303281,-0.240574,-0.223099,-0.037363,-0.555518,0.834066,0.053481,-0.226828,0.235947,-0.197368,0.444616,-0.040044,0.535121,-0.134318,-0.036543,-0.070091,-0.293639,-0.100603,0.351115,-0.212407,0.004456,0.202932,0.279668,-0.282607,0.320048,0.894267,-0.683076,0.097555,-0.411634,0.175013,-0.393711,-0.139482,0.010680,0.548536,-0.225959,-0.195235,0.023521,0.058099,0.016289,0.210673,-0.033658,-0.824776,-0.255513,-0.117928,-0.029373,-0.356909,0.371786,0.012594,0.037985,-0.073021,-0.171222,0.137925,0.538081,0.241391,0.379954,-0.192007,-0.094802,-0.633542,0.030613,0.657766,-0.146307,-0.749675,0.258464,-0.194287,-0.666344,-0.380691,-0.484036,-0.310961,-0.245113,0.208359,0.265973,-0.114448,0.414555,-0.980415,0.046131,-0.446547,-0.214030,0.143478,-0.402631,-0.203450,-0.607349,-0.150337,-0.397134,-0.261920,0.217530,0.057098,-0.381128,0.715151,-0.813029,0.100430,0.658368,0.743951,-0.256447,0.622394,-0.264526,0.205583,-0.128700,0.040997,0.362985,0.060531,0.456895,0.075255,0.315899,0.253239,0.028078,-0.364841,0.580370', '25774050', '27126350', '26290398', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27126350', '哥斯拉：噬星者', '动作', '系列第三部 最终话 Netflix大门开启，黄金的刻印切裂星球。21世纪初，被哥斯拉夺走了地球的人类，将一部分人类送往其他恒星系移居，但这一计划以失败告终。失意地回到地球的人类，面对的是两万年后巨变的地球。一切动植物都拥有哥斯拉细胞，化作“怪兽行星”的地球。君临于此的，是身高超过300m的史上最大哥斯拉“哥斯拉·地球”。燃起讨伐哥斯拉执念的主人公晴男，与人类的子孙种族弗图亚相遇。晴男等人在弗图亚双子姐妹玛伊娜和米亚娜的引导下，发现仍在持续增殖的对哥斯拉决战兵器·机械哥斯拉的残骸。他们使用构成残骸的纳米金属，令武装要塞都市“机械哥斯拉都市”启动，向“哥斯拉·地球”发起挑战。在这一作战的过程中，之前曾经一同共存的异星人种族之一比尔沙尔德与人类之间的裂痕逐渐表面化。与比尔沙尔德首领·加尔格的“若要打倒哥斯拉，就要成为超越‘人’的存在”这一信念相对，晴男无法放弃“不可为了打倒怪兽而使自己也变成怪兽，应该作为‘人’将其战胜”这一信念。终于，晴男舍弃了打倒“哥斯拉·地球”的唯一机会，将加尔格杀死。另一方面，晴男的青梅竹马优子也由于比尔沙尔德进行的人体强制纳米金属化，而陷入脑死状态。败北感和虚无感在人类之间扩散。另一方的异星人，宗教种族埃克西弗的大司教·梅特菲斯，将晴男从战斗中存活下来之事主张为“奇迹”，并借此增加信徒。这是为了达成埃克西弗隐藏起来的“终极目的”。米亚娜和玛伊娜警戒着这样的埃克西弗。此外，晴男也自问自己身为“人”应该去做什么。不久，在没人能打倒“哥斯拉·地球”的地球上，覆盖着金色闪光的“基多拉”降临，震天动地的超次元战斗开始了。“哥斯拉”是什么？“人”应该去做的事情是什么？晴', '宫野真守', '静野孔文', 6.1, 6383, 'tt8478602', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2545100842.jpg', 7.5, 20.9, 41.4, 19.5, 10.7, '-0.012906,0.131389,-0.691462,0.546468,-0.110711,0.011915,0.730369,-0.060162,-0.099218,-0.025780,0.082027,0.754743,-0.133588,-0.090525,0.290452,0.008008,-0.346499,-0.457447,-0.066141,-0.232250,-0.401403,-0.438047,-0.246919,-0.211195,0.054061,-0.599154,0.848536,-0.106488,-0.288413,0.239469,0.016061,0.433866,-0.201137,0.450977,0.039124,-0.075597,-0.239635,-0.283838,-0.409364,0.185662,-0.053955,0.162682,0.018673,0.344806,-0.342352,0.144234,0.775488,-0.692535,0.281761,-0.524997,0.078163,-0.365509,-0.162494,-0.101857,0.466772,-0.245673,-0.112804,0.229051,0.256816,0.099055,0.298895,0.087135,-0.760478,-0.204182,0.109972,0.140206,-0.208380,0.386282,-0.006467,0.157423,0.071529,-0.196875,-0.069502,0.477764,0.245726,0.419997,-0.288511,-0.105904,-0.573534,-0.097537,0.635174,0.017284,-0.739334,0.171361,-0.118511,-0.568643,-0.374456,-0.208428,-0.308565,-0.277317,0.172280,0.291439,-0.167412,0.615254,-0.947157,-0.067733,-0.262410,-0.242897,0.092765,-0.404845,-0.048476,-0.479497,-0.101588,-0.253743,-0.250156,0.100528,0.152936,-0.365427,0.742607,-0.778590,0.084364,0.564599,0.765002,-0.158024,0.547925,-0.306355,0.172330,-0.122247,-0.116472,0.231796,-0.009048,0.451213,0.018639,0.249150,0.218183,0.053612,-0.337927,0.615195', '27126349', '25774050', '26759819', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27129560', '吾乃母亲', '科幻', '影片讲述一名少女在人类灭绝后，被一个用于构造生命让人类重现于地球、被称为“母亲”的机器人所创造，成为了新一代人类中的第一位，并且与“母亲”保持着独特的关系，然而一名受了伤的陌生人的到来使得这个关系受到动摇，让这名少女对于母亲告诉自己关于外面世界的一切以及母亲的意图产生了怀疑。', '罗丝·伯恩', '格兰特·斯布托尔', 7.4, 22790, 'tt6292852', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2555918291.jpg', 0.8, 3.8, 35.9, 44.9, 14.5, '0.182778,0.536813,-0.700836,0.974550,-0.300873,0.061649,0.957747,-0.372307,-0.636263,-0.812328,0.080101,1.035452,0.010728,0.344154,0.351526,-0.296780,0.118736,-0.646376,-0.342402,-0.053932,-0.510908,-0.406589,-0.410985,0.061715,-0.572588,-0.813668,1.169356,-0.109579,-0.797422,0.314531,-0.037248,0.518910,-0.151033,0.334970,-0.173505,-0.172272,0.119196,-0.049364,-0.496793,0.402035,-0.068270,0.025678,0.425571,0.578238,-0.827080,0.067606,0.820451,-0.829612,-0.501170,-0.640271,0.529132,-0.143807,0.125812,0.311111,0.452644,0.291772,0.044587,0.364010,-0.238785,0.132963,0.261197,-0.050919,-1.278093,-0.343566,0.290509,0.167572,-0.644830,0.106217,0.074275,-0.267502,0.205586,-0.057118,0.583188,0.538126,0.754073,0.699654,-0.378876,0.052783,-0.467443,-0.264674,0.938687,-0.140586,-0.571329,0.450400,-0.428337,-0.315021,-0.255786,-0.344555,-0.683462,0.306366,-0.194346,0.324718,-0.204165,0.583001,-0.627915,-0.168397,-0.070168,-0.317617,0.133759,-0.486217,-0.065302,-0.495236,-0.346302,-0.464910,-0.276746,-0.101383,0.159184,-0.548010,1.175070,-1.042459,0.529878,0.437079,0.367118,-0.846504,0.604547,0.093368,0.462989,-0.519643,-0.110357,0.486185,0.285074,0.058925,-0.260164,0.236382,-0.283217,-0.039634,-0.350247,0.561571', '26667010', '27602116', '25880986', '3001114');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27129663', '冠军', '剧情', '在美国洛杉矶夜店工作的马克（马东石 饰），一直梦想在腕力比赛中成为世界冠军，被自认是他经纪人的晋基（权律 饰）说服，回到韩国参加全国腕力大赛。除了比赛之外，晋基还送了从小被领养到美国的马克亲生母亲住家地址当做回国礼物。不过，马克只遇见从没见过面的妹妹秀珍（韩艺利 饰）和她的 一双儿女。在晋基牵线下，马克参加非法的腕力比赛。面对腕力怪物强敌环伺，在家人的支持下，马克能够一圆冠军梦吗？', '马东锡', '金勇完', 6.9, 8930, 'tt8367080', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2518254284.jpg', 1, 7.5, 49, 28.7, 13.8, '-0.292274,-0.066330,-0.516027,0.556036,-0.216890,-0.430542,0.077141,0.088934,-0.409888,-0.287033,0.181498,0.803040,-0.110048,0.237454,0.184406,-0.243227,0.004354,-0.740261,0.038686,0.061172,-0.250852,-0.585303,-0.134587,0.080465,0.103035,-0.271091,0.580733,-0.146876,-0.124285,0.453648,0.333790,0.090118,0.078367,0.233973,-0.343051,-0.108905,0.155497,0.353093,-0.634726,0.598655,-0.232508,0.039606,-0.256827,0.009605,0.419577,0.006889,0.554036,-0.103161,0.282122,-0.139786,0.146204,-0.211162,0.015464,0.117567,0.256793,0.070805,0.425356,0.202340,-0.082447,0.360024,0.163134,-0.463540,-0.388498,0.145479,0.098578,0.105805,-0.779561,0.524235,-0.291768,0.200104,0.077512,-0.223511,0.247349,0.328149,-0.106076,0.248855,-0.328838,0.213460,-0.566076,0.390013,0.713237,-0.157454,0.051807,-0.046559,0.099532,-0.421997,0.144580,-0.452616,-0.377121,0.422373,0.246546,-0.234391,-0.110143,0.001282,-0.549954,-0.077051,0.066197,-0.247532,0.213361,-0.498502,0.219963,-0.698872,0.238806,-0.190747,-0.406078,0.130783,0.172898,-0.468080,0.516528,-0.930449,0.313382,0.524966,0.382103,-0.375120,0.766144,0.203979,0.189193,-0.232096,-0.296729,0.201369,0.064266,0.080804,-0.186647,0.141274,0.083544,-0.270663,-0.417835,0.572613', '30345227', '26971054', '1897368', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27131218', '肥龙过江', '喜剧', '香港警察朱福龙（甄子丹 饰）因一次工作失误惨被降级，万般无奈之际又遭未婚妻可儿（周励淇 饰）悔婚，事业爱情的双重打击令他一蹶不振，暴饮暴食六个月后体重猛增到220磅！上司黄警官不忍其继续堕落，委派朱福龙前往日本押送一名犯人，并承诺只要完成任务就可以为他恢复职位。可惜来到日本，倒霉的事件便接连在他身上发生，不仅财物尽失，连犯人也在押送途中逃脱了。幸好得到前香港警察潇洒哥（王晶 饰）的帮助才得以暂时解困，为了完成任务找回犯人，朱福龙与潇洒哥共同行动，不料在查找真相的过程中发现了日本黑帮的惊天阴谋......', '甄子丹', '谷垣健治', 4.7, 27217, 'tt7335600', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2580345427.jpg', 15.4, 43.6, 35.4, 4.3, 1.4, '-0.156110,0.141196,-0.463364,0.255431,-0.208881,-0.479382,0.350803,0.090280,-0.476494,-0.271551,0.133983,0.232499,-0.081622,0.072215,0.347729,-0.377786,-0.230419,-0.587626,0.125654,-0.057629,-0.385813,-0.278902,0.004602,-0.263355,-0.184649,-0.167522,0.400401,0.368792,-0.089017,0.373298,0.412127,0.302633,-0.181633,0.603668,0.016211,0.184570,0.151429,-0.057236,-0.183666,0.264553,0.281843,-0.576896,0.227189,0.121361,0.108749,0.118935,0.731652,-0.013211,-0.361096,-0.244500,0.281818,-0.267390,-0.060987,0.027464,0.399724,0.127927,0.034195,0.348897,-0.303176,-0.086710,0.245516,-0.100814,-0.501920,0.023444,0.066185,-0.196248,-0.277562,0.184468,-0.179876,0.376224,-0.017270,-0.191291,0.101255,0.540185,0.468071,0.123734,-0.272597,0.265780,-0.560280,0.366847,0.566150,-0.236680,-0.061694,-0.096493,0.273866,-0.432230,0.174774,-0.261805,0.091303,0.297992,0.381596,-0.014297,-0.057944,-0.108548,-0.202198,-0.309982,-0.621449,-0.072525,-0.283190,-0.139945,0.112912,-0.387489,0.109558,0.067537,-0.186763,0.248954,0.132783,-0.251599,0.194732,-0.522692,0.287713,0.604683,0.348460,-0.718388,0.026823,0.073746,0.299712,-0.253389,-0.057317,0.197635,0.350891,0.541388,0.354256,-0.091442,-0.193816,-0.240957,0.022850,0.072702', '35073886', '3103418', '1366853', '30299515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27132510', '教宗的承继', '剧情', '这是一个真实的故事，讲述了近 2000 年来最戏剧性的权力交接事件之一。主教贝尔格利奥（乔纳森·普雷斯饰演）对教会的发展方向感到十分失望，因此向教皇本笃（安东尼·霍普金斯饰演）申请在 2012 年退休。然而，面对丑闻和自我怀疑，善于内省的教皇本笃召见对他最严厉的批判者和未来的继任者来到罗马，在梵蒂冈的围墙之内，展开了一场传统与进步、罪恶与宽恕之间的斗争，这两位截然不同的人直面各自的过去，以图寻找共同点，以及为全世界十亿信徒开创未来。', '安东尼·霍普金斯', '费尔南多·梅里尔斯', 8.6, 56181, 'tt8404614', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2567299222.jpg', 0.2, 0.7, 9.7, 46.6, 42.8, '0.126163,-0.131355,-0.669821,0.822750,0.207736,-0.167486,0.815777,0.075725,-0.552232,-0.544181,0.185982,0.857862,-0.172749,-0.152494,0.852196,-0.361044,-0.320731,-0.672919,-0.242558,-0.332068,-0.246918,-0.629232,-0.204212,-0.372972,-0.345844,-0.443055,0.604107,0.210916,-0.250527,0.395449,0.447032,0.432841,-0.048733,0.289481,-0.019311,-0.124540,0.221671,0.025375,-0.755053,0.126815,0.029458,-0.140592,-0.309949,0.255609,-0.356004,0.162112,0.244627,-0.506048,-0.135235,-0.241231,0.498479,-0.279872,-0.185237,0.325779,0.313745,0.351791,0.038554,0.646564,0.016099,-0.066661,-0.221555,-0.364903,-1.074933,-0.060889,0.052096,0.249669,-0.555348,0.434891,0.016043,-0.198250,0.270921,-0.262524,0.140320,0.487792,0.277990,0.589206,-0.281885,0.020325,-0.290138,-0.225489,0.694546,0.232111,-0.315410,0.076344,-0.184048,-0.365030,-0.112281,-0.325043,-0.318601,0.017282,-0.019560,0.012947,0.369272,0.650651,-0.653896,-0.229416,-0.180148,-0.505126,0.247563,-0.616049,0.102567,-0.732681,-0.374312,-0.516147,-0.151153,-0.042571,0.145097,-0.511739,0.732993,-0.711070,0.317065,0.443023,0.525400,-0.615641,0.885636,0.286799,0.394694,-0.521187,-0.251202,0.450871,0.114315,0.242898,-0.302659,0.133648,0.082718,-0.149525,-0.331348,0.408035', '26678784', '4301278', '1793491', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27133024', '世界奇妙物语 2017年秋季特别篇', '悬疑', '《寺岛》：刚刚拿到第一个连载的漫画家山崎（峯田和伸 饰），因为助手突然走掉而疲于奔命。某个下雨的日子，自称寺岛的女子（吉冈里帆 饰）前来担任助手职务。作为创作素材，寺岛向漫画家讲述了一个可怕的故事。《Freestyle妈妈》：人过中年的主妇细川房子（中山美穗 饰）在生活、职场中充满不快，某晚下班时一个奇怪男子推荐给她一支神秘口红。突然口红后，她就会以说唱的方式把心中不满一吐为快。《命运探测器》：完全不相信命运和缘分的和泉凉平（岩田刚典 饰）至今单身，某天他捡到一块奇怪的手表，谁知这竟是一个命运探测器。此后，探测器一次次将他带到美丽女孩北泽由纪（石桥杏奈 饰）的身边。《夜之声》：大型IT公司总裁我堀英一（藤原龙也 饰）人前风光，私下里则时长办成流浪汉减压。某晚，他救下了被坏人追逐的少女百合（饭丰万理江 饰）。百合从此暂住流浪汉家中，流浪汉介绍她到自己的公司应聘，然而少女却爱上了流浪汉。', '岩田刚典', '都筑淳一', 6.6, 6147, 'tt10178170', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2502012094.jpg', 2, 11.2, 51.6, 26.3, 8.9, '0.075910,0.033079,-0.284049,0.400214,-0.269333,-0.273509,0.737025,0.132641,-0.274456,-0.275627,0.240663,0.668110,-0.196622,0.484884,0.479193,0.260683,-0.316183,-0.589823,0.055523,0.076846,-0.344412,-0.037471,-0.194388,-0.331986,-0.064776,0.051357,0.561363,0.052385,0.018706,0.385980,0.251799,0.182978,-0.256109,0.282624,-0.189027,0.118775,0.203106,0.147215,0.042776,0.180878,-0.164622,-0.366656,-0.035266,0.122786,-0.097668,0.315177,0.609974,-0.128012,-0.141448,-0.228724,0.365777,-0.013721,0.012308,0.052530,0.206566,0.078903,0.194520,-0.118023,-0.227580,0.025827,0.094807,-0.176168,-0.418328,0.011416,0.000279,0.145062,-0.396977,0.390526,-0.175285,-0.066143,0.302066,-0.407938,0.110371,-0.042458,0.444326,0.237662,-0.150484,0.172928,-0.167094,0.498714,0.179520,0.135991,-0.107582,0.354394,-0.173897,-0.280028,-0.016241,-0.065830,-0.438091,-0.024910,0.184770,0.110297,-0.055589,-0.181532,-0.499615,-0.090803,0.069494,0.122406,0.135876,-0.286344,-0.282649,-0.361945,0.068668,-0.262931,-0.360612,0.232567,0.232813,-0.066386,0.569741,-0.486469,0.049728,0.570050,0.177603,-0.275431,0.607436,-0.008940,-0.103870,-0.232423,0.132319,0.144459,0.088947,0.293240,0.071422,0.392797,-0.177166,-0.065089,-0.302931,0.317115', '4233625', '1467779', '1303083', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27133050', '天作谜案', '悬疑', '维克拉姆（西达尔特·马尔霍特拉 Siddharth Malhotra 饰）的妻子凯瑟琳（Kimberley Louisa McBeath 饰）和玛雅（索娜什·辛哈 Sonakshi Sinha 饰）的丈夫谢加（Samir Sharma 饰）在同一天深夜死去，维克拉姆和玛雅自然成为了这两宗凶杀案的主要嫌疑人。实际上，维克拉姆和玛雅都坚定的认为，对方才是杀死自己爱人的真正凶手。德夫（阿克夏耶·坎纳 Akshaye Khanna 饰）是负责调查这两起案件的警官，上级命令他必须在三天之内将案件破获，这带给了德夫巨大的压力。为了混淆德夫的视线，并且将犯罪嫌疑推到对方身上，维克拉姆和玛雅使出了浑身解数。在此过程中，三人都发现，在这本就错综复杂的案件背后，隐藏着令人不寒而栗的真相。©豆瓣', '施坦·马洛萨', '阿沛·乔普拉', 6.7, 28212, 'tt6692354', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2571445582.jpg', 0.4, 7, 56.5, 31, 5.1, '0.350710,-0.128436,-0.802143,0.556196,-0.086159,0.081873,0.545863,-0.054294,-0.439100,-0.250733,0.317728,0.514566,-0.074412,-0.177966,0.320315,0.172353,-0.468530,-0.701872,-0.028406,-0.292177,-0.340156,-0.696732,-0.279662,-0.247930,0.150613,-0.336463,0.156388,0.030180,-0.190111,0.373886,0.465423,0.610489,-0.289080,0.365790,0.006059,0.029005,0.234825,-0.232601,-0.129165,0.229721,0.053180,-0.331141,-0.100916,0.496957,0.022188,0.453349,0.559660,-0.290809,-0.120194,0.188551,0.128853,-0.447921,0.183335,0.208471,0.299333,-0.031189,0.131670,0.512861,-0.335649,-0.130648,0.310738,0.126022,-1.028208,-0.081702,0.248563,0.180003,-0.319597,0.105026,-0.302875,-0.174752,0.116470,-0.210021,0.141069,0.447560,0.093297,0.184358,-0.171358,-0.011981,-0.644893,-0.035921,0.342438,-0.213738,-0.223347,-0.022889,-0.103769,-0.328394,-0.056648,-0.098648,-0.061586,-0.032447,0.485507,0.115689,0.006216,0.421052,-0.418933,-0.329865,-0.405607,-0.151409,-0.325987,-0.337654,-0.002983,-0.306731,-0.325304,-0.340074,-0.378474,-0.073157,0.110786,-0.356369,0.275797,-0.480401,0.328762,0.651078,0.136269,-0.110359,0.373326,0.265873,0.372164,-0.267211,-0.370182,0.110589,0.445914,0.340282,0.108656,0.370028,0.227393,-0.153147,-0.380111,0.536843', '1307442', '25862560', '26747274', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27133303', '超时空同居', '喜剧', '生活在2018年的大龄女青年谷小焦（佟丽娅 饰），梦想能够嫁一个能买得起她幼时豪宅的有钱人，却屡屡受挫，只能蜗居在一栋老居民楼里。生活在1999年的陆鸣（雷佳音 饰）手握着自己设计的宏伟蓝图，却始终找不到投资人，同时也面临重大的事业危机。奇怪的时刻来临了，失意的两个人回到家中居然发生了惊人的一幕，同一扇门关上后居然是两个时空的交汇点，两个不同时空的人相遇了，为了拯救自己的未来，两人共商大计，开启了幻想一夜暴富的一系列措施，引发了啼笑皆非的连锁反应。而他们不知道的是，两个时空的重叠是人为的操控，他们每走一步都会引发不可预知的结果，更要命的事，本来只是视对方为赚钱拍档的两人引发了爱的火花……©豆瓣', '雷佳音', '苏伦', 6.8, 499591, 'tt8404272', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520331478.jpg', 1.1, 8.1, 48.5, 34.4, 8, '0.295697,-0.114655,-0.702167,0.330475,-0.100420,-0.175438,0.914708,0.204255,-0.512922,-0.318507,0.334020,0.729184,-0.350606,0.218149,0.187188,-0.057414,-0.024493,-0.716452,0.039737,-0.200349,-0.361915,-0.156604,-0.425226,-0.420022,-0.126256,-0.197206,0.542935,0.338578,-0.288482,0.052952,0.271869,0.189835,-0.141219,0.493971,-0.514678,-0.006294,-0.029362,0.303621,-0.287879,0.147940,-0.145288,-0.338989,-0.332445,0.201185,-0.283899,0.283999,0.607811,-0.301831,-0.293338,0.011163,0.460279,-0.306505,-0.350666,0.074393,0.196161,-0.138210,0.189851,0.174423,-0.307339,0.060103,0.300122,-0.070891,-1.006814,-0.047727,0.126110,0.124352,-0.579278,0.445411,0.090619,-0.288547,0.053482,-0.282822,0.175703,0.516552,0.485215,0.608384,-0.361965,-0.183778,-0.639878,0.104428,1.073463,-0.093881,-0.527561,0.556110,-0.268494,-0.296794,-0.385395,-0.233001,-0.641521,0.065359,0.331212,0.261349,-0.093815,0.257065,-0.628425,0.183669,-0.354346,-0.169011,-0.067225,-0.559241,-0.349373,-0.484522,-0.134973,-0.492176,-0.373264,0.469919,0.076345,-0.372126,0.650840,-0.826036,-0.002520,0.526564,0.200494,-0.680874,0.945365,0.226218,0.110766,-0.271415,0.111487,-0.062686,-0.242934,0.253361,-0.042498,0.419584,-0.106393,0.031278,-0.384465,0.479627', '26678784', '25721544', '3055049', '30140231');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27133569', '小丑回魂2', '剧情', '1989年与小丑（比尔·斯卡斯加德 Bill Skarsgård 饰）的大战过后，窝囊废联盟的好友们各自长大，他们曾经相约当黑暗再次到来时，将再次集结德里镇，与小丑做最后的决断。可是当小丑再度出现的消息到来之时，窝囊废联盟的好友们却迎来了前所未有的内心冲击。有的人选择终结生命，而比利（詹姆斯·麦卡沃伊 James McAvoy 饰）、瑞奇（比尔·哈德尔 Bill Hader 饰）、贝弗莉（杰西卡·查斯坦 Jessica Chastain 饰）、本（杰·瑞恩 Jay Ryan 饰）等人却在留守的麦克（艾赛亚·穆斯塔法 Isaiah Mustafa 饰）的召唤下重返噩梦故乡。愈加狡猾的小丑肆意攻击着每个人心灵最脆弱的部分，噩梦似乎没有终结……本片根据斯蒂芬·金的同名原著改编。©豆瓣', '詹姆斯·麦卡沃伊', '安德斯·穆斯切蒂', 6.4, 67321, 'tt7349950', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2562980418.jpg', 2.6, 14.2, 50.8, 24.2, 8.2, '0.019581,-0.134679,-0.696316,0.455424,0.146219,-0.347789,0.751566,0.315722,-0.340901,-0.308395,0.065902,0.742380,-0.313084,0.233240,0.421524,-0.234015,-0.640943,-0.750902,-0.258502,-0.258118,-0.193542,-0.260682,-0.230858,-0.200691,0.118630,-0.360867,0.669404,0.009398,-0.087059,0.429013,0.376399,0.628088,-0.026369,0.478188,-0.056807,0.078044,0.175440,-0.108247,-0.335250,0.009988,-0.239644,0.094330,-0.386122,0.272670,0.057721,0.347366,0.711997,-0.886991,0.228984,-0.411334,0.101151,-0.280033,0.102838,-0.083280,-0.117894,-0.077927,0.182761,0.151990,0.045866,-0.002005,0.012510,-0.181689,-0.823701,0.217271,0.140983,0.221404,-0.383137,0.189815,-0.137861,0.235871,0.173853,-0.157489,0.122889,0.436214,0.312417,0.220863,-0.123303,-0.013709,-0.392234,-0.024545,0.583134,0.171096,-0.610625,0.172811,0.000944,-0.356644,-0.050125,-0.085613,-0.415196,0.000227,0.370839,0.125647,0.182681,0.566448,-0.834304,-0.296716,-0.425734,-0.098157,0.127666,-0.382472,-0.264850,-0.964116,-0.071854,-0.138449,-0.393539,0.041052,0.011312,0.091620,0.757753,-0.802098,0.490617,0.361068,0.148254,-0.108810,0.442467,0.104516,0.115518,-0.345840,0.019544,0.444704,0.228126,0.260147,0.179197,0.058507,-0.269631,-0.052961,-0.416773,0.731411', '25774050', '20274039', '2369613', '1294917');
