INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27135473', '阳台上', '剧情', '张英雄（王锵 饰）从小就生活在父母的溺爱之中，性格难免有些软弱。某日，张英雄的父亲张肃清（姚培德 饰）在和政府拆迁办的工作人员陆志强（许江宁 饰）的争吵中突发心梗去世了。无奈之下，母亲带着张英雄搬进了舅舅家中，过起了寄人篱下的生活，舅舅和舅妈对待他们的态度并不算客气，这让张英雄的心理更加不平衡了，他决定找陆志强报仇。张英雄搬出了舅舅家，在一家小店里当起了服务生，从这家店看出去刚好能够看到陆志强的家，张英雄就此认识了陆志强的女儿陆珊珊（周冬雨 饰）。陆珊珊是一个有着轻微智障的女孩，她的单纯和善良慢慢的消解了张英雄内心里的仇恨，他发现自己竟然爱上了她。©豆瓣', '周冬雨', '张猛', 5.7, 45654, 'tt9690762', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2546828235.jpg', 5, 28.8, 47.6, 15.6, 2.9, '0.212913,0.144255,-0.313491,0.753743,-0.366671,-0.568560,0.901020,0.192741,-0.430692,-0.281846,0.026680,0.822210,0.174040,1.173254,0.135300,-0.333109,-0.137058,-0.368612,-0.108087,-0.053300,-0.254748,-0.644774,-0.152462,-0.191391,-0.186929,0.145282,0.235075,0.073070,-0.420039,0.159300,0.413285,-0.054013,-0.033748,0.620295,-0.071584,0.296332,-0.228281,0.323673,-0.171208,-0.349504,0.472444,-0.525227,-0.097133,0.238539,0.246543,0.426248,0.578201,-0.068108,-0.159316,-0.101111,0.440732,-0.060704,0.064826,0.163459,0.259292,-0.132919,0.132337,-0.513672,-0.394086,-0.054168,0.044885,-0.064099,-0.247330,0.299364,0.299377,-0.232010,-0.836572,0.382084,-0.099099,0.054954,0.147865,-0.470409,0.146226,0.230169,0.207554,0.571332,-0.027936,0.232776,-0.309728,0.343730,0.528542,0.035179,-0.246592,0.089124,-0.227174,-0.594564,-0.025575,-0.171396,-0.743669,-0.099462,0.474536,-0.144197,-0.033657,0.068626,-0.474121,-0.093533,0.021683,0.104394,0.082082,-0.141717,0.080367,-0.283616,-0.290570,-0.582208,-0.000368,0.338949,-0.034385,-0.306590,0.604940,-0.795729,-0.167094,-0.197389,0.233992,-0.646189,0.688771,0.074432,0.013279,-0.182900,0.356709,-0.016871,-0.006742,0.148112,0.575030,0.486817,-0.114712,0.046528,0.141556,0.654378', '1895119', '25828521', '4030411', '1292207');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27135550', '齐天大圣·万妖之城', '奇幻', '由陈浩民、林子聪、范梦、赵东昊、李佳颖等主演的奇幻类喜剧电影《万妖之城》于8月30日在银川隆重开机，众主创集体亮相开机仪式现场。此次，他与林子聪再次搭配饰演师兄弟，倾力演绎唐僧师徒在万妖之城的故事。值得一提的是，陈浩民与林子聪已合作十余次，可见这对“好基友”深受观众喜爱，《万妖之城》中两人再度搭戏，一定能塑造出更受欢迎的师兄弟二人组。', '陈浩民', '项秋良', 4.7, 2775, 'tt9726522', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2515482502.jpg', 18, 42.7, 28.1, 8.4, 2.8, '-0.349205,0.130216,-0.587770,0.501603,0.502956,0.355782,0.183730,-0.087090,-0.231812,0.257617,0.254081,0.605717,-0.623123,0.061627,0.608436,-0.734717,-0.212950,-0.387094,-0.265158,-0.151007,0.281050,0.130451,0.011904,-0.015393,-0.396451,-0.429326,0.530781,0.249158,0.174286,0.546005,0.535444,0.011166,-0.595395,0.140945,0.167775,-0.003747,0.142431,0.105442,-0.542598,0.208866,-0.535140,0.169430,-0.272687,0.150533,0.078505,0.106018,0.800337,-0.463506,-0.404813,-0.075628,0.434599,-0.245363,0.010399,-0.125983,0.267925,-0.135340,1.003832,0.349492,0.156681,-0.176422,-0.372158,-0.372430,-0.334231,0.235440,0.499924,-0.118572,-0.136138,0.225677,-0.040442,0.021035,0.209245,0.028320,-0.029603,0.310243,0.555803,0.298081,0.310886,-0.267539,0.138213,0.487228,0.533431,-0.070135,-0.038017,0.088523,0.467317,-0.866052,-0.242290,-0.030890,-0.217119,0.217833,0.616017,-0.281786,0.189216,0.203951,-0.661026,-0.086963,0.041542,-0.134986,0.307139,-0.399051,0.309110,-1.072916,0.076681,-0.255680,0.035658,-0.024056,0.384205,-0.241104,0.779909,-0.645042,0.164939,0.016364,0.214054,-0.513381,0.563717,-0.065907,0.089080,-0.169383,-0.198626,-0.183518,-0.023923,0.364235,0.158741,0.495467,0.031313,-0.012002,-0.552518,-0.004214', '5403927', '24751811', '3318306', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27138615', '自卫的艺术', '喜剧', 'Bleecker Street购得莱利·斯特恩斯执导的黑色喜剧新片《自卫艺术》 的全球发行权，杰西·艾森伯格、伊莫珍·波茨、亚历桑德罗·尼沃拉主演，艾森伯格饰演一个在街上莫名遭遇攻击的倒霉孩子，后加入柔道训练学校跟着极有魅力又充满神秘的师傅(尼沃拉饰)学习自卫防御术，揭开了充满兄弟会情谊、暴力、超男子主义的邪恶世界的面纱，波茨扮演的女主角正努力奋斗想取得一席地位。该片已于周一在肯塔基开拍。', '杰西·艾森伯格', '莱利·斯特恩斯', 7.4, 13699, 'tt7339248', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2557471857.jpg', 1, 4.3, 33.6, 46.9, 14.1, '-0.082134,-0.158456,-0.448309,0.729910,0.090976,-0.262109,0.522547,0.285760,0.283122,-0.587662,0.526658,0.856739,-0.308555,0.048155,0.390673,-0.143972,-0.378382,-0.292241,0.002536,-0.157660,-0.160134,-0.300677,-0.343705,-0.107349,-0.040687,-0.620213,0.721413,-0.122601,-0.310568,0.292852,0.706209,0.434513,-0.051409,0.153844,0.118796,0.022248,0.414581,-0.343979,-0.568723,0.351817,0.198924,0.172416,-0.202610,-0.079054,-0.098794,0.020943,0.595487,-0.067335,0.336897,-0.086261,0.546881,-0.112202,0.085323,-0.187052,0.174892,-0.130813,-0.134238,-0.006403,-0.107549,0.028556,0.143924,-0.320524,-0.532662,0.022832,0.165992,0.060955,-0.158235,0.103909,-0.276593,0.044089,0.062262,-0.063942,-0.324193,-0.066600,0.424510,0.206429,0.425873,0.236524,-0.177988,-0.098088,-0.035996,-0.314467,-0.230402,0.382889,-0.365020,-0.280910,-0.027529,-0.323614,-0.620366,-0.139065,0.343419,-0.371039,0.202883,0.486758,-0.592723,-0.188184,-0.205356,-0.006844,0.098567,-0.130343,0.053643,-0.917287,-0.249466,0.053402,-0.132751,-0.037414,0.141471,-0.217242,0.663941,-0.753092,0.248522,0.497216,0.161039,0.001287,0.421169,-0.086020,0.138773,-0.220376,-0.382196,0.566218,0.157139,-0.028488,0.031011,0.587689,0.050089,-0.125819,-0.086170,0.714027', '26611806', '1870681', '2369613', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27139732', '你给的仇恨', '剧情', '斯塔尔（阿曼德拉·斯坦伯格 Amandla Stenberg 饰）是一名16岁的黑人少女，就读于一家白人私立学校中，每一天，她都要在学校和家庭之间不断的切换自己的身份，肤色所带来的的困扰令她感到十分的之一。一天，斯塔尔参加了一场朋友举办的派对，在派对上，她和自己儿时的玩伴哈勒利（阿格利·史密斯 Algee Smith 饰）重逢了。老友相见分外亲热，哈勒利开车载斯塔尔回家，哪知道在半路上遇到了警察的拦检。让斯塔尔没有想到的是，警察竟然因为一个小小的误会就开枪射杀了哈勒利，而自己是唯一的目击证人。在之后的听证会上，哈勒利被形容成为了一个贩毒的小混混，但斯塔尔知道，这一切都是谎言。©豆瓣', '阿曼德拉·斯坦伯格', '小乔治·提尔曼', 7.9, 12385, 'tt5580266', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2528989179.jpg', 1, 2.6, 23.3, 48.9, 24.2, '0.512323,-0.244106,-0.616324,0.625653,-0.204931,-0.323658,0.852022,0.035572,-0.571416,-0.313935,0.268239,0.893462,-0.360407,0.450377,0.404139,-0.005547,-0.186094,-0.736436,0.126458,-0.267414,-0.287400,-0.431881,-0.257827,-0.187311,-0.030205,-0.324709,0.289404,-0.041464,-0.024068,0.396806,0.296780,0.351913,0.217920,0.440016,-0.172881,0.033787,0.184954,0.136900,-0.036983,0.214030,-0.009444,-0.239098,-0.088605,0.330092,-0.166686,0.544232,0.506921,-0.118624,-0.113258,-0.059719,0.430142,-0.444434,0.124748,0.087236,0.340107,-0.194166,0.159813,-0.027195,-0.385409,-0.037842,0.254236,-0.004389,-0.674707,0.134293,0.161494,0.361784,-0.761866,0.721507,-0.227151,-0.283331,0.030401,-0.124997,0.339844,0.398583,0.279466,0.313616,-0.000674,-0.248882,-0.745354,0.051159,0.879481,-0.100983,-0.315002,0.216793,-0.432957,-0.407347,0.204531,-0.107235,-0.411156,0.022236,0.000708,-0.240076,-0.150497,0.084814,-0.486486,-0.115897,-0.497498,-0.124405,-0.187743,-0.418297,-0.086242,-0.635045,-0.008795,-0.449960,-0.323667,0.194292,0.095903,-0.193070,0.599887,-1.027051,0.211039,0.683234,0.388654,-0.022040,0.877321,0.256636,0.083253,-0.276840,-0.071671,-0.024430,0.387717,0.001542,0.057449,0.499179,0.035848,-0.034313,-0.173280,0.556188', '1308755', '3055049', '1302384', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27140071', '找到你', '剧情', '律师李捷（姚晨 饰）正在离婚进行时，与前夫争夺女儿抚养权，拼命工作为给孩子最好的生活，幸有保姆孙芳（马伊琍 饰）帮忙照顾孩子视如己出。                                                                                  一日下班，李捷发现保姆孙芳和女儿毫无预兆地消失了，她内心最大的恐惧变成了现实。在追寻孙芳和女儿的下落时，她收到来自家人的谴责声讨，甚至遭到警方的怀疑。几乎崩溃的李捷，靠着惊人的勇气，踏上独自寻访的旅 程。在追踪过程中，李捷逐渐接近了另一个女人——保姆孙芳的人生故事，她的身份原先都是谎言，而真相也将浮出水面……', '姚晨', '吕乐', 7.3, 196268, 'tt9034530', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2534471408.jpg', 0.7, 4.6, 37.1, 44.9, 12.7, '-0.069555,0.075231,-0.787184,0.522956,-0.264742,-0.353268,0.540528,0.200891,-0.675100,-0.255776,-0.056076,0.548730,0.012897,0.383382,0.296955,-0.164341,-0.295921,-0.720845,-0.122446,0.208058,-0.288599,-0.496243,0.106943,-0.440270,-0.034446,-0.227330,0.498834,0.111307,-0.190007,0.212270,0.236819,0.103006,-0.174444,0.615104,0.001739,0.135023,-0.090248,0.084643,-0.375536,0.200153,0.128611,-0.245070,-0.071791,0.100053,-0.217885,0.380136,0.854342,0.012661,-0.052273,-0.090139,0.481102,-0.538502,-0.035460,0.127679,0.129579,0.161699,0.110361,0.126661,-0.211499,-0.116520,0.273746,-0.180018,-0.555421,0.021368,0.126835,-0.114947,-0.680744,0.313431,-0.214813,0.022236,0.397234,-0.464810,0.416271,0.464268,-0.047836,0.399033,-0.589789,0.256348,-0.404570,0.210276,0.423757,-0.017905,0.046007,0.170422,-0.120655,-0.245674,0.131570,-0.167893,-0.441560,-0.199179,0.112096,0.296212,-0.320874,0.275036,-0.327895,-0.145734,-0.280190,-0.221994,-0.040549,-0.554843,-0.253359,-0.314104,-0.080465,-0.046602,-0.208847,0.190120,0.026049,-0.337833,0.630036,-0.511021,0.387486,0.319929,0.365104,-0.606559,0.709218,-0.055997,0.158781,-0.645320,0.050926,0.353390,-0.043869,0.147357,-0.003432,-0.150692,-0.268603,0.282708,-0.316634,0.469617', '1301022', '1293607', '1301221', '30140107');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27145041', '全职高手之巅峰荣耀', '剧情', '电子竞技成为全国第78个体育赛事，“荣耀”将首次举办职业联赛。18岁的叶秋（本名叶修）与好友苏沐秋，在网吧老板陶轩的协助下，开始组建草根电竞战队“嘉世 ”。同时，来自全国各地不同背景的队友们也因为梦想齐聚一堂，为着电竞舞台的最高荣耀而刻苦训练。嘉世一路过关斩将，即将冲进决赛之际，团队却遭遇危机。面对劲敌皇风战队来势汹汹，作为队长的叶秋要如何解决眼前的困境？这样一群怀揣梦想的少年，是否能够登上荣耀的巅峰？', '张杰', '史涓生', 5.5, 30977, 'tt10736726', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2564508538.jpg', 9.6, 32.1, 38.1, 15, 5.2, '0.037605,0.388003,-0.502220,0.508371,0.086434,-0.246920,-0.079830,0.060963,-0.446158,-0.158392,0.442775,0.800183,-0.068619,0.528486,0.427350,-0.641319,0.268862,-0.784475,-0.414005,-0.271319,-0.164185,-0.103301,-0.421708,0.233554,-0.054187,0.050923,1.183430,0.137516,-0.260264,0.595138,0.625498,0.552827,-0.022738,0.331076,-0.062496,-0.506122,0.546469,0.254363,-0.591642,0.397392,-0.583754,-0.003246,-0.433993,0.100230,0.026722,-0.189476,0.611950,-0.352106,0.266483,-0.297986,0.433339,-0.324525,-0.128145,0.107844,0.586327,0.258259,0.085274,0.099222,0.603775,0.275558,-0.436397,-0.450490,-1.195045,-0.035230,0.139131,0.057248,-0.597137,0.402628,-0.106909,0.056254,0.361209,0.055733,0.073901,0.578493,0.477679,0.411517,-0.348977,0.337399,-0.363125,0.190700,1.045568,0.003052,-0.192300,-0.210032,-0.015048,-0.386297,0.116069,-0.358762,-0.386786,-0.006585,0.074801,0.219735,0.473717,0.199497,-0.612739,0.487140,-0.082586,-0.381196,0.140706,-0.455115,-0.055349,-0.648470,0.041083,-0.002302,-0.185370,0.131897,0.191409,-0.350944,1.080605,-0.908648,-0.122593,0.537100,0.118783,-0.472692,0.553418,0.182407,0.362588,-0.367949,-0.427283,0.183178,-0.121309,0.469593,-0.313702,0.158636,-0.413125,-0.447683,-0.198396,0.403538', '27602116', '3861846', '25880986', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27149818', '胖子行动队', '喜剧', '特工“J”（文章 饰）在执行一次A级任务时头部中枪，导致颅内下丘脑受损。养伤期间，J渐渐变成了一个三百斤的大胖子，并患有严重的嗜睡症，但J依然认为自己是一个王牌特工。终于，J再次接到任务，只身前往日本取回机密文件。文件得手后，J却擅自拆开文件决定替组织继续完成隐藏其中的任务，不料却晕倒在居酒屋。医院醒来的J结识了保安郝英俊（包贝尔 饰），郝英俊为了证明自己不是个一事无成的废物毅然决然地加入任务中。这对临时拍档在执行任务的过程中，经历一次又一次令人啼笑皆非、险象环生的危机......', '文章', '包贝尔', 4.2, 78841, 'tt8845432', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2526215398.jpg', 34.6, 33.1, 24.6, 4.6, 3, '-0.018587,0.330700,-0.403417,0.558462,-0.181580,-0.246331,0.569436,0.007855,-0.512866,-0.483212,0.282851,0.669035,0.032732,0.144436,0.303979,-0.264571,-0.175006,-0.559524,-0.023113,0.010217,-0.844641,-0.334170,-0.046071,-0.366848,0.009520,-0.250439,0.647238,0.394580,-0.120053,0.450842,0.211263,0.256902,-0.135874,0.541886,0.038143,-0.326039,0.256913,-0.070307,0.111010,0.545061,0.385230,-0.416490,-0.108602,0.375030,0.204449,0.497327,0.678838,-0.062061,-0.493793,-0.297253,0.319067,-0.176420,-0.361805,-0.156958,0.381553,0.291379,0.107185,-0.017288,-0.399245,0.183714,0.102004,-0.323230,-0.804440,-0.230043,0.164843,0.072484,-0.381492,0.336785,-0.447205,0.435748,-0.187159,-0.217414,0.026725,0.474385,0.501089,0.274157,-0.209565,0.313508,-0.375339,0.053899,0.333620,-0.070781,-0.141218,0.174725,0.150742,-0.585374,0.232838,-0.230783,0.031023,0.300320,0.247820,0.202152,-0.261205,-0.101003,-0.437690,0.026316,-0.657648,-0.174522,-0.308947,-0.155145,-0.355259,-0.452034,0.252945,0.329682,-0.217585,0.331977,-0.074980,-0.176161,0.382746,-0.649444,0.219439,0.565643,-0.167091,-0.524482,0.301149,0.330975,0.288285,-0.320242,0.099038,0.147025,0.409593,0.462400,0.233474,0.190284,-0.226766,-0.372361,-0.433974,0.267834', '2988294', '25774050', '1297689', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27150225', '狂暴凶狮', '喜剧', '在阿姆斯特丹，警方发现了被残忍杀害的一家人的尸体，警方对此案一时之间毫无头绪。但是阿姆斯特丹动物园的兽医Lizzie通过伤口怀疑这应该是一只大型的狮子所为。但最初Lizzie的猜测并没有受到警方的重视，直到越来越多的受害者以相同的方式被杀害，毫无疑问阿姆斯特丹已经成为了一位捕食者的狩猎场。警方指派猎人Jack和Lizzie一起对行凶的狮子进行追捕，而Lizzie的男友，一位电视台记者也在跟踪报道此案，Lizzie除了追查狮子的下落还担忧着男友的安全，而此时的狮子已经饥饿难忍……', '索菲·范·德温', '迪克·麦斯', 5, 12343, 'tt4291700', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2548549246.jpg', 13.3, 34.7, 42.1, 7.5, 2.4, '0.381999,-0.223159,-0.784032,0.711861,0.049478,-0.075556,0.971254,-0.025352,-0.685762,-0.250343,0.392161,0.725283,-0.138033,0.260945,0.053388,-0.133402,-0.057824,-0.613583,-0.259096,-0.116174,-0.416086,-0.778427,-0.284918,-0.386308,0.153925,-0.215926,0.740219,0.203648,-0.215484,0.610222,0.405886,0.223493,-0.165045,0.668353,-0.319409,-0.403036,0.214261,-0.005536,0.008460,0.205420,0.258586,-0.343179,0.076828,0.418624,-0.327641,0.666785,0.722203,-0.351444,-0.556264,-0.112284,0.472510,-0.667636,0.254196,0.350624,0.924464,-0.102752,0.067515,0.132707,-0.206993,0.015157,0.033779,0.152131,-1.267141,-0.142582,0.161679,0.464321,-0.472284,0.564147,-0.140381,0.133765,0.056664,-0.347777,0.335723,0.453941,-0.014497,0.355225,-0.216642,0.045099,-0.606955,0.029477,0.679024,-0.054456,-0.194986,0.152740,-0.291924,-0.530914,0.015218,-0.327127,-0.215138,-0.115602,0.250318,0.221254,-0.631446,0.158315,-0.555924,-0.124904,-0.387017,-0.396292,-0.310961,-0.436168,0.075906,-0.819684,-0.071520,-0.480054,-0.106518,0.065418,0.365417,-0.236463,0.472914,-0.993878,0.342724,0.874785,0.260390,-0.641613,0.552208,0.081233,-0.041750,-0.062368,-0.449752,-0.003945,0.530329,0.471504,0.249695,0.241997,0.117694,-0.625838,-0.402698,0.139640', '1793491', '1307442', '35073886', '1297689');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27150283', '狼嚎', '动作', '一个年轻人有一种罕见的礼物，可以识别他听到的每一个声音。在一艘法国核潜艇上，一切都依赖于他，金耳朵。看上去绝对可靠，他犯了一个错误，让船员处于死亡的危险之中。他希望重新获得同志的信任，但他的追求会让他们陷入更加戏剧化的境地。在核威慑和错误信息的世界中，他们发现自己被困在一个无法控制的装备中。', '弗朗索瓦·西维尔', '安东·鲍德里', 7.2, 11927, 'tt7458762', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2542972538.jpg', 1.2, 5.3, 37.7, 41.8, 14, '0.470418,0.473477,-0.782897,1.071901,-0.405843,0.088549,1.174873,-0.142296,-0.570903,0.036499,0.339019,1.238644,0.071492,0.023686,0.103720,-0.012018,-0.017714,-0.551121,-0.133649,-0.033331,-0.595718,-0.586286,-0.659567,-0.433007,-0.260392,-0.448162,0.788442,0.434555,-0.353130,0.204984,0.065591,0.185821,0.276097,0.838180,-0.187698,-0.216022,0.231245,-0.091424,0.051119,0.451990,-0.040512,-0.059723,0.316695,0.702735,-0.424144,0.154512,0.744773,-0.529660,-0.638587,0.311458,0.620868,-0.079347,-0.197857,0.087870,0.091950,-0.196858,-0.108359,-0.042104,-0.487081,0.184037,0.044590,0.288085,-1.201618,-0.356248,0.124906,0.313949,-0.357526,0.346804,0.055990,-0.048628,0.081693,-0.333608,0.288329,0.250843,0.340072,0.510303,-0.346234,-0.164605,-0.635139,-0.047464,0.785773,-0.274081,-0.792943,0.164002,-0.630336,-0.511743,-0.167120,-0.403971,-0.723986,-0.033991,0.196816,0.092828,-0.306175,0.035583,-0.557579,0.317870,0.023626,-0.380947,-0.503601,-0.564306,-0.141531,-0.199167,-0.113022,-0.420774,-0.595378,0.306329,0.017499,-0.432581,0.869609,-0.840182,0.179012,0.826369,0.170604,-0.335025,0.905582,0.135502,0.054915,-0.328025,-0.076369,0.182658,-0.023248,0.093813,0.124718,0.420582,-0.164060,0.167794,-0.415171,0.649855', '25932086', '3119246', '34890458', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27150284', '速成家庭', '剧情', '皮特（马克·沃尔伯格 Mark Wahlberg 饰）和爱丽（萝丝·拜恩 Rose Byrne 饰）结婚多年，夫妻两人之间的感情一直十分要好，只是这么多年来，他们都没有孩子，不过对于两人来说，这并不是什么着急的事情。一场意外让两夫妻的观念开始产生了改变，他们开始渴望一个爱情的结晶，年纪已经不再年轻的他们选择了走了领养这条路。一个名为利兹（伊莎贝拉·莫奈 Isabela Moner 饰）的小姑娘吸引了皮特和爱丽的注意，虽然利兹的个性尖锐而又叛逆，但他们还是在她的身上看到了动人的闪光点。利兹还有一个弟弟胡安（古斯塔夫·奇洛兹 Gustavo Quiroz 饰）和一个妹妹丽塔（朱莉安娜·甘米兹 Julianna Gamiz 饰），夫妻两人一不做二不休的也顺带收养了这两个孩子。©豆瓣', '马克·沃尔伯格', '西恩·安德斯', 7.5, 17036, 'tt7401588', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2547253192.jpg', 0.6, 3.2, 31, 48.6, 16.6, '0.704965,-0.249295,-0.708455,0.708544,-0.366341,-0.638291,1.032249,0.020539,-0.514884,-0.201111,-0.058046,0.923755,-0.344432,0.166996,0.103974,0.357042,-0.459076,-0.592224,0.172541,-0.262611,-0.219016,-0.758220,-0.197103,-0.112524,-0.240142,-0.041723,0.531624,-0.152076,0.236889,0.819419,0.450808,-0.063950,0.107016,0.459720,-0.110326,0.258906,0.202983,0.115144,-0.170165,-0.022230,0.003507,0.232349,-0.214493,0.414900,-0.041389,0.556063,0.402880,-0.264400,-0.070311,-0.089959,0.136660,-0.086360,0.029733,0.145740,0.317891,-0.335348,0.485076,0.093669,-0.178928,0.014893,0.127241,0.018663,-0.599444,0.261511,-0.013123,0.150083,-0.887431,0.666018,0.014975,-0.390657,0.131387,-0.342404,-0.001768,0.511155,0.291434,0.403836,-0.300084,-0.173898,-0.498347,-0.362069,0.754459,-0.139763,-0.381161,0.682655,-0.323935,-0.410464,-0.233245,0.043599,-0.544606,0.025331,0.396457,0.067120,-0.218837,0.151536,-0.614924,0.184390,-0.226682,0.033094,-0.060917,-0.635450,0.103491,-0.425009,-0.165209,-0.912439,-0.736098,0.124034,0.030431,-0.145118,0.808836,-0.722891,0.108419,0.412385,0.190576,-0.641010,0.612225,0.414142,0.227906,-0.452506,-0.150146,0.080094,-0.256806,-0.078351,0.361196,0.530469,0.221116,-0.011192,-0.130359,0.544453', '3111650', '25867546', '1301516', '4301215');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27155276', '素人特工', '喜剧', '极限运动达人赵风（王大陆 饰），误打误撞闯入了一场国际犯罪交易，不得不跟随国际特工（米拉·乔沃维奇 饰）一起前往布达佩斯。在这里他与废柴刑警淼淼（张榕容 饰）、民间科学家丁山（许魏洲 饰）与待业医生LV（刘美彤 饰）组成一支素人特工小队。这四个特工小白和高级国际特攻米拉一起，与恐怖分子开启了一场又惊又喜的斗争。', '王大陆', '袁锦麟', 3.4, 37747, 'tt7773340', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2560447448.jpg', 52.8, 31.2, 12.7, 1.4, 1.9, '0.307174,-0.157411,-0.541192,0.676512,0.398206,-0.105404,0.331305,-0.059058,-0.610240,-0.326874,0.228404,0.596381,-0.101924,-0.128427,0.472850,-0.021256,-0.449767,-0.581691,-0.137797,-0.152839,-0.268137,-0.384966,-0.430607,-0.195935,-0.184437,-0.164341,0.624206,-0.216043,-0.162282,0.836289,0.644567,0.445453,-0.407471,-0.055029,0.121103,-0.167879,0.799851,0.155998,-0.576438,0.178881,-0.042883,0.101092,-0.046747,-0.298195,0.330199,-0.261249,0.489961,-0.417294,0.595639,-0.435655,-0.114692,-0.558783,-0.254593,-0.267352,0.433551,-0.003361,0.470897,-0.072247,0.212292,0.140586,0.219891,0.016169,-0.325861,-0.110631,0.340773,-0.035045,-0.532902,0.238146,-0.481060,0.118959,0.023315,0.008850,0.217372,0.537826,0.391536,0.061292,0.176995,-0.265379,-0.340465,0.294154,0.673407,0.288646,0.050225,-0.241527,0.079667,-0.686711,-0.302411,-0.167768,-0.304765,0.165303,0.166189,-0.565935,0.210200,0.158393,-1.015379,-0.170684,-0.372094,0.034460,-0.109641,-0.276748,0.250828,-0.954740,0.250086,-0.224918,-0.177013,0.252212,0.206831,0.209545,0.594730,-0.839142,-0.018198,0.222881,0.332733,-0.364908,0.342749,-0.122052,0.349334,-0.521985,-0.197906,-0.101647,0.142973,0.557673,0.102368,0.606637,-0.092326,-0.161910,-0.302757,-0.369244', '20274039', '26365262', '25833539', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27155457', '目击者', '悬疑', '午夜两点，传来无辜女子的凄厉求救声，在阳台上目睹杀人实况的尚勋（李星民 饰），当他正准备要报警的时候，竟意外跟凶手对上了眼，让他与家人成为凶手的下一个目标。为了保护自己与家人，尚勋必须对警方隐瞒自己看见凶手的事实，并展开与杀人魔之间的惊悚追击…', '李星民', '曹圭章', 6.4, 13756, 'tt8865562', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2527640726.jpg', 4.8, 14, 45.6, 26.5, 9.1, '0.320952,0.135610,-0.470784,0.383496,-0.036461,0.053121,1.094158,-0.238837,-0.302851,-0.045211,0.103423,0.754283,-0.006050,0.000433,0.238188,0.149714,-0.349126,-1.079350,0.012772,-0.181782,-0.316250,-0.526400,-0.163770,-0.251181,0.001908,-0.043410,0.346959,0.143753,-0.481467,0.734920,0.397829,0.276381,-0.378092,0.706582,-0.134882,-0.510900,-0.081924,-0.088176,-0.311341,0.282155,0.093166,-0.473853,-0.268351,0.561794,-0.462975,0.448540,0.531527,-0.422603,-0.364102,-0.230027,-0.076350,-0.412244,0.215663,0.528553,0.123892,-0.132606,0.349814,0.478260,-0.143188,-0.241998,-0.153929,0.283698,-1.202823,-0.012651,0.332689,0.058810,-0.382061,0.304908,-0.366182,0.128851,0.561590,-0.225321,0.362688,0.250615,0.124862,0.470431,-0.720365,-0.176719,-0.442002,-0.237968,0.591611,0.163685,0.278604,0.133807,0.242350,-0.353712,-0.035705,0.045217,-0.446919,-0.031039,0.369525,0.134989,-0.220312,-0.094937,-0.443692,-0.218832,-0.278206,-0.114804,-0.329315,-0.482496,-0.214560,-0.258386,0.094722,-0.181707,-0.560624,0.334958,0.053635,-0.385194,0.166221,-0.618202,0.297562,0.537274,0.435232,-0.300439,0.690871,0.232134,0.053612,-0.480999,-0.352891,-0.331695,0.378402,0.499862,0.032883,-0.103444,0.137522,-0.082238,-0.598928,0.345432', '3119246', '10486471', '25828589', '2027938');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27157811', '死于明日', '剧情', '片中的故事均以真实新闻改编而成。每天的日常生活看来并无什么特别之处，但死亡往往就会来得猝不及防，日常生活中的琐碎赋予了生命以价值。在曼谷，朋友庆祝毕业、兄弟姐妹再次相聚、恩爱夫妻面对分离、女演员等待召集...... 这是对命运和生命无常的一种既愉快又忧郁，同时充满哲学性的反思。该片由六部分组成，分别讲述了死亡之前平静的一天是怎样度过的。这部作品继承了纳瓦彭之前影片中的混杂实验元素，是一种包含虚构成分的散文电，有音频、图片、记录文件等媒介拓展达到对死亡意义的探索。', '桑尼·苏瓦美塔农', '纳瓦彭·坦荣瓜塔纳利', 7.4, 7889, 'tt7683696', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2504253175.jpg', 1.2, 4, 35.4, 44.7, 14.7, '0.157688,-0.058751,-0.339235,0.704213,0.172610,0.147823,0.822365,-0.095600,-0.458142,-0.289889,0.013602,0.383133,-0.379671,0.093633,0.291664,-0.389844,-0.277101,-0.562888,-0.191982,-0.038797,-0.308336,-0.624068,-0.295505,-0.125703,0.014383,-0.397329,0.715664,0.234750,-0.282651,0.304451,0.031351,0.242968,-0.393816,0.306950,0.142418,-0.146104,-0.216492,0.245317,-0.470232,0.005432,0.301053,-0.132936,-0.014887,0.184511,-0.191904,0.314734,0.792487,-0.142949,-0.235061,0.116382,0.745623,-0.136890,-0.198272,-0.114387,0.046084,0.488813,0.134625,0.387994,-0.021456,0.250073,-0.236871,0.015638,-1.246524,-0.362375,0.210161,0.263508,-0.063221,0.428853,0.257675,-0.161336,-0.036692,-0.090851,0.268224,0.205736,0.662921,0.568737,0.103582,-0.210393,-0.205497,0.372115,0.449472,-0.335644,-0.550969,0.650092,-0.492605,-0.506181,-0.233296,-0.186509,-0.258186,0.102115,-0.003200,0.545164,0.132163,0.350257,-0.810655,0.022226,-0.002932,-0.410232,0.190278,-0.495695,0.136107,-0.680778,-0.251742,-0.362580,-0.180666,-0.047014,0.472857,-0.472639,0.921906,-0.738533,0.214768,0.379477,0.087027,-0.445635,0.489409,0.245681,0.001045,-0.490964,0.154246,0.305722,-0.014787,0.063053,-0.276765,0.047950,0.266570,0.088282,-0.602462,0.618428', '6844861', '27602116', '26667010', '35360296');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27160618', '阳光姐妹淘', '剧情', '90年代的日本，6名女子高中生组成了「SUNNY」，一起经历了美好的青春岁月，更希望可以一直在一起…转眼20年过去，她们却各自踏上不一样的路，过着毫无交集的生活。某天，已经成为家庭主妇的奈美，竟遇上另一成员芹香，更意想不到的是好友身患重病，时日无多…她唯一的愿望就是跟「SUNNY」成员重聚！为了实现芹香最后的心愿，奈美展开了寻找昔日好友之旅…', '筱原凉子', '大根仁', 8.3, 63426, 'tt7493818', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2526509538.jpg', 0.3, 1.7, 16.9, 45.2, 35.9, '0.070119,-0.187740,-0.523831,0.450488,0.234458,-0.705982,0.786228,-0.214150,-0.540410,-0.202078,-0.081176,0.604307,0.052431,0.523618,0.400276,-0.210952,-0.302793,-0.731299,-0.128582,-0.333800,-0.425939,-0.249750,-0.089408,0.014140,-0.203387,-0.233204,0.942251,0.154216,0.130786,0.432189,0.412999,-0.041140,-0.346269,0.496480,-0.443464,0.081169,-0.094878,0.284139,-0.647940,0.165444,-0.212655,-0.030220,-0.166890,0.102120,-0.129660,-0.008852,0.620658,-0.418638,0.015320,-0.406417,0.140423,-0.075225,-0.172481,-0.096910,0.241765,0.036759,0.471494,0.173965,0.042508,-0.335597,0.072797,-0.257591,-0.804243,0.038564,0.285265,0.390713,-0.518979,0.288474,0.115089,-0.084472,0.179442,-0.295691,0.037302,0.516477,0.425615,0.186012,-0.339634,0.080022,-0.501649,0.378352,1.132114,0.280364,-0.280309,0.523096,-0.396158,-0.294959,-0.095908,-0.290749,-0.278233,0.115617,-0.120257,0.277132,-0.134040,0.424642,-0.590381,0.192917,-0.149109,0.092743,0.316734,-0.569668,-0.002516,-0.412309,0.097898,-0.237231,-0.528330,0.416562,0.071820,-0.508433,0.957445,-0.995575,0.285977,0.607111,0.532001,-0.410357,0.993689,0.302248,0.167783,-0.295386,0.204315,0.499361,-0.375680,0.362745,0.133255,0.093864,-0.411795,0.002241,-0.433417,0.477245', '25721544', '5985887', '1296569', '35030151');
