INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27161899', '那些年，我们一起追的女孩', '喜剧', '日本将翻拍[那些年，我们一起追的女孩]。导演为长谷川康夫，男主角山田裕贵，曾在古川雄辉版《一吻定情》中饰演阿金。女主角则是乃木坂46的斋藤飞鸟。影片预计2018年秋天日本上映。', '山田裕贵', '长谷川康夫', 6.7, 8414, 'tt7339938', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2523121920.jpg', 2.1, 11.8, 48.6, 26, 11.4, '-0.204734,-0.256172,-0.012334,0.408549,0.117190,-0.332704,0.391002,-0.094053,-0.029109,-0.408006,0.451634,0.616230,-0.531162,0.296403,0.261085,0.212793,-0.263308,-0.977515,-0.348974,-0.243276,0.403652,-0.148740,-0.118954,0.035706,-0.334723,-0.007094,1.212952,-0.008391,0.258593,0.736163,0.432410,-0.169313,-0.432684,-0.321727,0.230306,0.463028,0.271252,-0.110030,-0.593328,0.407968,-0.310313,-0.662517,-0.227289,-0.395693,0.100016,0.256509,0.626669,0.204453,0.287115,-0.259808,0.278332,-0.362333,-0.267959,0.044890,0.661592,-0.017126,0.102227,0.515397,-0.309104,-0.279609,-0.288127,-0.223986,-0.091166,0.251833,-0.116326,0.266130,-0.020463,0.112862,-0.203647,0.231871,0.345450,-0.235067,0.016064,-0.005747,0.520240,0.029085,-0.235438,0.287012,0.210783,0.759891,0.558319,-0.119649,0.495208,0.331579,-0.022759,-0.391872,-0.233629,-0.207621,-0.398196,0.430546,-0.031279,-0.154328,-0.289374,-0.076316,-0.276781,-0.122851,0.096319,-0.324765,0.116103,0.098107,0.215913,-1.117209,0.069460,-0.595834,-0.043530,-0.211348,0.424657,-0.238831,0.982631,-0.320903,0.143647,0.815657,0.540041,0.010420,0.604297,0.085953,-0.790180,-0.015646,0.383665,0.179943,-0.234600,-0.241233,0.251392,0.407232,-0.285509,-0.359154,-0.274924,0.378382', '1322847', '2369613', '3266509', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27163278', '速度与激情：特别行动', '喜剧', '一个是美国外交安全局的忠诚特工、身材魁梧的执法者霍布斯（强森饰），一个是前英国军事特工精英、无法无天的恶棍肖（斯坦森饰）。在2015年的《速度与激情7》中首次对峙之后，两人不论言语还是肢体都冲突不断，一直试图打倒对方。然而，通过高科技进行了基因增强的无政府主义者布里克斯顿（伊德瑞斯·艾尔巴饰）控制了一种可能永远改变人类命运的不为人知的生化武器，并且还打败了一位大胆优秀又特立独行的军情六处特工（曾出演《王冠》的凡妮莎·科比饰）——她恰好是肖的妹妹，为了扳倒这个世界上唯一可能比他们更厉害的敌人，这两个不共戴天的宿敌不得不联手。《速度与激情：特别行动》一片在《速度与激情》系列的宇宙中推开了一扇全新的大门。从洛杉矶到伦敦，从切尔诺贝利的有毒废墟到美丽的南太平洋岛国萨摩亚，本次特别行动席卷全球。该片由大卫·雷奇执导(《死侍2》导演)，由《速度与激情》系列故事的缔造者克里斯·摩根编剧，摩根、强森、斯坦森和海拉姆·加西亚共同担纲制片。丹尼·加西亚、凯利·麦考密克、 、史蒂文·查斯曼、伊森·史密斯和安斯利·戴维斯担任监制。', '道恩·强森', '大卫·雷奇', 6.3, 241159, 'tt6806448', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561542272.jpg', 2.1, 14.8, 55.6, 22.4, 5.1, '0.054597,0.090024,-0.724829,0.852634,-0.017400,-0.311832,0.655586,0.092711,-0.440055,-0.251653,0.153438,0.719995,-0.227922,-0.169916,0.388956,-0.114245,-0.360735,-0.725165,-0.240877,-0.134382,-0.377448,-0.519363,-0.567288,-0.454868,0.030796,-0.328910,0.595628,-0.078689,-0.322995,0.282796,0.312917,0.259416,-0.013589,0.204897,-0.020850,-0.179933,0.445809,-0.176348,-0.461891,0.255094,0.047630,-0.023317,-0.070307,0.108860,-0.129244,0.236417,0.428812,-0.325704,0.127489,-0.168474,0.172577,-0.238623,-0.007439,0.048428,0.424142,-0.148776,0.096741,0.128109,0.115383,0.078427,0.042597,-0.139856,-0.847615,-0.014857,0.058584,0.213763,-0.294923,0.236253,-0.328624,-0.037769,0.036489,-0.306188,-0.067156,0.237217,0.405726,0.249149,-0.088494,0.010704,-0.269303,0.040397,0.539859,0.152254,-0.535355,0.088828,-0.296790,-0.453724,-0.300545,-0.157592,-0.404537,-0.145388,0.422942,-0.093403,0.158930,0.469904,-0.780624,-0.096734,-0.325261,-0.109054,-0.198373,-0.250844,0.277129,-0.833035,-0.306252,-0.466642,-0.018588,0.088009,0.139266,-0.093402,0.724567,-0.562863,0.133572,0.600620,0.213365,-0.253049,0.364818,0.071953,0.169064,-0.239996,-0.174500,0.310820,0.27