INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27165968', '少年泰坦出击电影版', '喜剧', '威尔·阿奈特、克里斯汀·贝尔献声[少年泰坦出击电影版](Teen Titans Go! to the Movies，暂译)。该动画片将由亚伦·霍瓦特、彼得·里达·米卡尔执导。剧版《少年泰坦出击》原版配音人马格雷格·西佩斯、斯科特·门维尔等悉数回归。而威尔·阿奈特、克里斯汀·贝尔两人在片中的角色暂不可知。', '尼古拉斯·凯奇', '亚伦·霍瓦斯', 8.2, 6266, 'tt7424200', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2513656628.jpg', 0.7, 2.1, 18.5, 44.3, 34.4, '0.206518,-0.255512,-0.112002,0.339093,0.247950,-0.493513,0.614898,0.399711,-0.038871,-0.314450,0.331810,0.525850,-0.087131,-0.594609,0.758590,0.437885,-1.235218,-0.254465,0.126185,-0.309684,0.495904,-0.581490,-0.179429,-0.079330,-0.053974,-0.264881,0.344157,-0.411047,-0.041738,0.137633,0.163561,0.382065,0.245699,0.042584,1.155008,0.559287,0.273258,-1.125551,0.235765,0.614130,0.256233,0.287625,-0.327838,-0.134638,0.499455,0.206155,0.650188,-0.574717,1.171294,-0.238408,-0.233353,0.058421,0.733903,0.253569,-0.108457,-0.588382,0.223069,-0.155300,0.251618,-0.250130,0.492872,-0.484396,-0.082682,0.599406,-0.571368,0.558923,-0.366888,-0.203670,-0.823487,0.098883,0.521380,-0.348797,-0.567228,0.314683,0.615146,-0.153529,0.083375,-0.286901,0.032912,-0.035068,-0.099683,0.263166,-0.177836,-0.264261,-0.057441,-0.760329,-0.611496,0.301562,-0.833613,-0.274613,0.894097,-0.295513,0.655829,0.998312,-0.288150,-0.449155,-0.590877,-0.174843,-0.322623,-0.025896,0.218049,-1.242070,0.240593,0.263273,0.117095,-0.692081,0.033764,-0.026833,0.081063,-0.685096,0.393955,0.232384,0.281037,0.631652,0.323096,-0.266815,0.309278,-0.100327,0.343118,0.757875,0.292871,0.044453,0.601179,0.572444,0.359134,-0.056049,-0.082848,0.617242', '27098363', '6517421', '3089638', '26335580');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27166442', '夏目友人帐', '剧情', '在人与妖怪之间过着忙碌日子的夏目，偶然与以前的同学结城重逢，由此回忆起了被妖怪缠身的苦涩记忆。此时，夏目认识了在归还名字的妖怪记忆中出现的女性·津村容莉枝。和玲子相识的她，现在和独子椋雄一同过着平稳的生活。夏目通过与他们的交流，心境也变得平和。但这对母子居住的城镇，却似乎潜伏着神秘的妖怪。在调查此事归来后，寄生于猫咪老师身体的“妖之种”，在藤原家的庭院中，一夜之间就长成树结出果实。而吃掉了与自己形状相似果实的猫咪老师，竟然分裂成了3个——！？', '神谷浩史', '大森贵弘', 8, 182132, 'tt9081300', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2546745948.jpg', 0.4, 2, 23.4, 46, 28.2, '0.410387,-0.037093,-0.667125,0.627036,-0.166488,-0.368231,1.052605,0.172398,-0.660850,-0.206185,-0.093333,0.603405,-0.353587,0.517539,0.159855,-0.064210,-0.143999,-0.678155,-0.244385,-0.079046,-0.134663,-0.362297,-0.355233,-0.177762,0.007230,-0.688724,0.775157,0.152932,-0.038252,0.842568,-0.233499,0.124952,-0.408717,0.326176,-0.362268,0.163923,-0.082111,0.521959,-0.149342,-0.059870,-0.131214,-0.237362,0.001206,-0.085961,0.127323,0.339387,0.898221,-0.414027,-0.540555,-0.047874,0.032628,-0.034483,-0.088367,0.293084,0.704063,0.151431,0.332887,0.137128,-0.132427,-0.051993,-0.185955,-0.054011,-0.597419,0.045452,0.027819,0.485396,-0.412022,0.725301,0.227522,-0.144369,-0.037300,-0.490758,0.393236,0.458001,0.263351,0.418190,-0.261121,0.047664,-0.496662,-0.029118,0.832086,-0.060065,-0.433137,0.466105,-0.490606,-0.608747,-0.259044,-0.118455,-0.251503,0.011074,0.068363,0.208393,-0.440972,0.530476,-0.833601,-0.009100,-0.011318,0.201406,0.116262,-0.392504,-0.342606,-0.384548,-0.411503,-0.629757,-0.429078,0.111568,0.103728,-0.405428,0.894168,-1.134596,0.301164,0.471429,0.369797,-0.125362,0.555203,-0.091358,-0.008717,-0.244555,-0.092023,0.203261,0.145460,0.412228,0.298829,0.349964,-0.075811,0.179902,-0.740009,0.359822', '1292219', '35030151', '1826173', '24839498');
