INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27168151', '上流社会', '剧情', '有着信念的大学教授张泰俊(朴海日饰)为了改变世道梦想进入政界，张泰俊的妻子美术馆副馆长吴秀妍(秀爱饰)想要成为馆长。各方势力在密切关注着利用“市民银行”这一idea挑战国会议员的张泰俊。今年获得作家奖的作家兼大企业总裁韩龙锡(尹济文饰)，和他的妻子美术馆馆长李画兰(罗美兰饰)将关注着张泰俊和吴秀妍夫妇。讲述比起现在，想要进入更好的群体、进入上流社会的人们的欲望冲撞。——来自@罗美兰－中文饭团', '朴海日', '边赫', 5.9, 10724, 'tt8865580', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2528502067.jpg', 5.1, 23.3, 49.1, 16.4, 6.1, '0.140462,0.066702,-0.575578,0.639963,0.131469,-0.186952,0.434314,0.416536,-0.806877,-0.482327,0.243939,0.653615,-0.249666,0.143314,0.419032,-0.275584,-0.221547,-0.514656,-0.072929,0.024049,0.135177,-0.611861,-0.267226,-0.255736,-0.326916,-0.258845,0.649559,0.121300,-0.568102,0.215191,0.214830,0.306291,0.011861,0.185507,0.078081,-0.159639,0.290926,-0.101302,-0.938727,0.453565,0.214402,0.059855,-0.030532,0.194914,0.159188,-0.082567,0.385187,-0.432783,0.072724,-0.002235,0.506433,-0.294499,-0.201030,0.151034,0.398766,0.219177,0.261471,0.265954,-0.160578,0.273988,0.120057,-0.378411,-0.855738,-0.138504,0.549895,0.480816,-0.567187,0.353172,0.063281,-0.025305,-0.011812,-0.263465,0.165136,0.470431,-0.035946,0.439064,-0.051977,0.483203,-0.477878,0.317647,0.592471,-0.028288,-0.025328,-0.238157,-0.321333,-0.413727,-0.144254,-0.339417,-0.643621,-0.168721,0.209897,0.098324,0.139513,0.329647,-0.664004,0.011447,0.190253,-0.140136,0.451291,-0.456171,0.013751,-0.826508,-0.166898,-0.141072,0.252847,-0.306352,0.150832,-0.614679,1.267554,-0.991888,0.174446,0.598616,0.769049,-0.582115,0.913595,-0.087191,0.009954,-0.580526,-0.445806,0.186549,0.080357,0.392834,-0.283357,-0.006214,-0.177150,-0.565504,0.136154,0.179458', '27602116', '24284209', '1308424', '26711487');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27168310', '哭泣女人的诅咒', '悬疑', '新线恐怖片[孩子们]更名为[哭泣的女人的诅咒](The Curse of La Llorona，暂译)，温子仁担任制片，其公司Atomic Monsters担任制作。导演迈克尔·查维斯，主演琳达·卡德里尼。墨西哥传说中有一个“哭泣的女人”的故事， 一个丢了自己孩子的女人开始掠夺其它人家的孩子。片中的单身母亲在调查儿童失踪案时发现这个“哭泣的女人”似乎就在她的身边。', '琳达·卡德里尼', '迈克尔·查维斯', 5.9, 16897, 'tt4913966', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2537353038.jpg', 4.1, 22.7, 52.2, 15.3, 5.7, '0.171613,-0.267540,-0.659621,0.537241,-0.563457,-0.464190,0.860477,0.189162,-0.353335,-0.308954,0.500772,0.894820,-0.112633,0.410772,0.008065,0.206074,-0.486282,-0.683309,-0.248578,0.081498,-0.217275,-0.205674,-0.032904,-0.409335,-0.134954,-0.293247,0.775685,-0.303899,-0.134934,-0.139531,0.537037,0.021862,-0.095684,0.238893,-0.213879,0.366913,0.351182,-0.179865,0.040429,0.229029,-0.271282,-0.107251,-0.050271,-0.106637,-0.211851,0.520759,0.665537,-0.304319,0.188991,-0.430918,0.561627,-0.234693,-0.112375,-0.145609,0.099053,-0.267612,0.537312,-0.090550,-0.243710,-0.361527,-0.020607,-0.012469,-0.572377,0.039283,0.095085,0.518423,-0.501535,0.176471,-0.169441,0.380036,0.256626,-0.341476,0.171130,-0.010411,-0.079140,0.430777,-0.166602,0.197799,-0.436909,0.500232,0.257063,-0.351480,-0.127660,0.453705,-0.034928,-0.394489,-0.232911,-0.154791,-1.003626,0.105721,0.086546,-0.342713,-0.353829,0.267205,-0.565741,-0.079492,-0.064619,-0.143608,-0.004442,-0.170751,-0.297586,-0.594077,-0.072663,0.118793,-0.142106,-0.418452,0.197869,-0.393830,0.924085,-0.517812,0.155411,0.706663,0.162221,-0.668297,0.618127,0.201516,0.234953,-0.348471,-0.248136,0.547225,0.027678,-0.112731,-0.170749,0.424480,-0.214186,0.056094,-0.340288,0.506204', '4233625', '4847665', '1908036', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27170563', '下海', '剧情', '上世纪90年代末东北爆发大规模下岗潮，女性失业尤为严重。很多女人听说当法国保姆能赚钱，便不惜背上巨债出国。到巴黎后发现求生无路，只好去“站街”。比利时导演奥利维耶偶然遇到她们，进行了长期调查，并找到王小帅任监制，以此拍摄出电影《下海》。', '耿乐', '奥利维耶·梅斯', 7, 16585, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2550629939.jpg', 0.7, 5.4, 45.8, 39.1, 9, '-0.036730,-0.061008,-0.789351,-0.040951,0.161962,-0.553894,0.330663,-0.178569,-0.380316,-0.172169,-0.050809,0.410798,0.056223,0.135452,0.331689,-0.236929,-0.557058,-0.383736,0.098943,0.074559,-0.434716,0.110515,-0.025736,0.055400,-0.658357,-0.147846,0.367380,0.202749,-0.280151,0.181498,0.230687,0.209470,-0.096318,0.362948,-0.038871,0.078513,-0.116796,0.061674,-0.538246,0.551373,0.061879,-0.115709,-0.318919,-0.266096,0.348024,0.212558,0.304486,0.392405,-0.042150,-0.175851,0.866953,-0.155585,-0.107328,-0.287550,0.321726,0.255453,0.393416,-0.026313,-0.122767,-0.071211,-0.212799,-0.275285,-0.129037,0.252141,-0.227145,0.008934,-0.328770,-0.504035,0.012837,0.042185,-0.061228,-0.484776,0.090358,0.114989,0.251730,-0.069548,-0.008206,0.269639,-0.453449,0.375311,0.822084,-0.029986,-0.241431,-0.069801,0.272884,-0.380784,0.445972,-0.366591,0.000095,0.399349,0.212743,-0.184025,-0.337856,-0.212872,-0.361290,0.131555,-0.373959,-0.319938,0.218232,0.327314,0.065742,-1.171732,0.067286,-0.010963,0.059998,0.208828,0.174109,-0.386331,0.087336,-0.540694,0.155422,0.722738,0.575175,-0.380766,0.428616,-0.251348,0.174148,0.084241,0.122693,0.372977,-0.237493,0.330389,-0.238893,-0.066482,0.008472,-0.141206,0.040215,0.135992', '34961898', '24751811', '3871833', '27013111');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27172872', '呼吸', '剧情', '当巴黎被一种奇怪的致命烟雾淹没时,幸存者只能在城市的上层和屋顶避难。没有新闻,没有电,没有水,没有食物,一个小家庭在灾难中挣扎求生。但随着时间的推移,他们不得不面对现实:救援队伍不能来了。如果他们希望活着出来,他们就得冒着被雾笼罩的危险。', '罗曼·杜里斯', '丹尼尔·罗比', 5.7, 9741, 'tt5092380', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2622749786.jpg', 4.5, 22.6, 57.5, 12.7, 2.7, '0.349504,0.240900,-1.221723,0.720134,-0.190327,0.008613,1.402110,-0.080019,-0.514768,-0.155651,0.169978,0.580009,-0.015325,-0.191818,-0.446587,-0.154098,-0.308542,-0.758639,-0.342783,-0.298016,-0.701700,-0.293008,-0.370627,-0.371016,-0.385792,-0.165801,0.864831,0.851559,-0.299148,0.280551,-0.055636,-0.040432,-0.024623,0.976747,-0.585789,-0.049346,0.174571,0.113891,0.043801,0.553849,0.264932,-0.220880,-0.545266,0.751633,0.195725,0.383586,0.750579,-0.394743,0.100587,0.267546,0.005547,-0.736422,0.214671,0.082432,0.384129,-0.332371,0.398070,-0.188953,-0.172526,-0.337544,0.047145,0.153115,-1.136082,0.177250,0.028214,0.591356,-0.775194,0.635325,-0.178190,-0.358137,0.087850,-0.291619,0.312078,0.206759,0.123523,0.430270,-0.455544,0.025032,-0.951788,0.159948,1.202667,-0.195788,-0.738591,0.440878,-0.798319,-0.235149,-0.343585,-0.178020,-0.522062,-0.320865,0.743316,0.359103,-0.762125,0.134752,-0.317938,0.076252,-0.099737,-0.763869,-0.161778,-0.207282,-0.347986,-0.192767,0.003643,-0.116412,-0.276119,0.503030,-0.104929,0.309419,0.814037,-0.869540,0.404513,1.071813,0.291603,-0.420228,1.031313,0.144627,-0.185762,0.138128,0.356988,-0.178822,-0.068260,0.718714,0.839540,0.556914,0.029281,-0.122862,-0.398661,0.462993', '1947080', '26715845', '1304862', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27172891', '大象席地而坐', '剧情', '满州里动物园有一头大象，每天坐在那里。为朋友出头的少年、为弟报仇的恶霸哥哥、身陷囹圄的女生，卡在世界灰暗的缝隙里无法脱身，却挣扎着去看大象。萧瑟寒冬的一天，绝望身影在不对称不平衡的影像中碰撞， 爆裂了压抑的沉郁，在粗糙布景、朦胧灯光的低成本制作中肆意蔓延。作者兼导演胡波 （笔名胡迁）首作，以青涩朴质与震撼感性，获柏林影展赏识入围论坛单元， 却是无法嵌合和谐主旋律的一块失落拼图。看不见大象是共同宿命，胡波骤然陨落，也成了这一代人的遗憾。', '彭昱畅', '胡波', 8.1, 179214, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2511811355.jpg', 1.1, 3.2, 18.5, 46.2, 31, '0.103129,0.141846,-0.692774,0.401205,-0.004570,-0.159147,1.093667,0.375750,-0.233949,0.176894,0.334215,0.466288,-0.252404,0.271203,-0.163759,-0.006314,-0.290446,-0.501628,-0.380337,-0.248393,0.039747,-0.308741,-0.587104,-0.229434,0.000736,-0.232493,0.957459,0.307884,-0.230296,0.403328,0.275411,-0.130326,-0.362517,0.486266,-0.208728,-0.314208,-0.054845,0.090908,-0.057959,-0.301801,-0.058839,-0.281647,-0.092617,-0.007136,-0.261455,0.245881,0.715902,-0.274364,0.047069,0.074912,0.375803,-0.039931,-0.157104,0.064172,0.145285,0.040286,0.213826,-0.211354,-0.067046,-0.003220,-0.046980,0.007936,-0.635951,0.087046,0.214341,0.592453,-0.331099,0.841452,0.000449,-0.323411,0.091178,-0.198572,0.210561,-0.192756,0.273805,0.642508,-0.155594,0.275292,-0.304818,0.338520,0.462514,0.165757,-0.599333,0.277717,-0.634438,-0.259871,-0.028958,-0.267623,-0.559250,-0.279871,0.585112,0.062676,-0.153118,0.239377,-0.536513,-0.020153,0.015300,-0.020845,-0.503206,-0.322813,-0.298029,-0.202061,-0.251397,-0.127837,0.048454,0.183861,0.146402,-0.264796,0.491116,-0.605348,0.166577,0.338424,0.224814,0.459369,0.869887,-0.065021,-0.195923,-0.162444,-0.007270,0.100873,-0.263205,0.246000,0.243028,0.450687,-0.209227,0.312756,-0.725120,0.594565', '1467779', '1417428', '1304862', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27176717', '熊出没·变形记', '喜剧', '光头强（谭笑 配音）和爸爸（孟雨田 配音）之间的关系一向不算太好，两人分居两地，很少有联系。这一天，光头强的爸爸突然来到狗熊岭探望自己的儿子，虽然爸爸对待光头强照顾的十分周到，但三观不合的两人之间还是很快就发生了冲突。在父子两人又一次爆发激烈的争吵时，光头强和熊大（张伟 配音）、熊二（张秉君 配音）意外的被“缩小机”给变小了，并不知道事件真相的光头强爸爸以为儿子失踪了非常的伤心，遂选择了离开。他并不知道的是，自己在无意之中带走了缩小机。就这样，为了恢复原本的尺寸，光头强带着两头熊开始了寻父之旅，被缩小后的三人需要面对的，是平常万万想象不到的困难和麻烦。©豆瓣', '张伟', '丁亮', 6.8, 18165, 'tt8028526', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2506889386.jpg', 2.2, 9.6, 45.1, 31, 12.1, '0.346056,-0.254652,-0.942600,0.373228,-0.163733,-0.404173,0.704512,0.325081,-0.494722,-0.278475,0.043858,0.642949,-0.400711,-0.077558,-0.167136,-0.316110,-0.054388,-0.601911,-0.211158,0.197689,-0.273836,-0.589008,-0.225885,0.067700,-0.274907,-0.231315,0.216113,-0.105157,-0.411585,0.482381,0.331436,-0.196576,0.039219,0.642180,-0.273733,0.201731,-0.091921,0.276300,0.095160,0.124691,0.302361,0.079436,0.038004,0.154349,0.127498,0.517972,0.627130,0.053902,-0.643018,0.102900,0.234890,-0.075147,-0.292185,0.103064,0.654426,0.047499,0.362779,-0.014675,-0.313590,0.029887,-0.167425,0.028969,-0.691769,0.389996,0.256596,-0.149413,-0.733522,0.399890,-0.072050,-0.251513,0.361478,-0.327024,0.189740,0.732091,0.128918,0.504533,-0.027959,0.066993,-0.446897,-0.138662,0.902289,0.098384,-0.441576,0.232782,0.025150,-0.242349,-0.178460,-0.300195,-0.156791,0.144980,0.403838,-0.011536,-0.329242,0.133755,-0.549652,-0.016391,-0.270023,0.076031,-0.173315,-0.280424,-0.106102,-0.193287,-0.124807,-0.660184,-0.283115,0.267119,-0.234238,-0.295847,0.770059,-1.070278,0.191369,0.314264,0.546675,-0.470456,0.541796,0.213326,0.062999,-0.399166,0.100747,-0.230519,-0.081266,0.059144,0.387864,0.281415,0.112345,-0.310441,-0.487068,0.321367', '1292219', '1301022', '35030151', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27176742', '驭风男孩', '剧情', '改编自William Kamkwamba所著自传《驭风男孩》（The Boy Who Harnessed The Wind），讲述一个改变人生的故事：Kamkwamba本人在13岁那年，以小块金属废料、旧自行车零件和木材修建了风轮机，拯救了自己的村庄。13岁的Kamkwamba因家里没钱交80美元一年的学费而被学校开除，热爱学习的他溜到学校的图书馆，找到了一种拯救饥荒村庄的方法：用父亲的自行车的主架打造了一个简陋但可行的风车，为西部地区提供了急需的电力，不受政府断电的干扰。这个发明也让Kamkwamba得到马拉维一名教授的资助，获得学校的奖学金，并于非洲大陆其他的发明者进行深入交流。', '切瓦特·埃加福', '切瓦特·埃加福', 8.2, 20890, 'tt7533152', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2547694957.jpg', 0.2, 0.8, 16.1, 52.7, 30.3, '0.451486,-0.047266,-0.274813,0.616055,-0.218455,-0.176444,0.516816,0.050119,-0.105621,-0.452479,0.043304,0.776603,0.251641,0.344844,-0.014029,-0.042380,-0.092156,-0.310590,0.032653,-0.077069,-0.558313,-0.530263,-0.030648,-0.353264,-0.145137,-0.489217,0.727307,0.250946,-0.299621,0.416236,-0.255289,0.157676,0.349665,0.095329,-0.452559,-0.246649,-0.054214,0.309815,0.126133,0.349115,-0.379710,-0.211269,0.013885,-0.014092,0.074340,0.638518,0.762672,0.116395,-0.100802,-0.034793,0.716362,-0.135682,-0.051113,-0.232675,0.315901,0.204570,-0.153711,0.036326,-0.283169,0.219833,0.030678,-0.296504,-0.783289,-0.358025,0.144221,-0.183391,-0.687536,0.480034,-0.015254,-0.082332,-0.159487,-0.307614,0.188267,0.397855,0.042888,0.825036,-0.404633,0.148036,-0.698144,0.438648,0.455589,-0.583748,-0.505303,0.332656,-0.469890,-0.493213,0.066532,-0.363613,-0.476124,-0.155031,0.159240,-0.086491,-0.171695,-0.243338,-0.871785,-0.022891,-0.034976,-0.433994,0.231743,-0.270091,-0.218530,-0.718145,0.122950,-0.304418,-0.064717,-0.042404,0.442638,-0.415043,0.825816,-0.562201,-0.031589,0.720041,0.221442,-0.582078,0.690557,-0.107294,0.188141,-0.183775,-0.065034,0.137611,-0.007628,0.627062,-0.150207,0.380005,0.226405,-0.340525,-0.485517,0.471242', '26290398', '1302661', '22265121', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27177908', '凯特', '动作', '凯特一丝不苟，技艺超群，是职业杀手中的标杆，并正处于巅峰期。然而这次在东京，她在暗杀一名极道成员时一反常态地失手，并被判了残忍而缓慢的死刑：她中毒了，只有不到 24 小时的时间复仇。身体状况迅速恶化的凯特与一名少女意外建立起感情，而这名少女是她以前杀掉的一个人的女儿。《凯特》由玛丽·伊丽莎白·温斯特德、米库·马蒂诺和伍迪·哈里森主演，塞德里克·尼古拉斯·特罗扬担任导演，讲述了一名被算计的杀手在临终前的绝地反击。', '玛丽·伊丽莎白·温斯特德', '塞德里克·萨科', 6.3, 14596, 'tt7737528', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2675197481.jpg', 2.4, 14.9, 54.6, 21.5, 6.7, '0.037258,0.008331,-0.494893,0.713231,-0.324516,-0.471101,0.901782,0.156892,-0.567035,-0.478948,0.558907,0.794125,-0.010579,0.081043,0.731472,-0.173846,-0.342535,-0.791608,-0.053063,-0.216715,-0.326561,-0.636760,-0.294294,-0.289092,-0.215265,-0.471619,0.540114,-0.178308,-0.227554,0.436038,0.277820,0.561691,0.124765,0.463093,-0.051650,0.039833,0.300254,-0.580952,-0.067112,0.374956,0.157593,-0.190827,-0.329065,0.259655,-0.083753,0.650447,0.512270,-0.277358,0.035362,-0.301441,0.276095,-0.470615,0.052160,0.039523,0.587778,-0.095312,0.015117,0.216977,-0.039120,0.086266,0.027619,-0.328676,-0.872960,0.176292,-0.146542,0.393312,-0.584856,0.555064,-0.374859,0.195625,0.088988,-0.256019,-0.206580,0.262764,0.043300,0.155674,-0.175742,0.027463,-0.514919,0.161709,0.437139,0.127098,-0.340852,0.373424,-0.083857,-0.612938,-0.269709,-0.455246,-0.471181,-0.107275,0.333657,0.176262,0.051534,0.356314,-0.156123,-0.163217,-0.524425,-0.051728,-0.262763,-0.207184,-0.235462,-0.698970,0.032467,-0.244653,-0.320105,-0.095320,-0.126127,-0.164974,0.488448,-0.861482,0.185167,0.442672,0.075883,-0.161964,0.460962,0.096540,0.178035,-0.064650,-0.389956,0.420340,0.234277,0.225512,0.289246,0.474589,-0.093507,-0.073100,-0.264964,0.373326', '3119246', '1793491', '1307442', '1298095');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27179039', '朱迪', '剧情', '故事开始于20世纪30年代的好莱坞，14岁的朱迪（蕾妮·齐薇格 Renée Zellweger 饰）因为其甜美的嗓音而被经纪人梅耶（理查德·科德里 Richard Cordery 饰）看中，就此走上了星途，但此时的朱迪并不知道的是，等待着她的，除了功成名就所带来的的名声和财富之外，更多的是痛苦。 时间来到几十年后，已经40岁的朱迪同丈夫西德尼（卢夫斯·塞维尔 Rufus Sewell 饰）离了婚，独自抚养两个孩子罗娜（贝拉·拉姆齐 Bella Ramsey 饰）和乔伊（勒温·劳埃德 Lewin Lloyd 饰），经济状况十分的糟糕。无奈之下，朱迪做了一个决定，那就是将两个孩子留给前夫，自己前往英国继续打拼事业，可是此时的朱迪的健康情况已经非常的糟糕了，更糟的是，她早已经失去了粉丝们的信任。©豆瓣', '蕾妮·齐薇格', '鲁伯特·古尔德', 7.6, 36122, 'tt7549996', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561885281.jpg', 0.4, 2.4, 33, 47.8, 16.5, '0.298927,-0.026447,-0.606697,0.513713,-0.285235,-0.418904,0.726211,0.318051,-0.548343,-0.277668,-0.131846,0.792508,0.045659,0.527504,0.166911,0.010254,-0.485440,-0.833287,-0.089661,-0.190768,-0.156661,-0.647019,-0.197087,-0.170046,-0.250826,-0.503337,0.586734,0.094869,0.045266,0.390400,0.407758,0.416866,0.272172,0.382246,-0.178787,0.047790,0.279322,-0.224851,-0.209429,0.155449,0.302179,-0.144842,-0.041071,0.310179,0.143384,0.399309,0.494026,-0.296113,-0.135533,-0.084676,0.535525,-0.323023,-0.030755,0.182721,0.224194,-0.322122,0.406092,0.159075,-0.428929,-0.058479,0.228344,-0.310779,-0.784737,0.182364,0.120924,0.203614,-0.854102,0.338849,-0.278746,-0.225635,0.216308,-0.493906,0.247057,0.593676,0.016885,0.475266,-0.329594,0.002019,-0.457598,0.135033,0.666886,0.191730,-0.267535,0.465681,-0.311125,-0.404214,-0.202592,-0.302756,-0.607446,0.027565,0.400766,0.089559,0.061867,0.191677,-0.386544,-0.023254,-0.386952,-0.433806,-0.016921,-0.453815,-0.100610,-0.541746,-0.266804,-0.657948,-0.503357,0.002790,0.081744,-0.346199,0.806915,-0.609494,0.184823,0.270124,0.192084,-0.527773,0.619595,-0.115248,0.345166,-0.093764,0.059529,0.476533,-0.225994,-0.096313,0.135282,0.378539,-0.033596,-0.356708,-0.296365,0.653985', '30162520', '1783461', '4301215', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27179199', '本回家了', '剧情', '影片故事发生在24小时之内，男主角Ben Burns富有魅力但又烦恼缠身，某个灾难性的圣诞节前夕，他回到了毫不知情的家里。母亲Holly Burns小心谨慎但热烈欢迎了她深爱的儿子，但随后发现他依旧存在着很大的问题，在这可能改变他们一生的24小时之内，母亲要竭尽所能避免家庭分崩离析。万斯将饰演本的继父，他自己有一套教育孩子的方法，因此与Holly发生了直接矛盾。凯瑟琳·牛顿饰演17岁的妹妹Ivy Burns，是位漂亮的歌手，热爱兄长，但不相信他能够变为一个更好的人，不喜欢他对家庭造成的影响，但明白他对母亲的重要性，也知道应该帮助他走入正轨。', '朱莉娅·罗伯茨', '彼得·赫奇斯', 7, 6081, 'tt7545524', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2537465672.jpg', 0.4, 4.6, 48.2, 39.9, 6.8, '0.100268,0.115714,-0.869838,0.452324,-0.370539,0.286115,0.806754,-0.097555,-0.632251,-0.365752,0.233103,0.965060,0.107897,0.156835,0.216757,0.165849,-0.185879,-0.552569,0.339916,-0.237517,-0.211599,-0.723051,-0.195611,-0.383922,-0.053779,-0.389313,0.412315,0.184553,-0.190557,0.176600,0.227755,0.109869,0.406808,0.622186,0.089195,0.243462,-0.315601,0.038213,-0.135181,0.242347,0.324037,-0.100190,-0.100051,0.367553,-0.153182,0.405600,0.661061,-0.192431,-0.714539,-0.040078,0.762271,-0.431602,-0.159428,0.170381,0.225812,0.077274,0.137227,0.286691,-0.054267,-0.230805,0.069701,-0.223937,-0.526875,-0.009405,0.080312,0.172196,-0.685673,0.676776,-0.055056,-0.236614,-0.007281,-0.145126,0.210193,0.588261,0.445378,0.265863,-0.410825,0.120432,-0.698589,0.160818,0.909769,-0.033586,-0.442000,0.629144,-0.650150,-0.517483,-0.242614,-0.702104,-0.693481,0.145312,-0.024103,0.392251,-0.443692,0.131209,0.080278,0.147287,-0.099257,-0.109795,-0.120219,-0.691243,0.105534,-0.110750,-0.304377,-0.678752,-0.358042,-0.113670,-0.094909,-0.652308,1.041084,-0.924544,0.226742,0.587871,0.646603,-0.874828,0.980107,0.350255,0.246572,-0.285534,-0.041682,0.306936,-0.198541,-0.102888,-0.137769,0.196392,0.267157,-0.194787,-0.297810,0.326041', '1303112', '3504940', '1309161', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27179288', '血色天劫', '动作', '恐怖分子企图劫持横越大西洋的夜间班机，身怀怪病的女子因而被迫亲上火线。为了保护儿子，她必须让黑暗的祕密曝光，释放出她一直设法压抑在体内的怪物。', '佩莉·鲍麦斯特', '彼得·图万斯', 6.4, 19349, 'tt6402468', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2665626425.jpg', 2.7, 14.2, 50.1, 25.7, 7.3, '-0.255032,0.178891,-0.787758,0.720689,-0.090820,0.155735,0.579855,-0.059893,-0.454193,-0.034016,0.489589,0.255047,0.077105,-0.153933,0.265247,0.169415,-0.072334,-0.516434,0.042359,-0.112772,-0.460467,-0.050367,-0.370859,-0.171812,0.088439,-0.787572,0.673542,0.483596,-0.398116,-0.390979,0.166561,0.409727,-0.526927,0.464670,-0.210819,-0.582568,-0.446486,-0.313497,-0.194551,0.176441,0.154310,-0.536661,0.248681,0.054323,-0.141048,0.318445,0.609107,-0.182822,0.120401,-0.288654,0.039283,-0.419915,0.022175,-0.082864,0.211225,-0.040767,0.258143,-0.124015,-0.316165,-0.296847,-0.047419,0.313663,-0.647388,-0.072534,0.173107,-0.270646,-0.048237,-0.028420,-0.051060,0.316748,0.383205,-0.198563,-0.100644,0.160343,-0.290739,0.015817,-0.475056,0.203111,-0.600202,-0.173006,0.446039,-0.439489,-0.102476,-0.209480,-0.435709,0.087592,0.325786,-0.515733,-0.270190,-0.213107,0.551668,0.380926,-0.756822,0.371537,-0.244186,-0.339778,-0.524223,0.097973,-0.052096,-0.473385,-0.096120,-0.387990,0.191867,0.111027,0.291772,-0.053813,0.102585,-0.135606,0.356821,-0.485001,0.447399,1.313501,0.415090,-0.670385,0.169931,-0.011685,0.307012,-0.112124,-0.020701,0.394818,0.240679,0.625482,0.045325,0.157111,-0.230761,0.533703,-0.339415,0.402189', '4190211', '26277361', '26365236', '27018354');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27179414', '人间·喜剧', '喜剧', '平时靠当主播为生的小人物濮通（艾伦 饰）生活进入困境，老板拖欠三个月的工资，导致他连房租都交不起，因此遭到老婆米粒（王智 饰）的奚落。老婆找到公司讨薪，他仓皇失措跑到公司赶走老婆，随后找到经理索要工资。谁知眼看到手的钱，却被公司背后的金主杨台竣（金士杰 饰）的儿子杨小伟（鲁诺 饰）抢走。杨小伟是一个典型的浪荡无度的富二代，他每日花天酒地，挥金如土，由于老爹恼怒他的放纵，并进而拒绝给他钱，所以债台高筑的小伟遭到巴爷（任达华 饰）的威胁。此后，紧追不放的濮通跟小伟回到家中，小伟干脆假装被对方绑架，怂恿濮通向杨台竣索取高额赎金。然而，事情最终朝着不可预料的方向发展……©豆瓣', '艾伦', '孙周', 3.3, 32107, 'tt9887130', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2551693460.jpg', 51.5, 34, 12.3, 1.6, 0.6, '0.172242,-0.026910,-0.391976,0.020354,-0.350830,-0.269265,0.324585,0.383415,-0.251463,-0.146290,0.060535,0.245184,0.181793,0.078187,0.178335,0.027738,0.104474,-0.408696,0.137278,0.017676,0.139588,-0.210361,0.238975,-0.188450,-0.276361,0.063410,0.300497,-0.037700,-0.126415,0.393829,0.374704,0.267347,0.095580,0.349131,0.009021,0.209036,0.109803,0.052714,-0.142481,0.358624,-0.121875,-0.197100,0.021962,-0.097150,0.195225,0.469436,0.392224,0.200138,-0.207729,-0.092775,0.319916,-0.284697,-0.308181,0.075316,0.170360,0.115674,0.315944,0.121750,-0.366064,0.085709,0.359433,-0.066908,-0.500280,-0.020784,0.001217,-0.048320,-0.640401,0.152107,-0.118075,0.069516,-0.059622,-0.423008,-0.060804,0.106460,0.008067,0.363935,-0.367041,0.334606,-0.734407,0.248391,0.396474,-0.209129,0.147620,0.144722,0.092215,-0.019644,0.202350,-0.409537,-0.500032,-0.022835,0.257041,0.085471,-0.187069,0.025911,-0.361375,-0.020428,-0.140699,-0.155853,0.118794,-0.473600,-0.289685,-0.420604,0.087466,-0.166440,-0.139423,0.233225,0.181416,-0.265505,0.064541,-0.250927,0.015547,0.499070,0.688314,-0.800743,0.455326,0.031245,-0.080707,-0.171933,-0.284665,0.139570,0.558487,0.304114,0.013058,-0.261664,0.104736,-0.357461,0.194703,0.229339', '1293908', '1302110', '1417543', '1299182');
