INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27180759', '送我上青云', '剧情', '盛男（姚晨饰），女，独立上进有追求，渴望真爱却仍孑然一身。一次意外发现自己患上了卵巢癌，需要进行手术，但父亲出轨，母亲幼稚，家庭给不了她可能的支持，她不得不接受一份自己不喜欢的工作去筹手术费。天生骄傲的盛男，在生死关头才发现成年人想生存的体面比想象中还艰难，在一次又一次的希望与绝望中，最终用自己的方式和世界和解。', '姚晨', '滕丛丛', 7, 183020, 'tt10097364', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2565751382.jpg', 1.3, 7.8, 41.3, 39.9, 9.8, '-0.273116,0.255964,-0.712751,0.666181,-0.530892,-0.269018,0.779668,-0.155029,-0.288317,-0.129633,0.043828,0.743899,0.337770,0.113396,-0.062817,-0.092418,-0.132636,-0.555296,0.391542,-0.034289,-0.516562,-0.471701,-0.346589,-0.422080,-0.315064,-0.231444,0.786097,0.245024,-0.298481,0.088645,0.350547,0.118872,0.194580,0.685812,-0.068837,-0.357079,-0.048697,0.413675,-0.427012,0.309321,0.491528,-0.215715,-0.302317,0.644364,0.164808,0.483756,0.566909,-0.247120,-0.615810,-0.162126,0.528648,0.091872,-0.328974,0.240137,0.039125,0.075045,0.315159,-0.050585,-0.043419,-0.261502,0.051844,0.024356,-0.867764,-0.335152,0.335386,-0.101591,-0.653056,0.619422,-0.113204,-0.083978,0.056890,-0.276533,-0.082419,0.241157,0.562012,0.593887,-0.393964,0.071167,-0.186656,0.167503,0.924416,0.151796,-0.452796,0.667910,-0.358462,-0.347032,-0.054995,-0.625944,-1.024257,0.212350,-0.095301,0.330752,-0.525269,0.177327,-0.203177,0.238510,-0.286879,0.055675,-0.016907,-0.348217,0.232045,0.013860,-0.040063,-0.248304,-0.307429,0.130684,0.338232,-0.811577,0.720963,-0.760002,0.300524,0.542613,0.658179,-0.826541,0.760270,0.549441,-0.010524,-0.480218,-0.051065,0.222304,-0.167778,-0.103396,0.159525,0.194651,-0.186777,0.076028,-0.439850,0.532405', '1494897', '1877596', '6874741', '1304977');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27185558', '在乎你', '爱情', '国内知名女设计师袁元（俞飞鸿 饰），日本留学归国，气质出众，事业成功，多年的合伙人雷鸣也对她照顾有加。然而，看似人生赢家的袁元，内心深处却始终隐藏着一个难以放下的心结。在遇到事业瓶颈时，一位日本女孩（木下彩音 饰）的突然出现打破了袁元原本风平浪静的生活，一段关于北海道的神秘往事也随之展开……', '俞飞鸿', '毕国智', 5.4, 4805, 'tt10449116', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2552608202.jpg', 10, 34.8, 36.9, 14, 4.3, '0.208938,0.232980,-0.610223,0.649196,-0.098653,-0.354704,0.647839,0.074118,-0.644760,-0.519539,0.332753,0.757170,-0.099031,0.505703,0.237511,-0.142643,-0.047456,-0.590265,0.201623,-0.119575,0.177640,-0.042229,-0.685842,0.113467,-0.319571,-0.347967,0.710360,0.298985,-0.210375,0.497085,0.124675,0.334727,-0.263423,0.544297,0.040745,-0.365946,0.125146,0.363403,-0.435121,-0.001086,-0.080121,-0.362176,-0.185476,0.104118,-0.278481,0.271368,0.459744,0.009029,-0.285044,0.098144,0.686659,-0.119465,-0.166355,-0.104935,0.436168,0.152530,-0.018612,0.356412,-0.290782,-0.120418,0.115789,-0.193266,-0.262758,-0.130068,0.182761,0.254215,-0.487482,0.423221,0.052108,-0.079104,-0.135801,-0.408297,-0.042028,0.300536,0.521324,0.222461,-0.132702,0.615523,-0.174156,0.384533,0.715400,0.006819,-0.639640,0.253707,-0.193485,-0.332206,-0.116709,-0.292008,-0.604717,-0.101951,0.028853,0.097270,-0.080099,-0.030924,-0.416383,0.294220,-0.178807,-0.024179,0.139331,-0.261165,-0.174554,-0.556938,-0.322423,-0.558877,-0.484608,0.154696,0.190235,-0.109618,0.991204,-0.689191,0.233877,0.389153,-0.029605,-0.359164,0.423393,0.242118,0.001309,-0.384490,-0.189883,0.604831,-0.358496,-0.181002,-0.421786,0.190649,-0.489241,-0.232779,-0.347591,0.332680', '25922902', '27602116', '3811356', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27185563', '日日是好日', '剧情', '典子（黑木华 饰）是一名20岁的女大学生，每天过着浑浑噩噩随波逐流的日子的典子，对于自己的未来充满了迷惘。在母亲的介绍之下，典子和表姐美智子（多部未华子 饰）一起来到了家附近的一间茶道教室里学习茶道，这是典子第一次踏入这个对她来说陌生而又神秘的领域。负责授课的老师是一位名叫武田（树木希林 饰）的老太太，典子有些害怕这位稍显严厉的老师。然而，随着时间和学习进度的推移，典子渐渐从茶道的知识中领悟到了人生的道理。期初那些她并不是很理解的繁文缛节，也在无形之中抚平了她焦躁的内心。©豆瓣', '黑木华', '大森立嗣', 8.2, 48317, 'tt7575778', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2529177999.jpg', 0.2, 1.2, 17.8, 48.7, 32, '0.414202,0.019520,-0.505191,0.686051,-0.185918,-0.237203,0.876712,-0.033276,-0.664789,-0.780242,-0.003264,0.628358,-0.041083,0.653724,0.312066,-0.044332,-0.105587,-0.528629,-0.257005,-0.321168,-0.283452,-0.585173,-0.092809,-0.039449,-0.273325,-0.399371,0.565764,0.049101,-0.231595,0.683546,0.034198,0.285602,0.136749,0.437478,-0.124902,-0.013954,0.197141,0.117903,-0.002441,-0.102924,0.140475,-0.309954,-0.221408,0.049908,0.062626,0.359178,0.575055,-0.109584,-0.267524,0.124919,0.433313,-0.208440,-0.277972,0.198450,0.375278,0.078604,0.078828,0.190632,-0.251942,0.254404,-0.304819,-0.245373,-0.593413,0.045046,0.222240,0.172972,-0.663334,0.473762,0.145640,-0.383415,0.035858,-0.424619,0.144747,0.143089,0.122494,0.520582,-0.299294,-0.061349,-0.148146,0.127050,0.586453,0.200420,-0.172517,0.547870,-0.542352,-0.380093,-0.062312,0.044106,-0.569655,-0.149959,-0.109701,0.278832,-0.054630,0.153729,-0.524232,0.101751,0.049092,-0.253827,0.055523,-0.415485,-0.121607,-0.554824,-0.206767,-0.938866,-0.441321,-0.094695,0.136524,-0.419727,1.045975,-1.095532,0.108787,0.349516,0.142633,-0.287341,0.708637,0.141521,-0.065411,-0.123359,-0.265827,0.154820,-0.184344,0.306656,-0.109511,0.760223,-0.078966,-0.277950,-0.446032,0.572828', '1292219', '1390020', '25922902', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27186348', '春潮', '剧情', '报社记者郭建波、母亲纪明岚与女儿郭婉婷同住在一个屋檐下，祖孙三代因亲情关系捆绑在一起的生活，看似平静实则暗潮涌动。记者郭建波在报导社会负面事件的同时，也在揭开自己身上的伤疤；母亲纪明岚在外为人热情，受人爱戴，但是回到家却判若两人；女儿郭婉婷小小年纪就学会了成人世界里的种种生存法则。一次次的叛逆与反抗都在隐忍中归于平静，一场悄无声息的战争在三代人之间暗自滋生，终将爆发……', '郝蕾', '杨荔钠', 7.1, 71563, 'tt10428252', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2559868455.jpg', 0.9, 5.3, 41, 43, 9.8, '0.100729,0.185012,-0.848547,0.527791,-0.234426,-0.129380,0.901373,0.164693,-0.714119,-0.169244,0.211725,0.664424,-0.299950,0.371883,0.029365,-0.636348,-0.333612,-0.867445,-0.038358,0.052036,0.101157,-0.336477,-0.090302,-0.205283,-0.221469,-0.492686,0.919467,0.416648,-0.183548,0.328616,0.027769,0.107915,-0.641616,0.700284,-0.173296,-0.124465,-0.238075,0.158533,-0.529412,-0.211585,-0.065009,-0.310830,-0.055024,0.216162,-0.009306,0.221756,0.816432,-0.373429,-0.020951,0.048227,0.405325,-0.095509,-0.189870,0.212835,0.425017,0.153790,0.269235,0.364678,-0.138057,0.044156,0.184459,-0.030875,-0.420699,-0.222249,0.118141,0.274646,-0.651956,0.990547,0.298400,-0.285326,-0.230937,-0.165118,0.070086,0.228990,0.271433,0.741631,-0.436151,0.081647,-0.099479,-0.081327,0.854512,-0.028674,-0.363672,0.387532,-0.549674,-0.098395,-0.096194,-0.411281,-0.769796,-0.666822,-0.013007,0.083586,-0.268710,1.036294,-0.541890,0.085567,-0.061506,0.234229,0.083333,-0.668593,-0.066137,-0.386629,-0.569050,-0.273336,-0.236344,0.208656,0.337047,-0.313047,0.606203,-0.770787,0.455113,0.246572,0.275076,-0.469787,0.506447,0.245818,0.222090,-0.173609,-0.226430,0.381181,0.019308,0.107923,0.071442,0.251293,-0.491840,0.535702,-0.223459,0.751368', '26245360', '2365260', '1305666', '1472510');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27186354', '灵能百分百 REIGEN', '动画', '平凡的中学二年级少年影山茂夫，因其微弱的存在感与名字茂夫的谐音被周遭人称为龙套（モブ）（路人），但不起眼的他其实是强大的天生超能力者。历经每一次的成长，龙套开始认为自己的超能力是危险的存在，为了不让超能力失控，龙套无意识的压抑著情感。虽然只想平凡的度过每一天，但各种麻烦却接二连三找上他，随着被压抑的情感在内心一点点膨胀，龙套体内积累的力量似乎也正蠢蠢欲动……', '伊藤节生', '立川让', 8.9, 9037, 'tt10317978', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2507179835.jpg', 0.2, 0.9, 9.6, 33.7, 55.6, '0.123431,0.174130,-0.788238,0.588955,-0.151533,0.129420,0.962935,0.007006,-1.008050,-0.435119,0.079009,0.357160,-0.124814,0.236008,-0.083262,-0.090834,0.122922,-0.479183,0.045353,0.009457,-0.295542,-0.044787,-0.470008,-0.199692,-0.380916,-0.527240,0.897014,0.486049,-0.548831,0.276530,0.100766,0.510504,0.008260,0.498975,-0.165438,-0.270367,-0.248988,-0.092590,0.068158,-0.272314,0.128123,-0.209746,0.037452,0.217072,-0.197627,0.382666,0.613574,-0.165323,-0.224273,0.034592,0.477942,-0.174399,-0.314714,0.117080,0.010699,0.384444,0.420882,-0.051103,0.328576,0.016274,-0.047003,0.052214,-1.132409,-0.010030,0.298672,0.285907,-0.345699,0.491694,0.054358,-0.279340,-0.010430,-0.059739,-0.162086,-0.208592,0.229757,0.398350,-0.442745,-0.064491,-0.182972,-0.119336,0.802452,0.033347,-0.835049,0.548668,-0.619182,-0.445402,-0.275406,-0.495460,-0.440240,0.013201,-0.003633,0.699864,-0.271454,0.343070,-0.549736,0.369902,-0.047978,0.187690,-0.229846,-0.513973,-0.188719,-0.213689,-0.251028,-0.396199,-0.235349,0.037816,0.193986,-0.431102,0.900143,-0.734067,0.372590,1.037551,0.204040,-0.288512,0.394992,-0.099722,-0.105717,-0.255865,-0.007474,0.326528,-0.203930,0.342587,0.065371,0.324624,-0.347663,0.234944,-0.293672,0.961371', '26667010', '25932086', '1308784', '26871938');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27186368', '希望沟壑', '剧情', '格雷斯（安妮特·贝宁 Annette Bening 饰）和丈夫爱德华（比尔·奈伊 Bill Nighy 饰）结婚已经二十九年之久了，在这几十年里，格雷斯一直非常庆幸自己选择了爱德华这样一个好男人来做自己的丈夫，然而，就在他们的第二十九个结婚纪念日即将到来之际，格雷斯突然被爱德华告知后者已经做好了离婚的打算，并且找到了下家。这突如其来的婚姻变故让格雷斯的生活发生了翻天覆地的变化，爱德华想要离婚的心思坚定不移，格雷斯除了要面对自己心灵上的地震之外，还要处理琐碎的离婚事宜。在离开了丈夫之后，自己将如何一个人生存下去也成为了了格雷斯必须要面对的问题。©豆瓣', '安妮特·贝宁', '威廉姆·尼克尔森', 8.2, 8623, 'tt7587876', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2581064876.jpg', 0.3, 1.2, 17.4, 52.7, 28.3, '0.167071,-0.003953,-0.989662,0.472054,-0.300111,-0.507903,0.708184,0.054236,-0.371786,-0.420459,0.008623,0.778954,-0.146747,0.220769,0.334416,0.128507,-0.352457,-0.935973,0.120571,-0.231736,-0.511296,-0.587799,-0.100051,-0.311501,-0.193308,-0.091362,0.399667,-0.032834,0.277898,0.179071,0.394796,0.122797,0.388472,0.777967,-0.173093,0.272528,0.013690,-0.047003,-0.412453,0.314844,0.273154,-0.197160,-0.059056,0.462193,0.082906,0.553912,0.370732,-0.159174,-0.172704,-0.055232,0.345709,-0.267316,-0.031819,0.436459,0.238461,-0.202073,0.035649,0.464112,-0.500099,-0.078161,0.249388,-0.144385,-0.726701,0.106984,-0.127566,0.167379,-0.874756,0.311164,-0.128385,0.052945,0.209666,-0.572632,0.381883,0.723802,0.485145,0.351863,-0.459608,0.056643,-0.542898,0.040087,0.914322,0.037752,-0.076208,0.395034,-0.049104,-0.320309,-0.238532,-0.066124,-0.436638,-0.033631,0.255328,0.167228,-0.434969,0.370003,-0.366749,-0.270310,-0.367388,-0.331922,-0.201142,-0.538586,-0.026774,-0.290526,-0.166973,-0.373208,-0.651102,0.195356,0.019531,-0.408613,0.458496,-0.720235,0.214840,0.492594,0.411676,-0.646957,0.411974,0.276299,0.516009,-0.139049,0.235188,0.198818,-0.085313,0.386376,0.052463,0.378993,0.384482,0.008604,-0.275033,0.739620', '35461732', '1306801', '1301022', '1292064');
