INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27191173', '恋如雨止', '剧情', '橘晶（小松菜奈 饰）是一名17岁的女子高中生，和同龄的女孩不同，橘晶有着超越了年龄的沉稳，以及稍许的冷漠。课余时间里，橘晶在一家家庭餐厅打工，店长近藤正己（大泉洋 饰）是橘晶的上司。正己是一个邋邋遢遢的中年男子，性格迷迷糊糊又有些天然的他常常在无意之中令橘晶脸红心跳。是的，橘晶喜欢上了这位年长她二十几岁的男性，即便正己曾经有过一段婚姻，还有一个孩子，橘晶依然无法抗拒他的吸引，而对橘晶汹涌的感情，正己似乎毫无察觉。曾经，橘晶是学校田径队的王牌，但因为不明原因而选择了退部，得知了这一信息的正己开始鼓励橘晶重拾跑步的爱好。©豆瓣', '小松菜奈', '永井聪', 7.4, 16729, 'tt7637350', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2511831665.jpg', 0.8, 3.7, 36.1, 43.3, 16.1, '0.467346,-0.133136,-0.500093,0.662583,-0.543297,-0.264772,0.875832,0.231423,-0.625064,-0.466919,0.126999,0.929560,-0.029242,0.480655,0.173152,-0.075977,0.143836,-0.459778,-0.252118,-0.203191,-0.247641,-0.585160,-0.256862,0.094449,-0.246882,-0.670426,0.583397,-0.127983,-0.280718,0.581387,0.537907,0.220770,0.143862,0.399034,-0.306726,-0.182015,0.063389,0.135850,0.194509,-0.024273,0.066468,-0.330391,-0.173399,0.357950,-0.186474,0.762969,0.544374,-0.020513,-0.513590,0.103128,0.568463,0.036136,-0.340980,0.045202,0.374253,0.054213,0.187065,0.053336,-0.091578,0.037618,0.099361,0.018027,-0.537971,-0.080106,0.262582,0.341115,-0.611381,0.668900,0.112073,-0.335165,0.223842,-0.160767,0.053108,0.081364,0.072369,0.461135,-0.149663,-0.035075,-0.462114,0.185377,0.601698,0.343088,-0.444158,0.517223,-0.745492,-0.349015,-0.012737,-0.455884,-0.681898,0.019610,-0.021872,0.086760,-0.268906,-0.045333,-0.377193,0.260875,0.102894,0.041205,-0.003664,-0.248066,-0.234408,-0.266501,-0.381271,-0.969730,-0.333408,0.114487,0.098035,-0.249853,1.071701,-1.164164,-0.024926,0.481539,0.237340,-0.471611,0.850435,0.191307,-0.217915,-0.312133,0.028876,0.096953,-0.162808,-0.020197,-0.263012,0.581595,-0.267179,-0.194741,-0.293485,0.582141', '1390020', '1292720', '3445516', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27191431', '过春天', '剧情', '单亲家庭出身的16岁女学生佩佩（黄尧 饰），她的城市既是香港、也是深圳，白天在香港上学，晚上回到深圳跟妈妈（倪虹洁 饰）住在一起，频繁地穿梭于两地。为了和闺蜜Joe（汤加文 饰）一起旅行的约定，为了自己的存在感，为了对Joe男友阿豪（孙阳 饰）懵懂的好感，她内心的冲动被点燃，“水客”成为了她的另一个身份，一段颇有“冒险”感的青春故事就此开始。©豆瓣', '黄尧', '白雪', 7.7, 307369, 'tt8875366', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2549537782.jpg', 0.2, 1.8, 27.2, 56.8, 14, '0.334871,0.035213,-0.597940,0.466829,-0.193669,-0.052723,0.541030,0.185869,-0.649313,-0.363793,-0.116231,0.955088,-0.197692,0.683664,0.112228,-0.079175,-0.104734,-0.683946,0.111576,-0.176258,-0.013114,-0.248105,-0.118435,-0.100737,-0.034514,-0.130070,0.607131,-0.019428,-0.167680,0.567681,0.297697,0.285833,-0.144627,0.357134,-0.253018,-0.072849,-0.117390,0.257116,-0.430271,0.052469,0.062116,-0.199547,-0.007167,0.017548,0.215436,0.239845,0.926248,0.218968,-0.124905,-0.055944,0.412470,-0.133323,-0.141680,-0.134848,0.165866,0.127363,0.480200,0.210494,-0.026644,0.064748,0.153669,-0.260008,-0.506853,0.380079,0.442043,0.099890,-0.495690,0.488957,-0.270990,-0.334865,0.245801,-0.343257,0.147524,0.328013,0.131594,0.537453,-0.174469,0.090584,-0.410063,0.214196,0.778872,0.117475,-0.060274,0.324082,-0.422913,-0.313214,0.081137,-0.025789,-0.465538,-0.126906,0.035939,-0.111197,-0.288981,0.132463,-0.961448,0.202283,0.025240,0.151944,0.076619,-0.354135,0.079327,-0.336529,0.044814,-0.725987,-0.227843,-0.103129,0.238060,-0.101600,0.715802,-0.948825,0.185834,0.729889,0.574608,-0.764751,0.796809,0.359479,-0.059606,-0.340240,0.298573,0.258188,-0.385537,0.101441,-0.122981,0.188784,-0.163621,-0.113472,-0.424533,0.541854', '1292219', '3445516', '3055049', '1309161');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27191829', '初吻50次', '喜剧', '热衷于观察星空的日本青年弓削大辅（山田孝之 饰），在夏威夷盘桓期间干着兼职导游的工作。利用工作之便，这个花花心肠的男子恣意游走花丛，乐在其中。某天，他在一家餐厅邂逅了美丽女孩藤岛瑠依（长泽雅美 饰）。瑠依专注的样子令大辅分外痴迷，当再次见面时他鼓起勇气上前搭讪。对于这位情场老手来说，一切进展得顺风顺水。可是次日见面时，瑠依却对大辅冷眼相对。原来，这个女孩十年前曾遭遇一场车祸，导致她无法保有当下的记忆，永远活在车祸前的那一天。固执而不认输的大辅对女孩展开了执着的追求，他百折不挠，屡败屡战。他不希望只是拥有当下的激情，而是希望可以和心中的爱人走到永远……本片翻拍自美国同名影片。©豆瓣', '山田孝之', '福田雄一', 6.9, 7268, 'tt6916872', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2513056531.jpg', 0.9, 8, 46.8, 31.2, 13, '0.030926,0.062797,-0.785956,0.520020,-0.134836,-0.484809,0.680205,0.070196,-0.296385,-0.341577,0.241323,0.563379,-0.223577,0.313575,0.347837,0.077215,-0.262954,-0.748834,-0.184461,0.025570,-0.004564,-0.266881,-0.042438,-0.023846,-0.344127,-0.003471,0.709124,0.173076,-0.078106,0.606595,0.109275,0.248866,0.029598,0.582022,-0.208639,-0.188590,-0.064831,0.247923,-0.374158,0.186077,0.222596,-0.306207,-0.254408,0.198148,-0.049291,0.065774,0.789208,-0.123166,-0.437162,-0.118338,0.327601,-0.087864,-0.095275,0.046769,0.118680,-0.050615,0.213026,0.053181,-0.000243,-0.194274,-0.000320,-0.082892,-0.468293,0.083684,-0.191796,0.115577,-0.395236,0.368263,-0.025936,-0.004793,0.158419,-0.251164,-0.102107,0.280933,0.517723,0.109595,-0.196453,0.168434,-0.270768,0.212847,0.596487,0.274505,-0.216452,0.898820,-0.118305,-0.250963,-0.023963,-0.143768,-0.661862,0.081343,-0.115894,-0.017100,-0.168540,0.194807,-0.435123,0.105961,-0.046891,0.149160,0.178448,-0.396377,-0.291108,-0.506778,-0.165372,-0.584703,-0.513957,0.095998,0.123314,-0.324934,0.688668,-0.882717,0.190057,0.617649,0.095287,-0.471448,0.751326,0.235035,-0.177284,-0.295170,0.014490,0.562042,-0.129577,0.269511,-0.080433,0.161507,-0.077369,-0.006724,-0.415100,0.516844', '34973399', '26354526', '2027925', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27193043', '一条狗的回家路', '剧情', '某日，善良的男孩卢卡斯（乔纳·豪尔-金 Jonah Hauer-King 饰）在一幢废弃的大楼里遇见了一只孤零零的小狗，虽然卢卡斯的母亲禁止他养宠物，但是不忍心看到小狗无人照料的卢卡斯还是将小狗带回了家并取名为贝拉，就这样，贝拉成为了卢卡斯家中新的一员。某日，卢卡斯的母亲带着贝拉前往退伍军人医院看病，哪知道贝拉不仅没有给她惹麻烦，反而还给医院里原本郁郁寡欢的病人们带来了快乐，很快，贝拉就成为了医院中的人气明星。一场意外让卢卡斯不得不将贝拉寄养在朋友家中，并不理解主人的用意的贝拉决定离家出走，依靠自己的勇气和智慧和主人重聚。©豆瓣', '艾什莉·贾德', '查尔斯·马丁·史密斯', 6.8, 38009, 'tt7616798', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2545487478.jpg', 0.7, 7.5, 52.1, 29.3, 10.4, '0.304113,0.227915,-0.657684,0.459267,-0.337604,-0.398240,0.805011,0.217289,-0.427446,-0.272347,-0.030027,0.818720,0.112935,0.614844,0.251957,0.214732,-0.385370,-0.352752,0.034237,-0.074405,-0.204159,-0.470299,-0.320995,-0.375332,0.038871,-0.265495,0.441817,-0.058267,0.062599,0.470807,0.170942,0.233404,0.017495,0.466332,-0.319704,0.229112,0.152818,0.223687,0.039586,0.313431,0.195097,-0.135646,0.102040,0.364380,0.271551,0.292174,0.606627,-0.427779,-0.098365,-0.320452,0.143416,-0.095495,0.173537,0.208694,0.143939,-0.128583,0.385742,0.044220,-0.370572,0.169518,0.163995,-0.182984,-0.647600,0.016445,0.104957,0.169210,-0.744487,0.488712,-0.062437,-0.053189,0.179323,-0.264171,0.183491,0.075842,0.042079,0.485360,-0.170111,0.196559,-0.525441,-0.055148,0.492791,-0.390376,0.067751,0.389843,-0.293953,-0.338632,0.356993,-0.083125,-0.726374,-0.002247,0.233498,0.076990,-0.251996,0.054904,-0.533405,-0.187991,-0.540676,-0.269582,-0.031569,-0.437323,0.232506,-0.390224,0.267719,-0.134711,-0.208732,-0.154445,0.158270,-0.191169,0.668328,-0.764759,0.354384,0.491187,0.466706,-0.421419,0.652391,-0.047853,0.337935,-0.195123,0.061490,0.251010,0.312728,0.272763,0.325521,0.209118,0.021183,-0.244961,-0.422688,0.693221', '24698878', '1299965', '3055049', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27194336', '神弃之地', '剧情', '该片是一部中西部哥特风电影，安东尼奥·坎帕斯(《克里斯汀》)执导，讲述俄亥俄州偏远之地Knockemstiff，男主角Willard Russell绝望地想拯救濒死的妻子，不惜屈服于牺牲，而他的儿子(霍兰德)正从一个在学校被虐待的孩子成长为知道何时出手的男人，角色包括一对连环杀手夫妇、一个考验人的信仰的传教士、一个腐败的当地警长(斯坦)。时间从二战末期到1960年代，地点从南俄亥俄州乡村到西维吉尼亚。', '汤姆·赫兰德', '安东尼奥·坎波斯', 7.1, 19832, 'tt7395114', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2619322729.jpg', 0.9, 6, 43.1, 38.7, 11.4, '0.129881,-0.238172,-0.486318,0.615993,-0.073963,-0.329952,0.489771,0.246262,-0.403616,-0.174737,0.452889,0.948379,0.051375,0.012356,0.523119,0.010352,-0.221065,-0.466592,-0.176377,-0.106160,-0.352591,-0.241651,-0.112263,-0.447743,0.042053,-0.691961,0.613276,0.259908,-0.162421,0.102991,0.201353,0.342556,-0.190326,0.106660,-0.055671,-0.044083,0.327051,-0.243101,-0.400054,0.456372,-0.186560,-0.093338,-0.230992,0.118273,-0.239641,0.468140,0.775935,-0.010252,0.295178,-0.185075,0.489459,-0.276125,-0.340461,-0.024660,0.337815,-0.381460,0.048324,0.002760,0.082446,-0.161749,0.008680,-0.417966,-0.733059,0.025924,-0.140199,0.132926,-0.613739,0.332096,-0.107205,0.043857,0.135798,-0.594961,-0.000775,0.030426,0.100662,0.665491,-0.185192,-0.047858,-0.373811,0.367543,0.727958,-0.253943,-0.163293,0.175031,-0.202913,-0.515543,-0.189780,-0.302558,-0.772988,-0.094283,0.465575,-0.487484,-0.291591,0.285401,-0.380450,-0.154259,-0.594194,-0.203155,0.244946,-0.294456,-0.343295,-0.582515,-0.015240,0.017509,0.097549,-0.088481,0.273107,-0.283344,0.713408,-0.632275,0.308702,0.813573,0.134415,-0.213524,0.681880,0.037258,0.076495,-0.509569,-0.064552,0.625776,0.131884,0.143758,-0.074001,0.169706,-0.297534,-0.093490,-0.181759,0.523739', '1460341', '34890458', '4071762', '26593587');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27195078', '急先锋', '动作', '中国商人秦国立在英国惨遭雇佣兵组织“北极狼”绑架，秦的女儿Fareeda（徐若晗 饰）也卷入其中，遭到追杀。千钧一发之际，急先锋国际安保团队成为他们唯一的希望，由总指挥唐焕庭（成龙饰）带领雷震宇（杨洋饰）、张凯旋（艾伦饰）、弥雅（母其弥雅饰）、神雕（朱正廷饰）等组成的急先锋行动小组，上天入地，辗转全球各地施展惊险营救。解救人质的过程中，竟发现“北极狼”背后的犯罪集团还策划了一场惊天密谋……', '成龙', '唐季礼', 4.4, 77475, 'tt9695722', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2619027144.jpg', 23.2, 42.6, 27.7, 4.7, 1.9, '-0.247801,-0.008683,-0.741737,0.390593,0.344134,0.059703,0.008698,-0.034972,-0.380368,-0.299211,0.474467,0.367447,-0.027249,-0.172546,0.519006,-0.265113,-0.078609,-0.750826,-0.287346,0.366174,-0.079395,-0.062082,-0.579143,-0.290340,0.040006,-0.030861,0.627021,0.411313,-0.314051,0.599202,0.293311,0.462240,-0.668821,0.273977,0.194323,-0.287873,0.464250,-0.064312,-0.399578,0.206796,-0.520002,-0.395335,0.021154,0.092263,-0.136756,0.370743,0.604132,-0.321641,0.572537,-0.610655,0.056182,-0.661343,-0.044045,-0.293092,0.640071,0.119694,0.101313,0.075933,0.127020,-0.054924,-0.227488,-0.109739,-0.732707,-0.051416,0.484600,-0.106475,-0.456877,-0.100689,-0.084697,0.417419,0.212312,-0.065190,0.155895,0.537096,0.737102,0.102555,0.298475,0.421597,-0.487233,0.112159,0.645999,-0.483613,-0.133607,-0.463601,0.455833,-0.461736,0.283388,-0.268329,0.118364,-0.025750,0.297979,-0.277420,0.093086,0.115932,-0.493370,-0.043068,-0.525209,-0.118669,-0.006747,-0.190707,0.082381,-0.977038,0.007181,0.102782,0.117994,0.394789,0.205807,0.232821,0.435311,-0.424478,0.185662,0.453500,0.152021,-0.381607,0.244483,0.018353,0.426501,-0.252089,-0.051676,-0.187354,0.389908,0.121695,-0.005478,-0.139130,-0.146971,-0.173021,0.114616,-0.374037', '4014397', '2369613', '25723905', '11610281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27195080', '泄密者', '剧情', '马来西亚爆发神秘传染病，当地药业公司AMANAH研究的特效药MD5成为救助病患的神丹妙药。可是一直跟踪报道该疾病的记者宋丹文意外死亡，跟着AMANAH总裁张日善（郑则仕 饰）的儿子在办公室自杀身亡。经警方调查，张公子纯系他杀。与此同时，张公子的妻子彭珍美（周秀娜 饰）秘密跑到香港，她随身携带的机密引起多方势力的争抢。香港警察王大伟（吴镇宇 饰）与马来西亚皇家警察警长李永勤（张智霖 饰）接头，协助调查这一系列案件。不久后，王大伟收到一段视频，视频录制者自称“泄密者”指控AMANAH是绝命病毒的始作俑者，而张日善的二儿子更落到他们手中。与死神争分夺秒，李永勤和王大伟展开夺命追查……©豆瓣', '吴镇宇', '邱礼涛', 5.3, 28441, 'tt8490838', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2524686290.jpg', 5.7, 35.4, 48.8, 8.6, 1.4, '-0.022477,-0.117545,-0.308478,0.225019,0.230197,0.077524,0.240976,0.118305,-0.576279,-0.429670,0.337991,0.344774,-0.237974,-0.025289,0.119414,-0.176019,-0.341496,-0.549197,-0.040819,0.041843,-0.118345,-0.179675,-0.138261,-0.490304,0.172427,-0.151941,0.427371,0.057757,-0.265383,0.316557,0.300897,0.556157,-0.568396,0.217873,-0.009316,0.065519,0.379126,-0.011815,-0.605220,0.279923,0.276573,-0.345783,-0.044053,-0.090523,0.161420,0.254739,0.326933,-0.012017,-0.298144,-0.348238,0.516953,-0.508506,-0.072287,-0.011079,0.654781,0.168681,0.277737,0.399448,-0.304334,-0.418589,-0.011006,0.086396,-0.612989,-0.048826,0.174208,0.572003,-0.214891,-0.158727,-0.591414,0.245832,0.122698,-0.249994,0.366645,0.474015,-0.003189,-0.101846,-0.032107,-0.012918,-0.404393,0.497623,0.444539,-0.201928,-0.015891,-0.153610,0.291244,-0.487630,-0.130910,-0.019279,-0.270289,0.165915,0.354823,-0.114623,0.006001,0.107293,-0.401165,-0.375705,-0.245509,-0.125510,-0.020704,-0.108832,-0.244734,-0.840598,-0.092529,0.010271,-0.122742,-0.073486,0.355942,-0.026001,0.464537,-0.429946,0.168552,0.325081,0.082469,-0.756898,0.252360,-0.156715,-0.024876,-0.660415,-0.363886,-0.191209,0.456844,0.506718,0.063284,0.080681,-0.117624,-0.520999,-0.169216,-0.273212', '26996640', '2369613', '1305096', '27126336');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27195204', '卢斯', '剧情', '艾米（娜奥米·沃茨 Naomi Watts 饰）和皮特（蒂姆·罗斯 Tim Roth 饰）是一对富有而又善良的中产夫妻，十年前，他们领养了来自非洲战乱国家厄利垂亚的一位名为卢斯（小凯文·哈里森 Kelvin Harrison 饰）的男孩，卢斯曾经被作为童兵而接受了非常残酷的军事训练，艾米和皮特坚信，良好的教育和包容的爱能够帮助他找回自己善良的本性。一晃眼十年过去，卢斯无惊无险的成长为了一位正直有为的少年，过去在他身上刻下的烙印已经很淡了。卢斯的非裔老师哈雷特（奥克塔维亚·斯宾瑟 Octavia Spencer 饰）非常欣赏这位学生，认为他能够改变人们对于非洲国家和人种的刻板想象。©豆瓣', '娜奥米·沃茨', '朱利叶斯·约拿', 7.6, 6813, 'tt7616148', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2562070353.jpg', 0.7, 2.3, 27.5, 54.1, 15.4, '0.226408,-0.143977,-0.421669,0.658317,-0.398404,-0.342319,0.755639,0.102626,-0.511510,-0.201573,0.044261,0.853259,0.069629,0.130421,0.508124,0.358044,-0.324084,-0.584650,0.032099,-0.302433,-0.185561,-0.594466,-0.488502,-0.171724,-0.441523,-0.609371,0.695165,-0.000772,-0.238958,0.473635,0.186028,0.567276,0.453858,0.109672,-0.251844,-0.156565,0.004830,-0.204870,-0.303110,-0.019279,0.040866,0.147619,-0.101097,0.285866,-0.035256,0.239869,0.553239,-0.380645,-0.019916,-0.291882,0.414010,-0.192597,-0.005382,0.214316,0.208192,-0.115147,0.296904,0.225758,-0.161386,-0.314546,0.135713,-0.368202,-0.760598,0.004717,0.200415,0.118948,-0.737535,0.635987,0.016983,-0.153929,0.215886,-0.254942,-0.165941,0.379921,0.093752,0.568126,-0.074313,-0.024735,-0.418844,0.012536,0.467109,0.101847,-0.568073,0.313151,-0.556919,-0.507461,-0.031878,-0.404093,-0.720663,0.143803,0.233956,-0.112416,-0.165606,0.444367,-0.562854,0.060832,-0.525579,-0.156508,0.180359,-0.585140,-0.261807,-0.582912,-0.270266,-0.637009,-0.362608,-0.055967,-0.010811,-0.306153,1.075815,-1.048990,0.260795,0.451144,0.241000,-0.424169,0.716982,0.266575,-0.035215,-0.420130,-0.114271,0.780282,0.130886,0.045914,-0.008770,0.369273,0.000754,-0.068278,-0.295200,0.684974', '26348103', '1292720', '24284209', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27196380', '花滑女王', '剧情', '佳娜（阿格莱亚·塔拉索娃 Aglaya Tarasova 饰）出生在一个非常贫困的家庭之中，在母亲的鼓励和栽培下，佳娜成为了一名花样滑冰运动员，虽然佳娜的身体条件并不是非常适合这项运动，但凭借着自己的努力，佳娜最终成功的站在了世界顶级花滑男选手里奥纳夫（米洛斯·比柯维奇 Milos Bikovic 饰）的身边，成为了他的搭档。两人通过默契十足的合作夺得了许多耀眼的成绩，彼此之间也碰撞出了爱情的火花。花滑世界杯即将开始之前，佳娜不幸受伤，无奈只能告别赛场，里奥纳夫也因此离开了她。就在佳娜万念俱灰的时候，冰球运动员萨沙（亚历山大·佩特洛夫 Alexander Petrov 饰）成为了她坚强的后盾。©豆瓣', '阿格拉娅·塔拉索娃', '奥列格·特罗费姆', 6.7, 18330, 'tt5844488', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2517485270.jpg', 1.4, 10, 50.4, 30.4, 7.8, '0.121867,0.133829,-0.574767,0.541273,-0.157047,-0.458448,0.636819,0.310546,-0.336151,0.123106,0.299731,0.920303,-0.278491,0.216330,0.341389,-0.025225,-0.271491,-0.631691,0.221978,-0.070262,-0.347907,-0.584197,-0.227503,-0.045432,-0.245672,-0.504488,0.937829,-0.213787,-0.026169,0.377871,0.349612,0.146894,0.473147,0.373483,-0.203424,0.021949,0.245403,-0.092205,-0.172862,0.288830,-0.144644,0.209753,-0.240921,0.168659,0.437575,0.259371,0.442521,-0.331740,0.219248,-0.022686,0.421375,-0.038648,0.284053,0.218712,0.148293,-0.072366,0.335475,0.138363,-0.049848,0.150521,0.123108,-0.255759,-0.658935,0.008545,0.098587,0.041923,-0.754096,0.607676,0.059787,-0.480116,0.154492,-0.168969,0.017866,0.470195,0.142361,0.270779,-0.478732,0.000717,-0.284606,-0.030182,0.549911,0.063797,-0.377875,0.391288,-0.354203,-0.626405,-0.268509,-0.204231,-0.379541,-0.413071,0.556986,0.182942,0.073844,0.429944,-0.569295,0.073818,-0.117490,-0.135459,-0.083833,-0.461279,0.184013,-0.404228,0.177688,-0.320888,-0.546653,-0.055301,-0.219116,-0.317495,0.865927,-0.977497,0.077859,0.522739,0.184815,0.071619,0.454235,-0.021470,0.318276,-0.188078,0.010380,0.665618,-0.035579,0.017976,0.025198,0.726900,0.192102,0.155189,-0.288043,0.895799', '1870681', '26387939', '3882427', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27197086', '国家破产之日', '剧情', '《国家破产之日》将镜头对准了1997年的亚洲金融风暴。讲述国家破产前的一周时间内，想要阻止危机的人和追逐利益的人身上发生的故事。金慧秀在片中饰演最早预见破产并开始寻找对策的韩国银行通货政策小组组长韩诗贤，面对复杂的体系和权利关系，她面前的道路可谓困难重重；刘亚仁则饰演在危机中逐利的金融才子尹正学；法国影帝文森·卡索将饰演秘密入韩的IMF总裁。', '金惠秀', '崔国熙', 7.5, 44050, 'tt7233726', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2536564565.jpg', 0.4, 2.8, 33.4, 47.8, 15.7, '0.128419,0.114594,-0.572529,0.423825,0.498388,0.053557,0.447909,0.072781,-0.524921,-0.324862,-0.027963,0.484694,-0.118192,0.111599,0.709438,-0.283325,-0.276835,-1.163026,-0.382875,-0.124865,0.006167,-0.486744,-0.402247,-0.226010,-0.205875,-0.376989,0.858558,0.283399,-0.214894,0.445962,0.402208,0.194983,-0.331000,0.394359,0.315323,-0.216825,0.323651,0.003228,-0.825895,0.281842,0.001835,-0.451291,0.015298,0.199757,0.137816,0.345451,0.550904,-0.200199,0.120015,-0.357388,0.465869,-0.398026,-0.104227,0.019229,0.578500,0.140915,0.256965,0.792868,-0.099545,-0.013672,0.025317,-0.452301,-1.054102,-0.172923,0.258275,0.297602,-0.414538,0.266201,-0.107724,0.202492,-0.131306,-0.227325,0.365166,0.428944,0.661128,0.216750,-0.283057,0.289897,-0.395324,0.136226,0.515031,-0.123845,-0.165650,0.174575,0.050209,-0.403903,-0.397869,-0.366246,-0.177668,-0.113826,0.237867,0.170818,-0.187682,0.465979,-0.492704,0.101384,-0.034307,-0.420052,0.210239,-0.329187,0.027149,-0.589542,-0.201308,-0.262244,-0.019309,0.199132,0.096867,-0.199804,0.587747,-0.455510,-0.187017,0.663454,0.745776,-0.541329,0.780303,-0.002413,0.365741,-0.600865,-0.254314,0.181716,-0.091760,0.255463,-0.369290,-0.042699,-0.240436,-0.295768,-0.125589,0.367182', '1293989', '26678784', '4301278', '1307914');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27198855', '印度合伙人', '剧情', '电影曾译名《护垫侠》，根据印度草根企业家Muruganantham真实事迹改编。因为卫生巾关税高昂，在2012年印度仍有80%以上的女性在生理期无法使用卫生用品，初中文化程度的主人公拉克希米（阿克谢·库玛尔 饰）为了妻子（拉迪卡·艾普特 饰）的健康，寻找低成本的卫生巾的生产方法，却被全村人视为变态、疯子；最后他远走大城市德里，遇到了生命中最重要的美女合伙人帕里（索娜姆·卡普尔 饰），最终发明了低成本卫生巾生产机器，并开放专利，为印度全国对于女性经期卫生观念带来变革，2018年7月印度取消卫生巾进口关税。“权势之人、强壮之人不会让国家变强，女性强大、母亲强大、姐妹们强大后，国家才会强盛。”', '阿克谢·库玛尔', 'R·巴尔基', 7.7, 103264, 'tt7218518', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2540940050.jpg', 0.3, 2.2, 29.8, 49.9, 17.8, '-0.192340,-0.002470,-0.354781,0.392258,-0.042709,-0.027781,0.424127,-0.059639,-0.465095,-0.421174,0.106683,0.466234,0.120076,-0.362202,0.239113,0.001961,-0.193360,-0.445541,0.005927,-0.180318,-0.385913,-0.207710,-0.386151,-0.459053,-0.525935,-0.484984,0.243295,-0.087955,-0.409737,-0.005911,0.214357,0.320787,0.098798,0.164600,0.128453,-0.352790,0.196855,-0.179291,-0.421100,0.218062,-0.121917,-0.067917,0.036835,0.107970,0.098455,0.075508,0.466072,-0.178055,0.116555,-0.491466,0.551772,0.193140,-0.152333,-0.118061,0.228798,-0.006830,0.390593,0.151859,0.133569,-0.091124,0.324306,-0.218267,-0.645825,-0.161808,0.308721,-0.236228,-0.212399,0.264459,-0.262029,0.192067,0.176687,-0.332366,0.012656,0.101657,0.490685,0.506629,0.088423,0.109136,-0.411154,0.432149,0.316201,0.098246,-0.604504,-0.064056,-0.725726,-0.653591,-0.020622,-0.766237,-0.411634,0.232282,0.207888,0.284976,-0.062678,0.577298,-0.662065,0.052389,-0.132922,-0.369231,0.422115,0.130334,0.063527,-0.423749,-0.090737,-0.436554,-0.058683,0.131138,0.354016,-0.248987,1.099225,-0.535000,0.113254,0.597374,0.709722,-0.618385,0.461831,-0.252455,0.035584,-0.343391,-0.330595,0.491538,-0.228333,0.272645,-0.176410,0.027719,-0.040257,-0.218145,-0.029042,0.491596', '24284209', '27602116', '26348103', '25882279');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27199324', '野性的呼唤', '剧情', '巴克是一只骨骼壮硕身材强壮的狗，本来在大法官家里过着养尊处优的生活的它，被园丁偷走，卖到了严寒的阿拉斯加，成为了雪橇犬。巴克坎坷的命运并没有就此终结，之后，它又辗转经历了好几个主人，他们残暴而又冷酷的对待巴克。不仅如此，巴克在狗群中也为了保住自己的地位而经历了巨大的挑战 。这一次，约翰（哈里森•福特Harrison Ford 饰）成为了巴克的新主人，幸运的是，约翰是一个善良的男人，他不仅非常温柔的对待巴克，还治好了它伤痕累累的身体。随着时间的推移，一人一狗之间产生了坚实的友谊。然而，在一场意外中，约翰被印第安人杀死了，愤怒的巴克失去了理智，它要为自己的主人报仇。©豆瓣', '哈里森·福特', '克里斯·桑德斯', 7, 41052, 'tt7504726', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2624308041.jpg', 0.6, 6.7, 46.2, 34.9, 11.5, '0.050990,0.060370,-0.740971,0.580139,-0.469618,-0.490263,1.059729,0.081962,-0.470591,0.016520,0.372915,0.719897,0.001566,0.122768,0.041749,0.131868,0.084572,-0.543749,-0.092368,0.048848,-0.249231,-0.217507,-0.538585,-0.293815,-0.055546,-0.506867,0.661379,-0.067120,-0.132318,0.428363,0.230829,0.119233,0.324180,0.450992,-0.413549,0.271129,0.169997,-0.138076,0.018492,0.104634,0.079360,-0.204014,0.126668,0.459220,-0.293033,0.496828,0.615508,-0.481490,-0.194052,-0.408757,0.354863,-0.325819,0.084635,0.237960,0.379340,-0.043319,0.094711,0.279494,-0.258664,-0.090116,0.281511,-0.107380,-0.999344,0.050070,-0.261717,0.258852,-0.737460,0.766926,-0.115191,-0.082102,0.116343,-0.416193,0.215091,0.251127,0.305445,0.361874,-0.242883,0.061088,-0.539542,-0.028605,1.025803,-0.081106,-0.567584,0.227077,-0.566435,-0.478244,0.096463,-0.541104,-0.388903,-0.318842,0.576501,0.186871,-0.344645,0.426403,-0.704007,0.106780,-0.399648,-0.197065,-0.348108,-0.440165,-0.141638,-0.127336,-0.229670,-0.717848,-0.242408,-0.063352,-0.079655,-0.426530,0.694359,-0.740358,0.354404,0.687972,0.412282,-0.222686,0.461333,0.009909,0.175143,0.154286,0.029968,0.375212,0.233568,0.133107,0.465872,0.458902,0.078268,0.032055,-0.450622,1.003056', '25828589', '34875369', '1307311', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27199577', '银魂2', '喜剧', '位于歌舞伎町一隅的万事屋，坂田银时（小栗旬 饰）、志村新八（菅田将晖 饰）和神乐（桥本环奈 饰）因为没钱交房租而焦头烂额，于是三人只得外出打工。他们先是去夜总会担任女招待，之后又临时充当理发师，可好死不死都碰上了微服出访的将军大人德川茂茂（胜地凉 饰），令他们战战兢兢，如履薄冰。另一方面，真选组土方十四郎（柳乐优弥 饰）遭伊东鸭太郎（三浦春马 饰）暗算，从刚硬坚毅的武士变成了柔弱怯懦的御宅族，最终被真选组扫地出门。在此之后，伊东联合鬼兵队，策划足以颠覆江户政府的大阴谋……本片根据空知英秋的超人气漫画改编改编，是同系列真人电影的第二部，此次的故事根据“将军接待篇”和“真选组动乱篇”改编。©豆瓣', '小栗旬', '福田雄一', 7.2, 39079, 'tt7639528', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2527126044.jpg', 0.8, 5.7, 38.8, 41.4, 13.4, '-0.091073,-0.277663,-0.204817,0.091471,0.227572,-0.142700,0.267249,0.381612,-0.234085,-0.358631,0.306036,0.646647,-0.078289,0.088238,0.421229,0.010270,-0.347768,-0.432911,-0.243548,0.106744,0.246836,-0.228335,0.151700,-0.069746,-0.073585,-0.203097,0.792649,0.026780,-0.305154,0.347882,0.444145,0.611991,-0.370400,0.001454,0.200743,0.287303,0.178489,-0.199620,0.071101,0.148277,-0.469683,-0.261857,-0.259165,-0.044318,0.281534,0.535967,0.548337,-0.195763,-0.093643,-0.171597,0.300224,-0.015832,-0.366942,0.066049,0.458765,0.095383,0.176460,0.372977,-0.234060,0.055197,-0.030048,-0.125251,-0.425585,0.107972,0.409653,0.161764,-0.253010,0.330480,-0.214989,-0.201981,0.352613,-0.097804,0.112239,0.334724,0.538650,-0.049154,0.000333,0.162252,-0.084843,0.412499,0.385381,0.155102,0.004588,-0.006828,0.177207,-0.302227,-0.109910,-0.426519,-0.097671,0.077274,0.020256,-0.197884,0.140649,0.108168,-0.556561,-0.346262,-0.076469,-0.169286,0.177305,-0.159613,0.090911,-0.701252,0.172881,-0.331789,-0.096433,0.129083,0.442814,0.053890,0.455371,-0.419894,-0.150815,0.284529,-0.128466,-0.277130,0.233337,-0.021974,-0.195852,-0.077095,-0.006716,-0.081033,0.306106,0.474407,0.399310,0.412961,-0.065722,-0.465747,-0.338259,-0.103078', '2369613', '1322847', '20274039', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27199913', '灰猴', '剧情', '电影《黄花梁上的灰猴们》讲述了一个荒诞离奇的犯罪型喜剧故事。影片通过一件“古陶坛子”为 引子，从而引出了一系列形形色色的人物：大智若愚的小饭店老板、见利忘义的无良商人、深明大义的老者、利欲熏心的小人、善良淳朴的朴实女孩、拜金风骚的妙龄女郎。种种风格迥异的角色加之各种棘手的麻烦事件，与“古陶坛子”这个主线巧妙结合在一起。张璞导演选择多角度的叙述手法，让故事情节环环相扣，先将悬疑抛出，再把线索一点一点如抽丝剥茧般呈现给观众，耐人寻味。', '王大治', '张璞', 5.9, 8673, 'tt10357088', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2561541477.jpg', 5.2, 23.5, 48.3, 17.5, 5.5, '0.649696,0.027079,0.079850,0.767146,-0.239387,0.126422,0.702780,0.107025,-0.575284,0.011393,0.237850,0.458891,-0.331068,-0.234132,0.245148,-0.129434,-0.341027,-0.609221,-0.349150,0.053130,-0.020259,-0.571323,-0.091784,-0.273867,-0.003850,-0.169033,0.421623,0.046360,-0.283008,0.067799,0.297698,0.232829,-0.412596,-0.077409,-0.183996,-0.002851,-0.188221,-0.059153,-0.255023,0.003750,0.006704,-0.308566,0.183969,0.281741,-0.422191,0.338758,0.852393,-0.320742,-0.400023,0.145002,0.950342,0.042374,-0.023879,0.046910,0.076082,0.227793,0.453550,0.138267,-0.122699,-0.125711,0.381427,-0.278039,-0.925542,0.007424,0.320625,0.134545,-0.380383,0.109851,0.316794,0.042340,0.156768,-0.241627,-0.049109,-0.175937,1.057703,0.329367,0.222873,0.035245,-0.111354,0.569250,0.135340,0.429359,-0.324706,0.614525,-0.306171,-0.360354,0.020993,-0.328251,-0.070209,0.166409,0.555431,-0.302784,-0.196636,0.431258,-0.977953,-0.133721,-0.164483,0.100611,0.138749,-0.271871,-0.414607,-0.524838,-0.228903,-0.133623,-0.022093,-0.181608,0.189579,-0.143112,1.057243,-0.313352,-0.153436,0.715583,-0.289084,-0.318388,0.513951,-0.250797,-0.019270,-0.141974,-0.114561,-0.172705,0.104625,0.091900,-0.084689,0.833290,-0.183804,-0.321330,-0.358080,0.235243', '27602116', '6844861', '4181031', '25918677');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27200012', '领袖水准', '动作', '梅尔·吉布森、弗兰克·格里罗商谈加盟动作惊悚片《领袖水准》(Boss Level)，乔·卡纳汉(《人狼大战》《天龙特攻队》)执导并编写剧本。格里罗将饰演一名退役特种部队老兵，被困在永无止境的死亡循环之中。Emmett/Furla/Oasis投资，洛伦佐·迪·博纳文图拉(《变形金刚》《生死狙击》)、Mark Vahradian(《赤焰战场》)、兰道尔·艾米特(《第一滴血》《金蝉脱壳》)、 George Furla(《双龙出手》《孤独的幸存者》)联合制片。', '梅尔·吉布森', '乔·卡纳汉', 7, 20648, 'tt7638348', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2632882617.jpg', 0.9, 5.8, 45.2, 37.6, 10.5, '-0.334673,-0.297456,-0.636409,0.405027,0.432525,-0.448484,0.324879,0.048901,-0.250668,-0.691186,0.263126,0.271699,-0.263130,-0.228773,0.570389,-0.381921,-0.291677,-0.541172,-0.246045,0.054345,0.000472,-0.476506,-0.386801,-0.624354,0.269851,-0.178598,0.775829,0.138159,-0.145593,0.129358,0.306918,0.561100,-0.157221,-0.156336,0.488715,-0.039594,0.423223,-0.481999,-0.517586,0.352884,-0.297529,0.307497,-0.036035,-0.103033,0.462968,0.105350,0.376559,-0.404386,0.681234,-0.251341,-0.049068,-0.165385,0.031717,-0.438054,0.530769,-0.326772,-0.261149,-0.169225,0.295885,0.385333,-0.331954,-0.420887,-0.641419,0.096906,-0.276572,0.343322,-0.452279,-0.081146,-0.242799,0.627454,-0.198120,0.076325,-0.203408,0.241604,0.839201,-0.149087,0.302216,0.256912,-0.301766,0.159864,0.310735,-0.108129,-0.189017,-0.167507,-0.070167,-0.752055,-0.569573,-0.080758,-0.353498,-0.057440,0.523081,-0.268230,0.400825,0.530521,-0.390549,-0.160206,-0.256427,0.061103,-0.362279,0.323159,0.274518,-1.225689,0.058593,0.433744,0.252119,-0.311311,-0.183771,-0.010684,0.561332,-0.281914,0.350879,0.230095,0.257780,0.095997,0.273296,0.175171,0.333763,-0.477632,0.092761,1.042012,0.444408,-0.032775,0.266848,-0.003928,-0.063553,0.181750,0.149728,0.277030', '6517421', '26335580', '2369613', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27200988', '未来机器城', '科幻', '一个即将被用于拯救人类的新型机器人7723（韩莹棣 配音），因缘际会遇上了热爱足球的调皮少女苏小麦（郑海音 配音）。而看似顽劣的小麦生长在一个不算完整的家庭里，父亲为追梦离家，使得小麦的成长也受到了影响，性格冷漠孤僻。7723的出现也使得这对欢喜冤家逐渐在相爱相杀中成为了一对挚友。然而好景不长，心怀毁灭人类之梦的庞老板（冯远征 配音）追踪到了7723的下落，然而那些印刻着小麦名字的温柔颜色和绚烂时光早已在他的生命里留下了不可磨灭的痕迹……', '韩莹棣', '安恪温', 5.7, 14491, 'tt7133686', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2561782665.jpg', 7.6, 26.8, 44.7, 15.3, 5.5, '0.129237,0.242855,-0.685211,0.914503,-0.384268,-0.332492,0.995558,0.108806,-0.282846,-0.062850,0.110737,0.625227,-0.034789,0.215033,0.173392,-0.202625,0.060229,-0.480908,-0.205867,-0.042460,-0.239043,-0.424014,-0.463025,0.060629,-0.221400,-0.445751,0.674326,0.392653,-0.378211,0.550861,0.089096,0.077555,-0.262963,0.385615,-0.190153,0.156308,-0.076346,0.058542,-0.120458,0.191820,0.104352,-0.312139,0.257589,0.217838,-0.553494,0.608223,1.052168,-0.560712,-0.180652,-0.254363,0.596712,-0.126094,-0.207756,0.209042,0.328656,0.249789,-0.012728,-0.004725,-0.357368,0.168979,0.202348,-0.192033,-0.856618,0.009190,0.101567,0.362180,-0.645159,0.606853,0.102736,-0.237902,0.085561,-0.376767,0.381075,0.110539,0.469940,0.528428,-0.246072,0.207727,-0.408549,0.243682,0.621974,-0.038009,-0.588162,0.627011,-0.575207,-0.467591,-0.014831,-0.234829,-0.759211,-0.152919,0.210522,0.158388,-0.179709,0.450069,-0.925738,0.433301,-0.029509,0.056571,-0.125215,-0.418943,-0.181826,-0.469017,-0.398068,-0.689264,-0.471748,0.149736,-0.157962,-0.488548,0.992186,-0.899915,0.209454,0.344263,0.230811,-0.437195,0.569737,0.050059,0.059155,-0.130805,-0.016546,0.602206,0.105224,0.043418,0.151766,0.417021,-0.154029,0.060022,-0.398445,0.732984', '26348103', '1303542', '2053515', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27201353', '大师兄', '喜剧', '陈侠，一位初出茅庐的教师，他的学生全是品学皆劣的边缘青年，陈侠运用非常教学的手法，从家访、投其所好、甚至修补各人的家庭关系，化解每位学生的问题，最终把全班学生收服！一切向好之际，陈侠遇到黑道人物鹰哥，为了学生，陈侠跟鹰哥展开一场守护学生前途的终极大战！', '甄子丹', '阚家伟', 5.1, 40570, 'tt7336572', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2528842218.jpg', 10.9, 36.6, 41.1, 8.4, 3, '0.220415,-0.520527,0.091007,0.463511,-0.370974,-0.061139,0.245193,-0.007814,-0.515668,-0.645311,0.449424,0.488656,-0.292665,0.166433,0.601730,-0.626347,0.038942,-0.731711,-0.219962,0.313583,-0.142472,-0.239059,-0.263512,0.109571,-0.303675,-0.521288,0.863240,-0.192147,-0.356677,-0.011241,-0.081624,0.184755,-0.107100,0.042978,0.093296,-0.417385,-0.251140,0.023083,-0.444786,0.029906,0.004386,-0.208022,-0.326963,-0.002476,0.053844,0.218654,0.741815,-0.013542,0.008670,-0.086488,0.407730,-0.253526,-0.052434,0.140951,0.299234,0.226942,0.138123,0.316633,0.317676,-0.222269,0.125708,-0.187449,-0.472063,-0.341832,0.379822,-0.142041,-0.310157,0.570433,0.282990,-0.076703,-0.104388,-0.231235,-0.161278,0.283431,0.312515,0.487847,-0.137594,-0.040318,-0.046945,0.161816,0.628481,-0.045567,-0.070602,0.051039,-0.203821,-0.578886,-0.059386,-0.293157,-0.290825,0.161816,0.077297,0.112819,0.082766,0.310021,-0.580311,-0.156398,0.083850,-0.067922,0.004938,-0.228078,0.043880,-0.760050,0.161027,0.133038,-0.456030,-0.035882,0.146391,-0.394848,1.221480,-0.958965,-0.439224,0.154865,0.139844,-0.335415,0.556978,-0.084528,0.498435,-0.468416,-0.424999,-0.295673,0.141809,0.397159,-0.029256,0.411983,-0.232202,-0.418181,0.139922,0.533409', '25922902', '10174444', '3811356', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27202765', '好久不见', '剧情', '飞刀是为黑社会杀人的冷酷杀手，浸淫这一行当多年，双手沾满了鲜血的他感到异常疲惫，萌生了退意。就在这个节骨眼上，飞刀结识了名为野狗的男子，和飞刀一样，野狗也是一名杀手，他们两人所效力的，刚好是两个相互对立的帮派，因此两人之间可谓是敌对的关系。然而造化弄人，在机缘巧合之下，飞刀和野狗之间竟然碰撞出了爱情的火花，为了成全各自心底的感情，他们都选择了隐瞒他们的真实身份，这为日后的矛盾买下了引线。纸是无法包住火的，当两人之间的感情被帮派发现后，他们被打上了叛徒的烙印，遭到了同伙的追杀。©豆瓣', '탁우석 Tak woosuk', 'Woo-seok Seo', 7.2, 6742, 'tt7863474', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2509705871.jpg', 1.7, 8.3, 36.1, 33.9, 20, '0.677693,-0.004766,-0.842029,0.589531,-0.052678,-0.302120,0.777352,0.055738,-0.528124,-0.013398,0.449621,0.705423,-0.273491,0.156867,-0.078910,-0.303021,0.210991,-1.205060,-0.233998,-0.385396,-0.361068,-0.355064,-0.358859,-0.068956,-0.283781,-0.089543,0.625897,0.252298,-0.245540,0.490290,0.596905,0.260249,-0.252272,0.437829,-0.290700,-0.137849,-0.037442,0.019735,-0.290097,-0.081908,-0.123521,-0.246962,0.234556,0.351729,-0.382873,0.620677,0.646993,-0.129793,0.019779,-0.222209,0.190689,-0.301071,-0.083268,0.139572,0.577676,0.048456,0.225291,0.137178,-0.045324,-0.097245,0.051683,0.192654,-0.984147,0.088517,0.013666,0.201045,-0.925971,0.813336,-0.019730,-0.356760,-0.118243,-0.208932,0.444770,0.180979,0.464655,0.074674,-0.317546,-0.299538,-0.504075,-0.089824,0.960239,-0.090728,-0.231008,0.310007,-0.362930,-0.300367,-0.269939,-0.275501,0.142663,-0.368034,0.608536,0.147026,-0.308213,0.427457,-0.808819,-0.054939,-0.260670,0.371181,0.031469,-0.579342,0.049334,-0.319811,-0.475374,-0.715981,-0.573071,0.259011,0.096456,-0.015546,0.656427,-0.938145,-0.132701,0.474082,0.252346,-0.279761,0.706982,0.227719,-0.110088,0.006971,-0.043386,-0.189596,0.295036,0.209243,0.446651,0.412063,-0.063460,0.240648,-0.221321,0.297691', '1301022', '25853727', '1293829', '35030151');
