INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27202819', '反贪风暴4', '动作', '廉政公署收到报案人廖雨萍（周秀娜饰）的实名举报，举报正在坐牢的富二代曹元元（林峯饰）涉嫌行贿监狱里的监督沈济全（谭耀文饰）以及惩教员，首席调查主任陆志廉（古天乐饰）决定深入虎穴，卧底狱中。在监狱里，被陆志廉送入监狱的前警司黄文彬（林家栋饰）以及曹元元两大帮派势成水火，陆志廉趁机接近曹元元取得信任。同时监狱外的廉政公署总调查主任程德明（郑嘉颖饰）、国内反贪局行动处处长洪亮（丁海峰饰）也陆港联手，通力合作，最终成功破获贪腐行贿大案。', '古天乐', '林德禄', 5.9, 162932, 'tt10017680', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2551353482.jpg', 4, 21.9, 53.6, 16.9, 3.7, '0.148928,0.018672,-0.309335,0.223729,0.154989,0.084069,0.162273,0.497131,-0.561237,-0.206671,0.256973,-0.051640,0.136699,0.026083,0.079231,-0.464696,-0.497039,-0.586058,-0.300828,-0.257076,-0.233935,-0.635112,-0.132133,0.002390,0.117968,0.185677,0.471124,0.165831,-0.155197,0.291861,0.448329,0.379429,-0.307854,0.004301,0.137997,-0.166045,0.893851,0.010975,-0.643476,0.134439,0.163806,-0.151387,0.118648,-0.264929,0.506128,0.233902,0.190243,-0.135453,-0.126222,-0.384925,0.493225,-0.296274,-0.204659,0.031421,0.609842,0.722492,0.337516,0.750925,-0.524974,0.166680,0.135311,-0.177202,-0.692263,-0.151242,0.378832,-0.034211,-0.035218,-0.195656,-0.033551,0.282675,0.296898,0.082313,0.190169,0.074856,0.135502,0.169434,0.101470,0.233825,-0.386442,0.505501,0.266976,-0.314562,0.250668,-0.673143,0.252668,-0.484081,0.264855,-0.208066,0.117608,-0.000970,0.131660,-0.391561,0.203988,-0.039085,-0.110556,-0.227837,-0.358071,0.373107,-0.105842,0.159675,0.152450,-0.801879,-0.163601,0.065895,-0.136355,0.134624,0.271255,-0.092904,-0.186469,-0.405382,-0.131922,0.256121,0.295182,-0.544391,0.405472,0.221204,0.254444,-0.364308,-0.340079,-0.166006,0.778104,0.562372,-0.109809,-0.001062,-0.000431,-0.843240,-0.089346,-0.539947', '26996640', '1293572', '32579501', '26352445');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27202825', '最后一球', '剧情', '尤里（丹尼拉·科兹洛夫斯基 Danila Kozlovsky 饰）原本是莫斯科王牌球队的队长兼主力，因为痛失点球情绪失控不得不提前退役，退役后的生活颓废至极，在父亲的劝说下，他来到了俄罗斯边远小城，成为了这个城市唯一一支球队——流星队的主教练。尤里由于脾气火爆，跟球队经理（伊琳娜·戈尔巴乔娃 Irina Gorbacheva 饰）和市长冲突不断，而懒散的球员们也对曾经的巨星疯狂奚落，尤里本想破罐破摔，但是美丽的队医（奥莉亚·祖耶娃 Olya Zueva 饰）照亮了他的生活，少年球队的教练（弗拉基米尔·伊利因 Vladimir Ilin 饰）也给他带来了眼前一亮的训练方法。在了解了球员们的真实状况后，尤里决心重新以主教练的身份一雪前耻，等待他们的是困难重重的比赛，和物力、人力的缺失，关键的比赛时刻，一直支持尤里的父亲也突然去世，尤里能否引领队伍重回巅峰呢？', '丹尼拉·科兹洛夫斯基', '丹尼拉·科兹洛夫斯基', 7.4, 10637, 'tt7632930', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2526211692.jpg', 0.3, 4.4, 37.8, 39.4, 18, '0.020174,0.095705,-0.520103,0.474039,-0.178095,-0.488931,0.499269,0.420025,-0.632536,-0.056368,0.336975,0.596665,0.011994,0.019752,0.401405,-0.397784,-0.289010,-0.780223,0.015688,0.201169,-0.181084,-0.483560,-0.318181,-0.285645,0.068162,-0.362355,0.842743,-0.125665,-0.168900,0.386554,0.268270,0.549586,0.458038,0.303356,-0.069727,-0.101415,0.252257,-0.088521,-0.347302,0.171550,0.032724,-0.151782,-0.409571,0.305921,0.335059,0.271562,0.503524,-0.225691,-0.004814,0.050569,0.090061,-0.199986,0.017825,0.121314,0.207917,-0.078493,0.121020,-0.010254,0.069143,0.122119,-0.312956,-0.224467,-0.673474,0.104589,0.049646,0.055540,-0.542897,0.585075,-0.204035,-0.096920,0.321827,-0.299840,0.091618,0.507145,0.144983,0.262978,-0.209810,-0.044432,-0.302829,0.091105,0.547210,-0.115698,-0.314872,0.084293,-0.508470,-0.460721,-0.084954,-0.443443,-0.616187,0.089924,0.258054,0.035883,0.182328,0.183325,-0.461999,0.104094,-0.303189,-0.482633,-0.099835,-0.408271,0.110451,-0.415012,-0.122578,-0.390247,-0.312020,0.021544,-0.191686,0.183927,0.732517,-0.857134,0.134852,0.584466,0.025310,-0.389977,0.459280,0.066439,0.143513,-0.308302,-0.040203,0.387466,-0.273056,0.298333,-0.053347,0.314506,-0.004361,-0.241989,-0.111421,0.606893', '35030151'