INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27203644', '尼罗河上的惨案', '剧情', '故事继续聚焦在上流社会的秘事，大侦探波洛（肯尼思·布拉纳 Kenneth Branagh 饰）在埃及度假期间， 卷入到了一场危险的三角关系之中，他在察觉到这趟旅程中不寻常的味道之后，登上了那条驶往阴谋和死亡的船。', '肯尼思·布拉纳', '肯尼思·布拉纳', 5.7, 86374, 'tt7657566', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2854856216.jpg', 3.9, 22.9, 57.3, 13.9, 2.1, '0.464594,0.046468,-0.986154,0.625982,0.250349,0.235531,0.905783,0.036106,-0.560104,0.042035,0.155805,0.897912,-0.392556,-0.210176,0.639357,0.158812,-0.521711,-0.655935,0.068801,-0.309713,-0.401079,-0.735752,-0.389672,-0.099960,0.104263,-0.620280,0.350844,0.617867,-0.466390,0.551633,0.153141,0.113440,-0.643227,0.653875,0.047397,0.011141,0.381014,0.373752,-0.016557,0.514892,-0.110918,-0.233571,-0.237019,-0.102647,0.223164,0.399172,0.699404,-0.544516,0.119969,0.348405,-0.170241,-0.353304,-0.065158,0.044614,0.419624,-0.163147,-0.101697,0.445406,-0.433183,0.357095,0.102673,-0.165201,-0.313672,-0.181945,-0.190762,0.636015,-0.543190,0.577312,0.074270,-0.431518,-0.166365,-0.357300,0.436891,0.313118,0.314667,0.199808,0.315285,0.372170,-0.639288,0.023956,1.161100,0.112217,-0.286732,0.435623,0.043144,-0.322061,-0.519261,-0.043806,-0.433435,-0.377821,0.682805,0.015416,-0.313544,0.731751,-0.910152,-0.007044,-0.155526,-0.272288,-0.179811,-0.112152,-0.015559,-0.511452,-0.099408,-0.580740,0.107401,0.184992,0.204884,-0.387142,0.132907,-0.567408,0.383556,0.771609,-0.041322,-0.047315,0.768050,0.166938,0.449558,-0.204410,-0.258167,0.249504,0.039059,0.289172,0.108612,0.430736,-0.143214,-0.315171,-0.550207,0.541917', '34461680', '27053945', '3011051', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27589933', '风平浪静', '剧情', '十五年前的一次意外，成绩优异高中生宋浩离开了家乡，也离开了原本的人生轨迹。十五年后，他回到家乡，一切仿佛都已风平浪静。与老同学潘晓霜的重逢，给了他人生久违的光亮。他决定揭开那个十五年来不敢触碰的伤疤，重新掌控人生，完成一场似乎不可能的自我救赎。', '章宇', '李霄峰', 6.2, 141742, 'tt11306684', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2626255103.jpg', 3.1, 18.6, 50.6, 23, 4.7, '-0.069621,0.279392,-0.771599,0.584480,-0.403326,-0.853824,0.787296,-0.168751,-0.471156,-0.327895,0.031093,0.765691,-0.120694,0.544842,0.237114,0.106858,-0.365404,-0.933853,0.162961,-0.636293,-0.246412,-0.103589,-0.249812,0.007967,0.103320,-0.332765,0.838359,0.531473,0.045504,0.463183,-0.172427,-0.443411,0.159391,0.504501,-0.222274,0.065454,-0.204133,0.520031,-0.750273,-0.088359,0.297172,-0.539560,-0.262869,0.528874,-0.098529,0.359447,0.867019,-0.236290,-0.482328,-0.042144,0.580202,-0.343724,-0.331267,0.220850,0.062244,0.245773,-0.019589,0.393288,-0.128694,-0.054755,-0.116942,-0.274257,-0.527638,-0.115897,-0.162882,-0.125750,-0.432946,0.670902,0.010021,0.012817,-0.060043,-0.480150,0.109597,0.414189,0.518418,0.461216,-0.633633,0.224920,-0.266165,0.417836,1.169380,-0.205236,-0.476208,0.635852,0.062228,-0.446269,-0.197555,-0.030519,-0.368432,0.396825,0.245108,0.398665,-0.256717,0.400969,-0.403522,-0.112622,-0.405461,-0.130736,-0.074824,-0.574192,-0.070133,-0.163984,-0.327819,-0.007899,-0.479042,0.273950,0.091156,-0.382464,0.117761,-0.615566,0.506524,0.345789,-0.082035,-0.418560,0.505771,0.228493,0.128868,-0.520586,0.533231,0.443339,-0.275349,0.659540,0.085451,0.254865,-0.091482,0.391034,-0.585739,0.813995', '2365260', '27008393', '1293964', '1302109');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27591193', '来自深渊：深魂的黎明', '动画', '在每一个角落都被探索完毕的世界中，唯一残留的秘境——大洞穴“阿比斯”。不知道延续到何方，深不见底的巨大纵向洞穴，栖息着奇妙奇怪的生物们，沉眠着现在的人类无法制造的贵重遗物。“阿比斯”那充满了不可思议的姿态吸引了人们，并驱使人们展开冒险。如此，多次挑战大洞穴的冒险者们，陆续得到了“探窟家”的名号。住在建造于阿比斯边缘的城镇“奥斯”的孤儿莉可，梦想着有朝一日成为母亲那样伟大的探窟家，并解开阿比斯的谜团。某天，以母亲莱萨的白笛被发现为契机，莉可决定潜入阿比斯深处。被莉可捡到的丧失记忆的机器人雷格，也为了寻找自己的记忆而决定同行。莉可在深界四层中了穿弹兽的毒。救了莉可的，是“生骸”娜娜奇。娜娜奇也成为两人的同伴，三人的冒险向着波多尔多所在的深界五层进发。在那里，他们遇到了一位自称为普鲁修卡的女孩子……', '富田美忧', '小岛正幸', 8.7, 17803, 'tt10068916', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2589852362.jpg', 1.2, 1.7, 10.2, 34.1, 52.8, '0.347495,0.050645,-0.745205,0.656656,-0.003508,-0.424851,0.781396,-0.027923,-0.282974,-0.231176,0.168328,0.590757,-0.031261,0.092434,0.176204,0.197940,-0.284034,-0.338502,-0.066572,-0.379764,-0.636148,-0.404362,-0.326937,-0.459991,-0.192264,-0.491529,0.635833,0.231375,-0.201412,-0.052647,0.190670,0.368203,-0.138184,0.451877,-0.266085,0.009372,0.059875,0.009495,-0.078880,0.447205,-0.191352,0.089736,-0.300280,0.287330,-0.070717,0.216111,0.783672,-0.753522,-0.001806,0.041818,0.199177,-0.277941,0.104318,-0.056247,0.434628,-0.129427,-0.098524,-0.088762,-0.061884,0.012970,0.307568,-0.233855,-0.893943,-0.110057,0.208442,0.230867,-0.493101,0.222743,0.178914,-0.107374,0.173092,-0.516392,0.023201,0.312510,0.085166,0.310455,-0.387609,0.074953,-0.501287,-0.076308,0.604977,-0.040393,-0.342374,0.161503,-0.300141,-0.645670,0.038036,-0.250724,-0.654475,-0.114587,0.328575,0.301467,-0.166549,0.478454,-0.772124,0.012524,-0.402429,-0.238431,-0.089777,-0.418938,-0.237841,-0.427341,-0.195585,-0.068159,-0.094314,0.087897,-0.070143,-0.349089,0.697311,-0.787768,0.416306,0.773830,0.374149,-0.198877,0.953150,-0.359777,0.146045,-0.037686,-0.447201,0.378532,0.150225,0.504126,0.271773,0.426105,-0.115727,-0.010585,-0.556450,0.468085', '3055049', '3769423', '3005387', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27592484', '热气球飞行家', '动作', '故事发生在1862年的伦敦，詹姆斯（埃迪·雷德梅恩 Eddie Redmayne 饰）是一位非常有理想抱负的年轻科学家，致力于研究天气预报技术，然而，经济上的窘迫让他无法使用自己的热气球将研究成果带上天空，于是，他找到了名为艾米莉亚（菲丽希缇·琼斯 Felicity Jones 饰）的女子。艾米莉亚是一个经验非常丰富的热气球飞行员，如今却沉溺在一段痛苦的往事之中无法自拔。她答应了詹姆斯的请求，两人共同驾驶着热气球开始了他们的冒险，并且凭借着智慧和勇气抵达了人类从未涉足过的高度。然而，当他们飞的越高，所要面对的危险就越大。©豆瓣', '埃迪·雷德梅恩', '汤姆·哈伯', 7, 33652, 'tt6141246', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2624376523.jpg', 0.3, 3.7, 48.3, 39.6, 8.1, '0.373708,0.078133,-0.779906,0.696859,0.058071,-0.351956,0.721779,-0.189256,-0.590378,-0.244923,0.109815,0.689050,-0.124312,0.134708,0.230648,-0.003647,-0.364727,-0.548307,-0.013019,-0.129217,-0.448548,-0.638978,-0.492923,-0.290282,-0.246065,-0.420249,0.680022,0.089990,-0.277489,0.209423,-0.026916,0.196415,0.134241,0.553148,-0.215831,-0.197653,0.207744,0.105951,-0.155393,0.206732,0.127743,-0.169168,-0.251844,0.166105,-0.066016,0.127945,0.525860,-0.393852,-0.210397,0.067502,0.252379,-0.259302,0.111893,0.010988,0.107691,0.058858,-0.196495,0.119106,-0.016591,-0.072657,-0.024028,-0.164027,-0.766744,0.053030,-0.114110,0.079779,-0.721549,0.189261,-0.282301,-0.054646,0.149158,-0.491394,-0.212716,0.211768,0.227219,0.263866,-0.302708,0.022504,-0.654683,0.244727,0.627311,0.141634,-0.316693,0.454004,-0.422258,-0.735319,-0.427979,-0.300107,-0.597931,-0.100466,0.483364,0.245024,-0.131028,0.447404,-0.578857,0.176740,-0.393394,-0.244328,-0.104317,-0.238004,-0.015385,-0.436667,-0.140848,-0.453291,-0.468837,-0.025423,0.034429,-0.481024,1.026610,-0.743044,0.183894,0.581100,0.204279,-0.191873,0.640853,0.039691,0.064583,-0.152992,-0.136740,0.485431,-0.263875,0.242466,0.016651,0.437655,0.117906,-0.322056,-0.348220,0.798925', '1870681', '26348103', '25932086', '27602116');
