INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27594653', '发财日记', '剧情', '故事讲述上世纪90年代初，穷小子小宝追随同村“发小儿”二哥，一路从贫穷朴实的东北农村来到了经济飞速发展的深圳。期间，两人无意中收留了一个嗷嗷待哺的婴儿，生活困窘的小宝和二哥该如何将孩子抚养长大？当小宝和二哥与同在深圳打拼的创业女青年马露“狭路相逢”，三人之间又将发生哪些令人捧腹的爆笑故事？一段笑泪参半、起伏跌宕的小人物奋斗史就此展开……', '宋小宝', '宋小宝', 5.7, 82041, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2632091530.jpg', 6.4, 24.5, 49.8, 15.2, 4, '0.296773,-0.378460,-0.306280,0.223557,-0.030338,-0.506527,0.473807,0.000075,-0.531283,0.056605,0.057908,0.806976,-0.107545,0.391650,0.229711,-0.211265,-0.190768,-0.650558,-0.047178,-0.128402,0.031304,-0.400942,-0.017088,0.185899,-0.162461,-0.033868,0.590900,-0.183803,-0.108547,0.524571,0.006566,-0.007745,-0.772591,-0.026885,-0.501437,0.185174,-0.091009,0.566717,-0.484494,-0.116979,-0.041487,-0.218989,-0.222000,-0.384189,0.118878,-0.002851,0.950288,-0.223892,0.104386,-0.110270,0.363737,0.181105,-0.494461,0.026522,0.112007,0.208615,0.428465,0.440670,0.141422,-0.316992,-0.214997,-0.370341,-0.160570,0.150389,0.073850,0.104362,-0.859027,0.291678,0.264612,-0.266291,0.219294,-0.533643,0.300700,0.727690,0.182094,0.929732,-0.178740,0.224215,-0.231355,0.416879,0.982507,0.041773,-0.155241,0.248726,0.026298,-0.323243,0.249678,-0.065362,-0.832009,0.073445,0.080580,-0.158226,-0.656929,0.498903,-0.598452,0.297311,-0.088111,0.085133,0.305360,-0.336915,-0.320125,-0.173463,-0.291304,-0.562980,-0.170429,0.001440,0.270508,-0.126561,1.008195,-0.783732,0.171886,0.112532,0.232020,-0.360555,0.593453,-0.035327,0.422152,-0.355096,0.330205,0.029404,-0.121015,0.032744,-0.084759,0.283165,-0.490308,0.035641,-0.221629,0.251823', '25738406', '3445516', '1292720', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27594938', '准备好了没', '悬疑', '格雷斯（萨玛拉·维文 Samara Weaving 饰）自幼失去双亲，成长在寄养家庭之中，这样的她再也没有想到自己竟然邂逅了豪门之子亚里克斯（马克·奥布莱恩 Mark O''Brien 饰），两人的恋爱顺利，通往婚姻的道路一路亮起绿灯。终于，格雷斯满心期待的那一天到来了，然而，在新婚之夜，亚里克斯却告诉了格雷斯一个非常古怪的消息。原来，在亚里克斯的家族中流传着这样一个传统，每一位嫁进来的新娘都必须在结婚当晚完成一个游戏，而游戏的具体内容则由抽牌来决定。虽然对这样的规矩万分不理解，但格雷斯还是决定忍一时风平浪静。万万没想到，格雷斯抽到了最糟糕的那张牌——捉迷藏，格雷斯必须在天亮之前找到一个可以躲藏的地方，不能够被任何的人发现，否则就只有死路一条。©豆瓣', '萨玛拉·维文', '马特·贝蒂内利-奥尔平', 6.8, 75957, 'tt7798634', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2559919245.jpg', 1.4, 8.8, 49, 32.2, 8.6, '0.272389,0.163594,-0.871431,0.688088,-0.224426,-0.442095,0.556213,-0.205201,-0.412477,-0.477285,0.065113,0.838290,-0.306902,0.088746,0.348306,0.069861,-0.248625,-0.345160,-0.022153,-0.349106,-0.443428,-0.563954,0.018715,-0.227748,-0.154419,-0.073579,0.517618,0.288916,0.038305,0.410214,0.380208,0.114482,0.009792,0.401044,-0.221344,-0.220456,0.066759,-0.006384,-0.134269,0.323422,0.028661,0.154719,-0.166384,0.435111,0.115940,0.347208,0.371051,-0.565183,-0.137543,0.281264,0.255200,-0.237079,-0.258773,0.062618,0.314807,-0.378339,0.187502,0.277890,-0.233118,-0.074854,0.016561,-0.038719,-0.763995,0.185997,-0.071652,0.246658,-0.485080,0.329656,-0.101533,-0.154761,0.031465,-0.412136,0.257234,0.522327,0.376125,0.159275,-0.432070,0.037243,-0.939619,-0.102433,0.618164,-0.104231,-0.141412,0.392570,-0.161379,-0.655223,-0.054649,-0.104545,-0.492044,-0.041212,0.275359,0.225262,-0.393403,0.231752,-0.448900,0.009492,-0.352598,-0.156123,0.051188,-0.586507,-0.127467,-0.389608,0.019664,-0.144552,-0.526358,0.448027,-0.159601,-0.322671,0.483375,-0.863693,0.354714,0.307011,-0.003011,-0.406109,0.708542,0.411323,0.346318,-0.154861,-0.141796,0.502529,0.314590,0.144991,-0.051069,0.387728,0.075076,-0.128425,-0.385910,0.784151', '1783461', '3055049', '3215099', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27595272', '冰峰暴', '动作', '喜马拉雅周边国家为了地区和平召开地区会议，议定《喜马拉雅公约》。会议召开前一架载有机密文件的飞机坠毁在珠峰南部，该文件可能危及喜马拉雅地区得之不易的和平局面。两名自称是印度军方紧急派出的特工，找到喜马拉雅救援队“翼小队”，请求协助登上珠峰秘密取回文件。尽管翼小队对此事心存疑虑，因陷入财务困难，犹豫再三，还是接受了珠峰领路的任务。但每个人并不知道在严酷的雪山之巅等待他们的将是什么……', '张静初', '余非', 4.3, 3637, 'tt8761374', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2575134653.jpg', 26.1, 41.9, 25.7, 3.9, 2.5, '-0.023491,0.332749,-0.956455,0.460394,0.380153,0.490197,-0.186549,0.066448,-0.455861,-0.314521,0.508654,0.662699,0.460012,-0.199273,0.211414,-0.200297,-0.591080,-0.686511,-0.171598,-0.082086,-0.459810,-0.658730,0.153566,-0.274251,0.121472,-0.230803,0.763339,0.527974,-0.295923,0.420881,0.169063,0.554084,-0.533697,0.387250,0.005935,-0.563815,0.516666,-0.259394,-0.534363,0.185533,-0.278989,-0.072352,-0.101026,0.217280,0.562609,0.503511,0.542235,-0.123815,-0.511276,-0.181490,-0.168367,-0.762064,0.186653,-0.076017,0.891367,0.336819,-0.347252,0.577943,-0.299006,0.121489,0.004603,-0.196280,-0.416439,-0.111709,0.090350,0.519905,-0.507441,0.338233,-0.457409,0.071031,-0.109971,-0.228350,0.320070,1.011290,0.164537,0.115992,0.287578,0.181138,-0.295491,-0.265275,0.807065,0.002254,-0.046705,-0.290231,0.202083,-0.688963,-0.039389,-0.183320,0.125232,0.008389,0.079234,-0.121730,0.107860,0.131498,-0.646792,0.086584,-0.364330,-0.726518,-0.022585,-0.447519,-0.009598,-0.566688,0.380664,0.233161,-0.299845,0.178795,0.164147,0.228772,0.528337,-0.588769,0.369371,0.517772,0.406725,-0.627625,0.554152,0.480171,0.029618,-0.523044,0.184814,0.156156,-0.026274,0.375681,-0.347204,-0.460291,-0.011671,-0.348114,-0.291976,-0.303284', '1424552', '1296947', '4193254', '1316511');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27596682', '路人女主的养成方法 Fine', '爱情', '某个春日，安艺伦也在樱花飞舞的坡道上与少女·加藤惠命运般地邂逅，并想着要制作以她为第一女主角的同人游戏。他邀请美术部所属、以同人插画师的身份活动的泽村·斯宾塞·英梨梨，以及学年第一的优等生、身为轻小说作家活跃中的霞之丘诗羽，共同成立了blessing software。并终于发表了第一部作品——。英梨梨和诗羽为了开发大作游戏《寰域编年纪》而前往人气创作者红坂朱音之处。blessing software的代表伦也继续社团活动，和副代表惠一起开始了新作的开发。他起用在做插画师的学妹·波岛出海，向身为制作人的出海之兄·伊织发出委托，和冰堂美智留及其乐队icy tail一同推进着新作的开发，然而……。英梨梨和诗羽的大作会变得如何？伦也和惠的关系发生异变？blessing software的新作究竟会走向何方？围绕着不起眼女主角的青春涂鸦，迎来终幕。', '松冈祯丞', '柴田彰久', 9.1, 6987, 'tt11203468', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2543633829.jpg', 0.9, 1.2, 7.6, 23.2, 67.2, '0.321483,0.004405,-0.417442,0.739387,0.287068,-0.180658,0.354445,0.191261,-0.094314,-0.380871,0.081377,0.783922,-0.420296,0.185765,0.460488,-0.052380,-0.350760,-0.859121,-0.081963,-0.180412,0.005692,-0.440255,0.093818,-0.020195,0.106223,-0.283387,0.870521,-0.015790,-0.391623,0.536474,0.473761,0.356168,-0.402896,0.136611,0.085350,-0.192720,-0.096539,0.197139,-0.227069,0.324279,0.075996,-0.449091,-0.272375,-0.073381,0.149021,0.427875,0.756450,-0.515215,0.112910,0.003083,0.467543,-0.156552,-0.015738,-0.058820,0.337741,0.201409,0.023463,0.394134,-0.181005,0.309008,-0.034864,-0.506714,-0.704526,-0.069906,0.427799,0.223691,-0.415765,0.447006,0.076203,-0.198532,0.290800,-0.106373,0.271365,0.459457,0.186387,0.373392,-0.116757,0.128985,-0.300582,0.382197,0.461310,0.134163,-0.189744,0.394504,-0.126241,-0.308871,-0.384479,-0.240066,-0.354833,-0.142394,-0.008958,0.091439,0.124873,0.017466,-0.641042,0.046997,0.018186,-0.211388,0.178551,-0.230658,-0.023206,-0.856102,0.094024,-0.292940,0.109670,-0.019109,0.154023,-0.431053,0.771856,-0.998710,-0.001494,0.314377,0.319489,-0.381803,0.657055,0.183070,-0.146141,-0.189628,-0.341603,-0.072306,0.081940,0.236394,-0.054893,0.178045,0.082939,-0.377582,-0.415640,0.162249', '3811356', '258809