INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27597250', '极限职业', '喜剧', '一支由5位掉漆警探组成的缉毒小组，因办事不力被长官钉得满头包，成天埋伏在毒贩巢穴对面的炸鸡店中监视，案情也毫无进展。既然每天都得待在炸鸡店，不如动手卖起炸鸡，看似无厘头的决定，竟让鲁蛇警探们意外找到事业第二春，卖到吓吓叫的神级美味炸鸡，让餐厅一夕爆红，订单电话接到手软！副业做太大的警探们有办法达成使命吗？对面的毒贩又是否会闻香而来呢？', '柳承龙', '李炳宪', 7.8, 168414, 'tt9541602', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2542216607.jpg', 0.3, 1.9, 26.3, 50.4, 21, '0.050842,-0.076045,-0.354767,0.133844,-0.109667,-0.087887,0.157138,0.350074,-0.174278,-0.042743,-0.018572,0.301272,-0.159583,-0.066061,0.269899,-0.028793,-0.041100,-0.455082,-0.092934,0.014556,-0.050040,-0.222314,-0.022062,-0.307148,0.085273,0.170219,0.259315,-0.193613,-0.086025,0.143541,0.056336,0.138829,-0.214120,0.155395,-0.074818,-0.172736,0.441916,-0.096678,-0.144449,0.066355,-0.110681,-0.225772,0.044074,-0.110580,0.338504,0.433228,0.290610,-0.036220,-0.662346,-0.039638,-0.083619,-0.224883,0.124358,-0.121628,0.635213,-0.046829,0.090554,-0.044285,-0.152616,0.193199,0.231369,0.166220,-0.841492,0.023491,0.202874,-0.034464,-0.385281,0.029489,-0.161632,0.078881,0.173172,-0.105922,0.237604,0.213174,0.308687,0.332183,0.182179,0.340116,-0.763705,0.154555,0.323795,-0.040880,0.063955,-0.178834,0.058694,-0.140848,0.297875,-0.213350,-0.025166,-0.070911,-0.034665,-0.002870,-0.088180,-0.242003,-0.404328,-0.002794,-0.086067,-0.302473,0.094762,-0.305192,-0.341596,-0.672000,0.408637,0.335108,-0.279392,0.432098,0.362256,0.195030,0.370664,-0.192528,0.134324,0.412139,-0.076684,-0.387227,0.314011,0.281998,-0.007131,0.041374,-0.291969,-0.260209,0.395294,0.365434,0.562335,0.117861,-0.069277,-0.264103,-0.224643,-0.159796', '30387441', '26747274', '1793491', '26703844');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27597950', '悬案密码4：64号病历', '悬疑', '丹麦悬疑犯罪片，该片刷新丹麦国产片票房纪录，是系列电影《悬案密码》的第四部，也是最终章，《悬案密码》系列改编自丹麦小说家尤西·阿德勒-奥尔森（JussiAdler-Olsen）的同名小说，', '尼古拉·雷·卡斯', '克里斯托弗·鲍伊', 7.3, 12132, 'tt6916362', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2529147387.jpg', 0.6, 3.8, 37.5, 45.2, 13, '-0.236398,-0.133949,-0.173042,0.596731,1.247106,0.032441,0.390045,-0.150259,-0.254458,-0.155865,0.115816,0.769795,-0.538804,-0.278997,-0.205473,0.232872,-0.669896,-0.737755,-0.056004,-0.728045,0.155846,0.039080,-0.573042,0.045444,0.142349,0.052543,1.159426,0.241953,-0.762009,-0.363147,0.900335,0.486443,-0.318232,-0.279397,0.004781,0.641926,0.246545,-0.491835,-0.418344,0.819673,0.082333,-0.172207,0.033117,-0.494946,0.088368,0.225140,0.809158,-0.288566,0.012673,0.470897,1.061423,-0.159041,-0.549256,-0.398565,0.149466,-0.105271,0.469073,0.435255,0.363355,0.117327,-0.003269,-0.157370,-0.911140,-0.118905,0.345747,0.650006,0.005140,0.247630,-0.968958,0.383434,-0.231969,0.144698,0.141223,-0.336864,1.170952,0.185941,0.154858,-0.020622,-0.175238,0.969025,-0.420742,0.252799,-0.576276,0.654082,0.023925,-0.880509,-0.517744,-0.454708,-0.447623,0.681564,0.724847,-0.253928,0.315660,0.471028,-1.050671,-0.000139,0.040686,-0.468563,-0.331132,-0.209872,0.276883,-0.638553,-0.318510,0.312156,0.179610,-0.332561,0.475523,-0.653053,0.593361,0.354767,0.087245,0.703961,-0.370093,-0.022039,0.862917,0.259521,-0.478230,-0.041704,0.336457,0.587754,-0.027243,-0.064723,-0.506396,0.110854,0.527353,-0.668611,-0.318561,0.433630', '26823502', '26759820', '2042226', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27600925', '卡斯特纳与小星期二', '剧情', '故事发生在1929年的德国柏林。埃里希（弗洛里安·大卫·菲茨 Florian David Fitz 饰）是一位小有名气的作家，创作过很多脍炙人口的作品。一天，一个名叫汉斯（尼科·拉莫·克莱曼 Nico Ramon Kleemann 饰）的小男孩出现在了埃里希的家门口，他告诉埃里希自己是他的超级粉丝。刚开始，埃里希对于汉斯的存在并没有太过在意，但随着时间的推移，他发现这个脑袋里充满了奇思妙想的男孩能够成为自己创作的灵感来源。在埃里希的推荐之下，汉斯也得到了一个在电影里扮演角色的机会，一来二去之间，一老一少两人结下了深厚的友谊。二战爆发了，纳粹的铁蹄踏破了埃里希和汉斯的宁静生活。©豆瓣', '弗洛里安·大卫·菲茨', '沃尔夫冈·穆尔恩贝格', 8.3, 8141, 'tt5126602', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2513672656.jpg', 0.1, 0.9, 13.4, 52.9, 32.7, '0.528792,-0.002167,-0.836935,0.701269,-0.152121,-0.223268,0.982282,-0.008117,-0.717276,-0.332147,-0.038699,0.929789,-0.503936,0.242859,0.469257,-0.142059,-0.197981,-0.882395,0.190616,-0.354002,-0.058594,-0.550894,-0.393213,-0.197938,-0.253256,-0.459707,0.687349,0.090027,-0.235873,0.447716,0.305704,0.263058,0.311839,0.485679,-0.234256,0.213290,0.394910,-0.286357,-0.056613,0.269272,0.136035,-0.183259,-0.152667,0.263375,-0.116272,0.294024,0.444630,-0.265293,-0.026371,0.221341,0.482641,-0.156663,0.072651,-0.070964,0.257974,0.030445,0.160525,0.238664,-0.140740,0.073782,-0.096081,-0.129277,-0.743522,-0.005420,0.010847,0.332062,-0.724903,0.391985,0.016271,-0.176123,-0.049909,-0.365948,0.135603,0.392314,0.242111,0.375472,-0.185293,-0.038498,-0.521630,0.187421,0.507730,-0.040967,-0.374508,0.592248,-0.295225,-0.492754,-0.251138,-0.135140,-0.502184,-0.068860,0.390498,-0.146642,-0.143708,0.356485,-0.629995,0.048195,-0.239348,-0.410050,-0.097049,-0.266196,-0.234668,-0.698154,-0.388513,-0.581766,-0.310843,-0.029562,-0.141787,-0.514927,0.966849,-0.899743,0.209840,0.593448,0.083083,-0.002745,0.805255,0.151348,0.009100,-0.063734,0.075282,0.320687,-0.004740,0.071488,0.129737,0.440245,0.105091,-0.353308,-0.333748,0.694627', '30162520', '1870681', '1783461', '1303449');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27601006', '翠丝', '剧情', '★ 港版《丹麦女孩》 勇敢用爱为自己发声！★ 金马影后惠英红 继《血观音》后话题演出★ 本届金马奖 最佳男配角 最佳女配角 双料入围金马奖影后惠英红年度话题演出。安宜（惠英红 饰）与结缡多年的老公大雄（姜皓文饰）在同个屋簷下，一同育有儿子（吴肇轩 饰）与女儿（余香凝 饰），出嫁的女儿也已有孕在身，一切看似和乐无忧，但她竟却从未发现与枕边人原来是同床异梦。某日深夜老公接到越洋来电，得知儿时老友已在伦敦逝世，致电告知的是他的合法同婚伴侣阿邦（黄河 饰），并预计携带老友骨灰返港安置。与此同时，老公又安宜客串票戏的场合，重遇他儿时认识的昔日粤剧花旦打铃哥（袁富华 饰）。故友骤逝又加上巧遇故知，翻起老公许多往事，他决定坦承揭示深藏已久的秘密：他想要变性。安逸过著师奶生活多年的安宜，自认平静的婚姻生活顿时发生剧烈家变，她与家人将如何面对曾是一家之主的人，如今改名唤做「翠丝」……？◇导演：新锐导演 李骏硕◆演员：【拆弹专家】姜皓文【血观音】惠英红【红衣小女孩系列】黄河【树大招风】袁富华【一念无明】吴肇轩【骨妹】余香凝', '姜皓文', '李骏硕', 6.9, 14309, 'tt7762748', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2540428736.jpg', 1.3, 7.5, 45.4, 35.1, 10.7, '-0.223575,-0.033426,-0.445065,0.428477,0.017623,-0.266718,0.424569,-0.033486,-0.552854,-0.337011,0.165012,0.841641,-0.366578,0.198513,0.248815,0.037344,-0.070075,-0.662471,0.039939,-0.004954,0.239383,-0.284537,-0.212702,0.209143,0.011461,-0.228127,0.497608,-0.136993,0.101133,0.357350,0.553751,0.004659,-0.415642,0.254477,-0.039818,0.214044,-0.021865,0.281841,-0.555001,0.137735,0.001619,-0.308989,-0.202046,-0.056403,0.072652,0.340072,0.349154,-0.075710,-0.046908,-0.086676,0.477270,-0.038747,-0.032822,-0.067529,0.212891,-0.026359,0.370272,0.360072,-0.107472,-0.186321,0.023926,-0.084305,-0.153379,0.178667,0.271672,0.152721,-0.260610,0.222019,-0.234648,0.209096,-0.098855,-0.188856,0.113699,0.018937,0.080145,0.092198,-0.140497,0.175909,0.014036,0.713360,0.442171,0.119034,0.042391,0.322815,0.064076,-0.378278,0.058213,-0.144797,-0.499994,0.139897,0.044765,0.108169,0.059539,0.155671,-0.139227,-0.167630,-0.249067,0.219528,0.343737,-0.027388,0.014777,-0.394036,-0.180464,-0.191904,-0.253149,-0.232021,0.157694,-0.353285,0.521979,-0.621956,0.090159,0.174206,0.078834,-0.431401,0.426905,0.202136,0.032515,-0.497582,0.106838,0.232467,-0.332282,-0.075238,0.004362,0