INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27602116', '我的英雄学院：两位英雄', '动作', '继《海贼王》、《火影忍者》、《死神》三大巨作后，日本第一漫画刊《周刊少年JUMP》近十年力推巨作，《我的英雄学院》创造了一系列绝佳成绩，引人注目。这个讲述大多数人都有超能力的未来，一个毫无能力的少年如何成为英雄的故事，在日本、美国、中国等地引发绝佳成绩和好评。作为该作首 部剧场版，在海外取得令人称道的成绩和好评，以主角绿谷出久与师傅欧鲁迈特联手对敌的新故事，讲述了一个简单又热血激昂的青春战斗故事，传承少年热血漫传统的同时，大胆创新、场面激烈、有笑有泪，令人瞩目。', '山下大辉', '长崎健司', 6.9, 33376, 'tt7745068', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2548783889.jpg', 2.8, 7.1, 44.1, 33, 12.9, '-0.203764,0.108305,-0.463761,0.767278,0.233379,-0.019700,0.167820,-0.187633,-0.204613,-0.151958,0.129762,0.975884,-0.278148,0.171454,0.184044,-0.329870,-0.193380,-0.718347,-0.200925,-0.150266,-0.035745,-0.140081,-0.231549,0.009446,-0.179361,-0.364805,0.765587,-0.004292,-0.583540,0.341520,0.394090,0.220493,0.082242,-0.045893,-0.172257,-0.047683,0.447130,0.272981,-0.187656,0.253104,-0.235474,-0.205591,-0.280197,0.129886,-0.272379,0.007032,0.488508,-0.182701,-0.240102,0.060798,0.814887,-0.279238,-0.231194,-0.085867,0.366962,0.017839,0.161574,0.070225,0.306058,-0.170780,-0.342159,-0.279722,-1.241775,-0.210518,0.294647,0.010051,-0.356338,0.699907,0.192652,-0.332416,0.384185,-0.088407,-0.180070,0.180629,0.688901,0.253790,0.144164,0.286535,-0.079331,0.666460,0.531797,0.045475,-0.488157,0.285979,-0.219420,-0.570982,-0.075586,-0.526105,-0.319829,0.193544,0.303958,-0.001463,0.198858,0.314720,-0.521375,0.168047,-0.088506,-0.216378,0.135405,-0.290373,-0.145398,-0.626637,-0.372742,-0.240675,-0.193184,-0.172165,0.295216,-0.303104,1.532250,-0.762332,-0.164253,0.457833,-0.148154,-0.489645,0.529689,0.297259,-0.039984,-0.174578,-0.126164,0.051820,-0.080923,0.166161,-0.169235,0.541426,0.009260,-0.259087,-0.436605,0.502127', '24284209', '3718665', '3072064', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27603669', '为你写诗', '喜剧', '你的一生中有过一个让自己心跳加速的人吗？故事里抑郁不得志的中年龙套演员陈诗杰在一次心脏病发后意外发现，只要自己心跳加速到160，就可以穿越回到大学时代。陈诗杰决定利用这个机会来改写人生的遗憾，追回如今已是国际影后的大学女神黑小甄。于是他不顾医生叮嘱，喝刺激性饮料、剧烈运动、挑战高空跳水、高台滑雪......想尽办法让自己的心跳加速到160回到过去。可每每以为可以很牛逼的改变一切，却总是更怂逼的一败涂地。尽管遭受着黑小甄野蛮的蹂躏，情敌的摧残，但来自未来的陈诗杰并没有想要放弃！在一次次穿越的同时，问题也接踵而至，他发现心脏已经无法承受负荷。在濒临死亡的时刻，陈诗杰会选择接受这惨败的人生，还是拼尽最后的力气为心爱的人再傻一次呢？', '吴克群', '吴克群', 3.7, 3458, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2537681630.jpg', 48.1, 30.2, 12.7, 5.3, 3.7, '-0.236340,0.173809,-0.832892,0.500216,-0.197702,-0.541717,0.702645,0.045436,-0.269806,-0.186112,0.311641,0.628490,-0.167937,0.234945,0.366098,-0.146053,0.074994,-0.619158,0.260820,0.083442,-0.491132,-0.244797,-0.104755,-0.218793,-0.114874,-0.370061,0.664246,0.189380,-0.562150,0.170761,0.281135,-0.147010,0.392495,0.751732,-0.294999,0.091151,-0.239176,0.148158,-0.180340,0.281071,0.486180,-0.260617,-0.041708,0.477487,-0.220707,0.154326,0.627374,-0.251136,-0.325362,-0.020756,0.438864,-0.374096,-0.211240,0.064629,0.094274,-0.022197,0.108297,-0.194996,-0.141999,0.219091,0.083120,0.266441,-0.846119,0.018932,0.076026,0.039666,-0.832978,0.251406,-0.054031,0.188476,0.075371,-0.248566,-0.024330,0.281684,0.490722,0.458249,-0.615885,0.110925,-0.361346,0.048838,0.951491,-0.040278,-0.540298,0.457863,0.009819,-0.267747,-0.009629,-0.376912,-0.554771,0.135234,0.031525,0.329198,-0.399206,0.290132,-0.302571,-0.000816,-0.247519,-0.196621,-0.066466,-0.452482,-0.105461,-0.187728,-0.003436,0.050539,-0.054701,0.225664,0.008505,-0.503055,0.503979,-0.484543,0.235105,0.742834,0.292652,-0.578225,0.473030,0.379410,-0.125335,-0.095900,-0.071736,0.529198,-0.184228,0.478918,0.033032,0.137243,-0.122143,-0.016284,-0.454360,0.664679', '1309116', '1292064', '25828589', '6874741');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27604296', '家和万事惊', '喜剧', '敦厚老实的中介卢伟文（吴镇宇 饰）与家庭主妇妻子淑贤（袁咏仪 饰）、失业愤青儿子（吴肇轩 饰）、沉迷网恋的女儿（蔡颂思 饰）及生活不能自理的父亲（张达明 饰）一家五口过着每月要还房贷的节衣缩食生活。鸡毛蒜皮的邻里纠纷、还不完的买房贷款、上有老下有小的尴尬处境，都成了这个家随时爆发争吵的源泉，而他们唯一舒缓焦虑的就是那一扇窗外的海景。可万万没想到的是，突然有一天，一块飞来广告牌完完全全阻挡到了整家人的视线，他们再也没有办法去舒缓压力。而这块广告牌的主人王小财（古天乐饰）却不以为然。解决无期、焦虑升级，卢伟文一家的疯狂计划就此展开……', '吴镇宇', '邱礼涛', 5.9, 15931, 'tt8443432', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2545486388.jpg', 4.7, 21.4, 51, 18.7, 4.2, '0.076124,-0.068194,-0.562412,0.318553,-0.133534,-0.491248,0.709892,0.416314,-0.122963,-0.179297,0.238321,0.391746,0.051139,0.263920,0.105446,0.139799,-0.145926,-0.358356,0.073636,0.222908,-0.025342,-0.346799,-0.103702,-0.352219,-0.147679,-0.081975,0.494823,0.192866,-0.012383,0.368718,0.385104,0.011299,-0.095070,0.385893,-0.334556,0.128095,-0.199361,0.233082,-0.221069,-0.121810,0.057503,-0.194858,-0.102265,0.246323,0.191816,0.460976,0.617886,0.058486,-0.354715,0.158882,0.243022,-0.122624,-0.158847,0.221212,0.081374,-0.126714,0.225167,-0.018759,-0.447014,0.066150,0.247942,-0.005619,-0.741470,-0.035263,0.101141,0.104727,-0.518651,0.450792,-0.053970,-0.299481,-0.059612,-0.377548,0.253631,0.453814,-0.025385,0.582968,-0.610748,0.029167,-0.686608,0.473886,0.585584,0.083768,-0.341960,0.430896,-0.240275,-0.158935,-0.026940,-0.341137,-0.596850,-0.173422,0.169492,0.208220,-0.197298,0.021240,-0.689529,0.031561,-0.150232,-0.225004,0.068381,-0.363874,-0.011082,-0.272100,-0.083248,-0.318761,-0.441755,0.358443,0.157165,-0.274142,0.338269,-0.527957,0.176869,0.363514,0.357595,-0.461007,0.563159,0.069857,0.199403,-0.015516,-0.286397,-0.128266,-0.040650,0.397337,0.131033,0.177591,0.079370,-0.202573,0.037931,0.484393', '1306666', '21619567', '26857170', '1299932');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27605105', '玉面情魔', '剧情', '斯坦顿（布莱德利·库珀 Bradley Cooper 饰）是一个穷困潦倒的男人，误打误撞之中来到了流动马戏团，在这里，他凭借着自己的聪明才智为自己某得了一份差事——为塔罗牌占卜师赞娜（托妮·科莱特 Toni Collette 饰）和她的情人皮特（大卫·斯特雷泽恩 David Strathairn 饰）工作。从这两个人身上，斯坦顿学会了如何依靠巧舌如簧和敏锐观察来施展观众们眼中的“魔法”。与此同时，斯坦顿还在马戏团里邂逅了名为茉莉（鲁妮·玛拉 Rooney Mara 饰）的女孩，随着时间的推移，斯坦顿和茉莉之间产生了感情。最终，斯坦顿带着茉莉离开了马戏团，他们坚信他们能够靠自己的双手打开一片属于他们的天地。一晃眼多年过去，虽然斯坦顿在占卜圈已经小有名气，但他并不满足，渴望更多的金钱。此时，一个名叫莉莉丝（凯特·布兰切特 Cate Blanchett 饰）的女人出现在了他面前。', '布莱德利·库珀', '吉尔莫·德尔·托罗', 6.8, 27266, 'tt7740496', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2757579107.jpg', 0.8, 7.6, 50.3, 33.6, 7.6, '0.442571,0.164090,-0.738407,0.639843,-0.267452,-0.312010,1.010749,0.080324,-0.628132,-0.243546,0.075867,0.860189,-0.283360,0.096969,0.093187,0.238024,-0.576625,-0.818554,0.000643,-0.397099,-0.259328,-0.545522,-0.413531,-0.161341,-0.290994,-0.258914,0.476107,0.025737,0.010975,0.464786,0.223627,0.140501,0.182431,0.386688,-0.146498,0.092385,0.296037,-0.159428,-0.061051,0.433833,0.239475,-0.133069,-0.260855,0.091858,-0.107323,0.126857,0.627607,-0.250872,0.101538,0.002559,0.098555,-0.235643,0.120597,0.155647,0.085590,-0.198445,0.190065,-0.045647,-0.430290,0.136495,-0.029688,-0.222194,-0.735752,0.053226,-0.139527,0.187837,-0.816135,0.383946,-0.088913,-0.345086,0.210930,-0.429880,-0.027426,0.155193,0.019045,0.409797,-0.140434,-0.163013,-0.430304,-0.079790,0.302677,0.062244,-0.159458,0.533041,-0.415974,-0.407943,-0.309075,0.047131,-0.392585,-0.280020,0.271836,0.098915,0.077258,0.212848,-0.561233,0.113391,-0.200309,-0.153541,-0.120637,-0.503226,-0.153683,-0.603497,-0.333119,-0.509161,-0.364811,0.093873,0.049656,-0.191247,0.632055,-0.929991,0.324197,0.574423,0.328263,0.047459,0.801125,-0.010832,0.167396,-0.299429,-0.245647,0.255883,0.104708,0.275661,0.369301,0.543641,0.106396,0.064625,-0.369938,0.723804', '3230121', '1309172', '3111650', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27605698', '西虹市首富', '喜剧', '西虹市丙级球队大翔队的守门员王多鱼（沈腾 饰）因比赛失利被教练开除，一筹莫展之际王多鱼突然收到神秘人士金老板（张晨光 饰）的邀请，被告知自己竟然是保险大亨王老太爷（李立群 饰）的唯一继承人，遗产高达百亿！但是王老太爷给出了一个非常奇葩的条件，那就是要求王多鱼在一个月内花光十亿，还不能告诉身边人，否则失去继承权。王多鱼毫不犹豫签下了“军令状”，与好友庄强（张一鸣 饰）以及财务夏竹（宋芸桦 饰）一起开启了“挥金之旅”，即将成为西虹市首富的王多鱼，第一次感受到了做富人的快乐，同时也发现想要挥金如土实在没有那么简单！©豆瓣', '沈腾', '闫非', 6.6, 964935, 'tt8529186', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2529206747.jpg', 4, 13.5, 43.7, 28.6, 10.3, '-0.032487,0.246861,-0.617464,0.544814,-0.125755,-0.359762,0.283202,0.121061,-0.629849,-0.458673,0.165460,0.697312,-0.175836,0.028022,0.352711,-0.137726,0.315934,-0.522597,-0.062847,-0.169832,-0.202811,-0.544351,-0.023403,0.022750,-0.207931,-0.114255,0.544375,-0.000923,-0.189797,0.382398,0.430005,0.370007,0.289738,0.331971,-0.202867,0.099766,0.167607,0.170253,-0.453380,0.250907,0.012189,0.002002,0.103481,0.026267,0.310427,0.310929,0.311380,-0.483458,-0.222576,-0.033516,0.436602,-0.082492,-0.184368,0.152486,0.215806,0.084698,0.458474,0.145782,-0.360720,-0.073723,0.340387,-0.119421,-0.874299,0.085422,0.165538,0.044943,-0.439607,0.286965,-0.358801,-0.098358,0.088256,-0.223906,0.294267,0.400588,0.237736,0.114619,-0.340947,-0.029289,-0.548410,0.348466,0.511397,0.079746,-0.078400,0.076654,-0.019203,-0.495139,0.138465,-0.487585,-0.220102,0.413785,0.308584,0.235695,0.184997,-0.045099,-0.401427,-0.144865,-0.227654,-0.216378,0.291560,-0.621856,-0.104645,-0.285538,0.010805,0.004941,-0.270518,0.260631,0.067561,-0.292177,0.661934,-0.847909,0.022935,0.157351,0.558622,-0.551265,0.655597,0.043569,0.043512,-0.264239,0.023800,-0.138471,0.261917,0.290643,0.244332,0.090342,-0.045094,-0.593323,0.109513,0.289273', '1793491', '4301278', '1304382', '27056396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27607378', '龙珠超：布罗利', '动作', '全新的“赛亚人”故事。力量大会后，悟空了解到宇宙中还存在着自己未曾见过的 强者。某天，现身于悟空和贝吉达面前的是从未见过的赛 亚人布罗利。三个走上完全不同道路的赛亚人，为集齐七 龙珠意外相遇，从地狱中再度归来的弗利萨也被卷入其中， 地球将爆发一场壮烈战斗……', '野泽雅子', '长峰达也', 7.2, 49740, 'tt7961060', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2557371503.jpg', 0.9, 6.4, 39.4, 38.9, 14.4, '0.082874,0.391937,-0.881748,0.709162,0.217868,-0.232478,0.821770,-0.402252,-0.396434,-0.116345,-0.112834,1.059182,-0.756615,0.311934,0.617059,-0.257078,0.065163,-0.851950,-0.516884,0.094270,-0.419512,-0.348958,-0.534807,0.171101,-0.191588,-0.678499,0.618976,0.484062,-0.341557,0.578033,0.325372,0.291238,-0.556912,0.511027,-0.233237,-0.046048,-0.147319,0.311226,-0.256566,0.267831,-0.121814,0.014508,-0.102123,0.661969,-0.067827,0.052254,0.594638,-0.905159,0.238411,-0.201979,0.177208,-0.126639,-0.319220,0.002172,0.455181,0.140417,0.099723,0.095155,0.385404,0.459574,0.079693,-0.308842,-0.930818,-0.027143,-0.315091,0.134352,-0.482568,0.086340,0.114578,-0.151681,-0.038342,-0.069927,0.217787,0.361131,0.543819,0.398974,-0.292396,-0.206831,-0.511542,-0.146316,0.857351,-0.084635,-0.466277,0.365909,0.143312,-0.825003,-0.360233,-0.543772,-0.152379,0.214555,0.324122,0.464951,-0.019176,0.442858,-0.772409,-0.019437,-0.373174,-0.281989,-0.279253,-0.028756,-0.125299,-0.522246,-0.342720,-0.316250,-0.420626,0.146429,0.031337,-0.353026,0.672871,-0.761364,0.539806,0.226911,0.325061,-0.171869,0.801428,-0.114090,0.187623,-0.282715,-0.035857,0.262092,-0.101713,0.353759,0.126591,0.467728,-0.147323,0.009448,-0.524937,0.760461', '30162520', '19899707', '3006892', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27607392', '故事贩卖机', '喜剧', '据悉，电影《故事贩卖机》由四个独立的城市怪谈故事单元组成，其中《驯兔记》皮皮鲁看见身边同学逐渐变成兔子时选择是否被驯化；《鬼打墙》悬疑重重，引人尖叫的同时吸引力十足；《官能许愿》则讲述了以失去器官为代价获得超能力的城市穿越爱情故事；《鸡汤泡面》则赋予了普通泡面迷幻剂一般的神奇力量，荒诞的同时又笑料百出。', '曹云金', '朱佳梦', 5.6, 3237, 'tt9036980', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2508067269.jpg', 7.6, 22.1, 53.6, 13.9, 2.7, '0.163953,0.064146,-0.067530,0.616353,0.022337,0.053212,0.696694,0.175208,-0.138141,-0.181099,0.115500,0.486926,-0.203472,-0.036775,-0.071891,-0.456993,-0.089633,-0.396751,-0.274271,-0.065750,-0.364495,-0.123243,-0.191770,-0.200300,0.011728,-0.570273,0.486585,-0.216215,-0.371865,-0.090753,0.281125,0.327401,-0.358342,-0.031423,0.051760,0.084880,0.100098,-0.093977,-0.325427,0.142077,-0.333130,-0.144366,0.096511,0.144037,-0.434627,-0.301267,0.797891,-0.453396,-0.289373,-0.631348,0.626306,0.230823,-0.192543,-0.273463,0.159326,0.365539,0.527968,-0.230971,-0.030255,0.212026,0.340062,-0.059046,-0.843966,-0.226040,0.312552,0.082517,0.041237,-0.125192,0.183516,0.087538,0.447009,-0.016641,-0.084406,-0.132062,0.871015,0.735579,-0.019289,0.173777,-0.437134,-0.047826,0.356016,-0.015611,-0.473735,0.459907,-0.486470,-0.339379,0.085819,-0.130948,0.155505,0.330768,0.032359,0.451800,0.006346,0.550052,-0.898707,0.125084,0.030936,-0.139781,0.128620,-0.114409,-0.435634,-0.768608,0.018116,0.532802,0.271870,0.074001,0.286291,-0.164372,0.973197,-0.282730,0.180135,0.471660,0.082230,-0.292523,0.388178,-0.401967,-0.158261,-0.464318,0.020744,0.246016,0.066063,0.341549,0.153977,0.274159,-0.397197,0.017672,-0.534768,0.621892', '4181031', '27199913', '3318306', '2364051');
