INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27608279', '网诱惊魂', '悬疑', '故事描述一名英国记者为了调查百名欧洲女子皈依伊斯兰教，并前往伊斯兰国加入ISIS的原因，创立了一个假帐号，与叙利亚的圣战士展开了交流，试图得到更多资讯，但对方一心只想娶她为妻。然而在身份不断切换之时，这位记者也逐渐迷失自己。', '瓦伦·凯恩', '提莫·贝克曼贝托夫', 7.2, 13999, 'tt7826276', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2640506011.jpg', 1.2, 4.3, 37.2, 45.9, 11.3, '0.088538,0.289633,-0.492978,0.971819,0.061722,-0.133588,0.315227,-0.188523,-0.470386,-0.634036,-0.228075,0.931857,0.032652,-0.018419,0.421843,-0.043192,-0.305007,-0.594404,0.302532,-0.079010,0.176660,-0.465954,0.014094,-0.471303,-0.360236,-0.149540,0.902655,0.135438,-0.422206,0.036721,0.267423,0.260542,-0.204833,0.413198,-0.088110,-0.314179,0.090007,-0.195291,-0.351079,0.346649,-0.156241,-0.376368,-0.114480,0.185551,-0.308413,0.270675,0.571894,-0.310029,0.008057,-0.343662,0.330410,-0.281612,0.144113,0.317835,0.143177,0.198558,0.368814,0.368349,0.161679,0.105680,-0.175304,-0.244317,-0.707179,0.055957,0.113282,0.141284,-0.320785,0.085514,-0.531250,0.002539,-0.082584,-0.026936,0.178162,0.750416,0.186281,-0.154323,-0.271397,-0.214525,-0.349909,0.241375,0.610494,0.147908,-0.085343,0.395704,0.079392,-0.646907,0.016338,0.104698,-0.193817,-0.145460,0.066419,0.208676,-0.084571,0.466277,-0.676642,-0.205493,-0.474254,-0.491189,0.157442,-0.401584,0.314089,-0.561437,-0.425250,0.151488,-0.131061,-0.197470,0.266498,-0.148270,1.093720,-0.852344,0.080352,0.598345,0.556821,-1.143028,0.641809,0.225104,0.203775,-0.374472,-0.370069,0.499689,0.352412,0.235099,-0.407240,0.043060,-0.275208,-0.425238,-0.233951,0.081301', '27602116', '4301278', '30465281', '1303451');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27608785', '沉默的教室', '剧情', '1956年，两位高中生提奥和库特在去西柏林看电影的路上见到了匈牙利十月起义的新闻报道。为了对起义的死者表示悼念，他们和同班同学们决定，一起在课堂上无视老师，突发沉默一分钟。然而这短短的一分钟彻底改变了班上同学的命运，许多人从此被东德安全局视为眼中钉，加以监视和迫害。在 班级被强行解散后，他们却决心在西德重新结集，不过是以作为逃亡者的新身份。', '乔纳斯·达斯勒', '拉斯·克劳梅', 8.4, 29506, 'tt6576556', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2513164684.jpg', 0.4, 0.9, 12.3, 51.5, 35, '0.380054,-0.108553,-0.579424,0.489712,-0.086756,-0.270461,0.515408,0.092520,-0.605780,-0.198815,-0.121696,0.928483,-0.454564,0.229312,0.427950,-0.445665,-0.614070,-1.160677,-0.196005,-0.398026,-0.454227,-0.517492,0.065731,-0.276390,-0.003784,-0.470864,0.564743,-0.060066,-0.003643,0.659580,0.298643,0.342980,0.152940,0.425946,-0.321738,0.048923,0.096100,-0.202306,-0.359164,0.244734,-0.022340,-0.378634,-0.396267,0.112885,0.115594,0.414192,0.776499,-0.064812,-0.253689,-0.219876,0.356911,-0.566416,-0.189856,0.318858,0.834455,0.185378,0.258245,0.401138,-0.127512,0.063039,-0.086046,-0.078498,-0.519791,0.059463,0.043261,0.033621,-0.683758,0.914885,0.110715,-0.021334,0.187157,-0.370079,0.190644,0.668871,0.199612,0.449889,-0.190057,-0.156662,-0.511064,0.084418,0.845593,-0.085921,-0.321668,0.155133,0.185790,-0.183875,-0.011443,-0.114014,-0.396013,-0.088890,0.199132,0.035911,-0.315723,0.118837,-0.594989,-0.241868,-0.248630,-0.603518,0.155464,-0.796598,0.014468,-0.795408,-0.203573,-0.328541,-0.267675,0.258820,0.190602,-0.126194,0.905463,-0.910130,0.169115,0.408718,0.520615,-0.730413,0.867451,0.295944,0.165769,-0.073876,0.156057,-0.065252,0.387661,0.619827,0.270467,0.402916,-0.033924,-0.174210,-0.492746,0.217619', '3212120', '4202326', '10876425', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27611496', '神之一手：鬼手篇', '动作', '权相佑饰演的主人公“鬼手”一角，是小时候因为赌棋失去一切，要对放弃自己的人实施报复的人物。权相佑将在没有替身的情况下直接消化所有动作。权相佑说：“毫不夸张地说，我在 这部电影中什么都干过，非常强烈，很好。我将竭尽全力去拍摄。”', '权相宇', '李凎', 6.9, 6869, 'tt11177112', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2573073796.jpg', 0.8, 6.9, 48.3, 32.4, 11.7, '0.361753,-0.266057,-0.786993,0.625877,-0.432984,0.374699,1.023446,-0.269088,-0.500411,-0.267042,0.241547,0.902646,-0.324243,-0.199621,-0.067369,0.122750,-0.315939,-0.783723,-0.265917,0.233864,-0.229996,-0.546390,-0.073844,0.100895,-0.417835,-0.142276,0.797453,0.040463,-0.440042,-0.149810,0.386831,0.036734,0.247487,0.687209,-0.048650,0.165049,-0.436670,-0.229394,-0.016015,0.548400,0.511337,-0.565990,-0.359495,0.630644,0.099440,0.361837,0.432778,-0.344553,-0.278942,0.316748,0.250163,-0.609154,0.016119,0.226434,-0.080851,0.115812,0.220692,0.437485,-0.476733,0.081185,0.034239,-0.237657,-1.071984,-0.152328,0.198870,0.262011,-0.797878,0.243866,-0.134827,0.156099,0.372422,-0.538224,0.278413,0.037284,0.447928,0.112984,-0.085498,-0.064612,-0.526159,0.413112,0.808342,0.165974,-0.009493,0.610167,0.037164,-0.284761,-0.385175,-0.159431,-0.527361,0.191602,0.060857,0.130873,-0.410937,0.157104,-0.225005,-0.041943,0.042166,-0.580183,-0.339064,-0.742217,0.148718,-0.564499,-0.191658,-0.444222,-0.200846,-0.398048,0.010805,-0.747863,0.785478,-1.119257,-0.039249,0.549574,0.474716,-0.299289,0.403255,0.186638,-0.200431,-0.092086,0.031772,-0.033957,0.145993,0.240389,0.512346,0.356164,0.301389,-0.122282,-0.307770,0.777693', '1793491', '1783461', '30163500', '6745433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27611498', '王者天下', '剧情', '故事以未曾经历统一、战乱不止的中国战国时代为舞台，主人公李信是一位秦国的少年，他因为战乱而失去双亲，并在收留自己的里长家里过着奴隶一样的生活。里长家里收留了两名战争孤儿信和漂。然而，身为孤儿的信和漂并没有因为身份的卑贱而失去志向，反而这战事频繁的乱世中，立志要成为大将军，两人一同苦练武功。他们以成为名震天下的大将军为目标，每日磨练自己，等待机会建功立业。某天，漂被带入宫中任官。及后濒死的漂回到家中，信在漂指引下，见到了因为政变而被追杀的秦国大王嬴政，他戎马天下的人生便由此拉开了序幕……', '山崎贤人', '佐藤信介', 6.4, 11661, 'tt9099938', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2548852197.jpg', 3.4, 14.7, 49.2, 23.9, 8.8, '0.127872,0.027412,-0.534418,0.541309,0.009453,-0.280539,0.543749,0.040785,-0.631580,-0.456788,-0.008798,0.818207,0.288583,0.142214,0.202676,-0.337764,-0.159291,-0.879910,-0.257925,0.060861,-0.121027,-0.186841,-0.158594,-0.051600,-0.356229,-0.269355,0.947003,0.115459,-0.094321,0.709278,0.142426,0.197577,-0.038497,0.515685,-0.537794,0.035482,-0.198410,0.139596,-0.336905,0.280277,-0.315888,-0.400395,-0.256857,0.157903,-0.107379,0.186695,0.489639,-0.544321,-0.001298,-0.400423,0.270707,-0.265553,-0.069665,0.113528,0.470136,0.136850,0.229633,0.461864,0.082298,-0.091755,-0.107086,-0.176176,-0.735597,-0.147165,0.127293,0.033757,-0.723715,0.456770,0.035506,-0.377376,-0.085516,-0.118125,0.347253,0.507931,0.346067,0.212687,-0.405659,-0.074719,-0.522882,0.375308,0.804655,-0.217990,-0.343930,0.359199,0.029522,-0.356179,0.350077,-0.506069,-0.574346,-0.088009,0.038969,0.067201,-0.213365,0.318545,-0.257858,0.186717,-0.553575,-0.250793,0.093515,-0.177776,-0.220738,-0.123713,-0.335340,-0.324702,-0.422712,0.066843,0.074829,-0.231793,0.681515,-0.864634,0.246775,0.438076,0.321157,-0.769192,0.635412,0.235478,0.373343,0.021578,-0.065789,0.268957,0.055874,0.349806,-0.139171,-0.172746,-0.359269,-0.046797,-0.456703,0.524279', '35030151', '30345227', '1301022', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27611667', '喜宝', '剧情', '姜喜宝（郭采洁 饰）出生在一个贫困的家庭之中，从小到大她吃尽了贫穷的苦头，对于金钱有着格外强烈的渴望。一次偶然中，姜喜宝在飞机上结识了名为勖聪慧（李彦漫 饰）的女孩，并且得知勖聪慧是衔着金汤匙出生的千金小姐。聊得格外投机的两人很快就成为了好朋友。通过勖聪慧，姜喜宝和她的父亲勖存姿（张国柱 饰）相识了。勖聪慧本想撮合喜宝和自己的哥哥勖聪恕（曹恩齐 饰），哪知道喜宝身上散发出来的魅力竟深深吸引了勖存姿。抵挡不住勖存姿的金钱攻势，喜宝沦陷成为了他的情妇。虽然经济上得到了极大的满足，但喜宝很快就再度被灵魂的空虚所吞噬。©豆瓣', '郭采洁', '王丹阳', 3.3, 58383, 'tt13180792', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2621473195.jpg', 58.5, 26, 11.4, 2.7, 1.4, '0.300870,0.243403,-0.617656,0.671006,-0.308336,-0.281264,0.380158,0.320696,-0.572420,-0.110657,0.038102,0.592300,-0.219880,0.299492,0.078047,0.105910,-0.028330,-0.689626,-0.119028,-0.216493,-0.192514,-0.411128,-0.512643,0.250071,-0.230934,-0.319680,0.342220,0.147873,0.069815,0.499957,0.266959,0.252439,0.015083,0.660181,-0.265391,0.015657,-0.147007,0.111846,-0.144539,-0.044984,0.076167,-0.459243,0.029510,0.212993,-0.027576,0.245149,0.578594,-0.408757,0.075436,-0.037105,0.416527,-0.148034,0.155554,0.044040,0.053595,0.332659,0.347153,0.038869,-0.382384,-0.053369,0.031956,-0.000486,-0.813513,-0.155991,0.287489,-0.078604,-0.527420,0.473527,-0.029649,-0.292406,-0.128765,-0.290988,0.053350,0.059272,-0.100295,0.516400,-0.344503,0.155428,-0.448859,0.057319,0.683564,0.098806,-0.276488,0.300525,-0.184611,-0.452132,0.231250,-0.239378,-0.168483,-0.065809,0.450809,0.340631,0.013256,0.237607,-0.462492,0.285821,-0.210665,0.226624,0.214819,-0.373429,-0.235018,-0.194716,-0.504088,-0.604730,-0.397790,0.061508,0.090478,-0.379079,0.909116,-0.911040,0.158778,0.223711,0.359534,-0.527439,0.678615,-0.140967,-0.169087,-0.066228,-0.120794,0.211976,-0.054348,-0.273308,0.141259,0.456550,-0.205427,-0.040579,-0.361942,0.789204', '26283288', '35144311', '21360412', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27615233', '你好，之华', '剧情', '生死离别，红颜薄命。告别了命途乖离的姐姐，袁之华（周迅 饰）带着些许落寞的心情和丈夫以及姐姐的儿子晨晨踏上归途。临走的时候，她从外甥女睦睦（邓恩熙 饰）手中接过一封邀请函，这是姐姐袁之南初中同学会的邀请。在久别重逢的老友欢聚环境中，被众人当作之南的之华无法坦然道出姐姐去世的事实。她选择先行离去，途中却又与姐妹俩的旧相识尹川（秦昊 饰）重逢。在此之后，之华以姐姐的名义给尹川写信，重温青葱时代的记忆。与此同时，待在老家的睦睦和之华的女儿飒然（张子枫 饰）接到了尹川的来信，出于对母亲过往的好奇，她们以稚嫩的笔触写了回信。喧嚣匆忙的电子时代，两代人分出三地，重绘他们逝去的岁月人生……©豆瓣', '周迅', '岩井俊二', 6.7, 254761, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2538345957.jpg', 2.3, 11.4, 46.1, 31.6, 8.7, '0.278368,0.164098,-0.463197,0.770079,0.069131,-0.408422,0.527160,0.260615,-0.571566,-0.230989,0.039729,0.762412,-0.011727,0.554479,0.318657,-0.213340,-0.161453,-0.632496,-0.030397,-0.226998,-0.070486,-0.392466,-0.009963,0.245199,0.030355,-0.316118,0.372247,-0.022275,0.085979,0.974074,0.116443,0.151499,-0.630304,0.435722,-0.353471,0.255180,-0.320975,0.380192,-0.677236,-0.156058,0.164801,-0.228186,-0.169610,0.072327,-0.031940,0.396744,0.771016,-0.212301,-0.023623,0.110955,0.384283,0.013860,0.052979,0.256397,0.102905,0.292536,0.027400,0.317923,-0.275491,-0.106517,-0.055946,-0.053986,-0.300252,0.192001,0.170353,0.143177,-0.558098,0.620610,-0.270566,-0.059980,0.036462,-0.499587,0.263464,0.292466,0.052520,0.572731,-0.079491,-0.111078,-0.111631,0.340155,0.347160,-0.078406,0.034759,0.481136,-0.202597,-0.223606,0.189580,-0.057348,-0.631335,0.150862,0.338551,0.056240,-0.025467,0.242358,-0.542376,-0.249255,-0.113049,-0.062416,0.382788,-0.455957,-0.064739,-0.307228,-0.122914,-0.533788,-0.507388,0.088898,0.105300,0.016498,0.671466,-0.695190,0.183048,0.201450,0.337814,-0.387551,0.555006,0.219869,0.005265,-0.269196,0.124401,0.222441,-0.135949,0.181246,0.158284,0.041826,-0.118776,0.116255,-0.665797,0.280233', '1301562', '25723081', '3155839', '2278795');
