INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27615564', '的士速递5', '喜剧', '巴黎警官西尔万(弗兰克·盖思堂彼得 饰)因执行任务的方式过于激进,被调任马赛 社区警局。赴任第一天,便遇到意大利超跑帮抢劫珠宝,劫匪驾驶着法拉利风驰电 掣,让西尔万和“各怀绝技”的警员们“望尘莫及”、出尽洋相。正当西尔万一筹 莫展之际,他结识了憨厚莽撞的出租车司机埃迪(马利克·班泽拉 饰)。两人毫无默 契,却要合力抓捕疑犯,一场状况频出、笑料横行的猫鼠游戏即刻展开......', '弗兰克·盖思堂彼得', '弗兰克·盖思堂彼得', 5.3, 25618, 'tt7238392', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2529136453.jpg', 7.9, 33.3, 45.6, 10.1, 3.2, '0.311872,0.045243,-0.258000,0.351501,-0.096361,-0.133850,0.259762,0.082416,-0.457136,-0.168592,0.236621,0.756338,-0.381877,-0.132612,0.510761,-0.332151,-0.167520,-0.413528,0.085198,0.239748,0.158847,-0.292894,0.060881,-0.109701,-0.038232,0.090437,-0.028976,0.052072,0.069373,0.621301,0.212053,0.332856,-0.471421,0.232951,0.218798,-0.015131,0.195207,-0.086013,0.014280,0.023493,-0.365558,-0.091878,-0.230325,0.132561,0.226247,0.443206,0.738829,-0.016302,-0.205043,-0.268933,-0.114667,-0.227577,0.042249,-0.148838,0.235744,0.053864,0.001978,-0.066965,-0.057087,0.127511,0.047410,0.139109,-0.575721,0.262832,-0.138804,-0.383419,-0.483199,-0.058959,-0.488942,0.305561,0.133215,-0.201920,-0.132539,0.317459,0.328277,-0.047818,0.299328,-0.207102,-0.624070,0.282320,0.334348,-0.010829,-0.107005,-0.009732,-0.000640,-0.374418,0.222777,-0.246335,-0.220358,-0.298593,0.678505,-0.386877,-0.313089,0.014949,-0.381385,-0.190336,-0.442158,-0.141112,-0.254226,-0.059815,0.141153,-0.858688,0.294651,-0.239652,-0.087319,0.133628,0.117862,0.361894,0.170895,-0.660273,0.104945,0.589337,0.173618,-0.237416,0.283517,-0.083726,0.165657,-0.108908,-0.090736,-0.059354,0.235088,0.516553,0.039145,0.313166,-0.089131,-0.397632,-0.011162,0.378240', '25833539', '1309194', '3178770', '2357711');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27617348', '门锁', '悬疑', '熙攘喧嚣的大都会里，供职于某银行的独身女子赵京敏过着朝九晚五的生活，独自穿梭在城市的街头巷尾。这一晚，京敏下班回到家，发现家门的密码锁盖子被人打开。进屋后不久，她突然听到门口传来按密码锁的声音，更有人试图扭开门把手。虽然没有看到任何人，但恐慌的京敏还是选择报警，然而警方却以未发生侵入和伤害行为而拒绝进一步调查。夜渐渐深了，在极不正常的深度睡眠中，似乎有什么人坦然自若地走入京敏的房间，紧紧抱着这个女孩入睡。接下来的日子，京敏的精神状态越来越差，无理的客户更是让她倍感恐慌。 她开始变得不知所措，身边每个男人似乎都变得无比可疑，而可怕的事情终于发生……©豆瓣', '孔晓振', '李权', 6.9, 50441, 'tt9402676', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2537955628.jpg', 1.3, 6.6, 46.1, 36.2, 9.8, '0.615866,0.286710,-0.913259,0.428820,0.012302,-0.052064,1.231511,0.257531,-0.778037,-0.477922,-0.029789,0.494413,-0.338929,0.340232,0.165460,-0.094029,-0.363413,-0.817366,-0.176414,-0.060915,-0.433709,-0.186749,0.005764,-0.323005,-0.163137,-0.104023,0.524443,0.262901,-0.259978,0.322578,-0.061197,0.100617,-0.134723,1.009281,-0.235543,-0.175252,-0.057576,0.174029,-0.020234,-0.056282,0.225997,-0.434953,-0.416428,0.145631,-0.073604,0.337209,0.362072,-0.306161,-0.608121,0.281020,0.400144,-0.223944,-0.351702,0.066789,0.289029,0.276282,0.230004,0.089268,-0.366028,0.119316,-0.066319,0.034798,-0.240353,0.426700,0.004181,0.491029,-0.417112,0.060557,-0.288303,0.037682,0.108013,-0.351288,0.264118,0.336991,0.036420,0.497610,-0.350137,0.017329,-0.650325,-0.380849,0.515241,0.012773,-0.449406,0.404677,-0.162159,-0.530318,0.063584,0.028476,-0.360901,-0.145889,0.086818,0.326322,-0.415793,0.211581,-0.350853,0.222265,-0.038823,-0.482737,-0.272978,-0.350805,-0.366319,-0.702160,-0.175592,-0.332199,-0.318320,0.265869,-0.182574,-0.162020,0.356091,-0.922208,0.177963,0.220508,0.557420,-0.222978,0.484871,-0.230773,0.009490,0.056331,-0.241936,0.333232,-0.062023,0.463122,0.192492,0.364288,-0.333300,-0.071240,-0.439076,0.465759', '35073565', '21348112', '1304665', '3059036');
