INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27621498', '狩猎的时间', '悬疑', '《守望者》导演新作，讲述在不久的将来韩半岛再次受到经济冲击，进而出现巨大的贫民街。为了生活下去，在这条街上的年轻人不惜以身试法的故事。', '李帝勋', '尹成贤', 6.3, 9348, 'tt11777040', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2584034774.jpg', 3.1, 16.8, 50.3, 22.2, 7.6, '-0.169280,0.045366,-0.517117,0.845302,0.376927,-0.205365,0.454669,0.425803,-0.617691,-0.039186,0.437351,0.810933,-0.297377,0.029315,0.616461,-0.522375,-0.183721,-0.324846,0.174934,0.029197,-0.271485,-0.011541,0.033479,-0.403791,-0.493352,-0.543136,0.692968,0.412059,-0.639975,-0.010106,0.285861,0.261335,-0.384464,0.339008,-0.347689,0.325214,-0.217530,-0.034369,-0.734874,0.220201,0.067008,-0.582455,0.221366,-0.034062,-0.078202,-0.226406,0.903137,-0.305051,-0.257922,-0.015890,0.713757,-0.223019,0.163644,-0.328973,0.575639,0.112937,0.380798,0.269929,-0.271417,-0.012259,0.098355,-0.854217,-0.258669,-0.379287,-0.050666,0.329958,-0.527441,0.111250,0.486524,0.058217,0.276757,-0.049535,0.103834,0.590338,0.564249,0.145412,-0.069102,0.339526,-0.444616,0.138453,0.889085,0.199797,-0.288890,0.074681,-0.206944,0.010331,-0.370491,-0.295393,-0.776982,0.053017,0.615584,-0.177430,-0.526134,0.368530,-0.519866,-0.059786,-0.061444,-0.528121,0.534765,0.036289,-0.346116,-0.780549,0.119493,-0.209877,0.443568,0.354837,-0.080395,-0.351750,0.477525,-0.806687,0.291914,0.479609,0.601471,-0.600190,0.342078,-0.149393,0.208840,0.047194,-0.237321,0.484658,-0.004415,0.731880,-0.178661,-0.236166,-0.328669,-0.077999,-0.320096,0.624405', '35051438', '2159244', '10567506', '1291992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27621727', '遗传厄运', '恐怖', '安妮（托妮·科莱特 Toni Collette 饰）和丈夫史蒂文（加布里埃尔·伯恩 Gabriel Byrne 饰）带着大儿子皮特（亚历克斯·沃尔夫 Alex Wolff 饰）生活，他们的小女儿查理（米莉·夏普洛 Milly Shapiro 饰）则交由安妮的母亲艾伦抚养 。实际上，安妮和母亲之间的关系十分疏远，艾伦去世后，查理重新回到了父母的身边。自从查理回家之后，家里便开始接二连三的发生诡异的事件。神秘的图腾，陌生的姓名以及神出鬼没的不速之客让这个家庭被笼罩在压抑的气氛之中。由于皮特的疏忽，一场车祸夺走了查理的性命，查理的死加快了各家庭成员之间的分裂，在安妮最绝望的日子里，一个名叫乔安（安·唐德 Ann Dowd 饰）的女人出现在了她的身边，她声称自己拥有能够召唤灵魂的特异功能。©豆瓣', '亚历克斯·沃尔夫', '阿里·艾斯特', 7.2, 137865, 'tt7784604', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2518865763.jpg', 2.1, 6.5, 34.8, 40.5, 16.1, '0.401483,0.008126,-0.665271,0.544640,-0.312678,-0.474163,0.996924,0.292929,-0.645158,-0.407036,0.285536,0.959660,-0.206508,0.447383,0.438211,0.131046,-0.491588,-0.709998,-0.062201,-0.114649,-0.300737,-0.514209,-0.151957,-0.177879,-0.122558,-0.321843,0.378718,-0.333419,-0.003594,0.702865,0.147526,0.506640,-0.209342,0.387884,0.066888,0.282452,0.151315,-0.254599,-0.275661,0.068121,0.237484,-0.053517,0.156509,0.426791,0.051695,0.259560,0.821183,-0.368676,0.057502,-0.329602,0.401432,-0.022441,0.017447,0.009778,0.324076,0.226091,0.272918,0.148790,-0.411577,0.022732,0.188783,0.094617,-0.760855,0.238784,0.143224,0.365042,-0.592971,0.450141,-0.047186,-0.042433,0.341246,-0.386134,0.329444,0.533224,0.081505,0.541804,-0.346302,0.093980,-0.378307,-0.170277,0.521390,-0.334645,-0.275141,0.298447,-0.316682,-0.221402,-0.029910,0.065706,-0.638504,-0.089191,0.416634,0.194356,0.022181,0.532797,-0.633824,-0.312207,-0.294456,-0.076083,-0.097332,-0.302655,-0.136698,-0.569577,-0.239160,-0.583093,-0.458837,-0.147456,-0.150487,0.047591,0.470387,-0.794226,0.517707,0.347980,0.300922,-0.212734,0.373912,0.136487,0.553536,-0.223176,-0.050391,0.413862,0.097159,0.136251,0.162972,0.237943,-0.018329,0.019552,-0.352677,0.705278', '3111650', '1296534', '1309172', '3014557');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27621991', '白牙', '动画', '故事的主角是一只名叫白牙（尼克·奥弗曼 Nick Offerman 配音）的狼，它自幼生长在弱肉强食的世界之中，早已经习惯了其中的尔虞我诈。长大之后，母亲将白牙带回了主人身边——一位善良强壮的印第安人，就这样，白牙有了一份拉雪橇的工作，日子在平静中一天一天的过去了。然而，拮据的经济让主人不得不将白牙卖给了一个名为史密斯的男人，史密斯满肚子坏水，丝毫没有仁爱之心，只想着怎样榨取利益，在史密斯的调教之下，白牙成为了一匹斗狼，用自己的鲜血为史密斯换取金钱。幸运的是，白牙很快就遇见了自己的新主人斯科特，斯科特用爱和关怀渐渐治愈了白牙受伤的心灵。©豆瓣', '拉斐尔·佩尔索纳', '亚历山大·埃斯皮加雷斯', 7.6, 8572, 'tt5222768', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2557286943.jpg', 0, 2.3, 33.2, 46.5, 18, '0.059169,0.472890,-0.417977,0.417004,-0.396534,-0.543168,0.663892,0.213822,-0.104962,0.047140,0.051060,0.541016,0.102798,0.299865,0.058624,0.079323,-0.008858,-0.565880,-0.215181,-0.211648,-0.383727,-0.406725,-0.419857,-0.314723,0.045333,-0.341499,0.630312,0.194954,0.109012,0.286960,0.169877,0.151700,0.286967,0.467414,-0.559078,-0.057422,0.204304,-0.127880,0.174376,0.214575,0.054404,-0.217660,0.052978,0.324159,-0.128452,0.349178,0.551611,-0.337811,-0.222753,-0.388084,0.209329,-0.165613,0.106699,0.104873,0.263618,-0.248182,0.274994,0.070096,-0.246401,0.252125,-0.016830,-0.246758,-1.003720,-0.495213,-0.205775,0.193151,-0.916260,0.617352,-0.076114,-0.302137,0.199365,-0.407224,0.350546,0.254690,0.196788,0.325625,-0.121329,0.450182,-0.480571,-0.002225,0.526017,-0.228019,-0.044430,0.430237,-0.346221,-0.337996,0.050086,-0.097784,-0.408896,-0.160856,0.280254,0.220350,-0.315655,0.289328,-0.853105,0.079326,-0.260066,0.144917,0.232347,-0.533556,-0.322123,-0.298219,-0.231608,-0.542720,-0.042949,-0.167429,0.100204,-0.224309,1.028320,-0.668885,0.142144,0.322194,-0.087364,-0.050596,0.591813,-0.016081,0.256862,-0.170010,0.381376,-0.018603,0.250678,0.180483,0.357714,0.572701,0.085150,0.025136,-0.056099,0.858305', '1302661', '27602116', '24284209', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27622447', '小偷家族', '剧情', '东京的都市丛林中央，残存着一栋古旧寒酸的老房子，这里局促地生活着柴田一家五口人。在工地当临时工的男人阿治（Lily Franky 饰）经常带着儿子祥太（城桧吏 饰）到超市盗窃生活用品，这一天，他们回家路上遇到了独自待在户外的四岁女孩由里（佐佐木美结 饰）。妻子信代（安藤樱 饰）起初极力主张将女孩送回父母身边，但当看到女孩原生家庭的状况时又心生恻隐。原本柴田家就靠着老奶奶初枝（树木希林 饰）的养老金度日，而今多了一口人，自然更艰辛了几分。包括信代的妹妹亚纪（松冈茉优 饰）在内，虽然一家人游走在贫困和违法的边缘，但笃深的羁绊将他们紧紧联系在一起，使他们的心不会随着冰冷的都市而寒冷下去……本片荣获第71届戛纳电影节金棕榈©豆瓣', '中川雅也', '是枝裕和', 8.7, 769176, 'tt8075192', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2530599636.jpg', 0.2, 0.7, 9.4, 44.7, 45, '0.185293,-0.081331,-0.831267,0.450051,-0.066844,-0.255363,0.703949,0.476760,-0.562407,-0.103911,0.289688,0.762927,-0.033751,0.429948,0.223778,0.005211,-0.394333,-0.421120,-0.219423,-0.222557,-0.324431,-0.231541,-0.071481,-0.093393,-0.282870,-0.167258,0.523375,0.252639,0.169077,0.422797,0.190761,0.093026,-0.317200,0.293930,-0.327032,-0.027824,-0.001126,0.119249,-0.252966,0.069239,-0.095476,-0.292272,-0.313343,-0.104176,0.209886,0.162155,0.901642,-0.007571,-0.123082,-0.067015,0.118214,0.134230,-0.133416,0.080189,0.306938,-0.088624,0.373807,0.208893,-0.349778,0.134645,0.338119,0.008119,-0.216129,0.181812,0.212728,0.160879,-0.644733,0.531840,0.054921,-0.120214,0.050009,-0.388524,0.283125,0.135173,0.053279,0.325675,-0.244897,-0.039265,-0.515161,0.101202,0.460904,-0.024913,-0.036896,0.209489,-0.452397,-0.301591,-0.139046,-0.174610,-0.617104,-0.195315,0.222356,0.035773,-0.278912,0.169955,-0.593017,0.032578,0.160471,-0.133882,0.063759,-0.260181,-0.018434,-0.483268,0.217058,-0.409997,-0.180122,0.294438,0.177711,-0.139051,0.602884,-0.510964,0.255383,0.451368,0.520198,-0.131158,0.522012,-0.114969,0.222838,-0.067795,-0.291415,0.195239,-0.079546,0.341003,0.369176,0.444638,-0.460625,-0.080851,-0.326210,0.492607', '21619567', '25723780', '25790555', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27624661', '比悲伤更悲伤的故事', '爱情', '唱片制作人张哲凯(刘以豪)和王牌作词人宋媛媛(陈意涵)相依为命，两人自幼身世坎坷只有彼此为伴，他们是亲人、是朋友，也彷佛是命中注定的另一半。父亲罹患遗传重症而被母亲抛弃的哲凯，深怕自己随时会发病不久人世，始终没有跨出友谊的界线对媛媛展露爱意。眼见哲凯的病情加重，他暗自决定用剩余的生命完成他们之间的终曲，再为媛媛找个可以托付一生的好男人。这时，事业有 成温柔体贴的医生(张书豪)适时的出现让他成为照顾媛媛的最佳人选，二人按部就班发展着关系。一切看似都在哲凯的计划下进行。然而，故事远比这里所写更要悲伤......', '陈意涵', '林孝谦', 4.8, 164995, 'tt9081562', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2549523952.jpg', 23.8, 30.9, 30.6, 9.9, 4.8, '0.027760,-0.088141,-0.626413,0.518223,-0.111082,-0.277803,0.569191,0.108344,-0.403830,-0.120142,0.112436,0.754009,-0.031643,0.424530,0.005563,-0.067787,-0.204539,-0.934803,-0.079479,-0.048383,-0.276885,-0.694871,0.046214,-0.109885,-0.216868,-0.418546,0.769143,0.030157,-0.128746,0.137228,0.139897,0.142115,-0.209548,0.379525,-0.216403,0.129225,-0.263912,0.015340,-0.747978,0.052634,0.377353,-0.196249,-0.051874,0.190141,-0.218560,0.264913,0.607061,-0.038951,-0.188387,-0.020432,0.410932,-0.365672,0.021466,-0.191993,0.196971,-0.008179,0.224610,0.505555,-0.314760,-0.133251,0.058101,-0.160441,-0.790709,-0.091245,0.306195,0.263482,-0.758103,0.244554,0.119737,0.028260,0.186806,-0.247747,0.405219,0.375106,0.228526,0.324840,-0.326233,0.115956,-0.413643,0.076583,0.925542,0.065964,-0.302028,0.491779,-0.331173,-0.208899,0.032775,-0.305483,-0.602740,0.133984,0.034877,0.288437,-0.097617,0.071916,-0.186135,-0.018392,-0.147449,0.177629,0.183148,-0.581775,0.163459,-0.312656,-0.178218,-0.530647,-0.554895,0.185336,-0.064687,-0.620871,0.861570,-0.709406,0.077166,0.048214,0.438224,-0.588415,0.711304,0.161770,0.204048,-0.198752,0.139916,0.282211,-0.258156,-0.173188,0.204234,-0.069248,0.071006,0.377351,-0.376815,0.469101', '35048413', '5985887', '1296569', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27624665', '通往春天的列车', '剧情', '讲述小镇青年寻找自我、为生活奔波的故事。将要被火车配件厂买断工龄的李大川，因意外事件被工厂保安当成小偷当场抓获，导致他失去了领取四万元补偿金的资格。李大川为了找回清白，过上了一边寻找小偷、一边为生活奔波的日子。', '李岷城', '李骥', 6, 11006, 'tt9097170', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2620365836.jpg', 2.8, 19.5, 55.3, 18.3, 4.1, '-0.071071,-0.112817,-0.039525,0.131768,-0.230341,-0.691605,0.591224,0.029998,-0.458795,-0.494441,0.290261,0.090979,0.109964,0.395267,0.597728,-0.319745,-0.096600,-0.596382,-0.120783,0.197319,-0.360171,-0.170461,0.216844,-0.421602,-0.654126,-0.118615,0.672843,0.049080,-0.314534,0.127882,-0.133787,0.532250,0.035418,-0.011709,-0.458367,0.299287,0.119419,0.075821,-0.525787,0.080600,0.089550,-0.348740,0.091721,-0.199111,0.141666,0.276320,1.038057,0.275158,0.040224,-0.547199,0.201806,-0.215144,0.096504,-0.278687,0.163260,0.201769,0.142827,0.206405,-0.236165,-0.220930,0.444195,-0.208031,-0.742313,-0.322600,0.164009,-0.038189,-0.343652,0.004474,-0.143893,0.134083,0.318494,-0.284006,0.209008,0.260106,0.563475,0.507336,-0.000721,0.070973,-0.696529,0.863350,0.665350,-0.366120,0.165264,0.288752,-0.373739,-0.073152,0.322513,-0.197342,-0.362617,-0.273862,0.130301,-0.014194,-0.173112,0.279381,-0.355948,-0.073011,-0.289872,-0.646930,0.251443,-0.369982,-0.546081,-0.407498,0.162605,0.041388,0.175226,0.127256,-0.112292,-0.112603,0.123341,-0.441755,0.177437,0.595169,0.227038,-0.900107,0.314158,-0.132160,0.468467,-0.458277,0.213229,0.164231,0.212007,0.865600,0.270182,-0.530038,-0.570606,0.001566,-0.355480,0.489030', '30180781', '20515071', '26754643', '10581450');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27662541', '福尔摩斯小姐：失踪的侯爵', '剧情', '故事发生在1884年的英国，伊诺拉（米莉·博比·布朗 Millie Bobby Brown 饰）正准备迎接自己的16岁生日，哪知道在这一天，她的母亲（海伦娜·伯翰·卡特 Helena Bonham Carter 饰）失踪了。大名鼎鼎的名侦探夏洛特福尔摩斯（亨利·卡维尔 Henry Cavill 饰）和麦考夫（山姆·克拉弗林 Sam Claflin 饰）成为了伊诺拉的监护人。面对古灵精怪不受控制的妹妹，两个男人一门心思的想要将她送到专门培养“淑女”的寄宿学校中就读，伊诺拉哪会这样乖乖受人摆布？一言不合之下，她选择了离家出走，只身一人前往伦敦寻找母亲的下落。在旅途中，伊诺拉被卷入了一个非常神秘的案件之中，她化身成为侦探，和自己的哥哥展开了斗智斗勇的较量。©豆瓣', '米莉·波比·布朗', '哈利·布拉德比尔', 5.9, 23139, 'tt7846844', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2617666143.jpg', 2.6, 20.5, 57.2, 17.4, 2.4, '0.263630,-0.011312,-0.656640,0.372756,-0.290312,-0.182216,0.464379,0.075370,-0.159331,-0.415375,0.066648,0.840011,-0.261795,0.578337,0.537303,0.088853,-0.306354,-0.823204,-0.100758,0.023094,-0.206634,-0.577740,-0.165515,-0.201765,0.130806,-0.142527,0.417269,-0.191226,-0.109873,0.317615,0.427858,0.699809,-0.188134,0.518236,-0.196062,0.177475,0.354978,-0.123214,0.049906,0.428670,0.101234,-0.100251,0.323313,0.308056,0.220381,0.345410,0.687012,-0.596394,0.345473,-0.206283,0.258527,-0.212711,0.020045,0.127340,0.196155,-0.219257,-0.130920,0.091444,-0.251966,-0.106847,0.038342,-0.327442,-0.447361,-0.270723,0.275530,0.331788,-0.734139,0.090819,-0.192743,-0.055350,0.049222,-0.221939,-0.009397,0.471633,0.196228,0.196712,0.025297,0.001104,-0.608780,-0.117525,0.388290,-0.151108,0.061244,0.307313,-0.093943,-0.298897,0.008192,-0.253885,-0.665075,-0.213405,0.108827,-0.265080,0.063093,0.248599,-0.431715,-0.359903,-0.374918,-0.108199,0.038440,-0.458461,-0.119309,-0.357761,0.227762,-0.447263,-0.327516,-0.168613,-0.101071,-0.316609,0.588898,-0.887577,0.314928,0.608826,0.400531,-0.225393,0.563081,0.087534,0.368671,-0.370033,0.087564,0.371523,0.244451,0.129338,0.223947,0.385400,0.127979,-0.038798,-0.452942,0.580975', '30345227', '1783461', '1292207', '26809592');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27662747', '许愿神龙', '喜剧', '你知道这世上仅存一条粉红色的许愿神龙吗？他能够实现许愿者任何逆天改命的愿望。这样的神力引得不少人在暗中寻找神龙的踪迹，然而普普通通的上海小青年丁思齐误打误撞打开了神龙的封印。千年代沟引发连串爆笑经历，被绑定的一人一龙踏上了一段妙想天开又惊险万分的旅途…', '成龙', '克里斯·艾伯翰斯', 6.5, 35780, 'tt5562070', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2626260539.jpg', 1.6, 10.6, 54.7, 27.7, 5.4, '0.247258,0.087326,-0.624787,0.585118,-0.059993,-0.078268,0.660935,-0.433721,-0.564495,0.173421,0.184348,0.563807,-0.388326,-0.039614,0.213807,-0.258531,0.075106,-0.328557,0.502574,-0.243541,-0.086668,-0.011972,-0.473867,-0.059689,-0.083646,-0.605218,0.862027,0.452424,0.053782,0.090975,0.222940,0.016969,-0.314883,0.057624,-0.630646,0.293001,-0.231766,0.320782,0.167910,0.278920,-0.239899,-0.272978,0.198181,0.622414,-0.754540,0.114289,0.398306,-0.601176,-0.046332,0.044684,0.684619,-0.372236,-0.046844,-0.177117,0.083485,0.096245,0.118857,0.274690,-0.052636,-0.313670,0.211225,0.038124,-0.864666,-0.181177,-0.005185,0.172184,-0.231457,0.259894,0.282101,-0.013052,-0.067371,-0.275447,-0.030433,0.463786,0.478936,0.160810,-0.396264,-0.182311,-0.654195,0.165333,0.658437,-0.571879,-0.298670,0.579454,-0.100916,-0.451013,-0.250875,-0.207702,-0.261844,-0.056727,0.476706,0.435559,-0.243646,-0.017497,-0.756060,0.307207,-0.369151,0.016740,-0.314293,-0.286666,-0.196145,-0.260037,0.046092,0.086768,-0.219876,0.268237,0.221269,-0.585870,0.580733,-0.642561,0.114856,0.529450,0.274288,-0.198168,0.760456,-0.103376,0.089662,-0.275342,0.014260,0.351117,0.115128,0.406116,0.045054,0.316761,0.077220,0.340489,-0.541366,0.350314', '27098364', '2364054', '26759819', '6844861');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27663742', '老师·好', '剧情', '故事发生在20世纪80年代的偏远山城。南宿一中的优秀教师苗宛秋（于谦 饰）踌躇满志，迎来了新一届的高中学生。开学第一天，霸气十足的苗老师便给这群性格张扬、问题多多的学生们一个下马威，无论是桀骜不驯的混混洛小乙，还是一脑袋鬼点子的王海，无论是投机倒把的耗子，还是虚荣张扬的关婷婷，都被他收拾得服服帖帖。只不过这帮孩子表面顺服，背地里却与苗霸天展开了旷日持久的战争。在战争的过程中，专横的苗霸天不时展现温情的一面，他的古道侠肠更是令孩子们暗自佩服。转眼三年时光过去，懵懂无知的孩子们渐渐长大，他们似乎开始认识到苗老师最真实的一面了……©豆瓣', '于谦', '张栾', 6.6, 267262, 'tt10066162', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2551352209.jpg', 2.1, 12, 47, 29.4, 9.5, '0.370745,0.029764,-0.507080,0.489134,-0.468482,-0.204038,0.553481,-0.142124,-0.551378,-0.175144,0.214647,0.263210,-0.370661,0.461308,0.193711,-0.283859,-0.206664,-0.559667,-0.172689,-0.132915,-0.062038,-0.094400,-0.064891,-0.072923,-0.048700,-0.132619,0.445110,0.011253,-0.029151,0.454460,0.241581,-0.010799,0.128034,0.399692,-0.451476,0.084671,-0.083324,0.067570,0.029135,-0.320434,0.054864,-0.212808,-0.542634,0.088689,0.138069,0.312092,0.825068,-0.199080,-0.211465,-0.024453,0.553904,-0.168393,-0.282868,0.283840,0.463093,0.035245,0.123541,0.118843,0.284296,-0.008836,-0.075903,-0.094077,-0.445276,0.029543,0.052983,-0.126806,-0.574936,0.551580,0.371556,0.151995,0.082553,-0.327724,-0.070187,0.185419,0.076616,0.583608,-0.156071,0.102954,-0.398564,0.256425,0.481084,0.165197,-0.495860,0.265115,-0.353371,-0.381065,0.033873,-0.358128,-0.499580,-0.136550,0.373976,-0.346765,-0.298266,0.464008,-0.644097,0.047684,0.132076,-0.210591,0.118077,-0.491485,-0.379631,-0.270383,-0.305749,-0.611196,-0.315585,0.141953,-0.007289,0.024144,1.181926,-0.796907,0.014292,0.381334,-0.033849,-0.479728,0.396028,0.455316,0.019389,-0.034307,-0.325063,0.105448,-0.036375,0.392299,0.005151,0.741807,-0.372217,-0.396915,-0.279678,0.547942', '25922902', '26348103', '24284209', '1303010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27666513', '莫扎特！', '歌舞', '音乐剧莫扎特是一部德奥音乐剧，由Michael Kunze作词，Sylvester Levay作曲，是一部描述Wolfgang Amadeus Mozart的德语音乐剧。全剧共有53首歌曲，分为两幕进行演出，其中包含了流行、摇滚和古典等各种风格的歌曲。 这部音乐剧概述了Wolfgang Amadeus Mozart的痛苦而又短暂的一生，突出了他对艺术的极致追求和对自由的无限渴求，也描绘出由此在他生活中与父亲和Colloredoqin亲王产生的冲突。这部音乐剧最特别的设定是，在舞台上让Mozart和一个孩子Amadè同时出现, 他就是小时候的Mozart, 永无停止地在写新的交响乐，最后也是他终结了Mozart的生命。', 'Oedo Kuipers', 'Harry Kupfer', 9.5, 7217, '', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2510734167.jpg', 0.3, 0.3, 2.5, 18.1, 78.9, '0.207577,-0.144013,-0.720071,1.217796,-0.011761,0.017507,1.116177,-0.077978,-0.397613,0.063020,0.274645,1.128829,-0.359186,0.166671,0.244489,-0.163169,-0.305817,-0.912320,-0.195913,0.073602,-0.118742,-0.505039,-0.086595,0.074620,-0.143873,-0.479460,0.911884,0.182091,-0.585629,0.407470,0.375979,0.125056,0.048590,0.276574,-0.250742,0.141289,-0.225681,-0.018635,-0.023094,0.210150,0.370471,-0.520469,-0.172846,0.235239,-0.404345,0.160306,0.981993,-0.309295,0.152739,0.292530,0.704554,-0.377414,-0.294480,-0.067505,-0.082595,0.156291,0.362803,0.322884,-0.390123,0.059746,-0.339849,-0.230992,-1.386675,-0.168573,0.194111,0.164582,-0.463663,0.816776,-0.057372,-0.457950,0.294043,-0.194262,0.365508,0.098778,0.573768,0.759206,-0.130863,-0.212920,-0.311825,0.476913,0.650081,0.039809,-0.452844,0.679651,-0.488207,-0.682120,-0.380655,-0.376566,-0.490240,0.022938,0.202734,0.106441,0.070085,-0.070448,-0.844699,0.270178,0.194749,-0.589582,0.204832,-0.864155,0.113672,-0.886103,-0.372685,-0.766403,0.017729,-0.280846,0.363187,-0.567389,1.142010,-0.936655,0.108506,0.280460,0.018355,-0.283515,0.998206,0.273504,-0.060594,0.027340,0.160596,0.045658,-0.332495,0.063247,-0.023559,0.674383,0.382887,0.102230,-0.740212,1.032264', '1303542', '27602116', '4267948', '35360296');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27667334', '暹罗决：九神战甲', '动作', '拉玛贴王国遭遇夜叉族入侵，一夜之间覆灭。传说，将会出现一位拥有神器九神战甲的泰拳少年，挽救苦难中的王国。为绝后患，夜叉王举全族之力毁灭神器，战甲守护者及幼子奥特被泰拳大师所救。多年后，夜叉族再次追寻到神器踪迹，已成长为泰拳战士的奥特在父辈的保护下携九神战甲出逃，并与女海盗小兰、神秘夜叉玛拉达以及猴王瓦达一起，与邪恶的夜叉族展开较量......', '卡诺查·曼雅德昂', '彭萨·康斯里', 6.6, 3104, 'tt7717440', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2524042454.jpg', 1.7, 10.2, 52.2, 28, 7.9, '-0.258264,0.297241,-0.248886,0.738178,0.213406,-0.051606,0.405548,-0.217803,-0.155110,-0.807446,0.794179,0.661371,0.200850,0.017775,0.299052,0.072448,0.225328,-0.546306,0.067682,0.266163,-0.317724,0.350178,-0.545253,0.060534,-0.131797,-1.196050,0.875357,0.047273,-0.261764,0.123083,0.010126,0.627567,-0.566106,-0.120246,-0.122274,-0.128899,-0.118414,-0.204826,-0.454229,0.507927,-0.565764,0.256290,0.217481,0.201979,-0.505758,-0.246357,0.448185,-0.766015,0.447801,-0.700779,0.178151,-0.214413,-0.108229,0.088340,0.793586,-0.143882,0.246625,0.287820,0.221554,-0.369917,0.110513,-0.025613,-0.967487,0.083793,0.165112,-0.046520,-0.506750,0.372246,-0.004418,0.281738,0.186820,-0.183761,0.130447,0.582058,0.294731,0.230049,0.165926,0.069169,-0.444905,0.079367,0.478135,-0.690488,-0.261692,-0.386786,0.424696,-0.747411,-0.365986,-0.692964,-0.029462,0.023586,0.256382,0.211114,0.484090,1.161095,-1.058648,-0.000111,-0.636903,0.168343,0.340382,-0.066184,-0.029644,-0.469292,-0.261290,0.137494,-0.161420,0.343724,0.519547,-0.090563,0.685395,-0.559351,0.503563,0.151760,0.461239,-0.331222,0.640705,-0.384995,0.269671,-0.227021,-0.223515,0.636026,0.530914,0.309490,0.087152,-0.077035,-0.028665,0.188651,-0.117612,0.404359', '1298586', '26589957', '30201138', '4154632');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('27668250', '南方车站的聚会', '剧情', '南方某城市，重案队长刘队（廖凡 饰）重金悬赏在逃罪犯周泽农（胡歌 饰）。陪泳女刘爱爱（桂纶镁 饰） 、周泽农曾经的好友华华（奇道 饰）、五年未见的妻子杨淑俊（万茜 饰），各色人等各怀心事，相继被卷入这场罪与罚的追击旋涡。冒险与爱情，人性与救赎，这场特别的“聚会”该如何收场？善恶有道一念之间。中国导演刁亦男曾凭借前作《白日焰火》获第 64届柏林国际电影节最佳影片金熊奖，凭本片入围第 72届戛纳国际电影节主竞赛单元。', '胡歌', '刁亦男', 7.4, 311713, 'tt9647768', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2553934187.jpg', 0.6, 4, 33.1, 49.8, 12.5, '-0.313819,-0.003206,-0.330714,0.467634,0.482581,-0.153311,0.101056,0.287172,-0.288542,-0.018748,0.271783,0.502056,-0.368731,-0.225086,0.523537,-0.328850,-0.204621,-0.514797,-0.161213,-0.281490,0.474630,-0.262810,-0.278126,0.439134,0.173174,-0.097707,0.727311,0.044312,0.037479,0.400336,0.939620,0.299699,-0.501609,-0.118765,0.315246,-0.082347,0.420657,0.520408,-0.725140,0.042300,-0.374154,-0.119718,-0.322012,-0.273106,-0.033974,0.122905,0.575186,-0.017346,0.105538,-0.287756,0.578858,-0.214066,-0.170127,-0.102113,0.432605,-0.171092,0.210987,0.332245,0.444789,0.364268,0.310336,-0.057052,-0.203421,0.093699,0.304253,0.089170,-0.090527,0.237805,-0.166618,0.101706,-0.163012,0.233256,0.005217,0.360511,0.304527,-0.146586,0.228497,-0.096042,-0.255902,0.765129,0.516233,0.026357,-0.252715,0.069215,0.044527,-0.628300,0.046253,-0.484764,-0.436775,0.337088,0.316186,-0.173298,0.050469,0.255536,-0.285237,-0.012497,0.148681,-0.013428,0.152187,-0.068567,0.397450,-0.875787,-0.089238,-0.076830,0.064309,-0.169664,0.142574,-0.024947,0.466957,-0.486241,0.120232,0.157901,0.260510,-0.254819,0.570072,0.543589,-0.072771,-0.281938,-0.053138,0.055828,-0.138486,0.248540,-0.314960,0.086504,0.010313,-0.385867,-0.095535,-0.163644', '3275168', '1292759', '24751811', '3077791');
