INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('28510273', '旺扎的雨靴', '剧情', '入围第68届柏林国际电影节新生代竞赛单元。该片由北京电影学毕业生拉华加担任编剧、导演，著名导演万玛才旦担任监制，著名摄影师吕松野担任摄影，青影厂陈中国和文学系孟中担任制片人。改编自才朗东主同名短篇小说，讲述了生活在藏地农区的小男孩旺扎一直想拥有一双漂亮的雨靴。然而，等他拥有了一双雨靴之后，却一直没有下雨。他盼望下一场大雨从而能够在雨天穿上这双雨靴……', '周拉多杰', '拉华加', 7, 5144, 'tt7961082', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2615497491.jpg', 0, 4.1, 47.3, 41.9, 6.7, '-0.270397,-0.013334,-0.803528,0.669839,0.238395,-0.243916,0.209633,0.310657,-0.173100,-0.449997,0.168852,0.738113,-0.378266,0.037630,0.130646,-0.177549,-0.586676,-0.681047,-0.242705,0.144560,-0.013251,-0.088578,-0.215820,0.244560,-0.265985,-0.004361,0.802623,0.228855,-0.235786,0.414417,0.574178,0.123831,0.319415,0.117706,-0.125181,-0.289884,0.366240,0.180447,-0.231973,0.690981,0.015866,-0.198069,-0.192876,-0.342458,0.442996,0.186106,0.485981,-0.000360,0.275963,0.049805,0.310865,-0.423336,-0.039103,-0.300567,0.474979,0.263897,0.280282,0.018180,0.002805,-0.072387,-0.159567,-0.426148,-0.373371,0.014202,0.460346,0.344405,-0.533988,0.204008,-0.246857,-0.105824,0.024797,-0.330159,0.096987,-0.099178,0.254234,0.315244,0.523284,0.487668,-0.245094,0.934444,0.371960,-0.189294,-0.329787,0.229094,-0.229509,-0.453028,-0.160710,-0.228547,-0.505603,0.207608,0.248010,-0.322251,0.160821,-0.342260,-0.182591,0.010324,0.226163,-0.419579,0.060276,-0.112560,0.020902,-0.604610,0.233170,-0.304011,0.036640,-0.244772,0.174751,-0.233886,0.613484,-0.708932,0.169322,0.164418,0.197958,-0.170610,0.963849,0.251907,0.221020,-0.069743,0.017967,0.019429,-0.345733,0.390728,-0.102163,0.641719,-0.072962,-0.186809,-0.234446,0.106760', '2338019', '1302279', '1297368', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2910660', '爱情无限谱', '剧情', '尼克（迈克尔·塞拉 Michael Cera 饰）是个高中生贝斯手，有着不凡的音乐才华，不过性格内向木讷，因此惨遭女友抛弃；诺拉（凯特·戴琳斯 Kat Dennings 饰）是个有头脑的个性女孩，从小受音乐人父亲影响深远，对音乐极其敏感。机缘巧合之下，诺拉拾到一张CD，被里面的音乐打动，后又在一场演唱会上遇到尼克，对他一见钟情。荒诞的一夜就此开启，尼克要求诺拉做他“五分钟女友”，恰逢诺拉好友卡罗拉喝醉走失，于是两个人拉上整个乐队成员踏上寻人之旅。期间，诺拉发现CD的原主人正是尼克，尼克也被诺拉带到父亲曾经的录音室，受到极大震撼，两个同样爱着音乐的年轻人，尝试和试探着走在一起……©豆瓣', '迈克尔·塞拉', '彼得·苏列特', 6.7, 10964, 'tt0981227', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1270623176.jpg', 1.4, 9.9, 50.4, 29.7, 8.6, '0.544728,0.063944,-0.516868,0.378562,-0.111766,-0.080979,0.731573,0.126915,-0.763621,-0.368719,0.367158,0.871280,-0.386222,0.348947,0.555743,0.082090,-0.350806,-0.544820,0.141719,0.014937,-0.129596,-0.700080,0.004338,0.275167,-0.141124,-0.472575,0.437374,-0.435294,-0.325657,0.679569,0.282004,0.260585,-0.006504,0.315397,0.061029,0.147864,0.259380,-0.125055,0.076496,0.314488,-0.028951,-0.210270,-0.095181,-0.079770,-0.169692,0.194908,0.543730,-0.260598,-0.052797,-0.008332,0.337165,-0.283173,-0.262712,-0.009492,0.236258,0.102655,0.328860,0.214964,-0.256125,-0.005964,0.015100,-0.108119,-0.341920,0.191745,0.179462,0.124765,-0.466944,0.223146,0.087502,-0.062498,0.187121,-0.254778,-0.020161,0.160253,0.364773,0.462435,0.024752,0.272965,-0.173148,-0.427072,0.750405,-0.064156,-0.134237,0.211238,-0.288053,-0.229642,0.064346,-0.243338,-0.847920,0.144785,0.137998,0.005066,-0.018940,0.018399,-0.588132,0.189858,-0.206508,-0.059514,-0.000755,-0.459606,-0.006566,-0.720492,-0.231848,-0.376748,-0.124696,-0.144034,-0.006014,-0.494462,0.637893,-0.784659,0.443958,0.338785,-0.039269,-0.200700,0.593713,0.080774,-0.062356,-0.117174,-0.009507,0.474388,0.151519,-0.073916,-0.173661,0.283843,0.070361,-0.161331,-0.340762,0.253083', '1292720', '25721544', '26971054', '2002744');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2968611', '口是心非', '爱情', '英国军情六处的前特工雷（克里夫•欧文 饰）转行做了商业间谍。在酒会上，他邂逅了曾在美国中情局工作的特工克莱尔（茱莉亚•罗伯茨 饰）。不过，克莱尔却装作不认识，这勾起了他的好奇。终于，雷依靠软磨硬泡，拉克莱尔去开房。没想到，却被对方下药迷倒，还偷走了他的重要文件。原来，此时的克莱尔已经做了竞争对手公司的间谍。这令如梦初醒的雷非常愤怒。在一次接头任务中，雷再次见到克莱尔的身影，于是不顾命令，拦住了她，结果他意外发现她恰恰就是接头人。虽然因为他的鲁莽，这场碰头不欢而散，但是这两人的纠缠却并未结束，因为他们先后卷入了两家竞争公司的明争暗斗之中，为了窃取商业情报，两人大打出手，互相斗法，并在其中擦出了爱情的火花……©豆瓣', '克里夫·欧文', '托尼·吉尔罗伊', 6.3, 8815, 'tt1135487', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p776823062.jpg', 1.8, 13.2, 56.5, 24.3, 4.3, '0.383122,0.154680,-0.951822,0.426524,-0.020957,-0.421078,0.793306,-0.054771,-0.416935,-0.253523,0.117417,0.585402,-0.387034,0.093807,0.361067,-0.027459,-0.445675,-0.800266,0.032299,-0.206255,-0.328308,-0.439527,-0.229499,-0.291654,0.036883,-0.016507,0.340670,0.116591,-0.407320,0.363552,0.550491,0.146827,-0.174948,0.835026,0.064879,0.139631,0.306402,0.129560,-0.089731,-0.125706,0.057256,-0.585317,-0.301589,0.241259,0.271513,0.829671,0.245276,-0.215977,-0.013342,-0.124376,0.117414,-0.447203,0.076804,-0.102060,0.320546,-0.051382,0.146173,0.011429,-0.096828,-0.075781,0.013811,0.116078,-0.792706,0.235163,0.013425,0.177285,-0.417563,0.637908,-0.117393,0.279325,-0.136537,-0.294562,0.227326,0.468368,0.204736,-0.008878,-0.144727,0.065826,-0.525978,0.054157,0.660553,0.071809,-0.101210,0.402062,-0.263310,-0.464691,-0.217406,-0.094103,0.005907,-0.103696,0.626947,0.164043,-0.149866,0.163067,-0.442745,-0.333322,-0.156804,0.024075,-0.175833,-0.488678,0.029306,-0.779499,-0.150045,-0.381020,-0.499728,0.123450,-0.063315,-0.100634,0.269485,-0.810925,-0.162190,0.635633,0.349644,-0.368788,0.529047,0.282943,-0.076909,-0.254660,-0.112347,0.009743,0.314040,0.383540,0.492870,0.416057,0.110479,-0.182651,-0.215184,0.255518', '1947080', '25870679', '1307442', '1306801');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2968813', '生人勿进', '剧情', '遥远的北欧地区，瑞典的斯德哥尔摩一片银装素裹，寒气逼人。12岁少年奥斯卡（Kåre Hedebrant 凯尔•赫德布朗特 饰）生活在一个单亲家庭，他在学校形单影只，饱受欺负；回家后则偷偷搜集关于各类凶杀案的剪报，或者深夜挥着小刀在树上发泄着自己的愤怒。新搬来的小孩爱莉（Lina Leandersson 莉娜•莱纳德尔森 饰）走进了奥斯卡的生活，他们慢慢成为朋友，并逐渐产生爱情。而就在此时，奥斯卡无意中发现爱莉一个令人毛骨悚然的秘密……本片改编自瑞典小说家约翰•林德科维斯特（John Ajvide Lindqvist）2004年的同名畅销书，并荣获2008年翠贝卡电影节最高奖、2008高森博格电影节最佳北欧电影奖及柯达最佳摄影奖。©豆瓣', '凯尔·赫德布朗特', '托马斯·阿尔弗莱德森', 7.6, 44695, 'tt1139797', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2189771086.jpg', 0.8, 3.5, 29, 45.9, 20.7, '0.070582,0.020815,-0.504025,0.507023,0.190502,-0.336026,0.783200,0.205395,-0.354820,-0.312469,0.061493,0.983586,-0.171346,0.402119,0.357669,0.168608,-0.634583,-0.667895,-0.176111,-0.419224,-0.158597,-0.273976,-0.265287,-0.097110,-0.103483,-0.253602,0.534161,-0.204245,-0.159846,0.627589,0.401382,0.245689,-0.132618,0.206359,-0.179862,0.069931,0.407549,-0.033629,-0.247148,0.407320,0.025929,-0.208927,-0.330263,0.070473,0.070944,0.142275,0.741412,-0.200125,0.033572,0.018226,0.605176,-0.197690,-0.047041,-0.061830,0.321712,-0.218523,0.078512,-0.179105,-0.130259,0.204528,0.259726,-0.221658,-0.399231,0.269584,-0.130513,0.301343,-0.366328,0.502186,0.017192,-0.054691,0.099766,-0.174552,0.217428,0.141790,-0.009134,0.227741,-0.085722,0.047906,-0.311798,0.497652,0.244006,-0.034314,-0.220818,0.041967,-0.363070,-0.433545,-0.068370,-0.011336,-0.611288,-0.253301,0.678588,-0.130059,-0.017849,0.330609,-0.449946,0.138108,-0.039305,-0.331651,-0.008724,-0.145532,-0.105054,-0.754112,0.014195,-0.028636,-0.187937,-0.275342,-0.030384,-0.263490,0.531687,-0.456035,0.510505,0.643921,0.074192,0.206836,0.552166,-0.256143,0.076828,-0.178789,-0.281103,0.709811,-0.006120,0.274410,0.085689,0.381723,-0.031475,-0.139861,-0.339552,0.650163', '1309194', '1484091', '1299663', '1829654');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2969282', '七磅', '剧情', '“上帝用7天创造世界，我用7秒钟，就毁灭了自己。”本·汤姆森（威尔·史密斯饰）向急救中心报告自己自杀的情况。是什么让他选择了自杀来结束自己的生命？追溯往日，本作为调查员，负责调查部分公民对国家经费的拖欠与申请问题。表面上刻薄的他其实内心充满温情。但没有人能够触及他的内心，本心中到底牵挂着什么？某一天，本开始调查心脏病移植手术等待者艾米莉·波莎（罗萨里奥·道森饰）。在调查过程中，他的心中起了波澜。于是，一个计划在本的心中盘算。本到底隐瞒了什么？而这些，又与本的自杀有什么样的关系呢？一份重达七磅的救赎，一段不堪回首的记忆，本·汤姆森与观众一同探寻生命的意义。©豆瓣', '威尔·史密斯', '加布里埃莱·穆奇诺', 8.2, 117977, 'tt0814314', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p729808513.jpg', 0.3, 1.8, 18.7, 47.8, 31.4, '0.086732,0.187243,-0.731431,0.430005,-0.247083,-0.012686,0.605723,-0.109005,-0.396303,-0.243668,-0.111649,0.648511,-0.255354,0.085745,0.367195,0.059242,-0.411964,-0.613297,-0.062255,-0.304269,-0.151800,-0.856186,-0.373242,-0.569073,0.216946,-0.102004,0.679574,0.232596,-0.196130,0.024106,0.055554,0.403376,0.320738,0.314556,-0.016203,-0.221634,-0.213443,0.051093,-0.036316,-0.053506,0.443152,-0.402744,-0.343050,0.479712,-0.092937,0.658157,0.363431,-0.335286,-0.280959,-0.121558,0.225343,-0.078833,0.085058,-0.047477,-0.340038,-0.025307,-0.058911,0.535705,-0.075631,-0.102040,0.200896,0.117884,-0.906914,-0.389531,-0.276737,0.214190,-0.344759,0.171249,-0.219770,0.075224,-0.026384,-0.196070,0.228374,0.388854,0.230298,0.213082,-0.547450,-0.231302,-0.541584,0.190549,0.686671,0.117582,-0.162383,0.361366,-0.131519,-0.566746,-0.395345,0.106372,-0.314524,-0.070433,0.130300,0.315407,-0.214403,0.212666,-0.573600,-0.065037,-0.239455,-0.320854,-0.139227,-0.506974,0.110194,-0.280619,-0.269034,-0.222616,-0.501042,-0.192970,0.478088,-0.248850,0.697411,-0.745716,0.297580,0.417546,0.078854,-0.825251,0.466350,0.573827,-0.031901,-0.160243,-0.074037,0.204546,-0.168998,0.411916,0.008755,-0.045137,0.384478,0.054577,-0.326072,0.514578', '26678784', '30163500', '1811755', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2969402', '所罗门王凯恩', '动作', '在那个充满战争和巫术的时代，所罗门·凯恩（杰姆斯·鲍弗 James Purefoy 饰）在无尽的贪欲和杀戮之中迷失自我，险些沦为魔王的傀儡。大难不死的所罗门回到故乡英格兰的一所修道院里，本想就此过上远离杀戮生活的他，在神父的指示下踏上回家的路。此时，外面遍布杀戮与抢掠，孤身上路的所罗门险遭不测，幸被准备举家迁往美洲的克鲁索恩一家所救。在与克鲁索恩一家相处的过程中，所罗门感受到家人的温暖与信任。一天清晨，克鲁索恩一家遭遇一群邪恶武士，他们杀死了克鲁索恩先生和两个儿子并抢走了克鲁索恩先生的女儿梅瑞蒂斯（蕾切儿·哈伍德 Rachel Hurd-Wood 饰），克鲁索恩在临死之前，祈求所罗门救出女儿，并告诉他只有救出梅瑞蒂斯，他的灵魂便才能得到惩救。立誓永不杀戮的所罗门为了救出梅瑞蒂斯同时惩求自己的灵魂，他不得不重拾战剑……本片根据美国作家罗伯特·霍华德（Robert E. Howard）1928年创作的同名小说改编。', 'Rachel Hurd-Wood', 'Michael J. Bassett', 5.8, 7214, 'tt0970452', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1681020288.jpg', 4.6, 23.9, 53.5, 14.2, 3.7, '0.129238,0.120515,-0.649823,0.494048,0.017326,-0.559038,0.779445,-0.092513,-0.292748,-0.386422,0.105957,0.747242,0.136614,0.348933,0.489707,0.072544,-0.359227,-0.471508,-0.128480,-0.154733,-0.191872,-0.464970,-0.279566,0.018030,-0.027547,-0.623614,0.662827,0.302689,-0.185855,0.413356,-0.071732,0.453221,-0.257739,0.352910,-0.215819,-0.023559,0.010134,-0.013197,-0.630731,0.355901,-0.051170,0.000268,-0.068307,0.064414,0.010399,0.075054,0.636040,-0.569962,0.150517,-0.149723,0.135395,-0.303802,0.035177,0.180773,0.057156,-0.109240,0.135418,0.364738,-0.222951,-0.034937,-0.168548,-0.299107,-0.853158,-0.160725,-0.032456,-0.066522,-0.500709,0.328766,0.152669,0.119094,0.115277,-0.430571,0.308904,0.192645,0.115665,0.400192,-0.290695,-0.006103,-0.459311,-0.123442,0.787740,-0.303642,0.013263,0.075857,-0.064689,-0.316279,-0.063506,0.117446,-0.567876,-0.109048,0.304889,0.186444,-0.111622,0.443993,-0.679255,-0.218020,-0.320299,-0.117029,0.225649,-0.342188,0.097646,-0.599224,-0.213346,-0.083879,-0.115575,0.059501,0.267053,-0.306843,0.505960,-0.763143,0.518286,0.494359,0.430666,-0.337943,0.531322,0.107612,0.292335,-0.209152,0.023308,0.695231,0.311932,0.142464,0.114376,0.159186,0.04