INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2970087', '生化危机：恶化', '动作', '7年前，一颗核弹将浣熊市的一切隐藏在历史之中。7年后的今天，美国中西部城市哈佛维尔，参议员朗•戴维斯因群众抗议其与威法玛公司的关系而被困飞机场。正当他乔装打扮准备离开之时，一位抗议者咬死了参议员的警卫。这位抗议者竟然是T病毒感染者！“浣熊市事件”幸存者， 克莱尔•雷德菲尔德在机缘巧合下救出议员，不想这时一架飞机冲向候机大厅。推开机门的，竟是一个个T病毒感染者！政府迅速采取对策，里昂•S•肯尼迪——“浣熊市事件”的另一位幸存者，奉命前来支援。浣熊市的悲剧是否会重演？事件的幕后黑手又在盘算什么样的阴谋？根据游戏改编的全CG电影《生化危机：恶化》将作出解答。©豆瓣', '保罗·默西埃', '神谷诚', 7.2, 32144, 'tt1174954', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1722814464.jpg', 0.7, 4.4, 40.5, 40.6, 13.8, '0.268830,-0.010538,-0.541426,0.355732,0.244067,-0.011573,0.554254,0.146560,-0.434104,-0.250770,0.502332,0.709823,-0.297940,0.210952,0.305395,-0.254723,-0.508164,-0.551580,-0.188711,-0.093393,-0.200467,-0.374722,-0.409171,-0.424005,0.257730,-0.140072,0.651875,0.335199,0.051975,0.309791,0.270241,0.605066,-0.478287,0.352647,0.217667,-0.108999,0.430150,-0.196726,-0.384243,0.209433,-0.086145,-0.370305,-0.041287,0.034581,0.126990,0.305461,0.485932,-0.086977,-0.064482,-0.245509,0.202374,-0.400235,0.001915,0.064784,0.749143,-0.166201,-0.001364,0.272045,-0.127541,-0.000364,-0.073026,-0.078549,-0.373511,-0.098247,-0.145923,0.217361,-0.412337,0.056356,-0.338181,0.163721,0.023908,-0.195472,0.178643,0.670113,0.240354,0.117169,0.037138,0.118215,-0.421978,-0.015895,0.537828,0.020230,0.007319,0.033832,0.060105,-0.457822,-0.144329,0.049015,-0.095244,-0.029858,0.478758,-0.226307,-0.210500,0.233301,-0.353345,-0.444066,-0.558747,-0.567312,0.174294,-0.095003,-0.228394,-0.758898,0.194064,0.348028,-0.018102,-0.090240,0.075166,0.194777,0.459506,-0.681668,0.070851,0.570819,0.053558,-0.536599,0.345078,-0.296417,0.112087,-0.083728,0.001157,0.187194,0.206663,0.572646,-0.159126,0.130992,-0.082846,-0.452154,-0.181301,0.196714', '1306809', '25723905', '3871833', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2970163', '曾是超人的男子', '剧情', '宋秀晶（全智贤 饰）三年来不断面对虚伪的感动拍摄记录片，此刻她想要拍真实的非洲狮子。感到厌倦不已的她拿走了公司的摄影机代替自己的工资，决心要开办小型的制片公司。但发展所需的材料令她困扰极了，拍摄日子在即，她的摄影机眼看就被小偷抢走了。危急之际，一个穿着夏威夷衬衫的男人（黄政民 饰）帮她从小偷手上抢回了摄影机。这个男人自称自己是超人，更摆出各样奇怪的超人姿势。秀晶灵机一动，决定跟随他拍摄“拯救地球”的记录。这段影片很快便曝光了，而且得到了极高的关注率。可是在告捷会后，这个傻傻的超人竟然说要揭开记录片里的伪造之处。因此意外摔伤了头部的超人，被医生发现了脑中又异样的东西。©豆瓣', '黄政民', '郑胤澈', 7.4, 11870, 'tt1119199', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2276782676.jpg', 0.9, 5.3, 34.3, 41.4, 18.1, '0.258020,0.042375,-0.595603,0.396825,0.033815,-0.026481,0.592690,0.048914,-0.348941,-0.280246,0.472236,0.680867,-0.330485,0.054412,0.169056,0.154407,-0.236796,-0.669690,-0.095561,-0.067135,-0.348451,-0.106649,-0.525429,-0.233155,-0.104481,-0.168469,0.516662,0.097129,-0.194106,0.413794,0.316867,-0.017356,0.246802,0.504800,-0.163682,-0.097885,-0.147678,-0.013759,0.186779,0.156877,0.171380,-0.447475,0.157646,0.532649,-0.139344,0.492870,0.592005,-0.092120,-0.295254,0.059944,0.626177,-0.354268,-0.021250,-0.007515,0.019442,0.199938,-0.030410,-0.250016,-0.396339,0.098031,0.257128,-0.019491,-0.781411,-0.032749,0.020636,0.098471,-0.679130,0.271397,-0.307104,0.234423,0.220331,-0.296528,0.117456,0.194254,0.288559,0.450718,0.043624,-0.082252,-0.441382,0.469081,0.237610,-0.205056,-0.103107,0.549654,-0.112234,-0.324914,-0.092680,-0.115662,-0.341892,0.002530,0.229238,0.095946,-0.291379,-0.064543,-0.383436,0.061346,-0.176731,-0.020387,-0.163026,-0.433368,-0.259851,-0.510719,-0.136985,-0.259486,-0.068016,-0.091194,0.066618,-0.337550,0.596319,-0.570285,0.038700,0.627332,0.188873,-0.482214,0.592223,0.027523,-0.161866,-0.231792,-0.111678,0.057053,0.039586,0.328607,0.072667,0.249497,0.052060,-0.469812,-0.369258,0.417303', '25928048', '30279170', '34890458', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2971730', '你好，再见', '剧情', '一宗交通意外，连结两个陌生的人。马克（查克·伯劳姆 Chuck Blaum 饰）在车祸中丧生，一直暗恋他的好友杰夫（亚当·尼尔·史密斯 Adam Neal Smith 饰）因代为回复电邮，认识了马克生前的意大利网友安德烈（亚历山德罗·卡萨 Alessandro Calz a 饰）。安德烈本想取消来德州的计划，但最终被杰夫说服。两个拥有不同人生轨迹的男人，于是带着一点点惆怅和困惑，在阳光如织的德州天空下发生交集。他们真切的分享对逝者的美好回忆，于淡淡的哀鸣中寻找路标前行。“Ciao”在意大利语里既是“你好”也是“再见”的意思。一个悠长的故事在Ciao中开始，在Ciao中结束，引发了人们强烈的共鸣。生与死，性与爱，得到与失去，就像绵绵的细雨落在全世界的草坪，打湿一颗颗柔软的心。©豆瓣', '查克 布劳姆', '陈俊彦', 8.1, 15805, 'tt0870089', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p523684897.jpg', 0.4, 1.9, 20, 48.1, 29.6, '0.401537,0.174510,-0.866534,0.583675,0.034463,-0.100270,0.994150,0.008906,-0.416878,0.049437,0.092293,0.636877,-0.364951,0.197894,0.291475,0.034741,-0.399840,-0.761993,0.109476,-0.078130,-0.192574,-0.652038,-0.275288,-0.116232,-0.152795,-0.340862,0.473219,0.313052,-0.123980,0.640854,0.200733,0.219221,-0.289493,0.557828,-0.194982,0.165917,-0.057637,0.055159,-0.285172,0.049980,0.075139,-0.186185,-0.143215,0.015555,-0.112010,0.465799,0.685075,-0.372946,0.004464,0.197663,0.254190,-0.144980,0.045593,0.256812,0.120452,0.369772,0.051541,0.247314,-0.318300,0.021704,0.028020,0.142201,-0.569333,-0.028505,0.156091,0.568852,-0.408785,0.632177,-0.023209,-0.304981,0.239589,-0.376319,0.315895,-0.063697,0.197338,0.530270,-0.126479,-0.047512,-0.308319,0.094898,0.670188,0.009474,-0.438224,0.270858,-0.451084,-0.222693,-0.152275,0.275219,-0.486369,-0.098126,0.427383,0.088985,-0.088267,0.422015,-0.669878,0.127650,-0.090619,-0.365730,-0.247080,-0.456462,-0.218517,-0.490296,-0.173903,-0.447782,-0.336529,0.111781,-0.015911,-0.239563,0.573423,-0.824767,0.318611,0.395904,0.159667,0.015035,0.598697,0.333877,0.144870,-0.142097,0.020980,0.453088,0.050366,0.077213,0.158720,0.255078,-0.095781,0.304207,-0.514191,0.445995', '1292211', '1296534', '3111650', '6827727');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2971742', '雪地巴迪', '家庭', '五只终日脏兮兮的小狗因为贪食冰淇淋被飞机从华盛顿带到了阿拉斯加，起初，它们面对满山冰雪异常兴奋，但很快便被寒冷的天气打败。这时，它们认识了一只爱斯基摩犬，并通过它知道了一个故事。爱斯基摩犬的小主人亚当（Dominic Scott Kay）一心想参加即日举行的年度雪橇比赛，可是有伤心往事的爸爸只想他做棒球手，于是亚当日夜期盼奇迹发生：上天派给他五只小狗（加上他的爱斯基摩爱犬，刚好组成一支雪橇队），爸爸看到后同意他参加比赛。五只小狗听后，决定帮助亚当圆梦，并于圣诞节将自己当作礼物齐齐出现在亚当面前，兴奋异常的亚当知道无法说服爸爸，决定瞒着他报名参赛。©豆瓣', '多米尼克·斯科特·凯伊', 'Robert Vince', 7.7, 5919, 'tt1079448', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2513448969.jpg', 0.5, 2.7, 30.8, 44, 22, '0.075510,0.073298,-0.721497,0.292685,0.138968,0.034839,0.440713,-0.064108,-0.301331,-0.073783,0.077429,0.703832,-0.059422,0.417106,0.147183,-0.103587,-0.097498,-0.359723,0.092976,0.035354,-0.161050,-0.147831,0.020605,-0.100605,0.306298,-0.160262,0.396471,-0.176267,0.123190,0.798960,0.408082,-0.021272,0.086754,0.360439,-0.139095,-0.156338,0.063740,0.082649,-0.021877,0.218370,-0.051000,0.127784,-0.093678,0.129438,0.086656,0.084432,0.612586,-0.550273,-0.327142,-0.347151,0.006242,-0.377778,0.137716,0.178801,0.265587,0.261635,0.016929,-0.123441,-0.015177,0.310546,0.215358,-0.183833,-0.371755,0.221326,-0.348767,0.279485,-0.492275,0.144926,-0.117514,0.330801,0.309753,-0.458716,0.165688,0.116896,0.158352,0.298971,-0.101845,0.114314,-0.468687,-0.024313,0.672130,-0.418861,-0.054622,0.145742,-0.054213,-0.388628,0.349135,-0.087207,-0.099055,0.192562,0.351082,0.065098,-0.544498,0.072419,-0.425091,-0.154883,-0.151609,-0.502627,-0.095784,-0.461190,0.049758,-0.260652,0.333958,0.034171,-0.200836,-0.019057,0.084176,-0.323084,0.493121,-0.663901,0.440762,0.360806,0.240075,-0.161044,0.399865,-0.009581,0.124315,-0.124471,0.324623,0.088419,0.203971,0.209085,0.373835,0.202708,0.255981,-0.117645,-0.528614,0.362645', '25723081', '35256235', '1292219', '3626364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2973079', '霍比特人3：五军之战', '动作', '被吵醒的史矛革大闹长湖镇，最终为人类巴德（卢克·伊万斯 Luke Evans 饰）射杀。索林·橡木盾（理查德·阿米蒂奇 Richard Armitage 饰）多年的夙愿终于实现，孤山埃尔波尔重新回到矮人手中。然而这位矮人王子仿佛被史矛革的贪婪和堆成山的黄金迷惑了心窍，他 疯狂地搜寻象征王位的阿肯宝石，不仅撕毁了付给长湖镇报酬的约定，更拒绝了精灵王（李·佩斯 Lee Pace 饰）索要本族国宝的要求，为此导致三族的战争一触即发。与此同时，苍白半兽人阿索格率领大军浩浩荡荡向孤山逼近。得知消息的灰袍巫师甘道夫（伊恩·麦凯伦 Ian McKellen 饰）从中调停斡旋，而被索林视为唯一朋友的霍比特人比尔博·巴金斯（马丁·弗里曼 Martin John C. Freeman 饰）则掌握着中土命运的关键。五军会战，爆发在即！本片根据J.R.R·托尔金的同名原著改编，为霍比特人系列的最后一部。', '马丁·弗瑞曼', '彼得·杰克逊', 8.6, 361243, 'tt2310332', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2219406504.jpg', 0.3, 1.3, 13.5, 40, 44.9, '0.220924,0.285849,-0.612108,0.600360,0.309309,-0.565399,0.456109,0.033114,-0.069559,-0.378476,0.359413,0.560574,-0.041441,-0.373640,0.397609,-0.109583,-0.419005,-0.354289,-0.136188,-0.085113,-0.201591,-0.323566,-0.278463,-0.339107,-0.176160,-0.425039,0.574809,0.032077,-0.059336,0.315342,0.296931,0.654628,0.114200,-0.006870,0.075802,0.072998,0.191857,-0.224850,-0.322454,0.244892,-0.244569,0.085744,-0.206330,0.190862,-0.112821,0.315218,0.654834,-0.688242,0.331750,-0.186317,0.167120,-0.315272,0.229264,-0.055392,0.347434,-0.058083,-0.038959,0.089741,-0.256022,-0.295406,0.181064,-0.065196,-0.496444,0.043553,0.169470,0.196345,-0.462552,0.301873,-0.165112,0.272613,0.264417,-0.122754,0.002760,0.431984,0.319476,0.152673,0.173817,-0.066569,-0.448303,0.105459,0.210541,-0.195282,-0.176308,-0.305217,-0.149196,-0.461162,0.029849,-0.212218,-0.352515,-0.128321,0.664268,-0.041763,0.413697,0.620712,-0.772123,-0.392037,-0.552118,-0.137418,0.200622,-0.299883,-0.137444,-0.719166,-0.122249,0.028631,0.165979,0.026658,0.246569,0.075557,0.484055,-0.207070,0.188396,0.270021,0.173110,-0.035614,0.260342,-0.095848,0.062074,-0.354183,-0.165008,0.505039,0.475925,0.205472,0.363519,-0.022315,0.112865,-0.121073,-0.221697,0.614462', '11606328', '27133569', '20326665', '1298586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2973528', '密码疑云', '剧情', '俄罗斯国家安全局女特工达莎（安娜斯塔西娅·扎沃洛纽克 Anastasiya Zavorotnyuk 饰），受命在恐怖组织首领扎法德的武装基地担当卧底，逐渐获得信任，得知扎法德即将实施一起全球性恐怖计划——犯罪组织已在四个人口密集的国际大都市内秘密安放了四枚遥控核弹，几乎可以破坏整个亚欧大陆。然而扎法德却突然被同伙巴特杀死，并被盗取了引爆密码。达莎又受命联络一位法国银行家路易斯（文森特·佩雷斯 Vincent Perez 饰）一同阻止阴谋。两人在追查的途中，达莎的恐怖分子身份不料引起了美国中情局的注意，跨国追查遇到重重阻碍。然而就在达莎击毙恐怖分子巴特之后，核弹危机竟然仍未解除，事态远比想象中复杂……本片由俄罗斯国家电影基金会投资，并获得俄罗斯军方全力支持。美国、法国、挪威、英国等多国均参与合拍，并在巴黎、佛罗伦萨、挪威、吉隆坡双子塔等地取景拍摄。©豆瓣', '文森特·佩雷斯', '瓦季姆·舒梅列夫', 6.2, 5107, 'tt1087832', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1815369838.jpg', 3.3, 15.9, 54.1, 21.2, 5.5, '0.121789,0.222238,-0.762492,0.288737,0.373607,0.009352,0.322024,0.050065,-0.264546,-0.110103,0.224329,0.486047,-0.122562,-0.322136,0.155261,-0.044751,-0.577583,-0.693092,-0.140721,-0.057987,-0.251168,-0.605136,-0.348768,-0.352037,0.015776,-0.269042,0.652068,0.269495,-0.435921,0.307419,0.181400,0.381342,-0.463311,0.544939,0.104253,-0.418291,0.684753,-0.241230,-0.466661,0.489568,-0.245432,-0.283775,0.160099,0.184245,0.047093,0.422385,0.263576,-0.187069,0.189857,-0.192946,0.167362,-0.129565,0.004155,0.015467,0.532769,-0.010104,-0.144720,0.296903,-0.278322,-0.023216,0.248725,-0.164225,-0.637868,0.172927,0.177165,0.175037,-0.194744,0.059189,-0.260226,0.239970,-0.059177,0.093824,0.175583,0.703922,0.396514,0.068588,-0.022296,0.287673,-0.445011,0.010296,0.454100,-0.413116,-0.432615,-0.110700,0.088871,-0.340777,0.020009,-0.124281,0.128577,0.009090,0.304204,-0.128450,-0.060941,0.396284,-0.589482,0.086962,-0.559941,-0.284002,0.038974,-0.204058,0.254127,-1.221713,-0.085867,0.209747,-0.116906,0.227855,0.219908,0.161331,0.486439,-0.357984,0.129368,0.718981,0.506298,-0.423786,0.147473,-0.011254,0.043658,-0.293056,-0.121401,0.337170,0.435465,0.257826,-0.051186,-0.030698,-0.025316,-0.491777,-0.009946,-0.048880', '1293572', '3003137', '4014397', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2973543', '合法副本', '剧情', '英国作家詹姆斯·米勒（威廉·施梅尔 William Shimell 饰）来到意大利城市托斯卡纳为新作《合法副本》举办讲座。他与读者讨论书中的观点：关于艺术创作真实性的议论是毫无必要的，因为复制品本身即是原作，原作也是由其他作品复制而来。一个做古董买卖的法国女人（朱丽叶· 比诺什 Juliette Binoche 饰）带着11岁的儿子参与了讨论会，想为刚买的书索要签名。中途因为儿子饿了她提前离开，临走时留下了一个电话号码。米勒和女人在她的古董店再次相遇，他们驱车去郊外看一样东西。她开着车载着米勒无目的游荡，谈论书的主题，参观博物馆，谈论她叛逆的儿子，两人一路上争吵不休。在一个咖啡馆，女老板以为米勒是女人的丈夫，就开始和她围绕米勒讨论起婚姻。于是他们将错就错，米勒开始扮演女人的丈夫，两人约会，去宾馆。但是副本只是复制，而非原作，米勒结束复制身份，独自离开了郊外。比诺什凭借此片获得第63届戛纳电影节主竞赛单元最佳女演员奖。', '朱丽叶·比诺什', '阿巴斯·基亚罗斯塔米', 8, 21255, 'tt1020773', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p567795093.jpg', 0.5, 2.1, 20.8, 50.4, 26.3, '0.432148,-0.067566,-0.618322,0.581711,-0.176814,-0.286568,0.523025,0.196585,-0.339430,-0.188071,0.147755,0.906115,-0.199901,0.099636,0.265852,-0.036255,-0.538384,-0.487843,0.091796,-0.241612,-0.087624,-0.603670,0.250458,-0.332325,-0.037453,-0.129353,0.437694,-0.173850,-0.185490,0.230327,0.432439,0.080923,-0.242398,0.319226,-0.170496,-0.064345,0.096722,0.190031,-0.353980,0.465982,0.001025,-0.056678,-0.356972,-0.015688,0.201250,0.397003,0.704500,-0.082629,0.069380,-0.018232,0.432126,-0.126288,-0.090626,-0.023426,0.112578,0.151106,0.284954,0.185068,0.007313,0.085417,-0.020591,-0.241045,-0.365893,0.170332,0.096069,0.178008,-0.462139,0.482377,-0.217956,0.074638,0.212297,-0.353598,0.373748,0.121542,0.381904,0.158251,0.202008,-0.152735,-0.543721,0.461290,0.342675,0.050848,0.059583,0.414105,-0.107678,-0.333846,0.070491,-0.100373,-0.395790,0.040008,0.183726,-0.048878,-0.089384,-0.122846,-0.559649,-0.132788,-0.042480,-0.462777,0.249700,-0.487758,0.052111,-0.916348,0.081423,0.083494,-0.083929,-0.167674,0.066985,-0.369694,0.639229,-0.768689,0.181999,0.791049,0.460391,-0.660543,0.874851,-0.030216,0.022171,-0.326885,0.031411,0.049715,0.024072,0.214020,-0.148536,0.312864,0.208322,-0.201057,-0.330230,0.551211', '1484091', '3326747', '3285622', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2974273', '地铁惊魂', '剧情', '沃特（丹泽尔•华盛顿 Denzel Washington 饰）是一名纽约地铁调度员，负责控制各条线路的调配运营。某日，一群恐怖分子劫持了地铁123号线，匪首雷德（约翰•屈伏塔 John Travolta 饰）为前美国雇佣兵，声言要提供1000万赎金才释放人质。巧的是，该数额正式保险金、商业贷款等提取的上限。地铁123号线在隧道里飞驰，乘警多人毙命，司机被挟持，乘客人人自危。沃特因工作失职被调离，后因雷德点名，才被迫参与谈判，面对贪污的质问，他的坦诚拯救了一名年轻乘客的生命。面对劫匪提出的高额赎金和苛刻条件，纽约市长如坐针毡，正当他准备划破钱款平息事端之时，丧心病狂的劫匪又突然改变了主意。作为高速运输管理局要员，沃特决定用自己替换人质，与劫匪展开了一场惊心动魄的生死搏斗……©豆瓣', '丹泽尔·华盛顿', '托尼·斯科特', 6.7, 32549, 'tt1111422', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p620142513.jpg', 0.9, 7.1, 54.2, 31.5, 6.3, '-0.074488,-0.033129,-0.329073,0.210811,-0.128444,-0.262327,0.632691,0.056036,-0.186845,-0.059868,0.606810,0.684527,-0.142967,-0.206426,0.631969,-0.069424,-0.376931,-0.459339,-0.045919,0.077966,-0.370917,-0.569560,-0.087613,-0.276442,-0.086557,-0.083420,0.341973,0.113269,-0.108509,0.328332,0.322160,0.251460,-0.186363,0.365376,0.190796,-0.320164,0.502392,-0.220879,-0.111264,0.150170,-0.264067,-0.353598,0.076586,-0.077868,0.071155,0.809872,0.550077,0.198265,-0.109779,-0.099613,0.087370,-0.458330,0.184950,0.004331,0.236897,0.343965,0.023777,0.145108,-0.428072,-0.053240,-0.085532,0.003219,-0.689590,-0.178907,-0.229827,-0.116730,-0.491987,0.102675,-0.360302,0.162760,-0.011349,-0.295647,0.033793,0.349012,0.092032,0.345988,-0.006787,-0.185666,-0.289277,0.270321,0.576121,-0.193984,-0.276658,0.062894,-0.055189,-0.486951,0.253839,-0.197290,-0.209828,-0.200786,0.411819,-0.218454,-0.003579,0.077861,-0.306584,-0.181602,-0.604034,-0.290331,-0.214891,-0.038151,-0.125608,-0.728748,0.241382,0.077238,0.022048,0.351783,0.362754,0.317952,0.339178,-0.428434,-0.039098,0.747327,0.465977,-0.800794,0.230172,-0.003518,0.262595,-0.264927,0.003738,-0.226937,0.224027,0.657156,0.095732,0.033517,-0.075638,-0.227760,-0.039113,0.097676', '5973984', '1309116', '1303139', '27126336');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2974278', '蓝色情人节', '剧情', '《蓝色情人节》在分级上经历了一波三折，最终被定为R级。Dean(瑞恩·高斯林 Ryan Gosling 饰)和Cindy(米歇尔·威廉姆斯 Michelle Williams 饰)在朝夕相处了六个年头之后，他们的婚姻出现了问题。两人想借情人节之际修补彼此的关系， 特意将女儿留在外公家。他们还特意找了一家情人酒店，想找点新的“兴奋点”来刺激自己的爱情。可两人就对未来的生活态度发生了争执，感情不但没有修复反而愈吵愈烈。Dean安逸于有妻女的平淡生活，但Cindy却希望开创属于自己的事业。随着两人的分歧不断升温，那些以往美好婚姻生活中的幸福的片段如今却变成了令人难堪和苦恼的回忆。是否一段感情必须要经历“七年之痒”的磨练？这两个曾经相爱的彼此，曾经甜蜜的婚姻，否则最终会走向支离破碎？©豆瓣', '瑞恩·高斯林', '德里克·斯安弗朗斯', 7.8, 90703, 'tt1120985', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p710464565.jpg', 0.4, 2.4, 26.7, 49.2, 21.3, '0.287799,0.098743,-0.618176,0.603333,0.070291,-0.480615,0.957740,0.054072,-0.538993,-0.221529,-0.058003,0.499993,-0.211707,0.245479,0.212094,-0.287839,-0.181617,-0.899168,0.199898,-0.089958,-0.285254,-0.449987,-0.352482,-0.158865,-0.222012,-0.087823,0.622878,0.186147,-0.117872,0.281257,0.212253,0.079065,-0.215569,0.396561,-0.323522,0.036502,0.035322,0.541661,-0.637995,-0.064278,0.238620,-0.179382,0.001723,0.161439,0.008000,0.382604,0.690703,-0.154314,-0.433470,0.130106,0.278285,-0.016092,-0.139768,0.246243,0.074403,0.286259,0.224692,0.345585,-0.274686,-0.239531,0.013375,-0.126304,-0.988408,0.112664,0.102493,0.036134,-0.537233,0.661201,0.120418,-0.171495,0.155455,-0.072656,0.349641,0.794478,0.619242,0.390459,-0.299725,-0.046255,-0.300380,0.405516,1.082665,-0.090623,-0.313735,0.539162,-0.538684,-0.096329,-0.231897,-0.128806,-0.581874,0.051747,0.310186,0.280321,-0.275277,0.444952,-0.751742,0.110346,-0.187933,-0.123185,0.212622,-0.514032,0.198196,-0.424831,-0.339921,-0.663162,-0.554601,0.066434,-0.053859,-0.372337,0.606758,-0.738912,0.257241,0.339060,0.403701,-0.726666,0.614031,0.365634,0.101134,-0.227626,0.165094,0.231883,-0.354274,0.077029,0.259275,0.327480,0.177496,0.250889,-0.434876,0.651051', '26678784', '25828589', '30140231', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2974280', '所有美好的东西', '剧情', '影片根据纽约历史上最声名狼藉的谋杀悬案改编。1973年纽约地产富豪的儿子Robert Durst（瑞恩·高斯林 Ryan Gosling 饰）娶了美丽的穷学生Kathleen McCormack（克斯汀·邓斯特 Kirsten Dunst 饰）。两人婚后离开 城市，到乡村享受了一段恬静的时光，当返程时卡蒂回到了学校继续学业。一切看似幸福，可1982年Kathleen突然失踪寻访不得。2000年Durst的好友Susan Berman被发现死在家中，20年前的失踪案被重新唤起，Durst因这两个案件受到询问，但都因为证据不足而未受起诉。2001年Durst的邻居Morris Black被杀，尸体被分解，他再一次受到怀疑被起诉，可经著名律师辩护后被无罪释放。直到2004年再次接受审判Durst最终被判5年监禁，媒体将"百万富翁凶手"的名号赠予他。©豆瓣', '瑞恩·高斯林', '安德鲁•亚雷茨基', 6.7, 11393, 'tt1175709', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1139859260.jpg', 0.8, 7.6, 51.9, 33.6, 6.1, '0.168384,-0.018701,-0.398787,0.142158,0.237428,-0.396175,0.560494,-0.050235,-0.721411,-0.387241,-0.060266,0.523638,-0.516564,0.437767,0.409917,-0.177734,-0.111804,-0.741621,0.229245,-0.278573,-0.358191,-0.401023,0.134212,-0.088219,-0.201837,-0.327511,0.515632,0.259503,0.270398,0.531697,0.083331,0.368758,0.164355,0.311549,-0.104982,0.093825,0.169658,0.090020,-0.282536,0.459429,0.128288,-0.656767,-0.118529,-0.109596,-0.103243,0.268854,0.780498,-0.056680,-0.197019,-0.385744,0.566571,-0.451066,-0.103214,0.224759,0.527756,0.201305,-0.009548,0.672442,-0.684926,-0.290286,0.169491,-0.323661,-0.342811,-0.041593,-0.044337,-0.125199,-0.513535,0.338320,-0.294712,0.269489,-0.245648,-0.245402,0.384139,0.380077,0.546427,0.477314,-0.188745,0.215535,-0.445594,0.392516,0.705372,0.007081,-0.342697,0.109502,-0.031436,-0.429727,0.011129,-0.575487,-0.397120,0.474038,0.236047,0.144405,-0.276016,0.367724,-0.593671,-0.497136,-0.523929,-0.434278,0.138146,-0.425388,-0.440176,-0.365248,-0.270321,0.021161,-0.292471,0.080376,-0.012548,-0.288091,0.394196,-0.626523,0.512659,0.453053,0.382440,-0.718807,0.796458,-0.077831,0.152284,-0.011072,0.098418,0.418119,0.496550,0.296677,0.333459,0.016206,-0.255633,-0.256671,-0.144077,0.314176', '1366853', '21937434', '1308086', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2976072', '东京少年', '爱情', '少女藤木美奈斗（堀北真希 饰）有一个无话不谈的笔友奈特（意为“骑士”），生活中发生的大小事她都与之倾诉。在士多店打工的美奈这天遇见了男生唐泽秀（石田卓也 饰）并一见钟情。阿秀热爱摄影，却迫于医学家族的压力一直努力考取大学医学专业，两度落榜的他还在苦闷地奋斗中。阿斗将自己的倾心告诉奈特，却被奈特反对。然而阿斗这次仍然听取了自己的心意，向阿秀表白。在二人交往的过程中，阿斗发现自己会突然消失记忆，甚至手机中存储的阿秀的照片以及号码都会不见。困惑的她怕被阿秀嫌弃，一直保守着这个秘密。随着失忆的情况发生次数越来越多，阿斗鼓励她去他父亲的医院检查。检查结果出来后，阿斗却提出了分手。伤心的阿秀接受了这个结局，她渴望这时能见到奈特，得到奈特真人的慰藉。然而无论她如何苦等，奈特也没有出现，直到这晚，她得到一串钥匙，当她启开秘密的大门，惊讶地发现了奈特是谁。©豆瓣', '堀北真希', '平野俊一', 6.6, 16932, 'tt1179301', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2190133835.jpg', 1.7, 11.4, 51.5, 27.2, 8.2, '0.242435,0.114585,-0.855010,0.488689,-0.175716,-0.331283,0.817427,-0.057725,-0.394778,-0.300960,0.201540,0.702132,-0.143480,0.386997,0.049249,0.130120,-0.308695,-0.850033,0.192301,-0.103331,-0.037928,-0.483390,-0.179093,-0.014846,-0.191773,-0.156496,0.468901,0.140342,-0.083180,0.323185,0.238308,0.034315,0.082518,0.769682,0.028459,0.246636,0.094029,0.167094,0.061004,0.113576,0.352101,-0.313873,-0.233112,0.242414,0.172558,0.478959,0.529911,-0.067234,-0.174039,0.292313,0.337675,-0.146704,0.110535,0.252537,0.256378,0.078107,0.061757,0.051333,-0.138379,0.068849,-0.110177,0.298790,-0.502654,0.007522,0.086436,0.310933,-0.622593,0.425583,-0.313905,-0.083770,-0.022802,-0.369129,0.178353,0.378066,0.128834,0.367654,-0.365786,0.063241,-0.298580,0.119093,0.460680,-0.052765,-0.262489,0.398891,-0.310967,-0.537953,0.043503,-0.020495,-0.557270,0.155325,0.423664,0.312840,-0.346329,0.230050,-0.341532,-0.046528,-0.150671,-0.159014,-0.036243,-0.354510,-0.237798,-0.374683,-0.076587,-0.325038,-0.652378,-0.148460,-0.132817,-0.506835,0.578455,-0.933418,0.016155,0.483681,0.312128,-0.415220,0.562528,0.199151,0.029723,0.092358,0.015644,0.381604,-0.106637,0.346438,0.053083,0.259727,0.324193,-0.144067,-0.487641,0.387190', '1301022', '1309080', '1292211', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2976111', '狗狗与我的十个约定', '剧情', '十四岁的少女齐藤明莉（福田麻由子 饰）收养了一只可爱的小狗，在妈妈的建议下她给小狗取名为“索克斯”，并和小狗定下“十个约定”。不久，妈妈去世，而身为医生的爸爸忙于工作，无暇多照顾明莉，“索克斯”便成为明莉最忠实的玩伴。明莉在学校还有个梦想成为演奏家的朋友星进，当明莉因为爸爸工作调动搬家时，“索克斯”便寄养在星进家。可是星进（佐藤祥太 饰）要去国外留学时，爸爸却因为急诊没有按时送他，明莉没能见到星进最后一面。为了弥补对女儿长期以来的亏欠，爸爸决定辞职开起了小诊所，“一家三口”又重新生活在了一起。长大后的明莉开始了忙碌的生活，陪伴“索克斯”和爸爸的时间也越来越少。后来明莉（田中丽奈 饰）又遇见学成归来的星进（加濑亮 饰），两人还成为相爱的恋人。很快，距离初遇索克斯已过去十年，“索克斯”也走到了生命的尽头，这时，明莉又想起了当初与“索克斯”的十个约定……©豆瓣', '田中丽奈', '本木克英', 8.1, 64376, 'tt1179271', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1093145688.jpg', 0.4, 2, 20.8, 45.5, 31.4, '0.302270,-0.074959,-0.579754,0.146568,0.017002,-0.899975,0.623533,0.390159,-0.346932,-0.318876,-0.032515,0.573432,0.101467,0.520603,0.463758,0.025413,-0.403909,-0.582135,0.284160,-0.103054,-0.257526,-0.201677,0.157844,0.118357,-0.083870,-0.417639,0.304830,-0.114850,0.261523,0.515427,0.079635,0.238232,-0.003876,0.242550,-0.143753,0.126307,0.100489,0.122013,-0.213019,0.332899,0.165519,0.155148,-0.032050,-0.187182,0.385016,0.243914,0.641045,-0.078180,-0.201757,-0.289079,0.110446,-0.061991,-0.123527,-0.065877,0.289390,-0.023341,0.324575,0.141114,-0.520634,0.017068,-0.020324,-0.166098,-0.418148,0.140532,-0.138386,-0.030801,-0.867917,0.367142,-0.076233,-0.208006,0.280027,-0.737176,0.182987,0.508838,-0.117884,0.211253,-0.513735,0.077739,-0.380745,0.215856,0.704747,-0.013020,0.273839,0.282023,0.032428,-0.282896,0.111173,-0.094691,-0.336249,0.049304,0.147684,-0.056571,-0.310434,0.210334,-0.499932,-0.024906,-0.611575,-0.211786,0.275549,-0.542977,0.175715,-0.409991,0.197291,-0.204358,-0.287352,0.316847,0.049701,-0.135437,0.650680,-0.813361,0.561449,0.244337,0.459662,-0.266405,0.563314,0.176196,0.009697,-0.605666,0.244060,0.327747,-0.003415,0.498787,0.215006,0.156665,0.246424,-0.120582,-0.457761,0.455172', '1299965', '34869495', '1926007', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2976123', '文雀', '剧情', '祺（任达华 饰）是一名职业扒手，这天出门前，家里飞来一只文雀，放生也不肯走，逗留昏暗屋内。祺与伙伴们午餐时问起自来雀的象征意义，伙伴说这是惹祸上身的前兆。当然，这是玩笑话。祺带着兄弟四人在香港街头偷窃讨生活，四人共骑一辆自行车，歪歪扭扭，别有一番兄弟情趣。祺闲来爱拍摄街头风情，这日一名急匆匆跑过的女子甄珍妮（林熙蕾 饰）吸引了他的目光，他迅速拍下她的倩影。无独有偶，他的另外三位兄弟，先后被同一位风情万种的女子缠绕，这女子总是步伐匆匆，但兄弟四人都着迷于此。直到他们被人狠狠教训。才明白珍妮是富商傅先生（卢海鹏 饰）的情妇，她想从傅先生那里取回自己的护照，过回自由的生活。这四名兄弟，决定为她，冒险一回。不为什么原因。然而傅先生也是江湖老手，一场较量正在开始。©豆瓣', '任达华', '杜琪峰', 6.9, 51179, 'tt0491044', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p648373937.jpg', 1.7, 8.5, 43.6, 36, 10.3, '0.359381,-0.171985,-0.405751,0.427955,-0.007391,-0.165509,0.643267,0.165157,-0.319997,-0.191755,0.466093,0.687494,-0.122271,0.318727,0.457686,0.068447,-0.332635,-0.568011,-0.022975,-0.220287,-0.139908,-0.135463,-0.012864,-0.095495,-0.086571,0.044260,0.334315,-0.078304,-0.003589,0.669473,0.551223,-0.023598,-0.421525,0.393966,-0.424789,0.098674,0.114452,0.134968,-0.110408,-0.090966,0.046714,-0.359256,-0.389766,0.055193,0.046170,0.067376,0.688677,-0.082239,0.061637,-0.162558,-0.070887,-0.034824,0.221098,0.006314,0.104576,-0.065116,0.266032,0.016359,-0.044507,0.004158,-0.056553,0.036646,-0.220084,0.293068,0.027998,0.089841,-0.542775,0.405402,-0.141513,-0.084384,-0.053053,-0.168822,0.225098,0.203495,0.136377,0.078246,0.133445,-0.096653,-0.445693,0.156633,0.688399,0.124625,0.151081,0.370122,-0.168643,-0.282449,0.155114,-0.044168,-0.284830,-0.145352,0.324551,-0.022902,-0.128967,-0.101530,-0.485981,0.075800,-0.118375,0.020909,-0.160004,-0.330293,-0.142021,-0.406080,0.082060,-0.420395,-0.136879,0.261029,-0.095201,0.057560,0.634723,-0.647243,0.073112,0.363160,0.372134,-0.574088,0.772448,-0.080918,0.165569,-0.140718,-0.066377,-0.140292,0.113251,-0.062737,0.183759,0.510324,-0.185156,-0.018246,-0.219943,0.082369', '26687241', '1361252', '30162520', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2977357', '杀人不分左右', '剧情', '克林伍德夫妇（Monica Potter & Tony Goldwyn 饰）携女儿玛丽驱车来到湖畔别墅度假，刚抵达不久，玛丽（Sara Paxton 饰）便开车去找朋友佩姬（Martha MacIsaac 饰）玩。期间她们邂逅碰巧路过此地的青年贾斯汀（Spencer Treat Clark 饰），在男孩的邀请下，玛丽和佩姬一同前往贾斯汀所在的旅馆。在旅馆中，她们遇见贾斯汀的父亲克鲁克（Garret Dillahunt 饰）。克鲁克是一个变态杀人犯，他刚刚被弟弟法兰西（Aaron Paul 饰）和女友莎蒂（Riki Lindhome 饰）从监狱救出。为避免泄漏行踪，他们劫持了玛丽和佩姬开车跑路。途中玛丽试图逃跑，由此引发了一连串的血腥事件……本片荣获2009年布鲁塞尔国际奇幻电影节最佳导演奖。©豆瓣', '加瑞特·迪拉胡特', '丹尼斯·伊利亚迪', 6.6, 16370, 'tt0844708', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2099553797.jpg', 1.4, 8.9, 53.2, 29.3, 7.3, '0.096065,-0.039035,-0.595628,0.410480,0.240758,-0.340272,0.461197,0.118371,-0.391178,-0.389786,0.210406,0.839026,-0.363110,0.163968,0.895690,0.135325,-0.525214,-0.250327,0.235741,-0.265079,-0.510452,-0.238656,-0.094994,-0.205508,0.217176,-0.299416,0.184884,0.035363,-0.275098,0.951964,0.415649,0.535281,-0.826475,0.385537,0.045240,0.275025,0.486878,0.117945,-0.315641,0.435438,-0.090933,-0.495753,-0.001928,-0.243820,0.329679,0.237580,0.680748,-0.012797,0.119407,-0.218412,0.090881,-0.181531,0.117531,-0.099770,0.246451,-0.440562,0.302493,0.156649,-0.222469,-0.105127,0.116570,-0.374374,-0.135235,0.251507,0.135346,-0.070900,-0.703507,-0.130989,-0.276460,-0.068653,0.318562,-0.361207,0.305568,0.319711,0.145264,0.065664,0.305760,0.054870,-0.521303,0.156171,0.629859,-0.106951,0.343465,0.155049,0.016429,-0.262835,0.196484,0.276383,-0.438544,0.101846,0.520231,-0.193463,0.073688,-0.267369,-0.426529,-0.563000,-0.415856,0.061809,0.399633,-0.116223,0.008166,-1.078429,0.374240,-0.099930,0.012821,0.087216,-0.294471,0.069262,0.147160,-0.479518,0.380833,0.593945,0.390103,-0.475122,0.720783,-0.334944,0.457461,-0.213063,0.109202,0.384331,0.316145,0.296921,0.000728,0.283661,-0.216584,-0.258263,-0.411190,0.079096', '2075345', '25833539', '3036464', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2977731', '元年', '喜剧', '故事发生在很久很久以前，乍得（杰克·布莱克 饰）和奥尔（迈克尔·塞拉 饰）是一个原始部落中的猎人。两人因为不遵守部落中的规矩而被驱逐，于是两人互相为伴，踏上了离群的旅程。沿途他们遇见了亚当和夏娃、该隐和亚伯、亚伯拉罕等一系列圣经人物，亲眼见证了一系列圣经故事的发生。最后，他们来到了传说中的罪恶之城索多玛，然而这个地方在他们看来简直宛如天堂，于是也注定了这个地方成为他们旅途的终点……©豆瓣', '杰克·布莱克', '哈罗德·雷米斯', 5.8, 6242, 'tt1045778', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1282980731.jpg', 6.2, 23.6, 48.9, 16.4, 4.8, '0.720171,0.110812,-0.868115,0.551706,0.124335,-0.029321,0.874750,-0.170978,-0.577838,-0.287318,0.111840,1.188970,-0.372067,0.148090,0.596512,0.060532,-0.620718,-0.786187,0.068020,-0.364181,-0.297815,-0.374699,-0.064748,-0.094869,-0.043561,-0.102370,0.643486,0.165125,0.132401,0.496174,0.018528,0.319464,-0.351922,0.366075,-0.286912,0.214962,0.328734,0.030363,-0.178990,0.134307,-0.076489,-0.059038,-0.228829,0.183577,-0.100522,0.186654,0.436531,-0.705555,-0.202350,-0.257154,0.030431,-0.545078,-0.104456,0.175767,0.267200,-0.119124,0.255876,0.612263,0.260423,-0.131242,0.049164,-0.205857,-0.757740,0.103361,-0.074869,0.314623,-0.538808,0.306251,0.126919,-0.188525,0.160080,-0.330822,0.632672,0.344312,0.820220,0.185929,-0.085996,-0.519470,-0.702943,0.034781,0.869870,0.000612,-0.482736,0.307312,-0.005675,-0.687106,-0.327621,0.119923,-0.452160,0.112682,0.322882,0.054231,-0.422033,0.460798,-1.000490,-0.026630,-0.122416,-0.376237,-0.101575,-0.477347,-0.122672,-0.760367,-0.194209,-0.686813,-0.350708,-0.024590,-0.125370,-0.287857,0.494195,-0.685217,0.415191,0.421000,0.180281,-0.372823,0.791704,-0.018549,0.393849,0.009394,0.349717,0.370915,0.138475,0.452630,0.210339,0.276930,0.143541,0.031427,-0.428332,0.724765', '30162520', '3055049', '35161768', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2977870', '哆啦A梦：大雄与绿巨人传', '动画', '大雄在学校的后山捡到一株被人抛弃的树苗，通过哆啦A梦的植物自由化生长叶，树苗一夜之间变成了蹦蹦跳跳的小家伙，大雄为其取名木木。木木聪明伶俐，热爱学习，不仅得到了野比家所有人的喜爱，也成为胖虎、小夫、静香他们的好朋友。某天，小伙伴们去后山玩耍，结果被吸入到外星飞船之中。由于人类对地球生态环境的破坏日趋严重，一群具有高智慧的植物宇宙人决定将地球上的植物劫持，以挽救它们濒临灭绝的命运。然而，失去植物，地球上的氧气将会减少，人类乃至所有动物都将灭亡。大雄他们能否阻止宇宙人的计划？本片根据日本漫画家藤子不二雄的原作改编。©豆瓣', '水田山葵', '渡边步', 7.6, 12361, 'tt1180304', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2190148498.jpg', 1.2, 5.1, 31.2, 37.3, 25.2, '0.198590,0.221259,-0.578529,0.404349,-0.165030,0.038967,0.314384,-0.032705,-0.165252,0.200900,0.011849,0.475957,-0.029088,0.179946,0.121008,0.191881,-0.238619,-0.334714,-0.194663,0.116377,-0.616819,-0.181291,-0.291451,-0.437397,-0.034506,-0.275599,0.861016,0.004719,-0.239361,0.247579,-0.313344,0.186263,-0.211087,0.215056,-0.198557,0.367602,-0.080058,-0.167760,-0.163710,0.175605,-0.461755,0.093381,0.156918,0.023977,-0.073770,-0.169288,0.907352,-0.663926,-0.151555,-0.529239,0.449921,-0.460028,-0.003411,-0.092173,0.622966,-0.063352,-0.092156,-0.018854,-0.050152,0.203180,0.165919,-0.098420,-0.712675,-0.022096,0.095087,0.015415,-0.376786,0.319730,0.547708,0.079565,0.000031,-0.447647,0.148832,0.160148,0.192951,0.335253,-0.172716,-0.119132,-0.437259,-0.070307,0.658895,-0.334065,-0.514884,0.147468,-0.316241,-0.448203,-0.282366,-0.332270,-0.296085,-0.014624,0.284333,0.099402,-0.416894,0.323579,-0.882813,0.054926,-0.039828,-0.457808,0.198307,-0.325729,-0.228272,-0.525502,0.082666,-0.126919,-0.269046,0.005438,0.225774,-0.476661,1.293077,-0.612184,0.114895,0.681527,0.270096,-0.514252,0.428128,-0.581564,-0.044704,-0.287668,-0.248271,0.354627,0.206987,0.476975,0.143338,0.125353,-0.032172,0.161384,-0.477739,0.402157', '4181031', '24284209', '1292444', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2977957', '科洛弗道10号', '科幻', '年轻女子米歇尔（玛丽·伊丽莎白·温斯特德 Mary Elizabeth Winstead 饰）不久前刚和男友发生争吵，她夜晚驾车奔驰在黑暗的公路上，突然遭遇严重车祸昏迷过去。当她再度醒来时，发现自己被绑住手脚，关在一个密闭的空间里。少顷，一个健硕冷峻的男子霍华德（约翰·古德曼 John Goodman 饰）走了进来。军人出身的霍华德声称地球刚刚遭遇可怕的生化危机，地球人几乎灭亡殆尽。他在数年前未雨绸缪修建了这个设备、资源齐全的避难所，只为生存下去。避难所内，除了霍华德、米歇尔外，还有另外一个年轻男子埃米特。米歇尔对霍华德的说辞半信半疑，她坚信自己遭到了变态狂的拘禁。真相究竟为何？威胁无处不在……©豆瓣', '约翰·古德曼', '丹·特拉亨伯格', 6.9, 66751, 'tt1179933', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2310097289.jpg', 1.2, 7.5, 46, 36.6, 8.6, '0.118067,0.294947,-0.862655,0.196106,-0.109712,-0.245465,1.106347,-0.089861,-0.379839,-0.609441,0.406255,0.638775,-0.168316,0.138969,0.303691,0.253801,-0.394909,-0.449438,-0.125217,-0.116013,-0.689366,-0.271768,-0.382804,-0.384565,0.118672,-0.334687,0.391409,0.109393,-0.210258,0.198344,0.066223,0.329185,-0.097345,0.496966,-0.122680,0.257588,0.317785,-0.317864,-0.104214,0.095263,-0.223386,-0.237309,-0.056226,0.038854,-0.172620,0.467187,0.463406,-0.210454,-0.117305,-0.049734,0.233200,-0.150587,-0.086806,0.155713,0.470821,-0.137321,-0.050571,0.122663,-0.131567,-0.032403,-0.042900,-0.059396,-0.377568,0.165224,-0.247573,0.186847,-0.307283,0.445313,-0.207296,0.234098,0.041691,-0.225365,0.083165,0.178762,0.235753,0.295930,-0.038606,0.226776,-0.511240,-0.169045,0.508010,0.064466,-0.342923,0.320909,-0.291347,-0.333134,-0.155039,-0.098760,-0.436669,-0.144898,0.453888,-0.106061,-0.123619,0.223163,-0.337224,0.136479,-0.294050,0.048516,-0.132532,0.120884,-0.582474,-0.406758,-0.026186,-0.146531,-0.221367,0.205188,-0.278166,-0.007648,0.395782,-0.349188,0.239951,0.476330,0.187783,-0.404725,0.352780,-0.029680,0.294178,-0.041651,-0.048123,0.594071,0.194358,0.418340,0.102837,0.357708,-0.177714,0.056199,-0.417991,0.451943', '20451118', '3011051', '1316693', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2978211', '美丽', '剧情', '少女恩英（车秀妍 饰）即使闲坐在咖啡厅里，也会因为美貌而被人当成明星追捧。数不清的路人找借口搭讪以及无数求爱电话对她来说更是日常生活中的家常便饭。闺蜜的男友的居然向她展开狂热的追求，虽然她再三拒绝，但是最终还是遭到闺蜜的误会。她感觉远处总有一个人在跟踪他，不过对此她也并没有多在意，岂料，这个疯狂的追求者居然闯进她家来并且对她施暴，并且声称是恩英的美丽毁灭了他。美貌到底是上天赐于她的幸运还是魔鬼惩治她的手段，恩英对此产生了疑问。在一番思索之后，恩英开始了一连串疯狂的行为……本片由金基德一手栽培的韩国新锐导演金宰洪执导，该片是他的长片处女作。©豆瓣', '车秀妍', '全宰洪', 6.3, 6410, 'tt1173686', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2166629788.jpg', 4.2, 14.7, 50.9, 24, 6.1, '0.297978,-0.004197,-0.879043,0.780694,-0.334022,-0.024835,0.961399,-0.087326,-0.566055,-0.134781,0.354319,0.684966,-0.271602,0.130780,0.221530,0.070154,-0.163470,-0.656176,-0.020073,-0.096520,-0.091442,-0.367771,-0.449601,-0.234856,-0.092829,-0.152490,0.335507,-0.005315,-0.461069,0.270737,0.545961,0.324985,0.195447,0.833720,0.008251,0.188200,0.101824,0.132245,-0.027371,0.229570,0.033716,-0.560818,-0.238821,0.489510,-0.256729,0.576926,0.588369,-0.290752,-0.290255,0.010793,0.405532,-0.554635,0.063441,0.253604,0.290026,0.101549,0.472210,-0.005562,-0.148019,0.078574,0.133198,0.026368,-0.800627,0.070295,0.190439,0.005515,-0.551109,0.458662,0.005790,-0.158373,-0.082324,-0.307637,0.119770,-0.206144,0.205279,0.278575,-0.225968,0.048922,-0.276669,0.215267,0.649230,0.295244,-0.125097,0.436571,-0.380737,-0.386255,-0.031225,-0.217186,-0.588293,-0.074782,0.164707,0.047768,-0.306189,0.091253,-0.409632,0.007130,-0.218088,-0.112081,-0.119805,-0.519083,0.027925,-0.466515,-0.097774,-0.442996,-0.451837,-0.020838,0.093700,-0.237266,0.876549,-0.891874,0.109736,0.701071,0.366955,-0.753927,0.703166,0.239277,-0.324218,0.019210,-0.304236,0.250205,-0.098208,0.077471,0.030635,0.324121,0.214460,-0.302350,-0.231424,0.446869', '1308206', '25932086', '1301022', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2978639', '滑轮女孩', '剧情', '在德州名叫伯顿的普通小镇里，生活着一个并不开心的少女布里丝·卡文德（艾伦·佩姬 Ellen Page 饰）。她迷恋摇滚乐，对人生有着别样的憧憬，但却常被母亲布鲁克（玛西亚·盖·哈登 Marcia Gay Harden 饰）打扮成乖乖女，参加镇上举行的各种选美比赛，这令她倍感乏味。某个夜晚，布里丝和好友佩希（阿莉雅·肖卡特 Alia Shawkat 饰）去临镇奥斯汀观看了全由女子参加的轮滑对抗赛，女孩们的飒爽英姿和出色表现令布里丝倾倒，于是她决定学习轮滑。布里丝瞒着父母，偷偷加入奥斯汀的胡安童子军轮滑队，在紧张激烈的训练和对抗中，布里丝结识了不少好朋友，同时也找到久违的乐趣……©豆瓣', '艾利奥特·佩吉', '德鲁·巴里摩尔', 7.3, 15924, 'tt1172233', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p455257390.jpg', 0.3, 3.2, 39.1, 45.6, 11.8, '0.344887,-0.136117,-0.435485,0.582102,-0.025618,-0.353636,0.607646,0.152285,-0.551097,-0.336498,-0.014138,0.717035,-0.256885,0.357729,0.256284,0.019465,-0.452127,-0.594850,-0.087082,0.057774,-0.117936,-0.348250,-0.132889,-0.396127,-0.148974,-0.562218,0.258879,0.057966,-0.173488,0.968336,0.456870,0.238638,0.154325,0.472375,-0.058773,-0.191030,0.261222,-0.012996,-0.038035,0.245703,0.010333,0.356357,-0.382237,0.144722,0.507968,0.251501,0.714209,-0.153287,0.320257,-0.048408,0.123162,0.001470,0.271081,0.203484,0.053372,0.141887,0.140088,-0.028463,-0.065566,0.239916,0.212693,-0.270946,-0.337434,0.223336,0.234904,0.120691,-0.547939,0.633361,-0.132980,-0.177104,0.282225,-0.069077,0.038868,0.181534,0.245209,0.208709,0.192964,0.123040,-0.291340,0.296179,0.700525,0.179707,-0.074125,-0.191374,-0.598073,-0.498519,0.071797,-0.203725,-0.470711,-0.051850,0.364381,-0.164397,0.251657,0.426915,-0.723051,0.068772,-0.209486,-0.144852,-0.128664,-0.425629,0.222167,-0.926117,0.137255,-0.406907,-0.471726,-0.114683,-0.054413,-0.191613,0.560436,-0.995996,0.217347,0.452902,0.045344,-0.011788,0.493875,0.203142,0.171045,-0.197468,-0.457955,0.626414,-0.172330,-0.101247,-0.011898,0.681383,-0.134490,-0.123110,-0.436600,0.699932', '3139191', '26365262', '11541282', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2978752', '蝴蝶梦：梁山伯与祝英台', '爱情', '以动画的手法演绎梁山伯与祝英台的故事。熟悉的经典故事，不一样的表现手法。动画前半段的明媚让梁山伯和祝英台的形象不再只局限于纸张上和想象中，有了实体。可这明媚愈发衬托出后半段的凄凉。让我们跟随动画再重温这个经典凄凉的爱情故事。出身富裕人家的小姐祝英台（刘若英 配音）有着不同于传统女性的想法，争取到了和男生一同上学堂的机会。扮成男装的祝英台在路途上结识了志趣相投的梁山伯（萧亚轩 配音）。二人同起同卧，吟诗作赋，同窗相伴三年。祝英台也在这过程中爱上了梁山伯。二人的相恋却受到了门第观念的阻隔。活着时不能在一起的他们选择了死亡。翩翩起舞的彩蝶是二人渴望自由的化身，而他们终究不再受到束缚，终可以永生相随起舞。©豆瓣', '萧亚轩', '蔡明钦', 7.5, 18375, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2334561250.jpg', 0.9, 4.1, 35.7, 38, 21.3, '0.614155,-0.043446,-0.572572,0.836545,0.137863,-0.440975,0.892293,0.254649,-0.457101,0.033204,0.137699,0.841237,-0.243133,0.217666,-0.001289,-0.204109,-0.432128,-0.700756,-0.062192,-0.070892,-0.024975,-0.353086,0.043371,-0.004345,-0.253286,-0.298446,0.866702,-0.007532,-0.423395,0.725020,0.128052,-0.055746,-0.370921,0.218159,-0.385616,0.112394,-0.056123,0.466335,-0.385397,0.165436,-0.009068,-0.216036,-0.217534,-0.124994,-0.274230,0.158780,0.775657,-0.258299,0.005654,0.276585,0.502017,0.035861,0.068886,0.245417,-0.087328,-0.163746,0.274006,0.243044,-0.121045,-0.095906,-0.083865,-0.183103,-0.879395,0.198293,0.290031,0.301886,-0.530449,0.729320,0.173264,-0.278199,0.162259,-0.204726,0.059784,0.137689,0.495233,0.389652,-0.104628,-0.073489,-0.579121,0.566473,0.865698,0.366543,-0.510484,0.686090,-0.499304,-0.434349,-0.293474,-0.356900,-0.427383,-0.120032,0.320179,0.078299,-0.233297,0.269180,-0.876196,0.023080,0.166884,0.184492,-0.143563,-0.469632,0.093536,-0.563438,-0.290628,-0.838588,-0.428686,0.071197,0.351764,-0.474231,1.007161,-0.921665,0.112786,0.439650,0.240529,-0.348219,0.980590,0.277406,0.190301,-0.013612,0.005694,0.096971,-0.260438,0.077560,0.289037,0.496946,-0.086123,0.088210,-0.769703,0.680382', '2053515', '26283288', '30162520', '1303542');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2978773', '呼啸山庄', '剧情', '故事发生在名为“呼啸山庄”的别墅之中，希斯克利夫（詹姆斯·豪森 James Howson 饰）是山庄主人收养的孤儿，在那里，他遇见了养父的女儿凯瑟琳（卡雅·斯考达里奥 Kaya Scodelario 饰），随着时间的推移，真挚而又纯洁的感情在希斯克利夫和凯瑟琳之间产生了。可是，最终，凯瑟琳选择嫁给了多金的农场主林顿（詹姆斯·诺斯科特 James Northcote 饰），伤透了心的希斯克利夫选择了离开。希斯克利夫这一走就是多年的了无音信，当他再次出现在凯瑟琳面前时，已然可以用“功成名就”一词来形容了。林顿的妹妹伊莎贝拉（妮可拉·布利 Nichola Burley 饰）深深地爱上了希斯克利夫，而希斯克利夫也似乎对她情有独钟，可是，希斯克利夫真的已经忘却了曾经遭到的背叛了吗？©豆瓣', '卡雅·斯考达里奥', '安德里亚·阿诺德', 6.7, 10101, 'tt1181614', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1716967110.jpg', 3.2, 13.4, 41.8, 30.4, 11.2, '0.183739,0.150597,-0.686656,0.590704,-0.012931,-0.699290,0.788825,0.100486,-0.314615,-0.089658,-0.075796,0.722219,-0.263508,0.174386,0.292790,0.526363,-0.251361,-0.732677,-0.148893,-0.373277,-0.478664,-0.841236,-0.025013,-0.097102,-0.082350,-0.344781,0.340641,-0.128741,-0.030543,0.308681,0.605710,0.491747,-0.018485,0.462474,0.047460,0.269342,0.206357,0.052836,-0.393802,0.108275,0.292194,-0.001515,-0.120993,0.299462,0.017297,0.355074,0.664134,-0.415020,0.035583,-0.077467,0.232138,-0.206327,0.064382,-0.119381,0.292216,-0.300631,0.039216,0.318980,-0.168482,-0.200631,0.166667,-0.091464,-0.452563,0.008072,0.037977,0.027518,-0.646629,0.466888,-0.118035,-0.172043,-0.022627,-0.352412,0.238903,0.177845,0.119381,0.386422,-0.088240,-0.187514,-0.320919,-0.074229,0.730554,0.061019,-0.504577,0.625591,-0.388779,-0.204460,-0.067257,0.006480,-0.564607,0.134698,0.211614,-0.022264,-0.302604,0.501720,-0.271553,-0.498652,-0.566016,0.058103,0.194134,-0.531567,-0.057417,-0.349253,-0.256894,-0.491464,-0.309300,0.049407,-0.223678,-0.124754,0.504158,-0.990636,0.469915,0.407229,0.371128,-0.205233,0.512437,0.029555,0.057219,0.106759,-0.076709,0.710695,-0.081909,-0.108840,0.606788,0.082775,0.159021,-0.052512,-0.390322,0.729847', '1922691', '3230121', '26340522', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2978951', '我叫刘跃进', '剧情', '在工地上做厨子的民工刘跃进（李易祥 饰）人生的奋斗目标便是在北京赚点钱，回老家开一家小饭馆。有一天，倒霉的刘跃进的包被抢了，包里有四千多块钱，还有一张离婚证，离婚证里有一张六万块钱的欠条。四千块钱是他所有的积累，离婚证里的欠条是他用老婆换来的，那是他彻底改变命运的希望。为了找到自己的包，刘跃进跟踪深夜入室抢劫的小偷拣到一只包。结果第二天便有人找到刘跃进要找丢失的包，声称包里有一只U盘，U盘里有一些东西。自此，刘跃进的身边出现各式各样奇奇怪怪的人，而他们的目标都是为了那只U盘，刘跃进的生活因为这只U盘居然变得精彩起来……此片由作家刘震云的同名小说改编。©豆瓣', '李易祥', '马俪文', 6.4, 19138, 'tt1180323', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p646826671.jpg', 2.5, 12.4, 53.3, 26.9, 5, '0.305722,-0.009260,-0.430848,0.414561,-0.468093,-0.549949,0.889799,-0.052668,-0.053364,-0.252562,-0.082696,0.463749,0.007452,0.264483,-0.025490,-0.024851,-0.100878,-0.506530,-0.222176,-0.383712,-0.266631,-0.296087,-0.451178,-0.427655,-0.132048,0.386278,0.120860,0.286500,-0.175918,0.131346,0.668754,-0.180430,0.202099,0.262251,-0.373153,0.339645,-0.492441,0.277392,0.135279,0.180871,0.273017,-0.388791,-0.020868,-0.096421,0.439001,0.384803,0.697542,0.169684,-0.057347,0.154987,0.402816,-0.049553,-0.343054,-0.210486,0.111840,0.318666,0.084752,-0.416864,-0.524201,0.102466,0.370794,-0.221214,-0.791760,-0.169729,-0.052912,0.116139,-0.617679,-0.000075,-0.151015,0.382542,0.172580,-0.528979,0.427840,0.190608,0.129789,0.388892,0.056884,0.006924,-0.969547,0.581546,0.464373,-0.298471,0.368010,0.038603,-0.251199,-0.400590,0.407146,0.004600,-0.235278,0.008049,0.695116,-0.290593,0.038467,-0.474977,-0.760947,0.179173,-0.013272,-0.313209,0.094538,-0.259199,-0.194109,-0.225782,-0.104842,-0.200299,-0.094696,0.355008,0.136479,-0.501052,0.747896,-0.252804,0.116732,0.270070,0.250405,-0.332170,0.787895,-0.278172,0.167769,0.099334,0.135596,-0.170072,0.357082,0.713701,0.278923,0.225739,-0.003621,-0.226510,-0.023828,0.599099', '1309101', '1293515', '21619567', '30387441');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2979528', '2012世界末日', '动作', '2012年12月21日，在这次史无前例的灾难中，四个素不相识的人踏上了探寻墨西哥古代玛雅神庙的征程，因为据玛雅神庙记载，玛雅人最后的记录时间就是2012年。对于美国宇航局的科学家来讲，也许是洪水暴发，两极交替，对我们来说，那就是世界末日..', '克利夫·德杨', 'Nick Everhart', 4.7, 9656, 'tt1132130', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2337745611.jpg', 36.2, 19.9, 24, 12.9, 7.1, '0.176279,-0.282683,-0.483813,0.482502,0.345124,0.037426,0.620123,-0.746242,-0.870941,-0.123214,0.301821,0.508053,-0.264348,0.201951,0.521020,0.047842,-0.405878,-0.392497,-0.287535,-0.631882,-0.662447,-0.435501,-0.116248,-0.065030,0.101021,-0.625283,0.580578,0.539974,-0.148226,0.406848,-0.124898,0.512357,0.087192,0.137212,-0.259303,-0.286981,-0.149772,0.311710,-0.438158,0.321035,-0.324367,-0.089509,-0.180785,0.251650,-0.340042,0.327395,0.269214,-0.828648,-0.035974,-0.441180,0.531160,-0.428102,-0.557978,-0.053576,0.549703,0.235216,-0.029572,0.676193,0.051616,-0.184675,-0.160278,-0.659499,-0.649202,0.148531,0.009814,0.168903,-0.514455,0.618975,0.254108,-0.066824,-0.036516,-0.028164,0.368187,0.473186,0.540923,0.755527,-0.213846,-0.231381,-0.406349,0.173950,0.619345,0.076056,-0.469800,0.306845,-0.164390,-0.733775,-0.128153,0.029363,-0.302345,0.402781,-0.086233,0.053271,-0.306615,0.505442,-0.681612,0.487601,-0.117816,-0.781848,0.352480,-0.114827,-0.284803,-0.531195,-0.142209,-0.693304,-0.255911,0.186458,0.364106,-0.198949,0.900247,-0.617733,0.500044,0.847324,0.403518,-0.277471,1.034397,-0.056971,-0.348217,-0.665674,0.054788,0.374881,-0.247477,0.458690,-0.270497,0.143319,0.385400,-0.167201,0.111556,0.807338', '3026559', '1437204', '3448362', '1432669');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2980431', '东京残酷警察', '动作', '东京警察株式会社，亦称“东京残酷警察”，这是一个在近未来成立的警察私有化组织，他们的权力甚至凌驾于法律之上，以保护人民生命安全之名，对一切罪犯进行残酷拷问和虐杀。不仅罪犯谈虎色变，连普通市民也噤若寒蝉。公正善良的父亲被杀害，自幼被局长抚养成人的少女留加（椎名英姬 饰）长大后加入东京残酷警察部队，成为一名干练的女警察。彼时一种名为“技师”的变异人种横行世间，他们会从伤口处变出杀人凶器，危害性极大。为了铲除这些怪物，警察部队展开大规模地搜捕和屠杀，甚至普通市民也难以幸免。而留加在追捕幕后黑手的过程中，信念渐渐开始动摇……导演西村喜广，曾担任《循环自杀》、《人肉机器》等影片的特技导演。©豆瓣', '椎名英姬', '西村喜广', 6, 6424, 'tt1183732', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2198150285.jpg', 9.7, 22.3, 37.9, 19.7, 10.4, '-0.049117,0.004563,-0.415893,0.333781,-0.245443,0.205158,0.619038,0.023599,-0.538971,-0.209809,0.431922,0.601653,0.131556,-0.078893,0.250449,-0.298286,-0.227318,-0.647477,-0.260615,-0.058701,-0.160846,-0.232040,-0.196431,-0.498969,-0.046265,-0.274006,0.747690,0.238569,-0.340805,0.229452,0.199388,0.346080,-0.245126,0.154917,-0.015667,-0.353122,0.258476,-0.284879,-0.405210,0.074491,-0.340870,-0.207470,0.004386,0.135830,-0.264936,0.216378,0.535248,-0.393652,-0.248451,-0.603134,0.430007,-0.511870,-0.207359,0.331503,0.466061,0.070730,0.261236,0.314126,0.036267,-0.047318,-0.099482,-0.041889,-0.991791,-0.237323,0.170313,0.158141,-0.346193,0.155856,0.012871,0.113863,-0.049956,-0.045011,0.108900,0.192713,0.249845,0.376817,-0.086996,0.183865,-0.288657,0.160980,0.673761,-0.260683,-0.467948,-0.305324,-0.239600,-0.503960,0.033699,-0.570714,-0.268334,-0.107571,-0.028759,-0.226624,-0.138561,0.332637,-0.603044,-0.037023,-0.320157,-0.083045,-0.037569,-0.156247,-0.156061,-0.563305,0.196527,-0.173644,-0.183569,0.062872,0.245308,-0.267473,0.867651,-0.696121,0.108386,0.449143,0.331022,-0.568648,0.139968,0.117762,0.100397,-0.208501,-0.387554,0.351566,0.475533,0.492898,0.011825,0.076733,-0.127123,-0.083172,0.167147,0.056197', '24284209', '27602116', '26667010', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2980581', '欢迎来到利雷家', '剧情', '女儿的死让洛伊斯（梅丽莎·里奥 Melissa Leo 饰）的精神受到了极大的打击，作为一名母亲，她无法原谅自己的疏忽和失职。面对妻子的崩溃，道格（詹姆斯·甘多菲尼 James Gandolfini 饰）感到十分痛苦却又无能为力，他只能终日徘徊于酒吧与欢场之间，试图暂时忘却现实的残酷。在一家脱衣舞店里，道格遇见了16岁的舞女马洛莉（克里斯汀·斯图尔特 Kristen Stewart 饰），在短暂接触后，他们进行了一笔交易——道格将以每天100美元的价格住进马洛莉的家里，成为她的房客。当丈夫从生活里彻底消失的时候，洛伊斯才感到了危机，十年没有离开过家的她决定出门寻找道格，而当洛伊斯找到道格时，最让她震惊的并非丈夫正在和马洛莉同居，而是马洛莉和他们的女儿异常相似。鬼使神差之下，洛伊斯也住进了马洛莉的家里，一个奇怪的三人家庭诞生了。©豆瓣', '詹姆斯·甘多菲尼', '杰克·斯科特', 7.5, 6091, 'tt1183923', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p658330727.jpg', 0.4, 2.5, 34.7, 48.8, 13.6, '0.333129,-0.019806,-0.663991,0.551315,-0.041984,-0.589476,1.142223,0.214136,-0.341821,-0.518943,-0.080505,0.893416,-0.168495,0.502165,0.542428,0.070660,-0.180667,-0.630110,-0.028856,-0.238973,-0.272392,-0.590447,0.068245,-0.486209,-0.324564,-0.221049,0.376293,0.110600,0.006027,0.340252,0.245469,0.684900,0.201247,0.737307,-0.042259,-0.051568,0.118578,-0.278269,-0.108960,0.288566,0.372365,-0.236607,0.044767,0.525107,0.113689,0.293659,0.835142,-0.492917,0.014828,0.126961,0.462177,-0.329296,0.092124,-0.080426,0.221899,-0.454321,0.058534,-0.142968,-0.269496,-0.097615,0.318433,-0.158028,-0.778663,0.063287,0.083549,-0.115072,-0.699412,0.230427,-0.064743,0.218232,-0.063378,-0.444136,0.248752,0.471852,0.281410,0.360189,-0.514723,0.064184,-0.411058,-0.183075,0.578311,0.125622,-0.140189,0.253411,-0.595813,-0.585891,0.051056,-0.417821,-0.627906,-0.187935,0.308981,0.249920,0.027016,0.194040,-0.537295,-0.357447,-0.506414,-0.413919,0.043507,-0.516518,0.037834,-0.515932,-0.361326,-0.344978,-0.520255,0.132754,-0.070653,-0.404265,0.427920,-0.917309,0.213458,0.587249,0.453716,-0.362702,0.690491,-0.110018,0.343796,-0.021753,0.077015,0.645091,-0.018623,0.154292,0.313458,0.346062,0.078523,0.359172,-0.237397,0.694388', '1309172', '3059036', '14