INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2980609', '女拳霸', '剧情', '将司（阿部宽 饰）是一个来自日本的黑社会头目，在一次与泰国黑帮的交易冲突中，对方容貌妖艳、身手矫捷的女子成员阿欣（Ammara Siripong 饰）引起了他的注意。在此之后，两人开始交往，然而日本和泰国的帮派冲突却逐渐升级。最终，阿欣为了救心上人而背叛了自己的老大。将司迫于无奈逃回日本，阿欣则留在泰国，独自生下女儿阿珊。阿珊从小患有自闭症，但她却有着非凡的能力，她能迅速记下并掌握复杂的格斗动作。数年过后，成年的阿珊（杰佳·亚宁 JeeJa Yanin 饰）俨然成长为一个出色的格斗高手。另一方面，阿欣当年被老大刺伤，如今又患上癌症，生活无法自理。倔强的阿珊决定向泰国帮讨还属于母亲的钱，而她注定要面对无数危险……©豆瓣', '杰佳·亚宁', '普拉奇亚·平克尧', 6.8, 6026, 'tt1183252', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1465033967.jpg', 2, 9.6, 46.4, 30.4, 11.6, '0.149590,0.079548,-0.509845,0.464156,-0.290144,-0.274029,0.532974,0.038244,-0.603540,-0.347993,0.251880,0.745722,0.226498,0.044384,0.082109,-0.227056,0.156598,-0.585409,0.142282,0.035018,-0.268220,-0.378940,-0.332523,-0.219361,-0.246175,-0.198493,0.795033,-0.057013,-0.258186,0.619430,0.317528,0.358960,-0.219969,0.220227,-0.160199,-0.182934,-0.121039,-0.165242,-0.360364,0.430505,0.068775,-0.131404,-0.077825,0.239137,-0.112044,0.455870,0.627008,-0.023756,-0.132151,-0.335814,0.364241,-0.195689,-0.318392,0.169330,0.321245,-0.049155,0.170725,0.197822,-0.194178,-0.095157,-0.035181,0.104637,-0.639841,0.067558,0.383079,0.060366,-0.708849,0.229616,-0.110506,-0.116825,0.025574,-0.061437,0.012762,0.460583,0.204545,0.300487,-0.257153,0.213520,-0.325335,0.104679,0.737441,0.009616,-0.137062,0.165154,-0.190785,-0.405630,0.025417,-0.691337,-0.314683,0.132499,0.128621,0.057072,-0.308658,0.230334,-0.417968,0.079133,-0.268394,0.020845,-0.210827,-0.392103,0.060287,-0.253707,-0.220772,-0.455538,-0.368366,0.101671,0.033889,-0.184758,0.717611,-0.942352,-0.002200,0.508644,0.363032,-0.697141,0.323994,0.209355,0.159985,-0.179852,-0.248867,0.365971,0.086397,0.113555,-0.156932,0.097034,-0.112960,-0.127646,-0.251037,0.211112', '35030151', '30345227', '1877596', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2982823', '河童之夏', '喜剧', '就快放暑假了，小学生上原康一在放学回家的路上捡到一块大石头。他把石头带回了家，没想到用水一洗，里面竟跳出一只小河童来。小河童对他“咕”的叫了一声，于是康一就给它取名为“小咕”。小咕会说人类的语言，几百年来他一直被埋在在地下。康一很快就和小咕成了好朋友，他们一起洗澡，一起吃饭，一起睡觉。而其它家庭成员也接受了小咕，小河童成了上原一家的秘密。一天，小咕提出想回家和伙伴们在一起。康一为了让小咕了解外面的世界，悄悄把它带了出去。小咕发现环境已经面目全非，大吃了一惊，这个不适合就河童生存的地方根本就找不到伙伴。看到小咕难过，康一也不好受。他和小咕一起外出旅行，来到了还保存着河童传说的远野县。两人在美丽的大自然中找到了适合河童生活的地方，小咕愉快地在清澈的河里游了起来，康一也为它高兴。可是，在这里也怎么都找不到其它河童。康一听到村民们说“抓住一只河童能得一千万呢！”，赶忙带着小咕离开了那里。回到家，康一讶异地撞见了一个小报记者。原来那人听说上原家养着一只河童，一定要拍照。小咕的秘密终于被大家知道了。康一的爸爸被公司勒令一定要让河童上电视。为了上原一家，小咕答应参加电视节目。然而在到场嘉宾里，它看到了一个长得很像杀父凶手的人。就在小咕被恐惧包围的时候，电视节目现场发生了意外。它拼命逃到了外面，然而无论跑到哪里都会看到黑压压的人群。为了摆脱让它害怕的人类，小咕爬上了东京塔。夏季的烈日照得它精疲力竭。小咕俯瞰着城市，独自低语道：“哪里都找不到一个安静的地方，这里是人类的窝。我已经不行了。我要去爸爸那里……”', '富泽风斗', '原惠一', 8.7, 76345, 'tt1179773', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1015305516.jpg', 0.1, 0.5, 10.1, 40.5, 48.7, '0.478078,0.112983,-0.835949,0.384780,-0.047174,-0.403804,0.495246,-0.023593,-0.231324,0.048876,-0.203728,0.807797,-0.254280,0.445122,-0.063879,0.332582,-0.444099,-0.488539,-0.235646,-0.283376,-0.629300,-0.266880,-0.111014,-0.180763,-0.108632,0.018430,0.067810,0.074186,0.044405,0.419684,0.187559,-0.206941,-0.126469,0.578710,-0.346625,-0.029412,-0.078185,0.150495,0.101695,0.304857,0.146290,-0.203307,-0.150400,0.181079,0.204467,0.144769,0.470865,-0.143005,-0.115858,0.102640,-0.138462,-0.260246,0.086466,0.057135,0.513539,-0.403941,0.186883,-0.102383,-0.266643,0.027414,0.232257,0.013815,-0.559407,0.149191,-0.046549,0.245324,-0.607329,0.309824,0.253448,-0.004447,0.071041,-0.554080,0.496517,0.150159,0.051571,0.420921,-0.212600,0.068839,-0.604860,0.104029,0.804696,-0.180979,0.079153,0.183233,-0.002414,-0.308928,0.066178,-0.118617,-0.313934,-0.192509,0.327832,0.031483,-0.674578,-0.305425,-0.569780,0.087296,-0.094020,-0.305143,-0.271249,-0.224379,-0.055564,-0.207377,0.198850,-0.175032,-0.141961,0.322543,0.015200,-0.251550,0.646411,-0.607270,0.324948,0.729443,0.567250,-0.239909,0.739378,-0.217455,0.004253,-0.042457,0.152352,-0.287052,0.117153,0.537165,0.622934,0.489794,-0.038283,-0.169366,-0.654580,0.373854', '1296538', '3055049', '1866424', '1926007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2982853', '星球大战：克隆战争', '动作', '银河共和国的克隆军队与分裂联盟的机器人军队交战正炙，尤达大师派极地学徒亚苏卡•谭诺作为阿纳金的学徒加入克里斯多菲斯星战斗。杜库伯爵设计绑架了塔图因星贾霸的幼子，绝地长老院为了获得银河星系外围的通路权，战斗结束后派阿纳金，亚苏卡和机器人R2带领克隆军队前去拯救人质，而欧比-旺•肯诺比则去塔图因星贾霸处商讨联盟事宜。阿纳金一行在泰斯星一处寺院遭遇分裂联盟的机器人军队及西斯武士阿萨基•文翠斯，尽管救回贾霸幼子，却没料到更大的阴谋正等待着他们。本片是唯一一部电脑动画“星战”电影，也是“星战”系列中唯一一部由华纳公司发行的电影。©豆瓣', '马特·兰特尔', 'Dave Filoni', 7.8, 10848, 'tt1185834', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1790901669.jpg', 0.7, 2.5, 26.1, 45.8, 24.8, '-0.078380,0.096633,-0.572847,0.598610,0.310277,-0.029308,0.280579,0.228719,-0.186252,-0.442569,0.482754,0.713994,0.190639,-0.198323,0.255281,-0.149568,-0.538216,-0.105857,-0.362728,-0.091481,-0.126923,-0.348250,-0.107272,-0.198778,0.009222,-0.697558,1.128107,0.002796,-0.299962,0.091551,0.076391,0.468519,-0.361560,-0.001515,0.348670,0.009509,0.561088,-0.446158,-0.488669,0.369501,-0.398511,0.457979,-0.302614,0.135541,0.006342,0.413783,0.469041,-0.318934,0.539633,-0.462033,0.061434,-0.323104,0.063327,-0.424712,0.616506,0.000868,-0.130802,0.242418,0.238045,-0.049794,-0.197145,-0.262478,-1.062849,0.104031,0.239861,0.146652,-0.338722,0.292375,-0.419120,0.040602,0.168929,0.022547,0.243133,0.814504,0.362304,0.159100,-0.076559,0.019509,-0.643353,0.315103,0.407242,-0.059820,-0.289788,-0.062458,0.258214,-0.682184,-0.084905,-0.470505,-0.170539,-0.090346,0.463096,-0.390249,0.270483,0.546971,-0.768459,0.143720,-0.449833,-0.497376,0.473227,-0.174540,0.357300,-1.075043,0.164547,0.221949,0.025940,0.146227,0.161050,0.074897,0.705298,-0.567939,0.106530,0.499558,0.524363,-0.378094,0.645714,-0.195858,0.161668,-0.340344,0.053678,0.200251,0.320978,0.516640,0.327763,0.049463,0.221308,-0.387614,-0.245682,-0.064045', '2369613', '3861846', '27073234', '1305096');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2983135', '感染列岛', '剧情', '2010年秋，世卫组织官员小林荣子（檀丽 Rei Dan 饰）随队前往菲律宾扑灭禽流感，疫情很快得以控制，但仍有感染者私自离开疫区……次年，东京都的某家市立医院，医生松冈刚（妻夫木聪 Satoshi Tsumabuki 饰）收治的一名高烧病人入院后情况急转直下，咳血而死，病人家属与部分医生亦因感染而病倒。同时，近郊一家养 鸡场内检测出禽流感病毒，场主神苍及女儿（池肋千鹤 Chizuru Ikewaki 饰）的平静生活被打破。小林荣子受命至此指导防疫，旧相识松冈担任其助手。疫情迅速扩散，一月之内病亡人数达到两千，各地出现恐慌，引发国际关注，政府迅速将疫区封锁。松冈偶然之下得知病毒源头可能另有所在，国外传回的检测结果支持了他的判断，松冈决定远赴国外查找病源。在空前的疫情中，松冈、小林以及神苍每个人都将面临自己选择的考验。©豆瓣', '妻夫木聪', '濑濑敬久', 6.4, 6869, 'tt1185654', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p739812900.jpg', 2.5, 14.1, 51.9, 23.8, 7.7, '-0.067599,-0.077957,-0.392477,0.093373,0.144067,0.212956,0.193028,0.164065,-0.738514,-0.267284,0.318516,0.347409,0.013523,-0.035082,0.179410,-0.352807,-0.124232,-0.431715,-0.005169,-0.039703,-0.492685,-0.165527,-0.338177,-0.337553,-0.049812,-0.427819,0.417585,0.271890,-0.019086,0.577936,-0.130950,0.553489,-0.315783,0.511226,0.273881,-0.067975,0.171671,-0.289535,-0.315872,0.589668,0.014300,-0.286767,-0.022264,-0.183916,0.189873,0.551069,0.648600,0.072072,-0.278061,-0.372266,0.532672,-0.164842,-0.105803,0.268153,0.604238,0.421355,-0.010048,0.164630,-0.548734,0.010747,-0.241398,0.180747,-0.211926,-0.189925,0.307160,0.360841,-0.079401,0.106143,-0.110043,-0.036263,0.035276,-0.187833,0.005334,0.585530,0.105948,0.193212,-0.257628,0.066054,-0.176897,-0.052082,0.364592,-0.488884,-0.379514,-0.140057,-0.186457,-0.624172,0.150470,-0.182167,0.002803,0.178342,-0.088934,0.279106,-0.232328,0.198813,-0.047090,-0.052976,-0.442288,-0.365394,-0.195128,0.191693,0.074063,-0.941382,0.156634,0.246457,-0.189017,-0.114841,0.231454,-0.149592,0.526167,-0.421235,0.062245,0.393933,0.267312,-0.549419,-0.072264,0.027142,0.293951,-0.154172,-0.019956,0.278600,0.167720,0.809343,-0.097139,0.176772,-0.190069,-0.066659,-0.188006,-0.009739', '2369613', '1306809', '3871833', '26788667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2988103', '欢迎来北方', '喜剧', '菲利普（凯德·麦拉德 Kad Merad 饰）在法国南部普罗旺斯的一家邮局任职了十多年，一成不变的生活和闷闷不乐的妻子朱莉（Zoé Félix 饰）令他感到压抑。为了讨妻子欢心，菲利普装扮成残疾人申请升职到南部的黄金海岸地区，却不料弄巧成拙被调派到了极北的小城贝尔格（Bergues）担任局长。在南方人眼里，那里气候寒冷恶劣，人民粗俗不堪，说话还带着难懂的Ch''ti口音，是堪比地狱的地方。心灰意冷的菲利普辞别家人，忐忑不安的独自赴任。然而出乎意料的是，他发现自己的新下属们和当地的居民都很热情好客，自己也很快与邮递员安东尼（丹尼·伯恩 Dany Boon 饰）交上了朋友。菲利普逐渐爱上了这处淳朴简单的小城，但当他试图说服朱莉一同来到北方生活，却遭到了妻子的质疑……本片曾获2008年欧洲电影奖及2009年法国恺撒奖提名。©豆瓣', '凯德·麦拉德', '丹尼·伯恩', 8.2, 29882, 'tt1064932', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2557468422.jpg', 0.2, 1, 19.1, 50.4, 29.3, '0.324901,-0.085162,-0.716828,0.588134,0.052725,-0.194054,0.535396,0.342641,-0.743312,-0.214903,-0.062658,0.871538,-0.031623,0.222739,0.341699,0.228037,-0.374660,-0.453172,-0.044928,-0.125741,-0.063470,-0.402940,-0.328200,-0.265061,-0.230093,-0.410023,0.349864,0.114582,-0.067164,0.645133,0.168604,0.309356,0.021504,0.466104,-0.361937,-0.044449,0.287689,-0.012259,-0.332892,0.117736,-0.071510,-0.168940,-0.308301,0.190831,0.165465,0.580597,0.356346,0.185349,-0.122623,0.027055,0.254864,-0.266272,0.025223,-0.033242,0.244053,-0.236183,0.035620,0.206065,-0.267610,-0.008132,0.009401,-0.189426,-0.414014,0.358542,0.153826,0.055557,-0.561266,0.518204,-0.017606,-0.028801,-0.057369,-0.475017,0.229759,0.219265,-0.127041,0.542645,-0.012195,0.125935,-0.383390,0.314420,0.821479,0.020801,-0.333936,-0.005842,-0.360723,-0.453964,0.345859,-0.348209,-0.740413,-0.024839,0.055428,0.037170,-0.062338,0.149140,-0.586201,0.052622,-0.275782,-0.237035,0.188227,-0.278368,-0.065962,-0.649303,-0.143657,-0.514041,-0.183931,-0.096252,-0.044903,0.046389,0.523954,-0.677040,0.276224,0.475632,0.438129,-0.470705,0.599520,0.172717,0.050712,-0.066266,-0.065476,0.413142,0.054944,0.284610,0.215292,0.120630,-0.238920,-0.333309,-0.211002,0.473616', '25721544', '34461680', '1303333', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2988294', '蝙蝠侠：哥谭骑士', '动作', '蝙蝠侠到底是什么样的？本片通过6个相互关联又独立成篇的短片，为观众带来一个真正的蝙蝠侠。《轮到我了》：4个儿童用吹牛的方法描述心中的蝙蝠侠形象，但这时伤痕累累的蝙蝠侠突然出现在他们面前。《身陷火线》：蝙蝠侠送来一位犯人， 2位探员负责将犯人押解到监狱，不想路上碰到两个黑帮火拼，蝙蝠侠适时出现了。《亲身历行》：蝙蝠侠有了新装备——卢修•福克斯为蝙蝠侠设计了一个防弹衣。这本该完美的设计，却给蝙蝠侠带来了苦恼。《不见天日》：某宗教主教被绑架，幕后主使是蝙蝠侠的老对手稻草人。于是蝙蝠侠潜入下水道，与蜥蜴人、稻草人展开决斗。《克服伤痛》：下水道的战斗令蝙蝠侠陷入伤痛与回忆之中，曾经一个印度女人教授布鲁斯•韦恩如何克服痛觉，现在，蝙蝠侠要自己去面对这一切。《亡灵射手》：传奇杀手Deadshot受雇来到高潭市，蝙蝠侠再次出击。©豆瓣', '凯文·康瑞', '西见祥示郎', 7.5, 6777, 'tt1117563', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1061410222.jpg', 0.9, 3.8, 33.2, 44.1, 18, '0.205087,-0.118099,-0.235437,0.435597,-0.004852,-0.252137,0.886727,-0.258597,-0.296231,-0.703365,0.520708,0.844649,-0.180266,0.096121,0.122614,-0.184601,-0.413450,-0.630429,-0.085658,-0.038359,-0.404510,-0.236800,-0.393826,-0.192858,0.182763,-0.043347,0.626038,-0.016206,-0.192623,0.112157,0.474975,0.480423,-0.256812,0.244555,-0.114048,0.005410,0.269303,-0.388283,-0.293882,0.377953,-0.022939,-0.094034,0.104272,0.195616,-0.387885,0.172375,0.757847,-0.425874,-0.139018,-0.104078,0.425754,-0.362122,-0.009633,0.151226,0.173665,-0.016091,-0.122265,-0.051737,0.176908,0.058069,-0.002078,-0.081131,-1.002853,-0.190100,-0.055331,0.216263,-0.293439,0.033231,-0.119606,0.113981,0.169758,-0.176743,0.093512,-0.006192,0.708556,0.252820,-0.142383,0.017872,-0.421150,0.018555,0.666392,0.061556,-0.189574,0.044534,-0.083507,-0.355061,-0.005148,-0.157113,-0.265434,0.148743,0.297388,-0.148621,-0.121005,0.325007,-0.675877,-0.083582,-0.260035,0.036510,-0.238327,-0.286338,-0.200533,-0.554507,-0.296630,0.044199,0.009717,-0.116331,0.010584,-0.184633,0.482925,-0.650471,0.034953,0.588009,0.059251,-0.332481,0.391497,0.135470,0.067604,-0.239461,0.000726,0.103133,0.315145,0.317246,0.032325,0.183749,-0.096073,-0.078145,-0.304380,0.193334', '25828589', '26678784', '25774050', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2988506', '庇护所', '悬疑', '精神病学家卡拉（朱丽安·摩尔 Julianne Moore 饰）不相信存在多重人格症，她父亲（杰弗里·迪马恩 Jeffrey DeMunn 饰）却让她诊断一个多重人格的奇怪病例。病人大卫（乔纳森·莱斯·梅耶斯 Jonathan Rhys Meyers 饰）性格温和，但在接到电话后瞬间就变为个性彪悍的亚当。百思不得其解的卡拉驱车前往人格大卫的故居，得知真正的大卫多年前就已然死于一起诡异的谋杀。卡拉急迫地想找出亚当与大卫的关联，却同时发现自己的同事离奇死亡，尸体背上也出现了与亚当/大卫背上相似的十字架。看似简单的医学病例瞬间被笼罩上了灵异世界的阴影，就连卡拉的父亲都难逃诅咒。这其中的真相究竟是什么呢？©豆瓣', '乔纳森·莱斯·梅耶斯', '曼斯·马林德', 6.4, 5962, 'tt1179069', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p644389271.jpg', 2.3, 12.7, 54, 25.4, 5.6, '0.447096,0.085287,-0.653513,0.425188,-0.041169,-0.199144,0.803648,0.124094,-0.544696,-0.294389,0.304862,0.842784,-0.240400,0.156595,0.221550,0.377023,-0.367148,-0.683526,-0.106301,-0.042327,-0.558830,-0.694886,-0.566330,-0.290465,0.195772,-0.407598,0.124654,-0.039787,-0.037372,0.387300,0.252509,0.692880,-0.252290,0.321560,0.129217,0.093158,0.213411,0.009554,-0.169559,-0.082695,0.306632,0.026166,0.195243,0.278562,-0.102356,0.403426,0.266451,-0.172977,-0.218920,-0.026936,0.404700,-0.034850,-0.152612,0.136884,0.257299,-0.007353,0.271097,0.352319,-0.153649,-0.159076,0.042677,0.259013,-0.872741,0.238360,0.039776,0.498055,-0.314246,0.280139,-0.341043,-0.258515,-0.148234,-0.221045,0.229037,0.161747,0.333553,0.406397,0.004410,-0.102844,-0.304462,-0.174828,0.309274,0.094193,-0.559865,0.139722,-0.350521,-0.422103,-0.138367,-0.016806,-0.238701,0.095412,0.268574,0.131544,-0.275558,0.318333,-0.349904,-0.125336,-0.514117,0.129764,-0.147317,-0.048219,-0.200249,-0.262956,-0.195665,-0.178329,-0.467545,-0.130046,0.063650,-0.047930,0.466725,-0.573192,0.540299,0.331966,0.110507,-0.084566,0.390121,0.006306,-0.124286,-0.098565,0.092088,0.472746,0.198551,0.055157,0.080138,0.386462,0.227465,-0.248056,-0.308440,0.623619', '3569911', '1293145', '3006892', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2988893', '鬼肢解', '惊悚', '人的身体究竟有着怎样的构成？难道仅仅是血肉和骨骼这样的平凡和简单吗？最经，崇（亚瑞克·阿莫苏帕西瑞 Arak Amornsupasiri 饰）经常被一个可怕的梦魇所纠缠着。在梦里，一个女人被痛苦的肢解成零碎的小块后被冲入厕所。可怕的是，随着时间的流逝，梦境变得越来越真实 和清晰，而被肢解的痕迹与痛感也渐渐的在崇的身上得到了体现，梦境和现实逐渐混淆。在寻求心理医生的帮助无果后，崇察觉到或许梦境正是梦中的女人所为，她在向自己寻求帮助。为了从痛苦中解脱也为了找到真相，崇开始了漫漫寻凶路。凶手是真的存在吗？亦或只是崇神经错落后产生的臆想？目前，一切的答案尚在迷雾之中。©豆瓣', '亚瑞克·阿莫苏帕西瑞', 'Paween Purikitpanya', 6.8, 7405, 'tt1160315', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1074951312.jpg', 1.8, 8.9, 46.2, 32.2, 10.9, '0.254217,0.184720,-0.683214,0.659276,-0.177948,-0.026566,0.989858,-0.009332,-0.551400,-0.522936,-0.176050,0.770084,-0.168223,0.152440,-0.072578,0.064146,-0.149069,-0.928362,-0.361994,-0.150752,-0.684650,-0.636128,-0.256021,-0.178440,0.102808,-0.428413,0.794133,0.477786,-0.357618,0.160686,0.172142,0.487271,-0.255753,0.741362,-0.208543,-0.100863,-0.214635,0.332164,-0.247235,-0.059793,0.486624,-0.612181,0.130926,0.319185,-0.484353,0.193479,1.028965,-0.685275,-0.146404,0.230098,0.305148,-0.367013,0.047818,0.090757,-0.063409,-0.082230,0.216070,0.129105,-0.297513,0.116043,0.087968,0.034616,-1.107996,-0.114239,0.193650,0.074528,-0.455952,0.289934,0.192348,-0.179536,0.262056,-0.282081,0.363148,0.501327,0.469766,0.473284,-0.555770,-0.255459,-0.579680,-0.051154,0.688417,0.194618,-0.652108,0.599968,-0.384198,-0.290279,-0.348803,-0.152862,-0.139614,-0.009520,0.308687,0.449188,-0.463431,0.441500,-0.613002,-0.016328,-0.157493,-0.281496,-0.199339,-0.450047,-0.429105,-0.243226,-0.474804,-0.166672,-0.027434,-0.313281,-0.038874,-0.658092,0.388171,-0.894419,0.540630,0.656611,0.253584,-0.487972,0.396867,-0.075767,-0.041810,-0.137067,-0.049007,0.441938,0.375485,0.221247,0.293228,0.290978,-0.203687,0.303975,-0.746318,0.622883', '25774050', '2988294', '26759819', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2990737', '人生访客', '剧情', 'Walter（理查·詹金斯 Richard Jenkins 饰）的生活一成不变，20多年来教同一门课程，与别人一起合著自己没有出过半分力的书，请私人教师学钢琴又难以与人相处。生活沉闷如一潭死水。直到与他合著出书的shelly待产而无法前去参加学术年会换成Walter出席，他的生命才赢来转变。由于妻子去世而极少去纽约的Walter一回到纽约的家赫然发现家里有两个陌生人！误会过后才明白这对小情侣是被人所骗才租了这间屋子。Walter让他们留下，Tarek是来自叙利亚的热情的小伙子，热爱打鼓，他的女友则是来自塞内加尔的黑人。Walter被Tarek的开朗所打动，跟他学打鼓，还跟着他去公园参加少数族裔的打鼓练习。这天Walter与Tarek练习过后赶着回家，过地铁时因为要过鼓Tarek错过了最好的过关卡的机会，从关卡上跳过时被警察逮捕拘留。Walter这才知道他们是非法移民，他为他聘请律师东奔西跑，毫无进展之际Tarek的母亲Mouna（西亚姆·阿巴斯 Hiyam Abbas 饰）因为担心儿子而上门，Walter安抚这位母亲焦急的情绪，带她去纽约四处散心，二人产生一种互相懂得理解的情愫。Walter从学校请了长假，决定留在纽约，去做他认为真正有意义且值得去做的事。', '理查德·詹金斯', '汤姆·麦卡锡', 7.9, 10520, 'tt0857191', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1216528285.jpg', 0.2, 1.3, 21.3, 56.5, 20.7, '0.236602,-0.293353,-0.777509,0.405148,-0.119125,-0.323808,0.775103,-0.000634,-0.528970,-0.405314,-0.050890,0.760672,-0.019002,0.284383,0.196967,-0.140903,-0.350527,-0.518925,0.153537,-0.251635,-0.232016,-0.336748,0.202618,-0.173000,-0.079693,-0.224042,0.242924,-0.040799,-0.232235,0.555938,0.198521,0.252663,0.024255,0.557214,-0.085554,-0.147980,-0.119306,0.205731,-0.294294,0.124968,0.188578,-0.110270,-0.304556,-0.002721,0.244527,0.364104,0.527536,0.054983,-0.140859,-0.005499,0.227177,-0.130185,-0.107258,0.182205,0.237584,0.174369,0.049612,0.191661,-0.179775,0.179460,-0.042685,-0.225103,-0.624100,0.155282,0.120609,-0.052218,-0.705564,0.448883,0.010855,-0.372046,-0.089129,-0.463795,0.423853,0.463529,0.120226,0.354202,-0.093138,0.084994,-0.405615,0.163483,0.877972,-0.025012,-0.024834,0.297532,-0.209511,-0.313969,0.324514,-0.347967,-0.353201,0.014398,0.017149,0.015700,-0.290944,-0.157094,-0.367545,-0.148579,-0.130251,-0.352445,-0.026327,-0.620043,0.005040,-0.495215,0.042381,-0.313055,-0.244200,0.158324,0.127119,-0.270160,0.558129,-0.947790,0.374434,0.587175,0.424785,-0.691734,0.914349,0.106205,-0.036601,-0.217212,0.008008,0.084172,-0.006598,0.386213,0.103158,0.243153,0.090278,-0.022425,-0.274854,0.184802', '1302384', '1308755', '3055049', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2992042', '再见古惑仔', '动作', '黑道刀手阿钉（陈小春 饰）入狱八年终于刑满释放，对帮派生涯感到厌倦的阿钉一心希望顺利照顾大美小美两个妹妹考入大学。阿钉和从小玩到大的好友九辉合力经营装修公司，决意彻底退出江湖。然而两个妹妹令阿钉颇为忧心，大美结交到好脾气的混血男友，小美却在校园暴力肆虐的环境中沾染了不良习气。另一方面，在阿钉入狱的多年中，帮派后起之秀约尼放高利贷坏事做尽，大力扩张势力范围，引起社团元老宝叔（王天林 饰）不满，宝叔邀请阿钉出山，以制约约尼的力量，虽然阿钉一口回绝，但约尼方面为免除后患，频频向阿钉发难。九辉被约尼一伙殴打，阿钉两个妹妹也被其掳走，忍无可忍的阿钉决定反击……©豆瓣', '陈小春', '钟少雄', 6.1, 5427, 'tt1185427', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2364828331.jpg', 5, 17.9, 50.2, 18.5, 8.4, '0.107528,0.054114,-0.423328,0.416273,0.077460,-0.255458,0.365836,0.252088,-0.322840,-0.336713,0.115275,0.383987,-0.095409,0.253911,0.298075,-0.584653,0.318052,-0.593789,0.016874,-0.075925,-0.046003,-0.360299,-0.003918,-0.143067,-0.342741,-0.300822,0.507274,-0.013708,-0.109875,0.618696,0.268647,0.279811,-0.256516,0.214944,0.117500,-0.047884,0.155572,-0.119983,-0.586618,-0.033499,-0.097888,-0.115031,-0.073287,-0.038249,0.179792,0.195710,0.606362,0.181922,-0.156851,-0.404724,0.210264,-0.302728,-0.237259,0.134919,0.625086,0.001890,0.251684,0.267329,-0.097324,-0.094708,-0.057514,-0.260745,-0.429782,0.003637,0.369314,-0.235963,-0.519649,0.333009,0.007972,-0.067706,-0.278116,-0.191006,-0.243222,0.333078,0.222015,0.322294,-0.070257,0.615578,-0.277833,-0.137364,0.657184,-0.290365,0.017480,-0.041103,0.014840,0.057131,0.331605,-0.295973,-0.274680,-0.088537,0.180662,-0.380392,-0.074753,0.237156,-0.433708,-0.152411,-0.268205,-0.017339,0.309235,-0.437992,0.093922,-0.434067,-0.381774,-0.038081,-0.069820,0.214667,0.146615,-0.097621,0.666548,-0.736539,-0.071676,0.306970,0.309544,-0.800098,0.452487,0.225500,0.172769,-0.215229,-0.262014,0.068213,0.330370,-0.113720,0.215651,0.204089,-0.169752,-0.285900,-0.229670,-0.231041', '1293265', '3445516', '1482541', '3598221');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2993217', '未来战警', '动作', '近未来，人类工业文明高度发达，一种名为“代理人”的仿生机器人迅速流行。它具有完美的容貌与身体，各项物理功能超群。人们通过特定的装置可以将自己的意识上载到代理人身上，并通过它进行工作、学习和社交。然而正因为容貌的随意性和可塑造性，人类越来越依赖这种科技，犯罪率也随之飙升，有人拥护，有人反对，社会现状并未因科技的进步而有任何好转。汤姆•吉尔（布鲁斯•威利斯 Bruce Willis 饰）是FBI的探员，某晚他受命调查一起代理人谋杀案。正常情况下代理人被损坏其本体很难受到伤害，而这起案件中两名代理人的本体全部遇害身亡。汤姆意识到这里的阴谋，于是和搭档展开连番调查，而这一过程中由代理人组成的虚拟社会也开始受到动摇……©豆瓣', '布鲁斯·威利斯', '乔纳森·莫斯托', 6.8, 33422, 'tt0986263', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2178095791.jpg', 0.7, 6.2, 53.4, 33, 6.6, '0.413683,0.313880,-0.702291,0.663730,-0.019884,0.177140,0.521569,-0.014444,-0.697234,-0.393204,0.047267,0.632470,-0.112685,-0.065280,0.099600,-0.167606,-0.348350,-0.537572,-0.006965,0.114047,-0.519568,-0.613922,-0.249595,-0.306647,-0.453767,-0.533144,0.845956,-0.066752,-0.615269,0.366912,-0.003931,0.366146,-0.083451,0.462459,0.200921,-0.328258,-0.042819,-0.329437,-0.191500,0.416424,0.191048,-0.151306,0.221089,0.310482,-0.248767,0.206704,0.593267,-0.361852,-0.336078,-0.401809,0.600090,-0.061307,-0.073862,0.167344,0.455006,0.247404,-0.023594,0.245246,-0.083315,0.113315,0.010915,-0.029586,-1.046994,-0.223281,0.042538,0.218820,-0.105350,-0.118583,-0.156319,-0.183189,-0.128401,-0.239018,0.057160,0.475962,0.511000,0.181063,-0.332674,0.026153,-0.357109,-0.077512,0.416923,0.066722,-0.899763,0.300998,-0.440842,-0.678275,-0.478564,-0.378834,-0.041246,-0.082562,-0.038135,0.534063,-0.116658,0.382629,-0.743425,0.271428,-0.227112,-0.287382,-0.167944,-0.184651,0.202752,-0.819361,-0.415572,-0.586900,-0.249637,-0.128746,0.137431,-0.467149,0.635694,-0.901734,0.114588,0.583436,0.435738,-0.448745,0.302897,-0.265149,0.278856,-0.405512,-0.398789,0.067264,0.009173,0.377438,-0.186563,0.099979,0.263016,-0.037484,-0.178687,0.310739', '26759819', '1793491', '26759820', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2994851', '血滴子', '动作', '《血滴子》由陈可辛监制、刘伟强执导，取景地包括山西、北京、杭州等地。雍正（刘伟强 饰）在位期间创立杀手组织——血滴子，专执行朝廷秘令，缉杀异己，其暗器专取人首级。在统帅龚额（王羽 饰）指挥下，队长冷（阮经天 饰）率领陈泰（蒲巴甲 饰）、胡图（高天 饰）、穆森（李宇春 饰）、十三（井柏然 饰）、布喀(周一围 饰）等人配合默契从未失手。边境处，天狼（黄晓明 饰）建立牧人帮多次密谋反清，声势日渐壮大深得民心，乾隆(文章 饰）授命血滴子将其擒杀。众人成功擒拿天狼，却在通往刑场的路上遭遇牧人帮埋伏。危急关头，穆森被天狼胁持，而血滴子也生擒了天狼的部下白兰（李梦 饰）。成功脱身的天狼正逃去根据地武关镇，龚额命众人必须取下天狼首级。而另一边，乾隆早希望以火枪、火炮等火器取代冷兵器，任命大内密探海都（余文乐 饰）一路随行，借机将血滴子赶尽杀绝。这一次，双方处境岌岌可危......', '黄晓明', '刘伟强', 4.7, 57348, 'tt1847713', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1791054126.jpg', 20.1, 37.7, 31.9, 5.9, 4.3, '-0.405394,0.096588,-0.562848,0.473628,0.347021,0.203708,-0.097377,0.331443,-0.247474,-0.095622,0.465203,0.063990,0.220647,-0.274341,0.332424,-0.126880,-0.210043,-0.665805,-0.092355,0.056995,-0.321338,0.134243,-0.127468,-0.255046,-0.114627,-0.050988,0.626833,0.158715,0.162303,0.546908,0.219354,0.229784,-0.263796,0.093565,-0.037180,-0.077987,-0.154769,-0.401367,-0.193589,0.089149,-0.475868,-0.287762,-0.454947,-0.150149,0.040744,0.373196,0.462451,-0.409304,0.361829,-0.238960,-0.087843,-0.342373,0.042879,-0.054464,0.362188,0.161639,-0.105749,0.320926,-0.172043,0.088995,-0.064684,0.013104,-0.436646,-0.010280,-0.078453,-0.031257,-0.436159,0.251597,-0.318214,0.321514,0.004677,-0.305927,-0.058323,0.048854,0.107441,-0.146133,-0.023326,-0.099121,-0.280342,0.191191,0.266006,-0.352200,0.286956,-0.389189,0.464043,-0.228900,-0.004169,-0.046930,0.183573,0.033167,0.536115,-0.074459,0.143619,-0.036649,-0.326671,-0.307666,-0.565684,0.216436,0.049505,0.177289,-0.138055,-0.502409,0.036772,-0.055158,-0.254414,0.031028,0.239979,0.394564,0.180624,-0.303326,-0.067357,0.238741,0.118974,-0.450124,0.109954,0.096733,-0.092485,-0.142173,-0.180086,-0.167728,0.352604,0.298243,0.409533,0.166538,-0.309469,-0.354381,-0.099760,-0.098308', '1294011', 