INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2996625', '大婚告急', '剧情', '蕾切尔（金妮弗·古德温 Ginnifer Goodwin 饰）年近三十却依然单身，对于自己的终身大事，这位咋咋呼呼的傻大姐保持着乐观的态度，加上好闺蜜达茜（凯特·哈德森 Kate Hudson 饰）的陪伴，日子过得还算有滋有味。可是，一个“噩耗”的到来让蕾切尔无法继续淡定——达茜即将和男友走入婚姻的殿堂并邀请蕾切尔成为伴娘，而达茜的男友不是别人，正是蕾切尔曾经暗恋过的德克士（科林·伊格斯菲德 Colin Egglesfield 饰）。原来，大学时代的蕾切尔对当时英俊帅气的德克士十分倾慕，可达茜的出现立刻就将德克士的目光吸引了过去，面对好友的横刀夺爱，蕾切尔也只能忍气吞声。现在，当初青涩的三人都已经长大成人，内心的情感早已不复往日的单纯。达茜的婚期将近，蕾切尔绝望的发现，自己已经无法再抑制内心里的蠢蠢欲动。©豆瓣', '金妮弗·古德温', '卢克·格林菲德', 6.4, 8336, 'tt0491152', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p970712797.jpg', 3, 11.9, 52.7, 25.6, 6.8, '0.443278,-0.056963,-0.644627,0.496684,-0.243420,-0.578246,0.966564,0.252341,-0.338341,0.011120,-0.022116,0.364326,-0.250866,0.469762,0.441126,0.183318,-0.371563,-0.744558,-0.015332,-0.598933,0.207418,-0.698277,-0.295467,0.336226,-0.188804,-0.499611,0.582679,-0.336682,0.481427,0.689992,0.243067,0.412889,0.356480,0.597139,0.075732,-0.233705,0.339970,-0.108653,-0.263670,-0.028280,0.096596,0.000570,-0.184504,0.610273,0.353638,0.430586,0.583034,-0.383846,-0.079888,0.146325,0.152745,0.017541,0.004452,0.053700,0.154383,-0.417785,0.390991,0.092845,-0.098588,0.082697,-0.191073,-0.003324,-0.625755,0.423514,-0.041765,-0.022601,-0.682814,0.157611,-0.221939,-0.221453,0.137235,-0.495462,-0.117095,0.468911,0.345553,0.686428,-0.369868,0.408547,-0.395682,-0.104207,0.589123,0.381056,-0.629380,0.699424,-0.412393,-0.173608,0.016551,-0.197788,-0.929702,-0.030782,0.130500,0.166999,0.057195,0.368893,-0.270668,-0.057222,-0.502745,-0.288697,0.279262,-0.445142,-0.425078,-0.492385,-0.429750,-0.584377,-0.505268,-0.259406,-0.030069,-0.197160,0.579407,-0.771498,0.386553,0.245773,0.312339,-0.503765,0.596090,0.247867,0.012120,0.030417,-0.422059,0.660981,-0.185732,0.025869,-0.077840,0.358617,0.059477,-0.190317,-0.299895,0.670621', '2131640', '1292211', '2002744', '3626365');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2996640', '朱莉与朱莉娅', '剧情', '对工作感到灰心沮丧的曼哈顿下城发展公司员工茱莉•鲍威尔（艾美·亚当斯Amy Adams 饰）决定用一年时间实践美国最受欢迎的电视名厨茱莉亚•切尔德（梅丽尔•斯特里普 Meryl Streep 饰）第一本食谱《精通法国烹饪的艺术》中的全部524道菜，并写博客记录每日进展。与此同时，电影平行穿插茱莉亚•切尔德随美国新闻署任职的丈夫保罗•切尔德（斯坦利•塔奇 Stanley Tucci 饰）于1948年来到法国巴黎居住，学习烹饪，并历经十年艰辛出版厚达七百多页的《精通法国烹饪的艺术》过程。茱莉•鲍威尔在模仿茱莉亚•切尔德的历程中终于找到了自我，而随着博客浏览量的增加，就连茱莉亚本人也得知了茱莉的存在，但结果却在茱莉意料之外。©豆瓣', '梅丽尔·斯特里普', '诺拉·艾芙隆', 8.1, 105921, 'tt1135503', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p596884844.jpg', 0.1, 1.2, 21, 50.9, 26.8, '0.212803,-0.264658,-0.273750,0.524478,0.281823,-0.399774,0.213887,0.130443,-0.430936,-0.396833,0.023855,0.529959,-0.268048,-0.103846,0.144451,-0.083140,-0.451382,-0.625150,0.311504,-0.436449,-0.058624,-0.513854,-0.158741,-0.361630,-0.200733,-0.379830,0.398677,-0.025462,-0.092035,0.447708,-0.011036,-0.093250,0.123506,-0.068543,0.238635,0.130623,0.430264,-0.254084,-0.318803,0.200481,0.156566,-0.060843,-0.190895,-0.135472,0.392765,0.312721,0.490845,0.067973,0.072011,0.204102,0.474423,-0.067612,-0.189066,-0.015302,0.231959,0.078022,-0.035656,0.402376,-0.248525,0.186291,-0.124389,-0.288716,-0.677561,-0.171595,0.055391,0.051412,-0.343241,0.277652,-0.249819,-0.014298,-0.138789,-0.475198,-0.275269,0.245123,0.335530,0.483063,0.262725,-0.021443,-0.020620,0.455072,-0.106775,-0.018379,-0.468803,0.426191,-0.086568,-0.447401,-0.106751,-0.256952,-0.308226,-0.038547,-0.010197,0.211487,0.112470,0.339102,-0.697826,0.154002,-0.216034,-0.514079,0.108785,-0.217661,-0.288683,-0.999511,-0.060652,-0.160229,-0.173683,-0.333707,0.134147,-0.385166,0.645185,-0.513126,0.450033,0.208913,0.112972,-0.002408,0.590214,-0.138879,-0.163074,-0.036704,-0.119032,0.643413,0.090561,0.064562,-0.147974,0.278901,0.228970,-0.422776,-0.578340,0.610905', '3318306', '26275494', '34961898', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2996642', '魔鬼山历险记', '科幻', '许多年以来，美国的内华达大沙漠一直是个 "神秘" 的地方，各种各样奇怪的现象层出不穷。有人说，这是因为外星人的飞船曾在巫山（Witch Mountain）降落。杰克（道恩·强森 Dwayne Johnson 饰）是一个拉斯维加斯的普通出租车司机，有一天他在车上发现了一对神秘的兄妹俩。从伸出援手的那一刻开始，他就卷入了一场令人惊心动魄的冒险旅程。原来，这对拥有异能的兄妹来自外星，且还隐藏了不为人知，却足以使整个宇宙毁灭的秘密。兄妹两人必须在现有的时间内找到失踪的太空船，返回外星。这趟旅程是场生与死的追逐，他们必须躲过来自各方的追杀，包括黑道，美国政府以及外星人。时间正式倒数，宇宙毁灭在即。一个攸关全宇宙及人类生死的冒险正在进行……©豆瓣', '道恩·强森', '安迪·菲克曼', 5.7, 11496, 'tt1075417', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1236036566.jpg', 5, 24.6, 55.2, 11.4, 3.8, '0.190303,0.132386,-0.901378,0.563132,-0.010130,0.100297,0.703064,-0.215572,-0.683230,-0.137717,0.316956,0.639338,-0.170940,0.032223,0.325569,0.079460,-0.240594,-0.415884,-0.273129,-0.271940,-0.538608,-0.274257,-0.475917,-0.120621,0.090005,-0.320928,0.495496,0.316944,-0.364906,0.316249,0.188173,0.267934,-0.474848,0.409084,-0.510063,-0.284009,0.055561,0.224531,-0.362238,0.132789,-0.097102,-0.116975,-0.003665,0.079302,-0.292657,0.333302,0.500485,-0.332755,-0.177483,-0.028971,0.268855,-0.430498,-0.331394,-0.273589,0.542180,-0.081764,-0.112477,0.122843,-0.053838,0.129839,0.066828,0.190573,-0.939883,-0.058240,-0.043556,0.094258,-0.431737,0.309183,0.174356,-0.156124,-0.029542,-0.335365,0.316710,0.603355,0.210897,0.214661,0.043330,-0.011332,-0.450372,0.071248,0.940465,-0.244602,-0.362947,0.334318,0.046777,-0.524240,-0.278055,-0.085107,-0.420123,-0.058952,0.358981,-0.029820,-0.243591,0.383880,-0.833286,0.354948,-0.260861,-0.436701,0.135698,-0.404957,-0.117312,-0.777178,-0.053726,-0.441933,-0.223280,0.351012,0.117624,-0.214033,0.767591,-0.704728,0.363921,0.754242,0.133841,-0.405580,0.769686,0.036371,0.154897,-0.337365,0.043311,0.169742,0.020264,0.548453,-0.103869,0.348298,0.151919,0.037411,-0.294260,0.360208', '1308784', '19965431', '1793491', '1294941');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2996790', '林肯律师', '剧情', '故事讲述洛杉矶刑事辩护律师米奇·豪勒（马修·麦康纳 Matthew McConaughey 饰），绰号“林肯律师”，经手的都是些处于社会底层的客户。他善恶分明、正直守信，并非贪财小人。然而这一次，豪勒的辩护对像是年轻富有的房地产开发商路易斯-罗莱特（瑞恩·菲利普 Rya n Phillippe 饰）。罗莱特受到的指控是殴打并企图强奸应招女郎瑞琪（玛格丽塔-莱维瓦 Margarita Levieva 饰），但罗莱特声称自己是无辜的，有人栽赃陷害他。罗莱特的母亲愿意不惜重金证明自己心爱儿子的清白。为了解案情的细节，豪勒及其私人调查员对此案进行了调查。他们最初获得的证据证明罗莱特似乎确实无辜，这个案子能够轻而易举地打赢，豪勒也能够轻松地获得一笔高额的律师费。然而，一个偶然的机会使豪勒发现，此案与他曾经接手的另一桩强奸杀人案有诸多相似之处……©豆瓣', '马修·麦康纳', '布拉德·福尔曼', 7.9, 42603, 'tt1189340', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p846769692.jpg', 0.1, 1, 22.8, 57, 19, '0.315808,0.091500,-0.495132,0.581448,-0.385120,-0.264823,0.552262,0.085258,-0.541056,-0.459994,0.217928,0.442540,-0.080625,-0.024656,0.189372,0.163059,-0.172209,-0.570583,0.084435,-0.139278,-0.135127,-0.931258,-0.217147,-0.584580,-0.189350,-0.097212,0.092539,0.107260,-0.319190,0.200862,0.427728,0.715329,0.232655,0.290110,-0.037832,0.011301,0.131200,0.155295,-0.440211,0.203486,0.039437,-0.126596,-0.143153,0.307822,0.025734,0.773691,0.332967,-0.215154,-0.259733,-0.034839,0.597793,-0.283967,0.314308,0.184474,0.240801,0.164100,0.045643,0.350578,-0.208264,-0.129452,0.241546,-0.124564,-0.928230,-0.384254,0.139485,0.174553,-0.254467,0.165229,-0.246752,0.278546,0.006127,0.014062,-0.040395,0.246207,0.374472,0.277721,0.181676,0.221562,-0.709808,0.195737,0.403642,0.182350,-0.118182,0.242354,-0.499906,-0.597705,0.121855,-0.229558,-0.302754,0.253535,0.478397,-0.194029,0.028530,0.345573,-0.215505,-0.293760,-0.419462,0.139111,-0.072374,-0.270949,0.010407,-0.435581,-0.164448,-0.369206,-0.344154,-0.034942,0.010119,-0.536212,0.409855,-0.590234,0.078509,0.546788,0.229344,-0.528386,0.521824,0.375960,0.105933,-0.337734,-0.420315,0.098897,0.398769,-0.015934,0.025573,-0.113730,0.345338,-0.476182,-0.111130,0.221653', '1296217', '1297689', '25862560',