INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2997052', '吾栖之肤', '剧情', '在位于郊外的华丽别墅内，人过中年的整形医生罗伯特·雷德加（安东尼奥·班德拉斯 Antonio Banderas 饰）和忠心老仆人玛丽莉娅（Marisa Paredes 饰）居住于此。在过去的十二年里，他先后失去了妻子盖儿和女儿诺玛（Ana Mena 饰），一桩桩人间惨剧彻底颠覆了罗伯特看似完美的生活，同时也将他的事业与研究推向了完全未知的领域。在别墅的某个神秘房间内，居住着一个美丽且与世隔绝的女子，她叫薇拉（埃琳娜·安纳亚 Elena Anaya 饰），既是罗伯特的病人，又是他的实验对象，二人有着纷繁错乱的渊源。她经罗伯特之手精心塑造出来的容颜，将彼此紧紧缠绕在了一起……本片荣获2011年华盛顿影评人协会最佳外语片奖。©豆瓣', '安东尼奥·班德拉斯', '佩德罗·阿莫多瓦', 7.6, 129228, 'tt1189073', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1221998208.jpg', 0.4, 2.4, 30.2, 50.9, 16.1, '0.340691,-0.024752,-0.546304,0.566219,-0.159266,-0.057903,0.852074,0.184008,-0.468401,-0.116175,0.375685,0.767210,-0.095012,0.240781,0.282192,0.223950,-0.343700,-0.768025,-0.161236,-0.313843,-0.200187,-0.364499,-0.323404,0.004644,-0.035553,-0.459881,0.427321,-0.162612,0.025927,0.342970,0.225915,0.348217,-0.300453,0.199463,-0.151360,0.161475,0.182502,-0.209722,-0.347009,0.241905,-0.036456,-0.213125,-0.120448,0.204289,-0.032655,0.193307,0.623161,-0.394864,0.092698,0.006687,0.374262,-0.049197,-0.009875,0.167061,0.265878,-0.058609,0.206511,0.272475,-0.416903,0.042743,0.416574,-0.246865,-0.592367,0.081850,0.270339,0.105164,-0.778546,0.690968,-0.025579,-0.122136,-0.097981,-0.291356,0.036364,0.103836,0.078934,0.445817,0.092849,-0.074787,-0.405135,0.327826,0.230527,0.117049,-0.343329,0.272023,-0.338291,-0.446179,-0.245190,-0.163896,-0.555435,-0.238892,0.432310,-0.045719,0.081563,0.296243,-0.575399,-0.051525,-0.334902,-0.128469,0.009266,-0.437279,-0.152397,-0.619158,-0.183745,-0.375506,-0.328598,-0.134637,-0.000941,-0.130032,0.580460,-0.730138,0.260754,0.471130,0.072229,-0.227156,0.705601,-0.056076,0.413974,-0.058818,-0.214979,0.381162,-0.047898,0.417083,0.197052,0.537210,-0.181048,0.123084,-0.550454,0.556199', '26677495', '1307146', '27605105', '1895119');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2997063', '遭遇陌生人', '剧情', '在共同度过了40年平静的婚姻生活后，阿尔菲（安东尼·霍普金斯 Anthony Hopkins 饰）突然决定离开妻子海伦娜（盖玛·琼斯 Gemma Jones 饰），转而投向和自己年龄差距极大的应召女郎查梅尼（露茜·彭奇 Lucy Punch 饰）的怀抱。在巨大的打击之下，海伦的精神开始崩溃，她选择了自我麻醉的手段，将意识和身体全部托付给了一个神神叨叨的算命师，唯命是从。父母的婚变让身为女儿的莎莉（娜奥米·沃茨 Naomi Watts 饰）感到十分的头痛，同时，她和丈夫罗伊（乔什·布洛林 Josh Brolin 饰）的婚姻也出现了问题，莎莉爱上了其他的人。巧的是，同样的情况也出现在了罗伊的身上，并且，对于一个半红不紫的小说作者来说，还能有什么事情要比发现自己的死党拥有着高出自己千百倍的创作天赋更令人沮丧的呢？几乎完全相同的故事发生在了两代人之间，此时此刻，除了直面自己的处境，他们没有更好的选择。', '安东尼·霍普金斯', '伍迪·艾伦', 7.4, 18802, 'tt1182350', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p529809614.jpg', 0.4, 2.9, 37, 47, 12.7, '0.315217,-0.111882,-0.778869,0.773083,-0.048284,-0.279266,0.827186,0.340385,-0.623916,-0.368329,0.174749,0.821937,-0.253622,0.148997,0.137997,-0.002874,-0.303614,-0.806992,-0.075487,-0.130036,-0.522817,-0.756848,-0.237863,-0.300803,-0.193251,-0.603919,0.424854,-0.156891,-0.197985,0.194410,0.402315,0.331993,0.269452,0.598758,-0.104116,0.211901,0.000565,0.065658,-0.141712,0.183208,0.228272,-0.058720,-0.058496,0.413669,-0.075765,0.310303,0.587241,-0.354082,-0.307618,0.063463,0.364989,-0.279495,-0.072299,0.206931,0.246130,-0.161800,0.150099,0.028837,-0.304909,0.066252,0.362779,-0.002802,-0.924313,0.067851,0.247446,0.242793,-0.775001,0.503230,-0.152092,-0.118818,0.244563,-0.332927,0.137575,0.433434,0.130809,0.382654,-0.330403,-0.124016,-0.435325,0.018173,0.605947,0.232587,-0.347467,0.503449,-0.400180,-0.400145,-0.533462,-0.166658,-0.426361,-0.022113,0.264411,0.335422,-0.214478,0.452360,-0.545716,-0.075857,-0.102732,-0.221545,-0.033739,-0.544504,0.040943,-0.284493,-0.287648,-0.690212,-0.575180,-0.004395,-0.041205,-0.372942,0.861624,-0.881707,0.059572,0.481308,0.374111,-0.309009,0.624481,0.102241,0.065575,-0.149598,-0.121920,0.260923,-0.185381,0.127722,0.189356,0.310237,0.054895,0.052951,-0.397038,0.785409', '1783461', '24756472', '4058933', '3006892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2997076', '华尔街之狼', '剧情', '在危机四伏的投资界，掌管史崔顿·奥克蒙公司的乔丹·贝尔福特（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）生活侈靡、实力雄厚。1987年，22岁的乔丹进入罗斯柴尔德公司，从接线员做起，在高级经纪人马克（马修·麦康纳 Matthew McConaughey 饰）指点下，进入了股票经纪人充满毒品和欲望的世界，半年后因“黑色星期一”，乔丹转投靠贩卖“便士股票”的小公司，凭借巧舌如簧获得成功，与邻居唐尼（乔纳·希尔 Jonah Hill 饰）和一班朋友另立门户，游走在灰色地带获利颇丰，获称“华尔街之狼”，然而，FBI已经开始留意他……本片根据前华尔街股票经纪人乔丹·贝尔福特的个人自传《华尔街之狼》改编。©豆瓣', '莱昂纳多·迪卡普里奥', '马丁·斯科塞斯', 8, 374565, 'tt0993846', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2160254162.jpg', 0.5, 2.1, 20.8, 48.3, 28.4, '-0.015006,-0.113159,-0.606567,0.401867,0.019857,-0.398079,0.507729,0.333433,-0.290859,-0.238276,-0.097831,0.829923,-0.525004,0.280731,0.500947,-0.100830,-0.191272,-0.561891,-0.011581,-0.359951,0.331527,-0.474536,-0.467370,-0.444805,-0.158032,-0.390585,0.658205,-0.056285,-0.089416,0.230299,0.188289,0.393562,-0.001889,0.072090,0.133499,0.094852,0.369791,-0.124864,-0.421623,0.264994,-0.063288,-0.021204,0.031928,-0.172581,0.432662,0.383282,0.329078,-0.198123,0.427949,-0.124194,0.327394,0.214677,0.008134,-0.284842,0.471929,-0.074406,0.209212,0.346144,-0.120618,-0.101048,-0.143497,-0.361944,-0.530480,-0.107743,0.075696,0.263931,-0.620222,0.197830,-0.299560,0.159645,-0.093390,-0.304459,-0.199304,0.476345,0.177720,0.254304,0.402434,0.236879,-0.487868,0.182928,0.029505,0.033840,-0.197070,0.232742,0.069653,-0.422928,-0.059241,-0.006911,-0.290498,-0.310513,0.471638,-0.295503,0.206484,0.559733,-0.762959,-0.035836,-0.096808,-0.294684,0.216131,-0.085867,-0.145660,-0.743356,-0.103284,-0.140992,-0.044999,0.177405,0.222116,-0.123951,0.235144,-0.758886,0.030408,0.449600,0.262700,-0.083437,0.666701,-0.604608,0.229791,-0.276052,-0.064016,0.340947,0.341881,0.218571,0.161775,0.207058,-0.073376,-0.345864,-0.125277,0.383865', '25833539', '6858739', '1299166', '1308237');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2997094', '一代骄马', '剧情', '《一代骄马》根据真实的故事改编。潘妮·切纳里（黛安·莲恩 Diane Lane 饰）原本是一个普通的家庭主妇。对赛马几乎一窍不通的她，却在哥哥和丈夫的反对声中，从患病的父亲手中接管了位于弗吉尼亚州的养马场。尽管其时马场已亏损多时，但她依然不得不在居家的科罗拉多州和马场所在的弗吉尼亚州之间疲于奔命。为了觅得良马，潘妮特地找来告老还乡的驯马师路西安(约翰·马尔科维奇 John Malkovich 饰)，这个总是诸多抱怨的老头却对门外汉潘妮另眼相待。潘妮一眼相中马场里一匹一出生打个滚居然就能站立的栗色小马驹，起名为“秘书”。在路西安的个性训练下，“秘书”初出茅庐就一鸣惊人。它快如闪电、奔跃如飞，像个战士一般，甚至会为了赛场地面的震动而兴奋不已。终于到了决一胜败的时刻，“秘书”会顶着所有压力，不辜负潘妮的期望，成为25年来第一匹赢得美国三冠大赛的赛马么?©豆瓣', '戴安·琳恩', '兰道尔·华莱士', 8.1, 10090, 'tt1028576', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p506794780.jpg', 0.2, 1.2, 21.9, 48.7, 28, '0.157502,0.006275,-0.717298,0.707154,-0.142453,-0.493761,0.512364,0.096082,-0.241535,-0.273638,0.310326,0.759769,-0.070028,0.119684,0.274431,0.052142,-0.137693,-0.641379,-0.169888,-0.141358,-0.194857,-0.238505,-0.414255,0.050008,-0.067466,-0.123336,0.392032,0.025569,-0.196708,0.731685,0.346541,0.113489,0.082429,0.329671,-0.385599,-0.039517,-0.063647,0.040323,-0.167248,0.217300,0.074973,0.067383,-0.125164,-0.042854,0.106286,0.150507,0.617575,-0.497062,-0.087574,-0.127687,0.333554,-0.051388,0.210375,0.042157,0.201087,0.042955,0.231778,0.084310,-0.301097,0.238550,0.088144,-0.096022,-0.703427,0.084128,-0.007500,0.279265,-0.711125,0.339506,-0.089096,-0.189721,0.086081,-0.425356,0.064113,0.129384,-0.106120,0.532289,-0.331759,0.076618,-0.444463,0.051875,0.528443,0.099565,-0.349960,0.199583,0.002840,-0.283582,0.272630,-0.118733,-0.409845,-0.249535,0.162244,-0.105630,-0.041302,-0.071361,-0.345616,0.217719,-0.101750,-0.226127,-0.106840,-0.344684,-0.155521,-0.336431,0.121304,-0.548991,-0.117074,0.052994,0.240721,-0.065505,0.644930,-0.755716,0.172448,0.477135,0.057705,-0.235161,0.487929,0.034615,0.295286,-0.090929,-0.137280,0.083606,-0.057122,0.463974,0.004835,0.368875,-0.089602,-0.427337,-0.383531,0.606917', '1850797', '21360412', '35144311', '3006892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2997134', '创：战纪', '动作', '20世纪80年代，电子软体天才凯文·弗林（杰夫·布里吉斯 Jeff Bridges 饰）创建了英康公司，将人类带入一个全新的时代。可是在辉煌的时代开创不久后，凯文神秘失踪。在此之后，凯文年幼的儿子萨姆（加内特·赫德兰 Garrett Hedlund 饰）继承了父亲的位置，实际工作则由其他工作人员主持。萨姆天资聪颖，充满冒险精神，经常给英康的高层们惹来麻烦。这一天，他得知一间荒废已久的工作室内竟传来父亲的讯息。萨姆前去探查，结果竟进入一个全数字化的虚拟世界。这个世界的掌控者克鲁（杰夫·布里吉斯 Jeff Bridges 饰）与父亲有着同样的容貌，却野心勃勃，邪恶无比。萨姆被迫卷入一场充满阴谋的电子争霸战中……本片荣获2010年奥斯汀影评人协会最佳原创配乐奖。©豆瓣', '加内特·赫德兰', '约瑟夫·科辛斯基', 6.7, 103010, 'tt1104001', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p684659296.jpg', 2.4, 11.5, 46.5, 28.6, 10.9, '-0.050162,0.340528,-0.529569,0.565057,-0.239732,-0.228698,0.415761,0.116186,-0.650607,-0.470833,0.115048,0.755460,0.034057,0.087572,0.440609,0.008500,-0.445243,-0.366389,0.054657,-0.392012,-0.087016,-0.393408,-0.402969,-0.261465,-0.013702,-0.449989,0.782619,-0.158192,-0.202994,0.292552,0.235972,0.407582,-0.107719,0.108443,0.117486,0.051859,0.486103,-0.193824,-0.304404,0.188018,-0.170676,0.231132,-0.312928,0.042567,-0.044610,0.131519,0.378831,-0.261271,0.206105,-0.334762,0.644150,0.010072,-0.146988,-0.120098,0.339040,0.127996,0.026065,0.401332,-0.137715,0.049213,0.027538,-0.160909,-0.839507,0.024216,0.181038,0.120507,-0.286019,0.207287,-0.156731,-0.009582,-0.166023,-0.210042,-0.008005,0.316785,0.325191,0.381805,0.025438,0.289496,-0.227814,0.076537,0.333971,-0.152480,-0.422082,0.038938,-0.103720,-0.354874,-0.096967,-0.302558,-0.629185,-0.034865,0.417594,0.002788,0.172718,0.428653,-0.623276,0.019092,-0.346409,-0.293286,0.233625,-0.106279,-0.168691,-0.973803,-0.199552,0.023790,-0.247211,-0.158441,0.046426,-0.128708,0.642852,-0.721120,0.332255,0.341607,-0.101977,-0.218646,0.512640,-0.022232,0.419388,-0.403951,-0.343815,0.421323,0.079701,0.327272,-0.234546,0.156831,-0.055805,-0.330052,-0.303952,0.422368', '2369613', '30229667', '3318306', '1293656');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2997155', '风云Ⅱ', '动作', '绝无神（任达华 饰）及其子绝心（谢霆锋 饰），投毒暗算中原武林，无名（何家劲 饰）、步惊云（郭富城 饰）成阶下囚。聂风（郑伊健 饰）闻讯赶到，与步惊云联手攻击，均遭重创。无名单挑绝无神，使用万剑归宗也无济于事。为破强敌，聂风、步惊云、楚楚（唐嫣饰）一起来拜谒魔道高人，但直到第二梦（蔡卓妍 饰）出现，才引得高人现身，但他双臂已断，功力也大不如前。为了破敌，聂风愿身堕魔戒，增强功力。而步惊云则师从无名，创建了新派剑道。此时，绝无神生擒了中州皇帝（谭耀文 饰）来到凌云窟。绝心用残酷逼皇帝说出龙骨所在。千钧一发之际，风云先后赶到，一场江湖对决，由此展开……本片根据马荣成畅销漫画《风云》改编，为10年前刘伟强版《风云雄霸天下》的续集，导演是擅长恐怖片的彭氏两兄弟。©豆瓣', '郭富城', '彭顺', 5.1, 40154, 'tt1186371', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1320935641.jpg', 13.4, 34.9, 39.1, 8.9, 3.7, '-0.254822,0.038586,-0.364333,0.317471,0.494413,-0.269733,0.185328,0.076913,-0.276469,-0.425789,0.629859,0.547481,-0.067152,-0.308894,0.241641,-0.089654,0.197644,-0.695146,-0.168300,-0.094694,0.159425,0.203761,-0.148287,0.129952,-0.272865,-0.251530,0.681148,0.112932,-0.220169,0.328005,0.245204,0.157999,-0.337774,0.108293,0.046669,0.229347,-0.294985,0.010750,-0.534025,0.442775,-0.357125,-0.485996,-0.422225,0.270874,-0.386001,0.312934,0.351419,-0.325420,0.078370,-0.102666,0.527494,-0.309160,-0.485424,-0.128664,0.214779,0.006595,0.381389,0.134875,0.056118,0.110558,-0.115389,-0.005047,-0.583669,0.073100,0.303991,0.063241,-0.106081,0.130176,-0.483364,-0.245182,-0.345702,-0.329974,-0.002398,0.152793,0.549415,-0.163275,-0.072694,-0.213547,-0.417111,0.146690,0.427725,-0.044315,0.162196,-0.069705,0.619302,-0.225941,-0.094586,-0.628422,0.281635,-0.093166,0.477212,0.061825,0.415761,0.325405,-0.221765,-0.315789,-0.266991,0.293063,-0.268870,0.105041,-0.039544,-0.620186,-0.312412,-0.037740,-0.035222,-0.262503,0.543264,-0.211422,0.606055,-0.717594,0.217764,-0.117282,-0.015874,-0.299270,0.247286,-0.030823,-0.103561,-0.229142,-0.091445,0.159571,0.053410,0.367793,0.177208,0.115320,-0.109424,-0.185271,-0.165504,-0.109981', '30465281', '2369613', '25723905', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2997402', '漂亮爸爸', '动画', '在鹰司千里（绿川光 配音）的心里，作家咲春香的作品是文坛上的最高作，他唯一的梦想就是能够和春香老师谈一场充满了浪漫的恋爱。某日，幸运的拿到了春香手稿的千里发现手稿上的字迹十分眼熟，经过仔细辨认，矛头指向了自己最大的敌人榊俊介（樱井孝宏 配音）。原来，春香是俊介的笔名，得知真相的千里大受打击。不仅如此，之后来自俊介的表白更让千里不知所措。在经历了诸多波折后，别扭的千里终于开始正视对俊介的感情，但在千里的心中，始终有着一个疙瘩——俊介的父亲神崎（成田剑 配音）正是曾经侵犯过他的学长。无论如何都跨不过这道坎的千里会做出怎样的选择呢？©豆瓣', '绿川光', '愚痴蓝', 6.8, 6264, 'tt1247224', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2503145653.jpg', 1.8, 8.1, 49.9, 27.7, 12.4, '0.362007,-0.084875,-0.605401,0.662463,0.250473,-0.338423,0.559594,-0.126035,-0.485488,-0.365581,0.380692,0.692395,-0.384550,0.110557,0.284232,0.116252,0.081752,-0.725574,-0.061497,-0.301419,-0.191641,-0.515951,-0.364257,0.020344,-0.241963,-0.041823,0.752555,0.077252,-0.208783,0.281323,0.377008,0.138448,0.106162,0.174023,-0.216254,0.086956,-0.023219,0.219860,-0.205685,0.085175,0.136177,-0.338091,-0.212014,0.450404,-0.314101,0.426119,0.653599,-0.158128,-0.581343,0.466245,0.577736,-0.453169,-0.206894,0.023286,0.113716,0.059241,0.123060,0.112171,-0.199715,-0.155010,0.021810,0.100983,-0.638733,-0.045619,0.190390,0.283218,-0.518124,0.533952,-0.026625,-0.268474,0.159039,-0.345985,0.199834,0.279385,0.308146,0.325166,-0.471240,0.082753,-0.311410,0.245422,0.649650,0.099756,-0.022025,0.262057,-0.036081,-0.479979,-0.085357,-0.235047,-0.487861,0.316205,-0.008358,0.198564,-0.193524,0.174474,-0.703952,0.018054,-0.263135,-0.051067,0.104449,-0.607713,-0.216297,-0.279887,-0.361273,-0.556792,-0.385751,-0.104926,0.255168,-0.606575,0.850020,-0.883843,0.063566,0.330467,-0.041450,-0.222240,0.567114,0.409608,-0.199221,-0.012814,-0.090433,0.205621,-0.002040,0.509539,-0.020200,0.423995,0.239347,-0.318450,-0.464473,0.583420', '25880986', '1826173', '35030151', '26809007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2997404', '棋魂·通往北斗杯之路', '剧情', '佐为已离开，但光的围棋生涯还在继续。接续动画版的剧情，这部是之后推出的OVA，讲述了这群年轻棋手们的北斗杯之旅。经过一番努力和征战，进藤光（川上伦子 配音）终于成为了一名职业棋手，这是对自己能力的认可也是全新的开始。成为职业棋手后的光从棋院那得知了北斗杯的消息，这是为18岁以下的年轻人举办的围棋赛，会有来自中国、韩国等围棋强国的青少年参与。兴致勃勃的光把这个消息告诉了塔矢亮（小林沙苗 配音），亮听到后一脸淡然的说自己已经是北斗杯确定的参与选手了。而光还得参与预选赛，才有资格和亮一起站在北斗杯的现场，通往北斗杯之路就此拉开。©豆瓣', '川上伦子', '西澤晋', 9, 7840, 'tt1236468', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2317864927.jpg', 0.2, 0.2, 8, 31.8, 59.7, '0.210501,0.306253,-0.598279,0.589616,-0.122640,-0.345315,0.299145,-0.024894,-0.532196,0.039088,0.059333,1.041039,-0.388734,0.326728,0.511574,-0.300311,-0.310044,-0.977510,-0.434230,-0.212558,-0.338062,-0.474939,-0.017432,0.145934,-0.178168,-0.261481,0.649341,-0.081989,-0.435283,0.480543,0.340994,0.066023,0.120018,0.292891,-0.284060,-0.097663,0.033342,-0.082385,-0.124703,0.423326,-0.083523,-0.338232,-0.363296,-0.037600,0.263650,0.314284,0.453447,-0.069880,-0.062241,0.117464,0.259222,-0.364490,-0.344718,0.128936,0.397675,0.318972,-0.059999,0.175378,-0.040450,0.315453,-0.351529,-0.243380,-0.956695,-0.013066,0.125476,0.394998,-0.587375,0.581662,-0.133797,-0.339026,0.221868,-0.059119,0.525874,0.496690,0.222552,0.351796,0.002550,0.088293,-0.347362,0.106795,0.577735,-0.088530,-0.134326,0.273092,0.361994,-0.715191,-0.175423,-0.080488,-0.070789,-0.030987,0.192201,0.214886,0.253115,-0.082854,-0.748669,0.043345,0.053512,-0.499452,0.274368,-0.192137,0.052649,-0.578276,-0.104519,-0.563903,-0.368486,0.091909,0.040479,-0.378067,1.119363,-0.974728,0.067604,0.323680,0.050453,-0.258613,0.838427,0.177026,0.081865,-0.079821,0.017120,-0.137142,-0.152452,0.523581,-0.148831,0.803636,0.244406,-0.592457,-0.255969,0.229350', '27602116', '26711487', '4127270', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2998253', '兰戈', '喜剧', '兰戈（约翰尼·德普 Johnny Depp 配音）是一只干瘦、翠绿的蜥蜴，他住在鱼缸里，蓝天白云椰子树的假相让他倍感无聊，这个酷爱幻想和表演的家伙只得在头脑中编出属于自己的英雄剧。可就在某天，一个意外将他驱赶出惯常的方寸空间，兰戈莫名其妙来到了西部荒原的公路上。在沙漠中穿行的时候，兰戈遭到猎鹰的袭击。经过一番周折，他来到了名为黄沙（Dirt）的小镇，这里住着许多昆虫和动物，破败不堪，宛若死城。兰戈意外干掉了凶恶的猎鹰，由此被镇上的居民视为英雄，他也乐于享受这种荣誉，可是英雄毕竟不好当……本片荣获2012年奥斯卡金像奖最佳动画长片奖；2012年安尼奖最佳动画片、最佳角色设计、最佳编辑和最佳剧本奖；2011年青年选择奖最佳配音奖（约翰尼·德普）。©豆瓣', '约翰尼·德普', '戈尔·维宾斯基', 8, 135822, 'tt1192628', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1000880652.jpg', 0.2, 1.6, 22, 50.5, 25.6, '0.144060,0.004196,-0.696630,0.594463,0.114562,0.037131,0.749563,-0.042672,-0.555231,-0.078925,0.338346,0.776989,-0.189323,0.201270,0.302305,0.053786,-0.320970,-0.527241,-0.164446,-0.168593,-0.080465,-0.215488,-0.589752,-0.096083,-0.096038,-0.323325,0.727826,0.021541,-0.260624,0.323055,0.366356,0.010077,-0.070064,0.305780,-0.430444,0.151237,0.165214,-0.168474,-0.029427,0.402771,-0.110925,-0.434962,-0.205172,0.284505,0.017967,0.229317,0.973035,-0.473906,-0.257463,0.149069,0.452430,-0.432426,-0.140356,-0.055478,0.362700,-0.346488,0.413633,-0.099335,-0.078270,0.377245,0.097146,-0.345550,-0.755011,0.027886,-0.015174,0.174755,-0.691339,0.387263,0.231918,-0.032990,0.029088,-0.208922,0.379819,-0.142426,0.505663,0.354436,-0.195259,0.103721,-0.336590,0.459575,0.348283,0.043129,-0.326123,0.336036,-0.213826,-0.572609,-0.018042,-0.342090,-0.444446,-0.156915,0.464108,-0.143460,-0.296279,-0.008757,-0.628612,0.218877,-0.158479,-0.338420,-0.223658,-0.178381,-0.335611,-0.611083,0.114814,-0.174800,-0.138544,0.010086,-0.102586,-0.317700,0.510422,-0.644763,0.210241,0.617827,-0.024239,-0.031535,0.708290,-0.164982,0.055806,-0.054417,-0.147386,0.121211,-0.034492,0.350785,0.249180,0.384652,-0.138367,-0.425025,-0.435967,0.555311', '1292925', '21619567', '1467779', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2998270', '大侦探福尔摩斯', '动作', '大侦探福尔摩斯（小罗伯特·唐尼 Robert Downer Jr. 饰）即使在置人于死地之时也异常的逻辑清晰，然而办案时有条不紊的他在私底下的生活中简直就是个“怪胎”，至少在他的助手华生医生（裘德·洛 Jude Law饰）眼中他是这样一个人。他们亲手绳之以法的“黑暗巫师”布莱克大人（马克·斯特朗 Mark Strong 饰）在临死前说死亡即是开始，随后艾琳·艾德勒（瑞秋·麦克亚当斯 Rachel McAdams 饰）出现在他的身边要他帮忙找个失踪的人，而她身边有个影子般可怕人物。坊间传说黑暗巫师已经复活，他的墓地遭到破坏，而躺在棺材里的人另有其人。又到了大侦探福尔摩斯出马的时候了，然而调查过程从一开始就险象环生，助手华生医生在调查中更是险些丧命，福尔摩斯也陷入连串的迷团之中。本片根据著名同名漫画改编，作者莱昂纳尔·威格拉姆（Lionel Wigram）。2010年第82届奥斯卡最佳艺术指导、最佳配乐2项提名、第67届金球奖音乐/喜剧类最佳男主角Robert Downey Jr.', '小罗伯特·唐尼', '盖·里奇', 7.7, 301578, 'tt0988045', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1078047854.jpg', 0.3, 2.3, 28.5, 50.6, 18.2, '0.121655,0.001545,-0.689833,0.604193,-0.039028,-0.233228,0.792187,0.058970,-0.408420,-0.351516,0.338793,0.848605,-0.280673,0.220265,0.352197,0.007025,-0.496295,-0.681582,-0.213716,-0.228891,-0.274472,-0.519890,-0.360225,-0.350236,0.067769,-0.311110,0.420159,-0.060528,-0.138589,0.145742,0.281216,0.233111,-0.010795,0.317019,-0.069528,0.156565,0.291768,-0.109809,-0.124313,0.331337,0.124910,-0.337060,-0.277969,0.019179,-0.061839,0.169735,0.500792,-0.454188,0.165045,0.191617,0.501801,-0.397711,-0.198008,-0.051979,0.324805,-0.320642,0.119868,0.111899,-0.018056,0.117467,-0.018786,-0.174344,-0.809767,0.083378,-0.109962,0.431037,-0.376591,0.226216,-0.050692,0.242144,0.084861,-0.165497,0.264464,-0.108127,0.305407,0.091368,-0.053515,-0.043490,-0.350534,0.282129,0.250126,0.122671,-0.378103,0.208925,-0.061818,-0.794361,-0.071701,-0.081664,-0.363297,-0.065551,0.462466,-0.167645,-0.188025,0.201524,-0.332741,-0.035149,-0.224536,-0.071487,-0.429918,-0.114137,-0.145484,-0.552178,-0.079854,-0.064878,-0.013228,-0.019686,0.026794,-0.401596,0.697387,-0.480976,0.339798,0.504706,-0.201740,-0.026874,0.573237,0.004804,0.192345,-0.152880,-0.246041,0.140400,0.342003,0.386190,0.175698,0.368757,-0.056488,-0.029343,-0.309426,0.444424', '34890458', '2028634', '25928048', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2998340', '仪式', '剧情', '迈克·科瓦克（科林·奥多霍诺 Colin O''Donoghue 饰）是一个出身葬仪家庭的神学院学生，但是他的心中始终找不到任何信仰的依附。偶然机缘，迈克被派往梵蒂冈参加一个驱魔师的培训课程。对上帝尚且心怀疑惑，何况玄之又玄的驱魔仪式，迈克以科学的角度和授课老师展开辩论。在老师的推荐下，他前去拜访了因驱魔而名声显赫的卢卡斯·特雷万神父（安东尼奥·霍普金斯 Anthony Hopkins 饰）。虽然亲身经历了卢卡斯神父的驱魔仪式，但是他依然不相信魔鬼的存在，直到一系列匪夷所思的事情在其身上发生，迈克灵魂的深处才真正发生了动摇……根据Matt Baglio的小说《仪式：现代驱魔人的制造》改编，故事灵感来自真实事件。©豆瓣', '安东尼·霍普金斯', '米凯尔·哈弗斯特罗姆', 6.7, 11500, 'tt1161864', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p786306798.jpg', 1, 9, 50.9, 30.9, 8.2, '0.430792,-0.140156,-0.503672,0.703235,-0.056491,-0.056785,0.470863,-0.080631,-0.644472,-0.699863,0.238591,0.730269,-0.131565,0.045841,0.264427,-0.079408,-0.226676,-0.578523,0.195238,-0.105003,-0.246592,-0.559112,-0.212035,-0.317911,-0.177357,-0.415595,0.553987,0.050030,-0.236953,0.379712,0.186156,0.353774,0.065257,0.231834,-0.060499,-0.186622,0.311269,0.125998,-0.118429,0.216797,0.228363,-0.094186,-0.249760,0.300529,-0.142243,0.492744,0.206905,-0.473531,-0.201065,-0.001033,0.493679,-0.355089,0.015930,0.261229,0.207974,0.234880,-0.123775,0.476368,0.268039,0.048802,-0.073119,-0.139418,-0.919288,-0.138055,0.131647,0.466491,-0.442918,0.445155,-0.163407,-0.056940,-0.160631,-0.275111,0.074573,0.070783,0.441533,0.357987,-0.110862,-0.119215,-0.320328,0.149237,0.463139,0.102427,-0.480300,0.242973,-0.517173,-0.511987,-0.036016,-0.150758,-0.425899,0.288392,0.092343,0.059944,0.036138,0.299164,-0.519064,-0.248526,-0.160098,-0.234492,-0.042585,-0.320543,0.135281,-0.836383,-0.169449,-0.174696,-0.290614,-0.449499,0.334790,-0.304947,0.745983,-0.909349,0.326495,0.696914,0.141090,-0.436199,0.707845,0.088764,0.059047,-0.308229,-0.162240,0.252903,0.170826,0.398753,-0.233765,0.383755,0.364007,-0.312440,-0.238197,0.532913', '1793491', '10763928', '25932086', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2998373', '帕丁顿熊', '喜剧', '在神秘的秘鲁，生活着一种十分稀有的果酱熊，他们拥有非常高的智商和语言能力。当年果酱熊夫妇帕斯图佐和露西曾与来自伦敦的探险家结下深厚的友谊，并且学到了压制果酱的技巧。时至今日，一场灾难摧毁了果酱熊安宁快乐的生活，露西阿姨将淘气的侄子送上开往伦敦的邮轮，嘱咐他在那个友好的国度展开新的生活。万里漂泊而来的小熊懵懵懂懂来到帕丁顿火车站，可是当代人的冷漠却让他倍感失落。幸运的是小熊遇到了布朗一家，并且得到了一个好听的名字——帕丁顿（本·卫肖 Ben Whishaw 配音）。善良的女主人玛丽（莎莉·霍金斯 Sally Hawkins 饰）殷切要帮助帕丁顿找到可以栖身的地方，而男主人亨利（休·博内威利 Hugh Bonneville 饰）则时刻想把这个突如其来的麻烦赶走。在此过程中，搞怪不断的帕丁顿和布朗一家关系逐渐融洽，而自然历史博物馆的标本师米莉森特（妮可·基德曼 Nicole Kidman 饰）则怀着邪恶的目的悄然向帕丁顿接近……', '本·卫肖', '保罗·金', 7.8, 232829, 'tt1109624', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2231740424.jpg', 0.2, 1.8, 27, 48.7, 22.3, '0.368758,0.135054,-0.673275,0.854206,-0.129794,-0.168475,0.763631,0.182287,-0.406035,-0.220606,-0.005752,0.732853,0.127422,0.127098,0.317147,0.159975,-0.201690,-0.409848,0.037521,-0.001422,-0.124567,-0.499865,-0.436765,-0.226618,-0.090683,-0.441474,0.292467,0.019137,-0.158025,0.603248,0.175079,0.377468,-0.210011,0.231595,-0.404948,-0.069591,0.201271,0.058067,-0.326068,0.135337,0.095824,0.105429,0.002663,0.217654,0.120698,0.205711,0.687686,-0.318079,-0.245854,-0.024892,0.283413,-0.256913,0.140683,0.180585,0.067639,-0.081494,0.175339,0.013157,-0.259506,0.102511,0.275654,-0.230050,-0.830407,0.069556,0.033395,-0.027312,-0.546548,0.618711,0.109661,-0.110119,0.204834,-0.413724,0.227190,0.366769,0.145682,0.581555,-0.099482,0.270858,-0.384810,-0.131519,0.632148,-0.065443,-0.193574,0.295720,-0.441740,-0.435934,0.099451,-0.198073,-0.614799,-0.136222,0.398649,0.015206,-0.017389,0.352541,-0.893528,-0.089181,-0.275082,-0.123773,0.187667,-0.414917,-0.096091,-0.582096,-0.077170,-0.531025,-0.185347,-0.132769,0.047338,-0.256355,0.819444,-0.757287,0.254960,0.461433,0.275672,-0.253519,0.549116,0.059068,0.144613,-0.283428,-0.184597,0.317301,0.082726,0.059694,0.201520,0.358842,-0.022169,-0.065063,-0.40318