INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2998395', '新猛鬼街', '惊悚', '在《守望者》（Watchmen）中扮演蒙面侠客罗夏的杰克·厄尔·哈利（Jackie Earle Haley）将在新线公司新版的《猛鬼街》（A Nightmare on Elm Street）中扮演弗莱迪（Freddy Krueger）！《猛鬼街》系列电影一共9部，讲述的都是恶魔弗莱迪潜入人的梦中杀人的恐怖故事。此次的新版《猛鬼街》不是续集，而是从头再来。“弗莱迪”是恐怖电影史上的经典形象，原来扮演这一角色的是罗伯特·英格兰德（Robert Englund）。据制片方透露，选择“弗莱迪”演员人选最重要的是要在化装的观众都不认识你的情况下，依然能表演精彩，而杰克·厄尔·哈利在《守望者》中的表演证明了他有这种能力。©豆瓣', '杰基·厄尔·哈利', '塞缪尔·贝尔', 6.1, 15602, 'tt1179056', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1634913686.jpg', 2.8, 16.8, 56.7, 18.5, 5.3, '0.267305,-0.223602,-0.358841,0.693828,-0.093461,0.043382,0.759976,-0.307440,-0.302111,-0.111007,0.440259,0.808444,-0.053428,0.072202,0.244744,0.101636,-0.532491,-0.530551,-0.447154,-0.169710,-0.066940,-0.612768,-0.582412,-0.262860,0.034119,-0.370448,0.792995,-0.029057,-0.484572,-0.058339,0.564283,0.372597,-0.111155,0.161541,0.022026,0.141451,0.265208,-0.236912,-0.183033,0.455916,0.056342,-0.269713,-0.161325,0.422204,-0.034544,0.565856,0.576697,-0.422473,-0.001242,0.114214,0.546106,-0.218265,-0.180845,-0.061017,0.141541,-0.123365,0.325463,0.399357,0.293276,0.168988,-0.309748,-0.283864,-1.320925,-0.024640,0.489154,0.503395,-0.380974,0.359059,-0.204097,-0.039009,0.333741,0.010509,0.300264,-0.117736,0.638969,0.259016,0.207088,-0.070974,-0.480357,0.564562,0.487064,0.069362,-0.413692,0.628889,-0.211341,-0.586754,-0.380927,-0.278425,-0.468630,0.194435,0.276044,-0.091924,-0.119018,0.278534,-0.466350,0.026552,0.095540,-0.155568,-0.321103,-0.320077,-0.139769,-0.795543,-0.212443,-0.339884,0.052228,-0.228079,0.057710,-0.612647,0.635997,-0.806324,-0.008861,0.592610,-0.025271,-0.013196,0.831981,0.097230,0.048056,-0.146352,-0.117272,0.029905,0.128830,-0.044189,-0.008276,0.433380,0.254262,-0.440539,-0.443966,0.784413', '6844861', '1793491', '27098364', '35360296');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('29984000', '热带往事', '剧情', '南方炎热的夏日夜晚，年轻的王学明（彭于晏 饰）遭遇了一起意外。梁妈（张艾嘉 饰）的老公忽然失踪，她寻求陈警官（王砚辉 饰）的帮助，却不知自己已成为别人的下一个“目标”。陈警官负责老梁失踪案，他发现案情的发展远超自己掌控。这群不知命运已被悄然更改的人，都在试图窥视关于那个夜晚的真相，但这个夏夜的记忆如错乱的拼图，愈加扑朔迷离……', '彭于晏', '温仕培', 6.2, 86071, 'tt8519380', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2654729576.jpg', 1.8, 16.6, 56.9, 21.7, 3.1, '0.519382,0.259771,-0.631721,0.501053,0.002453,-0.103802,0.834401,-0.004236,-0.390722,-0.701156,0.134451,0.365603,-0.086770,0.395584,0.128059,0.022419,-0.241654,-0.753249,0.050023,0.113813,-0.364408,-0.409900,-0.554992,-0.068030,-0.037564,0.240553,0.553188,0.439525,-0.310431,0.422443,0.154797,0.321128,0.016307,0.762950,-0.253932,0.157241,0.113330,0.088438,-0.003013,-0.056047,0.086902,-0.590686,-0.053016,0.234046,-0.182716,0.611036,0.676087,-0.207955,-0.375864,-0.102456,0.690190,-0.262644,0.041666,0.031508,0.372636,0.141720,-0.339433,-0.061475,-0.291132,-0.156207,0.095685,-0.040382,-0.792133,0.262869,0.397215,0.287251,-0.288515,-0.129887,-0.108646,0.110800,0.069448,-0.340874,0.454207,0.374555,0.279694,0.411483,-0.266718,-0.201243,-0.631021,0.338949,0.704445,0.058802,-0.325058,0.260593,-0.466203,-0.614061,-0.066144,-0.061736,-0.459049,0.035609,0.296052,0.038825,-0.151027,0.367997,-0.304856,-0.082390,0.047433,0.021927,-0.437870,-0.358993,-0.087909,-0.212880,-0.462183,-0.460037,-0.264190,0.281397,-0.141072,-0.317986,0.437395,-0.606733,0.274274,0.479490,0.005806,-0.598267,0.489145,0.204063,0.197830,-0.183791,-0.071348,0.433351,0.062880,0.353833,-0.034497,0.366507,0.077023,-0.020209,-0.420310,0.227418', '1301022', '35073886', '3059036', '3263169');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2998412', '蒙特卡洛', '喜剧', '影片改编自朱尔斯·贝斯的小说《猎头族》。三个年轻女孩Grace (赛琳娜·戈麦斯 Selena Gomez 饰), Emma 凯蒂·卡西迪 Katie Cassidy 饰) 和 Meg (莉顿·梅斯特 Leighton Meester 饰) 决定用她们攒下的钱踏上梦想中的巴黎之旅，却发现旅行完全变成了灾难。当她们决定从他们糟糕的游览中休息一下，进入了一家5星级酒店大堂时，Grace却被误认为是一位叫Cordelia的富有英国继承人。Grace便将计就计，假扮成Cordelia好让大家体验到她们应得的梦想中的假期，但事情并没有按计划进行，Grace喜欢上了一个叫Theo（皮埃尔·布朗格 Pierre Boulanger 饰）的法国男孩。Theo爱上了作为Cordelia的Grace，完全不知道Grace是个骗子。当真正的Cordelia到达酒店时，女孩子们该如何搞定这场意外呢？', '赛琳娜·戈麦斯', '托马斯·伯祖查', 6.5, 10811, 'tt1067774', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p972082000.jpg', 1.5, 11.3, 56.7, 23.9, 6.6, '0.391097,0.252400,-0.538910,0.329107,-0.152390,-0.505915,0.604049,-0.098870,-0.273256,-0.393382,-0.073972,0.783595,-0.121760,0.287343,0.450776,0.196186,-0.567453,-0.693211,0.137796,-0.314478,-0.343719,-0.211284,-0.115827,-0.059994,-0.035396,-0.077416,0.354467,0.253423,-0.166893,0.395984,0.497081,0.362752,0.156064,0.264470,-0.031125,-0.097195,0.323257,0.054717,-0.243535,0.496626,-0.205941,0.121976,-0.338398,0.126751,0.263853,0.282731,0.463094,-0.241741,-0.120172,-0.123225,0.199503,-0.129683,-0.038866,0.207608,0.012061,-0.160275,0.277658,-0.118176,-0.183425,0.137924,0.055710,-0.279383,-0.718987,0.210600,0.113835,-0.007109,-0.613188,0.098769,-0.079257,-0.188748,0.058649,-0.388882,0.148279,0.359396,0.410287,0.302787,-0.025347,0.043055,-0.631725,0.164243,0.818608,0.078202,-0.292911,0.240025,0.097755,-0.521847,0.062690,-0.245021,-0.280567,0.178572,0.229005,0.190065,0.064071,-0.155153,-0.600060,-0.201895,-0.313575,-0.429286,-0.029103,-0.524956,-0.069727,-0.678131,0.014873,-0.273289,-0.370336,0.009238,-0.036824,-0.270865,0.603283,-0.822732,0.313257,0.408609,0.150091,-0.581817,0.718977,0.169079,0.190799,-0.298693,-0.046147,0.061997,0.073043,0.118595,0.048257,0.363190,-0.031643,-0.392197,-0.428017,0.492886', '4301278', '3055049', '30162520', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2998439', '我们所知道的生活', '剧情', '霍莉（凯瑟琳·海格尔 Katherine Heigl 饰）与埃里克（乔什·杜哈明 Josh Duhamel 饰）被他们的共同好友诺瓦克夫妇撮合，结果第一次约会就是灾难性的。不过两人好歹相识了，从此在任何有幸共同出席、互打照面的场合互相拆台，闹出不少笑话。天有不测风云，一场车祸夺去诺瓦克夫妇的性命，律师整理遗嘱发现，他们把尚在襁褓中的小女儿苏菲的监护权留给了霍莉和埃里克共同所有。一对冤家就这样聚头在同一屋檐下，共同担起奶爸奶妈的职责。最开始两人依旧互看不顺眼，吵吵闹闹是家常便饭，甚至拉来各自炮友搅乱空气，但在相处中，两人开始渐渐发现对方的好处和优点，在为小苏菲的各种事项忙得焦头烂额之时，更是发觉这个负担其实非常甜蜜……©豆瓣', '凯瑟琳·海格尔', '格里格·伯兰蒂', 7.2, 27356, 'tt1055292', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p677793721.jpg', 0.4, 3.9, 43.7, 41.1, 10.9, '0.580563,-0.187710,-0.683735,0.298189,-0.019419,-0.365003,0.638356,0.097237,-0.652299,-0.261387,0.108846,0.792405,-0.545834,0.279917,0.380095,-0.434298,-0.253203,-0.760420,-0.041866,-0.044308,-0.222797,-0.558896,-0.147531,0.092410,-0.337492,-0.024799,0.378016,-0.343366,0.037618,0.432591,0.447371,0.044875,-0.430683,0.406160,-0.111274,0.020539,-0.070794,0.088002,-0.690533,-0.098407,-0.056247,0.084783,-0.285086,0.092986,0.137655,0.330190,0.717701,-0.367246,-0.086040,-0.000768,0.272321,-0.090776,0.021588,0.236249,0.319484,0.040692,0.611527,0.089864,-0.135109,-0.049340,0.175480,0.066730,-0.421261,0.410996,0.192742,0.224843,-0.452553,0.618006,0.141731,-0.108170,0.047798,-0.114288,0.266764,0.694977,0.117502,0.315983,-0.330726,0.072847,-0.490028,-0.127315,0.658698,-0.095308,0.060444,0.492206,-0.148938,-0.265146,0.018436,-0.073553,-0.417139,-0.186370,0.251976,0.021314,0.041078,0.475303,-0.759784,-0.049026,-0.076342,0.108544,0.072972,-0.668766,0.207837,-0.845981,-0.267991,-0.472378,-0.398276,0.412317,0.187454,-0.343043,0.545097,-0.762812,-0.028713,0.204359,0.067021,-0.355764,0.402840,0.379225,0.657384,-0.289669,-0.152521,0.003308,0.288194,-0.020598,0.317698,0.308122,0.022115,0.181109,-0.187834,0.309583', '11541282', '1292050', '1291856', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2999500', '七天', '惊悚', '女律师刘智妍（金允珍 饰）业务能力过人，保持着从未败诉的记录，她和女儿恩英一起生活，把所有的爱都倾注在后者身上。学校举办的运动会上，恩英在混乱的人流中被人绑走了。起初，刘智妍因为报警而遭到了绑匪的警告，第二天，刘智妍终于得知了绑匪的目的：他并非为钱，而是要求刘智妍为一个杀人嫌犯辩护。一个月前，一个年轻女子被人杀死在家中并遭弃尸，郑铁镇因为在现场留下了指纹和足迹成为最大嫌疑人，在一审中，郑铁镇被判死，眼下距离二审开庭只有四天时间，刘智妍找到深陷违纪案的小学同学金警官帮忙，迅速展开了对案情的调查，随着种种证据浮现，刘智妍发现此案确有蹊跷，而案件背后的隐情，更是只露出了冰山一角……©豆瓣', '金允珍', '元新渊', 7.5, 32352, 'tt0997229', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p642667992.jpg', 0.5, 2.8, 32, 49.7, 14.9, '0.164201,-0.011535,-0.502524,0.360289,-0.191241,-0.120323,0.813528,-0.084890,-0.569712,-0.321513,0.166712,0.477422,-0.145299,0.168260,0.240466,-0.312597,-0.325513,-0.827181,-0.058658,-0.384442,-0.513650,-0.701283,0.142429,-0.222219,-0.064568,-0.229498,0.421267,0.203410,-0.023856,0.537673,0.307814,0.095531,-0.392611,0.508733,-0.020496,-0.161267,0.154422,-0.001757,-0.228610,0.318859,0.208587,-0.540415,-0.046000,0.074303,-0.188702,0.590968,0.726337,-0.072423,-0.289105,-0.113436,0.259202,-0.430607,-0.004737,0.222986,0.433338,0.160045,0.326297,0.633393,-0.500894,-0.001641,0.159284,-0.133751,-0.806499,-0.100030,0.080809,0.273781,-0.349099,0.341485,-0.273300,0.055125,-0.032540,-0.173083,0.380599,0.239654,0.185481,0.103454,-0.264713,0.022272,-0.598858,0.139531,0.487730,-0.112330,0.106870,0.127562,0.005747,-0.557510,-0.112645,0.014563,-0.009023,0.129120,0.253982,0.138234,-0.392678,0.017721,-0.433519,-0.091831,-0.226822,-0.254896,-0.108993,-0.367184,-0.217917,-0.313846,-0.213820,0.046129,-0.449142,0.209763,0.034235,-0.330263,0.290854,-0.711360,0.188645,0.518537,0.404806,-0.358049,0.714655,0.098558,0.162158,-0.233669,-0.258422,-0.056014,0.368205,0.434728,0.191246,0.064477,-0.196650,-0.290650,-0.412732,0.344592', '3263169', '25862560', '1947080', '4903581');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2999913', '保罗', '喜剧', '格雷姆（西蒙·佩吉 Simon Pegg 饰）与克莱夫（尼克·弗罗斯特 Nick Frost 饰）是一对来自英国的极客好友，每天生活中充斥着外星人事件、漫画故事、科幻点子，今次又跑到美国来参加漫展，顺道探访外星人爱好者圣地：内华达州51区，没想到在路上偶遇一个真正的外星  人——60年前被困在地球，又被科研基地囚禁研究，而今终于逃出来的保罗（塞斯·罗根 Seth Rogen 配音）。不出所料的是，保罗长得一副ET样，超能力一流，而出乎他们意料的是，保罗是个满口美式俏皮话和脏话的“痞子”外星人，三个难兄难弟走上“帮保罗回家”的路途，后面紧追不舍的是国土安全局探员佐尔（杰森·贝特曼 Jason Bateman 饰）和他的笨搭档，一心想抓保罗回研究基地……本片是英国金牌喜剧搭档西蒙·佩吉和尼克·弗罗斯特继《僵尸肖恩》和《热血警探》之后再度爆笑合作。©豆瓣', '西蒙·佩吉', '格雷格·莫托拉', 7.6, 65950, 'tt1092026', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2110513689.jpg', 0.4, 2.6, 29.7, 49.1, 18.1, '0.265221,-0.391643,-0.521786,0.481514,0.004874,-0.358974,0.612773,-0.138886,-0.576347,-0.086311,0.066943,0.910929,-0.438861,0.141700,0.314845,0.177606,-0.549789,-0.405994,-0.128350,-0.216235,-0.133591,-0.564315,-0.426547,-0.271578,0.043389,-0.332993,0.397218,-0.239309,-0.270278,0.598376,0.330513,0.541174,-0.162236,0.136633,-0.144714,0.064386,0.505701,-0.105321,-0.074215,0.206348,-0.044461,0.094699,-0.231103,0.003415,0.104796,0.144501,0.400091,-0.045029,0.345669,-0.073169,0.161765,-0.473076,-0.180199,-0.089060,0.501841,-0.261622,0.152445,0.106648,0.152706,-0.068692,0.142130,-0.295140,-0.410491,0.135483,-0.147849,0.205853,-0.485819,0.221458,-0.167642,-0.015901,0.119385,-0.257799,0.224731,0.212415,0.369364,0.428648,0.326125,0.110361,-0.437081,0.135597,0.478393,0.092597,-0.163310,0.144016,-0.013598,-0.400459,-0.102401,-0.113010,-0.387621,0.001853,0.197794,-0.377997,-0.118317,0.168817,-0.719066,0.130838,-0.374253,-0.145903,0.022322,-0.238554,-0.096381,-0.961917,0.045947,-0.330092,-0.063047,-0.046854,0.172223,-0.083381,0.592115,-0.622600,-0.068099,0.520929,0.034304,-0.227579,0.697922,-0.049410,-0.131430,-0.270588,0.015245,0.078342,0.328441,0.193316,-0.014257,0.539346,0.239803,-0.379452,-0.372982,0.257310', '1297659', '317877