INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3000078', '舞出我人生3', '剧情', '和前几集不同，这次影片采用了3D立体电影形式，可以让观众有身临其境的感觉。史上第一次国际性街舞对战，将在纽约举行!来自世界各地藏龙卧虎的顶级高手，都将在此一决高下!和卢克（瑞奇·马兰博瑞 Rick Malambri 饰）一起组成团队的，个个都是不怕虎的初生牛犊。刚刚考入纽约大学的可爱小子莫斯(亚当·G·瑟瓦尼 Adam G. Sevani 饰)、永不言败的自信美眉娜塔莉(沙妮·文森 Sharni Vinson 饰)、一脸孩子气但舞技惊人的卡米尔(艾莉森·斯卡里奥缇 Allison Scagliotti 饰)、高大威猛的肌肉大块头杰森。他们，每个人都做出了破釜沉舟的决定。尽管对于他们中的某些，这可能意味着耽误学业，意味着和家人反目，但为了追逐梦想，他们谁也不会后退……©豆瓣', '瑞奇·马兰博瑞', '朱浩伟', 7.7, 28897, 'tt1193631', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p620259526.jpg', 0.4, 3.1, 30.3, 45.2, 21, '0.361624,-0.159319,-0.798868,0.610620,-0.006110,-0.014644,0.584030,0.075383,-0.495429,0.018397,0.307246,0.782179,-0.302382,-0.028119,0.210447,-0.146253,-0.195884,-0.743772,-0.225506,-0.213292,-0.044748,-0.540696,-0.422537,-0.055052,-0.156149,-0.286188,0.490737,-0.127478,-0.065238,0.819481,0.492518,0.138302,0.037176,0.234584,0.051046,-0.237154,0.243424,-0.012878,-0.218976,0.244560,0.158600,0.178400,-0.155499,0.271801,0.153696,0.177379,0.483561,-0.349456,0.171787,0.056745,0.162163,-0.091264,0.011713,0.330145,0.129689,-0.312033,0.433250,0.265060,0.042676,0.264001,0.219711,0.113780,-0.986018,0.209332,0.290838,0.149771,-0.562692,0.544710,-0.034511,-0.232004,0.125123,-0.279635,0.212169,0.370437,0.508360,0.148702,0.135732,-0.069431,-0.529911,-0.075234,0.757111,0.114307,-0.370750,-0.008509,-0.271257,-0.443200,-0.365354,-0.495995,-0.364126,0.143494,0.059913,0.041873,-0.129718,0.140358,-0.565479,0.189676,-0.045638,-0.105763,-0.310785,-0.375669,0.083767,-0.605047,-0.041892,-0.617072,-0.366918,0.060992,0.158368,-0.270707,0.949101,-0.968692,-0.029451,0.373919,0.410481,-0.186292,0.737153,0.118855,-0.090627,-0.141004,-0.299787,0.018919,-0.053847,0.144858,0.008373,0.603360,0.283558,-0.288014,-0.112846,0.643308', '35144311', '35030151', '1793491', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3001077', '谍影重重4', '动作', '杰森·伯恩事件引起连锁反应，踏脚石（Treadstone）计划以及CIA用药物控制强化特工的行径通过报纸公之于众，令其幕后人物坐立不安。为了阻止满盘皆输的局面出现，CIA高层决定中止该计划，并将相关特工人员以及科学家从行动中抹杀。在此后的日子里，那些深藏在国家政治最底层、依靠蓝绿药丸执行各种绝密任务的特工相继殒命，而负责染脏双手的执行人——前美国空军上校艾瑞克·贝尔（爱德华·诺顿 Edward Norton 饰），正慢慢将屠刀伸向隐藏在位于阿拉斯加崇山峻岭、暴雪深山中的特工艾伦·克劳斯（杰瑞米·雷纳 Jeremy Renner 饰）。突如其来的炮火袭击令艾伦意识到自己所处的危险境地，在之后的日子里，他不仅要在昔日同伴的追杀中求生，还必须设法找到那曾为他提供源源不断体能和智力的蓝绿药丸……©豆瓣', '杰瑞米·雷纳', '托尼·吉尔罗伊', 6.8, 142930, 'tt1194173', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1706819167.jpg', 1.3, 8.3, 48.5, 32.4, 9.4, '-0.034996,0.096732,-0.546528,0.580991,-0.000530,0.136313,0.488144,0.060565,-0.596329,-0.244079,0.422872,0.389814,0.144067,-0.275340,0.579404,-0.203617,-0.506976,-0.824042,-0.121899,-0.157275,-0.487519,-0.453856,-0.401646,-0.551369,0.061850,-0.533852,0.910966,0.167216,-0.365438,0.141918,0.018091,0.455281,-0.456376,0.286176,0.214851,-0.307027,0.163391,-0.432363,-0.479328,0.261774,0.120678,-0.440566,0.044333,0.158764,0.120698,0.404856,0.614134,-0.547899,-0.048665,-0.145816,0.135734,-0.500162,-0.013837,0.114944,0.343320,0.093845,-0.045538,0.197537,-0.319309,0.274570,0.184924,-0.111856,-0.832820,-0.206692,-0.034215,0.338753,-0.484909,0.194671,-0.112512,0.347928,0.211576,-0.318491,0.080891,0.390296,0.194831,0.176842,-0.226590,-0.091103,-0.226324,0.043962,0.351604,-0.362339,-0.008765,-0.040324,-0.144993,-0.269540,-0.028936,-0.240560,-0.170539,-0.233545,0.213499,0.335100,-0.198283,0.579265,-0.489280,-0.021266,-0.304159,-0.369527,-0.081494,-0.230042,-0.193332,-0.846623,-0.039295,0.091447,-0.120505,0.079767,0.042745,-0.241931,0.520285,-0.715339,0.142882,0.677789,0.130370,-0.427166,0.052962,-0.098245,0.429198,-0.235681,-0.314233,0.244089,0.260056,0.510084,-0.021724,0.093801,0.016643,-0.258571,-0.143639,0.221153', '2369613', '25723905', '20274039', '1046