INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3001114', '沙丘', '剧情', '电影《沙丘》为观众呈现了一段神秘而感人至深的英雄之旅。天赋异禀的少年保罗·厄崔迪被命运指引，为了保卫自己的家族和人民，决心前往浩瀚宇宙间最危险的星球，开启一场惊心动魄的冒险。与此同时，各路势力为了抢夺这颗星球上一种能够释放人类最大潜力的珍贵资源而纷纷加入战场。最终，唯有那些能够战胜内心恐惧的人才能生存下去。', '蒂莫西·柴勒梅德', '丹尼斯·维伦纽瓦', 7.7, 549659, 'tt1160419', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2687443734.jpg', 0.8, 3.9, 26, 47.3, 22, '-0.217533,0.593097,-0.677926,0.971540,0.029010,0.181766,0.401652,0.013877,-0.653668,0.083535,0.237335,0.832870,0.202125,-0.088540,0.266519,-0.240092,-0.080392,-0.344707,-0.156569,-0.213042,-0.309141,-0.052795,-0.601127,-0.561096,-0.159262,-0.713418,1.355340,0.761188,-0.431705,0.072116,0.089404,0.530981,-0.121853,0.129585,-0.050356,-0.684521,0.009185,-0.080880,-0.711039,0.370167,-0.410392,0.031565,-0.015667,0.657897,-0.306224,-0.410275,0.804862,-0.550611,0.114114,-0.433452,0.307158,-0.354847,0.017413,-0.117157,0.201531,0.047689,0.249928,0.191319,0.206361,0.089288,0.240970,-0.271318,-1.462904,-0.396131,0.251852,0.068640,-0.219769,0.128336,0.264666,-0.311922,-0.033016,-0.072283,0.204143,0.463871,0.483833,0.230849,-0.411951,-0.092001,-0.167505,0.077626,1.022682,-0.501166,-0.138363,0.306438,-0.433132,-0.597609,-0.331574,-0.580834,-0.710139,-0.021018,0.450694,0.449285,0.014646,0.550720,-0.857143,0.238943,-0.298310,-0.335139,0.002787,-0.561355,0.037242,-0.386827,-0.271041,0.194805,0.064621,0.251108,0.261788,-0.357201,1.352712,-0.549278,-0.045783,0.741168,0.309903,-0.477131,0.658989,-0.240789,0.176432,-0.367226,-0.153574,0.588562,-0.277832,0.333104,-0.472187,-0.048109,-0.075923,0.029753,-0.264877,0.560650', '27602116', '26667010', '3718665', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3001142', '韩塞尔与葛雷特', '剧情', '因母亲染病，青年李恩洙（千正明 饰）驱车向家中赶去，但中途遭遇车祸，翻到路边。当他从昏迷中醒来时，发现眼前站着一个有如天使般的女孩子（沈恩京 饰）。在这个名叫英姬的女孩的引导下，恩洙随之来到了女孩位于密林深处的家。那是一幢宛如从童话书中出来的梦幻而华美的大房子，家中摆放着各种各样精巧可爱的饰品。这里住着英姬、她的父母、哥哥万福（殷元宰 饰）以及妹妹贞顺（陈智熙 饰）。疲劳疼痛的恩洙起初并未察觉丝毫一样，可是他很快便发现，如此美好的童话所在竟成为永远无法逃离的樊篱……本片荣获2009年葡萄牙奇幻国际电影节评委会特别奖。©豆瓣', '千正明', '任弼星', 7.1, 7944, 'tt1002567', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p628104789.jpg', 1, 6.1, 43.2, 36.1, 13.5, '0.239739,0.148862,-0.751635,0.419775,0.082209,-0.180230,0.938582,0.190811,-0.565399,-0.334588,0.404681,0.720146,-0.243926,0.498140,0.267648,0.303587,-0.327531,-0.432508,-0.290876,-0.237300,-0.297245,-0.121123,-0.137899,0.127016,0.149360,-0.276767,0.568276,0.058035,-0.146099,0.626512,0.184659,0.225088,-0.428000,0.416968,-0.319766,0.174122,-0.193934,0.166674,-0.025720,0.318009,-0.123938,-0.363023,-0.162170,0.070087,-0.255947,0.179127,0.688880,-0.462589,-0.099389,-0.083191,0.587968,0.094055,-0.014715,0.148485,0.129299,0.052771,0.208226,-0.206620,-0.310087,0.192645,0.195199,-0.236853,-0.187823,0.089483,0.242587,0.321905,-0.708696,0.226855,0.069323,-0.192600,0.189785,-0.350872,0.221856,-0.071680,0.017099,0.424054,-0.201636,0.216468,-0.606102,0.214171,0.355755,0.170009,-0.262319,0.492962,-0.143431,-0.360619,-0.025644,0.024814,-0.482369,0.071522,0.252109,0.219816,-0.038447,-0.053728,-0.456851,0.075785,-0.162408,-0.031987,-0.108669,-0.179359,-0.370307,-0.518942,0.135774,-0.258570,-0.219011,0.197672,-0.242513,-0.005932,0.392959,-0.463466,0.518228,0.403039,0.161719,0.059750,0.649560,-0.362696,0.028293,0.097684,-0.218971,0.547244,-0.038441,0.271808,-0.220680,0.282286,-0.377125,-0.195407,-0.503321,0.337792', '21619567', '1467779', '1296534', '1302133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3001149', '机械心', '剧情', '19世纪末的爱丁堡，在一个极度寒冷的冬天，痛苦的孕妇找到被人称作巫婆的玛德莲大夫（Marie Vincent 配音）。不久，一个孱弱的婴儿降临人间，但是这个小家伙的心都冻僵了，为此玛德莲帮他安装了机械心脏。孩子的生母不告而别，玛德莲将其作为亲生儿子抚养，并起名杰克（Mathias Malzieu 配音）。她告诫杰克不可以生气，避免强烈的情绪起伏，尤其要避免陷入爱恋。小杰克一天天长大，在他十岁的那年他首度来到镇上玩耍，并和命运中的天使邂逅。他的机械心脏出了故障， 冒出浓烟，他知道他恋爱了。从这一天起，杰克注定要踏上追寻爱情的征程……本片根据马提亚斯·马吉尔（Mathias Malzieu）的原著改编。©豆瓣', '马赛厄斯·马尔修', '施特凡·柏拉', 8, 28399, 'tt1181840', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2167571462.jpg', 0.4, 2.2, 22, 46.2, 29.3, '0.115795,0.173929,-0.792574,0.403610,-0.194025,-0.308268,1.027048,0.134245,-0.279132,-0.151399,0.318005,0.888226,-0.216273,0.380993,0.115925,0.222065,-0.159090,-0.441702,0.031950,-0.081406,-0.279049,-0.237354,-0.075655,-0.211219,0.028678,-0.426088,0.623163,0.062993,-0.164937,0.279183,0.002695,-0.024018,0.173698,0.319960,-0.261862,0.219607,-0.250795,-0.031736,0.166118,0.155900,0.154274,-0.110119,0.110853,0.203022,-0.273516,0.495984,0.826433,-0.401237,0.052872,-0.183311,0.539940,-0.390128,-0.165841,0.090337,0.067246,0.033673,-0.226771,0.044434,-0.279941,0.102142,-0.006983,-0.222155,-0.571012,0.045558,-0.061825,0.208466,-0.626942,0.315603,-0.023990,0.189938,0.075317,-0.306527,0.236457,0.295708,0.042480,0.695491,-0.518207,0.190176,-0.412137,0.181606,0.771401,-0.298488,-0.318788,0.349002,-0.489473,-0.443610,0.049320,-0.298641,-0.674969,-0.084594,0.348712,0.062421,-0.522132,0.425558,-0.368644,0.024398,-0.199057,-0.223730,-0.108078,-0.321749,-0.019341,-0.306563,-0.223152,-0.255809,-0.197288,-0.108623,0.065136,-0.368694,0.626194,-0.671693,0.380026,0.839103,0.138525,-0.168645,0.470042,0.153790,0.033103,-0.304414,0.078652,0.679942,-0.077165,0.275873,0.103364,0.361508,-0.061148,0.276374,-0.522476,0.549167', '21619567', '1428054', '1296534', '1292217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3001184', '遁入虚无', '剧情', '一场车祸夺去了父母的性命，年幼的奥斯卡和妹妹琳达发誓永不分开。成年后，奥斯卡（Nathaniel Brown 饰）漂泊来至东京，为了实现童年的誓言，他以兜售毒品赚取钱财，终于为琳达（Paz de la Huerta 饰）挣得了飞来东京的机票。兄妹相遇，却终是随波逐流的个体。在这个繁花乱坠迷人眼的大都会，奥斯卡继续进行毒品交易，而琳达则在一家夜总会大跳艳舞。在一次交易时，奥斯卡遭到警察围捕，混乱中更被枪击身亡。他的意识渐渐脱离肉体，穿梭在东京的大街小巷，关注跟随每一个在他生命中留下痕迹的人，等待着下一场不知何时才会开始的轮回……本片荣获2009年Sitges – Catalonian国际电影节最佳摄影奖和评委会特别奖。©豆瓣', '内森奈尔·布朗', '加斯帕·诺', 7.7, 10948, 'tt1191111', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2148705476.jpg', 2, 5.9, 24.3, 38.4, 29.4, '-0.204196,0.174588,-0.671373,0.432585,0.106587,-0.355690,0.514599,0.044115,-0.221077,0.120073,0.443903,0.942766,-0.238873,0.048430,0.250851,-0.180315,-0.250313,-0.741441,-0.181376,-0.228880,-0.292537,-0.267353,-0.149119,0.076975,-0.214807,-0.047269,0.586579,0.176684,-0.110982,0.623052,0.421654,0.057578,-0.259415,0.287535,-0.261638,0.020835,0.083080,0.178426,-0.359672,0.288468,-0.035527,-0.600301,-0.034093,-0.021498,-0.024030,0.217344,0.917210,-0.269299,0.106630,-0.184648,0.557608,-0.322290,-0.035605,0.020241,0.319689,0.146545,0.101571,0.091922,-0.441432,0.125507,0.089228,-0.101715,-0.782814,-0.052306,0.056782,0.271451,-0.610691,0.370822,-0.006657,0.117159,0.086621,0.015788,0.304943,0.538501,0.188751,0.108812,-0.318554,-0.124724,-0.551811,0.363474,0.805918,-0.219962,-0.100296,0.321338,-0.133631,-0.472085,-0.081945,-0.152649,-0.325881,-0.096387,0.402232,0.115533,-0.109627,0.336639,-0.573927,0.004509,-0.147181,-0.309339,0.002243,-0.168948,-0.309438,-0.692027,0.053715,-0.117845,-0.155596,0.222704,0.014040,-0.274884,0.500008,-0.725699,0.361555,0.725483,0.489965,-0.286501,0.695870,-0.046196,0.186288,-0.041065,-0.064237,0.459824,-0.050675,0.439511,0.022060,-0.019969,-0.172640,0.106589,-0.312058,0.505110', '1309194', '11541282', '3326747', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3001472', '青春爱欲吻', '剧情', '14岁的小女孩乔治娅·尼克尔森（乔治娅·格洛梅 Georgia Groome 饰）刚刚步入青春期，她的叛逆和倔强随之而生。这个年龄的她不再为了糖果和洋娃娃欢呼雀跃，虽然父母仍旧将其看作一个小孩子，但她已经开始为了朦胧的爱情怦然心动了。升入中学，一众死党感受到来自自身和外界的冲击，她们讨论乳房、初恋、接吻，一切都让懵懂的女孩们激动不已。与此同时，乔治娅迷上了阳光帅气的男孩罗比（亚伦·约翰逊 Aaron Johnson 饰），从此每一天都变得多姿多彩起来……本片根据英国作家露易丝·任尼森（Louise Rennison）系列日记体小说的“Angus, Thongs and Full-Frontal Snogging”和“It’s Okay, I’m Wearing Really Big Knickers”改编，并荣获2008年巴斯特国际儿童电影节观众奖和最佳儿童演员奖（Georgia Groome）。', '乔治娅·格洛梅', '顾伦德·查达哈', 7.1, 36857, 'tt0963743', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p553177612.jpg', 1.1, 6.2, 42.1, 38, 12.5, '0.287244,0.006633,-0.618008,0.654063,-0.168859,-0.174193,0.698789,0.077551,-0.289776,-0.281327,0.053309,1.002881,-0.513619,0.436207,0.348279,0.202750,-0.614598,-0.824514,-0.152281,0.097563,-0.048090,-0.217462,0.005997,-0.065384,-0.209526,-0.353077,0.753537,-0.158576,0.040353,0.585948,0.444812,0.034994,0.119796,0.314727,-0.015931,0.202977,0.149350,-0.062101,-0.031342,0.037714,0.012879,0.025879,-0.062622,0.267780,0.091733,0.194756,0.812317,-0.363278,0.164896,-0.083031,0.475334,-0.239867,-0.154876,0.199469,0.107747,-0.010245,0.441037,-0.230147,0.061879,0.089557,-0.137288,-0.259071,-0.517354,0.204846,0.343429,0.146782,-0.083414,0.357201,-0.057604,0.078461,0.259757,-0.013682,-0.127290,0.243567,-0.097753,0.464208,-0.331132,-0.040042,-0.324179,0.366769,0.443016,0.303110,-0.420684,0.410899,-0.737537,-0.543648,-0.220856,-0.133290,-0.513912,0.149760,0.332777,0.117513,-0.039736,0.537997,-0.694192,-0.025762,-0.016148,-0.152379,-0.016145,-0.666464,-0.243651,-0.625797,0.012668,-0.428544,-0.169310,-0.075353,0.059637,-0.401074,1.049980,-0.796176,0.059766,0.434268,0.195862,-0.136808,0.568279,-0.121481,-0.021391,-0.374404,-0.383724,0.824235,-0.122507,0.026261,-0.179325,0.492389,-0.196015,0.016150,-0.359783,0.712518', '3811356', '1307146', '1870681', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3002065', '一公升的眼泪追忆篇', '剧情', '亚也（沢尻エリカ饰）逝去后，池内一家人内心的悲痛渐渐平复，生活也重新走上轨道。而亚也的影响依然无处不在：留在人们记忆中的除了她的音容笑貌外，她已成为勇气和信念的化身。为了能帮助更多的人，妹妹亚湖（成海璃子饰）选择成为一名护士。亚也生前的恋人麻生（錦戸亮饰）也当上了神经科医师，为探究“脊椎小脑变性症”这种疾病而努力。亚湖注意到麻生似乎变得有些消沉，对待人和事都不怎么积极，她为此忧心忡忡。一日，病人長島（岡本杏理饰）无意间看到亚也的文字，好奇的她向麻生询问亚也的事迹，记忆的匣子打开了，麻生终于敞开自己的心扉，细细讲述亚也的故事……©豆瓣', '泽尻英龙华', '村上正典', 7.8, 9895, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1899152472.jpg', 0.6, 3.4, 29, 40.5, 26.6, '0.047204,0.059048,-0.360326,0.587821,0.096881,-0.425118,0.681344,0.086784,-0.511209,-0.565067,0.010259,0.726441,-0.077449,0.450162,0.223444,-0.020618,-0.572994,-0.704339,0.028667,0.162833,-0.423200,-0.418385,-0.183595,-0.455958,-0.230075,-0.508136,0.620630,0.388959,-0.171994,0.371105,0.039723,0.354249,0.071299,0.487619,0.304409,-0.138775,-0.358728,0.009392,-0.058626,-0.134122,0.060348,-0.300038,-0.199135,0.620056,0.150787,0.324826,0.681263,-0.318074,-0.115412,0.140146,0.201747,-0.095828,-0.078040,0.027867,0.099267,0.008263,-0.024429,0.265079,-0.479383,0.062060,-0.292165,0.105288,-0.587982,-0.065083,-0.025878,0.339116,-0.345901,0.226602,0.174049,0.053703,0.199344,-0.034831,0.108570,0.171050,0.189478,0.494266,-0.608808,0.115273,-0.108844,-0.115648,0.440436,0.019068,-0.085385,0.568799,-0.468940,-0.670210,-0.333541,-0.213069,-0.167978,-0.297850,-0.124170,0.590082,-0.098899,0.472216,-0.428790,-0.040739,-0.133523,-0.288665,0.077245,-0.260097,0.139945,-0.370127,-0.219719,-0.300819,-0.273948,0.049592,0.069998,-0.442006,0.835407,-0.485466,0.134020,0.327689,0.002003,-0.520026,0.764878,-0.005119,-0.150092,-0.241895,-0.361564,0.915011,0.075317,0.289494,-0.102729,0.128831,-0.159126,0.013060,-0.404898,0.618935', '3001472', '3882427', '30349667', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3002819', '花花型警', '动作', '麦克（余文乐 饰）是全港破案率最高的警察，这是因为他有钱，更确切地说，是他爸爸有钱。用金钱作诱饵、用金钱收买线人，这让他的破案纪录屡屡上升的同时也收获了同事给他的称号：花花型警。没有人相信他能不用金钱破案。一次破案时麦克再次给警队带来大麻烦——从空中洒下金钱导致交通瘫痪——于是被停职。而从大陆过来调查哥哥死因的同样家财万贯的林亨（陈坤 饰）正好认识麦克，相识当天，二人穿着同样的西装，打着同样的领带，冥冥中的缘分，更巧合的是，麦克的前女友lisa（钟嘉欣 饰）对林亨形影不离。一个要查出真凶，一个要证明自己的能力。林亨与麦克结伴而行，从获得线索开始，他们渐渐发现，自己被凶手带入了一个陷阱，险象环生中二人建立了非同一般的友情，然而结局并非我们所想的美好。©豆瓣', '余文乐', '马楚成', 5.7, 24628, 'tt1194582', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2028206530.jpg', 5.9, 23, 55.1, 13.2, 2.8, '0.266793,-0.014658,-0.490530,0.651665,-0.331560,-0.128150,0.641004,0.049724,-0.524311,-0.100766,0.235838,0.632853,0.077470,-0.076938,0.192413,-0.078526,-0.276947,-0.666545,0.319683,-0.312404,-0.471927,-0.644761,-0.319475,-0.284504,-0.166766,0.010026,0.372803,0.126071,-0.186583,0.441065,0.444417,0.137800,0.159666,0.453639,-0.248817,-0.069269,0.024244,-0.013405,-0.202760,0.432423,0.023906,-0.127681,-0.015893,0.257123,-0.163613,0.434106,0.444772,-0.091557,-0.110742,-0.001488,0.474504,-0.348237,0.052213,-0.115544,0.217796,0.021430,0.189485,0.186227,-0.273666,-0.040371,0.169696,-0.030753,-0.970550,0.041755,0.069318,0.166798,-0.410057,0.324413,-0.277666,-0.140905,0.050395,-0.194330,0.190099,0.424348,0.377166,0.097820,-0.099563,-0.232609,-0.683279,0.210315,0.549605,0.000476,-0.054520,0.440569,-0.366706,-0.328102,-0.019151,-0.039118,-0.126166,0.123169,0.576032,0.081060,-0.087562,0.081403,-0.545193,-0.026707,-0.229223,0.008362,-0.175795,-0.549565,-0.068123,-0.341222,-0.296575,-0.376775,-0.339780,0.162895,0.163861,-0.437589,0.636472,-0.692261,-0.162836,0.658539,0.255703,-0.493898,0.631965,0.041199,0.017740,-0.394906,-0.214809,-0.124598,0.314043,0.449542,0.249195,0.217366,0.113906,-0.230007,-0.284208,0.206535', '3785918', '1793491', '26678784', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3002820', '神枪手', '剧情', '凌靖（黄晓明 饰）连续四年成为香港警察狙击手队伍的第一神枪手，上司与队友对他赞赏有嘉，可自视甚高的他却不大喜欢跟人家打交道，他唯一的幸福就是太太的陪伴。一次剿匪行动中，凌靖失手打死人质——城中首富独子。富商向警察部不断施压，最后凌靖被判误杀入狱四年。自从凌靖离开，原来警队第二的克明（任贤齐 饰）成为了最强的一个，当年正是他做假证害凌靖入狱。凌靖发誓要向出卖他的警队和克明报仇。O仔（陈冠希 饰）是警校的高材生，枪法如神、用枪技术一流，很快被克明招揽加入香港警察狙击队队伍。在听说在凌靖的故事后对他感到好奇，在偶然的机会下遇到凌靖并得到指导，成为朋友。凌靖频繁挑衅警队，引得整个狙击手队伍出动围捕他。凌靖拼死力战，独战警队。怎料，克明以自己作饵，加上O仔的助攻，让他不慎暴露了位置。最后，到底哪方会胜利？而凌靖又可以为自己找到应有的公平吗？©豆瓣', '任贤齐', '林超贤', 5.9, 31535, 'tt1194624', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2212582547.jpg', 4, 19.5, 56.6, 15.8, 4.1, '-0.039975,-0.178157,-0.511093,0.487011,-0.122977,-0.203335,0.366262,-0.180873,-0.540154,-0.092553,0.480867,0.645303,0.135107,0.062074,0.154379,-0.167068,0.068318,-0.713481,-0.000549,-0.264118,-0.226061,-0.346647,-0.182443,-0.121229,0.003127,-0.102955,0.555938,-0.092096,-0.350917,0.449591,0.496926,0.239486,0.081562,0.294981,-0.203825,-0.005380,0.133881,-0.235440,-0.456740,0.299781,-0.083800,-0.281621,-0.240299,-0.035460,0.061582,0.271892,0.517639,0.094952,-0.218755,-0.157713,0.264132,-0.443380,-0.137649,-0.135739,0.387848,0.110138,0.178108,0.182555,0.187124,-0.035264,-0.194303,0.017426,-0.779778,0.156647,0.208574,-0.124640,-0.588627,0.347093,-0.161809,0.041545,0.134729,-0.058493,0.144653,0.260704,0.139629,-0.029407,-0.282431,0.170288,-0.409047,0.227206,0.633954,0.001830,-0.014138,-0.096890,0.279556,-0.325726,0.302468,-0.409254,-0.160343,0.278367,0.271626,-0.248271,0.050331,-0.080018,-0.128321,-0.099052,-0.224110,-0.036753,0.016260,-0.437769,-0.011737,-0.480787,0.147786,-0.195842,-0.359393,0.241936,0.038731,-0.379600,0.549378,-0.952792,0.059844,0.654344,0.241774,-0.749043,0.541719,0.244492,0.065732,-0.316678,-0.220594,0.062942,0.350702,0.211623,0.158974,0.153848,-0.081429,-0.372011,-0.197942,0.041048', '30345227', '1877596', '3503015