INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3003137', '洋葱电影', '喜剧', '洋葱电视台以新闻播报准确及时而著称，同时还制作许多专题采访节目，比如采访动作明星“击蛋侠”（史蒂文•西格 Steven Seagal 饰）和清纯流行偶像歌手梅丽莎•雪莉（莎拉•迈克埃利戈特 Sarah McElligott 饰）等。随着美国的全球性文化输出，就连在中东恐怖分子集训营受训的恐怖分子也偷看洋葱电视台的节目。电视台的新闻主播诺姆•阿彻（莱恩•卡利欧 Len Cariou 饰）反对高层与大公司合营的决定，尤其对新闻播报时插播玩具企鹅的广告不满。忍无可忍的诺姆决定在某次直播过程中宣布自己深思熟虑的宣言，但就在开口之际，洋葱电视台突遭恐怖分子袭击，诺姆被挟持，事态严峻。©豆瓣', 'Daniel Chacón', 'Tom Kuntz', 7.6, 53541, 'tt0392878', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p779407026.jpg', 0.9, 4.1, 28.8, 44.8, 21.4, '0.186558,-0.106226,-0.461735,0.400622,0.533259,0.100639,0.258229,0.494624,-0.337693,0.069304,0.155353,0.500575,-0.910835,-0.201918,0.389810,-0.195515,-0.565086,-0.826461,-0.071094,0.196070,0.107745,-0.411283,-0.053790,-0.310867,0.114663,-0.170799,0.420527,-0.056742,-0.240574,0.341962,0.554938,0.156649,-0.200532,0.485857,0.290514,-0.215759,0.648371,-0.191900,-0.233515,0.251288,-0.023333,-0.181113,-0.110846,0.292801,0.292109,0.329803,0.211735,-0.053963,-0.007383,-0.017861,0.464590,-0.276161,0.170452,0.114305,0.609080,0.034482,0.447211,-0.133384,-0.054233,0.173806,-0.143690,-0.143458,-0.451632,0.182179,-0.241563,0.394675,-0.373062,0.363925,-0.461148,0.267329,0.196614,-0.338265,-0.033677,0.182125,0.485463,0.227238,0.332773,0.111446,-0.104640,0.345053,0.015531,0.237858,-0.320579,0.280768,-0.045938,-0.376325,-0.237329,-0.064044,-0.543229,0.131125,0.340205,-0.448806,-0.196861,0.320034,-0.466426,-0.226624,-0.102557,-0.699540,0.116091,-0.118046,-0.219420,-1.458717,0.113204,0.094143,0.069446,-0.027059,0.282175,0.048664,0.742729,-0.740259,0.134299,0.684784,0.079305,-0.366958,0.406372,0.060976,-0.146140,-0.362613,-0.192674,-0.054026,0.217508,0.079823,0.001192,0.219433,0.197087,-0.750861,-0.198297,0.256806', '34961898', '6517421', '24751811', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3003192', '僵尸脱衣舞娘', '喜剧', '在不远的将来，美国总统布什第四次获得连任，他解散国会，在世界范围内散播战火，为了能源源不断的提供兵源，政府研制了能够将人化为僵尸战士的病毒，岂料病毒扩散，军方派遣一支精英小队平息事端，一名队员被咬伤后逃走……脱衣舞俱乐部“犀牛”中，老板艾斯寇（罗伯特•英格兰德 Robert Englund 饰）迎来了新人杰西，暗恋杰西的小伙子戴维斯亦随之潜入犀牛。当夜舞女们的表演令一票观众疯狂，突然被僵尸咬啮的战士当场将当家舞女凯特（詹娜•詹姆森 Jenna Jameson 饰）咬死，谁知凯特死而复生，并因病毒在女性身上可以保持纯洁的特性而未丧失理智，僵尸化的凯特舞技大增，一干舞女因无法忍受被观众忽视纷纷献身僵尸，只顾赚钱的艾斯寇决定将事情隐瞒，僵尸舞女们在犀牛中大放光彩……©豆瓣', '詹娜·詹姆森', 'Jay Lee', 5.3, 6680, 'tt0960890', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1769722619.jpg', 12.4, 30.4, 39.9, 12.1, 5.1, '0.248655,0.010524,-0.341167,0.178145,-0.112584,0.106739,0.659436,-0.061622,-0.402048,-0.022245,0.330416,0.539368,-0.395334,-0.217003,0.194077,-0.431365,0.058483,-0.533963,-0.102840,0.035091,-0.139171,-0.017379,-0.186314,-0.592459,-0.119803,-0.603760,0.880686,-0.019319,-0.057189,0.509171,0.258304,0.465706,-0.000524,0.278617,0.080032,-0.064136,0.213771,-0.553229,-0.039741,0.524634,-0.070024,-0.313419,0.124631,0.093218,-0.122408,0.015343,0.857880,-0.561692,0.314060,-0.596255,0.135288,-0.274539,0.330391,0.277862,0.407076,-0.022645,0.122441,0.079467,0.083610,0.043172,0.142518,0.098350,-0.533741,-0.065900,0.060274,0.324628,-0.406540,0.345460,-0.019188,0.233935,0.217716,0.041358,-0.148293,0.131725,0.128772,0.149473,0.065049,0.154257,-0.542823,0.268349,0.590267,-0.326635,-0.344519,0.137869,-0.321229,-0.547043,-0.111382,-0.260392,-0.222705,-0.165066,0.462308,0.262305,-0.023243,0.391567,-0.531944,-0.201529,-0.363114,-0.352824,-0.202176,-0.057203,-0.292629,-0.531888,0.038376,0.315393,0.082265,0.003508,0.122373,-0.041844,0.734334,-0.750108,-0.027627,0.672571,0.344314,-0.497214,0.339735,-0.378953,0.253072,0.024067,-0.196737,0.045343,0.271516,0.383973,0.461167,0.364331,-0.240428,-0.215037,-0.044150,0.302763', '3811356', '26759820', '1826173', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3003830', '恋空', '剧情', '漂亮乖巧的高一女生美嘉（新垣結衣 饰）不小心丢了手机，被樱井弘树（三浦春马 饰）捡到，放在图书馆归还给她。然而弘却把美嘉手机里所有的联系人方式都删掉了，自己就在整个暑假日日夜夜给美嘉打电话，有一搭没一搭地闲聊。虽然素未谋面，美嘉的心扉已经渐渐打开。开学正式见面后二人坠入爱河，共尝禁果。不久却被弘的前女友笑子报复，酿成悲剧，美嘉伤心欲绝，弘强有力的保护让美嘉度过这次难关。很快，美嘉怀孕了，弘请求她把孩子生下来，二人会见双方家长，弘诚恳坚决的请求得到了大家的体谅。但悲剧再次发生，美嘉失去了孩子。更大的打击来自高二开学后，弘提出分手。因为得不到一个确切的理由，美嘉苦守许久才渐渐开始新生活，和庆大的温柔的男生优恋爱，升大学，一切都好像好起来，这年圣诞，优向美嘉求婚，但随即而来，美嘉知道了弘一直隐瞒自己的悲伤的秘密……一切都被打破了，美嘉知道自己最爱的，仍然是弘。', '新垣结衣', '今井夏木', 7, 213521, 'tt1194664', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p634019904.jpg', 2.9, 9.5, 38.5, 32.6, 16.5, '0.451822,0.135141,-0.743920,0.020899,-0.147003,-0.342674,0.335631,0.109147,-0.340377,0.024133,0.030752,0.663665,-0.352008,0.350824,0.118427,0.113019,-0.298189,-0.889072,0.222862,-0.173215,-0.140038,-0.509794,0.310507,0.310611,0.055298,-0.205754,0.284418,-0.290172,0.112812,0.645333,0.179330,0.051722,0.123192,0.617646,-0.031504,0.350506,0.045366,0.006178,-0.165941,0.153349,0.277482,-0.286941,-0.407587,0.519415,0.209494,0.421552,0.686221,-0.138706,-0.312212,0.194541,0.402261,-0.412065,-0.499314,0.170993,0.328059,0.136353,0.202443,0.357456,-0.355368,0.287134,0.020470,0.050683,-0.343203,0.140231,0.002244,0.024442,-0.310827,0.659469,0.175838,0.028971,0.192366,-0.344615,0.133902,0.440440,0.083332,0.354949,-0.435793,0.432623,-0.069450,0.068600,0.569439,-0.143731,-0.147574,0.436987,-0.018063,-0.154015,0.157729,-0.111389,-0.663710,0.222408,0.321432,0.146663,-0.306782,0.160965,-0.576254,-0.130777,-0.460829,-0.211768,0.202411,-0.373647,-0.341902,-0.076926,-0.211154,-0.075419,-0.568608,-0.056458,-0.052157,-0.322513,0.836804,-0.921159,0.189216,0.324534,0.459389,-0.319669,0.287256,0.221134,0.066806,-0.230985,0.173544,-0.064221,-0.192000,0.297068,0.197375,0.360929,-0.151185,-0.012214,-0.591480,0.327830', '1292219', '1826173', '3091208', 