INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3003836', '小屁孩日记', '喜剧', '本片根据美国作家杰夫·金尼（Jeff Kinney）的同名畅销儿童系列读物改编。第一天升入初中的格雷·郝夫利（扎克瑞·戈登 Zachary Gordon 饰）忐忑不安，拼命想要突出表现成为班级年鉴中的明星。格雷的哥哥罗德里克（戴文·博斯蒂克 Devon Bostick 饰）给了他一堆不能这样也不能那样的忠告，他的好朋友罗利·杰佛森（罗伯特·卡普荣 Robert Capron 饰）却不以为然，继续沿用小学时那一套穿戴、用语、态度，让格雷十分头疼。格雷拒绝了女孩安琪（科洛·莫瑞兹 Chloe Moretz 饰）加入校报的邀请，拉着罗利加入了校安全巡逻队。在逃避万圣节得罪的三个小混混时格雷犯了错误，却又缺乏勇气承认，听任罗利替自己背了黑锅。后续事件的发展越来越糟，格雷在学校的受欢迎度直线掉落，就连他与罗利的友谊都岌岌可危……©豆瓣', '扎克瑞·戈登', '托尔·弗罗伊登塔尔', 7.2, 42969, 'tt1196141', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p500460679.jpg', 0.4, 4, 42.5, 40.6, 12.4, '0.425492,-0.127810,-0.508760,0.283274,-0.149850,-0.430530,0.429012,0.415539,-0.395014,-0.039934,-0.036961,0.580021,-0.204608,0.046443,0.254568,-0.048417,-0.472987,-0.556528,0.153656,-0.173524,0.041796,-0.598571,-0.139431,-0.203868,-0.186283,-0.469206,0.500923,-0.228928,-0.252862,0.382033,0.439192,0.336377,0.210170,0.265905,-0.010386,0.088687,0.167425,-0.054853,0.145616,0.205139,0.063727,0.220765,-0.115690,0.165793,0.250529,0.359161,0.468251,-0.186496,-0.004524,0.073883,0.508272,-0.178509,-0.039155,0.105865,0.347771,-0.156505,0.017596,0.086557,-0.025807,0.167159,0.027518,0.088006,-0.423138,-0.049126,0.067098,0.125921,-0.682415,0.467651,-0.232034,-0.144991,0.223562,-0.417800,-0.082313,0.333123,0.339814,0.058229,-0.044204,0.010626,-0.299909,0.226358,0.275300,0.018416,-0.232938,0.060803,-0.328076,-0.224265,-0.118188,-0.198458,-0.451384,-0.036261,0.227814,-0.176661,-0.063849,0.056547,-0.269222,-0.255188,-0.346335,-0.247633,-0.294128,-0.357571,-0.024169,-0.461646,0.182245,-0.222648,-0.157561,-0.260248,-0.126851,-0.089490,0.618702,-0.613038,0.191009,0.418966,0.176780,-0.098765,0.306915,0.120441,0.120587,-0.191117,-0.074543,0.083704,0.152035,0.168676,0.196511,0.562259,0.317219,-0.384616,-0.030727,0.459118', '1292943', '1308609', '1301169', '1986338');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3003842', '陵园路口', '剧情', '在20世纪70年代的英国，三个蓝领好友整天过着相互逗乐，喝酒，打架，泡妞的生活。弗雷迪（克里斯蒂安·库克 Christian Cooke 饰）是一个保险推销员，但他想离开解工人阶级队伍，告别这样的生活方式。但是充满魅力的布鲁斯（汤姆·休斯 Tom Hughes 饰）和永远泡不到姑娘的失败者斯诺克（杰克·多兰 Jack Doolan 饰）却很享受这样的幸福生活。而当弗雷迪获得了一份上门推销保险的推销员工作后，却在一天意外遇到了他旧时的老相好朱丽（菲丽希缇·琼斯 Felicity Jones 饰），而同时，这个三人小团体也被迫抉择，是否要永远的改变他们当前的生活方式......©豆瓣', '克里斯蒂安·库克', '瑞奇·热维斯', 7.6, 8131, 'tt1196204', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2370863007.jpg', 0.4, 2.7, 29.5, 50.1, 17.3, '0.304414,-0.088062,-0.319276,0.558384,-0.375893,-0.520724,0.679732,0.267554,-0.333441,-0.289583,0.178531,0.829618,-0.074319,0.134883,0.312363,-0.020103,-0.303996,-0.523260,0.165871,-0.060181,-0.262412,-0.336802,-0.173502,-0.507268,-0.245089,-0.056581,0.576595,-0.202760,-0.036171,0.456371,0.263443,0.128864,0.135033,0.542793,-0.250829,-0.126709,0.083982,0.072428,-0.419033,0.307177,0.168054,0.165172,-0.346592,0.241573,0.125604,0.259599,0.480678,-0.140280,-0.088083,0.158647,0.149210,-0.225279,-0.082086,0.036359,0.068818,-0.267923,0.174626,0.015654,0.030821,0.042329,0.032596,0.089134,-0.545206,0.011005,-0.124922,0.134667,-0.647029,0.400185,-0.056442,-0.196248,0.002209,-0.371221,0.008522,0.418201,0.385677,0.288230,-0.241572,-0.090227,-0.658352,0.453227,0.638744,0.016890,-0.221148,0.519054,-0.444484,-0.316874,-0.109231,-0.121657,-0.785040,-0.211858,0.077004,-0.103244,-0.190482,0.112689,-0.948276,0.081513,-0.161683,-0.059261,0.126283,-0.556330,0.124535,-0.773726,-0.182223,-0.519077,-0.524153,0.069080,0.045408,-0.272482,0.647542,-0.864328,0.138005,0.696783,0.105945,-0.409552,0.709889,0.436595,0.102254,-0.250339,-0.085779,0.368541,-0.033862,0.089915,-0.092644,0.441905,0.303638,0.019290,-0.234279,0.549238', '6858739', '35161768', '11541282', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3004244', '破处之旅', '喜剧', '十八岁的伊恩（乔什·朱克曼 Josh Zuckerman 饰）一直被好友奚落为“美国最后一个处男”，他一直被发好人卡，泡妞技术还不如14岁的弟弟。在网上认识一个叫“DANIELLE”的女孩后，似乎转机到来了，对方答应只要他前往诺克斯维尔市见他，就会和他发生关系。带着破处的愿望，伊恩与两个好友——万人迷兰斯（克拉克·杜克 Clark Duke 饰）和假小子费莉西亚（阿曼达·克鲁 Amanda Crew 饰）一起上路了。其实费莉西亚是伊恩一直很有好感的女孩，但是她似乎一直钟情兰斯，三个人同行一路，遇到各种爆笑奇事，也渐渐发现自己心底真正的情感需求……©豆瓣', '乔什·祖克曼', '西恩·安德斯', 6.4, 7889, 'tt1135985', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p915815153.jpg', 2.9, 14.3, 51.3, 23.8, 7.7, '0.347631,-0.050194,-0.665835,0.488465,-0.126987,-0.361991,0.743747,-0.044632,-0.624839,-0.386679,-0.086530,0.828707,-0.495282,0.240608,0.250167,0.341857,-0.565417,-0.732309,0.183619,-0.238056,-0.050772,-0.380595,-0.238884,0.072742,-0.317153,-0.202474,0.292276,-0.285595,0.163349,0.448972,0.348498,0.304288,0.088215,0.633641,-0.043008,0.051278,0.303023,-0.132663,0.073791,0.211450,-0.052076,0.130750,-0.112558,0.048638,0.025422,0.438522,0.444808,0.112896,-0.018193,-0.104396,0.002853,-0.129528,0.180177,0.081666,0.089149,-0.158892,0.500593,0.141745,0.123751,-0.018149,0.194040,-0.040313,-0.404682,0.234354,-0.116472,0.127983,-0.423451,0.200622,-0.316352,-0.190912,0.213199,-0.338459,0.202680,0.446287,0.352963,0.021088,-0.305922,0.081250,-0.616215,-0.115465,0.594160,0.085278,-0.126475,0.174503,-0.292173,-0.515947,-0.116440,0.179230,-0.457273,0.095371,0.097913,0.141788,-0.348110,0.082166,-0.510358,0.150077,-0.283524,0.098477,-0.103805,-0.479713,0.083643,-0.562531,-0.129945,-0.581203,-0.544722,-0.095193,-0.049846,-0.261396,0.583160,-0.658994,0.187021,0.537611,0.492278,-0.260860,0.660399,0.344069,-0.291245,-0.257217,-0.026740,0.423125,-0.136745,-0.134488,0.065738,0.392126,0.223123,-0.117196,-0.037548,0.584126', '30162520', '1309172', '3055049', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3005365', '蓝调传奇', '剧情', '1941年，波兰裔移民里奥纳德·切斯（亚德里安·布洛迪 Adrien Brody 饰）为出人头地，开始经营一间酒吧。而此时密西西比的佃农麦肯利·摩根菲尔德（杰弗里·怀特 Jeffrey Wright 饰）怀揣音乐梦想背着一把吉他只身来到芝加哥，在街边他遇到了17岁的天才口琴演奏师小沃尔特，两人一拍即合，开始在切斯的酒吧驻唱。野心勃勃的切斯凭借自己敏锐的直觉和商业头脑，开办了切斯工作室（Chess Records），为沃特斯录制唱片，取得巨大成功。切斯在经营切斯工公室期间，广纳音乐人才，推陈出新，造就了一大批对美国乐坛影响深远的歌手……本片主题曲Once in a Lifetime在2009年金球奖上，获得最佳电影歌曲提名。©豆瓣', '艾德里安·布洛迪', '达内尔·马丁', 8.1, 15073, 'tt1042877', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p719411750.jpg', 0.1, 1.1, 19, 51.1, 28.7, '0.037623,0.043594,-0.468644,0.283949,0.224780,-0.283631,0.436357,0.402121,-0.673662,-0.259121,0.062916,1.102089,-0.055226,0.063435,0.523381,0.189720,-0.621641,-0.805068,0.130133,-0.114322,0.350858,-0.521890,-0.264229,-0.060035,-0.357497,-0.434873,0.460996,-0.154595,-0.095335,0.618573,0.223667,0.333949,0.216910,-0.196011,0.120879,0.084359,0.720399,-0.134597,-0.385525,0.392940,-0.236428,-0.177675,-0.396663,-0.321870,0.372216,0.152863,0.519733,0.175369,0.491330,0.032562,0.280269,-0.125308,-0.199884,-0.261694,0.243926,0.121924,0.263058,0.199304,-0.474424,-0.052004,-0.153015,-0.287014,-0.587835,0.213827,0.062236,0.226984,-0.604191,0.415858,-0.237982,-0.236815,0.015887,-0.242304,-0.202533,0.189597,0.238191,0.344141,-0.038078,0.286806,-0.524445,0.199196,0.472138,0.064921,-0.105595,0.331773,-0.044916,-0.402820,-0.252842,-0.438978,-0.401136,-0.361331,0.406510,-0.415567,0.279387,0.327325,-0.607161,-0.034639,-0.123292,-0.417400,0.158864,-0.236462,-0.173641,-1.019600,-0.134161,0.041396,0.003848,-0.246210,0.177917,-0.311910,0.756277,-0.806454,0.240778,0.495627,0.062588,-0.057328,0.665960,-0.238706,0.307544,-0.097402,-0.225109,0.424967,-0.022800,0.104677,-0.079727,0.351800,0.028456,-0.490314,-0.240189,0.534724', '1829654', '11541282', '25833539', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3005387', '怪兽在巴黎', '喜剧', '1910年，法国巴黎。电影院放映员埃米尔（Sébastien Desjours 配音）和他的朋友罗尔（Gad Elmaleh 配音）来到某科学家的实验室送货，科学家恰好不在，两个人胡乱动实验室的药品，结果引发大混乱，更令一只小跳蚤巨大化，变成恐怖的大怪物。怪物跳蚤逃出实验室，在巴黎引来了一阵骚乱和恐慌。而事实上，这只跳蚤温柔无辜，有着一颗纯洁的心。它偶然结识了美丽的酒吧驻唱歌手露西（Vanessa Paradis 配音），由此得名弗兰卡。弗兰卡具有令人惊叹的音乐天赋，它和露西的演出得到人们的欢迎。而另一方面，贪心的警察局长却想消灭怪物以壮大自己的威信。为了保护弗兰卡，埃米尔、罗尔和露西通力合作……©豆瓣', '丹尼·赫斯顿', '毕鲍·鲍格朗', 7.7, 20814, 'tt0961097', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p820534127.jpg', 0.4, 2.4, 28.9, 47.3, 21, '0.228672,-0.034553,-0.668060,0.319446,-0.054091,0.032247,1.059412,0.267037,-0.287610,-0.091691,0.314595,0.579520,-0.367048,0.106830,0.003658,-0.012558,-0.197011,-0.340101,-0.001016,-0.006016,-0.128272,-0.099895,-0.485605,-0.616893,0.087466,-0.353348,0.490352,0.130483,-0.344310,0.371211,0.131971,0.237428,-0.167350,0.164270,-0.043977,-0.094060,0.141146,0.055838,0.119309,0.023542,-0.049037,-0.109421,-0.210190,0.013322,-0.028485,0.159362,0.598621,-0.252762,-0.203139,-0.278801,0.300223,-0.434073,0.037100,-0.166756,0.146538,-0.033357,0.194496,-0.393921,-0.073463,0.034216,0.149685,-0.315146,-0.825547,0.174228,-0.071875,0.209568,-0.268607,0.422939,-0.110565,-0.063598,0.246575,-0.236791,-0.042517,0.105806,0.099813,0.474069,-0.181881,0.267638,-0.424844,0.097447,0.545541,-0.028018,-0.446565,0.239265,-0.461719,-0.605843,-0.065617,-0.236558,-0.332219,-0.141850,0.441892,-0.059769,-0.131583,0.235059,-0.710151,0.001634,-0.268269,-0.239582,-0.147228,-0.231569,-0.213465,-0.630665,-0.188520,-0.046762,-0.059840,-0.004778,0.107781,-0.278652,0.991493,-0.871686,0.080894,0.754583,0.211451,-0.292855,0.537402,-0.289714,-0.126298,-0.075472,-0.340667,0.202598,0.160366,0.309209,0.281964,0.291022,-0.024425,-0.179116,-0.536950,0.295227', '24284209', '3769423', '2053515', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3005496', '一个好爸爸', '剧情', '李天恩（古天乐 饰）少年时代便喜欢打架，后来成为了江湖老大，他与母亲恩妈（苗可秀 饰）互相斗嘴，是他们一贯的相处方式。陈美宝（刘若英 饰）与李天恩在警察局一见钟情，即使两人背景相差甚异，两人还是相爱了。可是当美宝告诉天恩自己已怀孕的时候，天恩犹如晴天霹雳，没有父亲的他根本不知道如何当一名父亲。应负的责任，李天恩还是逃不过的。天恩觉得自己的一生就要被妻儿困住时，女儿喜儿的出生让李天恩彻底改变了。天恩想尽办法对女儿隐瞒自己黑帮的身份，放弃做歪门邪道的生意，为了女儿他放下身段取悦女儿。期间天恩的母亲逝世了，也由于不景气，天恩的生意一落千丈。眼看社团的几位老前辈给予天恩的压力越来越大，天恩还是无奈的接受了。喜儿还是一天天的长大了，她也知道了父亲黑社会的身份，美宝希望天恩能就此退出江湖，可是社团却想在这时候推荐他做龙头老大，更把他欠债的事做威逼，天恩进退两难。为了对社团有交待，能从此退出，他决定与毒贩交易，被埋伏的警方发现了。愤怒的毒贩向天恩开了一枪……', '古天乐', '张艾嘉', 7.1, 35635, 'tt1196714', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2193260103.jpg', 0.6, 4.9, 42.9, 41.2, 10.3, '0.236299,0.130035,-0.589038,0.410145,-0.199038,-0.506989,0.500975,0.272085,-0.648192,-0.194048,0.317157,0.670271,0.047089,0.025375,-0.072015,-0.001641,-0.079442,-0.745300,0.166710,-0.270980,0.013639,-0.461268,-0.132179,-0.097704,-0.226528,-0.112921,0.431209,-0.105196,-0.208733,0.362159,0.398180,0.056011,0.346682,0.572103,-0.239154,0.071977,-0.054389,0.221303,-0.610853,0.100970,0.302687,-0.404488,-0.300917,0.210878,0.015362,0.269717,0.358695,-0.196185,-0.351828,-0.215034,0.180132,-0.296423,-0.031400,0.286818,0.298609,-0.004131,0.080284,0.357238,-0.191429,-0.205761,-0.056884,0.160321,-0.745037,0.120396,0.221899,0.180576,-0.741926,0.302463,-0.419908,-0.301379,0.039251,-0.557539,0.204009,0.426098,0.129807,0.563671,-0.408802,0.251694,-0.667124,0.145919,0.811266,0.045155,-0.025940,0.238719,-0.128349,-0.302091,0.063311,-0.217603,-0.532268,0.121698,0.202280,-0.029559,-0.190124,0.272563,-0.157695,-0.007712,-0.183027,-0.141811,-0.115006,-0.705257,0.095812,-0.032079,-0.388950,-0.450862,-0.260330,-0.191176,0.270061,-0.300083,0.780961,-0.831697,0.112526,0.366666,0.593880,-0.921327,0.695030,0.437468,0.050440,-0.195005,0.009906,-0.182705,-0.123912,0.441181,0.346165,0.210504,0.420021,-0.36