INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3005875', '2012', '科幻', '太阳活动异常，地球内部的能量平衡系统面临崩溃，玛雅人的预言即将实现，人类将遭遇灭顶之灾。各国政府已经联手开始秘密制造方舟，希望能躲过这一浩劫。以写科幻小说谋生的杰克逊（约翰·库萨克 John Cusack 饰）在带孩子们到黄石公园渡周末时发生一连串怪事，而且遇到了神经兮兮的查理（伍迪·哈里森 Woody Harrelson 饰)，查理告诉他世界末日即将来临。伴随着火山爆发，强烈地震以及海啸，杰克逊带领自己的家人驾驶一架临时租来的飞机冲出被死神阴霾瞬间笼罩的城市上空，开始寻找查理口中各国政府正在联合秘密制造的方舟。在生死攸关的时刻，一些伟大的鬼魂将脱颖而出，而一些自私的心灵将无所遁形，当千千万万个生灵通过各种方法来到方舟制造基地之时，方舟有限的容纳数量引发前所未有的恐慌。最终，仅存的人们用互爱和对生命的尊重渡过了难关。本片被称为《后天》的升级版，投资超过2亿美元，是灾难片大师罗兰·艾默里奇（Roland Emmerich）的最新力作。', '约翰·库萨克', '罗兰·艾默里奇', 8, 537291, 'tt1190080', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p505238859.jpg', 0.4, 1.9, 22.4, 49.5, 25.8, '0.113563,0.079234,-0.826750,0.325697,0.143353,0.235007,0.632406,-0.126843,-0.367130,-0.091924,0.374251,0.810955,-0.356397,0.010599,0.168994,-0.265777,-0.231967,-0.389170,-0.041422,0.018395,-0.298038,-0.428940,-0.379077,-0.120406,-0.008129,-0.591513,0.666930,0.370198,-0.316283,0.217447,-0.233052,0.635900,-0.114105,0.452508,-0.195058,-0.157769,0.058049,-0.091836,-0.400385,0.293466,-0.188933,-0.068397,0.116510,0.315447,-0.280501,0.159187,0.633717,-0.509008,-0.065180,-0.133749,0.409805,-0.501546,-0.098814,0.052486,0.219607,0.276775,-0.142151,0.158065,-0.223011,0.176925,0.141949,-0.139307,-0.885759,-0.127864,0.113887,0.090324,-0.251367,-0.020227,-0.005230,0.022802,0.303178,-0.128518,0.234813,0.570540,0.352874,0.467963,-0.356398,0.169937,-0.495036,-0.125724,0.682060,-0.505115,-0.481922,0.319906,-0.156631,-0.221886,-0.070997,-0.282921,-0.388627,0.009322,0.364570,0.079587,0.031940,0.582474,-0.747445,-0.054677,-0.292926,-0.594774,-0.007779,-0.261924,-0.258122,-0.853657,-0.159852,-0.042266,0.124385,0.093381,0.301430,-0.253343,0.828293,-0.508266,0.309462,0.577326,0.321205,-0.287554,0.422681,-0.224437,0.188629,-0.265820,0.130831,0.213346,0.038107,0.656327,-0.110297,0.144725,0.098102,0.022097,-0.100132,0.355203', '3318306', '25928048', '26667010', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3006123', '星河战队3：掠夺者', '动作', '一晃十年过去，地球人和虫族的战争如火如荼，愈演愈烈。某日，空军元帅奥玛•阿诺克（斯蒂芬•霍根 Stephen Hogan 饰）来地球人的远方农场罗库山视察，时任上校的强尼•瑞克（加斯帕•范•迪恩 Casper Van Dien 饰）也一同前来。在此期间，阿诺克的心智被虫王操控，他切断了隔离区的电力，使基地完全失去保护。是夜，虫族对隔离区发动总攻，地球军虽顽强抵抗，终因寡不敌众而告败，基地陷落。阿诺克则和一干心腹逃离，飞船迫降在OM-1行星。瑞克因失职被军事法庭判处绞刑，行刑之际被政府秘密部门救下。阿诺克知晓联邦舰队基地所在地的秘密，一旦被虫族得知将不堪设想。因此政府高层要求瑞克带上一队人马，前去营救受困的阿诺克……©豆瓣', '卡斯帕·范·迪恩', '爱德华·诺麦尔', 5.4, 15408, 'tt0844760', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2128557979.jpg', 11.8, 29.6, 42, 11.4, 5.2, '0.092033,0.505813,-0.940949,0.503231,0.175177,0.054205,0.414019,-0.056073,-0.207184,-0.222232,0.318383,0.320405,0.409974,-0.356457,0.300969,-0.363516,-0.637089,-0.203701,-0.161141,-0.300359,-0.419050,-0.504164,-0.152080,-0.244581,-0.085916,-0.548363,0.543761,0.256456,-0.137805,0.417871,0.145925,0.602972,-0.198648,0.606934,0.420646,0.086012,0.329552,-0.443367,-0.256571,0.435600,-0.129725,0.291031,-0.179290,-0.107897,0.031883,0.197966,0.771897,-0.316746,0.366094,-0.721886,-0.127264,-0.557599,0.617332,-0.020127,0.934983,-0.126646,-0.530448,0.197257,-0.355456,0.053985,0.264478,0.130204,-0.148882,-0.039934,0.308961,-0.076907,-0.493440,0.012781,-0.546130,0.361263,0.015982,-0.141791,0.077227,1.008768,0.359359,0.235544,0.146232,0.260186,-0.563046,-0.202807,0.612705,-0.338082,-0.311121,-0.768232,0.000462,-0.810147,-0.043222,-0.090586,-0.177787,-0.186900,0.508941,-0.455471,0.109490,0.630283,-0.360718,-0.154843,-0.467834,-0.351417,-0.114896,-0.235027,0.186605,-0.991509,0.187304,0.301395,0.111309,0.355882,0.082194,0.717305,0.361379,-0.293193,0.294901,0.622324,0.573398,-0.381319,0.469427,0.150261,0.190669,-0.373722,0.101999,0.546535,0.567784,0.623598,0.388006,0.063728,-0.032841,-0.323584,-0.099723,0.080125', '3871833', '27073291', '1291824', '1293830');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3006309', '追击者', '剧情', '深夜的首尔街头，出租车上频频被插上写有电话的应召女郎的卡片。前刑警忠浩（金允石 Yun-seok Kim 饰）手下就有着一批应召女郎，表面粗暴野蛮的他，对姐妹们貌似毫不讲理。最近忠浩手下的姐妹频频发生失踪事件，他认为是有人故意把她们拐卖。暴跳如雷的他猛翻登记簿寻找蛛丝 马迹，最后确定了一个嫌疑电话尾数为4885。正好这个电话这时呼入需要应召女郎。忠浩让美珍（徐英姬 Yeong-hie Seo 饰）前去。正在家里发烧卧床的美珍想拒绝，无奈拗不过忠浩，留下七岁女儿在家后还是出门了。忠浩让她记住对方的地址并且用短信告诉他，叮嘱她别搞砸。忠浩亦同时尾随而去，想揪出这个拐卖贩子。美珍跟着4885池英民（河正宇 Jung-woo Ha 饰）进入房间时发觉一切已经太迟，在这个毫无信号的地方，池英民要将她残忍杀害……失去美珍联系的忠浩开始四处寻找，偶遇到池英民后凭借他身上的血迹断定他是凶手，经过追逐后把他带到警察局。然而警察的冷漠无能以及池英民惊人的冷静，让案件无法侦破。池英民说美珍可能也活着，而忠浩一直没有放弃寻找美珍的希望，拼命追击。', '河正宇', '罗泓轸', 8.4, 220924, 'tt1190539', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2496896804.jpg', 0.7, 1.2, 12, 48.4, 37.7, '0.247289,0.207586,-0.548546,0.360795,-0.261158,-0.138906,0.676191,-0.229516,-0.479691,-0.268706,-0.075745,0.504467,0.040369,0.194992,0.044711,-0.001559,-0.316845,-0.606657,-0.074974,0.098307,-0.443907,-0.449360,-0.007929,-0.125298,-0.087539,0.049087,0.075102,-0.053009,-0.119363,0.494212,0.262382,0.373663,-0.212483,0.514222,-0.126438,0.192711,-0.097576,-0.054873,0.069784,0.187121,0.342933,-0.155343,0.017807,0.148776,0.213949,0.487045,0.549263,0.146981,-0.305352,0.019893,0.354905,-0.279984,-0.003064,0.126737,0.350620,0.246334,0.207087,0.123284,-0.431469,-0.220059,0.128179,0.167334,-0.651471,0.049927,0.005570,0.109188,-0.372242,-0.012076,-0.230335,0.020108,0.234462,-0.241736,0.309144,0.293212,0.165278,0.017139,-0.143147,-0.123847,-0.376418,0.128865,0.319058,-0.083694,0.193265,0.226346,0.032360,-0.223185,0.300196,-0.032488,-0.145182,0.089265,0.301560,0.128201,-0.505927,-0.240473,-0.084750,-0.260634,-0.340422,-0.117802,-0.032805,-0.359123,-0.311484,-0.278716,-0.106457,-0.025413,-0.274101,0.245990,-0.215932,-0.124095,0.240101,-0.652699,0.149792,0.524122,0.426002,-0.572687,0.564247,0.076349,-0.062541,-0.153161,0.153600,0.092157,0.310696,0.43384