INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3006327', '为子搬迁', '剧情', '伯特·法兰德（约翰·卡拉辛斯基 John Krasinski 饰）和维罗纳·德·泰桑特（玛娅·鲁道夫 Maya Rudolph 饰）是一对恩爱夫妇，维罗纳怀孕了，因此二人需要找到一个最适合的地方，安家，抚育即将到来的子女。他们首先想到投奔伯特父母，却不巧遇上二老决定出门旅行，他们继续走过亚利桑那州、威斯康辛州，寻找许多故交、亲属，也目睹家家有本难念的经。在走过一站又一站的过程中，两个人的感情愈发相笃，愈加意识到彼此都是唯一，也许将来也会遇到所见其他夫妻那样的问题，也正是这些真实故事，更利于他们找到幸福，兜兜转转，他们最终的家到底在何方……©豆瓣', '约翰·卡拉辛斯基', '萨姆·门德斯', 7.6, 7706, 'tt1176740', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1054013994.jpg', 0.5, 2.8, 31, 49.8, 16, '0.534570,-0.443201,-0.619875,0.424925,0.275143,-0.463455,0.401149,0.039907,-0.571308,-0.529679,-0.042023,0.849964,-0.168364,0.287100,0.170251,-0.127220,-0.417525,-0.259339,0.249468,-0.243566,-0.225158,-0.644828,-0.123514,-0.139052,0.046001,-0.179124,0.425223,0.223574,0.027407,0.229524,0.242517,0.273644,-0.323912,0.407471,-0.285284,0.042261,0.014330,0.232585,-0.439709,0.107976,-0.188230,0.192794,-0.384700,0.171089,0.098190,0.193221,0.354669,-0.215939,-0.142356,0.089265,0.172363,-0.004944,0.064855,0.110033,0.384421,-0.409906,0.258682,0.497057,-0.187270,0.118609,-0.127401,-0.073461,-0.552345,0.107891,0.281941,0.324438,-0.534546,0.090954,0.238000,-0.467469,0.031727,-0.458165,0.384368,0.801293,0.157115,0.245098,-0.235784,-0.247656,-0.582404,-0.127107,0.970762,-0.070296,0.041637,0.398194,0.004000,-0.306933,0.141708,-0.078589,-0.434657,0.049723,0.009919,0.348091,-0.005176,0.193442,-0.468674,0.233614,-0.191872,-0.050762,0.238405,-0.568972,0.187964,-0.558361,-0.017419,-0.434992,-0.477931,0.214473,0.113908,-0.383028,0.632316,-0.499645,0.127109,0.358394,0.224165,-0.539559,0.676201,0.172419,0.274574,-0.497633,-0.102743,0.388434,0.257310,-0.011806,-0.276837,0.057488,-0.025983,0.006056,-0.241294,0.353303', '25721544', '6890343', '26724989', '1307125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3006416', '青春大反抗', '剧情', '影片的故事灵感来自于极具荒诞主义写实手法的作家C·D·佩恩的小说《青春大反抗：尼克·特威斯普的冒险传奇》，经由格斯汀·纳什之手创作改编成剧本。尼克（迈克尔·塞拉 Michael Cera 饰）痴迷于法国文化，但总显得与他人格格不入，家庭情况也让他无能为力。直到他遇到了漂亮的邻家女孩辛妮（波茜娅·道布尔戴 Portia Doubleday 饰）。她喜欢收藏法国歌手唱片，让尼克觉得两人是天生一对，但作为处男的尼克如何应对。为了赢得辛妮的芳心，尼克制造出了另外一个自我——弗朗西斯·狄林杰尔。弗朗西斯与生性懦弱的尼克完成相反，他是一个纯粹的坏男孩，会做一些尼克可能永远都不敢尝试的事情。“两人”联手频出“奇招”，引发笑料不断。这一次，尼克会完成自己的青春大反抗吗？©豆瓣', '迈克尔·塞拉', '米盖尔·阿尔特塔', 6.4, 7292, 'tt0403702', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1264070467.jpg', 2.2, 12.3, 53.6, 25.1, 6.8, '0.258135,-0.027415,-0.434154,0.626802,-0.034442,-0.287216,0.573984,0.094759,-0.528076,-0.168298,0.049070,0.798421,-0.182485,-0.049064,0.223177,-0.009963,-0.326660,-0.576137,0.284346,0.075803,-0.024408,-0.523946,-0.234066,-0.326725,-0.135731,-0.333918,0.554914,-0.016982,-0.278698,0.206551,0.340175,0.398124,0.268621,0.069483,0.260175,-0.102033,0.067210,-0.191970,-0.175329,0.298641,0.237071,0.079330,-0.300928,0.191503,-0.084638,0.288541,0.376219,-0.217406,-0.107742,-0.193214,0.645164,-0.168042,0.082221,-0.009445,-0.380665,-0.128537,0.199970,0.108262,0.009757,0.092359,0.349288,-0.066695,-0.937544,0.247912,-0.006048,0.246559,-0.294083,0.163531,-0.216076,-0.176419,0.110171,-0.363461,-0.182990,0.166624,0.742187,0.067319,-0.106271,0.020948,-0.382516,0.082928,0.463791,0.280237,-0.613915,0.305960,-0.510805,-0.305070,-0.124141,-0.509199,-0.467078,0.162886,0.189814,-0.033184,0.076670,0.357846,-0.554797,-0.023094,-0.247281,0.023188,-0.124082,-0.372632,-0.051566,-0.709211,-0.062194,-0.330106,-0.356362,-0.324964,0.344523,-0.451388,0.851597,-0.688737,0.026322,0.657451,0.140629,-0.278643,0.483988,0.330085,-0.072687,0.030729,-0.121927,0.310049,0.005935,-0.078635,0.048018,0.350051,0.334957,-0.180511,-0.321125,0.435084', '27602116', '24284209', '35280911', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3006424', '我配不上她', '喜剧', '身形矮小、其貌不扬的柯克（杰伊·巴鲁切尔 Jay Baruchel 饰）是供职于匹兹堡机场的一名普通保安。他的爱情可以称得上是完败，女友玛妮（林德赛·斯隆 Lindsay Sloane 饰）弃之而去，他一心重修旧好而不能；工作枯燥乏味，波澜不惊，平时最多和学生时代的好友扯扯皮、谈谈心，俨然一个不被人关注的废柴。然而就是这么一个小人物，却狠狠交了一把桃花运。偶然机会，柯克邂逅了美丽出众、光彩夺目的富家女莫莉（爱丽丝·伊芙 Alice Eve 饰），对方热情主动，令柯克如坠梦中。一段身份地位乃至各个方面都极不相称的恋情就此展开，不过诸多的麻烦也随即涌现，柯克该如何面对这突如其来的一切……©豆瓣', '杰伊·巴鲁切尔', '吉姆·费尔德·史密斯', 6.6, 40364, 'tt0815236', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p508715055.jpg', 1.4, 9.7, 54.6, 27.7, 6.6, '0.394993,0.036546,-0.596255,0.636530,-0.390226,-0.162911,0.643400,0.209944,-0.416494,-0.254356,0.058132,0.686771,-0.084344,0.150415,0.237663,-0.251110,-0.085168,-0.587577,0.056015,-0.229514,-0.060115,-0.429972,-0.234137,-0.262890,-0.251584,-0.108273,0.536610,-0.200637,-0.056904,0.477954,0.557666,0.427823,-0.028781,0.558503,-0.266607,-0.200047,0.133337,-0.026391,-0.257911,0.153277,-0.109657,-0.083903,-0.117165,0.312765,-0.035290,0.257488,0.424282,-0.046150,-0.049510,-0.051585,0.468231,-0.129222,0.083502,0.103342,0.157166,-0.184407,0.201690,-0.122449,-0.066511,-0.083878,0.325696,-0.341034,-0.520654,0.174458,0.168720,0.292561,-0.378351,0.432090,-0.118549,-0.296689,-0.102418,-0.139568,-0.214720,0.146024,0.420672,0.029556,0.054218,0.039846,-0.279677,0.159885,0.489607,0.409310,-0.532863,0.588244,-0.325017,-0.265188,-0.090812,-0.353377,-0.485745,-0.095879,0.215117,-0.083436,0.002008,0.350232,-0.329375,-0.016570,-0.412514,0.136337,-0.255995,-0.481263,-0.052835,-0.382687,-0.114646,-0.621042,-0.542011,-0.046870,0.210570,-0.203923,0.717742,-0.707418,-0.140512,0.383109,0.234680,-0.294856,0.565359,0.031664,0.234012,-0.220208,-0.151483,0.219114,0.286493,0.096564,0.021766,0.421323,-0.035934,-0.158927,-0.150125,0.474271', '24756472', '3230462', '30162520', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3006769', '大眼睛', '剧情', '《大眼睛》故事发生在上个世纪60年代，一种名为“大眼孩子”的插图流行起来。不久，其作者沃尔特·基恩遭到起诉，被指责盗取他人作品，而对方正是沃尔特的妻子玛格丽特。玛格丽特表示，大眼孩子的绘画原本出自她之手，性格内向的她每天在地下室里作画，而丈夫沃尔特仅仅是在画作下方签上自己的名字进行销售而已。最终二人婚姻破裂。事情闹上法庭后，法官让二人现场作画，沃尔特推三阻四，借口不断，最终版权案真相大白。', '艾米·亚当斯', '蒂姆·波顿', 6.9, 12735, 'tt1126590', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2206810559.jpg', 0.4, 5.2, 50.9, 35.3, 8.2, '0.186768,0.157436,-0.842271,0.447157,0.070440,-0.033458,0.621017,0.155764,-0.530531,-0.348013,0.253308,0.758250,-0.394001,0.374858,0.011343,0.064391,-0.342531,-0.701033,0.106845,-0.297625,-0.209066,-0.654133,0.195203,-0.261115,-0.173644,-0.047132,0.441867,-0.138654,-0.338455,-0.060606,0.277252,0.048028,-0.067796,0.028249,0.093938,-0.109016,0.003461,-0.169649,0.000687,0.182020,0.219509,-0.294507,-0.338983,0.008674,-0.235839,0.308416,0.794501,-0.314977,-0.125603,-0.324349,0.536201,-0.133101,0.096678,0.261294,0.017839,0.189148,0.397332,0.136946,-0.194405,-0.315815,0.231633,-0.166631,-0.239807,-0.098462,-0.120727,0.212127,-0.312797,0.392956,-0.252896,0.243911,-0.044728,-0.467930,0.045819,0.061178,0.589013,0.248641,-0.152970,-0.096081,-0.404406,0.145017,0.149979,0.297850,-0.313418,0.352402,-0.249255,-0.220923,-0.113413,-0.246326,-0.455941,0.123557,0.374531,-0.102721,-0.072487,0.399364,-0.280459,-0.076983,-0.294781,-0.195852,0.033522,-0.118059,-0.084375,-0.644882,-0.143296,0.024912,-0.293782,-0.205495,0.034208,-0.363317,0.634605,-0.313395,0.281558,0.461398,0.160990,-0.188341,0.490691,0.097609,0.189381,-0.077852,-0.199059,-0.093781,0.177495,0.094024,0.253647,-0.276428,0.136789,0.043446,-0.161922,0.448974', '1307146', '5262339', '25785124', '1484091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3006772', '第九区', '剧情', '1990年，一艘巨大的飞船出现在地球上空，人们惶恐不安，却又分外好奇。经过一段时间紧张的等待，外星飞船始终没有动静。人类终于小心翼翼靠近它，强行走进舱内，结果发现了不计其数的外星人。他们形容丑陋，宛如虾子，而且健康状况极差，虚弱无力。原来这是一群来自外星的难民，他们最终被地球人接纳，并隔离在南非约翰内斯堡的一片区域内生活，此地名为“第九区”。经过长达20年的繁衍，外星难民的数量扩张至180万之多，且和周边人类的矛盾冲突不断，越来越多的人类呼吁将“大虾”赶出地球。MNU（列国同盟组织）经过磋商，决定将外星难民迁移到更为偏远的区域。MNU外星事务部门的特工威库斯（Sharlto Copley 饰）专门负责搬迁工作。威库斯在动员过程中傲慢随意，与当地居民冲突频频。最终，他为自己的行为付出代价，外星人的神秘流体将其感染，威库斯慢慢变成了外星人的模样……©豆瓣', '沙尔托·科普雷', '尼尔·布洛姆坎普', 8.3, 428238, 'tt1136608', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1559469100.jpg', 0.4, 1.6, 15.8, 45.8, 36.3, '0.253808,0.176646,-0.881731,0.312161,0.086724,0.299076,0.726570,-0.157161,-0.529405,-0.097305,0.148716,0.364367,-0.101724,0.044626,0.027451,-0.168747,-0.407709,-0.345306,-0.204512,-0.250315,-0.358674,-0.232883,-0.545797,-0.509247,-0.030349,-0.514345,0.491387,0.179941,-0.120666,0.372629,-0.328904,0.350193,-0.376265,0.592058,-0.249311,-0.260523,0.085250,-0.054825,-0.062266,-0.026536,-0.429923,-0.212925,-0.158428,0.202960,-0.120191,0.344358,0.954068,-0.538501,-0.110874,-0.254114,0.269390,-0.346432,-0.059064,0.103200,0.590868,0.059268,-0.167744,-0.026727,-0.173953,0.076042,-0.025835,-0.119152,-0.389957,-0.088789,-0.100301,0.373268,-0.280988,0.324045,-0.015783,0.022147,-0.060913,-0.334420,0.056019,0.507977,0.291091,0.430570,-0.192621,0.085202,-0.395403,-0.198519,0.642103,0.123097,-0.650308,-0.054054,-0.436867,-0.662328,-0.008887,-0.423404,-0.227406,-0.396074,0.135835,0.079349,-0.136725,0.602496,-1.073586,0.158821,-0.330074,-0.623735,-0.035860,-0.084058,-0.186938,-0.857165,-0.118661,-0.200597,0.009012,0.228715,-0.063261,-0.064386,0.823710,-0.420080,0.170265,0.669401,0.425836,-0.667237,0.335823,-0.305705,0.111770,-0.150352,-0.193059,0.212358,0.281624,0.676101,0.020727,0.209055,-0.156417,-0.040900,-0.166454,0.259683', '2