INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3006775', '前女友们的幽灵', '喜剧', '英俊帅气的康纳•米德（马修•麦康利 Matthew McConaughey 饰）是一名事业有成且艳遇不断的著名摄影师，崇尚自由的他游走各色美女之间，却从来不许下任何承诺。直到意兴阑珊之时，“挥一挥衣袖，不带走一片云彩”。潇洒至极，乐在其中。与游戏人间的哥哥不同，康纳的弟弟保罗（Breckin Meyer 饰）则即将走入婚姻的殿堂。康纳首要前往参加婚礼，当然对他来说，这也许又是另外一段（或者几段？）艳遇的开始。然而，事情的发展却出乎他的意料，他先是在洗手间遇见早已去世的叔叔（迈克•道格拉斯 Michael Douglas 饰），接着又遭遇三名前女友的幽灵。她们带领康纳回溯自己这些年来的“浪漫史”，在这一过程中，康纳也发现自己遗失且忘却了很久的东西……©豆瓣', '马修·麦康纳', '马克·沃特斯', 6, 12482, 'tt0821640', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p895371397.jpg', 3, 17.2, 58.2, 17.7, 3.9, '0.429140,-0.084821,-0.706477,0.586280,-0.170521,-0.426447,0.937066,0.003456,-0.320635,-0.361091,0.345523,0.813482,-0.040259,0.091023,0.522434,0.059907,-0.322259,-0.540129,-0.041409,-0.143456,-0.182554,-0.414414,-0.337890,0.122122,-0.039754,-0.354328,0.530199,-0.012799,-0.036744,0.714499,0.249002,0.189180,-0.187409,0.494342,-0.077628,0.083741,0.264473,0.305962,-0.230264,-0.018320,0.053487,-0.150361,-0.138526,0.317989,-0.203335,0.302684,0.600778,-0.242323,-0.095829,-0.008910,0.384751,-0.236115,-0.001487,0.201376,0.120615,0.045352,0.206753,0.395615,-0.113619,0.033939,0.043056,-0.165933,-0.529309,0.049475,0.038968,0.190619,-0.442979,0.443232,-0.076450,-0.230054,0.163646,-0.366689,-0.002714,0.371007,0.343864,0.276960,-0.182321,-0.021782,-0.479044,0.224180,0.652896,0.228259,-0.306374,0.425172,-0.260274,-0.372709,-0.006572,-0.020411,-0.416157,-0.116142,0.148945,0.029481,-0.095111,0.375227,-0.425348,0.081934,-0.239062,-0.156564,-0.038072,-0.252473,-0.257332,-0.517502,0.000419,-0.424006,-0.396591,-0.056644,-0.067014,-0.147985,0.565673,-0.740932,0.277128,0.259165,0.125255,-0.303175,0.657000,0.342340,0.236456,-0.133232,-0.243069,0.434210,0.045043,0.172298,0.002476,0.324963,0.102754,-0.356336,-0.428121,0.494669', '1296534', '3111650', '1309172', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3006781', '高度怀疑', '剧情', '本片根据德国表现主义电影大师弗列兹·郎1956年的同名电影改编而成。电视记者希杰·尼古拉斯（杰西·麦特卡尔菲 Jesse Metcalfe 饰）和好友考利·芬雷（乔·摩尔 Joel Moore）一起供职于电视台的“调查报道”栏目。在对某凶杀案的报道过程中，希杰认识了地区检察官办公室的助理检察官艾拉（爱波·塔布琳 Amber Tamblyn 饰），并依据其提供的审讯录像资料怀疑她的上司，地区检察官马丁·汉特（迈克尔·道格拉斯 Michael Douglas 饰）靠伪造DNA物证来赢得检控，为竞选州长铺平道路。调查无门的希杰决定与考利一起执行一个天衣无缝的计划，故意采办各种物证指正自己是一起妓女凶杀案的最大嫌疑人。在审判过程中，考利本应出示二人拍摄的录像来证实希杰并非凶手，却在赶往法庭的路上死于车祸。被判处死刑的希杰走投无路，只能求助于艾拉，但她能证明希杰的清白吗？', '杰西·麦特卡尔菲', '彼得·海姆斯', 7.2, 16978, 'tt1183251', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2220873265.jpg', 0.8, 4.3, 39.8, 45.1, 10.1, '0.171352,-0.287736,-0.214097,0.540925,0.116345,-0.148839,0.361819,0.118105,-0.367495,-0.462481,0.144643,0.614967,-0.156102,0.080922,0.422742,-0.002504,-0.642930,-0.701849,-0.171018,-0.030265,-0.133605,-0.957911,-0.014594,-0.449134,0.023719,-0.035010,0.500817,-0.051863,-0.164025,0.314479,0.219399,0.236346,-0.459514,0.013908,0.121312,-0.058874,0.448066,-0.237392,-0.628155,0.399778,0.277063,-0.123506,-0.101017,0.078667,0.272633,0.324118,0.359482,-0.181365,0.025326,0.036492,0.434899,-0.362321,0.338187,0.092589,0.395445,0.119979,0.252108,0.434361,-0.365516,-0.120087,0.234329,-0.083121,-0.889938,-0.166933,0.160950,0.300842,-0.096094,0.186338,-0.394295,0.331890,0.051415,-0.164186,0.129774,0.263360,0.269808,0.099981,0.099066,-0.211538,-0.380501,0.220121,0.172817,0.070674,0.051468,0.041981,-0.234594,-0.435828,-0.124269,0.059431,-0.334446,0.193955,0.240277,-0.218616,0.056478,0.154842,-0.319552,-0.517160,-0.316283,-0.081842,-0.136451,-0.292730,0.048245,-0.937211,-0.114026,0.034439,-0.104014,-0.216214,0.156117,-0.283419,0.191219,-0.606266,0.142988,0.608193,0.197490,-0.353202,0.635717,0.229035,0.020565,-0.292548,-0.175200,0.137570,0.475397,0.284951,0.143464,0.146568,0.253324,-0.403768,-0.457517,0.093999', '2028645', '1307442', '6517421', '30143331');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3006783', '机械师', '动作', '稳定的心态，精妙的手法，杀人于无形，这是一个顶尖杀手的必备特质。亚瑟（杰森•斯坦森Jason Statham 饰）入行多年，在自己以前的搭档哈里（唐纳德•萨瑟兰Donald Sutherland 饰）的帮助下，已经成为一个出色的杀人机器。亚瑟接到一项新任务，暗杀对象是哈 里。虽然亚瑟不忍下手，但在清楚的得知哈里难逃一死之后，最终还是决定亲自送哈里一程。哈里的儿子史蒂夫（本•福斯特 Ben Foster 饰）为了替父报仇，决意要跟随亚瑟学习。在亚瑟的训练下，史蒂夫逐渐掌握了作为一个机械师所必备的技能，与亚瑟合作完成一项又一项暗杀任务。虽然亚瑟从未告诉史蒂夫杀害哈里的凶手，但史蒂夫还是知道了其父被害为亚瑟所为，复仇的火焰在史蒂夫心中逐渐升腾……本片翻拍自1972年的同名电影（译作《龙虎铁金钢》），投资约4000万美元。©豆瓣', '杰森·斯坦森', '西蒙·韦斯特', 7.2, 138677, 'tt0472399', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1008022297.jpg', 0.5, 4.6, 42.4, 39.6, 12.9, '0.066152,0.123858,-0.433995,0.669080,-0.152934,-0.518325,0.341560,-0.125792,-0.356479,-0.694572,0.363272,0.861204,0.108774,-0.072012,0.325338,-0.024823,-0.242464,-0.475981,-0.004277,-0.249822,-0.193570,-0.751006,-0.445203,-0.287757,-0.073165,-0.355427,0.674955,0.065438,-0.025544,0.232766,0.441136,0.428538,0.173769,0.062203,0.047558,-0.352430,0.114824,-0.301838,-0.463768,0.290551,0.102457,-0.116449,-0.161791,0.105777,0.104895,0.420097,0.414000,-0.296643,-0.117708,-0.101236,0.398459,-0.261084,-0.020754,-0.106350,0.068555,0.103395,0.024928,0.292063,-0.205044,0.183766,-0.016145,-0.147280,-1.127513,-0.118354,0.161083,-0.119557,-0.610999,0.235261,-0.369527,0.081650,0.028924,-0.433629,-0.171442,0.253930,0.393946,0.380927,-0.300063,0.276415,-0.209640,0.083811,0.682043,0.061890,-0.041780,0.088643,-0.091883,-0.389925,0.082974,-0.202525,-0.249034,-0.024785,0.347159,0.200308,-0.037126,0.258594,-0.545316,-0.319713,-0.398400,-0.080927,-0.013332,-0.375355,0.145053,-0.604296,-0.043753,-0.108568,-0.286925,-0.149893,0.202699,-0.477859,0.641120,-0.952881,0.404937,0.467920,-0.123549,-0.524047,0.295117,0.216968,0.212277,-0.293318,-0.107946,-0.007764,0.255900,0.117283,0.134306,0.316788,0.369415,-0.339796,-0.343260,0.509343', '1793491', '26678784', '27056396', '24875409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3006892', '超级魔术师', '喜剧', '在拉斯维加斯的魔术界，无人不知波特（史蒂夫·卡瑞尔 Steve Carell 饰）和安东（史蒂夫·布西密 Steve Buscemi 饰）这对好搭档的大名，他们以高超的技术和迷人的魅力赢得了粉丝们的追捧和喜爱。一次表演中，安东意外受伤，这让他和波特之间的友谊产生了裂痕，当这裂痕随着时间的推移而变得越来越大以至于最终无法收拾之时，也正是两人分道扬镳之日。失去了安东的支持和陪伴，波特第一次开始了独自一人的艰难奋斗，与此同时，一个名为史蒂夫（金·凯瑞 Jim Carrey 饰）的新人魔术师的出现迅速取代了波特在业界的地位。谁能帮助波特挽回昔日的风光和对魔术的热爱？第一个出现在波特脑海中的人是安东。©豆瓣', '史蒂夫·卡瑞尔', '唐·斯卡尔蒂诺', 6.1, 8846, 'tt0790628', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1858019111.jpg', 3, 16.1, 57.3, 18.5, 5.1, '0.248506,0.031425,-0.884249,0.792274,0.015757,-0.412466,0.782846,0.275855,-0.604187,-0.001219,0.039886,1.017827,-0.324993,0.299486,0.430576,-0.269499,-0.254809,-0.948062,-0.025448,-0.304932,-0.293582,-0.517334,-0.764150,-0.285823,-0.247737,-0.680158,0.442923,0.185257,-0.365271,0.908773,0.453501,0.258324,0.235292,0.355501,-0.114873,0.008394,0.233939,0.093256,-0.374504,0.144193,0.076695,-0.182877,0.058841,0.305041,0.028554,0.251067,0.649077,-0.447355,-0.068303,-0.075004,0.406898,-0.289269,-0.016203,0.270800,0.132761,-0.001341,0.218841,0.167813,-0.246335,-0.172384,-0.148825,-0.010714,-1.253855,0.243286,0.170483,0.198726,-0.733442,0.668643,-0.080541,-0.504746,0.201775,-0.398533,0.158836,0.399341,0.272716,0.346400,-0.338884,-0.023783,-0.282367,-0.126626,0.573538,0.014957,-0.573480,0.364567,-0.097435,-0.363196,-0.157794,-0.181273,-0.406715,-0.118629,0.451848,0.157699,0.106089,0.410034,-0.868851,0.078394,-0.266150,-0.314071,0.125856,-0.377620,-0.101962,-0.676674,-0.368624,-0.709652,-0.218241,0.123913,-0.030236,-0.312776,0.912326,-1.200237,0.305609,0.267902,0.351390,-0.364985,0.767416,0.278233,0.209037,-0.096722,-0.288305,0.033367,0.113260,0.294009,0.047802,0.336077,0.169843,-0.072206,-0.458076,0.754726', '1793491', '35144311', '3000078', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3007297', '楼上的外星人', '科幻', '皮尔森（凯文•尼龙 Kevin Nealon 饰）带着家人来到郊外的别墅和弟弟一家一起避暑度假。一场看似普通的流星雨让4个带着可以控制人思维的高科技仪器企图侵略地球的外星人迫降在别墅的阁楼里。他们起初利用控制贝瑟尼（阿什丽•提斯代尔 Ashley Tisdale 饰）的男朋友里基（罗伯特•霍夫曼 Robert Hoffman 饰）悄然打入这家人中，可不料还是被皮尔森家的孩子们敏锐的觉察到。虽然家里的大人不相信小孩子们的说法，可孩子们还是渐渐意识到了家中阁楼上这四个外星人存在的巨大潜在危机，悄悄的团结在一起开始了一场人类保卫战。而那四个外星人也不甘示弱，面对孩子们制造出的各种新奇的小武器，他们用控制人思维的机器控制了家里的大人来反攻这些孩子们。可这四个外星人里有一个例外，就是技师斯帕克斯，原本就无心恋战的他更是机缘巧合的和汉娜结成了好友，弃暗投明的开始帮助皮尔森一家。面对强大的外星人入侵，孩子们能否把这场人类危机化险为夷呢？', '卡特·詹金斯', 'John Schultz', 6.4, 5346, 'tt0775552', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1956774557.jpg', 2.1, 11.2, 55.7, 24.3, 6.8, '0.632851,0.074133,-0.677287,0.406239,-0.383407,0.045354,0.721629,0.038832,-0.497299,-0.253296,0.258449,0.697611,-0.011914,0.289427,0.052842,-0.007594,-0.348289,-0.434844,-0.095599,-0.044704,-0.500689,-0.320366,-0.444768,-0.283587,-0.005980,-0.255485,0.312662,0.041575,-0.145927,0.395990,0.241903,0.339347,-0.174909,0.196630,-0.227749,-0.019524,0.009541,-0.099282,-0.077567,0.198496,-0.070418,0.125372,-0.184323,0.297439,0.179909,0.338572,0.736155,-0.401142,0.082767,-0.291814,0.064699,-0.144596,-0.044186,0.343903,0.160690,0.003692,0.132134,-0.068841,-0.104813,0.132451,0.116885,-0.073046,-0.737462,0.140526,0.108509,-0.075722,-0.509827,0.117734,0.276928,-0.116237,-0.103524,-0.248058,0.199815,0.348668,0.006315,0.550378,-0.363343,-0.020262,-0.665550,-0.143211,0.691364,-0.177783,-0.419165,0.160434,-0.145779,-0.214605,-0.116636,-0.316634,-0.536700,-0.113598,0.276125,0.084228,-0.312972,0.178270,-0.817452,0.232322,-0.295345,-0.170071,-0.058590,-0.508518,0.097202,-0.846761,0.066385,-0.376553,-0.219109,0.322807,0.129185,0.000973,0.985329,-0.622244,0.031693,0.587106,0.393916,-0.463960,0.546198,-0.009951,0.183971,-0.115477,-0.219624,-0.046202,0.084267,0.196581,0.213062,0.523879,-0.125675,-