INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3007809', '城市广场', '剧情', '公元4世纪，罗马帝国日渐衰落，在亚历山大港，多神教的智者希帕提娅（蕾切尔·薇姿 Rachel Weisz 饰）为弟子们授课。奥利斯蒂斯（奥斯卡·伊撒克 Oscar Isaac 饰）对她频频示爱，甚至在剧院大胆表白；奴隶达乌斯（麦克思·明格拉 Max Minghella 饰）也对她颇有好感，但因身份卑微无法启口。与此同时，基督教徒宣扬的自由，让达乌斯的信仰开始动摇，此举令他遭受鞭刑，是希帕提娅为他疗伤，抚慰了他的心灵。时局动荡，在多神教的挑动下发生暴乱，基督教转而取得优势，双方在亚历山大图书馆对峙。后来，接到了罗马统治者的号令，让多神教撤出图书馆，允许基督教徒进入，于是一场残酷的浩劫开始了……本片为第62届戛纳电影节的非竞赛展映片，取景地为马耳他的里卡所里堡，这里曾是《角斗士》和《特洛伊》拍摄地。希帕提娅原定由妮可·基德曼出演，但因其在《黄金罗盘》中饰演反派，遭到基督教徒反感，因此换角。', '蕾切尔·薇兹', '亚历杭德罗·阿梅纳瓦尔', 8.1, 18175, 'tt1186830', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1056945371.jpg', 0.3, 1.6, 19, 48.9, 30.1, '0.299672,0.150164,-0.757856,0.560323,0.264727,0.021281,0.498866,0.156276,-0.411365,-0.025818,0.261529,0.811541,-0.307256,-0.258101,0.284942,0.041549,-0.453693,-0.639411,-0.109618,-0.201870,0.170980,-0.432874,-0.069440,0.038553,-0.379991,-0.625068,0.511367,0.006421,-0.258899,0.373348,0.435574,0.438681,0.232919,0.153692,0.097170,-0.112009,0.159530,-0.234384,-0.289751,0.242503,-0.028608,-0.228643,-0.284201,0.367640,-0.122132,0.565792,0.407916,-0.453926,0.155058,-0.081807,0.529890,-0.248477,0.132585,0.294315,0.411262,0.011762,-0.083065,0.260062,-0.070328,0.186213,0.010236,-0.117138,-0.601318,0.143077,0.148681,0.167221,-0.530178,0.383969,-0.278857,-0.034636,-0.023936,0.016905,0.056558,0.538881,0.282686,0.272935,0.214484,-0.161754,-0.294691,-0.117781,0.523769,-0.011628,-0.325527,0.192392,-0.442839,-0.418594,0.012945,-0.339770,-0.475907,-0.156904,0.157785,-0.128934,0.228057,0.589919,-0.478324,-0.271599,-0.527681,-0.320796,0.173437,-0.117109,-0.020156,-0.706973,-0.130581,-0.290914,-0.160480,-0.376126,0.137196,-0.246084,0.572743,-0.835403,0.432660,0.517214,0.541443,-0.341685,0.612084,0.109375,0.037621,0.031400,-0.087371,0.673392,-0.053865,0.155276,-0.001740,0.144858,0.294100,-0.300080,-0.029538,0.427610', '3285622', '1303034', '26259202', '1293656');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3007817', '裂缝', '剧情', '20世纪30年代，英国某女子教会寄宿学校。这里校风极其严格，女孩们被要求墨守成规，不允许有任何堕落和消极的思想。而游泳队的教师G小姐（伊娃·格林 Eva Green 饰）显得如此与众不同，她个性张扬，思想开放，鼓励学生努力追求自身的欲望。在女孩们的眼中，G小姐是如此迷人。不久，来自西班牙的贵族小姐费雅玛·科罗纳（玛利亚·瓦沃德 María Valverde 饰）转学至此，她高雅尊贵的气质和亲切友善的性格令女孩们甚为倾倒，甚至G小姐也喜欢上这个出身豪门却有着独立思想的女孩。然而费雅玛的处事态度渐渐令G小姐感到矛盾与困惑，曾经是中心人物的女孩黛·拉斯菲尔德（朱诺·坦普尔 Juno Temple 饰）也心生嫉妒……本片根据女作家谢拉·科勒（Sheila Kohler）的同名小说改编。©豆瓣', '伊娃·格林', '乔丹·斯科特', 8, 85227, 'tt1183665', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561909661.jpg', 0.3, 1.5, 21.9, 53, 23.4, '0.430095,-0.023429,-0.406043,0.667417,-0.302774,0.044352,0.578498,0.191732,-0.864382,-0.350343,0.222486,0.695992,-0.142590,0.270751,0.378215,0.037659,-0.311105,-0.317070,-0.299973,-0.182250,0.212886,-0.378760,-0.071929,-0.243447,-0.183760,-0.610137,0.685746,-0.176654,-0.287338,0.673013,0.258801,0.547475,0.054650,0.277635,-0.080195,-0.321066,0.048341,0.061054,-0.142719,-0.055163,0.069035,0.009293,-0.108897,0.195850,-0.181957,0.232920,0.439893,-0.231350,-0.194224,-0.287699,0.744557,0.072484,0.018779,0.325083,0.272189,-0.240025,0.252410,0.176859,0.210829,-0.103526,0.081618,-0.169980,-0.324326,0.102151,0.473984,0.246491,-0.412036,0.229785,-0.091721,-0.316920,0.113356,-0.260090,-0.160205,-0.233556,0.254188,0.209665,0.169143,0.172255,-0.214098,0.047478,0.526555,0.289777,-0.494487,0.136336,-0.937596,-0.636282,0.117846,-0.453517,-0.861372,0.126859,-0.216255,0.073707,0.236492,0.465726,-0.594620,0.083131,-0.092024,0.252416,0.044735,-0.627596,-0.051494,-0.544610,-0.278694,-0.716788,-0.180003,-0.327444,0.053821,-0.027073,1.160136,-1.073421,0.036335,0.381654,0.443168,-0.486197,0.704766,0.181481,-0.253188,-0.089536,-0.485209,0.354257,-0.155248,-0.269922,-0.529809,0.496791,-0.170636,-0.095777,0.014397,0.446507', '6963575', '1303010', '26348103', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3007819', '水性杨花', '喜剧', '1929年的英国，惠特克太太（克里斯汀•斯科特•托马斯 Kristin Scott Thomas 饰）是贵族家庭的掌门人，她精心操持着家务，平衡着丈夫（科林•费斯 Colin Firth 饰）及两个女儿的关系。不过，一切却因长子约翰•惠特克（本•巴恩斯 Ben Barnes 饰）的归来被打破了。约翰闪婚的妻子是明艳动人的美国赛车手拉丽达（杰西卡•贝尔 Jessica Biel 饰）。她的很多行为都被正统的婆婆视为放浪。并且，两个女儿也看她不顺眼，替哥哥惋惜。拉丽达跟老公的朋友们前去兜风，别人优雅地骑马，她却驾驶着摩托风驰电掣。孤立时，她会跟公公吐露心事，两人甚至在舞会上翩翩起舞。这让事情演变为婆媳间的恶斗……本片改编自诺埃尔•考沃德的戏剧，克里斯汀•斯科特•托马斯凭借此片获英国独立电影奖最佳女配角奖提名，该片还被选作多伦多电影节的放映影片，杰西卡•贝尔在本片中首次献声。', '杰西卡·贝尔', '斯蒂芬·埃利奥特', 7.6, 14004, 'tt0808244', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p881072462.jpg', 0.5, 3.2, 32.6, 45.7, 18, '0.236520,-0.091189,-0.559322,0.744490,-0.006990,-0.388377,0.700849,0.194413,-0.476518,-0.205752,0.339177,0.872633,-0.289356,0.139714,0.299463,0.398486,-0.528394,-0.723529,-0.072695,0.149878,0.167726,-0.300028,-0.204242,-0.141613,-0.162301,-0.272992,0.366562,-0.280332,0.049861,0.400487,0.338329,0.083445,-0.015701,0.219945,0.025828,0.287993,0.191529,-0.130589,-0.113784,0.173409,0.045033,-0.214006,-0.371240,0.070141,0.075247,0.404071,0.593937,-0.133354,0.171995,-0.187037,0.315364,-0.172454,0.261872,0.332633,0.073015,-0.134930,0.308625,0.223193,-0.152188,0.099907,0.174395,-0.034910,-0.538293,0.270566,0.003903,0.130359,-0.697031,0.522046,-0.302896,-0.075036,0.031448,-0.199775,0.171174,0.123046,0.092310,0.281973,-0.093506,0.085695,-0.501993,0.398126,0.389925,0.187491,-0.196181,0.366907,-0.412851,-0.326243,-0.107138,-0.233684,-0.848343,-0.103658,0.413186,-0.237939,0.291185,0.377971,-0.370108,-0.114484,-0.244555,-0.142908,-0.267570,-0.451777,0.156292,-0.784179,0.100209,-0.574997,-0.300222,-0.206913,0.037405,-0.191539,0.580092,-0.491549,0.114708,0.567744,0.085411,-0.335852,0.673123,0.126038,0.239639,-0.224434,-0.350995,0.112948,-0.288441,-0.069816,0.259107,0.478630,0.205331,-0.115814,-0.145699,0.528776', '30162520',