INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3007826', '摔角王', '剧情', '绰号“大锤”的兰迪•罗宾森（Mickey Rourke 米基•洛克 饰）是上世纪80年代美国独立摔角圈中一颗耀眼的明星，他留下了无数经典的比赛，其绝招“大锤粉碎压”更虏获众多狂热的摔角爱好者。但随着行业的飞速发展和身体健康状况的下降，属于“大锤”的时代早已远去。出于对摔角的热爱，兰迪始终没有离开这个圈子，他忍受着生活拮据，忍受着伤痛困扰，只为了和陪伴多年的摔角迷们享受每一次秀所带来的莫大快乐。他固执地追逐着最后一丝荣光，私人生活却越来越糟。长年奔波以致和女儿斯蒂芬妮（Evan Rachel Wood 埃文•蕾切尔•伍德 饰）的关系疏远，剧烈的撞击和不断摄取处方药又令他的心脏接近崩溃边缘。孤独的他只能在每次艰苦的比赛之后，从脱衣舞女卡西迪（Marisa Tomei 玛丽莎•托梅 饰）那里得到些许短暂的安慰。因身体的原因，兰迪决定退出摔角圈，做一份稳定的工作，并找回家庭的温暖。但经理人策划了一场二十周年的经典重赛。为了毕生钟爱的摔角、为了狂热执著的摔角迷、为了心中长久以来所坚持的，兰迪终于再次披挂上阵，重返擂台……本片荣获2008年威尼斯电影节金狮奖、2009年英国艺术电影电视学院奖（BAFTA）最佳男主角奖（Mickey Rourke）、2009年金球奖最佳原创歌曲和最佳男主角。', '米基·洛克', '达伦·阿伦诺夫斯基', 8.3, 43998, 'tt1125849', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2508065161.jpg', 0.2, 1.1, 14.8, 49.3, 34.5, '-0.164958,0.005455,-0.553814,0.482581,0.126112,-0.298435,0.727375,0.040542,-0.396170,-0.212769,0.237516,0.719181,-0.348877,-0.033771,0.309761,-0.018440,-0.167050,-0.902756,-0.218983,0.085991,0.037281,-0.298874,-0.395253,-0.011264,-0.370613,-0.386446,0.832003,0.016721,-0.144191,0.520588,0.394563,0.304907,0.273317,0.150147,0.023739,-0.138314,0.005683,-0.094665,-0.352053,0.221864,0.330816,-0.160097,-0.344763,0.149138,0.071567,0.137029,0.620677,-0.148778,0.111398,-0.167798,0.527832,-0.171542,-0.215141,-0.082611,-0.061122,0.135654,0.266509,0.105108,-0.205830,0.050736,0.204854,-0.137812,-0.663851,0.006334,0.166344,0.014564,-0.434625,0.613147,0.004325,-0.040112,-0.026951,-0.212880,0.029453,0.181510,0.276180,0.321875,-0.351520,0.210503,0.029545,0.398179,0.611409,-0.069996,-0.436582,0.146456,-0.564557,-0.307336,-0.170408,-0.367767,-0.691044,-0.207605,0.407429,0.315771,-0.086400,0.394680,-0.439144,0.216887,-0.240345,-0.484523,0.040137,-0.458464,-0.026708,-0.662686,-0.158852,-0.344729,-0.007415,-0.248355,0.072575,-0.264305,0.717352,-0.723790,0.449396,0.671670,0.002147,-0.106924,0.551254,0.181658,0.048628,-0.100352,-0.308038,0.592510,-0.314390,0.059089,-0.118607,0.195950,0.019829,0.063719,-0.377236,0.756838', '1299663', '3811356', '1303034', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3008068', '告密者', '剧情', '正享受快乐家庭聚会的某建筑公司老板约翰·马修斯（道恩·强森 Dwayne Johnson 饰）突然接到前妻（梅琳娜·卡纳卡罗兹 Melina Kanakaredes 饰）的电话，他那刚满18岁的儿子詹森·科林（拉菲·格拉沃恩 Rafi Gavron 饰）受到朋友蛊惑签收 一件装有毒品的包裹，结果被CIA当场抓包，因涉嫌毒品分赃面临长达十年的监禁。对儿子的童年深感愧疚的约翰，无论如何也不相信这样的指控。在尝试各种办法无果之后，他决定亲手揪出那个令儿子身陷囹圄的毒枭。在征得政府官员同意后，通过一名前雇员牵线，约翰成功与某贩毒组织建立联系。为了营救儿子，这名父亲踏上通往地狱的凶险路程……©豆瓣', '道恩·强森', '里克·罗曼·沃夫', 6.1, 8010, 'tt0882977', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1953381566.jpg', 2.9, 17.7, 57.9, 16.4, 5.1, '-0.029495,0.007853,-0.513449,0.268536,0.084225,-0.367143,0.536247,0.265694,-0.412505,-0.329243,0.272919,0.606589,-0.148294,0.320351,0.385983,-0.064145,-0.378699,-0.395968,0.088450,-0.179054,-0.180406,-0.404731,0.098896,-0.215021,0.083895,-0.151610,0.374003,-0.021630,0.097371,0.329564,0.286801,0.751651,0.059367,0.157700,-0.003128,-0.152383,0.372307,-0.180049,-0.526810,0.092950,-0.008828,0.118211,0.350429,-0.076978,0.119368,0.383949,0.330984,-0.222956,-0.230053,-0.217395,0.210153,-0.360246,0.123332,0.142788,0.167921,0.044660,0.042567,0.252744,-0.420836,-0.199320,0.176008,-0.223984,-0.586111,-0.129868,0.065385,0.066241,-0.333792,0.057585,-0.264012,0.260141,0.059103,-0.189808,0.014119,0.602952,0.171738,0.246886,-0.094105,0.318577,-0.462901,-0.020238,0.440661,-0.303985,-0.044273,0.036518,-0.200954,-0.408884,0.118096,-0.106408,-0.370100,0.086500,0.307583,-0.024782,-0.016163,0.129847,-0.475125,-0.400448,-0.313110,-0.005750,0.226457,-0.288333,-0.128030,-0.463247,-0.031521,0.113553,-0.226138,0.011115,0.149589,-0.292362,0.285156,-0.365461,0.195131,0.484480,0.388086,-0.407172,0.415689,0.269918,0.160441,-0.405674,-0.032353,0.483837,0.367771,0.121958,0.063999,0.003325,0.285655,-0.286776,-0.216785,0.046900', '3569910', '26260853', '20277632', '3014957');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3008247', '穿条纹睡衣的男孩', '剧情', '八岁男孩布鲁诺（Asa Butterfield 饰）一家随着纳粹军官父亲的一纸调令，由柏林搬迁到了乡下。失去了朋友们的布鲁诺很快对新家附近的“农庄”产生了兴趣，那里有一群身穿“条纹睡衣”的人终日忙碌，并且其中一个为布鲁诺一家服务，他形容肮脏，态度慎微。周遭环境和布鲁诺的举止让母亲暗暗担忧，但纳粹父亲制止家中任何怀疑既定政策的行为。布鲁诺偷偷结识了铁丝网另一边的同龄男孩施穆尔，并时常带给他食物吃。在紧张的家庭氛围和姐姐向成人世界的变化中，施穆尔是布鲁诺惟一的朋友。某日布鲁诺决定，去铁丝网的另一边，以便见到施穆尔的父亲……本片根据约翰·伯恩的同名小说改编，获2008年芝加哥国际电影节观众票选奖。©豆瓣', '阿萨·巴特菲尔德', '马克·赫尔曼', 9.2, 515213, 'tt0914798', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1473670352.jpg', 0.1, 0.2, 4.4, 31.8, 63.4, '0.303775,-0.237178,-0.397591,0.543570,-0.136235,-0.068162,0.597277,0.342872,-0.594345,-0.320042,0.135785,0.792339,-0.093129,0.383890,0.412498,0.021516,-0.444312,-0.484047,-0.244084,-0.134962,-0.200742,-0.343944,-0.227168,-0.513501,-0.053488,-0.354283,0.381954,-0.129301,-0.007454,0.647609,0.223241,0.120367,-0.016163,0.411413,0.079046,0.114889,0.289870,-0.158332,-0.313167,0.026698,-0.201561,-0.137024,-0.175082,0.291177,0.190330,0.468392,0.661538,-0.162082,-0.164350,-0.251064,0.481400,0.058745,0.287636,0.054878,0.288651,0.032670,0.184345,0.021689,-0.069084,0.080236,-0.096981,-0.151781,-0.271239,-0.038496,0.192439,0.124427,-0.452999,0.272477,-0.057867,-0.121687,-0.008051,-0.342457,0.042395,-0.007550,0.128928,0.413930,0.056596,-0.033576,-0.295315,0.095108,0.386608,0.038350,-0.207162,0.083453,-0.581685,-0.187563,0.072949,-0.009928,-0.462781,-0.085562,0.224738,0.027555,-0.023903,0.103714,-0.513443,-0.181436,-0.044378,-0.306660,0.225779,-0.270487,-0.105430,-0.739371,-0.036317,-0.289177,-0.235660,-0.238362,-0.055896,-0.208445,0.635787,-0.552418,0.113891,0.490690,0.307059,-0.381456,0.611826,-0.012003,0.344168,-0.062238,-0.145472,0.281480,-0.038752,0.128029,-0.055995,0.327618,-0.119717,-0.129994,-0.200082,0.366285', '3811356', '3154392', '35161768', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3008253', '百货战警', '喜剧', '商场保安保罗（凯文·詹姆斯 Kevin James 饰）的梦想是成为一名警察，但低血糖的体质让他在新泽西警察学校的考试中再次失败，保罗带着颓意返回家中，母亲和女儿给予安慰并劝说他再找一位爱人。保罗又开始了每天平淡的工作：指路或是被商场的孩子们捉弄，但今天，他的目光被假发柜台的艾米（杰玛·梅斯 Jayma Mays 饰）深深吸引，保罗希望在艾米面前彰显男儿本色，但无奈庞大的身躯和偏弱的体质总是令他的自尊受损。这天，一群匪徒占领了商场，计划对店面和银行进行暴劫，而躲在游戏厅中的保罗对这一切浑然不觉，当他赤手空拳面对劫匪时，剩下的只有逃跑，然而保罗意识到艾米被劫为人质时，他决定不顾一切返回商场……©豆瓣', '凯文·詹姆斯', '史蒂夫·卡尔', 6.2, 17111, 'tt1114740', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1775086243.jpg', 2.1, 13.8, 59.4, 20.1, 4.6, '0.296635,0.150145,-0.642091,0.473476,-0.332799,-0.343311,0.768570,0.261339,-0.433880,-0.248501,0.317462,0.868580,-0.113964,0.287133,0.250280,-0.015198,-0.175166,-0.684612,0.006227,-0.028087,-0.291740,-0.379209,-0.136475,-0.248496,-0.168424,-0.228884,0.588276,0.124304,-0.130009,0.613078,0.203369,0.294956,0.214398,0.575952,-0.116570,-0.033055,0.136308,-0.188219,-0.098224,0.354489,0.253823,-0.273458,-0.259350,0.405939,-0.047584,0.284065,0.745679,0.112573,-0.088914,-0.025247,0.267295,-0.321007,0.078520,0.351262,0.188339,0.062167,-0.028031,0.090508,-0.102032,0.039773,0.195927,-0.013091,-0.696411,0.007836,-0.170317,0.022886,-0.778652,0.337134,-0.197442,0.091447,0.203395,-0.271562,0.143862,0.198891,0.131122,0.467800,-0.272250,0.012965,-0.571007,-0.132951,0.351627,-0.073659,0.040740,0.282909,-0.220341,-0.189484,0.157458,-0.217577,-0.458806,-0.121872,0.163528,0.120172,-0.280525,-0.036560,-0.528730,-0.032055,-0.272709,-0.348926,-0.139909,-0.535156,-0.172800,-0.787995,-0.029399,-0.350918,-0.258420,0.090063,-0.017117,-0.067492,0.612822,-0.724329,0.164853,0.781435,0.446274,-0.477184,0.696382,0.008230,0.206522,-0.079399,0.030363,0.114066,0.090551,0.328456,0.200889,0.300777,-0.147527,-0.039066,-0.341730,0.527494', '3326747', '25928048', '3811356', '3285642');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3008256', '罗马情缘', '喜剧', '纽约古根海姆美术馆年轻的现代艺术馆长贝丝（克里斯汀·贝尔 Kristen Bell 饰）是个工作狂，她很不看好妹妹一见钟情式的闪电结婚，却依然挤出时间飞往意大利罗马参加婚礼。在婚礼上，贝丝对前橄榄球员的尼古拉斯（乔什·杜哈明 Josh Duhamel 饰）一见钟情，却在古老的爱情许愿池边看到尼古拉斯亲吻别的姑娘。大失所望的贝丝趁酒醉跳进许愿池大声斥责爱神雕塑，并捡起了别人投下的三枚硬币及一枚赌桌筹码带回了美国。没想到古老的意大利传说竟然显灵，被贝丝捡到硬币的男人纷纷向她疯狂求爱，焦头烂额的贝丝却还得顶着老板莎莉丝特（安杰丽卡·休斯顿 Anjelica Huston 饰）的压力确保艺术馆年度筹款酒会的成功。关键时刻竟是尼古拉斯帮了大忙，而就在贝丝幸福地坠入爱河之际，她才意识到，那枚从许愿池拣得的筹码竟属于尼古拉斯。真情还是假爱？贝丝痛苦万分……©豆瓣', '克里斯汀·贝尔', '马克·斯蒂文·约翰逊', 6.2, 17481, 'tt1185416', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p501872321.jpg', 2, 14, 59.5, 20.5, 4, '0.096928,0.213823,-0.779260,0.462430,-0.219969,-0.499100,0.719370,-0.018451,-0.073769,0.141925,0.559386,0.623186,-0.403740,0.264893,0.443898,0.353881,-0.305614,-0.472369,-0.062233,0.027151,-0.345612,-0.333186,-0.364719,-0.075583,-0.096921,-0.243823,0.272965,0.060193,-0.120525,0.339512,0.399724,0.201297,-0.090956,0.360787,-0.275751,0.065044,0.115338,0.181285,-0.177026,0.247476,-0.038517,-0.300128,-0.102579,0.203163,0.074963,0.206411,0.538974,-0.258444,0.250898,0.096588,0.303540,-0.211696,-0.025192,0.129819,0.086908,-0.094018,0.010585,-0.153256,-0.153110,0.024526,0.485537,-0.190874,-0.399787,0.292745,-0.031988,0.377723,-0.430501,0.542539,-0.360454,0.192013,-0.072647,-0.244410,0.064492,-0.026851,-0.048047,0.337419,-0.321742,0.042650,-0.412717,0.164364,0.233322,0.064502,-0.044496,0.473824,-0.162314,-0.377063,0.050302,0.029295,-0.230589,-0.091817,0.402250,-0.182957,0.116114,0.093995,-0.602965,-0.085495,-0.210703,-0.211824,0.256692,-0.221962,-0.080797,-0.670429,0.119047,-0.088832,-0.367685,-0.061037,0.097374,-0.075718,0.490821,-0.361579,0.210397,0.742396,0.135176,-0.005449,0.547261,0.049174,-0.198460,-0.176697,-0.250076,0.433540,0.093908,0.182641,-0.062013,0.303967,-0.012927,-0.186872,-0.313242,0.520472', '1301686', '2269893', '34461680', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3008263', '失落的大陆', '喜剧', '量古生物学学家瑞克•马绍尔（威尔•法瑞尔 Will Ferrell 饰）提出了时光旅行的设想，并征得1500万美元的经费专门开发穿越时空的超光速粒子仪。然而公众对此并不买帐，反而对其大肆嘲笑和抨击。3年来，瑞克无奈窝在一所小学里教书，自暴自弃。某天，来自剑桥的美丽女子霍莉（安娜•弗莱尔 Anna Friel 饰）找到瑞克，她展示了一块不可思议的化石，以此鼓励瑞克继续他的研究。重获信心的瑞克最终制造出超光速粒子仪，他和霍莉来到化石的发现地，准备进行时光旅行的测试。在有些神经质的威尔（丹尼•麦克布莱德 Danny McBride 饰）的带领下，他们划着皮筏漂流。不料一场强烈地震突然袭来，三人被狂卷的波涛带入一个未知的世界，一场充满惊险和刺激的探险就此展开……©豆瓣', '威尔·法瑞尔', '布拉德·塞伯宁', 5.8, 8802, 'tt0457400', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p709062098.jpg', 8.3, 22.8, 47.1, 15.5, 6.4, '0.350936,-0.167079,-0.638089,0.510728,-0.023294,-0.047709,0.789697,0.128510,-0.159831,-0.090479,0.285101,0.729926,-0.400455,0.017907,0.293929,-0.005338,-0.580551,-0.548238,0.002967,0.060502,-0.012560,-0.645035,-0.289836,-0.062939,0.086719,-0.338280,0.406149,-0.072394,-0.151363,0.799878,-0.138866,0.303894,-0.054824,0.590140,0.066387,-0.076724,0.313453,0.153340,-0.030422,0.250588,0.041582,-0.064473,-0.095954,0.161345,-0.147556,0.292048,0.537038,-0.378524,0.199640,0.114250,0.328779,-0.443200,0.049494,0.153526,-0.160304,0.087363,-0.151545,-0.082041,-0.192018,0.244919,0.216920,-0.242851,-0.550275,-0.064862,-0.118400,0.056192,-0.379320,0.400797,-0.038335,-0.140092,0.028050,-0.242309,-0.224419,0.210251,0.272858,0.368879,-0.363009,-0.045213,-0.154941,0.234763,0.261072,-0.164474,-0.596655,0.241113,-0.088245,-0.380927,-0.038225,0.144407,-0.380690,-0.292282,0.392571,0.277604,-0.111339,0.348642,-0.959909,0.061658,-0.545025,-0.439735,-0.063135,-0.136708,-0.209742,-1.048028,-0.027289,-0.223224,-0.268565,-0.057019,0.147379,-0.373047,0.259075,-0.694552,0.129360,0.582645,0.168115,-0.186536,0.452883,-0.071645,-0.106710,-0.195393,-0.210964,0.309563,-0.119884,0.574589,0.043860,0.540575,0.262535,-0.081171,-0.511993,0.465662', '1297659', '3178770', '3735015', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3008655', '蝎子王2：勇士的崛起', '动作', '在两河流域的古国阿卡德，黑蝎子战士是最菁英的国王御前武士。阿沙是黑蝎子中的佼佼者，阿沙为了维护13岁的儿子玛沙亚斯（Michael Copon 饰），开罪了将军萨贡。掌握黑暗魔力的萨贡驱使毒蝎将阿沙杀害。玛沙亚斯怀着为父报仇的决心加入了黑蝎子行列。六年后，成为黑蝎子佼佼者的玛沙亚斯荣归故里，等待着他的却是仇人萨贡取代老王成为国主。萨贡为考验玛沙亚斯的忠诚，令其杀死亲弟，玛沙亚斯奋起反抗，终不敌萨贡的魔力，逃出阿卡德。玛沙亚斯幼年好友莱拉（Karen Shenaz David 饰）追随他上路，二人远赴埃及，寻找能破解萨贡的神之武器，他们要面对的，是吃人的怪兽米诺陶和非人力所能探晓的冥界……©豆瓣', '迈克尔·科彭', '拉塞尔·穆卡希', 5.7, 8084, 'tt1104123', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1352572154.jpg', 7.8, 21.7, 51.2, 14.1, 5.1, '0.123020,0.038426,-0.361652,0.612623,-0.057052,-0.361182,0.625113,0.080287,-0.304117,-0.173678,0.515817,0.609732,0.260443,-0.213058,0.207670,0.207919,-0.149568,-0.517163,-0.023728,-0.103704,0.087983,-0.244920,-0.505220,0.053478,-0.130421,-0.704821,0.592574,-0.013581,0.074029,0.202267,0.111269,0.374704,0.054907,0.005542,-0.118620,-0.195892,-0.056725,-0.368671,-0.160110,0.270123,-0.292581,0.077636,-0.061513,0.131413,0.083845,0.272885,0.384711,-0.458167,0.542330,-0.334484,-0.031236,-0.581887,0.073664,-0.010377,0.177575,-0.284567,0.014380,0.103317,0.175068,-0.318107,-0.098093,0.081204,-0.787490,-0.024254,0.174686,0.259351,-0.638934,0.342443,-0.311058,-0.140256,0.303590,-0.239355,0.023682,0.278719,-0.004653,0.529629,0.054821,0.003168,-0.719802,-0.102627,0.680262,-0.358043,-0.188455,-0.404495,-0.119057,-0.487061,0.185157,-0.476878,-0.328300,-0.306116,0.538473,0.033118,0.005601,0.578825,-0.740176,-0.135792,-0.497718,-0.030379,0.138178,-0.233892,-0.008056,-0.230707,-0.085307,-0.249968,-0.002026,-0.056786,0.356265,-0.259618,0.604840,-0.631860,0.154558,0.365250,0.569748,-0.342873,0.613139,-0.075707,0.035885,-0.187861,0.056202,0.327787,0.344935,0.363628,0.083496,0.148149,0.136433,-0.186747,-0.524051,0.465068', '1422920', '24750460', '1793491', '1308837');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3008659', '临终千言', '剧情', '杰克（艾迪·墨菲 Eddie Murphy 饰）有一张刀子嘴，为了达到目的，他什么样的话都能说得出口。因为这张嘴，他失去了许多的朋友却并不以为意。一日，杰克的诳语得罪了辛加博士（克利夫·柯蒂斯 Cliff Curtis 饰)——一位神秘的宗教领袖，为了让杰克明白自己的缺点，他召唤来了一颗菩提树。辛加告诉杰克，菩提树上有一千片叶子，杰克每说一个单词，就会有一片树叶凋落，当树叶掉光之时，就是杰克的临终之日。突然被剥夺了自由说话的权利的杰克痛苦不已，失去语言的庇护反而让杰克懂得了“谨言慎行”的真正含义，随着时间的流逝，杰克也开始明白，有些话不能乱说，可是有些话却不能不说。©豆瓣', '艾迪·墨菲', '布莱恩·罗宾斯', 6.8, 10770, 'tt0763831', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1428335743.jpg', 1.2, 8.1, 50.8, 30.8, 9.2, '0.300353,0.318174,-0.567940,0.598049,-0.272063,-0.340120,0.890649,0.017463,-0.385282,-0.132938,-0.080248,0.621324,-0.325140,0.040463,0.010622,0.106942,-0.128467,-0.215236,0.275213,-0.269083,-0.077424,-0.785482,-0.087152,0.032202,-0.216466,-0.178400,0.267666,0.026696,-0.359096,0.115702,0.196731,0.076584,0.752778,0.377488,-0.111894,-0.029902,-0.170740,-0.068693,0.142754,-0.109552,0.260624,-0.134195,-0.291557,0.458977,-0.351789,0.476688,0.279245,-0.177275,-0.039892,0.158107,0.324901,-0.298494,0.248572,0.048430,0.220132,-0.115051,0.158059,0.107477,-0.060704,0.071189,0.262832,0.331838,-0.946452,0.164649,-0.268239,0.395352,-0.475309,0.288441,-0.166448,-0.245224,-0.012557,-0.354084,0.429802,0.102003,0.370148,0.374064,-0.285099,-0.288213,-0.758125,0.028145,0.530476,-0.183230,-0.406752,0.407172,-0.278503,-0.625147,-0.009090,0.053403,-0.092096,-0.159078,0.296160,0.188252,-0.193010,0.020686,-0.417145,0.095535,-0.347295,-0.471075,-0.241287,-0.687522,-0.062162,0.215794,-0.194706,-0.247630,-0.299440,0.119372,0.231578,-0.107756,0.863113,-0.806537,0.281415,0.432248,0.274295,-0.338990,0.279712,0.598281,-0.122371,-0.181557,-0.074742,0.349755,0.117541,0.331190,0.361205,0.300728,0.495610,-0.257657,-0.096093,0.463827', '26341137', '1793491', '25932086', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3008672', '美错', '剧情', '乌西巴尔（哈维尔·巴登 Javier Barden 饰）是个职业通灵师，他能与死人交流从而抚慰那些悲痛的亲人，但能沟通生死的同时，他自己也罹患癌症，只剩两个月寿命，家里还有两个需要照顾的小孩，而孩子的母亲，他的前妻玛拉姆巴塔（玛丽赛·阿尔瓦雷兹 Maricel Álvarez 饰）却是个常年酗酒和药物依赖的妇人，难以依靠。自家一团糟的乌西巴尔还要周旋在一群非法移民和偷渡者中间，帮助他们找工作，逃避警察，还自己掏钱为睡在工厂的移民们买了几个暖气，却不想好心造就一场煤气泄露事故，二十五名非法移民一夜殒身，赤裸裸的惨剧令乌西巴尔无法承受，随着他受到身心双重煎熬，一个肮脏破败的巴塞罗那随之掀开它的幕布……©豆瓣', '哈维尔·巴登', '亚历杭德罗·冈萨雷斯·伊纳里图', 8, 17810, 'tt1164999', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p553292146.jpg', 0.4, 1.9, 21.1, 50.2, 26.3, '0.008247,-0.263444,-0.537002,0.321785,-0.275500,-0.268794,0.687234,0.299256,-0.527335,-0.349129,-0.014546,0.565612,0.113657,0.407745,-0.231614,-0.188992,-0.146494,-0.646102,0.012936,0.100319,-0.441218,-0.375349,-0.173893,-0.443806,-0.376462,-0.273754,0.353682,0.016197,-0.053715,0.031910,0.390297,0.354501,-0.074211,0.289522,-0.338135,-0.275808,0.009314,-0.225771,-0.105967,0.088088,-0.008426,-0.081514,-0.006258,0.094426,0.195937,0.347308,0.606555,-0.218310,-0.039834,-0.223233,0.178249,-0.170225,0.023177,0.255802,0.043380,-0.299221,0.261956,0.030573,-0.377068,-0.053572,0.256161,0.079323,-0.786155,-0.071486,-0.197702,0.053487,-0.680720,0.422354,0.033381,-0.039041,-0.065898,-0.011129,0.099673,0.501682,-0.115675,0.567800,-0.232097,-0.198127,-0.386257,0.269847,0.668265,-0.111635,-0.263659,0.432992,-0.540341,-0.243017,-0.016435,-0.433746,-0.613243,-0.138168,0.425483,-0.115696,-0.179205,0.214086,-0.532402,0.120181,-0.406107,-0.315609,-0.247595,-0.135491,0.190014,-0.560360,-0.137374,-0.404721,-0.392904,0.352070,0.340735,-0.059831,0.672414,-0.392605,0.256417,0.631608,0.259749,-0.631957,0.439060,0.183362,0.294390,-0.104575,-0.100896,0.376785,0.018393,0.210951,0.333784,0.247625,-0.020079,0.255828,-0.404983,0.311762', '26678784', '1877596', '25928048', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3008691', '贝尔科实验', '动作', '故事讲述别尔科公司的职员们原本平静的一天被广播里的神秘声音划破，他们被告知公司范围内将强制展开大型逃杀活动，一群平日西装革履的伪善者会不会在死亡面前创造人性丑陋新高度？', '小约翰·加拉赫', '克瑞格·麦克林恩', 6.2, 15665, 'tt1082807', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2410846893.jpg', 2.8, 16.3, 55.6, 19.9, 5.4, '0.493121,0.648125,-0.422945,0.368294,-0.158404,0.539497,0.697569,0.090501,-0.642360,-0.393822,-0.019467,0.609219,-0.423179,0.445625,-0.181437,-0.260364,-0.223558,-0.684100,-1.050341,-0.317464,-0.210560,-0.448980,-0.173983,-0.386257,-0.109759,-0.446527,0.228919,0.047122,-0.350501,0.421300,0.392040,0.254474,-0.344516,0.375281,-0.215547,-0.480383,0.497669,-0.155877,0.048408,0.149179,-0.417549,-0.249509,0.325270,0.358690,-0.227338,0.215954,0.930875,-0.133871,-0.372077,-0.293375,0.862206,0.141071,0.075682,0.213394,0.448017,0.329063,0.591027,0.745759,-0.220753,0.201101,-0.150211,-0.365157,-0.780651,0.023616,-0.118510,0.094905,-0.308760,-0.095845,0.158935,0.121801,0.274766,-0.301616,0.298830,0.019861,0.909872,0.343173,0.109543,0.377458,-0.351042,0.030099,0.812819,-0.351244,-0.508403,0.110746,-0.163610,-0.201189,-0.289393,-0.314145,-0.453540,-0.221124,0.030995,0.218815,-0.172646,0.241758,-0.618364,0.114914,-0.192012,-0.508458,-0.196196,-0.167037,-0.546622,-0.838398,-0.124203,-0.077087,-0.288842,0.288101,-0.165433,-0.038788,0.752809,-0.614678,0.505730,0.434342,0.370801,-0.103353,0.612242,-0.179125,0.205749,-0.034326,0.177949,0.053625,0.269127,0.424019,0.057126,0.208032,-0.616320,-0.420616,-0.477300,0.478895', '3318306', '10466639', '27199913', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3009079', '另一个女人', '剧情', '本片原名《爱以及其他不可能的诉求》，根据阿耶莱-沃尔德曼的同名小说改编。也是娜塔莉·波特曼参与制片的首部电影。艾米莉亚·格林里夫（娜塔丽·波特曼 Natalie Portman 饰）的生活正陷入一团乱麻。因失去了尚处襁褓中的爱女伊莎贝尔而无比悲痛，同时作为律师杰克·沃尔夫（斯科特·科恩 Scott Cohen 饰）的第二任妻子过着郁闷的生活。更因背负家庭破坏者的恶名，还要应对杰克的前妻卡洛琳（莉莎·库卓 Lisa Kudrow 饰）的怨恨和攻击。而如何与继子威廉姆相处不但考验着她为人处世的能力，更让她再度陷入对失去的孩子的悲伤回忆，她该如何从生活的困境中走出？©豆瓣', '娜塔莉·波特曼', '唐·罗斯', 7.3, 12461, 'tt1032825', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p776180630.jpg', 0.3, 2.7, 40.1, 45.9, 10.9, '0.132427,-0.129290,-0.534560,0.615628,0.156837,-0.586568,0.783942,0.187028,-0.482998,-0.462861,0.102371,0.677375,0.076436,0.261111,0.169932,0.031342,-0.512470,-0.661784,-0.154762,0.027393,-0.139243,-0.661747,-0.202344,-0.219593,-0.022102,-0.409233,0.726608,-0.078374,-0.233022,0.123657,0.313144,0.588994,-0.007986,0.445936,0.142757,0.124601,-0.004714,-0.130932,-0.486692,0.022451,0.473246,-0.008774,-0.220962,0.271979,-0.026179,0.193519,0.887109,-0.585930,0.133293,-0.155612,0.391255,-0.177939,-0.078079,0.041775,0.055643,-0.107064,0.078280,0.120828,-0.274672,0.139369,0.098752,-0.151803,-0.917240,0.015984,0.199741,0.454242,-0.506414,0.205599,-0.269825,-0.068437,0.219608,-0.106316,0.015385,0.458469,0.312608,0.554638,-0.350899,-0.107937,-0.248332,0.182646,0.590088,0.144097,-0.104703,0.400048,-0.753962,-0.478311,-0.194655,-0.258492,-0.872782,-0.248499,0.244939,0.140045,-0.008817,0.762423,-0.448870,-0.105174,-0.318920,-0.147887,-0.062169,-0.540103,0.063636,-0.722130,-0.351209,-0.314051,-0.161904,-0.242197,0.040062,-0.374138,0.721255,-0.853237,0.228797,0.196809,0.388615,-0.257300,0.530933,0.149295,0.300650,-0.225400,-0.254325,0.913567,0.028823,-0.300210,0.043187,0.030910,0.042043,-0.149626,-0.279717,0.599063', '10533913', '1296992', '30401849', '3160978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3009161', '守法公民', '剧情', '克莱德·谢尔顿（格莱德·巴特勒 Gerard Butler 饰）是居住在费城某小镇的一名研发人员，他有着美丽的妻子和可爱的女儿，生活幸福美满。但这一切都被突如其来的灾难所摧毁。某晚，两个暴徒闯入他的家中，妻子和女儿都受到残害。然而虽然证据确凿，但由于司法程序的迂腐和尼克·瑞斯（杰米·福克斯 Jamie Foxx 饰）助理执行官的堕落，最终让首犯克拉伦斯·多比（克里斯蒂安·斯多特 Christian Stolte 饰）因证据不足只得到10年徒刑。本以为一切归于沉寂，但10年后当年未了的风波再起。怀着巨大仇恨的克莱德开始筹划展开报复，先是干掉了当年的从犯阿米，接着他很快找到了邪恶无耻的多比，并对其进行残酷的折磨与虐杀。克莱德的仇恨得到巨大的宣泄，但是他的复仇还未就此停止。他所针对的不只是那两个暴徒，而是整个腐朽堕落的司法系统……©豆瓣', '杰米·福克斯', 'F·加里·格雷', 8, 111462, 'tt1197624', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p769555454.jpg', 0.4, 1.6, 19.5, 52.4, 26.1, '0.343498,0.025578,-0.725978,0.425835,-0.231782,-0.342430,0.980571,0.095260,-0.429266,-0.394626,0.137606,0.624673,-0.113355,0.124995,0.126750,0.054501,-0.355753,-0.597387,-0.120577,0.022339,-0.033592,-0.549969,-0.192003,-0.206730,-0.043991,-0.324272,0.755531,0.222403,-0.103224,0.229080,0.179661,0.425269,0.039619,0.503932,-0.067448,0.094012,0.064295,-0.040874,-0.224059,0.161264,0.060547,-0.154294,-0.079025,0.291182,-0.249447,0.532860,0.498538,-0.553636,-0.212394,-0.350874,0.373956,-0.565117,-0.106654,0.384004,0.165638,-0.012928,0.064654,0.307586,-0.372458,-0.016408,0.140562,-0.112117,-0.817721,-0.145078,0.000558,-0.012895,-0.372143,0.485539,-0.098272,-0.005512,0.059087,-0.053073,0.046282,0.430548,0.252149,0.463187,-0.231157,-0.087516,-0.552071,-0.085861,0.674480,-0.118813,-0.532211,0.118523,-0.255624,-0.530924,0.058926,-0.410778,-0.359844,0.009640,0.228120,0.245164,-0.069496,0.545066,-0.583737,-0.017444,-0.519426,-0.162655,-0.106619,-0.591250,-0.277748,-0.535537,-0.283741,-0.293441,-0.421538,-0.010229,0.177763,-0.312849,0.495512,-0.792114,0.421690,0.403116,0.240648,-0.578536,0.281967,0.174880,0.124630,0.068393,-0.259575,0.404353,0.190231,0.277555,0.236942,0.192866,0.172576,-0.232422,-0.123544,0.483142', '25828589', '1428054', '1