INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3009168', '不朽', '动作', '影片改编自法国作家Franz-Olivier Giesbert在2006年出版的同名小说。故事取材于法国上世纪70年代末发生在雅克贝特的一起真实暴徒火拼事件。Charly Matte（让·雷诺 Jean Reno 饰）曾是马赛流氓帮的一位教父级人物，在经历了一段漫长的马赛黑手党生涯之后，告别混乱的生活，开始走向正道。三年间，这个只求平静度日了此余生的男人平静的和老婆孩子享受天伦之乐，以为可以彻底告别过往那段阴暗的岁月。但是在一个寒冬的清晨，一切都彻底被改变，Charly遭到伏击，身中数枪，倒在车库中。医生在Charly的身体里发现了22颗子弹，而他却奇迹般地得以生还。到底是谁策划了这次谋杀，又是谁出卖了他，一切真相都将被揭开……©豆瓣', '让·雷诺', '理查德·贝里', 6.8, 9450, 'tt1167638', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p539195395.jpg', 1, 7.5, 49.5, 33.2, 8.9, '0.247502,0.164683,-0.538696,0.347253,-0.064939,-0.307176,0.674535,-0.292417,-0.592330,-0.217311,0.162244,0.635513,-0.327172,0.228132,0.300655,-0.052387,-0.327861,-0.880306,-0.070334,-0.231162,-0.362594,-0.421278,-0.342982,-0.012342,0.021523,-0.321570,0.648928,0.353294,0.030003,0.238581,0.129339,0.167095,-0.156935,0.341189,-0.274319,0.187513,0.048191,0.121169,-0.445328,0.119344,-0.111379,-0.709948,-0.178590,0.140169,-0.060489,0.117516,0.640643,-0.189502,-0.157570,0.160313,0.444848,-0.241969,-0.335547,0.192548,0.383868,0.028712,0.142733,0.471405,-0.019559,-0.171582,-0.076784,-0.043297,-0.639197,-0.014169,-0.126871,0.178830,-0.647388,0.469141,0.006452,0.064282,0.042136,-0.195118,0.370539,0.371369,0.533381,0.485218,-0.142289,0.066941,-0.505967,0.431518,0.954367,-0.129615,-0.305442,0.445489,-0.035392,-0.332660,-0.137900,-0.260724,-0.605834,0.141890,0.258469,-0.067405,-0.456906,0.613588,-0.531117,0.204161,-0.218436,-0.285352,-0.025421,-0.317407,-0.237893,-0.354397,-0.409041,-0.309149,-0.207829,0.071307,0.116213,-0.389263,0.699178,-0.643236,0.441663,0.432025,0.052949,-0.259062,0.601083,0.183276,0.033490,0.057038,0.194546,0.408187,0.118324,0.300792,0.091474,0.364255,-0.130849,-0.049913,-0.428513,0.486225', '30162520', '1870682', '25721544', '4861627');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3010409', '冷血悍将', '动作', '本片由斯特法诺·索利马执导，泰勒·谢里丹担任编剧，根据汤姆·克兰西创作同名小说改编，讲述前特种兵约翰·克拉克(乔丹饰)女友被贩毒组织杀害，可就在他决定复仇时，华盛顿高管要求他完成解救高级军官的秘密任务。杰米·贝尔仍在就加盟本片进行最后谈判。', '迈克尔·B·乔丹', '斯特法诺·索利马', 5.7, 8855, 'tt0499097', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2638872429.jpg', 5.2, 27.3, 50.9, 11.8, 4.8, '-0.079131,-0.199314,-0.314959,0.443113,0.174665,-0.552893,0.022413,0.035775,-0.137449,-0.390102,0.354295,0.759116,0.009085,-0.297959,0.433269,-0.107435,-1.007665,-0.669223,0.057405,-0.040902,0.215282,-0.704431,-0.181179,-0.493410,0.187168,-0.457892,0.899546,-0.311589,-0.298768,-0.052064,0.431225,0.413704,-0.112286,-0.022394,0.522790,0.134148,1.005733,-0.272233,-0.317681,0.548129,-0.026749,0.073659,-0.060586,-0.185472,0.339042,0.497670,0.389542,-0.273433,0.232637,-0.082761,0.289357,-0.335736,0.304203,-0.257615,0.250011,0.282936,0.221988,0.530594,-0.097621,0.046359,-0.306547,-0.369352,-0.876594,-0.039874,0.198778,0.245215,-0.515073,0.061446,-0.640411,0.466934,0.263583,-0.277653,-0.329738,0.262777,0.593989,-0.033079,0.267404,0.176658,-0.061866,0.656311,0.229351,-0.162441,-0.151730,-0.129066,-0.077619,-0.355093,0.075440,-0.111167,-0.285974,0.208993,0.199082,-0.162383,0.229603,0.327783,-0.286688,-0.519903,-0.436392,-0.024677,-0.032750,-0.159878,0.162463,-1.259568,-0.014798,0.756040,0.097676,-0.437147,0.239415,-0.233910,0.490796,-0.568328,0.351750,0.631015,0.133445,-0.245717,0.381576,0.237057,0.358749,-0.637486,0.110635,0.464161,0.194051,0.214475,0.188285,0.189148,0.319991,-0.512048,-0.036294,0.408409', '1293572', '1298616', '2028645', '34961898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3010828', '我的爱', '爱情', '本片是一部关于爱情记忆的影片，透过“日全食”这一天文现象将四段爱情集结：一次偶然的机会，素贤（李延熙 饰）暗恋师兄京宇（郑日宇 饰）重逢，在校友聚会上，她主动对心上人展开了攻势，但结果却不如意；地铁司机世镇（甘宇成 饰）爱上了女乘客珠媛（崔江姬 饰），但他总觉得女友患有妄想症。当她因故缺席自己生日会后，他才真正理解她爱的方式；广告公司女强人秀晶（林晶恩 饰）爱上了大自己12岁的师兄正锡（柳成龙 饰），但是这段办公室恋情却遭遇难题，原来正锡始终难以忘怀亡妻，而孩子则成了他酗酒之外的唯一安慰。她开始接近他，一切却变得异常艰难；一个呼吁免费拥抱运动的流浪汉振万（严泰雄 饰），为了5年前对女友的承诺回到汉城，但他需要面对物是人非的现实。©豆瓣', '甘宇成', '李翰', 7.7, 5650, 'tt1233484', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p700719661.jpg', 0.5, 3, 31.1, 43.6, 21.9, '-0.004460,0.082162,-0.533893,0.414038,0.031488,-0.232515,0.795831,0.008970,-0.454668,-0.358990,0.263454,0.609187,-0.198822,0.320842,0.157043,-0.052607,-0.055942,-0.595349,0.426072,0.002932,-0.211720,-0.231031,-0.180587,-0.108698,-0.083037,-0.073786,0.572103,0.116935,-0.161255,0.335152,0.427707,0.028131,0.207923,0.548091,0.063849,-0.008588,0.101754,0.258902,-0.291249,-0.043030,-0.063272,-0.371261,-0.143596,0.455033,-0.175611,0.333190,0.653325,-0.176431,-0.393450,-0.017479,0.446888,-0.244275,-0.104796,0.083130,0.087210,0.258692,0.344880,0.102818,-0.011713,-0.164916,-0.072702,-0.050625,-0.407642,0.047180,0.106544,0.002287,-0.278180,0.405754,-0.321824,0.098291,-0.044323,-0.444087,0.032092,0.235847,0.446926,0.193590,-0.409253,0.013251,-0.203710,0.386873,0.566986,0.085561,-0.240289,0.713743,-0.403302,-0.437170,-0.060290,-0.228007,-0.538417,0.327421,0.001341,-0.146102,-0.183863,0.140048,-0.309144,-0.027992,-0.207306,0.064366,-0.099058,-0.279284,-0.017417,-0.183668,-0.122538,-0.255591,-0.388631,-0.078571,0.071655,-0.445937,0.629999,-0.730013,0.096155,0.526520,0.317451,-0.623599,0.763098,0.356093,-0.162126,-0.425521,0.103431,0.462259,-0.269902,-0.026808,-0.091072,0.142028,-0.101834,0.007516,-0.423709,0.449745', '1389971', '27191829', '4275444', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011022', '狐狸猎手', '剧情', '马克（查宁·塔图姆 Channing Tatum 饰）是一名职业摔跤手，在过去的职业生涯中，他也曾有过辉煌的胜利，然而，如今，一切光芒都已经散去，他不过只一个碌碌无为的无名小卒。马克的哥哥大卫（马克·鲁法洛 Mark Ruffalo 饰）也是一名摔跤手，兄弟两人彼此之间 关系十分要好，可是，马克明白，大卫有自己的家庭和事业，而自己却只有摔跤。某日，马克意外受到了一位名为约翰（史蒂夫·卡瑞尔 Steve Carell 饰）的神秘富商的邀请，希望马克能够成为他所组建的摔跤队中的一员，在约翰的摔跤队中，马克找到了自己的价值所在，深受约翰重用的他成为了约翰唯一的朋友，然而，随着时间的推移，当大卫也加入了摔跤队后，一切都开始改变。本片根据真实故事改编。©豆瓣', '史蒂夫·卡瑞尔', '贝尼特·米勒', 7.4, 24052, 'tt1100089', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2208497877.jpg', 0.7, 3.6, 34.6, 47.5, 13.6, '0.138556,-0.005190,-0.577180,0.556613,-0.133809,-0.526782,0.627097,0.017123,-0.504692,-0.455411,0.236788,0.937680,-0.064667,0.145346,0.298326,0.063739,-0.162984,-0.699357,0.094111,-0.285320,-0.233838,-0.620069,-0.398624,-0.183168,-0.125471,-0.362516,0.837765,-0.017097,-0.303600,0.398574,0.395437,0.200380,0.380471,0.503688,-0.147965,0.256174,0.221280,-0.142550,-0.379865,0.063374,0.080420,-0.037716,-0.259779,0.219053,0.048382,0.394306,0.304959,-0.284545,0.001505,0.205925,0.275457,-0.278911,0.118688,0.103438,0.217355,0.057803,0.185259,0.166988,0.019498,0.173168,-0.111623,-0.061746,-0.975974,0.046853,0.080380,0.314373,-0.761595,0.471508,-0.165117,-0.323736,0.109240,-0.275028,0.150500,0.296412,0.283319,0.197685,-0.245809,0.017487,-0.571283,0.168418,0.825724,0.078507,-0.488601,0.400055,-0.216482,-0.494570,-0.257622,-0.237780,-0.431734,0.135427,0.347733,0.080003,0.162751,0.251179,-0.542584,0.117817,-0.250873,-0.267815,-0.147087,-0.442473,0.171064,-0.468738,-0.267470,-0.375528,-0.407884,-0.092628,-0.049211,-0.411200,0.775684,-0.851957,0.314691,0.643817,0.006479,-0.319027,0.578718,0.262452,0.349757,-0.329642,-0.188863,0.245690,0.195744,0.053975,0.023100,0.344976,0.132436,-0.421862,-0.269233,0.584387', '1793491', '30163500', '1783461', '24875409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011033', '忍者刺客', '剧情', '数千年来，来自东方的忍者刺客只是被当作一个传说，然而柏林的法院调查员米卡（娜奥米·哈里斯 Naomie Harris 饰）在调查一系列政治暗杀案时却把目标锁定在这个传说中古老而又成熟暗杀组织。通过秘密调查，米卡得知一个叫奥祖奴的暗杀集团，而且在一盘监控录像里，米卡看到一张年轻的东方面孔，这个人叫雷藏（Rain 饰）。雪藏年幼时即被奥祖奴的暗杀集团收养，并且把他训练为一个出色的忍者刺客。然而善良的雪藏并未在兽化的训练中泯灭良知，最终因厌倦杀戮而逃离集团，并且隐居于柏林。此时，米卡已成为暗杀集团的追杀对象，在危急关头，雷藏及时出现救下米卡。雪藏希望得到米卡的帮助，从而彻底摧毁奥祖奴……本片由曾执导《V字仇杀队》的导演詹姆斯·麦克提格（James McTeigue）担当导演，亚洲人气小天王Rain主演，这是他在打入好莱坞之后的第二部作品。©豆瓣', '郑智薰', '詹姆斯·麦克特格', 6.3, 16924, 'tt1186367', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p906801407.jpg', 3.3, 16.5, 50.2, 22.3, 7.8, '0.015158,0.164470,-0.543743,0.797497,-0.131744,-0.106248,0.525547,0.011478,-0.339735,-0.547020,0.378858,0.627128,0.089658,0.089309,0.592981,-0.121696,-0.100428,-0.619272,-0.046574,-0.112276,-0.215327,-0.493050,-0.549449,-0.275462,0.005414,-0.546107,0.893513,0.213730,-0.376828,0.299058,0.286526,0.360774,-0.268755,0.250713,0.171069,-0.081486,0.394001,-0.224637,-0.329036,0.628411,-0.346582,-0.355827,-0.058021,0.051183,-0.200074,0.419285,0.359512,-0.224650,0.022963,-0.339592,0.404269,-0.584185,-0.234850,0.013247,0.506876,-0.040501,0.180124,0.212989,-0.410854,-0.266508,-0.085488,-0.230708,-1.148883,-0.065800,0.266829,0.101146,-0.580534,0.290063,-0.360209,0.278637,0.049377,-0.115813,0.202977,0.302637,0.283120,0.209008,0.035489,0.409774,-0.393255,0.140699,0.582407,-0.345342,-0.205574,-0.074259,0.248051,-0.411400,-0.079359,-0.358652,-0.176163,0.138323,0.244822,0.009388,-0.210324,0.224996,-0.467562,-0.172326,-0.350651,-0.036621,0.117489,-0.473690,-0.189277,-0.888593,-0.234550,0.037765,-0.096192,-0.023005,0.017809,-0.240701,0.709035,-0.821400,0.289758,0.502065,0.008652,-0.485485,0.564534,0.181221,0.084569,-0.156799,-0.317304,0.246275,0.473304,0.217635,-0.015701,0.226148,0.051813,-0.435145,-0.325481,0.135970', '27073234', '1793491', '2369613', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011049', '姐姐的守护者', '剧情', '为了让罹患血癌的凯特（苏菲亚·威希涅瓦 Sofia Vassilieva 饰）能够活下去，父母通过基因技术“制造”了与凯特的基因完美配型的小女儿——安娜（阿比吉尔·布莱斯林 Abigail Breslin 饰）。安娜感觉自己只是姐姐凯特的“药罐子”，11年来，凡是在凯特有需要的时候，无论是脐带血还是白血球、肝细胞、骨髓，她都得源源不断的向凯特提供。然而，即使有孤注一掷的妈妈（卡梅隆·迪亚茨 Cameron Diaz 饰）、无可奈何的爸爸，以及身边所有人的爱，凯特的情况还是越来越糟，肾功能的衰竭必须要年仅11岁的安娜捐献出自己的一个肾。这一次，安娜选择了拒绝，并且寻找到律师坎贝尔把母亲告上法庭，她要捍卫自己的身体。然而，法庭上哥哥杰西却吐露了另一番真相……本片根据美国当代畅销书女王朱迪·皮考特（Jodi Picoult）的同名小说改编。©豆瓣', '阿比盖尔·布雷斯林', '尼克·卡萨维蒂', 8.2, 58326, 'tt1078588', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p650019299.jpg', 0.3, 1.3, 17, 50.2, 31.3, '-0.003893,0.108697,-0.426687,0.615697,-0.106068,-0.592338,0.708394,0.180414,-0.349674,-0.135078,0.215191,0.694954,-0.030199,0.246044,0.010553,0.407179,-0.457491,-0.504577,0.114327,-0.208623,-0.363415,-0.543693,-0.238778,-0.143364,-0.121485,-0.448803,0.540312,-0.357009,-0.088580,0.078102,0.270842,0.437316,0.313501,0.300407,0.048917,0.096055,0.098995,-0.278042,-0.198437,0.301905,0.590346,0.074347,-0.035575,0.180592,0.209498,0.380989,0.534612,-0.364644,0.045380,-0.103557,0.580007,-0.099583,0.269558,0.123741,-0.035422,-0.058687,0.251432,0.157195,-0.227250,-0.017488,0.252805,0.145517,-0.926331,-0.204613,0.192432,0.282692,-0.527621,0.163525,-0.206210,0.101596,0.334256,-0.537788,-0.023354,0.370428,0.072444,0.361392,-0.385667,-0.067014,-0.640554,0.029625,0.452356,0.085645,-0.261483,0.307566,-0.463962,-0.522712,-0.043392,-0.257462,-0.612841,0.228150,0.307281,0.127810,-0.123582,0.379558,-0.319634,-0.237574,-0.232895,-0.246874,0.005187,-0.298015,0.141687,-0.498076,-0.149098,-0.274314,-0.249797,-0.052525,0.039486,-0.487343,0.826533,-0.611346,0.081932,0.606767,0.231508,-0.420729,0.495460,0.090380,-0.044975,-0.240226,0.019705,0.384171,0.025463,0.300723,0.276287,0.360702,0.401876,0.077399,-0.509629,0.668939', '27602116', '24284209', '1793491', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011051', '恐怖游轮', '剧情', '单亲母亲杰西（梅利莎·乔治 饰）和一帮朋友乘游艇出海游玩，但她总有一种有不好的事情发生的感觉。不久，他们便在海上遭遇一场强烈的风暴。游艇翻船，众人落海，几经挣扎他们好不容易爬到游艇残骸上来。正当他们无计可施之时，一艘巨大的游轮向众人缓缓驶来。众人欣喜过望，未加思索便登上这艘名为“艾俄洛斯”的游轮，结果发现这竟是一艘1930年便告失踪的神秘之船，而船上更是空无一人。随处可见的鲜血、神秘的指示以及突如其来的凶杀事件，将这群男女带入万劫不复的恐怖轮回之中……©豆瓣', '梅利莎·乔治', '克里斯托弗·史密斯', 8.5, 787884, 'tt1187064', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p462470694.jpg', 0.3, 1.2, 13.1, 43.2, 42.2, '0.251440,-0.107692,-1.166132,0.382448,0.308631,-0.249247,1.151358,-0.086314,-0.634892,-0.085702,0.580457,0.748908,-0.417966,0.170051,0.532723,0.172536,-0.391015,-0.453642,-0.058419,-0.028212,-0.414754,-0.223193,-0.287133,-0.103161,0.024311,0.019185,0.530650,0.378975,-0.013753,0.691347,0.219363,0.466047,-0.448348,0.846224,-0.354977,0.096089,-0.013208,0.167838,-0.011505,-0.240904,-0.375173,-0.419658,-0.134817,-0.042218,-0.089743,0.306852,0.810635,-0.311656,-0.216783,-0.005569,0.026460,-0.275641,0.100846,0.220523,0.352544,0.344662,-0.299355,-0.080292,-0.271482,-0.220660,0.026460,0.333775,-0.221112,0.007483,-0.411761,0.072889,-0.220633,-0.047166,-0.004405,-0.170059,0.071752,-0.128093,0.082450,0.202285,0.089782,0.244503,-0.060879,0.157205,-0.509317,-0.212655,0.835693,-0.041164,-0.181354,0.436527,0.205962,-0.250455,-0.045005,-0.129279,-0.170800,-0.099566,0.766889,0.393968,-0.203746,0.348456,-0.647992,0.085891,-0.531156,-0.570765,-0.306476,-0.048460,-0.462331,-0.809883,-0.121110,-0.122604,-0.089598,0.415340,0.066716,-0.073206,0.401638,-0.299557,0.278006,0.382375,-0.026631,-0.348137,0.438828,-0.214202,0.059080,-0.006249,-0.063497,0.150239,-0.221399,0.396944,-0.053168,0.372394,-0.077121,0.177937,-0.308621,0.270880', '2269893', '1473795', '4724373', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011052', '婴灵恶泣', '悬疑', '正值花季的美丽女孩凯西（Odette Yustman 欧黛尤斯曼 饰）近来饱受困扰，她经常能看到一名面容阴森如幽灵般的男孩充满憎恨地望着她。凯西求助好友和医生，但都不见效果，不过却从眼科医生那里得知自己可能拥有双胞胎兄弟/姐妹的消息。这一点随后在父亲那里得到证实，凯西通过翻检母亲的遗物找到线索，并拜访了身在养老院的索菲（Jane Alexander 饰）——一个二战时期大屠杀的幸存者。索菲向其讲述了纳粹对集中营中的双胞胎所做的残酷试验。而这一切都与凯西的遭遇有着千丝万缕的关系。随着调查的深入，凯西离事实的真相越来越近……©豆瓣', '奥黛塔·安纳布尔', '大卫·S·高耶', 5.5, 6685, 'tt1139668', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1256677489.jpg', 6.1, 27.1, 53.4, 10.3, 3, '0.223741,-0.289323,-0.556666,0.565185,-0.089141,-0.092131,0.964409,-0.140752,-0.700936,-0.418249,0.118246,0.688259,-0.142041,0.278326,0.171826,-0.020384,-0.324069,-0.502937,-0.135804,-0.379136,-0.162898,-0.676227,-0.408662,-0.244367,0.087661,-0.352307,0.551593,0.009535,-0.111156,0.535327,0.139339,0.220503,-0.350640,0.403816,-0.272665,-0.053825,0.116678,0.259696,-0.320896,0.237286,0.348033,-0.156144,-0.081280,0.321463,-0.164264,0.518503,0.593551,-0.353734,-0.200614,0.035247,0.203463,-0.127311,0.112896,0.295731,0.356787,0.094027,0.205906,0.250963,-0.243647,-0.293113,-0.036441,0.100502,-0.631586,0.027259,0.377550,0.408644,-0.340040,0.302709,-0.033018,0.012053,0.264611,-0.233273,0.379719,0.174451,0.027040,0.608845,-0.229523,-0.026414,-0.542746,0.116637,0.520502,-0.111880,-0.125889,0.332873,-0.465653,-0.346293,-0.122367,-0.050136,-0.340959,0.159765,0.180367,0.261695,-0.285252,0.327160,-0.431038,-0.098750,-0.317594,-0.149427,-0.085318,-0.410469,-0.186755,-0.594099,-0.289887,-0.553097,-0.385342,0.161226,0.064599,-0.374498,0.658112,-0.819361,0.225019,0.375616,0.326117,-0.403903,0.579983,0.144027,0.135557,-0.374765,-0.259311,0.560701,0.159692,0.120686,-0.032364,0.140570,0.062367,-0.260557,-0.472006,0.272976', '2002744', '6021916', '1296534', '4301215');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011058', '柏林的女人', '剧情', '1945年，第二次世界大战接近尾声。第三帝国的心脏柏林在盟军的猛烈攻势下已化作废墟，在短暂的交火之后，成千上万的苏联士兵涌入这座颓败之城。躲在掩体下的德国百姓在步枪的威慑下乖乖走出地面，男人的犯下的罪孽转嫁到女人的身上。无数妇女被强奸，却没有任何一个苏联军官出面制止。她（Nina Hoss 尼娜•霍斯 饰），是这群备受屈辱的德国女人中的一员，丈夫远在前线，生死未卜，惶恐无助的她只能一次次忍受屈辱。她将自己委身一位苏联军官，只为在这恶境中求得生存……本片根据根据德国女记者同名日记体作品改编。©豆瓣', '尼娜·霍斯', '马克斯·法贝尔布克', 7.4, 7232, 'tt1035730', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2874243886.jpg', 1.5, 4, 32.9, 44.9, 16.7, '0.182782,0.250294,-0.931696,0.590236,-0.013729,0.075739,0.928277,-0.205709,-0.318223,0.141372,0.789496,0.662603,0.056562,0.157719,-0.024200,-0.210265,-0.173790,-0.887494,-0.525516,-0.112912,-0.285684,-0.233062,-0.378231,-0.349008,-0.311635,-0.384805,1.075188,0.303799,-0.073076,0.224097,0.266836,0.351105,-0.002667,0.619179,-0.241108,0.122879,0.170411,-0.454378,-0.195140,0.203919,-0.129884,-0.666938,-0.090571,0.253289,-0.183756,0.298047,0.855185,-0.422305,0.105048,-0.139900,0.426263,-0.237526,0.034586,0.291378,0.243901,-0.194125,0.063314,-0.016760,-0.142172,0.080282,-0.013342,0.211037,-0.469158,-0.171715,-0.035350,0.177250,-0.782330,0.609621,-0.265891,0.249956,0.076353,-0.322022,0.110248,0.233500,-0.041426,0.389547,-0.509327,0.066449,-0.352717,0.419569,0.819697,0.042030,-0.520837,-0.296794,-0.413423,-0.252751,0.094118,-0.405795,-0.608129,-0.424042,0.423051,-0.314847,-0.110315,0.410648,-0.580502,0.070423,-0.437889,-0.436822,-0.108627,-0.212628,-0.240667,-0.446494,-0.152733,-0.193568,-0.259697,0.255204,0.167783,-0.041522,0.831711,-0.488553,0.268088,0.782690,0.548401,-0.091726,0.492158,0.026470,0.172458,0.240755,-0.092137,0.659429,0.044313,0.542557,0.190706,0.373203,-0.291670,0.081101,-0.400969,0.415963', '21619567', '1467779', '2294568', '1303624');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011091', '忠犬八公的故事', '剧情', '八公（Forest 饰）是一条谜一样的犬，因为没有人知道它从哪里来。教授帕克（理查·基尔 Richard Gere 饰）在小镇的火车站拣到一只走失的小狗，冥冥中似乎注定小狗和帕克教授有着某种缘分，帕克一抱起这只小狗就再也放不下来，最终，帕克对小狗八公的疼爱感化了起初极力反对养狗的妻子卡特（琼·艾伦 Joan Allen 饰）。八公在帕克的呵护下慢慢长大，帕克上班时八公会一直把他送到车站，下班时八公也会早早便爬在车站等候，八公的忠诚让小镇的人家对它更加疼爱。有一天，八公在帕克要上班时表现异常，居然玩起了以往从来不会的捡球游戏，八公的表现让帕克非常满意，可是就是在那天，帕克因病去世。帕克的妻子、女儿安迪（萨拉·罗默尔 Sarah Roemer 饰）及女婿迈克尔（罗比·萨布莱特 Robbie Sublett 饰）怀着无比沉痛的心情埋葬了帕克，可是不明就里的八公却依然每天傍晚五点准时守候在小站的门前，等待着主人归来……本片根据上个世纪30年代发生在日本的真实故事改编，1987年在日本拍成电影后创造了40亿日元的票房。', '理查·基尔', '拉斯·霍尔斯道姆', 9.4, 1319727, 'tt1028532', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2587099240.jpg', 0.1, 0.2, 3.7, 21.4, 74.6, '0.118825,-0.111714,-0.722703,0.354576,-0.056561,-0.366873,0.543191,0.234523,-0.508418,-0.127134,0.312378,0.743689,-0.230465,0.438443,0.304187,0.029242,-0.392699,-0.380615,-0.058205,-0.167496,-0.073893,-0.429437,-0.255530,-0.260174,0.056234,-0.258443,0.345517,0.026772,0.058508,0.489145,0.130637,0.242161,0.024516,0.417107,-0.229958,0.165164,0.089782,0.001297,0.150841,0.110184,0.181778,-0.136280,-0.095204,0.028730,0.182547,0.199601,0.497119,-0.511424,-0.240780,-0.018076,0.251895,-0.125588,0.075321,0.094433,0.338792,-0.234914,0.027420,0.199834,-0.272879,0.177377,0.047084,-0.115787,-0.454531,0.102190,-0.127652,0.305769,-0.696485,0.374474,-0.223790,0.075748,0.322702,-0.558635,0.129245,0.322187,-0.082884,0.441416,-0.011402,0.081049,-0.557502,0.025051,0.245013,-0.196769,-0.111296,0.331874,-0.222807,-0.259488,0.085684,-0.063714,-0.615809,-0.082608,0.269297,0.064525,-0.251747,0.079715,-0.404793,-0.059914,-0.224770,-0.224416,0.019680,-0.364522,-0.074783,-0.591904,0.066509,-0.433245,-0.212666,-0.029286,-0.068470,-0.115352,0.493870,-0.868980,0.574251,0.495295,0.097873,-0.150060,0.674888,-0.077386,-0.120540,-0.247060,0.161395,0.353700,0.051247,0.173309,0.226867,0.338236,0.084488,-0.139010,-0.364449,0.789999', '1292720', '24698878', '3230121', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011093', '成长教育', '剧情', '本片根据英国星期日泰晤士报记者琳·巴贝尔（Lynn Barber）的回忆录改编。1961年，16岁的少女珍妮（凯瑞·穆里根 Carey Mulligan 饰）对父母反复督促她学好拉丁文考上牛津的唠叨不厌其烦，而正在追求自己的男孩又不令父亲杰克（阿尔弗雷德·莫里纳 Alf red Molina 饰）满意。一个雨天，珍妮邂逅了成熟男人大卫（彼得·萨斯加德 Peter Sarsgaard 饰），对方的风流倜傥和举手投足的迷人气质深深吸引了珍妮。大卫和朋友不断带珍妮出入高档酒吧、艺术品拍卖行和高级餐厅，甚至说服珍妮的父母带她游览梦寐以求的巴黎。灯红酒绿中珍妮迅速坠入爱河，只可惜事实真相却并非梦想中那样美好……本片获2009年圣丹斯电影节观众选择奖和摄影奖，被提名剧情片陪审团大奖，并获2009年金球奖最佳女主角提名（凯瑞·穆里根）和奥斯卡最佳电影、最佳女主角（凯瑞·穆里根）和最佳改编剧本三项提名。', '凯瑞·穆里根', '罗勒·莎菲', 7.7, 126215, 'tt1174732', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p465499294.jpg', 0.3, 2, 27.2, 51.4, 19.1, '-0.106173,-0.186876,-0.429570,0.608224,0.185170,-0.370434,0.707033,-0.051880,-0.287711,-0.150509,-0.113319,0.929552,-0.640250,0.314282,0.616895,0.055409,-0.585213,-0.713139,0.034610,-0.115162,0.088329,-0.456141,-0.261489,-0.203027,-0.011791,-0.150629,0.646656,-0.199226,-0.045296,0.737807,0.398403,0.207421,0.085342,0.132336,-0.018138,0.177831,0.621339,-0.007080,-0.340586,0.433864,0.142993,-0.211730,-0.257718,0.114924,0.304395,0.268021,0.704920,-0.199132,0.169610,0.114588,0.472028,-0.232706,-0.001315,0.008251,-0.145463,-0.235842,0.318296,0.055727,0.079833,-0.159871,-0.057072,-0.530692,-0.349646,-0.021145,0.340330,0.110043,-0.176037,0.216835,-0.179223,0.391536,0.021846,0.060926,0.015327,-0.216187,0.288634,0.207049,0.006379,0.039320,-0.288063,0.699970,0.051418,0.108858,-0.388146,0.347179,-0.534422,-0.625822,-0.018936,-0.144846,-0.617568,0.150393,0.455939,-0.100770,0.488013,0.057468,-0.285432,-0.394246,-0.274686,-0.130190,-0.092586,-0.344483,0.085772,-0.900440,-0.088700,-0.291843,-0.070901,-0.226250,-0.085981,-0.281249,0.670152,-0.470137,0.271016,0.388433,0.265907,-0.243804,0.758577,-0.066265,0.229546,-0.461890,-0.188137,0.516454,-0.091123,-0.238067,-0.021695,0.423197,0.032055,-0.156073,-0.356277,0.593525', '34795703', '3275168', '26611806', '6537486');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011094', '下流女孩', '剧情', '在众人的眼中，丹妮尔（朱诺·坦普尔 Juno Temple 饰）是一个让人头痛的不良少女，年纪轻轻的她不仅成绩一塌糊涂，个性也倔强得让人吃惊。无奈之下，对丹妮尔束手无策的母亲将她送往了集中了所有差生的补习班进行“改造”，这让丹妮尔更加的不满。在补习班上，丹妮尔结识了一个名叫克拉克（杰瑞米·多泽 Jeremy Dozier 饰）的男孩，没想到，她和这个个性娘里娘气的胖男孩居然颇为意气相投。两个年轻人对于各自的生活都有诸多的抱怨，也在潜意识里逃避着即将履行责任，就这样，一拍即合之下，两人踏上了发现自我的旅程——寻找丹妮尔未曾谋面的生父。然而，正是这趟特殊的旅程让丹妮尔的个性发生了改变，开始思考起了作为一个人的意义和价值。©豆瓣', '米拉·乔沃维奇', 'Abe Sylvia', 6.7, 6175, 'tt1107319', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1875973568.jpg', 1.9, 10.6, 48, 30, 9.5, '0.431082,0.042042,-0.892362,0.715700,-0.344653,-0.248899,0.766128,0.083361,-0.688726,-0.233150,0.198804,0.781878,-0.244548,0.416251,0.361929,-0.030171,-0.202153,-0.698563,-0.245750,-0.127519,-0.250739,-0.655733,-0.272903,-0.144284,-0.200793,-0.531697,0.589743,0.041358,-0.217260,0.523298,0.417758,0.100983,0.191776,0.597682,-0.254619,0.103626,0.092919,0.070985,0.205432,0.032584,0.212566,-0.319311,-0.060392,0.352160,-0.162072,0.549803,0.783689,-0.220947,-0.384824,0.005068,0.382454,-0.343256,-0.211787,0.255133,0.146797,-0.144983,0.019368,0.093802,-0.300971,0.011317,0.157082,0.132402,-0.891348,0.167024,0.161039,0.141431,-0.802924,0.494909,-0.011334,-0.234042,0.001413,-0.390262,0.121872,0.377056,0.263642,0.341098,-0.205967,0.040220,-0.297265,0.028975,0.610894,0.118016,-0.356172,0.358541,-0.394740,-0.411736,-0.098000,-0.257444,-0.542633,-0.074032,0.194007,0.185100,-0.211251,0.137599,-0.611509,0.179015,-0.087767,-0.214710,-0.113682,-0.605988,-0.060482,-0.484122,-0.111721,-0.514598,-0.612833,0.041590,-0.040509,-0.357727,0.967567,-0.843943,0.025706,0.427859,0.110061,-0.569821,0.638989,0.180583,0.172959,-0.129166,-0.107340,0.150304,-0.041845,0.079949,-0.027245,0.659968,-0.058946,-0.164497,-0.428363,0.486589', '21360412', '1301022', '35144311', '26253737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011102', '假结婚', '剧情', 'Margaret（Sandra Bullock 桑德拉·布洛克饰）是美国一家知名出版公司的高管，办事出色，为人却极为强势，一旦她的身影出现在办公室，气氛立即会降至冰点，员工们在表面上无不对她噤若寒蝉，在心底则暗呼她为“女魔头”。Margaret对这一切置若罔闻，照旧施行铁腕政策，可就在她事业如日中天之际，一个噩耗却几乎把她砸晕——因为某些技术性原因，她的签证无法续签，而她本人不得不被遣送回原籍加拿大。为了保住她苦心经营的一切，Margaret决定和助手Andrew（Ryan Reynolds 瑞安·雷诺兹饰）伪装结婚，以取得在美居住权。在半利诱半胁迫之下，Andrew答应了这个荒唐的要求。移民局将在一周后对两人进行测试，而Margaret对Andrew还是一无所知，这个周末，她和Andrew一同回到他的家乡……©豆瓣', '桑德拉·布洛克', '安妮·弗莱彻', 7.2, 153062, 'tt1041829', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p571879335.jpg', 0.4, 3.6, 43.2, 41.1, 11.7, '0.182220,0.245870,-0.854319,0.612939,-0.290452,-0.150196,0.580630,0.336282,-0.620167,-0.335350,0.218515,0.946145,-0.254146,0.114624,0.188572,-0.155300,-0.191381,-0.707161,-0.144631,-0.252870,-0.105389,-0.382272,-0.015873,-0.287971,-0.375575,-0.098853,0.609810,0.119168,-0.165994,0.334251,0.356239,0.245645,0.174848,0.647229,-0.169994,-0.201466,-0.056946,-0.100433,-0.315921,0.265050,0.210870,-0.451870,-0.200936,0.260469,0.079114,0.396048,0.544050,-0.112700,-0.447244,0.027504,0.365854,-0.590710,-0.162780,0.408241,0.287075,-0.125710,-0.032541,0.359859,-0.453931,-0.027094,0.204504,-0.014086,-0.843654,0.093001,-0.086381,-0.014093,-0.706956,0.548817,-0.393636,0.141660,-0.040580,-0.467952,-0.097196,0.309654,-0.051367,0.457804,-0.153239,0.156963,-0.380675,0.194686,0.685321,0.049194,-0.229048,0.368871,-0.220648,-0.349102,-0.085717,-0.167296,-0.257206,-0.281387,0.154656,0.141074,-0.058251,-0.032296,-0.364460,-0.172445,-0.322223,-0.511261,-0.133194,-0.623088,-0.044866,-0.446264,-0.105581,-0.344949,-0.386119,0.139073,0.186837,-0.029886,0.613305,-0.922819,0.048160,0.477120,0.520036,-0.819688,0.416795,0.257095,0.259656,-0.226637,-0.100024,0.047657,0.101962,0.356376,0.071931,0.257112,0.084875,-0.050666,-0.437671,0.441582', '1301022', '35461732', '1949320', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011235', '哈利·波特与死亡圣器(下)', '奇幻', '当又一次和伏地魔（拉尔夫·费因斯 Ralph Fiennes 饰）的意识连通，哈利·波特（丹尼尔·雷德克里夫 Daniel Radcliffe 饰）断定最后一件魂器藏在霍格沃茨，于是和罗恩（鲁伯特·格林特 Rupert Grint 饰）、赫敏（艾玛·沃森 Emma Watson 饰）一同返回阴云密布的学校。在好友们的帮助下，他们成功驱逐了斯内普（艾伦·瑞克曼 Alan Rickman 饰），然而觉察到哈利目的的伏地魔则率领徒众向霍格沃茨逼近。食死徒、摄魂怪、巨人疯狂涌入这所有着悠久历史的魔法学校，正邪决战旋即爆发，一时间血雨腥风，死伤无数。从斯内普的眼泪中，哈利不仅了解到父辈的故事，也证实了藏缅于他体内最后的秘密。在此之后，他也和伏地魔迎来了最后的对决……本片根据英国作家J.K.罗琳的同名原著改编，也是“哈利·波特”系列影片的完结篇。©豆瓣', '丹尼尔·雷德克里夫', '大卫·叶茨', 9, 764378, 'tt1201607', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p917846733.jpg', 0.2, 0.6, 8.6, 32.5, 58, '0.229761,-0.130721,-0.589406,0.610983,0.392079,-0.269372,0.578949,-0.058471,-0.247544,-0.213908,0.219994,0.672946,-0.429080,0.183934,0.269834,0.012251,-0.542849,-0.726894,-0.069197,-0.102370,-0.206971,-0.378420,-0.369746,-0.291015,-0.114618,-0.432048,0.434028,0.233585,-0.344288,0.222147,0.349602,0.666522,-0.112984,0.165630,0.228079,0.124021,0.203032,-0.218052,0.079182,0.328179,0.035604,0.063240,-0.242210,0.191174,0.185224,0.346000,0.634233,-0.465705,0.389720,0.112658,0.255454,-0.284313,-0.068867,0.189186,0.293737,-0.057523,0.004081,0.188586,0.124834,-0.090426,-0.067633,0.119169,-0.757735,-0.118733,0.127384,0.243124,-0.511989,0.560666,-0.088069,0.245909,0.309542,-0.197252,-0.088579,0.354396,0.170873,0.092064,-0.078589,-0.140704,-0.363539,-0.049280,0.170652,-0.188090,-0.214365,0.110542,-0.376267,-0.401664,-0.304301,0.244527,-0.161243,-0.253618,0.545099,0.194863,0.148729,0.687298,-0.716085,-0.484680,-0.384628,-0.128530,0.090179,-0.190343,-0.111652,-0.822875,-0.071541,-0.176025,-0.130150,-0.377224,-0.043396,-0.108225,0.493457,-0.401060,0.171144,0.382674,0.100746,0.223652,0.461013,-0.180822,0.236154,-0.175889,-0.128553,0.476698,0.365482,0.395070,0.289916,0.244144,0.287051,-0.032432,-0.418498,0.627294', '26577354', '3318306', '1294917', '27133569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011308', '孤儿怨', '悬疑', '意外流产让满心期待宝宝降生的约翰（Peter Sarsgaard 饰）和凯特（Vera Farmiga 维拉•法米加 饰）深受打击，凯特精神几近崩溃，而他们的婚姻也岌岌可危。为了挽救濒临破败婚姻，这对夫妇前往孤儿院希望收养一个孩子。在这里，他们见到了有些特立独行的小女孩伊斯特（Isabelle Fuhrman 伊莎贝尔•福尔曼 饰）。小女孩所散发出的独特气质吸引了约翰夫妇，最终伊斯特成为他们家庭中的一员。然而，随着伊斯特的到来，各种离奇事件接踵而至。凯特隐约感到，这个长着天使面容的小女孩背后有着不为人知的一面……©豆瓣', '维拉·法米加', '佐米·希尔拉', 8.2, 451253, 'tt1148204', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1592298962.jpg', 0.4, 1.4, 17.1, 50.4, 30.7, '0.021589,-0.011433,-0.658867,0.369250,0.059574,-0.096572,0.914736,0.253622,-0.724032,-0.565301,0.326486,0.809512,-0.313264,0.421463,0.407388,-0.044281,-0.325605,-0.234479,-0.189634,0.051261,-0.091539,-0.310223,-0.353992,-0.278609,-0.162392,-0.603745,0.803504,0.105527,0.027079,0.859063,0.209747,0.598560,-0.141484,0.220816,0.165319,0.104122,0.013889,-0.023251,-0.235111,-0.049825,0.044704,0.247324,0.001963,0.465405,-0.369597,0.282570,0.673528,-0.430989,-0.039517,-0.217124,0.441911,-0.218787,-0.087272,0.308297,0.070587,-0.136799,0.270615,-0.013952,-0.303653,-0.164054,0.218966,0.043696,-0.684362,0.222078,0.334250,0.305390,-0.375682,0.256930,0.020985,-0.077482,0.500165,-0.258404,0.131077,0.425360,0.385610,0.619912,-0.188470,0.156156,-0.543916,-0.391722,0.629811,-0.226000,-0.360424,0.183608,-0.814149,-0.267595,0.014744,-0.320239,-0.461243,0.232126,0.256811,0.201461,-0.015107,0.415191,-0.547909,-0.091288,-0.352509,-0.015927,-0.031023,-0.429755,-0.172551,-0.608417,-0.255418,-0.377026,-0.388049,-0.049247,-0.161465,-0.150656,0.755037,-0.722073,0.400522,0.319804,0.146894,-0.283014,0.574029,0.158377,0.239152,-0.337925,-0.248909,0.612663,-0.123414,-0.150177,-0.171102,0.027079,-0.209083,0.015712,-0.195715,0.454911', '4896894', '25721544', '26724989', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011373', '滑稽人物', '剧情', '事业成功广受欢迎的喜剧演员乔治•西蒙斯（亚当•桑德勒 Adam Sandler 饰）发现自己身患白血病，决定趁有生之年重返单口笑话表演舞台。在一次表演中乔治结识了单口笑话表演爱好者艾拉（塞斯•罗根 Seth Rogen 饰）。穷困潦倒的艾拉一直梦想成为一名职业单口笑话演员，付不起房租的他一直借住朋友电视演员马克（詹森•舒瓦兹曼 Jason Schwartzman 饰）的客厅，同住的还有单口笑话表演爱好者利奥（乔纳•希尔 Jonah Hill 饰）。艾拉被乔治雇佣成为私人助理，说服乔治将患病消息通家人与前未婚妻劳拉（莱斯利•曼恩 Leslie Mann 饰）。乔治的白血病在新型实验药物的作用下得到控制，惊喜的他与艾拉前往旧金山表演，在城北马林县家劳拉家中二人旧情复燃。但劳拉的丈夫克拉克（埃里克•巴纳 Eric Bana 饰）此时突然返家，一切变得尴尬又糟糕……', '亚当·桑德勒', '贾德·阿帕图', 6.5, 6287, 'tt1201167', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p916283875.jpg', 2.4, 11.6, 52.6, 27.5, 6, '0.070656,-0.095741,-0.335510,0.217698,0.048742,-0.487458,0.530079,0.074920,-0.428037,-0.334537,0.113385,0.733926,-0.424169,0.255637,0.327881,0.124018,-0.644853,-0.532351,0.338508,0.019591,0.127793,-0.566406,-0.241848,-0.484929,0.031376,-0.523119,0.316282,-0.307376,-0.088936,0.393678,0.412353,0.371079,0.056453,0.131098,0.049715,0.190478,0.451333,-0.171016,-0.480622,0.195901,-0.211313,0.208296,-0.012921,-0.012210,0.273929,0.171849,0.359213,-0.066493,0.161287,0.087987,0.185165,-0.159603,0.267436,0.110005,0.040172,0.114867,0.347214,-0.123648,-0.175292,-0.057236,-0.066652,0.045814,-0.273401,0.229461,0.125930,0.185796,-0.363587,0.385365,-0.439513,-0.006056,0.055461,-0.095543,0.160721,0.110817,0.314315,0.430264,-0.017101,0.170479,-0.323953,0.099750,0.384279,0.040488,-0.232266,0.196275,-0.241799,-0.414857,0.122178,-0.078320,-0.516424,-0.007678,0.215892,-0.351081,0.305108,0.240963,-0.302901,-0.230196,-0.222934,0.156309,-0.045931,-0.154136,-0.000871,-1.039934,0.095372,0.134961,-0.076453,-0.312542,0.123573,-0.388333,0.433950,-0.484127,0.353308,0.415772,0.225099,-0.109512,0.495504,-0.019134,0.352920,-0.230452,-0.264064,0.302561,0.037741,0.100750,0.029074,0.196245,-0.027103,-0.157335,-0.267584,0.414005', '34961898', '6517421', '2075345', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011380', '完美逃亡', '动作', '好莱坞编剧克里夫·安德森（斯蒂夫·赞恩 Steve Zahn 饰）和希德妮（米拉·乔沃维奇 Milla Jovovich 饰）这对看似新婚燕尔的小夫妻正驱车前往风景迷人的夏威夷度假，他们在当地结识了另一对情侣——极具野性的尼克（蒂摩西·奥利芬特 Timothy Olyphant 饰）和吉娜（凯尔·桑切斯 Kiele Sanchez 饰）。在尼克夫妇的指引下，他们走入原始丛林探险，寻找从未有人涉足的完美之地。但是在此过程中，他们从其他游客那里听说了一对新婚夫妇狂乱杀人的恐怖传闻。美丽的小岛瞬间杀气腾腾，阴云密布，是去是留成为了一个艰难的选择。随着时间的流逝，死神的脚步似乎变得越来越清晰，而被深藏已久的秘密也慢慢浮出水面……©豆瓣', '米拉·乔沃维奇', '大卫·杜西', 6.8, 21626, 'tt0971209', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p901415792.jpg', 1.6, 8, 47, 34.4, 9.1, '0.300010,-0.075959,-0.850726,0.546552,0.086424,-0.247823,0.895802,0.178851,-0.448456,-0.033552,0.167278,0.785257,-0.350572,-0.110457,0.238094,0.145265,-0.540008,-0.495630,-0.015761,-0.250155,-0.016569,-0.538868,-0.438677,-0.115093,0.041267,-0.305186,0.428561,0.111793,-0.027399,0.694023,0.189905,0.303743,-0.360075,0.319385,-0.250891,-0.040903,0.394675,-0.034606,-0.214009,0.239096,-0.000789,0.013671,-0.181624,-0.095717,-0.062366,0.396075,0.506780,-0.419849,0.085608,0.169969,0.137755,-0.201890,-0.022189,0.148105,0.179553,-0.221423,0.067089,0.017340,-0.314673,-0.167776,0.139345,-0.292213,-0.457345,0.247901,-0.070600,0.424096,-0.442329,0.108420,0.098111,-0.343448,0.307830,-0.389717,0.245113,0.268568,0.191758,0.097146,0.052683,-0.043277,-0.350591,-0.000579,0.441097,0.267568,-0.209560,0.276860,-0.447904,-0.402840,-0.089226,0.028819,-0.384175,-0.377588,0.586148,0.098913,-0.091343,0.270105,-0.618711,0.104019,-0.307745,-0.227336,-0.140158,-0.380646,-0.330705,-0.956118,-0.058993,-0.629979,-0.179882,-0.012902,-0.064040,-0.085712,0.575622,-0.682702,0.368002,0.519389,0.187544,-0.045986,0.692947,-0.292793,0.170774,-0.105923,-0.179630,0.458998,0.070091,0.317776,0.102579,0.535831,-0.120238,0.190616,-0.465454,0.589008', '1316693', '1301686', '10466639', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011459', '危情时速', '动作', '宾夕法尼亚州南部的布鲁斯特市，资深的火车机师弗兰克·巴恩斯（丹泽尔·华盛顿 Denzel Washington 饰）即将提前退休，作为拥有丰富阅历和经验的老员工，他和伙伴们虽然对公司出于成本雇用相对便宜却没有经验的新员工不满，却也无可奈何。这天早晨，弗兰克迎来了新的搭档，年轻气盛的领航员威尔·科尔森（克里斯·佩恩 Chris Pine 饰），新老交替正式开始。与此同时，位于北部的富勒站出现状况，满载危险化学品的777号列车在无人驾驶的情况下径自开走，如野兽般咆哮着冲向人口密集的城镇。危险随时降临，弗兰克和威尔即将度过难忘的一天……本片根据2001年美国俄亥俄州的一个真实事件改编。©豆瓣', '丹泽尔·华盛顿', '托尼·斯科特', 7.8, 61685, 'tt0477080', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p645525196.jpg', 0.3, 1.5, 25.4, 55, 17.9, '0.291285,0.164861,-0.770692,0.439264,0.252983,-0.104796,0.710481,0.152762,-0.296937,-0.270099,0.314869,0.639650,-0.027091,0.072424,0.406039,-0.168023,-0.385345,-0.394185,-0.087046,-0.086844,-0.249983,-0.458140,-0.495045,-0.330049,0.117686,-0.331213,0.553161,0.125248,-0.050612,0.642890,0.156375,0.528048,0.062255,0.574219,-0.097722,-0.151556,0.516333,-0.088072,-0.365926,0.141522,-0.222275,-0.047171,-0.063549,-0.234508,0.337590,0.561613,0.408405,-0.189858,-0.261351,-0.016278,0.206797,-0.074378,0.020956,-0.007792,0.478039,0.023956,0.042262,0.089603,-0.018367,0.177485,-0.340142,-0.296657,-0.759250,-0.096441,0.066539,0.154944,-0.443194,0.386928,-0.352909,0.034036,0.070438,-0.428989,-0.031326,0.163690,0.049368,0.478970,0.038031,0.182248,-0.240143,0.014516,0.744893,0.139828,-0.475055,0.194666,-0.285040,-0.400182,-0.233169,-0.249186,-0.403318,-0.049391,0.411980,0.075686,0.006769,0.434598,-0.660579,0.225830,-0.151952,-0.542411,-0.096107,-0.091401,-0.153127,-0.844815,0.286927,-0.383716,-0.138066,0.186716,0.035106,-0.103727,0.714492,-0.619392,0.233704,0.517556,0.228503,-0.214491,0.453915,-0.118254,0.147236,-0.442166,-0.100584,0.385187,-0.043717,0.372250,-0.041854,0.209302,-0.060051,-0.349641,-0.036708,0.546979', '3147969', '2159244', '3178770', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011460', '牙仙', '喜剧', '身形健硕的德里克·汤普森（巨石·强森 Dwayne Johnson 饰）是一个作风粗暴的职业冰球手，由于经常打掉别人的牙齿，因此他在场上得了“牙仙”的绰号。正所谓风云变幻，时代更迭，随着才俊新秀的涌现，德里克也渐渐成为一名过气的板凳选手。狂放自负的他必定心情极度失落，故而经常用冰冷的语言打碎别人的梦想。德里克的女友卡莉（艾什莉·贾德 Ashley Judd 饰）有一双可爱的儿女，小女儿刚好处在换牙期，对神秘的牙仙还充满遐想。此时德里克的老毛病又犯了，一心希望向女孩讲述牙仙并不存在的真相。他的粗暴做法惹来了麻烦，牙仙大陆的负责人莉莉（朱丽·安德鲁斯 Julie Andrews 饰）将他变为一个身长翅膀、手持魔杖、衣着短裙的牙仙女，在接下来的两周里，他将被迫以这身装扮为孩子们带去祝福……©豆瓣', '道恩·强森', '迈克尔·莱拜克', 6.3, 7716, 'tt0808510', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2576872441.jpg', 2.2, 12.9, 57.4, 21.5, 5.9, '0.167874,0.104632,-0.458220,0.560061,-0.456704,-0.151495,0.775209,0.260606,-0.290569,-0.172391,0.351993,0.538302,-0.238704,0.182833,0.331581,0.011350,0.038604,-0.671882,0.094906,-0.107009,-0.243767,-0.073463,-0.290925,-0.024259,-0.176583,-0.415009,0.591077,-0.035584,-0.059406,0.467704,0.291181,0.364378,0.235766,0.367325,-0.163802,-0.180764,-0.012825,-0.175369,0.227574,0.077754,0.033824,-0.070652,0.050645,0.349848,-0.257783,0.385833,0.815386,-0.226827,0.073744,-0.149829,0.339779,-0.110340,0.027774,0.281276,0.323610,-0.035164,0.111657,-0.103503,-0.080041,0.187932,0.300364,-0.250543,-0.560918,0.113996,-0.098045,0.316196,-0.395479,0.555069,-0.360655,-0.152899,0.100964,-0.099334,-0.026080,-0.040907,0.094331,0.458358,-0.111957,0.131266,-0.378519,0.088452,0.189967,0.302786,-0.133737,0.184804,-0.478058,-0.244890,-0.042291,-0.237615,-0.441421,-0.317819,0.471262,-0.101159,-0.167858,0.468759,-0.518354,-0.076092,-0.260510,-0.107898,0.025238,-0.436382,-0.258009,-0.296653,0.036928,-0.466921,-0.090515,-0.094137,0.091319,-0.046727,0.852991,-0.762868,0.021623,0.444155,0.125121,-0.100403,0.417928,-0.020775,0.324783,-0.108807,-0.268902,0.321032,0.199598,0.055246,0.097700,0.614310,0.017908,-0.160459,-0.294184,0.713504', '1307146', '24839498', '3811356', '1292943');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011484', '蠢蛋搞怪秀3D', '喜剧', '约翰尼·诺克斯维尔和斯蒂夫·噢、巴姆、胖子佩斯顿、矮人威曼等人再度集结，制作了全新的3D版蠢蛋搞怪秀。2000至2010，十年时光，记录了他们的青春和友情，这种友情不会因为受各种弹性装置发射的巨掌、棒球、水果的击打而消散；不会因为被故意置入充满蛇的陷阱、在空中翻飞或是爆炸的厕所等险境而倒退；不会因为尿水攻击、喝下对方的汗水、用万能胶拔体毛而反目成仇。他们拥抱彼此，还包括动物，他们用身体承受蝎子、狗、岩羊、驴、牛和蜂群的攻击，他们和新朋友“屁王”一起开怀大笑。不用怀疑，这部纪录片不仅是自毁式恶搞的集合，更是一曲友谊的赞歌。©豆瓣', '约翰尼·诺克斯维尔', '杰夫·特里梅因', 7.8, 7128, 'tt1116184', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p863365845.jpg', 3.1, 4.5, 23.4, 36.5, 32.4, '0.331213,-0.565173,-0.476465,0.496597,-0.167476,-0.094769,0.735860,0.268323,0.023497,0.120127,0.269665,0.428976,-0.499369,-0.053825,-0.094973,-0.347588,-0.071663,-0.658423,0.093358,0.152099,-0.428838,-0.097815,-0.163156,-0.373944,0.025715,-0.322208,0.612576,-0.163121,-0.145880,0.444130,0.221747,0.191668,-0.074999,0.249218,-0.230200,0.119482,-0.306517,-0.165492,-0.104761,0.103700,0.081085,-0.232281,0.252401,0.094369,-0.185489,0.197900,0.708093,-0.223939,0.240277,-0.373368,0.045707,-0.400114,0.235851,0.074182,0.151272,-0.192059,0.427502,0.056541,-0.099824,0.181272,0.230980,0.044020,-0.582629,-0.116035,-0.064064,-0.027989,-0.288895,0.429483,-0.069361,-0.017789,0.094756,-0.170084,0.060564,0.073179,0.544289,0.328459,-0.309504,-0.247872,-0.357408,0.012164,0.364195,-0.306864,-0.352864,0.265717,-0.140635,-0.235574,-0.196407,-0.034504,-0.149899,-0.206584,0.337343,0.294656,-0.096176,0.317590,-0.808602,-0.097565,-0.328371,-0.304508,-0.138026,-0.439193,-0.330292,-0.739510,-0.207083,-0.487151,-0.092975,0.013025,0.295317,0.061650,0.408991,-0.675986,0.093325,0.415290,0.242734,-0.000295,0.310136,-0.163450,-0.292355,-0.145242,0.098267,0.136934,0.112261,0.057613,0.554393,0.369422,0.145207,0.226011,-0.308260,0.498644', '20274039', '1294917', '10467125', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011574', '怒火攻心2：高压电', '动作', '从直升机上坠落的切弗（杰森•斯达森Jason Statham 饰）并没有死，当他醒来的时候，正躺在一家黑诊所，几个蹩脚的香港医生正在做心脏移植手术。期间，小混混强尼万不时在身边干扰。手术后的切弗拥有了一颗Avicor公司的人造心脏以和一块腰带电池。医生告诉切弗，为了保持心脏的活力，他必须不停给身体充电。切弗认定是强尼万偷了他的心脏，所以疯狂追击。在性爱社交俱乐部，他碰巧搭救了妓女瑞亚（白灵 饰），在夜总会，他又见到了跳钢管舞的女友伊芙（艾米•斯玛特Amy Smart 饰）。夜总会的枪战，引来了警察，但是电棍只会给切弗充电。追到跑马场的切弗，为了摩擦充电，在众目睽睽之下出尽洋相。直到香港三合会老大唐金出现，切弗才真正了解心脏被盗的真正原因……©豆瓣', '杰森·斯坦森', '马克·耐沃尔代', 7, 61587, 'tt1121931', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1501108792.jpg', 2.2, 8.2, 40.6, 33.5, 15.5, '0.204839,0.059116,-0.551946,0.146241,0.030220,-0.213492,0.495381,0.328447,0.118958,-0.054217,0.388840,0.452907,-0.388577,0.102309,-0.006120,-0.103218,-0.166835,-0.638748,0.039850,0.023779,-0.647094,-0.178331,0.014266,-0.323548,0.062376,-0.174970,0.261168,-0.203631,-0.284346,0.443398,0.240482,0.337067,0.130015,0.406881,-0.352816,-0.158613,0.064243,-0.032341,0.088072,0.241661,0.444765,-0.608317,0.204927,0.344622,0.254035,0.468242,0.622011,-0.196930,-0.000419,-0.084296,0.174027,0.020575,0.075838,-0.141158,0.263785,-0.164826,0.083752,-0.235348,-0.218195,0.081305,0.360752,0.019627,-0.530676,-0.183612,-0.043840,0.161375,-0.534797,0.173725,-0.235125,0.276080,0.110515,-0.361420,0.501115,0.205947,0.021400,0.250836,-0.381568,0.084594,-0.706028,0.245757,0.428358,-0.102199,-0.122588,0.410886,0.040705,-0.313246,-0.049985,-0.006071,-0.270450,-0.282479,0.458642,-0.265923,-0.193212,-0.134420,-0.407801,-0.154831,-0.204152,-0.366322,0.090898,-0.233993,-0.177168,-0.388111,-0.138700,-0.141229,-0.009925,0.150803,-0.165560,-0.125011,0.340324,-0.738219,0.268264,0.843356,0.166639,-0.250769,0.541795,-0.177495,-0.075150,-0.114377,-0.198898,0.170677,0.384306,0.372076,0.120725,0.345176,0.049679,-0.020467,-0.527678,0.231934', '1947080', '1297347', '1477916', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011581', '丛林大反攻2', '喜剧', '又一个打猎季节到来之际，黑尾鹿艾略特与母鹿吉赛尔的婚礼在即，可艾略特却心生怯意。刚从主人的束缚中重获自由的腊肠先生却在此时被一群嚣张的宠物绑架, 企图要把它绑回重返丛林的女主人身边。艾略特以此为借口与棕熊布哥、松鼠、鸭子等一行人踏上了解救腊肠的冒险之旅，它们又将进行全方位的抢救大行动。而这一次，它们的战友又多了一只刚逃离了猎人控制的驯养德国猎犬维尼。在供人类和其宠物度假的宠物天堂里，除了痛恨野生动物的贵宾狗菲菲，人类的麻醉枪，还有什么危险和挑战在等待着它们呢？它们这一次能否完成大反攻，顺利救出腊肠先生？而艾略特与吉赛尔又是否能如期地步入礼堂完成终身大事呢?©豆瓣', '乔尔·麦克哈尔', 'Matthew O''Callaghan', 6.8, 7814, 'tt1107365', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1910387322.jpg', 1.1, 8, 51.4, 30.1, 9.3, '0.141930,0.078974,-0.634219,0.602716,-0.187655,-0.367529,0.712767,0.042046,-0.227535,0.106586,0.155473,0.763537,-0.075805,0.168255,0.019613,-0.011862,-0.215500,-0.410944,-0.005952,0.070553,-0.344030,-0.115399,-0.428857,-0.246651,0.193441,-0.194695,0.624569,0.100570,-0.169224,0.435358,0.122273,-0.132642,-0.305058,0.407646,-0.303155,-0.189582,0.187349,0.192622,-0.119260,0.475855,0.015451,-0.146166,-0.204828,0.166453,0.026614,0.251853,0.819944,-0.707445,-0.138770,-0.269200,0.091332,-0.396361,0.268352,0.204236,0.071575,-0.273530,0.011898,-0.016615,-0.030357,0.296537,0.044106,-0.278889,-0.898078,-0.064506,-0.395581,0.010666,-0.662924,0.377343,-0.044198,0.228246,0.220038,-0.451160,0.088901,0.546585,-0.003019,0.532243,-0.217257,-0.004358,-0.615172,-0.060694,0.740984,-0.228985,-0.144629,0.209650,-0.046028,-0.636999,0.246867,-0.097650,-0.308513,-0.319100,0.549665,0.256946,-0.535327,0.103698,-0.884531,0.138097,-0.519876,-0.148933,-0.122031,-0.418974,-0.039665,-0.512883,0.397788,-0.124524,-0.054265,0.132312,0.470635,-0.222746,0.568649,-0.915210,0.385879,0.803972,0.347914,-0.367896,0.391281,-0.092604,0.278786,-0.145370,-0.071829,-0.076734,0.199122,0.696952,0.421146,0.412715,0.081428,-0.055113,-0.603890,0.477626', '25774050', '2032339', '3213270', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011606', '狂蟒之灾4', '动作', '一队摄制人员为寻访神秘的希里莎纳部落，正向神秘的亚马逊原始森林迈进。途中他们遇见已在森林里生活多年的“捕蟒专家”，他一直在追捕一条长达40英尺、凶猛而且狡猾的巨蟒。为了借助摄制组的力量，他以带路为借口，把摄制组带进这条巨蟒的领域。就这样，摄制组在毫无准备之下陷入了极度的危险之中……..', '克里斯托·艾伦', '唐·方李洛伊', 4.7, 6050, 'tt1150934', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2518156085.jpg', 21.9, 36.3, 30.8, 6.6, 4.4, '0.209442,-0.059645,-0.863375,0.855377,0.024920,0.097436,0.715413,-0.169772,-0.657799,-0.169025,0.516261,0.631277,0.103663,-0.017745,0.120546,-0.179613,-0.041633,-0.289514,-0.527574,-0.153474,-0.357442,-0.135899,-0.666882,-0.248540,0.050534,-0.462262,0.580145,0.440761,-0.234605,0.310150,-0.050100,0.403956,-0.536685,0.506104,-0.274992,-0.222785,0.191024,-0.214736,-0.131435,0.420522,-0.218288,-0.303275,-0.040420,0.079284,-0.172552,0.232881,0.892196,-0.343270,-0.179249,-0.058203,0.161029,-0.374581,0.052720,-0.112134,0.740188,-0.171826,0.414041,0.073310,-0.387069,0.296561,-0.168918,-0.344963,-0.921694,-0.017379,-0.153856,0.072802,-0.767123,0.152718,0.257492,-0.064862,0.345407,-0.599370,-0.105689,0.242311,0.272024,0.161751,0.045609,0.055178,-0.193614,-0.198691,0.873024,-0.362519,-0.271450,-0.025491,-0.170164,-0.220225,-0.015062,0.016885,-0.359517,-0.451021,0.379493,-0.034006,-0.389027,0.159679,-0.818861,0.323650,-0.402014,-0.324297,-0.176070,-0.295818,-0.309342,-0.583919,0.151009,-0.071920,0.039850,0.349553,-0.038144,-0.066333,0.189294,-0.516571,0.413689,0.781281,0.266130,-0.303241,0.908149,-0.446562,0.142857,-0.097118,-0.117505,0.351338,0.175659,0.522084,0.225619,0.332878,-0.189334,-0.139478,-0.549545,0.280441', '1308784', '34461680', '24879819', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011617', '深空失忆', '动作', '经过数百年的发展，人类文明高度进化，他们逐渐将触角伸向宇宙深处。然而，随着人口激增，有限的资源消耗殆尽。到2174年，地球资源严重匮乏，资源争夺战达到顶峰。为了寻求新的生存乐土，人类向宇宙发射了名为“极乐世界”的宇宙飞船，开始漫长、未知的宇宙探索。经过长时间的深度睡眠，船员鲍尔（本·福斯特 Ben Foster 饰）和佩顿上尉（丹尼斯·奎德 Dennis Quaid 饰）相继醒来。不知出于何种原因，他们完全忘记了航行的目的和任务。鲍尔与佩顿合作检查飞船，很快便发现其他同伴的尸体，这些昔日的伙伴死状恐怖。而且他们似乎不是仅存的生命体，一种神秘的生物仍在威胁着他们的生命……©豆瓣', '丹尼斯·奎德', '克里斯蒂安·阿瓦特', 7.4, 52182, 'tt1188729', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p453467740.jpg', 0.8, 4.5, 34.2, 43.6, 16.9, '0.074215,0.293804,-0.773967,0.388892,0.006472,-0.042523,0.740460,-0.262125,-0.521185,-0.255309,0.180978,0.419873,0.038392,-0.093882,0.133920,-0.239356,-0.196210,-0.202265,-0.209688,-0.052049,-0.703687,-0.620256,-0.678191,-0.351297,0.005588,-0.718663,0.878437,0.236177,-0.204795,0.174812,-0.469915,0.294752,-0.202246,0.418960,-0.048218,-0.116191,0.201230,-0.068383,-0.471145,0.135081,-0.232672,-0.051080,-0.007598,0.016608,-0.172162,0.235893,0.766459,-0.378777,-0.135996,-0.107838,0.416850,-0.346512,-0.014336,-0.228022,0.541156,0.106632,-0.109594,0.151679,0.129703,0.057388,-0.056412,-0.150065,-0.961641,-0.267668,-0.076118,0.097142,-0.079962,0.367481,0.050470,-0.206579,-0.052730,-0.455064,0.136474,0.691016,0.089401,0.352739,-0.305940,-0.080677,-0.550219,0.131080,0.576680,-0.185717,-0.649421,0.385195,-0.226081,-0.721442,-0.485890,-0.483956,-0.193229,-0.282236,0.368930,0.689141,-0.203552,0.629849,-0.905337,0.460910,-0.227547,-0.666685,0.005327,-0.060653,-0.081948,-0.576418,-0.274636,-0.390035,-0.102190,0.100938,0.142871,-0.260033,0.900559,-0.592281,0.239911,0.771812,0.479490,-0.555779,0.572543,-0.484685,0.177153,-0.554033,-0.062816,0.531276,-0.143341,0.574280,0.132892,0.024756,0.048375,0.279157,-0.445319,0.432870', '26667010', '1578502', '1308784', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011906', '秘岸', '剧情', '夏日江城，出租车司机吴涛（曾志伟 饰）驾车意外坠江身亡，留给妻子凡丽（蒋雯丽 饰）的除了腹中的遗腹子以及高中毕业的儿子小川（檀健次 饰）还有个受伤女乘客苏丹（莫文蔚 饰）。凡丽无法负担高额的住院费，只能接苏丹回家亲自照顾。男人的去世，让这个家弥漫着一种哀伤之气，而风尘女子苏丹的入住让这个家焕发出一丝生机。小川从迷茫少年开始变得成熟，而凡丽也渐渐摆脱了丧夫之痛。苏丹腿伤慢慢好转，凡丽为了避免苏丹和儿子的进一步接触想办法把苏丹打发走。一直对父亲的死因有怀疑的小川在两年后找到了苏丹，本来只是给她送赔偿金时却意外发现了一个秘密。本片由导演张一白编剧并执导，是张一白“爱情三部曲”（其他两部《开往春天的地铁》、《夜上海》）中的最后一部。©豆瓣', '莫文蔚', '张一白', 6.3, 11448, 'tt1201637', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p648441636.jpg', 2.8, 14.8, 54.6, 22, 5.8, '0.024820,0.209231,-0.517205,0.405341,-0.124048,-0.458943,0.596227,0.239274,-0.631169,-0.399022,0.005958,0.717606,0.034656,0.206043,0.327932,0.117030,-0.248771,-0.400372,0.006409,-0.036479,-0.165153,-0.453106,-0.063981,-0.006193,-0.092671,-0.390576,0.782021,0.230156,0.098295,0.664454,0.324038,0.026807,-0.006090,0.445163,-0.000533,0.034327,-0.133181,-0.177214,-0.271197,0.312491,0.233787,-0.212536,-0.220677,0.109664,-0.065661,0.609365,0.685597,0.297041,-0.213523,-0.244930,0.375811,0.008611,-0.163696,-0.080927,-0.099626,0.117519,0.258562,0.151854,-0.339365,-0.010926,0.054213,0.178109,-0.429871,0.306186,0.028385,0.146012,-0.564894,0.148844,-0.185445,-0.234831,0.210925,-0.414075,0.410235,0.296083,-0.038555,0.550472,-0.516822,0.299110,-0.356268,0.249679,0.463655,-0.276554,0.017312,0.572952,-0.116528,-0.248105,0.206454,-0.087465,-0.449365,0.251803,0.201053,0.243162,-0.246229,-0.065630,-0.632986,-0.127580,-0.407562,-0.193462,-0.044324,-0.215087,0.105562,-0.398052,-0.245363,-0.036051,-0.074703,-0.064153,0.286385,-0.049496,0.481165,-0.422634,0.286556,0.185214,0.388199,-0.489763,0.332428,0.210875,-0.028845,-0.283901,-0.151344,0.380925,-0.039522,0.250974,-0.037301,0.059571,-0.266682,-0.251439,-0.367548,-0.022813', '2365260', '5364978', '3111650', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3011997', '伊甸湖', '惊悚', '热恋中的珍妮（Kelly Reilly 饰）与史帝夫（Michael Fassbender 饰）来到美丽的湖边，计划度过一个浪漫而温馨的周末。但是他们的周末被一群胡作非为、大声喧哗的少年给搅乱。一番口角冲突过后，夫妇俩的食物以及车钥匙不翼而飞。他们只得徒步前往镇上求助，却不知道，这恰恰是恶梦的开始……本片荣获2009年《帝国》杂志奖最佳恐怖片奖、2009年葡萄牙奇幻国际电影节最佳导演奖、2009年伦敦影评电影金像奖英国年度青年演员奖（Thomas Turgoose）、2008年Sitges – Catalonian国际电影节评审团特别奖最佳影片。©豆瓣', '凯利·蕾莉', '詹姆斯·瓦特金斯', 7.7, 120061, 'tt1020530', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1182863876.jpg', 1.5, 3.2, 25.6, 48.6, 21, '-0.101665,-0.015763,-0.540320,0.580690,0.525844,-0.079015,0.432816,-0.018401,-0.465558,-0.036710,0.128805,0.795783,-0.573033,0.216367,0.599045,-0.018682,-0.526666,-0.757971,-0.098208,-0.178000,-0.019703,0.024363,-0.196882,-0.189731,-0.105201,-0.110715,0.736993,0.192360,0.020671,0.863556,0.696856,-0.089044,-0.070056,0.189389,-0.051111,0.011756,0.462861,0.142778,-0.584704,0.596775,-0.158239,-0.450069,-0.643374,-0.007764,0.345275,0.036172,0.799165,-0.044344,0.036618,0.009549,0.683096,-0.507126,-0.370145,-0.240331,0.430587,0.076256,0.353563,0.094037,-0.025512,0.143788,-0.058340,-0.376198,-0.271544,0.362091,0.061023,0.046751,-0.505187,0.576780,-0.067533,0.249342,-0.241858,-0.043614,0.427086,0.065784,0.455547,0.338917,0.132170,0.058565,-0.422995,0.740077,0.509034,0.030214,-0.115216,0.360884,-0.240489,-0.701638,-0.063478,-0.362523,-0.471489,0.248874,0.333813,-0.258003,0.153827,0.152978,-0.585202,0.153605,0.002789,-0.570212,-0.003704,-0.243057,-0.263766,-0.915049,0.177039,-0.030328,-0.200535,-0.069045,0.103993,-0.011065,0.753372,-0.365601,0.266088,0.620156,0.187353,-0.217557,0.925464,0.035248,0.105992,-0.247229,-0.374614,-0.008387,-0.361425,0.035485,-0.219978,0.198178,-0.142057,-0.375679,-0.328448,0.242575', '1780122', '1302279', '24751811', '30397916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3012009', '殉难者', '剧情', '露西（Mylène Jampanoï 饰）童年时被一神秘组织绑架，在那一年的黑暗岁月里，她饱受折磨。最终她趁守卫不注意逃脱，在孤儿院结识了新的朋友安娜（Morjana Alaoui 饰）。然而露西心灵受到严重创伤，她经常能够看到一个全身赤裸、伤痕累累的恐怖女人对她进行恐吓与追杀。露西就在恐慌与悲痛中度过了童年。15年后，经过一番追查，露西和安娜查到了当年的行凶者之一。露西将对方一家杀害，却仍无法摆脱童年的梦魇，最终在歇斯底里中自杀身亡。悲伤的安娜很快被那个神秘组织抓到，她将如朋友一样，被迫成为传说中的殉道者……©豆瓣', '莫贾娜·埃尔阿劳维', '巴斯卡·劳吉哈', 6.8, 13907, 'tt1029234', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2175244756.jpg', 4.2, 10.1, 40.2, 31.4, 14, '0.296820,0.260799,-0.780057,0.309716,-0.138505,-0.100824,1.216260,-0.197279,-0.645472,-0.249212,0.355327,0.789331,-0.311065,0.555495,0.171776,0.132783,-0.214469,-0.742640,0.034023,-0.182670,-0.460345,-0.348821,-0.440964,0.054067,-0.106962,-0.642474,0.531779,0.092341,-0.195306,0.570959,0.048017,0.489928,-0.298151,0.612867,-0.126858,0.033319,0.369287,-0.113130,-0.152327,0.215638,0.134057,-0.552272,0.049578,0.439270,-0.269596,0.297738,0.826573,-0.503863,0.015805,-0.194274,0.343612,-0.259134,-0.249085,0.332162,0.292723,-0.036345,0.249915,0.261871,-0.343132,-0.065933,0.081640,0.054413,-0.928517,-0.108756,0.293973,0.222059,-0.593663,0.408500,0.038658,0.135310,0.215222,-0.240785,0.139503,0.311485,0.330298,0.511367,-0.344524,0.031200,-0.468508,0.162150,0.884850,-0.293646,-0.249470,0.279691,-0.188196,-0.113609,0.028014,-0.331051,-0.508097,0.061040,0.518005,0.240818,-0.660192,0.439712,-0.555088,-0.135089,-0.407751,-0.084783,-0.245999,-0.439630,-0.373667,-0.506468,-0.397779,-0.325147,-0.311365,0.120722,-0.107422,-0.251294,0.634723,-0.899579,0.509582,0.617484,0.465804,-0.303476,0.406441,0.148564,0.157303,0.063578,0.099714,0.679919,0.319409,0.355547,0.389922,0.312512,-0.258969,0.225569,-0.539873,0.459802', '1428054', '21619567', '25828589', '1292528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3012013', '伸冤人', '动作', '麦考尔（丹泽尔·华盛顿 Denzel Washington 饰）是一名已经退役的黑色行动突击队队员，常年浸淫在充满了暴力和危险的生活中，麦考尔的内心早已经疲惫不堪，为了脱离组织，他大费周章伪造了自己已经死亡的假象，来到了波士顿，改头换面，隐姓埋名，企图能够过上平静安宁的新生活。一次偶然中，麦考尔遇见了被俄国黑帮控制的雏妓泰利（科洛·格蕾斯·莫瑞兹 Chloe Grace Moretz 饰），女孩坎坷的身世和危险的现状博得了麦考尔的同情，他决定帮助这个可怜的女孩。然而，在解救泰利的同时，麦考尔自己也陷入了黑帮强大的火力之中，对警方的昏庸和腐败失望透顶的麦考尔决心挺身而出与体制对抗。©豆瓣', '丹泽尔·华盛顿', '安东尼·福奎阿', 7.8, 96311, 'tt0455944', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2201052935.jpg', 0.3, 2.1, 26.9, 48.7, 21.9, '0.199019,0.140082,-0.745016,0.546931,-0.293465,-0.175531,0.808936,0.189089,-0.569937,-0.127706,0.001690,0.756574,-0.015301,0.226110,0.270849,-0.050755,-0.399011,-0.913126,-0.236295,-0.069333,-0.383510,-0.519256,-0.495064,-0.501887,-0.205060,-0.153976,0.552521,0.357471,-0.400269,0.521153,0.382565,0.620840,0.087486,0.620385,-0.145793,-0.077923,0.399464,-0.306715,-0.367741,0.091107,0.174971,-0.336595,-0.082325,0.375725,0.166943,0.506612,0.766640,-0.332450,-0.153457,-0.015159,0.059026,-0.337834,-0.120737,0.118239,0.121259,-0.095512,-0.177443,0.073198,-0.009769,-0.048916,-0.177011,-0.245515,-1.007281,-0.207395,0.101268,-0.078356,-0.745816,0.421655,-0.240827,0.126470,-0.055511,-0.236692,0.133034,0.327990,0.229598,0.340391,0.009629,0.078611,-0.574397,0.118788,0.756523,-0.069372,-0.541801,0.240505,-0.427406,-0.530555,-0.196332,-0.359653,-0.542761,-0.260840,0.616863,-0.163281,-0.203513,0.534660,-0.542805,-0.060080,-0.564839,-0.101667,-0.401717,-0.275404,0.044227,-0.487322,-0.602986,-0.536818,-0.355585,0.258632,-0.241556,-0.212540,0.641138,-0.976591,0.505723,0.557592,0.363503,-0.293017,0.471938,0.132750,0.378646,-0.258161,-0.131437,0.595435,-0.133437,0.356675,0.365660,0.269948,-0.038554,-0.306689,-0.364976,0.507368', '1301022', '1793491', '3006892', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3012032', '名扬四海', '剧情', '根据1980年艾伦-帕克导演的经典歌舞片《名扬四海》改编。在纽约表演艺术高中，年轻人的任何梦想都将可能被实现。无论是舞蹈、歌唱、表演或是拥有其他艺术才华的学生们都将可能在这里得到实现自己艺术梦想的宝贵机会。在舞蹈、歌唱、表演等着有天分并期待着能在艺术方面有所建树的几个年轻人，马可（阿什·布克 Asher Book 饰）、罗茜、尼尔、凯文、丹尼斯（娜图里·劳顿 Naturi Naughton 饰）以及珍妮（凯·帕娜贝克 Kay Panabaker 饰）等，心怀希望来到了这里。 然而，在孩子们入学之初便遭遇了及其严格的考核：来自自己内心不坚定的意志的折磨，使得他们原有的激情都面临考验。另外，青春校园中从来就不缺乏的青春躁动、同学友谊、爱情的萌芽、以及种种对于成功失败的处理方式，都让前来参加入学应试并最终在这所学校里走到一起的孩子们茁壮成长……©豆瓣', '凯·帕娜贝克', '凯文·坦查隆', 7.6, 32115, 'tt1016075', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p867986377.jpg', 0.5, 3.5, 32.3, 45.1, 18.6, '0.235070,-0.038381,-0.802093,0.536626,-0.023473,-0.131679,0.421904,-0.107679,-0.457366,-0.349766,0.102014,0.562201,-0.010966,0.548094,0.293461,-0.327345,-0.508620,-0.821971,-0.034996,-0.120461,-0.261339,-0.537834,0.013446,-0.031209,-0.257711,-0.500636,0.713049,0.027055,-0.148606,0.659219,0.152944,0.037999,0.074321,0.237561,-0.055409,-0.126255,0.311865,0.006399,-0.314204,0.093180,0.189860,-0.007604,-0.276693,0.098230,0.139813,0.086150,0.654148,-0.390627,0.023226,0.256972,0.391583,-0.212448,0.141923,0.382354,0.053648,-0.013541,0.013684,0.520391,-0.001210,0.297513,-0.049995,-0.249413,-0.952826,-0.117426,0.159861,0.239044,-0.594591,0.524306,0.228812,-0.205915,0.069277,-0.085666,-0.007470,0.283433,0.441643,0.426127,-0.190662,0.026495,-0.317107,0.289105,0.713021,-0.120224,-0.359000,0.232284,-0.486852,-0.457181,-0.085855,-0.249064,-0.473884,0.002621,0.097570,0.378956,-0.031936,0.068072,-0.566367,0.203748,0.055000,-0.276527,0.018811,-0.464638,0.045078,-0.926461,0.031439,-0.364491,-0.413333,-0.019419,0.277974,-0.464197,1.255569,-0.972492,0.245892,0.544088,0.340905,-0.517908,0.631374,0.089351,0.161479,-0.032906,-0.421140,0.442218,-0.144444,0.194129,-0.207200,0.466868,0.117339,-0.150688,-0.295970,0.737846', '27602116', '3811356', 