INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3012033', '爱宠', '恐怖', '《峰回路转》卡里斯陶伦斯执导，《魔戒三部曲》多明尼克莫纳罕、《黑天鹅》柯赛妮亚索罗主演。BDSM结合笼女监禁题材，惊狂混血出击，让我养你一辈子！超有爱心的赛斯在动物之家工作，他每天细心呵护小动物，对于只有基本工资的日子也甘之如饴。某天她在公车上巧遇学生时期的暗恋对象荷莉，她清新亮丽的气质让赛斯内心中沉寂多年的欲望再次被唤醒。赛斯企图要拉近与荷莉之间的距离，可是郎有情妹无意。没想到两人久别重逢的首次见面，荷莉竟然失去意识，清醒后她发现自己衣不蔽体，还被关在动物之家地下室的铁笼之中！爱到失去理智的赛斯口口声声表示会这么做，一切都是因为深爱着荷莉。然而，被受困笼中的荷莉也不是省油的灯，各怀鬼胎的两人随即展开惊悚离奇的对峙……经典的猫捉老鼠游戏，刻画出尔虞我诈的主从之战。究竟谁是主人、谁是宠物，不到最后谁也不知道！', '多米尼克·莫纳汉', '卡莱斯·托伦斯', 6, 6393, 'tt1183374', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2393778761.jpg', 3.6, 19.1, 56, 16.6, 4.7, '0.125709,-0.010371,-0.763855,0.411551,-0.074623,-0.293360,0.806608,-0.082571,-0.385793,-0.198702,0.045462,0.342619,-0.379922,0.116921,0.062983,0.191971,-0.097922,-0.656304,-0.134520,-0.045646,-0.031534,-0.253598,-0.151781,-0.123201,-0.148673,-0.327663,0.399842,-0.065438,-0.151542,0.092289,0.417823,0.224455,-0.186122,0.385306,0.077283,-0.077191,0.180060,0.012153,-0.153700,0.017873,0.101250,0.047639,-0.112123,0.179363,-0.063907,0.164916,0.500807,-0.321713,-0.092464,-0.066135,0.249320,-0.141911,-0.036780,0.077159,0.267539,-0.237274,0.263592,-0.025663,-0.013883,-0.052384,0.133249,0.052148,-0.467841,0.130823,0.023779,0.163983,-0.287653,0.262372,-0.057086,-0.017370,0.147614,-0.214372,0.074685,0.159820,0.659280,0.336441,-0.090562,-0.046293,-0.471911,-0.201664,0.731945,-0.027227,-0.288404,0.405763,-0.226132,-0.580560,0.100929,-0.293764,-0.516662,0.042143,0.127909,0.106301,-0.226272,0.567189,-0.581049,-0.084928,-0.289487,0.100522,0.019242,-0.589899,-0.079279,-0.195160,-0.174764,-0.460594,-0.395477,0.046030,0.172261,-0.544273,0.464807,-0.898433,0.404069,0.678606,0.091042,-0.191363,0.630884,0.147261,-0.138234,-0.048959,0.044263,0.353038,0.249815,0.065849,0.280579,0.204705,-0.030374,-0.008466,-0.351822,0.488674', '1308755', '1292211', '4275444', '129637