INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3012053', '终极斗士3：赎罪', '剧情', '犯人战士尤里•伯伊卡（Scott Adkins 饰）在上一集中膝盖受重伤，失去了搏击能力，只能在监狱中清理卫生，昔日的荣耀和战斗已离他远去，而监狱方面又驳回了他的假释要求，从不曾甘心失去自由的伯伊卡，将希望寄托在国际犯人格斗大赛上，因为大赛最终的冠军将获得自由。经过严酷的恢复性训练，伯伊卡战胜并取代了嘎卡（Mark Ivanir 饰）手下的参赛选手，两人再一次合作，前往格鲁吉亚境内的葛贡监狱，伯伊卡在那里将同世界各地的其他七名犯人战士，角逐出唯一的犯人格斗之王。参赛选手中，美国的特伯（Michael Shannon Jenkins 饰）和哥伦比亚的“杀人狂”各具实力，伯伊卡为了自由必须战胜他们，然而他很快发现，真正的敌人并不是搏击场中的对手……©豆瓣', 'Scott Adkins', '艾萨克·佛罗伦汀', 7.9, 19293, 'tt1156466', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1418305969.jpg', 0.4, 2.4, 25.4, 46.7, 25.2, '0.248796,0.026091,-0.578760,0.703484,0.101820,-0.314437,0.662401,-0.050317,-0.319752,-0.253730,0.151210,0.932747,0.065357,0.170413,0.237284,-0.463912,-0.157961,-0.826636,-0.310716,-0.181065,-0.547697,-0.660595,-0.187848,-0.131219,-0.136869,-0.504456,0.884298,0.163594,-0.353606,0.542554,0.388060,0.092049,0.016201,0.393772,0.054890,-0.388175,0.149592,-0.166633,-0.301939,0.290504,-0.014203,-0.164611,0.034801,0.198749,0.471725,0.114969,0.687020,-0.578570,0.286569,-0.084147,0.072993,-0.323015,0.152872,0.035888,0.232528,-0.210674,-0.022071,0.311389,0.087965,0.074358,0.063827,-0.181680,-0.938504,-0.204055,0.153697,-0.070567,-0.549058,0.773008,-0.071375,0.207928,-0.065788,0.060425,0.136694,0.443340,0.166419,0.153855,-0.156228,-0.202476,-0.475644,0.247702,0.621528,-0.189605,-0.356089,-0.145195,-0.101036,-0.815303,-0.175712,-0.895762,0.031816,-0.093423,0.456258,0.380378,-0.136294,0.001525,-0.235998,-0.079945,-0.231799,-0.432102,-0.123061,-0.320424,0.209789,-0.803449,0.167705,-0.227698,-0.412427,0.093890,0.071978,-0.540190,0.593348,-1.138234,0.127883,0.638174,0.421034,-0.246826,0.467472,-0.100774,0.448987,0.028605,-0.183204,0.260244,0.561677,0.633257,0.403927,0.306226,-0.304933,-0.028290,-0.292102,0.701072', '1420088', '1793491', '1652618', '1986338');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3012257', '独家试爱', '喜剧', '本片与同为叶念琛执导的《十分爱》及《我的最爱》合称为“爱情三部曲”，这是三部曲中的第一部。林嘉华（方力申 饰）和邝美宝（邓丽欣 饰）决定结婚的时候，都各有自己的忧郁与不安。幸好婚后生活还算美满，大家都互相迁就。不久开宠物店的嘉华在办宠物丧礼时重遇中学补习老师Josephine（吴佩慈 饰），嘉华对她余情未了，二人常常短信交流。美宝开始对嘉华产生猜疑，更偷看他的手机。美宝想与嘉华出外旅游，希望能改善二人日渐恶劣的关系，但嘉华不同意美宝的挥霍，美宝盛怒并提出离婚。嘉华喝得耵聍大醉来到了Josephine的家中，两人发生了关系。嘉华觉得自己对不起美宝，便同意了美宝的离婚要求，美宝伤心欲绝。离婚后，美宝遇见了Philip，一个被旧报纸打碎做成了新纸的男人，两人渐渐走近。分开后的他们各自过着自己的生活，相遇的时刻发现对方还在彼此心里……到底谁才是谁的独家爱人？', '方力申', '叶念琛', 7.2, 36939, 'tt0781359', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486588678.jpg', 0.9, 4.8, 42.1, 40, 12.3, '0.349486,-0.209790,-0.825376,0.272940,0.066491,-0.403135,0.446728,0.255671,-0.358108,-0.047769,0.182226,0.729660,-0.270377,0.290215,0.113392,0.057145,-0.279676,-0.744636,0.398275,-0.040597,-0.018483,-0.480535,-0.112405,0.113935,-0.008456,-0.033048,0.387534,-0.140144,-0.075727,0.574576,0.248508,-0.133618,0.112893,0.389468,-0.143601,0.239837,-0.065238,0.379529,-0.736087,0.050145,0.194826,0.012425,-0.357550,0.032547,0.089671,0.233791,0.409064,-0.036676,-0.299841,-0.005152,0.230814,-0.073609,-0.234971,0.194906,0.131334,0.165210,0.355665,0.628456,-0.417278,0.133582,-0.092106,0.422675,-0.625863,0.346587,0.035632,0.214867,-0.370805,0.593137,-0.157832,-0.208025,0.214708,-0.448128,0.191961,0.490076,0.138562,0.412298,-0.334953,0.019924,-0.433200,0.092704,0.637396,0.003579,0.043853,0.554291,-0.205503,-0.163189,0.071266,0.111712,-0.443593,0.049076,-0.053485,0.174786,-0.225694,0.189207,-0.750382,-0.040612,0.014344,0.072315,0.197444,-0.474598,-0.000438,-0.563411,-0.422302,-0.547489,-0.440278,-0.115942,0.119567,-0.453407,0.463497,-0.918954,0.056590,0.132871,0.582969,-0.588550,0.608446,0.644276,0.030794,-0.195035,-0.009602,0.018291,-0.188492,0.104720,0.079805,0.203176,0.172161,-0.005632,-0.299790,0.249743', '1306133', '10876425', '1418613',