INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30122633', '快把我哥带走', '喜剧', '拥有一个每天耍贱整蛊妹妹、毫无家庭感的哥哥是一种什么感受？油炸还是蒸锅？时秒只希望哥哥时分彻底消失！连珍贵的生日愿望都是“快把我哥带走”。不料愿望成真，哥哥变成闺蜜妙妙的哥哥，时秒同情妙妙的同时心里暗爽摆脱“大魔王”！变成独生女的时秒感觉生活无限美好，但却发现时分除了整天和好基友甄开心、万岁插科打诨、整蛊妹妹妙妙之外，还隐藏着不为人知的秘密……', '张子枫', '郑芬芬', 6.8, 375220, 'tt8774260', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2531080870.jpg', 2, 10.5, 44.7, 32.1, 10.7, '-0.313888,-0.001655,-0.382569,0.468714,-0.169952,-0.097789,0.426621,-0.145427,-0.388187,-0.413181,-0.300209,0.215729,-0.642762,0.521425,0.032010,0.304331,0.019580,-0.485794,-0.077487,0.045324,-0.104947,-0.350329,-0.398096,-0.009682,0.041331,-0.374332,0.398421,0.159543,0.094111,0.075759,0.245080,-0.056699,-0.100618,0.760406,-0.074580,-0.140901,-0.158060,-0.197252,-0.030403,0.107981,0.145682,0.290151,0.277944,-0.019398,-0.062325,-0.132202,0.577463,-0.371679,-0.484078,-0.150902,0.538459,-0.052084,-0.290819,-0.124071,-0.211993,-0.225503,0.442424,-0.306063,-0.141127,-0.170473,0.331621,-0.140687,-0.598001,0.228172,0.321145,-0.393060,-0.207622,0.220507,-0.118001,0.202319,0.484542,-0.408673,0.524229,0.192209,0.288485,0.705096,-0.594975,0.148266,-0.616204,-0.095166,0.752942,-0.492901,-0.294931,0.332599,0.141472,-0.031814,0.073549,-0.137630,-0.091780,0.264480,-0.363491,0.446116,-0.217245,0.322999,-0.313164,-0.012739,-0.083430,0.119497,0.415520,-0.822036,-0.255440,0.131364,0.020213,-0.152382,-0.271072,0.156601,0.148161,-0.600783,0.830090,-0.683225,0.644214,0.184166,0.116989,-0.220341,0.852336,0.062216,-0.289955,-0.032281,-0.038922,0.121870,-0.028586,-0.292355,0.412027,0.223856,-0.332592,0.062444,-0.110783,0.434959', '2081098', '26790961', '2052978', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3012819', '胡桃夹子：魔境冒险', '动作', '九岁的小女孩玛丽（艾丽·范宁 Elle Fanning 饰）拥有锦衣玉食的生活，却缺乏父母的陪伴。圣诞节前夜，玛丽收到了叔叔送来的一份珍贵礼物——一个装木偶的小房子和一只胡桃夹子。喜出望外的玛丽将胡桃夹子视作自己的知心伙伴，竟意外地发现它会说话，并声称自己名叫NC（查理·罗 Charlie Rowe 饰），是玩具王国的王子，然而在一场噩梦中，美好的王国被凶残的鼠王（约翰·特托罗 John Turturro 饰）占领了，他还将王子变成一只木偶永远驱逐出境，只有找到真正相信童话的人才能解除咒语。在雪仙子（朱莉娅·维斯托斯卡亚 Yuliya Vysotskaya 饰）的指引下，玛丽帮NC恢复了肉身，并勇敢地答应与他一起回王国打败鼠王，解放子民。然而，这两个毫无武力只有一颗纯真之心的孩子，能否对抗整支血腥残暴的老鼠大军和卑鄙狡猾的鼠王呢？片中歌曲多数改编自柴可夫斯基的交响乐，其中一部分来自芭蕾舞剧《胡桃夹子》。', '艾丽·范宁', '安德烈·康查洛夫斯基', 6.5, 17249, 'tt1041804', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p663092770.jpg', 2.5, 13.3, 49.1, 24.9, 10.1, '0.157790,0.362245,-0.353318,0.647457,-0.162292,-0.026196,0.768522,0.005925,-0.249991,-0.249853,0.176608,0.613829,-0.012587,0.033540,0.124927,0.084495,-0.181201,-0.492052,-0.180432,0.174635,-0.102980,-0.224930,-0.335567,-0.176024,-0.065538,-0.330877,0.639908,0.015625,-0.063487,0.466717,0.276106,0.216888,-0.076131,0.246728,-0.169059,0.146421,-0.025709,-0.004588,-0.119800,0.169592,-0.101333,0.175167,0.033400,0.223605,0.177513,0.056411,0.763233,-0.847688,0.076504,-0.279540,0.267640,-0.297607,0.104399,0.134645,0.075061,-0.068286,0.259542,-0.138791,-0.127489,0.101904,0.325483,-0.274797,-0.711841,-0.105342,0.083946,0.113142,-0.625704,0.271816,-0.126864,0.244233,0.277337,-0.344973,0.176930,0.263939,0.172243,0.572484,0.057136,0.080886,-0.610185,0.108502,0.432733,-0.255317,-0.439830,0.097933,-0.223526,-0.703751,-0.134604,-0.219200,-0.400698,-0.009498,0.466303,-0.046936,-0.158766,0.250204,-0.890000,-0.278912,-0.510408,0.032656,0.276161,-0.694858,-0.151283,-0.299660,0.214370,-0.252937,-0.148663,0.143299,0.277651,-0.272031,0.759505,-0.681383,0.407016,0.346555,0.238092,-0.023907,0.323124,-0.005538,-0.076310,-0.225266,-0.079814,0.576537,0.352458,0.061642,0.369461,0.292653,-0.016262,0.016779,-0.48