INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30128916', '夺冠', '剧情', '2008年8月15日，北京奥运会女排比赛，中国VS美国。戴着金丝框眼镜的郎平（巩俐 饰）坐在美国队教练席上，大气沉稳，目光如电；中国队教练（黄渤 饰）站在场边，全神贯注，面带笑容。中国队教练望向郎平，目光充满深意，不断经过的人影遮蔽了他的视线，中国女排三十余年的沉浮图景被缓缓打开……', '巩俐', '陈可辛', 7.1, 411696, 'tt10670442', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2620083313.jpg', 1.1, 6.6, 40.6, 39.3, 12.4, '-0.574372,0.073891,-0.177010,0.415594,0.093330,-0.298746,0.392932,0.189097,-0.382492,0.350510,0.384972,0.454555,-0.699106,0.256593,0.269017,-0.498484,-0.545253,-1.166350,-0.554149,-0.002651,-0.300871,-0.321530,0.208938,0.267691,0.262116,-0.060396,0.753544,-0.198981,0.227631,0.945981,0.131626,0.163250,0.351079,-0.020954,-0.048004,-0.379451,-0.284172,-0.354162,0.144510,0.381530,-0.038848,-0.484443,-0.982496,0.025015,-0.042097,-0.267795,1.071214,0.163970,0.359310,0.242388,0.317943,-0.020077,0.118359,0.424547,-0.072551,0.280563,-0.228159,0.067324,0.220238,-0.220866,-0.264057,-0.290884,0.442551,0.288829,-0.549533,0.880004,-0.244435,0.918568,-0.164700,0.058367,0.171781,-0.501139,-0.092383,-0.353605,0.223262,0.238235,-0.216359,0.165336,0.010932,0.118298,-0.535368,0.479012,-0.137111,0.082720,-0.045724,-0.435817,-0.079907,0.366346,-0.283437,-0.245279,0.874314,0.109603,0.776100,0.105592,-0.280710,0.368745,0.501000,-0.539860,0.032216,-0.283014,-0.361921,-0.761746,-0.244316,-0.777019,-0.085541,0.479475,-0.504723,0.421500,0.240219,-0.200158,0.098036,0.312132,-0.322933,0.819939,0.895191,-0.618924,-0.136590,-0.074725,-0.482291,0.100958,-0.121633,0.397690,-0.285189,0.692671,-0.448769,0.238451,-0.144981,0.007550', '4202326', '26365262', '1432699', '3078390');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30128985', '勇敢者游戏2：再战巅峰', '喜剧', '四名勇敢者再次穿越回到险象环生的游戏世界中，开启全新冒险。与上次不同的是，变身勇石博士 (道恩·强森 饰) 的是斯潘瑟的外公，外公的好友则变身为语言学家 (凯文· 哈特 饰)，高大威猛的弗里奇变成了中年发福地质学家 (杰克·布莱克 饰)，只有学霸玛莎依旧化身性感打女 (凯伦·吉兰 饰)，斯潘瑟和贝瑟尼却不知所踪。为营救消失的伙伴，四人必须进入全面失控的未知世界，面对难度爆表危险重重的致命关卡，强森领队挑战极限玩命闯关。山崩石裂的险境中命悬一线，与突如其来的凶猛野兽死战到底，他们唯有绷紧神经并肩作战，才能通过生死考验逃出生天。一场惊险刺激又充满惊喜的冒险之旅即将展开！', '道恩·强森', '杰克·卡斯丹', 5.9, 107607, 'tt7975244', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2575911093.jpg', 3.2, 20.8, 58.6, 14.8, 2.6, '0.050074,-0.067870,-0.447319,0.347209,0.018642,-0.282689,0.639134,-0.134997,-0.271627,-0.159193,0.557392,0.660631,-0.343083,-0.060425,0.321695,-0.225657,-0.030346,-0.441627,-0.190383,-0.038770,-0.240066,-0.427972,-0.549893,0.070888,0.071788,-0.448037,0.724762,0.001272,-0.290384,0.458015,0.286553,0.536029,-0.282113,0.279679,0.078133,-0.108783,0.096480,-0.030346,-0.515795,0.072430,-0.008203,0.223187,-0.026141,0.129029,-0.033611,0.177197,0.472622,-0.531831,-0.103837,-0.110188,0.419599,-0.217300,-0.253417,0.127084,0.219835,0.058461,-0.078443,-0.042194,0.156777,0.092421,-0.130174,-0.102962,-0.620391,0.214413,0.301883,0.103719,-0.309301,0.030860,-0.016440,-0.023021,0.276582,-0.126766,-0.152821,0.348076,0.499516,0.470784,-0.065084,0.151592,-0.039244,-0.132214,0.711892,0.010234,-0.458432,-0.133991,-0.044839,-0.388227,-0.013849,-0.323865,-0.324853,0.073366,0.208689,0.235871,0.051254,0.403448,-0.577895,0.020568,-0.534336,-0.034698,-0.393091,-0.103470,-0.337784,-0.717196,0.051803,-0.045382,-0.135213,0.352209,-0.040501,-0.275123,0.445665,-0.652549,0.156021,0.260615,0.327591,-0.097652,0.397897,-0.101550,0.154252,-0.564736,0.043635,0.635710,-0.081461,0.177506,0.019433,0.179652,-0.214544,0.072670,-0.448650,0.428435', '7051375', '25828589', '2369613', '1482099');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30129061', '我想结束这一切', '剧情', '剧本改编自伊恩·里德同名小说，小说审视了心灵的脆弱和孤独的极限。杰克原本带女友回家见父母，女友一路却在想着“结束这一切”，在杰克改变原定路线后，一切都朝着失控方向发展。', '杰西·普莱蒙', '查理·考夫曼', 7.3, 22713, 'tt7939766', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2619279677.jpg', 2.8, 7, 31.1, 39.9, 19.3, '0.018977,-0.099100,-0.700448,0.449956,0.168009,-0.402625,0.834089,0.148453,-0.233229,-0.347836,0.048832,0.621313,-0.336937,-0.104524,0.362309,-0.126628,-0.934101,-0.591660,-0.138379,-0.076930,-0.156661,-0.412939,0.067184,-0.117216,0.205468,-0.338238,0.781632,-0.026741,-0.174153,0.514411,0.088713,-0.009530,-0.477796,0.288774,0.191323,0.354200,-0.120411,-0.092048,-0.581022,0.246866,0.621921,0.081012,-0.229999,0.198390,-0.116257,0.149467,0.991658,-0.015360,-0.321660,0.214078,0.450391,0.067891,-0.021845,0.223576,0.062536,0.111568,-0.021284,-0.182019,0.158690,-0.010238,-0.331096,0.011788,-0.676734,0.126210,-0.229208,0.292195,-0.526912,0.169106,-0.062032,0.105758,0.324345,-1.011032,-0.036476,0.148992,0.477632,0.522404,-0.265435,0.209368,-0.072769,0.158870,0.487523,0.305077,-0.273661,0.682078,-0.042631,0.060888,-0.372705,0.445425,-0.655238,0.131755,0.343228,0.465309,-0.305352,0.411221,-0.113227,0.133783,-0.103614,-0.492417,0.029565,-0.900704,-0.334494,-0.844657,-0.051057,-0.218743,0.278669,-0.295169,-0.146026,-0.282902,0.494909,-0.340094,0.332237,0.641627,0.217611,-0.816152,0.517184,-0.118342,-0.081307,-0.333741,0.389349,0.746205,-0.362371,0.750774,0.239407,0.176034,0.110550,0.383469,-0.651449,1.020788', '1302022', '2334814', '1296757', '1295253');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3013046', '法国贩毒网', '动作', '腰缠万贯的法国富豪阿兰（费尔南多·雷依 Fernando Rey 饰）手上运作着全球最大的海洛因走私网，警方多番追踪仍无法将其落网，卧底警察也被残忍杀害。而在另一头的纽约城，侦探道尔（吉恩·哈克曼 Gene Hackman 饰）和鲁索（罗伊·施奈德 Roy Scheider 饰）还在酒吧中与当地贩毒分子交锋，浑然不知阿兰正在计划将一笔3200万美元的海洛因走私入美国。然而没过多久，在一次跟踪行动中，道尔和鲁索很快发现了可疑人物与贩毒网之间的关系，一场与贩毒团伙斗智斗勇的险恶持久战就此拉开。道尔和鲁索这对互相看不顺眼的搭档，究竟能想出多少计谋，躲过多少暗箭，最后又能否一举破获这起来自法国的大规模贩毒案呢？本片根据罗宾·摩尔（Robin Moore）的真人真事作品改编，并获得第44届奥斯卡金像奖最佳电影、最佳导演、最佳男主角、最佳改编剧本、最佳剪辑奖。', '吉恩·哈克曼', '威廉·弗莱德金', 7.7, 10292, 'tt0067116', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1435506144.jpg', 0.5, 2.3, 25.9, 52.3, 19, '0.151438,-0.088067,-0.536167,0.560191,0.203887,-0.435208,0.570366,-0.219696,-0.471859,0.019842,0.012019,0.628665,-0.375958,-0.301256,0.213919,-0.182476,-0.543528,-0.890696,-0.232370,-0.276704,-0.059293,-0.605769,-0.824698,0.052807,-0.028687,-0.083876,0.568574,0.064724,-0.183216,0.324518,0.651025,0.328037,-0.345620,0.196104,0.022328,0.047321,0.410165,-0.176628,-0.600949,0.526624,0.136686,-0.529021,-0.172859,0.068898,0.100894,0.318010,0.657129,-0.366320,0.088684,0.076410,0.346437,-0.251113,-0.038830,-0.016073,0.417687,0.020571,0.368522,0.290578,-0.266539,0.241887,-0.049741,0.016483,-0.883746,-0.043347,0.079075,0.172239,-0.508595,0.082166,-0.319404,0.126046,-0.066419,-0.128161,0.157722,0.676368,0.590653,0.048357,-0.213212,-0.083645,-0.473710,0.241276,0.288812,0.094523,-0.104660,0.085581,0.132963,-0.633904,-0.034744,-0.302574,-0.061175,-0.081161,0.773593,-0.003712,0.027718,0.211083,-0.689122,0.065918,-0.350933,-0.200965,-0.109266,-0.271935,0.156880,-1.042813,-0.294104,-0.318675,-0.104331,0.023607,0.217072,-0.307966,0.416111,-0.640539,0.035451,0.733145,0.175937,-0.059962,0.256423,0.320936,0.154502,-0.203038,-0.463152,0.023459,0.291734,0.476529,0.184749,0.309044,0.199178,-0.571160,-0.202551,0.241723', '4014397', '25723905'