INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30135110', '五尺天涯', '剧情', '女孩斯黛拉（海莉·露·理查森 Haley Lu Richardson 饰）在医院结识了男孩威尔（科尔·斯普罗斯 Cole Sprouse 饰），但因为“囊性纤维化”疾病，他们之间的相处必须永远相隔“六英尺”，即使触不可及也不能阻挡两人逐渐升温的情愫。他们的爱情能够战胜疾病和死亡吗？', '海莉·露·理查森', '贾斯汀·贝尔杜尼', 7.2, 57666, 'tt6472976', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2538545442.jpg', 0.6, 5.6, 41.7, 39.4, 12.7, '0.386857,-0.371710,-0.497785,0.393075,0.040465,-0.215528,0.851355,0.537379,-0.132207,-0.118321,-0.053208,0.614938,-0.321195,-0.176639,-0.138729,-0.229893,-0.080403,-0.673148,0.234258,-0.110925,-0.346713,-0.375403,-0.257098,-0.446207,-0.246739,-0.382275,0.861296,0.193438,-0.121249,0.334401,-0.126718,0.301646,-0.153327,0.268732,0.144810,-0.450766,0.034114,-0.184139,-0.593256,0.265508,0.245779,0.077707,0.231970,0.164307,-0.268456,0.521155,0.456658,-0.414300,0.157008,0.071639,-0.164366,-0.033735,0.178031,0.121407,0.085575,-0.550943,0.443308,0.494852,-0.172523,-0.260333,0.226359,0.269454,-0.347461,0.205239,0.255584,0.431504,-0.043796,0.431930,-0.048303,-0.259306,0.113397,-0.189580,-0.089702,0.668359,0.231929,-0.079073,-0.433251,-0.488491,-0.627197,-0.385243,0.534483,-0.023915,-0.687255,0.351278,-0.654427,-0.487420,-0.559209,-0.350641,-0.601960,0.111955,0.134787,0.492771,-0.391116,0.734669,-0.372548,-0.164950,-0.384511,0.111378,-0.092102,-0.340527,0.467662,-0.597443,-0.252177,-0.515515,-0.779958,0.288241,0.165147,-0.342347,0.369863,-0.721485,0.232552,0.423732,0.420767,-0.275775,0.760378,0.267018,-0.011120,-0.202581,-0.151748,0.927126,-0.332813,0.019969,0.290771,0.445748,-0.133224,0.394415,-0.262783,0.584663', '1472510', '2131640', '1305666', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30135113', '骡子', '剧情', '厄尔（克林特·伊斯特伍德 Clint Eastwood 饰）是一名独居的八旬老人，正在面临非常严峻的财务危机，他唯一的住所即将被拍卖用来抵扣债务，在这个节骨眼上，厄尔得到了一份司机的工作，但厄尔所要运送的却并非什么乘客，而是毒品。就这样，厄尔成为了墨西哥贩毒集团中的一员。不得不承认，厄尔将这份工作完成的非常出色，出色到贩毒集团专门为他配备了对接人员。可就在厄尔的财务问题得到解决的同时，他的反常举动也遭到了美国缉毒局特工科林（布莱德利·库珀 Bradley Cooper 饰）的注意。如果继续在法律的边缘试探，厄尔就有可能锒铛入狱，但如果就此金盆洗手，知道太多秘密的厄尔亦有可能被毒枭灭口。©豆瓣', '克林特·伊斯特伍德', '克林特·伊斯特伍德', 7.9, 132450, 'tt7959026', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2563626309.jpg', 0.1, 1.3, 21.4, 57, 20.2, '0.340603,-0.027287,-0.595785,0.345936,-0.395083,-0.276712,0.608701,0.045629,-0.651818,-0.184113,0.254543,0.867173,0.303587,-0.182741,0.325168,0.188558,-0.277355,-0.370777,0.128180,-0.249390,-0.234404,-0.813213,-0.374801,-0.227915,0.014609,-0.253407,0.681636,0.128817,-0.124017,0.071690,0.190394,0.337019,0.369304,0.607782,-0.153553,-0.132890,0.168391,-0.312465,0.015946,0.221827,0.119504,-0.109808,-0.081524,0.326792,0.213700,0.463707,0.145787,-0.150584,-0.283593,0.027081,0.267746,-0.411809,0.284477,0.244243,0.401512,-0.028781,0.034904,0.422415,-0.461394,0.007433,0.132982,0.069650,-1.158244,0.096456,0.194751,0.306823,-0.484034,0.243730,-0.323373,-0.136267,-0.240996,-0.218776,0.095617,0.655501,0.506481,0.050605,-0.289026,-0.153050,-0.649361,-0.016420,0.397570,-0.170530,-0.144636,0.067213,-0.073772,-0.594732,-0.085492,-0.273308,-0.249878,-0.062407,0.331608,0.030768,-0.172392,0.287865,-0.536557,0.114800,-0.482176,-0.436296,-0.264030,-0.384281,-0.133851,-0.634800,0.055523,-0.092425,-0.259507,0.107972,0.442166,-0.333199,0.434661,-0.813656,0.309317,0.781140,0.364155,-0.361985,0.370898,0.132545,0.397755,-0.262421,-0.385251,0.214520,0.319042,0.259947,-0.020716,0.285368,0.268282,-0.673203,0.022533,0.426452', '1793491', '27009869', '1297689', '1294893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3013580', '意外', '悬疑', '某人在开车经过街区时被突然从天而降的碎玻璃砸中，当场毙命。警察及时赶到，将此案定为意外。而实际上，意外乃是犯罪团伙联手制造的假象。团伙的首领大脑（古天乐 饰），跟女人（叶璇 饰）、胖子（林雪 饰）以及嗑药老头（冯淬帆 饰），经常联手搞意外杀人。他们采取的手段多为利用电击、雷劈、车祸、悬挂物坠落等方式。在作案中，大脑负责全盘统领，女人协助做诱饵，胖子和嗑药老头做障眼法。在前面的案件中，由于嗑药老头导致的失误，险些令行动失败，所以大脑大发雷霆，生怕稍有闪失即遭覆灭。后来，在妻子（莫小奇 饰）的温柔乡中，大脑紧张的神经才得以恢复平静。然而，后一单的雨夜杀人计划依旧遇到了前所未有的难题，一个神秘人物陈芳洲（任贤齐 饰）的出现，改变了这个集团的命运……©豆瓣', '古天乐', '郑保瑞', 7.4, 97947, 'tt1202514', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2196915554.jpg', 0.3, 2.6, 36.1, 49.4, 11.6, '0.062421,0.087713,-0.419106,0.131024,0.020730,0.093190,0.487743,0.338030,-0.562621,-0.298131,0.514594,0.329546,-0.279021,-0.267732,0.450920,-0.384152,-0.156437,-0.637486,0.017590,0.115199,-0.423931,-0.360755,-0.097548,-0.324385,0.038019,-0.465173,0.405955,0.041052,-0.380332,0.327166,0.192504,0.516251,-0.196612,0.414550,0.137313,-0.026333,0.166264,-0.258904,-0.144675,0.243970,0.068155,-0.702838,0.286742,0.175969,-0.201917,0.558259,0.672239,-0.340945,-0.434433,-0.368551,0.194575,-0.254331,-0.246676,-0.040937,0.347450,0.120863,0.380880,0.107639,-0.223562,0.105811,0.423554,0.085270,-0.624394,0.028435,0.346592,0.097328,-0.453964,0.097987,0.034438,0.224372,0.056079,0.007362,0.464818,0.327350,0.882808,0.254951,-0.309537,0.107497,-0.375861,-0.100154,0.375034,-0.233654,-0.288161,0.342136,0.144677,-0.187014,0.098781,-0.244448,0.197684,0.234370,0.306660,0.046489,-0.308729,0.290262,-0.240834,-0.076736,-0.315639,0.045714,-0.265668,-0.108283,-0.423213,-0.435591,0.052226,0.114054,-0.125819,0.228677,-0.016448,0.096060,0.098912,-0.480531,0.146839,0.310560,0.014354,-0.294082,0.211977,-0.059928,-0.044811,-0.323257,-0.169730,-0.164676,0.192541,0.310795,0.020156,0.094849,-0.113175,-0.177790,-0.053296,-0.036933', '26691509', '2988294', '1432699', '26775933');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30135942', '默片解说员', '喜剧', '一百年前，黑白默片风靡日本，大人小孩都为之著迷。俊太郎（成田凌 饰）常常鑽进戏院偷听免费电影，不管是邦片还是洋片，总能将辩士的口吻模仿得唯妙唯肖，「旁白辩士」是俊太郎自幼的梦想，长大后却沦落为「冒牌辩士」，分散观众的注意力，再让小偷趁机闯空门。在某次差点穿帮的过程中，他带著赃款逃到小镇戏院「青木馆」，戏院裡有醉汉辩士、花美男辩士还有肥宅辩士等各种不同风格的辩士，加上电影放映师、乐师以及小气老闆夫妻带他畅游电影幕后世界，但小偷集团、热血警察紧追不捨，童年一起看电影的初恋女孩也跟著现身，还有镇上那新开幕的时髦戏院，老闆的女儿也疯狂地爱上了他，俊太郎的青春恋爱梦该何去何从……', '成田凌', '周防正行', 7.7, 16581, 'tt11147106', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2571079312.jpg', 0.5, 2.2, 27.5, 51.1, 18.7, '-0.000431,-0.110516,-0.212580,0.334484,0.063416,-0.331961,0.519364,0.288008,-0.266167,-0.092389,0.170089,0.525013,-0.293792,0.323156,0.230300,0.105077,-0.287031,-0.735756,-0.576013,0.100014,0.178632,-0.105168,0.047964,-0.069063,-0.209420,-0.128797,0.394230,0.090845,-0.160707,0.249021,0.419707,-0.065020,-0.274038,0.085144,-0.170733,0.042384,-0.045860,0.046876,-0.256235,-0.051011,0.105491,-0.185881,-0.210441,-0.139577,-0.046211,0.128322,0.720594,0.109705,0.015266,-0.100871,0.271850,0.040659,-0.222484,0.041769,0.266035,-0.149658,0.301309,0.015240,0.209869,-0.117380,0.016654,0.075282,-0.484603,0.397992,0.256108,0.223782,-0.151219,0.124295,-0.063593,-0.024671,0.236329,0.062108,0.177508,0.054658,0.490229,0.125716,-0.007800,0.192002,-0.325144,0.566349,0.489909,0.097537,-0.138004,0.421555,0.012241,-0.196999,-0.117658,-0.377121,-0.336024,-0.025231,0.021582,-0.303611,-0.271073,0.193224,-0.327730,-0.122158,0.105478,0.181652,0.174868,-0.351924,-0.183481,-0.790657,-0.075522,-0.409546,0.176187,0.073674,0.353402,0.092223,0.706861,-0.335813,-0.151893,0.563925,0.351747,-0.288830,0.862777,-0.155446,-0.397045,-0.131697,-0.273041,0.077904,0.160474,0.262470,-0.021013,0.365640,-0.031336,-0.342629,-0.399792,0.235945', '1322847', '1291564', '3811356', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30136177', '黑夜吞噬世界', '恐怖', '看起来有些格格不入的山姆（安德斯·丹尼尔森·李 Anders Danielsen Lie 饰）来到前女友组织的喧嚣派对之中。整个晚上人们纵情狂欢，高歌劲舞，山姆焦灼地穿梭而过，渴望早些取到想要的东西快些离去。许是神经过于紧绷，疲惫的山姆瘫坐在沙发中沉沉睡去，全然没有听到门外传来的撞击声和尖叫声。次日一早，山姆醒来，正准备带着个人物品离开，结果却发现房间墙壁、地板满是血迹，此前活生生的人全部变成了嗜血如命、丧失人性的僵尸。街道上僵尸狂奔，搜寻猎物。无助的山姆被迫困在公寓里，他试图逃生，然而整个城市似乎已经被绝望和死亡所主宰……本片根据法国作家PitAgarmen的小说改编。©豆瓣', '安德斯·丹尼尔森·李', '多米尼克·罗彻', 6.6, 6999, 'tt4266076', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2526960359.jpg', 2.5, 11.6, 48.3, 29.2, 8.4, '0.281844,0.258726,-0.988650,0.200853,0.088488,-0.250879,1.074482,0.191337,-0.469940,-0.341253,0.157114,0.307737,-0.342598,0.454998,0.313967,-0.111143,-0.448101,-0.648951,-0.369144,0.046812,-0.429730,-0.103142,-0.004233,-0.401660,-0.086161,-0.265418,0.652938,0.234199,-0.053313,0.692420,0.005833,0.171921,-0.348272,0.874594,-0.206466,-0.035149,0.052505,-0.071406,-0.078889,0.024872,0.120277,-0.240835,-0.146515,0.002800,-0.160876,0.106608,0.664220,-0.296779,0.146684,0.055788,0.126483,0.005816,-0.110092,0.252274,0.200218,0.064381,0.135498,-0.103941,-0.091459,0.164158,-0.052675,0.108061,-0.334526,0.082693,-0.079738,0.421515,-0.350777,0.422255,-0.093610,0.264222,0.237483,-0.403107,0.453545,-0.292225,0.020451,0.622788,0.066470,-0.018025,-0.590784,-0.118829,0.308278,-0.075804,-0.073747,0.330444,-0.194727,-0.337799,0.174770,0.131854,-0.210938,-0.396427,0.456828,0.200900,-0.310498,0.119595,-0.690846,0.069482,-0.009953,-0.691764,-0.319023,-0.112513,-0.343363,-0.706705,-0.146476,-0.073314,0.233870,0.352256,-0.128202,0.057529,0.341599,-0.524721,0.321048,0.285637,0.061337,0.108112,0.304012,-0.489861,-0.039636,0.179948,-0.025419,0.570015,0.064975,0.602704,0.325058,0.263673,-0.529898,0.252313,-0.942629,0.593282', '3011051', '1945330', '26751772', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30137576', '记忆', '剧情', '杰西卡·霍兰德（蒂尔达·斯文顿 Tilda Swinton 饰）是旅居哥伦比亚的欧洲人，她来到波哥大看望她生病的姐姐（艾格尼丝·布雷克 Agnes Brekke 饰）。因为总是听到奇怪的巨响，于是她试图去找寻幻听的根源，并由此开始了一场由幻想、偶遇与重逢组成的，与记忆和历史产生回响的旅程。', '蒂尔达·斯文顿', '阿彼察邦·韦拉斯哈古', 7.7, 8316, 'tt8399288', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2666266209.jpg', 1.6, 5, 27, 41.3, 25.1, '0.188346,-0.120987,-0.747551,0.494739,0.151132,-0.397297,1.071959,0.001530,-0.693535,-0.598220,-0.114205,0.992549,-0.441916,0.180988,0.497982,0.103916,-0.343521,-0.727313,0.382509,0.032304,0.064676,-0.375390,-0.159993,-0.174291,0.125300,-0.591878,0.165714,-0.040118,-0.544708,0.692934,0.171827,0.573262,-0.194638,0.453925,-0.276023,0.132359,-0.325225,0.180907,-0.390312,-0.123700,0.275849,-0.177869,0.051123,-0.197382,-0.275802,0.303089,0.628342,-0.260345,0.028965,0.071869,0.300408,-0.114375,0.024738,0.157453,-0.032464,0.281386,-0.036821,0.325431,-0.407849,0.317513,-0.145651,-0.201971,-0.362586,0.180226,0.085789,0.296133,-0.242983,0.218612,-0.014095,-0.253732,0.235355,-0.095329,0.230632,0.479342,0.419168,0.482045,-0.208849,-0.040037,-0.259982,-0.120602,0.751764,-0.053009,-0.102287,0.378284,-0.006177,-0.408762,-0.024227,0.164426,-0.290977,0.274539,-0.022412,0.095709,-0.094692,0.365515,-0.766308,-0.018905,-0.463546,-0.475338,0.227439,-0.343072,-0.166250,-0.804805,-0.193747,-0.406361,-0.192589,-0.198272,-0.100784,-0.229398,0.236050,-0.964296,0.298942,0.578427,0.325924,-0.200280,0.266362,0.087918,-0.168170,-0.337733,0.165216,0.684090,-0.271550,0.216004,-0.229618,0.049852,0.285962,0.111469,-0.523096,0.181583', '1296534', '1300958', '1301686', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30139756', '只有爱能让我生存', '爱情', '津奈木（菅田将晖 饰）和宁子（趣里 饰）同居三年，在这三年里，宁子的精神状况每日愈下，如今，她被抑郁折磨的已经无法外出，也无法从事家务劳动，只能够每天躲在被窝里睡觉。津奈木一人担负起了整个家庭的重担，虽然他内心里怀揣着远大的文学梦想，却为了收入每天撰写着毫无价值的野鸡八 卦报道。辛苦了一天的津奈木回到家里，等待着他的往往是宁子的无理取闹，虽然感到痛苦，但津奈木从来都没有跟宁子发过脾气。一天，津奈木的前女友安堂（仲里依纱 饰）前来拜访，表露出了想要和津奈木复合的意图。为了使宁子能够离开津奈木，独自一人也能活下来，安堂将玲子送到了咖啡店打工。©豆瓣', '趣里', '关根光才', 7.5, 10877, 'tt8676984', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2534687964.jpg', 1.5, 5, 31.8, 41.6, 20.2, '0.135472,0.137245,-0.822045,0.294078,-0.228553,-0.331981,0.678265,0.132854,-0.854328,-0.480244,-0.125741,0.601257,0.065330,0.590983,0.192566,-0.192809,-0.308282,-0.520066,-0.243971,-0.138792,-0.073827,-0.297832,-0.243950,-0.186519,-0.428545,-0.136153,0.305186,0.050045,0.216025,0.410883,0.339143,0.106692,0.055950,0.413088,-0.244499,-0.176801,-0.137382,0.152518,-0.025185,0.292925,0.152892,-0.410094,-0.234535,0.184302,0.364762,0.162504,0.576569,-0.055731,-0.220941,-0.028715,0.244322,-0.150188,-0.119858,0.268276,0.284892,0.044469,0.529897,0.339353,-0.385215,0.335414,0.296923,-0.153984,-0.868752,-0.033553,0.033561,0.225022,-0.860768,0.638851,-0.219923,-0.104884,-0.078378,-0.499719,-0.007453,0.398094,0.129767,0.501215,-0.351808,0.014129,-0.560923,0.223537,0.663516,-0.113480,-0.100956,0.334026,-0.231920,-0.158842,-0.078593,-0.319836,-0.431078,-0.228637,0.173687,0.311133,-0.458335,-0.024662,-0.399041,0.397727,0.003665,-0.340166,-0.032266,-0.265488,-0.024643,-0.377172,0.100166,-0.528423,-0.520282,0.347267,0.296983,-0.246355,0.448904,-0.775824,0.394124,0.314322,0.370572,-0.496032,0.525648,0.390477,0.071984,0.079337,0.261817,0.242232,-0.355157,0.641394,0.294573,0.319713,0.006832,-0.166554,-0.735374,0.634289', '1866424', '1299965', '1783461', '27125208');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30140101', '你觉得我是谁', '剧情', '比诺什在片中饰演50岁的离异教师克莱尔，她为了监视自己的情人乔，在Facebook上虚构了一个24岁漂亮黑发女生的人物身份。但是乔只接受自己认识的人的好友请求。为了能接近乔，克莱尔给他最好的朋友克里斯发了好友请求，克里斯接受了。不曾想，经过一段时间的聊天，克莱尔爱上了克里斯，克里斯也爱上了这个虚构出来的女生，他提出想见一面的要求。于是克莱尔不得不编出了一份繁忙的工作，一次长时间的出差旅行，还有一个嫉妒心很强的前任。她要么只能继续编造各种谎言来维持这份没有未来的爱情，要么就得承认自己的欺骗并做好失去爱情的准备……', '朱丽叶·比诺什', '萨菲·奈布', 7.6, 9012, 'tt7552686', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2545203566.jpg', 0.4, 2.6, 30.2, 51.3, 15.5, '0.562348,0.096823,-0.490781,1.014897,-0.635321,-0.435156,0.579604,-0.043103,-0.384563,-0.533426,-0.026950,0.791430,-0.010222,0.292938,0.227289,0.053011,-0.522050,-0.564473,-0.054732,-0.044904,-0.310510,-0.704582,-0.181695,-0.446062,-0.262189,-0.029360,0.542896,0.001331,-0.086313,0.194281,0.416505,0.167119,0.493305,0.329139,0.011532,0.085142,-0.095204,0.143032,-0.179191,0.446465,0.202644,-0.189366,-0.030333,0.438461,0.162516,0.557048,0.395161,-0.219711,-0.215293,0.024925,0.440269,-0.438473,0.147431,-0.015957,0.133591,-0.179693,0.387896,0.013187,-0.225382,0.014324,0.082993,-0.141391,-1.014842,-0.028785,-0.044756,-0.064369,-0.513870,0.442123,-0.239863,0.084479,0.151166,-0.378273,-0.096644,0.270062,0.160572,0.174232,-0.192698,0.069800,-0.302232,0.569781,0.764974,0.133769,-0.396235,0.366519,-0.571783,-0.244011,-0.054412,-0.417562,-0.734878,0.057609,0.215589,0.084955,-0.341423,-0.180582,-0.314126,-0.270750,-0.274142,-0.027888,0.141128,-0.590243,-0.015009,-0.355212,-0.246055,-0.282273,-0.234868,-0.126599,-0.066326,-0.549703,0.612587,-0.903176,0.279806,0.656495,0.161297,-0.828398,0.813240,0.515127,-0.180305,-0.375118,0.050626,0.488983,0.030917,0.131038,0.082699,0.059286,0.225699,-0.019368,-0.426343,0.375197', '3785918', '1877596', '26678784', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30140107', '真相', '剧情', 'Fabienne是一个女星——是法国影坛巨星。在拥护爱戴她的男人面前她是高高在上的女神。她的女儿因她出版回忆录而带着丈夫和年幼的孩子从纽约回到巴黎。母女二人的重聚很快便变成互相指责：真相将被揭露、算清所有前帐，向对方坦然承认自己的爱和怨恨。', '凯瑟琳·德纳芙', '是枝裕和', 7.1, 12649, 'tt8323120', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2565063791.jpg', 0.5, 3.6, 43.7, 43.4, 8.7, '0.138520,0.139243,-0.936276,0.664494,-0.295301,-0.282749,0.933492,0.113052,-0.484945,0.302012,0.342040,1.212037,-0.283510,0.541562,0.121145,0.150042,-0.247840,-1.070493,-0.323890,-0.096703,0.068990,-0.377649,-0.046492,-0.100201,-0.375218,-0.221044,0.764416,-0.005555,-0.203417,0.313625,0.758311,0.258225,-0.193744,0.697315,-0.327228,0.185691,-0.202639,0.021381,-0.409232,0.289015,0.103216,-0.431460,-0.291104,0.299363,-0.288790,0.157867,0.843051,-0.227327,-0.109242,-0.294066,0.678406,-0.560583,-0.048074,0.494320,0.158225,0.110750,0.115113,0.136802,-0.065941,-0.276921,-0.059403,-0.006799,-0.663280,-0.173961,0.114929,0.114395,-0.963805,0.758644,-0.337790,-0.096714,0.389866,-0.285158,0.415897,0.042013,-0.217494,0.608127,-0.219020,0.030616,-0.696486,0.269505,0.530164,0.187075,-0.219256,0.175596,-0.309394,-0.264891,0.077417,-0.342080,-0.774236,-0.104405,0.227019,-0.034086,0.005598,0.357943,-0.271503,-0.236226,-0.348834,-0.173703,0.487993,-0.971991,-0.039883,-0.257602,-0.390656,-0.634263,-0.463421,-0.212694,0.047084,-0.305677,1.011234,-0.747445,0.366840,0.530036,0.672204,-0.691824,0.928649,0.042011,0.130534,-0.109875,0.053146,0.310571,0.127568,0.091267,0.260279,0.274911,-0.068249,0.412060,-0.308515,0.535843', '1292207', '1456503', '1316525', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30140229', '来了', '悬疑', '野崎（冈田准一 饰）是一名灵异小说家，一天，一位名叫田原秀树（妻夫木聪 饰）的男子找到了他，说自己的家里发声了超自然现象，怀疑是不是有恶灵企图伤害他的妻子香奈（黑木华 饰）和孩子知纱。于是，野崎找到了灵能力很强的女友比嘉真琴（小松菜奈 饰），一起调查这起事件。让两人没有想到的是，没过多久，便传来了秀树和香奈惨死的消息，种种线索指出，潜伏在他们家里的“东西”不是等闲之辈。意识自己的力量远远不够的真琴搬出了自己的姐姐琴子（松隆子 饰），琴子是世界上远近闻名的驱魔师。在简单的调查了案发现场后，琴子向世界各地的灵媒发出了邀请，请他们于圣诞夜集结于此，共同对付这个超乎想象的邪魔。©豆瓣', '冈田准一', '中岛哲也', 7, 25695, 'tt7997042', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2539079432.jpg', 2.6, 9.3, 38.4, 35.9, 13.9, '0.292910,-0.132734,-0.568248,0.520383,-0.310180,-0.056739,0.651304,0.090249,-0.662461,-0.414259,-0.072000,0.696420,-0.087455,0.187353,0.150170,0.065081,-0.071468,-0.656236,0.008607,-0.126057,-0.463797,-0.576831,-0.343109,-0.341619,-0.049615,-0.404937,0.316365,0.182284,-0.519283,0.263749,0.303571,0.481356,-0.247201,0.352962,-0.189899,0.053059,0.118136,0.206810,-0.097854,0.368213,0.004223,-0.441648,0.053275,0.412009,0.053617,0.294600,0.448130,-0.280968,-0.216663,-0.035268,0.258561,-0.207292,-0.078345,0.112979,0.470867,-0.084591,0.092776,0.230959,-0.299525,-0.250689,0.110926,0.156654,-0.786522,-0.091789,0.237130,0.315946,-0.512768,0.241612,-0.090064,-0.165694,0.203136,-0.297409,0.354621,0.324982,0.074817,0.104008,-0.080328,-0.200925,-0.478845,0.098938,0.594766,0.011318,0.038761,0.271923,-0.218799,-0.588570,-0.363975,0.177646,-0.163069,0.199904,0.209002,0.249603,-0.272902,-0.038739,-0.444932,-0.304331,-0.121628,-0.079879,-0.045144,-0.312702,-0.104779,-0.607907,-0.053880,-0.508691,-0.422036,0.096791,0.097288,-0.285933,0.866504,-0.950559,-0.098807,0.610368,0.315540,-0.458204,0.650333,-0.260547,-0.089376,-0.216256,0.245437,-0.237234,0.082815,0.202351,0.296982,0.353344,0.124393,-0.229955,-0.471171,0.238201', '1793491', '25932086', '4301278', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30140231', '沦落人', '剧情', '这是关于两个沦落香港的最低下层的人的故事。中年男子汉昌荣（黄秋生饰）因意外受伤瘫痪后妻离子散，他认为人生再没有值得期望的东西，而自己亦不值得拥有任何东西。年轻菲佣Evelyn（Crisel Consunji饰）因为现实的原因，成为了一个寄人篱下的工人，放弃了成为摄影师的梦想。那一个夏天，这样的两个陌生人相遇相识，感情在他们的主仆关系中发芽，然而盛放的，却是灵魂与灵魂之间的尊重和爱。他们一起经历的春夏秋冬，令他们学习到底要怎样面对人生的四季。', '黄秋生', '陈小娟', 8.2, 39486, 'tt8497794', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2555952192.jpg', 0.4, 1.2, 17, 50.1, 31.2, '0.384921,0.007331,-0.663967,0.556343,-0.196702,-0.170917,0.901017,0.017470,-0.531276,-0.437290,0.087826,0.902819,0.219478,0.244010,0.003037,-0.247863,-0.028634,-0.700059,-0.071311,-0.156231,-0.346630,-0.399823,-0.196284,-0.141426,-0.300556,0.078291,0.833945,0.172788,-0.053512,0.476173,0.359815,0.217760,0.021829,0.343005,-0.168893,-0.068236,0.191862,0.405370,-0.600149,0.104699,-0.064112,-0.063618,0.061567,0.387501,-0.281191,0.259786,0.610093,-0.221709,-0.277404,-0.173100,0.459552,-0.148679,-0.091641,0.038261,0.064703,-0.003060,0.217713,0.183696,-0.003903,0.018002,0.202659,0.031834,-1.189985,-0.128102,0.343851,0.284361,-0.462178,0.572144,0.147686,-0.212910,0.003383,-0.073404,0.362474,0.432477,0.665825,0.402667,-0.408796,-0.196222,-0.476087,0.199025,1.046255,-0.104290,-0.548976,0.587685,-0.594645,-0.436258,-0.057217,-0.472138,-0.553503,0.141861,-0.127775,0.433430,-0.221500,0.181230,-0.572878,0.183407,0.016237,0.119867,0.010846,-0.533684,-0.068927,-0.222901,-0.212258,-0.699739,-0.654874,0.046064,0.092222,-0.441530,0.853009,-0.756184,0.226475,0.462054,0.478312,-0.880477,0.948997,0.417311,0.183302,-0.433431,-0.009604,0.454390,-0.074538,-0.085973,-0.178837,0.070766,-0.009814,0.229167,-0.404944,0.450127', '26678784', '30163500', '4301278', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30140571', '嗝嗝老师', '剧情', '患有抽动秽语综合征的女主人公奈娜。经过无数次面试失败后，终于找到理想的工作，成为了一名中学老师。然而她被指派的班级学生却是全校最顽皮的学生。', '拉妮·玛克赫吉', '西达夫·马贺拉', 7.4, 90083, 'tt6588966', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2535365481.jpg', 0.4, 3.5, 34.9, 46.1, 15.2, '0.261949,-0.272828,-0.049224,0.388728,-0.223949,-0.735522,0.537439,-0.127351,-0.419328,-0.437049,0.444962,0.481738,-0.392310,0.679159,0.615891,-0.414681,0.051413,-0.718250,-0.118756,-0.148865,-0.351877,-0.125968,0.296492,0.155972,-0.195894,-0.652483,1.061802,-0.124631,-0.175622,0.197193,0.452032,0.521022,0.182239,0.220757,-0.168661,-0.108872,0.607985,0.078141,0.097856,0.015847,0.134300,-0.291467,-0.149483,-0.200460,-0.108701,0.564957,0.679271,0.123880,-0.106590,-0.271213,0.775830,-0.468886,-0.259109,0.279103,0.726314,0.418980,0.327339,0.012129,0.168747,0.145159,-0.159884,-0.161810,-0.706014,-0.258580,0.406985,0.135351,-0.076780,0.466434,0.219089,0.068915,0.118476,-0.139588,-0.106315,0.305340,0.189083,0.350988,-0.363084,0.314648,-0.112476,0.445345,0.488874,-0.151701,-0.614141,0.410547,-0.232403,-0.967881,0.547374,-0.500424,-0.517474,0.376332,0.132715,0.197069,-0.463377,-0.006083,-0.376159,-0.302194,-0.281790,-0.573729,-0.038768,-0.148053,-0.403016,-0.768001,0.115956,0.431814,-0.468528,0.114137,-0.097887,-0.432085,0.896299,-1.398257,0.066830,0.441334,-0.196893,-0.457286,0.586170,0.214345,0.322227,-0.245465,0.096868,0.424002,0.104558,0.533994,-0.270773,0.639234,-0.748249,-0.521857,-0.593442,0.489444', '1826173', '1316589', '10174444', '26999591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30141681', '飞奔去月球', '动画', '影片讲述了小女孩菲菲的奔月故事。菲菲从小听着妈妈讲述的嫦娥与后羿的爱情故事长大，她坚信嫦娥是真爱永恒的化身。妈妈去世几年之后，爸爸准备再婚，菲菲深受打击。为了捍卫自己的家庭，为了向爸爸证明，嫦娥还在月球上永志不渝地等待后羿，她所代表的永恒真爱是真实存在的，菲菲自己动手制作了一艘“火箭飞船“，开启一段奇妙的奔月之旅。影片预计将于2020年在中国院线上映，海外观众可通过Netflix平台欣赏到这一影片。', '凯西·昂', '格兰·基恩', 6, 7119, 'tt7488208', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2621020634.jpg', 4, 20.8, 51.3, 18.8, 5.1, '-0.068768,0.131918,-0.698972,0.428639,0.209180,-0.370729,0.532646,-0.187873,-0.517187,0.164160,0.537574,0.668775,-0.205831,0.046730,0.197102,0.411487,-0.280422,-0.362665,0.170261,-0.044393,0.097719,-0.456620,-0.147899,0.298455,-0.099498,-0.532394,0.705044,-0.517434,-0.134199,0.359031,-0.108605,-0.074586,0.007910,-0.068614,-0.042529,0.300526,-0.224755,0.197168,-0.864840,0.239845,0.138041,-0.064897,-0.084264,0.212835,-0.437849,0.000230,0.702521,-0.425962,-0.225175,-0.093950,0.435670,-0.424460,-0.226882,-0.024538,0.091687,0.260232,0.224874,0.438953,-0.240382,0.053547,-0.104916,-0.129415,-0.585203,-0.237946,0.030053,0.199334,-0.220652,0.305387,-0.254008,0.048755,0.510666,-0.629722,0.146578,0.324729,0.158967,0.659398,-0.639291,0.106741,-0.439481,0.640365,0.601605,-0.055428,-0.086983,0.759741,0.173962,-0.025368,-0.243218,-0.043735,-0.931103,0.273496,0.209268,-0.030678,-0.364562,0.303002,-0.572887,0.159002,-0.161705,-0.314428,0.216720,-0.562958,-0.238161,-0.492739,-0.267749,-0.187029,-0.088169,-0.324504,0.094700,-0.451898,1.245050,-0.775868,0.441272,0.529159,0.400875,-0.387065,0.740536,0.209533,-0.011249,-0.394721,0.231321,0.339217,-0.485429,0.300685,-0.222991,0.067923,0.105195,0.087610,-0.691062,0.399567', '26348103', '25738406', '24284209', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3014200', '布偶大电影', '喜剧', '沃尔特（Peter Linz 配音）和盖瑞（杰森·席格尔 Jason Segel 饰）是一对情深意笃的兄弟，所不同的是沃尔特是一个永远不会长高的布偶，而盖瑞则是正常的人类。岁月流逝，盖瑞渐渐长大，拥有自己的工作和爱情，沃尔特则始终保持孩童般的心，他最爱看的就是电视上播放 的布偶秀，即使这个节目已经停播多年，但他还是布偶秀的忠实粉丝。某天，盖瑞和女友玛丽（艾米·亚当斯 Amy Adams 饰）、沃尔特前往洛杉矶旅行，顺便参观布偶秀的剧院。沃尔特意外得知，某黑心商人要收购这里的土地挖掘石油。为了保护心中的圣地，他必须找到散落在各个角落的布偶家族成员……本片荣获2012年奥斯卡最佳原创歌曲奖。©豆瓣', '杰森·席格尔', '詹姆斯·博宾', 6.8, 5309, 'tt1204342', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1663326320.jpg', 1.7, 8.7, 47.2, 31.7, 10.6, '0.047796,-0.140940,-0.316610,0.527277,0.021811,-0.134523,0.619254,0.126656,-0.299574,-0.174136,0.249211,0.838442,-0.195507,0.345488,0.097390,0.239022,-0.566161,-0.677165,-0.212838,-0.094230,0.058489,-0.397130,-0.299238,-0.275189,-0.052159,-0.143389,0.948976,-0.125702,-0.015250,0.382043,0.375324,0.202240,-0.228523,-0.056668,-0.379323,-0.077795,0.155820,-0.163979,-0.218162,0.062606,-0.099066,-0.020529,-0.003986,0.070387,0.195922,0.254701,0.664351,-0.220845,0.047976,-0.051209,0.381362,-0.197067,-0.066534,-0.049562,0.166320,-0.144216,0.514144,0.151780,-0.175744,0.097592,0.024357,-0.285981,-0.834887,-0.148701,0.320841,0.294807,-0.455428,0.603215,0.112452,0.096132,0.036396,-0.162537,0.365419,0.103281,0.247086,0.374983,0.010000,0.077864,-0.356976,0.331238,0.286963,0.194322,-0.075630,0.358865,-0.269586,-0.388590,-0.092864,-0.179826,-0.653064,0.077622,0.156675,-0.176617,0.127158,0.142611,-0.661111,-0.018705,-0.210522,-0.399559,0.296145,-0.394818,-0.135024,-0.758295,-0.074219,-0.450656,-0.092877,0.025963,0.129205,-0.387126,0.883561,-0.890436,0.139478,0.631617,0.103888,-0.360132,0.786509,-0.048631,-0.075408,-0.435341,-0.165477,0.239727,-0.161931,-0.178621,-0.121259,0.091516,0.133179,-0.353828,-0.370656,0.448637', '25880986', '3811356', '1870681', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3014302', '爱情公寓', '剧情', '滂沱大雨，促成了一段平凡又显得有些另类的姻缘。带着些许颓废气质的摄影师罗曼（Aleksey Chadov 饰）与学习大提琴的红发孤独女孩卡嘉（Olga Makeyeva 饰）在空荡荡的公车上相遇了。赤裸的足踝与类似的境遇让他们刹那间产生认同感，并很快坠入情网。爱情或需至纯至真，因此他们搬到一间与世隔绝的公寓内，切断电话线、门铃以及与外界的一切联系，在这个颓败的方寸空间内经营着只属于他们的爱情。但完美的爱情也许只存在于童话之中，即使怎样保持它的纯洁，仍不可避免地受到来自现实的侵蚀。罗曼和卡嘉的恋情也不例外……©豆瓣', '阿雷克西·查多夫', 'Alan Badoyev', 7.4, 9501, 'tt0489793', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2501441990.jpg', 1.4, 5.3, 32.5, 41.9, 18.9, '0.424844,0.250248,-0.788215,0.486262,-0.246372,0.009846,1.081044,0.210083,-0.510863,-0.378442,0.027633,0.747958,-0.124436,0.240401,0.215733,-0.099962,-0.253019,-0.586904,-0.122681,-0.177235,-0.242081,-0.346648,-0.365856,0.113815,-0.070420,-0.240679,0.927464,0.194335,-0.440030,0.547390,-0.018651,0.179694,-0.371042,0.528413,-0.212632,-0.206478,-0.243754,0.348850,-0.260522,-0.121493,0.049711,-0.131659,0.092471,0.140818,-0.385110,0.211138,0.734540,-0.600674,-0.258679,0.227050,0.424193,-0.117822,-0.222089,0.177587,-0.015672,0.043109,0.123800,0.211128,-0.493387,0.212491,0.223185,0.064190,-0.754393,-0.095667,0.080831,0.426234,-0.322719,0.687061,0.287262,-0.305708,0.068278,-0.197508,0.053998,0.153899,0.393209,0.630894,-0.301496,-0.088969,-0.492212,-0.116500,0.534229,0.112441,-0.617631,0.516739,-0.627588,-0.428848,-0.346509,-0.053056,-0.686384,-0.269409,0.175219,0.351781,-0.051097,0.369260,-0.856500,0.210344,-0.001488,-0.011285,-0.161112,-0.568530,-0.046394,-0.690249,-0.277861,-0.836913,-0.373857,-0.059419,0.296477,-0.175869,0.594355,-0.863206,0.292077,0.354238,0.256679,-0.305073,0.575831,0.293797,0.231184,-0.121613,-0.185023,0.709086,-0.108613,0.317674,0.035726,0.476513,-0.184905,0.315757,-0.586919,0.642277', '5029050', '1299261', '1296992', '6021916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30143331', '红色通缉令', '喜剧', '当国际刑警发布的红色通缉令（追捕世界头号通缉犯的最高级别通缉令）出炉时，联邦调查局的顶尖犯罪侧写师约翰·哈特利（道恩·强森饰）正在调查此案。在调查一起大胆的抢劫案中，约翰陷入了困境，被迫与世界头号艺术品大盗诺兰·布斯（瑞安·雷诺兹饰）合作，以抓捕世界头号通缉的艺术品窃贼“主教”（盖尔·加朵饰）。激动人心的冒险之旅将带领三人环游世界，他们的经历包括穿过舞池、被困在一个隐蔽的监狱、进入丛林，最糟糕的是，他们彼此间的默契不断增加。里图·阿亚和克里斯·迪亚曼托波洛斯加入了全明星阵容。《红色通缉令》由罗森·马歇尔·瑟伯（《乌龙特工》和《摩天营救》）担任导演和编剧，制片人团队包括 Seven Bucks Productions 的海拉姆·加西亚、道恩·强森和丹妮·加西亚，Flynn Picture Co. 的比尤·弗林，以及 Bad Version, Inc. 的瑟伯，该片是一部紧跟潮流的全球猫捉老鼠（还有猫）游戏。', '道恩·强森', '罗森·马歇尔·瑟伯', 6.3, 78027, 'tt7991608', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2702918768.jpg', 2.1, 14.1, 55.2, 22.3, 6.3, '0.299009,-0.214974,-0.547492,0.622457,0.227653,-0.080752,0.625625,0.257830,-0.433386,-0.145333,0.410780,0.700723,-0.242785,-0.088481,0.530721,-0.009475,-0.501340,-0.875131,-0.195360,-0.366884,-0.218812,-0.586836,-0.611366,-0.269784,0.105098,-0.305068,0.586149,-0.005583,-0.266026,0.382126,0.439555,0.456920,-0.432031,0.115091,-0.031747,-0.235133,0.768128,-0.162436,-0.435093,0.157954,-0.263963,0.032070,-0.017742,-0.183434,0.244479,0.202813,0.500913,-0.602398,0.079621,-0.169165,0.249200,-0.473400,-0.105577,-0.219863,0.474782,-0.160556,0.200245,0.243979,0.015049,0.065787,-0.001397,-0.200077,-0.954095,0.032079,0.210454,0.320871,-0.404760,0.037843,-0.335312,0.077458,0.332440,-0.068811,0.130670,0.267487,0.232167,0.174556,0.400382,0.143077,-0.444136,0.166424,0.255982,-0.034064,-0.161861,-0.102740,-0.004294,-0.391295,-0.246013,-0.090799,-0.175037,-0.068399,0.447171,-0.259326,0.066614,0.262236,-0.633971,-0.076844,-0.169476,-0.374020,-0.153394,-0.253569,-0.102436,-1.143089,-0.215813,-0.152031,-0.093952,-0.028995,0.057712,-0.083270,0.491289,-0.561141,0.218731,0.468517,0.021588,-0.294432,0.639893,0.066048,0.198109,-0.459535,-0.181906,0.074625,0.419702,0.232235,0.200178,0.315569,0.035455,-0.310107,-