INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30143333', '我的一级兄弟', '喜剧', '由陆相孝执导，申河均、 李光洙、李絮、 朴哲民、权海虓主演的喜剧电影，讲述肢体残疾一级的男子与精神障碍一级的男子相遇后发生的故事。', '申河均', '尹尚孝', 8.3, 75064, 'tt10237612', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2548467439.jpg', 0.2, 0.7, 15.2, 50.2, 33.6, '-0.079414,-0.504404,-0.365137,0.705832,0.279160,-0.143153,1.146330,0.341014,-0.253594,-0.114124,0.662401,1.011762,-0.627193,0.093212,0.722900,-0.505306,-0.156261,-0.714734,-0.124330,-0.029996,-0.351261,-0.484285,0.134075,0.199359,-0.283858,-0.598283,1.078909,-0.363611,-0.388336,0.312874,0.673547,0.100174,-0.222370,0.068539,0.147525,0.237704,-0.091009,0.013376,-0.207521,0.032672,0.134671,0.057406,-0.211124,-0.410479,-0.402675,0.225843,1.097211,-0.188408,0.101718,-0.276408,0.583855,0.166324,0.033235,-0.333202,0.162502,0.478269,0.501214,0.562006,0.472564,-0.102446,0.097912,0.038883,-0.532087,0.282349,0.094835,0.519322,-0.053987,0.535205,0.036426,0.101007,0.203496,-0.022375,0.064420,0.258459,0.623138,0.371209,-0.361729,-0.032531,0.061505,0.559407,0.554130,0.209325,-0.546139,0.605465,0.007261,-0.813195,-0.427686,0.087266,-0.568405,0.417305,-0.175577,0.089909,-0.288357,0.252055,-0.131235,-0.554112,-0.176864,0.274964,-0.154667,0.230283,0.003208,-0.446908,-0.173280,-0.341706,-0.128964,-0.238568,0.432774,-0.369435,0.563644,-0.470822,-0.109856,-0.125808,0.312143,-0.350409,0.351068,-0.174201,0.507096,-0.330371,-0.011318,0.146347,0.000136,-0.166461,-0.053794,0.615371,-0.381025,0.315291,-0.424382,0.171317', '1467779', '21619567', '1322847', '1307800');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30143336', '灯塔', '恐怖', '1890年代，两名灯塔管理员试图在他们生活在偏僻而神秘的新英格兰岛上时保持理智。随着雾角的摇摆声响彻空中，沉默寡言的前伐木工人埃弗莱姆·温斯洛和两鬓斑白的灯塔管理员托马斯·韦克踏上了十九世纪末新英格兰沿岸一个僻静且了无生气的岛屿。 在接下来四周艰苦的工作和不利的条件下 ，俩沉默寡言男人除了彼此以外，没有其他人的陪伴，被迫忍受，仇怨与日俱增。 然后，在恶劣的预兆中，狂怒而无休的暴风使看守员受困于本就不宜居的火山岩，助长了长期的野性饥饿；极度痛苦；使人躁狂的隔绝以及恐怖的酒后幻觉。现在，精神错乱得令人窒息。 还可以从无形的牢狱中逃脱吗？', '罗伯特·帕丁森', '罗伯特·艾格斯', 7.3, 45374, 'tt7984734', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2572123509.jpg', 2, 5.9, 33, 43.3, 15.7, '0.229283,0.052043,-0.936886,0.654855,-0.000737,-0.085966,1.095557,0.302306,-0.452054,0.095777,0.071575,0.466277,0.009799,0.263431,0.082136,-0.160394,-0.187209,-0.743945,-0.500613,-0.021643,-0.475298,-0.486431,-0.400191,-0.343963,-0.298478,-0.599310,0.481222,0.316131,-0.275489,0.413535,-0.193841,0.284314,-0.264209,0.578492,-0.323452,-0.405723,0.104860,-0.151820,-0.072236,0.125297,-0.050794,-0.183763,0.049197,0.257258,0.021853,0.610342,0.767716,-0.398924,-0.236984,-0.038040,0.148372,0.150691,-0.205866,0.213810,0.297875,-0.256808,0.207598,0.208138,-0.254537,0.059614,-0.191636,-0.012074,-0.556396,0.074663,0.136479,0.185180,-0.506049,0.752439,0.150735,-0.342453,0.118307,-0.176226,0.205934,0.174792,0.028820,0.592686,-0.116303,-0.000795,-0.239534,0.040194,0.710151,0.115028,-0.712017,0.240394,-0.385039,-0.270271,-0.198572,-0.152734,-0.527034,-0.484129,0.187863,0.152818,-0.175569,0.298938,-0.601698,0.338893,-0.112244,-0.084707,-0.531626,-0.212949,-0.496216,-0.580039,-0.003908,-0.406468,-0.007767,0.257522,0.009453,0.004672,0.443207,-0.633119,0.563995,0.634014,0.137399,-0.075406,0.489890,-0.016824,0.296270,0.048213,-0.173710,0.222719,-0.031454,0.618668,0.304424,0.305347,-0.362018,0.196940,-0.418817,0.578275', '20451118', '21619567', '25884436', '21339377');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30143523', '死亡天使', '剧情', '布宜诺斯艾利斯，1971年。Carlitos是个17岁的青少年。他拥有常人难以抗拒的天使般的面庞。不论他想得到什么，他总能心想事成。在学校，他与Ramon不期而遇。两人组成了魅力难当的美男二人组。他们很快踏上了一条以偷盗、谎言，甚至杀戮组成的堕落之路，而这只是他们表达自我的一种方式。', '洛伦佐·法罗', '路易斯·奥特加', 7.4, 8278, 'tt7204348', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2527181272.jpg', 1.3, 4.4, 34, 43.3, 16.9, '0.363179,0.020478,-0.504018,0.888148,-0.369500,-0.021802,0.910825,-0.042564,-0.417431,0.045652,0.109354,0.832475,-0.202227,0.209150,0.097092,-0.196848,0.099453,-0.541277,0.164057,-0.235994,0.007679,-0.187566,-0.420964,-0.123338,-0.275632,-0.108576,0.784748,0.211295,-0.017065,0.441416,0.273387,0.331960,0.147885,0.380117,-0.302911,-0.330230,-0.097358,0.047522,0.046963,0.040974,0.001413,-0.274038,-0.138294,0.534391,-0.841754,0.245469,0.853365,-0.400302,-0.119380,-0.207486,0.438306,-0.352156,0.003996,0.324536,-0.090088,-0.248877,0.189940,0.037465,0.132200,-0.147202,0.205052,0.157040,-0.939573,-0.385717,-0.027170,-0.005321,-0.271850,0.034670,0.099845,-0.132798,0.140910,-0.459158,-0.223344,0.089704,0.221967,0.423984,-0.133416,-0.421137,-0.566216,0.149597,1.021233,0.130856,-0.935325,0.484600,-0.637083,-0.678544,-0.297546,-0.419115,-0.533787,-0.061714,0.190612,0.128310,-0.070978,0.010155,-0.873259,0.141260,-0.091686,0.209437,-0.242475,-0.636667,0.167154,-0.371398,-0.298843,-0.756557,-0.343198,0.110109,0.343459,-0.246882,0.772220,-0.897983,-0.070156,0.740432,0.305994,-0.741200,0.835693,0.021914,-0.102398,-0.167456,-0.046018,0.411988,-0.331894,0.314399,-0.091534,0.675722,0.130125,0.441641,-0.526513,0.680483', '2053515', '1303542', '30162520', '1304641');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30143698', '兰开斯特之王', '剧情', '蒂莫西·柴勒梅德将加盟新片[兰开斯特之王](The King，暂译)，出演男主角年轻的亨利五世。亨利五世为英格兰兰开斯特王朝国王，在他短暂的九年统治期间，他取得了中世纪任何一位英格兰国王都未取得过的军事辉煌。本片由布拉德·皮特公司Plan B制作，大卫·米奇欧德([动物王国])执导，米奇欧德也将与乔尔·埃哲顿担任编剧，计划6月开机。', '蒂莫西·柴勒梅德', '大卫·米奇欧德', 6.5, 7324, 'tt7984766', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2567131266.jpg', 1.7, 12.6, 51.1, 27, 7.6, '-0.209505,0.548001,-0.608857,0.827070,0.051521,-0.514626,0.229266,0.079416,-0.291597,-0.488891,0.188124,1.116471,-0.607362,-0.150393,0.655335,-0.090118,-0.398318,-0.550989,0.005305,-0.114579,0.282471,-0.507578,-0.588987,-0.412479,-0.354990,-0.775044,1.037934,-0.197104,0.222097,0.283495,0.115935,0.240707,0.497051,0.025183,0.436412,0.300722,0.638546,-0.331394,-0.569177,0.484222,-0.047909,-0.025019,-0.329030,0.257630,0.354616,0.336588,0.127889,-0.667967,0.478315,-0.453476,0.467124,-0.228237,0.260911,0.118897,0.343788,-0.065805,0.016656,0.896817,0.064870,-0.268860,-0.132008,-0.527431,-0.783591,0.125568,-0.110525,0.213837,-0.567710,0.371453,-0.910356,0.095059,0.084175,-0.427396,0.106547,0.710285,0.613328,0.255061,0.243692,0.468750,-0.517130,0.602855,0.490393,-0.173293,-0.664077,-0.116536,0.060196,-0.747371,-0.213898,-0.267259,-0.592506,0.175651,0.389327,-0.420892,0.568113,0.372965,-0.585130,-0.079273,-0.635285,-0.715149,0.449071,-0.265437,0.226671,-1.075132,-0.177933,-0.076003,0.054219,-0.374527,0.274685,-0.190568,0.540080,-0.527126,0.334959,0.507588,0.412802,0.020442,0.673852,0.019254,0.251193,-0.214101,-0.241922,0.838725,0.269774,-0.172168,0.091764,0.290975,0.227777,-0.183188,-0.141845,0.474287', '26990609', '30397916', '1780122', '10508921');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30143861', '我的冤家是条狗', '喜剧', '弗朗西斯（比蒂·埃德蒙森 Beattie Edmondson 饰）最近似乎是触了霉头，事业又失恋，与此同时，她的外婆亦去世了。无奈之下，弗朗西斯只得收养了外婆的爱犬——一只名叫帕特里克的八哥犬。弗朗西斯本身并不喜欢动物，她所居住的公寓也明令禁止不许养宠物，帕特里克的存在让弗朗西斯整天战战兢兢提心吊胆。况且帕特里克也不是省油的灯，他贪吃又调皮，整天给弗朗西斯惹麻烦，令她的主人不禁怀疑，它是上天派来惩罚自己的吗？养狗虽然面临着各种困难，但同时也乐趣多多，在养狗的过程中，弗朗西斯结识了英俊的兽医奥利华（艾德·斯克林 Ed Skrein 饰）和爱狗人士阿宾（汤姆·班尼特 Tom Bennett 饰），交际圈的拓展让弗朗西斯逐渐脱离了曾经的怨妇状态。©豆瓣', '比蒂·埃德蒙森', '曼迪·弗莱彻', 6.3, 11858, 'tt6542108', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2537054509.jpg', 2.5, 14.9, 54.9, 22.3, 5.3, '0.280664,-0.009082,-0.419523,0.527401,-0.213180,-0.350206,0.582686,0.196203,-0.524395,-0.209353,-0.113831,0.660096,0.114191,0.433223,-0.103281,0.251484,-0.116242,-0.358918,0.109723,-0.049582,-0.147189,-0.333923,-0.214432,-0.420132,-0.039487,-0.412412,0.188205,-0.116448,-0.114554,0.246644,0.321090,0.266980,0.075270,0.444356,-0.260712,0.155864,0.135313,-0.063304,0.132947,-0.126600,0.242566,-0.155823,-0.002228,0.318117,0.362015,0.315426,0.421226,-0.456194,-0.265223,-0.339024,0.196044,-0.150547,0.101216,0.124459,0.241138,-0.300538,0.264421,0.028815,-0.012644,0.329015,0.042746,-0.007395,-0.607389,0.016166,0.139684,0.029466,-0.633993,0.441885,-0.079581,-0.042848,0.034439,-0.118159,0.148953,0.211083,-0.044924,0.335450,-0.090313,0.158382,-0.284915,0.105736,0.386218,0.125394,-0.134083,0.302144,-0.541917,-0.266500,0.104062,-0.295832,-0.544211,-0.147118,0.285267,-0.109333,-0.293044,0.364955,-0.446360,-0.088218,-0.066457,0.016951,-0.237794,-0.475611,0.035174,-0.318370,0.188334,-0.615003,-0.254674,-0.082075,0.001554,-0.339340,0.389715,-0.769377,0.276045,0.723389,0.114977,-0.389891,0.636789,0.045606,0.070323,-0.116170,-0.145099,0.321902,0.141269,0.188612,0.285142,0.211205,0.374741,-0.329627,-0.142685,0.657519', '10774184', '1308314', '4058933', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30143939', '神童', '惊悚', '在一个弥漫着不祥气息的夜晚，约翰（彼得·穆尼 Peter Mooney 饰）和莎拉（泰勒·席林 Taylor Schilling 饰）迎来了家庭的新成员，与此同时在世界的另一个角落，某个冷血杀人狂遭受警方枪击，倒在血泊之中。此后不久，莎拉发现她这个有着异色瞳的儿子迈尔斯具有远超出同龄人的智慧，她为此兴奋不已，一门心思以天才的方式培养儿子。可是随着儿子年龄的长大，种种异相接二连三在迈尔斯的身上发生。他会在梦中用匈牙利语咒骂他人，会以残酷凶狠的手段殴打同学，他眼神中透露出来的冷酷凶残令约翰、莎拉夫妇站立不安。从他人口中得知，迈尔斯体内有可能住着另一个人的灵魂，而那个灵魂以残杀嗜血为乐……©豆瓣', '泰勒·席林', '尼古拉斯·麦卡锡', 6.1, 7796, 'tt4504044', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2544381499.jpg', 3.4, 19, 52.5, 18.8, 6.3, '0.123723,0.103596,-0.744271,0.640649,-0.104504,0.090184,0.954713,0.111932,-0.670581,-0.390517,0.395115,0.739898,-0.050533,0.315436,0.229148,-0.054643,-0.069548,-0.626997,-0.283165,-0.217362,-0.274697,-0.478863,-0.290871,-0.350270,0.055483,-0.629939,0.415172,0.064047,-0.259589,0.530086,0.278745,0.643651,-0.253029,0.486895,-0.259219,-0.030292,0.066462,-0.174008,-0.095874,0.167339,0.039806,-0.094961,-0.015915,0.102452,-0.192629,0.220130,0.813399,-0.156455,-0.195681,-0.222354,0.549611,-0.096371,-0.229051,0.225744,0.312111,-0.106022,0.177093,0.068495,0.047001,-0.030716,0.030247,0.071499,-0.940582,0.003338,-0.082396,0.341232,-0.409643,0.307934,0.066723,0.010879,0.305217,-0.180207,0.124193,-0.079184,0.081203,0.526109,-0.200298,0.041312,-0.410698,-0.260049,0.527137,-0.106392,-0.333517,0.149090,-0.501769,-0.304418,-0.130290,-0.248232,-0.525035,-0.103613,0.496746,0.174327,-0.316707,0.645386,-0.360518,0.033292,-0.010686,0.153231,0.038804,-0.283860,-0.571115,-0.508203,-0.337280,-0.429786,-0.332861,0.087003,-0.123413,-0.273673,0.680564,-0.835256,0.362011,0.509886,0.188790,-0.242451,0.500449,-0.130071,0.080147,-0.197880,-0.256643,0.431870,0.230028,0.032454,-0.091136,0.267424,-0.276498,0.198913,-0.371445,0.383412', '3005387', '1307311', '1306450', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30145117', '翻译疑云', '悬疑', '知名畅销小说作家的遗作——他生前畅销小说的三部曲最后一集，即将发布。为了能在世界主要地区同时出版这本小说，出版商聘用了9名来自世界各地的翻译员，同时在现场翻译小说。他们被关进了一间豪华但守卫森严的套房，时刻在监视之下。然而，绝密手稿的前十页突然在网上流出，出版商也被勒索巨额赎金。如果不支付五百万欧元，还会继续泄漏内容。除了出版商和这9名翻译，没有人接触过这份手稿。出版商确信，泄密者就在他们9人当中。究竟谁是这一切的幕后操纵者？', '朗贝尔·维尔森', '雷吉斯·罗因萨尔', 7.2, 36792, 'tt6270534', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2580137248.jpg', 0.9, 4.9, 38.6, 42.7, 12.9, '0.272052,0.018331,-0.834289,0.690912,0.073070,0.131758,0.512882,-0.094996,-0.431744,-0.204904,0.333604,0.748552,-0.101106,-0.227606,0.042177,0.067810,-0.384193,-0.482216,-0.191671,-0.708765,-0.225192,-0.586482,-0.321354,-0.495219,-0.148798,-0.218908,0.605614,0.262232,-0.446011,-0.101971,0.288512,0.258400,-0.383178,0.288493,-0.218210,0.164700,0.487996,-0.202806,-0.041007,0.336682,-0.010721,-0.286681,-0.145823,0.038841,0.223871,0.310455,0.544658,-0.322845,-0.164234,0.463969,0.565343,-0.055337,-0.151031,-0.072218,0.288083,0.016453,0.781435,0.443868,-0.246711,0.103543,-0.023341,-0.036340,-0.975327,-0.431428,0.236506,0.360060,-0.311506,0.466971,-0.365534,0.259897,-0.238013,-0.152050,0.377366,0.156160,0.197815,0.185098,0.312544,-0.244687,-0.500639,0.593437,0.156604,-0.050580,-0.167751,0.262146,-0.231572,-0.466941,-0.305141,-0.232478,-0.405485,0.350729,0.488949,0.183037,-0.161220,-0.112853,-0.492841,0.031263,0.135009,-0.477407,-0.119571,-0.636551,-0.405069,-0.661481,-0.166793,0.185047,0.128223,0.114816,0.379612,-0.395087,0.940046,-0.468516,0.160558,0.718706,0.295417,-0.435927,0.819586,0.098606,-0.203082,0.161387,-0.102717,-0.150711,0.435150,0.712247,0.295494,-0.087300,0.335336,-0.418583,-0.128935,0.432898', '27602116', '3318306', '4267948', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3014557', '最后的维加斯', '喜剧', '山姆（凯文·克莱恩 Kevin Kline 饰）和妻子结婚多年，两人感情十分要好，然而，腿脚的不便削减了山姆本该享受的快乐，再加上一个负能量爆棚的邻居，山姆觉得人生似乎失去了乐趣。阿尔奇（摩根·弗里曼 Morgan Freeman 饰）和儿子相依为命，可是，性格过于严厉的儿子令阿尔奇感到透不过气。派迪（罗伯特·德尼罗 Robert De Niro 饰）刚刚失去了挚爱的妻子，这让他的生活瞬间陷入了一片空洞和苍白之中。比利（迈克尔·道格拉斯 Michael Douglas 饰）正在着手准备他和年轻妻子的婚礼，这几乎成为了他生活的全部。四个人至暮年的老人，四位患难与共的好友，当他们重新聚集到一起，决定最后疯狂一把去拉斯维加斯参加单身派对之时，会有怎样有趣的故事发生呢？©豆瓣', '罗伯特·德尼罗', '乔·德特杜巴', 7.3, 13868, 'tt1204975', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2153684611.jpg', 0.6, 4.6, 38.2, 41.9, 14.8, '0.242000,-0.186536,-0.812052,0.493206,-0.164349,-0.588576,0.980060,0.337145,-0.624485,-0.284600,0.022310,0.933699,-0.246223,0.546771,0.503589,-0.016204,-0.198652,-0.762675,-0.181179,0.012319,-0.226914,-0.390045,-0.070840,-0.135891,-0.147607,-0.301627,0.450344,-0.096651,0.282520,0.527273,0.253631,0.335588,0.183003,0.502270,-0.019919,0.038020,0.164934,-0.005663,-0.481709,-0.025770,0.251638,0.127935,-0.066543,0.276655,-0.098232,0.229303,0.620973,-0.068452,-0.191380,-0.104574,0.287590,-0.051716,-0.163185,0.197247,0.043030,0.078820,0.138639,0.051201,-0.130191,-0.137898,0.220948,-0.179121,-0.690491,0.292370,-0.024074,0.094874,-0.528009,0.325996,-0.088425,-0.184350,0.118192,-0.279055,0.243259,0.434428,0.309300,0.387760,-0.177722,-0.003385,-0.314867,0.185748,0.972412,0.005492,-0.334548,0.302662,-0.336950,-0.201445,0.106221,-0.256500,-0.521301,-0.065260,0.276892,0.169070,-0.187782,0.426910,-0.604281,-0.053479,-0.162441,-0.229999,-0.093703,-0.428457,-0.035702,-0.400508,-0.401551,-0.569108,-0.317159,0.042200,-0.033001,-0.251140,0.633631,-0.736353,0.259100,0.279530,0.244523,-0.412635,0.540495,0.162151,0.267851,-0.199147,-0.056939,0.301657,-0.172013,0.072254,0.434416,0.183485,-0.069344,0.108085,-0.528358,0.542680', '25721544', '1296534', '30162520', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30146756', '风语咒', '动画', '生活在孝阳岗的少年郎明怀揣侠岚梦想，但双眼失明的他却只能靠招摇撞骗混于市井之中。直到有一天，罗刹袭击孝阳岗，与他相依为命的母亲突然失踪，郎明迫不得已踏上了找寻真相之路。一波未平一波又起，上古神兽饕餮现世让人间危在旦夕，传说中的侠岚们也出现在眼前，郎明也踏上了改变一生的冒险之旅……', '路知行', '刘阔', 6.8, 145306, 'tt9496406', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2530872223.jpg', 2.4, 11.4, 42.6, 31.4, 12.2, '-0.053905,0.190062,-0.870171,0.290944,0.360703,-0.429839,0.803169,-0.324406,-0.484925,-0.209689,0.335635,0.716789,-0.067355,0.259903,0.442971,-0.016070,0.091705,-0.464719,0.263142,-0.180475,-0.002485,0.007941,-0.528861,0.053769,-0.189416,-0.277054,0.944973,0.748150,-0.376121,0.381132,0.205400,0.182065,-0.476879,0.355386,-0.409674,-0.049735,-0.208743,0.541076,0.015716,0.111578,-0.093058,-0.524867,-0.209398,0.484853,-0.323244,0.252318,0.689601,-0.504948,-0.230647,-0.067112,0.090647,-0.626754,-0.423410,-0.192383,0.092361,-0.115783,0.044480,0.221380,0.025557,-0.200740,-0.419165,0.120206,-0.531925,-0.042302,0.140002,0.298384,-0.539901,-0.003805,0.321952,-0.100878,0.031436,-0.394489,0.412260,0.475343,0.580610,0.419664,-0.193647,-0.089739,-0.620884,0.080358,0.831748,-0.211780,-0.310090,0.348079,0.032856,-0.400956,0.072612,-0.310275,-0.551588,-0.140811,0.081200,0.228973,-0.397518,0.615915,-0.541277,0.253677,-0.282841,0.063483,0.041371,-0.228196,-0.115950,-0.100310,-0.097533,-0.362296,-0.418254,0.272376,0.081465,-0.497470,0.387667,-0.696233,0.570567,0.433725,0.077763,-0.443382,0.861249,-0.061351,0.177051,-0.185587,0.344985,0.676554,0.072175,0.467206,-0.230409,-0.195693,-0.039814,0.279801,-0.593233,0.483715', '35287908', '1291835', '11615927', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30146843', '德九', '剧情', '七岁的德九（郑志薰 饰）与妹妹德熙，一起和爷爷（李顺载 饰）住在一个小村庄。几年前，德九的爸爸因为交通事故过世，备受冲击的妈妈后来也不久于人世。爷爷只能四处打零工，努力扶养两个孙子，但甚至连想给德九买台玩具车都负担不起。当德九将进小学时，爷爷发现自己时日不多，担心年幼 的德九无法照顾自己和妹妹，爷爷准备了最后的礼物要给他两个孙子……', '李顺载', '房秀吟', 7.9, 6290, 'tt8383596', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2514413785.jpg', 0.4, 2.4, 22.9, 50.3, 23.9, '-0.162665,-0.126833,-0.770866,0.583391,0.009433,-0.825689,0.514131,0.182787,-0.615617,-0.602112,-0.333570,0.563684,0.093190,0.648011,-0.075100,-0.045836,-0.108771,-0.542875,-0.024830,0.029595,-0.616600,-0.576104,0.126739,-0.008415,-0.349830,-0.270757,0.083961,-0.162382,0.275318,0.346586,0.194177,0.252363,-0.077215,0.063845,-0.234461,0.222252,-0.264690,-0.020912,-0.453005,0.024797,0.279681,-0.055241,-0.154686,0.173688,0.455440,0.003681,0.733117,-0.106298,-0.188277,-0.583564,-0.123112,0.200803,-0.237761,0.233326,0.169804,-0.152511,0.787574,0.307173,-0.238252,0.046104,-0.039994,-0.165691,-0.376012,0.240830,-0.027981,-0.189767,-0.982572,0.403835,-0.244694,-0.007669,-0.114287,-0.479813,0.205315,0.671091,-0.500109,0.543114,-0.878745,0.181797,-0.454617,-0.001539,0.657373,-0.105321,0.182130,0.388014,0.269756,0.096703,-0.001840,-0.414003,-0.812209,0.618533,-0.028980,0.031689,-0.261413,0.236138,-0.481556,-0.320129,-0.423270,-0.159334,0.232679,-0.215828,-0.145701,0.111745,0.253164,-0.398231,-0.292204,0.145027,0.088875,-0.047335,0.807938,-0.398100,0.739691,0.127519,0.491272,-0.715992,0.698986,0.164309,0.405585,-0.224377,0.079537,-0.455386,-0.265787,0.092408,0.620814,0.152978,-0.064400,-0.278031,-0.432386,0.315696', '1291565', '1316513', '1306505', '3060325');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3014957', '一触即发', '剧情', '海军陆战队员杰克·帕特里克·赖恩（克里斯·派恩 Chris Pine 饰）是一个拥有强烈爱国情怀的热血男儿，在阿富汗执行任务期间，他所乘坐的直升机遭到敌人的炮火攻击，杰克也身受重伤，几乎殒命。康复期间，他与善良美丽的医学院学生凯茜·穆勒（凯拉·奈特莉 Keira Knightley 饰）相知相恋，与此同时他还被CIA官员托马斯·哈柏（凯文·科斯特纳 Kevin Costner 饰），伤愈后潜入华尔街，以分析师的身份监控每一个可能危害到国家安全地资金源。身份和任务极度机密的杰克对女友也要三缄其口，为此不得不承受各种莫名的质疑和猜测。某天，杰克发现俄罗斯可能正利用金融向美国发动潜在的恐怖袭击。为了查明真相， 他只身前往俄罗斯，谁曾想却置身于最危险的境地……©豆瓣', '克里斯·派恩', '肯尼思·布拉纳', 5.7, 31447, 'tt1205537', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2165631381.jpg', 4.9, 23.2, 55.2, 13.3, 3.4, '0.051741,-0.071739,-0.836023,0.508659,0.181589,-0.066811,0.519151,0.078029,-0.522537,-0.372818,0.352818,0.732374,0.028475,-0.133534,0.293986,-0.025920,-0.403665,-0.550087,-0.041307,-0.081556,-0.347689,-0.517371,-0.282781,-0.393203,-0.078101,-0.420939,0.510743,0.145896,-0.366817,0.278464,0.254642,0.736476,-0.048318,0.547373,0.161270,-0.252602,0.244564,-0.256497,-0.416446,0.400204,0.169654,-0.078383,-0.071026,0.283884,0.051660,0.284576,0.654839,-0.145494,-0.160398,-0.251978,0.148822,-0.495611,0.209042,0.181110,0.331475,-0.139535,0.093181,0.219300,-0.065877,0.129488,0.132245,0.082387,-0.801463,-0.144526,-0.064157,0.111537,-0.272950,0.049537,-0.416100,0.116055,0.034239,-0.325745,-0.050305,0.379920,0.017560,0.217478,-0.200405,0.099769,-0.338331,-0.120603,0.639253,-0.059863,-0.278451,0.015272,-0.310310,-0.444648,-0.045367,-0.288928,-0.422624,0.000082,0.258955,0.093555,0.060568,0.225301,-0.427223,0.055082,-0.612736,-0.255520,-0.204472,-0.303545,0.014092,-0.654354,0.064023,-0.259125,-0.491222,0.059529,0.191081,-0.059984,0.592928,-0.813592,0.224366,0.808733,0.368373,-0.570611,0.350692,0.252812,0.047064,-0.334241,-0.247340,0.400379,0.207951,0.317635,-0.190063,0.005672,0.165796,-0.232508,-0.007033,0.139864', '35073886', '1292849', '1307442', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30150727', '怪物先生', '动作', '有些奇怪的事情一直存在，你以为是巧合，或编个理由让它合理，其实，是因为你们不想承认……季末（春夏饰）从小就因为能看见“怪物”而被视作异类，直到有一天她在工作的超市再次看到“ 怪物” 并神奇的邂逅了“怪物猎人”——猛哥（余文乐饰），她才发现原来世界上真的有“怪物”存在，两个年轻人由此卷入了一场新的风波。', '余文乐', '黄智亨', 4.2, 10760, 'tt10097484', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2616835570.jpg', 23.2, 49.1, 22.9, 3.7, 1, '0.261601,-0.013627,-0.549763,0.155880,-0.255329,0.062498,0.735024,-0.354249,-0.906760,-0.453950,0.149899,0.619514,-0.209397,0.003892,0.099675,-0.055119,-0.005196,-0.413403,0.293294,-0.287192,-0.481519,-0.452533,-0.294492,-0.420689,0.215146,-0.398947,0.599718,0.224029,-0.283124,-0.054034,0.247388,0.220583,-0.136385,0.755518,-0.034781,-0.283085,-0.019556,0.387795,-0.104324,0.179077,-0.115853,-0.113545,-0.079719,0.230870,-0.390722,0.029177,0.431301,-0.477697,-0.644197,-0.074758,0.265118,-0.257492,-0.142397,-0.121583,0.474912,-0.450039,0.460954,-0.060575,0.106322,-0.005009,0.124056,0.089948,-0.507665,0.167114,-0.068966,0.210252,-0.241483,0.466386,0.251485,-0.348765,0.158109,-0.278269,0.222442,0.148971,0.986793,0.288458,0.026984,-0.183001,-0.507603,-0.023505,0.521839,0.012627,-0.395687,0.800806,-0.081379,-0.476902,-0.125090,-0.068987,-0.161498,0.497459,0.297834,0.269041,-0.593581,0.087927,-0.601437,0.109783,-0.108770,-0.149526,0.060175,-0.510542,-0.076434,0.199248,-0.006838,-0.124275,-0.429052,0.096488,-0.020174,-0.491273,0.388352,-1.005172,0.367837,0.859831,0.201814,-0.526595,0.689092,-0.119767,-0.322678,-0.403820,0.060033,-0.123455,-0.123415,0.212399,0.419570,0.172904,0.147648,-0.410158,0.077568,0.464280', '2052978', '3012033', '1292529', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30151048', '请寻找我', '惊悚', '闊別大銀幕14年，大長今李英愛強勢回歸，飾演一位瀕臨崩潰邊緣的母親，誓要尋回被擄走的兒子。兒子失蹤6年，赫然傳來疑是孩子下落的消息，母親決定隻身走到漁村，希望找出一個被黑道家族控制的小孩，查看他是否失散多年的兒子。奈何冷血的惡人想把孩子留下當生財工具，將她拒諸於門外。母親唯有在雷雨交加的晚上，以極端手段再闖虎穴。首次執導的金勝友，營造張力到家，描繪由心而發的暴力，教人觸目驚心', '李英爱', '金承宇', 6.6, 6569, 'tt8123618', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2572545171.jpg', 1.6, 8.4, 56, 26.6, 7.3, '0.472289,0.115858,-0.403082,0.279963,-0.461178,-0.140878,0.182946,0.046524,-0.620148,-0.266235,0.295467,0.698785,-0.023189,0.225741,0.173797,-0.066821,0.239018,-0.783454,-0.142756,-0.082230,-0.563829,-0.328917,-0.029848,0.024206,0.039315,-0.544489,0.577486,0.209087,0.141785,0.001830,0.163568,0.066200,-0.300022,0.330634,-0.519880,-0.151741,-0.219135,0.111563,-0.095229,0.467498,0.145132,-0.666495,-0.347084,0.311104,-0.009421,0.260815,0.790286,-0.260787,0.013477,0.059095,0.272891,-0.219509,-0.253160,0.196569,0.348178,-0.215969,-0.131975,0.573070,-0.279504,-0.215976,0.252247,-0.105934,-0.707848,0.104098,0.274299,-0.070194,-1.012699,0.409457,-0.353061,-0.067681,0.081870,-0.365046,0.279980,0.322580,-0.185917,0.689282,-0.267356,0.099175,-0.591696,-0.066870,0.533851,-0.283252,-0.019923,0.080665,0.263169,-0.377008,0.023315,-0.652008,-0.294175,-0.065318,0.486169,0.164861,-0.794331,0.004351,-0.592073,-0.194552,-0.407936,-0.169386,0.222717,-0.483283,-0.398624,-0.141532,-0.144264,-0.077446,-0.124124,0.379384,0.297292,-0.399334,0.747579,-0.646834,0.286264,0.734173,0.119113,-0.782702,0.960892,-0.285924,-0.060534,-0.246655,0.078770,0.188476,0.468814,0.328680,0.354366,0.244597,-0.484311,-0.248246,-0.315454,0.342172', '1877596', '1293607', '1306530', '6101834');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30153314', '白狮奇缘', '家庭', '11岁的女孩米娅（丹妮·戴·维利尔斯 Daniah De Villiers 饰）跟随着家人，从伦敦来到南非生活，居住在当地的一间农场里。离开了熟悉的家乡，非洲广袤的平原并未能够吸引米娅的注意，正相反，米娅无时不刻怀念着过去的城市生活。自从搬来这里，她稚嫩的脸庞上少了笑容，多了阴霾。某日，农场里诞生了一位新成员——一只名叫查理的小狮子。小狮子的到来让米娅重新找回了快乐，和查理一起生活的每一天，都有着新的惊喜等待着米娅去挖掘。然而，随着时间的推移，查理慢慢的长大，它的攻击性和危险性也与日俱增，为了保护米娅的安全，家人们不得不选择将这对好朋友隔离开来。©豆瓣', '丹尼·戴·维利尔斯', '吉勒斯·戴·迈斯特', 6.6, 4436, 'tt4844148', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2615303224.jpg', 2.1, 8.1, 56.5, 26.7, 6.7, '0.155234,0.077528,-0.631135,0.396444,-0.215299,-0.325787,0.892063,0.201927,-0.490280,-0.093605,-0.047656,0.777164,0.024348,0.515170,0.275614,0.375572,-0.689133,-0.420917,-0.111152,-0.418986,-0.166108,-0.242548,-0.458534,-0.291499,0.031445,-0.455686,0.405449,-0.022008,0.058912,0.824888,-0.085170,-0.027523,-0.210561,0.509745,-0.320174,-0.079850,0.069472,-0.149372,-0.294732,0.213625,0.004323,-0.013190,-0.090031,0.070245,0.330467,0.245582,0.818816,-0.143288,-0.066911,0.041852,0.303421,-0.087546,0.036307,0.061326,0.204101,0.141017,0.184505,0.270203,-0.391106,0.148526,-0.103805,-0.402820,-0.622895,0.205519,0.125875,0.215600,-0.570761,0.612523,0.140467,-0.402032,0.429495,-0.444667,0.452329,0.510018,0.010162,0.567202,-0.198518,0.392904,-0.224229,-0.079441,0.604954,-0.201399,-0.063386,0.251620,-0.410724,-0.263138,0.025843,-0.007886,-0.486786,-0.316977,0.142847,0.287729,-0.200255,0.203781,-0.903411,0.077190,-0.159569,-0.523744,0.181872,-0.350103,-0.262796,-0.641192,-0.052102,-0.610842,-0.107334,0.100976,-0.058302,-0.070901,0.847778,-0.801054,0.404441,0.644805,0.566116,-0.205781,0.605079,-0.123188,0.287314,-0.143254,0.090962,0.416244,-0.047030,0.601448,0.068118,0.334636,-0.166117,-0.065521,-0.600295,0.730966', '25785314', '5977789', '1419992', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30154537', '高潮', '剧情', '故事设定在1990年，聚焦一群舞者共同参加为期3天的排演，后却变为通往毒品的地狱之旅，麻木使得有些人感觉置身天堂，但大多数人却陷入地狱。', '索菲亚·波多拉', '加斯帕·诺', 6.5, 6711, 'tt8359848', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2531195804.jpg', 6.3, 16, 37.9, 26.4, 13.5, '-0.264101,-0.154893,-0.465161,0.288206,0.374734,0.165028,0.981921,0.108609,-0.947714,0.005091,0.331901,0.715652,-0.649245,0.093171,0.651405,-0.249183,-0.477100,-0.468173,-0.388159,-0.313669,-0.436885,0.046461,0.238091,-0.109450,0.269595,-0.407098,1.082574,0.481428,-0.308169,0.552288,-0.134313,0.125963,-0.223412,0.663429,0.012599,-0.625727,0.072798,0.204658,-0.009353,0.032830,-0.723793,0.355080,-0.669063,-0.005295,-0.330954,0.017556,0.769158,-0.736879,0.051447,0.074499,0.167348,-0.615123,-0.854740,-0.006254,0.144000,0.221787,-0.056528,0.053939,0.100388,0.249148,-0.190335,-0.207944,-0.990724,0.147386,-0.247332,0.402465,0.005357,0.293741,0.492301,0.775586,-0.574630,-0.417429,0.212398,-0.265106,0.742990,0.865083,-0.117958,-0.489581,-0.156846,0.009966,1.587315,-0.093847,-0.891446,0.436263,-0.437049,-0.806407,-0.228367,0.400187,-0.040326,-0.209321,-0.228717,0.311130,-0.503978,0.606426,-0.942812,0.199421,-0.011833,-0.756757,-0.160661,-0.562158,-0.517605,-0.671709,-0.384997,0.010311,-0.071790,0.054233,-0.004349,-0.315471,0.493208,-0.858010,0.624224,0.692950,-0.183798,-0.205218,1.147812,-0.209834,-0.135417,-0.140997,-0.393509,0.898787,0.012313,0.545386,-0.014938,0.041977,-1.085160,0.302834,-0.401862,0.524254', '25721544', '20443013', '25828589', '1307681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30156898', '肆式青春', '动画', '动画分为三个短篇。《一碗乡愁》：青年小明（坂泰斗 配音）独自一人离开故乡来到大城市北京打拼，掐指一算，他已经很久没有回去过了。某日，小明拖着疲惫的身躯去往上班的路上，忽然怀念起了家乡的味道。往事伴随着思念渐渐浮现。《霓裳浮光》：依琳（寿美菜子 配音）和璐璐（白石晴香 配音）是两个生活在广州的年轻女孩，无依无靠的她们相互扶持，将彼此视为自己的亲人。依琳曾经是一名红极一时的人气模特，但现如今，她能够很明显的感觉到自己的事业正在走下坡路。巨大的压力之下，她只有将情绪发泄到离自己最近的璐璐的身上，两人之间产生了隔阂。《纤雨初晴》：故事发生在1990年代的上海，李墨（大冢刚央 配音）和夏小雨（长谷川育美 配音）是青梅竹马的玩伴，两人的友谊一直持续到了中学时代。然而，当李墨离开了故乡去别的城市上学之后，这段友谊便画上了句点。©豆瓣', '坂泰斗', '李豪凌', 5.6, 28180, 'tt8176578', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2526429256.jpg', 7.2, 31, 42.4, 15.4, 4, '0.350598,-0.110420,-0.785113,0.429057,0.153471,-0.442085,0.630260,0.281140,-0.448447,-0.217402,0.207893,0.596869,-0.246947,0.794779,0.223798,0.026774,-0.126756,-0.790171,0.083903,-0.443154,-0.171947,-0.153445,-0.127831,-0.072784,-0.271665,-0.196285,0.598683,0.016822,-0.128735,0.448212,0.075364,-0.076333,-0.370702,0.523882,-0.363183,0.303336,0.098631,0.064736,-0.226520,0.169268,0.140835,-0.231246,-0.194585,-0.021579,0.131021,0.138816,0.885845,0.046741,-0.225309,0.125489,0.288052,-0.074359,-0.253784,0.041028,0.284914,0.139300,0.153709,0.138446,-0.194677,-0.007901,-0.194707,-0.249648,-0.274645,0.127701,-0.094367,0.253271,-0.653704,0.643814,0.015282,-0.419351,0.275869,-0.562835,0.316377,0.197416,0.072064,0.529210,-0.301653,0.318360,-0.399670,0.321602,0.856068,0.069025,-0.233471,0.448336,-0.245643,-0.164970,-0.361496,0.033948,-0.323359,-0.173854,0.176022,0.066757,-0.167649,0.077886,-0.661727,0.042602,-0.078895,-0.119616,0.171810,-0.289060,-0.000068,-0.446080,-0.316790,-0.678318,-0.334271,-0.040716,0.090316,-0.333103,0.853274,-0.848378,0.234688,0.685930,0.265288,-0.176588,0.362113,0.078980,-0.005384,0.010113,0.118527,0.321918,-0.455039,0.287007,0.162259,0.374411,-0.327819,0.273841,-0.516195,0.490179', '1292219', '1826173', '5977789', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30157153', '印度制造', '剧情', '帮助叔叔经营缝纫机店的青年茂吉（瓦伦·达瓦 Varun Dhawan 饰）乐观开朗，似乎特别乐意取悦他人。在叔叔儿子的婚礼上，茂吉嬉皮笑脸，哗众取宠，这令他的妻子玛姆塔（安努舒卡·莎玛 Anushka Sharma 饰）倍感羞耻和伤心。回到家后，玛姆塔闷闷不乐，以泪洗面，她劝丈夫利用自己裁剪方面的技能自力更生，不要屈辱求存。茂吉不愿重走裁缝爷爷昏暗的老路，可是他似乎也无法再忍受叔叔他们的戏谑。终于在一次争吵后，茂吉愤而辞职。偏偏此时，母亲一病不起。在妻子的鼓励下，茂吉不再踌躇，他决定经营自己的裁缝摊，从一点一滴做起。一直忙于家务的夫妻二人，也借此机会贴近彼此……©豆瓣', '安努舒卡·莎玛', '夏兰特·卡塔里亚', 6.7, 15821, 'tt7147540', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2531064347.jpg', 1.6, 8.8, 51, 31.1, 7.6, '0.080960,-0.112958,-0.643425,0.361541,-0.214780,-0.518776,0.478953,0.385826,-0.555259,-0.140390,0.378580,0.604786,0.154531,0.389096,-0.027525,0.126792,-0.465405,-0.479876,0.321294,0.116280,0.063795,-0.353133,-0.046717,-0.360866,-0.320370,-0.293459,0.394578,-0.134913,0.022222,0.240790,0.190037,0.004754,0.021705,0.434166,0.091852,0.049541,-0.060987,0.123117,-0.368440,-0.239548,0.174372,-0.029102,-0.177335,0.185045,0.398302,0.226307,0.604899,-0.204085,-0.267470,0.050746,0.225325,0.066832,0.129504,0.198890,-0.126712,-0.034564,0.218229,0.094936,-0.438524,-0.222868,-0.112787,0.060134,-0.362749,0.074719,0.235527,-0.247865,-0.756759,0.560510,-0.047496,0.145937,0.203665,-0.534991,0.038589,0.513092,0.122824,0.499488,-0.330764,0.239669,-0.154844,0.310093,0.474255,0.221324,-0.022445,0.394670,-0.275563,0.157115,0.279491,-0.433117,-0.716761,-0.183186,0.070241,-0.023379,-0.032862,0.248547,-0.221682,-0.114670,-0.197686,-0.001089,0.090325,-0.465318,0.049360,-0.184318,0.032152,-0.243019,-0.097725,-0.036935,-0.113791,-0.264579,0.438797,-0.762930,0.337109,0.295751,0.391460,-0.406125,0.518169,0.060340,0.162211,-0.444983,-0.229167,0.328107,-0.246763,0.110316,0.224804,0.227031,0.217466,0.182645,-0.337170,0.415813', '1299965', '1301221', '21354767', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3015835', '我的最爱', '爱情', '宝（邓丽欣 饰）本来与男友俊（黄嘉乐 饰）一起经营甜品店，生意兴隆，两人也感情稳定。可是宝多年不见的旧同学琪琪（曾恺玹 饰），竟抢走了俊，破坏了宝的幸福生活。另一方面，宝的好友蚊（唐宁 饰）常常对男友风（胡清蓝 饰）发脾气，当风结识了已有男友的敏（杨爱瑾 饰）后，两人展开了一段“后备恋情”。蚊与风最终分手收场。后来宝结识了老千阿强（方力申 饰），宝给了强十万块要他帮忙报复琪琪。强成功的把琪琪吸引住了，更想通过强骗取俊的甜品店。期间，宝与强也产生了感情。宝相信强的本质不坏，更相信他能改过自身。不料事情还是被琪琪发现了，她愿意出更多的钱买通强，要宝再一次在她面前难堪。宝纵使被俊抛弃，但当她得知俊被琪琪骗了之后，还是回到他的身边与他再次开创甜品店。而琪琪也强的精心安排下，同样被骗了所有的钱，更负债累累。强不再行骗，却遭到了黑帮报复……©豆瓣', '邓丽欣', '叶念琛', 7.6, 45208, 'tt1205065', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1015596190.jpg', 0.7, 3.3, 31.2, 46.6, 18.2, '0.112707,0.161348,-0.321775,0.347036,0.080054,-0.268713,0.302381,0.118021,-0.367498,-0.009735,-0.204983,0.717680,-0.264347,0.095056,-0.272670,0.193226,-0.016647,-0.659389,0.148160,-0.084809,-0.209414,-0.406305,-0.328346,0.223699,-0.184228,-0.125412,0.047270,0.054192,-0.283134,0.491804,0.518373,0.020413,0.056883,0.358067,-0.110818,0.212014,-0.032021,0.349258,-0.151973,0.094729,0.238925,-0.097626,-0.208647,0.202097,0.219271,0.163975,0.513006,0.140840,-0.417798,-0.001952,0.331787,-0.169851,-0.191003,-0.018330,0.123352,-0.057755,0.237293,0.230525,-0.295226,0.226591,0.287673,0.141503,-0.753060,0.320617,0.175158,-0.402375,-0.477139,0.356936,-0.020719,0.303633,-0.120316,-0.171466,0.133144,0.277770,-0.106081,0.219092,-0.349062,0.087924,-0.493462,0.170120,0.584786,0.117345,0.097418,0.400756,-0.156408,-0.085610,-0.085809,-0.343106,-0.211347,0.079461,0.509403,0.158215,-0.247332,0.080924,-0.623535,-0.344686,-0.313907,0.449100,0.005715,-0.286336,-0.057713,-0.297814,-0.298632,-0.466125,-0.331834,0.279770,-0.138168,-0.478804,0.807947,-0.745447,-0.019282,0.449318,0.660869,-0.747075,0.451712,0.037233,-0.188260,-0.046438,-0.126045,-0.098773,0.047960,0.142022,0.541756,0.189455,-0.108373,-0.336042,-0.219935,0.350179', '26678784', '4301278', '2428420