INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30158829', '我在你床下', '爱情', '影片改编自擅长禁忌题材的作家大石圭的同名小说，讲述不被任何人重视的三井直人与学生时代第一次喊自己名字的女生时隔十一年再会，但是对方却像变了个人，三井为了监视她潜藏在她床底，爱的疯狂加速了他暴走的进程。', '高良健吾', '安里麻里', 6.7, 7589, 'tt9855728', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2560029804.jpg', 2, 10.3, 49.4, 27.9, 10.3, '0.316586,-0.117690,-0.517670,0.510467,0.123703,-0.007557,0.543360,-0.017769,-0.700709,-0.232621,0.199259,0.818778,-0.232311,0.022556,-0.274291,0.288397,-0.113892,-0.671288,-0.035241,0.092237,0.093679,-0.051656,-0.105784,-0.402036,-0.340499,-0.363359,0.526569,0.048407,-0.597384,0.121268,0.110192,0.071089,0.251489,0.521807,0.183886,0.160138,0.001895,0.070923,0.179664,0.140184,-0.133059,-0.233774,-0.226158,0.414797,-0.141434,0.473950,0.370002,-0.188686,-0.176530,-0.139773,0.597390,-0.136352,-0.381489,0.307921,0.271796,-0.022385,0.355925,0.059881,0.245903,-0.018878,-0.279394,-0.153021,-0.648160,0.046650,0.331395,0.225878,-0.413218,0.661352,-0.491276,0.125905,0.096786,-0.217131,-0.177758,-0.225497,0.628601,-0.003814,-0.204245,-0.174081,-0.006524,0.482512,0.563453,-0.148550,-0.473810,0.476035,-0.387965,-0.290478,-0.655570,-0.318855,-0.540223,0.177309,0.465138,0.101139,-0.562758,0.287745,-0.372655,-0.026410,0.131266,0.002022,-0.110750,-0.497795,-0.389249,-0.354715,0.029772,-0.338512,0.087154,-0.192420,0.109997,-0.576422,1.124609,-0.768109,0.070628,0.959624,0.120743,-0.437688,0.579382,0.213318,-0.553943,-0.403229,0.190347,0.434622,-0.026462,0.344231,0.009910,0.359793,-0.019094,0.035446,-0.384933,0.538731', '27602116', '24284209', '3072064', '26790961');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30158971', '企鹅公路', '动画', '讲述了在一个原本百无聊赖的平凡夏天，一群企鹅凭空出现在远离大海的小镇之上。在目睹了牙医大姐姐所投掷的可乐罐变成企鹅之后，有着强烈好奇心的小少年青山同学决心一探究竟，并展开了一场不可思议而令人难忘的夏季冒险。本片改编自日本著名作家森见登美彦同名小说作品。', '北香那', '石田祐康', 7.6, 52291, 'tt8076344', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2555927320.jpg', 0.4, 3, 30.1, 47, 19.5, '0.383410,-0.098262,-0.698130,0.374523,0.227962,-0.081600,0.746891,0.298065,-0.216405,0.032034,0.346551,0.817859,-0.340596,0.301184,0.140473,-0.109364,-0.086711,-0.292349,-0.274005,-0.359576,-0.009866,-0.465162,-0.425328,-0.036037,0.363315,-0.286784,0.560507,-0.176060,-0.255520,0.430963,0.573069,0.061608,-0.429418,0.406268,-0.125035,0.022006,0.118201,0.153353,-0.199835,0.237280,-0.222336,-0.262440,-0.022820,0.103453,-0.101714,-0.024944,0.980567,-0.638864,-0.336608,-0.129394,0.457973,-0.209415,-0.291873,-0.020105,0.343018,0.321515,-0.114393,-0.376218,-0.141708,0.095074,0.175363,-0.313531,-0.345202,0.158549,0.128159,0.240563,-0.643255,0.454227,0.324713,-0.365653,0.287088,-0.396460,-0.126513,0.084073,0.162691,0.409027,-0.089565,0.098746,-0.169786,0.251858,0.606394,0.201630,-0.264082,0.568499,-0.170245,-0.083819,0.052873,0.067223,-0.463367,-0.086064,0.536376,-0.155943,-0.559382,0.320845,-0.673998,0.409248,-0.390307,-0.071768,-0.120961,-0.231268,-0.548643,-0.313026,-0.045220,0.002923,0.116248,0.132828,0.151972,-0.168365,1.018825,-0.596636,0.287685,0.722283,-0.096427,0.214064,0.422371,0.003469,-0.287961,0.045641,-0.002606,0.263520,-0.049668,0.460256,-0.030584,0.388363,-0.257754,-0.181186,-0.387376,0.215056', '21619567', '3811356', '4181031', '27069070');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30159390', '我的冠军男友', '剧情', '来自德国，球技非凡的帅哥里昂加入了瑞士职业球队，遇见了一头金发的马利欧。他们平日里一起训练、打闹，即便国籍不同，两人渐渐对彼此产生好感。然而他们暧昧关系引发了旁人的闲言闲语，甚至被恐吓威胁。初尝恋爱滋味的马利欧是否会为了爱情而放弃自己从小到大的理想？', '麦克斯·胡巴赫', '马塞尔·吉斯莱', 7.4, 10159, 'tt6999052', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2515187596.jpg', 0.8, 3.4, 35.8, 44.7, 15.4, '0.676837,0.038173,-0.722969,0.612827,-0.129565,-0.210727,0.459047,0.078918,-0.741807,-0.212687,0.059810,0.733327,-0.257585,0.118691,0.035348,-0.398570,-0.008166,-0.879952,0.028334,-0.035886,-0.209969,-0.469241,-0.337512,-0.143088,-0.177334,-0.165937,0.788405,-0.213438,-0.332811,0.666050,0.325198,0.370849,0.122731,0.507910,-0.094148,-0.122612,0.437410,0.431394,-0.386571,0.148163,0.030404,0.080691,0.024435,0.060857,-0.274147,0.125252,0.783951,-0.248232,-0.174779,-0.267734,0.428886,-0.034115,0.029021,0.416602,0.290609,-0.013337,0.429671,0.342436,0.292514,0.051664,-0.120356,0.227058,-0.376461,-0.021794,-0.005708,0.065960,-0.254249,0.506323,0.148252,-0.270307,0.131000,0.225889,0.187117,0.284284,0.594202,-0.007364,-0.265838,-0.079669,-0.565256,0.031940,1.220401,-0.048069,-0.455915,0.342368,-0.753489,-0.383962,-0.254568,-0.255501,-0.610066,0.064112,0.063411,0.279490,-0.216797,0.423321,-0.797423,0.334522,0.053439,0.080516,-0.093569,-0.480027,0.278627,-0.681310,-0.562743,-0.834108,-0.772485,-0.107938,0.180532,-0.053881,0.914709,-1.157560,-0.002277,0.611116,0.355469,-0.727469,0.673736,0.289159,0.045828,-0.321029,-0.354038,0.577428,-0.292446,-0.377219,-0.070123,0.248144,-0.142705,0.081596,-0.069469,0.408975', '35030151', '25721544', '1292219', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30159456', '再见十八班', '剧情', '梧桐中学高二十八班是远近闻名的问题班级，后进生、艺术生、体育生、不良少年聚集在此，以宋宸（柯焱曦 饰）为首的男生帮派和以秦淼淼（熊婧文 饰）为首的女生帮派互相不服，班级混乱无序。一天，高二十八班收到了一封信，这封信自称是由一年后的他们集体寄来。信上说，即将调来的班主任谭 睿明（秦海 饰）会改变十八班，成为对他们最重要的人。然而在一年后的未来，谭老师却永远地离开了他们。为了实现一段没有遗憾的青春，扭转历史，少年们决定按照信上所说，挑战一个个不可能实现的任务...', '柯焱曦', '禹岚馨', 6.5, 8729, 'tt7861446', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2515853287.jpg', 5.3, 16, 39.5, 25.1, 14.1, '0.198457,-0.186653,-0.515373,0.623805,-0.201243,-0.022576,0.347162,-0.117089,-0.489632,-0.145036,0.036054,0.577569,-0.038172,0.444210,0.284347,-0.359580,-0.079396,-0.609796,-0.150926,-0.593605,-0.447870,-0.698002,0.099828,-0.378444,0.000648,-0.140489,0.538260,0.099296,-0.116510,0.501582,0.405012,0.218808,0.118460,0.134153,-0.118983,-0.157624,0.083008,0.091307,-0.042294,0.150814,-0.064957,-0.050013,-0.453480,0.033043,0.144497,0.288836,0.632113,0.055017,-0.205849,-0.017099,0.468451,-0.255473,-0.354025,-0.086936,0.725586,-0.083308,0.103753,0.409035,0.119402,0.036900,-0.270179,-0.285065,-0.564617,0.032379,0.270107,0.017176,-0.630164,0.576475,-0.007971,-0.154174,0.197548,-0.202142,0.054926,0.538503,0.276584,0.302182,0.134224,-0.072424,-0.347088,0.379321,0.594481,-0.052068,-0.398595,-0.042674,-0.110513,-0.443435,-0.166637,-0.067230,-0.328488,0.390376,0.232195,0.224343,0.073484,-0.203251,-0.364254,-0.189644,0.043494,-0.243913,0.167929,-0.607516,-0.287587,-0.303361,0.119349,-0.095592,-0.265159,0.091860,0.076607,-0.202127,1.208738,-0.887387,0.096038,0.270831,0.330408,-0.724525,0.780209,0.149856,0.180216,-0.576094,-0.030918,-0.139532,-0.007145,0.447417,0.014952,0.288956,-0.128580,-0.253201,-0.266432,0.303966', '25922902', '1307741', '27602116', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30159567', '金都', '剧情', '《金都》以坐落于太子的金都商场为背景，商场以售卖廉价婚礼商品闻名，电影的主角莉芳在商场的婚纱租赁店工作，与另一婚礼摄影店的年轻东主Edward拍拖七年，Edward被视为莉芳的白马王子，结婚似是迟早的事，但原来莉芳有个不能结婚的秘密。「婚姻」一直被描绘为爱情的大团圆结局，三十开外的女性除了结婚生子，似乎没有出路。电影以太子的平民化婚庆圣地金都商场为背景，三十多岁的婚纱店员为了应付男友催婚，逼于处理早年为钱假结婚的烂摊子。每天都离不开婚嫁话题的她，如何选择自己的人生路向？', '邓丽欣', '黄绮琳', 7.7, 40057, 'tt11070230', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2574853860.jpg', 0.5, 1.9, 25.6, 56.2, 15.8, '-0.049709,-0.089060,-0.493894,0.511919,-0.053788,-0.419628,0.460808,0.110359,-0.061882,-0.604765,0.267461,0.719311,-0.120292,0.232232,0.330692,-0.039874,0.015032,-0.483811,-0.102833,-0.053112,-0.301168,-0.272400,0.134335,-0.109191,-0.096132,0.030718,0.670178,0.154724,-0.044510,-0.008880,0.674832,0.101202,-0.053705,0.156888,-0.125294,-0.427377,-0.092905,0.409358,-0.665180,0.040124,-0.278807,-0.050000,0.007956,0.057580,0.092607,0.423603,0.531675,0.169336,-0.048125,0.003221,0.685818,0.172738,-0.043660,0.099187,0.342599,-0.138283,0.264870,0.503811,-0.324033,-0.196405,0.176696,-0.212726,-0.831074,-0.192590,0.417717,-0.092623,-0.527312,0.442841,-0.171695,-0.016916,0.170902,-0.298574,0.147114,0.327264,0.536895,0.444481,-0.046337,0.382749,-0.858406,0.452048,0.688817,0.577708,-0.065897,0.446639,-0.287477,-0.276142,-0.095366,-0.372209,-0.493784,0.085493,-0.068910,-0.220301,-0.067846,0.302086,-0.424631,-0.309023,0.251142,-0.407149,0.647627,-0.433944,-0.315617,-0.638729,0.083710,-0.334862,-0.300797,0.058530,0.328776,-0.232782,0.594653,-0.601561,-0.114154,0.586683,0.248904,-1.170997,1.202125,0.236789,0.384276,-0.350266,-0.309232,-0.032063,-0.019131,0.189813,-0.018969,-0.048027,0.012371,-0.324915,-0.348547,0.603198', '26646649', '4301278', '25881781', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30159568', '手卷烟', '剧情', '退役华籍英军关超 (林家栋 饰) 加入黑社会维生，但近年经济不景，经常入不敷支。一天，南亚裔古惑仔文尼 (Bipin Karma 饰) 为躲避仇人，误闯关超家，文尼以三十万酬劳哀求他收留五天，关超欣然接受。另一边厢，关超早前促成了江湖老大大口泰 (袁富华 饰) 与台湾黑帮菜甫 (杜燕歌 饰) 的金钱龟走私交易，大口泰收货后竟发现货不对办，要关超交还一百五十万订金！文尼突然拿出一包毒品供关超换钱还债，事情像是完结之际，文尼竟又被大口泰的手下捉走！关超会自保逃走，还是冒险拯救这位相遇相知的新朋友？关超吸一口手捲烟，作出了最终的决定！', '林家栋', '陈健朗', 7.1, 21435, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2618359596.jpg', 0.6, 4.8, 43.8, 40.7, 10.2, '-0.039153,0.055891,-0.030680,-0.209781,0.271444,-0.301700,0.136817,0.028970,-0.075419,-0.229091,-0.065025,0.438415,-0.010431,-0.151853,0.255206,-0.126782,-0.002664,-0.586192,-0.089464,-0.200830,-0.214914,-0.187509,-0.220513,-0.205778,-0.061451,0.238849,0.266424,0.185210,-0.252340,0.639733,0.325883,0.097304,-0.109035,0.165511,-0.160860,-0.087533,0.079967,0.065701,-0.438411,0.164256,-0.084509,-0.268463,-0.113390,0.019399,0.422808,0.513365,0.456341,0.025172,-0.139147,-0.201863,-0.092655,-0.129949,-0.142578,-0.248708,-0.058330,0.257609,0.197142,0.198687,-0.267225,-0.034508,0.171482,-0.153032,-0.371587,-0.037623,-0.069305,-0.078109,-0.531821,-0.011432,-0.275161,0.437303,-0.047041,-0.132845,-0.031132,0.622884,0.295020,0.114547,0.001176,0.083758,-0.632281,0.374085,0.483033,-0.284200,0.295584,-0.042612,0.133672,-0.324805,0.420068,-0.301340,0.086938,-0.150155,0.202121,-0.152257,0.077047,-0.124544,-0.657603,-0.224752,-0.329455,0.085497,0.114065,-0.115224,-0.029136,-0.360319,-0.155135,0.003950,0.018549,0.201411,0.260409,-0.121428,0.368598,-0.034974,-0.027106,0.428207,0.495803,-0.521832,0.333099,0.100959,0.096926,-0.320442,0.125247,-0.040900,0.311303,0.238786,0.184417,-0.139193,-0.024452,-0.377192,-0.099475,-0.080155', '2209368', '35256235', '1293908', '2084048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30160393', '猛禽小队和哈莉·奎茵', '动作', '你听过一个有关警察、歌手、神经病和黑手党公主的故事吗？《猛禽小队和哈莉·奎茵》是一个只有哈莉·奎茵本人才能讲出来的超乎寻常的奇妙传奇。哥谭市最为凶残自大的恶棍罗曼·赛恩尼斯和他狂热的手下萨斯为了寻找一个年轻女孩卡斯，将这座城市翻了个底朝天。哈莉、女猎手、黑金丝雀和蕾妮·蒙托亚不期而遇，看似违和的四人组不得不团结一致、携手作战，才有可能打败罗曼。', '玛格特·罗比', '阎羽茜', 5.8, 91676, 'tt7713068', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2575974437.jpg', 7, 24.9, 44.7, 16.3, 7.1, '0.330762,-0.404025,-0.222814,0.615782,-0.313072,-0.273706,0.983154,-0.280212,-0.404737,-0.026630,0.179278,0.751145,-0.104036,-0.067797,0.422328,0.089583,-0.411963,-0.392175,-0.175971,-0.184438,0.004378,-0.763411,-0.558145,-0.078243,0.133923,-0.143243,0.387212,-0.298678,-0.034846,0.283388,0.351269,0.387353,-0.154583,-0.026141,-0.226663,0.078326,0.298520,0.036970,-0.223836,0.113893,-0.066054,0.384152,-0.109571,0.205597,-0.102563,0.114122,0.218626,-0.479922,0.039676,-0.135604,0.178938,-0.187141,-0.239928,0.063541,0.210009,-0.467876,0.353574,0.140376,0.430226,-0.306736,-0.063230,-0.041769,-0.864663,0.314015,0.057785,0.035273,-0.374407,0.329184,0.046597,-0.135074,0.413779,-0.179930,0.017046,0.144621,0.570060,0.262006,0.064638,0.212476,-0.437599,0.098065,0.425179,0.147325,-0.443796,0.093252,-0.057893,-0.498709,-0.054965,-0.243254,-0.406081,-0.001220,0.365291,-0.325927,-0.141604,0.204318,-0.810344,-0.146485,-0.291516,-0.135113,0.078408,-0.442032,-0.094960,-0.287705,-0.090679,-0.353714,-0.099061,0.088937,0.184357,-0.171214,0.916819,-0.694424,0.148587,0.648703,0.208085,-0.336716,0.239433,0.037357,0.027469,-0.246803,-0.080745,0.322015,0.250059,0.295936,0.207933,0.622393,0.043802,-0.258891,-0.284774,0.358373', '24284209', '3005387', '1308585', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30162520', '盛夏', '音乐', '这是一个关于摇滚、爱情和友谊的故事。列宁格勒，80年代初的一个夏天：摇滚音乐在当地风靡一时。Viktor Tsoï是位年轻的音乐家，就像其他年轻人一样，他也被齐柏林飞船和大卫·鲍伊的音乐所吸引，并尝试在摇滚乐坛上闯出一片名堂。一天，他遇到了偶像Mike和他漂亮的妻子Natacha。这次邂逅使他的命运发生了巨大转变。他们三人将一同写就Viktor的传奇，使他名留青史。', '刘台午', '基里尔·谢列布连尼科夫', 7.9, 11396, 'tt7342838', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2524209517.jpg', 0.5, 2.5, 24.1, 49, 23.8, '0.362266,-0.032145,-0.590976,0.655861,-0.163642,-0.012711,0.804642,0.021489,-0.406626,-0.002502,0.081851,1.238162,-0.470999,0.302492,0.213268,-0.046789,-0.139030,-0.993712,0.001405,-0.088169,-0.094215,-0.324371,-0.318097,0.096272,-0.046552,-0.291804,0.447254,-0.069307,-0.263997,0.374416,0.432181,-0.091826,0.026533,0.491542,-0.386401,0.159436,0.129362,0.353630,-0.145998,-0.085879,-0.224418,-0.352891,0.016987,0.107298,-0.354411,0.150311,0.578327,-0.191792,-0.147980,-0.051990,0.307662,-0.173399,-0.000999,0.060169,0.248986,-0.028875,-0.032985,0.223575,0.084920,-0.101448,-0.232270,-0.030463,-0.722027,0.094213,0.123161,0.090305,-0.552633,0.550323,0.134113,-0.120654,-0.050283,-0.144533,0.424128,0.192264,0.445542,0.316667,-0.127338,-0.054903,-0.523820,0.450362,0.985362,0.067998,-0.563142,0.431160,-0.396976,-0.448850,-0.348901,-0.159280,-0.453818,0.157160,0.341517,-0.253944,-0.066817,0.035510,-0.663822,0.046947,-0.091388,-0.277519,0.083149,-0.381552,-0.021074,-0.741022,-0.104793,-0.643853,-0.218862,-0.005695,0.206801,-0.316526,1.103532,-0.602500,0.270324,0.665665,0.116846,-0.385809,0.886523,0.076181,-0.037651,-0.143867,0.040321,0.163509,-0.126965,0.200451,-0.029634,0.661767,-0.062844,-0.041460,-0.336634,0.699119', '27602116', '3811356', '34890458', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30163500', '鬼影特攻：以暴制暴', '动作', '来自世界各地的六人，个个都是各自领域的佼佼者。他们之所以被选中，不单是因为能力出众，还在于其独特的志向：他们想抹杀自己的过去以改变未来。一位神秘的领袖（瑞恩·雷诺兹饰）将他们召集到一起组成了这个团队，他毕生唯一的使命就是确保即使他和自己的同伴会被遗忘，但也要让人们永远铭记他们所做的一切。', '瑞安·雷诺兹', '迈克尔·贝', 6.4, 33803, 'tt8106534', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2574329643.jpg', 4, 15.7, 46, 24.9, 9.3, '0.258491,0.108974,-0.915402,0.857386,-0.583517,-0.140774,0.545831,-0.217885,-0.453475,-0.362627,0.295019,1.091455,0.310138,0.219402,0.327830,0.110036,0.066430,-0.886126,-0.194257,-0.124808,-0.584981,-0.429305,-0.362351,-0.330966,-0.266624,-0.266243,0.861809,0.065983,-0.359427,0.026218,0.361910,0.314870,-0.157949,0.485974,-0.164719,-0.066657,-0.206730,-0.363818,-0.220042,-0.010648,-0.240118,-0.294935,-0.190879,0.596632,-0.388873,0.186424,0.514721,-0.355532,-0.258251,-0.116219,0.184043,-0.634815,-0.014406,0.263894,0.247572,-0.153661,0.170623,0.504676,-0.009782,0.040524,-0.008792,0.222934,-1.661461,-0.261235,0.430765,-0.048673,-0.761216,0.430760,0.303151,-0.493175,0.061259,-0.357344,0.171862,0.291774,0.119421,0.207814,-0.308659,-0.303966,-0.790794,0.249625,1.073847,-0.161297,-0.485362,-0.012420,-0.228057,-0.335089,-0.338612,-0.468655,-0.606471,0.256116,0.168066,0.509025,0.111891,0.194338,-0.583345,-0.026542,-0.207372,-0.425953,-0.023004,-0.855689,0.451154,-0.464047,-0.129856,-0.488004,-0.478674,0.039811,0.325186,-0.474789,1.369898,-0.887512,0.003014,0.803983,0.197326,-0.964154,0.716766,0.051254,0.551277,-0.140319,-0.192403,0.040707,0.400006,0.287873,0.050253,0.437963,0.324149,0.106903,-0.429962,0.654288', '26678784', '27602116', '24284209', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30163509', '飞驰人生', '喜剧', '曾经叱咤风云的拉力赛车手张驰（沈腾 饰），五年前因私自赛车而被禁赛。从天堂跌落谷底，张驰饱尝生活的艰辛。他忍辱负重，洗心革面，终于争取到了解禁的判决。在此之后，他重新找到亲如兄弟的领航员孙宇强（尹正 饰），决心共同冲击本年度的巴音布鲁克拉力赛。然而在此之前，张驰必须重考驾照，改装赛车，拉到赞助。每一步都充满艰难，他忍受着旁人的奚落嘲讽，忍受着现实的冰冷残酷，无论如何都不改变前进的目标。当他好不容易走到了赛场，还将面对禁赛这几年崛起的新秀林臻东（黄景瑜 饰）的挑战。张驰的时代是否就此远去……©豆瓣', '沈腾', '韩寒', 6.9, 860714, 'tt9597190', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2542973862.jpg', 2.2, 10.3, 41.3, 34.8, 11.4, '-0.172244,0.186974,-0.595308,0.411278,-0.005296,-0.488728,0.408401,0.118348,-0.190926,0.186968,0.680133,0.290806,-0.259756,0.007337,0.403922,-0.222514,-0.145828,-0.616966,-0.008368,0.048285,-0.340087,-0.342419,-0.145329,0.069103,-0.059845,-0.025144,0.981453,0.248163,-0.284884,0.370006,0.331324,0.206490,0.024263,0.409341,-0.244528,-0.119569,0.052277,0.208887,-0.291821,0.059047,0.010015,-0.434999,-0.312126,0.016503,-0.009280,0.355846,0.313155,-0.087098,-0.075432,0.048605,0.442303,-0.489487,-0.284576,0.066025,-0.061851,0.225638,-0.352635,0.571097,-0.076896,0.011992,-0.161043,0.005910,-0.586556,-0.067457,-0.049107,-0.127260,-0.698592,0.571267,-0.119548,0.067357,0.008045,-0.053241,-0.019714,0.277346,0.152721,0.217390,-0.193560,0.209884,-0.302429,0.342112,0.751020,-0.151474,-0.431351,0.094417,0.001815,-0.353735,0.090671,-0.501784,-0.560824,-0.077643,0.287091,0.309658,-0.322447,0.296800,-0.303401,0.135990,-0.247865,-0.402261,0.023835,-0.391845,-0.031840,-0.453655,-0.123848,-0.353617,-0.078731,0.131731,-0.093929,-0.434271,0.437090,-0.416833,0.251159,0.438425,0.155706,-0.378680,0.330954,0.008937,0.145596,-0.225541,-0.001490,0.649389,-0.172755,0.515208,-0.097252,0.272963,0.020494,0.274625,-0.453032,0.855725', '25827741', '25931618', '1297007', '30213339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30164448', '海市蜃楼', '科幻', '小男孩尼克（胡里奥·博希加斯 Julio Bohigas-Couto 饰）在一个风雨交加的夜晚目睹了邻居安吉尔（哈维尔·古铁雷斯 Javier Gutiérrez 饰）杀害自己妻子的场面。在和安吉尔的追逐之中，一辆车将尼克撞倒，导致了他的死亡。一晃眼多年过去，薇拉（阿德丽安娜·尤加特 Adriana Ugarte 饰）和丈夫大卫（阿尔瓦罗·莫奇 Álvaro Morte 饰）带着他们的女儿住进了尼克曾经居住过的房子。有一个电闪雷鸣的夜晚，薇拉意外的在电视里看到了尼克，让薇拉感到震惊的是，自己似乎能够通过电视和25年前的尼克对话。在薇拉的告诫之下，尼克免于一死，但过去的改变也牵连着薇拉的生活发生了巨变。大卫不再是薇拉的丈夫，而他们的女儿自然也不复存在。©豆瓣', '阿德里亚娜·乌加特', '奥里奥尔·保罗', 7.6, 349399, 'tt6908274', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2551172384.jpg', 0.3, 2.7, 29.1, 50.6, 17.3, '0.599694,-0.198575,-0.728196,0.513353,-0.248356,-0.076594,1.096070,0.247880,-0.327791,0.040116,0.558620,0.961685,-0.478607,0.396129,0.564504,0.267931,-0.393436,-0.991486,0.164012,-0.278834,-0.412007,-0.781437,-0.001954,-0.034745,0.062929,-0.351820,0.401364,-0.499577,0.257647,0.820036,0.154117,0.226894,-0.091079,0.630103,-0.133282,0.499451,-0.021022,-0.159725,-0.041917,0.207943,0.299683,-0.172643,-0.482978,0.324915,0.117009,0.422809,0.681064,-0.624380,0.247836,0.280937,0.188894,-0.264420,0.208841,-0.110266,0.237880,-0.384570,-0.017019,0.187930,-0.409028,-0.146359,0.262367,0.267150,-0.679116,0.544692,0.027100,-0.110299,-0.856555,0.336253,0.078658,0.188173,0.119603,-0.239875,0.282076,0.426560,0.046385,0.666159,-0.056166,0.132330,-0.487494,-0.188733,0.464471,-0.373958,-0.239221,0.596902,-0.457338,0.066261,-0.360364,-0.157303,-1.008796,-0.149371,0.596626,-0.114146,-0.270706,0.081937,-0.473661,-0.155162,-0.370150,-0.382449,-0.037829,-0.156524,-0.330370,-0.313469,-0.338531,-0.548512,-0.378839,-0.247816,-0.307366,-0.284194,0.444989,-0.601177,0.248479,0.355946,0.289687,-0.291576,0.868926,-0.057321,0.226114,0.248836,-0.095220,0.469503,-0.012253,0.260677,0.442419,0.420993,0.004644,0.053772,-0.306548,0.567215', '26809592', '1301582', '3111650', '1895119');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30164711', '咖啡未冷前', '剧情', '故事发生在一家从昭和时代就开始经营至今的咖啡店中，在这家咖啡店里有一个神奇的座位，坐在这个座位上的人能够回到他们想要回到的过去某一日，重温旧日时光，而时限就是一杯咖啡从滚烫到冷却的那么长时间。回到过去的人是无法干涉已经发生过的事情，亦无法改变未来，可即便如此，想要体验这神奇时刻的客人仍然络绎不绝。在感情和现实之中纠结无法做出选择的OL清川二美子（波瑠 饰）、一直过着形单影只的生活的平井八绘子（吉田羊 饰）、因为阿兹海默症而渐渐失去记忆的高竹佳代（药师丸博子 饰），每一个人的生命里，都有不惜代价想要回到的那一天。©豆瓣', '有村架纯', '冢原亚由子', 7.3, 7165, 'tt8315128', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2526785147.jpg', 0.9, 4.4, 39.3, 42.1, 13.3, '0.344983,0.490018,-0.931883,0.473831,-0.169979,-0.308769,1.133265,0.072753,-0.911816,-0.248202,0.127199,0.757646,0.023359,0.462668,0.547403,-0.069530,-0.296411,-0.838685,0.149650,-0.494402,-0.441028,-0.373311,-0.160920,-0.202100,-0.206387,-0.264887,0.636036,0.196193,-0.061688,0.228288,0.097164,0.122498,-0.154696,0.591251,-0.332945,-0.002337,-0.194558,0.304428,-0.532344,0.348650,0.280630,-0.423913,-0.203944,0.080421,0.176905,0.115295,0.739901,-0.430976,-0.591408,0.317761,0.346566,-0.088243,-0.336107,0.255247,0.309773,0.292229,0.079949,0.155338,-0.364904,0.341558,-0.066439,-0.039763,-0.980541,0.008450,-0.052815,0.483035,-0.752314,0.794777,0.100770,-0.222368,-0.065704,-0.633082,0.230943,0.306334,0.223890,0.445990,-0.353349,0.001415,-0.630464,0.031087,1.066619,0.064627,-0.468779,0.666907,0.040339,-0.238095,-0.223165,-0.267325,-0.470890,-0.026572,0.064704,0.574050,-0.280030,0.223663,-0.792898,0.443761,-0.095495,-0.464235,0.288436,-0.147552,-0.302646,-0.406614,-0.204836,-0.449737,-0.338315,0.347225,-0.067152,-0.465394,0.669709,-1.077697,0.266727,0.469303,0.282643,-0.286839,0.836133,0.032987,0.147648,-0.128332,-0.038797,0.466804,-0.236586,0.579936,-0.054183,0.379154,-0.143851,0.120385,-0.716422,0.483051', '1308755', '25721544', '1296370', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30165034', '昨日奇迹', '喜剧', '杰克（希米什·帕特尔 Himesh Patel 饰）是一个名不见经传的小歌手，除了他的好友艾利（莉莉·詹姆斯 Lily James 饰）以外，没有一个人相信他能够出名。一场意外中，杰克震惊的发现自己被传送到了某个平行世界中，在这个世界里，披头士未曾存在过，这也就意味着，杰克是这个世界里唯一知道这支乐队，听过他们的作品的人。于是，杰克开始表演披头士的歌曲，并且将它们占为己有，果不其然，这支历史上最伟大的乐队的歌曲很快就令杰克名利双收，他一举成为了当时全球最火的音乐创作人。然而，在最初的兴奋感平息之后，杰克发现，自己竟再也无法创作出属于自己的音乐了，只能沦为可怜的复读机，这显然不是他想要的结果，于是杰克开始想方设法寻找回到正常世界里的方法。©豆瓣', '希米什·帕特尔', '丹尼·博伊尔', 6.4, 14728, 'tt8079248', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2561245949.jpg', 1.5, 11.8, 56.1, 25.3, 5.3, '0.512784,0.437060,-1.086331,0.777369,-0.286030,-0.117480,0.789378,-0.285120,-0.839791,-0.132108,-0.046485,0.904170,-0.088597,0.332177,0.226277,0.122466,-0.351796,-0.739897,-0.014467,-0.503324,-0.201405,-0.374307,-0.543563,-0.399921,-0.186862,-0.304982,0.608490,0.131650,-0.310035,0.338841,0.400893,0.161989,0.225451,0.496413,-0.120428,0.372558,0.275989,-0.164477,-0.137722,0.318582,0.011871,-0.081244,-0.021427,0.480467,-0.296926,0.288516,0.663398,-0.592359,0.024311,0.047620,0.404993,-0.254418,-0.295439,0.039758,0.107154,0.041647,0.283155,-0.008586,-0.104693,0.232101,-0.024594,0.016422,-1.101987,0.164058,-0.034283,0.324924,-0.415553,0.308822,-0.233877,-0.184642,0.037770,-0.343954,0.519784,0.034278,0.647853,0.320833,-0.193081,-0.019593,-0.524223,0.317640,0.704695,-0.111452,-0.536104,0.567746,-0.160607,-0.493371,-0.213955,-0.373326,-0.393619,0.092606,0.356930,0.359368,-0.204607,0.030016,-0.587847,0.183184,-0.188010,-0.370928,-0.172280,-0.301722,-0.259354,-0.383035,-0.241909,-0.231033,-0.024726,-0.169920,-0.164491,-0.440034,0.853776,-0.907626,0.215304,0.571638,0.172729,-0.207113,0.698887,0.083343,0.106416,-0.196681,-0.154261,0.239828,-0.203433,0.364412,-0.000492,0.508025,0.200007,-0.350454,-0.498758,0.841946', '1793491', '25928048', '25932086', '1481233');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30165311', '坏蛋联盟', '喜剧', '故事的主角是五个无恶不作的坏蛋——风度翩翩的扒手“大坏狼”、见多识广的保险箱窃贼“贪心蛇”、冷静沉稳的伪装大师“美肚鲨”、暴躁易怒的打手“食人鱼”、伶牙俐齿的黑客专家“骇客蛛”闪亮登场，他们是最臭名昭著的“坏蛋联盟”。他们平时威风八面，四处作案，令人闻风丧胆。直到某一天，他们突然想成为模范公民，然而转型路途甚是艰难，且意外层出不穷，令人啼笑皆非。', '山姆·洛克威尔', '彼埃尔·佩里菲尔', 7.3, 131328, 'tt8115900', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2870318303.jpg', 0.4, 3.6, 39.5, 42.8, 13.7, '0.148410,-0.396611,0.003389,0.306737,-0.067042,-0.003236,0.712374,-0.334864,-0.853299,-0.124097,0.385871,0.178198,-0.377457,-0.195063,0.238022,-0.151407,0.139002,-0.154673,-0.085942,-0.014157,0.395005,-0.062359,-0.638356,-0.423237,0.118725,-0.205607,0.589693,0.234541,-0.158672,0.325456,0.365883,0.277670,-0.166690,0.036126,-0.364339,-0.368521,0.142270,-0.354922,0.082077,-0.385604,-0.278151,-0.005800,-0.093721,0.349485,-0.203696,0.127731,0.392403,-0.314149,-0.530280,-0.284760,0.532561,-0.439529,-0.465412,-0.058278,0.477640,-0.229114,0.316701,0.042940,0.496220,-0.259509,-0.131423,0.110209,-0.751139,0.208974,0.145195,0.213939,-0.221144,0.308058,-0.129579,0.244540,0.185061,-0.031368,0.026735,-0.256155,0.445985,0.172399,0.595399,0.198254,-0.370292,0.201525,0.276699,0.220373,-0.449898,0.197857,0.130316,-0.749703,0.373356,-0.827465,-0.205736,-0.004051,0.397437,-0.486828,-0.407408,0.454320,-0.604611,0.172549,-0.035173,0.055048,-0.245817,-0.211709,-0.421505,-0.293897,0.004813,-0.434016,-0.032954,0.219322,-0.233940,-0.020829,0.857031,-0.890791,-0.080097,0.677476,-0.309439,-0.375801,0.486548,-0.116910,-0.348647,-0.302360,-0.271975,-0.112653,0.422490,0.088624,0.020694,0.390176,-0.294573,-0.403411,-0.129040,0.218145', '24284209', '3005387', '3718665', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30166971', '测谎人', '喜剧', '浑水摸鱼、游戏人间的职业欺诈师左南（文章 饰）与徒弟马候（于洋 饰）因为一所老宅、一个社会黑哥（梁超 饰）与“鉴渣”测谎人马小凡（马丽 饰）相逢，原来左南与马小凡曾有过婚约。再聚首，左南因高僧（游本昌 饰）的催眠只能口吐真言，而马小凡因说实话而被网暴，这对落魄的欢喜冤家既要面对犯罪团伙的威胁又要在爱与谎言中寻找彼此内心的答案。', '马丽', '杨沅翰', 2.8, 16127, 'tt15245278', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2676943868.jpg', 69.1, 24.8, 5.3, 0.5, 0.4, '0.276614,-0.151536,-0.261677,0.659432,-0.011977,-0.090603,0.670927,-0.076397,-0.625286,-0.326598,0.011012,0.699683,-0.144509,0.339713,0.248980,-0.146955,0.076090,-0.520712,0.221830,-0.219956,-0.054481,-0.589113,-0.213689,-0.072966,-0.164165,0.034388,0.531642,0.234336,-0.393511,0.352947,0.433927,0.267935,-0.171277,0.118570,-0.184971,-0.129565,-0.052681,0.253413,-0.421275,-0.047291,0.089037,-0.191489,-0.103388,0.102501,-0.088957,0.091109,0.577643,-0.358330,-0.200216,-0.184187,-0.027183,-0.146510,0.124529,0.063097,-0.037428,-0.001229,0.484828,0.358793,0.156862,0.087656,0.091816,0.002780,-0.712203,0.025439,0.250402,-0.101147,-0.511186,0.444754,-0.182021,-0.146441,-0.151916,-0.040732,0.240825,0.184628,0.565227,0.294177,-0.367646,-0.360376,-0.516705,0.192435,0.194866,0.196167,-0.045212,0.293259,-0.150674,-0.520503,0.134768,-0.231945,-0.333718,0.181502,0.013083,0.016762,-0.179836,0.031000,-0.669524,-0.009917,-0.216308,0.393668,0.129306,-0.283621,0.030113,-0.326474,-0.102141,-0.583922,-0.314220,0.287939,0.312563,-0.054135,0.613547,-0.975689,-0.006064,0.130058,0.411170,-0.720080,0.572255,0.560452,-0.091777,-0.456045,0.007468,0.176610,-0.209514,0.153553,0.046910,0.200450,0.094570,-0.179296,-0.361804,0.138743', '1293265', '4301278', '1420088', '26730542');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30166972', '少年的你', '剧情', '陈念（周冬雨 饰）是一名即将参加高考的高三学生，同校女生胡晓蝶（张艺凡 饰）的跳楼自杀让她的生活陷入了困顿之中。胡晓蝶死后，陈念遭到了以魏莱（周也 饰）为首的三人组的霸凌，魏莱虽然表面上看来是乖巧的优等生，实际上却心思毒辣，胡晓蝶的死和她有着千丝万缕的联系。一次偶然中，陈念邂逅了名为小北（易烊千玺 饰）的小混混，随着时间的推移，心心相惜的两人之间产生了真挚的感情。小北答应陈念在暗中保护她免受魏莱的欺凌，没想到这一决定引发了一连串的连锁反应。负责调查胡晓蝶死因的警官郑易（尹昉 饰）隐隐察觉到校园里的古怪气氛，可他的调查却屡屡遭到校方的阻挠。©豆瓣', '周冬雨', '曾国祥', 8.2, 1401066, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2572166063.jpg', 1.3, 2.1, 16, 46.5, 34.1, '0.351812,-0.084429,-0.727900,0.621946,0.017523,-0.144035,0.720342,0.105124,-0.729922,-0.267362,-0.041942,0.414909,-0.563693,0.425719,0.260574,-0.284794,-0.005404,-0.714940,-0.214963,-0.078688,-0.390521,-0.415272,-0.181050,-0.054316,-0.206839,-0.001897,0.543591,0.376460,-0.251268,0.725246,0.268250,0.374317,-0.002600,0.608386,0.201192,-0.067283,-0.002321,0.025127,0.033259,-0.112202,0.278854,-0.374493,-0.102751,0.257258,0.004182,0.618137,0.655812,-0.124780,-0.164381,-0.032544,0.426253,-0.337365,-0.048602,0.189987,0.451533,0.297828,0.100422,0.146467,-0.311472,0.077985,0.243833,0.067050,-0.538693,0.144010,0.267300,0.103896,-0.389767,0.466588,0.096369,0.005069,-0.054591,0.049297,0.205083,0.294561,0.435578,0.246816,-0.102303,-0.065238,-0.047896,-0.031459,0.772875,0.043487,-0.339644,0.109566,-0.382191,-0.387465,-0.065123,-0.063484,-0.305299,-0.016135,0.322490,0.020049,-0.162835,0.174790,-0.389915,-0.164924,-0.070786,0.118224,-0.332173,-0.378511,-0.033033,-0.476911,-0.283163,-0.656709,-0.504711,0.115697,-0.010330,-0.325466,0.590261,-1.007059,0.051683,0.245063,0.206313,-0.411863,0.376320,0.087825,0.039673,-0.058087,-0.034198,0.129397,0.097499,0.122951,0.202550,0.345677,-0.094786,-0.173255,-0.125551,0.238532', '35030151', '1301022', '25810920', '1307186');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30167129', '荒城纪', '剧情', '故事发生在二十世纪三十年代的民国，山西一个偏远的小山村。村里的保长为了趋炎附势，把自己的女儿嫁给了县长的儿子，并从女儿口中辗转得知了一条旱涝保收的消息：在村里建个“李忆莲祠堂”，就可以获得县里拨发的巨额救济粮和银元。虽然不太明白县里的意思，但是贪财的保长立马勾搭了村里的族长，开始筹谋这桩买卖。', '李畅', '徐啸力', 6.8, 11076, 'tt8291232', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2521436620.jpg', 1.3, 9.9, 46.4, 33.9, 8.5, '0.561009,-0.057385,-0.542286,0.389946,-0.384220,-0.220562,0.301669,0.155059,-0.567525,-0.059311,0.027303,0.853236,0.135457,0.258664,0.133221,0.273979,0.122329,-0.205944,0.025896,-0.378992,0.072036,-0.628575,-0.023221,-0.266103,-0.176122,0.100741,0.314987,0.239584,0.030335,0.183986,0.331576,0.049139,0.144273,0.196878,-0.631760,0.140582,0.062182,0.220353,-0.204582,-0.071199,-0.048774,-0.283485,0.016373,-0.045350,0.376667,0.553290,0.513597,0.016716,-0.192787,0.060276,0.224613,0.159604,-0.041651,0.111756,0.547764,0.088340,0.386748,0.668161,-0.252320,-0.215805,-0.042349,-0.200458,-0.474658,0.156415,0.232984,0.120296,-0.751946,0.180487,0.048741,-0.114384,-0.140183,-0.581726,0.555025,0.657097,-0.078453,0.711194,-0.517965,0.011746,-0.865516,0.519605,0.471466,-0.370648,-0.103286,0.331343,0.019045,-0.587766,0.368388,-0.114252,-0.443923,0.093502,0.144317,-0.198746,-0.526235,0.044129,-0.413976,-0.044344,-0.130670,-0.453292,0.393324,-0.382765,-0.389905,0.058611,-0.337356,-0.165999,-0.101864,0.051588,0.495260,0.057488,0.525002,-0.491161,-0.090819,0.506864,0.351268,-0.725912,0.550569,0.088800,0.283245,-0.354132,0.054822,-0.389436,0.143649,0.483641,0.070869,0.135341,-0.159692,-0.792081,-0.010712,0.549955', '3430271', '26647117', '1303637', '3215099');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30167633', '谎言大师', '剧情', '海伦·米伦与伊恩·麦克莱恩即将出演新线的剧情片《The Good Liar》（优秀的骗子，暂译）。影片将由比尔·康顿执导，他最近的作品，就是在全世界狂揽12亿美元的《美女与野兽》。在影片中，伊恩爵士饰演一名职业骗子，当他遇到海伦·米伦饰演的富裕寡妇时，简直不敢相信自己的运气。这位寡妇把自己的生活和家门都向骗子打开，骗子却发现自己是真的关心她，让这笔本该骗了就撤的买卖，变成了像走钢丝一样的危险关系。', '海伦·米伦', '比尔·康顿', 7.2, 16289, 'tt5563334', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2560819247.jpg', 0.5, 3.7, 43.7, 41, 11.2, '0.284493,-0.163324,-0.546870,0.477154,-0.262846,-0.414399,0.794981,-0.011188,-0.196367,-0.090334,0.300295,1.132738,-0.257259,-0.040410,0.290036,0.303842,-0.194142,-0.824293,-0.299425,-0.155995,0.189572,-0.365412,-0.523225,-0.102927,-0.028948,-0.429473,0.652453,-0.167056,-0.425265,0.238565,0.565908,0.413887,0.074182,-0.035594,-0.111041,0.212556,0.241628,0.102846,-0.233221,0.424521,0.007460,0.104500,-0.057599,0.014398,-0.060906,0.380238,0.412000,-0.235913,-0.234754,0.150786,0.415551,-0.441537,0.060386,0.055511,0.101610,-0.221306,0.385881,0.064115,-0.054623,0.145181,0.101863,-0.273862,-0.888262,0.068357,0.192579,0.023990,-0.776439,0.166067,-0.174168,-0.080718,0.227513,-0.122132,0.237256,0.013357,0.259486,0.548391,-0.092777,0.254742,-0.497906,0.370849,0.387778,0.194042,-0.317176,0.587021,-0.164684,-0.369647,-0.160917,-0.334013,-0.680095,0.224347,0.304062,-0.237670,-0.209316,0.262734,-0.525063,-0.031454,-0.172213,0.022427,-0.081373,-0.270772,-0.134960,-0.355021,-0.032956,-0.378517,-0.164553,-0.127409,0.093123,-0.420772,0.615591,-0.606296,0.099130,0.744961,0.312515,-0.444488,0.883173,0.070334,-0.140630,-0.075490,-0.099774,-0.070503,0.197293,0.234820,0.276690,0.324978,0.007436,-0.324998,-0.218690,0.846301', '34890458', '30162520', '1292207', '1292925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30167974', '浪客剑心 最终章 人诛篇', '剧情', '明治维新运动后十二年，日本迎来了新时代。曾经叱咤风云的刽子手绯村剑心如今已成为和平主义者，与朋友们一起在东京过着平静的生活。一天晚上，剑心最喜欢的餐厅遭到炮火袭击，只留下一张写着“人诛”的字条——有人准备替天行道，审判之日近在眼前。此人名为雪代缘，对剑心怀恨在心，带着一众手下前来复仇。目睹无数无辜之人被牵扯进这场残酷的斗争，剑心终将面临一场审判，并由此找到对过去的救赎。', '佐藤健', '大友启史', 7.6, 29943, 'tt11809034', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2627551613.jpg', 0.8, 3.8, 32.3, 42.3, 20.8, '-0.157067,0.208934,-0.466850,0.233921,0.061528,-0.071331,0.680578,0.083818,-0.348278,-0.404234,0.334919,0.541627,-0.117420,0.358703,0.605940,-0.219445,-0.151635,-0.744362,-0.393141,-0.230356,-0.277113,-0.089153,0.038702,0.144762,-0.217680,-0.253612,0.608180,0.372622,-0.041433,0.459789,0.355905,0.301694,-0.165832,0.491459,-0.280703,-0.258811,-0.199092,-0.079170,-0.602346,0.132951,-0.000617,-0.291230,-0.434087,0.220610,-0.454482,-0.174846,0.696067,-0.345539,-0.125162,-0.557767,0.370742,-0.362618,-0.217691,0.393443,0.510295,0.499121,-0.046562,0.344473,-0.042422,0.045417,-0.043074,-0.187914,-0.770783,-0.076352,-0.167972,0.043712,-0.387914,0.580643,-0.103664,0.141719,0.026045,-0.113718,0.320849,0.326976,0.349603,0.221907,-0.217449,-0.033132,-0.317745,0.073228,1.079022,-0.244775,0.139773,-0.035395,0.270437,-0.114401,0.201915,-0.310789,-0.331026,0.129577,0.408181,-0.040082,-0.113978,0.506534,-0.747521,0.104407,-0.286983,-0.203826,0.426896,-0.324208,-0.143964,-0.686473,-0.082826,-0.040748,-0.253578,0.515448,0.096036,-0.137947,0.859429,-0.653789,0.604448,0.389230,0.206324,-0.398542,0.468251,0.385119,0.194486,-0.067675,-0.062230,0.460734,0.327027,0.525367,0.010650,-0.042682,-0.108804,0.131023,-0.244325,0.538186', '25828589', '11541282', '25721544', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30168032', '战斗民族养成记', '喜剧', '当“上海女婿”遇上“俄罗斯岳父”，到底会上演一段怎样的乌龙奇遇？由高分神剧《战斗民族养成记》原班人马共同打造的同名喜剧电影，讲述了一段上海小伙彭鹏为了追求真爱远赴俄罗斯，攻略彪悍岳父大人的异国奇遇。他将如何面对伏特加酒局、冬泳、射杀狗熊等一系列爆笑考验，令人期待…', '董畅', '阿卡季·萨赫拉什维利', 4.7, 7521, 'tt9387352', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2546069661.jpg', 21.9, 35, 34.4, 5.7, 3.1, '-0.239247,-0.391717,-0.192686,0.284197,0.139325,-0.011310,-0.127316,-0.293419,-0.355457,-0.257556,0.513088,0.470944,-0.350933,-0.099541,0.499969,-0.468715,0.059265,-0.465590,0.010678,0.198157,-0.003210,-0.199012,-0.406402,0.015654,0.140527,-0.133993,0.414689,0.029290,-0.206799,-0.023078,0.581992,0.345062,-0.247936,-0.138173,-0.129705,-0.269876,0.239696,0.386347,-0.656759,0.074261,-0.013627,-0.172795,-0.083788,-0.068730,-0.064572,-0.105440,0.508574,-0.172618,-0.046188,-0.439990,0.470414,-0.076103,-0.075312,-0.150899,0.152187,0.211004,0.105386,0.403432,0.122859,-0.428253,-0.243971,-0.181602,-0.330830,0.074912,0.238156,-0.182424,-0.378103,-0.218380,0.263204,0.094728,0.315277,0.017601,-0.084691,0.644238,1.056674,0.530258,0.118284,0.316176,0.103662,0.466916,0.790269,-0.476356,0.056784,-0.007703,0.051141,-0.181461,0.550555,-0.526067,-0.541513,0.319173,-0.048516,-0.191476,0.009748,0.204175,-0.317588,-0.130594,-0.472929,0.000683,0.316889,-0.495817,-0.158921,-0.570571,0.043606,0.097262,0.161096,-0.147966,0.487194,-0.228802,0.787106,-0.203128,-0.351450,0.482849,-0.119618,-0.665815,0.311052,0.473539,-0.246172,-0.446049,0.194411,0.176711,-0.078144,-0.253936,-0.390373,0.107009,0.122974,-0.138004,-0.162211,0.430748', '26790961', '26857654', '1291546', '4301659');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30170375', '真爱百分百', '喜剧', '乔斯兰（弗兰克·杜波斯科 Franck Dubosc 饰）是一位非常富有的商人，凭借着自己有两个臭钱，他整日流连于不同的女人身边，可谓是万花丛中过，片叶不沾身，女人对于他来说，不过只是玩物而已。一天，乔斯兰家隔壁新搬来的女邻居吸引了他的注意，为了博得对方的好感迅速拉近距离，乔斯兰伪装成了一名残疾人，哪知道邻居家中竟然有一位真的身患残疾的姐姐弗洛伦斯（亚历山德拉·拉米 Alexandra Lamy 饰）。在一来二去之间，乔斯兰发现弗洛伦斯无论是言谈举止还是处世哲学，都深深的令自己折服，他第一次对一个女人产生了心动的感觉。与此同时，乔斯兰也知道，如果自己装残疾的事情被拆穿，那么他和弗洛伦斯之间的关系就将走到尽头。©豆瓣', '弗朗克·迪博斯克', '弗朗克·迪博斯克', 7.4, 13397, 'tt6838702', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2555646002.jpg', 0.2, 2.6, 37.6, 45.2, 14.4, '0.505897,-0.163697,-0.492515,0.636889,-0.435506,-0.198337,0.819199,-0.050664,-0.514718,-0.457247,0.131852,0.756318,-0.260807,0.183641,0.356913,0.069615,0.104271,-0.697082,-0.109676,-0.444621,-0.437186,-0.438879,-0.580792,-0.176242,-0.290430,-0.141886,0.304049,-0.068170,-0.427455,0.506291,0.555299,0.310706,0.126315,0.664148,-0.266404,-0.051671,-0.130179,0.115517,0.010037,0.064783,0.050928,-0.183572,0.057053,0.086417,-0.068478,0.452620,0.498608,-0.223902,-0.073410,-0.078893,0.274084,0.256869,0.005805,0.105223,0.356296,-0.125298,0.212589,0.070345,-0.258323,-0.084797,0.399899,0.042361,-0.674472,0.056993,0.076814,0.012199,-0.639025,0.289675,0.256586,-0.377083,0.105959,-0.167224,0.223277,0.203202,0.307092,0.366852,-0.141724,-0.095988,-0.703428,-0.218423,0.761774,0.132704,-0.204006,0.564667,-0.231603,-0.444716,-0.078636,-0.304693,-0.290205,-0.073964,-0.099630,0.029171,-0.058813,0.118210,-0.446690,0.166569,-0.096433,0.083531,-0.175094,-0.664495,0.056666,-0.113817,-0.202365,-0.534386,-0.407966,0.175239,0.110762,-0.500681,0.808926,-0.864066,0.205557,0.544068,0.387876,-0.633694,0.989886,0.242912,-0.053653,-0.299779,-0.420035,0.339198,0.224125,-0.028833,0.100796,0.389224,-0.344082,-0.277283,-0.074470,0.637115', '3230462', '3055049', '1456503', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30170448', '何以为家', '剧情', '法庭上，十二岁的男孩赞恩向法官状告他的亲生父母，原因是，他们给了他生命。是什么样的经历让一个孩子做出如此不可思议的举动？故事中，赞恩的父母在无力抚养和教育的状况下依然不停生育，作为家中的长子赞恩，弱小的肩膀承担了无数生活的重压。当妹妹被强行卖给商贩为妻时，赞恩愤怒离家，之后遇到一对没有合法身份的母子，相互扶持勉强生活。然而生活并没有眷顾赞恩，重重磨难迫使他做出了令人震惊的举动……', '赞恩·阿尔·拉菲亚', '娜丁·拉巴基', 9.1, 971246, 'tt8267604', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2555295759.jpg', 0.2, 0.4, 5.5, 34.1, 59.9, '0.123091,0.017771,-0.737800,0.631016,-0.445346,-0.014640,0.847055,0.214959,-0.620068,-0.224595,0.404503,0.888319,0.019611,0.268465,-0.028035,-0.108199,0.011033,-0.742365,-0.014806,0.250396,-0.384146,-0.575188,-0.070622,-0.121414,-0.255466,-0.339031,0.657544,-0.102966,-0.189924,0.302652,0.257128,0.419813,0.147977,0.396198,-0.535952,0.164361,0.046896,0.346696,-0.249524,0.031694,0.001959,-0.458340,-0.150132,0.320247,-0.182202,0.421413,0.695176,-0.361357,-0.500430,-0.403308,0.362548,-0.397176,0.025288,0.356837,0.180386,0.007845,0.318023,0.125458,-0.223266,-0.239955,0.263386,-0.109815,-1.012677,-0.086378,0.216301,0.008018,-0.961242,0.435375,-0.116859,-0.168081,0.135876,-0.272768,0.222907,0.459337,0.395555,0.592297,-0.588070,0.095154,-0.221459,0.002299,0.877646,-0.054784,-0.589059,0.361299,-0.876514,-0.281028,0.247778,-0.689096,-0.726603,0.107361,0.028340,0.287767,-0.496488,0.538878,-0.166433,-0.046839,-0.407045,-0.265748,0.142635,-0.717148,-0.068720,-0.143725,-0.353960,-0.556413,-0.463368,-0.009016,-0.007225,-0.497557,0.743605,-0.568243,0.179585,0.376208,0.565434,-0.681222,0.715784,0.282574,0.308385,0.049467,0.228832,0.127710,0.012467,-0.011546,0.059702,0.013460,0.158493,0.259488,-0.112332,0.555377', '26678784', '6745433', '30163500', '34875369');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30170546', '乔乔的异想世界', '剧情', '二战时期，男孩乔乔(戴维斯)和母亲(斯嘉丽)生活在纳粹德国统治下，他不知道母亲在家中藏着一个犹太女孩(麦肯齐)，而母亲秘密为抵抗军工作。乔乔渴望加入希特勒青年团，他脑内出了一个颠覆版的希特勒，这个希特勒有魅力、傻傻的、天真可爱，是他的朋友，帮助他应付生活中的困境。', '罗曼·格里芬·戴维斯', '塔伊加·维迪提', 8.3, 316607, 'tt2584384', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2567973073.jpg', 0.3, 1.5, 15.4, 49.2, 33.7, '0.100748,0.084974,-0.672013,0.631391,-0.518978,-0.017839,0.850540,-0.064056,-0.349159,-0.354339,0.266266,0.774540,0.452498,0.427004,-0.025048,0.287685,-0.431861,-0.655571,0.138735,0.173567,0.091996,-0.584511,-0.506680,-0.554400,-0.167184,-0.305176,0.832476,0.139541,-0.147832,0.111996,0.094478,0.317967,0.243396,0.578259,-0.297683,0.120334,0.270130,-0.114229,-0.134515,0.212083,-0.028302,-0.195044,-0.156296,0.348020,-0.032097,0.219782,0.507593,-0.400949,-0.091152,-0.177260,0.157214,-0.414342,-0.358471,0.216009,0.086317,-0.227496,0.018547,-0.100539,-0.175496,-0.090203,-0.096683,-0.141165,-0.516136,-0.317154,0.040294,0.204768,-0.687712,0.466407,-0.284366,0.089610,0.292751,-0.426279,0.051735,0.613973,0.008508,0.574401,-0.269550,0.350073,-0.593854,0.276789,0.770347,-0.276459,-0.200639,0.264320,-0.802636,-0.206790,-0.076645,-0.291881,-0.849503,-0.258692,-0.143524,-0.519251,-0.239285,0.375083,-0.364093,0.114151,-0.168322,0.140547,-0.040859,-0.620401,-0.202920,-0.139959,-0.490804,-0.284269,-0.319661,-0.133644,-0.136315,-0.231674,1.218149,-0.943775,0.133068,0.748747,0.459468,-0.627947,0.771112,0.530767,0.058755,-0.400248,0.224612,0.583575,-0.246201,-0.263074,-0.199194,0.383943,0.101410,0.238423,-0.237099,0.272140', '26348103', '25882279', '3445516', '6963575');
