INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30171424', '拆弹专家2', '动作', '香港某处发生爆炸案，前拆弹专家潘乘风（刘德华 饰）因昏迷于现场，被警方怀疑牵涉其中。苏醒后的潘乘风只能一边逃亡一边查明真相，然而，他的好友董卓文（刘青云 饰）和他的前女友庞玲（倪妮 饰）却给他讲述了两段截然不同的经历。有计划的爆炸案接二连三发生，真相却越来越扑朔迷离……', '刘德华', '邱礼涛', 7.5, 538667, 'tt9597838', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2621379901.jpg', 0.6, 3.6, 31.8, 50.5, 13.6, '0.367443,-0.099668,-0.752782,0.270485,0.526430,-0.138026,0.951689,-0.154250,-0.641553,-0.550421,0.277060,0.198174,-0.535047,-0.028960,0.336711,-0.502981,-0.373086,-0.918044,0.053229,0.133898,-0.244660,-0.515044,-0.284647,0.066863,-0.264309,0.307386,0.342033,0.364075,-0.363827,0.317517,0.295869,0.547750,-0.426512,0.664034,-0.051113,0.464453,0.068752,0.211894,-0.237457,-0.070587,0.640567,-0.781488,-0.136242,0.298276,0.032655,0.426334,0.781205,-0.084739,-0.263599,-0.120934,0.491804,-0.211312,0.047787,-0.073014,0.378945,0.535098,-0.014903,0.302255,-0.104506,-0.356453,0.131028,0.224512,-0.624571,0.179870,0.222554,0.445163,-0.054094,0.044127,-0.339745,0.462918,0.134040,-0.329341,0.337230,0.516100,0.564326,-0.000401,-0.075558,-0.206558,-0.609310,0.445387,0.675550,0.216148,-0.153080,0.160438,-0.253281,-0.327351,-0.170910,0.150322,-0.215990,0.299054,0.565157,0.140493,-0.240493,0.387662,-0.071171,-0.247184,-0.264067,-0.168983,-0.426430,0.029692,-0.088232,-0.562875,-0.300703,-0.484504,-0.151302,-0.204330,-0.187780,-0.200189,0.139502,-0.415249,0.297802,0.200357,0.148663,-0.524883,0.134057,0.150830,0.256522,-0.168188,0.050064,0.276770,-0.016924,0.207336,0.149672,0.183768,-0.004425,-0.264448,-0.367554,-0.026001', '3011051', '21348112', '1773217', '4023433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30171425', '扫毒2天地对决', '剧情', '毒品市场维持四分天下的格局已久，但自从地藏与墨西哥大毒枭跨境合作扩展势力，再加上一连串黑吃黑的动作，毒界变得风声鹤唳。另一方面，因儿时亲眼目睹父亲被毒品所毁而嫉毒如仇的慈善家兼金融巨子余顺天，正悬赏一亿歼灭香港最大毒贩，此举在社会上引起轩然大波。警员林正风本致力搜证拘捕地藏，毒贩却因巨额悬赏导致人身安全受威胁，他在执行保护毒贩的任务时深感无奈，但又被余顺天的出价所诱惑，陷入黑白正邪的心理挣扎。原来，余顺天和地藏有不可告人的同门关系，一场天地对决一触即发。', '刘德华', '邱礼涛', 6, 238193, 'tt8239806', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561172733.jpg', 3.1, 20.7, 55.4, 16.6, 4.1, '0.108257,0.074775,-0.563793,0.359660,0.389775,-0.062343,0.368428,0.350111,-0.856533,-0.259188,0.188868,0.425491,-0.267222,-0.130072,0.122915,-0.381939,-0.146431,-0.476544,-0.315486,0.077624,-0.044149,-0.389208,-0.239078,-0.330771,-0.277849,-0.223727,0.834799,0.566759,-0.538240,0.151564,0.133931,0.375800,-0.275016,0.336005,0.062527,-0.285966,0.042502,0.085388,-0.492714,0.084923,-0.187977,-0.508503,-0.261451,0.009482,0.068040,0.564086,0.550808,-0.188342,-0.178453,-0.227298,0.493625,-0.555701,-0.190596,-0.138856,0.249672,0.214787,0.112209,0.215959,-0.517692,0.089942,0.302397,0.018313,-0.770726,-0.090743,0.307875,-0.076000,-0.184917,0.463495,-0.228091,0.021140,-0.249490,0.064918,0.105190,0.651989,0.340866,0.135563,0.002644,0.123822,-0.403842,-0.160780,0.777239,-0.113256,0.049215,-0.233994,-0.079560,-0.548686,-0.265577,-0.418967,0.038703,-0.304381,0.296908,-0.111818,-0.105537,0.536134,-0.384640,-0.075839,-0.432280,-0.134784,-0.234850,-0.140416,-0.277917,-0.565338,-0.331159,-0.231353,0.023824,0.048040,0.414777,-0.199457,0.368321,-0.562188,-0.045814,0.587040,0.232542,-0.575973,0.284234,0.325439,0.041521,-0.401353,-0.582670,-0.028152,0.116329,0.160601,0.322856,-0.375326,-0.257146,0.051337,0.381180,0.057673', '4767216', '4133814', '1293265', '1307694');
