INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30172751', '一百样东西', '喜剧', '安东尼（马提亚斯·施维赫夫 Matthias Schweighöfer 饰）和保罗（弗洛里安·大卫·弗里茨 Florian David Fitz 饰）是从小玩到大的青梅竹马，两人共同经历了太多的事情，彼此之间的友谊坚不可破。成年之后，他们一起创办了一家公司，这一天，公司觅得了一名非常慷慨的投资人，为了庆祝这件事情，公司里开设了一场盛大的派对，在派对上，玩的兴起的安东尼和保罗决定打一个赌，赌注是公司百分之五十的股份。安东尼和保罗交出了身上所有的东西，两人回归到身无分文的状态，然后每一天，他们都可以在他们所拥有的东西里拿回一件，如此往复，看谁能够撑更长的时间，先放弃的人就是输家。©豆瓣', '弗洛里安·大卫·菲茨', '弗洛里安·大卫·菲茨', 7.3, 13063, 'tt8129794', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2540250054.jpg', 0.7, 4.6, 37.2, 41.7, 15.8, '0.212618,0.001894,-0.632315,0.372425,-0.173180,-0.399476,0.389896,0.169164,-0.393050,-0.195896,-0.009625,0.891812,-0.296444,0.448469,0.287314,-0.102492,-0.317055,-0.738163,0.069607,-0.442766,-0.343015,-0.419654,-0.083989,-0.287332,-0.213136,0.202092,0.378318,0.051082,0.098925,0.258643,0.466795,0.037815,0.164419,0.238371,-0.126238,-0.185059,-0.040138,0.015410,-0.565100,0.291851,0.140092,-0.052958,-0.012094,0.218965,0.467848,0.113152,0.364470,-0.137779,-0.000678,-0.175734,0.143526,-0.079111,-0.089726,0.075013,0.205084,0.069186,0.419065,0.324612,-0.411126,-0.121731,0.222537,-0.294033,-0.951792,-0.074683,0.010772,-0.011829,-0.666964,0.577994,0.003786,0.014372,-0.161292,-0.338326,0.089026,0.628399,0.281919,0.085414,-0.008346,-0.148959,-0.566218,-0.006151,0.890408,-0.251417,0.025257,0.408385,-0.017366,-0.276143,-0.294593,-0.383947,-0.311788,0.081874,0.288302,-0.000860,0.178022,0.169837,-0.734608,-0.084800,-0.222491,-0.329888,0.113040,-0.504550,0.175201,-0.520786,-0.051583,-0.529841,-0.312934,0.320795,0.322868,-0.256117,0.515563,-0.633738,-0.126857,0.465918,0.367928,-0.226967,0.612506,-0.048226,0.388824,-0.080647,0.044072,-0.309015,-0.029362,0.154792,0.311245,0.378241,0.206127,0.018490,-0.380046,0.472786', '26678784', '25917239', '4301278', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30174085', '怒火·重案', '动作', '重案组布网围剿国际毒枭，突然杀出一组蒙面悍匪“黑吃黑”，更冷血屠杀众警察。重案组督察张崇邦（甄子丹 饰）亲睹战友被杀，深入追查发现，悍匪首领竟是昔日战友邱刚敖（谢霆锋 饰）。原来敖也曾是警队明日之星，而将敖推向罪恶深渊的人，却正是邦。宿命令二人再次纠缠，一切恩怨张崇邦如何作出了断……', '甄子丹', '陈木胜', 7.2, 412867, 'tt8165192', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2673412189.jpg', 0.6, 4.6, 39.9, 44.8, 10.1, '-0.042322,-0.460443,-0.104794,0.238375,0.027639,-0.039550,0.364164,0.132026,-0.644405,-0.265654,0.480964,0.141064,-0.012768,-0.027448,0.190075,-0.254769,-0.020633,-1.084227,-0.394879,-0.031852,-0.040609,-0.237634,0.156045,-0.197574,0.259407,0.044900,0.786550,0.194541,-0.476604,0.306574,0.740216,0.519319,-0.763463,0.667374,-0.302488,-0.162150,0.281868,-0.209801,-0.468565,-0.421416,-0.437615,-0.564738,-0.086966,0.177190,-0.056977,0.292306,0.400149,-0.376639,-0.111244,-0.307268,0.091280,-0.625733,0.100838,-0.155529,0.784172,-0.091946,0.101998,0.439410,0.266067,-0.052753,-0.015686,-0.039264,-0.314021,0.530726,-0.064914,0.072492,-0.539688,0.065417,-0.131230,0.493566,0.091610,0.557873,0.208018,-0.112463,0.210353,-0.169028,0.217692,-0.199350,-0.166050,0.248543,0.853155,-0.363437,0.082306,-0.403243,0.580080,-0.556232,-0.260271,-0.216178,0.433320,0.089342,0.250914,-0.284054,0.132168,0.515525,-0.517445,-0.258364,-0.528971,0.178227,-0.028335,-0.259489,0.079241,-0.782309,-0.079886,0.431304,-0.148163,0.442079,-0.099017,-0.225323,0.420804,-0.479595,-0.259357,0.238295,0.447327,-0.823128,0.248315,-0.000880,0.070271,-0.388675,0.086306,0.313200,0.786306,0.117710,0.470028,-0.136360,-0.587976,-0.022268,0.178967,-0.305018', '25723905', '1307914', '26996640', '1298104');
