INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30174652', '合法伴侣', '喜剧', '在伦敦追求音乐梦想的音乐才子古大白（李治廷 饰），因为一场意外陷入签证危机，将被遣送回国。已拿到绿卡的发小金天（白客 饰）突发奇想，企图在签证官华生（鲁伯特·格雷夫斯 饰）面前蒙混过关，而古大白也与新搬来的邻居赫敏（张榕容 饰）之间擦出恋爱的火花。但事情并没有想象中顺利：火眼金睛的签证官穷追不舍、大白的父母突然来访、金天也与女友出现感情危机… 各种突发状况让这对“伦漂”兄弟手忙脚乱，小谎言滚成了大雪球，在签证与真相之间，兄弟俩又将如何选择？©豆瓣', '李治廷', '黄雷', 3.4, 8008, 'tt10428328', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2634807354.jpg', 49.4, 33.8, 13.2, 2.8, 0.9, '0.202289,0.127406,-0.402920,0.374141,0.280321,-0.129666,0.587122,-0.029799,-0.469480,-0.364601,-0.164792,0.640962,-0.537360,0.172577,0.165778,-0.133029,-0.371990,-0.919626,0.156408,-0.077065,-0.396341,-0.522462,-0.219954,-0.157759,-0.102207,0.019890,0.361963,0.046048,-0.337592,0.608712,0.457706,-0.014833,-0.342723,0.446486,-0.047323,-0.067201,-0.061592,0.494400,-0.313756,-0.013997,0.061212,-0.206130,-0.026347,0.190676,0.149029,0.214037,0.733491,-0.399581,-0.113327,0.191999,0.240496,-0.325465,0.031178,0.247017,0.171581,0.090223,0.190824,-0.014835,-0.092838,-0.035805,0.328074,-0.158688,-0.600540,0.192378,-0.255884,0.184092,-0.415736,0.304774,-0.074044,-0.009393,0.222282,-0.287668,0.133866,0.537703,0.475296,0.329231,-0.444376,0.139913,-0.267028,0.092772,0.585233,0.054090,0.047094,0.384385,-0.174973,-0.444855,-0.213188,0.018793,-0.148114,-0.126209,0.367909,0.180948,-0.193777,0.338476,-0.660267,-0.108109,-0.245149,0.018141,-0.107468,-0.351990,-0.050107,-0.438461,-0.225923,-0.275925,-0.473286,0.120882,0.273855,-0.121018,0.576917,-0.643974,0.111923,0.239195,0.288465,-0.195253,0.474070,0.140230,0.044826,-0.251578,-0.190823,0.026955,0.113614,0.188075,0.178284,0.150010,-0.020615,-0.126601,-0.187982,0.126448', '30345227', '25777330', '20440456', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30175306', '追龙Ⅱ', '剧情', '悍匪龙志强，在香港回归前，趁香港英政府不作为，而屡犯巨案，先后绑架富豪利家及雷家之长子，勒索超过二十亿元，事主怕被报复, 交赎款后都不敢报警。中国公安部极为关注，与香港警方合力，派香港警员何天卧底潜入龙志强犯罪团伙，发现他正策划绑架澳门富豪贺不凡，最终陆港警察合力勇擒龙志强，救出贺不凡。', '梁家辉', '王晶', 5.4, 141438, 'tt10279010', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2559100280.jpg', 5.8, 31.7, 50.7, 9.9, 2, '0.026774,-0.622807,-0.569009,-0.008641,0.108291,-0.130468,0.026977,-0.103087,-0.821066,-0.299857,0.284953,0.426031,0.103498,0.384113,0.444982,-0.129849,-0.064512,-0.463406,0.010507,-0.031414,0.102818,-0.344075,-0.172123,-0.090699,0.048011,0.232706,0.160317,0.038831,-0.270451,0.592218,0.159212,0.448401,-0.589005,0.564219,0.093612,0.120532,0.581910,-0.254380,-0.499358,0.403792,0.112464,-0.532634,0.191779,0.342282,0.158297,0.420630,0.251603,-0.021905,0.160141,-0.358932,0.113613,-0.621342,-0.311790,-0.066520,0.649893,0.091126,0.615019,0.528591,-0.176697,-0.217254,-0.028325,0.259741,-0.158111,0.357353,0.383647,-0.097547,-0.339351,0.113963,-0.328871,0.440612,-0.087347,-0.013772,0.408361,0.506191,0.073420,-0.357600,0.094262,0.053723,-0.755753,0.103302,0.651626,-0.191028,0.352972,-0.487161,0.435257,-0.407091,0.562119,-0.647897,0.119800,0.185499,0.554916,-0.139262,0.176448,-0.030408,-0.062695,-0.450506,-0.477743,0.459958,-0.038797,-0.170962,-0.146147,-0.528652,-0.377675,-0.242306,0.106063,0.191946,0.079790,0.069760,-0.025489,-0.462857,-0.204773,0.218957,0.414247,-0.914151,0.485198,-0.205669,-0.136599,-0.330314,-0.182630,-0.612531,0.760569,0.659391,0.005232,-0.316699,0.151165,-0.689408,0.399274,-0.409550', '1464901', '1292633', '1297213', '1459054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30176282', '词典', '剧情', '金判秀被戏院开除后，为了儿子的学费而不得不去行窃，不料却失风被抓，被盗的主人正巧是朝鲜语学会的代表柳正焕。判秀阴错阳差地获得在朝鲜语学会工作的机会，处在母语被禁止的时代，两人于所剩不多的时间中，必须在日本帝国高层的监视下完成属于朝鲜的字典……', '柳海真', '严宥娜', 7.7, 8553, 'tt9602258', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2542477332.jpg', 0.5, 2.2, 27.2, 49.7, 20.4, '0.454622,0.576506,-0.625678,0.487391,-0.307308,-0.206218,0.396484,-0.049339,-0.457617,-0.235193,0.152739,0.325347,0.250158,0.136242,0.351368,-0.361973,-0.042074,-0.783066,-0.128853,-0.428681,-0.326974,-0.531748,0.019755,-0.057109,-0.518267,-0.577018,0.877283,0.340985,-0.279245,0.045702,0.085796,0.236108,0.192654,0.351820,-0.334974,-0.166118,0.059286,-0.332349,-0.226260,0.709958,0.360488,-0.307555,-0.004176,0.022664,0.144843,0.414309,0.860803,-0.190733,0.113605,-0.233806,0.534579,-0.339604,-0.449882,0.189001,0.522281,0.344322,0.090524,0.466313,-0.343583,0.300899,0.308221,-0.267253,-1.126959,-0.173795,0.303764,0.013082,-0.682458,0.573972,-0.135891,-0.053565,-0.001156,-0.631557,0.174427,0.405213,0.243164,0.528570,-0.179923,0.161289,-0.727962,0.110581,0.646113,-0.685301,0.109944,0.397391,0.076784,-0.385115,0.109794,-0.613522,-0.175133,-0.147891,0.192188,0.016678,-0.427412,-0.143229,-0.472715,-0.213068,-0.378576,-0.666656,0.170540,-0.817348,-0.303458,-0.446254,0.255316,-0.185423,-0.071518,0.513620,0.297211,-0.044829,0.575877,-1.039576,0.326710,0.770230,0.381717,-0.400272,0.614651,0.377732,0.153774,-0.120478,-0.170371,-0.023225,0.540772,0.809780,0.278920,-0.011260,-0.010757,-0.286672,-0.504051,0.502792', '1793491', '1294893', '30272753', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30176393', '误杀', '剧情', '李维杰（肖央 饰）与妻子阿玉（谭卓 饰）来泰打拼17年，膝下育有两个女儿，年届四十的他靠开设网络公司为生，为人也颇得小镇居民的好感，而这一切美好却被突如其来的不速之客打破。这个充斥走私，贩毒活动的边陲小镇，各种权力交织碾压公平正义。李维杰的大女儿平平（许文珊 饰）被督察长拉韫（陈冲 饰）的儿子素察（边天扬 饰）迷奸，因反抗误杀对方。李维杰曾亲眼目睹督察长滥用私刑，深知法律无用，为了维护女儿，捍卫家人，李维杰埋尸掩盖一切证据，在时间与空间的交错缝隙中，与警方在身心层面，展开了殊死一搏的较量。©豆瓣', '肖央', '柯汶利', 7.5, 840834, 'tt11210032', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2614628862.jpg', 0.9, 3.9, 29.5, 50.1, 15.6, '-0.033575,-0.006999,-0.628320,0.500880,-0.110503,0.076892,0.610649,0.243897,-0.753959,-0.258549,0.480690,0.430600,-0.171854,-0.017547,0.212785,-0.203895,0.060422,-0.736517,-0.054259,0.016646,-0.105976,-0.349816,-0.290531,-0.259647,-0.256159,-0.220553,0.686306,0.115114,-0.161673,0.211277,0.105911,0.023256,-0.265519,0.125341,-0.158806,-0.180476,-0.190472,-0.095499,-0.498625,-0.198367,-0.222420,-0.363213,-0.089045,0.001085,-0.225109,0.470500,0.699003,-0.158850,-0.063430,-0.376648,0.350490,-0.235196,-0.100176,0.126295,0.100432,0.014632,0.312159,0.389729,-0.237126,-0.229483,0.270549,-0.016007,-0.672519,-0.055771,0.233175,0.069654,-0.507876,0.603082,-0.128658,-0.147933,-0.266778,-0.082004,0.025345,0.286974,0.015047,0.316454,-0.226118,-0.063730,-0.347084,0.317502,0.483417,-0.295265,-0.199887,0.002423,-0.479971,-0.319055,-0.068097,-0.421977,-0.386546,-0.258882,-0.019446,-0.137031,-0.053277,0.416210,-0.636415,-0.001780,-0.265422,-0.018053,0.075719,-0.437406,-0.118623,-0.386844,-0.222266,-0.275686,-0.225053,0.324197,0.300159,-0.131223,0.371041,-0.736577,0.021237,0.367182,0.451869,-0.450923,0.607495,0.276673,0.219634,-0.264285,-0.291213,0.065202,0.114960,0.165422,0.135212,0.060079,-0.085788,-0.014899,-0.255079,0.316167', '35030151', '1301022', '30345227', '3033092');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3017651', '女巫季节', '动作', '十三世纪，牧师已经开始用“所罗门之书”对抗女巫和恶魔。一百年后，在十字军战争中因为战功卓著而声名鹊起的骑士贝曼（尼古拉斯·凯奇 Nicolas Cage 饰）和老搭档菲尔森(朗·普尔曼 Ron Perlman 饰）厌倦了战争的残酷，二人解甲返乡，但他们在小镇上看到的却是瘟疫肆虐的景象。贝曼和菲尔森因逃兵的身份被收押，当地领主了解二人的功勋，随即代表教会委托给他们押送一个女巫去修道院接受审判的任务。贝曼、菲尔德以及当地的一位牧师、一名骑士，还有一个担任向导的盗贼组成了一支押送队。笼中的少女看起来毫无威胁并且无辜，贝曼难以相信她是带来瘟疫的女巫。沿路一位年轻骑士加入了他们的队伍，但同时莫名的血腥异像也反复出现，贝曼一行在抵达终点时终于发现，这一切都是恶魔的一场阴谋……©豆瓣', '尼古拉斯·凯奇', '多米尼克·塞纳', 5.5, 55189, 'tt0479997', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1086794968.jpg', 6, 28.4, 51.1, 11.7, 2.8, '0.247502,0.064408,-0.378479,0.670317,-0.127861,-0.219501,0.924638,-0.042994,-0.248459,-0.452459,0.592489,0.927116,0.008130,0.051497,0.612984,-0.096339,-0.291717,-0.600468,-0.208897,-0.332463,-0.383734,-0.491846,-0.232716,-0.340324,0.045863,-0.535962,0.689396,0.290119,-0.127480,0.545236,0.321684,0.487905,-0.327797,0.367198,-0.192899,-0.167378,0.439032,-0.286306,-0.135131,0.128663,-0.256594,-0.182254,-0.329650,0.187710,-0.214082,0.272615,0.718964,-0.648776,-0.047493,-0.314166,0.136702,-0.409968,0.057695,0.167856,0.554136,0.082640,0.012355,0.069818,0.241306,0.039103,-0.232763,-0.184901,-0.765160,0.111219,-0.031109,0.272905,-0.643921,0.608854,-0.008002,-0.085740,0.059738,-0.068261,0.221163,0.269332,0.293710,0.429772,0.022949,-0.088276,-0.562957,0.054597,0.552504,-0.097437,-0.489988,-0.002587,-0.265502,-0.648927,-0.113239,-0.227667,-0.468895,0.072091,0.249897,-0.035470,0.072591,0.359679,-0.971870,0.134459,-0.564538,-0.219426,-0.172635,-0.199750,-0.175955,-0.797768,-0.031218,-0.180117,-0.278648,0.299009,0.196199,-0.068067,0.565453,-0.721315,0.384943,0.502599,0.177620,-0.398972,0.388433,0.015091,0.308562,-0.095879,-0.160102,0.238984,0.376218,0.426852,0.347122,0.415523,-0.225725,-0.226144,-0.067549,0.491438', '1294917', '26290398', '2988294', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30176790', '梅艳芳', '剧情', '电影讲述了梅艳芳一生的传奇经历。梅艳芳（王丹妮 饰）年仅4岁半便和姐姐梅爱芳一起登台卖唱，养家糊口。19岁参加华星唱片举办的第一届新秀歌唱大赛，获得冠军，从此同舞台结下不解之缘，凭借敬业的精神和过人的才华，慢慢成长为一代巨星，获封“百变天后”。2003年，一首《夕阳之歌》和一件定制的婚纱，她选择把自己嫁给了舞台。风华绝代尤可见，世间再无梅艳芳。', '王丹妮', '梁乐民', 6.9, 61873, 'tt15010590', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2706812406.jpg', 1.3, 8.8, 44.6, 35.2, 10.1, '-0.387457,0.042567,-0.523636,0.653516,-0.102973,-0.283541,0.163208,0.028607,-0.273294,-0.188212,-0.059882,0.936141,-0.510392,0.503049,0.682948,-0.299209,0.148155,-1.035294,0.241666,-0.079419,0.043847,-0.137493,-0.008641,0.259707,-0.209826,-0.464664,0.981027,0.094093,-0.105821,0.979910,0.583641,-0.358141,0.318081,-0.281970,-0.341800,-0.301631,0.470723,0.634572,-0.385072,0.457661,-0.380406,-0.319625,-0.098281,-0.244855,-0.099609,-0.210898,0.688349,-0.072875,0.187878,-0.252596,0.801692,-0.075832,-0.120712,-0.191057,0.173673,0.466970,0.179626,0.559960,-0.030163,-0.083689,-0.217440,-0.560026,-0.675120,0.194782,0.444487,-0.262833,-0.541518,0.661653,-0.162305,-0.144531,0.138029,0.033775,0.204628,0.085613,0.544431,0.245351,0.021282,0.065748,-0.483589,0.893255,0.790976,0.334041,-0.233507,0.289533,0.305845,-0.513055,0.044694,-0.657681,-0.426468,0.602947,-0.032492,-0.046116,0.308798,0.048614,-0.441337,-0.106876,-0.137437,-0.326546,0.562065,-0.296339,0.178277,-0.545478,-0.398634,-0.155737,-0.046632,-0.099636,0.191733,-0.737884,1.070474,-0.519639,0.357261,0.068894,0.332230,-0.262557,0.953299,-0.074720,0.447715,-0.061960,0.168893,0.069596,-0.524306,-0.047466,-0.221773,0.375279,-0.067954,0.091769,-0.445500,0.470792', '1780122', '27602116', '3811356', '30391300');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3017691', '逃出熔炉', '剧情', '罗塞尔（克里斯蒂安·贝尔 Christian Bale 饰）和弟弟罗德尼（卡西·阿弗莱克 Casey Affleck 饰）相依为命的生活在穷困而又闭塞的工业小镇之中，总有一天能够离开这里的朴素愿望成为了支撑兄弟两人了唯一动力，两人每日辛苦打拼，为的就是能够实现这一愿望。苍天无眼，厄运降临到了与世无争的两兄弟头上，因为一场意外，罗塞尔不得不面临着为期四年的牢狱之灾，当漫长的四年终于走到尽头，重返社会的罗塞尔却发现罗德尼早已成为了一缕冤魂。原来，罗塞尔入狱后，形单影只的罗德尼受到奸人诱惑，开始在地下黑市里打起了违法的拳击赛，这直接导致了他的死亡。悲伤和愤怒一起涌上心头，他决定为罗德尼报仇。©豆瓣', '克里斯蒂安·贝尔', '斯科特·库珀', 6.4, 8252, 'tt1206543', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2152728124.jpg', 1.9, 14, 53.5, 23.7, 6.9, '-0.008587,0.162920,-0.760571,0.399569,-0.054647,-0.748693,0.745588,0.094401,-0.596623,0.100437,0.144627,0.726368,-0.154776,0.457420,0.419539,0.052644,-0.327210,-0.731816,-0.166961,-0.452194,-0.290327,-0.354959,-0.307918,-0.258917,-0.308833,-0.351039,0.750321,0.489983,0.126206,0.504921,0.394251,0.209661,0.016694,0.385857,-0.181594,0.065204,0.008474,0.044014,-0.341792,0.200952,0.151815,-0.236057,-0.127817,0.248769,-0.044310,0.209762,0.448487,-0.261787,-0.071736,-0.310034,0.355003,-0.325729,-0.099516,0.243793,0.076608,0.012487,0.160814,0.294237,-0.297039,-0.102008,0.151036,-0.278277,-0.731886,-0.066797,-0.103574,0.089338,-0.654729,0.541900,-0.056935,-0.384100,0.021009,-0.304984,0.060619,0.471171,0.433375,0.582110,-0.506194,0.075054,-0.378482,0.004600,0.821776,-0.383772,-0.325095,0.222245,-0.120754,-0.150658,0.171454,-0.241927,-0.268802,-0.238237,0.381810,0.235774,-0.017988,0.457249,-0.680730,0.252240,-0.353374,-0.257750,-0.091485,-0.329400,-0.115696,-0.333357,-0.226979,-0.273036,-0.146462,0.273970,0.016386,-0.359882,0.436855,-0.625015,0.427769,0.571040,0.321663,-0.249768,0.574986,0.048158,0.390983,-0.121181,0.175384,0.453676,-0.258551,0.554494,0.240613,0.055189,-0.007773,0.193447,-0.337058,0.642795', '25828589', '26245360', '3014557', '1293945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3017836', '我的老婆是赌圣', '喜剧', '赌坛高人龙天九（王晶 饰）之妹龙盈盈（孟瑶 饰）青出于蓝，号称“美女赌神”。龙盈盈为取回宿敌仇曼联（陈国坤 饰）的欠款，前往对方赌船却遭暗算，被自己的保镖兼恋人亨利击落坠海。这边厢，不成器的财务公司讨债主任周姐轮（张家辉 饰）与两名死党同事终日只是在工作中犯锉与被自己女友欺骗、殴打。郁闷的三人在海边散心，却捡回失忆美女一名。自此周姐轮与失忆的龙盈盈共处一室，经历了前任女友的周姐轮得温柔的盈盈照顾，倍感爱情的甜蜜。不久仇曼联不甘失败再出阴谋，组织亚洲赌神大赛逼龙盈盈出现。终于明了龙盈盈真实身份的周姐轮连同死党也一起被卷入了这场赌局……©豆瓣', '张家辉', '王晶', 4.8, 6514, 'tt1369831', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2366021318.jpg', 18.7, 36.2, 36.4, 6.1, 2.6, '-0.164608,0.053124,-0.251358,0.407918,-0.111705,-0.166273,0.411032,0.024992,-0.364729,-0.152310,0.483971,0.609626,-0.480198,0.425042,0.471660,-0.103363,0.195000,-0.767984,0.084149,0.215556,-0.010619,-0.208669,-0.296590,0.060473,-0.088689,0.068773,0.579211,0.110609,-0.051478,0.706546,0.678832,0.407664,-0.444585,0.252391,-0.151950,0.335564,0.164066,0.108716,-0.270109,0.035612,0.015818,-0.214995,0.013765,-0.042666,0.137973,0.201183,0.596451,-0.006400,-0.164647,-0.320873,0.399900,-0.409936,-0.010007,0.198705,0.401771,0.072963,0.173993,0.264892,-0.053728,-0.019869,0.143424,0.012251,-0.510030,0.361093,0.134156,-0.090894,-0.397692,0.594784,-0.224257,0.173213,0.118809,0.452208,0.378564,0.382270,0.010133,0.209938,0.021112,0.097583,-0.460327,0.338949,0.496573,-0.113185,0.224717,0.091504,0.179748,-0.178187,0.067913,-0.298714,-0.062481,0.122727,0.236303,-0.019749,0.081475,0.243976,-0.548900,-0.084953,-0.144095,0.408353,-0.124239,-0.358205,0.053072,-0.523663,-0.293689,-0.444226,-0.213504,0.287348,-0.160112,-0.255879,0.375450,-0.699827,0.020377,0.226404,0.371051,-0.539134,0.770029,0.246876,0.070964,-0.465739,-0.200157,0.102376,-0.020913,0.022583,0.406269,0.357146,-0.109356,0.011618,-0.009728,0.108188', '4202326', '26365262', '3139191', '2976123');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3017896', '毕业生生存指南', '喜剧', '美丽大学生瑞登·梅比（阿里克西丝·布莱德尔 Alexis Bledel 饰）即将迎来毕业的那一天，她乐观向上，学业优秀，从小就对人生作出理性而系统的规划。毕业后她决定进入当地最棒的出版社哈伯曼&布朗宁，再于几年后发表一部个人小说。憧憬固然美好，但现实却无比残酷。瑞登的大学同学，同时也是她学业上最强劲的竞争对手杰西卡•巴登（凯瑟琳·雷特曼 Catherine Reitman 饰）成功得到那家出版社的工作，失意的瑞登只好返回家乡。即使降低了标准，求职之路也充满艰辛。与此同时，瑞登多少有些脱线也让她烦恼不已。在这一过程中，青梅竹马的好友亚当（扎克·吉尔福德 Zach Gilford 饰）始终陪在她的身边，而瑞登似乎又对帮助过自己的邻居有了别样的情感……©豆瓣', '阿丽克西斯·布莱德尔', 'Vicky Jenson', 6.2, 11585, 'tt1142433', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2267737657.jpg', 2.2, 14.7, 57.6, 21.5, 4, '0.213439,0.173377,-0.643591,0.626188,0.010412,-0.522631,0.659324,-0.017103,-0.554099,-0.105142,0.076758,0.721082,-0.115923,0.236902,0.223723,0.017147,-0.470941,-0.525826,0.208705,-0.127955,-0.147400,-0.374864,-0.248208,-0.078289,-0.095761,-0.253241,0.616625,0.123924,0.031641,0.478798,0.174180,0.219156,0.225637,0.511139,0.044044,0.100899,0.088485,0.135501,-0.209015,-0.031275,0.310168,-0.037159,-0.371198,0.099559,0.207001,0.309226,0.672156,0.115720,-0.213508,0.040425,0.446324,-0.064776,-0.032543,-0.022865,0.113510,0.027321,0.124358,0.247027,-0.151063,0.006207,-0.149616,-0.127237,-0.772145,-0.047217,0.132095,0.043445,-0.426228,0.462387,-0.205128,0.006295,0.120903,-0.340656,-0.237960,0.344908,0.271790,0.341926,-0.212799,0.079365,-0.237505,0.437734,0.515554,0.106660,-0.413085,0.299377,-0.464337,-0.444800,-0.064875,-0.210810,-0.631225,-0.067062,0.268445,0.252202,-0.227779,0.481865,-0.627559,0.129333,-0.225523,-0.212553,0.038503,-0.444246,-0.050523,-0.595991,-0.032680,-0.502297,-0.433809,-0.067227,0.212541,-0.358890,0.866451,-0.845329,0.150604,0.457799,0.279062,-0.258782,0.684209,0.143929,0.250030,-0.169151,-0.092327,0.603852,-0.291980,0.181189,-0.107471,0.346184,0.061244,-0.277362,-0.411779,0.826624', '1870681', '1292720', '4058933', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30179560', '紫罗兰永恒花园 剧场版', '剧情', '延续TV版的主线剧情，继续讲述从战场回来的少女薇尔莉特·伊芙加登为了理解“爱”的含义而从事为有需要的人们写信传情的工作。薇妹一直挂念的少佐的下落大概率会在这部剧场版中讲述。', '石川由依', '石立太一', 8.1, 17259, 'tt8652818', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2611203679.jpg', 0.4, 3.7, 19.5, 44.6, 31.8, '-0.045336,-0.031888,-0.508313,0.942491,0.096025,0.190283,0.505589,-0.259569,0.120121,-0.126098,0.244662,0.887237,-0.179896,0.227037,0.336209,0.114688,-0.429882,-0.639235,0.008262,-0.361952,-0.156644,-0.813144,0.249692,-0.075165,-0.276192,-0.259247,0.803579,0.085854,-0.095680,0.436841,0.223954,0.237642,-0.330096,0.412169,0.092986,0.152522,-0.332676,-0.250147,-0.181450,0.252830,0.560507,0.189837,-0.267350,0.354581,0.208301,0.305867,1.012342,-0.721177,0.038708,0.359204,0.593173,0.078325,0.393032,-0.396792,0.305757,-0.017460,0.207314,0.529184,-0.275403,0.144672,-0.205694,-0.465310,-1.066914,-0.036697,0.230482,0.413413,-0.548757,0.004915,-0.134071,0.199677,0.353180,0.026789,0.034572,0.709723,0.609802,0.678934,-0.081998,0.198275,0.193021,0.236135,0.208649,-0.507434,-0.328411,1.218037,-0.051786,0.024114,-0.160747,-0.109860,-0.793841,-0.027305,-0.070512,0.207777,-0.428855,0.092360,-0.280776,-0.014415,-0.139932,-0.403577,0.369648,-0.141068,-0.507137,-0.388773,-0.099080,-0.497091,0.112110,-0.333973,0.064976,-0.694880,1.089707,-0.905291,0.028930,0.776621,0.125409,-0.870401,0.725896,0.249080,0.012904,-0.195385,-0.259550,0.503900,-0.227572,0.074845,0.059622,0.155802,0.108606,-0.335796,-0.501926,0.315214', '30279170', '24284209', '25880986', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30180126', '窗里的女人', '剧情', '乔·赖特(《至暗时刻》《赎罪》《傲慢与偏见》)将执导悬疑惊悚新片《窗里的女人》(The Woman in the Window)，根据A.J. Finn所著同名畅销小说改编，崔西·莱茨(《八月:奥色治郡》《伯德小姐》)操刀剧本。讲述女主角Anna Fox隐居在纽约家中，酗酒、看老电影、回忆曾经的美好，以及暗中监视她的邻居们。当罗素一家三口搬来后，Anna某晚透过窗户看到了不该看的东西，她的世界开始支离破碎，令人震惊的秘密开始显露出来。', '艾米·亚当斯', '乔·赖特', 6.1, 8417, 'tt6111574', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2639263452.jpg', 2.5, 17.3, 56.8, 19.6, 3.8, '0.368681,-0.059613,-0.561448,0.598891,0.062646,0.022493,0.725755,0.063206,-0.520925,-0.278199,0.078472,0.752124,-0.344230,0.459625,0.250904,0.159057,-0.605632,-0.788951,-0.305788,-0.275247,-0.075353,-0.443636,-0.220943,-0.517466,0.124302,-0.349024,0.432470,0.281874,-0.120892,0.199664,0.206145,0.019711,-0.402274,0.260718,-0.040338,0.078917,0.069303,0.194049,-0.449107,-0.023168,0.188214,-0.383435,-0.186984,0.059417,0.046891,0.251386,0.599624,-0.312590,-0.199249,-0.194919,0.539795,0.191737,0.007550,0.059912,0.352029,0.279921,0.245482,-0.049033,-0.227458,-0.233708,-0.287484,0.047358,-0.544664,-0.003305,0.434001,0.135404,-0.434913,0.292044,-0.067716,0.126145,0.154263,-0.344773,0.225104,-0.133308,0.608547,0.345303,0.163811,-0.001751,-0.079774,0.526343,0.024875,-0.122541,-0.013785,0.483942,0.101570,0.019753,0.174188,0.162484,-0.540992,0.263582,0.349246,-0.106037,-0.013654,0.205951,-0.375611,-0.339091,-0.079509,-0.372356,0.059609,-0.477590,-0.403577,-0.688301,-0.402359,0.078251,0.250265,-0.037543,0.126434,-0.415326,0.432791,-0.423962,0.180212,0.335859,0.152380,-0.281366,0.699782,-0.248234,-0.197819,-0.294641,-0.004309,0.494608,0.016711,0.082317,0.076558,0.335441,-0.009882,0.038200,-0.334015,0.596386', '1299663', '6537486', '1299248', '5262339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30180781', '抓住稻草的野兽', '惊悚', '因失踪的恋人而负债累累的泰荣（郑雨盛饰）、辛苦打工却只能勉强维持生计的一家之长忠万（裴成宇饰）、想要洗白过去而觊觎他人所有的妍希（全度妍饰），以及高利贷放贷者朴社长（郑满植饰）、因欠债而家庭破碎的美兰（申贤彬饰）、非法滞留者镇泰（郑家蓝饰）、一心为家人而活的英善（陈庆饰）、失忆的顺子（尹汝贞饰），所有身处困境的这些人，都将一个钱袋视为自己人生的最后机会，从而引发了一连串始料未及的事件。', '全度妍', '金容勋', 7, 20681, 'tt9747594', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2593860359.jpg', 0.6, 4.7, 47.1, 37.5, 10.1, '0.014251,0.046464,-0.315962,0.443618,-0.188571,-0.421541,0.599704,0.320367,-0.296723,-0.505582,0.246665,0.467424,0.385850,0.132799,0.339977,-0.154596,0.127947,-0.638356,-0.062919,-0.074642,-0.247208,-0.243919,0.022228,-0.280435,-0.661068,0.163385,0.739570,0.136998,0.020026,0.197425,0.291083,0.392172,-0.186292,0.190172,0.074338,0.222386,-0.283225,-0.070202,-0.401203,-0.111823,0.055962,-0.281848,-0.206511,0.475529,-0.020743,0.285416,0.806415,-0.210721,-0.064017,-0.309104,0.420361,-0.462028,-0.021565,0.122829,0.185191,0.100384,0.452490,0.101885,-0.305085,-0.158160,0.485737,0.115176,-1.138365,-0.229267,0.131819,0.019610,-0.167506,0.295122,0.058317,0.000349,-0.121872,-0.213964,-0.068542,0.514962,0.019107,0.257683,-0.574920,0.044838,-0.248715,0.476567,0.499150,-0.285024,-0.336706,0.460137,-0.250059,-0.025964,0.043706,-0.343042,-0.890806,-0.150831,0.281368,0.222807,-0.162125,0.428682,-0.398668,-0.092345,-0.539518,-0.216802,0.129905,-0.314663,-0.091542,-0.276624,-0.223602,-0.304979,-0.184430,0.207298,0.218524,-0.360027,0.514776,-0.573716,0.059469,0.767665,0.089601,-0.736999,0.288557,0.011483,0.511388,-0.047011,-0.271639,0.084839,0.182426,0.402410,-0.034761,-0.205368,-0.015523,-0.014449,-0.194885,0.197979', '26678784', '30279170', '4820775', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30181079', '阴曹使者', '动作', '《阴曹使者》讲述死神来到阳间发生的故事，同时是一部带有超自然元素的惊悚动作片。失去父亲的格斗选手勇厚（朴叙俊 饰）在遇到祭司安神父（安胜基 饰）后，与扰乱世界的邪恶死神展开了决斗。', '朴叙俊', '金周焕', 6.4, 19823, 'tt10550884', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2560576875.jpg', 2, 13.2, 53.7, 23, 8.2, '0.354173,-0.120756,-0.269931,0.495882,0.176609,0.208512,1.090507,-0.132082,-0.298183,-0.298911,0.551372,0.812626,-0.580797,-0.149529,0.877384,-0.389360,-0.256248,-0.759128,-0.163763,-0.009990,-0.194743,-0.539199,-0.152539,0.048157,0.082824,-1.096739,0.678338,0.155107,-0.543920,0.135299,0.287940,0.555562,-0.737658,0.210478,-0.017363,-0.060220,-0.196925,-0.026170,-0.427522,0.135076,0.306761,0.015616,0.065408,-0.008814,-0.237816,-0.174004,0.741379,-0.915146,-0.023530,-0.223742,0.803420,-0.104818,-0.208341,-0.212144,0.191182,0.481548,-0.357644,0.256217,0.488661,0.156544,0.003481,-0.114740,-0.833611,0.154014,0.256867,0.415908,-0.233628,0.328145,0.273920,0.270556,0.444817,-0.114226,0.564990,0.121629,0.807752,0.502307,0.340457,-0.325355,-0.231875,0.273547,0.668988,-0.187211,-0.484525,0.192907,-0.372869,-0.773225,-0.495303,-0.118172,-0.433572,0.347882,0.348223,0.110843,0.171777,0.416826,-0.814719,-0.396496,0.251192,-0.137953,0.176825,-0.220780,-0.109520,-0.846126,-0.173021,-0.252446,0.042847,0.066679,0.168235,-0.305360,0.627568,-1.295862,0.539259,0.553096,0.275595,-0.191062,0.608494,-0.388172,-0.000485,-0.429008,0.085856,0.513119,0.283874,0.666299,0.006024,0.203849,-0.013718,0.273860,-0.115001,0.197119', '26759819', '10174444', '10569150', '4126925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3018122', '玩命快递3', '动作', '超强押运人弗兰克·马丁（杰森·斯坦森 Jason Statham 饰）平静的休假再次被打破，一名驾驶着奥迪车的男人载着一名女孩在马赛横冲直撞，与此同时，商人约翰森（Robert Knepper 饰）为了向乌克兰运输有毒物质正与该国环境部长针锋相对。受伤的奥迪车司机闯入弗兰克家中，并死于手腕上的炸弹，他的幕后老板约翰森强迫弗兰克接替运送女孩的任务，被安装了手腕炸弹的弗兰克不得不就范，因为只要他离开车子75英尺炸弹就会引爆。在前往布达佩斯的路上，弗兰克终于明白任务的真相：女孩瓦伦汀娜（Natalya Rudakova 饰）是乌克兰环境部长之女，约翰森为使部长批准他的计划而掳走瓦伦汀娜，在约翰森和部长两路人马的追击中，弗兰克该如何化解这次的危机？©豆瓣', '杰森·斯坦森', '奥利维尔·米加顿', 7, 75474, 'tt1129442', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p461621583.jpg', 1.1, 5.9, 45, 35.6, 12.4, '0.014245,0.027206,-0.513201,0.332076,-0.363901,-0.167104,0.558348,0.258235,-0.448050,-0.223259,0.491179,0.796127,-0.060540,-0.140606,0.681663,0.232114,-0.400621,-0.494619,-0.163183,-0.014044,-0.311071,-0.614419,-0.144102,-0.297994,0.372141,-0.319472,0.694571,0.046625,-0.259437,0.290767,0.245580,0.425649,-0.152236,0.498816,-0.117359,-0.082398,0.113359,-0.557790,-0.228955,0.313976,-0.021232,-0.400882,0.172440,0.049838,0.038820,0.259475,0.649279,-0.134714,0.022285,0.020742,-0.107556,-0.386698,0.375129,-0.102131,0.300893,0.119229,0.085424,0.116326,-0.303412,0.079855,0.360710,0.031977,-0.337093,0.093695,-0.264558,0.257106,-0.554813,0.204935,-0.438243,0.035150,0.026843,-0.435209,0.090432,0.372911,0.065477,0.226549,-0.257199,-0.020103,-0.569696,-0.219945,0.472790,-0.000324,0.012522,0.028811,-0.147932,-0.445100,-0.073208,-0.181688,-0.485603,-0.149973,0.535448,0.073263,0.016925,0.179879,-0.359114,0.033018,-0.499254,-0.179227,-0.098244,-0.259237,-0.102463,-0.706064,0.331708,-0.079437,-0.048495,0.212699,0.108463,0.160673,0.394506,-0.606168,0.133323,0.697417,0.409138,-0.189245,0.322668,0.107718,0.205100,-0.435350,-0.104134,0.111402,0.213111,0.505619,0.068818,0.298241,-0.046074,-0.419286,-0.325098,0.109950', '1297389', '1309194', '1484091', '3326747');
