INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30182726', '狩猎', '动作', '12个陌生人在空地上醒来。他们不知道自己在哪里，或者是如何到达这里的。他们不知道他们已经被选中，为了一个非常特殊的目的——捕猎。', '贝蒂·吉尔平', '克雷格·卓贝', 7.4, 135882, 'tt8244784', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2585533507.jpg', 0.6, 4.1, 36.2, 43.9, 15.2, '0.960893,-0.085413,-1.159789,0.601796,-0.595094,0.190823,0.780837,-0.456722,-0.505330,-0.786168,0.377568,1.272342,0.023933,0.242214,-0.294261,0.367713,-0.253129,-0.042464,0.025899,-0.797885,-0.867556,-0.714086,-0.720214,-0.074542,-0.016282,0.400526,0.714105,0.104864,-0.125093,0.106712,0.471492,0.380701,0.324475,0.786254,-0.571173,-0.209211,0.014487,0.057546,0.380060,0.424258,-0.012380,-0.444530,-0.342004,0.326100,-0.287059,0.353904,0.652598,-0.262778,-0.331281,-0.034199,0.090362,-0.884780,0.370762,0.460773,0.506899,-0.903501,0.371017,-0.061214,-0.277689,0.223523,-0.145497,0.079025,-1.101753,-0.151415,0.044151,0.679650,-0.703061,0.484601,-0.223403,-0.579257,-0.171026,-0.639428,0.644173,1.145961,0.234842,0.238151,-0.367433,-0.630376,-1.477842,-0.592682,1.591404,0.156897,0.079598,0.479183,-0.168597,-0.679644,0.021471,-0.282862,-0.387123,-0.172348,0.059127,0.255738,-0.536170,-0.627449,-0.237240,0.282268,0.174697,-0.317645,-0.399635,-0.813721,-0.131159,-0.153120,-0.027819,-0.764527,-0.575434,0.033984,-0.132164,-0.385398,0.753168,-1.587267,0.208894,0.722810,0.584668,-0.727469,1.077139,0.189208,-0.158170,-0.882230,0.060923,-0.500694,0.610353,0.295359,0.401585,0.464035,0.406105,-0.153044,-0.617840,0.556733', '25721544', '1308762', '1308755', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30182877', '坏教育', '剧情', '弗兰克（休·杰克曼 Hugh Jackman 饰）是美国纽约州长岛公立学校的负责人，在他和同事帕姆（阿丽森·詹尼 Allison Janney 饰）的努力之下，纽约罗斯林学区的升学率得到了全美排名第四的好成绩。弗兰克的出名不仅让学校变得炙手可热，同时也带动了学校周边的学区房房价一路上涨。瑞秋（杰拉尔丁·维斯瓦纳森 Geraldine Viswanathan 饰）是罗斯林高中的一名学生，某日，在撰写校刊报道时，她震惊的发现学校的账目漏洞百出，不仅仅是校长，学校的整个领导阶层都在肆意的挪用着董事会的拨款，去满足他们无限膨胀的物欲。随着调查的深入，一场涉案金额极高、涉事人员众多的贪污案浮出了水面。©豆瓣', '休·杰克曼', '科瑞·芬莱', 7.2, 9883, 'tt8206668', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2594754124.jpg', 0.5, 2.5, 41.5, 45.9, 9.6, '0.337237,-0.066836,-0.827034,0.655926,-0.052778,-0.257884,0.473394,0.340459,-0.427315,0.050291,0.098776,0.562269,-0.383643,0.452331,0.063548,-0.066991,-0.070736,-0.641402,-0.236260,-0.383738,-0.071460,-0.551306,-0.188931,-0.306774,0.043994,-0.192606,0.361519,0.146705,-0.183045,0.491860,0.264581,0.257502,0.181267,0.287474,-0.173265,-0.055823,0.389555,-0.029315,0.083352,0.122710,0.124835,-0.249809,-0.168554,-0.125397,0.542989,0.388551,0.717299,0.323744,-0.096694,0.324252,0.807730,-0.295726,-0.058958,0.125455,0.818793,0.065321,-0.102173,0.201667,-0.291610,-0.019060,0.001188,-0.098984,-0.589223,-0.105756,0.188651,0.271313,-0.572548,0.565967,-0.169044,-0.047189,0.021974,-0.205742,-0.009649,0.267572,-0.222739,0.419372,0.099944,0.016078,-0.507514,0.436632,0.440725,0.003231,-0.338682,-0.121745,-0.426247,-0.543891,-0.138264,-0.052299,-0.263156,-0.242170,0.384261,-0.201905,0.294532,0.293292,-0.368905,-0.279807,-0.223531,-0.747862,-0.188814,-0.118239,-0.190561,-0.909156,-0.159833,-0.256419,-0.157728,-0.084864,0.034769,-0.238234,0.704711,-0.758381,-0.033960,0.743170,0.271432,-0.331391,0.665914,-0.161111,0.304821,0.079551,-0.369109,-0.165900,0.177695,0.475236,0.113563,0.548258,-0.092682,-0.495417,-0.266252,0.582511', '26259202', '2245683', '3178770', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30183666', '老爸102岁', '剧情', '达特利（阿米特巴·巴强 Amitabh Bachchan 饰）已经102岁高龄了，但无论是思想还是行为，他都仿佛是一个二十几岁的小伙子，充满了活力。和达特利相比，他的儿子巴布（里希·卡普尔 Rishi Kapoor 饰）更像是一个实实在在的老人，每天都浑浑噩噩没精打采，父子两人的身份仿佛掉了个个儿。一天，达利特宣布了一个让巴布惊掉了下巴的决定，他竟然想把巴布送进养老院。为了避免这样悲惨的命运，巴布承诺会做出一系列的改变，并保证他将会对生活重新燃起热情。在改变的过程中，巴布和达利特之间发生了各种各样的碰撞和摩擦，但父子两人的感情也在吵吵闹闹中日渐升温。©豆瓣', '阿米达普·巴强', '奥米史·舒克拉', 7.2, 17625, 'tt6580564', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2540024317.jpg', 1, 7, 38.2, 39.5, 14.2, '0.384736,0.055431,-0.620657,0.358948,-0.189832,-0.460886,0.857840,0.371475,-0.636839,-0.122889,0.085507,0.677337,-0.409208,0.145454,0.231333,-0.163954,-0.398140,-0.782108,-0.106613,-0.239270,-0.183178,-0.549814,-0.199071,0.009391,-0.198939,-0.276750,0.049351,-0.384368,0.053107,0.537698,0.210548,0.075946,0.394376,0.500778,0.062639,0.047293,-0.005155,-0.127165,-0.013523,-0.036566,0.253487,-0.016910,0.037946,0.156583,-0.139004,0.580222,0.762636,-0.498310,-0.246960,-0.194472,0.241425,-0.168429,-0.133760,0.507305,0.121913,0.004043,-0.041769,0.226108,-0.277118,-0.134227,0.226015,0.038509,-0.750981,0.181009,-0.027049,0.197754,-0.707398,0.509035,0.145824,-0.161822,0.061672,-0.340556,0.314989,0.588082,0.435948,0.550160,-0.431029,-0.357775,-0.727176,-0.129221,0.834699,0.046259,-0.354444,0.237767,-0.620281,-0.290007,-0.344020,-0.171307,-0.603024,-0.121591,0.129836,-0.012253,-0.260174,0.587307,-0.494946,-0.068445,-0.498050,-0.319234,-0.101380,-0.549373,0.087022,-0.357376,-0.197188,-0.521266,-0.439714,-0.014082,0.027080,-0.382524,0.694832,-0.543225,0.256519,0.375771,0.447014,0.061782,0.625663,0.023085,0.051701,0.020360,0.078034,0.204218,-0.032817,0.076674,0.119682,0.627179,0.126810,-0.101992,-0.133175,0.625405', '30162520', '1305986', '34875369', '25723780');
