INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30184555', '铤而走险', '剧情', '山城修车行老板刘小俊（大鹏 饰）因迫于生计倒卖黑车，却意外发现了被困于后备箱中的小女孩奇奇。随着奇奇（乌兰托雅·朵 饰），兄弟夏西（欧豪 饰）与夏涛（沙宝亮 饰）、舞女（李梦 饰） 、二手车贩（曹炳琨 饰）等越来越多看似无关联的人都被卷入命运旋涡，这场迷局背后不可告人的秘密也逐渐浮出水面……', '大鹏', '甘剑宇', 6, 30107, 'tt10074486', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2587114196.jpg', 2.1, 19.5, 59.3, 16.8, 2.3, '0.252197,0.016029,-0.402090,0.045369,0.242149,0.123739,0.875351,0.284020,-0.557072,-0.095077,0.284441,0.230044,-0.273102,-0.344039,0.212460,-0.017448,-0.307645,-0.426016,0.075811,-0.246667,0.024453,-0.302626,-0.325496,0.087117,-0.375194,-0.088933,0.581857,0.238369,0.167845,0.520468,0.348186,0.107964,-0.522896,0.282119,0.269635,0.180466,0.027425,0.185001,0.002517,-0.317371,-0.267481,-0.346030,0.048060,0.031431,-0.101713,0.413113,0.804286,-0.180901,0.187470,-0.344192,-0.079277,0.063480,-0.088548,-0.280980,0.144275,0.261995,0.172211,0.482569,-0.382673,0.126549,0.448043,0.171300,-0.110237,0.326077,0.435825,0.258209,-0.331089,0.106107,-0.010115,-0.346224,-0.009806,-0.230571,0.197658,0.002934,0.596169,0.065405,-0.035306,0.259238,-0.523024,0.228962,0.239912,-0.179391,0.039087,0.181614,-0.208356,-0.132983,-0.001713,0.086804,-0.241767,-0.163477,0.434576,0.059313,-0.220927,0.335164,-0.504179,0.138796,-0.297195,-0.081937,-0.262620,-0.216123,0.008163,-0.304466,-0.117654,-0.351559,0.098114,0.314736,0.178712,0.159481,0.279757,-0.419629,0.147920,0.434484,0.419030,0.039885,0.163231,-0.062385,0.167369,-0.278850,-0.285145,-0.179048,-0.247883,0.151004,0.079965,0.233283,-0.030011,-0.440980,0.037625,-0.163091', '21619567', '1467779', '1578663', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30188253', '珍品', '剧情', '故事发生在1895年的巴黎，皮埃尔（尼尔斯·施内德 Niels Schneider 饰）是一个放浪形骸的诗人，同时也是臭名昭著的花花公子。亨利（本杰明·拉维赫尼 Benjamin Lavernhe 饰）是皮埃尔的好友，两人共同在导师海德利亚（阿蜜拉·卡萨 Amira Casar 饰）门下学习诗歌，海德利亚有一个非常可爱的女儿玛利亚（诺米·梅兰特 Noémie Merlant 饰），皮埃尔和亨利疯狂的爱上了这个女人。虽然玛利亚的内心里深爱着皮埃尔，但迫于经济上的压力，玛利亚最终嫁给了亨利。心碎欲绝的皮埃尔决定离开伤心地，前往阿尔及利亚，并在那里结识了名为佐哈（卡梅丽雅·乔丹娜 Camélia Jordana 饰）的女子。虽然佐哈美丽又温柔，但皮埃尔始终忘记不了玛利亚。©豆瓣', '诺米·梅兰特', '卢·热内', 6.2, 27102, 'tt7598076', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2550530631.jpg', 2.9, 16.6, 52.9, 20.4, 7.2, '0.325873,0.039216,-0.536823,0.631585,0.123443,-0.301354,0.810278,0.154660,-0.471641,-0.366470,0.118948,0.754453,-0.151900,0.423176,0.370581,0.414200,-0.486303,-0.489203,0.222477,-0.177506,-0.111388,-0.820341,-0.216090,-0.193967,-0.263267,-0.310817,0.410971,-0.043437,0.208413,0.551208,0.511887,0.527453,0.251442,0.273342,-0.017520,0.105240,0.260734,-0.188494,-0.166545,0.114384,0.011593,-0.117608,-0.230344,0.175165,0.126432,0.220044,0.250188,-0.320908,0.279071,-0.128124,0.214991,-0.128237,0.057619,0.145311,-0.039520,-0.313087,0.167769,0.068954,-0.247046,0.029193,0.361674,-0.199309,-0.497422,0.439954,0.316569,0.221881,-0.620949,0.549594,-0.309642,-0.009379,0.081167,-0.394787,-0.014603,0.059956,0.081131,0.335318,-0.053150,0.251693,-0.375566,-0.190898,0.427871,0.235687,-0.148251,0.216255,-0.409960,-0.396921,-0.056810,-0.248432,-0.557374,0.177349,0.086210,0.092436,0.012450,0.249620,-0.660723,-0.072326,-0.479000,-0.033420,-0.038398,-0.426927,-0.052142,-0.613408,-0.146164,-0.675706,-0.396770,-0.072003,-0.186702,-0.265019,0.820084,-0.830638,0.060500,0.441178,0.113435,-0.222144,0.581689,0.328606,-0.043108,-0.031224,-0.241480,0.809461,0.047695,-0.136993,-0.096183,0.417290,0.199293,-0.124267,-0.108269,0.591865', '1292720', '26348103', '2002744', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30189817', '江边旅馆', '剧情', '一位老诗人在河畔酒店里住了一段时间，想起了他两个久未联系的儿子。一个被同居男人背叛的年轻女人，也入住了这家酒店。为了寻求支持，她请了一位朋友来陪她。在这个江边旅馆里，人们只是相互凝视，生活于每个人来说都很艰难，这样的日子似乎每天都在不知疲倦地反复。', '奇周峯', '洪常秀', 7.3, 10741, 'tt8725958', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2545912829.jpg', 0.9, 4.3, 38.8, 42.3, 13.7, '0.270594,-0.025644,-0.761940,0.637078,-0.365908,-0.249750,0.956641,0.144049,-0.607859,-0.471040,0.219168,0.981482,0.010537,0.711227,0.361285,-0.086223,-0.276040,-0.566449,0.085645,-0.282648,-0.309736,-0.041593,-0.081995,-0.334100,-0.207268,-0.018111,0.096712,0.084664,0.328168,0.347521,0.077466,0.117464,0.118752,0.468032,-0.691060,-0.174282,0.327930,0.129190,-0.053159,0.398245,-0.098420,-0.380521,-0.122930,0.116251,0.131005,0.151882,0.640421,-0.120159,-0.448669,0.112027,-0.023779,-0.113573,-0.138825,0.301711,0.519867,-0.096132,0.573047,0.166996,-0.590651,-0.051490,-0.073264,-0.048714,-0.757524,0.065342,0.079789,0.132281,-0.859021,0.840942,0.302560,-0.208843,-0.196048,-0.437500,0.305125,0.291992,0.131793,0.445399,-0.300728,0.115409,-0.544453,0.195472,0.960940,0.112653,-0.064816,0.334621,-0.143093,-0.339005,0.021259,0.139792,-0.908981,-0.205818,-0.091880,-0.309701,-0.521133,0.007345,-0.756410,0.347401,-0.045453,-0.219421,-0.010447,-0.640604,-0.257997,-0.676316,0.167800,-0.452453,-0.110381,0.289518,0.029794,-0.169645,0.839381,-0.824027,0.155440,0.682100,0.505219,-0.790689,1.225473,0.420163,0.289444,-0.003281,0.017439,0.153162,0.076895,0.320070,0.251180,0.572103,-0.361758,0.402019,-0.556040,0.593628', '3055049', '1302384', '1294364', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30192287', '把哥哥退货可以吗？', '喜剧', '电影《把哥哥退货可以吗》故事叙述了废柴哥哥查（Sunny饰）跟模范生妹妹珍（Yaya饰）从小争斗到大，但又鲁又废的他在优秀的妹妹面前任何事都占不了上风，唯有恶搞妹妹为乐，尤其是在妹妹谈恋爱时，常摆出兄长的架子来逞威风。而这次珍努力发展与日泰混血帅哥小饼（尼坤 饰）的恋情，但查却因不满妹妹的选择，决定要出招来恶搞这对小情人！势死保卫爱情的珍又该如何接招！', '桑尼·苏瓦美塔农', '维塔亚·东俞扬', 5.1, 7450, 'tt8060408', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2550530988.jpg', 10.6, 36.4, 40.6, 9.8, 2.6, '-0.104461,-0.030541,-0.322571,0.516389,0.062286,-0.258807,0.297257,0.213861,-0.230327,-0.202724,-0.053575,0.362243,-0.120150,0.147416,-0.024702,0.076451,-0.202135,-0.606841,0.136682,-0.163982,-0.200129,-0.525972,0.111633,-0.132884,0.066249,0.089928,0.338793,-0.212813,-0.365891,-0.012579,0.687874,0.039487,-0.037143,0.136791,-0.124709,0.092413,-0.327542,0.392109,-0.299082,-0.071415,0.384629,-0.091606,-0.065741,0.140366,0.439779,0.291365,0.655397,-0.397069,-0.141015,-0.022496,0.258269,-0.110254,0.152662,0.144414,0.086497,-0.326759,0.222024,0.057737,0.024308,-0.151082,0.069515,-0.295531,-0.546758,0.261341,0.200746,-0.134450,-0.543213,0.359324,0.013306,0.018247,0.041805,-0.126310,0.191436,0.333918,0.189622,0.272443,-0.252961,0.100206,-0.344252,0.147844,0.454417,0.227574,0.239003,0.383185,0.000216,-0.196006,-0.092082,-0.732492,-0.552040,0.166988,-0.097226,-0.092803,-0.138247,0.329557,-0.336839,-0.229681,-0.115862,0.287987,0.188994,-0.706329,0.126613,0.076280,0.086022,-0.338688,-0.138987,0.393319,0.219668,-0.284183,0.901262,-0.847321,-0.112381,0.389263,0.504242,-0.833654,0.582168,0.353875,-0.097645,-0.469772,-0.288472,-0.027801,-0.084258,-0.210510,0.154354,0.005755,0.239679,-0.296873,-0.320567,0.093349', '1877596', '6963575', '26730542', '1305915');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30192401', '气球', '剧情', '故事发生在1979年冷战期间，冈特（大卫·克劳斯 David Kross 饰）和皮特（弗莱德里奇·穆克 Friedrich Mücke 饰）身处东德统治者的铁腕政权之下，虽然被限制了行动，但是两人并没有放弃对于自由的追求，他们利用长达两年的时间，策划了一起惊天大逃亡。两人动用了手边一切能够得到的资源，制作了一个巨大的热气球，他们打算用最朴素也是最直接的方式，带领着他们的家人逃往西德。然而，就在一行人即将越过边境之际，热气球却因为意外而坠毁了，与此同时，他们的行动也引起了秘密警察的注意，针对他们的追捕很快展开了。一边躲避追兵，冈特和皮特还要一边想方设法制作新的热气球，一场与时间的竞赛开始了。©豆瓣', '弗莱德里奇·穆克', '米夏埃尔·赫尔比希', 8.4, 52343, 'tt7125774', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2586729373.jpg', 0.3, 0.8, 13, 51.7, 34.2, '0.493168,-0.129430,-0.703499,0.625317,0.118052,-0.169121,0.501862,0.072176,-0.726811,-0.360173,0.098554,0.651824,-0.197275,-0.285617,0.223486,-0.300910,-0.552418,-0.860335,0.040407,-0.113135,-0.306608,-0.560172,-0.237459,-0.306279,-0.210234,-0.352933,0.573262,0.178587,-0.139060,0.638991,0.238460,0.090041,-0.099472,0.690510,-0.081825,-0.207037,0.181101,-0.310686,-0.322319,0.356746,0.170338,-0.414602,-0.131282,0.410137,0.084414,0.466409,0.668792,-0.511783,0.036485,-0.216085,0.021833,-0.492983,0.014787,0.123880,0.433805,-0.060115,0.157912,0.362387,-0.177917,0.106514,0.195578,-0.206803,-0.831359,0.085821,-0.114881,0.129491,-0.603816,0.442474,-0.168994,-0.091359,0.099229,-0.491605,0.273832,0.777563,0.469936,0.042081,-0.423304,-0.393375,-0.656870,0.004997,0.755649,-0.092714,-0.160315,0.495324,-0.091792,-0.455603,-0.445628,-0.267694,-0.169409,-0.164262,0.416670,0.318359,-0.132176,0.193404,-0.682952,0.241413,-0.380971,-0.565925,0.113352,-0.561688,-0.020020,-0.847609,0.059137,-0.358047,-0.346219,0.237282,-0.104088,-0.135930,0.607018,-0.764824,0.147858,0.585004,0.530818,-0.409958,0.405784,-0.096545,0.306154,-0.122702,0.007160,-0.071565,-0.080466,0.462551,0.263822,0.318238,0.103430,-0.373554,-0.250076,0.509615', '6790253', '5157137', '1301022', '1306723');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30194752', '边境', '剧情', '缇娜（伊娃·米兰德 Eva Melander 饰）是一位经验非常丰富的海关官员，她拥有着对于犯罪气息异常敏锐的嗅觉，没有一个心怀鬼胎的人能够轻易逃脱的了她的双眼。某日，缇娜遇见了一个名为沃尔（埃罗·米罗诺夫 Eero Milonoff 饰）的男人，直觉告诉缇娜，这个看上去无比正常的男人，正在隐藏着什么惊天大秘密。让缇娜感到无法相信的是，自己竟然不可自持的被沃尔所吸引着，当她和沃尔的距离渐渐拉近之时，缇娜震惊的发现，原来沃尔的秘密和自己亦有着千丝万缕的关联。沃尔的存在让她开始意识到，自己有条不紊的一生其实都是谎言，是继续闭上眼睛苟且偷生，还是勇敢的触碰真相，缇娜需要做出她的选择。©豆瓣', '埃娃·梅兰德', '阿里·阿巴西', 6.8, 8781, 'tt5501104', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2534389119.jpg', 1.7, 7.2, 46.5, 36.4, 8.2, '0.464756,0.056995,-0.848315,0.873174,0.022157,0.229141,0.967738,-0.018864,-0.384277,-0.476009,-0.005576,0.728274,-0.291615,0.156840,0.350567,0.384602,-0.284584,-0.693182,0.163845,-0.417685,-0.136880,-0.705600,-0.577563,-0.171839,-0.189285,-0.519353,0.565977,-0.178231,-0.450528,0.379937,0.303145,0.600831,0.178033,0.768858,-0.020883,-0.313378,0.271366,-0.387198,0.069821,-0.164738,0.565378,-0.039889,-0.171523,0.620345,-0.118095,0.348756,0.595721,-0.824694,-0.216367,0.200192,0.188137,-0.458595,0.301199,0.070412,0.005540,-0.618025,-0.132251,0.250779,-0.175211,0.317325,0.598206,0.013531,-1.053267,0.164615,0.036526,0.420318,-0.476772,0.313782,-0.054092,-0.046898,0.230720,-0.404507,0.152193,0.430194,0.025285,-0.004651,-0.327063,-0.065918,-0.693255,-0.259693,0.674304,0.191342,-0.317048,0.516208,-0.476089,-0.793697,-0.288487,-0.223481,-0.593444,0.118511,0.370660,0.509646,-0.232753,0.314390,-0.396293,-0.282852,-0.395225,-0.154274,0.043991,-0.667296,-0.206052,-0.394170,-0.434324,-0.635753,-0.642636,0.004170,-0.186487,-0.472702,0.776027,-1.033502,-0.278520,0.821860,0.245468,-0.231990,0.638636,0.019789,-0.103234,-0.212080,-0.373211,0.413710,0.158319,0.185236,0.169674,0.536151,0.145529,0.156729,-0.137675,0.691749', '1867335', '25932086', '24756472', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30194769', '女孩', '剧情', '主角 Lara 于15岁之「老龄」才加入芭蕾舞班。由于较其他女孩迟起步，她每日下尽苦功，甚至练到脚尖破皮流血亦不肯歇息。Lara 的梦想不只是成为芭蕾舞蹈员——她还想成为一个女孩。是的，「他」原是家中的长子，名叫 Victor……犹幸爸爸一直在旁鼓励﹑陪她接受荷尔蒙治疗，全心全意支持她完成梦想。', '维克托·波尔斯特', '卢卡斯·德霍特', 8.1, 37029, 'tt8254556', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2519456723.jpg', 0.3, 1, 17.2, 56.5, 25, '-0.163795,-0.236053,-0.720284,0.201176,-0.465886,-0.322571,0.320807,-0.009754,-0.100317,-0.469971,0.276084,0.376771,0.293274,0.443292,0.112102,-0.251244,0.044180,-0.516790,0.244548,0.156045,-0.280974,-0.130476,-0.069555,0.039718,-0.656170,-0.392860,0.717880,-0.082670,-0.085528,0.333240,0.180319,-0.202059,0.195079,0.094849,-0.367751,-0.307360,0.028680,-0.067672,-0.103633,0.231860,0.178376,-0.565872,-0.046303,-0.195092,0.107782,0.142787,0.571364,0.128460,0.022874,-0.190019,0.092950,-0.406825,-0.086494,0.010561,0.127220,-0.100521,0.360114,0.164589,0.133111,0.080985,-0.241615,-0.360330,-0.684328,-0.018431,0.550397,0.239144,-0.589719,0.509510,-0.282745,-0.122028,-0.129156,-0.325263,-0.069741,0.325844,-0.113564,0.229916,-0.510018,0.115018,-0.265133,0.327497,0.635941,0.086456,-0.343835,0.393830,-0.072156,-0.443171,0.352343,-0.343820,-0.416533,-0.058793,-0.490585,0.130548,0.075361,-0.396216,-0.192671,0.093650,-0.099465,-0.315054,0.198112,-0.229153,0.388269,-0.363514,0.255546,-0.210036,-0.302945,-0.051343,0.171142,-0.813166,0.876331,-0.900495,0.457058,0.509115,0.459181,-0.715375,0.729107,0.073539,0.342586,-0.105644,0.338450,0.452331,-0.228735,-0.122849,-0.252772,0.183398,-0.069083,0.171387,-0.570203,0.334199', '1877596', '1308499', '1308424', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30195228', '男人要自爱', '喜剧', '在一个由女人主宰的世界里苏醒后，一名无耻的大男子主义者因与一名有权势的女作家发生争执而自食苦果。', '樊尚·埃尔巴兹', '埃莱奥诺尔·普里亚', 7.6, 15609, 'tt6857988', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2522124933.jpg', 0.5, 3.4, 31.5, 46.4, 18.2, '0.329564,0.658942,-0.899051,0.924155,-0.731100,-0.054583,1.472292,0.308144,-0.602458,-0.250592,0.312100,1.342418,0.045791,0.421195,0.818484,-0.348639,0.459771,-0.674872,-0.052110,-0.663234,-0.468741,-0.195299,-0.353494,-0.350076,-0.558667,-0.701738,1.223875,0.217337,-0.213534,-0.117210,0.712551,0.172261,-0.026668,0.454348,-0.283741,-0.531044,0.374740,0.219391,-0.244089,0.617696,-0.068722,-0.291718,-0.020465,0.065677,-0.904438,0.081961,0.799432,-0.989556,-0.103669,-0.809990,0.502628,-0.179739,-0.328660,0.318285,0.567507,-0.188841,0.138908,0.258217,0.027392,0.163557,0.173781,0.028770,-1.458214,-0.702930,0.093738,0.185705,-0.357937,0.606897,0.147696,-0.405280,-0.149097,-0.011341,0.139933,0.137032,0.540421,0.855106,-0.277140,0.041472,-0.308808,-0.174482,0.735575,-0.001204,-0.524577,0.422315,-0.002354,-0.564507,0.122323,-0.603727,-1.098893,-0.420862,0.020400,-0.103108,-0.153574,0.231655,-0.882938,0.223137,-0.162911,0.227804,0.021615,-0.281913,-0.530426,0.085678,-0.081267,-0.326291,0.224521,0.303187,0.523227,-0.131518,1.209595,-0.846215,0.371558,0.551684,0.272905,-1.006759,0.865058,0.146354,0.561139,-0.622210,-0.203189,0.507958,0.259707,0.039475,-0.170636,0.369347,-0.463932,0.047096,-0.175146,0.204239', '4847665', '26884422', '26667010', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30196755', '世界奇妙物语 2018年春季特别篇', '科幻', '《关注者》某小公司职员藤田小春（白石麻衣 饰）在网上将自己打造成香车、包包、富豪男友环绕的闪亮港区OL，为了不输给网络上的竞争对手，她落入了奢靡虚荣的深坑，与此同时有位网络好友似乎识破了她的真面目。《外遇警察》在民众的呼吁下，日本政府成立出轨取缔厅，对不伦出轨行为施以最严厉的打击。某公司部长葛木良男（唐泽寿明 饰）小心谨慎，生怕瓜田李下的事情发生。然而，一系列误会之后他还是引来了出轨取缔厅的官员。《穿越到明天》独立电影导演小林峰雄（三浦春马 饰）奋斗多年，仍然无法得到证明自己的机会。经心理医师建议，他服用了一种可以清除之后24小时记忆的药物减缓压力。换言之，这种药物可以删除随后的痛苦，让人安全穿越到未来。《少年》一个因车祸入院治疗的神秘少年，不知为何始终逡巡在OL小遥（仓科加奈 饰）的身边。直到某天，少年借住小遥家中，他们之间似乎有着更深远的联系。', '三浦春马', '植田泰史', 7.4, 11598, '世界奇妙物语 ''18春之特别篇', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2522281465.jpg', 0.5, 3.4, 35.2, 45.3, 15.6, '0.053783,0.062378,-0.366203,0.335626,-0.090598,0.030480,0.592427,0.218137,-0.499085,-0.212593,0.491165,0.374751,-0.157999,0.111022,0.328234,-0.008467,-0.303521,-0.520220,0.118647,-0.141194,-0.317116,-0.377600,-0.247304,-0.369955,-0.139948,-0.475897,0.641156,0.202910,-0.360941,0.141661,0.111101,0.284481,-0.081093,0.510762,0.133508,0.076160,0.113256,-0.053830,-0.311413,0.233745,0.040101,-0.450257,0.012922,0.282194,-0.050022,0.326687,0.595808,0.005988,-0.457426,-0.106135,0.644092,0.010989,-0.057618,0.021163,0.415645,0.190838,0.171859,0.256554,-0.258264,-0.031994,0.166890,0.220264,-0.447953,-0.060621,0.086175,0.312471,-0.157449,0.475067,-0.096045,0.065243,0.012448,-0.190954,-0.077597,0.208366,0.228547,0.047217,-0.283534,0.361004,-0.256951,0.276638,0.448356,-0.019813,-0.221375,0.243317,-0.228120,-0.290102,-0.087710,-0.169143,-0.420010,-0.092401,0.299873,0.150420,-0.279095,0.177847,-0.227497,-0.197038,-0.122796,-0.145309,0.130749,-0.249070,-0.116155,-0.575040,-0.209507,-0.175131,-0.211812,0.090533,0.186989,-0.227704,0.721416,-0.787661,0.044462,0.668110,0.368232,-0.498255,0.539546,0.019661,-0.037783,-0.231095,-0.228164,0.179548,0.063177,0.501378,0.031710,0.165532,-0.096801,-0.128960,-0.249945,0.122938', '25