INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30198539', '痛苦与荣耀', '剧情', '佩德罗·阿莫多瓦、安东尼奥·班德拉斯、佩内洛普·克鲁兹将合作新片《痛苦与荣耀》(Dolor y Gloria)，7月上半月开拍。和阿莫多瓦上部影片《胡丽叶塔》相反，影片主角将是两名男性，由班德拉斯和阿谢尔·埃特塞安迪亚扮演，克鲁兹和胡丽叶塔·塞拉饰女配，讲述一个处于晚年的电影导演的生活故事，包含初恋、第二次恋爱、母亲、死亡、与他合作过的一些演员，时间跨越60、80年代和现在，一种不适应的空虚感导致他现在无法拍电影。', '安东尼奥·班德拉斯', '佩德罗·阿莫多瓦', 8.5, 79167, 'tt8291806', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2593729173.jpg', 0.3, 1, 11.7, 46.3, 40.7, '0.273324,-0.229118,-0.291058,0.672077,0.276778,-0.143733,1.247233,0.046240,-0.396295,-0.451097,-0.041781,0.773861,-0.383934,-0.025403,0.289537,-0.056722,-0.698715,-0.670261,-0.010359,-0.001055,0.042254,-0.558571,-0.328477,0.168647,-0.326433,-0.740793,1.014786,-0.346512,-0.113953,0.487074,0.179085,0.334837,0.214641,0.176860,0.313568,0.223057,0.362136,-0.090099,-0.552760,0.394070,0.340378,0.131283,-0.246456,-0.029097,0.159220,0.260834,0.489806,-0.065099,0.129001,-0.069473,0.474619,-0.162445,-0.206592,0.202933,0.003488,-0.174739,0.407577,0.361687,0.132613,-0.170630,-0.173164,-0.237309,-0.774769,0.387726,-0.103295,0.116689,-0.393873,0.426875,-0.393881,-0.160356,0.084129,-0.353758,0.001154,0.455050,0.678297,0.328171,-0.308793,0.017391,-0.468908,0.304354,0.865371,0.022416,-0.300125,0.590318,-0.180535,-0.600974,-0.842597,-0.064324,-0.846375,0.137962,0.147747,-0.142536,0.014432,0.513348,-0.499060,-0.022708,-0.240148,-0.376167,-0.028404,-0.349283,0.148011,-0.851742,-0.528015,-0.286036,-0.288153,-0.543180,0.480698,-0.437788,0.535131,-0.571195,0.302994,0.483906,0.453959,-0.178675,1.089520,0.478642,0.135353,-0.642383,0.194125,0.541015,-0.241045,-0.217006,0.165521,0.468597,0.067916,0.208989,-0.332103,0.850885', '1305666', '1291835', '1316693', '1417428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30198715', '吹哨人', '剧情', '一通深夜来电，打破了澳洲华人职员马珂（雷佳音 饰）的平静生活。消失多年的前女友周雯（汤唯 饰）突然出现、神秘杀手接踵而至。面对层层追杀，马珂带周雯奔赴非洲寻找真相。他逐渐意识到，自己正在负责的跨国交易背后另有阴谋，是做个“吹哨人”向社会公布真相？还是视而不见明哲保身？马珂不得面对两难选择。与此同时，马珂发现本以为和自己“同病相怜”的周雯也绝不是看上去那么“简单”。真相越埋越深，更大的危机也正在逼近……', '雷佳音', '薛晓路', 5.3, 36764, 'tt8971476', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2572746113.jpg', 10.4, 33.1, 40.7, 12.4, 3.4, '0.203998,-0.085285,-0.634333,0.299069,-0.012177,0.134178,0.518578,0.046607,-0.447467,-0.460999,0.193448,0.567141,-0.168210,0.136346,0.394236,0.012369,-0.280690,-0.628650,-0.099638,0.056202,-0.155550,-0.620792,-0.302081,-0.316596,0.032935,0.092111,0.503768,0.428179,-0.443617,0.009612,0.414317,0.618034,-0.392428,0.687684,0.235323,-0.207082,0.073891,-0.139627,-0.283029,0.009667,0.007102,-0.337572,-0.162068,0.177312,-0.251240,0.361220,0.333281,-0.176561,-0.466358,-0.051393,0.454660,-0.663616,-0.276239,-0.123567,0.352039,0.036565,0.102138,0.195982,-0.252984,0.175160,-0.187819,-0.001071,-0.481685,0.229206,0.050577,0.327506,-0.222735,0.015478,0.077051,0.001679,0.242525,-0.391348,0.070276,0.464577,0.333548,0.170005,-0.269015,0.179534,-0.431203,-0.053587,0.749686,0.223273,-0.000796,0.205817,0.245029,-0.195008,0.179633,-0.110018,-0.219138,-0.164188,0.136271,0.393876,-0.171148,0.335637,-0.133424,0.027772,-0.137817,-0.164696,0.193459,-0.481296,-0.265429,-0.319435,-0.387549,-0.125611,-0.260549,0.281996,-0.166454,-0.234349,0.480813,-0.569828,0.100170,0.341540,0.238295,-0.504895,0.276702,0.091869,-0.140521,-0.392495,-0.085946,0.407822,0.034110,0.106038,-0.033582,-0.197098,0.020200,-0.263021,-0.198082,0.001483', '1292064', '1301022', '25870679', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30198729', '新大头儿子和小头爸爸3：俄罗斯奇遇记', '动画', '小头爸爸带全家去俄罗斯出差，大头儿子在俄罗斯发现了自己画的白夜城是真实存在的，一家人半路遇到交通事故，被迫夜宿小旅馆，第二天醒来发现身处大头儿子画中的世界——白夜城。他们发现如果不解决白夜城中的危机便无法走出这个世界，一家人在白夜城中经历了重重困难终于回到了现实世界。', '刘纯燕', '何澄', 4.8, 4364, 'tt8669442', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2522820714.jpg', 27.1, 24.8, 36.1, 6.8, 5.3, '0.122284,0.637090,-0.785952,-0.150401,-0.162746,-0.209535,0.411095,0.126681,-0.524832,-0.511520,0.227638,0.818349,0.178707,0.536564,0.261437,0.190019,-0.544269,-0.276340,0.165718,-0.512405,-0.561839,0.078525,0.122425,-0.151963,-0.062407,0.236191,0.382008,0.407664,-0.007245,0.239642,-0.036615,-0.057052,-0.506789,0.710868,-0.507126,0.318530,0.132389,0.169290,-0.245570,0.412976,-0.251172,0.235376,-0.456074,0.104909,0.143350,-0.118586,0.884390,-0.225406,-0.407792,-0.123971,0.163487,-0.547518,-0.393476,0.023149,0.476890,-0.246728,0.246099,-0.103530,-0.102284,-0.169648,-0.150714,-0.239190,-0.161854,0.170352,0.172484,-0.010554,-0.332000,-0.007874,0.016526,-0.241083,0.181309,-0.584168,0.533922,0.662470,0.486999,0.504116,0.111077,0.197988,-0.743331,-0.221521,0.587777,-0.464678,-0.201311,0.270776,0.189219,-0.223878,-0.100048,-0.160802,-0.173936,0.265677,0.481770,0.003562,-0.818076,0.253761,-0.368165,-0.009384,-0.353405,-0.229045,0.177742,-0.340397,-0.427488,-0.398935,-0.217937,-0.141802,-0.029597,0.469158,-0.094536,0.149888,0.261668,-0.766679,0.385623,0.561878,0.388015,-0.188675,0.665038,0.008226,-0.202843,-0.645248,0.328991,0.576039,0.012617,0.694445,-0.149648,0.018766,-0.281343,-0.082573,-0.604791,0.333996', '1438591', '1300359', '1299433', '1293019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30200973', '一级指控', '动作', 'CK律所在城中是一家声名卓著的律师事务所，合伙人之一雷有辉（方中信饰演）更有法律界“常胜将军”的声誉，却在十年前的成富商场倒塌案中令一众商户败诉。城中首富郭世荣（廖启智饰演）的女儿郭嘉仪在工作室中离奇暴毙，当年商户珠妈（鲍起静饰演）的孙儿李逸峰因在现场而作为嫌疑人被捕，并被控以一级谋杀罪名！珠妈面对孙儿被控谋杀手足无措， 只能求助法律援助。雷有辉律所的合伙人张美仪接受了珠妈这宗法援，派出律所新人何学铭（陈嘉乐饰演）负责。为了补偿十年前的官司败诉的愧疚，雷有辉也决心协助何学铭为李逸峰沉冤昭雪。在调查的过程中，雷有辉抽丝剥茧，发现案件另有隐情，却遭遇证人反口、证剧被毁、同僚遇害……如何将真凶绳之以法，雷有辉唯有在最后的庭审中绝地反击！', '方中信', '黄国辉', 5.4, 10942, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2691890349.jpg', 5.4, 31.7, 53.2, 8.7, 1, '-0.152789,0.065671,-0.338052,0.350118,0.124518,-0.089252,0.409528,0.281160,-0.480278,-0.405241,0.427597,0.612132,-0.050906,0.238198,0.302852,-0.387108,-0.042095,-0.590545,-0.186118,-0.380375,-0.080778,-0.558220,-0.011040,-0.133697,-0.008735,-0.080536,0.672550,0.319477,-0.167678,0.212354,0.566706,0.411428,-0.392005,0.180730,0.024372,0.033221,0.182322,0.003676,-0.567658,0.185718,-0.114898,-0.521511,-0.128329,0.020457,-0.005172,0.479491,0.387637,-0.012752,-0.212679,-0.366613,0.328305,-0.392792,-0.015549,0.068240,0.577497,0.037613,0.253101,0.525472,-0.354802,-0.156847,-0.009912,-0.062236,-1.130387,-0.170209,0.507546,0.103752,-0.490593,0.188635,-0.166739,0.054276,-0.115542,0.071766,0.287295,0.333926,0.088078,0.318785,-0.318423,0.151085,-0.492419,0.328167,0.481122,-0.090587,0.079904,-0.093917,0.058029,-0.586382,0.322670,-0.442053,-0.117555,0.141734,0.139479,0.009042,0.093234,0.211518,0.022599,-0.271059,-0.329459,0.073735,-0.098813,-0.207419,-0.093025,-0.395203,-0.059391,0.137436,-0.069801,-0.002763,0.156075,-0.439092,0.332955,-0.554994,0.032242,0.413514,0.315403,-0.610346,0.473587,0.265132,0.373966,-0.230655,-0.339269,0.085016,0.294126,0.321530,-0.021413,-0.302425,-0.211323,-0.437040,-0.304259,-0.085328', '26678784', '27073234', '3670447', '1793491');
