INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30204142', '女警', '喜剧', '讲述虽然是传说中有名的Ace刑警，但在结婚后就到了民怨室工作的美英(罗美兰)和闯祸后被驱逐到民怨室的警察智慧(李圣经)相遇，偶然追赶犯罪事件的喜剧动作故事。故事中罗美兰饰演过去是机动队的王牌，结婚生子后放弃了梦想在民怨室担任主务工作的警察美英。李圣经饰演虽然在强力班抱有梦想但因为意欲过多接连发生事故后被派遣往民怨室的智慧。影片描写了两人偶然卷入犯罪事件，并一起扫荡犯人的喜剧过程。 罗美兰和李圣经虽然互相争吵的关系，但在抓捕犯人面前却不惜肆意展现义气的桀骜不驯的魅力，在调查过程中展现出的两位演员的武打动作也将给观众带来趣味性。————翻译转自@罗美兰-中文饭团', '罗美兰', '郑多元', 6.9, 31020, 'tt10161238', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2553964373.jpg', 0.8, 7.8, 49.4, 30.4, 11.5, '0.270802,0.038268,-0.726562,0.526151,0.090304,-0.186344,0.989606,0.143298,-0.410554,-0.354259,0.150654,0.265370,-0.384694,-0.070819,0.281295,-0.490164,-0.340581,-0.882964,-0.127138,0.055658,-0.428499,-0.407399,0.156716,-0.265103,-0.210911,-0.364440,0.531147,-0.044301,-0.703601,0.300312,0.399547,0.239834,-0.275058,0.476380,-0.013181,0.264412,0.222610,0.272548,-0.475520,0.180277,0.271827,-0.494098,-0.392887,-0.002535,0.261906,0.170656,0.909214,0.021938,-0.157044,0.229998,0.352323,-0.258200,-0.102660,-0.020767,0.695692,0.224192,0.299813,0.263002,0.316071,-0.070734,0.004514,-0.223951,-0.754073,0.014186,0.190874,0.273031,-0.336064,0.168278,0.044793,0.182759,0.152554,-0.133243,0.111346,0.273965,0.439764,0.421731,-0.042078,0.341916,-0.582312,0.280600,0.473027,0.024390,-0.263204,0.368540,-0.280624,-0.591391,-0.314948,-0.100396,-0.277057,0.022761,0.426529,-0.238297,0.009055,0.435872,-0.666301,-0.304263,0.147988,0.094695,-0.009325,-0.301156,-0.021436,-0.773644,-0.093364,-0.378442,-0.149007,0.064420,0.183103,-0.230313,0.759985,-0.462226,0.326420,0.514037,0.013192,-0.560504,0.645927,0.349765,0.280318,-0.111640,-0.008378,0.099869,0.355511,0.484810,0.215686,0.337303,-0.053372,-0.363144,-0.386352,0.260764', '10466639', '21619567', '1467779', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30204413', '气球', '剧情', '《气球》故事发生在藏地，讲述灵魂与现实的紧张关系。主人公达杰一家因一只普通的避孕套卷入了一系列尴尬而又难以抉择的事件当中，他们原本宁静的日常生活被彻底打破，生老病死如日月流转，当灵魂遭遇现实的挑战，该如何抉择？', '索朗旺姆', '万玛才旦', 7.7, 80114, 'tt10703752', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2623499790.jpg', 0.2, 1.5, 24.7, 60.6, 13, '0.462059,0.323098,-0.356887,0.343649,0.184465,0.060485,0.836794,0.411855,-0.493711,-0.586393,0.197588,0.607081,-0.415912,-0.139031,0.281243,-0.200969,-0.066756,-0.813566,-0.044298,0.180955,-0.083804,-0.446400,-0.011545,-0.049071,0.257770,-0.103590,0.743310,0.271079,-0.505262,0.089781,0.190147,0.659193,-0.565429,0.280917,0.112964,-0.105945,-0.263494,0.387334,-0.581891,-0.336651,-0.150706,-0.274754,0.154710,0.207184,-0.213777,0.230284,0.813068,-0.321989,-0.414028,0.100763,0.573598,-0.334824,-0.248420,0.206894,0.133238,0.315425,-0.052425,0.022761,-0.141455,0.063412,0.157325,-0.066831,-0.897797,-0.173601,0.184459,0.374490,-0.040046,0.124888,0.409291,0.173153,-0.022666,-0.018359,0.162340,0.549089,0.977235,0.869195,-0.202843,-0.128913,-0.328932,0.032745,1.015582,-0.141496,-0.706392,0.631153,-0.414412,-0.328019,-0.416861,-0.271598,-0.564452,0.172135,0.585090,0.615790,-0.565550,1.105210,-0.518214,-0.104736,-0.191574,-0.245441,-0.134137,-0.552123,-0.137355,-0.230686,-0.384878,-0.289345,-0.416569,-0.176793,0.036003,0.038177,0.403142,-0.549711,0.334014,0.410211,-0.295024,-0.236485,0.118585,0.501244,0.393364,-0.299386,0.305267,0.552251,-0.069783,0.259333,0.033321,0.117440,-0.180353,0.349902,-0.620065,0.204685', '26277156', '2988294', '25828589', '3743052');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30205168', '篮球冠军', '剧情', '马尔科（哈维尔·古铁雷斯 Javier Gutiérrez 饰）是西班牙职业篮球甲级联赛中的第二教练，个性向来傲慢无礼的他，因为和球队的第一教练之间爆发了激烈的争吵而惨遭球队解雇。之后，靠喝酒来抒发心中郁闷情绪的马尔科驾车撞倒了一辆警车，并且最终成功的将自己弄进了警察局。法官给了马尔科两个选择，要么坐牢两年，要么去社区服务一个半月，马尔科毫不犹豫的选择了后者。就这样，马尔科成为了一支名为“Los Amigos”的球队的教练，这支球队里的选手全部都是精神残障者，而帮助马尔科训练的，是名叫朱里奥（胡安·马加略 Juan Margallo 饰）的老者。在解决自己的职业麻烦的同时，马尔科还需要修复自己和妻子之间的关系。©豆瓣', '哈维尔·古铁雷斯', '哈维尔·费塞尔', 7.2, 5924, 'tt6793580', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2550534680.jpg', 0.2, 3.8, 42.8, 41.1, 12.2, '0.270150,0.072465,-0.432565,0.692322,-0.400579,-0.560175,0.348095,0.150551,-0.397083,-0.089322,0.133434,0.855896,0.062817,0.230257,0.466698,-0.233079,0.035178,-0.988407,-0.238928,0.027208,-0.460310,-0.699702,-0.148753,-0.398067,0.031222,-0.215909,0.726171,-0.193109,-0.161196,0.481552,0.236464,0.384101,0.438249,0.206987,0.043260,0.122128,0.278824,-0.212801,-0.062849,0.337858,0.186976,-0.163531,0.077632,0.223744,0.235222,0.334326,0.598980,-0.123772,0.089396,-0.023119,0.190467,-0.272656,0.048384,0.178978,0.404146,-0.128362,0.295550,-0.019414,-0.065908,0.205095,-0.014149,0.136579,-0.871926,0.049926,-0.139210,-0.129072,-0.661977,0.691085,-0.142659,-0.101780,0.241329,-0.110942,0.198344,0.320690,0.375366,0.154900,-0.232493,-0.267860,-0.298920,0.119608,0.531242,-0.162851,-0.211419,0.147227,-0.318380,-0.338151,-0.105206,-0.284611,-0.337097,-0.207444,0.519528,0.128660,0.129492,-0.020757,-0.623622,0.119157,-0.200391,-0.210445,-0.277782,-0.311606,0.271947,-0.451006,0.104497,-0.333035,-0.228998,0.042874,0.025703,-0.018170,0.628475,-0.727977,-0.025985,0.660788,0.070562,-0.459908,0.528491,-0.003213,0.447116,-0.140018,0.014035,-0.012318,0.025152,0.200441,0.099369,0.625241,0.107942,-0.138487,-0.247468,0.527817', '30345227', '1308815', '26809007', '1292943');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30205667', '温泉屋的小老板娘', '动画', '小学六年级的小织，在父母车祸双亡后被经营温泉旅馆「春之屋」的外婆收养，也开始了她的小女将修行之路。少根筋又冒失的她，时常被敌对旅馆同龄之女秋野真月嘲笑。但生性乐天的小织，在旅馆里的幽灵小卖、美阳及铃鬼鼓励之下，努力地招待每位客人。是一部温暖且欢乐的女孩成长记。', '小林星兰', '高坂希太郎', 7, 11943, 'tt8328740', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2631409396.jpg', 0.8, 5.8, 44.8, 39.6, 9, '0.526168,-0.077534,-0.712837,0.282968,-0.429349,-0.440994,0.512094,0.422382,-0.502143,-0.046905,0.458288,0.709106,-0.218158,0.715743,0.112569,-0.036245,0.133694,-0.509113,0.055118,-0.231044,-0.103828,0.014505,-0.092160,-0.046824,-0.256313,-0.209680,0.088552,0.204582,0.101527,0.302125,-0.305966,0.147912,-0.049049,0.309495,-0.335339,0.066198,-0.193107,0.130862,0.118029,0.052935,-0.172042,-0.174974,-0.122571,0.162977,0.252035,0.458314,1.035264,-0.161591,-0.133569,-0.291467,0.284321,0.091691,-0.012990,0.251495,0.456341,0.180649,0.333354,0.294746,-0.216753,-0.144134,-0.066036,-0.195296,-0.296662,0.133810,0.058804,-0.016019,-0.723732,0.442991,0.192743,0.036234,0.122370,-0.247511,-0.061882,0.119249,0.036314,0.694500,-0.203754,0.160911,-0.289159,0.110488,0.489153,-0.371833,-0.132543,0.518086,-0.369678,-0.390941,0.270545,-0.010184,-0.722722,-0.132329,0.317720,-0.168188,-0.326868,0.152342,-0.679368,-0.044033,-0.218685,0.131015,-0.149028,-0.394185,-0.381097,-0.797181,0.197425,-0.301707,-0.303757,-0.306065,0.280787,-0.170168,0.926981,-1.102882,0.040944,0.943847,0.441025,-0.430088,0.598059,-0.000263,0.303971,0.249443,-0.064558,0.235769,-0.048816,0.506713,0.095627,0.477000,-0.326616,0.146928,-0.688757,0.494548', '3811356', '25922902', '1418179', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30206311', '寂静之地2', '科幻', '故事紧承上一部展开。在丈夫为保护家人牺牲后，伊芙琳（艾米莉·布朗特 饰）不得不独自带着孩子们（米莉森·西蒙斯、诺亚·尤佩 饰）面对全新的生存挑战。他们将被迫离开家园，踏上一段未知的旅途。在无声的世界里，除了要躲避“猎声怪物”的捕杀，铺满细沙的道路尽头还暗藏着新的危机。', '艾米莉·布朗特', '约翰·卡拉辛斯基', 6.4, 155966, 'tt8332922', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2651298629.jpg', 1.5, 12.3, 54.5, 27.9, 3.9, '-0.013551,0.058646,-0.461559,0.638759,-0.016121,-0.164501,0.728056,0.143365,-0.452839,0.011920,0.476931,0.551079,0.086390,0.225322,0.275691,-0.216830,-0.526176,-0.403152,-0.212833,-0.076609,-0.557328,-0.484317,-0.436410,-0.264714,-0.136928,-0.448617,0.878243,0.337028,-0.183771,0.296380,0.088212,0.220350,-0.788647,0.499186,-0.227896,-0.057063,-0.142402,0.019925,-0.563244,0.296632,-0.114347,-0.111695,-0.365618,0.117546,-0.291372,0.194309,1.030072,-0.663948,0.380334,-0.176150,0.023952,-0.400498,0.139612,0.126288,-0.010738,0.008043,0.015465,0.530028,-0.185450,0.258270,0.334836,-0.244078,-0.661630,-0.202877,0.087745,0.332612,-0.832229,0.236146,0.003653,-0.081939,0.504097,-0.462029,0.037192,0.276810,0.342356,0.558615,-0.321849,0.122363,-0.377965,-0.008195,0.540685,-0.281525,0.007491,0.302555,-0.073717,-0.064670,0.060168,-0.053649,-0.816042,-0.415635,0.163219,0.216766,-0.106519,0.215457,-0.990403,0.108770,-0.285579,-0.590179,0.063934,-0.519297,-0.138456,-0.682548,0.288396,-0.044653,-0.155488,0.451071,-0.011570,-0.249544,0.692021,-0.538595,0.557673,0.637216,0.351104,-0.367810,0.670164,-0.055843,0.531521,-0.134916,-0.003256,0.756285,-0.096449,0.436186,-0.005068,0.005495,-0.216462,0.201909,-0.482173,0.694774', '1294917', '26290398', '21619567', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30206431', '过昭关', '剧情', '暑假，七岁的宁宁被送回乡下，由七十多岁的爷爷李福长照顾。李福长偶然间得到了一个老朋友的联系方式，老友身体中风，时日无多。他决定带上孙子，骑着一辆摩托三轮车，去千里之外看望老友。影片以“过昭关”喻指人生，是难得一见的中国乡村公路片。', '杨太义', '霍猛', 7.8, 19856, 'tt9496220', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2556430298.jpg', 0.4, 3.3, 24.7, 49.1, 22.6, '-0.133591,-0.257025,-0.241995,0.505406,-0.266180,-0.492256,0.364927,0.283055,-0.634324,-0.429359,0.038268,0.931325,0.207760,0.553279,0.352316,0.056053,-0.153561,-0.100054,0.048761,0.089586,-0.357882,-0.093104,0.010180,-0.001522,0.198450,-0.182613,0.393799,-0.125458,0.191614,0.770673,-0.201801,-0.043738,-0.044423,-0.048545,-0.866116,0.216228,-0.308951,0.170883,-0.305468,0.385188,-0.213310,0.164583,0.325428,-0.373304,0.015958,0.135356,0.802829,0.534582,-0.321395,-0.241961,0.341263,-0.009512,0.061913,-0.229369,0.438915,0.210925,0.436166,-0.014957,-0.013181,-0.095177,-0.155489,-0.280722,-0.049990,0.108708,-0.183720,-0.326379,-1.058919,0.184623,-0.194108,-0.225327,-0.024800,-0.638715,0.636875,0.063145,-0.279944,0.631865,-0.185773,0.395737,-0.534584,0.349049,0.561256,-0.266488,0.137384,0.305084,-0.196998,0.008098,0.522652,-0.383717,-0.597421,0.320525,0.030168,-0.475002,-0.399245,-0.110943,-0.412016,-0.281499,-0.387785,-0.254192,0.319335,-0.272332,-0.200829,-0.317364,0.155544,-0.126289,0.260055,-0.088818,0.252975,-0.044446,0.692212,-0.350221,0.381331,0.333808,0.242682,-0.480529,1.178592,-0.102832,0.328905,-0.520151,0.483641,-0.013188,-0.007184,0.383843,-0.230753,0.066102,-0.125702,-0.075997,-0.746964,0.073220', '1306505', '1304758', '2080130', '26596361');
