INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30207919', '安娜贝尔3：回家', '悬疑', '故事背景就发生在驱魔名人艾德与罗琳华伦这对恶魔学巫术顾问夫妇的家中；他们在各地为有需要的人驱魔，并且为了防止这些恶魔邪灵再度危害人间，他们将那些被诅咒、被鬼附身甚至被拿来举行邪教仪式的物品带回家中，放置于神器室兼灵异博物馆中加以保存，并且固定时间请神父来祈福、净化，而邪恶到连罗琳华伦都不想与它正面直视的安娜贝尔就是被华伦夫妇灵异博物馆「收藏」的物品之一。在某个不洁的夜里，通往华伦夫妇灵异博物馆的大门被开启，华伦夫妇女儿茱蒂的朋友进入了灵异博物馆内，不知事态严重性的她，不经意地将安娜贝尔释放出来，带领着馆中所有被释放出的恶灵，苏醒过来的安娜贝尔与恶灵们有了全新的目标：华伦家的女儿茱蒂与她的好朋友…', '维拉·法米加', '加里·多伯曼', 6.1, 32882, 'tt8350360', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2557085889.jpg', 3.9, 21.2, 50.8, 16.4, 7.7, '0.679462,-0.016210,-0.648145,0.466479,-0.165482,0.103087,0.831464,-0.095322,-0.567161,-0.485389,0.415095,0.806688,-0.249488,0.167461,0.280216,0.149591,-0.352512,-0.627140,-0.155834,-0.314713,-0.368330,-0.252075,-0.228258,-0.206314,-0.237134,-0.451592,0.352396,0.037073,-0.044778,0.115606,0.014914,0.639040,-0.289158,0.156859,-0.235383,0.106920,-0.006776,-0.195330,-0.213039,0.361086,0.122124,-0.187455,0.011240,0.170258,0.130590,0.097421,0.687352,-0.520806,0.119489,-0.240758,0.251771,-0.254405,0.074884,0.378242,0.244085,0.256342,0.284321,0.323815,-0.300123,-0.017469,0.220385,-0.101733,-0.840816,0.087558,0.199154,0.146862,-0.408842,0.399034,-0.059952,-0.073635,0.191827,-0.364770,0.557532,0.354051,0.218595,0.280072,-0.097724,-0.157200,-0.537570,0.010689,0.292773,-0.344229,-0.260360,0.129698,-0.200732,-0.506283,-0.010835,-0.193794,-0.276917,-0.115238,0.492544,0.291639,-0.082502,0.490184,-0.797740,-0.314078,-0.221227,-0.292960,0.076303,-0.220432,-0.145044,-0.867240,0.005682,-0.192192,0.035354,-0.096803,0.200659,-0.293845,0.686962,-0.861669,0.391681,0.640892,0.493996,-0.489129,0.643237,-0.262120,0.461489,0.016201,-0.370027,0.052822,0.434058,0.789144,0.171074,0.400275,0.191558,-0.008181,-0.325553,0.367667', '11810348', '25774050', '1297659', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30207949', '黄飞鸿之南北英雄', '动作', '晚清时期，外来入侵，国家内忧外患，民不聊生。黄飞鸿（赵文卓 饰）面对列强的压迫，依旧弘扬中国文化，保护民族信仰，与外来者的打击坚持抗争。在这样一个社会动荡的时期，北拳宗师吴镇南（唐文龙 饰），初入佛山北拳南传，却屡屡碰壁，面对黄飞鸿的盛情款待，吴镇南却不愿接受他的帮助。就在这个时候，洋人趁火打劫，把药品研究用在了吴镇南身上，导致两人矛盾再度激化，面对洋人的利用和威胁，吴镇南不得不和黄飞鸿展开激烈的一战。被洋人雇佣来协助研究项目的女孩路小月（魏小欢 饰）在秘密研究项目中也慢慢了解到洋人的残暴实验，渐渐地看清了洋人计划，危险一触即发……', '赵文卓', '林珍钊', 4.5, 7290, 'tt8787116', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2610156527.jpg', 20.3, 41.8, 32.7, 3.7, 1.5, '0.264596,0.178178,-0.709717,0.535258,0.072261,-0.100245,0.353819,0.144496,-0.626667,-0.277100,0.275857,0.207338,0.020423,-0.299597,0.122634,-0.642782,-0.050516,-0.641306,0.006861,0.239544,-0.318106,-0.518953,-0.572117,-0.370016,-0.432428,-0.205279,0.595177,0.532966,-0.811943,0.326802,0.200530,0.327460,0.060092,0.640689,0.022660,-0.436286,0.145544,0.073866,-0.543550,0.091471,0.224253,-0.681235,-0.177033,0.368466,-0.058485,0.381789,0.488247,-0.346835,0.057302,-0.189399,0.159810,-0.179351,-0.321530,0.053012,0.419499,0.015418,-0.244545,0.114218,-0.109709,0.050018,-0.139240,0.114051,-0.527391,-0.014665,0.423189,0.146739,-0.725983,0.312861,0.069410,-0.020939,-0.203547,-0.313502,0.141191,0.576474,0.470800,0.529668,-0.037495,0.192964,-0.367619,0.154372,0.462447,-0.160167,-0.209053,-0.198069,-0.223194,-0.469417,-0.077512,-0.536183,-0.306460,-0.207224,0.123433,-0.266197,-0.136310,0.378064,-0.792832,-0.137545,-0.175598,-0.082704,0.104899,-0.140525,0.229556,-0.630864,-0.270591,-0.330703,0.011849,0.109456,0.298634,-0.182280,0.821583,-0.686695,-0.018025,0.424827,0.590968,-0.689660,0.336455,0.261015,-0.058909,-0.375349,-0.308819,0.124535,0.120147,0.289550,0.046988,0.358572,0.094057,-0.043331,0.218012,0.437797', '1480318', '1307762', '6982558', '4913200');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30208010', '名侦探柯南：绀青之拳', '动画', '“名侦探柯南系列”第23部动画剧场版，票房和口碑也屡破纪录。作为平成年代最后一部柯南电影，首次将案件发生地设立在海外，基德时隔四年后再度回归，与柯南合体展开行动。故事围绕着19世纪末与海盗船一同沉入海底、世界上最大的蓝宝石“绀青之拳”展开。', '高山南', '永冈智佳', 5.8, 147400, 'tt9501310', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2566225091.jpg', 4.8, 24.9, 51.3, 14.7, 4.2, '-0.268431,0.147315,-0.621669,0.643720,0.821177,-0.154206,0.277876,0.034381,-0.268131,-0.159866,-0.080436,0.829243,-0.576053,-0.125175,0.280210,-0.116688,-0.586618,-0.978455,-0.460754,-0.479161,0.112274,-0.166699,-0.477887,0.500070,-0.066738,-0.406651,0.891228,0.028980,-0.362924,0.454355,0.442510,0.201488,-0.609125,0.123098,0.337353,0.087830,0.235561,0.154038,-0.576168,0.635967,-0.258343,-0.208030,0.058445,-0.467165,-0.012087,-0.107626,1.253800,-0.495753,0.020278,-0.240279,0.561348,-0.097423,-0.641676,-0.203967,0.583922,0.595329,0.030384,0.583520,0.144044,0.217248,-0.139574,-0.605654,-0.557819,0.101835,0.081193,0.051858,-0.088965,0.046903,-0.327374,0.199016,0.128725,-0.304160,0.183260,0.327259,0.956991,0.065940,-0.129886,0.258527,-0.032119,0.437370,0.146605,0.232333,-0.218583,0.482176,0.275036,-0.581205,-0.923181,-0.271028,0.022286,0.102944,0.184329,0.022886,-0.078074,0.414420,-0.899207,0.103526,-0.130387,-0.658649,0.046601,0.034728,0.034049,-0.965868,0.025628,-0.123638,0.085325,-0.071528,0.082804,-0.463777,0.831550,-0.326712,0.297807,0.432287,0.198357,0.049608,0.710019,0.071836,0.063149,-0.375266,0.346870,0.140829,-0.007331,0.467622,-0.106086,0.111155,-0.344210,-0.095861,-0.581726,0.545088', '5403927', '26877406', '30434174', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30209018', '陪你很久很久', '喜剧', '性格憨直的赵玖秉的整个青春，都是陪着梁薄荷一起度过的，两个青梅竹马的伙伴一路相伴成长，他们的欢笑和眼泪都与彼此有关。上了同一所大学后，一连串的意外事件导致薄荷的初恋被帅气的学长夺走。抓不到，又舍不得放手的九饼决定不再沉默，要为自己的女神奋力一搏。偏偏在薄荷眼中，他只是一个幼稚、长不大的男生。从恋人未满回归到普通朋友，从亲密无间到渐行渐远，不甘心的九饼依旧谱写出一支没有终点、只有无止尽陪伴的追爱练习曲。', '李淳', '赖孟杰', 4.7, 6558, 'tt11082644', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2678123003.jpg', 20.9, 38.8, 28.2, 7.3, 4.9, '0.572620,-0.001769,-0.889962,0.795531,-0.210491,-0.588435,1.147584,0.071625,-0.198014,-0.032566,0.123510,0.654464,-0.083765,0.506499,0.307192,-0.093129,0.070083,-0.910828,-0.250754,-0.195893,-0.405846,-0.497458,-0.083563,0.271672,-0.401005,-0.030325,0.987692,0.094656,-0.037391,0.792756,0.478757,-0.032393,-0.214492,0.383463,-0.510640,-0.010021,-0.109735,0.269410,-0.129582,0.147312,0.250379,-0.078840,0.020166,-0.141333,-0.130662,0.139085,0.937194,-0.352700,0.237578,0.265700,0.222954,-0.261412,-0.090767,0.139091,0.125857,-0.023896,0.154064,0.049258,-0.183969,0.110869,0.008520,0.098169,-0.767475,0.092328,0.112980,0.219297,-0.894806,0.742458,0.185005,-0.319556,0.514667,-0.444968,0.214246,0.448563,0.245368,0.720428,-0.324356,0.192307,-0.517865,0.186999,1.229785,0.174536,-0.284952,0.628172,-0.305125,-0.329611,-0.111939,-0.515806,-0.789897,-0.088708,0.068626,0.191125,-0.009126,0.242752,-0.635814,0.157498,0.144103,0.037107,0.267244,-0.629655,-0.037591,-0.223695,-0.197721,-0.610814,-0.097058,0.663825,0.031794,-0.470182,0.892728,-0.934129,0.231014,0.618945,0.030485,-0.358634,0.711564,0.370172,0.070200,-0.383057,0.243484,0.461376,0.312778,0.159649,0.291319,0.429246,-0.088171,0.436954,-0.639808,0.414452', '21619567', '35030151', '25721544', '1850797');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30209084', '对不起，我们错过了你', '剧情', '故事发生在英格兰北部的纽卡斯尔，因为遭遇了次贷危机，瑞奇（克里斯·希钦 Kris Hitchen 饰）不仅丢掉了工作，还背负上了巨额的债务。为了维持生计，瑞奇贷款买了一辆小货车，准备靠送货来开启事业的第二春，哪知道他这一没有经过思考的举动给整个家庭都带来了无法挽回的伤害 。瑞奇的妻子艾比（黛比·哈尼伍德 Debbie Honeywood 饰）是一名家政工，专门为残疾人和老人服务，如今，她不得不依靠公交车往返于不同的雇主家中，这令她感到非常的疲惫。为了偿还货车的贷款，瑞奇不得不将更多的时间花费在工作上，这令他们的大儿子塞布（瑞斯·斯通 Rhys Stone 饰）感到备受冷落。©豆瓣', '克里斯·希钦', '肯·洛奇', 8.5, 51774, 'tt8359816', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2584121702.jpg', 0.3, 0.7, 10.6, 50.1, 38.3, '0.235914,-0.146294,-0.656472,0.332494,-0.022263,-0.620804,0.647164,0.420647,-0.478976,-0.336242,0.272845,0.586431,0.140432,0.102887,0.394012,-0.146421,-0.268683,-0.387051,0.007881,-0.058930,-0.242201,-0.529352,-0.273176,-0.255345,-0.369226,-0.377249,0.352095,-0.128393,0.054604,0.372228,0.297408,0.283853,0.386265,0.423541,0.008570,0.150148,0.047237,0.003592,-0.259109,0.163570,0.124151,-0.225523,0.087290,0.187667,0.228615,0.505183,0.546374,-0.096478,-0.151910,-0.316495,0.318016,-0.165134,0.179942,-0.029430,-0.031206,0.141956,0.178645,0.236970,-0.684793,0.031832,0.425027,0.030756,-0.985208,-0.029421,-0.042707,0.136990,-0.762105,0.467289,-0.388684,-0.048639,-0.067547,-0.597167,0.118271,0.606750,0.297077,0.360681,-0.351045,-0.033771,-0.570396,0.023145,0.730854,-0.183231,0.027781,0.524277,-0.454048,-0.101514,0.133271,-0.389867,-0.440458,-0.074317,0.183614,0.015258,0.093507,0.224800,-0.519945,0.032003,-0.412576,-0.765173,-0.100625,-0.308068,-0.181430,-0.414119,-0.033894,-0.454542,-0.351823,0.050780,0.361460,-0.247357,0.483934,-0.701235,0.068413,0.646894,0.537477,-0.321419,0.501691,0.049442,0.346100,-0.075355,-0.255576,0.099768,-0.145747,0.566783,0.102262,-0.029058,-0.020024,-0.227428,-0.152608,0.579464', '1793491', '1299965', '1783461', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30209085', '年轻的阿迈德', '剧情', '阿迈德是一个生活在比利时的移民少年。像许多摸索个人价值的青春期孩子一样，阿迈德对父母和学校定下的规则有疑问。曾经是心中偶像的表哥叛逆地离开了比利时。青春期敏感孤独的少年之心需要叛逆的做派来武装。他于是也模仿起表哥，并和社区补习班年轻的数学女老师发生了冲突……', '伊迪尔·本·阿迪', '让-皮埃尔·达内', 7.2, 6069, 'tt8359822', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554651495.jpg', 0.5, 4.3, 40.7, 45.3, 9.2, '0.449221,-0.099170,-0.743736,0.524349,-0.415135,-0.316294,0.763281,0.019235,-0.517838,-0.257675,-0.050251,0.627766,-0.051077,0.505257,0.236582,-0.128684,-0.091942,-0.647423,-0.156057,-0.250564,-0.049337,-0.695839,-0.069342,-0.186132,-0.204924,-0.587490,0.577202,-0.167964,-0.348814,0.331934,0.339709,0.110798,0.278157,0.425382,-0.325910,-0.180675,-0.195593,0.119227,-0.161759,-0.152899,0.163810,0.121105,-0.064214,-0.035097,0.262767,0.361851,0.869362,-0.028121,-0.101191,-0.257162,0.430262,0.185749,-0.097032,0.216978,0.359570,0.092427,-0.023349,0.005067,0.352067,0.058392,-0.091491,-0.249703,-0.270100,-0.142221,0.175969,0.156301,-0.637988,0.458464,-0.021083,-0.179078,0.167732,-0.471317,-0.048662,0.273340,0.277876,0.701189,0.110909,0.216305,-0.342225,0.172412,0.696250,-0.018273,-0.285842,0.305968,-0.704563,-0.704945,-0.260446,0.049818,-0.757361,-0.004080,0.174508,-0.303728,-0.377686,0.426834,-0.514128,0.182437,-0.011410,0.068061,0.195936,-0.548757,0.001220,-0.317652,-0.171935,-0.506762,-0.401764,-0.021818,0.245413,-0.047147,0.995656,-1.039160,0.220467,0.882506,0.522156,-0.577047,0.583149,0.227526,-0.147937,-0.465244,0.011851,0.384525,-0.341436,0.180340,-0.327709,0.379586,0.004356,-0.120004,-0.140420,0.346163', '3445516', '1309161', '1292219', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30209802', '之后', '爱情', '泰莎（约瑟芬·兰福德 Josephine Langford 饰）是一位向来循规蹈矩的女生，在父母眼里，她是听话乖巧的好女儿，在男友眼里，她是体贴懂事的好女友，在老师眼里，她是守规矩讲礼貌的好学生，这样一个女孩，在她踏进大学校园后，邂逅了名为哈丁（赫洛·费因斯·提芬 Hero Fiennes Tiffin 饰）的男孩。哈丁和泰莎所见过的所有男生都不一样，他有着桀骜不驯的眼神，花哨夸张的外表，做事情也向来不拘一格。泰莎对哈丁的第一印象并不好，但随着时间的推移，他身上某些独特的气质渐渐的吸引了泰莎，她开始渴望成为像他一样自由的人。在阴差阳错之中，泰莎和哈丁接吻了，之后哈丁飘忽不定的态度反而让泰莎对他更加的沉迷。©豆瓣', '约瑟芬·兰福德', '珍妮·盖奇', 6.5, 34125, 'tt4126476', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2543670474.jpg', 4.1, 16.1, 43.1, 23.8, 12.9, '0.602072,-0.043504,-0.861633,0.708570,-0.591755,-0.083796,0.956105,0.085319,-0.708456,-0.007506,0.087571,0.799029,-0.208381,0.292192,0.115355,0.374316,-0.274376,-0.774068,-0.264996,-0.227260,0.045259,-0.550896,-0.267080,-0.136952,-0.046233,-0.551550,0.411761,-0.180185,-0.115936,0.566512,0.378074,-0.029615,0.357052,0.700425,-0.401120,-0.065098,-0.054478,0.023513,0.214157,-0.037230,0.210340,-0.128822,-0.222283,0.284534,0.078365,0.416431,0.595079,-0.181397,-0.372762,0.105268,0.365610,-0.119119,0.002102,0.348118,0.147735,-0.178925,0.267642,0.046009,0.058093,0.051980,0.020121,-0.009325,-0.494402,-0.050439,0.157330,0.288855,-0.650439,0.815597,0.051687,-0.287257,0.175634,-0.528640,-0.021828,-0.226970,0.029682,0.473966,-0.031018,0.060519,-0.290611,0.190031,0.674171,0.372978,-0.544789,0.674278,-0.607691,-0.419347,-0.094483,-0.274994,-0.598469,-0.037423,0.232920,-0.113405,-0.035691,0.384014,-0.426344,0.147486,0.050864,-0.046237,-0.278112,-0.675992,0.007032,-0.272563,-0.246725,-1.094208,-0.646124,-0.052489,-0.269990,-0.350196,1.015545,-1.059593,0.234635,0.601564,0.261596,-0.363487,0.702826,0.255011,-0.051233,-0.088953,-0.236003,0.279480,0.039649,-0.094349,0.058544,0.746280,-0.020888,-0.040017,-0.250141,0.690994', '1390020', '1309161', '26354526', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30209818', '忌日快乐2', '悬疑', '停靠在路边的汽车内，黄毛小子瑞恩（飞·武 Phi Vu 饰）被其他汽车的喇叭惊醒，他昏头昏脑走下来，一路晃进校园，进了实验室。由于正在研究的装置耗能巨大，学院院长气急败坏责令瑞恩停掉在研项目。糟糕的事不止于此，事后不久他就被一个带着面具的家伙给杀掉了。然而，他再度醒来， 发现自己还躺在车里，而接下来发生的一切都和“梦境”中的一样。瑞恩惶恐不安，找到了好基友卡特·戴维斯（伊瑟尔·布罗萨德 Israel Broussard 饰）及其女友泰莉·格尔布曼（杰西卡·罗德 Jessica Rothe 饰）。这种生死轮回对于泰莉再熟悉不过了，她首先跟瑞恩讲述自己的经历，随后告诉他想终止轮回的方法只有找到凶手。而接下来，他们不仅发现瑞恩那台装置似乎是造成轮回的一个成因，而且泰莉再次回到了那个可怕的早晨……©豆瓣', '杰西卡·罗德', '克里斯托弗·兰登', 6.6, 90724, 'tt8155288', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2537453473.jpg', 1.3, 10.5, 52.1, 28.3, 7.8, '0.434512,0.229722,-0.699123,0.247357,-0.104100,-0.256319,0.710284,-0.082516,-0.390423,-0.437868,0.158220,0.565218,-0.278606,0.238323,0.288992,0.096844,-0.463030,-0.593675,-0.043406,-0.057380,-0.625841,-0.534849,-0.000858,-0.129124,0.091834,-0.272357,0.414007,0.016186,-0.022789,0.281417,0.124953,0.227485,-0.080867,0.545478,-0.114969,0.198203,0.122557,-0.082737,-0.068198,0.259001,0.117422,-0.334285,-0.053346,0.201921,-0.057430,0.171683,0.484984,-0.325438,-0.270587,0.034669,0.278011,-0.270164,-0.175320,-0.013483,0.243535,0.267821,-0.012802,0.030880,-0.249702,0.092317,0.192125,0.139991,-0.484473,0.099762,-0.254571,0.059975,-0.468076,0.204600,-0.166188,0.041386,0.195282,-0.251786,0.364977,0.254088,0.370737,0.353132,-0.270752,0.065304,-0.594103,-0.114123,0.380630,-0.096418,-0.298848,0.513662,0.092677,-0.306086,-0.112246,0.035791,-0.245061,0.040177,0.573951,0.182133,-0.277661,0.008642,-0.270774,0.001620,-0.348062,-0.416894,-0.270443,-0.073618,-0.335275,-0.594599,-0.045383,-0.118655,-0.230289,0.075211,-0.237445,-0.276380,0.376490,-0.599423,0.268112,0.369396,0.155159,-0.247851,0.334778,-0.126754,0.265916,-0.060305,-0.107207,0.218447,0.123959,0.584331,0.192250,0.395404,0.039496,-0.186051,-0.440870,0.424076', '3011051', '3735015', '2210143', '2761734