INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30210689', '乳牙', '剧情', '一对夫妻发现重病的青春期女儿米拉爱上了一个毒贩，二人的关系成为了夫妻俩的噩梦。而濒临死亡的米拉却对生活产生了新的渴望，传统的道德观念也被抛到脑后。米拉向她身边的每个人展示了如何一无所有地生活。这对一个家庭来说，原本可能是一场灾难，但最终却让他们在生活的混乱中找到了平静。', '本·门德尔森', '香农·墨菲', 7.2, 6199, 'tt8399664', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2626896044.jpg', 1.1, 5.3, 40.3, 39.3, 14, '0.497324,0.083033,-0.766915,0.777062,-0.326251,-0.384541,1.272114,0.155344,-0.577677,-0.152859,0.273107,0.942793,-0.032549,0.347174,0.310074,0.158261,-0.141153,-1.061603,-0.076981,0.003294,-0.537269,-0.309615,-0.404507,-0.122958,-0.264238,-0.249148,0.684939,0.343818,-0.078885,0.584869,0.163324,0.341635,0.188678,0.644700,-0.238286,0.057761,-0.089706,0.175364,-0.377606,0.343865,-0.129461,-0.056384,-0.130157,0.516418,-0.329112,0.412066,0.907529,-0.316247,-0.340795,-0.178191,0.518960,-0.481828,-0.383627,0.505546,0.427106,0.056896,-0.015755,-0.148100,-0.227703,0.016444,0.051346,0.190892,-1.057995,0.059021,-0.098810,0.228209,-0.883173,0.763834,0.280882,-0.325862,-0.070099,-0.074627,0.393773,0.528228,0.442371,0.683989,-0.520133,0.086097,-0.649769,-0.118382,1.054991,-0.191955,-0.556258,0.556444,-0.642494,-0.465485,-0.224388,-0.148366,-0.670237,-0.248754,0.167253,0.212103,-0.558286,0.492237,-0.657666,0.234505,-0.344548,-0.283632,-0.158263,-0.910502,-0.066810,-0.302025,-0.456206,-0.741661,-0.779370,-0.033494,0.052386,-0.492584,0.861586,-0.769022,0.229755,0.630371,0.218577,-0.692874,0.687871,0.414099,0.330284,-0.270571,0.012793,0.388440,-0.162442,0.247296,0.154763,0.201516,-0.121573,0.247710,-0.351393,0.798479', '1307748', '24756472', '6745433', '26862829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30210691', '极限逃生', '喜剧', '在大学时代，龙南曾是校内最强的攀岩选手，但是毕业后他的人生却“一路向下”。找不到工作的龙南只能依靠父母接济过活。马上就要到他母亲的七十大寿，龙南坚持要将庆祝仪式放在学妹仪珠工作的酒店中举办。在宴会厅，龙南和仪珠意外相遇，然而等待着他们的却是一场前所未有的灾难。当剧毒的气体充满首尔城区时，他们要通过自身的能力和攀岩技巧来逃出生天。', '曹政奭', '李相槿', 7.5, 153274, 'tt10648440', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2559890156.jpg', 0.6, 3.1, 32.3, 47.7, 16.3, '-0.021495,-0.047673,-0.718468,0.689164,-0.094728,-0.361109,0.564118,0.105382,-0.565759,-0.041673,0.269289,0.572457,0.064041,0.411672,0.225847,-0.274919,-0.076629,-0.681941,0.012218,-0.121095,-0.546705,-0.293502,-0.055361,-0.000381,-0.079293,-0.196704,0.740007,0.149122,-0.099423,0.600375,0.178086,0.158407,-0.061524,0.598097,-0.534600,-0.341831,-0.092173,0.308009,-0.584724,0.419053,0.293023,-0.158772,-0.504383,0.248433,0.313056,0.256413,0.846328,0.128005,0.083820,0.099137,0.115829,-0.245487,-0.142717,0.211748,0.361222,0.009474,0.260083,0.216541,-0.023835,0.070838,-0.119695,-0.298511,-0.690145,-0.171901,0.096790,0.054832,-0.700172,0.504732,-0.076454,-0.160121,0.134005,-0.470412,0.133809,0.515110,-0.049520,0.525127,-0.494076,0.070702,-0.417931,0.360148,0.903970,-0.207297,-0.203383,0.447978,-0.119829,-0.445246,-0.039072,-0.357355,-0.495408,0.062853,0.165741,0.346197,-0.169515,-0.030683,-0.590084,-0.217310,-0.125875,-0.497759,0.216280,-0.282222,-0.093804,-0.727723,0.011662,-0.188026,-0.258078,0.260107,0.172850,-0.356076,0.500154,-0.999736,0.130347,0.671487,0.202408,-0.331996,0.890336,0.036123,0.262481,-0.250761,-0.071425,-0.179255,-0.282224,0.721413,-0.027077,0.593126,0.065669,-0.069525,-0.504035,0.852415', '1652618', '2124718', '1870682', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30210700', '巨鳄风暴', '剧情', '故事发生在位于美国佛罗里达州的一座小镇内，一场猛烈的飓风在居民们措手不及的情况下袭击了该小镇。海丽（卡雅·斯考达里奥 Kaya Scodelario 饰）是一名游泳运动员，在训练中，她接到了姐姐打来的电话，姐姐告诉她，她们的父亲戴夫（巴里·佩珀 Barry Pepper 饰）失踪了。政府命令小镇上所有的居民们都从家中撤离，但是海丽无法弃父亲于不顾，擅自折返来到了父亲的家中，果不其然，在地下室里，海丽找到了身受重伤的父亲，如果不是她即使出现，那么戴夫将必死无疑。现在，父女两人需要面对的，是逐渐被洪水填满的地下室，但很快，海丽就意识到，他们的对手并非这么简单，有一些邪恶而又凶暴的黑影隐藏在水面之下。©豆瓣', '卡雅·斯考达里奥', '亚历山大·阿嘉', 5.7, 48630, 'tt8364368', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2568264291.jpg', 4.7, 24.5, 54.6, 13.7, 2.3, '0.431511,-0.040360,-0.816137,0.418515,-0.078255,0.130633,0.841644,0.123008,-0.608257,-0.259296,0.245316,0.804756,0.098051,0.253421,0.154620,-0.159685,-0.201671,-0.558425,0.027152,-0.411190,-0.354362,-0.490899,-0.171144,-0.311541,-0.045967,-0.347153,0.389274,0.115623,-0.254193,0.229366,0.169798,0.355705,-0.224911,0.593300,-0.268095,0.224341,-0.015961,-0.080823,-0.109192,0.406380,0.002615,-0.180207,-0.029325,0.287376,0.160041,0.340739,0.574376,-0.232579,-0.149633,0.036361,0.247927,-0.306459,0.174900,0.250452,0.625660,-0.146397,0.159805,0.102865,-0.400406,0.059120,0.098152,-0.037673,-0.458414,0.169230,-0.052262,0.250060,-0.787782,0.143552,-0.064458,-0.180733,0.036807,-0.445812,0.324989,0.386828,-0.078814,0.312945,-0.182469,-0.285228,-0.585250,-0.131852,0.908372,-0.170739,-0.136639,0.270112,-0.063272,-0.305748,0.062826,-0.126451,-0.373063,-0.031605,0.322166,0.135426,-0.426028,0.141365,-0.369428,-0.105264,-0.335190,-0.400204,-0.336446,-0.403536,-0.317803,-0.448230,-0.039539,-0.183685,-0.238445,0.271345,-0.223100,0.086632,0.564863,-1.032372,0.359088,0.471825,0.273339,-0.285526,0.362020,-0.097887,0.294604,0.199310,0.235116,0.180909,0.246788,0.480222,0.209556,0.321460,-0.105045,-0.227039,-0.375223,0.298712', '1308755', '25721544', '1299965', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30211551', '恶人传', '剧情', '接连发生的凶杀案让负责这一片区治安的警官郑泰锡（金武烈 饰）感到非常的头痛，种种线索表明，这些案件均是同一人所为。这一天，黑帮大佬张东秀（马东锡 饰）也遭到了神秘男子的袭击，身受重伤的他为了挽回自己在业内的名声，决定和郑泰锡联手调查此案，一正一邪两拨人马虽然目的相同，但仍然爆发了诸多的矛盾。郑泰锡和张东秀达成了协议，如果哪一方先抓到了连环杀手，那么这个人就可以任凭那一方处置。就这样，郑泰锡和张东秀马不停蹄的展开了调查，随着时间的推移，针锋相对的两人之间慢慢产生了信任和友谊。与此同时，他们发现，他们所面对的杀人魔，要远比他们所想像的邪恶的多。©豆瓣', '马东锡', '李元泰', 7.8, 258864, 'tt10208198', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2555084871.jpg', 0.3, 1.9, 27.1, 49.5, 21.2, '0.422971,-0.269242,-0.781312,0.448783,0.077654,0.083131,0.627709,0.152314,-0.630678,-0.264267,0.217854,0.690533,-0.289235,-0.272483,0.211275,-0.407087,-0.211165,-0.824050,-0.122090,-0.372955,-0.253697,-0.540547,-0.247956,-0.266756,0.050351,-0.008208,0.542264,0.345065,-0.260768,0.483980,0.290009,0.319025,-0.324295,0.505568,-0.022337,-0.058435,0.019465,0.047687,-0.293127,0.107730,0.195510,-0.203868,0.057204,0.437556,-0.150602,0.614075,0.522239,-0.272790,-0.486868,0.103662,0.304968,-0.544426,-0.046855,0.200347,0.579290,-0.042845,0.171399,0.365552,-0.292707,-0.223539,-0.089579,0.218603,-1.141017,0.081916,0.225303,0.220150,-0.554765,0.451371,0.045877,-0.119213,-0.048964,-0.114266,0.394934,0.867771,0.200135,0.088985,-0.167592,-0.424340,-0.665725,-0.128106,1.019278,0.045853,-0.136832,0.077289,-0.148947,-0.400220,-0.437485,-0.414430,0.032584,-0.105754,0.276742,0.221564,-0.032219,0.215359,-0.508898,0.011579,-0.204321,0.009394,-0.239725,-0.611295,0.236920,-0.522949,-0.385467,-0.485226,-0.378080,0.269128,0.224937,-0.196700,0.625665,-0.986395,-0.123696,0.494051,0.556406,-0.686979,0.350168,0.335811,0.148164,-0.258514,-0.274837,-0.219168,0.314847,0.318429,0.172957,0.376429,0.230965,-0.171901,-0.270741,0.161351', '26678784', '25917239', '1877596', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30211998', '绅士们', '喜剧', '美国移民Mickey Pearson（马修·麦康纳 饰）成功在英国伦敦建立大麻帝国，发了大财后，他试图将资产转卖给一个美国富豪。然而风声走漏，一连串的阴谋及谎言开始从Mickey展开…私家侦探Fletcher（休·格兰特 饰）用尽各种手段，收集所有Mickey的黑材料，企图从中得利。这时，新崛起的唐人街帮会龙头Dry Eye（亨利·戈尔丁 饰）对Mickey的生意虎视眈眈，最后… Mickey如何保护自己的生意与生命呢？', '马修·麦康纳', '盖·里奇', 8.3, 207602, 'tt8367814', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2592646837.jpg', 1.2, 1.6, 14.3, 47.2, 35.5, '-0.145815,0.254434,-0.451902,0.580284,0.033236,-0.028076,0.202920,0.069380,-0.456903,-0.334391,0.027697,0.532030,-0.100660,-0.164300,-0.090114,-0.009458,-0.249112,-0.761700,0.184665,-0.173338,-0.097511,-0.325121,-0.436050,-0.436654,-0.250225,-0.119909,0.357160,0.240656,-0.294262,0.095903,0.372758,0.484380,-0.177386,0.124659,-0.104334,-0.198181,0.237275,-0.144166,-0.510133,0.371334,-0.028927,-0.294490,-0.092869,-0.011239,-0.000740,0.515329,0.449517,-0.047058,0.184545,-0.132882,0.375314,-0.220990,0.006289,0.071527,0.292132,0.322363,0.093270,0.263475,-0.494622,-0.156948,0.255950,-0.198268,-0.904537,-0.300392,0.060757,0.007019,-0.559910,0.105696,-0.502418,0.214845,-0.058245,-0.284530,0.260189,0.546460,0.186463,-0.078537,-0.067057,0.469789,-0.652363,0.085232,0.322273,-0.283374,-0.005508,0.031645,0.097704,-0.158564,-0.030588,-0.306745,-0.040743,-0.293806,0.600093,-0.038232,0.134847,0.325038,-0.962941,-0.090400,-0.310400,-0.443587,0.375756,-0.281896,-0.301072,-0.649838,-0.265493,0.026236,0.093059,0.273511,0.385127,0.126361,0.735628,-0.375246,0.032507,0.483859,0.308690,-0.565839,0.130814,-0.335126,0.220442,-0.231018,-0.376726,-0.146621,0.388304,0.303458,0.201281,-0.210131,0.134442,-0.417368,-0.161619,0.183654', '1308248', '7155241', '1308585', '1498811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30212001', '信使', '惊悚', '根据英国商人葛雷维尔韦恩(Greville Wynne)的真实故事改编。《信使》描述葛雷维尔（本尼迪克特·康伯巴奇 饰）在冷战期间与苏联线人欧列格潘科夫斯基(Oleg Penkovsky)，暗中协助中情局渗透苏联的核子计划，并提供了成功阻止古巴导弹危机的重要情报。', '本尼迪克特·康伯巴奇', '多米尼克·库克', 7.3, 12900, 'tt8368512', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2631621151.jpg', 0.9, 3.4, 36.7, 46.1, 12.8, '0.106942,-0.044399,-0.456034,0.771958,0.271568,0.041758,-0.046500,-0.326554,-0.555497,-0.313792,-0.558518,0.330616,-0.002279,-0.409900,0.349991,-0.159212,-0.662040,-0.414151,-0.272121,0.237223,-0.288817,-1.193636,-0.343556,-1.066107,0.032183,-0.559897,0.333193,0.586931,-0.473092,0.332696,0.221640,0.993865,-0.550356,0.293778,0.371042,-0.156412,0.645819,-0.213388,-0.617279,0.010609,0.060616,-0.056191,0.278033,0.530587,0.488612,0.708960,-0.042971,-0.410001,0.135323,-0.019717,0.119100,-0.268074,0.627827,-0.290986,0.506973,-0.028919,0.100406,0.122663,-0.048020,0.057030,-0.205564,-0.306321,-0.476157,-0.523860,0.224525,-0.071848,-0.292670,-0.173026,-0.701458,0.686905,0.028241,-0.288641,0.137124,0.826751,0.606330,-0.183230,0.186890,-0.056332,-0.412150,0.409920,0.153059,-0.141075,-0.143003,-0.106523,-0.540363,-0.541731,-0.332109,0.054809,0.055175,0.170574,0.738523,-0.202911,0.413367,0.279084,-0.131660,-0.114654,-0.349893,0.031919,-0.071232,-0.222042,0.257093,-1.175651,-0.301575,-0.262986,-0.147950,0.263712,0.110408,-0.024946,0.240956,-0.209543,0.168442,0.667777,-0.062172,-0.342015,-0.176395,0.267538,0.171816,-0.815111,0.091472,0.665757,0.639589,-0.170299,0.035051,0.103359,0.110663,-0.350170,-0.062553,0.094188', '1293572', '6517421', '1293544', '1293537');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30212622', '前哨', '剧情', '斯科特·伊斯特伍德、卡赖伯·兰德里·琼斯、奥兰多·布鲁姆将主演Millennium Media打造的阿富汗战争题材影片[前哨](The Outpost，暂译)。罗德·拉里执导影片，影片则根据CNN记者Jake Tapper著作改编。影片故事将围绕53名美国士兵的真实故事展开，这些士兵与阿富汗东北部约400名敌方武装分子拉开持久的作战。他们所建造的前哨基地位于巴基斯坦边境仅14英里处的三处陡峭山脉底部。基地则面临塔利班恐怖分子的袭击。而驻扎在那里的士兵则面临着巨大威胁。片中斯科特·伊斯特伍德扮演克林特·罗马沙军士，卡赖伯·兰德里·琼斯扮演专业军士Ty Michael Carter，布鲁姆扮演的Benjamin D. Keating在阿富汗战争中不幸丧生。该片预计将在今年8月展开拍摄，影片也将在戛纳电影节寻找买家。', '斯科特·伊斯特伍德', '罗德·拉里', 7.2, 21888, 'tt3833480', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2607219972.jpg', 1.2, 4.5, 41.1, 40.7, 12.5, '0.101682,-0.380454,-0.560464,0.617704,0.599815,0.104016,0.730504,-0.080398,-0.171602,0.064861,0.582567,0.641661,0.077232,-0.548622,0.420112,-0.028006,-0.879381,-0.615886,-0.469137,-0.192766,-0.012748,-0.449750,-0.613511,-0.249727,0.100473,-0.429649,0.754434,-0.051539,-0.273896,0.315205,-0.003745,0.359546,-0.380690,-0.048758,0.320579,-0.030837,0.336093,-0.656020,-0.494909,0.430520,-0.293707,-0.135412,-0.227220,-0.190460,0.087699,0.637281,0.901297,-0.483301,0.394461,-0.021742,0.230728,-0.500060,0.292896,-0.119497,0.307397,0.228007,0.202399,0.090464,0.011123,0.094020,-0.248364,-0.474926,-0.458166,-0.099843,0.210394,0.213857,-0.231111,0.415864,-0.285587,0.163291,0.271347,-0.137479,0.133945,0.521138,0.376318,-0.004606,0.066862,-0.030364,-0.303458,0.210447,0.397333,-0.207012,-0.195735,-0.224690,-0.084014,-0.490869,-0.264915,-0.253100,-0.450783,-0.046033,0.402289,-0.435894,0.265795,0.440312,-0.675845,0.197989,-0.330537,-0.563520,-0.052355,0.071725,-0.133725,-1.246448,0.173452,0.129707,0.135727,-0.092937,0.138022,0.199718,0.698451,-0.248592,0.195882,0.710183,0.454478,0.144355,0.396340,-0.075468,0.333898,-0.167123,-0.047161,0.663899,0.118244,0.248012,-0.044998,0.133929,-0.305155,-0.392073,-0.316707,0.482469', '34961898', '6517421', '2075345', 