INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3021273', '越狱特别篇：最后一越', '剧情', '《最后一越》将讲述众人在《越狱》正剧最后的大结局忽略掉的四年之间发生的事。迈克尔（文特沃斯·米勒 Wentworth Miller 饰）在同伴的帮助下搞垮了“公司”， 但迈克尔脑中还有一个肿瘤。就在他和怀胎八月的莎拉（莎拉·韦恩·卡丽丝 Sarah Wayne Callies 饰）结了婚，还来不及度蜜月享受新婚生活时，莎拉就因为杀了克里斯蒂娜·斯科菲尔德而被捕关进了Miami-Dade女子监狱，在狱中她遇到了格雷琴。而坎特兹将军也被关进了Miami-Dade男子监狱，当不久要坐上电椅的他得知莎拉的境地时，悬赏十万美元加害于她。迈克尔为了自己爱的人和尚未出世的孩子，决定联手哥哥林肯（多米尼克·珀塞尔 Dominic Purcell 饰）故技重施，帮助莎拉越狱。这一次，他们不得不最后一次铤而走险……©豆瓣', '多米尼克·珀塞尔', '凯文·霍克斯', 7.9, 27512, 'tt1131748', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2201756672.jpg', 0.7, 2.7, 24.4, 43, 29.2, '0.187606,-0.023837,-0.721966,0.411805,-0.263997,-0.461677,0.756365,0.250854,-0.428535,-0.156789,0.303774,0.760079,-0.367603,0.293615,0.323451,0.323657,-0.452387,-0.759565,0.141473,-0.198706,-0.460570,-0.585036,-0.019530,-0.292141,0.114936,-0.341204,0.480235,-0.037737,0.007151,0.222051,0.403486,0.265007,0.009149,0.462788,-0.170985,0.287588,0.142685,0.004471,-0.192096,0.438639,0.152756,-0.360396,-0.071550,0.040321,0.141388,0.352856,0.556796,-0.216900,0.105800,-0.080716,0.192222,-0.471835,-0.073764,0.245725,0.340258,-0.274889,0.131394,0.450134,-0.410804,-0.211086,0.215843,0.013918,-0.610108,0.230475,-0.228729,-0.052649,-0.685317,0.382163,-0.256820,0.349323,0.277914,-0.233770,0.178355,0.579264,0.170215,0.295878,-0.170218,-0.246036,-0.576852,0.162258,0.815925,-0.263728,0.061754,0.287467,0.027560,-0.364892,-0.110141,-0.141391,-0.255509,0.120091,0.374764,0.116569,-0.441666,0.339571,-0.250120,-0.250940,-0.615511,-0.072041,-0.028426,-0.392567,-0.237044,-0.434053,-0.161356,-0.125140,-0.369582,-0.053121,0.031595,-0.247788,0.344840,-0.594701,0.400876,0.579653,0.313118,-0.374421,0.614797,0.232426,0.186624,-0.087604,0.177973,0.156301,0.096301,0.204451,0.327992,0.187530,0.040445,-0.032030,-0.409866,0.414533', '1292584', '1292217', '25908042', '1306801');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30213339', '比得兔2：逃跑计划', '喜剧', '为了追求自己的“兔”生意义，年少轻狂的比得（詹姆斯·柯登 James Corden 配音）踏上了背井离乡的路并成功赢得老江湖巴拿巴的青睐、成为了团伙中的扛把子，怎料却将追随而来的昔日老友们推入死亡陷阱。 幡然醒悟后，比得化身“兔界阿汤哥”带领同伴展开海陆空三栖大营救。高空跳伞、水下救援、雪山速滑、快艇追击，无所不能。在这场冒险旅途中，比得收获了友情，理解了亲情，最终实现了自我成长，成为真正的“兔一哥”。', '詹姆斯·柯登', '威尔·古勒', 7, 39315, 'tt8376234', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2586350077.jpg', 0.4, 5.5, 47.4, 38.9, 7.7, '-0.012240,0.152864,-0.590384,0.504954,-0.036296,-0.319706,0.333788,-0.109451,-0.173030,0.221009,0.281235,0.441439,0.093000,-0.031170,0.404240,-0.438188,-0.202940,-0.564836,-0.056078,-0.025259,-0.399377,-0.178071,-0.545250,0.011580,-0.353019,-0.440424,1.077738,0.348904,-0.243306,0.680498,0.259959,-0.026352,0.251152,0.241472,-0.300593,0.052749,-0.144339,0.208539,-0.404878,0.227059,-0.478711,-0.068207,-0.099562,0.115679,-0.216123,0.244324,0.701535,-0.395894,-0.003372,-0.473598,0.151889,-0.573645,0.225398,-0.052737,0.216358,0.225192,-0.238982,0.261264,0.076699,0.113136,0.094157,-0.216152,-0.981835,0.057617,0.135454,-0.146532,-0.795394,-0.130702,0.040107,-0.031791,0.118233,-0.022757,-0.081033,0.169744,0.316370,0.238789,-0.404933,-0.004012,-0.492285,0.185392,1.023498,-0.406751,-0.377062,0.279716,0.053639,-0.536034,0.204062,-0.563263,-0.028432,-0.145849,0.385152,0.296675,-0.075928,0.427444,-0.512023,0.151012,-0.316243,0.055869,-0.242114,-0.726130,-0.033278,-0.538181,0.014185,-0.195473,0.106955,-0.137999,-0.054566,-0.664845,0.844954,-0.606711,0.123864,0.732703,0.230311,-0.502284,0.712815,0.271713,0.371719,-0.115017,0.165421,0.451067,-0.123884,0.216753,-0.060838,0.036569,-0.428157,-0.124002,-0.458447,0.564054', '3001114', '30163500', '1482089', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30214145', 'RRR', '动作', '1920年，英国总督斯科特和他的妻子凯瑟琳访问阿迪拉巴德的一个部落，并强行带走了部落里歌唱天赋异禀的小女孩玛莉，部落的保护者比姆（小老虎 饰演）为了救回玛莉，伪装成穆斯林。斯科特得知消息后，总督府的底层卫兵拉朱（拉姆·查兰·特哈 饰演）为了升职也同时为了完成他父亲遗愿和他对部落承诺，主动请愿自己可以将比姆逮捕。比姆和拉朱因共同拯救了一个差点葬身火海的小男孩而巧遇，他们并不认识对方，然而两人也隐藏了自己的真实身份，相互联系，成为挚友。拉朱在一次调查中发现自己的挚友就是总督要逮捕的比姆，他一边是承载了父亲的遗愿和整个部落的承诺，一边是自己的挚友，他该如何抉择…..', '小老虎', 'S·S·拉贾穆里', 7.2, 9278, 'tt8178634', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2870618629.jpg', 1.8, 5.4, 37.2, 40.2, 15.5, '0.090618,0.162617,-0.429029,0.809984,-0.365783,-0.253962,0.638635,-0.077200,-0.449757,-0.263630,-0.003948,0.998944,0.209598,0.242846,0.345421,0.181105,-0.464782,-0.776073,-0.025495,-0.032480,-0.455053,-0.714733,-0.186229,-0.437967,-0.196431,-0.215815,0.575062,-0.234787,-0.150431,0.240446,0.549426,0.416183,-0.236533,0.514718,-0.088514,0.055777,0.123630,-0.178855,-0.353778,0.328310,-0.004683,-0.111201,-0.158842,0.433278,0.036628,0.439478,0.408685,-0.337549,0.170603,-0.411620,-0.018602,-0.466085,0.237355,0.100087,0.321585,-0.206726,0.329272,0.354271,-0.060705,-0.338612,0.077864,-0.169437,-0.824100,-0.083235,0.356916,-0.032863,-0.624332,0.258264,-0.117380,0.133335,0.348450,-0.283019,0.033943,0.571071,0.103426,0.370684,-0.160131,-0.162627,-0.468682,0.204229,0.685788,-0.420379,-0.003779,0.206549,-0.105750,-0.541136,-0.086699,-0.118654,-0.335232,0.035428,0.231087,0.286480,-0.019390,0.165906,-0.353255,-0.390339,-0.515705,-0.187180,0.124361,-0.734506,0.264247,-0.275883,-0.163539,-0.279007,-0.151710,-0.118530,0.042485,-0.244978,0.588026,-0.660501,0.087588,0.512744,0.305415,-0.608385,0.570343,0.391524,0.272968,-0.355841,0.254196,0.268340,0.360467,0.280191,0.169618,0.030062,0.082296,-0.042525,-0.347219,0.301723', '3119246', '4301278', '26678784', '1295733');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30214261', '一百零八', '剧情', '电影讲述了驻唱歌手肖兰（吕星辰 饰）离开成都前往什邡，在遭遇男友陆地（高亮 饰）的闭门之痛后决定引产，沮丧之时突遇地震袭击。医护人员全力保护全院孕妇紧急转移至安全区域罗汉寺，自此寺院变产院，禅房变产房。这期间，肖兰亲历了灾难中人性极限的撕裂与挑战......', '吕星辰', '孔嘉欢', 5, 8213, 'tt10848020', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2646758688.jpg', 14.1, 37.2, 37.9, 5.5, 5.2, '-0.122492,0.151113,-0.676245,0.247714,0.435387,0.062369,0.603618,0.505517,-0.242020,-0.264764,0.318080,0.316130,-0.284913,0.115803,0.318056,-0.186553,-0.179379,-0.549234,-0.256822,0.023919,-0.406057,-0.059760,0.369630,-0.094552,0.169592,-0.606825,0.150658,0.320551,-0.339281,0.377378,0.099167,0.230564,-0.430344,0.700050,0.220603,-0.020231,-0.208691,0.200924,-0.398978,0.071585,-0.140319,-0.267286,0.164456,0.310863,-0.181545,0.375992,0.567231,0.146431,-0.337904,-0.445906,0.434346,0.129742,-0.047005,0.160969,0.618183,0.054175,0.097069,0.034051,-0.018272,0.121959,-0.335633,-0.090775,-0.161019,0.018909,0.356217,-0.178322,-0.515169,-0.090962,0.076808,0.386301,-0.214459,-0.150803,0.223580,0.588000,0.084477,0.246466,-0.250425,0.178025,-0.129096,0.273627,0.717343,-0.504631,-0.033734,0.087585,0.243098,-0.393577,0.136088,0.091735,-0.120170,0.082469,0.083217,-0.000584,-0.038480,0.189982,-0.439241,-0.308506,-0.496277,-0.034878,-0.217728,0.096791,-0.063318,-0.900178,0.426848,0.260991,-0.198255,0.110925,0.120566,0.037614,0.391751,-0.270879,0.293482,0.298841,0.270498,-0.280499,0.648099,-0.336805,0.485535,-0.281787,0.416303,0.560019,-0.252199,0.967159,-0.107612,0.142444,-0.279553,0.026106,-0.565144,0.255837', '27073291', '3871833', '3735015', '1309110');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30216729', '王牌保镖2', '喜剧', '这对世上最要命的混搭-——保镖迈克尔·布莱斯和杀手大流士·金凯，再次执行一项要命任务。大流士反复无常更胜以往的妻子——臭名昭著的国际诈骗家索尼娅·金凯迫使布莱斯出山。布莱斯被这俩最危险的保护对象逼得走投无路，三人在一个全球级的阴谋中陷入困境，很快还发现他们是一个大疯子复仇欧洲的唯一障碍。摩根·弗里曼也加入了这场有趣而又致命的乱局，他饰演的是——嗯，不得不看。', '瑞安·雷诺兹', '帕特里克·休斯', 6.4, 25623, 'tt8385148', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2647131304.jpg', 2.4, 14.5, 53.3, 22.1, 7.5, '0.259792,-0.267973,-0.681444,0.639319,-0.254605,-0.176310,0.535332,-0.025713,-0.333697,-0.129052,0.304955,1.124448,-0.180299,-0.138037,0.392018,0.045596,-0.039937,-0.475437,-0.128658,-0.210555,-0.170256,-0.576130,-0.429726,-0.370790,-0.062084,-0.116169,0.499895,0.118853,-0.158428,0.200361,0.628350,0.347918,0.095561,0.284364,-0.239401,-0.133689,0.282435,-0.243969,-0.135746,0.322071,0.098108,-0.103348,-0.141155,0.427743,-0.205429,0.402203,0.202084,-0.251936,-0.015957,-0.303557,0.241246,-0.772230,-0.281121,-0.081492,0.471315,-0.560116,-0.024364,0.208466,-0.056223,-0.176773,-0.041276,-0.022340,-1.180519,0.013424,0.255665,-0.096673,-0.449453,0.408486,-0.146267,0.033250,0.013034,0.004899,0.298528,0.494782,0.316259,0.140893,-0.201707,0.041544,-0.448416,-0.062070,0.581373,-0.048946,-0.221188,0.262920,-0.127053,-0.256681,0.157392,-0.544164,-0.383565,-0.037176,0.362611,-0.104227,-0.211304,0.187725,-0.521962,0.166529,-0.306374,-0.078210,-0.279642,-0.516898,-0.024452,-0.614848,-0.237574,-0.397533,-0.280251,0.216755,0.044110,-0.316733,0.576763,-0.544042,-0.060589,0.598299,0.282884,-0.416974,0.471941,0.372713,0.318643,-0.300371,-0.359916,0.123272,0.266586,0.217421,0.161874,0.367823,-0.034477,-0.452557,-0.201825,0.462300', '26678784', '30163500', '1793491', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30217371', '动物特工局', '喜剧', '谁说猫鼠不能做朋友？谁说损友不能一起拯救世界？在一个多种动物组成的现代化世界里，动物特工局精英张大威（猫）在因缘际会下结识废柴技术宅阿丘（鼠），当傲娇成性、嘴硬心软的张大威遇见幽默呆萌、重情重义的阿丘，会发生什么欢乐逗趣的故事？这对被卷入一场惊天阴谋的猫鼠搭档，在破案的途中联合其他伙伴各显神通，斗智斗勇。随着一个名叫“寒冰魔鬼”的幕后黑手的出现，令人不寒而栗的真相渐渐浮出水面……', '姜广涛', '张志一', 6, 5684, 'tt8028842', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2580985868.jpg', 4.9, 18.1, 55.6, 18.1, 3.3, '0.302732,-0.072615,-0.693619,0.536051,-0.415276,0.384548,0.641432,-0.295985,-0.174718,-0.076299,0.398322,0.609080,-0.515603,0.166752,-0.236562,-0.472817,0.265210,-0.432711,0.069011,0.212488,0.102709,-0.168439,-0.489556,-0.110631,0.020368,-0.175416,0.367158,0.199407,-0.081009,0.085368,0.342361,0.397201,-0.680113,-0.142732,-0.100065,-0.093878,0.311493,0.267943,-0.161499,-0.104711,-0.351394,0.214302,0.068141,0.101703,-0.178316,-0.200150,0.750452,-0.707422,-0.209907,-0.252098,0.150719,-0.390351,-0.030415,0.052935,0.365630,-0.093049,0.138514,0.036753,0.127783,0.001129,-0.089619,0.279339,-0.900422,-0.065663,0.075997,0.372775,-0.087987,0.033120,0.212843,0.164037,0.053123,0.058144,0.115525,0.085309,0.722370,0.494831,0.326702,0.696112,-0.340926,-0.317781,0.932773,-0.181859,-0.407171,0.268514,0.059208,-0.332633,0.172072,-0.167810,-0.166502,-0.198578,0.144193,-0.400587,-0.601451,0.408492,-0.712694,0.305933,0.056368,0.333192,-0.178032,-0.342826,-0.234228,-0.193348,0.078207,-0.329800,0.091704,0.305429,0.297838,-0.398086,0.740053,-0.717950,0.013941,0.594581,0.042588,-0.324064,0.535897,-0.005832,-0.122906,-0.194962,-0.022286,-0.023751,0.474093,-0.072094,0.298046,0.416577,0.029588,-0.117278,-0.188174,0.257662', '10581450', '1874704', '26678784', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30219670', '罪途2之救赎代价', '剧情', '深夜，列车因暴雨引发泥石流而被停在半路。一节车厢中的八名乘客，全部陷入了不明原因的昏迷当中。调查结果则更让人心惊，其中一位乘客已经成为了冰冷的尸体……侦查中乘警发现了针管，其他几位乘客各执一词，使得案件更加扑朔迷离。在调查陷入僵局之时，一桩十年前的校园暴力案件浮出水面， 当年的真相被人掩盖，真正的犯人又会是谁？', '含笑', '马小刚', 6.5, 13707, 'tt10260386', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2548070168.jpg', 1.1, 9.7, 55.8, 28.2, 5.2, '0.478304,-0.026246,-0.624233,0.212543,-0.018776,0.064713,1.171412,-0.213806,-0.941877,-0.201893,0.518586,0.716748,-0.635096,0.132562,0.405483,-0.412017,-0.282078,-0.831261,-0.374507,-0.316774,-0.829311,-0.226217,-0.145164,-0.135236,-0.039740,-0.175904,0.625372,0.708749,-0.005535,0.377463,0.210832,0.453344,-0.649240,0.542845,0.223022,-0.166427,0.275875,-0.296713,0.217906,0.023248,-0.084553,-0.869063,-0.057635,0.300876,-0.412816,0.597724,0.883343,0.066229,-0.305457,-0.191911,0.310866,-0.373735,0.018178,0.032231,0.825222,0.055357,-0.038607,0.528557,-0.211391,-0.189789,0.084833,0.446153,-0.478435,0.180743,-0.192397,0.368036,-0.250383,0.110928,0.009966,-0.016871,0.027920,0.086981,0.609702,0.414129,0.219970,0.282295,-0.158860,-0.402466,-0.508622,0.131296,0.631625,-0.045806,-0.270208,0.325592,-0.119150,-0.563727,-0.093746,-0.181640,-0.124973,0.043982,0.690325,0.341941,-0.307507,0.568049,-0.354715,-0.045933,-0.307564,-0.451982,-0.627079,-0.054953,-0.470805,-0.533261,-0.127899,-0.011966,-0.116644,0.226929,0.076103,-0.026644,0.456206,-0.543463,0.089708,0.325913,-0.259938,-0.188204,0.245785,-0.192328,0.294935,0.111605,-0.009763,-0.087166,0.150960,0.469026,0.028033,0.363388,-0.555902,-0.211271,-0.431884,0.084357', '20451118', '1773217', '3011051', '1309297');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30220799', '末日逃生', '剧情', '科学家们发现，宇宙中的两颗彗星正在急速向地球逼近，不出意外的话，它们终将撞上地球，给地球带来无法估量的损失。为了避免造成世界级的恐慌，政府封锁了这一消息，偷偷在格陵兰岛建造了非常坚固的堡垒，只有躲进堡垒的人们才能够获得一线生机，而进入堡垒的条件非常的苛刻。杰夫（杰拉德·巴特勒 Gerard Butler 饰）是一名建筑工程师，他得到了进入堡垒的机会，于是决定带着妻子艾莉森（莫瑞娜·巴卡琳 Morena Baccarin 饰）和儿子内森（罗杰·戴尔·弗洛伊德 Roger Dale Floyd 饰）一起前往格陵兰岛。哪知道旅途进行到一半，察觉到了事件真相的军方开始了暴乱行动。©豆瓣', '杰拉德·巴特勒', '里克·罗曼·沃夫', 5.4, 42040, 'tt7737786', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2626067725.jpg', 6.3, 31.8, 49.5, 10.3, 2.1, '0.012678,0.239982,-1.004007,0.709674,-0.005506,-0.162483,0.678184,-0.060310,-0.435516,0.005075,0.249515,0.618014,-0.207062,-0.008102,0.310081,0.008649,-0.478280,-0.306241,-0.030828,-0.448470,-0.679185,-0.485146,-0.253585,-0.415126,-0.104143,-0.458419,0.714984,0.204193,-0.404881,0.039330,-0.020810,0.423995,0.024103,0.523943,-0.135513,0.065447,0.024521,-0.384661,-0.382733,0.498034,-0.153549,0.128312,-0.050037,0.261025,-0.053833,0.196590,0.699326,-0.408506,-0.006947,-0.185842,0.201482,-0.262419,0.191425,0.160150,0.436931,0.066244,-0.072381,0.078366,-0.222709,0.234387,0.323362,-0.300097,-0.566371,-0.084369,-0.051504,0.231833,-0.517439,0.012085,-0.018180,-0.038576,0.039325,-0.459830,0.166684,0.547929,0.183476,0.310669,-0.308919,0.213518,-0.681575,-0.219984,0.569522,-0.144507,-0.198368,0.149274,-0.087358,-0.462472,-0.126705,-0.111459,-0.228395,-0.221442,0.598788,0.132079,0.013436,0.287136,-0.770441,0.037389,-0.280662,-0.791782,-0.028300,-0.306760,0.128400,-0.755204,-0.010325,-0.146385,-0.199847,0.373722,-0.080306,-0.131970,0.765593,-0.665703,0.104401,0.702506,0.573545,-0.249068,0.456475,-0.238235,0.176470,-0.240992,0.144460,0.186100,0.022574,0.576763,0.088617,0.193735,0.014936,-0.386018,-0.304599,0.508990', '34461680', '2159244', '1307897', '1304496');
