INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30221757', '烈火英雄', '剧情', '滨海市海港码头发生管道爆炸，整个罐区的原油都顺着A01油罐往外流，化成火海和阵阵爆炸，威胁全市、全省，甚至邻国的安全。慌乱的市民们四处奔逃，一辆辆消防车却逆向冲进火海……', '黄晓明', '陈国辉', 6.4, 305837, 'tt10218674', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2563630521.jpg', 4.9, 15.9, 45.1, 24.4, 9.7, '0.318955,-0.050710,-1.051329,-0.005072,0.837681,0.320875,1.181947,-0.084928,-0.052359,0.314130,0.321000,0.085302,-0.390342,-0.334299,-0.358117,-0.233622,-0.196502,-0.612011,-0.624277,-0.042600,-0.445414,0.158002,-0.093848,-0.264884,0.008880,0.113937,0.393485,0.658365,-0.273495,0.346301,-0.049617,0.138970,-0.645730,0.841720,-0.220065,0.079418,-0.319345,-0.003479,0.024247,-0.169713,-0.368768,-0.309257,0.087827,-0.431325,0.314938,0.489723,0.774184,0.327153,0.495230,-0.143948,0.163906,-0.440453,0.426084,0.150978,0.489205,0.085389,-0.084508,-0.271329,-0.008161,-0.164286,0.212460,0.241481,0.076360,-0.045364,-0.275021,0.092873,-0.646514,-0.286536,0.220737,-0.283996,-0.010394,-0.023250,0.693410,-0.091252,-0.730370,0.401749,-1.181267,0.492704,-0.809978,-0.268578,0.771868,-0.222304,-0.707344,-0.195341,-0.219000,-0.070890,-0.134961,0.417131,-0.042176,-0.720089,0.433998,0.083124,0.329049,0.424176,-0.634399,-0.016270,-0.307698,-1.299353,-0.220977,0.476406,-0.765642,-0.889393,0.564737,0.087596,0.440761,-0.036976,-0.326315,0.792040,0.143974,0.353992,-0.176875,0.379859,0.060972,-0.519136,0.436219,-0.375935,0.124143,0.130122,-0.150368,0.247367,0.234990,1.206208,-0.218018,0.531109,-0.456835,-0.124269,-0.166457,-0.002915', '1292834', '1473795', '1945330', '20497633');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30223596', '陈翔六点半之铁头无敌', '剧情', '七旬大爷老废年轻时在香港练功夫练成铁头无敌，如今老了铁头功却毫无用处，生活穷困窘迫。老废面对惨淡人生，发出了要再奋斗一次的誓言，在所有人都嘲笑他的时候，一个废柴老头、一门没用的武功在新的环境下，却碰撞出了前所未有的火花……他也大器晚成、飞黄腾达。只不过，生活也变得错综复杂，面对家庭、事业、感情的冲击，他该如何抉择？', '应宝林', '陈翔', 6.2, 15109, '铁头无敌', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2522275201.jpg', 6.3, 17, 47.5, 20.7, 8.4, '-0.173890,-0.134191,-0.557844,0.343504,-0.323184,-0.704530,0.658091,0.370882,-0.296310,-0.243016,0.461678,0.532849,-0.080876,0.229356,-0.089541,-0.372048,0.120532,-0.658422,0.352538,-0.048065,-0.177362,-0.003413,-0.320493,-0.117932,0.020478,-0.379572,0.450741,0.252355,-0.481190,-0.211088,0.214802,-0.106265,0.292884,0.436154,-0.372371,-0.214554,-0.058906,0.302969,-0.206230,-0.184043,0.065872,-0.349111,-0.242976,0.071047,-0.098778,0.117719,0.521091,-0.010108,-0.256619,-0.066579,0.377422,-0.043340,-0.368657,0.242134,0.069729,-0.238542,0.019022,0.162742,0.198307,-0.136922,-0.304329,0.041390,-0.865214,0.141777,0.039312,0.044174,-0.666586,0.616023,0.092710,-0.271559,-0.293783,-0.598341,-0.029511,0.308016,0.351045,0.558289,-0.508241,0.094669,-0.293322,0.364170,0.869386,0.271205,-0.674694,0.383838,-0.299473,-0.127378,-0.084811,-0.663865,-0.597979,-0.260657,0.117590,-0.061220,-0.294943,0.599847,-0.377163,0.260284,-0.201429,0.072655,-0.158435,-0.369443,-0.324187,-0.188657,-0.302039,-0.412729,-0.546799,0.114641,0.077588,-0.156627,0.859201,-0.747867,-0.081064,0.273145,0.096572,-0.354523,0.428052,0.230315,-0.134432,-0.115693,-0.077527,0.099280,-0.308436,0.398337,0.073648,0.332031,-0.060265,0.248053,-0.208117,0.773388', '24284209', '1877596', '27602116', '3718665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30223840', '脱欧：无理之战', '剧情', '本尼迪克特·康伯巴奇将主演聚焦英国脱欧的2小时新剧《脱欧》(Brexit，暂定名)，饰演公投官方竞选组织“Vote Leave”的首席总监多米尼克·卡明斯。该剧将探索这场数据驱动的政治运动，这是现代史上最具争议、最有争议的政府公投之一。剧集由托比·海恩斯执导，剧作家詹姆斯·格拉汉姆操刀剧本，今年下半年开拍。', '本尼迪克特·康伯巴奇', '托比·海恩斯', 7.7, 16184, 'tt8425058', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2544474921.jpg', 0.4, 1.9, 28.4, 51, 18.3, '0.006239,-0.232300,-0.382321,0.531855,0.592113,0.053928,-0.240629,0.273605,-0.138110,-0.268173,0.324650,0.980990,-0.505671,-0.242102,0.690062,-0.066453,-0.802047,-0.602354,-0.576493,0.156290,0.013060,-0.861003,-0.013998,0.093594,-0.020486,-0.306443,0.956487,-0.013581,-0.408196,0.125839,1.039001,0.230461,0.274928,-0.107677,0.602935,-0.326741,0.256192,-0.621626,-0.343949,0.550460,0.014226,-0.167798,-0.075539,0.133263,0.295604,0.489388,0.261045,-0.150077,0.405300,-0.361521,0.908024,-0.514900,-0.212969,-0.354310,0.432554,0.319080,-0.078227,0.686773,-0.092085,-0.033710,-0.416116,-0.457229,-0.646995,-0.086920,0.107635,0.535630,-0.261370,0.175740,-0.499527,-0.032581,-0.388704,0.075152,-0.123933,0.498198,0.260696,-0.016750,0.275125,0.423957,-0.005256,0.603052,0.233354,-0.218625,-0.381136,-0.008707,0.102679,-0.663292,-0.177257,-0.589530,-0.098554,0.077926,0.039351,-0.108163,0.610985,0.360803,-0.562992,0.005101,-0.098253,-0.749956,0.343458,-0.206861,0.147124,-1.157338,-0.165804,0.511837,0.356878,-0.692789,0.274590,-0.264294,0.604188,-0.177843,-0.039649,0.427320,0.171328,0.069909,0.503245,-0.056540,0.274913,-0.670247,-0.257765,0.178452,-0.054804,0.065139,-0.349454,0.158378,0.571665,-0.508792,-0.301795,0.228654', '1298616', '26990609', '30397916', '34961898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30223888', '永恒族', '动作', '公元前5000年，“天神族”的“审判者”阿里瑟姆从奥林匹亚星挑选10位拥有超能力的“永恒族”，派遣他们前往地球抵御“变异族”的入侵。几千年来，永恒族一直帮助人类抵御变异族入侵。最后一批变异族在1521年被消灭后，永恒族内部对于是否继续保护人类一事产生分歧，最终决定分开，并等待阿里瑟姆将他们召唤回母星。时间到了现在，瑟西（嘉玛·陈 Gemma Chan 饰）和丝派特（莉亚·麦克休 Lia McHugh 饰）一同住在英国伦敦。500年前，瑟西与前男友伊卡瑞斯（理查德·麦登 Richard Madden 饰）分开，并结交了在伦敦自然史博物馆工作的戴恩·惠特曼（基特·哈灵顿 Kit Harington 饰）。一天晚上，一位名叫克罗的变异族突袭三人，伊卡瑞斯却突然出现，暂时击退克罗。瑟西、丝派特和伊卡瑞斯意识到情况不妙，于是决定紧急召集其他人以应对新的威胁……', '嘉玛·陈', '赵婷', 5.8, 117433, 'tt9032400', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2677303737.jpg', 5.5, 23.2, 49.7, 18.1, 3.6, '0.229832,0.451476,-0.444139,0.175874,0.177650,-0.065342,0.415449,0.040067,-0.209859,-0.713618,0.081689,0.407674,0.153621,0.124665,0.275527,-0.111069,-0.609716,-0.146589,0.284282,-0.110022,-0.440787,-0.039972,-0.293169,-0.305631,0.121132,-0.753164,0.629554,-0.078385,-0.240879,0.482180,-0.016682,0.940758,-0.306402,0.236275,-0.030308,-0.095315,0.298328,-0.120021,-0.372453,0.361696,-0.296274,0.221128,-0.252708,0.205412,0.293625,0.114135,0.249813,-0.537727,0.024017,-0.281505,-0.083620,-0.441146,0.187206,0.043305,0.823303,-0.425439,0.178922,0.406234,-0.064320,-0.165612,-0.142955,0.056341,-0.799332,0.153502,-0.139789,0.133642,-0.536034,-0.091207,0.040684,-0.035194,0.150998,-0.161796,-0.055221,1.109617,0.129258,0.146802,0.108885,-0.157773,-0.552362,-0.188578,0.677546,-0.463394,-0.407642,-0.189612,0.419256,-0.587083,-0.294188,-0.266865,-0.017636,-0.110462,0.239823,0.274845,0.324034,0.656336,-1.024821,-0.233314,-0.628603,-0.388082,0.432037,-0.472594,0.178803,-0.840058,0.033016,0.271554,-0.449890,0.346557,0.474677,-0.035439,0.565363,-0.619865,0.368612,0.403499,0.602636,-0.607758,0.414076,-0.273741,0.143383,-0.350773,0.268719,0.583198,0.577087,0.244975,0.079455,0.148093,0.303442,0.240349,-0.350948,0.511798', '20326665', '1305096', '