INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30225296', '柳烈的音乐专辑', '剧情', '在1994年歌手柳烈第一次做广播主持人的那天，经营母亲留下的面包店的美秀（金高银饰）与偶然出现的贤宇（丁海寅饰）相遇了。虽然彼此有了心动的感觉，但却因为意外事件而失去联系。直到三年后，两个人又奇迹般的再度重逢。伴随着广播节目《柳烈的音乐簿》，美秀和贤宇在各种偶然和必然的反复中，找寻着同一个频率。', '金高银', '郑址宇', 7.9, 71527, 'tt10763618', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2561996109.jpg', 0.3, 2.2, 25.1, 47.5, 25, '0.326740,-0.024029,-0.858087,0.726925,0.370338,-0.508117,1.075403,0.137769,-0.744825,-0.376300,0.242082,0.910967,-0.528117,0.355257,0.217030,-0.143526,-0.062781,-0.876957,0.134248,-0.225340,-0.220392,-0.298747,-0.155593,-0.000865,-0.134318,-0.141992,0.449273,0.036113,-0.118298,0.905690,0.197469,-0.078886,-0.145343,0.663908,-0.306021,-0.043436,0.062530,0.470157,-0.257859,0.137218,0.375165,-0.492993,-0.233411,-0.012271,-0.231598,0.514505,0.662231,-0.463325,-0.194577,0.274220,0.357935,-0.095746,-0.236001,0.027237,0.247051,0.347193,0.399002,0.382651,-0.444025,-0.037606,0.002735,0.226099,-0.661418,0.170691,0.077990,0.317485,-0.435966,0.602051,0.136077,-0.102054,0.102199,-0.250283,0.321672,0.539106,0.379978,0.451753,-0.563193,-0.165558,-0.374951,0.129427,0.822910,0.129783,-0.409084,0.467333,-0.154771,-0.645219,-0.144313,0.051650,-0.566422,0.227563,0.120268,0.292849,-0.327825,0.208489,-0.804038,0.126465,0.071894,-0.054847,0.083597,-0.315498,-0.346201,-0.973728,-0.294243,-0.574846,-0.429362,0.268156,-0.096087,-0.161162,0.685142,-1.205616,0.347774,0.701592,0.128246,-0.173141,0.734189,0.110564,0.134189,-0.179721,-0.019719,0.006085,-0.210049,0.325142,0.241684,0.456559,-0.044141,0.182327,-0.545769,0.382978', '1296534', '1308755', '11541282', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30229667', '智能大反攻', '喜剧', '《智能大反攻》是由美国索尼哥伦比亚影片公司和索尼动画联合出品的原创喜剧冒险动画电影。该片由荣获奥斯卡最佳动画长片大奖的《蜘蛛侠：平行宇宙》金牌制作团队重磅打造，可谓2020年最值得期待的动画巨制。迈克尔·里安达（《怪诞小镇》）担任导演、菲尔·罗德和克里斯托弗·米勒（《蜘蛛侠：平行宇宙》《乐高大电影》）担任制片人。特立独行又充满创意的凯蒂·米切尔考上了她梦寐以求的电影学院。她本打算坐飞机前往学校，但热爱大自然的父亲瑞克却决定开车载全家人一起送凯蒂上大学，在她离开之前增进家人感情。除了凯蒂和瑞克，米切尔一家还包括乐天派的母亲琳达和性格古怪的弟弟艾伦，以及胖乎乎的可爱八哥犬蒙奇，他们展开了一段刺激的家庭公路自驾游。但意外发生了，智能科技突如其来地向人类发起反攻，彻底打乱了米切尔一家的计划。人们最常用的电子设备，从手机到家用电器，乃至一系列最新的私人机器人，决定在全球范围内向人类进攻。在两台友好的故障机器人帮助下，米切尔一家齐心协力互相帮助，共同面对这次非同寻常的挑战！', '奥利维娅·科尔曼', '迈克尔·里安达', 7.3, 18397, 'tt7979580', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2637896820.jpg', 0.5, 4.6, 38.5, 42.6, 13.9, '0.201969,-0.026303,-0.632007,0.590708,0.279735,-0.111619,0.434618,0.163470,-0.309030,-0.135213,0.161976,0.762204,-0.162949,0.036017,0.347159,-0.134866,-0.460677,-0.305928,-0.122326,-0.029627,-0.018865,-0.526389,-0.233926,-0.331936,0.103024,-0.275696,0.724014,-0.147242,-0.360432,0.328198,0.329116,0.117138,-0.157661,0.039378,0.110418,-0.052280,0.230444,-0.112617,-0.585887,0.294526,-0.042641,0.106872,-0.045312,0.081668,0.129650,0.198239,0.576068,-0.125472,-0.041327,-0.043542,0.435073,-0.176087,-0.093013,-0.183945,0.102290,0.103698,0.062936,0.097015,-0.005112,0.211475,0.053729,-0.361864,-0.731487,0.051029,0.121576,-0.154972,-0.434466,0.357161,-0.165365,0.043871,0.237875,-0.379362,-0.000344,0.358041,0.519156,0.378947,0.001235,0.413887,-0.214772,0.199117,0.444810,-0.060005,-0.533118,0.298393,-0.155752,-0.411355,-0.310921,-0.308289,-0.604896,0.039286,0.296223,-0.166216,0.065002,0.274621,-0.643049,0.045699,-0.082099,-0.335090,0.230375,-0.265408,0.147161,-1.109351,0.095761,-0.275733,-0.068395,-0.192845,0.133160,-0.242380,0.713106,-0.692720,0.033642,0.427775,0.165568,-0.439350,0.666998,0.008197,0.084138,-0.335913,-0.213414,0.138685,-0.071952,0.223731,-0.115300,0.303783,0.154358,-0.250922,-0.261145,0.378258', '2369613', '24751811', '3318306', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3023164', '点球成金', '剧情', '在美国职业棒球大联盟MLB中，比利（布拉德•皮特 Brad Pitt 饰）所属的奥克兰运动家队败给了财大气粗的纽约扬基队，这让他深受打击。雪上加霜的是三名主力纷纷被重金挖走，未来的赛季前途渺茫。在管理层会议上，大家一头雾水，只有他暗下决心改造球队。一次偶然的机会，他认识了耶鲁大学经济学硕士彼得（乔纳•希尔 Jonah Hill 饰），两者对于球队运营的理念不谋而合。凭借直觉和经验，他仿佛找到了破解金元棒球的钥匙。他聘请彼得作为自己的顾问，一起研究如何打造最高胜率的球队。他们用数学建模的方式，逐渐开始挖掘上垒率的潜在明星，并通过软磨硬泡将他们招致麾下。他们不在乎高层的冷嘲热讽，只是专心地为球队寻找信心和实力的根源，终于新的赛季开始了……影片改编自迈克尔•刘易斯的《魔球—逆境中致胜的智慧》（Moneyball: The Art of Winning an Unfair Game）。', '布拉德·皮特', '贝尼特·米勒', 8.3, 99898, 'tt1210166', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1393286611.jpg', 0.1, 0.8, 14.7, 52.8, 31.6, '0.005228,0.217250,-0.571581,0.666958,-0.230269,-0.224785,0.117082,0.063048,-0.607070,-0.158050,0.220214,0.675909,-0.030712,0.096460,0.131241,-0.365374,-0.164208,-0.870449,-0.021017,-0.134367,-0.327050,-0.744838,-0.545522,-0.266313,-0.004899,-0.251902,0.811013,0.059015,-0.397047,0.247296,0.149629,0.488644,0.486164,0.148223,0.021883,-0.103670,0.354047,-0.092343,-0.381899,0.351132,-0.057350,-0.038869,-0.242011,0.215087,0.208373,0.365191,0.498937,-0.228936,0.204075,-0.251224,0.267620,-0.261172,-0.097096,0.102306,0.309586,0.210137,0.237833,0.261203,0.123801,0.103253,-0.245235,-0.190726,-0.995208,-0.023950,0.162293,0.063770,-0.631126,0.479620,-0.230241,0.006306,-0.035132,-0.064102,-0.090962,0.416629,0.531337,0.036189,-0.140044,-0.043823,-0.349988,0.114932,0.483815,-0.166975,-0.221013,0.150025,-0.217204,-0.385343,-0.094720,-0.422999,-0.242728,-0.110352,0.345529,0.203442,0.210895,0.120041,-0.599767,0.331667,-0.144007,-0.424531,0.060626,-0.427867,0.423955,-0.777826,-0.079388,-0.328593,-0.395840,-0.135210,0.042668,-0.261711,0.988254,-0.826591,-0.304755,0.640833,0.279647,-0.419779,0.552084,-0.090291,0.191639,-0.438764,-0.125491,0.051449,-0.069383,0.259827,0.003842,0.483694,0.146933,-0.366366,-0.288032,0.621869', 