INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30234315', '摄影机不要停！', '喜剧', '郊外一座废弃的工厂内，一支摄制组正在拍摄一部粗糙简陋的僵尸片。导演日暮隆之（滨津隆之 饰）不满女主角松本逢花（秋山ゆずき 饰）的演技，因此暴跳如雷，大吼大叫。在工作人员晴美（しゅはまはるみ 饰）的建议下，剧组暂时停止拍摄。休息间隙，晴美向松本以及饰演僵尸的男演员神谷和明（长屋和彰 饰）讲述了这座工厂在二战期间的恐怖旧事。就在此时，不祥的巨响突然传来，未过多久，一名工作人员化作僵尸突然出现，对其他剧组成员展开疯狂啃咬。演职员们四散而逃，而疯狂的导演却举起摄像机，开始了他梦寐以求的电影的拍摄。30多分钟的血腥屠杀，令所有人始料未及的是，这还并不是这部恐怖电影的全部！©豆瓣', '滨津隆之', '上田慎一郎', 8.2, 179897, 'tt7914416', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2541824676.jpg', 0.9, 2.3, 16.1, 47.4, 33.3, '0.179795,-0.094659,-0.784918,0.342579,0.428509,0.053043,1.025745,0.214278,-0.150827,-0.351621,0.473097,0.425927,-0.441738,0.293917,0.155200,-0.256779,-0.285174,-0.729767,-0.436033,-0.054980,-0.037091,0.096188,-0.285675,-0.206495,-0.047007,-0.211462,0.741733,0.184781,-0.207867,0.519624,0.474264,0.118791,-0.375727,0.329925,0.201115,0.003472,0.077379,-0.250417,-0.102545,-0.027289,-0.160908,-0.430508,-0.114867,0.082385,-0.079690,0.559474,0.525221,-0.235225,-0.241766,0.141003,0.353749,-0.311141,-0.118052,0.209546,0.360003,0.003788,0.211520,-0.123526,-0.233716,0.322693,-0.290598,-0.045053,-0.757965,0.026401,-0.003429,0.473800,-0.351617,0.412168,-0.114359,0.008079,0.125858,-0.258274,0.094058,0.127051,0.230218,0.363746,-0.114395,0.027747,-0.152436,0.429674,0.566577,-0.027041,-0.287883,0.364092,0.260436,-0.436472,-0.279762,0.138314,-0.440471,-0.157119,0.403301,0.161152,0.135228,-0.184603,-0.758276,0.027271,0.028494,-0.501053,0.030653,-0.043883,-0.287398,-1.127193,-0.005636,-0.206409,-0.045162,-0.051869,0.025173,-0.045144,0.628690,-0.554000,0.058312,0.281185,0.114503,-0.076890,0.340471,-0.380185,-0.148984,0.315217,-0.044749,0.052452,0.219491,0.575406,0.246377,0.446788,-0.151624,-0.553051,-0.574881,0.264607', '10466639', '1316693', '3318306', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30234891', '红心女王', '剧情', '安妮（崔娜·蒂虹 Trine Dyrholm 饰）是一名经验非常丰富的律师，擅长的领域是青少年性侵案。她和丈夫皮特（马格努斯·克雷佩 Magnus Krepper 饰）结婚多年，夫妻两人之间的感情非常的稳定。在外人眼中，安妮是一位事业和爱情双丰收的人生赢家。可是，安妮的生活在皮特和前妻所生的儿子古斯塔夫（古斯塔夫·林德 Gustav Lindh 饰）搬来和他们同住的那一刻起崩塌了。古斯塔夫的个性粗暴而又叛逆，对安妮这位继母毫无尊重可言，可就是这样的针锋相对让安妮的内心里荡漾起了别样的波纹，在古斯塔夫的身上，她找回了久违的激情。最终，安妮和古斯塔夫之间逾越了伦理道德的红线，而为了挽救这段关系给自己的家庭和事业带来的毁灭性的破坏，安妮决定利用自己的专业知识，牺牲古斯塔夫。©豆瓣', '崔娜·蒂虹', '梅尔·图琪', 7.2, 11153, 'tt8378126', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554682676.jpg', 1.1, 4.4, 40.1, 43.7, 10.6, '0.478743,-0.126440,-0.817539,0.835944,-0.346292,-0.463102,1.000507,0.191292,-0.570087,-0.085663,0.151820,0.859671,-0.068462,0.269424,0.307862,0.157671,-0.140216,-0.869916,-0.034809,-0.110060,-0.220755,-0.724724,-0.350178,-0.023438,-0.214236,-0.316573,0.767215,-0.160837,-0.317789,0.599003,0.363526,0.205570,0.230541,0.438951,-0.057640,0.100642,-0.076594,-0.055901,-0.456506,0.044398,0.205742,0.048884,0.019433,0.534829,-0.069353,0.405869,0.554152,-0.310333,-0.086264,-0.057037,0.470812,-0.289962,0.098014,0.205546,0.136505,-0.111727,0.273054,0.345555,-0.232727,-0.121003,0.210380,-0.087786,-0.859569,-0.024866,0.023691,-0.020775,-0.874752,0.799219,0.037854,-0.335057,0.259681,-0.249922,0.116047,0.478272,0.220448,0.630006,-0.549276,0.046567,-0.367201,-0.000032,0.554795,-0.037254,-0.272634,0.456354,-0.611145,-0.253845,-0.151323,-0.197294,-0.616240,-0.329446,0.236796,0.175346,0.087239,0.432421,-0.800360,0.099665,-0.252335,0.103461,-0.045617,-0.769907,0.044695,-0.470069,-0.610106,-0.916344,-0.580847,0.021299,0.157967,-0.443965,0.820095,-1.107870,0.102964,0.470079,0.324539,-0.479365,0.665214,0.522899,0.211253,-0.356014,-0.100707,0.122445,-0.190795,-0.010845,0.084262,0.358770,0.201061,0.148388,-0.221116,0.618105', '24756472', '20277433', '35030151', '4301215');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30235440', '小小的愿望', '剧情', '突然患上肌肉萎缩症的高中生高远（彭昱畅 饰），被医生告知时日不多，决心在临死之前完成一个愿望，那就是成为一个真正的男人！得知这个消息的身边两位好兄弟徐浩（王大陆 饰）和张正阳（魏大勋 饰），为了兄弟最后的愿望，不惜一切奋战到底！©豆瓣', '彭昱畅', '田羽生', 5, 133891, 'tt10219674', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2567277578.jpg', 14.2, 37.5, 37.1, 8.4, 2.8, '-0.124937,0.203488,-0.329637,0.459519,-0.234617,-0.495542,0.694692,-0.049841,-0.461592,-0.594395,0.188558,0.802295,-0.024926,0.384098,0.203768,-0.137197,-0.337057,-0.387604,0.118735,-0.065449,-0.335801,-0.180337,-0.332065,-0.186479,-0.159838,-0.324266,0.878477,0.105202,-0.007999,0.379161,0.547814,0.203576,0.208475,0.279648,-0.326779,0.053328,0.162216,-0.060038,-0.654218,0.050982,0.214661,-0.004428,0.018228,0.173636,-0.234815,0.061315,0.339351,-0.095324,-0.382506,-0.311686,0.424977,-0.408905,0.107636,0.132074,0.183374,0.085507,0.597931,0.210205,-0.377740,-0.159309,0.080930,-0.230038,-0.833044,-0.082263,0.520542,0.162016,-0.312828,0.170255,-0.488696,-0.075289,0.111745,-0.423083,0.376844,0.650742,0.376038,0.188706,-0.677007,-0.037968,-0.530302,0.290601,0.703348,-0.060777,-0.070363,0.072894,0.332118,-0.484041,-0.045164,0.011832,-0.012790,0.207169,0.097638,-0.046470,-0.325309,0.118765,-0.351563,-0.201732,-0.347244,0.070902,0.128199,-0.301626,-0.264213,-0.156559,-0.077633,0.077910,0.028055,0.299754,0.121224,-0.194443,1.051830,-0.657824,0.046868,0.146037,0.538774,-0.554730,0.535621,0.324796,0.199492,-0.577662,0.220762,0.093527,-0.023856,0.073860,0.224245,0.283191,-0.210390,-0.008358,-0.381538,0.402831', '27602116', '4301278', '24284209', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30237255', '两大无猜', '喜剧', '青梅竹马的好友莎夏和马库斯闹翻了，并且 15 年都没说过话。莎夏成为了洛杉矶的名厨，回到家乡旧金山开了一家餐厅，就在这里，她遇到了老朋友 — 一位快乐、知足的音乐家，他一直与父母同住并为父亲打工。尽管两人都不情愿和好，但他们很快就发现彼此之间还存在旧的火花，或许还擦出了一些新火花。', '黄阿丽', '纳卡那驰·韩', 6.2, 9752, 'tt7374948', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2556816232.jpg', 2.4, 16.8, 52.9, 21.9, 6.1, '0.479300,-0.027231,-0.786847,0.312520,-0.015267,-0.722615,0.717707,-0.021749,-0.413974,-0.291969,-0.226777,0.950204,-0.224434,0.532007,0.005950,0.080642,-0.438844,-0.696971,0.430603,-0.449474,-0.273833,-0.449834,-0.260480,-0.053685,-0.216344,-0.192971,-0.014050,0.103133,0.095626,0.452287,-0.029069,-0.247425,0.101009,0.788726,-0.541416,0.236197,0.045629,0.735070,-0.232843,-0.115326,0.173671,-0.217110,-0.014819,-0.073002,0.280854,0.444394,0.234404,0.114252,-0.023226,0.222160,-0.080667,-0.185042,0.098853,0.226525,0.515617,-0.138794,0.427700,0.122809,-0.087792,-0.001205,-0.380633,0.008349,-0.684292,0.151043,-0.057121,-0.060015,-0.583579,1.036588,-0.030792,-0.203799,0.039620,-0.453963,0.515374,0.221815,0.145016,0.391550,-0.454173,0.121780,-0.537455,0.416015,1.149277,-0.072937,-0.169944,0.447144,-0.206626,-0.492869,-0.029278,0.012494,-0.256391,0.021761,0.084862,0.203188,-0.134467,0.036411,-0.673279,-0.065939,-0.266175,-0.152063,0.300471,-0.451879,0.236737,-0.541611,-0.154820,-0.622586,-0.433784,0.153594,0.061390,-0.049840,0.721941,-0.993613,0.263211,0.266468,0.550839,-0.629810,0.920992,0.140884,0.110653,-0.065301,0.065441,0.075714,-0.014496,0.303362,0.512422,0.390384,0.042248,0.027420,-0.146102,0.231224', '25721544', '1308755', '1292219', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30238963', '光', '剧情', '电影是一段围绕着两兄弟的故事。哥哥文光（庄仲维 饰）个性敏感，无法专注集中，更不善与人交际。尽管如此，弟弟（张顺源 饰）一直设法帮助文光找到工作。然而，文光屡次搞砸面试，闯祸惹麻烦，弟弟气愤又无奈。直到有一天，弟弟听到哥哥房间传来的音乐声，才意识到哥哥的音乐天赋一直默默闪耀着。', '庄仲维', '郭修篆', 7.3, 9625, 'tt9121254', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2623438495.jpg', 0.3, 3.7, 38.1, 48.4, 9.4, '-0.291026,-0.062809,-0.383451,0.537307,0.074279,-0.288266,0.399797,0.337813,-0.733874,-0.363638,0.263524,0.343225,-0.005693,0.094088,0.139848,-0.022080,-0.246322,-0.467191,0.373403,0.210149,0.203254,-0.878915,0.258414,0.137452,-0.058589,-0.542312,0.225771,-0.286776,-0.141748,0.385082,0.030353,0.133402,-0.461137,0.561911,0.278875,-0.244494,0.025043,0.069696,-0.283679,-0.161342,0.345520,0.015076,-0.199062,-0.185703,0.176897,-0.271848,0.576815,0.163581,-0.411527,0.240553,0.523923,-0.092354,-0.274077,-0.245640,0.248469,0.220098,0.591152,0.184123,-0.090104,-0.174841,-0.345276,-0.022172,-0.336803,0.209070,0.310138,0.281724,-0.319000,0.056067,-0.031935,-0.061960,0.365093,-0.567206,0.111018,0.262961,0.219675,0.499177,-0.777945,0.230489,-0.166889,-0.125731,0.540839,-0.173778,0.306033,0.492252,0.297775,0.145458,0.204257,-0.106650,-0.760735,0.213780,-0.025169,0.253875,-0.323243,0.078757,-0.112858,-0.024347,0.339759,-0.419052,0.331446,-0.653717,0.028654,-0.121690,-0.123666,-0.040317,-0.023982,0.275951,-0.155576,-0.320854,0.907523,-0.696102,0.328587,0.647746,0.239965,-0.039198,0.592387,-0.053927,-0.139423,-0.339719,-0.019404,0.001384,-0.218075,-0.273741,0.075246,0.055256,-0.069326,-0.334417,-0.364280,0.036375', '3445516', '1293175', '25738406', '26348103');
