INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30241298', '南山的部长们', '剧情', '电影"南山的部长们"以韩国中央情报部(KCIA)的部长们(副总理级)与他们所主导的政治阴谋为素材， 原作为揭露韩国政治内幕的同名小说，以历代中央情报部的部长金载圭和金炯旭的故事为中心重新创作而成。1979年下半年，YH贸易女工笼城事件、新民党总裁金泳三的国会议员除名事件以及10月的釜马事件先后爆发，政局不定。中央情报部金载圭和强硬派总统警卫室室长发生摩擦，朴正熙对他逐渐反感和不信任。1979年10月26日，在汉城钟路区宫井洞中央情报部官邸中，朴正熙和总统警卫室室长在宴会酒席中被金载圭用手枪枪杀。', '李秉宪', '禹民镐', 8.1, 146310, 'tt11358398', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2581888792.jpg', 0.2, 1, 17.4, 54.1, 27.3, '0.161763,-0.074865,-0.270031,0.455487,0.242584,-0.097390,0.131606,0.213620,-0.823821,-0.603094,0.225827,0.794199,-0.368381,-0.027487,0.473990,-0.089565,-0.560268,-0.808566,-0.391911,0.062205,0.034735,-0.519481,-0.158573,-0.163495,0.023357,-0.157220,0.886425,-0.053555,-0.036549,0.499859,0.247681,0.468062,-0.001185,0.304381,0.231796,-0.015434,0.392466,-0.177225,-0.632945,-0.069485,0.013100,-0.498146,-0.426723,-0.292068,0.229781,0.088050,0.489694,-0.470093,-0.109070,-0.407865,0.522730,-0.241924,-0.163661,0.097963,0.884212,0.433071,0.322858,0.769057,-0.464118,-0.006584,0.026090,-0.323328,-0.311863,-0.187606,0.138872,0.351320,-0.087242,0.483590,-0.301603,0.097443,0.431974,-0.231690,0.176626,0.616535,0.171132,0.315992,-0.274802,0.204648,-0.233218,0.143541,0.662315,0.035809,-0.379935,-0.046650,0.129983,-0.249518,-0.316951,-0.473883,-0.070689,0.073139,-0.030741,-0.080458,0.254606,0.450696,-0.583227,-0.232718,-0.040603,-0.451713,0.268039,-0.002412,-0.049825,-0.944236,-0.331338,-0.390031,0.268843,-0.421246,0.393628,-0.001204,0.616725,-0.707227,0.236401,0.279347,0.202521,-0.483635,0.744276,0.345946,-0.117371,-0.471508,-0.287527,-0.416586,0.071659,0.695811,-0.122399,0.412690,0.195892,-0.536049,-0.009612,-0.072284', '25723905', '26365262', '26990609', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30241301', '衣橱', '恐怖', '自从妻子过世后，尚元（河正宇饰）和女儿的关系越来越疏远，于是他决定带着女儿搬到乡下，修复彼此的关系。但即使搬家后，尚元仍专注于自己的工作，不多关心女儿。女儿多了更多独处的时间，且开始表现出奇怪和令人不安的行为，而尚元也开始在家中遭遇离奇的现象。某天，女儿竟突然在衣橱前消失得无影无踪……无论尚元如何寻找，就是找不到女儿的踪迹。此时，一名叫做庆勋（金南佶饰）突然找上门来，并称自己知道关于那衣橱的秘密。为了寻找尚元的女儿，庆勋坚持要尚元和他一起闯入「中间地带」，于是两人开始揭开隐藏于衣橱背后不可告人的真相……', '河正宇', '金光彬', 5.8, 8422, 'tt11727052', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2580988442.jpg', 4.6, 25.9, 51.8, 12.6, 5.1, '0.221900,-0.125050,-0.986452,0.384167,-0.016921,-0.370158,0.758808,0.135963,-0.632746,-0.635395,-0.075073,0.571340,0.023771,0.440153,0.126603,0.134678,-0.426696,-0.670481,-0.079532,-0.514165,-0.345895,-0.561227,-0.316915,-0.237755,-0.148750,-0.139370,0.518998,0.100842,-0.156293,0.210784,0.356892,0.142857,-0.281598,0.734212,-0.110255,-0.117189,-0.021541,0.473220,-0.345578,0.002610,0.367449,-0.066772,-0.244262,0.064099,-0.005372,0.413594,0.580696,-0.082372,-0.336710,-0.076815,0.239997,0.037331,-0.026902,0.037664,0.409201,0.095585,0.443724,0.368309,-0.287159,-0.069732,0.015150,0.024260,-0.527676,0.225457,0.206996,0.011904,-0.460040,0.065970,-0.091281,-0.260665,0.219010,-0.735197,0.307473,0.596691,0.153495,0.317734,-0.379668,-0.002353,-0.417765,-0.258035,0.544846,-0.184181,0.103620,0.530621,0.091863,-0.096596,0.041138,-0.431243,-0.202149,-0.060877,0.138409,0.316251,-0.226974,0.276976,-0.227837,-0.040478,-0.173710,-0.019986,0.255506,-0.462412,-0.092216,-0.068924,-0.194912,-0.361359,-0.302691,0.240575,-0.135050,-0.325953,0.563410,-0.772726,0.281315,0.452890,0.358563,-0.763766,0.430173,0.208889,0.190167,-0.369860,0.034555,0.026876,-0.125105,0.202643,0.124615,0.029945,-0.046755,-0.046033,-0.416959,0.169521', '35073886', '1303485', '1301022', '1309125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30242164', '海吉拉', '剧情', '面对不可抵抗的改变后，自己究竟是她？还是他？两个性格迥异的女性却意外成了最好的姐妹——何希真、刘宛婷，他们同时喜欢上文棠生，但其实文棠生早就注意到刘宛婷，在好友希真的让步下，婉婷跟棠生进入交往，三人也形成亲密的三角关系，直到一场意外让宛婷发现原来她具有双重性征，而此刻她必须选择作为其中一个性别活下去。宛婷突如期然的不告而别让棠生和希真措手不及，多年后，希真跟棠生身边出现了一位长相清纯的男孩——刘廷。', '许光汉', '蔡宓洁', 7.1, 58355, 'tt8523074', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2524187708.jpg', 1.1, 6.7, 42.8, 37.2, 12.3, '0.322962,0.139120,-0.944290,0.557433,-0.103721,-0.380812,0.585390,-0.086513,-0.198555,-0.330890,-0.065854,0.765566,-0.352686,0.278342,0.041831,-0.116828,0.079963,-0.940615,-0.180333,-0.147974,-0.424381,-0.527171,-0.147893,0.096752,-0.138450,-0.182392,0.645905,-0.201292,-0.365660,0.540976,0.429296,0.387277,-0.241108,0.586437,0.053956,-0.087895,-0.218956,0.171197,-0.434239,-0.023339,0.288472,-0.312067,-0.253618,0.536453,0.164634,0.552442,0.753922,-0.531608,-0.695410,-0.064736,0.145638,-0.156583,-0.559977,-0.050133,0.229286,-0.305338,0.348706,0.099961,0.164666,-0.044229,0.033641,0.201032,-0.568461,0.128313,0.182063,0.077827,-0.522040,0.237767,0.236902,-0.265771,-0.193592,-0.528158,0.555974,0.382918,0.248316,0.263741,-0.368073,0.178141,-0.304962,-0.436099,1.203045,0.398178,-0.448568,0.405568,-0.540564,-0.384367,0.214795,-0.290385,-0.433348,0.419064,-0.075344,0.152364,-0.003961,-0.170160,-0.277595,-0.150160,-0.382841,0.420104,-0.123316,-0.707765,0.117759,-0.036684,-0.314408,-0.596618,-0.602430,0.421739,-0.315772,-0.639588,0.671714,-0.870740,0.071403,0.176336,0.540004,-0.866879,0.632089,0.133498,0.275604,-0.130881,-0.072798,0.063587,-0.310793,-0.425295,-0.035113,0.244231,-0.124852,-0.064146,-0.556810,0.120805', '4145476', '1494897', '1301022', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30243396', '逃跑', '悬疑', '克洛伊（基拉·艾伦 Kiera Allen 饰）从一出生起就和母亲（莎拉·保罗森 Sarah Paulson 饰）过着相依为命的生活，在她们的世界里，父亲这一角色是从未存在过，也不可提及的。因为早产，克洛伊的健康面临着非常严重的打击，时时刻刻都在遭受着死亡的威胁，可即便如此，母亲也从未放弃过克洛伊，她凭借着自己坚强的力量将克洛伊抚养长大。克洛伊体弱多病，半身不遂只能依靠轮椅行动，母亲是她和外界唯一的联系，在母亲的帮助之下，克洛伊靠着自学参加了大学的入学考试，正在焦急的等待着考试结果的公布。某日，克洛伊对自己每天都要服用的药物产生了怀疑，通过种种调查，她震惊的发现这些药物正是导致自己无法行走的元凶。©豆瓣', '莎拉·保罗森', '阿尼什·查甘蒂', 6.8, 15002, 'tt8633478', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2587085523.jpg', 0.8, 7, 52.4, 31.8, 7.9, '0.010420,-0.044385,-1.000752,0.685684,-0.316508,-0.245330,0.831238,0.051512,-0.730965,-0.421292,0.202178,0.732507,-0.048813,0.495915,0.086590,0.021647,-0.160807,-0.556438,-0.027951,0.039395,-0.369697,-0.635464,-0.253346,-0.192712,-0.127108,-0.728795,0.595343,-0.148789,-0.421831,0.324991,0.126711,0.250577,0.008411,0.643645,-0.256000,0.017886,-0.250916,0.114855,-0.307044,0.193979,0.526737,-0.371977,-0.080177,0.438026,0.167022,0.354156,0.649984,-0.456168,-0.199167,-0.067873,0.421222,-0.305972,-0.040724,0.302784,0.610031,0.059892,0.033305,0.323799,-0.279234,0.200478,0.131801,0.049075,-1.087681,-0.190430,0.145575,0.344911,-0.878008,0.450578,-0.192808,-0.129239,-0.007425,-0.341366,0.251849,0.726004,-0.015587,0.411639,-0.522910,-0.024261,-0.504076,0.107239,0.746325,-0.245391,-0.285895,0.390881,-0.551225,-0.324906,-0.002244,-0.507655,-0.704483,0.051390,0.072595,0.306467,-0.511230,0.333829,-0.222368,0.070442,-0.161758,-0.472580,0.007678,-0.264559,0.044542,-0.546267,-0.122038,-0.503737,-0.690995,0.076630,-0.055144,-0.600051,0.796444,-1.023435,0.462343,0.626388,0.533099,-0.509137,0.533781,0.217436,0.270900,-0.111607,-0.190958,0.662429,-0.130840,0.314863,0.125021,0.277377,0.348184,0.090009,-0.385355,0.713589', '1793491', '1877596', '1866424', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30246061', '学区房72小时', '剧情', '某大学副教授傅重为了让女儿进入市重点小学，在72小时内出售现有房子，凑足钱款，买下对口学校的学区房。由于时间紧迫，傅重不得不以200万价格降价出售，钟点工牛阿姨声称儿子小宝正急于购买婚房，拿出自己多年的积蓄，双方一拍即合，立刻签约。正在皆大欢喜的时候，傅重又接到坏消息— —卖方坐地起价40万。傅重正为难之际，中介来电说有客户愿以市场价250万一次性付款购买傅重的住宅，这样，所有问题便可解决…… 而这位客户，正是有求于傅重的学生家长袁主席。是坚守诚信与牛阿姨履行合约，还是为孩子的未来，毁约将住宅高价转售他人，傅重面临两难抉择……', '管轩', '陈晓鸣', 7, 11200, 'tt10560614', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2560837532.jpg', 1.7, 6.6, 41.2, 40.7, 9.9, '-0.110538,0.241995,-0.234174,-0.074849,-0.131564,-0.347481,0.043326,0.243412,-0.312075,-0.399555,0.020843,0.403266,0.107388,0.378160,0.365179,-0.003419,0.050589,-0.107159,0.034589,-0.267063,0.097568,-0.871423,0.229101,-0.381601,-0.008008,0.319224,0.321825,0.104610,0.097244,-0.030909,0.102006,0.266431,-0.006262,0.268579,0.094351,-0.299478,-0.175210,0.159594,-0.613100,0.210704,-0.093689,0.175669,-0.045399,-0.086799,0.816081,0.501116,0.362346,0.176226,-0.434755,0.152956,0.363004,0.049659,-0.140467,-0.169266,0.123241,0.193877,0.587367,0.090728,-0.689132,0.071904,0.024054,-0.307226,-0.406490,-0.083572,0.084966,-0.466452,-0.513587,-0.007678,-0.155052,0.268288,0.105096,-0.365669,-0.225808,0.651060,0.241605,0.374699,-0.166493,0.004679,-0.419273,0.203952,0.413090,-0.075708,0.178504,0.020534,0.142676,-0.354202,0.514890,-0.234006,-0.159337,0.174803,0.033842,0.098605,0.385639,-0.524763,-0.412469,-0.252896,-0.253623,-0.362636,0.544581,-0.233367,-0.156455,-0.436064,0.065726,0.349636,0.099122,0.074193,0.553709,-0.052201,0.564566,-0.367266,-0.219695,0.205369,0.824513,-0.708696,0.566712,0.004835,0.280344,-0.493348,-0.035608,-0.440796,0.017311,0.559919,0.073779,-0.450540,0.091331,-0.260335,0.056411,0.161230', '1303724', '1304382', '1417543', '3558661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3024838', '独行侠', '动作', '1869年，一列驶往美国德克萨斯州科尔比镇的列车，羁押着即将被送往当地处决的杀人魔头卡文迪什（威廉·菲德内尔 William Fichtner 饰），未料途中卡文迪什在同伙的协助下逃脱。同在囚犯车箱内的印第安人杀手Tonto（约翰尼·德普 Johnny Depp 饰）和联邦检查官约翰·雷德（艾米•汉莫 Armie Hammer 饰）历经万险，侥幸逃生，谁知却被后者投入监牢。约翰身为骑警的老哥丹（詹姆斯·戴尔 James Badge Dale 饰）率手下追捕卡文迪什，结果遭到对方残忍屠戮。随行的约翰在越狱逃走的Tonto的帮助下再度捡回一条命，并得知骑警中叛徒的真身。对于这个本应死掉的人来说，也许只有戴上面具才能匡扶正义。白人和印第安人，两个原本没有任何交集的人踏上复仇之路……©豆瓣', '约翰尼·德普', '戈尔·维宾斯基', 7.1, 69570, 'tt1210819', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2121685760.jpg', 1.2, 6.9, 42.3, 37, 12.4, '0.223516,-0.055255,-0.545627,0.408242,-0.019148,-0.357021,0.790751,-0.077209,-0.408930,-0.321587,0.381860,0.510697,0.111291,-0.104914,0.394432,-0.083427,-0.470010,-0.376346,-0.117377,-0.172805,-0.291551,-0.435714,-0.504432,-0.201400,-0.060422,-0.412472,0.724243,0.213845,0.054815,0.618912,0.412757,0.529749,-0.213081,0.402645,-0.059899,-0.035140,0.366577,-0.423092,-0.237881,0.190356,-0.273029,-0.209446,0.043851,0.053354,-0.090961,0.472281,0.471296,-0.493438,0.129797,-0.288300,-0.054918,-0.416677,-0.069795,0.095215,0.315295,-0.102680,0.065011,0.509715,-0.055459,0.062505,0.384331,-0.100159,-0.590779,0.029262,0.051202,0.208876,-0.533072,0.249691,-0.430314,0.243525,-0.059962,-0.180529,0.087389,0.194337,0.182013,0.164340,-0.086129,-0.064816,-0.775362,-0.074109,0.617760,-0.298567,-0.149328,-0.237137,0.147525,-0.372396,0.193342,-0.322245,-0.266455,-0.094936,0.512757,-0.040016,-0.126864,0.150733,-0.387259,0.003167,-0.727779,0.066748,-0.149783,-0.144327,-0.096192,-0.690969,0.221210,0.052796,-0.241298,0.168417,0.009149,-0.092385,0.335176,-0.440947,0.240562,0.348831,0.268907,-0.346491,0.501398,0.046279,0.310636,-0.195023,-0.334816,0.594970,0.572658,0.505380,-0.010101,0.176415,-0.132057,-0.209895,-0.087320,0.261945', '1301345', '1316693', '1578663', '1301686');
