INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30249161', '哆啦A梦：大雄的月球探险记', '剧情', '月球探测器在月亮上捕捉到了白影，大雄认为这道白影是月亮上的兔子，惹来了大家的耻笑，于是哆啦A 梦为了帮助大雄，利用道具“异说俱乐部徽章”，在月球背面制造了一个兔子王国。一天，神秘少年露卡转学而来，与大雄和伙伴们一同前往月亮上的月兔王国展开了一场别开生面的浪漫想象力之旅。', '水田山葵', '八锹新之介', 7.2, 49781, 'tt9735672', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2557500825.jpg', 0.5, 4.2, 41.7, 40.9, 12.8, '0.112021,0.262755,-0.465011,0.660092,0.112683,0.020573,0.310970,0.128250,-0.124624,0.221538,0.108519,0.723655,-0.335002,0.299114,0.277370,0.123780,-0.569034,-0.553771,-0.103237,-0.363135,-0.611944,-0.400677,-0.109326,-0.098092,0.074128,-0.180756,0.493583,0.119048,-0.071535,0.450707,0.136426,-0.058339,-0.301442,0.050781,-0.000812,-0.208374,-0.033687,0.283322,-0.085066,0.306173,-0.595028,-0.060906,-0.199115,0.148412,0.021883,-0.022105,0.849442,-0.794605,-0.142077,-0.698185,0.233094,-0.266709,0.128467,-0.234185,0.284610,0.192624,0.134411,-0.254472,0.200203,-0.432338,0.166658,-0.446905,-0.574836,0.374745,0.010785,-0.038805,-0.355137,0.481591,-0.060636,0.073625,0.176601,-0.391631,0.288096,0.259893,0.139479,0.212551,-0.078658,0.320252,-0.283427,0.115273,0.648701,0.264861,-0.125362,0.186073,0.008059,-0.232011,-0.283495,0.094481,0.037715,-0.121794,0.589640,-0.233833,-0.245264,0.250799,-0.914428,0.368237,-0.400109,-0.109276,-0.031038,-0.263119,-0.080381,-0.577633,0.308209,-0.161228,-0.207267,0.351850,0.110612,-0.300258,0.794162,-0.799459,0.268372,0.740467,0.357678,0.184771,0.669172,-0.401598,-0.105658,-0.157084,-0.030758,-0.256679,0.124646,0.109832,0.265624,0.260979,-0.022327,0.073377,-0.403995,0.315521', '1457926', '26290398', '1458910', '1438591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3024983', '地下理想国', '剧情', '在并不遥远的2024年，人类社会危机重重。地球能源日渐枯竭，世界经济开始崩溃。Trexx集团将地铁连接成巨大的网络，名之为Metro。在这个网络具象化的世界里，人们躲在地下，如同工蚁一般奔忙劳碌，无欲无求。罗格（文森特·加洛 Vincent Gallo 配音）是一名电话接待员，与其他人相比，他似乎显得过于孤僻。在人们都习惯了地铁生活之时，只有罗格每天骑着单车上下班，穿梭于充满污染和破败的城市街头，孤独无助。直到某天早晨，罗格的自行车被人毁坏，他不得不乘坐地铁上班。一段奇妙的经历就此展开……本片荣获2009年斯德哥尔摩电影节最佳音乐奖、2009年威尼斯电影节未来数字电影奖。©豆瓣', '文森特·加洛', '塔里克·萨利赫', 7.1, 5745, 'tt0985058', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2165272417.jpg', 1, 5.6, 43.4, 39.2, 10.8, '-0.082151,0.211339,-0.797139,0.212613,0.128322,0.191275,0.682106,0.104082,-0.579387,-0.145262,0.144850,0.707924,-0.266421,0.287890,0.542113,-0.219970,-0.354321,-0.426923,0.042840,-0.145242,-0.068509,-0.328757,-0.188964,-0.435155,-0.218982,-0.510272,0.827319,0.425091,-0.082159,0.402315,-0.281439,0.032293,-0.266497,0.552841,-0.349411,-0.100885,0.035221,0.152775,-0.104558,-0.061409,-0.277822,-0.138514,-0.049492,-0.078910,0.076811,0.005835,0.618725,-0.217892,-0.286246,-0.195206,0.624315,-0.272170,-0.360096,-0.341911,0.461799,0.017457,0.046572,0.090513,0.006840,0.177276,0.022824,-0.233880,-0.363880,0.044951,-0.203269,0.116361,-0.373261,0.559470,-0.018872,-0.134054,-0.275096,-0.345373,0.217379,0.039079,0.237973,0.594206,0.061514,0.085299,-0.446812,0.377079,0.643476,0.278384,-0.743886,0.523994,-0.259993,-0.369715,-0.441883,-0.256853,-0.677101,-0.109136,0.183265,-0.150113,-0.373151,0.534654,-0.677447,0.374522,0.123463,-0.672348,0.042511,-0.114838,-0.461134,-0.872008,0.160020,-0.469297,0.049163,0.038920,-0.106149,-0.059982,0.568087,-0.777377,0.456414,0.559349,0.330114,-0.349769,0.917942,-0.283968,0.030132,-0.175398,0.050121,0.605420,-0.352207,0.579306,-0.087511,0.063718,-0.347021,0.229988,-0.535355,0.713405', '2159244', '2334814', '25785124', '1302050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30251948', '伊莉莎与玛瑟拉', '爱情', '故事开始于1898年西班牙西北部的一座名叫拉科鲁尼亚的城市之中。马赛拉（格蕾塔·费尔南德斯 Greta Fernández 饰）是修道院里新转来的学生，在这里，她认识了名为伊莉莎（娜特莉·德·莫利纳 Natalia de Molina 饰）的女孩。两个女孩之间很快就结下了深厚的友谊，并且这种友谊渐渐转化成为了懵懂的爱情。这段背德的感情在当时当然是不被允许的，为了拆散两人，马赛拉的父亲将女儿送进了另一所位于马德里的学校。一晃眼三年过去，此时的伊莉莎在一座小村庄里当老师，而马赛拉义无反顾的去那里找她，这对有情人终于再度走到了一起。可是，最终，她们的爱情还是抵不过世俗的非议，伊莉莎选择了离开，而马赛拉则和一个男人结婚了。©豆瓣', '纳塔利娅·德·莫利纳', '伊莎贝尔·科赛特', 8.4, 6949, 'tt6704898', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2552458804.jpg', 0.5, 1.7, 15.4, 42.7, 39.7, '0.538628,0.070093,-0.596337,0.571779,-0.113102,-0.396070,0.745580,0.066878,-0.477722,0.001194,-0.166805,0.942908,-0.167897,0.471972,0.377025,0.037953,-0.232913,-0.781076,-0.120223,-0.497943,-0.541344,-0.690491,-0.229464,-0.086538,-0.225501,-0.090682,0.793549,-0.044689,-0.032421,0.597537,0.426799,0.306061,-0.060914,0.263266,-0.348748,0.229314,0.058743,0.015166,-0.334093,0.317322,0.048923,-0.192479,-0.059929,0.016334,0.043447,0.310429,0.672076,-0.357279,0.217761,-0.150755,0.368941,-0.195267,-0.193857,0.099375,0.290903,-0.222141,0.240282,0.203663,-0.424871,-0.149602,0.152851,-0.378090,-0.340864,0.153557,0.131427,-0.013737,-0.630187,0.696388,0.162381,-0.283868,0.282819,-0.327730,0.121231,0.378637,0.071943,0.539304,-0.202147,-0.152318,-0.395697,-0.156594,0.750228,-0.046782,-0.076960,0.415867,-0.217694,-0.289388,-0.120624,-0.063404,-0.472615,-0.030148,0.247690,0.097685,0.023989,0.247289,-0.705625,-0.053826,-0.322390,0.021107,0.303960,-0.658865,-0.064514,-0.326555,-0.184034,-0.466531,-0.165619,0.145641,-0.110032,0.047518,0.677880,-0.865245,0.158144,0.522364,0.412879,-0.397475,0.831890,0.050176,0.372814,-0.056443,0.178507,0.334005,-0.090207,0.336037,0.229860,0.549249,-0.051262,0.024967,-0.394680,0.490793', '1292219', '35048413', '30162520', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30252334', '爱情是什么', '剧情', '山田光子（岸井雪乃 饰）是一名28岁的职场白领，在朋友的婚礼上，手足无措的她邂逅了名叫守（成田凌 饰）的男子，温柔风趣的守巧妙的化解了光子的尴尬和不适，一下子就俘获了光子的心。之后，守经常约光子出来吃饭玩耍，某一天，光子留宿在了守的家里，两人发生了关系。光子开始越来越频繁的住在守家中，虽然没有告白，但是两人之间的相处就好像在交往一样，渐渐的，光子开始将自己的身份当成了守的女友。可是，对于守来说，光子只不过是一个召之即来挥之即去的消遣而已。为了守，光子甚至辞掉了工作，一心一意的想要和守结婚做家庭主妇，就在光子的算盘打得哗哗响的时候，守突然失联了。©豆瓣', '岸井雪乃', '今泉力哉', 7.2, 12419, 'tt9163346', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2536769554.jpg', 0.9, 4.8, 40, 42.4, 12, '0.494529,-0.321809,-0.933913,0.256334,-0.230175,-0.223814,0.816248,0.399603,-0.289799,-0.305811,0.209976,0.232521,-0.362902,0.392568,0.305817,-0.348494,-0.239293,-0.831085,-0.216580,-0.056629,-0.277499,-0.318954,0.021669,-0.175986,-0.281603,-0.318237,0.292811,-0.288569,0.093710,0.343263,0.131491,0.274425,-0.145097,0.536587,-0.383360,-0.254009,-0.074929,0.066414,-0.028979,0.321950,-0.136962,-0.291564,0.195515,-0.128844,0.365449,0.482239,0.434947,-0.165262,-0.161821,0.327428,-0.017418,-0.119836,-0.231586,0.098198,0.247118,0.010536,0.078710,-0.272812,-0.577938,0.153355,0.019650,-0.201506,-0.645295,0.140929,0.141261,0.191845,-0.743020,0.655756,-0.015659,-0.242579,0.149305,-0.370919,0.385982,0.435240,-0.016386,0.561643,-0.177266,0.384295,-0.268697,0.097899,0.757778,-0.056364,-0.322241,0.629636,0.097184,0.069277,-0.088201,0.138281,-0.619961,-0.366090,-0.140769,-0.155320,-0.045982,-0.009122,-0.523420,-0.035071,0.045166,-0.005594,0.345249,-0.437155,-0.038662,-0.596304,-0.088870,-0.652499,-0.260277,0.515420,0.126759,-0.120577,0.812910,-0.997068,0.161620,0.416706,0.275850,-0.433414,0.645524,0.349297,0.079379,0.140229,0.208900,-0.127486,0.093493,0.401308,0.168682,0.453131,0.001305,0.025738,-0.450064,0.205549', '1308755', '26354526', '1301022', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30252495', '1917', '剧情', '1917年，第一次世界大战进入最激烈之际，两个年仅16岁的英国士兵接到的命令，需立即赶往死亡前线，向那里的将军传达一个“立刻停止进攻”讯息。 时间只有八小时，武器弹药有限，无人知晓前方敌况：死亡寂静之地、布满尸体的铁丝网、突如其来的敌军、随时毙命的危险境况…… 这一次两 个少年为救1600个人的性命，不完成，毋宁死！', '乔治·麦凯', '萨姆·门德斯', 8.5, 483682, 'tt8579674', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2587146023.jpg', 0.2, 0.8, 11.6, 50.1, 37.3, '0.069195,0.104336,-0.798265,0.621459,0.116638,-0.019057,0.770604,-0.520391,-0.183763,-0.546998,0.435062,0.446655,0.183478,-0.059531,0.461381,-0.431681,-0.109508,-0.529743,-0.502450,-0.010014,-0.734123,-0.040244,0.009667,-0.261986,-0.170839,-0.403730,0.807979,0.532421,0.190523,0.635231,-0.089096,0.230951,-0.051976,0.409729,0.055802,-0.314331,0.156097,-0.641415,-0.228306,0.656105,-0.132438,-0.159295,-0.171330,0.027389,-0.351842,0.462841,0.715221,-0.408861,-0.283863,-0.214804,0.413316,-0.337233,-0.036712,0.079046,0.383223,-0.181547,0.007001,-0.036197,-0.352721,0.318719,-0.319365,-0.081790,-0.678092,-0.097501,-0.293326,0.198758,-0.191633,0.045088,-0.348477,0.111822,0.042319,-0.402730,0.069274,0.694000,-0.129320,0.223835,-0.717871,-0.031044,-0.383757,-0.337824,0.938165,-0.250317,-0.349438,-0.156811,0.008767,-0.395029,0.382777,-0.168234,-0.030321,0.149809,0.269205,0.201772,-0.000615,0.038783,-0.406567,0.195167,-0.388577,-0.580996,-0.059407,-0.223516,-0.723706,-0.610953,0.082816,0.108143,-0.239134,0.516495,0.101052,0.293438,0.670099,-0.110291,0.101582,0.198214,0.234483,-0.205762,0.458407,-0.018096,0.279490,-0.211268,0.522597,0.121485,0.321707,0.445639,0.210720,-0.115639,-0.330473,-0.186329,-0.479890,0.185478', '26342391', '3011051', '1473795', '3606973');
