INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3025375', '奇异博士', '动作', '斯特兰奇博士（本尼迪克特·康伯巴奇 Benedict Cumberbatch 饰）是一名外科手术医生，他拥有着高超的智商和精湛的技艺，是医院乃至整个医学界的传奇人物。某一日，斯特兰奇博士遭遇了一场可怕的车祸，尽管保住了双手，但这双手伤痕累累不住颤抖，这也就意味着，他再也不能拿起手术刀，站在无影灯下了。斯特兰奇博士的生活就此失去了意义陷入了绝望之中，他决定远赴尼泊尔，寻找传说中能够治愈他双手的神秘力量。在尼泊尔，风尘仆仆的斯特兰奇博士拜入了神秘的古一法师（蒂尔达·斯文顿 Tilda Swinton 饰）门下，成为了其弟子，与此同时，古一法师曾经的弟子卡西利亚斯（麦斯·米科尔森 饰）亦在虎视眈眈，企图完成他获得永生的大业。©豆瓣', '本尼迪克特·康伯巴奇', '斯科特·德瑞克森', 7.6, 553636, 'tt1211837', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2388501883.jpg', 0.5, 3.2, 29.8, 47.4, 19.1, '0.305959,-0.037411,-0.401889,0.494126,0.016444,-0.424836,0.516409,0.168349,-0.409976,-0.405050,0.406118,0.854250,-0.048500,0.111800,0.144209,0.391467,-0.233616,-0.897732,-0.058285,-0.196628,-0.199535,-0.454956,-0.304676,-0.142206,-0.082257,-0.719762,0.389576,0.111059,-0.174362,0.504951,0.063509,0.564560,0.165626,0.297992,-0.327453,0.013301,0.271010,-0.346384,-0.062781,0.346144,0.198856,-0.131229,0.050832,0.187502,-0.014728,0.073927,0.452584,-0.408720,-0.064701,-0.096039,0.088746,-0.293643,-0.157075,0.150087,0.143486,-0.009378,0.065443,0.138529,-0.168451,0.016275,0.295315,-0.146095,-0.838076,-0.081099,0.099672,0.304804,-0.681486,0.591087,-0.424362,-0.100150,-0.102692,-0.283208,-0.005491,0.222134,0.096109,0.291190,-0.011496,-0.133669,-0.512495,0.066533,0.452713,-0.080769,-0.355359,0.077145,-0.220437,-0.567989,-0.198611,-0.195492,-0.282456,-0.101906,0.510361,0.047476,0.183515,0.504037,-0.381875,0.182923,-0.549038,0.025890,-0.330841,-0.022173,-0.202157,-0.334984,-0.044837,-0.110457,-0.238397,-0.113430,-0.074241,-0.446284,0.666132,-0.624010,0.290142,0.354019,0.368572,0.185895,0.577824,-0.214234,0.270802,-0.053029,-0.432399,0.480026,-0.079517,0.595697,0.434530,0.400243,0.045052,-0.096715,-0.337653,0.388172', '1309069', '1793491', '1303034', '3006892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3025447', '金蝉脱壳', '动作', '孔武冷峻的雷·布雷斯林（西尔维斯特·史泰龙 Sylvester Stallone 饰）经过周密计划，成功从戒备甚严的监狱中逃脱。他隶属于独立的BC安保公司，该公司受联邦监狱局之托测试国家各地监狱的安全性，通过布雷斯林这些越狱高手查找监狱的漏洞，以确保不会有犯人从牢笼中逃 脱。在过去八年里，雷已成功征服14座监狱。这一次，中情局为验证关押了罪大恶极恐怖分子的设施的安全，委托正准备退休的雷进入神秘莫测的国际监禁中心。但此次行动似乎出了什么差错，雷与团队失去联系，冷酷无情的典狱官霍布斯（詹姆斯·卡维泽 Jim Caviezel 饰）也完全无视他的撤离申请，更有凶残的狱卒（维尼·琼斯 Vinnie Jones 饰）热衷草菅人命。孤立无援的雷，只能在囚徒埃米尔（阿诺·施瓦辛格 Arnold Schwarzenegger 饰）的帮助下寻找逃脱的一线生机……©豆瓣', '西尔维斯特·史泰龙', '米凯尔·哈弗斯特罗姆', 7.8, 238889, 'tt1211956', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2155236151.jpg', 0.2, 1.8, 26.7, 51.6, 19.7, '0.104508,0.136066,-0.567668,0.438756,-0.095585,-0.071009,0.546400,-0.024979,-0.435559,-0.225009,0.167876,0.295383,-0.002341,0.176183,0.175939,-0.153785,-0.401907,-0.478658,-0.326014,-0.265469,-0.582772,-0.620926,-0.284209,-0.547163,0.073062,-0.372426,0.650064,0.439721,-0.398139,-0.113190,0.421436,0.314959,-0.160450,0.385409,-0.005137,-0.277183,0.100477,-0.179402,-0.228370,0.207039,-0.019775,-0.062273,-0.185829,0.060139,0.575543,0.547662,0.388684,-0.217830,-0.229570,-0.082251,0.535818,-0.329473,-0.070018,-0.034797,0.284518,-0.055941,-0.299012,0.244525,-0.097061,0.188066,0.043868,-0.245015,-0.913858,-0.220626,0.191560,-0.009750,-0.493726,0.096681,-0.117096,0.254575,-0.099830,-0.080536,0.044184,0.524588,0.121478,0.118246,-0.003972,0.206973,-0.654139,0.121486,0.410136,-0.200873,-0.311907,-0.318440,-0.175815,-0.666785,-0.155398,-0.206410,-0.115812,-0.216492,0.466344,-0.125456,-0.035472,0.038729,-0.298008,-0.324520,-0.436469,-0.132838,-0.257426,-0.352960,-0.012882,-0.853963,0.110488,-0.097363,-0.143470,0.282839,0.075802,-0.222545,0.216266,-0.703212,0.111383,0.447978,0.271626,-0.551248,0.469847,-0.170012,0.183719,-0.317196,-0.049668,0.352584,0.609126,0.606897,0.249787,0.348625,0.025802,-0.210374,-0.322910,0.199900'