INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3025450', '纯情漫画', '爱情', '《纯情漫画》改编自人气网络漫画家姜草的同名作品。30岁的公司职员金延寿（刘智泰 饰）每天上班乘地铁时总会遇见和自己抢位置的女高中生秀颖（李妍熙 饰），两人慢慢开始留意对方。一次秀颖上学时忘记系领带，便向延寿临时借了领带，两人的心因此慢慢地靠近。而因为进修同样的课程，24岁的孰（金英云 饰）喜欢上了比自己年长5岁的夏京（蔡贞安 饰），面对孰的爱情告白，有着悲伤爱情回忆的夏京婉拒了，在孰的努力下，夏京开始慢慢敞开心扉。然而因为年龄的差距，秀颖的母亲介入了这段恋情，而孰也因为夏京放不开原来的恋情而感到受伤。两段恋情都陷入了危机之中……那么这两段两段纯情之恋是否能在这个夏末秋初的午后继续上演呢？©豆瓣', '刘智泰', '柳彰河', 7.3, 11931, 'tt1210837', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p724998046.jpg', 0.5, 4.4, 40.3, 38.1, 16.7, '0.507832,0.088873,-0.568207,0.342643,0.154941,-0.291896,0.429011,0.367154,-0.304751,-0.169558,0.095339,0.549646,-0.265296,0.426939,0.163820,-0.319165,-0.221289,-0.831712,0.185405,-0.202143,-0.314988,-0.140513,-0.182784,0.264303,-0.065860,-0.199735,0.820252,0.106602,-0.149166,0.602709,0.336227,0.107752,0.209763,0.267980,-0.150419,-0.140191,-0.013725,0.303185,-0.195021,0.006930,0.039391,-0.359836,-0.101106,0.013448,-0.105101,0.348599,0.863006,-0.040404,-0.222435,0.069848,0.781368,-0.140079,-0.099912,-0.010130,0.338495,0.279470,0.291546,0.052688,-0.053634,0.101074,0.023061,-0.133797,-0.575459,0.194222,0.025746,0.295880,-0.502609,0.276971,-0.142091,0.068738,0.089818,-0.166663,0.013869,0.385063,0.314838,0.286625,-0.392187,-0.220112,-0.221411,0.109287,0.530578,0.127208,-0.373238,0.615879,-0.130786,-0.264100,-0.179575,-0.074830,-0.529047,-0.096605,0.054233,0.032289,-0.116449,0.074580,-0.575739,0.038005,-0.003921,-0.011332,0.141120,-0.282101,-0.217007,-0.355145,-0.373182,-0.622406,-0.216406,-0.163142,0.249234,-0.407238,0.549320,-0.705800,0.073702,0.413490,0.417264,-0.422505,0.915447,0.153076,0.146089,-0.052503,-0.018307,0.326696,-0.383527,0.150190,-0.057450,0.458892,-0.123926,-0.066204,-0.587509,0.337393', '26759820', '5416009', '25880986', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30255079', '杀手寓言', '喜剧', '本作改编自南胜久的同名漫画《杀手寓言》，主演为冈田准一。「无论多强的敌人都可以在6秒内击杀他」的天才杀手“寓言”（冈田准一），被BOSS命令去大阪隐居一年，期间不可以杀害任何人。于是他化名为佐藤明，与伪装成自己妹妹的拍档佐藤洋子（木村文乃）移居大阪，在那里他第一次遇见了一般人女性·清水岬（山本美月），本该开始普通的日常生活，但是……', '冈田准一', '江口幹', 7.2, 13788, 'tt8676426', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2551329804.jpg', 0.9, 4.6, 40.5, 42.4, 11.6, '0.181370,-0.122966,-0.331378,0.478313,-0.348334,-0.229319,0.350438,0.145763,-0.397064,-0.614334,0.357940,0.892050,0.124250,-0.021179,0.176751,0.282742,-0.333801,-0.458503,-0.131737,-0.366746,-0.118941,-0.447736,-0.125515,-0.487770,-0.187652,-0.118025,0.806978,0.183500,-0.176360,0.167183,0.240906,0.419159,-0.049805,0.126109,0.041012,0.119391,0.080936,-0.190089,-0.087596,0.646680,-0.430466,-0.294143,-0.154596,0.372392,0.066328,0.210853,0.524732,-0.054094,-0.001866,-0.404621,0.062116,-0.244245,-0.233226,0.268807,0.563894,-0.351257,0.356145,0.299151,-0.082327,0.063188,-0.240361,-0.036001,-0.610635,-0.031680,0.139318,0.248161,-0.309659,0.542942,-0.274655,-0.048420,0.435215,-0.198319,-0.170522,0.091619,0.390580,-0.103601,-0.459499,-0.075560,-0.331609,0.364327,0.896565,0.052711,0.135892,0.130052,0.071417,-0.561130,-0.355032,-0.431221,-0.254810,0.126718,-0.035864,0.109056,-0.435299,0.296422,-0.312329,-0.223105,-0.004991,0.227855,0.013110,-0.289036,-0.076748,-0.764783,0.239834,-0.408575,-0.136010,-0.008004,0.345808,-0.304670,1.049133,-1.054310,-0.020383,0.522738,0.219314,-0.111317,0.521074,0.187280,-0.286154,-0.039168,0.110526,0.104325,0.530536,0.544984,0.155767,0.284955,-0.045764,-0.092507,-0.267626,0.197684', '2369613', '3811356', '1826173', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30256006', '再见，嘴唇', '音乐', '在地下音乐界有点知名度的女生乐团两人组合“ハルレオ(harureo)”。Haru（門脇麦饰）和Reo（小松菜奈饰）两人为了各自发展，而决定解散。他们找来外援志摩（成田凌饰）一起做全国巡演。但是在路上Reo喜欢上志摩，志摩却喜欢上Haru。而其实Haru对Reo有着友情以上的感觉…。', '小松菜奈', '盐田明彦', 7.2, 8978, 'tt9827784', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2547307760.jpg', 0.7, 6.3, 40.3, 38.1, 14.7, '0.449544,-0.163418,-0.662318,0.580428,0.417159,-0.101221,0.401171,0.233784,-0.549739,-0.235343,-0.276913,1.120858,-0.331074,0.326111,0.157301,-0.160263,-0.423274,-0.939130,0.056310,-0.399751,-0.276063,-0.640793,0.118343,-0.062690,-0.593358,0.251210,0.758249,0.188805,-0.180632,0.723429,0.684784,0.193529,-0.154038,0.463132,0.115464,-0.693115,0.010320,0.043487,-0.476777,0.478876,-0.071117,-0.022928,-0.093612,-0.130766,0.331248,0.106893,0.460074,-0.062142,-0.002075,0.041965,0.057178,-0.174431,-0.041518,-0.033958,0.294650,0.264782,0.407484,-0.097062,-0.045558,-0.272603,0.076030,-0.377962,-0.605336,0.234902,0.251929,0.202115,-0.343070,0.531912,0.153342,-0.040245,0.140264,-0.576088,0.296604,0.322372,0.538699,0.191943,-0.296258,0.196393,-0.310629,-0.374252,0.940710,0.162449,0.144540,0.186149,-0.246814,-0.275153,-0.328364,-0.232680,-0.175599,-0.115024,-0.510510,0.049189,0.173230,-0.312749,-0.596426,0.291236,0.154557,-0.250689,-0.002792,-0.473101,0.401069,-0.680998,-0.110075,-0.653686,-0.364759,0.222723,0.315199,-0.394516,0.999706,-1.142488,-0.007142,0.649632,0.632223,-0.387584,0.900964,0.193391,-0.003565,-0.413872,-0.243481,-0.203059,-0.357282,-0.051050,0.200193,0.212063,-0.084124,-0.157821,-0.345239,0.155341', '35048413', '1292219', '35030151', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3025666', '后备计划', '喜剧', '多年寻觅真爱不获，大龄女青年佐伊（詹妮弗·洛佩兹 Jennifer Lopez 饰）决定通过生个孩子改变自己的生活。就在她人工受孕的当天，在大街上遭遇“抢车男”斯坦（埃里克斯·奥洛林 Alex O''Loughlin 饰）。斯坦的风趣和浪漫似乎契合了佐伊对于另一半的所有幻想，可是不幸的是通过人工受孕，佐伊真的怀孕了。遭遇真爱之时，受孕成功的消息无疑成为一颗定时炸弹，佐伊不知道面前的这个男人能否接受这件事情。满怀忐忑的佐伊告诉了斯坦自己怀孕的事情，幸运的是斯坦最终选择了继续和她在一起。不过，对于即将到来的新生命，斯坦的内心依旧充满不安……©豆瓣', '艾历克斯·奥洛林', '艾伦·保尔', 6.2, 20118, 'tt1212436', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p475211554.jpg', 2, 13.2, 59.6, 21.3, 3.9, '0.171704,0.030656,-0.723584,0.288091,-0.148829,-0.457329,0.582158,-0.145611,-0.339095,-0.214195,0.014672,0.613467,-0.277614,0.153461,0.380196,0.243207,-0.496597,-0.437823,-0.017046,0.061170,-0.340418,-0.681280,-0.071353,-0.249218,-0.082760,-0.318250,0.879497,0.044997,-0.237660,0.302331,0.512483,0.780998,0.236662,0.385707,-0.002276,0.013451,0.201446,-0.098650,-0.235283,0.300924,0.261763,0.063191,0.176721,0.413501,0.212655,0.375059,0.550714,-0.311174,-0.231619,0.276887,0.364800,-0.113425,0.071401,0.079964,-0.080438,-0.174683,0.014649,0.101601,-0.299137,-0.570100,0.185327,-0.066891,-0.622566,-0.287696,0.277957,0.320175,-0.338313,0.135485,0.012337,0.025160,0.333241,-0.393358,0.163983,0.541361,0.487390,0.356476,-0.155728,-0.051116,-0.449267,-0.110838,0.845176,0.305021,-0.268037,0.272999,-0.335324,-0.393269,-0.054750,-0.060360,-0.696486,0.266923,0.216128,0.180913,-0.186778,0.621201,-0.128042,-0.139746,-0.407395,-0.110828,0.272010,-0.311125,0.061679,-0.352763,0.014931,-0.285631,-0.697186,0.025428,0.075121,-0.431408,0.692853,-1.026122,0.532480,0.594408,0.302419,-0.316777,0.615530,0.265477,0.099127,-0.469687,0.094594,0.483829,-0.162354,-0.059886,0.192503,0.268243,0.015147,-0.122273,-0.515844,0.613912', '1308836', '35030151', '10511636', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3025669', '迷失Z城', '剧情', '英国探险家珀西·福斯特（查理·汉纳姆 Charlie Hunnam 饰）深入神秘的南美洲亚马逊丛林探险，竟发现未知的文明生活迹象，他回到英国公开这个意义深远的重大发现，却被当成笑话嘲弄，没有人愿意相信他的话。在爱妻尼娜（西耶娜·米勒 Sienna Miller 饰）无怨无悔的支持下，福斯特决心带领儿子杰克（汤姆·霍兰德 Tom Holland 饰）重返亚马逊丛林，寻找古文明存在的证据，一行人却离奇消失，从此再无任何音讯，成为史上最神秘又悬疑的失踪事件。', '查理·汉纳姆', '詹姆斯·格雷', 6.9, 23122, 'tt1212428', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2460384566.jpg', 1.3, 7.4, 43.5, 38.5, 9.3, '0.090690,0.092188,-0.971239,0.511022,0.059250,-0.051166,0.769021,-0.198645,-0.828378,-0.247342,0.134564,0.651672,0.056577,-0.090908,-0.007143,0.050791,-0.558613,-0.425947,0.308153,-0.175548,-0.219523,-0.412853,-0.317729,-0.376423,0.100696,-0.339511,0.669021,0.247466,-0.616209,0.477091,0.070098,0.426149,-0.276640,0.531755,-0.144836,0.277507,0.517014,0.097173,-0.629140,0.316074,-0.300909,0.115605,-0.199652,0.354323,-0.225055,0.301962,0.352427,-0.381372,-0.253224,0.023564,0.459999,-0.445208,-0.199437,0.076542,0.224838,-0.067555,-0.176103,0.458029,0.183054,-0.072234,0.122553,0.033081,-0.645221,0.096397,-0.019536,0.812917,-0.314160,0.208947,-0.264700,-0.160278,-0.141359,-0.305175,0.383987,-0.118876,0.372715,0.035553,0.220868,0.410502,-0.334443,0.079148,0.483841,-0.378592,-0.437395,0.254071,-0.031751,-0.591860,0.110713,-0.174089,-0.327263,0.056679,0.286718,0.194772,-0.234724,0.447593,-0.499730,0.071648,-0.374438,-0.368252,-0.021297,-0.223906,-0.005660,-0.612451,-0.077377,-0.236207,-0.500077,0.229787,-0.087113,-0.321496,0.309649,-0.497288,0.623901,0.610158,0.362748,-0.628578,0.614822,0.092586,0.072967,-0.323218,0.065901,1.066046,0.209977,-0.012026,-0.300735,-0.282645,0.183092,-0.213181,-0.264036,0.247650', '1300945', '22637441', '10487568', '26586806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3025673', '从今以后', '剧情', '《从今以后》被选为2010年年纽约国际电影节的闭幕电影。故事的地点分别发生在美国、英国和法国。美国，蓝领乔治（马特·达蒙 Matt Damon 饰）可以和死人说话。他的超能力，一度让他成为全美宠儿。精明的哥哥准备把他打造为全方位娱乐红人。然而他放弃了一切在建筑工地上 工作。法国，记者玛丽（西西·迪·法兰丝 Cécile De France 饰）是2004年印度洋海啸中的生还者。那次经历之后，她似乎拥有了通灵能力。英国，学生马库斯刚失去了双胞胎兄弟杰森，他正在绝望地想要寻找答案。与死亡擦肩的神秘、对未知世界的迷茫、痛失至亲的悲伤、寻找答案的迫切，在冥冥中将这三个本来毫无关系的人连在了一起，进而颠覆了他们未来的一切……©豆瓣', '马特·达蒙', '克林特·伊斯特伍德', 7.2, 25431, 'tt1212419', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p729136753.jpg', 0.7, 5, 41.3, 41.1, 11.8, '0.093213,0.101090,-0.806974,0.478280,0.168155,-0.291955,0.479157,-0.082735,-0.682598,-0.148216,-0.254061,0.850560,-0.246773,0.348737,0.278373,0.192374,-0.403358,-0.952630,-0.221990,-0.232466,-0.238557,-0.546659,-0.300059,-0.532268,-0.031867,-0.353692,0.611772,0.235920,0.083664,0.407165,0.270900,0.234772,0.076974,0.502605,-0.081626,-0.035792,0.216128,-0.046141,-0.565066,0.198082,0.088501,-0.128287,-0.155943,0.332088,0.031446,0.231821,0.546580,-0.236492,0.211841,-0.226322,0.228898,-0.384936,-0.016344,0.106537,0.152287,0.062723,-0.043625,0.403417,-0.106663,-0.257572,0.193015,-0.057073,-0.750616,0.015515,0.037191,0.248644,-0.430393,0.518798,-0.120690,0.217357,0.148548,-0.310895,0.417792,0.280583,0.300510,0.302837,0.013629,-0.019103,-0.410669,0.342543,0.997314,-0.011447,-0.128865,0.238651,-0.219558,-0.384910,-0.384875,-0.236955,-0.430069,0.183772,0.349056,0.194919,-0.244525,0.383577,-0.636102,-0.091661,-0.122051,-0.294033,-0.101098,-0.463579,-0.037009,-0.607997,-0.216020,-0.396646,-0.343805,-0.074849,0.020750,-0.225261,0.831398,-0.823061,0.180236,0.700231,0.588997,-0.402252,0.848354,-0.071783,-0.035104,-0.438149,0.004316,0.414576,-0.238759,0.282306,0.134781,0.178605,-0.012300,0.199037,-0.366723,0.634200', '30162520', '25721544', '1870682', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30256796', '女王的柯基', '喜剧', '雷克斯作为女王的皇家首席狗狗，是一只在白金汉宫过着奢靡生活、备受宠爱的小柯基犬。一次意外让它流落伦敦街头，闯入流浪狗中心，他将如何自我救赎并重返皇宫？一场民间和皇家萌犬的冒险即将上演......', '鲁斯蒂·沙克尔福特', '文森特·凯斯特鲁特', 5.8, 22501, 'tt6563576', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2566480237.jpg', 3.8, 24.6, 55.4, 12.2, 3.9, '-0.172677,0.548490,-0.671718,0.689690,0.111593,0.078810,0.781498,0.051717,-0.720850,-0.050495,0.556770,0.937031,-0.096671,0.637580,0.049621,0.257452,-0.062152,-0.287894,-0.248160,-0.033954,0.079929,-0.012755,-0.328515,-0.077715,-0.204284,-0.372123,0.783474,0.004454,-0.399361,0.424816,0.523332,0.128469,-0.270768,0.302025,-0.405901,-0.450125,0.279053,0.490386,-0.227825,-0.049168,0.122261,-0.516445,-0.270901,0.292173,0.203482,-0.212217,0.734325,-0.944297,0.076220,-0.681883,0.603318,-0.255759,-0.034808,0.357753,0.213096,-0.109179,-0.055196,0.147743,0.094851,0.321885,0.079300,-0.254577,-0.649102,-0.252289,-0.260861,0.171109,-0.649325,0.743126,0.065114,-0.303174,0.242793,-0.281156,0.290165,0.279051,0.282415,0.351642,-0.264908,0.315306,-0.359745,0.276288,1.204546,-0.059771,-0.322376,0.000256,-0.208930,-0.738127,0.379368,-0.548918,-0.778850,-0.045100,0.279313,-0.223597,-0.070807,0.583715,-0.619184,0.266301,-0.786303,-0.439419,0.202630,-0.444337,0.043057,-0.722297,0.310123,-0.342280,-0.248544,-0.066761,0.335255,-0.376805,0.316309,-0.813353,0.504366,0.897822,0.360292,-0.502347,0.504876,0.083326,0.506632,-0.041142,-0.380028,0.543950,0.278366,0.533589,-0.021598,-0.007261,-0.101717,-0.045928,-0.502211,0.629835', '25721544', '1307311', '25828589', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30257175', '燃烧女子的肖像', '剧情', '1760年法国布列塔尼，才华洋溢的年轻女画家玛莉安（诺米·梅兰特饰）收到委托，需要在对方不知情的状况下，完成富家小姐艾洛伊兹（阿黛拉·哈内尔饰）出嫁前的肖像画。两人在孤岛相依为命，白天女画家悄悄观察小姐的一举一动，到了晚上才纵情下笔。两人在画与被画的亲密接触下，即便是在充满礼教束缚的时代，却也渐渐萌发了禁忌的暧昧情愫，随着大婚之日越来越近，她们的爱火却越烧越猛烈…', '诺米·梅兰特', '瑟琳·席安玛', 8.7, 180607, 'tt8613070', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2584308261.jpg', 0.2, 0.9, 11.4, 40.1, 47.4, '0.448231,-0.006329,-0.933617,0.328852,0.384899,-0.382450,0.747651,0.036987,-0.259433,-0.263386,0.170716,0.391154,-0.798879,0.324323,0.389200,-0.112774,-0.360524,-0.756498,0.090335,-0.204010,-0.165380,-0.366624,-0.180545,-0.006929,-0.157165,-0.443494,0.336115,0.220740,-0.026054,0.299439,0.065497,0.323053,-0.290234,0.520331,-0.392041,-0.145638,0.158037,-0.060451,-0.265861,0.130469,0.134199,-0.319005,-0.189908,-0.093610,0.121925,0.227710,0.619066,-0.536832,-0.142275,0.036555,0.483228,0.146153,0.130255,0.052354,0.394098,-0.115956,-0.064594,0.113707,-0.422558,-0.002326,-0.167321,-0.186070,-0.058280,0.259137,0.336508,0.317370,-0.706392,0.530770,-0.047324,-0.166370,0.107881,-0.510404,0.084746,0.225756,-0.096209,0.459537,0.053617,0.102464,-0.517084,-0.139387,0.358172,0.437504,-0.277107,0.454616,-0.234542,-0.374190,-0.078184,-0.219084,-0.280219,-0.156793,0.396185,0.189243,0.134049,0.389282,-0.504143,-0.304884,-0.154890,0.007925,0.172712,-0.460991,-0.121769,-0.642757,-0.314962,-0.613761,-0.396511,0.301127,0.254788,-0.194676,0.561249,-0.747492,0.573040,0.517505,0.237659,-0.082151,0.338944,0.257178,-0.055370,-0.063469,-0.237906,0.259578,0.004544,0.282217,0.330702,0.513367,-0.156936,0.156141,-0.346585,0.709103', '21348112', '1292211', '20515070', '6827727');
