INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30257608', '净化之时', '恐怖', '网路新时代下，德鲁与马克斯开设网路驱魔直播平台，邀请神父对被附身者进行驱灵，全球观赏人数超过千万，但幕后竟是为求成名的装神弄鬼。但没想到，某次直播招来真正恶灵，班门弄斧的假神父惨遭攻击，然而点阅率竟创新高，直播该立即中止还是血溅全网。', '瑞安·古兹曼', '达米安·莱韦克', 6.9, 13297, 'tt8009906', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2601811430.jpg', 1.8, 8.7, 42.9, 35.7, 10.9, '-0.038520,0.261185,-0.299590,0.034996,0.277619,0.429454,0.113904,-0.383164,-0.202617,-0.108555,0.265415,0.585859,-0.649006,-0.024818,0.114270,-0.372462,-0.113852,-0.392575,0.172940,-0.285930,0.013205,-0.228582,-0.279840,0.066284,-0.372108,-0.219351,0.452724,0.044377,-0.429564,0.001576,0.299999,0.223664,-0.127524,0.188156,0.121288,-0.473914,0.161278,-0.423624,-0.121084,0.521777,-0.156454,-0.270284,0.006818,0.063992,0.018238,0.150078,0.266151,-0.339870,-0.233866,-0.093555,0.607993,-0.340052,0.079821,0.269285,0.436220,0.240942,0.325223,0.051161,0.286658,0.111489,-0.192933,-0.044100,-0.684489,0.182333,0.223603,-0.163204,-0.187710,0.055908,-0.241693,0.047514,-0.294527,0.072132,-0.110203,0.187897,0.935205,0.028631,0.092802,-0.253302,-0.116038,-0.096470,0.117890,0.172886,-0.580179,0.032044,0.349515,-0.378712,0.161102,-0.463495,-0.184673,0.103890,-0.075228,0.100695,0.359300,0.088494,-0.581698,-0.104365,-0.261276,-0.260602,-0.261855,-0.133330,-0.500377,-1.015543,-0.029838,0.178870,0.000916,-0.040906,0.375050,-0.561410,0.626840,-0.782467,0.285109,0.489031,0.509300,-0.439389,0.520479,0.169873,0.032237,0.017367,-0.357355,-0.070876,0.333815,0.339876,-0.177721,-0.344801,-0.002860,-0.595138,-0.064256,0.149366', '3003137', '26275494', '3318306', '2369613');
