INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30257991', '六欲天', '剧情', '因女友自杀而患上抑郁症的警察阿斌（祖峰 饰）和搭档磊哥（陈明昊 饰）在调查一起碎尸案中，与被害者的姐姐李雪（黄璐 饰）相识。李雪自称梦见弟弟被人杀害。在调查过程中，阿斌发现李雪痛失女儿并患上抑郁症的悲惨经历，两人彼此怜悯，相互理解。 这时，在城市漂泊的少女婷婷（张倩如 饰）也渐渐走入阿斌（祖峰 饰）的生活，和他产生说不清的牵绊。孤独的少女、备受抑郁症折磨的患者，他们都该如何面对自己的内心，又该如何在这个世界寻找光明……', '祖峰', '祖峰', 5.6, 6622, 'tt10199668', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2633493571.jpg', 4.1, 31.8, 45.6, 15.2, 3.3, '-0.010893,-0.324005,-0.600640,0.238728,-0.145526,-0.178220,1.030188,0.148920,-0.690302,-0.229647,0.473930,0.586617,-0.048360,0.451837,0.383947,-0.039987,-0.231837,-0.701252,0.334561,-0.060586,-0.334936,-0.352524,-0.150557,-0.150024,0.001997,-0.257917,0.667232,-0.112256,0.032042,0.429633,0.222795,0.555183,-0.539962,0.512544,0.058172,0.233731,0.023229,0.269926,-0.473110,-0.044316,0.282619,-0.234958,0.009290,-0.006717,-0.326046,0.261083,0.824665,-0.142029,-0.244167,-0.301363,0.359841,-0.137501,-0.171858,0.130428,0.213484,-0.008423,0.314985,0.102793,-0.095142,-0.134795,0.071166,0.357738,-0.314790,0.081001,0.538588,0.409279,-0.441707,0.410350,0.051561,-0.159354,0.236758,-0.089783,0.230739,0.451176,0.322661,0.729659,-0.449476,-0.250949,-0.449912,0.289438,0.662471,0.079255,-0.003764,0.216855,-0.278175,-0.369874,-0.028538,-0.109874,-0.902613,0.080306,0.076536,0.033294,-0.556186,0.465095,-0.322111,0.019615,0.018501,0.152696,-0.044808,-0.523152,-0.008433,-0.394819,-0.328210,-0.461648,-0.392759,0.010473,0.008508,-0.306467,0.492462,-0.916191,0.376034,0.206291,0.412185,-0.614677,0.331091,0.255249,0.012766,-0.322463,-0.161273,0.683813,-0.115094,0.126353,-0.110075,-0.001459,-0.160801,0.417437,-0.472265,0.176431', '10574468', '4275444', '1308755', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3025809', '无法无天', '剧情', '20世纪三十年代的美国富兰克林，Bondurant家的三兄弟Forrest（汤姆·哈迪 Tom Hardy饰），Howard（杰森·克拉科 Jason Clarke饰）和 Jack（希亚·拉博夫 Shia LaBeouf饰）做私酒生意做得风生水起，在当地小有名气。然而当地真正的黑帮老大却是Floyd Banner（加里·奥德曼 Gary Oldman 饰）。Forrest的酒吧里新招了一名女服务生Maggie Beauford（杰西卡·查斯坦 Jessica Chastain 饰），而Jack则爱上了一个神父的女儿Bertha Minnix（米娅·华希科沃斯卡 Mia Wasikowska 饰）。Jack经常和他的好朋友Cricket Pate（戴恩·德哈恩 Dane DeHaan 饰）一起鼓捣一些新奇的东西，然而在他两个哥哥眼里他却始终是个不能真正参与到他们生意中的小孩。新上任的警官Charley Rakes（盖·皮尔斯 Guy Pearce 饰）看Bondurant三兄弟非常不顺眼，屡次挑起事端，三兄弟将如何面对挑战？', '汤姆·哈迪', '约翰·希尔寇特', 7.4, 25648, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1652810256.jpg', 0.6, 3.3, 37.5, 45.1, 13.5, '0.498523,-0.218803,-0.403377,0.535391,-0.147459,-0.528740,0.697731,0.227505,-0.419301,-0.371337,0.067929,0.735379,-0.028237,0.237417,0.275004,0.233121,-0.394768,-0.579507,0.134138,-0.294310,-0.035182,-0.401367,-0.562064,-0.112853,-0.276509,-0.087049,0.097363,-0.226502,0.308843,0.346235,0.447757,0.313587,0.132678,0.025486,-0.071057,-0.163539,0.331552,-0.068029,-0.219687,0.076437,-0.022704,-0.116714,-0.304944,0.191484,0.373639,0.438157,0.483034,-0.253695,0.264390,-0.303483,0.077158,0.107176,0.090530,0.000295,0.207654,-0.112249,0.283430,0.264735,-0.056804,-0.153269,0.166451,0.051568,-0.471023,0.231065,0.284379,0.295664,-0.697951,0.386333,-0.257227,-0.086173,-0.147842,-0.286285,0.050221,0.208855,0.156599,0.285030,-0.177399,0.038271,-0.668395,0.101821,0.572581,0.227367,0.060291,0.025762,-0.008234,-0.320704,-0.021273,-0.278350,-0.675618,-0.098721,0.216556,-0.269210,0.192146,0.113668,-0.696007,-0.000699,-0.209077,-0.129082,-0.009478,-0.168335,0.108503,-0.623318,0.042567,-0.477684,-0.334250,0.053304,0.233447,-0.018626,0.725195,-0.559299,-0.028646,0.341934,0.285715,-0.278191,0.620520,0.175626,0.221693,-0.308710,-0.397501,-0.256403,0.111056,-0.08