INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30259043', '跳舞吧！大象', '剧情', '热爱跳舞的13岁少女黎春夏不幸遭遇车祸，沉睡15年后竟奇迹般地苏醒，醒来后却发现生活发生了天翻地覆的变化，不仅丧失了十五年的生活常识，体重也飙升至200斤。但是为了完成在舞台上翩翩起舞的梦想，她与童年的三位同伴再次合体，巧遇灵魂舞者培训班创始人皮鲍十，一场华丽丽的魔鬼特训就此开启。', '艾伦', '林育贤', 5, 40189, 'tt10504110', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2562934437.jpg', 15.2, 35.8, 36.8, 9.6, 2.6, '-0.287425,0.247193,-0.493067,0.188770,-0.083202,-0.410493,0.750053,-0.134726,-0.336627,-0.600730,0.180751,0.486503,-0.617882,0.344583,0.718079,-0.351836,-0.063975,-0.882352,0.061503,0.170379,-0.608968,0.063306,0.026931,-0.005953,0.001968,-0.497631,0.818336,0.183769,-0.098437,0.627008,0.036952,0.009534,-0.099291,0.270757,-0.160433,-0.025083,-0.054346,0.420273,-0.121793,0.151149,-0.127299,-0.580765,0.085341,-0.063481,-0.123639,-0.102059,1.000565,-0.288575,-0.302082,-0.244146,0.600266,-0.225615,-0.225520,0.058933,0.530818,0.277119,-0.110126,-0.051265,0.102401,-0.170038,-0.256806,-0.384167,-0.422142,0.079931,-0.039537,-0.014950,-0.264619,0.396882,0.193469,0.290270,-0.176109,-0.120666,-0.157208,0.431627,0.455857,0.500977,-0.284071,0.136300,-0.477410,0.292192,0.975347,-0.087266,-0.760638,0.581769,-0.201000,-0.544337,-0.372748,-0.257393,-0.159635,0.185622,0.037242,0.414675,-0.109159,0.403449,-0.576907,-0.096600,-0.436865,-0.282512,-0.190353,-0.074788,-0.396633,-0.429115,-0.360025,-0.260118,-0.226918,0.152445,0.082725,-0.528665,0.514114,-0.799124,0.683027,0.388616,0.205165,-0.320375,0.546289,-0.271810,0.243675,-0.286687,0.022929,0.750448,-0.243873,0.164051,-0.139404,0.110066,-0.424585,0.312178,-0.737890,0.466302', '2365260', '1417036', '1773217', '3667102');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30259221', '去年圣诞', '喜剧', '凯特（艾米莉亚·克拉克 Emilia Clarke 饰）是一个非常平凡的女人，每天都过着浑浑噩噩的日子，她的个性和一连串错误的选择导致她如今只能在一家全年无休的商店里当店员。无家可归的凯特借住在朋友家里的沙发上，虽然凯特有一位很爱她的母亲阿黛拉（艾玛·汤普森 Emma Thompson 饰），但凯特却因为某些心结而拒绝回家和母亲同住。某日，一位名叫汤姆（亨利·戈尔丁 Henry Golding 饰）的男子出现在了凯特的面前，成为了照亮她前路的明灯，汤姆的出现让凯特开始意识到自己的人生或多或少出现了问题，在汤姆的帮助之下，她开始正视自己和母亲之间的矛盾，并且开始一步一步的纠正自己错位的人生。©豆瓣', '艾米莉亚·克拉克', '保罗·费格', 6.5, 7901, 'tt8623904', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2568501167.jpg', 2.4, 12.6, 51.4, 25.3, 8.3, '0.503612,0.118804,-0.691346,0.659350,-0.244480,-0.429789,1.006563,0.234474,-0.525605,-0.376910,0.324872,0.921731,-0.237218,0.634522,0.444980,0.164501,-0.210708,-0.752366,0.091386,-0.059380,-0.416338,-0.551192,-0.335132,-0.212352,-0.319268,-0.321948,0.567577,-0.014909,-0.067561,0.316629,0.276970,0.324019,0.175667,0.648604,-0.177750,0.092855,-0.009836,-0.152783,-0.152382,0.100353,0.149598,-0.250412,-0.075619,0.384852,0.040360,0.355342,0.648693,-0.305061,-0.185527,0.180706,0.415455,-0.202727,-0.066692,0.153903,0.367827,-0.097720,0.123956,0.151557,-0.184789,0.051295,0.137567,0.083177,-0.693420,0.019518,-0.028905,0.347271,-0.832001,0.405727,-0.100305,-0.126759,0.233084,-0.565892,0.018999,0.281295,0.111187,0.292945,-0.455140,-0.068471,-0.582766,-0.056798,0.654974,0.068407,-0.128894,0.528898,-0.417076,-0.347776,-0.292426,0.015585,-0.653884,-0.162950,0.052298,0.097652,-0.295143,0.284250,-0.561143,-0.052748,-0.137192,-0.261567,-0.042379,-0.524853,-0.163475,-0.468020,0.051390,-0.576306,-0.529827,0.057460,-0.156234,-0.427117,0.606522,-0.872680,0.235197,0.595439,0.235270,-0.218490,0.857061,0.189777,0.322339,-0.149705,-0.118408,0.422407,0.036277,0.094299,0.101289,0.283358,-0.034363,0.181538,-0.498020,0.782602', '3055049', '1309172', '4275444', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3026005', '现在和相爱的人在一起吗?', '剧情', '建筑公司理事英俊（李东健 饰）和在灯具店工作的小如（韩彩英 饰）相识两个月就闪电结婚，火热的激情在三年的婚姻生活中燃烧殆尽，貌合神离。时尚顾问柔娜（严贞花 饰）和饭店管理人员敏才（朴拥宇 饰）相恋四年，结婚三年，正在经历着爱情的“七年之痒”，已无当初的浪漫温馨。在陌生的香港，敏才邂逅了小如，二人一见钟情；几乎同时，英俊为了设计问题，拜访柔娜，心灵疲惫的柔娜，被英俊所吸引。看似永远不会有交集的四个人，分别和对方的爱人发生了一夜情。心灵错位的他们以外在电梯口相遇，所有的心情都写在暧昧的眼眸里，尴尬？惊喜？心跳？他们该何去何从？©豆瓣', '严正化', '郑允秀', 6.4, 12168, 'tt1159223', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p472359034.jpg', 2, 12.8, 55.2, 23.5, 6.5, '0.294963,0.021722,-0.799830,0.328290,0.009229,-0.226726,0.976557,0.221055,-0.357800,-0.235615,0.208717,0.517768,-0.491687,0.485149,0.218794,-0.021638,-0.056433,-0.830016,-0.088078,-0.369163,-0.075441,-0.461975,-0.043580,-0.020087,0.221673,-0.273849,0.430798,0.127862,0.064450,0.641627,0.299955,-0.078237,-0.413131,0.223451,-0.128071,-0.095685,0.027630,0.279916,-0.537637,-0.314237,-0.153179,-0.173501,-0.127545,-0.045834,-0.131157,0.324418,0.753774,0.156803,-0.475123,0.169549,0.408272,0.086835,-0.083852,0.166731,0.217421,0.191043,0.322453,0.342455,-0.306148,0.018912,0.283298,-0.091614,-0.664976,0.341138,0.119238,0.328496,-0.423796,0.777560,0.000220,-0.204625,0.268227,-0.093518,0.165074,0.326291,0.359283,0.585531,-0.101088,0.262113,-0.360511,0.392212,0.780349,0.214891,-0.490284,0.569360,-0.291531,-0.234305,-0.175037,0.101623,-0.404403,0.102552,0.173239,0.106953,-0.112160,0.380550,-0.711810,0.116335,0.100900,0.127899,0.049795,-0.421930,-0.136315,-0.807377,-0.484017,-0.705002,-0.280481,0.320089,0.229374,0.042110,0.587067,-0.802071,0.151707,0.184769,0.372310,-0.354366,0.701940,0.168116,-0.139677,-0.174675,-0.113679,0.301345,-0.173858,0.058914,0.134623,0.383756,-0.249241,0.338790,-0.685356,0.330364', '26687241', '1296534', '24839498', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30261964', '古田军号', '剧情', '《古田军号》是庆祝中华人民共和国成立70周年献礼影片。影片用真诚的艺术表达和创新的手法，以一个红军小号手的视角，讲述了红军从井冈山突围到闽西期间，年轻的革命领袖带领年轻的红军，在绝境中探索真理，开辟了中国革命成功的非凡历程。', '王仁君', '陈力', 6.8, 13318, 'tt10734292', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2564173381.jpg', 3.8, 10.3, 40.7, 30.6, 14.6, '0.146107,-0.113218,-0.593327,0.671493,-0.028613,-0.182065,0.157226,-0.046085,-0.336850,0.212148,0.647981,0.684824,0.142267,-0.075949,0.245485,-0.293282,-0.151933,-0.681606,-0.076272,0.267121,-0.228951,-0.414286,-0.253857,0.054534,-0.272361,-0.306669,0.589571,0.142450,-0.814729,0.697991,0.138993,0.199287,0.148306,0.080862,-0.057632,-0.024190,0.390444,-0.161701,-0.644839,0.285359,-0.194231,-0.393456,-0.594777,0.306995,-0.498229,0.602849,0.693287,-0.319720,0.103968,0.152594,0.653282,-0.459096,-0.371548,0.194081,0.259454,0.487744,-0.017301,0.376305,0.099023,0.241110,-0.793558,-0.383408,-0.949145,-0.407179,-0.095940,0.225902,-0.663853,0.423771,0.230847,-0.095281,0.632230,-0.399992,0.171431,0.367172,0.132053,0.578953,-0.155897,0.128825,-0.369240,0.634724,0.326834,-0.266437,-0.536937,0.329919,-0.291138,-0.420769,0.297470,-0.180946,-0.249597,-0.030396,0.117484,-0.268971,0.214115,0.014097,-1.000869,0.169332,-0.285680,-0.418931,0.273052,-0.155020,-0.293675,-0.962804,-0.566328,-0.507500,0.004178,-0.143408,-0.048493,-0.258825,1.279547,-0.880859,-0.222175,0.473286,-0.045795,-0.342161,0.864774,0.496234,-0.103023,-0.282163,0.112242,0.125225,-0.488265,0.414780,-0.252622,0.621343,-0.230327,-0.102109,-0.587159,0.562182', '27602116', '3811356', '24284209', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30262334', '三傻闹地球', '喜剧', '三个外星人因看中电视购物中的按摩毯决定飞往地球，谁知途中飞船坠毁，意外遇见小男孩Luis并与其成为好友。因Luis父亲痴迷于证明太空中智慧生命的存在，而忽略了儿子，导致Luis十分孤独，没有朋友。甚至被校长建议送去寄宿学校。为避免被送去寄宿学校，一场狂乱的冒险就此展开。', '卡勒姆·马洛尼', '克里斯托弗·劳恩斯坦', 6.3, 2959, 'tt4410000', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2572182952.jpg', 1.3, 10.7, 62.7, 20.7, 4.7, '0.296538,0.155431,-0.521296,0.392685,-0.241591,0.004624,0.523486,0.059689,-0.496048,-0.507656,-0.057872,0.689228,0.220593,0.221090,0.343751,-0.349434,0.033641,-0.217775,0.162319,0.030248,-0.350985,-0.517320,0.032138,-0.104299,-0.104779,-0.534350,0.765675,0.033481,-0.492172,0.843006,-0.214830,0.450328,-0.489515,0.439214,-0.145901,-0.207372,-0.079429,0.386953,-0.347205,0.555555,0.082227,-0.140483,0.422013,0.115096,-0.090536,0.155004,1.068240,-0.039356,-0.207498,-0.698912,0.447048,-0.193696,-0.025893,0.030742,0.184778,0.391741,0.009750,0.074075,-0.028737,0.147948,0.540179,0.145288,-0.553776,0.040719,0.233413,-0.219011,-0.405932,0.365152,0.018701,-0.187548,0.115156,-0.213466,0.401796,0.069448,0.465899,0.271751,-0.133963,0.195901,-0.102875,0.197660,0.743991,-0.189000,0.109144,0.465279,-0.048183,-0.040152,0.526316,-0.217609,-0.523130,0.364418,-0.052289,0.209495,-0.296160,0.290645,-0.513273,-0.189875,-0.425331,-0.275760,0.200926,-0.537263,0.161419,-0.675000,0.317519,0.397808,0.033430,0.014536,-0.050083,-0.311826,0.346631,-0.599783,0.471387,0.788971,0.409748,-0.718220,0.880025,0.184283,0.181954,-0.215145,0.356348,0.117714,0.311298,0.243005,-0.256563,-0.310769,-0.087594,0.021875,-0.356240,0.227225', '1309194', '34966198', '3811356', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3026357', '老爷车', '剧情', '曾参加过朝鲜战争的福特车厂退休老工人沃尔特•科瓦尔斯基（克林特•伊斯特伍德 Clint Eastwood 饰）在妻子去世后独自居住在密歇根州小城的低收入亚洲移民区。邻居是个苗族大家庭，其中一对兄妹引起了沃尔特的注意。姐姐苏（安蕾•荷 Ahney Her 饰）幽默善谈，逐步与固执又有点种族主义的老沃尔特成为了朋友；沉默寡言的弟弟涛（比•王 Bee Vang 饰）则被自己的远房表兄强迫加入当地的苗族黑帮，第一次行动就被指派去偷沃尔特视为珍宝的1972年福特老爷车。偷车不成，涛被家人强迫，给沃尔特打工赎罪，却没曾想与沃尔特建立了深厚的友谊。而当地的苗族帮派却不肯就此罢手，为了苏与涛的安全和社区的安宁，老战士沃尔特该如何行动呢？本片获金球奖最佳原创歌曲提名（《老爷车》）。©豆瓣', '克林特·伊斯特伍德', '克林特·伊斯特伍德', 8.6, 92130, 'tt1205489', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1155946363.jpg', 0.2, 0.8, 10.9, 44.7, 43.4, '0.262548,-0.148602,-0.548113,0.529913,-0.106309,-0.611138,0.384815,0.111226,-0.561334,-0.320329,-0.062978,0.864744,-0.077005,0.156515,0.111361,-0.056099,-0.218027,-0.479477,-0.094269,-0.122468,-0.222413,-0.439407,-0.034843,-0.111954,-0.201376,-0.120874,0.492497,-0.161571,-0.090727,0.517015,0.360032,0.442196,0.048950,0.122939,-0.353189,0.099917,0.186255,-0.018858,-0.503188,0.134836,-0.045058,-0.067591,-0.164915,0.127009,0.323436,0.366090,0.454242,-0.168644,0.020284,-0.197544,0.151681,-0.096500,0.128123,-0.015511,0.526344,-0.133998,0.233694,0.309608,-0.220240,-0.178905,0.044405,-0.214834,-0.471202,0.251882,0.280217,-0.037737,-0.672729,0.324002,-0.110584,-0.004508,-0.089256,-0.094556,0.314607,0.525175,0.113973,0.355724,0.036039,0.147927,-0.467924,0.423700,0.665325,0.079808,-0.135777,0.145021,-0.205109,-0.302937,0.255772,-0.510962,-0.502921,-0.084457,0.284097,-0.298041,0.106565,0.260978,-0.565108,-0.287855,-0.306618,-0.113360,0.295008,-0.290611,0.086514,-0.441008,-0.067009,-0.279330,0.092743,0.105645,0.007954,-0.085208,0.671868,-0.921598,0.249273,0.455705,0.375995,-0.674331,0.642922,0.118512,0.249188,-0.190677,-0.129808,0.032908,0.261517,0.086905,0.239282,0.100732,0.006560,-0.430807,-0.046063,0.196584', '1308035', '1292720', '1292219', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30263995', '一吻定情', '喜剧', '笨蛋爱上天才，会有结果吗？平凡女孩原湘琴（林允饰）喜欢上了天才少年江直树（王大陆饰），在她表白失败准备放弃之际，爸爸居然带着自己搬进了直树家里？！一个猛追，一个猛逃，热闹欢腾的纯真高中生活就此上演。朝夕相处中，直树渐渐被湘琴乐观的无畏精神吸引，他开始怀疑：湘琴究竟是人生偏差、还是自己的命中注定?', '王大陆', '陈玉珊', 4.4, 99366, 'tt9657764', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2546255256.jpg', 28.3, 35.1, 27.2, 6.2, 3.3, '0.285331,0.301464,-0.622837,0.257137,-0.349813,-0.071564,0.465941,-0.099923,-0.235117,0.055132,0.081519,0.444033,0.001500,0.574862,0.194547,0.092198,-0.096569,-0.512564,0.252512,0.081931,-0.225425,-0.143896,-0.365923,-0.242987,-0.096186,-0.193559,0.531635,0.237271,-0.077306,0.472281,0.354782,0.091347,0.122352,0.423860,-0.119611,0.198465,0.244261,0.394868,-0.007532,0.134162,-0.161679,-0.181310,-0.077541,0.150105,-0.190546,0.183404,0.638945,-0.050849,-0.275249,-0.256171,0.347708,-0.280279,-0.330051,0.233670,0.281175,-0.098779,-0.052824,-0.034802,0.072263,-0.138288,-0.011963,0.007535,-0.289045,0.000505,0.170979,0.005104,-0.422985,0.401948,0.221166,-0.127087,0.243156,-0.304357,0.089099,0.219892,0.573454,0.108133,-0.032577,0.131579,0.011372,0.194940,0.947736,-0.079662,-0.239290,0.428369,-0.395587,-0.072106,0.316691,-0.365482,-0.763753,0.157678,0.188277,-0.140384,-0.153889,0.108823,-0.248330,0.139249,0.090585,0.113116,0.032669,-0.563620,-0.325715,0.094695,0.020903,-0.361078,-0.428568,0.115554,-0.440004,-0.323120,0.901396,-0.792370,0.189009,0.505955,0.187951,-0.523068,0.522655,0.149881,-0.486577,-0.255909,0.221930,0.467689,-0.470642,0.050618,-0.139151,0.245146,0.009874,0.171118,-0.439135,0.701884', '1308836', '35030151', '3445516', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30264504', '异界', '动作', '在一场巨大而神秘的事故之后，一位年轻有才华的建筑师在一个与现实世界相似的奇异世界里苏醒，这个世界建立在这里人民的记忆之上，而这些人则处于深度昏迷之中。由于这些人的记忆力参差不齐、混乱、不稳定，导致奇怪的记忆和回忆——城市、冰川、河流可以共存在一个房间里，所有的物理定律都可以被打破，建筑师必须找到他们昏迷的具体规律，才能找到通往现实世界的出口。就在他与命运抗争的同时遇到了真爱，而经历此次昏迷之后，他发现自己不得不重新认识这个世界……', '林奈·穆罕默托夫', '尼基塔·阿格诺夫', 6.2, 21534, 'tt6087226', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2581658698.jpg', 1, 16.4, 58.4, 20.6, 3.5, '0.281809,0.727192,-0.871693,0.607408,-0.176877,0.075162,0.978281,-0.204213,-0.851001,-0.531530,0.024000,0.767561,-0.014517,0.364752,0.194122,-0.141532,-0.251307,-0.666221,-0.235656,-0.239741,-0.898104,-0.608199,-0.639979,-0.289644,-0.308765,-0.552277,0.955739,0.466393,-0.399136,0.204817,-0.240472,0.267655,-0.323236,0.513001,-0.398850,-0.125069,0.274290,0.230050,-0.460572,0.162537,-0.120701,-0.034471,0.145778,0.368963,-0.407935,0.117576,0.815039,-0.356650,-0.464130,0.116193,0.478749,-0.261458,-0.468302,-0.027463,0.482265,-0.069831,0.159066,0.170946,-0.125349,-0.032452,-0.116700,-0.137554,-0.992628,-0.220299,0.193603,0.330728,-0.310972,0.382614,0.265915,-0.429971,-0.268512,-0.120359,0.424896,0.501258,0.700844,0.589124,-0.252353,-0.134457,-0.329166,-0.015023,0.882977,-0.230737,-0.761404,0.633090,-0.387694,-0.518736,-0.406676,-0.125790,-0.503109,0.168905,0.169472,0.312041,-0.501794,0.278538,-0.655605,0.382758,-0.133527,-0.383304,-0.201819,-0.375160,-0.359421,-0.195231,-0.493363,-0.263595,-0.163912,0.176818,0.015618,-0.101842,0.801872,-0.950423,0.353014,0.572746,0.235065,-0.407289,0.787400,0.116222,0.243899,-0.592697,0.260174,0.468256,-0.238104,0.283657,-0.414682,0.293187,-0.129287,0.191259,-1.078920,0.703326', '30401849', '26667010', '1291835', '4927785');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30264607', '鬼娃回魂', '恐怖', '重启版《鬼娃回魂》首爆海报，凶险公仔Chucky全新回归由《拍栗得》导演Lars Klevberg执导的新版《鬼娃回魂》首爆海报，经典的杀人公仔Chucky将全新回归。本片由《英格丽向西行》的奥布瑞·普拉扎和《亚特兰大》的布莱恩·泰里·亨利领衔主演，并已于本周在温哥华开拍。在新版中，普拉扎饰演的母亲送给自己儿子一个公仔作为生日礼物，却对公仔凶险的本性毫不知情。该片基于1988年的原版，但该系列的编剧唐·曼西尼和制片人大卫·基施纳并没有参与到此次新版中。实际上，两人目前正在忙于更多原版“鬼娃回魂”的电影和相关的潜在剧目。MGM推出的这个新版《鬼娃回魂》显然将会和大家熟知的原版Chucky区分开来，并同后者展开竞争。', '奥布瑞·普拉扎', '拉尔斯·克列夫伯格', 5.9, 9252, 'tt8663516', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2553873608.jpg', 5, 23.3, 50, 15.7, 5.9, '0.271934,-0.009482,-0.509962,0.548799,0.075351,-0.129318,0.699474,-0.088929,-0.163216,-0.289390,0.014494,0.835756,-0.358865,-0.067618,0.290869,0.114187,-0.277107,-0.454021,-0.144114,0.048441,0.005573,-0.485351,-0.572828,0.003065,-0.102349,-0.174814,0.788775,-0.035843,-0.304283,0.339446,0.554823,0.113674,-0.217275,0.167718,0.202201,0.167047,-0.199338,0.031494,-0.397014,0.307085,0.094749,-0.044069,-0.156006,0.161885,0.079786,0.515845,0.673250,-0.585175,0.004145,0.171052,0.670243,-0.299306,-0.233428,-0.086994,0.048130,0.176269,0.229904,0.090215,-0.000269,0.433350,-0.223236,-0.432259,-0.936857,-0.023721,0.398425,0.214119,-0.459453,0.525263,-0.237960,0.121286,-0.010823,-0.404415,0.094158,0.270567,0.344185,0.459733,-0.091772,-0.011156,-0.248951,0.403760,0.163457,0.107176,-0.160417,0.490086,-0.008616,-0.526729,-0.277616,-0.171689,-0.366708,0.167758,0.339722,0.163253,0.044221,0.130849,-0.637397,-0.028344,-0.035344,-0.393223,0.006175,-0.297839,0.143793,-0.927774,-0.102822,-0.448505,0.111523,-0.322289,0.384609,-0.487785,0.573150,-0.648665,0.283078,0.142194,0.092053,-0.202301,0.482306,0.191233,0.144246,-0.433703,-0.253641,0.245425,0.140604,0.245199,0.005413,0.243409,0.193919,-0.515909,-0.495574,0.428765', '3318306', '26275494', '26577354', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3026555', '丛林有情狼', '喜剧', '加拿大绿宝石国家公园生活着两群完全不相来往的两群狼，其中凯特（海顿·潘妮蒂尔 Hayden Panettiere 配音）是西部狼群首领的女儿，对她来说原则、职责和责任重于一切；亨弗雷（贾斯汀·朗 Justin Long 配音）则来自另一个狼群，成天嘻嘻哈哈，无忧无虑，是个享受派。凯特即将嫁给东部狼群首领的儿子加斯（克里斯·卡马克 Chris Carmack 配音），并不是为了爱情，而是为了阻止两只狼群之间即将爆发的一场可怕战争。世事难料，就在婚礼当天，凯特和亨弗雷被森林管理员抓走送去了爱达荷州的“锯齿”国家公园，为了避免组群见不必要的战争，俩人逃离出来，他们能在战争爆发前赶回去，化解矛盾吗……本片曾入围了第83届奥斯卡奖最佳长篇动画奖。©豆瓣', '贾斯汀·朗', 'Anthony Bell', 6.5, 12893, 'tt1213012', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p871731481.jpg', 1.8, 12, 55.3, 23.7, 7.3, '-0.053284,-0.009736,-0.506544,0.573535,0.168859,-0.116864,0.623929,0.214012,-0.071750,-0.205066,0.035322,0.616944,0.008487,-0.113254,0.363644,-0.038532,-0.239999,-0.556761,-0.241525,0.031561,-0.184940,-0.339506,-0.065736,-0.259979,0.011518,-0.253789,0.375726,-0.154421,-0.231890,0.390737,0.560635,0.361997,-0.378789,0.300938,0.061935,-0.081248,0.174207,-0.013718,-0.538957,0.191396,-0.296664,0.243159,-0.389961,0.163655,0.233619,0.109026,0.622974,-0.368452,0.080159,-0.339060,0.109963,-0.441013,0.163495,-0.018854,0.444663,-0.443533,0.406724,0.336452,0.231970,0.249370,0.022611,-0.264541,-0.661377,0.110722,-0.177518,0.174624,-0.409412,0.352907,0.092632,-0.080590,0.370171,0.017064,0.200297,0.532589,0.286237,0.120975,-0.008473,0.043892,-0.544146,0.173824,0.771227,-0.111483,-0.085843,0.058244,-0.206894,-0.323494,-0.084181,-0.139650,-0.541164,0.014668,0.454067,-0.232587,-0.280543,0.401884,-0.515370,-0.105198,-0.253903,-0.432496,0.076347,-0.383411,0.062179,-0.712293,0.152619,-0.140962,-0.309244,0.029663,0.032005,-0.157100,0.527351,-0.595445,0.181596,0.773664,0.204257,-0.246053,0.361608,0.263044,0.352433,-0.375715,-0.029325,0.057218,0.188395,0.301171,0.121641,0.040068,0.048469,-0.057839,-0.250367,0.657558', '1306723', '11541282', '3147969', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3026559', '登月第一人', '剧情', '影片将聚焦美国传奇宇航员尼尔·阿姆斯特朗的生平，重点讲述他在1961-1969年间成为人类历史上第一个登月者的过程，同时也展现出人类在这次史上最危险的宇宙探索征途中所付出的难以想象的国家与个体牺牲。影片根据詹姆斯·汉森的传记作品《第一人：尼尔·阿姆斯特朗的人生》改编而成。尼尔·阿姆斯特朗，是人类历史上首位登上月球的宇航员。他1930年出生，2012年逝世，是美国阿波罗11号登月计划宇航员。在美国航空航天局服役时，阿姆斯特朗于1969年7月21日成为了第一个踏上月球的宇航员，也是第一个在地球外星体上留下脚印的人类成员。', '瑞恩·高斯林', '达米恩·查泽雷', 7.7, 47623, 'tt1213641', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2532776305.jpg', 0.4, 2.1, 27.8, 51.2, 18.5, '0.014841,0.025536,-0.803444,0.633869,0.157611,-0.274756,0.522540,-0.510181,-0.693712,0.075049,0.301883,0.990210,0.023161,0.151770,0.599882,0.112096,-0.459907,-0.435030,-0.150650,-0.457564,-0.688561,-0.528571,-0.380194,-0.343775,-0.055347,-0.781350,1.286430,0.027730,-0.090710,0.234288,-0.120037,0.182334,0.084371,0.165830,-0.133082,0.005474,0.148280,0.035438,-0.531359,0.188325,-0.530402,-0.329382,-0.068349,-0.129066,-0.436385,0.017189,0.569997,-0.410199,0.276719,-0.597416,0.587450,-0.348608,-0.308136,-0.321763,0.575386,0.042233,-0.164438,0.589506,0.323241,-0.007965,-0.155650,-0.425889,-0.912664,-0.383567,-0.029184,0.090726,-0.392512,0.481944,-0.402252,0.288227,-0.032062,-0.289834,0.324380,0.316923,0.367297,0.317888,-0.339086,0.100216,-0.253227,0.420147,0.626786,0.177775,-0.449223,0.150174,-0.057859,-0.749329,-0.380296,-0.545945,-0.268180,0.282985,0.148813,0.163695,-0.108829,0.564906,-0.750691,0.220454,-0.190849,-0.659318,0.325902,-0.234990,-0.201030,-0.775869,-0.043106,-0.392931,-0.160664,-0.039656,0.186193,-0.642396,1.106375,-0.580308,0.368854,0.722305,0.292987,-0.137747,1.090785,-0.305381,0.234156,-0.497518,0.133850,0.539042,-0.039133,0.294356,-0.576549,0.225828,0.040832,0.026252,-0.164708,0.613097', '25880986', '35262731', '30349667', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3026572', '世界尽头', '喜剧', '过度沉湎酒精、年届不惑的盖瑞·金（西蒙·佩吉 Simon Pegg 饰），突然间想起20年前青春时代一件引以为豪但未竟的浪荡事，于是相继找来如今已经有了各自家庭和事业的好伙伴奥利弗·张伯伦（马丁·弗瑞曼 Martin Freeman 饰）、彼得·佩吉（埃迪·马森 Eddie Marsan 饰）、史蒂文·普林斯（帕迪·康斯戴恩 Paddy Considine 饰）和安迪·奈特利（尼克·弗罗斯特 Nick Frost 饰）。他们相约返回故乡纽顿哈芬，试图再次找回通宵5人、12间酒吧、60杯啤酒的快乐时光。小镇一如既往，几乎没有什么变化，但是镇上的人似乎全然不记得这几个老男孩。在盖瑞的引领下，起初一切还比较正常，可当夜幕降临之后，诡异事件交替上演，盖瑞等人发现，他们仿佛不知不觉步入某种超自然的圈套之中……©豆瓣', '西蒙·佩吉', '埃德加·赖特', 7.4, 57444, 'tt1213663', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1979763511.jpg', 1, 4.4, 33.6, 43.1, 17.9, '0.366675,0.078094,-0.640327,0.157866,0.014539,-0.494791,0.766616,0.168926,-0.684365,-0.577212,-0.115342,0.738669,-0.273141,0.214369,0.490170,0.015359,-0.625152,-0.687805,0.195866,-0.179553,-0.313765,-0.358147,-0.236230,-0.137525,-0.167093,-0.189698,0.182082,0.118217,0.221574,0.527641,-0.033803,0.260046,-0.004606,0.542252,-0.053717,0.257597,0.312781,-0.012164,-0.248272,-0.068099,0.173748,-0.066343,-0.361732,0.053652,0.217348,0.384766,0.487175,-0.229064,-0.057456,0.020801,0.217624,0.060384,0.003361,-0.004418,0.077544,0.033606,0.118486,0.115129,-0.087871,-0.221433,0.030045,-0.083662,-0.264689,0.261703,0.014872,0.179393,-0.242133,0.289256,0.042581,0.028653,0.145229,-0.164430,0.063576,0.311807,0.523845,0.166183,-0.012367,-0.098304,-0.612739,0.054341,0.515762,0.047977,-0.326575,0.526807,-0.215721,-0.263463,-0.229019,0.089460,-0.418656,0.020665,0.149865,0.208859,0.042847,0.333102,-0.638809,-0.099563,-0.200864,-0.006918,-0.120819,-0.228067,-0.313628,-0.668226,-0.100423,-0.406274,-0.193545,-0.000915,-0.071280,0.123202,0.304948,-0.654789,0.276283,0.443023,-0.083995,0.028363,0.566527,-0.175219,0.178448,-0.367875,-0.066632,0.274518,0.004321,0.021916,0.200514,0.393794,-0.030478,0.064334,-0.181680,0.478976', '1309172', '1297239', '1296534', '1394176');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30267284', '阿基米德大战', '剧情', '三田纪房人气漫画<阿基米德大战>将拍摄真人电影，山崎贵导演，菅田将晖主演。故事舞台设定在二战对美开战前，为了设计大和号战舰，山本五十六找到了被称为“阿基米德再生”的天才数学家櫂直。然而，随着计划的深入，櫂直发现了军部不可告人的阴谋。影片将于明年暑假公映，东宝2019年度大作。', '菅田将晖', '山崎贵', 7.4, 13109, 'tt8708802', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2556860883.jpg', 1.7, 4.1, 32.9, 44.4, 16.8, '-0.549003,-0.230165,-0.607575,0.387811,0.706825,-0.026634,0.335113,0.072891,-0.077345,-0.323459,0.238905,0.675756,-0.697255,-0.050593,0.458143,-0.140560,-0.263413,-0.566021,-0.325544,0.130096,0.170065,-0.449955,-0.083169,-0.098239,-0.075966,-0.490013,1.074788,0.175680,-0.507585,0.126337,0.516907,-0.057273,-0.125902,-0.169226,0.305336,0.095263,0.293651,-0.107813,-0.436146,0.524970,-0.368219,0.024019,-0.225116,-0.301394,0.038272,0.197126,0.460772,-0.156794,-0.125305,-0.077164,0.573176,-0.447974,-0.284066,0.053188,0.423777,0.476467,-0.052406,0.473901,-0.008356,0.132580,0.037123,-0.509503,-0.465607,0.207412,-0.024282,-0.020267,-0.070284,0.436448,-0.472999,-0.010765,0.245458,-0.047256,0.203443,0.318051,0.728270,-0.067747,-0.031611,0.470148,-0.292149,0.403004,0.163849,0.011339,0.167302,0.413901,0.332194,-0.484443,-0.516126,-0.435650,0.122068,0.223775,0.496720,-0.248171,-0.188329,0.323816,-0.255941,-0.181263,0.096975,-0.420411,0.215681,0.074729,-0.045205,-0.813699,-0.150333,0.251368,-0.177387,0.005309,0.131765,-0.518089,1.078967,-0.474661,-0.077125,0.717866,0.324003,-0.115027,0.580442,-0.017278,-0.293434,-0.192973,0.062302,-0.070867,-0.224365,0.483084,0.349336,0.512632,-0.233743,-0.801496,-0.436659,0.255347', '1322847', '27602116', '25880986', '1920765');
