INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30269016', '半个喜剧', '喜剧', '三个自由浪漫的年轻人，过着各怀心思的人生：有人急着摆脱单身，有人想在结婚前放荡一番，有人想在 大城市站稳脚跟。因为一次情感出轨，三人扭结成了一团“嬉笑怒骂”的乱麻。当各种价值观碰撞在一起， 当一个人需要平衡亲情友情与爱情......他们慌乱的生活，就像是半个喜剧。', '任素汐', '周申', 7.3, 528120, 'tt11273332', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2576482356.jpg', 1.2, 5.7, 34.7, 44.6, 13.8, '0.432920,0.003224,-0.932216,0.415338,0.153881,-0.455738,1.126935,0.033327,-0.234965,-0.015440,-0.182457,0.437984,-0.452763,0.610397,0.113915,-0.443917,-0.363928,-0.865821,0.094367,0.291019,0.143948,-0.272142,-0.004186,-0.194516,-0.348402,-0.240395,0.744178,0.157457,-0.260253,0.242545,0.478206,-0.185208,-0.510905,0.266874,-0.341501,-0.097646,0.043599,0.362411,-0.929741,0.014158,-0.056073,0.132203,-0.299060,-0.147044,-0.289862,0.000916,0.734930,-0.119417,-0.232525,0.385411,0.257135,0.124584,-0.233534,0.284773,0.102014,-0.100698,0.149032,0.065368,-0.093552,0.373971,0.160923,0.023041,-0.514053,-0.133971,-0.291943,0.132651,-0.627434,0.791330,0.195001,-0.291682,-0.113468,-0.415936,0.130188,0.553666,0.186267,0.552580,-0.532217,0.048347,-0.623858,0.305647,1.229608,0.238572,-0.442324,0.628600,-0.265056,-0.212991,-0.440217,-0.029429,-0.435230,-0.611352,0.549912,-0.304949,-0.628651,0.266091,-0.662614,0.315262,0.085585,-0.080870,0.147838,-0.589318,0.100590,-0.246632,-0.175734,-0.327498,-0.694934,0.371046,-0.004928,-0.149015,0.583359,-0.896669,0.271845,0.960637,0.165106,-0.665000,0.588275,0.511602,0.045178,-0.290923,0.011536,0.116770,-0.166583,0.100630,0.404966,0.502150,-0.205487,0.479835,-0.640001,0.332719', '1291835', '30209018', '4861627', '27041519');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3027015', '世界奇妙物语 2008春之特别篇', '悬疑', '1 比之前更好的人这一天，是孝（伊藤英明饰）女朋友的生日，孝打算精心准备一番，在列出详细的日程表后，他出门了。可是没有给老人让座的孝竟回到了起床时刻！就这样，只要一不回应他人的请求，孝的一天便会重新来过。2 你看…这个…麻美（户田惠梨香饰）和恋人光一（向井理饰）于图书馆邂逅，之后便开始了甜蜜生活。某日，麻美的面前突然出现一个举着dv的小孩，dv中的影像竟全部在未来成真！麻美看见了光一将会被人攻击，她匆忙赶去解救光一……3 日出商店街 疯狂节一年一度的疯狂节来到了，所有的人都动了真格，操做生意的器材与人疯狂搏斗。（船越英一郎饰）4 透明的一天纯子（北乃きい饰）死后，她的灵魂出窍，她见到了班里的同学伪善的笑容下真实的嘴脸，发现了教导主任肮脏的秘密，还目睹校方领导为了掩盖她的死因的卑劣手段。这时，纯子突然想起自己并非自杀，而是被人推下楼的……5 回放FED是能将他人的亲身经历重放的机器，即五感体验装置。公司课长大石（堺雅人饰）其实也是“黑暗一族”，他深深迷恋着FED给予的模拟杀人快感。可是，大石的眼前却开始出现幻象，他陷入了虚幻和真实边缘的泥沼。', '伊藤英明', '植田泰史', 7.6, 7607, 'tt3713716', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1517935820.jpg', 0.4, 2.5, 31.1, 47.8, 18.3, '0.275503,0.105590,-0.736205,0.364092,-0.205272,-0.282935,0.763180,0.096458,-0.374445,-0.167341,0.252696,0.715980,-0.427481,0.371807,0.158780,0.151008,-0.333499,-0.794520,-0.155772,-0.126316,-0.404890,-0.269457,-0.104936,-0.201807,0.086073,-0.301232,0.306321,0.085096,-0.128033,0.356864,0.166803,0.037954,0.050660,0.636583,-0.247979,0.135691,-0.092921,0.051799,-0.078718,0.032246,0.000520,-0.467646,-0.211696,0.412670,-0.157157,0.243705,0.691275,-0.239357,-0.222851,-0.135049,0.398998,-0.166835,-0.095158,0.260399,0.162924,-0.000772,0.087815,0.136432,-0.271068,0.081113,0.158032,-0.086294,-0.715261,-0.031213,-0.118232,0.091635,-0.484452,0.354177,-0.082585,-0.036087,0.195366,-0.285802,0.326235,0.153859,0.155297,0.379365,-0.248750,-0.117849,-0.286490,0.305583,0.562287,-0.101193,-0.219388,0.512340,-0.028359,-0.346647,-0.173247,-0.017381,-0.165053,-0.043772,0.272935,0.225624,-0.254731,-0.011821,-0.569625,-0.180870,-0.215831,-0.153617,-0.008719,-0.386162,-0.462230,-0.368545,-0.083260,-0.238494,-0.506126,0.278643,0.003353,-0.250667,0.551238,-0.873367,0.222823,0.561491,0.196703,-0.299530,0.568894,-0.125811,-0.196367,-0.017030,0.