INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30270746', '寒单', '剧情', '台东特有的元宵文化习俗「炸寒单」。 《大钓哥》黄朝亮执导，郑人硕、胡宇威主演。肉身寒单阿义站在神轿上，炸药意外造成阿义女友萱萱的死亡。当年意外的真相曝光后，炸在身上的纹身之罪，是否能抵消深藏的锥心之痛？', '郑人硕', '黄朝亮', 7.7, 7247, 'tt9531138', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2542179594.jpg', 0.8, 2.7, 28.1, 49.5, 19, '0.040566,0.121723,-0.561070,0.280999,0.136831,0.563053,0.710592,0.283375,-0.252688,0.033511,0.770489,0.777082,-0.416398,-0.051612,0.021332,0.121677,-0.035605,-0.629227,0.000751,-0.175509,-0.734606,-0.241570,0.251755,0.101681,-0.273945,-0.323729,0.706411,-0.046933,-0.145868,0.656773,0.071786,0.201205,-0.310578,0.459100,-0.180929,0.218617,-0.118594,-0.093914,0.126338,0.021180,0.224734,-0.778683,0.326941,0.587192,-0.093936,0.288359,0.559927,-0.233116,0.004800,-0.153050,0.201859,-0.077174,0.167986,0.382259,-0.116954,-0.199207,0.635367,0.086474,0.043189,-0.110590,0.029277,0.030360,-0.603892,-0.247323,-0.001813,0.161969,-0.241771,0.454391,-0.225035,0.412030,-0.161280,-0.008604,0.065826,0.067207,0.161540,0.693110,-0.486242,0.314863,-0.188909,-0.082481,0.447034,-0.476344,-0.287727,0.491330,-0.122029,-0.209895,-0.329444,0.087624,-0.370505,0.285229,0.374237,0.202997,-0.158110,0.206839,-0.435665,-0.229559,-0.202313,0.315267,0.097523,0.372033,-0.394270,-0.421120,-0.415601,-0.368321,-0.443305,-0.191909,0.572086,-0.359352,0.306268,-0.412801,0.235604,0.154781,0.096300,-0.275497,0.238056,-0.291047,-0.014565,-0.020041,-0.024686,0.569712,0.000285,0.161393,0.214297,0.384848,-0.048426,0.062355,-0.304442,-0.038754', '26342391', '1298095', '1306692', '1307800');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30271236', '最后一封信', '剧情', '岸边野裕里（松隆子）在姐姐远野未笑的葬礼上，遇到了姐姐的女儿远野鮎美（广濑铃）。无法接受母亲亡故的鮎美，也无法打开母亲留下的最后一封信。裕里参加了要和大家报告姐姐往生的同学会，巧的是，她的初恋对象镜史郎（福山雅治）也来了，两人在一封封书信的联系中串接起三人当年的故事。', '松隆子', '岩井俊二', 7.5, 8674, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2570353329.jpg', 0.6, 3.2, 32.6, 46.7, 17, '0.285094,-0.113741,-0.594057,0.814321,-0.246811,-0.307284,0.771438,-0.135723,-0.601882,-0.000993,0.020673,1.099255,-0.111839,0.610915,0.086262,0.144310,-0.241022,-0.647342,-0.028889,-0.278934,-0.438780,-0.565890,0.091935,-0.006580,-0.087719,-0.094543,0.331790,-0.211274,0.019347,0.410525,0.394962,0.006803,-0.304493,0.465106,-0.295682,0.355880,-0.367454,0.247498,-0.173296,0.273992,0.311964,-0.345154,-0.069602,0.355796,0.150702,0.241636,0.547125,-0.210946,0.140713,0.095258,0.297961,-0.176042,0.239983,0.305440,0.236119,0.148488,0.456148,0.364392,-0.323743,-0.449765,-0.192331,-0.139848,-0.595384,0.087397,0.179768,0.288124,-0.684984,0.661113,-0.312135,0.124736,0.139320,-0.692774,0.492665,0.475663,0.027638,0.287745,-0.369293,-0.228284,-0.261376,0.405836,0.624533,-0.008796,0.267377,0.345844,-0.166888,-0.329928,-0.063864,-0.178674,-0.634427,0.579324,0.259080,0.162734,-0.274460,0.117098,-0.506594,-0.345130,-0.220564,-0.084661,0.080443,-0.427583,0.056618,-0.308000,0.003891,-0.380186,-0.501166,0.181262,0.208049,-0.245409,0.825743,-0.789330,0.116858,0.436525,0.234399,-0.254638,0.806036,0.467489,-0.001589,-0.136459,0.335195,-0.096191,-0.140815,0.589098,0.390484,0.304908,0.195000,-0.128625,-0.702900,0.144890', '30162520', '1456503', '1292219', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30271717', '21座桥', '动作', '事业失意的纽约警探安德烈·戴维斯（查德维克·博斯曼 饰）意外被任命追捕一起重大涉毒杀人案的凶手。在这个骇人听闻的案件中，八名警察惨遭谋杀。为了让凶手尽快落网，戴维斯开启了曼哈顿历史上第一次全境封锁，岛上与外界联系的21座桥全部禁止出入。但封锁时间只有四个小时，戴维斯必须在天亮之前抓到凶手！在紧张的追捕行动中，戴维斯发现凶手也同样在被追杀，这起案件背后可能藏着一个滔天阴谋，他必须在一切不可挽回之前找出凶手并查明真相。', '查德维克·博斯曼', '布莱恩·柯克', 6.5, 37504, 'tt8688634', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2635094940.jpg', 0.4, 7.5, 61.5, 27, 3.7, '0.162650,0.034083,-0.810842,0.322422,-0.124397,0.111163,0.593484,-0.233462,-0.707133,-0.459051,0.217129,0.398153,-0.059632,0.050329,0.229942,-0.099328,-0.550509,-0.904290,-0.010464,-0.586504,-0.542286,-0.779920,-0.391144,-0.443433,0.024991,-0.125856,0.483612,0.392298,-0.090269,0.394357,0.384808,0.360658,-0.546770,0.479170,-0.078398,-0.276420,0.444444,-0.529029,-0.437657,0.493125,0.021029,-0.457785,0.081984,0.439474,-0.060844,0.640624,0.476749,-0.340424,-0.286567,0.178163,0.223121,-0.654990,-0.068461,0.294965,0.794726,-0.178404,0.177610,0.763088,-0.493909,-0.010612,0.132807,-0.069685,-0.789236,-0.083236,0.140778,0.234079,-0.307038,0.011786,-0.109122,0.226454,0.005030,-0.058718,0.201544,0.582922,0.377392,0.104446,-0.087366,-0.046125,-0.660394,-0.123627,0.614106,-0.455095,0.047838,-0.293246,0.266360,-0.191769,-0.240519,-0.232518,-0.057366,0.254951,0.619787,-0.023655,-0.319605,0.405382,-0.178628,-0.166559,-0.670770,-0.022388,-0.492830,-0.237162,-0.073357,-0.654764,-0.020403,0.197483,-0.234312,0.300294,0.043338,-0.298515,0.007164,-0.533669,0.249747,0.861973,0.145378,-0.542178,0.228431,0.322262,0.322838,-0.348701,-0.262154,0.124293,0.425582,0.596129,0.105667,0.188448,0.044513,-0.275232,-0.434096,0.211819', '1293434', '1307442', '26328483', '1419974');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30271841', '多哥', '剧情', '聚焦1925年雪橇手和雪橇犬齐心协力为拯救阿拉斯加州诺姆市孩子的性命而奔波于血清接力路上的事件，被称为“Great Race of Mercy”。1924年年底，诺姆市一个2岁小孩生病，医生诊断其患有扁桃体炎，这种疾病通常不会有生命危险，然而这个小孩成为例外，接下来很多孩子都被诊断患上了扁桃体炎，有几个不幸离世，医生最终确认这种病症是白喉。当时有一种疫苗能够用来对付白喉，然后诺姆市的疫苗全部过期，新疫苗在港口关闭前却未能送达，来年6月波罗的海才会解冻，也没有公路直通诺姆市、没有飞机，唯一运输货物的通道是邮路，然而冬天只有雪橇犬能够通行。卫生局决定使用两组雪橇犬接力运输，20个雪橇手和150只雪橇犬必须日夜兼程，经过河流，跨过平原，穿过森林，穿越冰冻的阿拉斯加邮路。最近的疫苗所在地为南纳，距离诺姆市1085公里，一般情况下狗拉雪橇需要费时25日，而他们只花了5天半就成功完成接力，拯救了多名孩子的性命。本片主角Togo是挪威赶雪橇高手Leonhard Seppala（威廉·达福 饰）使用的其中一只领头犬，因机智、卓越的领导力和敏锐的直觉备受称赞。Seppala被委任传送这场接力中最危险的一段，从诺姆到奴拉托接收那批免疫血清，在零下30度、七级以上强风的环境下成功完成了任务。之后南极探险家Roald Amundsen为Togo颁发了一枚金牌。比约恩饰演一名接力人员，在途中背叛了Seppala。', '威廉·达福', '埃里克松·科尔', 8.8, 93817, 'tt5116302', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2575882765.jpg', 0.2, 0.6, 9.1, 38.1, 52.1, '-0.181202,-0.177240,-0.420978,0.391627,0.000725,0.121782,0.332772,-0.281637,-0.315177,-0.270498,0.220949,0.752850,-0.089114,-0.054566,0.257648,-0.214473,-0.022511,-0.240530,-0.036669,-0.284009,-0.797021,-0.229187,-0.317545,-0.064946,-0.048141,-0.503325,0.554837,0.237264,0.026962,0.481510,-0.056179,0.366044,-0.083911,0.214391,-0.359799,-0.208214,0.225017,-0.249215,0.000923,0.569028,-0.181094,0.026435,0.093156,0.023479,0.199144,0.432957,0.614292,-0.183407,-0.222295,-0.239881,0.144792,-0.390589,0.072102,-0.174627,0.642733,0.112244,0.157505,0.112692,-0.242877,0.093648,0.011168,-0.215546,-0.665210,-0.135904,-0.200897,0.040879,-0.454314,0.078667,-0.207880,-0.083005,-0.006681,-0.363073,0.312436,0.426548,0.074190,0.351311,-0.315632,0.006600,-0.560625,0.059566,0.764309,-0.354047,-0.385532,0.270628,-0.174304,-0.661862,0.226876,-0.400663,-0.035787,0.195423,0.241676,0.225056,-0.273398,-0.024431,-0.287904,0.133885,-0.478444,-0.431826,-0.058400,-0.068525,-0.118022,-0.486200,0.339933,-0.212568,-0.163436,0.288286,0.168975,-0.238803,0.467103,-0.494685,0.235659,0.557451,0.234358,-0.343867,0.572895,-0.018565,0.381697,-0.272175,0.271729,0.218288,0.000937,0.542988,0.084177,0.274993,-0.056637,-0.164622,-0.396807,0.366321', '3755531', '1306530', '1294941', '1929463');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30272143', '盗梦特攻队', '动画', '心理治疗师鲁本的梦境饱受“妖魔化”的名画侵扰，蒙娜丽莎、维纳斯全都成了骇人的噩梦怪物;若想一觉好眠，唯一的办法是偷走所有入侵他梦里的名画。为帮助鲁本脱离梦魇，他与四名身怀绝技的病人联手组团偷遍罗浮宫、泰特现代艺术馆等各大美术馆一场飞天遁地、瞒天过海的疯狂盗窃计划也就此展开...', '伊万·卡马拉斯', '米洛拉德·科斯蒂奇', 8.3, 50726, 'tt6241872', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2574224336.jpg', 0.2, 1.4, 15.9, 47.2, 35.2, '-0.003149,0.063236,-0.450970,0.446701,-0.003878,-0.021651,0.484205,-0.194455,-0.400448,-0.308092,0.369312,0.514152,-0.208016,0.170443,0.315154,-0.086321,-0.297373,-0.764001,-0.259412,0.067826,-0.388905,0.021521,-0.424249,-0.354121,0.054083,-0.316111,0.569764,0.349087,-0.377326,0.110049,0.169770,0.403642,-0.262717,0.034283,-0.180739,-0.258635,-0.234821,-0.147954,-0.447703,0.326973,-0.155513,-0.263345,-0.021104,0.416810,-0.414778,-0.100408,0.632322,-0.427243,0.011641,-0.316530,0.132367,-0.375981,-0.262002,0.253110,0.171514,0.009552,0.038202,-0.035916,-0.236059,0.147041,0.117331,0.296110,-1.036425,-0.131079,0.349922,-0.029185,-0.234026,0.256300,0.091100,0.183768,0.027580,-0.081783,0.016829,0.284479,0.250415,0.486804,0.130164,0.026773,-0.788718,0.272083,0.471781,-0.123098,-0.253969,0.219895,0.050921,-0.242612,-0.050120,-0.460124,0.036360,-0.091941,0.319895,-0.085922,-0.320465,0.603808,-0.805302,-0.126839,-0.492048,-0.210160,-0.454047,-0.118970,0.193373,-0.879245,-0.161593,0.182729,0.067270,-0.103649,0.239265,-0.086114,0.466256,-0.450009,0.550492,0.572437,-0.028298,-0.359834,0.388061,0.012336,0.092901,0.079898,-0.172906,0.220829,0.355180,0.583797,-0.159042,0.190444,0.192521,-0.080669,-0.323123,0.437491', '30387441', '26747274', '7155241', '4014397');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30272753', '宝可梦：超梦的逆袭 进化', '动画', '故事讲述的是一群疯狂的科学家，为了自己的梦想，研制出一套只需要少许基因便可复制出宝可梦的机器，并把发掘到的世界最强宝可梦复制成了拥有比梦幻更强能力的超梦。但当超梦醒来后，却因无法找寻到真正的自我而暴走。火箭队的老大出现在超梦的面前，用花言巧语把迷失自我的超梦拉拢过来为自己办事，但没过多少时间，超梦再次对自我感到迷茫。超梦回到那个复制它的岛屿，决定开始它的复仇之战。', '松本梨香', '汤山邦彦', 6.1, 10403, 'tt8856470', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2625913008.jpg', 2.4, 17.7, 56.3, 19.5, 4.1, '0.008479,0.494817,-0.547285,0.618185,-0.454942,-0.461794,0.627967,-0.378722,-0.420945,-0.318567,-0.022679,0.620353,-0.039995,0.315388,0.029697,-0.137831,-0.041770,-0.414584,0.026189,-0.083504,-0.382931,-0.343872,-0.359024,-0.077127,-0.058587,-0.600925,1.094784,0.130963,-0.265636,-0.027637,0.112345,0.356369,0.124572,0.418106,-0.235274,-0.009991,-0.456291,-0.173351,-0.317500,0.393529,0.229528,-0.069327,-0.148365,0.496295,-0.311112,-0.005654,0.909171,-0.547857,-0.330037,-0.160257,0.606334,-0.303852,-0.121517,0.088669,-0.017735,0.415161,-0.239412,-0.139811,-0.062386,0.364824,0.030316,0.082191,-1.321222,-0.067007,-0.116513,0.038973,-0.468475,-0.022815,0.080739,-0.128921,0.186846,-0.458702,0.011983,0.289035,0.533582,0.498890,-0.589545,0.108213,-0.531844,-0.013137,0.414412,-0.430338,-0.424169,0.790411,0.168635,-0.521934,-0.237520,-0.384883,-0.230229,-0.098971,0.216242,0.487150,-0.158891,0.226443,-0.961799,-0.086845,-0.222132,-0.610214,0.075542,-0.525195,-0.107804,-0.351154,-0.319601,-0.149249,-0.181413,0.086136,0.168193,-0.575879,0.759971,-1.135493,0.254496,0.743962,0.076810,-0.612482,0.172733,-0.278561,-0.046786,-0.375112,-0.004527,0.297818,0.143009,0.439570,0.061139,0.273713,0.257944,-0.075717,-0.890109,0.834450', '26759820', '26759819', '1793491', '6844861');
