INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30274839', '丧尸未逝', '喜剧', '电影故事发生在寂静的小镇森特维尔，有些事情不太对劲。月亮又大又低地挂在天空中，白天的时间变得不可预测，动物开始表现出不寻常的行为。没人知道原因。新闻报道是可怕的，科学家们对此感到担忧。但没有人预见到，人们很快就会迎来最奇怪、最危险的后果：死人不会死——他们从坟墓里爬出来，野蛮地攻击活人，并大肆享用——镇上的居民必须为生存而战。', '科洛·塞维尼', '吉姆·贾木许', 5.7, 15690, 'tt8695030', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2552413094.jpg', 7.8, 25.4, 44.5, 17.5, 4.8, '0.256064,-0.233164,-0.977527,0.291218,0.092973,0.351896,1.145258,-0.029815,-0.675366,-0.351136,0.339031,0.641559,-0.202172,-0.122077,-0.009113,-0.146449,-0.609419,-0.288892,-0.044576,-0.332108,-0.333496,-0.209651,0.025402,-0.837348,-0.072204,-0.296108,0.506751,0.591743,-0.476483,0.083561,-0.037434,0.276300,0.327383,0.810206,-0.286723,-0.239668,-0.238243,0.265772,0.180900,-0.067715,0.118293,-0.041090,-0.535150,0.352562,0.183500,0.407612,0.428362,-0.516591,-0.511789,-0.004638,0.253793,-0.396925,-0.100838,0.095530,0.531639,-0.387492,0.146251,0.109353,0.145293,0.183564,-0.146488,0.113794,-0.768667,0.310416,0.137026,0.648827,-0.236381,0.222787,-0.019368,-0.056282,0.084080,-0.358432,0.351071,0.072041,0.487210,0.513065,0.143658,-0.041303,-0.597197,-0.259994,0.982809,-0.055195,-0.470320,0.624904,-0.790484,-0.749297,-0.196532,-0.296721,-0.305946,0.050910,0.192036,0.087329,-0.493416,0.749071,-0.320098,0.285100,0.105116,-0.664579,-0.271533,-0.192836,-0.461249,-0.292290,0.061719,-0.436693,-0.219085,0.103119,-0.105368,-0.173079,0.608458,-0.856280,0.019037,0.486159,0.249181,-0.305062,0.552718,0.067725,-0.265058,-0.200333,-0.072329,0.121902,-0.183537,0.462233,0.084511,0.037003,0.046733,-0.253150,-0.218158,0.390614', '1296370', '3059036', '1294941', '4724373');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30276726', '爸，我一定行的', '剧情', '369（郑润奇 饰）是父亲李锦龙（郑鹏生 饰）拉扯大的，父亲最大的愿望，是369能考上大学，将来有个像样的生计，但369的成绩总是全校倒数前十。高二那年，369逃课被退学了，父亲的愿望泡汤，只能各种托关系，让儿子去学个一技之长，望他出社会能够独立。然而， 369做一样厌一样，混了七八年一事无成，被乡里人唱衰。最终，369决定逃离乡里，逃离每天被流言蜚语的日子，跑到深圳，做起了网络主播。父子俩的关系，在369一次次违背父亲的愿望中，走向了决裂。', '郑润奇', '蓝鸿春', 6.3, 7254, 'tt8901722', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2530908793.jpg', 7.3, 20.4, 37, 19.8, 15.5, '0.145457,-0.036287,-0.466485,0.344106,-0.443386,-0.314418,0.033649,0.116589,-0.744872,-0.061348,-0.309836,0.779494,-0.138117,0.662904,-0.079732,-0.373809,0.282094,-0.798887,0.191553,-0.439469,-0.052775,-0.478831,0.090568,-0.008669,-0.378134,-0.021743,0.745529,0.007442,-0.073221,0.130529,0.414472,-0.065832,0.297521,0.071132,-0.527373,-0.174111,-0.164560,0.209590,-0.159237,0.408271,0.215735,-0.212244,-0.003034,-0.206148,0.248867,0.205872,0.626699,0.149593,0.112719,-0.004833,0.575787,-0.332210,-0.383273,0.478112,0.326221,0.120384,-0.008013,0.372702,-0.147965,0.033105,0.026080,-0.281685,-0.517693,-0.103472,0.199230,-0.036255,-0.998888,0.336348,0.199914,-0.157911,0.141328,-0.406582,0.294784,0.310281,0.229486,0.700339,-0.408050,0.407005,-0.571862,0.346343,0.865032,-0.442670,-0.192277,0.195231,-0.230150,-0.001499,0.157290,-0.606714,-0.347836,-0.024989,0.074836,-0.032906,-0.368645,0.189190,-0.340574,-0.143831,-0.316725,-0.182685,0.008854,-0.518066,-0.193795,-0.261429,0.067877,-0.182417,-0.263662,0.357421,0.015557,-0.676408,0.743192,-0.931112,-0.068945,0.545270,0.459385,-0.700181,0.835827,0.313926,0.403958,0.020233,0.284901,0.254843,-0.209568,0.468908,-0.187260,0.074589,0.028404,-0.477591,-0.145133,0.613272', '1877596', '2124718', '35048413', '1299062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30279170', '倒数时刻', '剧情', '设定在1990年，主角为加菲饰演的Jon，一个年轻、雄心勃勃的音乐剧作曲家。他在纽约一边当侍者，一边写一部叫《Superbia》的音乐剧，希望能平步青云，开启事业。但他从女友Susan那里感受到了压力，对方已经厌倦了任男友的职业前途牵制自己的人生；同时，Jon的室友Michael也放弃了创作梦想，做了一份高收入的广告业工作。快30岁的Jon非常焦虑：自己的梦想是否值得继续拼搏？', '安德鲁·加菲尔德', '林-曼努尔·米兰达', 8.2, 58884, 'tt8721424', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2690712224.jpg', 0.5, 2.5, 19.3, 43.3, 34.4, '-0.122964,0.094496,-0.462654,0.825159,-0.298816,-0.454337,0.455711,0.240288,-0.141567,-0.222620,0.317409,0.886284,0.098918,0.474346,0.403515,-0.147475,-0.144554,-0.871578,0.057199,-0.012855,-0.263038,-0.202854,-0.456869,-0.337731,-0.417135,-0.298431,0.932489,0.182816,-0.126494,0.157071,0.487683,-0.171220,0.177257,0.412653,-0.226003,-0.084156,0.262934,0.114032,-0.291108,0.410194,0.152810,-0.298067,-0.157727,0.080463,-0.040399,0.188732,0.741842,-0.001910,-0.262341,0.205847,0.705095,-0.179348,-0.012669,-0.107073,0.006780,0.159149,0.020369,-0.055114,-0.045583,-0.029206,-0.146509,-0.319190,-1.355399,-0.374841,-0.004920,0.095479,-0.610370,0.487765,-0.205732,0.026165,0.256948,-0.315822,-0.042283,0.286255,0.125704,0.596942,-0.453701,0.341099,-0.420393,0.603001,0.493123,0.010131,-0.087367,0.691845,-0.313546,-0.341291,-0.349617,-0.202902,-0.829044,-0.191718,0.236200,0.180791,-0.052827,-0.060077,-0.376871,0.050840,-0.006196,-0.217722,0.093518,-0.628637,0.081172,-0.228259,-0.169334,-0.193273,0.052729,-0.089386,0.176394,-0.660962,1.102384,-0.677870,0.015484,0.791996,0.108121,-0.663949,0.973866,0.369131,0.145186,-0.347418,-0.002059,0.242160,-0.406241,0.242097,0.215647,0.337565,-0.055785,-0.343963,-0.587855,0.766865', '27602116', '25880986', '30163500', '26315728');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30279836', '第十一回', '剧情', '30年前一桩杀人案，被市话剧团拿来改编成舞台剧，马福礼（陈建斌 饰）作为杀人案的当事人，旧事重提让他的生活再起波澜。马福礼一边忙着和话剧团导演胡昆汀（大鹏 饰）纠缠掰理，一边找律师翻案寻求真相还自己清白，还要忙着调和妻子金财铃（周迅 饰）和女儿金多多（窦靖童 饰）剑拔弩张的关系，生活给了他多记重锤……时隔多年，马福礼能否重新翻案？真相到底有几个？人生如戏，请君入席。', '陈建斌', '陈建斌', 7.2, 225345, 'tt10097436', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2637603645.jpg', 1, 5.9, 35, 46.8, 11.4, '-0.141608,-0.107956,-0.104738,0.508005,0.000731,-0.290021,0.444091,0.339735,0.022437,-0.370850,0.201398,0.503575,-0.089806,0.213647,0.269769,-0.115713,-0.465976,-0.830976,0.404765,0.387009,-0.099839,-0.321331,-0.041162,-0.119751,-0.268014,0.274581,0.096510,-0.074110,-0.019934,0.150250,0.521328,0.108940,-0.372490,0.003459,-0.179333,0.318198,-0.115315,0.208648,-0.679070,-0.027129,0.389738,-0.276694,-0.130265,-0.011854,0.254714,0.008595,0.442420,-0.070065,0.086786,0.063413,0.227689,-0.247535,0.426673,-0.122905,0.074495,0.220072,0.202652,0.382927,-0.205474,-0.068586,0.233777,-0.292104,-0.320570,0.164886,0.243191,0.215465,-0.553751,0.143105,-0.158211,0.242173,0.020542,0.018225,-0.076433,0.548847,0.380263,0.206599,-0.178054,0.171270,-0.593642,0.683278,0.411231,0.428644,0.253745,0.084998,0.044020,-0.222236,0.017542,0.035931,-0.245088,-0.097384,0.297760,-0.155375,0.080637,0.223121,-0.252682,-0.166875,-0.206282,0.277605,0.162469,-0.504882,0.330914,-0.302230,-0.100437,-0.225477,-0.213465,-0.135249,0.310359,-0.344895,0.332300,0.011316,-0.079102,0.220381,0.143857,-0.573473,0.375098,0.271578,0.354457,-0.322495,0.303097,-0.154384,-0.220618,0.316425,0.339574,0.115769,-0.004853,0.000926,-0.325621,-0.030566', '1299790', '1890558', '1301982', '4301278');
