INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30283179', '撞死了一只羊', '剧情', '司机金巴在路上撞死了一只羊，决意超度此羊；杀手金巴即将找到杀父仇人，准备报仇雪恨。阴差阳错，杀手金巴搭上了司机金巴的卡车。于是，两个叫金巴的男人的命运便神秘地联系在了一起，一段惊心动魄的旅程开始……', '金巴', '万玛才旦', 7.1, 53756, 'tt8836292', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2550800623.jpg', 1, 4.5, 39.8, 46.3, 8.3, '0.238123,-0.097671,-0.467589,0.378219,-0.253642,-0.564511,0.583985,0.494274,-0.204182,0.200306,0.386733,0.491027,0.021311,0.485652,0.763722,0.140151,-0.465009,-0.679094,0.111272,-0.075402,-0.442437,-0.214095,-0.028551,-0.389113,0.177379,0.037350,0.530200,-0.071695,0.189799,0.409907,0.280876,-0.018636,-0.554366,0.215116,-0.760180,0.004031,0.228023,-0.157253,-0.317151,-0.131965,-0.269327,-0.335509,0.265653,-0.107945,-0.402263,0.270109,0.479842,-0.218294,-0.005684,-0.181348,-0.035135,-0.175245,0.304030,-0.064256,0.392055,0.177884,-0.099085,0.142824,-0.008409,-0.441566,0.207023,0.018990,-0.456262,0.037293,-0.351736,-0.035195,-0.762543,0.263011,0.108398,0.359467,0.205927,-0.399316,0.281242,0.185651,0.409086,0.256751,0.237644,0.025301,-0.241382,0.215076,0.853573,-0.283878,0.493953,0.465579,0.352799,-0.172024,0.056057,0.312979,-0.273520,-0.261918,0.927133,-0.098867,-0.543679,0.091036,-0.616333,-0.312265,-0.646920,0.289090,-0.307582,-0.327941,0.045870,-0.305758,0.110555,-0.084860,0.104359,0.460231,0.225351,-0.008778,0.464732,-0.182637,0.409752,0.882849,-0.043649,-0.218597,0.418822,-0.141203,0.171307,-0.233974,0.416349,0.034282,-0.002312,0.579392,0.428009,0.391880,-0.390504,0.297307,-0.436511,0.326512', '1292533', '1303462', '1316560', '27069070');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30283209', '与我跳舞', '喜剧', '职场OL铃木静香（三吉彩花 饰）在日本一流公司任职。某一天，她意外地被一位催眠师催眠，得了一个连医生都检查不出来的“怪病”：无论何时何地，每当听到音乐响起，就会不由自主地唱歌跳舞。这个“怪病”给静香的工作和生活都带来了极大困扰，她找到了催眠师前助理斋藤千绘（八城优 饰），一起踏上“治病”之旅。随之，一系列荒诞搞笑的故事就此展开。', '三吉彩花', '矢口史靖', 6.6, 8857, 'tt9529640', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2629952366.jpg', 1.1, 10.3, 49.9, 33.6, 5, '0.098860,-0.086033,-0.289443,0.454539,-0.011920,-0.170195,0.512465,0.015645,-0.305988,-0.629506,0.215633,0.596161,-0.300543,0.232081,0.397094,0.121188,-0.191867,-0.692234,0.092482,0.150618,-0.390579,-0.302924,0.090256,-0.313621,-0.094655,-0.272858,0.315578,-0.073858,-0.547210,0.452910,0.147340,0.386309,0.085107,0.268333,-0.213267,0.343549,0.256390,-0.042261,0.103387,0.148173,0.127612,-0.438076,0.124563,0.188311,-0.062752,0.045446,0.492283,0.061383,-0.461519,0.035217,0.543637,-0.147681,-0.091698,0.060354,0.187383,0.311836,0.210841,0.153986,-0.392698,0.106544,-0.002868,0.165109,-0.747810,0.016230,0.214872,0.323276,-0.316993,0.097382,0.205619,0.077683,0.175630,-0.253669,0.217366,0.359055,0.524551,0.546965,-0.315225,0.372930,-0.324962,0.428710,0.657729,-0.148445,-0.159383,0.390608,-0.191917,-0.323203,0.169070,-0.072286,-0.316297,0.141392,-0.087611,0.015696,-0.084667,0.127694,-0.228706,-0.150614,-0.161058,-0.351538,0.003965,-0.247453,0.073338,-0.686611,0.157582,-0.068957,-0.579148,0.289185,0.024411,-0.282917,0.930693,-0.782626,0.235120,0.666957,-0.011933,-0.256456,0.332220,0.149169,0.067835,0.048976,0.160161,0.098645,-0.140800,0.570747,0.222985,0.632199,0.117717,0.014425,-0.491500,0.204888', '27602116', '3811356', '24284209', '1920765');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30283308', '阿浪的远方', '喜剧', '电影《阿浪的远方》讲述的是酷爱诗词的阿浪毕业后在一所中学任职语文老师，因为在中学不能发挥他的诗学天赋，所以他毅然决然的怀着梦想告别喧嚣的城市，来到偏远的二郎山小学任教，在这所只有16个学生1个校长的小学里， 李阿浪开始实施他的“诗学栽培”计划。', '周子龙', '宋媚', 7, 3225, '', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2531097433.jpg', 2.7, 13.2, 32.9, 33.8, 17.4, '0.622264,-0.207784,-0.802915,1.097806,-0.276827,-0.341083,0.249696,-0.009136,-0.420954,-0.487005,0.303125,0.804565,0.115692,0.942301,0.062881,-0.205424,-0.219219,-0.640887,0.154367,-0.651945,-0.130103,-0.635921,0.068738,0.053968,-0.089960,-0.308924,0.888297,0.196158,-0.513832,0.515872,-0.242268,-0.099979,0.368080,0.064973,-0.397340,-0.092932,0.141458,0.302186,-0.016628,0.175807,0.216414,-0.145016,-0.257521,-0.223066,0.325722,0.138441,1.062827,0.245407,-0.150048,0.117621,0.759301,-0.258313,-0.151703,0.253734,0.565055,0.165374,0.037302,0.096892,-0.078608,0.162157,-0.621800,-0.588689,-0.445018,-0.327407,0.158046,0.109123,-0.800441,0.910421,0.379921,-0.231029,0.220363,-0.351058,-0.124158,0.249121,-0.061574,0.825998,-0.197830,0.276601,-0.283186,0.421009,0.685772,-0.513966,-0.274665,0.355640,-0.100478,-0.563798,0.225732,0.024244,-0.532022,0.042421,-0.115178,-0.253919,-0.312749,-0.067301,-0.403566,-0.123499,0.237542,-0.132375,0.198805,-0.391343,-0.318703,-0.566134,0.038289,-0.251185,-0.195760,-0.191765,-0.050988,-0.454968,1.242603,-1.359994,0.108429,0.413613,0.259304,-0.383517,0.914270,0.132481,0.250832,-0.231056,-0.041174,0.406437,-0.188701,0.883085,-0.237044,0.716145,0.144386,-0.672895,-0.598447,0.866697', '25922902', '1826173', '26259677', '26219652');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30283526', '塔巴德', '剧情', '20世纪初，印度有一条名叫Tumbbad的小村庄，Vinayak就住在村庄的郊外，他是村长不承认的私生子，痴迷于神话中一个祖传宝藏。他的曾祖母是一个被诅咒沉睡千年的女巫，Vinayak认为宝藏的秘密就藏在她身上。经过与曾祖母的对质，Vinayak最终直面宝藏的守护者邪恶的堕落之神。最初的几枚金币迅速升级变成一种不计后果，跨越几个世纪，永恒不灭的渴望，倘若Vinayak如愿以偿，这种渴望将变成一种会延续至下一代的魔咒。', '索姆·沙', '拉希·阿尼尔·巴夫', 7.5, 13706, 'tt8239946', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2532668828.jpg', 0.9, 3.7, 31.1, 46.7, 17.6, '0.180522,0.358082,-0.594880,0.859598,-0.429303,0.157199,0.836874,-0.428188,-0.352953,-0.208074,0.367745,0.990089,-0.038149,0.238934,0.038757,0.195128,0.232348,-0.328998,-0.203570,-0.353229,-0.222774,-0.371958,-0.761279,0.063204,-0.292445,-0.299260,0.981310,0.324819,-0.390782,-0.013949,0.193867,0.488899,-0.152918,0.140575,-0.766488,-0.191423,0.006839,0.011481,-0.054407,0.228045,-0.219105,-0.005503,0.301879,0.283900,-0.366775,-0.065485,0.577851,-0.575204,-0.068419,-0.111054,0.497748,-0.159718,-0.451441,0.190809,0.438922,0.023763,-0.071936,0.250488,-0.198823,-0.243102,0.151438,-0.127035,-1.189734,-0.322545,0.116511,0.338654,-0.491174,0.285998,0.261722,-0.136455,0.150449,-0.435260,0.369526,0.176891,0.133177,0.705993,-0.321718,-0.218142,-0.629066,0.289791,0.671170,-0.478247,-0.434059,0.274889,-0.139167,-0.539711,0.073948,-0.141649,-0.688975,-0.112432,0.411766,0.106845,-0.309363,0.418152,-0.894020,0.127783,-0.493147,-0.009627,0.339810,-0.481376,-0.322059,-0.109364,-0.329016,-0.065344,0.018407,0.323029,0.166061,-0.485089,0.792278,-0.752011,0.651955,0.636088,0.279205,-0.377508,0.725771,-0.022855,-0.074775,-0.385682,0.208710,0.675560,0.109298,0.231670,-0.095604,0.363878,0.023556,0.348993,-0.279816,0.803083', '1308784', '1308585', '26667010', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30284119', '宅男腐女恋爱真难', '喜剧', '桃瀨成海是一個深藏腐女屬性的OL，不過在情場上十分失意。而二藤宏嵩是桃瀨的青梅竹馬，雖然是個徹頭徹尾的死宅，但是長著一副英俊的面孔帶著酷冷的形象。在桃瀨情場失意時作為青梅竹馬的二藤迅速拉近了與桃瀨的感情距離，一臉淡然的告白之後正式交往...', '高畑充希', '福田雄一', 5, 6598, 'tt9018612', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2575765698.jpg', 12.9, 38.5, 36.3, 8.5, 3.8, '0.568682,-0.022248,-0.598933,0.715577,-0.306699,-0.581993,0.920497,0.324748,-0.191434,0.173396,0.437919,0.726383,-0.328077,0.554772,0.198539,-0.108300,0.129478,-0.909958,-0.742432,-0.053611,0.249855,-0.587809,-0.110370,0.617629,-0.174782,-0.485674,0.969454,-0.133875,0.045953,0.763597,0.374438,0.165446,-0.192453,0.669990,-0.329097,-0.177160,-0.385394,-0.215485,-0.266817,-0.085894,-0.052861,-0.473170,-0.073795,0.280647,-0.180234,0.593087,0.937692,-0.038767,-0.647486,0.609218,0.828618,-0.342541,-0.317524,0.204587,0.179978,-0.220963,-0.022718,-0.082253,-0.070471,-0.197991,0.073660,0.047403,-0.378960,0.108285,-0.205620,0.710327,-0.679722,0.911016,0.328991,-0.067258,0.231220,-0.288855,0.178496,-0.087118,-0.009060,0.705880,-0.032236,0.531379,-0.585016,0.080504,0.330283,0.685992,-0.409562,0.837190,-0.391168,-0.435048,0.126474,-0.423981,-0.715400,-0.456731,0.133289,-0.142586,-0.128199,0.400769,-0.998316,0.034311,-0.100372,0.515956,0.090872,-0.358872,-0.167947,-0.518705,-0.881662,-1.185728,-0.609515,-0.185208,0.019197,-0.500674,0.816962,-1.388116,0.061774,0.457729,0.050671,-0.265039,0.752558,0.669564,-0.452663,0.145100,-0.109338,0.539778,-0.121538,0.140239,-0.100657,0.682916,-0.192205,-0.222281,-0.644220,0.732904', '24839498', '26354526', '1390020', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30284141', '晴雅集', '爱情', '天都城内频频出现怪象，法师们从各方赶来，试图找到真相。阴阳师晴明（赵又廷 饰）在探寻真相的过程中，与武士博雅（邓伦 饰）、法师泷夜（春夏 饰）、鹤守月（汪铎 饰）相识，四人决定联手展开调查。深宫内，公主（王子文 饰）背负着巨大秘密，深陷这场迷案中...却未曾料到，这背 后暗藏一段哀伤的往事。一场危机悄然来临，在紧急关头，有人为知己、有人为心上人、有人为世间安宁，大家为了守护心中所爱，拼死一战……', '赵又廷', '郭敬明', 5, 197105, 'tt11454718', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2622484010.jpg', 20.3, 29.5, 33.7, 11.6, 5, '-0.357995,0.147729,-0.649914,0.141205,0.498696,0.302072,0.472443,-0.456371,-0.791871,-0.500514,0.504814,0.306218,-0.402091,0.008719,0.350022,-0.284562,-0.438091,-0.721438,0.162320,-0.366871,-0.087416,-0.017591,-0.216706,-0.149083,-0.372427,-0.334958,0.766341,0.760041,0.159500,0.301603,0.087690,0.490789,-0.748628,0.478181,0.389357,-0.233406,0.014172,-0.010274,-0.609799,0.230928,-0.177760,-0.278057,-0.619378,0.232045,-0.177765,0.095613,0.618977,-0.650693,0.075117,0.001681,0.074768,-0.251136,0.129614,0.363876,0.378591,0.154603,0.273521,0.478959,-0.169718,-0.110331,-0.093597,-0.139997,-0.367111,0.193657,0.221970,0.164317,-0.184439,-0.114169,-0.311996,0.164113,0.215478,-0.340960,0.082285,0.407052,0.771109,-0.131349,-0.398181,-0.060837,-0.182138,0.142113,0.937651,-0.002055,0.115008,-0.073391,0.243409,-0.309611,-0.169331,-0.012755,-0.341168,0.129724,0.191114,0.270966,0.134499,0.623695,-0.310109,-0.037806,-0.512825,0.180513,0.160203,-0.227277,-0.362817,-0.255722,-0.148783,0.141391,-0.001285,0.327260,0.368586,-0.158343,0.445133,-0.657376,0.479223,0.153595,0.112327,-0.221413,0.451542,-0.044652,0.178319,-0.242794,-0.282639,0.225205,-0.101033,0.011544,-0.164209,-0.107939,-0.058180,0.021295,-0.230266,-0.271081', '26850330', '1307023', '1433736', '1306021');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30286712', '蝙蝠侠：缄默', '动作', '影片改编自同名漫画，原著漫画讲述一个神秘的跟踪者名叫“缄默”，他似乎打算从远处暗杀蝙蝠侠。故事中有许多客串角色，其中包含了大量的蝙蝠侠反派，还有多位蝙蝠家族的成员以及和蝙蝠侠的老战友，超人。它还探索了蝙蝠侠和猫女之间的暧昧情愫。', '杰森·奥玛拉', '贾斯汀·科普兰', 6.3, 6611, 'tt8752440', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2557007107.jpg', 3.8, 14.3, 52.9, 21.6, 7.4, '0.360270,-0.242517,-0.349154,0.879840,0.489233,0.073250,0.986273,-0.049767,-0.341515,-0.485020,0.262747,0.784318,-0.206815,0.054582,0.135009,-0.275140,-0.595442,-0.600352,-0.507790,-0.038089,-0.131006,-0.244856,-0.559343,-0.089812,-0.014849,-0.426395,0.802346,-0.061358,-0.610813,0.233883,0.462843,0.426613,-0.834172,-0.015062,-0.181754,0.130751,0.429175,0.160082,-0.188019,0.065425,-0.156645,0.003004,0.040104,-0.146069,-0.455008,0.465971,0.743285,-0.281396,-0.053112,-0.000115,0.293958,-0.024116,-0.197248,-0.265193,0.446696,0.005062,0.549435,0.240145,0.607266,-0.017566,-0.464171,-0.013419,-1.114079,-0.161360,0.242143,0.586303,-0.116938,0.175590,0.139931,0.195723,0.537344,0.152521,-0.095876,-0.375798,0.553205,0.087509,0.204142,0.130766,-0.265627,0.582945,0.057885,0.037854,-0.259374,0.544531,-0.039627,-0.546378,-0.499350,0.182475,-0.347857,0.106014,0.539569,-0.073161,-0.273580,0.474428,-0.918960,0.107254,0.170198,0.075497,0.167642,-0.504263,-0.033076,-1.176997,-0.328627,-0.210909,0.318178,-0.164206,0.592336,-0.340854,1.084962,-0.523835,0.128110,0.756140,-0.261539,-0.517854,0.669075,-0.002981,-0.241266,-0.332678,0.082201,0.133963,0.146060,-0.054632,0.006316,0.425351,-0.170517,-0.299516,-0.321693,0.222424', '3318306', '1322847', '1293433', '26577354');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30288638', '仲夏夜惊魂', '恐怖', '丹妮（佛罗伦斯·珀 Florence Pugh 饰）的姐姐因为精神疾病而自杀，在死的时候还顺带着杀死了他们的双亲。这巨大的打击令丹妮患上了抑郁症。克里斯蒂安（杰克·莱诺 Jack Reynor 饰）是丹妮的男友，实际上，他早就决定和丹妮分手了，可是悲剧的发生和丹妮糟糕的状况让他不得不将自己的分手计划无限期的延后。克里斯蒂安和同学佩勒（维尔赫尔姆·布洛姆根 Vilhelm Blomgren 饰）、马克（威尔·保尔特 Will Poulter 饰）、乔什（威廉·杰克森·哈珀 William Jackson Harper 饰）决定一起前往佩勒的故乡——一座位于瑞典的偏僻小村庄，那里古老的文化和祭祀活动将成为他们毕业论文的题材，在克里斯蒂安的邀请下，丹妮也加入了这趟旅途。©豆瓣', '弗洛伦丝·皮尤', '阿里·艾斯特', 6.8, 68988, 'tt8772262', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2555805593.jpg', 3.5, 10.8, 41.3, 33, 11.4, '0.455141,-0.181840,-0.744703,0.471239,-0.055480,-0.309068,0.672916,0.278015,-0.356526,-0.226581,0.092344,0.965992,-0.223269,0.183485,0.290507,0.221592,-0.548001,-0.640869,0.198742,-0.153695,-0.426816,-0.888630,-0.249632,-0.324655,0.064563,-0.423018,0.441016,-0.057612,-0.129039,0.465796,0.285057,0.456557,0.143937,0.389292,-0.053135,0.163093,0.189529,-0.104974,-0.235238,0.244847,0.245758,-0.050926,0.009103,0.288848,0.162284,0.490998,0.533617,-0.388672,0.071009,0.089474,0.193761,-0.509727,0.116433,0.168894,0.297190,-0.259760,0.245596,0.289759,-0.371586,-0.186289,0.259536,-0.132065,-0.496987,0.220525,-0.042458,0.268941,-0.716336,0.599604,-0.268783,-0.084860,0.242162,-0.509931,0.240028,0.603607,0.190577,0.367905,-0.117632,-0.139070,-0.404908,0.001764,0.660127,0.076322,-0.187062,0.075867,-0.263813,-0.425004,-0.199761,-0.048891,-0.461814,-0.028110,0.450761,-0.125538,-0.161747,0.350580,-0.629195,-0.284047,-0.405706,-0.223752,-0.150769,-0.295435,0.085757,-0.705372,0.162544,-0.315538,-0.428039,-0.074228,0.023551,-0.175722,0.447532,-0.631245,0.405819,0.581520,0.408537,-0.346338,0.524370,0.044356,0.348557,0.013521,-0.050325,0.377817,-0.143730,0.219686,0.349376,0.484068,0.395635,-0.208095,-0.506142,0.620924', '1293145', '1309069', '3285622', '1895119');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30289194', '爆炸新闻', '剧情', '约翰·利特高(《王冠》)饰演福克斯新闻创始人之一、前董事长罗杰·艾尔斯，塞隆饰演前福克斯新闻主持人梅根·凯利，妮可饰演前主持人格雷琴·卡尔森，罗比饰演一个虚构角色、名叫Kayla Pospisil的助理制片人，珍妮饰演艾尔斯的律师Susan Estrich，马尔科姆·麦克道威尔(《发条橙》《罗马帝国艳情史》)饰演鲁伯特·默多克，布里盖特·伦迪·佩恩(《非典型少年》《缩小人生》)饰演Julia Clarke，丽芙·休森(《小镇滋味》《忽然七日》)饰演梅根·凯利的助手Lily，霍尔姆饰演主持人Martha MacCallum，是艾尔斯的捍卫者，加雷特饰演主持人Sean Hannity，一直将艾尔斯视为第二个父亲，称其为“美国最伟大爱国战士”之一。艾尔斯掌管福克斯新闻外，也是是共和党的风云人物，曾帮助选举了理查德·尼克松、罗纳德·里根和乔治·布什三个美国总统，也帮助发展了Sean Hannity、梅根·凯利、格雷琴·卡尔森等著名主持人的职业生涯。2016年，因被多名女性指控骚扰，艾尔斯被迫辞职，凯利和卡尔森在其中起到重要作用。新闻台尝试向凯利试压，强迫她出面支持艾尔斯，被她拒绝。', '查理兹·塞隆', '杰伊·罗奇', 7.2, 41345, 'tt6394270', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2571554907.jpg', 0.4, 3.7, 43.7, 40.6, 11.5, '-0.137865,-0.150199,-0.374470,0.548593,0.126160,-0.286029,0.509195,0.459778,-0.309977,-0.524872,0.101976,0.810430,-0.253836,0.077466,0.743241,0.152431,-0.627084,-0.488959,0.074402,0.081874,0.189836,-0.589366,-0.156072,-0.302243,-0.120835,-0.423851,0.461336,-0.529367,-0.125783,0.352863,0.661544,0.622794,0.019143,-0.107874,0.506756,0.234460,0.861137,-0.661178,-0.473556,0.517813,0.019725,0.146278,-0.081315,0.136277,0.122187,0.382056,0.029050,-0.172358,0.451411,-0.167131,0.357185,-0.304517,0.175886,-0.050754,0.425791,-0.103067,0.318619,0.333762,-0.116954,-0.255160,-0.012658,-0.225295,-0.627009,0.154001,-0.167586,0.418920,-0.309578,0.233638,-0.433061,0.032911,0.119596,-0.090595,0.086394,0.032322,0.175105,-0.051558,0.295757,0.277638,-0.017921,0.128839,0.104526,0.123066,-0.285844,0.243596,-0.036644,-0.308414,-0.172173,-0.163553,-0.581800,-0.006328,0.221703,-0.284873,0.438316,0.282628,-0.155007,-0.287191,-0.577915,-0.240070,0.252567,-0.006624,0.091115,-0.905405,-0.209204,0.058234,0.044761,-0.578018,-0.163506,-0.225639,0.697112,-0.448210,0.288277,0.527270,0.145740,-0.002708,0.600247,0.313213,0.412347,-0.296107,0.