INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30289828', '兔子暴力', '剧情', '故事发生在一座荒芜的南方小镇中，这里的环境因为重工业的无节制发展而遭到了严重的破坏，居民们接二连三的从这里搬走，可以想象，不久之后，这个小镇将成为一座废城。少女水青（李庚希 饰）自幼失去了母亲，在继母造成的阴霾之下长大，她唯一的愿望就是能够见一见未曾谋面的生母曲婷（万茜 饰）。在十七岁这一年，水青的梦想成真了，曲婷回到了小镇，重新参与进了水青的生活之中，带给了她久违的温暖和快乐。曲婷和水青的闺蜜们还一起组建了“青春兔子帮”，大家一起快乐的这段日子是水青生命中唯一一抹亮色，但这一抹亮色，却因为一个名叫老杜（黄觉 饰）的神秘男人的到来，而遭到了破坏。©豆瓣', '万茜', '申瑜', 5.8, 54947, 'tt10393440', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2675924254.jpg', 4.3, 24.7, 51, 17.1, 2.9, '0.203247,0.151655,-0.803472,0.684570,-0.237961,-0.203773,0.955077,0.040427,-0.670503,-0.184037,-0.009160,0.788109,-0.050149,0.538309,0.240957,0.179287,-0.081862,-0.509242,0.006551,-0.364960,-0.273954,-0.198167,-0.211592,-0.098600,-0.144731,-0.363753,0.813732,0.534251,-0.044588,0.622678,0.056384,0.040114,-0.112303,0.521342,-0.324014,0.114734,-0.060161,0.126567,-0.236049,0.370834,-0.045305,-0.300068,-0.008394,0.252525,-0.144165,0.211361,0.842062,-0.174739,-0.310006,-0.163402,0.446717,-0.252551,-0.127313,0.104373,0.233401,-0.141825,0.076074,0.122430,-0.436463,-0.066279,0.118944,-0.357467,-0.671848,0.022024,0.057041,0.051994,-0.556163,0.494997,0.246526,-0.322373,0.156479,-0.215565,0.543365,0.540642,0.221450,0.456913,-0.482829,0.196872,-0.559502,0.290730,0.818199,-0.283838,-0.257043,0.554514,-0.434791,-0.236840,-0.098934,-0.126951,-0.414920,0.143052,0.160800,0.183332,-0.380305,0.332617,-0.765514,0.208317,-0.151654,-0.266817,0.101407,-0.379274,-0.322221,-0.564449,-0.297374,-0.498613,-0.330651,0.129566,-0.131763,-0.329055,0.654772,-0.913127,0.390397,0.266630,0.489880,-0.387761,0.695193,0.075239,0.453028,0.069210,0.173776,0.357378,-0.098181,0.402975,0.152104,0.320147,-0.309377,-0.027296,-0.455450,0.572865', '3055049', '21619567', '25721544', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30289869', '艾娃', '动作', '顶尖杀手艾娃效忠于一个神祕组织，在全球各地执行高价值目标的暗杀行动。然而，一次出了差错的行动，让艾娃身陷生死危机。面对各路杀手铺天盖地的追杀，无路可退的艾娃唯有杀出血路，才有活下去的机会…', '杰西卡·查斯坦', '泰特·泰勒', 4.7, 15888, 'tt8784956', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2610576528.jpg', 13.4, 47.1, 33.2, 5.3, 1.1, '-0.283784,0.063152,-0.782767,0.609486,0.006156,-0.085994,0.405013,-0.191637,-0.278854,-0.028533,0.665756,0.462007,0.365837,-0.361312,0.470655,-0.730785,0.358637,-0.941740,0.097633,-0.232293,-0.377446,-0.199426,-0.701028,-0.539252,0.052688,-0.272461,0.966120,0.594819,-0.517575,0.285030,0.428066,0.400559,-0.196649,0.571957,-0.025749,-0.699047,0.232854,-0.104938,-0.460798,0.711832,-0.602591,-0.458112,-0.426071,0.489639,-0.198834,0.529019,0.488674,-0.619273,-0.144415,0.095003,0.359561,-0.890941,-0.223700,-0.039118,0.517612,-0.253682,-0.072823,0.052886,0.139554,-0.056032,-0.211351,-0.141341,-1.493375,-0.408006,0.256456,0.148644,-0.889794,-0.105080,-0.313623,-0.023625,-0.268145,-0.319122,-0.137902,0.276194,0.418947,-0.024839,-0.252330,0.243319,-0.453423,-0.245132,0.934747,-0.312285,-0.428480,-0.532246,0.151103,-0.508872,-0.011229,-0.804683,-0.183137,-0.115909,0.642436,-0.159075,-0.237622,0.044132,-0.468841,0.005033,-0.601028,-0.091197,-0.210033,-0.297449,-0.060438,-0.652556,-0.117657,0.336361,-0.418128,0.502544,0.067545,-0.094511,0.822225,-0.645354,0.176467,0.814819,0.280666,-0.822427,0.682568,0.227639,0.198190,-0.298137,0.247631,0.202475,0.245129,0.487523,0.007368,-0.293599,-0.241969,0.015413,-0.177641,-0.031035', '30163500', '26678784', '1293605', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30290068', 'DC萌宠特遣队', '喜剧', '超狗小氪和超人是形影不离的好朋友。他们共享超能力，在大都会并肩作战打击犯罪。但是当超人和正义联盟的其他成员被绑架时，小氪必须要说服一群收容所里的小动物们，包括猎犬王牌、小胖猪PB、乌龟默顿、松鼠奇奇组成萌宠特遣队，帮助他们掌握刚获得的超能力，一起拯救超级英雄。', '道恩·强森', '贾里德·斯特恩', 7.2, 9502, 'tt8912936', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2741687784.jpg', 0.8, 5.4, 42.3, 38.1, 13.4, '0.259156,-0.245000,-0.351172,0.338838,-0.132178,-0.221802,0.275623,-0.123966,-0.105062,-0.201373,0.288640,0.858483,0.128891,0.397326,-0.170762,-0.352456,-0.398772,-0.592234,-0.176223,0.026754,-0.338079,-0.441429,-0.641384,0.004040,-0.055371,-0.301636,0.725100,-0.638148,-0.218354,0.520085,0.328366,-0.055574,-0.490350,-0.349464,-0.260831,-0.158193,0.504740,-0.121933,-0.465545,0.007021,-0.419266,0.728065,0.028933,-0.176032,0.289102,-0.158053,0.558439,-0.971814,0.237031,-0.848574,-0.163281,-0.319380,-0.132865,0.012185,0.173938,0.112831,0.594791,-0.070397,0.429169,0.140939,0.196836,-0.023701,-0.916821,-0.136039,0.237416,0.142950,-0.441228,-0.080071,0.328342,0.136524,0.811889,-0.166465,0.097416,0.173585,0.058439,0.542153,0.019897,0.514230,-0.757201,-0.053485,0.861382,-0.277577,-0.181801,-0.149632,0.177385,-0.348240,0.138002,-0.393645,-0.144272,-0.040784,0.054831,-0.119480,-0.348658,0.408104,-1.218629,0.273316,-0.039816,0.120021,-0.132731,-0.308044,0.226308,-0.837018,0.103451,-0.402138,0.122286,0.489081,0.354701,-0.348934,1.413390,-1.132624,0.215819,0.410645,0.407104,-0.573791,0.663123,0.074873,0.143352,-0.296628,0.016817,-0.346472,0.468242,0.473646,0.317339,0.189879,-0.035374,-0.349584,-0.411991,0.274596', '24284209', '1302661', '4181031', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30291500', '复活的鲁路修', '动画', '光和2年。世界以重组的超合众国为中心统一，讴歌着和平的日子。但和平却突然宣告结束。以面具男·零的身份随娜娜莉同行去难民营慰问的朱雀，被谜之Knightmare Frame打败，两人被带走了。奉修奈泽尔的密命潜入战士之国·吉尔克斯坦王国的卡莲、罗伊德、咲世子，遭到神秘的Geass使用者袭击。而被袭击者称作“前向主”的C.C.也在那里。以曾经连神圣布里塔尼亚帝国的大军都击溃过的无敌王国为舞台，人们所描绘的愿望，是希望还是绝望？知晓Geass之事的吉尔克斯坦王宫众人，以及C.C.的心思究竟是——。', '福山润', '谷口悟朗', 8.7, 11641, 'tt6344664', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2548230523.jpg', 1.1, 2.3, 12.2, 27.9, 56.5, '0.150740,0.249910,-0.555785,0.694010,0.210203,-0.193336,0.534062,0.027884,-0.345452,-0.253600,0.185719,0.555909,-0.018849,-0.100155,0.638442,0.145003,-0.261852,-0.627856,-0.323669,-0.256797,-0.185881,-0.411152,-0.267717,-0.272810,-0.176968,-0.685986,0.770137,0.043464,-0.154850,0.315657,0.316448,0.552498,-0.091578,0.399130,-0.065547,-0.199344,-0.012547,-0.226068,-0.452395,0.148470,-0.321969,-0.261244,-0.266298,0.407592,-0.265374,0.233035,0.668152,-0.685938,0.124104,-0.318537,0.296847,-0.493982,0.044885,0.000457,0.494989,-0.200498,0.182144,0.419240,0.204813,-0.182861,0.196332,-0.018711,-0.884740,-0.033572,0.307909,0.082003,-0.569523,0.523826,-0.224729,-0.156939,0.160080,-0.461797,0.421103,0.617927,0.098845,0.476013,-0.162039,-0.080263,-0.574063,0.124633,0.774228,0.063763,-0.490317,-0.234456,-0.041148,-0.530139,0.059266,-0.523645,-0.438627,0.052567,0.026952,0.065744,0.360940,0.574396,-0.850143,-0.296660,-0.745394,-0.522757,0.359021,-0.590366,0.057758,-0.702331,-0.217399,-0.171826,-0.171939,0.204977,0.283575,-0.017682,0.651438,-1.101375,0.345324,0.460547,0.488638,-0.555765,0.747356,0.104858,0.057876,-0.113640,-0.346886,0.182940,0.258778,0.449180,0.098272,0.286476,0.068088,-0.158444,-0.339282,0.424280', '1420088', '1308837', '2032339', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30291552', '影里', '剧情', '今野秋一（绫野刚 饰演）因为被公司调职，从大城市的东京来到岩手县盛冈市居住，人生地不熟的他，虽能与同事正常相处却总无法融入。直到他结识了同龄的日浅典博（松田龙平 饰演），才逐渐对这未知的土地卸下了心房。外表吊儿啷当的日浅，不仅留着一头凌乱的中长发，还常不听今野的劝导在公司偷抽烟。两人乍看个性不合，却在一夜把酒言欢，建立起深厚的友谊，结伴溯溪钓鱼甚或夜游。因为一些微不足道的小事而欢笑的日子，彷佛像是已然成熟却迟来的青春岁月，让今野内心也泛起了阵阵涟漪。某天，日浅突然下落不明，随着今野开始找寻他的踪迹，挚友底下截然不同的面貌才逐渐浮出水面：公司女同事表示曾借钱给日浅却无从追讨、断绝父子关系而不愿向警方提出协寻申请的冷淡家庭……究竟那个曾经一起度过许多美好时光的男人，是否为日浅真正的模样？行踪不明的他，现在又身处何方？', '绫野刚', '大友启史', 7.5, 8389, 'tt11362496', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2576851525.jpg', 0.7, 3.1, 32.5, 48.5, 15.2, '0.263664,0.177424,-0.703369,0.458180,-0.055940,-0.518725,0.577771,0.314414,-0.490626,-0.206514,-0.028902,0.526652,-0.041787,0.352877,0.139974,-0.010229,-0.197984,-0.726606,-0.088259,-0.119329,-0.257297,-0.129252,-0.316955,0.065972,-0.121744,-0.170993,0.592800,0.328364,-0.102376,0.599776,0.186312,0.226516,-0.341382,0.530835,-0.429190,-0.227309,-0.043483,0.449983,-0.127230,0.008763,0.043271,-0.243628,-0.235445,-0.098396,0.017030,0.652455,0.608027,-0.067463,-0.497238,0.033558,0.471478,-0.151428,-0.011064,0.203884,0.299994,0.164659,0.097110,0.275844,-0.494175,-0.053175,-0.061627,-0.033795,-0.425788,0.191901,0.108614,0.102070,-0.282528,0.456670,-0.004760,-0.393282,0.052993,-0.244074,0.007020,0.473571,-0.046441,0.404174,-0.259393,0.035708,-0.283155,0.224951,0.845662,0.377854,-0.388150,0.387994,-0.354783,-0.178006,-0.097466,-0.006359,-0.157892,-0.323669,0.207653,0.150483,-0.139107,0.331647,-0.504093,0.171097,-0.260908,-0.104326,0.053700,-0.283905,-0.170454,-0.301807,-0.504801,-0.597339,-0.108177,0.097229,0.259866,-0.034150,0.507376,-0.936420,0.237650,0.657266,0.139798,-0.341446,0.546236,0.230474,-0.184053,-0.320529,0.056111,0.116617,-0.048830,0.215462,0.026174,0.236833,-0.101936,-0.013870,-0.488262,0.239040', '35030151', '1301022', '1870682', '129