INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30292581', '再见，少年', '剧情', '影片讲述了千禧年发生在南方小镇上的一段曾经无限接近，却又渐行渐远的少年情谊。“好学生”黎菲（张子枫 饰）与“坏孩子”张辰浩（张宥浩 饰），各自经历了时代大潮下家庭的变迁，一起奋力而坚韧地成长。然而高考前的一场剧变，让青春笼上阴影，最终裹挟住了二人的命运。', '张子枫', '殷若昕', 4.3, 14964, 'tt10234650', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2676541622.jpg', 23.2, 47.7, 23.9, 4, 1.3, '0.243984,0.055838,-0.675246,0.639711,0.530824,-0.307390,0.714500,0.150439,-0.335443,0.004457,-0.004132,0.445550,-0.215763,0.273636,0.229402,-0.341823,-0.145641,-0.970099,-0.140132,-0.078565,-0.329405,-0.241930,-0.323614,0.340179,-0.107404,-0.246082,0.825596,0.462446,0.204643,0.672038,0.124286,-0.107670,-0.373177,0.340657,-0.092035,0.021094,-0.078110,0.475912,-0.487746,-0.027613,0.086067,-0.584532,-0.334855,-0.103623,-0.210369,0.260699,0.833072,-0.014586,-0.030043,-0.207088,0.422338,-0.113043,-0.203707,-0.000097,0.324829,0.349661,0.200736,0.242514,0.097195,-0.313491,-0.292408,-0.208007,-0.286516,0.210771,0.235180,-0.064012,-0.596481,0.718023,0.331833,0.043093,0.048850,-0.363060,-0.052988,0.247134,0.689283,0.398239,-0.306078,-0.014642,-0.214458,0.216453,0.768610,0.103159,-0.508576,0.356216,-0.568275,-0.128522,-0.465745,-0.132014,-0.791536,-0.060038,0.293831,0.334711,-0.454378,0.658476,-0.701126,0.181599,-0.455923,-0.056282,0.035067,-0.430378,-0.062227,-0.415963,-0.423432,-0.564993,-0.495940,0.099711,0.033225,-0.271501,0.676650,-0.387466,0.366972,0.448313,0.264011,-0.150674,0.477443,-0.022258,0.487652,0.089024,0.198765,0.488986,-0.574248,0.367626,0.142800,0.335996,-0.536394,0.186100,-0.448836,0.789049', '2365260', '1307146', '4202326', '1432699');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30292777', '阳光普照', '剧情', '平凡的一家人阿文（陈以文 饰）和琴姐（柯淑勤 饰）育有两个儿子，叛逆的小儿子阿和（巫建和 饰）与好友菜头（刘冠廷 饰）砍伤人进了少年辅育院，但阿和的女友小玉（吴岱凌 饰）却带着身孕来家里…琴姐不顾阿文反对，将小玉留下来照顾。此时，被砍伤者家属也来找阿文求取巨额赔偿，阿文受不了总是带来麻烦的小儿子，将所有希望都寄托在资优生大儿子阿豪（许光汉 饰）身上，却不知道温暖善良的阿豪心中也藏着不为人知的秘密…', '陈以文', '钟孟宏', 8.5, 307081, 'tt10883506', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2570235120.jpg', 0.2, 0.7, 10.4, 48.8, 39.9, '0.082627,-0.126999,-0.629804,0.443488,-0.207254,-0.342996,0.859663,0.041467,-0.370994,-0.298577,-0.068804,0.375474,0.198909,0.359194,0.069784,0.011571,-0.175541,-0.500074,-0.057505,-0.048098,-0.316701,-0.442755,-0.107803,-0.113601,-0.297998,-0.226349,0.210566,-0.178579,-0.051004,0.615872,0.527343,0.345221,-0.172988,0.521187,-0.214947,0.147739,-0.308232,0.076357,-0.030026,0.035372,0.314977,-0.094291,-0.036911,0.144292,0.348709,0.374804,0.772603,-0.153068,0.074093,-0.060362,0.032279,-0.081796,0.098703,0.139989,-0.048515,-0.000125,0.411479,0.199757,-0.269290,-0.007190,0.432246,-0.008411,-0.606086,-0.057680,0.531700,0.033149,-0.777670,0.358217,-0.180580,-0.141126,0.200275,-0.433391,0.360977,0.161204,0.004490,0.513514,-0.179874,0.264946,-0.477163,0.148968,0.448732,-0.322180,0.487232,-0.113962,-0.375141,-0.225238,0.087243,-0.083478,-0.640555,0.101067,0.207748,-0.008925,0.074662,0.095989,-0.315839,-0.078132,-0.037631,0.134424,0.015013,-0.750142,0.207763,-0.019467,-0.025012,-0.384731,-0.517985,0.365819,0.265177,-0.158466,0.789187,-0.469362,0.221209,0.263614,0.650953,-0.463551,0.680378,0.148267,0.263468,-0.461880,-0.172404,-0.130200,0.189708,-0.108414,0.439894,0.273288,-0.168502,-0.036334,-0.250704,-0.008901', '26348103', '21619567', '3111650', '1304309');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30293828', '中国合伙人2', '剧情', '影片讲述了从九十年代末到当下的近二十年期间，互联网行业在中国从发轫、发展到行业泡沫再到高速爆发行业成熟的过程。影片选取了三位有代表的行业人物，程序员楚振辉、秦磊和投资人徐顺之。影片围绕楚振辉、秦磊，并以徐顺之的视角展现了一个程序员向创业者的蜕变，讲述他们三人在互联网大潮中创业、守业以及行业升级的故事，表现了中国互联网人的中国精神和民族情怀。他们将成为新时代的中国合伙人，而中国互联网行业的创业热血正在继续生生不息。', '赵立新', '刘亚当', 4.1, 10296, 'tt9844650', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2541742368.jpg', 33.2, 38.4, 22.8, 3.8, 1.8, '0.084391,0.101340,-0.732106,0.664701,0.190583,-0.156066,0.260927,0.172298,-0.589707,0.052909,0.101106,0.767614,-0.330704,0.063023,0.289729,-0.383749,-0.006141,-0.855058,-0.096936,-0.120028,-0.068758,-0.115327,-0.076353,-0.349210,-0.380341,-0.301160,1.035196,-0.059279,-0.668400,0.057805,-0.254675,0.151051,-0.087910,0.356929,-0.010494,-0.181884,0.318459,0.016768,-0.707183,0.291265,0.000712,-0.387162,-0.165197,0.027013,-0.216386,0.122333,0.706057,0.101290,0.029261,-0.007949,0.736777,-0.229670,-0.271517,-0.408529,0.388897,0.230383,0.145624,0.433097,0.299292,-0.049749,-0.368085,-0.391208,-0.866473,-0.255584,0.024751,0.312042,-0.657252,0.223667,-0.028586,-0.250786,-0.149491,-0.527815,-0.037803,0.364600,0.559975,0.574324,-0.053427,0.286822,-0.535567,0.624917,0.275523,0.190395,-0.952301,0.776531,0.019967,-0.658796,-0.520942,-0.089947,-0.428873,-0.341616,0.461598,-0.013793,-0.261487,0.467127,-1.041165,0.242897,0.284378,-0.714135,0.492426,-0.214509,-0.098467,-0.888391,-0.478349,-0.502218,-0.036445,-0.158969,0.415057,-0.242701,1.276797,-0.714756,-0.215103,0.731406,0.142078,-0.776828,0.750192,-0.365088,0.119601,-0.469469,-0.074834,0.003266,-0.273654,0.335006,-0.377649,0.487866,-0.417483,-0.148179,-0.554643,0.525306', '27602116', '22265121', '25863940', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30294313', '舞女大盗', '剧情', '戴斯特尼（康斯坦斯·吴 Constance Wu 饰）是一名单身母亲，独自拉扯着年幼的孩子，日子过得非常的辛苦。无奈之下，她只得来到一家脱衣舞俱乐部寻找一份高薪的工作来供养家庭，就这样，戴斯特尼成为了一名脱衣舞女。戴斯特尼所在的俱乐部是面向高端白领男性开放的，在这里，她邂逅了同行拉莫纳（詹妮弗·洛佩兹 Jennifer Lopez 饰），她是这里人气和地位最高的舞女。善良的拉莫纳在工作上给与了戴斯特尼很多帮助，两人之间很快就建立起了信任关系。经济危机的到来对娱乐业产生了重大的影响，为了挽救岌岌可危的生意，拉莫纳带着戴斯特尼一行人开始了她们的圈钱计划。©豆瓣', '吴恬敏', '劳伦·斯卡法莉娅', 6.3, 19473, 'tt5503686', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2568198146.jpg', 1.6, 13, 57.4, 22.7, 5.3, '0.139331,-0.130886,-0.416657,0.454398,-0.392275,-0.211340,0.520334,0.351942,-0.518029,-0.259310,0.176426,0.635914,-0.052860,0.231727,0.433012,0.053724,-0.396824,-0.431731,0.185966,-0.206463,-0.092645,-0.401389,-0.427940,-0.320664,-0.316687,-0.327323,0.352035,-0.104364,-0.191994,0.527476,0.427109,0.220315,0.068883,0.253906,-0.473061,0.004883,0.183928,-0.051343,-0.262844,0.354936,-0.098119,-0.141333,0.169805,0.260135,0.417621,0.290776,0.578956,-0.042023,0.135472,-0.091344,0.412943,-0.282891,0.159575,0.082716,0.504587,0.024767,-0.022774,0.033246,-0.569250,0.024045,0.038379,-0.495825,-0.669423,0.053911,0.323174,0.213113,-0.785985,0.496109,-0.254721,-0.247433,0.000603,-0.213157,-0.003314,0.468976,0.186169,0.423337,0.250640,0.377397,-0.541530,-0.000922,0.651017,-0.006190,0.005923,0.259168,-0.573472,-0.435461,-0.164907,-0.189750,-0.505354,-0.440381,0.237694,-0.216171,0.254282,0.125574,-0.511199,-0.042019,-0.095118,-0.202616,0.316389,-0.434155,0.186531,-0.624069,-0.057312,-0.636613,-0.302335,0.168134,0.048596,-0.311948,0.594833,-0.574332,0.225147,0.370599,0.513458,-0.593067,0.869412,0.111284,0.593181,-0.007043,-0.044634,0.278473,0.027532,0.071058,0.126088,0.166687,-0.129868,-0.159440,0.017653,0.480855', '3055049', '27060077', '1917323', '3236520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30294963', '怪胎', '剧情', '故事发生在一个虚构的科幻世界之中，在这里，拥有着超能力的异能人和普通人生活在一起，曾经，因为超能力被滥用至失控，人类经受了惨痛的教训，因此，在创伤渐渐恢复之后，这些超能力者便沦为了遭受政府严密监控的“二等公民”，处处受人歧视，甚至遭到了军方追捕，被捉到的人将会被送往隔离 区隔离。克洛伊（莱克西•科尔克Lexy Kolker 饰）是一个单纯善良的孩子，和父亲（埃米尔•赫斯基Emile Hirsch 饰）过着相依为命的生活。平日里，父亲严禁克洛伊踏出家门一步仿佛屋外的世界充满了危险。一天，在冰淇淋的诱惑下，克洛伊偷偷的出门了，并且意外的得知，自己的母亲或许依然活在世上。©豆瓣', '埃米尔·赫斯基', '扎克·利波夫斯基', 7.1, 10433, 'tt8781414', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2562158193.jpg', 1.6, 6.6, 40.1, 38.6, 13.2, '0.420776,0.197560,-0.833421,0.576397,-0.302323,0.016231,0.939558,0.200944,-0.670439,-0.137519,0.287608,0.791978,-0.104411,0.170124,0.210889,-0.135831,-0.240316,-0.568027,-0.182790,-0.355267,-0.488006,-0.353262,-0.323083,-0.253425,-0.199069,-0.780793,0.413018,0.163582,-0.393221,0.220705,-0.017268,0.354918,-0.254091,0.548421,-0.250841,0.171342,0.189784,-0.147672,-0.171266,0.242147,0.070362,-0.201134,0.103934,0.210271,-0.048122,0.110194,0.810791,-0.447143,-0.236550,-0.297945,0.418131,-0.170981,-0.066516,0.267396,0.374885,0.036648,0.017575,0.299928,-0.136619,0.230022,0.257061,0.011058,-0.766652,-0.225171,0.250116,0.036717,-0.731772,0.517177,0.042834,-0.071100,-0.059536,-0.230205,0.256562,0.257784,0.133814,0.596311,-0.166508,0.039569,-0.694068,0.101676,0.825335,-0.285165,-0.498840,0.139821,-0.380320,-0.306976,-0.240574,-0.408015,-0.756558,-0.106500,0.307447,0.006255,-0.470986,0.471289,-0.549028,0.212235,-0.174915,-0.197640,-0.183043,-0.428107,-0.215903,-0.555446,-0.031943,-0.308545,-0.370904,0.359201,-0.077850,-0.270605,0.606917,-0.799686,0.639875,0.737078,0.468628,-0.540118,0.529987,-0.052416,0.245847,0.007924,-0.073361,0.524131,0.347364,0.556109,0.250081,0.314005,-0.173206,0.146550,-0.297989,0.570823', '1307311', '21619567', '1866424', '1428054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30295905', '中国机长', '剧情', '根据2018年5月14日四川航空3U8633航班机组成功处置特情真实事件改编。机组执行航班任务时，在万米高空突遇驾驶舱风挡玻璃爆裂脱落、座舱释压的极端罕见险情，生死关头，他们临危不乱、果断应对、正确处置，确保了机上全部人员的生命安全，创造了世界民航史上的奇迹。', '张涵予', '刘伟强', 6.6, 703880, 'tt10218664', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2568258113.jpg', 2.8, 13.4, 44.7, 29.7, 9.4, '-0.137369,0.534750,-0.335290,0.095900,0.196856,0.572011,-0.292531,-0.112693,-0.088452,0.096536,0.673479,0.329890,-0.060989,-0.548158,0.408549,-0.095584,-0.582419,-0.525936,-0.017443,-0.273446,-0.854514,-0.536337,-0.272863,-0.471890,0.225558,-0.165874,0.728996,0.419027,0.157494,0.341371,-0.299418,0.089123,-0.359275,0.222118,-0.064453,-0.630998,0.014098,-0.120343,-0.050485,0.005078,-0.540570,-0.295289,0.199734,0.052001,0.018274,0.437518,0.884529,-0.266638,-0.344190,-0.255924,0.611442,-0.349113,0.094073,-0.476393,0.644946,0.207311,-0.402977,0.387441,0.121485,-0.198689,0.183354,-0.032827,-0.133643,-0.603068,-0.244031,-0.259034,-0.178378,-0.136051,-0.808157,0.326783,-0.081082,-0.254168,0.083985,0.319385,0.324597,0.348596,-0.497294,0.036146,-0.066311,0.384720,0.279773,-0.026179,-0.663519,-0.002147,0.108641,-0.594756,-0.313571,-0.523847,0.095707,0.038263,0.255558,0.422676,-0.080658,0.322894,0.138861,-0.049200,-0.380484,-0.433100,-0.390780,-0.263908,-0.358529,-0.692405,0.248859,0.367871,-0.191978,-0.127093,-0.160273,0.027867,0.573887,-0.437478,-0.044797,0.634158,-0.153385,-0.075189,0.518765,-0.133335,0.210674,-0.507112,0.376140,-0.261603,-0.102532,0.534625,-0.222601,0.634968,-0.181367,0.189334,-0.237348,-0.039770', '25912924', '5403927', '4268598', '1322847');
