INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30299345', '康斯坦丁：恶魔之城 电影版', '动画', 'CW Seed的网剧《康斯坦丁：恶魔之城》准备发布一部长篇的版本正如网剧《雌狐》一样，5集的《康斯坦丁：恶魔之城》将汇编在一起并加入新片段，最终转换成一部完整的电影。DC动画电影《康斯坦丁：恶魔之城》将于10月9日发布蓝光和数字版，敬请期待', '马特·瑞安', '道格·墨菲', 7.6, 11890, 'tt9177882', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2536561659.jpg', 0.7, 2.7, 29.8, 47.7, 19.2, '0.311864,0.382572,-0.360343,0.873588,0.682198,0.300993,0.506466,-0.132860,-0.131621,-0.080739,-0.057699,1.001568,-0.554941,0.354410,0.415236,-0.499350,-0.336925,-0.651840,-0.234225,-0.679572,0.261483,-0.161219,-0.172944,0.102507,-0.128219,-0.516749,1.136932,0.423471,0.099175,0.044793,0.269308,0.311658,-0.747149,0.261831,0.257530,-0.177776,-0.269459,-0.422253,-0.261007,0.567903,0.012526,0.099316,0.174921,0.090775,0.026307,0.062929,1.230986,-0.969367,-0.060303,-0.442841,0.762050,-0.055753,0.008558,-0.431621,0.123726,0.477259,0.476208,0.544077,0.192404,0.050774,-0.031709,-0.875469,-0.986753,-0.093309,0.444895,0.151142,-0.268961,0.208364,-0.429000,0.485539,0.064403,-0.270732,0.057145,0.268549,0.776806,0.461294,0.021314,0.003060,-0.139357,0.673041,0.105020,0.078624,-0.568690,0.399776,0.519907,-0.632725,-0.376509,-0.035655,-0.248261,0.403576,0.487547,0.267966,-0.050452,0.108619,-1.082710,-0.162675,-0.161468,-0.310926,0.212880,-0.442259,-0.004229,-1.207015,0.174202,0.414798,0.254601,-0.036983,0.672877,-0.191210,0.744982,-0.727402,0.204718,0.206825,0.502511,-0.298895,0.305102,-0.535291,-0.181116,-0.196278,0.369388,0.350908,0.497413,0.591997,0.156081,0.044490,-0.023521,-0.383262,-0.634016,0.865752', '26759820', '35088569', '30434174', '1292347');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30299356', '友情以上', '喜剧', '潘（奈哈·西贡索邦 Naphat Siangsomboon 饰）和琴（平采娜·乐维瑟派布恩 Pimchanok Leuwisetpaibul 饰）已经做了十多年的朋友了，曾经，他们亦有机会将这段友情升华成为爱情，然而，面对潘的表白，琴一口回绝，她认为两人还是更适合做朋友。于是，潘和琴成为了世界上最亲密的朋友。每当潘和他的女朋友们分手时，琴都会陪伴在潘的身边帮助他度过失恋期。而琴失联的时候，无论潘在世界的哪个角落，他也都会来到琴的身边。潘和琴的友谊是如此的坚定，甚至导致琴的男友泰德（杰森·杨 Jason Young 饰）大吃飞醋。一天，琴忽然问潘有没有想过如果有一天他们真的走到一起会怎样，对于他们来说，这会是另一段美好感情的开始，又或是终结呢？©豆瓣', '平采娜·乐维瑟派布恩', '查亚诺普·布恩帕拉科布', 6.2, 55970, 'tt9737688', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2565511423.jpg', 2.8, 17.3, 52.3, 22, 5.6, '0.178610,0.171608,-0.676361,0.719243,-0.210213,-0.172525,0.637655,-0.204415,-0.403117,-0.355152,-0.165789,0.624517,-0.131943,0.725363,0.556094,-0.142574,-0.008761,-1.000434,0.154297,-0.157147,-0.858440,-0.534401,-0.143371,-0.402055,-0.216990,-0.079378,0.477253,0.132703,-0.271439,0.101070,0.586191,0.278196,-0.083020,0.660269,-0.227057,-0.076573,-0.002057,0.489234,-0.485823,0.070158,0.158321,-0.313251,-0.137710,0.280393,0.231149,-0.085679,0.543097,-0.119723,-0.235058,0.012849,0.221048,0.000074,0.103742,-0.374738,0.472025,-0.235575,0.373468,0.278520,-0.212402,0.050211,-0.055146,-0.215369,-0.643149,0.077126,-0.028801,-0.154619,-0.511432,0.244594,0.387362,0.099660,0.054469,-0.183117,0.527011,0.537968,0.370407,0.287998,-0.274920,-0.230827,-0.567791,0.230192,0.824509,0.285327,-0.017259,0.354587,-0.122017,-0.393533,-0.187359,-0.221412,-0.317020,0.047436,0.062577,0.227234,-0.052759,0.130164,-0.444465,-0.000755,0.030621,0.180881,0.364479,-0.623747,0.325434,-0.403297,0.041824,-0.453051,-0.271837,0.347289,-0.140647,-0.649298,0.945956,-0.911571,0.453921,0.158905,0.305318,-0.647625,0.777364,0.433076,-0.117761,-0.463719,0.178437,0.605978,-0.183536,-0.340325,0.169028,0.056804,0.148639,0.108073,-0.233271,0.761035', '4301278', '26730542', '35048413', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30299515', '釜山行2：半岛', '动作', '上集列车驶往釜山后，丧尸病毒瞬间全国爆发，4年后的韩国尸毒遍野，被全球孤立，沦为死城。所馀无几的生还者踏上最后一艘难民船，离开被世人遗弃的朝鲜半岛。退伍军人正锡(姜栋元 饰)和家人有幸登上难民船，但一上船便发现丧尸潜伏，幸得香港收容，这批韩国人才得以上岸，以「半岛难民」身分在香港重新生活。但正锡受不住金钱诱惑，加入了一个回国窃取巨额美金的行动。他和队友重返韩国，竟然发现仍有一班未受尸毒感染的人在挣扎求存，正锡决定带这班倖存者逃生，他们最后能否成功逃出尸杀半岛？', '姜栋元', '延尚昊', 5.1, 120697, 'tt8850222', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2610358497.jpg', 12.7, 34.5, 39.9, 9.2, 3.7, '-0.172519,0.045724,-0.685597,0.137590,0.266250,-0.268937,0.477536,-0.092798,-0.519428,0.127865,0.163018,0.660423,0.046870,0.132121,0.155474,-0.089616,-0.373631,-0.381301,0.083016,-0.228466,-0.361209,0.015527,-0.259078,-0.103582,-0.058280,-0.247376,0.821367,0.640144,-0.068489,0.600791,-0.054756,0.144752,-0.236800,0.553777,-0.288656,0.055496,0.036664,-0.351694,-0.210709,0.337409,-0.517019,-0.534037,-0.073730,-0.135247,0.004258,0.186121,0.981887,-0.048551,0.058806,-0.194395,0.099798,-0.611408,0.026664,0.121202,0.290919,0.124883,-0.002633,0.056514,-0.177486,0.108865,0.021488,0.168101,-0.375940,-0.164426,-0.167475,-0.075675,-0.431732,0.208745,-0.007408,0.143048,-0.168152,-0.211887,0.102940,0.482592,0.087072,0.040336,-0.225289,0.230107,-0.797460,0.103821,0.826715,-0.434104,-0.360248,0.014375,0.225970,-0.658624,0.147020,-0.420058,-0.107689,-0.057834,0.420213,0.093322,-0.366163,0.217693,-0.736130,-0.006634,-0.634530,-0.400625,-0.054339,0.100907,-0.116735,-0.676782,-0.187686,0.154813,0.029081,0.361330,0.329651,-0.069075,0.749902,-0.364217,0.133479,0.498108,0.618203,-0.630675,0.409462,-0.284120,0.223274,0.116739,0.108515,0.332987,0.229525,0.715742,0.167916,-0.009051,-0.484284,-0.027612,-0.138573,-0.067609', '1856675', '2159244', '6007281', '1308982');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30300277', '猎杀T34', '动作', '每一场战争都有一些传奇故事。根据二战真实事件改编。莫斯科保卫战时，刚从坦克学校毕业的尼古拉被派往战场执行“自杀式”的任务，在以一敌六的情况下，他驾驶着传奇坦克T-34，奇迹般地击毁了德军耶格尔上校的小队，但自己却遭到俘虏。到了二战末期，耶格尔为了快速训练出德国希特勒青年团的坦克新兵，逼迫集中营里的尼古拉和另外几名苏联俘虏驾驶一辆翻新的T-34作为他们训练的活靶子。在其他人都在为赴死作心里准备时，尼古拉的脑子里却浮现出了一个惊人的计划——驾驶T-34在训练中逃离德国军营。', '亚历山大·佩特罗夫', '阿列克赛·西多洛夫', 7.5, 53965, 'tt8820590', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2627487532.jpg', 0.5, 2.9, 31.8, 51.1, 13.6, '0.217013,0.073741,-0.921960,0.782112,0.083399,-0.229963,0.751242,-0.233809,-0.276253,-0.149897,0.728811,0.675175,0.062144,-0.044960,0.420923,-0.342336,-0.547504,-0.590912,-0.368778,0.044674,-0.538367,-0.474185,-0.322143,-0.395254,0.136475,-0.244797,0.901236,0.224728,-0.318316,0.265639,0.103522,0.470182,0.039016,0.254021,-0.229034,0.040211,0.170213,-0.310068,-0.125075,0.148869,-0.208107,-0.324048,-0.395491,-0.077935,-0.066847,0.522429,0.883684,-0.306727,0.110101,-0.046969,0.017601,-0.323147,-0.034214,-0.007614,0.462757,0.299175,-0.167993,0.081704,0.276270,0.413566,-0.231451,0.042222,-0.800849,-0.123470,-0.345762,-0.042580,-0.763391,0.366217,-0.521563,0.379100,0.464892,-0.125467,0.112043,0.686682,0.090637,0.336638,-0.349040,0.217136,-0.655235,0.338976,0.739129,-0.235601,-0.512348,0.155107,-0.039474,-0.363765,-0.022758,-0.585548,-0.054706,-0.062412,0.185891,-0.231618,-0.099701,0.295662,-0.651116,0.062821,-0.438569,-0.575228,-0.167835,-0.100328,-0.138910,-1.051949,0.189990,-0.099494,-0.383874,0.442755,0.096909,0.193716,0.772416,-0.723068,0.065611,0.479579,-0.010010,-0.390473,0.269735,0.093863,0.054207,-0.158852,0.082270,0.141483,0.052824,0.731323,0.158921,0.720059,-0.128856,-0.242187,-0.508264,0.614925', '1294917', '2369613', '1307897', '10467125');
