INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30301264', '看不见的女人', '剧情', '故事发生在1950年巴西的里约热内卢，18岁的尤丽狄茜与20岁的吉达是一对形影不离的亲生姐妹，她们与保守的父母一同生活。虽然家风传统，姐妹俩却各自怀揣梦想：尤丽狄茜想做一名职业钢琴家，吉达渴望追寻真爱。在一次戏剧化的变故后，姐妹被迫分离，两人各自的梦想也因生活的无奈被搁置。即便如此，姐妹俩从未放弃找寻彼此的希望。©豆瓣', '朱莉娅·斯托克勒', '卡里姆·埃诺兹', 7.8, 8557, 'tt6390668', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2558202387.jpg', 0.4, 2, 22.9, 53.9, 20.7, '0.335140,-0.263313,-0.652938,0.541390,-0.078078,-0.433234,0.845240,-0.034063,-0.708710,-0.349375,0.261223,0.895021,-0.191167,0.338928,0.105623,-0.291033,0.062552,-1.018563,0.327974,-0.131627,0.111045,-0.342939,-0.063280,-0.102863,-0.383183,-0.328233,0.731807,-0.054595,0.228677,0.628452,0.420737,0.246740,-0.514771,0.106277,-0.294557,-0.296876,0.131610,0.622170,-0.870945,-0.081212,-0.150409,0.071453,-0.290976,-0.113869,0.128211,0.275560,0.875816,-0.271514,-0.008967,0.084930,-0.028379,-0.168561,-0.230671,0.146496,0.253740,-0.037724,0.198196,0.250035,-0.032800,-0.361078,-0.236320,-0.083278,-0.839537,0.053289,0.462873,0.018339,-0.622973,0.791593,0.081259,-0.058514,0.212968,-0.307390,-0.041555,0.509663,0.420763,0.717044,-0.210640,0.168128,-0.298912,0.258774,1.090444,-0.052436,-0.109483,0.493351,-0.615690,-0.212892,-0.065716,-0.370224,-1.001289,-0.049665,-0.033786,0.296285,-0.217480,0.425468,-0.525709,0.088959,-0.065861,-0.014781,0.646757,-0.834296,0.231421,-0.232669,-0.159973,-0.761913,-0.308589,0.212343,0.105675,-0.295062,0.981717,-0.727491,0.291332,0.343995,0.132555,-0.871921,0.808547,0.363403,0.293994,-0.437936,0.278098,0.628243,-0.329010,-0.261483,0.072647,0.214515,0.028624,0.362674,-0.468815,0.471928', '25721544', '3445516', '26678784', '1296569');
