INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30306436', '大蛇', '动作', '林奇为救身患绝症的女儿，加入了富豪齐腾、医学专家岚若、地质学家胖子及雇佣兵团等组成的冒险小队，踏上了寻找“生命之果”的旅程。在这片危险密布的丛林中，险象接踵而至，队员接二连三遇难身亡，暗处似乎还潜伏着觊觎他们生命的凶残猛兽。想要逃离的队员和齐藤的关系越发紧张，与此同时，生命之花即将开放，神秘猛兽的真面目也浮出水面。', '黄凯伦', '林珍钊', 3.3, 3426, 'Snakes', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2531890522.jpg', 51.8, 33.8, 10.8, 3.1, 0.5, '-0.118762,-0.283124,-0.675168,0.348803,0.074294,-0.051864,0.711796,-0.176263,-0.379629,0.066772,0.370418,0.460053,0.137031,0.125465,0.159944,-0.143682,-0.102298,-0.423654,-0.276067,0.006391,-0.197600,-0.042992,-0.386876,-0.353830,0.323023,-0.636664,1.074965,0.616216,-0.148251,0.678996,-0.051311,0.393174,-0.689652,0.446656,-0.051410,-0.172586,0.153298,0.092649,-0.371931,0.090839,-0.266875,-0.193008,0.150020,0.031293,0.043767,0.505436,0.835147,-0.411605,-0.034620,-0.209972,0.149067,-0.641086,0.309432,-0.099028,0.569480,-0.130239,0.127663,-0.003689,0.196878,0.080349,-0.291428,-0.026215,-0.951223,0.166117,0.286527,0.213637,-0.600001,0.125568,0.255601,0.155995,0.289507,-0.005180,0.498406,0.273783,-0.031001,-0.006391,-0.183016,-0.033182,-0.237170,0.010807,0.683793,-0.351957,-0.133173,-0.066519,-0.176017,-0.535966,-0.072442,-0.077116,-0.178011,-0.183107,0.394221,0.174450,-0.034125,0.401398,-0.598173,0.290200,-0.226877,-0.067606,-0.136859,-0.340116,-0.274886,-0.411867,0.268653,0.253452,-0.062145,0.647421,0.006806,-0.147951,0.497071,-0.407907,0.252968,0.589676,0.251732,-0.623739,0.292339,-0.293861,-0.000222,-0.360285,-0.177867,0.573694,0.084164,0.420484,0.047924,-0.181541,-0.187977,0.029526,-0.150935,-0.028394', '7051375', '3001114', '26759819', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30306570', '囧妈', '喜剧', '虽然有着诸多不舍，但是强势的老板徐伊万（徐峥 饰）还是和合作伙伴兼妻子张璐（袁泉 饰）结束了失败的婚姻。由于某种心理作祟，他试图阻挠前妻在海外重新创业。为了第一时间赶去美国，他回到母亲卢小花（黄梅莹 饰）的住处取护照，结果阴差阳错和母亲坐上了开往俄罗斯的K3次列车。如同身边的老年人一样，卢小花对儿子有着无休止的过度关爱与碎碎念。漫长的旅途中，伊万饱受折磨，他一边遥控表弟郭贴（郭京飞 饰）破坏张璐的生意，一边和母亲展开斗智斗勇的拉锯战。在这一过程中，母子二人冲突不断。伊万渐渐了解到母亲的爱情，同时他也开始反省自己的人生。一路向北，久违的《红莓花儿开》期待再度唱响……©豆瓣', '徐峥', '徐峥', 5.9, 574286, 'tt11172926', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2581835383.jpg', 4.8, 24.2, 49.9, 15.5, 5.5, '0.129783,0.188312,-0.734211,0.682769,0.042849,-0.400861,0.783887,0.145822,-0.634219,-0.144647,0.100248,0.436103,-0.135847,0.337213,0.280394,-0.108578,-0.480612,-0.553421,0.050722,0.039755,-0.355818,-0.400034,-0.117133,-0.162133,-0.150102,0.035547,0.456304,0.076733,-0.252950,0.614633,0.406080,0.258445,-0.277356,0.536121,-0.047675,0.330421,-0.063912,0.148562,-0.460152,-0.018636,0.415232,-0.235492,-0.049857,-0.030643,0.081976,0.228754,0.741136,-0.203121,0.057565,-0.146045,0.361118,-0.159445,-0.078061,0.128882,0.262453,0.245185,0.268807,-0.061960,-0.281449,0.002940,0.152709,-0.194776,-0.566565,-0.111784,-0.004782,0.044483,-0.612246,0.401631,0.031058,0.189310,0.298927,-0.530621,0.162349,0.476444,0.338657,0.425835,-0.469713,-0.033797,-0.282311,0.196627,0.701508,0.131513,0.141381,0.318216,-0.371988,-0.137896,-0.083974,-0.064472,-0.588704,-0.339733,0.471129,0.088494,-0.025618,0.328886,-0.539253,-0.086261,-0.046557,-0.160197,0.029965,-0.472202,0.180377,-0.465967,-0.138419,-0.805567,-0.080111,0.069859,-0.029931,-0.225034,0.584696,-0.703696,0.444495,0.415503,0.212031,-0.546459,0.301688,0.287348,0.280426,-0.421190,0.022538,0.440974,-0.122371,0.273760,0.187709,0.182773,-0.147358,0.198079,-0.288872,0.467877', '1301022', '3111650', '1308745', '20020577');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30306597', '黄金宝藏', '剧情', '有「巨人」称号的策本是那达慕节的摔跤冠军，尽管已获得无数次的胜利，年迈的他却没有儿子能继承这份荣耀，就在得知妻子生下的第四胎也是女儿的当下，策本决定把么女太文视为男孩来抚养，面对被迫放弃女儿身的太文，内心依旧渴望换上美丽的衣服，当个漂亮的女孩。就在某次意外中，她的死对头杭艾发现这个惊人的真相，两人的关系也因此产生微妙的变化，究竟这个家族秘密能否永远守住？太文是否注定一生都得当个男孩子？', 'Erdenetsetseg Bazarragchaa', 'Uranchimeg Urtnasan', 8.2, 6936, 'tt4717534', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2578570322.jpg', 0.5, 1.4, 16.7, 48.8, 32.7, '0.002338,0.328034,-0.774217,0.599261,-0.481043,-0.250289,0.414078,-0.188139,-0.297571,-0.373252,0.352147,0.850546,0.100539,0.125435,0.114294,-0.033765,0.033601,-0.615139,-0.013046,-0.051726,-0.227274,-0.473205,-0.403467,-0.007833,0.065651,-0.210698,0.986850,0.004313,-0.198971,0.238326,0.574952,0.173440,0.172168,0.445365,-0.385933,0.036257,-0.152195,0.326178,-0.110517,0.138821,-0.043879,-0.203972,-0.042190,0.367879,-0.057531,0.383696,0.619701,-0.547040,-0.329254,0.004865,0.563065,-0.115978,-0.132453,0.113263,0.260511,-0.092954,-0.011412,0.271370,-0.143821,-0.144850,0.033113,-0.023913,-0.922597,-0.119011,0.587072,0.077780,-0.496686,0.511983,0.024915,-0.276327,0.085710,-0.325950,0.220162,0.348569,0.163604,0.585433,-0.292444,0.300204,-0.499667,-0.000970,0.785614,-0.033148,-0.384312,0.207056,-0.415367,-0.408650,0.130897,-0.576941,-0.550169,0.268436,0.263736,0.371912,-0.174593,0.331161,-0.178641,-0.034743,-0.296081,0.142500,0.320042,-0.619729,0.101870,0.065973,-0.178842,-0.287537,-0.299168,0.139956,0.074329,-0.574898,0.778219,-0.771945,0.335451,0.382009,0.062171,-0.683407,0.582918,0.401737,0.296325,-0.391192,-0.262931,0.404596,-0.158497,-0.117411,-0.262179,0.190595,0.138039,-0.133366,-0.270741,0.633508', '30163500', '25880986', '26678784', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30306756', '大饿', '剧情', '阿娟（蔡嘉茵 饰）本该是一个快乐的30岁女青年，可是她105公斤的体重总让她成为周遭人议论和嘲笑的对象，灰暗的生活中，只有温暖的食物才能带给阿娟一丝丝的安慰，但这显然是一种恶性循环。在生日这一天，母亲送给了阿娟一套减重课程作为礼物，人生道路上接连遭遇挫折的阿娟虽然很不情愿，但亦明白，自己不得不踏上减肥的旅途。在此过程中，阿娟邂逅了名为吴浩仁的快递员，知道了他隐藏在开朗表象之下的悲惨过去；又在误打误撞之中撞破了旁人眼中的模范男孩的女装秘密。接二连三的事件让阿娟开始明白，每个人都有着自己的深渊。©豆瓣', '蔡嘉茵', '谢沛如', 6.9, 10337, 'tt10380980', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2572235972.jpg', 1.1, 5.9, 48.1, 34.8, 10.1, '0.223373,-0.027038,-0.612876,0.601543,-0.188683,-0.026377,0.858103,-0.068396,-0.637197,-0.194904,0.353915,0.685718,-0.058033,0.398578,0.377157,0.089212,-0.101117,-0.412098,-0.117542,-0.357856,-0.414926,-0.336882,-0.334917,-0.025544,-0.103635,-0.314212,0.523812,0.337778,-0.151435,0.473446,0.398944,0.307962,0.119499,0.711109,-0.203194,0.042022,0.046392,0.035780,0.013506,-0.026522,-0.005834,-0.359192,-0.018597,0.429854,-0.188388,0.411420,0.754048,-0.212877,-0.295102,0.142121,0.463528,-0.169648,-0.191005,0.113515,0.124893,0.097429,0.277026,0.005997,-0.204185,0.104518,0.106794,0.059302,-0.670545,-0.098658,0.262635,0.026828,-0.560885,0.524023,0.196277,0.004802,0.065817,-0.262079,0.205641,0.131146,0.259375,0.596017,-0.238010,-0.002342,-0.518916,0.145310,0.786914,-0.001822,-0.312782,0.485848,-0.661685,-0.438260,-0.018806,-0.241258,-0.571937,0.077610,0.167096,0.295388,-0.300111,0.276888,-0.585302,0.224252,-0.058605,-0.170803,-0.146732,-0.624871,-0.220179,-0.089592,-0.180376,-0.541153,-0.571127,0.086462,0.127772,-0.506079,0.774801,-0.895505,0.305199,0.509189,0.014194,-0.324478,0.738880,0.370744,0.112994,-0.167326,-0.104137,0.119038,-0.092214,-0.032288,-0.153856,0.470794,-0.156372,-0.041593,-0.520741,0.581396', '1296370', '2081098', '1307561', '1292062');
