INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30307197', '星之彩', '科幻', '一颗流光溢彩的太空陨石径直坠入新英格兰偏远庄园后，邪恶势力开始暗暗渗透静居于此的加德纳一家。不知不觉中，时间开始膨胀，自然逐渐呈现超凡脱俗的异世色调，而所有鲜亮美丽之物则受其影响纷纷异变腐败。本片由南非影人理查德·斯坦利执导，与斯嘉丽·阿马里斯合作改编自H·P·洛夫克拉夫特1927年同名短篇小说《异星之彩/流星溢彩（The Colour Out of Space）》，并由奥斯卡影帝尼古拉斯·凯奇领衔主演。', '尼古拉斯·凯奇', '理查德·斯坦利', 6.5, 18558, 'tt5073642', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2582953131.jpg', 3.6, 15, 45, 27.8, 8.6, '0.046520,0.160368,-0.672910,0.502792,0.569945,-0.161206,0.418750,0.466356,-0.360738,-0.158870,0.041206,0.607907,-0.442987,-0.107273,0.274957,-0.090071,-0.644314,-0.530743,-0.351258,-0.333440,0.161649,-0.240950,-0.070731,0.055866,-0.085115,-0.304174,0.545603,0.276381,0.186558,0.532166,0.051393,0.537617,-0.297516,0.079739,0.299888,-0.262644,0.190711,-0.182179,-0.381458,0.216809,-0.116902,-0.138349,-0.005635,-0.007298,-0.034153,0.061810,0.622303,-0.324687,0.184309,-0.674798,0.482366,0.148488,0.049992,-0.100233,0.249013,0.030993,0.055841,-0.119945,-0.218822,0.102294,0.188675,-0.310895,-0.186688,0.015608,0.155151,0.221961,-0.013286,-0.031120,0.265253,-0.198672,-0.248263,-0.094796,0.176507,-0.288073,0.345517,-0.109397,0.039605,0.013477,0.037471,0.155756,0.311535,-0.009842,-0.551923,0.258846,-0.373877,-0.404812,-0.067697,0.239293,-0.227402,-0.192985,0.399557,0.397107,0.431889,0.661393,-0.549491,0.068958,-0.452431,-0.428554,-0.286649,-0.022376,-0.074547,-0.508479,-0.293622,0.031169,0.041707,-0.109152,-0.181436,0.206618,0.317474,-0.197427,0.574689,0.184283,-0.057837,-0.108397,0.224386,-0.653973,0.130519,-0.226298,-0.190589,0.734323,-0.016947,0.141086,-0.123764,0.169380,-0.084154,0.070290,-0.089612,0.232588', '1308069', '3871833', '3645150', '26823502');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30310218', '标准之外', '剧情', '二十年来，般奴和马力克生活在一个不同的世界当中，那是一个属于患自闭症的儿童和青少年的世界。他们二人分别管理The Hatch & The Shelter两个非牟利机构，目标在贫困地区培训年青人担任守护工作，负责照顾一些被其他机构拒于门外的重度患者个案。这非传统的合作关系展现了非一般的人生。', '文森特·卡索', '奥利维埃·纳卡什', 8.4, 16807, 'tt8655470', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2556765966.jpg', 0.5, 1.3, 11.9, 53.1, 33.1, '0.416560,-0.111686,-0.442120,0.589931,-0.434880,-0.028750,0.661152,0.221417,-0.276257,-0.530660,-0.015888,0.925655,0.341701,0.032921,0.113952,-0.603713,0.044007,-0.651474,-0.429188,-0.376207,-0.438878,-0.531154,-0.126748,-0.326507,-0.436545,-0.414113,0.925999,-0.357155,-0.182173,0.488942,0.058991,0.320406,-0.276081,0.084448,-0.380687,-0.438999,0.423956,-0.016503,-0.578724,0.305092,-0.311267,0.101286,0.191504,0.046556,-0.012394,0.312189,0.717916,-0.076180,-0.166954,-0.492767,0.456944,-0.080308,-0.194420,-0.196839,0.701556,0.038580,0.208377,0.362094,-0.398317,0.132488,0.097005,-0.387850,-1.099938,-0.583907,0.519820,0.373374,-0.546997,0.515951,0.361467,-0.520696,-0.270169,0.154130,0.542478,0.599720,0.179738,0.870037,-0.004667,0.210734,-0.569759,0.179832,0.772844,-0.223678,-0.357013,0.218233,-0.560164,-0.340267,-0.069259,-0.203282,-0.413188,-0.146323,0.103341,-0.486424,-0.394946,-0.016673,-0.693987,0.153472,0.153167,-0.322158,-0.092951,-0.533295,0.150344,-0.859695,0.043132,-0.361335,-0.304360,0.096421,0.351997,-0.245661,0.918987,-0.972618,-0.092870,0.542929,0.342324,-1.052907,0.947464,0.475638,0.804856,-0.490370,0.010470,0.145423,0.189870,0.280990,-0.288526,0.467390,-0.030662,0.289880,-0.608280,0.370377', '26678784', '4301278', '1793491', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30312137', '麦路人', '剧情', '曾是一位金融才俊的阿博（Bowen），终日在24小时快餐店借宿，店内有不少同路人与阿博为伍，相互改写了各自的人生。分别有一直为奶奶还债而债台高筑的妈妈带着囡囡、不敢回家的等伯、刚离家出走的少年深仔，还有暂居庇护宿舍的歌女阿珍都以阿博为首，各人互相扶持，希望能尽力帮助彼此走过人生低谷…..', '郭富城', '黄庆勋', 6.5, 30422, 'tt10117402', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2619912723.jpg', 1.4, 12.2, 53.1, 27, 6.4, '0.191950,-0.389479,-0.363380,0.286531,-0.034269,-0.773392,0.474552,0.342687,-0.659558,-0.131799,0.061892,0.641411,-0.018567,0.521735,0.209352,-0.507688,-0.248710,-0.568205,-0.198710,-0.214864,-0.327467,-0.454641,0.207909,0.025459,-0.313635,-0.058829,0.320746,-0.086163,0.199100,0.498367,0.166638,0.059018,-0.285265,0.183594,-0.594014,0.005441,-0.165697,0.158485,-0.677892,-0.055722,-0.000969,-0.166106,-0.353627,-0.394198,0.133824,0.252044,0.636178,-0.018851,0.031718,-0.048970,0.280172,0.164864,0.075413,-0.030601,0.323946,-0.100820,0.450987,0.216762,0.019022,-0.203519,0.050074,-0.071924,-0.726813,0.088377,0.288905,0.055402,-0.623121,0.461757,0.239012,-0.257625,0.386546,-0.136334,0.054047,0.744795,0.097028,0.390599,-0.097492,0.015965,-0.598501,0.247570,0.732336,0.014382,0.042690,0.200089,-0.140205,-0.165236,0.362650,-0.165703,-0.681743,-0.238872,-0.020791,0.207175,-0.044458,-0.094386,-0.377974,0.168409,-0.096969,-0.207204,0.488266,-0.655655,0.078164,-0.690873,-0.264370,-0.335423,0.059526,0.540302,0.436125,-0.093789,0.853710,-0.867398,0.332336,0.305871,0.611417,-0.527293,1.112834,0.109848,0.345405,-0.127724,0.036850,-0.084225,-0.155178,0.442415,0.210844,0.205122,0.050092,0.338367,-0.416598,-0.091890', '10876425', '25881781', '4004731', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30314127', '惊天营救', '动作', '泰勒·雷克（克里斯·海姆斯沃斯饰）是一名无所畏惧的黑市雇佣兵，一无所有的他奉命营救入狱的黑帮大佬被绑架的儿子。但是在充斥着武器交易商和毒贩的阴暗地下世界中，本就致命的任务更是难以完成，并彻底地改变了雷克和男孩的命运。', '克里斯·海姆斯沃斯', '山姆·哈格雷夫', 7.2, 85551, 'tt8936646', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2594557845.jpg', 0.6, 4.4, 43, 40.3, 11.7, '0.435901,0.060099,-0.630244,0.629436,-0.482856,-0.215514,0.958669,-0.036389,-0.547303,0.024864,0.485332,0.930418,0.105005,0.123497,0.628599,0.090890,-0.372751,-0.776597,-0.505727,-0.268610,-0.270872,-0.737783,-0.502235,-0.502562,0.084920,-0.345668,0.913017,0.412440,-0.085298,0.260507,0.333733,0.400668,-0.057115,0.693203,-0.049002,-0.088443,0.276709,-0.254877,-0.076571,0.241716,0.015821,-0.337266,-0.040651,0.435184,-0.112105,0.535679,0.396917,-0.501131,0.309854,-0.392792,0.029351,-0.556457,-0.071072,0.101706,0.378303,-0.241391,0.008958,0.307699,0.050063,-0.055967,0.286652,-0.123806,-0.969219,-0.122418,0.205112,0.143769,-0.638870,0.583779,-0.289854,0.128629,-0.152861,-0.172134,0.182333,-0.026514,0.137839,0.449636,-0.333532,0.047791,-0.699375,0.064300,0.374984,-0.157332,-0.446962,-0.182896,-0.412251,-0.590260,-0.306048,-0.395878,-0.470011,-0.202129,0.676235,0.002906,-0.532181,0.524311,-0.663543,0.050020,-0.294993,-0.392712,-0.471746,-0.418244,-0.217834,-0.661740,-0.120116,-0.370295,-0.181302,0.253146,0.251677,-0.079857,0.501552,-0.894902,0.327720,0.815553,0.247160,-0.381961,0.404072,0.135188,0.378579,-0.196680,-0.424130,0.185509,0.326192,0.583938,0.311215,0.372838,-0.141691,-0.137874,0.039468,0.736448', '1292000', '25828589', '1793491', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30314848', '瞬息全宇宙', '喜剧', '55岁的美国华裔移民伊芙琳（杨紫琼 饰）家庭事业两崩溃。在老父亲生日大寿这天，除了要阻止女儿（许玮伦 饰）暴走出柜、替无用丈夫（关继威 饰）擦屁股，还得去税务局向古板大婶（杰米·李·柯蒂斯 饰）解释不太妙的税务问题。才踏进大楼电梯，软烂丈夫竟摇身一变演起黑客帝国，声称自己是另一个宇宙的版本，而秀莲也是千万宇宙里的其中一个。还来不及理解，邪恶势力已在多元宇宙中蔓延，世界即将毁灭，只有在这个宇宙里，“一无是处”的伊芙琳才能拯救世界……', '杨紫琼', '关家永', 7.6, 370134, 'tt6710474', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2869765076.jpg', 1.5, 5.6, 27.8, 40.2, 24.8, '-0.219928,0.369259,-0.720150,0.239208,-0.337287,-0.327094,0.691159,0.090909,-0.078088,-0.197487,-0.102234,0.462225,-0.002098,0.286119,0.344043,0.147667,-0.138497,-0.368116,-0.202509,-0.063710,-0.381167,-0.484368,-0.340131,-0.270437,-0.109148,-0.285122,0.457206,0.087969,-0.219110,-0.237718,0.263428,0.191798,-0.293707,0.437758,-0.288762,0.003587,0.208163,0.317754,-0.226670,0.127305,-0.205343,-0.047280,0.012778,0.256408,-0.190383,0.258215,0.441637,-0.179357,0.316103,-0.244122,0.577419,0.016300,-0.341264,-0.162658,0.448832,-0.348772,0.095710,-0.038965,-0.004135,0.269469,0.138946,-0.247613,-0.548966,-0.288273,0.182034,0.127907,-0.541694,-0.099828,-0.198668,-0.293871,0.118748,-0.244099,0.139874,0.260844,0.243221,0.756156,-0.231717,0.116653,-0.482304,0.223803,0.243322,0.047164,-0.328763,0.346930,-0.152838,-0.386089,-0.130262,-0.054809,-0.608760,-0.239869,0.070030,-0.131948,0.080603,0.150085,-0.288207,-0.111591,-0.185223,-0.305380,0.164601,-0.152619,-0.008562,-0.192766,0.013194,-0.027733,-0.073821,0.144391,0.229424,-0.028003,0.509225,-0.371991,0.260696,0.466529,0.384684,-0.423612,0.829137,0.225091,0.209587,-0.564731,0.297070,0.196291,-0.140526,0.235979,-0.240762,0.312320,0.007557,-0.263849,-0.211948,0.377184', '4066127', '1302384', '26884422', '1303077');
