INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30317706', '特警队', '动作', '《特警队》是华语内地警匪片中第一部完全以特警为主角的电影，影片以真实的特警精英队伍“蓝剑突击队”为人物原型，讲述了特警队员们对内在实战演练中互相博弈，置身训练场不断淬炼自我，场场来真的；对外无惧艰险，深入虎穴，齐心协力捣毁制毒基地、解救线人，共同守护城市安全的故事。', '凌潇肃', '丁晟', 5, 26412, 'tt9243442', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2576871245.jpg', 11.4, 38.9, 40.3, 7.4, 2, '-0.327396,-0.193847,-0.270493,0.673741,0.349835,0.339030,0.296599,-0.314398,-0.761383,-0.029296,0.749892,0.411899,0.226313,-0.339405,0.097096,-0.657522,-0.516621,-0.862758,-0.669858,-0.005389,-0.313107,-0.167491,-0.175090,-0.133994,0.077248,-0.265041,0.906235,0.154865,-0.333776,0.103559,0.001815,0.075503,-0.572550,-0.231031,0.103122,-0.261998,0.288239,-0.277948,-0.696370,0.083629,-0.554933,-0.027787,-0.539560,0.051533,0.025622,0.155461,0.874074,-0.147246,0.081369,-0.173687,0.270995,-0.302501,-0.135121,-0.304245,0.388998,0.289650,0.406878,0.065690,0.418962,0.289971,-0.484949,-0.401461,-1.190286,-0.308157,0.350703,-0.018000,-0.180011,0.191159,0.032183,0.195877,0.429421,0.141176,-0.010332,0.140649,0.752161,0.255004,-0.078127,-0.040562,-0.307573,0.678730,0.661523,-0.093726,-0.325847,-0.067828,-0.234083,-0.440760,-0.269139,-0.477447,-0.260961,-0.277435,0.061756,-0.167147,0.040861,0.219959,-0.466241,0.176181,0.075154,-0.452705,-0.132159,-0.482770,0.167044,-1.046208,-0.045865,0.026915,0.316443,0.158638,-0.163868,-0.082047,1.059354,-0.950373,-0.067418,0.706879,-0.067918,-0.524247,0.473706,0.006277,0.275748,-0.442097,-0.010956,0.195300,0.208173,0.579070,0.095625,0.402705,-0.398996,-0.055683,-0.651423,-0.068099', '2369613', '27602116', '5403927', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30318116', '利刃出鞘', '剧情', '富豪小说家哈兰·斯隆比在自己85岁生日第二天，被发现在自家庄园离奇自杀，遗留了亿万遗产。久负盛名的大侦探布兰科（丹尼尔·克雷格饰）突然被匿名人士雇佣调查此案真相。同时，哈兰的孙子兰森（克里斯·埃文斯饰）也正在秘密调查此案。当布兰科和哈兰·斯隆比家族的其他人对谈时， 他发现事情并没有想象中那么简单。哈兰家族没有表面上那么和睦，每个人都有着不可告人的秘密，每个人都想得到遗产……究竟这起命案是自杀还是他杀？似乎每个人都有嫌疑。随着一位遗产继承人的意外亮相，真相谜底渐渐浮出水面……', '丹尼尔·克雷格', '莱恩·约翰逊', 8.1, 757532, 'tt8946378', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2574172427.jpg', 0.2, 1.1, 17.6, 54.8, 26.4, '0.101579,-0.119579,-0.783803,0.286788,-0.056962,0.031701,0.803189,-0.083241,-0.721521,-0.691721,0.084362,0.857557,-0.126364,0.084146,-0.080522,-0.017211,-0.536631,-0.735673,0.179966,-0.515433,-0.179735,-0.829829,-0.281782,-0.488532,-0.026818,-0.136077,0.224487,0.130447,-0.129623,0.117362,0.465855,0.538034,-0.162765,0.426931,-0.223620,-0.013574,0.548962,0.232807,-0.084496,-0.018858,-0.344599,-0.163285,-0.271513,0.228842,-0.029712,0.651106,0.124911,-0.091981,-0.364414,-0.020823,0.114767,-0.215082,-0.137171,0.129647,0.659964,-0.187952,0.189451,0.607289,-0.056734,-0.252542,0.087379,-0.001422,-0.809329,-0.094241,0.438990,0.621509,-0.428518,0.209338,-0.283478,-0.152043,0.049624,-0.204854,0.271765,0.337209,0.177397,-0.022624,0.032057,-0.004200,-0.801744,0.121505,0.535087,-0.007398,-0.087121,0.172148,-0.367930,-0.425971,-0.174119,-0.253641,-0.127391,0.447901,0.420839,0.077388,0.051960,0.743753,-0.055754,-0.132194,-0.184755,-0.299950,-0.122512,-0.479629,-0.045107,-0.441103,-0.328088,0.030660,-0.484903,0.069067,0.015070,-0.357042,0.628210,-0.497655,0.164954,0.457877,0.011990,-0.642452,0.389901,0.138551,-0.139662,-0.341441,-0.322506,-0.006745,0.381040,-0.009252,-0.202149,0.153838,0.199765,-0.370558,-0.115584,0.353033', '1296217', '1293145', '25862560', '1292268');
