INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30320057', '新灰姑娘', '动画', '一次偶然中，灰姑娘艾拉（Cassandra Morris 配音）得到了前往王宫，参加王子艾利克斯（Chris Niosi 配音）所举办的宴会的机会，可是会场上，聪敏的艾拉很快就发现眼前的王子是个冒牌货。经过一番缜密的调查，艾拉终于发现了真相，原来真正的王子早已经被邪恶的女巫（温迪·李 Wendee Lee 配音）变成了一只老鼠，而女巫真正的目的，是夺得掌控这个国家的权利。为了化解女巫的阴谋，艾拉在魔仙学徒莉莉（Kristen Day 配音）的帮助下踏上了拯救王子的旅途。艾拉凭借着自己的勇气和智慧，以及莉莉的半吊子魔法，破解了女巫设下的一个又一个难题。时间一分一秒的流逝着，每过一分钟，王子和这个国家就将离危险更近一步。©豆瓣', 'Kirsten Day', '林恩·萨瑟兰', 4.4, 2631, 'tt6241270', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2535297332.jpg', 35.3, 28.6, 23.5, 5, 7.6, '0.391539,0.358845,-0.275705,0.697297,-0.146303,-0.261737,0.666215,-0.403397,-0.285743,-0.520751,0.345119,0.702224,-0.440193,0.149609,0.498451,0.085711,-0.394045,-0.589751,-0.086421,-0.341237,-0.316596,-0.612136,-0.525322,-0.183627,0.020638,-0.391194,0.828971,0.055592,-0.090615,0.270755,0.214940,-0.052605,0.067904,0.368807,-0.037174,0.009667,0.447048,-0.119983,0.023445,0.583352,0.123560,-0.214260,-0.103709,0.312409,-0.208748,0.343457,0.605161,-0.710485,0.101742,-0.222051,0.495747,-0.652296,0.046311,0.177103,0.269540,-0.185635,0.204736,0.197057,-0.005336,-0.264679,0.114815,-0.253006,-0.907812,0.020534,0.146194,0.147786,-0.572016,0.212954,-0.024970,-0.162816,0.290479,-0.505321,0.229175,0.471701,0.451809,0.338307,-0.271363,-0.074320,-0.481680,0.010276,0.660220,-0.004265,-0.383993,0.251505,-0.020472,-0.748988,0.012179,-0.261123,-0.358567,-0.071859,0.432080,0.059616,-0.016533,0.415144,-0.697628,-0.114527,-0.598581,-0.213039,0.160741,-0.557882,-0.018568,-0.646437,-0.198376,-0.078772,-0.073419,0.128181,0.219160,-0.440731,0.699613,-0.982865,0.398692,0.759605,0.273587,-0.200198,0.608219,-0.139334,0.039049,-0.269569,-0.021009,0.211616,0.028956,0.458665,-0.004585,0.532286,0.066541,-0.293490,-0.567169,0.539968', '1793491', '1420088', '26759819', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30322432', '周恩来回延安', '剧情', '影片以1973年6月身患重症的周恩来总理，在特殊历史时期下肩负历史使命和老一辈革命家对老区人民的情怀回到圣地延安的历史事件为叙事中心，电影通过周恩来总理独有的视角回顾了中国革命在延安时期13年的重大历史事件，以四个时空表现了周恩来总理在延安的所见所闻、所思所感展示了中国共产党人不忘初心、砥砺前行的崇高责任感。', '刘劲', '吴卫东', 6.4, 2934, 'tt10357206', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2553832372.jpg', 9.1, 12.3, 39.6, 26, 13, '-0.232088,0.028619,-0.580906,0.774752,0.225252,-0.019436,0.154609,0.069935,-0.864454,-0.199106,0.522473,0.770288,-0.043623,-0.051084,0.548552,-0.280090,-0.400230,-0.779312,-0.009994,-0.152575,-0.146234,-0.408430,-0.320717,-0.236357,-0.181789,-0.421745,0.794274,0.262792,-0.408440,0.217560,-0.185482,0.319828,-0.033757,0.133832,-0.085689,-0.041044,0.122663,-0.036373,-0.807155,-0.041463,0.258134,-0.364349,-0.504454,0.140657,-0.208420,-0.051726,0.503212,-0.634421,-0.339080,-0.096351,0.724951,-0.209384,-0.245433,-0.059584,0.640849,0.549867,-0.041008,0.945534,0.101074,-0.054965,-0.205901,-0.365876,-0.317330,-0.407582,-0.037014,0.551167,-0.624601,0.975176,-0.259797,0.007994,0.095009,-0.372785,0.139506,0.659534,0.167854,0.871711,0.050675,0.058717,-0.019463,0.499914,0.549524,-0.001998,-0.612551,0.087174,-0.582024,-0.394894,-0.096160,-0.350200,-0.223987,0.044959,-0.076973,-0.202200,0.048272,0.664122,-0.615804,0.000858,-0.061028,-0.310483,0.449585,-0.205637,-0.085764,-0.560583,-0.508766,-0.571413,-0.042141,-0.407293,0.112179,-0.285993,1.163620,-0.882717,0.062825,0.395996,-0.117270,-0.851097,1.061707,0.118485,-0.178852,-0.574041,0.162395,0.538871,-0.319732,0.730746,-0.383904,0.325588,-0.161778,-0.252611,-0.249276,0.298106', '1483630', '1297514', '30159456', '34947776');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30323120', '酒精计划', '剧情', '本片将围绕马丁(米科尔森饰)和他三个朋友展开，这四个高中老师为了摆脱日常的循规蹈矩，开始了一项持续醉酒的实验。虽然计划最初很成功，但最终失败了。', '麦斯·米科尔森', '托马斯·温特伯格', 7.8, 80427, 'tt10288566', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2628440526.jpg', 0.3, 2, 25.7, 50.1, 21.9, '0.450848,0.055554,-0.414877,0.756426,-0.068444,-0.355690,0.735604,-0.120825,-0.580214,-0.728278,-0.041258,0.618492,-0.514296,-0.071154,0.430582,-0.459008,-0.220448,-0.481807,-0.049010,0.149436,-0.142130,-0.546159,-0.057375,-0.096142,-0.721465,-0.093848,0.843743,-0.054361,0.320272,0.644687,0.219467,0.142020,0.397334,0.152988,-0.050995,-0.008321,0.158329,-0.306402,-0.242798,0.515162,0.491365,-0.254746,0.082671,0.423286,0.268842,0.452486,1.062560,0.056477,-0.216654,-0.085530,0.132150,-0.744600,-0.369917,0.409151,0.420344,0.347294,0.191411,0.343109,-0.173809,0.036480,-0.265950,-0.190875,-0.899920,-0.005646,0.309459,-0.243069,-0.269239,0.387646,-0.176623,0.052854,-0.039843,-0.432586,-0.285830,0.831143,0.579019,0.213276,-0.681748,-0.013949,-0.735761,0.065100,0.869371,-0.397574,-0.204640,0.541295,0.068830,-0.681536,0.039724,-0.218996,0.029118,0.205646,-0.051966,0.241199,-0.229021,0.285047,-1.091834,0.085353,-0.457640,-0.325308,-0.180795,-0.937001,0.084199,-0.644937,-0.040218,-0.126956,-0.488563,0.049601,-0.436568,-0.505499,0.679724,-1.102139,0.275512,0.478329,0.256969,-0.281043,0.342795,0.699094,0.638618,-0.492934,0.070858,0.013233,0.028185,0.317561,0.111247,0.857414,0.250542,-0.368960,-0.533718,0.630827', '1420088', '2032339', '26759819', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30323687', '夜间小屋', '惊悚', '贝丝（丽贝卡·豪尔 Rebecca Hall饰）在先生欧文（伊万·乔尼凯特 Evan Jonigkeit饰）过世后，独自住在先生生前为她所建造的湖边小屋中，虽然她努力维持正常的生活，但恶梦仍朝她袭来，她感受到屋内似乎有一些不寻常的动静，而在朋友的建议下试图从先生的遗物中 找寻答案，于是她决心解开这令人不安的秘密……', '丽贝卡·豪尔', '大卫·布鲁克纳', 6.3, 13260, 'tt9731534', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2637498114.jpg', 3, 14.6, 52, 24.8, 5.6, '0.191737,0.219863,-0.714246,0.491361,-0.314365,-0.191125,0.971773,0.129716,-0.569210,-0.553732,0.291093,0.597354,0.284597,0.211155,0.044131,0.411408,-0.593201,-0.351666,0.225511,-0.179118,-0.260049,-0.482400,-0.405874,-0.313722,-0.153154,-0.423097,0.366098,0.156317,-0.065138,0.185535,0.053970,0.348923,-0.021087,0.750335,-0.222847,0.018440,0.203890,0.106291,-0.295866,0.324761,0.154152,-0.360175,-0.283772,0.489838,0.170695,0.494637,0.523398,-0.521381,-0.135427,0.488033,0.048433,0.017598,0.276347,0.249186,0.123049,0.187867,0.116591,0.317035,-0.427566,0.045723,-0.128711,0.053714,-0.483069,-0.025382,0.365492,0.394082,-0.579758,0.188881,-0.253827,-0.153085,0.091628,-0.403272,0.052675,0.338688,0.022377,0.076978,-0.392485,0.098213,-0.532690,0.021203,0.699526,-0.163407,-0.050929,0.482295,-0.425448,-0.280616,-0.016618,0.126315,-0.442688,-0.382900,0.019955,0.270348,-0.222612,0.022303,-0.389930,-0.106892,-0.123331,-0.057172,-0.244007,-0.442998,-0.206929,-0.469430,-0.158431,-0.298051,-0.134288,-0.273665,-0.008677,-0.439233,0.380237,-0.825170,0.294299,0.536911,0.237029,0.021625,0.698156,-0.143440,0.251398,-0.173174,-0.083879,0.329296,-0.172984,0.352503,0.150787,0.379179,0.186978,-0.027096,-0.715674,0.578226', '1296370', '1309172', '1309080', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30327842', '82年生的金智英', '剧情', '表面看来，金智英（郑有美 饰）是一个生活在幸福之中的家庭主妇，有一个收入不菲又温柔体贴的丈夫郑大贤（孔侑 饰）和一个非常可爱的女儿，在波澜不惊的日子里享受着每一天的平淡和安稳。实际上，金智英的内心早就如同地震一般的产生了天崩地裂的动摇，在她的身上背负着无比沉重的枷锁。婆婆面前，她要扮演逆来顺受的好儿媳。丈夫面前，她又是无条件支持他的贤妻。面对女儿，金智英必须隐藏起脆弱，做她无坚不摧的母亲。那么，真正的金智英究竟在哪儿呢？长久的压抑和挣扎中，金智英患上了心理疾病，郑大贤决定和妻子一起接受心理咨询，共同面对命运设置给他们的难题。©豆瓣', '郑有美', '金度英', 8.6, 353517, 'tt11052808', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2578045524.jpg', 0.2, 0.7, 10.9, 45.3, 42.9, '-0.015075,-0.053592,-0.677577,0.675450,-0.248478,-0.046726,1.053842,0.204660,-0.348660,-0.204604,0.311537,0.788655,-0.045385,0.394661,0.095541,0.117710,-0.106820,-0.656014,-0.166768,0.128251,-0.043734,-0.255358,-0.493406,-0.012793,-0.288250,-0.160884,0.503330,0.016542,0.133747,0.278689,0.532696,0.326228,0.160299,0.647003,-0.330508,-0.056649,-0.310891,0.301159,-0.165154,-0.006728,0.311212,-0.165927,0.053013,0.433109,-0.019411,0.310226,0.289837,-0.295315,-0.261402,-0.046861,0.376105,-0.172630,-0.171393,0.327234,-0.004697,0.067539,0.146855,0.064571,-0.465057,0.003703,0.341376,-0.168238,-0.881807,-0.353895,0.449217,0.109004,-0.833231,0.405733,0.245728,-0.075405,0.157872,-0.183792,0.199546,0.272555,0.193581,0.697205,-0.474970,0.081519,-0.433016,0.278051,0.622721,0.174851,-0.341570,0.186357,-0.554968,-0.390197,0.191542,-0.618907,-0.860769,-0.142362,-0.079122,0.096899,-0.178589,0.203465,-0.338094,0.177900,0.039685,0.137586,-0.205192,-0.820893,-0.014764,-0.212636,-0.146519,-0.713875,-0.468828,0.103636,-0.154008,-0.528799,0.844476,-0.889186,0.303693,0.214475,0.233494,-0.425486,0.569703,0.458485,0.148525,-0.343365,0.211633,0.206054,-0.288987,0.160894,0.174829,0.340754,-0.234475,0.309585,-0.381738,0.845147', '6745433', '24756472', '1299802', '1303077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30327897', '漫长的告别', '剧情', '本片改编自中岛京子同名小说，讲述原是中学校长的父亲(山崎努饰)被确诊为认知障碍后，他是如何和妻子曜子(松原智恵子饰)及两个爱女(竹内结子、苍井优饰)度过接下来的时光的。', '苍井优', '中野量太', 7.6, 32287, 'tt9657904', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2616359124.jpg', 0.3, 2.5, 29.4, 51.4, 16.4, '-0.153934,0.034132,-0.172100,0.620632,0.181181,-0.401375,0.340960,0.338343,-0.323819,-0.709728,-0.056403,0.407089,-0.159381,0.369711,0.073822,0.074069,-0.252843,-0.632753,-0.312043,0.018901,-0.245469,-0.231918,0.389730,0.254054,-0.298477,-0.209753,0.840047,0.030965,0.141177,0.068915,0.311352,0.746376,-0.369851,-0.327139,-0.021153,0.598077,0.098663,0.052432,-0.212841,0.461292,0.085109,-0.055272,-0.355275,0.126752,0.074085,0.193403,0.877982,-0.023707,-0.283373,-0.474623,0.457518,-0.209286,-0.117648,0.145025,0.095742,-0.084119,0.212944,0.449594,-0.494024,-0.071311,0.086096,0.151579,-0.751806,-0.164291,0.015836,0.231004,-0.486045,0.275089,-0.145687,-0.402620,0.331958,-0.227231,0.042636,0.526153,0.339659,0.139111,-0.179576,0.142646,0.180725,0.287195,0.800154,0.198540,-0.015870,0.555771,-0.041343,-0.238731,-0.065446,-0.076504,-0.431900,0.202473,0.077427,0.034830,0.055041,0.132971,-0.042179,-0.427270,-0.429340,-0.053129,0.323584,-0.273914,-0.189272,-0.379263,0.110640,-0.646979,-0.321713,-0.105771,0.423370,-0.883611,1.099386,-0.742746,-0.070941,0.265486,-0.206445,-0.215144,0.359625,0.303080,-0.091139,-0.272881,0.424134,-0.014675,0.265178,0.151620,0.118346,0.285795,-0.179223,0.053109,-0.685773,0.273437', '25880986', '3811356', '27602116', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30328584', '十二个想死的孩子', '悬疑', '當活着比死更需勇氣，十二個少年來到荒廢醫院，進行本以為是12 比0 的投票，通過後便可集體自殺，卻發現房間多了一具屍體，必須找出兇手和企圖破壞契約的潛入者。劇情以新本格派推理展開，同時進行「十二怒漢」式針鋒相對。原來再厭世，內心極渴望別人聆聽自己故事。每一個都可疑，每一個都隨時被說服，結局示範最令人心悅誠服的反轉。《20 世紀少年》（2008-09）、《愛的成人式》（2015）導演堤幸彥巧妙觸碰少年自殺的禁忌，像補完計劃般置諸死地，在絕望深淵，一次擁抱可拯救一個靈魂。', '杉咲花', '堤幸彦', 5.7, 10614, 'tt9214844', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2543516380.jpg', 5.8, 26, 49.3, 14.8, 4.2, '0.150019,-0.380865,-0.553432,0.586908,-0.257823,-0.262189,0.849162,-0.275408,-0.390316,0.292593,0.290533,0.722479,-0.191893,0.107442,0.025632,-0.372032,0.093505,-0.535617,-0.074561,-0.376213,-0.693221,-0.471114,-0.186250,0.029405,0.050977,-0.582596,0.919406,0.116677,-0.318120,-0.081015,0.038694,0.194613,-0.096872,0.609385,-0.624741,-0.210498,-0.244712,0.297184,0.139317,0.378236,0.026985,-0.362192,-0.566776,0.689178,-0.719517,0.457722,0.609107,-0.706876,-0.336774,0.034585,0.267988,-0.287473,-0.216302,0.144923,0.035861,-0.214527,0.303754,0.480639,-0.032144,0.189944,0.074397,0.097406,-1.187437,0.125276,0.397308,0.130429,-0.646165,0.288312,-0.022664,0.035839,0.404510,-0.401812,0.235027,-0.038460,0.301541,0.530136,-0.352165,-0.339546,-0.779198,0.350377,0.398374,0.191784,-0.600335,0.427633,0.355747,-0.670896,-0.085823,-0.669005,-0.218459,0.172899,0.104195,-0.069478,-0.047560,0.196846,-0.884410,0.088989,-0.401135,-0.155300,-0.301063,-0.502364,-0.044947,-0.087176,-0.023007,-0.214419,-0.098791,0.203488,0.646850,-0.743368,1.230555,-0.566625,0.251612,0.759426,-0.007661,-0.837824,0.575058,0.257702,-0.013528,-0.027256,-0.241288,0.094214,0.395151,0.132030,0.183093,0.749980,-0.309640,-0.011404,-0.690469,0.723558', '24284209', '27602116', '30163500', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3032912', '时尚先生', '剧情', '八卦杂志《雄辩》因爆猛料被停刊，为摆脱困境，主编李嘉吾（方中信）决定转做潮流杂志《时尚先生》。为了提高新杂志的知名度和影响力，他以《时尚先生》的名义和电视媒体合作操办了“时尚先生新秀大赛”。由于做《雄辩》时在娱乐、时尚圈树敌无数，李嘉吾难找可以博观众眼球的名人做毒辣评委。穷途末路之时，他昔日的恋人、当红影星叶菁（孔维）出现，她答应出任此次大赛的总评委。然而，她却是为报复李当年对她的伤害而来：参赛选手中，有她找来并精心包装的假小子廖宇（付静），也对李仇视的电脑高手符迦宁（吕玉来）亦被她找来做李的助手。©豆瓣', '方中信', '乔梁', 4.7, 5924, 'tt1475176', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2367003291.jpg', 17.2, 36.6, 39.3, 5.7, 1.2, '-0.057966,0.037132,-0.390831,0.571599,-0.095883,-0.206991,0.456465,0.124923,-0.295979,-0.319717,0.067641,0.711212,-0.472017,0.145364,0.321214,-0.245814,0.017982,-0.859573,0.033190,-0.062226,0.124026,-0.213871,-0.323652,-0.080776,-0.311467,0.178084,0.507299,0.009654,-0.451094,0.250029,0.632801,-0.021742,0.418625,0.525762,0.080537,-0.324822,-0.040752,0.151330,-0.333091,0.145629,0.296858,-0.443803,-0.260782,0.058365,0.203751,0.271641,0.541646,0.122900,0.032437,-0.150192,0.755423,-0.363327,0.351814,0.058616,0.232909,0.323646,0.125819,-0.017794,0.019116,-0.223478,-0.031521,-0.272732,-0.896369,0.220908,0.226587,0.030530,-0.294104,0.293435,-0.359448,-0.078304,0.007372,-0.190295,0.264580,0.164671,0.387070,0.026010,0.249603,0.333014,-0.141959,0.616879,0.449461,0.667497,-0.078878,-0.092328,-0.345853,-0.524237,0.285368,-0.330073,-0.494809,0.192575,0.244313,-0.386859,0.322507,0.025123,-0.501631,-0.242635,0.109866,-0.178409,0.249444,-0.394244,0.010202,-0.774647,-0.182934,-0.094276,0.144450,-0.283364,0.330931,-0.443869,0.885638,-0.740400,-0.165447,0.345461,0.429907,-0.768156,0.957339,-0.217429,-0.113647,-0.116505,-0.393702,-0.125985,-0.065102,0.460082,-0.001821,0.302759,0.501076,-0.441539,-0.218861,0.095514', '4301278', '2027945', '27602116', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30329892', '航海王：狂热行动', '动画', '《航海王：狂热行动》是“航海王系列”第14部剧场版，也是《航海王》动画二十周年纪念之作。以超新星为代表的众多航海家纷纷现身世界最大的航海家庆典——航海世博会。草帽航海团也收到了主办者费斯塔的邀请函，搭乘万里阳光号前往。原以为航海家们的狂热世博会只是为争夺“航海王罗杰留下的宝藏”，就在神秘宝藏争夺战如火如荼之际，阻挡在路飞等人面前的可怕威胁道格拉斯·巴雷特突然现身！暗藏阴谋的敌我混战一触即发……', '田中真弓', '大塚隆史', 7.5, 95461, 'tt9430698', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2570039912.jpg', 1.4, 5.6, 32.7, 36.5, 23.8, '-0.092226,0.078957,-0.876127,0.313477,0.496795,0.046352,0.310674,-0.109924,-0.004454,0.008091,0.483442,0.839984,-0.248767,-0.252476,0.345222,-0.163618,-0.296098,-0.475062,-0.280243,-0.172867,-0.220213,-0.166851,-0.189756,0.027837,-0.098770,-0.466827,0.805354,0.507239,-0.451390,0.460989,0.656798,0.392953,-0.311765,0.523409,-0.368111,-0.297747,0.248251,-0.106174,-0.231886,0.147002,-0.814863,-0.144708,-0.289168,0.183804,0.224963,0.118948,0.679695,-0.448852,0.005136,-0.111540,0.156637,-0.299068,-0.054019,-0.222330,0.461141,0.043066,-0.101664,0.267717,0.144569,0.240729,-0.269303,-0.286385,-0.937881,-0.025890,0.158397,0.164130,-0.419634,0.280585,-0.017139,-0.198332,0.431945,-0.007880,0.716872,0.251385,0.359045,-0.085163,0.324962,0.319023,-0.438644,0.132863,0.347007,0.004819,-0.090606,0.071853,-0.005843,-0.323337,-0.126974,-0.245314,-0.079376,0.169093,0.397881,-0.208078,0.274558,0.398894,-0.830375,0.042452,-0.238050,-0.467218,0.260663,-0.488560,-0.237882,-1.014914,0.218566,0.148401,0.042292,0.194460,0.160389,-0.148449,0.848868,-0.512246,0.468248,0.547183,0.034948,-0.256266,0.692312,0.133467,-0.079241,-0.153316,-0.063849,0.127366,0.253379,0.415612,-0.254841,0.096999,0.249853,-0.288059,0.012633,0.333914', '3318306', '25928048', '1322847', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30329902', '青春期猪头少年不做怀梦少女的梦', '剧情', '住在天空与海洋辉映的城镇“藤泽”的梓川咲太，就读高中二年级。他与既是学姐又是恋人的樱岛麻衣所度过的令人雀跃的日常，随着初恋对象牧之原翔子的出现而改变。不知为何，存在着“中学生”和“大人”两个翔子。出于无奈开始和翔子住在一起的咲太，受到“大人翔子”的捉弄，和麻衣的关系也变得尴尬。此时，“中学生翔子”身患重病的事实被发现，咲太的伤痕开始隐隐作痛——。', '石川界人', '增井壮一', 8.7, 31312, 'tt10472884', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2597748379.jpg', 0.9, 2, 11.7, 30.3, 55.1, '0.579479,-0.258365,-0.496209,0.524221,-0.034783,-0.247051,0.888382,0.290706,-0.417676,-0.530550,0.331856,0.781850,-0.467040,0.737032,0.134183,-0.167355,0.100673,-0.684225,0.040045,0.018961,-0.177062,-0.542108,0.030299,0.146555,-0.075542,-0.682647,0.921722,0.152403,-0.117478,0.619308,0.221283,0.447644,-0.216417,0.474156,-0.245731,-0.212454,-0.292382,0.349176,-0.232226,-0.032588,0.083626,-0.024885,-0.155332,0.126611,-0.125776,0.468508,0.788329,-0.108937,-0.270464,0.049553,0.542961,-0.278351,-0.015442,0.379944,0.581842,0.037049,0.012086,-0.020880,-0.072482,0.021791,0.009111,0.052747,-0.396036,0.252621,0.315497,0.463640,-0.474800,0.530008,0.001842,-0.631832,0.207960,-0.466453,0.200753,0.570421,0.243624,0.574484,-0.447057,0.121509,-0.540136,-0.084422,0.978116,0.234275,-0.389704,0.346417,-0.257587,-0.377429,0.088703,-0.086766,-0.558769,0.134123,-0.146586,-0.011278,-0.215293,0.298334,-0.618833,0.088640,0.048497,-0.264796,-0.033159,-0.576587,-0.335179,-0.257075,-0.232636,-0.591405,-0.276475,0.117392,0.185443,-0.377925,0.625816,-1.300750,0.073149,0.373643,0.180837,-0.233550,0.639910,0.316275,-0.005357,-0.085945,-0.329439,0.071783,0.080563,0.257794,0.250670,0.350046,-0.189206,0.240008,-0.443427,0.221408', '1292219', '35030151', '30345227', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3033030', '寻求正义', '剧情', '影片最早名为《饿兔子跳》，早在2009年就已摄制完成，但因为种种原因被一直拖延。中学教师威尔（尼古拉斯·凯奇 Nicolas Cage 饰）与妻子劳拉（詹纽瑞·琼斯 January Jones 饰）生活安稳而平静。但一切在劳拉遭到强奸后被改变了。威尔对嫌犯一无所知，而神秘人西蒙（盖·皮尔斯 Guy Pearce 饰）突然出现，称可以替威尔免费收拾对方，只要日后帮一个小忙。第二天，强奸犯就被发现自杀于家中，威尔感觉十分震惊。不多日，威尔接到指示，需要完成一件跟踪任务。完成任务后，本以为日后就可以可以相安无事，却不料西蒙要求他将另外一名嫌犯瓦尔恰克从天桥上推下，伪造成自杀。威尔拒绝执行，遭到西蒙以劳拉的性命作为威胁。无奈威尔只能答应，不料瓦尔恰克在与他的争斗中不幸坠桥身亡。瓦尔恰克死后，威尔遭到警察的拘捕，惊闻死者是报社记者阿兰。威尔逃离的警局开始亡命天涯，也在为寻求真相而努力......', '尼古拉斯·凯奇', '罗杰·唐纳森', 6.3, 6634, 'tt1214962', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1544471446.jpg', 1.5, 11.2, 60.7, 22.8, 3.8, '0.247285,0.064729,-0.440600,-0.096058,-0.362094,-0.269222,0.552394,0.050623,-0.325161,-0.401090,0.210350,0.708995,-0.113928,-0.275665,0.568638,0.170121,-0.428543,-0.526933,0.287061,0.085533,-0.019458,-0.712218,-0.081176,-0.508831,-0.266475,-0.342604,0.457057,0.188174,-0.214518,0.400260,0.154075,0.605633,-0.014908,0.421466,0.135909,-0.210526,0.086381,-0.496317,-0.096715,0.539739,0.181894,-0.297006,-0.001233,0.303047,-0.092000,0.288553,0.260046,-0.112484,-0.173380,-0.039051,0.050963,-0.377202,0.118805,0.307927,0.075875,0.075471,0.280272,0.447234,-0.180064,-0.249732,0.301600,-0.137639,-0.646072,0.249969,-0.291602,0.261954,-0.395320,0.203172,-0.512781,-0.059875,0.320111,-0.586043,0.073211,0.682056,0.348210,0.090181,-0.319914,-0.012615,-0.483390,-0.067177,0.363734,-0.103892,-0.091150,0.112504,0.389725,-0.426455,0.392730,-0.072171,-0.174139,0.099165,0.296662,0.335940,-0.282061,0.236111,-0.227900,-0.105984,-0.608589,-0.438542,-0.081276,-0.416106,-0.092929,-0.463689,-0.113944,0.228891,-0.665885,-0.180998,0.018157,-0.333407,0.054148,-0.889704,0.817320,0.375095,-0.045369,-0.490680,0.367994,0.236397,0.408969,0.141213,0.233306,0.280105,0.219505,0.530298,0.258060,-0.001405,0.049479,-0.382212,-0.493689,0.291801', '1304811', '1293145', '30345227', '1294559');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30330751', '二哥来了怎么办', '喜剧', '故事讲述了关于重组家庭里吵闹而又温馨的那些事。杨听风（胡先煦 饰）杨听雨（邓恩熙 饰）是一对兄妹，自从杨妈妈与李叔叔再婚后，五花八门的尴尬大戏便在重组家庭中一直上演。这一天，不速之客李圣（郑伟 饰）突然出现，平静的生活就此乱套……天降2哥？父母偏心？亲哥也倒戈？这一连串的巨变令杨听雨不堪忍受，只想大喊一句：2哥来了怎么办！', '胡先煦', '郑芬芬', 4.2, 19409, 'tt12565346', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2664990775.jpg', 31.6, 36.4, 24.1, 6.7, 1.2, '0.055952,-0.066668,-0.412874,0.236975,0.360611,-0.513042,0.873095,-0.208541,-0.599917,-0.345060,-0.211282,0.057665,-0.655290,0.392109,0.185328,-0.265268,-0.328131,-0.579236,0.096152,0.268526,-0.119541,-0.167876,0.284984,-0.418418,0.060287,0.088267,0.077765,0.251222,-0.249988,0.478240,0.527510,0.184765,-0.241204,0.467697,-0.063788,0.541601,-0.305972,0.968462,-0.426030,-0.340957,0.341111,-0.341616,-0.017541,-0.027673,0.223714,0.053193,0.398601,-0.287160,-0.247999,0.114417,0.334285,-0.062969,-0.309658,0.192703,0.352500,0.030308,0.318579,-0.156822,-0.327179,-0.281407,-0.230696,0.033929,-0.149242,0.076000,0.212058,0.167225,-0.253098,0.077612,-0.062260,0.033379,0.134074,0.029865,0.489383,0.456838,0.712211,0.944526,-0.179176,0.056848,-0.051986,0.297022,0.736683,-0.031565,-0.148903,0.104130,-0.160546,-0.178347,0.090726,0.133081,-0.502778,0.063226,0.066671,-0.306528,0.254566,0.532942,-0.313246,0.021247,0.085514,-0.199245,-0.095923,-0.457180,-0.049717,-0.125552,-0.012944,-0.169124,-0.036510,0.639285,-0.026538,-0.117399,0.482226,-0.410078,0.222704,-0.533850,0.339157,-0.466666,0.063385,0.166873,0.412512,-0.344750,0.312138,0.130327,-0.076003,-0.071276,0.218664,0.366916,0.142454,0.108730,-0.168506,0.273174', '30257386', '26366465', '35225859', '25845910');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3033085', '率性而活', '喜剧', '新上任的三圃市警署署长李承宇（孙秉浩 饰）为了挽回警察在市民心目中的形象，亦为个人大造政绩，异想天开决定实行一次银行模拟劫案演习，当然，对这次训练的态度警局众人心照不宣，大家都明白这不过是逢场作戏，然而被安排扮演劫匪的巡警郑度满（郑在泳 饰）却不这么认为。平时默默无闻行事一丝不苟的郑度满受命后全力研究劫匪作案手法，完全进入了角色。演习当日，郑度满的专业表现令所有人大惊失色，警方的便衣与突击队纷纷“阵亡”在郑度满的枪下，原计划在媒体面前大出风头的李承宇如意算盘落空，却又对郑度满无可奈何。究竟这次“劫匪”逞凶的演习该如何收场？本片剧本出自韩国著名编剧张镇之手，他的知名作品尚有《欢迎来到东莫村》等。©豆瓣', '郑在泳', '罗喜灿', 8.3, 70532, 'tt1193460', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p773565963.jpg', 0.2, 1.1, 16, 51.4, 31.3, '-0.021614,-0.154047,-0.454384,0.469056,-0.014681,-0.118476,0.195332,-0.058511,-0.452998,-0.434314,0.530487,0.616465,-0.169721,-0.216859,0.238838,-0.505026,-0.476263,-0.380963,-0.431007,-0.171782,0.075630,-0.364383,0.037266,-0.050634,-0.071757,0.235381,0.647525,0.145407,-0.115699,0.329623,0.532083,0.253843,-0.119147,0.214031,0.355497,-0.285654,0.185386,-0.119993,-0.446261,0.032949,-0.006829,-0.171346,-0.434982,0.234446,0.059561,0.360173,0.598408,-0.048446,-0.364144,0.178346,0.442087,-0.461802,0.145001,0.066293,0.247654,0.163510,0.031783,0.093793,0.143690,0.090680,-0.083569,-0.041030,-0.729677,0.082495,0.131346,-0.064509,-0.475757,0.283703,-0.088817,0.159805,-0.252972,-0.271589,0.276464,0.345370,0.404517,0.200828,-0.019869,0.093588,-0.467303,0.190029,0.307712,0.092171,0.010051,0.097292,-0.203442,-0.612354,0.050105,-0.230375,-0.218404,0.093917,0.049145,-0.213510,-0.038093,0.115528,-0.108348,-0.157657,-0.063330,-0.120507,-0.159416,-0.302835,-0.128502,-0.715957,0.010901,-0.040203,-0.256585,0.069801,0.173886,0.072997,0.409950,-0.931310,-0.215368,0.126153,-0.184780,-0.583244,0.328179,0.469253,-0.080891,-0.436811,-0.523340,-0.059244,0.400356,0.236172,-0.013756,0.269124,-0.041103,-0.606703,-0.328992,0.087214', '2369613', '1420088', '20388224', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30330875', '超能计划', '动作', '在新奥尔良的街道上，关于神秘新药丸的消息开始传播开来，这种药丸可以解锁每位使用者独特的超能力。但问题是：在服用之前，没人知道用药后会发生什么。一些人会进化出防弹皮肤、隐形能力和超强力量，也有很多人会表现出更致命的反应。但是，当药丸使城市内的犯罪升级到危险水平时，当地警察（约瑟夫·高登-莱维特饰）与一名少女小贩（多米尼克·菲什巴克饰）和誓报私仇的退伍士兵（杰米·福克斯饰）联手以硬碰硬，他们冒着服用药丸的风险，以追踪并制止制造出该药丸的团队。', '杰米·福克斯', '亨利·朱斯特', 5.7, 11865, 'tt7550000', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2614190404.jpg', 4.3, 25.4, 53.8, 12.6, 3.9, '0.134584,0.273280,-0.348758,0.465372,-0.257282,0.315074,0.684774,-0.032602,-0.769482,-0.147816,0.067656,0.495896,-0.165176,-0.203086,0.144029,-0.314709,-0.168586,-0.402542,0.259458,-0.272620,-0.764090,-0.614482,-0.545345,-0.470051,-0.141497,-0.796583,0.469175,0.034645,-0.495907,-0.001687,0.125199,0.195668,-0.035838,0.483368,-0.038149,-0.287947,-0.019443,-0.144716,-0.117789,0.430352,0.162143,-0.218455,-0.071908,0.184201,0.197427,0.255059,0.437455,-0.195425,-0.251019,-0.156830,0.330835,0.008372,0.169313,-0.075620,0.150995,0.126723,0.264684,0.008924,0.121456,0.278010,-0.028548,0.193630,-0.858084,0.018522,-0.033314,0.375601,-0.517319,0.026537,-0.198543,-0.188172,0.016888,-0.358247,0.165442,0.329667,0.217369,0.101451,-0.378685,-0.187490,-0.940153,-0.095288,0.471815,-0.152482,-0.445603,0.241673,-0.468644,-0.582679,-0.306638,-0.131360,0.006153,0.107696,0.263546,0.462299,-0.176584,0.069605,-0.553748,0.095865,-0.255380,-0.160491,-0.108853,0.250816,-0.052693,-0.790307,0.001589,-0.264262,-0.491733,0.156056,0.346886,-0.221673,0.745514,-0.821371,-0.130909,0.417160,0.426197,-0.376804,0.110700,-0.271333,0.103598,-0.214897,-0.477566,0.154427,0.259044,0.214219,-0.099483,0.500869,0.295407,-0.345491,-0.078819,0.180620', '1793491', '1946776', '24753477', '1401524');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3033092', '八面玲珑的申小姐', '喜剧', '广告公司客户主管申美珠（韩艺瑟 饰）是个超级自恋的潮女，整天幻想着能够钓到一个如意郎君。在她的生活中，先后出现了四个完全不同类型的男人，分别是：肌肉男人气歌手贤俊（孙浩英 饰）、准备司法考试的纯情男云洙（金仁权 饰）、富有的财团贵公子俊生（权五中 饰）以及成熟男东民（李宗赫 饰）。对于任何一个，美珠都不想放弃，因此她只能使出浑身解数游走于这些男人中间。她曾与肌肉男在健身房里大方上演姐弟恋；她曾甘愿做纯情男的精神支柱与情感源泉陪他到深山寺院进修；她曾沉浸在贵公子名车玫瑰和高级餐厅的诱惑中；她曾与眼中钉肉中刺的成熟男彼此拆台。起初，脚踏4只船的申小姐还游刃有余，但是后来却进入了作茧自缚的迷局……©豆瓣', '韩艺瑟', '朴庸集', 6.3, 5990, 'tt1213617', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2167465120.jpg', 2.2, 12.9, 58.3, 21.6, 5, '0.250095,0.052988,-0.557172,0.562180,-0.292181,-0.168611,0.821429,0.227949,-0.530080,-0.267340,0.121974,0.443934,-0.216783,0.290025,0.230847,-0.028739,0.056384,-0.728445,-0.111733,0.075229,0.075377,-0.216229,-0.349873,0.070183,-0.296329,-0.211051,0.657833,-0.046998,-0.191031,0.252578,0.643042,0.028476,-0.181084,0.264635,-0.382292,-0.139803,0.076460,0.084176,-0.284073,0.020933,-0.026654,-0.312699,-0.090495,0.079347,0.061369,0.190085,0.659295,-0.206096,0.001966,-0.047122,0.316492,0.150369,-0.212672,0.222467,0.078022,-0.128887,0.499156,0.029246,0.083246,0.088909,0.339018,-0.109889,-0.590783,-0.112145,0.161840,0.112935,-0.468067,0.424893,0.062847,-0.057819,0.056452,-0.236455,0.046096,-0.208212,0.127304,0.145220,-0.081066,0.099105,-0.565821,0.485773,0.624517,0.344266,-0.366788,0.343701,-0.176663,-0.411818,-0.267559,-0.419989,-0.684875,0.010703,-0.010754,0.010101,-0.099367,-0.003798,-0.677251,0.261208,-0.018968,0.078948,0.198268,-0.306499,-0.105407,-0.503524,-0.027954,-0.572725,-0.219805,0.322271,0.121749,-0.176368,0.616946,-1.047809,0.071201,0.369559,0.323783,-0.627731,0.950425,0.093773,-0.086242,-0.160138,-0.305208,0.136814,-0.103498,0.043082,-0.058084,0.561380,-0.260090,-0.051226,-0.391226,0.312451', '6518721', '3055049', '26354526', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30331149', '白蛇：缘起', '爱情', '幽暗洞中，白蛇（张喆 配音）苦苦修炼却不得其法，小青见此情景，将发髻上的碧玉簪子取下，令白蛇攥在手中。那一刻，五百年前的记忆瞬间苏醒。五百年前，晚唐君主昏聩庸碌，掌握邪术的国师只手遮天，命令天下百姓捕蛇修法。为了拯救族群，白蛇冒险行刺，结果却遭遇挫败，还失去了记忆。当她再度醒来，发现自己被一个专门捕蛇的村落所救下，而那个胆小却善良的青年许宣（杨天翔 配音）则吸引了白蛇的注意。与此同时，国师派出爪牙四处追寻白蛇的下落，而蛇族更误解白蛇叛逃人类，接二连三派出杀手。五百年后的一段姻缘，早在这乱世之间便已缔结……©豆瓣', '张喆', '黄家康', 7.8, 714519, 'tt9288776', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2544313786.jpg', 0.5, 3.3, 27.1, 45.3, 23.8, '0.038955,0.335456,-0.310879,0.459464,0.204580,-0.314700,0.600206,-0.188364,-0.466281,-0.312448,0.221712,0.264923,-0.158986,0.176471,0.112230,-0.057574,-0.085954,-0.590875,-0.201201,-0.068609,-0.219002,0.166826,-0.555248,-0.031738,-0.118812,-0.305835,0.867835,0.251986,-0.169036,0.488392,0.133516,0.084668,-0.358685,0.352095,-0.164717,0.006673,0.120266,0.066174,0.199988,0.021649,-0.308200,-0.712497,-0.018820,0.258261,-0.501901,0.356924,0.445818,-0.497692,-0.093854,-0.597484,0.297512,-0.211811,-0.188076,0.039485,0.443987,0.118853,0.087864,0.157362,-0.133030,-0.094417,-0.118601,-0.096825,-0.745890,0.016824,0.026556,0.278652,-0.259196,-0.048886,0.032315,0.281657,-0.144266,-0.384369,0.134442,0.205914,0.332726,0.028350,-0.295489,-0.111697,-0.283394,0.224969,0.513574,-0.401648,-0.248787,0.214714,0.035917,-0.537596,0.230762,-0.191475,0.035270,-0.213696,0.379301,0.221059,-0.144478,0.444164,-0.360417,-0.015497,-0.325415,0.298770,-0.030706,-0.047962,-0.274602,-0.130951,-0.169583,0.069275,-0.246717,0.078810,0.156639,-0.052766,0.519251,-0.303651,0.320104,0.556363,0.107807,-0.130838,0.525581,-0.146577,0.251812,0.020148,-0.008421,0.533994,0.030510,0.483290,-0.031018,-0.170279,-0.161693,0.039016,-0.568523,0.397961', '7051375', '3001114', '25827286', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30331424', '最普通的恋爱', '喜剧', '对分手的女朋友恋恋不舍的“在勋”（金来沅）。像平时一样以宿醉开始的清晨，发现自己和不认识的电话号码的某个人有通宵2小时的通话记录他得知电话那头正是！和自己互通姓名还不到24小时的职场同事“善英”。和男朋友处在有心结的分手中的“善英”（孔晓振）。到新公司上班的第一天，那个该说的不该说的全都说出口的和男朋友分手的现场偏偏！被同一个职场的“在勋”看到了。见面才一天时间，比起工作上的事情，反而对彼此的恋爱史更为了解的两人。但微妙的紧张感和尴尬都是暂时的即使是“不像话”“无语”的碰撞也还是牵挂为什么呢？', '金来沅', '金涵洁', 7.1, 15402, 'tt11041006', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2570803082.jpg', 0.7, 5.4, 43.2, 37.6, 13.1, '0.731660,-0.129383,-0.896976,0.430340,-0.057033,-0.398447,0.581508,-0.132433,-0.558738,-0.407914,-0.242714,0.722753,-0.489134,0.403880,0.176125,-0.163956,-0.289413,-0.903695,0.071739,-0.265220,-0.423662,-0.856606,0.035606,0.089230,0.145737,-0.084703,0.311509,0.000866,-0.190714,0.537316,0.319315,0.108790,0.041243,0.871427,-0.302078,-0.019604,-0.142973,0.455147,-0.240774,-0.077114,0.390872,-0.106433,-0.040558,0.289717,0.130550,0.812214,0.361401,0.097706,-0.581597,0.446349,0.478263,-0.125014,-0.328128,-0.074802,0.634156,0.105064,0.461570,0.173503,-0.202573,0.132938,-0.116094,0.105719,-0.610933,0.177767,0.053461,0.231806,-0.456313,0.711750,-0.124915,-0.289327,0.178653,-0.299146,0.436450,0.610116,0.000392,0.744410,-0.204780,-0.116666,-0.620619,0.022354,0.768281,0.264229,-0.206030,0.689857,0.124547,-0.590607,-0.248876,-0.141276,-0.467903,0.087716,-0.156746,0.194357,-0.313892,-0.147725,-0.629208,0.031155,0.125435,-0.106767,0.102253,-0.738949,-0.109533,-0.405973,-0.222278,-0.705396,-0.349804,0.449510,0.258210,-0.255061,0.604298,-1.288567,0.150999,0.360078,0.561699,-0.669456,0.743500,0.432073,-0.178691,-0.454419,-0.066096,0.019892,0.029059,0.127541,0.254450,0.277458,0.090718,-0.117675,-0.618983,0.328294', '1297052', '1308755', '2052978', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30331959', '黑水', '剧情', '基于Nathaniel Rich在《纽约时报》上发表的文章《The Lawyer Who Became DuPont’s Worst Nightmare》，围绕罗伯特·比洛特展开，他担任辩护律师长达8年之久，他对化工巨头杜邦公司提起了环境诉讼，这场官司揭露了几十年来杜邦公司化学污染的历史。', '马克·鲁弗洛', '托德·海因斯', 8.6, 124018, 'tt9071322', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2569450232.jpg', 0.1, 0.5, 10.3, 48.3, 40.7, '-0.161120,-0.261128,-0.446960,0.433314,0.128088,0.047384,0.570249,-0.123811,-0.716076,-0.111533,0.315222,0.324506,-0.680123,-0.007005,0.323449,-0.393734,-0.500334,-0.797955,0.153276,-0.282675,0.012478,-0.696621,-0.159917,-0.433441,-0.172343,-0.457754,0.429841,-0.116566,-0.491874,-0.017275,-0.141844,0.178341,0.202016,0.402521,0.445926,0.035845,0.009962,0.144247,-0.508803,0.301522,0.082130,-0.456496,-0.123549,-0.125038,0.298618,0.395626,0.215804,-0.285526,0.110862,-0.296406,0.549199,-0.480556,-0.072545,0.271090,0.889862,0.395818,-0.239524,0.792913,-0.550975,-0.319884,-0.124127,-0.495823,-0.559027,-0.088085,-0.248698,0.314643,-0.476433,0.957595,-0.357605,0.173232,-0.591379,-0.356167,-0.182995,0.155256,0.286826,0.191635,0.462902,0.183621,-0.277364,0.608473,0.516756,-0.093937,-0.131486,-0.003217,-0.238198,-0.251090,-0.702645,-0.575946,-0.155187,-0.331210,0.005048,-0.347593,-0.196635,0.711920,-0.715347,-0.203049,-0.130517,-0.658599,0.480826,-0.192601,-0.348056,-0.417495,-0.322567,-0.384109,-0.147901,-0.136400,0.100596,-0.694546,0.544738,-0.751320,0.343828,0.356274,0.166781,-0.239973,0.730436,0.200214,0.088020,-0.141885,-0.285522,0.340321,-0.017715,0.425669,-0.099893,0.157704,0.338867,-0.157782,0.110638,0.297899', '2245683', '1306544', '1303449', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30334073', '调音师', '喜剧', '双目失明的钢琴家阿卡什（阿尤斯曼·库拉纳 Ayushmann Khurrana 饰）为了参加国际大赛，平日里通过私人授课赚取经费。事实上他的眼睛完全正常，只不过希望通过这种方式感受不同的生活。因为一场意外，阿卡什结识了美丽的姑娘苏菲（拉迪卡·艾普特 Radhika Apte 饰）。凭借出色的演奏技巧，阿卡什在苏菲父亲经营的西餐馆谋得兼职。他的演奏不仅令食客们倾倒，更虏获了苏菲的心。某天，阿卡什接受过气的影星普拉默（安尔·德霍万 Anil Dhawan 饰）的邀请，登门为对方的妻子西米（塔布 Tabu 饰）演奏庆生，谁知却亲眼目睹了倒在血泊中的普拉默的尸体。惊慌失措的阿卡什假装镇定，虽然暂时骗过了西米及其情夫，但是他的秘密还是慢慢被人戳穿……本片改编自2010年的同名法国高分悬疑短片。©豆瓣', '阿尤斯曼·库拉纳', '斯里兰姆·拉格万', 8.2, 885546, 'tt8108198', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2551995207.jpg', 0.3, 1.8, 16.7, 49, 32.1, '0.185006,0.101159,-0.521649,0.423304,-0.067684,-0.191727,0.419114,0.083006,-0.271095,-0.247611,0.144537,0.563629,-0.221788,-0.053259,0.447393,-0.099513,-0.389554,-0.518943,0.041167,-0.173924,0.062370,-0.416656,-0.257274,-0.177278,-0.158384,-0.417110,0.488414,0.022721,-0.199203,0.561139,0.227673,0.186387,0.234030,0.061090,0.142965,-0.201665,0.281479,0.128394,-0.011660,0.033676,-0.106159,-0.091128,-0.220211,0.051334,0.309137,0.508565,0.507847,-0.225552,-0.007933,0.108426,0.309694,-0.060080,0.277651,0.056516,-0.049169,-0.068500,0.198898,-0.038428,-0.075317,0.016197,0.170848,0.030687,-0.957096,0.160260,0.356665,-0.102445,-0.434467,0.417099,-0.164036,-0.042558,-0.210395,-0.047469,0.042856,0.236254,0.363584,0.361968,-0.225401,0.131355,-0.319587,0.253426,0.343307,0.173400,-0.413824,0.331295,-0.410710,-0.610716,0.093228,-0.324738,-0.230767,-0.009403,0.201240,0.017622,-0.044536,0.295855,-0.388839,-0.221497,-0.341221,-0.198404,0.035594,-0.274720,0.002071,-0.807204,-0.130206,-0.281086,-0.093415,-0.299072,0.167198,-0.442593,0.651520,-0.727181,0.184803,0.454300,0.167974,-0.135203,0.602444,0.166145,0.014212,-0.113514,-0.452945,0.241568,0.070093,0.052573,0.067960,0.398821,-0.049656,-0.323352,-0.283348,0.426025', '1793491', '3318306', '27602116', '26259202');
