INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30334399', '三夫', '剧情', '本片是香港导演陈果妓女三部曲最后一部（《榴莲飘飘》，《香港有个荷里活》），本片讲述了一个奇特的妓女在香港的一条船上生活的故事。她有着超乎常人的性欲和三个丈夫，她将自己地献身于她的工作。用性来讽刺时代，这部电影充满了强烈的欲望。', '曾美慧孜', '陈果', 5.7, 27330, 'tt9076570', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2552829833.jpg', 7.7, 25.3, 45, 16.7, 5.3, '0.363628,-0.047805,-0.557662,1.037802,0.031880,-0.225750,1.019595,0.136428,-0.360555,0.070850,0.164815,1.037284,-0.074274,0.260428,0.013256,0.125393,-0.116527,-0.509628,-0.292922,0.070083,0.281580,-0.134575,-0.491933,-0.077699,-0.379917,-0.071393,0.770156,-0.104433,-0.512944,0.316130,0.566757,0.196348,0.073764,0.532198,-0.361875,0.147908,0.036103,-0.069660,-0.155803,0.410759,0.314392,-0.272681,-0.122503,0.315990,-0.409250,0.100784,0.698828,0.211379,-0.144801,-0.028064,0.779668,-0.128773,-0.273310,-0.013567,0.073671,0.140020,0.223305,0.150326,-0.223202,-0.014975,0.021199,-0.198966,-1.087622,-0.203571,0.096506,0.078178,-0.453564,0.350562,-0.160909,-0.047216,0.154666,-0.321567,0.018773,-0.303556,0.255975,0.535219,-0.068583,-0.018131,-0.455027,0.780908,0.624590,0.209819,-0.337399,0.582093,-0.561455,-0.495654,-0.409392,-0.037884,-0.873907,0.056770,0.460194,-0.363896,-0.398322,0.012136,-1.002360,0.023925,0.022674,-0.210892,-0.244513,-0.380450,-0.055794,-0.724471,-0.372850,-0.631802,-0.085115,-0.373462,0.496297,-0.250130,0.929689,-0.630770,-0.007321,0.853703,0.006859,-0.494408,0.892802,0.081490,0.087739,-0.144375,0.006768,0.216354,-0.416489,0.087663,-0.000404,0.699497,-0.054676,0.287949,-0.661719,0.818252', '22265121', '4267948', '34890458', '3603547');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30335059', '熊出没·原始时代', '喜剧', '熊大熊二光头强意外穿越回恢宏的石器时代，在原始部落与猛犸象、剑齿虎等一众奇特生物开启了眼界大开的奇幻之旅！原始时代瑰丽非常却又危机四伏，熊强三人组与一只可爱狼女一路相伴，笑料百出。原始部落纠葛不断，女族长竟对光头强情愫暗生……面对凶猛狼族的步步紧逼、原始人类的不断质疑、自然危机的全面爆发，熊强究竟何去何从？他们又能否回归现代？一场关于守护与成长、爱与勇气的冒险，拉开序幕……', '张伟', '丁亮', 6.6, 21667, 'tt10250750', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2541035591.jpg', 4.3, 9.8, 46.6, 29, 10.4, '-0.122829,0.133971,-0.716037,0.463189,0.313942,0.128827,0.622593,-0.284747,-0.307789,-0.118547,0.201847,0.520566,-0.188531,-0.083841,0.137411,-0.522561,0.033549,-0.247038,-0.041127,0.292223,-0.023190,0.013396,-0.686226,-0.132272,0.150119,-0.282421,0.582240,0.307993,-0.534460,0.563516,0.272382,0.285694,-0.709176,0.226952,-0.183576,-0.168341,-0.051997,0.448804,-0.256815,-0.190554,-0.182530,-0.116405,-0.338795,0.113892,-0.081174,-0.053631,0.623408,-0.635613,-0.396828,-0.381912,0.396493,-0.050320,-0.286570,0.433843,0.299916,0.016177,-0.079582,0.077845,0.417421,0.032307,-0.221369,-0.205199,-0.797988,0.093547,-0.034380,-0.029734,-0.454424,0.084949,0.316468,-0.187298,0.217402,-0.072067,-0.169856,0.217033,0.438683,0.611660,0.148990,0.143155,0.103103,-0.346084,0.811327,0.189683,-0.492167,-0.041660,0.020125,-0.577578,-0.231252,-0.205001,-0.455242,-0.173739,0.328377,0.339521,-0.185542,0.504188,-0.882436,0.405800,-0.319253,0.019692,-0.112282,-0.192578,-0.099275,-0.381770,-0.143534,-0.507087,-0.069445,0.297540,0.292557,-0.105746,0.833258,-0.534200,0.330520,0.425262,0.391478,-0.662575,0.306871,0.035271,0.000266,-0.424918,-0.282035,0.356811,-0.205217,0.119032,-0.027673,0.321605,-0.249340,0.014817,-0.295330,0.349528', '24284209', '35377026', '4181031', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30335799', '城市猎人', '喜剧', '北条司著名漫画《城市猎人》的法国真人版，Nicky Larson（寒羽良）是人称“城市猎人”的私家侦探，他集幽默、正义、欣赏美女的天性于一身，擅长处理五花八门的棘手任务，深受委托人信赖。阿香与寒羽良为多年搭档，两人看似相爱相杀，实则互相关心，有一天，阿香为两人接来了一单神秘生意——保护一瓶无论谁用了都会魅力大增的香水，神探寒羽良和阿香即将开启新的一次冒险旅程，这一切背后交织着怎样的阴谋，又有多少人卷入了这场啼笑皆非的大战中......', '菲利普·拉肖', '菲利普·拉肖', 6.9, 27492, 'tt8523334', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2626879808.jpg', 1, 6.7, 48.1, 36.6, 7.6, '-0.011044,-0.178904,-0.332643,0.451943,0.005478,-0.143793,0.365120,-0.162678,-0.534473,-0.321865,0.273012,0.728342,-0.264462,-0.119292,0.462237,-0.024318,-0.044037,-0.630945,-0.236139,0.005644,-0.256766,-0.233164,-0.699234,-0.175364,-0.042346,-0.207698,0.416910,0.278701,-0.234702,0.450501,0.683503,0.317909,-0.334150,0.177851,0.045168,-0.113827,0.108167,0.234778,-0.467779,0.191453,0.000440,-0.097388,-0.228344,0.029714,-0.157143,0.243885,0.528988,-0.136759,-0.286677,0.041162,0.492329,-0.412899,-0.174716,-0.152296,0.226728,0.230387,0.287415,0.346024,-0.198501,-0.171626,-0.035045,-0.088735,-0.900794,-0.386428,0.219204,-0.093325,-0.321878,0.438887,-0.016147,-0.161737,0.066351,-0.209704,0.122282,0.274412,0.662011,0.370180,0.220741,-0.019589,-0.218644,0.230930,0.831349,0.169885,-0.161248,0.293067,-0.208831,-0.240294,0.005832,-0.473843,-0.471326,0.193733,0.322518,-0.073385,0.181573,0.291131,-0.762417,0.209261,-0.189249,0.098978,0.148007,-0.425609,0.097690,-0.636312,-0.338997,-0.562826,-0.111953,0.014210,0.296231,-0.265142,0.922272,-0.870122,0.041072,0.573814,-0.091710,-0.482910,0.549303,0.394661,0.110569,-0.235074,-0.089803,-0.044393,0.077148,-0.106281,0.111126,0.348680,0.189178,-0.058434,-0.326331,0.143400', '4301278', '24284209', '27602116', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30336307', '俑之城', '动画', '地下世界，千奇百怪，不仅生活着兵马俑，还有各种各样的青铜文物复活的青铜兽和一种叫做“地犼”的地底原生生物。地犼与俑的战斗旷日持久，男主角蒙远是地下秦陵中一打杂的杂役俑，他和神秘少女史玉合作抓捕地犼、经历险境，不料却发现地犼与兵俑战斗不息的谜团，却因此遭遇更大危机......', '朱光祖', '丁亮', 5.9, 23229, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2656628179.jpg', 4.5, 24, 51.1, 15.3, 5, '0.085604,-0.023009,-0.867130,0.711902,-0.016781,-0.042391,1.196014,-0.175731,-0.338764,-0.382935,0.566493,0.556982,-0.014996,-0.027510,0.086995,-0.154588,0.001135,-0.665751,-0.701149,0.235125,-0.490468,-0.074763,-0.723045,-0.163847,-0.230640,-0.354767,0.959470,0.467660,-0.261134,0.356599,-0.058468,0.508439,-0.494284,0.503621,-0.137028,-0.155615,-0.172062,0.263833,-0.155545,-0.051691,-0.508180,-0.025370,-0.419725,0.186007,-0.314041,0.019123,0.630249,-0.812789,0.146940,-0.173013,-0.120922,-0.011722,-0.150562,-0.222788,0.454557,0.092667,0.148357,0.266075,0.015341,0.079759,0.362885,0.133973,-0.584757,-0.039332,-0.096513,0.403244,-0.452023,0.218930,0.447090,0.239446,0.066962,-0.094016,0.271616,0.111860,0.699925,0.567360,-0.005535,-0.111310,-0.554720,0.007356,0.282078,-0.125483,-0.446052,-0.171485,-0.188194,-0.969369,-0.505315,-0.219735,-0.110102,-0.132166,0.293057,0.306320,-0.426801,0.475783,-1.293003,0.257580,-0.361741,-0.092016,-0.282246,0.048528,-0.294852,-0.756672,-0.064929,-0.406635,-0.495035,-0.035376,0.177443,-0.159140,0.613458,-0.611431,0.099532,0.669049,0.329931,-0.215572,0.501640,-0.025499,0.010068,-0.295104,-0.297989,0.003012,-0.189089,0.434205,-0.124853,0.239450,-0.057100,-0.183188,-0.673451,0.455108', '1467779', '26290398', '1293515', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30337147', '那年1987', '剧情', '电影以来自山东的叔侄俩叶振云和叶川，结伴来到改革开放初期的“花花世界”广州，在火车上相遇了同乡女大学生刘芳为开头。在三人一次次的不期而遇中，上演了一段在理想和情感之间徘徊的青春修炼曲。然而就在此时，香港商人李想的出现，又将这段错综复杂的感情推向另一个高潮。在男女主人公的爱情面临各种命运考验的同时，还背负着自身对于人生未来的迷茫和追求。他们的未来将何去何从？一场跨度30年的恋曲相伴着一条充满荆棘挑战的创业之路，在电影诗歌般的叙事结构中，显得更加荡气回肠扣人心弦。', '吴永淦', '余斌', 6.3, 2332, 'tt9060288', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2535396971.jpg', 4.6, 22.2, 37, 24.1, 12, '0.346406,-0.128460,-0.750931,0.898698,0.230783,-0.412237,0.947850,0.108656,-0.399489,0.006562,0.235074,0.738792,-0.394346,0.289432,0.597462,-0.626331,-0.196884,-0.839125,-0.204753,-0.140828,-0.158652,-0.501519,-0.181374,0.122928,-0.302550,-0.272472,1.079747,0.279930,-0.412988,0.564535,0.292292,0.195028,-0.627078,0.347919,-0.239087,-0.021252,0.013579,0.393310,-0.676774,0.102007,0.131805,-0.359692,-0.112254,-0.054229,-0.433549,0.065804,1.043538,-0.262497,0.034448,0.283833,0.636181,-0.176553,-0.327281,-0.018025,0.307716,0.164428,0.072983,0.275604,-0.154476,0.030574,-0.069209,-0.313571,-0.837374,-0.104956,0.073328,0.189909,-0.568586,0.632119,0.367511,-0.178865,0.257834,-0.277521,0.173110,0.642832,0.584483,0.831911,-0.296562,-0.029150,-0.376943,0.223516,1.073898,0.270655,-0.291568,0.483284,-0.227499,-0.394719,-0.255185,-0.096030,-0.743031,-0.229360,0.330604,0.077379,-0.218512,0.464135,-0.853796,0.362869,0.117141,-0.194227,0.249268,-0.569634,-0.091470,-0.773331,-0.295325,-0.721995,-0.258650,0.201411,0.380272,-0.512314,0.909305,-0.891927,0.080158,0.471324,0.261273,-0.282328,1.000014,0.146715,0.317433,-0.258187,-0.158967,0.370241,-0.229834,0.236341,-0.069305,0.394402,-0.440158,0.392967,-0.733018,0.760531', '3811356', '2053515', '2334814', '35287908');
