INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30337760', '在无爱之森呐喊', '惊悚', '《在没有爱的森林呐喊》审视了人类行为的黑暗面，讲述了冷酷无情的村田丈利用自己的魅力来操纵周围的人。村田认识了信和一群胸怀抱负的电影制作人，他们认为村田以及他与美津子的多 磨的感情关系是完美的电影主题。在拍摄期间，这群人的关系越来越亲密，谎言与真相变得难以区分，人性的极限也受到了考验，导致了各种令人毛骨悚然的行为。在怪诞出奇的作品的《冰冷热带鱼》和《恋之罪》之后，富有远见的导演园子温又在新作品中展现了自己的才能。', '椎名桔平', '园子温', 6.9, 9712, 'tt10589914', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2571542101.jpg', 3.9, 10.3, 37.2, 33.8, 14.8, '0.228166,-0.108701,-0.783638,0.958174,-0.171853,-0.057597,0.935006,0.326058,-0.588175,-0.067931,0.158112,0.643294,-0.273831,-0.065982,0.050426,-0.328054,-0.216833,-0.722112,-0.314556,-0.109522,-0.105672,-0.510518,-0.318271,-0.393421,-0.056457,-0.589562,0.577210,0.053411,-0.743551,0.261310,0.344467,0.143972,0.044220,0.586843,-0.145518,-0.144274,0.151059,0.243969,-0.254556,-0.093206,-0.034707,-0.277289,-0.138625,0.541808,-0.303674,0.415229,0.889460,-0.224234,-0.483784,0.136194,0.614653,-0.154711,0.154377,0.189830,0.192494,-0.072889,0.182231,0.399300,-0.121557,0.069959,-0.101011,0.045075,-1.376522,-0.164802,0.211834,0.013743,-0.542233,0.603122,0.048325,-0.358165,0.131008,-0.257745,0.326115,-0.065959,0.502427,0.544669,0.060192,-0.156847,-0.354434,0.231411,0.613713,0.055192,-0.479946,0.793267,-0.614966,-0.585909,-0.612070,-0.421758,-0.452581,-0.220575,0.406495,0.068025,-0.409393,0.304443,-0.722555,-0.001895,0.054995,-0.250753,-0.032914,-0.589585,0.044160,-0.618243,-0.412654,-0.871756,-0.254896,-0.015908,-0.023341,-0.405413,1.042978,-0.796292,-0.087512,0.674033,0.243066,-0.582015,0.747231,0.241180,-0.366842,-0.111488,-0.166535,0.135132,-0.033726,0.185424,0.300001,0.626955,0.014740,0.071201,-0.686378,0.769288', '35360296', '1303542', '6844861', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30337935', '亲密旅行', '剧情', '吊儿郎当的专车司机沈童，接到一个从北京到舟山的长途订单，乘客有点特殊--8岁的男孩男男和一条叫伽利略的狗。看在酬劳的份上，沈童不情不愿地接下了这个订单，开始了北京前往舟山的驾车旅途。一路上的旅程，经历各种各样的事情，沈童和男男之间发生了微妙的变化，直到旅途临近结束，沈童才发现他和男男之间，也许存在着某种关系。旅途到达终点，沈童才明白：生活给他开了一个巨大的玩笑！这一路炎炎夏日的海滨旅途，治愈了两颗孤单的心，他们转身开始了各自人生路上新的旅程。', '沙俊伯', '沙溢', 5.3, 5094, 'tt11015340', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2569102032.jpg', 8.8, 34.4, 46, 7.2, 3.6, '0.301227,-0.100414,-0.569790,0.416664,0.055611,-0.463480,0.840561,0.020676,-0.414069,-0.026706,0.092827,0.724929,-0.394205,0.212917,0.926790,-0.048175,-0.422085,-0.400718,0.053510,-0.312253,-0.495914,-0.163976,0.087666,0.152876,0.013708,-0.136309,0.640499,0.161795,-0.095860,0.849291,0.144791,-0.066134,-0.088804,0.479268,-0.526023,0.120668,-0.047936,0.180454,-0.052719,0.051237,0.196648,-0.165755,-0.137627,0.044698,-0.066457,0.409059,0.882703,-0.001600,-0.392544,0.170763,0.245343,-0.216082,-0.157964,-0.225462,0.425745,0.287064,0.010689,-0.108123,-0.112532,-0.184786,0.023838,0.161417,-0.162452,0.009661,-0.405374,0.186470,-0.332852,0.506446,0.144018,-0.275354,0.127790,-0.848804,0.252786,0.402672,0.238207,0.253674,-0.205046,-0.006301,-0.427278,0.153894,0.912090,0.098139,-0.275482,0.533367,-0.074829,-0.541194,-0.166111,0.117164,-0.652088,-0.028474,0.422192,0.138807,-0.458576,0.006263,-0.775074,0.290391,-0.062128,-0.256291,-0.043268,-0.374452,-0.139771,-0.680062,0.003292,-0.522320,-0.031657,0.199531,0.194386,-0.047372,0.467313,-0.546598,0.185234,0.649153,0.213518,-0.414799,0.693748,0.045337,0.361104,-0.341731,0.235647,-0.073437,-0.156613,0.647295,0.061014,0.588218,-0.379319,0.012866,-0.338163,0.281937', '26687241', '1291992', '1299433', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3033864', '地道战', '战争', '1942年，日军侵华的战火烧到了冀中平原。俯首称臣只有死路一条，奋起反抗才是最终的出路，冀中的人民都动员起来共抗日军了，高家庄更是调集了大量民兵。为了对抗日军的飞机大炮，当地人民利用地貌开凿出了一条条错综复杂的地道。民兵队长高传宝（朱龙广 饰）利用这些巧妙的地道，率领 民兵与日军展开迂回作战。虽然曾因队伍里的败类汤丙会的出卖而吃了不少苦头，但是智勇双全的高传宝最终率领队伍利用地道围剿了日军，清理了汤丙会，并活抓了日军领队山田。地道战的胜利奏响了冀中反日的最强音。©豆瓣', '朱龙广', '任旭东', 8.3, 63322, 'tt1110246', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2551228401.jpg', 1.3, 1.6, 15.6, 44.7, 36.8, '0.180760,-0.299714,-0.560519,0.598606,0.131983,-0.289779,0.235388,-0.052069,-0.287769,0.292682,0.339257,0.163080,0.472838,-0.414935,0.091032,-0.526524,-0.282149,-0.790140,-0.340777,-0.060517,-0.166714,-0.288777,-0.331610,-0.314778,0.007132,-0.021231,0.727530,0.462300,-0.412776,0.340852,0.052502,0.054826,0.415157,0.200802,0.025288,0.056264,-0.077507,-0.532966,-0.102986,0.055692,-0.392372,-0.588937,-0.251769,0.128000,0.081397,0.698684,0.730504,-0.546854,0.122804,-0.031208,-0.138392,-0.557489,-0.048521,0.074516,0.501724,0.179797,-0.056918,-0.076150,-0.062067,0.174852,-0.208225,0.188767,-0.597815,-0.304856,0.062930,-0.249418,-0.521281,0.565192,0.158139,0.264873,0.196365,-0.253658,0.111090,0.832926,0.006813,0.206908,-0.240817,0.009462,-0.592626,0.294651,0.503952,-0.443919,-0.006518,-0.435607,-0.248261,-0.401014,0.055919,-0.495350,0.158975,-0.299208,0.360014,-0.242037,0.207464,0.161820,-0.982879,0.029902,-0.331706,-0.374323,0.001625,-0.144087,-0.073235,-0.739302,0.014674,-0.217932,-0.082721,0.457920,0.180427,0.227071,0.795228,-0.632285,-0.216134,0.440210,0.147497,-0.494375,0.086798,0.249866,-0.069669,0.221804,0.234696,0.100905,-0.069342,0.768034,0.627180,0.495555,-0.330708,-0.490362,-0.129480,0.036595', '1291860', '5361544', '1296909', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30340038', '吉祥', '剧情', '她叫王丽丽，是一个从东北小城来北京打工的女孩。丽丽的父亲名叫王吉祥，中年得病，脑子痴呆，丽丽妈妈执意离婚并带她离开。春节前夕，奶奶突然辞世，丽丽返回东北老家，面对生死离别，也面对家族的矛盾冲突。', '王吉祥', '大鹏', 7.8, 12740, 'tt9303734', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2540195487.jpg', 0.3, 1.7, 21.4, 59.9, 16.7, '0.108034,-0.079235,-0.482075,-0.463153,-0.220616,-0.542094,0.572335,0.316074,-0.328488,-0.464287,0.351427,0.828559,0.298152,0.342161,-0.097984,0.115131,0.040304,-0.036666,0.496500,0.177147,0.125626,-0.142895,0.591089,0.030117,0.314749,0.231611,0.038916,-0.613330,-0.121394,0.939248,0.177916,0.227362,-0.283369,0.686794,-0.267095,0.388145,-0.180915,0.144252,-0.539059,-0.047781,0.156173,0.166542,-0.170557,-0.212773,0.278618,0.284232,0.256144,0.256514,-0.033458,-0.087296,0.195147,-0.266202,-0.598568,0.085515,0.438231,-0.227574,0.405624,0.278338,-0.325223,-0.305765,-0.293180,-0.140205,0.104690,0.602786,0.225832,0.385209,-0.462792,-0.275743,0.127738,-0.272036,0.528897,-0.401672,0.503744,0.568898,-0.259946,0.789899,-0.293455,0.336278,-0.324529,0.085756,0.535705,-0.392868,0.139001,-0.154712,0.120754,0.013704,0.614129,-0.113383,-0.685669,0.319143,-0.368872,-0.529274,-0.287514,0.032959,-0.584902,-0.019599,-0.498592,0.105131,0.331041,-0.298150,-0.424114,0.139430,-0.093600,-0.104184,-0.175586,-0.102036,0.065273,0.400582,0.535056,-0.597393,0.088451,0.404834,0.997044,-0.799236,0.241243,0.468714,0.044033,-0.597451,0.161718,0.603200,-0.310189,0.599476,-0.498536,0.068167,0.042833,0.125881,-0.092693,0.171654', '1857175', '4896894', '1304304', '1294911');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30344474', '暗处的女儿', '剧情', '莱达（奥利维娅·科尔曼饰）一个人前往海滩度假，在海滩上，她注意到一对年轻母女，并难以移开视线。她们之间引人注目的关系，以及她们吵闹、绝非善茬的家庭成员都让莱达感到不安，她想起自己刚做母亲时的恐惧、困惑和种种劳苦。一个无心之举，更是将莱达抛入了连她自己都感到陌生和不祥的内心世界，在那里，她看到了自己的过去：在她还是一名年轻妈妈时，她做出了非同寻常的选择，并迎来一系列后果。该片是玛吉·吉伦哈尔的导演处女作，她将埃琳娜·费兰特的小说改编为该片的剧本。《暗处的女儿》主演阵容还包括达科塔·约翰逊、杰西·巴克利、艾德·哈里斯、彼得·萨斯加德、保罗·麦斯卡和达格玛拉·多敏齐克。', '奥利维娅·科尔曼', '玛吉·吉伦哈尔', 7.5, 14779, 'tt9100054', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2689478834.jpg', 0.7, 3.3, 31, 48.4, 16.6, '0.543968,-0.174976,-0.975723,0.654279,-0.077192,-0.390685,0.982355,0.110084,-0.460759,-0.173244,0.299496,1.008494,-0.375356,0.211056,0.307969,0.374618,-0.527994,-0.823971,0.006044,-0.182366,-0.063226,-0.500981,-0.239696,-0.340105,-0.143623,-0.382103,0.276318,-0.128564,-0.088826,0.336316,0.482860,0.280520,-0.040869,0.701117,0.090765,0.297606,0.053936,-0.309176,-0.183225,-0.047768,0.143127,-0.097179,-0.441114,0.461506,0.056476,0.504829,0.612665,-0.258292,-0.057905,0.156493,0.256795,-0.209472,0.277705,0.143590,0.146566,-0.245496,0.037014,0.024209,-0.180184,0.233923,0.092251,0.129506,-0.740296,0.308250,0.036171,0.344119,-0.492841,0.342796,-0.187177,-0.118605,0.193378,-0.440737,0.050353,0.057712,0.219901,0.219752,-0.181175,-0.094122,-0.363782,0.000945,0.562296,0.274921,-0.184333,0.307456,-0.336562,-0.484046,-0.136172,0.016155,-0.735197,0.010750,0.432165,0.018217,0.078381,0.320076,-0.364580,-0.135052,-0.292705,-0.288559,-0.182601,-0.430319,-0.023287,-0.607063,-0.051639,-0.429798,-0.557707,-0.169059,0.041815,-0.349815,0.554532,-0.481830,0.152936,0.582591,0.190505,-0.072402,0.547366,-0.024845,0.162290,0.030998,-0.400706,0.388755,0.046931,0.185860,0.162252,0.424886,0.025277,0.204458,-0.300554,0.676585', '1309172', '34461680', '34890458', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30345226', '若能与你共乘海浪之上', '爱情', '向水日菜子（川荣李奈 配音）是一位冲浪爱好者，对大海有着强烈的热情和真挚的喜爱，只有在风口浪尖处，她才能够感受到自己真正的在活着，可是别看日菜子在海上神气活现，在生活里，她其实是一个多思多虑的女孩，对未来感到深深的迷惘。一场活在让日菜子结识了名为雏罂粟港（片寄凉太 配音）的消防员，勇敢正直的港很快就吸引了日菜子的注意，两人一拍即合走到了一起，开始了一段充满了幸福的恋情。可是好景不长，一场海难夺走了港的生命，日菜子无法接受竟然是自己挚爱的大海夺走了她最爱的人。某日，陷入消沉许久的日菜子哼起了两人在一起时经常会唱的那首歌，令她没有想到的是，港竟然出现在了自己的面前。©豆瓣', '片寄凉太', '汤浅政明', 7, 49537, 'tt9193612', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2574029074.jpg', 0.7, 7.3, 44.7, 37.7, 9.5, '0.274351,0.070247,-0.819107,0.591259,-0.095569,-0.280129,0.898808,0.085160,-0.372808,0.170399,0.078003,0.976327,-0.279294,0.576508,0.378858,0.179873,-0.122137,-0.812877,-0.259221,-0.247147,-0.289797,-0.323929,-0.164035,-0.081880,-0.190048,-0.572176,0.584814,0.332460,-0.204310,0.384771,0.512599,0.146644,0.068616,0.761675,-0.290617,0.038417,0.139538,0.137142,-0.312358,0.415095,0.042412,-0.402653,-0.274516,0.490320,-0.077913,0.076858,0.860319,-0.264110,-0.509738,-0.139454,0.464587,-0.408144,-0.063000,0.138732,0.307761,-0.105112,-0.072704,0.097902,-0.628199,0.001584,0.082832,0.046762,-0.725804,-0.104654,0.005310,-0.007053,-0.666719,0.490603,0.189946,-0.417935,0.407876,-0.310724,0.318866,0.326493,0.005174,0.439733,-0.078133,-0.053573,-0.358440,0.284002,1.144611,0.070605,-0.173229,0.571891,-0.041638,-0.374862,-0.116787,-0.141934,-0.573696,-0.057853,0.226449,0.159957,-0.418066,0.185970,-0.493624,0.190323,-0.089344,-0.402121,0.396480,-0.551445,-0.327608,-0.366006,-0.180066,-0.812101,-0.241453,0.240971,-0.089424,-0.499734,0.846581,-1.124109,0.317354,0.733179,-0.094130,-0.149943,0.903608,0.338060,-0.454887,-0.182096,0.185964,0.192657,-0.127796,0.077815,0.379231,0.476477,-0.209236,0.187633,-0.466389,0.618791', '1292219', '4275444', '30162520', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30345227', '回归之路', '剧情', '一个曾经的篮球明星在与酒瘾作斗争时失去了妻子与家庭，为了能够找回自我选择回到母校为一支高中篮球队做教练，同时也要继续防止自己再次被酒瘾控制。', '本·阿弗莱克', '加文·欧康诺', 6.7, 6465, 'tt8544498', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2584332087.jpg', 1, 6.7, 54.6, 29.6, 8.1, '0.154678,0.135347,-0.235489,0.757937,-0.421891,-0.839642,0.605022,0.178028,-0.626729,-0.484283,-0.085689,1.219202,0.071969,0.397451,0.216721,-0.518502,0.008368,-1.442283,0.184194,-0.001774,-0.296805,-0.527188,-0.016429,-0.099695,-0.463823,-0.407854,1.134380,-0.095226,-0.226414,0.170348,0.235132,0.435577,0.387379,0.242300,-0.283849,-0.302643,-0.230390,0.096718,-0.739628,0.634113,0.460120,-0.322923,-0.282700,0.190871,0.099356,-0.050049,1.025582,-0.231671,-0.252132,-0.698867,0.219909,-0.245077,-0.117179,0.353551,0.104043,0.178500,0.359135,0.158063,-0.211548,0.414504,0.201865,-0.517930,-0.981662,-0.254386,0.131212,-0.280752,-0.794241,0.365407,-0.053148,-0.168271,0.562120,0.051710,0.327247,0.776573,0.539922,0.397489,-0.862685,0.118313,-0.113149,0.213610,1.147162,-0.143627,0.032764,0.276549,-0.178319,-0.204586,0.145062,-0.378489,-0.482193,0.174062,0.113876,0.408389,-0.158637,0.122255,-0.732800,-0.223135,-0.238614,-0.289522,0.360529,-0.801668,0.092687,-0.107349,0.022235,0.283236,0.177013,0.093869,-0.069161,-0.305571,0.702386,-1.658072,0.193949,0.829938,0.237339,-0.896385,0.438749,0.260401,0.447391,-0.422805,0.171824,-0.058560,-0.089916,0.638949,-0.100632,0.194090,-0.087455,-0.111555,-0.396333,0.314508', '35030151', '1301022', '2027925', '1296569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30346025', '电话', '剧情', '为了探望患病的母亲（金成铃 饰），金书妍（朴信惠 饰）返回了家乡。自从父亲死后，金书妍和母亲之间的关系跌落到了冰点，她认为母亲应给对父亲的死负全责。金书妍不小心将手机落在了火车上，无奈之中，她只得暂时用家中的一台固定电话和外界联系。一天，电话响了，在电话另一头的，是一位名叫吴英淑（全钟瑞 饰）的女孩。很快，金书妍就发现，这台电话似乎拥有穿越时间的特使能力，而吴英淑并非和自己生活在同一时代，而是十年前生活在这幢房子里的某个女孩。根据吴英淑的叙述，她被信奉邪教的母亲（李艾 饰）囚禁在家中，过着生不如死的日子，随着时间的推移，两个女孩之间逐渐建立起了友谊。而金书妍亦发现，就在不久之后，十年前的吴英淑将会葬身火海。©豆瓣', '朴信惠', '李聪贤', 7.6, 146362, 'tt10530176', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2624028650.jpg', 0.7, 2.8, 28.8, 50.2, 17.6, '0.351457,0.398835,-0.486635,0.648913,-0.220706,-0.255545,0.686587,0.239586,-0.500455,-0.331581,0.177393,0.640292,-0.071459,0.201345,0.267899,0.031640,-0.469105,-1.002805,0.037916,-0.480557,-0.314703,-0.731105,0.109419,0.129023,0.002759,-0.335478,0.326435,-0.257820,0.197305,0.502766,-0.022340,0.214249,-0.527991,0.291125,-0.239121,0.337767,-0.112156,0.295071,-0.054385,0.119092,0.353892,-0.504747,0.042627,0.184087,0.139921,0.201990,0.775850,-0.299035,-0.195480,-0.201592,0.232582,0.093392,-0.087714,0.005142,0.521686,0.169485,0.502463,0.562942,-0.568845,0.026602,0.134885,0.051930,-0.515818,0.364411,-0.130066,-0.061669,-0.483280,0.667820,-0.318370,-0.049565,-0.296900,-0.341175,0.683299,0.846985,-0.067221,0.583679,-0.525703,-0.068038,-0.236324,0.141319,0.477686,-0.048430,0.149807,0.558870,0.016914,-0.232331,-0.317970,0.086003,-0.725699,-0.230560,0.408675,0.217927,-0.282281,-0.060579,-0.598740,0.102948,-0.339222,-0.152265,0.172238,-0.031329,-0.078977,-0.233386,-0.245896,-0.383007,-0.412317,0.152109,-0.194792,-0.279803,0.712248,-0.898652,0.362342,0.262871,0.551673,-0.580473,0.555099,-0.002473,0.081791,-0.201591,0.229926,0.357111,-0.075252,0.296951,0.041756,0.142023,-0.181979,-0.138489,-0.672219,0.595590', '26809007', '30345227', '1307146', '25777330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30346880', '银行家', '剧情', '影片改编自真实故事，20世纪50年代的美国，从小励志改变命运的黑人企业家伯纳德（安东尼·麦凯 饰）和乔（塞缪尔·杰克逊 饰）在种族制度的枷锁下，创业处处受阻。不得已他们想出奇招，雇佣白人马特（尼古拉斯·霍尔特 饰）来扮演他们产业帝国的“老大”，伯纳德和乔则扮成门房和司机，幕后操盘。就在他们的产业帝国越发壮大之时，却面临暴露的危险……', '安东尼·麦凯', '乔治·诺非', 7.4, 47181, 'tt6285944', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2738616657.jpg', 0.2, 1.8, 36.3, 52.6, 9, '0.057145,0.034208,-0.564011,0.574529,0.017763,-0.022991,0.516295,0.276693,-0.377885,-0.288191,0.098856,0.988143,0.056800,0.075478,0.392784,-0.159468,-0.495672,-0.590345,0.022126,0.013555,0.082500,-0.408559,-0.276042,-0.659177,-0.148757,-0.334781,0.588173,0.185102,-0.438170,0.041458,0.232119,0.482921,-0.216382,0.321649,-0.148132,0.084346,0.325975,-0.127311,-0.383869,-0.046060,-0.027954,-0.255814,-0.280139,0.158823,0.191392,0.272217,0.266630,-0.210202,0.210014,-0.228883,0.377587,-0.227696,-0.083040,-0.290785,0.583653,-0.187588,0.162332,0.321012,0.044290,-0.143506,-0.037940,-0.291012,-0.942048,-0.000373,0.458766,0.094098,-0.793472,0.139357,-0.037661,0.075277,-0.027833,-0.297953,0.132439,0.437716,0.419152,0.071228,0.282770,0.055315,-0.762355,0.343836,0.458878,0.111626,-0.286974,-0.035399,-0.272136,-0.492534,-0.319451,-0.376914,-0.594627,-0.189580,0.635281,-0.308914,0.085507,0.122149,-0.598364,-0.188442,-0.114898,-0.176342,-0.094576,-0.513446,0.063789,-0.616368,-0.059484,-0.484245,-0.049223,0.393936,0.118713,-0.115834,0.483364,-0.701246,-0.227460,0.417201,0.405038,-0.652973,0.555285,-0.171330,0.117712,-0.477543,-0.290667,0.331771,0.035577,0.030695,0.062664,0.160400,-0.012270,-0.082262,-0.022237,0.424728', '1793491', '1309069', '26678784', '1299799');
