INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30349249', '夺金营救', '动作', '汤姆（连姆·尼森 Liam Neeson 饰）曾经是雄霸一方叱咤风云的劫匪，犯下了屡屡大案依然逍遥法外。之后，他邂逅了名为安妮（凯特·沃什 Kate Walsh 饰）的女子，美丽善良的安妮令汤姆坠入了情网之中，甘愿为她放弃自己前途无量的犯罪生涯，不仅如此，他还试图通过归 还赃款的方式，来为自己赎罪。联邦调查局警探尼文思（杰·科特尼 Jai Courtney 饰）和霍尔（安东尼·拉莫斯 Anthony Ramos 饰）奉命从汤姆处回收高达700万美元的赃款，两位警探被这数量过于巨大的金钱蒙蔽了双眼，他们不仅企图将这笔钱私吞，甚至想要通过诬陷汤姆杀人的方式将他除之而后快。©豆瓣', '连姆·尼森', '马克·威廉姆斯', 5.8, 6838, 'tt1838556', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2615856924.jpg', 3.7, 24.5, 55.1, 11.9, 4.8, '-0.028173,0.211950,-0.543427,0.498479,-0.328119,-0.353198,0.680644,0.094177,-0.434734,-0.096145,0.204252,0.624615,0.003763,-0.092559,0.092770,0.185468,-0.349256,-0.710380,-0.206968,-0.211837,-0.141552,-0.611978,-0.262206,-0.117971,-0.280748,-0.196059,0.542778,-0.018290,-0.164822,0.214726,0.319545,0.499415,0.276326,0.241508,-0.091892,0.053031,0.207093,-0.324900,-0.119581,0.149331,0.078697,-0.439581,-0.024481,0.443411,-0.188924,0.383160,0.747306,-0.401811,0.115087,-0.136315,0.144847,-0.346723,0.131521,0.272182,-0.216477,-0.093140,0.109802,0.324316,-0.488432,0.097000,0.479563,-0.127155,-0.977918,-0.202465,-0.016290,-0.094631,-0.560306,0.133091,-0.521958,0.265339,0.289603,-0.165017,-0.302138,-0.013407,0.194366,0.035744,-0.189871,-0.234511,-0.401342,0.334701,0.341547,-0.066460,-0.141782,0.068530,-0.391925,-0.439857,0.023388,-0.301446,-0.293340,-0.004750,0.640347,-0.107394,0.052932,0.504783,-0.639702,-0.192223,-0.586130,0.085240,-0.157085,-0.236390,-0.282812,-0.456053,-0.162329,-0.236122,-0.311473,-0.108013,0.113663,-0.320159,0.476551,-0.426128,0.044982,0.875650,0.340857,-0.350299,0.547646,-0.083499,0.024607,0.106990,-0.462326,0.173355,0.374197,0.433340,0.311428,0.046169,0.154568,-0.158799,-0.004123,0.533027', '1307442', '4820775', '1308585', '4816602');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30349667', '指挥家', '剧情', '影片是一部真实的女性职场奋斗史，看出身底层的女性如何突破职场“天花板”，成为史上第一位女性指挥家！当爱情和梦想“狭路相逢”，看她如何“指挥”人生，成就自我！电影根据真人故事改编，讲述“史上最伟大女指挥家”安东尼娅‧布⾥克勇敢追求音乐梦想，在女性社会地位极度受限的上世纪20年代，最终实现自我价值的故事。她出身微寒，却心怀音乐梦想。追梦途中，在以男性为主导的音乐世界中历尽荆棘和冷眼，却永不言弃。当希望的曙光初露，她深爱的男人却希望她为爱止步，最终她毅然选择飞往追寻音乐梦想的欧洲，可他们的爱情又将何去何从......电影由荷兰名导玛利亚·彼得斯执导。', '克里斯蒂亚娜 ‧德‧布奥恩', '玛利亚·彼特斯', 7.3, 9213, 'tt6932818', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2630029701.jpg', 1.4, 6.5, 35.1, 42.5, 14.5, '-0.370973,0.446607,-0.440641,0.878291,-0.039734,-0.278524,0.521056,-0.025446,-0.203894,-0.305758,0.176125,0.992803,0.249477,0.223322,0.330923,-0.097842,-0.347178,-0.737646,0.185945,-0.004547,0.000579,-0.049260,-0.378198,-0.046711,-0.188878,-0.404869,1.364444,0.326117,-0.471876,-0.060243,0.463126,0.123754,0.050121,0.117770,-0.090065,-0.173005,0.279609,0.152352,-0.767355,0.056663,-0.207971,-0.107690,-0.270117,0.257819,-0.542757,-0.149835,0.669479,-0.384233,0.197616,-0.154137,0.664053,-0.368736,-0.017255,-0.143175,-0.099890,0.108353,0.138874,0.229971,0.321603,-0.202907,-0.363401,-0.113327,-1.001204,-0.349997,0.383639,0.144159,-0.385444,0.221598,-0.116208,0.042463,0.167365,0.095365,-0.138816,-0.209518,0.772059,0.566961,-0.266965,0.138186,-0.152452,0.550314,0.630186,0.283640,-0.464889,0.598030,-0.492180,-0.548185,-0.011272,-0.525279,-0.801691,-0.178367,-0.008573,0.180560,-0.050670,0.294560,-0.379476,0.198689,-0.000556,-0.100267,0.312089,-0.760636,0.112242,-0.490660,-0.109047,-0.321299,-0.034274,-0.311723,0.106943,-0.745235,1.242291,-0.686779,0.006501,0.601461,0.165019,-0.548889,1.145270,0.251445,0.024370,-0.581798,0.028140,0.929729,-0.335227,-0.150565,-0.664375,-0.020914,-0.161598,0.013895,-0.436344,0.922920', '25880986', '27602116', '26647163', '30279170');
