INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30352946', '世界奇妙物语 2018年秋季特别篇', '剧情', '《世界奇妙物语 2018秋季特别篇》5个故事主线和主演阵容：「无法逃脱」，坂口健太郎饰演在出版社编辑部工作的志仓真司某天醒来后发现自己和其他3名男女被困在狭小的水泥屋中，之后一起挑战“密室逃脱游戏”。「圣诞的怪物」川荣李奈饰演期待在圣诞前夜被恋人求婚的小野寺奈央，看 着一帆风顺，其实内心曾因7年前发生的某个事件留下阴影。本乡奏多在剧中扮演小野寺奈央的恋人绪方良辅，性格温厚，是IT企业社长。「明天的我」中饰演35岁的主妇齐木香织，每天过着平淡无奇的生活，和丈夫拓也进入了婚姻的倦怠期，因为一个神奇的广告，香织与前男友小野寺修二医生再会，她期待再一次恋爱，不可思议的事情一次次发生，而最终事态超乎了她的想象。「数学的傍晚」「幽灵社员」佐野史郎饰演在某建设公司上班，存在感很低、时间到就准时下班的中年上班族工藤良治。胜地凉演幽灵，是个很年轻就过劳死的上班族。有一天工藤在公司厕所碰见里山，唯一一个可以看见里山且可以和里山交谈的工藤，收到里山的请求，希望借助工藤的力量帮他完成过世前不管怎样都想完成的的工作。', '佐野史郎', '都筑淳一', 6.7, 7428, '', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2568435877.jpg', 1, 8.1, 52.4, 30.3, 8.2, '0.066855,-0.086679,-0.493991,0.398326,-0.053031,-0.128667,0.601251,0.129334,-0.223508,-0.617702,0.030009,0.722947,-0.280662,0.599381,0.291793,-0.180826,-0.196152,-0.642814,-0.123340,-0.058971,-0.203112,-0.298114,0.033578,-0.047078,-0.095811,-0.319853,0.789796,0.188211,-0.088984,0.493096,0.099925,0.159507,-0.155734,0.366188,-0.087017,-0.021867,0.245258,0.309752,-0.235203,0.326638,0.039323,-0.094657,-0.036360,0.085166,0.249347,0.220414,0.550213,-0.061166,-0.417500,0.150036,0.513798,-0.161221,-0.225920,0.101726,0.577815,0.044410,0.138524,0.294288,-0.197923,0.008769,-0.208934,-0.196075,-0.759860,-0.059135,0.078972,0.229049,-0.275646,0.375924,0.058360,-0.007733,0.329509,-0.302109,0.139773,0.322137,0.352929,0.297520,-0.235496,0.200892,-0.404990,0.290694,0.636473,-0.035274,-0.203281,0.566049,-0.060787,-0.362489,-0.180994,-0.115272,-0.391968,0.243893,-0.085191,-0.030040,-0.425092,0.085946,-0.391217,-0.021320,0.051645,-0.136732,0.015509,-0.210240,-0.227346,-0.717948,-0.053062,-0.400576,-0.365705,0.105020,0.191844,-0.403016,0.550747,-0.777130,0.131212,0.565640,0.282708,-0.099524,0.926066,0.156320,-0.007116,-0.219339,0.207732,0.108983,-0.153052,0.282376,0.024