INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30357885', '天·火', '动作', '天火岛美得如同世外桃源，几乎让人忘记它位于“Ring of Fire”——全球知名的环太平洋火山带。年轻的地质学家李晓梦为了研发首个火山监测系统“朱雀”，带着团队来到了这里。李晓梦的父亲、隐退多年的火山专家李文涛得知后赶到火山口，力图劝说她离开。与此同时，探险专家正楠在美轮美奂的水下溶洞潜水，准备给女友佳慧一个浪漫的求婚……火山喷发了，这些人的命运纠结在一起。为了看见明天的太阳，他们必须与过去和解，合力为自己也为众生在绝境中寻找一条生路。 这是一个关于爱与勇气、选择与放弃、自救与他救的中国式英雄的故事。', '王学圻', '西蒙·韦斯特', 4.2, 18474, 'tt9203190', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2576728533.jpg', 28.7, 41.2, 25.1, 3.9, 1.1, '0.030050,0.132484,-0.900692,0.613368,0.081143,-0.144456,0.640215,-0.195733,-0.456806,0.028857,0.104799,0.918058,-0.120086,0.170237,0.162195,-0.091651,-0.362749,-0.517522,-0.287616,-0.064040,-0.405514,-0.336761,-0.242502,0.023709,0.089677,-0.186830,0.701197,0.345064,-0.020107,0.376540,0.117252,0.165713,-0.372480,0.379222,-0.255419,-0.413859,-0.264198,0.128331,-0.669151,0.434306,-0.206287,0.038707,-0.045555,0.189627,-0.094496,0.292693,0.527745,-0.327541,0.102452,-0.145484,0.231523,-0.514109,0.189435,-0.025280,0.106172,-0.144050,0.126981,0.227194,-0.119794,0.119947,-0.007001,-0.380685,-0.772534,-0.114866,0.042121,0.134198,-0.563216,0.265165,0.127687,-0.123827,0.374712,-0.338317,0.246903,0.263435,0.132769,0.410176,-0.546755,0.194513,-0.533535,0.102823,0.697783,-0.269786,0.102082,0.057439,0.104210,-0.253899,0.216717,-0.039686,-0.205227,-0.155872,0.302396,0.190901,-0.364426,0.055999,-0.762661,-0.104049,-0.203351,-0.229400,0.101848,-0.660854,-0.306498,-0.569144,0.004246,0.141618,0.122043,0.238673,0.005186,-0.141420,0.629956,-0.600930,0.345737,0.469468,0.355118,-0.636919,0.877240,0.043916,0.053334,-0.469683,0.233752,0.221417,-0.069484,0.603649,-0.037671,0.254593,0.067952,0.076903,-0.710757,0.049165', '3055049', '3606973', '4301278', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30359340', '南巫', '恐怖', '1987年马泰边界，吉打象屿山下的村落里，村民阿昌是民间神明拿督公的虔诚信仰者，妻子阿燕却不以为然。某日阿昌驱赶神龛前的蛇，不慎打破暹罗裔邻家屋墙。两周后，阿昌突在田埂晕阙，口吐血丝锈钉，村人知悉各圆其说，阿燕全然不信，决意为丈夫遍寻药方。三个月后，阿昌久病不愈，阿燕无计可施，到洞穴祭拜象屿山神。此时，穴内出现一名女子，向她娓娓道出狼牙修时代的传说。霎时之间，阿燕仿如置身边界的融汇与对立，深陷惶恐与未知。本片以精湛的视听语言和炉火纯青的场面调度勾勒出东方神秘主义的新面貌。', '徐世顺', '张吉安', 6.5, 21483, 'tt13212046', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2635906761.jpg', 4.3, 12.8, 45.6, 29.8, 7.6, '-0.090624,0.126440,-0.473509,0.528144,0.263966,0.033223,0.793703,0.056018,-0.584092,-0.023536,0.245740,0.318319,-0.101450,0.161555,0.256127,0.126219,-0.110056,-0.555940,-0.254664,-0.213816,-0.312660,-0.112360,-0.013433,-0.252365,-0.409437,-0.388047,0.156270,0.215974,-0.161999,0.382274,-0.182887,0.362373,-0.356001,0.229278,-0.139372,-0.033172,-0.348997,-0.063583,-0.086818,-0.092590,-0.199389,-0.182720,-0.492410,-0.090075,-0.401375,0.412968,0.500222,-0.294684,-0.026844,-0.353616,0.294890,-0.209486,-0.165955,0.162355,0.320668,-0.047341,0.094066,0.028649,0.054411,-0.290653,-0.064334,-0.008875,-0.199286,0.018776,-0.076081,0.271379,-0.433043,0.420655,0.097637,-0.037701,-0.083837,-0.350297,0.114342,-0.008766,-0.006159,0.398593,-0.023450,-0.073754,-0.548581,0.180761,0.230638,0.059858,-0.316768,0.062448,-0.128377,-0.564004,0.001087,-0.167499,-0.095706,-0.102451,0.222992,0.111166,-0.221879,0.103197,-0.328779,-0.107571,-0.241603,0.017833,-0.060391,-0.135402,-0.312245,-0.435889,-0.022572,-0.429731,-0.193976,0.059149,0.122556,0.199592,0.456719,-0.366820,0.263930,0.147126,0.200558,0.067339,0.596320,-0.079403,0.008173,-0.217274,-0.155424,0.326534,0.077708,0.446991,0.136463,0.276817,-0.236998,0.309911,-0.497731,0.064987', '21619567', '1578663', '20451118', '35073565');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30359376', '美国女孩', '剧情', '2003年，移民美国五年的莉莉因罹患乳癌，抱病带著两个女儿芳仪、芳安从洛杉矶回到新店，与疏离多年的丈夫宗辉团聚。芳仪因为中文障碍在班上成绩严重落后，被同学戏称为“美国女孩”。横衝直撞的她面对母亲生病深感无力，最渴望的就是回到美国。随时担心癌症恶化的莉莉不能谅解芳仪的各种叛逆行为，家庭成员之间的紧张关係一触即发。在文化衝突、经济、疾病等压力之下，莉莉与芳仪的衝突节节升高，并在小女儿芳安于SARS期间被医院隔离时达到高峰。莉莉原本即将分崩离析的家庭，因一场意外的疫情被迫面对彼此的心结，进而获得重新开始的契机。', '林嘉欣', '阮凤仪', 7.3, 19559, 'tt15620158', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2703935581.jpg', 0.5, 3.4, 37.6, 45.7, 12.8, '0.204271,0.011365,-0.635782,0.063203,0.093298,-0.304657,0.495857,0.419550,-0.578934,-0.299541,0.397567,0.636659,-0.322130,0.373083,0.062653,-0.354728,-0.009072,-0.607619,0.194016,0.122342,-0.235185,-0.336675,-0.030691,-0.015693,-0.278452,-0.671941,0.580452,0.045655,-0.116729,0.573934,-0.285082,0.444380,-0.055433,0.452119,0.222407,-0.090578,-0.020560,-0.072712,-0.720346,0.251159,0.392650,-0.139090,-0.071416,0.135700,-0.089717,0.278057,0.726711,0.040456,-0.215826,-0.224818,0.580863,-0.067608,-0.302969,0.321277,0.483596,-0.076281,0.145338,0.220028,-0.355731,0.091888,0.100236,-0.080711,-0.535223,0.237828,0.154410,0.113282,-0.312251,0.693492,-0.139577,-0.091255,0.294449,-0.465487,-0.008801,0.950870,-0.018506,0.843592,-0.624691,0.326022,-0.188352,-0.108783,0.734489,-0.084593,-0.467768,0.381144,-0.265185,-0.083859,0.349966,-0.273404,-0.514492,0.051271,0.107541,0.086537,-0.228484,0.563413,-0.457314,0.181272,-0.517814,-0.210889,0.260829,-0.296178,-0.120292,-0.364677,-0.090764,-0.209773,-0.124188,-0.142199,0.114696,-0.358953,0.667328,-0.828398,0.380731,0.463851,0.381186,-0.695841,0.287124,0.139049,0.295529,-0.188287,-0.190099,0.334729,-0.344021,0.368333,-0.024642,-0.028033,-0.215934,0.138127,-0.201250,0.343013', '30345227', '1292864', '3078390', '34841067');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30359468', '浊水漂流', '剧情', '千言万语，世道如此，约定桥底见。刚出狱的辉哥回到深水埗露宿，遭食环署扫荡清场，家当尽失。他与街友另觅居所，于桥底搭建小木屋相依为命。初出茅庐的社工替街友入禀索偿，但在公义与赔偿来临之前，他们能否挨过寒冬？齐集几代实力演员，改编自真人真事，描述深水埗露宿者如何在狭缝中生存，并为自己争取一丝尊严。', '吴镇宇', '李骏硕', 7.6, 23763, 'tt13887128', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2644033883.jpg', 0.5, 2.9, 29.7, 51.5, 15.4, '-0.177927,-0.313417,-0.141614,0.115954,0.035765,-0.225425,0.495204,0.089963,-0.495953,-0.420560,0.230549,0.596038,0.202403,0.110430,0.051920,-0.378510,-0.304192,-0.179044,0.107307,-0.369403,-0.027633,-0.537876,0.039624,0.189494,-0.206444,0.118765,0.980887,0.327777,-0.175213,0.159618,-0.155499,-0.060333,-0.481074,0.209728,-0.475792,-0.334422,-0.345354,0.202329,-0.830830,0.300597,-0.365470,-0.070816,-0.526318,-0.225886,0.096302,0.346069,0.677035,-0.101197,-0.346512,-0.071626,0.137646,-0.323342,0.123137,0.252358,0.072905,-0.238867,0.272686,0.315934,-0.049201,0.049933,-0.052853,-0.371350,-0.549481,-0.181853,-0.098828,0.072818,-0.424695,0.158270,0.178293,-0.167221,-0.005776,-0.138367,-0.011209,-0.073139,-0.054231,0.335391,-0.532416,-0.066323,-0.321773,0.035168,0.844055,-0.165524,0.281730,0.248967,0.244214,-0.606729,0.309574,-0.194541,-0.282420,-0.396166,-0.306277,0.187885,-0.213497,0.178089,-0.520015,0.096798,-0.425530,-0.097377,0.073820,-0.299633,-0.218327,-0.510364,0.020504,0.079474,-0.146601,0.173052,0.536682,-0.220829,0.346502,-0.605998,0.022798,0.081863,0.425951,-0.448209,0.587405,0.063529,0.388443,-0.128300,0.090083,0.333369,0.199424,0.389297,0.000649,-0.111947,-0.550960,0.332533,-0.440736,0.136636', '26759819', '2369613', '6519585', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30361134', '9号秘事 万圣节特别篇', '喜剧', '亚瑟在墓地捡到旧手机，谁知他好死不死地非要去联系原机主。可是有些秘密最好不要揭开。随着万圣节临近，亚瑟坠入自找的噩梦中。无论今生来世，好人是没有好报的……', '史蒂夫·佩姆伯顿', '巴巴拉·威尔希尔', 8.7, 31537, 'tt7976574', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2538458306.jpg', 0.5, 1.5, 12.7, 35.3, 49.9, '0.293633,-0.125641,-0.726631,0.169308,-0.411272,-0.260593,0.959828,-0.065284,-0.375014,-0.207954,-0.015742,0.543901,0.154287,-0.116469,-0.278310,0.346326,-0.371896,-0.513107,0.114724,-0.321545,-0.582497,-0.777521,-0.314206,0.168992,-0.179777,0.275181,0.646033,0.201007,0.023404,-0.103684,0.294723,0.192169,-0.250238,0.515840,-0.654146,-0.060492,-0.446258,0.376201,-0.396209,0.483418,0.436070,-0.085692,-0.174802,0.464743,0.201292,0.215712,0.308573,-0.281263,0.112023,0.327678,0.306014,-0.172772,-0.248338,-0.055202,-0.128735,-0.446430,0.106258,0.433647,-0.291701,0.077900,0.207514,0.060478,-0.283695,-0.096570,0.263527,0.272218,-0.722014,0.237443,-0.253778,0.335341,0.205148,-0.324059,0.546088,0.186089,0.510973,0.258157,0.175876,-0.076502,-0.630926,-0.012483,1.068602,0.135571,0.374689,0.227324,0.289937,-0.053636,0.297665,-0.059568,-0.552289,0.328662,0.134342,0.170353,-0.457029,0.324663,-0.427784,-0.299764,0.047372,-0.002616,0.041367,-0.507138,-0.187762,0.371883,-0.102154,0.002266,-0.099639,0.413758,-0.177824,-0.523598,0.113763,-0.835626,0.433063,0.694961,0.084963,-0.380290,0.689852,0.574690,-0.184793,-0.215235,0.192011,0.120786,0.033547,0.597589,0.172706,-0.484320,0.378602,-0.310272,-0.716562,0.338338', '1291835', '26715845', '1302384', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30361878', '爱玛', '剧情', '21岁的艾玛（安雅·泰勒-乔伊 Anya Taylor-Joy 饰）一看就是一个聪明的姑娘，脑袋里塞满的全都是古灵精怪的点子。艾玛最大的兴趣爱好就是给身边的朋友们牵线搭桥，最近，她把目标放在了自己的好友哈莉特（米娅·高斯 Mia Goth 饰）的身上。虽然哈莉特已经有了 心上人，但艾玛还是千方百计的想要将有些古怪的招风耳神父埃尔顿（乔什·奥康纳 Josh O''Connor 饰）推荐给自己的好友。虽然艾玛总是沉浸于浪漫的幻想之中，但她却坚信自己并不会走入婚姻。艾玛那英俊而又活泼的姐夫的弟弟奈特利（约翰尼·弗林 Johnny Flynn 饰）吸引了哈莉特的注意，而另一位名叫弗兰克（卡勒姆·特纳 Callum Turner 饰）的男子则开始让艾玛的不婚主义开始动摇。©豆瓣', '安雅·泰勒-乔伊', '奥特姆·代·怀尔德', 7.3, 34845, 'tt9214832', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2581191543.jpg', 0.7, 4.4, 37.7, 42.7, 14.5, '0.530491,-0.044467,-0.375242,0.661857,-0.366146,-0.582405,0.905482,0.045829,-0.401004,-0.166990,0.150497,0.751773,-0.230614,0.379967,0.385185,0.551372,-0.223766,-0.725615,-0.078602,-0.224901,-0.300789,-0.562337,-0.501413,-0.109755,-0.085743,-0.217552,0.378705,-0.186167,-0.079159,0.302717,0.661630,0.259651,0.184847,0.494309,-0.062592,0.103088,0.002674,-0.273291,0.192919,0.003691,0.154163,-0.055776,0.002006,0.477341,0.105197,0.543718,0.562361,-0.402002,0.077350,0.087551,0.366951,-0.042617,0.090269,0.203859,0.062793,-0.062227,0.231358,-0.140782,-0.133448,0.146026,0.267514,-0.160251,-0.804296,0.203034,0.169328,0.134177,-0.572611,0.374967,-0.108751,-0.186693,0.136840,-0.094496,0.070189,0.148988,0.266229,0.323464,-0.255800,0.016703,-0.162816,-0.040187,0.009808,0.176958,-0.108428,0.447979,-0.518486,-0.262973,0.177822,0.066060,-0.591651,-0.146290,0.303276,0.150884,0.037129,0.236297,-0.626973,0.053794,-0.387713,-0.079223,0.028064,-0.532499,-0.204956,-0.251436,-0.130278,-0.599564,-0.160626,0.003270,0.124015,-0.249445,0.935805,-0.746715,0.089952,0.599109,0.068656,-0.295716,0.564265,0.161324,0.044593,-0.251848,-0.315310,0.224760,0.042038,0.029993,-0.011706,0.454584,-0.034888,-0.446449,-0.313393,0.728648', '26348103', '1292062', '35158375', '4847665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30362186', '大约在冬季', '剧情', '1991年齐秦狂飙演唱会上，北师大才女安然（马思纯 饰）和来自台北的摄影师齐啸（霍建华 饰）因缘相识，曲终人散后再度重逢的二人陷入热恋，然而不是勇敢就一定能拥有爱，不是所有再见都能再见！在漂泊岁月中，弄丢了挚爱的我们，是否还能安然无恙？没有我的日子里，你是否能保重自己？2019年，齐啸和安然能否重逢？', '马思纯', '王维明', 5, 71974, 'tt11162126', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2571441805.jpg', 14.9, 36.3, 34.7, 10.4, 3.8, '-0.245610,0.105326,-0.552185,0.216225,-0.003241,-0.746342,0.476954,-0.169996,-0.371551,0.093712,-0.277728,0.251544,-0.077939,0.412251,0.027302,0.011568,-0.383841,-0.940366,0.017770,-0.148444,-0.368091,-0.305097,-0.199777,-0.031287,-0.073208,-0.268024,0.328097,0.242495,-0.210753,0.488725,0.192282,0.219643,-0.396313,0.632555,-0.827690,0.021568,-0.096663,0.910328,-0.895180,0.362430,0.261897,-0.321994,-0.153705,0.069587,0.233930,-0.144273,0.538922,-0.229338,-0.033198,0.160378,0.193342,-0.007916,0.077391,0.239582,-0.187506,-0.060921,0.418670,0.226186,-0.380745,-0.168901,-0.192992,-0.131504,-0.448504,-0.216706,-0.073085,0.109641,-0.390351,0.364805,0.197374,-0.123543,0.299473,-0.004548,0.489165,0.366853,0.451094,0.195708,-0.037264,-0.142252,-0.655018,0.622465,1.044224,0.034355,-0.264252,0.423099,0.083505,-0.609172,-0.091717,-0.081913,-0.731270,0.283205,0.115544,0.177170,0.059894,0.188338,-0.176195,0.049477,-0.337722,-0.099719,0.001283,-0.428610,0.154300,-0.081739,-0.205808,-0.760814,-0.436454,0.106214,0.022744,-0.452737,0.937027,-0.838692,0.483603,0.118051,0.472427,-0.324441,1.005069,0.424086,0.065686,-0.000551,0.532169,-0.006977,-0.237389,0.208767,0.448059,0.228937,0.080641,0.281895,-0.539807,0.467873', '10535447', '3212120', '5985887', '1949811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3036460', '母亲', '剧情', '因为儿子尹泰宇（元斌 饰）是智障，所以母亲（金惠子 饰）总是担心他受伤。一天，泰宇被一辆奔驰车撞倒，朋友镇泰（秦久 饰）带他去高尔夫球场找打球的教授报仇，结果被带回了警局。因为镇泰踢坏了后视镜，教授向他们索赔，泰宇被当成了挡箭牌。 从警局出来后，在家吃过晚饭，泰宇去找镇泰喝酒，但此时镇泰趁着夜色回到球场找出了白天扔进湖中的球杆。泰宇酒后尾随一个名叫文雅中的女学生，结果第二天雅中的尸体就出现在屋顶。泰宇被当做唯一的嫌疑人带回了警局，接着在警察的威胁下画押认罪。得知儿子入狱，心急如焚的母亲委托著名律师为他翻案。但是，泰宇的病影响了他的记忆，母亲在替儿申冤的道路上步履蹒跚……©豆瓣', '金惠子', '奉俊昊', 8.3, 96957, 'tt1216496', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1518748581.jpg', 0.2, 1, 13.6, 51.4, 33.7, '0.209746,0.010894,-0.367625,0.108697,-0.166296,-0.497182,0.558828,0.366893,-0.503209,-0.353822,0.264032,0.528742,0.228580,0.307393,0.430816,0.172866,-0.277648,-0.454956,0.132990,-0.086857,-0.422251,-0.356484,0.164625,-0.009384,0.238333,-0.091731,0.188011,-0.208587,-0.116061,0.663845,0.044090,0.140077,-0.081101,0.355999,-0.152793,0.284124,0.034305,-0.077877,-0.190348,0.336979,0.210252,-0.414124,0.016150,-0.014050,0.078758,0.385879,0.808947,0.283105,-0.264049,-0.036546,0.238115,-0.456398,0.064447,0.146595,0.327674,0.089825,0.217360,0.138097,-0.228033,-0.208483,0.025342,0.148856,-0.426573,0.149678,-0.180680,0.014924,-0.680686,0.503777,-0.118709,0.046104,0.095727,-0.486015,0.518585,0.003243,-0.211539,0.347621,-0.292210,0.148406,-0.675600,0.200971,0.442312,-0.179369,0.439833,0.187961,0.144666,-0.081100,0.373981,-0.155689,-0.264383,-0.036746,0.609619,-0.189216,-0.455915,-0.336236,-0.337291,-0.277749,-0.335037,-0.087597,0.074690,-0.231057,-0.239805,-0.302111,0.201580,0.149595,-0.161787,-0.070943,-0.197101,-0.078443,0.320243,-0.444789,0.429769,0.490044,0.344317,-0.414123,0.818604,-0.002266,0.117798,0.009897,0.138625,-0.157568,0.443114,0.592278,0.199790,0.247256,-0.099312,-0.346966,-0.529544,-0.007680', '1294252', '1306505', '26882457', '3074303');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3036464', '闰年', '喜剧', '城市女孩安娜（艾米·亚当斯 Amy Adams 饰）与男友杰里米（亚当·斯科特 Adam Scott 饰）相恋四年，共同申请购买波士顿顶级豪华社区的高尚住宅。安娜本以为杰里米要向自己求婚，失望后听从父亲建议，飞往爱尔兰首都都柏林，打算依照爱尔兰传统，在闰年的2月29日这天向在都柏林参加医学会议的杰里米求婚。没想到飞机遭遇气流，迫降威尔士加的夫。安娜从加的夫雇船航行至爱尔兰丁格尔半岛，狼狈不堪中投宿当地青年德克兰（马修·古迪 Matthew Goode 饰）的海滨旅店。德克兰同意次日开车带安娜前往都柏林，一路上二人相互看不顺眼，争吵不休。争执中又遭遇车坏、暴雨、误点、假扮夫妻投宿农家等爆笑事件，可这一对冤家却也在不断的摩擦中彼此了解，情愫渐生。2月29日终于到来，安娜的一颗芳心究竟要托与何人呢？©豆瓣', '艾米·亚当斯', '安南德·图克尔', 7.8, 101333, 'tt1216492', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p570006170.jpg', 0.3, 2.4, 27.7, 47.5, 22, '0.114751,-0.046120,-0.718455,0.273113,0.422716,-0.267728,0.341193,0.135679,-0.387648,-0.040709,0.278860,0.771872,-0.370751,0.044136,0.701434,0.066231,-0.769102,-0.394907,0.348288,-0.458078,-0.125432,-0.660688,-0.029541,0.022165,0.221759,-0.102771,0.158422,0.056167,0.220961,0.757008,0.077860,0.407267,-0.318070,0.202973,-0.072928,-0.175493,0.460009,0.153958,-0.582073,0.260901,-0.160976,0.089746,-0.187129,-0.298039,0.270019,0.374831,0.539275,-0.141038,0.188949,-0.327465,0.087584,0.136397,0.164185,0.243130,0.240804,0.007419,0.218135,0.214339,-0.128904,-0.110388,-0.017964,-0.060658,0.133263,0.403667,0.071109,-0.000144,-0.339263,0.266180,-0.250323,-0.153706,0.054734,-0.352577,-0.088494,0.556940,0.119310,0.422998,0.106993,0.058964,-0.286495,-0.322093,0.647544,-0.076652,-0.026738,0.157622,0.094890,-0.169953,0.225084,0.236441,-0.457731,-0.048033,0.142690,-0.002304,0.039046,0.284917,-0.562892,0.026506,-0.388351,-0.084602,0.195555,-0.047551,-0.141612,-1.100103,0.046645,-0.158103,-0.007171,-0.067004,0.193111,0.334805,0.254422,-0.531884,0.265890,0.294503,0.599326,-0.320957,0.450128,0.202921,0.132707,-0.345488,-0.056107,0.320977,-0.060913,0.127098,-0.183393,0.255211,0.175741,0.038952,-0.112498,0.031803', '2075345', '1296339', '1293572', '1293537');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3036465', '爱在记忆消逝前', '喜剧', '该片改编自Michael Zadoorian的同名小说，讲述了一对患重病的老夫妻开着老旧的房车从马塞诸塞州出发前往海明威的故居，在旅途中回顾人生的故事。约翰是一位文学教师和作家，海明威的死忠，尽管阿兹海默症已经让他的记忆越来越差，甚至会忘记妻子和儿女的名字，却依旧可以随口说出海明威的所有作品，《老人和海》更是他的钟爱。因为妻子艾拉患重病需要住院， 约翰就只能进入养老院，携手走过一辈子的二人面临永远分开的未来。于是，他们有了一个疯狂的决定，决心驾驶名叫“leisure seeker 求闲者”的房车，从马塞诸塞州一路南行，回顾70年代曾和孩子们一起度假的旅程，目的地是西锁岛key west 的海明威故居。', '海伦·米伦', '保罗·维尔齐', 8.1, 40918, 'tt3741632', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505160727.jpg', 0.1, 1.2, 18.7, 52.4, 27.5, '0.279917,-0.300905,-0.542303,0.639878,0.163528,-0.514964,0.817752,0.142964,-0.636464,-0.314173,0.197392,1.004578,0.061195,0.388648,0.388529,-0.059484,-0.356806,-0.578151,-0.077775,-0.017992,-0.242475,-0.576506,0.036937,-0.190163,0.010106,-0.292093,0.626558,0.233694,-0.204011,0.474927,0.307997,0.276483,-0.245276,0.370841,-0.519455,0.105401,-0.003837,0.130252,-0.423279,0.247133,0.057295,0.044316,0.015482,-0.083398,0.005922,0.143237,0.718931,-0.255320,-0.145882,0.186625,0.267357,-0.028273,-0.105553,0.028641,0.334607,0.120935,0.306585,0.334039,-0.226511,-0.020681,-0.173691,-0.067429,-0.647340,-0.007042,0.180095,0.169626,-0.831186,0.346609,0.075392,-0.111472,0.206654,-0.306529,0.447228,0.360081,0.052566,0.608661,0.049917,-0.061757,-0.455917,0.323387,0.779165,-0.070931,-0.077449,0.440416,-0.186359,-0.256672,-0.174505,-0.074037,-0.680842,0.128766,0.224065,0.065265,-0.341611,0.226427,-0.307521,-0.037877,-0.239401,-0.470962,0.363657,-0.257836,0.043332,-0.609060,0.087364,-0.336699,0.027794,0.029234,0.092365,-0.266133,0.851031,-0.691094,0.358782,0.367316,0.146415,-0.559027,0.911278,0.178865,0.209617,-0.206338,0.280365,0.693843,-0.188755,0.364621,-0.081247,0.204264,-0.088681,-0.071302,-0.507031,0.604267', '1292720', '30162520', '1460341', '1292001');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3036469', '小叮当：拯救精灵大作战', '喜剧', '充满了阳光和活力的夏天到来了！为了应付炎热的天气和即将到来了秋冬，汀克贝儿（梅·惠特曼 Mae Whitman 饰）和她的仙子朋友们此刻正忙得不亦乐乎。虽然身为仙子，但也有着各自不同的喜恶，汀克贝儿和薇迪亚（Pamela Segall 配音）就一直看对方不太入眼，这不，为了一点小事，两人又吵了起来啦。令两人没有想到的是，就在这个节骨眼上，一个人类的孩子莉兹（Lauren Mote 配音）竟然在无意之中将汀克贝儿给捉走了！如果坐视不管，仙子们企图隐藏的仙子世界终究会被人类发现。为了解救同伴，薇迪亚前后奔走着，祸不单行，雨季来临了，一边是恶劣的天气，一边是陷入危险的汀克贝儿，薇迪亚会怎么做呢？©豆瓣', '梅·惠特曼', '布拉德利·雷蒙德', 8.2, 6893, 'tt1216515', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2501664599.jpg', 0.2, 1, 18, 49.3, 31.4, '0.450105,-0.107488,-0.565468,0.570556,-0.317910,0.162420,0.768628,0.159916,-0.419894,-0.044978,0.147034,0.935695,-0.569029,0.307823,0.226391,0.313984,-0.565121,-0.726510,-0.127258,-0.140202,-0.386166,-0.356960,0.056040,0.213690,-0.211215,-0.264311,0.398453,0.001811,-0.125419,0.398711,0.192795,-0.131570,-0.088488,0.962312,-0.104600,-0.071514,-0.085759,-0.001352,0.145184,0.334106,0.353643,-0.150383,-0.350165,0.467383,0.172397,0.380545,0.456814,-0.535628,-0.130815,0.008961,0.264507,-0.482892,0.413444,0.162042,0.425448,-0.551440,0.170343,0.033045,-0.129328,-0.176634,0.093294,-0.146451,-0.942548,0.654679,0.150509,0.127877,-0.660485,0.295580,0.078484,-0.104881,0.113128,-0.190161,0.431018,0.615286,0.242560,0.527442,-0.136203,-0.369717,-0.686105,-0.075440,0.745658,0.222144,-0.191007,0.660678,-0.309903,-0.191582,-0.151845,-0.010885,-0.597378,-0.282809,0.292465,0.015323,-0.255052,0.154272,-0.517571,0.294823,-0.004815,-0.390502,-0.125525,-0.483413,-0.350032,-0.230819,0.054575,-0.638735,-0.589119,0.277289,0.170859,-0.379265,0.790758,-1.022076,-0.001512,0.652488,0.358950,-0.415607,0.708320,-0.001388,-0.082489,0.018190,-0.150903,0.084801,-0.221962,0.330379,0.688977,0.548938,-0.122692,-0.106779,-0.278300,0.389341', '1308755', '1304749', '1783461', '1303112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3036473', '勇敢传说', '喜剧', '长久以来，那些伟大的战争故事和魔幻的传说一直被人们口口相传，一代又一代，生生不息在这片延绵又神秘的苏格兰高地上。迪士尼∙皮克斯的又一诚意之作，勇敢的梅莉达抗争传统束缚，追求自由从而改变自己命运的瑰丽故事横空出世。梅莉达是佛格国王与艾莉诺皇后的长女，她是一名出色的弓箭手， 也有任性不羁，《勇敢传说》讲述的就是她的冒险故事。为了走出自己的生活之路，梅莉达拒绝承袭对于3个部落首领（丁瓦、麦金、麦葛）来说神圣不可侵犯的古老传统。梅莉达的鲁莽给她的王国带去了混乱和灾难，当她向森林中的女巫寻求帮助的时候，女巫却实施了灾难性的魔咒。接踵而来的灾难逼迫梅莉达使出浑身解术——包括自己的三胞胎弟弟们——来帮助她解除咒语，寻获勇气的真谛。由马克∙安德鲁斯与布兰达∙查普联合执导，凯瑟琳∙萨拉斐安监制的这部《勇敢传说》，充满了伟大冒险传奇，打造出经典的人物角色，当然还有备受全球影迷期待的皮克斯式幽默。', '凯莉·麦克唐纳', '马克∙安德鲁斯', 7.6, 166618, 'tt1217209', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1597593082.jpg', 0.4, 2.7, 31.9, 46.2, 18.7, '-0.077214,0.129958,-0.565005,0.820378,-0.007221,-0.005200,0.804880,-0.215071,-0.335554,-0.260939,0.335362,0.873001,0.137783,0.002912,0.398420,0.138860,-0.203855,-0.383519,-0.129132,0.170424,-0.033854,-0.289676,-0.438589,-0.267549,-0.107146,-0.568538,0.713099,0.067758,-0.646485,0.144604,0.425866,0.451094,0.058979,0.104932,-0.228424,-0.047509,-0.004616,0.041513,-0.309942,0.073733,-0.194551,-0.094363,-0.350895,0.482807,-0.229517,0.151693,0.323200,-0.570181,0.034114,-0.114888,0.488281,-0.496929,-0.093329,0.134240,0.170507,-0.044934,0.126596,0.287877,0.257537,-0.212809,-0.051209,-0.325644,-1.134648,-0.090447,0.169535,0.055155,-0.556373,0.336712,0.122794,-0.086974,0.202373,-0.206777,-0.053940,0.020077,0.433443,0.448418,-0.140057,0.131008,-0.289017,0.381898,0.658963,-0.079663,-0.596618,0.236104,-0.445009,-0.398292,0.062653,-0.504935,-0.672765,-0.047866,0.421477,-0.086093,0.111488,0.522945,-0.797908,0.017130,-0.201345,-0.221138,0.172043,-0.455906,0.067032,-0.420983,-0.166803,-0.317258,-0.142487,-0.227779,0.222210,-0.192521,1.081250,-0.589544,0.312647,0.579174,0.189001,-0.595093,0.557144,0.137215,0.152229,-0.205468,-0.105205,0.627522,-0.057857,0.211369,-0.073481,0.279083,0.083704,-0.001285,-0.351124,0.533374', '27602116', '24284209', '26667010', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3036477', '小叮当：羽翼之谜', '喜剧', '在动物仙子（简·霍洛克斯 Jane Horrocks 配音）和小叮当（梅·惠特曼 Mae Whitman 配音）的帮助下，动物们浩浩荡荡的迁徙到了冬森林，冬森林实在是太美丽了，小叮当瞬间就被迷住了。之后，小叮当发现自己背上的翅膀竟然开始发光，她来到藏书室，好不容易找到了记载着翅膀发光缘由的书籍，却发现自己所需要的那几页书居然被虫蛀得斑斑驳驳。无奈之下，她只得前去寻求图书管理员的帮助，图书管理员告诉小叮当，她所寻求的答案就藏在冬森林之中，于是，小叮当踏上了寻求真理的旅途。在冬森林，小叮当遇见了铃兰花仙子（露西·海尔 Lucy Hale 配音），与此同时，一个隐藏了多年的秘密渐渐浮出水面。©豆瓣', '梅·惠特曼', '罗伯茨·甘纳韦', 8.3, 10535, 'tt1217213', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1739457786.jpg', 0.2, 0.9, 17.5, 48.2, 33.1, '0.514014,0.293606,-0.664145,0.601244,0.339982,-0.279723,0.236047,-0.097007,-0.285085,-0.218636,0.033694,0.378199,-0.302091,0.323140,-0.121455,0.087001,-0.354483,-0.534805,-0.388851,-0.370717,-0.828824,-0.144364,-0.223145,-0.261196,0.096891,-0.431074,0.500702,0.272801,-0.159721,0.202135,0.035800,0.217954,-0.289609,0.496236,-0.201961,0.416595,0.144493,0.132739,0.221096,0.256489,-0.052700,-0.230886,-0.253021,0.085511,0.183246,0.212952,0.827674,-0.520539,-0.201248,0.165932,0.300800,-0.333611,0.127576,-0.036566,0.510238,-0.156877,0.021236,-0.127339,-0.298553,0.187218,0.089583,-0.286907,-0.375920,-0.131749,-0.197024,0.347765,-0.391021,-0.247261,0.067052,0.169331,0.083482,-0.569062,0.204002,0.087867,0.142144,0.213783,0.021203,0.037936,-0.472381,0.283419,0.173829,0.033759,-0.027533,0.413314,-0.381819,-0.379555,-0.119151,0.312417,-0.216881,-0.405287,0.934467,0.052695,-0.379506,-0.054340,-0.711821,-0.226303,-0.368689,-0.373800,-0.050366,-0.419279,-0.337636,-0.284468,-0.041140,-0.007826,-0.199151,0.138531,-0.070768,-0.315015,0.610090,-0.813870,0.434132,0.711251,-0.066702,0.039820,0.420527,-0.622082,-0.155009,0.183795,0.118095,0.456406,0.239303,0.591954,0.383956,0.304923,-0.011760,-0.105051,-0.540245,0.503827', '1438591', '1294037', '27069070', '1292829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3036478', '赛车总动员2', '喜剧', '开发出新能源的迈尔斯伯爵召开世界杯赛车大奖赛，各路好手纷纷云集，独独缺了活塞杯霸主闪电麦昆（黄磊 配音）。原来他刚好回到温泉镇，与好哥们板牙（范伟 配音）、女友莎莉享受快乐的假期。由于意大利方程式赛车法拉斯·高的挑衅，当然也有吃醋的原因，麦昆最终同意参加世界杯，并带着板 牙等好友一同周游世界。在日本站比赛的前一天，板牙偶然结识了英国特工迈克飞弹和霍莉（姚晨 配音），他们正在追查一支犯罪团伙的新动向。板牙阴差阳错被霍莉当作美国来的接头特工，由此卷入了麻烦之中。在次日的比赛中，麦昆与法拉斯·高竞争激烈，与此同时不断有选手意外爆缸，板牙则撞见迈克和神秘组织火并的场面。因这一连串意外，麦昆和板牙的友情受到动摇，而这一切的幕后老板也渐渐露出真实面目……©豆瓣', '欧文·威尔逊', '约翰·拉塞特', 7.8, 94670, 'tt1216475', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p960983865.jpg', 0.3, 2.2, 27.8, 48.5, 21.2, '0.081846,-0.015994,-0.614178,0.217681,0.171714,-0.222579,0.585169,0.177255,-0.324816,-0.008187,0.319091,0.651004,-0.390385,-0.019167,0.372789,-0.333156,-0.396314,-0.577764,0.111530,0.016645,-0.249567,-0.339905,-0.106834,-0.122116,0.182786,-0.247522,0.439662,0.008863,-0.105927,0.863905,0.380921,0.158551,-0.204555,0.593747,0.017339,-0.036427,0.434613,0.095188,-0.197113,0.250910,-0.140681,-0.111599,-0.165376,-0.125996,0.238650,0.491959,0.370679,-0.165440,0.036526,-0.046377,0.220384,-0.367751,-0.004263,0.041566,0.418426,0.072204,0.316959,-0.049373,0.064194,0.094357,-0.049198,-0.186479,-0.682341,0.092438,0.113257,0.137672,-0.275850,0.631659,-0.034517,-0.260355,0.135119,-0.080662,0.431928,0.375262,0.238068,0.089581,0.058354,0.296672,-0.332186,0.030676,0.419400,-0.098072,-0.097380,0.023901,0.065910,-0.413647,0.061019,-0.305514,-0.148618,0.057838,0.528611,-0.100987,0.166082,0.150764,-0.645169,0.057253,-0.021962,-0.183849,0.061380,-0.231689,-0.025956,-0.718017,0.014071,-0.352210,0.040424,-0.078363,0.046090,-0.020196,0.388804,-0.742508,0.104308,0.580843,0.044011,-0.084118,0.414729,0.101525,0.148417,-0.424700,-0.363641,-0.042455,0.123621,0.244553,-0.098917,0.415389,0.279457,-0.130982,-0.128917,0.100605', '26365262', '11541282', '3139191', '2357711');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30364976', '人间失格：太宰治和三个女人们', '剧情', '太宰治與蜷川實花的組合，一字記之曰：色。蜷川並不服膺於太宰治半自傳小說《人間失格》的隔靴搔癢，借書之名直接拍他本人和三個女人的故事。太宰治的妻子美知子、有志成為作家的情人靜子和他最後一位情人富榮，分別由演技派女優宮澤理惠、澤尻英龍華和二階堂富美飾演，襯托著蜷川分別為三女精心設計的主題色調，色彩濃烈絢麗的畫面是一場流動的視覺盛宴。為了對抗生命的無力感，太宰治沉溺於女人與酒精，在靡爛晦暗的生活中追逐死亡之光。在蜷川的鏡頭下，他既是才子，亦是賤男，他的不堪，反而折射出人間的脆弱和美好。', '小栗旬', '蜷川实花', 6.2, 21366, 'tt10065976', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2551425342.jpg', 2.6, 18.3, 51.4, 20.6, 7.2, '0.006796,-0.212169,-0.292141,0.693428,-0.374346,0.151528,0.997526,0.598546,-0.322085,-0.140990,0.389734,0.737436,-0.212959,0.081990,0.380412,0.162452,-0.061516,-0.750680,-0.192329,0.287318,-0.033681,-0.275473,-0.312257,0.213801,-0.203381,-0.413560,0.942047,-0.022021,-0.060668,0.222268,0.268488,0.303516,0.055981,0.386088,-0.127119,-0.046094,-0.336019,0.099806,-0.088817,0.119724,0.034206,-0.569270,0.079743,0.222756,-0.420278,0.361399,0.733490,-0.404368,0.057863,-0.220789,0.394190,-0.342449,-0.083132,0.187906,-0.070246,-0.269671,0.285070,0.363384,-0.120111,-0.072290,0.185008,0.356035,-0.858650,-0.190474,0.478072,0.164407,-0.344321,0.779888,-0.117812,-0.438099,0.078102,-0.327807,0.192096,-0.102900,-0.055785,0.468583,-0.020510,0.005337,-0.198438,0.423270,0.364255,0.193609,-0.327579,0.485271,-0.334359,-0.624064,0.028594,-0.385473,-0.729863,-0.220222,0.311513,-0.040403,-0.190106,0.241440,-0.543214,-0.012041,-0.066950,-0.017882,-0.001492,-0.169035,0.075145,-0.050426,-0.088826,-0.762605,-0.149067,-0.191889,0.507177,-0.323146,0.535394,-0.886431,0.026744,0.379439,0.054304,-0.408981,0.947989,0.388266,-0.066934,0.104131,-0.117027,0.178594,0.073346,0.209986,0.061732,0.654419,-0.116122,0.242031,-0.398100,0.532442', '3033092', '1417428', '5416009', '27666513');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3036564', '不存在的女儿', '剧情', '故事开始在一个突降大雪的夜晚，十月怀胎的Nora（格瑞辰·摩尔 Gretchen Mol 饰）肚子作动，身为医生的丈夫David（德蒙特·莫罗尼 Dermot Mulroney 饰）决定送她去自己的诊所，同时打电话给护士Gil（艾米丽·沃森 Emily Watson 饰）让他赶紧去诊所准备。Nora诞下一对龙凤胎，然而David一眼便看出女儿患有唐氏症，想起自己12岁的妹妹便是死于唐氏症的折磨下，而且家母终身未能再展露笑容。为了避免悲剧的发生，David当机立断让Gil把小女儿送走，只对Nora说女儿一出生便夭折了。这一个决定，改变了三个人的命运。©豆瓣', '艾米丽·沃森', '米克·杰克逊', 7.6, 8005, 'tt0955298', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2194014325.jpg', 0.3, 2.6, 30.4, 49.2, 17.5, '-0.074783,0.024606,-0.399813,0.473909,-0.337336,-0.513832,0.624645,0.310041,-0.310041,-0.307141,-0.014172,0.712298,-0.247929,0.520271,0.403817,0.164635,-0.126179,-0.505565,0.088107,-0.140241,-0.616065,-0.212783,0.188931,-0.420654,0.411233,-0.314116,0.149736,-0.056673,0.014852,0.308764,0.347567,0.243696,0.071427,0.348078,-0.310959,0.363313,-0.453488,-0.096243,-0.272240,0.499271,0.333697,-0.159144,-0.188257,0.307320,-0.000276,0.404496,0.730618,-0.184602,-0.286619,-0.341637,0.553000,-0.105382,-0.038867,0.269674,0.288530,0.078558,-0.069378,-0.050666,-0.402742,-0.158449,0.208257,0.033366,-0.579445,0.255869,0.062868,-0.094878,-0.788797,0.103826,-0.175375,0.099103,0.179316,-0.462007,0.224533,0.576807,0.039438,0.706353,-0.303684,0.193549,-0.632223,0.064551,0.575229,-0.242136,0.029239,0.436899,0.043019,-0.300159,0.214867,-0.014708,-0.446862,0.150205,0.375079,-0.064054,-0.163163,0.064262,-0.071887,-0.444193,-0.409890,-0.367556,0.202621,-0.410847,0.046051,-0.013025,0.037836,0.026253,-0.521666,0.240676,0.193390,-0.194860,0.667944,-0.483145,0.422652,0.349126,0.175377,-0.657193,0.544770,0.185683,0.472964,-0.159352,0.364457,0.274960,0.063908,0.185015,0.185452,0.321767,-0.183735,0.045571,-0.352779,0.273261', '25731805', '1299965', '1306505', '1292337');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30366084', '断裂', '惊悚', '雷·门罗（萨姆·沃辛顿饰）是一个好心但不堪重负的居家男人。在与岳父岳母度过一个紧张的假日周末后，雷带着妻子乔安妮（莉莉·拉贝饰）和女儿佩里（露西·卡普里饰）开车回家，途中驶入一个休息区。然而屋漏偏逢阴雨夜，佩里在事故中受伤。一家人急忙带着她来到附近一个急诊室，这里的工作人员看似有些意图可疑。被送去做进一步检测后，佩里与乔安妮失踪了，他们所有的访问记录也消失不见。雷的担忧成了真：他必须争分夺秒寻找家人，并搞清他们究竟遭遇了什么。', '萨姆·沃辛顿', '布拉德·安德森', 6.9, 13998, 'tt4332232', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2568649517.jpg', 1.2, 7, 47, 35.9, 9, '0.346716,-0.033724,-0.644451,0.316650,-0.017423,-0.262627,0.890455,0.214312,-0.365759,-0.577766,-0.222355,0.666693,-0.373859,0.517256,0.516457,0.131173,-0.615469,-0.510332,0.133141,0.033510,-0.437539,-0.603538,-0.087880,-0.063021,0.084753,0.002363,0.010670,0.123259,0.237725,0.610699,0.249620,0.301642,-0.247540,0.803729,-0.066826,0.212015,0.254031,-0.163254,0.059196,0.307822,0.289834,-0.107437,-0.208643,0.150286,0.384514,0.468769,0.495293,-0.065659,-0.040972,0.223202,0.188657,-0.363779,0.177332,0.193903,0.204001,-0.173740,0.032246,-0.048818,-0.360829,0.068400,0.223410,-0.123407,-0.520922,0.248561,-0.039531,0.039313,-0.790932,0.319470,-0.233845,0.033351,-0.030860,-0.621570,0.520337,0.645469,0.016272,0.430286,-0.199514,-0.158199,-0.529990,-0.177079,0.599563,-0.103711,-0.008216,0.267758,-0.006988,-0.307524,0.020307,0.228140,-0.622725,-0.128440,0.487584,0.040432,-0.035188,-0.162508,-0.360859,-0.236959,-0.556210,-0.244268,-0.335850,-0.212169,-0.264469,-0.622200,0.333446,-0.382796,-0.439536,0.164761,-0.139856,-0.062479,0.210277,-0.626108,0.150981,0.391253,0.092592,-0.511126,0.622050,0.044805,0.308790,-0.161599,-0.017818,0.150119,0.228532,0.455976,0.399428,0.408362,0.008452,0.136069,-0.268907,0.235367', '1302384', '26457368', '21348112', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30367643', '前哨基地', '动作', '不是陨石撞击地球，也不是恐怖份子的全球威胁，更不是发生核子战争，人类熟悉的世界一夕之间面目全非，没有人知道是什么原因导致全球电力系统故障，消灭所有生命，唯独一个位于东欧的小区域幸存下来，仍保有正常的电力运作。面对毁天灭地的灾难，这个人类最后的希望堡垒必须全力反击，阻止这场灭绝浩劫……', '阿雷克西·查多夫', '埃格尔·巴拉诺夫', 5.8, 7376, 'tt8664988', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2571627286.jpg', 5.4, 25.5, 49.5, 14.2, 5.4, '0.028864,0.512788,-0.860042,0.231682,-0.156131,0.514742,0.924637,-0.389720,-0.076913,-0.216870,0.369814,0.426548,0.284750,-0.254731,-0.346591,-0.316018,0.085192,-0.280947,-0.318694,0.283432,-0.508423,-0.512067,-0.626595,-0.166358,-0.107172,-0.591224,0.950450,0.763732,-0.693407,-0.127255,-0.113532,0.174452,0.167075,0.524090,-0.091474,-0.351023,-0.391909,-0.136515,-0.516372,0.223922,-0.451830,-0.095277,0.072840,0.501784,-0.311766,0.455279,0.382814,-0.400167,-0.078692,-0.427000,0.437613,-0.725519,-0.242026,-0.175472,0.522264,-0.462882,-0.011468,0.055501,0.101916,-0.272316,0.393211,0.192309,-1.100851,-0.131122,0.188584,0.609723,-0.095168,0.420382,-0.105828,-0.046390,-0.325133,-0.020295,0.509909,0.582153,0.627106,0.369730,-0.312209,0.323817,-0.711923,-0.206350,1.178336,-0.327679,-0.962492,0.380767,-0.341017,-0.406699,-0.332791,-0.711253,-0.222098,0.234950,-0.080752,0.200260,-0.293487,0.682937,-0.527613,0.195879,-0.406180,-0.668472,-0.043701,-0.536760,-0.164121,-0.473511,0.006598,-0.307011,-0.098034,0.113515,0.023010,-0.097782,0.871104,-0.755523,0.042158,0.713506,0.724272,-0.520311,0.471307,0.246629,0.007018,-0.339305,0.323453,0.301395,-0.043475,0.342446,-0.352780,0.001948,0.427822,-0.012948,-0.081325,0.554884', '26667010', '35377026', '1874704', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30368448', '无限', '动作', '改编自D. Eric Maikranz所著小说《转世文献》(The Rein carnationist Papers)，聚焦一个被自己前两世的记忆缠绕的男子，引出一群几乎长生不死、几世纪来多次转生的人，被称为“无限/无穷之人”，他们的组织叫“Cognomina”。为了打败想毁灭地球的邪恶力量，他们必须依靠这个精神分裂的男子，而后者先要搞清楚：他常做的奇怪的梦都是前世的记忆。', '马克·沃尔伯格', '安东尼·福奎阿', 5.4, 12740, 'tt6654210', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2655492682.jpg', 7.6, 31.7, 46.8, 10, 3.9, '-0.042526,0.085926,-0.642436,0.924121,-0.546768,-0.052006,0.838581,-0.296351,-0.353990,-0.426910,0.030023,0.897414,0.041732,0.248253,0.245877,0.337246,0.176392,-0.674740,-0.043535,-0.016788,-0.469666,-0.294574,-0.498498,-0.130218,0.034475,-0.508867,0.710586,0.118291,-0.235117,0.064384,0.133273,0.432008,-0.089679,0.376666,-0.325209,0.109776,-0.400261,-0.080436,-0.018736,0.042489,-0.150933,-0.294626,0.014519,0.335471,-0.613307,0.090950,0.473228,-0.182684,-0.167654,-0.172417,0.559294,-0.400311,-0.299416,0.023539,0.125341,0.110575,0.213594,0.257827,0.054581,-0.359675,0.087319,0.058343,-1.433925,-0.204213,0.259021,0.083070,-0.368443,0.371550,0.300291,0.311084,-0.054394,-0.066883,0.372352,0.175331,0.432549,0.454287,-0.119158,-0.185263,-0.445584,0.448336,0.774234,-0.349875,-0.493465,0.486004,-0.089471,-0.172604,-0.320788,-0.188555,-0.350608,0.311597,0.219269,0.211427,-0.535618,0.367286,-0.656716,-0.086208,-0.103202,0.043088,-0.107382,-0.458299,-0.099656,-0.158049,-0.467611,-0.107846,-0.130192,0.044599,0.255292,-0.399033,0.876642,-0.400904,0.198618,1.045533,0.074703,-0.690084,0.718023,0.049429,0.030518,-0.167144,-0.128358,0.443835,0.209983,0.579302,-0.069902,0.406011,0.211801,0.365772,-0.861583,0.615274', '3785918', '30163500', '26678784', '4820775');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30368608', '第一头牛', '剧情', '故事改编自乔纳森·雷蒙德的小说《半条命》，雷蒙德和导演雷查德共同改编，设定在十九世纪二十年代（即1820s）的俄勒冈，一个西方厨子Cookie(约翰·马加罗饰演)来到荒蛮的西部碰运气，遇到了同样前来寻找机会的中国移民King Lu( 奥瑞恩·李饰演)，两人一见如故，并借着一头奶牛合伙做起了生 意。', '约翰·马加罗', '凯莉·莱卡特', 7.7, 14774, 'tt9231040', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2625858055.jpg', 0.6, 3, 25.4, 52.5, 18.4, '0.379797,-0.248635,-0.598082,0.834191,0.161029,-0.488489,0.493523,0.144891,-0.118929,-0.469205,-0.097570,0.873026,-0.251937,0.059349,0.527111,-0.468911,-0.296625,-0.296827,-0.173891,0.111955,0.027175,-0.272441,-0.266810,-0.224184,-0.174226,0.171892,0.577505,-0.069012,-0.299614,0.522875,0.312733,0.433234,-0.168573,-0.107709,-0.078075,0.261536,0.035330,-0.160828,-0.264086,0.346941,0.025443,0.020855,0.012539,-0.373859,0.165420,0.424120,0.526024,-0.218839,0.287644,-0.114558,0.433587,-0.143387,0.013300,-0.231207,0.312595,-0.179769,0.108021,-0.073095,0.227346,0.056746,-0.179056,-0.480118,-0.574951,0.204004,0.071022,0.105140,-0.553491,-0.069998,0.114678,0.056387,-0.154505,-0.422486,0.130560,0.222052,0.478731,0.446057,0.208557,0.268425,-0.370348,0.308425,0.725112,0.238323,-0.049351,-0.087005,0.000286,-0.568637,-0.060304,0.138462,-0.338385,-0.053105,0.688797,-0.553396,0.035180,0.165946,-0.656583,-0.233225,-0.092269,-0.219857,0.136737,-0.037791,0.171945,-0.818573,0.054971,-0.162351,0.400983,-0.035507,0.463022,-0.254870,0.630297,-0.413912,0.020890,0.330349,-0.030032,-0.359331,0.477417,-0.037999,0.274614,-0.266362,0.177645,0.370421,0.286453,0.147123,0.185918,0.481383,-0.019553,-0.131830,-0.380126,0.304874', '1829654', '1294917', '26611806', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3036997', '立春', '剧情', '北方某小城市的大龄音乐女教师王彩玲（蒋雯丽）相貌丑陋，却因天生有一副唱歌剧的嗓喉，相当清高。不甘像周围人一样过平庸世俗生活的她，一心要将根扎在北京。钢铁厂工人周瑜迷上了在广播里献声的王，以拜师的名义对她展开追求，却间接令王爱上了其一心想去北京念美院但屡考屡败的表弟黄四宝（李光洁），然而黄只当王是自己苦闷精神世界的知音。后来，黄因为认为这段纯洁关系被王玷污去了深圳，周对王的再度追求也不了了之。在王以为自己再也无法从身边找到志同道合者时，自小迷恋芭蕾、被旁人视作异类的胡老师（焦刚）走进她的生活，但胡以悲剧将自己与世俗生活作了断将追梦的王进一步打击，伤心之时，她从父母身上发现一直不愿与之握手的世俗生活也有美的一面。这时，自称身患癌症去日无多的高贝贝（张瑶）找到王，想让王助她去北京参加青年歌手比赛，王犹豫一番，决定帮她圆梦，但高的故事原是杜撰。王走到人生的十字路口时，和以前从不正眼相看的邻居（董璇）成了朋友，而在结束了与她的短暂友谊后，王以自己的方式和世俗生活言和。', '蒋雯丽', '顾长卫', 8.3, 135926, 'tt1214973', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p582511565.jpg', 0.2, 1.1, 14.9, 50.3, 33.4, '0.171288,0.302591,-0.705228,0.791767,-0.162488,-0.451743,0.810885,0.085885,-0.613314,-0.384315,-0.350295,0.682698,-0.139189,0.414897,0.001108,-0.195084,-0.025583,-0.561309,-0.094427,-0.012449,-0.244249,-0.286538,0.008500,-0.232676,-0.388587,-0.217985,0.516321,0.132631,-0.404277,0.301997,0.410739,0.143595,0.123154,0.670514,-0.330809,0.007705,-0.293789,0.393646,-0.251645,-0.062758,0.247902,-0.330712,-0.307506,-0.060039,0.150770,0.207943,0.751780,-0.151283,-0.243440,-0.185747,0.486488,-0.260220,0.038481,0.268475,0.227445,-0.071382,0.172066,-0.050936,-0.165757,-0.269378,0.093089,-0.195349,-0.503029,-0.031653,0.023750,-0.088900,-0.709095,0.394394,-0.097445,-0.149217,0.099715,-0.409583,0.407269,0.311410,0.296654,0.278535,-0.021741,-0.049599,-0.390634,0.504377,1.048262,0.426640,-0.371639,0.154124,-0.154135,-0.592465,-0.186277,-0.222399,-0.392333,-0.073644,0.340754,-0.069887,-0.259527,0.058222,-0.399206,-0.262623,0.062244,0.053520,0.209180,-0.666252,0.042153,-0.275756,-0.042168,-0.630720,-0.225492,0.016436,0.181244,-0.487405,0.674317,-0.987485,0.190675,0.382609,0.269921,-0.741936,0.949547,0.224659,0.068691,-0.140057,0.046769,0.410245,0.045990,0.408148,0.338877,0.438172,-0.22062