INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30371819', '热带雨', '剧情', '从马来西亚移居新加坡的阿玲在一间高中担任中文老师。她的家庭生活让她倍感沮丧：公公因为瘫痪无法说话，丈夫对她也日趋冷淡。夫妻二人多年来一直尝试怀孕，但情况一直没有得到好转，丈夫的不闻不问更让她感到孤独。伟伦是阿玲的一位学生，他通过中文课对老师产生了某种不可名状的情愫，两人的关系随着阿玲给伟伦的课外辅导产生了变化……', '杨雁雁', '陈哲艺', 7.5, 70622, 'tt9822706', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2573124645.jpg', 0.2, 2.3, 31.1, 56.3, 10.2, '0.295456,-0.319867,-0.732648,0.727387,-0.185495,-0.382926,0.851261,0.086606,-0.998335,-0.535727,0.282047,0.823470,-0.197677,0.294349,-0.145024,-0.057369,-0.102486,-0.533705,0.268664,0.060454,-0.066360,-0.491789,0.134701,-0.139179,-0.403016,-0.379351,0.468270,-0.329853,-0.336684,0.614542,-0.235872,0.212202,0.235650,0.755819,-0.001412,0.032131,-0.058659,0.090481,-0.383402,0.025183,0.612099,-0.128351,-0.237127,0.213661,-0.052273,0.305209,0.637358,0.197590,-0.431081,0.209447,0.346921,-0.141478,-0.233785,0.092028,0.390996,0.128766,0.069519,0.192489,-0.453338,0.003757,-0.288458,0.298666,-0.502370,0.230415,-0.023813,0.366545,-0.408607,0.631419,-0.150052,-0.327064,-0.005468,-0.582996,0.107809,0.365505,0.117387,0.556635,-0.472972,0.117485,-0.252796,-0.009392,0.866183,-0.140436,-0.500610,0.524318,-0.671461,-0.368597,0.034209,-0.022913,-0.720777,0.113428,-0.213588,0.276868,-0.414359,0.307622,-0.435261,0.055339,-0.230244,-0.176469,0.071928,-0.570633,0.178161,-0.363274,-0.313067,-0.499272,-0.480351,-0.347708,0.102706,-0.475656,0.668229,-1.188547,0.330028,0.348360,0.521749,-0.674264,0.606217,0.324913,-0.019996,-0.354258,-0.212899,0.322900,-0.484692,0.282262,0.255028,0.345152,0.141828,0.119329,-0.032646,0.257068', '35030151', '1308755', '25721544', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30372022', '绿衣骑士', '剧情', '影片根据故事《高文爵士与绿衣骑士》改编，讲述亚瑟王在自己的宫廷里举行宴会。一位绿衣骑士前来向圆桌骑士挑战：有谁敢当场砍下他的头，并让他一年后回敬一斧。高文接受挑战，砍下了绿衣骑士的头。那具依然活着的躯体捡起头颅，回到绿色的教堂。一年以后，高文践约去寻找绿衣骑士。', '戴夫·帕特尔', '大卫·洛维', 6.5, 14436, 'tt9243804', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2659155163.jpg', 3.8, 13.4, 45.8, 28.7, 8.4, '-0.007605,0.071951,-0.139667,0.404818,-0.219619,-0.342946,0.846420,-0.123095,0.341036,-0.339820,1.147704,0.625782,0.120956,-0.009029,0.559835,-0.003712,-0.177253,-0.742147,-0.294120,-0.180102,-0.576096,-0.015624,0.163354,-0.174736,0.117242,-0.511499,0.863666,-0.215421,-0.040845,0.474323,0.233353,0.088124,0.128309,0.144237,-0.451832,0.130895,0.033415,-0.201725,0.083471,0.787651,0.113352,-0.520671,-0.325381,0.093097,-0.107814,-0.031428,0.754334,-0.731338,0.358404,-0.271225,0.335608,0.109157,0.129674,0.531323,0.398800,-0.088712,0.018045,0.263422,0.168747,-0.178458,0.059914,-0.109991,-0.341859,-0.136348,-0.421094,0.274750,-1.038002,0.296352,-0.005496,0.361967,0.142202,0.040781,-0.186791,-0.105252,0.190867,0.239728,-0.012961,-0.016812,-0.321533,0.298931,0.445195,0.436434,-0.169812,-0.410375,-0.115958,-0.411439,-0.192504,-0.053586,-0.173386,-0.312299,0.548843,0.013828,0.247700,-0.215447,-0.584591,0.107838,-0.316739,-0.445119,0.096576,-0.300500,-0.330678,-0.406768,0.115279,0.109233,-0.151572,-0.255142,0.321394,-0.101928,0.489908,-0.412820,0.398691,0.400384,0.616100,0.098774,0.704223,0.148210,0.144867,0.132265,-0.000635,0.139351,0.345454,0.465712,0.138332,0.313062,-0.176729,-0.095047,-0.552559,0.232483', '21619567', '1578663', '1467779', '5319819');
