INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30373723', '除暴', '剧情', '上世纪90年代，刑警钟诚受命追捕悍匪集团“老鹰帮”。这群悍匪犯下惊天连环劫案，训练有素且纪律严明，首领张隼更屡次恶意挑衅，矛头直指钟诚。为将“老鹰帮”捉拿归案，钟诚带领刑警小队咬死不放，誓与恶势力斗争到底。数年间，警匪上演了一次次紧张刺激的较量，悍匪愈加猖獗，警方步步逼近，双方展开殊死对决……', '王千源', '刘浩良', 6.1, 245431, 'tt9877138', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2625777429.jpg', 2.4, 17.4, 56.6, 20.1, 3.7, '-0.097811,-0.408647,-0.300026,0.189261,0.575783,0.207058,0.196408,-0.148736,-0.059792,0.010170,0.530483,-0.090742,-0.002062,-0.402667,-0.124707,-0.803327,0.076830,-1.002883,-0.474300,0.264436,0.375165,-0.289911,0.163750,-0.001123,0.391605,0.176752,0.415294,0.061992,-0.479726,0.472632,0.609918,0.508079,-0.350740,-0.128975,-0.002583,-0.345710,0.265178,-0.413246,-0.485553,-0.138624,-0.181956,-0.469560,-0.081669,0.128441,-0.114068,0.163539,0.662585,-0.232278,0.019504,-0.522157,0.052324,-0.609907,-0.313782,0.348026,0.686052,0.235960,-0.154404,0.142564,0.323678,-0.250612,-0.263035,-0.081752,-0.599387,-0.009229,0.188231,-0.070353,-0.578549,-0.022415,-0.071060,0.766838,0.135565,0.403551,-0.078483,0.285607,0.670716,-0.147812,0.275957,-0.043689,-0.207769,-0.165819,0.749396,-0.228523,0.222255,-0.801867,0.376772,-0.330798,0.124348,-0.397651,-0.007999,-0.295870,0.366274,-0.488155,-0.100790,0.676888,-0.324910,-0.021183,-0.338889,0.392835,-0.033795,-0.495303,-0.092820,-0.601131,-0.148560,0.000213,0.206707,0.586983,-0.045766,-0.096959,-0.037745,-0.156118,0.023199,0.543258,0.292400,-0.276226,0.119131,0.255829,-0.305628,-0.163861,-0.126154,-0.117182,0.566697,0.077241,0.454834,-0.203733,-0.280193,0.033144,0.395186,-0.190792', '30347029', '30174085', '30249076', '3621404');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30376977', '小Q', '剧情', '本片讲述了聪明可爱的小Q在训练师悉心照料和训练过程中成长为一只合格的导盲犬，并遇到了主人李宝庭（任达华饰）——中年失明、孤僻又坏脾气的天才糕点师。他们共同生活的日子里，小Q逐渐融化并走入了宝庭的心里，温情的陪伴令处于低谷期的宝庭有了新 生活，一人一犬，深深的羁绊，他们谁也无法再失去彼此。', '任达华', '罗永昌', 6.5, 34321, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2566474488.jpg', 2.4, 12.4, 50.2, 26.8, 8.2, '0.069746,-0.033983,-0.343638,0.520834,-0.209322,-0.220000,0.677579,0.165879,-0.693437,-0.231871,0.062688,0.716365,0.147699,0.475842,0.093677,-0.518810,-0.144887,-0.711217,-0.266557,-0.134773,-0.447753,-0.145934,-0.300563,-0.169294,-0.184114,-0.420253,0.881432,0.005510,-0.209127,0.315240,0.084145,-0.076560,0.007852,0.190051,-0.329512,-0.018728,0.107603,0.181761,-0.148256,-0.125700,-0.050050,-0.067577,0.045301,-0.166644,0.156025,0.195080,0.947170,-0.408761,-0.290831,-0.221933,0.075262,-0.163035,-0.056737,-0.023601,0.125580,0.265939,0.357876,0.155571,-0.199034,0.379356,-0.384397,-0.306777,-1.021123,0.165008,0.132231,-0.091011,-0.421913,0.502730,0.361467,-0.262210,0.125865,-0.130881,0.066381,0.424572,0.353103,0.436349,-0.300450,-0.051560,-0.100730,0.399229,0.589768,-0.015372,-0.664885,0.584206,-0.340253,-0.717019,-0.092985,-0.550116,-0.474484,-0.037173,0.073562,0.519785,-0.274430,0.558503,-0.687090,0.454368,-0.265477,-0.137036,-0.051813,-0.443932,-0.008711,-0.408192,-0.220909,-0.674252,-0.494406,0.228429,0.065623,-0.235870,0.968793,-1.029022,0.292314,0.102134,0.301167,-0.444216,0.710154,0.062960,0.343875,-0.260509,-0.057407,0.677374,-0.361513,0.209886,0.201632,0.433866,-0.422021,0.282220,-0.663563,0.307149', '24284209', '25880986', '26759820', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30377703', '来电狂响', '剧情', '某天，久不谋面的老同学相约聚会。聚会在教师文伯（田雨 饰）及其妻子戴戴（代乐乐 饰）的家中举行。小人物吴小江（乔杉 饰）和老婆李楠（霍思燕 饰）、女强人韩笑（马丽 饰）、不出名的编剧贾迪（佟大为 饰）及其新结交的富家女友娇娇（奚梦瑶 饰）相继到来。身为心理医生的戴戴的一番话，让李楠对老公吴小江看手机时鬼鬼祟祟的行为起了疑。之后在众人的提议下，他们决定玩一个游戏：所有人都把手机放在餐桌中央，期间无论哪部手机接到的微信、短信还是电话都必须当众宣读或接听。光鲜靓丽的外表之下，每个人都有着不想被他人知道的秘密。却仅仅以为一部手机，让各自真实的面目大白天下……©豆瓣', '佟大为', '于淼', 5.7, 275952, 'tt9408490', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2542268337.jpg', 5.8, 25.8, 47.9, 16.9, 3.6, '0.161975,-0.038114,-0.485172,0.642368,-0.317788,-0.019375,0.174669,0.208828,-0.471201,-0.354322,0.095099,0.609216,-0.388230,0.322847,0.245064,-0.051371,-0.434750,-0.648619,0.001499,-0.112674,-0.171004,-0.196957,-0.155762,-0.034803,0.074526,0.023280,0.122855,-0.176161,0.052252,0.497785,0.469669,0.112243,-0.243593,0.453181,0.031967,-0.114361,0.119960,0.142474,-0.116817,0.073153,-0.058934,-0.288049,0.020240,0.346034,0.178600,0.272198,0.555775,-0.133689,-0.104138,0.059172,0.391614,0.207607,-0.115903,-0.021773,0.301860,0.178596,0.410665,0.167496,-0.299817,0.213677,0.329108,0.206926,-0.469368,0.069053,0.110008,0.181638,-0.329389,0.562070,-0.422407,0.009997,-0.006965,-0.453355,0.319958,0.075435,0.200471,0.355629,0.060699,-0.003122,-0.294933,0.267397,0.170075,0.546591,0.231384,0.152611,-0.179066,-0.285217,0.221891,0.032782,-0.682363,0.052697,0.248876,-0.086308,0.056237,-0.209779,-0.390923,-0.173527,0.081477,-0.117033,0.287759,-0.650396,-0.308093,-0.530502,-0.155490,-0.358721,-0.315551,0.164568,0.146171,-0.032235,0.707528,-0.871038,0.059713,0.034584,0.017519,-0.556534,0.749057,0.376227,-0.014764,-0.217496,0.055715,-0.262201,0.132031,0.282969,-0.093004,0.128784,-0.268539,-0.374997,-0.430412,0.169207', '6963575', '3445516', '5374383', '1306544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30378158', '秘密访客', '悬疑', '校车司机于困樵（段奕宏 饰）因失职酿成了一起重大的校车车祸，困樵拼死救出了似与车祸背后真相息息相关的汪楚祺（荣梓杉 饰），校车上的其他学生无人生还。得知此事家境显赫的汪父（郭富城 饰）为了隐藏这个秘密，不得不把困樵藏在自己家的地下室里长达三年，却处处暗示困樵何时自首。随着访客的到来，这个原本温馨和睦的四口之家变得越来越诡异，母亲（许玮甯 饰）整日惴惴不安，姐姐（张子枫 饰）举止一反常态，家人个个心怀鬼胎，怪事频出，这个家背后不可告人的秘密似乎即将浮出水面……', '郭富城', '陈正道', 5.3, 173483, 'tt10097384', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2629408730.jpg', 7.5, 33.6, 45.8, 11.3, 1.8, '0.436719,0.057231,-0.577963,0.291028,0.106484,-0.085019,0.676678,0.191234,-0.781653,-0.506416,0.368315,0.588064,-0.277714,0.233406,-0.042465,-0.069895,-0.258476,-0.502961,-0.071647,-0.071205,-0.009792,-0.351733,-0.251348,-0.068811,-0.265680,0.135368,0.347417,0.286511,0.094512,0.532027,0.420936,0.483680,-0.622202,0.152873,-0.134592,-0.125732,-0.054393,0.338252,-0.218404,-0.384194,0.027420,-0.346773,-0.009907,0.182290,0.017068,0.570238,0.543998,0.009061,-0.507376,-0.146886,0.497518,-0.079949,-0.033652,0.136595,0.448900,0.030977,0.191631,0.340913,-0.227896,-0.175008,0.108804,0.015466,-0.549691,-0.063554,0.368231,0.178289,-0.202498,0.023305,-0.022277,-0.267431,0.238010,-0.110920,0.313307,0.510080,0.157547,0.129991,-0.344817,0.083977,-0.603692,0.058321,0.614447,-0.169320,0.143885,0.136338,-0.193360,-0.159762,0.096731,-0.131885,-0.561790,0.186380,0.175837,0.097716,0.053798,0.403762,-0.292980,-0.127036,-0.215677,0.284942,0.017470,-0.319513,-0.131348,-0.421844,0.057685,-0.417666,-0.327755,0.184858,-0.004414,0.032138,0.349474,-0.538189,0.235110,0.254767,0.201735,-0.490181,0.236457,0.064142,0.372890,-0.158931,-0.211893,0.063534,-0.082805,0.036700,-0.219025,0.125464,-0.087905,-0.061540,-0.384190,0.042193', '25721544', '26724989', '3263169', '1301022');
