INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30384019', '死无对证', '剧情', '加里夫妇的独生子丹尼尔遭遇车祸，被肇事者沉车灭迹。丹尼尔失踪之后有证据指向他是因为贪污公款潜逃。悲痛中的父母突然想起事故同一天，加里曾带回一位汽车抛锚的女车主，当日诸多细节显示她和真正的车主在隐瞒着什么......而他们编织的谎言滴水不漏，寻求答案阻碍重重。为了最后的真相，加里夫妇通过易容瞒天过海，展开一场精心策划的较量……。本片改编自西班牙经典电影《看不见的客人》，被豆瓣评为年度冷门高分电影。', '里卡多·斯卡马乔', '斯蒂法诺·摩尔蒂尼', 7.4, 60590, 'tt7735502', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2620256769.jpg', 3.5, 4.9, 32.1, 39.4, 20, '0.190993,-0.127386,-0.497416,0.500459,0.096682,-0.022990,0.728167,-0.238872,-0.539730,-0.545480,0.370232,0.731108,-0.412339,0.080026,0.311087,-0.137057,-0.411957,-0.657100,0.121328,-0.174587,-0.072460,-0.677832,-0.136247,-0.031623,0.068048,-0.059421,0.570628,0.071519,-0.396223,0.219697,0.382944,0.463793,-0.472743,0.157819,0.109625,0.216045,0.138909,-0.002452,-0.351911,0.160237,-0.074393,-0.474718,-0.235717,0.163113,-0.242585,0.530773,0.520979,-0.136138,-0.148411,0.037211,0.444695,-0.511280,0.167735,0.137802,0.393467,0.124858,0.403275,0.423542,-0.184677,-0.391490,0.129133,0.149093,-0.696516,-0.141369,0.166817,0.277713,-0.461509,0.238109,-0.318258,0.054592,0.142561,0.002613,0.344282,0.506736,0.436153,-0.041826,-0.099807,-0.030135,-0.517276,0.319739,0.686496,-0.257101,-0.039134,0.261789,0.015911,-0.212890,0.005470,-0.177771,-0.362803,0.368254,0.598337,-0.057523,-0.169630,0.346626,-0.283977,-0.398726,-0.321694,-0.125927,-0.105395,-0.200153,-0.235241,-0.679473,-0.056099,-0.006680,-0.272330,-0.190475,-0.029610,-0.294311,0.252515,-0.594272,0.147698,0.372417,-0.046907,-0.309139,0.409031,0.016725,0.171516,-0.284496,-0.173432,0.083512,0.307829,0.208699,-0.111732,0.016055,0.105249,-0.236536,-0.169564,0.284482', '2988294', '25828589', '3119246', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30385361', '少女佳禾', '剧情', '两年前，母亲（李娟 饰）的意外遇害，令李佳禾（邓恩熙 饰）的生活彻底“黑暗”起来。面对同学的霸凌和懦弱的父亲（吴国华 饰），少女佳禾逐渐养成了有仇必报的刚硬性格。一次车祸，她撞见了在工读学校表现良好而提前归来的“少年犯”于镭（李感 饰），寻求律师无果后，佳禾决心要在14岁生日之前完成自己的“未成年复仇计划”。她跟踪并伺机接近于镭，学喝酒、泡网吧，甚至和他身边的社会青年混成一片。终于，当机会到来时，她一步步陷入了危险与犯罪的边缘……', '邓恩熙', '周笋', 5.4, 4326, 'tt11151736', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2627779454.jpg', 4.8, 34.7, 47.5, 10.8, 2.2, '-0.134268,0.082867,-0.588256,0.494604,-0.175665,-0.433062,0.579279,0.076110,-0.609985,-0.342064,0.079362,0.675379,-0.019995,0.392272,0.559525,-0.309190,-0.272895,-0.820555,-0.093416,0.112803,-0.288245,-0.306227,-0.186613,-0.097472,-0.092305,-0.378988,0.676017,0.163625,-0.153268,0.632147,0.196928,0.287874,-0.028828,0.430160,-0.011997,-0.318931,0.139016,0.091054,-0.427434,0.119864,0.147088,-0.496924,-0.067520,0.182547,0.044218,0.317711,0.767820,-0.233974,-0.458637,-0.290135,0.372070,-0.209373,-0.169388,0.219882,0.284736,0.066543,0.460973,0.246172,-0.182877,0.088460,0.005249,-0.164508,-0.442484,0.078227,0.107417,-0.087825,-0.430477,0.305787,-0.033073,0.126950,0.340352,-0.338049,0.084614,0.404398,0.129085,0.143596,-0.452986,-0.083460,-0.244266,0.142678,0.651862,0.000634,-0.113672,0.378873,-0.122471,-0.257441,0.068566,-0.182707,-0.417523,0.132129,0.257955,0.167546,-0.474480,0.178514,-0.395153,-0.269754,-0.172763,0.140426,-0.086174,-0.270792,-0.169020,-0.394525,-0.186273,-0.335256,-0.428400,0.234602,-0.209149,-0.166361,0.215941,-0.922809,0.477953,0.375338,0.093812,-0.548783,0.465573,0.128838,-0.032833,-0.311663,0.090667,0.189470,-0.237977,0.352344,-0.122869,0.222391,-0.084429,-0.132262,-0.436820,0.461277', '30345227', '1301022', '2027925', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30386678', '心愿房间', '剧情', '马特（凯文·詹森斯 Kevin Janssens 饰）和凯特（欧嘉·柯瑞兰寇 Olga Kurylenko 饰）是一对非常恩爱的夫妻，两人美满的婚姻里唯一的遗憾就是没能够拥有他们爱情的结晶，凯特曾经两度怀孕，都不幸流产了。为了缓解意外带来的阴翳，夫妻两人前往一座位于纽约郊区的古宅中度假，让两人没有想到的是，他们在房子里找到了一间被隐藏的密室。这是一个拥有神奇魔法的房间，只要你身在房间之中，无论许什么物质方面的愿望 ，都能够实现。利用这个房间，夫妻两人瞬间拥有了很多他们想买但舍不得买的东西，然而，起初了兴奋感平静之后，凯特内心的贪欲开始蠢蠢欲动，她真正想要的“东西”只有一个。©豆瓣', '欧嘉·柯瑞兰寇', '克里斯蒂安·福克曼', 6.6, 14221, 'tt8485364', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2557967220.jpg', 1.4, 9.2, 52.6, 29.1, 7.6, '0.665730,0.053997,-0.864202,0.631457,-0.059358,-0.266100,1.001980,-0.054419,-0.636017,-0.501863,0.061422,0.712244,-0.118396,0.155983,-0.099754,0.146057,-0.281027,-0.412857,0.110566,-0.473115,-0.408174,-0.547155,-0.595615,-0.327646,-0.313343,-0.153210,0.551496,0.280328,0.026328,0.372843,0.285712,0.229278,0.045110,0.335692,-0.303948,-0.000591,0.121589,0.169998,-0.328814,0.232276,0.068289,0.031936,-0.008586,0.604040,0.193354,0.182612,0.661428,-0.215819,-0.229328,0.173577,0.112560,0.153148,-0.153939,0.198914,0.027294,-0.174622,0.407496,0.041815,-0.300996,-0.175339,0.392660,-0.071632,-0.945617,-0.063064,0.182984,-0.050944,-0.324197,0.354054,0.115076,-0.289798,0.282373,-0.314634,0.417320,0.521216,0.530242,0.655023,-0.209894,-0.146097,-0.808587,-0.036839,0.780821,-0.303053,-0.169115,0.724045,-0.600441,-0.531478,-0.144755,-0.096747,-0.445530,0.154765,0.240431,0.476184,-0.013736,-0.038113,-0.700752,0.140096,-0.113320,-0.076426,0.003776,-0.630602,-0.031584,-0.377782,-0.273293,-0.320210,-0.352297,0.216290,-0.130985,-0.372501,0.529477,-0.996996,0.282730,0.277116,0.375934,-0.596402,0.851930,-0.089176,0.160373,-0.157910,0.138379,0.154662,-0.141595,0.128062,0.242182,0.386194,-0.093003,0.140215,-0.506443,0.595118', '1296370', '3055049', '1308755', '1783461');
