INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30389258', '月半爱丽丝', '喜剧', '胖女孩林晓曦（关晓彤 饰）性格开朗大方，她和音乐制作人韩冰（黄景瑜 饰）是多年好友，两人友达以上，恋爱未满。在一次奇幻的经历后，林晓曦出人意料地变身成为美丽的爱丽丝，并得以接近自己的偶像黄可（官鸿 饰）。虽然赢得了偶像的关注，但夹在青梅竹马与偶像之间时，林晓曦渐渐明白了什么……', '关晓彤', '张林子', 3.4, 24965, 'tt11575350', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2622519829.jpg', 50.3, 33.2, 13.2, 1.6, 1.7, '0.209103,0.060270,-0.550235,0.524969,-0.031352,-0.242926,0.631069,-0.013983,-0.696831,-0.061259,0.042820,0.707686,-0.608341,0.284462,0.245364,-0.164278,-0.101512,-0.782735,0.124580,-0.245544,-0.095272,-0.498481,-0.331164,0.291838,-0.267117,-0.391425,0.561120,-0.137348,-0.236079,0.530292,0.496026,-0.148270,-0.132625,0.311553,0.007953,-0.056965,0.281627,0.268723,-0.308382,0.002887,-0.154096,-0.113443,-0.236412,0.175745,-0.056278,0.194869,0.730286,-0.197129,-0.245975,0.184476,0.256822,-0.195943,-0.341786,-0.101913,0.037863,0.141005,0.354346,-0.022662,0.000814,0.053696,-0.034555,0.102584,-0.553994,0.158628,0.075884,-0.008553,-0.488479,0.605281,0.191819,-0.142797,0.215694,-0.337499,-0.013831,0.298135,0.360039,0.046270,0.015878,0.103761,-0.107449,0.467884,0.729274,0.422585,-0.255810,0.806828,-0.287307,-0.530384,-0.362361,-0.208775,-0.533409,0.236053,0.193351,0.206110,0.047509,0.214075,-0.411422,-0.184141,-0.258398,0.129674,0.229712,-0.398116,-0.203036,-0.307271,-0.241390,-1.014367,-0.456354,-0.041150,-0.191943,-0.680979,0.937597,-1.074719,0.200556,0.185608,0.102882,-0.439866,0.727434,0.187977,-0.213779,-0.293982,-0.255697,0.179199,-0.154325,-0.350042,-0.090136,0.284493,-0.323476,-0.030289,-0.338927,0.285367', '26354526', '21766698', '1292219', '35030151');
