INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30390144', '别告诉她', '剧情', '影片讲述一个华人家庭的奶奶被诊断罹癌，但家人选择隐瞒奶奶，假借一场婚礼的名义让所有家人回家见奶奶最后一面，但在纽约长大的碧莉（奥卡菲娜饰演）认为知道自己病况是奶奶的人权，因此在华人家庭中上演一场中西文化冲突，一部寻根家庭喜剧。故事改编自华裔女导演王子逸自己的家庭故事，她也因本片被《综艺》杂志评选2019年必关注导演之一。', '奥卡菲娜', '王子逸', 7.2, 89499, 'tt8637428', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2578097413.jpg', 0.9, 5.4, 38.2, 43.8, 11.7, '-0.027227,-0.231102,-0.232396,0.478397,0.344198,0.036667,0.375683,0.175885,-0.541337,-0.557597,0.509274,1.021893,-0.152730,0.118840,0.196167,-0.203416,-0.079575,-0.405871,0.207295,0.365401,0.207565,-0.374497,0.170952,0.024704,-0.267269,-0.315172,0.593188,-0.426599,-0.126737,0.357666,0.303305,0.058994,-0.108316,0.008268,0.261941,0.317581,0.070621,0.031039,-0.675276,0.230097,0.230207,-0.017756,-0.365831,0.143866,0.049682,0.205753,0.656220,0.020826,-0.031981,-0.109557,0.876543,-0.389968,-0.108380,0.173522,0.544637,0.136298,0.595632,0.611130,0.061155,-0.266434,-0.014045,0.029893,-0.446007,0.079294,0.508956,0.214505,-0.567269,0.474743,-0.041850,-0.181092,-0.222950,-0.065572,0.548658,0.111558,0.516251,0.333428,-0.099577,0.221730,-0.153355,0.531246,0.796780,-0.080682,0.056151,0.413874,-0.444308,-0.216219,0.037636,-0.438189,-1.021614,0.541201,-0.172586,-0.435152,-0.425550,0.407400,-0.365610,-0.261523,-0.354693,-0.289635,0.171080,-0.586227,0.227248,-0.491129,-0.357657,0.024939,0.046152,-0.387212,0.278654,-0.356752,0.995335,-0.551893,0.062379,0.452497,0.187419,-0.648756,0.901290,0.601042,0.216068,-0.117441,0.036138,0.062683,-0.009842,-0.402113,-0.403783,0.065654,0.119230,-0.181307,-0.184493,0.181891', '25738406', '30353869', '1292720', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30390185', '一切如你', '剧情', '影片的初衷是，有四位年轻人，他们用镜头记录下了爷爷奶奶的现实生活，在创作过程中，他们了解到中国当今的老龄化现状，有太多的老人缺少陪伴，于是，他们决定用自己的所学，拍摄这部电影《一切如你》。从年轻人角度出发，讲述了十个“养老、孝老、敬老”的故事。他们的举动得到了老一辈电影艺术家的鼎力支持，这次拍摄是一次难忘的创作历程，更是一次肩负使命的文化传承。', '于蓝', '黄宏', 7.5, 5604, 'tt10974336', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2566220443.jpg', 2.6, 6, 30.2, 34.9, 26.4, '-0.049559,-0.120882,-0.519061,0.723321,-0.008236,-0.154380,0.376657,-0.133558,-0.576416,-0.276575,0.421758,0.835635,0.002541,0.348501,0.265792,-0.280224,-0.516135,-0.619166,-0.108910,-0.040428,-0.320103,-0.298042,-0.014760,-0.410185,-0.182525,-0.488558,0.806236,0.177002,-0.652317,0.014408,0.131957,-0.056882,-0.003883,0.113739,-0.249477,0.055497,-0.182018,0.014309,-0.656025,0.189768,0.125959,-0.153646,-0.504553,0.214856,-0.166412,0.259411,0.589196,-0.177331,-0.331882,0.210822,0.532287,-0.350295,-0.243678,-0.232851,-0.048030,0.288754,0.290041,0.606597,0.141045,-0.060437,-0.490321,-0.404920,-1.093399,-0.303516,0.150342,0.318983,-0.792960,0.472926,-0.029063,0.012799,0.070929,-0.638524,0.117256,0.169255,0.530353,0.364719,0.000239,-0.121837,-0.359624,0.730176,0.800088,-0.044162,-0.376910,0.731080,-0.313786,-0.512544,-0.366555,-0.244370,-0.472269,0.473699,0.264618,-0.206910,-0.179377,0.335737,-0.340929,0.038107,0.110638,-0.744912,0.251610,-0.550320,0.136003,-0.756083,-0.333749,-0.374089,-0.382621,-0.377641,0.248225,-0.577606,1.432618,-0.576088,0.062568,0.550832,-0.156974,-0.582832,0.971746,0.002466,0.056830,-0.351887,0.052020,0.059667,-0.154409,0.155295,-0.201535,0.217310,0.012889,-0.050510,-0.619209,0.718176', '27602116', '24284209', '1908036', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30391228', '了不起的老爸', '剧情', '一个患有罕见疾病却怀有“马拉松梦”的少年肖尔东（张宥浩 饰），一个固执逼迫儿子预习“盲人生活”的出租车司机父亲肖大明（王砚辉 饰），互不理解的父子俩，却在一场马拉松比赛中“互换身份”，并肩站在了起跑线上……影片通过对“命运”持有不同态度的一对单亲家庭父子，讲述了一个用爱向阳而生的故事。', '王砚辉', '周青元', 6.5, 39566, 'tt11317408', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2654767767.jpg', 0.8, 10.4, 56, 28.4, 4.4, '-0.022725,-0.050817,-0.301553,0.859471,-0.114700,-0.303842,0.719381,0.213718,-0.348828,-0.185778,0.517893,0.881515,-0.233651,0.137979,0.160829,-0.208873,-0.140407,-0.546050,-0.062651,0.248523,-0.394108,-0.540302,-0.010555,-0.188410,-0.185759,0.065409,0.559140,-0.209860,-0.351108,0.762055,0.356277,0.137890,-0.315953,-0.005649,-0.248848,-0.142360,-0.091219,0.412831,-0.471125,0.089037,-0.105481,-0.060625,-0.005371,0.211722,-0.008563,0.332933,0.847433,-0.456260,-0.115253,-0.006584,0.382222,-0.134601,-0.298761,0.101745,0.469320,0.301024,0.085286,0.037924,0.019847,0.039497,-0.117374,0.094893,-0.538592,-0.178487,0.078359,0.367024,-0.392856,0.704090,0.086872,-0.134125,0.017086,-0.212356,0.091196,0.178649,0.459750,0.709537,-0.085335,-0.196852,-0.424577,0.051355,0.791494,0.146320,-0.169388,0.686402,-0.715304,-0.420351,-0.234547,-0.033373,-0.794029,-0.088927,0.195051,-0.375979,-0.204013,0.136346,-0.228012,0.108598,0.156866,0.298876,0.069442,-0.669493,0.166212,-0.390023,0.030886,-0.561260,-0.387223,0.006908,-0.108180,-0.508350,0.720689,-0.660097,0.008523,0.196415,-0.035467,-0.464248,0.701341,0.412981,0.281591,-0.438004,0.206811,0.386942,-0.053950,-0.102029,-0.290677,0.218375,-0.286335,0.520207,-0.424328,0.517372', '4817024', '3445516', '1309161', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30391241', '切尔诺贝利·禁区电影版', '科幻', '在切尔诺贝利异常区，在第4发电机组的保护性石棺下，全球金泰克公司正在进行非法建筑。这些计划需要阻止建立一个特别的州际委员会，但就在新闻发布会上，不明身份的恐怖分子组织的头目。他成功地与该区域作战，但现在似乎该区域本身已经俘获了他。他的四分之一的朋友——一切，时间，时间和夜晚——不需要其他任何东西，只是再次踏上旅程，试图拯救帕夏，并制造一个全球性的威胁。', '康斯坦丁·达维多夫', '德米特里·基谢廖夫', 7.5, 6746, 'tt10100620', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2570615901.jpg', 1.3, 5.6, 31.3, 41.9, 19.9, '0.306787,0.383658,-0.716077,0.546208,0.184628,0.060207,0.613912,-0.096393,-0.465799,-0.299812,-0.008527,0.460689,0.125393,-0.063585,-0.058989,-0.057785,-0.547590,-0.606135,-0.233033,-0.273301,-0.549496,-0.550803,-0.199146,-0.331631,-0.035084,-0.076750,0.989225,0.363983,-0.226301,-0.104097,0.108749,0.220568,-0.146744,0.776575,-0.122596,-0.494299,0.321522,-0.133746,-0.359755,0.429774,-0.105896,-0.180845,-0.144888,0.499413,0.045329,0.507392,0.615643,-0.237835,-0.399294,-0.161618,0.237132,-0.277308,0.150625,-0.200367,0.326368,-0.113301,0.302111,0.357206,0.022704,0.225707,0.040923,-0.307045,-0.887062,-0.209137,0.010000,0.247944,-0.398520,0.430297,-0.314555,-0.040803,-0.095715,-0.405022,0.249458,0.854655,0.347069,0.139596,-0.365405,-0.105396,-0.737137,0.026052,0.547482,0.102802,-0.261786,0.530536,-0.227781,-0.656875,-0.411969,-0.211326,-0.103360,-0.148104,-0.050081,0.189004,-0.236120,0.256762,-0.864782,0.179225,-0.200178,-0.667778,-0.056796,-0.592320,0.225501,-0.773366,0.029589,-0.143335,-0.289837,0.168380,0.225920,-0.144418,0.486302,-0.993238,0.192495,0.699006,0.404249,-0.564367,0.422322,0.229909,0.122939,-0.273767,-0.129037,-0.041080,-0.046782,0.590038,-0.088434,0.355857,0.189044,-0.532026,-0.415216,0.441852', '26759819', '1986338', '6532822', '6519585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30391289', '无罪谋杀：科林尼案', '剧情', '柯林尼（弗兰科·尼罗 Franco Nero 饰）是一位勤勤恳恳工作了几十年的老打工人，某一日，竟然向警方投案自首，声称自己杀害了一位名叫迈耶（曼弗莱德·扎帕卡 Manfred Zapatka 饰）的男子。莱恩（埃利亚斯·穆巴里克 Elyas M''Barek 饰）是负责替柯林尼辩护的律师，这是初出茅庐的他承接的第一个案子。实际上，迈耶是莱恩的老熟人了，曾经，莱恩受过前者的诸多照顾。与此同时，莱恩的对手理查德（海纳·劳特尔巴赫 Heiner Lauterbach 饰）是一位经验非常丰富的法庭老手。在寻找真相的过程中，柯林尼一直都保持着沉默，这让莱恩的工作根本就无处施展。然而，随着调查的推进，莱恩之间发现，自己要揭开，是笼罩在德国司法史上的一块巨大的黑幕。©豆瓣', '弗兰科·内罗', '马可·克罗伊茨派因特纳', 7.5, 19901, 'tt8739752', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2646050974.jpg', 0.2, 2.6, 31.2, 52, 14, '0.119672,-0.363622,-0.577314,0.618340,-0.189037,-0.410462,0.510071,0.205089,-0.429452,-0.542464,0.377443,0.539686,-0.083776,0.026749,0.512081,0.072936,-0.315147,-0.658918,-0.180862,-0.225803,-0.268307,-0.757104,-0.515506,-0.329948,-0.170185,-0.330567,0.316072,-0.185026,-0.193271,0.216572,0.440537,0.549699,0.255879,0.291148,-0.077694,-0.064163,0.433216,-0.384670,-0.177012,0.224361,0.157285,-0.070215,-0.184064,0.227368,0.133387,0.586241,0.213608,-0.268823,0.076652,0.040518,0.151825,-0.241743,0.165161,-0.003817,0.435333,-0.230007,-0.019160,0.397027,-0.451115,-0.023204,0.258660,-0.193267,-0.778937,-0.047563,0.081434,0.363977,-0.732281,0.153283,-0.141712,0.036706,-0.099203,-0.227414,-0.147832,0.295306,0.039256,0.340150,0.142665,0.001972,-0.427010,0.050327,0.280839,0.066760,-0.388946,0.140123,-0.239288,-0.225521,-0.026060,-0.092869,-0.456929,-0.176468,0.260833,-0.144128,0.133849,0.417159,-0.459166,-0.160316,-0.490290,-0.310073,-0.028468,-0.174681,-0.251099,-0.773269,0.005344,-0.306329,-0.362806,-0.023364,-0.128685,-0.128518,0.533815,-0.673147,0.254297,0.490793,-0.051971,-0.077498,0.669987,0.142721,0.273959,-0.178541,-0.230058,0.269763,0.466380,0.262226,0.139445,0.343457,0.232938,-0.394034,-0.311412,0.475063', '1307442', '24753477', '1793491', '30143331');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30391300', '我们是小僵尸', '剧情', '日本新锐导演长久允一鸣惊人赢得日舞影展全球剧情片类评审团特别奖、柏林影展新世代单元青少年评审团特别提及的首部剧情长片《爸妈死了，我却不想哭》，描述四名面对父母死亡却无法流出真诚眼泪的青少年，宛如冷血殭尸的他们决定组成乐团，踏上寻找血泪的长征。影片以仿真RPG游戏的趣味模式，让观众和角色一起共同打怪破关。除了年轻世代演员的精彩表现，还吸引永濑正敏、菊地凛子、池松壮亮、佐佐木藏之介一票影帝后助阵，演绎不同世代的代表精神。', '二宫庆多', '长久允', 7.6, 8249, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2541300705.jpg', 1.2, 5.2, 28.3, 43.1, 22.3, '-0.137189,-0.167314,-0.212105,0.398997,0.265146,-0.149344,0.262607,-0.059422,-0.135275,0.163329,0.248285,0.769064,-0.461955,0.139325,-0.120028,-0.418070,-0.354441,-0.511723,-0.333553,0.170411,0.215589,-0.036073,0.025350,0.142875,-0.200347,-0.344055,0.990582,-0.065290,-0.254779,0.565071,0.412410,0.147213,-0.384168,-0.048382,0.210963,-0.027749,0.269561,0.045212,-0.343011,0.022578,-0.267527,0.038302,-0.327579,0.024830,0.111850,0.285720,0.409571,-0.177252,0.010978,-0.136360,0.370564,-0.371747,-0.138435,-0.104769,0.047336,0.039579,0.541761,0.219283,0.312093,0.028963,-0.095468,-0.071207,-0.891351,0.022602,0.514582,0.247232,-0.286006,0.303344,0.035638,-0.088685,0.190157,0.035346,-0.030030,-0.203397,0.535868,0.147350,-0.089429,0.263629,0.004392,0.662393,0.680038,-0.390260,-0.403668,0.315573,-0.059371,-0.455657,0.002975,-0.622709,-0.368138,0.312601,0.091129,-0.052946,0.197656,0.054142,-0.336732,0.007812,0.098467,-0.127813,0.006937,-0.256231,0.156185,-0.744384,-0.037598,-0.090782,-0.034661,-0.127704,0.148009,-0.418702,0.978651,-0.378958,-0.079282,0.169671,0.163922,-0.368978,0.479775,0.246154,-0.222533,-0.317168,-0.175593,0.184157,-0.179358,-0.064435,-0.095326,0.207663,-0.115776,-0.183387,-0.240581,0.395603', '27602116', '25880986', '1322847', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30391372', '巴尔干边界', '动作', '1999年, 南斯拉夫。 俄罗斯特遣部队被命令控制科索沃的斯拉蒂纳机场，直到增援部队抵达。但这一战略目标对于阿尔巴尼亚战地指挥官和北约将军来说极为重要。该组织被迫与恐怖分子进行不平等的战斗。俄罗斯维和部队和北约部队正赶往机场。世界再次接近一场大战。但是特别组织的指挥官安德烈 ·沙塔洛夫并不接受政治：在机场，他心爱的女孩亚斯纳是人质之一......', '安东·庞布施尼', '安德烈·沃金', 7.1, 18421, 'tt5951188', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2548930005.jpg', 0.6, 5.7, 40.8, 45, 7.9, '0.410081,0.089963,-0.810408,0.602185,0.327051,-0.043997,0.364942,-0.141329,-0.375401,-0.259393,0.220620,0.842175,0.329315,-0.432057,0.587664,0.195808,-0.556176,-0.660605,-0.228903,-0.102400,-0.320258,-0.754828,-0.125939,-0.278342,-0.018316,-0.205687,0.957974,0.094809,-0.177845,0.391576,0.237700,0.499770,0.094203,0.762262,0.206202,-0.493026,0.678805,-0.485772,-0.584478,0.228775,-0.062288,0.218451,-0.211411,0.382473,0.061298,0.232103,0.545485,-0.637008,0.127941,-0.494432,-0.269828,-0.767675,-0.050448,0.051729,0.410855,-0.128743,-0.018121,0.350619,0.262963,0.097727,-0.209770,-0.195341,-0.292724,0.098604,-0.025057,-0.050739,-0.358414,0.425050,-0.682934,0.150907,0.220847,-0.144504,0.344568,1.113681,0.265187,0.394578,-0.331728,-0.064791,-0.757238,-0.405879,0.757727,-0.007921,-0.456676,-0.043889,-0.094469,-0.749492,-0.023370,-0.371905,-0.353033,0.002284,-0.213969,-0.223797,0.007324,0.292368,-0.724178,0.152503,-0.510741,-0.622052,0.084309,-0.493588,0.141122,-0.879422,-0.245547,-0.321030,-0.279904,0.293520,0.161396,0.517431,0.749524,-0.902266,-0.026138,0.526245,0.419978,-0.623062,0.392822,0.544631,0.175840,-0.581885,0.136415,0.550945,0.038932,0.515370,-0.069829,0.345608,-0.105157,-0.359796,0.027542,0.222897', '25978126', '1316511', '1424552', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3039187', '阿基里斯与龟', '剧情', '富商之子仓持真知寿（吉岡澪皇 饰）从少年时代便痴迷绘画，随着父亲企业的破产，父母相继自杀，真知寿的童年也变得一片黯淡。即便如此，他也从未放弃成为画家的梦想。时光流转，转眼长成青年的真知寿（柳忧怜 饰）自顾自徜徉在艺术的世界中。为了提高技艺，他就读艺术学校，遇到一班志同道合的好朋友，和他们经历了喜怒哀乐、悲欢离合。他经常往返于画廊，而作品却迟迟得不到赏识，唯有同在印刷厂打工的少女幸子（麻生久美子 饰）真切理解真知寿的艺术。人过中年，真知寿（北野武 饰）依旧默默无闻，但即使生活怎样清贫，他的妻子幸子（樋口可南子 饰）始终与其相伴，相互搀扶继续着这条充满磨难的艺术之路……本片荣获2009年保加利亚索非亚国际电影节观众大奖。©豆瓣', '北野武', '北野武', 8.3, 23405, 'tt1217243', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2194386594.jpg', 0.4, 1.4, 15.5, 49.3, 33.4, '-0.374385,0.042889,-0.328722,0.541753,0.045357,-0.340950,0.342580,0.203160,-0.410664,-0.336542,0.133535,0.700465,-0.063352,0.384761,0.327329,-0.260905,-0.137298,-0.510958,0.232531,-0.014303,0.074832,-0.248744,-0.103491,0.062454,-0.450710,-0.191360,0.861305,0.239161,0.062117,0.552309,0.188578,0.309180,-0.364690,0.104617,-0.163693,-0.047359,0.158190,0.475483,-0.441874,-0.285974,-0.168459,-0.347239,-0.499404,-0.244438,-0.041869,-0.128134,0.669045,-0.158711,-0.098350,-0.062230,0.363838,0.023911,-0.243410,-0.011968,0.007325,0.122099,0.016537,0.353830,-0.046838,-0.078012,-0.034829,-0.039331,-0.487703,-0.105325,0.347253,0.159588,-0.404370,0.642488,0.273593,-0.199108,-0.071320,0.050485,-0.097795,0.007912,0.210470,0.274892,-0.126523,0.192580,-0.126903,0.645249,0.500215,0.108929,-0.471430,0.618508,-0.507861,-0.527258,-0.046913,-0.359372,-0.747474,-0.015117,0.035903,0.041342,-0.023469,0.096660,-0.426107,-0.035936,0.010018,0.083682,0.304978,-0.189610,0.089798,-0.561503,0.171243,-0.511497,-0.310990,0.110055,-0.044015,-0.380904,0.830798,-0.621891,0.184877,0.391206,0.197475,-0.299049,0.860846,-0.150703,0.001680,-0.248338,-0.401803,0.603518,-0.043961,0.131803,-0.141707,0.068452,-0.145159,0.114702,-0.392424,0.581950', '2338019', '1908036', '3811356', '30349667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30394484', '然后我们跳了舞', '剧情', '梅拉布（列文·格尔巴赫亚尼 ლევან გელბახიანი 饰）出生于舞蹈世家，专研格鲁吉亚民族舞，然而，这种舞蹈追求的是强劲有力的男子气概，可梅拉布自幼就身材娇小一副弱不禁风的样子，因此，无论他怎样的努力，却总是遭到教练根本性的否定。某日，舞蹈队里来了一位名叫伊拉克利（巴奇·瓦利什维利 ბაჩი ვალიშვილი 饰）的新队员，这个男人幽默风趣，自由不羁，同时也有着极强的专业素养。在伊拉克利的刺激之下，梅拉布再度燃起了斗智，想要和他一分高下，与此同时，还有另外一种隐秘的感情在梅拉布的内心里渐渐苏醒，而他知道，这种感情很可能会毁掉自己的前途，乃至整个人生。©豆瓣', '列文·格尔巴赫亚尼', '列万·阿金', 7.8, 12673, 'tt8963708', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2554393520.jpg', 0.5, 1.5, 24, 52.9, 21, '0.178744,0.025764,-0.646301,0.671534,-0.112951,-0.098041,0.602135,0.050634,-0.552429,-0.298986,0.128295,0.750847,-0.020470,0.270225,0.261466,0.109452,-0.328108,-0.801275,-0.071068,-0.121240,-0.234383,-0.245931,-0.505233,0.027616,-0.141571,-0.465230,0.509147,0.004951,-0.341437,0.423676,0.317515,0.537761,0.290467,0.279049,-0.008075,-0.063136,-0.001213,-0.229052,0.112642,-0.008551,0.133612,0.108093,-0.193590,0.293293,-0.036872,0.508670,0.524985,-0.323934,0.045181,0.035383,0.571317,-0.035477,0.111971,0.169145,0.024676,-0.115882,0.013917,-0.145847,-0.356827,0.157901,0.243931,-0.208715,-0.672131,-0.058716,0.126899,0.216869,-0.651093,0.491856,0.069660,-0.217198,-0.011992,-0.118797,-0.071454,0.182958,0.285229,0.338315,-0.091873,0.057278,-0.393628,-0.194599,0.597762,0.151334,-0.529539,0.121684,-0.702702,-0.326672,-0.050243,-0.494361,-0.308333,-0.398548,0.144720,0.138441,0.189980,0.160993,-0.545097,0.203122,-0.292575,0.374194,-0.223870,-0.406368,-0.135763,-0.302273,-0.109735,-0.606992,-0.210527,0.145207,-0.051040,-0.220170,0.808700,-0.974841,0.006391,0.322499,0.178937,-0.189003,0.327379,0.170953,0.053089,-0.098052,-0.365155,0.424649,-0.083482,-0.119401,-0.155505,0.682501,0.180394,-0.262284,-0.127708,0.581647', '35030151', '4127270', '26809007', '35144311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30394535', '被光抓走的人', '剧情', '据说该片的创作灵感来源于董润年的一个脑洞：“如果有一道神秘的光把一部分人抓走，社会的平静与法则被打破，我们该怎么办？” 在导演的脑洞中，光代表什么？为什么人会被光抓走？谁会被光抓走？留下来的人要怎么办？这一系列疑问未来都需要在片中得到解答。', '黄渤', '董润年', 6.9, 175274, 'tt10489348', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2575887979.jpg', 1.5, 9.3, 42.9, 36.7, 9.6, '0.126700,0.304997,-0.592986,0.328461,-0.387906,0.019954,0.258836,-0.203723,-0.309672,-0.420838,-0.059303,0.504073,-0.217369,0.251857,0.168047,0.231067,-0.144597,-0.334118,0.207628,-0.299798,-0.576554,-0.406963,-0.432093,-0.141965,0.465693,-0.464089,0.608600,0.565530,-0.352317,-0.197601,0.426151,0.232542,-0.211874,0.506426,0.155132,0.078514,-0.011078,-0.181567,0.008936,0.019371,-0.208035,-0.381161,-0.104732,0.054340,-0.270185,0.050143,0.310078,-0.200410,-0.200231,0.174983,0.699136,-0.581903,0.062959,0.053709,0.000445,-0.002027,0.084978,0.626521,-0.302414,0.125467,0.018398,-0.069745,-1.299492,-0.266691,0.381866,0.383578,-0.660220,0.392607,0.246783,-0.362203,-0.007320,-0.196172,0.045872,0.365069,0.482011,0.774440,-0.324336,-0.119098,-0.691815,-0.023789,0.903898,-0.362073,-0.179613,0.245695,0.142445,-0.150212,-0.427402,-0.040190,-0.356587,0.322482,0.364160,0.077079,-0.452529,0.109127,-0.346582,-0.173626,0.033206,-0.040859,-0.078883,-0.692692,-0.289248,-0.156452,0.079634,-0.067474,-0.090568,0.273368,0.276727,-0.108866,0.953489,-0.727194,0.262781,0.633423,0.504935,-0.627706,0.554827,0.382258,-0.287097,-0.338431,-0.258481,-0.454499,0.701701,0.078772,0.083024,0.063792,0.372828,-0.108479,-0.048193,0.205713', '30163500', '26678784', '25917239', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30394797', '尚气与十环传奇', '动作', '故事发生在《复仇者联盟4：终局之战》事件之后，尚气（刘思慕 饰）自幼接受父亲（梁朝伟 饰）的铁血战斗培训，精通各种武术招式。长大后为了逃离家乡，他改名换姓展开新生活，认识了新挚友凯蒂（奥卡菲娜 饰），平静日子就这样过了十年，直到过去再度找上门……', '刘思慕', '德斯汀·克里顿', 6.1, 200347, 'tt9376612', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2674321872.jpg', 4.3, 19.7, 50, 21.2, 4.8, '-0.201435,0.023773,-0.357632,0.301832,0.422214,-0.298507,0.288115,-0.300460,-0.583084,-0.762973,-0.067377,0.352236,-0.073828,0.237281,0.337303,-0.414720,-0.407180,-0.706773,0.182212,-0.282527,-0.250983,-0.180509,0.047882,0.017873,0.056138,-0.409796,0.537301,-0.108939,-0.222027,0.523055,0.299998,0.283654,-0.121794,0.105551,-0.017283,0.145068,0.121325,0.446745,-0.865643,0.029613,-0.158305,-0.170838,-0.204587,-0.143950,0.131887,-0.106103,0.671011,-0.104854,-0.121518,-0.299759,0.279729,0.078701,-0.226277,0.165733,0.519269,0.351982,0.090513,0.460996,0.038556,0.017321,-0.500822,-0.253338,-0.156454,0.197997,0.027141,0.011567,-0.555593,0.067448,-0.156874,0.057326,-0.076755,-0.417231,-0.058580,0.708222,0.774736,0.120606,0.086730,0.417697,-0.087215,0.564698,0.856721,-0.319482,-0.300600,0.403177,0.172136,-0.467026,-0.053067,-0.488531,-0.139372,0.092052,0.077480,-0.052563,-0.067221,0.629670,-0.494548,-0.227305,-0.116121,-0.048791,0.380767,-0.024547,0.001490,-0.690902,-0.241435,-0.329410,-0.466541,-0.089315,-0.319226,-0.269831,0.607496,-0.905493,0.582601,0.103125,0.097658,-0.704642,0.170758,0.223654,0.304732,-0.256427,0.373953,0.731140,0.085915,0.280338,-0.008570,0.127152,0.053044,-0.060834,-0.098701,0.400871', '1293265', '1433736', '1507140', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30394807', '蜡笔小新：新婚旅行飓风之遗失的野原广志', '喜剧', '这一次的舞台是澳大利亚，野原家族，第一次的新婚旅行，对于从来没有过新婚旅行的美伢&广志二人而言，某天。美伢找到了一个可以全家超低价参加新婚旅行的旅游活动。于是，美亚决定动员一家参加这场活动，但是，在旅途的前方等待他们的并非火热的甜蜜爱情蜜月，而是猛烈又危险的大冒险？？', '小林由美子', '桥本昌和', 8.3, 15372, 'tt10208548', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2549326655.jpg', 0.5, 2, 18.5, 42.3, 36.8, '0.373410,-0.232823,-0.886542,0.423628,0.196372,-0.272329,0.644169,0.114788,-0.327047,0.136521,0.299267,0.574494,-0.265319,0.285531,0.360220,0.229233,-0.024613,-0.481040,-0.019236,0.085463,-0.119493,-0.411159,-0.025417,0.081799,0.065387,-0.177086,0.539504,0.201438,-0.017636,0.968827,0.354968,0.066566,0.011125,0.466961,-0.041919,-0.507774,0.390682,0.508651,-0.721456,0.511715,-0.265577,0.327852,-0.301399,0.472778,0.137116,0.549062,0.666012,-0.369460,-0.184210,0.055862,0.141975,-0.287663,-0.422124,0.216669,0.212772,-0.202902,0.354329,0.260316,0.077155,0.055999,0.097460,-0.155853,-0.938303,0.091123,0.109240,0.004204,-0.331319,0.691652,0.109259,-0.121522,-0.014589,-0.260291,0.257896,0.580666,0.380449,0.121882,-0.149715,0.234243,-0.139515,0.420042,1.157617,0.163752,-0.418522,0.485677,-0.229262,-0.408511,0.317399,-0.095164,-0.568974,0.315493,0.072358,0.027647,-0.468505,-0.073007,-0.789242,0.297681,-0.230855,-0.521973,0.272389,-0.426866,-0.070819,-0.895076,-0.120123,-0.436600,-0.311111,0.081914,0.116350,-0.228209,0.526296,-0.985699,0.200897,0.829334,0.060153,-0.479538,0.705999,0.597107,0.015638,-0.005689,-0.128829,-0.026428,-0.433599,0.396505,0.069055,0.351086,0.191295,-0.185017,-0.573301,0.309457', '11541282', '3147969', '26687241', '26930504');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30395081', '致所有我曾爱过的男孩2', '剧情', '故事紧接着上一部展开。拉拉（陈东兰 Lana Condor 饰）和皮特（诺亚·森迪尼奥 Noah Centineo 饰）总算是互相坦白了感情走到了一起，他们两人都兴致勃勃的准备迎接在一起之后的第一个情人节的到来。对于这对初来乍到的小情侣来说，之后两人所要经历的一切对他们既是享受也是挑战，从来没有过类似经验的拉拉内心里难免充满了忐忑。基蒂（安娜·卡思卡特 Anna Cathcart 饰）、玛格特（贾娜尔·帕里希 Janel Parrish 饰）和新结识的伙伴斯托米（霍兰德·泰勒 Holland Taylor 饰）是拉拉最坚实的后盾，但拉拉有时候又会觉得疑惑，自己是不是过于依赖她们了呢？当约翰（乔丹·费舍 Jordan Fisher 饰）再度出现在拉拉的身边时，给她和皮特的感情带来了许多不确定因素。©豆瓣', '诺亚·琴蒂内奥', '迈克尔·费穆格纳瑞', 6.4, 14042, 'tt9354842', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2582094440.jpg', 1.9, 15, 52.1, 22.7, 8.3, '0.644860,-0.194437,-0.726648,0.558318,0.161322,-0.366370,0.769885,0.126820,-0.642064,-0.172038,-0.009576,0.609163,-0.511657,0.101381,0.308842,-0.022147,-0.568005,-0.731894,-0.094364,-0.201891,-0.408558,-0.685408,-0.383176,-0.126552,-0.240983,-0.290938,0.343637,-0.415329,-0.083007,0.718546,0.529012,0.394029,0.176182,0.646826,0.022815,0.162544,0.181432,0.165558,-0.444262,0.027216,0.273670,-0.067806,-0.018620,0.389626,0.249231,0.370880,0.449527,-0.506008,-0.118820,0.120390,0.079347,-0.169315,0.142144,0.072580,0.068894,0.003351,0.291250,0.044626,-0.116218,0.030301,-0.012707,-0.084492,-0.691472,0.050418,0.223940,0.204830,-0.743858,0.362553,0.000724,-0.193580,0.287494,-0.502282,0.249429,0.621835,0.409401,0.334456,-0.075506,-0.135227,-0.305224,-0.030752,0.809404,0.234442,0.079959,0.485963,-0.437651,-0.288191,-0.160338,0.163700,-0.572188,0.026517,0.124593,0.214484,0.170631,0.256454,-0.715007,-0.010380,0.044161,-0.186573,0.166326,-0.618323,0.229551,-0.528751,-0.190650,-0.927795,-0.564189,0.003554,0.020465,-0.291454,0.607288,-1.034683,0.330319,0.273971,0.450453,-0.196143,0.642293,0.187735,0.103667,-0.190770,0.011746,0.150328,-0.164412,0.027677,0.357376,0.516871,0.190365,-0.289051,-0.245013,0.639949', '1304868', '20277433', '1308755', '24325