INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30396443', '特种部队：蛇眼起源', '动作', '亨利·戈尔丁饰演一名因背负了复杂过去而隐忍的独行者，代号蛇眼。一次偶然，他救下了岚影一族的准接班人，从而被邀请加入他们在日本的组织。在那里，岚影一族不但教会了蛇眼如何成为一名忍者，也给了他一直想要的一个家。但当蛇眼过去的秘密被逐渐揭开，他的信誉以及对组织的忠诚也将受到考验，即便这会使他会失去最亲近的人的信任。特种部队原著中的经典角色也将在《特种部队：蛇眼起源》中一一亮相。', '亨利·戈尔丁', '罗伯特·斯文克', 4.3, 16630, 'tt8404256', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2709891880.jpg', 20.3, 50.2, 25.9, 3.3, 0.4, '0.478124,0.330997,-0.771712,0.852690,-0.276467,-0.185709,0.564000,-0.202016,-0.501582,-0.168693,0.233665,0.980189,0.312619,0.101092,0.175774,-0.053271,0.103362,-0.666689,-0.255730,-0.356971,-0.499610,-0.378495,-0.264746,-0.104475,-0.094379,-0.367934,0.915306,0.129458,-0.324172,0.352562,0.567800,0.604283,0.177492,0.382771,-0.173163,-0.206700,0.127059,-0.149082,-0.098478,0.396944,0.068016,-0.448441,-0.215530,0.626852,-0.212252,0.298256,0.598587,-0.493678,-0.260818,-0.344324,0.367241,-0.471792,0.077126,0.084646,0.583134,0.119803,0.048756,0.560615,-0.026502,0.063604,-0.196358,-0.025026,-1.354238,-0.176651,0.296796,0.047871,-0.943194,0.517405,0.076924,-0.154151,-0.029161,0.054464,0.324728,0.406207,0.344818,0.101431,-0.380053,0.131547,-0.418050,0.108672,0.645047,-0.104686,-0.338943,0.185621,-0.168497,-0.431327,-0.101559,-0.515147,-0.392694,-0.036507,0.629324,0.034747,-0.303949,0.188774,-0.542773,-0.019278,-0.259885,-0.280579,0.085104,-0.560558,0.058392,-0.386673,-0.246862,-0.355049,-0.388547,0.111397,0.037357,-0.251069,1.061438,-0.818905,0.143428,0.738646,0.259835,-0.625329,0.664643,0.074657,0.276277,-0.185668,-0.173613,0.084885,0.489644,0.274631,0.293076,0.343926,-0.087753,-0.143480,-0.306933,0.319444', '30163500', '27602116', '1793491', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30397916', '新秩序', '剧情', '墨西哥导演米歇尔·弗兰克在参加马拉喀什电影节时确认他执导的第六部影片[少数人的梦想](The Dreams of a Few，暂译)将于明年4月开机拍摄。弗兰克的上一部影片[艾普尔的女儿]于去年戛纳电影节“一种关注单元”首映并荣获评审团奖。弗兰克表示新片将是一部大制作影片，影片风格有别于他以往作品，将采用全墨西哥演员阵容，墨西哥取景拍摄。据悉新片故事将设定在一个不远未来的反乌托邦世界，影片主题涉及墨西哥城的贫富鸿沟。', '奈安·诺温德', '米歇尔·弗兰克', 7.3, 13448, 'tt12474056', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2621425700.jpg', 2.1, 6.4, 31.3, 42.2, 17.9, '-0.101932,0.157801,-0.504098,0.842481,0.626837,0.071089,0.423384,0.133171,-0.189284,0.050048,0.084524,1.120998,-0.694468,-0.152051,0.382397,-0.204500,-0.598136,-0.503257,-0.339048,-0.118845,0.100487,-0.318170,-0.353110,-0.171614,-0.030155,-0.210027,1.060830,0.194390,-0.490782,0.237431,0.590850,-0.133975,-0.005191,-0.095407,0.369359,-0.178460,0.124009,-0.138753,-0.577091,0.581157,-0.052229,-0.262630,-0.295494,0.086583,0.112830,0.309783,0.817657,-0.158578,0.023719,0.040160,1.059731,-0.341536,-0.074681,-0.227830,-0.075363,0.246837,0.090413,0.256451,0.015183,0.145813,0.005373,-0.750611,-0.761243,0.069410,0.085290,0.233194,-0.219947,0.506740,-0.441965,0.188415,-0.190375,-0.391129,0.231415,0.107656,0.594247,0.183362,0.222708,0.053225,-0.276660,0.802971,0.298115,-0.155233,-0.287612,0.490595,-0.049765,-0.676255,-0.507068,-0.187184,-0.549682,0.398338,0.397722,-0.422020,-0.141609,0.035892,-0.388350,0.013926,-0.031733,-0.691686,-0.051465,-0.202631,0.326072,-1.412187,0.071453,0.140983,0.118900,-0.690203,0.386851,-0.398018,0.917754,-0.217295,0.218165,0.617081,0.420608,-0.173016,1.016832,-0.019001,0.071306,-0.339777,0.006025,0.375120,-0.078009,-0.156226,-0.149150,0.295386,-0.074401,-0.292371,-0.336752,0.744499', '26275494', '34961898', '1322847', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30400539', '罪人', '剧情', '该电影背景设定在 911 紧急呼叫中心的一个早上。呼叫接线员乔·贝勒（吉伦哈尔饰）试图拯救一名危在旦夕的呼叫者，但他很快发现事实并非如此，而面对真相是摆脱困境的唯一办法。', '杰克·吉伦哈尔', '安东尼·福奎阿', 6.5, 9822, 'tt9421570', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2680985686.jpg', 1.8, 11.1, 52.7, 27.2, 7.1, '0.141895,0.320790,-0.427132,0.488595,0.091638,0.434668,0.482997,0.055271,-0.379613,-1.004647,0.074433,0.486705,0.111899,0.337787,0.330319,-0.204203,-0.170669,-0.341563,0.554922,0.067406,-0.271630,-0.596477,-0.068244,-0.735655,0.175129,-0.026039,0.683809,0.145920,-0.229722,-0.032285,0.558467,0.342697,-0.006996,0.557317,0.249688,-0.306906,0.152239,-0.233611,-0.154602,0.412665,-0.081114,-0.466135,0.013475,0.750141,-0.238613,0.863573,0.034965,-0.390517,-0.104789,0.573038,0.502249,-0.503413,0.046545,-0.004192,0.152232,-0.451598,-0.233114,-0.286695,-0.048907,-0.005224,-0.133446,-0.235823,-0.927308,-0.085968,0.133258,0.357233,-0.269694,-0.357622,-0.456908,0.072740,0.100499,-0.395833,0.197436,0.534515,0.190437,0.325625,-0.364548,-0.006994,-0.690534,0.082448,0.654614,0.057090,-0.168568,0.575081,0.110379,-0.572233,-0.231126,-0.276255,-0.737687,0.166187,0.045771,0.375333,-0.229447,-0.253692,-0.304923,-0.165165,-0.444226,-0.238140,-0.139136,-0.481568,0.208252,-0.298484,-0.176315,-0.001634,-0.096961,0.155516,-0.314590,-0.367227,0.486409,-0.647119,-0.327307,0.292868,-0.269026,-0.701707,0.431918,0.441300,0.111713,-0.400181,0.300341,0.659696,0.448886,0.176606,-0.433096,-0.190847,0.153048,-0.531396,-0.606497,-0.053537', '3670447', '3006783', '1297689', '3808604');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30401194', '你好世界', '爱情', '在京都居住的内向男高中生直实（北村匠海 配音）的面前，突然出现从10年后穿越而来26岁的自己（松坂桃李 配音）。未来的直实告诉他，自己不久便会与琉璃（滨边美波 配音）相爱，可是之后烟花大会时她却会因为一场事故意外离世。为了拯救爱人，16岁的直实卷入了这场现实与虚拟的记忆世界，经历了一系列超乎想象的事情。即使世界毁灭，我也想再见你一面。', '北村匠海', '伊藤智彦', 6.9, 59864, 'tt9418812', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2654818960.jpg', 1.2, 8.4, 46.4, 34.7, 9.3, '-0.125458,0.291997,-0.615737,0.344982,-0.084696,-0.217322,0.663203,-0.154193,-0.414208,-0.360318,0.105360,0.878050,-0.313017,0.272492,0.533262,0.168288,-0.250761,-0.808735,0.143152,-0.391070,-0.346793,-0.259405,-0.215494,-0.125433,0.071304,-0.453601,0.709640,0.171787,-0.370409,0.470027,0.118333,0.008649,-0.180508,0.467962,-0.012425,-0.136809,0.059335,0.861674,-0.434888,0.053260,-0.188510,-0.513144,-0.232876,0.267885,-0.292571,0.151412,0.613968,-0.273006,-0.432643,-0.251728,0.528389,-0.327471,-0.256152,0.011429,0.352524,-0.194339,0.147002,0.218047,-0.149971,-0.158406,-0.123047,-0.294391,-0.557304,-0.047682,0.005847,-0.036065,-0.219703,0.200762,0.115500,-0.043413,0.313147,0.035355,0.129246,0.501912,0.676666,0.348730,-0.606103,-0.154829,-0.157042,0.492695,1.079227,-0.128268,-0.405381,0.619424,0.019363,-0.446658,-0.460318,-0.151770,-0.745629,0.608249,-0.050004,0.099994,-0.448104,0.584075,-0.465589,-0.168021,-0.223088,-0.050361,0.158222,-0.177308,-0.228698,-0.315257,-0.519731,-0.285429,-0.472839,-0.125243,0.000342,-0.312036,0.779139,-0.693787,0.389500,0.586739,0.322239,-0.416726,0.709385,0.279404,0.097535,-0.475497,0.322119,0.160382,-0.230420,0.305172,-0.168697,0.165688,0.050625,-0.084466,-0.603884,0.514621', '30162520', '25721544', '35068654', '27008393');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30401849', '1/2的魔法', '喜剧', '影片设定在一个由精灵、巨魔和灵魂等组成的郊外幻想世界，在那里独角兽在垃圾桶中穿行，像是有着糖果条纹的负鼠。影片提供了一个前提，即魔法是真实的，但它早已被现代技术所遗忘和取代。一对十几岁的兄弟，在他们尚不更事时父亲便已离世，他们决定进入这个幻想世界，与父亲共度最后一个神奇的日子。霍兰德配音弟弟伊安、帕拉特配音聒噪的哥哥、德瑞弗斯配音兄弟二人的母亲、斯宾瑟则会利用其声线的优势。', '汤姆·赫兰德', '丹·斯坎隆', 7.6, 103167, 'tt7146812', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2616349563.jpg', 0.2, 2.6, 32.1, 49.4, 15.7, '0.150704,0.052419,-0.448951,0.894461,-0.202544,-0.248130,0.885907,0.219451,-0.410143,-0.378724,0.173643,0.941346,-0.013210,0.157137,0.251165,-0.032071,-0.378122,-0.558377,-0.040714,-0.167781,-0.242292,-0.495579,-0.419697,-0.245655,-0.087711,-0.516652,0.839140,-0.032327,-0.095217,0.252531,-0.044000,0.156194,-0.369400,0.119856,-0.223919,-0.036577,0.131623,-0.010824,-0.246264,0.089294,-0.245712,0.017205,0.334649,-0.056804,-0.270932,-0.013516,0.892874,-0.512047,-0.036130,-0.130254,0.451438,-0.159377,0.006205,0.009723,0.142833,-0.274574,0.290263,-0.021537,-0.076496,0.153056,-0.080043,-0.217079,-0.943958,-0.232506,-0.007571,0.052881,-0.496404,0.336723,0.176606,0.125288,0.214441,-0.308359,0.127794,0.072501,0.313018,0.638700,-0.242719,-0.079829,-0.474987,0.146402,0.378736,-0.235104,-0.276286,0.564041,-0.372378,-0.448948,-0.254284,0.002120,-0.681140,-0.045504,0.294586,0.206729,-0.231001,0.308847,-0.645883,0.010942,-0.185607,-0.043218,0.154532,-0.520156,-0.161704,-0.457407,-0.194483,-0.345848,-0.173330,0.008370,0.220196,-0.201330,0.845456,-0.918714,0.300172,0.535314,0.083916,-0.355857,0.670279,0.118318,0.354669,-0.377656,0.208560,0.322187,-0.021365,0.021212,-0.066706,0.307513,0.060326,0.152028,-0.729219,0.532298', '25880986', '3769423', '27666513', '5416009');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30402056', '致我的陌生恋人', '喜剧', '穿过千千万万时间线，跨越漫长岁月去寻找曾经的爱人。只是平行时空，重新认识，她还会爱上他吗？一次激烈的争吵，一场意外的时空旅行，拉斐尔（弗朗索瓦·西维尔 饰）从一名成功的畅销书作家，变成平庸的中学语文老师；妻子奥利维娅（约瑟芬·约比 饰）从家庭主妇成为了星光熠熠的著名钢琴家。再相遇，身份颠倒，不再是夫妻，平行时空又一次浪漫邂逅，拉斐尔能否守住最初的爱情？', '弗朗索瓦·西维尔', '雨果·热兰', 6.8, 14454, 'tt8265928', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2871300186.jpg', 0.6, 8, 48.3, 34.7, 8.4, '-0.051047,0.017241,-0.370985,0.527920,-0.036470,-0.529472,0.728480,-0.063067,-0.257301,-0.017714,0.110505,0.659997,-0.362811,-0.012513,0.305515,0.196928,-0.509700,-0.796668,0.345737,-0.271062,-0.266793,-0.522039,-0.246365,0.008939,0.264200,-0.364944,0.716041,0.009619,-0.318958,0.127278,0.242829,-0.117299,-0.324762,0.249689,-0.339242,-0.137933,0.110671,0.377635,-0.604952,0.225150,-0.219797,-0.022435,0.036075,-0.116811,-0.283227,0.191689,0.540474,-0.314141,0.231338,0.088155,0.508244,-0.004595,-0.098540,-0.030925,-0.085054,0.130132,0.153881,-0.011426,-0.031881,0.022223,-0.188553,-0.313739,-0.531700,0.233676,0.025441,0.141833,-0.246167,0.507155,0.111624,-0.382478,0.283157,-0.280596,0.050751,0.381409,0.641931,0.270166,-0.258521,0.018748,-0.087487,0.333690,0.964552,0.314081,-0.385319,0.442640,-0.174406,-0.465251,-0.172840,-0.125959,-0.515149,0.147788,0.223273,-0.099503,0.038489,0.644862,-0.699627,0.009126,-0.564398,0.051625,0.238859,-0.319279,0.100325,-0.368236,-0.035696,-0.248033,-0.242735,0.035419,-0.061870,-0.583766,0.475292,-0.768256,0.439658,0.796537,0.378422,-0.139776,1.073014,0.303459,0.017172,-0.517704,0.305875,0.712365,-0.039809,0.219720,-0.271958,0.276766,0.119961,0.231510,-0.358972,0.555126', '10577869', '1307200', '3012033', '1437204');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30402296', '天气之子', '爱情', '高一那年夏天，帆高（醍醐虎汰朗配音）离开位在离岛的家乡，独自一人来到东京，拮据的生活迫使他不得不找份工作，最后来到一间专门出版奇怪超自然刊物的出版社担任写手。不久，东京开始下起连日大雨，仿佛暗示着帆高不顺遂的未来，在这座繁忙城市里到处取材的帆高邂逅了与弟弟相依为命，不可思议的美少女阳菜（森七菜配音）。「等等就会放晴了喔。」阳菜这样告诉着帆高，不久，头顶的乌云逐渐散去，耀眼的阳光洒落街道……原来，阳菜拥有「改变天气」的奇妙能力……', '醍醐虎汰朗', '新海诚', 7, 358346, 'tt9426210', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2558022335.jpg', 1.2, 8, 41.8, 35.7, 13.3, '0.169863,0.228063,-0.869221,0.465597,0.150666,0.016387,0.393503,0.399917,-0.161560,-0.337018,0.147879,0.668532,-0.160930,0.559180,0.455821,0.039242,-0.489132,-0.577732,-0.131024,-0.367923,-0.401891,-0.392182,-0.176525,-0.077569,-0.139502,-0.246819,0.591807,0.694282,0.054044,0.528815,-0.030206,-0.053108,-0.154594,0.307065,-0.282723,-0.074561,-0.146927,0.385975,-0.075555,0.334059,0.011649,-0.178552,-0.166608,-0.208419,0.409287,0.066800,0.837174,0.064694,-0.502347,0.041094,0.642533,-0.039756,-0.074789,-0.026348,0.701864,0.295235,-0.149818,0.023241,-0.265754,0.104919,-0.338597,-0.417692,-0.235260,0.323913,-0.009327,-0.143201,-0.454595,0.191760,0.271261,-0.420972,0.186477,-0.558606,0.300944,0.253001,-0.037961,0.763413,-0.198510,0.552937,-0.190091,0.433564,0.779281,0.320231,-0.350874,0.176471,-0.242681,0.178334,0.098327,0.018636,-0.309549,-0.127667,0.103720,0.013711,-0.027075,-0.010321,-0.616084,0.207555,-0.060660,-0.278130,-0.081946,0.013670,-0.385472,-0.486579,0.170863,-0.254760,0.091409,0.266208,-0.143568,-0.326201,0.574956,-0.839514,0.377650,0.418586,0.432217,-0.011242,0.492339,-0.264974,0.149716,0.003939,-0.038643,0.314154,-0.336432,0.582917,0.109158,0.165188,-0.070688,-0.017196,-0.472016,0.171093', '1438591', '1292219', '1292371', '33218345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30403683', '菊石', '剧情', '故事发生在19世纪20年代的英国，玛丽（凯特·温丝莱特 Kate Winslet 饰）是一名古生物学家，然而，这个行当显然无法让她过上优渥的生活，所以玛丽至今仍然在贫困线上挣扎，为了给病重的母亲治病，玛丽靠着在沙滩上捡化石卖给游客来维生。某日，一个名叫罗德里克（詹姆斯·麦卡德尔 James McArdle 饰）的男人找到了玛丽，开出了很高的薪酬，希望玛丽能够去照料他病重的妻子夏洛特（西尔莎·罗南 Saoirse Ronan 饰），经受不住金钱的诱惑，玛丽答应了。可是，就在玛丽刚刚见到夏洛特没多久，两人之间差异巨大的思想就碰撞出了火花，但随着时间的推移，她们都在彼此的身上看到了自己未曾经历过的世界。©豆瓣', '凯特·温丝莱特', '弗朗西斯·李', 7.2, 35346, 'tt7983894', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2631726396.jpg', 0.5, 5.1, 42.6, 37.3, 14.5, '0.278053,0.259916,-0.828608,0.349446,-0.206867,-0.546745,0.886524,-0.014564,-0.563393,-0.149193,0.276720,0.573850,-0.262151,0.104725,0.305721,0.290901,-0.342592,-0.579366,0.226098,-0.292939,-0.465155,-0.477849,-0.346702,-0.202728,-0.330264,-0.464527,0.338717,-0.164264,-0.021271,0.398889,0.188912,0.236901,0.245346,0.535086,-0.382544,0.157558,0.051550,0.044144,-0.156835,0.204725,0.151507,-0.291398,-0.117832,0.110418,0.206680,0.248038,0.465423,-0.352309,0.075516,0.027426,0.251716,0.075724,0.211982,0.216882,0.148784,-0.111058,0.286350,0.114759,-0.232430,-0.088962,0.119004,0.013082,-0.604395,0.236115,-0.059586,0.356558,-0.873165,0.413994,-0.227103,-0.289390,0.000929,-0.569208,0.093301,0.385035,0.170256,0.427532,-0.344606,0.052744,-0.555605,0.151231,0.640711,0.065882,-0.345769,0.383566,-0.576453,-0.396486,-0.147365,-0.143151,-0.619647,-0.116258,0.284861,0.166465,-0.486306,0.196318,-0.680069,0.056807,-0.339155,-0.391714,0.144333,-0.138476,-0.236868,-0.567650,-0.240388,-0.521772,-0.442978,-0.077651,0.009875,-0.385031,0.669800,-0.780240,0.416046,0.622318,0.481649,0.093997,0.738728,0.092488,0.080791,0.106169,-0.105124,0.261085,0.026079,0.144949,0.113655,0.412023,0.118372,0.022080,-0.321494,0.688894', '1292211', '1866424', '3055049', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3040438', '格莫拉', '剧情', '本片讲述了意大利黑手党格莫拉的5个故事：13岁男童托托（萨尔瓦多•阿布鲁兹Salvatore Abruzzese 饰）近墨者黑，逐渐堕落；马可（马可•马克尔 Marco Macor 饰）和希罗（希罗•帕冲Ciro Petrone 饰）一心想称霸，结果横尸街头；因为丈夫涉黑，妻子玛利亚（玛利亚•纳棕娜丽 Maria Nazionale 饰）锒铛入狱，她把孩子托付给帮派同伙弗兰克（托尼•瑟维洛 Toni Servillo 饰）；黑帮老会计唐•希洛（吉安法利斯•因巴拉多Gianfelice Imparato 饰），因出卖朋友，命丧黄泉；黑帮纺织厂的裁缝帕里跨斯（萨尔瓦多•坎德鲁普Salvatore Cantalupo 饰）因给华人上课而引火烧身……本片荣获61届戛纳最佳影片评委会大奖。©豆瓣', '萨尔瓦多·阿布鲁齐斯', '马提欧·加洛尼', 7.4, 9633, 'tt0929425', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1089031125.jpg', 0.8, 4.4, 32.2, 47.9, 14.7, '-0.030411,-0.355060,-0.380651,-0.092086,0.154954,-0.361643,0.336073,0.357629,-0.434373,-0.198310,-0.067484,0.683170,-0.227525,-0.073895,0.465539,-0.154174,-0.327780,-0.458806,0.207470,-0.127150,0.152382,-0.368829,-0.185775,-0.177300,-0.267919,-0.263143,0.158436,-0.385329,0.232921,0.364316,0.579757,0.494842,0.005657,-0.447705,0.139759,0.182417,0.448154,-0.205201,-0.303025,0.140446,-0.274310,0.037368,-0.023823,-0.270973,0.161768,0.347434,0.352517,-0.152752,0.461785,-0.410661,0.371603,-0.337310,-0.066384,-0.194125,0.284925,-0.280155,0.007570,0.059264,-0.113659,-0.369746,0.455219,-0.290086,0.014344,0.136266,0.301200,0.238436,-0.381673,0.179741,-0.228222,0.190462,0.018919,-0.095899,-0.089535,0.060508,0.499437,0.143513,0.038450,0.018268,-0.279679,0.437145,0.142664,-0.044023,0.025482,-0.094694,-0.033361,-0.259839,0.029791,-0.158993,-0.451740,0.163459,0.446874,-0.490060,0.313440,0.522775,-0.291910,-0.483805,-0.244413,0.024174,-0.104054,0.159563,-0.030057,-0.426932,-0.063053,0.012888,0.029416,-0.181136,0.197731,0.222858,0.425751,-0.221038,0.285937,0.372611,0.195916,-0.203072,0.283828,0.140740,0.281407,-0.404564,0.012314,0.570919,0.323651,-0.390920,0.119318,0.163545,-0.147907,-0.411057,0.214273,0.183545', '1295187', '1829654', '35161768', '2968813');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30405087', '火口的两人', '爱情', '「当巨大的外在世界崩坏时，人们只能在自己的小世界中寻求生存之道。直子与贤治将自我封闭在两人专属的小世界里，伴随着男女之间自然而然的肉体关系，仿佛被抛入了无法说谎的宇宙之中，当中有着快感，也袒露出人们原本拥有的特质。似乎唯有潜入这个小小宇宙之中，人们才能发挥真正的坚强」─原著作家白石一文十天后即将迎接婚礼的直子，与重回故乡秋田的往日恋人贤治，久别重逢。直子从为了迎接新生活而整理出来的物品当中，翻出了一本相簿，相簿里是她与贤治一丝不挂地交缠着的黑白照片；往昔顺从着欲望本能共度的青春时光就此苏醒。「只要今晚就好，让我们回到过去好吗？」在直子未婚夫归来的五天内，在刻画于肉体的愉悦记忆及纠葛的尽头，两人将看到什么风景？结合了震灾背景，包覆在漠然日常之下的浓密性爱，仿佛即将喷发的火山，迸裂出扭曲却纯洁、毅然而绝美的生命岩浆。', '柄本佑', '荒井晴彦', 7.2, 66665, 'tt10747038', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2556419282.jpg', 1, 5.3, 40, 39.4, 14.3, '0.085635,0.519801,-0.907717,0.637690,-0.195427,-0.184196,0.904481,0.091945,-0.442092,-0.105741,0.086973,0.713500,-0.126911,0.384457,0.160790,0.003981,-0.311954,-0.911488,-0.364236,-0.223294,-0.281319,-0.335542,-0.464753,0.089061,-0.184704,-0.594335,0.818482,0.300573,-0.221683,0.225617,-0.083386,0.092072,-0.547128,0.434104,-0.240496,-0.199362,-0.187017,0.287509,-0.449344,0.110265,0.031296,-0.187193,0.033514,0.086861,-0.199390,0.056157,0.990481,-0.741452,-0.018892,-0.034903,0.288750,0.001645,-0.244483,0.349693,-0.022952,0.125138,0.230729,0.192236,-0.317310,0.143712,0.213341,-0.140985,-0.585594,-0.381552,0.029089,0.227909,-0.281162,0.616245,0.332925,-0.308134,0.376185,-0.284181,0.294443,0.187459,0.151231,0.528656,-0.513119,0.118004,-0.287832,0.154110,0.560149,0.107367,-0.422126,0.530302,-0.366009,-0.263819,-0.288265,-0.115429,-0.413296,-0.248638,0.257903,0.515086,-0.256391,0.443063,-0.815995,0.147560,-0.114630,-0.128016,-0.028124,-0.441254,-0.230128,-0.598847,-0.274776,-0.287192,-0.080290,0.167780,0.176833,-0.349319,0.853239,-0.746691,0.340346,0.444371,0.195085,-0.029451,0.558536,-0.112420,0.156276,-0.162174,0.084859,0.403069,-0.184836,0.600709,0.091054,0.445660,-0.397060,0.443208,-0.723429,0.881739', '11615927', '1467779', '21619567', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30408298', '犬鸣村', '恐怖', '位于福冈县的犬鸣村，是著名灵异地点之一。三吉彩花饰演精神科医生森 田奏，因为可以看到亡灵，令她痛苦不堪。一天，哥哥悠真和女朋友明菜 出于好奇，为了试试胆量，走到了犬鸣村。结果他们差点死掉，明菜因此 发疯，后来更自杀了。为了弄清真相，悠真带着几个朋友回到村里。最终 不仅悠真失踪了，他的朋友们在村子附近也离奇遇害。 这个村庄本应在水 坝建设后消失，隧道出口都封闭了。森田奏意识到父亲似乎知道背后的故 事。还有一个神秘人，仿佛可以解开谜团。而犬鸣村的诅咒才刚刚开始。', '三吉彩花', '清水崇', 5.4, 7937, 'tt10919074', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2577059230.jpg', 7.7, 34, 44.6, 10.4, 3.3, '0.138778,-0.038001,-0.519000,0.031722,0.050412,-0.098357,0.567681,-0.080071,-0.643701,-0.661036,0.038269,0.579655,-0.164308,0.474744,0.180231,-0.126940,-0.202185,-0.351663,-0.083920,-0.421835,-0.576186,-0.515840,-0.027861,-0.244829,0.060810,-0.333029,0.345459,0.345222,-0.157140,0.096062,0.310875,0.361453,-0.253310,0.332353,-0.028917,0.025772,0.158044,-0.085910,-0.240601,0.163568,-0.068311,-0.156125,-0.072909,0.222608,-0.020000,0.335338,0.512913,-0.119306,-0.451930,0.001984,0.150950,-0.400758,-0.150035,0.091223,0.402700,-0.354805,0.228513,0.407307,-0.180752,0.008274,0.103282,0.103265,-0.514802,0.138001,0.115195,0.081891,-0.516627,0.280362,0.241148,-0.242903,0.038284,-0.552408,0.603297,0.305827,0.062568,0.329296,-0.415762,0.066621,-0.447988,0.125545,0.983972,-0.234034,0.097895,0.326729,0.170574,-0.468121,-0.232807,0.009689,-0.008874,0.359590,0.253193,0.211157,-0.406627,0.026994,-0.386993,-0.372785,-0.157829,-0.194281,0.010089,-0.297650,-0.169974,0.065547,0.081096,0.334612,-0.014813,0.271556,-0.301050,-0.190886,0.470125,-0.673619,0.142923,0.730008,0.362170,-0.462124,0.410967,0.089924,0.024271,-0.420643,-0.089033,0.295061,0.232384,0.460732,0.055935,0.060836,-0.087291,-0.335035,-0.534885,0.082316', '25721544', '1292064', '1305084', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30409439', '兹山鱼谱', '剧情', '纯祖一年，丁若铨（薛景求饰）因受辛酉迫害事件影响被发配到遥远的黑山岛。来到岛上后，丁若铨对这里的海洋生物产生了浓厚的兴趣，并决定写一本关于海洋生物的书籍。他向在这里土生土长、熟识各种海洋生物的青年渔夫昌大（卞耀汉饰）寻求帮助，但最初昌大因丁若铨是戴罪之身而拒绝。后丁若铨了解到昌大在自学识字的过程中常遇到困难，于是提议将各自擅长的知识教授对方，昌大最终同意，两人也在相互碰撞中成为了彼此的良师益友。然而，丁若铨在得知昌大学习的目的是为仕途后大失所望，昌大也明白两人各有志向，亦师亦友的二人决定分道扬镳……', '薛景求', '李濬益', 8.8, 38939, 'tt14371900', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2634952893.jpg', 0.3, 0.8, 8.4, 40.5, 49.9, '0.528697,-0.026893,-0.810966,0.649153,0.224936,-0.142933,0.369736,-0.063553,-0.691234,-0.304435,-0.040026,0.801540,0.015951,0.220656,0.310587,-0.275025,-0.137743,-0.485649,-0.037134,-0.353343,-0.304199,-0.768610,-0.077899,-0.129542,-0.325850,-0.457495,0.501581,0.443211,-0.391218,0.751693,0.182149,0.298919,-0.120724,0.331018,0.085933,-0.043840,-0.276758,0.066226,-0.484907,0.207798,0.101043,-0.055676,-0.316245,0.044668,0.137202,0.255060,0.815780,-0.162355,-0.385766,-0.019734,0.333545,-0.282439,0.005697,0.315383,0.503372,0.321108,0.100815,0.414382,-0.084947,0.107627,-0.089447,0.036728,-0.451439,-0.180577,0.216118,0.061115,-0.571064,0.525465,0.273601,-0.501316,-0.166615,-0.512708,0.194928,0.538501,0.237522,0.321229,-0.105619,-0.007668,-0.250780,0.101495,0.701417,-0.055504,-0.174613,0.243406,-0.230390,-0.575668,-0.234910,-0.202859,-0.089956,-0.180102,0.237760,0.451769,-0.397884,0.150389,-0.501331,0.001813,-0.163360,-0.100819,0.176609,-0.402608,0.060114,-0.614082,-0.195472,-0.340091,-0.242470,0.025778,0.186579,-0.429276,0.825896,-0.885931,0.339788,0.463222,0.345654,-0.642583,0.804354,0.116109,0.154006,-0.222545,-0.006231,0.005430,0.274890,0.246605,-0.139343,0.137902,0.160014,-0.229871,-0.485171,-0.055162', '1292219', '3445516', '1897368', '10876425');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30410114', '给我翅膀', '冒险', '科斯迪安（让-保罗•卢弗Jean-Paul Rouve 饰）是一名鸟类研究学者，对于鸟类学的热爱让他将毕生的精力都投入到了这个领域之中。失去了父母的白额雁无法学习迁徙的技巧，于是科斯迪安决定驾驶轻航指引幼鸟们从挪威迁徙到目的地法国。然而，在向巴黎博物馆申请经费时，科斯迪安却遭到了拒绝。托马斯（路尔斯•瓦兹奎兹 Louis Vazquez 饰）来到了父亲的农舍度假，刚开始，这个男孩并不理解为什么科斯迪安总是如此的关心鸟类，但随着时间的推移，托马斯也渐渐被神奇的鸟儿所吸引。一天，科斯迪安震惊的发现，托马斯私自驾驶轻航踏上了引导鸟类迁徙的旅途。©豆瓣', '让-保罗·卢弗', '尼古拉·瓦尼埃', 8.8, 41471, 'tt10204940', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561160802.jpg', 0.2, 0.6, 7.8, 40.4, 51, '0.599627,0.169041,-0.711191,0.404755,0.044648,-0.518798,0.505120,0.045790,-0.547752,-0.138758,0.088443,0.627480,0.072307,0.023780,0.404859,0.342874,-0.577014,-0.427895,0.096413,-0.156913,-0.329069,-0.626496,-0.123814,-0.234311,-0.041111,-0.535987,0.397828,0.142594,-0.105543,0.668968,-0.106778,0.370084,0.085940,0.425938,0.006104,0.074435,0.591185,-0.096889,0.135912,0.230006,0.027207,-0.003929,-0.416003,0.115420,-0.018675,0.183625,0.665699,-0.274658,-0.098416,-0.130306,0.203993,-0.198363,0.217785,0.259043,0.158292,0.013964,-0.226119,0.099278,-0.258406,0.324538,-0.079082,0.063492,-0.549510,0.176310,-0.187074,0.190318,-0.772538,0.043193,-0.117293,-0.428902,0.056275,-0.645807,-0.009269,0.500379,0.043136,0.331819,-0.157519,-0.100479,-0.335102,-0.188591,0.737884,-0.201845,-0.448814,0.279301,-0.252633,-0.520934,-0.045145,-0.041985,-0.275436,-0.305244,0.324305,0.491244,-0.275515,0.311220,-0.758667,0.137759,-0.430176,-0.571344,-0.186236,-0.343983,-0.197031,-0.807042,0.082584,-0.355859,-0.062252,-0.114934,0.190366,-0.198868,0.797216,-0.766372,0.466679,0.655118,0.114034,-0.088164,0.541728,-0.453421,-0.059890,-0.305613,-0.038732,0.407117,0.234681,0.467569,-0.109056,0.430080,0.341826,-0.254917,-0.249145,0.735766', '3178770', '5977789', '2159244', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3041201', '恋物', '惊悚', '在过去的韩国很多孩子被用来神婆祭祀，身子在坛子里被关着直到死去，而灵魂也被琐到铃铛里。当今的韩国也有很多神婆用铃铛来招魂，传说最有名的神婆都是哑巴，而淑熙（宋慧乔 Hye-kyo Song 饰）则生在这样一个世代都为神婆的名门家族。为了摆脱这种命运，她从神圣女子大学休学，通过相亲与从小生活在美国的皮特结婚，追随丈夫和婆婆远嫁到美国生活。初到异乡的淑熙努力适应着周围全新的环境，和家人一起信仰基督吃西餐。原以为这样就可以割舍神婆的命运，然而神婆的命运却依然紧紧的缠绕着她，母亲送给自己结婚礼物里竟然缝合着招魂的铃铛，丈夫和婆婆的相继离奇死亡再次点燃了已然成为孤身一人的她内心的欲望，她渐渐的迷恋上了了邻居约翰（亚诺•弗里斯奇 Arno Frisch 饰）和朱莉（阿瑟娜•库瑞 Athena Currey 饰）夫妇的生活，开始在生活的各个方面模仿女主人朱莉的举手投足，勾引她的丈夫约翰，诡异的气氛渐渐弥漫开来…', '宋慧乔', '孙秀范', 4.7, 5684, 'tt1145152', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p714449477.jpg', 19.2, 38.2, 34.6, 6.4, 1.6, '0.272627,-0.027282,-0.626908,0.572383,-0.384580,-0.307129,0.763586,0.283656,-0.406256,-0.412337,0.150797,0.880686,-0.093774,0.423775,0.177852,0.162395,-0.110512,-0.692091,-0.022546,0.077884,-0.167230,-0.166873,-0.059366,-0.194344,-0.095452,-0.301488,0.601209,-0.067578,0.107368,0.288302,-0.003094,0.246882,-0.083282,0.186824,-0.556495,0.181011,-0.123011,-0.070124,-0.295244,0.145247,0.138325,-0.160512,0.005612,0.289525,-0.118356,0.106698,0.699391,-0.496255,0.047756,-0.088292,0.389529,-0.255046,-0.173663,0.280214,0.259630,0.049968,0.303130,0.178976,-0.231338,0.082630,0.081567,0.014818,-0.590378,0.255538,0.111119,0.094832,-0.684305,0.533871,0.124867,-0.062224,0.025132,-0.471613,0.527642,0.259278,-0.129388,0.617105,-0.508845,0.087331,-0.605750,0.191776,0.657682,-0.034067,-0.060146,0.322196,-0.422586,-0.252230,0.056172,-0.284643,-0.753695,-0.236448,0.185341,0.003289,-0.196962,0.389497,-0.703834,0.040862,-0.091942,-0.077659,0.184276,-0.461195,-0.074796,-0.475884,-0.264017,-0.361283,-0.210476,-0.016170,0.120045,-0.296363,0.700274,-0.823463,0.344691,0.568553,0.257550,-0.401408,0.521704,-0.008824,0.225923,-0.143753,-0.298338,0.504078,0.055976,0.368916,0.147812,0.432907,0.002341,0.295384,-0.284642,0.731790', '30162520', '1460341', '26884422', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3041261', '第四类接触', '科幻', '美国阿拉斯加德诺曼小镇，在过去的几十年里当地不断发生离奇事件。许多人神秘失踪，还有很多人被严重的失眠所困扰，自杀案件居高不下。单身母亲阿比盖尔•泰勒（米拉·乔沃维奇 Milla Jovovich 饰）当年曾经历一场诡异的灾难，在那场灾难中，睡在身边的丈夫神秘死亡。在此之后，阿比盖尔开始研究催眠。当得知诺曼镇发生的事情时，她直觉这与自己的经历有很大关系。经过对几名当事人的催眠，阿比盖尔得知他们都有着遭遇莫名生物的经历，在此期间，她更目睹了当事人杀害全家并自杀的悲惨场面。随着调查的深入，真相渐渐浮出水面，然而最为恐怖的事情也随之发生……本片据传由真实事件改编。©豆瓣', '米拉·乔沃维奇', '奥拉顿德·奥逊山米', 6.7, 15142, 'tt1220198', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1742608675.jpg', 2.7, 10.9, 44, 31.9, 10.5, '0.184445,-0.246789,-0.904174,0.186361,0.282982,0.293282,1.028746,-0.378083,-0.864218,-0.765663,0.231549,0.651124,-0.440556,0.114499,0.463035,-0.338300,-0.326439,-0.628670,0.311099,-0.133815,-0.329484,-0.568239,-0.469689,-0.348448,-0.000071,-0.419084,0.322823,0.293103,-0.339187,0.371840,0.214594,0.706929,-0.339896,0.446304,0.123343,0.216757,0.226149,0.225963,-0.395390,-0.171814,0.117054,-0.370139,-0.089356,0.165980,0.040088,0.237615,0.412805,-0.383686,-0.571247,-0.127388,0.417319,-0.426858,-0.058289,0.117141,0.635562,0.281399,0.161755,0.617745,-0.225900,-0.320796,-0.084153,0.125902,-0.634221,0.185581,0.255909,0.496956,-0.240415,0.047437,0.013116,0.146524,0.209028,-0.009083,0.229487,0.660391,0.433501,0.254353,-0.057372,-0.089299,-0.321965,0.025007,1.064643,-0.205935,-0.277113,0.285090,-0.149532,-0.220021,-0.138456,-0.299196,-0.185534,0.719122,0.079508,0.180319,-0.418649,1.018977,-0.311562,-0.080171,-0.275925,-0.433713,-0.203140,0.054771,-0.258217,-0.755824,-0.541544,-0.390740,-0.463634,-0.145129,-0.189370,-0.395207,0.326204,-0.570266,0.423510,0.465972,0.153103,-0.450521,0.089369,0.095813,0.255396,-0.220666,-0.100032,0.695956,0.059113,0.094944,-0.215454,0.028190,0.217981,-0.108581,-0.211600,0.473752', '25909236', '6082346', '3231742', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3041264', '洛杉矶之战', '动作', '2011年夏天，无数枚陨石坠落地球，竟导致12个国家的沿海城市系数毁灭。原来陨石实则有一群神秘的外星人操纵。外星人凭借陨石着陆地球，展开残酷无情的屠杀和破坏。作为世界上的头号超级大国，美国自然也无法避免这场灾难，随着入侵者的则多，美国只有西太平洋的洛杉矶暂未沦陷。海军陆战队中士麦克·纳兹（艾伦·艾克哈特 Aaron Eckhart 饰）受命编入威廉姆·马丁内斯中尉（拉蒙·罗德里格兹 Ramon Rodriguez 饰）的小分队，准备与外星人展开殊死搏杀。适值此时，外星入侵者成功登陆，并杀入人口稠密的圣莫尼卡区。军方决定诱敌深入，再对敌人施以空中打击。为了营救无辜，纳兹和马丁内斯的小分队义无反顾冲了进去……©豆瓣', '艾伦·艾克哈特', '乔纳森·里贝斯曼', 6.1, 103807, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2261837887.jpg', 4.1, 17.6, 52.3, 20.9, 5.1, '0.305254,0.134624,-0.669321,0.425912,0.140667,0.124323,0.543237,-0.121591,-0.106036,0.072515,0.172148,0.511771,0.138958,-0.184135,0.298245,-0.059303,-0.453750,-0.528151,-0.361002,-0.174971,-0.442579,-0.419657,-0.629504,-0.300929,0.094758,-0.320453,0.599108,0.136070,-0.277167,0.303727,0.141581,0.566009,-0.151028,0.495064,0.219662,-0.184909,-0.025025,-0.111904,-0.485724,0.364982,-0.291353,0.064174,0.042288,0.124498,-0.152312,0.214722,0.722228,-0.602580,0.373648,-0.627519,0.083968,-0.442826,0.097139,0.059065,0.485598,-0.040109,-0.171471,-0.130394,0.218109,0.054368,0.229623,-0.096313,-0.532550,-0.022838,0.016785,-0.083378,-0.149442,0.095769,-0.030667,0.312037,-0.055167,-0.168472,0.035542,0.656828,0.515552,0.106143,-0.250683,0.103891,-0.279053,-0.031906,0.499771,0.075475,-0.481951,-0.452646,-0.096706,-0.362284,-0.014722,-0.314074,-0.166470,-0.149781,0.418666,-0.086763,0.133797,0.542978,-0.852614,0.151869,-0.535558,-0.494818,-0.164126,-0.196978,0.025916,-0.871270,0.216048,-0.017128,-0.094116,0.421179,0.033459,0.192710,0.649449,-0.356064,0.175935,0.790015,0.498374,-0.170265,0.251140,0.033300,-0.025960,-0.430557,0.044713,0.448287,0.218009,0.337580,0.031269,0.163438,0.029267,-0.201747,0.040163,0.443240', '3006772', '3871833', '4014397', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3041269', '永无止境', '科幻', '影片改编自阿兰·格里恩出版于2001年的小说《黑暗领域》，主演布莱德利·库珀曾获得2011年全球最性感男人称号。潦倒颓废的艾迪·莫莱（布莱德利·库珀 Bradley Cooper 饰）是一个丢掉了工作，缺乏灵感的作家。许久不联系的前小舅子给他一种正处在试验阶段的药物--NZT。服用一次之后艾迪发现自己精力充沛，思维清晰，行动敏捷，甚至能在瞬间把一些平时不易留意的细节和信息重新组合和整理并得出推论。等他再一次去找小舅子却发现他已被人谋杀，屋里一片狼藉，紧跟着是一群杀手的追杀。死里逃生的艾迪终于发现了这款名为NZT的新药物能使人发挥大脑100%的能力。借助NZT，艾迪重获灵感并进入上流社会，但大获成功之余也有致命的作用：身体不适和失控的情绪。而此时埃迪已不能离开这种药，这使他进入了一个黑暗领域，而杀手也在暗处监视他……©豆瓣', '布莱德利·库珀', '尼尔·博格', 7.5, 130737, 'tt1219289', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p868781788.jpg', 0.4, 2.9, 35, 46.7, 14.9, '0.131723,0.046048,-0.594039,0.591685,-0.176750,-0.372143,0.613365,0.040172,-0.820664,-0.535312,-0.046664,0.529277,-0.218621,0.018419,0.174230,-0.134286,-0.235874,-0.545237,0.231404,-0.078238,-0.455958,-0.317329,-0.506941,-0.324399,-0.055128,-0.786159,0.655199,0.125153,-0.477366,0.240636,-0.019810,0.205447,0.200558,0.575420,-0.070674,-0.104056,0.025966,-0.261349,-0.159106,0.474313,0.199716,-0.344378,-0.287536,0.203310,-0.025404,0.307764,0.619759,-0.166287,-0.283581,-0.013869,0.433032,-0.053305,-0.044542,-0.097456,0.103278,-0.074086,0.268667,-0.003888,-0.260624,0.228761,-0.154876,0.038267,-0.952482,-0.006736,-0.107714,0.146279,-0.439828,0.137671,-0.189661,0.031989,-0.102574,-0.380274,0.082412,0.216919,0.317650,0.329510,-0.334797,-0.004652,-0.414951,-0.035169,0.345323,-0.072652,-0.412106,0.726905,-0.180121,-0.586321,-0.307735,-0.140589,-0.219082,-0.026346,0.302865,0.539707,-0.332381,0.074396,-0.540952,0.117329,-0.333608,-0.355729,-0.082762,-0.335098,-0.046372,-0.554478,-0.365178,-0.027194,-0.232107,-0.064027,0.131130,-0.262953,0.648713,-0.723480,0.269563,0.628055,0.053932,-0.399628,0.587185,-0.011585,0.002933,-0.106040,-0.067039,0.205866,0.216182,0.339326,0.012504,0.424969,-0.115589,-0.138435,-0.428401,0.482061', '1793491', '25932086', '6844861', '3262091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3041281', '猫头鹰王国：守卫者传奇', '动作', '在茂密宁静的仓鸮森林，猫头鹰诺克图斯和妻儿们生活在一棵参天大树的枝干上。她的儿子索伦（吉姆·斯特吉斯 Jim Sturgess 配音）无比迷恋“守护者”的传说。据说很久以前，佩戴着钢喙的邪恶“纯种者”（草鸮）国王压迫猫头鹰子民，关键时刻守护者挺身而出，打败了国王及其爪牙，但失败者从未放弃复仇的念头。憧憬古老传说的索伦令哥哥库鲁德（瑞恩·科万腾 Ryan Kwanten 配音）颇为气恼，以致于被哥哥从树上推下。两只还没学会自由飞翔的小家伙跌落到危机四伏的地面，他们躲避各种猛兽的袭击，却无法避免成为邪恶猎手捕获的目标。兄弟俩连同其他种类的猫头鹰被抓到神秘的圣鸮学校，他们在这里接受严格的训练，学到不同的技能，而猫头鹰王国沉寂已久的战火即将再次点燃……本片根据凯瑟琳·拉斯基的经典儿童文学作品改编。©豆瓣', '艾米丽·巴克雷', '扎克·施奈德', 7.4, 36800, 'tt1219342', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p566825144.jpg', 0.5, 3.4, 36, 45.5, 14.6, '0.198768,0.039392,-0.683398,0.672744,-0.027808,0.087244,0.534774,0.062010,-0.169077,-0.093046,0.582962,0.481835,0.106777,-0.046248,0.162022,0.007264,-0.111024,-0.309252,-0.001321,0.119689,-0.277636,-0.152188,-0.547673,-0.328053,-0.212691,-0.496583,0.899632,-0.047607,-0.234670,0.383301,-0.123058,0.284785,-0.213812,0.033509,-0.365761,-0.175115,0.101428,-0.119524,-0.103342,0.098105,-0.344025,0.027185,-0.338934,0.021332,-0.137529,0.099288,0.591223,-0.675194,0.144592,-0.238715,0.227413,-0.395394,0.100174,0.116408,0.429367,-0.255968,0.087962,0.015849,0.179875,-0.088383,0.045150,-0.113731,-0.734236,-0.005082,-0.051737,0.344571,-0.521615,0.426441,-0.091992,0.286295,0.251544,-0.431157,0.120097,-0.012122,0.069688,0.418965,-0.124606,0.062178,-0.381072,0.036966,0.514648,-0.258616,-0.519136,-0.105779,-0.325406,-0.472811,-0.147844,-0.322780,-0.459319,-0.315555,0.548808,0.105143,-0.334300,0.481493,-0.866198,-0.005626,-0.176052,-0.306234,0.108149,-0.351601,-0.354593,-0.468932,0.018515,-0.113485,-0.116538,-0.027585,0.258341,-0.287265,0.742822,-0.827731,0.541474,0.518278,0.097609,0.066243,0.410938,-0.268472,-0.007542,-0.140988,-0.291612,0.402553,0.402454,0.300860,0.118363,0.225270,0.077285,-0.092037,-0.457291,0.609904', '26759819', '26290398', '3213270', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3041294', '生化危机4：战神再生', '动作', '爱丽丝（米拉·乔沃维奇 Milla Jovovich 饰）重回在东京，向安布雷拉公司复仇。后者潜藏在地球的底部，威斯克（肖恩·罗伯茨 Shawn Roberts 饰）执行着自以为是的安 全技术标准。爱丽丝闯入了禁区，直捣黄龙。而威斯克竟然不惜毁灭城市做困兽斗。最终，当他驾驶着直升机逃离时，却被爱丽丝胁迫，情急之下，他向爱丽丝身上注入了具有对T细胞的免疫病毒，令她丧失了超能力，只能驾机飞翔荒无人烟的阿拉斯加。地球上已经177天没有生命迹象。然而，爱丽丝却意外发现了克莱尔（艾丽·拉特 Ali Larter 饰）。她们循着阿卡迪亚信号，回到了地狱之城，满眼的僵尸令人触目惊心。迎接她们的是同样听到信号的幸存者。在神秘犯人克里斯（文特沃斯·米勒 Wentworth Miller 饰）的帮助下，她们向阿卡迪亚之船进发……©豆瓣', '米拉·乔沃维奇', '保罗·安德森', 6.8, 195943, 'tt1220634', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p564897015.jpg', 1.8, 10.2, 46.8, 28.8, 12.4, '0.195501,0.194019,-0.838273,0.582100,0.048767,-0.197360,0.904883,0.134073,-0.239886,0.023773,0.265150,0.588181,-0.220850,-0.171893,0.228997,0.319711,-0.493004,-0.525024,-0.156615,-0.237870,-0.471142,-0.484419,-0.361132,-0.390266,0.177640,-0.425731,0.463363,0.143172,-0.190105,0.233528,0.164334,0.409446,-0.186915,0.556652,0.027571,0.027992,0.050210,-0.418650,0.002757,0.312049,0.069939,-0.034648,-0.202945,0.454450,-0.003725,0.309226,0.652614,-0.549448,0.240049,-0.338445,0.164951,-0.249903,0.298506,0.101587,-0.030506,-0.244942,-0.206194,-0.070405,0.071770,-0.037420,0.504687,0.153052,-0.642480,0.009019,-0.264803,0.220450,-0.378352,0.084302,-0.310291,0.206498,0.171677,-0.483714,0.155117,0.152612,0.104329,0.320389,-0.226596,-0.019397,-0.589910,-0.152294,0.427184,0.002664,-0.503903,0.086406,-0.272697,-0.422396,-0.253424,0.070373,-0.502606,-0.279434,0.629157,0.340689,-0.017590,0.302153,-0.535752,-0.136531,-0.495375,-0.401858,-0.190377,-0.196238,-0.109477,-0.781281,0.051601,-0.048066,-0.277341,0.108077,-0.206563,-0.104353,0.372611,-0.733900,0.297072,0.880821,0.311110,-0.177194,0.390996,-0.344826,-0.084800,-0.145513,-0.002063,0.593683,0.164270,0.736760,0.269102,0.250358,-0.051448,0.070727,-0.285038,0.571549', '3735015', '1316693', '1301