INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30413052', '攀登者', '剧情', '1960年，中国登山队向珠峰发起冲刺，完成了世界首次北坡登顶这一不可能的任务。15 年后，方五洲和曲松林在气象学家徐缨的帮助下，带领李国梁、杨光等年轻队员再次挑战世界之巅。迎接他们的将是更加 严酷的现实，也是生与死的挑战......', '吴京', '李仁港', 6, 305539, 'tt9635616', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2568577681.jpg', 5.8, 20.5, 48, 19.8, 5.8, '-0.057110,0.034039,-0.772497,0.809102,-0.136456,-0.119000,0.133507,-0.120572,-0.353599,0.266414,0.298828,0.636361,-0.144064,0.354154,0.675394,-0.400152,-0.055107,-0.745796,-0.505950,-0.157453,-0.955709,-0.422862,-0.138432,-0.314691,-0.009163,-0.408185,0.768321,0.350376,-0.395874,0.531777,0.359008,0.131740,0.191622,0.816476,-0.196650,-0.267436,0.431815,0.319127,-0.486224,0.566568,-0.025787,-0.500247,-0.402327,0.323806,-0.106305,0.206222,0.539068,-0.453454,-0.109874,-0.180366,0.097149,-0.589680,0.041449,-0.080851,0.606757,-0.316260,-0.285272,0.576484,0.098659,0.112219,-0.459970,-0.542950,-0.699247,0.045639,0.213191,-0.129205,-0.731604,0.207267,-0.161261,0.179710,-0.031464,-0.409523,-0.006919,0.629328,0.674844,0.479424,-0.300606,-0.212152,-0.272570,0.143197,0.779984,0.265010,-0.395213,0.042276,-0.071252,-0.864189,-0.227048,-0.061103,-0.350564,-0.038129,0.290116,0.281017,0.045092,0.014307,-0.503220,0.304085,-0.234282,-0.625412,0.063038,-0.464489,-0.229144,-0.526029,0.038540,-0.229763,-0.086533,0.199357,-0.026942,-0.381034,0.828860,-0.734603,0.326331,0.469809,0.460062,-0.296543,0.996555,-0.031938,0.075033,-0.361675,0.492799,0.072811,-0.275528,0.716081,0.097067,0.488415,-0.274324,-0.019874,-0.222191,0.547469', '1308499', '1381964', '1897368', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30414462', '黑镜：潘达斯奈基', '剧情', '菲恩·怀特海德、威尔·保尔特等主演的《黑镜》特别影片[黑镜：潘达斯奈基]首发剧照！影片将聚焦一位年轻的程序员，他将一部奇幻小说改编为游戏。然而很快现实和虚拟世界混合在一起，开始造成混乱。影片充满大量的暴力元素。该片将于12月28日登陆Netflix。', '菲恩·怀特海德', '大卫·斯雷德', 6.9, 72794, 'tt9495224', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2543862640.jpg', 2.6, 9.8, 42.9, 31.7, 12.9, '0.214426,0.159018,-0.215119,0.746985,0.430702,-0.092270,0.712897,0.107032,-0.213724,-0.095293,0.162772,1.005255,-0.856539,-0.401587,0.237658,-0.285066,-0.646439,-0.491660,-0.428489,0.239718,-0.062670,-0.470619,-0.270357,-0.172057,-0.056066,-0.744841,0.979241,0.021256,-0.220074,0.176855,0.330007,0.364484,-0.275526,0.090686,0.628979,0.110306,0.029262,-0.381868,-0.430918,0.634599,-0.096916,-0.205659,-0.246664,0.001143,0.057084,-0.279253,1.100351,-0.195703,0.054486,0.061591,1.041384,-0.116357,-0.212025,-0.281110,-0.197614,0.432948,0.349543,-0.212612,-0.059040,0.264092,-0.247074,-0.454109,-0.549544,0.090912,-0.128849,0.034318,-0.021083,0.188352,-0.357370,0.072036,0.330904,-0.256165,-0.047632,0.108483,0.679548,0.271968,-0.003402,0.075862,-0.153926,0.603695,-0.047789,0.030209,-0.423223,0.406510,0.022135,-0.660619,-0.654973,-0.027333,-0.596260,0.135678,0.794513,-0.054403,0.024388,0.532494,-0.834629,0.192816,0.193414,-0.793891,-0.040972,-0.158277,-0.077018,-1.126444,-0.347512,0.117860,0.073056,-0.296396,0.335217,-0.159111,0.981764,-0.578968,0.438365,0.483655,-0.099287,-0.299221,0.591662,0.107295,-0.052213,0.016652,-0.177130,0.394115,0.436795,0.315789,0.405386,0.562476,-0.392684,0.149213,-0.549479,0.801335', '30397916', '1322847', '22265121', '6537486');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3041614', '蜡笔小新：呼风唤雨！光荣的烤肉之路', '动画', '大件事！小新一家變成全國通輯犯！在少年警訊的「野原家成魔之路特輯」中透露，小新一家正與邪惡勢力「獎鬥人」進行「秘密東西」交易。據小新的好朋友正男(別號：「無間正男」) 所說，自從美冴媽媽縮減早餐改買「特級烤肉」晚餐的那一刻開始，他們一家就變了，爸爸變成「臭狐戰士」，媽媽化成「電波少女」，小新聯同妹妹小葵、小狗小白組成「搗蛋兵團」。另據警方線人指出小新一家正合力避開警民耳目，潛入獎門人的總部。但在另一方面，小新一家的鄰居卻相信他們是無辜的。究竟誰是誰非？小新一家真的與邪惡勢力交易？還是另有冤情？', '矢岛晶子', '水岛努', 8.6, 14966, 'tt1149379', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2509870833.jpg', 0.3, 1.1, 13.5, 39.3, 45.8, '0.194789,-0.263995,0.187168,0.056725,-0.086517,-0.212533,0.208691,0.338462,-0.355432,-0.248931,0.425364,0.482788,0.295614,0.211972,0.266303,0.352735,0.093522,-0.313594,0.054079,-0.206771,-0.176745,-0.455122,0.062033,-0.073574,0.062604,0.017410,0.370408,-0.101448,0.136790,0.125580,0.307195,-0.016555,-0.779860,0.338826,-0.296390,-0.107416,0.166324,0.165859,-0.435878,-0.043260,0.026519,-0.039884,-0.202585,0.131771,-0.023593,0.289271,0.433754,-0.097032,-0.315160,-0.220887,-0.106379,0.109711,0.026114,0.030129,0.320591,-0.142462,0.714802,-0.252623,-0.210567,-0.220006,0.091047,0.056333,-0.238561,-0.222577,-0.024146,0.057841,-0.025276,0.392460,0.125474,0.212826,0.607234,-0.206723,0.044652,0.058400,0.221103,0.511545,0.207025,0.190753,-0.655473,-0.274478,0.606523,0.179137,0.564980,0.424736,-0.171008,-0.216261,-0.028484,0.217327,-0.304256,0.046490,0.306287,-0.024067,-0.253983,0.346170,-0.589737,-0.069160,-0.099298,0.462539,0.355174,-0.166873,-0.070583,-0.411271,0.122991,0.295014,0.233828,0.425881,0.288775,-0.297113,0.504014,-1.080181,0.362610,0.378559,0.167528,-0.541708,0.765732,0.063339,0.181362,-0.528406,-0.390020,-0.365806,0.069611,-0.166226,0.164156,0.205425,0.176651,-0.385057,-0.191289,0.247163', '2052978', '2124718', '3033092', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30416337', '唐伯虎点秋香2019', '喜剧', '黄伯虎（陈浩民 饰）、刘浩南（何浩文 饰）和排骨（林子聪 饰）是青梅竹马的玩伴，彼此之间感情十分要好。他们共同喜欢一部名为《唐伯虎点秋香》的经典电影，时时拿出来重温。长大之后，三人走向了不同的道路，黄伯虎成为了警探，刘浩南是泊车小弟，而排骨则成为了发明家。一次偶然中，排骨用自己发明的时光机做实验，竟然在误打误撞之中将自己和两个兄弟欢送到了《唐伯虎点秋香》中的世界里，在那里，他们遇见了祝枝山（陈百祥 饰）。祝枝山告诉三人，这个世界里的唐伯虎早已经跑路了，于是黄伯虎决定代替唐伯虎去华府应聘。©豆瓣', '陈浩民', '张敏', 2.8, 3992, 'tt12228850', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2546364248.jpg', 73.6, 16.6, 7.3, 1.6, 1, '0.288834,-0.046477,-0.574823,0.574705,-0.057377,-0.328610,0.645970,0.031726,-0.533118,0.067199,0.067132,0.790457,-0.110664,0.542641,0.308577,-0.080900,-0.422699,-0.655671,0.053833,-0.536534,-0.460937,-0.245297,-0.353159,-0.017584,-0.290487,-0.096390,0.539098,0.061161,-0.040084,0.553667,0.380171,0.025897,-0.384464,0.318063,-0.275663,0.411230,0.219850,0.090578,-0.443448,0.283044,0.067907,-0.171307,-0.149162,0.155298,-0.009589,0.046733,0.717035,-0.435704,-0.094498,-0.072394,0.032244,-0.107666,-0.230980,0.000283,0.168531,0.171914,0.475375,0.140495,-0.212455,0.381850,-0.137603,-0.108217,-0.624712,-0.155629,0.148945,0.090585,-0.774151,0.321335,0.132526,-0.383513,0.124012,-0.365390,0.358618,-0.069699,0.618766,0.427981,-0.151745,-0.199744,-0.441899,0.255551,0.579769,-0.102760,0.159841,0.537106,0.050926,-0.192036,-0.016321,0.031455,-0.116652,0.073521,0.277404,-0.014123,-0.137275,-0.086174,-0.822025,-0.006885,-0.014644,0.042097,0.081776,-0.412708,-0.129461,-0.455034,-0.036289,-0.572477,-0.164172,0.160690,-0.024021,-0.325894,0.712311,-0.621190,0.089355,0.192702,0.143654,-0.381311,0.827340,-0.149501,0.100750,-0.337142,0.274367,-0.248177,-0.099458,0.207485,0.259278,0.517917,-0.105260,-0.178695,-0.663958,0.525732', '3055049', '26958479', '30162520', '1414808');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3041749', '天伦之旅', '剧情', '年迈的弗兰克（罗伯特·德尼罗 Rovert De Niro 饰）曾是给电线涂保护层的工人，他的工作保护了电线不受外界的侵蚀。对于自己的四个孩子，弗兰克同样是百般呵护，可是在妻子去世的8个月时间里，他发觉自己和孩子们的距离越来越远。弗兰克不顾医生的告戒，独自踏上了拜访四个孩子的旅程。然而，在弗兰克的心目中应该成为画家的小儿子不知所踪，大女儿Amy（凯特·贝金赛尔 Kate Beckinsale 饰）的婚姻生活似乎并没有表面上那样幸福，本以为会是乐队指挥的儿子Robert（山姆·洛克威尔 Sam Rockwell 饰）其实只是个鼓手，而从小就喜欢跳舞的女儿Rosie（德鲁·巴里摩尔 Drew Barrymore 饰）似乎同样对父亲有所隐瞒。就这样，老弗兰克带着满腹的猜疑踏上归途。途中由于心脏病弗兰克住进医院，孩子们终于齐聚弗兰克的医床前，可是小儿子却依旧没有出现……本片翻拍自意大利导演朱塞佩·多纳托雷1990年的同名电影，主演罗伯特·德尼罗由于在本片中的出色表演，荣获第13届好莱坞电影节年度男主角奖。', '罗伯特·德尼罗', '柯克·琼斯', 8.6, 91172, 'tt0780511', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1217133544.jpg', 0.1, 0.5, 10.9, 45.3, 43.2, '0.076117,-0.291733,-0.802634,0.472873,-0.140588,-0.573040,0.794583,0.068642,-0.595429,-0.383534,0.299431,0.760297,-0.132746,0.329763,0.267881,-0.006831,-0.395459,-0.539036,-0.179944,-0.070969,-0.094257,-0.480666,-0.313880,-0.039457,-0.189816,-0.459200,0.595604,-0.076687,0.032915,0.333946,0.397631,0.181563,0.138944,0.246756,-0.111929,0.215491,0.206776,-0.027299,-0.110289,0.212530,0.189026,-0.047365,-0.166879,-0.028599,0.147405,0.491788,0.516567,-0.199824,0.059102,-0.121595,0.387887,-0.290578,0.037714,0.043082,0.256944,-0.002362,0.393844,0.103331,-0.133789,-0.014942,-0.075984,-0.228503,-0.497296,0.261404,0.176215,0.261657,-0.748238,0.378255,-0.157320,-0.179903,0.008121,-0.294613,0.236223,0.197966,0.086402,0.351682,-0.291355,0.134163,-0.414118,0.088398,0.555738,0.149795,-0.204319,0.286194,-0.286617,-0.290103,-0.032436,-0.251808,-0.735861,0.036739,0.151999,-0.013199,-0.049284,0.284415,-0.158462,0.002541,-0.272727,-0.233912,0.056120,-0.290183,0.055767,-0.648714,0.108615,-0.535292,-0.236350,-0.182256,0.049228,-0.224239,0.639139,-0.736528,0.586396,0.283335,0.172315,-0.398060,0.777316,0.322804,0.153960,-0.160723,-0.212088,0.390087,-0.070745,-0.132090,0.026841,0.296471,-0.002355,-0.447734,-0.307354,0.451261', '1302384', '3230121', '3111650', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3041753', '荷尔蒙', '喜剧', '暑假开始了，伴随着夏日热度一同翻滚的，还有悸动的青春心灵……清迈的普（查理·哲华 Charlie Trairat 饰）和迈（司拉恰奇·齐恩萨温 Sirachuch Chienthaworn 饰）是一对竞争多年的邻居，同时又是校内颇受女孩欢迎的组合，他们一齐喜欢上了回乡度假的少女娜娜，相约展开竞争；曼谷少女娥乐（霍嘉丝·芝华顾 Focus Jirakul 饰）痴迷台湾明星迪迪，为了不错过迪迪在电影中和舞台上的每个表演，娥乐决定学习中文；羞涩笨拙的宅男佐（Ratchu Surachalas 饰）为了追求美女茜，从电影中学习浪漫桥段，并且精心准备剧本，但收获的却是拒绝；恒（Chantawit Thanasewee 饰）送女友离开后，终于回到了一班兄弟的怀抱，并且再次燃起了对AV女神的憧憬……©豆瓣', '查理·瑞纳', '颂裕·素玛戈南', 7.5, 37308, 'tt1208717', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1074591790.jpg', 0.5, 3.1, 33.4, 45.4, 17.5, '0.260500,0.013955,-0.597928,0.610419,0.231877,-0.352127,0.516825,0.272070,-0.283471,0.039711,0.172244,0.566348,-0.535528,0.461023,0.247656,0.095323,-0.501558,-0.893798,-0.120585,-0.179272,-0.132592,-0.028198,0.166883,0.082578,-0.201778,-0.296000,0.466586,-0.054986,-0.095947,0.833971,0.493660,0.059668,-0.202935,0.246644,-0.072130,-0.027292,0.085254,0.129152,-0.497677,0.209883,0.162596,-0.131530,-0.145445,-0.038133,0.265470,0.196020,0.984061,-0.184033,0.076226,0.018420,0.339592,0.088660,-0.151229,0.232571,-0.041749,0.296032,0.293371,-0.091837,-0.072187,0.005595,-0.000690,-0.472108,-0.497071,0.377394,0.243238,-0.031979,-0.579574,0.596069,0.121015,0.045630,0.286917,-0.232473,0.049514,0.089562,0.137163,0.537710,0.101150,0.238800,-0.053065,0.424059,0.535730,0.095822,0.039847,0.647442,-0.417761,-0.308769,0.031929,0.142601,-0.483340,-0.095457,0.274654,-0.125497,0.235254,0.046049,-0.881278,0.162694,-0.198219,-0.034017,0.225954,-0.394491,-0.123833,-0.788151,-0.094453,-0.388894,-0.044299,0.069197,0.098404,-0.265665,0.950135,-1.049006,0.034910,0.465151,0.262880,-0.445723,0.694596,-0.134410,-0.233955,-0.275404,-0.024833,0.119181,-0.317820,-0.068840,0.129554,0.520635,-0.304760,-0.066703,-0.479283,0.418126', '3811356', '4127270', '25922902', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3041773', '蜡笔小新：呼风唤雨！金矛之勇者', '剧情', '某日，小新（矢岛晶子 配音）在街上遇见了一只黑色的小狗，因为它和小白犹如一个模子里刻出来一般相像，小新将它取名“小黑”，带回了家。之后，一位名叫普莉林的美丽女子出现在小新的面前，普莉林告诉小新，他是被选中的勇者，黑暗世界库莱顿的大门已经打开，若小新再不行动，整个世界就将要被卷入阴谋和毁灭之中。果不其然，美伢（楢桥美纪 配音）和广志（藤原启治 配音）接连遭遇不幸，这说明，黑暗的力量变得越来越强大，少年麻达的到来给小新带来了新的希望，他的职责，就是保护勇者小新的安全。在麻达的鼓励和帮助之下，小新拿起了武器走上了战场，他所要面对的不仅仅是层出不穷的敌人，还有强大而且邪恶的幕后黑手。©豆瓣', '矢岛晶子', '本乡满', 7.4, 7933, 'tt1220673', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2190162697.jpg', 1.2, 6.3, 38, 31.2, 23.3, '0.179946,0.187174,-0.648200,0.552646,-0.276725,-0.019494,0.702179,0.144913,-0.254034,-0.166950,0.334188,0.758544,-0.074518,0.232502,0.167316,0.097098,-0.080469,-0.710630,-0.401048,-0.150573,-0.375940,-0.245448,-0.394075,-0.012218,0.004159,-0.427681,0.540526,0.023937,-0.446864,0.338567,0.340048,0.300429,-0.218557,0.170361,-0.352333,-0.020471,-0.013663,0.005124,-0.024720,0.310880,-0.147895,-0.119525,0.052465,0.375807,-0.069733,0.273835,0.659265,-0.539255,-0.223714,-0.258726,0.393737,-0.238959,-0.041761,0.162178,0.349639,0.198051,0.169724,-0.077454,-0.245268,-0.009169,0.190694,-0.291673,-0.980892,0.021058,0.102925,0.234792,-0.522868,0.175009,0.135625,-0.268504,0.454668,-0.360294,0.286908,0.148161,0.361931,0.436716,-0.194523,0.275082,-0.327625,-0.187996,0.616501,-0.212039,-0.199701,0.273670,0.017918,-0.262460,0.022025,-0.176762,-0.337833,0.146778,0.467793,0.179973,-0.219565,0.137168,-0.797566,0.044116,-0.240838,-0.124074,-0.078625,-0.418377,-0.332083,-0.398001,-0.215369,-0.236007,-0.110681,0.338975,0.106240,-0.275838,0.950374,-0.780484,0.389483,0.604428,0.460439,-0.131688,0.457397,-0.042191,0.083870,-0.109068,0.148882,-0.147820,0.256300,0.402809,0.217498,0.476231,-0.116320,-0.228124,-0.577236,0.543460', '25928048', '27602116', '24284209', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3041806', '叶问', '剧情', '1930年代，中国武术之都佛山。这日，武功了得的北方武师金山找（樊少皇 饰）率众来佛山踢馆，各大武馆馆主皆成他手下败将之后，他找上习得一身武艺却为人低调未设馆授徒的叶问（甄子丹 饰）。在巡警李钊（林家栋 饰）、好友武痴林（行宇 饰）等乡邻的请求及妻子张永成（熊黛林 饰 ）的鼓励下，叶问用咏春拳以柔克刚将金山找制服，确立在佛山的大师傅地位，李钊更私下将他视作师父。之前叶问挚友周清泉（任达华 饰）有心拉他合开纺织厂，但怕与爱妻及爱子分开的他只在资金上将周支持。几年之后，侵华日军将佛山攻占，叶问同幸存下的乡邻一样，被迫携妻儿移居废屋。生计面前，叶问混在人群争抢去煤矿做苦力的机会，李钊则成为日军翻译官。日军将领三蒲（池内博之 饰）是名武痴，他以一袋白米作奖赏，派李钊四处搜寻能打国人在打斗场上与日军切磋，多名昔日武馆馆主及武痴林因此惨死。这将叶问激怒，他走入打斗场。', '甄子丹', '叶伟信', 7.8, 357696, 'tt1220719', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p458263441.jpg', 0.3, 1.8, 27, 51.6, 19.2, '-0.060712,-0.011448,-0.390577,0.423464,-0.096720,-0.325630,0.134746,0.287817,-0.431192,-0.218165,0.315670,0.520578,0.116692,0.173182,0.013504,-0.373504,-0.080185,-0.663312,-0.129440,-0.189783,-0.089516,-0.302995,-0.071683,-0.026175,-0.382964,-0.069739,0.267900,0.032627,-0.239565,0.309885,0.352164,0.100631,0.081114,0.448778,-0.240500,0.080163,-0.056916,-0.059513,-0.371602,0.169874,-0.215961,-0.481939,-0.276630,-0.144436,0.164673,0.390739,0.617978,0.202847,0.145948,-0.213905,-0.006474,-0.102628,0.214804,0.225045,0.348149,0.099444,0.243659,0.069440,-0.032550,-0.050501,0.120104,0.002962,-0.274094,0.209644,0.469154,-0.102229,-0.595115,0.381151,-0.097232,-0.039903,-0.157583,-0.284861,0.113273,0.358601,0.077816,0.099835,-0.016788,-0.032190,-0.436712,0.614774,0.463578,-0.105166,0.323203,-0.083459,0.229827,-0.256416,0.198330,-0.264171,-0.053240,-0.333296,0.381561,-0.361136,0.175519,0.070875,-0.394434,-0.046654,-0.071477,-0.018827,-0.083952,-0.179496,0.122321,-0.676833,0.140618,-0.330369,-0.125447,0.088706,0.368771,-0.080281,0.709325,-0.420003,-0.051972,0.157918,0.299084,-0.306351,0.642222,-0.100749,0.177309,0.031157,-0.034028,0.039930,0.372504,0.490071,0.273404,0.357997,-0.154351,-0.072959,-0.262177,0.080722', '3811356', '1308609',