INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30419744', '春江水暖', '剧情', '六百年前元朝画家黄公望先生以富春江两岸风貌画下《富春山居图》，为迎接2022年亚运会，富阳正在热火朝天地进行新城建设。在此背景下，《春江水暖》讲述杭州富春江畔，四兄弟分四季轮流照顾中风后失智的母亲，四个家庭面临亲情与生活的考验，借由一年四季的冷暖变化如画卷般徐徐展开。', '杜红军', '顾晓刚', 7.3, 26210, 'tt10219146', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2572231147.jpg', 1, 4.5, 34.7, 47.1, 12.6, '-0.161198,-0.187332,-0.261799,0.598846,0.737968,-0.321406,0.293510,0.403462,-0.377163,-0.107017,0.142125,0.241943,-0.126884,0.490859,0.350633,-0.264413,-0.591596,-0.782471,-0.471837,0.071410,-0.092331,-0.176264,0.031097,0.466377,-0.168686,0.094081,0.273141,-0.000142,0.200340,0.510322,-0.438324,-0.011953,-0.508771,-0.139745,-0.126248,-0.150701,-0.228834,0.187527,-0.959825,0.266248,-0.242793,-0.171086,-0.169368,-0.232962,-0.088717,0.077828,0.880935,-0.351332,-0.024001,-0.405896,0.326660,0.365901,0.086993,0.087082,0.370375,0.296429,0.047548,0.351512,-0.388855,-0.124148,-0.274183,-0.600127,-0.351143,-0.272494,0.455901,0.191132,-0.512777,0.171360,0.182209,-0.114149,-0.052325,-0.275899,0.068783,0.570923,0.360901,0.842453,-0.230960,0.143628,-0.230827,0.204006,0.481889,0.194694,-0.148988,0.227754,-0.344589,0.104865,0.216139,-0.162755,-0.166418,-0.056438,-0.264468,-0.004191,0.419873,0.208500,-0.751554,0.164135,-0.135928,-0.147956,0.195496,0.132199,-0.478070,-0.866389,0.047580,-0.295086,-0.185097,-0.043145,0.301385,-0.223843,0.544371,-0.360890,0.347990,0.283228,0.098178,-0.235748,0.355530,0.269521,0.291413,-0.165593,-0.117207,0.119610,-0.319020,0.510237,-0.310730,0.118251,-0.569063,0.287784,-0.342379,0.184296', '1304694', '26946508', '5403927', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30423193', '使徒行者2：谍影行动', '剧情', '童年兄弟意外失散，30年后因一桩罪案相见，两人已身处不同阵营。随着对罪案调查的深入，一个多年来隐于幕后的恐怖组织渐渐浮出水面。', '张家辉', '文伟鸿', 6.2, 184155, 'tt10295602', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2563751491.jpg', 2.1, 16.8, 54.8, 21.3, 5.1, '0.261154,-0.295573,-0.601846,0.427290,0.624735,-0.304075,1.064317,-0.259221,-1.128168,-0.486384,0.111221,0.583677,-0.298751,-0.184473,-0.048007,-0.531320,-0.162074,-0.852941,-0.026124,-0.511807,0.081434,-0.500676,-0.532108,-0.072870,-0.134243,0.078016,0.602935,0.592504,0.143510,0.973911,0.099249,0.289984,-1.163485,0.261053,0.298657,-0.347311,0.439280,0.558415,-0.779657,0.120658,-0.319690,-0.434499,-0.024358,-0.475962,-0.226570,0.498000,1.230623,-0.078167,-0.327780,-0.227774,0.470661,0.071455,-0.079054,-0.188549,1.054223,0.511124,-0.122684,0.717393,-0.477307,-0.375156,-0.503405,-0.269478,-0.533713,-0.027211,0.257516,0.302209,-0.251518,0.177707,0.294482,-0.304546,-0.023876,-0.190789,0.135894,0.741459,0.457632,0.436175,0.086609,0.430329,0.203693,0.100914,1.025707,-0.056007,-0.155189,0.351680,-0.003679,-0.278685,-0.082566,-0.033930,-0.027604,-0.173952,0.139868,0.030294,-0.130339,0.957463,-0.212835,0.120792,-0.395317,-0.060368,0.187791,-0.142650,-0.052542,-0.191889,-0.865398,0.151795,-0.227106,0.709800,-0.268999,0.008222,0.128259,-0.803714,0.436231,0.645695,-0.223330,-0.746150,0.555112,0.164673,0.228473,-0.602318,0.256083,0.555820,0.091194,-0.158695,0.122091,-0.156426,-0.361131,-0.009654,-0.237570,-0.713517', '1773217', '3391271', '2365260', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30425219', '从邪恶中拯救我', '动作', '泰国发生震惊人心的绑架事件，完成最后杀人任务的杀手仁南（黄政民饰演），在得知这事件与自己有关之后，随即前往泰国，并与助手开始追查这起事件。另一方面，得知自己兄弟被仁南杀害的雷（李政宰饰演），为了复仇，也前往了泰国。惨烈的暗杀者与无情的追击者，展开了一场没有底线的猛烈追击。', '黄政民', '洪元灿', 7.3, 65340, 'tt12763920', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2612814747.jpg', 0.5, 4.2, 39.7, 40.7, 14.9, '0.283112,-0.130358,-0.867425,0.703253,0.268664,0.256620,0.715819,-0.255483,-0.344235,-0.480567,0.367958,0.710983,-0.072233,-0.295165,0.772642,-0.309970,-0.357493,-0.763055,-0.202385,-0.086215,-0.343360,-0.457058,-0.204447,-0.386460,0.248695,-0.330258,0.840235,0.416762,-0.591888,0.873190,0.605106,0.773698,-0.529670,0.415942,0.262727,0.191449,0.121240,0.142403,-0.573985,0.265546,0.198126,-0.554007,-0.048791,0.301007,-0.043307,0.759088,0.618580,-0.378992,-0.309457,-0.304944,0.371989,-0.907675,-0.013999,0.065146,0.515864,0.121156,0.308808,0.738303,0.029797,-0.277383,-0.050757,-0.099262,-1.193945,-0.060189,0.501887,-0.029940,-0.243727,0.215369,-0.353023,0.414018,0.116541,0.029976,0.227115,0.767672,0.447824,0.114003,-0.223334,-0.169329,-0.181152,0.224856,1.331125,-0.230317,0.098965,0.009111,0.537899,-0.448014,0.092425,-0.512655,0.213463,0.492594,0.621779,0.274748,-0.384084,0.591875,-0.305000,-0.386248,-0.373611,-0.149376,0.182138,-0.214449,-0.023152,-0.919173,-0.155564,-0.230396,-0.100698,0.032173,-0.008129,-0.405646,0.236101,-1.035876,0.069886,0.738104,0.260299,-0.938624,0.225154,0.210789,0.362524,-0.382857,0.031347,-0.027714,0.463605,0.571857,0.030961,0.038998,0.029075,-0.128474,-0.164537,-0.183376', '5157137', '1294941', '25828589', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30425275', '火药奶昔', '动作', '萨姆（凯伦·吉兰饰）的母亲斯卡利特（琳娜·海蒂饰）是一名精英刺客，当萨姆被迫与母亲分开时，她只有 12 岁。萨姆由 The Firm 抚养长大，这是她母亲为之工作的无情犯罪集团。现在，15 年过去了，萨姆跟随母亲的脚步，成长为一名作风凌厉的女杀手。她用自己的“才能”来收拾 The Firm 最危险的烂摊子，既能干又忠诚。但是，当高风险工作出问题时，萨姆必须选择继续效忠 The Firm，还是保护无辜的 8 岁女孩埃米莉（克洛伊·科尔曼饰）的生命。萨姆成为了被追杀的对象，现在她只有一次生存的机会：与她的母亲和其他女杀手“图书管理员”（杨紫琼、安吉拉·贝塞特和卡拉·古奇诺饰）团聚。这三代女性现在必须学会彼此信任，勇敢地对抗 The Firm 及爪牙大军，奋起反抗那些可以夺走她们一切的人。', '凯伦·吉兰', '纳沃特·帕普莎多', 5.8, 6971, 'tt8368408', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2669216586.jpg', 6, 26.4, 47.1, 14.3, 6.1, '0.103962,-0.110075,-0.602993,0.468704,-0.452729,-0.568919,0.646018,0.039773,-0.421403,-0.407158,0.160748,0.686577,0.352191,0.162867,0.273453,0.036083,-0.307678,-0.760710,-0.017600,-0.233699,-0.346717,-0.400061,-0.111097,-0.376230,-0.169013,-0.367692,0.616413,-0.214958,0.173297,0.375788,0.166035,0.413393,0.249532,0.332061,-0.088560,-0.195687,0.106618,-0.437800,-0.378071,0.288343,0.001936,0.140551,-0.292026,0.216665,0.003539,0.418105,0.602544,-0.309750,0.248335,-0.494092,0.170668,-0.307301,0.062023,0.176062,0.162342,-0.368805,0.196733,0.260209,-0.024873,-0.144343,-0.044935,-0.219745,-1.041786,-0.246121,-0.009616,-0.016641,-0.781186,0.090662,-0.170698,0.059901,0.255125,-0.409503,-0.087819,0.415428,0.109717,0.328305,-0.325186,0.049045,-0.408850,-0.001044,0.741733,0.045037,-0.182100,0.132727,-0.314359,-0.524594,0.060739,-0.631958,-0.622574,0.032361,0.267931,0.141543,0.055120,0.333704,-0.467128,-0.397426,-0.477663,-0.052017,0.064820,-0.648307,0.018733,-0.324100,0.048432,-0.454567,-0.423091,0.029245,0.038150,-0.273022,0.904712,-0.782860,0.058150,0.631779,0.483820,-0.589171,0.611225,0.211523,0.396550,-0.288105,-0.092270,0.442638,0.179085,0.253982,0.161634,0.070695,0.362687,0.069970,-0.306355,0.410673', '1877596', '30163500', '26678784', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30426519', '从宫本到你', '剧情', '宫本(池松壮亮 饰)是个职场菜鸟，在恋爱和工作上都十分笨拙，一直烦恼著自己在社会上生存的意义。直到某日，和靖子(苍井优 饰)一见锺情后，他的人生终于露出一线曙光，稳定的日子过没多久，却突然发生了一件大事，彻底的改变了他们，让靖子和宫本的关係降到了冰点，宫本要如何做才能巩固这份得来不易的爱情呢？', '池松壮亮', '真利子哲也', 7.2, 17744, 'tt9575164', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2564266421.jpg', 1.7, 7, 35.1, 40.9, 15.2, '0.271200,0.251900,-0.525767,0.479438,-0.090441,-0.645218,0.774452,0.172032,-0.442847,-0.227278,0.152860,0.391946,-0.205093,0.353656,0.471778,-0.041007,-0.605281,-0.930616,0.247970,-0.168164,-0.362810,-0.150837,-0.452622,-0.013131,-0.368845,-0.104031,0.693209,0.243573,-0.180524,0.152714,0.313724,0.199211,0.437489,0.589571,0.143041,0.022948,-0.203543,0.463986,-0.148541,-0.020393,0.063123,-0.466912,-0.253598,0.120283,0.159842,0.430702,0.455015,-0.312345,-0.471046,0.008070,0.236729,-0.267828,-0.170976,0.246042,0.174367,-0.224809,-0.180478,0.316289,-0.333922,-0.061399,-0.009150,-0.084380,-0.766673,-0.421101,-0.006381,0.183357,-0.363661,0.662537,0.003624,-0.115435,0.277979,-0.446792,-0.069381,0.790404,0.455684,0.310548,-0.548037,-0.130803,-0.398175,0.600795,0.702391,0.044202,-0.403886,0.594638,-0.153675,-0.790533,-0.523538,-0.322614,-0.293776,-0.320506,0.320473,0.217669,-0.210802,0.268828,-0.449786,0.007218,0.136848,-0.286257,0.003227,-0.504681,0.194578,-0.184928,-0.208611,-0.808828,-0.609530,0.291065,0.076645,-0.418888,0.564634,-0.859790,0.328875,0.551808,-0.155860,-0.268064,0.273514,0.183551,0.054265,-0.232783,0.063255,0.100985,-0.388925,0.700946,-0.035904,0.399059,0.010499,0.049108,-0.276661,0.662642', '1291577', '30345227', '34973399', '26263428');
