INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30428914', '非凡夏日', '家庭', '作为家庭中年纪最小的成员，萨姆因为害怕家人离开后的孤独，而在度假小岛上开始了自己秘密的“孤独训练”。而岛上古灵精怪的女孩苔丝则绞尽脑汁想要和素未谋面的生父见面。萨姆没想到这暑假的怦然心动不仅会打乱他培养自己适应孤独的训练安排，还会将他带入另一场冒险旅程中。在这个悠长的夏日假期里，两人相依为伴，收获了最美好的记忆，萨姆也意识到人生并非一座孤岛，相伴本身就是意义。', '桑尼·库普斯·范·乌特伦', '史蒂文·沃特卢德', 7.9, 7298, 'tt6851430', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2576226152.jpg', 0.3, 1.3, 21.4, 55.2, 21.9, '0.110349,0.033049,-0.928371,0.592771,-0.314240,-0.158075,0.894233,-0.016794,-0.753681,-0.324756,0.189890,0.747400,0.265097,0.630665,0.626829,0.087345,-0.337988,-0.568927,-0.167618,-0.311864,-0.399789,-0.593247,-0.352259,-0.319044,0.106054,-0.414264,0.833740,0.155519,-0.165815,0.496186,0.069187,0.064420,-0.196340,0.460819,-0.252373,-0.011266,0.138405,0.322184,-0.293304,0.172988,-0.149122,-0.036468,-0.024151,0.202227,-0.005293,0.279927,0.947557,-0.174072,-0.233439,-0.335288,0.338470,-0.099285,-0.303037,-0.062942,0.261338,-0.021207,0.298289,0.261347,-0.242744,0.089660,-0.070287,-0.254466,-0.796481,0.270453,0.239246,0.114195,-0.588166,0.539382,0.329592,-0.312524,0.080162,-0.198367,0.247296,0.486918,0.508660,0.421674,-0.288814,0.017672,-0.076947,0.244064,1.029383,-0.432616,-0.218703,0.615676,-0.464494,-0.227974,0.153365,-0.258478,-0.388252,-0.161154,0.048029,0.258815,-0.257550,0.291306,-0.683700,0.484762,-0.178483,-0.098066,-0.125675,-0.495851,-0.144597,-0.406027,-0.117377,-0.345033,-0.472491,0.135620,0.016680,-0.415030,0.750613,-0.802359,0.321598,0.673118,0.279556,-0.358832,0.659326,0.377690,0.311827,-0.469088,0.250079,0.775751,-0.355887,0.188429,-0.298802,0.071454,-0.228430,0.055134,-0.741622,0.691136', '1291835', '25721544', '35287908', '2365260');
