INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30443686', '穷途鼠的奶酪梦', '剧情', '大伴恭一（大仓忠义 饰），从学生时代起就只与“喜爱自己的女性”交往，不断重复着被动的恋爱，也因为优柔寡断的性格而不断地出轨。大学后辈今之濑涉（成田凌 饰）作为出轨调查员在接受主人公妻子的委托后，某日与前辈大伴恭一时隔7年再次相遇，突然向其告白「从很早以前就一直喜欢你了」，并用为其隐瞒出轨事实作为代价要求前辈以身体来交换。在被今之濑死缠烂打地靠近和追求下，最终恭一也体会到了如胸口揪心般的恋爱之痛…', '大仓忠义', '行定勋', 7.6, 26724, 'tt9770716', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2586418907.jpg', 0.8, 3.9, 30.2, 44.7, 20.4, '-0.050631,0.156469,-0.697797,0.639252,0.065418,-0.447464,0.703704,0.091867,-0.297793,-0.100691,0.159958,0.809963,-0.313755,0.373019,0.545336,0.124336,0.030070,-1.069020,-0.320152,-0.144582,-0.427498,-0.693613,0.076432,-0.094430,-0.249543,-0.450639,0.440184,-0.132498,-0.454674,0.511601,0.647912,0.322528,0.054035,0.636026,-0.240757,-0.234402,-0.265364,0.475331,-0.481214,-0.034492,0.372260,-0.418110,-0.041369,0.047513,-0.100856,0.307807,0.689233,-0.483665,-0.289309,-0.234036,0.328897,0.037921,-0.036384,0.085330,0.302106,0.174008,0.231845,0.465247,-0.122018,0.195440,-0.039605,-0.090578,-0.619507,-0.134956,-0.178965,0.091235,-0.610171,0.258213,-0.101100,0.140037,0.061487,-0.365004,-0.154777,0.318515,0.200797,0.418717,-0.729857,0.175617,0.149947,0.188581,0.636214,0.362574,-0.307489,0.311305,-0.237749,-0.346492,-0.031786,-0.142073,-0.417258,-0.179717,0.060646,0.165673,-0.267572,0.359934,-0.374948,-0.274053,-0.055645,-0.031288,0.366487,-0.446288,-0.020994,-0.090708,-0.119078,-0.272694,-0.481179,-0.021589,0.212866,-0.485435,0.690419,-1.041762,0.131060,0.661927,0.541495,-0.607565,0.589357,0.271728,-0.136751,-0.199633,-0.008847,0.371401,0.135957,0.360625,0.161437,0.373922,0.087632,0.103528,-0.387999,0.286700', '30345227', '1301022', '26809007', '2027925');
