INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3044673', '蜡笔小新：呼唤传说！跳吧！朋友！', '剧情', '双叶幼儿园的游园会快到了，往年都会在游园会里跳春日部舞，但今年松阪老师却突然提议要跳森巴，不过马上受到吉永老师和上尾老师的大力反对，最终也只好不了了之。奇怪的是，第二天在幼儿园里，吉永老师却不同前一晚的态度，大力向园长建议游园会上应该跳热情的森巴……', '矢岛晶子', '武藤裕治', 8.1, 10087, 'tt1033485', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2609958547.jpg', 0.2, 2.3, 22.2, 41.7, 33.6, '0.580962,-0.040343,-0.648961,0.160615,0.137591,-0.201760,0.256291,0.258552,-0.386763,-0.019413,0.357580,0.588994,-0.557994,0.664365,0.274141,0.193823,-0.436091,-0.471675,0.099670,0.005990,-0.298330,-0.399835,0.267379,0.014543,-0.099516,0.106205,-0.054155,-0.245843,-0.235692,0.996654,0.216091,0.010932,0.175603,0.532562,0.002080,-0.082055,0.180903,0.130999,0.171072,0.254519,0.335905,-0.243298,-0.458511,0.093781,0.559214,0.570734,0.259971,-0.031032,-0.265323,0.167151,0.191136,-0.201106,0.124022,0.573171,0.805527,0.328569,0.336176,0.141037,-0.017041,0.038376,-0.234665,-0.472803,0.082843,0.348946,0.099848,0.158407,-0.414709,0.583039,0.106072,-0.084060,0.206173,-0.651907,0.006180,-0.020359,-0.094296,0.400273,-0.341495,0.092981,0.121943,-0.085980,0.812875,-0.104965,-0.104034,0.271476,-0.150336,-0.201106,0.159282,-0.004434,-0.321025,0.177334,0.004180,0.244839,-0.179305,0.027750,-0.424559,0.125504,-0.014177,-0.123214,-0.129020,-0.095965,0.169341,-0.317355,0.208669,-0.072581,-0.268111,0.135455,0.270177,-0.058559,0.710780,-0.940396,0.127084,0.248361,0.365810,0.109389,0.443543,0.087998,-0.206788,0.191862,0.189101,-0.526247,0.003772,0.526103,-0.157621,0.615577,0.359310,-0.818986,-0.219135,0.340193', '1294131', '1292219', '3091208', '25723081');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3044835', '蜡笔小新：云黑斋的野心', '喜剧', '铃可是一名时空巡逻员，某日，在巡逻之中，她发现战国时代即将发生打乱，于是决定穿越到那个时代，解除危机，没想到在穿越的过程中，铃可竟然遭到了莫名的敌人的攻击，兵荒马乱之中，铃可来到了二十世纪，刚刚好跌落到了男孩野原新之助（矢岛晶子 配音）家的庭院之中。铃可附身在了小新所饲养的宠物狗小白的身上，借小白之口向美伢（楢桥美纪 配音）和广志（藤原启治 配音）说明了事件的前因后果，于是，一家三口跟随着铃可，穿越回了十六世纪的战国时代，在哪里等待着他们的，除了新奇刺激的体验，还有无穷无尽的危险和穷凶极恶的敌人。©豆瓣', '矢岛晶子', '本乡满', 8.1, 7569, 'tt2098658', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2510911677.jpg', 0.2, 1.8, 23.8, 43, 31.2, '0.440065,0.133292,-0.871021,0.297584,0.035978,-0.136832,0.571880,-0.023413,-0.342880,-0.333441,0.210216,0.582561,-0.178586,0.414624,0.396168,0.227676,-0.031589,-0.805817,0.032955,-0.101716,-0.565285,-0.165220,-0.242592,-0.074897,-0.071743,-0.396244,0.448901,0.317868,-0.395848,0.270447,0.140337,0.284769,-0.506573,0.562453,-0.210778,0.157191,0.228025,0.122852,-0.102868,0.348058,-0.116128,-0.391841,-0.187303,0.164549,0.101162,0.178124,0.760977,-0.719710,-0.309303,0.070435,0.355279,-0.097703,-0.333784,0.205018,0.382517,0.156575,0.104868,0.029428,-0.283382,0.127239,0.026145,-0.047381,-0.430658,0.067200,-0.116750,0.138666,-0.444150,0.056245,0.263480,-0.174709,0.217888,-0.480066,0.410661,0.381196,0.335634,0.474080,-0.634147,0.061661,-0.375211,-0.073359,0.685035,-0.113275,-0.216761,0.295457,0.350339,-0.322013,-0.254350,0.041849,-0.290695,-0.020939,0.314276,0.225119,-0.458389,0.183604,-0.729734,0.012330,-0.153161,-0.097001,-0.190789,-0.450510,-0.580368,-0.683277,-0.119498,-0.300620,-0.295372,0.313132,0.130010,-0.274843,0.728050,-1.064784,0.165644,0.735344,0.275427,0.021680,0.274813,-0.105507,-0.017457,-0.004692,-0.099695,0.044644,0.039473,0.622658,0.305935,0.394335,-0.328922,-0.339464,-0.553002,0.369671', '1438591', '3044878', '21360412', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3044878', '蜡笔小新：奇异乐园大冒险', '喜剧', '双叶幼稚园的小朋友们来到了高快乐园，在此进行愉快的远足活动。期间，小新（矢岛晶子 配音）在误打误撞之中来到了高快马戏团内，看到了木偶娃娃多佩玛（渊崎有里子 配音）。多佩玛告诉小新，自己被邪恶的乔奇莉诺（室井深雪 配音）施下了诅咒只能在晚上现身，而这个马戏团其实是邪恶的马卡欧（大冢芳忠 配音）和裘马（田中秀幸 配音）两人的老巢，而小新拥有能够将他们打败的扑克牌。害怕的小新并没有答应帮助多佩玛，第二天，幼稚园新来了一位名叫雪人（古川登志夫 配音）的老师，而雪人来这里的唯一目的，就是夺回小新的扑克牌。很快，笑眯眯胖乎乎的雪人就取得了广志和美伢的信任，并下药将他们迷倒。在这千钧一发之际，小新念出了多佩玛教给他的召唤咒语，打败了雪人。©豆瓣', '矢岛晶子', '本乡满', 8.3, 8160, 'tt2643796', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2510911608.jpg', 0.3, 1.4, 18.9, 42.8, 36.6, '0.410091,0.032175,-0.416591,0.264379,-0.292410,-0.172413,0.498515,0.104017,-0.138232,-0.189960,0.187012,0.691839,-0.208973,0.312721,0.146970,0.008082,-0.166326,-0.566019,-0.205009,-0.185863,-0.240257,-0.450736,-0.179217,-0.046726,-0.022034,-0.310729,0.307185,-0.091113,-0.171802,0.591025,0.419479,0.053407,-0.218586,0.138901,-0.147292,0.187900,0.143485,-0.125175,0.137417,0.457067,-0.135526,-0.113645,-0.063243,0.240166,0.102780,0.242854,0.749580,-0.450287,-0.207999,-0.137683,0.219067,-0.427134,-0.110280,0.193929,0.283307,-0.112449,0.150385,-0.061463,-0.249790,0.220309,0.127253,-0.257978,-0.793993,0.094726,-0.095784,0.139465,-0.498823,0.383725,0.225405,-0.214871,0.492367,-0.346148,0.352632,0.253313,0.245989,0.305584,-0.222291,0.217923,-0.423814,0.167162,0.332203,-0.201661,-0.040501,0.371147,0.027039,-0.360728,-0.025441,-0.133594,0.014594,0.014781,0.332413,0.152596,-0.309374,-0.233212,-0.589138,-0.143024,-0.161547,-0.116378,0.030979,-0.457995,-0.174057,-0.550470,-0.038782,-0.134697,-0.157953,0.112321,0.086592,-0.279466,0.873454,-1.114550,0.231527,0.578905,0.290373,-0.054375,0.458279,0.082623,-0.011079,-0.024443,0.030737,-0.171446,0.192919,0.628848,0.265363,0.514612,0.005332,-0.205318,-0.591611,0.297405', '1420088', '4127270', '1826173', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30449624', '暗恋·橘生淮南', '爱情', '暗恋，是一个人的兵荒马乱，也是一辈子的刻骨铭心。成绩优秀、生性骄傲的洛枳（张雪迎 饰），暗恋着幼时有过一面之缘的同学盛淮南（辛云来 饰），而盛淮南对此全然不知。高中毕业后，洛枳发现自己和盛淮南竟在同一所大学。两人意外相识并越走越近，但洛枳依然不敢表白心迹。当成长和现实的压力接踵而来，这场漫长的暗恋，究竟该如何安放？影片改编自八月长安振华系列，为电影《最好的我们》续篇。', '张雪迎', '黄斌', 4.2, 25792, 'tt18291400', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2873970594.jpg', 25.8, 44.8, 23.6, 4.5, 1.4, '0.217604,-0.276803,-0.543395,0.621879,0.398546,-0.047971,0.498892,0.092192,-0.304703,-0.313164,-0.118648,0.606310,-0.283833,0.302925,0.181071,-0.104005,-0.085973,-0.629006,0.084967,-0.584040,0.062134,-0.438064,-0.183868,0.032943,0.086550,0.218277,0.863612,0.140895,-0.127862,0.840890,0.545402,0.325177,-0.163101,0.558404,-0.041834,-0.009717,0.042312,0.301839,-0.620954,-0.144872,0.125928,-0.441815,-0.377640,0.122572,0.193175,0.072597,0.481306,-0.025619,-0.352809,0.037031,0.706556,-0.163606,0.045726,-0.144976,0.392261,0.021870,0.065698,0.279772,0.082692,0.191271,-0.287374,-0.148350,-0.587216,0.222017,0.359038,-0.148758,-0.429447,0.517296,0.287332,0.049573,0.043283,-0.089340,0.050764,0.425918,0.204176,0.222848,-0.239307,0.073018,-0.297163,0.352508,0.798536,-0.001186,-0.274844,0.652060,0.075712,-0.403545,-0.183147,-0.236588,-1.056125,0.289230,-0.166512,0.144433,-0.028122,0.243411,-0.115145,0.043322,-0.194748,0.096792,0.362127,-0.174285,-0.045266,0.119593,-0.421568,-0.748301,-0.360181,-0.195420,0.017711,-0.506803,0.519291,-0.777909,0.017765,0.192848,0.295326,-0.662982,0.556655,0.633199,-0.114677,-0.134905,-0.060763,0.583322,-0.064843,-0.099602,-0.069040,0.276184,0.187727,-0.082926,-0.581284,0.296294', '35030151', '3445516', '6973376', '4920528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30450313', '前程似锦的女孩', '剧情', '卡桑德拉（凯瑞·穆里根 Carey Mulligan 饰）曾是医学院里前途无量的高材生，却因为朋友的自杀而选择了退学。白天，卡桑德拉在咖啡店里打零工，而每当夜幕降临，她都会换上一身性感的装扮，出没于城市里各间声色犬马的夜总会之中，她会假扮成醉酒的样子，等待着某个“善良”的男人将她带回自己家中，由此来实行她对于男人的无伤大雅的报复。一天，卡桑德拉在咖啡店里和曾经的同学雷恩（博·伯翰 Bo Burnham 饰）重逢了，雷恩之后开始了对前者的热烈追求。雷恩的出现再次勾起了卡桑德拉对于学生时代悲惨经历的回忆，当她得知曾经造成自己好友死亡的罪魁祸首们如今都过上了各自精彩的人生后，复仇的火苗在内心里愈演愈烈。©豆瓣', '凯瑞·穆里根', '埃默拉尔德·芬内尔', 7.7, 55154, 'tt9620292', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2622450735.jpg', 0.9, 3.7, 28.1, 46.3, 21, '0.432559,0.121094,-0.814755,0.518264,-0.190722,-0.259994,0.941464,-0.132070,-0.763369,-0.242844,0.104426,0.824009,-0.390843,0.766997,0.498366,-0.001408,-0.254447,-0.850273,-0.290136,-0.314377,-0.326658,-0.393292,-0.436867,-0.310246,-0.079273,-0.275262,0.406199,0.265132,-0.164065,0.451598,0.466255,0.348774,0.055331,0.426058,-0.157479,-0.010662,-0.041968,0.110437,-0.088415,0.184364,0.144975,-0.502916,-0.107371,0.381691,0.020772,0.435708,0.849509,-0.335521,-0.173999,-0.292205,0.387663,-0.210278,-0.053312,0.234370,0.330004,0.008765,0.452555,0.272238,-0.099295,-0.180311,-0.099638,-0.069058,-0.462511,0.024091,0.119936,0.140918,-0.519729,0.489700,0.046813,0.122470,0.293345,-0.235159,0.305792,0.102349,0.363141,0.381549,-0.096781,-0.047641,-0.396901,0.327879,0.732536,-0.008603,-0.066384,0.345322,-0.440376,-0.197320,0.021119,-0.272670,-0.617018,-0.058566,0.089770,0.168294,-0.117531,0.382382,-0.553990,-0.029672,-0.213308,-0.112971,0.035588,-0.148644,-0.273525,-0.632719,-0.152549,-0.514341,-0.372416,0.139703,-0.172663,-0.267335,0.685055,-1.165663,0.296399,0.367475,0.419921,-0.454561,0.601908,-0.006315,0.263977,0.026340,0.077343,0.328280,-0.049550,0.229118,-0.088987,0.310295,-0.153795,-0.216115,-0.412385,0.794489', '1308755', '1292219', '35030151', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30452121', '头痛欲裂', '剧情', '29岁的建筑师 Markus（马克思·雷迈特饰）具有恋童癖倾向，他尽力抑制自己隐秘的欲望。当单身母亲 Jessica 和她八岁的儿子 Arthur 搬进公寓隔壁时，让 Markus 倾心的诱惑变得越来越大——尤其是在他与新邻居结交朋友之后……', '马克思·雷迈特', '萨瓦斯·泽维斯', 7.6, 6310, 'tt8603122', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2592605178.jpg', 0.7, 2.2, 30.1, 51.1, 15.9, '0.265568,-0.165024,-0.754634,0.299696,-0.478598,-0.371491,1.015933,0.389072,-0.758187,-0.428579,-0.151339,0.841777,-0.165055,0.790300,0.113413,0.194452,-0.218758,-0.637389,-0.005185,-0.051178,-0.283654,-0.190527,-0.423879,-0.447645,0.064651,-0.529214,0.301747,0.197722,-0.178102,0.257429,0.413424,0.457198,0.225080,0.388319,-0.273873,-0.260262,-0.065357,0.269846,-0.032046,0.010704,-0.178285,-0.001224,-0.008425,0.061788,-0.040659,0.522714,0.677218,0.038785,-0.467784,-0.197127,0.448139,0.225925,-0.125792,0.249096,-0.032087,-0.136032,0.307061,0.128010,-0.248999,-0.293949,-0.209844,0.039685,-0.614008,0.020915,0.346356,-0.567841,-0.739941,0.341610,-0.060199,0.129606,0.262572,-0.235873,-0.070421,0.088241,-0.416745,0.557113,-0.411040,0.099380,-0.348633,0.223487,0.599923,0.041691,-0.160296,0.114858,-0.300568,-0.439984,0.087012,-0.162647,-0.632784,-0.085016,0.093666,0.158741,-0.115713,0.268216,-0.687130,-0.311104,-0.090756,0.304659,0.162677,-0.362371,-0.040264,-0.425933,-0.517510,-0.363863,0.240490,-0.153167,0.262589,-0.329208,0.882163,-0.826807,0.196880,0.373690,0.579729,-0.609710,0.864645,-0.072540,-0.107532,-0.320443,-0.194042,0.122632,-0.096145,-0.174762,0.100733,0.355112,-0.070630,-0.030056,-0.584936,0.719155', '3055049', '3111650', '2081098', '2002744');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30453095', '言语如苏打般涌现', '动画', 'Cherry是个不善与人交谈、一直戴着耳机的少年，他喜欢把无法说出口的心情寄托于俳句中。Smile是个为了把矫正中的大门牙挡起来而一直戴着口罩的少女，身为人气视频上传者的她，看到可爱的东西就会发布视频。这样的两个人在商场相遇了，交换了联系方式开始聊天。他们在一起打工的地方，遇见了一个叫藤山的老人，后来还得知了老人一直在寻找某张唱片的原因。他们决定一起寻找唱片，而两人之间的距离也越来越近。但当某件事情发生之后，两人的想法出现了分歧。', '藤间斋', '石黑恭平', 7.8, 18928, 'tt12735338', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2624516210.jpg', 0.5, 2.5, 27.6, 45.4, 23.9, '0.624742,-0.003840,-0.713209,0.758863,-0.306708,-0.206512,0.748080,0.071941,-0.465018,-0.231609,-0.004923,0.984376,-0.501741,0.441881,0.203962,0.063787,-0.258676,-0.944347,-0.040791,-0.176272,-0.336135,-0.578928,-0.051849,-0.186423,-0.395979,-0.139176,0.527290,0.035227,-0.172419,0.368493,0.635870,-0.220200,-0.307558,0.602408,-0.405413,-0.282815,-0.033455,0.003087,0.063596,0.429047,0.230475,-0.306376,0.040923,0.144698,-0.069424,0.411003,0.640011,0.057095,-0.164614,0.227229,0.187924,-0.024042,-0.071206,-0.068116,0.489444,0.005114,0.478233,0.177714,-0.361829,0.078893,0.205320,0.037425,-0.611176,0.231640,-0.044773,0.604759,-0.587804,0.554732,-0.005067,-0.142653,0.249405,-0.447284,0.522226,0.389664,0.427604,0.258716,-0.274396,-0.161213,-0.556460,0.017514,0.746093,-0.124461,-0.104231,0.478490,-0.166269,-0.228962,-0.135746,0.133924,-0.448212,-0.017996,0.151780,0.141840,-0.523267,-0.034631,-0.643765,0.056590,-0.029416,-0.145342,0.090102,-0.546486,-0.224629,-0.522044,-0.254304,-0.574223,-0.306848,0.453456,0.062220,-0.304667,0.896207,-0.952691,-0.057594,0.563460,0.376729,-0.358849,1.025539,0.242369,0.133209,-0.254408,0.135765,-0.095485,-0.150815,0.192196,0.154698,0.365687,-0.019269,-0.205524,-0.524869,0.417467', '30162520', '3055049', '1303449', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30453797', '浴火鸟', '同性', '根据真实的故事改编，《浴火鸟》是一部冷战惊悚片，背景设定于1970年代的苏联。故事讲述，谢尔盖（Sergey，一名陷入困境的应征者，他的最好的朋友路易莎（Luisa），一位迷人有野心的基地指挥官秘书，以及一个胆大的年轻战斗机飞行员罗曼，三者之间如何形成危险的三角恋爱关系。在好奇心的驱使下，他们开启了禁忌之恋，在暧昧与欺骗之间，爱情与友谊的界限开始模糊。随着罗曼的职业生涯受到威胁，谢尔盖被迫面对自己的过去，而路易莎（Luisa）也努力使家人团聚。在围城之内，他们冒着失去自由和生命的危险，面对克格勃不断升级的调查，他们之间的命运会走向何方？', '汤姆·普赖尔', '皮特·列巴尼', 7.8, 9409, 'tt4061620', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2834406068.jpg', 1.2, 3.8, 26.5, 42.8, 25.8, '0.423975,0.101015,-0.672722,0.761200,-0.008324,0.009896,0.805370,-0.014264,-0.313483,-0.092960,0.345598,0.740461,-0.117284,-0.000382,0.275558,-0.393227,-0.126478,-0.743484,-0.172157,0.050729,-0.217498,-0.708050,-0.554439,-0.265778,-0.097106,-0.356173,0.877829,0.119027,-0.486932,0.281417,0.284948,0.278432,-0.495656,0.250077,-0.009188,-0.155802,0.276563,0.068403,-0.675147,0.147208,0.046706,-0.004321,0.004370,-0.009576,-0.264217,0.223232,0.650032,-0.393105,-0.270758,-0.016865,0.455689,-0.268464,0.012353,0.043761,0.330206,0.251499,0.121126,0.208606,-0.063880,0.016540,-0.172425,0.064221,-1.022773,-0.133938,0.193541,0.324786,-0.331075,0.232362,-0.020623,-0.216641,0.385889,-0.212484,0.110809,0.571952,0.504889,0.514325,-0.393011,0.155037,-0.333223,-0.137966,0.907870,-0.007813,-0.610196,0.277297,-0.331718,-0.228589,-0.295510,-0.155582,-0.597173,-0.262721,0.235932,0.122345,-0.003272,0.511906,-0.741698,0.020675,-0.144596,-0.084483,0.052207,-0.490344,0.078094,-0.477339,-0.430952,-0.538535,-0.378718,0.186119,0.183041,-0.307333,0.904821,-0.756902,0.255683,0.696748,0.383145,-0.526120,0.621167,0.399445,0.185813,-0.428174,-0.150169,0.601377,-0.130929,0.110992,-0.071370,0.266264,-0.006930,0.259868,-0.423252,0.403554', '26678784', '26667010', '1874704', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30454679', '打开心世界', '剧情', '故事发生在19世纪的美国东北部，艾比盖尔（凯瑟琳·沃特森 Katherine Waterston 饰）和丈夫戴亚（卡西·阿弗莱克 Casey Affleck 饰）在这里经营着一座农场，繁重的农活让艾比盖尔和丈夫之间没有任何的交流，不久之前两人的女儿因病去世的事件也让这对夫妻之间的感情更加的疏离。某日，农场里来了一对小夫妻——塔利（凡妮莎·柯比 Vanessa Kirby 饰）和芬妮（克里斯托弗·阿波特 Christopher Abbott 饰），塔利的处境和艾比盖尔差不过，在家庭中也处于弱势的地位，她因为无法怀孕而遭到丈夫的冷待。两个内心里伤痕累累的女人一拍即合，很快就培养出了真挚的友谊，这友谊随着时间渐渐发酵，散发出了爱情的醇香。©豆瓣', '凯瑟琳·沃特斯顿', '莫娜·法斯特欧德', 8.2, 32291, 'tt9738716', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2632936000.jpg', 0.6, 1.8, 18.6, 46.2, 32.7, '0.457738,-0.120091,-0.921569,0.703354,-0.061271,-0.476294,1.148743,0.349059,-0.654930,-0.288018,0.000621,0.734041,-0.240450,0.195229,0.155187,-0.072791,-0.500316,-0.802112,-0.059940,-0.249808,-0.139802,-0.657662,-0.283968,-0.138539,-0.328595,-0.271571,0.412216,-0.257691,0.047660,0.561012,0.212670,0.189355,0.087453,0.295199,0.042091,0.175188,0.203396,0.164360,-0.383260,0.195024,0.364071,0.216873,0.013507,0.175289,0.118847,0.517093,0.590695,-0.299102,-0.077732,-0.212618,0.237617,0.050245,0.191776,0.280292,0.426176,-0.224375,0.409574,0.265308,-0.529696,-0.124615,0.154256,-0.014376,-0.618399,0.345383,0.154454,0.233337,-0.494412,0.684932,-0.200754,-0.516521,0.198634,-0.327663,0.172873,0.847182,0.437629,0.583963,-0.379298,-0.001344,-0.593204,-0.141479,0.588666,0.067675,-0.326254,0.491028,-0.548393,-0.359330,-0.254864,-0.094266,-0.538761,-0.281769,0.336144,0.099306,-0.064230,0.807185,-0.852187,0.116378,-0.210280,-0.049643,0.043812,-0.422275,0.138794,-0.667364,-0.435460,-0.883469,-0.527886,0.035091,0.147261,-0.197712,0.531192,-0.867410,0.244958,0.239611,0.476660,-0.158048,0.628809,0.259451,0.403504,-0.154546,0.029017,0.505770,-0.151010,0.059011,0.271184,0.448937,0.086958,0.036042,-0.224703,0.720642', '24639908', '3111650', '26857860', '5966609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30454698', '解放·终局营救', '剧情', '1949年1月，中国人民解放军将国民党 50 万军队围困于平津地区，总攻在即。是否能和平解放北平，取决于天津一战。此时的天津城内，暗堡、工事林立，士兵荷枪实弹进入状态，大战前的天津城已是一座炼狱。为了总攻的发动扫平道路，解放军炮兵侦察连连长蔡兴福、侦察兵马宝树、报务员廖枫、炮兵见习参谋葛贵忱四人临危受命，组成解放炮兵侦察别动队，乔装潜入天津城。此时，负责转移北平守军眷属的国军军需官姚哲在宪兵营长钱卓群的暗算下成为通缉犯，带女儿出逃时恰好与进城的蔡兴福一行人相遇，蔡兴福挟持姚哲欲完成任务。随着目标任务的逐步明晰，姚哲被暗算背后的秘密、钱卓群企图破坏北平和谈的阴谋、蔡兴福失踪儿子的下落都渐渐浮现出来……', '周一围', '李少红', 4.4, 10643, 'tt10074536', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2576622878.jpg', 23.4, 43.1, 26.2, 4.6, 2.7, '-0.036778,-0.146660,-0.473125,0.357836,0.106592,0.130271,0.152330,-0.106650,-0.348130,0.016616,0.420859,0.324160,0.450551,-0.385726,0.338723,-0.350652,-0.482814,-0.808168,-0.364555,-0.342551,-0.174073,-0.519234,-0.268935,-0.192020,0.363261,-0.402251,0.862494,0.638048,-0.178708,0.338957,0.167679,0.165767,-0.465865,0.473695,0.087071,-0.002789,0.203772,-0.651586,-0.404716,0.131030,-0.578371,-0.229385,-0.187595,-0.177944,0.004551,0.341465,0.951974,-0.210796,0.097949,-0.337235,-0.281911,-0.341746,0.105557,-0.116672,0.584223,0.304032,-0.061549,0.145854,-0.109247,0.028062,-0.529599,-0.067586,-0.311027,0.058786,0.161822,-0.206592,-0.189921,0.147242,-0.065217,0.602600,0.373527,-0.336628,0.274496,0.942766,0.009867,0.203796,-0.419522,0.340259,-0.541672,0.134719,0.642650,-0.441278,-0.034204,-0.483108,0.354726,-0.227556,0.124694,-0.206769,0.071268,-0.005189,-0.008768,-0.147374,0.237660,0.134096,-0.327078,-0.188486,-0.489078,-0.143082,0.187436,-0.047541,-0.146192,-0.730860,0.150230,0.194353,-0.057575,0.485306,0.096439,0.585788,0.462853,-0.773456,-0.059399,0.423565,0.514695,-0.426977,0.214191,0.246045,0.235357,-0.337339,0.167379,0.176780,0.182285,0.962965,0.200632,0.211182,-0.591865,-0.297202,-0.320849,0.224450', '1307201', '1464540', '1431694', '1305697');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30456637', '沿路而下', '动作', '西班牙银行是无与伦比的，绝对没有人能闯得进去，也不可能被人抢劫，没有蓝图、没有资料，世上没有人知道一百多年前用来建造金库的历史性工法。这个充满刺激的挑战激起了汤姆的好奇心：这个天才决心找出金库的秘密，闯进银行的最深处。目标是遗失已久的宝藏，将在这家银行内保管仅仅十天。在极具领袖风范的艺术鉴赏家华特的带领之下，汤姆和他的团队要在短短十天内准备好这次的抢案，事成后还要拟好千载难逢的逃跑计划。计划十天，但执行这个计划却只有90分钟：这90分钟是世界杯足球决赛的时间，届时将吸引成千上万的球迷来到西班牙银行的门口。', '弗莱迪·海默', '豪梅·巴拉格罗', 6.9, 17981, 'tt9742794', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2633150167.jpg', 0.9, 6.6, 48.6, 34.9, 9.1, '0.066152,0.254122,-0.860953,0.608157,-0.280305,-0.084585,0.651264,-0.356154,-0.672729,-0.226805,0.147971,0.654028,-0.162808,-0.195727,0.119816,-0.004240,-0.208781,-0.728682,-0.363136,-0.777547,-0.200866,-0.433975,-0.397869,-0.300903,-0.018579,-0.223479,0.775229,0.409957,-0.088625,0.220312,0.198834,0.142370,0.397483,0.412021,-0.405901,0.002318,0.427361,-0.044935,-0.154042,0.636538,0.070762,-0.298799,-0.080616,0.454157,0.089256,0.399975,0.366106,-0.276537,-0.120540,0.151403,0.377624,-0.409796,-0.280809,0.057847,0.369788,-0.160507,0.097811,0.439481,-0.467832,-0.023468,0.090406,-0.373688,-1.077601,-0.224750,0.032710,0.108146,-0.644121,0.514230,-0.336788,0.170380,-0.064454,-0.212881,0.175447,0.415507,0.355606,0.182241,0.013556,-0.047053,-0.920493,0.096535,0.678614,-0.349397,-0.056607,0.209848,-0.094586,-0.596384,-0.029613,-0.490008,-0.183484,0.003383,0.485633,0.256625,-0.190729,-0.088605,-0.502973,0.274086,-0.270411,-0.434436,0.077020,-0.529780,-0.198390,-0.748773,-0.138288,-0.143470,-0.246576,0.281356,0.116670,-0.133608,0.685905,-0.799424,0.143991,0.719589,0.387652,-0.456004,1.047266,0.000406,-0.039649,-0.182695,0.078486,-0.145218,-0.117806,0.630507,-0.052564,0.481309,0.225686,-0.572262,-0.509039,0.655909', '1793491', '1308842', '3785918', '1299932');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30458826', '赌博默示录3', '剧情', '2020年，在东京奥运结束后，日本的景气突急速低迷，变成贫穷的弱者能轻易被击垮的社会。被派遣公司当成傻子，领微薄的薪水过着堕落生活的伊藤开司（藤原龙也 饰），某天再次遇见了成为帝爱集团社长的大槻太郎，大槻告诉开司在某位有钱长者所举办的活动中，能够一获千金的机会…', '藤原龙也', '佐藤东弥', 5.5, 7180, 'tt10423160', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2572823044.jpg', 9.4, 30.2, 43.4, 11.5, 5.5, '-0.158675,0.454767,-0.529659,0.376066,-0.132149,-0.139695,0.136033,0.310016,-0.348206,-0.146753,-0.114420,0.720796,-0.048207,0.490188,0.678961,-0.123886,0.236244,-0.633776,-0.353711,-0.036936,-0.006530,-0.369611,-0.226168,-0.406746,-0.202932,-0.200286,0.493187,0.281858,-0.243206,0.319566,0.388443,0.398628,0.260587,0.144765,-0.353152,-0.067688,0.194632,0.174937,-0.358458,0.614147,-0.529070,-0.012907,0.054985,-0.023321,0.228046,-0.009116,0.386829,-0.163868,-0.197979,-0.430271,0.572919,-0.085794,-0.287739,0.323979,0.420538,0.280943,0.172907,0.261617,-0.258363,0.097950,0.241298,-0.305204,-0.808164,-0.052160,-0.110278,0.055975,-0.578360,0.482492,0.157962,-0.394000,-0.052765,-0.272653,0.146585,0.520325,0.203653,0.085143,-0.231819,0.422988,-0.447676,0.413473,0.827379,-0.125291,-0.671083,0.039387,0.198934,-0.407440,0.108490,-0.572619,-0.206966,-0.274874,0.290719,0.202103,-0.341465,0.276765,-0.359381,-0.143767,-0.157839,-0.318264,0.258021,-0.324134,-0.154620,-0.425070,-0.066967,-0.315137,-0.154898,0.413700,0.154940,-0.313999,0.641239,-0.997090,0.302377,0.685007,0.547501,-0.379338,0.500352,-0.015372,-0.122082,0.373379,-0.253053,-0.090625,0.035884,0.674238,0.196413,0.088010,-0.265510,-0.494777,-0.081545,0.249033', '30345227', '1877596', '5985887', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30458949', '无依之地', '剧情', '2008年金融危机下，美国内华达州昂皮尔小镇的重要经济支柱石膏厂倒闭，人去镇空，这里的邮政编码也被取消。丈夫去世后，几乎在在昂皮尔小镇度过了一生的弗恩（弗兰西斯·麦克多蒙德饰）无力独撑生活。为了将生活成本压到最低，她将简陋的家当搬上了改装后的厢式货车，开始了一边打工、一边西行的公路生活。她在亚马逊流水线上、在游乐园的咖啡厅里、在国家森林公园做临时工。一路上，她和许多厢式货车寄居者相遇、相识，彼此帮助，并缔结了友谊。', '弗兰西斯·麦克多蒙德', '赵婷', 8.1, 159203, 'tt9770150', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2630453887.jpg', 0.3, 1.6, 17.7, 51.3, 29.1, '0.414153,0.218361,-0.805832,0.334966,-0.029771,-0.232140,0.804648,0.415358,-0.538777,0.124116,0.352996,0.825382,0.136409,0.315715,0.135608,-0.002399,-0.478346,-0.530946,0.097933,-0.109576,-0.608391,-0.453417,0.031929,-0.325728,-0.314401,-0.115201,0.430916,0.276853,0.168506,0.401029,-0.033594,-0.111091,-0.135857,0.329002,-0.565538,-0.054741,-0.008635,0.011098,-0.410769,0.235184,-0.218421,-0.413398,0.233702,-0.269062,0.490936,0.137386,0.784035,0.146854,0.027855,0.043905,0.052718,-0.156523,-0.032419,-0.029621,0.457108,0.179686,0.049684,0.402702,-0.436017,-0.045660,0.262974,-0.172235,-0.675607,-0.046015,-0.180304,-0.103318,-0.959364,0.874155,-0.079686,0.002848,-0.212777,-0.599991,0.252934,0.354181,0.151697,0.367580,-0.228968,0.220395,-0.679592,0.294237,0.914752,-0.246149,-0.016239,0.416020,-0.112085,-0.214884,-0.209393,-0.274983,-0.360617,-0.358639,0.204521,-0.192802,-0.363065,0.135769,-0.718005,0.209070,-0.102908,-0.655175,0.208168,-0.243187,-0.185182,-0.727543,0.074641,-0.485876,-0.188292,0.116262,0.166208,-0.289273,0.464413,-0.638597,0.137215,0.569032,0.519597,-0.143686,0.731265,-0.295652,0.646726,-0.046267,0.071453,0.317193,-0.184586,0.898955,0.259753,0.282331,-0.365839,0.348422,-0.549702,0.668350', '26678509', '3055049', '1926007', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30459571', '明日之战', '动作', '2022年地球收到一份来自未来的召唤：30年后的地球遭遇未知物种的攻击，面临灭种危机，为了拯救地球，丹（克里斯·帕拉特 饰）被招募为战士去到未来，支持地球上人类的最后一战。直到亲眼所见，丹才终于知道人类所面临的对手竟是是以人为食的残暴怪兽………关乎人类存亡的最后一场大战拉开帷幕......', '克里斯·帕拉特', '克里斯·麦凯', 5.9, 103825, 'tt9777666', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2678875868.jpg', 3.8, 21.1, 56, 16.8, 2.4, '-0.098367,0.314619,-0.342952,0.489855,0.327030,0.215846,0.223954,-0.250008,-0.381430,-0.292943,0.352988,0.585683,0.184445,-0.224824,0.517329,-0.210585,0.164194,-0.361727,0.031383,-0.149649,-0.791874,-0.006952,-0.462683,-0.101674,-0.107538,-0.505318,0.966668,0.484424,-0.271560,0.301360,-0.005824,0.759286,0.062891,0.524953,0.140164,-0.223377,-0.210540,0.256982,-0.637774,0.431220,-0.277755,0.020676,0.146277,0.414537,-0.290044,-0.027306,0.688626,-0.820136,0.143104,-0.915459,0.487591,-0.431491,-0.084962,0.038886,0.755655,-0.020336,-0.187675,0.247064,0.082034,0.064176,0.132389,-0.223191,-1.322149,-0.461318,-0.085557,-0.079788,-0.391408,0.428883,0.180333,0.353519,0.219230,0.037528,0.165013,0.947261,0.604643,0.608667,-0.008372,-0.277655,-0.394099,-0.331674,1.013824,-0.475656,-0.328774,0.175748,-0.124088,-0.687295,-0.110043,-0.893758,-0.345038,0.435780,-0.206576,0.495971,-0.215914,0.851523,-0.945553,0.054088,-0.556063,-0.523600,0.498788,-0.437699,-0.276513,-0.429338,-0.212249,-0.069056,-0.161973,0.332796,0.375306,-0.569905,0.909188,-0.685364,0.248134,0.623043,0.426568,-0.547689,0.574432,0.134357,0.144696,-0.604331,-0.148911,0.720030,0.052521,0.389243,-0.354251,-0.526044,0.213822,0.226435,0.089558,0.598307', '35377026', '3001114', '25827286', '3718665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30459588', '蝙蝠侠大战忍者神龟', '动作', '讲述了忍者神龟与蝙蝠侠跨时空相遇，他们本都是默默守护正义的使者。然而在铲除罪恶的过程中蝙蝠侠和忍者神龟产生了误解，经过一系列打斗后，解除彼此的误解，共同作战，守护城市的和平以及人们的安全。', '达伦·克里斯', '杰克·卡斯托雷纳', 7.5, 6521, 'tt9775360', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2557150529.jpg', 0.7, 3.4, 34.9, 44.7, 16.3, '0.391181,-0.158991,-0.610832,0.482627,0.225842,0.050066,0.555177,-0.007471,-0.415179,-0.172863,0.505788,0.707694,-0.174160,-0.095930,0.523871,-0.531271,-0.708626,-0.911080,-0.445436,0.026581,-0.263938,-0.666971,-0.299685,-0.427805,-0.075367,-0.669076,0.907803,0.374044,-0.489699,0.230005,-0.015081,0.248101,-0.746168,0.517668,-0.077945,0.114818,0.016410,0.004152,-0.669212,-0.038402,-0.153773,-0.153083,-0.029017,0.195299,-0.318193,0.373446,0.696598,-1.001478,-0.241133,-0.257658,0.254492,-0.820711,-0.097256,-0.118368,-0.038539,0.137016,0.183202,0.673291,0.002073,0.083346,-0.138483,-0.053104,-0.990963,-0.253732,0.275236,0.091039,-0.419345,0.819941,0.486428,0.012793,0.415014,-0.107596,0.424389,0.686185,0.899405,0.182167,-0.328266,-0.028009,-0.363240,0.021451,1.130684,-0.317794,-0.320900,0.137668,-0.155620,-0.377170,-0.396018,-0.066245,-0.441980,-0.275050,0.025251,0.268526,0.018913,0.625665,-0.940606,-0.239774,-0.253461,-0.342557,0.254357,-0.701010,0.124235,-0.960120,-0.505744,-0.545787,-0.038537,0.141075,0.127037,-0.391989,0.860543,-1.054315,0.354506,0.462973,0.481943,-0.565362,0.650223,0.270113,0.533467,-0.289878,-0.045397,0.327652,0.098504,0.500597,-0.054695,0.097386,-0.012179,0.512721,-0.541149,0.296266', '26759819', '25917239', '26375028', '1849026');
