INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30463515', '八子', '动作', '上世纪30年代的赣南地区，在这个被称为中国革命“红色摇篮”的地方，曾经有这样一位母亲，她将八个儿子先后送入红军，奔赴战场前线。但战火无情，兄弟中的六人陆续牺牲，只剩下大哥杨大牛和最小的孩子满崽。满崽找到了大牛的部队，成了哥哥麾下的普通一兵，一场场艰苦战役的淬炼让新兵满崽迅速成长为一个真正的战士。最后的战斗打响了，为了掩护大部队安全撤离，杨大牛带领弟弟满崽和全体战友浴血肉搏，直至弹尽粮绝……英雄的身前，是枪林弹雨的沙场，而在英雄的身后，家乡的村庄依然宁静安详，微风吹过金黄的稻浪簌簌作响，一位年迈的母亲正在村头的小路旁孤独的守望……影片根据江西赣南地区家喻户晓的“八子参军”的故事改编。在战火硝烟的年代，千万人民群众投入到支援革命战争中，奉献了自己的一切。作为那个残酷年代的缩影，骨肉相连的母子情、不离不弃的兄弟情、赤胆忠心的家国情.....无数荡气回肠、难以割舍的情感凝聚于影片之中，共同谱写了一首可歌可泣、永垂不朽的英雄乐章。', '刘端端', '高希希', 4.1, 2978, 'tt10434986', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2557265183.jpg', 40.2, 24.7, 25.8, 6.2, 3.1, '0.086108,0.070550,-0.620298,0.649448,0.052352,-0.195973,0.589868,0.144037,-0.357086,0.010926,0.448412,0.703385,0.462372,0.157157,0.161365,-0.301728,-0.057050,-0.904405,-0.574650,0.067834,-0.352817,-0.312849,-0.316177,-0.026766,-0.222600,-0.282497,0.893490,0.339512,-0.086542,0.419120,0.096618,0.056848,-0.196188,0.154316,-0.362723,0.023047,0.033146,-0.121669,-0.574568,-0.001990,-0.374497,-0.149471,-0.151146,0.008695,-0.237268,0.196635,0.960882,-0.399654,0.176473,-0.212256,0.381979,-0.171004,-0.065860,-0.046873,0.335998,0.104776,0.361426,0.090703,0.163020,-0.160655,-0.296856,-0.185092,-0.799226,-0.200564,0.160407,0.086031,-0.743339,0.611435,0.129700,-0.100010,0.441851,-0.026845,0.370962,0.383465,0.224634,0.546448,-0.565479,-0.085062,-0.269453,0.506802,0.846979,-0.222955,-0.310660,0.071421,-0.378823,-0.334898,0.102314,-0.442241,-0.652409,-0.095461,0.152082,-0.026258,-0.002013,0.443975,-0.830524,0.290320,-0.170458,-0.297143,0.089142,-0.280246,-0.238132,-0.344616,-0.213145,-0.313075,-0.133432,0.358011,0.018797,0.066514,1.143847,-0.497849,0.156733,0.437910,0.040218,-0.181873,0.651420,0.250289,0.287428,-0.038794,0.178288,0.420882,-0.125623,0.416978,0.274381,0.238113,-0.509965,0.071218,-0.463268,