INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30464264', '犹大与黑弥赛亚', '剧情', '影片改编自真人真事。讲述了1960年代美国黑人社团黑豹党历史上的真实事件，故事聚焦于Hampton之死，他于1969年被杀，死于芝加哥警察局和FBI组织的一次突袭行动。警方开了80枪，而“黑豹党”成员一共只开了一枪，这一枪还是来自于一位成员被警方打死后的肌肉收缩。Hampton与怀孕的未婚妻正在睡觉时，头部被近距离射杀2枪，他当晚被下了药，根本没听见任何警方的动静，死后尸体被拖进小巷中，年仅21岁。经过审讯，他的死被判定为“正当杀人”，后来在1982年，以185万美元的赔偿数额，达到了民事诉讼的庭外和解。', '丹尼尔·卡卢亚', '沙卡·金', 7.3, 6687, 'tt9784798', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2632634812.jpg', 1, 4, 38.2, 44, 12.8, '0.118975,-0.127768,-0.639607,0.209498,-0.065986,-0.002352,0.668916,-0.248319,-0.476977,-0.246636,0.154745,0.699543,-0.391024,0.021631,0.246718,-0.451751,0.246458,-0.830067,-0.246006,-0.015453,-0.643418,-0.441934,0.009514,-0.133011,-0.008845,-0.303238,0.444760,0.088771,-0.406586,0.391221,0.270019,0.556890,-0.010152,0.343638,-0.071816,0.052199,0.212464,-0.340427,-0.151497,0.525419,-0.062565,-0.799128,0.097712,0.072172,-0.353359,0.426894,0.716249,-0.215110,-0.223716,-0.222260,0.316080,-0.335914,-0.395343,0.220451,0.651569,0.236587,0.299652,0.521938,-0.215186,0.087479,0.079522,-0.149598,-0.718993,-0.169428,-0.095761,-0.057610,-0.627478,0.502457,-0.480918,0.404970,-0.158242,-0.175935,0.426748,0.163935,0.209230,0.307415,-0.431062,-0.098397,-0.788095,0.046456,0.667398,0.000753,-0.138322,0.104486,0.135045,-0.541894,-0.226395,-0.335682,0.181850,0.357035,0.663149,-0.079662,-0.470263,0.166581,-0.389159,-0.326765,-0.452359,-0.600300,-0.082661,-0.288408,-0.436947,-0.247116,-0.193675,-0.031740,-0.343393,0.247506,0.051650,-0.123844,0.351710,-0.740101,0.201120,0.466944,0.288752,-0.361856,0.650682,0.048838,0.074635,0.239909,-0.020274,0.098120,0.626178,0.488179,0.356446,0.219747,-0.238792,-0.354532,-0.484389,0.095601', '1300359', '25870679', '1400667', '1305386');
