INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30465538', '法兰西', '剧情', '法国第一女主播法兰西强悍娇艳，记者会上向总统犀利提问，转眼又眉来眼去频送秋波；坐镇主持政论节目，以完美妆容力战来宾；亲身前往远方战地“演绎”实况，还不忘忙碌奔波照顾家庭。她原是法国人心头上的一颗硃砂痣，一场肇事车祸却让她成了那抹蚊子血。法兰西发现主播的华美衣袍下其实爬满了蚤子，播报台下的美丽与哀愁谁人能解？当她决定洗尽铅华隐姓埋名，意外的邂逅突然降临，触动心中最柔软的那一块⋯⋯。怪咖名导布鲁诺杜蒙以“法兰西”为名，直讽国家金玉其外却败絮其中的种种现象。从新闻操弄、难民问题到失能家庭，刻意营造的通俗手法与脸部特写，捕捉主角在虚假之外，无处安放的敏感脆弱。', '蕾雅·赛杜', '布鲁诺·杜蒙', 6.9, 10688, 'tt9714030', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2870562827.jpg', 1.6, 8.9, 43.4, 36.2, 9.9, '0.087751,0.132915,-0.617619,0.377787,0.086596,0.061871,0.698894,0.065442,-0.126944,0.000822,0.291002,0.403719,-0.456275,0.068402,0.264809,0.115091,-0.289817,-0.544345,-0.099003,0.127058,-0.050760,-0.040697,-0.310188,-0.165107,0.169130,-0.211571,0.492658,0.306890,-0.362866,0.316393,0.230784,0.209076,-0.229583,0.245751,0.013654,-0.278041,-0.267017,-0.029675,0.049141,-0.021397,-0.034416,-0.445070,-0.171830,0.280799,-0.235326,0.455587,0.496336,-0.103335,-0.124604,-0.145678,0.408543,-0.226892,0.148502,0.162535,0.045680,0.026710,0.365783,-0.174052,-0.192472,-0.100705,0.021736,-0.009173,-0.561338,0.010012,0.102032,0.367664,-0.241360,0.452512,-0.245429,-0.060065,0.054231,-0.239107,0.289560,-0.117708,0.090618,0.414716,0.096328,0.212992,-0.089938,0.443969,0.477624,0.410283,-0.377263,0.251884,-0.270504,-0.301292,0.143049,-0.420386,-0.098013,-0.039067,0.139635,-0.105131,0.127468,0.178742,-0.399742,-0.002840,-0.152786,-0.140809,-0.188268,-0.224022,-0.089729,-0.600946,-0.290181,-0.202861,-0.302694,0.055261,0.249366,-0.143429,0.528069,-0.484624,0.085223,0.524611,0.007708,-0.212925,0.450899,0.168447,-0.160577,-0.096466,-0.278649,0.220255,0.111486,0.217969,-0.136410,0.172044,-0.279447,-0.031693,-0.426220,0.311912', '3005387', '30234315', '10466639', '1316693');
