INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30466831', '独家记忆番外之再见爱', '爱情', '一晃眼时间来到了数年后，此时的白霖（张樟 饰）已经升入了大四，正在青山学院经历她的实习期。在这个节骨眼上，李佳航（李欢 饰）再度出现在了她的身边，虽然白霖一直对李佳航的付出十分的抗拒，但后者却从来没有因为白霖的态度而改变过自己的感情。即将毕业之际，白霖遭到了同学的算计而失去了拿奖学金的机会，虽然受到了重大的打击，但白霖却并没有自怨自艾，而是将所有的心思都放在了找工作上，踏踏实实的她最终获得了应得的回报。而命运的红线将李佳航再度带到了白霖的面前，这一次，他们能否珍惜这来之不易的机会呢？©豆瓣', '张樟', '刘畅', 6.5, 4729, 'tt10472286', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2549575499.jpg', 1.2, 14, 53.2, 22.8, 8.8, '0.363825,0.360230,-0.921151,0.682706,-0.304904,-0.736399,0.785189,0.165736,-0.678544,-0.088334,0.117310,0.655423,-0.055941,0.194771,0.243235,-0.072899,-0.076670,-0.998809,0.068989,-0.301381,-0.460681,-0.316392,-0.202822,0.161298,-0.347620,-0.315193,0.773260,-0.006643,-0.021361,0.643379,0.314035,-0.067280,0.443578,0.966705,-0.118737,0.058107,0.059543,0.299409,-0.099108,0.360246,0.292531,-0.480958,-0.336476,0.569201,0.101875,0.572193,0.666960,-0.269509,-0.451635,-0.033901,0.337066,-0.565607,0.056207,0.209577,0.170749,0.137324,0.172138,0.264588,-0.308678,-0.084212,0.162347,-0.122827,-0.910986,-0.077114,-0.075251,0.248248,-0.820719,0.815182,-0.025553,-0.100034,-0.195530,-0.427579,0.245517,0.603430,0.257646,0.043732,-0.658745,-0.205654,-0.399353,0.172649,0.579189,-0.198216,-0.215639,0.590351,-0.223074,-0.524182,-0.149083,-0.232185,-0.289218,0.061373,0.307693,0.554685,-0.460240,0.123788,-0.570032,0.238713,-0.267394,-0.432397,0.001589,-0.709286,-0.152434,-0.435565,-0.120507,-0.663564,-0.870273,0.149107,0.046703,-0.347582,0.650427,-0.996008,0.273675,0.433605,0.348084,-0.500697,0.760101,0.190025,0.057382,0.102191,-0.071601,0.212796,-0.275649,0.783667,0.206244,0.267972,0.156701,-0.374589,-0.344162,0.898092', '34973399', '1301022', '21360412', '1306801');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30466833', '独家记忆番外之勇敢爱', '爱情', '慕承（张超 饰）和薛桐（李婷婷 饰）在大学校园里曾经有过一段浪漫的恋情，然而年少轻狂的两人因为不懂得如何沟通而最终擦肩而过。校园里的一幕幕都被时间蒙上了厚厚的灰尘，在大家以为过去终究会过去之际，慕承和薛桐竟然在机缘巧合之下重逢了。重逢的短暂喜悦消退之后，尴尬慢慢浮现。此时的薛桐已经选择和刘启（陈博豪 饰）走近了一段新的感情之中，而慕承则选择出国留学。在即将离开之际，慕承念念不忘曾经对薛桐的承诺，薛桐被此感动了，她决定再给两人的感情一次机会，于是他们一起来到了俄罗斯。慕承是否能够珍惜薛桐给他的这次珍贵机会，摆脱过去的阴云，迎接新的希望呢？©豆瓣', '张超', '刘畅', 5.1, 5683, 'tt10472282', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2549575419.jpg', 10.9, 41, 35.6, 8.2, 4.3, '0.359783,0.360049,-0.977892,0.636116,0.093780,-0.681831,0.681659,-0.119779,-0.645033,-0.130860,0.041861,0.536155,-0.370515,0.457269,0.227459,-0.231088,-0.331692,-0.978630,0.058339,-0.444189,-0.394977,-0.258752,-0.409901,0.097540,-0.222559,-0.190401,0.693037,0.373598,0.068824,0.831509,0.340138,0.024527,-0.351253,0.818176,0.032327,-0.011778,0.111084,0.312075,-0.777217,0.257175,0.249319,-0.351920,-0.300202,0.180838,-0.075658,0.121104,0.731803,-0.214235,-0.331462,0.063711,0.277269,-0.180944,0.093604,0.440130,0.007261,0.355256,0.521040,0.169753,-0.417900,0.057695,-0.011051,-0.041712,-0.347771,0.128293,-0.235528,-0.023988,-0.704200,0.588607,0.059560,-0.249912,0.167512,-0.571408,0.214400,0.578045,0.780351,0.266429,-0.465101,-0.031796,-0.138638,0.092752,0.857149,-0.064437,-0.092744,0.611862,-0.131389,-0.247435,-0.087515,0.200291,-0.362590,0.008850,0.479806,0.315732,-0.386005,0.235439,-0.586075,-0.141023,-0.268617,0.059251,0.083191,-0.358179,0.017153,-0.336004,-0.429142,-0.402271,-0.608786,0.282139,0.017282,-0.318171,0.509848,-0.930867,0.388189,0.285375,0.428244,-0.300639,0.551137,0.200885,-0.000940,-0.094902,0.278665,0.234230,-0.161315,0.285106,0.286521,0.336054,-0.095176,0.048760,-0.595605,0.525142', '1301022', '2365260', '34973399', '3401409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30466860', '倩女幽魂：人间情', '剧情', '书生宁采臣（陈星旭 饰）进京赶考，在某日深夜为了躲雨而进入了废弃的兰若寺，哪知道在这里竟然遇到了一位绝世美女聂小倩（李凯馨 饰），不仅如此，聂小倩还非常主动的对宁采臣投怀送抱。原来，聂小倩是一名女鬼，专门替她的主人黑山老妖（徐少强 饰）勾引男人，让黑山老妖可以吸食他们的精气。然而，无论聂小倩如何像宁采臣搔首弄姿，后者都不为所动，头一次见到如此正直之人，聂小倩心动了。当宁采臣知道了聂小倩的真实身份之后，决定和驱魔道士燕赤霞（元华 饰）联手，将聂小倩从黑山老妖的掌控之下解救出来。©豆瓣', '李凯馨', '林珍钊', 4.7, 25249, 'tt12217840', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2597931214.jpg', 19.8, 37.7, 33.5, 6.2, 2.8, '0.103503,-0.075089,-0.621187,0.400221,-0.444900,-0.129651,0.404043,-0.023927,-0.543582,-0.286149,0.301778,0.550552,-0.242164,0.224133,0.196189,0.074593,0.226668,-0.309601,-0.121882,-0.409356,-0.148418,-0.113409,-0.329832,0.047690,-0.025837,-0.143413,0.475559,0.166689,-0.134370,0.304238,0.559364,0.262532,-0.241658,0.574737,-0.266330,-0.024458,-0.102763,-0.089158,-0.078339,0.523111,0.044542,-0.330136,-0.095674,0.296883,-0.367610,0.204839,0.509470,-0.376234,-0.148344,-0.011475,0.241853,-0.106969,0.119060,0.213549,0.144198,-0.373716,0.322717,0.057204,-0.027310,-0.281253,0.156265,0.103968,-0.319698,0.463688,0.263332,0.129463,-0.622453,0.045471,0.133438,0.227998,0.005643,-0.574580,0.038203,0.203207,0.352050,0.147745,-0.148270,-0.330575,-0.577870,0.104055,0.465809,0.039276,0.239868,0.392691,0.239936,-0.479500,0.107848,-0.175197,-0.288176,0.104994,0.136714,0.019846,-0.083743,-0.053798,-0.288386,-0.228602,-0.270524,0.460746,-0.101186,-0.122594,-0.253942,-0.326386,-0.178884,-0.138314,-0.060496,-0.104465,0.132089,-0.261369,0.694828,-0.979705,0.081964,0.426604,0.402278,-0.690650,0.488749,-0.002769,-0.102833,-0.256169,-0.233808,0.007718,0.324262,0.362361,0.163160,0.348238,-0.069191,-0.161997,-0.380271,0.060507', '1419416', '2052978', '35030151', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30466885', '我们永不言弃', '剧情', '拳坛上所向披靡的“死神”周始因一次意外被判入狱五年，出狱后妻子离世，只剩女儿周自在等他。年幼的女儿被发现患上白血病，周始为完成女儿心愿，以36岁高龄重返擂台，与拳王展开IBF金腰带争夺战。即使体能消耗殆尽、头破血流、视线模糊、血肉飞溅，亦会继续打下去，直至分出胜负…', '韩庚', '周显扬', 4.6, 3170, 'tt12746342', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2595882406.jpg', 24.2, 38.8, 26.7, 5.5, 4.8, '-0.678277,0.356866,-0.500446,-0.035090,-0.038370,-0.650475,0.511003,0.003093,-0.275056,-0.307035,0.260659,0.661309,-0.346601,0.105472,0.158840,-0.631942,0.027878,-0.673617,0.128437,0.106451,-0.500654,-0.383638,0.111505,0.316818,-0.223466,-0.582779,0.833224,0.272382,0.206578,0.563137,0.200246,0.043704,-0.081289,0.242387,-0.000541,-0.007744,-0.458374,-0.094238,-0.473288,0.532200,0.057539,-0.238872,0.073579,-0.312188,-0.307754,0.303019,0.955597,0.101993,-0.047474,-0.705322,0.526425,-0.362770,-0.303126,0.483540,0.469948,0.425651,0.399980,0.094926,0.051422,-0.341840,0.057853,0.069200,-0.184803,-0.108489,-0.026745,-0.025433,-0.490578,0.601987,-0.193916,0.124399,-0.198800,-0.145199,-0.095043,0.340698,0.114937,0.447235,-0.561968,0.186736,-0.412913,0.081082,0.595786,-0.248861,-0.366638,0.146688,0.523592,-0.310105,0.234215,-0.932176,0.049913,0.214637,0.185097,0.364149,0.021616,0.274107,0.154324,-0.102365,-0.612323,-0.301749,0.065148,-0.032332,-0.278729,-0.011155,-0.250196,0.168085,-0.406008,0.364890,-0.075267,-0.526242,0.157790,-0.245235,0.486740,0.099327,0.315909,-0.157510,0.315811,0.227536,0.401364,-0.239007,0.193292,0.408291,-0.064533,0.055341,0.418126,-0.403370,-0.294593,0.472335,-0.444385,0.309936', '3736637', '1440164', '1780122', '1388219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30466931', '波斯语课', '剧情', '二战期间，犹太人吉尔斯在集中营谎称自己是波斯人保命，被一位德国军官看中要求教自己波斯语。对波斯语完全不懂的吉尔斯只能凭空编出一门语言，他开始用集中营中关押的犹太人的名字作为词根，编造出上千个“波斯语”单词，军官在残暴的环境中对吉尔斯竟有了依赖，并开始袒护他，不料集中营中来了一 个真正的波斯人……', '纳威尔·佩雷兹·毕斯卡亚特', '瓦迪姆·佩尔曼', 8.1, 312056, 'tt9738784', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2588101332.jpg', 0, 0.8, 16.7, 57.9, 24.6, '0.730157,0.190615,-0.575727,0.740903,-0.416163,0.034611,0.721750,-0.587469,-0.735999,-0.181030,0.227643,0.895787,0.100516,0.049744,0.124792,0.394801,-0.264573,-0.721736,-0.140232,-0.449497,-0.421543,-0.810301,-0.136239,-0.594072,-0.206957,-0.406700,0.132699,0.031724,-0.441635,-0.076600,0.117528,0.352247,0.297844,0.340272,-0.109975,0.018968,0.141275,-0.370325,0.321622,0.031901,-0.192768,-0.453222,-0.206333,0.225115,-0.193651,0.679403,0.590627,-0.510050,0.324297,-0.276611,0.195069,-0.196176,-0.314255,0.101448,0.321910,0.051485,0.291687,0.291663,0.097686,0.199838,-0.016636,-0.240903,-0.679688,0.050001,-0.003569,0.030516,-0.454453,0.449769,-0.215039,-0.205378,0.042641,-0.393712,-0.016462,-0.128857,0.344223,0.597486,-0.091120,-0.274531,-0.494622,0.294948,0.441350,-0.268875,-0.484124,0.270082,-0.415548,-0.660307,0.052355,-0.420168,-0.025698,-0.400298,0.115442,-0.343981,-0.248383,-0.027900,-0.578675,0.175508,-0.012989,-0.203824,0.068968,-0.349300,-0.160960,-0.207119,-0.152966,-0.213571,-0.205583,-0.038063,0.230130,0.144440,1.060930,-0.800871,0.050306,0.582309,0.241329,-0.279605,0.449703,0.296188,-0.148273,0.077113,-0.040880,0.286272,0.392143,0.306837,0.178230,0.313440,0.116009,-0.152747,0.006063,0.472585', '27602116', '24284209', '25932086', '1298468');
