INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30472643', '精灵旅社4：变身大冒险', '喜剧', '在精灵旅社125周年庆典派对上，一场意外使德古拉带领的精灵家族首次变身成人，而约翰尼则成了怪兽。为了寻找治疗方法，这对冤家翁婿前往危机重重的南美雨林开启了一场欢乐又刺激的冒险之旅，遭遇了种种令人捧腹的窘况。得知消息的梅菲斯带领精灵家族前去营救爱人和老爸，他们最终能否将一切恢复正常？', '布赖恩·哈尔', '德里克·德莱蒙', 6.3, 42749, 'tt9848626', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2870571717.jpg', 1.9, 14.2, 55.4, 22.4, 6.1, '-0.044457,-0.096481,-0.465299,0.306329,0.231601,-0.204616,0.336301,-0.032730,-0.661028,-0.011851,0.298796,0.908890,-0.349334,-0.056445,0.827317,0.004573,-0.648415,-0.379734,-0.009521,-0.078756,-0.203242,-0.333632,-0.186223,-0.495122,0.245656,-0.543315,0.590664,0.373876,0.015228,0.823890,0.350479,0.467471,-0.446850,0.282701,0.159057,-0.137602,0.184720,0.145008,-0.492090,0.345399,-0.080041,-0.158536,-0.089715,0.479700,0.214779,0.220425,0.776789,-0.586634,0.081529,-0.367306,0.132917,-0.474300,-0.024001,0.183874,0.603067,-0.092452,0.251713,0.350689,-0.106674,-0.180070,-0.135594,-0.455772,-0.700736,0.167914,0.370500,-0.057817,-0.427699,0.204771,0.161553,0.151440,0.181724,-0.112247,0.109078,0.873920,0.574669,0.319282,-0.110373,-0.115617,-0.292419,-0.004902,0.782376,-0.367389,0.123238,0.196849,-0.146591,-0.518899,-0.132175,-0.187375,-0.323570,0.008682,0.403048,0.212487,-0.176578,0.475747,-0.800524,-0.038088,-0.576161,-0.438162,0.044050,-0.245559,-0.072895,-0.833435,0.016208,0.159997,0.048110,0.042915,0.229537,-0.162421,0.494621,-0.793996,0.131862,0.481049,0.192908,-0.535547,0.538549,-0.015661,0.491833,-0.241901,0.023096,0.342692,-0.099652,0.463976,0.069784,0.134938,0.020414,0.082784,-0.211540,0.190341', '11541282', '3147969', '1968438', '1308754');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30475125', '担保', '剧情', '1993年，仁川，高利贷追讨者头石（成东日 饰）和宗培（金熙元 饰）想从明子（金允珍 饰）处拿回欠款，却因为明子的窘迫只得将她的女儿承利（朴昭怡 饰）带走作为担保。因为被人举报，作为非法滞留者的明子遭到驱逐，临行前拜托头石将承利送至其大伯处。本以为承利会被有钱人家收养的头石却发现承利被送到了不该她待的地方，他毅然决定把承利夺回…此去经年，正在中国作为中韩外交事务翻译的承利接到宗培的电话，得知了失踪已久的头石的讯息…', '成东日', '康大奎', 7.8, 20944, 'tt13273172', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2616180034.jpg', 0.5, 2.3, 26.2, 47.6, 23.4, '0.205905,0.285719,-0.367741,0.379029,-0.166835,-0.165204,0.387336,-0.022266,-0.651588,-0.372617,-0.113436,0.525782,0.043904,0.242687,0.348015,0.094111,-0.102347,-0.478297,0.005098,-0.337892,-0.196725,-0.278872,-0.066579,0.042511,-0.249979,-0.440588,0.341230,0.038829,-0.225694,0.390766,0.053350,0.596939,-0.183451,0.337037,-0.103925,0.192970,-0.203208,-0.011405,-0.122875,0.251639,0.021800,-0.492781,0.001568,0.105765,0.256405,0.533675,0.547414,-0.112879,-0.132541,-0.266656,0.263276,-0.304345,-0.057377,0.326726,0.074323,0.318414,0.226191,0.534356,-0.693427,0.112299,0.457799,-0.291491,-0.712518,0.015940,0.330717,-0.039942,-0.492116,0.368827,-0.351443,0.048075,0.041114,-0.518868,0.281843,0.408950,-0.149663,0.274751,-0.174454,0.001529,-0.389316,0.182036,0.502439,-0.359980,0.236418,-0.002853,0.450019,-0.429501,0.498348,-0.084989,-0.016252,0.147586,0.380607,0.107147,-0.075957,-0.198578,-0.335358,-0.387750,-0.249724,-0.063315,0.289639,-0.353197,-0.317894,-0.130800,0.050595,-0.364148,-0.094919,0.246750,0.136026,-0.107346,0.392348,-0.501773,0.295972,0.383734,0.364321,-0.586293,0.428316,-0.133216,0.022832,-0.088205,0.050310,-0.212735,0.501708,0.651682,0.183355,-0.106811,-0.116153,-0.596529,-0.103029,0.033377', '3811342', '26678784', '1295746', '1410695');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30475837', '杨之后', '剧情', '杰克（柯林·法瑞尔 Colin Farrell 饰）和卡雅（朱迪·特纳-史密斯 Jodie Turner-Smith 饰）收养了名叫美香的华裔小姑娘，为了美香能够接触属于自己种族的文化，杰克购买了仿生机器人杨（贾斯汀·闵 Justin H. Min 饰）。之后，杨成了美香最好也是最信赖的朋友，同时也成为了这个家庭里不可或缺的一份子。随着时间的推移，米卡渐渐长大，而杨也因为零件老化等问题，机能发生了故障。杰克想要找人修好杨，但因为杨是一款“二手”的机器人，所以自然没有任何的售后保障。杰克通过特殊的手段获得了记录了杨自出厂以来全部记忆的内存条，在播放这些画面的过程中，杰克发现了杨的一些不为人知的记忆。©豆瓣', '科林·法瑞尔', '郭共达', 7.4, 12166, 'tt8633464', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2867419800.jpg', 1.3, 5.2, 33.7, 41.7, 18, '0.253283,0.325548,-0.511893,0.677176,-0.129183,-0.514241,0.821820,-0.193743,-0.709669,-0.782942,-0.175695,0.289243,-0.080281,0.118162,0.071990,-0.214453,-0.399356,-0.507386,-0.006201,-0.248388,-0.764303,-0.605181,-0.187893,-0.492014,-0.351919,-0.207965,0.617875,0.005361,-0.251795,0.188667,0.282267,0.335071,0.177665,0.386515,-0.080125,0.116617,0.127466,-0.209688,-0.230890,0.172417,0.327493,-0.309912,0.332888,0.156225,0.214993,0.397861,0.815338,-0.236446,-0.050779,-0.033872,0.290400,0.056113,0.040529,-0.205257,0.192700,0.008457,0.137503,-0.205255,-0.314950,-0.098855,0.153805,0.140107,-0.813055,-0.215974,0.161680,0.209801,-0.511486,0.113967,-0.190568,-0.043706,0.054686,-0.462414,0.496895,0.481198,0.519024,0.181755,-0.187638,-0.001449,-0.369904,0.176838,0.303970,-0.109786,-0.380019,0.600690,-0.537948,-0.822054,-0.297065,-0.037615,-0.268822,0.065117,0.506779,0.202223,0.059322,0.287572,-0.710590,-0.184814,0.163885,-0.296025,0.050515,-0.403177,0.237559,-0.687933,-0.211148,-0.759452,-0.128330,-0.026174,-0.006920,-0.440024,0.835308,-0.844395,0.160326,0.191448,0.032894,-0.425287,0.406964,-0.319558,0.276765,-0.373464,0.155616,0.153590,0.242545,0.297649,0.152429,0.507050,0.213749,-0.347252,-0.201033,0.671317', '2053515', '6038071', '3262091', '26341137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30479644', '铁雨2：首脑峰会', '惊悚', '《铁雨2》将围绕韩半岛统一的各方势力各自不同的强硬立场展开故事。', '郑雨盛', '杨宇硕', 5.8, 20018, 'tt10516176', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2611996958.jpg', 6.9, 25, 45.4, 16.2, 6.6, '0.893312,0.395418,-0.739001,1.192897,0.540897,1.075196,0.280515,0.533638,-1.137505,0.257036,-0.367631,0.556508,-0.083675,-0.040679,0.300491,-0.685808,-0.304489,-1.145255,-0.520678,0.476959,0.074665,-0.880174,-0.146684,-0.607255,-0.519368,0.153945,0.450013,0.059748,-0.459362,0.422896,0.639713,0.231056,-0.944242,0.357504,0.235338,-0.277057,-0.283384,-0.162397,-1.071789,0.146811,-0.268473,-0.068394,0.231269,0.922973,0.016811,0.812250,1.121496,-0.591790,0.561132,0.084562,0.502491,0.052973,-0.026047,0.690097,0.759193,0.768317,-0.403465,0.316042,0.140418,0.251731,0.016845,-0.515067,-0.636083,-0.420228,0.957087,0.363594,-0.682579,0.868391,0.290891,-0.114662,-0.487971,0.115578,-0.003552,0.926319,0.321425,-0.220957,0.431633,0.120782,-0.295796,-0.271812,0.722176,0.537856,-0.247181,-0.536621,-0.375027,-0.271695,-1.043194,-0.537170,0.052199,-0.775288,0.212507,0.034093,0.603793,0.571900,-1.188841,-0.340678,0.248872,-0.650641,0.450556,-0.765812,0.535922,-0.751002,-0.229570,-0.371445,0.256904,0.331533,0.032198,0.527433,1.335490,-0.683545,-0.402215,-0.028034,0.830228,-0.717711,0.056876,0.073171,0.714824,-0.748129,0.100044,0.186255,0.339969,-0.036447,0.203011,0.128645,-0.393682,0.411599,-0.395193,0.253487', '25863940', '1296044', '2027899', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3047989', '风云决', '动作', '《风云决》（Storm Rider-Clash of Evils），改编自香港漫画家马荣成的漫画名作《风云》，制作历时5年。该动画由于其精湛的2D+3D制作水品和题材方面的突破获得了国内外的好评，至今仍为中国大陆公认的制作水品最高的2D+3D电影动画。步惊云（谢霆锋 配音）、聂风（任贤齐 配音）为报杀父深仇，合力斩杀火麒麟，吞下麒麟血，不惜以入魔为代价，将杀父仇人雄霸联手铲除。但聂风无法控制体内魔性，失手将云打落山崖……拜剑山庄为天下第一铸剑山庄，却被朝廷诬陷谋反而惨遭灭门。少庄主傲决（童自荣 配音）死里逃生，独自隐居西域，伺机复仇。当决得知风、云二人身负麒麟血，可为其祖传旷世神剑开封，遂开始苦苦寻觅两人踪影……其时，风、云各自有了心爱之人，过着远离江湖的平淡日子。然而，决的到来，注定将掀起一场血雨腥风……©豆瓣', '任贤齐', '林超贤', 7, 17945, 'tt2047732', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2227571255.jpg', 2.5, 10.1, 39.2, 28.9, 19.4, '-0.299606,0.368316,-0.404854,0.567801,0.631379,0.106357,0.109420,0.089832,-0.366761,-0.256939,0.122486,0.598582,0.012222,0.282482,0.151464,-0.171570,0.362159,-0.810716,-0.225612,-0.155545,-0.027648,0.047688,-0.330243,0.018401,-0.397878,-0.368397,0.821848,0.403665,-0.234484,0.311057,0.280869,0.206888,-0.442324,0.191816,-0.288733,-0.085648,-0.263635,0.093617,-0.465261,0.368886,-0.147280,-0.349919,-0.219373,0.205770,-0.108501,0.384691,0.468030,-0.069453,0.066901,-0.481062,0.533335,-0.398564,-0.111144,-0.131343,0.294129,0.278926,0.159036,0.448996,0.075894,-0.113359,-0.237849,-0.229334,-0.850343,-0.097275,0.472845,-0.149890,-0.475506,0.298214,-0.349865,0.159144,-0.410921,-0.055825,-0.067021,0.078513,0.462212,-0.008214,-0.174516,0.033033,-0.549455,0.404402,0.839481,-0.328284,0.040178,0.007011,0.602692,-0.146558,-0.079436,-0.705024,0.076594,-0.161543,0.430828,0.237801,0.168873,0.386996,-0.419430,-0.303820,-0.276588,0.124752,0.111730,-0.038968,-0.180477,-0.546836,-0.225213,-0.080255,-0.099617,-0.335025,0.318876,-0.545952,0.937540,-0.523544,0.030865,0.098645,0.027022,-0.505840,0.297340,-0.244725,0.097568,0.114196,-0.190443,0.466083,0.234369,0.163637,0.237782,0.024369,-0.044860,0.091208,-0.285279,0.258671', '27602116', '30391300', '3718665', '1438924')