INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30479973', '狗眼看人心', '剧情', '本片讲述了一桩因“狗咬狗”引发的连锁故事。余峰（黄磊 饰）、亮亮（闫妮 饰）、余一诺（安吉 饰）家的小狗妮蔻，为了救主人被隔壁藏獒咬成重伤，有权有势的藏獒主人却对余峰一家百般刁难。面对种种不公，余峰不再忍气吞声，发誓要为小狗讨回公道，但柴女士（汤唯 饰）等人的出现，却让矛盾进一步激化......狗生不易，小狗愿意用生命守护我们，我们又能为它做什么呢？', '黄磊', '吴楠', 5.5, 8194, 'tt10214198', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2551690865.jpg', 14, 25.1, 39.8, 15.3, 5.8, '0.052020,-0.049353,-0.285560,0.236063,-0.148396,-0.103847,0.630764,0.295044,-0.472862,-0.072260,0.169060,0.552572,-0.078857,0.033441,-0.175673,-0.106221,0.134846,-0.319199,0.416557,0.224824,-0.041040,-0.157086,0.088130,-0.304430,-0.046177,0.126441,0.179246,0.031495,0.010917,0.277569,0.230539,0.250471,-0.181334,0.014716,-0.084055,0.034917,-0.226928,0.179395,-0.317476,0.035902,0.149198,-0.145430,0.056215,0.321425,-0.107342,0.230916,0.396909,-0.376563,-0.344058,-0.486203,0.106084,-0.304527,0.313621,0.200222,0.050042,-0.221690,0.259787,0.158896,-0.225493,-0.080915,0.328602,-0.037439,-0.895591,-0.014484,0.067496,0.177353,-0.440850,0.218514,0.061125,0.174847,0.321873,-0.122077,0.110136,0.208717,0.601752,0.405037,-0.242112,0.177772,-0.629786,-0.025715,0.506333,-0.284838,0.309400,0.322058,-0.146125,-0.127181,0.291272,-0.227781,-0.587955,-0.089265,0.002980,0.148783,-0.222513,0.076108,-0.475716,-0.392363,-0.343656,0.052362,0.173524,-0.454935,0.023590,0.101895,0.058194,-0.236976,0.027013,0.279815,0.347052,-0.380533,0.479905,-0.615023,0.116267,0.436500,0.407947,-0.790372,0.453295,0.047525,0.218662,-0.207060,0.076555,-0.048783,0.194204,-0.072862,0.365519,-0.009604,0.462153,-0.084661,-0.217646,0.130051', '26678784', '1877596', '1302110', '35096844');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30481476', '国王理查德', '剧情', '该片剧本排2018年好莱坞“剧本黑名单”第二，讲述理查德·威廉姆斯的真实故事，这位精明务实、不屈不挠、没有任何网球背景的父亲培养 出了两个网球天才，她们后来成了超级巨星——维纳斯·威廉姆斯和塞雷娜·威廉姆斯(大威小威)。理查德·威廉姆斯为女儿们的职业网球生涯起草了一份78页的计划，女孩们在康普顿破旧、杂草丛生的公共球场上学会了这项运动。据报道，在那之前，她们的父亲与一些不喜欢这项运动、不肯让位的年轻硬汉发生了争执。威廉姆斯姐妹后来成为了网球史上最伟大的女选手之二。', '威尔·史密斯', '雷纳尔多·马库斯·格林', 7.5, 26404, 'tt9620288', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2690707256.jpg', 0.8, 3.8, 33.6, 46.1, 15.8, '0.251796,-0.254365,-0.642610,0.588437,-0.297075,-0.449501,0.216634,0.107409,-0.541012,-0.493216,0.193952,0.719333,-0.151555,0.113556,0.270639,-0.438429,-0.314810,-0.816895,-0.295263,-0.080680,-0.218644,-0.463182,-0.236774,-0.223624,-0.320517,-0.179366,0.695091,-0.300534,-0.380779,0.201213,0.288940,0.188239,0.416323,-0.304604,-0.297582,0.159062,0.441740,0.019055,-0.237337,0.218072,0.031496,0.066933,-0.282807,0.026974,0.229430,0.100428,0.426970,-0.110055,0.054422,-0.187318,0.601459,-0.026249,-0.208926,0.056258,0.488352,0.024831,0.154258,0.192464,0.215203,-0.010514,-0.248749,-0.359637,-0.890009,-0.036920,-0.175384,0.381137,-0.526399,0.478059,-0.417538,-0.145449,0.000030,-0.293057,0.078605,0.051513,0.259431,0.013482,0.009270,0.244444,-0.155193,0.520574,0.537768,0.244422,-0.251938,0.349420,-0.270877,-0.396950,-0.109939,-0.535299,-0.482702,0.269460,0.484774,-0.079123,0.071969,0.335362,-0.473704,-0.179448,0.027503,-0.303267,0.139047,-0.325879,-0.156649,-0.630774,-0.152060,-0.437979,-0.257028,-0.253630,-0.208322,-0.195372,1.293010,-0.881700,0.108614,0.524123,-0.288496,-0.487174,0.667273,0.264524,0.326934,-0.196539,-0.008489,0.126580,-0.012287,0.189606,-0.123193,0.625720,0.151106,-0.414311,-0.492805,0.424259', '27602116', '24284209', '25880986', '3072064');
