INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30482481', '我很在乎', '喜剧', '玛拉（裴淳华 Rosamund Pike 饰）经营着一家监护人公司，她专门寻找身体情况欠佳同时又无依无靠的老年人下手，通过并不是那么合法的手段令自己成为他们的法定监护人，将他们送进疗养院，之后便可接手和变卖他们的财产和房产，再将所得据为己有。某日，玛拉将下一个“吞噬”的目标放在了一位名叫珍妮弗（黛安娜·维斯特 Dianne Wiest 饰）的老太太身上，经调查，珍妮弗没有任何的亲人，同时又拥有着价值不菲的遗产，简直就是他们的最佳“肥羊”。在一番操作之后，珍妮弗被没收手机关进了疗养院，但此时的玛拉和她的恋人兼合伙人弗兰（艾莎·冈萨雷斯 Eiza González 饰）并不知道的是，她们惹上了一个不该惹，也不能惹的人。©豆瓣', '裴淳华', 'J·布莱克森', 6.3, 18745, 'tt9893250', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2630607691.jpg', 6.1, 15, 44.6, 25.9, 8.4, '0.515606,0.062598,-0.593684,0.635629,-0.446265,-0.330930,0.758337,0.232440,-0.498834,-0.145977,0.079540,0.902237,0.017844,0.271604,0.177647,0.362335,-0.218335,-0.690279,0.032878,-0.325665,-0.271598,-0.576033,-0.179510,-0.009809,-0.160663,-0.220835,0.513351,-0.150521,-0.301912,0.138419,0.303991,0.250419,0.028913,0.403248,-0.450928,0.039469,0.038781,-0.056038,0.025295,0.498800,0.167131,-0.284262,0.031895,0.343127,0.150328,0.385096,0.680779,-0.305952,-0.088846,-0.166004,0.248810,-0.212550,0.086620,0.184739,0.116900,-0.048713,0.239510,0.276001,-0.612863,0.042723,0.520649,-0.081489,-1.027804,-0.067880,0.158489,0.031069,-0.926390,0.294968,-0.351875,-0.116686,-0.169285,-0.411309,0.476343,0.441592,-0.048509,0.281499,-0.266073,-0.118469,-0.724798,0.160681,0.451008,-0.115081,0.102162,0.252460,-0.174110,-0.476339,0.004651,-0.270275,-0.309304,-0.163367,0.426560,0.354818,-0.022174,-0.052697,-0.604800,-0.040311,-0.413717,-0.522950,0.027318,-0.646934,0.072756,-0.537862,-0.142980,-0.344996,-0.525843,0.019880,0.322073,-0.310948,0.625499,-0.732958,0.012959,0.601493,0.444948,-0.553911,0.605304,-0.137996,0.340361,-0.120034,-0.187329,-0.225489,0.399440,0.509865,0.382039,0.377450,0.027411,-0.261366,-0.208856,0.438938', '1793491', '1783461', '1299932', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30482645', '数码宝贝：最后的进化', '动画', '2010年，曾经的小学生们已经步入大学，太一、阿和等人步上不同的人生道路（八神太一和石田大和将会成长为22岁），而就在此时，数码宝贝的研究者メノア(松冈茉优 配音)却告诉他们：“被选召的孩子们”长大成人后，数码宝贝也将随之消失…。预告中字幕表明这是“太一他们最后的故事” ，结尾则注明：献给所有和数码宝贝一起成长的“孩子”们，还有亚古兽注视着长大成人的太一的背影，“太一，你长大了呢”。', '花江夏树', '田口智久', 7.3, 87374, 'tt9507234', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2623955494.jpg', 1.5, 7.9, 34.7, 37.2, 18.8, '0.465375,-0.240235,-0.655007,0.636336,-0.080369,-0.483537,0.759778,-0.213269,-0.537507,-0.110204,-0.093942,0.973132,-0.342638,0.685951,0.339628,-0.190004,-0.412435,-1.048654,-0.413520,-0.312047,-0.587420,-0.477879,0.049773,0.083121,-0.328614,-0.270010,0.946627,-0.162252,0.181487,0.768562,0.379102,-0.079818,0.005835,0.178566,-0.370717,0.361557,-0.241318,0.059217,0.178963,0.078850,-0.001864,-0.318727,-0.173872,0.018687,0.030145,0.076537,0.968129,-0.473585,0.141562,-0.342094,0.191334,-0.491706,-0.291613,0.406920,0.192639,0.070115,0.165205,0.427932,-0.116693,0.026072,-0.366170,-0.247844,-0.934556,0.051485,-0.044630,0.243400,-0.752306,0.091751,0.242905,-0.172475,0.410418,-0.350540,0.472753,0.526787,0.245417,0.735597,-0.428565,-0.019542,-0.203916,0.147850,0.484179,-0.014398,-0.220442,0.153537,-0.172330,-0.643557,-0.364912,0.023816,-0.465538,0.126944,0.126321,0.494821,-0.212335,0.397587,-0.608940,-0.146761,0.110542,-0.668233,0.046988,-0.654288,-0.202018,-0.541900,-0.050405,-0.660873,-0.461362,0.364729,0.005057,-0.287895,1.339295,-0.975152,0.282688,0.009900,0.556128,-0.473483,0.901658,0.083022,0.320726,-0.123982,0.050055,-0.010912,-0.179548,0.272813,0.349016,0.361540,-0.111064,0.028319,-0.715336,0.539917', '1307146', '3811356', '27602116', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30484534', '摇滚红与黑', '剧情', '音乐剧《摇滚红与黑》改编自法国著名作家司汤达的名著《红与黑》。于连（Côme 饰）是木匠的儿子，出生于贫困的家庭之中。做梦都想要跨越阶级跻身名流的他得到了一个机会，来到了市长家成为了那里的家庭教师。就此，于连结识了市长夫人德瑞那（Haylen 饰），德瑞那是一个内心里崇尚自由的女子，却被婚姻所舒服，粗俗浅薄的市长带给她的只有痛苦。这时，于连出现了。于连和德瑞那之间的感情犹如干柴遇见了烈火，立刻熊熊燃烧起来，但没过多久，他们的恋情就败露了。之后，于连经由德瑞那的介绍，来到了侯爵家做秘书，在这里，对感情心灰意冷的于连邂逅了侯爵千金马蒂尔德，马蒂尔德是一个心高气傲的姑娘，对于连忽冷忽热，搅得他心神不宁。之后，于连略施小计最终获得了马蒂尔德的芳心，不仅如此，马蒂尔德的腹中还怀上了他的孩子。©豆瓣', 'Côme', 'François Chouquet', 9.2, 16125, '', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2550176123.jpg', 0.2, 0.5, 5.6, 27.8, 66, '0.305900,0.065256,-0.890318,0.513816,0.106403,-0.561935,0.620742,0.176845,-0.872367,-0.243691,-0.160285,0.972549,-0.472209,0.165233,0.578739,-0.129027,-0.155473,-0.729028,-0.129711,-0.055157,-0.083127,-0.441091,-0.202802,-0.296779,-0.343699,-0.359641,0.288984,0.152237,-0.068192,0.315134,0.424593,0.541055,0.190083,0.146118,-0.387730,0.331356,-0.013642,-0.092664,-0.490918,0.322733,0.178421,0.105262,0.073342,-0.133719,0.092959,0.194617,0.367100,-0.395928,-0.066975,-0.273624,0.345249,-0.046292,-0.038279,0.159710,0.029564,0.057374,0.295871,0.190468,-0.244854,0.079439,0.429458,-0.116108,-0.697603,0.115532,0.252232,0.354828,-0.650838,0.547676,-0.097278,-0.282700,-0.157792,-0.209475,0.394177,0.144268,-0.039313,0.399909,-0.196956,0.060630,-0.777911,-0.061408,0.726412,0.277965,-0.537594,0.265658,-0.215839,-0.368366,0.053342,-0.380285,-0.417427,0.064919,0.131672,0.274164,-0.056617,0.264586,-0.568256,-0.262406,-0.313490,0.067892,0.159730,-0.412436,-0.302992,-0.138205,-0.103891,-0.522035,-0.257361,0.065235,0.052503,-0.113824,0.637943,-0.897361,0.158053,0.114173,0.445348,-0.267116,0.715799,0.068375,0.276867,0.266767,0.003740,0.059133,0.006304,0.406562,0.330320,0.441667,-0.097180,-0.231110,-0.102596,0.377712', '1783461', '25721544', '34968329', '1303449');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30487597', '棕榈泉', '喜剧', '奈尔斯（安迪·萨姆伯格 Andy Samberg 饰）和女友的感情之路早已经走到了尽头，可即便如此，他还是勉强跟着她去参加了一场婚礼。婚礼现场，谁也不认识的奈尔斯百无聊赖，一个名为萨拉（克丽斯汀·米里奥蒂 Cristin Milioti 饰）的放荡不羁的女孩吸引了奈尔斯的注意。萨拉是新娘的姐姐，实际上，她和新郎长期保持着肉体关系，就连新婚前一晚，她都是在新郎的床上度过的！这样一个令全家人都感到头疼的姑娘，在奈尔斯的眼中却显得格外有吸引力，在同女友分手后，奈尔斯和萨拉渐渐走到了一起。萨拉泼辣的个性给奈尔斯的生活带来了惊喜，却也制造了种种麻烦，当奈尔斯发现自己真的深深地爱上了萨拉时，后者却不告而别。©豆瓣', '安迪·萨姆伯格', '马克斯·巴尔巴科夫', 6.7, 12662, 'tt9484998', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2605116792.jpg', 1.2, 7.7, 51.7, 31.4, 8.1, '0.456498,0.082189,-0.555864,0.259840,0.013863,-0.317876,0.825268,0.369841,-0.534006,0.127181,0.250214,0.757774,-0.143682,0.246957,0.650289,0.335890,-0.505718,-0.666673,0.004446,0.124397,-0.227874,-0.624871,-0.183904,0.150527,-0.041034,-0.529303,0.384193,-0.196706,0.278384,0.819665,0.167949,0.047263,-0.010749,0.680762,0.197526,0.177601,0.270141,-0.092937,0.148595,0.204602,0.027908,0.082358,-0.211701,0.329067,0.214272,0.476861,0.131290,-0.055230,-0.034850,0.086112,-0.010084,-0.081983,0.104320,0.474681,-0.159773,-0.622252,0.180138,0.109081,-0.503413,-0.207690,0.061447,0.321073,-0.625282,0.356405,0.131146,0.358989,-0.726737,0.531510,-0.477061,-0.593610,0.109980,-0.318182,-0.165975,0.521592,0.057210,0.289462,-0.110592,-0.087268,-0.441469,-0.207308,0.612463,0.449861,-0.185677,0.252937,-0.294856,-0.156014,-0.404804,0.090906,-0.571914,-0.193004,0.177752,0.009992,-0.053679,0.499193,-0.842032,-0.134528,-0.360768,-0.047960,0.030300,-0.543978,-0.068016,-0.395049,-0.019611,-0.450723,-0.610972,-0.091739,-0.008215,-0.274691,0.455653,-0.892560,0.449332,0.672946,0.363975,0.119643,0.643050,0.315309,-0.003948,-0.138593,-0.051503,0.379346,-0.123175,0.099484,0.314192,0.708437,0.405213,-0.223406,-0.522671,0.694618', '1309172', '3111650', '24698878', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30488003', '致允熙', '剧情', '电影讲述收到初恋的信的女主人公“允熙”(金喜爱 饰)为寻找遗忘的记忆而离去的故事。金喜爱饰演本片的女主人公，寻找深埋心底的初恋的“允熙”，日本演员中村优子饰演允熙的老朋友，允熙的女儿由I.O.I出身的金素慧饰演，通过多部作品展示不俗演技的成侑彬饰演允熙女儿的男朋友。', '金喜爱', '任大炯', 8.3, 35098, 'tt11311974', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2571774021.jpg', 0.5, 1.4, 16.6, 46.8, 34.8, '0.033095,-0.354161,-0.142623,0.976425,0.067664,-0.162950,0.630940,0.172971,-0.091990,-0.590508,0.341016,0.778677,-0.236982,0.302911,0.583969,-0.087151,-0.415476,-0.500836,-0.347491,0.177999,0.357030,-0.188548,-0.102428,0.156482,-0.113299,-0.421000,1.284537,-0.155682,-0.295147,0.505393,0.729250,0.566057,-0.406264,-0.426408,0.333732,0.455199,-0.101168,0.311121,-0.324983,0.308549,-0.006803,-0.069140,-0.029680,-0.062482,-0.222536,0.478284,0.921337,0.114992,0.061521,0.116470,0.936158,-0.353084,-0.109101,-0.103197,-0.067386,0.392264,0.373770,0.137426,-0.053703,-0.026714,-0.067640,-0.212079,-0.894412,-0.275769,0.657876,0.114756,-0.201365,0.076220,-0.027625,0.212015,0.425491,-0.125001,0.070304,-0.186457,0.338088,0.385651,-0.220290,0.340895,0.055045,0.871080,0.163990,0.004299,0.183111,0.662267,-0.194081,-0.472562,-0.046682,0.013839,-0.956689,0.397359,-0.053205,0.157788,-0.209799,0.004659,-0.178264,-0.507367,-0.020908,-0.018970,0.610328,-0.603157,0.013023,-0.963572,-0.633102,-0.172196,0.227854,-0.471083,0.059082,-0.510442,1.209987,-0.551153,-0.086806,0.418456,-0.153900,-0.512735,0.862292,0.244902,-0.324689,-0.551934,0.007767,0.558174,0.167750,-0.501363,-0.481898,0.094464,-0.385923,-0.456991,-0.937194,0.174758', '1322847', '25880986', '22265121', '26759820');
