INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('30489388', '蛛丝马迹', '剧情', '克恩郡巡警乔狄肯，小名狄克（丹泽尔·华盛顿 饰），被派往洛杉矶进行本该是趟简单明快的证据收集任务。取而代之的是，他被卷入一场缉捕正肆虐该市的连环杀手之行动。领导缉捕的是洛杉矶郡警长吉姆贝克斯特（拉米·马雷克 饰），对狄克的警察直觉大为惊艳，因而私自寻求他的协助。但在两 人追踪主要嫌疑人艾伯特史帕玛（杰瑞德·莱托 饰）时，贝克斯特浑然不觉该调查勾起了狄克对过去不愉快的回忆，随之出土的黑暗秘密除了威胁案件调查外，可能牵连更剧。', '丹泽尔·华盛顿', '约翰·李·汉考克', 6.5, 10235, 'tt10016180', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2628906317.jpg', 1.7, 11.3, 54, 26.4, 6.6, '0.408078,-0.323612,-0.532007,0.405285,0.085549,-0.008590,0.370245,0.163236,-0.704617,-0.180015,0.208472,0.322780,-0.034569,-0.205056,0.396534,0.037797,-0.318161,-0.565242,0.036503,-0.204954,-0.226524,-0.653434,-0.216521,-0.554634,0.225250,-0.265488,0.197461,0.327605,-0.261230,0.288869,0.365437,0.734688,-0.396615,0.487285,0.114082,-0.171949,0.368694,-0.371632,-0.251522,0.195699,0.191450,-0.266613,-0.226239,0.136768,-0.053827,0.697790,0.578194,-0.182585,-0.101930,-0.093962,0.076122,-0.467772,0.023789,0.110240,0.230603,0.021009,-0.152990,0.516570,-0.123582,-0.215234,0.110882,-0.074547,-0.558643,0.116175,0.173072,0.427527,-0.302863,0.276983,-0.375235,0.222035,0.005494,0.007864,0.208523,0.347296,-0.115029,0.111619,0.322513,-0.099586,-0.381139,0.147436,0.387714,-0.265075,-0.042501,0.153239,-0.330448,-0.357813,-0.052828,-0.192943,-0.021355,0.054691,0.417191,-0.006734,0.175715,0.129164,-0.477678,-0.262141,-0.387501,-0.261795,-0.278770,-0.351258,0.082542,-0.724434,0.029642,-0.162819,-0.349246,-0.084128,0.115386,0.057715,0.158169,-0.770854,-0.008684,0.755441,-0.023060,-0.523246,0.335246,0.152930,0.044955,-0.509116,-0.160441,0.043611,0.401710,0.216871,0.195967,0.197936,0.241550,-0.564045,-0.214189,0.106768', '1307442', '2352630', '1867415', '1293823');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3053397', '蜡笔小新之电击！猪之蹄大作战', '喜剧', '某日，双叶幼稚园的孩子们正在船屋里愉快的玩耍，一位名叫美色（三石琴乃 配音）的神秘人物忽然现身，紧接着，一艘巨大的飞船将船屋整个抓了起来，来不及逃跑的风间（真柴摩利 配音）和小新（矢岛晶子 配音）等人和飞船一起消失在了空中。小新的失踪令美伢（楢桥美纪 配音）和广志（藤原启治 配音）感到十分焦急，就在此时，一名代号肌肉（玄田哲章 配音）的男子出现在了两人的身边，很显然，肌肉知道小新的下落和整件事情的来龙去脉，但肌肉并不愿意带着美伢和广志去寻找小新。追寻着细微的线索，美伢和广志得知小新身在香港，两人前往香港，在那里又遇见了肌肉，一行人前往神秘组织“猪蹄组”的老巢。©豆瓣', '矢岛晶子', '本郷みつる', 8.2, 6383, 'tt2643808', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2609958372.jpg', 0.3, 1.3, 19.9, 42.7, 35.8, '0.225110,-0.207450,-0.844107,0.454350,-0.018696,-0.208290,0.768168,0.293554,-0.383221,-0.260461,0.114931,0.730774,-0.246737,0.375126,0.184747,0.285382,-0.251827,-0.587978,-0.132254,-0.048693,-0.361617,-0.287851,-0.040308,-0.021591,-0.068848,-0.321638,0.401558,-0.074385,-0.052810,0.896574,0.399736,0.193521,-0.592664,0.312533,-0.238311,0.102082,0.252336,0.002928,0.117227,-0.019090,-0.180273,-0.116302,-0.192753,0.044195,0.066791,0.226383,0.760339,-0.006264,-0.086481,0.070413,-0.057411,-0.172703,-0.043896,0.050038,0.569929,0.058226,0.252701,0.111205,-0.354573,0.076978,0.151256,0.138564,-0.669872,0.226311,0.062339,0.662706,-0.423682,0.129039,-0.145609,-0.255774,0.323753,-0.602899,0.326672,0.325625,0.135369,0.250719,-0.241464,0.312787,-0.416064,0.009929,0.479250,0.171885,0.023635,0.263564,0.240620,-0.371446,-0.315592,0.271722,-0.137737,-0.196002,0.278491,0.106667,-0.426056,-0.063016,-0.511221,0.109698,-0.031733,-0.366741,-0.117083,-0.384851,-0.275472,-0.817544,-0.141951,-0.354378,-0.103291,0.334450,-0.020633,-0.002336,0.772867,-0.856554,0.120025,0.489303,0.211787,-0.134469,0.478099,0.087223,0.038096,-0.123483,-0.023759,-0.247738,0.120584,0.296790,0.234225,0.682283,-0.302901,-0.209378,-0.787943,0.145375', '3811356', '2357711', '25723081', '34429100');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3053521', '二十四城记', '剧情', '曾经的繁华荣耀，随着时光流转与时代变迁渐渐褪去耀眼的光环，留下的则是无尽的落寞与慨叹。420厂（成华集团），一座从东北迁至四川的飞机军工厂，在特殊的年代里它曾是无数人羡慕与自豪的所在，然而和平的气息和体制改革却将它的光鲜逐渐销蚀。经济浪潮的冲击下，它不可避免地经历了转型的阵痛，而今旧厂址易作他主，一片现代化的楼宇将拔地而起。大丽（吕丽萍 饰）、小花（陈冲 饰）、娜娜（赵涛）以及众多新老员工见证了厂区几十年的变迁。斗转星移，沧海桑田，万千唏嘘连同那旧日回忆随风飘散……©豆瓣', '吕丽萍', '贾樟柯', 7.4, 39582, 'tt1103963', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2567418569.jpg', 1.2, 5.1, 32.7, 45, 16.1, '0.106756,0.282352,-0.743378,0.619514,0.145907,-0.181437,0.797185,0.265805,-0.564492,-0.121416,0.217787,0.432402,-0.120356,0.267536,0.060728,-0.117036,0.068855,-0.744535,-0.185191,-0.227951,0.008914,-0.272328,-0.560599,0.011532,-0.063330,-0.269860,0.893120,0.626524,-0.123523,0.541393,0.132824,0.131888,-0.419418,0.332264,-0.410827,-0.091383,-0.135046,0.249011,-0.345695,-0.391824,-0.262564,-0.644983,0.015395,-0.115848,-0.256963,0.195003,0.752111,-0.081770,0.033085,-0.084042,0.441133,-0.026040,-0.179702,0.186574,0.073725,0.344550,-0.106364,0.193913,-0.359692,-0.396908,-0.081467,-0.134346,-0.681539,-0.025996,0.063744,0.234410,-0.555214,0.656126,0.171724,-0.314297,-0.032055,-0.232592,0.484727,0.172973,0.088395,0.771354,-0.178463,0.118330,-0.209284,0.537781,0.650532,0.104655,-0.474084,0.228534,-0.491591,-0.011247,-0.326256,0.052707,-0.523869,-0.294805,0.232550,0.277451,0.136995,0.644623,-1.214400,0.236582,-0.139709,-0.478081,-0.025646,-0.201608,-0.213734,-0.475285,-0.378798,-0.663261,-0.148347,-0.005349,0.086641,0.026732,0.710779,-0.763318,0.237613,0.066968,0.251677,-0.158530,0.512915,-0.334834,0.180231,-0.176439,-0.070319,0.358549,-0.214128,0.496304,0.088507,0.514415,-0.311603,-0.010247,-0.576416,0.486036', '26290398', '1299261', '20020577', '5361544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3054944', '蜡笔小新：爆发！温泉火热大决战', '喜剧', '某日，小新（矢岛晶子 配音）、小葵和美伢（楢桥美纪 配音）被一群神秘人物绑架，醒来之后发现身处一间神秘的基地之内，原来，这里是名为“温泉G组”的秘密组织，意在保护对于日本来说十分珍贵的温泉。然而，横空出世的污垢达人博士（家弓家正 配音）企图利用“地球温泉计划”将温泉G组彻底击垮。唯一能够阻止污垢达人博士的阴谋的，就只有仅存在于传说之中的“黄金之魂温泉”，而组员们经过调查，发现该温泉正好处于小新他们家地下。小新一家人决定帮助温泉G组的同胞们找到黄金之魂温泉，却遭到了污垢达人博士的袭击，并且最终沦为俘虏遭受了酷刑。©豆瓣', '矢岛晶子', '原惠一', 7.9, 7547, 'tt2643818', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1379342162.jpg', 0.5, 2.6, 28, 39.2, 29.7, '0.076623,0.081891,-0.500994,0.131821,0.156577,0.045967,0.319069,0.252027,-0.785858,-0.637065,0.294141,0.298487,0.074404,0.152823,0.167292,0.056088,-0.302851,-0.437904,-0.393411,-0.261300,-0.506750,-0.197690,-0.204926,0.009198,0.130503,-0.377872,0.626591,0.229415,-0.261153,0.115538,0.049066,0.595074,-0.356423,0.318655,-0.006639,-0.256913,0.533788,-0.244143,-0.318270,0.460944,-0.397358,0.167625,0.229654,-0.045432,-0.059724,0.086503,0.818495,-0.320623,-0.314277,-0.342342,0.198717,-0.391814,-0.156991,0.028347,0.596660,-0.047739,0.274097,0.316569,-0.103613,-0.128179,0.357690,-0.271690,-0.767947,0.026843,0.292554,0.131281,-0.059026,0.083853,0.240206,-0.050749,0.148466,0.013984,0.321085,0.081418,0.529405,0.264285,-0.240650,0.102061,-0.512878,-0.141811,0.588336,-0.309438,0.128474,0.186785,0.068940,-0.390960,0.112384,-0.201912,0.124569,0.236328,-0.126138,0.413806,-0.247254,-0.100968,-0.774608,0.034624,-0.495087,-0.201263,0.171479,-0.281742,-0.274994,-0.796114,-0.151831,0.367783,-0.297505,0.028054,0.073844,-0.165181,0.657366,-0.682041,0.190361,0.501401,0.259777,-0.284656,0.635555,-0.284096,-0.113713,-0.252392,-0.039231,0.402288,0.193581,0.392383,-0.066634,0.256568,-0.306814,-0.459140,-0.432588,-0.054325', '2369613', '1307897', '1306809', '5384590');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3055049', '动物园看守', '喜剧', '影片中出现的大象泰，还出现在了《大象的眼泪》一片中。影片中出现的长颈鹿Tweet曾经出现在金·凯瑞的代表作《神探飞机头》之中。富兰克林公园动物园是波士顿当地的一家著名的动物园，1913年开业，占地72英亩。在富兰克林公园动物园，一群动物们都很爱他们好心的饲养员Griffin Keyes（凯文·詹姆斯 Kevin James），但他们发现他和狮子在一起比跟姑娘在一起相处融洽。Griffin觉得他找到人生另一半的唯一机会就是另找一个体面的工作，此时动物们都很伤心，他们决定向Griffin展示他们的秘密：他们能说人话！为了Griffin不要离开，他们当上了他的求爱老师，可惜是以动物的方式……©豆瓣', '凯文·詹姆斯', '沃尔特·拜克', 6.3, 10297, 'tt1222817', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1031784300.jpg', 2.2, 13.8, 55.9, 22.9, 5.2, '0.367148,-0.226808,-0.818962,0.656234,-0.056300,-0.163958,0.947070,-0.061854,-0.404011,-0.149622,0.148981,0.902420,-0.306521,0.518411,0.077614,-0.144621,-0.369366,-0.577884,-0.052301,-0.159124,-0.190340,-0.283645,-0.219201,-0.431949,-0.040047,-0.000980,0.442608,-0.021511,0.034906,0.420277,0.130195,0.010245,-0.104749,0.244704,-0.475397,-0.035320,0.046852,0.025870,-0.205200,0.219942,-0.003909,0.107014,-0.191730,0.009789,0.167195,0.048147,0.751787,-0.291425,-0.234229,-0.005926,0.140663,-0.226361,0.135126,0.163164,0.412541,-0.269809,0.398878,0.014353,-0.051047,0.089606,0.015092,-0.072641,-0.683583,0.151998,-0.155537,0.416228,-0.571536,0.366426,0.361516,-0.078667,0.178630,-0.436131,0.316459,0.068356,0.251185,0.379133,-0.123337,0.121915,-0.778010,0.016949,0.864888,-0.020844,-0.039362,0.269482,-0.236514,-0.593890,0.141085,-0.104760,-0.316966,-0.017212,0.218489,-0.278974,-0.396052,-0.052846,-0.799227,0.108119,0.019547,-0.447030,-0.179532,-0.413187,-0.065737,-0.683779,0.090447,-0.563565,-0.319537,0.152058,0.009565,-0.413742,0.716672,-0.946182,0.091938,0.519533,0.484761,-0.403059,1.168125,0.039616,-0.086343,-0.125605,-0.157307,0.021138,0.020677,0.215525,0.275922,0.223534,-0.007599,-0.225567,-0.524992,0.610745', '1302384', '1296538', '30162520', '1917323');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3055303', '蜡笔小新：呼风唤雨！战国大合战', '动画', '某一晚，野原一家同时梦见了古装剧里才会出现的”古代美女”，虽然全家人都觉得很不可思议，却也没有深入追究。当天下午小新从幼儿园回来时，看到小白正在庭院里拼命挖洞，而当小新也跟着开始挖掘后，竟然挖出了一个箱子，里面放有小新亲笔写的书函，除了写有天正2年的字眼外，还画有肥嘟嘟左卫门的图案。小新由于摸不着头绪而闭上眼睛思考，却在睁开眼时发现自己已经身处在一个战国时代，并阴错阳差救了武士，更因此得以见到了梦中的那位美女”阿廉公主…', '矢岛晶子', '原惠一', 9.1, 17572, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2618853312.jpg', 0.1, 0.5, 7.4, 30.3, 61.8, '0.202964,-0.024770,-0.711034,0.360100,0.187003,-0.508020,0.827503,-0.048503,-0.693859,-0.483423,0.164483,0.567822,-0.407332,0.488300,0.199034,0.064513,-0.497305,-0.618910,-0.030124,-0.318476,-0.532619,-0.258384,-0.249366,-0.081894,-0.095231,-0.182089,0.409023,0.094570,-0.114977,0.390237,0.105396,-0.422984,-0.215275,0.718540,-0.185807,-0.002942,0.043277,0.346870,0.369326,0.107350,0.151681,-0.429645,-0.274003,0.047885,0.091104,0.390023,0.636499,-0.574210,-0.128892,-0.035047,0.172414,0.074444,-0.413736,0.056176,0.358191,0.043710,0.258231,-0.211510,-0.207864,-0.002443,0.031454,-0.104553,-0.500676,0.189789,0.050123,0.388541,-0.416123,0.214483,0.131934,-0.102748,0.291389,-0.553488,0.256397,0.261255,0.199837,0.368256,-0.239428,-0.026343,-0.456008,0.001279,0.178584,-0.093670,-0.026130,0.614352,0.061303,-0.485678,0.260188,0.109938,0.021611,0.091234,-0.003312,0.380604,-0.423470,-0.147228,-0.509029,0.285373,-0.223575,-0.213952,0.071439,-0.232380,-0.431292,-0.344275,-0.029624,-0.079273,-0.097264,0.421716,-0.067879,-0.224850,0.521229,-0.742022,0.231907,0.167774,0.178642,-0.011782,0.707423,-0.127287,-0.288014,0.091412,-0.098765,0.044359,-0.121737,0.602262,0.050127,0.319135,-0.223750,-0.514453,-0.439832,0.347453', '21348112', '35073565', '4724373', '27617348');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3055450', '看不见的世界', '剧情', '五十年代的南非，正是种族隔离制度执行时期。影片讲述在这样特别的时代下，妇女米里亚姆（丽莎·蕾 Lisa Ray饰）与妇女阿米拉（茜多·塞丝 Sheetal Sheth饰）之间的特别情感。米里亚姆的婚姻生活并不幸福，她发现丈夫与其大嫂偷情，唯有隐忍。直到一身牛仔打扮的阿米拉出现在她压抑恪守的生活中，两个美丽的女人一见钟情。拥有反抗精神的阿米拉是坚决反对种族隔离制度的人，这也正是吸引米里亚姆的地方。两个女人之间这微妙而细腻的情感，都在指尖的每一次轻佻中，在眼神的每一次凝视里。她们超越的不仅是性别的屏障，还有种族的阻隔。本片由导演谢米姆·萨尔弗根据自己创作的同名小说改编拍摄而成。©豆瓣', '丽莎·蕾', '谢米姆·萨尔弗', 8.2, 19349, 'tt1048174', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1005179057.jpg', 0.2, 1.4, 18.1, 46.2, 34.1, '0.359922,-0.100049,-0.739987,0.825840,-0.018451,-0.221859,0.992174,0.093964,-0.237936,-0.247481,0.221221,0.337381,-0.216364,0.035280,0.289340,-0.011179,-0.408734,-0.791864,-0.193702,-0.192214,-0.212680,-0.342412,-0.195062,-0.095029,-0.226185,-0.558987,0.646591,-0.030906,-0.316093,0.257710,0.318544,0.229550,-0.080874,0.327808,0.092179,-0.102363,0.220783,-0.051233,-0.163341,0.001087,0.067905,0.029065,-0.072564,0.259518,-0.146380,0.387270,0.657008,-0.612625,0.076929,0.038493,0.468746,0.137824,-0.126226,-0.032114,0.038118,-0.183557,0.282959,0.072032,-0.020484,0.053011,0.143473,-0.165148,-0.548641,-0.002171,0.233297,0.456990,-0.453047,0.366786,0.064834,-0.204144,0.050697,-0.289551,0.033128,0.077569,0.403218,0.543649,-0.033363,0.031953,-0.287056,0.152687,0.520309,0.196562,-0.546864,0.262012,-0.824967,-0.489233,0.024094,-0.190544,-0.597970,-0.009833,-0.006126,-0.125657,0.056847,0.563122,-0.665726,0.102828,-0.013006,0.083135,0.044771,-0.509721,0.049265,-0.719521,-0.369629,-0.738658,-0.251173,0.152630,0.044045,-0.393249,0.637663,-0.703625,0.337358,0.373716,0.356638,-0.240198,0.649946,0.180134,0.106538,-0.211629,-0.289945,0.530204,-0.001678,-0.169828,-0.121933,0.531446,0.013529,0.160397,-0.392593,0.710731', '1299261', '6021916', '3097044', '1417428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3056455', '蜡笔小新：呼唤传说！三分钟嘎巴大进攻', '剧情', '突然出现在野原家面前的时间和空间调查员,说时空发生了扭曲，不应存在的怪兽从怪兽的世界进入了现实世界。怪兽出现3分钟后。3分钟后的未来那个怪兽不被打倒,在现实里怪兽要出现！为了抵御世界灭亡，野原一家担任了地球防卫这个重大使命。但是，连续不断强大的怪兽从后边开始出现，渐渐现实世界变得危险…', '矢岛晶子', '武藤裕治', 7.9, 7423, 'tt2643846', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2495956986.jpg', 0.7, 4.1, 27.6, 37.3, 30.4, '0.127186,0.895479,-0.950253,0.458992,-0.193700,0.432475,1.038437,0.037131,-0.241262,-0.159789,0.255526,0.895616,-0.352974,-0.154519,0.247319,-0.116190,-0.033259,-0.697193,0.115562,-0.375552,-0.617788,-0.175552,-0.280156,-0.593614,0.045720,-0.570291,0.683955,0.461424,-0.165967,-0.103183,-0.211007,0.405278,-0.391390,0.703782,-0.127115,-0.082387,0.338382,0.230502,-0.173715,0.385947,-0.167531,0.025411,0.296889,0.112291,-0.477437,-0.193752,0.818232,-0.465430,-0.480662,-0.340155,0.527219,-0.265187,-0.578940,-0.149399,0.897528,-0.391366,-0.254605,-0.137737,0.140230,0.092497,-0.192134,-0.220597,-0.728949,-0.043593,-0.367001,0.367639,-0.137933,0.145889,0.027177,0.013460,0.066830,-0.197547,0.440962,0.722199,1.043378,0.207720,-0.222353,0.309992,-0.474922,-0.359265,0.645202,-0.515470,-0.915655,0.427366,-0.177168,-0.393401,-0.584029,-0.044393,-0.414150,-0.058644,0.337021,0.563905,-1.009655,0.584165,-0.906276,0.173279,-0.239486,-0.482083,-0.032628,-0.458467,-0.821065,-0.198158,-0.446943,-0.175427,-0.104117,0.283387,-0.198759,-0.170442,0.706313,-0.841724,0.328876,0.622504,0.654381,-0.144499,0.830338,-0.288705,0.083442,-0.425012,0.728146,0.157815,-0.032461,0.743895,0.129953,0.409200,-0.252541,0.193973,-0.335856,0.795040', '2377539', '10581450', '20451118', '25884436');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3057495', '布鲁克林警察', '剧情', '故事发生在布鲁克林恶名昭彰的布朗斯维尔区，埃迪·杜根（理查·基尔 Richard Gere 饰）是一位还有一个星期便可退休的老警察，二十多年的职业生涯让他看透了肮脏的社会规则，只求顺利退休，别节外生枝。然而事与愿违，他被分配负责监督一名新丁上岗，似乎每个初当警察的小伙子都有着拯救世界的固执，这令埃迪乏力厌恶。萨里（伊桑·霍克 Ethan Hawke 饰）是一名领着普通薪水的纽约警察，拥有好几个孩子的他却仍然与妻子住在狭窄的黑人区，受尽奚落，为了筹钱买房，他开始打起警局缴获赃款的主意。而谭戈（唐·钱德尔 Don Cheadle 饰）则是警方派到毒贩集团的卧底，在完成最后一个任务后便可得到他梦寐以求的一份文员工作，然而这次任务的对象却是曾经救过他一命的毒贩卡兹（韦斯利·斯奈普斯 Wesley Snipes 饰），谭戈陷入两难抉择。意想不到的是，命运却将这三个无助的人引向了同一点……', '理查·基尔', '安东尼·福奎阿', 7.4, 8260, 'tt1210042', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p504410555.jpg', 0.5, 2.9, 34.6, 50.8, 11.2, '0.087025,-0.016824,-0.429052,0.459933,-0.626365,-0.469785,0.667243,0.074039,-0.423016,-0.293448,0.178783,0.660749,0.136331,0.266270,0.335683,-0.066351,-0.159937,-0.563228,-0.017561,-0.118162,-0.248058,-0.529093,-0.152079,-0.357401,-0.107840,-0.215606,0.526814,0.221145,-0.037104,0.089879,0.469614,0.382827,-0.114774,0.369086,-0.242227,-0.028591,0.333649,-0.134313,-0.260546,0.077415,0.043573,-0.106435,-0.227581,0.168482,0.113877,0.451243,0.453578,0.143959,-0.257707,-0.025566,0.368470,-0.385356,-0.031913,-0.057969,0.193646,-0.045073,-0.002389,0.084847,-0.215074,0.006459,0.177511,-0.139503,-0.898559,0.094746,0.068710,0.130778,-0.630472,0.401166,-0.276052,0.149204,-0.158411,-0.342788,0.054779,0.393121,0.123181,0.314108,-0.190705,0.100525,-0.591249,0.189790,0.737329,-0.062807,-0.263618,0.045076,-0.140287,-0.431155,0.123578,-0.246764,-0.427361,0.079480,0.388469,-0.053356,-0.131787,0.106777,-0.422402,-0.002275,-0.333108,-0.332494,-0.044032,-0.574975,-0.075571,-0.469856,-0.009018,-0.105426,-0.474820,0.262375,0.220751,-0.251653,0.487424,-0.536568,0.181123,0.654106,0.089032,-0.521535,0.610883,0.181562,0.357344,-0.311485,-0.096654,0.191811,0.310808,0.416047,0.187009,0.300064,-0.259818,-0.182846,-0.228191,0.451386', '3785918', '26678784', '30163500', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3059036', '亚当', '剧情', '亚当（休•丹西 Hugh Dancy 饰）是一个声控娃娃的玩具设计师，同时也是一个天文爱好者。由于存在社交恐惧症，他一直独居。某天，公寓里搬来了一个性格开朗的女孩——贝丝（（萝丝•拜恩 Rose Byrne 饰）），她和他在洗衣间相识，并开始了交往。贝丝发现亚当并不谙人情世故。虽然他不懂得约会，却带领她来中央公园看浣熊。慢慢地，两个人产生了感情。贝丝希望亚当进入自己的朋友圈，但是天生对于社交圈的恐惧，让他闹出了不少笑话。与此同时，老板认为亚当的工作效率无法适应竞争的环境，将他解雇。于是，贝丝开始帮助亚当克服心理恐惧，应对面试。两人的感情也随之加温。正在此时，贝丝的父亲突然卷入了一场诉讼案，并面临牢狱之灾，这时亚当却因为贝丝善意的欺骗而大发雷霆。口角时，两人失去了理智，这场恋爱岌岌可危……©豆瓣', '休·丹西', '马克思·梅尔', 7.8, 38220, 'tt1185836', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453719887.jpg', 0.2, 1.7, 25.7, 51.2, 21.3, '0.478274,0.152629,-0.705001,0.327364,-0.180416,-0.251576,1.043452,0.123402,-0.478680,-0.399056,0.046000,0.668200,-0.250847,0.321498,0.104269,-0.042354,-0.338968,-0.641609,0.062692,-0.073176,-0.236796,-0.330372,-0.111029,-0.318316,-0.134236,-0.235240,0.471217,0.007633,-0.356798,0.459807,0.185858,0.098461,0.139990,0.850006,0.152595,-0.059143,0.111765,-0.039347,-0.109854,0.076372,0.024909,-0.145268,-0.079937,0.310330,-0.019158,0.441348,0.568836,-0.337518,-0.191055,-0.133809,0.284347,-0.205133,-0.148175,0.211081,0.301827,-0.086694,0.056179,0.102848,-0.108367,0.114810,0.076607,0.048730,-0.657480,0.198373,-0.123070,0.336066,-0.329196,0.395376,-0.001987,-0.099559,-0.159901,-0.223911,-0.082844,0.196026,0.247282,0.335382,-0.346665,0.006148,-0.320841,-0.129753,0.683813,-0.024551,-0.193880,0.625054,-0.527679,-0.457796,-0.011609,0.050389,-0.447686,-0.290708,0.236172,0.119688,-0.278681,0.366403,-0.421096,0.039167,-0.199030,-0.068672,-0.142008,-0.606422,0.100997,-0.537810,-0.327327,-0.451723,-0.429023,-0.167214,0.022707,-0.323351,0.593809,-0.957424,0.097601,0.621268,0.210398,-0.437216,0.521930,0.269288,-0.018595,-0.243037,-0.066232,0.380517,-0.211192,0.197895,0.032039,0.405505,0.148795,-0.026164,-0.118608,0.469843', '1308755', '1296370', '4275444', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3059389', '漂亮男孩', '剧情', '尼克（提莫西·查拉梅 Timothée Chalamet 饰）从小就是一个人见人爱的乖孩子，他有着美丽白净的外表，活泼开朗的个性和一个聪慧的大脑。学生时代，他很轻松的就获得了不菲的成绩，申请了六家大学均得到了认可，获得了入学资格，每个认识他的人都坚信这位少年有着无量的前途。然而，尼克的命运，从他接触到一种名叫“大麻”的东西开始，就发生了剧烈的变化。这种能够给他带来短暂刺激和幻觉的毒品很快就令尼克深陷其中，之后，不满足的尼克又从大麻转向了病毒，彻彻底底的成为了一名瘾君子。为了戒毒，尼克进过戒毒所，参加过互助会，但这些努力最终还是付之东流。©豆瓣', '史蒂夫·卡瑞尔', '菲力斯·范·古宁根', 6.2, 13017, 'tt1226837', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2526320265.jpg', 1.3, 16.9, 56.9, 20.9, 4, '0.339827,0.176718,-0.703194,0.561468,-0.542020,-0.334069,0.758171,-0.019626,-0.606034,-0.085459,0.015141,0.907536,-0.365879,0.289953,0.346921,0.067626,-0.001675,-0.621771,-0.096262,-0.217727,-0.362645,-0.384427,-0.314058,-0.066135,0.017551,-0.523592,0.564847,0.011171,-0.241863,0.547002,0.145427,0.310377,0.419290,0.481329,-0.244328,-0.005592,0.096592,0.008873,0.060041,0.273992,0.160752,-0.071126,-0.012090,0.329352,0.009856,0.355314,0.550879,-0.175895,-0.408922,0.048784,0.367357,-0.081806,-0.237297,0.148324,0.186190,0.133231,0.047437,0.116388,-0.274548,0.209799,-0.014746,-0.016645,-0.878050,-0.263773,0.223672,0.287047,-0.583117,0.454940,0.111303,-0.173946,-0.009261,-0.179830,0.009865,0.297706,0.219123,0.356991,-0.317866,0.115978,-0.693047,0.148549,0.712075,-0.156335,-0.627340,0.486327,-0.585631,-0.613457,0.035962,-0.225222,-0.258293,0.190334,0.370989,0.250425,-0.288217,0.225337,-0.637092,0.035970,-0.236783,-0.237453,-0.050554,-0.377892,-0.001819,-0.323340,-0.441585,-0.465925,-0.485598,-0.084856,-0.068978,-0.537538,1.088041,-0.885812,0.140835,0.521427,0.027916,-0.481016,0.529290,0.175288,-0.028817,-0.053844,-0.015968,0.334262,0.185094,0.361409,-0.060708,0.688813,0.098373,-0.364000,-0.095808,0.760276', '24284209', '27602116', '30162520', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3060325', '哥哥我爱你', '剧情', '淘气的张韩一（朴智彬 饰）是一名九岁的孩子，经常逃课或在学校捣乱。十二岁的哥哥韩星（崔佑赫 饰）则是个懂事乖巧的孩子，对弟弟照顾有加。虽然性格各有不同，两兄弟依然相亲相爱。不幸的是，哥哥韩星竟然患有了脑癌，父母既震惊又伤心。手术还可能造成韩星失明，深感自责的父母觉得自己对不起大儿子，十分担忧孩子的将来。他们都忙于照顾卧病在床的韩星，忽略到了顽皮的韩一。父母的忽略，哥哥不能陪伴自己，韩一变本加厉的顽皮了。因为哥哥把韩一送的卡片送给了另一位病友，韩一十分生气，被哥哥骂了一顿后离开了医院。韩一突然懂事了，在哥哥与病友都有生命危险的时候，韩一开始为生病的哥哥付出自己的一份力。©豆瓣', '朴智彬', '林泰亨', 8.3, 6807, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p532706995.jpg', 0.2, 1.2, 16.9, 48.9, 32.7, '0.001400,-0.393896,-0.498527,0.367877,-0.436584,-0.586439,0.720103,0.214154,-0.617087,-0.224634,0.220802,0.664253,0.030972,0.799265,0.070483,-0.046748,0.039462,-0.273111,-0.072993,0.151317,-0.303998,-0.505571,-0.017586,-0.178616,-0.069924,-0.542137,0.193261,-0.210987,0.154723,0.390729,0.160372,-0.038389,0.017806,0.564534,-0.097164,0.244237,-0.262383,0.278071,0.186859,-0.087784,0.360699,-0.045266,0.145802,0.151547,0.338323,0.294955,0.827916,0.058585,-0.406495,-0.314020,0.590245,-0.292209,-0.028835,0.204761,0.257336,-0.020458,0.365139,-0.220352,-0.278884,-0.048689,0.004627,-0.097554,-0.515211,0.023108,0.326422,-0.136577,-0.852058,0.587678,-0.172512,-0.190607,0.292315,-0.500051,0.230970,0.523566,-0.089179,0.816288,-0.617597,0.234461,-0.327324,-0.007188,0.541768,-0.265301,0.144172,0.347134,-0.256260,-0.273947,0.282865,-0.408667,-0.675848,0.264027,0.173058,-0.178564,-0.237052,0.189177,-0.012773,-0.160015,-0.036487,-0.079027,-0.092051,-0.610854,-0.019442,0.205722,0.333656,-0.447514,-0.361709,0.146755,0.061902,-0.382761,1.033510,-0.967673,0.307127,0.359108,0.413532,-0.758641,0.584737,0.376502,0.022397,-0.306341,0.149366,0.196480,0.056108,-0.233310,0.165032,0.277436,0.037085,-0.026217,-0.153700,0.232088', '3445516', '26348103', '6963575', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3062897', '葫芦兄弟', '动画', '在很久以前，某座山中蛇精和蝎子精为害人间，它们的恶行引起天神震怒。天神用雷电化成的葫芦把两个妖精收了进去。葫芦化作葫芦山镇守两只妖精，只要满一万年，它们就会被葫芦化去。然而天运使然，就在九千九百九十九年之际，一只穿山甲无意钻破葫芦山，放出两只妖精。穿山甲带着老爷爷找到葫芦种子，只要种出七颗葫芦，便可将妖精重新收伏。重新获得自由的蛇精和蝎子精无所顾忌，大肆残害生命。它们偶然得知老爷爷种出神葫芦，于是接连派出爪牙企图斩草除根。接连遭遇挫折的妖精转而绑架老爷爷，各具异能葫芦七兄弟相继出世，他们打向葫芦山，与狡猾的妖精展开正邪大战……©豆瓣', '豆豆', '胡进庆', 8.8, 40723, 'tt6450154', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2318160313.jpg', 0.4, 1, 10.2, 36.2, 52.3, '0.054847,0.058251,-0.268287,0.231967,-0.032715,0.181488,0.408967,-0.119086,-0.239046,0.345156,0.037027,-0.008474,-0.318802,-0.295317,-0.319164,-0.191329,0.348907,-0.221683,-0.023453,-0.059046,-0.007338,0.068584,-0.487269,0.198400,0.357204,-0.428498,0.406585,-0.149429,0.232681,0.273433,-0.007716,0.615497,-0.586901,-0.171333,-0.339890,0.228239,-0.263442,0.154714,0.239229,0.369894,-0.318136,-0.152808,0.164471,0.008480,-0.298950,-0.004862,0.878064,-0.782595,-0.246819,-0.592589,0.158622,-0.109299,-0.240437,0.134554,0.548536,0.049886,0.323174,-0.134704,0.111124,0.218508,0.312927,-0.110672,-0.117983,-0.239823,-0.124600,0.004241,-0.394546,0.017064,0.573534,0.393396,0.136102,-0.485445,-0.045858,0.285533,0.358506,0.131213,-0.108438,-0.090650,-0.890909,-0.045945,0.244600,-0.403295,0.038872,0.127688,0.343434,-0.356893,-0.044412,-0.165586,0.098196,-0.085518,0.826257,0.260466,-0.364960,0.478112,-0.942438,-0.188333,-0.331666,0.008354,0.491416,-0.056295,-0.277049,-0.087115,-0.022059,0.260240,-0.128793,0.059591,0.281051,0.215355,0.686989,-0.511510,0.648778,0.376269,0.034382,-0.072853,0.364449,-0.630391,-0.071556,-0.308517,0.258071,-0.256044,0.858920,0.481517,0.443534,0.070346,-0.044078,0.193442,-0.181564,0.096611', '1458910', '1764796', '1856675', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3066083', '黑暗侵袭2', '惊悚', '美国阿巴拉契亚山脉的查图嘎国家公园岩洞群，朱诺（Natalie Jackson Mendoza 饰）、莎拉（Shauna Macdonald 饰）一行六人在此经历了一生中最恐怖的时刻，最终只有莎拉一人侥幸逃生。在此之后，警方派出大批搜救人员进山寻找遇难者的尸体以及可能的幸存者，但是最终却一无所获。女警官萝丝（Krysten Cummings 饰）负责询问莎拉失踪事件的始末，但是莎拉对过往发生的事情没有任何记忆。为了寻找幸存者和事实真相，萝丝带着莎拉再次来到岩洞群，并在此与搜救人员凯西（Anna Skellern 饰）和格雷格（Joshua Dallas 饰）等碰头。他们从废弃的矿井口进入岩洞，不久便发现贝丝等人的尸体。搜救人员意识到这不是简单的失踪事件，与此同时危险正向他们悄悄逼近……©豆瓣', '迈克尔·J·雷诺兹', '约翰·哈里斯', 6.8, 41514, 'tt1073105', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1061248355.jpg', 1.4, 9.4, 48.1, 30.8, 10.3, '0.277288,-0.179710,-0.867471,0.330599,0.340278,0.015242,1.021682,-0.200989,-0.745657,-0.456908,0.333558,0.554113,-0.167091,-0.137609,0.085105,-0.174359,-0.599185,-0.582993,-0.163456,-0.283448,-0.706374,-0.476633,-0.117854,-0.247550,0.115897,-0.297298,0.534806,0.444052,-0.101566,0.740450,0.080611,0.515943,-0.809812,0.595400,0.033735,0.092981,0.398878,0.011375,-0.243234,0.232040,-0.225494,-0.230542,-0.284351,-0.044781,0.182526,0.482689,0.911633,-0.232579,-0.277258,0.184679,-0.134035,-0.488995,0.169722,-0.049425,0.743674,-0.180812,0.078315,0.433390,-0.138289,-0.114972,0.014343,-0.016246,-0.555769,0.102400,0.078340,0.573093,-0.400251,0.017195,-0.143004,0.028407,0.376526,-0.318271,0.246951,0.555093,0.117474,-0.078408,-0.159301,-0.078456,-0.521441,-0.034006,0.579430,-0.222886,0.077573,0.193973,-0.007686,-0.578668,-0.211847,0.195656,0.023841,0.105233,0.390314,0.405880,-0.298096,0.037107,-0.591187,-0.010078,-0.364139,-0.628836,0.044322,-0.238858,-0.224424,-1.053262,0.039851,-0.152874,-0.331307,0.361845,-0.237703,0.102476,0.413745,-0.487255,0.307109,0.539990,0.137746,-0.521259,0.493110,-0.268977,0.211746,-0.203240,0.186319,0.395455,0.223862,0.426144,0.003348,0.091396,-0.083207,-0.434516,-0.659004,-0.174566', '10466639', '3011051', '1306809', '2024935');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3066739', '钢铁侠2', '动作', '钢铁侠托尼·斯塔克（小罗伯特·唐尼 Robert Downey Jr. 饰）在国会听证上拒绝交出最新技术。与此同时，他发现胸口的微型电弧反应炉正迅速造成血液的钯金属中毒。沮丧的托尼将斯塔克公司的总裁职务交予了秘书波兹（格温妮丝·帕特罗 Gwyneth Paltrow 饰），由她全权负责正在进行的纽约斯塔克博览会。波兹从法律部门调来助理娜塔莉（斯佳丽·约翰逊 Scarlett Johansson 饰）照顾托尼。托尼在媒体前的高调亮相引起了其父当年同事的儿子，伊凡（米基·洛克 Mickey Rourke 饰）的不满。为了实施报复，他子承父业，研制出了一套可与钢铁战衣相媲美的装备。伊凡的技术引起了托尼的竞争对手，军火商贾斯丁·汉默（山姆·洛克威尔 Sam Rockwell 饰）的注意，他设法将伊凡劫持出狱，秘密研究取代钢铁侠。正当托尼苦于钯金属中毒造成的失意之时，他发现娜塔莉原来身负秘密使命，而自己的任性，也造成了与好友，空军上校罗尼（唐·钱德尔 Don Cheadle 饰）的反目，眼看局势就要失控……', '小罗伯特·唐尼', '乔恩·费儒', 7.7, 399582, 'tt1228705', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p451885601.jpg', 0.4, 2.9, 30.8, 44.1, 21.7, '-0.029825,0.150914,-0.641220,0.279224,-0.043226,-0.357845,0.615570,0.263308,-0.336385,-0.370258,0.348912,0.578683,-0.162377,-0.083337,0.205460,0.201145,-0.477004,-0.551005,0.121274,0.065420,-0.129539,-0.585855,-0.210034,-0.363771,0.047538,-0.524886,0.466267,-0.244447,-0.244105,0.332202,0.184651,0.449461,0.150973,0.445852,0.462169,-0.126980,0.312129,-0.264320,-0.241307,0.157917,0.153894,-0.140536,0.214642,0.289238,0.121190,0.396089,0.364990,-0.239005,0.167721,-0.237870,0.432099,-0.144881,0.351526,-0.020646,0.217572,0.260409,-0.331159,-0.012051,-0.356188,-0.015303,0.499478,-0.015525,-0.462568,-0.002191,-0.185382,0.186201,-0.485737,0.353435,-0.699143,0.180545,0.026187,-0.470631,0.098311,0.275715,0.242282,0.059406,-0.240867,0.338800,-0.440071,-0.011546,0.158300,-0.027307,-0.222205,-0.034303,-0.103617,-0.280225,-0.003513,-0.111529,-0.288139,-0.220604,0.620856,0.005809,0.219591,0.357969,-0.499129,-0.370657,-0.359634,-0.122173,-0.012975,-0.081378,0.178705,-0.873799,-0.171076,-0.091509,-0.221020,-0.222334,0.088261,-0.153052,0.323957,-0.531484,0.158041,0.508804,0.286987,-0.306715,0.342942,-0.195577,0.239695,-0.201874,-0.368588,0.111091,0.306816,0.171750,0.130669,0.367332,0.313956,-0.329979,0.036764,0.221158', '6517421', '34961898', '1316693', '2075345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3066798', '僵尸至尊', '喜剧', '七月十五，鬼门大开，孤魂野鬼游荡人间。茅山道长九叔（林正英 饰）精心准备鬼月所需祭品，而顽皮的二徒弟文才却跑去看鬼戏。文才懵懂，不只身旁已聚满群鬼，更有貌美如画的女鬼小丽（吴家丽 饰）将其相中。九叔命大徒弟秋生（钱小豪 饰）前去营救，秋生则为小丽美色所惑。最终师徒惊动群鬼，使得它们逃脱鬼差管制，徘徊人世。为避免群鬼危害世人，九叔请来师兄弟共同商议对策。大师兄提出先天八卦阵，而由文才和秋生两个惹祸头负责将群鬼吸引出来……©豆瓣', '林正英', '刘伟强', 7.5, 17612, 'tt0093309', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2592105677.jpg', 0.5, 3.7, 34.9, 40.4, 20.5, '-0.013612,-0.286518,-0.096628,0.096668,-0.193992,-0.150196,0.401180,0.142703,-0.342369,-0.418457,0.223792,0.194079,-0.175900,-0.082457,-0.037045,-0.003293,0.023755,-0.429967,-0.278242,-0.179239,-0.047147,0.044392,0.068177,0.074427,-0.042714,-0.008940,0.279481,-0.068450,0.232893,0.128638,0.150593,-0.085858,-0.614527,-0.049084,0.113625,0.108539,-0.310679,-0.092870,-0.091341,0.113226,-0.312944,-0.129889,-0.565835,-0.155806,-0.168324,0.067263,0.648843,-0.399173,-0.247481,-0.504199,0.156140,-0.122601,0.055013,0.016381,0.122445,-0.099147,0.404719,0.007511,0.089368,-0.107999,-0.062574,0.101113,-0.131610,0.543606,0.264432,-0.029268,-0.297745,-0.029146,0.146033,0.100824,-0.028112,-0.260508,-0.061719,0.301864,0.218970,0.129663,-0.043279,-0.138790,-0.299546,0.192241,0.138473,-0.203576,0.521469,-0.043322,0.176557,-0.106595,0.271641,-0.273797,-0.261493,-0.102161,0.354097,0.173289,-0.049680,0.060435,-0.192104,-0.396260,-0.280972,0.378845,-0.113986,-0.207017,0.086754,-0.530054,0.132616,0.051582,0.056465,-0.148346,0.526105,-0.200856,0.728158,-0.277241,0.061833,0.392556,0.230198,-0.473666,0.528087,-0.258057,0.141654,-0.349092,-0.457303,-0.167147,0.213058,0.581759,0.279399,0.090375,0.017593,-0.066046,-0.202812,-0.275098', '5403927', '25922902', '25863940', '27069070');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3068206', '碟中谍4', '动作', '特工汉纳威（乔什·哈洛威 Josh Holloway 饰）执行任务时遇害，核机密文件被女杀手莫伦（蕾雅·赛杜 Léa Seydoux 饰）截获。为了找回文件，特工班吉（西蒙·佩吉 Simon Pegg 饰）和特工简（宝拉·巴顿 Paula Patton 饰）从俄罗斯监狱救出了伊桑·亨特（汤姆·克鲁斯 Tom Cruise 饰）。他们接受的幽灵协议任务便是从克林姆林宫盗取核军事密码。然而，当他们接近目标时，却发现被恐怖分子亨德里克斯（迈克尔·恩奎斯特 Michael Nyqvist 饰）捷足先登，抢走了核军事密码。在爆炸中，亨特受困医院，遭俄特工的追捕，幸好他身手矫捷，才化险为夷。不过，亨特的上司也在混乱中丧生，只剩下其助手布兰德（杰瑞米·雷纳 Jeremy Renner 饰）与亨特死里逃生，加上班吉和简，逼上绝境的四人开始了最后一搏，从迪拜到印度，他们出生入死，与恐怖分子斗智斗勇……', '汤姆·克鲁斯', '布拉德·伯德', 8.3, 409443, 'tt1229238', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1382432968.jpg', 0.1, 0.6, 13.7, 53, 32.6, '0.058957,-0.081157,-0.753507,0.475239,-0.036266,-0.478297,0.560182,-0.013339,-0.287453,-0.260841,0.148063,0.530708,-0.210730,-0.340835,0.398732,-0.006741,-0.511314,-0.740390,-0.015774,-0.280738,-0.430281,-0.593161,-0.465950,-0.308034,0.138910,-0.463678,0.484536,0.007708,-0.138709,0.292903,0.302952,0.686255,-0.399035,0.208959,0.267814,-0.114800,0.508531,-0.383310,-0.270201,0.014307,0.006583,-0.128989,-0.126445,-0.054089,0.478738,0.443570,0.694739,-0.359455,0.273907,-0.247834,-0.103457,-0.404471,-0.053199,-0.110579,0.090565,0.045509,0.006926,0.068636,-0.046857,0.053729,0.165386,-0.153527,-0.490076,-0.061412,-0.162892,0.167360,-0.290260,0.128812,-0.620597,0.495906,0.053253,-0.323132,0.131524,0.236604,0.183254,-0.001177,-0.054089,-0.025625,-0.695027,-0.076039,0.279409,-0.171960,-0.146437,-0.101773,0.149973,-0.638537,0.078898,-0.093240,-0.128053,0.121134,0.809663,-0.106966,-0.048644,0.186027,-0.470323,-0.520563,-0.816740,-0.097318,-0.323877,-0.289982,-0.095333,-0.972274,-0.141018,-0.038028,-0.387799,0.314350,-0.087255,-0.117764,0.441569,-0.417993,0.162208,0.599189,0.148794,-0.175223,0.207190,-0.110570,0.340105,-0.287374,-0.194370,0.422695,0.579595,0.199028,0.377062,0.054106,-0.140105,-0.320726,-0.403173,0.170036', '6517421', '2028645', '11610281', '21349734');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3070319', '爱很复杂', '喜剧', '加州圣芭芭拉市的面包店老板娘珍妮（梅丽尔•斯特里普 Meryl Streep 饰）与前夫杰克（亚历克•鲍德温 Alec Baldwin 饰）20年的婚姻因后者的外遇而解体。十年后，三个孩子均已长大成人，珍妮的生活也终于步入正轨，并在扩建房屋的过程中结识了建筑师亚当（史蒂夫•马丁 Steve Martin 饰），二人互生情愫。但在小儿子Luke（亨特·帕瑞施 Hunter Parrish 饰）的毕业典礼上，珍妮却突然发现杰克对她旧情复燃。心乱如麻的珍妮禁不住诱惑，竟与已婚的杰克搞起了婚外恋。面对这段剪不断理还乱的复杂四角关系，珍妮到底该如何选择呢？本片获第67届金球奖音乐喜剧类最佳影片、最佳女主角（Meryl Streep）和最佳剧本三项提名。©豆瓣', '梅丽尔·斯特里普', '南希·迈耶斯', 7.4, 23069, 'tt1230414', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p904956135.jpg', 0.3, 2.7, 35.4, 47.7, 13.9, '0.072345,-0.032801,-0.629618,0.368958,0.373625,-0.629513,0.545850,-0.030605,-0.362393,-0.258973,0.167887,0.685226,-0.516901,0.238152,0.341090,0.111402,-0.412473,-0.703228,0.156098,-0.229316,-0.093927,-0.590106,-0.468692,-0.008623,-0.082341,-0.217847,0.661118,-0.214861,0.130900,0.425438,0.543013,0.109679,-0.157425,0.089296,0.110462,0.133207,0.240426,0.101341,-0.554968,0.059148,0.144486,-0.162585,-0.221696,-0.104465,0.212526,0.455866,0.679337,-0.132632,0.138843,0.134666,0.467749,0.045223,-0.073777,0.055943,0.296677,-0.265564,0.202238,0.350877,-0.097957,-0.038580,0.113607,-0.042249,-0.349583,0.193954,0.101417,0.161415,-0.372327,0.445587,-0.163179,0.088374,-0.060629,-0.095061,-0.013154,0.392845,0.310113,0.493666,-0.301583,-0.112691,-0.145562,0.288654,0.194534,0.116614,-0.224839,0.445362,-0.196373,-0.491699,-0.261058,-0.031428,-0.541605,-0.115633,0.303783,0.217198,0.132267,0.324493,-0.491193,-0.197242,-0.310354,0.031744,-0.043215,-0.255910,0.148067,-0.665782,-0.142910,-0.280116,-0.289173,-0.091192,0.204846,-0.139082,0.315314,-0.574487,0.391008,0.246354,0.101172,-0.431601,0.357827,0.313107,0.374687,-0.357100,-0.430188,0.412623,-0.290401,-0.155179,0.063072,0.334915,0.006624,-0.234210,-0.287011,0.345395', '6843843', '1484091', '1780122', '34795703');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3070888', '非常舞者', '剧情', '母亲和弟弟和马的相继去世给女孩宫本昴（黑木明纱 饰）留下了永远不能消散的伤痛记忆，在她以后的生活中，芭蕾成为她寄托哀思和寻找勇气的惟一方式。在学习芭蕾的过程中，凭着自己天生的才气以及执着和倔强的性格，她结识了很多老师和朋友，她相信只要自己想做的就一定能做到。然而生活中的 人际关系并不像她所看到的那样简单，良师益友的背后也暗藏不可告人的秘密。终于，她走到了上海国际艺术节的赛场，初试复试毫无悬念的通过，然而就在决赛的前一晚，她得知把她带进芭蕾艺术殿堂，而且从小便像婶婶一样的爱护她的老师五十岚铃（桃井薰 饰）去世，赛前的她伤心和压力过度，导致高烧不退，而且伴有短暂的失忆现象，昴能否撑过这一关，值得所有人的期待……本片改编自日本同名人气漫画《舞吧！昴》。©豆瓣', '黑木美沙', '李志毅', 7.2, 5315, 'tt1230424', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p724715853.jpg', 1.3, 7.2, 38.7, 35.7, 17.1, '0.158502,0.062903,-0.800822,0.697808,-0.273366,-0.199344,0.539608,-0.007322,-0.317930,-0.201478,0.196627,0.832985,0.006769,0.269896,0.110921,-0.060525,-0.174421,-0.935704,-0.067458,-0.055034,-0.318899,-0.462334,-0.155816,-0.141065,-0.217912,-0.539143,0.733685,0.169857,-0.196986,0.422228,0.134812,0.242339,0.050928,0.408020,-0.140314,0.022864,-0.093241,0.318596,-0.324195,0.193157,0.290856,-0.196997,-0.085384,0.215202,0.116410,0.163469,0.563159,-0.231470,-0.209720,0.089926,0.297595,-0.276945,-0.074848,0.199805,0.086469,-0.076330,0.401640,0.330754,-0.232660,0.134223,-0.138108,-0.083759,-0.746144,-0.117671,0.308483,0.255098,-0.562910,0.603125,0.058694,-0.161701,0.243634,-0.208036,-0.004784,0.175508,0.221689,0.299488,-0.446544,0.054971,-0.418803,0.226929,0.747821,-0.161077,-0.397109,0.474573,-0.218799,-0.306938,-0.110722,-0.233516,-0.427670,0.227241,0.081096,0.152291,-0.428152,0.162270,-0.370913,-0.012705,0.027193,-0.160776,-0.079382,-0.575576,0.180053,-0.398829,-0.079238,-0.609870,-0.451866,-0.222379,0.139214,-0.513647,0.906782,-0.922939,0.334719,0.323163,0.285653,-0.389133,0.680180,0.175119,-0.031651,-0.046197,0.029197,0.229543,-0.158751,0.097968,0.089261,0.470636,0.111295,-0.006632,-0.519693,0.722808', '26809007', '30162520', '35048413', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3070921', '饥饿', '剧情', '北爱共和军领导人鲍比•桑兹（迈克尔•法斯宾德 Michael Fassbender 饰）因为领导反对当局的游行而被捕。在梅兹监狱中，他依然没有放弃斗争。监狱里都是六平方米的封闭牢房，这里关押着北爱共和军的囚犯，他们赤身裸体拒绝穿囚衣，以此对抗撒切尔夫人剥夺囚犯权利的法令。他们用污浊的食物和排泄物掩盖着变形门下的沟渠，以此传递消息。通过一台蒙混过关的收音机，囚犯们得以及时了解共和军与英国政府斗争的消息。最后，在桑兹决定以绝食抗争的时候，他与神父多米尼克•莫朗（利亚姆•坎宁安 Liam Cunningham 饰）有过一场精彩的辩论，然而结果却于事无补……本片获得第61届戛纳电影节金摄影机奖。©豆瓣', '迈克尔·法斯宾德', '史蒂夫·麦奎因', 8, 15359, 'tt0986233', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p788163635.jpg', 0.6, 2.1, 20.2, 51.6, 25.5, '0.044069,-0.035253,-0.593196,0.601621,0.028912,-0.106714,0.752736,0.145073,-0.532755,-0.131897,0.147140,0.535210,-0.134358,0.001085,0.072732,-0.228728,-0.713075,-0.653991,-0.269685,-0.032844,-0.183673,-0.600150,-0.206718,-0.461742,-0.113685,-0.273188,0.846475,0.068607,-0.357340,0.138276,0.567981,0.172620,-0.014871,0.452379,0.215177,-0.121059,0.426111,-0.077525,-0.373743,0.116741,-0.112030,-0.314988,-0.334108,0.261418,0.271603,0.581511,0.366043,-0.576022,0.145652,0.012423,0.257966,-0.244687,-0.172909,0.295640,0.228911,-0.057716,0.183340,0.527998,0.064709,0.059114,0.106255,0.064408,-0.445373,-0.164674,-0.010127,0.272827,-0.241342,0.433401,-0.298266,0.362663,-0.095900,-0.204804,0.049578,0.264484,0.125142,0.207730,-0.257191,-0.215980,-0.667870,0.321649,0.373017,-0.261528,-0.485746,-0.093887,-0.383386,-0.494168,0.124042,-0.499642,-0.350750,-0.249427,0.320037,-0.089647,0.049683,0.271176,-0.512682,-0.357285,-0.363538,-0.361008,-0.052551,-0.008138,-0.012801,-0.818916,-0.079182,-0.035088,-0.207606,-0.028647,-0.050271,-0.158204,0.424278,-0.480156,0.161722,0.365930,0.316321,-0.371427,0.624179,0.244431,0.221959,-0.086897,-0.184405,0.142253,0.105152,0.273026,0.287679,0.252042,-0.017905,-0.156396,-0.340556,0.180709', '26990609', '1301444', '1295484', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3071441', '雪国列车', '剧情', '为了应对愈演愈烈的温室效应，世界各国在2014年发射了代号CW-7的冷冻剂，谁知却将地球推入了万劫不复的极寒深渊。大多数的人类死于寒冷与恐慌，只有为数不多的数千人登上了威尔福德工业开发的列车，成为永不停歇的流浪者。这列火车借助威尔福德（艾德·哈里斯 Ed Harris 饰）开发的永动引擎，并且配备各种完备设施，在之后的十七年里构建了属于自己的独立生态系统，周而复始旋转在43.8万公里的漫长旅途中。生活在末尾车厢的底层人民一直饱受压迫，为了争取自由和权力，他们在过去发起过多次暴动，但无疑例外均以失败告终。这一次，拥有领袖气质的柯蒂斯（克里斯·埃文斯 Chris Evans 饰）试图找到被囚禁的安保设计师南宫民秀（宋康昊 饰），借助他之手打开通往首节车厢的重重大门，推翻威尔福德的统治。新年伊始，一场血腥革命正在进行……本片根据根据法国漫画《Le Transperceneige》改编。', '克里斯·埃文斯', '奉俊昊', 7.5, 423918, 'tt1706620', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173648321.jpg', 0.7, 3.5, 30.8, 47.7, 17.2, '0.037226,0.234635,-0.804681,0.481713,-0.076112,0.016219,0.641568,-0.005754,-0.495713,-0.162480,0.268998,0.636100,-0.122857,-0.319551,0.377880,-0.170202,-0.226645,-0.472504,-0.266021,-0.012672,-0.271036,-0.324728,-0.495933,-0.349151,-0.040180,-0.455970,0.919742,0.353477,-0.347549,0.282572,-0.080934,0.315626,-0.173111,0.310047,-0.054631,-0.097884,-0.029201,-0.312288,-0.444481,0.330921,-0.420239,-0.334679,-0.102929,-0.063175,-0.050075,0.263635,0.595169,-0.500534,0.148999,-0.172309,0.401590,-0.310468,-0.358309,0.078138,0.132037,0.303066,-0.009949,0.418380,-0.205725,0.087436,0.178150,-0.250877,-0.970544,-0.282857,-0.120807,-0.057866,-0.554822,0.642483,-0.081106,-0.241628,-0.053073,-0.314341,0.098054,0.314011,0.160165,0.472951,-0.209171,0.096946,-0.441596,0.022744,0.612180,-0.124648,-0.543358,0.107765,-0.104638,-0.374501,-0.204926,-0.407921,-0.419678,-0.355693,0.366568,0.139661,0.015625,0.323420,-0.800220,0.228284,-0.317396,-0.674090,0.036754,-0.274646,-0.126334,-0.836021,0.065603,-0.189153,-0.024471,0.094494,0.006509,-0.335426,0.585622,-0.759121,0.384998,0.519148,0.232045,-0.459671,0.518975,0.120831,0.289757,-0.228261,-0.165470,0.542451,0.054442,0.737808,0.009480,0.288578,-0.061798,0.102003,-0.517686,0.544555', '7051375', '26759819', '1793491', '10558440');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3071461', '鼠来宝2：明星俱乐部', '喜剧', '上一集的相会，无意改变了作曲家戴夫·塞维利亚（杰森·李 Jason Lee 饰）与三只可爱的花栗鼠艾尔文（贾斯汀·朗 Justin Long 配音）、西蒙（马修·格雷·库伯勒 Matthew Gray Gubler配音）与西奥多（杰西·麦卡尼 Jesse McCartney 配音），他们结伴出游，享受音乐的乐趣，当然也闹出不少的乱子和笑话。意外受伤的戴夫将三只小家伙托付给杰姬阿姨，还为他们办了入学手续。但杰姬阿姨也出了事故，艾尔文他们只能和戴夫不着调的侄子托比（扎克瑞·莱维 Zachary Levi 饰）混在一起，开始了校园生活，还结识了另外三只美丽可爱的小花栗鼠布列塔妮（克里斯蒂娜·艾伯盖特 Christina Applegate 配音）、埃莉诺（艾米·波勒 Amy Poehler 配音）与珍妮特（安娜·法瑞丝 Anna Faris 饰）。有趣、浪漫且韵律十足的校园故事轻松上演……本片荣获2010年美国儿童选择奖最受喜爱的影片。', '扎克瑞·莱维', '贝蒂·托马斯', 7.1, 31721, 'tt1231580', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p761388083.jpg', 0.7, 5.3, 43.9, 35.9, 14.1, '0.263338,-0.171859,-0.459959,0.339362,0.143201,-0.553099,0.766049,0.181640,-0.151079,-0.086266,-0.127388,0.561534,-0.494668,0.325326,0.408628,0.277971,-0.676714,-0.457057,0.122976,0.179173,0.104657,-0.494374,-0.048061,-0.305777,0.046413,-0.276781,0.075484,-0.404363,-0.180887,0.619381,0.514125,0.185721,-0.290054,0.186061,0.018332,0.339475,0.220414,0.082288,-0.054469,-0.061652,0.133894,-0.032252,-0.372813,-0.216930,0.444448,0.140982,0.773161,-0.136328,0.113251,-0.018802,0.222812,-0.175364,0.205528,0.038630,0.031198,-0.130262,0.320725,-0.025994,-0.023047,-0.006831,0.059026,-0.319049,-0.449993,0.332431,-0.087891,0.167980,-0.265400,0.333391,-0.020297,-0.009439,0.350763,-0.340079,0.140032,0.166743,0.212984,0.196881,0.024743,0.215191,-0.322578,0.200010,0.397020,0.135635,-0.267962,0.070286,-0.302355,-0.591657,-0.171676,-0.185904,-0.490149,0.171620,0.552144,-0.413304,0.230081,0.266167,-0.577649,-0.256066,-0.226576,-0.167384,-0.184196,-0.229758,0.225908,-0.887916,0.135832,-0.342191,-0.525951,-0.260084,0.106509,-0.192992,0.745380,-0.494390,0.127892,0.428363,0.025905,0.007560,0.467261,-0.007367,0.250936,-0.196229,-0.122706,0.023972,-0.069228,-0.192713,0.489020,0.632551,0.179988,-0.1