INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3071469', '预产期', '剧情', '略带神经质的彼得（小罗伯特·唐尼 Robert Downey Jr. 饰）是一个准爸爸，五天后就是妻子（米歇尔·莫娜汉 Michelle Monaghan 饰）的预产期。他冲忙赶上飞机，希望可以马上飞到妻子身边陪她生产。不料，事与愿违，偏偏 上了飞机遇上一心想成名的演员伊森（扎克·加利凡纳基斯 Zach Galifianakis 饰）。然后，麻烦也就接踪而至了。在一场混乱过后，两人被赶下飞机并列入禁飞乘客名单。更不幸的是，彼得皮夹、证件又通通被飞机载走。为了及时赶上宝宝的诞生，彼得不得不选择和讨厌的伊森共同上路。二人被迫一起搭上顺风车，展开了一次穿州过省的公路旅程。当神经男遇上怪咖男，路上还有什么在等着他们呢？最后，彼得是否赶得上迎接孩子的出生？©豆瓣', '小罗伯特·唐尼', '托德·菲利普斯', 7.1, 60951, 'tt1231583', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p640220590.jpg', 0.6, 5, 43.4, 40.1, 11, '0.214030,-0.016314,-0.632061,0.291075,-0.106320,-0.458425,0.446335,0.192871,-0.424872,0.099543,0.198154,0.554902,-0.277104,0.115542,0.548790,0.014663,-0.544833,-0.362353,0.183050,0.006864,-0.631884,-0.353285,-0.042515,0.037116,-0.005115,-0.249049,0.352010,-0.046139,0.294580,0.727227,0.308647,-0.063229,-0.137411,0.467664,-0.287575,0.051293,0.007319,-0.101260,-0.155432,0.341750,0.120507,-0.083025,0.081258,-0.143591,0.085145,0.244097,0.576648,0.145878,0.085156,-0.013740,0.022905,-0.310633,0.105004,-0.006928,0.392355,-0.063947,0.102560,0.003944,-0.135453,0.138887,0.186246,0.111536,-0.328196,0.390098,-0.396448,-0.176658,-0.636554,0.250569,-0.275544,-0.080819,0.213503,-0.502028,0.164032,0.373240,0.074656,0.313467,-0.083271,0.045670,-0.468541,-0.110263,0.527577,-0.037857,0.056002,0.490429,0.345867,-0.280678,0.101245,-0.131484,-0.417122,0.120707,0.495477,-0.061478,-0.234804,0.110485,-0.328704,0.105161,-0.468339,-0.280532,0.055256,-0.330800,-0.009401,-0.473635,0.361166,-0.061484,-0.068228,0.240991,0.163159,-0.115456,0.440915,-0.515216,0.323589,0.552177,0.301853,-0.203024,0.534053,0.158830,0.316476,-0.096984,0.276438,-0.102119,-0.030775,0.453672,0.177762,0.234728,0.023929,-0.155478,-0.255637,0.420260', '1451563', '1303723', '1819460', '1296636');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3071471', '热浴盆时光机', '喜剧', '居住洛杉矶的亚当（约翰·库萨克 John Cusack 饰）刚被女友甩掉，他的单亲侄子雅各布（克拉克·杜克 Clark Duke 饰）一天到晚沉迷于电子游戏，赖在他家的地下室不走。亚当的老朋友尼克（克雷格·罗宾逊 Craig Robinson 饰）是个“妻管严”，工作亦不顺心；而另一位旧友卢（罗伯·考德瑞 Rob Corddry 饰）则酗酒无度，自杀未遂被送进医院。为了开导卢，亚当与尼克决定邀卢重游科迪亚克谷滑雪度假村，雅各布也同行。四人入住当年的酒店房间，在露台上的温泉浴盆里又喝又唱。次日宿醉醒来，却发现他们竟鬼使神差地回到了八十年代。担心因改变历史而消失的雅各布着力敦促三人回忆当年的历史行为，并照行不误；但这三位突然发现人生第二次机会的老友却各自心怀鬼胎。损坏了的热浴盆时光机究竟能否修好？未来是否会因为历史的改变而混乱不堪呢？©豆瓣', '约翰·库萨克', '斯蒂夫·平克', 6.5, 19629, 'tt1231587', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p511537373.jpg', 1.8, 10.7, 55.2, 26.3, 6, '0.194912,0.129375,-0.592820,0.271264,0.075206,-0.492571,0.753055,0.377410,-0.494003,-0.526821,-0.060440,0.572236,-0.115478,0.442247,0.444623,-0.021172,-0.467454,-0.397561,0.138099,-0.101521,-0.378065,-0.277722,-0.160055,-0.455459,0.144202,0.016871,0.357564,0.060618,-0.204416,0.333800,0.255028,0.308280,-0.116850,0.424473,-0.043287,0.110841,0.009953,0.314021,-0.181308,0.038775,0.131763,-0.230208,-0.131822,-0.057647,0.217435,0.300579,0.533373,-0.041844,-0.226467,-0.141943,0.195223,-0.049176,0.056508,0.104230,0.401812,-0.061286,-0.000585,0.201782,0.032584,-0.014767,0.017764,-0.031149,-0.302586,0.204577,-0.074626,-0.036042,-0.412344,0.287117,-0.072370,0.020221,-0.287084,-0.220324,0.181791,0.360127,0.295011,0.356628,-0.117841,0.027264,-0.466381,0.110766,0.261436,-0.032702,0.009392,0.432643,-0.051815,-0.344582,0.055300,0.058415,-0.401524,-0.128323,0.337911,0.025426,-0.128127,0.103825,-0.339854,-0.128425,-0.281164,-0.118646,-0.151587,-0.151124,-0.149478,-0.607268,0.032461,-0.057104,-0.183854,-0.012307,-0.031109,0.096382,0.171849,-0.510358,0.261831,0.370038,-0.019027,-0.461986,0.647809,0.089102,0.081598,-0.273905,0.048664,0.600722,0.093192,0.150298,0.013041,0.237454,-0.092883,-0.010398,-0.500666,0.267827', '1309172', '1301686', '131