INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3071509', '后裔', '剧情', '事业有成的律师马特（乔治·克鲁尼 George Clooney饰）的妻子因为一次意外变成了植物人。最近医生告诉他，妻子大限将至，令他倍受打击。同时，他作为夏威夷某岛的继承人还在与信托基金谈开发事宜。忙乱之中，两个女儿也不让马特省心：小女孩斯科蒂（阿玛拉·米勒 Amara Mil ler 饰）经常对同学爆粗口，马特只得带她亲自登门道歉；大女儿亚利桑德拉（谢琳·伍德蕾 Shailene Woodley 饰）住寄宿学校终日酗酒，母亲病重，马特希望亚利桑德拉摒弃对母亲的敌意，然而女儿却道出了母女决裂的原因——她发现了母亲出轨的事实。这彻底颠覆了妻子在马特心目中的印象。他跑去找妻子的闺蜜求证，答案竟然如出一辙。一直被蒙在鼓里的马特既失望又愤怒，开始带着女儿顺藤摸瓜，寻找第三者……本片获第84届奥斯卡最佳改编剧本奖。©豆瓣', '乔治·克鲁尼', '亚历山大·佩恩', 7.5, 43061, 'tt1033575', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1330001435.jpg', 0.3, 2.1, 31.7, 52.2, 13.7, '-0.170743,-0.054129,-0.560069,0.558815,-0.161436,-0.510059,0.532468,0.172986,-0.574929,-0.233755,-0.010287,0.638066,-0.088483,0.374951,0.227484,0.156369,-0.297817,-0.458007,0.005669,-0.147565,0.079614,-0.464551,-0.024938,-0.217898,0.025471,-0.318440,0.190803,-0.350915,-0.173667,0.224486,0.449842,0.284219,-0.026056,0.520472,0.113325,0.210637,0.026490,0.032198,-0.439302,0.165744,0.179268,-0.094710,-0.090311,0.166600,0.119118,0.481431,0.410532,-0.100630,0.021585,-0.234871,0.396453,-0.214593,-0.016452,0.145581,0.153686,-0.098831,0.270264,0.062649,-0.076895,-0.246843,0.152514,0.002343,-0.506766,0.248339,0.150912,0.104963,-0.576147,0.401784,-0.363908,0.120671,0.148447,-0.385976,0.145055,0.185775,0.137912,0.434769,-0.256068,0.260585,-0.352083,0.114722,0.421580,-0.239921,0.086477,0.154943,-0.256880,-0.251538,0.316374,-0.108275,-0.557382,0.071341,0.248066,0.020178,-0.027526,0.291727,-0.068961,-0.288156,-0.402910,-0.020691,0.066270,-0.586823,0.023472,-0.287318,0.012487,0.064238,-0.254205,-0.239766,0.077698,-0.294584,0.445148,-0.387700,0.213681,0.528163,0.362096,-0.532312,0.513827,0.322848,0.096667,-0.619992,-0.156985,0.369019,-0.026370,0.124683,0.111481,0.026407,0.136501,-0.180889,-0.263545,0.268632', '26420626', '30140107', '1299802', '1305175');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3071517', '蕾蒙娜和姐姐', '喜剧', '9岁的小女孩蕾蒙娜·昆比（乔伊·金 Joey King 饰）生活在一个幸福美满的家庭里，父亲罗伯特（约翰·考伯特 John Corbett 饰）和善宽容，尽心支撑着这个家；母亲桃乐丝（布丽姬·穆娜 Bridget Moynahan 饰）善良温柔，悉心打理家中的一切；她的姐姐碧祖丝（赛琳娜·戈麦斯 Selena Gomez 饰）美丽聪颖，品学兼优，姐妹俩还有一个牙牙学语的小妹妹。古灵精怪的蕾蒙娜每天尽情玩耍、调皮捣蛋，无忧无虑地享受这份宛如天堂般的快乐时光。然而随着父亲的失业，昆比家的快乐不复存在，人人脸上挂满愁容。蕾蒙娜不愿看到这一切，她决定用自己的奇思妙想为家人们找回久违的快乐……本片根据作家碧弗利·柯利瑞（Beverly Cleary）的小说改编。©豆瓣', '乔伊·金', '伊丽莎白·艾伦', 8, 21910, 'tt0493949', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p544485781.jpg', 0.3, 1.7, 22.3, 47.2, 28.6, '0.082788,0.091514,-0.433015,0.570957,-0.347235,-0.383886,0.866248,0.196550,-0.141895,-0.099312,0.098535,0.526295,-0.119436,0.747421,0.290780,0.374446,-0.431507,-0.608421,-0.057676,-0.044801,0.402161,-0.308416,-0.166535,-0.158387,-0.097880,-0.322544,0.240545,-0.126189,0.574134,0.755309,0.108650,0.243323,-0.099232,0.023277,-0.147106,-0.075766,-0.125564,0.027130,-0.118799,-0.088847,-0.032639,0.372072,-0.142921,0.062474,0.276751,0.040659,0.811654,-0.471061,0.047937,-0.155817,0.491603,-0.083119,0.150783,0.088463,-0.178145,-0.223290,0.210979,-0.161724,-0.230558,-0.037038,0.136751,-0.494546,-0.537886,-0.335307,0.261352,0.154080,-0.531483,0.286957,0.004206,-0.021742,0.382208,-0.364995,-0.188012,0.224991,0.096189,0.630257,-0.159310,0.339112,-0.113066,0.405640,0.355670,-0.046363,-0.377298,0.464057,-0.784594,-0.030835,0.361216,-0.300022,-0.968984,-0.020320,0.063621,-0.241296,0.131558,0.405194,-0.492541,-0.115971,-0.258978,-0.059963,-0.035349,-0.481126,-0.248394,-0.576888,-0.090557,-0.614062,-0.416497,-0.134804,-0.196899,-0.427439,1.026862,-0.713731,0.446871,0.303668,-0.076807,-0.144300,0.533257,-0.002237,0.190962,-0.166317,-0.212201,0.877100,-0.144499,-0.247637,-0.164689,0.346805,-0.155224,0.293946,-0.490413,0.604905', '26348103', '10533913', '25882279', '1464633');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3071604', '丹麦女孩', '剧情', '1926年哥本哈根，风景画家艾纳（埃迪·雷德梅恩 Eddie Redmayne 饰）和擅长人物画的格尔达（艾丽西亚·维坎德 Alicia Vikander 饰）结为夫妇。因为模特失约，格尔达为顺利完成画作说服了艾纳穿上女装救场。这次意外令艾纳多出一个女性人格“莉莉”，而后者亦成为妻子的灵感女神，让格尔达声名鹊起。只是随着沉睡女性人格的被唤醒，艾纳开始厌恶自己作为男性的身体，他渐渐发现莉莉不但是艺术存在，更是真正的自己。格尔达也没有想到只是临时起意的游戏，竟为自己人生投下了一颗震撼弹，她该如何继续爱她的伴侣？她们在各种社会非议和误解中不离不弃，最后格尔达鼓励艾纳彻底变成莉莉......根据世界上首位变性人士生平改编的《丹麦女孩》讲述一段跨越性别和性向的爱情，重现一位最早接受性别重置手术的丹麦画家与妻子的传奇故事。该片由奥斯卡导演汤姆·霍珀执导，入围威尼斯电影节金狮奖。', '埃迪·雷德梅恩', '汤姆·霍伯', 8.3, 222520, 'tt0810819', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2264778990.jpg', 0.2, 1, 15.1, 49, 34.7, '0.041654,0.084589,-0.342297,0.573222,-0.132612,-0.367342,0.658979,0.063027,-0.313421,-0.280322,0.166848,0.892300,-0.291071,0.087584,0.414432,0.089164,-0.507453,-0.669746,0.297743,-0.002990,-0.156255,-0.418183,-0.284743,0.021118,-0.122171,-0.546391,0.933071,-0.224892,-0.339555,0.209901,0.318275,0.437418,-0.064518,0.185962,0.071112,0.045591,0.199184,-0.009748,-0.388743,0.179691,-0.114005,-0.040178,-0.135155,0.263896,-0.590635,0.183326,0.661410,-0.289217,-0.018177,-0.235214,0.680216,-0.237230,0.047016,-0.168414,-0.024427,0.047195,0.175464,0.106602,0.028495,-0.057451,0.072903,-0.113681,-0.530536,0.007989,0.189402,0.313485,-0.290402,0.333602,-0.270175,-0.148120,0.117346,-0.319838,-0.070318,0.213221,0.450331,0.429755,-0.289525,0.099254,-0.220888,0.281797,0.477048,0.136875,-0.462759,0.527925,-0.369993,-0.457079,0.108960,-0.309904,-0.450831,0.166469,0.036392,0.123892,0.051973,0.340327,-0.450387,-0.141600,-0.238761,-0.273319,-0.012248,-0.500284,0.070988,-0.518531,-0.259137,-0.129282,-0.143017,-0.484307,0.237643,-0.417192,0.711534,-0.675918,0.347333,0.381657,0.104125,-0.280407,0.643436,0.178365,0.055603,-0.349327,-0.053657,0.520274,-0.155647,-0.102952,-0.174798,0.126320,0.161609,-0.016067,-0.486303,0.554205', '25880986',