INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3071624', '床伴逐个数', '喜剧', '电影改编自小说《黛丽拉和她的20个前男友》。人缘极好的单身女郎艾莉（安娜·法瑞丝 Anna Faris 饰）忽然在杂志上读到 “女人只要睡超过20个男人，一辈子就可能单身”，这论点让她心惊，当下决定要回头寻找过去的“床友”。邻居柯林(克里斯·埃文斯 Chris Evans 饰)，他为逃避女人的情债而借躲进艾莉家，两人不打不相识，于是达成协议，只要柯林帮艾莉从”床友”们中找到理想的另一半，她就要无条件提供避风港让他躲女人！柯林像秘书般开始寻索并安排艾莉的行程，让艾莉和”回头草”们一一约会，而他也顺利在一夜情之后次次落跑成功。 就在艾莉还幻想这些前男友可能有长高变帅或功成名就的同时，她和柯林的盟友关系也开始有了变化……©豆瓣', '安娜·法瑞丝', '马克·米罗', 6.4, 20895, 'tt0770703', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p987115494.jpg', 1.8, 12.4, 54.9, 23.3, 7.5, '0.191988,-0.322669,-0.647509,0.497271,-0.293897,-0.444542,0.665882,0.118875,-0.334492,0.069010,-0.000871,0.571756,-0.277829,0.074650,0.373153,0.096196,-0.356106,-0.843070,0.162002,-0.305129,-0.269321,-0.311393,-0.297022,-0.454473,-0.253181,0.000448,0.425605,-0.396847,-0.042715,0.213401,0.414099,0.038651,-0.000048,0.592173,-0.126601,-0.001118,-0.170056,0.213245,-0.185638,0.480314,0.281540,0.068370,-0.163228,-0.064253,0.095205,0.225598,0.444490,-0.111954,-0.190527,0.169308,0.175845,0.013146,-0.045408,0.305627,0.206791,-0.250518,0.386727,-0.067340,-0.041577,-0.032797,0.106180,0.244100,-0.507361,0.116391,-0.047670,0.109050,-0.543355,0.275617,-0.035371,-0.038729,0.218473,-0.578286,-0.069227,0.329391,0.446741,0.156900,-0.141288,0.145434,-0.449494,0.155268,0.376261,0.212213,-0.288269,0.471926,0.037467,-0.219820,-0.115176,0.213622,-0.671117,-0.054040,0.403381,0.092869,-0.174394,0.065673,-0.464986,0.046424,-0.144960,-0.168816,-0.090176,-0.456445,0.115778,-0.527722,-0.125204,-0.128726,-0.314844,0.077378,0.271098,-0.583392,0.663479,-0.682714,0.295465,0.733368,0.232295,-0.762878,0.649127,0.319221,0.147230,-0.128610,-0.047394,0.227461,0.069652,0.311798,0.101692,0.331017,0.035258,-0.195996,-0.350656,0.479121', '4301278', '3230462', '1418613', '4604803');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3072064', '飞鹰艾迪', '剧情', '详述了英国历史上最著名的跳台滑雪运动员，有“飞鹰艾迪”之称的迈克尔.爱德华兹激励人心的真实事迹。影片刻画了艾迪在运动赛场上永不言弃的宝贵精神，赞扬了他在面对巨大困难和挑战时所表现的非凡毅力和乐观精神。影片的男主人公“飞鹰”艾迪，由曾在《王牌特工：特工学院》中有杰出表现的新晋英国小生塔伦·埃格顿饰演，而好莱坞著名影星“金刚狼”休·杰克曼也重磅加盟，饰演艾迪的教练，为帮他圆梦卡尔加里冬奥会，对他进行严格训练。冬奥会上艾迪有趣又颇具历史性的展示让他名声鹊起，成为记者关注的焦点人物，并俘获了全世界观众的心。', '塔伦·埃哲顿', '德克斯特·弗莱彻', 8.1, 62484, 'tt1083452', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2322216899.jpg', 0.2, 1, 18.9, 53.6, 26.3, '-0.171411,-0.234342,-0.599098,0.727662,0.124696,-0.127488,0.349789,0.080577,-0.475214,0.189437,0.471815,0.916068,-0.492808,-0.005641,0.506551,-0.128431,-0.322197,-0.586122,-0.240329,0.086016,0.055773,-0.364500,-0.457471,-0.144000,-0.101939,-0.499186,0.654364,-0.136475,-0.473752,0.495512,0.399800,0.237861,0.419091,-0.075898,-0.164011,-0.133015,0.270476,0.058539,-0.211057,0.209024,0.034754,-0.146824,-0.275687,0.263043,-0.062172,0.190045,0.393062,-0.177671,-0.008466,-0.008466,0.606296,-0.349940,0.204885,0.027461,0.176134,0.062327,0.049522,0.070934,0.092430,0.062382,-0.169346,-0.198954,-0.968294,-0.139275,0.102618,0.064300,-0.543850,0.710125,-0.258332,-0.040042,0.321813,0.071561,0.094236,-0.099959,0.106196,0.059447,0.328901,0.249457,0.170661,0.447642,0.549623,0.073858,-0.412328,0.091625,-0.344258,-0.621081,-0.243326,-0.539756,-0.515908,0.055956,0.296736,-0.163341,0.139631,0.160297,-0.307485,0.142960,-0.191525,-0.254457,-0.117229,-0.206770,0.084370,-0.865944,-0.119828,-0.342766,-0.053227,-0.311627,0.023404,-0.246371,1.269516,-0.745631,0.089495,0.696763,-0.037794,-0.191795,0.695610,0.077449,-0.052261,-0.375085,-0.443001,0.306681,0.088776,0.200512,-0.324572,0.569794,0.053423,-0.400079,-0.364510,0.518949', '27602116', '24284209', '1870681', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3072086', '和莎莫的500天', '剧情', '来自新泽西的汤姆（Joseph Gordon-Levitt约瑟夫•高登-莱维特 饰）是一个沉溺于英伦哀歌与《毕业生》情境的年轻人。他供职于一家贺卡公司，任务是撰写富有创意的祝辞。某次会议上，汤姆的老板把新助理介绍给大家，她是来自密歇根的魅力女孩莎莫（Zooey Deschanel 佐伊•丹斯切尔 饰）。莎莫自幼父母离异，因此对于感情的态度与众不同。汤姆和莎莫没有一见钟情，但却在一次酒吧K歌后彼此示好，成了非典型的恋人。而且这段办公室恋情迅速升温，爱火烧得谁都无法预料。最后，在一个餐馆里，莎莫对汤姆说了绝情的分手。深陷情网的汤姆，经受不住失恋的打击，郁郁寡欢，周围的伙伴们希望帮他走出阴影，然而，这并不是故事的全部，本片以汤姆的视角把时间重新组接，让观众在对比中体味500天恋爱的弦外之音……©豆瓣', '约瑟夫·高登-莱维特', '马克·韦布', 8, 421768, 'tt1022603', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p455251312.jpg', 0.4, 1.9, 22.1, 48.3, 27.3, '0.370771,-0.030641,-0.366657,0.682607,-0.235702,-0.244203,0.743751,0.106752,-0.511542,-0.216144,-0.032300,0.754176,-0.273116,0.555862,0.159281,0.003070,-0.348756,-0.746235,-0.078320,-0.168066,-0.281443,-0.673742,0.080973,-0.213335,-0.095519,-0.199387,0.522954,0.089842,-0.250140,0.341302,0.366037,0.364941,0.062355,0.497919,0.015308,-0.005040,0.210469,0.091409,-0.327074,0.149867,0.190125,-0.094200,-0.141348,0.432420,0.245574,0.233655,0.694134,-0.305835,-0.066949,0.142493,0.538051,-0.053686,0.114968,0.118045,0.104329,0.084540,0.284137,0.105624,-0.260397,-0.069853,-0.076035,-0.137080,-0.658769,0.035603,0.100366,0.092325,-0.459157,0.529194,-0.093677,0.110785,-0.015971,-0.132596,-0.006471,0.145167,0.578000,0.416152,-0.153429,0.099060,-0.437821,0.096832,0.735264,0.182377,-0.384221,0.564435,-0.492472,-0.456705,-0.415816,0.120592,-0.539468,-0.003373,0.293820,-0.054065,-0.045030,0.362742,-0.560565,-0.175371,-0.197250,-0.216006,0.029352,-0.437690,-0.226145,-0.487082,-0.170916,-0.374115,-0.236602,-0.173391,0.120758,-0.266862,0.793731,-0.906350,0.108449,0.539351,0.108489,-0.425595,0.910199,0.248972,-0.027228,-0.240289,-0.064752,0.439904,0.166077,-0.027056,0.375974,0.435969,-0.068878,-0.098500,-0.403298,0.564224', '30162520', '3230462', '3055049', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3072124', '玛丽和马克思', '剧情', '1976年，8岁的玛丽·黛西·丁格尔（贝丝妮·惠特摩尔 Bethany Whitmore 配音）是澳大利亚墨尔本的一个小女孩，喜欢动画片“诺布利特”、甜炼乳和巧克力。玛丽的妈妈是个酒鬼，而在茶叶包装厂工作的父亲平日只喜欢制作鸟标本。孤独的玛丽没有朋友，某一天心血来潮给美国纽约市的马克思·杰瑞·霍罗威茨（菲利普·塞默·霍夫曼 Philip Seymour Hoffman 配音）写了一封信询问美国小孩从哪里来，并附上一根樱桃巧克力棒。44岁的马克思患有自闭症及肥胖，碰巧也喜欢看“诺布利特”动画片及吃巧克力。二人的笔友关系从1976年维持到1994年，期间各自经历了许多人生起伏，直到成年的玛丽（托妮·科莱特 Toni Collette 配音）终于来到纽约看望马克思……本片获2009年法国昂锡国际动画影展最佳动画长片奖，柏林国际电影节水晶熊奖及渥太华国际动画电影节最高奖。', '托妮·科莱特', '亚当·艾略特', 8.9, 403354, 'tt0978762', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p488255145.jpg', 0.2, 0.7, 8.1, 33.4, 57.6, '0.030711,-0.336364,-0.286996,0.442853,0.215371,-0.552679,0.489042,0.270097,-0.304749,-0.177782,-0.126881,0.858049,-0.295859,0.224528,0.346570,0.252831,-0.369614,-0.528345,0.134474,-0.257205,-0.072186,-0.346423,-0.239456,-0.070120,-0.050653,-0.452717,0.225903,-0.423463,0.201169,0.526661,0.255136,0.179286,0.069729,0.128301,-0.106584,0.040683,0.499461,0.005553,-0.262369,0.223866,0.240297,-0.082545,-0.121217,-0.088791,0.394982,0.194836,0.506881,-0.078886,0.099119,-0.157579,0.553484,-0.014814,-0.042187,-0.218089,0.296995,-0.117437,0.079860,-0.016535,-0.152494,0.261064,-0.076029,-0.357487,-0.273487,-0.075765,-0.203023,0.266524,-0.491702,0.423308,-0.315619,0.199352,-0.046861,-0.241230,0.132822,0.112938,-0.040077,0.605915,0.202007,0.245903,-0.300309,0.465451,0.120151,0.013639,-0.217038,0.469364,-0.270231,-0.472014,0.127556,-0.176593,-0.397219,0.358858,0.232379,-0.325345,-0.092487,-0.032708,-0.592219,-0.119003,-0.096457,-0.474896,0.402976,0.036261,-0.381114,-0.854114,0.138580,-0.191763,0.010999,-0.375312,0.179193,-0.081244,0.666623,-0.395185,0.344254,0.602351,-0.016241,0.027035,0.768397,-0.145266,-0.335785,-0.337358,0.043017,0.412000,-0.063020,-0.258655,0.053980,0.400099,0.333180,-0.285661,-0.234047,0.396189', '26611