INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3072185', '前往希腊剧院', '喜剧', '亚伦（乔纳·希尔 Jonah Hill 饰）是一个刚离开校园，走进社会的大学毕业生，他找到的第一份工作则是在一家唱片公司做助理。可对于他自己而言，这工作干得并非那么开心，因为这个助理每天都会被人呼之则来，挥之则去，最让亚伦头疼的就是还要应付公司里那帮说着色情笑话，总是让自己难堪的同事和上司。一天，上司突然派给亚伦一个工作：要陪伴公司的签约艺人、著名摇滚歌手奥尔德斯（拉塞尔·布兰德 Russell Brand 饰）到洛杉矶的希腊剧院，完成他的演出活动。其实这本来是一件再简单不过的事，但这位奥尔德斯可不是一般人，他每天都生活在殴打记者、酒后驾车、吸毒、夜场泡马子的醉生梦死状态中，而要把这位无论白天黑夜都处于神志不清的大人物按时弄到希腊剧院去，亚伦的这趟旅途注定充满了诸多不可预知的意外……©豆瓣', '拉塞尔·布兰德', '尼古拉斯·斯托勒', 6.8, 13752, 'tt1226229', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p494392334.jpg', 1.9, 10.4, 46.4, 30.7, 10.5, '0.454854,-0.068643,-0.605719,0.523809,-0.231909,-0.437711,0.576931,0.275997,-0.433202,-0.429145,0.136791,0.852435,-0.147488,0.305853,0.504053,0.014783,-0.254984,-0.475218,-0.002121,-0.202593,-0.109365,-0.360287,-0.015286,-0.317777,-0.108640,-0.096078,0.344688,-0.030042,0.010099,0.329263,0.166527,0.353764,0.321831,0.519317,-0.082704,-0.237428,0.223359,0.040305,-0.099931,0.256508,0.330317,-0.122203,-0.117366,0.288939,0.386748,0.301403,0.294049,0.059810,-0.290234,0.085081,0.507692,-0.491090,0.046734,0.016733,0.324045,-0.230045,0.156547,0.173039,-0.306854,0.144071,0.063452,-0.203464,-0.911125,0.054606,0.110956,0.179715,-0.686142,0.312423,-0.056804,0.002630,0.121636,-0.362019,0.364801,0.504872,0.143454,0.516229,0.092487,0.111222,-0.665845,0.398815,0.802435,0.094466,-0.197888,0.353865,-0.203547,-0.244313,0.082401,-0.269818,-0.536322,0.021806,-0.146208,-0.238924,-0.080977,0.056527,-0.540525,-0.014121,0.096613,-0.390789,-0.232158,-0.520271,-0.022504,-0.721865,0.096162,-0.185223,-0.172719,0.154162,0.370224,-0.229138,0.506140,-0.797782,0.152154,0.912150,0.250561,-0.604759,0.903651,0.175377,0.173677,-0.126586,-0.179154,-0.047021,0.181923,0.475151,-0.100018,0.556602,0.302776,-0.344543,-0.370487,0.439566', '1793491', '1299628', '1308842', '4604803');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3072779', '监狱生活', '剧情', '韦德·波特（斯蒂芬·多尔夫 Stephen Dorff 饰）有一个甜蜜的家庭，温柔贤惠的妻子和天真可爱的儿子。他还幸运地申请到了工商业贷款，准备在来年大干一番。某夜，正当全家熟睡之际，突然房间里进来了盗贼，约翰保护好妻儿后，追击盗贼，在对方准备掏凶器时，他出于自卫挥起大棒，结果盗贼当场毙 命。约翰因此锒铛入狱，由于他未选择抗辩因此被判3年有期徒刑，还获得了减刑。然而，在进入牢狱之后，他才发现铁窗的日子其实跟黑社会差不多。一个通缉犯在押解途中，被捅死，原因是其吞了帮派的毒品。狱警希望约翰可以出面指证，但是约翰怕惹事，并未就范。于是，他跟狱警结下了梁子。跟他同屋的狱友，曾是一个帮派的头领，他教会了约翰应该如何融入这个肮脏的环境。为了能跟妻儿重逢，约翰被迫加入了纳粹帮，从此卷入了一场血腥的争斗……©豆瓣', '斯蒂芬·多尔夫', '里克·罗曼·沃夫', 7.7, 14381, 'tt1117385', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1210689821.jpg', 0.3, 1.9, 28.7, 50.9, 18.3, '0.231288,0.000491,-0.462484,0.223519,-0.324911,-0.484593,0.654573,0.208645,-0.472873,-0.089915,0.170626,0.537825,-0.027737,0.126192,0.250508,-0.150504,-0.344230,-0.670558,0.012820,-0.099862,-0.300054,-0.366611,-0.156768,-0.322906,-0.104914,-0.324160,0.439006,-0.040793,-0.056886,0.271513,0.185959,0.292438,-0.069834,0.466364,-0.186209,0.163186,0.144426,-0.109523,-0.399955,0.266294,0.110245,-0.365144,-0.199224,-0.017870,0.041033,0.444337,0.547545,-0.188092,-0.040556,-0.148972,0.168725,-0.341871,-0.231434,0.304190,0.300180,-0.171407,0.255234,0.186850,-0.148499,-0.019889,0.101779,-0.134888,-0.508791,-0.028467,-0.104744,-0.105740,-0.577287,0.425747,-0.209276,0.270834,0.073247,-0.233415,0.073271,0.489952,0.160411,0.240796,-0.140794,0.018409,-0.620913,0.197571,0.728693,-0.252383,0.070410,0.108844,0.035663,-0.482866,0.014119,-0.213229,-0.271734,-0.154748,0.593439,-0.062591,-0.417495,0.088045,-0.536484,-0.249134,-0.401729,0.060182,0.066023,-0.361482,-0.101871,-0.120249,-0.190344,0.000684,-0.346907,0.117560,-0.074890,-0.044049,0.418735,-0.706262,0.317253,0.654821,0.356514,-0.564835,0.568853,0.163819,0.203206,-0.007070,0.071688,-0.073613,0.363994,0.309915,0.568928,0.279441,-0.018769,-0.264779,-0.014888,0.107400', '1947080', '1308755', '1292584', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3072804', '护送钱斯', '剧情', '2004年，美国在伊拉克的战争仍未有结束的迹象，而前方战士的伤亡则一直在增加……美国海军陆战队上校迈克（凯文·贝肯 Kevin Bacon 饰）接受了一项任务：护送一等兵钱斯的遗体回乡安葬，尽管迈克与钱斯素不相识，后者又并非他的下属，但参加过海湾战争的迈克认为有责任帮助这位科罗拉多同乡入土为安。与此同时，钱斯和战友们的遗体从欧洲的机场开始了回家之路，在凝重的氛围中，他们的遗体被仔细的清理、编号，小心翼翼的摆放在灵车中……经过了相关礼仪的培训后，迈克踏上了护送的路途，一路上，他感受到了形形色色美国民众对于战死他乡的战士的敬意，这不单是一次护送，同时也是迈克与死者的一次无声对话……©豆瓣', '凯文·贝肯', '罗斯·卡兹', 8.2, 11024, 'tt1019454', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2499101149.jpg', 0.6, 2, 18.5, 46.2, 32.7, '0.197128,-0.154898,-0.945376,0.633364,-0.140725,-0.464740,0.709939,-0.019621,-0.524916,-0.195989,0.425208,0.857876,0.096529,0.195960,0.444983,-0.275023,-0.586264,-0.614836,-0.282562,-0.265441,-0.616297,-0.564374,-0.137514,-0.321538,-0.083330,-0.489304,0.562782,0.125588,0.017347,0.864919,0.119373,0.314318,-0.093478,0.636854,-0.195327,-0.084232,0.262681,-0.116326,-0.338794,0.042629,-0.118336,-0.365695,-0.287668,0.059612,0.256036,0.574880,0.885032,-0.228948,-0.055546,0.010250,0.037656,-0.329157,0.271286,0.075293,0.418436,0.290191,0.057254,0.543120,-0.082285,-0.037087,-0.191962,-0.040392,-0.786800,-0.120613,-0.051039,0.266631,-0.781362,0.692766,-0.222829,0.084706,-0.133586,-0.344327,0.356559,0.446372,-0.008541,0.393911,-0.158804,-0.080027,-0.331422,0.172034,0.778968,-0.093375,-0.148914,0.166543,-0.236892,-0.639791,0.130156,-0.029556,-0.365361,-0.030137,0.294428,0.046187,-0.059076,0.105145,-0.671357,0.085187,-0.339318,-0.666717,-0.178563,-0.307418,0.051033,-0.841170,0.044838,-0.496325,-0.286699,0.129034,0.120509,-0.027048,0.856939,-0.595140,0.301952,0.459286,0.257575,-0.534616,0.707450,0.146065,0.335646,-0.069677,-0.096967,0.225933,0.187617,0.535050,0.240107,0.404000,-0.037501,-0.089578,-0.352146,0.402778', '2159244', '3811356', '1303333', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3072822', '逃亡乐队', '剧情', '在20世纪70年代以前，摇滚乐还是男性的天下，即使它的影响力以遍及世界各地，但全女子的摇滚乐团却从未出现。18岁的琼·杰特（克莉丝汀·斯图尔特 Kristen Stewart 饰）是一个狂迷摇滚乐的叛逆女孩，她始终渴望组建一支女子摇滚乐团。在经纪人金·弗利（麦克·谢农 Michael Shannon 饰）的帮助下，他们找到了15岁的切丽·柯里（达科塔·范宁 Dakota Fanning 饰）——与琼同样来自南加州且喜爱大卫·鲍伊的女孩——担任主唱。在此之后，吉他手丽塔·福特（Scout Taylor-Compton 饰）、鼓手珊蒂·韦斯特（Stella Maeve 饰）、贝司杰基·福克斯先后入队，全女子乐队“逃亡”正式成立。女孩们由此展开了多姿多彩、忧喜相伴的音乐之旅……本片根据切丽·柯里（Cherie Currie）的自传改编。©豆瓣', '克里斯汀·斯图尔特', '弗洛莉娅·塞吉斯蒙迪', 7, 19335, 'tt1017451', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p458986068.jpg', 1, 6.1, 44.6, 36.4, 11.9, '-0.105858,-0.073013,-0.471439,0.498877,-0.137010,-0.172338,0.608878,0.164429,-0.548775,-0.198942,0.168840,0.818152,-0.120189,0.175504,0.479148,0.072599,-0.328208,-0.691192,0.004033,-0.340912,0.149308,-0.304792,-0.301829,-0.134241,0.091336,-0.523683,0.735829,-0.172369,-0.079361,0.475192,0.514558,0.304535,-0.190407,-0.090639,-0.033258,0.008640,0.442543,-0.016241,-0.226460,0.169740,-0.371038,-0.293640,-0.166429,-0.200034,-0.182503,0.375409,0.554537,-0.426251,0.310434,-0.073142,0.408693,0.224583,-0.164032,-0.203959,0.224603,-0.126926,0.242695,0.052990,-0.092197,-0.099609,-0.228611,-0.229245,-0.480696,0.354815,0.277948,0.319001,-0.554579,0.321045,-0.365341,0.030392,-0.099032,-0.120384,-0.123868,0.101101,0.143448,0.219070,0.146826,0.273032,-0.172932,0.294257,0.446514,0.374380,-0.481983,0.069469,-0.529483,-0.508560,-0.452050,-0.151551,-0.752407,-0.008575,0.237559,-0.111778,0.282128,0.031799,-0.541475,-0.101341,-0.267464,-0.066371,0.180381,0.036592,-0.052363,-0.941542,0.096030,-0.396595,-0.051900,-0.117227,0.226159,-0.226731,0.921816,-0.811181,0.266855,0.295372,0.071372,-0.063823,0.370295,-0.154514,0.076877,-0.367050,-0.323156,0.731947,0.003600,-0.241426,-0.021854,0.322503,-0.096034,-0.204916,-0.072725,0.426357', '3811356', '259