INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3072888', '爸爸的好儿子', '喜剧', '13岁的风流小子唐尼（亚当·桑德勒 Adam Sandler 饰）生性放荡不羁，抽烟酗酒不在话下，更离谱的是，他竟然与自己22岁的女老师发生了关系还使其怀了孩子，老师入狱，将孩子汉（安迪·萨姆伯格 Andy Samberg 饰）托付给了唐尼。然而唐尼依旧是那个风流少年，根本没有尽到一个靠谱父亲的责任，于是当汉年满18岁，变愤然离开了父亲。如今42岁的唐尼已经变成一个百无聊赖的酒鬼，欠下的税还足够让他在监狱里蹲三年。然而一个偶然的机会，唐尼在报纸上得知自己的儿子汉如今已经事业有成并大婚在即，为了避免牢狱之苦，他决定重新修复与儿子的关系以寻求资助。然而不请自来的父亲并没有得到儿子的欢迎，两人之间发生的一系列激烈碰撞不仅将汉一家搅得鸡犬不宁，还顺带把婚事也搞黄了……©豆瓣', '亚当·桑德勒', '西恩·安德斯', 6.7, 16669, 'tt1232200', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1501295159.jpg', 2.6, 11.2, 46.3, 28.3, 11.5, '0.278139,0.038810,-0.650507,0.318862,-0.509539,-0.448815,0.663303,0.198755,-0.552314,-0.287228,-0.027212,0.712348,-0.163977,0.471964,0.205283,-0.132683,-0.036973,-0.773761,0.002980,-0.043968,-0.118281,-0.682069,-0.169224,-0.114932,-0.192570,-0.487839,0.426362,-0.082201,0.107970,0.311786,0.430552,-0.029040,0.106304,0.596787,-0.265565,0.140121,-0.036146,0.073931,-0.010080,0.167925,0.145914,-0.467811,0.176573,0.112779,0.041800,0.494334,0.621733,-0.141647,-0.271855,-0.091718,0.455513,0.064378,-0.328557,0.203441,0.348375,-0.282208,0.218793,0.318142,-0.268910,-0.205420,0.105365,-0.193361,-0.550717,0.060894,0.038518,-0.034957,-0.759538,0.574603,-0.085176,-0.045463,-0.015870,-0.257768,0.215824,0.492998,0.110261,0.397987,-0.357860,0.023215,-0.603191,0.127425,0.553535,-0.090948,-0.137719,0.389654,-0.100843,-0.265039,-0.039688,-0.410463,-0.455539,0.091662,0.091795,-0.150729,-0.191033,0.202485,-0.216359,-0.111465,-0.480144,-0.022386,0.108272,-0.249776,0.030474,-0.215644,-0.268685,-0.318752,-0.326421,0.122915,0.071528,-0.472385,0.457867,-0.634079,0.211956,0.299433,0.237556,-0.388358,0.652271,0.133053,0.344952,-0.217851,-0.100869,0.152366,0.163250,0.089451,0.201869,0.228197,0.074011,-0.200859,0.004201,0.286611', '35461732', '1301022', '1302384', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3072889', '龙虎少年队', '喜剧', 'Morton Schmidt（乔纳·希尔 Jonah Hill 饰）和Greg Jenko（查宁·塔图姆 Channing Tatum 饰）两人是同学，后来又在警校相逢，两人互相帮忙，终于顺利从警校毕业，成为了好搭档。无奈两人只能当交警，抓抓小混混。后来他们加入了警方的卧底缉毒组织“21 Jump Street”，队长Dickon（艾斯·库珀 Ice Cube 饰）告诉他们，他们的任务是重回高中当卧底，找到那个向学生提供毒品的人。在学校里，他们了解到，学生们的毒品是从一个叫Eric（戴夫·弗兰科 Dave Franco 饰）的人手里来的，但案件并没有这么简单。同时，Schmidt也喜欢上Eric的一个朋友Molly，Jenko的化学老师似乎也对他挺感兴趣的。到底两人在学校的卧底调查会有怎样的结果？本片改编自同名电视剧。©豆瓣', '乔纳·希尔', '菲尔·罗德', 6.9, 32963, 'tt1232829', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1467624554.jpg', 1.1, 7.3, 47.2, 33.7, 10.7, '0.543535,-0.424206,-0.449648,0.401741,-0.201559,-0.276586,0.581679,-0.120495,-0.664651,-0.185682,0.126090,0.771763,-0.095286,0.170769,0.137614,0.008720,-0.565110,-0.816381,0.156716,-0.507552,-0.427937,-0.515931,-0.330939,-0.262764,0.008480,0.028552,0.534562,-0.124349,-0.220834,0.551847,0.424861,0.303036,-0.171191,0.296305,-0.267874,-0.019288,0.318500,0.071445,-0.267985,0.136550,0.044333,-0.149860,-0.357837,-0.221007,0.428093,0.451948,0.546321,0.097781,-0.180240,0.202525,0.204563,-0.388673,-0.119669,-0.051964,0.522364,0.016794,0.291407,0.084385,0.067193,-0.045240,-0.099080,-0.149223,-0.710302,0.029597,0.092901,0.313984,-0.561724,0.404529,0.006160,-0.055013,0.210078,-0.331085,0.204937,0.402215,0.108001,0.339650,0.021706,-0.061589,-0.451672,0.267220,0.666957,-0.104680,0.005368,0.237542,-0.051818,-0.610744,-0.176914,0.022834,-0.352268,0.297896,0.391752,-0.097398,-0.146008,-0.106461,-0.497266,-0.147389,0.120206,-0.049581,0.087520,-0.613429,0.028698,-0.617212,0.007007,-0.180788,-0.378593,0.102636,-0.068185,-0.264578,0.791071,-1.039911,-0.033090,0.626993,0.187575,-0.563993,0.689410,0.171446,0.010362,-0.417289,-0.224899,-0.305262,0.386737,0.424119,0.284324,0.620011,0.287478,-0.512162,-0.242940,-0.093836', '4127270', '35030151', '4301278', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3073071', '新乌龙女校2：弗里顿的黄金的传奇', '喜剧', '翻拍50年代经典伊灵喜剧的《新乌龙女校》（St. Trinian''s）系列第二部，上一集的转校生Annabelle Fritton 已晋升为新的大姐大（head girl）。根据上世纪50年代的《乌龙女校》，改编的《新乌龙女校》在2007年取得了巨大成功。如今续集《新 乌龙女校2》已经登陆英国的银幕，新片中又讲述了怎样的离奇故事呢？影片中女学生们发现，校长竟然是一位著名海盗的后代，于是她们开始了探秘之旅，共同寻找埋藏的海盗宝藏。有着模特身材的80后英国美女，塔姆欣·伊格顿扮演了片中的女主角，“乌龙女校”女学生组织的领军人物切尔西。塔姆欣表示，相比第一部《新乌龙女校》，这部续集将故事的重心更多放在了女学生身上，《新乌龙女校2》已经于18号在英国上映。这一集主要讲述女校学生们发现校长是一位著名海盗的后代，从而出发寻找埋藏的黄金的故事。《新乌龙女校》汇集众多英伦新星，女校学生还包括了过去的邦女郎，如今的《诸神之战》和《波斯王子》女郎杰玛·阿特登以及《赎罪》的朱诺·坦普尔等人。上一部的鲁伯特·艾弗雷特、科林·费尔斯和拉塞尔·布兰德将继续出演，“神秘博士”大卫·田纳特最新也加盟本片。', 'Rupert Everett', 'Oliver Parker', 6.4, 10154, 'tt1210106', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1640830689.jpg', 2, 14, 52.5, 22.5, 9, '0.285852,-0.187499,-0.299290,0.501450,0.437691,-0.265978,0.302102,-0.083051,-0.365859,-0.218134,0.214925,0.751397,-0.405512,0.253585,0.550304,0.026460,-0.704805,-0.592625,-0.151682,-0.422056,-0.174940,-0.268159,-0.410374,-0.021902,-0.096653,-0.416046,0.777240,-0.037660,-0.184807,0.257177,0.561399,0.361027,-0.105896,-0.094577,-0.038141,0.191302,0.378257,0.030580,-0.169604,0.311385,0.006247,-0.201323,-0.211877,-0.119800,0.211886,0.297071,0.592870,-0.277013,0.213606,-0.221764,0.761681,0.010056,-0.224902,-0.187110,0.477083,0.098707,0.208216,0.187018,0.023310,-0.135222,-0.178468,-0.526527,-0.505332,-0.066832,0.240181,0.233952,-0.395676,0.289572,0.008905,0.083755,0.208388,-0.130031,0.056577,0.241256,0.407987,0.280068,0.313876,0.286183,0.035626,0.590555,0.417073,0.100060,-0.333284,0.146931,0.011907,-0.520805,-0.139994,-0.226220,-0.471711,0.319251,0.402762,-0.113766,0.198520,0.354177,-0.756943,-0.160139,-0.466399,-0.307263,0.262674,-0.061751,-0.170681,-0.946554,-0.107064,0.064654,0.172597,-0.267614,0.308961,-0.240778,1.073272,-0.627179,0.101852,0.513049,0.081739,-0.211601,0.497149,-0.180725,0.215325,-0.273681,-0.252803,0.117005,-0.015337,0.314111,-0.105244,0.470114,-0.100615,-0.610112,-0.153042,0.420493', '1322847', '25863940', '27602116', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3073073', '简爱', '剧情', '从小失去父母的简·爱（米娅·华希科沃斯卡 Mia Wasikowska 饰）寄居在舅妈家，自幼受尽表兄（克雷格·罗伯兹 Craig Roberts 饰）欺辱和舅妈（莎莉·霍金斯 Sally Hawkins 饰）冷眼，稍大些后即被送入管教严格的教会女子学校。在冷漠、刻板环境中长大的简·爱并没有成为心理扭曲的女孩，而是自立自强，还 积累了不凡的学识修养，成年后她成为桑菲尔德贵族庄园的家庭教师。男主人罗切斯特先生（迈克尔·法斯宾德 Michael Fassbender 饰）第一次露面时，与简·爱相识于一场堕马事故，随着二人慢慢熟悉，罗切斯特先生体会到简·爱的与众不同，并渐渐爱上她，简·爱亦受到罗切斯特先生的强烈吸引，但是大宅夜晚总会发生一些怪事，二人的爱情似乎蒙着一层阴影……本片根据英国作家据夏洛蒂·勃朗特原著改编，是这部名著第18次被搬上大银幕。©豆瓣', '迈克尔·法斯宾德', '凯瑞·福永', 7.5, 69429, 'tt1229822', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1590555816.jpg', 0.3, 2.7, 33.1, 47.1, 16.7, '0.100339,-0.048467,-0.545293,0.516835,0.019436,-0.480129,0.749135,0.138687,-0.475983,-0.522311,-0.149191,0.752142,-0.205323,0.367478,0.368598,0.114021,-0.092614,-0.441056,-0.099837,-0.091929,-0.067151,-0.468109,-0.111748,-0.338941,-0.156095,-0.641612,0.383654,0.126503,-0.417917,0.339237,0.203194,0.449492,-0.281204,0.273136,0.059900,0.085434,0.009591,0.234734,-0.493154,-0.062812,0.100705,0.041032,-0.099461,-0.184701,0.205838,0.100171,0.679039,-0.221695,-0.290467,-0.245221,0.443529,0.105608,-0.050669,0.086548,0.325968,-0.018730,0.161336,0.429516,0.120168,0.181039,-0.160215,-0.292204,-0.195649,-0.316685,0.412633,-0.040356,-0.282033,0.656776,-0.045361,-0.180972,-0.135770,-0.160139,-0.004751,-0.023924,0.310205,0.120784,-0.020007,0.076754,-0.197509,0.176213,0.420418,0.269066,-0.399535,0.287273,-0.467616,-0.462478,0.117259,-0.259148,-0.733173,0.382954,0.219459,0.149819,-0.132512,0.429811,-0.181616,-0.300904,-0.212868,-0.000661,0.169116,-0.538095,-0.073091,-0.647152,-0.388369,-0.672184,-0.064227,0.028099,-0.202807,-0.270379,0.572400,-0.732395,0.628587,0.119594,0.115847,-0.257508,0.469680,0.026118,0.003127,-0.194479,-0.151350,0.647993,0.156052,-0.082713,0.003772,0.075794,-0.142152,0.120821,-0.274633,0.525621', '1422992', '1296