INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3073117', '少许灰烬', '剧情', '这是一部关于西班牙三位后现代大师——大画家萨尔瓦多·达利（罗伯特·帕丁森 Robert Pattinson 饰），诗人加西亚·洛尔迦（哈维尔·贝尔特兰 Javier Beltrán 饰）以及电影大师路易斯·布努艾尔（马修·麦克诺提 Matthew McNulty 饰）年轻时代的电影。故事发生在1922年的西班牙，当时的传统价值正受到了新文化浪潮的冲击。进步青年洛尔迦和布努艾尔是大学里的风云人物，达利则是一名刚刚进入大学的新生。才华横溢而又害羞局促的达利很快引起了二人的注意，他们主动结识了达利，并带他参加各种小社团活动。渐渐地，达利性格中狂放不羁的一面深深地吸引着洛尔迦，心灵的契合和灵魂的相通使二人的关系向着爱情的方向发展。发现了这一切的布努艾尔把达利带去了巴黎，二人在后现代艺术中尽情施展才华。两人分道扬镳后走上了截然不同的道路，洛尔迦成了当时反法西斯的重要带头人，而达利只沉迷于名利中，不关心政治。后来，洛尔迦却因政治斗争而丧命，达利闻讯悲痛不已，在画纸上疯狂地涂抹……', '哈维尔·贝尔特兰', 'Paul Morrison', 7.3, 7757, 'tt1104083', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p769237027.jpg', 1, 6.6, 37, 39.3, 16.1, '0.623762,-0.004462,-0.719953,0.509679,0.120549,-0.321215,0.756566,0.140833,-0.482662,-0.148821,0.101050,0.736812,-0.400724,0.115780,0.460873,0.105564,-0.331577,-0.771913,-0.037164,-0.285070,-0.150185,-0.635324,-0.432617,0.059562,-0.369165,-0.542039,0.435451,-0.027493,-0.232254,0.701328,0.028953,0.386844,-0.085200,0.259797,0.168190,0.123413,0.349596,-0.101132,-0.256820,0.068151,0.133001,-0.065207,-0.345615,0.103583,-0.177076,0.318966,0.384276,-0.375433,0.364883,-0.075147,0.320847,-0.063314,0.095245,0.213702,0.059335,-0.051515,0.183153,0.393933,-0.139613,0.080005,-0.005084,-0.103945,-0.569347,0.100252,0.070556,0.401598,-0.580757,0.555412,-0.069291,-0.239193,0.126921,-0.186163,0.082423,0.276576,0.351306,0.541302,0.106209,-0.031006,-0.230479,-0.015270,0.508006,0.150065,-0.424192,0.367456,-0.257668,-0.304915,-0.116133,-0.174466,-0.465904,-0.057595,0.497575,0.137803,0.152558,0.449953,-0.719180,0.037181,-0.261557,-0.249118,0.070832,-0.031471,-0.117417,-0.891846,-0.346095,-0.723775,-0.073603,-0.322020,-0.005486,-0.176200,0.854246,-0.700978,0.061551,0.468576,0.233763,-0.178426,0.595400,-0.045862,0.096056,-0.071863,-0.300763,0.226726,-0.046979,0.187110,0.074171,0.511218,0.105598,-0.173934,-0.271951,0.603337', '30162520', '3811356', '1301172', '19965431');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3073124', '月球', '剧情', '未来世界，随着科技的飞速进步，地球的污染也越来越严重。为了遏制这种现状，一家名为月能工业有限公司的企业应运而生。该公司致力于月球能源的开发，通过采集氦-3来满足地球对能源的需求。月能公司在月球设有基地，山姆·贝尔（山姆·洛克威尔 Sam Rockwell 饰）正是该基地 上唯一的工作人员。山姆是公司聘用的合同工，他已在月球孤零零地生活3年，陪伴他的只有智能机器人戈蒂（凯文·斯派西 Kevin Spacey 饰）。枯燥乏味的生活令山姆归心似箭，在还有两周就离开月球的时候，山姆偶然遭遇一起事故。醒来后的他发现戈蒂似乎对其有所隐瞒，公司高层也拒绝他的回程请求。山姆借机逃出基地，却在事故发生地点发现另一个自己……本片荣获2009年爱丁堡国际电影节最佳英国影片奖、2009年西雅图国际电影节最佳男主角奖。©豆瓣', '山姆·洛克威尔', '邓肯·琼斯', 8.5, 257565, 'tt1182345', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p449399746.jpg', 0.2, 0.8, 11.9, 47, 40.1, '-0.271083,0.341225,-0.777821,0.311685,0.181440,-0.138068,0.232269,-0.011883,-0.477122,-0.102584,0.242466,0.764174,-0.114076,0.081942,0.385942,0.120019,-0.500663,-0.257189,0.102389,-0.448640,-0.312176,-0.514730,-0.378210,-0.518896,-0.069024,-0.295346,0.791116,0.183235,-0.005585,0.126476,-0.049419,0.271358,-0.030589,0.461676,-0.024136,-0.095853,0.296167,-0.043400,-0.537601,0.305334,-0.096715,-0.106643,-0.007912,-0.046571,0.210323,0.145840,0.584657,0.076841,-0.246858,-0.340587,0.520636,-0.160294,0.039269,-0.518817,0.604329,-0.181790,-0.178338,0.308308,-0.235486,-0.119548,0.186697,-0.186358,-0.572048,0.079862,-0.054335,0.070529,-0.452846,0.214161,-0.242708,-0.024984,-0.072699,-0.470337,0.118717,0.842135,0.278450,0.351163,-0.073756,0.469941,-0.443522,0.338799,0.484307,-0.067555,-0.517439,0.464868,-0.177335,-0.560115,-0.378279,-0.236262,-0.264588,-0.198148,0.098824,0.173618,-0.220450,0.237611,-0.440445,0.228582,-0.077040,-0.554916,0.355238,-0.159053,0.114794,-1.113006,0.073405,-0.173030,-0.143843,-0.045112,0.090641,-0.152586,0.450018,-0.744989,0.216317,0.773345,0.602159,-0.443766,0.712227,-0.072005,0.092953,-0.329949,-0.263094,0.507270,-0.268259,0.516292,-0.315027,0.151688,0.384567,-0.342099,-0.197143,0.226774', '3871833', '2369613', '34961898', '30229667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3073158', '铁娘子：坚固柔情', '剧情', '耄耋之年的撒切尔夫人（梅丽尔•斯特里普 Meryl Streep 饰）罹患老年痴呆症，时常在幻觉和回忆中切换。她感觉深爱的丈夫一直在身边陪伴，其实后者早已亡故。她作为杂货店的女儿，因为出身贫寒，时常饱受世人的白眼。然而，在聆听了保守党的演讲后，她坚定了自己的政治信仰，并以优异成绩考入牛津大学，虽然在一次议员选举中落败，但是她却收获了真挚的爱情与他相伴，坚定了自己从政的人生道路。从此，她逐渐走到了保守党魁的位置。终于，保守党在选举中大胜，而她也成为了英国历史上第一位女首相，组建了自己的内阁政府。面对纷繁复杂的国际国内局势，她力主的自由市场政策也饱受非议，但是她用过人的智慧和超强的忍耐力，战胜了左辅右弼众叛亲离的局面，凭一己之力拯救了英国经济，捍卫了领土主权，被世人称作铁娘子……©豆瓣', '梅丽尔·斯特里普', '菲利达·劳埃德', 7.6, 70872, 'tt1007029', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1223336524.jpg', 0.3, 2.9, 30.8, 47.5, 18.5, '-0.071052,0.329033,-0.742125,0.798166,-0.199709,-0.315675,0.548650,0.354209,-0.580559,0.005266,0.262686,1.088894,-0.007349,0.313291,0.204691,-0.074200,-0.152238,-0.876620,-0.023479,-0.054906,-0.190690,-0.463947,-0.440674,-0.328326,-0.395158,-0.223332,0.879935,0.171650,-0.272545,0.287037,0.259696,0.280590,0.281942,0.678665,-0.208937,-0.019681,0.094799,-0.018902,-0.270176,0.059627,0.112260,-0.542874,-0.255140,0.457974,-0.077533,0.377929,0.470425,-0.477702,0.014014,-0.294453,0.349920,-0.391002,-0.206789,0.392650,0.364540,0.094909,0.049515,0.421598,-0.123506,-0.181547,-0.075833,-0.058044,-0.746996,-0.244812,-0.048446,0.153809,-0.574548,0.831299,-0.134220,-0.122076,-0.204985,-0.014350,0.119575,0.302020,0.002679,0.354626,-0.400618,-0.045817,-0.407282,0.295969,0.550013,0.092625,-0.620685,0.276377,-0.403649,-0.404833,-0.081440,-0.636422,-0.456996,-0.260854,0.203894,0.066931,-0.125621,0.470814,-0.427837,-0.025094,-0.295304,-0.176066,-0.153125,-0.611112,0.107935,-0.353051,-0.387412,-0.516456,-0.367964,-0.088134,0.151585,-0.343474,0.897228,-0.914915,0.029882,0.536337,0.463101,-0.603865,0.708840,0.129740,0.231651,-0.150412,-0.178284,0.499348,-0.229246,0.267638,0.112951,0.222887,-0.036218,0.038969,-0.272896,0.827230', '1870681', '1303034', '30162520', '1309183');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3073268', '传奇的诞生', '剧情', '本片讲述了球王贝利儿时从贫民窟擦鞋童，靠自己的努力克服重重阻碍，逆转绝境成为足球世界最强者的故事。影片揭秘了贝利成名前不为人知的经历，家境贫穷、旁人的冷眼、队友的排挤并没有阻碍贝利的成长，父母的教育一直影响着贝利，从被人贬低到万人瞩目，他一个人的逆袭，燃动了数十亿人的斗志。', '凯文·德·保拉', '杰夫·泽姆巴利斯特', 7.7, 28924, 'tt0995868', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2531286907.jpg', 0.3, 3.1, 30.2, 45.6, 20.9, '0.007834,-0.228058,-0.524651,0.725204,-0.256365,-0.231592,0.783448,0.352977,-0.432239,0.151194,0.475803,0.776009,-0.325794,0.134160,0.398713,-0.284758,-0.062355,-0.837955,0.038119,-0.104519,-0.262122,-0.418522,-0.412196,-0.359182,-0.154076,-0.536325,0.669466,0.176736,-0.750005,0.199305,-0.066913,0.137859,0.115314,0.571925,-0.084552,0.391566,0.009388,0.204196,-0.208260,0.010692,-0.469919,-0.435392,-0.196755,0.220297,-0.272433,0.148724,0.674893,-0.367742,0.120968,-0.012434,0.433353,-0.430796,-0.129850,0.057885,0.243840,-0.275463,0.015395,0.152839,0.399513,0.001366,0.008849,-0.297335,-1.051339,-0.339328,0.018681,0.172749,-0.890998,1.083213,0.018309,0.046476,-0.080937,0.036707,-0.035699,0.178599,0.052010,0.411300,-0.416784,0.001142,-0.601964,0.538508,0.558485,-0.322410,-0.597358,0.288715,-0.468074,-0.492982,-0.390069,-0.344448,-0.812163,-0.096716,0.593471,0.227911,-0.448944,0.770452,-0.381928,0.203238,-0.114655,-0.354423,-0.043932,-0.797291,-0.206506,-0.498819,-0.423232,-0.270457,-0.221477,-0.165782,-0.107832,-0.379050,1.153613,-0.415936,0.290092,0.929833,0.184093,-0.342412,0.772385,-0.181988,0.145850,-0.103469,-0.309982,0.817172,-0.159394,0.526905,0.093648,0.236514,-0.211533,0.044241,-0.335462,0.882926', '27602116', '26315728', '26348103', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3073281', '伴侣度假村', '喜剧', '婚前热情如火的情侣们，婚后却未必如此。当柴米油盐取代了浓情蜜意，生活的裂缝就渐渐暴露出来：杰森（杰森·贝特曼 Jason Bateman 饰）与妻子辛西娅（克里斯汀·贝尔 Kristen Bell 饰）因为不孕症考虑离婚，乔伊（乔恩·费儒 Jon Favreau 饰）和露西也已经对对方身体没有兴趣，戴夫（文斯·沃恩 Vince Vaughn 饰）和萝尼则整日被房子和孩子的压力弄得心烦意乱。眼看曾经令人艳羡的婚姻就要面临崩溃，杰森夫妇决定最后一搏，他们费尽心力想出一个度假疗法，说服几对欢喜冤家们前往一个热带小岛二度蜜月。异国的碧海蓝天似乎让这些中年夫妇又重拾热情，但度假村老板马塞尔（让·雷诺 Jean Reno 饰）提供的硬性课程又让他们摸不着头脑：雷人不浅的猛男瑜伽、夫妻按摩、与鲨同游真的能唤醒这些夫妻的情感，拯救他们的婚姻么？©豆瓣', '杰森·贝特曼', '彼得·比灵斯雷', 6, 5855, 'tt1078940', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1544116521.jpg', 3.8, 17.2, 57.4, 18, 3.6, '0.208324,-0.151604,-0.557240,0.478997,-0.057629,-0.437614,0.813595,0.121028,-0.179319,-0.171860,0.108136,0.548556,-0.296759,0.184547,0.300490,0.170512,-0.420699,-0.615213,0.111879,0.005734,-0.149747,-0.461403,-0.170461,-0.259388,-0.124716,-0.074567,0.495145,-0.083192,-0.054239,0.559914,0.190003,0.215849,0.079870,0.314306,-0.006247,0.046372,0.036055,0.239393,-0.388286,-0.086449,0.057027,0.153527,-0.161343,0.411008,0.175021,0.236901,0.502641,-0.222820,-0.163181,-0.015131,0.125963,-0.148568,0.141607,0.380601,0.055843,-0.373704,0.316195,-0.019901,-0.180252,-0.149715,0.181343,0.090610,-0.713600,0.378410,-0.019539,-0.020307,-0.495349,0.226112,-0.043930,-0.188053,0.010219,-0.150371,0.077602,0.487924,0.234074,0.586248,-0.278802,0.034932,-0.552865,0.148745,0.666615,0.069192,-0.087503,0.211994,-0.485864,-0.175805,-0.032026,0.046219,-0.439915,-0.227960,0.318241,0.094603,-0.140911,0.272113,-0.578876,-0.076410,-0.324567,-0.102984,0.019066,-0.578839,0.183711,-0.758960,-0.143796,-0.461040,-0.285344,-0.031223,0.290305,-0.218025,0.619119,-0.652709,0.023675,0.379719,0.346200,-0.636031,0.535646,0.278233,0.166349,-0.221310,-0.097014,0.130413,-0.219486,0.033306,0.312441,0.475734,0.272137,0.143612,-0.188574,0.376189', '19965431', '4301278', '1307853', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3073647', '黑暗边缘', '剧情', '《黑暗边缘》根据1985年BBC六小时的迷你剧集改编。波士顿警局的凶杀案侦探托马斯·克莱文（梅尔·吉布森 Mel Gibson 饰），作为一名单亲父亲他对24岁的女儿疼爱有加，但天有不测风云，一天女儿被人杀死在自己家门前的台阶上。托马斯认为杀手真正的目标是自己，固执的他一头扎进这个案子中，但随着调查的深入他发现女儿的被害其实另有隐情，在案件背后是整个政府系统的腐败。©豆瓣', '梅尔·吉布森', '马丁·坎贝尔', 6.8, 9464, 'tt1226273', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p769242953.jpg', 0.9, 7.7, 49.3, 32.1, 9.9, '0.205172,0.018842,-0.676272,0.492940,-0.198368,-0.008089,0.798420,-0.082696,-0.711269,-0.439436,0.435452,0.766511,-0.002425,0.296553,0.195087,0.283255,-0.118738,-0.681380,-0.044679,-0.313167,-0.371655,-0.724953,-0.386304,-0.336158,-0.056830,-0.015255,0.670875,0.233253,-0.003068,0.220575,0.337996,0.492469,0.032266,0.212985,-0.115014,0.121119,0.413761,-0.202771,0.043384,0.268091,-0.139980,-0.217204,-0.039604,0.184330,-0.151897,0.653649,0.492235,-0.244022,-0.273507,-0.232487,0.682372,-0.425958,-0.268468,0.156306,0.773125,0.079098,0.122908,0.400852,-0.183628,-0.227802,-0.159134,-0.266188,-0.579687,-0.304372,0.214796,0.137165,-0.710816,0.156686,-0.325410,0.037145,-0.023026,-0.256260,0.094182,0.051612,0.067446,0.394588,-0.280020,0.179185,-0.508593,0.047807,0.447843,-0.042380,-0.221811,0.163373,-0.170138,-0.464242,-0.155104,-0.348276,-0.529054,0.069879,0.251435,-0.021610,-0.244809,0.262174,-0.213293,0.029328,-0.450855,-0.171609,-0.181227,-0.262029,-0.227235,-0.253468,-0.242552,-0.352041,-0.374575,-0.230381,-0.217937,-0.526144,0.549809,-0.664052,0.322262,0.666317,0.102714,-0.392675,0.853103,0.134515,0.171579,-0.416918,0.007528,0.173028,0.348569,-0.104767,-0.054443,0.221634,-0.045891,-0.404265,-0.282639,0.510490', '1302384', '3263169', '1293145', '30167633');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3073648', '坏中尉', '惊悚', '飓风后的奥尔良，全城陷入瘫痪。当地的监狱中，所有狱警和囚犯已全部撤离，却有一个囚徒被遗忘在这里。警官特伦斯•麦克多纳（尼古拉斯•凯奇 Nicolas Cage 饰）和同事巡查牢房时发现了他，特伦斯出手相助。这个英勇举动使他晋升为中尉，但他的脊柱也受到严重损伤，从此只能靠药物缓解疼痛。不断加剧的疼痛令各种药物失去效力，特伦斯在这一过程中饱受折磨，他不得以求助毒品，身体和经济状况都接近崩溃边缘，脾气也越来越糟。一个英雄警察逐渐堕落。不久，城内发生一起灭门惨案，大毒枭达费特具有重大嫌疑。特伦斯受命调查此案，在这一过程中，他泯灭已久的良知逐渐复苏……本片荣获2009年威尼斯电影节Christopher D. Smithers Foundation特别奖。©豆瓣', '尼古拉斯·凯奇', '沃纳·赫尔佐格', 7, 26172, 'tt1095217', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1077984645.jpg', 0.9, 6.2, 45.2, 38.9, 8.8, '0.047552,0.068672,-0.750702,0.162308,0.213772,-0.084751,0.975996,0.103311,-0.713487,-0.204780,0.195616,0.736176,-0.312089,0.029779,0.156434,-0.164980,-0.390294,-0.788504,-0.127976,0.036807,-0.490804,-0.293911,-0.285801,-0.310642,-0.173298,-0.673212,0.472094,0.287006,-0.304700,0.443639,0.017815,0.188732,0.121045,0.673063,0.155563,0.259958,0.395312,-0.450528,-0.084918,0.111621,0.203516,-0.527002,0.009453,0.343792,-0.091160,0.399614,0.554655,-0.189718,-0.236375,-0.327849,0.329228,-0.447284,-0.177597,0.177466,0.449282,0.060676,0.046324,0.080135,-0.400893,-0.091194,0.059209,0.158554,-0.776793,-0.126150,0.052479,0.238286,-0.254767,0.102912,0.027696,0.247707,-0.224819,-0.223177,0.168531,0.420226,0.182678,0.080405,-0.461591,-0.164151,-0.447161,-0.068902,0.893273,-0.247819,-0.652738,-0.138809,-0.377220,-0.424342,-0.055929,-0.357334,-0.237376,-0.187117,0.315009,0.190293,-0.254014,0.530398,-0.216112,-0.011172,-0.344973,-0.371187,-0.480004,0.089118,-0.181780,-0.551141,-0.437645,-0.113122,-0.220193,-0.005229,0.131774,-0.046323,0.461757,-0.490440,0.411022,0.539309,0.270109,-0.387400,0.307261,0.008787,0.253732,0.148334,-0.214762,0.282370,0.103722,0.561122,0.294260,0.169444,-0.187725,-0.019553,-0.304918,0.343545', '25828589', '1294941', '1307311', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3073875', '鱼缸', '剧情', '15岁的米娅（凯蒂·贾维斯 Katie Jarvis 饰）性格叛逆而古怪，惹事生非的她不仅被学校开除而且连她最好的朋友都离她而去。米娅热爱跳舞，然而身边却似乎并没有多少人在意她那充满热情的舞步，直到一个叫康纳（迈克尔·法斯宾德 Michael         Fassbender 饰）的男人出现。康纳是母亲的男朋友，在他与母亲同居的日子里，米娅被这个英俊而又友善的男人所吸引。在康纳的支持和鼓励下，米娅得到了一次舞蹈面试的机会，而且与康纳的关系也更进了一步。然而，现实世界并非想像的那样的美好……本片由在2006年凭借《红色之路》获得戛纳电影节评委会奖的英国新锐女导演安德里亚·阿诺德（Andrea Arnold）执导，是她的第二部电影长片。作为2009年戛纳电影节竞赛影片，《鱼缸》在2009年英国独立电影节获得8项提名。©豆瓣', '凯蒂·贾维斯', '安德里亚·阿诺德', 7.5, 30622, 'tt1232776', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p750879606.jpg', 0.7, 3.9, 33.4, 46, 15.9, '0.113189,0.015106,-0.664346,0.800541,-0.119146,-0.399829,0.773159,0.028799,-0.311631,-0.217035,0.054510,0.890947,-0.191619,0.196551,0.391937,0.084853,-0.195899,-0.623629,0.063433,-0.173715,-0.105800,-0.381236,-0.340541,-0.147795,-0.126333,-0.500976,0.701832,-0.061957,-0.078557,0.564374,0.544660,-0.080541,0.224826,0.427904,-0.017815,0.035370,0.276179,0.111103,-0.339628,0.264641,0.177902,-0.174009,-0.422575,0.145332,0.182852,0.408994,0.602156,-0.236031,-0.017089,0.039164,0.601194,-0.329489,-0.000953,0.008406,0.142169,-0.167573,0.277289,0.359111,0.062886,0.115951,0.122540,-0.315587,-0.587240,0.235596,0.068469,0.243483,-0.513811,0.576080,-0.161290,0.036988,0.019751,-0.239713,0.051553,0.080264,0.234686,0.327901,-0.193337,0.049297,-0.529607,0.286732,0.514836,0.145332,-0.555511,0.531690,-0.412066,-0.613925,-0.319665,-0.335695,-0.648182,0.165040,0.284989,-0.250315,-0.175567,0.205630,-0.517443,-0.145375,-0.056952,-0.167275,0.018464,-0.416203,-0.052639,-0.670820,0.049566,-0.388390,-0.400579,-0.196667,-0.021558,-0.512015,0.740026,-0.727343,0.246936,0.587905,0.364496,-0.487647,1.053591,0.222013,0.032786,-0.135846,-0.272609,0.446223,0.021307,-0.022914,-0.001204,0.428249,-0.003623,-0.339675,-0.478620,0.645787', '30162520', '3055049', '2338019', '25785124');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3074303', '停车', '剧情', '台北，入夜，母亲节的晚上，陈莫（张震 饰）约好与妻子（桂纶镁 饰）一起晚餐，归家途中想买个蛋糕，将车停在店门外。转身功夫，陈莫的车被另一辆车并排停放堵死在那里。回不了家的他开始在附近公寓寻找车主，岂料遇到的尽是奇人异事：失去独子的老夫妇将他的到来误认为儿子归家，独臂理发 店老板（高捷 饰）把鱼头摆在厕所，内地来的妓女（曾佩瑜 饰）夜市落跑，香港来的裁缝店老板（杜汶泽 饰）被黑道追杀……一个被卡的停车位，好像解开了连环套索，只想移车回家的陈莫，莫名其妙被卷入许多陌生人的是非，他心系在家等待的妻子，本也是因为二人关系面临破裂边缘，今夜本来是个挽回的契机……台湾广告片导演钟孟宏首部长片，入围戛纳影展一种注目单元。©豆瓣', '张震', '钟孟宏', 7.3, 26297, 'tt1232827', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1222526992.jpg', 0.7, 4.5, 35.8, 46.4, 12.6, '0.568523,0.120726,-0.431653,-0.026124,0.035488,-0.170801,0.454604,0.514258,-0.280249,-0.311153,0.170036,0.653478,-0.198760,0.198819,0.392846,0.019986,-0.211928,-0.366358,-0.048635,-0.109706,-0.174343,-0.103920,0.055301,0.095118,-0.144907,0.203329,0.364500,0.042992,0.050604,0.467454,0.451924,0.218393,-0.231256,0.292653,-0.342394,0.199870,-0.001800,-0.167414,-0.247978,0.272468,-0.106624,-0.222794,0.057591,0.038807,0.177590,0.184178,0.610230,0.293201,-0.135707,-0.018106,0.178875,-0.088531,0.005444,-0.136453,0.455430,0.084017,0.262834,0.075688,-0.356964,0.080437,0.378814,0.035611,-0.256588,0.171622,0.114454,-0.108122,-0.665580,0.368047,-0.016776,-0.132969,-0.001313,-0.388967,0.593569,0.192110,0.117861,0.195226,0.115221,0.088873,-0.744364,0.092069,0.629805,-0.124679,0.327284,0.223061,0.185328,-0.051783,0.092271,-0.132028,-0.304486,-0.091010,0.437365,-0.142247,-0.169380,-0.282924,-0.540094,-0.154042,-0.257206,-0.089214,0.219784,-0.235296,-0.236923,-0.652896,0.207396,-0.024315,0.080041,0.275182,0.034010,0.041979,0.324534,-0.524049,0.172917,0.320754,0.406238,-0.289972,0.862093,-0.007612,0.180530,-0.274710,-0.052303,-0.000924,0.183185,0.417548,0.050037,0.110921,-0.335831,-0.060671,-0.458030,0.284493', '3055049', '1306505', '1291992', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3074307', '一半海水一半火焰', '剧情', '本剧根据王朔的同名小说《一半是火焰，一半是海水》改编。 香港，是一座充满罪恶的城市。王耀(廖凡 饰) 就是其中的一个无耻的皮条客，干的最多的事情就是假装成被带绿帽子的丈夫敲诈勒索和老婆偷情的男人。有一天什么都不在乎的王耀遇到了纯情少女丽川(莫小奇 饰) 。王耀原本以为， 丽川就像其它无知的女孩一样，可以任由他的摆布，但是丽川的倔强远远超乎他的想象，并深深吸引了他。两个人相爱了，却经常互相折磨中,并渐渐越走越远。终于在一次警方的围剿行动中，王耀不幸被捕，而丽川穿着洁白的婚纱在浴缸中割腕自杀了。服刑八年后,王耀走出监狱的大门，持枪闯入丽川母亲(鲍起静 饰) 的住所……©豆瓣', '廖凡', '刘奋斗', 6.6, 40948, 'tt1232825', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2527286935.jpg', 4, 13.3, 43.2, 28.5, 11, '0.452429,-0.085327,-0.546027,0.504888,-0.441108,-0.238293,0.992532,0.097338,-0.461066,-0.020179,0.397830,0.672555,-0.161622,0.314485,-0.041621,0.072988,-0.189135,-0.803114,-0.265436,-0.274109,-0.312437,-0.372101,-0.257605,0.095716,0.134142,-0.140362,0.692308,0.253930,-0.299348,0.306828,0.468093,-0.047543,-0.229523,0.547628,-0.255252,0.044617,0.124299,0.095496,0.088076,0.165740,-0.246799,-0.268853,0.034492,0.206886,-0.277944,0.349232,0.633202,-0.289930,-0.166469,-0.069613,0.409613,-0.204248,-0.169097,0.209593,0.203278,-0.057728,0.327118,0.067627,-0.220386,0.093495,0.161429,0.132229,-0.670386,-0.056657,0.076121,0.239845,-0.553040,0.550657,0.147546,-0.201197,0.344255,-0.266187,0.123849,-0.078651,0.267092,0.585469,-0.287731,-0.141253,-0.723393,0.385071,0.436486,0.080444,-0.135405,0.391158,-0.260056,-0.321112,-0.050275,-0.132998,-0.404803,0.070606,0.270923,-0.172822,-0.331512,0.188513,-0.432841,0.093000,-0.234023,-0.039503,-0.157889,-0.405504,-0.218494,-0.500273,-0.146955,-0.539563,-0.155551,0.268182,0.002725,-0.250199,0.442330,-0.652252,0.250139,0.615123,0.270144,-0.498944,0.503504,0.270856,-0.035146,0.110794,0.046894,0.200890,0.118583,0.171191,0.188784,0.577133,-0.084880,-0.249622,-0.347936,0.624006', '21619567', '4275444', '25917973', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3074408', '热血高校2', '动作', '在GPS与芹泽军团的恶战之后，铃兰高中进入短暂的和平期。芹泽多摩雄（山田孝之 饰）让出老大宝座，泷谷源治（小栗旬 饰）则持续向恐怖的林田惠（深水元基 饰）发起冲击。8个月时间转瞬即逝，铃兰与宿敌凤仙学院的风波再起。两年前，川西仁（阿部進之介 饰）所率领的铃兰军团与美藤真喜雄率领的凤仙学院展开大战。混战中，川西刺死真喜雄，他也随后被送入少管所。为防止伤亡进一步增加，铃兰和凤仙签订了停战协议。两年后，川西出狱，遭到凤仙学院的追杀。芹泽出面阻挠，泷谷的介入更摧毁双方的停战协议。继承了真喜雄遗志的鸣海大我（金子ノブアキ 饰）和美藤龙也（三浦春馬 饰）决定以此为契机彻底摧毁宿敌铃兰高中……©豆瓣', '小栗旬', '三池崇史', 8.2, 93850, 'tt1232831', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p936977410.jpg', 0.4, 1.9, 19.6, 45.8, 32.4, '-0.155412,0.287018,-0.488195,0.624625,0.293997,-0.254380,0.120075,0.159610,0.000093,-0.195898,0.198907,0.492567,-0.217843,0.090045,0.453307,-0.338823,-0.060518,-0.872860,-0.209878,-0.292094,-0.140082,-0.321653,-0.055127,0.145644,-0.139742,-0.395928,0.961280,0.092235,-0.273117,0.748887,0.256625,0.586270,-0.028674,0.175864,0.331245,0.159341,0.001610,0.066535,-0.445215,0.232310,-0.301873,-0.193346,-0.140136,0.056442,0.253124,0.249940,0.781843,-0.380894,-0.073959,-0.654996,0.070831,-0.371556,-0.144557,0.242880,0.680283,0.077125,0.185228,0.620701,-0.275045,0.089462,-0.111082,0.005341,-0.367734,0.226307,0.024432,-0.144497,-0.292915,0.563838,0.086236,-0.010334,0.322448,-0.050381,-0.148889,1.104107,0.415841,0.038305,-0.574735,0.124256,-0.269827,-0.054734,0.707417,-0.360465,-0.134451,-0.206278,0.324248,-0.417745,-0.109546,-0.347958,0.155849,-0.142263,0.233295,-0.041756,0.362014,0.325203,-0.712551,-0.187208,-0.450781,-0.150598,0.374161,-0.223391,0.120286,-0.844115,0.001516,-0.151156,-0.502916,0.387364,0.225960,-0.112067,0.592157,-0.687588,-0.079902,0.111713,0.655270,-0.312559,0.236491,0.248527,0.233935,-0.271785,0.087112,0.013952,0.170754,0.428260,0.300599,0.172519,0.060291,-0.050229,-0.420527,0.189607', '26852888', '26365262', '1424552', '1427947');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3074415', '婚礼2008', '剧情', '《婚礼2008》集合了《疯狂的石头》制作团队，由香港金牌制作人文隽操刀主创。老郭（郭涛 饰）是一名婚礼主持，为人风趣、可靠。一次偶然机会遇到了诡计多端的职业“婚托”---小桃（陶虹 饰），并从此爱上了她。因为他的热烈追求，误打误撞多次破坏了小桃好事，把小桃的富商猎物全都吓走。为免夜长梦多，她坦白向痴心的老郭说出自己的骗子身份，怎料老郭依然不肯放弃，不折不挠地求爱求婚。哪想这一切全是小桃的骗局！她深明以一贯旧有手法，难以骗走老郭的房子与现金，无奈苦无对策，只好欲擒故纵。可是，在来来往往地尔虞我诈之间，小桃竟又对老郭发生了真情感。到最后，老郭终得美人归，眼看尘埃落定，老郭却卷款而逃。到底谁是个中高手？这场婚礼，究竟谁在骗谁？哪个是真正大老千？©豆瓣', '郭涛', '张承', 5.5, 4825, 'tt1064221', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p890139199.jpg', 7.3, 25.7, 54.8, 10.2, 2, '-0.045555,0.121770,-0.466316,0.371244,-0.453423,-0.272273,0.365558,-0.338220,-0.268081,-0.403358,-0.072958,0.406794,-0.326094,0.235338,-0.013336,-0.120946,0.136944,-0.481976,-0.198249,-0.021871,-0.300764,-0.320528,-0.065782,-0.181365,-0.044468,0.318590,0.174910,0.374353,-0.255277,0.030346,0.921325,0.071646,0.016406,0.351260,-0.093900,0.012685,0.147535,0.154053,-0.131231,-0.120474,0.041701,-0.410749,-0.204316,0.049302,0.070379,0.169901,0.336796,-0.138782,-0.065545,0.062240,0.300408,-0.328886,0.107350,0.177945,0.171868,-0.177134,-0.021994,0.051984,-0.071037,-0.126048,0.232647,0.037585,-0.624330,0.331583,0.100762,-0.092556,-0.529037,0.093051,0.091984,0.190565,-0.329316,-0.345988,0.164801,0.203095,0.532479,0.013181,-0.062963,-0.011773,-0.461256,0.342317,0.722635,0.260864,0.116394,0.097471,-0.080972,-0.418196,0.186720,-0.219857,-0.350836,0.126761,0.453059,-0.170993,-0.131081,0.105860,-0.216706,-0.283801,-0.069777,0.210697,0.055519,-0.466414,0.073890,-0.378127,-0.001696,-0.460032,-0.132501,0.112908,0.011043,-0.280898,0.532942,-0.427607,-0.112927,0.359934,0.081757,-0.768347,0.540069,0.319424,-0.141527,-0.128190,-0.042219,0.085999,0.141701,0.187214,0.391134,0.317910,0.107521,-0.298112,-0.080167,0.325613', '1297710', '1302110', '1305915', '26425062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3074503', '功夫梦', '剧情', '本片根据好莱坞1984年的同名电影翻拍而成。12岁的德瑞·帕克（贾登·史密斯 Jaden Smith 饰）随母亲（塔拉吉·P·汉森 Taraji P. Henson 饰）由底特律搬家至中国北京，认识了同校拉小提琴的中国女孩美莹（韩雯雯 饰）。德瑞与美莹的交往引起了学校以程（王振威 饰）为首的小团体的不满，在一次打斗中，处于劣势的德瑞被公寓管理员老韩（成龙 饰）所救，却得罪了程的武术老师李师傅（于荣光 饰）。老韩与李师傅约定，由徒弟们在比武大会上一较高下。从此，德瑞师承老韩开始学习中国功夫，从拳脚练习到个性修炼，一点点领会武术及人生的真谛，同时也与老韩建立了深厚的友谊。但只有短期训练的德瑞究竟能否在残酷的比武大赛上战胜程，取得最终胜利呢？©豆瓣', '贾登·史密斯', '哈罗德·兹瓦特', 6.4, 94420, 'tt1155076', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p512634618.jpg', 2.6, 13.2, 53.3, 24.2, 6.8, '0.147296,0.070696,-0.505693,0.442690,0.090923,-0.507277,0.196989,0.032855,-0.409120,-0.561523,-0.197185,0.507879,-0.183248,0.414211,0.260051,-0.575415,-0.010983,-0.663246,-0.075844,-0.064479,-0.365910,-0.537392,-0.098716,-0.155683,-0.167458,-0.214642,0.395785,0.072240,-0.489169,0.618716,0.432390,0.185225,0.038084,-0.100804,0.005688,-0.192842,0.218343,0.221287,-0.455510,0.115857,-0.000590,-0.090432,-0.143750,-0.286589,0.282614,0.374928,0.653465,-0.033217,0.100069,0.007881,0.417930,-0.062293,-0.065914,-0.065217,0.332481,0.235120,-0.100385,0.153736,0.009889,0.155676,-0.173896,-0.476187,-0.393418,0.139658,0.265609,-0.143695,-0.574649,0.443775,0.271059,-0.172342,-0.224118,-0.285802,0.044767,0.463978,0.208408,0.121043,0.069759,-0.008728,-0.409423,0.361652,0.489335,0.071692,-0.117500,0.114862,0.050267,-0.672169,-0.127972,-0.509883,-0.300485,0.014423,0.357469,-0.185689,0.189440,-0.017018,-0.453998,-0.185619,-0.030672,0.166327,0.091748,-0.226063,0.379526,-0.869175,-0.224590,-0.561519,-0.039459,-0.023057,0.201141,-0.266098,0.890325,-0.935683,0.249994,0.077284,0.151217,-0.258600,0.574638,0.223649,0.068238,-0.356695,-0.182084,0.237482,0.190192,-0.015376,-0.041056,0.446172,-0.020799,-0.100725,-0.445753,0.421188', '25922902', '3811356', '26784898', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3074533', '萨米大冒险', '动画', '阳光明媚、寂静平和的海滩，一群小海龟孵化出壳，他们摆动着稚嫩的臂膀，奋力向大海爬去。名叫萨米（比利·安格 Billy Unger 配音）的小海龟最后爬出蛋壳，但是他怎么也无法爬出沙坑。焦急时分，塞米更被海鸟捉到空中，眼看就成为了对方的点心。混乱之际，他结识了美丽的女孩莎莉（伊莎贝拉·弗尔曼 Isabelle Fuhrman 配音）。此后，他乘坐轮船的碎木板像海洋中心飘去，偶然遇到了他一生的好朋友雷。在此后的50年里，两个小家伙乘坐破木板周游世界，见识了海洋各处的美景奇观，也经历着人类为了私欲对海洋做出的无可弥补的破坏，他们的冒险从未结束……©豆瓣', '蒂姆·克里', '本·斯塔森', 6.9, 4166, 'tt1230204', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p757420578.jpg', 1.2, 6.4, 50.1, 32.3, 10.1, '0.301849,0.077173,-0.911945,0.400164,-0.225740,-0.145651,0.816641,0.284394,-0.197597,0.173826,0.239358,0.454016,-0.220186,0.145711,0.134008,0.357309,-0.200124,-0.548974,-0.023981,0.028739,-0.317094,-0.112476,-0.376965,-0.071839,0.009171,-0.218332,0.315834,0.133375,-0.095790,0.413269,0.086393,-0.171250,-0.165132,0.546170,-0.422960,0.088214,-0.214835,0.125344,0.119330,0.013878,-0.131325,-0.389858,-0.149890,-0.169887,-0.065974,0.200731,0.913708,-0.327413,0.140666,-0.066181,0.202214,-0.439779,0.235963,0.026049,0.341465,-0.003400,-0.239630,-0.095097,-0.065742,-0.047366,0.175407,-0.119793,-0.494689,0.279628,-0.399318,0.165883,-0.553395,0.360138,0.128951,-0.138174,0.144353,-0.315961,0.092630,0.125818,-0.087075,0.293421,-0.285726,0.185705,-0.561642,0.000692,0.668264,0.230585,-0.337294,0.169710,-0.303041,-0.371056,0.063997,-0.227459,-0.277118,-0.316876,0.638633,0.098145,-0.488044,0.137608,-0.734221,0.185227,-0.373639,-0.437406,-0.091026,-0.284238,-0.496018,-0.497668,0.104740,-0.185276,-0.220468,-0.035623,-0.138075,-0.335157,0.618493,-0.404995,0.139736,0.608090,0.148705,0.133145,0.847405,-0.449028,-0.117893,0.089894,0.268569,0.339067,-0.052962,0.630019,0.376999,0.367410,-0.080720,0.256389,-0.517907,0.560941', '21619567', '26882457', '3055049', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3074676', '七音符', '制片国家/地区:', '申恩奎（张根锡 饰）是一个乐团的主唱，一次偶然的机会，他结识了柔道队里活泼开朗的女孩——尹贞媛（车艺莲 饰），并且渐渐爱上了这个肯为他扛吉他的挑夫。但是，当他把贞媛带回乐队，却引起了自己的朋友姜西元（郑义哲 饰）的不满。原来，西元跟贞媛早就熟识，是交往了十年的朋友。西元早已视贞媛为己物，所以对恩奎的突然介入极为不爽。由于恩奎的爱，使得西元与贞媛形同路人，这也让他内心非常痛苦。与此同时，西元却以死要挟间接地得到了贞媛的陪伴。由于一次车祸，贞媛误使西元的父亲锒铛入狱，西元的母亲身患重病，所以善良的贞媛抱着友情和歉意接纳了西元。此后，恩奎因遭遇了车祸而失去记忆，无助的他能否获得友情与爱情呢……©豆瓣', '张根锡', '姜建享', 6.6, 18838, 'tt1669582', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p701337805.jpg', 2.3, 11.5, 51.1, 25.9, 9.3, '0.128193,-0.038025,-0.585111,0.645271,-0.193570,-0.502851,0.772365,0.068568,-0.564180,-0.175758,0.208119,0.732469,-0.108479,0.466072,0.123238,0.058509,-0.070431,-0.812353,0.054885,-0.095879,-0.357451,-0.336407,-0.243079,-0.024609,-0.209584,-0.303130,0.701223,0.007137,-0.156993,0.628144,0.334696,0.513317,0.087452,0.496279,-0.231813,0.099655,-0.168919,0.134796,-0.274350,0.000088,0.139105,-0.379755,0.073666,0.421849,-0.124037,0.572335,0.754059,-0.304578,-0.199113,-0.164576,0.410659,-0.327531,-0.053230,0.070397,0.093878,0.270675,0.366970,0.292667,-0.356993,-0.069229,-0.009729,0.047390,-0.798397,0.126225,0.105485,-0.043948,-0.607519,0.754827,-0.041352,-0.102480,0.128480,-0.014097,0.397936,0.510077,0.144455,0.289489,-0.531146,-0.032570,-0.348419,0.096897,0.798095,-0.164049,-0.110083,0.743656,-0.262331,-0.468317,-0.064794,-0.195826,-0.478190,0.197408,0.197374,-0.063510,-0.068852,0.300418,-0.470452,-0.178205,-0.288698,0.288563,0.187582,-0.422238,0.061978,-0.170888,-0.268060,-0.451873,-0.244627,-0.058180,-0.007470,-0.305710,0.790047,-0.899492,0.175576,0.561133,0.451781,-0.549821,0.551738,0.213098,0.014859,-0.229632,0.076310,0.286637,-0.096517,-0.015702,0.246762,0.223956,0.149694,-0.083536,-0.482740,0.444635', '35030151', '26809007', '1395231', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3075287', '源代码', '科幻', '在阿富汗执行任务的美国空军飞行员科特史蒂文斯上尉（杰克·吉伦哈尔 Jake Gyllenhaal 饰）突然惊醒，发现自己在一辆高速行驶的列车上，而他的身边坐着一个素不相识的女子克里斯蒂安（米歇尔·莫娜汉 Michelle Monaghan 饰）正在与自己讲话。科尔不知自己为什么会在这辆车上，而且他发现自己居然是以另一个人的身份存在，正当他迷惑不解的时候，列车上忽然发生爆炸……科特又一次惊醒，发现自己身处一个密闭的太空仓里，有一位女军官古德温（维拉·法米加 Vera Farmiga 饰）正在通过视频和自己对话，并要求自己报告列车上发生的事情。一头雾水的科特还没搞明白是怎么回事时，他又一次被送上那辆列车。这次之后，科特终于明白自己在执行一件任务，负责调察芝加哥火车爆炸案找到恐怖份子并查出他的下一个目标。科特被一次又一次的送上那辆高速列车，每次只有八分钟的时间调察，调察过程中，科特发现自己已在一周前去世，原来他正在参与是一项“脑波原代码”的秘密任务，这项任务通过已经死亡的科特尚未完全死亡的脑细胞影像来还原事件，调查事情的真相。最终，科特顺利完成了任务，但是他却决定再一次返回列车，拯救列车上那些无辜的生命……', '杰克·吉伦哈尔', '邓肯·琼斯', 8.5, 785622, 'tt0945513', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p988260245.jpg', 0.1, 0.6, 12, 47.9, 39.4, '0.293164,0.271075,-0.713229,0.606095,-0.071202,-0.418104,0.725942,-0.310240,-0.535777,-0.439966,0.362987,0.758554,-0.154002,0.078574,0.369758,0.361726,-0.725380,-0.526191,0.155040,-0.187766,-0.707217,-0.743366,-0.206449,-0.092607,0.409594,-0.236091,0.549114,-0.021797,-0.022211,0.387833,0.369048,0.160303,-0.103607,0.708779,0.065489,-0.108434,0.417882,0.006557,0.174564,0.126837,-0.060449,-0.463763,-0.153594,0.114383,-0.146717,0.495835,0.558800,-0.161236,-0.280089,-0.027759,0.139775,-0.427222,0.146781,-0.185406,0.276730,-0.002181,0.075294,0.007681,-0.160470,-0.038887,0.026912,0.146735,-0.550846,-0.150900,-0.459582,0.264425,-0.434537,0.181266,-0.519787,0.232190,-0.031724,-0.598155,0.143435,0.513001,0.416329,0.323715,-0.449682,-0.208034,-0.585293,-0.163187,0.668568,-0.107253,-0.243278,0.643533,0.075600,-0.580366,-0.088496,-0.044116,-0.354210,0.096438,0.282632,0.131629,-0.230062,0.037598,-0.339675,0.049795,-0.567557,-0.491327,-0.316695,-0.098907,-0.127673,-0.600813,0.088803,-0.113620,-0.312186,0.181901,-0.026319,-0.274784,0.189613,-0.582173,0.432588,0.659380,-0.067338,-0.217657,0.473716,0.233392,0.2