INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3075921', '以眼杀人', '喜剧', '鲍勃•维尔登（伊万•麦克格雷格Ewan McGregor 饰）是个婚姻失败的美国记者，绝望中来到中东，试图设法潜入伊拉克进行战地新闻报道以赢回前妻芳心。鲍勃在科威特遇到了以前采访中听说过的私家建筑商林恩·卡萨迪（乔治•克鲁尼 George Clooney 饰），苦苦哀求后者带他过境。林恩曾是美国陆军“地球精神部队”的特种兵，在越战老兵嬉皮比尔•迪昂格（詹姆斯•布里奇斯 Jess Bridges 饰）的特殊训练方法下寻求“绝地武士超能力”，以精神意念战胜敌人；直到军人拉里•霍珀（凯文•斯帕西 Kevin Spacey 饰）的加入改变了“地球精神部队”的训练方针。鲍勃跟随林恩在伊拉克经历了一系列令人啼笑皆非的事故与事件，到底林恩是否真有“绝地超能力”呢？©豆瓣', '乔治·克鲁尼', '格兰特·赫斯洛夫', 6.6, 13977, 'tt1234548', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p580618707.jpg', 2, 11.6, 49.2, 29.4, 7.8, '0.110794,-0.111004,-0.542630,0.513261,0.169450,-0.194517,0.298550,-0.219876,-0.631336,-0.318648,0.423535,0.586022,-0.069244,-0.009605,0.324337,-0.150715,-0.501591,-0.547616,0.100525,0.113203,-0.155666,-0.518688,-0.475558,-0.379777,0.034015,-0.476164,0.618656,-0.089311,-0.215206,0.311700,0.045445,0.575945,0.295795,0.164328,0.139406,0.095790,0.363054,-0.117196,-0.531017,0.131376,0.158087,-0.071546,-0.195333,0.059798,0.233131,0.192283,0.307626,-0.314282,0.210425,-0.114511,0.275681,-0.083611,0.139345,0.129575,0.296580,0.065617,-0.078497,0.129109,0.214938,0.223050,0.011350,-0.018454,-0.444214,-0.000469,-0.115049,0.150453,-0.379306,-0.076888,-0.364197,0.285637,0.070329,-0.159883,-0.131499,0.372959,0.464998,0.145495,0.034079,0.039303,-0.216454,-0.031160,0.519137,-0.129303,-0.358002,0.021139,-0.435388,-0.500765,-0.087905,-0.147006,-0.322302,0.103470,0.213290,-0.186426,0.000656,0.413605,-0.627856,0.014314,-0.262821,-0.164530,-0.160215,0.058828,-0.012976,-0.984103,-0.120828,-0.233217,-0.133328,0.068174,-0.000005,0.004844,0.461522,-0.735265,0.132528,0.595692,0.216586,-0.395871,0.259388,0.036941,-0.001852,-0.277320,-0.014832,0.654418,-0.005175,0.279920,0.021354,0.314686,0.082873,-0.283348,0.032440,0.290848', '2369613', '4014397', '20274039', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3075983', '电锯惊魂6', '悬疑', '“竖锯”约翰•克莱默（Tobin Bell 饰）肉体虽死，但精神长存。这一次，某医疗保险公司的老总威廉•伊斯顿（Peter Outerbridge 饰）成为他狩猎和考验的目标。威廉贪婪狡诈，他发明了一套医保的计算公式，同时凭借爪牙的协助，成功向无数病入膏肓的人们拒保，从中赚取黑心钱财。然而他没有想到，自己有朝一日也要将生命的决定权交与别人手中。他必须按照“竖锯”的游戏规则，小心翼翼寻找逃生之路。另一方面，约翰门徒之一马克•霍夫曼（Costas Mandylor 饰）成功害死警官斯特朗，并试图将警方的注意力引到斯特朗身上来。然而种种迹象早已令同侪对马克的身份产生怀疑，他的身份即将被揭穿，而他违背约翰精神的暴力之路也慢慢走向尽头……©豆瓣', '托宾·贝尔', '凯文·格劳特', 7.9, 101637, 'tt1233227', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p788637973.jpg', 0.4, 2.2, 25.2, 46.1, 26.1, '0.106516,0.220651,-0.560238,0.534967,-0.255049,-0.298471,0.519768,-0.040908,-0.301587,-0.071315,0.239983,0.603764,0.019694,-0.062921,0.306245,-0.121788,0.017722,-0.588674,0.050931,0.043879,-0.318158,-0.468958,-0.262481,-0.315635,-0.329257,-0.236611,0.609692,0.066530,-0.230244,0.388454,0.331983,0.493040,-0.024025,0.355799,0.050586,-0.092643,0.032918,-0.416388,-0.226788,0.057567,0.127729,-0.310758,-0.022342,0.540588,-0.252547,0.525904,0.418587,-0.220503,-0.118685,-0.084013,0.319000,-0.493999,0.204673,0.313276,0.138013,0.301802,-0.193203,0.385173,-0.037015,-0.009202,0.262320,-0.235595,-1.120280,-0.235165,-0.231546,0.301514,-0.451777,-0.023480,-0.242589,0.007275,-0.081706,-0.355970,0.012144,-0.022788,0.382672,-0.092146,-0.357921,-0.200534,-0.475861,-0.037111,0.480144,-0.336615,-0.132207,0.344499,-0.089469,-0.226976,0.107385,-0.215995,-0.212943,-0.146027,0.324386,0.412990,-0.031179,0.149948,-0.515782,-0.045118,-0.394974,-0.155085,0.009132,-0.347537,0.175153,-0.405814,-0.247650,-0.248494,-0.240269,-0.063485,0.132420,-0.521013,0.462177,-0.472828,0.081937,0.587501,0.317154,-0.575379,0.429916,-0.185483,0.286093,-0.101451,-0.143870,0.207992,0.498733,0.479451,0.026358,0.144750,0.245649,-0.183686,-0.155724,0.580417', '30163500', '26678784', '4820775', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077408', '灵魂战车2：复仇时刻', '动作', '约翰·布雷斯（尼古拉斯·凯奇 Nicolas Cage 饰）被正义天使拉萨罗斯附体，但天使暴躁乖戾，遇到坏人就要吸取他们的灵魂。莫罗（伊德瑞斯·艾尔巴 Idris Elba 饰）请求布雷斯把小孩丹尼带来神殿以避免恶魔夺取他的灵魂，作为回报他将驱除布雷斯身上的诅咒。丹尼是魔鬼罗尔科的儿子，罗尔科为了把自己的魔力植入儿子体内正派卡里跟追踪逃跑途中的母子两人。正当母子俩被困在采石场的时候，布雷斯到来，他体内的天使爆发了出来，压制住了卡里根。他变成了恶灵骑士，毫不手软的把对手撕成碎片。当战争结束时，三人前往神殿，同时，罗尔科也救醒了死亡边缘的卡里根，并赋予他更可怕的摧毁力，让他再去把丹尼找回来。在神殿里，莫罗履行协议把布雷斯体内的扎萨罗斯驱赶了出来。但正当他做法时，神殿的牧师试图杀死丹尼——他认为丹尼就是恶魔。还没等他们行动，卡里根就到了。把丹尼带去见了罗尔科。罗尔科逼迫丹尼参与一个仪式，想使他变成一个彻头彻尾的恶魔。布雷斯试图阻止这个仪式，说服丹尼弃恶从善。在最后一战中，为了打败恶魔，丹尼用了他的力量把扎萨罗斯再次植入布雷斯体内。这次扎萨罗斯变成了正义的化身，打败了恶魔。', '尼古拉斯·凯奇', '马克·耐沃尔代', 5.9, 65627, 'tt1071875', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1494005631.jpg', 5.6, 23.8, 47.8, 15.6, 7.2, '0.314844,0.373408,-0.446371,0.466350,-0.358166,-0.406584,0.663674,0.014846,-0.108966,-0.053208,0.189725,0.685771,-0.064284,-0.106572,0.430193,0.201276,-0.269107,-0.633548,-0.040010,0.119847,-0.258419,-0.481441,-0.365776,-0.121176,-0.132460,-0.777756,0.408275,-0.133128,-0.107959,0.123175,0.207889,0.373457,0.005551,0.429235,-0.017373,0.162806,0.077831,-0.585952,0.019459,0.448640,0.244539,-0.039751,0.086462,0.626813,-0.030350,0.261891,0.563733,-0.471322,0.411088,-0.342038,0.091382,-0.586699,-0.018309,0.310418,0.064771,-0.050232,0.105593,0.132123,-0.128258,-0.028727,0.309173,0.102421,-0.833456,0.086737,-0.215290,0.036446,-0.449228,0.131835,0.017117,0.216703,0.296304,-0.369067,0.148164,0.154060,0.248349,0.177938,-0.220476,-0.283546,-0.685561,-0.177902,0.629205,-0.491939,-0.248495,-0.140026,-0.165183,-0.272961,0.056514,-0.230407,-0.215654,-0.143368,0.586003,0.215719,-0.272443,0.309952,-0.773502,-0.437491,-0.729743,-0.066928,-0.058073,-0.400650,0.130388,-0.468524,-0.319897,0.238091,-0.088797,-0.061260,0.029360,-0.264420,0.473560,-0.641623,0.431326,0.854842,0.664534,-0.183548,0.438960,0.021045,0.203314,-0.07