INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077412', '寻龙诀', '剧情', '上世纪80年代末，胡八一（陈坤 饰）、王凯旋（黄渤 饰）与Shirley杨（舒淇 饰）在美国打算金盆洗手，本来叱咤风云的摸金校尉沦为街头小贩被移民局追得满街跑。就在此时，意外发现20年前死在草原上的初恋对象丁思甜（杨颖 饰）可能还活着，胡八一、王凯旋、Shirley杨决定再入草原千年古墓……', '陈坤', '乌尔善', 7.4, 576493, 'tt4276752', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2284620292.jpg', 1.2, 4.9, 32.4, 44.1, 17.3, '-0.049419,0.534984,-0.819752,0.185408,0.082170,-0.179618,0.460243,-0.308392,-0.513250,-0.292350,0.052016,0.412481,-0.197022,0.194912,0.127449,-0.185450,-0.284957,-0.513965,0.117258,-0.169708,-0.316578,-0.172482,-0.474653,-0.189563,-0.471256,-0.128095,0.687474,0.299131,0.007165,0.688170,0.350860,0.112656,0.069574,0.349494,-0.485261,0.209099,-0.072916,0.278543,-0.520263,0.058556,-0.129409,-0.363861,0.005713,-0.247987,0.054599,-0.058677,0.542164,0.078717,0.049796,0.130468,0.280571,-0.054176,-0.275156,-0.027468,0.735859,-0.503125,0.172371,-0.027810,0.046334,-0.258167,0.310489,0.058975,0.233336,0.124171,0.126487,0.294097,-0.619919,-0.042300,-0.201260,0.270557,-0.170800,-0.684492,0.323847,0.138703,0.728905,0.342788,0.124001,-0.073208,-0.605757,0.750500,0.632461,0.127745,0.177613,-0.070887,0.250685,-0.696886,-0.170326,0.031743,-0.248123,0.032088,0.519547,-0.606670,-0.255445,-0.076636,-0.394203,-0.058976,0.124816,0.293072,0.007082,0.068148,0.113418,-0.461192,-0.092168,-0.358243,-0.070097,0.427318,0.207863,-0.237490,-0.030971,-0.258448,0.555773,0.145439,0.296087,-0.295391,0.701635,0.165446,0.022905,-0.229067,0.013283,0.408876,-0.034864,0.138768,0.084877,0.205715,-0.167040,-0.339969,-0.301057,0.391770', '1451563', '1307200', '2080130', '35256235');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077413', '蝴蝶效应3：启示', '剧情', '主人公山姆（克里斯·卡马克 Chris Carmack 饰）有着沉重的过去，一场大火让他的家庭支离破碎，妹妹珍妮（蕾切尔·敏纳 Rachel Miner 饰）也由于自己的失误葬生火海。成年后的山姆在偶然间发现自己拥有了能够穿越时空的超能力，他利用自己的能力回到了火灾现场，虽然救出了珍妮，但是本该逃生的父母却死于火灾。改变了过去后，山姆和珍妮相依为命，山姆结交了女友丽贝卡（Mia Serafino 饰），可是没多久，惨剧再次发生，丽贝卡死于一场谋杀，而山姆的朋友朗尼（Richard Thorne 饰）则被警方当做真凶逮捕判刑。丽贝卡的妹妹伊丽莎白（莎拉·哈贝尔 Sarah Habel 饰）觉得事有可疑，他拜托山姆穿越回丽贝卡被杀害的那一天，找出真凶。一次次的穿越让时间线索变得面目全非，本该死的人活着，本该清白的人却背上的罪名，唯一不变的，是所有亲近他的女性都会惨遭杀害。随着真相的渐渐明朗，一个另山姆意想不到的身影出现在了本不属于他的时空中。', '克里斯·卡马克', '塞斯·格罗斯曼', 6.7, 64028, 'tt1234541', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2191931872.jpg', 1.6, 9.4, 49, 30.5, 9.5, '0.229487,0.099207,-0.723063,0.386878,-0.168314,-0.380102,0.950037,0.034038,-0.436075,-0.269215,0.274692,0.835285,-0.084275,0.137703,0.308884,0.210980,-0.406121,-0.562855,0.077739,-0.205749,-0.516479,-0.502599,-0.406974,-0.299054,-0.000457,-0.334343,0.477193,0.017067,-0.098295,0.352334,0.268899,0.328506,-0.011353,0.463019,-0.033367,0.240099,-0.045679,-0.069657,-0.260280,0.189546,0.051402,-0.251870,0.036515,0.261971,-0.215224,0.417945,0.744714,-0.316050,-0.086971,-0.228734,0.378036,-0.329299,-0.024988,0.104043,0.076067,-0.139341,0.112254,0.199311,-0.302482,-0.164844,0.278246,0.119562,-0.720656,0.160378,-0.068667,0.255403,-0.449488,0.332497,-0.175080,0.057251,0.255573,-0.363215,0.278615,0.376486,0.133359,0.223590,-0.393066,0.050523,-0.652616,0.020266,0.652625,0.024757,-0.321239,0.332006,-0.282005,-0.288420,-0.005743,-0.083411,-0.340853,0.069448,0.609092,0.144178,-0.332604,0.436042,-0.425114,-0.342263,-0.494473,-0.063581,-0.300037,-0.432859,-0.231671,-0.277424,-0.173838,-0.194132,-0.422064,0.009338,-0.195947,-0.358604,0.578501,-0.659416,0.296500,0.647653,0.157684,-0.452463,0.389677,0.204540,0.224921,-0.057591,-0.112755,0.393721,0.191015,0.317704,0.322641,0.191767,0.078817,