INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077668', '天水围的日与夜', '剧情', '天水围位于香港新界元朗区，原是一条小围村，1980年代末被港英政府发展成为以住宅为主的新市镇，但今天它的30万居民多为底层劳工（其中有诸多新移民及大陆新娘）。由于天水围发生过多起震惊港媒的伦常惨案，该地被视作“悲情市镇”，可是其中多数居民平日其实过着与其他港人并无差异的生活，相依为命的贵（鲍起静）与张家安（梁进龙）母子便是如此。年纪轻轻便守寡的贵14岁出来做工，先后供两个弟弟念完大学，如今他们做成富贵人，她依旧是超市女工一名，但是她并不觉上天待她刻薄，每日生活都很乐观。张家安是乖乖仔，会考完毕没找暑期工做的他多数时候会呆在家里睡觉或看电视，外出见朋友、参加活动的时间非常有限。母子一起坐下吃晚饭聊天时，说的也是该买哪家报纸一类再平常不过的话。与他们住在同一栋楼里的阿婆梁欢（陈丽云）是新搬来的住户，她每日过着郁郁寡欢、斤斤计较的孤独生活。凭着曾在市区卖过果蔬的经验，她在贵工作的超市找到份工。起初，她与贵不过是见面点头之交，且神情相当冷漠，但慢慢地，贵的慷慨与无私融化了她心中的冰山。而贵在了解到她的心结后，给了她更多温暖，两人渐渐亲如母女。日子一天天过，张家安亦从母亲身上、几件平常事中了解到生活的多面，舅舅们并没在心理上疏远他们母子，每人都有自己的生活要过。他做好了若是会考成绩不理想，便出来做事的准备。', '鲍起静', '许鞍华', 8.6, 110111, 'tt1233499', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2157923959.jpg', 0.2, 0.8, 10.6, 43.9, 44.4, '0.350090,-0.128981,-0.719256,0.379952,-0.163035,-0.175095,0.685559,0.149035,-0.663810,-0.247019,-0.035201,0.709215,-0.078365,0.446397,-0.033237,-0.060116,-0.226779,-0.349966,-0.084465,-0.275462,-0.172278,-0.305193,-0.064602,-0.183509,-0.298019,-0.067164,0.237053,0.098131,0.038274,0.332693,0.048408,0.003580,-0.057586,0.500954,-0.503899,-0.026402,-0.240668,0.273241,-0.282114,-0.032090,-0.064872,-0.053798,-0.361814,0.018149,0.485642,0.347384,0.555220,0.197460,-0.386703,0.164440,0.267376,0.028656,-0.099871,0.133585,0.442516,-0.001975,0.355451,0.298718,-0.106443,0.206988,-0.150226,-0.124953,-0.508225,0.090112,0.095328,-0.081868,-0.709297,0.591540,0.107088,-0.202380,-0.290850,-0.462783,0.307539,0.358002,0.025138,0.274763,0.008041,-0.044331,-0.652875,0.341504,0.950404,0.094066,-0.170205,0.321142,-0.297131,-0.447239,0.190275,-0.367349,-0.430766,-0.005814,0.006855,0.004463,-0.114175,0.038320,-0.584262,0.248513,-0.011718,-0.296328,0.264922,-0.292292,0.037255,-0.525841,-0.119572,-0.809125,-0.542294,0.113475,0.176959,-0.305979,0.753834,-0.766667,0.139877,0.234736,0.488811,-0.692469,0.750110,0.110119,0.272046,0.086368,-0.154187,0.025526,-0.107804,0.297614,0.176975,0.269750,-0.087393,-0.110200,-0.325513,0.410156', '25721544', '3055049', '1300202', '1291586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077673', '六年之痒', '爱情', '和学生时代的恋人执手到现在，又是畅销的恋爱小说家，多珍（金荷娜 饰）被很多人所羡慕着。而殊不知，即将三十岁的多珍也面临着许多烦恼。自己的男友在英（尹继尚 饰）是购物频道的金牌编导，又长得一表人才，身边追求者无数，却只倾心于多珍她一个人。本来对二人关系很自信的多珍，却在相处了六年后，渐渐有了危机。不再如同学生时代那般浪漫和激情，工作后的在英越来越把自己当做空气，曾经浪漫的男人，现在却不知浪漫为何物。是不是恋爱就一定会有倦怠期，所谓的七年之痒提前一年来到，多珍不知该不该和在英继续保持这种状态。于是，多珍决定以“同居”的方式使两人的方式更进一步，却发现弄巧成拙……©豆瓣', '金荷娜', '朴贤真', 6.8, 8301, 'tt1233458', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p710910641.jpg', 0.9, 6.5, 51, 33.3, 8.4, '0.131064,0.061806,-0.733864,0.487107,-0.102399,-0.267970,0.797220,0.152648,-0.571686,-0.254477,-0.084545,0.700255,-0.519857,0.272135,0.321037,-0.167913,-0.115749,-0.882615,-0.240258,-0.275130,-0.310578,-0.414868,-0.326125,0.109572,-0.253078,-0.495264,0.713543,0.064185,-0.210758,0.175382,0.266198,0.295652,0.075184,0.755481,-0.390406,-0.109128,0.054900,0.378368,-0.254419,-0.128410,0.114827,-0.355438,-0.330027,0.163565,-0.044362,0.180963,0.839485,-0.191293,-0.371460,0.240370,0.375581,-0.056649,-0.310361,0.008966,0.317167,-0.190737,0.340916,0.141732,-0.104422,-0.010750,-0.049131,-0.194303,-0.769142,0.157541,-0.014520,0.219623,-0.453524,0.529542,-0.021688,-0.107370,0.138265,-0.362352,0.103062,0.432634,0.241233,0.481406,-0.416663,-0.195058,-0.552711,0.360665,0.973126,0.469998,-0.219120,0.832744,-0.321329,-0.505862,-0.259263,-0.068839,-0.686823,-0.136727,0.112925,0.099551,-0.245434,0.269314,-0.655291,0.137060,-0.093639,0.176762,0.156076,-0.668150,0.001607,-0.387593,-0.086374,-0.763372,-0.432030,0.075786,0.209220,-0.293691,1.001463,-1.212091,0.216297,0.458615,0.212171,-0.589465,0.680542,0.336279,-0.071217,-0.226043,-0.182367,0.044787,-0.137529,0.050294,0.134028,0.501713,-0.029517,-0.099135,-0.378571,0.592635', '21766698', '1395231', '26354526', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077680', '傻瓜', '剧情', '李承龙（车太贤 Tae-hyun Cha 饰）因为童年一场意外让他的智商只停留在了儿童时期，无论快乐还是悲伤都有着傻瓜一样的笑容。父母离世后靠着三明治店的收入来养活照顾妹妹智仁（崔雪莉 Sulli 饰），每晚唱着《小星星》想着妈妈，盼望着童年暗恋的对象芝浩（河智苑 Ji-won Ha 饰）归来。某天承龙在路上一眼认出了留学十年刚刚回国的芝浩。随着两人相处日子的增多，芝浩对承龙儿时的记忆被渐渐被唤起，在承龙的鼓励下对钢琴的信心也渐渐恢复。就在芝浩，妹妹智仁和玩伴相洙（李己雨 Ki-woo Lee 饰）这三个承龙最爱的人都陪伴在自己身边的时候，妹妹的意外病倒让幸福的故事开始发生了转折…该片改编自韩国著名网络漫画家姜道英的同名漫画《傻瓜》。©豆瓣', '车太贤', '金正权', 7.6, 36336, 'tt1233461', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2097943861.jpg', 0.5, 3.3, 31, 45.4, 19.8, '-0.109560,0.014150,-0.635266,0.422651,0.199176,-0.415762,0.684053,0.258443,-0.375313,-0.237956,0.095187,0.594893,-0.259569,0.480304,0.215556,-0.211795,-0.297283,-0.625756,-0.056354,-0.204963,-0.067863,-0.271400,-0.037242,-0.034003,-0.152744,-0.679331,0.344095,0.032364,0.098198,0.683948,0.315931,-0.049890,-0.175440,0.275228,-0.177717,0.141193,0.011400,0.403484,-0.258350,0.050506,0.119349,-0.195389,0.026973,0.056599,0.022214,0.050179,0.947137,0.014818,-0.253623,0.097921,0.302738,0.041938,-0.057009,-0.099488,0.350813,0.107371,0.244793,0.100010,-0.229921,0.043991,-0.125456,0.076211,-0.500192,0.047044,0.205461,0.182982,-0.671920,0.626220,0.123475,0.021985,0.205066,-0.417384,0.307074,0.351867,0.229468,0.663648,-0.313217,0.402965,-0.249682,0.447499,0.627708,-0.123304,-0.002956,0.742190,-0.145505,-0.172697,-0.036596,-0.103934,-0.588448,0.275984,0.090415,-0.093105,-0.340776,0.296329,-0.467474,0.075313,0.153824,-0.132685,0.168495,-0.462803,-0.068086,-0.393228,-0.115895,-0.305882,-0.196949,0.116733,0.043743,-0.417989,0.991646,-0.742872,0.461111,0.466557,0.219014,-0.270998,0.724268,0.170426,-0.081890,-0.236032,0.162922,0.347533,-0.144420,-0.147455,-0.013883,0.238589,-0.262922,0.031422,-0.527306,0.444441', '3811356', '1316698', '5977789', '1308609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077701', '空之境界 第四章 伽蓝之洞', '动画', '1998年06月，意外事故后昏睡两年的两仪式苏醒了。18年的记忆没有了，两仪织的人格也代替两仪式死去了。只有名为“黑桐干也”的男子守护在自己的身边。还有眼前奇怪的现象。两仪式获得了直视万物死之线的异形之力“直死之眼”。黑桐干也的上司，苍崎橙子，来到医院接触两仪式，教导她“直死之眼”的使用方法。医院突然遭到袭击，式手握匕首，跨出了2年来，最坚毅的一步。日本同人小说最高境界《空之境界》全七章动画化，本作为第四章电影版。©豆瓣', '坂本真绫', '泷口祯一', 8.8, 19731, 'tt1233474', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2194400621.jpg', 0.2, 0.6, 10.5, 36.7, 52.1, '-0.033179,0.102596,-0.457061,0.285262,0.075991,-0.111120,0.405625,0.174055,0.034535,-0.451606,0.320467,0.548366,-0.218629,0.005795,0.318742,-0.253511,0.238523,-0.658239,-0.061429,-0.147193,-0.506855,-0.032909,-0.183538,-0.028330,0.090194,-0.685861,0.729003,0.079533,0.038155,0.129936,0.131403,0.347017,0.045884,0.140341,-0.057772,-0.116928,0.133448,-0.076616,0.037741,0.339355,-0.137009,-0.322469,-0.075816,0.240109,-0.058212,0.304908,0.706644,-0.145883,-0.174424,-0.433455,0.320322,-0.151963,-0.576143,-0.149690,0.282553,0.051377,0.055930,0.479367,0.000722,0.035941,-0.020691,-0.341001,-0.811755,-0.058181,-0.198536,-0.097189,-0.512578,0.280994,-0.009879,-0.032169,0.093733,-0.309646,0.258344,0.318992,0.356435,0.585845,-0.234027,-0.206572,-0.297822,0.227017,0.264522,-0.298320,-0.568956,0.763928,-0.029824,-0.696280,-0.555618,-0.477137,0.208003,0.077396,0.271217,0.495523,-0.026120,0.227878,-0.595312,-0.297092,0.003575,-0.218048,0.184314,-0.129720,0.036713,-0.635539,-0.103517,-0.247420,-0.388192,0.151915,0.220133,-0.290727,0.492711,-0.560165,0.462408,0.262998,0.268898,-0.466459,0.992705,0.200847,0.066292,-0.217862,0.077731,0.279679,-0.278839,0.468361,0.074717,0.290427,0.152714,0.386736,-0.396603,0.561030', '1291564', '26759820', '25880986', '1303263');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077739', '预言者', '剧情', '青年马利克（Tahar Rahim 饰）因参与犯罪活动被判刑六年，在监狱里，他很快因自己的一半阿拉伯血统被科西嘉帮派领袖卢西亚尼（Niels Arestrup 饰）注意，后者强逼马利克刺杀一名阿拉伯犯人，马利克完成了任务，在监狱生涯中得到卢西亚尼帮派的保护。一年后监狱转移部分科西嘉犯人，卢西亚尼势力大减，视学会了科西嘉语的马利克为眼耳，同时马利克在监狱学校中补习不辍，不久马利克得到白天外出工作的机会，借助监狱中获得的关系，马利克涉足大麻生意，获利颇丰，并逐渐挣脱卢西亚尼的控制自立门户……本片获2009年戛纳电影节评审团大奖。©豆瓣', '塔哈·拉希姆', '雅克·欧迪亚', 7.6, 16787, 'tt1235166', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p776480745.jpg', 0.6, 2.9, 28.6, 50.2, 17.7, '0.030364,0.361718,-0.273437,0.233778,0.122975,-0.030561,0.320855,0.065784,-0.365687,-0.369661,-0.105468,0.579345,-0.223598,0.031287,0.260227,-0.244823,-0.432911,-0.423007,-0.055887,-0.406200,-0.190874,-0.558274,-0.194118,-0.123689,-0.380030,-0.456355,0.762881,0.165293,-0.099038,0.552820,0.160740,0.299054,0.061214,0.164110,0.178990,-0.080810,0.559137,-0.338163,-0.252941,0.370263,-0.131762,-0.241746,-0.231658,0.054116,0.329941,0.313901,0.688903,-0.052538,0.263195,-0.484736,0.186261,-0.030643,-0.262731,-0.260827,0.544622,-0.095734,-0.026813,0.646655,-0.254052,0.137580,0.078696,-0.382677,-0.486516,-0.302820,0.356044,-0.029688,-0.338211,0.048897,-0.122524,0.365932,-0.197622,0.130735,-0.198992,0.459182,0.181931,0.393230,0.010447,0.137644,-0.723159,0.167453,0.330193,-0.844659,-0.343263,0.157033,-0.004049,-0.554187,-0.032307,-0.447353,-0.100567,-0.043144,0.404012,-0.217545,-0.204070,0.453750,-0.326335,-0.225703,-0.351641,-0.374420,0.061485,-0.071788,-0.102599,-0.839047,-0.014310,0.228780,-0.165813,0.040905,-0.044753,-0.094195,0.365445,-0.543951,0.187894,0.688362,0.372011,-0.248439,0.482814,-0.237516,0.725359,-0.272990,-0.144504,0.503724,0.607197,0.168892,0.222550,-0.025423,-0.204459,-0.339629,-0.227132,0.406531', '2369613', '1899892', '1293572', '2028645');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077742', '机械战警', '动作', '2028年，专事军火开发的机器人公司Omni Corp.生产了大量装备精良的机械战警，他们被投入到维和和惩治犯罪等行动中，取得显著的效果。罪犯横行的底特律市，嫉恶如仇、正义感十足的警察亚历克斯·墨菲（乔尔·金纳曼 Joel Kinnaman 饰）遭到仇家暗算，身体受到毁灭性破坏。借助于Omni公司天才博士丹尼特·诺顿（加里·奥德曼 Gary Oldman 饰）最前沿的技术，墨菲以机械战警的形态复活。数轮严格的测试表明，墨菲足以承担起维护社会治安的重任，他的口碑在民众中直线飙升，而墨菲的妻子克拉拉（艾比·考尼什 Abbie Cornish 饰）和儿子大卫却再难从他身上感觉亲人的温暖。感知到妻儿的痛苦，墨菲决心向策划杀害自己的犯罪头子展开反击……©豆瓣', '乔尔·金纳曼', '何塞·帕迪里亚', 6.4, 84542, 'tt1234721', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2170735207.jpg', 1.8, 12, 56.9, 23.5, 5.9, '0.006006,-0.121627,-0.668697,0.497753,-0.205649,-0.127221,0.733065,0.232959,-0.533717,0.099632,0.315372,0.524152,-0.015620,-0.133001,0.250329,0.019353,-0.198807,-0.632448,-0.025666,0.049880,-0.167546,-0.397990,-0.578575,-0.331855,-0.006421,-0.581902,0.497029,-0.085088,-0.491418,0.354225,0.132946,0.509906,0.057328,0.488759,0.133256,-0.084724,0.158208,-0.391041,-0.280284,0.283910,0.007134,-0.140692,-0.061410,0.142257,0.118357,0.321106,0.639575,-0.152801,-0.087410,-0.219525,0.479159,-0.364095,0.094502,0.197410,0.307830,0.170530,-0.159767,0.273800,-0.054415,-0.095137,0.101536,-0.263330,-0.990298,-0.283901,0.082104,-0.021675,-0.505187,0.228785,-0.495660,0.047005,-0.051376,-0.316038,-0.115149,0.144308,0.034307,0.526362,-0.298486,0.136371,-0.608844,0.060681,0.441091,-0.312962,-0.423225,-0.142783,-0.211339,-0.385072,-0.170775,-0.443126,-0.250147,-0.310902,0.490959,-0.015906,0.011966,0.400076,-0.589079,0.062972,-0.435593,-0.233912,-0.324654,-0.172879,-0.049004,-0.763690,-0.196651,-0.202181,-0.234243,0.049932,0.029255,-0.279417,0.598733,-0.731371,0.100283,0.792633,0.434441,-0.399771,0.188056,-0.190579,0.238688,-0.091816,-0.380726,0.279997,0.140400,0.364259,0.222203,0.260248,0.136357,-0.167764,0.088680,0.599330', '1793491', '3769423', '1308585', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077791', '在云端', '剧情', '本片改编自美国作家沃尔特•肯的同名小说。瑞恩•布林厄姆（乔治•克鲁尼 George Clooney 饰）供职于美国内布拉斯加州奥马哈市一家专为其他公司提供裁员服务的公司，一年有300多天辗转于全国各地解雇他人，几乎以机场为家。在一次例行裁员旅行中，瑞恩遇到了商务美女亚历克斯（维拉•法梅加 Vera Farmiga 饰），二人一见钟情，却都满足于维系随意的性伴侣关系。与此同时，瑞恩公司的大学生新人娜塔莉（安娜•肯德里克 Anna Kendrick 饰）得到了公司总裁的青睐，竭力推广通过网络视频会议远程裁员的改革。瑞恩反对变革，却不得不带娜塔莉四处实习熟悉业务……本片获奥斯卡最佳导演、最佳影片、最佳男主角（乔治•克鲁尼）、最佳女配角（维拉•法梅加 和安娜•肯德里克）及最佳改编剧本六项提名，金球奖最佳导演、最佳影片等六项提名，并获洛杉矶影评人协会最佳剧本奖。', '乔治·克鲁尼', '贾森·雷特曼', 7.9, 205346, 'tt1193138', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2151251263.jpg', 0.2, 1.2, 22.9, 53.6, 22.1, '-0.332061,-0.049455,-0.549732,0.560790,0.312123,-0.281979,0.100059,0.177017,-0.335131,-0.115027,0.251662,0.983855,-0.313619,0.104001,0.587192,-0.142333,-0.647956,-0.548543,-0.020369,-0.190057,0.255309,-0.545640,-0.564804,0.014243,-0.255690,-0.162532,0.730339,-0.395832,-0.060498,0.556035,0.672786,0.042844,0.021363,0.095441,0.396188,0.082464,0.761874,-0.326584,-0.794363,0.610680,0.122276,-0.020213,-0.375830,-0.153838,0.564237,0.269283,0.307189,0.099815,0.181670,-0.029721,0.756300,-0.123040,0.014766,-0.247235,0.142559,-0.021505,0.493478,0.310049,-0.178721,0.329894,0.212424,-0.220313,-0.584598,0.059974,0.130210,0.247664,-0.183498,0.102591,-0.315029,0.069720,-0.157381,-0.135912,-0.277205,0.279819,0.270106,0.033501,0.168496,0.292512,-0.169781,0.707661,-0.020923,-0.091298,-0.604103,0.225011,-0.190095,-0.545111,0.118472,-0.152701,-0.382947,-0.002168,0.399953,-0.055120,0.481196,0.075638,-0.238793,-0.203811,-0.268598,-0.419312,0.094143,-0.106891,0.236146,-1.385948,0.169999,0.200973,0.088599,-0.326385,0.270712,-0.201944,0.514197,-0.616466,-0.013813,0.626114,0.212099,-0.433440,0.590548,0.178643,0.452843,-0.372840,-0.288963,0.222655,0.003202,0.228247,-0.061566,0.134580,0.321735,-0.482890,-0.272039,0.218295', '34961898', '1298616', '2075345', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077826', '女校风波', '喜剧', '少女克莱尔·里昂斯（艾伦·马洛 Ellen Marlow 饰）随父母从奥兰多搬到西切斯特，由于尚未找到合适住所，里昂斯一家暂时住在朋友威廉姆·布洛克（David Chisum 饰）的家中。布洛克的女儿梅西（伊丽莎白·麦克洛林 Elizabeth McLaughlin 饰）养尊处优，个性张扬，她所就读的奥克特私立女子中学更是一所云集了高贵娇小姐的学校。在她眼里，衣着质朴、个性单纯的克莱尔如同一只丑小鸭。不同的身份和成长环境令两个女孩之间无法建立平等的友情，梅西和同党们在学校里想方设法整治克莱尔，而克莱尔也受虚荣心的驱使，一心结交这群高贵的小姐们。在这一过程中，她们各自迷失了自己……本片根据美国作家Lisi Harrison同名畅销少女小说的第一部改编。©豆瓣', '瓦妮莎·马兰洛', '迈克尔·莱拜克', 6.3, 14153, 'tt1059905', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2195835425.jpg', 2.4, 13.7, 56.2, 20.3, 7.3, '0.542920,0.020716,-0.688672,0.607574,-0.091384,-0.364716,0.536113,0.304860,-0.408812,-0.484700,0.178536,0.785525,-0.002992,0.418939,0.306650,-0.097284,-0.444821,-0.439648,-0.161787,-0.425166,-0.040978,-0.309997,-0.119007,-0.458042,-0.145109,-0.390773,0.513533,-0.372125,-0.201320,0.438537,0.290605,0.396866,-0.092654,-0.099796,-0.165171,-0.000603,0.155517,-0.048673,-0.247050,0.295815,0.044473,0.130205,-0.207079,0.007061,0.389315,0.210597,0.811095,-0.360928,0.218567,-0.125372,0.372454,0.255165,0.204507,0.344883,0.231904,-0.486820,0.112324,-0.039912,-0.237970,0.085728,0.112563,-0.366041,-0.529940,-0.183354,0.278206,0.251899,-0.382896,0.267986,0.024946,-0.263547,0.065587,-0.395314,-0.189703,0.082021,0.135275,0.274341,0.183386,-0.020100,-0.255828,0.149985,0.571270,0.255394,-0.346436,0.214610,-0.632334,-0.371087,-0.218538,-0.078219,-0.866811,-0.199646,0.342641,-0.121870,0.184507,0.468286,-0.589436,-0.160500,-0.342761,0.089039,-0.064519,-0.459428,0.065058,-0.700534,-0.206903,-0.470945,-0.002721,-0.099459,0.125567,-0.044186,0.796628,-0.868838,0.045187,0.478412,0.227258,-0.228491,0.425050,-0.041654,0.308599,-0.132283,-0.274859,0.506240,0.351766,0.007752,-0.089470,0.474953,-0.191948,-0.003459,-0.418064,0.432269', '3811356', '1309161', '25922902', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3077840', '三只猴子', '剧情', '在一个阴沉的雨夜，准备参加竞选的老板塞维（厄康•吉赛尔 Ercan Kesal 饰）驾车撞死了一个路人。他极度恐惧，于是选择了找司机伊约（里法特•桑贾尔 Rifat Sungkar 饰）顶包，并许诺出狱后给他一笔钱。伊约的家境非常不好，孩子厌学，妻子海瑟（哈提斯•阿斯兰 Hatice Aslan 饰）也对他颇有微词，为了能够改善家庭环境，他毅然决定接受塞维的条件，充当替罪羊改善家人的生活。然而，事情却没有想象中那么简单。为了救出丈夫，海瑟希望塞维出面求情，并以身体交换作为筹码，这种超越底线的交易，最终让这对夫妻陷入了更加复杂的困境……本片导演尼瑞•贝利奇•锡兰获得第61届戛纳电影节最佳导演奖。©豆瓣', '亚武兹·宾戈尔', '努里·比格·锡兰', 7.6, 13051, 'tt1233381', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1520758383.jpg', 0.6, 3.6, 27.6, 49.5, 18.6, '-0.155716,0.072831,-0.332448,0.581858,-0.199248,-0.380023,0.529059,0.335138,-0.539563,-0.272872,0.046428,0.864248,0.205459,-0.045264,0.449118,-0.269145,-0.494475,-0.342434,0.227249,-0.112331,-0.090858,-0.642879,-0.200490,-0.217203,-0.327352,-0.141813,0.713031,0.014564,-0.210584,0.464547,0.343392,0.148138,0.409661,0.531932,-0.090042,-0.046204,-0.043717,0.204478,-0.614228,0.353802,0.056056,0.055175,-0.120867,0.395876,0.200175,0.525724,0.383912,-0.118940,-0.300364,-0.109324,0.283777,-0.214669,-0.068451,-0.002448,-0.014634,-0.049247,0.196407,0.139593,-0.278295,-0.025304,0.097851,0.007656,-0.952243,0.107145,0.219267,0.069973,-0.579404,0.151481,-0.004811,0.091812,0.005754,-0.079748,-0.005797,0.384196,0.369471,0.120086,-0.433471,0.062131,-0.390435,0.151557,0.490348,-0.076225,-0.099964,0.370152,-0.548838,-0.449245,0.289147,-0.176064,-0.437133,0.057541,0.241724,0.216273,-0.132180,0.033502,-0.219298,-0.287709,-0.226826,-0.104666,-0.057565,-0.594026,0.333527,-0.350241,0.028273,0.123588,-0.324743,-0.084095,0.279838,-0.420388,0.350441,-0.578653,0.141940,0.369152,0.582189,-0.556269,0.438025,0.284950,0.213912,-0.557001,-0.301967,0.222356,-0.135363,0.065253,-0.189410,0.090344,0.103489,-0.377816,-0.173650,0.445853', '26678784', '1793491', '1308976', '1304977');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3078386', '道林·格雷', '剧情', '穷小子道林格雷（本·巴恩斯 Ben Barnes 饰）从乡下来到伦敦，结识了社交场上的著名画家巴兹尔（本·卓别林 Ben Chaplin 饰）和绅士亨利（科林·费斯 Colin Firth 饰），两人见他长相俊美，所以引荐他进入社交名流圈。巴兹尔专门以他为人体模特，画了 一幅细腻入微、栩栩如生的半身肖像画，立刻引起社交圈的惊艳和赞叹。从此，格雷进入了名利场，每日过着五光十色的生活。一次偶然的机会，他爱上了小剧场演员塞西莉亚，两人一见钟情，私定终身。听说格雷要结婚，亨利便开始诱导他，不要相信婚姻，应该好好享受风月。于是，格雷跟爱人之间产生了矛盾，后来人们在河中发现了她怀孕的尸体，这让他非常震惊和懊恼，但是无力挽回。格雷彻底堕落，不断用女人、酒精甚至毒品麻醉自己。一个灵魂从此走上了邪恶的道路……本片根据英国作家王尔德发表于1891年的第一篇小说《道林·格雷的画像》改编。', '本·巴恩斯', '奥利弗·帕克', 6.8, 44768, 'tt1235124', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p769586059.jpg', 1.2, 8.1, 48.3, 33, 9.4, '0.171942,0.099816,-0.558046,0.602243,0.011140,-0.460927,0.651818,0.034023,-0.524292,-0.114284,-0.119237,0.758958,-0.477299,0.315069,0.340440,0.065619,-0.556386,-0.745560,0.131030,-0.155732,-0.239378,-0.291406,-0.185722,-0.454772,-0.156361,-0.378732,0.298232,-0.084696,-0.151429,0.483436,0.200115,0.254489,0.136682,0.253723,-0.097423,0.060125,-0.002760,-0.072439,-0.315335,0.096237,0.119492,-0.297731,-0.166291,0.076806,0.004416,0.113684,0.607627,-0.318220,-0.155045,-0.079516,0.554070,-0.136480,0.064825,0.215800,-0.201501,-0.087174,0.140975,0.018296,-0.191672,0.025119,0.127476,-0.115878,-0.267952,-0.048171,-0.210316,0.170470,-0.468999,0.452020,-0.068471,-0.043022,0.027064,-0.253330,0.064803,0.150036,0.378248,-0.031005,-0.092636,0.106320,-0.367584,0.372597,0.363491,0.412491,-0.284142,0.122485,-0.218917,-0.408398,-0.079950,-0.029122,-0.245561,-0.042631,0.394716,-0.093627,-0.112870,0.270911,-0.557541,-0.354758,-0.192378,-0.100293,-0.117513,-0.301153,-0.037594,-0.706383,-0.390443,-0.284188,-0.223069,-0.168995,-0.046974,-0.287634,0.648622,-0.694446,0.312792,0.386656,0.255659,-0.399785,0.577084,0.070680,0.047326,-0.214589,-0.082380,0.460211,0.050972,0.190432,0.224705,0.461085,0.079833,0.162119,-0.283015,0.570762', '3016252