INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3078390', '太平轮(上)', '剧情', '抗日战争胜利前夕，国军将领雷义方（黄晓明 饰）以惨重的代价取得了重大胜利，这次战役中的幸存者还有通讯兵佟大庆（佟大为 饰）以及台湾籍日军军医严泽坤（金城武 饰）。抗日战争结束，雷义方迅速与千金小姐周蕴芬（宋慧乔 饰）相恋结合；佟大庆喜欢上了跟自己假扮夫妻拍照各取所需的孤 女于真（章子怡 饰），两人相遇不久就各奔前程；严泽坤顺利回到台湾，乘坐“太平轮”穿梭于海峡两岸购买药材，却心系青梅竹马的日籍女子雅子（长泽雅美 饰）不能忘怀。内战的爆发迫使雷义方和佟大庆重回战场，周蕴芬和家人乘“太平轮”去了台湾，从此开始漫长的等待。历史的不幸使大家相遇，“太平轮”成了几对情侣此生的牵挂。本片为《太平轮》的上集。©豆瓣', '章子怡', '吴宇森', 6, 94697, 'tt2150371', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2212075889.jpg', 6.1, 20.2, 48.6, 19, 6, '-0.238514,-0.055554,-0.415135,0.226475,0.310538,-0.176233,0.199036,-0.001024,-0.240170,0.017984,0.200973,0.655313,-0.278200,-0.194816,0.409595,-0.256931,-0.115119,-0.923306,-0.006407,0.048725,-0.071131,-0.283802,-0.080036,-0.238892,-0.089766,-0.100176,0.468049,0.454275,-0.102572,0.950297,0.346110,0.065224,-0.420859,0.293787,-0.063728,0.214386,-0.144207,0.172602,-0.681859,-0.029303,-0.263480,-0.379091,0.093240,-0.225848,0.246158,0.011718,0.842897,-0.406824,0.135001,-0.222775,0.218976,-0.004087,-0.280255,0.170297,0.295619,0.266358,0.210152,0.141801,-0.213737,0.077842,-0.115417,-0.101409,-0.309535,0.045901,0.045552,-0.026361,-0.301481,0.846277,0.042375,0.119074,0.242206,0.012481,0.364318,0.876613,0.281861,0.083588,0.032004,-0.080406,-0.290899,0.448490,0.848219,-0.095106,0.134679,0.175929,-0.000172,-0.473751,0.068576,-0.185188,-0.180265,0.128686,0.252548,-0.092245,0.288629,0.178205,-0.480157,0.063448,-0.403406,0.068317,0.344142,-0.226735,0.086616,-0.693857,-0.129230,-0.647543,-0.202206,0.265429,-0.076049,-0.203502,0.762644,-0.688614,0.039357,0.152323,0.327324,-0.550273,0.501871,0.288182,0.383959,-0.316406,0.084762,0.380328,-0.236460,0.340274,0.167862,0.011498,-0.381159,0.069858,-0.274091,-0.028775', '26365262', '3230460', '4202326', '3139191');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3078391', '破碎之城', '剧情', '比利·塔吉特（马克·沃尔伯格 Mark Wahlberg 饰）是一名备受尊敬的纽约警察。然而在一次追捕杀人犯人中致后者死亡，最终审判结果被私下篡改，犯人被定为自卫，而被市民称为“英雄”的塔吉特却被迫离开警局。7年后，塔吉特以一名私家侦探的身份重新出现，然而市场并不景气，濒临破产之际，市长霍斯泰特勒（罗素·克劳 Russell Crowe 饰）找到他，让他帮忙查出妻子凯瑟琳（凯瑟琳·泽塔-琼斯 Catherine Zeta-Jones 饰）的情夫。然而事成之后，塔吉特却渐渐发现事件并非表面上那么简单，在此背后隐藏的政权利益、金钱交易和肉体买卖仿佛黑幕般笼罩着纽约这座破碎之城，牵扯其中的甚至还有7年前自己那桩冤案……©豆瓣', '马克·沃尔伯格', '艾伦·休斯', 5.7, 4957, 'tt1235522', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1729011590.jpg', 3.6, 24.7, 56.6, 12.6, 2.6, '0.255904,0.359466,-0.668434,0.469620,0.010090,-0.131418,0.666172,0.281911,-0.525469,-0.398142,0.371791,0.677157,-0.197445,0.091496,0.268239,0.223886,-0.366102,-0.532020,0.337982,-0.385670,-0.181849,-0.529049,-0.369806,-0.113028,-0.357585,-0.334277,0.577398,0.224479,-0.038263,0.213191,0.230128,0.630018,-0.040797,0.548544,0.262362,-0.106050,0.435074,-0.269116,-0.260876,0.252933,-0.174934,0.033264,-0.062384,0.205676,0.023905,0.556101,0.226297,-0.236836,0.077233,-0.214991,0.392994,-0.352587,0.238593,0.056097,0.409933,0.027638,0.013421,0.391902,-0.446300,-0.201004,0.420207,-0.157072,-0.436853,-0.108658,0.187558,0.174789,-0.437769,0.099750,-0.329570,0.139163,-0.200023,-0.147811,0.123641,0.423420,0.392870,0.099944,-0.052668,-0.132545,-0.658758,0.060212,0.387506,-0.147027,-0.539665,-0.039937,-0.135069,-0.486526,-0.069370,-0.249544,-0.112301,-0.069848,0.379776,0.015382,-0.076769,0.508246,-0.378821,-0.291821,-0.658513,-0.077942,-0.135676,-0.349113,-0.036798,-0.663947,-0.236097,0.054891,-0.226291,-0.061645,-0.019331,-0.018723,0.106649,-0.597615,0.398185,0.637832,0.422879,-0.177909,0.362910,-0.021314,0.172134,-0.154551,-0.320215,0.416104,0.557117,0.367031,-0.023710,-0.058997,0.099122,-0.405765,-0.087643,0.559479', '26949264', '1297260', '7916027', '20277632');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3078403', '解冻', '科幻', '工业高度发达，为人类生活带来前所未有的便利，却同时将世界推向毁灭的边缘。人们过于专注自身生活水平的提高，而忽略的对赖以生存的地球的合理保护。随着二氧化碳排放量持续增多，全球日趋变暖，两极的冰川开始融化。十年来，世界各地的科学家们不断向世人发出警告，海平面上升将最终淹没人类的家园，但真正的威胁还远远不止于此。阿德姆（Aaron Ashmore 饰）、菲德里克（Kyle Schmid 饰）、陈玲（Steph Song 饰）三名大学生来到加拿大北部班克斯岛，准备协助生态学家大卫•克鲁潘（Val Kilmer 饰）在当地进行考察。他们在科考站发现了克鲁潘博士遗留在这里的北极熊尸体，此时博士一行人已被北极熊身上携带的神秘病毒感染。随着冰川的融化，这种致命病毒也从永恒的睡眠中苏醒……©豆瓣', '宋琇萱', 'Mark A. Lewis', 6.2, 10356, 'tt1235448', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1582884800.jpg', 2.8, 15.4, 54.9, 20.5, 6.3, '0.071776,0.298179,-0.852392,0.606999,-0.099247,-0.045032,0.856617,0.026931,-0.350128,-0.161753,0.186986,0.578351,-0.137690,-0.077572,0.245565,-0.273897,-0.266842,-0.605528,-0.212184,-0.077757,-0.581405,-0.281117,-0.520825,-0.132300,-0.458928,-0.540912,0.741170,0.297122,-0.399079,0.532188,-0.342790,0.458272,-0.124040,0.571060,-0.174111,-0.246044,-0.084501,-0.411539,-0.249111,0.323157,-0.024138,-0.090852,0.187444,0.051267,-0.105962,0.154923,0.888457,-0.380766,-0.053865,-0.356217,0.573448,-0.540222,-0.000426,0.064668,0.397755,0.116976,-0.205427,0.098043,-0.242047,0.027749,-0.016758,-0.030816,-0.647705,-0.074182,0.031768,0.154512,-0.376956,0.340748,0.211435,-0.181865,-0.086729,-0.261397,0.216245,0.289954,0.005130,0.614087,-0.335140,-0.032357,-0.333181,0.101183,0.524319,-0.118512,-0.439017,0.062555,-0.349090,-0.418642,-0.122999,-0.045053,-0.209006,-0.359538,0.075525,0.382592,-0.041058,0.591710,-0.877687,0.235180,-0.242014,-0.637510,0.063486,-0.264522,-0.351455,-0.898027,-0.210395,-0.237639,0.018471,0.193737,0.049210,-0.248465,0.775537,-0.578424,0.258470,0.537237,0.565487,-0.211990,0.305286,-0.419076,0.164349,-0.170366,-0.337107,0.486340,0.196079,0.501840,-0.124947,0.223935,0.027897,0.128953,-0.436842,0.517194', '2159244', '1307897', '25774050', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3078409', '古驰家族', '剧情', '本片围绕时尚品牌古琦（Gucci）的第三代接班人毛里奇奥·古琦（Maurizio Gucci）的故事展开，毛里奇奥是古琦创建人古琦欧·古琦（Guccio Gucci）的孙子，1995年被一个西西里岛的年轻人枪杀于米兰办公室的楼梯上，他的妻子Patrizia Gucci因策划杀夫一案而被判入狱29年。', 'Lady Gaga', '雷德利·斯科特', 6.3, 27136, 'tt11214590', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2688624729.jpg', 2.5, 14.7, 53.1, 22.8, 6.9, '0.238153,-0.359785,-0.356013,0.469957,-0.068055,-0.361546,0.552971,0.091021,-0.650414,-0.287064,0.203817,0.607922,-0.319607,0.430046,0.466353,0.378854,0.047747,-0.847439,-0.235852,-0.156951,-0.261825,-0.451721,-0.436249,-0.211994,-0.103125,-0.024377,0.429009,0.005991,0.135487,0.411225,0.756268,0.227116,0.049093,-0.151807,0.057531,0.228391,0.113337,-0.108484,0.030055,0.020938,-0.054247,-0.592804,0.114548,-0.000091,-0.211241,0.463373,0.495495,-0.299909,0.576133,-0.787222,0.584242,-0.261434,-0.319435,0.101698,0.628667,0.447299,0.295449,0.569839,-0.220198,-0.611069,0.066454,-0.347959,-0.519320,-0.234068,0.163025,0.169127,-0.499577,0.553316,-0.410979,0.220186,-0.102597,-0.374336,0.012553,-0.332749,0.285792,0.521630,-0.010239,0.122628,-0.429656,0.133933,0.182015,-0.045881,-0.145264,-0.089036,-0.032143,-0.231164,-0.100658,-0.230028,-0.455020,-0.068078,0.271791,-0.248973,0.208253,0.446753,-0.464036,0.035547,-0.468665,-0.163065,-0.039533,-0.034101,-0.538064,-0.096761,-0.057552,-0.272512,-0.073936,-0.008386,-0.092924,-0.165088,0.278338,-0.498491,0.312094,0.304822,-0.009818,-0.342821,0.881182,-0.282806,0.522876,-0.091605,-0.260067,0.241867,0.111741,-0.128848,0.159725,0.419678,-0.413048,-0.276907,-0.187176,0.319843', '11510624', '1293643', '1291564', '1777570');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3078514', '特别响，非常近', '剧情', '九岁男孩奥斯卡·史埃尔（托马斯·豪恩 Thomas Horn饰）的父亲（汤姆·汉克斯 Tom Hanks饰）在911事故中丧生，在他幼小的内心中留下了阴影。无意间奥斯卡发现了一封写着“布莱克”的信封和一把钥匙。奥斯卡认为这是父亲给他留下的寻找线索，钥匙背后一定隐藏着什么 秘密。奥斯卡把这一秘密告诉了不会说话的老爷爷（马克斯·冯·西多 Max von Sydow饰）。此后的每个周末，奥斯卡开始在五个城区里寻找姓“布莱克”的人。父亲生前跟奥斯卡一起规划了寻找第六城区的“侦查探险”游戏，告诉奥斯卡：不要停止寻找。本片根据作家乔纳森·萨佛兰·福尔的小说改编。©豆瓣', '桑德拉·布洛克', '史蒂芬·戴德利', 7.7, 33460, 'tt0477302', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1353738074.jpg', 1, 4.3, 27.4, 42.2, 25.1, '0.153347,-0.224407,-0.663642,0.849818,-0.010258,-0.274515,0.710362,-0.114627,-0.305747,-0.219137,0.015260,0.927013,-0.064279,0.408999,0.193890,0.038468,-0.520311,-0.674375,-0.175381,-0.298424,-0.379431,-0.638942,-0.475419,-0.023206,0.064972,-0.148186,0.397869,0.136055,-0.123312,0.364379,0.389170,0.075561,-0.393664,0.083785,-0.025838,0.254497,0.249442,-0.080527,-0.202234,0.389521,0.227320,-0.169688,-0.034914,0.141045,0.288259,0.436972,0.578430,-0.349302,0.155641,0.104862,0.483491,0.012969,-0.106818,-0.076856,-0.044776,0.190228,0.213131,0.312324,-0.208674,0.147542,0.108570,-0.258628,-0.755890,-0.098638,0.066271,0.561096,-0.684524,-0.000860,-0.325618,0.072536,0.272028,-0.153438,0.621341,0.153814,0.298828,-0.096951,-0.161948,-0.007725,-0.452561,0.232343,0.014749,-0.285794,0.173377,0.096729,0.035844,-0.237177,0.072296,0.264413,-0.509074,0.219534,0.457818,0.023537,-0.143009,-0.053594,-0.312543,-0.098673,-0.061603,-0.449919,0.063988,-0.304276,-0.143404,-0.486332,-0.037129,-0.081863,-0.178546,-0.133450,-0.085963,-0.288908,0.698033,-0.433630,0.252098,0.518699,0.289690,-0.228319,0.618687,0.077829,0.227217,-0.331193,0.118143,0.170172,0.250726,0.476039,0.153898,0.297693,0.198488,-0.458070,-0.633777,0.561606', '25837262', '4206468', '34890458', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3078517', '分手信', '剧情', '美国陆军特种部队的约翰（钱宁·塔图姆 Channing Tatum 饰）在家乡渡假时意外结识渡假的女学生莎文娜（阿曼达·塞弗里德 Amanda Seyfried 饰），两人很快便深陷爱河。约翰成年后和自己的醉心于收集硬币的父亲鲜有交流，莎文娜却对约翰的父亲十分友善。两人的假期很快结束，分别时约翰承诺莎文娜自己的服役期一年后便结束，之后两人便再也不分离。海外驻军常常扎营在一些偏远的地区，约翰只能通过信件和莎文娜互诉衷肠，在那些充满浓情蜜意的文字间二人都憧憬着日后可以长相厮守。911事件爆发，面对约翰不得不延长的服役期，俩人的感情出现危机，不过很快便重归于好。约翰回到部队很久都没有收到莎文娜的来信，日思夜盼等来的却是莎文娜分手信。在失恋的怆痛未弥合之时，约翰不幸负伤，在昏迷的前一刻，约翰居然想到的是父亲收集的那些硬币。几年后，当约翰再一次见到莎文娜时，发现了那封分手信背后的秘密……本片改编自美国“纯爱小说天王”尼古拉斯·斯帕克斯（Nicholas Sparks）的第11部小说《分手信》。', '阿曼达·塞弗里德', '拉斯·霍尔斯道姆', 7, 85389, 'tt0989757', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p500444655.jpg', 1, 6.5, 44.8, 35.8, 11.8, '0.334270,-0.109463,-0.775707,0.425692,0.109234,-0.603536,0.698961,-0.098261,-0.422897,-0.307061,0.012425,0.692932,-0.438994,0.280104,0.062056,-0.342451,-0.522006,-0.727534,-0.097674,-0.483756,-0.261321,-0.508222,0.001405,-0.092422,-0.023450,-0.394278,0.475179,-0.003520,-0.076906,0.566931,0.058496,0.227947,-0.253736,0.624077,-0.217237,0.194558,0.141794,0.196626,-0.412634,0.206563,0.189793,0.010654,-0.159347,0.015132,0.136891,0.314277,0.771406,-0.130488,-0.074405,0.194348,0.248244,0.077622,-0.129165,0.109620,0.283137,0.055517,0.266953,0.229666,-0.319757,-0.005994,-0.190649,0.112090,-0.344665,0.092574,-0.221370,0.246456,-0.385539,0.370451,-0.190203,0.205467,0.115760,-0.324949,0.119220,0.660351,0.195484,0.393077,-0.097592,0.101376,-0.314364,0.210507,0.694810,-0.178098,-0.244768,0.359308,0.018909,-0.547751,0.095713,0.192018,-0.412407,0.021490,0.339456,0.085695,-0.091577,0.252134,-0.521849,-0.156505,-0.349896,-0.072071,0.324398,-0.339438,-0.222645,-0.703940,-0.087486,-0.262373,-0.397077,0.181442,0.184082,-0.083441,0.531872,-0.506304,0.506971,0.319536,0.060804,-0.252177,0.560793,0.247831,0.007116,-0.193425,0.050429,0.501185,0.145225,0.346407,0.316904,0.18665