INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3078521', '迷踪：第九鹰团', '剧情', '20年前，强盛的罗马帝国派出由5000精兵组成的罗马第九军团，却在苏格兰高地神秘消失。第九军团首领之子马库斯（查宁·塔图姆 Channing Tatum 饰）骁勇善战，带兵征战在前线。因为在一场战争中严重受伤，他不得不在叔叔家中养伤。养伤期间，马库斯在角斗场中救下一名奴隶埃斯科（杰米·贝尔 Jamie Bell 饰），并将其收为仆人。不久之后，马库斯听闻北方一个部落有人发现了当年父亲遗失的鹰杖，立志为父亲赢回荣誉的他决心远赴北方拿回鹰杖。马库斯带着对北方环境比较熟悉的埃斯科一起出发。路途中主仆二人的关系经历了各种起伏与相互考验。尤其是当他们遇到凶狠的西尔王子（塔哈·拉希姆 Tahar Rahim 饰）后，马库斯发现埃斯科的身份远远不只是个普通的奴隶那么简单。究竟谁掌控着鹰杖，当年的第九军团是如何覆灭的？真相愈加扑朔迷离……©豆瓣', '查宁·塔图姆', '凯文·麦克唐纳', 6.3, 9446, 'tt1034389', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p706164568.jpg', 1.8, 14.4, 55.3, 22.8, 5.7, '0.188802,0.069588,-0.824296,0.727324,0.000228,-0.042526,0.526670,0.052261,-0.436836,-0.425848,0.333187,0.783445,0.335379,0.088206,0.235704,-0.071870,-0.175213,-0.569155,-0.127714,-0.205297,-0.159599,-0.496533,-0.463479,-0.013064,-0.102468,-0.508746,0.524217,0.088521,-0.026023,0.536750,0.208865,0.296338,-0.229998,0.255068,-0.083039,-0.168789,0.170714,-0.046845,-0.391215,0.213196,-0.210272,-0.028251,-0.180087,0.085760,0.104858,0.303624,0.626906,-0.488608,0.198201,-0.312934,0.043216,-0.233822,0.004284,0.052448,0.694442,0.119072,-0.026614,0.343610,0.066930,0.022357,-0.347272,-0.112196,-0.591180,-0.008065,0.152679,0.156971,-0.702481,0.508685,-0.280951,-0.119427,0.174102,-0.201318,0.286633,0.683549,0.188447,0.173750,-0.002882,-0.107344,-0.519332,-0.049383,0.802432,-0.148874,-0.171352,-0.256241,0.099146,-0.553377,0.102036,-0.394142,-0.320549,0.063665,0.357674,-0.022351,0.150964,0.405593,-0.545710,0.059102,-0.278206,-0.238843,0.036017,-0.292845,-0.005694,-0.370342,-0.086933,-0.590070,-0.194135,0.083114,0.017517,0.043772,0.374045,-0.744703,0.237961,0.391377,0.382262,-0.374024,0.241972,0.148586,0.400701,-0.085161,-0.108911,0.326657,0.316015,0.170613,0.111633,0.096232,0.046261,-0.229054,-0.285819,0.381282', '25721544', '1301022', '24325798', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3078549', '虎胆追凶', '动作', '在枪案频发的芝加哥，保罗原本是一个温文儒雅仁心妙手的医生，拥有一个幸福美满的家庭。一场突如其来的厄运让他的妻女惨遭暴徒欺凌，女儿昏迷不醒，爱妻更因此丧失生命，与他天人永隔。然而，城市里连串的凶案让警方束手无策，种种原因使得保罗的案件无法结案，本应受到制裁的凶徒逍遥法外。在崩溃和绝望中，保罗的人生价值观彻底改变。为了替家人复仇，保罗决定孤身寻凶，主动出击，单枪匹马在城市街头制裁暴力犯罪。警方和大众对这位伸张正义的神秘“帽兜男”众说纷纭，争论不休。在“守护天使”的外衣下，保罗最终迎来了和仇人的生死决战。', '布鲁斯·威利斯', '伊莱·罗斯', 6.5, 26404, 'tt1137450', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2532509221.jpg', 1.1, 8.5, 60.8, 25.7, 3.9, '0.053183,0.031885,-0.538951,0.409474,-0.213231,-0.021567,0.859801,0.246876,-0.526043,-0.218947,0.590958,0.918219,-0.041695,0.191604,0.333421,-0.437557,-0.220002,-0.749721,-0.223534,0.055323,-0.389613,-0.563528,-0.294906,-0.183463,-0.164171,-0.310726,0.753925,0.332371,-0.284838,0.373142,0.284590,0.586451,-0.177562,0.468810,-0.215478,-0.156851,-0.063926,-0.029359,-0.606540,0.371497,0.155351,-0.425689,-0.176262,0.571359,-0.459313,0.257529,0.732180,-0.537750,-0.185434,-0.453221,0.543963,-0.716843,-0.151879,0.334146,0.340721,-0.168354,0.002763,0.306804,-0.174485,-0.129678,0.308618,0.045430,-0.842813,0.010473,0.235548,0.251973,-0.567148,0.498897,-0.118103,0.093936,0.146137,-0.188834,0.216632,0.285169,0.387573,0.453038,-0.385561,0.063959,-0.543059,0.101712,0.913983,0.018800,-0.220276,-0.129622,-0.343318,-0.276916,0.044567,-0.458332,-0.771826,-0.042513,0.280011,-0.144814,-0.318857,0.435707,-0.446034,-0.163460,-0.568361,-0.303981,-0.295011,-0.471566,-0.114219,-0.475860,-0.247412,-0.091083,-0.124751,0.310693,0.150680,-0.193917,0.577200,-0.717474,0.231477,0.679747,0.224394,-0.578867,0.392510,0.432352,0.385501,-0.081799,-0.291739,0.264794,0.285211,0.562048,0.023006,-0.046532,-0.158834,0.171064,-0.286068,0.317865', '25828589', '2988294', '1309116', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3078609', '爱情与灵药', '剧情', '杰米（杰克•吉伦哈尔 Jake Gyllenhaal 饰）出身医药世家，舌灿莲花，热情似火，是电器行的金牌销售，不过由于桃花运太壮，以至于因为跟女同事在工作时间亲热，被老板开除。此后，他在辉瑞公司连番洗脑后，成为了一名医药销售代表。为了能打开区域市场，他摸清了某医院的底细，决定从主治医师斯坦下手。他用1千美元的支票，换取了一个实习生的身份，穿梭于诊室。某日，他偶然间邂逅了因帕金森症就诊的女患者玛姬（安妮•海瑟薇 Anne Hathaway 饰），并阴差阳错瞥见了她的乳房。正当花花公子以为占了便宜时，却被玛姬抡包打伤，甚至还拍了照片。为了讨回声誉，他利用关系要到了对方号码，并约她面谈。没想到这次约会，却让两人陷入了匪夷所思的亲密关系之中，令他难以自拔。正当杰米因伟哥成为销售红人时，玛姬的病患却每况愈下……©豆瓣', '安妮·海瑟薇', '爱德华·兹威克', 7.2, 205634, 'tt0758752', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1525267789.jpg', 0.4, 4.2, 42.6, 39.8, 13, '0.139984,0.169842,-0.419132,0.216920,-0.225716,-0.383496,0.464628,0.342174,-0.488457,-0.235811,0.191044,0.539203,-0.347318,0.079604,0.280338,0.012480,-0.065004,-0.623063,0.093077,-0.075792,-0.221904,-0.219937,-0.230737,-0.110405,-0.135662,-0.241334,0.264865,-0.184328,-0.422874,0.319658,0.117228,0.156839,0.023271,0.511541,-0.104174,-0.013076,0.333754,0.019858,-0.262666,0.383433,0.100177,-0.382218,0.143219,0.162381,0.107770,0.597108,0.554340,0.131407,-0.163374,-0.000402,0.291564,-0.091847,-0.086392,0.031901,0.300374,-0.004733,0.242503,-0.102550,-0.402769,0.124279,0.290037,-0.087244,-0.770135,0.147662,0.030337,0.072619,-0.571005,0.565424,-0.337523,-0.008984,-0.128723,-0.212094,0.043815,0.339083,0.108112,0.169859,-0.016246,0.055531,-0.488132,0.233396,0.348124,0.007827,0.092396,0.468817,-0.314970,-0.431793,0.144806,-0.109861,-0.229400,-0.053437,0.549718,0.019986,-0.093618,0.040091,-0.368371,-0.169675,-0.407409,-0.221306,0.122571,-0.356835,-0.063823,-0.432541,-0.153889,-0.105976,-0.301039,-0.027470,0.201614,-0.053144,0.429813,-0.694659,-0.066159,0.643522,0.395605,-0.428923,0.591821,0.203917,-0.035031,-0.121872,-0.207120,0.016530,0.195849,0.462074,0.237787,0.181710,0.042716,-0.331194,-0.151113,0.390809', '1793491', '1947080', '1307442', '1294893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3080192', '喜盈门', '剧情', '1970年代末，中国大陆某北方乡村。陈家这日正为仁武（马晓伟）与薛水莲（温玉娟）的新婚欢天喜地，仁武嫂子王强英（王书勤）见新婚排场及新娘子行头均强过自己当年，一面怨婆婆（王玉梅）偏心，一面吵着丈夫仁文也要水莲穿的涤纶绸裤，后又见小姑仁芳（洪学敏）也有涤纶绸裤料（仁芳男友所送），她更认准了婆婆眼里没她，吵闹着要婆婆一视同仁，婆婆无奈欲借钱买料好求媳妇定心，善心的水莲拿出自己的钱帮婆婆解围。这是强英无理取闹的第一步，其后她更做出试图拆散仁芳与男友、分家时强夺硬抢、分家后虐待爷爷（于绍康）等事，以致顺从听话的仁文也不再能将她忍受；但也是水莲体人顾家的开始。©豆瓣', '王书勤', '赵焕章', 8.2, 6036, 'tt1021003', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2532205114.jpg', 0.4, 1.6, 16.8, 48.5, 32.7, '-0.055247,-0.124844,-0.550004,0.377110,-0.155005,-0.405573,0.196951,0.316337,-0.420767,-0.015694,0.134470,0.414294,0.116928,0.183272,0.086725,0.170513,-0.070242,-0.370854,0.326901,0.071948,-0.035234,-0.117672,0.191621,-0.054828,-0.323695,0.000034,-0.026997,-0.352949,0.067194,0.093813,0.561588,-0.080252,0.197195,0.292659,-0.252673,0.202184,-0.304472,0.378338,-0.370050,-0.082901,0.280045,0.057710,-0.399994,0.254491,0.123295,0.375070,0.218993,-0.118385,0.058495,-0.450461,0.381605,0.024112,0.164847,0.288410,0.135212,-0.138100,0.279846,0.248653,-0.120154,-0.000903,0.231972,0.196235,-0.078975,0.236982,0.213394,-0.214014,-0.674423,0.171360,-0.070650,0.041246,0.074073,-0.419145,0.031142,0.297600,-0.053123,0.217959,-0.252574,0.017240,-0.447207,0.446622,0.417524,0.099377,0.289333,0.222241,-0.127204,-0.084094,0.549587,-0.382064,-0.761706,-0.059240,0.034296,-0.037244,-0.056705,0.071802,-0.330999,-0.068266,-0.026188,0.161800,0.235450,-0.257381,0.050298,0.123548,-0.168617,-0.513026,-0.393719,0.045404,0.159928,-0.081888,0.409867,-0.251382,0.062160,0.204065,0.600531,-0.652422,0.568487,0.283906,0.265018,-0.246939,-0.016840,-0.373723,-0.325748,0.236580,0.350788,0.262925,0.176737,-0.074923,0.091458,0.284806', '1296897', '26279353', '1421278', '24879820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3082393', '青苔', '剧情', '丈（余文乐 饰）是香港深水区的一名放蛇警察，作为底层的警察，丈整日与一个难得见光的世界打交道，这里充斥着暴力、毒品，是社会阴暗的一个角落。要想在这里生存，丈不仅要学会如何做警察，更需要学习黑道的生存法则，渐渐地丈的身份越来越模糊，他生活在黑与白之间的灰色地带。Lulu（冼色丽 饰）是这一区的妓女，丈与之保持着来往，却始终没有将关系向前推进。一次意外，丈误杀小头目四眼堂（廖启智 饰），神秘杀手（樊少皇 饰）是唯一目击者，为了自保，丈和神秘杀手展开了一场追逐……杀手背后有怎样的秘密？丈是否能够逃过此劫？《青苔》为我们展现了社会阴暗处的小人物们如何似青苔一般生存。©豆瓣', '余文乐', '郭子健', 6.5, 6009, 'tt1236325', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1143482112.jpg', 2, 11.7, 53.8, 26.6, 6, '0.203005,-0.009375,-0.488460,0.761445,-0.214989,0.117277,0.740244,0.104682,-0.490151,-0.372384,0.217692,0.306647,0.123480,0.056948,-0.211526,-0.241871,-0.113275,-0.619616,-0.223526,-0.350871,-0.344027,-0.257950,-0.638122,-0.198823,-0.247210,0.083349,0.613596,0.371475,-0.243364,0.112462,0.216457,0.139650,-0.342923,0.242416,-0.386909,-0.657986,0.027118,-0.079587,-0.341713,0.080144,-0.184579,-0.266561,-0.084777,-0.055973,0.025093,0.343610,0.746656,-0.290311,-0.099577,-0.135072,0.098856,-0.123359,-0.052213,-0.252872,0.308711,-0.326013,0.196465,0.138311,0.036259,-0.036965,0.237046,-0.114789,-0.712131,-0.184065,0.257095,0.445463,-0.568348,0.231926,0.087180,-0.380101,-0.003927,0.060549,-0.062813,0.273194,0.384627,0.188793,-0.134843,-0.051899,-0.603353,0.101161,0.766331,0.200851,-0.335075,0.116330,-0.411253,-0.533371,-0.210045,-0.369572,-0.273357,-0.326240,0.124630,-0.124503,-0.222794,0.333283,-0.666922,0.211787,-0.041540,0.031825,-0.107807,-0.486354,-0.118858,-0.291854,-0.102910,-0.350582,-0.171016,0.270984,-0.012219,-0.291215,0.732520,-0.578908,0.183973,0.467987,0.399489,-0.421228,0.871946,0.128591,0.107972,-0.199056,-0.050400,0.035712,0.042479,0.326168,-0.200832,0.228291,-0.055216,-0.125089,-0.190242,0.231018', '1302661', '3055049', '2053515', '1308499');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3082396', '六楼后座2家属谢礼', '语言:', '2003年黃真真導演、鄭丹瑞編劇的喜劇《六樓后座》拍出香港新一代的愛情面面觀，其中「Truth orDare」大膽遊戲更表達時下年青人對於感情所體會的各種形態，創出票房之餘，又引起不俗的回響。2008年，黃真真新作《六樓后座2家屬謝禮》以全新的青春偶像上陣，由江若琳、田原、羅仲謙、鄭融，以及組合農夫、I Love YouBoyz及來自台灣的棒棒堂，以殯儀眾生相為主題及純粹的喜劇手法，去表達年輕人青春活潑的一面。 同樣在六樓后座發生的故事，藝術乞丐 Kay(田原飾)、無腦記者阿之(江若琳飾)、世界仔彭爺(少爺占飾)、電視台傻仔BonBon(Donald飾)與未紅先衰的Hip-hop組合「農夫」(農夫飾)同一屋簷下，除了包租婆Suzy(侯煥玲飾)仍抱有夢想之外，其他年青人只憧談戀愛及搵快錢。一天，這班年青人想出「開心喪禮」的殯儀服務，找來殯儀館一哥萬生 (曾志偉飾)投資，結果誤打誤撞之下，他們找到人生的道理……片中女角之一江若琳擺脫玉女形象，角色性格為不拘小節的男仔頭，與羅仲謙飾演的戇直古惑仔為情侶兼有親嘴戲。而農夫以真正的身份，在片中自嘲為一對未被人認識的Hip-hop組合，與首次全隊在大銀幕客串演出的台灣當紅偶像組合棒棒堂，在溜冰場上玩「Truth orDare」，形成莫大的對比。此外，《六樓后座》的林嘉欣、盧巧音、周俊偉和森美也亮相，為這場續作《家屬謝禮》打氣。導演︰黃真真Director: Wong Chen Chen五年前，后座玩 Truth or Dare 玩到通街都係。五年後，誠實大膽巳經 OUT，虛擬 Online 先叫潮；愛情已經 Out，搵錢先係 Yeah；今日', '田原', '黄真真', 6.5, 5861, 'tt1236332', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p916244428.jpg', 3.2, 13.1, 48.4, 26.6, 8.8, '0.193673,-0.027867,-0.552381,0.565372,0.028408,-0.354500,0.498136,0.186829,-0.379195,-0.000243,0.280990,0.511132,-0.412470,0.192357,0.432491,-0.215732,-0.024430,-0.667285,-0.396519,-0.178029,-0.204616,-0.245978,-0.406558,0.206758,-0.427010,-0.283756,0.501816,-0.329923,-0.013151,0.412468,0.544908,0.024133,0.045931,0.106832,-0.306397,0.080445,-0.207284,0.255265,-0.240747,-0.029562,0.127692,-0.327072,-0.150209,-0.282071,-0.075468,0.046630,0.622730,-0.267722,-0.083618,-0.117311,0.340677,0.157552,-0.277327,-0.331154,0.421191,-0.172072,0.383822,0.293609,0.056441,-0.078826,0.324389,0.012263,-0.531704,0.120454,0.167981,-0.041379,-0.499180,0.389047,-0.136900,-0.175927,0.139595,-0.167712,0.053597,0.158319,0.330247,0.530105,-0.098961,0.224569,-0.360675,0.220218,0.285686,0.255362,-0.188492,0.397645,-0.028966,-0.337096,-0.082331,-0.510898,-0.280780,0.003833,0.135641,-0.172334,-0.233736,-0.020948,-0.520979,0.325525,0.256973,-0.041768,0.078711,-0.304007,-0.182133,-0.525845,-0.183470,-0.389499,0.036042,-0.023707,0.317898,-0.183479,0.917228,-0.721408,0.058024,0.185149,0.109743,-0.283557,0.875540,0.167147,0.013721,-0.062837,-0.336855,-0.096289,-0.059023,0.284851,0.060870,0.592020,-0.319653,-0.289811,-0.415531,0.418578', '1302661', '3811356', '1307146', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3082452', '狼牙', '动作', '台风过境，阴霾的天色不知会在闭港的小岛上空持续多久，陈旧的民宅内，几个帮派人物突遭袭击，来人身手矫健，斩去当家马天泰之首级后消失于夜色……次日，小岛女警晓禾（Celina Jade 饰）为救自家的猫坠树，一过路男子相救，他自称阿布（吴京 饰）。两人在食档与三名泰国悍匪狭路相逢，晓禾耿直但无法抵敌，阿布出手拼倒三人，随晓禾暂留警局。阿布令属意晓禾的警员泰山（森美 饰）大为吃味，同袍关公（许绍雄 饰）与靓宝（方力申 饰）冷语调笑，给这孤独的小岛警局凭添了不少温馨活气。马天泰遗孀佐佐木（青山伦子 饰）命手下肥荣（林雪 饰）带人登岛，寻回马爷头颅凑成全尸，孰料晓禾与泰山巡逻中发现藏尸处反将尸身也带走，肥荣等人冲入警局抢尸，混战中靓宝中枪殉职。港口重新开放，大批警员登岛，阿布因断头案的嫌疑被短暂扣留后释放，他虽然能瞒过警方，却无法摆脱佐佐木的追杀，晓禾被对方掳走以后，阿布再没有其他选择……', '吴京', '李忠志', 6.4, 43976, 'tt1236370', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p668656862.jpg', 2.6, 12.7, 52.9, 23.4, 8.3, '0.030178,-0.101556,-0.541013,0.223110,-0.026227,-0.067341,0.727911,0.126285,-0.451017,-0.141594,0.363461,0.453502,-0.074889,0.008348,0.119426,-0.136305,-0.216413,-0.492883,-0.201370,-0.097647,-0.259944,-0.053756,-0.202376,-0.117312,-0.046390,-0.122099,0.396988,0.301941,-0.007827,0.650772,0.066179,0.237963,-0.416717,0.439668,-0.234712,0.094806,-0.014557,-0.215209,-0.085971,0.280783,-0.365430,-0.288780,-0.228487,0.068293,-0.103551,0.326974,0.725694,0.092380,-0.101620,-0.172329,-0.189770,-0.095600,0.105158,0.152210,0.429423,-0.178544,0.104971,0.040072,-0.188832,-0.100863,0.014360,0.191384,-0.289033,0.302072,-0.038421,0.081300,-0.431937,0.148872,-0.292295,-0.046658,-0.134434,-0.261885,0.113108,0.021024,0.089870,0.053210,0.014842,0.021988,-0.428380,0.083467,0.428213,-0.217041,0.086955,-0.100144,0.076631,-0.366129,0.138275,-0.104963,0.033225,-0.161140,0.585120,-0.043855,-0.171815,-0.108409,-0.325630,-0.185706,-0.485151,0.060785,-0.448980,-0.151292,-0.211166,-0.513699,0.063701,-0.178202,-0.194540,0.282814,0.142981,0.238591,0.195097,-0.416010,0.184030,0.272018,0.248287,-0.291416,0.314139,0.149830,0.051874,0.131858,0.055928,0.045040,0.300190,0.396830,0.405090,0.158157,-0.338270,-0.217056,-0.418661,-0.141025', '3011051', '21619567', '1773217', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3089571', '总统杀局', '剧情', '美国总统大选进入白热化阶段，两位候选人在之前的得票数旗鼓相当。距离俄亥俄州的初选还有一周时间，两人都把此州当做具有决定性意义的阵地，开始明争暗斗。候选人之一莫里斯（乔治·克鲁尼 George Clooney 饰）竞选团队的二号人物斯蒂芬（瑞恩·高斯林 Ryan Gosling 饰）年轻有为，此时遭到另一位候选人竞选团队的首脑汤姆·达菲（保罗·吉亚玛提 Paul Giamatti 饰）的挖角，但斯蒂芬对莫里斯忠心耿耿，并不为所动。另一方面，斯蒂芬深深为新来的实习生莫莉（埃文·蕾切尔·伍德 Evan Rachel Wood 饰）吸引，两人迅速打得火热。不料，泰晤士报的记者艾达（玛丽莎·托梅 Marisa Tomei 饰）得知了斯蒂芬与汤姆的会面，以此要挟斯蒂芬透露政选内幕。焦头烂额的斯蒂芬又在与莫莉的交往中发现了一个惊人的秘密……©豆瓣', '瑞恩·高斯林', '乔治·克鲁尼', 7, 28976, 'tt1124035', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1282063834.jpg', 0.4, 4.4, 48.1, 40.5, 6.6, '0.253738,-0.063918,-0.458117,0.615882,-0.049126,-0.159937,0.549738,0.154167,-0.517368,-0.360639,0.133262,0.715632,-0.634400,0.002136,0.558184,-0.178478,-0.389891,-0.860139,-0.029610,-0.302370,-0.087728,-0.825403,-0.275617,-0.246943,-0.034111,-0.211495,0.633854,-0.228742,-0.069122,0.441289,0.507600,0.458968,0.036814,0.236668,0.273690,-0.078406,0.728355,-0.352734,-0.418640,0.403725,0.008283,-0.005109,-0.333956,0.249991,0.279318,0.630833,0.349985,-0.195877,0.099142,-0.103359,0.263321,-0.004512,0.054614,0.062265,0.615711,0.041671,-0.000216,0.254306,0.047621,0.127462,0.083890,-0.153318,-0.577531,0.440411,-0.022720,0.405906,-0.172731,0.401489,-0.244406,0.032665,0.076043,-0.093405,-0.072321,0.496568,0.153443,-0.057552,-0.059895,0.165923,-0.390039,0.049270,0.293730,0.018894,-0.339240,0.134550,-0.076124,-0.489859,-0.015226,-0.119341,-0.335627,-0.212141,0.533282,0.078060,0.365432,0.330199,-0.505871,-0.108110,-0.294671,-0.340003,0.020760,-0.450902,0.109851,-0.982777,-0.316977,-0.277345,-0.131993,-0.022302,0.091264,-0.090860,0.800647,-0.648659,0.022767,0.306317,0.147109,-0.258678,0.672920,0.102701,0.289738,-0.446308,-0.291093,0.208336,0.272954,-0.082986,0.071635,0.335006,0.034653,-0.468106,-0.244768,0.125335', '3003137', '25723905', '26990