INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3089638', '塞尔玛', '剧情', '历史传记题材电影《塞尔玛》由阿娃·杜威内执导，蒂姆·罗斯、大卫·奥伊罗、小库珀·古丁、汤姆·威尔金森主演，影片聚焦美国民权斗士马丁·路德·金1965年组织的“由塞尔玛向蒙哥马利进军”行动。', '大卫·奥伊罗', '艾娃·德约列', 7.3, 7560, 'tt1020072', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2220218254.jpg', 0.8, 4.1, 37.9, 44.4, 12.8, '-0.616500,-0.233218,-0.290966,0.579886,0.576935,-0.746445,0.282955,0.207098,-0.335052,-0.638526,0.009124,0.731596,-0.408436,-0.260468,0.683586,0.063557,-0.783723,-0.513258,-0.293945,-0.041746,0.190056,-0.552265,-0.496444,-0.662532,-0.215178,-0.375292,0.314299,-0.083289,-0.489713,-0.122194,0.642252,0.390165,0.177536,-0.454154,0.998018,0.122031,0.358088,-0.684990,-0.707509,0.254587,0.035245,0.284897,-0.355705,-0.464524,0.524859,0.102971,0.375419,-0.232588,0.796679,-0.329619,0.069416,-0.128081,0.034949,-0.047088,-0.009464,0.092741,0.005641,0.190563,0.432423,-0.191170,-0.255928,-0.415408,-0.246189,0.469330,-0.258942,0.618474,-0.139216,-0.064325,-0.731273,0.556882,-0.048364,-0.435430,-0.386220,-0.024592,0.521622,-0.002327,0.321631,0.375292,0.045176,0.291317,-0.036833,0.466852,-0.217349,-0.274555,-0.362383,-0.515023,-0.256764,0.109934,-0.268178,0.273870,0.796735,-0.592376,0.492374,0.800298,-0.512302,-0.414197,-0.287455,-0.488317,-0.033384,0.177241,0.435401,-1.412975,0.191562,0.147885,0.457547,-0.488606,-0.059220,-0.106685,0.816501,-0.049138,0.348028,0.171622,0.212466,0.075155,0.649190,-0.190637,0.102835,-0.266108,0.183023,0.954192,0.024835,0.159819,0.131744,0.024224,0.117350,-0.643085,0.103287,0.328297', '26335580', '6517421', '34961898', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3089689', '灾难大电影', '喜剧', '男青年威尔（马特•兰特尔 Matt Lanter 饰）从一场诸多电影情节和明星串联而成的噩梦中惊醒，发现这天正是他梦中显示的世界末日——2008年8月29日。威尔不能确定与女友艾米（凡妮莎•米尼洛 Vanessa Minnillo 饰）的关系，后者愤而离去。为了弥补遗憾，已经25岁的威尔为自己举办甜蜜16岁的生日派对，这场疯狂派对变成了一场无尽恶搞电影的狂欢，所谓乐极生悲，狂欢中的人们突然发现城市已经陷入地动山摇陨石坠落的大灾难之中，混乱中威尔和艾米失散了，为了找回真爱，威尔偕同加尔文与女友、怀孕的朱妮踏上了前往博物馆解救艾米的旅程，一路上绿巨人、钢铁侠等英雄纷纷被灾难击溃，威尔一伙儿也连续击败欲望都市女郎、魔法奇缘王子等人，在这场无厘头电影中向博物馆前进。©豆瓣', '马特·兰特尔', '贾森·弗莱德伯格', 4.9, 6673, 'tt1213644', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2212628856.jpg', 20.4, 30.5, 35.6, 9.3, 4.1, '0.053098,-0.032297,-0.455462,-0.041094,0.292576,-0.130396,0.863756,-0.169885,-0.277057,-0.235495,0.456911,0.745184,-0.725704,-0.002065,0.768889,0.009874,-0.555635,-0.692551,0.021799,0.117084,0.056913,-0.313600,-0.265075,-0.103816,0.166943,-0.502944,0.589926,0.347039,-0.217795,0.788819,0.096357,0.252325,-0.121965,0.306155,0.484284,0.036659,0.101001,-0.029676,-0.316588,0.256602,-0.296254,-0.195301,-0.125764,0.108869,-0.164164,0.226844,0.627433,-0.384840,0.348800,-0.168317,0.177268,-0.304948,-0.214724,0.125473,-0.082794,-0.007521,0.529071,0.054665,0.111179,-0.223129,-0.019206,-0.309110,-0.308552,0.339174,-0.045574,0.145907,-0.227532,0.401855,-0.050890,0.004113,0.417635,-0.194559,0.161777,0.436764,0.550628,0.628225,-0.320163,-0.086193,-0.319764,0.237686,0.636860,0.057360,-0.223198,0.335652,0.146598,-0.428205,-0.116353,-0.052745,-0.493369,0.050709,0.485672,-0.030854,-0.116853,0.718350,-0.732277,-0.027125,-0.284131,-0.475510,0.042107,-0.240059,-0.164078,-0.791557,-0.110201,0.044481,-0.063969,-0.233874,-0.018786,-0.249982,0.321506,-0.719445,0.575064,0.445206,0.055885,-0.119588,0.633342,-0.109731,0.016760,-0.093644,0.081923,0.346944,-0.188607,0.341479,-0.061413,0.128008,0.005123,-0.176378,-0.491153,0.416543', '1292050', '26687241', '1308069', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3090455', '波西·杰克逊与神火之盗', '奇幻', '黑夜，天神宙斯召见海神波塞冬，称其子偷了闪电火，要挟他若不尽快找回，必将开战。现实中，波塞冬与人妻萨利之子波西杰克逊（罗根•勒曼 Logan Lerman 饰）是个大学生，17岁的他可以在水下呆7分钟，但对老师关于莎翁的提问不感兴趣。参观博物馆时，他遇到了摇着轮椅的人马老师（皮尔斯•布鲁斯南 Pierce Brosnan 饰）。而文学老师却变身成了复仇女神，向他逼问闪电火的下落。幸好人马教授和羊男朋友及时赶到，化险为夷。他们带波西来到营地，训练波西，他们找来了一个女战士安娜贝斯（亚历山德拉•达达里奥 Alexandra Daddario饰）与之比武。落败后，触水的波西被激活了潜能，成为奋勇无敌的战士，并开始踏上了追寻闪电火的英雄之旅。面对蛇女美杜莎等神怪的攻击，冥王冥后珀尔赛弗涅的刁难，他的自我救赎只剩下10天……©豆瓣', '罗根·勒曼', '克里斯·哥伦布', 6, 52870, 'tt0814255', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2211754176.jpg', 3.6, 19.3, 53.6, 18.3, 5.3, '0.262517,-0.088116,-0.395642,0.402327,0.113579,-0.319723,0.614558,0.249869,-0.161499,-0.240079,0.312659,0.613388,-0.078444,0.051026,0.399739,-0.032348,-0.281993,-0.675089,0.070762,-0.098110,-0.116180,-0.345259,-0.199028,0.049824,0.078351,-0.638091,0.407667,-0.079274,0.151718,0.456336,0.138100,0.133386,0.163747,0.276825,-0.193715,0.180047,-0.012210,-0.199571,0.025111,0.504445,0.007619,-0.057957,-0.139768,0.086886,-0.084352,0.187527,0.513157,-0.465300,0.326290,-0.269420,0.132016,-0.559258,0.103314,0.272611,0.198337,-0.143321,0.046139,0.170875,0.154739,0.062097,-0.028959,-0.217988,-0.694864,0.201621,-0.246143,0.179909,-0.572639,0.341196,-0.105642,0.088571,0.201271,-0.248205,-0.024160,0.103263,0.066499,0.197321,-0.285873,-0.293348,-0.481964,0.095772,0.477613,-0.223357,-0.163336,0.083982,0.250406,-0.321256,-0.075941,-0.058258,-0.336632,-0.015287,0.506610,0.267952,-0.046799,0.161092,-0.590454,-0.208952,-0.451474,-0.054888,-0.154242,-0.436066,-0.056888,-0.666864,0.062815,-0.080251,-0.142131,-0.030080,0.124811,0.018212,0.508710,-0.791359,0.231239,0.419009,0.386645,-0.343738,0.708170,-0.179733,-0.131256,-0.321894,0.108767,0.197506,0.281984,0.544905,0.203397,0.323581,0.177124,-0.182571,-0.338520,0.248979', '3044878', '1420088', '11810348', '1308842');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3091208', '樱桃小丸子', '动画', '正在上小学三年级的樱桃小丸子（Tarako 配音），因班长丸尾末夫（飞田展男 配音）提出了抽签换座位的要求，抽到了她不喜欢的调皮同学大野健一（山口胜平 配音）跟彬山聪（真山亚子 配音）同桌。而且和最好的同学小玉（渡辺菜生子 配音）分了桌。大野和彬山是一对好朋友，他们虽然总是抄袭作业欺负同学，可他们参加劳动时非常能干，学校有活动配合的也很默契。学校要开运动会，小丸子和上六年级的姐姐樱杏子(水谷优子 配音)都要参加，在运动会开始时爸爸樱宏志（屋良有作 配音）妈妈小林堇（一龙斋贞友 配音）也来给她们加油，小丸子参加的借物竟赛时多亏大野和杉山的帮助取得了第二名。男生骑马打仗比赛，因大野没发挥好以至最后输了比赛，大野和彬山这对最要好的朋友因此友谊出现了裂痕。赌气不说话的两人，转眼来到了平安夜的合唱比赛。一场大野的危机即将降临，这是否是二人关系的转捩点呢？©豆瓣', '鳕子', '芝山努', 9.1, 9002, 'tt2167725', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2380703550.jpg', 0.1, 0.4, 6.2, 28.9, 64.4, '0.292198,-0.423901,-0.290321,0.332032,0.038011,-0.449513,0.005895,0.408131,0.005955,0.036085,0.101014,0.556661,-0.390662,0.124313,0.153935,-0.210822,-0.239961,-0.707631,-0.001692,-0.070521,-0.356733,-0.364186,0.437165,0.208800,-0.038489,0.022283,0.456849,-0.371606,-0.032802,0.842051,0.225431,-0.070835,0.151966,0.253257,0.134057,0.142779,0.156982,0.302977,-0.104351,0.269321,-0.045385,0.052831,-0.259520,0.037060,0.678711,0.365301,0.650510,0.016070,-0.160382,-0.072712,0.141781,-0.213549,-0.051769,0.242619,0.409438,0.080208,0.434813,0.157252,0.013912,-0.111541,-0.295945,-0.286584,-0.338724,0.139955,0.130188,0.070157,-0.171972,0.779305,0.022013,-0.128276,0.361301,-0.030101,0.227442,0.556406,0.184927,0.160366,-0.253527,-0.013166,-0.190313,0.181336,0.768046,-0.050052,0.154386,0.332262,0.049975,-0.374832,0.050270,-0.131300,-0.256045,0.350327,-0.013734,-0.086081,-0.027040,-0.335824,-0.605818,-0.070988,0.283083,-0.024179,0.164645,-0.431426,0.023904,-0.630119,0.101628,-0.344452,-0.457631,0.008892,-0.060891,-0.287411,1.049388,-1.151692,-0.093644,0.433036,0.448862,0.050490,0.631851,0.331776,-0.147824,-0.328278,-0.042631,-0.511108,-0.264799,0.226001,0.326796,0.570128,0.127776,-0.222643,-0.476556,0.155806', '1826173', '3139191', '25922902', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3091572', '圣诞传说', '剧情', '四处洋溢着节日气氛的圣诞夜，一位作家接到了一个神秘的电话，在电话那头的不是别人，竟是世界上唯一的一位圣诞老人尼古拉斯（汉努·珀卡·卓克曼 Hannu-Pekka Björkman 饰），而我们的故事，讲述的正是这位传奇老人的奇幻人生。从小就不幸成为孤儿的尼古拉斯生活在位于芬兰的一座小岛之上，在那里，居民们轮流担负起了照顾尼古拉斯的责任，为了感谢收养他的善良的人们，每当即将离开一个家庭的时候，尼古拉斯便会献上自己亲手制作的小小礼物表达谢意。饥荒的爆发让居民们陷入了恐慌，无奈之下，他们将尼古拉斯送往了名为利萨齐（约翰·特托罗 John Turturro 饰）处做学徒工，也正是这段特殊的经历改变了尼古拉斯的一生。©豆瓣', '汉努-佩卡·约克曼', '卓哈·沃里诸基', 7.7, 6442, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1090354424.jpg', 0.4, 3.3, 29.6, 44.1, 22.6, '0.195390,0.037342,-0.423544,0.642291,-0.215919,-0.161603,0.656259,0.100795,-0.416308,-0.356617,0.336906,0.971734,0.050093,0.550284,0.580162,0.032200,-0.173948,-0.447939,-0.113591,-0.116754,-0.235084,-0.480888,-0.276942,-0.388224,-0.045536,-0.381368,0.437321,0.146300,-0.172424,0.414052,0.231630,0.558467,-0.099863,0.389684,-0.224300,0.053967,0.163429,0.025300,-0.321580,0.010600,-0.355649,-0.295491,-0.022574,0.241762,0.031314,0.254073,0.603538,-0.521978,-0.170191,-0.145945,0.469210,-0.220427,0.045377,0.056358,0.152108,0.110273,0.204883,0.167732,-0.390474,0.038751,0.156354,-0.354202,-0.848286,-0.086942,0.031820,0.115157,-0.691102,0.404639,0.136669,-0.235970,0.158126,-0.214649,0.418489,0.311584,0.068709,0.642080,-0.135790,0.175833,-0.175782,0.181543,0.739647,-0.088299,-0.223819,0.249933,-0.395856,-0.294477,0.023781,0.013508,-0.515872,0.043898,0.316211,-0.073356,-0.007134,0.195366,-0.667709,-0.211509,-0.214717,-0.475797,0.237457,-0.329990,-0.426632,-0.663723,-0.038979,-0.156888,-0.371816,-0.113666,0.107952,-0.075436,0.994647,-0.728842,0.400865,0.412685,-0.071866,-0.411148,0.637136,0.211859,0.259858,-0.187744,-0.023607,0.372355,0.118259,0.260979,0.050108,0.192955,-0.225547,0.015114,-0.351384,0.660531', '27602116', '1870681', '30162520', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3094580', '极限空间', '悬疑', '伽罗华（阿雷胡·苏拉斯 Alejo Sauras 饰）、奥莉薇娅（伊莲娜·巴雷斯特罗斯 Elena Ballesteros 饰）、帕斯卡（桑提·米兰 Santi Millán 饰）和希尔伯特（路易斯·霍马 Lluís Homar 饰）分别是各自学术行业里的佼佼者，某一日，一封神秘的邀请函和一道诡异的谜题将四人聚集到了同一个房间之中。然而，被困住的四人很快就发现，他们陷入了某人精心设计的“游戏”之中，如果不能正确回答一道又一道的谜题，他们终将被不断逼近的墙壁压成肉泥。在紧张的解题过程中，四人还必须相互试探彼此的真实身份以及找到其中的关联，紧张的氛围之中，高智商的四人组最终能够逃出生天吗？之后等待着他们的又会是什么呢？©豆瓣', '阿雷胡·苏拉斯', '路易斯·佩德拉希塔', 6.6, 22444, 'tt1016301', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2444748574.jpg', 1.6, 9.9, 50.4, 30.6, 7.5, '0.583217,0.302788,-0.701496,0.742537,0.169548,-0.107097,0.714455,0.066281,-0.570536,-0.152825,0.071935,0.562352,-0.468553,0.292076,0.245931,0.051696,-0.194320,-0.949778,-0.198975,-0.384844,-0.713945,-0.634857,-0.380520,-0.211321,-0.171726,0.093876,0.267221,0.398607,-0.030336,0.259300,0.252643,0.267090,-0.444230,0.489193,-0.016417,0.059532,0.217609,-0.215942,-0.089527,0.156883,0.133383,-0.235781,-0.033335,0.219226,-0.056896,0.310698,0.696833,-0.410207,0.214419,0.309858,0.064247,-0.182142,-0.134671,0.300247,0.189717,-0.019691,0.378737,0.058322,-0.222917,0.263182,0.065946,0.004928,-0.837364,-0.112357,0.075829,0.376033,-0.373669,0.332699,0.219616,-0.285203,0.065122,-0.330471,0.214185,0.299227,0.559420,0.297718,-0.116395,-0.205457,-0.455117,-0.184843,0.332416,-0.032084,-0.371006,-0.013361,-0.100816,-0.414991,-0.212534,0.045775,-0.208044,-0.206888,0.730600,0.487430,0.033840,0.181303,-0.718852,-0.019340,-0.219433,-0.178329,-0.322308,-0.454655,-0.046992,-0.442179,-0.100326,-0.240853,-0.199439,0.456695,-0.107881,-0.049606,0.538868,-0.562100,0.224889,0.148642,0.053963,-0.012610,0.396891,-0.057955,0.298758,-0.094224,-0.138627,0.014101,0.292846,0.190680,0.298248,0.679281,0.028959,0.035257,-0.546944,0.456715', '1805685', '1310176', '1307146', '34429100');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3094909', '乌云背后的幸福线', '剧情', '本身生性开朗乐观的中学教师帕特（布莱德利·库珀 Bradley Cooper 饰）回家撞见老婆出轨后因精神创伤被父母送进医院进行精神治疗。出院后帕特回到父母家与父母同住，在父亲（罗伯特·德尼罗 Robert De Niro 饰）与母亲（杰基·韦佛 Jacki Weaver 饰）的过度关怀下不免觉得压抑。一次聚会上帕特遇到了刚刚失去丈夫和工作的年轻女子蒂凡妮（詹妮弗·劳伦斯 Jennifer Lawrence 饰）。浑身是刺的蒂凡妮与帕特处处针锋相对，令帕特一开始唯恐避之不及。但随着两人接触的深入，帕特渐渐发现了蒂凡妮的动人之处，蒂凡妮也发现了帕特身上难以磨灭的乐观精神。蒂凡妮要求帕特与她共同练舞参加比赛，两人的关系开始向积极的方向改善。在舞蹈比赛的赛场，帕特终于找到了一生的所爱，而他与蒂凡妮的生活也拨开乌云重见阳光。本片根据Matthew Quick的同名小说改编。自2012年在多伦多国际电影节首映后获得各项好评，其后得到包括四项金球奖提名，三项BAFTA提名，五项独立精神奖提名，八项奥斯卡提名等多项电影节与电影奖项提名。其中詹妮弗·劳伦斯获得第七十届金球奖最佳女主角奖，第八十五届奥斯卡最佳女主角奖。', '布莱德利·库珀', '大卫·O·拉塞尔', 7.7, 174761, 'tt1045658', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1755867083.jpg', 0.4, 2.3, 28.1, 48.5, 20.8, '-0.055882,-0.158464,-0.660313,0.504567,0.126721,-0.466964,0.527658,0.179403,-0.456555,-0.129232,0.029676,0.972075,-0.570528,0.299651,0.621166,-0.262267,-0.451029,-0.734797,-0.172075,-0.113911,-0.132914,-0.486202,-0.212908,0.219775,-0.026704,-0.757793,0.697770,-0.125113,-0.028173,0.736065,0.634803,0.203196,0.021391,0.256034,0.145425,0.029377,0.095996,0.053742,-0.424966,0.503921,0.302981,-0.081366,-0.415341,0.037526,0.311889,0.352423,0.595497,-0.190025,0.012037,-0.117397,0.728974,-0.142433,0.076789,0.193787,0.135858,0.025174,0.422310,0.345596,-0.108068,0.214416,0.123820,-0.212699,-0.526762,0.163873,0.146716,0.177014,-0.406680,0.132399,-0.158994,0.073100,-0.055480,-0.329807,0.074784,0.300962,0.083482,0.219469,-0.155898,-0.060680,-0.086464,0.238709,0.592089,-0.002151,-0.332039,0.377672,-0.181381,-0.393727,0.053288,-0.167749,-0.418421,0.080320,0.511677,0.328755,0.309668,0.212484,-0.336108,-0.078823,-0.185229,-0.346335,0.135048,-0.178194,0.172522,-0.739142,-0.249417,-0.236884,-0.336084,-0.093105,-0.107667,-0.369479,0.463037,-0.766872,0.273676,0.200167,0.161240,-0.325037,0.629575,0.002789,0.229138,-0.083756,0.096493,0.361246,-0.089918,0.067425,-0.073343,0.364326,-0.199217,-0.304564,-0.464607,0.371995', '1780122', '1829654', '34795703', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3095189', '恶魔的艺术3：鬼影随行', '恐怖', '近年來，泰國恐怖片在台灣逐漸受到矚目，之前的《鬼影》、《邪降：惡魔的藝術》在台上映時就廣受好評，引發網友的熱烈討論、口碑推薦，尤其《邪降：惡魔的藝術》當初上映時更曾發生觀眾驚嚇到奪門而出的事件。《邪降3：鬼影隨行》正是因應《邪降：惡魔的藝術》在全球的好口碑而開拍，不僅由原班人馬再度通力合作，導演也保證這次的內容絕對更加驚悚可怖，舉凡剪舌、別針穿眼、電鋸鋸頭等種種意想不到的駭人場景都將一一呈現。這次的故事回到《邪降：惡魔的藝術》發生之前，對人物的轉折際遇將做出更完整的交代。潘老師是個充滿魅力的鄉下老師，她的美貌讓許多男人藉由各種妖術與降頭的力量，來贏得其芳心。為了斬斷這些無窮盡的威脅，潘老師不得不殺了對她下降頭的巫醫，但她也因此落入三眼神的掌控之中。另一方面，巫醫的朋友帝特，為了征服三眼神，決定介入這場風波…。', 'Napakapapa Nakaprasit', 'Pasith Buranajan', 6.9, 8839, 'tt1424066', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2538292133.jpg', 1.2, 7.8, 49.1, 30.5, 11.5, '0.112477,-0.123838,-0.774503,0.862432,0.030522,-0.087399,0.784676,0.298334,-0.448397,-0.032383,0.465085,0.528226,-0.393121,0.105928,0.383199,-0.161853,-0.057687,-0.795379,-0.219299,-0.106108,-0.228111,-0.223577,-0.529033,0.020749,-0.117954,-0.446284,0.671897,0.268657,-0.569829,0.018324,0.281505,0.053238,0.164834,0.251642,-0.296994,0.016943,-0.571767,0.005957,-0.244023,0.322526,0.208556,-0.665861,-0.235379,0.275412,-0.273319,0.383712,0.750584,-0.321755,-0.264461,0.134269,0.643523,-0.438116,-0.211643,-0.040342,0.329142,0.070664,0.152926,0.187427,-0.234537,0.256520,-0.014791,-0.003975,-1.033790,0.343424,0.221245,0.301348,-0.651058,0.468513,-0.001320,0.068357,-0.012951,-0.401635,-0.039180,0.053004,0.015224,0.400435,-0.383215,0.209708,-0.523083,-0.026776,0.467253,0.183725,-0.260242,0.393384,0.115259,-0.679099,-0.379399,-0.361105,-0.084113,0.065560,0.554834,0.254396,-0.043538,0.458564,-0.760167,-0.173708,-0.158798,-0.395985,-0.105636,-0.279574,0.028449,-0.949689,-0.393394,-0.550121,-0.245222,0.106978,0.414834,-0.320805,0.844401,-0.846074,0.127591,0.325632,0.169526,-0.543022,0.465573,0.179226,0.117100,0.208201,-0.363536,0.083422,0.040426,0.359985,0.049428,0.358792,-0.150173,-0.399911,-0.512614,0.638978', '3318306', '1793491', '26577354', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3095514', '阴风阵阵', '惊悚', '1977年，德国正值于冷战时期。少女派翠西亚欲参与革命而离开柏林当地知名的顶尖舞蹈学校─马可斯舞蹈学院，于离开柏林前探望了心理医生约瑟夫。约瑟夫对其所言的舞团所发生之事产生疑惑。也使其回想起与他逝去的妻子的过往。不久后派翠西亚便失踪了。另一位来自美国的少女苏西前往柏林就读马可斯舞蹈学院，艺术总监白夫人对她的表现非常青睐，便想她取替派翠西亚培养成下一个明日之星，而派翠西亚的好友莎拉及欧嘉也告诉了苏西于舞团所发生的事。自派翠西亚失踪及欧嘉离奇死亡后，苏西的到来也使灵异现象接二连三的发生，而随着苏西一步步取代舞团首席，苏西也变得越来越怪异。莎拉也渐渐发现学校深处的腥风血雨。而约瑟夫也将慢慢揭开这所由白夫人领导的学院背后的黑暗历史。而发生的一切也记录了柏林在历史中被遗忘的一面。', '达科塔·约翰逊', '卢卡·瓜达尼诺', 6.8, 32822, 'tt1034415', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2532759044.jpg', 3.4, 11.5, 40.5, 32.1, 12.5, '0.195916,-0.110393,-0.661378,0.504733,0.238004,-0.300146,0.770103,-0.035511,-0.501845,-0.363705,0.016976,0.907335,-0.278574,0.299678,0.811246,-0.018766,-0.226587,-0.807242,0.024816,-0.414988,-0.078721,-0.374355,-0.236728,-0.161965,-0.180427,-0.429544,0.580274,0.078965,-0.174061,0.529275,0.257022,0.472394,-0.250561,0.515070,0.174722,-0.017284,0.221343,0.288966,-0.289097,-0.026323,0.310653,-0.517176,-0.185490,0.013350,-0.120225,0.178293,0.454411,-0.255610,-0.154356,-0.340065,0.448197,-0.320301,0.061450,0.136543,0.568772,0.325745,-0.079831,0.364234,-0.313603,-0.029077,-0.066774,0.070915,-0.330000,0.254381,0.105561,0.326768,-0.403413,0.253367,0.038826,-0.239997,0.119322,-0.431987,0.394014,0.383447,0.176321,0.116233,-0.188976,-0.044523,-0.124262,0.091801,0.595934,-0.002210,-0.426769,0.206111,-0.129736,-0.448555,0.188692,-0.088583,-0.398671,0.259362,0.100110,0.143164,0.010316,0.501999,-0.379803,-0.247158,-0.445104,-0.470240,-0.164479,-0.312915,-0.014034,-0.661982,-0.335744,-0.238841,-0.218465,-0.256157,0.221866,-0.146365,0.521263,-0.805179,0.454137,0.294445,0.205737,-0.542204,0.286134,-0.126408,0.453166,-0.050127,-0.113173,0.465141,-0.037621,0.477628,-0.311175,0.371269,0.032560,-0.318906,-0.245687,0.271795', '1916995', '1303333', '1309162', '30137576');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3096161', '摇滚夏令营', '喜剧', '热爱音乐的青春少女米琪·桃瑞斯（黛米·洛瓦托 Demi Lovato 饰）希望参加一个摇滚夏令营，但是昂贵的费用让她望而却步。幸运的是，她的母亲科妮（玛丽娅·加诺斯·贝瑞拉 Maria Canals Barrera 饰）所经营的餐厅承包了夏令营的餐饮任务，于是米琪作为随行人员来到这个她梦寐以求的营地。这里云集了无数怀有音乐梦想的年轻人，他们努力学习，尽情歌舞，享受快乐的夏日时光。与此同时，当红组合灵犀三人组的灵魂人物辛恩·格雷（乔·乔纳斯 Joe Jonas 饰）机缘巧合来到夏令营。劲歌热舞、友情梦想，此时此刻全部汇聚于此，对米琪来说这注定是一个难忘的夏天……本片是迪斯尼频道制作拍摄的原创电影。©豆瓣', 'Alyson Stoner', '马修·戴蒙德', 6.5, 15259, 'tt1055366', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1161405249.jpg', 2.6, 11.9, 51.6, 25.1, 8.8, '0.175191,-0.019185,-0.551464,0.493382,0.060974,-0.267179,0.614644,0.296767,-0.291258,-0.166572,0.216077,0.661721,-0.130172,0.471304,0.301137,-0.006386,-0.357546,-0.530549,-0.021922,-0.063222,0.052639,-0.160254,-0.129545,-0.179369,-0.086751,-0.147815,0.600471,0.146377,-0.041043,0.549507,0.491649,0.327673,0.017533,0.036225,-0.055805,-0.177690,0.478390,-0.015752,-0.298423,0.199241,-0.547050,-0.051318,0.010392,0.131432,0.213615,-0.025491,0.692533,-0.060764,0.072298,0.029394,0.521363,-0.462720,-0.048601,-0.150455,-0.144037,0.143312,0.232734,-0.142247,-0.148282,0.061644,0.089633,-0.507767,-1.021764,-0.094058,0.291988,-0.032979,-0.307576,0.512080,-0.014717,-0.141715,0.068485,-0.217329,0.124801,0.137844,0.321132,0.255393,0.122355,0.188649,-0.270855,0.595427,0.727728,-0.143148,-0.307786,0.457099,-0.631894,-0.555869,-0.075653,-0.045083,-0.460092,-0.017788,0.099716,0.075172,0.303298,-0.000182,-0.660576,-0.009768,0.043611,-0.306145,0.097054,-0.325297,-0.184659,-0.966995,-0.158491,-0.296391,-0.243603,-0.241982,0.093281,-0.324749,1.007069,-0.698188,0.221904,0.575604,0.019473,-0.244221,0.876674,-0.095310,0.205427,0.051974,-0.115376,0.472050,-0.199243,-0.009776,-0.181096,0.264990,0.088118,0.012454,-0.595883,0.601927', '3318306', '27602116', '2027945', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3097044', '我唾弃你的坟墓', '惊悚', '为全身心投入创作，美丽迷人的作家珍妮弗（莎拉·巴特勒 Sarah Butler 饰）驱车来到一个偏僻乡间撰写小说。她的绰约身子在当地俨然一道靓丽乃至刺眼的风景，自然吸引了许多人的注意和妄念。她闲适恬淡的心情并未持续多久，似乎总有无数双眼睛在背后紧紧注视着她。某晚，与珍妮弗有过一面之缘的加油站工人乔尼（杰夫·布兰森 Jeff Branson 饰）带领伙伴们闯入她的房间，虽然她奋力反抗，但在这片法外之地，她仍无法逃脱被侮辱的命运，更遭到无数的虐待。这些禽兽般的男人没有想到，他们的恶行致令珍妮弗化身为残酷无情的复仇女神……本片翻拍自1978年的同名经典恐怖片。©豆瓣', '莎拉·巴特勒', '史蒂文·R·蒙若尔', 6.6, 47288, 'tt1242432', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p546563942.jpg', 1.9, 11, 51.2, 26.3, 9.5, '0.348578,0.087277,-0.741939,0.604572,-0.051518,0.070334,1.072579,0.078375,-0.266103,-0.233180,0.459374,0.647351,-0.396219,0.093419,0.161304,-0.067100,-0.122886,-0.666188,-0.182019,0.057790,0.080266,-0.141631,-0.287755,-0.111317,-0.109149,-0.167612,0.619882,0.123077,-0.122204,0.516092,0.099975,0.154700,-0.153324,0.467130,-0.252312,-0.050793,-0.007988,-0.053105,0.095612,0.130974,-0.139910,-0.544792,-0.370708,0.127322,-0.264758,0.122354,0.808204,-0.314874,-0.382044,0.061943,0.385874,-0.174931,0.162562,0.312743,0.145530,-0.003457,0.184717,0.021587,-0.062123,0.007966,0.117578,-0.085372,-0.676404,0.033274,0.060965,0.333858,-0.401056,0.334219,-0.016568,-0.112105,-0.004101,-0.263204,0.029659,-0.038986,0.102598,0.336209,-0.057981,0.230906,-0.335042,0.312252,0.509080,0.211156,-0.297213,0.281413,-0.408386,-0.259159,-0.054050,-0.035332,-0.710486,-0.171956,0.384565,0.015390,-0.178416,0.408014,-0.609597,0.174574,-0.108886,-0.197920,-0.217345,-0.453971,-0.201628,-0.683068,-0.180035,-0.352341,-0.185907,0.317552,-0.024767,-0.183165,0.720804,-0.692689,0.406582,0.476182,0.255395,-0.302416,0.700037,0.053939,-0.044870,0.211498,-0.350351,0.746739,0.094952,0.300917,0.133326,0.418717,-0.194224,0.154638,-0.400130,0.538705', '21619567', '1296992', '1467779', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3097352', '剃头匠', '剧情', '敬大爷如今是个九十三岁高龄的耄耋老人，他有八十多年的剃头经历，至今仍住在北京胡同的大杂院里，过着北京城内最底层最普通也是最平淡的生活，他经常给老主顾们上门剃头、聊天，回家后拨弄着自己那座每天慢五分钟的老座钟，他希望每个人（也包括他自己）干干净净的来到人世，也希望人们干干净净利利索索的离去……电影《剃头匠》以纪录和讲述的形式描述了这样一个老人恬淡而平凡的生活。©豆瓣', '靖奎', '哈斯朝鲁', 9.2, 18264, 'tt1160619', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2190291916.jpg', 0.2, 0.3, 4.6, 26.8, 68.1, '0.201149,0.005697,-0.621872,0.517032,-0.353172,-0.241958,0.894734,0.014776,-0.628973,-0.453748,0.079800,0.792916,0.120729,0.700851,0.061740,-0.118397,-0.254180,-0.266568,-0.162103,-0.213345,-0.271084,-0.064866,-0.051355,-0.017036,-0.314751,0.016234,0.124038,0.046370,0.139861,0.477057,0.139633,-0.123753,0.133386,0.284525,-0.685218,0.196012,-0.270268,0.031479,-0.120249,0.010425,-0.053700,-0.143080,-0.154394,-0.045861,-0.027716,0.342426,0.650659,-0.223431,-0.394488,0.096799,0.300432,-0.097209,-0.345440,0.391937,0.375445,0.023206,0.274187,0.269923,-0.120410,0.174520,-0.294827,-0.081353,-0.708495,-0.035869,-0.015506,0.267431,-0.852289,0.617177,0.236104,-0.067605,-0.118302,-0.449226,0.311243,0.172539,-0.036447,0.430564,-0.190205,-0.129255,-0.670231,0.635633,0.612255,0.101234,-0.436070,0.432802,-0.349691,-0.167818,0.148156,-0.391283,-0.658822,-0.050630,-0.159005,-0.124850,-0.258048,0.134642,-0.503856,0.343700,-0.024810,-0.413161,0.204894,-0.306231,-0.284411,-0.706068,-0.055988,-0.749822,-0.511454,-0.026099,-0.058058,-0.357526,0.781171,-0.433515,0.306579,0.372601,0.150422,-0.271966,0.998575,-0.034199,0.295213,-0.118390,-0.058612,0.242760,0.103240,0.475391,0.089216,0.522865,-0.272417,-0.096635,-0.492873,0.547868', '3055049', '1783772', '30189817', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3097525', '怪形前传', '科幻', '时为1982年，一支隶属挪威的三人南极科考队在冰原中行进，意外发现一艘一百万年前的奇怪船只，并且在附近找到了冻于严冰之中的神秘生物。才貌双全的美国古生物学家凯特·洛伊德（玛丽·伊丽莎白·文斯蒂德 Mary Elizabeth Winstead 饰）在桑德尔·哈沃森博士（Ulrich Thomsen 饰）的邀请下，随同一众科研工作者前往南极。经过认真研究，他们发现这是地球上从未有过的生物。正当科学家们为了这个伟大的发现载歌载舞庆祝之时，神秘生物悄悄解冻，继而向人类展开凶残的袭击。经过一番惨烈的搏斗，怪物最终葬身火海。但是厄运并未就此结束，经过对怪物细胞的观测，凯特隐隐感到一场灾难正向全人类袭来……©豆瓣', '玛丽·伊丽莎白·温斯特德', '小马泰斯·范海宁根', 7, 25831, 'tt0905372', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1322394563.jpg', 0.8, 6.4, 47.5, 34.4, 10.8, '0.219728,-0.038397,-0.872593,0.500532,0.331446,-0.021035,0.832521,-0.579369,-0.629065,-0.393152,0.345872,0.487623,-0.337650,0.074734,0.504676,0.029115,-0.361029,-0.361200,-0.271625,-0.122083,-0.443159,-0.259390,-0.686431,-0.230275,0.096856,-0.465614,0.390415,0.243289,-0.104336,0.825572,-0.086419,0.656667,-0.438153,0.498000,0.019592,-0.146011,0.311323,-0.040691,-0.314294,0.202409,-0.066468,-0.127678,-0.205149,0.182220,-0.240059,0.332767,0.788258,-0.556223,-0.101381,-0.341543,0.207517,-0.177351,0.149313,0.152855,0.535372,0.279797,-0.161022,0.056631,0.200016,0.140973,-0.133855,-0.072184,-0.469584,0.022566,-0.003587,0.405709,-0.308790,0.234828,0.109830,0.075982,0.056266,-0.313745,0.224476,0.454030,0.362991,0.552907,0.006055,0.309018,-0.144825,-0.186548,0.687915,0.045769,-0.285837,0.142167,-0.143184,-0.661944,0.114545,0.047996,-0.241095,-0.083451,0.124506,0.224876,0.025267,0.373107,-1.105210,0.146138,-0.319989,-0.374637,0.019393,0.130064,-0.261722,-0.979627,0.138717,-0.188130,-0.262164,0.261689,-0.182251,-0.390840,0.462934,-0.579894,0.326840,0.598423,0.148108,-0.323354,0.546324,-0.313124,-0.068356,-0.106697,-0.219753,0.286279,0.177374,0.424356,-0.114625,0.260642,0.063282,-0.326730,-0.313489,0.144964', '2159244', '1309056', '1306983', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3097572', '双子杀手', '剧情', '效力于美国国防情报局的特工亨利·布罗根（威尔·史密斯 Will Smith 饰）是一名顶尖狙击手，在他的职业生涯中，曾奉命扫除许多威胁国家安全的恐怖分子。执行任务时的他下手果断，毫不迟疑。可是最后一次任务险些失手，却让他产生了动摇，进而提出解甲归田。怎奈放下屠刀的他，偶然听到了一个有关国家机密的大事，随即便招来杀人之祸。在躲过政府第一次围剿之后，他偕同因监视自己而意外被卷入其中的女特工丹妮（玛丽·伊丽莎白·温斯特德 Mary Elizabeth Winstead 饰）展开逃亡，投奔昔日战友巴伦（本尼迪克特·王 Benedict Wong 饰）。未曾想新的杀手阴魂不散，尾随而至。更令亨利惊讶的是，追杀他的竟是年轻了25岁的另一个自己……©豆瓣', '威尔·史密斯', '李安', 6.8, 325054, 'tt1025100', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2554402180.jpg', 0.8, 7.5, 48.9, 35, 7.7, '0.150663,0.071197,-0.719095,0.708422,-0.207184,-0.411277,0.679745,-0.019006,-0.597820,-0.336844,0.477058,0.800762,0.015661,-0.174749,0.335743,-0.013157,-0.004934,-0.598594,-0.052633,-0.145177,-0.444793,-0.291192,-0.483733,-0.486695,-0.144623,-0.232639,0.472242,0.143933,-0.402818,0.491854,0.401832,0.697178,-0.013141,0.651484,-0.080698,-0.026821,0.380538,-0.186638,0.024432,0.144855,-0.109746,-0.522020,-0.279647,0.382452,-0.193774,0.717763,0.390107,-0.282861,-0.108169,-0.262887,0.254397,-0.581591,0.071627,-0.012787,0.332782,-0.040323,0.036904,0.215179,-0.115364,-0.092209,0.069151,-0.007189,-0.764709,0.020785,-0.031008,0.254324,-0.577780,0.223635,-0.464568,0.231078,0.104165,-0.123681,0.049625,0.532844,0.136443,-0.012714,-0.104562,0.007378,-0.323980,0.310869,0.693748,-0.128854,-0.277046,-0.141058,-0.077040,-0.385119,0.214801,-0.196871,-0.232230,-0.011248,0.502821,-0.093473,-0.007166,0.277397,-0.407139,-0.300123,-0.556599,0.045246,-0.163572,-0.215680,-0.085917,-0.521769,0.156963,-0.102709,-0.520583,0.172166,-0.069074,-0.000631,0.495278,-0.776655,0.230780,0.699940,0.050339,-0.643620,0.426444,0.170789,0.174064,-0.182375,-0.038601,0.282883,0.270084,0.317953,0.152335,0.312449,0.046225,-0.389107,-0.150971,0.309078', '1295733', '1294941', '1301022', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3099221', '活死人军团', '动作', '影片的故事发生在丧尸危机爆发的拉斯维加斯，在此期间，一名男子集结一群雇佣兵进行最终的赌博，冒险进入隔离区，以进行有史以来最大的劫案。', '戴夫·巴蒂斯塔', '扎克·施奈德', 5.2, 60035, 'tt0993840', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2643872011.jpg', 8.5, 34.9, 46, 8.7, 1.9, '0.179523,-0.117698,-0.635833,0.294571,0.402680,0.151938,1.131517,-0.234487,-0.132084,-0.215908,1.329876,0.680219,-0.254115,-0.139180,0.621209,-0.815736,0.051614,-0.452160,-0.102611,0.199340,-0.174717,-0.006967,-0.105344,-0.105447,0.039279,-0.237952,1.066737,0.427951,-0.976797,-0.043561,0.239021,0.412765,-0.561561,0.340582,0.192171,-0.634425,0.421267,-0.138461,-0.439559,0.649810,-0.251195,-0.460838,-0.223782,-0.226553,-0.023317,0.045328,1.202043,-0.618848,-0.265226,0.011898,0.700877,-0.547515,-0.557671,-0.073706,0.496180,0.316275,-0.296183,0.048003,0.211349,-0.010753,-0.484562,-0.321025,-1.057191,-0.387677,-0.132222,0.269466,-0.477846,0.182577,0.262105,0.248682,0.492754,0.043947,-0.162759,0.954981,0.332377,-0.149161,-0.280242,0.301694,-0.581855,0.096610,1.176902,-0.428658,-0.665726,-0.149984,-0.059100,-0.823127,-0.208007,-0.236816,-0.362764,0.157072,0.200653,-0.363209,-0.314428,0.407337,-0.908771,0.142811,-0.228987,-0.892681,0.058149,0.352509,-0.433544,-1.438201,-0.234118,0.061373,-0.090518,0.169180,0.073685,-0.174111,0.555781,-0.758351,0.099123,0.842727,0.002662,-0.698216,0.344907,-0.063114,0.466824,-0.433363,-0.408536,0.618031,0.107107,0.651701,-0.134576,0.224065,-0.304669,-0.168609,-0.162352,0.068609', '2369613', '1306809', '2159244', '4014397');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3101548', '天才眼镜狗', '喜剧', '皮博迪（泰·布利尔 Ty Burrell 配音）是一条与众不同的小狗，它拥有绝伦无比的高智商，因此注定拥有迥异于同类的“狗生”。它持有哈佛学位，成功开发了新能源，圆满解决地缘政治，还创立了属于自己的公司。皮博迪偶然机缘下收养了和它有着类似经历的人类小孤儿舍曼（麦克斯·查尔斯 Max Charles 配音），它如同慈父一般悉心教育着他的儿子，并利用自己开发的时光机带舍曼回到未来每一个重要时刻，亲身经历书本上枯燥的历史事件。转眼舍曼到了上学的年龄，他丰富的历史知识得到老师表扬，却也引来高傲的小姑娘佩妮·彼得森（阿芮尔·温特 Ariel Winter 配音）的嫉妒和欺负。舍曼和佩妮的冲突使皮博迪陷入前所未有的艰难境地，为了保住对舍曼的抚养权，它想尽办法取悦佩妮的父母和相关机构负责人。而就在那个晚上，舍曼和佩妮竟偷偷乘上时光机，进行了一次惊心动魄的时空大冒险……', '泰·布利尔', '罗伯·明可夫', 7.6, 88281, 'tt0864835', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2174250040.jpg', 0.5, 2.9, 31.7, 46.3, 18.7, '0.085522,0.086052,-0.619098,0.642451,-0.213056,-0.295110,0.543145,-0.027845,-0.432543,-0.207446,0.083326,0.832808,-0.113982,0.361972,0.053378,-0.059962,-0.325179,-0.464482,0.253532,-0.014635,-0.171647,-0.409586,-0.422446,-0.090908,-0.034589,-0.358826,0.601007,-0.088949,-0.480128,0.255263,0.068930,0.266908,-0.074609,0.293376,-0.311251,-0.042118,-0.051846,0.200901,-0.251502,-0.005461,0.176483,0.084187,-0.074562,0.055543,-0.051386,0.147112,0.563852,-0.375893,-0.199576,-0.321584,0.599400,-0.249511,-0.208790,0.042865,0.193820,0.118804,0.123941,0.160501,-0.126112,0.024436,0.234628,-0.354210,-0.950779,-0.241012,0.055324,0.124597,-0.305329,0.472966,0.046515,-0.013108,0.118909,-0.299909,-0.057279,0.261589,0.278232,0.426424,-0.091621,0.034607,-0.357159,0.224085,0.369246,-0.198676,-0.496408,0.352256,-0.526661,-0.476664,0.099776,-0.658862,-0.428030,0.135178,0.344760,0.016212,-0.286085,0.457537,-0.594870,0.010827,-0.245643,-0.080826,-0.009826,-0.475750,-0.002013,-0.648763,-0.072171,-0.545204,-0.417218,-0.174382,0.063174,-0.502285,0.816845,-0.712610,0.212005,0.549677,0.237961,-0.355292,0.588777,-0.065416,0.278764,-0.377128,-0.131991,0.303158,0.038928,0.236541,-0.013988,0.213997,0.294876,0.096803,-0.375479,0.647372', '27602116',