INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3101985', '灰姑娘之舞动奇迹', '喜剧', '万人迷乔伊·帕克在完成第四次世界巡回演唱会之后重返家乡比佛利山，他决定要回到学校读完高中，而且他将和唱片公司发起一场大规模的舞蹈比赛，这一消息让比佛利山的姑娘们兴奋不已。在一次化妆舞会上，一个舞技超众的神秘女孩凭借自己的舞蹈天赋令乔伊“一舞倾心”，可是她却在午夜12点的时候勿忙离去，只留下了一个音乐播放器。在乔伊设法寻找女孩的过程中，无数的冒名者趋之若鹜，而当真正的主角玛瑞（赛琳娜·戈麦斯 Selena Gomez 饰）鼓起勇气走到乔伊面前时却被乔伊当成了冒名前来的女生……本片女一号赛琳娜·戈麦斯生于1992年，10岁时被迪斯尼全球才艺计划发掘。©豆瓣', '赛琳娜·戈麦斯', 'Damon Santostefano', 6.7, 21461, 'tt1071358', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1161407716.jpg', 1.7, 10, 52.2, 26.4, 9.7, '0.037729,0.258906,-0.532466,0.643809,-0.066446,-0.372782,0.414373,-0.057720,-0.460052,-0.175821,0.176287,1.039931,-0.438070,0.403165,0.344576,-0.052120,-0.248211,-0.727411,-0.028651,-0.428519,-0.374647,-0.154188,-0.093396,0.108016,-0.215343,-0.439639,0.549190,-0.135717,-0.218162,0.615035,0.256231,-0.014906,0.045188,0.384713,-0.075428,-0.156857,0.443152,0.058987,-0.257052,0.620719,-0.012851,-0.249674,-0.577198,-0.014257,0.082754,0.002602,0.772683,-0.193574,0.040218,-0.283008,0.374973,-0.212652,0.017766,0.046576,0.289755,-0.076047,0.201302,0.091539,-0.152583,0.144326,0.133182,-0.489901,-0.584596,0.117454,0.273719,-0.024854,-0.579193,0.295592,-0.333681,0.197269,0.050884,-0.444180,-0.075626,0.220624,0.409535,0.224028,-0.158418,-0.012603,-0.435788,0.270455,0.633333,0.257661,-0.214572,0.395819,0.150430,-0.504865,-0.095831,-0.098802,-0.510701,0.311454,0.448280,0.021839,-0.149971,0.066973,-0.551999,-0.249301,-0.289589,-0.409123,-0.060827,-0.411600,-0.345897,-0.830107,-0.067841,-0.020524,-0.147441,-0.071065,0.022052,-0.299788,0.979755,-0.916330,0.327092,0.746184,0.048557,-0.175177,0.595036,0.001612,0.297137,-0.123626,-0.222542,0.111838,-0.031682,0.270243,-0.126482,0.454598,-0.281576,-0.343593,-0.526397,0.641898', '3811356', '1870681', '30162520', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3101989', '公主保护计划', '剧情', '本片由美国当红少女明星主演的最新迪斯尼原创电视电影。卡特（赛琳娜·戈麦斯 Selena Gomez 饰）的爸爸梅森是一名“公主保护计划 ”的特工少将。收到消息要保护一个名为克斯塔鲁那的小国的公主罗萨琳娜（黛米·洛瓦托 Demi Lovato 饰）。邪恶的凯恩将军在她的加冕仪式排练时，占领了克斯塔鲁那。梅森受公主的母亲索菲亚所托，把公主带走，而索菲亚自己却留下做人质。在经过公主保护计划指挥中心的改造后，梅森把公主带到了美国的一个乡下小镇，改名为罗西，并以卡特表姐的身份在那里生活。这一次，公主要去学会成为一个正常的美国青少年，等待合适的机会重返自己的国家打败夺权者继承自己的王位。在罗萨琳娜和卡特之间将会上演什么样的故事？罗萨琳娜最后是否能够救出母亲，夺回继承权？©豆瓣', '赛琳娜·戈麦斯', 'Allison Liddi', 6.4, 13240, 'tt1196339', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2204956524.jpg', 2, 12.3, 57.2, 21.6, 7, '-0.028304,0.290480,-0.340519,0.744732,0.022041,-0.422736,0.587329,0.266789,-0.326432,-0.244333,0.461566,0.649216,0.156766,-0.069758,0.564720,0.282369,-0.633399,-0.462714,0.030837,-0.066627,-0.170441,-0.417051,-0.274645,-0.372739,-0.019441,-0.640462,0.753222,-0.414712,0.039012,0.238090,0.449879,0.106592,-0.053365,0.109688,0.073645,0.074269,0.400428,-0.315641,-0.533047,0.773046,-0.011342,0.080048,0.055176,0.091094,0.145583,0.222009,0.420769,-0.489726,0.395755,-0.310046,0.330974,-0.344135,0.192258,0.110712,0.138984,-0.414674,0.225878,0.014942,-0.234005,-0.170801,0.147963,-0.276211,-0.712129,-0.071521,0.215632,0.330754,-0.663080,0.284813,-0.359845,0.056989,0.220547,-0.401415,0.189343,0.629446,0.101667,0.137629,-0.036812,0.134154,-0.440442,0.202706,0.561570,-0.058261,-0.034438,-0.107706,-0.002932,-0.434129,0.024376,-0.387587,-0.633369,0.140952,0.295203,-0.296311,0.174765,0.191549,-0.349927,-0.548528,-0.751096,-0.252077,0.329168,-0.669787,0.247591,-0.625833,0.118688,0.035092,0.057103,-0.236020,0.309363,-0.305434,0.662631,-0.875915,0.295122,0.652819,0.299700,-0.397794,0.327621,0.317374,0.389820,-0.317559,-0.274177,0.204347,0.096974,0.294516,-0.287679,0.287289,0.273021,-0.242626,-0.519736,0.357242', '5910040', '30345227', '1986338', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3102668', '天降美食', '喜剧', '在名为斯沃罗夫的小岛上，生活着一个名叫弗林德·洛克伍德（比尔·哈德 Bill Hader 配音）青年，他从小就想法多多，热衷各种各样的科学发明，比如不用鞋带的鞋子、能够自动行走的电视、飞行汽车、猴子语言翻译器等。想法虽好，但通常都以失败和灾难告终。母亲生前对他的鼓励令弗林德从不灰心，他屡挫屡勇，在科学发明的天地里自得其乐。不过，老爸再也无法忍受儿子无休止的折腾，他要求弗林德在自家的店里帮忙。与此同时，为了解决当地食物匮乏的问题，弗林德偷偷进行着超级食物机的研究。在最新的尝试中，弗林德毁掉了刚刚揭幕的沙丁鱼乐园，不过他的实验也取得成效。众目睽睽之下，天空下起了令人难以置信的汉堡包雨！一切都变得有趣起来……©豆瓣', '比尔·哈德尔', '菲尔·罗德', 7.5, 134336, 'tt0844471', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p501492695.jpg', 0.3, 2.7, 34, 46.5, 16.6, '0.319133,0.076829,-0.672227,0.549313,-0.123803,-0.133111,0.421476,0.150827,-0.441861,-0.153910,0.193927,0.574377,-0.062709,0.041740,0.123278,-0.084612,-0.410819,-0.379422,-0.067573,0.093391,-0.356534,-0.360396,-0.333931,-0.403624,-0.096468,-0.370713,0.367714,0.124605,-0.221318,0.128404,0.131695,-0.008761,0.045878,0.442983,-0.246011,-0.100167,-0.072890,0.074994,-0.077489,0.164337,-0.111238,-0.194253,-0.122612,0.317831,0.079345,0.135777,0.613477,-0.296119,-0.253034,0.033244,0.243782,-0.143450,0.048397,0.031973,0.146731,0.053350,0.184404,-0.068606,-0.167348,0.125506,0.096865,0.033652,-0.839043,-0.072934,-0.080012,0.043323,-0.638404,0.400746,-0.045109,-0.112872,-0.018331,-0.456386,0.062573,0.189273,0.283916,0.541635,-0.257795,0.028223,-0.361326,0.350468,0.378920,0.073987,-0.237800,0.368086,-0.277672,-0.192268,0.002707,-0.297807,-0.508264,-0.283862,0.279978,-0.001476,-0.547002,0.359955,-0.594867,0.292510,-0.052018,-0.449585,-0.122918,-0.175708,-0.098382,-0.651161,0.228462,-0.282197,-0.212646,-0.018300,0.065738,-0.238658,0.746301,-0.733068,0.239061,0.464500,0.014648,-0.189552,0.458160,0.033726,0.037367,-0.084307,-0.258450,0.129493,0.031437,0.314032,0.076142,0.458224,0.387849,-0.198588,-0.359076,0.664275', '1793491', '25928048', '3769423', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3103186', '钢铁苍穹', '喜剧', '2018年，美国总统为了自己的竞选能够胜出，再次启动了登月计划。当世界上第一位黑人宇航员詹姆斯·华盛顿（克里斯托弗·卡比 Christopher Kirby 饰）与同伴踏上月球时，却遭遇到了子弹的袭击。原来，早在1945年纳粹即将战败之时，纳粹的科学家在反重力的研究上取得了巨大的突破，并在南极的秘密基地上，将一支纳粹的研究部队送上了月球，并在月球背面建立起了一个军事基地。在那里，纳粹的科学家不分昼夜地研究新技术、改善武器，妄图在月球上重新建立起部队，反攻地球。华盛顿被俘后，其随身携带的智能手机被纳粹的科学家认为是启动他们的终极飞船的关键部件，因此掌权的军官阿德勒（戈兹·奥托 Götz Otto 饰）和情人雷纳特•里切特（茱莉亚·迭泽 Julia Dietze 饰）要求前往地球收集更多的手机，以便于反攻地球所用。当阿德勒带着华盛顿返回地球之后，一切的发展却与他们计划的有所不同，一个阴谋计划随之展开……', '戈兹·奥托', '提莫·沃伦索拉', 6.6, 45337, 'tt1034314', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1722221478.jpg', 3.5, 14, 42.9, 29.3, 10.3, '0.248077,0.239527,-0.899076,0.763569,-0.004532,-0.303465,0.501674,-0.163053,-0.373670,0.053148,0.208446,0.844200,0.042747,0.025406,0.246606,0.039039,-0.645892,-0.702655,-0.186921,-0.355498,-0.616985,-0.546267,-0.630017,-0.255515,0.008010,-0.442746,0.872259,0.187011,-0.223590,0.254570,0.025055,0.190806,0.035792,0.483493,-0.261417,-0.195976,0.097381,-0.029148,-0.395839,0.375745,-0.177543,-0.422485,0.078746,0.139265,-0.102827,0.300300,0.770875,-0.443561,0.160808,-0.582276,0.245829,-0.187341,0.030305,-0.003507,0.475929,0.347920,-0.315239,0.217822,-0.066118,0.206658,0.093452,-0.275606,-0.757540,-0.268343,-0.131206,-0.076039,-0.551590,0.290460,-0.507483,0.363605,-0.141924,-0.367153,0.312987,0.725330,0.092500,0.268630,-0.280387,0.068413,-0.505860,0.156311,0.346529,-0.092078,-0.312266,0.152120,0.004575,-0.503308,-0.234995,-0.113407,-0.238229,-0.268728,0.495779,-0.034190,-0.010701,0.238863,-0.879185,0.120336,-0.485401,-0.487392,0.167559,-0.137779,-0.029347,-0.952352,0.059924,-0.119396,-0.246454,0.159016,0.090398,-0.086635,0.830553,-0.801268,0.208823,0.742785,0.409729,-0.369548,0.383840,-0.181358,0.274354,-0.372392,0.004136,0.217999,-0.052825,0.761508,-0.117448,0.411430,0.006176,-0.260642,-0.437266,0.5