INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3103418', '囚室211', '剧情', '新任狱警胡安（Alberto Ammann 饰）为展示良好职业风貌，提前一天入狱体验工作。而在这一天里，犯人头目“恶母”击伤狱警，带领犯人暴动，监狱陷入了一片混乱……胡安因受伤被同伴丢弃在211囚室，为了避免被犯人们当做人质，他只得乔装罪犯，谋取恶母的信任，试图寻找脱身机会。犯人们以监狱中的三名刑期百年以上的“埃塔”恐怖分子要挟官方答应他们的谈判条件，因政府与埃塔方面有协议在先，监狱方与特别行动组投鼠忌器，迟迟不能强攻，致使局势僵持。另一方面，监狱暴动经媒体报道后引起连锁反应，家属们纷纷来到监狱探听消息，却遭到狱警们的毒打，胡安怀有身孕的妻子不幸受伤，而这让本欲确保自己脱身并协助狱方平息事端的胡安做出了疯狂的举动……本片横扫2009年西班牙戈雅奖最佳电影、导演、男主角等八个主要奖项。©豆瓣', '路易斯·托萨尔', '丹尼尔·蒙宗', 8, 40653, 'tt1242422', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1622684528.jpg', 0.3, 1.5, 19.6, 55, 23.7, '-0.017692,-0.047830,-0.482662,0.108295,0.072185,0.155124,0.408062,0.272292,-0.648634,-0.306320,0.431149,0.359263,-0.055796,-0.036044,0.269121,-0.695331,-0.461467,-0.549242,-0.134203,-0.095006,-0.247422,-0.129911,-0.037816,-0.549014,-0.144939,-0.487536,0.698574,0.011778,-0.302024,0.193087,0.317248,0.456855,-0.112583,0.191727,0.270592,-0.164351,0.312470,-0.326264,-0.439673,0.398565,-0.151784,-0.477505,-0.250188,0.106924,0.118446,0.481827,0.706358,-0.184355,-0.298559,-0.159584,0.285884,-0.528878,-0.097377,0.255099,0.386904,-0.091526,0.058500,0.464505,-0.313236,0.044248,-0.024648,-0.132006,-0.613552,0.051583,0.100065,-0.051954,-0.249594,0.070540,-0.086567,0.279300,0.022758,0.128393,0.070536,0.542644,0.169048,0.038309,-0.173876,-0.114286,-0.328924,0.132949,0.686382,-0.491360,-0.230227,-0.250951,-0.133240,-0.444005,0.103927,-0.416909,-0.130308,-0.045102,0.410801,0.007909,-0.254564,0.152931,-0.218678,-0.134042,-0.546822,-0.361353,-0.099188,-0.230806,0.071835,-0.760755,0.029799,0.337217,-0.245519,0.042617,0.073813,0.047646,0.433665,-0.420767,0.231124,0.721898,0.139590,-0.997079,0.334313,0.155543,0.277503,-0.147668,-0.112840,0.090488,0.417872,0.360768,0.087184,-0.231037,-0.192626,-0.273366,-0.141482,-0.160198', '1484760', '3412882', '1307106', '4193254');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3103683', '华尔街：金钱永不眠', '剧情', 'http://site.douban.com/108127/华尔街：金钱永不眠 豆瓣小站2001年，昔日叱咤华尔街的戈登（迈克尔•道格拉斯 Michael Douglas 饰）出狱了，无人来接，8年未见的女儿维妮（凯瑞•穆里根 Carey Mulligan 饰）与他势同水火。不过，她的男友——股票交易员杰克（希亚•拉博夫 Shia LaBeouf 饰）却对他有些崇拜。杰克热衷清洁能源项目，但他的老板兼导师路易斯都劝他早日收手，并给了他一笔钱。没想到，公司因负面新闻债台高筑，投资银行的詹姆斯趁机收购。被逼无奈的路易斯卧轨自杀。杰克决心为导师复仇。他向戈登毛遂自荐，希望得到他的指点。戈登了解到他与维妮的关系，便提出了一个交易：杰克给他创造接近女儿的机会，他教杰克如何操作资本。为了复仇，杰克决定铤而走险，然而感情的翻转却让他始料不及……©豆瓣', '迈克尔·道格拉斯', '奥利佛·斯通', 6.5, 49017, 'tt1027718', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p622403060.jpg', 1.5, 12.2, 52.9, 26.3, 7.1, '-0.056374,0.142576,-0.534399,0.553825,-0.211055,-0.752945,0.447811,0.161613,-0.293738,-0.273927,0.055989,0.526130,0.001691,0.107563,0.198827,0.092360,-0.195171,-0.509660,0.265560,0.057014,0.070539,-0.550283,-0.329671,-0.384096,-0.148259,-0.171315,0.434665,-0.006705,-0.104752,0.321855,0.213931,0.124946,0.361147,0.530089,0.072575,-0.005972,0.097807,-0.035264,-0.461783,0.328794,0.156171,-0.237006,-0.251605,0.370897,0.124096,0.544479,0.320443,-0.037830,0.056916,-0.048248,0.181024,-0.276999,0.269005,0.144459,-0.074528,0.006746,-0.023423,0.191566,-0.246322,-0.301272,0.058119,-0.062059,-0.834203,0.126699,-0.115200,-0.036630,-0.684732,0.381630,-0.619218,0.214382,-0.127935,-0.403533,-0.232101,0.172887,0.360481,0.203745,-0.192935,0.220162,-0.382979,0.248134,0.382168,-0.038405,0.007363,0.365713,-0.175724,-0.372456,0.027890,-0.131915,-0.366244,-0.171620,0.408325,-0.001523,-0.081989,0.170185,-0.435000,-0.225537,-0.443115,-0.112664,0.019334,-0.405867,0.216240,-0.370281,-0.136391,-0.107400,-0.288830,-0.139601,0.194026,-0.423970,0.517869,-0.578820,0.013503,0.693607,0.475323,-0.608628,0.690916,-0.010652,-0.047298,-0.340687,-0.089064,0.145501,0.125136,0.137682,0.276997,0.049190,0.437613,-0.303734,0.133328,0.469378', '3785918', '4604803', '26678784', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3104216', '心灵厨房', '剧情', '一个希腊后裔的德国人Zinos（亚当·布斯多柯斯 Adam Bousdoukos 饰）在汉堡开了间餐厅，名字叫“Soul Kitchen”，最近遭遇了严重的财政危机，入不敷出，难以为继。祸不单行，Zinos还因为一次意外而腰椎间盘突出。而他的情感生活也有麻烦，他的女友Nadine（菲琳·罗根 Pheline Roggan 饰）是一名记者，决定到上海工作。他的弟弟Illias（莫里兹·布雷多 Moritz Bleibtreu 饰）刚从监狱里假释出来，来到Zino的餐厅打工。因为身体问题，Zino只能雇了另外一个厨师Shayn（波热尔·尤内尔 Birol Ünel 饰），但是Shayn做出的新菜，却没有受到老顾客们的欢迎，餐厅的收入每况愈下。而Zinos的女友也决定抛弃他，和一个在上海萍水相逢的人在一起。问题多多的Zinos该如何咸鱼翻生？Soul Kitchen能否继续营业？', '亚当·布斯多柯斯', '法提赫·阿金', 7.3, 5888, 'tt1244668', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p546310549.jpg', 0.4, 3.7, 36.1, 47.7, 12.1, '0.242106,0.025014,-0.588686,0.396041,-0.257734,-0.524247,0.893794,0.474880,-0.477388,-0.136027,0.098664,0.794213,0.062650,0.333242,0.341912,0.082938,-0.208420,-0.322661,0.419321,-0.202404,-0.504224,-0.493047,-0.028370,-0.412981,-0.087663,-0.110581,0.268474,0.146677,-0.061286,0.204374,0.390303,0.158485,0.123798,0.686545,-0.107813,0.011439,0.256416,0.062707,-0.051085,0.291978,0.180704,-0.313862,-0.273183,0.229196,0.263325,0.504489,0.405833,0.065020,-0.275619,0.139365,0.291117,-0.052122,-0.087838,0.096757,0.373682,-0.171136,0.263550,-0.041721,-0.225285,0.173000,0.102636,-0.162156,-0.725004,0.030105,-0.138188,0.186056,-0.660594,0.559770,-0.184525,-0.063156,0.018564,-0.540789,-0.081975,0.477747,0.154809,0.388186,-0.239025,0.172321,-0.576016,0.158410,0.686666,0.041391,-0.272990,0.404456,-0.139948,-0.482894,-0.030081,-0.210879,-0.400320,-0.091596,0.298042,-0.065473,-0.241865,-0.050629,-0.538424,0.006614,-0.205164,-0.334025,-0.059851,-0.043464,-0.165563,-0.549932,0.088643,-0.246052,-0.177923,0.103726,0.191679,0.114386,0.571057,-0.754837,0.205563,0.693177,0.266871,-0.546054,0.658774,0.096603,0.200603,-0.092176,-0.341293,-0.079985,0.059114,0.327159,0.233772,0.272281,0.197041,-0.389138,-0.247630,0.190758', '1308755', '27060077', '1292217', '1292584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3104794', '赤焰战场', '喜剧', '前特工人员弗兰克·摩西斯（布鲁斯·威利斯 Bruce Willis 饰）早年和同伴们金戈铁马，经历大风大浪，如今早已各自闲赋家中，过着优哉游哉的安逸生活。然而这份退休后的平静突然被打破，在圣诞前夜，一群全副武装的不速之客闯入弗兰克的家中，对其痛下杀手。原来，作为资深探员，弗兰克和他的同伴知道太多关于政府和军方的秘密，他们理所当然成为被抹杀的对象。不甘将命运交诸他人之手，弗兰克找到了乔·麦瑟森（摩根·弗里曼 Morgan Freeman 饰）、马文·博格斯（约翰•马尔科维奇 John Malkovich 饰）和维多利娅（海伦·米伦 Helen Mirren 饰）等当年的好搭档，决心展开一场绝地大反击……本片根据华伦·埃利斯（Warren Ellis）和库里·汉默（Cully Hamner）的漫画改编。©豆瓣', '布鲁斯·威利斯', '罗伯特·斯文克', 7.6, 99583, 'tt1245526', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2536150267.jpg', 0.3, 2.7, 31, 50.4, 15.7, '0.449728,-0.015091,-0.563192,0.500707,0.045712,-0.316670,0.693287,-0.168434,-0.569874,-0.555317,0.085687,1.002135,-0.274280,0.313741,0.428782,-0.180687,-0.638247,-0.789688,-0.255710,-0.181337,-0.141051,-0.591616,-0.267646,-0.220512,-0.039859,-0.229252,0.579289,-0.048120,0.202692,0.533685,0.335307,0.576773,0.111920,0.207491,0.009148,0.309226,0.441632,-0.275770,-0.402865,0.097423,0.175450,-0.003558,-0.202392,0.200474,0.253970,0.256655,0.454296,-0.591291,0.070190,-0.094779,0.192762,-0.284534,0.239561,0.235242,0.405733,0.050626,0.000868,0.384523,-0.170026,-0.069063,-0.048926,-0.114956,-0.681157,-0.025675,-0.000146,0.093811,-0.480803,0.291822,-0.312957,0.176968,-0.029632,-0.103073,0.149644,0.377006,0.419266,0.174258,0.051686,-0.118538,-0.229582,0.109302,0.563024,0.114672,-0.097757,0.031256,-0.289008,-0.375212,-0.099698,-0.328647,-0.559110,-0.131153,0.463792,0.023298,0.080255,0.497926,-0.515957,-0.192114,-0.460771,-0.031971,-0.179595,-0.397318,-0.234418,-0.909012,-0.036377,-0.325371,-0.258031,0.156366,-0.025691,-0.159400,0.547749,-0.718030,0.303746,0.240856,0.230392,-0.203388,0.426796,-0.054907,0.344453,-0.132909,-0.070313,0.404524,0.512679,0.116278,0.359729,0.269518,-0.146660,-0.201629,-0.106020,0.371898', '11541282', '1293656', '7916027', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3104798', '世界末日', '喜剧', '杰伊（杰伊·巴鲁切尔 Jay Baruchel 饰）千里迢迢来到洛杉矶，希望能和好友塞斯（塞斯·罗根 Seth Rogen 饰）共度一段美好的时光，可是，没过多久，杰伊便发现，塞斯和自己不同，早已经在洛杉矶结识了一大帮新朋友的他并不如自己一般感到寂寞。在半推半就下，杰伊跟随塞斯加入了在詹姆斯（詹姆斯·弗兰科 James Franco 饰）家举行的一场疯狂派对，对于疯疯癫癫狂妄自大的詹姆斯，杰伊十分反感，但很显然，詹姆斯和塞斯之间的关系十分亲密。一场灾难的降临让世界陷入了一片火海，与此同时，在豪宅里狂欢的众人对此还一无所知。这一切究竟是天灾还是人祸？被困的杰伊等六人能否绝处逢生呢？©豆瓣', '塞斯·罗根', '塞斯·罗根', 6.8, 43949, 'tt1245492', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1933984371.jpg', 3.2, 10.9, 42, 32.6, 11.3, '0.301647,0.008720,-0.758781,0.341438,-0.002117,-0.314212,0.902578,0.312939,-0.771815,-0.209038,0.114715,0.820316,-0.365761,0.172741,0.489253,0.019601,-0.658708,-0.639824,0.005194,-0.226192,-0.179082,-0.651008,-0.359387,-0.166204,-0.032806,-0.454186,0.400625,0.171090,0.232014,0.686812,0.308922,0.443546,-0.080872,0.754436,-0.234710,0.038328,0.371110,0.203070,-0.649288,0.114973,-0.061681,0.131800,-0.282433,0.238128,0.149644,0.085626,0.455064,-0.372057,-0.090616,0.150293,0.083827,-0.163862,0.085186,0.342648,0.163094,-0.234787,0.341070,0.163109,-0.247690,0.116004,-0.050741,0.009650,-0.695987,0.398682,0.085953,0.296788,-0.553876,0.548153,0.090877,-0.383265,0.052938,-0.370194,0.031410,0.630692,0.408220,0.508940,-0.105016,-0.278256,-0.567339,-0.221070,1.049746,0.072382,-0.366380,0.446635,-0.130626,-0.192469,-0.088545,0.302512,-0.506245,-0.118589,0.281837,-0.092940,-0.011710,0.578976,-0.621622,0.234544,-0.368080,-0.378659,-0.129214,-0.589095,-0.112358,-0.743177,-0.234422,-0.305012,-0.367807,-0.080054,0.140296,-0.215116,0.500407,-1.020081,0.449599,0.352963,0.113748,-0.130849,0.451932,0.339924,0.095064,-0.145097,-0.090907,0.356246,0.056431,0.057106,0.022480,0.425396,0.071526,-0.188399,-0.359419,0.673618', '1308755', '25721544', '26971054', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3105588', '周围的事', '剧情', '金尾（Lily Franky 饰）和翔子（木村多江 饰）是一对普通的夫妇，金尾在鞋铺工作，翔子则是某杂志编辑部内不断被琐事烦扰的小编辑。夫妻俩的生活平淡无奇，甚至连亲热之事也按固定日期计划进行。在朋友的介绍下，金尾谋得一份法庭画家的工作。虽然妻子家人都不甚看好，但在安田（柄本明 饰）等前辈的帮助下，他的工作逐渐步入正轨。翔子不满意丈夫先斩后奏的做法，同时被杂志社的俗务所烦扰，但她心中幸福的种子正在发芽，一个小生命即将为这对夫妇的生活带来新的体验……本片荣获2009年日本电影学院奖最佳女主角（木村多江）、2009年蓝丝带奖最佳女主角（木村多江）和最佳新人（Lily Franky）、2008年报知电影奖最佳导演（橋口亮輔）、2009年每日电影大奖最佳剧本（橋口亮輔）和最佳影片。©豆瓣', '木村多江', '桥口亮辅', 8.4, 13372, 'tt1245489', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p624725042.jpg', 0.3, 1.3, 14.6, 47.9, 35.9, '-0.228450,-0.159818,-0.187381,0.664154,0.120109,-0.092557,0.269590,0.308922,-0.438093,-0.451878,0.221851,0.445997,-0.238190,0.132935,0.174525,0.009444,-0.388167,-0.775433,-0.097225,0.010602,-0.112297,-0.224449,-0.203050,-0.150909,-0.392831,-0.098109,0.803030,-0.096749,0.197935,0.423884,0.290335,0.085759,0.019022,-0.045468,-0.064163,0.026799,0.206490,0.021236,-0.594206,0.206287,0.101640,-0.285346,-0.124740,0.080747,0.396468,0.245242,0.844818,-0.093120,-0.401511,0.058557,0.630297,-0.196347,-0.014390,0.123550,0.240055,0.084583,0.290532,0.135363,-0.377206,0.198322,0.022458,-0.429542,-0.811647,0.044727,0.092022,0.090146,-0.448456,0.679347,-0.101268,0.288403,0.031361,-0.306383,0.131934,0.262321,0.415248,0.203918,-0.269936,0.132728,-0.094852,0.702643,0.333820,0.169991,0.022921,0.475008,-0.274338,-0.416891,-0.278287,-0.013342,-0.475168,0.051782,0.183541,0.113504,0.088386,0.155749,-0.464868,0.085902,0.060758,-0.330560,0.366237,-0.405892,-0.056104,-0.723370,-0.069654,-0.299162,-0.360814,-0.073209,0.362469,-0.375719,0.950007,-0.533042,0.193373,0.332211,-0.012801,-0.393075,0.886223,0.147729,0.084691,-0.421992,-0.149149,-0.056822,-0.085252,0.149229,0.268352,0.162618,-0.089825,-0.284661,-0.329767,0.306747', '27602116', '22265121', '2027945', '6101834');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3111650', '红河', '剧情', '阿桃（张静初 饰）幼时目睹父亲被炸死受到刺激，之后人就变的傻乎乎的。长大后姑姑阿水（李丽珍 饰）把她带到自己在中国经营的按摩房帮工，阿桃的纯真引起了光顾按摩房的黑帮老大沙巴（李修贤 饰）的好感。在一次警察的追捕中，阿桃误闯进瑶族男人阿夏（张家辉 饰）的家中。阿夏靠街边的卡拉OK生意为生，阿桃的好嗓子让他看到了新的商机，而阿桃则因为阿夏额头有一颗和父亲一样的痣而认定他就爸爸。阿夏的生意因阿桃的加入明显好转，小摊前要求和阿桃合唱的人排起了长队。在阿夏与阿桃相处的过程中，两人的关系发生了微妙的变化，阿夏因有好色之徒占阿桃便宜而大大出手，阿桃也因为阿夏和情人阿花亲热而发怒。沙巴一直牵挂着纯真的阿桃，他决心要收阿桃做干女儿。沙巴的手下绑架阿桃之后，阿桃意外看到沙巴开枪而对他充满恐惧并逃回阿夏身边。沙巴并不是会轻易放弃的人，故事因为沙巴的坚持而复杂起来。本片由著名导演章家瑞执导，他的三部作品——《诺玛的十七岁》、《花腰新娘》和《红河》，被合称为“云南三部曲”。', '张静初', '章家瑞', 7.2, 22499, 'tt1245719', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1972796908.jpg', 0.6, 4.8, 41.3, 40.7, 12.6, '0.287476,-0.076187,-0.768822,0.470016,-0.161387,-0.291527,0.976559,0.191950,-0.592765,0.122759,0.188453,0.800910,-0.154303,0.201793,0.361593,0.263844,-0.086266,-0.742849,0.066310,-0.026421,-0.090142,-0.376440,-0.095258,-0.178522,-0.136855,-0.347491,0.391248,-0.033365,-0.173131,0.731066,0.377874,0.057590,-0.053222,0.461462,-0.047392,0.261606,0.078176,-0.103834,-0.156442,0.024851,0.020094,-0.071364,-0.155491,0.148425,0.083521,0.422607,0.587545,-0.126078,-0.267460,-0.096723,0.058562,-0.199162,-0.005454,0.101218,0.239060,0.068788,0.259101,0.043715,-0.233739,0.043295,0.037694,0.110127,-0.478393,0.341670,0.267680,0.237992,-0.746506,0.548749,-0.062810,-0.124768,0.238696,-0.309471,0.327048,0.304060,0.273563,0.293162,-0.247491,0.031664,-0.443863,0.060575,0.559265,-0.222188,0.109268,0.344653,-0.218767,-0.279237,0.018966,-0.189897,-0.462793,0.108526,0.226880,-0.031416,-0.338761,0.084711,-0.599104,-0.054107,-0.102704,-0.141888,-0.110802,-0.354326,-0.084680,-0.455975,-0.064928,-0.499600,-0.312874,0.005483,0.078660,-0.269084,0.662248,-0.789928,0.219313,0.292143,0.393716,-0.493107,0.559468,0.090014,-0.042327,-0.230447,-0.214630,0.151590,-0.003975,0.081975,0.139584,0.238348,-0.023974,-0.169704,-0.136792,0.441029', '1308755', '1296534', '1292211', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3112738', '赛琳娜', '剧情', '故事发生在1929年，乔治（布莱德利·库珀 Bradley Cooper 饰）和新婚妻子萨琳娜（詹妮弗·劳伦斯 Jennifer Lawrence 饰）一起千里迢迢赶往位于北卡罗纳那的深山之中，野心勃勃的两人决心在那里建立属于他们的木材帝国。面对恶劣的生存环境，初来乍到的萨琳娜展现出了无比强悍的一面，尽管身为女子，但她捕蛇、狩猎样样精通，丝毫不输给丈夫，甚至在一次意外之中挽救了丈夫的性命。在萨琳娜的扶持之下，乔治步步为赢，给予了商业对手沉重的打击。然而，一次偶然中，萨琳娜发现了乔治的秘密，他竟然有一个私生子，这对于无法生育的萨琳娜来说无异于一个噩耗。愤怒的萨琳娜决心将这个无辜的孩子置于死地。©豆瓣', '詹妮弗·劳伦斯', '苏珊娜·比尔', 5.7, 6623, 'tt1247690', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199665827.jpg', 4, 27.1, 51.5, 13, 4.4, '0.386470,0.144536,-0.801411,0.910443,0.053759,-0.107097,0.545951,0.050931,-0.412772,-0.442598,0.278019,0.822804,0.210305,-0.090110,0.108703,-0.128729,-0.161960,-0.593727,0.104452,-0.248313,-0.221710,-0.623077,-0.523324,-0.443838,-0.263241,-0.552650,0.264045,0.137903,-0.107603,0.710106,0.476720,0.376639,0.331392,0.391028,0.194183,-0.039009,0.331264,-0.031533,-0.463370,0.549090,0.162784,0.126791,-0.100615,0.444187,0.182379,0.450575,0.448631,-0.760238,0.138222,-0.237110,0.383307,-0.384794,0.032862,0.174339,0.308023,-0.453802,-0.098545,0.182968,-0.464692,-0.065139,0.581138,-0.204845,-0.667849,0.047267,0.185468,0.059818,-0.668025,0.431194,-0.140926,0.082199,0.072124,-0.152053,0.056434,0.394036,0.227799,0.300035,-0.102680,0.009825,-0.600594,-0.128405,0.846083,0.262923,-0.207818,0.135078,-0.520717,-0.533065,-0.114590,-0.726923,-0.617022,-0.010512,0.293935,0.115070,-0.119049,0.540231,-0.323332,-0.260394,-0.537828,0.093223,-0.090645,-0.785321,-0.151143,-0.560753,-0.186881,-0.401952,-0.228274,0.232048,-0.094658,-0.351784,0.508598,-0.809105,0.126774,0.296557,0.206271,-0.313920,0.651983,0.126141,0.321058,-0.137231,-0.400468,0.661571,0.216312,-0.186192,-0.100907,0.170751,-0.017805,0.053676,-0.373258,0.574697', '34968329', '1309177', '3284768', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3113588', '艾草', '剧情', '58岁的母亲吴艾草（潘丽丽 饰）跟其他台湾师奶别无两样：膝下一双儿女，生活清闲平静。早年间曾与异乡老师私奔，可算是思想开放的女性。然而她在不经意间发现了小儿子宋海（莫子仪饰）举止异常，种种迹象都证明儿子是名同志。面对儿子的离经叛道，艾草并没有道破，但也使她无所适从，困惑不已。此 时，留学而归的大女儿宋伶（周姮吟饰）居然带回了跟黑人所生的私生女。这时的艾草再也按耐不住，长年建立起来的伦理观瞬间崩塌。作为一名母亲，她不能接受这种违背社会道德的行为。面对社会舆论的压力，艾草的内心陷入苦苦的挣扎中。最终，她会接受子女的选择么？©豆瓣', '潘丽丽', '姜秀琼', 8.3, 6649, 'tt1405358', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2370767486.jpg', 0.4, 0.9, 16.2, 48.7, 33.8, '0.338122,0.055952,-0.617159,0.506684,-0.301428,-0.320726,0.646633,0.158296,-0.862713,-0.466727,-0.057209,0.561332,-0.078909,0.507741,0.245829,-0.278018,0.021424,-0.555563,-0.134351,0.152141,-0.063475,-0.485105,-0.119150,-0.252269,-0.413094,-0.086468,0.675035,0.057093,-0.270656,0.380197,0.284349,0.261800,0.074449,0.470421,-0.033386,0.071898,-0.188664,0.186741,-0.235608,-0.130829,0.229070,-0.211440,-0.130382,0.239591,-0.027610,0.463945,0.364856,-0.287914,-0.245147,-0.250548,0.479822,-0.050898,-0.142101,0.150054,0.032011,-0.088191,0.196502,0.091176,-0.018280,0.003671,0.260357,0.081113,-0.342755,0.003772,0.236629,0.163932,-0.615126,0.188782,0.007913,-0.094170,-0.192366,-0.166907,0.173049,0.170135,0.235010,0.552529,-0.423870,0.032817,-0.314431,0.153452,0.612662,0.064748,-0.269941,0.069306,-0.482278,-0.460708,0.185348,-0.359402,-0.549838,-0.042971,-0.220405,0.299782,-0.302920,0.330677,-0.269495,-0.072800,-0.050531,0.062397,0.018030,-0.377389,0.073165,-0.136665,-0.092275,-0.546313,-0.344419,0.191714,0.145865,-0.267338,0.536683,-0.871532,0.263483,-0.106413,0.340105,-0.546239,0.514112,0.371825,0.136381,-0.119013,-0.122264,0.395646,-0.039879,0.068685,0.065939,0.047025,-0.135370,-0.137365,-0.009781,0.263082', '35030151', '1301022', '25721544', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3114109', '暴力街区13：终极', '动作', '卧虎藏龙而又凌乱不堪的13区在上一部《暴力街区》时间设定的两年后再次陷入了大宗阴谋事件，达米安上尉（西里尔•拉法埃利 Cyril Raffaelli 饰）与雷伊托（大卫•贝利 David Belle 饰）这次的对手是不择手段的房地产商——13区将因他的房地产计划而毁灭。在利益集团实施一系列精心筹备的栽赃行动后，13区的暴力一面被推向媒体的风口浪尖，13区一时间成为国民心中残暴的象征；达米安又身陷囹圄，极度不利的局势下，雷伊托成为13区最后的希望，他能否营救达米安并联合13区内的五大势力最后将真相呈献给总统以拆穿不法商人的阴谋呢？©豆瓣', '大卫·贝利', '帕特里克·亚力桑德罗', 7.5, 63132, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p486911445.jpg', 0.5, 3.8, 34.5, 45, 16.3, '0.220236,0.340304,-0.507501,0.604114,0.229808,0.055815,0.460126,0.254608,-0.559998,0.044358,0.303270,0.538509,-0.264029,-0.076975,0.451344,-0.112690,-0.504899,-0.821627,-0.293500,-0.173482,-0.199545,-0.403202,-0.372361,-0.486756,-0.006063,-0.156371,0.814297,0.496258,-0.487028,-0.084362,0.431952,0.536362,-0.040318,0.398742,0.074879,-0.173377,0.212435,-0.421851,-0.468226,0.403469,-0.024833,-0.418458,-0.099544,0.559504,-0.131981,0.401704,0.716588,-0.333343,0.018772,-0.266581,0.493179,-0.491401,-0.033583,0.194514,0.575162,-0.077413,0.198366,0.509421,-0.182648,-0.081285,0.253854,-0.195848,-1.037933,-0.048097,0.179139,0.031927,-0.406677,0.389692,-0.280341,0.188062,-0.003025,-0.236824,0.114373,0.695202,0.483520,0.139466,-0.033819,-0.043026,-0.324581,-0.012673,0.595450,-0.030986,-0.163541,-0.156851,0.059926,-0.509354,-0.130582,-0.599178,-0.131694,-0.301396,0.441399,0.004444,0.127948,0.566953,-0.766776,0.003894,-0.446471,-0.395481,0.151446,-0.446940,-0.036655,-0.682381,-0.068024,-0.115298,-0.093283,-0.050454,0.260413,-0.162982,0.533510,-0.743871,0.096202,0.504068,0.181547,-0.655895,0.378760,0.057076,0.283158,-0.066220,-0.384511,0.024060,0.122563,0.477437,-0.027342,0.285182,-0.045464,-0.445106,-0.123951,0.349481', '27073234', '26678784', '26759820', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3114200', '如梦', '剧情', '迈克（吴彦祖 饰）是纽约一家安全软件公司的职员，他的猫死了，这令他非常不安，他来到神父面前祷告，但是依旧无法安睡。在梦中，迈克遇到了一个奇怪的女人艾玲（袁泉 饰），她失魂落魄，因为男朋友此前跳楼自杀，迈克试图劝慰她，却屡屡受挫。因为这个离奇的梦，迈克的脑海中反复萦绕艾玲。他决定去上海寻找她。一次偶然的机会，他在冲洗店得到了她的照片。按照这个线索，他来到了杭州，却因为邂逅了艾玲的双胞胎妹妹。原来，她们是孤儿，被分别寄养。迈克漠然回到了纽约，内心却充满了纠结，他从此陷入了一种茶饭不思的窘境，以至于公司伙伴也开始觉得心寒。他再次来到了上海，重新见到了那个艾玲的妹妹，然而当双方吐露心事的时候，他们的关系也发生了复杂的改变……©豆瓣', '袁泉', '罗卓瑶', 6.2, 28290, 'tt1247676', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p506599333.jpg', 4, 17.5, 48.2, 23.4, 6.9, '0.351697,0.148864,-0.860481,0.491426,-0.063801,-0.491337,0.960314,0.161027,-0.746809,-0.271907,0.295803,0.813529,-0.270686,0.485953,0.155188,0.193485,-0.231590,-0.658081,0.219356,-0.164421,0.003006,-0.305273,-0.178654,-0.231276,-0.025084,0.020294,0.486064,0.121693,0.016113,0.432477,0.267508,0.236468,-0.006683,0.840458,-0.133691,0.251933,0.130493,0.036174,-0.113187,0.011984,0.225576,-0.310195,-0.101382,0.409819,-0.010145,0.482040,0.626802,0.010176,-0.465668,0.112450,0.323071,-0.150971,-0.163464,0.155862,0.054127,0.020535,0.045837,-0.107323,-0.335369,-0.203913,-0.159954,0.255284,-0.659055,0.211838,0.012513,0.264995,-0.609118,0.431731,-0.178116,0.148203,-0.002925,-0.416373,0.303831,0.211540,0.382845,0.328989,-0.241735,-0.016273,-0.462144,0.200164,0.691512,-0.010481,-0.144629,0.514132,-0.223602,-0.327241,-0.005100,0.103296,-0.448891,0.145858,0.338107,0.125827,-0.505108,0.121556,-0.499340,-0.192658,-0.311185,-0.196052,-0.177822,-0.511312,-0.100200,-0.276951,-0.176463,-0.270876,-0.442407,-0.084647,-0.278131,-0.226706,0.340140,-0.962665,0.246988,0.758944,0.285052,-0.427595,0.560696,0.107312,-0.049166,-0.319499,-0.013020,0.593675,-0.279233,0.367625,0.219978,0.361538,0.069480,0.094597,-0.468010,0.488748', '1308755', '3059036', '1309080', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3117778', '魔卡少女樱剧场版：被封印的卡片', '喜剧', '自从艾力欧走后，友枝町又恢复了宁静。无法目睹到小樱（丹下樱 配音）收复卡片英姿的知世（岩男润子 配音）找来了DV，自己弄起了特摄剧。在看录像带的过程中，小樱看到了小狼（熊井素子 配音）的影像，不经红了脸。小狼回到香港已经四个月了，距离小狼告白也有四个月了。这期间小樱一直模拟着告白，希望下次再见到小狼时，当面告诉他。艾利欧的家被拆了后，建起了游乐园。某次小樱和知世经过时，小樱发觉了不一样的气息，追随着跑进游乐园，结果撞上了一个人，抬头一看发现竟然是小狼。原来小狼和莓玲趁暑假来日本玩。再次和小狼相见，让小樱非常紧张也在寻找表达心意的机会，但无奈都被阴差阳错的打乱。而这时，小樱发现自己的牌变少了，而牌走失的方向正是游乐园。传说中被封印的最后一张卡片，艰难的战斗，小樱能否胜利？而她是否又能向小狼成功传达心意呢？©豆瓣', '丹下樱', '浅香守生', 9, 15154, 'tt0301083', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p453989041.jpg', 0.2, 0.6, 8.1, 29.3, 61.8, '0.175520,0.209448,-0.446478,0.425731,0.082242,-0.484958,0.473450,-0.027186,-0.108572,-0.022968,-0.055243,0.572925,-0.422189,0.366711,0.139562,0.132750,-0.348275,-0.566075,-0.188978,-0.328236,-0.563803,-0.297436,0.021158,0.195736,0.046460,-0.152396,0.345767,-0.138653,-0.185336,0.350253,0.216465,-0.072633,-0.256486,0.355797,0.002661,0.263300,0.108326,0.081448,0.191925,0.401925,0.056973,-0.340659,-0.311255,0.273586,0.099056,0.222190,0.993427,-0.460967,-0.218445,-0.135204,0.151405,-0.114730,-0.147950,0.117032,0.080727,0.162097,0.173493,-0.131467,-0.231330,-0.042272,0.002412,-0.054972,-0.469134,0.587934,-0.305318,0.162947,-0.552179,0.379152,0.040259,-0.013095,0.377007,-0.579190,0.215924,0.470264,0.202230,0.344973,-0.401658,0.116306,-0.341027,-0.101402,0.533763,-0.097455,-0.039344,0.562458,0.199601,-0.347569,0.205032,0.052803,-0.080676,0.007035,0.461723,0.297184,-0.438155,-0.110520,-0.611232,-0.042567,-0.303609,-0.305810,0.016507,-0.363877,-0.233482,-0.523907,-0.204391,-0.464316,-0.256405,0.208996,-0.051745,-0.254008,0.634092,-0.941175,0.018674,0.555015,0.343063,-0.039550,0.500235,-0.088462,-0.335792,0.002022,0.080590,-0.046807,0.054520,0.558197,0.649960,0.430967,-0.014937,-0.239800,-0.603903,0.450506', '3044878', '1292219', '1420088', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3118848', '虎与龙SP', '剧情', '2005年1月9日放送的一集90分钟左右的SP电视剧（《三枚起请》）。故事就从小虎讨债偶然看了“三枚起请”开始展开，好容易能够学习落语了，完全不明状况的小虎立即提出要学习“三枚起请”。先来解释一下这个落语故事吧。主要人物：仏壇屋の源兵衛，下駄屋の喜六，指物屋の清八，小山(おやま＝女郎)の小輝(こてる)，茶屋の女将三个男人在同一个女郎/游女那里得到了起请（就是向神佛起誓的誓言纸）。正常来说从良前女子写给自己中意男子，一个女子只能给一个男子。男人们发现自己被骗了之后就去找游女，并且告诉他“说谎的一张起请会杀死熊野的使者三只乌鸦”，因为熊野誓纸相当有名，而一旦毁约，神佛的使者乌鸦会死去。但是游女却引用会把高杉晋作做的“三千世界の烏を殺し、ぬしと朝寝がしてみたい”（天下的乌鸦都死了，就能睡好觉了<===随便翻ing，因为游女都是夜间工作，早晨吵闹的乌鸦使得她们和客人不能好好睡觉。）（= =………………严重BS自己的语言功能ing）而小虎完全不能理解故事的背景和笑点，通过师母的指点找到龙二，想让他教自己这个落语。之间两人解决了小虎流星会的麻烦，也卷进了MEGUMI和一众男人的故事中，通过这个，小虎讲起了自己的“五枚起请”，将落语和现实生活结合在一起，得到了意想不到的欢迎………………之后因崭新的剧情构成而反映强烈，所以顺势于春季推出了电视剧版。电视剧版的剧情承接自《三枚起请》。', '长濑智也 Tomoya Nagase', '金子文纪', 9.2, 7037, '三枚起请', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p809505182.jpg', 0.3, 0.4, 4.8, 27.1, 67.4, '0.461302,0.050389,-0.390541,0.548354,-0.125112,-0.134874,0.510737,0.055623,-0.238940,-0.075919,0.058473,0.662989,-0.105277,0.277396,0.214982,0.083517,-0.147471,-0.572983,-0.133011,-0.213545,-0.456249,-0.375638,-0.028375,-0.223272,-0.078032,-0.299391,0.292808,-0.105843,-0.146819,0.197100,0.159704,-0.025862,-0.008598,0.223723,-0.242813,0.058566,-0.243920,0.166734,0.047456,0.440825,0.093722,-0.214153,-0.138604,0.207981,-0.083896,0.141727,0.607341,-0.386905,-0.297939,-0.027184,0.432508,0.020120,-0.146683,0.086570,0.156468,-0.040615,0.401795,0.012370,-0.100875,0.027533,-0.017167,-0.005731,-0.536595,0.090405,-0.040659,0.021591,-0.437669,0.325724,-0.065999,-0.017539,0.183295,-0.318695,0.216651,0.263196,0.274344,0.351484,-0.182551,-0.160330,-0.441718,0.317181,0.332687,0.014004,-0.163949,0.390599,0.017515,-0.343707,-0.186796,0.027607,-0.081344,0.036998,0.349661,0.019821,-0.315482,-0.153592,-0.443675,0.026284,-0.114553,-0.186270,-0.041811,-0.389949,-0.090490,-0.267668,-0.147401,-0.095268,-0.260517,0.091099,0.335714,-0.216469,0.935911,-0.531753,0.137227,0.550264,0.245755,-0.337259,0.656787,-0.032187,-0.000236,-0.069827,0.229931,-0.371905,0.063849,0.369714,0.385712,0.410657,0.138920,-0.127619,-0.476074,0.318255', '27602116', '1302661', '1307146', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3119246', '游戏', '剧情', '闵熙道（申河均 饰）是一位名不见经传的街头画家，他和女友恩雅（李恩成 饰）相恋多年，将恩雅视作自己最重要的人。这样一个不起眼的小人物，在某一日却意外接到了一通诡异的来电，电话那头的，是在金融界里呼风唤雨的富豪姜鲁植（边熙奉 饰），后者以高额奖金为诱饵，邀请闵熙道前往他的别墅参加一个游戏。就这样，闵熙道被卷入了一场精心策划的阴谋之中，毫不意外的输给了姜鲁植，而他所要付出的代价，就是失去所有，包括自己作为一个独立的人的权利。陷入绝望之中的闵熙道遇见了叔叔泰锡（孙贤周 饰），两人找到了姜鲁植的妻子慧琳（李慧英 饰），向她请教反败为胜的方法。©豆瓣', '申河均', '尹仁灏', 7.1, 5750, 'tt1310501', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1023828490.jpg', 1.3, 6.5, 39.9, 38.6, 13.7, '0.131270,0.288657,-0.542749,0.967000,-0.342412,-0.152798,1.020267,0.092045,-0.408736,-0.171496,0.345740,1.083441,-0.064570,0.173882,0.367113,0.128630,-0.007228,-0.784694,-0.126228,-0.196231,-0.156960,-0.456872,-0.308244,-0.210922,-0.081350,-0.049106,0.459619,0.204449,-0.164132,0.466348,0.493850,0.384854,0.151775,0.482874,-0.212203,0.112219,0.048136,0.059871,-0.148749,0.284075,-0.179011,-0.371384,-0.194453,0.370728,-0.170232,0.428573,0.465913,-0.377009,-0.193992,-0.140142,0.477429,-0.481121,-0.178619,-0.027904,0.119181,0.031420,0.389312,0.175628,-0.454215,0.288536,0.411722,0.055733,-1.036929,-0.199370,0.101974,0.246978,-0.648178,0.579475,-0.033994,-0.328378,0.068917,-0.415376,0.103898,0.224569,0.097182,0.316164,-0.209988,0.061572,-0.391109,0.388808,0.698303,-0.066162,-0.085423,0.284529,0.000449,-0.413965,0.131527,-0.213530,-0.483005,-0.014467,0.404741,-0.317842,0.086405,0.055440,-0.532077,0.007519,-0.115495,-0.241471,-0.095770,-0.580809,-0.173375,-0.478704,-0.164780,-0.183487,-0.417257,0.208560,0.132951,-0.251647,0.686382,-0.786793,0.079138,0.483890,0.243786,-0.384841,0.692197,0.175282,0.175191,-0.309008,-0.064346,-0.124869,-0.075259,0.339471,0.107242,0.195896,0.028448,-0.271080,-0.327241,0.199913', '34890458', '26884422', '3785918', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3120171', '苏默斯小镇', '剧情', '来自诺丁汉的男孩托莫（Thomas Turgoose 饰）只身来到英国伦敦，却遭到抢劫。无家可归的托莫偶然结识年纪相仿热爱照相的波兰移民马尔克（Piotr Jagiello 饰），他总算找到暂时的落脚之处。马尔克的爸爸白天工作，这段时间两个好朋友四处游荡，或帮助托莫偷衣服，或者与马尔克心仪的咖啡馆女郎玛丽亚（Ireneusz Czop 饰）聊天玩笑，或从好心的杂货店老板格莱姆（Perry Benson 饰）那里赚点小钱。生活无聊，却又无忧无虑。当然这一切马尔克的父亲全不知情，直到他某天他回家撞见两个朋友打闹的场面……本片荣获2009年伦敦影评人奖英国年度最佳青年演员奖（Thomas Turgoose）。©豆瓣', 'Thomas Turgoose', '西恩·迈德斯', 7.9, 7950, 'tt1172206', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1163862485.jpg', 0.3, 1.4, 23.3, 52.5, 22.5, '0.171045,-0.131151,-0.349908,0.260925,-0.049796,-0.514160,0.592248,0.141136,-0.290399,-0.341177,0.150860,0.729078,-0.089710,0.460414,0.367441,0.048240,-0.513024,-0.423923,0.324586,0.033903,-0.093546,-0.184348,-0.258695,-0.203802,-0.244349,0.049364,0.267297,0.008624,0.105646,0.549302,0.265898,0.305965,-0.186482,0.262148,-0.399527,-0.297510,0.286471,0.216157,-0.405198,0.119130,-0.390717,-0.242864,-0.137715,-0.203393,0.458441,0.304096,0.730523,-0.091544,0.057993,0.074130,0.482604,-0.100491,0.226527,-0.116226,0.175735,-0.018905,0.462703,-0.256061,-0.151398,0.077013,-0.127741,-0.239074,-0.140524,0.107146,0.412376,-0.050968,-0.500871,0.428005,0.164528,0.007185,-0.019913,-0.172041,0.213690,0.249302,0.087717,0.183634,0.248336,0.108422,-0.408916,0.143458,0.473880,0.007603,0.055818,0.241659,-0.213671,-0.374620,0.425655,-0.027019,-0.449732,0.095753,0.127929,-0.465401,0.100526,0.045517,-0.652392,-0.043463,0.003105,-0.113112,0.078716,-0.143614,-0.079852,-0.858268,0.239112,-0.189375,-0.182206,0.034224,0.253776,-0.082621,0.554984,-0.524440,0.099877,0.632336,0.171734,-0.407906,0.667099,-0.003421,0.291734,-0.229574,-0.282901,0.347520,0.224557,0.109805,-0.025456,0.060484,-0.116012,-0.225406,-0.201887,0.341196', '3147969', '1484091', '3326747', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3120336', '偷偷爱着你SP', '喜剧', '本片是根据畅销漫画改编剧《花样少年少女》大受好评之后推出单集SP，还特别收录樱咲学园的毕业典礼。优秀跳高选手佐野泉（小栗旬 饰）为救被不良份子掳走（堀北真希 饰）割伤了韧带，自此不再跳高。为了补偿自己令泉不再跳高，为了想更了解泉和帮助泉再次跳高，瑞稀女扮男装转校到泉就读的日本樱咲私立高校。就此展开了一段啼笑皆非的校园趣事。SP的故事从瑞稀进入学园半年后开始。当时整个学园都沉浸在情人节的欢乐气氛中，泉（小栗旬 饰）和秀一（生田斗真 饰）开始回忆暑假最后一个星期发生的事情。就是TV版中没有提到的，第七集夏季合宿和第八集第二学期开始之间发生的故事。©豆瓣', '堀北真希', '松田秀知', 7.5, 17434, 'tt1619136', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1612136160.jpg', 0.5, 3.9, 35.8, 40.3, 19.6, '0.213068,-0.015214,-0.383881,0.411719,0.421831,-0.081402,0.275014,-0.182606,-0.164902,-0.554276,-0.149208,0.440690,-0.568493,0.439350,0.459807,-0.093638,-0.286931,-0.989216,-0.134026,-0.225868,-0.279882,-0.334923,0.300738,0.329430,-0.154773,-0.425087,0.799325,0.038799,-0.289107,0.558527,0.327774,0.289734,0.071403,-0.161594,-0.065390,-0.013391,0.123584,0.487690,-0.083341,0.277847,-0.011154,-0.419827,-0.318547,0.049314,0.384997,0.280072,0.839119,0.065076,-0.165997,-0.099216,0.605839,-0.083400,-0.390064,-0.082864,0.454665,0.049805,0.404779,0.303712,-0.197363,0.099937,0.103279,-0.476359,-0.294090,0.094292,0.230935,0.172435,-0.150571,0.287556,-0.003445,-0.096179,0.471829,0.028154,-0.039751,0.469120,0.503376,0.103946,-0.176730,0.058120,-0.076197,0.570022,0.812920,-0.193005,-0.125056,0.405592,0.145877,-0.304103,-0.090613,0.012224,0.153554,0.416483,-0.022644,0.089402,0.025191,0.242636,-0.527523,-0.143318,0.143763,-0.447311,0.310907,-0.222117,-0.164312,-0.648896,0.112170,0.053978,-0.020895,0.037439,0.212074,-0.385709,0.766808,-0.873958,0.054201,0.257399,0.126934,-0.350217,0.485198,0.116747,-0.039655,-0.209466,0.127192,0.059936,-0.136700,0.164325,0.005766,0.454053,0.011979,-0.581127,-0.486866,0.309283', '5403927', '1826173', '1316589', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3120852', '影子写手', '剧情', '他（伊万·麦格雷戈 Ewan Gordon McGregor 饰）是一个影子写手，一如其代号“Ghost（鬼魂）”一般，他深深躲在幕后，为各行各业的名流捉刀撰写回忆录。一日，鬼魂接到一项新的任务，即帮助前英国首相亚当·朗（皮尔斯·布鲁斯南 Pierce Brosnan 饰）的回忆录作润饰工作。此前，该书由亚当·朗在任期间的助手迈克·麦卡拉负责，然而麦卡拉却神秘自杀。看在丰厚报酬的份上，鬼魂接受了这项工作。在写书过程中，亚当受到战争罪的指控，政治风暴近在咫尺。而鬼魂也开始有意探知亚当不为人知的过去以及麦卡拉死亡的原因，却不知此举将他引入险途……本片改编自罗伯特·哈里斯（Robert Harris）的小说《枪手》，并荣获2010年柏林国际电影节银熊奖最佳导演奖。©豆瓣', '伊万·麦克格雷格', '罗曼·波兰斯基', 7.5, 63218, 'tt1139328', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p574855756.jpg', 0.4, 2.2, 31.1, 53, 13.3, '0.022641,0.129846,-0.536281,0.771621,0.198862,-0.053058,0.575656,0.166835,-0.225330,-0.413801,0.039175,0.744149,-0.182632,0.009524,0.427366,-0.044262,-0.298146,-0.592748,-0.200435,-0.131082,-0.159239,-0.516471,-0.241723,-0.305192,-0.196348,-0.270899,0.460842,0.111573,-0.127591,0.308591,0.528485,0.475616,-0.061171,0.300221,0.203836,-0.033248,0.340504,-0.168593,-0.162765,0.168587,0.186248,-0.353852,-0.261993,0.022452,0.081974,0.273565,0.468300,-0.335309,0.018016,0.002118,0.460783,-0.254107,0.116621,-0.120216,0.328248,-0.090416,-0.197562,0.260379,-0.106169,0.271992,-0.093647,-0.226217,-0.811693,-0.267082,-0.050597,0.364590,-0.284992,0.358938,-0.339729,0.393559,-0.334006,-0.223096,-0.029409,0.037786,0.248580,0.156142,0.037176,0.004621,-0.381809,0.446301,0.129083,0.056553,-0.245261,0.199489,-0.478286,-0.666358,-0.157200,-0.079881,-0.326435,-0.020964,0.394239,-0.022848,-0.080657,0.265154,-0.384942,-0.201436,-0.177148,-0.197914,-0.118213,-0.270995,-0.181065,-0.724777,-0.000802,0.159223,-0.116382,0.026063,0.066863,-0.473232,0.576138,-0.574100,0.319477,0.775457,-0.071778,-0.129053,0.650850,0.104365,0.325205,-0.300386,-0.186145,0.294221,0.345386,0.367434,0.210064,0.070331,0.158005,-0.343785,-0.141601,0.419859', '1293433', '34890458', '4206468', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3121610', '我的唯一', '剧情', '本片根据美国演员乔治·汉密尔顿（George Hamilton）的亲身经历改编而成。1953年，安·德弗罗（芮 妮·齐薇格 Renée Zellweger 饰）的丈夫丹·德弗罗（凯文·贝肯 Kevin Bacon 饰）因写出《我的唯一》这首歌曲一炮而红，此后招蜂引蝶，被捉奸在床。安一怒而走，带着儿子罗比（马克·兰道尔 Mark Rendall 饰）和乔治（罗根·勒曼 Logan Lerman 饰）离开了纽约，辗转波士顿、匹兹堡、圣路易斯，直到加州洛杉矶。安一路上不停地会见旧友，本打算找到一个合适的对象，为自己与孩子们提供一个美好的未来，直到储蓄用光，捉襟见肘。一路上乔治都以为母亲最终会因经济问题向父亲低头重返纽约，直到他终于了解了母亲的决心，也在意外中发现了自己的演艺天赋。本片获柏林国际电影节人道主义特别奖，并被提名最佳电影金熊奖。©豆瓣', '蕾妮·齐薇格', '理查德·隆克瑞恩', 8, 6439, 'tt1185431', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p475206911.jpg', 0.4, 0.9, 19.6, 55.9, 23.1, '-0.102795,0.085008,-0.673540,0.721216,0.430810,-0.613942,0.450570,0.030888,-0.422911,-0.421784,-0.340002,0.704991,-0.360039,0.271430,0.536079,0.040738,-0.515285,-0.678237,0.054001,-0.195026,-0.117055,-0.510519,-0.337410,-0.301942,-0.125528,-0.276439,0.357652,0.174500,0.105013,0.482544,0.471334,0.398750,0.170004,0.126853,0.138551,0.185705,0.180742,-0.166029,-0.285774,0.367536,0.360309,-0.146699,-0.198224,0.117199,0.364811,0.413171,0.654987,-0.162639,0.189025,-0.143928,0.373232,-0.190739,0.233815,0.014819,-0.120923,-0.149965,0.197321,0.344700,-0.126227,0.246322,0.183015,-0.219322,-0.560123,0.037958,0.114726,0.007042,-0.535362,0.357799,-0.213437,0.085283,-0.195933,-0.219057,0.156496,0.464409,0.196500,0.307372,-0.120784,0.227010,-0.330058,0.236799,0.326205,-0.101603,-0.059093,0.437069,-0.100673,-0.545311,0.040634,-0.172359,-0.456937,0.039994,0.364890,0.059213,0.214546,-0.010128,-0.298691,-0.142936,-0.390433,-0.180054,0.002501,-0.202887,0.240101,-0.759834,0.117807,-0.220054,-0.296462,-0.116082,-0.267125,-0.209882,0.579795,-0.285791,0.159429,0.514904,0.252204,-0.385158,0.575225,-0.028333,0.201672,-0.417107,-0.217837,0.440521,0.021600,0.177275,0.125884,0.018698,0.095002,-0.268359,-0.199279,0.420426', '2075345', '1829654', '1484091', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3121972', '产前阵痛', '语言:', '在出版社工作的西娅（琳赛·洛翰 Lindsay lonhan 饰）饱受苛刻的上司杰瑞（克里斯·帕内尔 Chris Parnell 饰）刁难，一次在女厕所和同事抱怨时却被隔壁的上司听到，得罪上司的西娅面临被炒鱿鱼的危险，情急之中，她谎称自己怀孕才幸免于难。从此西娅的生活发生了翻天覆地的改变，周围的同事开始在各方面给予她照顾，西娅很享受这种生活。为了让这种情况得以继续保持，西娅决定开始了假装怀孕十个月的各项准备。这时，苛刻的上司忽然出差，西娅在和男朋友感情出现问题之时，新任的代理上司和西娅相互萌生好感。谎言终有被揭穿的那一天，西娅将如何面对工作和情感的双重问题？©豆瓣', '琳赛·洛翰', 'Laura Shapiro', 5.9, 8597, 'tt1231287', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p899508597.jpg', 3, 18.1, 61.4, 14.4, 3.1, '0.483116,0.154515,-0.938838,0.514838,-0.115723,-0.182545,0.711761,0.267033,-0.577325,-0.517469,0.043019,0.748201,-0.570382,0.343192,0.299154,-0.111822,-0.490479,-0.875418,0.299719,0.253358,-0.312565,-0.350483,0.124875,-0.210656,-0.455394,-0.264755,0.550114,0.016392,-0.184027,0.162816,0.035938,0.588109,0.240558,0.645696,0.071306,0.051517,0.210201,-0.103896,-0.338765,0.217617,0.415136,0.068785,-0.108377,0.351804,0.392887,0.542740,0.703290,-0.262816,-0.615942,0.051689,0.424693,-0.414915,0.278006,0.283648,0.449081,-0.000086,0.209382,0.321060,-0.525560,0.142713,0.062097,-0.047640,-0.660414,0.021565,0.029046,0.139759,-0.461297,0.465687,-0.058134,-0.246887,0.193729,-0.128553,0.065600,0.766466,0.104419,0.490453,-0.350708,0.124328,-0.298251,-0.156021,0.655975,0.058226,-0.207366,0.331419,-0.209736,-0.093109,-0.049911,-0.173424,-0.269307,-0.188419,0.015400,0.107480,-0.338180,0.283217,-0.592981,-0.197007,-0.299208,-0.297801,-0.085851,-0.913566,-0.332173,-0.502965,0.073639,-0.263696,-0.448976,-0.050132,0.209454,-0.369250,0.309674,-1.120171,0.083967,0.285499,0.562814,-0.709402,0.365807,0.312021,0.155259,-0.354112,-0.171851,0.442026,0.018155,0.141561,0.123572,0.042422,0.410759,0.083482,-0.217035,0.416235', '1301022', '30345227', '1949320', '1886896');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3126138', '猛男诞生记', '喜剧', '在一个女权盛行的村落里，性格暴戾的卞强衰（奉太奎 饰）却被女性们公开的鄙视，原来一切只因为他的那话儿微小，相反他的哥哥强木在村中颇有人缘，强木对弟弟心有愧疚，原来兄弟俩靠买年糕为生，某次在街上，强木因为自己的疏忽导致弟弟丧失了那话儿。不久，村中来了一名女子月石（金新雅 饰），月石早年被日本人掳去，虽然风情万种可是头脑不大清楚。村中的登徒子们日日以偷窥月石为乐，不忍月石为难的强木将她娶回家，做了强衰的嫂子。某天夜里，强衰救下了一老一少，老人出于感激，将“天下大将军”神像下面神酒的秘密告诉了强衰，强衰饮酒后，迎来了汹涌澎湃的二次发育，这使他的人生，甚至全世界的历史都发生了剧烈的变化……©豆瓣', '奉太奎', '申汉率', 5.7, 13824, 'tt1433775', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2207669149.jpg', 8, 24.7, 47.8, 13.8, 5.7, '0.052510,0.064048,-0.710058,0.341366,-0.222597,-0.137781,0.488480,0.036241,-0.753608,-0.063386,0.124198,0.483891,-0.263954,0.138856,0.242775,0.095078,-0.058561,-0.433770,-0.073122,-0.427050,-0.312578,-0.183850,-0.092890,-0.158255,-0.242763,-0.246449,0.257713,0.165907,0.004231,0.320235,0.242100,0.199446,0.241793,0.494361,0.040078,0.092670,-0.189673,-0.035624,0.140275,-0.039405,-0.056743,-0.319239,-0.148937,0.078946,-0.004419,0.381492,0.727659,-0.363251,-0.400454,-0.338787,0.507326,-0.023833,-0.084887,0.105954,0.346223,0.173109,0.063202,0.139782,-0.204863,-0.343284,0.198519,-0.097043,-0.371641,0.255832,0.135322,-0.125744,-0.678388,0.516001,0.137565,-0.047887,-0.103551,-0.234066,0.219896,0.251926,0.073486,0.402170,-0.176094,0.069949,-0.429029,0.216264,0.540814,0.118873,-0.177686,0.131385,-0.151523,-0.242757,-0.089204,-0.151238,-0.333940,0.031480,0.256409,0.086037,-0.352416,0.155671,-0.334274,0.062053,0.046431,-0.063668,0.064372,-0.355785,-0.436557,-0.248878,0.017940,-0.407700,-0.082049,-0.058936,0.309620,-0.040517,0.791420,-0.677146,0.247369,0.471635,0.384076,-0.446675,0.638415,-0.080361,-0.012561,-0.099951,-0.369789,0.167742,-0.043127,0.120192,0.348811,0.344537,-0.139361,0.111811,-0.246615,0.290730', '3445516', '5262027', '4004731', '1308609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3126187', '死神的十字路口', '剧情', '影片由四个小故事组成。因为车祸而行动不便的女孩通过短信与一素未谋面的男孩交往甚密，她将自拍发给男孩，并向男孩索要照片，手机嗡嗡的震动着，男孩发给她的照片上，女孩看到的究竟是什么？男孩生来性格内向懦弱，这成为了同学欺负他的最佳理由。一开始只是玩笑般的打闹，但逐渐的，欺负步步升级。男孩忍无可忍，决定冒着极大的危险，通过降头术将欺负他的人一一杀死。一群朋友外出露营，夜里，无聊的他们以讲恐怖故事为消遣，却自己被自己吓到，抢着要睡中间最有安全感的位置。第二天，睡在中间的男孩意外溺水身亡，按照恐怖故事所说的，今晚，已经死去的他会从地狱归来。飞机上搭载着王妃的遗体，这次航班的任务就是护送遗体回国火化。空姐心里惴惴不安，没想到恐怖的事情真的发生了，遗体离奇消失，在机舱封闭的空间里，在本该空无一人的厕所中，传来了令人毛骨悚然的声音。©豆瓣', '赖拉·邦雅淑', '班庄·比辛达拿刚', 7.4, 45911, 'tt1292575', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p768892731.jpg', 0.7, 4.4, 34.4, 45.3, 15.2, '0.256881,0.024659,-0.727613,0.452393,-0.214554,-0.003002,1.009351,0.075669,-0.456490,-0.054237,0.237241,0.732288,-0.312489,0.467093,0.288866,0.208221,-0.238840,-0.528317,-0.255365,-0.140397,-0.574552,-0.519745,-0.007924,-0.292165,0.198452,-0.341528,0.417216,-0.066308,-0.307732,0.393628,0.364742,-0.048969,-0.315690,0.628799,-0.387456,-0.170617,-0.149283,0.075808,0.164396,0.093566,-0.018366,-0.330211,-0.086873,0.115415,-0.249975,0.334396,0.685904,-0.377892,-0.278957,-0.000977,0.450396,-0.298256,-0.197680,-0.071940,0.321651,0.193187,0.412269,-0.030612,-0.092726,-0.056238,0.109156,0.045948,-0.472778,0.117736,-0.000817,0.113142,-0.515078,0.228987,-0.093101,0.097596,0.490262,-0.344607,0.445673,0.150491,-0.029321,0.593737,-0.335686,0.062092,-0.429213,0.081336,0.562824,-0.052603,-0.178011,0.395312,-0.060125,-0.256596,0.104139,-0.087880,-0.497680,0.117160,0.411455,-0.098493,-0.346978,-0.014920,-0.357882,0.002404,0.020179,-0.216447,-0.210208,-0.424278,-0.368538,-0.352116,-0.165213,0.057434,-0.270519,0.183388,0.047579,-0.185327,0.792981,-0.569701,0.259096,0.745638,0.161004,-0.125793,0.527903,0.030017,-0.020131,-0.140522,0.001042,0.040959,0.079847,0.356763,0.137023,0.334104,-0.280349,0.021982,-0.669413,0.418012', '21619567', '1296534', '1783772', '1292217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3126196', '十全九美', '喜剧', '木匠神人鲁班留下一本秘笈《缺一门》，根据书里的提示制造木艺，能有惊人效果；然而此书却有一副作用，即拥有此书者，总不能十全十美，永远有不可预料的祸处在等待。若干年前，“鲁班传人”江南鹤带着这本秘笈出宫，凭着书内记载制造出快乐摇摇椅——让人返老还童。这引起了乾柜女老板和她骈头小六的歹心，他们谋害了江南鹤，并夺走了《缺一门》。明朝太子朱笑天（立威廉 饰）一心成为鲁班那样的顶级木匠，微服出宫寻找《缺一门》，结识了江南鹤的师妹唐小蝶（黄奕 饰）。当他们发现江南鹤已经被老板娘杀害后，一路追寻老板娘到龙门镇——那里正准备着热闹的抛绣球之夜，龙门镇的名门望族南宫家正在招婿，乱打乱撞的老板娘和小六成为了京城艺人，而朱笑天更是接到了绣球。各路人马一起上演这场缤纷闹剧。为了《缺一门》，大家都在拼命用力；然而，当它到手后才明白，自己最想得到的，恰恰就是永不能得到的。©豆瓣', '立威廉', '王岳伦', 5.1, 107970, 'tt6448922', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2097938328.jpg', 13.5, 32, 41.9, 10.1, 2.5, '0.305731,0.111332,-0.570874,0.448622,0.223077,-0.211105,0.329099,-0.051930,-0.381241,-0.338065,0.108097,0.523349,-0.169899,0.193392,0.169418,0.010881,-0.020788,-0.393270,0.100891,-0.318492,-0.147111,-0.167312,-0.157326,-0.087631,-0.327173,-0.110824,0.396322,0.205839,-0.255585,0.334133,0.189483,0.071327,-0.025811,0.103107,-0.441045,0.139038,-0.179694,0.149616,-0.174579,0.365287,0.103549,-0.177091,-0.303286,0.090765,-0.009815,0.072055,0.315613,-0.468124,0.002520,-0.124711,0.229597,-0.025159,-0.144984,-0.110955,0.151600,0.074888,0.166438,0.103009,-0.270341,-0.048078,0.212761,-0.171796,-0.705373,-0.046286,0.264097,0.057300,-0.242371,0.117700,-0.010927,-0.117316,-0.062967,-0.534506,0.339881,0.340750,0.281948,0.123210,-0.218129,-0.099725,-0.790817,0.326133,0.385878,-0.043167,-0.069519,0.305032,0.205649,-0.268614,0.234961,-0.557956,-0.214011,0.098074,0.610328,0.186768,0.110452,-0.135477,-0.188058,0.030902,-0.081003,-0.131488,0.174244,-0.223318,-0.155945,-0.386163,-0.013061,-0.105032,-0.250908,0.105226,0.317917,-0.469251,0.739670,-0.706030,0.376565,0.360414,-0.067234,-0.510491,0.526061,-0.127323,0.002878,0.024920,-0.374347,-0.136630,0.102963,0.531042,0.044586,0.199176,0.001314,-0.253819,-0.232820,0.399955', '1438924', '1793491', '1877596', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3130180', '花吃了那女孩', '爱情', '本片由四段感情故事“在一起很快乐”“不在一起很快乐”“不在一起不快乐”“在一起也不快乐”独立交错的演绎爱情的味道。《如果南国冰封了》中刚分手的小捷（辛佳颖饰）独自去台北疗伤，与高中就暗恋她的小Pon（陈泱瑾饰）重新开始，两个女孩在生活琐事中既有甜蜜也有争吵；《看不见攻击的城市》讲述完美主义的女料理师U（张榕容饰）被成熟女编辑（魏如萱饰）勾引，最终又回归一个人生活的故事；《梦见相反的梦》里执着爱情却要完成结婚生子社会责任的Summer（高伊玲饰）与痴情一片的女友Spancer（吴立琪饰）相约十年后再见，三年后Summer带着孩子终与Spancer重逢；《像花吃了那女孩》花心的Ricky（林嘉欣饰）周旋在前女友与现任女友（王心凌饰）之间，状况连连。故事中的女主人公都会收到寄给Candy Rain的无名包裹，打开后又是什么呢？©豆瓣', '陈泱瑾', '陈宏一', 6.1, 50224, 'tt1252557', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2506992397.jpg', 4.6, 18.8, 50.3, 20.6, 5.8, '0.168960,-0.147117,-0.534787,0.623604,-0.224488,-0.160436,0.947727,0.171044,-0.214132,-0.132058,-0.053194,0.619478,-0.194484,0.396088,0.195005,0.070434,-0.346965,-0.681258,0.079775,-0.249096,-0.315588,-0.395179,0.088804,-0.085745,-0.197627,-0.199526,0.828224,-0.130717,0.093197,0.494060,0.352020,-0.069815,-0.392330,0.540860,-0.423052,0.074154,0.045440,0.539161,-0.377783,0.087601,-0.008045,-0.175092,-0.006791,-0.037167,0.056544,0.030899,0.849050,-0.118122,0.050723,-0.090523,0.256866,0.008074,-0.177368,-0.017069,0.223256,0.060368,0.621873,0.285573,-0.250092,-0.132606,-0.018607,-0.237012,-0.457455,0.065424,0.400771,0.207697,-0.539241,0.558157,0.164956,0.013290,0.421783,-0.068986,0.118075,0.431146,0.446420,0.631375,-0.022441,0.045951,-0.397688,0.404506,0.952218,-0.031480,-0.195660,0.669818,-0.190359,-0.199658,-0.068577,0.080620,-0.675776,-0.115259,-0.172621,0.110266,-0.343964,0.470200,-0.697076,0.172649,0.171248,0.256966,0.278698,-0.644676,-0.082171,-0.409068,-0.265999,-0.498322,-0.387507,0.141835,0.126772,-0.343325,0.930135,-0.980929,0.281166,0.362200,0.427187,-0.480934,0.824399,0.578464,0.035529,-0.358858,0.273967,0.363108,-0.207673,0.005817,0.171692,0.456826,-0.149096,0.218779,-0.708605,0.642408', '2081098', '6963575', '3445516', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3134061', '友谊我和你', '爱情', '一直觉得学校生活百无聊赖的August（马里奥•毛瑞尔 Mario Maurer 饰），遇上了言语极少富有神秘气息的转校生June。对 June一见钟情的August，想要接近她，却不知如何是好。不知怎样表达其爱意的August适得其反，对 June的作弄使得其很反感August。一次偶然的机会，August知道了June沉默感言背后的原因：原来June的妈妈因为车祸丧失了听力，只能用手语表达。于是August开始为June学起了手语。两人在互相理解中开始对对方互生好感，一场校园恋爱似乎即将拉开序幕。但是双方的父母却因为各自的原因要换工作，而August和June也不得不因此换学校，相约在离开前再见对方的二人却又阴差阳错的错过彼此。被分开的二人依然记挂着彼此，为了见到对方而相互努力着，但这段青涩的爱总是被天意捉弄，最后知道真相的他们只能唏嘘长叹。©豆瓣', '马里奥·毛瑞尔', '皮查农·塔玛杰拉', 6.3, 5716, 'tt1842367', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p847191403.jpg', 2.1, 14.4, 57.6, 20.2, 5.7, '0.487312,0.028489,-0.819579,0.514379,-0.000010,-0.305554,0.661582,-0.174307,-0.566327,-0.282215,0.095580,0.686966,-0.356622,0.305307,-0.001013,-0.193533,-0.076922,-0.691335,0.247494,-0.120183,-0.086691,-0.512045,-0.183326,0.098964,-0.344452,0.097590,0.554784,0.164254,-0.240432,0.599365,0.421857,0.324519,0.066149,0.683704,0.139871,-0.081409,-0.264585,0.332844,-0.385792,-0.196929,0.451506,-0.334796,-0.401519,0.375414,-0.192223,0.480925,0.700588,-0.124451,-0.376207,0.115184,0.467469,-0.333161,0.042126,0.327605,0.293972,0.206637,0.373461,0.008120,0.043890,0.000136,-0.071392,0.352211,-0.659412,0.225955,0.044583,0.052164,-0.398478,0.603324,0.049854,-0.300778,0.019132,-0.433634,0.111556,0.576973,0.595598,0.345412,-0.534984,-0.157194,-0.322588,-0.272940,0.854385,0.040070,-0.231884,0.664746,-0.234596,-0.444172,0.012028,-0.184361,-0.456619,0.035188,-0.056325,0.627477,-0.227453,0.111122,-0.558302,0.040468,-0.158232,-0.035380,0.040654,-0.913698,-0.070444,-0.340930,-0.344326,-0.490894,-0.470495,0.070474,0.049079,-0.259550,0.500740,-1.226914,0.133319,0.539659,0.378982,-0.647295,0.484705,0.608211,0.031982,-0.339285,-0.090668,0.324646,-0.254854,0.018962,0.321622,0.204735,0.131323,0.099374,-0.554856,0.352045', '1301022', '35030151', '30345227', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3134345', '咕咕是一只猫', '剧情', '东京的吉祥寺一带，绿意昂然，安静怡人，时间仿佛停滞。这个关于爱的故事就发生在这里。小岛麻子（小泉今日子 饰）是个单身的女性漫画家，居住在吉祥寺，由于赶稿而忽略了爱猫沙巴的身体，导致爱猫因病死去而不自知。自责的她处于静默的情绪中，无法再画出漫画。身为她助手的直美（上野树里 饰）担心小岛麻子的状况，直至麻子在宠物店被一只小猫吸引，取名“咕咕”，重新振作。在吉祥寺的公园里，咕咕追逐母猫，人们欣赏樱花，天地万物自然地共处一起，实习医生青自（加濑亮饰）闯入了麻子的生活，当生活的趣味遍布四周时，麻子的身体却出现状况……自少女时代起就立志画出令人感觉幸福的漫画的麻子，真正寻找到属于自己的幸福了吗？“咕咕”这个名字也许是她的最佳回答。©豆瓣', '小泉今日子', '犬童一心', 7.4, 16292, 'tt1255872', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p724138138.jpg', 0.5, 3.5, 37.7, 43.6, 14.7, '0.255250,0.070320,-0.629116,0.372309,-0.042699,-0.319025,0.714228,0.361971,-0.329605,-0.209165,0.321673,0.351836,-0.060695,0.382995,0.086177,0.203116,-0.066307,-0.662781,0.015906,-0.071397,0.009698,-0.021685,-0.141183,-0.203404,-0.152044,-0.219200,0.579743,0.088716,-0.089177,0.563699,-0.002827,0.194110,-0.107451,0.243040,-0.063326,0.077014,0.039964,-0.038698,-0.049924,-0.010714,-0.123276,-0.351842,0.112132,0.041731,-0.011195,0.291105,0.865900,-0.403011,-0.438632,-0.094972,0.314188,-0.143868,-0.156537,0.298827,0.273383,-0.246477,0.136276,-0.236325,-0.387387,0.129809,-0.003226,0.112549,-0.515095,0.130164,0.054655,0.702591,-0.115060,0.497621,0.019549,-0.514367,0.248266,-0.366490,0.313831,0.051687,0.204998,0.303802,-0.261052,0.329315,-0.205885,0.052270,0.447537,-0.059245,-0.061635,0.535007,-0.413649,-0.331387,-0.078694,-0.050056,-0.381926,-0.163389,-0.056246,0.216219,-0.388350,0.127454,-0.515446,0.116280,0.100782,-0.264370,-0.051054,-0.188643,-0.457839,-0.399002,-0.042255,-0.271369,-0.134022,-0.077186,0.058047,-0.152726,0.599692,-0.773761,0.156217,0.644735,-0.052105,-0.073700,0.569655,0.039736,-0.104352,-0.161541,0.090072,0.440173,-0.040140,0.419664,0.029243,0.246511,-0.221365,-0.060010,-0.653841,0.676373', '10467779', '1417036', '24839498', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3135483', '严肃的男人', '剧情', '拉里·戈普尼克（迈克尔·斯图巴 Michael Stuhlbarg 饰）是美国明尼苏达州双城区某大学的物理教授，学校正决定是否颁发给他终身教授资格时，一位韩国学生向拉里抱怨考试评分不公，遭拒绝后则向拉里行贿。与此同时，拉里的妻子朱迪斯（莎瑞·莱尼克 Sari Lennick 饰）说她爱上了鳏夫塞·艾伯曼（弗雷德·迈拉麦德 Fred Melamed 饰），要求离婚。不仅如此，拉里的无业神经质哥哥亚瑟（理查德·坎德 Richard Kind 饰）越来越成为负担，儿子的犹太成人礼在即，女儿偷钱准备为鼻子做整容手术，而一封匿名信更是要将他的前程毁掉。焦头烂额的拉里求助于多位犹太牧师拉比，但信仰便能帮他走出困境吗？本片获英国电影电视协会奖最佳原创剧本提名及金球奖音乐剧和喜剧类最佳男主角提名（迈克尔·斯图巴）。©豆瓣', '迈克尔·斯图巴', '伊桑·科恩', 7.4, 21826, 'tt1019452', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1077993235.jpg', 1.2, 4.6, 33.4, 44.6, 16.3, '-0.014339,-0.108940,-0.241055,0.589912,0.106750,-0.613902,0.217323,0.364216,-0.185782,-0.152436,0.080930,0.819145,-0.094108,0.202736,0.321241,0.117138,-0.485311,-0.735902,0.100783,-0.217183,-0.110925,-0.595262,-0.002906,-0.298444,-0.064836,-0.426529,0.516484,-0.444341,0.018726,0.213728,0.398718,0.401059,0.334460,-0.179294,0.097741,0.242915,0.429329,-0.220429,-0.376135,0.416316,0.209984,0.141458,-0.289267,0.025982,0.390548,0.288736,0.442080,-0.100278,0.179313,-0.211985,0.599217,-0.410657,0.213005,0.332416,0.104097,0.003516,0.284263,0.222566,0.046570,-0.077892,0.169130,-0.276045,-0.504482,0.203349,0.018123,0.226789,-0.312445,-0.003092,-0.477049,0.115149,0.107302,-0.165316,-0.123427,0.080888,0.196772,0.286462,-0.076305,0.027813,-0.250096,0.405406,0.045643,-0.121659,0.068536,0.065631,-0.175770,-0.314468,0.029988,-0.113656,-0.724387,0.008798,0.364302,-0.161879,0.402117,0.160541,-0.182214,-0.308700,-0.399201,-0.244946,-0.009240,-0.152053,0.037661,-0.656117,0.157494,0.310110,-0.162500,-0.082812,0.326949,-0.283265,0.536202,-0.281238,0.267568,0.525887,0.308092,-0.324786,0.663571,0.141067,0.168492,-0.213933,-0.168098,0.261345,0.128964,0.058462,0.059358,0.017322,0.300530,-0.496605,-0.027336,0.489753', '1297920', '1829654', '1298616', '3275168');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3136488', '大搜查之女', '喜剧', '33岁还未结婚的香港女警司徒慕莲（郑秀文饰）一直为自己的婚事发愁。男友十年前的承诺，现在成了她与同事间的笑谈。一日，走私集团的头领霍青松（陈奕迅饰）的儿子被绑架，司徒慕莲奉命处理这宗案件。但霍青松一家为避免因走私之事被警方控告，处处表现出不合作的态度，而此时司徒慕莲发现自己有了身孕。黑白两道在一间大屋下貌和神离，霍家上下各自心怀暗计，同时，大陆警方也传来了联合破案的消息。作为“剩女”的司徒慕莲、作为警察的司徒慕莲，她到底能否解决眼前面对的一切？©豆瓣', '郑秀文', '麦兆辉', 5.9, 19572, 'tt1258130', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1733096714.jpg', 3.8, 20.2, 56.7, 15.9, 3.4, '0.124781,-0.027145,-0.694693,0.606354,-0.285026,-0.285322,0.647181,0.165114,-0.846785,-0.480995,-0.003292,0.408251,-0.041134,0.508480,0.505092,0.077005,0.080537,-0.592509,0.013638,-0.148962,-0.256262,-0.555042,-0.126893,-0.587174,-0.502069,0.154481,0.544090,0.184811,0.128935,0.298000,0.321180,0.151444,-0.354892,0.693250,0.251608,0.012923,0.215593,0.246893,-0.375972,0.382642,0.012697,-0.319927,-0.202837,0.155875,-0.078228,0.697923,0.227994,0.156313,0.029298,-0.341430,0.314315,-0.391428,0.231659,0.231825,0.559147,-0.187038,0.384672,0.455926,-0.618450,-0.355516,0.007600,-0.119346,-0.248101,0.001104,0.297488,-0.131155,-0.548136,0.336993,-0.586448,0.054211,0.030932,-0.356767,0.244693,0.797231,0.459219,0.248742,-0.217641,0.150442,-0.840769,-0.011113,0.524270,0.227147,0.010596,-0.088272,0.191690,-0.488789,-0.422462,-0.161299,-0.168772,-0.033976,0.255739,0.025482,-0.133339,0.366554,-0.115500,-0.291605,-0.081079,0.085555,0.180277,-0.505284,-0.044777,-0.625742,-0.244315,-0.440075,-0.333484,0.005699,0.343586,-0.323390,0.416044,-0.771469,-0.276074,0.050996,0.142594,-0.754784,0.361605,0.236868,0.321577,-0.079266,-0.120495,-0.203405,0.251573,0.333040,0.271853,0.258340,0.049318,-0.038061,0.021291,0.116875', '1303783', '1301022', '1308290', '4193254');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3136507', '机动部队—警例', '动作', '香港警方收到一卷录影带，内容指出三名警队成员涉嫌当街对一名男子使用暴力。为此，香港警方投诉科的成员开始对机动部队（英文PTU）的成员进行调查。机动部队的警员李永森（任达华饰）知道录影带中的警员乃是自己与同事，而被使用暴力的则是绰号“大麻成”的不法分子。于是阿森决定，对上隐瞒事件，对下寻找“大麻成”私了。而此时“大麻成”却不知去向。机动部队的警员孖八（李国麟饰）因为财务问题向警队寻求援助被拒，而其在一次行动中又被上司撞倒使用暴力，孖八被逼上人生的绝路。三队警察，在一夜之间紧张起来，他们能否解决各自的问题呢？©豆瓣', '任达华', '罗永昌', 6.8, 7951, 'tt1256635', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1630104799.jpg', 0.7, 6, 54.2, 31.9, 7.3, '0.532175,-0.175037,-0.401892,0.521787,0.020172,0.018156,0.636042,-0.012167,-0.583827,0.057461,0.135856,0.488143,-0.028963,0.072139,0.346787,-0.258535,-0.341207,-1.017218,-0.246943,-0.168936,-0.355887,-0.638314,0.033743,-0.270279,-0.066885,-0.254352,0.545329,0.061110,-0.284144,0.311342,0.378063,0.552555,-0.203299,0.347162,0.222699,0.014809,0.304670,-0.469396,-0.110584,0.304663,0.010897,-0.553562,-0.000729,0.187296,-0.052653,0.509366,0.795983,-0.084722,-0.154527,-0.321164,0.184323,-0.400361,0.035697,0.063150,0.788566,0.318027,0.194654,0.309052,-0.037208,0.081122,0.058530,0.067544,-0.814778,0.000888,-0.085951,0.388816,-0.600627,0.137876,-0.409080,0.268971,0.129241,-0.234690,0.044895,0.231119,0.222578,0.062602,-0.289650,-0.029793,-0.554197,0.115511,0.455194,-0.063102,0.097483,-0.116675,0.009938,-0.474143,-0.138024,-0.206584,-0.082485,-0.137272,0.307047,-0.132717,0.006679,-0.157218,-0.546736,-0.179666,-0.234348,-0.347774,-0.238797,-0.230793,-0.066520,-0.717351,0.222033,-0.105822,-0.216701,0.141543,0.270187,0.032459,0.558536,-0.668586,-0.026521,0.555798,0.270260,-0.764435,0.374417,0.213249,0.216108,-0.318562,-0.200831,-0.421041,0.403627,0.431883,0.380634,0.151963,-0.131809,-0.495370,-0.211113,-0.199751', '1292829', '25723905', '1307442', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3138953', '东京糖衣巧克力', '动画', '东京，冬季。青年佑太是一位胆小的青年，少女千鹤则是一位不走运的少女。二人都经历了多次不愉快的恋爱经历，而现在，他们在交往。这一天的约会，佑太打算向千鹤告白，而千鹤却打算提出分手以免被甩。正在双方欲言又止之时，佑太离席接听一通电话，而从佑太给千鹤的礼物中，居然突然蹦出一头小毛驴！淘气的小毛驴将千鹤的提包衔走，2人的约会计划彻底被打乱。这样的发展让两人措手不及，更给了两人重新审视这份爱情的机会。一只在东京大街上奔跑的小毛驴，牵动了恋爱中两人的心思。东京塔下的这段爱情，是否能有情人终成眷属呢？©豆瓣', '水树奈奈', '盐谷直义', 7.9, 9339, 'tt1239461', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2196515130.jpg', 0.5, 1.9, 25.6, 47.4, 24.5, '0.598214,-0.178357,-0.502379,0.532171,-0.253695,-0.273917,0.562575,-0.067293,-0.396911,-0.055072,0.179421,0.760853,-0.439739,0.315678,0.596196,-0.124725,-0.128019,-0.795999,0.114957,0.017163,-0.122672,-0.419547,0.021597,0.242216,-0.142188,-0.069712,0.726863,0.138112,0.009602,0.590688,0.212985,-0.108100,-0.072770,0.726162,-0.276443,0.042215,-0.061010,0.254974,0.140239,0.087273,-0.010628,-0.351463,-0.190213,0.488224,-0.133746,0.195042,0.686696,-0.179143,-0.140603,-0.033396,0.497362,-0.215367,0.032102,0.037084,0.440923,-0.171041,0.350300,0.105154,-0.133862,-0.089173,0.021982,-0.035622,-0.549059,0.417129,-0.529947,0.095707,-0.670237,0.423706,0.124329,0.216649,0.121428,-0.074467,0.042738,0.574437,0.465442,0.093116,-0.283254,-0.169767,-0.125613,0.092363,0.675811,-0.078810,-0.063535,0.717005,-0.136071,-0.445253,-0.192574,0.059333,-0.634098,-0.091014,0.253389,0.010069,-0.525470,0.060376,-0.581714,0.118702,-0.311687,-0.228909,0.092628,-0.424768,-0.357405,-0.451409,-0.059203,-0.586684,-0.448324,0.222387,0.064190,-0.016801,0.344545,-0.753077,-0.183022,0.377106,0.172868,-0.543431,0.685946,0.149763,-0.161694,-0.123508,0.139536,0.030945,-0.206647,0.018037,0.300320,0.436642,-0.012983,-0.047446,-0.502066,0.449913', '34973399', '1301022', '1302109', '27191829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3139191', '网球王子剧场版：二人的武士', '动画', '二人的武士：豪华客轮假富商邀请，众正选的华丽比赛和船上逃生。（会出现越前龙马的哥哥 越前龙雅）迹部的礼物：迹部举办了一场华丽的party，邀请中学网球界的人士参加。事实上是给桦地举行生日party，令人感动的兄弟情。', '皆川纯子', '滨名孝行', 7.4, 3849, 'tt1107334', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p454035450.jpg', 0.9, 5, 38, 37, 19.1, '0.314292,-0.076432,-0.206843,0.342169,0.244712,-0.000770,0.214203,0.045523,-0.251642,-0.219088,0.505480,0.787300,-0.160057,0.430681,0.910501,-0.021600,-0.064618,-0.643283,-0.513115,0.218391,-0.119353,-0.280521,0.369329,-0.050033,0.333102,-0.167157,0.495293,0.315400,-0.154904,1.099529,0.390130,0.035024,0.045162,0.128231,-0.125687,-0.347070,0.353180,0.554898,-0.215094,0.284715,-0.388557,-0.230855,-0.101727,0.201604,0.539947,0.060879,0.523993,-0.168896,0.285335,0.120065,0.465152,-0.179884,-0.155703,0.324990,0.248817,0.108291,0.253752,0.161352,0.317414,-0.053624,0.078861,-0.291883,-0.377739,0.038681,0.123405,0.098340,-0.205904,1.286233,-0.048364,0.017514,0.161220,-0.082833,0.330857,0.054406,0.293672,-0.107283,0.153811,0.147512,-0.087841,0.334784,0.992474,-0.140865,0.184627,-0.241179,-0.330316,-0.542922,0.197601,-0.554517,-0.299151,0.503451,0.194907,-0.339317,0.215737,0.047051,-0.678693,-0.434987,-0.259166,-0.202265,0.298080,-0.388340,-0.238911,-1.147098,0.578108,-0.535947,-0.378142,-0.009339,0.198534,-0.217127,0.789024,-1.348445,-0.143425,0.428007,0.395135,0.148525,0.892857,-0.008083,0.030755,-0.009477,-0.055452,-0.453340,-0.154926,-0.011771,-0.338672,0.495340,0.238186,-0.245259,-0.272493,0.061464', '3091208', '26365262', '1826173', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3142101', '攻壳机动队2.0', '动作', '公元2029年，未来世界是高科技与信息化的世界。人类生活水平的提高伴随着犯罪活动的高科技化，于是，专门镇压高科技犯罪的特殊部队——公安9课成立了。队长草薙素子，作为一位全身“义体化”的女警，带领公安9课不断展开行动。是次，公安9课帮助公安6课秘密解决了一位程序员外逃他国的麻烦琐事，又卷入传说中的黑客“傀儡师”的犯罪事件。当行动陷入僵局之际，傀儡师竟然不请自来，出现在公安9课！素子与她的战友们，不知不觉地被卷入了一场涉及政府的阴谋之中。本作根据1995年动画电影《GHOST IN THE SHELL》改编，系剧情不变、画面完全重制的作品。©豆瓣', '田中敦子', '押井守', 9, 17627, 'tt1260502', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p456918283.jpg', 0.3, 0.6, 7.8, 30.7, 60.7, '0.215122,-0.083430,-0.321208,0.419394,0.052097,0.257259,0.117155,-0.105156,-0.443016,-0.503797,0.300677,0.193375,0.025875,0.063533,0.418454,-0.582847,-0.240083,-0.707422,0.090374,-0.140701,-0.425792,-0.284267,-0.398355,-0.462334,0.073904,-0.799465,0.927380,0.048031,-0.601679,0.249843,0.055468,0.358663,-0.289351,0.247607,0.006790,-0.231619,0.492498,-0.086475,-0.260864,0.096763,-0.247266,-0.166362,-0.067500,-0.409641,-0.130906,0.065444,0.759079,-0.278740,-0.109435,-0.370434,0.407065,-0.448986,-0.274107,-0.232320,0.730554,0.299712,0.015633,0.569054,0.157263,0.109432,-0.167673,-0.290715,-0.860152,-0.348318,0.196108,0.060065,-0.248334,0.255957,-0.099651,0.274515,-0.184784,-0.079015,0.217561,0.380378,0.612253,0.500042,0.001916,-0.013318,-0.204658,0.458657,0.327233,-0.153359,-0.463493,0.158711,-0.179976,-0.407691,-0.305333,-0.235389,-0.085505,0.198500,0.169822,-0.151050,-0.114583,0.572341,-0.836976,-0.114455,-0.086035,-0.393739,0.138763,-0.247139,-0.133190,-0.753187,0.017130,0.056512,-0.127335,0.057020,0.087549,-0.169743,0.896064,-0.785304,0.001696,0.593493,0.123065,-0.579668,0.736004,0.100513,0.428297,-0.366128,-0.226115,-0.236548,-0.052644,0.627394,0.027735,0.353332,-0.041626,-0.233032,-0.095420,0.140748', '1291936', '26759820', '25912924', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3143676', '林中小屋', '恐怖', '在一个明媚的日子里，同在一所大学的荷登（杰西·威廉姆斯 Jesse Williams 饰）、马提（弗兰·克朗茨 Fran Kranz 饰）、茱尔丝（安娜·哈彻森 Anna Hutchison 饰）、戴娜（克里斯汀·康奈利 Kristen Connolly 饰）以及科特（克里斯·海姆斯沃斯 Chris Hemsworth 饰）等5人驱车前往位于深山老林的小木屋中度假。他们不知道的是，自己的一举一动都在一个神秘机构的监视之下，甚至会自觉不自觉按照那群人的引导进入圈套。“无意”之中，戴娜用拉丁文念出一段咒语，在此之后，长眠泥土之下的丧尸爬了出来，对年轻人们展开血腥大屠杀。而镜头的另一边，神秘机构的成员喜滋滋看着镜头前的一切。无知的年轻人们，为了一个神秘的目的必须死去……©豆瓣', '克里斯汀·康奈利', '德鲁·戈达德', 7.5, 225065, 'tt1259521', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1323381020.jpg', 1.1, 4.5, 30, 45.4, 19.2, '0.534565,0.011636,-0.661285,0.730798,-0.143313,0.077733,0.797098,0.047989,-0.494872,-0.285598,0.454708,0.603572,-0.085414,0.143411,0.265846,0.206718,-0.460724,-0.568014,-0.273263,-0.471130,-0.458954,-0.518103,-0.369442,-0.384254,-0.001942,-0.428712,0.270021,0.156256,-0.026236,0.523583,0.227346,0.435429,-0.379590,0.123021,-0.036850,-0.075869,0.304568,-0.237384,-0.095480,0.231630,-0.180889,-0.253126,-0.308419,-0.068979,-0.037349,0.300557,0.838798,-0.395852,0.020981,0.019418,0.203365,-0.197297,-0.057109,0.400975,0.241075,-0.166613,0.150810,0.233110,-0.276224,0.313816,0.136073,-0.144411,-0.722832,-0.026049,-0.090527,0.449990,-0.492557,0.448182,0.075744,-0.065237,0.200324,-0.402309,0.145737,0.056569,0.250775,0.349931,0.014220,-0.065995,-0.401175,0.016143,0.235289,-0.030562,-0.165599,0.353915,-0.363168,-0.241321,-0.260683,0.149510,-0.614736,-0.219574,0.396472,-0.118347,0.046260,0.184002,-0.565817,-0.044556,-0.197435,-0.380744,-0.064667,-0.241012,-0.441511,-0.675044,-0.000774,-0.256862,-0.060222,0.095180,-0.300841,0.037504,0.606558,-0.767059,0.363128,0.637183,0.198960,-0.152673,0.478694,-0.081883,0.229021,-0.212533,-0.211104,0.253759,0.303308,0.259165,0.062023,0.594212,-0.167005,-0.047735,-0.402153,0.393732', '30401849', '3005387', '26677495', '11810348');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3143727', '贼巢', '动作', '从未被劫的银行，三千万无记认钞票，引爆连环盗计。一群以梅雷亚（巴勃罗·施瑞博尔 饰）为首的高智罪犯，手法高超、火力强横、而且沉迷打劫；纵使犯案累累，却甚少破绽，令警方束手无策。一次押款车劫案后，他们的党羽唐尼（奥谢拉·杰克逊 饰）被辣手神探尼克（杰拉德·巴特勒 饰）识破，更从他身上知道匪帮下一个目标，是攻破从未遇劫的洛杉矶联邦储备银行，从中盗取三千万即将销毁的旧钞！于是尼克布下天罗地网，想趁机把他们一网成擒。然而，魔高一丈；梅雷亚以声东击西之法，引开警方注意。尼克错失擒获他们的良机，唯有尾随追击，双方展开连场枪战。虽然最终截获贼匪，但赃款竟全数不翼而飞！局中有局，究竟谁是取得巨款的幕后赢家？', '杰拉德·巴特勒', '克里斯蒂安·古德加斯特', 7.4, 26226, 'tt1259528', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2509782231.jpg', 0.6, 2.9, 34.5, 47.7, 14.3, '0.135084,0.074751,-0.449744,0.372625,-0.050864,0.023851,0.480354,-0.228249,-0.219222,-0.134217,0.375084,0.303229,-0.075531,-0.439140,-0.020341,-0.151721,0.008350,-0.695424,0.045310,-0.234989,-0.110376,-0.306964,-0.754486,-0.010651,0.054493,-0.111252,0.426639,0.378372,-0.192553,0.235671,0.382288,0.353230,-0.224428,0.339319,0.170324,-0.041302,0.029950,-0.332957,-0.214669,0.267915,-0.335134,-0.511080,-0.306149,0.121035,0.004607,0.514993,0.547367,-0.190227,0.051307,-0.000907,0.217782,-0.397459,-0.072041,0.097692,0.359949,-0.023894,0.031883,0.128426,-0.314338,-0.136011,0.298391,0.274050,-0.926700,-0.031488,0.109211,-0.149874,-0.302387,-0.128229,-0.369939,0.464091,-0.336368,-0.235841,-0.081272,0.349859,0.438787,-0.330703,0.231015,-0.187876,-0.678768,-0.073908,0.446787,-0.498394,-0.033119,-0.072851,0.191397,-0.351546,0.135919,-0.473711,0.022632,0.062441,0.579283,0.006923,0.104700,0.095059,-0.344032,-0.110437,-0.711584,0.114286,-0.334269,-0.224022,-0.044810,-0.540311,-0.154579,-0.034695,-0.254710,0.262341,0.177408,-0.039154,0.287005,-0.177116,-0.031547,0.628895,0.017471,-0.389159,0.230189,0.053353,-0.124852,-0.004902,-0.214940,-0.023675,0.730559,0.229600,0.244698,0.155407,-0.011769,-0.444339,-0.011858,0.073567', '26747274', '1293936', '4014397', '1293605');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3144512', '同心难改', '剧情', '本片依据导演兼编剧谢米姆·萨尔弗所撰写的自传小说改编而成。女配角之一的莉莎·瑞是印裔名模兼影戏女星，前作《水》更曾获奥斯卡提名。在传统的中东的上流社会中，Reema和Omar正为他们的女儿Tala（丽莎·蕾 Lisa Ray 饰）准备婚礼。在伦敦工作的Tala通过朋友Ali认识了Leyla（茜多·塞丝 Sheetal Sheth 饰）。Leyla正努力成为一名作家，淳朴、笨拙而又敏感，这些统统吸引了Tala的注意。同时，Tala的坦率使得Leyla对自我有了真正的认识。她们相爱了，但是责任与文化道德牵制着Tala，她身不由己地回家准备着她那密锣紧鼓的华丽盛大的婚礼。随着家庭成员的拜访和婚礼日子一天天的接近，Tala的压力不断上升。婚期一天天临近，Tala如何做出人生的抉择？©豆瓣', '丽莎·蕾', '谢米姆·萨尔弗', 8, 34267, 'tt0830570', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2425131039.jpg', 0.4, 2.7, 23.8, 40.5, 32.6, '0.327444,0.061109,-0.483891,0.669826,0.195474,-0.164154,0.468063,0.196371,-0.166564,-0.280405,0.093977,0.717246,-0.384823,0.138739,0.439141,-0.175483,-0.198670,-0.843551,-0.090815,-0.056765,-0.172391,-0.589292,-0.145003,-0.059447,-0.071971,-0.358667,0.508583,0.042463,0.036369,0.514494,0.442002,0.141681,-0.013843,0.277925,-0.038008,-0.024495,0.148906,0.055079,-0.424118,0.115875,0.128409,-0.205833,-0.198648,0.136464,0.101331,0.320167,0.680602,-0.222680,-0.054960,0.041722,0.746580,-0.298942,0.083326,0.058915,0.128909,0.109677,0.145565,0.120492,-0.073833,-0.007680,-0.024534,-0.364523,-0.854264,0.082830,0.243738,0.146645,-0.670269,0.381029,0.035575,-0.054848,0.030022,-0.317439,0.245431,0.612370,0.066547,0.425462,-0.048535,0.157628,-0.219238,0.584699,0.751793,0.142788,-0.189242,0.386828,-0.571040,-0.377053,0.025774,-0.372811,-0.564911,-0.228516,0.159248,0.066530,0.073966,0.225250,-0.487022,-0.053095,0.006649,-0.271838,0.241463,-0.475939,0.167508,-0.733836,-0.282059,-0.546951,0.013144,-0.134104,-0.004442,-0.372442,1.029191,-0.758793,0.215148,0.619050,0.496570,-0.522551,0.814275,0.195318,0.161509,-0.014124,-0.219912,0.183375,-0.257522,-0.070341,-0.011860,0.401468,0.106000,-0.233564,-0.436676,0.429939', '27602116', '3811356', '2027945', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3147497', '开国大典', '剧情', '举世闻名的辽沈、淮海、平津三大战役胜利后，西柏坡军民欢庆胜利。三大战役的胜利使蒋家王朝摇摇欲坠，蒋介石（孙飞虎 饰）发表“新年文告”、推出李宗仁（邵宏来 饰）任代总统，导演了一幕假隐退真操纵的丑剧。1949年1月21日，蒋介石由汤恩伯（叶庆林 饰）、蒋经国（陈国典 饰）等陪同，最后一次登上中山陵，之后又在其老家奉化溪口主持了高级军事会议，妄图阻止解放军过长江。3月，中共七届二中全会召开，4月，毛泽东（古月 饰）与朱德（刘怀正 饰）。总司令发出了向全国进军的命令。人民解放军百万雄师强渡长江，攻占总统府，南京胜利解放。5月24日，蒋介石逃往台湾。5月26日，上海解放。随后，全国大部分地区和城市都获得解放。毛泽东先后在中南海会见了国民党起义将领和各界民主人士。开国大典迫在眉睫......©豆瓣', '古月', '李前宽', 7.8, 7963, 'tt1220564', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2571440642.jpg', 3.2, 2.6, 24.9, 41, 28.2, '-0.380055,0.040926,-0.706958,0.179958,0.302341,0.002869,-0.393001,0.182812,-0.543062,0.523654,0.162996,0.469850,-0.322496,-0.209311,0.416364,-0.393618,-0.590815,-0.790534,0.008253,-0.334130,0.062322,-0.392446,-0.017218,-0.033592,0.162634,0.009893,0.544014,0.533560,0.256938,0.620936,0.423319,-0.046781,0.189855,0.380774,0.345443,-0.100065,0.042235,-0.253361,-0.452896,0.351064,-0.259457,-0.365671,-0.556297,0.061094,0.142220,0.024026,0.515115,-0.468784,0.127220,-0.552944,0.403190,-0.382016,-0.100169,-0.013451,0.457188,0.495397,-0.080854,0.544611,-0.206311,-0.189482,-0.103408,-0.313735,0.260081,0.198197,-0.190290,0.040399,-0.304787,0.522808,-0.164326,0.629840,0.074580,-0.423401,0.166446,0.994318,-0.202902,0.367299,-0.174597,0.190937,-0.217081,0.818698,0.271190,-0.257248,-0.351388,-0.524115,0.229104,-0.196959,0.132205,-0.244985,0.275597,0.066583,0.050800,-0.033793,0.296580,0.033126,-0.310102,-0.211289,-0.350552,-0.372978,0.351366,0.131937,-0.054972,-0.986646,-0.102097,0.134302,0.261419,-0.058945,0.302405,0.319153,0.612868,-0.637360,-0.063350,-0.000703,0.465462,-0.161633,0.549608,0.387470,-0.043465,-0.227476,0.344876,0.273796,-0.327732,0.669378,0.095764,0.194663,-0.209759,-0.169658,0.084320,0.099955', '26788667', '1424552', '1431694', '1316511');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3147941', '欲望都市2', '剧情', '凯瑞（萨拉·杰西卡·帕克 Sarah Jessica Parker 饰）和夏洛特（克里斯汀·戴维斯 Kristin Davis 饰）的两位同性好友，安东尼（马里奥·坎通  Mario Cantone 饰）与斯坦福（威利·加森 Willie Garson 饰）终于成婚，而凯瑞与“大先生”（克里斯·诺斯 Chris North 饰）婚后却不满生活日渐平淡，二人矛盾渐生。全职妈妈夏洛特日夜担心丈夫哈里（伊万·汉德勒 Evan Handler 饰）会与青春洋溢的爱尔兰保姆艾琳（爱丽丝·伊芙 Alice Eve 饰）出轨。律师米兰达（辛西娅·尼克松 Cynthia Nixon 饰）不满老板对女性的歧视，愤而辞职。就在此时，萨曼莎（金·凯特罗尔 Kim Cattrall 饰）应阿联酋酋长之邀，带领三人出游中东的阿布扎比。在香料集市上，凯瑞重逢多年前的旧爱艾登（约翰·考伯特 John Corbett 饰）。心猿意马的凯瑞盛装赴约，果然犯了不该犯下的错误……', 'Sarah Jessica Parker', 'Michael Patrick King', 6.9, 51072, 'tt1261945', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p500714629.jpg', 1.7, 10.2, 44.7, 30, 13.5, '0.291819,-0.133583,-0.365685,0.227700,0.267348,-0.670490,0.654636,0.335965,-0.364606,-0.257727,0.233824,0.772742,-0.309486,0.267622,0.488859,0.365303,-0.734244,-0.539877,0.182650,-0.088194,0.069117,-0.642688,-0.016710,-0.381604,-0.038705,-0.377222,0.069428,-0.378461,0.183427,0.744283,0.585091,0.598402,-0.091285,0.155100,0.380474,0.174775,0.504524,-0.119669,-0.509646,-0.001131,-0.027513,0.212717,-0.056624,0.035878,0.447781,0.309281,0.286011,-0.340255,0.145125,-0.191465,0.030299,0.217653,0.332639,0.210365,0.050787,-0.296559,0.149861,0.148182,-0.172617,-0.055911,0.013755,-0.141624,-0.125399,0.346737,0.001516,0.279427,-0.383915,0.487556,-0.466833,-0.153056,0.096045,-0.258992,-0.319102,0.215656,0.049787,0.218551,0.211586,0.107085,-0.046268,-0.033934,0.079518,0.189125,-0.117725,0.132531,-0.519477,-0.051246,0.026251,0.101894,-0.682773,-0.192400,0.248013,-0.190089,0.281276,0.406607,-0.538460,-0.183018,-0.513871,0.160314,0.080835,0.021497,0.016988,-0.720352,0.065779,-0.620726,-0.374666,-0.132221,0.205018,0.139498,0.316138,-0.684324,0.376850,0.181479,0.220877,-0.128097,0.217421,0.107334,-0.014197,-0.457365,-0.136272,0.503256,-0.090908,-0.250214,0.219998