INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3147969', '人皮客栈3', '恐怖', '四个朋友斯科特（布莱恩·哈利塞 Brian Hallisay 饰）、卡特（琦普·帕杜 Kip Pardue 饰）、贾斯汀和迈克相约，离开他们乏味或者控制欲旺盛的女友，结伴前往拉斯维加斯，预备开始一场猎艳消遣之旅。赌场中，两名女郎向四人发出邀请，令他们参与了一处荒僻建筑物中的私密狂野派对，他们玩得好不尽兴，岂料当晚迈克失踪，次日焦急的朋友们通过昨夜女郎留下的地址寻找迈克的下落，结果被卷入了一场猎杀游戏。原来有一支秘密的猎人俱乐部，在赌城中捕获游客，供会员们杀害与赌博。斯科特等人沦为猎物，等待他们的将是无情的残杀，而这几位朋友之中，有一位竟然也是俱乐部会员……©豆瓣', '布莱恩·哈利塞', '斯科特·斯皮格尔', 5.7, 18297, 'tt1255916', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2540601173.jpg', 7.3, 26.2, 46.4, 13.8, 6.4, '0.396550,-0.061050,-0.564996,0.357499,-0.090679,-0.056037,0.652499,-0.059724,-0.330772,-0.070453,0.110664,0.758424,-0.388895,0.291313,0.621566,-0.091433,-0.363959,-0.624089,-0.128627,-0.189740,-0.072187,-0.344657,-0.091931,-0.373922,0.054117,-0.096989,0.295571,0.028772,-0.161875,0.733017,0.372394,0.490328,-0.624738,0.371731,0.054948,-0.198271,0.511745,-0.036221,-0.237147,0.351819,-0.244469,-0.108136,-0.220894,-0.156410,0.354678,0.468356,0.715160,-0.215939,-0.029429,-0.241433,-0.154186,-0.231600,0.088295,0.241292,0.279631,0.010300,0.209650,0.156289,-0.165659,0.140711,-0.103149,-0.214491,-0.664578,0.188561,0.219705,0.002662,-0.339537,0.342701,0.075279,-0.063669,-0.046770,-0.219109,0.394474,0.286262,0.158138,-0.064332,0.376828,-0.182241,-0.440194,0.206063,1.058894,-0.179394,0.099567,-0.131457,0.052842,-0.270752,0.246633,0.088486,-0.468884,-0.140628,0.557659,0.007953,0.110634,-0.108272,-0.867715,-0.035742,-0.144950,-0.321892,0.097145,-0.334931,0.009509,-1.144950,0.155660,0.046859,-0.049034,0.071411,0.049631,-0.049371,0.704955,-0.587734,0.150197,0.668471,0.292640,-0.479614,0.805009,-0.076062,0.380762,0.029442,-0.200713,-0.080652,0.392661,0.083491,0.252029,0.214921,-0.162776,-0.050799,-0.298128,0.181385', '11541282', '10466639', '2159244', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3148013', '铁拳', '动作', '本片创造了一个虚构的混战时代，背景是19世纪的中国。在北方有一个势力强大的狮子帮，朝廷想用黄金收买他们，而此时帮派内讧了，老大金狮（陈观泰 饰）被老二银狮（文峰 Byron Mann 饰）和老三铜狮（黎烈弓 Cung Le 饰）杀害，金狮的儿子曾义（尹成植 Rick Yune 饰）决心要为父报仇。远在偏僻小镇的铁匠（RZA 饰）一心想存够钱跟心爱的青楼姑娘丝丝（杰米·钟 Jamie Chung 饰）远走高飞，却因为有一手好手艺被迫卷入了事件，而此时镇上来了个来路不明的高手杰克刀（罗素·克劳 Russell Crowe 饰），朝廷派来的双子男女杀手（连凯 饰）和（黄芝琪 Grace Huang 饰）也来到镇上，随后狮子帮的打手“黄铜阀体”（戴夫·巴蒂斯塔 Dave Batista 饰），朝廷特派官员（吴彦祖 饰）和青楼老鸨花夫人（刘玉玲 饰）也陆续加入了战斗，小镇陷入了一场空前的血雨腥风。导演编剧加主演RZA表示拍摄本片的初衷是为了向邵氏电影致敬。', '罗素·克劳', '罗伯特·菲茨杰拉德·迪格斯', 5.6, 17627, 'tt1258972', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1750066510.jpg', 10.7, 26.3, 41.6, 15.4, 6, '-0.055623,-0.058519,-0.320175,0.416407,0.025412,-0.221434,0.630105,0.446097,-0.317056,-0.109396,0.423991,0.706726,0.078738,-0.264511,0.169901,0.002096,-0.075236,-0.477788,0.089679,-0.134252,-0.108975,-0.146408,-0.184985,-0.328023,-0.070749,-0.185552,0.391566,-0.000216,-0.028367,0.513037,0.515684,0.287188,-0.008958,0.108032,-0.089404,-0.011731,0.125528,-0.077805,-0.281793,0.290657,-0.265665,-0.124490,-0.276216,0.034951,0.037009,0.276690,0.505741,-0.080608,0.174498,-0.126902,0.234226,-0.176105,-0.116810,-0.042379,0.465042,-0.038421,0.139552,0.060856,-0.123535,0.059437,0.150184,-0.215178,-0.602316,0.123636,0.328471,0.031064,-0.775650,0.526901,-0.202448,-0.197294,-0.022281,-0.179086,0.317742,0.204599,0.296036,0.108764,0.121058,-0.012095,-0.625564,0.498420,0.400123,-0.121349,0.257129,0.023117,0.052305,-0.427220,-0.258337,-0.192222,-0.320491,-0.052028,0.630560,-0.402013,0.006794,0.061387,-0.710622,-0.093355,-0.216724,-0.058433,0.063120,-0.336448,0.028200,-0.397446,-0.238829,-0.300835,-0.032248,-0.066205,0.280984,0.191855,0.715916,-0.542811,-0.047703,0.564707,0.276698,-0.441107,0.598465,-0.029039,0.097997,-0.170800,-0.107595,-0.332110,0.036999,0.279759,0.232285,0.243529,-