INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3148027', '暮光之城2：新月', '剧情', '贝拉（克里斯汀•斯图尔特 Kristen Stewart　饰）的18岁生日到了，父亲送了她礼物。爱德华（罗伯特•帕丁森 Robert Pattinson　饰）大方示爱，并为她讲述了意大利吸血鬼王族的传奇。爱德华的红发妹妹爱丽丝（阿什丽•格林尼 Ashley Greene　饰）特意为贝拉举办的生日派对,期间,贝拉无意中划伤了手臂，遭到加斯帕的袭击，靠着爱德华的庇护，才逃过一劫。不过，此后，爱德华逐渐疏远贝拉，并提出了分手。这令贝拉心寒，但爱德华也有苦衷，仍在暗中保护贝拉。贝拉处于空窗期，昔日老友雅各布（泰勒•洛特 Taylor Lautner　饰）嘘寒问暖，两人的关系也由此升温。此后,贝拉因为跳崖获救,才得知雅各布是狼人,专门对付吸血鬼。与此同时，不知情的爱德华以为贝拉自杀，心灰意冷，来到意大利请求王族结束自己的生命……本片根据美国女作家斯蒂芬妮•梅尔（Stephanie Meyer）的畅销小说《暮光之城：新月》改编。', '克里斯汀·斯图尔特', '克里斯·韦兹', 6.8, 268115, 'tt1259571', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p850945243.jpg', 2.2, 10.5, 44.5, 28.7, 14.1, '0.237645,0.001069,-0.513839,0.451172,0.084360,-0.520527,0.567309,0.183177,-0.332618,-0.508300,0.314239,0.647852,-0.202460,0.224454,0.666650,0.154335,-0.673661,-0.454945,0.207402,-0.180470,-0.241883,-0.614220,-0.119826,-0.311488,-0.003835,-0.565510,0.369803,-0.170443,-0.027450,0.566475,0.299086,0.533117,0.020182,0.232348,0.266713,0.121676,0.457764,-0.190172,-0.353564,0.212481,-0.005405,-0.105213,0.047628,0.388072,0.081272,0.641556,0.423716,-0.416787,0.215105,-0.322425,0.213040,-0.285111,0.254277,0.114905,0.326200,-0.208552,0.166030,0.197624,-0.141627,0.018808,0.099195,-0.071880,-0.420906,0.441510,-0.006331,0.116535,-0.418415,0.302601,-0.256365,0.108958,0.108269,-0.221993,-0.004348,0.483436,0.211393,-0.006996,0.020216,0.113951,-0.262291,-0.101476,0.416139,-0.057161,-0.140348,0.173628,-0.294568,-0.293121,0.212641,0.083572,-0.440513,-0.056258,0.416134,-0.035308,0.133463,0.457043,-0.462016,-0.507105,-0.804926,-0.147157,0.150678,-0.348395,0.121026,-0.764770,-0.096160,-0.157318,-0.224591,-0.379836,0.131484,-0.217498,0.299684,-0.691011,0.393349,0.556749,0.332720,-0.175076,0.191132,-0.034512,0.089707,-0.300775,-0.214533,0.800517,0.197752,-0.193701,0.075009,-0.003597,0.382776,-0.15987