INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3148089', '300勇士：帝国崛起', '剧情', '著名的马拉松战役中，希腊英雄特米斯托克列斯（沙利文·斯特普尔顿 Sullivan Stapleton 饰）射杀波斯国王大流士王，从此埋下薛西斯一世（罗德里格·桑托罗 Rodrigo Santoro 饰）卷土重来的祸根。在波斯王国海军统帅阿特米西亚（伊娃·格林 Eva Green 饰）的煽动下，薛西斯率领大军与斯巴达的领袖列奥尼达（杰拉德·巴特勒 Gerard Butler 饰）及其三百勇士在温泉关爆发流传千古的血战。另一边，阿特米西亚统帅的强大海上部队逼近爱琴海另一边的雅典。威望关头，特米斯托克列斯再度站出来，和希腊的勇士们为了捍卫自由迎战这个体内流淌着复仇之血的黑色女神。翻云吐雾，恶浪滔天，最残酷的杀戮在遥远的时代进行……©豆瓣', '沙利文·斯特普尔顿', '诺姆·穆罗', 6.3, 41211, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2001509087.jpg', 2.6, 15.9, 51, 22.6, 7.9, '-0.012863,0.150785,-0.638463,0.827127,0.410687,-0.280971,0.562016,0.240888,-0.134093,-0.013668,0.466344,0.564002,0.050489,-0.369975,0.610441,0.016846,-0.654525,-0.777988,-0.289781,0.118058,0.098889,-0.366680,-0.577552,-0.179829,-0.129137,-0.649565,0.525119,-0.113679,0.061344,0.444884,0.135956,0.677207,0.033486,0.177762,0.069824,-0.074914,0.197080,-0.448290,-0.153629,0.537240,-0.388882,0.191920,-0.247340,-0.047818,0.091050,0.120931,0.503369,-0.837740,0.727215,-0.422167,-0.037184,-0.389744,0.252720,0.084293,0.335434,-0.257223,0.025504,0.119958,0.103924,-0.126084,0.073215,-0.190426,-0.445276,-0.422487,-0.140704,0.278192,-0.624408,0.350982,-0.379800,-0.065397,0.746583,-0.038740,-0.013031,0.640211,0.206411,0.180859,-0.089656,-0.004400,-0.646029,-0.099964,0.527299,-0.102382,-0.271322,-0.651520,-0.177177,-0.514975,-0.116014,-0.228625,-0.561387,-0.404105,0.381624,-0.299857,0.678001,0.873522,-0.952121,-0.148607,-0.608275,-0.302133,-0.017717,-0.121556,-0.050043,-0.468657,-0.027318,-0.054219,0.024114,0.127666,0.160879,0.168533,0.448769,-0.241781,0.425600,0.361456,0.401354,0.407871,0.373726,0.072814,0.161109,0.034709,-0.292551,0.869388,0.164656,0.365073,-0.014021,0.377042,-0.045579,-0.010258,-0.397768,0.792261', '1298586', '3157583', '2158490', '4943938');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3148297', '一本漫画闯天涯II妙想天开', '喜剧', '青年张健康（张卫健 饰）靠画漫画维生，然而他的作品天马行空缺乏逻辑，导致单行本严重积压，社长和同事处处挤兑他，健康本人也为寻找灵感苦恼不已。饮料店小妹安琪对健康暗恋已久，健康的母亲明姐为了唤醒健康的灵感也在做着徒劳的努力，对女人们漠不关心的健康从《一本漫画闯天涯》中得到了启发，将希望寄托在形似黑道中人的新邻居包尾达（吴孟达 饰）身上，健康央求包尾达带他搜集黑道素材，包尾达因健康而受黑道兄弟侮辱，甩手不干，无奈明姐风情万种，二人勾动天雷地火，包尾达为了明姐只得再为健康引路，这次二人意外见证黑道血腥现场，惹祸上身……©豆瓣', '张卫健', '朱继生', 6.3, 5951, 'tt0108620', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2549054731.jpg', 4.8, 15.4, 52.8, 16.2, 10.8, '-0.168303,0.012881,-0.270389,0.296446,0.017592,-0.219675,0.435502,0.095437,-0.457770,0.005307,0.120824,0.475030,0.097260,0.217348,0.094532,-0.014733,-0.244693,-0.570242,0.083166,0.296521,0.086530,-0.118938,-0.289724,-0.296006,-0.428761,-0.636221,0.274238,0.186828,-0.322849,0.461513,0.372118,0.157576,-0.148581,0.046603,0.066404,-0.093307,-0.293138,-0.031457,-0.328267,-0.058300,0.338258,-0.284187,-0.217760,0.178696,0.135653,0.319723,0.659593,-0.010484,-0.431678,-0.099661,0.698542,-0.203715,0.044991,0.092013,-0.021883,0.216371,0.196291,0.017424,-0.153385,0.032991,0.104546,-0.021597,-0.813193,-0.293254,0.341611,0.176304,-0.324247,0.668397,-0.020909,-0.099802,0.305121,-0.241538,-0.044795,0.204371,0.253418,0.366235,-0.085327,0.450273,0.075834,0.410114,0.259070,0.035367,-0.121710,0.281290,-0.582685,-0.084321,0.148794,-0.266371,-0.452068,-0.108018,0.223182,0.156673,-0.076333,0.214418,-0.402681,0.223747,0.033321,-0.005330,-0.080052,-0.224889,-0.094913,-0.331395,-0.097107,-0.104805,0.018710,-0.181103,0.160396,-0.398677,0.837433,-0.466469,0.220950,0.417786,0.189898,-0.671931,0.558059,0.109639,0.016041,-0.287109,-0.242644,0.103265,-0.036770,0.257450,0.215850,0.111457,-0.103244,-0.118342,-0.253660,0.061902', '27602116', '24284209', '26678784', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3148571', '内衣少女', '喜剧', 'Miu（邓丽欣 饰）去应聘一家内衣公司，结果得到内衣调查员的工作，同时一直单身的姑姑去世，Miu与号称“大叔杀手”的表妹Donut（文咏珊 饰）一同搬入了姑姑的华居。公司这边，市场部的少女杀手Lucas（郑中基 饰）试图推倒Miu未果，转而以朋友的立场对她，在Lucas的开导下，Miu先后卷入与“银行经理”、著名才子、自恋的公司太子爷诸人的荒诞交往。住在Miu楼下的空姐Celina频频丢失内衣，在报警时结识了辅警沈家俊（徐天佑 饰），二人很快同居，但代价是小辅警不能阻碍空姐的攀高枝梦想……Miu在市场调查中结识的酒店公关CC（贾晓晨 饰）巧遇羞涩的哈佛毕业生Eugene（安志杰 饰），后者让CC找到了爱情的希望……几个女孩在各自的爱情路上磕磕绊绊，而内衣，也在她们寻找的过程中被赋予了更多的意义。©豆瓣', '邓丽欣', '陈庆嘉', 5.8, 19226, 'tt1262141', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2097903910.jpg', 5.3, 21.2, 53.5, 16.6, 3.5, '0.360252,0.053493,-0.408785,0.510911,-0.128379,-0.391550,0.534961,0.381598,-0.523452,-0.264736,0.330921,0.530863,-0.099155,0.339924,0.300720,-0.059549,-0.162993,-0.660947,0.085778,-0.156336,-0.317758,-0.304144,-0.067114,-0.131089,-0.086824,-0.251160,0.629185,0.045774,-0.090953,0.472581,0.522753,-0.057881,-0.352531,0.436966,-0.193993,0.019025,0.316900,0.133459,-0.583849,0.241055,0.006644,-0.345050,-0.048351,-0.044399,0.091615,0.266937,0.652911,-0.016629,0.030262,0.091590,0.443101,0.128795,0.139321,0.034730,0.460305,-0.031694,0.361520,0.140310,-0.302618,-0.010894,0.223658,0.047138,-0.582127,0.029662,0.347507,0.104559,-0.691519,0.534066,-0.105033,0.019853,0.155200,-0.441419,0.182188,0.274618,0.113394,0.128798,0.012624,0.206769,-0.446903,0.520132,0.448878,0.149683,0.219653,0.338821,-0.204280,-0.302643,-0.092157,-0.029107,-0.385319,0.042677,0.278919,-0.100661,-0.121669,0.054609,-0.684932,-0.159534,-0.182015,-0.033626,0.117312,-0.444262,0.021914,-0.584744,-0.115387,-0.294307,-0.033837,0.084734,0.187371,-0.026960,0.586406,-0.827426,-0.226805,0.611547,0.460052,-0.586127,0.844723,0.001073,0.239502,-0.242337,-0.261319,-0.064962,0.023792,0.251393,0.079403,0.411046,-0.192952,-0.245885,-0.335475,-0.032623', '3033092', '2124718', '1418179', '5374383');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3148748', '海扁王', '喜剧', '戴夫·莱泽斯基（亚伦·约翰逊 Aaron Johnson 饰）和所有普通的男孩一样，梦想有一天可以成为超级英雄，只不过他把自己的这一梦想带入了现实。在网上购买到一套廉价的绿色连体衣之后，戴夫便开始了只身打击犯罪的行动。虽然第一次行动便让戴夫身负重伤，不过戴夫可不是一个轻言放弃的人，伤愈之后的戴夫在一次阻止斗殴时，被热心的群众发现并拍摄，之后关于超级英雄“海扁王”的事迹便传遍整个城市。成为传说中超级英雄的戴夫在一次行动中结识超级英雄父女“大老爸”（尼古拉斯·凯奇 Nicolas Cage饰）和“超杀女”（科洛·莫瑞兹 Chloe Moretz 饰），之后戴夫遭毒枭集团老大弗兰克·阿米克（马克·斯特朗 Mark Strong 饰）之子伪装成的英雄“红旋风”（克里斯托夫·梅兹-普莱瑟 Christopher Mintz-Plasse 饰）的利用，让“大老爸”和自己身陷囹圄。危难之时，“超杀女”及时出现救出戴夫，但“大老爸” 却不幸身亡。“超杀女”决定完成其父遗志，彻底消灭毒枭集团……本片根据马克·米勒（Mark Millar）著名同名漫画改编。', '亚伦·泰勒-约翰逊', '马修·沃恩', 7.6, 218508, 'tt1250777', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2166633101.jpg', 0.8, 4, 30.6, 45.6, 18.9, '0.104698,0.331916,-0.617885,0.393121,0.064926,-0.479122,0.549669,-0.019870,-0.255352,-0.335860,0.201702,1.045008,-0.275968,0.088355,0.422813,-0.053447,-0.363303,-0.674221,0.026469,-0.170875,-0.239051,-0.423327,-0.375374,-0.114601,-0.118034,-0.488928,0.488236,-0.047837,-0.230008,0.233698,0.481138,0.334750,0.093585,0.263481,-0.013267,0.134436,0.363217,-0.035590,-0.446740,0.305441,-0.147148,0.142574,-0.011043,0.154130,0.086592,0.222166,0.457736,-0.564967,0.046462,-0.221095,0.350933,-0.238181,-0.102022,-0.026615,0.226223,-0.117502,0.349866,-0.019023,-0.047362,-0.254816,0.088229,-0.188317,-0.813408,0.069406,0.165404,-0.057586,-0.543246,-0.027068,-0.124359,0.048772,0.080124,-0.186227,0.073047,0.228760,0.518228,0.104578,0.050013,0.219418,-0.386285,0.180696,0.649482,0.126214,-0.285658,0.089348,0.196934,-0.353748,-0.047144,-0.294504,-0.306031,0.102376,0.470674,-0.138372,-0.038375,0.376792,-0.682636,-0.196805,-0.644504,-0.106649,0.111777,-0.175971,-0.131917,-0.604772,0.050521,-0.008333,-0.062688,0.199882,0.201708,-0.351236,0.773151,-0.822248,0.228115,0.365414,0.065316,-0.400274,0.368439,-0.030075,0.285676,-0.250662,-0.034752,0.119433,0.429545,0.250619,0.155143,0.366953,-0.167677,-0.523508,-0.274404,0.478682', '4301278', '25928048', '30162520', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3148877', '致命弯道3', '恐怖', '人迹罕至的森林中，四个乘舟沿河漂流的年轻人被一名畸形的食人猎手袭击，食人狂用弓箭和陷阱将他们猎杀殆尽，只有一名名叫爱丽丝（Janet Montgomery 饰）的姑娘侥幸逃脱。几乎与此同时，西弗吉尼亚州的葛夫顿监狱中，狱警尼特（Tom Frederic 饰）和搭档接到了一项任务：将墨西哥裔犯人查韦斯（Tamer Hassan 饰）等人转移到另一所监狱。为了防止查韦斯的同伙于路劫车，监狱安排卧底乔装成犯人与查韦斯同行，然而意外还是发生了，囚车在荒凉的山路上被食人狂驾驶的车子撞下悬崖……囚犯们夺走枪支反客为主，尼特因为熟悉地形而担任向导，大难不死的爱丽丝出现在这支混合囚犯与狱警的队伍前面，她带来了食人狂的信息，夜色深锁的密林中，疯狂而又漫长的一夜刚刚才开始……©豆瓣', 'Tom Frederic', '德克兰·奥布莱恩', 6.2, 20022, 'tt1261978', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1752177004.jpg', 3.5, 16.8, 52.6, 18.2, 8.9, '0.446865,-0.258615,-0.411418,0.626057,0.026697,0.059319,1.036839,-0.033200,-0.445492,-0.137093,0.515855,0.556267,0.046460,0.057484,0.396819,-0.014236,-0.437892,-0.616468,-0.445334,-0.193149,-0.835625,-0.296344,-0.286652,-0.283020,0.106654,-0.289799,0.766782,0.206334,-0.057236,0.547801,0.202876,0.370901,-0.608522,0.383756,-0.309402,-0.027551,0.421072,-0.344430,-0.007270,0.171482,-0.362633,-0.465660,0.006753,-0.051091,-0.049386,0.431159,0.982475,-0.174133,-0.064050,-0.089767,-0.068251,-0.537662,0.100657,0.029783,0.487614,-0.022502,0.017710,0.182431,-0.124076,-0.028133,-0.059280,-0.076230,-0.541481,0.120966,-0.054764,0.048085,-0.399545,0.270453,0.101125,-0.045448,0.202972,-0.224623,0.190858,0.053049,0.124763,0.232063,-0.170205,-0.131994,-0.600618,-0.036528,0.558667,-0.325304,-0.183071,0.083949,0.070108,-0.579078,0.159126,-0.045723,-0.191256,-0.147718,0.532661,0.045037,-0.384770,-0.013623,-0.675873,0.156620,-0.390402,-0.243115,-0.246530,-0.197239,-0.549916,-0.720941,0.136732,-0.047586,-0.178523,0.363247,0.048076,0.185954,0.390998,-0.494425,0.273318,0.714452,0.079605,-0.265533,0.422612,-0.225041,0.232512,0.000219,0.088172,0.098366,0.436290,0.601853,0.292991,0.355377,-0.611727,-0.135037,-0.496190,0.289958', '21619567', '20451118', '1467779', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3148956', '太空运输', '科幻', '23世纪中叶，地球已进入全面崩溃的阶段，战争和传染病让这颗原本美丽的蓝色星球破烂不堪，人类被迫离开赖以生存的家园，远赴外太空寻找新的栖息地。凭借TSA先进的技术，木卫五成为充满希望的新兴乐土。在此之后，大批地球人乘坐飞船前往木卫五，地球逐渐被人遗忘。然而就在此时，不断有人起来反抗，声称要推翻TSA利用机器对人类的麻醉和统治，并据此不断向空间站发起恐怖袭击。美丽的劳拉·波特曼博士（Anna-Katharina Schwabroh 饰）随一艘货船前去空间站看望亲人。在长达4个月的旅途中，大部分人需进入睡眠状态。劳拉担任了值班的任务，然而在这静寂的飞船里，似乎有其他人在暗中窥视着她。一桩桩阴谋渐渐浮出水面……©豆瓣', '马丁·拉波德', 'Ivan Engler', 6.3, 7491, 'tt0381940', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1762323094.jpg', 2.6, 14.1, 52.9, 24.3, 6.1, '-0.025685,0.419027,-0.972527,0.517005,-0.075040,0.123058,0.692803,-0.091874,-0.424871,-0.080863,0.106058,0.713931,0.062784,-0.001816,0.383326,0.014973,-0.423524,-0.388814,0.037308,-0.330901,-0.467629,-0.414284,-0.408715,-0.453166,0.004802,-0.586817,0.878230,0.512006,-0.146692,0.444415,-0.273171,0.178278,-0.313169,0.489219,-0.184009,-0.211838,-0.052484,-0.213387,-0.318044,0.379976,-0.344726,-0.080247,0.028014,-0.007010,-0.168806,0.283061,0.887924,-0.474223,-0.054035,-0.301802,0.231365,-0.428577,0.048141,0.005660,0.609281,0.252871,-0.308117,0.132125,-0.310992,0.254275,0.225880,-0.168825,-0.583164,0.065105,-0.031775,0.100022,-0.414226,0.296762,-0.018787,-0.026584,-0.035987,-0.245262,0.390676,0.587270,0.021130,0.467976,-0.228193,0.294764,-0.568678,0.095600,0.638939,0.134016,-0.427137,0.276433,-0.050015,-0.254297,-0.223506,-0.308578,-0.236100,-0.461817,0.225773,0.188707,-0.339041,0.350325,-0.697948,0.466388,-0.125886,-0.550343,0.089178,-0.303575,-0.117702,-1.013878,-0.063015,-0.038913,0.032278,0.346920,-0.071367,-0.181977,0.693791,-0.744157,0.242058,0.658783,0.397223,-0.549244,0.618315,-0.168630,0.126478,-0.257715,-0.004513,0.430320,-0.023653,0.743549,-0.128446,0.169198,-0.153653,0.149741,-0.531011,0.360341', '1307897', '2159244', '3871833', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3149087', '爱情的牙齿', '剧情', '几十年以来，钱叶红（颜丙燕 饰）从懂得爱、遇上爱、到最后对爱的惘然和麻木，她一直用疼痛去理解爱情的面貌。70年代末，她还是一个十几岁的学生领袖，在那个男女绝不能私下交往的年代，她收到了一封男生的情信。钱叶红公开信件，让男生受尽奚落。男生拿起砖头在她背上重重拍下，给钱叶红留下了终身的疼痛，然而，男孩却在之后不久意外过世。大四，钱叶红被一个已有妻儿的男人的魅力所吸引，不慎怀上孩子。为了不影响男人的前途，她让男人亲手打掉腹中孩子，但是，事情还是败露了，她被退回原籍。对爱情心灰意冷的钱叶红此时对爱情已经失望，只想找一个现实的结婚对象，然而太过现实，却让她陷入了新的疼痛。©豆瓣', '颜丙燕', '庄宇新', 7.7, 28037, 'tt1258623', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1510158030.jpg', 0.4, 2.3, 27.5, 50.9, 18.8, '0.120988,0.305329,-0.683102,0.282305,-0.506825,-0.324203,0.851284,0.039866,-0.534600,-0.122896,0.184095,0.695230,-0.128486,0.333930,-0.000169,0.171237,-0.034562,-0.729234,0.227921,-0.218814,-0.378072,-0.199607,0.086099,-0.211619,-0.379902,-0.363179,0.773619,0.129283,-0.255013,0.218684,0.388573,0.065165,0.150052,0.735065,-0.258533,0.136642,-0.195947,0.056034,-0.222833,-0.038025,0.233641,-0.454871,-0.123703,0.353257,-0.376747,0.382101,0.739736,-0.046112,-0.218204,-0.060563,0.525059,-0.313508,-0.324774,0.270810,0.109775,-0.048704,0.097117,-0.015329,-0.091497,-0.160262,0.239146,0.047647,-0.477803,-0.159395,0.086513,0.165268,-0.664787,0.697476,-0.420663,0.198058,-0.019504,-0.271821,0.075685,0.131916,0.173813,0.455826,-0.462739,0.148194,-0.218544,0.180251,0.824966,-0.068627,-0.196568,0.445739,-0.445350,-0.434051,-0.013159,-0.267673,-0.723730,0.191767,0.286598,0.152254,-0.562814,0.140893,-0.370101,-0.018224,-0.082299,-0.024873,0.045365,-0.661296,-0.228779,0.177478,-0.274852,-0.279494,-0.618841,-0.060859,0.210521,-0.245804,0.762011,-0.563690,0.333928,0.641328,0.401625,-0.543299,0.658300,0.278390,-0.063402,-0.236596,-0.044734,0.461809,-0.019664,0.149480,0.213653,0.199854,-0.321229,-0.000591,-0.414461,0.556555', '26245360', '25917973', '3262939', '3504940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3150346', '考死：血之期中考试', '悬疑', '五月，对于准备高考的学生来说所剩时间不多了，期中考试刚刚结束，新一轮的排名出来。姐妹淘姜伊娜（南圭利 饰）和明孝（孙云恩 饰）分列第五和第四名，成绩优秀。同班男生姜贤喜欢伊娜，知道她喜欢听歌，送给她一个mp3，更约她们周五晚去参加party。周六开始就要开始尖子生特训，这是最后的欢乐。那是愉快的一个晚上。5月24日，周六，尖子生特训班开始。惠闵却不见了，突然所有的电视机都转播出惠闵被困在密闭鱼缸里的画面，一把声音通过广播传出来，让大家重考一次期中考，并且答对所有考题，考试才能结束，如果不能及时解答，学生将一个接一个地死去。学校的通讯已经被全部切断，妄图外出学校求救的老师也都死去。班主任黄昌旭（李范秀 饰）让学生们不要慌，大家一边答题一边试图寻找失踪的学生，然而不是由于解答超时就是没有解答出来，学生接二连三地死去。伊娜推断出死亡顺序是按照期中考试排名得出的，下一个要死的人就是明孝。伊娜安慰早已慌乱的明孝，一边努力寻找答案，姜贤一路守护着伊娜。死去的人越来越多，题目依旧叫人匪夷所思，伊娜通过一个谜语推断出这起凶杀案跟2年前死去的好友智媛（尹晶喜 饰）有关。', '李凡秀', '尹鸿承', 6.4, 35216, 'tt1438522', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p823683705.jpg', 2, 11.9, 55.2, 24.5, 6.5, '0.306176,-0.114455,-0.278426,0.331133,-0.074474,-0.142077,0.454034,-0.288628,-0.262426,-0.313012,-0.174341,0.230015,-0.419042,0.622988,0.260071,-0.275835,-0.449118,-0.727374,-0.132482,-0.371901,-0.391417,-0.555914,0.293676,-0.045186,-0.035625,-0.179727,0.486120,0.068438,0.076145,0.589348,0.248404,-0.087760,0.089163,0.244902,-0.136308,-0.204581,-0.012268,-0.036750,-0.035810,0.253771,0.104105,-0.202460,-0.286798,0.116691,0.361472,0.246812,0.568689,-0.135635,0.039068,0.238754,0.569154,-0.283543,-0.279538,0.008081,0.425704,0.224296,0.371684,0.109560,0.009248,0.245430,-0.056153,-0.165339,-0.670805,0.085616,0.060050,0.214288,-0.223584,0.348556,-0.068768,0.179800,0.287728,-0.403003,0.130252,0.199342,0.172597,0.404120,-0.358543,-0.166578,-0.316133,0.197779,0.593455,-0.157569,0.026168,0.104244,0.161028,-0.324161,0.230569,-0.013132,-0.149139,0.312908,0.137984,0.178463,-0.046758,-0.026775,-0.129371,-0.016914,-0.135433,-0.610230,0.047527,-0.411980,-0.228592,-0.571301,0.203501,0.223198,-0.267156,0.252739,-0.065213,-0.300631,0.926367,-0.761479,0.220666,0.456740,0.307643,-0.359941,0.468896,0.251909,0.248051,-0.269203,0.089945,-0.254206,0.025790,0.325272,0.010713,0.478576,-0.088053,-0.218424,-0.637366,0.160318', '25922902', '3811356', '5403927', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3150816', '终极面试', '悬疑', '某实力雄厚、背景神秘的大集团展开公开招聘，经过激烈角逐，最终有8名精英男女入围最终测试。他们被带入一间近乎全封闭的房间，在测试期间只有三条规则：1）禁止与考官和警卫交谈；2）禁止污损考卷；3）禁止离开房间。违反其中一条规则，将丧失考试的资格。应聘者面前的考卷是白纸一张，却发贸然落笔也是污损考卷的一种。在各种奇怪的规则之下，这几位精英变得手足无措，个性张扬的白人男子（卢克•梅布利 Luke Mably 饰）率先提议应试者们要共同合作，解决问题。拥有不同背景的男女看似走到一起，却不知机关暗藏其中。与其说是一场激烈的就业测试，毋宁说是一场人性与智慧的大考验……©豆瓣', '卢克·梅伯利', '斯图尔特·哈泽尔丁', 6.9, 82634, 'tt1258197', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p508189927.jpg', 1.6, 8.2, 44.4, 35.8, 10.1, '0.559725,0.235783,-0.504500,0.678594,-0.035916,0.248942,0.660083,0.030804,-0.436450,-0.213620,0.419478,0.593175,-0.353353,0.154741,0.211855,-0.591945,-0.170956,-0.618552,-0.370352,-0.166480,-0.501688,-0.824771,-0.003606,0.062824,-0.129331,-0.281298,0.729628,0.046381,-0.561114,0.336729,0.311561,0.043355,-0.436999,0.075162,0.036307,-0.503104,0.328726,0.112735,-0.208314,-0.104325,-0.264843,-0.055109,-0.414145,-0.008075,0.178510,0.401142,0.393531,-0.152266,-0.157282,0.268985,0.477630,0.019728,-0.351055,0.281524,0.568121,0.204972,0.089488,0.339862,0.034183,0.275685,-0.042704,-0.207838,-0.781316,-0.155987,0.184895,0.295448,-0.275916,0.513502,0.130772,-0.309495,-0.141687,-0.107340,-0.189933,0.215924,0.428733,0.267220,0.280097,-0.096226,-0.363905,-0.073255,0.503228,-0.032553,-0.368303,-0.009557,-0.320086,-0.695771,-0.220869,-0.324503,-0.206494,-0.091517,0.328050,0.276460,-0.021985,-0.103615,-0.837045,0.132030,-0.158267,-0.082292,-0.189723,-0.366619,-0.021526,-0.871028,-0.214659,-0.233507,-0.305033,0.454126,0.150321,-0.197716,0.857619,-0.810882,-0.046194,0.161160,0.389476,-0.506558,0.527272,0.429512,0.297535,-0.193750,-0.254794,-0.197649,0.283574,0.264675,-0.113862,0.482714,0.068954,-0.021141,-0.316763,0.153663', '27602116', '25863940', '20388224', '30465281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3154003', '天佑鲍比', '剧情', '本片根据真人真事改编。Bobby（瑞恩·凯利 Ryan Kelley 饰）是一个善良、虔诚的少年，有爱他的家人。但在他向家人坦白自己的性倾向后一切改变了。母亲Mary（西格妮·韦弗 Sigourney Weaver 饰）认为同性恋会下地狱的训诫，想尽办法矫正儿子。而Bobby的痛苦与日俱增。在满20岁生日前Bobby认识了开朗青年David，可Mary拒绝接受，并以有一个同性恋儿子为耻。Bobby伤心的离开家最后选择死亡来结束内心的折磨。他的死彻底唤醒了家人，尤其是Mary，她在无尽的悔恨中开始接触同性恋人群，参加PFLAG小组，与神职人员探讨圣经解释。在翻阅儿子的日记后，她开始直面自己认同儿子。失去儿子的母亲在倾盆大雨中失声痛哭，雨水和泪水将固执、偏见和不理解洗刷得一干二净。Mary此后将毕生投入到同志维权事业中，帮助那些和Bobby一样的少年。©豆瓣', '西格妮·韦弗', '拉塞尔·穆卡希', 8.9, 46618, 'tt1073510', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1662271271.jpg', 0.2, 0.7, 8.7, 33.7, 56.7, '0.111255,0.054152,-0.745951,0.523596,-0.279263,-0.351425,0.842349,-0.025445,-0.435130,-0.090040,0.173647,0.753050,0.076963,0.331481,0.257812,-0.020944,-0.261039,-0.695048,-0.223563,-0.072351,-0.262137,-0.683195,0.054774,-0.172959,-0.245474,-0.395348,0.687564,-0.020015,-0.105820,0.432769,0.343919,0.221092,0.142443,0.421242,0.000686,0.068111,-0.152670,0.042945,-0.256573,0.146373,0.275089,-0.039834,-0.081466,0.297511,-0.233980,0.345629,0.718719,-0.319689,-0.230927,-0.021786,0.693937,-0.438627,-0.070006,0.407282,0.152180,0.158699,0.148069,0.262162,-0.079694,-0.193064,-0.052636,0.013265,-0.674632,-0.209346,0.134876,0.145182,-0.793461,0.525263,-0.011447,-0.045927,0.264718,-0.382525,0.202847,0.162019,0.117407,0.617382,-0.361097,-0.123623,-0.287634,0.349508,0.676781,-0.186372,-0.148632,0.212025,-0.369128,-0.103070,0.193055,-0.227206,-0.638541,-0.035456,0.034604,0.130722,-0.376992,0.508634,-0.268212,-0.106707,-0.223555,-0.069036,0.016806,-0.627206,-0.150662,-0.200511,-0.441349,-0.260247,-0.335742,-0.363120,-0.072926,-0.546077,0.884277,-0.934665,0.323646,0.444940,0.305480,-0.530381,0.663541,0.209708,0.043048,-0.296053,0.129878,0.557366,0.113376,0.046074,0.078038,0.179834,-0.005992,0.268557,-0.310160,0.443848', '3445516', '35048413', '35030151', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3154392', '永恒记忆', '剧情', '20世纪初的瑞典，社会动荡，物质生活与精神生活双双匮乏。玛丽亚（Maria Heiskanen 玛丽亚·海斯卡尼 饰）是个普普通通的家庭主妇，操持着一个并不富裕的家，一次偶然的博彩，让她中了一台相机，她的人生就此改变。她开始偷偷学习拍照，并对此非常着迷，她拍下孩子成长的  样子，随手发现的美景，慢慢的，她开始有能力为邻居拍照，赚点钱，他们也对照片特别满意，国王来访时，她也被请去拍照……当然，这一切要背着她的酒鬼丈夫。经常冲印照片令玛丽亚与当地小照相馆老板佩特森（Jesper Christensen 饰）熟悉起来，他是她的伯乐，一直称赞她的天赋，鼓励她拍下去，二人产生淡淡的情愫，最终发乎情止乎礼，湮没在时光里，唯有玛丽亚拍下的美妙照片，至今留存……本片是瑞典史上首位女性摄影师玛丽亚·拉森的传记片。©豆瓣', '玛莉亚·海思坎恩', '扬·特洛尔', 8.4, 10925, 'tt0961066', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2458917097.jpg', 0.1, 1, 13.7, 47.5, 37.6, '0.207877,0.107828,-0.602728,0.645882,-0.198111,-0.164293,0.737411,0.051658,-0.446478,-0.269694,0.175649,0.852060,-0.180788,0.361742,0.100791,0.152889,-0.356570,-0.610468,0.037612,0.063680,-0.230830,-0.149433,-0.330545,-0.137761,-0.344415,-0.272751,0.378217,-0.088323,-0.115588,0.436948,0.084298,0.018016,0.129158,0.408792,-0.359262,0.031128,-0.260456,0.029978,-0.242335,-0.022245,0.056171,-0.276618,-0.186336,0.232231,0.133548,0.224589,0.735542,-0.076470,-0.128231,0.006181,0.421827,-0.020373,-0.108550,0.092328,0.060584,0.170243,0.165906,0.038560,-0.321827,0.020469,0.026100,-0.010544,-0.530217,-0.086236,-0.011464,0.113133,-0.440916,0.500625,-0.056812,-0.048777,0.017462,-0.200368,0.099962,0.129095,0.136071,0.329050,-0.049715,0.027276,-0.321153,0.356893,0.483682,0.168063,-0.213004,0.626404,-0.581726,-0.364035,-0.027151,-0.101981,-0.654260,0.058758,0.263944,0.024528,-0.036250,0.203851,-0.574855,0.256782,-0.058477,-0.206780,0.014763,-0.433509,-0.049097,-0.688362,-0.204244,-0.486036,-0.462042,-0.197253,0.081250,-0.514136,0.846889,-0.637175,0.036205,0.661515,0.182628,-0.374218,0.818550,0.145525,-0.089605,-0.167314,-0.249446,0.274288,-0.072703,0.160392,-0.040771,0.306075,0.027213,-0.121429,-0.145920,0.651396', '30162520', '3811356', '1309161', '3927750');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3154822', '哆啦A梦：新·大雄的宇宙开拓史', '动画', '大雄最近一段时间经常被奇怪的梦困扰，接着，他房间中央的榻榻米下面还不断出现响动。某天，榻榻米被撞开，里面跑出一个像兔子一样的生物。它的名字叫恰米，是外星男孩罗布姆的宠物。罗布姆和亲人、朋友生活在名为可亚可亚的星球，这里盛产奇妙的浮游矿石。邪恶的浮游矿石工业公司为了霸占这些矿藏，不惜使用各种卑鄙手段企图将罗布姆这群早期开拓者赶走。罗布姆乘坐的飞船就是遭到浮游矿石工业的袭击，偶然引发错乱和大雄的房间连在了一起。哆啦A梦和大雄修好了罗布姆的飞船，还和可亚可亚星的人民成为好朋友。与此同时，浮游矿石工业继续他们罪恶的计划，善良正直的大雄决心帮助外星朋友守卫他们的家园……©豆瓣', '水田山葵', '腰繁男', 7.9, 7851, 'tt1264885', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p903758495.jpg', 0.4, 1.8, 25.6, 44.7, 27.4, '0.351364,0.082029,-0.627395,0.273819,-0.067832,0.085398,0.472478,0.085449,-0.523907,-0.208645,-0.036223,0.502963,0.095799,0.028602,-0.048511,0.169031,-0.407834,-0.526474,-0.286578,0.008201,-0.589997,-0.365503,-0.297928,-0.539060,-0.242646,-0.614302,0.167671,0.134909,-0.132508,0.317845,0.085579,0.506295,-0.279519,0.286854,-0.343314,0.004647,0.108093,-0.085319,-0.247288,0.210992,-0.365851,0.222315,0.230942,0.061032,0.174866,0.064128,0.581914,-0.449173,0.189509,-0.181536,0.010840,-0.248059,-0.042591,-0.067176,0.403704,-0.216966,0.051149,-0.174062,-0.262052,-0.017218,0.310716,-0.220743,-0.747312,-0.282146,-0.160065,0.139984,-0.408737,0.141256,0.170538,0.090781,0.256399,-0.208956,0.279670,0.157972,0.398835,0.455509,-0.111628,0.195793,-0.300073,-0.175604,0.543146,-0.067786,-0.078651,0.302585,-0.435963,-0.502288,-0.258704,-0.050095,-0.278140,-0.264834,0.328326,-0.217888,-0.118379,0.357246,-1.120210,0.093983,-0.155489,-0.149039,0.181336,-0.088616,-0.255457,-0.575295,0.293216,-0.138126,0.038538,0.377201,-0.127456,-0.074856,0.770586,-0.636942,0.299454,0.720941,0.665311,-0.061396,0.617199,-0.288969,-0.045729,-0.132532,-0.121666,0.151232,0.325501,0.333508,0.032965,0.161494,0.207441,-0.005998,-0.486287,0.338546', '26290398', '6982558', '1292680', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3154908', '五年之约', '喜剧', '在众人眼里，汤姆（杰森·席格尔 Jason Segel 饰）和薇莱特（艾米莉·布朗特 Emily Blunt 饰）是天设地造的一对，他们经过1年的爱情短跑，都自认为是世界上最了解对方的那个人，两人闪电订婚。薇莱特渴望有一个完美的家庭，但同时也希望能够有自己的事业，她收到了密歇根大学的一个梦寐以求的职位，但前提是汤姆必须放弃现在的工作，两人一起迁往密歇根。汤姆同意了，但在密歇根的生活并不如他所想得那么美好，一方面，专业技能很强的他居然只能在小吃店找到一份仅够糊口的工作，另一方面，薇莱特在职场上屡屡获得成功，两人的距离越来越远。矛盾随着薇莱特的步步高升日益激化，两人的婚礼年复一年的推迟着，而正当他们两人下定决心要举行婚礼的时候，一个第三者的吻却给两人的感情制造了难以愈合的伤痕。©豆瓣', '杰森·席格尔', '尼古拉斯·斯托勒', 6.8, 9442, 'tt1195478', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1443163715.jpg', 1.2, 8.5, 50.3, 31.3, 8.7, '0.462943,-0.222293,-0.721906,0.806605,-0.177687,-0.282365,0.738710,0.216275,-0.369406,-0.112713,0.193428,0.739488,-0.130534,0.256676,0.106231,-0.051579,-0.139384,-0.771273,0.243258,-0.377489,-0.148690,-0.736718,-0.208575,-0.049387,-0.205130,-0.159025,0.793240,0.094411,0.185974,0.598180,0.080428,-0.044654,0.306446,0.526452,-0.347187,-0.215241,-0.022416,-0.011808,-0.299026,0.158417,0.323478,0.013393,-0.410557,0.417500,0.146524,0.290160,0.545120,-0.134281,-0.049420,0.189577,0.375141,-0.375941,0.087813,0.145922,0.302616,-0.241446,0.229559,0.328317,-0.339918,-0.048220,0.106589,0.005160,-0.954450,0.117117,0.007880,0.003621,-0.659297,0.652759,-0.012332,-0.037596,0.058480,-0.320293,0.084410,0.618591,0.160500,0.305614,-0.383498,-0.061770,-0.605587,0.093147,0.917502,0.041078,-0.454409,0.575334,-0.478270,-0.394856,-0.343132,-0.162031,-0.655382,-0.084532,0.361032,0.187680,-0.223993,0.162114,-0.515359,0.051088,-0.242722,-0.293098,0.010684,-0.471983,-0.021580,-0.609027,-0.334842,-0.541394,-0.522287,0.007514,-0.146607,-0.530182,0.744365,-0.981978,0.009509,0.702008,0.301881,-0.561160,0.824289,0.250739,0.368831,-0.097472,-0.305356,0.137518,-0.205568,-0.038757,0.066037,0.481130,0.188165,-0.068603,-0.381987,0.713518', '35030151', '4604803', '26021055', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3154909', '整编特工', '喜剧', '简（凯瑟琳•海格尔 Katherine Heigl 饰）一家人乘飞机去法国尼斯旅行，途中父母谈起女儿的情事，令她很是不爽。在海滨宾馆的电梯间，简邂逅了身着泳装的帅哥斯宾塞（艾什顿•库彻 Ashton Kutcher 饰），两人一见钟情。他们相约在酒吧共进晚餐，但是刚好简的父母路过。简为了躲避他们的目光，情急之下编造了一个关于父亲的丑事，并不断圆谎。但随着她和斯宾塞情感加温，她还是对他袒露了实情。而斯宾塞却隐瞒了自己是杀手的事实。本来，斯宾塞要金盆洗手，但是最后一个任务，竟然就是对付简的父亲，自己未来的岳父。这令斯宾塞左右为难。与此同时，在这对如胶似漆的恋人周围，突然冒出了很多杀手，其中有喝得酩酊大醉的酒鬼，身材惹火的性感女郎，甚至邻居社区的小夫妻，纷纷对他下手……©豆瓣', '阿什顿·库彻', '罗伯特·路克蒂克', 6.2, 36076, 'tt1103153', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p454078045.jpg', 2.5, 15, 55.9, 21.7, 4.9, '0.393304,-0.290092,-0.617835,0.507989,-0.138362,-0.382550,0.889388,0.160048,-0.476099,-0.427113,0.170077,0.906278,-0.362454,0.250553,0.325291,0.214635,-0.223362,-0.517423,0.201974,-0.155338,-0.208538,-0.456860,-0.107516,-0.489453,-0.027528,0.109083,0.227670,-0.029543,-0.240285,0.340468,0.478505,0.174666,-0.124431,0.637059,-0.190072,0.130208,0.061853,0.113611,-0.210387,-0.056661,0.137779,-0.280113,-0.157560,0.355536,0.125474,0.546771,0.488888,-0.102712,-0.208435,0.095871,0.051601,-0.278511,0.013147,0.111709,0.195188,-0.277497,0.415746,0.111815,0.121048,-0.298326,0.074934,-0.017163,-0.373297,0.174839,0.089121,0.151247,-0.554613,0.523164,-0.207310,0.078118,0.078178,-0.276466,0.041243,0.253244,-0.013646,0.229141,-0.057226,-0.142809,-0.612535,0.251951,0.553090,0.339985,-0.036019,0.369787,-0.444635,-0.368121,-0.072902,0.165003,-0.451145,-0.088962,0.316007,0.039998,-0.130579,0.252149,-0.349497,-0.234021,-0.255723,0.119247,0.014530,-0.580810,-0.059054,-0.579034,-0.041220,-0.629760,-0.388018,-0.049990,0.019714,-0.138063,0.577560,-0.781988,-0.050005,0.597602,0.324421,-0.537835,0.694556,0.272842,0.211766,-0.195746,-0.086627,0.200286,-0.039455,0.016211,0.202992,0.449635,0.078629,-0.045477,-0.337878,0.349989', '1308755', '1302384', '1309172', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3155477', '爱有来生', '剧情', '小玉（俞飞鸿饰）与丈夫秦言（涂松岩饰）在儿时旧友雅萍（李佳饰）的帮助下搬入山顶一处僻静宅院。秦言外出代课，小玉独自打理庭院，尤其对院中的银杏树倾心。某晚小玉沏茶独自等待雅萍来访，却突遇一和尚打扮的男鬼阿明（段奕宏饰）树下现身。阿明说自己已在银杏树下等人五十载。经小玉同意，阿明开始缓缓讲述五十年前的一段经历。阿明的哥哥（姚橹饰）作为山寨头领，在一次仇杀中放走仇家六岁半的儿子。十几年后，弟弟阿明爱上了一个突如其来的神秘女子阿九（俞飞鸿饰）。阿明百般呵护却依然无法赢得阿九的芳心。绝望中阿明出家为僧，阿九却又不离不弃，直到有一天帮派火拼，一切因果真相大白却又无可挽回……©豆瓣', '俞飞鸿', '俞飞鸿', 7.7, 80954, 'tt1487861', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p823966534.jpg', 0.8, 3.9, 28.9, 43, 23.4, '-0.050642,0.128438,-0.557673,0.321448,-0.043327,-0.392714,0.817631,0.042760,-0.448520,-0.194312,0.519467,0.387453,-0.087064,0.560460,0.214617,-0.054293,-0.145251,-0.523078,-0.148202,-0.148020,-0.334174,-0.161876,-0.117602,0.048584,-0.206632,-0.069679,0.363685,0.119649,0.289749,0.535434,0.164729,-0.065670,-0.283853,0.374658,-0.180791,0.210824,0.120917,0.125589,-0.421987,-0.127616,-0.318226,-0.481619,-0.299260,-0.132824,-0.172713,0.163101,0.663929,-0.211920,-0.202699,-0.274362,0.158931,0.165062,0.047993,0.022005,0.379273,-0.123094,0.330558,0.301741,-0.242254,-0.113042,-0.131544,0.010574,-0.170992,0.145271,0.143471,0.041670,-0.664032,0.262488,0.069498,0.188840,0.028429,-0.400800,-0.156262,0.162460,0.364317,0.275513,-0.275664,-0.076137,-0.104471,0.091329,0.486883,-0.060225,0.184926,0.298140,0.088056,-0.212164,0.279206,0.194287,-0.443470,-0.045665,0.177096,-0.116130,-0.181838,0.039719,-0.163052,0.142673,-0.345187,0.047977,-0.050926,-0.454569,-0.161813,-0.400172,-0.019623,-0.177519,-0.279606,0.264750,0.174633,-0.142436,0.449752,-0.433386,0.436198,0.212862,0.135616,-0.200661,0.326047,0.066069,0.346228,-0.233024,0.141784,0.378437,-0.315432,0.219824,0.094220,0.230061,-0.189686,0.266589,-0.534799,0.107551', '21619567', '1773217', '21348112', '2365260');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3155839', '美丽的人', '剧情', '因母亲亡故，16岁的少女茱妮（Léa Seydoux 饰）转学至一所新的高中，在与她同班的堂兄马提西亚（Esteban Carvajal-Alegria 饰）的介绍下，她很快结识了一班新朋友。美丽的茱妮吸引了男孩们的目光，连一向害羞内向的奥图（Grégoire Leprince-Ringuet 饰）也鼓起勇气向她表白，两人随之陷入热恋。在意大利语课上，茱妮被曼妙委婉的歌剧感动，她的热泪和忘在桌子上的相片也令意大利语教师奈莫斯（Louis Garrel 饰）心有所动。当晚，奈莫斯与女友玛丽（Agathe Bonitzer 饰）分手，开始了对茱妮的追求……©豆瓣', '路易·加瑞尔', '克里斯托夫·奥诺雷', 7.4, 8264, 'tt1263778', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2461364109.jpg', 0.5, 4.3, 35.7, 42.1, 17.5, '0.628693,0.051349,-0.745571,0.528085,-0.138619,-0.266032,0.738811,0.270544,-0.204443,-0.142582,0.080974,0.826411,-0.533645,0.556977,0.450460,0.096776,-0.211982,-0.886316,-0.014513,-0.067664,-0.160007,-0.261691,0.040311,0.170417,-0.133444,-0.477386,0.356278,-0.186572,-0.165311,0.760013,0.367452,0.225979,0.138840,0.119367,-0.137017,0.118575,-0.072881,0.048157,0.014086,0.029247,-0.119069,-0.329988,-0.155697,-0.002770,-0.106813,0.357364,1.008563,0.119735,-0.046743,0.165724,0.541350,-0.011466,0.096190,0.278814,0.403967,0.241633,0.084963,0.018786,-0.263395,0.077614,0.093136,0.047612,-0.340482,0.115374,0.086476,0.136179,-0.717261,0.699840,-0.084226,-0.097151,0.245950,-0.366383,-0.035704,0.146057,-0.241873,0.489792,-0.126307,0.084870,-0.078364,0.351717,0.431299,0.425456,-0.116286,0.282912,-0.248209,-0.411689,0.084266,0.123737,-0.424907,0.042629,0.475560,0.030273,0.102375,0.229474,-0.689004,-0.308594,-0.062186,-0.144222,0.186651,-0.643478,-0.259843,-0.470189,-0.242775,-0.532702,-0.435610,-0.179253,-0.015326,-0.082225,0.843795,-0.985606,0.081069,0.328375,0.156620,-0.206525,0.633603,0.188849,-0.049244,-0.016077,-0.146412,0.317089,-0.046576,0.157192,0.058271,0.523893,-0.166833,0.162795,-0.489505,0.295542', '1307146', '1292219', '24839498', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3155961', '无处的男孩', '剧情', '本片讲述了约翰·列侬的少年故事。列侬（亚伦·泰勒-约翰逊 Aaron Taylor-Johnson 饰）从小被姨妈Mimi（克里斯汀·斯科特·托马斯 Kristin Scott Thomas 饰）收养，直到15岁才与亲生母亲Julia相认，他的姨妈更和他的母亲展开了对他的争夺。列侬的母亲带着列侬走上了音乐之路，给他买了一把吉他。后来列侬认识了和他差不多年纪的保罗·麦卡特尼（托马斯·桑斯特 Thomas Sangster 饰），保罗矫正了列侬的吉他技法。列侬的生活充满了挣扎和矛盾。直到有一天，列侬的母亲车祸死去，列侬下定决心离开Mimi，离开他从小生长的利物浦，去探求更广阔的天地.....©豆瓣', '克里斯汀·斯科特·托马斯', 'Sam Taylor Wood', 7.5, 7182, 'tt1266029', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2661605099.jpg', 0.5, 2.8, 35.4, 46, 15.4, '0.170869,-0.359492,-0.585600,0.456065,-0.190267,-0.833066,0.873354,0.331787,-0.302958,-0.263072,0.079841,1.052455,-0.124561,0.473213,0.280199,0.040683,-0.385926,-0.669356,0.363934,-0.064076,-0.232556,-0.758864,0.149901,-0.067550,0.007152,-0.262946,0.280847,-0.385138,0.034267,0.672049,0.118051,0.083548,0.377447,0.440781,-0.177291,0.700624,0.301943,-0.221650,-0.183772,0.158750,0.511549,-0.174918,-0.179623,0.176041,-0.122073,0.417990,0.547140,-0.164512,0.458032,0.010380,0.181736,-0.168885,0.059286,0.170745,-0.059497,-0.083440,0.063128,0.340610,-0.367600,-0.114034,-0.230010,-0.250323,-0.131066,0.257134,-0.077786,0.094658,-0.811599,0.393435,-0.273838,0.033944,0.283256,-0.330981,0.117746,0.310183,-0.160515,0.455110,-0.154439,-0.073242,-0.426043,-0.042971,0.290288,-0.244960,0.089078,0.419062,-0.337358,-0.280546,-0.309933,-0.152049,-0.648561,-0.075934,0.837420,-0.279703,0.115172,0.345473,-0.613801,-0.325384,-0.173684,-0.176609,0.085771,-0.341613,-0.180629,-0.506884,-0.134353,-0.565088,-0.171410,-0.281943,-0.210475,-0.221568,0.643075,-0.474215,0.274962,0.508944,0.112361,-0.142247,0.509062,-0.176512,0.218973,-0.326334,0.125466,0.769486,-0.011195,0.261903,0.382151,0.507462,0.350758,0.308817,-0.578597,0.777484', '1895119', '1291828', '1297239', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3156032', '三个臭皮匠', '喜剧', '影片由三个小段落组成，每一个小段落自成一章，之间有着微弱的联系。段落一，讲述的是科雷、摩尔、拉里三个婴儿被装载一个旅行包内丢到了孤儿院的门口，一个修女看到了这个包裹，便上前查看。不了却被科雷用“插眼二指禅”戳了个人仰马翻。从此之后，这三个小朋友就在孤儿院里生活了下来。段落二，讲述的是这三个人长到了40来岁，变成了三个臭皮匠。他们走到了社会上，在社会上闹出的各种各样的喜剧和笑话。段落三，讲述的是三个臭皮匠自娱自乐的故事。只有他们三个人，互相插科打诨，制造喜剧。', '西恩·海耶斯', '博比·法雷里', 6.5, 5441, 'tt0383010', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1620234040.jpg', 4.5, 13.7, 45.1, 25.3, 11.4, '0.707623,-0.132289,-0.458513,0.480291,0.023508,-0.251009,1.204694,0.156834,-0.161689,-0.015283,0.072305,0.745341,-0.652629,0.588470,0.085710,-0.165092,-0.348349,-0.762939,-0.484433,-0.137360,-0.510038,-0.466687,0.004788,-0.014859,-0.365318,0.107335,0.111651,-0.152843,-0.275127,0.186321,0.287236,0.066069,-0.285031,-0.115290,-0.431365,0.652085,-0.024476,-0.118580,0.299548,0.382929,-0.176034,-0.081725,-0.016236,-0.011412,-0.158720,0.465778,0.784549,-0.261358,0.125713,0.036869,0.405638,-0.079376,-0.667237,0.116375,0.233354,0.125237,0.394888,-0.057035,-0.225196,0.115524,0.004125,-0.236182,-0.880863,0.344805,-0.198372,0.324460,-0.926958,0.422848,0.172365,-0.523809,-0.035032,-0.359526,0.249887,0.259413,0.105087,0.573518,-0.009106,0.125808,-0.519327,-0.014598,0.418217,-0.001857,-0.568858,0.342184,0.155120,-0.300264,-0.057204,-0.307994,0.004823,-0.086336,0.645926,-0.268604,-0.181209,-0.178406,-0.896028,0.235859,-0.186742,-0.408465,0.063467,-0.470712,-0.233080,-0.553892,-0.121637,-0.297161,-0.625794,0.419432,0.288489,-0.208718,0.983475,-0.487581,0.094725,0.245260,-0.130037,-0.251953,0.639877,0.089570,0.375259,0.026986,0.494465,-0.226040,0.083286,0.746725,0.341567,0.833017,-0.424989,-0.153933,-0.880751,0.310604', '21619567', '1578663', '1299767', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3156086', '定罪', '剧情', '兄弟肯尼（山姆·洛克威尔 Sam Rockwell 饰）被控谋杀入狱的消息让贝蒂（希拉里·斯万克 Hilary Swank 饰）的内心久久不能平静，她拒绝相信善良的肯尼会犯下如此残忍的罪行，因此，固执的贝蒂决定踏上追寻真相的道路，为肯尼讨回一份清白。可是，事情并不是你想就能够做得到的。贝蒂的高中没有念完，目前也没有固定的工作和薪水，更糟的是，她并非茕茕独立，而是一个带着两个孩子的单身母亲。在生活和社会的双重压力下，贝蒂开始自学法律，在接下来的12年间，从未放弃的她最终获得了法学学位。与此同时，对于肯尼一案的调查也在进行之中，可并不乐观的证据和证词一次又一次的打击着贝蒂的自信。肯尼真的是无辜的吗？事情的真相又是如何呢？©豆瓣', '希拉里·斯万克', '托尼·戈德温', 7.9, 9149, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p663057760.jpg', 0.2, 1.4, 24.1, 54.3, 20.1, '0.218841,-0.020182,-0.682770,0.831524,-0.445962,-0.323313,0.831482,0.041998,-0.558318,-0.283719,0.089487,0.623827,0.170786,0.253116,-0.005265,0.175065,-0.324862,-0.693081,0.238671,-0.114405,-0.113510,-1.096285,-0.221648,-0.354862,-0.130570,-0.371147,0.689391,0.092990,-0.188898,0.235265,0.366532,0.367141,0.323131,0.529302,-0.086629,-0.070324,0.090445,0.197074,-0.309781,0.176030,0.430652,-0.298983,-0.210883,0.606849,0.193867,0.458875,0.411508,-0.441065,-0.283855,0.130724,0.410894,-0.616056,0.156197,0.273047,0.157343,-0.222339,0.281282,0.603326,-0.311483,0.021427,0.119126,-0.013372,-1.004054,-0.156041,0.060265,0.353442,-0.752695,0.446341,-0.408469,-0.118170,0.038163,-0.289276,-0.014559,0.525037,0.409879,0.613661,-0.366477,-0.175132,-0.435226,0.037570,0.697486,0.093125,-0.270080,0.354272,-0.255340,-0.508107,-0.082150,-0.224164,-0.514810,0.152467,0.109659,0.295826,-0.263041,0.349454,-0.219433,-0.030187,-0.337783,-0.397224,-0.034326,-0.635362,0.015165,-0.294563,-0.052804,-0.287829,-0.647041,-0.049518,0.078274,-0.493331,0.572650,-0.897470,0.191406,0.474064,0.384779,-0.766172,0.568687,0.525515,-0.075221,-0.022464,-0.075919,0.200233,-0.052759,0.178262,0.192768,0.283021,0.524886,-0.353529,-0.314005,0.645894', '26678784', '24743015', '1811755', '1295318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3156117', '汉娜', '动作', '位于北极圈附近的冰原森林，生活着一对平凡却有着非凡身手的父女。父亲艾利克·海勒（Eric Bana 饰）曾是受雇于CIA的特工，在上世纪90年代活跃于东欧和中亚等地，具有丰富的经验。然而最终却因为某种原因，令他带着女儿汉娜隐居在这人类罕至的寒冷所在。经过十多年的艰苦磨练，汉娜（Saoirse Ronan 饰）终于成长为拥有广博知识和出色身手的战斗少女。某天，自认已做好准备的汉娜按下了父亲那台信号发射器，不久美国方面便收到消息。艾利克当年的联系人玛丽莎（Cate Blanchett 饰）声称这个消失多年的特工掌握非常敏感的秘密，于是在她的主持下，一场居心叵测的围捕旋即展开。汉娜也已柔弱的身躯投入了血腥的战斗之中……©豆瓣', '西尔莎·罗南', '乔·赖特', 6.2, 27538, 'tt0993842', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1109415955.jpg', 2.9, 17.5, 52.5, 21.2, 5.8, '0.259363,0.149775,-0.779922,0.741660,-0.150880,-0.212565,0.591372,-0.159245,-0.593360,-0.341374,0.340665,0.762364,-0.076757,0.059615,0.240682,0.036445,-0.360910,-0.606586,-0.357939,-0.039186,-0.287548,-0.426450,-0.567887,-0.063566,-0.064256,-0.439680,0.709445,0.143644,-0.356802,0.484944,-0.080354,0.202945,-0.246370,0.315036,-0.321648,-0.259581,0.013260,0.016903,-0.408165,0.156797,0.083324,-0.245923,-0.117276,0.023416,0.078450,0.338581,0.613500,-0.344639,-0.247245,-0.023482,0.325208,-0.123101,-0.162464,0.002820,0.424066,0.091321,0.134153,0.217100,-0.214001,-0.043143,-0.139236,-0.223730,-0.778904,-0.022878,0.226925,-0.071733,-0.517672,0.376241,-0.165630,-0.046307,-0.006587,-0.480742,0.009163,0.420687,0.039284,0.475422,0.077356,0.072109,-0.172840,0.065750,0.558152,0.042826,-0.458568,0.098442,-0.366125,-0.732390,-0.062970,-0.372537,-0.442221,-0.172381,0.269001,0.153014,-0.196612,0.320247,-0.651466,0.353498,-0.203372,-0.211924,0.082752,-0.169427,-0.411565,-0.670766,-0.300581,-0.677954,-0.473576,0.182921,0.011707,-0.158175,0.816222,-0.953619,0.334614,0.353297,0.111466,-0.239832,0.559923,-0.132500,0.100079,-0.004600,-0.163156,0.530815,-0.115380,0.233174,0.009677,0.304327,-0.151406,-0.284727,-0.528907,0.457125', '35144311', '1420088', '3006892', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3156600', '弹道', '动作', '警员徐瑜昌（张孝全 饰）为调查一宗黑枪案件，只身犯险将黑帮人物庞天南之子捉拿。时值民选的最后阶段，调查局方正北与庞天南达成交易：庞天南出人行刺候选人来换回儿子无罪开释。黄营候选人吴志雄在民调中被对手田正远远甩开，普通的宣传战已无法挽回局势，但一则更大的阴谋早已在暗中筹划……庞天南义子金水（林家栋 饰）由越南返回担任杀手，但是他得到的两颗子弹却并无致命的药量，于此同时，失业退伍军人陈二同（廖启智 饰）因生计所迫，收钱在刺杀行动中扮顶罪羔羊。吴志雄在亲民巡游时计划正式启动，金水枪击吴志雄使田正阵营陷入不利局面。这场自导自演的枪击竞选秀牵涉高层利益，令负责此案的孙学仁（任达华 饰）警官与徐瑜昌倍感黑幕重重……©豆瓣', '任达华', '刘国昌', 6.4, 5266, 'tt1265647', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p707807069.jpg', 1.8, 11.2, 56.1, 26.2, 4.7, '-0.080890,0.029066,-0.289390,0.269674,0.124376,0.017419,0.123348,0.479917,-0.502028,-0.364963,0.405792,0.394838,-0.093891,-0.388087,0.268223,-0.508783,-0.116082,-0.528346,-0.285435,0.078232,0.011277,-0.638984,-0.143856,-0.335587,-0.026680,0.138033,0.660235,0.249665,-0.390201,0.356093,0.438108,0.488208,-0.396951,0.395395,0.205749,-0.239236,0.117607,-0.061595,-0.700048,0.126250,-0.036747,-0.729339,-0.103873,0.352371,0.090469,0.516578,0.408337,-0.269526,-0.119360,-0.328677,0.176831,-0.484995,-0.149827,-0.058799,0.555333,0.126455,-0.037715,0.347219,-0.185199,0.016145,0.092997,-0.119940,-0.726193,0.002643,0.282103,0.218739,-0.139084,0.148553,-0.335867,0.172048,-0.054198,-0.155312,0.091613,0.491777,0.329691,-0.083782,-0.159763,0.060565,-0.504196,0.276539,0.682688,-0.197779,-0.060411,-0.212620,0.043813,-0.451216,0.111651,-0.328047,-0.001051,-0.026656,0.310425,-0.039536,0.167987,0.207908,-0.147488,-0.246506,-0.370474,0.154637,-0.027071,-0.053857,0.117371,-0.683681,-0.095571,0.019586,-0.293753,-0.106343,0.192822,-0.161094,0.257150,-0.604731,-0.153242,0.274993,0.232492,-0.534305,0.304155,0.274165,0.509103,-0.262312,-0.255776,-0.158405,0.355360,0.282877,0.144342,-0.102949,-0.330133,-0.419119,0.079340,-0.226951', '30200973', '27073234', '2369613', '26934399');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3157583', '宙斯之子：赫拉克勒斯', '动作', '宙斯之子赫拉克勒斯（道恩·强森 Dwayne Johnson 饰）自幼饱尝人世间难以想象的苦痛与磨练，他完成了神所安排的十二项试炼，创造了万众敬仰的半神传奇。而事实上大力神赫拉克勒斯不过是在奥托力科斯（卢夫斯·塞维尔Rufus Sewell 饰）、安菲阿拉俄斯（伊恩·麦柯肖恩 Ian McShane 饰）、阿塔兰塔（英格丽德·波尔索·贝达尔 Ingrid Bolsø Berdal 饰）等足以托付生命的勇士的协助下走上了耀眼的神坛。英雄和他的伙伴们以雇佣兵的身份游走各地，似乎从来不关心什么才是正义。某天，大力神受雇于色雷斯国国王科杜斯，协助其训练一支无坚不摧的军队，挫败邪恶巫师瑞索斯的叛乱。但随着战争落下帷幕，大力神却被阴谋拉下神坛，不得不去面对内心最苦痛的回忆以及生命中最后的残酷试炼……本片根据史蒂夫·摩尔的漫画改编。©豆瓣', '道恩·强森', '布莱特·拉特纳', 6.1, 27513, 'tt1267297', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2202615085.jpg', 3.1, 17.2, 57.4, 17.4, 4.9, '0.082027,0.145033,-0.311608,0.691820,0.214684,-0.381086,0.601818,0.071447,-0.293434,-0.238837,0.427622,0.683310,-0.003322,-0.052958,0.486577,0.007666,-0.742598,-0.749325,-0.142256,0.005467,-0.194678,-0.368455,-0.414931,-0.106470,-0.136608,-0.505206,0.590494,0.162012,-0.013034,0.191402,0.266024,0.722735,0.003835,0.127692,-0.031439,-0.199734,0.127972,-0.183069,-0.176314,-0.044640,-0.206581,-0.129932,-0.322404,0.420220,-0.032008,0.176352,0.260615,-0.767283,0.485188,-0.323153,0.320459,-0.472356,0.230948,-0.016626,0.014630,0.108084,-0.029531,0.342284,0.177004,0.002890,0.180289,-0.265833,-1.208261,-0.290478,-0.013606,0.089451,-0.604345,0.385687,-0.128619,-0.123750,0.079880,-0.128986,-0.014518,0.343033,0.359865,0.349803,-0.210148,-0.146276,-0.221105,0.158977,0.522979,-0.051056,-0.417307,-0.118150,-0.192828,-0.609472,-0.100605,-0.293490,-0.470197,-0.039461,0.404159,0.099817,0.369812,0.673551,-0.698641,-0.346381,-0.591678,-0.285742,-0.166378,-0.310326,-0.028009,-0.574290,-0.286450,-0.318051,-0.235245,-0.096508,0.371165,0.072384,0.689929,-0.657473,0.327990,0.322523,0.217933,-0.025669,0.403296,-0.073723,0.081466,-0.317385,-0.076013,0.690626,0.061569,0.230022,0.134182,0.265829,0.199546,-0.083166,-0.201255,0.705221', '1793491', '27098364', '10440076', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3157605', '巴黎淘气帮', '喜剧', '小尼古拉（马克西姆·戈达尔 Maxime Godart 饰）深受父母宠爱，在学校也与一帮朋友玩得开心，这其中包括：想当大官的亚斯特Alceste（Vincent Claude 饰）、以后会继承父业的杰夫Geoffroy（Charles Vaillant 饰）、梦想成为自行车冠军在班上却总是被罚站的克劳岱Clotaire（Victor Carles 饰）、长大要当黑道的奥德Eudes（Benjamin Averty 饰）、希望跟老爸一样成为警察的鲁夫Rufus（Germain Petit Damico 饰）以及全班第一名永远不会被罚站也是老师（Sandrine Kiberlain 饰）的最爱学生同时是其他同学眼中讨厌的大蟑螂的阿南Agnan（Damien Ferdel 饰）。有一天，尼古拉的妈妈（瓦莱丽·勒梅西埃 Valérie Lemercier 饰）建议爸爸（凯德·麦拉德 Kad Merad 饰）请老板及夫人来家里吃饭，以便获得老板青睐涨工资；但小尼古拉听到和观察到的结果却让他以为父母要生个小弟弟，不要他了。沮丧的小尼古拉请求朋友们的帮助，大家七嘴八舌给他出了一堆建议，包括送花、大扫除，甚至找罪犯领养弟弟等荒谬办法。与此同时，教育部长也要来学校参观，班级又换了严厉的代课老师……本片根据由法国作家勒内·戈西尼（René Goscinny）创作，漫画家让-雅克·桑贝（Jean-Jacques Sempé）配画的系列同名漫画故事改编。影片在法国本土上映后一举拿下全法双周票房冠军，并获2010年凯撒奖最佳改编剧本提名。', '马克西姆·戈达尔', '洛朗·蒂拉尔', 8.6, 129121, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p524581356.jpg', 0.1, 0.6, 11.4, 42.8, 45.1, '-0.056692,-0.201249,-0.411064,0.446967,-0.001751,-0.485253,0.323107,0.138568,-0.473791,-0.176113,-0.036155,0.708590,-0.142439,0.374542,0.337189,-0.019334,-0.536098,-0.557676,0.068476,-0.160671,-0.129225,-0.435170,-0.035341,-0.154784,-0.161658,-0.303378,0.239634,-0.304681,-0.039759,0.405579,0.445317,0.203415,0.139476,-0.034059,-0.138619,0.021683,0.264608,-0.016323,-0.358404,0.262371,0.026274,0.139662,-0.271834,-0.109517,0.405519,0.056563,0.413224,0.022120,0.029725,0.011419,0.347903,-0.166904,0.186071,0.036822,0.095307,0.085471,0.480730,0.281300,-0.057002,0.253817,0.080383,-0.222878,-0.720193,0.241410,0.225067,0.177930,-0.467079,0.425072,-0.087698,-0.146291,0.326412,-0.139417,0.173009,0.205857,0.126293,0.373175,-0.109580,0.292781,-0.381323,0.281953,0.309230,-0.112422,-0.083644,0.020178,-0.033524,-0.101605,0.315370,-0.295073,-0.503795,0.287644,0.185809,-0.076108,0.094380,0.149765,-0.433576,-0.325359,-0.161364,-0.233255,0.203006,-0.387201,0.159415,-0.515743,0.182108,0.044213,-0.140685,0.061649,0.244217,-0.229296,0.973769,-0.615700,0.274610,0.396720,0.488563,-0.455066,0.717726,0.371460,-0.019530,-0.308276,-0.075159,-0.193033,0.162934,0.041582,-0.012545,0.259814,0.257365,-0.735982,-0.337420,0.382746', '27602116', '24284209', '1870681', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3158429', '西洋古董洋果子店', '剧情', '某个居民区的角落，有一家外表看似古董店，内里却飘来阵阵香气的名为“Antique”的蛋糕店。经营这家店的老板镇赫（朱智勋 饰）很会讨女人欢心，却无法让蛋糕店的生意好转，于是他决定对蛋糕店进行一番改造，请来了业内首屈一指的糕点大师鲜于（金材昱 饰）。鲜于的来到让蛋糕店的生意立马好转，但镇赫依然有个小小的烦恼，那就是作为他的同级生的鲜于曾在高中时代向镇赫表白过，被圈内尊称为“有魔性的GAY”的鲜于最近又看上了新来的学徒（刘亚仁 饰），而镇赫的神秘保镖（崔志浩 饰）也时不时的来蛋糕店捣乱，一出出充满香气的甜蜜故事在蛋糕店一一上演……本片改编自日本漫画家吉永史的同名漫画，先后分别被改编成日剧和动画。©豆瓣', '朱智勋', '闵奎东', 7.1, 19509, 'tt1205551', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2504995161.jpg', 1.4, 7.1, 41.7, 36.7, 13.1, '0.399728,0.111385,-0.463816,0.582679,-0.072254,-0.331789,0.994650,0.521256,-0.736597,-0.015181,0.289069,0.762652,-0.366694,0.301161,0.349702,0.155625,0.116046,-0.444848,-0.206411,-0.239436,0.025863,-0.101249,-0.350194,-0.119908,-0.120501,-0.176271,0.268978,0.032321,-0.247234,0.259234,0.510892,0.143893,-0.104087,0.375635,-0.170140,0.148927,0.040024,0.055234,-0.248749,0.132013,-0.089697,-0.455349,-0.095024,-0.149974,0.019651,0.448181,0.591285,0.273618,-0.159194,0.008487,0.617077,0.224999,0.034206,-0.068649,0.334941,0.278550,0.333687,-0.206313,-0.386556,-0.112842,-0.126819,0.002106,-0.734310,-0.042020,0.464382,0.219689,-0.684265,0.506312,0.061876,-0.285485,0.064211,-0.579589,0.078546,0.005524,0.371152,0.426596,0.101885,0.377467,-0.605718,0.310994,0.339868,0.232998,-0.007165,0.372820,-0.266524,-0.417646,0.022965,-0.064611,-0.409628,-0.103019,0.378136,-0.034050,0.070751,-0.203069,-0.755651,-0.069745,0.246585,-0.469905,0.399918,-0.227502,-0.180383,-1.014111,-0.080728,-0.432762,-0.098744,0.022254,0.334619,-0.004294,0.605216,-0.906370,0.049552,0.551225,0.074155,-0.295475,0.663789,0.029625,-0.174160,0.050018,-0.392293,0.075232,0.196261,0.393434,0.143077,0.681392,-0.013798,-0.477944,-0.523279,0.350718', '1394176', '10763928', '3326747', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3158432', '银行匪帮', '动作', '戈登（Idris Elba 饰）等五人组成的银行抢劫团伙每隔一年作案一次，其成员AJ（海登•克里斯滕森 Hayden Christensen 饰）、约翰（保罗•沃克 Paul Walker 饰）各有所长，抢劫所得和合理的投资令他们过着奢华的生活。在最近的一次劫案中，他们引起了铁腕警探杰克（马特•狄龙 Matt Dillon 饰）的注意。戈登团伙昔日的成员里弗斯新近出狱，里弗斯在狱中结识了俄罗斯黑帮，并取得一份银行的内线情报。里弗斯邀请众人行劫，否则就拿回当年属于自己的那份抢劫所得，尽管时间仓促，不符合团伙一贯的行事风格，然而一番讨论之下，他们决定再次出手。与此同时，杰克以抢劫所用的C4炸药为突破口，发现了这次有俄罗斯黑帮参与的抢劫计划图纸。距离计划时间所剩无几，这次抢劫会导致怎样的结局？©豆瓣', '克里斯·布朗', '约翰·卢森霍普', 6.9, 17834, 'tt1135084', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p597700664.jpg', 0.9, 6.9, 48, 34.6, 9.6, '0.156002,0.020512,-0.532919,0.433955,0.007080,-0.193673,0.421785,-0.094441,-0.844782,-0.329099,0.164081,0.424011,-0.005624,-0.097042,0.404531,-0.202691,-0.520764,-0.536210,-0.224286,-0.361289,-0.075751,-0.578135,-0.467803,-0.300961,0.024906,-0.242836,0.419851,0.203203,-0.176561,0.472765,0.134961,0.377520,-0.069813,0.237731,0.258831,-0.213845,0.296237,-0.171540,-0.387655,0.335872,0.018345,-0.172722,-0.132500,-0.025064,0.293869,0.669186,0.590011,-0.170428,-0.147259,-0.164593,0.305979,-0.062789,-0.140956,-0.056704,0.511295,0.012751,0.340266,0.597458,-0.262856,0.242047,-0.076232,-0.099542,-0.799598,-0.054497,-0.032055,0.052121,-0.620817,0.361542,-0.287742,0.176043,-0.135053,-0.268075,0.017801,0.506915,0.682197,-0.169210,0.062969,-0.173933,-0.529194,0.102762,0.595452,-0.307670,0.083083,0.051900,-0.082916,-0.330915,-0.024002,-0.278047,-0.037104,-0.057857,0.379304,-0.206255,0.062277,0.173437,-0.632821,-0.156979,-0.481190,-0.239002,0.179030,-0.226807,-0.088677,-0.967854,-0.051147,-0.157527,-0.342598,0.128524,0.067617,0.042173,0.340647,-0.699632,-0.122504,0.580608,0.158662,-0.415577,0.256387,-0.130212,0.283384,-0.310939,-0.099746,-0.159251,0.457153,0.267208,0.074421,0.100259,0.203221,-0.599949,-0.060102,0.062778', '4014397', '3178770', '1293936', '1307442'