INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3158443', '心理医师', '剧情', '本片是托马斯·墨菲特独立编剧的第一部作品。住在洛杉矶颇有名气的心理医生亨利·卡特(凯文·史派西 Kevin Spacey饰)，拥有众多需要帮助的高级病人，并且人数在逐渐增多，其中包括：已经过气的好莱坞女明星，滑稽的且有着严重强迫症迹象的经纪人，毫无安全感而言的畅销惊悚小说的作家等。与此同时，亨利还作为本地作为著名的心理专家而主持着一个最受欢迎的心理咨询的广播节目，对于他而言，仿佛全世界在这个特殊的时代里都存在严重的心理问题。然而，作为心理高手的他自己，也正遭遇着和很多人同样的麻烦。无论是包括私生活在内的家庭里，还是在公共社交以及与人交往中，总有些不如意的时候。身为心理医生的他却对于自己身上发生的悲剧毫无应对能力，只能沉溺于大麻的吸食中……©豆瓣', '凯文·史派西', '乔纳斯·佩特', 7.2, 7960, 'tt1247692', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p791455120.jpg', 0.9, 5.5, 38.1, 43.6, 11.9, '0.417676,-0.005030,-0.900240,0.690829,0.003611,0.091298,0.837502,0.049006,-0.732276,-0.561534,0.135010,0.846870,0.042205,0.356631,0.316644,-0.283357,-0.232781,-0.743261,-0.359556,-0.114225,-0.508419,-0.653810,-0.790611,-0.201090,-0.373233,-0.525921,0.608031,0.234573,-0.561481,0.152977,0.343250,0.440382,-0.023524,0.506117,-0.076218,-0.233932,0.271161,-0.142305,-0.232674,0.204001,0.314056,-0.090886,-0.084635,0.304699,0.110690,0.542185,0.473833,-0.481699,-0.398411,0.139489,0.535353,-0.214298,-0.188590,0.036562,0.264995,0.130799,0.541154,0.114282,-0.041526,0.376790,-0.034411,-0.056339,-1.274945,-0.127915,0.415692,0.357496,-0.530647,0.656729,0.066058,-0.315347,0.054387,-0.200606,0.247082,0.079998,0.162653,0.479324,-0.157260,0.227526,-0.307747,0.132593,0.564339,0.543128,-0.659862,0.247463,-0.626034,-0.422483,-0.166208,-0.518760,-0.530287,0.063985,-0.048787,0.194821,-0.102408,0.275303,-0.439320,0.562119,0.104103,-0.325953,-0.204332,-0.130664,0.023345,-0.798229,-0.106320,-0.744242,-0.191935,-0.105360,0.381616,-0.395935,1.101148,-0.929953,0.160579,0.465280,0.389668,-0.445128,0.826120,0.163708,0.153055,0.003562,-0.630026,0.161158,-0.198610,0.131068,-0.207748,0.320427,0.050395,-0.560905,-0.211873,0.635087', '24284209', '27602116', '25932086', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3158449', '希区柯克', '剧情', '本片根据史蒂芬·雷贝洛出版于1998年的同名纪实文学改编。记录了希区柯克（安东尼·霍普金斯 Anthony Hopkins 饰）为《精神病患者》的拍摄所付出的种种努力。在电影的拍摄过程中，他与妻子阿尔玛（海伦·米伦 Helen Mirren 饰）的关系也变成了大家关注的焦点。此后《精神病患者》成为了希区柯克经典代表作之一，该片讲述了女演员珍妮特·李（斯嘉丽·约翰逊 Scarlett Johansson）扮演的女秘书Marion，在卷走了老板的钱之后逃到一家偏僻的汽车旅馆，结果被由安东尼·珀金斯（詹姆斯·达西 James D’Arcy 饰）演的有精神分裂症的旅店老板Norman残忍杀死。她在片中惊恐尖叫的场景已经成为电影史上最让人难以忘记的画面之一，她也因此获得了当年金球奖和奥斯卡最佳女配角奖的提名。©豆瓣', '安东尼·霍普金斯', '萨沙·杰瓦西', 6.7, 12604, 'tt0975645', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1856990201.jpg', 0.7, 7.2, 55.5, 30.4, 6.2, '0.047290,-0.240628,-0.596450,0.474668,0.120938,-0.295013,0.782230,0.061173,-0.224780,-0.144665,0.376249,1.031396,-0.379154,0.142141,0.565109,-0.169958,-0.390804,-0.730888,-0.232330,-0.186760,-0.092298,-0.381523,-0.359578,-0.317351,-0.191085,-0.421813,0.647388,-0.061777,-0.294730,0.195750,0.607933,0.223522,-0.082227,0.185907,0.083181,0.437125,0.307929,-0.174177,-0.350474,0.425991,0.148677,-0.518616,-0.078574,0.084252,0.018055,0.390245,0.708538,-0.260299,-0.046674,0.195517,0.701583,-0.239527,-0.184681,0.012986,0.178978,-0.047816,0.277183,0.117427,-0.294778,0.073354,0.026116,-0.120241,-0.971520,-0.014680,0.329870,0.412774,-0.524576,0.404439,-0.215768,0.030533,0.011240,-0.145552,0.302643,0.008014,0.402625,0.294713,0.085664,0.074880,-0.307921,0.608492,0.413846,-0.011687,-0.340763,0.441587,-0.276017,-0.560637,-0.216301,-0.318919,-0.579514,0.186910,0.683615,-0.004842,-0.043473,0.262576,-0.374108,-0.336957,-0.138640,-0.365039,-0.096561,-0.238223,-0.042566,-0.761954,-0.232679,-0.226160,0.071493,-0.352599,0.022487,-0.580781,0.705792,-0.495833,0.149921,0.426663,-0.033736,-0.379925,0.802524,-0.060771,0.227844,-0.054497,-0.097437,0.294229,0.080551,0.257413,0.133407,0.413696,-0.014236,-0.277479,-0.410005,0.541590', '34890458', '2027945', '3318306', '1292925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3158990', '海角七号', '剧情', '依傍大海的美丽小镇恒春上，音乐梦想在台北遭受打击的年轻人阿嘉（范逸臣）冷眼旁观着一切。虽在民代主席后父的帮忙下成了代班邮差，信件和邮包却被他乱堆在房间，而对一个寄自日本的无法送至的邮包，他也没按老邮差茂伯（林宗仁）的吩咐将之退回，而是私自拆阅查看：里面除一张泛黄的少女照片，是几封写于60年前的信件。其时日本在二战中战败，在台日籍教师（中孝介）随日军撤退时遗弃了相约私奔的女友，归日途中，他将爱意和悔意化为文字，但信件直到去世才被其女儿代为寄出。在台湾留学、工作的日本女孩友子（田中千绘）有心成为模特，却被认为形象过时只能做负责日本超级“疗伤歌手”中孝介（中孝介）在恒春的演出事宜的公关。按惯例，中孝介演出之前会有乐团暖场，友子原本联络了日本某乐团，但民代坚持用本地乐团，友子无奈与包括阿嘉在内的几个年龄、工作、个性都有较大差异的当地音乐爱好者——因意外事件失掉幸福生活的交警（民雄）、暗恋老板娘的小店伙计水蛙（夹子小应）、早熟的小女生大大（麦子）等——成了工作搭档。由于阿嘉之外的几人全无舞台表演经验，临时组建的乐团时有矛盾发生，友子常被气得火冒三丈，最有经验的阿嘉气她最甚。屡有调整的乐团成员——茂伯、兜售客家小米酒的马拉桑（马念先）先后取代贝斯手加入乐团，一直不顺的排练，中孝介来台的日子越来越近，对阿嘉彻底失望的友子决定放弃在台的工作回日本，但两人已在摩擦中生出感情。不久友子在阿嘉房间看到那些60年前的信件，完全被美丽的爱情故事打动，叮嘱阿嘉一定要将信件送至当事人手中。双方虽没开口表白，但爱情的力量无疑是巨大的，阿嘉因为友子重新拥有了追求音乐梦想的勇气。中孝介演出即将开始之时，信件主人的', '范逸臣', '魏德圣', 7.6, 243181, 'tt1267160', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2346651192.jpg', 0.9, 4.1, 31.3, 43.7, 20.1, '0.246952,0.009701,-0.631907,0.431915,-0.051883,-0.149160,0.566791,0.238218,-0.352148,-0.263756,0.129210,0.669341,-0.099493,0.202578,0.161943,-0.266577,-0.181731,-0.794177,-0.122161,-0.175903,-0.122094,-0.351551,0.077948,-0.047973,-0.285464,-0.341613,0.630491,-0.052967,-0.215839,0.406150,0.306801,0.134547,-0.111830,0.331585,-0.097655,0.015929,0.086319,-0.027528,-0.248341,0.085548,-0.054413,-0.363507,-0.017992,0.127537,0.095141,0.340063,0.783233,-0.057819,-0.049244,0.088080,0.387973,-0.165980,0.047928,0.113470,0.408550,0.300810,0.047191,0.110737,-0.315173,-0.074632,0.063273,-0.140441,-0.471250,0.006057,0.121244,0.236167,-0.487855,0.460693,-0.199404,0.018858,0.079076,-0.262473,0.263203,0.294380,0.198157,0.334776,-0.074773,0.168634,-0.290656,0.238901,0.456272,-0.024458,-0.016120,0.317372,-0.177504,-0.447535,0.091305,-0.176723,-0.347864,0.097778,0.222356,0.033989,-0.089939,-0.088318,-0.616800,-0.132553,-0.063142,-0.263507,0.055417,-0.472764,-0.183595,-0.755145,-0.087267,-0.315143,-0.124696,0.042954,0.354723,0.024345,0.847098,-0.677516,0.219441,0.464482,0.130903,-0.388336,0.506976,0.116577,0.031545,-0.084764,0.103616,0.156813,-0.048538,0.430042,0.182323,0.223317,-0.132010,-0.237581,-0.474795,0.320267', '3811356', '5403927', '25863940', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3160325', '狂蟒之灾3', '动作', '在欧洲乡间的秘密研究室里, 一位顶尖的科学家正对着两只巨蟒进行实验测试. 当资助者(约翰莱斯戴维斯饰) 企图干预实验时, 饥饿的蟒蛇逃出了研究室. 汉密特(戴维赫索霍夫饰) 受雇追捕牠们, 其任务是必须在蟒蛇窜逃到城市且在灾难扩大以前, 实时捉拿这多产又极度致命的生物……', '克里斯托·艾伦', '唐·方李洛伊', 5.1, 7819, 'tt1137996', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2517326639.jpg', 14.4, 33.7, 38.8, 8.2, 4.9, '0.097874,-0.158886,-0.606961,0.402079,0.068399,-0.007440,0.726343,0.000937,-0.452535,-0.086507,0.560197,0.231102,0.091762,-0.007202,-0.157015,-0.392740,-0.239101,-0.279087,-0.144127,-0.281280,-0.619716,-0.216421,-0.669033,-0.479445,0.195248,-0.442545,0.655682,0.117077,-0.443732,0.048298,0.046481,0.585424,-0.375181,0.314644,-0.326342,-0.513111,0.462529,-0.061995,-0.226331,0.356003,-0.199377,-0.321248,-0.189476,0.152892,0.023138,0.340978,0.644866,-0.686341,-0.005467,-0.374651,0.182858,-0.497066,-0.030306,0.157567,0.702156,-0.074320,-0.025300,0.030033,-0.209310,0.395047,-0.021551,-0.161562,-0.718789,-0.386925,0.004242,0.412097,-0.550024,0.063739,0.119960,0.273114,0.136905,-0.245808,-0.164508,0.159601,-0.310043,0.239281,0.024445,0.387764,-0.546914,0.209128,0.328727,-0.270287,-0.288909,-0.143832,-0.141881,-0.701193,-0.045590,-0.397508,-0.098195,-0.313207,0.496085,-0.040622,-0.482708,0.420709,-0.813520,-0.040093,-0.396286,-0.457617,-0.264730,0.063128,-0.261047,-1.008276,0.264684,-0.123635,-0.042330,0.263939,0.170568,-0.157329,0.543283,-0.737911,0.131652,0.974104,0.044975,-0.293912,0.387502,-0.089607,0.375614,-0.416637,-0.362095,0.071912,0.253376,0.655352,-0.159419,0.289893,0.350502,-0.279060,-0.662442,0.576166', '1306809', '4014397', '11810348', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3160978', '世界上最伟大的父亲', '剧情', '在一所普通的高中内，生活着一对“废柴”父子。父亲兰斯克•莱顿（罗宾•威廉姆斯Robin Williams 饰）渴望成为名利双收的畅销作家，然而书稿却无法逃脱退回的命运。他所教授的诗歌鉴赏课听者寥寥，虽然和同校的的艺术课女老师克莱尔•里德（阿丽克谢•吉尔莫 Alexie Gilmore 饰）谈恋爱，但恋情始终无法公开。兰斯的儿子凯尔性格孤僻古怪，这个正处在青春躁动期的男孩处处与父亲作对，每天惹是生非，性格内向的小男生安德鲁（Evan Martin 饰）是他唯一的朋友。凯尔对学习、音乐、电影全不感兴趣，唯有色情和手淫主宰着他的生活。在一次超high的自娱自乐后，凯尔魂飞极乐。兰斯克沉浸在极度的悲伤之中。然而，兰斯克代为捉刀的遗书却在校内引起巨大震撼，所有人都渴望了解凯尔，兰斯克的人生也开始发生转变……©豆瓣', '罗宾·威廉姆斯', '博卡·格德斯维特', 7.4, 9467, 'tt1262981', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p770723859.jpg', 0.6, 3.9, 34.3, 46.9, 14.3, '0.351956,-0.108959,-0.813377,0.702939,-0.016815,-0.363561,0.777687,0.199111,-0.407016,-0.504838,0.204112,0.640983,-0.141039,0.388149,0.271230,-0.057639,-0.288978,-0.652078,-0.033741,-0.147326,0.131760,-0.574267,-0.227084,-0.158392,-0.327671,-0.377082,0.751351,0.009787,-0.359844,0.363361,0.135809,0.225996,0.137011,0.268438,-0.020015,-0.163149,0.159065,-0.046131,-0.336194,-0.146145,0.265742,0.118689,-0.185360,0.310418,0.116703,0.133613,0.763342,-0.604895,0.049911,0.291992,0.526877,-0.195401,-0.187864,0.113531,0.066057,0.005012,0.206997,-0.043340,0.069799,0.036738,0.035396,0.013891,-0.598995,0.045459,-0.005159,0.406231,-0.278099,0.660383,-0.017401,0.032618,0.130570,-0.136338,0.006627,0.199351,0.280321,0.458470,-0.152986,0.122339,-0.247660,0.148648,0.625711,0.126258,-0.560647,0.225492,-0.620237,-0.382766,-0.095753,-0.337738,-0.884027,-0.065214,0.141296,0.134466,0.024435,0.628240,-0.333439,0.040938,-0.045253,0.013785,0.095880,-0.411300,-0.290670,-0.740078,-0.130558,-0.456071,-0.346645,-0.204873,0.145248,-0.627532,0.790279,-0.890226,0.277080,0.434752,0.018464,-0.297541,0.823236,0.127985,0.097571,-0.241907,-0.494469,0.638923,0.071223,0.112409,-0.009852,0.300753,0.176489,0.033988,-0.252724,0.768450', '24708493', '1296992', '1298638', '3154392');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3161007', '小叮当与失去的宝藏', '喜剧', '精灵世界一年一度的秋季盛典马上又到了，恰逢难得的蓝月亮丰收之年，需要制作一把全新的蓝宝石权杖。负责修补工作的精灵小叮当（梅·惠特曼 Mae Whitman 配音）意外被任命为这次权杖制作的主管，个性毛躁的她虽然有好朋友特伦斯（杰西·麦卡尼 Jesse McCartney 配音）帮忙，但很快就起了争吵与之绝交，还在无意中打碎了蓝宝石，自觉大难临头。一次偶然的机会，小叮当得知传说中的一个神秘岛上藏有一面魔镜，可以帮助实现一个愿望。小叮当决意偷偷前往神秘岛，希望能重获一块蓝宝石。然而在这趟惊险的旅途中，小叮当却发现了另外一样珍贵的无价之宝……本片为迪士尼制作的《奇妙仙子》系列作品中的第二部。©豆瓣', '梅·惠特曼', '克雷·豪尔', 8.1, 9401, 'tt1216516', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2277170713.jpg', 0.3, 1.1, 19.5, 49.2, 29.9, '-0.050103,0.363444,-0.619373,0.618498,-0.088802,-0.297276,0.526215,-0.198433,-0.294939,-0.252169,0.103365,0.794521,-0.250284,0.080389,0.387349,0.173446,-0.159176,-0.419795,0.048585,-0.292782,-0.285278,-0.174416,-0.637765,0.065077,-0.187059,-0.539152,0.534021,0.302292,-0.021542,0.585327,0.204048,0.098751,-0.259446,0.346095,-0.196955,-0.338138,0.211548,0.252221,-0.433552,0.407836,-0.090336,-0.003092,0.043335,0.383885,0.068560,0.326801,0.594299,-0.539519,-0.111060,0.013684,0.625846,-0.023273,0.103390,-0.119743,0.158767,0.396857,0.092163,-0.148941,-0.333799,0.100783,0.260160,-0.642984,-0.802981,-0.150242,0.152988,0.176448,-0.352350,0.251212,0.019062,0.156029,0.056403,-0.394975,0.365915,0.177836,0.571833,0.368499,-0.064622,-0.037143,-0.274687,0.453383,0.422562,-0.106222,-0.177877,0.653162,-0.128464,-0.507788,0.204299,-0.060168,-0.285233,0.115481,0.663370,0.180284,0.041623,-0.002274,-0.751350,0.133901,-0.279795,-0.044385,0.084464,-0.240002,0.106259,-0.410214,0.060772,0.065857,-0.217100,0.030342,0.191633,-0.378845,0.649686,-0.803341,0.337560,0.608285,0.098743,-0.183842,0.529653,0.061454,0.160023,-0.256321,-0.049390,-0.070519,0.079416,0.315518,-0.026050,0.378075,0.165479,-0.442781,-0.630420,0.388969', '1308585', '25928048', '26839466', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3162953', '前任', '喜剧', '菲力浦与凯萨琳离了婚还为孩子的监护权争吵。再公判决官卢卡（希维欧·奥兰多 Silvio Orlando 饰）规劝两人复合，在私却在和老婆闹分居。伊丽莎（克劳蒂亚·洁里尼 Claudia Gerini 饰）结婚时却发现证婚神父竟然是前任罗伦佐（法拉维·因辛纳（Flavio In sinna 饰）。保罗（法比·奥德·路易吉（Fabio De Luigi 饰）在夜店结识梦妮卡（瑟西·卡索 Cecile Cassel 饰）却招来她前任男友大卫（亚历山德拉·葛斯曼 Alessandro Gassman 饰）的威胁。马克（马力克·齐狄 Malik Zidi 饰）和女友朱莉娅（克里斯廷娜·卡波唐迪（Cristiana Capotondi 饰）只能远距离恋爱。每个人都在为爱情努力向前看，却发现有的事情总有东西牵引大家回头......©豆瓣', 'Alessandro Gassman', '法乌斯托·布里齐', 7.7, 6397, 'tt1188988', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p479028593.jpg', 0.4, 3, 29.6, 47.6, 19.4, '0.077806,-0.107827,-0.433256,0.393739,0.115261,-0.587820,0.717251,0.375242,-0.047902,-0.358807,0.049117,0.546014,-0.515631,-0.113765,0.109750,0.229171,-0.667751,-0.727565,0.440531,0.045073,-0.268995,-0.573619,0.059304,-0.182211,-0.008868,-0.464589,0.167512,-0.295669,-0.016851,0.045725,0.593221,0.226365,-0.225450,0.430608,0.163510,0.342881,0.336125,0.047273,-0.312292,0.022495,-0.149946,0.068147,-0.414883,0.004792,0.449007,0.494959,0.290760,-0.139251,0.304096,0.212616,0.081324,-0.015978,0.269265,0.187483,0.009333,-0.400632,0.068646,0.010127,-0.208807,0.026592,0.231830,-0.019435,-0.286094,0.258259,-0.038272,0.357592,-0.471903,0.359642,-0.396773,0.008478,0.129112,-0.372046,-0.078338,0.142046,-0.079619,0.254149,0.023899,0.006583,-0.433759,-0.067345,0.079567,0.172176,-0.149542,0.200036,-0.316513,-0.315232,-0.164812,0.264242,-0.547682,-0.205094,0.363021,-0.270358,0.235444,0.395207,-0.373315,-0.327933,-0.401666,0.054594,0.121750,-0.419041,0.105027,-0.704773,0.103848,-0.347030,-0.549637,0.140094,0.036705,-0.252624,0.238106,-0.578456,0.298918,0.538385,0.366103,-0.299081,0.559079,0.341206,0.040565,-0.316425,-0.322251,0.571224,0.199183,-0.199256,0.288048,0.206007,0.262011,-0.058737,-0.077106,0.530751', '26915921', '1316693', '2034997', '1945337');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3166574', '猪头逛大街3', '喜剧', '遥想上一次惊心动魄的冒险已经远在六年之前，如今的哈罗德（约翰·赵 John Cho 饰）和卡玛（卡尔·潘 Kal Penn 饰）也已各自过上安定的生活，哈罗德成为了华尔街一名有为商人并已结婚，而卡玛还依旧住在当年和哈罗德合租的旧公寓。眼看圣诞将至，哈罗德的父亲和岳父决定前来一起过节，岳父还特地带来了他最钟意的一棵圣诞树。一天，卡玛收到一个写着哈罗德名字的包裹，他决意上门将其交给哈罗德，然而意想不到的事发生了，两人竟然无意中烧毁了岳父的圣诞树，为了在岳父发现之前找到一棵以假乱真的替代品，他们再次走上纽约街头，不过依二人的一贯作风，这次的寻找圣诞树之旅，恐怕又要发展成一次怪事不断高潮迭起的疯狂冒险了……本片为系列喜剧《寻堡奇遇》第三集。©豆瓣', '卡尔·潘', '托德·施特劳斯-舒尔森', 6.5, 6173, 'tt1268799', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1230920332.jpg', 1.9, 13.1, 52.3, 23.5, 9.2, '0.253817,0.008574,-0.734790,0.705065,0.108277,-0.565252,0.754790,0.041629,-0.534179,-0.373393,-0.019130,0.697996,-0.407125,0.280102,0.538634,0.017222,-0.302003,-0.699670,0.019375,-0.184183,-0.404354,-0.423045,-0.374419,-0.044325,-0.203510,0.004504,0.575672,0.214931,0.071050,0.517626,0.373698,0.133390,-0.101680,0.449260,-0.290382,-0.046186,-0.059039,0.240836,-0.437611,0.267794,0.025662,-0.391084,-0.078543,0.039300,0.095097,0.302970,0.508867,-0.240307,-0.194091,-0.006399,0.239209,0.027533,0.120594,0.171537,0.337856,-0.015960,0.146535,0.149599,-0.272647,-0.098226,0.119018,-0.293415,-0.629295,0.065262,-0.005558,-0.056910,-0.699196,0.268976,0.000165,0.114938,0.006210,-0.614491,0.206807,0.412036,0.226852,0.340649,-0.246241,-0.168406,-0.477604,0.114022,0.692660,0.060843,0.089167,0.300104,0.086235,-0.318255,-0.005301,-0.038590,-0.510703,0.203102,0.355156,0.023017,-0.028280,0.113575,-0.593950,-0.157610,-0.335249,-0.251292,0.089701,-0.310904,0.206327,-0.644541,-0.052698,-0.170439,-0.144183,0.152246,0.137954,-0.326168,0.285667,-0.444234,0.449625,0.355518,0.025666,-0.336363,0.542511,0.004115,0.326178,-0.125731,-0.098648,0.137072,0.137723,0.300143,0.207927,0.240269,0.125126,-0.315370,-0.305893,0.529101', '34461680', '3111650', '1293952', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3168086', '挪威的森林', '剧情', '木月自杀之后，留给曾经青梅竹马的恋人直子（菊地凛子 饰）以及他们的好朋友渡边（松山健一 饰）无法弥合的伤痛。为了忘掉曾经伤痛的记忆，渡边选择了前往东京求学。在新的环境中，渡边几乎忘记过去的一切，直到某天与直子偶遇。在他们共同的记忆里，木月是不可能回避的话题，但他们却像约好了一样谁也没有提起这个人。直子20岁的生日，屋外淫雨霏霏，屋内直子与渡边温存一夜。直子搬家了，她又一次从渡边的生活中消失，渡边的生活似乎又一次恢复平静，但他的内心却满怀伤害直子的愧疚，直到渡边收到直子的信。渡边认识了开朗热情的女同学绿子（水原希子 饰），两人很快坠入爱河，但在渡边的心里，永远有一个位置属于直子……影片改编自村上春树的著名小说《挪威的森林》，从开拍伊始，便倍受关注。©豆瓣', '松山研一', '陈英雄', 6, 120587, 'tt1270842', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p720673149.jpg', 4.3, 20.3, 50.4, 19.3, 5.7, '0.216410,-0.052030,-0.700139,0.631670,-0.170464,-0.577666,0.833930,0.000213,-0.543404,-0.475183,-0.001632,0.673614,0.015360,0.458820,0.230200,0.215413,-0.389523,-0.786513,0.049967,-0.090974,-0.080709,-0.488157,-0.156374,-0.100561,-0.220854,-0.158915,0.758043,0.334273,-0.103930,0.648487,0.176425,0.330349,-0.070680,0.630587,0.089865,0.090738,0.013539,0.164264,-0.306603,0.305238,-0.152876,-0.222301,-0.240234,0.252910,0.109797,0.488676,0.616790,-0.147992,-0.312449,0.234392,0.293007,-0.255526,-0.230105,0.224309,0.379064,-0.080882,0.204922,0.010024,-0.395531,-0.054465,-0.213189,0.173254,-0.271962,-0.033181,0.069158,0.316532,-0.321413,0.714584,-0.020360,-0.196035,0.361413,-0.204281,0.009159,0.270366,0.391524,0.175890,-0.405992,0.133921,-0.039497,0.031858,0.792938,0.025803,-0.099977,0.504111,-0.248498,-0.497654,-0.320866,0.014470,-0.361750,0.107114,0.038713,0.429537,-0.540956,0.254881,-0.319007,-0.102980,-0.062268,-0.145228,0.132884,-0.405010,-0.135699,-0.765488,-0.097906,-0.553669,-0.431456,-0.045665,0.087573,-0.300886,0.761368,-0.806011,0.301664,0.484623,0.022938,-0.214556,0.452527,0.239672,-0.337223,-0.154265,0.189467,0.482068,-0.090346,0.304524,0.180179,0.259583,-0.272941,0.129824,-0.520863,0.474756', '3811356', '1292219', '35030151', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3168089', 'X战警：第一战', '剧情', '年轻的X教授查尔斯（詹姆斯·麦卡沃伊 James McAvoy 饰）和万磁王埃里克（迈克尔·法斯宾德 Michael Fassbender 饰）是一对志向相投的好朋友。他们最早发现了自己的超能力，并与其他几个变种人一起在CIA工作。引发埃里克超能力的纳粹战争贩子肖（凯文·贝肯 Kevin Bacon 饰）一直试图挑起核战争，而想方设法挑起美苏两国的矛盾。埃里克和查尔斯一直与肖手下的变种人战斗，努力阻止肖的阴谋。肖怂恿苏联引发古巴导弹危机，查尔斯和埃里克获知消息后，在海湾与肖手下的变种人拉开了对决的一战。最终，肖被查尔斯和埃里克合力消灭。可是，在这个过程中，埃里克逐渐被肖的政治观点影响，与查尔斯产生裂痕。通过海湾的这一战，埃里克和查尔斯最终决裂，一方变成支持人类与变种人和平共存的X教授；另一方坚持通过消灭人类换来变种人兴起的观点，自称万磁王......', '詹姆斯·麦卡沃伊', '马修·沃恩', 8.2, 321003, 'tt1270798', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p956878707.jpg', 0.2, 0.8, 16.2, 53.1, 29.7, '0.095604,-0.085079,-0.748812,0.742440,-0.165592,-0.226779,0.798523,0.001101,-0.471386,-0.288187,-0.421858,0.689747,-0.417220,0.097313,0.488162,-0.438246,-0.403713,-0.674131,-0.187916,0.203785,-0.488496,-0.839952,-0.400339,-0.844324,-0.052202,-0.286128,0.649859,0.237188,-0.668819,0.418504,0.464280,0.606927,-0.251537,0.661202,0.097943,-0.009625,0.092389,-0.317376,-0.479214,0.022460,0.204836,-0.057905,-0.039621,0.361123,0.027134,0.299678,0.537208,-0.453371,0.167996,-0.200182,-0.116083,-0.376240,0.174894,0.089483,0.554375,-0.186176,-0.001464,0.178100,0.181153,-0.139661,0.169935,-0.096940,-0.513282,-0.013172,0.049148,0.079898,-0.264499,0.341783,0.156319,0.238619,-0.058730,-0.078984,0.123923,0.675986,0.581130,-0.029631,-0.137138,0.029506,-0.682360,-0.162221,0.688617,-0.039519,-0.303279,-0.014488,-0.304595,-0.602103,-0.394388,-0.206411,-0.230432,-0.167515,0.671349,0.031796,0.092890,0.280153,-0.825524,-0.312196,-0.143227,-0.039983,-0.036006,-0.414246,0.383673,-0.869979,-0.323777,-0.531051,-0.329498,0.159692,-0.101594,-0.337673,0.713983,-0.795594,0.050508,0.248967,0.462600,-0.357923,0.616225,0.137337,0.260638,-0.331723,-0.152727,0.262800,0.368806,-0.037756,0.322132,0.234231,0.200080,0.093957,-0.002705,0.485885', '1296702', '1309056', '20274039', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3168101', '毒液：致命守护者', '动作', '艾迪（汤姆·哈迪 Tom Hardy 饰）是一位深受观众喜爱的新闻记者，和女友安妮（米歇尔·威廉姆斯 Michelle Williams 饰）相恋多年，彼此之间感情十分要好。安妮是一名律师，接手了生命基金会的案件，在女友的邮箱里，艾迪发现了基金会老板德雷克（里兹·阿迈德 Riz Ahmed 饰）不为人知的秘密。为此，艾迪不仅丢了工作，女友也离他而去。之后，生命基金会的朵拉博士（珍妮·斯蕾特 Jenny Slate 饰）找到了艾迪，希望艾迪能够帮助她阻止德雷克疯狂的罪行。在生命基金会的实验室里，艾迪发现了德雷克进行人体实验的证据，并且在误打误撞之中被外星生命体毒液附身。回到家后，艾迪和毒液之间形成了共生关系，他们要应对的是德雷克派出的一波又一波杀手。©豆瓣', '汤姆·哈迪', '鲁本·弗雷斯彻', 7.2, 791266, 'tt1270797', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2537158013.jpg', 0.7, 5.3, 40.2, 42, 11.9, '0.262800,0.019097,-0.368438,0.518892,-0.313322,-0.412102,0.626468,0.218239,-0.624072,-0.142271,0.083120,0.588911,-0.155999,0.237320,0.182901,0.136857,-0.402966,-0.582110,0.124258,-0.161978,-0.272650,-0.678287,-0.271908,-0.322510,-0.038019,-0.544134,0.328610,-0.331984,0.081660,0.336590,0.174313,0.504805,-0.320199,0.345414,0.135723,0.173895,0.409667,-0.236476,-0.332362,0.590545,0.189845,0.083632,0.007376,0.209423,0.027050,0.390381,0.703416,-0.080222,0.217167,-0.273481,0.246091,-0.129851,0.190977,0.164747,0.519173,0.093174,0.169351,0.365915,-0.364976,-0.030267,0.342924,-0.076238,-0.681783,-0.150434,-0.098124,0.312516,-0.703078,0.215442,-0.277658,0.099321,0.189224,-0.480155,0.107802,0.310653,0.335469,0.260942,-0.016429,0.203575,-0.374577,-0.038144,0.519910,-0.270518,-0.026119,0.361826,-0.322470,-0.381710,-0.265069,0.131904,-0.503757,-0.149765,0.487752,0.075418,-0.021567,0.374527,-0.847581,-0.170991,-0.557756,-0.134589,-0.004407,-0.226800,0.099389,-0.657412,-0.301008,-0.212731,-0.257079,-0.090521,0.008407,-0.109743,0.595804,-0.694802,0.106449,0.867398,0.231347,-0.250440,0.568165,0.119005,0.117553,-0.186027,-0.058413,0.171863,0.192329,0.285611,0.085686,0.253330,0.216107,-0.354098,-0.123802,0.318078', '1292829', '11810348', '3326747', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3168993', '求婚大作战特别篇', '剧情', '礼（长泽雅美饰）听了健（山下智久饰）的表白，从与多田（藤木直人饰）正在进行的婚礼中落跑，转眼又过了一年。两人虽然都很了解对方的心思，但却始终无法迈出新的一步。这期间，绘里（荣仓奈奈）和小鹤（滨田岳饰）决定在夏威夷举行婚礼，健，礼还有干雄（平冈佑太饰）都来到了海边的教堂 。但众人发现新娘去向不明，绘里只留下了一张字条，上面写道“我不明白小鹤的心意”。久未谋面的妖精（三上博史饰）再次出现，他决定再给健一次回到过去的机会。健要拯救小鹤与绘里的婚礼，更要面对自己的内心，追求与礼的幸福。健再次念出咒语“哈利路亚，chance。”©豆瓣', '山下智久', '成田岳', 8.7, 41548, 'tt1270783', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2152409201.jpg', 0.1, 0.9, 13.2, 34.8, 50.9, '0.206586,0.008501,-0.645154,0.635546,0.184701,-0.430916,0.463266,-0.046838,-0.064949,-0.267801,0.061904,0.732947,-0.387482,0.367240,0.256616,0.057396,-0.350292,-0.750396,0.133340,-0.194101,-0.322993,-0.415750,0.309014,0.109443,-0.105911,-0.012352,0.470902,0.158408,0.109602,0.448546,0.242110,0.077612,-0.110175,0.533811,-0.172175,0.342550,-0.104542,0.202590,-0.379726,0.118669,0.268406,-0.337173,-0.587302,0.656579,0.187927,0.341823,0.748093,-0.387763,-0.300890,0.074653,0.162750,-0.124581,-0.095369,0.178334,-0.024284,0.064128,0.112421,0.414336,0.042824,0.172441,-0.250314,-0.040732,-0.092419,0.311291,-0.186924,0.043717,-0.742169,0.492993,-0.104895,0.116176,-0.082538,-0.501830,-0.033609,0.357292,0.006505,0.317808,-0.351267,0.190018,-0.318153,-0.046498,0.619970,0.120861,0.002415,0.706636,-0.067627,-0.624048,0.044815,0.113662,0.018030,0.025986,0.070884,0.361332,-0.071045,-0.244603,-0.394385,-0.109542,-0.456385,-0.225510,0.253426,-0.381687,-0.181587,-0.587260,-0.029760,-0.329000,-0.435886,0.350156,-0.040374,-0.334492,0.485001,-0.670542,0.115273,0.159003,0.351072,-0.354988,0.608226,0.139063,-0.173603,-0.315061,0.040372,0.181141,-0.249685,0.301951,0.333066,0.280297,0.031570,-0.245932,-0.484085,0.407605', '2027925', '34973399', '26958479', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3169043', '我的名字叫可汗', '剧情', '信奉伊斯兰教的里兹瓦·罕（沙鲁克·罕 Shahrukh Khan 饰）从小患有阿斯伯格综合症，母亲去世后，他追随弟弟扎克尔（吉米·舍尔吉勒 Jimmy Shergill 饰）的脚步 从印度孟买移民美国旧金山。里兹瓦在帮弟弟的化妆品公司推销美容产品时认识了经营发廊的单身母亲曼迪娅（卡卓尔 Kajol 饰）。里兹瓦不顾弟弟的反对执意与印度教的曼迪娅结为夫妇，一家人和谐美满。9.11恐怖袭击的发生使美国国内掀起了反对、歧视穆斯林教徒的风潮，里兹瓦与曼迪娅的发廊被迫关张，而曼迪娅的独子山姆（Yuvaan Makaar 饰）更是在一场由种族歧视引发的少年争斗中意外身亡。悲愤的曼迪娅将愤怒发泄在了里兹瓦的穆斯林姓氏“罕”上，说只有里兹瓦告诉美国人民及美国总统他的姓氏并非与恐怖分子相关，才会与他再次相见。就这样，执着的里兹瓦踏上了艰难的觐见总统之途……©豆瓣', '沙鲁克·汗', '卡伦·乔哈尔', 8.4, 58001, 'tt1188996', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2190816486.jpg', 0.8, 2.2, 14.7, 40, 42.2, '0.227740,-0.109374,-0.738314,0.379048,0.185262,-0.338279,0.408536,0.257270,-0.385914,-0.077448,0.134877,0.899468,0.010887,0.035477,0.281379,0.055051,-0.287990,-0.732397,-0.119246,-0.010917,-0.065126,-0.401718,0.128326,-0.325128,-0.264868,-0.387119,0.303887,0.046519,-0.349640,0.592758,0.346689,0.421516,-0.085137,0.254714,0.000233,-0.038664,0.119276,0.153680,-0.503056,0.079832,0.132883,-0.216900,0.123184,0.039834,-0.036395,0.566189,0.368120,-0.321511,0.187204,-0.347145,0.376874,-0.147151,0.091130,0.231123,0.289708,0.101659,0.097435,0.416139,-0.270486,-0.211817,0.234287,-0.054601,-0.452372,0.007687,0.183329,0.215571,-0.741951,0.585756,-0.236830,-0.196960,0.131034,-0.176316,0.365001,0.610437,0.188092,0.474687,0.083040,0.191512,-0.499988,0.317416,0.569873,-0.179758,-0.236214,-0.015369,-0.392454,-0.412133,0.330854,-0.307244,-0.435325,-0.174807,0.324588,-0.270318,-0.197664,0.510948,-0.496633,-0.173774,-0.324054,-0.215463,0.192139,-0.168163,0.021815,-0.499526,-0.001031,-0.382323,-0.088257,-0.013253,0.223284,0.003682,0.579183,-0.692350,0.298077,0.369412,0.590555,-0.573869,0.620884,0.077233,0.070086,-0.230082,-0.101350,0.435972,0.134518,0.095926,0.030907,0.084521,0.200558,0.027949,-0.206873,0.293265', '1309069', '1293303', '1293607', '1306133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3170961', '双龙出手', '剧情', '斯汀（马克·沃尔伯格 Mark Wahlberg 饰）和鲍比（丹泽尔·华盛顿 Denzel Washington 饰）刚刚进行了一次完美的抢劫，身后并无追兵，车内装载着巨额的现金，一路飞驰至荒野的两人心中充满了喜悦。就在准备分赃之时，斯汀和鲍比却都突然掏出了手枪对准彼此，直到这时，两人才发现，他们竟然都是卧底探员，一个效力于美国缉毒局，另一个则隶属海军罪案调查处。很快，斯汀和鲍比就发现，这一场乌龙事件并非巧合，他们不仅背上了“抢劫犯”的污名，还成为了警方大力追捕的对象。在这个世界上，能够还他们清白的只有他们自己了，两个铁血硬汉决定凭借自己的力量，对抗体制，找到真相。©豆瓣', '丹泽尔·华盛顿', '巴塔萨·科马库', 6.6, 15667, 'tt1272878', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1943399103.jpg', 0.9, 7.9, 56.8, 27.6, 6.7, '0.206733,-0.002556,-0.776113,0.609074,-0.003173,-0.412886,0.824027,0.003898,-0.488914,-0.160338,0.286204,0.717091,-0.083123,-0.029181,0.299346,0.007306,-0.512861,-0.947702,-0.205025,-0.229394,-0.438743,-0.436831,-0.643246,-0.237528,-0.038594,-0.109553,0.456462,-0.012423,-0.113175,0.517571,0.313937,0.281962,-0.324966,0.538188,-0.118188,0.057965,0.398145,-0.066674,-0.329086,0.120892,-0.077798,-0.307052,-0.083895,0.201191,-0.121764,0.541065,0.590747,-0.247493,0.010531,-0.191464,-0.031332,-0.384483,-0.091993,-0.046595,0.232206,-0.125983,0.361960,0.302217,-0.164246,0.075081,0.159186,0.059329,-0.896603,0.023774,-0.314712,0.215424,-0.343814,0.316076,-0.350940,-0.157418,0.061084,-0.420310,0.116363,0.338206,0.238381,0.162999,-0.390152,-0.229085,-0.632615,-0.077280,0.583639,-0.086241,-0.231504,0.227333,0.044512,-0.555739,-0.084747,0.026149,-0.096540,-0.139680,0.698698,0.052651,0.067932,0.109295,-0.613246,0.073899,-0.432367,-0.234876,0.018294,-0.329936,0.080770,-0.686110,-0.096134,-0.248124,-0.582851,0.331647,0.138648,0.023449,0.387356,-0.609499,-0.050105,0.637215,0.123132,-0.324697,0.371538,-0.014195,0.219988,-0.106860,-0.097736,-0.063648,0.160791,0.649397,0.312988,0.465215,-0.082580,-0.155816,-0.251099,0.379944', '1307442', '1947080', '6790253', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3172300', '香奈儿秘密情史', '剧情', '1913年的巴黎，可可·香奈儿（安娜·莫格拉莉丝 Anna Mouglalis 饰）在俄国作曲家伊戈尔·斯特拉文斯基（麦德斯·米科尔森 Mads Mikkelsen 饰）的《春之祭》首演中首次注意到了这位被观众的嘘声与喧哗沉重打击的音乐天才。七年后，二人再次相遇，可可慷慨邀请因俄国革命而流亡法国的伊戈尔携乐评人妻子卡特琳娜（伊莲娜·莫罗佐娃Yelena Morozova 饰）和四名子女搬入自己在巴黎郊外的府邸。随着时间的流逝，可可与伊戈尔之间愈发相互吸引。与此同时，可可也在积极研发自己品牌的香水。病中的卡特琳娜还是察觉了自己丈夫对可可的激情，三人的关系变得越来越紧张……本片获2010年法国恺撒奖最佳服装设计提名。©豆瓣', '安娜·穆格拉利斯', '扬·高能', 6.7, 17941, 'tt1023441', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p509619139.jpg', 1, 9.2, 53.3, 28.6, 7.9, '0.381972,-0.055556,-0.621083,0.530830,0.377720,-0.455758,0.625024,0.317239,-0.472823,0.001000,0.335524,0.842377,-0.475201,0.038102,0.621277,0.231713,-0.502376,-0.910768,0.158815,-0.139036,0.136101,-0.402490,-0.177796,0.026841,-0.186627,-0.534767,0.309405,-0.349047,0.026197,1.027856,0.225536,0.237886,0.144666,0.436073,0.349337,0.172752,0.748776,-0.329014,-0.414086,0.295211,-0.063138,-0.257923,-0.326420,0.075164,0.179422,0.328193,0.650533,-0.140055,0.355636,-0.140453,0.343436,-0.115063,0.338520,-0.005419,0.191256,-0.123147,0.186284,0.277176,-0.377050,0.178221,-0.068699,-0.001977,-0.369149,0.416611,0.112977,0.243959,-0.401189,0.540250,-0.322237,-0.111190,0.281195,-0.206352,-0.039247,0.461077,-0.100365,0.454779,-0.365268,0.000275,-0.438307,0.074139,0.401769,0.007298,-0.243783,0.253667,-0.208081,-0.508105,-0.126201,0.051612,-0.622714,-0.286120,0.395788,0.090162,0.275452,0.762772,-0.825773,-0.105082,-0.332982,-0.354157,0.052522,-0.178883,-0.178355,-0.954343,-0.310339,-0.538370,-0.189975,-0.276963,0.032697,-0.032874,0.725294,-0.717936,0.201780,0.407627,0.287024,-0.004961,0.488106,0.145421,0.190194,0.011023,-0.395445,0.371191,-0.203894,0.073886,0.117723,0.537352,0.119624,-0.106123,-0.259623,0.453073', '26365262', '1292050', '3811356', '26788667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3173556', '熟男，我爱你', '爱情', '影片由意大利畅销作家费德瑞克•莫洽执导，执导过不少电影的莫洽，这次首度将自己的小说搬上银幕。电影原著小说在义大利卖出110万册，电影上映10天就以1500万美金成绩刷新意大利近年票房纪录。37岁的亚力（雷欧·波瓦 Raoul Bova 饰）事业有成，长相英俊，最近却刚被女友给甩了。失意的亚力开车上班途中，竟不小心撞到了正要赶去上学的妮奇（米琪拉·奎阿托希欧奇 Michela Quattrociocche 饰），还将她的机车给撞烂了。17岁的妮奇刁蛮难缠，她不但坚持要亚力送她上学，还不忘跟亚力要了电话。之后妮奇没事就打电话让亚力带她去兜风，让她班上同学都看傻了眼。大家纷纷揣测：妮奇对成熟男人的兴趣，似乎还高过学校的男生。正当大家怀疑她是否只是一阵新鲜感时，妮奇却突然决定要带亚力回家，介绍给她年龄相仿的爸妈……©豆瓣', '雷欧·波瓦', '费代里科·莫恰', 7.3, 14004, 'tt1074213', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p900557662.jpg', 1.1, 6.1, 36.7, 40.6, 15.5, '0.071250,-0.171577,-0.531701,0.260820,0.068739,-0.756536,0.410048,0.338232,0.111174,-0.020176,-0.461143,0.499092,-0.565469,0.072571,0.262329,0.464810,-0.805082,-0.560662,0.165233,-0.025869,-0.144095,0.034927,-0.129887,-0.254635,0.097733,-0.228456,0.079260,-0.289084,-0.337135,0.485107,0.120493,0.061236,0.044521,0.621747,-0.290184,0.299223,0.173963,0.136884,0.164536,0.356397,0.165680,-0.055781,-0.272139,0.043303,0.346319,0.479144,0.522677,0.392241,-0.203895,0.229386,0.363136,-0.183449,-0.091458,-0.133289,0.130729,-0.221146,0.239475,-0.135146,0.062363,0.315050,-0.019444,-0.256870,-0.405299,0.182233,0.019540,-0.129512,-0.702861,0.496905,-0.353133,0.061492,0.143607,-0.297165,-0.071127,0.141905,-0.140513,0.345909,0.076233,-0.022235,-0.457108,0.379474,0.331240,0.051262,0.079825,0.459761,-0.044467,-0.223693,0.004781,0.088992,-0.485200,0.134653,0.400655,-0.209026,-0.015665,-0.215795,-0.171874,-0.328226,-0.408168,-0.280112,-0.200226,-0.492331,-0.199696,-0.549800,0.048282,-0.364991,-0.275184,-0.163122,0.384505,-0.013239,0.540208,-0.300350,0.136791,0.617267,0.369436,-0.304321,0.656058,0.012954,-0.462839,-0.175895,0.014864,-0.222433,-0.116741,0.262320,0.275510,0.384244,0.213626,-0.509213,-0.294485,0.595753', '1293511', '4319218', '1819460', '1297606');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3176525', '田禹治', '喜剧', '开天伊始，魔物横行人间，大神彪云台德借神笛封印魔物，岂料因三位守门神仙疏忽大意，致使魔物逃逸，自此，魔与仙依附人类肉身，开始了绵延不绝的对峙。时光荏苒，朝鲜朝时期有一位道术高深、生性风流的道士田禹治（姜东元 饰），其人凭借幻术以戏弄国王为乐，又对美丽的年轻寡妇（林秀晶 饰）心生情愫。为了达到道术的最高境界并让自己的狗跟班小毅（刘海镇 饰）化身为人，田禹治苦寻神笛与青铜剑，不期然与和他同样目标的画坛先生（金允锡 饰）发生冲突，最终导致恩师被画坛所害，自己和小毅也含恨被三位守门神仙封入画中……五百年后，魔物再现人间，三位守门神仙因不知画坛所踪，不得已放出田禹治降妖，一代道士终于重见天日，那宿命的爱情还在等待着他吗？同画坛的恩怨，又该如何了结？©豆瓣', '姜栋元', '崔东勋', 7.2, 21150, 'tt1274293', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p458639341.jpg', 0.8, 5.4, 40.4, 40.8, 12.6, '-0.141888,0.112814,-0.316144,0.562546,-0.186355,0.137683,0.446025,0.070554,-0.352819,-0.321928,0.266891,0.720930,-0.183889,0.074316,0.174248,-0.226994,0.256754,-0.534643,0.170059,-0.200828,-0.199152,0.174335,-0.355107,0.074487,-0.252440,-0.397320,0.604653,0.161706,-0.093779,0.129769,0.137909,0.420290,-0.515431,0.052681,-0.350124,0.099512,-0.176976,-0.031133,0.012696,-0.008047,-0.261803,-0.223654,-0.105313,0.085407,-0.536797,0.043414,0.483385,-0.472788,-0.042851,-0.385915,-0.061257,-0.145632,-0.090520,0.217788,0.426326,-0.138660,0.165007,0.326456,-0.027481,0.054068,-0.106417,0.040411,-0.653017,0.134330,0.075003,-0.121153,-0.209690,0.477519,0.149923,-0.057423,-0.103391,-0.052915,-0.018061,0.256414,0.208624,0.253480,-0.124337,-0.348495,-0.441877,0.321522,0.376235,0.049622,-0.162187,0.223013,0.267004,-0.436371,-0.095993,-0.574284,-0.235077,-0.042200,0.279312,0.166983,-0.038577,0.363266,-0.505102,-0.201750,-0.350050,0.510857,-0.172897,-0.266229,-0.101668,-0.136090,-0.022642,-0.389056,-0.186631,-0.157142,0.330013,0.005598,0.908090,-0.667458,0.195353,0.312676,0.266393,-0.471439,0.731088,-0.102953,0.160335,-0.221203,-0.352525,0.243652,0.242161,0.458498,0.137258,0.098896,-0.137127,0.129343,-0.126546,0.161167', '27602116', '24284209', '35262731', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3178770', '马达加斯加3', '喜剧', '在非洲游历了一圈之后，纽约中央公园的四位明星们继续着回到纽约，回到中央公园的旅程。不过，只要旅途中有猩猩和那群企鹅的“帮忙”，旅程就没有想象中的那么顺利。在蒙特卡洛的一家赌场里，由于大家的耍宝，大闹赌场，进而招致了心狠手辣的动物管理局上尉杜波依斯（弗兰西斯·麦克多蒙德 Frances McDormand 配音）的围追堵截。为了逃过追捕，大家逃进了一个在欧洲进行巡回演出的马戏团。在马戏团里，大家延续着“马达加斯加”式的幽默，笑料百出。虽然，欧洲这一路上的旅行并不顺利，不断受到杜波依斯上尉的追捕威胁，不过大家一直怀揣着回到纽约，回到纽约中央公园的梦想。在马戏团，还帮助了东北虎维塔利（布莱恩·科兰斯顿 Bryan Cranston 配音）、美洲虎吉亚（杰西卡·查斯坦 Jessica Chastain 配音）以及海狮斯蒂芬诺（马丁·肖特 Martin Short  配音）重拾对马戏表演的信心。', '本·斯蒂勒', '康拉德·弗农', 8.2, 167394, 'tt1277953', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1503869385.jpg', 0.2, 1.1, 17.8, 49.2, 31.7, '0.263194,-0.071541,-0.704921,0.586436,0.146033,-0.399516,0.650504,0.007989,-0.408064,-0.058234,0.097788,0.861707,-0.239031,0.293102,0.338363,-0.041914,-0.831562,-0.424300,-0.149925,-0.089720,-0.016615,-0.429025,-0.325805,-0.107745,-0.084627,-0.211261,0.216833,0.155366,-0.228037,0.590720,0.190554,0.092903,-0.139245,0.363280,-0.362606,0.123385,0.356446,0.022279,-0.220585,0.450609,0.130777,-0.106650,-0.265968,0.132814,0.394734,0.169868,0.733878,-0.381491,0.077050,0.067463,0.156438,-0.332555,0.036216,0.117608,0.333934,-0.106125,0.057268,0.089424,-0.118761,0.421404,-0.060208,-0.284664,-0.732965,0.034440,-0.173311,0.395978,-0.561420,0.439170,0.065230,0.106240,0.006125,-0.109052,0.219328,0.429596,0.067823,0.271193,0.037493,0.212753,-0.494663,0.119682,0.762812,-0.134896,-0.290582,0.173208,0.072590,-0.367828,0.096262,0.028399,-0.443559,-0.302829,0.357771,-0.291091,-0.129169,0.158146,-0.790699,0.200624,-0.190861,-0.616929,-0.103761,-0.179072,0.128781,-1.278477,0.254235,-0.392261,-0.026209,-0.036724,0.010954,-0.154446,0.498856,-1.003898,0.273518,0.770465,0.262196,-0.262878,0.553678,-0.089997,0.263457,-0.135673,-0.185959,0.395724,0.160443,0.480103,0.238884,0.564049,-0.047227,-0.554804,-0.261199,0.482063', '2