INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3179698', '伦敦战场', '悬疑', '改编自英国小说家马丁艾米斯(Martin Amis)1989年作品《伦敦战场》。安柏赫德主演。以英国伦敦为背景，讲述一个具有预知未来能力的美女，她与3个不同的男人周旋，然而她已预知，其中一个人将会谋杀她……', '安柏·赫德', '马提·卡伦', 5.8, 11002, 'tt1273221', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2171878843.jpg', 8, 26.3, 43.3, 15.1, 7.4, '0.367052,-0.026400,-0.473076,1.148846,0.198836,-0.061852,0.813674,-0.051303,-0.400835,-0.589653,0.158839,0.983001,-0.152442,-0.046091,0.591996,0.027481,-0.359575,-0.623475,0.165155,-0.060960,-0.414090,-0.649118,-0.591629,-0.574981,-0.261816,-0.142611,0.721416,-0.002537,-0.206175,0.223794,0.131558,0.245465,0.180734,0.177436,0.078208,-0.188411,0.181137,-0.088910,-0.297206,0.517649,0.010912,-0.015362,-0.105988,0.209202,-0.511750,0.099597,0.624137,-0.334907,0.266853,-0.392396,0.676183,-0.075471,0.272169,-0.125191,0.216720,-0.316037,-0.081521,0.248539,-0.069829,-0.292516,0.205615,-0.048038,-0.702643,-0.079039,0.277084,0.007812,-0.301382,-0.021068,-0.196997,0.128034,-0.177349,-0.011528,-0.238691,0.278692,0.505069,0.299429,0.162635,-0.106320,-0.555440,0.349368,0.469506,0.033956,-0.385605,0.142597,-0.406976,-0.620272,-0.265711,-0.338001,-0.751542,0.115474,-0.028092,-0.040064,-0.125654,0.393787,-0.293838,0.060151,-0.514074,0.183439,-0.392472,-0.496336,0.076299,-0.664962,-0.500809,-0.025768,-0.231982,-0.131935,0.252656,-0.310651,0.975664,-0.602486,-0.062529,0.832017,0.404318,-0.446305,1.142949,0.033031,0.159231,-0.558447,-0.035135,0.724726,0.013138,-0.506898,-0.322773,0.406244,0.128783,-0.026263,-0.025094,0.474669', '22265121', '2338019', '2027945', '1294048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3179706', '环形使者', '动作', '未来，2044年。时间旅行从被发明的一开始就属于非法，只有当黑帮组织想清理某个特定对象、又不愿意在此世界留下任何痕迹时，才会出动“环形使者”。他们专门负责处决那些被时间传送回彼世界的目标。之所以称为“环形使者”，因为他们最终必须杀死未来的自己——这样才不会给未来主顾留下任何的麻烦。这个过程被称为“封环”。杀手乔（约瑟夫·高登-莱维特 Joseph Gordon-Levitt 饰）是最年轻的环形使者，弹无虚发，然而当他想处决来自未来的自己（布鲁斯·威利斯 Bruce Willis 饰）时，却遭到激烈反抗而失手。老年乔希望杀死未来封环计划中的关键人物——唤雨师，从而改变妻子（许晴 饰）的命运；青年乔在追杀过程中遇到了农场单亲妈妈莎拉（艾米莉·布朗特 Emily Blunt 饰），意外的成为了一对母子的保护人。两个版本的乔在这场改变未来（和现在）的豪赌中各出奇谋，上演了自我的巅峰对决......', '约瑟夫·高登-莱维特', '莱恩·约翰逊', 6.9, 163225, 'tt1276104', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1682562648.jpg', 0.8, 6.3, 47.4, 37.5, 8, '-0.100650,0.154289,-0.609190,0.540995,-0.237746,-0.048782,0.579147,-0.131414,-0.417989,-0.449179,0.187546,0.659406,0.011017,0.177264,0.483033,-0.164039,-0.323890,-0.639676,-0.093743,-0.157906,-0.705878,-0.375707,-0.216673,-0.394012,0.034358,-0.246803,0.731387,0.216398,-0.458009,0.126509,0.175028,0.425907,-0.274796,0.451338,-0.065753,-0.095567,0.322916,-0.160063,-0.324822,0.279221,-0.302267,-0.096268,-0.006911,0.399334,-0.259822,0.519821,0.521945,-0.561607,-0.118024,-0.349067,0.267773,-0.365935,-0.014143,-0.000349,0.374161,-0.237023,0.237182,0.178982,-0.065197,-0.051076,0.170405,-0.179527,-1.087088,-0.063574,0.217983,-0.078698,-0.417197,0.126280,0.014992,-0.049934,0.073258,0.004519,0.345977,0.653495,0.649457,0.051319,-0.293023,0.003052,-0.396878,0.167696,0.775198,-0.173313,-0.277896,0.238454,-0.023852,-0.273289,-0.018499,-0.372841,-0.279329,0.182536,0.345728,0.225374,-0.004586,0.284827,-0.374405,-0.197964,-0.320126,-0.095721,0.206537,-0.362937,-0.088001,-0.490019,0.004868,-0.174512,-0.309263,0.162284,-0.086598,-0.243625,0.614952,-0.706339,0.258912,0.459388,0.341660,-0.651404,0.777760,0.216742,0.272744,-0.403133,0.111572,0.120206,0.134936,0.144422,-0.021353,0.080314,0.218101,-0.155371,-0.093159,0