INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3179758', '邻家特工', '喜剧', '鲍伯（成龙 饰）与独自带着三个孩子的女邻居吉莉安相恋已经三个月了，然而三个小鬼并不怎么喜欢这个窝囊、乏味，如同机器人般一程不变的钢笔商，但鲍伯其实是一名即将退休的秘密特工。吉莉安因故外出，鲍伯决定由他来照顾孩子，一个大男人要应付三个古灵精怪的小孩子已经足够让他头疼，而孩子们无意间下载了一伙罪犯的细菌配方引来了坏人的追杀，此时，中情局内部也有人想得到配方。在保护孩子们的过程中，鲍伯的身份爆光，吉莉安为了保护孩子们和他分手。为了打击犯罪，为了保护孩子们，鲍伯必须重新出马……本片是成龙继《尖峰时刻》系列后最新一部好莱坞作品。©豆瓣', '成龙', '布莱恩·莱温特', 6.3, 95444, 'tt1273678', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1509641713.jpg', 2, 12.5, 57.6, 21.9, 5.9, '-0.066397,-0.244112,-0.468345,0.354447,-0.382436,-0.277284,0.560038,-0.059852,-0.672272,-0.459266,0.077212,0.798668,0.077963,0.284011,0.040569,-0.105247,-0.291730,-0.516782,-0.227675,-0.241758,-0.381476,-0.266742,-0.051537,-0.348911,-0.299802,-0.294710,0.593397,-0.040944,0.153241,0.243880,0.595076,0.228726,-0.293201,0.199442,-0.166446,-0.403350,0.138842,-0.265412,-0.226483,0.290113,-0.122697,0.219257,-0.248603,0.143618,0.059076,0.183428,0.644164,-0.270844,-0.248795,-0.475204,0.162275,-0.288311,-0.149713,-0.127241,0.272476,0.016073,0.540472,0.090300,-0.225756,0.107811,-0.007520,-0.420643,-0.743489,0.062836,0.154807,0.003879,-0.685158,0.047600,-0.060564,-0.006725,0.074191,-0.306641,0.254847,0.383940,0.201964,0.465252,-0.403450,0.120261,-0.429543,0.181446,0.598593,0.032873,-0.133205,0.362690,-0.086027,-0.112599,0.075751,-0.386240,-0.587013,0.282958,0.247914,0.032775,-0.433882,0.042196,-0.490536,0.066441,-0.263707,-0.043062,-0.208351,-0.558115,0.065791,-0.536238,0.257011,-0.159712,-0.144019,0.161781,0.177151,-0.231949,1.179885,-0.586734,0.341901,0.530565,0.141131,-0.905563,0.427207,0.273146,0.312778,-0.323847,-0.080928,-0.127687,0.324390,-0.128875,0.111264,0.385026,-0.076034,-0.303075,-0.263373,0.227648', '24284209', '27602116', '1296770', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3181788', '余生的第一天', '剧情', '杜瓦尔家是居住在法国某市郊区的五口之家，身为出租车司机的罗伯特（Jacques Gamblin 饰）和妻子玛丽—让内（Zabou Breitman 饰）共同抚养三个儿女长大。长子阿尔贝（Pio Marmaï 饰）早年离家，在外独闯生活；次子拉菲尔（Marc-André Grondin 饰）是一个似乎对凡事都无所谓的散漫青年；最小的女儿弗洛尔（Déborah François 饰）从乖乖女变成叛逆少女，她的反叛时常令母亲不高兴。阿尔贝的离开让玛丽分外伤心，在此之后她转而求学，努力追寻自己的梦想。随着时间的流逝，父母、子女、兄妹彼此各有各的心事，然似乎总有什么将他们的关系拉远……本片荣获2009年法国凯撒电影节最佳剪辑、最佳新人男主角（Marc-André Grondin）和最佳新人女主角（Déborah François）三项大奖。©豆瓣', '雅克·冈布兰', '雷米·贝占松', 8.4, 16553, 'tt0926759', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1486075677.jpg', 0.2, 1, 13.9, 46.1, 38.8, '-0.114161,-0.230116,-0.565886,0.566802,-0.010449,-0.411351,0.592653,0.214960,-0.644646,-0.376151,0.231791,0.868021,-0.139443,0.291440,0.331060,0.110757,-0.239056,-0.595480,-0.166544,-0.133015,0.006948,-0.376742,-0.073868,-0.083480,-0.267031,-0.140081,0.785083,-0.196679,0.162385,0.475044,0.370610,0.097467,-0.262587,0.029185,-0.275009,0.111629,0.122575,0.006073,-0.308111,0.054020,-0.011780,-0.065735,-0.225140,-0.088565,0.227362,0.436479,0.744130,-0.094815,0.009415,-0.039386,0.284686,-0.202053,-0.225809,0.069879,0.072359,-0.084898,0.296753,0.227416,-0.144351,0.100751,-0.095961,-0.185234,-0.570632,0.100715,0.304421,0.073381,-0.741698,0.575984,-0.094516,-0.366759,0.193737,-0.122999,0.161471,0.468682,0.048768,0.328300,-0.195318,0.233077,-0.342860,0.326160,0.578271,0.055658,-0.231858,0.317880,-0.420120,-0.350378,0.069407,-0.340820,-0.669240,-0.053748,0.173749,0.048327,0.235772,0.387749,-0.338883,-0.070114,-0.276160,-0.084735,0.345737,-0.528922,0.037421,-0.539209,0.016713,-0.603844,-0.296920,-0.075194,0.027009,-0.244501,0.886425,-0.827419,0.231683,0.250464,0.270694,-0.586911,0.798467,0.235353,0.385021,-0.492063,-0.090941,0.496497,-0.076010,-0.153400,-0.202004,0.043777,-0.075803,-0.063025,-0.282459,0.386309', '3445516', '1292720', 