INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3182495', '天庭外传', '喜剧', '陈塘关总兵李靖负责替天庭看管宝物，他的儿子哪吒（释小龙 饰）聪明伶俐，武艺高强。某日，土地公公的干儿子猪八戒（郝邵文 饰）闯入府中，惹出不少祸端，幸得哪吒帮助方脱离危险，两人从此成为好友。两个小家伙玩心骤起，将书房弄得乱七八糟。适值此时，西海和东海龙宫联姻，西海龙女不愿出嫁。哪吒在海边戏耍，搅扰龙宫动荡不安，龙女更趁机逃跑。哪吒出手相助，与三太子展开厮杀。另一方面，东海傲来国花果山上有一尊石猴，经过数千年风吹雨打、吸收日月精华，石猴（林志颖 饰）终于幻化成形，在猴祖的点播下他学会七十二般变化，并决定前往东海龙宫取回如意金箍棒。他的到来更在龙宫引起一片混乱……©豆瓣', '林志颖', '陈志华', 5.9, 6341, 'tt13550394', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2169292776.jpg', 6.1, 20.9, 51.7, 14.5, 6.7, '0.005306,0.399943,-0.674872,0.402186,0.223792,-0.078341,0.330455,0.180737,-0.541300,-0.081552,0.198606,0.367498,-0.244630,0.043344,-0.161662,-0.071580,-0.136926,-0.095670,0.007691,0.166127,0.248452,0.017906,-0.440828,0.193589,-0.209898,-0.448840,0.494999,-0.070790,0.212706,0.334187,0.035763,-0.062965,-0.417260,0.230806,-0.189895,0.242891,-0.603478,0.463215,-0.008104,0.220619,-0.399355,-0.342585,-0.129003,0.100002,0.089951,0.013768,0.519761,-0.299931,-0.092573,-0.514385,0.313538,-0.046872,0.035490,0.049804,0.459409,-0.085282,0.094217,0.218716,-0.367256,0.221348,0.097501,-0.219189,0.109358,0.149605,0.085937,0.072686,-0.288631,-0.211304,0.203779,-0.047921,-0.089947,-0.352370,0.139325,0.535396,-0.044881,-0.017604,-0.273057,-0.003629,-0.488339,0.244376,0.535918,-0.449584,0.421852,-0.290172,0.453936,-0.126391,0.143638,-0.160112,0.120688,-0.236697,0.435289,-0.179924,0.281911,0.301431,-0.317283,-0.103638,-0.482659,-0.081801,-0.159710,0.033016,0.049857,-0.454975,0.071790,0.100664,-0.155628,-0.277113,0.400310,0.165287,0.482461,-0.362311,0.173081,0.197288,0.021382,-0.505963,0.420703,-0.010859,0.290833,-0.374382,-0.083239,0.039542,0.142090,0.332444,-0.059155,-0.143633,-0.213170,0.076868,-0.404617,-0.154400', '1292846', '1302753', '6007281', '30299515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3182864', '疯狂的心', '剧情', '本片根据美国小说家托马斯·科布（Thomas Cobb）的同名小说改编。拜德·布雷克（杰夫·布里吉斯 Jeff Bridges 饰）是一名酗酒成性的落魄蓝调乡村歌手，在新墨西哥州州府圣菲市表演时，认识了圣菲报的记者琴（玛吉·吉伦哈尔 Maggie Gyllenhaal 饰）。濒临破产的拜德赶往凤凰城为自己的旧时学生，新晋乡村红歌星汤米·斯威特（科林·法瑞尔 Colin Farrell 饰）的演唱会开场。演唱会后在从凤凰城到圣菲市的路上拜德出车祸，在琴家养伤，二人情愫渐生。拜德重新开始写歌，并向多年好友韦恩（罗伯特·杜瓦尔 Robert Duvall 饰）倾诉心声，一切似乎都在向着好的方向进行。但在琴携四岁的儿子来休斯顿探访拜德的过程中，一件意外却让拜德真正意识到自己的人生路在何方……本片荣获第82届奥斯卡最佳男主角（Jeff Bridges）、歌曲2项大奖，并获得最佳女配角提名（Maggie Gyllenhaal）。英国学院奖最佳男主角提名和最佳原创音乐提名，以及获金球奖最佳剧情片男主角奖及剧情片最佳原创歌曲奖。', '杰夫·布里吉斯', '斯科特·库珀', 7.6, 17617, 'tt1263670', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1671241723.jpg', 0.4, 2, 30.3, 50.9, 16.5, '-0.025758,-0.099068,-0.449678,0.530965,0.430995,-0.354177,0.462964,0.161626,-0.429861,-0.087981,0.144831,1.087126,-0.267410,0.109790,0.622370,0.126906,-0.539289,-0.741667,0.062385,-0.205063,0.142725,-0.370731,-0.215406,0.211124,-0.070006,-0.524219,0.584079,-0.111163,-0.029350,0.619640,0.646524,0.126714,-0.130751,-0.109350,0.227113,0.244408,0.584202,-0.061864,-0.477956,0.630582,-0.142070,-0.139729,-0.515718,0.023492,0.225724,0.355565,0.726371,0.084312,0.232376,0.206068,0.640611,-0.140357,0.002676,-0.237446,0.189197,-0.217916,0.400770,0.077209,0.027591,0.170364,-0.232663,-0.257156,-0.585769,0.200228,0.283043,0.340938,-0.378398,0.365524,-0.195161,0.092429,0.019383,-0.035894,0.033887,0.054687,0.117002,0.010663,-0.138246,-0.013724,-0.153843,0.711793,0.292912,-0.020151,-0.312874,0.274192,0.092508,-0.573826,-0.197528,-0.047498,-0.528461,-0.009080,0.465619,-0.125991,0.437836,0.047939,-0.336550,-0.145564,-0.230404,-0.243336,0.057087,-0.125117,0.075408,-0.940676,0.019879,0.084879,0.101734,-0.524482,0.271058,-0.250741,0.395709,-0.561415,0.368056,0.560354,-0.158046,-0.160231,0.534099,-0.008542,0.182983,-0.254111,-0.363978,0.320843,-0.140951,0.180315,-0.176763,0.326347,0.043419,-0.502086,-0.482319,0.629442', '34961898', '3275168', '1298616', '1484091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3183490', '约会之夜', '喜剧', '税务律师菲尔·福斯特（史蒂夫·卡瑞尔 Steve Carell 饰）与房地产经纪人的妻子克莱尔·福斯特（蒂娜·费 Tina Fey 饰）是居住在新泽西州的一对普通中年夫妇，育有两子，每日生活疲累而按部就班。受朋友分居的影响，菲尔心血来潮决定将每周末的晚餐约会改到城里，去曼哈顿新开张的一家海鲜餐厅就餐。没有预约的二人顶替了他人的位子，却没曾想吃到中途被两名陌生人挟持出餐厅，用枪威胁他们归还一个闪存。不明就里且吓得半死的福斯特夫妇想办法逃脱，找到克莱尔过去一位名叫霍尔布鲁克（马克·沃尔伯格 Mark Wahlberg 饰）的客户帮忙，却依然无法摆脱追杀。二人甚至还得假扮皮条客与舞女闯入黑帮头子乔·莫雷托（雷·利奥塔 Ray Liotta 饰）的脱衣舞厅周旋，洋相百出。©豆瓣', '史蒂夫·卡瑞尔', '肖恩·利维', 6.8, 21769, 'tt1279935', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p471743661.jpg', 0.9, 7.2, 49.2, 35.2, 7.4, '0.323284,-0.045267,-0.551563,0.423388,-0.184990,-0.517667,0.805728,0.438408,-0.171731,-0.458823,0.080587,0.499375,-0.178372,0.269544,0.575784,0.172266,-0.207000,-0.392096,0.218765,-0.105254,-0.157812,-0.510754,-0.257217,-0.219255,-0.239070,-0.075720,0.146981,-0.222619,-0.052521,0.264676,0.325536,0.276650,-0.148969,0.291764,-0.082447,0.052807,0.212875,-0.245967,-0.507298,0.263405,-0.095932,-0.041152,-0.256950,0.134334,0.534522,0.409008,0.267692,0.061864,0.014276,0.097117,0.062064,0.054635,0.066832,0.227202,0.380066,-0.255805,0.301962,-0.141087,-0.363276,0.052169,0.212687,0.016405,-0.609458,0.364042,-0.020170,0.027694,-0.616938,0.161660,-0.238619,0.041486,-0.150742,-0.139927,0.083490,0.241816,0.005043,0.287048,0.236229,0.108801,-0.747107,0.099928,0.578532,-0.006072,-0.244568,-0.022455,0.018369,-0.224429,0.006461,-0.196313,-0.282581,-0.127695,0.327544,-0.101446,-0.074698,-0.067375,-0.410730,-0.212691,-0.513131,-0.145328,0.082772,-0.235471,-0.032830,-1.089852,0.284606,-0.000917,-0.174538,0.195875,0.195499,-0.006004,0.215062,-0.641998,0.136877,0.511150,0.374722,-0.458573,0.702827,0.034270,0.410694,-0.143327,-0.166057,0.077708,0.415860,0.150376,0.418595,0.278958,-0.049376,-0.024714,-0.292995,0.247208', '10466639', '6517421', '25833539', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3187790', '空之境界 第五章 矛盾螺旋', '动画', '“荒耶，你在追求什么？”“真正的睿智。”“在哪里追求？”“只在自己的心里。”1998年11月，胭条巴遇到了两仪式并被她吸引。胭条巴每晚都做噩梦，自己犯下的罪行不断重现。两仪式为了调查事件的真相，前往胭条巴的寓所，却不知道，他们不知不觉已经进了敌人的圈套——复杂的“矛盾螺旋”。而在这一切的背后，是名为荒耶宗莲的男子。他宿命的劲敌是魔术师苍崎橙子，最强的人偶师。伽藍堂全体出动，赌上性命的战斗即将开始。日本同人小说最高境界《空之境界》全七章动画化，本作为第五章电影版。©豆瓣', '坂本真绫', '平尾隆之', 9.3, 23202, 'tt1278060', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2194403556.jpg', 0.2, 0.4, 4.2, 22, 73.1, '0.276488,0.172907,-0.684717,0.158141,0.035578,-0.046527,0.498923,-0.009108,-0.295498,-0.391856,0.424983,0.692000,-0.156133,-0.001866,0.136691,-0.192866,-0.063652,-0.802394,-0.079830,-0.365153,-0.290407,-0.378874,-0.157735,-0.122782,0.106681,-0.161059,0.703286,0.323221,-0.193534,-0.124698,0.455868,0.488361,-0.059412,0.360875,-0.209186,0.006192,0.059433,-0.219758,-0.008119,0.033495,-0.091563,-0.290333,-0.313929,0.473906,-0.093868,0.310950,0.595782,-0.484785,-0.178257,-0.097719,0.287715,-0.475273,-0.228250,0.018007,0.212019,-0.122453,0.083518,0.397235,0.178307,-0.046047,0.002407,-0.306826,-1.123681,-0.128694,0.188402,0.258673,-0.541224,0.175855,-0.137345,0.131111,0.193929,-0.013875,0.205456,0.554848,0.393077,0.196501,-0.311656,-0.122084,-0.566464,0.178464,0.776505,0.026569,-0.241883,0.365917,0.005081,-0.348669,-0.563577,-0.402032,-0.111123,0.098075,0.140880,0.209371,-0.009852,0.496578,-0.523693,-0.314165,-0.169504,-0.157586,0.044571,-0.512742,0.033183,-0.322950,-0.230663,-0.417219,-0.258596,-0.048760,0.263887,-0.255905,0.738140,-0.863269,0.332591,0.710276,0.107341,-0.449356,0.590740,0.181400,0.066269,-0.327042,-0.099447,0.314792,-0.013763,0.334259,0.074656,0.444894,0.300375,0.228389,-0.468665,0.666867', '30163500', '1793491', '25917239', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3188042', '变身西装', '喜剧', '大木琢郎（塚地武雅饰）是一家小餐馆的店长，虽然待人和善，脾气又好，可年过而立的他至今连一次恋爱都未成功过。店里来了新的服务员宽子（北川景子饰），长相甜美又勤劳的她一下子博取了众人的喜欢，当琢郎鼓起勇气对其告白时，对方却逃跑了。大受打击的琢郎将此归咎于自己外表的缺陷而懊恼不已，此时他意外地获得了一套“英俊西装”，穿上它，琢郎便化身为外表光鲜亮丽的光山杏仁（谷原章介饰），他火速跨入模特界，并和第一人气模特来香（佐田真由美饰）搭档，迅速蹿红为人气王。可是当巨大的刺激过后，一人分饰二角的情形开始困扰琢郎，大木琢郎和光山杏仁，他最终要选择哪一个呢？©豆瓣', '塚地武雅', '英勉', 6.7, 6011, 'tt1279943', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2192659534.jpg', 1.5, 8.4, 51.8, 29.5, 8.8, '0.108210,0.184616,-0.548150,0.456946,-0.353650,-0.516322,0.677024,0.334964,-0.325058,-0.154903,0.161832,0.719115,-0.390145,0.198835,0.100047,0.186873,-0.049269,-0.539376,-0.070374,-0.028804,-0.092364,0.161806,-0.369628,-0.000994,-0.161761,-0.050914,0.395143,-0.038170,-0.067977,0.568342,0.451605,-0.042815,0.291812,0.606925,-0.139005,0.112870,-0.165379,0.048794,0.052686,0.104499,-0.010592,-0.345485,-0.234644,0.423550,-0.033784,0.503044,0.513618,-0.123205,-0.263085,-0.079166,0.330027,-0.007500,-0.005439,0.294219,0.298504,-0.092403,0.314741,-0.128596,-0.222461,-0.039584,0.097502,-0.117364,-0.573509,-0.022364,0.001667,0.026483,-0.493437,0.365850,-0.259146,-0.148014,0.048193,-0.466172,-0.410554,-0.027810,0.361107,0.268368,-0.161801,0.192996,-0.272584,0.337260,0.400330,0.380784,-0.297886,0.554653,-0.214461,-0.675698,-0.157086,-0.253567,-0.299029,0.030626,0.234977,0.189149,0.039747,-0.173306,-0.675072,0.124433,-0.317948,0.014730,0.018237,-0.217814,-0.326413,-0.294855,-0.001955,-0.489587,-0.271521,-0.094952,0.076257,-0.036429,0.705988,-0.670195,-0.101906,0.419505,0.193208,-0.392425,0.435463,0.060098,0.022207,-0.067566,-0.249410,-0.050169,-0.164535,0.430098,0.235535,0.639545,-0.050980,-0.217090,-0.389764,0.399203', '34429100', '30162520', '35144311', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3189969', '皇家刺青', '剧情', '泥瓦匠鲁二（张桐 饰）因为修缮皇宫，巧遇被太后软禁的皇上。皇上在鲁二私处刺青，拟诏派他营救天牢中的大学士（王劲松 饰）。鲁二临危受命，详细制订了营救大学士的计划。他为潜入天牢假意打劫，却无意中邂逅了赌场老板娘红中（黄小蕾 饰），二人不打不相识。红中有个死对头许三刀，因冒犯钦差大臣福尔摩也被抓入天牢准备问斩。鲁二在潜入天牢，在搭救大学士之时，刚好赶上刺客前来行凶，两人狼狈逃出天牢，福尔摩在后面紧紧追赶。在逃亡中，大学士对鲁二的身份表示怀疑，后者遂露出私处方才验明正身。正当二人准备按刺青寻找藏宝图之时，福尔摩、红中、许三刀等形形色色的人物也卷入了这场追杀……本片是一部山寨版的《越狱》，其中花儿乐队、戴军、刘桦等明星友情出演。©豆瓣', '黄小蕾', '冯超', 4.7, 7491, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p790244736.jpg', 21.2, 34.1, 34.5, 7.7, 2.4, '0.068589,0.087613,-0.347566,0.451055,0.108673,-0.205125,0.774482,0.330021,-0.360804,-0.280162,0.777834,0.339622,-0.353439,-0.022547,0.314207,-0.152677,-0.235000,-0.357093,-0.092811,-0.146032,-0.203927,-0.268888,-0.065412,-0.058819,-0.140250,-0.083229,0.422108,0.139734,-0.110347,0.524566,0.380584,0.137212,-0.525959,0.367315,0.107196,0.061286,0.256791,-0.122544,-0.227174,-0.065675,-0.213483,-0.623959,-0.137276,-0.080570,0.148717,0.501239,0.515151,-0.323314,0.297601,-0.003408,0.191517,-0.428721,0.204409,0.272933,0.182685,0.034254,0.075759,0.131662,-0.124793,-0.006731,-0.094295,-0.171203,-0.582310,0.100941,0.168487,-0.021611,-0.464372,0.139832,-0.160914,0.146510,-0.073464,-0.225198,0.309125,0.316072,0.111316,-0.034626,0.097205,-0.037856,-0.366509,0.422174,0.258660,-0.188247,0.215183,-0.233837,0.276652,-0.468356,0.386011,0.208349,-0.022288,-0.089554,0.687938,-0.181603,0.057198,0.113009,-0.010649,-0.260399,-0.532059,0.235849,0.052818,-0.062984,-0.066300,-0.572251,-0.262533,0.075434,-0.194596,-0.128980,0.363958,0.075642,-0.151437,-0.359912,0.137929,0.175849,0.102012,-0.607699,0.461283,0.143548,0.025816,-0.024381,-0.067702,-0.091981,0.313552,0.335326,0.278552,0.367011,-0.207745,-0.333164,-0.467156,0.075923', '1578663', '5319819', '26897427', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3193964', '黑暗乡村', '悬疑', '迪克（托马斯·杰恩 Thomas Jane 饰）和吉娜（劳伦·泽曼 Lauren German 饰）是一对新婚夫妇，他们驾车沿着州际公路前往塞多纳，尽情享受这趟蜜月之旅。夜幕降临，迪克不知不觉间偏离了原来的95号公路，所谓春宵一刻值千金，这对夫妇似乎并不太在意迷路这件事，反而尽享欲望和速度所带来的双重快感。当激情过后，却有一个全身是血的男人（康·谢尔 Con Schell 饰）突然出现在他们的车前。迪克救助了受伤的男子，而对方则试图杀掉他。纠缠厮打之中，受伤男子被迪克所杀。为了防止惹上麻烦，夫妇俩将尸体偷偷掩埋。原本以为一切不快就此结束，谁曾想迪克和吉娜的诡异旅程才刚刚开始……©豆瓣', '托马斯·简', '托马斯·简', 6.5, 8922, 'tt0469318', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p913098676.jpg', 3.7, 12.8, 46.8, 28.6, 8.1, '0.313356,0.020440,-0.734272,0.306575,0.155584,-0.458105,0.924351,-0.106515,-0.410681,-0.264106,0.111133,0.442739,-0.187912,-0.001485,0.373738,0.182310,-0.509057,-0.554523,0.179932,0.000726,-0.418281,-0.367623,-0.182709,-0.047790,-0.023819,-0.372509,0.285521,0.175951,-0.200589,0.618155,0.481964,0.347491,-0.125725,0.558058,-0.111414,0.053802,0.038372,-0.160795,-0.122751,-0.083203,-0.077371,-0.334532,0.050466,0.121971,-0.025443,0.254317,0.731292,-0.294422,-0.053110,-0.066039,-0.062145,-0.470235,0.265668,0.163358,-0.038418,-0.055274,0.265051,0.146469,-0.168655,-0.175551,0.140294,-0.048312,-0.613843,0.408720,-0.227176,0.225604,-0.267885,0.139217,-0.202965,-0.220974,0.245160,-0.206515,0.171935,0.389578,0.296338,0.050683,-0.250918,-0.184149,-0.355448,-0.111373,0.822364,0.012310,0.073903,0.575021,-0.070766,0.010397,0.116828,0.163009,-0.237115,-0.113580,0.367774,0.320318,-0.022000,0.358050,-0.390171,-0.008350,-0.419780,-0.149736,-0.102567,-0.291102,-0.168731,-0.455324,-0.049998,-0.336404,-0.272304,-0.026858,-0.058552,-0.162429,0.105950,-0.490795,0.243800,0.525101,0.248458,-0.326972,0.437042,-0.006833,0.054593,-0.103881,-0.262731,0.162252,0.190025,0.118368,0.253134,0.403776,-0.035075,0.096797,-0.277415,0.558524', '3011051', '1773217', '1300958', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3194100', '厨房', '剧情', '本片为韩国原创作品，与吉本芭娜娜的同名小说并无关系。尚仁（金泰宇饰）和沫莱（申敏儿饰）结婚一周年的纪念日前夕，为了庆祝这个特殊的日子，沫莱特意到美术馆给丈夫挑选礼物，而在枝那里她邂逅了一名陌生的男子，并与其发生了性关系。充满内疚心情的沫莱回到家后，终于忍不住和尚仁坦 诚了一切，并得到了后者的体谅。尚仁也有惊人的举动：辞去了薪水丰厚的证券公司经理一职，向妻子告白了一生的愿望——开一家受欢迎的料理店。沫莱欣然支持他，万万料不到的是前来帮尚仁打理生意的正是与她发生了关系的青年多瑞（朱智勋饰）！从法国回来的多瑞有着出色的料理天分，丈夫有他的帮助是如虎添翼，可从多瑞住进他们家的那天开始，危险的三角关系也就拉开了序幕......©豆瓣', '申敏儿', '洪志英', 6.7, 9550, 'tt1516552', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p743164967.jpg', 1.6, 9.8, 49.9, 29, 9.8, '0.142075,0.165228,-0.491677,0.444688,0.106208,-0.435272,0.639822,0.421623,-0.294200,-0.361462,-0.039555,0.721336,-0.190129,0.092482,0.418034,0.268036,-0.231665,-0.949121,-0.028045,-0.238938,-0.040528,-0.356670,0.219902,-0.199853,-0.117625,-0.238609,0.462706,0.060998,-0.136004,0.594099,0.556840,0.173830,0.022972,0.540891,-0.151323,0.073657,-0.016146,0.213780,-0.498966,0.220433,0.130789,-0.005524,-0.179713,0.246431,0.389510,0.406806,0.496633,-0.028637,-0.374616,0.184501,0.367583,-0.069289,0.275809,0.035081,0.306792,-0.025565,0.121028,0.223187,-0.285386,0.169779,0.035723,-0.261080,-0.802061,-0.013241,0.195680,0.038151,-0.411490,0.693248,-0.049642,-0.163721,0.163341,-0.253423,0.222297,0.366449,0.059563,0.306461,-0.109848,0.273737,-0.405268,0.199759,0.705990,0.103070,0.062825,0.574442,-0.389371,-0.431389,-0.256766,-0.037587,-0.422433,0.179701,0.355021,0.301097,0.050975,0.177470,-0.607049,-0.095030,-0.254968,-0.086892,0.297861,-0.320516,-0.022197,-0.573682,-0.029743,-0.404267,-0.387187,-0.050699,0.113313,-0.425727,0.650437,-0.839765,-0.075101,0.518295,0.364821,-0.477932,0.725479,0.004328,-0.006404,-0.098190,-0.161677,0.177166,-0.099112,0.121534,-0.043638,0.309817,0.114169,-0.230496,-0.302457,0.350403', '4301278', '26809007', '30162520', '25777330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3194312', '情非得已之生存之道', '喜剧', '本片是一部mocumentary（伪纪录片），受访嘉宾包括台湾立委邱毅，知名艺人蔡康永、小S、Ella等。因主演台湾新电影《小毕的故事》、《风柜来的人》等被观众认识，执导偶像剧《求婚事务所》、《吐司男之吻》等被观众熟悉的豆子（钮承泽）就“是否幸福”街头随访台湾民众，众人皆摇头，随后他与“哈拉之友”陈希圣（杨德昌《一一》等电影的制片人）、冯家瑞（台湾偶像剧之父）等聊起台湾包括传媒在内的种种混乱现状，认为皆是政治的怪力乱神所致，越讨论越兴奋，拍一部mocumentary的念头蹦了出来。拍片计划如下：摄影机记录下以施明德作后台的演员拔下立委邱毅的假发、男主角在总统府前自焚、开车直撞总统府等的过程，让观众误以为这些事没经过设计，看会引发怎样的反应。在台湾惹怒民众的陈水扁有被人称作“鸭肉扁”，因为他的名字发音与台北一家位于武昌街与中华路转角处的“鸭肉扁”店名相通，民众如此称呼有可随吃随骂的意思，片名因之定为《情非得已之武昌街起义》，很烂俗又很革命。紧接，陈希圣答应做了制片人，由豆子公司的职员组成的新剧组正式成立，而拿到国片辅导金的批文（钮承泽的确以该计划在2005年拿到过350万的国片辅导金）之后，便是豆子和陈希圣四处找投资、演员等事宜。不料开拍即噩梦：男主角屈中恒一听拍摄计划并且需要自己融资，当即逃之夭夭；公司户头空空……豆子为了找到投资好让影片如期拍摄，做了诸多令他回想起便懊悔不已的事，过程中台湾电影业不景气导致的电影人的尴尬求生一览无遗。而与某女演员“车震”一事被媒体广播后，他与宁宁（张钧宁）本身存有问题的夫妻关系更是几乎崩溃，加上无法释怀多年前发生的一件与母亲有关的往事，他的人生', '钮承泽', '钮承泽', 7.9, 19177, 'tt1239313', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2198901866.jpg', 0.5, 2.4, 22.7, 51.8, 22.5, '0.175012,-0.126653,-0.604652,0.392841,0.394267,-0.131812,0.408539,0.277135,-0.391062,-0.205162,-0.076134,0.634506,-0.464137,0.064998,0.278322,-0.335254,-0.347532,-0.557980,-0.165490,-0.075453,0.034069,-0.220792,0.092118,-0.124785,-0.232031,-0.111339,0.561793,0.167476,-0.225868,0.178374,0.404801,0.169940,-0.146839,0.238546,0.261128,0.141287,0.004902,0.127217,-0.529648,0.100448,0.183673,-0.369849,-0.009055,0.026376,0.016221,0.345789,0.473926,-0.043347,-0.207551,-0.080306,0.418812,-0.230060,-0.088268,-0.019368,0.178060,0.260200,0.350933,0.154303,-0.274727,0.016941,-0.076764,0.012700,-0.646764,-0.028795,0.181868,0.155563,-0.350450,0.143797,-0.109808,0.172281,0.068483,-0.311306,0.221462,0.269456,0.472155,0.307533,0.087999,0.130184,-0.264485,0.499163,0.509927,0.048225,-0.032133,0.378110,0.108836,-0.478257,0.018466,-0.071297,-0.223687,0.203498,0.168314,-0.113212,-0.051184,0.017411,-0.328561,-0.172123,0.007462,-0.525675,0.234183,-0.207770,-0.025584,-0.655499,0.028717,-0.028811,-0.004569,-0.328374,0.340418,-0.078407,0.624209,-0.536920,0.000551,0.249752,0.183472,-0.679062,0.507945,0.020714,0.033161,-0.142068,0.102347,-0.132926,0.000276,0.270179,0.096069,0.114758,-0.015487,-0.504163,-0.354604,0.148132', '4301278', '3318306', '27602116', '25918677');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3195101', '我是爱', '剧情', '意大利米兰的瑞奇家族靠纺织业致富，在家长的寿宴上，爷爷将企业传给了儿子坦科雷德（加布里埃尔.费泽蒂 Gabriele Ferzetti 饰）和孙子爱德瓦多（弗拉维奥·帕伦蒂 Flavio Parenti 饰）。坦科雷德的俄国妻子艾玛（蒂尔达·斯维顿 Tilda Swinton 饰）酷爱烹饪。在结识了儿子爱德瓦多的厨师朋友安东尼奥（爱德瓦多·加布瑞尔利尼 Edoardo Gabbriellini 饰）之后，艾玛被安东尼奥高超的烹饪手艺所吸引，情不自禁坠入爱河。不仅如此，艾玛还必须隐瞒她偶然发现女儿伊丽莎白（阿尔芭·洛尔瓦彻Alba Rohrwacher 饰）是同性恋的事实。与此同时，家族的事业也在变迁，尽管爱德瓦多独力反对出售家族企业，却还是无法抵挡资本全球化大潮的冲击，并购势在必行。在探讨商务的晚宴上，一个意外打破了艾玛苦心枯守的表面平静，她的灵魂就要破茧而出……本片获柏林国际电影节最佳女主角奖及科罗拉多博尔德国际电影节最佳影片奖。', '蒂尔达·斯文顿', '卢卡·瓜达尼诺', 7.7, 8611, 'tt1226236', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p803433643.jpg', 0.6, 3, 27.1, 47.4, 21.9, '0.066436,-0.041584,-0.455954,0.488826,-0.005218,-0.441580,0.368027,0.419663,-0.438609,-0.093437,0.282540,0.730929,-0.101697,-0.148742,0.459705,0.323866,-0.411737,-0.537435,0.250797,-0.055756,0.079136,-0.578910,-0.408630,-0.011760,-0.159885,-0.566130,0.400362,-0.208409,-0.154948,0.299295,0.298089,0.389776,0.075729,0.161916,-0.055106,0.181307,0.470636,-0.151868,-0.479815,0.256640,-0.013825,-0.035924,-0.049106,0.198941,0.293480,0.228828,0.377463,-0.250887,0.416714,-0.045878,0.365903,-0.237515,0.279612,0.248898,0.164459,-0.240262,0.185928,0.270614,-0.187523,-0.238359,0.224908,-0.109709,-0.590760,0.227906,0.136064,0.154822,-0.748804,0.315251,-0.236630,0.015328,-0.212770,-0.252441,-0.004821,0.399473,0.101549,0.216919,0.003542,0.226630,-0.384752,0.134877,0.443446,0.096499,-0.275260,0.251597,-0.331556,-0.338345,-0.059879,-0.333440,-0.456410,-0.250937,0.451364,-0.002982,0.170011,0.527381,-0.361975,-0.235825,-0.469770,-0.321963,0.096686,-0.184699,0.053623,-0.640668,-0.066020,-0.002279,-0.151576,-0.233500,0.167570,-0.238419,0.492080,-0.585614,0.268612,0.635005,0.247479,0.028564,0.565446,-0.034710,0.150278,-0.218623,-0.448549,0.323238,-0.040457,0.090035,-0.092299,0.458356,0.342868,-0.22140