INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3195759', '犹大之吻', '剧情', '失意中年导演扎克（查理·大卫 Charlie David 饰）回母校“钥匙石”担任学生影展的评委，15年前他就因为夺冠而开始做导演梦，结果却被现实摔成了玻璃渣。扎克在评审前夜“不小心”睡了一个少年，而第二天面试名单里赫然就有这个叫丹尼（理查德·哈蒙 Richard Harmon 饰）的男孩！丹尼的处女短片“犹大之吻”是有力的竞选作品，巧合的是扎克当年得奖的电影也叫“犹大之吻”。随着两人的重合程度越来越高，扎克开始相信他是掉入了一个平行宇宙中。学长克里斯（肖恩·保罗·洛克哈特 Sean Paul Lockhart 饰）与校董儿子肖恩（蒂莫·德斯坎普司 Timo Descamps 饰）都迷恋着丹尼，而渴望成功的丹尼毫不介意用感情当敲门砖。扎克终于明白自己的今天源自昨天，他需要改变未来——通过改变丹尼的现在：这意味着他必须扼杀丹尼的导演梦...©豆瓣', '查理·大卫', 'J.T 泰普诺巴', 6.7, 7566, 'tt1242642', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p974450314.jpg', 1.9, 11.2, 47.5, 29.8, 9.5, '0.153273,0.056839,-0.617977,0.404832,-0.165073,-0.544315,0.855748,0.330364,-0.112719,-0.096059,0.144647,0.653582,-0.331967,0.141099,0.482909,0.254917,-0.395975,-0.612730,0.085860,-0.087882,-0.119947,-0.640806,-0.219296,-0.074789,-0.015792,-0.193074,0.623644,-0.209448,-0.150924,0.263635,0.399199,0.177940,0.417062,0.351784,0.366690,0.072870,0.336879,-0.023194,-0.196122,0.169213,0.197749,0.064221,-0.073895,0.078998,-0.056820,0.419553,0.288592,-0.356125,0.128147,-0.108303,0.378088,-0.266114,-0.020381,-0.016449,0.042641,-0.039624,0.149987,-0.019871,0.099315,-0.092593,0.075681,-0.045540,-0.485987,0.159471,-0.034466,0.225092,-0.308397,0.257530,-0.307206,0.184204,0.132016,-0.417151,0.156452,0.141490,0.386037,0.156080,0.003955,-0.132095,-0.232173,0.135395,0.298933,0.131466,-0.450820,0.361259,-0.218929,-0.562466,-0.020959,-0.019018,-0.416223,0.229340,0.483111,-0.016755,-0.002275,0.224500,-0.239858,-0.150820,-0.276677,-0.124562,-0.126508,-0.329020,-0.115941,-0.462724,-0.261807,-0.167550,-0.146523,-0.554044,-0.056388,-0.398479,0.509456,-0.732319,0.203502,0.766353,0.029034,0.027772,0.644983,0.201123,0.008366,-0.279291,0.082749,0.129991,-0.045904,0.128748,0.035427,0.428416,0.343467,-0.101928,-0.322427,0.671032', '1309172', '1301686',