INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3205571', '艾利之书', '剧情', '近未来，地球爆发一场毁灭性的战争。灾难过后，人类文明消失殆尽，整个星球满目疮痍。幸存者逆境求生，为了有限的资源回归原始，暴力血腥肆意蔓延。沉默的黑人艾利（丹泽·华盛顿 Denzel Washington 饰）是一个独来独往的旅者，他横越荒芜的美洲大陆，见识几多炎凉和凶险。这一日，艾利辗转来到一座喧嚣小镇。神秘危险的卡耐基（加里·奥德曼 Gary Oldman 饰）控制着小镇的水源，也因此成为富甲一方、不可一世的大头目。正当此时，世间流传着一本关乎人类未来命运的预言书的传说，而艾利正是这本书的护送人。卡耐基派出手下四处寻找预言书，结果一无所获，命运却指引着他和艾利宿命地相会。人类的命运终将如何……©豆瓣', '丹泽尔·华盛顿', '艾尔伯特·休斯', 6.7, 40708, 'tt1037705', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1612536937.jpg', 1.9, 9.8, 47.7, 30.8, 9.8, '-0.133897,0.214511,-0.786279,0.636677,0.056575,0.123326,0.681944,0.031424,-0.463793,-0.230171,0.294924,0.759095,0.063999,-0.024021,0.340978,0.120230,-0.288446,-0.473138,-0.176585,-0.085129,-0.188828,-0.190049,-0.559919,-0.210198,0.039340,-0.336918,0.604594,0.715837,-0.310777,0.251117,-0.101598,0.309777,-0.425919,0.316534,-0.341897,-0.186928,0.102808,0.064092,-0.422361,0.013976,-0.334407,0.006498,-0.242634,0.192716,-0.426752,0.040706,0.636867,-0.392619,0.077592,-0.300500,0.330240,-0.487849,-0.182026,0.001287,0.375563,-0.060755,-0.137555,0.054357,0.020326,-0.138703,0.000580,0.033408,-0.782531,-0.147559,-0.066653,0.241605,-0.362754,0.545008,0.095775,-0.228310,-0.237653,-0.204804,0.142204,0.395730,0.410739,0.251391,0.065068,-0.036012,-0.362771,0.056707,0.684245,-0.307982,-0.604233,0.106567,-0.223356,-0.560169,-0.146820,-0.415095,-0.720377,-0.166267,0.351291,0.197508,-0.088837,0.754953,-0.788092,0.387428,-0.342676,-0.433003,0.025513,-0.327853,-0.496167,-0.559491,-0.268337,-0.183097,-0.208815,0.106444,0.117585,-0.092062,0.926204,-0.284283,0.364141,0.725607,0.180446,-0.308166,0.524229,-0.043766,0.254765,-0.300021,-0.049839,0.931260,-0.058438,0.620548,-0.102232,0.008098,0.090603,0.098162,-0.282636,0.740189', '26647163', '10746430', '26667010', '3036473');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3205624', '社交网络', '剧情', '2003年秋，哈佛大学。恃才放旷的天才学生马克·扎克伯格（Jesse Eisenberg 饰）被女友甩掉，愤怒之际，马克利用黑客手段入侵了学校的系统，盗取了校内所有漂亮女生的资料，并制作名为“Facemash”的网站供同学们对辣妹评分。他的举动引起了轰动，一度致令哈佛服 务器几近崩溃，马克因此遭到校方的惩罚。正所谓因祸得福，马克的举动引起了温克莱沃斯兄弟的注意，他们邀请马克加入团队，共同建立一个社交网站。与此同时，马克也建立了日后名声大噪的“Facebook”。经过一番努力，Facebook的名气越来越大，马克的财富与日俱增。然而各种麻烦与是非接踵而来，昔日的好友也反目成仇……©豆瓣', '杰西·艾森伯格', '大卫·芬奇', 8.2, 438285, 'tt1285016', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2553756806.jpg', 0.2, 1.2, 18, 50.9, 29.7, '0.392374,-0.066459,-0.425126,0.514716,0.016295,-0.206622,0.199632,0.151240,-0.650908,-0.227286,0.036003,0.528376,-0.527703,0.050565,0.340863,-0.411962,-0.283409,-0.651531,0.138093,-0.289545,0.026222,-0.432393,-0.299767,-0.324817,-0.137268,-0.593866,0.535851,-0.077443,-0.483786,0.461998,0.175946,0.354944,0.133136,0.479606,0.303917,0.018779,0.411420,-0.184238,-0.115630,0.118728,-0.183317,-0.210399,0.060350,0.176017,0.122027,0.303362,0.558128,-0.130049,-0.045760,-0.239053,0.541527,-0.273515,0.116956,0.093750,0.504335,0.053661,0.291997,0.277196,-0.198017,0.114292,0.139930,-0.242196,-0.713251,0.095439,0.250147,-0.113249,-0.298640,0.466832,-0.328831,-0.029128,-0.151390,-0.046271,-0.034836,0.423958,0.506183,0.103037,-0.034666,0.151933,-0.178566,-0.004843,0.400419,-0.054099,-0.021534,-0.036951,-0.236891,-0.439183,-0.122504,-0.251906,-0.350959,-0.093843,0.500335,-0.046910,0.139646,0.506370,-0.750440,-0.071615,-0.379082,-0.367131,0.043931,-0.332592,-0.131783,-1.016640,-0.267887,0.036870,-0.120721,-0.058255,0.065613,-0.209081,1.049024,-0.759206,-0.058421,0.517973,0.219728,-0.553425,0.433595,-0.053171,0.178409,-0.104802,-0.445943,0.019056,0.243286,0.312745,-0.036526,0.139305,0.068379,-0.537302,0.096746,0.384335', '25863940', '3318306', '27602116', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3210534', '嚎叫', '剧情', '本片是美国“垮掉派”诗人艾伦·金斯堡（詹姆斯·弗兰科 James Franco 饰）的传记片，片名《嚎叫》沿用了金斯堡的同名长诗。艾伦·金斯堡，是美国战后“垮掉的一代”文学流派里的代表性诗人。他的代表作《嚎叫》出版后备受争议，其出版社甚至被起诉出售淫秽资料。金斯堡的父亲是个无名诗人，他的母亲后被送往精神病院。金斯堡是个同性恋者，他有过三段同性恋情，前两次都无疾而终，而第三段与彼得·奥莱斯基（艾伦·特维特 Aaron Tveit 饰）的恋爱，使他感到无比幸福，这段经历成为他的长诗《嚎叫》的部分灵感来源，而彼得成为了他的终身伴侣。本片主要以法庭审判长诗《嚎叫》、金斯堡剖白自己、金斯堡在众人面前朗诵长诗这三个场景，来表现传主金斯堡50年代的生平经历以及他的思想，金斯堡的合作者、漫画家埃里克·杜克还会以动画形式来展示诗歌《嚎叫》的内容。©豆瓣', '詹姆斯·弗兰科', '罗伯·爱泼斯坦', 7.4, 7398, 'tt1049402', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p548049650.jpg', 0.9, 5, 34.8, 42.5, 16.9, '0.217957,-0.370834,-0.651366,0.799614,0.368233,-0.303223,0.695503,0.034260,-0.409594,-0.258528,0.121365,0.765759,-0.199392,0.396053,0.277505,-0.093965,-0.060323,-0.743553,-0.130152,-0.156773,-0.006077,-0.377184,-0.095033,-0.256985,-0.348358,-0.307934,0.525886,-0.255899,-0.624888,0.283595,0.377045,0.515928,0.256301,0.265528,-0.053237,0.326133,0.362311,-0.192233,-0.157088,0.073311,0.240502,-0.111967,-0.031475,0.251475,-0.421818,0.166407,0.553447,-0.310726,0.257595,-0.090341,0.761142,-0.046646,-0.032660,0.211611,0.231080,0.040498,0.294758,0.530334,-0.026638,-0.059446,-0.040372,0.014098,-0.842388,-0.262861,0.071483,0.315063,-0.566599,0.437199,-0.227852,0.173294,0.050481,-0.239432,0.250386,-0.034180,0.305704,0.359080,0.102970,-0.038975,-0.379109,0.452664,0.358501,-0.061506,-0.548003,0.220784,-0.365767,-0.409647,-0.096651,-0.317292,-0.294138,0.069670,0.250533,-0.322736,-0.016913,0.137364,-0.646525,-0.251400,-0.280547,-0.337807,-0.274423,-0.212057,-0.185750,-0.641713,-0.183744,-0.366403,-0.103593,-0.355634,0.108972,-0.310303,0.834838,-0.464596,-0.003313,0.562051,-0.151740,-0.204362,0.548148,0.249751,-0.003407,-0.051370,0.018254,0.547158,0.087811,0.096261,0.016784,0.122163,0.303767,-0.062140,-0.330877,0.701357', '27602116', '22265121',