INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3212120', '九降风', '剧情', '台湾竹东某高中迎来1996~1997学年，该校不同年级的7名男生——即将毕业的郑希彦（凤小岳）、汤启进（张捷）、林敬超（林祺泰），刚入校门的谢志昇（邱翊程）、黄正翰（李岳承），不上不下的李曜行（王柏杰）、林博助（沈威年）——也因共同热爱棒球，迎来他们的友谊。除到职棒联赛现场高声支持所爱球员，他们还常在一起做只有青春少年人才爱做、会做的事，因之没少受教官责罚。中心人物郑希彦最大本领是泡马子，他虽有同班同学黄芸晴（初家晴）作女友，却仍在与兄弟们游玩时搭讪偶遇的女孩。与他走得最近的是汤启进与林敬超，前者与他共用一个呼机，后者常做帮他整理房间之类事情。谢志昇与黄正翰看来更像乖仔，他们常被班长沈培馨（纪培慧）相劝与“坏人”保持距离。李曜行与林博助则是，一个对前途满不在乎把兄弟情看作首位，一个总是担心会被退学。7人如上述般共度过诸多专属他们的简单却多彩的青春日子。某晚，郑希彦从摩托车上摔下，不久昏迷不醒，在他静静躺在医院的时日，他的众兄弟开始接受友谊的考验及成长的洗礼。', '凤小岳', '林书宇', 7.4, 67926, 'tt1286562', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2554113451.jpg', 0.5, 3.5, 36.7, 44.8, 14.5, '0.258823,-0.205651,-0.376479,0.336823,-0.116117,-0.125989,0.567504,0.196060,-0.453611,-0.279083,0.151245,0.665313,-0.323105,0.411394,0.186358,-0.329311,-0.154564,-0.802454,-0.030781,-0.065455,-0.089721,-0.280488,0.121364,-0.017183,-0.243816,-0.244956,0.572293,-0.168784,-0.070736,0.551816,0.235945,0.267772,-0.049798,0.367609,-0.281761,-0.176272,-0.101679,0.273192,-0.390032,-0.037551,0.019345,-0.369245,-0.212137,-0.170911,0.238177,0.197854,0.524053,-0.010795,-0.276465,-0.203622,0.197428,-0.283564,-0.045764,0.095470,0.330064,-0.033263,0.330405,0.338668,0.121199,0.111866,0.002659,-0.191989,-0.416821,-0.018457,0.213074,0.040745,-0.511505,0.723020,0.025434,-0.016315,0.202226,-0.108466,0.097801,0.314165,0.035681,0.382989,-0.152344,0.013102,-0.344811,0.211365,0.815857,-0.016775,-0.071983,0.248197,-0.154383,-0.356635,0.171440,-0.233669,-0.382948,0.005218,-0.020904,-0.086145,0.081012,0.095252,-0.272703,0.180560,-0.011061,-0.086271,0.077611,-0.596642,-0.034040,-0.430648,0.104570,-0.520937,-0.370702,0.229993,0.029104,-0.415284,0.888967,-0.844591,0.014259,0.365900,0.481972,-0.541097,0.836224,0.259131,0.326129,-0.247941,-0.062022,0.093726,-0.185495,0.141091,0.020298,0.295448,-0.137907,0.008815,-0.381805,0.274671', '35048413', '3445516', '35030151', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3212133', '崭新的生活', '剧情', '1975年，年仅9岁的李珍熙（金赛纶 饰）被爸爸（薛景求 饰）送进了一家天主教女子孤儿院。珍熙不明白爸爸为什么抛弃自己，他不但给自己买了新衣服，还买了大蛋糕，并且答应要带她去旅行，可是她万万没想到，旅行的终点居然是孤儿院。虽然极度排斥孤儿院的生活，但随着时间的推移，倔强的珍熙不得不开始接受新的生活。珍熙认识了淑喜（朴度妍 饰）还有艺新（高雅星 饰）两位好朋友，淑喜为了有人收养自己总是说自己只有11岁，而17岁的艺新为了能经常见到自己暗恋的男生而拒绝被人收养，珍熙则始终希望有一天能够回到爸爸的身边。然而命运的轨迹并不会如他们所构想的那样行进，人生的旅程上只有经历痛苦才能变得坚强，才能不断成长……作为首部韩法合拍片，本片在2009年的第62届戛纳电影节特别单元和第22届东京电影节亚洲之风单元均参加展映，并于当年11月在澳大利亚昆士兰第三届亚太电影奖上获得最佳儿童电影。', '金赛纶', '乌妮·勒孔特', 7.9, 6167, 'tt1287875', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p547686792.jpg', 0.3, 1.4, 24.8, 51, 22.5, '-0.231088,-0.030698,-0.514129,0.419110,-0.103506,-0.368029,0.294295,0.079993,-0.558655,-0.363445,-0.004825,0.790578,-0.048893,0.406306,0.283905,0.110020,-0.263430,-0.457710,-0.007293,-0.283062,-0.141799,-0.171509,-0.007264,-0.006445,0.080034,-0.286758,0.566057,0.134581,0.066887,0.445886,0.579155,0.208666,-0.001589,0.295809,-0.223200,-0.127679,0.003284,0.314640,-0.269620,0.134720,-0.097296,-0.160048,-0.132774,-0.039032,0.144049,0.096462,0.617111,0.039364,-0.145043,-0.187042,0.470923,-0.036991,-0.269379,-0.076917,0.105286,0.114173,0.452952,0.258995,-0.066475,0.191389,-0.000548,-0.492407,-0.549220,0.212670,0.250177,-0.090108,-0.477861,0.381210,0.009360,0.112979,0.055907,-0.298590,0.011169,0.469158,0.281491,0.420191,-0.382213,0.052584,-0.485599,0.304702,0.724674,-0.187546,-0.243821,0.450278,-0.276500,-0.323615,0.118382,-0.462034,-0.439086,0.438575,0.027942,0.215474,-0.313056,0.127324,-0.326725,0.057825,-0.183431,-0.331964,0.400635,-0.402615,-0.005076,-0.337226,0.126529,-0.399974,-0.137316,0.004001,-0.083557,-0.411017,0.822807,-0.766007,0.529536,0.380248,0.494691,-0.612183,0.695894,0.223992,-0.241315,-0.288878,-0.064956,0.515168,-0.216264,0.146119,-0.223723,0.089817,-0.038568,-0.235497,-0.293736,0.389321', '1292720', '6963575', '3445516', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3212221', '凯尔经的秘密', '动画', '在遥远的爱尔兰，聪颖纯真的少年修士布兰登（伊万·麦克奎尔 Evan McGuire 配音）生活在一座高墙围筑的修道院内。为了抵抗维京人的入侵，院墙不断加高，卡拉院长（布莱丹·格里森 Brendan Gleeson 配音）更严格禁止布兰登他们踏入外部世界。某天，一名留着长发、幽默风趣的修士来到修道院，他便是闻名遐迩的艾奥娜绘经师伊丹（米奇·拉里 Mick Lally 配音）。此前伊丹持续创作那部重要的宗教典籍《凯尔经》，然而异族的侵略使他不得不中断这项神圣的工作。为《凯尔经》所吸引的布兰登，决心帮助伊丹完成经典的绘制，为此他不惜挑战禁令走出修道院。外面的世界充满新奇和危险……本片荣获2009年昂西国际动画电影节观众奖最佳影片奖、2009年萨格勒布国际动画电影节特别提及。©豆瓣', '伊万·麦克奎尔', '汤姆·摩尔', 8.5, 60596, 'tt0485601', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1088520038.jpg', 0.2, 1.1, 14.3, 43.9, 40.5, '-0.054038,0.018906,-0.537870,0.718454,0.131443,-0.016636,0.578195,0.062839,-0.428420,-0.274496,0.350196,0.598950,-0.123206,-0.048474,0.557839,-0.056189,-0.387064,-0.403753,0.051243,-0.253867,0.008163,-0.352255,-0.358866,-0.404315,-0.322343,-0.770070,0.798309,0.301271,-0.325204,0.156668,0.033399,0.142243,-0.039506,0.034980,0.017000,-0.114962,0.493340,-0.137244,-0.186423,0.162825,-0.214251,0.153054,-0.326829,0.033265,-0.002798,0.215877,0.429591,-0.369660,0.023755,0.060876,0.580650,-0.262646,-0.062159,0.086827,0.223201,0.027541,0.072271,0.331761,0.046466,0.153803,-0.153270,-0.485433,-0.564288,-0.070662,0.097071,0.077338,-0.167833,0.495124,-0.168314,0.132946,-0.150241,-0.229957,-0.180318,0.042352,0.286752,0.307858,0.090198,0.224719,-0.133714,0.305761,0.409453,-0.149042,-0.406105,0.125146,-0.377606,-0.545277,-0.061711,-0.365147,-0.423366,0.012917,0.277118,-0.176780,0.221293,0.254390,-0.500892,-0.051543,-0.225672,-0.336179,0.146546,-0.045457,-0.173461,-0.985457,0.042416,-0.075856,0.085768,-0.174285,0.072042,-0.208258,0.827305,-0.704440,0.393129,0.589263,0.282618,-0.080387,0.645919,-0.141071,0.227840,-0.120460,-0.469306,0.671086,-0.158602,0.443330,-0.228577,0.302504,0.060317,-0.293827,-0.212622,0.455151', '1322847', '2369613', '26611806', '20283482');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3212289', '床的另一边', '喜剧', '阿丽亚娜（苏菲·玛索 Sophie Marceau 饰）和丈夫雨果（丹尼·伯恩 Dany Boon 饰）已经结婚十年，当初的热情虽犹在，却不得不被繁琐的日常事务所冲散。雨果每天为公司的事情在外奔波，阿丽亚娜则一边要当家庭主妇拉扯两个孩子，一边要照看与朋友合伙经营的珠宝生意，整日忙得焦头烂额。夫妻之间的抱怨和摩擦也日渐加剧，眼看自相水火，阿丽亚娜决定挽救这段婚姻，她想出一个看似荒唐的办法——两人互换身份，体验彼此生活一年。这样，阿丽亚娜变身公司高管，丈夫雨果则开始围着孩子和珠宝团团转，经过一段糗事出尽的艰难适应期，两人渐渐开始理解了对方位置的苦处，然而就在彼此感情渐渐被层出不穷的笑料修复之时，警察竟然找上了门……本片改编自法国当代作家阿历克斯·吉霍德的同名小说。©豆瓣', '苏菲·玛索', '帕斯卡莱·普扎杜', 6.8, 7565, 'tt1275590', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p498271519.jpg', 0.8, 7.5, 49.6, 33.5, 8.7, '0.277435,-0.252460,-0.487057,0.312944,0.167267,-0.537048,0.538228,0.242793,-0.543186,-0.405168,0.020720,0.453596,-0.459598,0.336743,0.404914,-0.038665,-0.445854,-0.772121,0.052964,-0.064224,-0.060833,-0.428750,-0.060969,-0.205821,-0.385440,-0.067843,0.444697,-0.106664,0.142525,0.353365,0.264651,0.069984,-0.200826,0.280920,0.024979,-0.055562,0.095084,-0.000521,-0.463567,-0.224002,0.108219,-0.230807,-0.108640,0.072392,0.149123,0.348754,0.487118,0.156649,-0.005078,-0.164672,0.330720,0.013398,-0.009696,-0.054109,0.348594,0.102286,0.488417,0.142255,-0.290229,-0.190063,-0.028849,-0.144402,-0.701473,0.308058,0.140312,-0.076381,-0.668739,0.313213,-0.063283,-0.006161,0.048577,-0.379674,0.052293,0.539271,0.258199,0.561451,-0.272170,0.145004,-0.397908,0.214648,0.546926,0.064295,0.002319,0.496454,0.032644,-0.009622,-0.314041,-0.176175,-0.471745,-0.317808,0.102927,0.020385,-0.063349,0.546256,-0.495329,0.169274,-0.171880,-0.212015,0.231981,-0.448971,0.127687,-0.624723,-0.103089,-0.368842,-0.250430,0.182901,0.240440,-0.167664,0.468075,-0.440724,-0.093060,0.358585,0.197654,-0.593409,0.441868,0.117200,0.464811,-0.351154,-0.057487,0.026179,-0.052576,0.114904,0.320194,0.239531,0.118468,0.225668,-0.306375,0.228393', '4301278', '26678784', '1418613', '25777330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3212306', '枕边的男人', '剧情', '雷奥（克里斯多弗·兰伯特 Christopher Lambert 饰）曾经是一名出尽风头的拳击手，退役后来到加勒比海边的小城卡塔赫纳定居。然而告别了辉煌的职业生涯，他突然对生活茫然无措，只终日混迹酒吧颓废度日。直到有一天，他迫于生计应聘了一个护工工作，负责照看一个因车祸导致全身瘫痪的女人莫伊尔（苏菲·玛索 Sophie Marceau 饰）。曾经干练好胜的女强人莫伊尔，自从车祸无情地夺走她的行动能力后，似乎也夺走了她全部的生机，虽家赀巨万，她却再也无法感受到昨日春光，温柔海浪。仿佛被生活掏空的莫伊尔只能天天躺着消磨余下岁月，并对雷奥的照顾吹毛求疵。然而，两个灵魂在摩擦的同时似乎也在磨合，渐渐地，雷奥不仅没被莫伊尔的挑剔吓跑，反而重新找回了生活的魅力，而一天清晨，莫伊尔竟也从雷奥的鼾声中又一次触碰到了生命的意义……©豆瓣', '苏菲·玛索', '阿兰·莫纳', 7.5, 7832, 'tt1282155', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2558717947.jpg', 0.3, 2.2, 33.1, 49.1, 15.3, '0.069162,0.212114,-0.883994,0.446090,-0.418046,-0.829953,0.898282,0.402085,-0.228668,-0.201187,0.177999,0.420849,-0.058151,0.585798,0.307122,-0.091896,-0.160098,-0.826890,0.059418,0.053159,-0.274176,-0.314002,-0.172965,-0.218871,-0.105552,-0.448602,0.663112,0.184321,-0.240792,0.335836,0.025256,0.254108,0.210341,0.979905,-0.234029,-0.146354,0.322149,0.142645,0.090499,0.042415,0.117397,-0.619548,-0.080437,0.180930,0.085320,0.501564,0.783581,-0.367460,0.055578,0.101441,0.568888,-0.287760,0.154089,-0.055573,0.235927,0.004321,-0.092767,0.039891,-0.349366,0.135058,0.071550,-0.105555,-0.478901,-0.165657,-0.027685,0.014519,-0.538423,0.566482,0.135018,-0.157447,-0.162218,-0.266554,0.278452,0.077464,0.210398,0.294629,-0.365866,0.497888,-0.398422,0.114764,0.622308,-0.036594,-0.277386,0.546005,-0.193056,-0.648835,-0.261183,-0.217343,-0.426846,-0.129501,0.299142,-0.042554,-0.164531,0.325992,-0.531561,-0.125556,-0.316105,-0.421012,-0.042530,-0.206577,-0.095899,-0.444042,-0.179074,-0.433656,-0.438684,0.260108,0.149482,-0.093919,0.371780,-0.466718,0.342141,0.779436,-0.211791,-0.318769,0.397549,0.052245,0.092343,0.125064,0.192948,0.739136,0.198693,0.436960,0.557751,0.284489,-0.125282,0.457436,-0.220228,0.867977', '21348112', '1300945', '1291559', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3212318', '噪反城市', '喜剧', '本片源自于瑞典导演奥拉西蒙森、乔安史特贾恩·尼尔森的成名短片《One Apartment and Six Drummers》。出生于著名音乐世家的警官阿玛迪斯仇恨音乐，童年记忆是一长串代表荣耀的祖先名单，但他痛恨音乐，那对他是一种折磨。当一群倡导无政府主义的鼓手发动音乐快闪攻击，把整座城市当作乐器敲打，先是潜入开刀房，用仪器与人体当作打击乐器，接著在银行绞碎钞票来创作曼妙声响，公然挑战当局，阿玛迪斯的生活顿时陷入混乱。为了追捕这群音乐恐怖份子，他必须踏进花了大半辈子想要逃离的音乐世界。鼓手们准备以歌剧院做为终极目标，让城市聆听一场前所未有的音乐会，而阿玛迪斯的哥哥正是该晚的指挥。此时，阿玛迪斯却发现自己爱上了这群闹事者的首领……©豆瓣', 'Bengt Nilsson', '乌拉·西蒙森', 7.8, 6270, 'tt1278449', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p661894434.jpg', 1.5, 4.4, 24.3, 40.4, 29.4, '0.009338,0.133098,-0.438799,0.619274,-0.050124,-0.080869,0.694929,0.145117,-0.342242,-0.352238,0.138303,0.608936,0.034723,0.000646,0.159579,-0.053268,-0.127654,-0.794457,-0.104917,0.064414,0.129183,-0.218921,0.145457,-0.410415,0.026159,-0.404173,0.635690,0.086690,-0.568055,0.265400,0.342771,0.286318,0.081080,0.172711,-0.093700,-0.222320,0.194840,-0.180858,-0.399267,0.143478,-0.291336,-0.282906,-0.223200,0.047686,-0.353652,-0.152814,0.659193,-0.341707,0.188691,-0.119265,0.417286,-0.350613,-0.189231,-0.157452,0.103953,0.248167,0.206804,0.120425,-0.156589,0.145597,-0.097354,-0.228784,-0.850221,-0.029811,0.001050,-0.003501,-0.423048,0.123185,-0.049785,0.052015,0.125895,-0.028554,0.360606,-0.168719,0.271181,0.613329,-0.152985,0.115673,-0.251458,0.137188,0.616749,-0.281428,-0.297605,0.260506,-0.295816,-0.318418,-0.064212,-0.214201,-0.346281,-0.202676,0.183126,-0.138606,0.026763,0.198825,-0.661916,-0.149434,-0.081139,-0.559537,0.133439,-0.535581,-0.211893,-0.748072,-0.224026,0.072573,0.078995,-0.068911,0.116397,-0.018537,0.883562,-0.733206,0.222691,0.505311,-0.181288,-0.373757,0.466611,0.129654,-0.163865,0.033925,-0.246745,0.267726,0.247570,0.358851,-0.183801,0.120445,0.092931,-0.104177,-0.544697,0.416909', '25928048', '27602116', '3811356', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3212352', '狗舍', '喜剧', '为了帮助好友文斯（斯蒂芬·格拉汉姆 Stephen Graham 饰）度过伤心的离婚，一群好友尼尔（丹尼·戴尔 Danny Dyer 饰）、科勒雷（比利·穆瑞 Billy Murray 饰）、米奇（洛尔·克拉克 Noel Clarke 饰）、马特（李·恩格里比 Lee Ingleby 饰）等人带着他前往一偏僻小镇度假。本以为去的是人间天堂，结果他们却发现这里根本就是地狱，因为这里的女人都染上了怪病，会像僵尸一样袭击、吃掉所有男人。尽管这些男人平时都是唯唯诺诺的“妻管严”，但是面对女僵尸他们绝不手软，于是一场好好的度假彻底沦为了爷们儿大战女僵尸的战争。©豆瓣', '丹尼·戴尔', '杰克·维斯特', 6.5, 8163, 'tt1023500', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2518985380.jpg', 4, 12.7, 46.7, 27.7, 8.9, '0.122171,-0.337089,-0.645621,0.002276,-0.322432,-0.318877,0.737659,0.062000,-0.408470,-0.196899,0.223070,0.616427,-0.098135,0.090073,0.241377,-0.023758,-0.471086,-0.289698,-0.113673,-0.254944,-0.225374,-0.148393,-0.279828,-0.235373,0.111029,-0.280997,0.166023,-0.098556,-0.038947,0.379104,0.382066,0.430424,-0.017058,0.422520,0.045771,-0.105587,0.070679,-0.154973,-0.130814,0.057399,-0.260819,0.297222,-0.163824,-0.047592,0.203785,0.271322,0.386427,-0.468035,0.022879,-0.433210,-0.058297,-0.231159,-0.034616,0.157946,0.196193,-0.532294,0.481032,-0.030688,0.144168,-0.156453,0.359561,-0.103509,-0.359437,0.317252,0.017743,0.291828,-0.342776,0.128301,0.031046,0.109695,0.011692,-0.236056,0.348217,0.131736,0.503326,0.266233,0.125567,-0.059369,-0.745952,0.070016,0.655782,0.146167,-0.219466,0.074220,-0.208248,-0.242591,0.094762,-0.296047,-0.504478,0.016827,0.190338,-0.246756,-0.227950,0.314311,-0.491204,-0.134827,-0.219263,0.096175,-0.177278,-0.301153,-0.113445,-0.637514,0.165782,-0.268821,-0.163887,0.063893,0.050423,-0.053873,0.473976,-0.647662,0.298680,0.452199,0.432564,-0.440201,0.518918,-0.021656,0.113340,0.055667,0.031305,0.349165,0.263113,0.149898,0.158165,0.313782,0.170812,-0.163166,-0.025474,0.615428', '1308755', '1301686', '3055049', '1296538');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3212397', '根西岛文学与土豆皮馅饼俱乐部', '剧情', '本片根据安妮·巴罗斯、玛丽·安·谢弗同名小说改编。故事构建于二战后，讲述作家朱丽叶·艾什顿(莉莉·詹姆斯饰)与“根西岛文学与土豆皮馅饼俱乐部”之间互相了解并熟知的故事。', '莉莉·詹姆斯', '迈克·内威尔', 7.4, 9201, 'tt1289403', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2530405011.jpg', 0.6, 4.1, 37.5, 42.4, 15.4, '0.473955,-0.462528,0.312710,0.608310,1.141280,-0.437083,0.579278,0.130844,-0.106258,-0.462438,-0.320617,0.923881,-0.911355,-0.176624,0.493365,-0.017067,-0.960303,-0.688852,0.147122,-0.012277,0.169258,-1.193320,-0.096329,-0.060078,-0.027022,-0.220984,0.538598,-0.380661,-0.677403,0.519702,-0.015949,0.347405,-0.580327,-0.153614,0.475254,0.615441,0.274096,0.074061,-0.852978,-0.173240,-0.018866,0.239574,0.098554,-0.214217,0.046362,-0.127514,0.438414,-0.453636,0.019124,-0.148795,0.495053,0.563531,0.100320,-0.526113,0.082762,0.333226,0.601454,0.386029,0.396005,0.421828,-0.103494,-0.530017,-0.313597,-0.176176,0.417966,0.363779,-0.174144,0.234556,-0.037474,0.001999,0.120980,-0.223704,0.016688,0.234522,1.165000,0.459032,0.389784,0.032940,0.206348,0.327485,-0.184874,0.404463,-0.417129,0.335010,-0.207775,-0.267099,-0.088771,0.597277,-0.191906,0.269597,0.235704,0.058383,0.172858,0.780266,-0.710582,-0.187597,-0.037091,-0.026419,0.502617,-0.519022,0.064709,-0.928999,-0.541939,-0.325142,-0.102435,-0.600218,0.284666,-0.250669,0.726764,-0.606884,0.407135,0.307023,-0.157237,0.148703,0.192403,0.095766,0.202625,-0.375184,0.226648,0.635961,0.090584,-0.249714,-0.242075,0.339073,0.188725,-0.331273,-0.611621,0.175155', '25821461', '26823502', '27040853', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3212398', '超能敢死队', '喜剧', '哥伦比亚大学教授Erin Gilbert（克里斯汀·韦格 Kristen Wiig 饰）和Abby Yates（梅丽莎·麦卡西 Melissa McCarthy 饰）是合作愉快的作家。如今，为了告诉人们“幽灵是存在的”，她们将一起编著一本关于幽灵的书籍。当对“鬼魂”的深 入研究中，当“鬼魂”入侵她们所居住的城市时，她们和另外两个搭档Jillian Holtzmann（凯特·麦克金农 Kate McKinnon 饰）、Patty Tolan（莱斯莉·琼斯 Leslie Jones 饰）一起投入到拯救城市、拯救世界的行动中……', '克里斯汀·韦格', '保罗·费格', 6, 30365, 'tt1289401', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2358684311.jpg', 4.2, 20.6, 52.8, 17.4, 5, '0.598771,-0.219427,-0.369205,0.498695,-0.074568,-0.172210,0.728114,-0.165049,-0.487888,-0.398915,-0.029975,0.578740,-0.033963,0.200394,0.275487,0.091171,-0.722837,-0.886977,0.028626,-0.508335,-0.497726,-0.666971,-0.373407,-0.258632,-0.213382,-0.480135,0.446517,0.109499,-0.048877,0.541116,-0.012181,0.518151,-0.597466,0.144892,0.349693,-0.232912,0.353481,-0.139319,-0.392891,0.427402,-0.227334,0.342193,-0.115618,0.064721,0.205874,0.017062,0.641025,-0.626298,0.417973,-0.348267,0.047724,-0.057439,0.008589,-0.126000,0.172466,-0.183221,0.276319,0.230323,-0.124170,0.087515,0.019466,-0.367048,-0.683974,-0.087884,0.234895,0.364786,-0.442155,0.039247,0.014353,0.064548,0.222736,-0.168403,0.321064,0.100776,0.454619,0.433273,0.111169,0.057177,-0.448579,0.146076,0.336990,0.046905,0.074635,-0.146695,-0.441590,-0.279830,-0.080377,0.021845,-0.430844,0.078948,0.100697,0.097545,0.076078,0.356823,-0.687814,-0.158721,-0.338690,-0.055810,0.176142,-0.410671,-0.038525,-1.016817,-0.046283,-0.321429,0.045244,-0.036658,0.031217,-0.495362,0.955704,-0.734247,0.343854,0.482591,0.535240,-0.044840,0.927983,-0.202106,0.374220,-0.414716,-0.090428,0.294252,0.269501,0.283269,0.026930,0.092553,0.315455,-0.058740,-0.449888,0.444055', '1293656', '1306860', '3811356', '19965431');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3212965', '诗', '剧情', '时髦的打扮掩饰了岁月在她的身上留下痕迹，66岁的美子（尹静姬 饰）像一朵摇曳在街边的小花一样绽放着自己暮年的美丽。美子靠做钟点工赚些小钱，与读初中的外孙独自生活的日子虽然清贫，但却丝毫没有影响她对于生活的热情。虽然已经确诊患上了老年痴呆症，但她却依然酷爱诗歌，不仅时常参加诗歌朗诵会，而且开始学习写诗。她总是留意观察生活中的点滴，以便捕捉随时可能出现的灵感，然后把它们记录在随身携带的小本上。然而，如同写诗的灵感并不会轻易出现一样，生活也并非表面的那样轻松和容易……在63届戛纳电影节上，李沧东凭借此片获得最佳编剧奖。©豆瓣', '尹静姬', '李沧东', 8.7, 48064, 'tt1287878', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p694844104.jpg', 0.2, 0.7, 9.5, 44.8, 44.8, '0.294318,0.079737,-0.640002,0.578165,-0.339835,-0.005913,0.614281,0.134852,-0.388035,-0.284083,0.162545,0.808709,-0.050541,0.176682,-0.161147,-0.248425,-0.308753,-0.735116,0.203642,0.055112,-0.056044,-0.185511,-0.380721,0.056552,-0.287421,-0.406844,0.365865,0.088332,-0.189611,0.796977,-0.060581,-0.049829,0.129024,0.448796,-0.307703,-0.335090,-0.377860,0.393438,0.140076,0.080229,0.188305,-0.472610,-0.086359,-0.074355,0.266637,0.429858,0.814605,-0.240827,-0.443597,0.226382,0.586745,-0.091351,0.029833,0.088895,0.078271,0.191254,0.242599,-0.057624,-0.200974,0.199221,0.047828,-0.313393,-0.746069,-0.084727,0.292368,0.572576,-0.551270,0.605682,0.177247,-0.065003,-0.187412,-0.191618,0.191551,0.123732,0.100592,0.281941,-0.364491,0.036040,-0.529363,0.635668,0.436154,-0.019712,-0.634973,0.580877,-0.565524,-0.122650,-0.065085,-0.309522,-0.362913,0.027780,-0.162242,0.100569,-0.449131,0.028000,-0.437946,0.267331,-0.084964,-0.181915,-0.048891,-0.363905,-0.164089,-0.711714,0.036923,-0.613976,-0.557541,-0.044278,0.062203,-0.530994,0.753986,-0.849790,0.503127,0.429731,0.290961,-0.179090,0.707313,0.037139,-0.130830,0.150585,-0.286556,0.524060,-0.118959,0.188351,0.060784,0.396500,-0.058120,-0.130772,-0.225830,0.765595', '35144311', '3811356', '30162520', '3154392');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3213173', '绯闻计划', '喜剧', '为了这部影片，艾玛·斯通推掉了《守望者》导演扎克·施奈德的《美少女特工队》。平凡的高中女生奥利芙（艾玛·斯通 Emma Stone 饰）生活在一个普通家庭，却也幸福美满。可在学校一直籍籍无名，甚至频繁被当成受气包。一次派对，她为了帮助死党布兰登摆脱同志嫌疑，自编自 导了 一处“破处戏”，从而一举成名成为学校的风云人物，再也没有人来欺负她。而众多平凡的男生慕名而来，希望奥利弗可以帮助他们成为学校的风云人物。从此，乖乖女摇身一变，成了一个处事随便的辣妹，而奥利芙在同学之间名声却彻底臭了。在拜读了霍桑的小说《红字》后，奥利芙觉得故事中女主人公的经历和自己简直太过相似，于是，她招摇地在胸口贴上了一个鲜红的“A”，小女生的高中生活彻底改变……©豆瓣', '艾玛·斯通', '威尔·古勒', 6.7, 51964, 'tt1282140', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p973944180.jpg', 1.1, 9, 53.1, 29.6, 7.2, '0.422997,-0.105619,-0.330232,0.658929,-0.104034,-0.371495,0.601608,0.271298,-0.408157,0.073704,0.179454,0.851804,-0.323607,0.152693,0.341770,0.064815,-0.245037,-0.691709,0.188083,-0.232568,-0.033871,-0.269217,-0.171013,-0.149871,-0.127961,-0.445931,0.649866,-0.202777,-0.021331,0.470403,0.463369,0.075189,-0.048575,0.202736,-0.098531,0.119999,0.087305,-0.008051,-0.163555,0.249484,-0.100921,0.112701,-0.268182,-0.049289,0.003803,0.088965,0.631576,-0.033968,-0.078921,-0.042284,0.412030,-0.194056,-0.207907,-0.024408,0.137534,-0.276614,0.621720,-0.012553,-0.016254,0.127749,0.218725,-0.216685,-0.525157,0.176613,0.238229,0.151209,-0.421199,0.571549,-0.069928,-0.098307,-0.035840,-0.143518,-0.083444,0.057317,0.206272,0.271326,-0.210951,0.367194,-0.308757,0.445409,0.506977,0.140497,-0.601625,0.428398,-0.084305,-0.061730,-0.120402,-0.312413,-0.639063,0.171722,0.262068,-0.269767,-0.487517,0.196897,-0.612058,-0.130294,-0.289619,-0.080595,0.150536,-0.349384,-0.108510,-0.477367,-0.345975,-0.040000,-0.206274,-0.379383,-0.114140,-0.287415,0.763161,-0.876763,0.085798,0.450059,-0.003181,-0.322254,0.645823,0.347875,0.182251,0.033086,-0.322379,0.307240,0.141773,0.479246,0.087761,0.390501,-0.077560,-0.241307,-0.118215,0.588967', '1292219', '1292720', '1870681', '4817024');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3213233', '坏老师', '喜剧', '伊丽莎白（卡梅隆·迪亚茨 Cameron Diaz 饰）在生活中是个不折不扣的贱人，但同时她还有着另一个身份——人民教师。在被前男友抛弃之后，她不得不重新回到了自己所厌恶的工作岗位上消极怠工。她一直对自己的胸部尺寸不太满意，这一次，她终于下定决心做隆乳手术，但在此之前，她得先凑齐昂贵的手术费用。新人教师斯科特（贾斯汀·汀布莱克 Justin Timberlake 饰）出现在了伊丽莎白的视线里，他的年轻帅气很快就吸引了她的目光，但糟糕的是，她那表面友善内心阴险的同事艾米（露茜·彭奇 Lucy Punch 饰）也向他送去了秋波。斯科特和艾米在一起了，这令伊丽莎白十分沮丧，不过一直在追求伊丽莎白的体育老师罗塞尔（杰森·席格尔 Jason Segel 饰）对此似乎十分高兴。被横刀夺爱的伊丽莎白将全部精力放在了赚钱上，她得知若班级的考试成绩在州里名列前茅的话，作为班主任的她将获得5700美元的奖金。这一消息振奋了消沉的伊丽莎白，但同时，班上这些不争气的孩子们让她在试卷的答案上动起了歪脑筋。', '卡梅隆·迪亚兹', '杰克·卡斯丹', 5.8, 24954, 'tt1284575', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2210502930.jpg', 4.4, 22.8, 54.5, 14.3, 4, '0.376926,0.184466,-0.832451,0.551676,-0.475615,-0.450606,0.727662,0.021736,-0.523184,-0.011292,0.208392,0.743859,-0.089233,0.448985,0.076595,0.398860,-0.452614,-0.629066,-0.044661,-0.365152,-0.331775,-0.579436,-0.127622,-0.279971,-0.200778,-0.294213,0.300754,-0.142242,-0.033824,0.360149,0.430342,0.131826,0.510983,0.556413,-0.185966,0.108029,0.065710,-0.224834,0.230667,0.217430,0.351786,-0.333191,-0.333518,0.536002,0.237002,0.547523,0.686142,-0.041418,-0.179444,0.217119,0.438384,-0.359990,0.021278,0.323045,0.096153,0.150702,0.076609,-0.088658,-0.314990,0.009250,0.264872,0.002451,-0.658503,-0.055529,-0.032969,0.232391,-0.719739,0.713990,-0.273513,0.148744,0.043825,-0.341632,0.084045,0.110923,0.069940,0.195864,-0.306269,0.134566,-0.347345,0.217336,0.466715,0.343966,-0.213677,0.300298,-0.478424,-0.536142,-0.066379,-0.119478,-0.523375,-0.061995,0.578031,0.124022,0.045501,0.175155,-0.464237,-0.150452,-0.113065,-0.221344,-0.167168,-0.445927,-0.070563,-0.352981,-0.153479,-0.546164,-0.589661,-0.127902,0.035188,-0.303656,0.880151,-0.826034,0.033833,0.630986,0.233199,-0.389650,0.609449,0.061874,0.183187,0.009751,-0.140037,-0.043250,0.005252,0.376185,0.335725,0.648318,0.014262,-0.310000,-0.485124,0.705470', '1298880', '1783772', '5262027', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3213250', '坏女孩2', '喜剧', '米歇尔（梅甘·洁特·马丁 Meaghan Jette Martin 饰）出生在一个并不富裕的家庭之中，因为父亲工作的缘故，米歇尔幼时常常搬家，因此身边并没有非常交心的朋友，个性敏感而又内向的她常常会因为自己的经历和出身感到自卑。这一次，米歇尔转入了北岸高中就读，在那里认识了校园女王曼蒂（玛雅拉·沃什 Maiara Walsh 饰）和经常受到曼蒂霸凌的女孩艾比（詹妮弗·斯通 Jennifer Stone 饰）。受艾比父亲所托，米歇尔决定和艾比成为朋友，两人的出双入对很快就激怒了曼蒂，米歇尔的这一举动无异于当众忤逆曼蒂。于是，曼蒂将米歇尔也划入了敌人名单之中，开始对她进行猛烈的“攻击”。©豆瓣', '玛依亚拉·沃尔什', '梅勒妮·梅隆', 5.8, 15227, 'tt1679235', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p817824933.jpg', 6, 23.3, 52, 13.8, 4.8, '0.624113,-0.083679,-0.819600,0.644795,-0.183886,-0.234357,0.906007,0.128937,-0.670161,-0.370225,0.026489,1.004734,-0.251916,0.342077,0.383682,0.081492,-0.249757,-0.582300,0.012507,-0.122956,-0.216311,-0.524946,-0.137929,-0.283250,-0.231080,-0.295190,0.431889,-0.304426,-0.292018,0.675324,0.326873,0.424459,0.246098,0.591346,0.026255,0.104931,-0.010446,0.038445,-0.180005,0.133477,0.101888,-0.144164,0.051554,0.422068,0.231447,0.443845,0.551905,-0.268344,-0.148039,-0.293905,0.239698,-0.235454,0.134859,0.203006,0.412642,-0.037321,0.336193,0.182703,-0.125360,0.181494,0.031366,-0.164043,-0.529944,0.110068,0.153735,0.082991,-0.472318,0.382378,-0.125903,-0.165266,-0.046784,-0.283428,-0.029953,0.380231,0.186614,0.274294,-0.263664,-0.080497,-0.164884,-0.137049,0.715045,-0.077627,-0.241394,0.368606,-0.364109,-0.341199,0.065854,-0.110247,-0.538906,-0.004321,0.190521,0.218866,-0.188566,0.351478,-0.382078,-0.132857,-0.234547,-0.139823,-0.060666,-0.433183,0.019090,-0.504099,-0.172865,-0.625136,-0.418457,-0.191431,-0.232504,-0.202092,0.484317,-1.015942,0.382644,0.459811,0.493623,-0.354177,0.439659,0.397815,0.201293,-0.089148,0.064676,0.395443,0.065271,0.121579,0.061875,0.217168,0.125307,-0.306506,-0.021998,0.660615', '1308755', '1296534', '4275444', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3213270', '猫狗大战2：珍珠猫复仇', '喜剧', '本片为2001年在《猫狗大战》的续集。故事发生在距离上一次猫咪和狗狗的大战已经过去了数年之后。来之不易的和平再一次受到威胁。这次的敌人可不是上一部中的笨蛋，它可是原猫咪间谍组织“喵”（MEOWS）的顶级特工，名为Kitty Galore。它顺利地窃取到了狗狗组织的核心机密，并且为了报复狗狗组织和人类，它设计了一个恐怖而毒辣的计划意图控制全世界！在面对这样一个迫在眉睫且前所未有的致命威胁的紧要关头，猫与狗在万不得已的情况下，只能被迫选择结成同盟——这还是这两种生物历史上的第一次，在这个由一只猫所制造的浩劫当中，它们需要拯救的不仅仅是自己，还有他们深爱着的人类。为了阻挠邪恶计划的征途，它们必须得将身体里潜藏的一切生物本能发挥到极致才行……©豆瓣', '詹姆斯·麦斯登', '布拉德·佩顿', 6.6, 13695, 'tt1287468', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p573428831.jpg', 1.5, 10.1, 53.9, 25.2, 9.3, '0.293043,0.164337,-0.772538,0.777614,-0.104100,0.098043,0.566011,-0.279033,-0.394259,-0.103899,0.420003,0.623948,-0.000186,-0.032221,0.012574,-0.263429,0.089214,-0.522613,-0.178629,-0.043084,-0.436410,-0.048820,-0.702595,-0.174053,-0.089862,-0.184198,0.968799,0.312505,-0.556167,0.071986,0.113245,0.374135,-0.070756,0.289344,-0.049720,-0.363306,-0.085313,-0.074713,-0.179901,0.344262,-0.010073,-0.299691,0.053777,0.517562,-0.197115,0.161516,0.788245,-1.118882,-0.357363,-0.405539,0.362514,-0.485766,-0.089134,0.184935,0.315223,-0.093283,0.305970,0.143278,-0.071583,-0.061263,0.007732,-0.249332,-1.361356,-0.412093,-0.057620,0.115024,-0.376746,0.377763,-0.007178,0.211131,0.330396,-0.449868,0.065904,0.482710,0.332670,0.430018,-0.357789,0.124006,-0.530449,-0.163686,0.790736,-0.230649,-0.404865,0.305686,-0.137073,-0.562942,-0.279748,-0.651715,-0.244191,-0.031514,0.364868,0.150192,-0.550078,0.394575,-1.027077,0.134468,-0.171890,-0.186049,-0.035777,-0.499626,0.061290,-0.387879,-0.040595,-0.415876,-0.189897,0.226912,0.251892,-0.449601,0.696623,-0.968044,0.225708,0.950925,0.158519,-0.482304,0.463205,-0.092774,0.144238,-0.295781,0.007775,0.015773,0.194588,0.537674,0.374164,0.315814,0.351223,0.048931,-0.446869,0.725833', '1305071', '35377026', '26759819', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3214137', '囧男孩', '剧情', '终日腻在一起的小学生“骗子”1号（李冠毅）及2号（潘亲御）是死党，两人的家庭都不完整，1号的妈妈下落不明、爸爸（马志翔）精神失常，2号干脆是与“自私、不爱他”的嬷嬷（梅芳）一起生活，他讨厌叔叔又送一个嗷嗷待哺的小妹妹给嬷嬷带。2号最爱卡达天王，1号为逗他开心会拿“妈妈从夏威夷寄至的”卡达天王将他逗耍。两人时常联手编造谎言作弄同学，老师没辙，屡罚他们放学留在图书馆里黏书，他们因之拥有了一个色彩斑斓的童话世界。而为了去那个他们称之为“异次元”的世界生活，两人尝试同时启动十台大风扇制造超大的龙卷风，结果虽然失败，却与永远有甜美笑容的同学林艾莉（徐启文）一起暂时远离了成长的痛苦。又听闻在某游乐场的恐怖滑道滑一百次便可飞到“异次元”，两人又决定省吃俭用存钱，相约一起长大。但2号经不起玩扭蛋抽超大卡达天王的诱惑，一念之差将共同梦想背叛，这成为两人友谊破裂的导火索，其后1号为挽回友谊，做出惊人决定。两个男孩的行为也许超“囧”，情感相比成人，却是真过百倍。', '潘亲御', '杨雅喆', 7.8, 14061, 'tt1289802', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p724744782.jpg', 0.5, 2.7, 27.1, 46.9, 22.8, '0.193269,-0.071554,-0.515230,0.333656,-0.223875,-0.324991,0.656468,0.161787,-0.228148,0.023452,0.153622,0.596017,-0.120542,0.229846,0.058812,-0.053212,-0.107738,-0.441388,0.215375,-0.224770,-0.083270,-0.313945,0.085904,-0.022540,-0.052687,-0.129022,0.516858,-0.312292,0.016134,0.449789,0.191937,0.106157,-0.158193,0.255534,-0.386034,-0.058545,-0.191554,0.089986,-0.351062,0.198496,-0.074080,0.103545,0.200115,0.023710,0.082801,-0.026135,0.756514,-0.375142,-0.083308,-0.191884,0.150032,-0.236146,-0.428173,0.059897,0.123392,0.126264,0.216096,0.116004,-0.153853,-0.044358,0.155996,-0.028384,-0.534522,0.151240,0.253779,-0.137765,-0.353496,0.316493,-0.078433,-0.112012,0.293322,-0.116569,0.055642,0.244222,0.208895,0.483504,-0.260123,0.225981,-0.276943,-0.025957,0.787995,-0.249660,-0.146654,0.249244,-0.007305,-0.039317,0.277946,-0.468387,-0.414608,0.096301,-0.055579,-0.125111,-0.033091,0.336505,-0.832001,0.178612,-0.180676,0.089539,0.185556,-0.503193,-0.040982,-0.414717,-0.086347,-0.172994,-0.066259,0.209616,0.111609,-0.253463,0.800395,-0.633394,0.354063,0.396788,0.448120,-0.566139,0.775602,0.276816,0.007025,-0.337532,0.340972,0.122822,-0.054919,0.297161,-0.017865,0.294431,0.109459,0.109060,-0.438557,0.309186', '2081098', '1302661', '4181031', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3215099', '风筝', '动作', 'J（赫里尼克•罗斯汉 Hrithik Roshan 饰）做梦都想过上有钱人的生活，然而命运总是跟他开玩笑。在拉斯维加斯打拼的他在最潦倒的时候，甚至会和那些想拿到美国绿卡的女人假结婚，赚取一定的佣金。但是他却差点儿错过主动投怀送抱的富家千金GINA（康格娜•拉瑙特 Kangana Ranaut 饰）。GINA的父亲BOB是拉斯维加斯最大赌场的老板，JAY得知后，最终凭借自己出色的舞技赢得了BOB一家的赏识。本来自此便可以飞黄腾达的他，在BOB家意外遇到与他假结婚的LINDA（芭芭拉•默瑞 Bárbara Mori 饰），此时，LINDA已经准备嫁给GINA的哥哥TONY了。在相处中，J和LINDA暗中互生情愫，并最终打伤TONY私奔。然而，TONY并没有打算轻易放过他们，不仅诬陷他们丢走了赌场巨额钱财，而且动用了所有力量对他们进行围剿……©豆瓣', '赫里尼克·罗斯汉', 'Anurag Basu', 7.6, 8768, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p490337273.jpg', 1.3, 4.4, 30.6, 41.9, 21.8, '0.292578,0.097638,-0.795642,0.498759,-0.307779,-0.477240,0.543776,-0.002729,-0.407082,-0.218314,0.068698,1.012590,0.002852,0.086175,0.178638,-0.059779,-0.156813,-0.758570,0.088792,-0.145368,-0.123197,-0.549262,-0.268527,-0.177302,-0.161188,-0.073121,0.505706,0.102195,-0.219756,0.525290,0.327129,0.083243,0.106136,0.536887,-0.334802,-0.045142,0.052953,0.326224,-0.392559,0.306394,-0.015267,-0.284279,-0.031910,0.171284,0.375278,0.327355,0.293572,-0.172119,-0.125655,0.049542,0.080330,-0.203571,-0.060206,0.215209,0.070379,-0.202704,0.428305,0.296477,-0.383402,-0.207836,0.224419,0.001780,-0.964353,0.051782,0.158366,-0.111361,-0.694053,0.421352,0.079822,-0.027624,-0.015121,-0.283113,0.351103,0.598256,0.200970,-0.020527,-0.285981,-0.070104,-0.920099,0.220484,0.818175,-0.178868,0.039276,0.335628,-0.038800,-0.268825,0.038301,-0.407500,-0.420115,0.125114,0.241479,0.169453,-0.295610,0.095245,-0.507501,-0.107737,-0.154371,0.004171,0.080260,-0.601043,0.132719,-0.484205,-0.396875,-0.465301,-0.487625,0.222853,0.093192,-0.411675,0.423602,-0.837152,0.185282,0.535944,0.628243,-0.885783,0.701992,0.233160,-0.007073,0.042118,-0.365136,0.125713,0.187786,0.220768,0.066296,0.175511,0.309448,-0.410615,-0.054977,0.534079', '1299799', '1835843', '26678784', '1306916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217099', '大决战！超奥特曼八兄弟', '剧情', '大古是一个憧憬着电视节目《奥特曼》中的奥特曼形象，梦想是有朝一日能成为宇宙船船长的平凡少年。现在还在逐渐成长中，目前只是横浜市观光课的一名普通公务员。没错，本作的舞台是和之前的昭和·平成系列毫无联系，平行存在于现实世界中的横浜。幼年时憧憬着成为职业棒球选手的飞鸟，现在是横浜体育场的一名球童。阿良也作为飞鸟的同事而不断支持着他。把“开发出大古梦想所能够驾驶的飞船”作为理想目标的我梦，目前和敦子一同作为横浜MaliTime博物馆的实习生而奋斗着。就在同时，为追赶超越了时间和空间的格斯拉王，梦比优斯奥特曼出现在了横浜港。他是唯一一个知道降临在我们世界的这一切的引导性角色。「让７名勇者再次觉醒、并一同去打倒侵略者」出现在梦比优斯面前说着这么番话的穿着红鞋的少女究竟是？随着格斯拉王的出现、在山下码头也同样出现了庞敦王。那是曾一度打败赛文奥特曼的强敌。和在横浜体育场工作的飞鸟，在横浜MaliTime博物馆工作的我梦，以及大古这３人相聚在一起谈论年幼时的梦想和将来的打算，期待着未来和他们擦出的火花吧。早田、团、乡、北斗这４人也同样只是普通的人类。并且也分别和秋子、安奴、秋、夕子结了婚，拥有了各自幸福的家庭。《迪迦奥特曼》第２６话《彩虹的怪兽魔境》中登场的刚力怪兽希尔巴贡，第３６话《超越时空的微笑》中登场的超力怪兽哥尔德拉斯，都以希尔巴贡王和哥尔德拉斯王的身份复活了。两只都是与时间和空间有关的怪兽，出现在这个世界也合情合意。在与未来的谈话中，大古更加确信了自己的目标。但是当从未来口中得知「穿着红鞋的少女」时，大古曾一度淡忘的记忆再次苏醒。还是孩子的他，当时也曾见过穿着红鞋的少女。将怪兽召唤至这', '长野博', '八木毅', 8.8, 13949, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2192662052.jpg', 0.5, 1.4, 11.9, 31.4, 54.8, '0.251978,0.135896,-0.640986,0.642758,-0.111754,-0.300638,0.744940,-0.061109,-0.311190,-0.252828,0.160644,0.805606,-0.072149,0.411530,0.353458,-0.051365,-0.231714,-0.718292,-0.274992,-0.083083,-0.369419,-0.489154,-0.365712,-0.111134,-0.004868,-0.543954,0.793636,-0.026275,-0.077496,0.380274,0.364171,0.196530,-0.200745,0.419110,-0.476231,-0.033140,-0.035423,0.277062,-0.319727,0.217973,-0.155708,-0.068916,0.022788,0.130187,-0.170202,0.036690,0.752886,-0.452996,0.050263,-0.096281,0.213843,-0.211460,-0.096411,0.026190,0.417508,-0.193604,0.093866,-0.035677,0.050757,-0.025486,-0.043978,-0.121855,-0.881881,-0.089196,-0.003232,0.304708,-0.693977,0.383254,-0.014731,-0.199031,0.414331,-0.121330,0.254061,0.193687,0.248272,0.371615,-0.285448,0.061425,-0.541220,0.261115,0.599360,-0.026716,-0.339323,0.311701,-0.132622,-0.517086,-0.460500,0.013202,-0.331931,-0.055381,0.148910,0.238067,-0.167525,0.311708,-0.628279,0.052080,0.004502,-0.263166,0.030268,-0.534614,-0.218216,-0.441580,0.062417,-0.614742,-0.295092,0.153494,0.149246,-0.342130,0.713332,-0.970588,0.270188,0.564733,0.461070,-0.146743,0.911963,0.142327,0.274588,-0.320225,-0.031319,0.125463,-0.046034,0.382918,-0.088948,0.457149,0.046868,-0.138457,-0.530209,0.716169', '3055049', '25880986', '1793491', '26021055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217122', '一页台北', '喜剧', '台北的夜，灯火通明。小凯（姚淳耀 饰）帮女友收拾好行囊，依依惜别。她去了巴黎，相思让他拼命补习法语，希望有朝一日团聚。期间，他在书店结识了店员Susie（郭采洁 饰），两人渐渐产生了感情。小凯的爸爸（高捷 饰）开了家小吃店，小凯的朋友高高常来光顾，并讲述懵懂爱情。老主顾还包括黑道人物豹哥，后者面临中年危机，更愿意谈情，而非生意。但是他的小弟阿洪（柯宇纶 饰）却跃跃欲试，准备干一票大的，以证明自己。终于，他等到了一次机会。豹哥的合伙人把一批货落在了佛龛里。面对警察（张孝全 饰）的盯梢无从下手。为了拿到这批货，豹哥许诺资助小凯去巴黎，将此事交给了他。但是阿洪决定自己单干。于是，一场螳螂捕蝉黄雀在后的游戏开始了……本片获柏林电影节最佳亚洲电影奖。©豆瓣', '郭采洁', '陈骏霖', 6.6, 78844, 'tt1291125', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p542945429.jpg', 1.6, 10.5, 50.8, 28.8, 8.3, '0.054810,0.115676,-0.432822,0.224683,-0.071882,-0.400091,0.285532,0.284405,-0.377293,-0.107081,0.136081,0.590612,0.036820,0.273711,0.116036,-0.042906,-0.392203,-0.624295,0.243365,-0.100362,-0.114265,-0.164957,-0.025148,-0.212338,-0.139944,0.181772,0.209292,0.036902,0.111404,0.472959,0.382394,-0.091394,0.090314,0.427442,-0.130971,0.058551,0.020291,0.014137,-0.533710,0.218166,0.223010,-0.263247,-0.263728,0.313841,0.342112,0.302642,0.649666,0.095926,-0.129171,0.101464,0.250636,-0.239938,0.024856,0.009518,0.116604,0.160216,0.117202,0.069961,-0.206210,0.020929,0.131736,-0.135967,-0.456282,0.239482,0.011747,-0.021269,-0.648741,0.420230,-0.097081,0.143520,0.103763,-0.237902,0.121996,0.240411,0.376007,0.006923,-0.055510,0.013121,-0.459616,0.476453,0.490412,-0.181028,0.421781,0.447001,0.065043,-0.321171,0.044362,-0.015196,-0.315569,-0.006163,0.462259,-0.252849,-0.208867,-0.125368,-0.558237,-0.251682,-0.169612,-0.176824,0.001462,-0.397636,0.237194,-0.621800,-0.085640,-0.020238,-0.107754,0.144447,0.212155,-0.205608,0.661470,-0.585983,-0.033567,0.645269,0.256283,-0.593901,0.480384,-0.037533,0.200559,-0.188195,-0.046856,-0.128575,-0.018693,0.233146,0.240669,0.320177,0.041973,-0.166451,-0.229921,0.299404', '3811356', '3326747', '11541282', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217128', '哈里·布朗', '剧情', '70多岁的哈里·布朗（迈克尔·凯恩 Michael Caine 饰）是一名退役的皇家海军军官，妻子去世后，靠退休金生活的哈里独自住在贫民窟附近的小公寓。附近的人行隧道是小混混们街头斗殴、毒品交易和肉体买卖的场所，跟布朗下象棋的好朋友，老头子莱昂纳德（大卫·布莱德利 David Bradley 饰）就常被这帮混混骚扰，甚至终被残忍杀害。女警官弗兰普顿（艾米莉·莫迪默 Emily Mortimer 饰）与下属负责调查案件，却因证据不足而不得不释放杀害莱昂纳德的凶手。一把年纪的布朗忍无可忍，决定亲自上阵，铲除混混，为莱昂纳德报仇。本片获2010年英国《帝国》电影杂志评选的最佳英国影片、最佳惊悚片及最佳男主角（迈克尔·凯恩）提名，并获伦敦影评人协会最具突破性的英国影人（丹尼尔·巴伯 Daniel Barber）提名。©豆瓣', '迈克尔·凯恩', 'Daniel Barber', 7.6, 21988, 'tt1289406', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p489147799.jpg', 0.4, 2.4, 30.5, 51.7, 15, '0.131433,-0.376092,-0.277931,0.457834,-0.019536,-0.400523,0.500165,0.266094,-0.469856,-0.360903,0.225137,0.788294,-0.123354,0.262163,0.413328,-0.137968,-0.442851,-0.580677,-0.192571,-0.057052,-0.114402,-0.468044,-0.234580,-0.382497,-0.294824,-0.239700,0.629211,-0.222206,-0.087406,0.435942,0.457523,0.486778,0.074487,-0.064080,-0.019200,0.021753,0.575942,-0.351462,-0.530018,0.256579,-0.110645,-0.181903,-0.160368,-0.120745,0.216570,0.356529,0.457375,0.092556,0.182765,-0.335409,0.328123,-0.409275,0.014769,0.051749,0.423115,-0.170941,0.375163,0.330534,0.010813,-0.042610,0.071446,-0.262668,-0.520816,0.071221,0.146750,-0.037759,-0.447986,0.274217,-0.269593,0.178941,-0.194216,-0.094167,-0.016202,0.131684,0.134447,0.105231,0.027182,0.032184,-0.392785,0.396963,0.330784,-0.103589,-0.219593,-0.040251,-0.143095,-0.433468,0.146995,-0.367619,-0.347298,0.092838,0.458309,-0.348821,-0.010774,0.089789,-0.399647,-0.327581,-0.513552,-0.228632,-0.020520,-0.170596,-0.067105,-1.102717,-0.000696,-0.028133,-0.129489,-0.078744,0.221940,-0.011844,0.368554,-0.477200,0.177645,0.630428,0.243349,-0.340838,0.613286,-0.031107,0.322268,-0.255336,-0.407544,0.285646,0.322354,0.131491,0.054216,0.073287,-0.033490,-0.427849,-0.162581,0.202936', '34961898', '2028645', 