INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217142', '通灵神探', '科幻', 'FBI特工乔（杰弗里·迪恩·摩根 Jeffrey Dean Morgan 饰）和搭档凯瑟琳（艾比·考尼什 Abbie Cornish 饰）正在调查一宗连环杀人案，此案件手段之凶残，逻辑之混乱让两名探员感到无从下手。无奈之下，他们找到了隐居多年的通灵神探约翰（安东尼·霍普金斯 Anthony Hopkins 饰），希望借助他的特异功能找到有用的线索。然而，案件的凶手似乎知道了约翰的重出江湖，他不仅毫不顾忌的再度犯案，还留下了充满挑衅意味的字条。随着调查的深入，约翰逐渐发现，凶手竟然和他一样拥有通灵能力，而和他相比，自己一方显然落入了下风，丝毫没有翻身的机会。就在约翰一行人走投无路之时，凶手竟然主动献出了真身。©豆瓣', '安东尼·霍普金斯', '阿方索·博亚尔特', 6.5, 35480, 'tt1291570', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2300255376.jpg', 1.4, 11.7, 54.5, 25.8, 6.6, '0.272824,-0.034383,-0.919029,0.781075,-0.366765,-0.187123,0.574196,-0.093134,-0.538865,-0.510173,0.116627,0.594739,-0.096454,-0.004035,0.022937,-0.188737,-0.164812,-0.810444,0.144371,-0.097810,-0.150924,-0.776611,-0.577344,-0.401232,0.086914,-0.295805,0.368333,0.233067,-0.240592,0.428058,0.144247,0.451571,-0.304833,0.593101,0.051159,-0.134822,0.337667,-0.048562,-0.177613,0.299492,0.202694,-0.325596,-0.065292,0.509210,-0.154989,0.664422,0.597497,-0.283058,-0.259304,0.033121,0.227502,-0.272653,-0.025848,0.262997,0.289584,-0.173309,0.065077,0.403664,-0.077444,-0.109063,0.225958,0.225885,-0.905690,0.095060,-0.021679,0.201122,-0.305864,-0.019460,-0.234057,0.033859,-0.158614,-0.432555,0.219542,0.028876,0.429289,0.016771,0.042158,-0.159817,-0.435000,-0.117560,0.323476,-0.175423,-0.178427,0.232330,0.117863,-0.624801,-0.129450,-0.190261,-0.035740,-0.027864,0.600632,0.221597,-0.058021,0.112632,-0.394710,-0.251252,-0.458568,0.066240,-0.294105,-0.280157,0.212936,-0.538018,-0.141048,-0.081721,-0.469991,-0.039769,0.041011,-0.533541,0.317949,-0.606224,0.240167,0.531734,0.090066,-0.564651,0.418518,-0.088791,-0.117894,-0.185112,-0.301437,0.182532,0.366549,0.266401,0.418409,0.146816,-0.019804,-0.253021,-0.148623,0.300970', '1307442', '35073886', '25862560', '3170961');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217149', '忍者神龟：变种时代', '喜剧', '繁华大都会美国纽约，邪恶领袖施莱德率领的大脚帮在城市内为非作歹，甚嚣尘上。安保公司老板埃里克·萨克斯（威廉·菲德内尔 William Fichtner 饰）推出最新安保系统，发誓维护城市的和平。第6频道女记者爱普尔·奥尼尔（梅根·福克斯 Megan Fox 饰）偶然拍到大脚帮被四名神秘侠客挫败的画面，在第二次遭遇非常事件时，她惊讶地发现四名侠客竟然是变异后的巴西龟：拉斐尔、列奥纳多、米可朗基罗、多纳泰罗。忍者神龟的名字勾起了爱普尔儿时的记忆，当年她的父亲与萨克斯正是研究生物变异实验的伙伴。她将这个消息告诉给萨克斯，可是在和忍者神龟及其老师斯普林特会面后，才发觉萨克斯与施莱德是这座城市内的罪恶之源……本片根据同名经典漫画改编。©豆瓣', '梅根·福克斯', '乔纳森·里贝斯曼', 6.6, 123755, 'tt1291150', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2204991581.jpg', 1.9, 11.3, 51.6, 27, 8.2, '0.117161,-0.106580,-0.565558,0.486869,0.092539,-0.320111,0.540403,0.150169,-0.515997,-0.240878,0.119940,0.614665,-0.088872,0.089974,0.541439,0.138706,-0.366342,-0.511710,-0.117294,-0.285151,-0.065753,-0.486522,-0.491770,-0.282121,0.190870,-0.657463,0.297174,-0.078465,-0.370685,0.258659,0.203793,0.523667,-0.225251,0.147248,-0.064242,0.094994,0.568764,-0.250661,-0.321142,0.162943,-0.320151,-0.074200,-0.002840,0.038761,-0.030900,0.130638,0.532050,-0.317064,-0.059793,-0.255731,0.287722,-0.148545,-0.001717,-0.147864,0.377069,-0.031344,0.203515,0.074265,-0.168999,-0.002301,-0.052409,-0.190114,-0.683958,-0.115877,-0.025532,0.263065,-0.457293,0.158934,-0.358960,-0.036619,0.291583,-0.213842,0.146067,0.030715,0.524140,0.309095,0.235755,0.158479,-0.245127,-0.113665,0.245289,-0.035407,-0.189886,0.201193,-0.122635,-0.388312,-0.103476,-0.092897,-0.353080,0.176655,0.193256,-0.055529,-0.016251,0.340527,-0.688567,-0.338874,-0.347583,-0.244616,0.066105,-0.045786,-0.331918,-0.931937,-0.135094,0.023756,-0.063446,-0.252536,0.116008,-0.203358,0.552944,-0.771486,0.581227,0.499889,0.266431,-0.091907,0.425598,0.043607,0.086817,-0.223759,-0.068088,0.231672,0.387827,0.365323,-0.005390,0.261366,0.037430,-0.509711,-0.375144,0.479093', '1293656', '3178770', '20274039', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217150', '烛台背后', '剧情', 'HBO电视电影《烛台背后》入围第66届戛纳电影节主竞赛单元。该片根据名人传记改编，主人公李勃拉齐（迈克尔·道格拉斯 Michael Douglas 饰）是20世纪50~70年代好莱坞家喻户晓的钢琴艺术家，不但演出费用高居世界之冠，而且以极尽华冶艳丽的造型获得了“闪耀之王 ”的舞台称号。他从不承认自己是同性恋并为此打过多起名誉官司，但在晚年却不得不与22岁的男助手兼保镖斯科特（马特·达蒙 Matt Damon 饰）对簿公堂。后者声称与他有着5年的地下情并主张天价的抚养费，该事件引发了美国娱乐圈的地震。双方后来选择庭外和解，次年李勃拉齐因艾滋病发症去世。电影从斯科特与李勃拉齐的相遇开始。初见面斯科特即被李勃拉齐出神入化的钢琴演奏所迷倒，而李勃拉齐一句挑逗“这一定是命运”让两人火速定情。在无需面对公众的时候，他们就像普通情侣那样如胶似漆，过着童话般的奢华生活。然而斯科特获得了女人们求而不得的爱情和物质保证，却注定得不到一纸身份证明。这样的遗憾不仅是时代偏见造成的，也有李勃拉齐自私和刚愎的原因。最终两人因此而决裂，一代巨星的隐秘地下生活变成现实中被公众观摩的巨幕肥皂剧，一份真心付出的爱情最终输给极力掩上的柜门......', '迈克尔·道格拉斯', '史蒂文·索德伯格', 6.7, 6252, 'tt1291580', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1974500598.jpg', 1, 6.7, 53, 32.7, 6.7, '0.078861,0.176782,-0.572933,0.639256,-0.125894,-0.107209,0.634379,0.170100,-0.468857,-0.127097,0.253136,0.863741,-0.393716,-0.001782,0.349661,-0.105619,-0.217547,-0.725042,0.034681,-0.101723,0.086736,-0.446511,-0.150525,0.017433,-0.264712,-0.374444,0.847841,0.071497,-0.195678,0.340209,0.442006,0.317656,0.031209,0.217996,-0.068540,-0.111431,0.056651,0.341940,-0.471067,0.260831,-0.079667,-0.139060,-0.139192,0.150032,-0.064977,0.254071,0.416203,-0.231723,-0.147676,-0.105716,0.679184,-0.179142,-0.181727,0.130963,0.294982,0.069430,0.245245,0.327108,0.059873,0.064648,0.081757,-0.003860,-0.618465,-0.098059,0.212910,0.061225,-0.465429,0.508613,-0.283847,-0.110940,-0.048804,-0.116051,0.088349,0.143780,0.622641,0.138576,-0.108157,-0.155449,-0.502653,0.392746,0.633097,0.131477,-0.474026,0.449321,-0.371574,-0.597951,-0.127752,-0.486593,-0.613243,0.247125,0.137720,-0.048133,0.025343,0.380780,-0.488538,-0.117238,-0.113613,-0.208788,0.101486,-0.342928,0.035364,-0.646962,-0.267573,-0.410727,-0.304466,-0.069579,0.057618,-0.452954,0.688166,-0.750029,0.241621,0.457527,0.300350,-0.404773,0.754202,0.276074,0.083719,-0.143217,-0.166120,0.364134,0.012765,0.121741,-0.120060,0.049804,-0.002781,-0.243343,-0.121560,0.525685', '4301278', '30162520', '25880986', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217153', '十三', '剧情', '为给身患重病的父亲交付医药费，电工文斯（萨姆·赖利 Sam Riley饰）不得已卖掉了房子。一次偶然的机会，文斯在他修理的房间里得到房主的一封神秘信件和一张不知道终点的火车票。一面是房主的离奇意外死亡和完全未知的危险旅程，一面是一笔足够改写人生的巨额财富，文斯最终还是决 定踏上这次神秘旅程。然而当他抵达隐蔽的目的地之后，等待他的却是一场无法全身而退的疯狂杀人游戏。本片翻拍自2005年法国犯罪惊悚影片《百万杀人游戏》（13 Tzameti），依旧由原作导演兼编剧的格拉·巴布鲁阿尼执导与编剧。萨姆·赖利、米基·洛克、杰森·斯坦森、雷·温斯顿等多位硬汉同台演绎这场生死博弈。©豆瓣', '萨姆·赖利', '杰拉·巴布鲁阿尼', 6.4, 10259, 'tt0798817', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1214875401.jpg', 2.3, 13.7, 52.1, 24.9, 7, '-0.151939,0.147194,-0.499449,0.453851,0.093065,-0.362147,0.698583,0.030843,-0.361021,-0.192302,0.351113,0.737945,-0.166738,-0.006887,0.336749,-0.075194,-0.337697,-0.475496,-0.072864,-0.027486,-0.172826,-0.495569,-0.476450,-0.038694,0.042894,-0.243774,0.616046,0.273762,-0.195401,0.363665,0.357448,0.372347,-0.053536,0.209612,-0.012502,-0.046405,0.149283,0.066854,-0.524780,0.153754,-0.001687,-0.101381,-0.353149,0.049437,0.172955,0.422375,0.532947,-0.088844,-0.233997,0.212130,0.461472,-0.288778,-0.173073,-0.128840,-0.035338,-0.038365,0.233447,0.273884,-0.165972,-0.061254,-0.052786,-0.153608,-1.045196,-0.115593,-0.024893,0.081812,-0.285018,0.311118,-0.324976,0.133377,-0.044814,-0.355541,-0.010535,0.184568,0.549424,0.233137,-0.208720,-0.018710,-0.356435,0.361121,0.478982,-0.063475,-0.151848,0.386183,-0.009361,-0.475335,-0.012114,-0.247777,-0.682582,0.326485,0.498002,0.094645,-0.052445,0.045189,-0.551417,-0.175208,-0.602423,-0.276673,-0.040676,-0.373923,-0.083867,-0.648952,-0.238460,-0.003406,-0.157670,-0.040222,0.199695,-0.273908,0.392218,-0.178158,0.359101,0.483770,-0.027290,-0.211205,0.499222,0.160846,0.127141,-0.303204,0.146066,0.174782,0.177281,0.310922,0.131422,0.098096,0.184682,-0.107698,-0.362477,0.701295', '6844861', '34890458', '27098364', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217165', '城中大盗', '剧情', '美国东部，位于波士顿近郊的查尔斯城，俨然一个被法制遗忘的失乐园。城中爱尔兰裔的工薪阶层占有很大比例，区域贫困的生活条件和令人无法喘息的压力让人们铤而走险，银行抢劫案时有发生，一切都变得癫狂无望。某个早晨，美丽的银行经理人克莱尔·吉塞（丽贝卡·豪尔 Rebecca Hall 饰）遭遇一伙头戴骷髅面具的劫匪，而她更被劫持为人质。奇怪的是，克莱尔最终意外生还，似乎这个早晨的变故从未发生过一样。一天，她邂逅了高大英俊的男子道格·麦克雷（本·阿弗莱克 Ben Affleck 饰），奇妙的缘分就此展开，两人的命运也由此改变……本片根据库克·霍根（Chuck Hogan）的原著改编。©豆瓣', '本·阿弗莱克', '本·阿弗莱克', 7.5, 65701, 'tt0840361', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p588491081.jpg', 0.3, 2.4, 32.3, 50.7, 14.4, '0.238384,0.158603,-0.660335,0.417817,0.142596,-0.056802,0.835386,0.192896,-0.416814,-0.438655,0.340800,0.812958,-0.207511,0.143285,0.318551,0.066809,-0.290517,-0.559936,-0.057449,-0.156668,-0.193235,-0.187841,-0.313944,-0.366444,-0.060979,-0.164105,0.627083,0.280378,-0.263834,0.364771,0.213532,0.313949,-0.010535,0.407515,-0.152312,-0.224536,0.169626,-0.090833,-0.219305,-0.017665,-0.300740,-0.202390,0.019367,0.413112,-0.082118,0.405431,0.737532,-0.276907,-0.369648,-0.168096,0.463169,-0.164878,-0.084861,0.154330,0.237309,-0.264169,-0.032990,0.150952,-0.154391,-0.164939,0.041007,-0.020122,-0.693942,0.229642,0.195192,0.276912,-0.277131,0.343418,-0.089827,-0.069479,-0.015956,-0.255284,0.001703,0.429316,0.497773,0.100480,0.025616,-0.069395,-0.508975,0.219783,0.790357,-0.052421,-0.677082,0.161472,-0.490904,-0.522613,-0.276975,-0.037111,-0.444447,0.284859,0.336623,-0.064026,-0.133456,0.500563,-0.662274,0.049687,-0.385605,-0.139758,-0.291886,-0.227919,-0.194811,-0.635510,-0.171902,-0.292035,-0.217060,0.043292,0.138147,0.064001,0.330560,-0.400658,0.110336,0.610230,0.158337,-0.409257,0.241675,0.056705,0.086090,-0.283337,-0.122951,0.641567,0.009135,0.249568,-0.115527,0.191285,-0.017216,-0.048766,-0.043499,0.501791', '25828589', '2988294', '1307311', '1292528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217169', '勇士', '剧情', '这是一个破碎的家庭，酗酒的教练父亲帕迪（尼克·诺特 Nick Nolte 饰）家暴妻子，次子汤米（汤姆·哈迪 Tom Hardy 饰）与不堪忍受的母亲远赴他乡；长子布兰登（乔尔·埃哲顿 Joel Edgerton 饰）为了爱情选择留下，并认为从此可以得到父亲的器重与栽培，然而最后父子还是分道扬镳。时隔多年后，汤米带着母亲痛苦死去的悲伤记忆，以及在伊战中的惨痛经历找到父亲，要求后者再度担任自己的教练，以参加MMA的重奖大赛；几乎与此同时，昔日的职业格斗选手、如今的中学物理教师布兰登为金钱所困扰，他不能忍受自己无法为妻女提供庇护，决定重返赛场。在MMA的赛场上，这对分离多年的兄弟将再度聚首，用血与汗的交融，化释彼此的心结……©豆瓣', '汤姆·哈迪', '加文·欧康诺', 8.9, 154949, 'tt1291584', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1145536386.jpg', 0.3, 0.7, 8.7, 35.1, 55.2, '-0.106098,-0.017236,-0.486575,0.671963,-0.116422,-0.595866,0.542184,0.100694,-0.524438,-0.332356,0.282456,0.999302,0.128492,0.446236,0.245491,-0.279703,-0.223456,-0.814385,-0.049183,-0.068883,-0.215271,-0.632687,-0.157946,-0.138474,-0.168390,-0.441660,0.988495,0.123104,-0.034679,0.551938,0.275193,0.339774,0.011487,0.180012,-0.015064,-0.111958,-0.140343,0.211494,-0.757066,0.038049,0.174318,0.038430,0.010341,0.058830,0.045406,0.255160,0.638804,-0.418835,-0.057741,-0.274668,0.363750,-0.256927,0.109228,0.265729,-0.141735,0.189612,0.276621,0.444879,-0.203865,-0.126413,0.055305,0.034920,-0.862154,-0.163948,0.321171,-0.048016,-0.622670,0.777258,-0.237958,-0.086707,0.173367,-0.221054,0.077185,0.376797,0.271320,0.455090,-0.566557,-0.013115,-0.036746,0.240738,0.816577,-0.258194,-0.182886,0.007664,-0.391126,-0.336225,0.236105,-0.531453,-0.510004,0.155570,-0.002115,0.377789,0.119395,0.355700,-0.278632,-0.227657,-0.254286,-0.049861,0.282550,-0.428955,0.038028,-0.429011,-0.211281,-0.179811,-0.309134,-0.030087,0.048188,-0.419998,0.610380,-0.828454,0.322544,0.294642,0.370991,-0.482373,0.652931,0.325108,0.441715,-0.329639,-0.214355,0.569567,-0.025267,0.134899,-0.012588,-0.016777,0.073121,0.124680,-0.349878,0.471985', '30345227', '1303034', '1482099', '25903033');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217669', '刺', '剧情', '生物学博士赛斯（Paulo Costanzo 饰）和妻子宝莉（Jill Wagner 饰）驾车去郊外游玩，路上，他们遭遇了另一对夫妇。丹尼斯（Shea Whigham 饰）和蕾丝（Rachel Kerbs 饰）是一对亡命鸳鸯，他们希望偷渡墨西哥开始新的生活，但是汽车在路上抛锚。因此，丹尼斯劫持了赛斯夫妇的汽车，并将他们绑作人质。驾驶汽车的宝莉无意中轧到一个奇怪生物，引起汽车爆胎。众人下车查看，赛斯惊奇地发现被压扁的动物竟仍有生命迹象。惶恐的他们逃到一座加油站，然而很快发现，他们正被一种长满刺的未知生物所包围……©豆瓣', '保罗·卡斯坦佐', '托比·维尔金森', 6.2, 8057, 'tt1031280', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1133892099.jpg', 3.5, 16.4, 54.6, 20.1, 5.4, '0.496421,-0.197631,-0.649822,0.400774,0.164318,-0.076312,0.896496,0.203390,-0.517592,-0.207121,0.481639,0.605389,-0.308165,-0.096056,0.331832,0.212163,-0.457707,-0.275928,0.249904,-0.026709,-0.544973,-0.219442,-0.198206,-0.290228,0.112648,-0.195679,0.438183,0.134065,0.058816,1.037986,-0.094832,0.224793,-0.576193,0.622515,-0.168274,0.315279,0.240247,-0.134043,-0.040041,0.032507,-0.262393,-0.112208,0.077068,0.142034,-0.261639,0.381058,0.789256,-0.121810,-0.072881,0.123998,-0.039959,-0.282170,0.306048,0.195050,0.479430,-0.038424,-0.133405,-0.146203,-0.157795,0.025846,0.216264,0.452212,-0.222868,0.179121,-0.327983,0.227456,-0.657928,0.268519,-0.074622,-0.205179,0.169790,-0.390408,0.382822,0.126254,0.204726,0.178445,-0.116607,-0.136587,-0.825559,-0.267514,0.606824,-0.224904,-0.117512,0.299839,-0.197725,-0.255894,0.036535,0.178221,-0.402621,-0.216881,0.756412,0.222471,-0.408377,-0.040336,-0.829266,0.029400,-0.448429,-0.220364,-0.057920,-0.263773,-0.001613,-0.789647,0.333129,-0.439234,-0.309516,0.249559,-0.086318,-0.095537,0.306214,-0.389499,0.152939,0.512444,0.197133,-0.430488,0.609421,-0.439195,0.048278,-0.123137,-0.243261,0.240234,0.181497,0.507045,0.027148,0.449465,-0.204460,-0.084633,-0.451979,0.174811', '1306670', '35256235', '3011051', '26882457');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217770', '单身指南', '喜剧', '爱丽丝（达科塔·约翰逊 Dakota Johnson 饰）和男友之间的感情走到了尽头，为了给这段恋情寻找新的可能性，她决定暂时离开男友，离开家乡，前往纽约闯荡。罗宾（瑞贝尔·威尔森 Rebel Wilson 饰）的个性大大咧咧，白天，她是法律事务所里衣着得体的小助理，每当夜幕降临，她便会摇身一变，成为夜场里最闪亮的女王。梅格（莱斯利·曼恩 Leslie Mann 饰）早已经看穿了婚姻的本质，是一名不婚主义者，可是，一个属于她的孩子对于梅格来说却有着致命的吸引力。露西（爱丽森·布里 Alison Brie 饰）的社交圈很小，因此她将脱单的期望寄托在了虚拟的社交网络中，结果却屡屡令她失望。©豆瓣', '达科塔·约翰逊', '克利斯汀·迪特', 6.8, 23839, 'tt1292566', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2285725831.jpg', 1.3, 9.4, 47.8, 30.8, 10.7, '0.350133,0.385048,-0.641598,0.586793,-0.295494,-0.253676,0.666678,0.087020,-0.478358,-0.460880,0.061667,0.974853,-0.176882,0.319622,0.314807,0.217905,-0.365034,-0.625563,0.057201,-0.431202,-0.116238,-0.423312,-0.536782,-0.129587,-0.205935,-0.212619,0.801449,0.104042,-0.272508,0.461944,0.455140,0.261023,-0.058775,0.634364,-0.045449,-0.122956,0.014751,-0.061704,-0.284137,0.162776,0.032070,-0.014399,0.227945,0.430053,0.166040,0.413185,0.477451,-0.503653,0.036422,-0.024608,0.471958,-0.208183,-0.040878,0.275060,0.208458,-0.016951,0.214951,0.258666,-0.298242,0.092570,0.030337,-0.363139,-0.660745,0.030733,0.073905,0.271024,-0.643081,0.433473,-0.205642,-0.180018,0.211708,-0.260853,0.140117,0.084847,0.223719,0.332880,-0.044556,0.326896,-0.364358,-0.111784,0.450145,0.127585,-0.238582,0.417088,-0.496705,-0.312544,0.001670,-0.070236,-0.525561,-0.151077,0.078569,0.139542,-0.126061,0.239315,-0.569549,0.088060,-0.271486,0.043498,0.061726,-0.473044,0.009251,-0.669204,-0.127948,-0.627825,-0.357511,0.058119,-0.064782,-0.260209,0.707469,-0.919880,0.156245,0.414826,0.396657,-0.521954,0.753901,0.130105,0.376370,-0.303926,-0.023637,0.666129,-0.238678,0.166082,-0.247456,0.324770,0.011008,-0.380249,-0.396911,0.794842', '1870681', '3882427', '1292720', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217878', '伦敦大道', '剧情', '本片根据Ken Bruen同名小说改编，由威廉姆•莫纳汉亲自改编剧本。米切尔（柯林·法瑞尔 Colin Farrell 饰）以前是个混迹在街头的痞子，蹲了几年牢被释放后决定重新做人，但却一直找不到工作。以前的那些朋友给他提供了一个替给放高利贷的金主收钱的工作，无可奈何的他只能接受。但不久后，他被一个不愿意抛头露面的女明星艾思林（凯拉·奈特莉 Keira Knightley）雇佣。艾思林不堪小报记者和狗仔队的困扰，雇佣了米切尔来给自己“清除麻烦”。当艾思林渐渐了解切米尔的为人，两人坠入了爱河。就在米切尔憧憬未来的时候，他的过去找上了门来。街头的那些违法犯罪的事情一直跟随着他。不幸的是，米切尔发现自己又莫名其妙地卷入了黑帮的矛盾中，这些矛盾直接威胁着他现在的生活，他能安然度过这些烦恼的事情并和艾思林生活在一起么？©豆瓣', '科林·法瑞尔', '威廉·莫纳汉', 6.5, 15867, 'tt1213648', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1294521317.jpg', 1.8, 13.2, 51, 26.5, 7.6, '0.562556,-0.105969,-0.607739,0.498337,-0.261301,-0.486327,0.824987,0.140257,-0.447296,-0.199026,-0.181573,0.789877,0.021770,0.156569,0.184904,0.110080,-0.479555,-0.947474,-0.006045,-0.221043,-0.304035,-0.422592,-0.160193,-0.459056,-0.365951,-0.118103,0.370214,0.063378,-0.123345,0.392199,0.229646,0.352030,0.128456,0.680627,-0.188314,0.235177,0.055768,0.033744,0.002217,0.323510,0.235666,-0.237824,-0.152433,0.117116,0.261509,0.491069,0.448512,-0.089276,-0.213088,0.140440,0.228154,-0.406788,-0.016709,0.141271,0.309880,-0.116693,0.397436,-0.024556,-0.357845,0.020432,0.004407,0.012556,-0.873765,-0.230810,-0.190705,0.174866,-0.909779,0.435997,0.009917,-0.096972,-0.127608,-0.384635,0.243056,0.380221,0.225260,0.308194,-0.066138,-0.097453,-0.541737,0.472725,0.686431,0.196183,-0.110219,0.432567,-0.303189,-0.207188,-0.134228,-0.263551,-0.646896,-0.102744,0.405674,-0.148439,-0.417542,0.249663,-0.578396,-0.113952,-0.191597,-0.194505,-0.296069,-0.636224,-0.030023,-0.421513,-0.220925,-0.234058,-0.312430,-0.053097,0.122242,-0.297344,0.589414,-0.800530,0.347243,0.954421,0.266568,-0.508342,0.648338,0.215297,0.188426,0.022157,-0.080885,-0.147437,0.110736,0.582550,0.394782,0.502417,0.351945,-0.328670,-0.397199,0.454704', '1947080', '4604803', '1949005', '1292584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3217894', '龙纹身的女孩', '剧情', '本片根据瑞典推理小说名家斯蒂格•拉赫松《千禧年》三部曲的第一部《恨女人的男人》改编。《千禧年》杂志的记者麦克•布隆韦斯特（迈克尔•恩奎斯特Michael Nyqvist 饰）应瑞典范耶尔财团巨头亨利（斯文-博蒂尔•陶博 Sven-Bertil Taube 饰）的请求，调查四十年前亨利挚爱的侄女海莉失踪案。在调查过程中，麦克接触了多位范耶尔财团人员，包括海莉的哥哥马丁（皮特•海伯 Peter Haber 饰）和表姐塞西莉亚（马莉卡•劳伦丝 Marika Lagercrantz 饰）。麦克发现保全公司调查员丽思贝丝•莎兰德（劳米•拉佩斯 Noomi Rapace 饰）入侵了自己的电脑，并提供了重要的破案线索。麦克决定与周身刺青鼻耳穿环的丽思贝丝联手调查。随着一步步接近真相，麦克发现自己的人身安全受到了威胁。但凶手是否与海莉失踪案相关呢？本片获丹麦阿曼达奖最佳外国电影提名。', '迈克尔·恩奎斯特', '涅尔斯·阿登·欧普勒夫', 7.5, 39665, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p849332967.jpg', 0.5, 2.6, 31.3, 50.4, 15.2, '0.184541,-0.108776,-0.286327,0.324064,0.313205,-0.265471,0.415056,0.059585,-0.323070,-0.368737,0.099781,0.593055,-0.278579,-0.178342,0.348236,0.247533,-0.574241,-0.699878,0.085407,-0.174887,-0.037984,-0.646371,-0.353718,-0.419169,-0.019349,-0.385669,0.483141,-0.292301,-0.033422,0.352090,0.453558,0.417121,-0.203215,-0.067156,0.386112,0.163331,0.607821,-0.237917,-0.457657,0.387892,0.101291,-0.061960,-0.054672,0.157030,0.182395,0.429684,0.318049,-0.079141,0.277063,-0.092320,0.364159,-0.043358,0.151776,-0.000783,0.267884,0.013816,0.162243,0.483102,-0.212882,-0.189178,-0.047030,-0.003296,-0.525922,0.041460,0.357902,0.372509,-0.234537,0.153114,-0.725300,0.164748,-0.052909,-0.197124,0.025045,0.227172,0.218375,0.003484,0.271106,0.154152,-0.376491,0.110653,-0.121335,-0.030930,-0.155503,-0.082464,-0.121645,-0.412561,-0.334853,0.043167,-0.354543,0.252973,0.529839,0.040676,0.131892,0.378346,-0.525604,-0.318307,-0.406226,-0.065972,0.047429,-0.171015,-0.001063,-0.898413,-0.198407,-0.056475,-0.030244,-0.234117,0.116379,-0.282227,0.448741,-0.300867,0.161940,0.627007,0.241374,-0.188902,0.340209,0.071451,0.224934,-0.436008,-0.272419,0.409302,0.209094,0.050843,0.127633,0.177523,0.030147,-0.506819,-0.205448,0.119055', '1293572', '6517421', '1298616', '2028645');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3218765', '玩火的女孩', '悬疑', '米克·布卢姆科斯特（Michael Nyqvist 饰）是千禧年报社的一名记者，他正就东欧雏妓贩卖的问题展开调查。然而随着调查的深入，他的助手道格及其女友被人残忍杀害。根据现场遗留下的指纹，所有的指控都指向了丽莎贝丝·萨兰德（劳米·拉佩斯 Noomi Rapace 饰）。不久，萨兰德的最新监护人尼尔斯·彼尤曼律师（Peter Andersson 饰）亦在寓所被人杀害。经过一段时间的环球旅行，萨兰德刚刚回到瑞典，等待她的却是一系列莫名的指控和追捕。究竟是谁策划了这一系列的谋杀？又为什么将罪名都转嫁到萨兰德的身上？所有的一切背后又隐藏着怎样的阴谋？本片根据瑞典小说家斯蒂格·拉尔松（Stieg Larsson）的原著改编。©豆瓣', '迈克尔·恩奎斯特', '丹尼尔·阿尔弗雷德森', 6.8, 6397, 'tt1216487', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1445269913.jpg', 0.9, 8.3, 51.5, 30.2, 9.1, '0.428783,-0.089691,-0.417968,0.566498,0.180368,-0.368824,0.484969,0.083142,-0.249903,-0.304233,0.339611,0.573814,-0.261282,-0.192884,0.318657,0.324399,-0.692217,-0.850038,-0.174956,-0.221898,-0.239656,-0.744981,-0.315416,-0.161468,0.248992,-0.284945,0.285473,-0.043294,-0.141158,0.071318,0.587856,0.692233,-0.266874,0.186969,-0.066418,0.093930,0.418386,-0.347190,-0.150419,0.072999,0.164719,-0.420002,-0.149692,0.297500,-0.158426,0.565760,0.631360,-0.416234,0.091921,0.109505,0.486140,-0.505348,0.233974,0.049635,0.278837,-0.015281,-0.073449,0.613997,-0.485520,-0.153196,0.147260,0.175590,-0.828735,-0.164359,0.153757,0.449140,-0.449493,0.062811,-0.387332,0.098903,0.126738,-0.178121,0.001105,0.388505,0.075607,0.366425,0.151897,-0.260910,-0.393905,0.137468,0.365979,-0.068940,-0.088825,0.040314,-0.068015,-0.374095,-0.008984,-0.089645,-0.290290,-0.034246,0.380172,-0.009843,-0.035350,0.527400,-0.457206,-0.166278,-0.567352,-0.365563,-0.028427,-0.427226,-0.118683,-0.910570,-0.233746,-0.026308,-0.201568,-0.084605,0.253410,0.049215,0.405070,-0.594343,0.309695,0.528080,0.173155,-0.230801,0.111977,-0.027110,0.039676,-0.180104,-0.451052,0.235024,0.640768,0.268402,0.067090,0.465786,0.283148,-0.309406,-0.262306,0.472429', '1307442', '6517421', '2028645', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3227266', '我的唐朝兄弟', '动作', '盛唐某年，两个盗贼来到位于荒山野岭之间的苦竹林。他们分别是善于射弈的薛十三（胡军 饰）和鲁莽开朗的陈六（姜武 饰）。二人于村民马七家落脚，与此同时三名官兵亦来到村中。官兵之一对马七的女儿罗娘（王晓 饰）欲行不轨，薛陈二人出手相助，杀死官兵两人。村中里正（李立群 饰）谨遵大唐律法，反将二人捉拿准备见官。次日，一队官兵前来捉拿盗贼，对村民大加挞伐。原本趁夜逃走被抓回的薛陈狂性大发，再次杀尽做恶官兵。在村中盘桓期间，薛十三和女屠户鹦哥（于小磊 饰）一朝云雨；陈六则迷上罗娘，情愿过回田园生活。然而他们毕竟是沾满鲜血的盗贼，且里正仍旧一门心思依靠官府除掉他们……©豆瓣', '胡军', '杨树鹏', 6.7, 21199, 'tt1518828', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p796380666.jpg', 3.5, 11.9, 42, 32.3, 10.4, '0.242822,-0.119877,-0.445994,0.261897,0.154340,-0.167532,0.476928,-0.066961,-0.628048,-0.335454,0.090750,0.230198,0.074477,0.100621,0.339587,-0.405714,0.170435,-0.439535,-0.353998,-0.035918,-0.019691,-0.218556,-0.003782,-0.335568,-0.294380,0.002530,0.194888,0.241235,-0.041245,0.708030,0.476149,0.310940,-0.618849,0.393741,-0.025423,0.059456,-0.143900,-0.313509,-0.235315,-0.090885,-0.382286,-0.362174,-0.362927,-0.355311,0.121136,0.355860,0.698128,-0.435986,0.115348,-0.272432,-0.063937,-0.148662,0.002674,0.265217,0.459520,-0.032261,0.094367,0.146258,0.024251,0.324147,0.035649,-0.183165,-0.166566,0.041529,0.246019,-0.228250,-0.788422,0.266725,0.047799,0.065963,-0.050497,-0.335575,0.239867,0.131207,0.007690,0.065508,0.174234,-0.138247,-0.563661,0.091050,0.601645,0.086793,0.493934,-0.470047,0.177087,-0.345265,0.203016,-0.083699,-0.058070,-0.169315,0.534248,-0.186574,0.051353,-0.245914,-0.268321,-0.157733,-0.337600,0.119586,-0.095863,-0.005666,0.010368,-0.614079,0.398137,-0.229497,-0.154483,0.436261,0.277743,0.008586,0.286568,-0.519203,0.140912,-0.127243,0.176114,-0.681249,0.237380,0.040998,0.335278,0.074235,-0.283014,0.076628,0.522718,0.184587,0.401648,0.145785,-0.605837,-0.068660,0.012723,-0.013490', '1451563', '1294227', '1474336', '3391271');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3227319', '幸运星 OVA', '动画', '2007年的热门动画《幸运星》以OVA形式推出了续篇。御宅族女孩泉此方、性格迥异的柊家姐妹、经常考虑问题不周到的高良美幸，四位女孩又要开始新的故事了。小狗Cherry的奇怪举动搞得大家哭笑不得；与老师一起玩网络游戏引出了话题大讨论；姐姐柊镜突然进入不伦不类的灰姑娘的世界；排球比赛中妹妹柊司努力挑战自我，要做的比姐姐还好；去山区郊游的四人陷入了迷路的困境；放学后大家一起去的宠物店似乎隐藏着不可告人的秘密。融合了日常生活与动漫恶搞的《幸运星》故事又开始了。©豆瓣', '平野绫', '武本康弘', 8.9, 5984, 'tt1418729', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2262328638.jpg', 0.2, 0.6, 9.4, 32.2, 57.6, '0.318212,-0.191344,-0.213392,0.351924,0.144439,-0.178067,0.421652,0.275431,-0.447012,-0.225448,-0.020635,0.477636,-0.524146,0.321789,0.415041,0.270758,-0.573835,-0.564797,-0.132250,-0.209772,-0.244999,-0.548527,0.123868,-0.261852,0.054291,-0.202943,0.358438,-0.212115,-0.387747,0.120739,0.210105,0.064667,-0.398886,0.338604,-0.085434,0.019207,-0.016364,0.277323,-0.142650,0.065764,-0.021806,-0.002109,-0.351150,0.029780,0.298080,0.120651,0.777096,-0.108856,-0.121716,-0.003068,0.315822,0.197688,-0.275346,-0.071203,0.451295,0.010617,0.519251,0.001189,0.163918,-0.001610,-0.017659,-0.415469,-0.401468,0.271034,0.337928,0.054642,-0.296582,0.170916,0.171182,-0.075705,0.456535,-0.258572,0.205109,0.293286,0.655110,0.424934,-0.037867,0.001735,-0.177198,0.259353,0.548977,0.032025,-0.063320,0.374510,-0.053297,-0.212472,-0.338919,-0.142174,-0.333257,0.186359,0.239835,0.004214,-0.405654,0.552660,-0.835336,-0.103558,0.142085,-0.116392,0.089512,-0.411178,-0.008323,-0.486822,-0.041753,-0.150332,-0.004148,-0.063862,0.148047,-0.184448,1.014059,-0.895258,-0.070519,0.771826,0.150327,-0.497959,0.579398,0.066691,-0.051100,-0.487210,-0.012594,-0.383212,-0.429781,0.227526,0.266854,0.469539,0.036167,-0.175572,-0.601584,0.168855', '5403927', '10174444', '3811356', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3227410', '加勒比海盗4：惊涛怪浪', '动作', '迪士尼《加勒比海盗4》豆瓣小站：http://site.douban.com/disneymovie/因故在伦敦盘桓期间，杰克·斯派罗船长（约翰尼·德普 Johnny Depp 饰）被英国国王的士兵抓住。原来传说中的“不老泉”重现世间，为了赶在西班牙之前得手。英国国王乔治二世（Richard Griffiths 饰）希望杰克和巴波萨船长（杰弗里·拉什 Geoffrey Rush 饰）联手出海寻找。倔强傲慢的杰克断然拒绝，阴差阳错进入了假杰克船长的巢穴，更由此邂逅了旧老情人安吉莉卡（佩妮洛普·克鲁兹 Penélope Cruz 饰）。各种因素促使迫使他加入了安吉莉卡的船队，更和她的父亲——臭名昭著海盗“黑胡子”（伊恩·麦柯肖恩 Ian McShane 饰）搅在了一起。新的冒险就在这纷乱中展开，无数的危险和诱惑等在大海的另一边……©豆瓣', '约翰尼·德普', '罗伯·马歇尔', 7.8, 349191, 'tt1298650', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p995422651.jpg', 0.3, 2.6, 27.9, 45.6, 23.6, '0.145938,0.132964,-0.703469,0.439409,0.106329,-0.437575,0.693699,0.273735,-0.362997,0.021901,0.125557,0.663056,-0.176278,-0.039233,0.406555,0.267219,-0.711449,-0.357969,-0.009907,-0.202753,-0.099751,-0.388382,-0.461256,-0.274368,-0.083320,-0.315620,0.478098,0.073246,-0.056593,0.466079,0.444839,0.389170,-0.120267,0.343604,-0.206351,0.182178,0.372781,-0.167354,-0.239786,0.282329,0.034586,-0.076880,0.126689,0.065888,0.138035,0.255461,0.492120,-0.485370,0.302499,-0.016997,-0.025161,-0.215061,0.026484,0.033313,0.313853,-0.203805,-0.091708,0.102996,-0.108916,-0.154447,0.123502,0.019764,-0.428990,0.237116,0.043511,0.311307,-0.466957,0.142740,-0.182801,0.192680,0.197434,-0.230552,0.166441,0.360277,0.262505,0.033108,0.117616,0.063678,-0.447248,0.303528,0.399302,-0.113312,0.019786,-0.034414,-0.166770,-0.224607,0.079709,-0.061730,-0.471317,-0.178412,0.596049,-0.297382,0.006865,0.468033,-0.799512,-0.064122,-0.460845,-0.048858,-0.115873,-0.054868,0.032018,-0.820267,-0.023574,-0.295672,0.176557,0.003555,0.013555,-0.029597,0.389142,-0.521553,0.337502,0.536598,0.343815,-0.076853,0.508192,0.039193,0.108395,-0.291803,-0.037947,0.581745,0.345003,0.291168,0.258655,0.377885,0.192227,-0.272038,-0.257121,0.312873', '3178770', '1297659', '14