INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3230023', '新邻里联防', '喜剧', '埃文（本·斯蒂勒 Ben Stiller 饰）是镇上的一个商店经理，对社区的事务也十分积极。然而商店保安却遭遇了意外谋杀，当地警察却无心追查，埃文的生活就此被打乱，他决心自己找出凶手。埃文将目光投向了邻里街坊，并与同样在生活中受挫的鲍勃（文斯·沃恩 Vince Vaughn 饰）、富兰克林（乔纳·希尔 Jonah Hill 饰）和贾马克思（理查德·艾欧阿德 Richard Ayoade 饰）四人组成了邻里联防组，每天在镇上巡逻，当然也借此理由偶尔放纵。在一次驾车巡逻时，他们意外地发现了一个奇怪的金属球，与此同时，镇上也出现了几起神秘死亡事件，联防组在被一只外来生物攻击时制服了它，得知外星人已经入侵小镇，并且通过偷窃人类皮囊来伪装成人，施展攻势。联防组方知行动已经迫在眉睫但却雾里看花，因为小镇上的任何一个人都可能是外星人，然而更可怕的是，外星人的最终目的竟然是毁灭整个地球。得知这一切的联防组能否凭四人之力粉碎外星人的阴谋呢……', '乔纳·希尔', '阿吉瓦·沙弗尔', 6.2, 7644, 'tt1298649', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1589718933.jpg', 2.9, 15.5, 56.2, 19.4, 6, '0.290898,-0.077353,-0.566473,0.360963,-0.145705,-0.044823,0.577782,0.040024,-0.553243,-0.333999,0.110591,0.654176,-0.118373,-0.101453,0.049183,-0.126997,-0.207651,-0.506515,0.013192,-0.175105,-0.394096,-0.350268,-0.393509,-0.551741,0.236661,-0.226047,0.304073,0.284306,-0.362054,0.341297,0.227199,0.473388,-0.242464,0.679476,-0.038966,-0.097323,0.116147,-0.258038,0.024366,0.042563,-0.265368,-0.334301,-0.143111,0.339812,0.022427,0.597856,0.768136,-0.204471,-0.254463,-0.128280,0.139657,-0.235753,0.075043,0.159151,0.450007,-0.101205,0.071695,0.149486,0.058577,-0.135383,0.123498,0.075673,-0.715035,-0.023618,0.076417,0.035419,-0.365684,0.192572,-0.003696,0.088621,-0.263641,-0.278607,0.342016,0.278383,0.443758,0.054458,0.019634,-0.175416,-0.581009,-0.033977,0.579805,-0.010205,-0.351890,0.209872,-0.273244,-0.527934,-0.334884,-0.044034,-0.109004,0.092550,0.360491,0.143486,-0.114625,0.134130,-0.767053,-0.014375,-0.471932,-0.078879,-0.286011,-0.384817,-0.022698,-0.834193,0.149894,-0.093413,-0.458293,0.226694,-0.032098,0.091007,0.412259,-0.629260,0.057813,0.738844,0.227365,-0.324555,0.541122,-0.070813,0.193375,-0.251982,-0.218143,0.017746,0.317208,0.462630,0.133822,0.319218,0.050054,-0.211157,