INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3230115', '极限特工3：终极回归', '动作', '当Triple X项目的创始人吉布森（塞缪尔·杰克逊饰）被杀害了的时候，美国国安局特工马珂（托妮·科莱特饰）决定请回自假死后一直被政府跟踪的桑德·凯奇（范·迪塞尔饰）。为了给吉布森报仇，同意回归，招募了一个新的Triple X团队，人员包括狙击手阿黛尔·沃尔夫（露比·罗丝饰），特技驾驶员火炬泰尼逊（罗伊·麦克凯恩饰）、夜店DJ 尼克斯（吴亦凡饰），还有计算机分析师贝基（妮娜·杜波夫饰）。桑德·凯奇团队针对的坏特工们包括头目项（甄子丹饰）、致命杀手赛琳娜·昂格尔（迪皮卡·帕度柯妮饰）、武术专家塔隆（托尼·贾饰），还有武器专家霍克（迈克尔·比斯平饰）。但当两个团队相遇时，突然发现事情并不是看上去的那样，有可能两拨人的目标是一致的。此时此刻，这两只Triple X队伍为了阻止未知的敌人，必须携手合作', '范·迪塞尔', 'D·J·卡卢索', 5.6, 109682, 'tt1293847', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2411445511.jpg', 8.3, 27.2, 44.1, 15, 5.4, '0.360674,-0.174017,-0.336224,0.335270,0.022767,-0.358200,0.363265,0.090976,-0.648490,-0.496668,0.294811,0.707411,0.116800,-0.133142,0.226662,-0.140383,-0.426011,-0.546927,-0.209111,-0.210739,-0.278786,-0.684980,-0.184330,-0.403624,0.054592,-0.256062,0.384653,-0.216633,-0.113725,0.479024,0.545644,0.622083,0.161186,0.186502,0.317464,-0.094022,0.693705,-0.421473,-0.483672,0.260153,-0.003253,0.268673,-0.190783,0.007608,0.172947,0.405080,0.260379,-0.124357,0.246361,-0.298674,-0.028854,-0.263895,0.315261,-0.128778,0.466994,-0.142520,0.068599,0.196589,0.131162,0.112158,0.202822,-0.091625,-0.809680,0.146004,0.270107,0.199502,-0.425576,0.078015,-0.384786,0.167891,0.267400,0.007976,0.094435,0.414376,0.570532,-0.022900,0.108210,0.067630,-0.420127,0.103876,0.379457,-0.030672,-0.143278,0.026055,-0.165008,-0.575401,-0.182855,-0.058192,-0.186917,0.170220,0.554510,-0.036552,0.122930,0.142925,-0.550798,-0.199408,-0.264946,-0.121895,-0.249069,-0.401690,0.114571,-0.948296,0.188864,0.013151,-0.189825,0.130479,-0.090088,0.019177,0.543258,-0.773786,0.051875,0.643787,0.067901,-0.335813,0.423586,0.044111,0.233751,-0.431243,-0.271231,0.138549,0.431711,0.176669,-0.002580,0.380084,0.149152,-0.508133,-0.118776,0.109783', '2028645', '25723905', '6517421', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3230121', '最后一支歌', '剧情', '根据畅销小说家尼古拉斯·斯帕克斯的同名小说改编的。父母的离婚让17岁的维罗妮卡（麦莉·赛勒斯 Miley Cyrus 饰）始终不能释怀。她曾是远近闻名的钢琴神童，可在父亲搬到泰碧岛上生活之后，就拒绝弹钢琴，并且不再和父亲说话。为化解父女之间的矛盾，母亲带着她一起到岛上和父亲共度夏天。父亲史蒂夫（格雷戈·金尼尔 Greg Kinnear 饰）是一位钢琴教师，在海岸的小镇上过着平静的生活，为当地教堂创作音乐。刚到达泰碧岛的时候，维罗妮卡对一切都充满了恐惧和敌意，连父女二人都无法有很好的交流。而在当地极受欢迎的帅哥维尔布雷克里（利亚姆·海姆斯沃斯 Liam Hemsworth 饰）也吃了闭门羹。不过在一起看护海龟巢穴之后，维罗妮卡改变了自己的敌对态度，这两个年轻人也开始慢慢坠入爱河。渐渐解开自己心结的维罗妮卡开始尝试着用钢琴和音乐来和自己的父亲沟通，而她不知道的是，史蒂夫这个时候已经罹患了不治之症……', '麦莉·赛勒斯', '朱莉·安妮·罗宾逊', 7, 13205, 'tt1294226', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453581645.jpg', 1.2, 6.8, 43.9, 35, 13.1, '0.371206,-0.011205,-0.816317,0.689353,-0.114607,-0.514119,1.022309,0.214004,-0.419794,-0.139522,-0.044341,0.946664,-0.126709,0.435497,0.232653,0.208036,-0.492391,-0.765175,0.114852,-0.203074,-0.396700,-0.673916,-0.225263,-0.060594,-0.257175,-0.487002,0.466516,-0.069944,-0.121427,0.317246,0.238157,0.120463,0.027760,0.516982,-0.293416,0.028723,0.097088,0.106835,-0.250774,0.149583,0.184893,-0.025640,-0.197714,0.117155,0.194207,0.351929,0.496068,-0.205306,0.011976,0.236850,0.151865,-0.271429,0.023347,0.123793,0.271875,-0.058065,0.352717,0.127498,-0.294791,-0.064908,0.009752,-0.068604,-0.561879,0.097205,-0.078507,0.234404,-0.734096,0.520433,-0.060667,-0.238091,0.180052,-0.310518,0.278783,0.260884,0.170608,0.407595,-0.200239,-0.092240,-0.450900,0.199612,0.732782,0.051929,-0.203748,0.442958,-0.268839,-0.413746,-0.095129,-0.197047,-0.668767,-0.106805,0.048844,0.110983,-0.267352,0.164928,-0.559625,-0.094039,-0.130109,-0.208891,0.084495,-0.505034,0.083772,-0.654401,-0.367445,-0.626507,-0.379460,-0.044862,0.070175,-0.326924,0.796445,-1.010529,0.428094,0.402341,0.225339,-0.256946,0.727342,0.233247,0.113950,-0.151553,-0.102502,0.307007,-0.078693,0.258505,0.325599,0.542183,0.234847,0.113424,-0.461794,0.77924