INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3230125', '稻草狗', '惊悚', '大卫（詹姆斯·麦斯登 James Marsden 饰）是一位小有名气的剧作家，为了能有更好的创作环境，大卫携爱妻艾米（凯特·波茨沃斯 Kate Bosworth 饰）回到了风景宜人的南方老家。老家清新的空气和闲散的生活让两个疲惫的城市人感到十分的新奇，而在这靓丽的风景之下，原住民们对这对初来乍到的夫妻却并不能算得上友好。秉着息事宁人的态度，大卫对来自外界的种种歧视选择了默默忍受，甚至在妻子被一名当地的建筑工人设计强暴之后，他也只是希望能够大事化小小事化了。可是，大卫的一味忍让换来的却是变本加厉的欺负，当一群“野蛮人”试图闯入他家时，曾经懦弱的大卫选择了拿起武器，为了保卫自己最后的家园而战。©豆瓣', '詹姆斯·麦斯登', '罗德·拉里', 6.5, 6773, 'tt0999913', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1326450265.jpg', 1.9, 11.6, 54.1, 25.3, 7.1, '0.395194,-0.013330,-0.638746,0.788427,-0.355700,-0.299859,0.798722,0.348192,-0.680029,-0.258372,0.220076,0.949938,0.002092,0.129080,0.144377,0.016369,-0.268454,-0.558252,-0.141064,-0.142931,-0.178134,-0.212279,-0.230419,-0.336687,-0.329208,-0.174383,0.471176,0.120387,-0.344790,0.438266,0.318981,0.412835,0.208024,0.409073,-0.453244,-0.183773,-0.074481,-0.012374,-0.455599,0.173794,0.010788,-0.020609,-0.200456,0.403227,0.066942,0.329700,0.774630,-0.209957,-0.343782,-0.037109,0.245880,-0.099374,0.268042,0.222485,-0.024068,-0.218610,0.082842,0.059929,-0.174014,-0.054126,0.160098,-0.027117,-1.089652,0.114002,0.114275,0.067050,-0.632208,0.632015,0.032777,-0.293460,0.008276,-0.319934,0.125344,0.309627,0.124370,0.460075,-0.188560,0.142855,-0.545088,0.087440,0.726487,0.155168,-0.321563,0.376521,-0.743816,-0.270261,0.200958,-0.416031,-0.819537,-0.277459,0.170243,0.009976,-0.031789,0.109108,-0.707580,0.132267,-0.160610,-0.278881,0.102116,-0.589883,-0.071000,-0.563547,-0.031162,-0.553763,-0.333353,0.099585,-0.003423,-0.265667,0.782406,-0.845537,0.162709,0.679511,0.271862,-0.542927,0.605174,0.414608,0.116104,0.014527,-0.396076,0.376183,0.187202,0.347901,0.127460,0.318447,-0.078316,-0.233954,-0.402759,0.461059', '1793491', '26678784', '30163500', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3230148', '死亡之雪', '喜剧', '就读于医科大学的维加德（Lasse Valdal 饰）及好友们驱车前往厄克斯尼湾附近的雪山，计划与其先行到达那里的女友莎拉（Ane Dahl Torp 饰）会合一同度假。当晚，他们从一个流浪汉（Bjørn Sundquist 饰）那里听到流传在此地的一个恐怖传说：二战期间，一支德国部队驻扎这里，他们从当地人手中大肆搜刮金银财宝，手段残酷，贪婪无度，但在战争结束前夕该部队却被愤怒的民众杀死，只有为首的赫尔措格指挥官（Ørjan Gamst 饰）极少数几个人躲进了雪山之中。年轻人们对此当然嗤之以鼻，但随着一盒财宝的出现，埋藏在雪中的纳粹僵尸开始一一复活，准备夺回一曾属于他们的财宝……©豆瓣', '维加·霍尔', '托米·维尔科拉', 6.1, 12234, 'tt1278340', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1511135273.jpg', 4.3, 18.5, 51.9, 18.6, 6.7, '0.424365,0.280153,-0.832793,0.432792,0.222602,0.076582,0.508856,-0.077048,-0.462716,-0.359363,0.273457,0.541514,0.018744,0.026059,0.303966,-0.117462,-0.587188,-0.474768,0.024143,-0.355233,-0.346531,-0.117214,-0.248921,-0.393757,-0.118680,-0.330416,0.585623,0.491891,-0.002161,0.676416,0.154758,0.569623,-0.431370,0.192184,-0.169885,-0.304919,0.313068,-0.266681,-0.298971,0.465512,-0.426848,-0.024338,-0.174737,-0.092736,0.093890,0.180866,0.717485,-0.281749,0.009188,-0.024662,-0.036107,-0.190050,-0.133795,0.317422,0.428275,-0.015610,0.087870,0.127927,-0.211343,0.278799,-0.047556,-0.127886,-0.473850,-0.168769,-0.056961,0.279632,-0.483450,0.386603,-0.015937,0.162005,0.016241,-0.199471,0.274806,0.361490,-0.098972,0.238782,-0.041404,-0.167451,-0.655489,0.088560,0.671386,-0.380275,0.120417,-0.158518,0.114294,-0.414320,0.031350,0.013316,-0.273317,-0.059367,0.226437,-0.067761,0.010171,0.241217,-0.876849,0.015184,-0.364998,-0.210531,0.224279,-0.037512,-0.351637,-0.760022,0.199158,-0.041983,-0.207244,0.311690,0.055333,0.213235,0.805783,-0.472916,0.245646,0.301390,0.298315,-0.366591,0.405940,-0.241414,0.186343,-0.037859,-0.160022,0.380918,0.444489,0.148342,0.143243,0.269733,-0.183623,-0.413489,-0.278219,0.253733', '3147969', '26290398', '1856675', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3230155', '偷心女盗', '喜剧', '潘妮（瑞贝尔·威尔森 Rebel Wilson 饰）拥有聪慧过人的头脑，却遗憾心宽体胖，因此在行骗的道路上屡屡碰壁。一次偶然中，她遇见了另一个名为约瑟芬（安妮·海瑟薇 Anne Hathaway 饰）的同行，约瑟芬肤白如雪发洁如缎，就连身位同性的潘妮也忍不住多看两眼。在经历了一番死缠烂打之后，约瑟芬答应收潘妮为徒。一次偶然中，潘妮和约瑟芬邂逅了一个名为托马斯（艾利克斯·夏普 Alex Sharp 饰）的英俊男人，这个男人正在为自己的企划寻找合伙人。两个女人决定来一场比赛，看看谁能够获得托马斯的信任，可随着计划一步一步的深入后，她们发现，托马斯并不是表面上看起来的那么呆。©豆瓣', '安妮·海瑟薇', '克里斯·艾迪生', 5.8, 22541, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2547930491.jpg', 3.7, 24.9, 51.9, 14.9, 4.6, '0.299256,0.077507,-0.696378,0.754203,-0.186652,-0.709288,0.680296,-0.028165,-0.440061,-0.330391,0.229633,0.819459,-0.488017,0.030091,0.253412,0.159714,-0.255207,-0.592858,0.187585,-0.217216,-0.448112,-0.402643,-0.154498,-0.069349,-0.101402,-0.158424,0.608376,0.060839,0.008855,0.511395,0.492357,0.138617,0.251128,0.248204,-0.154362,-0.099352,0.093943,-0.036400,-0.187065,0.486890,0.159380,-0.014070,-0.314750,0.180341,0.017648,0.323998,0.555173,-0.347300,-0.089841,-0.133252,0.431705,0.149059,0.115135,-0.004213,0.043858,-0.156101,0.116950,0.219291,-0.355434,-0.073210,0.130324,-0.012854,-0.472174,0.101547,0.011486,0.321551,-0.563782,0.274563,0.055776,-0.208982,-0.008058,-0.284826,-0.232591,0.213607,0.359191,0.099114,-0.030466,0.136307,-0.197989,-0.067084,0.478238,0.459707,-0.071353,0.657726,-0.074009,-0.376668,0.139554,-0.024536,-0.480055,0.166974,0.238646,0.027872,-0.002192,0.061146,-0.592310,0.026760,-0.501531,0.101463,-0.095501,-0.449573,-0.127054,-0.526361,-0.154641,-0.357116,-0.476719,0.125382,-0.124391,-0.510314,0.399361,-0.795192,-0.015049,0.596649,0.142348,-0.355134,0.621021,0.177940,0.191089,-0.169463,-0.091027,0.406716,0.078574,-0.065274,0.049843,0.506175,-0.074575,-0.203761,-0.387982,0.320769', '1414808', '1299556', '1307755', '1309080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3230165', '一夜迷情', '剧情', '迈克（萨姆·沃辛顿 Sam Worthington 饰）和乔安娜（凯拉·耐特丽 Keira Knightley 饰）是一对令人羡慕的年轻夫妻，迈克拥有安稳工作、乔安娜是自由作家，二人居于曼克顿的时尚住宅，生活无忧。两人出席迈克的工作派时，乔安娜发现新来的女同事罗拉（伊娃·门德斯 Eva Mendes 饰）对丈夫态度暧昧，心情不佳，而迈克对妻子反应亦不以为然。没过多久，迈克和罗拉一起去外地出差，同时心神不安的乔安娜则在曼哈顿街头巧遇了曾经深爱过的旧情人艾力克斯（吉约姆·卡内 Guillaume Canet 饰）。在这一夜，迈克能够抵抗住美丽罗拉诱惑？乔安娜又会不会和艾力克斯旧情复燃？精神外遇或肉体外遇，哪一种出轨方式对婚姻杀伤力最大？这一对伴侣是否可以回到原来平静的生活？©豆瓣', '凯拉·奈特莉', '玛西·塔吉丁', 7.2, 40828, 'tt1294688', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1072349940.jpg', 0.5, 4.2, 41.2, 42, 12.1, '-0.004961,-0.206574,-0.565373,0.588910,-0.086437,-0.401396,0.790555,0.242583,-0.543012,-0.502100,-0.131279,0.681560,-0.304588,0.599904,0.492289,0.194906,-0.474111,-0.545061,0.203434,0.057702,-0.278928,-0.663378,-0.084842,-0.429835,0.120704,-0.288409,0.151258,-0.184967,0.003096,0.539106,0.422699,0.412266,-0.179479,0.320861,-0.021161,0.060553,0.249334,0.036052,-0.574818,0.169487,0.381812,0.144479,-0.004721,0.088926,0.322474,0.024454,0.507177,-0.037870,-0.030821,0.043339,0.190618,0.117820,0.327071,0.215733,0.099876,-0.339215,0.208408,-0.083818,-0.171455,0.054311,0.391440,-0.047388,-0.463713,0.242097,-0.086509,0.058670,-0.323890,0.421751,-0.188152,-0.059551,-0.060793,-0.198092,0.095658,0.567980,0.313269,0.432959,-0.002315,0.244481,-0.298927,-0.054625,0.582145,0.242739,-0.049019,0.574617,-0.516974,-0.383928,-0.228932,0.101948,-0.690884,-0.208361,0.363104,-0.029771,0.199639,0.180155,-0.429034,-0.024782,-0.142241,0.266093,-0.071601,-0.271191,0.169244,-0.769372,-0.142331,-0.743172,-0.196258,0.120114,-0.028282,-0.195037,0.465369,-0.917058,0.173749,0.132023,0.514141,-0.541794,0.586262,0.251894,0.037065,-0.345590,0.041301,0.799022,-0.021691,-0.095714,0.192833,0.100765,0.110955,0.173900,-0.137919,0.482357', '1945337', '2002744', '1293077', '1299556');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3230195', '国家代表', '剧情', '本片围绕五位原本对跳台滑雪一无所知的少年，讲述了一段为争取申奥举办地而刻苦训练见证彼此成长的青春励志故事。1996年，为了承办冬季奥运会，韩国全罗北道抚州正在紧锣密鼓地筹备着。然而国际奥委会发来通知，由于抚州从来没有参与跳台滑雪项目，若没有队伍参加滑雪比赛将取消举办资格。组织委员会一时间乱作一团，他们决定立即组建跳台滑雪国家队。慌乱之中，他们临时召集了五位对跳台滑雪一无所知的“国家代表”：从小被美国人收养回国寻找生母的鲍勃（河正宇 饰），性格冲动的俱乐部服务生洪哲（金东旭 饰），对父亲言听计从的懦弱男孩在北（崔在焕 饰），以及想借机逃过兵役的七久（金基石 饰）和他的弟弟锋久（李在应 饰）。在不合格的前任儿童滑雪教练方钟三（成东日 饰）的带领下，五位性格迥异的少年开始了一番艰苦训练。©豆瓣', '河正宇', '金容华', 7.8, 8291, 'tt1298648', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p617514687.jpg', 0.4, 2.5, 24.4, 50.1, 22.6, '-0.005949,-0.180586,-0.707686,0.628577,-0.031789,0.106114,0.083320,0.064325,-0.503319,-0.294659,0.096740,0.596664,-0.147082,0.100928,0.498588,-0.438626,-0.246397,-0.684239,-0.416083,0.015890,-0.293784,-0.602411,0.163536,-0.270419,-0.121093,-0.270209,0.711246,-0.064797,-0.147276,0.764785,0.425856,0.064845,0.009653,0.064735,-0.025796,-0.367738,0.332167,0.294561,-0.295038,0.239385,-0.280326,-0.217939,-0.349828,0.017464,0.314927,0.401931,0.550206,-0.168479,0.238726,-0.378593,0.087383,-0.089660,-0.011188,0.105104,0.395671,0.232029,0.053572,0.443077,0.012886,0.087250,-0.086380,-0.577409,-0.539533,0.119552,0.327656,-0.004539,-0.626451,0.544861,-0.123748,-0.007142,0.120111,-0.200363,-0.036593,0.478804,0.197922,0.262656,0.091652,0.085982,-0.181008,0.562115,0.780123,-0.143984,-0.059464,0.014902,0.004746,-0.384659,0.046802,-0.254985,-0.304939,0.035240,0.015833,0.038309,-0.084431,-0.133867,-0.376178,0.084777,0.003985,-0.606412,0.206268,-0.275423,0.173756,-0.774063,0.235012,-0.236728,-0.109552,-0.073649,-0.071833,-0.062236,0.828741,-0.936184,0.111483,0.366826,0.224410,-0.767260,0.540678,0.172173,0.190246,-0.419879,0.018624,0.128584,-0.053338,0.117440,-0.064789,0.272589,-0.120671,-0.260343,-0.181539,0.114522', '25922902', '1316589', '35030151', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3230459', '李米的猜想', '剧情', '出租车司机李米（周迅 饰）嘴里一直叨叨着神秘的数字，坐她车的乘客都得回答她一个问题：见过这个男人吗？李米的男友方文已经失踪四年，然而在这四年里又一直不停地给她写信告知近况，找不到恋人的李米把他的照片贴在杂志里让人辨认，每天生活在极大的折磨下。这天她载了一对从云南来昆明等待交易的毒贩子裘水天（王宝强 饰）和裘火贵，这对毒贩在交易时发现“接头人”莫名其妙坠桥而亡，慌张失措时又遇见回头找钱给他们的李米，仓皇上车的裘火贵企图从李米这里抢回损失的金钱回老家。李米利用时机报警，但随后裘水天拜托李米寻找自己的初恋小香而放走了她。这边坠桥的“接头人”撞上了马冰（邓超 饰）和菲菲（王柠 饰）的车头身亡，马冰和菲菲不由自主地牵扯到这宗命案里。正好被逮捕裘家兄弟的警察叶倾城（张涵予 饰）和李米发现了方文的踪迹——马冰和方文长得一模一样！只是马冰对于李米的相认十分淡漠，李米等了四年的，竟是这样一个结局吗？叶倾城亦开始怀疑马冰的真实身份。', '周迅', '曹保平', 8.1, 336579, 'tt1299370', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p499462449.jpg', 0.3, 1.8, 21, 48.6, 28.3, '0.358461,0.009150,-0.734050,0.588548,-0.206868,-0.225594,0.672437,0.075560,-0.405276,-0.145489,0.171782,0.589374,-0.264177,0.171506,0.328048,0.155439,-0.392612,-0.686491,0.118311,-0.151600,-0.459009,-0.405512,-0.215609,-0.321183,0.000825,0.151366,0.188658,-0.001682,-0.081860,0.701065,0.289663,0.020254,-0.103008,0.550907,-0.327288,0.320012,-0.100233,0.031273,0.018407,0.274822,0.207973,-0.431452,-0.064864,0.161664,-0.181032,0.521732,0.486873,-0.030587,-0.259020,0.202653,0.169925,-0.372803,0.031287,-0.031447,0.328810,-0.054170,0.244610,0.047408,-0.378770,-0.157427,0.203186,0.372827,-0.429725,0.221040,-0.127209,0.217685,-0.731756,0.440352,-0.218658,0.174458,0.157097,-0.207856,0.406539,0.378096,0.006730,0.361903,-0.315279,-0.178942,-0.470780,0.279499,0.379796,-0.035636,0.271273,0.363161,0.067776,-0.432500,-0.106446,0.181985,-0.395056,-0.033808,0.364642,-0.023601,-0.343017,0.001363,-0.619995,-0.128443,-0.108056,0.091019,-0.145804,-0.403367,-0.062793,-0.464619,-0.091507,-0.347811,-0.213787,0.260756,0.026851,-0.211828,0.407820,-0.425622,0.140829,0.460595,0.349852,-0.380575,0.568019,0.071231,-0.065275,-0.217869,-0.061398,-0.004722,0.200253,0.392274,0.281489,0.394991,-0.022192,-0.022947,-0.392356,0.283758', '3111650', '1293303', '1805685', '10355329');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3230460', '夺标', '动作', '30年代，中国正式第一次组队参加世运会，将派出69人的运动代表团及9名中国武术表演团。这个消息在武林掀起轩然大波，各门派为名额私下决斗。为了避免内耗，中央国术馆馆长张之江（于荣光 饰）决定海选世运会队员。其门下弟子张凤（张卫健 饰）和关树宝（谢苗 饰）苦练螳螂拳多年，渴望为国出战。同时，张凤希望通过拿到代表资格，打动心仪的女运动员雁羚（黄翠如 饰）。为了筹集旅费，世运队在街头义卖，却遭遇群雄踢馆，波折不断。在世运会选拔赛场上，张凤却要对阵关树宝，同室操戈，最终败下阵来，正当他闹情绪时，是雁翎的话语让他释怀，师兄弟重归于好。此时，河北鹰爪王安勇（徐向东 饰）来袭，鹰爪与螳螂之战即将上演……与此同时，在女子长跑比赛中，雁翎为了证明中国人的实力，拼劲全力，虽然力压洋人夺魁，却倒在了血泊之中。最终，张凤见到了奄奄一息的雁翎……©豆瓣', '张卫健', '徐小明', 5.4, 5114, 'tt1296068', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2371889898.jpg', 9.2, 29.4, 46.1, 11, 4.3, '-0.301168,0.217762,-0.471967,0.270726,0.283330,-0.153056,0.118995,-0.055922,-0.637020,-0.118851,0.479233,0.611558,-0.229355,0.051452,0.109424,-0.639179,0.073434,-0.790751,-0.088124,-0.035405,-0.069025,-0.260307,-0.121248,0.112660,-0.153822,-0.202834,0.663161,0.224897,-0.380922,0.855079,0.434835,-0.025290,-0.052113,0.239989,0.123264,-0.306873,0.167102,0.192579,-0.579629,0.078890,-0.282205,-0.297874,-0.654190,0.082324,0.131226,0.275549,0.607893,-0.147663,0.282241,-0.140411,-0.013404,-0.151613,-0.014815,0.084813,0.146442,0.132217,0.334478,0.113832,0.078200,0.047483,-0.156795,0.005112,-0.411223,0.169397,0.287378,0.192446,-0.380329,0.660348,-0.209594,0.248894,0.008666,-0.148633,-0.076225,0.394725,0.303211,0.043857,-0.162605,-0.070526,-0.257878,0.345552,0.824076,-0.176060,0.070634,-0.154056,0.089882,-0.384125,0.152907,-0.438996,-0.009550,-0.084082,0.309167,-0.038942,0.222042,0.033664,-0.242843,-0.036836,-0.005228,-0.016552,0.006120,-0.052863,0.206786,-0.600564,0.040647,0.057309,-0.153388,0.017021,0.056954,-0.110809,0.814552,-0.803873,0.021322,0.341564,0.204431,-0.325896,0.482738,0.199987,0.137112,-0.286027,-0.359353,0.003827,-0.087038,0.172340,-0.000359,0.154373,-0.146274,-0.373759,-0.219972,0.123726', '35030151', '26365262', '4202326', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3230462', '女人不坏', '喜剧', '泛泛（周迅 饰）天资聪慧，却局限于实验室内。她不善于与男人交流，甚至被男人碰一下都会立时僵硬。精于专研人体科学的她发明了一样秘密武器——费洛蒙，只要把这种东西装在身上，就可以让异性趋之若鹜。铁菱（桂纶镁 饰）是个另类摇滚少女，爱好打拳击，副业写网络小说。从小迷恋天皇巨 星X，并渐渐把他想象成自己的男友，每天形影不离。唐露（张雨绮 饰）才貌双全，是大广场投资公司的执行总裁。她所遇到的男人，没有一个不对她顶礼膜拜，视她为梦中情人。从不对男人动心的唐露只希望人们明白，她得到的一切是靠她的才华，不是她的外表。生活在一个城市的三个女人，各怀梦想，各怀绝技。一场即将到来的拍卖会，一个即将被拆迁的音乐村，悄悄的把她们的命运交织在一起。©豆瓣', '周迅', '徐克', 6, 130915, 'tt1037146', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p484207298.jpg', 4.8, 19.3, 51.7, 19.5, 4.7, '0.433077,0.037003,-0.602369,0.605529,-0.508916,0.138967,0.787278,-0.024300,-0.456626,-0.133440,0.241639,0.780207,-0.305578,0.176273,-0.197799,0.137586,0.022727,-0.773080,-0.191570,-0.101216,-0.033822,-0.257821,-0.125053,-0.173091,-0.316089,-0.234204,0.661439,-0.038905,-0.204869,0.043517,0.421930,0.067127,0.110932,0.569430,-0.343690,-0.230108,0.006103,0.026420,0.018266,0.120327,-0.121593,0.004450,-0.024824,0.244599,-0.284015,-0.017426,0.667721,-0.263715,-0.059953,-0.357687,0.301816,0.001052,0.015531,0.158100,0.133384,-0.105468,0.240899,0.180155,-0.186007,0.032038,0.281429,-0.033984,-0.788256,-0.047438,0.320881,0.140207,-0.611170,0.489274,-0.066958,-0.162461,-0.023584,-0.221217,0.155765,0.158238,0.439507,0.340618,-0.078555,0.039033,-0.468272,0.457559,0.713257,0.236694,-0.237602,0.646362,-0.393924,-0.427718,-0.166916,-0.188809,-0.583754,-0.039470,0.064067,-0.151100,-0.196281,0.098404,-0.453085,0.108364,0.076815,-0.209602,0.139670,-0.745229,-0.100012,-0.404600,-0.114424,-0.489637,-0.363711,0.034631,0.180038,-0.402198,1.008657,-1.011207,0.053399,0.696056,0.171800,-0.479454,0.906138,0.030266,-0.268500,-0.187955,-0.072018,0.224752,-0.009334,0.022002,-0.092846,0.729582,0.050126,0.052720,-0.206460,0.705068', '30162520', '2053515', '1309161', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3231686', '巴黎谍影', '喜剧', '法国青年瑞斯（乔纳森•莱斯•梅耶斯 Jonathan Rhys Meyers 饰）在大使馆中工作，同时他还是美国情报部门的见习人员，精明强干的瑞斯对“换车牌”，加窃听器之类的任务自然是驾轻就熟，但是他很快迎来了真正的挑战——配合探员瓦克斯（约翰•特拉沃塔 John Travolta 饰）在巴黎的行动。瓦克斯作风强硬，举止粗暴。恍如漫画中走出的美国英雄，甫一下飞机，便咬住了毒品的线索一路大开杀戒，先后与华人、巴基斯坦和黑人帮派连番激战……瑞斯对神奇的瓦克斯目瞪口呆之余，也渐渐跟上了他的节奏。任务接近尾声之时，两人意外发现瑞斯居然也是恐怖分子的目标人物之一，原来恐怖分子们以瑞斯为突破口，试图刺杀赴法访问的美国高官，于是这对临时搭档，迅速整备出发……©豆瓣', '约翰·特拉沃尔塔', '皮埃尔·莫瑞尔', 6.5, 12075, 'tt1179034', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2203667657.jpg', 1.8, 10, 56.5, 26.1, 5.5, '0.386765,-0.111190,-0.611604,0.463199,-0.058576,-0.302020,0.421015,0.036851,-0.623505,-0.025007,0.341274,0.786858,-0.166570,-0.255828,0.493858,-0.120269,-0.745042,-0.922382,-0.074464,-0.225359,-0.278038,-0.355970,-0.363438,-0.267145,0.050289,-0.376626,0.311473,-0.068441,-0.084890,0.615588,0.273787,0.501442,-0.169583,0.512502,0.064093,-0.182703,0.655756,-0.441835,-0.219878,0.243402,-0.065875,-0.050707,-0.333985,0.108768,0.145038,0.654336,0.419412,-0.129398,-0.045551,-0.219120,0.060410,-0.243878,0.074567,0.124517,0.318506,0.129584,0.249017,0.226693,0.002868,0.315201,-0.047181,-0.118031,-0.587709,0.169895,-0.033949,0.038560,-0.353912,0.314223,-0.409199,-0.225438,0.119532,-0.306620,0.113172,0.577432,0.370234,0.145452,-0.066139,0.042686,-0.247569,0.017487,0.277853,0.305343,-0.329798,0.207082,-0.003717,-0.605617,0.090825,-0.177967,-0.070718,-0.188841,0.490098,0.055394,0.121410,0.307504,-0.725666,-0.082316,-0.552958,-0.339276,-0.338757,-0.365392,-0.010156,-0.953182,0.061402,-0.380197,-0.197667,0.069545,0.123535,0.151016,0.510691,-0.753320,-0.126561,0.548038,0.343585,-0.222518,0.291532,-0.171161,0.039829,-0.228496,-0.161847,0.028612,0.195889,0.550409,0.097679,0.502881,0.034249,-0.414990,-0.168619,0.424351', '25723905', '20274039', '2075345', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3231724', '狼灾记', '剧情', '两千多年前，汉王朝为抗击外族入侵，派兵镇守边陲。将军张安良（庹宗华 饰）率部活捉了外族的王子，希望借人质来诱敌。部下陆沈康（小田切让 饰）生性善良，抗拒血腥屠杀，还养幼狼为伴。但是，张安良对陆沈康颇为器重。一场激战后，张安良负伤离队，命令陆沈康统帅三军。由于大雪封山，陆沈康只得在卡雷村安营扎寨。他在帐中意外发现了一个异族女子（李美琪 Maggie Q 饰），两人发生争执。陆沈康一时失控，强奸了她，并将其秘密留在帐中。通过接触，两人慢慢产生了感情。女子讲了一个人变成狼的传说：公狼与母狼交配时，如果被人偷窥到，他们会一直追逐偷窥者，直到他死。这个传说会不会一语成谶，导致两人私情败露呢……本片根据日本作家井上靖小说改编，是田壮壮首度执导历史巨制，王志文为小田切让配音。©豆瓣', '小田切让', '田壮壮', 4.4, 8553, 'tt1300169', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p708990164.jpg', 26.2, 39.6, 25.7, 6.4, 2.2, '-0.027888,0.073562,-0.546799,0.508413,0.253085,0.119446,0.601571,0.080438,-0.611294,-0.269367,0.237275,0.440811,-0.082997,-0.217751,0.194662,-0.237399,-0.240750,-0.528143,-0.147349,0.024641,-0.114408,-0.065030,-0.077076,-0.367112,-0.191815,-0.374111,0.762373,0.190408,-0.367935,0.364445,0.276193,0.238734,-0.272376,0.473196,0.011417,0.154725,-0.023034,-0.094371,-0.146667,0.337066,-0.323030,-0.282645,-0.193407,0.018853,-0.348798,0.231050,0.703098,-0.463039,-0.261576,-0.281042,0.221457,-0.374443,-0.019746,0.060088,0.443042,-0.101029,0.242420,0.280605,-0.175406,0.040525,-0.074765,0.144842,-0.407506,-0.040701,-0.046555,0.204822,-0.451423,0.303983,0.048925,0.038034,0.191091,-0.141540,0.128395,0.356968,0.476997,0.015458,0.109633,-0.025154,-0.379009,0.241930,0.656814,-0.224351,0.004572,0.027628,0.101023,-0.560221,0.098841,-0.237865,-0.366284,0.129095,0.187147,-0.185548,-0.162759,0.337210,-0.480722,-0.293290,-0.395344,0.134353,0.050515,-0.316046,0.071333,-0.301786,-0.175694,-0.082133,-0.188578,0.167668,0.166679,-0.087907,0.424970,-0.661396,0.129934,0.551524,0.313536,-0.531256,0.323222,0.211026,-0.104787,-0.053563,0.189830,0.309648,0.304846,0.071871,0.220259,0.175157,-0.030814,-0.025009,-0.222853,0.066969', '1293265', '35030151', '1301022', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3231740', '侠探杰克', '动作', '影片根据“英国惊悚小说天王”李查德的小说《完美嫌犯》改编。六发子弹，五名死者，神秘枪手在闹市区制造了一起惨案让整个城市都陷入了恐慌。所有的证据都指向了前军队狙击手詹姆斯·巴尔（约瑟夫·斯科拉 Joseph Sikora 饰）。但他坚持自己的清白并要求把老相识 杰克· 理查尔（汤姆·克鲁斯 Tom Cruise 饰）找来，两人曾同在军队中服役。随着杰克调查的深入，他发现了更大的谜团，炮制这场惨案的真凶似乎另有其人，而别有用心的幕后黑手抓走了巴尔 ，只留下杰克一人探明真相。六发子弹中有一发漏空的子弹是杀手故意放空的。为了了解狙击手的工作，杰克特意来到了狙击手的训练营找到了一个叫做萨缪尔·卡什（罗伯特·杜瓦尔 Robert Duvall 饰）的教练。在卡什和巴尔妹妹以及律师的帮助下，杰克渐渐走进了事件的中心位置，一个关于苏联改造营和俄罗斯黑帮的秘密也慢慢浮出水面……', '汤姆·克鲁斯', '克里斯托弗·麦奎里', 6.3, 68488, 'tt0790724', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1740079049.jpg', 2.4, 13.7, 54.1, 23.9, 5.9, '0.184502,-0.144396,-0.488847,0.597239,-0.088956,-0.231866,0.777320,-0.133127,-0.394273,-0.275638,0.276939,0.489762,0.048491,-0.035463,0.138155,-0.104940,-0.518457,-0.731058,-0.119019,-0.281152,-0.360877,-0.765636,-0.571458,-0.512838,0.203559,-0.215656,0.374797,-0.006750,-0.234626,0.174669,0.256538,0.390089,-0.110185,0.244770,0.076670,0.082213,0.313559,-0.363617,-0.422855,0.213442,-0.012260,-0.392022,0.024515,0.160474,-0.045203,0.587655,0.559993,-0.301647,0.027635,-0.050152,0.042438,-0.245764,0.075626,-0.027119,0.378915,0.001346,0.127168,0.222150,-0.085976,0.096775,0.041661,0.038874,-0.717845,0.072608,0.125081,0.303180,-0.476404,0.231092,-0.449459,0.126335,0.141381,-0.168475,0.357299,0.303047,0.300654,0.007828,-0.275091,-0.010641,-0.404698,0.250111,0.468658,-0.107077,-0.137254,-0.017714,0.020702,-0.505200,-0.122050,0.082177,-0.048479,0.083220,0.652201,-0.174798,0.076802,0.342559,-0.476839,-0.145723,-0.311441,-0.369208,-0.209921,-0.286451,-0.007037,-0.688991,-0.191309,-0.016923,-0.178061,0.048452,-0.055020,-0.080565,0.522740,-0.462759,0.170883,0.619505,0.040867,-0.258618,0.395382,-0.167441,0.138407,-0.181558,-0.070592,0.156225,0.344252,0.461380,0.204252,0.493238,-0.032930,-0.395271,-0.361229,0.237750', '1307442', '1316693', '3170961', '26636537');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3231742', '钢铁侠3', '动作', '自纽约事件以来，托尼·斯塔克（小罗伯特·唐尼 Robert Downey Jr. 饰）为前所未有的焦虑症所困扰。他疯狂投入钢铁侠升级版的研发，为此废寝忘食，甚至忽略了女友佩珀·波茨（格温妮斯·帕特洛 Gwyneth Paltrow 饰）的感受。与此同时，臭名昭著的恐怖头目曼达林（本·金斯利 Ben Kingsley 饰）制造了一连串的爆炸袭击事件，托尼当年最忠诚的保镖即在最近的一次袭击中身负重伤。未过多久，托尼、佩珀以及曾与他有过一面之缘的女植物学家玛雅（丽贝卡·豪尔 Rebecca Hall 饰）在家中遭到猛烈的炮火袭击，几乎丧命，而这一切似乎都与22年前那名偶然邂逅的科学家阿尔德里奇·基连（盖·皮尔斯 Guy Pearce 饰）及其终极生物的研究有关。即使有精密先进的铠甲护身，也无法排遣发自心底的焦虑。被击碎一切的托尼，如何穿越来自地狱的熊熊烈火……', '小罗伯特·唐尼', '沙恩·布莱克', 7.8, 406578, 'tt1300854', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1955027201.jpg', 0.5, 2.4, 26.1, 46, 24.9, '0.097286,-0.234615,-0.859047,0.580567,-0.005763,-0.066770,0.821023,-0.165723,-0.442579,-0.683426,0.538097,0.606509,-0.397767,-0.047373,0.148661,-0.088008,-0.044704,-0.413062,-0.155601,-0.182006,-0.460650,-0.323946,-0.616983,-0.323818,0.099782,-0.590721,0.489738,0.039320,-0.352466,0.302798,0.238858,0.833173,-0.051224,0.466173,0.159093,-0.068848,0.069595,-0.010878,-0.211354,0.002839,0.031002,-0.236557,0.204849,0.239482,-0.135940,0.344780,0.443790,-0.606337,0.034235,-0.182297,0.467530,-0.147937,0.217729,0.203681,0.298943,0.107700,-0.001463,0.119850,-0.182069,-0.093772,0.256015,0.130150,-0.868206,-0.172110,0.031112,-0.081025,-0.392861,0.278675,-0.153580,0.206137,0.021289,0.012273,0.146916,0.350724,0.167328,0.312003,-0.176328,0.199627,-0.143770,0.184088,0.653543,-0.131905,-0.403865,0.165523,-0.191479,-0.245234,-0.136255,-0.189510,-0.529883,0.075988,0.175240,0.157344,0.014700,0.665573,-0.557522,-0.075798,-0.419279,-0.056070,-0.194435,-0.083678,-0.248018,-0.888430,-0.109942,-0.438491,-0.140850,-0.034011,0.083242,-0.034798,0.482114,-0.692673,0.365098,0.410698,0.045514,-0.028701,0.335635,-0.114047,0.074984,-0.066532,-0.216094,0.466430,0.266008,0.125785,0.129015,0.283509,0.176931,-0.201121,-0.169063,0.504998', '25828589', '