INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3233635', '功夫熊猫2', '喜剧', '上一部中，熊猫阿宝（杰克·布莱克 Jack Black 配音）功成名就，成为名震四方的神龙大侠。平日里他随同师傅（达斯汀·霍夫曼 Dustin Hoffman 配音）以及盖世五侠：悍娇虎 （安吉丽娜·朱莉 Angelina Jolie 配音）、猴王（成龙 Jackie Chan 配音）、快螳螂（塞斯·罗根 Seth Rogen 配音）、俏小龙（刘玉玲 Lucy Liu 配音）、灵鹤（大卫·克罗斯 David Cross 配音）在和平谷修炼，生活悠哉游哉。这一日，一伙恶徒闯入山谷抢夺金属材料，在与他们交手中阿宝意外产生幻觉，由此对自己的身世感到疑惑。另一方面，恶徒的魁首白孔雀沈王爷（加里·奥德曼 Gary Oldman 配音）正图谋闯入王宫，称霸全中国。新的正邪大战拉开序幕，阿宝他们面临前所未有的挑战……©豆瓣', '杰克·布莱克', '吕寅荣', 8, 418855, 'tt1302011', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p877183898.jpg', 0.2, 1.3, 21, 51.3, 26.2, '-0.006308,0.045636,-0.320895,0.432071,0.310307,-0.247481,0.460072,-0.021021,-0.452306,-0.410608,0.265988,0.512513,-0.261264,-0.018569,0.163502,-0.149799,-0.150670,-0.251081,-0.176139,-0.042391,0.237369,0.016336,-0.411359,-0.267633,0.044974,-0.131299,0.573473,-0.164574,-0.448455,0.550592,0.262482,0.126574,-0.348720,0.103185,0.105608,0.276954,0.272076,0.070144,-0.323821,0.099445,-0.205724,0.066481,-0.096434,0.115383,-0.076599,0.054098,0.345048,-0.336847,-0.001615,-0.277969,0.182071,-0.197884,-0.087583,0.008998,0.218790,-0.010689,0.223205,-0.002413,0.218706,-0.068899,-0.370262,-0.170716,-0.376642,0.125669,-0.059024,0.427973,0.097679,0.041567,-0.050196,0.179358,0.259525,-0.192509,-0.060028,0.103898,0.509268,0.029645,0.190995,0.142704,-0.366495,0.275356,0.547828,-0.248753,0.181880,-0.221818,0.247586,-0.321383,0.096600,-0.176235,-0.472239,-0.201310,0.438392,-0.350051,0.312074,0.387564,-0.342480,-0.010454,-0.125652,-0.034466,-0.266746,0.012998,0.136835,-0.776192,-0.162796,-0.223709,0.004945,-0.395278,0.258336,-0.558180,0.464555,-0.816543,0.310437,0.108309,0.047292,-0.055567,0.267839,-0.134374,0.196928,-0.380736,-0.232353,0.371410,-0.008942,0.150699,-0.009204,0.199860,0.145357,0.157431,-0.284139,0.417795', '2369613', '20274039', '25723905', '1316589'