INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3233761', '宿醉', '喜剧', '道格（贾斯汀•巴萨 Justin Bartha 饰）即将与女友结婚。婚礼前两天，道格与朋友菲尔（布莱德利•库珀 Bradley Cooper 饰）、西德（艾德•赫尔姆斯 Ed Helms 饰）和阿兰（扎克•加利费安纳基斯 Zach Galifianakis 饰）从洛杉矶驱车前往赌城拉斯维加斯为道格举办婚前单身派对，入住凯撒宫豪华套房。一晚过后，三人发现道格失踪，浴室里出现一只老虎，衣橱中多了一个婴儿，西德缺了一颗牙，窗外塔尖上插着席梦思床垫，菲尔戴着医院手环，西德口袋里有一张800美金收据，而他们的车也不知为何变成了警车。三人惊慌失措，完全无法记起昨晚发生过什么，却必须在24小时之内迅速解决谜团找到道格返回洛杉矶……©豆瓣', '布莱德利·库珀', '托德·菲利普斯', 7.7, 225164, 'tt1119646', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p455238724.jpg', 0.6, 3, 28.1, 47.9, 20.5, '0.195903,0.368904,-0.520218,0.250097,0.245664,-0.375229,0.849415,0.265991,-0.101497,-0.217595,-0.036286,0.511612,-0.382550,0.437001,0.510883,0.192271,-0.637173,-0.494836,0.156447,-0.416617,-0.501065,-0.441134,-0.164507,-0.077862,0.239991,0.046150,-0.014690,0.058430,0.334493,0.577296,0.555905,0.320305,-0.192020,0.269383,0.133366,-0.107624,0.199708,-0.067530,-0.214249,0.254585,0.058335,0.154320,-0.075817,0.103063,0.373114,0.290274,0.504399,-0.127659,0.124897,-0.179135,0.184585,0.268775,-0.044951,0.036926,0.314449,0.101128,0.073345,0.086424,-0.051311,0.180395,0.446269,-0.152383,0.112471,0.216041,-0.316048,0.142830,-0.604295,0.195382,-0.662812,0.008136,-0.029513,-0.495058,0.074426,0.324998,0.105150,0.110418,0.174567,0.004964,-0.788145,-0.202759,0.096499,-0.113201,-0.064507,0.217740,0.173287,-0.378847,0.094187,0.257467,-0.230308,-0.128120,0.401413,-0.123722,0.099334,-0.107171,-0.354524,-0.148931,-0.424390,-0.322093,0.125137,-0.014151,-0.271739,-0.800736,-0.104148,0.031915,-0.131869,0.111703,-0.157727,0.256315,-0.082533,-0.559668,0.206557,0.068069,0.398646,0.195245,0.444210,-0.321282,0.487958,-0.073437,0.140435,0.136817,0.120848,0.258910,0.019441,0.326377,-0.064571,-0.113976,-0.447756,0.422098', '1301686', '3183490', '10466639', '1394176');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3236520', '香奈儿', '传记', '香奈儿（巴博拉·伯布洛瓦 Barbora Bobulova 饰）六岁时母亲去世，父亲留下5个孩子离去，后来她进入修女院学校学了一门针线技巧。1905年，22岁的她当上咖啡厅歌手，有了艺名Coco，在不同的歌 厅和咖啡厅卖唱维生。在这段时间内，她结交了两名老主顾：英国工业家和富有的军官。成为他们的情人后，让她有经济能力开设自己的店子。1910年，在巴黎开设了一家女装帽店子 ，凭着非凡的针线技巧，缝制出一顶又一顶款式简洁耐看的帽子。两位情人为她介绍了不少名流客人。当时女士们已厌倦了花巧的饰边，所以Chanel简洁的帽子深得她们的喜爱。然而，做帽子已不能满足她对时装事业的雄心，她开始进军高级订制服的领域。1914年，开设了两家时装店，影响后世深远的时装品牌Chanel宣告正式诞生。©豆瓣', 'Daria Baykalova', '克里斯丁·杜瓦', 7.9, 32999, 'tt1094661', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p781926821.jpg', 0.2, 1.7, 23.9, 50.6, 23.7, '0.437314,0.209152,-0.266806,0.429105,-0.263340,-0.174865,0.453532,0.362391,-0.526251,-0.503098,0.331671,0.850861,-0.092279,0.101033,0.144254,0.064883,-0.174482,-0.620515,0.269943,-0.158518,-0.270086,-0.168994,-0.077778,-0.196732,-0.154855,-0.448645,0.246359,0.015044,-0.096400,0.424869,0.369165,-0.010852,0.262451,0.157345,-0.366222,-0.092631,0.280601,0.058606,-0.074825,0.215393,-0.193772,-0.260260,-0.070748,-0.038253,0.211366,0.206155,0.712922,0.138806,-0.064273,-0.007699,0.608432,0.304501,-0.102562,0.180784,0.247386,0.219734,0.029802,0.120184,-0.321591,0.106054,-0.128503,-0.229915,-0.536164,0.019348,0.261717,-0.213236,-0.686425,0.717873,-0.239254,-0.123418,-0.119623,-0.522666,-0.024471,0.109027,0.107971,0.381595,0.129369,0.300611,-0.753033,0.512172,0.561173,0.007930,-0.097404,0.188643,-0.431956,-0.411811,-0.060224,-0.339501,-0.391832,-0.143286,0.272041,-0.212012,0.099594,-0.178544,-0.688255,-0.124707,-0.050752,-0.298276,0.373193,-0.248095,-0.133493,-0.562444,-0.124016,-0.556899,-0.252589,-0.124689,0.177169,-0.155125,0.900301,-0.868647,0.143396,0.267990,0.314421,-0.550718,1.089004,-0.253006,0.538703,0.013918,-0.318516,0.138011,-0.192520,0.106853,0.091359,0.624592,-0.095923,-0.277971,-0.224857,0.200350', '1308609', '1292720', '3055049', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3236904', '自闭历程', '剧情', '本片根据自幼患有自闭症的美国动物科学家、畜牧学博士——天宝·葛兰汀（克莱尔·丹尼斯 Claire Danes饰）的个人自传改编而成，讲述天宝与众不同的成长经历。天宝四岁时被医生诊断为自闭症，母亲尝试多种方法让天宝开口说话。为了让天宝拥有正常人的生活，妈妈忍痛送她去一间寄宿学校念书。在这里，天宝认识了开启她天赋大门的恩师卡洛克博士。在恩师的帮助下，天宝顺利考入了大学。临上大学前的暑假，天宝来到姨妈家的农场度假。自此，天宝对牲畜产生了浓厚的兴趣。在大学里天宝制作“挤压机器”来平复紧张情绪。毕业后，天宝继续从事畜牧业的研究学习，设计出大大提高屠宰率且更为人道的屠宰方式。天宝以她独有的方式去认知世界，“像牲畜一样的思考”，在自闭症研讨会上大声的讲出自己的亲身经历……©豆瓣', '克莱尔·丹妮丝', '米克·杰克逊', 8.9, 64169, 'tt1278469', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p583188016.jpg', 0.1, 0.5, 7.5, 39.1, 52.7, '0.375543,-0.052465,-0.546534,0.219448,-0.177572,-0.447766,0.154812,0.199406,-0.752590,-0.333916,0.388545,0.466051,-0.038195,-0.085096,0.033052,-0.071678,-0.327078,-0.258511,0.222733,-0.300469,0.004223,-0.309769,-0.108990,0.020671,0.079559,-0.702633,0.264175,-0.363831,-0.249711,0.742904,-0.402615,0.228797,0.280163,-0.109217,-0.038859,0.027468,0.130597,0.066399,-0.521681,0.486140,0.099166,0.262263,-0.105901,-0.333468,-0.052621,0.005236,0.557318,-0.115131,-0.199656,-0.096939,0.499894,0.230754,-0.258929,0.272064,0.220888,0.644584,0.119568,0.398034,-0.427163,0.409013,-0.213675,0.042980,-0.412890,-0.146346,0.091019,0.295739,-0.428265,0.359091,0.173684,-0.202824,0.107708,-0.670397,0.024316,0.231326,0.119481,0.781453,-0.361253,0.252234,-0.127048,0.195832,0.357037,-0.525831,-0.051016,0.223780,-0.229623,-0.234398,0.366133,-0.264655,-0.298518,0.085380,-0.068191,0.004866,-0.360706,0.059221,-0.696447,0.100330,-0.117276,-0.187440,0.175920,0.059921,-0.222283,-0.750582,0.020340,-0.025595,-0.158855,-0.779130,0.209957,-0.529768,0.867708,-0.917865,0.302138,0.464495,0.554204,-0.307090,0.473244,-0.231346,0.045389,-0.281362,-0.319737,0.129215,-0.269325,0.894818,-0.426332,0.512248,0.371093,-0.271240,-0.422106,0.422943', '1307811', '3044878', '25922902', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3238076', '处刑人2', '剧情', '波士顿，一位深受爱戴的牧师神秘被杀，子弹交错穿过脑壳，死相极为惨烈，传言处刑人所为。负责此案的依旧是警察格林利、达菲和多利，但他们对此一筹莫展。幸有智慧性感的FBI特工尤妮斯・布鲁姆（朱莉•本茨 Julie Benz 饰）破解了处刑人的杀人手法。因10年前波士顿血案，异卵双生兄弟康纳（肖恩•派特里克•弗兰纳里 Sean Patrick Flanery 饰）和墨菲（诺曼•瑞杜斯 Norman Reedus 饰），随领袖父亲诺亚（比利•康诺利 Billy Connolly 饰）隐居在爱尔兰的乡村。此案一出，两兄弟削发明志，重新出山。期间，他们收服了墨西哥人罗密欧（小克利夫顿•克林斯 Clifton Collins Jr. 饰）。后者凭借机灵的头脑、出众的拳脚，战胜了人高马大的对手。虽然将对手置于死地有些残酷，但是兄弟俩觉得对味，并设计拉他入伙。这组搭档与美女特工都踏上征讨处刑人的危险之旅……', '肖恩·派特里克·弗兰纳里', '特洛伊·达菲', 7.1, 17228, 'tt1300851', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2643248098.jpg', 1.1, 7.2, 40.7, 36.5, 14.5, '0.142673,-0.322758,-0.287878,0.291474,-0.000141,-0.157053,0.481655,0.106306,-0.435586,-0.245724,0.244932,0.636679,-0.077775,-0.260315,0.491798,-0.109311,-0.384637,-0.467661,0.103331,-0.055914,-0.081355,-0.581872,-0.275591,-0.275347,0.138964,-0.395635,0.388111,-0.079917,-0.114660,0.590327,0.230683,0.380123,-0.135431,0.013806,-0.041237,-0.063401,0.129597,-0.208691,-0.357832,0.114141,-0.155579,0.050147,-0.231071,0.068097,0.023801,0.543417,0.258321,-0.387373,0.204378,-0.093323,0.099376,-0.302252,-0.024409,0.078605,0.358484,-0.083946,0.017262,0.170177,0.090198,0.026880,0.135740,-0.068729,-0.611551,0.257522,0.264741,-0.075805,-0.429044,0.315402,-0.182464,0.150579,-0.126813,-0.067164,0.042762,0.137863,0.365573,0.314654,0.364234,0.063894,-0.347309,-0.133278,0.544500,-0.090495,-0.129232,-0.205628,-0.230854,-0.547994,-0.039452,-0.464869,-0.237755,-0.007114,0.576189,-0.144660,0.232118,0.306953,-0.453011,-0.103451,-0.397157,0.235741,-0.227762,-0.269607,0.002364,-0.640627,0.040308,-0.353323,-0.149364,-0.074393,0.110402,-0.113500,0.444971,-0.554144,-0.052388,0.311879,0.314445,-0.159803,0.414303,0.145399,0.110974,-0.279060,-0.471968,0.360770,0.554752,-0.106561,0.245698,0.334068,-0.037429,-0.311168,-0.193276,0.124759', '11541282', '3147969', '1299851', '26930056');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3238087', '玩命追踪', '动作', '这座城市出现了一名绰号“Blitz”的连环杀人魔，他神出鬼没地杀害多名警官，而他的凶器只是一把锤子。没人知道他的踪迹，而他也因作案手法老练而使警方难以破案。嚣张的他更在每次作案前后都会和某报社负责犯罪版块的编辑邓洛浦（大卫·莫瑞瑟 David Morrissey 饰）报告杀人的细节，从而追求社会的关注。邓洛浦为了自己出名而没有通知警方，每次都能让警方试图封锁消息的计划破灭，也因此被警方注意。个性容易冲动火爆的警察布兰特（杰森·斯坦森 Jason Statham 饰）因正义感太强殴打嫌疑犯，屡次遭投诉、上报纸，上司颇为恼火。这一次，布兰特奉命追查这名凶手，面对凶残狂妄凶手的放肆挑衅，他决定要靠自己的双手，为这个社会伸张正义......©豆瓣', '杰森·斯坦森', '艾略特·莱斯特', 6.2, 25691, 'tt1297919', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1002600075.jpg', 2.5, 15.3, 55.6, 20.2, 6.3, '0.434060,-0.098580,-0.670648,0.602156,-0.423635,0.115149,0.576040,-0.019530,-0.560741,-0.256616,0.221921,0.462632,0.033932,-0.054245,0.066254,-0.155360,0.050301,-0.762597,0.006255,0.074915,-0.209503,-0.424307,-0.329450,-0.684859,-0.046700,0.011257,0.109787,0.158039,-0.487674,0.337568,0.516894,0.468681,0.208055,0.527729,-0.131434,-0.294186,0.186304,-0.338896,0.068828,0.134223,0.120943,-0.521325,0.033714,0.679942,-0.301951,0.597007,0.505680,0.087655,-0.434679,-0.168445,0.537069,-0.547792,0.149349,0.322865,0.608954,-0.235879,0.046683,0.244736,-0.232885,-0.169929,0.067207,0.015403,-1.161794,0.139872,0.002423,0.165612,-0.318818,0.105012,-0.404613,0.382300,-0.166113,-0.009755,0.050317,0.267469,0.359631,-0.078841,0.158372,-0.204187,-0.231812,0.221250,0.400208,-0.084789,-0.211457,-0.032432,-0.256823,-0.276446,-0.053384,-0.418812,-0.315449,-0.070258,0.492088,-0.248870,-0.397409,0.095640,-0.284794,-0.149387,-0.392530,0.052051,-0.452084,-0.184032,-0.271449,-0.547723,-0.032332,-0.334800,-0.239117,0.032342,0.041994,-0.133285,0.476202,-0.686057,0.017142,0.873531,0.245835,-0.882517,0.533460,0.392677,-0.280983,-0.140056,-0.348397,-0.018806,0.464970,0.458609,0.147638,0.175901,0.309590,-0.532942,-0.137791,0.269626', '35073886', '3785918', '3670447', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3239814', '中间人', '剧情', '杰克·哈里斯（卢克·威尔逊 Luke Wilson 饰）拥有美满的家庭和成功的事业，直到一次偶然的机会让他遇见韦恩（吉奥瓦尼·瑞比西 Giovanni Ribisi 饰）和巴克（盖布瑞·马赫特 Gabriel Macht 饰）。这两人一心想开发互联网色情行业但却始终不得要领，杰克看到了这个创意的前途，决意合伙经营。不久，三人就建立起了独家的色情门户网站，大赚特赚，甚至开始雇用自己的色情明星。然而杰克的妻子却十分反对他的事业，于是忙于吸金的杰克日渐与家庭疏远，并开始与色情艺人奥黛丽（劳拉·莱姆希 Laura Ramsey 饰）沉溺于肉体狂欢中。然而，随着网站效应日渐膨胀，恐怖分子和FBI竟同时盯上了杰克一行人，事情开始向戏剧性的方向发展，三人的网站也不再是赚钱那么简单了……©豆瓣', '卢克·威尔逊', '乔治·加洛', 7.2, 7605, 'tt1251757', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1480919755.jpg', 0.7, 3.7, 39.4, 46, 10.2, '0.227735,-0.009263,-0.753267,0.463707,0.255356,-0.578664,0.575097,0.178042,-0.506546,-0.132597,-0.171135,0.782786,-0.392524,0.019139,0.427325,0.048348,-0.362813,-0.734197,0.194365,-0.056480,0.087695,-0.487037,-0.244968,-0.562128,-0.250059,-0.205159,0.571839,0.140211,-0.192355,0.509214,0.283851,0.154065,0.032963,0.555430,0.080419,0.210034,0.196227,-0.053777,-0.339248,0.157188,0.163309,-0.104391,-0.194800,0.312654,0.148905,0.470439,0.410015,-0.207988,-0.071688,-0.197558,0.312020,-0.091217,-0.107760,-0.035563,0.179782,-0.038776,0.324937,0.328722,-0.095131,-0.107320,-0.016014,-0.161265,-0.791528,0.029864,0.004340,0.093892,-0.618428,0.189404,-0.215002,-0.163113,-0.049354,-0.279708,-0.051514,0.462771,0.331730,0.337424,-0.084348,0.051311,-0.629004,0.199992,0.412443,0.281412,-0.303894,0.668349,-0.157463,-0.341892,-0.290618,-0.142140,-0.196424,-0.282700,0.485802,0.170614,0.030575,0.374523,-0.820435,0.259795,-0.286463,-0.180882,0.101670,-0.319096,0.006399,-0.799594,-0.122481,-0.431183,-0.227769,0.104546,-0.119470,-0.391828,0.630082,-0.889398,-0.169539,0.508769,0.529385,-0.486933,0.456598,-0.046128,0.178232,-0.219019,-0.304545,0.000838,-0.173339,0.120698,0.172376,0.196341,0.149539,-0.499892,-0.059906,0.594707', '1783461', '1793491', '1299556', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3239892', '等到永远', '剧情', 'Emma（蕾切尔·比尔森 Rachel Bilson饰）和 Will（汤姆·斯图里奇 Tom Sturridge 饰）从小就是好朋友，但自从Emma离开家乡后，两人就再也没联系过。Emma后来成了一个演员，因为父亲病重的缘故回到了家乡。Emma都快忘记了Will，然而多年来Will却一直爱着Emma，并跟着Emma，一路上也没有工作，而是在路边表演戏法养活自己。Emma和Will见面了，她知道了Will一直以来对她的跟踪，让Will别再做这种事情了。Emma还向Will透露她对男友的背叛，她和另外一个男人偷情。后来，Emma的男朋友杀死了和Emma偷情的男人，同时也发现了Will一直跟踪Emma的事情，就把一切嫁祸到Will身上，Will只能接受警方调查。到底最后Will能否和他深爱的Emma在一起呢？©豆瓣', '蕾切尔·比尔森', '詹姆斯·基彻', 7.1, 9277, 'tt1296898', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p776174064.jpg', 1.5, 8, 41, 35.2, 14.3, '0.284080,-0.374125,-0.814634,0.636752,-0.353496,-0.670960,0.685194,-0.104267,-0.648603,-0.239819,-0.181013,0.905175,-0.153049,0.208436,0.128670,0.287629,-0.491236,-1.127745,0.220602,-0.329112,-0.491454,-0.560701,-0.089203,-0.129621,-0.069705,-0.199621,0.355216,-0.123768,-0.090390,0.428834,0.436087,-0.111543,-0.053306,0.918802,-0.139969,0.195758,0.047037,0.257904,-0.178522,0.271376,0.378720,-0.406444,-0.185552,0.421397,0.342813,0.430565,0.403065,-0.206709,-0.327451,0.063215,-0.103904,-0.163248,0.110779,0.129531,0.288027,-0.244185,0.553261,0.430586,-0.341994,-0.013176,-0.082583,0.203248,-0.734842,0.136027,-0.136079,-0.073081,-1.000456,0.350791,0.010849,-0.161264,0.144245,-0.547443,0.505930,0.435606,0.151121,0.465700,-0.375841,-0.098746,-0.525039,0.240446,0.843839,0.023133,0.057964,0.598116,0.162331,-0.201855,-0.258796,-0.167310,-0.431232,0.190783,-0.065665,0.166835,-0.516728,0.046155,-0.384562,-0.037064,-0.164000,-0.217897,0.156975,-0.729491,0.153682,-0.235112,-0.163952,-0.452020,-0.536916,0.349845,-0.116371,-0.344266,0.454566,-1.011482,0.422224,0.756733,0.567830,-0.985310,0.827944,0.484854,-0.079490,-0.018239,-0.014857,0.066520,0.107407,0.450820,0.362897,0.251722,0.378722,-0.204078,-0.388659,0.403409', '1306916', '1301022', '1418613', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3240208', '非常完美', '喜剧', '两年前，立志成为著名漫画家的女大学毕业生苏菲（章子怡 饰）突然罹患急性阑尾炎，英俊帅气的外科医生李杰夫（苏志燮 饰）为其手术，并迷上了眼前这个天真的女孩。接下来的日子里，两人陷入长久的热恋中。然而就在谈婚论嫁之时，他们的爱情却突遭变故。风情万种的女演员王菁菁（范冰冰 饰）迷上了杰夫，经过一番倒追攻势，杰夫最终拜倒在她的石榴裙下。惨遭出局的苏菲终日以泪洗面，长久无法摆脱旧日回忆的侵扰。另一方面，母亲（王姬 饰）又逼婚不断，令其颇为烦恼。在两位闺蜜陆小夕（林心如 饰）和李莉（姚晨 饰）的鼓励下，苏菲重拾信心，展开了一场赢回男友心的夺爱大作战。接下来的日子里，一连串爆笑的追逐战接连上演，而台湾摄影师常瑞（何润东 饰）又令战况扑朔迷离……©豆瓣', '章子怡', '金依萌', 5.9, 189190, 'tt1303833', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p482937086.jpg', 5, 21, 53.2, 17.2, 3.6, '-0.013311,0.070200,-0.534668,0.430719,0.255235,-0.245067,0.820003,0.001052,-0.322669,-0.245059,0.268961,0.419789,-0.597731,0.391027,0.452515,-0.222223,-0.314414,-0.765983,0.073298,0.115946,-0.136633,0.004859,-0.365935,-0.057394,-0.043623,-0.262800,0.688440,0.013305,0.013762,0.553088,0.425397,0.212917,0.059940,0.338952,0.166015,0.259818,0.047470,0.167119,-0.223223,0.074484,0.287044,-0.507911,-0.293255,0.041740,-0.057296,0.231725,0.707378,-0.280132,-0.061436,-0.174671,0.542598,-0.241023,-0.144763,0.177115,0.148757,0.032262,0.299725,0.052769,-0.314250,-0.004091,0.124479,-0.029779,-0.350509,0.298606,0.100595,0.043774,-0.392344,0.407664,-0.078891,0.154290,0.025127,-0.175728,-0.076640,0.406413,0.503640,0.338647,-0.291577,0.175382,-0.082612,0.455384,0.602273,0.363088,-0.309358,0.345820,-0.017371,-0.357626,-0.065787,-0.114393,-0.579794,-0.109274,0.303796,0.012488,0.019986,0.421403,-0.377239,0.059939,-0.439661,-0.054514,-0.212085,-0.141823,-0.282034,-0.609863,-0.194909,-0.390149,-0.323542,-0.028154,0.131501,-0.185869,0.629149,-0.739704,0.056237,0.115469,0.090155,-0.418103,0.252191,0.352461,0.227554,-0.108722,-0.312539,0.403609,-0.291652,0.182806,0.039808,0.340050,-0.366904,-0.054677,-0.387364,0.430686', '1432699', '6973376', '3811356', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3243344', '养子十五岁', '剧情', '身为同性爱人，格兰（古斯塔·斯卡斯加德 Gustaf Skarsgård 饰）和斯万（托克尔·彼特森 Torkel Petersson 饰）应该庆幸他们生在瑞典，因为这是世界上第七个承认同性恋婚姻的国家。随着感情的升温，他们觉得领养一个“爱情结晶”的时机到了。在申请屡次被拒绝之后，他们终于迎来了他们一岁半的小宝宝帕特里克（托马斯·柳恩格曼 Thomas Ljungman 饰），没想到，来到他们面前的，并非嗷嗷待哺的婴孩，却是一个浑身都充满了中二气息的少年。就这样，格兰与斯万和他们的“孩子”帕特里克开始了“幸福”的家庭生活。他们发现帕特里克不仅仅在个性上桀骜不驯，对于同性恋的态度也反感到令人发指。会有怎样尴尬而又温暖的故事在这三个男人之间上演呢？©豆瓣', '古斯塔·斯卡斯加德', '埃拉·列姆哈根', 8.1, 16726, 'tt1067733', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2365512421.jpg', 0.3, 1.1, 20, 52.2, 26.5, '0.329925,0.010525,-0.885522,0.542692,-0.183870,-0.185069,0.973156,0.169996,-0.568545,-0.131914,0.027718,0.953321,-0.404289,0.319702,0.446438,-0.018072,-0.368751,-0.599466,-0.183886,-0.332644,-0.422240,-0.471575,-0.128560,-0.281370,-0.040602,-0.302923,0.587709,-0.022336,0.015261,0.420925,0.441033,0.424059,0.172295,0.344772,-0.092903,0.208370,0.120679,0.146386,-0.127412,0.066039,0.047298,0.018191,-0.016525,0.275507,-0.047267,0.301079,0.577539,-0.407111,0.017119,-0.166642,0.241029,-0.234586,-0.109745,0.068464,0.171999,-0.224426,0.224526,0.159136,-0.147049,-0.132744,0.160429,-0.141141,-0.786060,0.377776,-0.018276,0.336994,-0.520508,0.454535,-0.053974,-0.306794,0.075222,-0.323684,0.069596,0.445760,0.196341,0.609219,-0.225827,-0.011115,-0.591963,-0.376840,0.709350,0.022131,-0.423143,0.373516,-0.396185,-0.490013,-0.048566,-0.144532,-0.498668,-0.157275,0.222216,0.101047,-0.113799,0.402054,-0.609893,0.048039,-0.181525,0.031079,0.021580,-0.553445,-0.067260,-0.411242,-0.212389,-0.534396,-0.587197,0.196552,0.001610,-0.416815,0.678479,-0.835565,0.203895,0.468150,0.393658,-0.377202,0.579247,0.203956,0.087514,-0.373525,-0.161357,0.461821,0.075341,-0.075876,0.325004,0.361882,-0.149147,0.137368,-0.190749,0.689181', '1292211', '24756472', '3111650', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3244128', '亲密', '剧情', '阿佩（林嘉欣 饰）在一间贸易公司的市场推广小组工作，小组组长是汤少（郑伊健 饰），贪玩的珠珠(活己岚饰)、羞涩的松仔(曾国祥 饰)、处事老练的球叔(骆应钧饰)也是小组同事。在小小办公室中日日相处，阿佩对汤少产生了不同于别人的情愫，而汤少却已有家室，对阿佩若即若离，阿佩也越来越深陷于这场还没开始的爱恋中，看不穿汤少的心意，也怀疑自己的爱恋。这一切到底是阿佩一厢情愿的单恋？还是两人的情投意合？凭借这部《亲密》林嘉欣夺得第3届韩国首尔忠武路电影展最佳女主角，岸西夺得15届香港电影评论学会奖最佳编剧奖和10届华语电影传媒大奖最佳新导演奖。©豆瓣', '林嘉欣', '岸西', 6.3, 12356, 'tt1303846', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p488206963.jpg', 3.6, 16.8, 48.8, 24.6, 6.3, '0.009938,-0.169927,-0.497827,0.600714,0.120979,-0.187280,0.399332,0.214981,-0.413799,0.009525,0.055386,0.685618,-0.303094,0.122533,0.091668,-0.183676,-0.316555,-0.769070,-0.370249,-0.203670,0.194972,-0.364415,-0.451335,0.173914,-0.185867,-0.010568,0.921768,-0.095501,-0.373831,0.435397,0.683842,-0.130789,-0.043539,0.428764,-0.060503,0.127255,0.335123,0.236255,-0.478636,0.106827,0.147972,-0.279143,-0.312233,-0.021785,0.320916,0.423221,0.689415,0.049573,-0.123171,0.125346,0.560430,-0.351195,-0.222760,-0.209930,0.388296,-0.005443,0.296323,0.198559,-0.145073,0.344759,-0.172578,-0.082220,-0.825578,0.104859,0.353857,0.204230,-0.409243,0.577664,-0.195628,-0.197332,0.064917,-0.227641,0.128053,0.304544,0.370389,0.191222,-0.100433,-0.106243,-0.228027,0.388742,0.489407,0.113105,-0.369800,0.622871,-0.169780,-0.675972,-0.024842,-0.116237,-0.412681,-0.067805,0.182677,0.002749,0.319959,0.064384,-0.573235,0.066182,0.285618,-0.227812,0.075427,-0.543039,0.292419,-0.564993,-0.309008,-0.571458,-0.292405,-0.189503,0.293844,-0.402349,0.610042,-0.897515,0.082510,0.307211,0.135376,-0.469130,0.873478,0.410932,-0.076602,-0.361956,-0.292583,0.090286,-0.445973,-0.157922,-0.054043,0.687307,0.050910,-0.272567,-0.305378,0.156244', '25880986', '4301278', '6101834', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3244162', '家有喜事2009', '喜剧', '余宝（郑中基 饰）的家姐余珠（吴君如 饰）性格强势，事业成功，著有多部宣传单身主义的畅销书。余珠的未嫁令弟弟颇为困扰，因为很据极为灵验的家训，余宝无法在姐姐成婚前确定自己的终身大事。经体会到爱情“天旋地转”之感的公司阿姨介绍，余宝请动爱情治疗师曹迪克（古天乐 饰）出面，帮助姐姐打开封闭的心锁。曹迪克成功接近余珠，并使其陷入了旋转的恋爱感觉。然而在曹迪克和余宝的一次千岛湖之行中，两人结识了豪放热情的龅牙珍（姚晨 饰）和温柔可爱的小敏（沈丽君 饰），并双双沉入爱河。与此同时，纠结难耐的余珠前往杭州探视曹迪克，在私家侦探柯男（黄百鸣 饰）的陪同下发现了事情的真相。不过幸运的是，每个人最终都找到了自己爱情的归宿……©豆瓣', '古天乐', '谷德昭', 5.5, 53204, 'tt1305854', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p815356766.jpg', 8.5, 27.4, 50, 11, 3.1, '0.043050,-0.050867,-0.531119,0.515044,-0.091870,-0.313932,0.706118,0.103409,-0.582362,-0.348520,-0.094443,0.513368,-0.291418,0.402745,0.388537,0.164338,-0.015645,-0.521688,0.123526,0.163591,-0.183127,-0.524202,-0.241441,-0.130614,-0.095851,-0.107655,0.482279,0.214510,-0.206105,0.470811,0.408985,0.261774,-0.160505,0.559140,0.095212,0.118075,-0.008647,0.085967,-0.306516,-0.051413,-0.082316,-0.069844,0.203619,0.131962,0.085700,0.299157,0.472455,-0.183031,-0.193825,0.204947,0.397690,-0.158895,-0.052779,0.179754,0.077972,0.249704,0.098148,0.048864,-0.323122,0.032035,0.098643,-0.011737,-0.509783,0.188853,0.302420,0.069377,-0.549128,0.390284,-0.040243,-0.107965,0.059779,-0.252944,0.101083,0.402188,0.294508,0.297989,-0.114450,0.168838,-0.325468,0.145524,0.422603,0.022743,-0.095136,0.444951,-0.248265,-0.576702,-0.063516,0.020042,-0.302479,-0.024097,0.324094,0.309725,-0.006404,0.066179,-0.459638,-0.224300,-0.059471,0.032224,0.014162,-0.409387,0.067822,-0.413809,-0.292337,-0.476024,-0.542385,-0.142247,-0.005089,-0.477142,0.523225,-0.699319,0.013977,0.289156,0.087117,-0.527419,0.736848,0.277975,-0.000489,-0.273974,-0.142362,0.603265,0.014961,0.196213,0.156758,0.248622,-0.299280,-0.019007,-0.469203,0.259979', '1302384', '25828521', '1292211', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('32491917', '我的喜马拉雅', '剧情', '电影以“时代楷模”卓嘎、央宗姐妹父女两代人爱国守边的先进事迹为题材，由中宣部电影局、电影频道、区党委宣传部联合打造，导演张馨执导。曾经在西藏玉麦乡只有桑杰曲巴一户人家。他们抵抗住环境恶劣、外敌骚扰、亲人病逝等艰难困境放牧戍边34年，如同格桑花一般扎根祖国雪域边陲，为祖国守住数千平方公里的国土。', '仁青顿珠', '张馨', 7.4, 3779, 'tt12752900', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2569207880.jpg', 1.6, 6, 34.2, 39.7, 18.5, '-0.381729,-0.366560,-0.558004,0.447095,0.424702,0.033874,-0.101658,0.287022,-0.545220,-0.029201,0.163280,0.336133,0.391385,-0.090329,-0.138765,-0.187186,-0.188407,-0.533601,0.079026,0.108729,0.173701,0.166736,-0.088042,-0.275220,-0.256743,-0.103626,0.701607,0.198197,-0.110583,0.073406,-0.083116,0.246101,-0.246123,-0.150148,-0.257110,-0.275833,-0.171936,-0.186869,-1.042965,0.185127,-0.605683,0.080416,-0.495958,-0.124456,-0.000616,0.334356,0.248181,-0.104378,0.066632,-0.465762,0.053333,-0.394552,0.067699,-0.148450,0.442209,-0.072117,0.170126,0.331673,-0.090915,-0.147479,-0.039418,-0.770941,-0.446520,-0.070885,0.321109,-0.091257,-0.780706,0.419666,0.225852,-0.114443,0.102862,-0.444770,0.225007,0.577933,0.212537,0.604887,-0.243946,0.232102,-0.074160,0.647591,0.802804,-0.384703,-0.355550,-0.135294,-0.196046,-0.362646,0.466933,-0.391561,-0.831270,0.095563,-0.328350,-0.265728,0.092447,0.212228,-0.450296,-0.123423,-0.099525,-0.088755,0.485323,-0.414607,0.092779,-0.396309,-0.157656,0.101937,0.152361,0.014477,0.290756,-0.064951,0.738385,-0.424202,0.078186,0.377154,0.587039,-0.513261,0.805459,0.106797,-0.044261,-0.177487,-0.068693,0.556815,-0.031011,0.362942,-0.021587,-0.415288,-0.476320,-0.064024,0.119569,0.269850', '1308035', '26410593', '6965615', '2080130');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('32493124', '悬崖之上', '剧情', '上世纪三十年代，四位曾在苏联接受特训的共产党特工组成任务小队，回国执行代号为“乌特拉”的秘密行动。由于叛徒的出卖，他们从跳伞降落的第一刻起， 就已置身于敌人布下的罗网之中。同志能否脱身，任务能否完成，雪一直下，立于“悬崖之上”的行动小组面临严峻考验。', '张译', '张艺谋', 7.6, 694331, 'tt11448076', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2636475385.jpg', 0.4, 2.7, 29.1, 53.1, 14.6, '0.217232,0.129630,-0.536786,0.575244,-0.236413,-0.144983,-0.155692,-0.193306,-0.332857,-0.241453,0.709672,0.333627,0.286747,-0.204724,0.436120,-0.159560,-0.375081,-0.831686,-0.630938,-0.170227,-0.759368,-0.577234,-0.135756,-0.063196,0.141559,-0.117013,1.207806,0.577418,-0.095447,-0.023042,0.402000,0.562817,-0.719349,0.167837,-0.027429,-0.668194,0.184442,-0.217469,-0.546960,0.421231,-0.604644,-0.237084,0.064935,-0.200367,0.131975,0.434246,0.683070,-0.429011,-0.215518,-0.406357,-0.033073,-0.519867,0.060902,-0.219059,0.572112,0.178582,-0.020037,0.453732,0.116806,0.223504,-0.648599,-0.493989,-0.610345,-0.111338,0.188983,0.040293,-0.644174,0.023383,-0.263131,0.530367,0.037810,-0.146223,-0.139373,0.744009,0.124281,0.335220,-0.199891,0.202454,-0.293660,-0.043853,0.849775,-0.243498,-0.274997,-0.527081,0.340068,-0.437931,-0.082762,-0.103027,0.254196,0.090784,0.008316,0.114140,0.036571,0.159483,-0.655198,0.163904,-0.505291,-0.335838,-0.083303,-0.332178,0.002694,-0.815280,0.230132,0.517008,-0.493095,0.463855,-0.103023,-0.351802,0.451926,-0.834323,0.688431,0.208491,0.173133,-0.077518,0.387426,0.333966,0.252148,-0.729285,0.170035,0.407295,0.038115,0.468619,-0.095672,0.027592,-0.305315,-0.133129,-0.310746,0.237767', '2369613', '3861846', '7051375', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('32493666', '追虎擒龙', '剧情', '影片讲述1973年，香港警黑勾结， 在英国人指使下贪污巨利，荼毒市民。港督成立廉政公署，最先两位检察官为黑白双煞 （古天乐、林家栋 饰）历尽千辛万苦调查权倾黑白两道的总华探长徐乐（吴镇宇 饰）及跛豪（梁家辉 饰），终把二人绳之以法的故事。', '古天乐', '王晶', 5, 64753, 'tt14466064', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2640758773.jpg', 8.4, 39.7, 45.3, 5.3, 1.3, '-0.354819,-0.288230,-0.013217,0.346547,0.533970,0.075423,0.161477,0.160426,-0.499113,-0.341883,0.284524,0.502599,-0.199178,-0.140602,0.391352,0.066521,-0.323095,-0.746899,-0.122888,0.117266,0.097486,-0.570070,-0.382828,-0.022264,-0.118438,-0.081353,0.274436,0.134757,-0.124050,0.338026,0.640471,0.022077,-0.482522,-0.329844,0.021114,0.243337,0.431388,-0.072633,-0.883030,-0.009721,-0.503317,-0.672803,-0.182088,-0.210137,-0.131389,0.177677,0.196249,-0.125872,0.153135,-0.130836,0.256378,-0.259917,-0.227645,-0.284261,0.356024,0.151637,0.542963,0.858068,-0.333945,0.003451,0.034922,0.083744,-0.308873,-0.186760,0.237214,0.233596,-0.123796,0.244949,-0.132895,0.479488,-0.070466,-0.021762,-0.127193,0.136171,0.046683,0.328548,0.133185,0.011637,-0.335958,0.659290,0.321763,0.030994,0.455500,-0.008206,0.179864,-0.390250,-0.152955,0.009759,0.027060,-0.245349,0.287899,-0.593310,0.128571,0.503532,-0.381168,-0.362031,-0.216961,0.279732,-0.078110,0.050372,0.178465,-0.616093,-0.437610,-0.323963,0.189540,0.081429,0.141051,-0.113734,0.329305,-0.127673,-0.040112,0.289190,-0.083179,-0.514847,0.279597,0.195337,0.030801,-0.387170,-0.437211,-0.089215,0.520935,-0.035996,0.300209,-0.111838,-0.200674,-0.503222,0.033051,-0.530096', '10726941', '27202818', '3275168', '27202819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3249742', '末日情缘', '喜剧', '地球将被一颗小行星撞击，还有三周就是世界末日了，人们各自用自己的方式度过最后的日子，有的忙着分手，有的忙着陪家人，有的忙着完成心愿。道格（史蒂夫·卡瑞尔 Steve Carell 饰）妻子第一时间跑掉了，留下他百无聊赖，恰好碰到女邻居佩妮（凯拉·耐特丽 Keira Knightley 饰）因为错过回家机票在窗下哭泣，两人就此结识。佩妮把错投递到他家的许多信还给道格，道格发现里面有几个月前初恋女友写来的，佩妮万分愧疚，决定帮助道格赶去见初恋女友一面，两人开车上路，一路相处甚欢，直到发现世界末日到来时，想陪在身边的人是彼此……©豆瓣', '史蒂夫·卡瑞尔', '劳伦·斯卡法莉娅', 6.4, 5747, 'tt1307068', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1604241900.jpg', 2, 16.6, 48.6, 24.7, 8.2, '0.119553,0.025215,-0.546070,0.277888,0.247967,-0.421536,0.626924,-0.058085,-0.369790,-0.224238,-0.064390,0.585026,-0.441209,0.462860,0.457792,-0.122828,-0.506790,-0.625775,0.163496,-0.279823,-0.475577,-0.351298,0.181846,0.095995,-0.154371,-0.208010,0.091997,-0.089071,0.375825,0.530528,0.315838,0.254760,-0.077676,0.419740,-0.246090,0.063969,-0.131435,-0.222344,-0.407732,0.262266,0.405524,-0.068861,-0.240271,-0.191119,0.258159,0.106244,0.601657,-0.123525,-0.145830,0.159300,0.278126,-0.268390,0.139179,-0.009035,0.236768,0.130146,-0.012253,0.056072,-0.379053,0.087799,0.420002,-0.071489,-0.267455,0.354983,-0.167559,0.204062,-0.695703,0.295807,-0.164291,-0.121170,0.221156,-0.619303,0.352705,0.609276,0.049542,0.182424,-0.137255,0.049926,-0.455388,-0.116421,0.616147,-0.021483,0.118280,0.280505,0.091891,0.054703,0.120056,0.022127,-0.389780,0.040474,0.264718,0.248529,-0.182613,-0.136292,-0.583479,-0.031449,-0.234642,-0.264332,0.307443,-0.567670,-0.214235,-0.827600,0.028897,-0.222563,-0.503475,0.184578,-0.067532,-0.283850,0.586098,-0.510130,0.241963,0.426428,0.623446,-0.233880,0.892746,0.051667,0.095464,-0.228946,0.362345,0.130986,-0.074730,0.249953,0.383099,0.227795,-0.044588,0.124733,-0.412300,0.323258', '3055049', '1306860', '3147969', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3250377', '即日启程', '剧情', '在塞浦路斯开餐馆的中年男人老崔（范伟 饰）回国跟妻子办离婚，却发现让自己后院起火的罪魁祸首是自己的朋友。老崔得知合伙人要卖掉塞浦路斯的餐馆，情场失意的老崔只想快点回到塞浦路斯挽救自己的事业。不料倒霉的事情并没有完，在老崔前往飞机场的途中，一个醉酒的女孩子小夏（居文沛 饰）忽然拦住了老崔的乘坐的出租车，好心的老崔本想只送小夏回家，没想后面却发生了一连串事情，搞到身无分文、护照失窍，曾至衣不遮体。情急之下，老崔只得和小夏合作，相互帮助，不料一波未平，一波又起，两人历经磨难，曾至还卷入到一场盗窃国宝的阴谋之中。在相处的过程中，两人的内心似乎也种下了一颗在渐渐发芽的种子……该片是“中影集团青年导演电影制作计划”启动的第一部影片。©豆瓣', '范伟', '刘江', 7.1, 47748, 'tt1307008', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1133234227.jpg', 1, 5.6, 41.2, 41.8, 10.5, '0.151161,-0.015098,-0.771276,0.467032,-0.012585,-0.558217,0.715863,0.066262,-0.331771,-0.457282,-0.145306,0.406336,-0.295916,0.458399,0.290727,0.018332,-0.316224,-0.455904,0.040297,0.058000,-0.432702,-0.489542,-0.168059,-0.229776,-0.180277,0.128457,0.460702,0.330295,-0.386991,0.107315,0.643320,0.023892,-0.160150,0.577399,-0.344760,0.421870,0.016183,0.217923,-0.314048,0.049958,0.378363,-0.461328,-0.441762,-0.084732,0.414181,0.458097,0.465807,-0.061882,-0.119305,0.310943,0.275129,-0.185636,0.084835,-0.155249,0.348535,0.059677,0.172996,-0.044409,-0.367059,0.138656,0.250741,-0.227361,-0.292092,0.319567,0.078647,-0.103631,-0.739613,0.089293,0.045255,0.353546,0.072058,-0.640072,0.323348,0.414902,0.233765,0.474715,-0.028356,0.105978,-0.674805,0.446550,0.927563,0.223728,-0.037572,0.479320,0.171652,-0.351361,-0.246375,-0.096018,-0.366184,0.008059,0.594464,-0.048710,-0.181516,0.162956,-0.409518,-0.254728,-0.141090,-0.051841,0.175012,-0.164732,0.151051,-0.432450,-0.112984,-0.235849,-0.033904,0.371127,0.093909,-0.156265,0.449525,-0.515037,0.186338,0.234168,-0.013124,-0.619133,0.535617,0.233989,0.101224,-0.115066,0.058224,-0.119239,0.243888,0.293489,0.404042,0.333072,-0.017975,-0.250197,-0.346198,0.218897', '1309125', '1303485', '1297710', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3250619', '棺木', '惊悚', '泰国当地流传着一个奇怪的风俗，生者只要在棺木里躺上一晚，就能欺骗死神，从而否极泰来，消除厄运。在澳洲长大的泰国籍男子克里斯（阿南达 饰）的未婚妻麻梨子遭到严重车祸，昏迷不醒，危在旦夕；香港女孩阿苏（莫文蔚 饰）即将走入婚礼殿堂，却发现自己患有肺癌，去日无多。当从电视上看到棺木仪式的相关报道后，这两个绝望之人有如抓到救命稻草，不约而同赶往仪式现场。经过漫长而恐慌的一夜，他们从棺木中走出。似乎得到上苍的眷顾，阿苏的肺癌奇迹般康复，麻梨子也从永恒的睡眠中苏醒。但是，世间从来没有免费的午餐，更何况他们修改了命运，换回来的却是……©豆瓣', '莫文蔚', '吕翼谋', 5.5, 6819, 'tt0460749', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1582250452.jpg', 6, 28.4, 52.2, 11.1, 2.2, '0.043414,0.275379,-0.777188,0.068491,0.108563,-0.227965,0.808798,0.097343,-0.503938,-0.170455,0.391726,0.597826,-0.409413,0.383825,0.225414,0.125509,-0.367132,-0.776017,0.012071,-0.104180,-0.694960,-0.039587,-0.151720,-0.052525,0.009375,-0.316866,0.558851,0.202879,0.035497,0.462796,0.067481,0.037805,-0.284528,0.462036,-0.346635,-0.001290,-0.019849,0.173471,-0.183699,0.248494,0.003340,-0.295638,-0.093127,0.217881,-0.128488,0.301672,0.482355,-0.415486,-0.198580,-0.145721,0.431639,-0.200000,-0.265649,0.335709,0.117425,0.116507,0.147810,0.077109,-0.190275,0.001964,-0.045009,-0.126252,-0.518730,-0.056522,-0.196008,0.511217,-0.491400,0.598424,0.057469,0.061457,-0.027797,-0.382409,0.398261,0.353966,0.081341,0.749611,-0.161036,-0.045084,-0.457409,0.179959,0.533319,-0.224555,-0.474662,0.428600,-0.098140,-0.539282,0.112540,0.057411,-0.325144,0.106730,0.359261,0.148061,-0.317297,0.137898,-0.384678,0.136635,-0.270364,-0.186867,-0.080981,0.044740,-0.175676,-0.727124,-0.032681,-0.067722,-0.246027,0.228136,0.211901,-0.310322,0.542327,-0.352164,0.647894,0.362411,0.090954,-0.158631,0.502672,-0.101681,0.046460,-0.120498,-0.038197,0.534066,0.019892,0.469468,0.151711,0.080976,-0.269032,0.169106,-0.570439,0.401712', '1478063', '30136177', '6753096', '25786077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3254242', '夜叉', '剧情', '现行法律体制下，犯罪分子们用各种方式逃脱法律制裁，人民对此无可奈何，然而一个神秘蒙面人“夜叉”突然出现，对那些逃脱惩罚的人渣施以鞭笞的私刑，润年企业主席也难逃夜叉制裁。从美国回港的警官华启伦（陈小春 饰）奉命抓捕夜叉，华选择即将退休的警察介哥（柯受良 饰）作为搭档。原来介哥当年与两名义子阿泰（古天乐 饰）、子年合称“旺角三鹰”，阿泰性格刚硬，嫉恶如仇，然而却在一次追索毒贩的任务中枪杀嫌疑人，导致失去公职。华启伦视阿泰为夜叉的真身，于是借介哥试图揭开事情真相。然而，华启伦和夜叉的对决，这才仅仅是开始……©豆瓣', '古天乐', '邱礼涛', 6.3, 4398, 'tt0833562', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2629196705.jpg', 1.4, 12.4, 62.6, 18, 5.7, '0.156606,-0.154674,-0.224135,0.459841,-0.120519,0.028311,0.503484,0.063507,-0.375634,-0.488545,0.550330,0.492069,0.086425,0.097456,0.240293,-0.204088,-0.047355,-0.687240,-0.108753,0.032245,-0.265171,-0.241153,-0.135868,-0.177720,0.024008,-0.146260,0.791530,0.008851,-0.239963,0.351436,0.553792,0.470114,-0.317929,0.275750,0.035268,-0.245680,0.263703,-0.258863,-0.355394,0.075508,0.069394,-0.542243,-0.046711,0.351271,-0.216503,0.537433,0.472879,-0.558508,-0.339108,-0.344612,0.230424,-0.649212,-0.343017,0.243774,0.333279,-0.058747,0.237724,0.416667,-0.002510,0.118073,0.109334,-0.047175,-0.447927,-0.067984,0.056476,0.132548,-0.248991,0.058031,-0.250374,0.310950,-0.132488,-0.131229,0.122170,0.160047,0.333622,0.205514,-0.191537,0.079182,-0.368333,0.024345,0.556285,-0.090428,-0.377689,-0.170814,0.020175,-0.520999,-0.044502,-0.473399,0.100233,-0.074047,0.153160,-0.003974,-0.185464,0.218794,-0.429026,-0.278489,-0.387681,0.194903,-0.248649,-0.111532,0.023317,-0.441245,-0.019674,-0.175261,-0.150997,0.207200,0.162242,-0.068023,0.537389,-0.678100,0.186814,0.274648,0.261367,-0.706260,0.289200,0.312400,0.033220,-0.373691,-0.141441,0.042797,0.401416,0.340155,0.092930,0.018721,0.067280,-0.467450,0.141428,0.070018', '1293265', '26759819', '1295746', '1307914');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3256172', '赤警威龙', '动作', '吉米·波波（西尔维斯特·史泰龙 Sylvester Stallone 饰）是一名混迹黑道、刀头舔血的杀手，他奉行不杀女人和儿童的原则，和合作长达六年的搭档路易斯·布兰查登（乔恩·塞达 Jon Seda 饰）将一个个渣滓送往地狱。在刺杀前恶德警察格雷利的行动中，吉米恻隐心动，冒险放走了一名女子。未过多久，路易斯在酒吧争执中遇害。警方根据女人的口供和路易斯的身份，顺藤摸瓜查到吉米。探员泰勒·科旺（姜成镐 饰）辗转与吉米接洽，谁知却遭到一伙不明身份之人的袭击。身受枪伤并且意外杀死警察的泰勒得到吉米的救助，这两个分出黑白两道的男人被迫联合在一起。而在接二连三的袭击背后，不为人知的阴谋正有条不紊地展开……©豆瓣', '西尔维斯特·史泰龙', '沃尔特·希尔', 5.9, 7981, 'tt1308729', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1865881239.jpg', 3.3, 21.2, 56.6, 13.9, 5, '0.387670,-0.159633,-0.624540,0.355803,-0.149390,-0.154957,0.594199,0.078083,-0.426231,-0.196205,0.469293,0.426616,-0.122565,0.007781,0.485662,-0.185677,-0.258917,-0.854250,-0.110586,-0.249713,-0.370955,-0.425343,-0.304266,-0.404627,0.051046,-0.243732,0.596839,-0.082294,-0.129404,0.541396,0.498398,0.481546,-0.464094,0.264587,-0.192140,-0.037488,0.346378,-0.263125,-0.232402,0.269149,-0.074895,-0.243282,-0.129158,-0.109058,-0.092242,0.663126,0.366254,-0.214253,0.114924,-0.078522,0.054084,-0.297450,0.052008,0.172875,0.550235,-0.047880,0.147879,0.218922,-0.168399,-0.146301,0.083159,0.060274,-0.665528,-0.021339,0.006364,0.572049,-0.647510,0.162584,-0.336832,0.061027,0.034698,-0.109597,0.016166,0.413879,0.225932,0.073955,0.186303,-0.030052,-0.568082,-0.157387,0.589986,0.013314,0.039725,-0.266434,-0.011123,-0.388248,-0.144187,-0.052999,-0.211311,-0.113402,0.434643,-0.238847,-0.061078,0.353822,-0.622367,-0.140042,-0.415921,0.239709,-0.172251,-0.229290,-0.222567,-0.892349,-0.176084,-0.164797,-0.095235,0.174233,0.125995,-0.138877,0.374491,-0.722155,0.224369,0.706655,0.286346,-0.284891,0.301829,0.202995,0.121542,-0.267184,-0.303439,0.265566,0.693937,-0.004744,0.124090,0.354684,-0.074268,-0.101994,-0.138869,-0.032503', '25723905', '3387546', '1307442', '26336253');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('32568661', '妈妈的神奇小子', '剧情', '电影根据残奥冠军苏桦伟真人真事改编。苏桦伟生来因黄疸病导致脑痉挛，无法正常站立行走。而苏妈（吴君如 饰）没有放弃，不仅帮助儿子站了起来，还发掘了他的跑步天赋，直到苏桦伟被残障田径队选中，夺得残奥会冠军并打破世界纪录，这对神奇母子的热血励志传奇开始家喻户晓。', '吴君如', '尹志文', 6.9, 16046, 'tt14892216', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2676932860.jpg', 0.6, 5.9, 50.6, 35.5, 7.4, '-0.219090,0.027774,-0.733021,0.396380,0.137240,-0.310163,0.243321,-0.129618,-0.554636,-0.218460,0.181363,0.693165,-0.434435,-0.035086,0.150624,-0.399946,-0.053157,-0.592648,-0.066831,0.246369,-0.239663,-0.302581,-0.170029,0.018798,-0.188516,-0.627722,0.648693,-0.029960,-0.564782,0.782218,0.422887,-0.191129,0.394448,-0.189497,-0.460516,0.058752,0.001829,0.177256,-0.041315,0.266289,0.056235,-0.175404,-0.036860,0.140424,-0.135493,0.122889,0.519901,-0.331776,0.112237,-0.196792,0.661779,-0.440029,-0.265747,0.033787,0.146964,0.279195,0.353715,0.206018,0.231713,0.451859,0.000794,-0.147725,-0.785196,0.137602,0.303454,0.150314,-0.323132,0.646401,-0.107419,-0.343254,0.037817,0.108420,0.236942,0.410831,0.553289,0.372323,-0.150644,0.133759,-0.301849,0.406687,0.643373,-0.217248,-0.446863,0.574368,-0.230540,-0.618901,0.164452,-0.562388,-0.252006,0.075441,0.226888,0.526995,0.111094,0.018989,-0.167014,0.428050,-0.098702,-0.168457,-0.040254,-0.230940,0.147041,-0.276135,-0.197625,0.069705,0.054951,0.008886,-0.331394,-0.582623,0.779652,-0.461479,0.134304,0.349623,0.254834,-0.326233,0.318952,-0.014983,-0.044104,-0.164167,-0.207509,0.514885,-0.198037,0.430570,-0.152291,0.170390,-0.095957,-0.245207,-0.473669,0.471448', '27602116', '25880986', '30391300', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('32579501', '反贪风暴5：最终章', '动作', 'ICAC首席调查主任陆志廉（古天乐 饰）与总调查主任程德明（郑嘉颖 饰）共同调查走私贪污案，意外发现另一起涉及人口贩卖的海关贪腐大案。此案与恐袭集团首脑King及其幕后指使人肖卓亚（谢天华 饰）有关，并牵涉多名香港海关高层领导，且似乎与受邀到香港、被JFIU廖保强（张智霖 饰）秘密保护的亚洲首席大法官庞爱玛（宣萱 饰）也有联系。暗流涌动、扑朔迷离，真相究竟何时浮现……', '古天乐', '林德禄', 4.6, 90521, 'tt10423286', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2686021044.jpg', 16.2, 44.9, 32.6, 4.8, 1.5, '0.011791,-0.253459,-0.399536,0.065811,0.407816,0.255333,0.161052,0.394730,-0.843923,-0.621305,0.256750,0.408695,-0.178493,-0.167517,0.195455,-0.068969,-0.284836,-0.709297,0.035578,-0.181029,-0.022123,-0.828668,-0.283871,-0.046028,0.275347,0.063683,0.311765,0.398141,-0.435546,0.371737,0.493985,0.520377,-1.040842,0.392224,0.276978,-0.484328,0.811286,0.315805,-0.524976,-0.282750,-0.051201,-0.405392,-0.027765,-0.268127,0.374432,0.616085,0.225907,0.103280,-0.153268,-0.123729,0.238175,-0.143332,0.155566,-0.129272,0.646037,0.568858,-0.000137,0.962288,-0.513109,-0.302604,0.172357,0.064545,-0.789805,-0.151543,0.599348,0.522764,-0.084249,-0.420443,-0.163719,-0.252716,0.044550,0.436451,0.395634,0.672034,0.159570,-0.193857,0.375452,0.219519,-0.411762,0.233570,0.451512,-0.108440,0.055608,-0.437517,0.063923,-0.598476,-0.131688,-0.039293,0.326816,0.180744,0.072787,-0.095304,0.334350,0.446395,-0.373045,-0.232075,-0.066041,0.194138,0.022104,0.064969,0.291790,-0.701481,-0.508599,-0.069803,-0.173525,-0.172440,0.425384,0.108401,0.045149,-0.313141,-0.058894,0.300419,0.297577,-0.804261,0.260762,0.301924,0.132024,-0.684090,-0.496113,-0.171586,0.401595,0.068387,-0.325588,-0.213503,0.040667,-0.814120,-0.118612,-0.608047', '26996640', '26985857', '26826398', '27202819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3259956', '赌博默示录', '剧情', '已经奔三的伊藤开司（藤原龙也 饰）做着无聊乏味的便利店员工作，对财富的渴望换来的不过是些无奈失落。某日，一位名叫远藤澟子（天海佑希 饰）的女人带领手下找到伊藤，要求他作为担保人偿还巨额高利贷债务。拮据的伊藤无力清债，只得按照远藤的建议登上“希望号”赌船奋力一搏。但在上船的那一刻起，伊藤以及其他众多同病相连的所谓“失败者”便陷入了巨大财富帝国的圈套。在赌博游戏中失败的伊藤众人，从此沦为帝国的奴隶，日日在地下工程中劳作，以期有朝一日能够脱离债务重返自由。帝国主管利川根（香川照之 饰）等人冷血无情，用尽招数榨取奴隶价值，不堪忍受剥削的伊藤最终选择了九死一生的“勇者之路”，用生命为赌注向利川根发起挑战……本片根据著名同名漫画改编。©豆瓣', '藤原龙也', '佐藤东弥', 7.2, 34026, 'tt1309449', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2200768775.jpg', 1.4, 6.6, 37.1, 39.3, 15.5, '-0.244776,0.101367,-0.362372,0.517490,-0.091555,-0.315227,0.385426,0.155844,-0.212369,-0.056138,0.392512,0.597821,0.418343,0.296997,0.290055,-0.181779,-0.059084,-0.510661,-0.277122,-0.120871,0.009588,-0.582425,-0.124076,-0.338195,-0.321050,-0.297333,0.948773,0.498821,-0.202084,0.264532,0.394469,0.249108,-0.130190,0.178265,0.021126,-0.221559,0.069883,0.021453,-0.392872,0.234453,-0.329175,-0.135815,-0.034108,0.190571,0.132920,0.343189,0.564873,-0.546278,0.082365,-0.201154,0.344832,-0.266177,-0.004041,0.265576,0.029024,0.100501,0.167813,0.218323,-0.419514,-0.115653,0.144631,-0.057943,-0.894847,-0.438860,0.031331,0.018814,-0.735311,0.402730,-0.157446,-0.124218,0.186761,-0.400219,-0.105816,0.220176,0.458779,0.234664,-0.312044,0.124110,-0.154201,0.151077,0.556005,-0.081961,-0.250492,0.038736,0.073020,-0.382331,-0.147775,-0.417911,-0.238702,-0.400864,0.375160,0.184414,0.148650,0.065913,-0.525946,0.085281,-0.068098,-0.323793,0.364794,-0.303299,-0.005620,-0.550156,0.121162,-0.058035,-0.114161,0.332733,0.482207,-0.462053,0.630704,-0.441510,0.033966,0.606633,0.356209,-0.529452,0.485923,-0.085277,-0.034098,-0.148579,-0.033836,0.457191,0.146815,0.460962,0.195869,-0.051696,-0.134105,-0.027763,-0.124984,0.445928', '26759820', '7051375', '25880986', '3001114');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3259973', '回来的路', '剧情', '1939年苏德瓜分波兰后不久，波兰青年维斯切克•乔努斯（吉姆•斯特吉斯 Jim Sturgess ）因其所谓的“反党反斯大林”间谍行为，被送入了西伯利亚的劳动营。其时已是1940年，在严寒的西伯利亚，乔努斯结识了同为政治犯的演员安德烈，后者有一项酝酿多时的逃跑计划，美国老人史密斯（艾德•哈里斯 Ed Harris 饰）、罪犯沃尔卡（柯林•法瑞尔 Colin Farrell 饰）等人陆续加入了他们的小圈子，在一个大雪之夜，乔努斯等七人成功逃出劳动营，他们唯一知道的，是向南前往贝加尔湖，同时躲避无处不在的举报者。一路上有人难耐恶劣的气候死去，在将要抵达贝加尔湖时，一个神秘少女伊莲娜（西尔莎•罗南 Saoirse Ronan 饰）加入了他们，她的加入，令一行人预备穿过蒙古、西藏，翻越喜马拉雅抵达英控印度寻找自由的路程又平添了几许困难……©豆瓣', '吉姆·斯特吉斯', '彼得·威尔', 7.9, 15061, 'tt1023114', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p795122029.jpg', 0.5, 2.1, 24.3, 50, 23.2, '0.247290,-0.144893,-0.583945,0.368675,0.036149,-0.189367,0.361840,0.051283,-0.670072,-0.081709,0.243131,0.615618,-0.142983,-0.283518,0.374526,0.086403,-0.482016,-0.535292,-0.032219,-0.335328,-0.229946,-0.348537,-0.215712,-0.292456,-0.028664,-0.395782,0.479046,0.327971,-0.089884,0.533390,0.034932,0.282078,-0.083604,0.455066,-0.063782,0.090316,0.459601,-0.514689,-0.200254,0.450576,-0.138605,-0.233888,-0.309080,-0.140156,-0.089066,0.624222,0.596463,-0.177072,0.200809,-0.049224,0.042421,-0.435822,-0.106319,0.267293,0.333564,-0.147345,-0.205810,0.152362,-0.293229,-0.071267,-0.095526,-0.092226,-0.317394,0.194485,-0.104817,0.215689,-0.354187,0.608721,-0.176808,-0.012791,0.186774,-0.525033,0.063525,0.653873,0.011275,0.195474,0.208381,-0.155610,-0.575067,0.124789,0.882224,-0.105438,-0.148877,-0.100708,-0.224147,-0.483442,0.044354,0.040005,-0.233544,-0.198963,0.643049,-0.057713,-0.093703,0.335020,-0.723791,0.017943,-0.483232,-0.379011,-0.021872,-0.164602,-0.207119,-0.673928,-0.099685,-0.134684,-0.204492,0.077462,-0.077935,0.074684,0.625499,-0.701136,0.396148,0.587748,0.409800,-0.281740,0.509201,-0.164033,0.288599,-0.172146,0.000683,0.460210,0.123947,0.314422,0.239026,0.454026,-0.248537,-0.193116,-0.193045,0.175334', '3147969', '11541282', '25721544', '1498831');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3259993', '丧尸乐园', '喜剧', '未来某天，灾难降临世间，天灾人祸让地球濒临毁灭。更为可怕的是，恐怖病毒肆意蔓延，人类相继化身为丧失人性、嗜血如命的恐怖僵尸。并且随着时光的流逝，僵尸的智商不断提升，已经成为规模庞大的恐怖大军。经过几个月的厮杀，居住在得州某小镇的哥伦布（杰斯·艾森伯格 Jesse Eisenberg 饰）是少数的幸存者之一，他唯唯诺诺，行事谨慎，却凭着总结出来的经验一次又一次逃出生天。某天，哥伦布遇见作风骠悍的塔拉哈西（伍迪·哈里森 Woody Harrelson 饰），两人一路同行，继而邂逅性感美艳的姐妹花薇奇塔（艾玛·斯通 Emma Stone 饰）和小石头（阿比盖尔·布莱斯林 Abigail Breslin 饰），他们由此开始了一段妙趣横生、惊险刺激的旅程……本片荣获2009年Sitges – Catalonian国际电影节观众奖。©豆瓣', '杰西·艾森伯格', '鲁本·弗雷斯彻', 7.3, 87177, 'tt1156398', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2210458082.jpg', 0.7, 4.3, 37.3, 43.4, 14.4, '-0.184092,0.013131,-0.692556,0.562526,0.052833,0.058441,0.805368,-0.138278,-0.404742,0.057091,0.342155,0.421514,-0.455593,0.067474,0.283448,-0.170042,0.024413,-0.500978,0.000245,-0.082208,-0.105794,-0.101721,-0.606934,-0.224913,0.139353,-0.544030,0.428443,0.373812,-0.122502,0.538303,0.097212,0.234103,-0.174146,0.274970,-0.250092,0.003925,0.070725,-0.151222,-0.186387,0.068659,-0.081966,0.149799,-0.216258,0.004645,-0.084234,-0.040076,0.723778,-0.511022,-0.099552,-0.244373,0.586216,-0.268049,-0.096014,-0.096480,0.435031,-0.041649,0.202865,0.153575,0.103203,-0.115171,-0.009220,-0.075350,-0.686660,0.223418,-0.181695,0.056005,-0.327488,0.204269,0.122080,0.064953,-0.120795,-0.272670,-0.215896,0.157500,0.340215,0.330394,0.076134,0.014157,-0.240340,0.147734,0.740423,0.099465,-0.783394,0.255275,-0.103954,-0.482294,-0.244018,-0.353131,-0.286161,0.037830,0.549342,-0.081822,0.059228,0.603925,-0.655634,0.094300,-0.361452,-0.311027,-0.098123,0.052456,-0.386475,-0.691727,-0.247861,-0.395078,-0.143023,0.033058,-0.013311,-0.240717,0.835957,-0.476249,0.150093,0.654133,0.229416,-0.391887,0.312378,-0.341851,-0.031745,0.088287,-0.091384,0.593752,-0.098611,0.130752,0.144110,0.312635,-0.268245,0.046377,-0.145280,0.713701', '3005387', '1308784', '4181031', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3262050', '美少女特攻队', '动作', '金发碧眼的洋娃娃（Emily Browning 饰）宛如一只时刻会受到惊吓的小鸟，这一天她被送进一家私人会所。该会所由蓝佬（Oscar Isaac 饰）掌控，他四处网罗妙龄女孩，并让葛斯基夫人（Carla Gugino 饰）教授她们舞蹈，旨在取悦那些腰缠万贯的富翁和手眼通天的政要。洋娃娃在此结识了小甜荳（Abbie Cornish 饰）、火箭女（Jena Malone 饰）、布女郎（Vanessa Hudgens 饰）、黑琥珀（Jamie Chung 饰）这4名好友。洋娃娃不愿沦为供人把玩的工具，她与朋友们商量从此逃走。逃亡计划需要4样工具：地图、打火机、刀和钥匙。朋友们负责盗取这些工具，而洋娃娃则用她那迷人且极具魔幻色彩的舞蹈吸引着蓝佬等人的注意力。只是终究也分不清，这是谁人的魔幻世界……©豆瓣', '艾米莉·布朗宁', '扎克·施奈德', 6.3, 64359, 'tt0978764', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p804624544.jpg', 6.9, 18.2, 39.8, 24.3, 10.8, '-0.005487,-0.070534,-0.178774,0.367920,-0.230987,0.178702,0.734916,0.264211,-0.452716,-0.313429,0.188449,0.634058,-0.087196,0.103661,0.181461,0.201521,-0.433635,-0.661171,-0.134792,-0.230694,-0.121714,-0.067004,-0.141382,-0.157259,0.149009,-0.150782,0.386112,-0.080226,-0.037465,0.373754,0.457629,0.020435,-0.392142,0.040159,-0.381467,-0.263495,-0.175014,0.035554,-0.111365,0.016431,-0.227389,-0.094894,-0.013111,0.042930,0.022242,0.101634,0.869489,-0.421392,0.216561,-0.377493,0.025986,-0.138096,0.239000,0.106615,-0.065843,0.004772,0.279646,-0.301556,-0.129808,0.347662,0.519278,-0.176776,-0.567699,0.161376,0.390364,0.198196,-0.465143,0.346843,-0.051136,0.182630,-0.071664,-0.038666,0.318056,-0.139920,0.131735,0.204555,0.262630,0.037574,-0.589802,0.510903,0.255677,0.151249,0.003944,0.252133,-0.379716,-0.252247,-0.161267,-0.166187,-0.477517,-0.072754,0.513637,0.156265,-0.154451,0.093684,-0.917729,-0.063439,-0.003104,0.176677,0.184236,-0.474047,-0.079072,-0.610527,0.290006,-0.417314,-0.131097,0.209972,0.317404,0.082589,0.931985,-0.569636,-0.045933,0.458301,0.175181,-0.426471,0.561319,-0.111001,-0.080649,-0.228564,-0.388272,0.010463,0.282159,0.276385,0.057400,0.302284,-0.091658,-0.300829,-0.287516,0.087226', '4181031', '3811356', '1302661', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3262091', '宝莱坞机器人之恋', '动作', '天才科学家瓦西（拉吉尼坎塔 Rajnikanth 饰）醉心于设计一款智能机器人，投入了大量精力和感情，仿照自己的外形，教与了机器人各种技能，带他在身边使他能够尽快的适应社会，并且命名它为“七弟”（拉吉尼坎塔 Rajnikanth 饰）。因为废寝忘食，忙于工作疏忽了女友sana（艾西瓦娅•雷 Aishwarya Rai 饰），为了哄女友开心，答应了女友让七弟陪自己期末复习的要求。一开始七弟闹出了许多笑话，但随着时间推移全能机器人七弟开始在生活的每个方面展现出自己过人的才能，和sana的相处，让他产生了人的情愫，并逐渐爱上了她。爱情的嫉妒心让瓦西和七弟的感情产生了缝隙，瓦西的老师趁机利用这一点开始怂恿七弟，在其体内插入了使七弟变成一台杀人工具的病毒芯片。源源不断的七弟机器人产生，世界陷入一片混乱。科学家瓦西和军方联手，开始了一场拯救原来那个善良的七弟的战斗。该影片耗资约16.5亿卢比（约3500万美元），为宝莱坞史上的最贵电影。这部电影也创下了印度电影历史上的多个“第一”。', '艾西瓦娅·雷', 'S·尚卡尔', 7.2, 24100, 'tt1305797', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p655825942.jpg', 1.9, 6.5, 35.9, 40.4, 15.2, '-0.039528,0.143736,-0.571298,0.644616,-0.258497,-0.267312,0.625833,-0.038944,-0.472010,-0.227391,-0.071162,0.649276,-0.179699,-0.036686,0.171975,-0.090167,-0.339869,-0.598732,-0.097816,0.008319,-0.231162,-0.284782,-0.239063,-0.249228,-0.149608,-0.528062,0.625584,-0.164048,-0.226374,0.273944,0.000366,0.215491,0.150261,0.284272,0.079385,-0.075305,-0.035235,-0.145933,-0.144087,0.227855,0.076659,-0.056955,0.210747,0.089769,-0.130021,0.155999,0.857953,-0.094625,-0.086860,-0.211323,0.505400,-0.115315,-0.013228,-0.107988,0.118585,0.182693,0.084889,-0.000732,-0.192573,0.094863,0.077862,-0.206939,-0.947907,-0.146726,0.004848,-0.258077,-0.543268,0.320340,-0.265045,-0.082327,0.002236,-0.123104,0.114977,0.469084,0.311149,0.273531,-0.268322,-0.216087,-0.410223,0.263243,0.323911,-0.193760,-0.271289,0.634822,-0.162127,-0.418084,-0.253107,-0.313604,-0.262456,-0.115147,0.364027,-0.140706,-0.148746,0.348476,-0.779380,0.124437,-0.006869,-0.295097,0.086330,-0.472403,0.245065,-0.515329,-0.424976,-0.427829,-0.125143,-0.210131,0.220360,-0.318277,0.889646,-0.799242,0.121869,0.592678,0.129740,-0.665209,0.586242,0.121677,-0.075246,-0.179483,0.024816,-0.037367,-0.127479,0.201193,0.144053,0.476903,0.208440,-0.075343,-0.440213,0.516778', '27602116', '24284209', '25928048', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3262939', '游龙戏凤', '爱情', '幸福是天上玻璃球的碎片，大家拼命的拾捡，却总归不会完满，爱情就是这种带点缺憾的甜蜜幸福。程仲森(刘德华饰)，亿万富翁，却始终没有找到可以携手白老的心爱之人。已经对爱情死心的他为朋友的爱情出谋划策，自己却对爱情不以为意。可是就在无心之时，他遇到了命中的“白骨精”，舞女米兰。米兰(舒淇饰)，自小与烂赌阿姨、好好姨丈同住。善良独立的她热爱跳舞，把跳舞当成自己的事业更是自己的生活。在一次兼职赌场小姐时，米兰偶遇了“烂赌棍”程仲森。爱情的火花点燃了，可是各种摩擦也随之而来。与此同时，程仲森的好友们也在捡拾着爱情的幸福碎片，争取着自己的幸福。©豆瓣', '刘德华', '刘伟强', 6, 65640, 'tt1312156', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1341267509.jpg', 3.4, 18, 57.8, 17, 3.8, '0.146495,0.067209,-0.714239,0.496395,-0.574673,-0.473147,0.980823,0.198813,-0.105515,0.125245,0.301273,0.670443,-0.064380,0.446352,-0.007590,0.120574,0.001407,-0.809789,0.130187,0.072782,-0.023520,-0.284643,-0.365368,-0.143073,-0.212658,-0.077560,0.658572,0.090375,-0.087401,0.293966,0.242513,0.040975,0.022189,0.558403,-0.534021,0.018274,-0.144845,0.302489,-0.462699,-0.188521,0.054766,-0.238479,-0.054756,0.247468,-0.160060,0.171671,0.751217,-0.421220,0.071539,0.044752,0.436516,-0.336620,0.169688,0.148249,-0.227776,-0.098820,0.304954,0.034406,-0.046472,-0.179074,0.351338,-0.012581,-0.898520,-0.179484,0.162275,0.162187,-0.687106,0.860149,0.045310,-0.059296,0.245870,-0.126797,0.393555,0.179452,0.230573,0.303552,-0.582852,-0.024446,-0.384126,0.630736,0.939434,0.086859,-0.190584,0.595477,-0.504713,-0.105315,0.082397,-0.114201,-0.753141,-0.240308,0.371911,0.053283,-0.061962,0.242437,-0.747741,0.166253,-0.020074,0.001179,0.259995,-0.646764,0.179567,-0.266970,-0.100002,-0.575864,-0.659994,0.029027,0.228625,-0.409791,0.950939,-0.819760,0.108655,0.787006,0.191157,-0.477462,0.861028,0.352077,-0.170287,-0.170704,-0.149119,0.370456,-0.217920,0.183689,0.064294,0.397933,0.133045,0.225483,-0.548090,0.770086', '3230462', '26862829', '30162520', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3263169', '假面', '剧情', '一名男子在他的公寓里被杀害了，警方在调查中发现死者乃是运动中心的富豪，现场唯一的线索是AB型男子的毛发。在调查中，怀疑的第一个对象是酒吧女，因为她曾在案发前给死者拨过电话。警员赵京尹（金康宇 Kang-woo Kim 饰）前去调查取样。然而，京尹却从同事口中得知，情况另有变化。大家开始怀疑死者与游泳中心教练是同性恋。不过随后，这个犯罪嫌疑人也惨遭杀害。警员们开始怀疑是连环杀人案与死者服兵役的经历有关。与京尹一同调查的警员朴恩珠（金敏善 Min-sun Kim 饰）是他的警校同学，虽有假小子作风，内心却渴望被呵护，而且暗恋的对象便是京尹。不过，京尹却面临更复杂的感情选择，他有固定的女友，也有藕断丝连的情人。随着抽丝剥茧，京尹发现此案隐藏着一段童年的往事……©豆瓣', '金康宇', '梁允豪', 7.5, 18497, 'tt1233473', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p501776635.jpg', 0.8, 4, 32.3, 45.6, 17.2, '0.428412,-0.340240,-0.589726,0.457993,-0.165580,0.041361,0.987377,-0.143589,-0.844197,-0.459555,0.359393,0.415733,-0.217582,0.207648,0.194870,-0.107875,-0.165483,-0.851300,0.001379,-0.192607,-0.300247,-0.660535,-0.315967,-0.137966,0.018136,-0.206016,0.610581,0.085548,-0.183033,0.442122,0.274611,0.342503,-0.372032,0.541068,-0.115470,-0.112539,0.121739,0.033173,-0.225489,-0.031609,0.201635,-0.551752,-0.017054,0.161112,-0.154018,0.852948,0.539364,-0.134086,-0.299237,0.108432,0.461780,-0.181881,-0.092951,0.126101,0.723351,0.318941,0.270467,0.423679,-0.114033,-0.124647,-0.078120,0.080688,-0.600207,-0.155565,0.391081,0.598822,-0.393904,0.246200,-0.251627,-0.031569,0.128527,-0.053091,0.321496,0.144240,0.100200,0.266702,-0.049321,-0.119475,-0.251953,0.285241,0.650100,0.013725,-0.054114,0.138596,-0.299028,-0.589362,0.076127,0.095757,-0.314867,0.242587,0.062857,0.104092,-0.325626,0.155042,-0.386868,-0.106130,-0.116052,-0.001152,-0.097417,-0.297780,-0.178081,-0.486723,-0.394796,-0.267640,-0.398765,-0.159736,0.022823,-0.425076,0.433780,-1.146446,0.027530,0.604541,0.154225,-0.687487,0.646147,0.092430,0.023258,-0.301721,-0.155276,0.170834,0.203361,0.197029,-0.206429,0.254777,-0.062602,-0.414606,-0.408578,0.039753', '1308755', '1304665', '1293265', '35073886');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3263410', '海贼王剧场版6：狂欢男爵和神秘岛', '剧情', '某天，草帽海贼团的诸位拾到一个漂流瓶。根据漂流瓶中的信息，在伟大航路上有一个娱乐至上的狂欢岛，靓女、美酒、佳肴应有尽有，是一个海贼中的海贼最值得去的地方。众人几乎未作过多迟疑，扬帆便向狂欢岛挺进。然而到达目的地才发现，这却是一个渺无人烟的荒凉小岛。当然好戏还在后头，他们很快便发现一个超级华丽的乐园。乐园的主人狂欢男爵承诺赐予众人天堂般的享受与欢乐，不过在此之前，他们还必须经过地狱般的试炼。已被“勇猛海贼”虚名冲昏头脑的路飞不顾众人阻拦，带着大家开始了一场莫名其妙的探险之中……本片根据日本漫画家尾田荣一郎的同名原著改编，是2005年上映的第六部动画剧场版。©豆瓣', '田中真弓', '细田守', 7.9, 11783, 'tt1018764', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2193283280.jpg', 1, 3, 24.7, 42.7, 28.7, '0.311496,0.070144,-0.756885,0.592011,0.312638,-0.239304,0.789513,-0.240903,-0.179059,0.146900,0.309935,0.742387,-0.403476,0.337757,0.578182,0.126058,-0.568485,-0.327564,-0.333913,-0.352577,-0.224005,-0.060788,-0.313021,-0.078641,-0.161434,-0.057650,0.685190,0.310627,-0.075144,0.530103,0.338361,-0.095354,-0.341852,0.614176,-0.334167,0.053324,0.111349,0.047874,-0.198896,0.343525,-0.418018,-0.147723,-0.338633,0.196955,-0.018765,0.280871,0.712524,-0.516483,-0.158166,-0.063323,0.255596,-0.282584,-0.010484,0.106180,0.361177,-0.114898,0.060175,0.195636,0.013100,0.219900,-0.265872,-0.230908,-0.640812,-0.160942,0.029476,0.233580,-0.163091,0.325574,0.252366,-0.244398,0.167537,-0.228023,0.244883,-0.056395,0.293671,0.303997,-0.009189,0.021233,-0.492850,0.381435,0.691398,0.104663,-0.307483,0.253846,0.259221,-0.601434,0.037263,-0.062262,-0.204112,-0.120854,0.291909,-0.035086,0.027851,0.104968,-0.933067,0.353356,-0.215361,-0.760324,-0.101873,-0.267659,-0.271412,-0.814738,0.155623,-0.098073,-0.082786,0.279715,0.230862,-0.165367,0.771776,-0.541745,0.195356,0.711614,-0.006597,-0.212696,0.644204,0.003324,-0.038802,-0.049388,-0.173583,0.234057,0.199031,0.517120,-0.042121,0.292078,-0.092957,-0.338925,-0.405586,0.478831', '2159244', '26290398', '1294917', '1856675');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3263814', '森林战士', '动画', '森林守护者 刚刚失去母亲的少女玛丽·凯瑟琳“M.K”（阿曼达·塞弗里德 Amanda Seyfried 配音）乘坐出租车来到一座几乎与世隔绝的大森林。这里生活着他的父亲，一个坚信森林里生活着矮人族的科学家，为了找到这些小生灵，他不惜牺牲家庭和婚姻。玛丽到达的那天刚好是夏至和满月，一个百年一次的特殊日子。包围着森林绿色和祥和的森林守护者的女王塔拉（Beyoncé Knowles 配音）将在这天选出继承人，然而他们的死对头Boggan人却要想方设法阻止继承人的诞生，这样便可以顺利地将腐烂和死亡的气息带到森林每一个角落。并不相信父亲说法的玛丽意外卷入两个矮人族的存亡纷争之中，而她也和数名森林守护者的勇士们肩负起保卫森林的重任……©豆瓣', '阿曼达·塞弗里德', '克里斯·韦奇', 7.4, 24243, 'tt0848537', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2158802659.jpg', 0.5, 3.8, 38.1, 42.5, 15, '0.092223,0.180628,-0.715585,0.829827,0.012048,-0.077676,1.025708,0.050152,-0.443883,-0.374131,0.321966,0.918480,0.176114,0.300257,0.336468,0.159648,-0.357646,-0.357031,-0.475541,-0.190143,-0.416440,-0.180883,-0.356694,-0.344534,0.074920,-0.475727,0.946585,0.128152,-0.274957,0.440694,-0.089711,0.113065,-0.389480,0.277938,-0.385934,-0.179529,0.123719,0.147478,-0.320884,0.266745,-0.350165,0.200275,-0.263752,0.172452,0.139704,0.213121,0.717433,-0.476202,-0.071246,-0.302034,0.238105,-0.670824,-0.007275,-0.004542,0.557216,-0.468434,0.307051,0.362459,0.102724,-0.096118,-0.025079,-0.423873,-0.953827,0.053110,-0.121203,0.239660,-0.648577,0.307464,0.225532,-0.317330,0.305239,-0.422983,0.243191,0.419120,0.118468,0.362801,-0.303647,0.056844,-0.707651,0.003992,0.954473,-0.493348,-0.181781,0.027615,-0.295975,-0.714153,-0.120235,-0.178789,-0.949973,-0.178390,0.259773,0.140153,-0.174505,0.254433,-0.743647,0.103043,-0.396752,-0.581756,0.375705,-0.529129,-0.263407,-0.396725,0.033570,-0.102637,-0.419107,0.150594,0.041082,-0.093212,0.647208,-0.619199,0.643179,0.570944,0.404308,-0.306240,0.823296,-0.049073,0.319985,-0.344541,-0.037338,0.518506,0.140511,0.542763,0.025988,0.188655,-0.110110,0.064746,-0.571636,0.318973', '21619567', '25828589', '26884422', '35287908');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3263820', '抗癌的我', '剧情', '四好青年亚当（约瑟夫·高登-莱维特 Joseph Gordon-Levitt 饰）的生活很圆满，工作顺利，家庭和睦，没想到，只是偶尔令他困扰的背痛居然被确诊为治愈率50/50的癌症。疾病的打击，女友瑞秋（布莱丝·达拉斯·霍华德 Bryce Dallas Howard 饰 ）的 离去，母亲的悲伤让原本自信面对病魔的亚当逐渐的感到沮丧和绝望，只有死党凯尔（塞斯·罗根 Seth Rogen 饰）一直用他特有的方式不离不弃的陪伴在他的身边。凯瑟琳（安娜·肯德里克 Anna Kendrick 饰）是一名缺乏经验的心理医生，负责亚当的情绪疏导，表面上专业镇定为人排忧解难的她，生活和感情上却是一团糟。两个失意的人，在疾病这个特殊的环境下相遇，从最初的误会到和解，他们逐渐的感觉到，也许这个世界上最重要的东西就在自己的身边。影片由编剧威尔·里瑟尔的真实经历改编而成，而当时站在他身后一直支持他的朋友正是饰演凯尔的塞斯·罗根本人。', '约瑟夫·高登-莱维特', '乔纳森·莱文', 7.7, 46914, 'tt1306980', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1114406235.jpg', 0.2, 1.5, 28.3, 53.7, 16.3, '0.286687,-0.015305,-0.683193,0.706234,-0.198129,-0.393385,0.913263,0.247005,-0.581668,-0.404084,0.486782,0.764175,-0.024660,0.403239,0.377572,0.036456,-0.401614,-0.674564,-0.104452,0.138743,-0.483154,-0.509447,-0.450191,-0.353993,-0.286767,-0.519254,0.661730,0.002176,-0.066899,0.407079,0.212602,0.536976,0.215809,0.559433,0.088044,-0.131916,0.012079,-0.241001,-0.308419,-0.092573,0.146173,-0.270126,-0.036463,0.282705,-0.044233,0.339580,0.586219,-0.256795,-0.142815,0.134179,0.322139,-0.289384,0.099187,0.073240,-0.023282,-0.172642,0.215425,0.077980,-0.214922,0.045238,-0.101835,-0.075202,-0.939602,0.091720,-0.041747,0.508150,-0.433765,0.478940,-0.171362,-0.103847,0.234549,-0.373273,0.066811,0.366045,0.095826,0.542302,-0.527206,0.036134,-0.340605,0.094732,0.613828,0.090930,-0.425997,0.381190,-0.552191,-0.389806,-0.200826,-0.216780,-0.561631,-0.105199,0.089719,0.083779,-0.153367,0.267388,-0.492244,0.045311,-0.051040,-0.067314,-0.142887,-0.381577,0.137823,-0.651925,-0.142588,-0.521115,-0.499079,-0.201823,-0.069821,-0.521217,0.716335,-0.740311,0.210223,0.533227,0.159994,-0.357942,0.655791,0.179424,0.041350,-0.243142,-0.370710,0.691701,-0.068475,0.115266,0.147603,0.413319,0.049647,0.176450,-0.422805,0.767863', '35158375', '1303077', '24756472', '1304641');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3264045', '花木兰', '剧情', '魏国与北方蛮族柔然连年交战，老单于心存退意，但是其子冒顿（胡军 饰）生性暴戾，意图吞并中原。为御外敌，魏国征召壮丁入伍，为国效忠。考虑到父亲花弧年迈病重，其女花木兰（赵薇 饰）毅然决定女扮男装、替父从军。在军中，木兰因有昔日玩伴小虎（房祖名 饰）做掩护，尚未露出破绽。一次偶然的机会，副营长文泰（陈坤 饰）发现了木兰的秘密，但见她为人正直功夫了得，所以替她隐瞒身份。后来，文泰与木兰并肩作战，屡破柔然大军，立下战功，均获封将军。不过，文泰发现木兰在战场上感情用事极为冲动，遂借故诈死，逼其独当一面。此时，屡战屡败的柔然部落已萌生退意，但冒顿一意孤行，不但剿杀异己，甚至手刃其父，自立为单于，发誓要扫平中原。门独面对的最大对手就是木兰领衔的魏国守军，一场惊心动魄的生死大战由此展开……本片有俄罗斯歌手维塔斯、韩国歌手李玖哲加盟，片尾曲分由孙燕姿与张靓颖演唱。©豆瓣', '赵薇 Wei Zhao', '马楚成', 6.2, 97529, 'tt1308138', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1629146620.jpg', 3.7, 15.8, 51.6, 22.1, 6.8, '-0.146272,0.143635,-0.523920,0.483741,0.226044,-0.215091,0.106625,0.229906,-0.596219,-0.384621,0.249111,0.459806,0.250926,-0.264857,0.101677,-0.341751,-0.040165,-0.651142,0.108301,0.018596,0.352082,-0.223351,-0.126434,-0.027528,-0.353645,-0.334409,0.926505,-0.078405,0.016579,0.681369,0.091496,0.116440,0.142931,0.307542,0.281519,-0.018596,-0.130580,-0.176565,-0.598472,0.145116,-0.274387,-0.287618,-0.536798,0.116092,-0.259567,0.436269,0.380999,-0.266044,0.125493,-0.402197,0.311354,-0.223337,0.211700,0.049144,0.426228,0.166535,0.133118,0.422591,0.103665,-0.098925,-0.260721,0.132006,-0.368561,0.132610,0.201941,-0.099429,-0.580787,0.354333,-0.175495,-0.037410,0.096181,-0.303168,-0.030136,0.610331,0.274595,-0.142772,-0.124877,0.127905,-0.352424,0.114204,0.664394,-0.194243,0.000830,-0.195843,0.458451,-0.297113,0.526730,-0.508463,-0.378146,0.144021,0.001627,-0.280755,0.146364,0.227183,-0.348611,-0.235616,-0.563650,0.354801,0.191710,0.104197,0.238596,-0.232483,-0.439537,-0.138758,-0.217394,-0.113238,0.498003,0.045713,0.315532,-0.646846,-0.114473,0.191661,0.357816,-0.723464,0.187786,0.309168,-0.050410,0.046005,-0.046432,0.244646,-0.002706,-0.100548,-0.060417,-0.187469,-0.125408,-0.356547,-0.232764,0.073810', '1293265', '35030151', '30345227', '27611498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3264229', '冥界警局', '喜剧', '青年警官尼克·克鲁兹（瑞安·雷诺兹 Ryan Reynolds 饰）思索再三，不愿和搭档巴比·海耶斯（凯文·贝肯 Kevin Bacon 饰）私吞毒贩的赃物黄金，结果在一次行动中被对方趁乱杀害。死后的尼克来到另一个世界，并受雇于冥界警局（R.I.P.D），其主要任务就是 追捕那些不愿接受死后审判而依靠伪装盘桓人间的死鬼。他的搭档是死于19世纪末的老头罗伊·鲍威尔（杰夫·布里吉斯 Jeff Bridges 饰）。罗伊作风粗犷，特立独行，这两个性格与风格上有着巨大差异的搭档跌跌撞撞展开行动。尼克在行动中发现死鬼们和海耶斯有着千丝万缕的关系，而在种种谜团背后隐藏着攸关世界命运的大阴谋。时间紧迫，尼克和罗伊必须尽最大可能阻止那个通天阴谋……©豆瓣', '瑞安·雷诺兹', '罗伯特·斯文克', 6.3, 46342, 'tt0790736', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1965136192.jpg', 1.9, 14.5, 57, 20.9, 5.7, '0.209562,-0.112330,-0.673206,0.465034,-0.311641,-0.289812,0.770936,0.156152,-0.663839,-0.347109,0.257576,0.749933,0.056981,-0.079166,0.253632,-0.223196,-0.351642,-0.595837,0.011726,-0.258185,-0.248486,-0.850107,-0.422444,-0.291604,-0.108492,-0.278855,0.690149,-0.164522,-0.029947,0.406043,0.553731,0.559725,-0.332583,0.203863,0.073891,-0.197224,0.233569,-0.343315,-0.451749,0.147812,-0.001981,0.190188,-0.213408,0.204701,-0.140766,0.279133,0.466299,-0.550161,0.001604,-0.248282,0.196515,-0.233977,-0.120261,0.219418,0.241167,-0.087808,0.196735,0.564673,-0.104315,-0.053187,0.319819,-0.009626,-0.578813,0.067384,0.063916,0.453433,-0.387306,0.132340,-0.026140,-0.213515,0.063948,-0.324649,-0.069465,0.327306,0.645369,0.103778,-0.051678,-0.121223,-0.410725,-0.318406,0.351226,0.052358,-0.163198,-0.011316,-0.156214,-0.075322,-0.256042,-0.224637,-0.297015,-0.086194,0.385153,-0.017238,-0.139636,0.431578,-0.510064,0.032694,-0.418895,0.049178,-0.283218,-0.340616,-0.117021,-0.750175,-0.229772,-0.359788,-0.378165,-0.047375,0.152769,-0.058237,0.441205,-0.743690,0.156046,0.632574,0.245284,-0.306765,0.469391,0.262915,0.169510,-0.404853,-0.184834,0.276106,0.249779,0.080216,-0.049425,0.240262,0.129475,-0.096794,-0.355246,0.383079', '1293145', '7916027', '1307442', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3264234', '狗蛋大兵', '喜剧', '故事发生在七十年代我国台湾某海防阵地，狗蛋（郝邵文 饰）是村里顽劣的孩子，他整天跟着值星官吴班长（吴宗宪 饰）干着偷鸡摸狗的勾当，过着无忧无虑的日子。由于军纪涣散、表现实在不象话，上司调来了新队长（吴奇隆 饰），新队长誓言三个月改造这群乌合之众。在历经一段令人啼笑皆非的整顿后，军纪果然有了明显提高，并在中美军演中表现突出，虽说以微弱比分输给了美军，但海军司令部高度评价了新队长的带兵经验，连狗蛋的班主后（翁虹 饰）也对其产生了好感。新队长谢绝上峰对他的提拔，说服当将军的父亲，绝定留在这里，父亲最终同意了他的请求。殊不知，吴班长等一干人马恨不得他离开这里，因为大家实在受不了他的魔鬼训练......©豆瓣', '吴宗宪', '朱延平', 7.7, 6584, 'tt4579930', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2281878640.jpg', 0.7, 3.6, 28.1, 43.9, 23.7, '-0.074428,-0.133322,-0.490243,0.502576,-0.254532,-0.292104,0.350012,0.126354,-0.834501,-0.173115,0.169324,0.339365,-0.011588,0.007801,0.148479,-0.375924,-0.301411,-0.553508,-0.175028,-0.164684,-0.029466,-0.382861,0.021642,-0.218372,-0.136096,-0.153263,0.523957,-0.053053,-0.098630,0.454869,0.358563,-0.076778,0.243161,0.412870,0.104676,0.194424,0.260206,-0.053270,-0.128071,-0.194586,0.106207,-0.130136,-0.203931,-0.078125,0.299860,0.372372,0.549612,-0.341931,-0.420985,-0.137956,0.079285,-0.177963,0.046782,0.053764,0.461163,0.220301,0.021255,0.204161,-0.017560,0.153727,-0.348245,0.013694,-0.375720,0.010414,-0.010691,-0.137015,-0.520517,0.374028,-0.036293,0.106405,0.065143,-0.196947,0.036421,0.356982,0.069984,0.326193,-0.184440,0.131527,-0.246351,0.373761,0.416329,-0.154692,-0.271202,-0.003197,-0.163240,-0.357330,0.112763,-0.303931,-0.360898,0.139124,0.048644,-0.166803,-0.051845,0.054072,-0.489986,-0.059655,-0.030924,-0.093460,-0.135622,-0.224191,0.029920,-0.384063,0.082171,-0.395621,-0.241850,0.116759,-0.000189,0.080498,0.666550,-0.743850,-0.039687,0.232316,0.223100,-0.663819,0.240496,0.331133,0.129170,-0.172152,-0.065972,0.064137,-0.043293,0.486025,0.428872,0.446867,-0.130874,-0.528291,-0.177897,0.208957', '35030151', '1293265', '1301022', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('32659890', '我和我的祖国', '剧情', '七位导演分别取材新中国成立70周年以来，祖国经历的无数个历史性经典瞬间。讲述普通人与国家之间息息相关密不可分的动人故事。聚焦大时代大事件下，小人物和国家之间，看似遥远实则密切的关联，唤醒全球华人共同回忆。', '黄渤', '陈凯歌', 7.6, 961954, 'tt10147382', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2567998580.jpg', 1.1, 3.9, 29.2, 44.9, 20.9, '0.269552,0.223225,-0.644655,0.619205,0.718110,0.505936,0.486676,-0.497957,-0.685272,-0.211419,-0.224543,0.707122,-0.432445,-0.087969,0.309514,-0.653783,-0.129567,-1.035912,-0.429158,-0.157719,-0.188872,-0.948526,-0.604591,-0.046583,-0.321169,-0.207487,0.534666,0.132099,-0.398947,0.452476,0.262323,0.155219,-0.883563,-0.135022,0.291103,-0.388483,0.312357,0.755804,-0.962880,-0.260584,-0.404373,0.306370,-0.041152,0.115944,-0.384346,0.191515,-0.100390,-0.430010,-0.008638,-0.587143,0.325231,0.462998,-0.439623,-0.457906,0.397619,1.001897,0.727815,0.837403,0.288182,-0.610935,-0.196155,-0.611083,-0.500147,0.176548,0.681574,0.339123,-0.127315,0.603541,0.510364,0.177346,0.282818,-0.080688,0.153761,0.647280,1.412147,0.521221,0.363273,0.551047,0.377146,0.341470,0.956895,0.121352,-0.856813,0.107245,-0.498292,0.065679,-0.273947,-0.159158,-0.251505,0.198137,-0.315014,-0.042139,0.033797,1.394104,-0.837039,0.389296,-0.115123,0.194704,0.527021,-0.321240,0.255243,-0.625179,-0.453988,-0.598536,-0.280782,0.358875,0.449851,-0.416299,1.279834,-0.559977,0.098075,0.388744,0.379376,-0.129543,0.761696,0.191373,0.335161,-0.659811,-0.278371,0.320469,-0.252722,0.009881,-0.469061,-0.205995,-0.687538,0.357538,-0.384189,0.383419', '1291546', '5153254', '26790961', '27040853');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3266407', '超强台风', '剧情', '面对“擦门而过”的台风三次转向，并且越来越远离这座拥有百万人口的城市，专家陈老师（宋晓英 饰）坚持台风仍有50%的可能性调头回来。依据以往防台工作“十防九空”的现实，在120万群众的安危和浪费38亿国家财产的面前，以徐市长（巫刚 饰）为主的市委领导坚持从人民群众的生命安全出发，宣布全市进入紧急状态，撤离工作在各种各样的质疑声中紧锣密布的进行。史无前例的18级台风掀起惊涛骇浪向着这座城市袭来，在城市的角落里，一些人没有来得及避险的人陷入危难之中。军民一心抗灾救人谱出一曲惊心动魄的乐章，人性在天灾面前绽放出瑰丽光辉。本片以2006年8月份在我国浙江温州登陆的超级台风“桑美”为素材，由冯小宁执导，号称我国首部灾难大片。©豆瓣', '巫刚', '冯小宁', 4.6, 11725, 'tt1313153', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2239086095.jpg', 31.2, 27.1, 28.2, 8.7, 4.9, '-0.063894,0.244308,-0.785612,0.515714,0.240591,0.211974,0.620313,0.111402,-0.376352,-0.098627,0.346672,0.366183,-0.114522,-0.218752,0.373184,-0.496858,-0.212039,-0.467420,-0.213316,-0.086240,-0.146538,-0.222198,-0.258135,-0.050540,-0.173345,-0.178532,0.592215,0.435231,-0.156131,0.300353,0.087457,0.223289,-0.039861,0.547674,-0.046454,-0.260937,-0.363273,0.080829,-0.536440,0.436540,-0.183841,-0.343250,-0.266112,0.092805,0.062388,0.141480,0.772849,-0.171706,-0.000541,0.092051,0.607845,-0.303369,-0.033747,-0.098261,0.553318,-0.032665,0.019874,-0.050544,-0.223296,0.151206,-0.123167,-0.378519,-0.532502,-0.174180,0.129115,0.111410,-0.472424,0.225440,-0.052340,0.057532,0.005460,-0.193636,0.202358,0.305627,0.044064,0.637823,-0.351696,0.192327,-0.440834,0.335775,0.517431,-0.090068,-0.304863,-0.176353,-0.301398,-0.418766,-0.086485,-0.461083,-0.226244,-0.141426,-0.032459,-0.155942,0.051473,0.198450,-0.768103,-0.061833,-0.044679,-0.768252,-0.043352,-0.086892,-0.319060,-0.772418,0.173377,-0.024823,0.037758,0.282577,0.134598,-0.142184,0.708831,-0.693147,0.049324,0.306423,0.402789,-0.320276,0.655702,-0.082060,0.191514,-0.128534,-0.085271,0.312368,-0.014658,0.697285,-0.082881,-0.028439,-0.170824,-0.348963,-0.067869,0.303860', '2159244', '1307897', '26951746', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3266509', '少年手指虎', '喜剧', '古灵精怪的栗田（宫崎葵 饰）是枫唱片公司新人发掘部的一名员工，不过在两年工作期间，她始终未取得任何业绩。就在即将辞职回老家之际，栗田在网络上看到一段某朋克乐队现场演出的视频。这群张扬跋扈又不失感染力的年轻乐手让栗田仿佛看到事业的曙光。她欣喜若狂找到社长时田（中山裕介 饰），大力举荐这支名为“少年手指虎”的乐队。一方面希望再给栗田一次机会，一方面也嗅到其中隐藏的卖点，时田决定签下“少年手指虎”，并立即举行全国巡演。作为该项目负责人，栗田开始四处寻找乐队成员，结果却惊奇地发现，所谓年轻乐手全是一群老弱病残、年过半百的大叔，而那段视频竟然是25年前录制的！巡演日期逐渐逼近，栗田只能赶鸭子上架，带着这群老头子展开了艰苦的巡演之旅……©豆瓣', '宫崎葵', '宫藤官九郎', 7.2, 8296, 'tt1313146', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p831524252.jpg', 1.3, 6.6, 38.3, 39, 14.9, '-0.022100,0.088151,-0.523653,0.445488,-0.022589,-0.194712,0.238688,0.053815,-0.301048,-0.320235,0.133199,0.431559,-0.236613,0.488443,0.408708,-0.153195,-0.125867,-0.730508,-0.153238,-0.026464,0.067855,-0.087966,0.002489,-0.049273,0.103386,-0.214595,1.012682,0.247141,-0.053161,0.660193,0.393812,-0.052646,-0.196176,0.241768,0.008383,-0.098552,0.356103,-0.058438,-0.133138,0.063750,-0.061474,-0.368350,-0.350424,0.099287,0.055362,0.419343,0.645309,0.057975,-0.084248,0.058705,0.304524,-0.166787,-0.083768,-0.050885,0.446052,0.228039,0.230366,0.119313,-0.139194,0.058804,-0.339420,-0.326789,-0.572005,0.141245,-0.168397,0.279213,-0.327657,0.336906,-0.095689,0.094377,0.196098,-0.296382,-0.102145,0.303787,0.249013,0.271967,-0.018386,0.454523,-0.179133,0.329461,0.338242,0.109856,-0.093033,0.311272,0.046485,-0.383921,0.043074,-0.153419,-0.173198,0.084319,0.259478,-0.057720,-0.090289,-0.166870,-0.520657,0.109293,-0.221129,-0.334908,0.182571,-0.310538,-0.096936,-0.938703,0.105237,-0.067842,-0.044333,0.273635,0.189664,-0.227962,0.696743,-0.801737,0.011741,0.512175,0.057319,-0.255746,0.386242,0.140104,-0.024389,-0.253840,-0.219470,-0.124612,0.021212,0.257140,0.057835,0.279535,-0.082242,-0.589113,-0.352908,0.309739', '2369613', '25723905', '20274039', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3267120', '魔法师的学徒', '剧情', 'http://site.douban.com/107187/魔法师的学徒豆瓣小站公元700年左右，正义的魔法师默林（James A. Stephens 饰）带领徒弟巴尔萨泽（尼古拉斯·凯奇 Nicolas Cage 饰）、维萝妮卡（莫妮卡·贝鲁奇 Monica Bellucci 饰）、霍瓦斯与邪恶的女巫莫戛娜·洛菲（Alice Krige 饰）展开抗争。维萝妮卡为了封住女巫，而将莫戛娜的灵魂吞入自己的体内，并由巴尔萨泽将她们封印在玩偶中。默林死前，将一枚龙指环交给巴尔萨泽，嘱托他寻找默林英雄，将莫戛娜彻底消灭。此后的岁月里，巴尔萨泽走遍世界各地寻找默林英雄，却始终一无所获，直到他来到美国纽约。公元2000年，四年级小学生戴夫在纽约一间魔法店宿命地邂逅了巴尔萨泽，并得到龙指环的肯定。期间，他无意中释放了邪恶的霍瓦斯，引发一场巨大的混乱，戴夫也被同学们认为精神错乱。转眼十年，戴夫（Jay Baruchel 饰）已成长为帅气青年。童年的遭遇恍如一场噩梦，却在十年后再次袭来，他不得不遵照命运的指引，与女巫展开最后的抗争……', '杰伊·巴鲁切尔', '乔·德特杜巴', 6.1, 62445, 'tt0963966', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p605523016.jpg', 2.4, 16.5, 56.9, 19.6, 4.6, '0.038090,0.344605,-0.293796,0.441104,0.014792,-0.387853,0.720342,-0.068443,-0.402490,-0.424792,0.063991,0.616054,-0.261194,0.200160,0.522103,0.096971,-0.249646,-0.663884,-0.052140,-0.116216,-0.215297,-0.365289,-0.263209,-0.125464,-0.027221,-0.589838,0.583226,0.176403,0.052451,0.212457,0.258850,0.509126,-0.224853,0.175670,-0.018650,-0.006962,0.070220,-0.063113,-0.255651,0.268482,0.165661,-0.276951,-0.057863,0.261001,0.041249,0.171205,0.739714,-0.578863,0.243458,-0.201762,0.130056,-0.286932,-0.193772,0.094680,0.213356,0.332852,-0.025117,0.231502,-0.022840,0.031569,0.154303,-0.140900,-0.469049,-0.070081,0.088793,0.017606,-0.383046,0.416607,0.046708,0.143429,-0.022283,-0.106869,-0.024617,0.106349,0.196821,0.206896,-0.223570,-0.020560,-0.331557,0.131453,0.289005,-0.290720,-0.203873,0.229957,-0.170700,-0.425075,-0.039604,0.097810,-0.384744,-0.094899,0.366958,0.371615,0.149260,0.624467,-0.868479,-0.187106,-0.641324,-0.063024,0.117931,-0.198014,-0.228922,-0.540082,-0.059565,-0.032658,0.113678,0.017976,0.015095,-0.204226,0.445322,-0.655471,0.311024,0.433168,0.381698,0.095955,0.260274,-0.324192,0.427666,-0.305363,-0.038512,0.368666,0.229798,