INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3267195', '童眼', '惊悚', '来自香港的琳妮（杨丞琳 饰）和乐仔（余文乐 饰）以及其他4名男女朋友飞赴泰国旅游，感情出现问题的琳妮和乐仔原本想借此弥合矛盾，然而一切未见好转。偏偏赶上泰国动乱，6人未及玩耍，匆匆收拾行李直奔机场，机场又让示威人员占领。万般无奈，他们只好在一个古旧的小旅店落脚。街道上已然动乱不堪，这间旅店又似乎充满悬疑和诡异，年轻人们一度放松快乐的心情被搞得惊恐慌乱。在一起恐怖的事件过后，乐仔和其他两名男孩神秘失踪。琳妮等人四下寻找，不见踪影。从当地一个小孩的口中，她们听到一则令人毛骨悚然的讯息：乐仔等人竟被一个女鬼抓走……©豆瓣', '杨丞琳', '彭顺', 4.7, 5792, 'tt1314170', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2282154372.jpg', 18.5, 39.3, 33.7, 6.1, 2.5, '0.462153,-0.038241,-0.955859,0.296544,0.174419,-0.076749,0.907265,0.203329,-0.394140,-0.380550,-0.110199,0.516174,-0.585109,0.302958,0.216629,-0.124146,-0.668812,-0.585742,0.036715,-0.191908,-0.322150,-0.072009,-0.041377,-0.466839,0.006738,-0.126069,0.212257,0.259956,-0.121220,0.868988,0.195935,0.325586,-0.705799,0.557572,-0.259439,-0.067634,0.297371,0.072642,-0.044981,0.007458,-0.108503,-0.226712,-0.258378,0.127283,-0.075917,0.477389,0.685469,-0.027074,-0.235465,0.131076,0.114203,-0.118294,-0.133514,0.101653,0.210731,-0.272890,0.349387,-0.187721,-0.386592,-0.168075,0.215430,0.040498,-0.406584,0.428989,0.113434,0.232462,-0.316264,0.375171,0.052252,-0.163286,0.119291,-0.338713,0.528013,0.352644,-0.010674,0.566584,0.080005,0.143104,-0.331451,-0.014298,0.741084,0.013213,-0.105797,0.110381,0.053637,-0.324865,0.061372,0.195453,-0.199314,-0.062829,0.374451,-0.045129,-0.162538,-0.041420,-0.536396,-0.039605,-0.315805,-0.110324,-0.303623,-0.393889,-0.217145,-0.818088,-0.003905,-0.182455,-0.190777,0.249006,0.108645,0.268392,0.520535,-0.419134,0.062178,0.332330,0.280306,-0.459913,0.254496,-0.220534,0.127501,-0.219727,-0.356304,0.121467,0.077134,0.286746,0.254686,0.367265,-0.359725,0.021055,-0.488935,0.267938', '10466639', '3011051', '1930829', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3268171', '电梯里的恶魔', '悬疑', '一天上午，有人坠楼摔死在一辆货车上。负责调查的警探博登（克里斯·梅西纳 Chris Messina 饰）来到现场后发现第一现场并不在货车停靠的位置，而是在不远处的一栋大厦。与此同时，这栋大厦的一处电梯突然故障，悬停在20层附近，电梯中的三男两女被困。大厦保安派去的维修人 员也未能解决故障。封闭的电梯里，五人因持续被困而情绪焦躁并争执起来。就在此时，电梯内的灯突然熄灭了十几秒钟，短暂的黑暗过后，其中一名女郎的背部受伤流血不止。保安决定报警。博登接到大厦保安报案之后赶赴监控室，正欲调动警力解救被困人员之时，电梯内的灯再次熄灭。灯亮之后，人们发现其中一名男子已被杀害，而凶手似乎只有可能是剩下的四人之一……©豆瓣', '克里斯·梅西纳', '约翰·埃里克·道达尔', 6.5, 51492, 'tt1314655', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p576334028.jpg', 1.6, 11.3, 54.2, 26.9, 6, '0.407752,0.312757,-1.078270,0.032583,0.228290,-0.225861,1.290881,0.349329,-0.372820,-0.405806,0.576716,0.394582,-0.288184,0.276948,0.469433,-0.282239,-0.445958,-0.527234,-0.347576,-0.592114,-0.771528,-0.272063,0.189321,-0.336011,0.261635,-0.141110,0.581410,0.568056,0.109405,0.377227,0.084225,-0.014993,-0.485904,0.563465,0.186104,-0.102652,0.412529,-0.351383,0.239414,0.325648,-0.519935,-0.476654,0.109670,-0.210150,-0.099362,0.463435,0.667037,0.021107,-0.302399,0.058216,-0.123241,-0.032587,-0.111548,-0.199234,0.873426,0.046989,0.301035,0.013386,-0.487253,0.096632,-0.139245,0.197833,-0.304859,0.073679,-0.363199,0.134179,-0.411316,0.233615,-0.212719,-0.066872,0.016914,-0.246148,0.220021,0.144464,0.051084,0.327916,-0.235018,-0.149980,-0.593988,-0.350322,0.379186,-0.252951,0.001745,0.481812,0.330321,-0.542967,-0.227662,0.279295,-0.316503,-0.302879,0.531430,0.252172,0.131238,-0.521846,-0.174947,0.063884,-0.507570,-0.344299,-0.311177,-0.084695,-0.326876,-0.995310,0.212518,0.395174,0.072687,0.484671,-0.258273,0.240607,0.041729,-0.731579,0.376151,0.308902,0.225182,-0.253848,0.585119,-0.415719,0.306213,0.089819,-0.072706,-0.072693,0.308066,0.962805,-0.076992,0.361285,-0.560243,-0.339709,-0.675202,-0.123048', '20451118', '3011051', '10466639', '1307807');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3268216', '桃花运', '剧情', '都市中五个婚爱观截然不同、年龄亦差异较大的女人：在保守环境中长大的章迎（梅婷）人已28岁，却从未尝恋爱滋味，发誓要把贞操留到与心爱的男人结婚那夜；小章迎几岁的“白骨精”（李小璐）性情泼辣，一心要找钻石王老五下嫁；“白骨精”的好姐妹是位“富家女”（小宋佳），为找到真心待她的男人，将自己扮成为生活打拼的普通女孩；大章迎几岁的叶（邬君梅）被丈夫抛弃，携子过着惨淡的日子，十分渴望身边能有个男人作支撑；人过50的高姐（元秋）则主动将嫌她是黄脸婆的丈夫踢下床，但过了一年多单身生活后，也想身边再有个男人。持怎样的婚爱观，便会有怎样的恋爱经历：章迎在假面舞会上与“海归”的赵大（耿乐）又见钟情，恋爱谈了大半年，两人仍在肉体上绝对纯洁；“白骨精”相中某处在发展中的公司的老总（段奕宏），向原公司请假半年来到他的身边，开始拼命自造与他亲密接触的机会；“富家女”因为一道菜结识某酒店的“10号厨师”（李晨），冲着他的体贴与单纯，不计他的贫穷与他开始浪漫的恋爱，却也没忘暗中将他考验；叶遇到从婚介所拿到她资料、主动将她找上、自称在神秘单位供职的王莽（葛优），王莽为她和儿子所做的件件事都强过前夫（刘震云）一百倍，令她以为迎来爱情上的第二个春天；高姐则结识小她好多岁、经历复杂的网友（郭涛），这个男人亦一次次带给她感动，她也甘心为他付出全部。五个女人恋爱谈得有甜有酸，五个男人也渐渐显出更多面，“真命天子”里，既有上天钦赐，亦有情感骗子、有缘无分的过客和想改过自新的浪子。', '葛优', '马俪文', 5.7, 63402, 'tt1314247', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2229591084.jpg', 5.9, 22.7, 53.6, 15.2, 2.6, '0.184472,-0.040607,-0.542952,0.509950,-0.457606,-0.285219,0.842566,-0.148779,-0.328880,-0.048638,0.071087,0.795192,-0.191574,0.468764,0.279517,0.031043,0.064831,-0.643661,-0.008858,-0.052423,-0.164030,-0.309641,-0.260362,0.026891,-0.219903,-0.058784,0.588536,-0.161540,0.059358,0.236640,0.478406,-0.117221,0.049099,0.531423,-0.345733,0.072679,-0.173061,0.347816,-0.248758,0.108099,0.092544,-0.255299,-0.034253,-0.070235,-0.028287,0.321134,0.562863,-0.067139,-0.196189,-0.071232,0.518050,-0.042155,-0.119933,0.198274,0.025308,0.084559,0.140101,0.181828,-0.143379,-0.118537,0.074908,-0.176606,-0.567764,0.060156,0.222139,-0.229902,-0.619736,0.485349,0.022790,-0.080843,0.169688,-0.257358,0.059720,0.320277,0.196460,0.264930,-0.187676,0.101192,-0.365698,0.333169,0.701480,0.305043,-0.197606,0.332811,-0.116001,-0.474882,0.099133,-0.328370,-0.515218,-0.008644,0.125940,-0.072071,-0.305422,0.164413,-0.438636,0.247809,0.029222,0.184746,0.107394,-0.395564,-0.097975,-0.206281,-0.252468,-0.525357,-0.466272,0.050515,0.233569,-0.510438,0.700710,-0.723341,0.093363,0.446257,0.497274,-0.645658,0.869821,0.253575,0.033747,-0.273781,-0.057560,0.364481,-0.128038,0.043913,0.099563,0.344092,-0.342354,0.044064,-0.297925,0.528593', '30162520', '3055049', '3504940', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3268493', '保卫者', '剧情', '亚瑟（伍迪·哈里森 Woody Harrelson 饰）是个无一技之长的建筑工人，大脑慢半拍，性格一根筋，但他沉迷于超级英雄漫画和个人英雄主义，幻想自己是个超人、蝙蝠侠一样的超级英雄，可以在夜间拥有另一个身份惩恶扬善。于是他用眼影、胶带自制了可笑的行头装备，武器更是毫无杀伤力的玻璃珠、橘子汁，每每在出手时被小混混揍得鼻青脸肿。一次挨揍后，一个年轻妓女凯瑟琳（凯特·戴琳斯 Kat Dennings 饰）帮助了他，相处中二人渐渐产生爱情，而亚瑟更要拿着凯瑟琳给他的枪，以卵击石地去找城市的大毒枭挑战……©豆瓣', '凯特·戴琳斯', '彼得·斯戴宾斯', 7.5, 6926, 'tt1303828', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p663049773.jpg', 0.8, 4.6, 31.7, 45.3, 17.6, '0.281564,0.003012,-0.418351,0.620215,-0.424722,-0.355979,0.782762,0.028504,-0.355602,-0.263952,0.326754,0.928823,-0.142750,0.049651,-0.120198,-0.170851,-0.094605,-0.724379,0.022161,0.111428,-0.329901,-0.303436,-0.438186,-0.147907,-0.193971,-0.175480,0.462159,-0.364231,-0.367513,0.158924,0.320375,0.182503,0.459930,0.276512,-0.387388,-0.303873,0.040693,-0.165676,0.094720,0.263044,0.086221,0.018883,-0.018398,0.421984,-0.383174,0.295535,0.679703,-0.353566,0.005782,-0.264478,0.436060,-0.191038,-0.147682,0.042338,0.155096,-0.063092,0.145202,-0.446451,0.129306,0.202999,0.505334,-0.102286,-0.717352,-0.105954,-0.061936,0.107651,-0.693153,0.370017,-0.246279,-0.048409,0.146997,-0.179250,0.070571,-0.147716,0.490254,0.198990,-0.241577,-0.024235,-0.669733,0.328617,0.303933,0.240668,-0.284895,0.412078,-0.418158,-0.262076,-0.106914,-0.487157,-0.566296,-0.239789,0.480302,-0.291388,-0.312870,0.140423,-0.776085,0.052855,-0.186213,0.118472,-0.162859,-0.312111,-0.219927,-0.420260,-0.051155,-0.554762,-0.295111,0.006764,0.399881,-0.096290,0.865234,-0.685665,-0.193807,0.518002,-0.102403,-0.345073,0.574807,0.010720,-0.144542,0.003810,0.057607,-0.051319,0.186591,0.069790,0.245453,0.568018,-0.014350,-0.080267,-0.185062,0.563793', '30162520', '21350559', '27602116', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3269018', '说来有点可笑', '剧情', '16岁的男孩Craig克雷格（凯尔·吉克瑞斯特 饰）经常会想象自己的死亡，在尝试多种药物皆没有效果后，自己来到精神病院接受治疗。在那里，他和一个自杀了几次却没能死掉的神神叨叨的Bobby鲍比（扎克·加利费安纳基斯 饰）成了朋友，还认识了一个特别的女孩Noelle，当然还有许许多多的“非正常人”。他们几个在医院的生活中，渐渐寻回了生命的意义，尤其是鲍勃·迪伦的歌词“He Not Busy Being Born Is Busy Dying”给了他们巨大的力量，让他们重新拥有勇气去面对生活的压力。最后，出院的克雷格是否能让他原本阴霾密布的生活重见阳光，他又将通过怎样的方式找回轻松充实的生活？本片改编自Ned Vizzini的同名小说，在布鲁克林的一所大学预科学校和一所医院取景拍摄。©豆瓣', '凯尔·吉克瑞斯特', '安娜·波顿', 7.7, 22044, 'tt0804497', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p595865058.jpg', 0.4, 2.3, 28.3, 48.1, 20.9, '0.261343,-0.066554,-0.536495,0.709523,-0.229687,-0.280655,0.873711,0.290070,-0.411389,-0.166726,0.127524,0.796620,-0.035069,0.320454,0.042994,-0.014675,-0.356250,-0.580939,0.119826,-0.028775,-0.612941,-0.446498,-0.409731,-0.270289,0.104842,-0.567967,0.516043,0.032416,0.050046,0.265233,0.007921,0.341139,0.077816,0.498087,-0.271320,0.045133,0.119623,0.045624,-0.095770,0.387052,0.216712,-0.412891,-0.052850,0.287773,0.082365,0.272491,0.934040,0.048628,-0.252695,0.126325,0.382094,-0.166806,-0.205359,0.279937,0.009238,-0.276011,0.144991,0.075872,-0.307958,0.110335,-0.062427,-0.089218,-1.007492,-0.158961,0.049227,0.183812,-0.662707,0.583363,0.122132,-0.154255,0.024508,-0.377890,0.251052,0.359265,-0.011432,0.616826,-0.326974,-0.123509,-0.520758,0.357505,0.707774,-0.212279,-0.377138,0.529496,-0.477305,-0.406318,-0.229939,-0.061084,-0.521201,-0.031643,0.310153,0.002536,-0.435566,-0.087853,-0.697777,-0.068315,-0.232935,-0.265061,-0.113442,-0.458897,0.054281,-0.643451,-0.111036,-0.327486,-0.324472,-0.169322,0.025316,-0.341007,0.817079,-0.770724,0.233266,0.583504,0.238626,-0.383373,0.597881,0.103341,0.060376,-0.057887,0.159555,0.349268,0.132029,0.459851,0.305895,0.516301,0.152574,0.072362,-0.430139,0.858498', '24733428', '35158375', '27666513', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3269019', '杰克与吉尔', '喜剧', '电影中的双胞胎兄妹杰克和吉尔两个角色全部由亚当·桑德勒一人饰演。第32届金酸莓奖颁奖典礼上，亚当·桑德勒与此片独揽了最差男女演员在内的10个主要奖项。新好男人Jack（亚当·桑德勒 Adam Sandler 饰）是一名有着优秀业绩的广告销售。他和美丽的妻子Erin（凯蒂·霍尔姆斯 Katie Holmes 饰），以及一对可爱的儿女，一家人幸福而平静的生活在洛杉矶。感恩节假期降至，Jack远在纽约的孪生妹妹Jill（亚当·桑德勒 Adam Sandler 饰）提出要来洛杉矶拜访。没想到Jill这一住上瘾，不愿离开，更是把Jack原来平静的生活搅了个天翻地覆……©豆瓣', '亚当·桑德勒', '丹尼斯·杜根', 5.8, 8101, 'tt0810913', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1356285897.jpg', 7, 24.1, 48.4, 15.3, 5.2, '0.096130,-0.193537,-0.826919,0.754196,-0.017383,-0.343930,0.667120,0.324996,-0.329461,-0.104392,0.100314,0.994793,-0.356689,0.171924,0.486377,0.139447,-0.305139,-0.658685,-0.300923,-0.218987,-0.013499,-0.292745,-0.258774,-0.066600,-0.184014,-0.195750,0.546167,-0.323007,0.385175,0.593594,0.822280,0.182298,-0.104070,-0.152328,-0.052253,-0.110235,0.293757,0.180797,-0.607969,0.591294,-0.130745,0.068518,-0.100020,-0.133094,0.079428,0.085311,0.684653,0.001319,-0.088334,-0.000367,0.463145,-0.368957,-0.348892,0.061198,0.387075,-0.052475,0.282261,0.095551,-0.145698,0.029715,0.099973,-0.532118,-0.676920,0.200514,0.278390,0.114304,-0.462200,0.603273,-0.035329,-0.160506,0.089744,-0.242791,0.106928,0.189906,0.137367,0.476513,0.020227,0.316686,-0.238706,0.436132,0.484444,0.126275,-0.155686,0.288594,-0.263140,-0.341356,0.013974,-0.554743,-0.792619,0.256789,0.296654,-0.105888,0.169778,0.370958,-0.533219,-0.053199,-0.173379,-0.214321,-0.056451,-0.393165,0.045026,-0.773890,-0.059113,-0.419190,-0.115603,0.043432,0.108720,-0.236213,0.868717,-0.628387,0.142217,0.312438,0.170288,-0.445123,0.765721,0.195160,0.253614,-0.451800,-0.117426,0.073341,0.105143,-0.265025,0.048509,0.320817,-0.268994,-0.025871,-0.438639,0.313693', '4301278', '1870681', '3811356', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3269068', '精灵旅社', '喜剧', '在阴森恐怖令人谈之色变的幽灵森林深处，耸立着一幢巍峨庄严的古堡。这里的主人正是声名显赫的吸血鬼德古拉（亚当·桑德勒 Adam Sandler 配音）。与传说中不同，德古拉是一个无比温柔的好爸爸，他独自抚养爱女梅菲丝（赛琳娜·戈麦斯 Selena Gomez 配音），为了保护女儿免遭人类的戕害，而特意修建了这座名为尖叫旅社的城堡，普通人类绝对无法接近这里。每年梅菲丝生日之际，科学怪人、狼人、木乃伊、隐形人等怪物都从世界各地赶来为小女孩庆生。在梅菲丝118岁生日之际，她渴望见识外面的世界，早有准备的德古拉设下骗局，却意外将人类少年乔纳森（安迪·萨姆伯格 Andy Samberg 配音）引入古堡。乔纳森的到来似乎为怪物世界带来一股全新的气息，德古拉伯爵则不得不费尽心机隐藏他是人类的真相……©豆瓣', '亚当·桑德勒', '格恩迪·塔塔科夫斯基', 8.1, 247886, 'tt0837562', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2155072056.jpg', 0.2, 1.3, 20.8, 50.9, 26.8, '-0.082638,0.008703,-0.678575,0.464615,-0.203871,-0.005214,0.834409,0.039687,-0.515401,-0.440430,0.332681,0.744656,-0.052691,0.189180,0.274407,0.099396,-0.393902,-0.075986,-0.275923,-0.224092,-0.165936,-0.159157,-0.569530,-0.470093,0.053080,-0.519218,0.499147,0.081183,-0.091179,0.165927,0.041731,0.560695,-0.263407,0.334361,-0.052795,-0.181193,0.330438,-0.168166,-0.242541,0.102891,-0.382362,0.165267,-0.096094,0.353167,-0.286337,0.187156,0.490503,-0.517864,0.135366,-0.413566,0.252435,-0.088630,0.070737,0.053056,0.163849,-0.495445,0.191577,0.182734,0.182428,-0.058354,-0.146753,-0.425901,-0.711926,0.076361,0.242867,0.132276,-0.163730,0.210631,-0.054682,0.027420,0.272656,-0.158209,0.023979,0.057289,0.403280,0.464123,-0.079543,0.050242,-0.398455,-0.085963,0.416699,-0.035601,-0.280158,0.225505,-0.424402,-0.572537,0.046885,0.036276,-0.483169,0.006665,0.156362,0.108483,-0.082137,0.355636,-0.691289,-0.271962,-0.538455,-0.057488,0.058754,-0.239230,-0.499011,-0.584512,-0.012268,-0.009756,0.048284,-0.083252,-0.090744,-0.068358,0.401004,-0.539920,0.313712,0.575374,0.284219,0.037920,0.580928,-0.429342,0.126427,-0.253429,-0.226252,0.451112,0.047769,0.315696,-0.020449,0.075014,-0.054522,-0.037530,-0.340190,0.632047', '3005387', '1293124', '1306666', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3269088', '知无涯者', '剧情', '拉马努金（戴夫·帕特尔 Dev Patel 饰）出生在印度一个非常贫困的家庭之中，从很小的时候起，他就展现出了异于常人的数学天赋，可是因为家境贫寒，家人无法给拉马努金提供一个良好的教育环境。1904年，拉马努金凭借着自己的努力进入了贡伯戈纳姆大学就读，却因为严重偏科而没有毕业，之后的日子里，拉马努金开始自学数学。1912年，拉马努金所撰写的论文《伯努尼数的一些性质》发表了，这篇文章在数学界激起了一些水花，也给拉马努金带来了些许的名声。之后，在好友的帮助下，拉马努金给著名数学家哈代（杰瑞米·艾恩斯 Jeremy Irons 饰）写了自荐信，哈代非常重视这位前途无量的年轻人，引荐他进入了剑桥大学深造。©豆瓣', '杰瑞米·艾恩斯', '马特·布朗', 7.7, 13733, 'tt0787524', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2326716876.jpg', 0.3, 2.9, 28.6, 45.7, 22.4, '0.464125,-0.238041,-0.439237,0.897507,-0.328108,-0.455681,0.624357,0.206434,-0.408516,-0.274862,-0.240430,0.757198,-0.131619,0.386245,0.338446,-0.016601,-0.561642,-0.642338,0.420087,-0.208908,-0.592932,-0.456449,-0.358138,-0.104466,-0.310189,-0.587016,0.478660,-0.136372,-0.571193,0.662204,-0.300735,0.372525,0.450596,0.192377,-0.427679,0.014713,-0.104994,0.206174,0.234800,0.431823,0.275858,-0.311540,-0.233710,-0.112751,0.197949,0.332964,0.419341,-0.054780,0.212407,0.077936,0.587217,-0.416036,-0.109385,0.117277,0.340417,-0.076168,0.162368,0.008585,-0.280032,0.192703,-0.015326,-0.501752,-0.654185,-0.147251,0.183521,-0.036638,-0.827282,0.690007,-0.157897,-0.245710,-0.170610,-0.240312,-0.229884,0.455171,-0.212388,0.657753,-0.098368,0.323879,-0.102177,0.141159,0.169429,-0.484757,-0.165350,0.339389,-0.522284,-0.490823,0.153982,-0.182245,-0.332666,0.025220,0.381302,0.125584,-0.216525,0.173796,-0.551802,-0.090084,-0.305910,-0.199785,0.027003,-0.492724,-0.379671,-0.245305,-0.322856,-0.145496,-0.219711,-0.108270,0.111228,-0.243543,1.052357,-0.665120,0.319327,0.068368,0.082358,-0.309534,0.640609,-0.027421,0.247597,0.038213,0.052019,0.031125,-0.043481,0.607702,0.061799,0.588970,0.272372,-0.588272,-0.119021,0.733938', '27602116', '1870681', '1307146', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3271093', '北壁', '剧情', '1936年纳粹者发起全国青少年挑战阿尔卑斯山背面的活动,很多人都认为那是死亡之墙,但还是有2位德国青少年挑战,而最终失败的故事。 人们在雪山中发现了他们的尸体　其中一人手紧握攥着一个小页血书，上书“给我一套装备。我能爬到中国……”', '本诺·菲尔曼', '菲利普·施特尔茨尔', 8.6, 12939, 'tt0844457', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2572699019.jpg', 0.2, 0.9, 11.3, 46.2, 41.4, '0.310620,-0.096343,-0.649670,0.708096,0.028135,-0.028165,0.470595,-0.166948,-0.475005,0.240946,0.510845,0.738579,0.012883,0.337427,0.130955,-0.033713,-0.085695,-0.532872,-0.029474,-0.217572,-0.907408,-0.237462,-0.437072,-0.454723,-0.272599,-0.323581,0.797559,0.131656,-0.198890,0.344276,0.270688,0.115703,0.231055,0.319717,-0.310333,-0.157563,0.185843,-0.245992,0.042308,0.429224,-0.201615,-0.447944,-0.427795,0.481016,-0.323707,0.391225,0.611728,-0.358109,0.184593,0.092407,0.469463,-0.637981,-0.310406,0.075517,0.674235,0.058252,-0.058857,0.289352,0.058461,0.197753,-0.052329,-0.188502,-0.497800,-0.377386,0.186409,0.391234,-0.640544,0.539956,-0.131297,0.210481,-0.297527,-0.476118,-0.028224,0.204804,0.158592,0.259057,-0.267185,-0.425690,-0.667752,0.259048,0.561491,-0.203353,-0.391456,-0.168860,-0.328358,-0.620952,-0.013395,-0.382637,-0.302409,-0.017949,0.402193,0.011964,-0.243307,-0.058939,-0.896399,0.125074,0.121679,-0.353777,-0.189616,-0.317956,-0.143036,-0.409973,-0.100705,-0.089889,-0.352501,0.338632,0.192208,-0.221272,0.931601,-0.540596,0.169727,0.728306,0.319497,-0.181880,0.782982,-0.029475,0.017805,0.372152,-0.125695,-0.072629,0.010531,0.329082,0.085235,0.393851,-0.030827,-0.351259,-0.213839,0.595160', '26290398', '1302661', '2977870', '35262994');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3274505', '猩球崛起', '剧情', '为了能让身患老年痴呆症的父亲重回正常的生活，威尔·罗曼（詹姆斯·弗兰科 James Franco 饰）一直致力于名为“Cure”的基因药物的开发，并在大猩猩身上不断进行着药物试验。在公司已经失去信心的同时，威尔继续在家完成试验，并在一只名为凯撒的大猩猩身上获得成功。借助灵长类学家卡洛琳（芙蕾达·平托 Freida Pinto 饰）的帮助，威尔发现凯撒的智力极大地提高。不过，人类的社会始终无法接受拥有极高智力的凯撒，凯撒被送往了猩猩看护所。看护所的残酷对待，使得凯撒利用智慧进行抗争，最终救走了同时被囚禁的其他猩猩，而且对它们都使用了Cure。一群高智商的猩猩与人类对立的战争就此拉开。本片获得了第84届奥斯卡最佳视觉效果的提名。©豆瓣', '安迪·瑟金斯', '鲁伯特·瓦耶特', 8.1, 400441, 'tt1318514', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1281402537.jpg', 0.2, 1, 17.6, 53.6, 27.5, '0.110470,0.161658,-0.506648,0.475857,-0.185271,-0.300262,0.517678,0.026944,-0.333209,-0.341733,0.240150,0.658894,0.062804,-0.152613,0.000356,-0.356263,-0.083704,-0.431553,-0.156023,0.287423,-0.469209,-0.547045,-0.580865,-0.104449,-0.142216,-0.628370,0.851360,-0.220980,-0.442175,0.395508,0.087799,0.318651,0.089749,0.191117,-0.095133,-0.283406,0.070568,-0.274172,-0.320459,0.568399,0.069886,-0.062118,0.192219,0.178830,-0.103429,0.078008,0.579179,-0.741374,-0.075913,-0.273745,0.391448,-0.233611,-0.000316,0.186806,0.171306,0.098274,-0.003466,0.251491,-0.018478,0.155506,0.227330,-0.050982,-1.204495,-0.192845,-0.052444,0.228349,-0.632684,0.440261,0.083882,-0.051651,0.152305,-0.152179,-0.057877,0.476080,0.243083,0.541934,-0.345506,0.070881,-0.480355,-0.028591,0.367931,-0.175476,-0.583833,0.314172,-0.235864,-0.604512,-0.157587,-0.484359,-0.214686,-0.228802,0.244382,0.479958,-0.277608,0.315792,-0.761017,0.177010,-0.260187,-0.317073,0.115040,-0.276179,0.296401,-0.890491,-0.128988,-0.337474,-0.329720,-0.128016,0.197825,-0.707674,0.626488,-0.996857,0.407007,0.538190,0.268981,-0.571076,0.416784,0.047810,0.253699,-0.039485,-0.341967,0.548302,0.279106,0.490627,0.070143,0.317434,0.220091,-0.285747,-0.519648,0.602811', '1793491', '26759819', '27073234', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3275168', '单身男子', '剧情', '本片根据美国小说家克里斯托弗·伊舍伍德（Christopher Isherwood）1964年的同名小说改编。故事发生于1962年11月30日的美国加州洛杉矶。中年英语教授乔治·费尔科纳（科林·费斯 Colin Firth 饰）沉浸在与自己十六年共同生活的同性伴侣吉姆（马修·古迪 Matthew Goode 饰）车祸死亡的阴影中无法自拔，精心准备打算自杀。电影记录了乔治从早到晚一天的活动，包括他在学习授课，处理与学生肯尼（尼古拉斯·霍尔特 Nicholas Hoult 饰）的关系，并参加伦敦旧情人夏洛特（朱丽安·摩尔 Julian Moore 饰）私人晚餐的过程。本片获奥斯卡最佳男主角提名（科林·费斯），英国电影电视协会最佳服装设计提名和最佳男主角奖，金球奖最佳男主角提名，最佳女配角提名（朱丽安·摩尔）和最佳原创电影音乐提名，以及威尼斯电影节金狮奖提名和最佳男主角奖。', '科林·费尔斯', '汤姆·福特', 8.5, 102971, 'tt1315981', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1749612217.jpg', 0.2, 1, 12.6, 45.6, 40.7, '-0.438746,-0.431524,-0.312521,0.621130,0.497450,-0.335713,0.456804,0.025692,-0.387116,-0.464260,0.042024,1.120811,-0.481186,0.211087,0.877324,-0.313694,-1.026790,-0.831168,-0.101152,-0.138844,0.148983,-0.667462,-0.245385,-0.087446,-0.010476,-0.588499,0.892682,-0.467202,-0.084689,0.620818,0.764312,0.054697,-0.247203,-0.368961,0.338896,0.204134,0.605428,-0.190834,-0.918583,0.596281,0.025147,-0.191010,-0.334799,-0.126317,0.461663,0.150190,0.739488,0.023480,0.176209,0.026031,0.830603,-0.378432,-0.220856,-0.001516,0.168621,-0.176021,0.562240,0.429937,0.133076,-0.046903,0.023210,-0.519299,-0.582575,0.274022,0.046204,0.373293,0.001819,0.291911,-0.177635,0.349745,-0.108695,0.118182,0.088120,0.189150,0.477177,-0.062812,0.074648,-0.121673,-0.093039,1.012548,0.183519,-0.085242,-0.305065,0.434330,-0.011185,-0.770030,-0.305077,-0.087951,-0.580709,0.206370,0.441335,-0.007693,0.244872,0.105216,-0.195252,-0.082176,0.110158,-0.416207,0.192462,-0.014630,0.288419,-1.480970,-0.063314,-0.046793,-0.071708,-0.529557,0.204712,-0.229697,0.484966,-0.491208,0.489228,0.520738,0.010773,-0.260549,0.904014,0.121338,0.311245,-0.343031,-0.278690,0.259687,-0.193999,-0.224116,-0.160838,0.311189,0.128703,-0.489022,-0.490889,0.332390', '34961898', '1298616', '3077791', '2075345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3279054', '老男孩', '剧情', '1993年，粗鲁张扬的男人约瑟夫·杜森特（乔什·布洛林 Josh Brolin 饰）在深夜遭人绑架。当他醒来时，发现身处一个完全封闭的房间。每天有人按时送来一成不变的饺子，却没人告诉他为什么将其囚禁在这里。他愤怒、沮丧、绝望、哀伤，通过房间里的电视机，得知前妻堂娜·霍桑被人残忍杀害、年仅三岁的女儿米娅被人收养的消息，而自己则背负了杀人犯的罪名。万念俱灰的约瑟夫求死不能，为了女儿他锻炼身体，试图从牢笼中逃脱。漫长的二十年过去，体格健硕的约瑟夫又意外地被人释放。他求助于好朋友恰吉（迈克尔·因佩里奥利 Michael Imperioli 饰），并得到了美丽女孩玛丽的帮助（伊丽莎白·奥尔森 Elizabeth Olsen 饰）。约瑟夫靠着仅有的线索追查自己被囚禁的原因，而他也终于逼近那个可怕的真相……©豆瓣', '乔什·布洛林', '斯派克·李', 6.5, 20355, 'tt1321511', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2030389813.jpg', 2.3, 12.1, 50.7, 26.7, 8.2, '0.070291,0.030998,-0.721809,0.306305,-0.494205,-0.191322,0.964181,0.043663,-0.638577,-0.343747,0.261898,0.505937,-0.026785,0.308636,0.164447,0.362616,-0.367220,-0.535179,0.209434,-0.237757,-0.298743,-0.280460,-0.226924,-0.513898,0.183021,-0.360257,0.409271,0.038536,-0.042972,0.213511,0.290213,0.290833,-0.056057,0.653313,0.025283,0.138355,0.115127,-0.216608,0.102721,0.028015,-0.108029,-0.528789,-0.167404,0.322634,-0.147127,0.463027,0.582536,-0.203533,-0.165369,-0.115605,0.220181,-0.300938,-0.236120,0.233654,0.152090,-0.077914,0.053006,0.259610,-0.270172,-0.200499,0.113171,-0.078044,-0.732070,0.124436,0.107325,-0.006265,-0.350575,0.397977,-0.330107,0.198357,0.128610,-0.473870,0.053275,0.044987,0.062257,0.454096,-0.253091,0.071471,-0.585755,0.029594,0.367579,-0.220437,-0.277256,0.193232,-0.308246,-0.233227,0.165709,-0.341447,-0.502148,0.110661,0.502548,0.163960,-0.425686,0.145361,-0.181763,-0.279912,-0.397205,-0.046834,-0.223673,-0.374810,-0.453994,-0.164260,-0.099631,0.020214,-0.266210,-0.030259,-0.133574,-0.283033,0.472252,-0.343489,0.514296,0.620391,0.294395,-0.266016,0.516082,-0.160984,0.061117,-0.221430,-0.260199,0.664726,0.303982,0.169473,0.256291,0.131802,-0.195025,0.089792,-0.507957,0.535587', '2977957', '1421570', '1309171', '25917973');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3279069', '葬礼上的死亡', '喜剧', '本片为2007年弗兰克·奥兹执导《葬礼上的死亡》的翻拍片，这部黑人班底的喜剧片做了不少适合于美国和黑人文化的移植。艾伦（克里斯·洛克 Chris Rock 饰）的父亲突然死亡，这让原本分布设在各地的亲友聚集在了一起。亲友们带着各自令人烦躁的焦虑抵达墓地，一个个问题也接 踵而来。一早运送的棺材的人就弄错了遗体；轻浮、爱吹牛的作家哥哥莱恩（马丁·劳伦斯 Martin Lawrence 饰）远道而来；堂姐第一次带未婚夫奥斯卡（詹姆斯·麦斯登 James Marsden 饰）出现在家人面前，希望能给父亲留下一个好的印象，可奥斯卡误食了迷幻药high翻了天。接着一个神秘来客自称掌握着一个可以粉碎死者生前信仰的惊天大秘密，并威胁着要在所有人面前将其揭穿，不和的两兄弟为了让父亲安息终于团结起来。到底过世的父亲有什么不可告人的隐秘？葬礼上还会新的麻烦吗？©豆瓣', '佐伊·索尔达娜', '尼尔·拉布特', 6.6, 8953, 'tt1321509', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2540478126.jpg', 2.7, 11.7, 48.7, 28.4, 8.5, '0.229956,-0.021877,-0.565015,0.638425,-0.018839,-0.371169,0.714149,0.143618,-0.365702,-0.216386,-0.001878,0.939418,-0.080590,0.229462,0.329639,0.180449,-0.324515,-0.588449,-0.304576,-0.097315,-0.521184,-0.626047,-0.414504,-0.388952,-0.043966,-0.178537,0.247572,0.105664,0.064075,0.463190,0.463831,0.260550,-0.149157,0.376252,-0.379930,0.008035,-0.048793,-0.036276,-0.246769,0.255437,0.007136,-0.160126,0.018757,0.239851,-0.031001,0.319245,0.437024,-0.131174,-0.092956,-0.126143,0.266059,-0.170887,0.097088,0.099931,0.103526,-0.073566,0.273681,0.251816,-0.123541,0.101098,0.177136,-0.081835,-0.899347,-0.069683,0.082597,0.148224,-0.723172,0.476633,-0.040637,-0.114420,0.090524,-0.249604,0.486459,0.462877,-0.006961,0.401360,-0.112948,0.022367,-0.451957,0.196776,0.399479,-0.232799,0.068202,0.090238,-0.190557,-0.227026,-0.039867,-0.073272,-0.462130,0.088300,0.303205,0.066673,-0.057041,0.016233,-0.588708,-0.237655,-0.103560,-0.162532,0.046375,-0.373193,-0.033660,-0.428210,-0.091175,-0.126545,-0.304021,0.003697,0.199650,-0.049449,0.711857,-0.555844,0.492005,0.578836,0.202481,-0.445166,0.535272,0.274053,-0.016929,-0.133819,-0.306547,-0.092999,0.055848,0.302669,0.163989,0.281876,0.121922,-0.300803,-0.332240,0.291528', '3119246', '348