INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3279080', '敢死队', '动作', '其貌不扬的退伍老兵巴尼·罗斯（西尔维斯特·史泰龙 Sylvester Stallone 饰）生活在城市的某个角落，事实上他却是一支特种兵的领袖，其麾下云集了李（杰森·斯坦森 Jason Statham 饰）、杨（李连杰 Jet Li 饰）等一众高手。正所谓艺高人胆大，只要酬金给足，再危险的任务也敢接。这天，来自中情局的教堂先生（布鲁斯·威利斯 Bruce Willis 饰）联系到巴尼，雇用他们前往位于南美的比莱纳岛，铲除与美国政府作对的独裁将军加尔萨（David Zayas 饰）。由于任务艰险，巴尼和李先行探路，发现加尔萨与前中情局官员詹姆斯·门罗相互勾结，残酷压榨比莱纳岛的人民。不久巴尼和他的战友赶赴小岛，而更大的挑战正等待着这群骁勇的战士们……©豆瓣', '西尔维斯特·史泰龙', '西尔维斯特·史泰龙', 6.9, 178580, 'tt1320253', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p547574189.jpg', 1.3, 7.2, 46.9, 33.5, 11.1, '0.116367,-0.142051,-0.806789,0.703604,-0.056032,-0.336050,0.636415,0.117194,-0.369498,-0.281693,0.239941,0.534568,0.224810,-0.061651,0.420987,-0.378171,-0.437762,-0.520720,-0.214696,-0.321207,-0.421820,-0.464597,-0.397791,-0.419967,-0.112759,-0.236384,0.612226,0.016393,-0.251041,0.387244,0.361370,0.371011,0.047054,0.450444,-0.248882,-0.206239,0.329344,-0.069570,-0.427372,-0.023876,-0.272649,0.005836,-0.313111,-0.175031,0.395882,0.284268,0.441295,-0.271424,0.061416,-0.195199,-0.225921,-0.277813,0.156684,-0.059206,0.579418,-0.236359,0.178670,0.035829,0.076830,-0.039009,-0.042484,-0.213210,-0.617686,0.032525,0.283409,0.244820,-0.512908,0.236236,-0.311518,0.023637,0.043249,-0.321207,0.125683,0.589765,0.017793,0.191614,0.200470,0.013269,-0.455191,0.113048,0.603062,0.110377,0.015716,-0.553539,-0.043438,-0.583729,-0.009962,-0.157527,-0.374102,-0.153765,0.415504,-0.582071,0.336039,0.397858,-0.771854,-0.061148,-0.277013,-0.256922,-0.041999,-0.353439,0.145951,-1.043457,0.179451,-0.277506,0.031798,0.475271,0.401596,0.050635,0.756402,-0.581171,0.227922,0.334556,0.416690,-0.500152,0.447604,0.082517,0.347404,-0.302517,-0.328070,0.364535,0.460588,0.483000,0.111953,0.448698,-0.072513,-0.452613,-0.241097,0.271628', '1307897', '1294917', '20274039', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3279093', '格列佛游记', '喜剧', '本片改编自英国作家斯威夫特的同名小说，讲述了格列佛在小人国的奇遇故事。格列佛（杰克·布莱克 Jack Black 饰）是一个公司邮政室小职员，岁数也不小，可事业和爱情却都一无所成，平时唯一的爱好就是星球大战玩偶作伴。一次阴差阳错的公派任务，把他带到了百慕大群岛，不料，出海即遭遇到大风暴。待一切风平浪静之后发现自己来到了一个地图上没有的神秘小岛Lilliput，这里住着成百上千“小人”。而自己正被他们用无数根绳子“钉”在了海滩上，成为了他们俘虏。但久而久之，小人国的人民和格列佛变成了好朋友。此时公主（艾米莉·布朗特 Emily Blunt）将被下嫁到另一个国家，但她已有了青梅竹马的爱人，格列佛出面化解了两国的纠纷，还帮助公主和爱人完成终身大事。格列佛因而变成了这里的英雄人物，而这段经历也让他明白了人类的内心的强大与否无关外表。©豆瓣', '杰克·布莱克', '罗伯·莱特曼', 6.1, 23600, 'tt1320261', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p687069077.jpg', 2.9, 17.1, 56.5, 18.7, 4.7, '0.358273,0.071657,-0.686295,0.711408,-0.215692,-0.221369,0.794724,0.117745,-0.537646,-0.079604,0.141889,0.927058,-0.232930,0.252116,0.100313,0.244221,-0.222231,-0.651051,-0.121388,-0.289784,-0.440387,-0.495382,-0.247345,-0.203669,-0.218096,-0.295587,0.629085,0.065723,-0.063499,0.203517,0.274863,0.082822,-0.099221,0.538219,-0.354702,0.246759,0.069885,0.120017,-0.026816,0.250610,0.035490,-0.180151,-0.004068,0.308416,-0.056444,0.278820,0.731154,-0.264994,-0.114569,-0.086537,0.396876,-0.361372,0.034564,0.043158,0.346583,-0.023597,0.235433,0.035634,-0.121563,-0.171301,0.300270,-0.328233,-0.564871,0.010839,-0.107719,0.088190,-0.806218,0.533868,-0.070450,-0.150440,-0.065901,-0.484051,0.330659,0.390747,0.341935,0.264844,-0.250182,0.000744,-0.730268,0.227499,0.752804,-0.022801,-0.351772,0.401383,-0.163338,-0.393289,-0.087616,-0.378386,-0.327769,-0.033650,0.248144,-0.129153,-0.453067,0.258720,-0.641961,0.009529,-0.487556,-0.142439,0.047719,-0.706537,0.029332,-0.422554,-0.343099,-0.410730,-0.316408,0.063400,0.290929,-0.326079,0.948821,-0.690458,0.148470,0.718183,0.217762,-0.383123,0.816660,0.016159,0.212108,-0.006928,0.196801,0.037105,0.073244,0.423540,0.358027,0.348819,-0.041253,-0.067798,-0.471821,0.446128', '30162520', '1456503', '3055049', '1783772');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3279107', '大兵小将', '喜剧', '公元前227年，卫国军队在凤凰山遭遇梁军伏击，血战之后惟有受重伤的卫国大将军（王力宏 饰）和装死的梁国士兵（成龙 饰）二人存活。将军有着统一诸国的宏图壮志，而小兵只想过自己的太平日子。小兵活捉大将，企图带着大将回到梁国，换良田五亩从此过上永无兵役的幸福生活。从凤凰山到梁国的路上，前有无数未知风险，后有卫国神秘小队追踪，小兵靠着美好信念的支撑以及自己的小聪明一次次化解危机，然而，在到达梁国之时小兵却出人意料的放大将返回卫国。小兵在江畔目送大将驾小舟渐渐远去，可是他并不知道在身后梁国的土地上，发生了一场天翻地覆的变化……©豆瓣', '成龙', '丁晟', 6.8, 147717, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1682724960.jpg', 1.3, 8.1, 46.9, 35.1, 8.7, '0.032430,0.051112,-0.656754,0.235126,0.372145,-0.073760,0.571656,0.398406,-0.805682,-0.010832,0.756514,0.311305,0.066626,-0.312829,0.480219,-0.286430,-0.303268,-0.594606,-0.041385,0.014867,-0.151618,-0.311886,-0.408289,-0.009167,-0.077645,-0.474319,0.775022,0.141553,0.091360,0.799543,-0.197932,0.156820,-0.286886,0.678272,-0.160858,0.388168,-0.016314,-0.057838,-0.568638,0.301502,-0.156596,-0.424905,-0.313461,-0.244095,-0.208999,0.151286,0.899133,-0.527521,-0.004276,0.111332,-0.091488,-0.370676,-0.119527,0.080660,0.219261,0.270006,-0.006390,0.427689,0.054562,-0.053615,-0.036130,0.058491,-0.311774,-0.139481,-0.119331,0.314470,-0.695518,0.787122,0.023805,-0.157958,0.263229,-0.499631,0.276048,0.672114,0.022834,0.186321,-0.308705,0.121610,-0.693334,0.161417,0.837089,-0.212107,-0.162600,-0.061432,0.283270,-0.200576,0.098228,-0.504940,-0.444775,-0.059853,0.123770,-0.066283,-0.135489,0.295385,-0.542451,0.305472,-0.591639,-0.076925,0.242900,-0.033152,-0.300227,-0.188413,-0.140914,-0.272587,-0.199454,0.370822,0.193820,0.056949,0.493552,-0.716628,0.189756,0.373732,0.404307,-0.208624,0.370598,-0.056487,0.173468,0.023341,-0.072845,0.058338,-0.023522,0.712114,0.110995,0.106108,-0.572567,-0.244159,-0.222785,0.206712', '35030151', '1301562', '26418093', '3230460');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3280079', '剑蝶', '动作', '十世相爱十世分，他们本是玉帝身边的金童玉女，因为相爱而被贬下凡间，要遭受十世的折磨。故事开始在第十世。祝家千金言之（蔡卓妍 饰）奉父母之命女扮男装前往逍遥派学艺，路上遭遇险境无数犹自未觉，幸得梁仲山（吴尊 饰）和随后赶来的马承恩（胡歌 饰）出手相救。江湖险恶对祝言之来说完全是抽象的概念，承恩把言之送到逍遥派便赴京复命。在逍遥派练功玩耍的日子，言之与仲山逐渐亲密，草头师叔（庾澄庆 饰）炼丹试验假死时言之上山采摘假药摔倒昏迷，仲山惊觉她是女儿身，惊讶之余又感到甜蜜。这对刚刚坠入爱河的小情人马上迎来了从京城赶回来的马承恩，承恩让言之马上回家。对未来的变故浑然不觉的言之和仲山约定好在家等候他来提亲。然而这对小情人等来的是一个精心设计的骗局。©豆瓣', '吴尊', '马楚成', 5, 22524, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2255619105.jpg', 16, 35.4, 37.5, 7.2, 3.8, '0.170650,-0.101658,-0.729037,0.457733,0.040688,-0.285087,0.641597,0.295902,-0.397734,-0.394363,0.150351,0.825612,-0.416060,0.256305,0.334607,-0.082034,0.127253,-0.701179,-0.074127,-0.321222,0.062783,-0.212811,0.232060,0.223222,-0.203033,-0.099109,0.229972,0.081113,0.063802,0.865045,0.216340,0.241128,-0.111678,0.349102,-0.393836,0.058413,-0.221145,0.328396,-0.479695,-0.021494,-0.015367,-0.269179,-0.195575,0.017789,-0.159201,0.318583,0.478111,-0.233295,-0.237937,-0.303335,0.354599,-0.259749,0.338387,0.153460,0.156820,0.117657,0.181625,0.219084,-0.157498,0.230901,0.048872,-0.115900,-0.429828,0.205120,-0.003621,0.060836,-0.594472,0.080769,0.028753,-0.044267,-0.061267,-0.323773,0.292649,0.544255,0.225851,0.311484,0.050190,-0.119058,-0.244052,-0.015086,0.598614,-0.241116,0.042639,0.621601,0.386164,-0.351991,0.545930,-0.050740,-0.422800,0.045254,0.165930,0.142627,0.000904,0.236226,-0.385444,-0.027142,-0.186422,0.196458,-0.000904,-0.177927,-0.104198,-0.518716,-0.166605,-0.280300,-0.534296,-0.076800,0.425831,-0.242595,0.514759,-0.646005,0.282881,0.268113,0.248016,-0.881925,0.553074,0.322886,0.224987,-0.058446,0.161789,0.238166,-0.037485,0.497769,-0.092640,0.220327,-0.105424,0.117457,-0.868265,0.035155', '1303333', '1451563', '1304600', '1307755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3282392', '海狸', '剧情', '沃尔特（梅尔·吉布森 Mel Gibson 饰）曾经是一名事业有成的玩具公司总裁，然而金融危机的重创让他不仅濒临破产，还患上了忧郁症，负能量感染着每一个家庭成员，妻子梅瑞迪斯（朱迪·福斯特 Jodie Foster 饰）在百般无奈的情况下只好让其搬出去住。意志消沉的沃尔特开始买醉度日，就在一次自杀未遂之后，他发现自己手上竟然套着一只海狸布偶，这只布偶还开始喋喋不休地与他对话。在与海狸博弈的过程中，沃尔特又渐渐拾回了生活的勇气，然而他却似乎再也离不开对海狸的依赖。妻子对他的振作喜忧参半又无可奈何，沃尔特是否才是那个真正被海狸操控的布偶，他又如何才能回归常人的生活呢？©豆瓣', '梅尔·吉布森', '朱迪·福斯特', 6.8, 5575, 'tt1321860', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1162761273.jpg', 0.8, 6.9, 50.3, 33.3, 8.6, '-0.003996,0.029921,-0.662031,0.577015,-0.310973,-0.595781,0.919507,0.264887,-0.382302,-0.082503,0.290238,0.688367,-0.164641,0.499910,-0.058538,0.271084,-0.320340,-0.766935,0.147324,0.275543,-0.266977,-0.253794,-0.495358,-0.165238,0.142612,-0.361024,0.550687,0.057823,-0.190838,0.086043,0.311674,0.245338,-0.033059,0.725341,-0.428209,0.124121,-0.057332,0.102476,0.020667,0.085113,0.257099,-0.523539,-0.152305,0.424414,-0.075039,0.303192,0.754661,-0.534053,-0.178843,-0.101134,0.267993,-0.152353,-0.071198,0.203511,0.142742,0.031012,0.054791,0.047885,-0.367150,0.216930,0.154148,0.166566,-0.684404,-0.035400,-0.172411,0.231891,-0.684125,0.438761,-0.050348,-0.026930,-0.122831,-0.392367,-0.058138,0.415242,0.016069,0.544387,-0.474807,0.022775,-0.613371,0.068032,0.473002,0.053019,-0.390638,0.558148,-0.080731,-0.611169,-0.157634,-0.271934,-0.579644,-0.311038,0.244351,0.269579,-0.295271,0.255412,-0.590616,0.269961,-0.391706,-0.296267,-0.153472,-0.349474,0.153245,-0.368361,-0.127660,-0.400098,-0.335093,-0.045178,0.186466,-0.375129,0.631069,-0.635704,0.323161,0.575990,0.159783,-0.335898,0.239849,0.229697,0.186051,-0.074787,0.005309,0.364561,-0.014448,0.278827,0.438341,0.338281,0.100223,0.202635,-0.278265,0.789659', '21619567', '21348112', '24756472', '25763555');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3282396', '匪帮传奇', '剧情', '20世纪40年代，前拳击冠军Mickey Cohen（西恩·潘 Sean Penn 饰）是洛杉矶最有势力的黑帮老大，他一边经营着卖淫、赌博等活动，一边贿赂洛杉矶警方和法官，在洛杉矶为非作歹，为霸一方。洛杉矶警官John O''Mara（乔什·布洛林 Josh Brolin 饰）嫉恶如仇，从来没有畏惧过Micky，刚刚破坏了他的一个卖淫窝点。这一次，洛杉矶警长Bill Parker决定对Micky展开决战，他让John组织一个秘密小组，以铲除Micky为目标。John在妻子的建议下，找到了他在警局的朋友Jerry（瑞恩·高斯林 Ryan Gosling 饰），同时也是Micky的情人Grace（艾玛·斯通 Emma Stone 饰）的男朋友；神枪手Max Kennard；同样嫉恶如仇的黑人警察Coleman Harris；前情报机关人员Conwell Keeler；Max的徒弟，墨西哥人Navidad Ramirez，组成了Gangster Squad。他们在Micky家中安装了窃听装置，多次破坏Micky的行动，捣毁了他的多个赌博窝点。他们本以为胜券在握，不料真正的战斗才刚刚开始......', '乔什·布洛林', '鲁本·弗雷斯彻', 6.5, 15413, 'tt1321870', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1867317599.jpg', 1.1, 10.9, 54, 27.8, 6.2, '0.114079,-0.130540,-0.609038,0.629929,-0.193546,-0.213582,0.614682,0.002335,-0.445892,-0.160848,0.369276,0.501898,-0.071132,0.033961,0.253418,-0.087325,-0.417863,-0.725407,-0.263295,-0.187010,-0.437169,-0.529467,-0.416238,-0.376014,0.078270,-0.059420,0.358187,0.120100,-0.171493,0.133469,0.421235,0.210942,-0.055106,0.384290,-0.210228,-0.072252,0.393412,-0.232580,-0.528710,0.428988,0.041946,-0.200658,-0.116420,0.277848,0.144873,0.543674,0.590445,-0.307449,-0.053465,-0.302049,0.056113,-0.127978,-0.029069,-0.124828,0.549473,-0.079600,0.135128,0.296860,-0.056246,-0.063883,0.227269,-0.052193,-0.756694,-0.059154,0.101087,-0.026690,-0.530526,0.513921,-0.347071,0.323572,-0.109421,-0.226241,0.304385,0.513534,0.282770,-0.113791,0.039234,0.150937,-0.608120,0.315261,0.577833,-0.009381,0.052022,-0.005916,-0.086709,-0.438765,-0.089648,-0.260646,-0.326467,-0.171781,0.392249,-0.414409,-0.080731,-0.070457,-0.538094,-0.143704,-0.163554,-0.019646,0.041153,-0.400232,0.063147,-0.724845,0.010971,-0.152487,-0.169410,0.240121,-0.204854,-0.078956,0.519387,-1.018466,0.086516,0.858642,0.258958,-0.527315,0.560733,0.189741,0.082592,-0.466710,-0.225799,-0.091770,0.292194,0.501771,0.232467,0.416702,0.165381,-0.441167,-0.051878,0.326925', '1307442', '1292829', '1986338', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3284257', 'BABY BLUE', '剧情', '这是一个甜美却酸涩的青春爱情故事。男孩在搬家前一天，邀请曾经青梅竹马的女孩一起随便走走，女孩欣然答应。于是两人踏上了前往海边放烟花的旅程。电车上，男孩提起儿时他们之间的一个秘密——共同偷了一枚手榴弹。两人相约找个地方把它埋掉。男孩和女孩，一路上刺激地骑着偷来的自行车，又跟暴走族斗智斗勇。终于来到了海边时，烟花却没能放成。两人相互表白，可这注定是一段无疾而终的爱情。最终，火车还是轰鸣地带着男孩去了远方。突然间在黑暗中，出现了一个熟悉的身影，两串璀璨的烟火。©豆瓣', '柳乐优弥', '渡边信一郎', 8.6, 9358, '淡蓝色', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2189926585.jpg', 0.3, 1.1, 13.4, 40, 45.2, '0.566010,0.114017,-0.814727,0.574875,0.111096,-0.451491,0.930910,0.139663,-0.114190,0.337970,0.168394,0.776979,-0.347044,0.556959,0.427617,0.275849,-0.475835,-0.681559,0.038635,-0.367352,-0.306090,-0.344418,-0.104985,0.340613,0.106977,0.178680,0.496635,0.221595,0.071444,0.708442,0.275387,-0.240730,-0.559601,0.615625,-0.547832,-0.138140,-0.008440,0.325583,-0.153446,0.201749,-0.105900,-0.415672,0.024284,-0.368778,-0.215936,0.038565,0.796947,-0.387054,0.149811,-0.036682,-0.065813,0.072447,-0.171168,-0.067988,0.182623,0.123455,0.454486,-0.217956,-0.076845,-0.107690,0.213548,-0.084028,0.117663,0.179901,-0.045753,0.107897,-0.722871,0.564494,0.394657,-0.038317,0.479941,-0.360468,0.481034,0.114925,0.256800,0.305592,-0.321020,0.198648,-0.277189,0.163784,0.769398,0.108519,0.022411,0.347940,-0.276591,-0.295297,0.021454,0.399236,-0.555086,0.023735,0.563055,0.037555,-0.399388,0.079181,-0.948371,0.179137,-0.082679,0.142889,0.100020,-0.511504,-0.306041,-0.574665,0.140916,-0.267299,-0.244360,0.351126,-0.110877,0.110598,0.625317,-0.407768,0.177592,0.720419,0.173813,0.151741,0.661935,0.011654,0.161669,-0.096417,0.232078,0.049714,-0.166850,0.368600,0.160166,0.500550,-0.294707,0.387475,-0.562641,0.332912', '1296534', '21619567', '1316560', '1293019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3284396', '远距离爱情', '喜剧', 'Erin（德鲁·巴里摩尔 Drew Barrymore 饰）和Garrett（贾斯汀·朗 Justin Long 饰）在灯红酒绿酒吧邂逅，两个青年对彼此人敞开了心胸，喝酒谈心度过了无比浪漫的美好一夜。第二天两人甚至还一块吃了早餐，火花就这样在两人中间闪现了。经过一段短暂但又甜蜜的时光，他们不得不面对一个严重的现实问题——Erin的家在旧金山，而Garrett的事业在纽约，但是他们两个都谁不愿意放弃现有的一切，更加舍不得让这段关系结束。于是，他们凭借着手机和各式通信工具开始了一场“远距离的恋爱”。而最后他们的工作跟感情不能兼顾？是否又会为了对方放下一切来成全这一段感情？©豆瓣', '贾斯汀·朗', '纳内特·波斯特恩', 6.8, 22626, 'tt1322312', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p596552058.jpg', 0.7, 6.7, 52.6, 33, 6.9, '0.340152,0.102010,-0.774446,0.578587,-0.065169,-0.464083,0.815932,0.148786,-0.386712,-0.220909,-0.088932,0.794239,-0.346792,0.300552,0.192365,-0.126569,-0.507220,-0.780954,0.219929,-0.112153,-0.258929,-0.586172,-0.013062,-0.322331,-0.062498,0.038161,0.478334,0.214282,0.064868,0.481855,0.225719,-0.227762,-0.212906,0.754014,-0.218867,-0.119262,0.007256,0.351066,-0.536023,-0.003521,0.300969,-0.231362,-0.255457,0.407695,0.061672,0.036819,0.696282,0.032354,-0.274978,0.244882,0.051760,-0.263189,-0.058899,0.141108,0.225420,-0.253003,0.424222,0.318505,-0.309927,-0.003944,0.020317,0.034002,-0.740235,0.003030,-0.224945,-0.022535,-0.562166,0.700334,-0.044252,-0.243761,0.072503,-0.336831,0.180447,0.693692,0.599061,0.417183,-0.326054,-0.387131,-0.590231,0.109465,0.973112,-0.032508,-0.193696,0.745865,-0.188929,-0.323075,-0.464331,0.012159,-0.482050,-0.160234,0.367915,0.073853,-0.264336,0.221943,-0.902128,0.241864,-0.126015,-0.283146,0.157215,-0.699342,0.126479,-0.711913,-0.147702,-0.613550,-0.698653,0.311655,0.188626,-0.069885,0.675393,-0.859564,0.071153,0.453459,0.129924,-0.426724,0.592239,0.499214,0.211178,-0.198624,0.129524,0.023887,-0.040499,0.175515,0.405017,0.538738,-0.028475,0.341014,-0.654975,0.491431', '11541282', '1301022', '34429100', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3284768', '最后一次驱魔', '惊悚', '坐落在路易斯安那州的巴顿鲁治郡，生活着一个名叫柯登·马可斯（帕特里克·法比安 Patrick Fabian 饰）的年轻牧师，他自幼跟随父亲学习圣经，其布道的风格独特，倍受欢迎，但与他来说终究只是一项营生；在家中柯登则是个好丈夫和好父亲，与妻儿过着幸福的生活。马可斯家族同 时也是有着丰富经验的驱魔世家，然而一些虚伪的驱魔仪式令柯登倍感苦恼。他于是请来摄制组拍摄纪录片，旨在揭露驱魔仪式中的骗人行径。恰好此时，另一个州的艾凡伍家来信求助。柯登决定将其作为自己最后一次的驱魔，他和摄制组驱车前往，并顺利为女孩奈儿做了驱魔仪式。然而，一切并未就此结束，恐怖的事情接二连三发生……©豆瓣', '帕特里克·法比安', '丹尼尔·斯坦', 6.4, 7275, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p492237985.jpg', 3.5, 14.3, 49.1, 26.4, 6.8, '0.252279,-0.100990,-0.601806,0.844567,-0.109298,0.018989,0.648370,0.060684,-0.664611,-0.659145,0.134384,1.088688,0.169578,0.282777,0.198950,0.047034,-0.263558,-0.577710,0.003745,0.022205,-0.116284,-0.467748,-0.069111,-0.237285,-0.226209,-0.467808,0.450304,0.122548,-0.011768,0.484073,0.255521,0.311711,-0.266242,0.340064,-0.290812,-0.210071,0.123320,0.105138,-0.314238,0.050232,0.100915,-0.102959,-0.329641,0.283961,0.128992,0.419071,0.381689,-0.377940,-0.350003,-0.221234,0.238548,-0.225135,-0.075167,0.173670,0.106760,0.178367,0.325637,0.365482,-0.140831,-0.006148,0.034928,-0.293619,-0.851057,-0.103656,0.145869,-0.049317,-0.746797,0.643926,-0.069467,-0.160718,0.013736,-0.442123,0.238453,0.389591,0.313579,0.175564,-0.189076,0.061202,-0.370015,0.327528,0.795701,0.142749,-0.168537,0.390465,-0.264785,-0.430576,0.122615,-0.357804,-0.478954,0.172098,0.133935,0.134188,-0.007194,0.163118,-0.401443,-0.059330,-0.171267,-0.195638,0.096839,-0.404959,0.015675,-0.760618,0.003762,-0.370173,-0.485951,-0.236862,0.113773,-0.319590,0.853485,-0.888822,0.283674,0.341634,0.106107,-0.571222,0.687698,0.246696,0.463236,-0.081149,-0.228971,0.117430,-0.060120,0.186033,0.014997,0.314411,0.049313,-0.220005,-0.183087,0.516434', '30162520', '4301278', '1870681', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3285050', '蒙羞之旅', '喜剧', '当你搞砸了好不容易得来的宝贵机会，面对排山倒海而来的挫败和失落感，你会做出怎样的应对呢？一心想成为著名主持人的梅根（伊丽莎白·班克斯 Elizabeth Banks 饰）觉得是时候来一场喧闹而又疯狂的派对了。在派对上，梅根遇见了名为戈登（詹姆斯·麦斯登 James Marsden 饰），两人之间眉来眼去，温度火速上升，一个充满了浪漫和激情的夜晚就在眼前！春宵一夜过后，来自经纪人的电话将还沉醉在粉色气息之中的梅根拉回了现实，一个工作上一举成名的大好机会到来了。然而，此时的梅根才发现，自己的车被拖走，钱包和所有证件全都随之而去。眼看着面试时间就要到来，能否准时出现在面试现场还是个问题的梅根能够抓住这次千载难逢的转机吗？©豆瓣', '伊丽莎白·班克斯', '史蒂文·布里尔', 6.3, 10595, 'tt2463288', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2166580754.jpg', 2.7, 13.7, 54.9, 22.5, 6.1, '0.127454,0.386506,-0.806749,0.464816,0.024030,-0.297932,0.792114,0.142019,-0.354655,-0.222988,-0.073876,0.698938,-0.596932,0.364019,0.585759,-0.017717,-0.337155,-1.050449,-0.259383,-0.095395,-0.505107,-0.287101,-0.145789,-0.029038,0.313562,-0.101533,0.214454,0.147161,-0.125110,0.561002,0.630434,0.192092,0.033172,0.838169,-0.114337,-0.175589,0.229017,0.009138,-0.078023,0.427212,0.314969,-0.402953,-0.019599,0.306898,-0.031318,0.163161,0.739894,-0.100227,-0.124793,0.227608,0.330706,-0.302391,0.021854,0.042605,0.070131,0.032956,0.058773,-0.089455,-0.317759,-0.023580,0.101810,-0.265405,-0.701451,0.364169,-0.298977,0.159453,-0.477256,0.293958,0.087630,-0.141022,0.156445,-0.489049,0.275347,0.360862,0.329324,0.533050,-0.165761,-0.038080,-0.534046,0.002829,0.742939,0.079452,-0.008199,0.513088,0.027578,-0.422621,-0.026346,0.058644,-0.444646,-0.115775,0.596234,0.160551,-0.129998,0.016634,-0.602624,0.026863,-0.311729,-0.332784,-0.122987,-0.420991,-0.132310,-0.552127,-0.130992,-0.084138,-0.400027,0.319290,0.129975,-0.156932,0.549995,-0.830755,0.281028,0.607629,-0.002037,-0.164514,0.622077,0.159456,-0.075850,0.098434,0.043017,-0.144770,-0.013279,0.348224,0.174629,0.404045,-0.168756,-0.133025,-0.343601,0.608877', '1301022', '34429100', '3027015', '1293142');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3285073', '王子殿下', '喜剧', '在传说中的年代，黄金骑士团在斩妖除魔后留下了一百年后双月同蚀时，世间会出现如他们一般的英雄的预言……时光荏苒，莫恩王国有两位性格迥异的王子，王位继承者法拜斯（詹姆斯•爱德华多•弗兰科 James Edward Franco 饰）英雄善战，深孚众望；二王子泰德斯（丹尼•麦克布耐德 Danny McBride 饰）则擅长搞砸任何任务，并且因长久以来人们对他的忽视而心生不满，满腹牢骚。法拜斯王子在讨伐邪恶法师“毒蜥”时救回了被常年囚禁的少女贝拉多娜（佐伊•丹斯切尔 Zooey Deschanel 饰），并计划与后者成婚，毒蜥赶到婚礼现场将贝拉多娜掳走以完成生下巨龙的仪式。法拜斯带着颇不情愿的泰德斯踏上了二度救回贝拉多娜的征途，根据传说，取得独角兽之剑是他们战胜毒蜥的唯一机会……©豆瓣', '娜塔莉·波特曼', '大卫·戈登·格林', 5.9, 8592, 'tt1240982', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p767450006.jpg', 6, 21.5, 48.6, 18.5, 5.4, '-0.191831,0.260283,-0.404711,0.475298,0.104097,-0.078590,0.318963,0.048548,-0.142747,-0.336517,0.263269,0.619140,-0.031130,-0.331768,0.504535,-0.005337,-0.319236,-0.338127,0.151007,-0.057963,-0.220938,-0.374216,-0.194856,-0.244584,-0.130321,-1.003744,0.556070,0.039269,-0.010983,0.342902,0.184721,0.495638,-0.063952,0.045165,0.014967,0.019060,0.132767,-0.240508,-0.313684,0.393025,-0.186911,0.292015,-0.266690,0.218539,0.012721,0.220663,0.538424,-0.737295,0.307091,-0.379245,0.169389,-0.265873,0.011324,-0.013023,0.233903,-0.197168,-0.017329,0.427440,0.072133,-0.296820,0.196353,-0.134133,-0.664480,0.060140,-0.075915,0.185073,-0.492256,0.681566,-0.218945,0.104879,0.184372,-0.263732,-0.062676,0.256120,0.250629,0.032924,0.074772,-0.034331,-0.606349,-0.069574,0.369050,-0.021969,-0.265112,0.009779,-0.083194,-0.712997,-0.108890,-0.253865,-0.262764,0.000666,0.629750,0.209222,-0.167110,0.625579,-0.469422,-0.267258,-0.602478,0.102416,0.162516,-0.313371,-0.201550,-0.522765,0.213239,-0.180337,-0.282951,-0.289877,0.316097,-0.172035,0.467813,-0.938297,0.437591,0.259541,0.203062,-0.066031,0.520072,0.042271,0.245813,-0.267628,-0.413980,0.247580,0.152121,0.134625,0.298408,0.327746,0.010145,0.101497,-0.227915,0.500000', '24750460', '1401524', '19951149', '10440076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3285622', '非法入境', '剧情', '在法国加莱，有一批来自伊拉克库尔德地区的难民，他们遭受着绝大多数法国人的提防和排挤，热衷于足球的17岁比拉尔（菲拉·阿伊维尔迪 Firat Ayverdi 饰）就是这些难民中的一个。比拉尔梦想着去英国，在通过卡车偷渡失败之后他开始学习游泳，并结识了法国人西蒙（文森特·林顿 Vincent Lindon 饰）。西蒙是游泳馆里的游泳教练，他被比拉尔的认真劲儿吸引，并逐渐对这个年青人产生好感。当西蒙得知比拉尔学习游泳是为了穿越拉芒什海峡时他曾试图劝阻，可是当他得知比拉尔去英国是为了见到女友米娜时，正在办理离婚手续的西蒙竟然决定帮助他……本片在2009年的柏林电影节获得欧洲电影标志大奖和天主教人道精神奖两项大奖。©豆瓣', '文森特·林顿', '菲利普·里奥雷', 8.2, 8786, 'tt1314280', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1620240883.jpg', 0.2, 0.8, 15.2, 54.4, 29.4, '0.272652,-0.053172,-0.776936,0.573789,-0.137930,-0.315597,0.357203,-0.158584,-0.473583,-0.231995,-0.053657,1.057723,-0.170188,0.193517,0.338683,0.147278,-0.599418,-0.689375,0.132491,-0.121639,-0.155080,-0.577536,-0.245851,-0.125323,-0.191225,-0.454188,0.398837,0.003367,-0.210833,0.608486,0.397746,0.280686,0.091241,0.546143,-0.006965,-0.064055,0.305231,-0.091732,-0.317825,0.255327,0.014640,-0.189265,-0.289909,0.078951,0.257048,0.324830,0.515544,-0.044912,0.248787,-0.104239,0.357276,-0.389218,0.063770,0.170519,0.319234,0.094996,-0.067276,0.135372,-0.116304,0.056238,0.037618,-0.216418,-0.459912,-0.036455,-0.046494,0.115794,-0.520055,0.272114,-0.128591,0.023479,0.122146,-0.326928,0.071796,0.505613,-0.082866,0.263535,-0.113394,0.033675,-0.555157,0.279343,0.712719,-0.142483,-0.132241,-0.044639,-0.278056,-0.485150,0.324040,-0.160914,-0.297179,0.073229,0.345008,-0.192292,-0.188443,0.199950,-0.618025,0.092586,-0.209253,-0.566704,0.109189,-0.070928,-0.025257,-0.921826,-0.005490,-0.359706,-0.237284,-0.066559,-0.075561,-0.137897,0.669806,-0.787005,0.300575,0.901572,0.517341,-0.461663,0.710386,0.046504,-0.021196,-0.198024,-0.261526,0.422319,-0.011880,0.124025,-0.156695,0.266437,0.261417,-0.354192,-0.079388,0.469373', '3178770', '1829654', '11541282', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3285632', '都灵之马', '剧情', '“1889年1月3日，都灵。弗里德里克·尼采在维亚·卡罗·艾尔波特酒店的六号门前驻足。他的目光被酒店外的一个马车吸引。不远的地方，停着一辆小马车。马车的车夫遭遇到了一匹倔强的马。不管车夫怎么喊叫，马匹根本没有要移动的意思。最终，车夫失去了耐心，拿起了鞭子，朝马匹打去。尼采见到此番情景，挤进人群，冲到马匹跟前，阻止住马夫，抱住马的脖子，痛哭起来。酒店的主人赶来，拉走了尼采。回到酒店的尼采在沙发上安安静静地、一动不动地躺了两天。随后，他小声地说了几句话。接下来，就是尼采精神错乱、神经颠颠的十年，由他的妹妹和母亲照顾的日子。谁也不知道，在都灵，在那匹马的身上，在尼采的心理，发生了什么。”', '亚诺什·德尔日', '贝拉·塔尔', 8.5, 19939, 'tt1316540', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2248876398.jpg', 1.3, 2.3, 13, 39.1, 44.3, '0.567762,0.171894,-0.808011,0.439205,-0.140750,-0.381160,0.928769,0.280727,-0.405147,0.005515,0.541438,0.553134,-0.303137,0.158408,0.498437,0.228881,-0.235753,-0.610943,-0.224436,0.023054,-0.641382,-0.364658,0.335931,-0.248645,0.031629,-0.280758,0.095455,-0.109586,0.081380,0.651234,0.292600,-0.031910,0.090167,0.251529,-0.412605,0.295555,-0.021863,-0.176680,0.182483,0.281845,0.192379,-0.582863,-0.408957,-0.210671,0.161648,-0.144678,0.638980,-0.079794,0.084227,0.455416,0.008953,-0.153158,0.349321,-0.038984,0.456698,-0.232032,-0.211452,-0.059323,-0.143003,0.102967,0.245485,0.306924,-0.059868,0.166852,-0.598878,0.296939,-1.059429,0.656043,-0.286448,0.042109,0.047434,-0.681479,0.279635,0.221069,-0.312614,0.483175,-0.109633,0.091582,-0.887629,-0.356082,0.522114,0.019916,0.239332,0.328677,-0.050755,-0.371677,-0.402534,0.125967,-0.422205,-0.501540,0.714365,-0.001803,-0.504373,-0.153921,-0.211099,0.036540,-0.049628,-0.585686,-0.033158,-0.279873,-0.299928,-0.368563,0.251352,-0.440284,0.250909,0.201139,-0.105651,0.188431,0.322899,-0.414409,0.257077,0.399501,0.375870,-0.092530,0.646746,-0.379392,0.267328,0.211637,0.309121,0.114993,0.219536,0.733113,0.527181,0.517026,-0.272937,0.256040,-0.620879,0.549981', '1303462', '1297347', '1306670', '25837175');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3285642', '音乐会', '剧情', '安德烈（阿列克塞·古斯科夫 Aleksei Guskov 饰）被盛赞为音乐天才，曾经当过俄国最伟大的交响乐团“波修瓦”的著名的乐队指挥。但因拒绝驱逐乐团里的犹太乐手，包括他最好的朋友——沙查（迪米特里·纳扎罗夫 Dmitri Nazarov 饰）而被解雇，染上了酗酒的毛病。“波修瓦”现在的经理为了愚弄和羞辱安德烈，让他留在乐团当清洁工。安德烈在无意之中发现了一份传真，法国巴黎最大的普莱耶音乐厅邀请“波修瓦”去演出，要求在两周之内给予回复。安德烈突然想到了一个疯狂的计划，他要把以前的那些音乐伙伴重新聚拢起来。被乐团流放之后，他们现在已经变成了一群混杂在莫斯科街头的最普通的人，从出租车司机、搬运工、跳蚤市场的地摊摊主到色情电影的配音演员，做的都是勉强维持生活的底层工作。他们决定顶替真正的“波修瓦”去巴黎，要向一切不公正的待遇展开复仇……©豆瓣', '梅拉尼·罗兰', '拉杜·米哈伊列亚努', 8.5, 17256, 'tt1320082', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p767824526.jpg', 0.3, 1.4, 13.5, 42.2, 42.6, '0.225734,-0.025246,-0.603224,0.693255,-0.422430,-0.289164,0.852018,0.229551,-0.441822,-0.198912,0.125511,0.956540,-0.131480,0.190142,0.586789,0.047042,-0.321052,-0.711249,-0.098420,-0.195154,-0.288310,-0.408166,0.023719,-0.318059,-0.161075,-0.258868,0.470888,-0.028459,-0.274057,0.220832,0.517012,0.132939,0.218969,0.307647,-0.226816,-0.045732,0.237206,-0.191906,-0.120972,0.288735,-0.036517,-0.273475,-0.115276,0.182945,0.133804,0.239864,0.721679,-0.134808,0.109879,-0.055844,0.272177,-0.352040,0.109577,0.118849,0.135667,0.112675,0.113455,0.205668,-0.367562,0.114244,0.006620,-0.046829,-0.905563,0.004075,-0.090709,0.024153,-0.741094,0.610798,-0.005862,-0.013976,0.045725,-0.287103,0.383653,0.290575,-0.050314,0.530320,0.028533,0.000285,-0.532846,0.360739,0.792080,0.005372,-0.174060,0.305629,-0.224820,-0.329654,0.065857,-0.203805,-0.395600,-0.207695,0.171370,-0.091351,-0.108438,0.055237,-0.701445,-0.276913,-0.114979,-0.499483,0.115391,-0.526618,-0.122905,-0.736517,-0.043246,-0.065005,-0.050134,0.062586,0.062796,-0.103335,0.789126,-0.911603,0.214925,0.651670,0.169048,-0.475958,0.627081,0.174303,0.121792,-0.056456,-0.090393,0.128906,0.373035,0.622077,0.200206,0.311453,0.056263,-0.460923,-0.376278,0.550758', '30162520', '1793491', 