INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3287562', '神偷奶爸', '喜剧', '超级坏蛋格鲁（史蒂夫·卡瑞尔 Steve Carell 配音）在听说埃及金字塔被盗的新闻后不满市面上新贼辈出，决定在纳法利欧博士（拉塞尔·布兰德 Russell Brand 配音）的帮助下建造火箭升空盗取月亮。在向坏蛋银行贷款的过程中，格鲁盗取的收缩射线枪被新贼维克托（杰森·席格尔 Jason Segel 配音）抢走。为了夺回收缩射线枪，格鲁决定领养三位孤儿——玛戈（米兰达·卡斯格拉夫 Miranda Cosgrove 配音）、伊迪丝（达娜·盖伊 Dana Gaier 配音）和阿格蕾丝（埃尔希·费舍 Elsie Fisher 配音），利用她们进入维克托的城堡兜售饼干的机会实施偷盗，计划成功后再偷偷处理掉三个小孩。然而在平凡的日常相处中，格鲁却发现自己越来越离不开这三个小鬼，但这样的感情用事却将严重影响周密的盗月计划……©豆瓣', '史蒂夫·卡瑞尔', '皮埃尔·柯芬', 8.6, 891992, 'tt1323594', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p792776858.jpg', 0.1, 0.5, 10.8, 44.2, 44.4, '0.166831,-0.069932,-0.395203,0.285317,-0.066503,-0.335315,0.528216,0.014257,-0.145825,-0.121762,0.153528,0.302877,-0.179308,-0.165352,0.177702,0.126235,-0.611495,-0.410978,0.094510,-0.184109,-0.124071,-0.626209,-0.376175,-0.176606,-0.099015,-0.402074,0.503898,-0.177481,-0.125709,-0.002011,0.064331,0.153392,-0.119066,-0.015098,0.150296,0.017672,0.238838,-0.397724,-0.120314,0.579283,-0.123628,0.150794,-0.033175,0.146135,0.208511,0.316489,0.473377,-0.263362,0.235180,-0.243993,0.344253,-0.128658,-0.050765,0.025363,0.165549,0.217582,-0.074229,-0.045874,-0.250628,-0.101122,0.109722,-0.226453,-0.508497,0.182470,-0.005161,0.173667,-0.498151,0.013875,-0.226994,0.248140,0.141638,-0.465176,-0.136876,0.351854,0.320574,0.274391,-0.327027,0.339714,-0.372503,-0.042074,0.096950,-0.272124,-0.255307,0.024121,0.245156,-0.358908,0.169385,-0.001495,-0.296080,-0.162523,0.644170,0.010518,-0.218127,0.466290,-0.533868,-0.067763,-0.326177,-0.236263,-0.095941,-0.196504,-0.166673,-0.842877,0.050654,0.112306,-0.135219,-0.089858,-0.071374,-0.359876,0.385714,-0.555947,0.392310,0.607071,0.116476,-0.136135,0.167324,-0.117243,0.164916,-0.178538,-0.201754,0.235583,0.367773,0.215532,0.094080,0.210518,0.265406,-0.341995,-0.324636,0.407821', '6517421', '2075345', '2369613', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3287578', '五路追杀令2：刺客舞会', '喜剧', '为FBI工作了一辈子的沃特·韦德（汤姆·贝伦杰 Tom Berenger 饰）眼下突然面对死亡威胁，暗杀组织在网络中放出消息，用300万美元在今夜索他的性命。一生只是一个中层情报分析员的沃特如何会得到这种“关注”，令前来保护他的众多探员百思不得其解，但眼下的首要任务是保证沃特在今夜不出意外。沃特被安置在芝加哥的地下避难所，众多探员围绕保全。另一方面，高额悬赏也吸引了众多职业杀手的注意，从冷血的蛇蝎拉丁美女、易容杀手，到父子齐上阵的纳粹狂人一家、AK47女郎一起将目标锁定之。FBI发现暗杀任务的幕后操控者是一个名为“真爱国者”的反美组织，而这个组织的真相，包括他们暗杀沃特的真实目的，将在今夜血肉横飞的战斗后揭晓……©豆瓣', '汤姆·贝伦杰', 'P.J. Pesce', 6.1, 5076, 'tt1319743', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2242256765.jpg', 4.1, 19.3, 51.9, 19.2, 5.6, '0.241154,0.044527,-0.637577,0.517181,-0.407516,0.123297,0.468424,-0.087607,-0.568843,-0.228490,0.610192,0.747796,-0.125188,-0.144152,0.357208,-0.132462,-0.014619,-0.542906,-0.343635,-0.256369,-0.409081,-0.554847,-0.364081,-0.388470,-0.039866,-0.323195,0.603264,0.262122,-0.232903,0.292732,0.455684,0.584869,-0.187953,0.441728,-0.032470,-0.384147,0.250273,-0.376250,-0.263364,0.557913,-0.196191,-0.307010,-0.132840,0.393589,-0.119257,0.479030,0.646487,-0.329756,-0.065331,-0.058499,0.288311,-0.601932,0.058226,-0.062890,0.520933,-0.206797,-0.058903,0.287027,-0.282453,-0.013519,-0.160299,0.121577,-1.216893,-0.225460,0.325065,0.180346,-0.501136,-0.006885,-0.276342,0.032054,-0.066845,-0.020475,0.391844,0.523778,0.058320,0.206233,0.046651,0.132321,-0.501224,0.138768,0.682485,-0.158582,-0.083467,0.042382,0.048043,-0.379391,-0.110923,-0.273625,-0.186355,-0.163456,0.356816,-0.042857,-0.116944,0.221308,-0.556247,-0.111682,-0.346999,-0.232039,0.018644,-0.577624,-0.137758,-0.825295,0.010484,-0.009885,-0.154384,0.248653,0.205417,-0.280369,0.788771,-0.831177,0.106070,0.830036,0.125963,-0.537988,0.534769,0.053915,0.305498,-0.123553,-0.211735,0.130848,0.811181,0.352729,-0.123283,0.275044,0.021828,-0.383214,-0.416109,0.249111', '1793491', '30163500', '27009869', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3288397', '初恋从打嗝开始', '喜剧', '影片翻拍自1999年的丹麦同名电影《初恋从打嗝开始》。高一新生维多（戴文·沃克海瑟 Devon Werkheiser 饰）喜欢上了高二女生安雅（丝柯·泰勒-考普顿 Scout Taylor-Compton 饰）。可安雅已和开着保时捷名车的彼得在交往。而维多的好友托奇与尼可莱都不支持他追安雅。某日,维多鼓起勇气邀请安雅参加班级舞会,安雅的死党吉蒂也鼓噪大伙同去。舞会上维多拼命打嗝，安雅开玩笑说如果维多再打嗝，她会强行献吻，结果维多真的停止了。维多无意间听到彼得买通吉蒂设计让安雅失身的消息,遂决心制止。但谁知导致全面失控,彼得自尊受到打击，也使得安雅大吃一惊。原来，安雅的弟弟布莱恩是维多弟弟艾斯本的同学，两人暗地里编导着一部“爱情灾难片”的拍摄作品。内容是关于维多不幸的爱情遭遇，以及如何浩劫重生。而最终维多是否真的可以赢得安雅的芳心？©豆瓣', '戴文·沃克海瑟', '芭芭拉·罗森博格', 6.2, 15995, 'tt1307065', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p792646577.jpg', 2.3, 14.9, 58.3, 19.9, 4.6, '0.230756,-0.182994,-0.414701,0.477338,0.206943,-0.632850,0.487253,0.215296,-0.454887,-0.029229,0.222934,0.486329,-0.557252,0.022471,0.448684,0.157823,-0.518591,-0.639028,0.261648,0.071579,0.085875,-0.571211,0.001798,-0.110973,0.251594,-0.489707,0.491912,-0.354345,-0.057593,0.619228,0.481979,0.137387,0.037643,0.263057,0.429109,0.105647,0.262417,-0.062289,-0.253225,0.222428,0.018714,-0.125981,-0.297338,0.069822,0.194927,0.184255,0.173706,-0.138955,0.204092,0.047359,0.409865,-0.229929,0.200403,0.287594,0.035610,-0.038715,0.607138,0.136481,-0.134059,-0.059868,0.098083,0.076356,-0.249509,0.093218,0.125580,0.136521,-0.330928,0.361386,-0.370764,0.026631,0.309782,-0.270066,-0.007139,0.356501,0.320529,0.342458,-0.260412,-0.152268,-0.411298,0.017272,0.553267,-0.080887,-0.113645,0.270584,-0.009740,-0.189196,0.048706,0.024389,-0.749454,0.426025,0.231627,0.107766,-0.212209,0.419194,-0.341819,-0.231869,-0.338151,-0.276262,0.172936,-0.204310,0.068691,-0.775573,-0.323918,-0.063772,-0.044615,-0.499397,0.045492,-0.431664,0.819552,-0.854246,0.154976,0.607703,0.303645,-0.194452,0.466867,0.226756,0.087694,-0.021718,-0.039518,0.384604,-0.125577,0.030409,0.010284,0.187426,0.217980,-0.379669,-0.146571,0.413628', '1316589', '25922902', '1292720', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3289081', '暮光之城4：破晓(上)', '剧情', '本片根据美国女作家斯蒂芬妮·梅尔的畅销小说《暮光之城：破晓》改编，是该作的终结篇,由于篇幅过长被分为了上下两部。贝拉（克里斯汀·斯图尔特 Kristen Stewart 饰）与爱德华（罗伯特·帕丁森 Robert Pattinson 饰）历经磨难终于踏进了婚姻殿堂。婚 后爱德华和贝拉去艾思蜜岛上渡蜜月，度过了一段快乐的时光。不久贝拉发现怀孕，蜜月提前结束。狼族担心胎儿会对族人构成威胁决定除掉它。雅各布（泰勒·洛特纳 Taylor Lautner 饰）为保护贝拉离开狼族，连夜警告库伦家。胎儿生长迅速令贝拉吃尽苦头。爱德华不忍看她受苦希望她放弃孩子，但贝拉却坚持要生下。分娩当晚，贝拉大量失血，在她命悬一线之际，爱德华将装有自己吸血毒液的针管插进贝拉心脏。另一边王族也注意到了这个新生儿，一场撼动吸血鬼、狼人和人类世界的对决正悄悄来袭......©豆瓣', '罗伯特·帕丁森', '比尔·康顿', 6.9, 179281, 'tt1324999', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1296034341.jpg', 2.9, 11, 42.5, 27.7, 15.9, '-0.040754,0.259369,-0.484023,0.113403,0.241540,-0.364479,0.758626,-0.032164,-0.147117,-0.122495,0.089292,0.569423,-0.287586,0.171462,0.257190,0.158639,-0.430589,-0.448595,0.178777,-0.081444,-0.358335,-0.288873,-0.085801,-0.166414,0.036338,-0.635284,0.695101,0.158185,-0.008704,0.352742,0.020532,0.270662,-0.114062,0.260721,0.093595,0.108181,0.093468,-0.395003,-0.296157,0.265847,0.160836,-0.058448,-0.087401,0.219711,0.160455,0.301213,0.735978,-0.356593,0.178152,-0.477886,0.304973,-0.374729,-0.058916,0.062879,0.327925,-0.137506,0.013688,0.215123,-0.204137,0.062241,0.004656,-0.232731,-0.279718,0.036027,-0.013955,0.207012,-0.694598,0.315863,-0.204346,0.124143,0.174871,-0.241626,0.126894,0.459332,0.257342,0.157101,-0.152149,0.005664,-0.259505,-0.147646,0.533615,-0.344378,-0.215825,0.157699,-0.058034,-0.461451,0.024504,-0.024878,-0.463640,-0.132642,0.544101,0.137584,-0.127768,0.385286,-0.303981,-0.268270,-0.675521,-0.393027,0.147257,-0.387977,0.100663,-0.590343,-0.063486,-0.161523,-0.241863,-0.062857,0.096766,-0.357385,0.367045,-0.327322,0.373086,0.470739,0.444898,-0.207507,0.407075,-0.062279,0.363659,-0.220219,0.189465,0.863603,0.051624,0.011656,0.196647,0.056095,0.170658,0.229544,-0.385016,0.482508', '1844413', '22637441', '1297735', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3289086', '暮光之城3：月食', '剧情', '贝拉（克里斯汀•斯图尔特 Kristen Stewart 饰）即将毕业，她与爱德华（罗伯特•帕丁森 Robert Pattinson 饰）在婚姻问题尚有分歧。父亲总担心女儿跟爱德华交往会吃亏，但是爱德华保守派风格令他安心。雅各布（泰勒•洛特纳 Taylor Lautner 饰）看到爱德华与贝拉依旧如胶似漆，内心十分挣扎。他感应到贝拉对自己的感觉，并私下对她示爱。在强吻遭拒后，两人不欢而散。贝拉的衣物神秘被盗，同时爱丽丝感到昔日库伦家族的维多利亚正在准备为死去的詹姆斯复仇。后者组建了一支吸血鬼新生儿军团，正在赶往此地，来势汹汹，不可不防。于是，库伦家族决定积极备战。考虑到贝拉的安全，雅各布也决定加入，昔日宿敌结盟，联手对抗外来的恶势力。然而大战在即，贝拉却还纠缠在同爱德华和雅各布的感情之间，难以抉择……©豆瓣', '克里斯汀·斯图尔特', '大卫·斯雷德', 6.8, 209672, 'tt1325004', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p533676600.jpg', 2.3, 10.4, 45.4, 27.4, 14.5, '0.230870,0.039965,-0.816241,0.372316,0.205104,-0.234661,0.535369,0.326600,-0.492629,-0.377741,0.190391,0.734839,-0.192391,0.077472,0.358643,-0.073715,-0.393339,-0.687951,0.251709,-0.010615,-0.128316,-0.646279,-0.029951,-0.543012,-0.059075,-0.250648,0.661717,0.081287,-0.254776,0.481751,0.291810,0.404830,-0.195126,0.625670,0.156488,-0.206257,0.108769,-0.110380,-0.570778,-0.043873,0.232420,0.227975,-0.227567,0.348217,0.252050,0.468716,0.420937,-0.364203,0.055263,0.005499,-0.058889,-0.188599,0.195279,0.279553,0.312561,-0.077602,-0.033002,0.356921,-0.008448,0.084141,0.002101,0.020335,-0.460102,0.389265,0.017183,0.239528,-0.470165,0.417978,-0.198013,0.148827,0.314924,-0.208988,-0.193163,0.723643,0.286691,0.127680,-0.123584,0.086066,-0.333995,-0.309592,0.657612,0.098031,-0.044263,0.125889,-0.233850,-0.337554,-0.235678,-0.087686,-0.410704,-0.331458,0.267199,0.141968,0.070135,0.535275,-0.531684,-0.423010,-0.428033,0.069963,0.221112,-0.454378,0.303080,-0.696559,-0.307030,-0.305396,-0.409846,0.058446,0.048868,-0.213873,0.410350,-0.834249,0.043466,0.571215,0.492216,-0.517522,0.292773,0.365814,0.114139,-0.327279,-0.261194,0.821683,-0.034335,-0.148608,0.167213,-0.003818,0.193841,0.171160,-0.182979,0.324576', '1302987', '1301022', '25978126', '26316956');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3291376', '幸运符', '剧情', '罗根（扎克•埃夫隆 Zac Efron 饰）是一名美国海军陆战队的中士，在战场上意外获得的一张女孩的照片。罗根三番两次的从伊拉克的战斗任务中死里逃生，战友们都称她是他的幸运女神。身边的战友都在意外的战斗破坏中阵亡，只有罗根幸存下来，因此罗根也把这张照片看成了他的幸运符，并对照片中的女孩心存感激之情。服役结束后，他回到了美国本土，决心找到这名照片上的陌生女孩。于是罗根带着猎狗步行横穿了多个美国的城市，四处询问后，终于找到了照片上这名叫做贝丝（泰勒•席林 Taylor Schilling 饰）的女孩的住处。在机缘巧合下罗根应聘成了贝丝所经营的动物会所的员工。两人在朝夕相处中渐渐相熟相知，罗根也在渐渐熟悉了贝丝复杂的生活后，对她产生了除去感谢之外的爱恋之情…改编自“美国男琼瑶”尼古拉斯•斯帕克斯的小说《幸运符》，又名《分手信》。该片是其被搬上银幕的第七本小说。', '扎克·埃夫隆', '斯科特·希克斯', 6.6, 12497, 'tt1327194', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1474320542.jpg', 1.3, 10.4, 53.6, 25.8, 8.9, '0.401454,0.053836,-0.737220,0.653998,-0.042782,-0.284799,0.753915,-0.160605,-0.422315,0.108707,0.279396,0.851664,0.016711,0.480599,0.242817,0.086290,-0.508737,-0.671871,-0.357736,-0.466775,-0.509537,-0.429557,-0.460622,-0.113274,-0.077403,-0.496829,0.478118,0.077117,-0.230241,0.525206,0.352896,0.191933,-0.095990,0.434810,-0.197812,0.246367,0.112233,0.016002,-0.132529,0.216075,-0.192234,-0.244827,0.036797,0.140647,0.063227,0.470686,0.969836,-0.192150,-0.156741,0.043218,0.315464,-0.049087,-0.031921,0.110614,0.287557,0.142766,0.213253,0.007145,-0.176524,0.109968,0.013897,0.157042,-0.636594,-0.040405,-0.087596,0.136511,-0.620565,0.654966,-0.031976,0.060134,0.088325,-0.363019,0.406666,0.120884,0.016710,0.220231,-0.094218,0.082828,-0.301752,0.446602,0.508018,0.053802,-0.256972,0.360849,-0.387466,-0.514284,-0.026096,-0.110329,-0.455040,-0.083096,0.624705,0.000366,-0.142956,0.067360,-0.660964,-0.040477,-0.160762,-0.110431,-0.104618,-0.273075,-0.057560,-0.680128,-0.295097,-0.518400,-0.369782,-0.093005,0.005619,-0.340740,1.041296,-0.606752,0.226305,0.532569,0.180041,-0.271710,0.750663,0.208510,0.052851,0.013154,-0.089882,0.418155,0.164743,0.454411,0.136552,0.320414,-0.189773,-0.116744,-0.382791,0.527075', '3811356', '130714