INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3291930', '赤壁(下)', '动作', '八卦阵一战，孙刘联军力挫曹兵之锐气。曹操（张丰毅 饰）为此忧心忡忡，加之北方将士因水土不服，死伤过重，更令其头风病发作，幸得侍女骊姬（小宋佳 饰）陪伴照顾。孙尚香（赵薇 饰）易容潜入曹营，借士官长（佟大为 饰）垂青，窃取军情。为了适应水战，曹操采纳荆州降将蔡瑁、张允的意见，将战船用铁锁相连。此后，曹操帐下谋士蒋干（师小红 饰）主动请缨前去拜访故友周瑜（梁朝伟 饰）刺探虚实。周瑜将计就计，假借酒醉泄露军机，让蒋干带回假情报，曹操一怒之下误杀了蔡瑁张允。曹操将因瘟疫致死的将士尸体投入江水，名曰“鬼兵”，意欲扰乱孙刘联盟之军心，小乔（林志玲 饰）见此情景，遂决定夜探曹营，劝其退兵。眼看万事具备，但是风向不对，周瑜遂派鲁肃（侯勇 饰）找诸葛亮（金城武 饰）寻助……©豆瓣', '梁朝伟', '吴宇森', 6.4, 145832, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2161629765.jpg', 2.7, 11.4, 53.5, 25.9, 6.5, '-0.144822,0.040340,-0.447603,0.283224,0.211940,0.362236,0.089378,0.539020,-0.674343,-0.288161,0.292984,0.081257,-0.063433,-0.262933,-0.087760,-0.321910,-0.157934,-0.538950,0.006423,0.148121,0.317107,-0.131457,-0.113363,-0.093473,-0.285686,-0.141656,0.506090,0.034510,-0.079347,0.567795,-0.030456,0.139825,-0.091501,0.741440,0.526579,0.166111,-0.499976,-0.308815,-0.276551,0.161321,-0.085968,-0.476777,-0.296997,-0.130806,-0.292515,0.349910,0.627021,-0.319215,0.064477,-0.079940,0.139561,-0.133910,0.410329,-0.113929,0.178686,0.299971,-0.174006,-0.024225,-0.181716,0.229818,0.161883,0.280925,-0.064673,0.069753,0.312324,-0.205819,-0.347819,-0.071299,-0.456767,0.091872,-0.192797,-0.316947,-0.003136,0.616966,0.320978,-0.305850,0.226756,-0.259532,-0.109038,0.303703,0.105278,-0.309837,0.434034,-0.542149,0.098007,-0.211418,0.657141,-0.061728,-0.218934,0.241866,0.599870,-0.195898,0.345330,0.054424,-0.091696,-0.388817,-0.399919,0.499545,-0.035877,0.302284,0.329721,-0.495009,-0.023847,0.083761,-0.165931,-0.102799,0.625518,0.353662,0.202302,-0.224164,-0.633356,0.153161,0.112279,-1.021172,0.034644,0.092103,0.168168,0.002075,0.260429,0.228581,0.339093,0.101968,0.336370,-0.157564,-0.272823,-0.346338,-0.409034,-0.347083', '1461031', '1465829', '1947091', '1297497');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3292949', '白宫管家', '剧情', '1926年，佐治亚州的棉花田内，少年塞西尔目睹了父亲被农场主射杀的一幕，从此种族歧视在他心底投下了毕生挥之不去的阴影。20世纪50年代末，盘桓华盛顿的塞西尔·盖恩斯（福里斯特·惠特克 Forest Whitaker 饰）意外获得白宫内务负责人的赏识，被推举进入这座国家政治的中心担任餐饮服务工作。他谨记上司的教诲，察言观色，将自己溶于空气中。此后的岁月，塞西尔服侍了艾森豪威尔（罗宾·威廉斯 Robin Williams 饰）、肯尼迪（詹姆斯·麦斯登 James Marsden 饰）、约翰逊（列维·施瑞博尔 Liev Schreiber 饰）、尼克松（约翰·库萨克 John Cusack 饰）、里根（阿伦·瑞克曼 Alan Rickman 饰）等在美国历史上各自书写了重要一笔的总统。围绕黑人的民权斗争，他和总统、家人以及手足同胞也经历着一个个刻骨铭心的时刻……本片根据白宫首席管家尤金·艾伦的真人事迹改编。', '福里斯特·惠特克', '李·丹尼尔斯', 7.4, 28195, 'tt1327773', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1993372611.jpg', 0.4, 3.3, 35.5, 45.5, 15.3, '0.007767,-0.050874,-0.604253,0.679964,-0.027471,-0.341083,0.447655,0.350530,-0.527258,-0.308924,0.371085,0.920840,-0.228380,0.033559,0.485003,0.185148,-0.429455,-0.771894,-0.213834,-0.156605,0.031269,-0.525958,-0.374453,-0.379889,-0.293151,-0.313170,0.400077,-0.027576,0.118160,0.278169,0.188644,0.339650,0.164481,0.133145,0.048423,0.121305,0.555405,-0.253428,-0.390855,-0.149659,0.050878,-0.298073,-0.029510,0.059495,0.098244,0.255705,0.399263,-0.336222,0.264879,-0.086329,0.240830,-0.208393,0.184763,0.176117,0.224737,0.132223,-0.068434,0.568034,-0.262489,-0.065893,0.062874,-0.121571,-0.305894,-0.242552,-0.057123,0.227173,-0.584986,0.605602,-0.367857,0.230360,-0.154705,-0.107597,0.100239,-0.034849,-0.002839,0.193430,0.193095,0.110465,-0.102520,0.434566,0.296327,-0.157450,-0.358346,-0.085597,-0.473777,-0.285151,-0.035151,-0.080429,-0.552285,-0.244460,0.332397,-0.231041,0.153193,0.459335,-0.383899,-0.138449,-0.509735,-0.334530,-0.071253,-0.149939,-0.055820,-0.776716,-0.320233,-0.373007,-0.189584,-0.200403,-0.024102,-0.045612,0.586900,-0.363899,0.249622,0.329766,-0.068273,-0.061363,0.653863,-0.040796,0.431518,-0.277071,-0.138050,0.487649,0.182737,0.218693,0.017542,0.385673,0.028047,-0.059348,-0.070086,0.374652', '4319218', '30162520', '35161768', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3299241', '在世界转角遇见爱', '剧情', '一个年过半百却精神矍烁的老人（米基马诺洛维克 Miki Manojlovic 饰）出现在躺在医院因车祸而失去记忆的青年亚历山（卡罗柳别克 Carlo Ljubek 饰）在的身边，他自称是亚历山大的外公，来自保加利亚。他还带来了一张旧照片和一盒双陆棋，并且如数家珍的向亚历山大讲起他小时候的事情。一系列的亲昵行为并不能唤起亚历山大的记忆，反正让亚历山大极不自在。于是，老人能做的只是每天来医院陪亚历山大下棋，跳动的棋子似乎扣动了亚历山大心灵深处的某种东西，他对这个老人之间建立起初级的信任。为了唤起亚历山大的记忆，并且重新鼓起他积极生活的勇气，老人决定带亚历山大开始一段“回家”之旅。一辆协力车，一路的美景，亚历山大在老人的鼓励下在途中邂逅美丽的爱情、重新找回积极生活的信心和勇气、并最近在意大利的收容所里找回往昔的记忆……这部德国莱比锡文学首奖作家伊利亚托亚诺（Ilija Trojanow）半自传式获奖小说，改编成电影后，横扫国际各大电影节，为导演史帝芬柯曼边瑞夫（Stephan Komandarev）拿下十多项国际大奖。', '米基·马诺伊洛维奇', '斯特凡·科曼达雷夫', 8.2, 14210, 'tt1178197', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1558551493.jpg', 0.2, 1.2, 17.4, 48.6, 32.5, '0.029987,0.195829,-0.614544,0.824382,-0.080523,-0.418664,0.743228,0.092813,-0.570472,-0.213353,0.145509,0.739631,0.026025,0.439493,0.394594,0.040140,-0.486891,-0.718186,0.018664,0.174684,-0.243200,-0.513584,-0.263679,-0.200978,-0.219107,-0.343687,0.464134,-0.043007,-0.215232,0.568824,0.171303,0.137648,0.077279,0.299992,-0.215306,0.072035,-0.004564,0.041295,-0.351036,0.151891,0.313973,-0.196992,-0.199681,0.267096,0.039230,0.134307,0.619793,-0.024845,-0.105695,0.067107,0.350234,-0.083346,-0.012250,-0.001033,0.067074,0.392275,0.098024,-0.051968,-0.154623,0.224027,-0.024893,-0.188365,-0.673519,-0.083736,-0.013953,0.224728,-0.439000,0.575424,-0.163490,0.202045,0.061122,-0.332070,0.002524,0.294447,0.132177,0.341730,-0.137251,0.240667,-0.380037,0.308955,0.394657,-0.025057,-0.164053,0.481310,-0.308759,-0.216840,-0.244563,-0.011042,-0.428710,-0.031575,0.203035,-0.123905,0.001905,0.260874,-0.525581,-0.025546,-0.127560,-0.303975,0.104404,-0.311874,-0.025054,-0.654535,-0.122366,-0.219298,-0.044425,0.008254,0.200696,-0.281715,0.770566,-0.490664,0.290141,0.448971,0.014338,-0.156107,0.485634,-0.003376,-0.053308,-0.224937,-0.112801,0.540558,-0.057397,0.223458,0.023740,0.156549,-0.064672,-0.008229,-0.595418,0.619068', '1299663', '25837262', '1870681', '10754780');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3302627', '复仇', '剧情', '费兰斯•高德勒（约翰尼•哈里戴 Johnny Hallyday 饰）20年前曾是叱咤风云的杀手，收山后他在巴黎开了一家餐馆，过着平静安宁的日子。某天，他定居在澳门的女儿爱莲（Sylvie Testud 饰）一家遭到不明身份的杀手的袭击。女婿和两个外孙全部遇难，只有爱莲侥幸逃生。费兰斯得知消息后连忙从法国赶往澳门，在见到现场的惨状后，他决心不惜一切代价为女儿一家复仇。由于人生地不熟，费兰斯的调查毫无进展。偶然间，他在酒店遭遇一起暗杀事件，三个杀手阿鬼（黄秋生 饰）、阿柱（林家栋 饰）和肥乐（林雪 饰）给他留下极深的印象。经过短暂的试探和接触，费兰斯决定雇佣阿鬼三人作为帮手。凭借爱莲留下的线索和在凶案现场的勘查，众人逐渐缩小包围圈，一场复仇战随即悄悄地展开，而幕后的阴谋也慢慢浮出水面……©豆瓣', '约翰尼·哈里戴', '杜琪峰', 6.9, 27652, 'tt1329454', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2217483708.jpg', 1.3, 7.6, 45.8, 35.5, 9.8, '-0.070338,0.000135,-0.715048,0.396019,0.118572,-0.442727,0.546222,0.119482,-0.482131,-0.345500,0.445506,0.632305,-0.050367,-0.097265,0.289700,-0.213301,-0.451461,-0.639709,0.050722,-0.312424,-0.109863,-0.507140,-0.257901,-0.204012,0.125211,-0.190367,0.184581,0.188401,-0.125459,0.624712,0.505215,0.239777,-0.383998,0.404720,-0.145008,0.015291,0.198099,-0.015427,-0.484649,0.253998,-0.106312,-0.317141,-0.221737,-0.055031,0.088681,0.501623,0.647863,-0.107966,-0.220725,0.029714,0.112007,-0.210959,-0.033658,-0.115774,0.470808,0.065087,0.159903,0.283212,-0.411138,-0.196883,0.013722,-0.084964,-0.574080,-0.006846,0.181143,0.046498,-0.693062,0.247323,-0.078058,0.091922,0.090641,-0.405634,0.189836,0.544213,0.173702,-0.003454,-0.066073,0.063869,-0.395400,0.125605,0.569649,-0.162521,0.226132,0.052755,0.046444,-0.436887,0.062819,-0.134752,-0.055697,0.075760,0.620420,-0.056388,-0.243096,0.104536,-0.453101,-0.311459,-0.502546,-0.322236,0.096874,-0.189601,-0.085508,-0.844301,-0.268322,-0.114248,-0.221621,0.089347,-0.253108,-0.171996,0.456551,-0.818397,0.376149,0.498721,0.259111,-0.469692,0.481308,-0.145330,0.183120,-0.120986,-0.075676,0.098411,-0.003521,0.350447,0.211937,0.109387,-0.200043,-0.167391,-0.225748,0.091258', '25833539', '3178770', '11541282', '25723905');
