INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3304014', '追影', '喜剧', '如果这个世界上真有宝藏的话，它在哪里，它又是什么？塞外高手叶赫长弓（吴镇宇 饰）隐匿中原，一日在街上看到琉球国忍者明月心（吴佩慈 饰），并被她的琴声所吸引，遂生爱慕之情。明月心为了得到“太祖开国密宝”，潜入皇宫偷取藏宝图，并和同样寻宝的三大高手展开激战，在打斗过程中，藏宝图神秘失踪。为了继续寻找宝藏下落，几人安家大明边陲小镇，每到月圆之夜，四人都会各显神通，继续追寻藏宝图下落。小镇首富许三官（房祖名 饰）富甲一方，三大高手为了房租的事情饱受许少责难。许少才高八斗，却苦恋长弓和明月心的养女唐薇（谢娜 饰）而不得芳心。明月心利用美色，企图从镇长古月金那里得到有关藏宝图的信息。藏宝图意外出现在小镇，引得天下众多英豪齐聚小镇，各路人马在小镇明争暗斗，企图占宝藏为已有。此时，明月心带领唐薇和许三官已经找到了藏宝的地点。然而，在经历种种之后，明月心终于发现了什么才是生命中真正的宝藏。', '吴镇宇', '吴镇宇', 4.4, 23591, 'tt1511528', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1229098496.jpg', 22.8, 40, 31.2, 4.8, 1.1, '-0.269513,0.194945,-0.820338,0.534897,0.320130,0.044598,0.416581,-0.031725,-0.820786,-0.261014,0.164874,0.404779,-0.119542,0.113079,0.182129,0.160319,-0.383534,-0.592337,0.137292,-0.486285,-0.276424,-0.258690,-0.250988,-0.083739,-0.198059,-0.111099,0.660468,0.533092,-0.151917,0.247021,0.233055,0.113682,-0.404372,0.254492,-0.455650,-0.159938,0.072200,0.270166,-0.478501,0.248232,-0.375380,-0.278099,-0.622907,0.278627,0.065259,0.117773,0.322691,-0.241127,0.025964,-0.042449,-0.140988,-0.095208,0.102260,-0.141001,0.319027,-0.064125,0.343815,0.269814,-0.233066,0.047484,0.196635,-0.061998,-0.513515,0.097304,0.231113,0.297064,-0.159233,0.139189,-0.184286,-0.150397,-0.149698,-0.256209,0.491950,0.361567,0.271651,-0.077745,-0.309368,-0.122312,-0.668703,-0.045250,0.532211,-0.089924,0.288637,0.208703,0.314229,-0.501591,-0.124180,0.096306,0.039117,0.118222,0.457580,0.256988,0.008380,0.398311,-0.462269,0.076218,-0.284877,-0.036849,0.247487,-0.193023,-0.335447,-0.470258,-0.325087,-0.066206,-0.067506,0.049569,0.347884,-0.041497,0.687416,-0.792491,0.195290,0.277917,0.163312,-0.550901,0.304798,0.061203,-0.166204,-0.220286,-0.323932,0.385710,0.189677,0.480230,-0.225794,-0.314631,-0.167387,-0.133937,-0.123057,0.299314', '1870682', '1301022', '35030151', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3305722', '刺陵', '动作', '网路作家蓝婷（林志玲 饰）写的小说人气很旺，她还遇到过一个自称排骨（曾志伟 饰）的粉丝索要签名。不过，蓝婷跟其父的关系很僵，所以后者派乔飞（周杰伦 饰）邀她共进晚餐。乔飞是打击盗墓走私的青年侠客，但是他与蓝婷之间也有误会。当晚，蓝婷突然遭遇车祸，被劫持。醒后，她发现劫匪竟是排骨一伙，为首的是深藏不露的华爷（陈道明 饰）。他们以蓝婷为人质，逼其父交出大漠的藏宝地图。没想到，前来谈判的竟是乔飞，他拿来了地图，同时也带来了蓝婷父亲意外丧命的消息。正在此时，突现的蒙面人将地图劫走。另有沙漠军团来袭，乔飞保护着蓝婷，两人互生情愫。众人先后来到浪人部落，乔飞意外发现劫走地图人的真面目，同时他们也渐渐揭开了失落古城的秘密……©豆瓣', '周杰伦', '朱延平', 3.9, 68306, 'tt1328865', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1505302123.jpg', 37, 37.9, 20.1, 2.8, 2.2, '0.076379,-0.140938,-0.520498,0.535796,0.082267,0.013264,0.613343,0.026483,-0.441858,-0.266986,0.444698,0.647472,-0.216480,0.204646,0.259101,0.037940,-0.181041,-0.632505,0.011314,-0.353300,-0.194859,-0.356589,-0.240439,-0.299133,0.150744,-0.285789,0.539797,-0.095701,-0.443189,0.592370,0.389138,0.109409,-0.545622,0.677260,-0.131904,0.257801,0.132362,-0.044840,-0.154390,0.005086,-0.302534,-0.285422,-0.168092,0.405126,-0.018559,0.579805,0.675542,0.017461,-0.256620,0.120612,0.161703,-0.257323,0.044800,-0.225766,0.460257,-0.019351,0.293963,0.059468,0.008908,-0.144134,0.034562,0.116676,-0.413286,0.271791,0.184402,0.210892,-0.403701,0.447754,-0.180370,-0.032708,0.016322,-0.137887,0.309747,0.427424,0.434236,-0.019760,0.095659,-0.064680,-0.513886,0.133392,0.464621,-0.103102,0.299880,0.291519,-0.057871,-0.474758,0.063169,-0.007646,-0.085290,0.287762,0.456816,-0.120858,-0.045982,-0.067227,-0.479223,-0.265680,-0.158222,0.255169,0.051585,-0.242264,-0.126234,-0.549847,-0.288958,-0.137285,-0.307356,0.188420,0.042812,-0.090404,0.596800,-0.203380,0.066214,0.491688,0.235834,-0.597664,0.453314,0.051545,-0.389812,-0.095319,-0.367573,0.056859,0.209723,0.097469,0.258990,0.104300,-0.057758,-0.262911,-0.156835,-0.087744', '1478066', '10466639', '1299135', '1293142');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3305873', '爱的发声练习', '爱情', '小猫（大S 徐熙媛 饰）从小父亲早亡，母亲随后另嫁他人。不过，她和聋哑妹妹对这个继父极为不满，因为后者经常偷窥她们洗澡，极为猥琐。在家庭得不到温暖的小猫，却在学校收获了一份纯爱。那个送吉他的男孩阿良（彭于晏 饰）身上拥有她极为珍视的品质，两人彼此相爱。但当小猫鼓足勇气准 备为他献身时，男人却婉拒了她。他坦言，要珍惜她的人，而不是贪图性。后来，阿良去服兵役，苦闷寂寞的小猫因为生活拮据，开始在网上援交。期间，她邂逅了一个有妇之夫小古（张孝全 饰），两个人深陷灵与肉的纠缠之中无法自拔……十年之后，小猫在一次同事聚餐中认识了sunshine（东明相 饰），这个跟妹妹一样聋哑的长发男孩，用他特有的方式温暖了她的心……©豆瓣', '徐熙媛', '李鼎', 5.5, 62971, 'tt1329101', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p886542944.jpg', 8.3, 27.1, 47.6, 13.6, 3.4, '0.344313,-0.055178,-0.645255,0.523659,-0.495093,-0.184033,0.907731,0.374442,-0.555593,-0.111341,0.160780,0.834775,-0.006327,0.559096,-0.066928,0.278281,0.012696,-0.594292,0.140129,-0.073480,-0.119790,-0.086071,-0.175355,-0.052424,-0.233313,-0.107300,0.623117,-0.137053,-0.105012,0.560518,0.159651,0.182446,-0.015065,0.534461,-0.454035,0.062398,-0.059707,0.186917,-0.049902,0.057802,0.058372,-0.056527,-0.137749,0.134563,-0.102316,0.310271,0.740233,-0.218303,-0.144748,-0.341312,0.371993,0.015451,-0.231072,0.234246,-0.037633,-0.012818,0.488887,-0.067422,-0.143910,0.017107,0.202665,-0.018154,-0.354420,-0.006920,-0.036786,0.153271,-0.547485,0.584958,-0.104116,0.007289,0.172905,-0.349617,0.069630,0.032906,-0.068788,0.317138,-0.295587,-0.064402,-0.281944,0.435269,0.690307,0.084557,-0.033439,0.630742,-0.584016,-0.481767,0.108015,-0.106438,-0.602062,0.028047,0.305534,-0.026973,-0.466262,0.045659,-0.593169,0.037999,0.032819,0.369921,-0.164668,-0.555916,-0.140391,-0.212854,-0.207927,-0.750331,-0.482949,-0.068954,0.094270,-0.315515,0.685302,-0.873755,0.157612,0.653575,0.301257,-0.550169,0.692784,0.172739,-0.038251,-0.334644,0.154462,0.235850,-0.088360,-0.122377,0.325769,0.326793,-0.034874,0.313839,-0.528540,0.449253', '4275444', '1292219', '1309161', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3310482', '蒸发的摩根夫妇', '喜剧', '居住在纽约的摩根夫妇生活优渥，丈夫保罗（休·格兰特 Hugh Grant 饰）在司法界声名远播，妻子梅莉（莎拉·杰茜卡·帕克 Sarah Jessica Parker 饰）则是房地产界的精英女强人。事业上的卓越成就无法弥合夫妇俩日渐凸现的情感矛盾，保罗的外遇更致使两人长期分居，婚姻濒临崩溃。在分居后的第三个月，保罗主动约出妻子，希望与之重归于好。晚餐过后，摩根夫妇在瓢泼大雨中偶然目睹一桩杀人案，他们清楚看到凶手（麦克·凯利 Michael Kelly 饰）的长相，而自己的容貌也被凶手尽收眼底。摩根夫妇此时恐怕首次要为自己的知名度而懊恼，因为凶手文森特毫不费力知道了他们的姓名。针对摩根夫妇的灭口追杀自此接连上演，他们只有抛弃一切，选择人间蒸发……©豆瓣', '莎拉·杰茜卡·帕克', '马克·劳伦斯', 6.2, 9847, 'tt1314228', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p563980108.jpg', 2.5, 15.5, 58, 19.9, 4.2, '0.015210,-0.125075,-0.845536,0.406925,-0.137202,-0.406425,0.672587,0.246807,-0.635684,-0.365220,0.352225,0.865260,-0.233455,0.248897,0.438206,-0.278573,-0.229912,-0.814633,0.075470,-0.408149,-0.090667,-0.656248,-0.188096,-0.391609,-0.009883,-0.244152,0.530948,0.066049,0.027684,0.479085,0.316033,0.313230,-0.287286,0.263142,0.068882,0.079946,0.112314,-0.043819,-0.806763,0.209008,-0.105172,-0.097390,0.156530,0.276355,-0.206332,0.369502,0.555639,-0.219412,-0.110171,-0.038779,0.314579,-0.322314,0.000307,0.404488,0.651261,-0.312754,0.211414,0.297138,-0.354087,-0.342663,0.006705,0.057921,-0.826693,0.260701,0.075769,0.273868,-0.439511,0.590139,-0.078773,-0.024290,-0.086373,-0.235142,0.097853,0.614958,0.401513,0.368679,-0.163768,0.110349,-0.457190,0.035437,0.727435,0.062323,0.101916,0.260087,-0.274158,-0.132410,-0.067811,-0.427400,-0.516754,-0.067310,0.440640,0.244537,-0.075303,0.567852,-0.210293,-0.258578,-0.466952,0.133598,-0.068582,-0.477083,0.084484,-0.663894,-0.277938,-0.328155,-0.271327,-0.016101,0.049220,-0.427992,0.383879,-0.789732,0.254762,0.140797,0.318754,-0.620268,0.474826,0.208469,0.368257,-0.320502,-0.161297,0.456018,0.270667,-0.007479,0.002416,0.015335,0.115676,-0.072340,-0.282536,0.398914', '26678784', '1301022', '24325856', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3312344', '证人', '动作', '沙展唐飞（谢霆锋 饰）办案追求快狠准，行动极为猛烈。在追捕疑犯张日东时，卖命追车超车，最终引发一场连环车祸，张日东一伙除却张自己重伤昏迷，其他全部当场死亡，然而在车后厢，唐飞发现被自己飞弹射死的小女孩，不禁愕然。二个月后，张日东苏醒，法院正式排期起诉他。检控官高敏（张静初 饰）正是当日被误杀的小女孩的母亲，与丈夫离婚的她如今把所有的爱都倾注在小女儿丁玲身上。活在愧疚感中的唐飞这两个月中也一直关注着丁玲，看见丁玲便又仿佛看见当日悲剧。身体残疾面目可怖的洪荆（张家辉 饰）以帮人绑架并灭口来赚取金钱，这次他接到的任务是绑架丁玲以挟持高敏，让高敏盗取对张日东不利的证供。丁玲的被绑架撕碎了高敏的心，唐飞不求一切代价拼尽全力去追寻丁玲下落。这些被事情串在一起的人们，都是当日那场连环车祸的受害者。每个人的生命都是在那日被改变，每个人背后都有自己不为外人道的故事，这会导出一个怎样的结局？丁玲能安然无恙地归来吗？', '谢霆锋', '林超贤', 7.3, 96440, 'tt1330525', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2192288625.jpg', 0.4, 3, 38.4, 46.9, 11.3, '0.052911,-0.057043,-0.658109,0.383351,-0.297425,-0.225698,0.747667,-0.129369,-0.219514,-0.209999,0.371409,0.685163,-0.237666,0.251349,0.024808,-0.080680,-0.032570,-0.725406,-0.244350,-0.003498,-0.394335,-0.417079,0.013325,-0.149210,-0.041618,-0.117081,0.477139,0.075955,-0.195818,0.488365,0.507177,0.333695,-0.269288,0.623605,-0.036196,0.217035,-0.188886,-0.046050,0.001713,0.044878,-0.024920,-0.540152,-0.051518,0.411667,-0.267275,0.433105,0.673113,-0.076700,-0.156376,-0.199450,0.448760,-0.539714,-0.010327,0.259446,0.342254,-0.027327,0.176722,0.242809,-0.339119,-0.101956,0.238622,0.197010,-0.747070,-0.147851,0.203810,0.056812,-0.684853,0.260724,-0.153436,0.208049,0.209368,-0.119130,0.321173,0.384028,0.131872,0.328612,-0.316762,-0.114802,-0.541388,0.225961,0.892124,-0.253493,-0.055023,0.201507,0.020740,-0.320515,-0.066321,-0.085168,-0.194982,0.158438,0.435727,0.105024,-0.182918,0.177148,-0.137149,-0.109127,-0.198444,-0.028965,-0.334142,-0.387499,-0.090847,-0.354495,-0.213505,-0.316049,-0.424818,0.165213,0.041330,-0.362186,0.398554,-0.445961,0.168600,0.529423,0.108396,-0.487071,0.321155,0.221758,0.053517,-0.046172,-0.146938,0.154285,0.263858,0.293272,0.067091,0.141792,0.152578,0.165165,-0.269325,0.430852', '1309116', '25828589', '1294941', '1305386');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3313801', '非诚勿扰', '喜剧', '海归秦奋（葛优 饰）的天才发明“分歧终端机”因能公平和平地解决人类分歧，被风投者以200万英镑高价买走。秦奋也开始踏上网上征婚的路途，一路笑话不断，不是重遇Gay友，就是遇到推销客，秦奋颇有点心灰意冷，以致遇到清冷女子梁笑笑（舒淇 饰）时便开门见山请求对方说明来意。这次更为棘手，笑笑爱上有妇之夫，陷于苦恋中不停挣扎，这次纯属听从家里人安排才出来与秦奋见上一面。不再打算再见的二人尽情地分享了生命中最隐秘的秘密。然而不久，打算和旧爱分手的笑笑找到秦奋，说要嫁给他,但想与他先去北海道一趟。因她与旧爱的爱情是在那里开始的，如今想在那里结束。秦奋答应了。二人踏上北海道之旅，秦奋在北海道的老友对他们盛情招待，三人游遍北海道各处，秦奋知道自己得不到笑笑的心，却不知道笑笑心中抑郁难解的结正冲向海底的漩涡……©豆瓣', '葛优', '冯小刚', 7.2, 404509, 'tt1330607', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p484914984.jpg', 0.9, 4.5, 39.5, 42.5, 12.6, '0.423107,0.123767,-0.670934,0.343398,-0.028787,-0.237234,0.580913,-0.206680,-0.407654,-0.161631,-0.226764,0.685114,-0.099895,0.215567,0.353211,-0.013619,-0.363506,-0.377393,0.067414,-0.252378,-0.054842,-0.606873,0.047690,0.021183,-0.320483,0.106183,0.531113,0.327670,-0.292805,0.684981,0.268584,0.289091,-0.142298,0.658198,-0.297108,-0.026234,-0.299702,0.286290,-0.550260,0.244629,0.266709,-0.239356,-0.305689,0.238239,0.124250,0.221939,0.388296,-0.048207,-0.098016,0.028370,0.065910,-0.327486,0.056426,0.125721,0.077977,0.224963,0.196787,0.161301,-0.161360,0.056301,0.081929,-0.124577,-0.330980,0.036202,0.108019,0.069888,-0.419004,0.260862,-0.153573,-0.101758,0.076152,-0.541644,0.234771,0.334700,0.410260,0.223004,-0.135353,-0.023227,-0.500765,-0.016822,0.825139,0.174696,0.200583,0.279555,0.141579,-0.318127,0.103469,0.004140,-0.218956,-0.146410,-0.017046,0.316287,-0.116109,0.005844,-0.435689,0.067740,-0.037400,-0.141884,0.027308,-0.526135,0.028685,-0.221906,-0.226206,-0.326110,-0.106227,0.111514,-0.149824,-0.307859,0.292314,-0.721714,0.180976,0.275312,0.555431,-0.538440,0.628830,0.417479,-0.043546,-0.456193,0.201582,-0.011255,-0.089202,-0.007563,0.093075,0.116079,0.201947,-0.084444,-0.321869,0.069481', '25721544', '1300553', '25908042', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3317370', '定制伴郎', '喜剧', '道格（乔什·盖德 Josh Gad 饰）和格雷琴（卡蕾·库科 Kaley Cuoco 饰）是相恋多年的情侣，彼此之间感情十分的稳定。终于，这对爱侣决定携手步入婚礼的殿堂，对于格雷琴来说，举办一场完美而又盛大的婚礼是她人生必要实现的梦想之一，而一位称职的伴郎是一场梦幻婚礼必不可要的要素，这正是道格所缺少的。于是，道格找到了名叫吉米（凯文·哈特 Kevin Hart 饰）的男人，后者经营着一家伴郎介绍所，专门为道格这样的准新郎提供服务。刚开始，吉米和道格针锋相对，处处产生摩擦，好在两个男人的目标是一致的，最终，他们能否化解恩怨，共同成就一场美好的婚礼呢？©豆瓣', '凯莉·库柯', '杰里米·加尔利', 7.1, 11270, 'tt0884732', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2212202680.jpg', 0.8, 5.7, 42.8, 38.8, 11.9, '0.074806,0.078146,-0.613012,0.682800,-0.142997,-0.251979,0.690644,0.204408,-0.281899,-0.206952,0.194957,0.815238,-0.246513,0.302596,0.665649,0.075159,-0.082343,-0.845891,-0.122668,-0.006914,-0.122739,-0.589995,-0.111741,-0.131692,-0.030994,-0.265441,0.614487,-0.000430,0.021733,0.354840,0.699270,0.361106,0.011333,0.150113,-0.223232,-0.353550,0.138587,0.098670,-0.871043,0.039709,-0.025064,0.136404,-0.204240,0.378674,-0.017167,0.221589,0.460718,-0.427118,-0.138664,0.055236,0.473514,-0.326675,0.165926,0.084717,0.057741,-0.026667,0.270793,0.351890,-0.239067,-0.027965,0.199628,-0.284678,-0.789137,0.090946,0.245879,0.041861,-0.587342,0.731764,0.111452,-0.303106,0.085519,-0.182275,0.032182,0.641963,0.573962,0.268330,-0.089334,-0.085487,-0.362977,0.138053,0.959541,0.124648,-0.182377,0.576455,-0.292888,-0.463893,-0.021620,-0.149882,-0.456403,-0.060671,0.284798,0.000753,0.384275,0.161099,-0.650738,-0.100335,-0.365037,-0.058347,0.259845,-0.656857,0.213212,-0.869563,-0.253628,-0.517299,-0.403671,0.127020,0.112450,-0.482810,0.702414,-1.047517,-0.078555,0.502202,0.024891,-0.393066,0.667349,0.414190,0.434487,-0.557234,-0.196902,-0.009783,-0.422341,-0.093968,-0.146139,0.405368,0.344345,-0.002844,-0.393053,0.514761', '4301278', '11541282', '26971054', '10876425');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3318306', '电影43', '喜剧', '三个毛头小子正在自拍他们号称“世界上最酷最疯狂”的搞笑视频短片“靶心”。看到互联网上频繁暴增的点击量，三人动心不已，着手筹备一部大项目——一部世界上最危险的影片，他们叫它《电影43》。当他们键入“电影43”到一个私人服务器的时候，发现了禁止视频。随即而来的《电影43》的播放列表，不仅让三人瞠目结舌，更足以让你在这十二个独立又相互关联的故事中，惊喜交加。这部由十一名导演、十五位编剧和十一个剪辑师共同打造的《电影43》，群星云集，带来史上最强明星阵容，艾玛·斯通、哈莉·贝瑞、凯特·温丝莱特、科洛·莫瑞兹等十几位好莱坞大牌明星联袂亲情演绎。众多知名明星使出浑身解数，颠覆形象之余大秀搞怪底线，上演一出爆笑连连的喜剧视觉大餐。©豆瓣', '艾玛·斯通', '伊丽莎白·班克斯', 6.4, 15747, 'tt1333125', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1814704269.jpg', 6.8, 15.7, 40.4, 24.1, 13.1, '0.124337,0.085232,-0.718074,0.717313,0.651252,0.176252,0.621288,0.072551,-0.147350,0.000915,0.192728,0.699026,-0.760689,0.163927,0.333859,-0.592462,-0.220489,-0.638142,-0.255665,-0.200214,-0.051958,0.014586,-0.386175,-0.110950,-0.001982,-0.431592,0.521545,-0.242401,-0.400480,0.140098,0.662647,-0.140530,-0.216222,-0.049223,0.205909,0.134356,0.358711,-0.150063,-0.363447,0.403111,-0.339696,-0.127874,-0.153733,0.128397,-0.276671,-0.093765,0.584616,-0.073430,-0.064607,-0.065638,0.582647,-0.031291,-0.304758,-0.174127,-0.026402,-0.042040,0.540220,-0.280460,0.196239,0.214894,-0.122498,-0.095875,-1.291933,0.134826,0.147328,0.161913,-0.286079,0.077791,-0.136060,-0.071497,0.006233,-0.316359,0.131311,-0.035613,0.564102,0.289238,-0.048634,0.069559,-0.169007,0.486849,0.393984,0.210024,-0.327320,0.428225,0.093777,-0.227607,-0.370357,-0.269276,-0.482823,0.212994,0.496959,-0.255029,0.300992,0.091819,-0.729810,0.137008,0.172978,-0.618009,-0.122266,-0.242785,0.173076,-1.280599,-0.198415,-0.054452,0.043552,-0.092007,0.344850,-0.328061,1.224130,-0.229201,0.031497,0.329535,0.057744,-0.300303,0.750420,0.098853,-0.030997,-0.365536,-0.229160,-0.163661,0.221646,0.077962,-0.033486,0.321594,-0.138115,-0.248066,-0.414553,0.453388', '27602116', '2027945', '22265121', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3318473', '妻子结婚了', '喜剧', '在别人眼里，仁雅（孙艺珍 饰）到目前为止的人生绝对都是完美的令人嫉妒。想法奇妙，又是狂热球迷的她却有一个大家公认的好好丈夫德勋（金柱赫 饰）来包容和宠溺。对于德勋而言，妻子是世界上最好的女人，拥有众多追求者的仁雅最后却选择了他，让他甘愿包揽所有的家务事，尊听妻子的话，给予她最大限度的自由。可这些无边无尽的包容却似乎还是抵不过妻子的好奇心。终于有一天，妻子颇为严肃的对德勋说，我想要再婚！听到这句话的德勋经历了从“愣住了”到反思自己的过程，最后不得不帮助妻子实现她的重婚计划……本片改编自韩国第二届世界文学赏的获奖小说，上映后获得了多项大奖。©豆瓣', '金柱赫', '郑允秀', 6.5, 8841, 'tt1329470', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1284966982.jpg', 4.5, 15.2, 44.2, 24, 12.1, '-0.256914,0.261083,-0.776114,0.808535,-0.261849,-0.187098,0.729264,0.025782,-0.623907,0.064129,0.199161,0.646221,-0.264786,0.248887,0.183053,0.018548,-0.078831,-0.489238,-0.051882,-0.225253,-0.210909,-0.387446,-0.135579,-0.018800,-0.215115,-0.238534,0.767900,0.141000,-0.313280,-0.027675,0.437879,0.257321,0.255992,0.670011,-0.261488,0.054841,-0.105852,0.193903,-0.354044,0.119841,0.052460,-0.058755,-0.399254,0.435161,-0.253616,0.069268,0.507104,-0.196972,-0.322608,0.255277,0.528085,-0.393746,-0.094448,0.076945,-0.116651,-0.085726,0.367495,0.239979,0.023136,-0.112990,0.013356,-0.022527,-1.155956,-0.270327,0.173269,-0.016921,-0.465124,0.476047,-0.080050,-0.059305,0.167782,-0.192274,0.194778,0.068859,0.244070,0.517538,-0.356883,0.183892,-0.298879,0.362950,0.576348,-0.114211,-0.324925,0.502940,-0.468751,-0.495449,-0.023543,-0.279066,-0.628638,0.183553,0.053595,0.332541,-0.202231,0.361479,-0.311178,0.089673,0.026191,-0.392851,0.146872,-0.906709,0.145932,-0.149005,-0.236644,-0.359591,-0.364023,0.043244,0.292154,-0.491706,1.065158,-0.838628,0.225930,0.502689,0.220173,-0.601505,0.755094,0.284984,-0.021125,-0.299231,-0.128079,0.384948,-0.225368,-0.022721,-0.045942,0.276070,0.116553,-0.101123,-0.338505,0.748025', '30163500', '27602116', '25932086', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3319741', '夺命深渊', '剧情', '在巴布亚新几内亚某地一个人迹罕见的原始丛林腹地，有一个号称洞穴之母的巨洞——伊萨·阿拉。腰缠万贯的探险家卡尔（Ioan Gruffudd 饰）一掷千金，雇用拥有丰富洞穴探险经验的弗兰克（Richard Roxburgh 饰）及其团队对这里进行勘查。转眼之间几个月过去，伊萨·阿拉的勘探虽然颇见成效，但进度仍显缓慢。与此同时，强烈的热带风暴即将到来，洞穴探险迫在眉睫。卡尔为此和弗兰克发生争吵，而后者孤注一掷，和早已身心疲惫的搭档茱德（Allison Cratchley 饰）潜入水中，挑战有着“魔鬼之限”之称的凶险通道。另一方面，卡尔的女友维多莉亚和弗兰克的儿子乔希也到洞中探险。殊不知灭顶之灾正在逼近……本片根据Andrew Wight在西澳大利亚探洞时的真实经历改编，采用《阿凡达》的3D摄像机拍摄。©豆瓣', '瑞斯·维克菲尔德', '阿里斯特·格里尔森', 7.4, 36431, 'tt0881320', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p738254395.jpg', 0.8, 4.6, 34.4, 44.5, 15.7, '0.248311,-0.066868,-0.776383,0.572110,0.314642,-0.038584,0.825453,-0.038143,-0.506926,-0.140985,0.413620,0.420450,-0.153728,-0.270703,0.313225,-0.074217,-0.304070,-0.312720,-0.298195,-0.122777,-0.365881,-0.441008,-0.547358,-0.022249,-0.092129,-0.453274,0.692430,0.264712,-0.062622,0.539662,-0.013537,0.338862,-0.255335,0.516454,0.040985,-0.244504,0.408413,0.001489,-0.176392,0.212747,-0.312544,0.101773,-0.261165,-0.024731,0.089936,0.589222,0.584265,-0.276076,-0.153498,0.083429,0.440758,-0.183551,-0.082799,-0.020908,0.559696,0.048787,0.057202,0.064572,-0.066139,0.015095,-0.194813,-0.417411,-0.734141,-0.014944,0.176379,0.187201,-0.294774,-0.004829,0.042091,-0.204672,0.248699,-0.379279,-0.082754,0.335444,0.240072,0.188286,-0.005192,0.120022,-0.418812,-0.102712,0.449803,0.000310,-0.186376,0.012450,-0.100096,-0.538479,0.045942,-0.151438,-0.328448,-0.186593,0.282903,-0.051658,-0.171589,0.308933,-0.774154,0.344864,-0.365834,-0.450859,-0.107872,-0.178783,-0.247771,-0.953033,-0.134238,-0.406814,-0.118484,0.060814,0.020795,-0.211997,0.446938,-0.547417,0.359857,0.622738,0.045652,-0.041881,0.582733,-0.172483,0.073754,-0.328793,-0.195177,0.751156,0.018834,0.275433,-0.155957,0.403802,0.022339,-0.240819,-0.546246,0.396086', '1316693', '2159244', '1293433', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3319755', '怦然心动', '剧情', '布莱斯（卡兰•麦克奥利菲 Callan McAuliffe 饰）全家搬到小镇，邻家女孩朱丽（玛德琳•卡罗尔 Madeline Carroll 饰）前来帮忙。她对他一见钟情，心愿是获得他的吻。两人是同班同学，她一直想方设法接近他，但是他避之不及。她喜欢爬在高高的梧桐树上看风景。但因为施工，树被要被砍掉，她誓死捍卫，希望他并肩作战，但是他退缩了。她的事迹上了报纸，外公对她颇有好感，令他十分困惑。她凭借鸡下蛋的项目获得了科技展第一名，成了全场焦点，令他黯然失色。她把自家鸡蛋送给他，他听家人怀疑她家鸡蛋不卫生，便偷偷把鸡蛋丢掉。她得知真相，很伤心，两人关系跌入冰点。她跟家人诉说，引发争吵。原来父亲一直攒钱照顾傻弟弟，所以生活拮据。她理解了父母，自己动手，还得到了他外公的鼎力相助。他向她道歉，但是并未解决问题。他开始关注她。鸡蛋风波未平，家庭晚宴与午餐男孩评选又把两人扯在了一起……', '玛德琳·卡罗尔', '罗伯·莱纳', 9.1, 1715092, 'tt0817177', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p501177648.jpg', 0.1, 0.5, 6.6, 30.7, 62.2, '0.173293,-0.025577,-0.791537,0.299234,-0.347459,-0.088870,0.566034,0.218072,-0.323774,0.210411,0.047454,0.808915,-0.260423,0.181283,-0.171720,0.206118,-0.165813,-0.666964,0.451230,0.058154,-0.064304,-0.351359,-0.091604,-0.281613,-0.348119,-0.007174,0.295263,-0.156132,-0.133538,0.313370,0.061983,-0.090567,0.260406,0.761997,-0.261767,0.235313,-0.244054,0.039536,-0.022067,0.032187,0.119146,-0.315241,-0.291938,0.479860,0.190041,0.375833,0.508172,0.124415,-0.203138,-0.053511,0.042511,-0.487102,0.126813,0.374375,0.157159,-0.005232,-0.077877,0.036243,-0.188875,-0.283333,0.132832,0.013168,-0.175430,0.109984,-0.081925,0.121530,-0.711515,0.581538,-0.325852,0.108111,0.098217,-0.295802,0.160993,0.124046,0.089522,0.143501,-0.227890,-0.099398,-0.590799,0.173568,0.771082,-0.085949,0.186819,0.358445,-0.343806,-0.266544,0.111580,-0.254259,-0.460999,0.150177,0.324845,0.007263,-0.194954,0.104839,-0.306445,-0.195603,-0.182246,-0.292866,-0.046555,-0.615415,-0.000239,-0.154221,-0.242154,-0.358088,-0.723495,-0.312137,-0.051520,-0.647568,0.674309,-0.671986,0.010310,0.510263,0.592056,-0.609000,0.738657,0.029122,0.009262,-0.226585,0.043357,0.221228,-0.001448,-0.003675,0.427901,0.217192,0.070155,0.161576,-0.286825,0.510890', '26718282', '1857175', '21447058', '3504940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3319775', '精彩的一天', '剧情', '喜秀（全度妍 饰）年过三十却依然单身，事业、爱情无一成功的她是一个标标准准的“loser”，就当她快要跌落到人生谷底之时，喜秀突然想起，自己的前男友秉云（何正宇 饰）曾经向自己借过三百五十万韩元至今仍为归还，这笔巨款成为了喜秀最后的希望。功夫不负有心人，喜秀终于找到了许久未曾联系的秉云，而直到此时，喜秀才发现，原来秉云的处境和自己相比好不到哪里去，他又怎么可能会有三百五十万的存款呢？好在秉云有着自己一套独特的圈钱技巧，那就是他英俊帅气的外表，靠着这张面皮，秉云开始了他的计划。一个走投无路的女人，一个浪迹天涯的男人，他们两人的纠葛会迎来怎样的结局呢？©豆瓣', '全度妍', '李胤基', 7.6, 7974, 'tt1330205', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p584881436.jpg', 0.5, 4, 30.4, 45.7, 19.4, '-0.063423,0.156612,-0.803670,0.551569,-0.376655,-0.617201,0.581273,-0.069810,-0.460328,-0.185006,0.316022,0.712734,-0.089372,0.337473,0.139215,0.245634,0.129183,-0.680854,0.027028,-0.395000,-0.384364,-0.165272,-0.617546,0.151478,-0.055476,-0.071028,0.512306,0.116987,-0.039089,0.178916,0.387529,0.141291,0.253048,0.506452,-0.383919,0.074915,-0.042949,0.303522,-0.043469,0.236035,0.107394,-0.225539,-0.278817,0.124457,-0.323754,0.510642,0.686607,-0.020759,-0.365091,0.266313,0.427830,0.034397,-0.213016,0.251756,0.160637,-0.151142,0.225108,-0.039580,-0.302219,-0.124206,0.041640,0.079070,-0.719807,-0.166290,-0.092438,0.143030,-0.602458,0.342108,-0.222212,-0.078866,0.001650,-0.473023,-0.032119,0.381491,0.265437,0.377067,-0.328136,-0.025957,-0.653834,0.415760,0.688548,0.115939,-0.310754,0.610563,0.029174,-0.561631,-0.151301,-0.357477,-0.356776,0.076704,0.354777,0.117760,-0.150321,-0.113335,-0.578204,0.113104,-0.305775,0.009002,0.030040,-0.357200,-0.183795,0.027603,-0.322784,-0.606011,-0.332797,0.238511,-0.004805,-0.461244,0.681847,-0.618320,0.150349,0.524663,0.140844,-0.531395,0.551553,0.226412,-0.191868,-0.156574,-0.028647,0.040892,-0.117445,0.213491,0.062761,0.114349,0.085664,-0.152964,-0.433435,0.664874', '25763555', '1783461', '30162520', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3319776', '美人图', '爱情', '《美人图》说的是朝鲜史上有名的女扮男装天才画家申润福的故事。申润福（金敏善 饰）的父亲将家族的兴旺寄予这个可怜的女孩，隐藏其女儿身，改以男儿身打扮亮相，跟随着当地有的画家金洪道（金英浩 饰）学习，苦学画技，以卖画给地主们维持生计。性格粗野的姜武（金南吉 饰）是市井青铜镜商人，一次偶然中发现了申润福的女人身份，与她相爱，并使润福认识到身为女人如命运般的爱情。但申润福的老师金洪道与徒弟之间也有一种奇妙的感情，他不容许润福背叛自己，千方百计阻止润福和姜武。而名妓雪花（秋瓷炫 饰）则深爱着金洪道。四个人将会走向何处？申润福和姜武能守护住自己的爱情吗？申润福的女子身份会被揭露吗？最终她是否能改变自己的一生，成为朝鲜知名画家？©豆瓣', '金圭丽', '田昀树', 6.6, 19490, 'tt1330206', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1773312906.jpg', 1.4, 9.9, 53.1, 27.9, 7.7, '0.151901,-0.056808,-0.400549,0.680686,-0.243492,-0.009605,0.593320,0.056992,-0.444212,-0.303708,0.191485,0.873541,0.060883,0.220413,0.247532,0.129698,0.069935,-0.874712,0.060345,-0.131235,-0.010445,-0.229150,-0.311129,-0.260516,-0.233755,-0.228883,0.726322,0.014500,-0.258548,0.292173,0.392640,0.368073,-0.206894,0.055267,-0.348764,-0.091462,-0.030863,0.174493,-0.211006,0.121215,-0.085523,-0.248889,-0.090053,0.072927,-0.357409,0.204965,0.504582,-0.442212,-0.078003,-0.116892,0.507368,-0.184220,-0.144287,0.157785,0.081213,-0.068726,0.221930,0.330550,-0.164763,-0.011543,0.098073,-0.142857,-0.619328,-0.194433,0.541977,0.191717,-0.707294,0.385187,0.025812,-0.446038,-0.012465,-0.303624,0.223624,0.071561,0.408590,0.232964,-0.063417,-0.015011,-0.522927,0.394282,0.577180,0.190608,-0.315118,0.331311,-0.314530,-0.319305,-0.005182,-0.612429,-0.623554,0.203118,-0.019158,0.018416,-0.015339,0.023027,-0.438233,-0.100968,-0.219461,0.224338,0.161173,-0.586067,-0.176131,-0.213799,-0.314811,-0.688898,-0.256231,-0.181615,0.216118,-0.457243,1.014699,-0.850627,0.028420,0.375176,0.211593,-0.695593,0.715015,0.265924,-0.049222,-0.126634,-0.239372,0.142513,0.108879,-0.176425,-0.334775,0.117913,0.017889,0.000951,-0.188933,0.322955', '27602116', '4301278', '26283288', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3321409', '别让我走', '剧情', '28岁的女子凯西（凯瑞·穆丽根 Carey Mulligan 饰）自幼生活在校风严谨的寄宿学校海尔森，汤米（安德鲁·加菲尔德 Andrew Garfield 饰）和露丝（凯拉·奈特莉 Keira Knightley 饰）是她最重要的两个朋友。少男少女们在英国乡间那温暖阳光的沐浴下，度过了人生最青涩浪漫的时刻，也收获着真挚的友情。然而某天，少男少女们却从露西老师（莎莉·霍金斯 Sally Hawkins 饰）的口中得到一个令人震惊的消息：海尔森的终极目标是将他们培养成器官捐献者，他们必须无私地奉献自己的一切，直到年轻的生命之花凋零。在18岁之际，他们得以走出海尔森，去往各地的寄宿学校。黯然的命运如影随形，在短暂的生命中他们还将经历更多……本片根据英国日裔小说作家石黑一雄的同名原作改编，并荣获2010年英国独立电影节最佳女主角奖（Carey Mulligan）。', '凯瑞·穆里根', '马克·罗曼尼克', 7.7, 83283, 'tt1334260', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p564143648.jpg', 0.6, 3.4, 29, 46.5, 20.5, '0.204784,0.046254,-0.573646,0.505291,-0.064450,-0.362194,0.733295,0.026658,-0.218786,-0.264006,0.259575,0.876939,-0.197624,0.456014,0.403629,0.111917,-0.419149,-0.737635,-0.142555,-0.179042,-0.140660,-0.390335,-0.155481,-0.159105,-0.099322,-0.487810,0.722438,0.144590,0.179959,0.419948,0.229694,0.332014,-0.110147,0.188700,-0.234245,0.037882,0.376567,-0.090348,-0.319099,0.168740,-0.018442,-0.308426,-0.287484,0.054363,0.108666,0.160648,0.806918,-0.373627,0.052911,-0.066212,0.556159,-0.280392,-0.157895,0.058298,0.248609,-0.214523,0.141989,0.372648,-0.009971,0.131343,-0.049097,-0.274309,-0.815416,-0.205100,0.089066,0.278645,-0.501258,0.494643,0.110531,-0.025297,0.293440,-0.340380,0.120664,0.169672,-0.020383,0.240116,-0.235699,0.072805,-0.332709,0.360010,0.497476,-0.049574,-0.430738,0.456812,-0.684531,-0.658253,-0.053057,-0.167333,-0.600249,-0.138466,0.399119,-0.014962,0.135812,0.259496,-0.651575,-0.033142,-0.184390,-0.312804,0.030602,-0.311047,-0.180545,-0.676641,-0.111604,-0.548068,-0.498139,0.128002,0.108373,-0.314552,1.108899,-0.710175,0.121217,0.640834,0.155320,-0.082486,0.619046,-0.001000,0.201591,-0.169782,-0.278519,0.572654,-0.042589,0.202995,-0.001654,0.398003,-0.203237,0.052351,-0.529499,0.576864', '3811356', 