INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33218345', '知晓天空之蓝的人啊', '动画', '茜（吉冈里帆 配音）和葵（若山诗音 配音）在很早之前失去了父母沦为孤儿，为了照顾妹妹，茜放弃了和当时的恋人金室慎之介（吉沢亮 配音）前往东京的计划，留在家乡找了份工作，扮演起了母亲的替代角色。一晃眼就是13年过去。如今，葵出落成为了大姑娘，身为一名高二学生，葵并没有将心思放在考试和升学上，每天都漫无目的的弹着贝斯，毫无干劲。茜将这一切看在眼里，感到非常的着急。某日，镇上举办了音乐会，在现场，葵意外的发现了金室慎之介的身影，他回到了这个小镇上！与此同时，13年前年仅18岁的慎之介亦穿越来到了姐妹两人的身边。©豆瓣', '吉泽亮', '长井龙雪', 7.7, 11357, 'tt10981202', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2571473945.jpg', 0.7, 3.7, 27.9, 44.4, 23.3, '0.310951,-0.122776,-0.611033,0.337878,-0.097611,-0.502696,0.460541,0.094458,-0.399845,-0.494610,-0.196201,0.689880,-0.183567,0.453419,0.508106,-0.050303,-0.323173,-0.828221,-0.342394,-0.373420,-0.170013,-0.524961,0.296445,0.139587,-0.192494,-0.426026,0.673456,-0.133057,0.118722,0.830863,0.142795,0.233987,-0.192348,0.168050,-0.090630,0.226556,-0.016284,-0.019052,-0.108215,0.301894,-0.122316,-0.297301,-0.132676,0.265981,0.419754,0.357391,0.934172,-0.152059,-0.154063,-0.207724,0.312991,-0.273427,-0.239733,0.055687,0.388788,0.050108,-0.013785,0.008789,-0.431994,-0.101636,-0.092909,-0.441260,-0.534383,0.157734,0.121622,0.066186,-0.680136,0.468416,-0.001164,-0.088029,0.095663,-0.459170,0.430746,0.413342,-0.240834,0.434657,-0.366516,0.213849,-0.271555,0.214932,0.807832,-0.007198,0.115851,0.467321,-0.047501,-0.101280,-0.176826,-0.134788,-0.347273,0.096927,0.011354,0.202480,-0.007852,-0.047512,-0.285634,-0.178640,-0.053667,-0.237082,0.367492,-0.485832,-0.241501,-0.581298,0.092711,-0.180891,-0.464320,0.072493,-0.097899,-0.497699,0.733531,-1.224085,0.134647,0.440463,0.456881,-0.153873,0.580521,-0.227423,0.128529,-0.242598,0.037723,0.045122,-0.173157,0.350438,0.241212,0.248729,-0.273460,-0.173684,-0.607513,0.437072', '35030151', '1292219', '30345227', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33218378', '奇门遁甲', '剧情', '从小痴迷于研究雾隐门的罗刹镇捕头周同，原本和罗刹镇父母官县令周守义过着太平日子，不料却被镇中乡绅之子贾明与父亲贾有为联手设计陷害，使得周同父亲蒙冤入狱，周同侥幸逃脱途中偶遇奄奄一息的雾隐门天老，天老濒死之际将体内的“甲”传给周同，周同想凭借“甲”的力量救出父亲，却眼睁睁看着父亲被妖人毕方害死。周同被雾隐门救走，并跟随雾隐门学习奇门技法顺利通过入门仪式。就在雾隐门人要帮助周同取甲的时候，周同独自找到毕方想要为父报仇，却被毕方生生抽出身体内所有的“甲”，好友小跳蚤也因其牺牲，失败后的周同万念俱灰。毕方得逞后要将雾隐门的远古基地覆灭，雾隐门人不惜一切代价阻拦妖人毕方，危机时刻周同顿悟明白自身的责任担当，勇于直面危险不再逃避，当他顿悟之时，能力竟然奇迹般地回到了他身上，周同最终利用奇门遁甲的强大力量，从毕方手中救下雾隐门人，挽救了这次危机。', '贺鹏', '项秋良', 5.2, 18912, 'tt12008944', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2590460570.jpg', 9.3, 32.8, 47.6, 7.3, 3, '-0.042526,0.207150,-0.512996,0.383851,-0.040850,-0.241928,0.182982,-0.026983,-0.539693,-0.528008,-0.001575,0.529348,0.146633,0.307021,0.005999,-0.251294,0.122514,-0.511959,-0.300650,0.036152,-0.173620,-0.202125,-0.169343,-0.018801,-0.271344,-0.463956,0.741661,0.381186,-0.275968,0.353590,0.133505,0.255969,-0.454832,0.346473,-0.041394,-0.177151,-0.186035,-0.025868,-0.217649,0.248471,-0.003069,-0.270118,-0.109248,0.229769,0.059029,0.234019,0.495129,-0.300646,-0.068013,-0.485876,-0.025805,-0.477328,-0.054368,0.140213,0.223277,0.165617,0.075292,0.298482,-0.105560,-0.301645,-0.063864,-0.101706,-0.768908,-0.015136,0.144093,-0.253323,-0.521179,-0.003038,-0.080421,0.143954,-0.031748,-0.384132,0.147072,0.227010,0.139750,0.117558,-0.474180,-0.087743,-0.381597,-0.055326,0.697584,-0.581209,0.019074,-0.084079,0.175382,-0.205261,0.246327,-0.390294,0.121125,0.170736,0.590511,0.313738,-0.002112,0.132382,-0.108466,-0.311672,-0.540674,0.325016,-0.151169,-0.030285,0.038992,-0.135052,-0.134322,0.157753,-0.252467,-0.094100,-0.000308,-0.334945,0.438565,-0.592312,0.375894,0.445234,0.313317,-0.545835,0.231805,-0.107018,0.318073,-0.180869,-0.051775,0.198233,0.214229,0.635827,0.303576,0.051616,-0.048504,-0.124415,-0.060616,0.028159', '30345227', '3861846', '26678784', '1293605');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3321892', '迪迦奥特曼：最终圣战', '动作', '在邪神加坦杰厄和迪迦奥特曼的决战结束后，人类世界迎来了长达两年的和平岁月。这一日，入间队长随同GUTS考古队来到位于南太平洋的远古遗迹露露耶，他们再次发现了业已毁灭的超古代城市以及三尊邪神的石像希特拉（婆裟羅天明 饰）、达拉姆（松田優 饰）及女领袖卡美拉（芳本美代子 饰）。入间极力反对对古迹的触动，但丝毫无法改变上层的决定，最终导致三尊邪神复活，人类再度面临危机。与此同时，圆·大古（长野博 饰）与柳濑·蕾娜（吉本多香美 饰）相知相守，即将步入婚礼的殿堂。可是邪神指挥其爪牙向人类世界发起进攻，早已丧失奥特曼力量的大古，面对当前的危机束手无策。三千万年前毁灭人类文明的遥远记忆，折磨着重新大古与迪迦奥特曼的神经……©豆瓣', '长野博', '村石宏实', 8.9, 17749, 'tt0228982', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2385140076.jpg', 0.6, 1.1, 9, 29.2, 60.2, '-0.015923,0.334371,-0.626561,0.269468,0.495895,-0.105361,0.595009,0.191821,-0.196897,-0.331610,0.359748,0.488747,-0.238155,0.032284,0.492343,-0.024388,-0.313048,-0.540580,0.050424,0.064646,-0.222462,-0.211586,-0.338654,0.069363,-0.052787,-0.633576,0.971747,0.230501,-0.114762,0.294257,0.058098,0.522306,-0.327389,0.377865,-0.005760,0.081913,-0.086844,-0.237110,-0.453387,0.248165,-0.243924,0.125354,-0.116517,0.483379,-0.449347,-0.034534,0.655340,-0.871133,0.142686,-0.388178,0.365451,-0.309917,-0.400346,0.054959,0.474608,-0.194913,-0.198839,0.228750,0.112514,0.037018,0.137197,-0.210602,-0.504564,0.065501,-0.002094,0.130233,-0.185849,0.255889,0.233109,0.138074,0.191469,-0.166440,0.054238,0.642656,0.407999,0.295631,-0.247451,0.042913,-0.338623,-0.090092,0.528809,-0.302939,-0.305816,0.150707,0.121831,-0.513130,-0.622598,-0.399844,-0.446660,0.025225,0.140413,0.335558,-0.022335,0.662124,-0.915940,-0.200869,-0.432713,-0.133448,0.171743,-0.271980,-0.129814,-0.696703,-0.263016,-0.166144,-0.004524,0.270693,0.014609,-0.000511,0.690643,-0.658462,0.352854,0.330412,0.437255,-0.153945,0.628914,-0.125015,0.098884,-0.319097,0.143406,0.753121,-0.017169,0.354678,-0.078162,-0.055890,-0.010099,0.220836,-0.244903,0.435106', '26759819', '20326665', '30201138', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3324130', '娜娜的玫瑰战争', '语言:', '开朗泼辣的女孩丁娜（谢娜 饰）即将与相恋六年之久的业余画家男友李晨走入婚姻殿堂，谁知男友临阵逃脱，与在油画拍卖展上偶然邂逅的鉴赏家林晓毓（金伊彤 饰）坠入爱河。心怀怨气的丁娜对着5块钱买来的天珠发誓，一定要找比李晨好一百倍的男子。也许上天听到了她的心声，缘分真地从天而降。某天，开着宝马、帅气潇洒的有钱公子哥洛阳（李承铉 饰）来到丁娜面前，谁知他竟是林晓毓的前男友。让丁娜郁闷的是，高傲张扬的林晓毓经常挎着李晨在众人面前大秀恩爱，令娜娜抓狂不已。与此同时，洛阳却希望丁娜和李晨重归于好，以迎回前女友的心。一段奇妙的姻缘由此展开……©豆瓣', '谢娜', '戴小哲', 4.3, 9552, '', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p589175106.jpg', 33.1, 31.2, 27.8, 5.8, 2.2, '0.088353,-0.082741,-0.593820,0.434814,-0.169779,-0.324819,0.853343,0.034822,-0.521545,0.111827,0.364540,0.593617,-0.492595,0.573395,0.646038,0.091554,-0.176449,-0.541245,0.107228,-0.206260,0.203658,-0.268239,-0.264883,0.174532,-0.042660,-0.324259,0.416387,-0.027835,0.083766,0.725347,0.531721,0.044839,-0.187690,0.353759,-0.277343,-0.059180,-0.022581,0.520345,-0.287138,0.020424,-0.078403,-0.061180,0.013223,0.125946,-0.235688,-0.102426,0.463646,-0.173764,-0.153516,0.296894,0.712196,-0.123807,-0.078450,0.190298,-0.054095,0.174272,0.326032,-0.032589,-0.258337,-0.119046,0.372985,-0.199950,-0.336190,0.313857,-0.038579,-0.171848,-0.541577,0.427111,-0.131674,-0.104674,0.299136,-0.271995,0.022531,-0.009109,0.587634,0.484759,-0.193401,0.214871,-0.368081,0.229212,0.577201,0.422830,-0.091415,0.175723,-0.031234,-0.309116,-0.099252,0.104569,-0.544006,0.047014,0.378435,-0.066372,0.152422,0.008661,-0.433826,0.023633,-0.006410,0.303429,0.317559,-0.368161,-0.446688,-0.479940,-0.104285,-0.442008,-0.167646,0.102297,0.128391,-0.260165,0.602364,-0.630848,0.156400,0.418612,0.238802,-0.429484,0.636518,0.201806,-0.239963,-0.154448,-0.116397,0.381805,-0.185011,0.137809,-0.018443,0.312066,-0.225243,-0.174054,-0.429040,0.509589', '1296534', '1301686', '26687241', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3324399', '迷城', '剧情', '历史系大二学生赵坡（郭晓然  饰）是一个出身贫寒的男孩，他诚实善良、内向羞涩，周围的同学除了高干军队子弟就是来自富商海归的家庭，与他们比起来，赵坡俨然是一只寒酸可怜的丑小鸭。偶然的机会，他结识了发廊洗头妹甘秀（霍思燕 饰），这是一个出淤泥而不染的清纯女孩，为了养活智障的弟弟辛苦赚钱。某天，赵坡带着甘秀和同乡何昌兴（赵志刚 饰）、杜永庆（唐以诺 饰）外出游玩。但是却目睹两名同乡兽性大发，玷污了甘秀。在此之后，甘秀从赵坡的生活中彻底消失，他四处寻找，似乎进入了一个扑朔迷离的世界……本片荣获第13届上海国际电影节传媒大奖最佳导演奖和最佳新人奖。©豆瓣', '霍思燕', '章家瑞', 6.3, 9292, 'tt1805334', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p810726538.jpg', 4.5, 16.1, 45.8, 24.6, 9, '-0.033206,-0.138651,-0.382376,0.571332,-0.305478,-0.133346,0.636469,0.160974,-0.357527,-0.220519,-0.041264,0.850921,-0.082990,0.422143,0.441262,0.093031,-0.081853,-0.545027,-0.106000,-0.302528,0.148207,-0.230379,-0.334161,-0.037824,-0.147316,-0.299168,0.589304,0.083076,-0.211992,0.744526,0.465586,0.095465,-0.164388,0.165890,-0.377157,-0.074092,0.235065,0.263018,-0.220764,0.281551,-0.307402,-0.110337,-0.215898,-0.048926,0.200795,0.368096,0.690565,0.002930,-0.055890,-0.206137,0.499497,-0.169812,-0.407486,0.000233,0.371442,-0.168124,0.385121,-0.046651,0.044758,0.064333,0.160161,-0.325889,-0.595287,0.071008,0.490215,0.006289,-0.592668,0.584083,0.208117,-0.237550,-0.058337,-0.046824,0.254179,0.098282,0.185824,0.347239,-0.001724,0.378368,-0.278299,0.623170,0.473747,0.212563,-0.375645,0.368739,-0.354691,-0.630373,0.298591,-0.231847,-0.585008,0.059912,0.299015,-0.252027,0.049110,-0.030295,-0.434734,-0.049206,0.018654,0.099200,0.089609,-0.149907,-0.256858,-0.345921,0.011477,-0.337224,-0.259853,0.040911,-0.024302,-0.328160,0.922780,-0.831449,0.074828,0.436287,0.295357,-0.570179,0.660250,0.077737,0.182153,-0.247104,-0.356258,0.195070,0.043185,0.134146,-0.054996,0.306179,-0.554918,-0.358516,-0.038044,0.279949', '3445516', '25922902', '3811356', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3326710', '亚瑟', '喜剧', '豪富的巴克家族继承人——亚瑟（拉塞尔•布兰德 Russell Brand 饰）是纽约城里知名的彼得潘式的人物，他化装成蝙蝠侠横冲直撞之类的荒唐行为屡屡见报，令他执掌家族公司的母亲倍感压力。亚瑟如同无知孩童一般的行为屡屡需要老管家霍布森（海伦•米伦 Helen Mirren 饰）收拾残局，母亲无法忍受亚瑟为公司名誉抹黑的举止，以断绝其经济来源要挟亚瑟和自己得力的女助手苏珊成婚，苏珊颇有事业野心，一心要靠这场婚姻提升她建筑商家庭出身的地位。看见钱财份上向母亲低头的亚瑟在街上偶遇无证导游娜奥米（格蕾塔•葛韦格 Greta Gerwig 饰），后者的风采令亚瑟萌发了爱意，在结婚和爱情的分叉路口，亚瑟希望找到完美结局，而这可能是他有生以来面临的最强挑战。©豆瓣', '拉塞尔·布兰德', 'Jason Winer', 6.2, 6690, 'tt1334512', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p850524921.jpg', 3.3, 17.5, 50.7, 22.4, 6.1, '0.166444,0.153105,-0.505678,0.551976,-0.049977,-0.188813,0.443727,0.483250,-0.469348,-0.256557,0.335503,0.756732,0.125492,0.229037,0.299736,0.022943,-0.217628,-0.552729,0.053878,-0.088292,0.183161,-0.424654,-0.200331,-0.493787,-0.204983,-0.388381,0.578762,-0.115890,-0.300515,0.258413,0.501416,0.500927,0.081085,0.209389,-0.039738,-0.009105,0.095399,-0.041920,-0.593452,0.022353,0.023866,0.117039,-0.029475,0.294657,-0.049216,0.328040,0.385239,-0.120184,-0.000118,-0.355115,0.665995,-0.195341,0.220958,0.226054,0.285935,-0.105544,-0.002923,0.212556,0.031452,-0.181329,0.400322,0.028627,-0.799227,-0.168708,0.139303,0.146881,-0.628014,0.389609,-0.167911,-0.048175,0.289964,-0.180494,-0.114038,0.152925,0.167467,0.257356,-0.122638,0.142044,-0.457510,0.162434,0.578317,0.115683,-0.228467,0.145981,-0.447869,-0.273662,0.014105,-0.534708,-0.545381,-0.106079,0.236712,-0.052401,0.172457,0.368108,-0.261976,-0.290002,-0.346273,-0.133910,0.119409,-0.487985,0.061181,-0.591509,-0.109719,-0.451207,-0.338470,-0.135974,0.249395,-0.470213,0.569047,-0.670421,-0.145146,0.664684,0.390932,-0.555880,0.597833,0.055204,0.152442,-0.403133,-0.333649,0.337739,-0.093722,-0.087618,-0.088783,-0.075841,0.114466,0.121165,-0.052715,0.521909', '1793491', '4301278', '24875409', '27056396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3326730', '四十七浪人', '剧情', '古老的日本进入江户时代，德川幕府闭关锁国，维持着与世隔绝的和平和将军家的绝对统治。五代将军纲吉（田川洋行 饰）在吉良上野介（浅野忠信 饰）的陪同下造访浅野内匠头（田中泯 饰）所领导的播州赤穗藩。吉良阴险狭隘，野心勃勃，他利用妖女美月（菊地凛子 饰）迷惑浅野藩主，令其对吉良挥刀相向。震怒的将军责令浅野切腹，并严禁赤穗藩的家老大石内藏助（真田广之 饰）挟私报复。高傲的武士们一瞬间沦为浪人，而藩主自由收养的混血儿魁（基努·李维斯 Keanu Reeves 饰）更遭到不公的对待。经过一段时间的忍辱负重，大石将四十六位忠勇的赤穗藩武士集结麾下，暗中展开针对吉良的复仇。他辗转找到了魁，自幼爱慕藩主女儿美伽（柴崎幸 饰）的魁，为了防止心上人被吉良玷污，选择加入了复仇集团。四十七浪人的经典故事，以别样的形式呈现出来……©豆瓣', '基努·里维斯', '卡尔·瑞奇', 5.7, 16855, 'tt1335975', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2157974527.jpg', 6.3, 25.4, 49.7, 14.2, 4.3, '-0.034644,0.016160,-0.083820,0.285619,-0.020579,-0.013580,0.187264,0.299827,-0.308841,-0.466657,0.448162,0.524397,0.198118,0.143144,0.382606,0.049746,-0.029718,-0.586428,-0.209353,-0.104360,0.189934,-0.466813,0.039561,-0.272793,-0.264689,-0.295054,0.805181,0.178930,-0.064722,0.475020,0.369032,0.657159,-0.189541,0.091083,0.124858,0.034250,0.008106,-0.229503,-0.236421,0.088527,-0.553320,-0.353862,-0.069261,0.158478,-0.071173,0.374875,0.454520,-0.526524,0.101606,-0.506600,0.116657,-0.156931,-0.249267,0.365214,0.630277,0.131039,-0.166830,0.486759,-0.220985,0.008535,0.175033,0.070157,-0.469810,-0.151251,0.220233,0.039603,-0.323946,0.536270,-0.015573,-0.264356,0.267729,-0.104512,-0.086209,0.287379,0.354543,-0.039001,-0.370706,0.285360,-0.193834,0.140492,0.354677,-0.177703,0.008372,-0.314200,0.054704,-0.098348,0.083952,-0.452598,-0.261892,-0.393642,-0.022491,-0.123559,0.195041,0.299138,-0.513682,-0.403861,-0.326806,0.222131,0.407953,-0.153365,0.111567,-0.637466,0.082996,-0.328420,-0.123034,0.237466,0.386630,-0.082311,0.732977,-0.687061,-0.124772,0.448205,0.469491,-0.357380,0.115209,0.153394,-0.265724,-0.162402,-0.383130,0.302766,0.477559,0.264625,0.123961,0.204040,-0.325836,-0.117407,-0.212650,0.163922', '2369613', '3861846', '1826173', '26615753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3326747', '摇滚年代', '剧情', '梦想着成为歌星的女孩Sherrie Christian（朱莉安·浩夫 Julianne Hough 饰）来到了洛杉矶，不料走在街上钱却被小偷给偷了。萍水相逢的男孩Drew Boley（迪耶戈·博内塔 Diego Boneta 饰）向她伸出了援手，带她去他工作的酒吧当服务生。酒吧的老板Dennis Dupree（亚历克·鲍德温 Alec Baldwin 饰）和助手Lonny Barnett（拉塞尔·布兰德 Russell Brand 饰）正为酒吧的财政危机发愁，于是他们决定邀请摇滚歌星Stacee Jaxx（汤姆·克鲁斯 Tom Cruise 饰）来演出。Sherrie和Drew被彼此吸引，坠入爱河。在酒吧的一次演出中，因为某支乐队的偶然缺席，Drew和他的乐队Wolfgang Von Colt得以上台表演，赢得好评，逐渐成为知名乐队。由于Sherrie对Stacy的狂热崇拜，让Drew产生了误会，两人只能分手。而另一方面，洛杉矶市长的妻子（凯瑟琳·泽塔-琼斯 Catherine Zeta-Jones 饰）又到处宣传，认为摇滚乐魅惑人心，有伤风化，费尽心思想让Dennis的酒吧倒闭。摇滚乐在洛杉矶遭遇了危机......本片根据同名音乐剧改编。', '朱莉安·浩夫', '亚当·尚克曼', 5.7, 7534, 'tt1336608', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1587926161.jpg', 9.5, 25.3, 41.1, 17.1, 7, '0.374982,0.012333,-0.577002,0.317418,-0.074071,-0.370124,0.840135,0.426453,-0.421181,0.018644,0.204305,0.865775,-0.418208,0.208993,0.529677,-0.098777,-0.235397,-0.675482,0.004272,-0.041657,0.026636,-0.232299,-0.157667,-0.135286,-0.051977,-0.182631,0.365610,0.103178,-0.156099,0.694562,0.675741,0.367874,-0.099455,0.399125,-0.049558,0.023275,0.262183,-0.027945,-0.403569,0.418220,0.034585,-0.387509,-0.167061,0.090834,-0.090228,0.282299,0.729079,0.074972,0.075254,-0.033553,0.437215,-0.249604,0.104023,-0.010538,0.177808,0.182372,0.158050,0.024561,-0.295713,0.014263,-0.072061,-0.119764,-0.566640,0.357318,0.108491,0.162040,-0.669831,0.376029,-0.042302,-0.149742,0.288430,-0.116700,0.179322,0.032930,0.340820,0.295559,0.052866,0.102903,-0.524958,0.335526,0.634874,0.128740,0.076025,0.356399,-0.220641,-0.338694,0.026568,-0.104106,-0.532000,0.017978,0.419309,-0.241350,0.069856,-0.083663,-0.673459,-0.281322,-0.089691,-0.358738,0.085716,-0.519779,0.032312,-0.975656,-0.111065,-0.113647,0.000555,-0.080884,0.071058,0.033453,0.503493,-0.875870,0.238225,0.931073,0.297681,-0.341682,0.852113,0.08