INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3329192', '未来警察', '科幻', '公元2080年，由于太阳能天幕的应用，人类基本上摆脱了能源危机。由于新能源的广泛应用损害了众多传统能源商人的利益，他们想法设法要除掉发明太阳能天幕的马博士。时值马博士发明太阳能天幕十周年纪念，未来警察周志豪（刘德华 饰）与妻子美莉（范冰冰 饰）负责大会的安保工作，不料受命于能源商人的卡龙（樊少皇 饰）带领手下的改造人兵团中途闯入大会现场，企图杀死马博士。为了保护马博士，由周志豪带领的众多未来警察们与改造人兵团发生激战，在掩护马博士离开会场之时，周志豪妻子美莉不幸牺牲，卡龙一方也损失惨重。并未杀死马博士的能源商们事后窃取政府正在研发的时光旅行绝密资料，并且把卡龙和妻子斐娜改造成为终极杀人工具，他们要回到过去杀死年轻的马博士，以图改变未来。为了保护马博士，满怀丧妻之痛的周杰豪被改造成为超级战士，携女儿淇淇（徐娇 饰）回到2020年寻找并保护年仅12岁的马博士……', '刘德华', '王晶', 4.1, 50689, 'tt1337055', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p874978043.jpg', 33.6, 38.3, 22.2, 3.7, 2.3, '-0.321841,-0.145320,-0.364972,0.322771,-0.123219,-0.308719,0.162741,-0.115134,-0.224168,-0.953223,0.290591,0.319964,0.299711,-0.019887,0.455355,-0.402059,-0.378299,-0.299695,0.002772,0.072202,-0.334397,-0.307157,-0.077924,-0.410386,-0.017054,-0.345760,0.844229,0.055208,-0.174331,0.550647,0.022831,0.421512,-0.153526,0.133926,0.120790,-0.082434,0.287401,-0.317605,-0.634016,0.208217,-0.371565,-0.017651,0.210996,-0.253915,0.106824,-0.027662,0.766437,-0.411762,0.136101,-0.403145,0.146881,-0.546212,0.286721,-0.118218,0.442549,0.408076,-0.204054,0.150804,-0.255307,-0.087444,0.171771,-0.309747,-0.717216,-0.117698,0.266505,-0.184903,-0.505483,0.086007,-0.113225,0.291055,0.014140,-0.203144,0.341102,0.413393,0.249853,0.393351,0.013491,0.289129,-0.583827,0.265886,0.518990,-0.339843,0.050127,-0.112303,0.013497,-0.507046,0.066797,-0.208896,-0.235769,0.152321,0.320916,0.030936,0.111982,0.424783,-0.563244,-0.125017,-0.360067,-0.017461,0.328146,-0.139386,0.105216,-0.754770,0.284858,0.004271,0.108829,0.128564,0.027536,-0.216829,0.682705,-0.655279,0.088279,0.163843,0.473465,-0.782854,0.344303,-0.244390,0.451493,-0.446986,-0.098758,0.122339,0.267938,0.579861,-0.110226,0.069611,0.107907,-0.299441,-0.085225,0.075949', '2369613', '3861846', '1300371', '1305096');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3330040', '不敢说爱你', '剧情', '曾经修汽车的穷光蛋李黑子（林申 饰）因为钱的问题被前女友抛弃。这让他对爱情和金钱都有了全新的认识。靠经营服装店发家的黑子因为店里缺人，而雇了一个学市场营销的在校大学生蓝馨（童瑶 饰）。随着相处时间的增加，黑子封闭的内心渐渐为蓝馨这个善良美丽的女孩而打开。为了应付工商局的检查，黑子“利用”了下蓝馨，而后蓝馨也反过来“利用”了黑子。在这过程中，黑子了解到蓝馨对她生父的憎恨，还有学费的问题。黑子慷慨的帮蓝馨解决了学费。看着两人越来越好，爱着黑子的小崔（商忆沙 饰）因爱生恨，举报了黑子的违法行为。幸运的是，黑子没受多少牢狱之灾就被释放出去。而帮他出罚款的则是蓝馨。性格直爽的黑子对待感情却是鸵鸟态度，他能否说出心中的爱，和心爱的姑娘牵手呢？本数字电影改编自小说《打死我也不相信爱情》。©豆瓣', '林雨申', '方军亮', 7, 5193, '', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1365699417.jpg', 2.3, 7.3, 42.3, 34.7, 13.4, '0.219062,0.063875,-0.467164,0.530628,-0.379994,-0.446734,0.738851,0.090111,-0.163387,-0.171967,0.039605,0.256766,0.093819,0.126544,0.098914,-0.080028,-0.088522,-0.545441,-0.174983,-0.049051,-0.314101,-0.537250,-0.134701,-0.236085,-0.182660,-0.102987,0.509606,-0.018857,-0.217968,0.327865,0.438984,0.189698,0.334985,0.251540,-0.119761,0.145777,-0.238573,0.253035,-0.057514,0.127373,0.229326,-0.255464,0.002776,0.167994,0.108051,0.514997,0.609990,-0.055564,-0.260671,0.017134,0.341228,-0.356748,-0.058806,-0.132736,-0.051368,0.088463,0.234583,0.011189,-0.297126,-0.033972,0.176183,-0.013602,-0.739762,0.036901,0.043108,0.022544,-0.550863,0.524021,-0.200968,-0.145490,0.151229,-0.426399,0.097081,0.253263,0.396361,0.367554,-0.398789,0.059659,-0.299914,0.252469,0.602183,0.055484,-0.145671,0.474810,-0.501437,-0.341184,0.037816,-0.251800,-0.373128,0.047966,0.234484,0.065640,-0.176091,0.106433,-0.402125,0.008626,0.135566,-0.014834,0.121530,-0.696527,-0.096426,-0.274813,-0.277568,-0.570196,-0.388329,-0.027213,0.131808,-0.422521,0.934404,-0.746907,-0.099697,0.526000,0.454232,-0.654091,0.619493,0.182188,-0.180104,-0.068306,-0.078481,0.103074,0.040193,0.302061,0.132037,0.270212,0.128433,-0.153477,-0.388608,0.461045', '26283288', '1304034', '24284209', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3335464', '交响情人梦 最终乐章 后篇', '剧情', '为了更专注自己的音乐事业，千秋真一（玉木宏 饰）向野田惠（上野树里 饰）提出分居的请求，浪漫之都巴黎，这对情侣两地相隔。当然野田并不会感到特别无聊，奥山真澄（小出惠介 饰）和峰龙太郎（瑛太 饰）的造访为她带来诸多的乐趣。原来每三年一度针对小提琴和钢琴的坎托纳国际竞演会召开在即，峰特意来给分别多年的恋人三木清良（水川あさみ 饰）加油打气。观看演出时，当拉威尔的G大调钢琴协奏曲响起时，野田深受触动，遂决定报名参赛，却被教授拒绝。与此同时，当听说复归后的孙蕊（山田优 饰）邀请千秋共演时心情更是跌落谷底。为了帮她重整旗鼓，千秋带领野田展开连番特训……本片根据二之宫知子的原著漫画改编。©豆瓣', '上野樹里', '武内英樹', 8.8, 35928, 'tt1337673', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p559029535.jpg', 0.2, 0.9, 11.3, 34, 53.7, '0.172973,-0.041048,-0.519235,0.515059,0.273589,-0.427406,0.206793,0.315161,-0.265014,-0.562669,0.318611,0.507609,-0.331992,0.048170,0.509663,-0.051587,-0.328960,-0.746662,-0.022089,-0.036636,0.043008,-0.279624,0.214301,0.092198,-0.355634,-0.159648,0.636319,-0.157276,-0.186342,0.723065,0.281537,0.685492,-0.006516,0.107963,0.288047,-0.046078,0.141554,0.219866,-0.306928,0.129862,-0.179022,-0.394298,-0.101528,0.168342,0.070872,0.243140,0.561882,-0.046752,-0.092354,-0.205745,0.386394,-0.120575,-0.087086,-0.004519,0.300170,0.193450,0.180354,0.284890,-0.534441,0.141061,-0.063191,-0.093497,-0.620204,0.211719,0.114984,0.112577,-0.054007,0.316030,-0.045633,-0.153906,0.248492,-0.074166,-0.028037,0.421489,0.393109,0.153664,-0.456299,0.181673,0.128076,0.029685,0.635891,0.005997,0.318929,0.102741,0.026753,-0.302962,0.331138,-0.057421,-0.105309,0.090817,-0.068098,0.069515,0.274624,-0.007918,-0.612457,-0.288230,-0.212829,-0.267636,0.464375,-0.256426,-0.079398,-0.999682,0.190958,-0.265515,-0.118813,-0.079446,0.335492,-0.347135,0.755063,-0.879032,0.188374,0.363968,0.224271,-0.064007,0.316482,0.263660,-0.216009,-0.203234,-0.295621,-0.009481,-0.084132,0.225297,-0.029544,0.024182,0.128196,-0.414125,-0.591274,0.139454', '2369613', '25723905', '20274039', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33371681', '恋途未卜', '爱情', '根据同名少女漫画改编，描绘了4名高中生男女的青春爱情故事。山本朱里（滨边美波）是崇尚现实恋爱的女主角，山本理央（北村匠海）则是她没有血缘关系的弟弟。', '滨边美波', '三木孝浩', 6.8, 6976, 'tt10228546', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2610762490.jpg', 1.3, 9.9, 47.5, 29.9, 11.4, '0.290497,-0.148122,-0.002860,0.421898,-0.355653,-0.207516,0.838754,0.212996,-0.155678,-0.437035,0.486812,0.438218,0.202148,0.111406,0.086516,0.310958,-0.558799,-0.613412,-0.330965,0.048566,0.208244,-0.502739,0.051636,0.241492,-0.254212,-0.148622,1.186808,-0.470247,-0.656220,0.283331,0.350043,0.202852,-0.185766,-0.189628,-0.055830,0.449702,0.087647,0.175998,-0.228589,0.014457,-0.506656,-0.103670,-0.220068,0.090234,-0.417228,0.666585,0.724199,0.176184,0.108279,-0.018454,0.855806,0.127053,-0.415053,-0.034939,0.427756,-0.413662,0.212595,-0.042975,0.281440,-0.600707,0.001048,-0.256973,-0.504511,-0.383042,0.337550,0.701003,-0.138532,0.671551,-0.160733,-0.310229,0.753044,0.087905,-0.236488,-0.205131,0.925263,0.117661,0.269082,0.192454,0.112886,1.072402,0.439181,0.390723,-0.326728,0.651678,-0.941549,-0.735926,-0.826525,-0.375139,-0.532048,0.291066,0.083156,-0.150709,0.017458,0.406297,-0.305890,-0.221889,0.385548,0.184270,0.306689,-0.229627,-0.063190,-0.611380,-0.348098,-0.741653,-0.430807,-0.396158,0.335722,-0.455261,1.269733,-0.928068,-0.108100,0.738337,-0.035265,-0.076219,0.580826,0.630333,-0.664058,-0.648946,0.143220,0.472362,-0.027715,-0.143918,0.008083,0.394783,0.017737,0.000344,-0.435980,0.596301', '27602116', '1322847', '27167055', '1920765');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3337866', '死神剧场版：黑色褪去 呼唤君之名', '动画', '在实验室里工作的涅被像镰刀一样的东西袭击，身体产生了异变。涅突然像疯了似的，没有缘由地乱敲试验装置的操作盘。於是，一瞬间瀞灵廷被灵子云所覆盖，死神们都准备去联络涅。当剑八冲进涅的实验室时，发生了巨大的灵子爆炸。 然后，瀞灵廷被破坏了。露琪亚惊愕地在远处发现了瀞灵廷被破坏，在她面前出现了某个影子。那个影子向露琪亚斩下镰刀，露琪亚的身体（心）之中像是有什麼东西消失了……同时，现世中感觉到异变的一护去找浦原。一护从浦原那裏听到了「瀞灵廷被破坏」的消息，便和魂一同去尸魂界。在崩坏的净灵廷中等待著一护的，是消除了和一护相关记忆的恋次等人。不仅仅是一护的事情，连露琪亚的事情都消失了。在死神面前虚化的一护，被当成了破坏净灵廷的犯人追杀……。尸魂界里到底发生了什麼？谜之两个黑影的真实身份是？露琪亚去了哪里？一护孤独的战斗开始了……。©豆瓣', '森田成一', '阿部记之', 7.1, 5922, 'tt1339302', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196427398.jpg', 1.1, 5.9, 43.5, 35.1, 14.4, '0.482017,0.249314,-0.712309,0.113915,0.023082,-0.174384,0.874584,0.212373,-0.156112,-0.303983,0.158202,0.596081,-0.415118,0.229729,0.036726,0.234423,-0.265957,-1.120911,-0.500142,-0.184623,-0.636516,-0.115438,-0.111956,0.142867,-0.032611,-0.594448,0.333575,0.177131,-0.246282,0.203138,0.028674,0.563505,-0.299535,0.635505,-0.209971,0.284885,0.158871,-0.094106,0.325449,0.234104,0.020392,-0.482200,-0.185756,0.563912,-0.019374,0.384232,0.805053,-0.503962,-0.128038,-0.212762,0.226701,-0.194045,-0.066017,0.276692,0.574720,0.249570,-0.313641,0.098075,-0.332232,0.219922,0.270277,-0.027352,-0.758150,-0.166005,-0.209669,0.385305,-0.652371,0.404188,0.229536,0.019954,0.222116,-0.362697,0.616783,0.011724,0.097454,0.463377,-0.559106,-0.283692,-0.482126,-0.129000,0.834783,-0.180033,-0.348129,0.269037,-0.096848,-0.281957,-0.862769,0.276508,0.099350,-0.248312,0.543316,0.325859,-0.324950,0.421963,-0.529102,-0.123949,-0.307892,-0.174787,-0.594320,-0.273371,-0.455684,-0.485637,-0.081628,-0.307324,-0.508847,0.265296,-0.272390,-0.026541,0.375608,-0.812019,0.291072,0.788274,0.249896,-0.180425,0.405275,-0.303323,-0.188296,0.017646,0.185425,-0.091038,0.226764,0.690622,0.587469,0.452525,0.125510,0.053348,-0.599815,0.505882', '1477916', '3027015', '1