INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33379493', '清白', '剧情', '从小因父亲重男轻女，贞仁（申惠善 饰演）在中学时就逃家自力更生，与家人断了联系。贞仁后来凭一己之力成为顶级辩护律师，在一次偶然中，她得知罹患老年痴呆症的母亲花子（裴宗玉 饰演）涉嫌杀害父亲，同时还对不少无辜民众下毒手。 怀疑事有蹊翘的贞仁决定亲自出马，在层层阻挠下，她该如何为母亲翻供，揭开这个桩谋杀案背后不可告人的真相？', '申惠善', '朴相铉', 6.8, 10502, 'tt12515958', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2583398530.jpg', 0.7, 6.1, 53.4, 31.2, 8.6, '-0.022781,0.114396,-0.456065,0.398371,-0.068862,-0.045557,0.409956,0.007779,-0.600510,-0.584423,0.233890,0.643216,0.038631,0.165860,0.037891,-0.136884,-0.136733,-0.626281,0.336753,-0.152833,-0.302499,-0.697333,-0.336733,-0.031150,-0.050693,-0.280939,0.563835,0.153421,-0.401297,0.183371,0.490316,0.629727,-0.438588,0.149004,-0.100632,0.168328,-0.025141,0.145003,-0.402391,0.036051,0.074980,-0.208297,-0.064888,-0.024956,-0.343496,0.398754,0.322851,-0.050996,-0.265357,-0.483282,0.493043,-0.205264,0.045189,0.382367,0.450177,0.175125,0.259237,0.680717,-0.554881,0.054672,0.106097,0.108585,-0.815972,-0.460925,0.291895,-0.052678,-0.570752,-0.110649,-0.127214,-0.273970,0.280558,-0.274395,-0.055067,0.663100,0.116594,0.289174,-0.390062,0.098963,-0.314436,0.090184,0.936329,0.005299,0.392733,0.096432,0.223058,0.047399,0.180825,-0.355292,-0.380815,0.332208,-0.014688,-0.066511,-0.300079,0.516264,0.170302,-0.473796,-0.251045,0.405653,0.203570,-0.459594,0.022963,-0.021445,-0.254423,0.040604,-0.214042,-0.067880,0.144978,-0.583407,0.310394,-0.837713,0.418032,0.354909,0.234019,-0.750695,0.283249,0.457013,0.083053,-0.249563,-0.146703,-0.028685,0.100569,-0.006276,-0.135700,-0.262692,0.346102,-0.158770,-0.146362,-0.159348', '26678784', '30345227', '1877596', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33379643', '逃狱兄弟', '喜剧', '龙蛇混杂的监狱世界，一直由江湖巨头滚筒（谭耀文饰）和被判终身监禁的刀疤（张建声饰）两大势力平分天下，却因为冤狱新囚麦建天（栢天男饰）的出现，改变了风平浪静的监狱生活。 建天先被刀疤连番威迫放弃上诉，后被揭发与滚筒有着深仇大恨而惨被欺凌，建天为求保命只好接受同仓狱友浩正（张继聪饰）的建议，合谋策划了精密的越狱计划。 为了避开邓狱长（黄德斌饰）的严密监管，浩正设局游说滚筒协助，同时却被刀疤识破而被迫接受加盟。就此，狱中四人只好放下成见共同联手，上演一场惊心动魄的逃狱行动！', '谭耀文', '麦浩邦', 6.1, 7260, 'tt13375600', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2628012137.jpg', 3.6, 17.4, 54.2, 18, 6.7, '0.005588,-0.040113,-0.442720,0.352143,0.171029,-0.007358,0.432262,0.417957,-0.400108,-0.115180,0.355723,0.472705,-0.191012,0.011558,0.024423,-0.565370,-0.187825,-0.797660,-0.294497,-0.030748,-0.141879,-0.601103,0.078305,-0.109148,-0.072520,-0.182773,0.683170,0.289180,-0.196677,0.206387,0.500839,0.371191,-0.464409,0.360425,0.075996,-0.361361,0.066481,-0.129417,-0.665485,0.100401,0.039108,-0.326807,-0.042813,0.227845,-0.028639,0.307380,0.574481,-0.330781,-0.250544,-0.342629,0.209633,-0.549562,-0.347255,0.232894,0.436569,0.079241,-0.119958,0.787604,-0.258593,-0.133907,0.299061,0.068958,-0.828529,0.105849,0.403998,-0.170551,-0.329785,0.245924,-0.016791,0.215361,-0.240154,0.077032,0.107221,0.469892,0.679205,0.059980,-0.084384,0.328658,-0.416400,0.061623,0.650318,-0.257688,-0.150195,-0.244146,0.268229,-0.028857,0.110767,-0.527263,-0.263359,-0.181119,0.310297,-0.014611,-0.281517,0.191465,-0.364398,-0.291010,-0.645791,0.041091,0.026086,-0.501004,-0.062473,-0.538213,-0.285707,0.118877,-0.228474,0.320247,0.135696,-0.227589,0.299559,-0.499920,-0.015793,0.242922,0.426130,-0.834425,0.400729,0.185994,0.167636,0.055754,-0.180413,0.117744,0.357996,0.283651,0.246635,0.074648,-0.064446,-0.136071,-0.196063,-0.084004', '26678784', '1484760', '1297862', '1307106');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33381474', '倒忌时', '惊悚', '当一名护士下载一个声称可以预测一个人死亡时间的应用时，它告诉她，她仅剩三天的生命。 随着时间的流逝、未知的某人/物阴魂不散，她必须在时间耗尽之前找到一种方法来自救。', '伊丽莎白·莱尔', '贾斯汀·戴克', 6.1, 19661, 'tt10039344', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2570967090.jpg', 2.4, 17, 56.8, 18.4, 5.4, '-0.433871,0.404388,-0.193470,0.676265,-0.521672,-0.150574,0.763793,-0.305284,-0.521642,-0.724862,0.180900,0.126333,0.216110,-0.202159,0.282622,-0.343108,-0.444603,-0.695616,0.099944,-0.376942,-0.763011,0.091910,-0.030693,-0.221396,-0.191302,-0.584975,0.779153,0.311461,-0.093514,0.178648,-0.184279,0.176642,-0.091781,0.504683,-0.155810,-0.607582,0.287339,-0.236555,-0.077393,0.606839,0.626318,0.130292,0.013274,0.214999,-0.439893,0.252421,0.668914,-0.089194,-0.503190,-0.201463,0.708677,-0.183073,-0.042416,-0.307427,0.119478,-0.072997,0.236969,-0.092551,-0.536020,0.216843,0.110859,0.192473,-1.201596,-0.258503,-0.576231,0.093487,-0.205556,-0.189783,-0.091485,0.156765,-0.100504,-0.902990,-0.065881,0.386611,0.044465,0.228967,-0.719435,-0.501984,-0.590704,0.333386,0.841265,-0.608625,-0.582493,0.537267,-0.131238,-0.281563,-0.160831,0.074164,-0.512990,0.149416,0.286804,0.645126,-0.600859,0.129266,-0.362762,0.161933,-0.390041,-0.442563,0.019936,-0.549787,-0.440230,-0.434450,0.024298,0.242822,0.085118,0.250587,0.402086,-0.330968,1.046341,-0.302987,0.455264,0.931133,0.383065,-0.364380,0.819034,0.112564,0.030687,-0.887477,0.067437,0.521612,-0.000184,0.551294,0.137687,0.218170,0.307155,0.230446,-1.025846,0.767748', '30368448', '3785918', '30279170', '26315728');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33386178', '麦克白的悲剧', '剧情', '影片以华盛顿饰演的麦克白为主线，他被三个女巫说服，认为自己注定要成为苏格兰国王。他和野心勃勃的妻子麦克白夫人(麦克多蒙德饰)一起，开始把预言变成现实……结果是大量的鲜血、背叛和死亡。格里森饰演国王邓肯，米尔林饰演邓肯的儿子马尔科姆，霍金斯饰演麦克达夫。布鲁诺·德尔邦内尔([醉乡民谣])担任摄影师。', '丹泽尔·华盛顿', '乔尔·科恩', 7.2, 7654, 'tt10095582', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2722980045.jpg', 1.2, 5.5, 38.7, 42.3, 12.2, '0.092672,0.220528,-0.386545,0.618062,-0.030549,-0.246326,0.581675,0.442755,-0.271224,-0.462786,0.228748,1.014018,0.001607,-0.006811,0.470579,0.148385,-0.536772,-0.729652,-0.215939,0.303539,0.123460,-0.697605,-0.078770,-0.199523,-0.150041,-0.527615,0.574344,-0.398121,-0.006663,0.244777,0.653477,0.738467,0.236126,-0.231440,0.192422,0.312590,0.530481,-0.745687,-0.534889,0.530107,0.219086,0.262564,-0.174601,0.057988,-0.059422,0.261936,0.255307,-0.133155,0.499703,-0.344804,0.403765,-0.573087,0.206420,0.171354,0.234387,-0.200295,0.169797,0.326933,0.022753,-0.113381,0.206036,-0.117472,-0.866183,0.204611,0.060022,0.341335,-0.672120,-0.080290,-0.436117,-0.051657,0.216350,-0.341842,0.109283,0.053806,0.443998,0.025704,-0.087752,-0.065370,-0.499872,0.026208,0.797089,0.025264,-0.261810,-0.324568,-0.064937,-0.275023,0.036423,-0.395831,-0.584311,0.197456,0.327791,-0.272200,0.180088,0.481831,-0.383777,-0.463052,-0.597527,-0.234029,0.160864,-0.201686,0.172549,-0.716491,-0.326895,-0.055725,0.139954,-0.428673,-0.059526,-0.457364,0.475801,-0.498631,0.433681,0.315439,0.188314,-0.261893,0.535083,0.466747,0.223326,-0.547562,0.322721,0.513928,0.387093,-0.351088,0.152934,0.190175,0.182870,0.070113,-0.312489,0.660259', '34890458', '30216729', '25731059', '1482099');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3338851', '锅匠，裁缝，士兵，间谍', '剧情', '冷战时，全球两大特工组织——俄罗斯“中心”与英国“圆场”明争暗斗。特工遇害，高层震怒，责成“圆场”挖出“地鼠”。怀疑对象共有5人，即圆场上任“老总”命名的锅匠，裁缝，士兵，穷人，乞丐。其中，金盆洗手的“乞丐”乔治·史迈利(加里·奥德曼 Gary Oldman 饰)本来有重大嫌疑。某日，行动组-剥头皮组头目的彼得·吉勒姆(本尼迪克特·康伯巴奇 Benedict Cumberbatch 饰)与英国内阁办公室谍报总监拉康排除了史迈利的嫌疑，令其重新出山，负责挖出“地鼠”。于是，史迈利开始分别走访故人，调查“圆场”老大阿勒莱恩，裁缝-比尔·海顿(科林·费斯 Colin Firth 饰)，士兵-掌管东欧事务的资深间谍罗埃·布兰德，穷人-后勤部门点路灯组组长托比·伊斯特哈斯。一时间，圆场疑云密布，人人自危，究竟谁才是“地鼠”……本片本片根据约翰·勒卡雷的同名小说改编。片名来自英国民间的“鹅妈妈童谣集”。', '加里·奥德曼', '托马斯·阿尔弗莱德森', 7.9, 106788, 'tt1340800', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1202175107.jpg', 0.7, 2.9, 23, 48.5, 24.9, '0.097532,-0.450453,-0.110347,0.022721,0.216397,-0.152631,-0.133192,0.263197,-0.663595,-0.351962,0.186771,0.370007,-0.164741,-0.345459,0.396327,0.028463,-0.558728,-0.363052,-0.194380,-0.156553,0.192852,-0.622187,-0.351792,-0.650568,-0.022579,-0.085846,0.085184,-0.110795,-0.030223,0.278666,0.181061,0.727510,-0.294659,-0.099312,0.561757,-0.061939,0.579434,-0.411385,-0.372945,-0.255902,-0.332026,0.038309,-0.186486,-0.135504,0.413587,0.413850,0.119586,-0.194086,0.535321,-0.334328,0.164840,-0.235939,0.019090,-0.340199,0.465901,0.152007,0.399224,0.098433,0.362315,-0.185990,-0.098307,-0.198483,-0.143137,-0.093571,0.216109,0.339240,-0.068544,-0.075763,-0.453053,0.200864,-0.082954,-0.001598,0.179392,0.081934,0.213180,0.041597,0.436406,0.180415,-0.082867,0.272216,0.100413,0.137590,0.073426,-0.523311,-0.065465,-0.355273,0.114732,0.050483,-0.049206,-0.051398,0.283331,-0.333202,0.312658,0.247362,-0.608411,-0.297869,-0.510971,-0.002253,-0.002504,0.020463,0.068116,-0.650832,-0.123155,0.232128,0.150508,-0.215995,0.317839,0.277818,0.330316,-0.403221,-0.003645,0.439888,-0.127006,-0.252452,0.091460,-0.120300,0.452443,-0.561394,-0.035155,0.131931,0.349981,0.303152,-0.055112,0.015115,-0.080793,-0.387552,0.0