INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3338862', '终结者：创世纪', '动作', '天网拥有独立意识后，对创造它的人类展开血腥屠杀。此后的岁月，约翰·康纳（杰森·克拉科 Jason Clarke 饰）率领战友和天网的机器人大军进行着旷日持久的战争。在关键的一次战役过后，天网将终结者派往1984年的洛杉矶，企图杀害约翰的妈妈莎拉（艾米莉亚·克拉克 Emilia Clarke 饰）。而约翰则将自己最亲密的战友——同时也是他的生身父亲凯尔·里斯（杰·科特尼 Jai Courtney 饰）派往过去。凯尔刚刚抵达洛杉矶便遭到液态金属终结者T-1000（李秉宪 饰）的袭击。与此同时，“老爹”（阿诺·施瓦辛格 Arnold Schwarzenegger 饰）则与莎拉联手干掉了终结者T-800（阿诺·施瓦辛格 Arnold Schwarzenegger 饰）。似乎过去的事情悄然改变，凯尔则从时间旅行中的遭遇得到灵感，与莎拉穿越来至2017年，尝试阻止天网的诞生……', '阿诺·施瓦辛格', '阿兰·泰勒', 6.9, 144721, 'tt1340138', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2262649521.jpg', 1.1, 7, 46.9, 33.8, 11.2, '0.067532,-0.040211,-0.666677,0.550006,0.241576,-0.417142,0.855210,-0.191065,-0.205050,-0.316286,0.453425,0.444213,-0.100555,-0.151711,0.557504,-0.019401,-0.549542,-0.710409,-0.114578,-0.037421,-0.442373,-0.400043,-0.394832,-0.110611,0.227910,-0.547013,0.616427,-0.180041,-0.098038,0.633571,0.017727,0.476775,-0.106669,0.409544,0.276724,0.158452,0.170416,-0.218176,-0.475840,0.293561,0.024572,-0.024415,-0.025714,0.113336,-0.029935,0.268162,0.854597,-0.666350,0.424446,-0.256431,0.163481,-0.267453,0.134738,0.012659,0.363763,0.222558,-0.032238,0.258263,-0.062293,0.161619,0.100834,-0.012263,-0.798437,0.003952,-0.161901,0.058985,-0.347951,0.226163,-0.310701,0.120417,0.289380,-0.444751,0.015059,0.668353,0.313339,0.230095,-0.277677,0.089403,-0.406346,0.000512,0.573525,-0.180284,-0.128876,0.042099,-0.088150,-0.487736,-0.312187,-0.226707,-0.246948,-0.047324,0.310402,0.079467,0.122446,0.784666,-0.866685,-0.273168,-0.558192,-0.229650,0.172965,-0.110047,-0.138123,-0.837119,-0.118310,-0.146259,-0.278875,0.026526,-0.105489,-0.102242,0.524327,-0.584829,0.336884,0.615758,0.481587,-0.042567,0.460104,-0.092699,0.233808,-0.398200,-0.000340,0.587735,0.191647,0.411127,0.289896,0.234308,0.106420,-0.173690,-0.217771,0.474829', '25774050', '27133569', '1316693', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3338879', '更好的世界', '剧情', '瑞典医生安东（米克尔·佩斯勃兰特 Mikael Persbrandt 饰）常年工作在苏丹的难民营，每天直面武装暴力造成的伤痛与死亡；休假时则飞返丹麦，与分居中的妻子玛丽安（崔娜·蒂虹 Trine Dyrholm 饰）轮流照看两个儿子。男孩克里斯蒂安（威廉·约翰·奈尔森 William Jøhnk Nielsen 饰）从伦敦迁至丹麦，母亲的病逝令他与父亲心生隔阂。在新学校中他与安东的长子伊莱亚斯（马库斯·瑞格德 Markus Rygaard 饰）结识，后者因瑞典人的身份受到同学的歧视与欺凌。克里斯蒂安教会伊莱亚斯以暴制暴，两个同样来自破碎家庭的男孩成为好友。安东带着两个儿子和克里斯蒂安外出游玩，因误会被人连续掌掴羞辱。安东坚持以宽容忍让的态度化解此事，却不被孩子们理解。在发现库房里的火药后，克里斯蒂安开始怂恿伊莱亚斯加入自己危险的复仇计划。而此时已经回到苏丹的安东因为救治了恶贯满盈的当地大佬，内心正经历着一场道德的煎熬……影片原名《复仇（The Revenge）》，后更名《更好的世界（In a Better World）》，于2011年相继摘得第68届金球奖最佳外语片奖和第83届奥斯卡金像奖最佳外语片奖两项殊荣。', '米卡埃尔·佩斯布兰特', '苏珊娜·比尔', 8.3, 26552, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p789131855.jpg', 0.2, 0.9, 14, 52.2, 32.7, '-0.022231,-0.126044,-0.662596,0.533086,0.052110,-0.312876,0.619915,0.267235,-0.590318,-0.207918,0.214233,0.796199,-0.067697,0.219510,0.471758,-0.002650,-0.386353,-0.677844,-0.045699,-0.032078,-0.105292,-0.480057,-0.240658,-0.135140,-0.231510,-0.544047,0.505963,-0.265003,0.006630,0.591658,0.343562,0.525143,-0.027669,0.257181,0.101182,0.031478,0.305553,-0.064202,-0.639625,0.363697,0.042306,-0.061130,-0.335981,0.002276,0.060100,0.398869,0.657516,-0.243909,0.101311,-0.381857,0.272277,-0.240148,-0.174257,0.261280,0.192744,-0.034349,0.251381,0.453543,-0.079548,0.166074,0.125014,-0.041107,-0.474720,0.091790,0.221943,0.126073,-0.629759,0.565811,-0.334654,-0.076931,0.085264,-0.203568,0.090539,0.395839,0.078991,0.401765,-0.427647,0.017056,-0.277162,-0.056439,0.563540,-0.225674,-0.330443,-0.120488,-0.255323,-0.288796,0.268325,-0.209951,-0.499198,-0.021629,0.210910,0.044938,0.027411,0.503141,-0.491893,-0.110474,-0.416017,-0.241276,0.121881,-0.255098,0.015379,-0.698328,-0.037080,-0.208160,-0.432386,-0.184633,0.212098,-0.153583,0.584431,-0.671260,0.455655,0.294307,0.353380,-0.363368,0.375395,0.399581,0.4