INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33391824', '水怪', '奇幻', '男主水生胆小懦弱，小时候和父亲一起捕鱼时，亲眼目睹父亲被怪物“水猴子”杀害，水生从此留下了心理阴影。十年后，怪物“水猴子”再次出现，杀害了水生爱慕的的香兰弟弟和父亲。为救香兰不被当“水猴子”的“祭品”，水生开始学习捕鱼和水上技能，并集结村民的力量，一起踏上讨伐“水猴子” 之路，一场大战即将在河边一触即发......', '刘林城', '项秋良', 4.3, 4952, 'tt15048108', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2562804412.jpg', 23.1, 47.9, 23.6, 3.3, 2.1, '0.316833,-0.275804,-0.485017,0.307174,-0.091292,-0.586563,0.663114,0.079693,-0.422096,-0.062982,0.228994,0.747404,-0.004262,0.134995,-0.153871,-0.250990,-0.116267,-0.631096,-0.264096,0.352426,-0.360389,0.024208,-0.069130,0.138543,0.000003,-0.501052,0.489720,0.024249,0.215759,0.631300,-0.100694,-0.018043,-0.526570,0.289748,0.117861,0.202315,-0.040291,0.009596,-0.372481,0.109087,-0.305614,-0.064717,0.018674,-0.077872,-0.011768,0.116622,1.039455,-0.357215,-0.032363,-0.852267,0.157324,-0.385361,0.240584,0.051892,0.496396,-0.102110,0.299056,0.095682,0.250118,-0.036814,-0.072098,-0.137114,-0.332099,0.091067,-0.188960,0.006952,-0.616534,0.317416,0.400315,0.248767,0.372423,-0.222171,-0.092974,-0.031904,0.169278,0.451969,-0.438610,-0.238018,-0.372699,0.085217,0.907714,-0.354497,0.424162,0.454259,0.135296,-0.150130,0.420232,-0.236977,-0.201452,0.230157,0.402704,0.245357,-0.951566,0.613167,-0.982323,0.043837,-0.241197,0.278175,0.156771,-0.023159,-0.380304,-0.228903,-0.072881,-0.181768,-0.082874,0.049571,0.112562,-0.204626,0.676240,-0.690737,0.197665,0.507238,0.306612,-0.492465,0.435711,-0.068611,-0.122139,-0.089910,0.581623,-0.110438,0.155653,0.531601,0.494631,0.221680,-0.221074,0.223187,-0.311085,0.398515', '1458910', '26603666', '5364978', '26280899');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33392524', '鬼吹灯之龙岭迷窟', '动作', '影片讲述了自精绝古城回来后，Shirley杨带陈教授回美国治疗，却发现背上长出眼球状的红斑。胡八一与王胖子、大金牙前往陕西古蓝县进货遇到Shirley杨。四人进到一座幽灵冢险些葬于人面蜘蛛的果腹，出来后，胡八一和王胖子也长出红斑。Shirley杨拿着外公鹧鸪哨的笔记，发现黑水城的通天大佛寺中，很有可能藏有解开红斑诅咒的关键——雮尘珠。三人沿黄河继续进发，按照笔记指引进到寺内，在对抗黑玉邪神之时，发现一藏宝箱，里面究竟藏着雮尘珠，还是暗藏凶险？摸金小队又能否成功揭开鬼眼红斑的诅咒谜团呢？', '林雨申', '朴成淑', 2.9, 10333, 'tt12867590', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2594050148.jpg', 69.1, 21.7, 6, 1.9, 1.4, '-0.042270,0.017797,-0.477154,0.292834,0.354463,-0.230558,0.607311,-0.160676,-0.157331,-0.255067,0.215394,-0.048134,-0.217753,0.083594,-0.144116,-0.017828,-0.173035,-0.101421,-0.097461,-0.402946,-0.595606,-0.157333,-0.653486,-0.048623,0.131427,-0.177941,0.308376,0.300894,-0.262887,0.285837,0.186689,0.255260,-0.510123,0.173921,-0.220206,0.110875,-0.403637,0.177032,-0.117038,0.138254,0.213881,-0.243228,-0.179266,-0.129786,-0.020920,0.350218,0.590840,-0.333353,0.012001,0.136673,0.075436,-0.083661,-0.233059,-0.172989,0.487117,0.095149,-0.019984,-0.040828,-0.175384,0.168830,-0.010725,0.124419,-0.116870,-0.135202,0.201681,0.500576,-0.228475,-0.015157,0.211385,0.207024,0.053904,-0.992884,0.336007,0.101351,0.271702,0.236374,0.044407,0.061415,-0.554460,-0.149079,0.194593,-0.370507,0.314913,-0.191874,0.366077,-0.696603,0.101848,0.235581,0.239381,0.248873,0.589814,0.250709,0.020650,-0.074532,-0.555227,-0.175634,-0.123226,-0.023110,0.239841,0.139270,-0.072418,-0.636168,-0.037890,0.048672,-0.034556,0.117244,0.013537,-0.269861,0.252862,-0.383113,0.337231,0.124805,0.108239,-0.053182,0.293228,-0.298792,0.221012,-0.120928,-0.107343,0.147173,0.311130,0.640098,0.129608,0.357504,-0.201883,-0.407487,-0.446216,0.102598', '34970316', '5247058', '35206186', '1297611');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33393167', '鬼灭之刃 兄妹的羁绊', '动作', '舞台是大正日本。卖木炭的心地善良的少年炭治郎的日常生活因家人被魔鬼杀害而彻底改变。为了帮助唯一幸存下来的却变成凶恶鬼的妹妹隅豆子恢复如初，炭治郎踏上了为讨伐杀害家人的鬼的旅途……', '大塚芳忠', '外崎春雄', 9.1, 21047, 'tt14888860', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2619534841.jpg', 1.1, 0.6, 5.9, 26, 66.4, '0.038076,-0.042310,-0.063831,0.431167,-0.686746,-0.406519,0.998350,0.307853,-0.222883,-0.261731,0.467826,0.561347,0.111207,-0.086998,0.114668,0.053961,0.133332,-0.265183,-0.421649,0.090545,-0.139984,-0.181235,-0.227749,0.017824,-0.027484,-0.600951,1.027522,0.358456,0.019453,0.476237,0.169416,0.470247,0.085084,-0.002750,-0.365268,0.110257,-0.643482,-0.151869,-0.307468,0.194934,-0.578885,-0.126159,0.003239,0.344171,-0.526311,0.498137,0.993898,-0.237290,-0.236391,-0.546307,0.359868,-0.478889,-0.078626,0.089839,0.427330,-0.092759,0.110927,0.302616,-0.211938,-0.170023,0.307245,0.195413,-0.892690,0.150098,0.420261,0.272318,-0.670854,0.527297,0.055653,0.131125,0.160199,-0.316319,0.464357,0.506164,0.210241,0.661533,-0.224073,0.152188,-0.861317,0.218993,0.811924,-0.188775,-0.021876,0.241454,-0.224475,-0.211160,0.701103,-0.692456,-0.167204,0.031440,0.052527,-0.205023,-0.554239,0.379949,-0.639156,-0.292391,-0.512773,-0.246324,0.303694,-0.669255,-0.350717,-0.351189,-0.049222,-0.210938,0.100179,-0.140809,0.045290,-0.438861,0.906601,-0.744943,0.416628,0.480056,0.071509,-0.619448,0.380286,0.036354,-0.010192,-0.188745,-0.150455,0.217655,0.500875,0.521077,-0.024099,-0.199307,-0.349651,-0.049625,-0.569501,0.315637', '21619567', '26667010', '26759820', '25890078');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33400376', '平原上的夏洛克', '剧情', '超英翻盖新房 ，占义、树河前来帮忙，没想到树河却因意外车祸入院，司机肇事逃逸，超英和占义化身“平原侦探”，踏上了一段令人啼笑皆非的荒诞追凶之旅。', '徐朝英', '徐磊', 7.8, 146189, 'tt10488396', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2574198225.jpg', 0.3, 2, 24.3, 55.1, 18.3, '-0.095532,-0.109820,-0.501334,0.090679,0.462472,-0.362560,0.532618,-0.177941,-0.336955,-0.296677,0.443610,0.656114,-0.302464,-0.491981,0.603692,-0.347952,-0.324319,-0.046631,0.308265,0.109998,0.093043,-0.248790,-0.108135,-0.042507,0.178565,0.201648,0.265839,0.251331,-0.140885,1.345918,0.051713,0.510366,-0.621207,0.565767,-0.167444,0.474523,0.095836,0.259311,-0.282310,-0.270689,0.098444,-0.231274,-0.218306,0.011974,-0.301078,0.569896,0.548896,0.095425,-0.659637,-0.224342,0.360247,-0.136665,-0.087505,-0.247006,0.233080,0.488856,0.181369,0.054700,-0.306604,-0.238128,0.147994,0.188322,-0.468529,0.290812,0.034752,-0.120637,-0.369095,-0.174380,-0.298838,-0.250285,0.138268,-0.478161,0.141467,0.241784,0.660818,0.313526,0.407947,0.235497,0.021656,0.291889,0.598540,0.023339,0.033700,0.737983,0.285232,-0.186432,-0.019785,0.125962,-0.094424,0.435853,-0.018647,-0.361641,-0.133585,-0.053686,-0.091801,-0.189350,-1.007061,-0.118325,-0.526743,0.196733,-0.590168,0.014518,0.469113,0.807167,-0.099040,-0.182542,0.136561,-0.208179,-0.183567,-0.232174,0.167854,0.340732,0.089274,-0.088521,0.198018,0.240859,-0.268736,-0.695229,-0.204157,0.118880,-0.061639,0.912647,-0.100047,-0.020682,0.028642,-0.309491,-0.191937,-0.050253', '35256235', '1451563', '4896894', '34966198');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33400537', '我是大哥大 电影版', '喜剧', '三桥贵志以转校为契机，决定在新学校“嚣张”一把，从此做个不良少年。为了能在同学中获得存在感，他还特地去发廊弄了一头金色卷发。而和他转到同一所学校的伊藤也有同样的想法。在开学第一天，伊藤和三桥就发现了彼此的秘密，也因此结成盟友。三桥的信条是“无论用多么卑鄙的手段，只要能赢就行”，所以，在和别人打架的时候只要能玩阴的就绝对不正面对抗，但他真正的实力也不容小觑。伊藤为人处世相对正经，有时候甚至会慢半拍，也因此常常被三桥利用且被蒙在鼓里，而在打架方面，他战斗力超群，有着不服输的信念。两个人一起挑战校内校外的不良少年，引发了一连串爆笑事件。', '贺来贤人', '福田雄一', 7.9, 49208, 'tt11427318', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2595471914.jpg', 0.7, 2.7, 24.4, 44.9, 27.3, '0.378309,-0.156095,-0.514569,0.666674,-0.464962,-0.150634,0.264247,0.163907,-0.528431,-0.107355,0.152388,0.755684,-0.000915,0.093338,0.123794,-0.383925,0.012581,-0.730263,0.170861,-0.274103,-0.262919,-0.584773,-0.243688,-0.195680,-0.021768,-0.318972,0.635276,0.051853,-0.539561,0.203198,0.323786,0.187675,-0.061510,0.616348,-0.152873,-0.456168,-0.182801,0.245272,0.009380,0.349922,0.166669,-0.233401,-0.036336,0.319548,0.005041,0.357589,0.504279,-0.195181,-0.250004,0.013503,0.224096,-0.236480,-0.127565,0.337901,0.398454,-0.391007,0.478260,0.397091,0.028216,0.065590,0.147923,0.014817,-0.861404,-0.018428,-0.022301,-0.060366,-0.598149,0.503062,0.196789,-0.395985,0.259857,-0.143722,0.118332,0.562169,0.506968,0.192261,-0.413364,-0.189096,-0.527356,-0.057329,0.696419,-0.069919,-0.175434,0.337361,-0.106533,-0.384288,-0.281621,-0.574708,-0.301450,-0.107017,0.164996,0.144491,-0.333698,-0.066994,-0.440741,-0.006087,0.117176,0.155948,0.073203,-0.674762,0.242116,-0.375283,-0.153666,-0.482864,-0.408329,0.265714,0.321227,-0.405102,0.774553,-1.164904,-0.094716,0.657265,0.438842,-0.512158,0.750624,0.281714,-0.193086,-0.117578,-0.157550,-0.155584,0.204819,0.429650,0.104485,0.577862,0.076346,-0.287616,0.019804,0.611538', '1877596', '35030151', '30345227', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33401841', '就爱断舍离', '剧情', '从瑞典回来后，喜爱“极简主义”的简计划将自己的家改造成工作室，多年前的旧物相继被清理了出来，其中包括前男友艾姆的东西。这些物件虽然已经没有用处，却承载着往事回忆与情意，简无法如自己预期的那样直接丢弃。为了找寻这些物件的归路，她做了很多努力：一一归还属于朋友的物品，亲自送回属于艾姆的东西并致歉自己曾经的离开，最终也卖掉了已逝父亲的钢琴。伴随着旧物的处理，她也告别了自己的过去，面对重新布置的新环境，准备好了新的开始。该片曾获2020年第15届大阪亚洲电影节最佳影片奖。', '茱蒂蒙·琼查容苏因', '纳瓦彭·坦荣瓜塔纳利', 6.8, 11957, 'tt11316824', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2654762253.jpg', 0.7, 8.5, 47.3, 36.3, 7.2, '0.286686,0.245579,-0.748215,0.580625,-0.266387,-0.536963,0.746577,-0.052028,-0.504898,-0.576031,-0.180491,0.701335,0.200549,0.263645,0.074531,0.095971,-0.460231,-0.805635,-0.227367,-0.441025,-0.505641,-0.362283,-0.327279,-0.071786,-0.182912,-0.211960,0.372904,0.092810,0.011748,0.252456,0.313882,0.151350,-0.007606,0.420993,-0.298093,0.095723,-0.220237,0.308839,-0.661449,0.129490,0.015440,-0.419507,-0.190004,0.225270,0.187341,0.348011,0.832842,-0.251531,-0.038185,-0.063104,0.359871,-0.017809,0.095759,0.107383,0.213085,0.433374,0.085260,0.260421,-0.460105,0.166795,0.039731,-0.308573,-0.947959,-0.320689,0.235306,-0.001145,-0.828770,0.570120,-0.067054,0.493769,-0.157381,-0.447879,0.444701,0.178192,0.163280,0.326042,-0.065741,0.050541,-0.519976,0.522264,0.538340,-0.120503,0.006349,0.354450,-0.168022,-0.348544,-0.008192,-0.228418,-0.328700,0.112433,0.414435,0.533222,-0.128006,0.170029,-0.673373,-0.231722,-0.239806,-0.520120,0.354694,-0.438219,0.144157,-0.489067,-0.022739,-0.327419,-0.308728,-0.024892,0.116769,-0.203806,0.816606,-0.612930,0.269579,0.461089,0.119512,-0.796981,0.368645,-0.061933,0.278475,-0.028778,0.088028,0.167984,-0.041398,0.579204,0.273794,0.379959,0.157517,-0.320439,-0.671343,0.622221', '25928048', '26678784', '30163500', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33404512', '东京贵族女子', '剧情', '改编自山内麻里子的同名小说，聚焦同样在都市生活境遇却截然不同的两个女子——门胁麦扮演生于大城市、被呵护长大的大小姐榛原华子，正全身心投入相亲；水原希子扮演从小地方来东京打拼，自己拼出一条活路的时冈美纪。', '门胁麦', '岨手由贵子', 7.7, 14527, 'tt12440140', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2627312853.jpg', 0.3, 2.2, 29.3, 50, 18.2, '0.051972,-0.147272,-0.353773,0.432231,0.038199,-0.265477,0.508186,0.287115,-0.169151,-0.004423,0.487783,0.828212,0.004896,0.228588,-0.031404,-0.030033,-0.058468,-0.630931,-0.118577,0.165604,-0.036953,-0.028780,-0.210202,0.246264,-0.002596,-0.098479,0.676201,-0.270881,-0.265345,0.143479,0.460616,0.139801,-0.501085,0.208025,-0.192483,0.131051,0.092465,0.142326,-0.008300,0.039770,-0.444695,0.058562,-0.353129,-0.262143,0.094026,0.477584,0.771106,0.096549,-0.078970,-0.379016,0.497847,0.236442,-0.276030,-0.017597,0.096185,-0.113371,0.278463,-0.067964,-0.111441,0.033395,0.080909,-0.346702,-0.510187,-0.325647,0.545498,0.369998,-0.555873,0.326389,0.631688,-0.561297,-0.101928,-0.489064,-0.136378,0.020989,0.089994,0.292133,-0.175555,0.379286,-0.153887,0.304933,0.664243,-0.324151,-0.025350,0.545758,-0.159136,-0.270329,-0.005591,-0.175393,-0.816088,-0.152615,-0.125882,-0.428526,-0.331992,0.329883,-0.363702,0.321076,-0.177902,-0.132436,0.111760,-0.529572,-0.054612,-0.496784,-0.079539,-0.318369,-0.014315,0.292550,0.393173,-0.346346,0.769735,-0.316136,-0.243073,0.713842,-0.118116,-0.575690,0.497444,0.213973,-0.160190,-0.451296,-0.131236,0.680974,0.176365,0.246661,0.033632,0.154115,-0.702280,0.323750,-0.779201,0.584942', '3811356', '1908036', '3732800', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33404726', '小委托人', '剧情', '律师正烨（李东辉饰）一心只想着功成名就，对身边人和事不闻不问的他，却被多彬（崔明彬饰）和敏俊（李周元饰）小姐弟所牵绊。就在收到盼望已久的著名律师事务所录取通知的那一刻，10岁的多彬向正烨自白称杀害了自己7岁的弟弟，而这一切又与多彬的母亲智淑（柳善饰）有关。感到后悔和抱歉正烨，决定揭开多彬母亲隐藏的秘密……', '李东辉', '张圭声', 8.1, 57508, 'tt10308634', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561250762.jpg', 0.3, 1.7, 19.6, 49.7, 28.6, '0.269439,-0.147246,-0.576310,0.426848,-0.026249,-0.632195,0.603296,0.134645,-0.471761,-0.399403,-0.021188,0.735959,-0.098183,0.466899,0.463216,0.328484,-0.318886,-1.038473,-0.071231,-0.382298,0.132533,-0.498269,0.194133,-0.107919,0.230241,-0.436570,0.429317,0.036810,-0.033270,0.575929,0.393554,0.402074,-0.243761,0.489855,-0.205491,0.126620,-0.060625,0.076780,-0.424639,-0.149258,0.439437,-0.218890,0.137585,0.336682,-0.112946,0.463033,0.403611,-0.263634,-0.508935,0.030733,0.482155,-0.587168,0.115522,0.354593,0.280913,0.027403,-0.017347,0.444620,-0.394223,-0.241864,-0.052844,0.119895,-0.835110,-0.035364,0.205061,0.252589,-0.532089,0.337897,-0.436723,0.207171,0.077987,-0.360853,0.302205,0.404326,-0.326028,0.433762,-0.351228,-0.002067,-0.172256,0.148647,0.576365,-0.156365,-0.073142,0.164820,0.083336,-0.070824,0.075001,-0.147460,-0.667482,0.136064,0.003896,0.114212,-0.063409,0.025499,-0.288822,-0.362223,-0.280107,-0.110175,0.345580,-0.678997,-0.024029,0.072710,-0.177476,-0.274831,-0.613765,0.057429,0.217999,-0.395312,0.693188,-0.804503,0.179660,0.276156,0.596250,-0.598336,0.903354,-0.052609,-0.084022,-0.321457,0.163008,-0.043230,-0.084330,0.261849,0.015377,0.166443,0.163698,-0.333121,-0.531232,0.003516', '4301278', '26021055', '1418613', '1299195');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33407124', '浪客剑心 最终章 追忆篇', '剧情', '幕府时代末期，外忧内患，山河动荡，百姓生活困苦，且生命时刻受到威胁。少年心太因其善良纯洁之心感动飞天御剑流高手比古清十郎，被其收入门下学习剑法，更名剑心。在国家危难之际，年轻的剑心怀揣改变时代的梦想下山，加入奇兵队，日后更被桂小五郎纳入麾下，以刽子手的身份为时代的变革尽一份绵薄之力。年仅15岁的剑心接连刺杀多名政府要员，令对手闻风丧胆，直到某一天，一名下级武士在他的脸上留下一道无法愈合的伤疤。来至京都寻找爱人的雪代巴邂逅了剑心，正是眼前这名瘦弱的男子将爱人从她的生命中带走。巴走入剑心的生活，随之经历了政治斗争的血雨腥风和田园乡下的宁静淡雅。也许她正是剑心那把狂舞之刀的刀鞘，但在大时代的背景之下，两个人的渺小幸福一触即碎……', '佐藤健', '大友启史', 8.5, 32737, 'tt11991748', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2641350668.jpg', 0.4, 1.4, 14.5, 40.1, 43.6, '-0.185806,0.354075,-0.638557,0.512782,-0.072027,-0.157061,0.494400,0.310203,-0.242997,-0.395460,0.385402,0.496974,0.239969,0.166563,0.388713,-0.341818,0.342337,-0.796922,-0.267484,0.020072,-0.370150,0.130418,-0.255217,0.007374,-0.493275,-0.454801,0.888719,0.403720,-0.204607,0.352437,0.199364,0.440950,0.068181,0.284143,-0.364340,-0.297064,-0.089205,-0.126648,-0.377313,0.093694,-0.294106,-0.368089,-0.163108,0.343024,-0.455400,0.082253,0.870734,-0.028386,0.006962,-0.453179,0.466365,0.032855,-0.267525,0.049692,0.153590,0.277459,-0.118663,0.030681,-0.218898,0.150945,0.089441,-0.414827,-0.825049,-0.173016,0.115717,-0.023406,-0.527068,0.324965,-0.193544,-0.009875,-0.080327,-0.147840,0.309322,0.041718,0.295911,0.298309,-0.283452,0.073596,-0.269296,0.108873,0.824661,-0.277245,-0.471054,0.060995,-0.280079,-0.262027,-0.200059,-0.371849,-0.125618,-0.166552,0.327344,0.046759,0.031373,0.701475,-0.497953,0.056043,-0.371084,0.134987,0.078140,-0.231994,-0.294069,0.023406,-0.310603,-0.258322,-0.330570,0.146538,0.213248,-0.071181,1.070482,-0.644263,0.149260,0.355983,0.070650,-0.202940,0.567028,0.149413,0.252666,-0.238210,-0.274401,0.824270,0.139637,0.197806,-0.134123,0.000549,-0.443192,0.130726,-0.122904,0.415920', '1763916', '27602116', '3001114', '3718665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33408026', '刻在你心底的名字', '剧情', '影片讲述上世纪90年代初，两位少年前往台北，那里的一切冲击着这两个少年的感官。学校宿舍里发生了对同性恋的霸凌，尽管禁忌一一解放，学校也开始招收女生，但同性恋三个字仍如毒蛇猛兽人人唾弃。而两个男孩间原本暧昧的情愫，也因一个女孩的介入，而就此被打乱。', '陈昊森', '柳广辉', 7.3, 103286, 'tt10329134', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2617820253.jpg', 1.1, 7.1, 35.4, 36.5, 19.9, '0.847968,-0.057745,-0.490570,0.480922,0.008677,-0.036189,0.932332,-0.057048,-0.487013,-0.206607,-0.007001,0.657056,-0.364820,0.718226,0.433772,-0.074031,-0.140782,-0.830073,-0.268465,-0.249761,-0.131686,-0.380945,-0.014266,-0.009127,-0.280347,-0.164418,0.438377,0.331603,-0.189657,0.414981,0.236080,-0.101464,-0.360245,0.240198,0.062637,-0.343941,-0.016750,0.174705,0.039060,-0.056863,-0.177353,-0.351503,-0.173302,0.114110,-0.409505,0.511751,0.667807,-0.133657,-0.144262,-0.266408,0.577981,-0.079654,-0.567121,0.088636,0.442227,0.147438,0.410411,0.256092,0.382850,-0.122392,-0.084969,-0.071768,-0.202333,0.092947,0.098399,0.240477,-0.211474,0.506449,0.258306,0.151095,-0.048440,0.002404,0.084044,0.086430,0.276533,0.523302,-0.302989,-0.093086,-0.362973,0.051607,0.737487,-0.093871,-0.568294,0.263019,-0.275670,-0.437813,-0.196206,0.222882,-0.588814,0.181887,-0.295902,0.145205,-0.413341,0.170612,-0.551639,0.283712,-0.082990,0.020719,-0.294773,-0.486830,-0.181646,-0.725783,-0.039125,-0.283342,-0.375191,-0.009279,0.250274,0.045819,0.859101,-0.656336,0.161924,0.404436,0.231661,-0.435408,0.621976,0.072240,0.216840,-0.144336,-0.176100,0.263573,-0.157934,0.016227,-0.209609,0.604683,-0.541508,0.033696,-0.220272,0.442167', '1307146', '1296534', '30162520', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33411505', '从不，很少，有时，总是', '剧情', '故事发生在位于美国宾夕法尼亚州的一个偏僻的小镇上，奥顿（茜德尼·弗拉尼根 Sidney Flanigan 饰）是生活在那里的一个平凡的少女。个性内向的奥顿和家人们关系非常的疏远，生活里也没什么能说得上话的朋友。一天，奥顿震惊的发现自己怀孕了，她前往镇上的医院就诊，在这个民风保守的小地方，堕胎是不被允许的。无奈之下，奥顿只能自己想办法打掉这个孩子，但试了好几个方法均以失败告终。表妹思凯乐（塔利娅·莱德 Talia Ryder 饰）是奥顿唯一的朋友，敏感又细心的她发现奥顿最近的表现非常的异常。几经询问之下，奥顿终于将自己的秘密告诉了思凯乐，思凯乐当机立断决定带着奥顿前往纽约堕胎。©豆瓣', '茜德尼·弗拉尼根', '伊丽莎·希特曼', 7.7, 43710, 'tt7772582', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2588279882.jpg', 0.3, 1.9, 28.3, 53.8, 15.8, '0.525513,-0.021882,-0.584797,0.539340,-0.105338,-0.026745,0.640577,0.049964,-0.780586,-0.364732,0.122282,0.853197,-0.057070,0.288913,0.173530,0.344853,-0.364594,-0.255888,0.069325,-0.238663,-0.320360,-0.638763,-0.348746,0.007108,-0.263226,-0.152545,0.409067,-0.029118,-0.163753,0.201620,0.241590,0.316365,0.102033,0.354726,-0.298234,-0.084168,0.104095,-0.176407,-0.064024,0.253650,0.152559,-0.175261,-0.195328,0.416698,0.212430,0.570095,0.463314,-0.021172,-0.235533,0.104644,0.259246,-0.177914,-0.124191,0.114164,0.167891,-0.301973,0.397743,0.195278,-0.314902,-0.102767,0.150845,0.038064,-0.647376,0.205345,0.277623,0.166408,-0.743939,0.520467,-0.103296,-0.256049,0.012047,-0.655308,0.367315,0.413377,0.182325,0.267936,-0.206967,0.003386,-0.440367,-0.130362,0.734367,0.001842,-0.272021,0.280293,-0.325433,-0.457171,0.126941,-0.230439,-0.505725,-0.005180,0.073897,0.143576,-0.364122,0.197048,-0.499453,0.004258,-0.372600,-0.225995,-0.006464,-0.345836,-0.041323,-0.411078,-0.132457,-0.546696,-0.494253,-0.048062,-0.109222,0.010881,0.530529,-0.929848,-0.000021,0.351536,0.460914,-0.426905,0.615741,0.218923,0.321182,-0.022266,-0.065419,0.295824,-0.003905,0.120111,0.013989,0.492299,0.054179,-0.382683,-0.435370,0.653742', '1783461', '1302384', '27125208', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33415943', '我失去了身体', '剧情', '一只断手在巴黎的一间实验室里逃脱了不幸的命运，动身重新和身体连接在一起。在一次令人毛骨悚然的穿越城市冒险之旅中，断手与鸽子和老鼠等诸多阻碍做斗争，只为与披萨男孩劳伍菲尔重聚。断手对劳伍菲尔的回忆以及他对图书管理员加布丽尔的爱可能会让我们了解导致断手与身体的分离的原因，并为他们三人可能的重逢提供了诗意的背景。本片改编自获奥斯卡金像奖提名的纪尧姆·洛朗（《天使爱美丽》）的小说《Happy Hand》。', '维克图瓦尔·杜布瓦', '杰赫米·克拉潘', 8.2, 27413, 'tt9806192', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2573594394.jpg', 0.3, 1.2, 16.7, 51.8, 30, '0.137409,-0.158836,-0.682095,0.543663,0.099921,-0.206947,1.090092,0.314169,-0.377258,0.148698,0.166351,1.020819,-0.084301,0.061075,0.314134,-0.046747,-0.193618,-0.817168,0.038569,-0.199833,-0.445144,-0.474060,-0.498600,-0.312309,0.054480,-0.570538,0.655975,0.210703,-0.061495,0.683950,0.260542,0.115469,-0.414848,0.325424,-0.061873,-0.119314,0.086217,0.166052,-0.551940,0.274108,0.053548,-0.010789,-0.152095,0.210718,-0.107538,0.114126,0.875398,-0.330954,-0.263788,-0.260975,0.337007,-0.084620,0.097698,0.042555,-0.042340,0.036461,0.416068,0.406753,-0.187499,0.146533,0.304452,0.115594,-0.965321,-0.073493,0.099131,0.249096,-0.589564,0.420757,-0.082117,-0.140770,0.073791,-0.137839,0.227577,0.438332,0.491871,0.598432,-0.030623,0.059085,-0.250970,-0.082752,0.469993,-0.354216,-0.292949,0.435150,-0.014950,-0.434442,-0.262455,0.034410,-0.494442,-0.090719,0.351507,0.261464,-0.243448,0.264861,-0.715164,0.080834,-0.372302,-0.242666,-0.120598,-0.495274,0.096660,-0.573001,-0.208992,-0.185514,-0.129357,0.054600,0.403330,-0.335921,0.649171,-0.815401,0.403615,0.781968,0.380780,-0.583799,0.706080,0.279129,0.219740,-0.210623,0.032579,0.320038,0.107429,0.300383,0.133866,0.435068,0.254463,0.072112,-0.759042,0.435903', '30401849', '3005387', '25928048', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33417030', '悲惨世界', '剧情', '刚从瑟堡来的斯蒂芬，加入了巴黎93省圣德尼的“反犯罪特种部队”。在这里，他遇到了新队友克里斯和瓦达，两位经验丰富的警察。但他很快就感受到了这个街区不同帮派间剑拔弩张的紧张氛围。在一次出警的行动中，局面变得不可控制，而这个事件意外地被一架无人机记录下来，进而引发了更为剧烈的冲突。', '达米安·勃纳尔', '拉吉·利', 8.1, 54433, 'tt10199590', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2592521688.jpg', 0.7, 1.5, 15.6, 55.8, 26.4, '0.776254,-0.046593,-0.970076,0.678894,-0.072440,-0.275992,0.746890,0.219973,-0.678619,-0.017989,0.112406,0.735939,-0.607915,-0.067104,0.328468,-0.202734,-0.292529,-0.688928,-0.098177,-0.007354,-0.436138,-0.270010,-0.399421,-0.486758,0.023421,-0.159281,0.496936,0.405613,-0.486561,0.690888,-0.030548,0.351725,0.065102,0.806663,-0.069501,-0.063378,0.308067,-0.151431,-0.012653,0.219751,0.085707,-0.415764,-0.142057,0.470726,0.165298,0.470251,0.734951,-0.100472,-0.251597,0.096091,0.138078,-0.078833,-0.054212,0.010684,0.609993,0.075963,-0.059407,-0.064034,-0.355406,0.115609,-0.200835,-0.138944,-0.644694,0.389664,-0.172159,0.315700,-0.338674,0.224173,-0.206732,-0.155390,0.072930,-0.102196,0.276394,0.688562,0.314717,0.292260,-0.266645,-0.254381,-0.350343,-0.289678,0.966927,-0.309690,-0.551606,0.391513,-0.200369,-0.485579,-0.339728,-0.146775,-0.208730,0.022645,0.554224,-0.134563,-0.208223,0.447042,-0.722699,-0.077866,-0.410270,-0.325032,-0.522185,-0.174915,-0.003839,-0.812129,-0.266154,-0.331776,-0.169580,0.217002,-0.081629,0.179822,0.490417,-0.904909,0.041978,0.793890,-0.031393,-0.491735,0.113253,0.092990,0.217393,-0.158557,-0.188556,-0.234454,0.031210,0.683801,0.342825,0.626712,-0.216589,-0.021732,-0.005328,0.299795', '34461680', '1294941', '1306723', '1298976');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33417046', '宠爱', '剧情', '电影《宠爱》共由6段温暖的故事组成，不同年龄段的人们，在宠物的陪伴和守护中，收获爱、发现爱，更重新学会爱。在“爱”的主线下，一系列关于亲情、友情、爱情的故事逐一展开。电影《宠爱》将于12月31日，全国公映，陪大家一起温暖跨年。', '于和伟', '杨子', 5.9, 244376, 'tt10203982', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2577327922.jpg', 6.1, 23.4, 46.4, 18, 6, '-0.199934,0.017526,-0.770275,0.775866,0.254768,0.141161,0.550704,-0.128731,-0.465234,0.293279,-0.107872,0.434167,-0.225077,0.589646,0.394244,-0.336435,-0.190130,-0.827486,0.104818,-0.146117,-0.054941,-0.666820,-0.262776,-0.313212,-0.246269,-0.835230,0.866466,0.289062,0.220078,0.366730,0.477409,-0.078173,-0.436527,0.218965,0.059466,-0.295809,-0.310591,0.172945,-1.143643,0.209307,-0.288892,0.008855,-0.099874,-0.135834,-0.102232,-0.436267,1.136908,-0.707525,-0.147130,-0.359190,0.961131,0.017750,-0.243489,-0.295397,-0.010624,0.554899,0.529452,0.639330,-0.106776,0.304927,-0.236562,-0.648549,-0.570147,-0.440797,0.435787,0.160974,-0.571215,0.702708,-0.162004,0.087388,0.373393,-0.300949,0.175585,0.171020,0.471967,0.989668,-0.295135,0.411346,0.133498,0.334534,0.850114,-0.213734,-0.126772,0.735889,-0.325601,-0.038419,-0.236079,-0.283212,-0.366141,0.294349,-0.180067,0.227049,-0.041631,0.461129,-0.718008,0.221289,0.705114,-0.296048,0.589831,-1.048561,0.075679,-0.821851,-0.183895,-0.397306,0.020369,0.166584,0.436096,-0.583530,1.417428,-0.802700,0.786968,0.520626,0.452576,-0.857637,1.124058,0.618585,0.131180,-0.315755,0.209861,0.759973,-0.147693,-0.442511,-0.092628,-0.027452,-0.379761,0.514825,-0.892078,0.496248', '1945253', '6963575', '11528271', '34947776');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33420285', '真心半解', '喜剧', '个性体贴的运动健将保罗爱上了学校校花，但他实在不善言辞，于是决定僱用内向的高材生艾莉帮他展开追求，毫不相干的两人也因此成为朋友。然而，艾莉发现自己竟然也对校花产生好感，她和保罗的友谊因此变得複杂。本片为编剧兼导演伍思薇的最新力作。', '莉娅·刘易斯', '伍思薇', 8, 135684, 'tt9683478', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2594916975.jpg', 0.4, 2.1, 21.6, 48.7, 27.2, '0.539624,-0.108907,-0.613621,0.845458,-0.279470,-0.521499,0.414251,0.325858,-0.563757,-0.239706,0.003488,0.506473,-0.295677,0.002438,0.558052,-0.294418,0.006868,-0.682220,0.045239,0.049078,0.207390,-0.429148,-0.373925,-0.110118,-0.242497,-0.375474,0.776864,-0.305798,-0.332953,0.332602,0.538016,0.155430,0.333700,0.605451,0.653629,-0.047596,0.137017,0.257012,-0.264322,0.214686,0.208856,0.014260,0.060480,0.156088,-0.110497,0.343660,0.587869,0.162814,-0.447489,-0.162563,0.737226,-0.348944,-0.035240,-0.072406,0.237074,0.374364,0.274530,-0.087981,0.247960,-0.064638,0.022519,-0.100666,-0.428258,0.302809,0.378628,-0.283012,-0.496993,0.310509,-0.347785,-0.407440,-0.142701,-0.363318,-0.169243,0.046239,0.751804,0.163122,-0.138805,0.510885,-0.017395,-0.068415,0.584735,0.144481,-0.546306,0.435592,-0.344717,-0.699519,0.047737,-0.370412,-0.602846,0.109797,-0.244024,0.071963,0.127879,0.164092,-0.554926,-0.342076,-0.182400,0.256939,0.000469,-0.536748,0.288701,-0.429904,-0.319636,-0.142581,-0.301852,-0.433510,0.005259,-0.593473,0.916572,-0.919768,0.179856,0.438205,0.264941,-0.610663,0.724411,0.421508,0.024400,-0.207321,-0.414271,0.456030,-0.097629,-0.226459,-0.159836,0.144094,-0.044403,-0.483042,-0.117367,0.350610', '6963575', '3445516', '1308499', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33424345', '紫罗兰永恒花园外传：永远与自动手记人偶', '剧情', '作为“战争机器”长大的女主人公薇尔莉特·伊芙加登，在战争中失去双臂，并与收养她的少佐分离，在装上义肢后，成为邮政公司一名从事代写书信工作的 “自动手记人偶”。在车马缓慢、只能以信件传递感情的年代里，“自动手记人偶”通过与委托人接触交流，代写书信，以优美准确的文字传递着人们最为真挚的感情。外传的故事中，薇尔莉特·伊芙加登接到了一桩特殊的委托工作……', '石川由依', '藤田春香', 7.4, 44401, 'tt10477558', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2578722076.jpg', 0.8, 4.9, 36, 39.4, 18.9, '0.467158,-0.002898,-0.268635,0.936056,0.072192,0.233898,0.571427,-0.141236,-0.133077,-0.248152,0.201000,0.780919,0.069677,0.286141,0.319267,-0.143406,-0.387996,-0.913435,-0.014224,-0.345434,-0.241359,-0.948149,0.329010,-0.057575,-0.144810,-0.467358,0.858949,-0.373434,-0.304050,0.628131,0.029104,0.226925,-0.849152,0.319063,-0.141406,-0.004313,0.022748,-0.340440,-0.311795,-0.048125,0.101556,0.088107,0.196163,0.237049,0.115254,0.340793,0.804432,-0.840559,0.088397,0.075939,0.622321,0.407028,0.328836,-0.134888,0.201486,0.650416,0.143872,0.553658,-0.662826,0.129034,0.072765,-0.197941,-0.711340,-0.306596,-0.027972,0.306700,-0.484386,0.264434,0.038968,0.169755,-0.090200,-0.202979,0.211214,0.351055,0.200824,0.409851,-0.259890,0.263975,-0.127137,0.163107,-0.041907,-0.119752,-0.670546,0.558763,-0.149277,-0.316204,0.191731,-0.131947,-0.398002,-0.038532,0.227039,0.263311,-0.147747,0.304504,-0.701740,-0.077290,-0.248257,-0.171769,0.402553,-0.231353,-0.238014,-0.892088,-0.174276,-0.176260,-0.513561,-0.121176,0.065228,-0.292063,0.864561,-0.805186,0.068709,0.588392,0.045277,-0.302731,0.544802,-0.063143,0.362917,-0.338157,-0.259898,0.529138,0.282285,0.433775,0.338212,0.200481,-0.016851,0.095887,-0.347762,0.628485', '20274039', '30434174', '3811356', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33425932', '鸣鸟不飞：乌云密布', '动画', '矢代个性超M又变态的人，从不会让别人看透他的内心。某天身边来了一名叫做百目鬼力的随从兼保镖。虽然早早就下定决心，绝不对不会对部下出手，但矢代不知为何，被百目鬼所深深吸引。彼此怀抱着自己的伤痛而活着的两人，他们的故事即将开始。', '新垣樽助', '牧田佳织', 8.3, 27367, 'tt10675392', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2586787185.jpg', 0.7, 2.2, 17.2, 41.7, 38.1, '0.264691,-0.055620,-0.693979,0.612814,-0.476818,-0.043232,0.912986,0.005138,-0.477655,-0.317006,0.402848,0.844617,-0.232285,0.287734,0.098241,0.218289,0.048070,-0.734916,-0.442679,-0.192914,-0.496501,-0.136339,-0.221735,-0.248000,0.010361,-0.267406,0.693145,0.346948,-0.014910,0.334185,0.305687,0.596807,0.072762,0.837167,-0.264776,0.010993,0.018382,-0.080573,0.147649,0.165003,0.167154,-0.334014,-0.288776,0.662334,-0.539967,0.037667,0.691224,-0.481291,-0.254372,-0.140287,-0.088701,-0.319646,0.074827,0.298440,0.116339,-0.101505,0.363696,0.321420,-0.119867,0.049867,0.069328,0.218329,-0.914174,0.139754,-0.093342,0.167096,-0.498603,0.123389,-0.303546,-0.013789,0.189773,-0.355404,-0.020612,0.013114,0.378922,0.174521,-0.455051,-0.201152,-0.664012,-0.129626,0.973553,0.153809,-0.008995,0.364229,-0.171867,-0.328672,-0.189634,-0.228362,-0.493388,-0.091829,0.252183,0.562367,-0.485318,0.060173,-0.107691,-0.260357,-0.131911,0.189146,-0.062664,-0.674554,-0.060356,-0.076437,-0.319413,-0.505253,-0.206580,0.220424,0.067070,-0.082179,1.027081,-0.963694,0.270072,0.876889,0.369994,-0.640173,0.619541,0.001968,-0.395684,-0.300827,-0.085957,-0.089492,0.161254,0.340634,0.570375,0.403152,-0.119223,-0.052573,-0.103182,0.739267', '30163500', '3230462', '25932086', '6874741');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33427574', '天堂的张望', '剧情', '7岁女孩张望和父亲张国华相依为命，生活虽是清贫，但还是生活的很幸福。一天张望突然流鼻血不止，去医院检查，才知得了急性白血病，治疗需要30多万的费用，筹钱无果的张国华整日以泪洗面；而张望，清楚自己的家庭情况，毅然决定放弃治疗。记者王小月得知此事，赶往张国华家中，才得知了张望的真实身世.....事件经媒体曝光后，张望引起社会各界关注，全国各地纷纷捐款资助，很快，张望的医疗费就凑够了。感受到社会爱的力量和无数陌生人的关心，也使张望变得无比坚强，她用常人难以想象的痛苦接受着治疗，并一次一次经历着鬼门关，然而就在大家都认为张望的病快要好起来的时候，张望却做了一个出乎所有人意料的决定..........', '杜奕衡', '杜斌', 6.8, 12685, '', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2623879042.jpg', 5.4, 9.5, 41.5, 29.6, 13.9, '-0.116729,-0.501509,-0.413397,0.150307,-0.055798,-0.083355,0.623263,0.028392,-0.530469,-0.192443,0.220078,0.515313,-0.271838,0.267228,-0.056396,-0.213447,-0.226456,-0.577575,-0.054416,0.121451,-0.319446,-0.268443,-0.046848,-0.502793,-0.244202,-0.297274,0.183015,0.268483,-0.065160,0.399146,0.139378,0.007644,0.122109,0.730331,-0.217681,-0.199021,0.181900,0.495802,0.005670,0.082124,0.306269,-0.614813,-0.346091,0.501163,0.143696,0.252357,0.586678,-0.054476,-0.450302,0.328350,0.401784,-0.177166,-0.056545,0.245043,0.466337,0.203352,0.230207,-0.114403,-0.532176,0.065962,-0.396348,0.310278,-0.527720,-0.175564,0.508884,0.222737,-0.680468,0.391823,0.090092,0.010547,0.044367,-0.341195,0.011733,0.454888,-0.014041,0.504305,-0.250629,-0.123995,-0.286098,0.068350,0.533761,-0.201552,-0.286054,0.466051,-0.439519,-0.368802,0.234492,-0.038145,-0.530779,0.025736,0.098137,0.366215,-0.611654,0.065057,0.090721,0.077635,-0.691670,-0.912777,-0.100505,-0.377764,-0.163590,-0.622767,-0.362290,-0.271416,-0.498835,0.207302,-0.047749,-0.590871,0.588245,-0.704805,-0.111647,0.542092,0.147609,-0.837642,0.852986,-0.142122,-0.173879,-0.161753,0.047858,0.526205,-0.129433,0.403239,-0.333520,0.170561,-0.082747,-0.070871,-0.295357,0.446458', '2990737', '1302384', '1303823', '19967839');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33427589', '世界奇妙物语 2019雨之特别篇', '剧情', '击退各种怪人，守护世界和平的警察大场博人（乡广美）唯一的放松便是与女儿亚希（上白石萌音）的视频通话。本以为明年退休后可以跟女儿一起悠闲生活的他不料却收到了恐怖袭击预告。', '乡裕美', '紙谷楓', 6.5, 7016, 'tt10491414', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2581969949.jpg', 1.9, 13.9, 49.1, 26.3, 8.8, '0.313155,0.011261,-0.539768,0.325865,-0.047630,-0.359994,0.318504,0.148834,-0.368397,-0.176938,-0.015670,0.440013,-0.399122,0.231116,0.412076,-0.102806,-0.748743,-0.714372,-0.273640,0.114797,-0.262027,-0.132888,-0.156372,-0.362701,-0.017236,-0.233122,0.859989,0.131140,-0.059788,0.552339,-0.017441,0.194267,-0.252759,0.158607,-0.467159,-0.097478,-0.243904,0.212099,-0.577681,0.316067,0.006751,-0.139970,-0.114918,0.117936,0.193464,0.241409,0.444635,-0.200613,-0.080381,-0.142840,-0.002632,-0.207691,-0.276727,-0.039648,0.052505,-0.056994,0.536915,0.235159,-0.164933,-0.318757,0.041072,-0.193551,-0.166277,0.142513,-0.344894,0.010249,0.003062,0.569873,-0.088349,0.111586,0.112799,-0.195686,0.403115,0.653747,0.346403,0.088297,-0.381921,0.264963,-0.164530,0.164718,0.483789,-0.037927,-0.077256,0.283835,-0.019344,-0.326439,0.020887,-0.235570,-0.274775,0.002764,-0.023588,0.125011,-0.290496,0.058718,-0.510655,-0.137642,-0.344865,0.026030,0.282187,-0.504091,-0.239367,-0.756881,0.005680,-0.081245,-0.180686,0.264250,0.315992,-0.312931,0.791045,-0.730519,0.475476,0.275904,0.349763,-0.325204,0.552274,0.239857,0.105131,-0.419735,0.074950,-0.030805,0.120221,0.382027,0.153457,0.030691,-0.228598,-0.122235,-0.302402,0.548100', '2369613', '20274039', '26365262', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33428622', '叔·叔', '剧情', '计程车司机柏（太保饰演），以及退休单亲爸爸海（袁富华饰演），即使大半生受尽传统社会的规范与约束，两人仍对多年来努力建立的家庭为荣。不过，两人没料到能在人生的最后这段路上，与彼此邂逅…。柏与清（区嘉雯饰演）结婚45年，育有一子一女，可谓上一代传统香港人眼中「幸福家庭」的典范。海的太太早年离他而去，与儿子永（卢镇业饰演）相依为命。虽然海与儿子一家同居，却无法感受到家的温暖。而柏与海迟来的相遇，也翻搅起两人尘封心底的爱慾。面对「爱情诱惑」与「社会道德价值」的拉扯，以及内心「原始慾望」跟社会传统「幸福家庭」的抉择，两人究竟要回归最原始的自己？还是重返风平浪静的生活，继续守护社会价值观所认可的「美好家庭」呢？', '太保', '杨曜恺', 7.6, 23824, 'tt10975520', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2588031096.jpg', 0.7, 2.2, 28, 53.5, 15.6, '-0.020657,0.096469,-0.773595,0.740666,0.252893,-0.368233,0.538159,0.020568,-0.519751,-0.449767,-0.212372,0.704721,0.057535,0.409063,0.451208,-0.181891,-0.101540,-0.669593,-0.188160,0.027387,-0.177447,-0.410801,-0.153274,-0.065114,-0.279592,-0.144835,0.916674,0.325412,-0.227538,0.432258,0.285864,0.357896,-0.303366,0.163502,-0.425768,-0.092187,-0.169003,0.438072,-0.953157,-0.228789,0.183109,-0.093832,-0.174025,0.091680,0.174149,0.005351,0.647386,-0.298553,-0.083385,-0.006023,0.334903,-0.144456,-0.314857,0.024227,0.223730,-0.108382,0.276339,0.605375,0.028671,-0.069048,-0.188445,-0.215220,-0.784576,-0.289620,0.172095,-0.321636,-0.534433,0.478718,0.326043,-0.217968,-0.109375,-0.188561,0.100019,0.155066,0.122635,0.842883,-0.369193,0.217788,-0.223714,0.204754,0.978524,0.101364,-0.188739,0.408285,-0.546621,-0.376522,-0.321662,-0.512866,-0.604466,-0.152532,-0.086332,0.233736,-0.319342,0.418700,-0.387761,0.219825,-0.221828,0.076229,0.616631,-0.611559,0.000912,-0.382159,-0.390181,-0.804001,-0.141671,0.271988,0.066074,-0.363100,0.689645,-0.750536,0.174252,0.080651,0.283675,-0.819651,1.011099,0.554745,0.086877,-0.642142,-0.080255,0.599944,-0.152363,-0.063335,-0.141275,-0.056617,-0.241740,0.382957,-0.313776,0.324856', '26921076', '30301264', '4145476', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33432655', '困在时间里的父亲', '剧情', '影片以重复加碎片式的感官叙事手法，讲述了年迈且身患疾病的安东尼（安东尼·霍普金斯 Anthony Hopkins 饰）正在面临一项艰难的人生选择——是搬到养老院还是接受女儿寻找的新护工。在这个过程中，安东尼发现自己仿佛进入了一场奇怪的时空之旅，错乱的记忆和时间线交织出一段段匪夷所思的故事，而一个个陌生又熟悉的人也让他陷入迷茫。影片根据法国小说家兼剧作家佛罗莱恩·泽勒的舞台剧《父亲》改编。', '安东尼·霍普金斯', '佛罗莱恩·泽勒', 8.6, 230901, 'tt10272386', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2628877926.jpg', 0.1, 0.6, 9.6, 49.3, 40.4, '0.175508,0.050954,-0.438509,0.670388,0.242921,-0.269692,0.851515,0.054678,-0.781509,-0.333201,0.224724,0.568791,-0.123581,0.177424,0.461102,0.080516,-0.493352,-0.650253,-0.010357,0.124326,-0.454445,-0.538299,-0.068831,-0.449103,0.178150,-0.577228,0.467636,0.224840,-0.470813,0.189428,-0.003518,0.385873,-0.153440,0.269543,-0.001180,0.250341,0.040332,0.017567,-0.243256,-0.027159,0.270918,-0.297536,-0.094495,0.064013,-0.315436,0.475179,0.936633,-0.129423,-0.154480,0.325995,0.639815,-0.181762,-0.453135,-0.056000,-0.063178,0.381340,0.054958,-0.074108,-0.209237,0.192963,-0.254049,-0.174658,-1.021421,-0.056486,0.235974,0.353951,-0.409814,0.213277,-0.045718,0.039120,-0.001790,-0.369589,0.023553,0.065543,0.735642,0.827669,-0.129641,-0.135743,0.018779,0.387046,0.501175,-0.061914,-0.746844,0.474190,-0.428899,-0.402943,-0.106868,-0.199062,-0.326692,0.164995,0.301886,0.149797,-0.138176,0.483175,-0.685280,-0.062628,-0.192176,-0.488357,-0.081606,-0.353049,-0.250191,-0.730920,-0.142722,-0.207389,-0.193473,-0.218733,-0.022285,-0.371380,0.690455,-0.453018,0.237257,0.531292,-0.180150,-0.203735,0.506881,-0.055200,0.236842,-0.392978,0.076753,0.391276,-0.118283,0.158587,-0.014999,0.354009,-0.196583,0.216038,-0.768818,0.504354', '6844861', '1457127', '27157811', '1422088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33436135', '只有芸知道', '剧情', '改编自冯小刚挚友的真实爱情经历，讲述了隋东风和罗芸之间相濡以沫的动人爱情故事。但罗芸隐藏了一个只有她知道的秘密，秘密的背后却是她对隋东风刻骨铭心的爱……', '黄轩', '冯小刚', 6.3, 156439, 'tt10564446', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2574861328.jpg', 4.7, 18.7, 42.7, 24.2, 9.6, '0.597706,0.180216,-0.659872,0.870467,0.465179,0.124239,1.252491,-0.057588,-0.495461,-0.098928,0.112904,0.313380,0.144771,0.065111,0.250646,0.076837,-0.068301,-0.951514,0.160667,-0.363525,0.183682,-0.693295,-0.700106,0.028110,-0.169737,-0.188746,0.680048,0.412198,-0.334440,0.513326,0.746924,0.056261,-0.127419,0.582548,-0.271111,0.128237,0.371300,0.394049,-0.920915,-0.113630,0.088885,-0.379746,0.170604,0.443738,-0.885342,0.322880,0.352020,-0.372826,-0.083098,0.113206,0.465809,-0.045053,-0.073200,-0.103562,0.188732,0.155482,0.369490,0.707125,-0.059108,-0.200795,-0.109953,0.153286,-1.159204,-0.426242,0.622663,0.344648,-0.473017,0.446558,-0.003993,-0.067733,0.369314,-0.046862,0.377067,-0.108743,0.692463,0.534697,-0.060465,0.163716,-0.279676,0.396910,0.899547,-0.391686,-0.055546,0.795623,-0.337021,-0.276195,-0.311442,-0.267867,-0.621979,0.379440,0.055995,-0.158993,-0.016444,0.298556,-0.456074,0.035141,-0.064979,0.242217,0.237262,-0.888015,-0.145605,0.180083,-1.000491,-1.027574,-0.417590,-0.159514,0.110079,-0.583284,0.928387,-0.679981,0.019994,0.701860,0.082560,-0.468734,0.753760,0.909449,0.006342,-0.418581,0.331243,0.717999,-0.391046,-0.134839,-0.239102,0.274495,0.148856,0.450987,-0.440962,0.463055', '1417428', '35360296', '1422954', '1307748');
