INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33437580', '天赐灵机', '喜剧', '巴尼是一个有着社交障碍的中学生。罗恩，则是他全新的行走、交流、数字连接的设备。罗恩是巴尼“开箱即用的最好朋友”。在社交媒体的背景下，罗恩的搞笑故障，将他们带入了一场动感十足的旅程，男孩和机器人在这段旅程中接受了真实友谊的美妙和混乱。', '杰克·迪伦·格雷泽', '莎拉·史密斯', 7.7, 22406, 'tt7504818', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2681332523.jpg', 0.6, 3.3, 29.8, 44.3, 22, '0.549331,-0.004837,-0.403916,0.715227,-0.008473,0.071642,1.069932,-0.105953,-0.401735,0.112828,0.554199,0.737786,-0.488584,0.021992,0.428114,-0.219387,-0.531461,-0.750633,-0.074340,-0.106190,-0.413095,-0.727437,-0.251523,-0.336485,-0.066971,-0.289235,0.889948,-0.130413,-0.548824,0.369676,0.058132,-0.139554,-0.393884,0.429901,-0.321580,-0.049776,0.047776,0.019558,-0.379169,-0.161563,-0.116831,-0.117521,0.114581,0.134043,-0.037134,0.377252,0.903578,-0.561010,-0.004203,0.484383,0.529599,-0.069113,-0.198840,0.059851,0.097761,0.005251,0.129559,0.059849,-0.155973,0.165142,-0.114441,-0.064109,-1.024266,-0.289012,0.072488,0.211490,-0.469345,0.959537,0.035780,-0.319861,0.238723,-0.213472,0.216855,0.381219,0.475062,0.592480,-0.018374,0.144830,-0.123593,0.157936,0.514546,0.221464,-0.682955,0.549498,-0.761375,-0.618321,-0.471954,-0.028134,-0.598532,-0.303664,0.532159,-0.109956,-0.161099,0.402836,-0.995503,0.166758,0.138741,-0.256445,-0.064226,-0.682995,-0.166390,-0.971179,-0.003287,-0.486711,-0.162232,-0.046134,0.258035,-0.361167,0.955959,-0.943135,-0.050200,0.791881,0.103763,0.055114,0.768220,0.161677,0.296893,-0.520719,-0.426540,0.145352,-0.148287,0.563583,0.060081,0.829938,-0.164142,0.222872,-0.695242,0.548407', '2053515', '3005387', '1829230', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33441781', '神枪手', '动作', '吉姆（连姆·尼森 Liam Neeson 饰）曾经是为了海军陆战队卖命的神射手，退休之后，他来到了位于亚利桑那州边境的一座牧场之中，过起了离群索居的生活。一场意外中，吉姆目睹了一位名叫罗莎（特蕾莎·鲁伊斯 Teresa Ruiz 饰）的年轻母亲遭到墨西哥毒贩追杀的场面，临死之前，罗莎将自己年仅11岁的儿子米格尔（雅各布·佩雷斯 Jacob Perez 饰）托付给了吉姆。吉姆决定带着米格尔前往芝加哥，在那里，生活着米格尔其他的家人们，在此过程中，一向无牵无挂独善其身的吉姆和米格尔之间产生了真挚的亲情。旅途遥远，除了要照顾年幼的米格尔外，吉姆还必须应对在身后紧追不舍的毒贩们。©豆瓣', '连姆·尼森', '罗伯特·洛伦兹', 5.5, 8757, 'tt6902332', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2631071497.jpg', 5.2, 31.5, 48.8, 10.5, 4, '0.235971,-0.053186,-0.731971,0.593164,-0.303212,-0.377983,0.801387,0.173397,-0.571751,-0.256415,0.130932,0.806782,0.045923,0.350525,0.473204,0.025657,-0.527857,-0.675259,-0.377507,-0.154944,-0.236683,-0.638775,-0.318123,-0.149132,-0.237610,-0.347902,0.403229,0.050871,0.112311,0.643686,0.235907,0.437687,-0.200724,0.266282,-0.272588,0.038182,0.296556,-0.224894,-0.449022,0.197646,-0.018814,-0.084125,-0.107549,0.067155,0.163442,0.327160,0.606749,-0.252444,0.180508,-0.253082,0.058431,0.013224,0.222483,0.324604,0.286848,-0.235936,0.240026,0.167535,-0.234662,0.079160,0.042831,-0.243530,-0.551833,0.025587,-0.035852,0.144605,-0.808165,0.310974,-0.000371,-0.119562,0.316173,-0.325037,0.190839,0.450024,0.015642,0.371363,-0.071100,-0.001189,-0.373675,0.022715,0.794991,-0.144649,-0.140663,-0.006048,-0.110444,-0.223044,0.039311,-0.126496,-0.630702,-0.083424,0.384019,-0.143333,-0.053305,0.361990,-0.436447,0.068523,-0.254329,-0.337409,0.008253,-0.119638,-0.244366,-0.740124,0.044495,-0.531644,-0.332066,0.001091,-0.124035,-0.098888,0.635435,-0.698869,0.369582,0.444273,0.255199,-0.146652,0.576865,0.214874,0.552790,0.003331,-0.081371,0.502479,-0.069538,0.120583,0.002885,0.218607,-0.159757,-0.211541,-0.302815,0.548495', '3111650', '1895119', '24698878', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33441983', '正直的候选人', '喜剧', '电影《正直的候选人》是一部讲述最容易说谎的3选国会议员"朱尚淑"(罗美兰饰)在选举前夕的某一天早晨突然无法说谎，而引发的左冲右突的喜剧。2019年凭借《我身体里的那个家伙》和《女警》的票房成为"喜剧不败演员"的罗美兰，通过《正直的候选人》变身在某一天突然成为了世界上最正直的政治家"朱相淑"回归。 预计演员罗美兰将以特有的喜剧演技再次给观众带来真实的欢笑。', '罗美兰', '张幼珍', 7.1, 20437, 'tt11812338', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2580093763.jpg', 0.4, 3.7, 45.5, 39.9, 10.5, '0.092918,0.126885,-0.337232,0.549342,-0.144160,-0.316566,0.517914,0.161335,-0.389594,-0.283606,0.406293,0.754523,-0.560973,0.051704,0.586442,-0.175486,-0.147314,-0.749620,-0.240300,-0.128535,-0.163323,-0.365402,-0.217865,-0.076613,0.039907,-0.285523,0.828857,0.092334,-0.346527,0.053083,0.533343,0.344345,0.333641,0.300924,0.060788,0.036150,-0.253879,0.029548,-0.164193,0.434814,0.179987,-0.260683,-0.032854,0.180725,-0.099235,0.100825,0.601669,-0.548109,-0.087754,-0.053955,0.874636,-0.300362,-0.232438,-0.128249,0.263081,0.064091,0.348994,0.171354,-0.128750,0.118495,-0.147614,-0.228492,-1.044828,0.133836,0.129886,0.233684,-0.120186,0.219830,0.203165,-0.041834,0.231991,-0.003853,0.225520,0.462587,0.352135,0.537853,-0.209767,0.300199,-0.357478,0.426970,0.383398,0.355305,-0.348838,0.479055,-0.158377,-0.503900,0.001373,-0.418118,-0.421142,0.005867,0.422060,0.031003,0.104074,0.233490,-0.674496,0.108968,0.028940,-0.035781,0.012742,-0.264948,-0.082872,-0.504827,-0.157272,-0.222582,0.161019,-0.279406,-0.012920,-0.564689,1.182376,-0.961384,0.168893,0.285793,0.375332,-0.128887,0.751876,0.180666,-0.052495,-0.276792,0.020644,0.251619,0.144773,0.198143,-0.087662,0.388772,-0.350807,-0.498556,-0.393366,0.671099', '27602116', '24284209', '25880986', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3344570', '爱情呼叫转移Ⅱ：爱情左右', '喜剧', '当红电视情感节目主持人聂冰（林嘉欣 饰）在年过三十之际突然感到情感上的困惑：她的父母婚姻失败，母亲（丛珊 饰）整日唠唠叨叨，父亲（朱时茂 饰）娶了聂冰的小学同学，追求者由爱生恨恶语相向……这一切都让她疲惫不堪。某日，聂冰遇到一个奇怪的天使（黄渤 饰），天使送给她一辆神奇的汽车，只要每次转弯时打着左灯向右行，她就会碰到一个不同类型的男子，一共12个类型！这样的遭遇不可谓不奇特，心怀疑惑的聂冰开始与白马王子候选人们一一邂逅。滔滔不绝的保险推销员（古巨基 饰）、自恋无比的选秀狂人（苏有朋 饰）、独断自大的律师（陆毅 饰）、忧郁内向的艺术家（黄磊 饰）……这些男人虽各有各的优点，却又各有其乖张之处。他们令聂冰难以忍受，几近崩溃……©豆瓣', '林嘉欣', '张建亚', 5.3, 84834, 'tt1340761', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2192304450.jpg', 11.1, 29.8, 46.4, 10.2, 2.4, '0.338162,-0.077605,-0.592710,0.546743,0.002856,-0.165344,0.909626,0.078926,-0.438893,-0.291635,0.378678,0.594158,-0.450672,0.180191,0.278878,0.037565,-0.022145,-0.414060,-0.114535,0.033541,-0.045388,-0.144363,-0.233985,-0.161961,-0.165849,-0.079497,0.496823,-0.133042,-0.114051,0.463382,0.494930,0.323820,0.008146,0.390971,-0.102902,-0.012807,-0.046689,0.214543,0.082226,-0.232654,-0.072665,-0.114745,-0.049843,0.173901,-0.413116,0.443023,0.662140,-0.102189,-0.223498,-0.086317,0.579674,0.059606,-0.074683,0.155453,0.068705,0.147096,0.207863,-0.081512,-0.000984,0.091463,0.070026,0.088882,-0.522428,-0.103933,0.104821,0.202355,-0.337393,0.371783,-0.202219,-0.015190,0.067752,-0.301324,-0.039965,-0.020606,0.324777,0.300613,-0.195175,-0.021633,-0.196926,0.376549,0.616871,0.411255,-0.379102,0.467417,-0.343358,-0.475438,0.104410,-0.180652,-0.667839,0.142881,0.208425,-0.041140,0.169055,0.096613,-0.654943,0.067241,0.217872,0.138596,-0.041907,-0.238150,-0.042985,-0.379602,0.019811,-0.641861,-0.447462,0.049753,0.097770,-0.022854,0.804128,-0.750938,0.047295,0.401065,0.124095,-0.530876,0.698360,0.171169,-0.140052,-0.192645,-0.126408,0.183548,-0.240367,-0.036034,-0.221734,0.499410,-0.086589,-0.122158,-0.151826,0.284851', '1292062', '24839498', '6963575', '3033092');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33446014', '人类清除计划5', '科幻', '故事紧接《人类清除计划3》。从贩毒集团手中脱逃的阿德拉与丈夫胡安自墨西哥来到美国得克萨斯州生活，后者在塔克家族的牧场工作。胡安深受塔克一家的族长，凯莱布的赏识，但这也让凯莱布之子迪伦心生妒忌。但在一年一度的“人类清除计划”过后的早上，一支地下组织意图将杀戮继续进行下去，让全美陷入狂乱之中。包括迪伦妻子和妹妹在内的塔克一家也遭受波及，迫使众人联合起来对付暴徒，并设法逃入开放边境仅有六小时的墨西哥。', '安娜·德拉·雷古拉', '埃弗拉多·瓦莱里奥·古特', 6, 14904, 'tt10327252', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2646890883.jpg', 4.2, 19.2, 53.4, 17.4, 5.7, '0.078191,-0.099480,-0.654863,0.415665,0.106185,-0.230651,0.522963,0.194012,-0.531901,-0.117814,0.059616,0.760488,0.030322,-0.098552,0.375201,-0.096510,-0.549830,-0.486564,-0.171545,-0.128579,-0.001985,-0.459878,0.078730,-0.378555,0.126169,-0.472536,0.630181,0.160775,-0.219682,0.494980,-0.083694,0.343705,-0.230698,0.340037,0.066146,-0.113256,0.126678,-0.376549,-0.555493,0.503742,-0.027138,-0.086451,-0.149655,0.149207,0.148406,0.341618,0.570554,-0.307315,0.006900,-0.435322,-0.028827,-0.374300,-0.097463,0.243157,0.436366,-0.051245,0.113460,0.285274,-0.274052,0.100289,0.137089,-0.067112,-0.783743,0.054324,0.142686,-0.047619,-0.466890,0.393410,-0.076585,0.036062,-0.132774,-0.246097,0.251484,0.691468,0.301873,0.097143,-0.243417,0.216076,-0.622934,-0.271351,0.810921,-0.397272,-0.061440,-0.308423,-0.156829,-0.270834,-0.046844,-0.169920,-0.222025,-0.413526,0.176257,0.122442,-0.050587,0.574142,-0.757724,0.045695,-0.523813,-0.563213,0.103565,-0.397960,-0.126948,-0.608560,-0.226838,0.051435,-0.094968,-0.174765,0.324596,-0.211691,0.553430,-0.699897,0.380516,0.420177,0.579302,-0.313355,0.130893,0.187341,0.532238,-0.081822,-0.300428,0.413765,0.290552,0.262874,0.045198,0.139642,-0.102375,-0.257623,-0.203814,0.197237', '1849026', '25721544', '2032339', '6790253');
