INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33446524', '剧场', '剧情', '永田从高中开始和朋友建立了一个剧团，他兼任编剧和导演，但剧作由于太过前卫收到了很多差评，剧团面临着即将解散的状态。直到一天，永田在路上向穿着同样鞋子的沙希搭话。梦想成为演员的沙希和永田就这么谈起了恋爱。身无分文的永田搬进了沙希的家里，两人开始了同居生活。沙希无条件地支持着永田追逐梦想，永田也渐渐重新拾起对戏剧的热爱。', '山崎贤人', '行定勋', 7.8, 23183, 'tt10650424', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2610788779.jpg', 1.1, 3.5, 23.9, 47.1, 24.3, '0.309307,-0.012209,-0.470782,0.503836,-0.160422,-0.664813,0.422126,0.413936,-0.380182,-0.416631,0.188423,0.876037,-0.116849,0.462722,0.694622,-0.171114,-0.578469,-1.080362,-0.065146,0.155110,-0.121664,-0.370782,0.090001,0.053947,-0.485411,-0.399691,1.116407,0.162760,-0.144499,0.673198,0.289491,0.277750,0.118617,0.266523,-0.191410,0.180958,0.273430,0.167724,-0.322449,0.288667,-0.080311,-0.305354,-0.065604,0.343919,0.394144,0.280505,0.661801,-0.119923,-0.041496,0.252018,0.576990,-0.411634,-0.209407,0.141599,0.507327,0.423030,0.210457,0.235860,-0.141771,0.016111,-0.045227,-0.257731,-0.346359,-0.104942,0.090634,0.305235,-0.777218,0.448095,0.251745,-0.190028,0.353309,-0.334930,0.065847,0.647059,0.151332,0.487416,-0.259509,0.121661,-0.270910,0.521680,0.415938,0.016623,-0.155544,0.479674,0.031128,-0.339385,-0.342110,0.027870,-0.496780,-0.399982,-0.061383,-0.010923,-0.153955,0.035355,-0.826690,0.061256,0.064421,-0.473460,0.379250,-0.473748,0.116136,-0.726874,-0.014997,-0.593741,-0.253865,0.128610,0.110018,-0.375032,1.026268,-0.975603,0.185589,0.323387,0.376950,-0.215931,0.535495,0.249962,-0.086363,-0.080008,0.411807,-0.000857,0.046881,0.369409,0.283587,0.566760,-0.144065,-0.238222,-0.564215,0.474437', '3811356', '1826173', '26784898', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33450426', '电锯惊魂9：漩涡', '悬疑', '老鸟警探（塞缪尔·杰克逊 Samuel L. Jackson 饰）带领警探（克里斯·洛克 Chris Rock 饰）调查惨绝人寰的连环杀警案，“拼图杀人魔”重出江湖的传言，再度勾起所有人心中的恐惧。这次新的游戏规则，似乎直冲警察而来。每个命案现场留下的“死亡漩涡”，将把他们卷进难以抽身的血腥深渊之中……《电锯惊魂》第九部由第8部的两位编剧皮特·古德芬格和乔什·斯托伯格撰写剧本。执导了《电锯惊魂234》的达伦·林恩·鲍斯曼此番回归执导。', '克里斯·洛克', '达伦·林恩·鲍斯曼', 5.2, 30191, 'tt10342730', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2637809736.jpg', 11.2, 33.8, 40.8, 9.8, 4.5, '0.136528,-0.301052,-0.581526,0.446900,0.275278,-0.250669,0.693582,0.038159,-0.357319,-0.140490,0.226410,0.659962,-0.348420,-0.132513,0.293984,0.043452,-0.347537,-0.734253,-0.589621,-0.082956,0.093535,-0.179578,-0.319200,-0.064426,0.153483,-0.104581,0.482724,0.102787,0.163429,0.485330,0.470505,0.682904,-0.442689,0.056365,0.360519,0.195844,0.342114,-0.365823,-0.414393,0.180856,-0.063124,-0.107555,-0.242716,0.278763,-0.165849,0.477859,0.541886,-0.349754,0.197083,-0.218838,0.400849,-0.383140,-0.148131,0.119518,-0.030697,0.137982,-0.123555,0.357695,-0.111696,0.241853,-0.164215,-0.075001,-0.962471,-0.042319,0.017415,0.327604,-0.314095,-0.222715,-0.397828,0.209947,0.130218,0.099369,0.047296,-0.112761,0.626561,-0.072035,0.128927,-0.143806,-0.030427,0.115984,0.374218,-0.195947,-0.273543,0.027336,-0.117932,-0.382031,-0.245566,0.058291,-0.232758,0.149635,0.623771,0.199176,-0.046364,0.386607,-0.517349,-0.373673,-0.481811,-0.310781,-0.503833,-0.032162,-0.203405,-0.920809,-0.225472,0.298685,-0.013543,-0.461097,0.079130,0.069378,0.148911,-0.322627,0.250752,0.391022,-0.271823,0.063069,0.115527,-0.052442,-0.088534,-0.212025,0.041211,0.044113,0.369293,0.450492,0.199925,0.416137,-0.031304,-0.263548,-0.134264,0.317121', '6517421', '4014397', '3318306', '26577354');
