INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33454474', '如果声音不记得', '爱情', '辛唐（孙晨竣 饰）拥有能够通过声音控制他人情绪的超能力，为了能够在这个世界上平凡的生活下去，辛唐小心谨慎的守护着自己的这个秘密。一次偶然中，辛唐邂逅了名为吉择（章若楠 饰）的女孩，并且在阴差阳错之下救下了准备自杀的吉择，就这样，两人的命运被紧紧的绑定在了一起。吉择虽然表面看来是在网络上拥有众多粉丝的女网红，但实际上，她患有非常严重的抑郁症，每天都在绝望和痛苦的深渊里挣扎，为了帮助吉择，辛唐不离不弃的守护在他的身边，用自己的声音来治疗她伤痕累累的内心，随着时间的推移，他慢慢的爱上了这个脆弱的女孩。©豆瓣', '章若楠', '落落', 3.9, 47535, 'tt13154372', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2627432193.jpg', 40.5, 35.9, 16.7, 4.3, 2.6, '0.222324,0.450122,-0.931039,0.787950,-0.280778,-0.039647,1.045717,0.022219,-0.599650,-0.082085,0.292857,0.779010,-0.061470,0.458578,-0.142712,0.084836,-0.203955,-0.771102,-0.235314,-0.148211,-0.640421,-0.342736,-0.533052,-0.177840,-0.392470,-0.395095,0.901557,0.211344,-0.182004,0.376405,0.284668,0.239522,0.120229,0.515282,-0.531763,-0.205125,-0.190438,-0.225449,-0.081902,0.302047,0.243841,-0.403936,0.251065,0.487343,-0.127267,0.286786,0.800778,-0.614807,-0.148750,0.155485,0.377130,-0.418639,-0.060518,0.193700,0.103176,0.076748,0.413502,0.028487,-0.532991,-0.029160,0.102314,0.000334,-1.274022,-0.141653,0.179264,0.396325,-0.758627,0.593930,0.002590,-0.023741,0.029541,-0.466479,0.214536,0.375903,0.122144,0.468510,-0.634661,-0.033404,-0.369071,0.046092,0.749754,-0.006081,-0.347244,0.514523,-0.534885,-0.332698,-0.323848,-0.489215,-0.664799,-0.286078,0.294205,0.287342,-0.418153,0.231196,-0.483850,0.350626,0.027571,-0.167899,-0.313498,-0.513512,-0.155165,-0.337190,-0.280334,-0.625890,-0.404055,0.128830,-0.050842,-0.471280,0.922387,-1.096246,0.345171,0.801962,0.447753,-0.371806,0.683573,0.433639,0.105563,0.053447,-0.157781,0.465953,-0.106604,0.350266,0.202782,0.465894,-0.079892,0.337886,-0.803235,0.924448', '1793491', '25928048', '3769423', '1303077');
