INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3346365', '摩天大楼', '剧情', '在一所与世隔绝的高层公寓中住户之间的阶级斗争与暴力事件。这一座高级公寓共40层，拥有超过2000套独立的套房，超市、游泳池、小学等生活设施一应俱全，各楼层通过高速电梯连接，形成一个完全独立于外界的小社会。不过这个看似完美的世界异常脆弱，一次小小的停电以及琐碎的邻里纠纷就能引发冲突，随着冲突的不断升级，大楼里的人也分成了三个阵营：居住在底层的下等居民、居住在中间的中产阶级、以及坐拥高层豪华寓所的富人阶级。不同阵营的居民为了有限的公共资源开始暴力相向，文明世界的规则在这里已经不再适用，取而代之的是丛林法则。', '汤姆·希德勒斯顿', '本·维特利', 5.7, 17877, 'tt0462335', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2319772500.jpg', 6.1, 26.4, 46.8, 15.5, 5.2, '0.770544,0.347647,-0.906894,0.510883,-0.105819,0.221765,1.017495,0.301992,-0.387354,-0.145533,0.325491,0.587908,0.025215,0.193128,0.077513,-0.536100,-0.241750,-0.308825,-0.280466,-0.472039,-0.600497,-0.533348,-0.260597,-0.445678,-0.178761,-0.292214,0.826003,0.335284,-0.396503,-0.027917,-0.052148,0.153252,-0.529552,0.181537,-0.420172,-0.364745,0.148229,0.172491,-0.421976,0.142753,-0.736210,0.231050,0.214302,-0.106435,0.112714,0.166181,0.951748,-0.398298,-0.097479,0.083079,0.525215,0.380462,-0.397275,-0.131982,0.750734,-0.089480,0.350664,0.159803,-0.202585,0.452211,0.116259,-0.308300,-0.816537,-0.354790,0.254904,-0.082048,-0.193878,0.785352,0.362094,-0.574467,-0.105950,-0.157977,0.121788,0.426232,0.277280,0.778166,-0.162938,-0.030313,-0.533309,-0.216743,0.628473,-0.059529,-0.598863,0.278465,-0.594578,-0.485260,-0.390754,-0.424781,-0.342671,-0.404235,-0.108415,-0.028119,-0.018786,0.300974,-1.066196,0.493219,0.094316,-0.439530,0.172767,-0.315254,-0.283048,-0.917112,-0.126731,-0.390072,0.082713,0.431184,0.106192,0.155006,0.623321,-1.009842,0.073165,0.255954,0.749194,-0.581970,0.990772,-0.158318,0.465865,-0.043443,-0.098597,0.190360,0.006683,0.773608,-0.153836,0.563345,-0.340960,-0.057881,-0.485396,0.539594', '26586766', '2334814', '3055049', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3346464', '给朱丽叶的信', '剧情', '苏菲·霍尔（阿曼达·塞弗里德 Amanda Seyf 饰）是《纽约客》的调查员。她的未婚夫维克多为开餐馆忙碌着。他们来意大利的维罗纳旅行。不过，维克多却醉心于品尝美食，对她疏于照顾。两人感情因此矛盾丛生。苏菲闲逛到许愿墙下，发现很多人给朱丽叶写信。她很好奇，尾随取信的 妇女，发现有四位女士扮演朱丽叶，回信解答情感问题。苏菲被感动了，决定加入她们的队伍。她读到一封50年前的来信：克莱尔·史密斯（瓦妮莎·雷德格瑞夫 Vanessa Redgrave 饰）讲述了一段留有遗憾的当年情。苏菲用心地回了信。没想到，某天，老人的孙子查理（克里斯·艾根 Chris Egan 饰）找上门来。她这才了解，老人读了她的信，决定重拾真爱。但查理觉得这很荒谬。在争执中，三个人共同踏上了寻爱之旅……©豆瓣', '阿曼达·塞弗里德', '盖瑞·温尼克', 7.6, 80494, 'tt0892318', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p546362391.jpg', 0.4, 2.9, 31.4, 46.3, 19, '0.389911,-0.148934,-0.602892,0.399166,-0.069522,-0.300463,0.573877,0.039414,-0.618152,-0.220686,0.223105,0.560415,-0.170958,0.203658,0.455917,0.000792,-0.446586,-0.258159,0.340538,-0.349325,-0.034703,-0.561946,-0.062886,-0.207795,-0.097088,-0.194609,0.112992,-0.123446,-0.001684,0.484428,0.037503,0.240089,0.019563,0.438625,0.086134,0.400350,0.178858,-0.095754,-0.034545,-0.027008,0.065859,0.111136,-0.407539,0.185015,0.157642,0.479714,0.486426,0.100458,-0.198962,0.160033,0.214425,-0.212932,0.227846,0.107543,0.016257,0.233685,0.001280,0.105615,-0.125509,-0.126456,-0.120973,0.044391,-0.401477,0.363394,-0.053421,0.288465,-0.573170,0.420263,-0.318208,0.002327,-0.099197,-0.429622,0.016336,0.348529,0.299415,0.138953,0.272054,0.017846,-0.427840,0.068276,0.439149,-0.216621,-0.087195,0.368719,-0.217324,-0.198558,0.124197,0.197699,-0.562846,-0.063859,0.276847,0.054891,-0.058981,-0.011883,-0.444824,-0.213266,-0.332536,-0.120391,0.065404,-0.349073,-0.070986,-0.540566,-0.160644,-0.251191,-0.523832,-0.270642,-0.018185,-0.344461,0.711972,-0.652946,0.133424,0.653731,0.277686,-0.438691,0.652517,0.192859,-0.239828,-0.315388,-0.194152,0.720372,-0.003543,-0.093552,0.195652,0.331147,0.122278,-0.179574,-0.484016,0.281845', '1292720', '1298468', '1309172', '1300945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3346995', '夺命手机', '动作', '美国工程师彼德森(夏恩·韦斯特 Shane West 饰)意外得到一部手机，接收到一条神秘短信。他先是因为它躲过了一次空难，后来，又在赌场里利用手机给他的短信赢得了不少的钱。他在赌场的举动不仅引起了赌场头目约翰的注意，也引来了格兰特特工。表面上格兰特用诈骗罪将彼德森逮捕，实际上他知道凡是用过此种手机的人最后都会死掉，他就是负责调查这个案子的人。科技时代，每部手机，它拨打的电话、发送的信息、手机邮件都通过卫星得到其踪迹，只除了一部，这是一部世界上独一无二的手机,一部具有预测能力的万能手机，它让你得到一切，只要你能保住它。所有按照短信的指令去做的人，都将能得到意想不到的巨大财富。然而，这写短信也能让人深陷一个致命的阴谋当中。彼德森的命运将会如何？这部神奇的手机究竟隐藏着怎么样的秘密？©豆瓣', '夏恩·韦斯特', '格雷格·马克斯', 6.2, 14022, 'tt1124039', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p485167838.jpg', 1.9, 14.1, 58.8, 20.8, 4.4, '0.112806,0.356857,-0.467540,0.804117,-0.253395,0.209196,0.231898,-0.212121,-0.406504,-0.055461,-0.028853,0.630655,0.053977,-0.099025,-0.073619,0.114821,-0.513471,-0.476601,0.163620,-0.249470,-0.515946,-0.354875,-0.730069,-0.231662,0.366850,-0.148954,0.299314,0.229778,-0.447056,0.109205,0.197839,0.093429,-0.167566,0.698398,-0.109780,0.284607,-0.105621,-0.228531,0.089312,0.284369,0.198675,-0.478117,-0.058620,0.676643,0.081837,0.404806,0.463341,-0.222150,-0.346353,0.111078,0.439841,-0.051643,-0.129543,-0.248005,0.092311,0.341279,0.305013,0.254615,-0.541777,0.138194,0.289789,0.323432,-1.183313,-0.302190,-0.213483,0.243909,-0.174836,0.093345,-0.643849,0.214587,-0.068463,-0.445430,0.318044,0.132984,0.204484,0.274810,-0.284761,-0.102369,-0.594286,0.241440,0.323130,-0.167011,-0.081010,0.296543,-0.012220,-0.582295,-0.192992,-0.162116,-0.394822,0.345676,0.721490,0.211861,-0.169949,-0.040552,-0.446308,0.129224,-0.228798,-0.454707,-0.075605,-0.789856,-0.234396,-0.557538,-0.249341,0.214059,-0.471413,0.213491,0.152759,-0.307189,0.757851,-0.504811,-0.016640,0.654972,0.031483,-0.377095,0.611952,-0.018293,-0.041236,-0.206207,-0.055744,-0.054172,0.583574,0.621101,0.032480,0.067765,0.254399,-0.383697,-0.484846,0.567444', '3785918', '25932086', '30163500', '1793491');
