INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3356338', '喜羊羊与灰太狼之牛气冲天', '喜剧', '又是新的一年，灰太狼（张琳 配音）喜上加喜，和老婆红太狼（赵娜 配音）得了宝贝儿子小灰灰（梁颖 配音）。为了给至今未开羊荤的小灰灰打打牙祭，灰太狼再次踏上了前往羊村的征程。此时羊村正在举行百年庆典，但是村长慢羊羊的坐骑蜗牛突然出现异样，经验丰富的村长（高全胜 配音）马上意识到100年前的瘟疫将再次席卷青青草原。为了拯救羊村、替村长排忧解难，喜羊羊（祖丽晴 配音）他们利用缩小药水进入蜗牛的体内，而灰太狼也尾随而入。谁知他们却分别遭遇了白牛军和黑牛军，一场新的冒险由此展开……本片为动画片《喜羊羊与灰太狼》的首部电影版，并荣获2009第五届美猴奖最佳动画配音奖、中国电影华表奖最佳动画片奖、2009第六届金龙奖最佳动画长片奖等多个奖项。©豆瓣', '阿牛', '赵崇邦', 6.9, 37468, 'tt2193273', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1572534757.jpg', 3, 8.7, 43.8, 27.7, 16.9, '-0.187207,-0.099742,-0.351125,0.414393,0.260508,-0.342588,0.267976,0.064593,-0.143843,-0.202326,0.113236,0.863404,-0.533818,0.011401,-0.021993,-0.031127,-0.269360,-0.398766,-0.229140,-0.050449,-0.057633,0.074733,-0.311159,0.227429,0.027480,-0.021065,0.658986,-0.257054,-0.258836,0.602905,0.626480,-0.376415,-0.021172,0.070778,0.025361,0.284781,-0.068188,0.085640,-0.098779,0.457167,0.056211,-0.093808,-0.254867,-0.105922,0.085246,0.140034,0.878127,-0.298536,-0.091522,-0.238208,0.528587,-0.460643,0.005455,-0.115534,0.184211,0.126832,0.296665,-0.116566,0.036292,0.344957,-0.004494,-0.478257,-0.755787,0.405335,-0.151033,0.064337,-0.231936,0.110953,0.136024,0.178776,0.362521,-0.276191,0.170173,0.310604,0.435819,0.473923,-0.306356,0.284453,-0.174273,0.519372,0.446193,-0.060520,0.004248,0.434531,0.262201,-0.575036,0.159715,-0.120999,-0.162360,0.193628,0.527119,0.280405,-0.089292,0.049374,-0.734800,-0.080394,-0.085106,-0.486407,-0.052719,-0.110809,0.071414,-0.757061,0.085824,0.171475,0.113355,-0.098772,0.151737,-0.567499,0.663872,-0.516240,0.237645,0.494928,0.113472,-0.130852,0.466996,-0.164977,0.108364,-0.318555,0.026272,-0.184477,-0.034192,0.529294,0.268700,0.116887,-0.110706,-0.454403,-0.498829,0.390829', '26759820', '4135443', '1309194', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33591810', '无声', '喜剧', '昌福(刘在明 饰)和泰仁(刘亚仁 饰)表面上以卖菜为生，实际上两人还有另一个活计，就是为黑道组织提供杀人场所以及处理尸体，一日像往常一样在处理尸体的两人被组织中的金室长(林姜成 饰)胁迫，去接管一个被绑架的11岁女孩初喜(文胜雅 饰)，两人平静的生活随即被打破，事情开始向着他们无法控制的方向发展…', '刘亚仁', '洪宜廷', 7.4, 60813, 'tt10431572', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2563624277.jpg', 0.5, 3.8, 35.1, 45.2, 15.4, '0.432729,-0.174364,-0.373463,0.245882,-0.387613,0.168916,0.789054,0.246390,-0.391710,-0.433723,0.145068,0.635205,0.075406,-0.076721,0.166798,-0.177530,-0.205646,-0.823351,-0.146572,-0.229080,-0.164000,-0.292270,-0.163525,-0.344090,-0.115889,-0.102752,0.457014,-0.009706,-0.139530,0.785930,0.158823,0.582772,-0.338515,0.239497,-0.017886,-0.288569,-0.106595,0.083050,-0.166615,0.250308,-0.244606,-0.226669,0.053715,-0.168183,0.033519,0.645566,0.736166,-0.313418,-0.181081,-0.392754,0.127838,-0.108291,-0.092300,0.184558,0.476798,0.238865,-0.006416,0.493040,-0.397120,0.090510,0.347368,-0.323831,-0.598043,-0.094983,0.293862,0.406335,-0.798122,0.329618,0.236949,-0.130810,0.054130,-0.509746,0.289989,0.278711,0.372988,0.700065,-0.044229,0.033042,-0.480487,0.316001,0.701155,0.289030,-0.089207,0.226147,-0.002406,-0.019686,-0.034576,-0.344321,-0.019221,-0.194542,0.231294,-0.124034,-0.091443,0.094612,-0.676127,0.027335,-0.013042,-0.246972,-0.065565,-0.436615,-0.125245,-0.896414,0.178692,-0.265282,-0.096555,0.280830,0.011533,-0.324195,0.502730,-0.785481,0.020099,0.224868,0.387199,-0.842580,0.299155,-0.163786,0.249949,-0.423237,0.204697,-0.152931,0.375904,0.349136,0.068484,0.252095,-0.305628,-0.089872,-0.295628,0.273217', '26991880', '3147969', '25723905', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3364223', '了不起的盖茨比', '剧情', '1922年的春天，作家尼克(托比•马奎尔 Tobey Maguire 饰)满怀希望离开家乡，随淘金热潮来到纽约这个新兴的城市，虽然这里爵士乐流行，股票飞涨，但是贫富两极分化，人们沉沦在纸醉金迷中。尼克为了追寻美国梦，放弃写作而进入证券市场，并搬入纽约附近的海湾居住，成为了神秘富豪盖茨比（莱昂纳多•迪卡普里奥 Leonardo DiCaprio 饰）的邻居。而海湾的对岸住着尼克的表妹黛西（凯瑞•穆里根 Carey Mulligan 饰）和她的贵族丈夫汤姆（乔尔•埃哲顿 Joel Edgerton 饰），尼克不仅被邀请去赴宴，之后汤姆还带着他去找情妇寻欢，尼克渐渐迷失在这个充满魅力，以及富豪编制的假象、爱与谎言的世界中。但是只有盖茨比最特别，他是唯一让尼克感到在这个迷失城市里充满希望的人。尼克被邀请参加了盖茨比豪宅中的盛宴，还发现盖茨比心中的秘密，原来他一直深爱着黛西，即使她没等到他战后归来，转而嫁给富豪汤姆，盖茨比一直深信他们的爱情矢志不渝。尼克作为盖茨比与黛西爱情的见证者，终于在盖茨比被谋杀之后，看清了这个上流社会的虚情寡义，决心远离喧嚣、冷漠、虚假的大都市，黯然回到故乡……', '莱昂纳多·迪卡普里奥', '巴兹·鲁赫曼', 7.9, 596492, 'tt1343092', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2091221628.jpg', 0.4, 2.2, 23.5, 47.7, 26.3, '0.287431,0.017209,-0.744775,0.511694,-0.093460,-0.523159,0.904748,0.078651,-0.637137,-0.455334,-0.047591,0.936655,-0.136123,0.406708,0.391954,0.197810,-0.522455,-0.485691,0.053452,-0.247526,0.093001,-0.591281,-0.222252,-0.161667,-0.138390,-0.184552,0.561487,0.280869,-0.091077,0.557708,0.269964,0.279968,0.146219,0.583032,-0.322727,-0.017430,0.179434,-0.170056,-0.494490,0.335008,-0.027496,-0.109449,-0.129282,0.072460,-0.022343,0.168894,0.350680,-0.392295,0.106916,-0.059436,0.238847,-0.286274,-0.210125,0.156764,0.079743,-0.183712,0.074611,0.194148,-0.229242,-0.009541,0.128503,-0.230711,-0.490892,0.253938,0.264197,0.270195,-0.540210,0.217199,-0.087217,-0.065953,0.117876,-0.085740,0.376617,0.067842,0.155868,0.361323,-0.128127,0.124045,-0.698534,-0.003866,0.653789,0.079631,-0.118566,0.193825,-0.242645,-0.439748,0.146243,-0.288176,-0.523807,0.081829,0.074529,-0.057062,-0.111889,0.475150,-0.726514,0.019848,-0.156071,-0.379116,-0.034389,-0.487393,-0.233956,-0.799546,-0.236418,-0.407285,-0.004708,-0.105407,-0.069298,-0.406346,0.561348,-1.028500,0.292652,0.551105,0.484953,-0.361831,0.740717,-0.199957,0.033096,-0.251034,-0.236454,0.670627,-0.012024,0.188041,-0.233664,0.115233,-0.102589,-0.326161,-0.224757,0.749938', '1297239', '1308755', '3055049', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3369426', 'T省的84·85年', '剧情', 'T省机械总公司一分厂原是个年亏损四十万元的企业，1983 年，程戈与总公司签订了承包一分厂的合同，期限两年。他上任后，大刀阔斧进行改革，使工厂在五个月内就盈利二百万元，但到84年春，厂长程戈却向法院提起诉状，告总公司党委以权代法。法院受理此案后，经济审判庭庭长郭刚动承担了审理任务。而总公司党委得知程戈已上告法院，十分震惊纷纷出面要程戈撤回起诉，但遭到程戈的拒绝。这个案件表现简单，但牵扯到很多方面， 特别是被程戈开除的五名职工中，有一名是省委第一书记的小舅子。法院院长特别在开庭前告诫已被市委内定为下任法院院长的郭刚慎重行事，但郭刚则决心以法律为准绳审理此案。后法庭经多次调查，公开审理此案件，并判程戈胜诉。但到1985年秋，程戈在合同一到期后就被免去厂长职务，郭刚则被调到郊区法院“锻炼”。', '叶志康', '杨延晋', 8.7, 8869, 'tt5848704', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2502295836.jpg', 0.2, 1, 9.9, 41.1, 47.8, '0.018740,0.073017,-0.661558,0.334129,-0.053392,-0.257761,0.260721,0.327595,-0.538476,-0.140333,0.195058,0.425819,-0.095971,0.174363,0.542614,-0.246623,0.021664,-0.577934,-0.052037,-0.326916,-0.247874,-0.892463,0.409879,-0.100120,-0.330566,0.136551,0.522618,0.033788,0.066836,0.178419,0.216634,0.133367,0.102468,0.474500,0.155799,-0.255770,0.505991,0.030846,-0.199315,0.418276,0.304546,-0.313233,-0.202440,-0.119661,0.352659,0.609415,0.301806,0.202020,-0.668597,-0.149827,0.611422,-0.412777,-0.142677,0.306607,0.862483,0.552600,-0.116028,0.969959,-0.913491,0.013492,-0.063782,-0.400185,-0.664262,-0.225121,-0.203921,-0.095874,-0.615055,0.064019,-0.259590,0.495385,-0.415766,-0.396149,0.047251,0.513307,0.041531,0.511943,-0.213597,0.031435,-0.370600,0.280469,0.480695,-0.035686,-0.457597,-0.274979,-0.081753,-0.435856,0.045764,-0.215522,0.094261,-0.046538,0.018796,0.006267,0.036369,-0.137043,-0.285606,-0.416927,-0.252717,-0.445110,-0.208091,-0.143964,0.040948,-0.293854,-0.243623,0.098319,-0.399802,0.052495,0.466673,-0.203385,0.198846,-0.500827,0.008096,0.251096,0.480698,-0.840583,0.514579,0.359129,0.540528,-0.146009,-0.071107,-0.353775,0.368626,0.692379,0.046434,0.292962,-0.068173,-0.805279,-0.008541,0.035791', '1750027', '2042181', '1410695', '26996640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3369765', '空之境界 第六章 忘却录音', '剧情', '1999年1月，黑桐鲜花所就读的高级女子中学——礼园出现了神秘的事件。一年四班的学生橘佳织在宿舍起火事件中身亡，随后，一年四班全体同学的生活改变了。每天活在痛苦与烦恼中的她们，收到了不明来源的信件。不安的情绪在礼园全体学生间蔓延。为了解决事件，两仪式假扮学生潜入礼园，与黑桐鲜花一同调查事件的原委。另一方面，黑桐干也在使用自己的方法追踪事件的真相。而事件的背后，似乎还有那个男人，魔术师荒耶宗莲的安排。苍崎橙子之徒黑桐鲜花，拥有“直死之魔眼”的两仪式，魔术与战斗的交叉，礼园的秘密在她们面前展开。日本同人小说最高境界《空之境界》全七章动画化，本作为第六章电影版。©豆瓣', '坂本真绫', '三浦贵博', 8.3, 17239, 'tt1343089', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1957634133.jpg', 0.5, 2.1, 19.7, 38.6, 39, '0.321428,-0.133123,-0.423909,0.408811,0.065933,0.116517,0.633025,0.051723,-0.221227,-0.433956,0.313688,0.557399,-0.356461,0.198397,0.344884,-0.349390,-0.207105,-0.766975,-0.076838,-0.458747,-0.213335,-0.350517,-0.154982,-0.288375,0.043010,-0.361058,0.855971,0.253053,-0.099152,0.451964,0.259627,0.514523,-0.450869,0.170179,0.224907,-0.194978,0.237615,0.139329,-0.224754,0.174646,-0.059284,-0.500279,-0.118628,0.079766,0.139493,0.152256,0.929323,-0.222545,-0.228217,-0.270807,0.471046,-0.304551,-0.412571,0.020198,0.505041,0.120809,0.263471,0.431169,0.005808,-0.090965,-0.037369,-0.292901,-0.481910,-0.176346,0.152269,0.222863,-0.211669,0.260304,-0.017234,0.037156,0.372847,-0.107378,0.088372,0.353346,0.314070,0.447156,-0.290104,-0.125825,-0.267311,0.253607,0.458472,-0.126663,-0.210787,0.303206,-0.134856,-0.452483,-0.364554,-0.105767,-0.081258,0.195141,0.201074,0.212110,0.068279,0.587593,-0.557947,-0.332297,0.010085,-0.281377,0.178640,-0.091254,-0.334504,-0.899951,-0.035906,-0.098674,-0.392532,-0.078266,0.398637,-0.350979,0.727842,-0.891406,0.306859,0.421245,0.051951,-0.520794,0.578676,0.112109,0.385745,-0.202167,-0.367480,-0.041511,-0.196115,0.447018,-0.017141,0.315540,-0.039903,-0.044134,-0.442261,0.279992', '2369613', '5403927', '3811356', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3387483', '特警判官', '动作', '未来世界，地球爆发了惨绝人寰的核战争。曾经显赫一时的超级大国美利坚合众国，也在连番的自戕战争中灰飞烟灭。现如今，以当初华盛顿等地为中心，高高的围墙将被核污染的大地隔绝在外，仅存的8亿人类生活在这名为超级城市一号的封闭空间内。只是人类从来不曾吸取教训，各种恶性犯罪层出不穷 ，鲜血染红大地。在此期间，名为“特警判官”的一群暴力机器得到确立，冷酷干练的Dredd（Karl Urban 饰）即是其中一员。他接手新人卡珊卓·安德森（Olivia Thirlby 饰）的培训评审工作，与之一同调查城市中似乎永无止境的恶性案件。围绕着各种罪案，超级罪恶女头目“马-马”（Lena Headey 饰）浮出水面，成为这对特警搭档面前最大的对手……©豆瓣', '卡尔·厄本', '皮特·特拉维斯', 6.5, 35567, 'tt1343727', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1679624292.jpg', 2.4, 12.3, 51.3, 26.2, 7.9, '0.049910,0.090437,-0.745681,0.625834,-0.057831,0.168478,0.689213,-0.108978,-0.524291,-0.168129,0.362986,0.656930,-0.159951,-0.075596,0.373130,-0.393399,-0.017822,-0.745201,-0.560830,-0.163504,-0.476763,-0.265308,-0.584699,-0.145528,-0.165408,-0.284814,0.900809,0.247348,-0.163656,0.203558,0.230247,0.409052,-0.231032,0.135072,-0.344850,-0.266859,-0.002919,-0.080039,-0.395188,0.032422,-0.450362,-0.145575,0.257919,0.047079,-0.166762,0.061256,0.669289,-0.548051,0.059717,-0.574530,0.406705,-0.364187,-0.062775,-0.089442,0.553703,0.207850,0.197554,0.312463,0.001511,-0.066001,0.197568,-0.147957,-0.795253,-0.200118,0.169080,0.103864,-0.322786,0.209632,0.163288,-0.238085,-0.018427,0.210459,0.159193,0.173529,0.335395,0.388723,-0.143064,0.233668,-0.368076,0.259546,0.417441,0.043188,-0.365527,-0.085881,-0.256415,-0.381699,-0.144097,-0.443905,-0.202277,-0.190303,-0.003506,0.010390,0.016526,0.539512,-0.739631,0.111492,-0.099104,-0.336119,0.011039,-0.196778,-0.415258,-0.748018,-0.240094,-0.277532,0.029236,0.179177,0.076007,0.017151,0.536032,-0.844286,0.131820,0.242227,0.322289,-0.362922,0.410771,0.072739,0.231508,-0.295879,-0.223606,0.317526,0.231676,0.517817,-0.144770,0.215172,-0.028286,-0.172753,-0.284792,0.493320', '26759819', '5308201', '25774050', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3387546', '名侦探柯南：漆黑的追踪者', '动画', '一年一度的七夕即将到来，东京、神奈、静冈、长野等地却接连发生六起连环杀人案，被害者身边皆留下麻将牌中的七筒和奇怪暗示。由于作案范围过大，各地警署探员纷纷聚到东京警署的专案组共同研究案情，毛利小五郎也被邀请参加，柯南则偷偷听取了会议的内容。会后，柯南无意中听到群马县警部山村操哼唱的童谣，继而发现有黑衣组织的成员混进警察中间。在一次围捕行动中，柯南遇到假扮人质的Vermouth，得知近期一连串的杀人案件与存有组织内部人员资料的记忆卡有关。与此同时，潜入警察内部的间谍偷偷盗取工藤新一和柯南的指纹，新一的身份眼看被拆穿，巨大的危险正向他和身边的人急速袭来……©豆瓣', '高山南', '山本泰一郎', 7.6, 95630, 'tt1343046', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453744999.jpg', 0.4, 3, 33.9, 44.2, 18.6, '0.592117,-0.189628,-0.699485,0.361101,0.192919,0.100854,0.575580,-0.210237,-0.521623,-0.365898,0.342978,0.665171,-0.373618,0.102463,0.445400,-0.209659,-0.333849,-0.950214,-0.398450,-0.255213,-0.474024,-0.428111,-0.133773,-0.076585,0.146933,-0.090621,0.192367,0.243388,-0.212786,0.844228,0.273001,0.536277,-0.692169,0.388058,0.181163,0.011099,0.471552,-0.091309,-0.075838,0.339164,-0.026939,-0.522991,-0.080083,0.121281,0.101328,0.633744,0.665532,-0.276148,-0.050690,-0.145642,0.215330,-0.225051,-0.248245,-0.004240,0.879923,0.400568,0.084870,0.358653,-0.261482,-0.057767,-0.158048,0.017995,-0.655226,0.049786,0.305199,0.431757,-0.018934,-0.004199,-0.133765,-0.000759,0.387481,-0.086850,0.280007,0.447941,0.349633,0.085817,-0.170186,0.075056,-0.330194,-0.031423,0.422007,-0.016665,0.082557,-0.346969,0.043746,-0.253156,0.027837,0.080739,0.129059,0.029882,0.263537,0.085603,-0.217823,0.024038,-0.450422,-0.038828,-0.168163,-0.366627,0.117324,-0.217237,-0.294476,-1.129528,0.145669,-0.078335,-0.066637,0.261127,0.130546,-0.005552,0.496642,-0.826409,0.037242,0.716471,0.312305,-0.223535,0.284383,0.009358,0.026777,-0.164843,-0.106442,-0.361940,0.503255,0.706887,0.123491,0.226377,-0.118024,-0.579004,-0.341138,-0.258333', '25723905', '6984051', '2357711', '26788667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3389558', '气喘吁吁', '剧情', '中年男人李强（葛优 饰）陷入了事业与家庭以及自身的三重麻烦：公司陷入三角债的泥潭，讨债的天天上门坐办公室里，欠债的经常约出去唱歌，白吃白喝白玩，可就是不跟他提还钱的事；家里老婆疑心他跟女秘书（林熙蕾 饰）有染，儿子（陈柏霖 饰）从美国回家度假，跟个哑巴一样，一句话都不说；他自己经常头痛，检查发现脑部有阴影，可能是癌。为了让整个生活有转机，也为了在自己可能死后给家人铺好后路，他决定要购买Frank（John Savage 饰）祖传的奶酪公司。年过半百的Frank自有另一番不为人知的光景，祖传的公司入不敷出，跟妻子离了婚，女儿又进了戒毒所，于是挺儿走险企图来中国卖掉自己一文不值的公司然后逃之夭夭。两个不同种族但又同样处于困境中的中年男人都渴望能解决自己遇到的问题，而现在又发生了千丝万缕的联系，而身边出现的女秘书、爆矿老板（刘桦 饰）等人物也都各有不为人知的心病，大千世界里的这些芸芸群生们将何去何从？', '葛优', '郑重', 4, 16916, 'tt1343717', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2873882668.jpg', 40.8, 30.8, 19.3, 6.2, 2.9, '0.260158,-0.148111,-0.542570,0.239116,-0.249566,-0.312051,0.624992,0.348608,-0.511540,-0.248163,0.005026,0.680285,0.149627,0.341779,0.009160,0.007139,-0.262772,-0.641426,0.196364,-0.207866,-0.335920,-0.406161,-0.199479,-0.183943,-0.148535,0.034165,0.185516,-0.038289,-0.217143,0.038108,0.331092,0.269620,-0.058626,0.501233,-0.280698,0.034731,-0.250552,0.348588,-0.242899,0.050957,0.198506,-0.004113,-0.079070,0.133267,0.262592,0.324019,0.381447,0.157205,-0.158755,-0.020973,0.251844,-0.057472,-0.158059,0.090942,0.350577,0.035023,0.473346,0.149135,-0.311459,-0.006615,0.218759,0.083008,-0.714718,0.022481,0.064654,0.133218,-0.631123,0.194095,0.116725,-0.210302,0.077226,-0.236404,0.415621,0.508804,0.349288,0.431459,-0.167954,0.007481,-0.730562,0.205148,0.554526,-0.149586,0.025996,0.305582,-0.037886,-0.143973,0.041325,-0.212624,-0.432116,-0.101699,0.011425,-0.023850,-0.303292,0.057476,-0.520505,0.173700,-0.147154,-0.138686,-0.120232,-0.540703,-0.026425,-0.153460,-0.228044,-0.345836,-0.339894,0.206837,0.389091,0.020269,0.542099,-0.514114,0.122150,0.434409,0.402849,-0.835315,0.653295,0.082655,0.237518,-0.318910,-0.047182,-0.136689,-0.008620,0.271088,-0.003980,0.137309,0.075487,-0.154418,-0.263553,0.138235', '321509