INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3389591', '四头狮子', '剧情', '四个生活在英国的穆斯林青年：奥马尔（Riz Ahmed 饰）、白人巴里（Nigel Lindsay 饰）、瓦伊以及费萨尔正在用一只玩具枪做道具拍摄圣战视频，献身圣战是他们狂热的梦想。奥马尔厌倦了巴里那吃电话卡避免被追踪的无厘头理论，与瓦伊远赴巴基斯坦的穆斯林游击战士训练营学习，奥马尔和瓦伊的苦逼训练生活很快因为误打战友而终止了；留在英国的巴里物色同志，找到了在公开场合质疑英国时政的阿拉伯青年哈桑，一起和使用变声大法收集过氧化剂制造炸弹的费萨尔研制炸弹。回国的奥马尔谎称接到制作炸弹的任务，将其他人置于自己的控制下。费萨尔由于失手被炸身亡，剩下的四名穆斯林战士将目标锁定在伦敦马拉松上……©豆瓣', 'Preeya Kalidas', '克里斯多夫·莫利斯', 7.7, 9496, 'tt1341167', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p584639477.jpg', 1.1, 3.9, 25.8, 48.8, 20.4, '0.320981,-0.304640,-0.381657,0.431477,-0.164093,-0.107475,0.544576,-0.059252,0.012034,-0.273223,0.247966,0.653865,-0.148581,-0.150100,0.296242,-0.151719,-0.422998,-0.668075,-0.097476,0.094209,-0.311660,-0.591954,-0.183824,-0.412352,-0.124592,-0.575709,0.774255,-0.230145,-0.263858,0.463521,0.135757,0.403352,-0.091138,0.244381,-0.170729,-0.170155,0.214909,-0.473918,-0.249552,0.507618,-0.046763,-0.137182,0.209278,-0.054551,0.217883,0.405196,0.590705,-0.126647,0.206742,-0.240987,0.116088,-0.399588,-0.004628,0.089345,0.101385,0.280436,0.049810,-0.138589,-0.125695,0.123251,0.148474,-0.098046,-0.573106,-0.081421,0.071199,-0.056477,-0.538212,0.591107,-0.347565,0.127023,0.215048,-0.134009,0.379550,0.466300,0.118918,0.324035,-0.120486,0.062290,-0.572201,0.296178,0.428430,-0.451915,-0.300292,-0.048210,-0.003380,-0.306354,0.219382,-0.179680,-0.139887,-0.170200,0.290107,-0.213428,-0.054418,0.197414,-0.706223,-0.034782,-0.344258,-0.378859,0.255600,-0.159466,-0.131671,-1.009037,-0.016661,-0.168506,-0.454512,0.005875,0.142884,-0.015783,0.728494,-0.556443,0.279234,0.577019,0.232565,-0.332825,0.341744,0.087931,0.228122,-0.173003,-0.108464,0.376350,0.437671,0.534415,0.335468,0.377164,-0.129588,-0.074542,-0.515650,0.335891', '2369613', '20274039', '1307897', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3391271', '机动部队—同袍', '剧情', '森（任达华 饰）和May（邵美琪 饰）各自带领的机动小组成员间争强好胜，May的小组得到何长官赏识，娇纵傲慢，森一队心有不服，却无可奈何。机动小组即将解散，但在执勤的最后一天发生一起抢劫案，劫匪逃入荒山。两支小组并为一队上山展开地毯式搜查。期间各种离奇状况不断，加上彼此矛盾重重，致使森和May分头行动，却遭遇诸多险阻。另一方面，为队员送饭的肥棠（林雪 饰）汽车抛锚，结果遭遇劫匪。官兵与强盗在山中展开了一场怪异惊险的捉迷藏游戏，而PTU同事间的友情也受到了考验……©豆瓣', '任达华', '罗永昌', 6.5, 11979, 'tt1344008', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p793188362.jpg', 2.1, 10.8, 54.8, 26.7, 5.7, '0.298166,-0.194791,-0.643647,0.438898,0.458262,-0.045490,0.587296,-0.169258,-0.699413,-0.306276,0.320705,0.413397,-0.345938,-0.048608,0.180037,-0.574905,-0.282635,-0.716456,-0.153160,0.038530,-0.372745,-0.382728,0.114754,-0.417896,0.280925,-0.176463,0.616382,0.523885,-0.055612,0.735088,0.402426,0.253624,-0.856607,0.543407,0.226808,-0.168059,0.382450,-0.033711,-0.271025,-0.227777,-0.098692,-0.287630,-0.473690,-0.124011,0.252782,0.584522,0.977206,-0.285196,-0.479882,-0.037882,0.042414,-0.299935,0.060313,-0.055365,0.732409,0.296595,0.033145,0.321938,0.187654,0.246634,-0.352946,-0.004598,-0.529749,0.015149,0.160794,0.013789,-0.506247,0.442406,-0.082615,0.125984,0.152387,0.020589,-0.009650,0.574285,0.504520,-0.031019,-0.167182,-0.268448,-0.388593,-0.194952,0.967056,-0.092839,0.076330,-0.034712,-0.225030,-0.396047,-0.021519,-0.087101,-0.396588,-0.112525,0.176624,-0.122004,0.029310,0.216608,-0.751454,0.239995,-0.438653,-0.036648,-0.326060,-0.335317,0.009533,-0.941466,0.383191,-0.262193,-0.266684,0.713139,0.036481,0.061345,0.450424,-0.779167,0.026041,0.330421,0.083799,-0.475349,0.228464,0.037294,0.214458,-0.196962,-0.193464,-0.019312,0.299720,0.080125,0.408870,0.249158,-0.422722,-0.124767,-0.074094,-0.232717', '1292846', '3147969', '1507140', '1305179');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3392569', '早间主播', '剧情', '电视节目制作人贝琪•弗勒（瑞秋•麦克亚当斯 Rachel McAdams 饰）最近可谓灾星附体，霉运连连，不仅被炒鱿鱼，还和男友分手。但好在柳暗花明又一村，贝琪幸运的获得了《晨间秀》节目组的邀约，这是一档面向全国播出的晨间新闻类脱口秀节目。贝琪看似开始行大运，实则不然。这节目的收视率近来连连下滑，完全是一烫手山芋，被丢在了贝琪手里。性格倔强不服输的贝琪决定在节目组来个大改革。因此，她决定不计代价地邀约传奇节目主持人迈克•波默罗伊（哈里森•福特 Harrison Ford 饰）。但性格难搞且对当下新闻节目颇多微词的迈克自是不肯欣然接受。在几经波折下，迈克总算被贝琪说服，不甘愿的成为改组《晨间秀》的一员大将。但新的问题随即而来，和迈克搭档主持的是风格极不相像的科琳•佩克（黛安•基顿 Diane Keaton 饰）。二人间硝烟四起剑拔弩张，让贝琪两头为难。而在生活中，贝琪邂逅了新的恋情，但工作与爱情似乎都无法平稳进展，波折连连……', '瑞秋·麦克亚当斯', '罗杰·米歇尔', 7.7, 44598, 'tt1126618', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p689627900.jpg', 0.3, 2, 29.7, 50, 18, '0.171273,0.100761,-0.573862,0.449988,0.084916,-0.257450,0.466081,0.274652,-0.302873,-0.042486,0.058597,0.682095,-0.601960,-0.008791,0.302460,-0.144242,-0.263102,-0.550202,-0.081503,0.115697,0.097018,-0.622141,-0.108054,-0.089340,-0.069246,-0.219920,0.560695,0.040917,-0.123829,0.396772,0.588825,0.216686,0.171064,0.565529,0.046959,0.101411,0.203795,0.010685,-0.079791,0.243778,0.260577,-0.211077,-0.257835,0.345594,0.308607,0.425558,0.501513,-0.217968,-0.182357,0.163812,0.521078,-0.167552,-0.037891,0.139658,0.224534,0.192630,0.366029,0.355237,-0.046724,0.039452,0.150652,-0.230536,-0.493387,0.285863,0.180858,0.117024,-0.422245,0.492340,-0.225570,-0.221936,-0.197198,-0.260101,0.043968,0.348639,0.626357,0.208212,-0.048395,0.228053,-0.325928,0.041988,0.558886,0.280531,-0.294548,0.594417,-0.329672,-0.417414,-0.177386,-0.246212,-0.507078,-0.007918,0.259532,-0.097546,0.053865,0.264130,-0.417926,0.011351,-0.246218,-0.020810,-0.265808,-0.397197,-0.118062,-0.642907,-0.129646,-0.437056,-0.359124,-0.047181,0.240843,-0.161864,0.642000,-0.706612,0.021453,0.417502,-0.129150,-0.196138,0.498019,0.298379,0.091119,-0.154461,-0.171047,0.014908,-0.292627,0.026609,0.330755,0.396861,0.145970,-0.638373,-0.21953