INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3393386', '咒怨2 录像带版', '恐怖', '由于俊雄多日未到学校上课，他的班主任小林俊介（柳忧怜 饰）赶来家访，看到精神恍惚、举止怪异的俊雄，并获悉川又伽椰子对自己的心意。这时他接到佐伯刚雄的电话，得知怀孕的妻子已被对方残忍杀害，与此同时，被杀死的伽椰子也出现他的面前。惨案不久，通灵者铃木响子（大家由佑子 饰）受经营地产中介的弟弟达也（芦川诚 饰）之托调查佐伯家房子的情况。响子向弟弟提出忠告，但她很快便发现厄运已经找到她和侄子信之的头上。另一方面，购买这幢房子的北田夫妻也开始了他们恐怖诡异的生活。咒怨不灭，死者连连……本片为咒怨系列OV版第二部。©豆瓣', '大家由祐子', '清水崇', 7.7, 7836, 'tt0330501', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2230105669.jpg', 0.9, 4.1, 29.1, 40.4, 25.6, '0.308268,-0.034272,-0.390079,0.132456,0.069584,-0.175920,0.545045,0.150845,-0.163081,-0.501907,0.190821,0.647241,-0.272551,0.237384,0.138396,0.159681,-0.186494,-0.470119,0.090024,-0.042852,0.004602,-0.280501,0.012243,-0.136629,0.123431,-0.013280,0.372163,0.124674,-0.110305,0.505872,0.084766,0.530061,-0.150102,0.320686,0.120918,0.357036,-0.006357,-0.116884,-0.046907,0.120819,-0.084554,-0.362670,0.048761,0.376144,0.080279,0.576134,0.659776,0.051506,-0.609646,-0.175401,0.438170,-0.085405,-0.003282,0.142431,0.538859,0.082589,0.182192,0.361946,-0.291744,-0.267141,-0.117265,-0.086230,-0.624428,0.205118,0.152812,0.032392,-0.317650,0.233667,-0.242419,-0.006515,0.091417,-0.388832,0.163236,0.348010,0.138245,0.419621,-0.491663,0.019970,-0.313904,-0.049065,0.373177,-0.145439,0.069383,0.187716,0.033284,-0.299835,0.071827,-0.102716,-0.337952,0.267831,0.160808,0.240250,-0.095420,0.052067,-0.288097,-0.399847,-0.298402,-0.181740,0.147028,-0.289077,-0.143647,-0.644682,-0.187980,-0.202265,-0.632577,-0.132892,0.149553,-0.151441,0.445726,-0.688588,0.145013,0.445895,0.522872,-0.220596,0.304044,-0.129140,-0.171048,-0.293450,-0.068009,0.141096,0.238255,0.384628,0.359032,0.120349,0.137444,-0.356794,-0.392143,0.215257', '2369613', '24753685', '25723905', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3395373', '蝙蝠侠：黑暗骑士崛起', '剧情', '检察官哈维·登特（艾伦·艾克哈特 Aaron Eckhart 饰）死后的八年间，哥谭市在戈登警长（加里·奥德曼 Gary Oldman 饰）的努力下有效地遏制了犯罪活动。而蝙蝠侠布鲁斯·韦恩（克里斯蒂安·贝尔 Christian Bale 饰）因为背负谋杀登特的罪名，被 警方通缉，在哥谭市销声匿迹。然而，这看似平静的状态被恐怖分子贝恩（汤姆·哈迪 Tom Hardy 饰）的出现打破，他利用猫女（安妮·海瑟薇 Anne Hathaway 饰）偷取布鲁斯的指纹，致使韦恩集团面临破财，布鲁斯被赶出董事会。为了保证韦恩集团投资的能源项目不被坏人利用制造核弹，布鲁斯帮助米兰达（玛丽昂·歌迪亚 Marion Cotillard 饰）成为董事会主席。贝恩接下来一连串精密设计的计划将哥谭市陷入孤绝之境，毁灭之日指日可待。布鲁斯只能再次肩负起拯救哥谭的重任，然而至亲的管家阿福辞职离开、猫女的背叛、贝恩的凶残手段，爱人米拉达的真实面目露出，都让他拯救哥谭的行动变得不可能……', '克里斯蒂安·贝尔', '克里斯托弗·诺兰', 8.8, 673886, 'tt1345836', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1706428744.jpg', 0.2, 0.8, 9.3, 36.8, 52.9, '0.047866,0.216195,-0.462899,0.296321,-0.163964,-0.271167,0.381634,0.193962,-0.093016,-0.287068,0.369157,0.658285,-0.048759,-0.071366,0.314503,0.103616,-0.312276,-0.464644,0.059057,0.045027,0.057860,-0.584994,-0.265851,-0.402593,0.117140,-0.438116,0.651873,0.095889,-0.037868,0.121172,0.134278,0.679595,0.234834,0.198831,0.348840,-0.051576,0.386787,-0.421468,-0.302173,0.398149,0.144910,0.093754,0.214218,0.469036,-0.157879,0.267386,0.418481,-0.409736,0.113349,-0.284084,0.377391,-0.448566,0.076078,-0.033853,0.181385,-0.184722,-0.237012,0.522709,-0.407140,-0.197716,0.362309,-0.099936,-0.703775,-0.016327,0.052593,0.271289,-0.351356,0.109354,-0.537537,0.279727,0.130487,-0.168938,-0.039621,0.395417,0.599852,0.276832,-0.092995,0.424564,-0.589124,-0.135751,0.449610,-0.180692,-0.487149,-0.118563,-0.098242,-0.176481,-0.041365,-0.278661,-0.306753,-0.323724,0.299657,-0.203353,0.004248,0.530044,-0.455479,-0.380842,-0.605206,-0.007751,-0.202064,-0.321094,-0.108259,-0.698493,-0.039554,0.043988,-0.040968,-0.121090,0.041551,-0.350029,0.285557,-0.605911,0.256233,0.565568,0.300140,-0.267616,0.278267,0.073411,0.150433,-0.324861,-0.236148,0.528236,0.346700,0.220293,0.214208,-0.041415,0.188213,-0.145097,-0.057046,0.409101', '27073234', '25849049', '7916027', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3395437', '弟弟', '剧情', '东京一隅，温柔善良的高野吟子（吉永小百合 饰）独自打理着去世丈夫留下来的药店。过去的20年里，她和婆婆、女儿小春（蒼井優 饰）住在一起，虽颇多艰辛，但日子平淡幸福。如今，女儿将要嫁作人妻，吟子喜悦之余仍不免有所忧虑。原来在丈夫13周年忌辰上，她的弟弟铁郎（笑福亭鹤瓶 饰）醉酒胡闹，惹得亲朋不快。吟子和哥哥庄平（小林稔侍 饰）有意瞒着弟弟，然而得到消息的铁郎依旧欢喜前来，而且照例醉酒闹事。铁郎的举动不仅让家人颜面尽失，也影响了小春的婚姻。此后的日子里，这个年过半百却总也长不大的弟弟成为了姐姐久久无法割舍的牵绊……本片为日本国宝级导演山田洋次向市川昆致敬之作，受邀参加第60届柏林影展，并荣获电影节特别奖。©豆瓣', '苍井优', '山田洋次', 8.1, 11296, 'tt1345834', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p544551472.jpg', 0.5, 1.4, 19.7, 52, 26.5, '-0.232906,0.034973,-0.588762,0.281766,0.018570,-0.540886,0.409596,0.262890,-0.650531,-0.297382,0.144558,0.559618,0.034177,0.354244,0.188145,0.074719,-0.226349,-0.260275,0.039308,-0.054392,0.179478,-0.196032,-0.008505,0.068536,-0.244319,-0.301306,0.317050,0.025234,0.240611,0.717986,0.405267,0.111610,-0.166569,0.426667,0.148776,0.132012,0.043692,0.350582,-0.348325,-0.091009,0.002876,-0.285101,-0.236929,0.120897,0.175081,0.240074,0.510379,-0.100169,-0.232495,-0.171996,0.395144,-0.190930,0.054153,0.169987,0.177056,-0.010263,0.248346,0.348329,-0.212897,0.086597,0.055212,-0.014357,-0.285491,0.285571,0.446171,0.156683,-0.538887,0.563776,-0.107530,-0.058535,0.036268,-0.144307,0.133896,0.137309,0.051560,0.293978,-0.467366,0.389158,-0.299324,0.352191,0.516180,0.012057,0.085457,0.064728,-0.217946,-0.081851,0.296498,-0.566608,-0.732231,0.182752,-0.158811,0.028731,0.028178,0.388646,-0.075958,-0.087644,-0.078745,0.182122,0.084802,-0.324641,0.192577,-0.362164,0.266069,-0.464195,-0.440536,-0.125997,0.410862,-0.350640,0.669927,-0.497714,0.332518,0.323221,0.268830,-0.444044,0.557623,0.437356,0.106104,-0.189782,-0.239397,0.286947,-0.260430,0.036010,0.084139,0.036953,-0.134204,-0.233040,-0.173707,0.160874', '3445516', '1292720', '1291565', '1296897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3395460', '同门', '动作', '1996年，香港警方预备在回归前夕涤荡黑帮势力，营造法制环境，戴先生掌控的社团首当其冲在打击范围之内。是夜，戴先生社团五大堂主之一的占米被人暗杀，身中两枪生死未卜，占米之妻张桦（蔡少芬 饰）远在台湾，授意保镖伍宝（余文乐 饰）代理老大一职调剂各方关系，阻止老二黑水（杜汶泽 饰）向其他四位堂主寻仇，咖啡（黄贯中 饰）、木星、沙纸三位堂主闻风而动，在乱局中各有盘算。真实身份是警方卧底的伍宝当夜宿醉难耐，又要在短短几小时内周旋于社团、黑水与警方之间，暗恋伍宝的亚玲（江若琳 饰）跟随相助，但社团混战随时可能爆发。另一方面，掌握了真凶的警方暗中布置，趁机派出内应把事件复杂化以便将社团一网打尽……©豆瓣', '余文乐', '邱礼涛', 6, 13928, 'tt1345525', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2374044702.jpg', 3.6, 19.5, 55.9, 17.1, 3.9, '-0.049958,-0.040358,-0.253775,0.211384,0.176900,0.371723,0.039324,0.327785,-0.597419,-0.312482,0.306377,0.312928,-0.145408,-0.085291,0.279593,-0.488626,-0.103748,-0.798785,-0.152281,-0.294462,-0.047867,-0.366452,-0.376513,-0.283981,-0.051176,-0.189236,0.445021,0.114744,-0.325636,0.345984,0.251283,0.373173,-0.593846,0.146930,0.153069,-0.376260,0.254831,-0.293794,-0.579514,0.375297,-0.309744,-0.375317,0.129016,0.033426,0.291229,0.330248,0.534908,0.035287,0.025899,-0.170242,0.026743,-0.415486,-0.143294,-0.037131,0.861522,0.198910,0.062281,0.508338,-0.506045,-0.033278,-0.041582,-0.093073,-0.572212,0.096548,0.466961,0.209114,-0.354964,0.388054,-0.114733,-0.081470,0.034611,0.003604,0.185294,0.678468,0.048416,-0.082497,0.187650,0.194850,-0.498103,0.129112,0.650997,-0.226625,0.143565,-0.421411,0.323512,-0.126210,-0.203147,-0.197705,0.079978,-0.190496,0.271775,-0.213752,0.376718,0.218088,-0.321784,-0.176730,-0.206631,-0.035258,0.030405,-0.285598,0.197928,-0.743027,-0.268582,0.093432,0.105112,0.015700,0.350418,0.089788,0.516244,-0.749504,0.005191,0.449580,0.360207,-0.641470,0.471541,0.297526,0.279323,-0.326268,-0.208030,-0.335468,0.529693,0.209036,0.177341,0.266797,-0.178830,-0.444995,-0.153108,-0.604213', '26336253', '25723905', '1307914', '1298104');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33973066', '霍家拳之铁臂娇娃', '动作', '讲述了天生神力的少女阿暿被染了烟瘾的父母卖到上海滩做舞女，因给同乡姑娘荷叶打抱不平而招惹权贵，被卷入一场巨大纷争。而后她凭借一双铁拳扬名法租界，变身暿爷销禁鸦片，顽抗日商，惩恶扬善，成为被后人传颂的传奇女侠的故事。', '叶小开', '刘巴音', 4.2, 4514, '功夫阿暿(公映许可证)', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2611318255.jpg', 38.7, 26.9, 25.8, 5.4, 3.2, '0.249950,0.012831,-0.052280,0.327866,-0.050420,0.044047,0.360623,0.335803,-0.255667,-0.130483,0.254544,0.545361,-0.279075,-0.091114,0.232798,-0.105555,0.497074,-0.559963,0.146723,0.098217,0.165053,0.015777,0.033157,0.039671,-0.063544,-0.619883,0.343481,0.128025,-0.531203,0.007483,0.160621,0.143190,0.048047,0.082559,-0.278055,0.209513,-0.147588,-0.025802,0.016158,0.190440,-0.186239,-0.530024,0.123742,-0.127627,-0.212784,0.023298,0.802202,-0.413916,0.430210,-0.525811,0.385264,-0.246933,0.038219,0.265835,0.311687,0.169746,0.140228,0.071906,0.053338,-0.501004,0.327001,-0.181427,-0.289810,-0.118132,0.249788,-0.031701,-0.410574,0.304076,0.119006,0.013493,-0.217350,0.199369,0.255766,-0.168237,0.377782,0.081904,0.155902,0.216077,-0.653687,0.583251,0.561658,-0.110819,-0.089439,0.035772,-0.108839,-0.159980,0.220570,-0.614403,-0.448392,-0.184089,0.471601,-0.561100,-0.033103,0.566355,-0.613799,-0.307408,-0.358273,0.057035,0.125973,-0.313458,-0.272125,0.066541,-0.540325,-0.023545,0.157432,0.097844,0.497056,-0.040643,0.628230,-0.454698,-0.101689,0.638346,0.152607,-0.301195,0.637279,-0.217332,0.128712,-0.023034,-0.249752,0.167510,0.297785,0.252663,0.232923,0.178095,-0.267925,0.297173,-0.006648,0.125628', '3262050', '1302661', '3448362', '24751763');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33973077', '皮皮鲁与鲁西西之罐头小人', '喜剧', '皮皮鲁和鲁西西是一对双胞胎兄妹，鲁西西成绩优异，皮皮鲁调皮贪玩。有一天鲁西西在家里发现了一个奇怪的罐头，罐头里面出现了五个只有火柴棍高的小人，鲁西西给他们分别起名博士、上尉、艺术家、歌唱家、外交官。皮皮鲁与鲁西西这对兄妹在结识了五位罐头小人后，使他们的学习和生活发生了翻天覆地的变化，开启了一系列奇幻冒险趣事。', '洪悦熙', '于飞', 6.3, 13049, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2680748636.jpg', 4.2, 17, 47.1, 26, 5.7, '0.602285,-0.501923,-0.316791,0.505035,-0.031089,-0.096150,0.717559,0.051730,-0.690746,-0.249476,0.110088,0.812452,-0.583654,0.050914,0.108886,-0.133738,-0.233678,-0.809711,0.096084,-0.394529,-0.080396,-0.474277,-0.464435,-0.165262,0.113130,-0.491498,0.081688,-0.220047,-0.148133,0.983298,0.156203,-0.205832,-0.387743,-0.115442,-0.368633,0.578651,0.284634,0.255883,-0.262468,0.053500,0.124917,0.036287,0.000403,0.005558,0.290205,0.202615,0.823789,-0.376725,-0.398760,-0.193083,0.221840,-0.036196,-0.377059,-0.165884,0.578467,0.305587,0.177939,0.030459,-0.000792,0.046375,0.078127,-0.116719,-0.430560,0.008936,-0.071286,0.298314,-0.868020,0.643214,0.104057,-0.455583,0.338369,-0.033233,0.441418,0.420660,0.151211,0.459422,0.029423,0.044921,-0.521647,0.216658,0.542455,-0.121962,-0.206606,0.625743,-0.054762,-0.234139,-0.023136,-0.289246,-0.336811,0.235174,0.466890,-0.186361,-0.088772,0.263051,-0.764747,-0.006961,0.015833,-0.015892,-0.020047,-0.537821,-0.097429,-0.597733,-0.055401,-0.549905,-0.474084,0.215948,-0.033771,-0.381478,1.019666,-0.938470,0.053864,0.165680,0.067353,-0.504006,0.822918,-0.245045,0.311804,-0.318410,0.194453,-0.351091,0.056391,0.079086,0.179351,0.847544,0.042270,-0.229081,-0.516285,0.057383', '1292219', '3811356', '3155839', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33974174', '85年盛夏', '剧情', '亚历克西斯（菲利克斯·勒费弗尔 Félix Lefebvre 饰）是一位精力旺盛，向往自由的少年。一天，在独自出海的过程中，亚历克西斯遭遇了意外，所幸得到了大卫（本杰明·沃辛 Benjamin Voisin 饰）的出手相救才逃过了一劫。这次事件让两个少年迅速建立了深厚的友谊，他们一个放荡不羁古灵精怪，一个沉着稳重心思细腻，简直就是天作之合。然而，当一个名叫凯特（菲莉皮娜·维莱芝 Philippine Velge 饰）的女孩出现在两人的生活中时，亚历克西斯和大卫之间的关系开始慢慢出现裂痕。在一次激烈的争吵中，亚历克西斯负气出走，不放心他的大卫驱车在后面追赶，哪知道因此遭遇了车祸命丧黄泉。©豆瓣', '菲利克斯·勒费弗尔', '弗朗索瓦·欧容', 7, 15216, 'tt10457128', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2609300674.jpg', 1.2, 7.2, 44.2, 35, 12.4, '0.332266,0.069037,-0.783198,0.451180,-0.198548,-0.325201,0.732109,0.024636,-0.514139,-0.194709,0.355865,0.996291,-0.440117,0.084794,0.270060,0.096681,-0.316570,-0.642847,0.223046,-0.214896,-0.401844,-0.588741,-0.309628,-0.144733,0.029692,-0.579983,0.375166,0.025879,-0.023864,0.879843,0.367595,0.327014,-0.174451,0.449471,-0.154536,0.183701,0.312045,-0.051592,-0.111128,0.142775,-0.062663,-0.080142,-0.249035,0.241299,0.094884,0.459550,0.427373,-0.299712,0.004105,0.059243,0.195671,0.001080,0.041151,0.256830,0.318176,-0.197093,0.228097,0.270938,-0.464023,-0.137291,0.049446,-0.093799,-0.593307,0.200577,0.023159,0.380461,-0.569606,0.458946,-0.131264,-0.385804,0.147528,-0.107350,-0.018729,0.657749,0.484203,0.256020,-0.042793,-0.064728,-0.260590,-0.356792,0.773824,-0.094343,-0.326397,0.622214,0.063690,-0.103805,-0.178081,-0.008378,-0.300763,-0.084592,0.502320,-0.130212,-0.180973,0.487406,-0.490728,0.037064,-0.569127,0.158767,-0.374932,-0.098996,-0.348692,-0.474993,-0.028474,-0.423411,-0.406589,0.157915,-0.264871,-0.199507,0.534393,-0.621734,0.261296,0.516589,0.165337,-0.133594,0.595336,0.041345,0.276465,-0.169667,0.053969,0.461646,0.247626,-0.277276,0.221240,0.476517,-0.248901,0.010833,-0.214675,0.486199', '30162520', '3111650', '1297239', '1361252');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3397503', '未知死亡', '剧情', '电信大亨杰辛哈尼亚（阿米尔•汗 Aamir Khan 饰）为人低调，某日却见报纸爆料他向一个叫卡尔帕谢蒂（阿辛 Asin 饰）的小广告模特大胆示爱，气愤之余杰辛哈尼亚去向这个造谣生事的女孩儿问责，谁料他途中看见一个美丽善良的女孩机智地帮助残疾儿童，而这 个女孩就是卡尔帕谢蒂，卡尔帕谢蒂并不认识杰辛哈尼亚，一场误会令别人以为她就是大亨的女友。杰辛哈尼亚隐瞒身份接近卡尔帕谢蒂，可后者以为他不过是求广告机会的无名小卒。杰辛哈尼亚结识卡尔帕谢蒂后开始了扮演双重身份的生活，两人在相处中感情逐渐加深。卡尔帕谢蒂从黑帮大佬手中救出了25名少女，惹来杀身之祸。杰辛哈尼亚遭连累被击中头部之后只能保留十五分钟的记忆，为了爱人，他艰难的凭借有限的记忆复仇……©豆瓣', '阿米尔·汗', 'A.R.目虏古多斯', 8.2, 101533, 'tt1166100', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p480880157.jpg', 0.9, 2.7, 18.5, 43.3, 34.6, '0.175155,0.126635,-0.419182,0.479975,-0.270378,-0.293726,0.550906,-0.008154,-0.326056,-0.214393,0.091576,0.587846,-0.228208,0.014711,0.331208,0.074653,-0.229726,-0.653055,0.125667,-0.077931,-0.054317,-0.355195,-0.255475,-0.347397,-0.154727,-0.253529,0.374212,0.017834,-0.304330,0.222033,0.378835,0.265970,0.100644,0.257292,-0.000144,-0.028230,0.103432,-0.177721,-0.167395,0.215965,0.008845,-0.232907,-0.044070,0.175114,-0.101050,0.461892,0.426780,-0.069584,-0.020791,-0.234981,0.284104,-0.238848,0.130030,0.165055,0.206110,-0.061163,0.331811,-0.124470,-0.164728,-0.279347,0.186595,-0.160309,-0.554005,0.298682,-0.031448,0.162869,-0.408517,0.207855,-0.478864,-0.100335,0.067390,-0.163932,-0.000486,0.224818,0.268367,-0.000455,-0.071279,0.142416,-0.286092,0.054378,0.410011,0.199582,-0.146217,0.397350,-0.134282,-0.217962,0.214190,-0.116512,-0.464550,0.051207,0.184728,-0.204676,-0.012081,0.362211,-0.313193,-0.097944,-0.439999,0.107725,0.040668,-0.424397,-0.207048,-0.172837,-0.353337,-0.078692,-0.094951,-0.052093,0.024003,-0.349599,0.533449,-0.535954,0.091786,0.644710,0.338607,-0.519181,0.561152,0.224773,-0.214079,-0.232439,-0.135499,0.293937,0.219598,-0.039300,0.065726,0.030424,-0.110222,-0.249433,-0.116318,0.288539', '3785918', '4301278', '34890458', '30167633');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('33977979', '镇魔司：苍龙觉醒', '动作', '影片讲述了在赵王朝元武十七年，仙师降灵打破四百年历任传统，即将迎来六百高寿。因呼声盖过当朝天子，皇帝震怒，欲将之铲除。镇魔司张谦派明、暗两部兵分量两路上玉虚山，明监负责打探消息，暗监负责刺杀仙师降灵。两部人员宿来不和，矛盾累计颇多，此番相遇必有一番龙争虎斗。', '张亚奇', '霍穗强', 5.7, 3446, '', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2558838623.jpg', 5, 29.5, 43.9, 17.3, 4.3, '-0.190777,0.437673,-0.419737,0.404072,0.539830,0.252741,0.266185,0.096644,-0.504938,-0.657706,0.110506,0.178154,-0.467075,-0.292788,0.368686,-0.527689,0.056721,-0.264551,-0.249466,-0.132248,0.324235,-0.330221,0.009623,-0.187564,-0.228848,-0.539629,0.649349,0.529620,-0.153225,0.221905,0.269170,0.433494,-0.296620,0.272471,0.084580,-0.127740,0.227721,-0.174077,-0.305243,0.094384,-0.361269,-0.714972,-0.338864,-0.006131,-0.085071,0.305513,0.073245,-0.185062,-0.284434,0.016114,0.331105,-0.037531,-0.241304,-0.095297,0.651068,0.449445,0.037173,0.699066,-0.129326,-0.032727,-0.519214,-0.318151,-0.340398,-0.039318,0.578161,-0.100982,-0.413710,0.386230,-0.244843,0.113645,-0.199944,-0.056195,0.367306,0.958641,0.173074,0.258009,0.163544,-0.202991,-0.317397,0.235093,0.932213,-0.247022,0.321477,-0.486754,0.535018,-0.463298,0.202054,-0.212586,-0.058830,0.254081,0.434896,-0.231231,0.771787,0.548472,-0.208128,-0.190001,-0.423166,-0.040903,0.390069,-0.080479,0.406951,-0.595349,0.011584,-0.135115,-0.048325,-0.012157,0.826457,-0.143482,0.532873,-0.405795,0.067807,-0.176556,-0.013131,-0.709614,0.350792,-0.121725,0.030143,-0.475798,0.167570,-0.213919,0.251244,-0.029447,0.060589,-0.037901,-0.238196,-0.457112,-0.297396,-0.045735', '26852888', '1305970', '1302705', '1484760');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3399553', '空之境界 第七章 杀人考察（后）', '剧情', '1999年2月，杀人鬼回来了！1995年在日本发生的连续猎奇杀人事件，因嫌疑人遇到车祸住院而草草结案。如今疯狂的犯罪再次出现，恐怖的气氛来袭，原嫌疑人的嫌疑被洗清，到底谁才是这一系列事件的凶手？解决都市不可思议事件的伽蓝堂的成员开始展开调查，两仪式准备以自己的匕首结束这一切。但决战之前，黑桐干也发现犯人居然是自己旧日所识！在友情与正义相混淆的世界中，干也到底要如何抉择？日本同人小说最高境界《空之境界》全七章动画化，本作为第七章电影版。©豆瓣', '坂本真绫', '瀧沢進介', 9.1, 19143, 'tt1345776', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2202703811.jpg', 0.5, 0.8, 6.9, 28.2, 63.5, '0.238420,0.026745,-0.571545,0.080202,0.075446,0.077821,0.346158,-0.228462,-0.312408,-0.544912,0.342632,0.423575,-0.400136,-0.092734,0.310741,-0.422534,-0.115665,-0.760899,0.016132,-0.320705,-0.258636,-0.345004,-0.232285,-0.119619,0.155452,-0.035693,0.566742,0.368423,-0.077674,0.074205,0.523349,0.549919,-0.318678,0.274210,0.194067,-0.057996,0.032799,-0.014767,-0.365911,0.051989,0.067684,-0.472308,-0.213815,0.147245,-0.031504,0.262368,0.736629,-0.219754,-0.547156,-0.157545,0.666612,-0.506091,-0.371442,0.084242,0.510055,-0.009686,0.070642,0.696930,0.145777,-0.115046,-0.175612,-0.193977,-0.854452,0.054598,0.090200,-0.004973,-0.129507,0.024626,-0.128039,0.138557,0.075796,-0.098897,0.275737,0.638613,0.696251,0.477800,-0.245267,-0.238386,-0.510291,0.163969,0.776217,-0.087062,-0.317337,0.233869,0.330688,-0.508104,-0.290841,-0.525268,0.297109,0.335829,0.114938,0.077706,-0.216988,0.583135,-0.441733,-0.371141,-0.237734,-0.189438,-0.053336,-0.092741,-0.220545,-0.450021,-0.253233,-0.125798,-0.351696,-0.069394,0.245830,-0.406561,0.297011,-0.727651,0.253889,0.585865,-0.020656,-0.783986,0.356056,0.260290,0.098487,-0.163164,-0.419103,0.036191,0.082076,0.370245,0.061399,0.104309,0.150177,-0.098937,-0.251981,0.197802', '26678784', '34454693', '1293265', '3412882');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3399559', '南极料理人', '喜剧', '本片改编自曾任日本南极观测队厨师的西村淳根据自身经历创作的散文集《有趣的南极料理人》。本是海员厨师的西村淳（堺雅人 饰）被派往冰天雪地的南极圆顶富士基地为七名考察队员担任厨师，妻子（西田尚美 饰）只好独自抚养8岁的女儿和刚出生不久的幼子。在冰天雪地的南极寒地，吃，是考察队七位成员——冰河学助手川村泰士（高良健吾 饰）、气象学家平林雅彦（小浜正宽 饰）、通讯员西平亮（黑田大辅 饰）、医生福田正志（丰原功补 饰）、气象学家兼队长金田浩（古关安广 饰）、机师御子柴健（古馆宽治 饰）和冰河学家本山秀行（生濑胜久 饰）——枯燥生活中的最大乐趣。西村淳想尽办法烹饪各种各样的美味料理，而围绕着吃，八个寂寞的男人也演出无数令人忍俊不禁的生活趣事。本片获日本横滨电影节最佳男主角奖（堺雅人）。©豆瓣', '堺雅人', '冲田修一', 8.3, 81266, 'tt1345728', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p575432919.jpg', 0.2, 1, 15.6, 50.9, 32.3, '-0.100085,-0.441288,-0.236057,0.362339,0.092312,-0.129627,0.288551,0.458225,-0.541039,-0.269356,0.282411,0.709866,-0.070041,0.187586,0.242594,0.129538,-0.401579,-0.383830,-0.221052,-0.142582,0.053393,-0.148278,0.012199,-0.019215,-0.041675,-0.273034,0.575740,-0.109426,0.076994,0.320004,0.253955,0.380044,-0.248850,-0.084845,-0.204669,0.048595,0.304818,-0.193773,-0.203773,0.089001,-0.458873,-0.126384,-0.299337,0.030698,0.154667,0.218683,0.765463,-0.146731,-0.046411,-0.421168,0.014989,-0.218464,-0.153347,-0.064462,0.332109,0.081119,0.005353,0.130189,-0.183379,0.162915,-0.042144,-0.111094,-0.404048,-0.000800,0.347582,0.139585,-0.166717,0.154905,0.047376,-0.354901,0.270346,-0.141345,0.017929,0.028857,-0.025551,0.271582,0.070941,0.267086,0.007721,0.589299,0.323410,-0.238049,0.050163,0.072874,-0.014473,-0.363967,0.113812,-0.353606,-0.466981,-0.030768,-0.079191,-0.358373,0.339499,-0.042228,-0.506386,0.334043,-0.029017,-0.295202,0.179854,0.270952,-0.143736,-0.830845,0.437098,-0.321072,-0.127781,-0.098124,0.398260,-0.013039,0.792694,-0.288725,0.168031,0.362312,0.073537,-0.007720,0.381393,-0.140033,-0.012599,-0.308296,-0.101348,0.075133,-0.017531,0.255613,-0.150031,0.477348,-0.172680,-0.272381,-0.438330,-0.153748', '5403927', '3811356', '1322847', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3401409', '好雨时节', '剧情', '韩国年轻帅气的小伙子东河（郑宇成 饰）来到中国四川成都出差，在游览杜甫草堂时偶遇留学时相识的中国同学五月（高圆圆 饰），后者目前在杜甫草堂从事讲解工作。这次相遇，让两人的心再次碰撞出爱情的火花。他们回忆着生日派对的誓言、彼此亲昵的举动，甚至是关于自行车的留恋，但是两人却给出了不同的版本。他们相约在雨夜，共同品尝中国的菜肴。然而，当他对她主动作出爱的表白时，她却左躲右闪。由于公司安排，东河要离开中国。在雨中，他挽着她的手翩翩起舞，但是气氛似乎显得过于沉静，以至于他开始怀疑自作动情。但是，一场机场送别却让两人重新敞开了心扉……©豆瓣', '高圆圆', '许秦豪', 6.4, 26571, 'tt1477859', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p465526682.jpg', 2.5, 14.2, 51.1, 24.9, 7.2, '0.505882,0.262102,-0.995143,0.530056,0.104378,-0.345785,0.633304,0.343920,-0.524646,-0.021309,0.300873,0.545005,-0.236863,0.340427,0.240880,-0.005906,-0.316715,-0.826483,0.161578,0.042921,0.014845,-0.324461,0.052290,-0.073601,-0.153642,-0.045320,0.411244,0.231889,-0.240563,0.859109,0.060662,-0.056199,-0.107632,0.733828,-0.246172,-0.289858,0.134969,0.338937,-0.507102,0.004994,-0.015065,-0.337313,-0.465639,0.139233,-0.043529,0.413445,0.839682,-0.008511,-0.329665,0.221707,0.405485,-0.118805,0.059627,0.151696,0.080250,0.339058,0.254394,0.134204,-0.058425,0.067874,-0.147692,-0.055426,-0.305899,0.425928,-0.039549,0.187716,-0.554717,0.609408,-0.150165,0.071762,0.041168,-0.370103,0.259804,0.316487,0.429072,0.358776,-0.176694,-0.004384,-0.247202,0.243421,0.850737,0.045895,-0.226872,0.440304,-0.402373,-0.384033,0.008608,0.179743,-0.241256,0.076970,0.078191,-0.047298,-0.103796,0.175099,-0.645353,-0.023387,-0.097237,-0.133537,0.059704,-0.368302,-0.203218,-0.812885,-0.242971,-0.527651,-0.434514,-0.046240,0.084993,-0.061628,0.591753,-0.945627,-0.013244,0.531142,0.306628,-0.434606,0.722613,0.191779,-0.218075,-0.170820,-0.055819,0.380877,-0.330933,-0.004123,0.060528,0.531526,-0.127879,0.231872,-0.480032,0.257647', '1308384', '1298346', '26687241', '1301562');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3401684', '至暗之时', '剧情', '西恩（埃米尔·赫斯基 Emile Hirsch 饰）和本（麦克思·明格拉 Max Minghella 饰）是两个来自美国软件工程师，因为新开发了一款软件，跑去莫斯科谈生意，晚上去酒吧找乐，遇到从美国跑来旅游的娜塔莉（奥莉薇·瑟尔比 Olivia Thirlby 饰）和安（瑞切尔·泰勒 Rachael Taylor 饰），四个人调情玩乐，却遇上天降白光，大地浩劫，原来是以能量场形态出现的外星人入侵莫斯科，碰触的瞬间就能让任何生命体灰飞烟灭。四个美国年轻人及时藏身，夜晚来临后试图逃出一片涂炭的红场，他们发现电可以感应外星人存在，又找到一位在家里布上电磁阵的极客老头。大家齐心协力，试图找到所有幸存者，利用电磁学知识，对外星人反戈一击……©豆瓣', '埃米尔·赫斯基', '克里斯·格拉克', 5.4, 8943, 'tt1093357', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1354958367.jpg', 8.8, 30.4, 45.4, 12.1, 3.2, '0.142418,-0.116367,-0.470411,0.170028,0.030582,0.009008,0.439630,0.045542,-0.180226,-0.292199,-0.222026,0.644380,-0.366161,0.135854,0.127898,0.150654,-0.426423,-0.466436,0.242908,-0.092692,-0.295000,-0.198819,-0.207179,-0.196459,0.287888,-0.370053,0.272093,0.052606,-0.387044,0.147793,-0.005586,0.287433,-0.476015,0.528785,-0.096390,-0.341873,-0.000203,-0.293719,-0.141683,0.420097,-0.375024,0.006010,-0.034080,-0.047835,-0.007503,0.141793,0.518709,-0.007691,0.227314,-0.089161,0.236317,-0.017422,-0.082852,-0.089583,0.188459,-0.269419,-0.076272,-0.035876,0.010045,0.057105,0.091074,-0.213239,-0.624890,0.181843,-0.180746,0.073398,-0.330723,0.039680,0.025901,-0.097617,-0.048301,-0.324645,0.416902,0.454661,0.171079,0.295153,-0.011176,-0.015416,-0.592422,-0.066431,0.486526,-0.293808,-0.317417,0.279105,0.197970,-0.292678,0.021242,0.149085,-0.067437,-0.070106,0.290863,0.018024,-0.084228,-0.032950,-0.828217,0.118039,-0.437849,-0.247203,0.041144,-0.197599,-0.158389,-0.953774,-0.057197,-0.038477,-0.368320,0.213396,-0.002356,-0.050810,0.547735,-0.598141,0.104292,0.570869,0.349992,-0.344752,0.713511,-0.273897,-0.145683,-0.308364,0.024541,0.172043,0.275142,0.482645,-0.011418,0.195785,0.062717,-0.097658,-0.053783,0.107882', '3147969', '1307897', '1297659', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3401751', '嘿咻卡', '喜剧', '《嘿咻卡》出自专攻低速喜剧和厕所幽默的法拉利兄弟之手。Hall Pass是在美国和加拿大，学生使用的一种“特权卡”。当在上课或者是在讲座中，如果有特殊情况就可使用这种卡片就可以临时走出教室。里奇（欧文·威尔逊 Owen Wilson 饰）与弗雷德（杰森·苏戴奇斯 Jason Sudeikis 饰）是一对非常要好的朋友。他们虽有稳定的婚姻，但总也免不了幻想一番艳遇，对来来往往的女性充满了幻想。二人的老婆想出一个大胆的招数，给他们一个星期的特权，让他们放风一周，绝不过问他们的生活。当拿到七天的“嘿咻卡”后两人觉得美梦终于成真，和几位已婚的朋友过上了梦想中的生活。但是这样的自由快乐单生活却又带来始料未及的难过与痛苦。原来自由自在的生活一点也没有家庭生活愉快。发现了这些的里奇和弗雷德恍然大悟，开始拼命向家庭回归……©豆瓣', '欧文·威尔逊', '彼得·法雷里', 5.9, 8266, 'tt0480687', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p828202185.jpg', 3.4, 20.7, 56.4, 15.7, 3.9, '0.458330,-0.186037,-0.449530,0.578160,-0.200357,-0.261585,0.860894,-0.127148,-0.522406,-0.383872,0.028307,0.928054,-0.263773,0.363662,0.379408,-0.060216,-0.230652,-0.651628,0.193035,-0.117357,-0.398569,-0.390957,-0.205222,-0.297596,-0.202833,-0.324321,0.565984,0.040330,-0.113876,0.499239,0.202934,0.217476,0.077048,0.338535,-0.489092,-0.094376,-0.110469,0.324735,-0.483965,0.156733,0.079350,0.015243,-0.237913,0.190706,0.330959,0.105286,0.676276,-0.076343,-0.401064,0.268303,0.284987,-0.139712,-0.186430,0.090869,0.063632,0.028942,0.289839,0.137800,-0.097304,0.174309,-0.008958,-0.044631,-0.934724,-0.014615,-0.015595,-0.031753,-0.545079,0.537367,0.153739,-0.372329,0.089546,-0.207555,0.235490,0.470151,0.305455,0.653750,-0.282247,-0.006617,-0.663648,0.161308,0.706424,0.042255,-0.463586,0.612248,-0.437804,-0.376634,0.006682,-0.145852,-0.610092,-0.132103,0.109522,0.085888,-0.331771,0.171258,-0.645270,0.329431,-0.089518,-0.298893,0.101861,-0.718258,0.107957,-0.672424,-0.019422,-0.481569,-0.422805,0.248611,0.181339,-0.358434,0.825970,-1.133799,0.166874,0.323376,0.349976,-0.583423,0.768802,0.455025,0.111162,-0.189954,0.064432,0.048627,0.078350,0.175736,0.159102,0.398640,0.084968,-0.082167,-0.387756,0.562648', '1793491', '4301278', '4817024', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3402101', '危情谍战', '喜剧', '平凡无奇的美女汽车修理师茱恩·哈文斯（卡梅隆·迪亚茨 Cameron Diaz 饰）如何也想不到，她回家的路途竟会变得如此漫长而险象环生。最初，她一波三折登上了开往家乡波士顿的神秘航班，机上乘客寥寥，茱恩与在机场有过短暂接触并拥有迷人气质的陌生男子罗伊·米勒（汤姆·克鲁斯 Tom Cruise 饰）相谈甚欢。看起来一段浪漫美好的旅途恋情即将展开，谁知短短几分钟过后，机舱便被恐怖肃杀的氛围所替代。除罗伊外，所有乘客和飞行员全部毙命。原来罗伊的正体是一名训练有素、身手不凡的特工，他持有一枚重要的电池，而这也成为一众叛徒特工不择手段急于得手的主要原因。茱恩也许猜对了结局，却根本没有猜到过程。在接下来的日子里，她将和罗伊上天入地、周游世界，享受枪林弹雨、血雨腥风旅途中的浪漫与惊险……©豆瓣', '汤姆·克鲁斯', '詹姆斯·曼高德', 6.8, 58288, 'tt1013743', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p527629468.jpg', 1.2, 8.2, 49.1, 32.8, 8.7, '0.283872,0.142803,-0.807915,0.462475,-0.026808,-0.124811,0.944465,-0.203341,-0.520340,-0.344760,0.280822,0.570292,-0.335940,-0.055440,0.519651,-0.038100,-0.300735,-0.500288,-0.153313,-0.174582,-0.165679,-0.303381,-0.402348,-0.141796,0.204780,-0.417602,0.656349,0.376893,-0.041300,0.683579,0.218423,0.192984,-0.151088,0.504206,-0.064848,-0.114485,0.126802,0.267369,-0.300410,-0.008490,-0.148105,-0.333970,-0.037072,0.152401,-0.148981,0.262219,0.710300,-0.057332,-0.232116,0.260600,0.365910,-0.210785,-0.080707,0.033876,0.290649,-0.014497,0.096750,0.126821,-0.039954,-0.047013,0.005391,0.092740,-0.768504,0.151573,-0.144749,-0.022442,-0.150328,0.389652,-0.198722,-0.168828,0.065176,-0.176736,0.213420,0.270017,0.457559,0.111488,0.117731,-0.022328,-0.341892,0.317156,0.935114,0.029937,-0.652189,0.530286,-0.275990,-0.534442,-0.129875,-0.425411,-0.277346,0.061896,0.242409,0.084121,0.002741,0.180563,-0.363626,0.432429,-0.318073,-0.217285,-0.199399,-0.389943,-0.261133,-0.724506,-0.038440,-0.559538,-0.454946,-0.142965,0.023191,-0.092742,0.734974,-0.532258,0.178447,0.482879,-0.047064,-0.191910,0.536998,0.066201,0.159547,-0.149722,-0.124991,0.443763,0.151558,0.178636,0.067387,0.380046,-0.345473,0.173377,-0.434960,0.346690', '25721544', '2053515', '10466639', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3406467', '电影就是电影', '剧情', '在社团前途一片大好的姜培（苏志燮 饰）却有一个想要成为演员的想法，这个念头也让他日渐想摆脱社团黑暗的日子。动作明星苏达（姜志焕 饰）总是在电影里扮演流氓，厌倦虚构的情节的他总希望成为真正身手厉害的人物。在拍摄动作场面时，把两个跟自己配戏的演员打得住了医院。偶然的一天，苏达碰到了要求自己给签名的姜培，流氓和演员就这样相遇了。苏达向姜培提出希望由他来继续出演这部电影的请求。面对这样的机会，姜培愉快地答应了，但是提出在影片中要所有的打斗场面都是真实展示。在电影的拍摄过程总，姜培越来越享受当演员的感觉，对于角色把握得十分到位。而目睹了姜培在拍摄电影时出色发挥的苏达也产生了新的想法，似乎对演员这样身份产品了厌恶感……©豆瓣', '苏志燮', '张勋', 7.5, 18194, 'tt1345734', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2166630729.jpg', 0.5, 3.6, 34.3, 45.3, 16.3, '0.012020,0.023247,-0.549534,0.547506,0.103009,-0.112406,0.576663,0.238557,-0.391228,-0.256356,0.278542,0.774735,-0.406687,-0.045524,0.296710,-0.369145,-0.309834,-0.816491,0.004145,0.090871,0.058057,-0.182454,-0.346960,-0.257834,-0.021402,-0.486411,0.850979,0.210112,-0.550240,0.143398,0.342164,-0.088474,0.287187,0.531151,-0.073512,-0.216406,0.116429,0.143051,-0.362799,0.390442,0.105323,-0.174290,-0.313798,0.212119,-0.036416,0.260316,0.582504,-0.043915,-0.572158,0.330747,0.527813,-0.320961,-0.011747,-0.007767,-0.029056,0.010237,0.351187,-0.014211,-0.029643,0.128547,-0.127596,-0.143826,-1.112681,0.227782,0.255581,0.182633,-0.747927,0.230583,-0.125913,-0.105339,0.135398,-0.194532,0.109330,0.087566,0.524378,0.447249,-0.285910,0.188356,-0.310991,0.423959,0.673988,0.178123,-0.298533,0.654117,-0.263075,-0.537253,-0.356670,-0.220113,-0.354026,0.162594,0.161832,-0.114039,-0.369847,0.100691,-0.479212,-0.042644,0.058850,-0.198149,-0.052185,-0.590998,0.153852,-0.669084,-0.172472,-0.046703,-0.273031,-0.260722,0.084994,-0.481747,0.889941,-0.725295,0.037895,0.607289,0.263516,-0.593533,0.878657,0.399739,-0.163470,-0.234985,-0.051150,-0.219965,-0.138390,0.069045,0.116772,0.472192,-0.071324,-0.490408,-0.389548,0.585881', '27602116', '30279170', '1793491', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3412830', '狄仁杰之通天帝国', '动作', 'http://site.douban.com/108331/狄仁杰之通天帝国豆瓣小站武则天（刘嘉玲 饰）登基之前，修建了高达三百尺的通天浮屠。竣工之前，却先后发生命案：工部侍郎贾颐、大理寺卿薛勇（刘金山 饰）相继自焚而亡。监工沙陀（梁家辉 饰）称此二人因动通天柱之灵符而遭天谴。大理寺少卿裴东来（邓超 饰）、武后贴身侍卫上官静儿（李冰冰  饰）奉命调查，但国师陆离却指点此案需狄仁杰（刘德华 饰）查办。武后下旨，入狱八年的狄仁杰获释任钦差负责此案，却遭刺客袭击。所幸其早有防备，加之上官静儿陪护，得以脱身。狄仁杰排除了怀疑对象琅琊王李宵（姚鲁 饰），并拒绝了其对抗武后之约。狄仁杰发现，死者身中赤焰金龟之毒，遂带领裴东来、上官静儿夜访鬼市，希望从昔日太医汪驴口中获得真相，不想遭遇埋伏，疑似国师显身，杀手集结，令三人难以脱身。然而，一番缠斗之后，案情似乎有了水落石出的转机……', '刘德华', '徐克', 6.6, 262745, 'tt1123373', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2166635320.jpg', 1.5, 9.5, 52.4, 29.8, 6.8, '-0.024717,-0.090042,-0.417330,0.312559,0.128553,0.028575,0.446548,0.364075,-0.809233,-0.413316,0.656474,0.117831,-0.316942,-0.117233,0.133427,-0.135922,-0.052286,-0.452456,0.164209,-0.145885,-0.001732,-0.398413,0.036970,-0.138913,-0.206697,0.028481,0.392755,0.148485,0.352688,0.491597,0.031604,0.133816,-0.390372,0.663772,0.264663,0.184968,0.011523,-0.267174,-0.109784,0.215090,-0.022878,-0.381654,-0.292769,0.082269,0.029861,0.420624,0.171430,-0.406447,0.054017,-0.209173,0.278414,-0.261374,0.385542,0.203102,0.204945,0.253992,0.105686,0.480162,-0.097600,-0.248653,-0.106329,0.167923,0.026074,0.113901,0.187330,0.056169,-0.045343,-0.012791,-0.348455,0.239039,-0.271102,-0.274492,0.108877,0.422100,0.252026,-0.266896,0.084898,-0.135790,-0.453442,0.235018,0.193967,-0.288267,-0.003525,-0.171411,0.452775,-0.545831,-0.019058,-0.017809,0.255634,0.126696,0.525379,0.070735,0.230894,0.086508,0.136815,-0.380824,-0.690860,0.507325,-0.185610,0.278292,0.116093,-0.374756,-0.176581,0.043314,-0.282465,-0.242861,0.430238,-0.141846,-0.060823,-0.225396,0.036748,0.010794,0.069908,-0.673700,0.086427,-0.069352,0.124890,0.102294,-0.002717,0.157204,0.104007,0.399925,-0.030223,0.030663,-0.036163,-0.311793,-0.373161,-0.331481', '1305720', '24745500', '4735944', '1293518');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3412882', '窃听风云', '剧情', '情报科窃听小组三兄弟情同手足，梁俊义（刘青云 饰）正直而又懦弱，在个人感情问题上托泥带水；杨真（古天乐 饰）家境窘困，不仅要应付身患白血病儿子的随时可能出现的突发情况，而且自己也病入膏肓，命不久矣；林一祥（吴彦祖 饰）年轻有为，满怀雄心，如今又“嫁入豪门”，前途不可限量。三兄弟在负责调查上市公司“风华国际”涉嫌内幕交易案起始，通力合作，出色的完成了布置各种偷听及监视仪器的工作。在继续的监听过程中意外获得一则情报，巨额利润诱惑之下，三人遂起贪念，在风起云涌的股市大赚一笔。事后三人又恐事情败露，利用职务之便销毁罪证。正当三人以为这件事平息之际，却不曾想风云再起，一只意想不到的黑手往他们袭来，三人陷入劫境，连遭杀戮，最终悲情收场。“三大型男”挑战极限，两大班底（《无间道》、《门徒》）共同打造，一段悲情感人至深。©豆瓣', '刘青云', '麦兆辉', 7.6, 272543, 'tt1349853', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1839391107.jpg', 0.2, 1.8, 29.2, 53.9, 14.9, '-0.329479,-0.055789,-0.531144,0.251718,0.106231,0.016644,0.189300,0.283273,-0.405047,-0.308888,0.277036,0.326824,-0.116926,-0.065906,0.314446,-0.435562,-0.201569,-0.573181,0.136575,-0.090684,0.027380,-0.330405,-0.262415,-0.347099,0.035001,-0.186209,0.547396,0.307637,-0.307693,-0.008636,0.191970,0.299093,-0.420912,0.022929,0.144438,-0.208337,0.033421,0.219436,-0.534652,0.147711,-0.060029,-0.310271,-0.153513,0.117564,0.109004,0.208719,0.493700,-0.122483,-0.239814,-0.055302,0.346732,-0.082716,-0.065428,-0.043447,0.471495,0.040638,0.188806,0.378717,-0.345515,-0.093713,0.123253,0.048655,-0.828256,-0.111350,0.099064,0.052596,-0.274207,0.054928,-0.318755,0.127932,-0.132667,-0.049516,-0.150815,0.621074,0.345897,0.177546,-0.072891,0.126565,-0.433721,0.166808,0.619156,0.015975,0.067808,0.044695,0.235517,-0.218872,-0.067420,-0.341967,-0.078907,-0.204768,0.505594,0.101335,0.146475,0.430605,-0.158788,0.105345,-0.267771,0.101366,0.021187,-0.157585,0.021416,-0.613831,-0.073136,0.249319,-0.267090,0.249104,0.457829,-0.244361,0.561430,-0.367225,-0.047940,0.276776,-0.092650,-0.864708,0.173976,0.132620,0.363526,-0.291185,-0.285364,-0.201641,-0.000041,0.053922,0.134665,-0.172725,-0.127784,-0.425639,-0.077085,-0.148227', '26678784', '1484760', '1302110', '129786