INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34142992', '那一夜，我给你开过车', '剧情', '该片通过一个代驾司机李渤的眼睛，展现人生百态，社会热点，虽然故事发生在夜晚，只是一段或长或短的车程，却让代驾司机李渤一次次生出念头，相对醉倒在眼前或哭或笑的人说一句，你这样做，不会后悔吗…………', '田雨', '林晓丽', 5.2, 3784, 'tt10452012', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2574203816.jpg', 15.4, 32.7, 34.6, 12.5, 4.8, '0.020830,-0.011274,-0.401539,0.412305,-0.140248,0.025455,1.069432,-0.108195,-0.350808,0.026211,0.047981,0.497945,-0.669238,0.334975,0.239549,-0.413371,-0.239701,-0.398398,0.579582,-0.420024,0.036307,-0.402486,0.462815,-0.064069,0.150161,0.025176,0.417478,0.068178,-0.293631,-0.094612,-0.200015,-0.145018,-0.025432,0.524842,-0.155892,-0.371824,-0.329549,0.092058,0.045562,-0.114427,0.075979,-0.489769,-0.228626,-0.169916,-0.445166,-0.148869,0.515926,0.071878,-0.642594,0.116690,0.254180,-0.134997,0.014935,-0.445213,-0.268892,-0.192720,0.431811,-0.104678,0.040449,-0.142405,0.040318,0.349348,-0.874522,0.040434,-0.376941,0.179669,-0.381258,0.277414,-0.151313,-0.060788,0.138546,-0.550564,0.226198,-0.030913,0.842202,0.378668,-0.133466,0.114410,-0.397850,0.113841,0.590990,0.151013,-0.536056,0.500127,-0.316529,-0.172842,0.072706,0.272857,-0.508171,-0.005478,-0.141177,-0.628639,-0.435756,0.119771,0.052618,0.311895,-0.012566,-0.275768,0.049920,-0.366390,-0.288481,0.039829,0.270857,-0.171378,-0.144243,-0.078022,0.261594,-0.204923,0.735389,-0.314550,0.315873,0.430467,0.331331,-0.348410,0.469547,0.431808,0.034295,-0.164652,0.171333,0.306458,-0.101737,0.068924,-0.106608,-0.024877,0.000399,0.301931,-0.152923,0.025096', '35360296', '1299767', '2377539', '1824412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3415993', '巨人捕手杰克', '剧情', '曾几何时，云端的巨人依靠通天豆荚来至大地，他们横行肆虐，吞噬人类，祸害无边。多亏勇敢机敏的埃里克国王将巨人赶回老家，巨人的传说从此越传越神，流传甚广。自幼深深为巨人故事所吸引的穷人家青年杰克（尼古拉斯·霍尔特 Nicholas Hoult 饰）进城买马，偶然遭遇一名被皇家卫队追捕的僧侣，他更在慌乱中用马换了对方手中的豆荚。夜幕降临，暴雨突至，不愿将毕生幸福付与他人的公主伊莎贝尔（艾莉诺·汤姆林森 Eleanor Tomlinson 饰）趁乱出走，辗转来到杰克家中避雨。正当他们聊天之际，被雨水浸透的豆荚突然发芽，豆茎疯长，直达天际，将困在屋中的公主带入云端。为了找回公主，杰克自愿加入国王组建的营救队伍，等待他们的却是耳熟能详的传说里的巨人……©豆瓣', '尼古拉斯·霍尔特', '布莱恩·辛格', 6.3, 44648, 'tt1351685', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1858018022.jpg', 2, 13.6, 57.5, 21.4, 5.5, '0.161651,0.174979,-0.608842,0.448566,0.043203,-0.082375,0.719599,0.069076,-0.334581,-0.221956,0.464287,0.503856,-0.091072,-0.169938,0.408323,-0.084110,-0.208229,-0.342193,-0.035723,-0.206687,-0.132924,0.125701,-0.269465,-0.229944,-0.148254,-0.329523,0.748067,0.064550,-0.024710,0.460550,0.011289,0.289238,-0.254165,0.291324,-0.475010,0.160698,-0.174994,-0.055990,-0.031736,0.282106,-0.371267,-0.228782,-0.093686,0.018146,-0.192597,0.054009,0.608272,-0.608064,0.434688,-0.273771,0.231235,-0.336174,0.136478,0.102743,0.461686,0.082465,0.064795,-0.100502,-0.059288,-0.173238,0.091505,-0.187964,-0.358950,0.025600,-0.008710,0.096271,-0.603775,0.023292,0.195670,0.081869,0.282394,-0.236565,0.119058,0.032784,0.058860,0.337011,-0.024692,-0.156614,-0.508086,0.237990,0.585872,-0.321003,-0.089593,-0.162201,-0.100772,-0.238395,0.166002,-0.114096,-0.390619,-0.330762,0.595672,0.043257,0.036880,0.518809,-0.565710,-0.148716,-0.433553,-0.160190,0.018341,-0.393250,-0.300572,-0.328050,-0.005280,0.091224,0.215362,-0.027701,0.185231,0.015859,0.556624,-0.385132,0.474147,0.487302,0.174229,-0.083917,0.347113,-0.379120,0.162357,-0.098990,-0.075806,0.486539,0.277297,0.496258,0.180611,0.272649,-0.254618,0.110166,-0.364402,0.328919', '21619567', '1856675', '1467779', '24879819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3418187', '克洛伊', '悬疑', '事业有成、家庭幸福的女医生凯瑟琳（朱利安·摩尔 Julianne Moore 饰），总是被诊所楼下的一个应召女郎牵绊着目光。音乐教授戴维（连姆·尼森 Liam Neeson 饰）生日当晚错过凯瑟琳准备的惊喜派对，第二天凯瑟琳又看到丈夫手机里收到学生发给他的暧昧短信，一切似乎验证了凯瑟琳长期以来对于丈夫不忠的怀疑。为了证实自己的猜测，凯瑟琳雇佣应召女郎克洛伊（阿曼达·塞弗里德 Amanda Seyfried 饰）去考验丈夫。在克洛伊向凯瑟琳的汇报里，关于她与戴维的交往细节令凯瑟琳感觉到极度伤心，被背叛和失落的情绪笼罩的凯瑟琳和克洛伊发生一夜情。凯瑟琳在外过夜的事情令戴维极为不悦，在夫妻二人争吵的过程中，面对妻子对于自己不忠的指控，戴维坚决否认。三人之间的关系扑朔迷离，凯瑟琳的家庭遭受严重危机……©豆瓣', '朱丽安·摩尔', '阿托姆·伊戈扬', 7.4, 56667, 'tt1352824', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p768098371.jpg', 0.3, 3, 36.7, 45.8, 14.3, '0.440753,-0.019414,-0.622979,0.436077,0.155024,-0.157877,0.879593,0.118679,-0.604628,-0.569354,0.129261,0.524572,-0.415152,0.318272,0.506811,0.042175,-0.594131,-0.676807,-0.053072,-0.095976,-0.062125,-0.680784,-0.086515,-0.370095,-0.036281,-0.345147,0.234303,-0.180931,-0.277154,0.661179,0.355480,0.413310,-0.206928,0.606948,0.245845,0.035579,0.251464,0.037259,-0.484429,-0.001197,0.326076,-0.019196,0.143257,0.357919,0.107456,0.425551,0.475969,-0.077370,-0.167362,0.091532,0.315328,-0.006602,0.101952,0.329881,0.308856,0.195048,0.156579,0.218235,-0.292499,-0.175992,0.222182,0.082670,-0.564370,0.069008,0.053839,0.384266,-0.256008,0.342324,-0.308367,0.048452,0.417273,-0.216678,0.094367,0.179665,0.252738,0.654841,-0.197227,0.045931,-0.208121,-0.141930,0.516385,0.139913,0.126700,0.196742,-0.494602,-0.214289,0.125669,0.196012,-0.669887,0.169914,0.266299,0.199600,-0.091652,0.599492,-0.411057,-0.317402,-0.193830,-0.118963,0.040970,-0.532709,-0.049370,-0.784641,-0.246720,-0.303065,-0.549556,-0.081793,0.026903,-0.211490,0.315918,-0.739428,0.344343,0.321790,0.376732,-0.431943,0.466922,0.237662,0.230709,-0.352815,-0.070496,0.480783,-0.027498,-0.000211,-0.007635,0.052395,-0.054418,-0.110987,-0.263476,0.328849', '4896894', '1916995', '3626365', '1945337');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3419943', '无声婚礼', '剧情', '故事发生在1953年的9月罗马尼亚的一个小村庄里，兰库（亚力山德鲁·波托西恩 Alexandru Potocean 饰）和玛拉（Meda Victor 饰）即将迎来他们盛大的婚礼，这一对男女是如此的相爱，除了做爱与结为夫妻，他们似乎再也无法找到什么更好的方式来传递他们的感情。然而，就在这大喜之时，传来了独裁者斯大林去世的消息，为了表达对他的祭奠，兰库和玛拉被告知他们必须取消婚礼。对于兰库和玛拉来说，一个无关紧要的人的死亡怎么能够阻挡他们的爱情？一场无声婚礼应运而生，这里的无声代表了彻底的静默，没有语言，亦没有碰撞，拉扯，咀嚼所带来的任何声响。对强权和独裁的反抗带给了村民们久违的快乐，却也让这特殊的婚礼最终演变成为了一场葬礼。©豆瓣', '梅达·安德列亚·维克托', '霍拉丘·默勒埃莱', 8.6, 14921, 'tt1194620', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2287838763.jpg', 0.3, 0.8, 10.2, 45.4, 43.2, '0.319720,-0.050191,-0.819044,0.706537,-0.217820,0.068834,0.927155,-0.018946,-0.418159,-0.136283,0.014667,0.850799,-0.416165,-0.013406,0.334775,-0.200404,-0.219250,-0.840529,0.053280,-0.073103,-0.232471,-0.515008,-0.104230,-0.210091,-0.070266,-0.115128,0.604388,0.236371,-0.193938,0.693179,0.344763,0.220943,-0.060141,0.556148,-0.311401,0.010615,0.058738,0.323480,-0.486214,-0.043692,0.029535,-0.043551,-0.125589,0.550255,-0.213405,0.420620,0.469905,-0.708390,-0.108428,0.058839,0.305255,-0.472817,0.111286,0.393359,-0.030271,-0.077910,0.238251,0.485971,-0.289282,-0.177724,0.105090,0.029602,-0.912860,0.185997,0.138447,0.162855,-0.432024,0.755192,0.066233,-0.230346,0.134386,-0.136149,0.470042,0.857683,0.270525,0.581749,-0.362217,-0.183098,-0.582988,0.114097,1.069051,-0.230883,-0.476040,0.434939,-0.345706,-0.567766,-0.014526,-0.226764,-0.295049,0.011789,0.130881,0.393743,-0.277013,0.142143,-0.607320,-0.164708,-0.088733,-0.550955,0.313773,-0.736687,-0.029351,-0.823164,-0.325175,-0.573416,-0.458242,0.206978,0.213137,-0.115735,0.779201,-0.966925,0.263409,0.298211,0.474225,-0.351469,0.697410,0.381544,0.225609,-0.092049,0.016580,0.107392,-0.067584,0.237336,0.121658,0.286648,0.333285,0.234172,-0.403787,0.540660', '25721544', '10876425', '30162520', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3420455', '大电影2.0：两个傻瓜的荒唐事', '喜剧', '文耀（郭涛 饰）四十岁了，还和老婆小鱼（刘心悠 饰）租房子住，整天为了房租推销他的书《新婚指南》，活得有点窝囊。某天，文耀突发奇想，准备把《新婚指南》拍成DVD，自己当导演，找来女演员美凤（谢娜 饰）试镜，谁知美凤却透露了试镜的片段，断章取义放在了网络上，令文耀因为“潜规则”名噪一时，他的电影也歪打正着地找到了投资商。正在文耀找到了业余演员燕子（姚晨 饰）和阿毛（李灿森 饰），准备大干一场的时候，后院起火，老婆小鱼知道了文耀“潜规则”的事情，闹得不可开交，一边是违约的赔款，一边是老婆离婚的威胁，文耀进退两难。©豆瓣', '郭涛', '刘晓光', 5.7, 25189, 'tt1119166', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2681083058.jpg', 7.5, 23.5, 50.1, 15.7, 3.2, '0.237177,-0.216769,-0.349532,-0.019488,-0.086156,-0.409682,0.202724,0.413957,-0.255738,-0.126221,0.361215,0.456780,-0.357966,0.145189,0.243618,0.280780,-0.569663,-0.623761,0.297730,0.060925,0.207790,-0.242583,-0.035418,0.222109,-0.145631,0.107420,0.274838,-0.442613,-0.092705,0.243929,0.292352,-0.230833,0.175299,0.166982,-0.064475,0.272435,0.070679,-0.091871,-0.397975,0.180272,0.249600,-0.027348,-0.282173,0.032096,0.073616,0.508199,0.433589,0.133433,0.075451,0.249006,0.495473,-0.395891,-0.335705,0.098973,-0.058924,0.072472,0.599463,0.213426,-0.237392,0.005250,0.513208,0.235893,-0.552580,0.251731,-0.202767,0.317769,-0.401993,0.391824,-0.249824,0.087126,0.227335,-0.583649,0.227743,0.157412,-0.057158,0.469913,-0.271630,0.000263,-0.694162,0.747749,0.190114,0.153982,0.485125,0.393878,0.196263,-0.125947,0.176320,-0.241083,-0.335970,-0.149584,0.325490,-0.366571,-0.301352,-0.055717,-0.561204,0.040168,-0.134347,-0.089146,-0.184851,-0.380363,-0.407262,-0.413162,-0.318664,-0.132416,-0.179941,-0.194409,0.336423,-0.255076,0.410566,-0.421061,-0.123568,0.645764,0.379728,-0.478028,0.556893,0.417795,-0.165072,-0.102034,-0.172486,-0.745638,-0.466152,0.642416,0.482169,0.349007,0.178363,-0.754286,-0.187097,0.069243', '1462467', '4300640', '1754628', '1307747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3426848', 'A面B面', '剧情', '教授“精神心理卫生”的陈聪明（王洛勇 饰）在评定教授职称的课上口出惊人之语，校长再也无法容忍这位行为疯癫的老师，于是后者进入一家惟利是图的精神病院暂时栖身。在这家医院工作的梁海潮（袁文康 饰）难以忘记前妻柳悦（张静初 饰），经陈聪明开导，梁海潮决定把前妻从开补药店的萧春雷（陈晓东 饰）那里夺回来。此时，日日与补药作伴的柳悦在工作时崩溃，也被送入精神病院，在陈聪明帮助下，梁海潮将柳悦救出，而萧春雷将柳悦的药吃下导致情绪失控，被精神病院关押。梁海潮认为夺回前妻的时机已到，而陈聪明则开始想法帮助受害的萧春雷……©豆瓣', '陈晓东', '宁瀛', 5.7, 8390, 'tt1664629', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p462019475.jpg', 8.9, 25, 42.9, 18.1, 5.1, '0.272284,0.369552,-0.453768,0.666399,-0.256315,-0.318473,0.654114,0.218197,-0.529566,-0.638410,-0.328404,0.057604,-0.134181,0.658697,0.162545,-0.391920,0.097165,-0.512735,-0.075627,0.196817,-0.441101,-0.773578,0.190189,-0.601579,-0.052600,0.207326,0.129914,0.363283,-0.380235,0.337429,0.349601,0.446669,0.196037,0.526955,-0.054202,-0.001349,-0.051048,0.095161,-0.209072,0.153486,0.632179,-0.571923,0.262091,0.291485,0.437431,0.094805,0.619962,0.125459,-0.161234,0.134546,0.582940,-0.215652,0.425489,0.368833,0.403047,0.023711,-0.207095,-0.393177,-0.491428,0.312640,0.117421,-0.177477,-0.339012,0.084853,0.345575,-0.284334,-0.559300,-0.186943,-0.031650,0.331376,-0.264352,-0.089458,0.230013,0.223075,0.337271,0.674506,-0.219082,0.231750,-0.413945,0.140279,0.626729,-0.107072,-0.081922,-0.163323,-0.093386,-0.647809,0.052974,0.093673,-0.163187,-0.189443,0.447890,0.092255,0.186136,0.045260,-0.198202,-0.458810,0.144521,0.278759,-0.227741,0.006567,-0.100858,-0.363188,-0.067579,-0.080270,0.181808,-0.015138,0.058651,-0.326040,0.684947,-0.468309,0.137107,-0.150470,0.120965,-0.748049,0.504233,-0.196258,0.090821,-0.310175,0.528860,0.498264,0.403745,0.199109,0.526442,0.282538,-0.231383,-0.040368,-0.123525,0.228550', '27135473', '2170916', '20470260', '26791455');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34281687', '线', '爱情', '13岁，初恋。俩人无奈分开。21岁，再会。时光却不再来。31岁，现在。如果能再一次与你相遇。这是一个被命运分离的俩人，直到再次相遇的宏大的爱情故事。', '菅田将晖', '濑濑敬久', 7.1, 15334, 'tt10467054', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2611735341.jpg', 1.4, 9.8, 38.8, 32.2, 17.8, '0.136084,-0.029628,-0.612994,0.308326,-0.322731,-0.948137,1.138490,-0.304214,-0.485254,-0.041613,-0.212974,0.971887,-0.322740,0.793181,0.059598,-0.295822,-0.007728,-1.040058,0.257600,-0.457710,-0.417646,-0.242981,0.365450,0.119094,0.337504,0.005576,0.547690,0.030926,0.183543,0.964779,0.339408,0.016468,-0.212371,0.427372,-0.696327,-0.162794,0.105346,0.547335,-0.477189,0.392627,-0.228928,-0.163852,-0.175395,0.011885,-0.534777,0.235460,0.893755,-0.025405,-0.369149,-0.131105,0.354068,0.016927,-0.515440,0.168596,0.142461,-0.111063,0.469352,0.178583,-0.110511,0.122056,-0.331021,-0.061402,-0.649469,0.527892,-0.297140,-0.189253,-0.476445,0.469625,0.301893,-0.137485,0.165015,-0.157749,0.137590,0.867114,0.773583,0.626772,-0.674493,-0.071432,-0.401246,0.130737,1.564658,0.128563,-0.404887,0.700172,-0.032842,-0.481366,-0.116548,-0.365526,-0.568296,0.486267,0.105405,0.081116,-0.158903,0.378640,-0.800256,-0.177130,-0.377341,0.395476,0.203321,-0.756472,0.150398,0.035020,-0.559482,-0.366589,-0.810075,0.979036,0.082479,-0.375382,0.662417,-0.301283,0.171346,0.587909,0.596110,-0.170642,1.102894,0.571315,-0.088735,-0.492811,0.509505,0.397213,-0.439222,0.222419,0.235225,0.360614,0.204641,0.463273,-0.971553,0.302150', '27008393', '26687241', '2365260', '27067713');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3428500', '潜伏者', '剧情', '鲍勃·梅瑟是一名海关工作人员，经常从事卧底工作以便抓捕贩毒人员。他虽然有资格以全额福利退休，但为了破获犯罪集团洗钱案不惜以身犯险。他和同事埃米尔·阿夫雷乌更名改姓，乔装成可以提供洗钱服务的富有商人，并通过线人的介绍，结识了一些需要该项服务的商业人士。经过一层层的牵线搭桥，他结识了犯罪集团的合伙人之一罗伯托·爱尔卡诺，并成功取得他的信任。鲍勃·梅瑟施计在自己的“婚礼”上一举抓捕包括罗伯托·爱尔卡诺在内的所有洗钱案涉事人，成功侦破美国史上最严重的一宗洗钱案内幕。', '布莱恩·科兰斯顿', '布拉德·福尔曼', 7, 10089, 'tt1355631', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2337024492.jpg', 0.8, 5, 46.7, 37.9, 9.6, '0.286757,-0.070538,-0.325863,0.477227,-0.267947,0.003486,0.102891,0.011788,-0.580931,-0.359577,0.260123,0.656084,0.210052,0.062836,0.256999,-0.212161,-0.203855,-0.706009,-0.108066,-0.226492,-0.199141,-0.790927,-0.274070,-0.441540,-0.339467,-0.232091,0.491194,0.117839,-0.189676,0.191154,0.342829,0.275204,-0.186128,0.331775,-0.056931,-0.434716,0.527272,-0.204863,-0.501580,0.188962,-0.223238,-0.438877,0.204586,0.016436,0.394112,0.545607,0.251399,-0.026308,-0.094104,-0.197856,0.371427,-0.507431,0.353559,-0.041919,0.275196,0.306265,0.397942,0.679097,-0.449667,-0.053985,0.057243,-0.326405,-1.303423,-0.508802,0.253763,0.120055,-0.352536,0.239061,-0.130660,0.265114,-0.142161,-0.242206,0.110612,0.612160,0.109243,-0.051422,0.198679,0.353169,-0.546470,0.538186,0.661635,-0.170008,0.004871,-0.107555,-0.428451,-0.544331,0.094301,-0.315840,0.163980,0.036136,0.490952,-0.362373,0.222817,0.056856,-0.516090,-0.200108,-0.267717,-0.300140,0.112304,-0.035968,0.323356,-0.947761,-0.180961,-0.056573,-0.176149,-0.004390,0.292396,-0.738474,0.446648,-0.906134,-0.292162,1.103024,0.317666,-0.909546,0.465943,0.175312,0.371084,-0.373665,-0.731243,-0.006692,0.541720,0.382652,-0.183854,0.060632,0.072234,-0.513877,0.027828,-0.308825', '1307442', '27009869', '27073234', '1297689');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3428529', '如果我留下', '剧情', '影片改编自美国作家盖尔·福尔曼畅销18个国家的同名小说，天赋超群的古典音乐少女米娅，与家人遭遇严重车祸，在昏迷之中忽然灵魂出窍，在生死之间看见未来。这段预告片中，莫瑞兹朗读小说的序言作为旁白，一边亲眼看着自己倒在车祸现场，躺在手术台上，男友和同伴奔向医院，护士在耳边喃喃低语，一边思索要如何做出这艰难的选择：是随父母离世而去，还是苏醒过来继续人生。', '科洛·莫瑞兹', 'R·J·卡特勒', 6.2, 10734, 'tt1355630', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2210971106.jpg', 3.1, 17.1, 51.8, 21.5, 6.6, '0.008636,-0.171777,-0.484073,0.557750,0.395642,-0.281247,0.898420,0.045986,-0.552882,-0.319077,0.372586,0.931668,-0.213264,0.467077,0.282850,-0.023727,-0.527220,-0.912525,-0.273745,0.151038,-0.496165,-0.649500,-0.091683,-0.018454,-0.062262,-0.332793,0.550097,-0.144095,-0.377747,0.479255,0.166353,0.487114,-0.552540,0.195946,-0.230250,0.307869,0.051951,0.086739,-0.369459,0.287535,0.690471,-0.441443,-0.312228,-0.158761,0.077015,-0.232719,0.647271,-0.150727,-0.108224,0.208083,0.515711,-0.229168,-0.084325,0.150129,0.161997,0.099578,0.560758,0.015366,0.100143,-0.039320,-0.302097,0.188076,-0.804587,-0.178465,-0.018093,0.325833,-0.588073,0.422834,-0.036578,-0.087573,0.471593,-0.442568,0.274446,0.386823,0.259479,0.744378,-0.304343,-0.026231,-0.165910,0.117460,0.230633,0.358390,-0.120469,0.584720,0.139305,-0.340329,-0.318049,0.090283,-0.570293,0.165102,0.147823,0.245218,-0.235480,0.180758,-0.012275,0.145773,-0.030654,-0.383705,-0.093952,-0.248087,-0.458652,-0.461151,-0.107896,-0.244899,-0.008454,-0.058619,0.017970,-0.322340,0.580506,-0.446121,0.273799,0.490534,0.171098,-0.141770,0.686988,0.116284,0.289594,-0.064103,0.090437,0.527063,-0.026609,0.268977,-0.010559,-0.052367,0.067925,0.371044,-0.783503,0.098763', '1824412', '26884422', '30401849', '33415943');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3430271', '沙漠之花', '剧情', '华莉丝（莉亚•科贝德 Liya Kebede 饰）出生在索马里的沙漠和母亲过着游牧民族的生活。在三岁时，华莉丝按照索马里习俗就被施以女性割礼。十二岁时父亲为了得到五头骆驼，要将华莉丝嫁给六十岁的老叟。就在出嫁前夜，华莉丝在母亲的默许下，在沙漠中徒步很久投奔摩加迪沙的外祖母,也在外祖母那里获得了去给当时索马里驻英国大使夫人的姨妈作女佣的机会。到英国后不久，索马里爆发战争，旧政府被推翻，华莉丝趁乱再次出逃大使馆而流浪英国街头。华莉丝在街头邂逅了收留自己的玛丽莲（莎莉•霍金斯 Sally Hawkins 饰），跟着又在打工的餐厅里遇到伯乐，最终被发掘成为世界名模，并投身于妇女解放事业。电影《沙漠之花》是根据出生于索马里的黑人模特华莉丝•迪里的自传畅销书改编。©豆瓣', '索亚那·奥马尔-斯切戈', '雪莉·霍曼', 8.8, 103687, 'tt1054580', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p860156043.jpg', 0.1, 0.5, 8.7, 41.8, 48.8, '0.101923,0.240607,-0.835162,0.536248,-0.077799,-0.290664,0.518241,-0.077400,-0.371350,-0.070452,0.157362,1.173728,-0.057685,0.312748,0.401362,0.186627,-0.371313,-0.591770,-0.076301,-0.156190,-0.285346,-0.320347,-0.139471,-0.098054,-0.158493,-0.468202,0.705255,0.224223,-0.242857,0.363982,0.134011,0.329752,-0.115431,0.352396,-0.611393,0.143668,0.011162,0.001590,-0.414597,0.462048,-0.071776,-0.276234,-0.168250,-0.100939,0.051378,0.168324,0.703899,-0.254034,0.146399,-0.220945,0.475050,-0.144587,-0.064341,0.102899,0.646542,-0.111348,0.153080,0.314665,-0.183592,0.231002,-0.068668,-0.242059,-0.374485,0.031823,0.103308,0.099663,-0.999738,0.446050,-0.028409,-0.186794,0.256768,-0.393034,0.328669,0.549878,-0.000099,0.442745,-0.102140,0.177681,-0.768285,0.464860,0.711251,-0.082758,-0.134223,0.126667,-0.080485,-0.520123,0.254542,-0.308476,-0.278495,-0.106718,0.232224,-0.410745,-0.514390,0.124841,-0.638494,-0.069363,-0.249236,-0.534226,0.255795,-0.221268,-0.210546,-0.677651,-0.011886,-0.296506,-0.212626,0.164737,0.200422,-0.064669,0.556659,-0.852771,0.517287,0.672193,0.474304,-0.341126,0.589389,-0.011480,0.207758,-0.154107,0.065015,0.365942,0.133159,0.417786,0.058362,0.072541,-0.081309,-0.252583,-0.405599,0.491922', '1309069', '26678509', '3285622', '1926007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3431336', '罗马的房子', '剧情', '影片上翻拍自一部智利2005年的电影《在床上》，但是导演将原片中的一男一女的结构变成了两个女孩的相遇。初夏的第一个夜晚，拥有两个孩子的西班牙母亲阿尔芭(埃琳纳·安娜亚 Elena Anaya 饰)，一周后即将嫁人的俄罗斯女孩娜塔莎(娜塔莎·亚罗温科 Natasha Yarovenko 饰)，在意大利那充满古韵的首都罗马相遇。两个女人的秘密，就这样绽放在一个罗马的房间。爱神的箭从天际射向了她们，欲望也为她们开拓了一个暧昧又趣味的时刻，使两人初相识的隐瞒与防卫心，竟开始逐一融。两个女人的心事，就这样交融在这样一个沁凉的初夏。这是一场持续了12个小时的爱欲盛宴，它穿过了深夜、一直到天亮。清晨的降临，预示着彼此的分离，她们要去面对现实生活与精神自由的考验。罗马这座城市终究会变成她们一个中转站，还是一个新的起点？©豆瓣', '埃伦娜·安纳亚', '胡里奥·密谭', 7.5, 41474, 'tt1263750', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p640322980.jpg', 1.1, 5.4, 33.3, 39.8, 20.4, '0.338180,0.198462,-0.705882,0.689570,0.014486,-0.431905,0.929560,0.091457,-0.178120,0.023717,0.372675,0.873462,-0.395701,0.277904,0.344432,0.141829,-0.370166,-0.818200,-0.093907,-0.196170,-0.239188,-0.227592,-0.224373,0.031957,0.055301,-0.040616,0.752833,0.121696,0.092263,0.375687,0.225615,-0.052311,-0.027735,0.475704,-0.180668,-0.081306,0.033619,0.010718,-0.204819,0.419951,-0.129644,-0.114617,-0.187641,0.112080,-0.288663,0.247438,0.891449,-0.335891,-0.000821,-0.196726,0.447080,-0.060940,-0.197160,0.134603,0.251478,-0.004170,0.071428,0.021847,-0.239863,0.042938,0.004029,-0.042065,-0.475260,0.133025,-0.034769,0.042107,-0.496402,0.521531,0.094527,-0.116658,0.079356,-0.348323,0.216629,0.490383,0.176950,0.557019,-0.395724,-0.005151,-0.573152,0.037244,0.740406,-0.054849,-0.372497,0.495803,-0.261766,-0.523561,-0.228641,0.129017,-0.608429,-0.324608,0.317367,-0.131983,-0.107366,0.170994,-1.086668,0.215209,-0.222202,-0.205683,-0.023789,-0.352132,0.016946,-0.518285,-0.185212,-0.328751,-0.361983,0.304117,0.097748,-0.052533,0.736956,-0.660168,0.433843,0.730457,0.177705,-0.241675,0.694544,0.285560,0.254460,-0.210997,0.009779,0.409259,-0.275073,0.213658,-0.040706,0.688303,-0.121851,0.365204,-0.629534,0.625462', '1467779', '26290398', '21619567', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3431735', '亨利的罪行', '剧情', '亨利（基努·李维斯 Keanu Reeves 饰）是一个没有梦想的男人，浑浑噩噩度日的他完全不明白自己究竟为了什么而活。一次意外让亨利锒铛入狱，在狱中，他结识了名叫马克斯（詹姆斯·凯恩 James Caan 饰）的诈骗犯。马克斯是一个无论身处何地都心怀梦想的男人，他的所作所为点醒了亨利，让亨利产生了寻找自己梦想的想法。出狱后，亨利总算找到了自己的梦想——抢劫一间银行。为了实现他的梦想，亨利甚至保释了根本就不愿意出狱的马克斯，两个笨贼开始着手实行他们的计划。在此期间，意外结识的女演员朱莉（维拉·法梅加 Vera Farmiga 饰）令亨利坠入了爱河，面对梦想和爱人，亨利不知该如何选择。©豆瓣', '基努·里维斯', '马尔科姆·文维尔', 6.6, 6660, 'tt1220888', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p884692268.jpg', 1.3, 10, 54.1, 27.9, 6.7, '0.055741,0.038326,-0.649695,0.501277,-0.416364,-0.551181,0.672634,-0.017369,-0.275138,-0.407954,0.170323,0.805076,0.044223,0.077444,0.159719,0.239811,-0.177001,-0.735877,0.181322,-0.186632,-0.249662,-0.527704,-0.437376,-0.502249,-0.040125,0.109026,0.729958,0.075724,0.048280,0.045968,0.522908,0.359981,0.293006,0.479359,-0.079610,0.246315,0.418997,0.230009,-0.393159,0.159746,0.008955,-0.233863,-0.223904,0.566155,-0.175493,0.358911,0.484650,-0.202459,-0.039053,0.101523,0.098497,-0.396472,0.065115,0.235860,-0.193391,-0.290414,0.003813,0.151617,-0.069931,-0.116579,0.182145,0.060463,-0.831198,-0.065189,0.045681,0.214615,-0.619211,0.068301,-0.289218,-0.028354,0.072022,-0.267655,0.036930,0.454377,0.504800,0.389130,-0.193244,-0.034958,-0.594220,0.360575,0.834176,-0.202318,-0.229927,0.549930,-0.316367,-0.332767,0.024176,0.065708,-0.574011,-0.094702,0.265735,0.164718,-0.234001,0.136634,-0.263996,-0.121692,-0.397499,-0.075397,-0.142649,-0.642101,0.127183,-0.090809,-0.241113,-0.069776,-0.224144,-0.199393,-0.036221,-0.457020,0.517295,-0.864817,0.242199,0.846924,0.166314,-0.774669,0.683660,0.468238,0.085616,-0.495188,0.133529,0.515172,-0.038998,0.076195,-0.070120,0.230874,0.169574,-0.089946,-0.296969,0.578268', '30345227', '5985887', '1296569', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3432861', '黑色弥撒', '剧情', '根据纪实文学《黑弥撒：FBI和爱尔兰黑帮不光彩合作的真实故事》改编。詹姆斯·巴尔杰是全球十大在逃通缉犯之一，他发迹于波士顿，获奥斯卡最佳影片的《无间道风云》中的黑帮大佬就有他的影子。巴尔杰建立的“冬日山岗帮”（Winter Hill Gang）是波士顿著名的黑帮组织，从贩卖毒品到倒卖军火无恶不作，另外他们和包括爱尔兰共和军在内的北美及欧洲许多主要的犯罪集团都有联系。', '约翰尼·德普', '斯科特·库珀', 6.5, 15085, 'tt1355683', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2261682765.jpg', 1.2, 10.8, 56.8, 24.9, 6.3, '0.321988,-0.323187,-0.972055,0.581999,0.096954,0.059737,0.468908,-0.078408,-0.587358,0.067426,0.202535,0.898672,0.001438,-0.000836,0.072812,-0.115980,-0.322819,-0.824654,-0.465789,-0.360056,0.136172,-0.608587,-0.929536,-0.166776,-0.161279,-0.123778,0.761442,0.336801,-0.539021,0.317136,0.318284,0.290266,-0.300491,0.093874,-0.469573,-0.013387,0.293834,-0.005581,-0.533515,0.332769,-0.264927,-0.323542,-0.140145,0.015475,0.267332,0.607517,0.271161,-0.300978,0.413285,0.050933,0.335195,-0.497328,-0.417413,-0.323696,0.690649,-0.155181,0.134957,0.616425,-0.035505,-0.085662,-0.083492,-0.087165,-1.079341,-0.064583,0.626455,0.637451,-0.685821,0.506763,-0.421213,-0.316448,0.201719,0.018435,0.471492,0.289910,0.068447,0.210847,0.518996,0.444736,-0.724877,0.494947,0.703127,-0.080419,-0.274033,-0.216771,-0.122829,-0.434059,-0.191898,-0.510711,0.244728,-0.027669,0.410232,-0.631845,0.154404,0.382598,-0.789890,-0.052151,0.327504,-0.546553,0.058514,-0.120412,-0.018992,-0.995691,-0.412550,-0.517611,0.173547,0.011686,0.344025,-0.119734,0.778964,-0.910460,0.149856,0.586680,0.235139,-0.621656,0.620556,0.130123,0.238846,-0.212106,-0.243375,0.027358,0.496239,0.386515,0.029465,0.266684,-0.022935,-0.464771,-0.002399,0.088280', '1793491', '4301278', '25928048', '1307762');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3434070', '太空旅客', '科幻', '吉姆（克里斯·普拉特 Chris Pratt 饰）是阿瓦隆号飞船上的一位工薪阶层旅客，在飞船前往太空殖民地家园2号的120年旅途中，因一次意外，他从冷冻睡眠中醒来。发现自己有可能要在这艘巨船上独自度过89年，吉姆试着重新入睡，但最终只能在安置了5000个同行人员的睡眠舱中孤独生活，处于自杀边缘的吉姆绝望中孤注一掷，于是，他唤醒了一名女乘客奥罗拉（詹妮弗·劳伦斯 Jennifer Lawrence 饰），两人在相处的期间产生了爱情的火花。而当飞船的操作系统瘫痪，这对情侣面临着更大的问题，生命受到威胁的不仅仅是他们自己，也包括同行的旅伴，和航行本身。', '詹妮弗·劳伦斯', '莫滕·泰杜姆', 6.9, 200991, 'tt1355644', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2410576676.jpg', 1.2, 8.4, 44.3, 35.1, 11.1, '0.195475,0.129314,-0.845436,0.472956,0.152447,-0.368855,1.118254,0.002459,-0.624267,-0.296669,0.356809,0.728260,0.062730,0.289665,0.391884,-0.046023,-0.632548,-0.349418,-0.106488,-0.076725,-0.700027,-0.514608,-0.110948,-0.241127,-0.156275,-0.491983,0.721880,0.179884,-0.101014,0.476944,-0.023600,0.265125,0.115450,0.605108,-0.082646,-0.088454,0.155285,-0.065437,-0.149294,0.331960,-0.209454,-0.262690,0.027552,0.063217,0.165550,0.345706,0.956848,-0.364469,-0.039708,-0.053212,0.045272,-0.295314,-0.053723,-0.120815,0.396763,-0.032292,-0.037155,-0.105059,-0.354216,0.168866,0.173781,0.124982,-0.646064,-0.132317,-0.218227,0.014725,-0.403146,0.488070,-0.053115,0.002673,-0.054089,-0.132384,0.208770,0.442409,0.218898,0.310208,-0.358536,0.024898,-0.583779,0.059734,0.770354,0.008664,-0.432410,0.520550,-0.435839,-0.570803,-0.330779,-0.229170,-0.574412,-0.395055,0.474240,0.237104,-0.357208,0.424817,-0.645298,0.374650,-0.282544,-0.468568,-0.291356,-0.188635,-0.019490,-0.707240,-0.047149,-0.396679,-0.201643,0.307015,0.096100,-0.174676,0.623974,-0.736165,0.391010,0.667239,0.244588,-0.278410,0.892624,0.206558,0.275788,-0.252669,0.057555,0.405265,-0.160347,0.196833,-0.025974,0.254529,-0.120478,0.269908,-0.522320,0.341076', '21619567', '3055049', '3011051', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3439312', '猫和老鼠', '喜剧', '“超杀女”科洛·莫瑞兹饰演的少女凯拉刚刚入职豪华大酒店，就碰上了叫人头疼的难题——杰瑞竟然想在酒店里定居，令酒店最近承接的世纪婚礼岌岌可危。于是，汤姆被凯拉雇佣成为酒店员工，目的是赶走杰瑞，这对欢喜冤家就此展开了一场你追我赶的爆笑喜剧。', '科洛·莫瑞兹', '蒂姆·斯托瑞', 5.2, 46914, 'tt1361336', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2632043260.jpg', 9.9, 36.2, 41.8, 9, 3, '0.362350,0.173587,-0.586244,-0.184981,-0.098004,-0.177027,0.571307,0.340792,-0.383831,-0.037941,0.560650,0.795665,-0.594866,0.180773,0.783223,0.193530,-0.455021,-0.499071,-0.048040,-0.276132,0.119221,-0.228320,0.083281,-0.307925,0.276156,-0.382968,0.077203,0.089812,-0.096357,0.343885,0.577982,0.496139,-0.215873,0.317805,-0.028790,0.122240,0.554681,0.071541,-0.174270,0.401244,-0.192958,0.044217,-0.116766,0.063355,0.200462,0.197571,0.425391,0.212838,-0.096650,-0.077876,0.300316,-0.286503,-0.377956,-0.053588,0.386426,-0.315679,0.460597,0.025263,-0.236685,-0.343264,0.161122,-0.122568,-0.668649,0.463260,0.237660,-0.454610,-0.538691,0.384953,-0.034649,-0.081788,0.242066,-0.087162,0.405172,0.362393,0.645837,0.373368,0.492213,0.415151,-0.353468,0.180259,0.837998,0.039922,-0.073058,0.260990,-0.096092,-0.350755,-0.047452,-0.139124,-0.211283,-0.043679,0.194521,-0.168076,-0.057052,-0.276259,-0.523679,-0.115877,-0.452444,-0.171919,0.099972,-0.401169,-0.174645,-0.732175,-0.036349,0.226879,0.083671,0.069518,-0.065511,0.175154,0.298423,-0.706241,0.008635,0.632734,0.514308,-0.167818,0.808595,-0.009778,0.095894,-0.138095,0.023134,-0.247221,-0.168408,0.442988,0.084520,0.448531,-0.082658,-0.426932,-0.338688,0.273657', '3147969', '3326747', '11541282', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3439340', '人间失格', '剧情', '出身于贵族家庭的大庭叶藏（生田斗真 饰）容貌清秀，气质不凡，但他似乎对周遭的人与事充满了焦虑和不安，于是经常有意做出拙劣、愚蠢的事来将自己深深地隐藏起来。所有人中，只有原本陌生的同学竹一看透了他的心思，两人更通过画作成为知己。在上京高等学校求学期间，叶藏偶然结识同一画塾的堀木正雄（伊势谷友介 饰）。这是一个放浪形骸、不拘小节的家伙。堀木仿佛来自伊甸园的毒蛇，为叶藏打开了通往地狱的大门。从此，对生命失去希望的叶藏愈加沉迷于酒色以及万劫不复的堕落之中……本片根据日本文豪太宰治的同名原著改编，系太宰治诞辰一百周年的纪念作品。©豆瓣', '生田斗真', '荒户源次郎', 6.8, 19546, 'tt1361324', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204835509.jpg', 1.8, 10.6, 45.3, 30.3, 12, '0.350704,0.003208,-0.420217,0.540316,-0.064340,-0.172750,0.616255,0.107130,-0.692341,-0.410968,0.211378,0.765307,-0.229872,-0.008577,0.216840,-0.056242,-0.295964,-0.616410,-0.236714,-0.119669,-0.084122,-0.333623,-0.301404,-0.039490,-0.190707,-0.366113,0.826308,0.222476,-0.447853,0.492148,0.120525,0.504113,-0.103493,0.301612,-0.129329,-0.133665,-0.234698,0.088921,-0.337055,-0.027025,-0.079422,-0.237059,-0.306766,0.223541,-0.233022,0.224305,0.574252,-0.514404,-0.275960,-0.168732,0.396512,-0.050771,-0.293968,0.180243,0.072932,0.101855,0.186299,0.260993,-0.396821,0.116382,0.078255,-0.064907,-0.613188,-0.217997,0.367773,0.218204,-0.151842,0.414201,0.237222,-0.255963,0.239700,-0.166240,0.145281,-0.172038,0.288063,0.383001,-0.078418,-0.042625,-0.357322,0.119276,0.429109,0.190550,-0.319182,0.231534,-0.359039,-0.330134,0.006865,-0.307939,-0.344362,0.075554,0.113033,0.005182,0.056990,0.397599,-0.489899,-0.240581,-0.044366,0.153375,0.026294,-0.476893,-0.241062,-0.373653,-0.288742,-0.212064,-0.118066,-0.134093,0.331852,-0.336207,0.882725,-0.884211,0.105960,0.246678,0.126580,-0.476686,0.572257,0.031247,0.071677,-0.142360,-0.385208,0.185205,0.122392,0.208838,-0.137346,0.270076,-0.269653,-0.062838,-0.445000,0.473818', '25880986', '27602116', '3445516', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3439354', '无声风铃', '剧情', '帕斯卡（Bernhard Bulling 饰）和永健（吕聿来 饰）是漂在香港的两个年轻人。帕斯卡来自瑞士，靠做街头艺人和小偷小摸维持生活；永健来自北京，是一家烧腊店的外卖伙计。两个陌生人在陌生的城市不期而遇，发展出一段心动的爱情。然而快乐却是短暂而伤感的，最终因为帕斯卡的一场意外而化做泡沫。很多年后永健单身前往瑞士去追寻爱人走过的足迹，却遇到有着和帕斯卡相似面容的男子。正如风铃破碎的旋律，这段诗意爱情的秘密将在静静的来回插叙中逐步揭示......在中国传统文化中， 当微风吹起风铃声响，代表有先人或魂魄到访。这是一个信号，告诉在世的人「我」回来了，亦是再次提醒他们至亲至爱已经永隔的事实。 《无声风铃》是一部关于放手的电影，它紧凑地展现了东西方在生活哲学、看待死亡与来世上的区别，同时也模糊了爱情与种族的界线、呈现不同文化的融合与一致。本片是香港导演洪荣杰的第一部剧情长片。', '吕聿来', '洪荣杰', 7.5, 6764, 'tt1360832', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p997915555.jpg', 1, 4.4, 32.9, 40.7, 21, '0.335778,0.129775,-0.657047,0.676062,-0.003689,-0.070221,0.896543,0.038797,-0.390964,-0.183555,0.057620,0.739027,-0.082282,0.150320,0.243180,-0.071211,-0.061003,-0.764711,0.087836,-0.278245,-0.063106,-0.544007,-0.277072,-0.153328,-0.153541,-0.254059,0.669091,0.211239,-0.322991,0.597188,0.226029,0.051874,-0.527045,0.311658,-0.366205,-0.142917,-0.111345,0.290599,-0.551450,-0.068195,-0.002950,-0.298585,-0.086113,-0.033904,-0.233734,0.293556,0.594141,-0.194146,-0.120601,0.110030,0.383889,-0.095593,-0.236801,-0.115531,0.204536,0.097311,0.229525,0.309200,-0.085791,0.009126,-0.055182,-0.098221,-0.688546,0.047731,0.231591,0.427015,-0.523141,0.623844,0.046283,-0.405835,0.056615,-0.349080,0.431038,0.120045,0.488375,0.787785,-0.043347,0.057269,-0.444359,0.192014,0.753715,0.130880,-0.579889,0.448086,-0.412235,-0.443036,-0.238092,0.025913,-0.394440,0.071741,0.074921,0.064817,-0.192203,0.186314,-0.905097,0.248544,0.038338,-0.250472,0.040443,-0.545159,-0.165860,-0.627945,-0.245557,-0.594395,-0.229236,0.170221,0.160737,-0.298866,0.748791,-0.735773,0.218121,0.492799,0.281936,-0.280256,0.862833,0.159682,0.000215,-0.274044,0.035075,0.373134,-0.089420,0.027329,-0.112948,0.167861,0.014914,0.251788,-0.618618,0.345485', '3055049', '2053515', '30162520', '2334814');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3440075', '心如折纸', '剧情', '爱情是什么？一个困扰人类几千年的问题。当很多人以为自己切实得到爱情之时，却发现这不过是一段无限接近的过程。而在他们中间，居住在美国洛杉矶的亚裔女孩易筱凌（Charlyne Yi 易筱凌 饰）似乎对爱情尤为困惑。对于这个有些羞涩且从未谈过恋爱的女孩来说，爱情仿佛只存在于童话之中。在导演尼克（尼古拉斯•杰森诺维克 Nicholas Jasenovec 饰）的帮助下，他们一起走过洛杉矶、拉斯韦加斯、奥克哈马等地，采访来自不同行业的各色人等，听他们讲述自己的故事，只为寻找爱情真正的含义。而在这一过程中，易筱凌也展开自己的初次约会……本片荣获2009年圣丹斯电影节华道•索尔（Waldo Salt）剧本奖。©豆瓣', '查琳·易', '尼古拉斯·杰森诺维克', 7.4, 14040, 'tt1331064', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p453132830.jpg', 1, 4.3, 33.5, 44.8, 16.4, '0.311475,-0.038711,-0.839176,0.761642,-0.078510,-0.194704,0.996685,-0.280804,-0.779215,-0.379049,0.088054,0.766705,-0.424963,0.270036,0.313088,0.032515,-0.456002,-0.638244,-0.001073,-0.329927,-0.277675,-0.583602,-0.313211,-0.085218,-0.265452,-0.173182,0.835655,0.193825,-0.172176,0.405496,0.217897,0.265344,-0.043690,0.594262,-0.203910,-0.054584,0.302657,0.287145,-0.468969,0.051199,0.031952,-0.138524,-0.488586,0.453738,-0.290058,0.234364,0.579286,-0.461809,-0.164588,0.112520,0.312974,-0.343634,-0.032516,-0.117223,0.148693,-0.119197,0.491914,0.196927,0.077780,-0.006510,-0.042817,-0.110291,-0.872647,-0.004721,0.012266,0.522581,-0.377054,0.312282,0.127769,0.033043,-0.025363,-0.221837,0.146978,0.333626,0.605934,0.377454,-0.336764,-0.114547,-0.472970,0.279122,0.727446,0.053537,-0.389903,0.748978,-0.420430,-0.560094,-0.247650,0.187839,-0.585639,0.120001,-0.073714,0.076910,-0.182416,0.274237,-0.634066,0.220216,0.057821,-0.385466,0.055021,-0.629502,-0.131213,-0.641310,-0.289531,-0.654309,-0.476054,-0.173586,0.317663,-0.286562,0.789422,-0.867857,0.317726,0.619206,0.197484,-0.318074,0.829422,0.299154,-0.053672,-0.482720,-0.265564,0.564551,-0.170128,-0.117791,-0.310683,0.308427,0.277841,-0.048787,-0.516694,0.861482', '24756472', '4275444', '2053515', '1304641');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3440481', '谎言的诞生', '喜剧', '这是一个现实之外的、根本不知谎言为何物的世界，人们正常工作、生活，只是所有人讲的每句话都是真话。一个刚经历失业、失恋、穷困潦倒的年轻人马克（瑞奇·热维斯 Ricky Gervais 饰）有一天参透了这个秘密——他用一个谎言，让自己账户上的钱增加了，但是没见过谎言的人们完全相信他。尝到甜头的马克开始利用这个秘密，他开始不停说谎，用来谋取任何他想要的东西。随着马克的谎言越编越离谱，相信他的人们越来越多，让事情愈发不可收拾。而马克也渐渐发现，面对自己心爱的女人珍妮弗（珍妮弗·加纳 Jennifer Garner 饰），用“世界末日要来了”将她骗上床并不是自己想要的，能获得爱情的唯一手段仍旧是真实……©豆瓣', '瑞奇·热维斯', '瑞奇·热维斯', 6.7, 11230, 'tt1058017', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1212487842.jpg', 1.4, 9.2, 51.1, 30, 8.3, '0.326769,0.273485,-0.546249,0.489964,-0.397128,0.045791,0.726147,-0.296562,-0.511270,-0.327728,-0.109103,0.642509,-0.044400,0.029635,-0.184709,0.160707,-0.233199,-0.541329,0.427458,-0.128545,-0.162975,-0.587381,-0.212387,-0.365166,-0.378672,-0.020433,0.433176,0.134786,-0.199809,-0.132041,0.347647,-0.018486,0.621633,0.588797,-0.060626,0.021124,-0.023979,0.064317,-0.081639,0.035127,0.130412,-0.164408,-0.186735,0.553136,-0.352626,0.411760,0.199579,-0.259848,-0.354194,0.021204,0.544512,-0.484342,-0.132816,0.080307,-0.165119,-0.156726,0.148505,0.086454,-0.037368,0.093930,0.128523,0.113494,-0.948112,-0.129542,-0.133904,0.158953,-0.381534,-0.034215,-0.217310,-0.060582,-0.010827,-0.343282,0.242825,0.143697,0.330192,0.203085,-0.496191,-0.337703,-0.737882,0.310390,0.651710,-0.007781,-0.329365,0.758243,-0.358202,-0.337563,-0.128249,-0.303420,-0.441431,0.194565,0.026568,0.219949,-0.329371,0.356257,-0.622214,0.154615,-0.150613,-0.403338,0.014608,-0.574211,-0.186190,-0.000688,-0.363366,-0.385036,-0.452767,-0.259702,-0.032245,-0.585880,0.709291,-0.738656,0.149128,0.819716,0.236934,-0.650157,0.420639,0.356427,-0.041986,-0.171197,-0.192275,0.406509,-0.085379,0.223586,0.059653,0.418295,0.266351,-0.101127,-0.167169,0.745389', '30163500', '1304977', '25932086', '4820775');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34429100', '音乐', '动画', '高中生健治有一天突发奇想，邀请伙伴太田和朝仓一起组乐队，但是三个人都对乐器一窍不通。他们的乐队是一把贝斯，再来一把贝斯，还有鼓，配置十分独特。当他们弹奏出第一个音符，立刻被一种前所未有的感觉淹没了，音乐震撼了他们。那天过后，他们决定乐队名字就叫“古典武术”，但是却发现学校里已经有一个“古典艺术”的乐队了。两个乐队明显撞型了，但在看了对方的表演之后，立刻碰撞出了合作的火花。于是他们摩拳擦掌，想要参加即将到来的摇滚音乐节…', '坂本慎太郎', '岩井泽健治', 8.6, 11265, 'tt10487722', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2559302599.jpg', 0.3, 1.4, 11.6, 39.9, 46.7, '0.330643,-0.049431,-0.635716,0.663543,0.015202,-0.241559,0.736886,0.019376,-0.470681,-0.160207,0.003582,0.902452,-0.389419,0.390077,0.329510,-0.259388,-0.284094,-1.048724,-0.040577,-0.271796,-0.307680,-0.253472,0.303145,-0.033956,-0.011954,0.023646,0.353489,-0.179735,-0.175967,0.887359,0.385042,-0.013859,0.116205,0.604199,-0.013293,-0.174408,0.491723,-0.097938,0.089279,0.029661,0.010975,-0.173002,-0.283887,0.204265,-0.170649,0.257660,0.492517,-0.145653,0.257378,0.025007,0.187657,0.038432,-0.119626,0.100643,0.202750,0.258815,0.326758,-0.178556,-0.199485,-0.081104,-0.227962,-0.170660,-0.805343,0.516491,-0.056478,0.000139,-0.408619,0.379175,0.124160,-0.216400,0.146476,-0.046490,0.559650,0.271856,0.584680,0.415792,-0.291508,-0.163192,-0.330634,-0.004089,1.032771,-0.149131,-0.175980,0.305081,-0.282442,-0.572300,-0.337352,-0.034398,-0.065226,0.035653,0.414149,0.252956,-0.072555,-0.380397,-0.883466,-0.024510,0.126438,-0.356986,-0.025645,-0.644980,0.204713,-0.912227,-0.156495,-0.094845,-0.290039,0.099950,0.241929,0.066856,1.058705,-0.974416,0.052753,0.518712,-0.004866,-0.061214,0.579791,-0.017723,-0.168369,0.068800,0.008737,-0.375976,-0.050173,0.369769,0.412535,1.074946,0.192672,-0.197726,-0.344995,0.507081', '30162520', '3811356', '11541282', '3775163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34430056', '北京女子图鉴之助理女王', '剧情', '讲述了小城市来的女生陈祥梅的故事，最终“丑小鸭”华丽蜕变为女王的May姐。', '王菊', '陈静', 5.6, 4513, '助理女王', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2579086404.jpg', 8.1, 25.1, 50.9, 12.5, 3.3, '-0.277981,0.248520,0.140499,0.891001,0.011748,-0.368886,0.740155,0.194379,-0.404903,-0.166070,0.290150,0.452484,-0.324190,-0.005612,0.330872,-0.032556,-0.404051,-0.178028,-0.428548,0.020904,-0.361989,-0.185552,0.181582,-0.098147,0.102953,-0.136576,0.515843,-0.306467,-0.301441,0.086446,0.512720,-0.424224,0.068591,-0.183724,-0.281615,0.182152,-0.127811,0.664739,-0.025597,-0.032928,-0.293745,0.030862,0.041051,0.070796,0.043688,-0.079071,1.299107,-0.736245,0.379935,-0.424541,0.957267,0.103901,0.348682,-0.430523,0.218755,0.096012,0.711528,-0.281268,0.298640,-0.753466,0.172491,-0.812953,-0.409980,0.158837,0.585374,0.046333,-0.218665,0.292458,0.298295,0.117797,0.999670,-0.437693,-0.298971,0.139782,0.975133,0.757271,0.353269,0.457527,-0.082689,0.787308,0.411615,0.439811,-0.485497,0.734515,-0.451675,-0.606582,-0.656519,-0.468383,-0.480410,0.264999,-0.087618,-0.250432,-0.366191,0.696379,-1.005096,-0.936524,-0.325900,0.006761,0.278453,-0.874580,-0.657001,-0.162780,-0.036028,0.185210,0.471573,0.127730,0.060396,-0.051412,1.192494,-1.029014,0.428489,0.776531,0.279125,-0.438925,0.474205,-0.182703,-0.094800,-0.406691,0.055975,0.523835,-0.345455,0.576392,-0.155826,0.439267,-0.555081,-0.371239,-0.946831,0.486274', '4181031', '10174444', '5403927', '27167055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3443074', '寂寞芳心', '剧情', '青年男子阿尔贝（瑟玛尔·侯奴 Cemal Hunal 饰）是一家餐厅的老板，有着很好的工作，事业成功，却过着离群索居的生活。他每天和不同的女人做爱，付她们钱，却从不留任何人过夜。他这样自由而孤独地生活着，自由却寂寞。直到他在二手书店邂逅了美丽的女子艾达（梅莉丝·柏坎 Melis Birkan 饰）。他对艾达一见钟情，并对她展开了热烈的追求。艾达自己经营着一家创意服装店，她从一开始就知道以阿尔贝这样的性格他们注定是分离的结局，但还是难以抵抗他迷人的魅力，与他陷入爱河。习惯了独住的阿尔贝一直无法舍弃自由的生活方式，难以完全溶入艾达，纵然她开朗、迷人，宛如天使。他挣扎，茫然，不知道该如何处理两人之间的关系......©豆瓣', '梅莉丝·柏坎', '查恩·厄尔马克', 8.5, 18338, 'tt1322930', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1389070372.jpg', 0.5, 1.5, 13.9, 40.1, 44, '0.204419,0.082869,-0.804868,0.532361,-0.531078,-0.323358,1.088122,0.333308,-0.447698,0.021808,0.131194,0.804415,0.071688,0.296874,0.226552,0.263376,-0.323353,-0.657288,0.125805,0.025222,0.025354,-0.361529,-0.081990,-0.309268,-0.034391,-0.090348,0.570107,0.158221,-0.075734,0.234780,0.181328,0.043801,-0.076040,0.850300,-0.272689,-0.206747,-0.205233,0.118238,-0.297510,-0.002733,0.153868,-0.222194,-0.385005,0.313510,-0.066162,0.266521,0.536456,-0.205319,-0.341012,0.122633,0.253161,-0.012792,-0.065115,0.318620,-0.069950,-0.255566,0.115907,0.075528,-0.128325,-0.044619,0.060623,0.078137,-0.770498,0.059195,0.008048,0.188444,-0.691943,0.714984,-0.105583,-0.152923,-0.022100,-0.523861,-0.155434,0.220238,0.366422,0.339362,-0.129188,0.007175,-0.673653,0.278448,0.881159,0.349884,-0.512552,0.715504,-0.793665,-0.588558,-0.459589,-0.191175,-0.789058,-0.375840,0.179694,0.212304,-0.215183,0.279875,-0.605953,0.196108,-0.041600,-0.126833,-0.225950,-0.604325,0.013230,-0.373427,-0.290342,-0.916472,-0.684840,0.041945,-0.040651,-0.270793,0.682798,-1.205660,0.058280,0.686840,0.567940,-0.504070,0.787138,0.285984,-0.030188,-0.130024,-0.178436,0.614736,-0.246902,0.132514,0.310669,0.518008,0.190067,0.363135,-0.401903,0.825741', '1296370', '1308755', '4275444', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34433857', '我的女友是机器人', '喜剧', '方元（包贝尔 饰）虽然年纪轻轻，却已经对生活失去了所有的热情。身为导游的他每天浑浑噩噩的做着自己的本职工作，对游览的风景名胜毫无兴趣和热爱。生活里，方元也是形单影只的一个人，长久的孤独让他早就对亲密关系失去了信心。一次偶然中，方元邂逅了一个神秘的女孩（辛芷蕾 饰），两人度过了开心的一夜，可之后，女孩便销声匿迹，令方元久久无法忘怀。一晃眼一年过去，在生日那天，方元意外的得到了一台名为初一的机器人，让他不敢相信的是，初一竟然有着和之前那个女孩一模一样的外貌。在朝夕相处之中，方元渐渐对初一产生了感情。©豆瓣', '包贝尔', '王伟', 3.6, 18357, 'tt13063654', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2617804496.jpg', 48.1, 32.5, 14.8, 2.7, 1.9, '0.117627,0.108420,-0.971861,0.685344,-0.380557,-0.455161,1.025524,-0.226502,-0.834180,-0.210030,0.055388,0.890345,-0.307983,0.479224,0.265271,0.100378,-0.118416,-0.800636,-0.161966,-0.323310,-0.416463,-0.460130,-0.275847,-0.091424,-0.249171,-0.217395,0.327705,0.042590,0.006260,0.803567,0.251687,-0.131246,0.137624,0.854912,-0.306110,0.067853,0.002057,0.117261,-0.114968,0.101889,0.121483,-0.284722,-0.176302,0.320170,-0.153192,0.360067,0.679256,-0.377008,-0.632732,0.044449,0.241926,-0.115049,-0.318697,0.230039,0.319802,0.097356,0.211335,-0.063645,-0.353645,-0.056995,0.025842,-0.001773,-0.783128,0.014905,0.001393,0.131149,-0.726394,0.878262,0.217297,-0.297393,0.071537,-0.329946,0.160444,0.194961,0.357567,0.586053,-0.183051,0.018749,-0.299303,0.355848,0.810196,0.118703,-0.420057,0.738048,-0.306783,-0.289610,-0.234269,-0.129488,-0.687056,0.189092,0.162336,0.149490,-0.232777,0.160291,-0.546349,0.338653,-0.074486,-0.143209,-0.044276,-0.619389,-0.143661,-0.342651,-0.226125,-0.791200,-0.584616,0.169579,0.065562,-0.429163,0.835098,-1.174112,0.396582,0.453061,0.238787,-0.336459,0.742865,0.164824,0.079297,-0.069568,0.164842,0.259263,-0.239357,0.260321,0.200763,0.683258,-0.052456,0.110068,-0.448683,0.706562', '35030151', '1292219', '1308755', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3443393', '百夫长', '剧情', '公元117年，罗马帝国在不断扩狂。但在不列颠北部，扩张却遭到了当地野蛮人——皮克特人的阻拦。百夫长昆图斯（迈克尔·法斯宾德 Michael Fassbender 饰）因在皮克特人袭击中幸存而被任命带领罗马军团中的常胜军团——第九军团前去歼灭皮克特人。但第九军团还是遭到了皮克特人的伏击，军团统帅维流士将军（多米尼克·威斯特 Dominic West 饰）被俘。昆图斯与敌人殊死反抗，带着部分人逃出。他们不但要面对皮克特人的追捕，更希望可以救出将军。他们并不知道，全家被罗马人杀害，自己也被割了舌头的艾泰恩（欧嘉·柯瑞兰寇 Olga Kurylenko 饰）正充满了怒火在对他们展开捕杀。一场逃离罗马边境的危险反抗战正在打响……©豆瓣', '迈克尔·法斯宾德', '尼尔·马歇尔', 6.4, 9118, 'tt1020558', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2159776057.jpg', 1.5, 12.4, 55.6, 24.8, 5.7, '0.132010,-0.039873,-0.932069,0.546530,0.155153,0.104355,0.451277,0.173622,-0.591960,0.177917,0.252425,0.626811,0.188498,-0.297194,0.367899,-0.124223,-0.321824,-0.743972,-0.035009,-0.132351,-0.278494,-0.155252,-0.231357,-0.576817,0.270657,-0.525077,0.714740,0.359803,-0.187424,0.472543,0.255240,0.649047,0.007730,0.683247,-0.011334,0.313776,0.158106,-0.712853,-0.131544,0.241556,-0.414663,-0.282394,-0.384641,0.236433,-0.092125,0.568494,0.763101,-0.622929,0.473450,-0.363732,-0.450804,-0.701088,0.056818,0.334257,0.575637,-0.125350,0.138056,0.452991,0.279925,0.172748,-0.081673,-0.099444,-0.774024,0.208265,0.156244,0.239753,-0.810123,0.630359,-0.258074,0.492160,0.161488,-0.108708,0.129895,0.584030,0.091239,0.194427,0.035958,-0.259214,-0.872879,-0.103869,0.880100,-0.386072,-0.159559,-0.470701,0.107464,-0.362204,-0.011327,-0.506573,-0.244903,-0.034409,0.385726,-0.124635,0.139322,0.413192,-0.903035,0.091158,-0.616942,-0.334249,-0.129497,-0.404897,-0.015290,-0.623761,0.017061,-0.119248,-0.118830,0.535259,0.082919,0.305724,0.492183,-0.673992,0.042080,0.575214,0.793346,-0.368897,0.373601,0.338758,0.104829,0.066299,-0.172343,0.314505,0.359591,0.286718,0.429428,0.202777,-0.325210,-0.160284,-0.045326,0.202038', '6982558', '26316956', '5157137', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34447553', '世界上最糟糕的人', '剧情', '故事聚焦当下的奥斯陆，围绕年轻睿智的女性朱莉展开。30岁的她仍徘徊在人生的十字路口，尽管她与事业有成的制图员阿克塞尔彼此相爱，拥有强烈的安全感，并很开心和他在一起，但她拒绝给渴望孩子的阿克塞尔生子。朱莉决意离开阿克塞尔前往艾文德，希望能够开始新的生活……', '雷娜特·赖因斯夫', '约阿希姆·提尔', 7.9, 61144, 'tt10370710', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2668815075.jpg', 0.5, 2.2, 22.3, 51.2, 23.9, '0.028415,-0.046946,-0.949349,0.641941,-0.091568,-0.402344,0.928383,0.101261,-0.356545,-0.143400,0.151781,0.622310,0.043668,0.413481,0.341475,0.067658,-0.369009,-0.514108,0.364650,0.169422,-0.039845,-0.409342,-0.130268,-0.170493,-0.297042,-0.356578,0.529520,-0.214622,0.017412,0.499552,0.293316,-0.018627,0.147910,0.733594,-0.182062,-0.069520,-0.165520,0.113834,-0.671648,0.126983,0.165499,0.297830,-0.094813,-0.070793,0.113142,0.141471,0.798724,-0.306414,0.088314,0.317327,0.311421,0.023297,0.006860,0.240295,-0.121427,0.150515,0.054941,0.000458,-0.031842,-0.111398,-0.163878,-0.066617,-0.432159,-0.116645,0.289436,0.185926,-0.371341,0.302176,0.126773,-0.080546,0.192245,-0.205817,-0.203968,0.386543,-0.007131,0.441092,-0.135531,0.463296,-0.329501,-0.169107,0.886784,0.207886,-0.486431,0.343405,-0.638897,-0.643684,-0.191437,0.078797,-0.752755,-0.071934,0.197236,0.141926,-0.001151,0.544996,-0.554994,0.103433,-0.072387,0.120236,0.244604,-0.664914,0.155723,-0.308873,-0.137636,-0.419274,-0.566479,0.143294,-0.159650,-0.515913,0.759252,-0.829431,0.326921,0.461709,0.653032,-0.216779,0.863536,0.451346,0.188421,-0.682752,-0.303681,0.971244,-0.194453,0.120554,-0.029893,0.239912,-0.201863,0.437266,-0.742847,0.639307', '1291835', '1292211', '3629232', '35225859');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34453129', '狄仁杰之飞头罗刹', '剧情', '讲述的是祈福仪式之时，天空现一巨型飞头，一时间人心惶惶。狄仁杰与赫连休屠联手查案，几番周折，狄仁杰等人来到神秘的北冥幽都，众人遭遇伏击险些丧命。回到洛阳后，天生异象，危机四伏，狄仁杰临危不惧，终查出幕后凶手。', '杨恭如', '黄河', 4.7, 3059, '', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2566710786.jpg', 15.8, 41.2, 35.6, 6.8, 0.6, '-0.492840,-0.132051,-0.930927,-0.044263,0.336826,0.228773,0.385226,0.110133,-0.760236,-0.669269,0.684708,0.484151,-0.573959,0.046763,0.571587,-0.409650,-0.307763,-0.630301,-0.096766,-0.389485,-0.256421,-0.106236,-0.017695,-0.220908,0.222051,-0.209983,0.031519,0.561234,-0.116729,0.338742,-0.088109,0.170154,-0.719451,0.631463,-0.232727,0.009281,-0.122502,0.100103,-0.126995,0.019272,-0.438219,-0.527807,-0.623301,0.074783,-0.222894,0.223537,0.617728,-0.537945,-0.196544,-0.293579,0.061474,-0.536882,0.064356,0.325941,0.441020,-0.045381,0.210781,0.488908,-0.135634,-0.121339,-0.017462,0.067518,-0.601257,0.213533,-0.034722,0.034297,-0.089794,-0.180453,0.325219,0.270751,-0.418493,-0.135686,0.624162,0.564259,0.472576,0.130319,0.335189,-0.062642,-0.213003,-0.224669,1.006289,-0.253012,0.047514,-0.204748,0.656432,-0.446961,0.206425,-0.019310,0.292143,0.101529,0.675248,0.258856,0.173502,0.403720,-0.365934,-0.352569,-0.510747,0.211367,-0.150716,0.074544,-0.394392,-0.646352,-0.073405,0.032428,-0.170339,0.171425,0.083511,-0.072008,0.352862,-0.375664,0.198905,0.295745,-0.359993,-0.704212,0.142160,-0.192997,0.098868,0.053644,0.006424,0.204202,0.412032,0.661283,-0.299879,-0.156999,-0.310567,-0.143160,-0.250614,-0.257007', '1292846', '3011051', '25870679', '1306021');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34454004', '哆啦A梦：大雄的新恐龙', '动画', '大雄把恐龙展发现的化石带回家，借助哆啦A梦的时光包袱竟然成功孵化出两只从未被发现过的长着翅膀的新恐龙。大雄和小伙伴们决定将小恐龙们带回到属于它们的时代，一场惊心动魄的白垩纪大冒险即将上演。本片是《哆啦A梦》漫画连载50周年纪念作品，同时也是《哆啦A梦》系列电影的第40 部作品。全新的故事，全新的大雄，全新的冒险，全新出发！', '水田山葵', '今井一晓', 7.1, 35500, 'tt10588750', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2624375776.jpg', 0.6, 5.6, 43.9, 37.9, 12, '-0.190297,-0.024842,-0.117052,0.298002,0.442388,-0.144334,0.480734,-0.192127,-0.197026,-0.080077,-0.015202,0.563357,-0.383914,0.416865,0.037579,0.104983,-0.261423,-0.595535,-0.339939,0.345848,-0.405770,0.198357,-0.211050,-0.002045,0.264547,-0.120048,0.821744,-0.169026,-0.452864,0.190919,0.378023,0.155739,-0.454052,-0.089651,-0.411477,0.144627,-0.279557,0.289672,-0.525161,0.098896,-0.241014,0.323831,-0.241429,-0.106429,0.004745,-0.202425,1.009961,-0.778541,-0.092284,-0.008046,0.917676,0.083564,-0.389978,-0.205722,-0.047443,0.389196,0.156094,-0.169977,0.272390,0.411157,-0.152375,-0.537475,-0.825186,0.052522,-0.050875,0.019606,-0.555764,0.180882,-0.024717,0.240933,0.923390,-0.314112,0.117331,0.107445,0.565716,0.404613,0.135912,0.369919,-0.297608,0.481765,0.239139,0.099035,-0.251352,0.507191,0.124408,-0.583486,-0.361346,-0.081459,0.051752,0.306576,0.233401,0.047408,-0.398650,0.375530,-1.187487,-0.069762,-0.061931,-0.718181,0.320723,-0.071573,-0.461179,-0.576187,0.153364,0.074037,-0.024092,0.022280,0.109301,-0.571792,0.793329,-0.682666,0.338834,0.450968,-0.241186,-0.107442,0.624361,-0.194555,-0.026337,-0.178094,0.332011,0.034735,-0.066106,0.342063,0.288133,0.421406,-0.012793,-0.109315,-0.753149,0.857700', '26759820', '4181031', '26290398', '27073245');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3445457', '无境之兽', '剧情', '广袤的非洲土地，奇珍异兽自由奔跑，然而贫穷饥饿、硝烟战火同时充斥着在这片黑土地的每一个角落。某国停站区内，黑人少年阿古（Abraham Attah 饰）调皮搞怪，和世界上其他和平国度的孩子没什么两样。只不过他所拥有的安宁脆弱不堪，政府军和反政府武装的协议一旦撕破，随之而来的便是呼啸而至的子弹与杀戮。阿古在小小的年纪和母亲生离死别，更眼睁睁目睹父兄被杀害的残忍一幕。他夺路狂奔，在密林中被一支由许多少年兵组成的游击队收留。游击队长（伊德里斯·艾尔巴 Idris Elba 饰）巧舌如簧，他如仁慈的父亲一般鼓动着不谙世事的少年们拿起武器，享受同类相残的快感。少年过早长大，过早衰老……©豆瓣', '伊德里斯·艾尔巴', '凯瑞·福永', 7.8, 14692, 'tt1365050', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2292735899.jpg', 0.2, 1.4, 24.3, 54.5, 19.5, '0.175564,0.121902,-0.781977,0.387106,-0.122959,0.059328,0.966050,0.096203,-0.348232,0.020315,0.292870,0.536364,0.011197,0.101574,0.004798,-0.112099,-0.102041,-0.488550,-0.292574,-0.038882,-0.063834,-0.222176,-0.344161,-0.299883,-0.103373,-0.369853,0.758790,-0.002040,-0.238646,0.392946,0.014832,0.158815,-0.354297,0.390733,-0.559840,-0.103826,-0.245445,-0.019690,-0.284050,-0.127311,-0.393451,-0.114718,-0.222849,0.101805,-0.384507,0.184016,0.957963,-0.522349,0.227279,-0.563881,0.246005,-0.145070,0.094477,0.191738,0.189624,-0.078904,0.190178,-0.123721,0.089026,0.142933,0.199505,-0.185402,-0.381884,-0.126621,0.005901,0.188835,-0.633827,0.629322,0.046592,-0.174569,0.259855,-0.276469,0.167619,0.100473,0.001316,0.494280,-0.303817,-0.052132,-0.558102,0.193613,0.608131,0.036255,-0.503840,0.016747,-0.577150,-0.398614,-0.040275,-0.361336,-0.614010,-0.380029,0.426127,-0.204267,-0.136772,0.535345,-0.871708,0.363157,-0.127831,-0.214682,-0.134657,-0.218854,-0.443673,-0.465855,0.098835,-0.430365,-0.262225,0.310613,0.072480,0.092756,0.655929,-0.398614,0.312205,0.538715,0.217078,-0.214551,0.296256,0.029563,0.154819,0.135600,-0.260224,0.554813,0.236041,0.273217,0.238894,0.158805,-0.461583,0.260228,-0.140421,0.520302', '21619567', '1467779', '1856675', '25884436');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34454589', '皮胡', '语言:', '小女孩皮胡爸妈前一天吵架,说了重话.皮胡爸爸第二天一早出去工作,而皮胡妈妈气不过,留下遗言吃安眠药自杀.小皮胡醒来后,在不知道妈妈已死的情况下,在一天时间内,经历了多次生死交关的时刻......', '拉胡尔·巴加', '卡普里·维诺德', 8, 7453, 'tt8458202', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561458322.jpg', 0.6, 1.4, 19, 53.6, 25.4, '-0.266249,0.120911,-0.894752,-0.077826,0.116868,-0.549608,0.218139,0.212029,-0.382770,-0.677575,-0.366816,-0.083333,-0.105494,0.667358,0.157497,-0.477527,-0.551083,-0.386549,0.364308,0.058668,-0.781133,-0.418471,0.675475,-0.129801,0.078961,-0.098587,-0.528629,0.026360,0.220946,0.227815,0.269261,-0.321990,0.255656,0.757307,0.125644,0.208785,0.084974,0.214729,-0.450143,0.290596,0.886957,-0.156996,-0.042065,-0.120417,0.451273,0.140713,0.193822,-0.069153,-0.374421,-0.131626,0.177149,-0.169998,-0.038187,0.106606,0.840363,-0.052207,0.630037,-0.125445,-0.402259,0.241292,-0.059244,0.266710,0.164960,-0.135360,-0.367404,-0.002275,-0.446910,0.294775,-0.148410,0.668530,0.178216,-0.802623,0.500512,0.283585,0.162012,0.120136,0.084539,-0.115550,-0.499451,0.037487,1.022597,-0.306130,0.481984,0.322567,0.300189,-0.055754,0.141200,-0.079633,-0.299133,0.617008,0.063553,-0.042855,-0.687176,-0.002613,-0.225140,-0.451252,-0.020348,-0.166022,-0.100027,-0.150395,-0.346152,0.200985,-0.003022,-0.222100,-0.274005,0.359745,-0.176845,-0.166664,0.320503,-0.478032,0.500089,0.045014,0.173155,-0.426653,0.607588,0.337860,0.281543,0.057814,1.061388,0.175067,0.095634,0.227233,0.608813,0.060805,0.099420,0.450262,-0.291215,0.108391', '1303485', '1292064', '2042219', '1305084');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34454693', '有一点动心', '爱情', '周启文（言承旭 饰）的梦想就是成立一家游戏公司，最终，凭借着努力和实力，周启文终于实现了自己的梦想。然而，因为一场直播意外的发生，导致周启文的公司遭到了全网的口诛笔伐，口碑彻底崩坏的周启文只得选择关掉公司，宣告破产。莫名其妙的被连累，这一口恶气不能不出，之后，周启文带着兄弟们去找始作俑者讨个说法，哪知道在误打误撞之中结识了一款相亲APP的女老板陈然（任素汐 饰）。周启文本想假扮相亲APP的用户，从内部将这家公司瓦解以达到复仇的目的，可在此过程中，周启文和陈然之间，竟然渐渐碰撞出了激情的火花。©豆瓣', '言承旭', '陈嘉上', 4.1, 8977, 'tt13556244', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2653938568.jpg', 31.9, 40.7, 22.1, 3.7, 1.6, '0.294269,0.482030,-0.661889,0.379168,0.045160,-0.432838,0.349125,0.087039,-0.329840,-0.128979,0.037779,0.696916,-0.368136,0.337415,0.337868,-0.324912,-0.009051,-0.779412,-0.047458,-0.263927,-0.027959,-0.510420,-0.206084,-0.027676,-0.019304,-0.114160,0.568315,0.289595,-0.421069,0.148845,0.566404,0.360200,-0.246352,0.510987,0.136646,-0.034131,0.090509,0.091238,-0.361094,0.290299,0.197342,-0.392460,0.038330,0.186558,-0.044924,0.439416,0.568686,-0.207554,-0.212133,-0.077427,0.633734,-0.445859,-0.073308,0.045245,0.253239,0.209409,0.378715,0.144855,-0.371972,-0.058684,0.039064,-0.104645,-1.141489,0.091940,0.253946,-0.154346,-0.480464,0.376481,0.021471,-0.255951,0.041752,-0.328874,0.368553,0.655854,0.728741,0.306337,-0.662139,0.205424,-0.514282,0.113201,0.844261,-0.151014,-0.082170,0.384308,0.074126,-0.110273,-0.046421,-0.224740,-0.175913,-0.126379,0.243246,0.300902,-0.109838,0.020612,-0.796358,-0.228510,-0.230143,-0.364173,0.192478,-0.396230,-0.071844,-0.479658,-0.300135,0.105870,-0.178420,-0.017994,0.012885,-0.340800,0.501428,-0.991791,-0.243502,0.649509,0.393446,-0.643143,0.632138,-0.018234,0.085157,-0.050126,0.077179,-0.239970,0.039722,0.299328,0.175334,0.359028,0.119012,-0.270294,-0.397309,0.355525', '26678784', '1793491', '1874704', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3445516', '阳阳', '剧情', '中法混血儿阳阳（张榕容 饰）是一名体院的四百米跑选手，由于母亲新近改嫁自己的教练，阳阳随母搬入教练家中，与教练之女兼队友小如（何思慧 饰）姐妹相称。小如男友绍恩（张睿家 饰）为阳阳的姣好容貌吸引，引起小如对阳阳的嫉恨，在两个家庭间引起不平的暗涌，最终因为绍恩同阳阳的一次 意外，小如在比赛中阴谋陷害阳阳使后者离家而去。阳阳投奔从事艺人经纪行当的学长鸣人（黄健玮 饰），在他的帮助下开始了自己的平面模特与演员生涯，而运动员之梦渐行渐远……鸣人细心的照顾让阳阳对其产生了依恋，但不知为何，鸣人始终维护着经纪人的职业角色。不久一位法国导演来台拍片，选中阳阳担纲主演，这难得的机会使阳阳再次面对心中对于不知所踪的法国生父复杂的感情波澜。©豆瓣', '张睿家', '郑有杰', 6.7, 6800, 'tt1363490', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2239206700.jpg', 1.4, 8.4, 51.5, 30.9, 7.7, '0.154004,-0.127387,-0.423136,0.525045,-0.014176,-0.191767,0.509874,0.239896,-0.532991,-0.268918,0.131753,0.652978,-0.138540,0.223090,0.163408,-0.085563,0.121617,-0.573839,-0.059161,0.020459,-0.108066,-0.328292,-0.286006,-0.064300,-0.122859,-0.355797,0.644480,-0.166294,0.013596,0.713761,0.219393,0.065718,-0.143412,0.278741,0.208620,0.085075,0.129571,0.187035,-0.278062,0.228353,0.132023,-0.040549,-0.234491,-0.066534,-0.016543,0.369714,0.716749,0.017073,-0.090232,-0.178739,0.311332,-0.122395,0.033555,0.005364,0.262469,0.140289,0.279556,0.226854,-0.121012,0.235840,0.045450,-0.065480,-0.353633,0.218570,0.463651,0.064370,-0.477688,0.439249,-0.218679,-0.215888,0.196945,-0.204136,0.107450,0.098406,0.031233,0.450780,-0.401180,0.375647,0.017114,0.287243,0.638379,0.074924,0.021231,0.114175,-0.361027,-0.226301,0.183240,-0.295014,-0.711502,0.053985,0.040645,0.021813,-0.035941,0.033760,-0.441547,0.041877,-0.154748,0.187225,-0.131578,-0.448122,0.061364,-0.308186,0.029868,-0.406673,-0.188864,-0.210131,0.042510,-0.318697,0.987065,-1.015809,0.075380,0.443226,0.200884,-0.611118,0.701298,0.127501,0.142716,-0.335464,-0.170846,0.016667,-0.355076,-0.112000,-0.263421,0.280131,-0.123106,-0.177656,-0.078175,0.114641', '25922902', '6963575', '35030151', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3445526', '白银帝国', '剧情', '本片以清末民初富可敌国的山西天成元票号的传承为主线，再现了“中国华尔街”金融业的百年兴衰。故事以一个风烛残年老人的回忆贯穿全片：天成元掌门人康老爷（张铁林 饰）膝下共有四子，但老大天生罹患聋哑残疾，老二生性莽撞好斗在一次意外中下肢瘫痪，老四因新婚娇妻在天津被劫惨死而疯癫，只剩下老三（郭富城 饰）可以继承祖宗家业。但康三却对父亲抱有深深的怨恨，原因是他夺走了自己昔日恋人（郝蕾 饰）。康老爷希望她可以为康家添丁，继承香火，但是她誓死不从。康夫人曾多次对康三表露心迹，但后者始终对继母礼让三分，不敢越雷池半步。康老爷见北京分号戴掌柜才智过人，遂恩威并用计赚邱掌柜（丁志诚 饰），令其死心塌地辅佐少主，然而康三心中却另有打算……本片根据成一的小说《白银谷》改编。©豆瓣', '郭富城', '姚树华', 6.3, 38177, 'tt1362045', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1025980415.jpg', 2.1, 13.3, 55.4, 23.8, 5.4, '-0.325620,0.090457,-0.430373,0.479650,0.029736,-0.421072,0.416829,0.303974,-0.679465,-0.388694,0.133514,0.593719,0.043774,0.144453,-0.176990,0.024601,0.250508,-0.181456,0.075859,-0.035527,0.206864,-0.362866,0.155633,-0.273564,-0.312904,-0.063922,0.445107,0.104590,-0.216126,0.222363,0.230457,0.274085,0.030129,0.026930,-0.351162,0.309643,-0.168137,-0.086265,-0.462717,-0.024041,0.173178,-0.262303,-0.164752,0.359696,0.015317,0.372658,0.476435,-0.247385,0.001643,-0.172404,0.310614,0.172655,-0.224540,0.094989,0.267918,0.094895,0.260567,0.431317,-0.048478,-0.199730,0.075397,0.043761,-0.498120,-0.106134,0.384403,0.196731,-0.554334,0.341512,-0.104461,0.003512,-0.407126,-0.229591,0.087077,0.036948,-0.012821,0.015223,-0.183844,0.127913,-0.562543,0.375173,0.364924,-0.142047,-0.165920,0.304404,-0.008660,-0.230096,0.254636,-0.574068,-0.544993,0.121420,0.018354,0.006089,0.327411,0.271841,-0.105537,-0.162466,-0.418401,0.329015,0.146281,-0.154229,-0.008922,0.002402,-0.322010,-0.563867,-0.076209,0.046480,0.355751,-0.204823,0.602280,-0.395827,0.157229,-0.044900,0.275859,-0.710492,0.671259,0.168550,0.081509,-0.400660,0.004396,0.030156,-0.005462,-0.219779,0.238338,-0.094983,-0.225175,-0.065694,0.116452,0.187987', '10561880', '10540066', '4004731', '3319776');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3445575', '关于伊丽', '剧情', '在德国生活着很多伊朗人，阿莫德就是其中一个。在阿莫德回祖国度假的时候，他偶遇了美丽的幼儿园老师伊丽，刚刚离婚的他很快坠入了情网。就他还没来得及发动爱情攻势的时候，伊丽就离奇的消失了。大家伙开始分头寻找，直到法院介入了这桩案件，也未能找到什么线索，伊丽还是没有回来……', '格什菲·法拉哈尼', '阿斯哈·法哈蒂', 8.1, 7399, 'tt1360860', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p857168883.jpg', 0.3, 1.4, 15.9, 57, 25.4, '0.523084,0.170505,-1.079100,0.541440,-0.363947,-0.558510,0.721141,0.007445,-0.402401,-0.287633,-0.045108,0.507809,-0.286493,0.261813,-0.001459,0.208287,-0.588080,-0.744296,0.114061,-0.095582,-0.584363,-0.518884,-0.040197,-0.121451,0.145310,-0.143340,0.233105,0.264149,-0.194754,0.190109,-0.042009,-0.031760,-0.092747,0.937612,-0.523817,0.379603,0.356425,0.096100,-0.095170,0.248906,0.540262,-0.456566,-0.329027,0.305730,0.148672,0.508420,0.647699,0.003273,0.072012,0.145480,0.026783,-0.280083,0.145243,0.179828,0.464050,-0.433009,0.034353,0.151099,-0.274524,-0.103397,-0.109356,-0.120231,-0.601055,0.142216,-0.317592,0.312162,-0.588462,0.317007,-0.336526,0.164337,0.258918,-0.630548,0.154245,0.544715,0.096917,0.194210,-0.065869,-0.050767,-0.846843,0.314216,0.874452,-0.115623,-0.463423,0.739143,-0.074065,-0.480565,-0.048314,0.421765,-0.099735,-0.076379,0.758726,0.025108,-0.451846,0.205244,-0.463773,-0.079647,-0.507534,-0.347389,0.086205,-0.283398,-0.194004,-0.522005,-0.144346,-0.164183,-0.445517,0.352705,-0.107000,0.092857,0.616621,-0.774618,0.257342,0.865034,0.382174,-0.384770,0.548541,0.051016,-0.015290,-0.047844,0.331768,0.201555,-0.194814,0.550982,0.414565,0.368818,0.290305,-0.237656,-0.410830,0.642018', '1947080', '2002683', '25870679', '2078159');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3445586', '伤心的奶水', '剧情', '2000年，秘鲁总统藤森宣布辞职，他的极权统治也从此结束。然而，因连年的恐怖袭击和高压统治，底层百姓的身心已经承受无数创伤。秘鲁境内某偏远山区，少女法斯塔（Magaly Solier 饰）的母亲年轻时曾遭到恐怖分子的强暴，继而感染一种名为“伤心的奶水”的怪病。病入膏肓之际，母亲独独担心因哺乳而可能受到传染的法斯塔。母亲去世，法斯塔远离家乡和悲伤，来到小镇上一个女钢琴家的别墅打工。她似乎对周遭一切都不关心，只一心关注自己随时可能失去的生命，和前景模糊的未来……本片荣获2009年柏林国际电影节金熊奖及国际影评人费比西奖、2009年瓜达拉哈拉墨西哥电影节最佳影片和最佳女主角（Magaly Solier）奖。©豆瓣', '玛佳丽·索利埃', '克劳迪亚·略萨', 7.3, 5643, 'tt1206488', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p452590442.jpg', 0.9, 4.4, 37.1, 42.6, 15, '-0.160215,-0.110412,-0.589720,0.369463,0.282647,-0.060826,0.377324,0.120645,-0.479431,-0.379828,0.091757,0.865303,-0.061811,0.096357,0.383397,0.067824,-0.292491,-0.622738,0.008415,-0.001281,-0.120119,-0.165638,-0.274272,-0.170778,-0.310711,-0.728083,0.567311,0.419093,-0.118650,0.475232,0.090696,0.407633,0.155476,0.333440,0.129656,0.001221,0.202721,-0.108794,-0.306938,0.168944,-0.037472,-0.275210,-0.255958,0.143112,-0.029979,0.374989,0.464844,-0.118423,-0.174666,-0.486718,0.669467,-0.431325,-0.008579,0.167908,0.188369,-0.054501,0.271041,0.246284,-0.392581,-0.019095,0.058882,-0.311546,-0.475111,-0.119001,0.311544,-0.035347,-0.297584,0.514903,-0.081338,0.070864,-0.133996,-0.098138,0.268747,0.403820,0.037348,0.517129,-0.154694,0.160955,-0.300267,0.266306,0.758657,-0.246688,-0.587406,0.023121,-0.233032,-0.473182,-0.053380,-0.548197,-0.605930,0.236698,-0.050138,0.074048,-0.236046,0.533018,-0.285082,0.028091,-0.355984,-0.365896,0.013014,-0.050790,-0.212048,-0.574612,0.004725,-0.202183,0.069298,-0.074940,0.169367,-0.036924,0.640474,-0.500054,0.674744,0.342184,0.409143,-0.552873,0.646080,0.029575,0.122542,-0.224595,-0.281753,0.702775,-0.192745,0.058188,-0.179421,-0.223188,-0.153313,-0.063506,-0.036029,0.375586', '25721544', '30162520', '1297368', '1780122');
