INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3445906', '古墓丽影：源起之战', '动作', '劳拉（艾丽西亚·维坎德 Alicia Vikander 饰）的父亲一生都致力于研究古墓，在劳拉尚且年幼的时候，父亲在一场冒险之中失踪了。一晃眼多年过去，劳拉一直拒绝承认父亲已死的消息，也拒绝接手父亲手下的商业帝国。一次偶然中，劳拉发现了父亲遗留下的冒险笔记，父亲希望劳拉能把这些资料付之一炬，但为了寻找父亲的下落，劳拉决定寻找笔记中记载的岛屿。劳拉找到了名为陆仁（吴彦祖 饰）的男子，两人结伴踏上了旅途。刚一上岛，劳拉和陆仁就遇见了一直和父亲作对的马赛亚斯（沃特·戈金斯 Walton Goggins 饰）以及他的雇佣兵团队。马赛亚斯一心想要找到古墓的踪迹，不惜杀死了不肯透露半点消息的劳拉的父亲，如今，劳拉亦落入了他的魔爪之中，会遭遇怎样的命运呢？©豆瓣', '艾丽西亚·维坎德', '罗阿尔·乌索格', 6, 143353, 'tt1365519', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2512717509.jpg', 2.6, 19.4, 57.4, 17, 3.6, '0.008222,0.065065,-0.749205,0.666966,-0.114691,-0.459775,0.318542,-0.181472,-0.778097,-0.285493,0.168950,0.966414,0.053566,0.118136,0.278847,0.292290,-0.408767,-0.577745,0.002513,-0.244676,-0.231008,-0.609832,-0.344552,-0.179032,-0.103422,-0.375384,0.589519,0.061720,-0.165255,0.428157,0.223829,0.190327,-0.414071,0.378165,0.092354,0.103098,0.310945,0.130154,-0.353171,0.346644,0.152951,-0.151639,-0.122723,0.256812,0.185985,0.426287,0.508948,-0.218307,0.091116,-0.119348,0.123907,-0.140150,0.147361,-0.089865,0.291793,-0.086196,0.247623,0.527811,-0.268047,-0.283146,0.107684,0.055670,-0.518682,-0.005354,0.227731,0.168182,-0.790666,0.113378,-0.217973,0.004821,0.100099,-0.518128,0.308140,0.556505,0.338097,0.182049,-0.076388,-0.078797,-0.342466,0.093100,0.499439,-0.354328,0.149946,0.055736,-0.095895,-0.248183,0.071131,-0.155788,-0.467153,0.102942,0.381210,0.143203,-0.383552,0.339680,-0.488665,-0.080956,-0.496106,-0.095478,0.133000,-0.363887,-0.118640,-0.397711,-0.056602,-0.146427,-0.394589,-0.093501,0.004675,-0.237669,0.484479,-0.669517,0.376429,0.433431,0.322080,-0.335708,0.649304,0.111846,0.117285,-0.191386,0.210664,0.467638,0.286293,0.238688,-0.046250,-0.008185,0.332612,-0.473235,-0.452539,0.244812', '1309069', '21354767', '35461732', '34968329');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34460763', '亲爱的新年好', '剧情', '离乡打拼的白树瑾（白百何饰）早年间为了有个更好的生活，放弃了向往的图书行业，转行成为地产经纪，不想工作成果惨淡，职场遭遇劲敌。到北京的第十个年头，白树瑾屡遭挫折，面临事业停滞、情路不顺、房租暴涨、母亲病情加重等多重打击，此时初到大城市打工的合租室友女孩（张子枫饰）突然闯入她的生活，在这个女孩的身上白树瑾似乎找到了十年前的自我，同时她也遇见了小七岁的同事仲要（魏大勋饰），渐渐地她开始有了变化……', '白百何', '彭宥纶', 5.5, 71206, 'tt11157590', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2578723424.jpg', 7.7, 30.4, 44.9, 13.3, 3.8, '-0.075486,-0.081709,-0.730876,0.189670,-0.216975,-0.474552,0.658163,0.264247,-0.597593,-0.365046,0.331418,0.525235,-0.130482,0.568453,0.259864,-0.158451,-0.105647,-0.582957,0.199074,-0.160882,-0.119447,-0.051527,-0.239959,-0.138728,-0.461250,-0.116788,0.801410,0.286393,-0.226668,0.237940,0.014102,0.080386,0.187338,0.481496,-0.284499,0.138062,0.006409,0.240355,-0.253141,0.062226,0.189842,-0.350099,-0.049190,-0.212633,0.290550,0.489314,0.618195,0.365136,-0.367773,-0.109770,0.562052,0.010487,-0.387829,-0.102932,0.396044,0.285067,0.190284,-0.009003,-0.350813,-0.158950,-0.245114,-0.274646,-0.513276,0.027296,0.287534,0.028805,-0.724351,0.386342,-0.051379,-0.261321,-0.080044,-0.350124,-0.051714,0.809100,0.343577,0.417708,-0.210248,0.467981,-0.289432,0.263668,0.862664,-0.083177,-0.395216,0.447679,-0.259010,-0.336111,-0.045622,-0.296570,-0.441696,-0.064160,0.201320,0.000879,-0.285102,0.536938,-0.606034,0.171110,-0.052290,-0.172513,0.139822,-0.210709,-0.390179,-0.262460,-0.267387,-0.242687,-0.145942,0.207496,0.074822,-0.435109,0.623660,-0.961736,0.234221,0.546283,0.566968,-0.616988,0.409165,-0.050517,0.193394,-0.325995,-0.038477,0.567877,-0.552386,0.549846,-0.064258,-0.054594,-0.267896,-0.090631,-0.313847,0.545221', '35030151', '30345227', '4728584', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34461680', '要强的人', '剧情', '该片讲述卢卡斯前往智利南部的一个偏远小镇探望他的姐姐。在海雾前，他遇到了当地渔船上的船长安东尼奥。当他们之间的情感越来越强烈时，他们的力量、独立性与成年期，在浪潮面前就变得不可动摇。', '塞穆尔.冈撒勒斯', '奥马尔·苏尼加·伊达尔戈', 7.6, 8145, 'tt9187214', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2580347406.jpg', 0.6, 3, 31.4, 47.7, 17.3, '0.433774,0.141696,-1.188520,1.037544,0.287742,-0.270411,0.935048,0.227302,-0.485436,0.090523,0.035863,1.097921,0.079778,0.360307,0.270688,-0.030388,-0.458586,-0.625060,-0.338061,-0.138050,-0.269148,-0.381026,-0.555475,-0.057573,-0.153614,-0.325809,0.489511,0.152945,-0.429469,0.481217,-0.013401,0.055944,-0.027038,0.738504,-0.331981,-0.084869,0.185135,0.051334,-0.188356,0.203034,-0.103109,-0.221686,0.233564,0.181831,0.099488,0.282761,0.649900,-0.132957,0.031116,-0.176767,0.126318,0.024897,0.290355,0.250496,0.451094,0.110121,0.036171,0.083035,-0.431131,-0.186486,-0.389187,-0.203758,-0.511196,0.246405,-0.228809,0.303826,-0.412849,0.142569,0.132493,-0.175892,0.088707,-0.587855,0.267595,0.267357,-0.183747,0.242330,-0.330156,-0.055395,-0.359105,-0.207771,0.995748,0.059652,-0.336213,-0.083791,-0.348678,-0.498558,-0.034877,-0.137889,-0.407187,-0.261180,0.375719,-0.029731,-0.302167,0.395188,-0.977930,0.127899,-0.233629,-0.198163,-0.205036,-0.017446,0.003730,-0.847329,-0.241329,-0.716675,-0.182791,0.133009,0.115887,0.088980,0.706737,-0.632038,0.375240,0.906818,0.633849,-0.044572,0.555065,0.045924,0.226648,0.059213,0.138626,0.154796,-0.268117,0.554753,0.025486,0.387043,-0.289511,0.256327,-0.147018,0.713154', '1293019', '30162520', '3606973', '35161768');
