INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34462037', '鲁邦三世 The First', '喜剧', '《鲁邦三世》首度以3DCG制成的电影版作品，那个大名鼎鼎的亚森‧鲁邦唯一失手的秘宝「布列松日志」，传说若能解开日志之谜，就会获得庞大的财宝。瞄准了这个目标的鲁邦，邂逅热爱考古学的少女蕾蒂西亚，两人决定合力解开谜团。然而，企图得到布列松日志的秘密组织研究人员‧兰贝尔，以及操控组织的神秘男子‧杰洛特却阻挡住两人的去路……。隐藏在布列松日志里令人震惊的真相究竟是！？巴黎、墨西哥、巴西——前所未有的大规模夺宝战即将开幕！', '栗田贯一', '山崎贵', 7.6, 7199, 'tt10621032', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2570280248.jpg', 0.5, 2.6, 31.1, 46.2, 19.5, '0.331281,0.240189,-0.601737,0.494920,0.459292,0.000674,0.504986,-0.283321,-0.073702,-0.415604,0.229237,0.467992,-0.350919,-0.167419,0.278261,0.234426,-0.348062,-0.441647,-0.012137,-0.326997,-0.317815,-0.282036,-0.670448,-0.279115,0.046554,-0.444684,0.913269,0.174817,-0.439677,0.068952,0.583454,0.937476,-0.381116,0.033489,0.036439,-0.133576,0.289328,-0.186484,-0.399720,0.289180,-0.220621,-0.166552,-0.153997,0.458447,-0.087132,0.041181,0.662264,-0.558550,0.106048,0.156609,0.221669,-0.292281,-0.160201,-0.326123,0.155760,0.022978,-0.211805,0.192382,-0.052122,-0.071348,-0.010859,-0.255657,-0.676821,-0.380743,0.340132,0.196494,-0.402360,0.190023,-0.285896,0.103829,-0.026705,-0.516876,0.211157,0.564982,0.253571,0.055808,0.208391,-0.035278,-0.408528,-0.034207,0.249284,-0.245916,-0.309144,0.072902,-0.201750,-0.498079,-0.242168,-0.119095,-0.221768,0.271830,0.427018,0.330320,0.123572,0.404759,-0.676771,-0.234815,-0.602884,0.016373,0.141294,-0.391153,-0.183136,-0.969978,-0.338418,0.270903,-0.101868,0.208873,-0.052473,-0.625991,0.669368,-0.644517,0.194967,0.559482,-0.072743,-0.167422,0.046049,-0.022597,0.335075,-0.222790,-0.356689,0.258702,0.086253,0.272525,0.040013,0.396160,-0.053187,-0.414084,-0.458055,0.416565', '2369613', '4014397', '20274039', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34462775', '#活着', '动作', '讲述突然被不明病毒感染，并失控扩散的城市中，被孤立的幸存者身上发生的故事。刘亚仁将在片中饰演因与世隔绝而幸存的游戏玩家俊宇一角，朴信惠饰演直面极端情况，寻找新的生存方式的幸存者宥彬一角。', '刘亚仁', '赵一亨', 5.7, 112540, 'tt10620868', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2604626010.jpg', 6, 25.9, 49.3, 14, 4.8, '0.734302,-0.222841,-0.465634,0.461196,0.271659,0.626876,0.851784,0.052066,-0.571450,-0.278128,0.584751,0.596608,-0.461837,-0.083438,0.229960,-0.325156,-0.282268,-0.836597,-0.580452,-0.045146,-0.606261,-0.239131,-0.335740,-0.137019,0.045678,-0.301866,0.943756,0.250179,-0.724645,0.427526,0.198369,0.765573,-0.877327,0.606058,0.398964,-0.163991,-0.211410,-0.174919,-0.220583,0.109154,-0.280522,-0.496149,0.080103,0.124225,-0.260253,0.614202,1.201820,-0.571346,-0.112316,-0.117715,0.077867,-0.371011,-0.206480,-0.046301,0.258715,0.147230,0.069118,0.334371,0.077440,-0.180290,-0.015711,-0.119378,-0.870274,0.012097,0.222151,0.515335,0.007110,0.248568,0.217775,-0.127286,0.200379,-0.003311,0.449372,-0.021424,0.547562,0.574690,-0.329075,-0.261873,-0.046567,0.429343,0.416543,-0.291384,-0.563658,0.544481,-0.541141,-0.427070,-0.128266,-0.219240,-0.657332,0.154917,0.094201,0.337517,-0.488440,0.627576,-0.614539,0.246742,-0.370371,-0.668872,-0.132352,-0.240789,-0.325324,-0.712360,-0.487227,0.236675,0.343388,0.013814,-0.233689,-0.489397,0.704100,-0.690741,0.181676,0.637177,0.545167,-0.505838,0.160727,-0.325118,0.391200,-0.002300,-0.109494,0.529551,0.023451,0.299351,-0.147066,0.048118,-0.615188,-0.155127,-0.457282,0.303276', '25774050', '26759820', '10467125', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34463995', '米纳里', '剧情', '故事发生在20世纪80年代的美国，美籍韩裔男子雅各布（史蒂文·元 Steven Yeun 饰）带着妻子莫妮卡（韩艺璃 饰）和两个孩子大卫（Alan S. Kim 饰）、安妮（Noel Cho 饰）一起从熟悉的西海岸搬到了偏僻而又陌生的阿肯色州。虽然对于丈夫的这一决定，莫妮卡的心中十分的反对，但她拗不过雅各布的坚决和顽固，只得被迫夫唱妇随。蛮荒之地的生活既不舒适也不有趣，在最初的新鲜感过去之后，大卫和安妮很快就开始怀念起过去的生活了。之后，孩子们的外婆也来到了他们的身边，给这个家庭带来了一丝热闹的气息。雅各布没有发现的是，当他将越来越多的时间和精力投入到开发农场这件事情上时，他和妻子之间的距离就越来越远。©豆瓣', '史蒂文·元', '李·以萨克·郑', 7.3, 23744, 'tt10633456', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2630505948.jpg', 0.4, 2.7, 38, 47.5, 11.4, '0.537269,-0.072161,-1.114199,0.681798,-0.212112,-0.434863,1.153769,0.048365,-0.673250,-0.143998,-0.124931,0.869972,-0.069315,0.413581,0.238361,0.262600,-0.523709,-0.637898,-0.160197,-0.233944,-0.462763,-0.520531,-0.098928,-0.148788,-0.283339,-0.190955,0.463173,0.039798,-0.073033,0.647123,0.228474,0.110182,0.027472,0.793059,-0.356127,0.135856,0.014216,0.049153,-0.152460,0.137600,0.483263,-0.111565,-0.226329,0.251985,0.203989,0.373894,0.718589,-0.049057,-0.320655,0.134563,0.285150,-0.071415,-0.146463,0.070073,0.155405,0.034667,0.275103,0.117693,-0.305022,0.009047,-0.024858,-0.057509,-0.567376,0.543546,0.047732,0.185656,-0.602397,0.587453,-0.121680,-0.337621,0.116328,-0.674618,0.234181,0.441990,-0.008218,0.506052,-0.380087,0.176207,-0.556800,-0.026479,0.854186,0.117532,-0.272578,0.602024,-0.310886,-0.417316,-0.249646,-0.117638,-0.499024,-0.152591,0.336627,0.116333,-0.210349,0.251033,-0.737031,0.150120,-0.079641,-0.306658,0.217067,-0.421298,0.012546,-0.392987,-0.254964,-0.822043,-0.462692,0.103110,0.094626,-0.175594,0.836406,-0.763399,0.223682,0.504072,0.419078,-0.341027,0.552969,0.026430,0.281903,-0.108469,0.165622,0.138351,-0.194005,0.333062,0.307553,0.635817,0.027180,-0.311605,-0.487601,0.654993', '3111650', '34461680', '1769507', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3447563', '保姆奇遇记', '喜剧', '诺亚•格里芬（乔纳•希尔 Jonah Hill 饰）是一个肥肥胖胖长的有些腼腆憨厚的大男孩，没有保姆经验的他因为妈妈的约会而不得不临时代替她去佩杜拉太太家做保姆的工作。佩杜拉太太有三个性格古怪的孩子，长相俊美的斯拉特是个同性恋，酷爱打扮的布莱斯总是喜欢浓妆艳抹，而罗德里格则是一个喜欢破坏的顽皮领养生。三个难对付的孩子让诺亚十分头疼，而与此同时他接到了女友玛丽萨以做爱为诱惑邀请他一起参加派对的电话。诺亚决定带上三个小孩一同前往，却不料在途中为女友买毒品的过程中，不仅三个孩子状况百出争吵不断，罗德里格更是顺手带走了毒贩卡尔装满卡洛因的罐子令四人引祸上身。而更加危险的意外是，罐子在争抢的过程中摔碎了。诺亚四人只得齐心协力，为了活命开始了逃亡之旅…©豆瓣', '乔纳·希尔', '大卫·戈登·格林', 6, 5723, 'tt1366344', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1520869227.jpg', 3.4, 19.1, 55, 17.5, 5, '0.384788,-0.138656,-0.480654,0.374532,-0.526998,-0.431457,0.725409,0.284437,-0.404920,-0.296413,0.136640,0.694410,0.038682,0.246733,0.138952,-0.031211,-0.074112,-0.297056,-0.095904,0.073760,-0.193346,-0.468831,0.044295,-0.424492,0.014129,-0.419769,0.310894,-0.248581,0.061085,0.542159,0.435329,0.167848,-0.139697,0.380262,-0.286743,-0.056652,0.087556,-0.164962,-0.097961,0.338854,0.058357,0.009341,-0.131830,0.244403,0.148326,0.562140,0.556628,-0.209716,-0.095277,-0.088873,0.336610,-0.161659,-0.231468,0.016405,0.272175,-0.056976,0.422373,-0.207178,-0.218232,0.052233,0.397985,-0.091719,-0.546885,0.282742,0.231706,0.228541,-0.608926,0.257844,-0.066375,-0.085707,0.326182,-0.345945,0.109308,0.205267,0.222711,0.435491,0.017715,0.187884,-0.355179,-0.042824,0.533061,0.043847,0.086262,0.384124,-0.361800,-0.158841,0.367092,-0.308022,-0.581221,0.106362,0.208501,-0.237264,-0.067282,0.179708,-0.619128,0.047257,-0.267596,-0.089736,0.023837,-0.330242,-0.132697,-0.424831,0.121443,-0.281272,-0.247712,0.065166,0.124627,-0.069031,0.633061,-0.666048,0.113199,0.674500,0.016305,-0.473321,0.572767,0.185760,0.125161,-0.180977,-0.003881,-0.078774,0.009903,-0.121681,-0.033315,0.571712,0.026953,-0.226897,-0.462104,0.268726', '2002744', '4847665', '3326747', '1304942');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3447591', '保持爱你', '爱情', '本片由叶念琛导演和编剧，讲述14个男女之间在情人节发生的5段爱情关系。爱情试用期风（胡清蓝 饰）琪（唐素琪饰）开始交往琪却不肯公开，还订下了爱情三个月试用期。情人节正好是试用期满的日子，风会修成正果吗？无声胜有声视音乐为生命的歌手伟（侧田 饰）爱上了开花店的宝（邓丽欣 饰）。情人节录了一首歌打算表白，却被告知宝有弱听。这段感情会开花吗？一日情人龙和虎从谈过恋爱，两个希望找一个女孩一起过情人节。在网上认识的女孩金鱼（杨爱瑾 饰）愿意给二人当一日情人。这个情人节会有奇迹发生吗？最后晚餐祖（梁祖尧 饰）和芳（谢安琪 饰）相恋七年发现彼此不和，决定共进情人节晚餐后分手。但前尘往事又一次涌上心头。他们会不会分手？分身大情圣辉（森美 饰）计划利用了四位女友背境上的特点，预备在情人节的早餐，午饭，下午茶和晚饭时间分别相聚。可一切渐渐失控……©豆瓣', '邓丽欣', '叶念琛', 6.7, 20919, 'tt1365441', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p933936290.jpg', 1.5, 9.1, 48.9, 31.6, 8.8, '0.125964,-0.117850,-0.391730,0.494072,0.296197,-0.170481,0.440276,0.018085,-0.097688,-0.398776,-0.398548,0.569325,-0.814393,0.507702,0.441397,-0.111933,0.037084,-0.912883,0.308550,-0.132380,-0.254643,-0.457771,0.296178,0.082872,0.034557,0.037223,0.523347,0.025195,0.281604,0.560795,0.668058,-0.223904,-0.183581,0.301913,-0.177955,0.064036,0.005131,0.578569,-0.575171,0.046753,-0.001867,-0.263388,0.088277,0.119458,0.270508,0.154386,0.613409,-0.109179,-0.214982,0.074441,0.345300,-0.032498,-0.143389,-0.022699,0.303089,-0.070908,0.398585,0.543932,-0.109454,0.008553,-0.260169,-0.261342,-0.397784,0.223047,-0.161113,-0.118950,-0.344533,0.568317,0.015386,0.335213,-0.022979,-0.162339,0.219202,0.388624,0.220442,0.514564,0.049620,-0.003513,-0.483580,0.443290,0.952743,-0.078680,0.112453,0.832466,0.000549,-0.194129,-0.206055,0.342246,-0.271296,0.361695,0.000190,0.202101,-0.319492,-0.077048,-0.626662,-0.157201,-0.140484,0.142116,0.517849,-0.401649,-0.025128,-0.641565,-0.086384,-0.381241,-0.346132,0.228720,0.152913,-0.247315,0.515596,-0.867144,0.180634,0.196423,0.289552,-0.682891,0.780169,0.429142,-0.269150,-0.516312,0.253544,0.148900,-0.206381,-0.372269,0.397329,0.229894,0.006749,0.256860,-0.455844,0.045954', '25777330', '26687241', '4301278', '26930504');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3447595', '爱得起', '喜剧', '陈丽娜（梁咏琪 饰）在广州工作,认识了会计师于晓东（邵兵 饰）。恋爱之后,晓东向丽娜求婚，二人想在香港补摆喜酒,丽娜索性辞去工作回港安排。晓东的弟弟于日东（陈柏霖 饰）在香港任职航行公司地勤经理,有自己的住所,为了节俭,丽娜搬去和日东同住,睡在客房。好事多磨，晓东的女秘书暗恋了他八年，突然示爱！晓东心猿意马，反省之后，发现自己不是一个好丈夫！强烈良心责备之下暗暗悔婚，向丽娜提出离婚！丽娜如跌入深渊，留在日东家，无法面对，终日神不守舍。日东还帮忙善后，代晓东向丽娜的家人和朋友致歉，并鼓励丽娜与其忧愁苦恼，不如面对现实，和晓东分开，重新站起来。二人继续一起生活，像兄妹和知己，互相扶持着。渐渐，两人之间有了爱意，可日东却总把情绪抑压在心里。最终，这一对有情人是否可以跨越内心的障碍，携手走下去？©豆瓣', '梁咏琪', '马伟豪', 5.7, 17166, 'tt1365493', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2372795056.jpg', 5.4, 23.6, 55, 13.2, 2.8, '0.129226,-0.234197,-0.489756,0.088635,0.114865,-0.487130,0.425361,0.505959,-0.428615,-0.089899,0.014946,0.634213,-0.001147,0.423690,0.178867,-0.082237,-0.601443,-0.675316,0.187554,0.031009,0.043689,-0.596772,0.269988,-0.049543,-0.033538,-0.087103,0.335065,-0.254729,0.142595,0.642840,0.143888,-0.068907,-0.338801,0.514112,-0.139786,-0.019070,0.147887,0.261302,-0.903030,0.115418,0.223394,0.110122,-0.174466,-0.166276,0.375942,0.035097,0.346238,0.223916,-0.286628,0.156219,0.027212,-0.139342,-0.033298,0.197100,-0.005030,-0.003985,0.287171,0.249925,-0.457458,0.099817,0.160322,0.037051,-0.349495,0.213093,-0.079170,0.095410,-0.477743,0.450872,0.026319,-0.074013,0.162840,-0.462074,0.003965,0.520835,0.094845,0.331292,-0.320278,0.191015,-0.252282,0.158578,0.802490,0.181388,0.134881,0.298325,0.108838,0.017008,0.192753,0.303191,-0.387688,-0.290164,-0.021985,0.221534,-0.208585,0.015132,-0.491687,-0.083739,-0.214040,0.039331,0.134517,-0.699195,0.025748,-0.300766,-0.266676,-0.227491,-0.298213,-0.034991,0.212441,-0.160938,0.224071,-0.784364,0.157735,0.421460,0.693711,-0.551351,0.739365,0.431122,0.007081,-0.305686,0.292788,0.100243,-0.439742,0.265468,0.207011,0.164009,-0.045512,0.251823,-0.465731,-0.126543', '35683855', '1291842', '3313801', '1302987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3448362', '鱼的故事', '喜剧', '四个时间段，四段不同年龄段的人不同的生活片段，四个看似独立的故事，可冥冥之中却被串联起来，成了改变世界的最强音。改编自作家伊坂幸太郎的同名小说，看一首朋克如何拯救地球。1975年，逆鳞乐队正在录制他们的最后一张专辑，主唱五郎（高良健吾 饰）和团长繁树（伊藤淳史 饰）抱着复杂的心情把专辑命名为《鱼的故事》；1982年，大学生们盛传着关于专辑《鱼的故事》的恐怖传说，平日里胆小的大学生雅史（滨田岳 饰）在夜晚回家的出租车上听到了这首，然后遇到了改变他人生的事；2009年，一艘轮渡载着旅客和少女麻美（多部未华子 饰）在海上行驶，却遇上了劫持轮渡的歹徒，可这时，正义使者（森山未来 饰）出现了；2012年，距离世界末日的最后五小时，奇迹却在这时出现……©豆瓣', '伊藤淳史', '中村义洋', 8, 6337, 'tt1244666', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p739307699.jpg', 0.6, 2.5, 21.7, 47.4, 27.7, '0.218221,0.152924,-0.220900,0.605473,0.326301,0.038990,0.797106,0.201916,-0.535650,-0.242892,0.120967,0.500638,-0.436608,0.238611,0.500303,-0.004958,-0.397078,-0.592188,-0.023218,-0.034684,-0.186188,-0.300358,-0.209589,0.016274,-0.043619,-0.379312,0.614792,0.116972,-0.005620,0.526186,0.201085,-0.006576,-0.286760,0.012696,-0.159733,0.080143,-0.016721,0.239380,0.099436,0.071784,-0.360572,-0.236759,-0.296962,-0.135886,-0.251371,0.207748,0.867848,-0.248421,-0.082500,0.155985,0.545407,-0.119821,-0.284081,-0.252501,0.231913,0.158998,0.183318,0.248440,0.040449,0.026949,-0.147634,-0.019133,-0.569060,0.069156,-0.062903,0.349779,-0.517034,0.527323,-0.114046,0.072378,0.163340,-0.320807,0.175331,0.034467,0.399732,0.568046,-0.104030,0.201188,-0.592597,0.449863,0.724718,0.094737,-0.256760,0.334602,-0.044036,-0.443487,-0.496769,-0.167484,-0.512120,0.141368,0.064937,-0.150681,-0.275287,0.097635,-0.824716,-0.020934,0.006562,-0.260948,0.192087,-0.332132,-0.461487,-0.472106,0.061631,-0.280022,-0.193020,0.285387,0.152583,-0.201199,1.112555,-0.624006,0.155977,0.508705,-0.082099,-0.045022,0.919786,0.000731,-0.172745,-0.261754,0.059748,0.028025,-0.231655,0.279335,0.098858,0.253415,-0.289028,-0.249347,-0.541546,0.482047', '1302661', '3811356', '4181031', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3450086', '白昼冷光', '动作', '在华尔街经营一家公司的年轻商人威尔（亨利·卡维尔 Henry Cavill 饰）从百忙之中抽身，飞往西班牙一处海滨小镇与家人度假。事隔多年，他与父亲马丁（布鲁斯·威利斯 Bruce Willis 饰）、母亲、弟弟乔什（莱菲·盖夫隆 Rafi Gavron 饰）及其女友达 拉（艾玛·汉密尔顿 Emma Hamilton 饰）相聚。家人围坐餐桌，其乐融融。但是祥和的气氛很快便被破坏，威尔接到公司破产的电话，心情糟糕到极点，由此也与家人的关系紧张起来。航海途中达拉意外受伤，当威尔去镇上买药期间，留在船上的家人却遭到绑架。焦急的威尔在当地无人可信，他独自搜索家人的下落，在此过程中竟发现了关于父亲和事件背后的诸多秘密……©豆瓣', '亨利·卡维尔', '马布鲁克·埃尔·梅奇', 5, 8409, 'tt1366365', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1287429626.jpg', 10.4, 40.8, 40.2, 6.7, 2, '0.156676,-0.086743,-0.671164,0.075121,0.028340,-0.233139,0.575091,0.529122,-0.621924,-0.326674,0.155387,0.951562,-0.075108,0.063212,0.574103,0.179345,-0.556411,-0.404893,0.255525,0.149509,0.193104,-0.568424,-0.279882,-0.342635,0.051446,-0.299766,0.164071,0.093881,-0.214203,0.841369,-0.229621,0.533673,-0.554124,0.578433,-0.015370,0.152158,0.334504,-0.178989,-0.460952,0.075269,-0.114523,-0.216092,-0.156743,0.154373,0.319176,0.329836,0.474943,0.269712,-0.102993,0.122828,-0.060318,-0.022286,0.093331,-0.010724,0.362138,-0.212169,0.572325,0.394512,-0.279945,-0.301436,0.078490,0.043362,-0.356606,0.343121,-0.038769,0.203229,-0.401088,0.218631,-0.361934,-0.144287,0.167731,-0.571691,0.311560,0.538869,-0.115664,0.303079,-0.155251,0.076290,-0.469185,-0.016041,0.595187,-0.054721,0.324651,0.091841,0.098818,-0.176860,0.050521,-0.064380,-0.447021,-0.081228,0.443929,-0.030456,-0.053565,0.249558,-0.497955,-0.023514,-0.356925,-0.298901,0.221552,-0.202509,-0.086906,-0.921169,0.100228,-0.076384,-0.469670,-0.170167,0.078779,0.078060,0.183132,-0.528853,0.450766,0.390418,0.122264,-0.394223,0.536060,0.047087,0.416838,-0.038215,-0.162824,0.199175,0.183878,0.470085,-0.086545,-0.036321,0.004108,-0.273059,-0.435161,0.205999', '3036464', '1303333', '2075345', '4319218');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34608294', '再见，妈妈', '剧情', '为了父亲的移墓，定居美国长达九年的阿棕，睽违许久回到家乡。他带了伊恩一起回来，但全家族并不知道伊恩正是阿棕的男友，而此趟阿棕也正打算与母亲出柜。长久以来，母亲一直希望阿棕能够早点成家，让她可以抱孙子，就跟所有平凡的家庭一样。阿棕一直找不到最适当的时机开口，就在此时，他意外得知母亲罹患重病的消息……', '岭清', '郑霆黎明', 8.2, 18540, 'tt10641972', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2562967550.jpg', 0.4, 1.7, 19, 47.8, 31.2, '0.028850,0.003679,-0.640273,0.389458,-0.139307,-0.535850,0.212283,-0.053100,-0.869658,-0.775809,-0.288344,0.877320,0.143483,0.785779,0.234301,0.134927,-0.313352,-0.503044,0.054605,-0.282207,-0.167952,-0.345388,0.156731,-0.015903,-0.138912,0.014197,0.575492,-0.232020,0.092993,0.483799,0.165909,0.089367,-0.059307,0.582691,-0.575241,-0.102236,-0.397216,0.225706,-0.690573,0.267616,0.439311,-0.052800,-0.092993,0.299115,0.156544,0.061599,0.372159,0.039013,-0.055311,0.059849,-0.038662,0.007240,-0.030121,0.157744,0.321166,-0.403474,0.583212,0.371206,-0.225050,-0.155551,-0.044605,-0.187098,-0.576054,0.211370,-0.102659,0.139717,-0.530914,0.251457,-0.095420,-0.057431,0.356073,-0.663699,0.341279,0.756920,-0.073024,0.465139,-0.523273,0.240857,-0.361099,0.027319,0.598954,-0.292316,0.288734,0.383980,0.037285,-0.304224,0.249503,-0.153475,-0.517831,0.065662,-0.008969,0.359188,-0.343087,0.001946,-0.255294,-0.031615,-0.387299,-0.186247,0.525496,-0.445898,0.102826,-0.173596,0.038696,-0.192017,-0.120943,0.393436,0.049352,-0.201288,0.276043,-0.806954,0.623088,0.477653,0.426036,-0.667404,0.511755,0.235059,0.085253,-0.565504,0.181110,0.282141,-0.168063,0.194506,-0.028007,-0.144301,0.157363,-0.204940,-0.467615,0.300362', '1303485', '2122766', '30345227', '20471829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34614665', '静水城', '剧情', '影片围绕一个来自俄克拉荷马州的美国石油钻井平台钻工比尔(达蒙饰)展开。他不得不前往马赛，拜访他久未谋面却锒铛入狱的女儿(布雷斯林饰)，他的女儿坚称并没有犯下谋杀罪。面对语言的障碍、文化的差异，以及复杂的法律制度，比尔决意孤注一掷拯救他的女儿。而在这个过程中，他与一位当地的女性和她的小女儿建立了友谊，也开始了个人的探索之旅，并获得了更大的归属感。', '马特·达蒙', '汤姆·麦卡锡', 7.2, 14019, 'tt10696896', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2654990612.jpg', 0.7, 4.2, 42.5, 42.1, 10.6, '0.361718,0.054264,-1.007313,0.938430,-0.245401,-0.317250,0.903472,0.205518,-0.522158,-0.177514,0.340566,1.022306,0.117117,0.280699,0.110755,0.025481,-0.321785,-0.703089,0.091045,-0.030414,-0.152053,-0.699046,-0.373918,-0.321714,-0.285884,-0.245827,0.783444,-0.005458,-0.367826,0.457698,0.068045,-0.006431,0.149627,0.630130,-0.223414,-0.052201,0.093473,0.177284,-0.370125,0.048251,0.075742,-0.212647,-0.176466,0.340877,-0.205139,0.777354,0.497388,-0.416168,0.055824,-0.221551,0.406255,-0.300031,-0.042128,0.352432,0.156290,-0.201651,-0.063128,0.407612,-0.019430,-0.108940,0.049160,-0.270628,-0.961924,0.012716,0.101825,0.279121,-0.609997,0.616069,-0.227770,-0.184334,-0.259028,-0.317223,-0.118551,0.351152,0.062340,0.413779,-0.465879,-0.053132,-0.417306,0.194802,0.465113,-0.025057,-0.298432,0.216480,-0.529978,-0.721788,-0.172104,-0.258165,-0.362277,-0.222509,0.347242,-0.057043,-0.171158,0.370119,-0.866559,0.060088,-0.247544,-0.296082,0.075597,-0.421422,0.074020,-0.681891,-0.036737,-0.554157,-0.265818,0.083482,0.420382,-0.272791,0.803032,-0.871645,0.056488,0.495871,0.452585,-0.832208,0.510299,0.248297,0.181435,-0.322804,-0.388361,0.415664,-0.238726,0.294589,-0.101699,0.259297,0.175916,-0.165977,-0.256072,0.572193', '1769507', '3119246', '25932086', '35144311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34614704', '只有野兽', '悬疑', '一场暴风雪覆盖了通往法国偏远小镇的道路，一台空车停在路边，车主却不知去向。当地警方来到了小镇农场主人米歇尔的家中问话，米歇尔却显不耐；女主人艾莉丝一面对失踪事件感到好奇，但同时她更挂念着她的保险客户约瑟夫。年轻貌美的服务生玛莉咏在餐厅邂逅了谜一般的伊芙琳，两人很快陷入热恋。虽然年龄差距和身份地位都阻挡她们在一起，但玛莉咏靠着伊芙琳留下的只字片语，花了好几天徒步走到伊芙琳的家门前。然而等待她的却不再是床上满口爱意的那个人。看似意外的小镇事故却如蝴蝶效应般影响着来自不同地方的人们，一个不宁静的夜晚意外串接起所有人心里最深层的秘密。', '德尼·梅诺谢', '多米尼克·摩尔', 7.5, 9735, 'tt10409498', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2596016343.jpg', 0.8, 2.6, 32.4, 50.9, 13.3, '0.559347,0.294889,-0.879289,0.604281,0.060181,-0.115177,1.148176,0.319814,-0.461147,-0.271478,0.345286,0.573999,-0.296700,0.236739,0.249739,0.054144,-0.519458,-0.327833,0.057686,-0.378403,-0.246740,-0.578483,-0.104822,-0.322993,-0.026227,-0.090409,0.419791,0.171717,-0.062814,0.449718,0.149235,0.192764,-0.340737,0.889924,-0.240150,0.002171,0.145601,-0.036692,-0.068660,0.124095,-0.198761,-0.205792,-0.377693,0.210338,0.006909,0.320731,0.658061,-0.206981,-0.160492,0.118536,0.017321,-0.145156,0.069619,-0.094272,0.585312,-0.385840,0.277160,0.018282,-0.141342,-0.138597,0.185196,0.042824,-0.306801,0.086654,0.217670,0.494057,-0.593386,0.465223,-0.129925,-0.098874,-0.137333,-0.339300,0.176877,0.108673,0.179157,0.453900,-0.126549,0.014024,-0.514151,-0.287433,0.759195,0.176014,-0.425675,0.477360,-0.543123,-0.496457,-0.260055,0.121808,-0.588235,-0.150249,0.324623,0.041238,-0.184584,0.105328,-0.438372,0.022662,-0.132831,-0.255714,-0.185007,-0.413884,-0.197830,-0.652051,0.093847,-0.447488,-0.431591,0.068892,-0.015650,0.096134,0.492131,-0.589324,0.248250,0.612801,0.141270,-0.092185,0.625619,-0.082614,0.127905,-0.164077,-0.287373,0.421898,-0.196776,0.383125,0.186413,0.269051,-0.448190,-0.040527,-0.328209,0.541658', '3011051', '2002683', '1296534', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34658290', '最后的决斗', '剧情', '根据中世纪法国最后一次经由战斗判决的真实故事改编而成。在尚·德·卡鲁日（马特·达蒙 饰）的妻子玛格丽特（朱迪·科默 饰）指控贾克·勒·格里（亚当·德莱弗 饰）强奸后，骑士尚·德·卡鲁日向他的前朋友贾克·勒·格里斯发起决斗。从多个“罗生门-式”的角度讲述。国王查尔斯六世宣布，尚·德·卡鲁日骑士向他的乡绅发起决斗，以解决与他的争端。', '朱迪·科默', '雷德利·斯科特', 8.3, 70155, 'tt4244994', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2755684064.jpg', 0.4, 1.2, 14.7, 49.8, 33.9, '0.175374,0.029128,-0.470073,0.769128,0.753324,-0.517168,0.439675,0.007065,-0.060327,-0.530643,0.260336,0.254109,-0.383518,0.150532,0.840419,0.062667,-0.615760,-0.549047,-0.070816,0.259952,-0.538359,-0.775925,-0.231055,-0.387727,-0.114445,-0.449196,0.542423,-0.258672,-0.374132,0.095171,0.475468,0.739166,0.024362,-0.098213,0.148269,-0.040400,0.107336,-0.241673,-0.646501,0.265133,0.148783,-0.072971,-0.259222,-0.030163,-0.122239,0.674656,0.618537,-0.731034,0.532423,-0.114739,0.284619,-0.151116,0.214697,0.234783,-0.099102,-0.119652,-0.111103,0.577216,0.169181,-0.138467,-0.082257,-0.218058,-0.256408,-0.108671,0.097768,0.491439,-0.338010,0.511864,-0.439045,0.641163,0.062894,-0.242589,-0.536148,0.408005,-0.002819,0.410785,-0.002001,-0.116488,-0.484901,-0.097594,0.413712,0.196931,-0.503655,-0.062878,0.030717,-0.478570,-0.064676,0.015687,-0.376761,-0.027102,0.316498,-0.154854,0.388291,0.545865,-0.675573,-0.559388,-0.422415,0.187818,0.573448,0.023999,0.028122,-0.900815,0.111066,-0.229005,-0.227579,-0.136177,-0.027212,-0.045223,0.428384,-0.370826,0.113366,0.238224,0.282719,0.112303,0.402363,-0.046542,0.413243,-0.451324,-0.082731,0.305527,0.463853,0.007416,0.299769,0.140410,0.265965,-0.071805,0.032741,0.432159', '6517421', '1293537', '1293572', '26260853');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34670218', '大赢家', '喜剧', '在银行同事们眼里，严谨（大鹏饰）是个十足的怪咖，凡事认真恪守原则，总是得罪行长，以至于连累大家奖金泡汤。一次偶然的机会，银行接到公安局举办的抢劫演习的任务，大家都想糊弄过去早点回家，严瑾却认认真真当起了“劫匪”……', '大鹏', '于淼', 6.7, 164066, 'tt11563836', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2591946932.jpg', 2.8, 10.5, 44.6, 33.9, 8.1, '0.127903,-0.064874,-0.321913,0.122018,-0.365557,-0.397282,0.036749,-0.208823,-0.169473,-0.135734,0.081464,0.311349,-0.058964,0.019991,0.346012,-0.267429,-0.218777,-0.174942,0.151463,0.083849,0.265977,-0.260532,0.124979,-0.078067,-0.032789,0.245976,0.184386,-0.124157,0.029017,0.520231,0.291686,0.035041,0.091000,0.177874,0.002148,-0.298456,0.131442,-0.162980,-0.094177,-0.028621,-0.001167,0.141597,-0.520618,0.024361,0.829195,0.363212,0.073059,0.361028,-0.784897,0.218590,0.439434,-0.302139,-0.004521,0.073078,0.329988,0.142318,0.478358,0.270490,-0.099479,0.028857,-0.143784,-0.086909,-0.575638,-0.106868,0.051628,0.132312,-0.508546,0.473737,0.190053,0.364960,-0.309042,-0.416014,0.062503,0.060164,0.080829,0.109133,0.049109,0.288491,-0.466250,0.266524,0.431074,-0.078301,0.084622,-0.077382,0.161652,-0.009595,0.498402,-0.171048,-0.439597,0.255012,0.141538,-0.590488,-0.254641,-0.046122,-0.310494,-0.269403,-0.090180,-0.348479,0.034394,-0.590576,0.003449,-0.434118,0.443661,0.117707,-0.582757,0.415334,0.066068,-0.035499,0.355795,-0.635566,0.049184,0.841607,-0.008325,-0.700880,0.628069,0.499362,0.167721,-0.141612,0.092910,-0.740717,0.390125,0.468732,0.087435,0.139316,0.233794,-0.384625,0.115231,0.087956', '4300640', '30197496', '1308590', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34777818', '黑暗正义联盟：天启星战争', '动画', '正义联盟集结地球上所有超级英雄一起对抗强大的反派达克赛德。', '托尼·托德', '马特·皮特斯', 7, 14138, 'tt11079148', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2601841242.jpg', 3.5, 8.2, 38.7, 34.9, 14.7, '0.561497,0.475051,-0.530032,0.413327,0.474833,0.101711,0.263549,0.239471,0.313428,0.295399,0.438704,0.739118,0.502396,-0.071902,0.038659,-0.260630,-0.287864,-0.832057,-0.285023,0.199960,-0.168876,-0.731126,-1.096665,0.008498,-0.340220,-0.200930,1.003545,-0.270586,-0.205157,0.190761,0.548210,0.515182,-0.296028,-0.102433,-0.001891,-0.473373,0.561711,-0.455712,-0.479365,0.218404,-1.330484,1.299823,0.191623,0.420393,-0.484397,-0.547058,-0.378200,-0.494346,1.192136,-1.150458,0.286431,-0.442604,-0.177709,-0.015181,0.789095,0.095917,0.149500,0.043121,0.944670,-0.700832,-0.395346,0.340342,-1.627219,-0.631296,0.312577,-0.142294,-0.490332,-0.009811,0.205116,-0.164689,0.503093,0.393001,-0.267309,0.469433,0.528876,-0.319352,0.504687,0.294903,-0.074325,-0.389453,1.080773,-0.401587,-0.655205,-1.022431,0.502866,-0.032579,-0.432993,-1.275497,-0.584155,-0.096571,-0.516514,-0.531326,0.807258,1.154302,-1.617066,0.378147,-0.543653,0.153186,0.276447,0.188243,0.405557,-1.268431,-0.619877,0.063448,-0.185826,0.078553,0.683459,0.037180,1.734307,-0.944275,-0.068793,0.936014,0.759836,-0.274028,0.198749,0.156507,0.381408,-0.152060,0.080768,0.297083,0.209626,0.695471,-0.066989,0.261483,-0.179716,0.519003,-0.165962,1.323223', '24284209', '7155241', '27602116', '30290068');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34779692', '新神榜：哪吒重生', '动作', '三千年前，天下动荡，人神共遇大劫，不想哪吒的一缕魂魄逃脱天罗地网，世世转世投胎，这一世与东海市酷爱机车的热血青年李云祥人神共生。然而龙族对哪吒恩怨并未善罢甘休，有着哪吒元神的李云祥，亦无法逃脱被龙族赶尽杀绝的宿命。东海危在旦夕，李云祥是否能够与哪吒元神并肩作战，成为抵抗龙族的英雄？东海市的子民能否得到拯救？', '杨天翔', '赵霁', 6.9, 198281, 'tt13269670', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2631711326.jpg', 1.7, 9.9, 42, 36.8, 9.6, '-0.038966,0.495537,-0.647511,0.635349,0.226363,-0.176661,0.053829,-0.111549,-0.773961,-0.050171,0.026872,0.845334,0.337126,0.102007,-0.238292,-0.112538,0.218312,-0.408114,0.181634,0.143567,-0.159834,0.226946,-0.600802,0.241815,-0.260206,-0.431358,1.371850,0.269710,0.239774,0.335782,0.136903,0.437242,-0.522234,0.141885,-0.536542,-0.041417,-0.748578,0.471987,-0.693662,0.362084,-0.161597,-0.190746,0.147572,0.373111,-0.336211,-0.071183,0.155382,-0.446600,0.039624,-0.590689,0.350579,-0.453141,-0.114642,0.093837,0.375385,-0.103103,0.189829,0.843962,0.074408,-0.344290,0.209663,0.167678,-0.949569,-0.311484,0.178555,0.136967,-0.207966,0.161355,0.101448,0.019988,-0.188999,0.065656,0.281205,0.767066,0.371040,0.166829,-0.320735,-0.224642,-0.778526,0.000472,1.051329,-0.432985,-0.337945,-0.102495,0.268980,-0.376049,-0.287780,-0.852853,-0.276537,0.285141,0.149377,0.386807,0.138494,0.811494,-0.291579,-0.269286,-0.595192,0.427007,-0.082883,-0.166429,0.120436,-0.116125,-0.483890,-0.015321,-0.107488,-0.089766,0.672278,-0.002657,0.687155,-0.808279,0.072774,0.365958,0.465982,-0.760799,1.064670,0.380030,0.408967,-0.627809,0.161874,0.739247,0.001392,0.436180,0.069534,-0.466043,0.177300,0.411091,-0.363223,-0.113648', '3861846', '26691320', '3001114', '26635323');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34786971', '陈情令之生魂', '奇幻', '靠近岐山，有一座曾被称作“小不夜天城”的扶风城。很久以前，此城花灯闪耀，夜如白昼。然而现在却被黑暗笼罩，流传着“点灯杀人”的传说。主人公温宁来到扶风城后，一入城，便发现了很多反常之处，整个城里都是老弱病残，一副萧条破败之景。黑夜来临，温宁刻意点灯，引来鬼影。正要将他擒获之时，一道蓝色剑光袭来，那黑影借机逃离。温宁抬眼一看，一道熟悉的身影从门外飞驰而入，正是他的旧相识，蓝氏子弟蓝思追。随后，温宁与蓝思追一起携手，经过不懈努力，二人最终解开谜团，擒住了幕后黑手，还百姓一个太平世间。', '于斌', '裘仲维', 4.8, 45877, 'tt11274256', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2609410463.jpg', 21.8, 34.2, 32.1, 5.7, 6.2, '0.399226,0.298050,-0.666678,0.402579,0.360584,0.112725,0.855107,0.275869,-0.196846,-0.402145,0.328945,0.497904,-0.131617,0.324463,0.198597,0.220216,0.049693,-0.693225,-0.184454,-0.496869,0.062466,0.307270,-0.067554,0.139437,-0.115645,-0.051522,0.391501,0.590296,-0.075692,0.639823,0.046257,-0.213551,-0.839958,0.527144,-0.263878,-0.222908,-0.014512,0.111276,-0.059260,0.252240,-0.510613,-0.329188,-0.537987,-0.031477,-0.389992,0.358595,0.411844,-0.254692,-0.085287,-0.021401,0.142685,-0.287792,0.016532,0.142718,0.342884,0.075108,-0.098241,-0.070543,-0.339539,-0.155835,-0.351319,-0.059476,-0.076705,0.305899,-0.032865,0.018666,-0.581352,0.003040,0.171913,-0.339894,0.100166,-0.388560,0.309650,-0.082841,0.026129,-0.003896,0.102404,0.076273,-0.507756,0.107949,0.720626,-0.159941,-0.344237,0.220009,0.283429,-0.178322,0.165579,0.341808,0.066121,-0.211705,0.734205,-0.064326,0.009971,0.116022,-0.571192,0.286539,-0.398125,0.042904,-0.301678,0.040379,-0.505566,-0.283896,-0.241251,0.110953,-0.250586,0.437988,-0.262210,0.261870,-0.021498,-0.418481,0.321949,0.313336,0.349529,0.021760,0.473794,-0.395573,-0.075343,0.128227,-0.019452,0.282650,0.538630,0.727875,-0.165066,0.178415,-0.336951,-0.187020,-0.624525,0.176899', '20380318', '20451118', '3011051', '10733357');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34787747', '最初的梦想', '剧情', '被帕塔克（苏尚特·辛格·拉吉普特 饰）寄予厚望的儿子拉加夫高考失利，因无法忍受“失败者”的标签而发生意外。面对病床前丧失信心的儿子，帕塔克讲述了大学时代，自己与朋友们以及前妻玛雅（施拉达·卡普尔 饰），为了完成“失败者”的逆袭，在冠军联赛中“损招”尽出的故事。一段啼笑皆非的青春往事揭开帷幕，他们会实现最初的梦想吗？', '苏尚特·辛格·拉吉普特', '涅提·蒂瓦里', 6.9, 24311, 'tt9052870', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2766852789.jpg', 1.2, 7.8, 43, 39.2, 8.7, '0.024139,-0.046348,-0.419643,0.454614,-0.037099,-0.397746,0.593662,-0.065643,-0.314852,-0.302651,0.152744,0.621401,-0.001360,0.277104,0.734572,-0.046042,-0.271780,-1.008510,0.149187,-0.298145,-0.341402,-0.545624,-0.263687,-0.249573,-0.248472,-0.537876,0.750412,-0.127253,0.030357,0.460042,0.505361,0.343404,0.174995,0.063570,0.298897,0.142230,-0.067263,0.086765,-0.472302,-0.029261,-0.111929,0.148994,-0.230673,0.182859,0.034379,0.151377,0.745305,-0.248314,0.255959,-0.554477,0.427717,-0.486072,0.130194,0.116927,0.100770,0.033966,0.103224,0.445723,0.127908,-0.399327,0.289860,-0.243469,-0.739612,-0.012850,0.088346,-0.029551,-0.515071,0.414206,-0.299307,0.050645,0.193191,-0.077976,0.090356,0.331284,0.697166,0.371355,-0.318274,-0.085954,-0.388116,0.440231,0.313842,-0.133808,-0.224753,0.252814,-0.036374,0.059758,0.068686,-0.248330,-0.611867,0.107806,0.150463,-0.028778,0.088561,0.512265,-0.417444,-0.394585,-0.528301,-0.207658,0.269471,-0.380220,-0.145115,-0.422135,-0.263364,0.023990,-0.361152,-0.099880,-0.061048,-0.350410,0.700564,-0.700522,0.327914,0.444311,0.181123,0.008142,0.234065,0.594742,0.488275,-0.376896,-0.141623,0.699107,-0.233937,0.087235,-0.061712,-0.062366,-0.202569,0.010651,-0.325982,1.102749', '1299663', '1308763', '25827741', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34795703', '伦敦生活', '喜剧', '※菲比·沃勒-布里奇在独角戏中气场全开※※同名改编剧集狂揽艾美奖4项大奖※※伦敦西区演出一票难求※闺蜜意外离世之后，只留下了她们经营不善的咖啡馆，我们的女主人公这才意识到她的生活早已一塌糊涂：分手的前男友不会再回来，原生家庭的疏离也让她难以开口求助，但面对一切，她看起来并非斗志全无。独角戏《伦敦生活》以一个大龄女青年的挣扎故事引发了广泛共鸣，又给予人无限勇气。该剧由编剧兼女主演菲比·沃勒-布里奇和导演维姬•琼斯联手打造，2013年于爱丁堡边缘艺术节首演时一炮而红；2016年被改编为同名BBC剧集，再掀热潮；2019年布里奇携独角戏强势回归舞台，她在外百老汇、伦敦西区的演出一票难求，而剧集《伦敦生活》第二季更是在艾美奖上狂揽11项提名，并最终斩获喜剧类最佳女主角、最佳编剧等4项大奖。眼下，才华横溢的布里奇已经引起万众瞩目。此次NT Live版《伦敦生活》来自该剧在伦敦西区的封箱演出，《卫报》盛赞在舞台上袒露心路的布里奇“放飞自我，气场全开”。', '菲比·沃勒-布里奇', '维姬·琼斯', 9.1, 10631, 'tt10702760', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2575437114.jpg', 0.4, 0.8, 6.9, 29.2, 62.6, '-0.203775,-0.079113,-0.505545,0.510875,0.204202,-0.137980,0.576590,0.178013,-0.378258,-0.065189,0.072547,0.918943,-0.537528,0.260650,0.515546,-0.238027,-0.370284,-0.654652,-0.148303,-0.005132,0.051013,-0.239981,-0.244984,0.086653,-0.229380,-0.250262,0.864594,0.007424,-0.314709,0.487732,0.584857,0.112746,-0.001987,0.345764,-0.011772,0.136111,0.120830,0.115537,-0.407926,0.414024,-0.067244,-0.338093,-0.293955,0.133499,0.060580,0.036686,0.688865,-0.019185,0.185287,0.102219,0.574133,-0.224603,-0.023879,-0.057307,0.265860,-0.109827,0.313895,0.084346,-0.183746,0.068931,-0.051486,-0.275945,-0.445998,0.198055,0.105845,0.081603,-0.278777,0.411202,0.038065,0.078286,-0.118010,0.014448,0.001131,0.019770,0.459023,0.176442,0.025299,0.059063,-0.115287,0.570761,0.574719,-0.030060,-0.376224,0.457508,-0.062626,-0.562851,-0.158520,-0.372753,-0.638972,0.013678,0.125701,0.146057,0.185785,0.127896,-0.391564,-0.057367,0.002214,-0.200338,-0.057395,-0.328534,0.154149,-0.940455,-0.320324,0.011700,0.095494,-0.097805,0.170825,-0.191876,0.556006,-0.441588,0.154948,0.433511,0.097670,-0.324172,0.656014,0.026974,0.140616,-0.181505,-0.088794,0.322279,-0.136944,0.122828,0.042839,0.214386,-0.193789,-0.1