INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34801038', '黑客帝国：矩阵重启', '动作', '尼奥（基努·里维斯 Keanu Reeves 饰）和崔妮蒂（凯瑞-安·莫斯 Carrie-Anne Moss 饰）重回矩阵：在这里，一个是矩阵创造出来，周而复始的日常世界，另一个则是隐藏其后，真实的人类世界。为了弄清楚自己所处的“现实”究竟是真是假，尼奥不得不再次做出选择……', '基努·里维斯', '拉娜·沃卓斯基', 5.7, 96774, 'tt10838180', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2844387600.jpg', 5.7, 27.4, 48.7, 14.6, 3.6, '0.100716,0.681860,-0.390955,0.524288,-0.326406,0.201487,0.696459,-0.100512,-0.382646,-0.440309,0.222050,0.733695,0.034407,-0.053736,0.203954,0.349679,-0.625748,-0.297940,-0.040893,-0.309303,-0.394205,-0.988579,-0.698639,-0.225783,0.115903,-0.103505,0.711163,-0.044834,-0.124553,-0.374273,0.557675,0.880712,-0.488883,0.304679,0.033781,0.132420,0.080849,-0.127587,-0.662924,0.084659,-0.121930,0.007073,-0.251668,0.529850,-0.209303,0.071928,0.393679,-0.520542,0.046385,-0.018202,0.804678,-0.220444,-0.306020,-0.514346,0.065239,-0.561802,0.121385,-0.020630,0.209499,0.419255,0.247364,-0.090956,-1.371366,-0.264379,0.530879,0.129770,-0.352224,-0.233217,-0.099606,-0.286412,0.182148,-0.400127,0.330155,0.634289,0.814444,0.174821,0.023141,-0.308240,-0.478018,-0.255458,0.446768,0.271964,-0.577478,0.203594,-0.445772,-0.297205,-0.540486,-0.113064,-0.456186,-0.136683,0.172973,0.281810,0.004666,-0.060898,-0.229389,-0.068631,-0.351745,-0.413444,0.253775,-0.577977,-0.163189,-0.145506,0.072804,-0.339801,-0.331188,-0.089659,-0.239784,-0.483889,0.467831,-0.966671,0.078654,0.840884,-0.069081,-0.407938,0.397674,0.143429,0.284144,-0.786951,0.230127,0.467491,0.214960,0.071763,-0.588929,0.279750,0.205183,0.338257,-0.817969,0.589071', '6844861', '1297689', '26678784', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34802334', '冰路营救', '剧情', '在加拿大北部偏远地区的一个钻石矿倒塌后，冰路卡车司机（连姆·尼森饰）必须带领救援人员完成一项不可能的任务 — 穿越结冰的海面，营救被困矿工。除了融冰和风暴，还有难以预见的威胁在等着他们。', '连姆·尼森', '乔纳森·汉斯雷', 6.4, 12313, 'tt3758814', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2649209327.jpg', 2.2, 13, 55.6, 22.8, 6.4, '0.061738,-0.448523,-1.090652,0.692602,-0.116772,-0.029848,0.623676,0.159202,-0.112498,-0.136834,0.373212,0.683373,0.304093,-0.165043,0.146742,-0.439816,-0.513513,-0.448706,-0.546151,-0.233189,-0.830871,-0.608087,-0.374977,-0.424714,0.044123,-0.697127,0.766444,0.724305,-0.070795,0.479808,0.163372,-0.055966,-0.560718,0.691861,-0.326608,-0.493715,0.336858,-0.100702,-0.351914,0.500602,-0.126008,-0.135897,0.190471,-0.024961,-0.006784,0.521644,0.617901,-0.288812,0.040331,0.046449,-0.061093,-0.963426,0.182295,0.217797,0.655872,-0.348232,-0.290413,0.352573,-0.393534,0.000319,0.123557,-0.235197,-0.930328,-0.285405,0.049326,0.475223,-0.767872,0.362379,0.075089,-0.264119,-0.178451,-0.330322,0.189700,0.772519,-0.106805,0.515120,-0.431384,0.115814,-0.734201,0.284690,0.879130,-0.357261,-0.204861,-0.041312,0.143423,-0.618312,-0.052891,0.047970,-0.305200,-0.073614,0.354172,0.267848,-0.351621,-0.123730,-0.524753,0.449940,-0.343833,-0.842827,-0.500535,-0.403628,-0.365938,-0.992887,0.263881,0.077153,0.044128,0.587911,0.192205,0.070051,0.602348,-0.668369,0.315323,0.641552,0.564390,-0.434722,0.540667,0.201804,0.319625,-0.404997,0.245738,0.041501,-0.215365,0.858781,0.282908,0.316139,-0.005159,-0.273118,-0.416214,0.278549', '26937563', '5157137', '4861402', '1303447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34804147', '寻龙传说', '动画', '很久以前，在充满奇幻色彩的龙佑之邦，人类和龙和谐地生活在一起。但当一股邪恶的力量袭来，龙牺牲了自己来拯救人类。500年后，同样的邪恶力量卷土重来，只有一个孤独的战士拉雅（凯莉·玛丽·陈 配音）承担重任，追踪传说中的最后一条龙，以修复这块破碎的土地，团结分裂的人民。在她的旅程中，她也会逐渐了解到拯救世界不仅仅需要一条龙，还需要信任和团队合作。', '凯莉·玛丽·陈', '唐·霍尔', 7, 113795, 'tt5109280', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2628052135.jpg', 0.6, 5.8, 45.1, 39.3, 9.2, '-0.134154,0.422227,-0.656309,0.892216,-0.228528,-0.124891,0.858620,-0.144276,-0.310112,-0.231309,0.158686,0.667859,0.235762,0.249300,0.358355,-0.026950,-0.059996,-0.520508,-0.148361,0.058105,-0.444013,-0.173625,-0.620847,-0.578944,-0.207356,-0.529933,0.953363,0.613431,-0.426083,0.378353,-0.030500,0.217875,-0.126042,0.499778,-0.245889,-0.209901,-0.099903,0.267540,-0.364610,0.139398,0.095813,-0.121785,0.077065,0.444844,-0.195416,0.196837,0.716334,-0.586157,0.168959,-0.206400,0.516171,-0.335627,-0.100026,-0.112386,0.200720,0.012217,0.097188,-0.007897,-0.030024,0.088828,-0.041298,-0.229694,-1.220158,-0.387853,-0.001366,0.130922,-0.454593,0.600862,0.338113,-0.114295,0.235628,-0.238501,0.155246,0.338725,0.284514,0.589834,-0.256368,0.102515,-0.414249,0.274422,0.885337,-0.392397,-0.620156,0.215884,-0.562870,-0.652784,-0.388395,-0.342484,-0.308181,-0.434544,0.288975,0.255407,-0.004739,0.414732,-1.182764,0.032797,0.064303,-0.064421,0.115497,-0.470766,0.167972,-0.418382,-0.450901,-0.402439,-0.005630,0.301228,0.051439,-0.519145,0.828648,-0.919570,0.218001,0.658855,0.476159,-0.611825,0.670378,0.020687,0.048731,-0.395961,-0.043708,0.435339,-0.016913,0.327882,0.198852,0.370490,0.189385,0.469975,-0.488503,0.740537', '26667010', '3769423', '1308784', '3213270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34805219', '饥饿站台', '科幻', '在未来的反乌托邦国度中，囚犯们被关押在垂直堆叠的牢房里，饥肠辘辘地看着食物从上层落下，靠近顶层的人吃得饱饱的，而位于底层的人则因饥饿而变得激进。由加尔德·加斯特卢-乌鲁希亚执导的《饥饿站台》是一部扭曲的社会寓言，讲述了人类最黑暗和最饥渴的一面。', '伊万·马萨格', '加尔德·加兹特鲁·乌鲁蒂亚', 7.9, 292533, 'tt8228288', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2566870171.jpg', 0.4, 2, 24.2, 51.4, 22, '0.573888,-0.268887,-0.753813,0.546273,-0.032990,-0.208803,1.361784,0.572880,-0.505823,0.073680,0.340879,0.642508,-0.117472,0.153461,0.552084,-0.079030,-0.409598,-0.520040,-0.426826,-0.403732,-0.534066,-0.298739,-0.220712,-0.523661,-0.121283,-0.345505,0.660816,0.190316,-0.350243,0.019882,0.174808,0.387214,-0.069194,0.426282,-0.151369,-0.253239,-0.048421,-0.203042,0.119187,-0.077514,-0.262841,-0.318623,-0.379795,0.248958,-0.142550,0.428869,0.758237,-0.562891,0.277982,-0.380021,0.059526,-0.498792,-0.223997,0.298980,0.350936,0.033890,0.121088,0.066168,-0.186310,0.178550,-0.128337,-0.105934,-0.838568,-0.100054,-0.012322,0.295951,-0.422012,0.527278,0.248700,-0.135894,0.171169,-0.424707,0.319307,0.107768,-0.067942,0.802909,-0.004846,-0.034555,-0.455356,0.013402,0.434126,-0.069556,-0.548784,0.140365,-0.370212,-0.511810,0.046996,-0.131332,-0.620867,-0.724691,0.493498,0.160404,-0.310842,0.564193,-1.037114,0.309186,-0.084052,-0.699651,-0.321612,-0.158628,-0.532263,-0.769901,-0.160959,-0.456035,0.211744,0.065543,-0.004713,-0.047573,0.759837,-0.394535,0.202283,0.335783,0.263473,0.073449,0.684019,-0.185744,0.190325,0.147100,-0.369853,0.746969,0.233380,0.431820,0.103703,0.402453,-0.531681,0.136069,-0.700493,0.676374', '1467779', '20451118', '21619567', '1293515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34805873', '孤味', '剧情', '林秀英（陈淑芳 饰）是台南赫赫有名的餐厅老板，在丈夫（龙劭华 饰）无声无息地离家后，便靠著卖虾卷独自抚养三个女儿长大成人，不仅把虾卷从路边摊卖到开餐厅，三个女儿更是成就非凡，大女儿阿青（谢盈萱 饰）是国际舞者，二女儿阿瑜（徐若瑄 饰）在台北当整形医生，小女儿佳佳（孙可芳 饰）则接手自己的餐厅事业。眼看就要苦尽甘来，秀英却在70大寿当天接到丈夫离世的噩耗，在替这位有名无实的丈夫筹办丧礼的同时，竟意外迎来了另一位陪伴丈夫度过晚年的女人，令她不得不再次面对内心埋藏已久的怨怼……', '陈淑芳', '许承杰', 8, 78208, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2623646280.jpg', 0.7, 2.2, 19.6, 49.9, 27.6, '-0.404876,0.075098,-0.468172,0.266237,-0.044481,-0.477410,0.471194,0.677101,-0.477820,-0.202093,0.539517,0.612931,-0.114478,0.595515,0.480170,0.073843,0.014458,-0.581268,0.014010,-0.034497,-0.156144,-0.005445,0.030995,-0.121573,0.001919,-0.015570,0.488855,-0.192662,0.104760,0.280920,0.378555,0.238976,-0.194914,0.300816,-0.529327,0.178714,0.103196,0.238569,-0.505176,0.218903,-0.050384,-0.248306,-0.133090,-0.049108,0.077865,0.065407,0.684570,-0.023373,-0.047445,-0.259752,0.393016,0.149140,-0.218090,0.066602,0.303203,0.064804,0.262618,0.066322,-0.463850,0.001719,0.340210,-0.191700,-0.415348,0.115913,0.275861,-0.169425,-0.765624,0.279820,-0.194659,0.004444,0.223939,-0.425677,0.072976,0.222471,-0.310097,0.777827,-0.203361,0.459395,-0.278032,0.329710,0.338374,-0.014626,0.290411,0.291091,0.148852,-0.087254,0.413716,-0.133211,-0.518557,0.013534,0.227838,0.014426,0.130960,0.180091,-0.251124,-0.227165,-0.417210,-0.147418,0.668410,-0.241421,-0.334989,-0.290259,0.185967,-0.094157,-0.148055,0.177192,0.185964,0.041648,0.631249,-0.460147,0.424743,0.125119,-0.007789,-0.456778,0.511936,0.034076,0.343029,-0.452083,0.020297,0.157152,-0.248842,0.109202,0.042111,0.064162,-0.365785,-0.081303,-0.430706,0.302732', '25731805', '4066127', '4030411', '1316525');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34809353', '始动', '剧情', '电影改编自同名人气漫画，讲述的是离家出走的青少年的成长故事。离家出走的叛逆儿泽日（朴正民饰）与盲目踏入社会并满腔热血的尚弼（丁海寅饰），在遇见长风饭馆的厨师长猛男哥（马东锡饰）后，让自己明白了什么是世间愉快与开心的故事。', '马东锡', '崔正烈', 6.6, 8468, 'tt11454170', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2576730703.jpg', 1.5, 10.6, 53.1, 24.8, 10.1, '0.403953,-0.260634,-0.401379,0.301506,0.100310,-0.239236,0.614406,0.065650,-0.795023,-0.118365,-0.174537,0.803731,-0.420707,0.416087,0.169619,0.083345,-0.064579,-0.559739,-0.045873,0.050271,0.403292,-0.618069,0.023901,0.001647,0.078050,-0.387020,0.477895,0.117764,-0.359763,0.673969,0.470149,-0.152843,-0.169906,0.304258,-0.235960,0.393821,-0.238848,0.187305,-0.573766,-0.199858,0.121275,0.112566,-0.231216,0.031297,-0.147979,-0.007089,0.527470,-0.065441,-0.534999,0.279109,0.792936,-0.344299,-0.257180,-0.045984,0.173638,0.028198,0.317183,0.320792,0.449888,0.206936,-0.352123,-0.140842,-0.893819,-0.113254,-0.036467,0.219264,-0.703065,0.437909,0.280948,-0.134065,0.512493,-0.105439,0.103111,0.256896,0.548958,0.488241,-0.020511,0.120397,-0.471994,0.506076,0.656270,-0.012503,-0.232189,0.948599,-0.071048,-0.318221,-0.405237,-0.148818,-0.683941,0.309051,0.047650,-0.093068,-0.331031,0.163128,-0.472627,-0.086487,0.049747,-0.126617,0.298125,-0.523849,-0.308325,-0.310535,-0.271440,-0.395482,-0.326503,-0.467641,0.179692,-0.467815,0.956942,-0.930845,0.199285,0.784748,0.054922,-0.617300,0.621508,0.257790,-0.327400,-0.068316,-0.040984,0.208918,-0.232295,-0.018772,-0.263240,0.479114,-0.004050,-0.239316,-0.604932,0.415674', '24284209', '27602116', '1308424', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34809360', '在街上', '剧情', '故事发生在下北泽，青年荒川青（若叶龙也 饰）和女友川濑雪（穗志萌香 饰）之间的感情一直十分稳定，哪知道在小雪生日这天，当荒川满心欢喜的为她庆祝的节骨眼上，小雪向荒川坦诚自己出轨了，并且要求分手。一次偶然中，荒川结识了在美术大学里深造的高桥町子（萩原实里 饰），高桥打算拍摄一部独立电影，她邀请荒川也参与其中。在拍摄的过程中，荒川认识了场务城定（中田青渚 饰），活泼可爱的城定和荒川相见恨晚，两人之间很快就成为了无话不谈的朋友。与此同时，参加电影拍摄的还有小有名气的电视演员间宫武（成田凌 饰），让荒川感到震惊的是，他竟然就是小雪的出轨对象。©豆瓣', '若叶龙也', '今泉力哉', 7.6, 8142, 'tt11952444', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2847602054.jpg', 0.7, 3.1, 28.2, 49.6, 18.5, '0.123266,-0.170170,-0.893971,0.515236,0.130511,-0.062468,0.432140,0.137349,-0.606396,-0.269181,-0.003610,0.807054,-0.528166,0.321753,0.531228,-0.078804,-0.299256,-0.908237,-0.116102,-0.296001,-0.155279,-0.588636,-0.462937,0.072516,-0.323375,-0.188269,0.702959,0.233558,-0.402269,0.498511,0.515762,0.133839,-0.245758,0.344317,0.202445,0.034108,0.118721,0.458219,-0.361418,0.255509,-0.197307,-0.112590,-0.124906,0.120339,0.360533,0.496734,0.672837,0.058011,-0.127818,0.185539,0.363801,-0.132401,-0.284904,-0.013888,0.391745,-0.020906,0.346766,0.171801,-0.284822,-0.065822,-0.130301,-0.117346,-0.618448,0.020284,0.189463,0.254456,-0.457062,0.594251,-0.094252,-0.218144,0.284721,-0.271244,0.052752,0.413846,0.424236,0.238954,-0.179590,0.163467,0.071268,0.358486,0.805246,0.319557,0.138136,0.544684,-0.117640,-0.366811,-0.131550,0.047011,-0.411359,-0.035970,-0.036981,-0.047566,-0.185814,0.062366,-0.340091,-0.159598,0.018899,0.084745,0.186791,-0.259791,0.129541,-0.929445,-0.046685,-0.682607,-0.311435,-0.086741,0.088583,-0.366027,0.806476,-1.039782,-0.029624,0.282075,0.394594,-0.108876,0.827878,0.284488,-0.101855,-0.259089,0.201918,-0.349572,-0.023352,0.099708,0.090024,0.314977,0.026412,-0.218630,-0.542416,0.338506', '1316589', '3811356', '1897368', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34809365', '非常宣言', '动作', '资深警探具仁浩队长（宋康昊 饰）收到一宗飞机恐怖袭击的情报，调查期间却发现疑犯柳镇锡（任时完 饰）早已秘密登机，更惊觉爱妻亦登上了同一航班，使他倍感担忧。柳镇锡于三万呎高空中散播生化病毒，令乘客逐一离奇死亡，虽然被患有飞机恐惧症的暖心爸爸朴在赫（李秉宪 饰）成功制伏，但已无法阻止致命病毒在机上传播。此时，以国土交通部部长金淑姬（全度妍 饰）为首的应变中心迅速成立，可惜各政府部门联手后还是无计可施…… 幸存的150名乘客被困机舱，惨变生化炸弹，同时机上燃料随时耗尽，机上众人生命危在旦夕！到底应该冒险展开救援让飞机迫降，还是要空中击落以遏止病毒传播全球？', '宋康昊', '韩在林', 6.3, 8152, 'tt11535228', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2876120616.jpg', 2.2, 17.7, 51.2, 22, 7, '-0.149613,0.170691,-0.513823,0.072959,0.424362,0.125815,0.181429,-0.058059,-0.317035,-0.204912,0.435016,0.294559,-0.044042,-0.264647,0.020383,-0.241126,-0.292055,-0.344970,-0.194444,-0.071569,-0.588413,-0.303726,-0.248467,-0.027727,0.122941,-0.355266,0.499072,0.252238,0.118937,0.428442,0.211521,0.314543,-0.296660,0.517560,0.069429,-0.359222,-0.012850,-0.426914,-0.366372,0.176553,-0.164788,-0.302488,0.237673,0.037817,-0.045705,0.431331,0.592053,-0.071761,-0.252692,-0.269746,0.201140,-0.345532,0.035152,-0.075553,0.548671,0.304311,-0.043736,-0.056741,-0.102933,0.188296,0.150460,0.643059,-0.512152,-0.036570,-0.027328,-0.027177,-0.060456,-0.158960,-0.451447,0.274873,-0.034820,-0.121253,0.177420,0.205561,0.120944,0.061564,-0.267353,0.026509,-0.189749,-0.025287,0.461896,-0.141983,-0.352558,0.029379,-0.002522,-0.462921,0.112684,-0.165562,0.010871,-0.012688,0.158511,0.383873,0.138418,0.307403,-0.159019,0.081953,-0.575685,-0.282166,-0.306477,-0.095247,0.107581,-0.750972,0.148266,0.233498,-0.079163,0.179615,0.259063,0.010267,0.558338,-0.265747,0.141015,0.414338,0.235996,-0.332153,0.047197,-0.012198,0.047043,-0.257513,-0.012578,0.256132,0.153151,0.588176,-0.176309,-0.006182,-0.307470,-0.420057,-0.236397,-0.169709', '2369613', '3871833', '1306809', '27110363');
