INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34814907', '老妇人', '剧情', '讲述现年69岁的“孝贞”在医院被29岁的男护士性侵，经过长时间的思考，她把这件事告诉了和她住在一起的“东根”并一起报了警，然而，警察和周围的人都认为这是不可能的事，污蔑“孝贞”是老年痴呆患者，法院也以年龄的悬殊为根据，事件的偶然性不足为由驳回了拘捕令。然而“孝贞”并没有因此屈服，而是鼓足勇气继续向前走。', '芮秀贞', '林善爱', 7.7, 7098, 'tt11585882', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2614611552.jpg', 0.3, 2, 28.4, 52.7, 16.6, '0.699187,-0.241792,-0.548879,0.459369,-0.146885,-0.245546,0.704182,0.118107,-0.594552,-0.333869,-0.083655,0.502879,-0.226901,0.155155,0.128384,-0.256084,-0.064699,-0.897403,-0.089052,-0.090599,-0.495456,-1.028019,0.383571,-0.296645,-0.084776,-0.306849,0.505270,-0.011049,-0.156289,0.628111,0.382698,0.139470,0.227350,0.738867,0.087452,0.012983,-0.069797,0.384762,0.046061,0.286844,0.308434,-0.522358,0.219706,0.278178,-0.045493,0.769743,0.264802,-0.218533,-0.435909,0.064970,0.448824,-0.461565,-0.025747,0.355848,0.626552,0.081758,0.092618,0.580614,-0.295635,0.020411,-0.159071,0.118746,-0.947073,0.035022,0.251612,0.046298,-0.754597,0.483469,-0.175957,-0.173930,0.116267,-0.000979,0.237472,0.670259,0.330411,0.489393,-0.189375,-0.288936,-0.593791,0.076672,0.599152,0.028368,-0.308868,0.164931,-0.416654,-0.613199,-0.005834,-0.411544,-0.190605,0.271333,-0.384311,0.338158,-0.509874,-0.192066,0.017206,-0.195044,-0.230632,-0.288973,-0.146180,-0.649182,-0.034865,-0.208342,-0.207069,-0.534952,-0.339392,0.088093,0.029635,-0.364766,0.296074,-0.624439,0.224581,0.592745,0.616659,-0.801286,0.960422,0.254521,-0.019036,-0.221402,-0.235987,-0.060022,0.071878,0.431306,0.268554,0.142777,0.455334,-0.486578,-0.488752,-0.014082', '25908042', '25862560', '35073886', '1293182');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34820925', '钛', '剧情', '艾莉克西亚（阿加莎·罗塞勒 Agathe Rousselle 饰）是一名汽车模特，拥有曼妙身材的她靠着跳艳舞维持生计。早年间，一场车祸让艾莉克西亚的大脑中被医生植入了钛金属，这块金属随着时间的推移，渐渐影响了她的性格，让她变得暴戾而又狂躁，在钛金属的影响下，她甚至杀死了自己的双亲。不仅如此，艾莉克西亚还发现自己对汽车产生了性趣，在和汽车发生了性关系后，艾莉克西亚发现自己的身体逐渐出现了妊娠的征兆。文森特（文森特·林顿 Vincent Lindon 饰）是消防队的队长，早年间，他的儿子失踪了，这些年来，他一直都没有放弃过寻找儿子的下落。命运让艾莉克西亚和文森特相遇了，艾莉克西亚女扮男装，假装成为文森特的儿子，和文森特开始了住在同一屋檐下的生活。她一边要努力维系自己的谎言不被戳穿，一遍还要隐藏渐渐变形的身体。当然，纸是包不住火的，在长久的压抑之后，艾莉克西亚和文森特之间的关系也发生了微妙的变化。', '阿加莎·罗塞勒', '朱利亚·迪库诺', 6.4, 52552, 'tt10944760', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2663190044.jpg', 5.6, 15.5, 42, 27.4, 9.6, '0.335099,0.243733,-0.861267,0.607531,-0.116672,-0.370890,1.012369,0.260748,-0.523799,-0.107448,0.227446,0.704049,-0.454858,-0.040832,-0.113401,0.193797,-0.432698,-1.046647,-0.120766,0.218532,-0.423473,-0.449500,-0.270943,-0.153647,-0.208972,-0.705150,0.527654,0.040779,-0.255543,0.178436,0.048978,0.265246,0.190355,0.564309,-0.195792,0.251404,0.199771,-0.093212,0.107938,0.297304,0.279315,-0.414039,0.180662,0.354784,-0.006004,0.508149,0.701214,-0.197273,-0.137603,-0.139817,0.223110,-0.129372,-0.116536,0.064733,0.442187,0.169096,-0.000607,0.199206,-0.481755,0.059274,0.249863,0.263200,-0.607235,0.174517,0.011710,0.409440,-0.868734,0.515577,-0.158664,-0.392614,0.141659,-0.406294,0.488897,0.610787,0.160214,0.238135,-0.357761,0.062365,-0.502881,0.031590,0.694769,0.045117,-0.437316,0.514624,-0.639997,-0.331088,-0.270773,-0.174091,-0.317160,-0.444695,0.342309,0.193989,-0.299090,0.494546,-0.618409,-0.058560,-0.378193,-0.376855,-0.397943,-0.600915,-0.027956,-0.339561,-0.316569,-0.761509,-0.190843,-0.099697,-0.089831,-0.352071,0.456975,-0.835229,0.355957,0.669053,0.422875,-0.201867,0.276225,0.009389,-0.109442,0.132819,-0.074015,0.258434,-0.137056,0.380924,0.245118,0.550339,0.253704,0.204325,-0.395146,0.878799