INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34822138', '咱们裸熊：电影版', '喜剧', '三只熊熊兄弟们因为网络上的名气，以及对大都市的迷恋，他们被迫面对无法预料的混乱，熊熊们不得不展开一场疯狂、危险但又有聚会的冒险之旅，以躲避来自国家野生动物管制局的追捕，于是大大、胖达和白熊一同踏上了前往加拿大的旅程！在旅途中，他们将互相帮忙、渡过种种难关，最重要的是，这趟旅程也将再次证明他们是彼此最好的伙伴。熊熊们是如何相识、又是如何建立起如此亲密的伙伴关系？这一次也将首次揭露当年熊熊们初识的点点滴滴，以及彼此从陌生到熟识的互动过程。', '埃里克·埃德尔斯坦', '丹尼尔·钟', 7.5, 8850, 'tt10474606', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2604993774.jpg', 0.7, 3.5, 34.2, 42.5, 19.1, '0.461304,-0.149561,-0.853142,0.565240,0.218482,0.074530,0.614438,-0.273176,-0.844361,0.155349,0.312125,0.861896,-0.185541,0.232656,0.098937,-0.422347,-0.134198,-0.873229,-0.125285,-0.227924,-0.388476,-0.537591,-0.234439,-0.149794,-0.174742,-0.209889,0.763901,0.292333,-0.359040,0.601725,0.434200,0.412492,-0.483209,0.622547,-0.233764,-0.278297,-0.122615,0.243055,-0.666195,0.091775,0.017408,-0.146431,-0.417877,0.162188,0.140615,0.220983,0.867983,-0.487320,-0.333933,-0.079596,0.322418,-0.578430,-0.036108,0.307092,0.186975,0.295451,0.166919,0.291467,0.032430,-0.017122,-0.210500,-0.168946,-0.825219,0.249627,0.247291,0.017186,-0.793586,0.303385,0.285366,-0.248361,0.266393,-0.130544,0.207400,0.886198,0.290859,0.204781,-0.251080,-0.034383,-0.277468,-0.046854,1.283192,0.155093,-0.152789,0.264236,-0.322852,-0.265623,-0.066309,-0.242098,-0.420066,-0.205198,0.234204,0.235414,-0.094654,0.564866,-1.027707,0.155827,-0.207654,-0.558764,0.198640,-0.457577,0.202808,-0.758651,-0.210936,-0.474523,-0.354029,0.267950,0.190059,-0.383426,1.075273,-0.991697,0.080914,0.682368,0.252568,-0.525529,0.601184,0.206598,0.266926,-0.292121,-0.209943,0.102559,0.218379,0.283055,0.188961,0.309201,-0.181923,0.268143,-0.584491,0.342782', '25721544', '1870682', '2032339', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34825886', '熊出没·狂野大陆', '喜剧', '狗熊岭附近新开业了一个神奇的“狂野大陆”，在那里，通过基因技术人可以自由变身各种动物，享受无比的自由和快乐。导游事业受挫的光头强，阴差阳错与神秘人乐天和熊二组队，参加乐园里奖金丰厚的比赛，却遭遇了队友乐天的背叛，历尽艰险终于获得冠军之际，却意外发现狂野大陆里隐藏着惊天的阴谋......', '张伟', '丁亮', 6.3, 23559, 'tt11654032', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2631708261.jpg', 2.1, 16.3, 54.5, 20.8, 6.3, '-0.172805,0.308844,-0.781153,0.576899,-0.039098,0.037673,0.517770,-0.039033,-0.548652,0.236535,0.121273,0.713218,-0.145815,0.053278,0.425709,-0.003930,-0.086934,-0.468695,0.032997,0.044998,-0.163768,-0.070078,-0.866932,-0.269719,0.018951,-0.537317,0.596127,0.410755,-0.338393,0.829122,0.056258,0.041588,-0.390339,0.580656,-0.355906,-0.065289,0.493262,0.301029,-0.309667,0.285549,-0.304229,0.201293,-0.329053,0.323425,0.233545,0.039679,0.701500,-0.398006,-0.437497,-0.355454,0.384617,0.027250,-0.263128,0.014590,0.291093,0.144399,0.500919,0.458036,0.160474,0.069634,0.035537,-0.176571,-0.958300,-0.239824,0.184921,0.103798,-0.308780,0.626047,0.032282,-0.058585,0.075530,-0.109975,0.216420,0.198697,0.318307,0.322820,-0.051456,-0.011658,-0.331775,0.134049,0.775442,-0.247204,-0.311533,-0.095365,-0.237263,-0.494009,0.087694,-0.559049,-0.265594,0.027894,0.335886,0.243674,-0.295066,0.251619,-0.873413,0.559785,-0.302484,-0.052776,-0.353060,-0.486289,-0.387186,-0.721476,0.004652,-0.172100,-0.259997,0.216439,-0.119905,-0.423002,0.817265,-0.912658,0.127876,0.743180,0.623758,-0.141969,0.556256,-0.153278,0.206029,-0.343678,-0.351393,0.041186,-0.350164,0.324157,-0.020506,0.368954,-0.207679,-0.112241,-0.360780,0.641037', '1793491', '3769423', '1308585', '35144311');
