INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34839344', '完美受害人', '剧情', '看似毫无联系的两起自杀案件，却将所有的疑点指向了一位著名画家。而正当警方锁定杀人凶手时，却发现嫌疑人画家已经跳楼自杀。危机并没有结束。案件陷入了前所未有的困境，唯一的线索只剩下嫌疑人画家的前妻。死去的画家，隐藏幕后的凶手，陷入困局的警察，一个患有创伤后应激障碍的女人，一桩陈年旧事。一个巨大的秘密和一场骇人的罪恶逐渐露出水面。所以真相到底是什么？你看见的就一定是真相吗？', '李乃文', '杨泷杰', 4.9, 6756, 'tt14766862', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2662473840.jpg', 14.5, 40, 36.4, 5.9, 3.2, '0.239979,-0.200432,-0.449061,0.351447,-0.245104,-0.201434,1.207126,-0.158191,-0.556735,-0.552203,0.361683,0.756200,-0.151787,0.062841,0.117720,-0.122410,-0.209335,-1.011658,0.100554,-0.191423,-0.512898,-0.735544,-0.422813,-0.309966,0.224127,0.002240,0.809276,0.632206,-0.281660,0.001487,0.299577,0.578508,-0.493463,0.833972,0.008083,-0.272830,0.115959,-0.102254,-0.266073,0.043047,0.278415,-0.583224,-0.040788,0.580059,-0.658479,0.530417,0.702256,-0.372465,-0.516984,0.152139,0.490057,-0.709589,-0.215209,0.233392,0.453738,-0.236995,0.082011,0.470479,-0.468414,-0.369105,0.155207,0.030501,-0.967123,-0.336198,0.232801,0.590788,-0.087416,0.176322,-0.097383,0.107728,0.164627,0.008159,0.363216,0.451317,0.408351,0.281340,-0.411722,-0.046344,-0.716305,0.003435,0.606790,-0.109149,-0.346343,0.255826,-0.082911,-0.570373,-0.282136,-0.047162,0.099414,0.338905,0.506686,0.144619,-0.579074,0.339310,-0.410846,-0.462428,-0.569987,-0.209980,-0.305198,-0.448180,-0.371115,-0.192894,-0.285136,0.224873,-0.283539,0.039806,0.312695,-0.253655,0.455537,-0.577055,0.335698,0.559974,-0.308917,-0.371452,0.439285,-0.055267,0.067533,-0.389332,-0.266038,0.080819,0.124561,0.350313,-0.031253,0.100412,-0.065134,-0.259884,-0.292127,0.370245', '4023433', '25909236', '25828589', '2988294');
