INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34845781', '鬼灭之刃 剧场版 无限列车篇', '动画', '该片基于吾峠呼世所著漫画《鬼灭之刃》创作而成，是2019年播出的TV动画的续篇，讲述灶门炭治郎和炼狱杏寿郎与下弦之壹魇梦作战的故事。', '花江夏树', '外崎春雄', 7.9, 94450, 'tt11032374', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2595123270.jpg', 0.3, 2.9, 24.2, 47.9, 24.7, '-0.183689,-0.277500,0.271561,0.625441,1.138329,-0.003932,0.468209,-0.055840,-0.183325,-0.760746,0.081033,0.372088,-0.327078,0.069878,0.248107,-0.014488,-0.056980,-0.827990,-0.504662,0.113654,0.132204,-0.258827,0.018461,0.346828,-0.139937,-0.541020,1.205077,0.043148,-0.185462,-0.008231,0.042916,0.527149,-0.504064,-0.159488,0.039258,0.082138,-0.400869,0.431071,-0.462267,0.157762,-0.362730,-0.192647,-0.722413,0.074635,-0.088694,-0.224101,0.942131,-0.770362,-0.047602,-0.161847,0.870240,-0.551432,-0.317633,-0.524805,0.031764,0.463983,0.340476,0.587331,0.196647,0.240400,-0.752318,-0.396728,-0.839179,-0.721933,0.122075,-0.009539,-0.251944,0.291582,-0.260637,0.089892,0.316347,-0.198363,0.130039,-0.139512,0.819203,0.720355,-0.316017,-0.257794,-0.378632,0.639801,0.241752,0.234754,-0.298812,0.475989,0.195540,-0.622635,-1.035556,0.116500,-0.335295,0.377893,-0.080053,0.274674,-0.189208,0.610373,-0.833863,-0.529176,0.140601,-0.314447,0.494306,-0.352572,-0.298051,-0.839518,-0.495790,-0.214063,0.360168,-0.225754,0.418010,-0.248275,0.691526,-0.816848,0.544606,0.477235,-0.133108,0.234505,0.722067,0.173266,-0.074233,-0.275507,0.411517,0.197958,-0.286802,0.164653,0.035726,0.375841,0.323262,-0.047861,-0.734414,0.455987', '26759820', '22265687', '26979208', '35088569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34850561', '咒', '恐怖', '六年前，怀孕的李若男（蔡亘宴 饰）、陈立东（林敬伦 饰）和陈振原（温庆禹 饰）秉着破除迷信的态度进入了陈家村，据说那里供奉着不可冒犯的神明。陈立东和陈振原因为传入了祭坛所在的禁地而招致了灭顶之灾，李若男虽然逃过一死，精神却受到了极大的冲击。此事过后，李若男生下了一个女儿，因为怕触犯禁忌，李若男将女儿寄养在孤儿院中。之后，李若男一直接受着心理治疗，一晃眼就是六年过去。当李若男觉得一切都已经平息之后，她将女儿陈乐瞳（黄歆庭 饰）接回了自己身边，哪知道女儿刚到家没多久，家中便屡屡出现可怕的异像，年幼的陈乐瞳似乎和曾经陈家村所供奉的神明有着千丝万缕的联系。©豆瓣', '蔡亘晏', '柯孟融', 6.8, 126212, 'tt18968540', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2871258860.jpg', 5.6, 9.7, 36, 34.3, 14.3, '0.011791,0.087155,-0.753039,0.605956,-0.149394,-0.152947,0.732641,0.104974,-0.765134,-0.395654,0.135664,0.826827,-0.104157,0.511299,0.461569,-0.023173,-0.083849,-0.472033,-0.192670,-0.394462,-0.474336,-0.207030,0.003682,0.243221,-0.319021,-0.443596,0.419099,0.109378,-0.316191,0.351650,0.477647,0.298450,-0.253541,0.409221,-0.033270,0.173513,-0.169720,0.152165,-0.147951,0.131558,0.157629,-0.331943,-0.049236,0.273771,0.042514,0.325827,0.474320,-0.427011,-0.268257,-0.555044,0.333847,-0.157205,-0.118899,0.523730,0.484888,0.087143,0.501694,0.279403,-0.298173,-0.252984,0.177202,-0.025758,-0.271867,0.064928,0.349380,-0.010041,-0.569707,0.357953,0.061215,-0.229577,-0.055937,-0.101222,0.320088,0.419511,0.164591,0.437687,-0.283902,0.023413,-0.406816,-0.025163,0.793998,0.001147,-0.048309,0.058202,0.052419,-0.418944,-0.215907,-0.027435,-0.519897,0.131875,0.157145,0.389737,-0.285219,0.208273,-0.223855,-0.067336,-0.157529,0.010815,0.248997,-0.370574,-0.197664,-0.391233,-0.038412,-0.343098,-0.409877,0.384867,0.121411,-0.157331,0.629260,-0.697831,0.371004,0.468544,0.699049,-0.508275,0.587412,-0.091208,0.239744,-0.219811,-0.108407,0.075863,0.063421,0.538493,0.288367,0.192741,-0.337759,-0.269477,-0.233396,0.457276', '25721544', '1302384', '3504940', '1292869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34850598', '无声', '剧情', '失聪少年张诚准备转到启聪学校就读。聋人的世界，却不比听人的世界宁静。当他发现校车最后一排的「游戏」，融入新生活的欣喜之情，瞬间成为恐惧⋯⋯。眼见心仪的女孩贝贝在游戏中遍体鳞伤、学长小光气势狂妄不可质疑，一群同学们又天真无害，张诚忖度着是否该揭开游戏的残忍真相，或加入游戏的行列？当加害者与受害者的界线越趋模糊，盘根错节的苦痛、无可倾诉的怨怼，种种困惑与不安在无声的校园蔓延。新锐导演柯贞年的首部长片大胆将真实事件搬上银幕，在直面残酷的同时，不失温柔的眼光。犀利刻画人物之间复杂与纠结的情感，呈现声嘶力竭却仍仿若无声的残忍。贝贝一句「他们只是在玩」轻描淡写，却惊悚、沉痛，更是真实无比的哀叹。', '陈妍霏', '柯贞年', 7.8, 39907, 'tt12396992', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2619399682.jpg', 0.5, 2.2, 23.7, 53.4, 20.2, '0.207441,0.261868,-0.519592,0.461954,-0.136013,-0.079458,1.052623,0.012382,-0.418899,0.178306,0.370271,0.374612,-0.442990,0.299682,-0.065563,-0.100556,-0.239219,-0.636459,-0.217848,-0.220980,0.221126,-0.512154,-0.287246,-0.151723,0.127086,-0.223573,0.676312,0.208191,-0.493307,0.387110,0.246693,0.479941,-0.584269,0.709756,-0.214367,-0.266783,0.111687,0.244878,-0.345258,-0.427800,-0.113189,-0.154982,-0.471884,0.225697,-0.413401,0.240864,0.840120,-0.190383,-0.431869,0.345456,0.521961,-0.207018,-0.296080,0.251006,0.129003,0.248576,-0.027313,-0.005151,0.181891,0.067995,-0.010453,0.156833,-0.959865,-0.015045,0.081529,0.418908,-0.224245,0.595684,0.035047,-0.258739,0.346984,-0.108728,0.044585,-0.213339,0.271791,0.690643,-0.330873,0.272416,0.030597,0.338710,0.429475,0.198462,-0.476828,0.411719,-0.327859,-0.281141,0.056654,-0.190610,-0.629418,-0.222369,0.243504,0.203133,-0.196643,0.640231,-0.497344,-0.234251,0.015231,-0.103116,-0.129540,-0.727554,-0.317558,-0.163263,-0.334852,-0.326059,-0.250993,-0.032036,0.172029,0.010766,0.859730,-0.788496,0.153316,0.284280,0.032707,-0.113522,0.329809,0.225656,-0.368927,-0.339445,-0.361699,0.372673,-0.161273,0.140455,0.163124,0.580596,-0.282123,0.282318,-0.516635,0.621013', '26667010', '4724586', '10533913', '1303077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34852385', '间谍之妻', '剧情', '影片讲述1940年的日本神户，正值太平洋战争爆发前夕，福原里子正等待着在外国做贸易生意的丈夫的归来，这时她青梅竹马的儿时玩伴、已经是日军宪兵的津森泰治告诉里子，他丈夫竟然从外国带回一个女人，并且那个女人已经去世。在里子的追问下，才得知丈夫在那里偶然发现了“震惊世界”的事件，并下决心要向全世界曝光这件事，为了丈夫的安全和两人的幸福，里子当然想要阻止丈夫的行动。', '苍井优', '黑泽清', 7.3, 20705, 'tt11917942', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2609587395.jpg', 0.6, 4.1, 38.8, 44.9, 11.6, '0.005977,0.053054,-0.770697,0.468234,0.032861,-0.536198,0.670905,-0.065955,-0.553675,-0.403425,0.183519,0.982354,0.009008,0.341093,0.485038,0.302671,-0.327998,-1.055683,0.045517,-0.003559,-0.262075,-0.358460,0.133189,-0.187492,-0.212792,-0.275686,0.728190,0.140816,-0.099741,0.050922,0.489799,0.164309,-0.062349,0.547635,-0.086452,-0.033330,-0.044329,0.037283,-0.451575,0.250397,-0.172806,-0.375064,-0.193686,0.320703,0.135724,0.384648,0.593884,-0.080472,-0.360544,-0.119177,0.409901,-0.287134,-0.033852,0.231459,0.412790,-0.165263,0.340338,0.261532,-0.232735,-0.193072,0.104910,-0.066775,-0.583777,-0.213446,0.177689,0.073994,-0.653020,0.412227,-0.020129,0.169982,0.246029,-0.278540,0.354580,0.670065,-0.050417,0.545850,-0.500004,0.348991,-0.434952,0.142248,0.646451,-0.099246,0.257685,0.480150,0.077052,-0.225174,-0.097264,-0.167400,-0.634507,0.183143,0.261229,0.095902,-0.450068,0.336563,-0.371821,-0.246668,-0.064198,-0.480125,0.343809,-0.401911,-0.110974,-0.340728,-0.256650,-0.376893,-0.455491,0.183785,0.249630,-0.155663,0.601978,-0.768277,0.252021,0.724797,0.087639,-0.761542,0.387649,0.203162,0.173888,-0.466925,-0.025158,0.197572,0.149734,0.123526,-0.293964,0.084227,-0.187010,-0.345351,-0.431722,0.355225', '30345227', '1301022', '1307922', '1293829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34852765', '寄生异形', '科幻', '年轻女医生Tatiana Yurievna（奥莎娜·阿金什那 Oksana Akinshina 饰）因为使用具争议的技术而差点被吊销医师执照。但她被军方招募来到一个机密的研究机构，协助研究一个特别的案例，太空人Konstantin Sergeyevich（彼得·费奥多罗 夫 Pyotr Fyodorov 饰）。这位太空人历经神秘的太空意外后幸存返回地球，体内却多了外星生物，而且这个神秘生物只在深夜时现身。军方想拥有这个外星生物进行邪恶的计划，但女医生只想阻止外星生物杀害太空人。', '奥莎娜·阿金什那', '艾戈尔·阿布拉门科', 5.9, 6940, 'tt11905962', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2614767662.jpg', 3.8, 21.1, 54.5, 15.6, 5, '0.244974,0.306788,-0.816569,0.444381,-0.211154,0.036404,0.584171,-0.320647,-0.673745,-0.617218,0.100088,0.463276,0.151520,-0.011743,0.138586,0.145676,-0.391380,-0.037989,0.075114,-0.124882,-0.748480,-0.301262,-0.420478,-0.641652,0.048554,-0.507560,0.652832,0.175882,-0.498385,0.228973,-0.308850,0.526716,-0.174503,0.560964,-0.246822,-0.475228,0.511837,-0.044959,0.060347,0.237128,-0.300434,-0.133455,0.027628,0.024109,-0.145351,0.254722,0.688291,-0.357754,-0.160374,-0.484910,0.291080,-0.524994,0.018706,-0.018639,0.416029,0.179181,-0.251568,-0.136110,0.207885,-0.062530,0.165648,0.028273,-0.896651,-0.247603,-0.163699,0.036678,-0.195255,-0.033364,-0.325388,0.208746,-0.312329,-0.103728,0.478093,0.225129,0.242562,0.186169,0.221556,0.250448,-0.650679,0.145147,0.368729,-0.227533,-0.842537,0.284636,-0.238229,-0.987694,-0.276344,-0.335338,-0.208265,0.139679,0.166208,0.035639,-0.290613,0.198054,-1.112490,0.235629,-0.385671,-0.002493,-0.397382,0.022496,-0.234170,-0.813473,-0.109335,0.054652,-0.484790,0.188477,0.097596,-0.215101,0.923567,-0.385779,0.292021,0.710920,0.260171,-0.831849,0.676540,-0.094703,0.110085,-0.299952,-0.238116,0.377290,0.318293,0.433002,-0.217468,0.344562,0.009809,-0.367466,-0.107416,-0.030471', '1292680', '26290398', '1293442', '26921827');
