INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34865507', '小人物', '动作', '一天晚上，Hutch（鲍勃·奥登科克 Bob Odenkirk 饰）位于郊区的家中遭两名小偷闯入。为了避免暴力冲突，Hutch没有为自己或是家人反击。他的儿子Blake（盖奇·芒罗 Gage Munroe 饰）对他感到很失望，他的老婆Becca（康妮·尼尔森 ConnieNielsen 饰）似乎也因此更加疏远他。这起事件激发了Hutch心中压抑许久的情绪和本能，促使他走上残酷的道路，将揭露他黑暗的秘密和致命的能力。在拳头、枪弹和急速行驶的车阵中，Hutch必须从危险的敌人（阿列克谢·谢列布里亚科夫 AlexeySerebryakov 饰）手中救出自己的家人，并确保别人不会再把他视作无名小卒。', '鲍勃·奥登科克', '伊利亚·奈舒勒', 7.8, 148913, 'tt7888964', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2640615589.jpg', 0.4, 2.5, 26.5, 47.8, 22.8, '0.264658,-0.020018,-0.710317,0.577891,-0.321684,0.085941,0.925213,0.039111,-0.519254,-0.257531,0.372245,0.820483,0.017986,-0.098514,0.148391,0.041262,-0.243895,-0.763353,0.166812,0.005236,-0.251636,-0.395693,-0.353555,-0.474406,-0.096341,-0.403567,0.576215,0.190845,-0.424718,0.363070,0.019684,0.570839,0.169724,0.719039,0.035392,-0.021238,-0.150148,-0.328281,-0.115726,0.048610,0.200867,-0.554761,-0.167102,0.702141,-0.036629,0.489494,0.641727,-0.198524,-0.172573,-0.002285,0.119522,-0.525526,0.195006,0.207509,-0.042575,-0.170040,0.126912,0.410800,-0.300141,-0.038286,0.231320,0.139439,-0.635352,0.120740,0.024512,0.016744,-0.549259,0.241957,-0.363140,-0.047856,0.207434,-0.149826,0.089939,0.149119,0.107160,0.101154,-0.606044,-0.216504,-0.434368,-0.216451,0.710828,-0.314457,-0.012380,-0.026167,-0.361458,-0.128141,-0.034265,-0.193357,-0.558404,-0.329759,0.624643,0.232028,-0.202911,0.419025,-0.447402,-0.033675,-0.417202,-0.208935,-0.254880,-0.431842,0.195392,-0.310693,-0.057124,-0.454399,-0.444950,-0.053808,-0.023967,-0.189083,0.336367,-0.547794,0.295253,0.657565,0.329772,-0.519240,0.366294,0.179140,0.127562,-0.192863,-0.097570,0.284854,0.061099,0.307824,0.006959,0.248873,0.185358,0.032019,-0.114142,0.778540', '25828589', '25763555', '1299665', '1309116');
