INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34869495', '海边的异邦人', '爱情', '故事讲述住在冲绳离岛上的桥本骏(村田 配音)，结识了失去父母的孤独高中生知花实央(松冈 配音)，两位少年成了好友。实央为了快点成长为大人，决定离开本岛，两人渐渐断了联系。3年后，实央却再次出现在骏的面前，还大胆告白。', '村田太志', '大桥明代', 7.4, 12398, 'tt11193002', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2616484920.jpg', 1.4, 7.2, 33, 36.7, 21.7, '0.076386,-0.084367,-0.303855,0.267027,0.214434,-0.725319,0.157373,-0.010148,-0.422147,-0.258614,-0.018847,0.648750,-0.229483,0.524136,0.453114,-0.111751,-0.436729,-0.944250,-0.112869,-0.136562,-0.299663,-0.592986,0.295640,0.079774,-0.202889,-0.216733,0.755457,-0.222773,-0.069431,0.481031,0.237888,0.033881,-0.204539,0.243431,-0.384995,0.277681,0.019492,-0.056328,-0.491481,0.181641,-0.156304,-0.395723,-0.044743,-0.048591,0.198056,0.123049,0.845583,-0.147565,-0.306536,0.009389,0.289418,-0.016814,-0.086508,-0.053374,0.194499,0.160176,0.061191,0.286039,-0.506466,-0.160787,-0.276889,-0.182476,-0.254276,0.215212,-0.128369,0.103216,-0.384063,0.255363,0.155189,0.098134,0.234562,-0.658298,0.100335,0.246447,0.194742,0.086815,-0.399013,0.289517,0.211423,0.293729,0.875709,0.195664,0.169280,0.351525,0.142731,-0.082002,-0.135563,-0.057773,-0.237425,-0.094590,0.031045,0.088003,-0.170167,0.256467,-0.414065,-0.430560,-0.491110,-0.042246,0.131292,-0.323742,-0.110977,-0.393518,-0.238712,-0.046797,-0.185593,0.260939,-0.012013,-0.373659,0.836977,-0.966073,0.163156,0.524838,0.556114,-0.278008,0.418464,0.093741,0.011588,-0.198610,0.165369,0.325973,-0.102041,0.220237,0.304150,0.134659,-0.431819,0.224800,-0.596005,0.173272', '30345227', '1826173', '33218345', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34874432', '花束般的恋爱', '剧情', '山音麦 (菅田将晖 饰) 和八谷绢 (有村架纯 饰) 因错过尾班车而相遇，在深夜咖啡馆聊起文学、电影和音乐，喜好竟奇蹟地相似，二人瞬间坠入爱河。他们毕业后开始一边兼职工作，一边开始同居生活，更一起养拾回来的街猫，最大的目标就是维持俩口子的日常。 但时日流逝，不想改变也得改变。他失约于《牯岭街》， 她独赏郭利斯马基黑色幽默。五年盛放，世上唯一的花未必结果，爱情若只如初见。《垫底辣妹》《借着雨点说爱你》导演土井裕泰联同《东京爱的故事》神级编剧坂元裕二，强调真实生活感的浪漫，菅田将晖和有村架纯衬到绝合演，谱出这代最揪心的爱的故事。', '菅田将晖', '土井裕泰', 8.6, 492325, 'tt11219254', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2868462052.jpg', 0.3, 1, 11.5, 42.8, 44.3, '0.181522,0.018512,-0.555516,0.379583,0.208397,-0.278509,0.668910,0.235051,-0.153904,-0.172045,0.050960,0.386132,-0.191663,0.056931,0.257757,-0.233700,-0.118124,-0.540651,0.317693,-0.145515,-0.100674,-0.306513,0.144753,0.076627,-0.258637,-0.085628,0.564440,0.210985,-0.040950,0.485296,0.324246,0.051005,-0.013113,-0.029868,-0.142308,-0.025542,-0.285741,0.457162,-0.450646,-0.082539,0.121380,0.104106,-0.283710,-0.031631,0.115140,-0.013770,0.591730,-0.112520,-0.054062,0.014478,0.316943,-0.030041,-0.143844,-0.259451,0.259700,0.030808,0.386180,0.204350,-0.114476,-0.112909,-0.152043,0.094670,-0.386859,0.135847,-0.011725,0.163019,-0.188419,0.265860,0.023976,-0.282291,0.161692,-0.200662,-0.054529,0.019126,0.447909,0.313699,-0.248345,0.083550,-0.416870,0.321785,0.654249,0.121332,-0.090150,0.610800,-0.009552,-0.165226,-0.186807,-0.334521,-0.049387,-0.009759,-0.095153,-0.095225,-0.191249,0.104637,-0.629915,0.232912,0.177793,0.003320,0.228333,-0.436933,-0.130800,-0.642678,-0.086786,-0.515374,-0.158366,0.088083,0.309167,-0.414692,0.651786,-0.574639,0.335530,0.414056,0.152596,-0.515783,0.785993,0.404529,0.050333,-0.350089,0.114635,0.466327,-0.117867,0.000010,0.042003,0.139059,-0.173092,0.062239,-0.655677,0.413220', '2334814', '3055049', '3811356', '3214137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34875261', '忠贞', '情色', '莉娜是一位才华横溢的妇产科医生，她的丈夫谢尔盖是一家省级剧院的演员。他们的关系温柔而亲密，但完全没有性。莉娜怀疑谢尔盖有外遇，但她默默忍受，没有让她的嫉妒表现出来。莉娜开始和一些随机的男人发生外遇，她的不忠行为最终失控并改变了她的真实生活。', '叶夫根尼娅·格罗莫娃', '尼吉娜·赛福莱娃', 6.3, 6835, 'tt10516086', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2607223143.jpg', 2.4, 14.9, 55.4, 19.4, 8, '0.683950,0.031075,-0.793341,0.654574,-0.385457,-0.029440,1.374375,0.109638,-0.751601,-0.269388,0.305097,0.748303,-0.112190,0.029762,-0.062363,0.342378,-0.251796,-0.732258,0.327637,0.119434,-0.120416,-0.687246,-0.273181,-0.255619,-0.411142,-0.272602,0.748740,-0.377787,-0.312290,0.317158,0.263518,-0.031796,0.415714,0.809141,0.050795,0.062047,0.345151,0.007322,-0.047341,0.007945,0.327648,-0.099766,-0.374792,0.695813,-0.033696,0.713904,0.435946,0.097612,-0.595832,0.125539,0.611925,-0.254613,-0.007767,0.231787,0.153956,-0.117783,0.074458,0.068265,-0.090535,-0.359843,0.216623,0.445214,-0.785648,0.144212,0.170563,0.395192,-0.426739,0.591339,-0.300685,-0.338956,0.083187,-0.297555,0.146108,0.207305,0.160378,0.234167,-0.336391,-0.196788,-0.666180,0.167728,0.992003,0.248122,-0.673512,0.536281,-0.817738,-0.441335,-0.241920,-0.348271,-0.919411,0.224940,-0.038410,0.059119,-0.558117,0.299676,-0.238454,-0.186334,-0.340331,0.062561,-0.444604,-0.678373,0.080105,-0.564752,-0.416504,-0.809424,-0.655987,-0.624935,-0.008499,-0.635919,0.659703,-1.246022,0.115215,0.678240,0.394567,-0.811889,0.781953,0.419089,-0.132778,-0.235327,-0.242240,0.485032,-0.299154,-0.161802,0.024957,0.542778,0.225463,0.187913,0.027370,0.635222', '1296370', '4275444', '1308755', '3059036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34875369', '七号房的礼物', '剧情', '梅莫（阿拉斯·布鲁特·伊涅姆利 Aras Bulut Iynemli 饰）虽然生得人高马大，但却只有相当于6岁孩童一般的智慧，他带着女儿奥瓦（妮莎·索菲亚·阿克松古尔 Nisa Sofiya Aksongur 饰），同奶奶法蒂玛（塞利尔·托扬·乌伊萨尔 Celile Toyon Uysal 饰）生活在一起，日子虽然过得紧巴巴的，但一家人能够团聚就是最大的快乐。哪知道某日祸从天降，连一只蚂蚁都不愿意踩死的梅莫，竟然背负上了莫须有的杀人罪名，被关进了七号牢房中，单纯的梅莫并不知道自己即将面临怎样悲惨的命运。在监狱里，梅莫很快就和他的狱友们成为了朋友，梅莫开朗乐观的性格感染了周围的每一个人，给他们带来了快乐和希望，为了回报梅莫，这些曾经“穷凶极恶”的罪人们决定用他们的性命为筹码，来实现梅莫一个希冀已久的愿望。©豆瓣', '阿拉斯·布鲁特·伊涅姆利', '梅米特·艾达·厄兹泰金', 7.6, 40972, 'tt10431500', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2622417580.jpg', 0.6, 2.8, 29.8, 47.6, 19.2, '0.181774,0.088148,-0.497100,0.314181,-0.429105,-0.150292,0.810136,0.068273,-0.402789,-0.077035,0.123845,0.667113,0.091277,0.319090,0.032902,0.041944,-0.262779,-0.539116,-0.036045,-0.198398,-0.256356,-0.336007,-0.267777,-0.281946,-0.068381,-0.210038,0.321754,0.082871,0.244816,0.333938,0.408824,0.343125,0.115971,0.219368,-0.405962,0.039119,-0.149179,0.120545,-0.231442,0.085672,-0.128401,0.045849,-0.035054,0.269673,-0.022868,0.274724,0.502089,-0.425801,-0.097378,-0.142519,0.206186,-0.337808,0.045126,0.355173,-0.009572,-0.048148,0.351767,-0.014485,-0.130091,-0.086199,0.238484,-0.219398,-1.069428,-0.145072,0.255699,0.118378,-0.578084,0.450243,0.093312,0.019094,0.175209,-0.103006,0.067066,0.352910,0.210754,0.543776,-0.280653,-0.076128,-0.622627,0.132484,0.837988,-0.245365,-0.210523,0.304264,-0.470189,-0.176986,0.138621,-0.389209,-0.525090,-0.047923,0.213631,0.026094,-0.331353,0.417607,-0.407929,0.080684,-0.195940,0.045310,0.106400,-0.616966,-0.065086,-0.170605,-0.014784,-0.541685,-0.445729,0.158888,0.133288,-0.284668,0.831790,-0.666220,0.366789,0.476570,0.418061,-0.376965,0.714715,0.176816,0.207237,-0.004805,0.078416,0.240760,0.234382,0.192983,0.281048,0.176860,-0.122550,-0.089723,-0.384877,0.779729', '30163500', '26678784', '1