INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34875588', '真人快打传奇：蝎子的复仇', '动作', '聚焦了异世界和地球之间的千载难逢的比赛，这场比赛将最终决定地球和人类所有的公民的命运。地球保护者雷电必须聚集其领域最伟大的战士，以从邪恶的尚宗手上保卫地球，从而结束所有战斗。', 'Grey Griffin', '伊桑·斯波尔丁', 7.4, 7326, 'tt9580138', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2589037112.jpg', 0.8, 4.6, 35.4, 42.3, 16.9, '-0.201945,0.433067,-0.650499,0.819620,-0.373231,-0.007419,0.341087,-0.183871,-0.108440,0.078981,0.471876,1.287989,-0.105150,-0.265915,0.559041,-0.359234,-0.018957,-1.189797,-0.586891,0.088543,-0.877411,-0.381010,-0.406200,-0.071293,-0.115955,-0.484939,1.320360,0.231663,-0.265021,0.136425,0.081971,0.313492,-0.218151,0.657113,-0.251117,-0.731980,-0.235075,-0.118189,-0.773047,0.038633,-0.331338,0.332180,0.150363,0.653539,-0.115641,-0.361258,1.003615,-0.859700,0.279786,-0.654419,0.627349,-0.703336,-0.253540,-0.024690,0.552054,0.053227,-0.248270,0.393332,0.480661,0.081620,0.001585,-0.188882,-1.401706,-0.345162,-0.000463,-0.271260,-0.328176,0.480188,0.386820,0.052908,0.001953,0.215477,0.461480,0.754046,0.466787,0.204354,-0.276225,-0.412544,-0.073457,-0.010412,0.546924,-0.209568,-0.689444,0.175187,-0.253550,-0.672235,-0.475293,-0.260736,-0.403435,0.072633,0.374221,0.445185,-0.215121,0.944180,-1.224966,-0.085106,-0.036695,-0.758658,0.529083,-0.858782,-0.008188,-0.751615,-0.390522,-0.206301,-0.175128,0.295057,0.244687,0.158591,1.399420,-1.080789,-0.123858,0.713097,0.334580,-0.510113,0.469704,-0.060743,0.615146,-0.701974,0.034999,0.400890,-0.159125,0.971549,-0.381080,0.353498,0.070884,0.351843,-0.626347,1.016273', '27602116', '26759820', '25880986', '1292444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34880302', '人潮汹涌', '喜剧', '陈小萌（肖央 饰）一直渴望成为一名演员，但残酷的现实令他至今扔在龙套的位置上苦苦挣扎。没钱没工作没恋人没朋友还欠了一大笔钱的陈小萌想到了死，可是就连死神都抛弃了他，他数次自杀都以失败告终。一天，陈小萌去澡堂泡澡，意外邂逅了一位神秘且富有的男子（刘德华 饰），该男子在澡堂里意外摔倒昏迷被送进了医院，拾得了他的储物室手环的陈小萌决定顶替他的身份，享受一下富人的生活。头部的撞击令男子失忆了，凭借着零星的线索，他认定自己是陈小萌，并且顺藤摸瓜来到了陈小萌的出租屋，希望熟悉的环境能够令他更快的恢复记忆。在此过程中，男子邂逅了名为李想（万茜 饰）的自媒体人，两人之间碰撞出了火花。©豆瓣', '刘德华', '饶晓志', 6.5, 378327, 'tt11564214', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2632862664.jpg', 1.8, 12.8, 48.5, 30.4, 6.5, '0.210987,0.219024,-0.650338,0.331365,-0.304654,-0.357527,0.780237,0.120243,-0.522631,-0.126069,0.378071,0.602484,-0.154456,0.090152,0.229930,0.068644,-0.126903,-0.677254,0.021638,-0.115326,-0.536671,-0.183972,-0.268364,-0.220148,-0.191930,-0.258111,0.532339,0.172534,-0.295121,0.234952,0.205009,0.019321,-0.069241,0.588887,-0.435314,0.156029,0.029385,0.147940,-0.080580,0.313945,0.129173,-0.611003,-0.024042,0.274423,-0.130327,0.300584,0.662700,-0.031788,-0.201479,0.220213,0.268216,0.006806,-0.268877,0.183705,0.133170,-0.075273,0.278445,0.038635,-0.188341,-0.125162,0.268976,0.112445,-0.637926,0.079910,-0.007256,0.147451,-0.696596,0.694178,-0.077577,0.058548,0.085202,-0.358085,0.219646,0.096062,0.196929,0.301668,-0.203528,-0.072512,-0.372773,0.523477,0.671150,-0.111355,-0.396597,0.472548,-0.306392,-0.479447,-0.233820,-0.157547,-0.380800,0.054411,0.390844,0.175720,-0.387867,0.110890,-0.404485,0.043207,-0.239193,-0.033014,-0.191166,-0.219228,-0.229156,-0.332966,-0.226298,-0.112387,-0.332049,0.094399,-0.092820,-0.217841,0.444072,-0.781137,0.154835,0.591063,0.159566,-0.291395,0.786255,0.049437,-0.044594,-0.101829,0.052858,0.161847,0.009542,0.207407,0.264056,0.334490,-0.238652,0.063320,-0.443843,0.376707', '1302384', '1308755', '2124718', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34881718', '不可饶恕', '剧情', '露丝·斯雷特（布洛克饰）因暴力犯罪被判入狱，出狱后的她重新踏入社会，但自己的过去却不被原谅。面对来自她曾经称之为“家”的地方的无情评判，她获得救赎的唯一希望，就是找到当初被自己无奈丢下而疏远了的妹妹。', '桑德拉·布洛克', '诺拉·芬沙伊德', 7.9, 11478, 'tt11233960', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2707727239.jpg', 0.5, 2.2, 24.1, 49.7, 23.5, '0.334656,0.285844,-0.607380,0.540648,-0.449803,-0.589113,0.917104,-0.020395,-0.205250,-0.265834,0.213511,0.727850,0.219489,0.255549,-0.012598,0.386079,-0.033278,-0.496028,0.198197,-0.329885,-0.464215,-0.561057,-0.118215,0.046990,-0.177091,-0.129766,0.897525,0.164857,-0.248803,0.282175,0.311102,0.666525,0.291251,0.544202,-0.276524,0.106955,-0.212384,0.331396,-0.373636,0.359290,0.365003,-0.196246,-0.107704,0.619119,-0.277110,0.542059,0.421241,-0.358942,-0.237092,-0.287173,0.482500,-0.637132,0.053439,0.178102,-0.018993,0.116583,0.166977,0.219575,-0.226235,-0.174560,0.156509,0.020008,-0.711454,0.021409,0.277452,-0.004250,-0.447986,0.364908,-0.296550,-0.145707,0.190438,-0.294744,0.214235,0.228914,0.340146,0.541447,-0.553483,0.059869,-0.623985,0.065201,0.768155,-0.185394,-0.317197,0.193858,-0.170814,-0.137374,0.550804,-0.664375,-0.468958,0.245758,-0.005450,0.312966,-0.242588,0.177079,-0.328978,-0.360999,-0.430338,0.023870,0.089221,-0.884879,0.099264,-0.077320,-0.140756,-0.198182,-0.527597,-0.269080,0.051610,-0.880007,0.553514,-0.826449,0.672854,0.497006,0.729392,-0.839880,0.518064,0.211795,0.079349,-0.076825,0.205733,0.622149,0.361350,0.265656,0.321434,-0.153583,-0.054863,-0.060612,-0.128819,0.738365', '1307584', '35287908', '1300953', '6745433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34884711', '流浪猫鲍勃2：鲍勃的礼物', '剧情', '詹姆斯（卢克·崔德威 Luke Treadaway 饰）从未想过一只流浪的橘猫可以拯救自己的人生。戒毒成功后的他与猫咪鲍勃过着贫苦却温馨的日子，一人一猫的卖唱风景总是能在街头成为焦点，为他们带来更多收入。眼看着生活开始有了起色，不料鲍勃却突然受伤，詹姆斯也面临着被迫和鲍勃分离的危机……', '卢克·崔德威', '查尔斯·马丁·史密斯', 6.6, 20136, 'tt9564270', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2674289979.jpg', 1.2, 12, 51.8, 27.3, 7.7, '0.115245,0.059444,-0.704169,0.342479,0.086875,-0.531217,1.098036,0.389522,-0.396434,-0.141303,0.139222,0.564840,-0.092476,0.502917,0.168667,-0.155900,-0.229473,-0.668978,0.089820,0.214525,-0.154079,-0.068491,-0.418264,-0.332570,-0.186887,-0.207088,0.611261,0.188428,-0.099693,0.517446,0.168794,0.090599,0.055652,0.828831,-0.487193,0.131538,0.096411,0.336510,-0.290790,0.296681,0.176505,-0.476408,-0.596817,0.112778,-0.187225,0.262269,0.847457,-0.329886,-0.124753,-0.051812,0.209595,-0.147755,0.071118,0.043734,0.122300,-0.017617,0.080283,-0.077939,-0.207316,0.230073,0.232017,-0.220000,-0.757040,0.083408,-0.215617,0.502839,-0.520991,0.481940,0.153074,0.179006,0.138256,-0.320219,-0.053734,0.380847,0.192025,0.363122,-0.399965,0.301050,-0.794897,0.249414,0.958926,-0.255963,-0.374963,0.490842,-0.411476,-0.563903,-0.058323,-0.294813,-0.607048,-0.305982,0.573394,0.163396,-0.390423,0.402388,-0.630940,0.344710,-0.176833,-0.185743,-0.054265,-0.291001,0.064704,-0.437448,0.110303,-0.540095,-0.531274,0.407214,0.012489,-0.567462,0.726724,-0.812908,0.340389,0.635579,0.344225,-0.340782,0.655749,0.287297,0.352783,0.072490,-0.262792,0.568098,-0.142797,0.378115,0.510866,0.200848,0.013609,0.093382,-0.349019,0.827850', '21619567', '4275444', '1428054', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34884712', '不要抬头', '喜剧', '天文学研究生凯特（詹妮弗·劳伦斯 Jennifer Lawrence 饰）和她的导师兰道尔博士（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）在一次研究中震惊的发现，一颗像喜马拉雅山那么大的彗星正在全速向地球靠近，不出意外的话，6个月之后，这颗彗星会抵达地球，将这里的一切都毁灭。凯特和兰道尔找到了美国总统奥尔良（梅丽尔·斯特里普 Meryl Streep 饰），希望她能够重视此事，可是，他们得到的却是嘲笑和蔑视。之后，师徒两人转而向媒体求助，决定跳过政府，直接向民众揭露这个秘密，效果当然也不尽如人意，不仅如此，凯特还因为泄露了国家机密而遭到了FBI的逮捕。当奥尔良总统深陷艳照丑闻中之时，她终于想到了这两个可怜的科学家，于是，她决定再给他们一次机会，借由政府之口将地球将要毁灭的消息昭告天下。©豆瓣', '莱昂纳多·迪卡普里奥', '亚当·麦凯', 7.6, 226469, 'tt11286314', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2730833093.jpg', 0.4, 3.4, 29.3, 50.7, 16.1, '0.093534,0.092140,-0.902330,0.712325,0.135945,-0.331552,0.453319,-0.137332,-0.424879,0.030907,-0.106538,0.744617,-0.453230,0.122314,0.254646,0.183731,-0.570589,-0.714994,0.183463,-0.564564,-0.337823,-0.663891,-0.234629,-0.447465,-0.014909,-0.194860,0.512296,0.219466,-0.299026,0.357439,0.248240,0.290436,0.187687,0.571532,0.036919,-0.020201,0.098595,-0.143273,-0.295979,0.472253,0.231961,0.049850,-0.115286,0.519657,0.063677,0.404885,0.289803,-0.426234,-0.109887,-0.211319,0.298241,-0.451694,0.258436,0.358117,0.330783,-0.077981,-0.035173,0.223390,-0.172279,-0.004728,0.215127,-0.080868,-0.548971,-0.061627,-0.240917,0.286259,-0.431226,0.151499,-0.137956,0.023443,-0.127636,-0.240270,0.173273,0.428790,0.366836,0.304867,-0.276887,0.036080,-0.418087,-0.004001,0.464927,-0.057220,-0.327836,0.303718,0.149375,-0.418356,-0.171284,0.018392,-0.326078,0.115631,0.539959,0.262285,-0.010082,0.506772,-0.388617,-0.290716,-0.513400,-0.272602,-0.041421,-0.438372,0.082793,-0.654285,-0.021399,0.030534,-0.329349,0.162667,0.107770,-0.222412,0.695797,-0.403038,0.231914,0.604916,0.569272,-0.570485,0.438728,-0.045684,0.086644,-0.159843,0.044182,0.216013,0.383784,0.375262,0.179223,0.254455,0.348974,-0.392055,-0.201479,0.189108', '34461680', '3285622', '1309115', 