INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34888057', '甘草披萨', '剧情', '这部影片以20世纪70年代为背景，故事围绕一位高中生，讲述了阿拉娜·凯恩和加里·瓦伦丁在1973年在圣费尔南多谷成长、四处奔波和坠入爱河的故事。', '阿拉娜·哈伊姆', '保罗·托马斯·安德森', 6.8, 21572, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2867240673.jpg', 1.6, 9.3, 45.8, 33.6, 9.8, '-0.095317,-0.476087,0.019623,0.608727,0.318166,0.130724,0.608139,0.010370,-0.574457,-0.508410,-0.380883,0.932415,-0.351973,0.328445,0.727369,0.016784,-0.930561,-0.702371,0.158267,-0.197007,0.035616,-0.607476,0.040304,-0.297129,-0.143528,-0.949521,0.789417,-0.167403,-0.389240,0.416478,-0.075101,0.640804,-0.357361,0.026603,-0.267484,0.220840,0.277933,0.152115,-0.354774,0.130764,-0.417145,-0.016281,-0.298037,-0.501074,0.145394,0.081826,0.770541,-0.253939,0.386535,0.162337,0.322184,-0.381130,-0.204491,-0.244750,0.659458,-0.248182,0.292429,0.880756,-0.034499,-0.353551,-0.458388,-1.134220,-0.803995,0.002293,0.314738,0.013563,-0.734890,0.106514,0.204595,0.163536,0.290959,0.071165,-0.262808,0.179614,0.627036,0.843289,0.090947,-0.101093,-0.389780,0.583182,0.675354,0.289848,-0.264019,0.958758,0.276521,-0.579038,-1.031931,0.168651,-0.789526,0.118009,0.211465,-0.263901,-0.337694,0.754655,-0.751950,-0.120100,-0.203091,-0.595072,0.305789,-0.675281,-0.754520,-0.484518,-0.645326,-0.146988,-0.072296,-0.225341,-0.159707,-0.361106,1.105888,-0.598862,0.391663,0.536942,-0.185436,-0.496974,1.327221,0.105163,0.064576,-0.613095,-0.005416,1.038963,-0.188517,-0.130406,-0.219099,0.171826,-0.367722,0.119230,-0.545105,0.521579', '34947776', '1291564', '25738406', '30349667');
