INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34890458', '天才不能承受之重', '喜剧', '尼古拉斯·凯奇（Nicolas Cage）有新片了，这次他要在电影里演自己。该片主角就是尼古拉斯·凯奇本人，他疯狂的渴望在昆汀·塔伦蒂诺的下部电影里得到一个角色，他经常会和自己脑海中一个90年代的自己对话，后者不断吐槽他“老是接烂片”、“再也不是当年那个电影明星”了。讲述破产边缘的凯奇为了100万美元的酬劳去参加一个亿万富翁粉丝（佩德罗·帕斯卡 饰）的生日派对，但这位富豪是一个危险的毒枭。当凯奇被一名CIA特工招募后，事情发生了意想不到的转变，为了拯救自己和亲人，他被迫出演一个终生难忘的角色——尼古拉斯·凯奇，用他最具标志性和最受喜爱的银幕角色来履行自己的传奇人生。《才华不能承受之重》会有多个桥段向凯奇的代表作致敬，包括《离开拉斯维加斯》（Leaving Las Vegas）、《变脸》（Face-Off）、《极速60秒》（Gone in 60 Seconds）等。影片风格酷似凯奇主演过的2002年电影《改编剧本》（Adaptation），后者是导演斯派克·琼斯与编剧查理·考夫曼联手的杰作。', '尼古拉斯·凯奇', '汤姆·戈米肯', 6.9, 29743, 'tt11291274', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2869531882.jpg', 1.2, 7.9, 47.5, 34.1, 9.4, '0.132299,0.004330,-0.681401,0.711594,0.007477,-0.169701,0.984241,-0.009536,-0.362979,-0.296515,0.423260,1.288637,-0.349592,0.051177,0.291191,0.047059,-0.289624,-0.676970,-0.140026,-0.062440,0.022218,-0.252422,-0.440313,-0.363489,-0.208742,-0.302549,0.610712,-0.259528,-0.398117,0.374862,0.647943,0.230146,0.258160,0.259450,-0.050721,0.264081,0.234485,-0.159750,-0.252066,0.450465,0.276667,-0.190473,-0.190694,0.378103,-0.148335,0.274124,0.429727,-0.083974,-0.043670,0.031736,0.464983,-0.413629,-0.096885,0.058034,0.070830,-0.094761,0.324756,0.144030,0.000652,0.062013,-0.063965,-0.270209,-1.113411,-0.184595,0.057371,0.277601,-0.643839,0.302538,-0.226048,-0.092537,0.192206,-0.349006,0.207382,-0.028844,0.489312,0.319443,-0.128396,-0.008693,-0.347418,0.721711,0.752167,0.143624,-0.314327,0.453669,-0.219982,-0.404956,-0.294503,-0.341193,-0.754318,0.397889,0.478046,-0.263228,0.025424,0.180488,-0.351234,-0.198583,-0.201346,-0.274544,-0.092287,-0.443898,0.003557,-0.695943,-0.303890,-0.281827,0.005257,-0.263585,0.002556,-0.486606,0.843031,-0.669986,0.062332,0.798077,0.205058,-0.456256,0.825664,0.279712,-0.034583,-0.119799,0.075191,0.095772,-0.061187,0.028771,-0.066434,0.258237,0.202553,-0.369761,-0.213030,0.563152', '30162520', '3119246', '30167633', '1299628');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34890921', '柳浪闻莺', '剧情', '影片改编自茅盾文学奖得主王旭烽系列小说《爱情西湖》，故事以西湖十景之一的“柳浪闻莺”为背景，主要讲述了上世纪90年代江南越剧团两个姑娘与一个画家间的情感纠葛。极具天赋的女小生垂髫（汪飏 饰），与花旦银心（阚昕 饰）自幼相识，一起在戏班子长大，两人性格迥然不同，但情同姐妹。垂髫至情至性，为舞台而活；银心看似单纯天真，实则是个知进退、会钻营的女孩。她俩本是彼此眼中最重要的那个人，可世事无常、种种分歧纷沓而至，特别是杭州画家工欲善（郑云龙 饰）的出现，让相依为命的两个女孩变得相爱相杀。时代变迁，越剧由盛转衰，垂髫与银心的命运与越剧一同沉浮。曲终人散之时，放眼世间，她最放不下的那个人，还是她。', '汪飏', '戴玮', 6.1, 11966, 'tt14760734', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2869236293.jpg', 2.9, 20.3, 50.6, 22.2, 4, '0.421409,-0.145897,-0.455275,0.733772,0.117039,-0.280248,0.897387,0.143238,-0.609203,-0.262413,0.042486,0.706177,-0.126937,0.154461,0.372223,-0.120708,0.065363,-0.546398,-0.067058,-0.280141,0.063443,-0.375078,-0.050722,0.259004,-0.371461,0.058222,0.790576,0.133293,0.030626,0.583292,0.288015,0.136716,-0.479384,0.066409,-0.274301,-0.097571,-0.157742,0.157572,-0.375793,-0.152020,-0.198410,-0.254313,-0.260769,-0.050242,-0.594966,0.012636,0.739931,-0.350767,0.083401,-0.321460,0.534759,0.086319,-0.186984,-0.102316,0.192693,-0.166917,0.379511,0.435705,-0.007567,-0.135589,-0.028585,-0.169329,-0.406950,0.093408,0.604632,0.175927,-0.596815,0.191906,0.179543,-0.347515,-0.194371,-0.284359,0.231009,0.207160,0.626656,0.358094,-0.046916,-0.299086,-0.334836,0.309876,0.811946,0.255895,-0.257343,0.551652,-0.271236,-0.548690,-0.063626,-0.343255,-0.677919,0.094152,-0.096426,-0.162969,0.082250,0.421609,-0.695771,0.225821,0.142355,0.411437,0.041787,-0.576686,-0.043108,-0.233526,-0.516316,-0.795848,-0.352550,-0.108061,0.202438,-0.314039,1.176411,-0.788742,0.043931,0.411357,-0.146598,-0.496967,0.955551,0.280404,0.145298,-0.408750,-0.088804,0.347938,-0.269798,-0.323460,-0.462066,0.350905,-0.311938,0.166488,-0.283574,0.273833', '6963575', '3445516', '26283288', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34894631', '母亲', '惊悚', '本片是根据实际发生的「少年杀害了祖父母事件」的构思而改编成电影的崭新故事。长泽扮演懒散奔放的母亲·秋子，挑战堕入了社会黑暗面的女人，而阿部サダヲ则饰演与秋子没有结婚登记而同居的丈夫·遼，影片将重点刻画秋子和她年幼的儿子·周平（郡司翔）之间所展开的关系。', '长泽雅美', '大森立嗣', 6.2, 8637, 'tt11656548', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2599858573.jpg', 4.1, 17, 52.2, 19.7, 7, '0.434966,-0.251571,-0.422900,0.773413,-0.158893,-0.096372,0.803685,0.363666,-0.284214,-0.345465,0.318993,0.597270,-0.119173,0.172944,0.458781,-0.069987,-0.195990,-0.870189,-0.184967,0.047426,0.015211,-0.679161,-0.093904,-0.148012,-0.100335,-0.424497,1.176879,-0.211705,-0.477730,0.192054,0.448408,0.238073,-0.467849,0.122252,0.000826,0.285686,-0.154249,0.240627,-0.408933,0.152724,-0.010054,-0.179352,-0.139066,0.106061,-0.286666,0.544447,0.963126,-0.202043,-0.144827,-0.324231,0.861126,-0.311742,-0.082291,0.170163,0.326105,0.239598,0.332694,0.412025,0.081961,-0.334489,0.158674,-0.353874,-0.783382,-0.041158,0.404129,0.233288,-0.390200,0.458924,-0.206508,-0.217626,0.339642,-0.319042,0.194031,0.417863,0.694757,0.515681,-0.162822,-0.055856,-0.140425,0.465318,0.557081,0.204523,-0.171148,0.609074,-0.394283,-0.487165,-0.331764,-0.451194,-0.488598,0.252576,0.033068,-0.017419,-0.311348,0.445278,-0.342660,-0.330574,0.007071,-0.138080,0.259900,-0.457422,-0.113186,-0.686124,-0.456275,-0.676187,-0.230918,-0.234056,0.069037,-0.370213,0.798599,-0.916648,0.027194,0.427274,0.183260,-0.581565,0.527157,0.284874,0.019651,-0.313164,0.122408,0.157833,-0.019504,-0.102200,-0.041058,0.182707,-0.252012,-0.113764,-0.528219,0.482497', '26759820', '25880986', '10467125', '24499012');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34894678', '明日家族', '剧情', '小野寺理纱（宫崎葵饰）四年前在婚礼上遭遇新郎逃婚，现如今心情已经平复，一直跟父母生活在一起。其父亲俊作（松重丰饰）曾经是糕点生产公司的营业部部长，现因人事变动被调到了其他的部门，而该部门新上任的部长就是俊作曾经的下属兵头幸太郎（永山瑛太饰）。其母真知子（松坂庆子饰）是一个性格开朗的家庭主妇，经常去仓桥响子（一路真辉饰）开的插花班上课。仓桥响子的前夫村上洋一（六平直政饰）是俊作的发小兼前辈，他经营了一家小酒馆，俊作是他家的常客。四年前父亲俊作为了想和女儿女婿住在一起建了一栋双户型的别墅，然而因为理纱被逃婚，现在就理纱、俊作以及真知子，这一家三口住在别墅里。某天理纱说自己被求婚了，要带个对象回来给俊作和真知子看看，谁知带回来的人竟然是兵头幸太郎。之前的下属，现如今成了自己的上司兼准女婿……理纱和幸太郎的感情究竟会如何发展？理纱、幸太郎会和俊作及真知子同住在一个屋檐下吗？', '宫崎葵', '土井裕泰', 7.7, 10274, 'tt12559772', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2580887608.jpg', 0.2, 2, 29.7, 48.5, 19.5, '0.221564,-0.172575,-0.264793,0.333901,-0.184460,-0.526071,0.293132,0.451346,-0.573730,-0.503421,0.041964,0.732887,-0.030187,0.638179,0.313212,0.213301,-0.061151,-0.454898,-0.155255,-0.055558,-0.123013,-0.411179,0.146366,-0.032202,-0.116136,0.087079,0.519977,-0.157419,0.119599,0.089570,0.329401,0.257863,-0.188336,-0.024432,-0.218328,0.230185,0.186378,0.217155,-0.264256,0.276940,-0.109197,-0.184361,-0.121533,-0.039289,0.489388,0.335282,0.425062,0.114879,-0.251501,-0.193697,0.110117,0.005219,-0.179547,0.381223,0.507303,-0.047550,0.349670,0.423012,-0.426619,-0.270082,0.100535,-0.167947,-0.457700,0.103228,0.115784,-0.070850,-0.554234,0.470619,-0.120044,-0.293243,0.257003,-0.396613,0.371678,0.560102,-0.082850,0.345036,-0.330521,0.130112,-0.180448,0.201091,0.751738,-0.061721,0.229471,0.348044,-0.022276,-0.180653,-0.088721,-0.228876,-0.392399,0.067575,-0.057408,-0.012201,-0.092220,-0.054809,-0.350698,-0.266738,-0.176996,0.160792,0.313442,-0.301453,-0.137255,-0.463396,0.223643,-0.482478,-0.221438,0.164599,0.165308,-0.199687,0.437690,-0.988501,-0.135044,0.455223,0.320461,-0.407374,0.706031,0.140137,-0.114111,-0.203865,0.001006,-0.207762,0.038609,0.405079,0.141640,0.440200,0.037306,-0.307139,-0.283569,0.173133', '30345227',