INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34894753', '沐浴之王', '喜剧', '在一次搓澡服务中，富二代肖翔（彭昱畅 饰）和搓澡工周东海（乔杉 饰）发生矛盾，让周东海面临生活困境。肖翔因跳伞事故被送到医院记忆全失，周东海恰巧撞见，心生一计，骗肖翔是自己的弟弟并骗回周家澡堂当搓澡工，于是一个富二代开始了一段终身难忘的搓澡生涯……', '彭昱畅', '易小星', 6, 293476, 'tt13347818', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2627788612.jpg', 4, 20.4, 53.4, 18.5, 3.7, '0.093570,-0.092385,-0.379033,0.415879,-0.234174,-0.234387,0.583698,0.109808,-0.625972,-0.583698,-0.271773,0.567788,-0.219448,0.735939,0.431486,-0.422822,0.141711,-0.459185,0.227647,0.145122,-0.391522,-0.132380,0.231289,-0.377049,0.018497,0.050183,0.256987,0.127009,-0.445683,0.476352,0.422606,0.409171,-0.259515,0.517434,-0.299197,0.163643,-0.044659,0.315321,-0.149017,0.017536,-0.071431,-0.579610,0.271853,0.174694,0.269494,0.016122,0.694740,0.467224,-0.237962,-0.293955,0.352657,-0.197519,-0.151791,-0.301718,0.600977,0.038468,-0.031357,-0.160612,-0.014171,-0.008676,0.260917,-0.141712,-0.427561,-0.223765,0.197231,-0.425808,-0.531236,0.133209,0.343246,0.040870,-0.015971,0.037735,0.270479,0.227524,0.703846,0.406717,-0.109558,0.380115,-0.413676,0.500909,0.786761,-0.288113,0.148767,0.196031,0.196769,-0.279095,0.242638,0.286186,-0.567322,0.219985,0.447292,-0.175211,-0.147983,0.195409,-0.070182,-0.371350,-0.279702,-0.057710,0.290412,-0.081165,0.117046,-0.387103,-0.124375,-0.346279,-0.344768,-0.062698,0.075977,-0.170516,0.100300,-0.595414,0.117045,0.274789,-0.136311,-0.812447,0.425877,0.319863,0.512325,-0.265454,0.342803,0.159387,0.296060,0.269969,0.118295,0.132164,-0.349133,0.111503,0.085162,0.127057', '1308035', '1293265', '1297710', '22555690');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34902639', '同学麦娜丝', '剧情', '四个高中同学毕业后常常聚在泡沫红茶店刁牌、唬烂三小，但聚会后他们还是要继续面对生活的艰难：电风（郑人硕饰）是保险业务员，领着微薄薪水省吃俭用买了新房，因为女友怀孕将步入婚姻的人生阶段；从事纸扎屋行业又有阴阳眼的闭结（刘冠廷饰），因长期照顾卧病在床的阿嬷错过婚姻，想寻求婚姻介绍所找一个好女人结婚；罐头（纳豆饰）在一次吞药自杀后洗心革面，接下了户政所的工作，因此与他心目中的女神校花麦娜丝重逢；添仔（施名帅饰）是怀才不遇的导演，却在机缘下被政客（陈以文饰）相中开始选举之路…', '施名帅', '黄信尧', 7.9, 101133, 'tt12899858', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2623673142.jpg', 0.4, 1.8, 22.5, 51.3, 24, '0.059710,0.052692,-0.325817,0.313448,-0.169710,-0.443393,0.626062,0.160532,-0.338403,-0.199261,-0.003595,0.618212,-0.196510,0.503191,0.122440,-0.157652,0.047492,-0.558537,0.065723,0.016710,-0.285669,-0.240211,0.070738,-0.009591,-0.447100,-0.105708,0.699595,0.059407,-0.013921,0.187694,0.273787,-0.023865,0.051961,0.251094,-0.177099,-0.144082,-0.008838,0.238611,-0.561923,0.204139,0.130518,-0.091970,-0.234529,-0.008739,0.346533,0.257026,0.436214,0.166099,-0.195296,-0.236491,0.413569,-0.039591,-0.241614,0.050099,0.222708,0.189390,0.443159,0.313331,-0.151241,-0.052278,0.042122,-0.213230,-0.526503,0.081588,0.126868,-0.217221,-0.637682,0.302198,-0.010428,-0.183056,0.114068,-0.333898,0.189011,0.408563,0.480716,0.429129,-0.225472,0.289445,-0.489580,0.390016,0.718836,0.011557,-0.018997,0.471601,-0.135521,-0.372497,0.393086,-0.271238,-0.410579,0.039158,0.079596,0.021793,-0.236303,0.120953,-0.575581,0.049169,-0.192466,-0.035424,0.293968,-0.359289,-0.091620,-0.358578,-0.014898,-0.248511,-0.481089,0.127529,0.203026,-0.442543,0.608855,-0.743720,0.129584,0.648044,0.452702,-0.733945,0.954897,0.273346,0.435379,-0.130238,0.219830,0.028261,-0.211257,0.297119,-0.060671,0.213214,-0.097465,-0.032580,-0.345158,0.414966', '2124718', '3055049', '5985887', '1296569');
