INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34905764', '乔西的虎与鱼', '动画', '活在自我世界中的乔西，遨游在自己感兴趣的绘画和书籍的海洋中。自幼便一直坐在轮椅上的她，某天在一个危险的斜坡上差点摔倒的时候，得到了大学生恒夫的帮助。专攻海洋生物学的恒夫，为了实现自己能够亲眼看一下只生活在墨西哥的梦幻鱼群的梦想，日夜不停地在进行着兼职打工。和乔西相依为命的祖母千津看到这样的恒夫，向他介绍了一份兼职工作。这份工作的内容就是听从乔西的要求，并想办法满足她。然而，固执且不善与他人交流的乔西对恒夫非常刻薄，而恒夫也没有在意乔西是个残疾人，直率地回应她。就这样逐渐地，双方的距离缩短，开始了解对方。在两人接触的过程中，乔西也下定决心，要与恒夫一起去看看自己梦寐以求的外面世界……影片改编自田边圣子小说《Jose与虎与鱼们》。', '清原果耶', '田村耕太郎', 6.3, 7628, 'tt12879624', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2677553878.jpg', 3.2, 11.5, 55.8, 24.5, 5, '0.475122,0.182430,-0.849451,0.968269,-0.219760,-0.335242,0.843041,-0.080379,-0.397783,-0.018001,0.034432,0.899361,0.007819,0.276487,0.245776,0.137137,-0.406113,-0.934852,-0.192821,0.004720,-0.304504,-0.714780,-0.239889,-0.292487,-0.304135,-0.288743,0.717769,-0.009098,-0.239370,0.418576,-0.023047,-0.000924,0.019290,0.600550,-0.377463,-0.131481,-0.212045,0.133821,-0.161445,0.154936,0.275788,-0.184262,-0.350631,0.153741,0.187672,0.151235,0.706376,-0.265957,-0.266476,0.018490,0.212610,-0.086571,0.080804,0.182592,0.176311,-0.058629,0.214378,0.189136,-0.097305,0.075037,-0.131237,0.032300,-0.882286,-0.299928,-0.073581,0.300203,-0.753438,0.524004,0.120963,-0.248528,0.074862,-0.467032,0.033062,0.438711,0.148960,0.513732,-0.424616,-0.001813,-0.323336,0.233947,0.473008,0.257067,-0.234577,0.554334,-0.242616,-0.459105,-0.207947,-0.039753,-0.522317,-0.399811,0.269188,0.162048,-0.431415,0.044021,-0.696097,0.281301,0.064008,-0.438456,-0.150518,-0.669270,-0.018715,-0.536219,-0.078512,-0.606079,-0.405160,-0.017120,0.176346,-0.655363,0.788305,-0.758603,0.163718,0.628806,0.441754,-0.278276,0.991899,0.173409,-0.039953,-0.239154,-0.187866,0.159994,-0.124783,0.441283,0.102342,0.500333,0.199540,0.076265,-0.619944,0.618284', '3055049', '27666513', '30162520', '26958479');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34906611', '辛弃疾1162', '动作', '1161年，大宋国土幅裂，金主完颜亮侵占中原，并再欲大举南侵。中原百姓不堪严苛压榨，奋起抗金，年方二十一岁的辛弃疾聚集乡众参加了由耿京领导的一支声势浩大的起义军，战功赫然。1162年，力主驱逐侵虏、收复失土、实现统一的辛弃疾，奉命南下说服南宋朝廷北伐，在他完成使命归来，却见主帅耿京被叛徒杀害后义军溃散的乱状。侠义所使、激愤所驱和再凝义军士气所谋，辛弃疾率五十多骑突袭数万人金军大营，生擒叛徒南归，写就一段悲壮的峥嵘历史。', '谢苗', '张哲', 6, 5187, 'tt12764298', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2579789452.jpg', 5.5, 19.5, 50.7, 19.1, 5.1, '-0.292969,0.115597,-0.500468,0.252013,0.269392,0.065788,0.086128,0.157434,-0.392987,0.067644,0.059025,0.205998,0.370860,-0.260909,0.206819,-0.336498,0.143139,-0.909527,-0.070579,-0.102463,0.306227,-0.161705,-0.132895,-0.297679,-0.067099,-0.186313,0.925443,0.582735,-0.231054,0.772371,0.091566,0.010121,0.143415,0.474160,0.151768,-0.088107,-0.408990,-0.225680,-0.223417,-0.075265,-0.681392,-0.591006,-0.546384,0.024508,-0.439049,0.377019,0.633084,-0.319550,0.156201,-0.170589,0.103728,-0.333968,-0.072674,0.110326,0.617880,0.291215,-0.177408,0.439733,0.118039,-0.153508,-0.503715,-0.050859,-0.367963,-0.430164,0.158920,-0.295943,-0.469673,0.657401,-0.097508,0.189501,-0.031853,-0.235423,-0.211896,1.023567,0.002154,0.173109,0.066905,-0.101635,-0.416352,0.625652,0.490088,-0.451403,-0.264309,-0.668585,0.137947,-0.129646,0.440013,-0.578235,-0.306453,0.027198,0.214770,-0.413797,0.285157,0.235278,-0.477286,-0.201100,-0.718698,-0.028213,0.161996,0.215873,-0.017590,-0.045627,-0.163115,0.252362,-0.057272,0.189356,0.401533,0.425331,0.519745,-0.383430,-0.164953,0.373357,0.463266,-0.981921,0.042562,0.192163,-0.073173,0.278270,-0.069927,0.304597,0.272944,0.401938,0.179098,-0.122923,-0.242004,-0.317902,-0.322923,0.245893', '1307201', '26852888', '3078390', '1424552');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34906689', '昨日的美食 2020新年特别篇', '剧情', '2019最温暖的「昨美CP」在2020再度同框，不料却出现了感情危机。故事描述由西岛秀俊饰演的「史朗」一直憧憬的女偶像「三谷麻美」居然出现在眼前，史朗兴奋不已，却也引发贤二(内野圣阳饰)的不悦；而新对象出现、与史朗 越来越忙碌的工作也让两人的感情逐渐出现变化。', '西岛秀俊', '中江和仁', 8.9, 9618, '', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2579566772.jpg', 0.3, 0.4, 8.4, 35.4, 55.4, '0.149142,-0.231426,-0.963626,0.540634,0.235432,-0.280595,1.133512,0.365241,-0.411663,-0.516993,0.459734,0.679489,-0.730445,0.292306,0.527520,-0.342256,-0.079978,-0.774342,-0.007404,-0.059532,0.032994,-0.233295,-0.202912,-0.183335,-0.149708,-0.562856,0.789341,0.042995,-0.182466,0.615430,0.448783,0.251405,-0.404146,1.042743,0.100256,0.061398,0.021848,0.340000,-0.095712,-0.055871,-0.043380,-0.446918,-0.275529,0.314358,-0.342785,0.400529,0.899062,-0.145886,-0.505847,0.138928,0.384073,-0.347361,-0.255503,-0.005037,0.492309,-0.094994,-0.035383,-0.081215,-0.276287,-0.169425,-0.278377,-0.058097,-0.782702,0.357654,-0.118810,0.637006,-0.382157,0.237694,0.204156,-0.288373,0.273794,-0.174476,0.208639,0.386024,0.576525,0.324123,-0.770254,0.412529,0.155473,-0.228209,0.423209,0.140510,-0.292523,0.724861,-0.322675,-0.412456,-0.169946,0.176714,-0.540956,-0.102898,-0.090380,0.349917,-0.151604,0.490926,-0.781423,-0.061484,0.083013,-0.166864,0.231257,-0.538495,-0.274194,-0.675257,-0.365154,-0.290861,-0.504507,0.338253,-0.043945,-0.384178,0.936601,-1.036302,0.133360,0.269025,0.033526,-0.321839,0.403714,0.379921,-0.093389,-0.384543,-0.512375,0.374252,-0.015364,0.165618,-0.095162,0.383827,-0.288177,0.025558,-0.415236,0.584271', '21348112', '3059036', '2301363', '4079119');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34906732', '在京都小住', '剧情', '在东京生活的江东佳奈（木村文乃）为了照顾受伤的舅公只身来到了京都。在京都生活多年的舅公大贺茂（近藤正臣）给了外甥女一份自己精心手绘的地图方便她在京都出行。这幅地图记录了一个对父辈而言韵味十足，对年轻人而言新奇特别的京都。谈笑风生，闲情漫步，只有小住片刻才能感受到京都深处的风情。在不同的地方遇到不同的人，佳奈在舅公手绘地图的指引下，渐渐放下心中防备，融入京都。', '木村文乃', '吉见拓真', 8.1, 25212, 'tt11823208', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2578681228.jpg', 0.4, 1.9, 19.9, 47, 30.8, '0.328604,0.143025,-0.691402,0.825953,-0.247793,-0.116201,0.563902,0.356866,-0.792523,-0.165426,0.467891,0.806888,-0.030018,0.326485,0.302797,0.057943,-0.317526,-0.411030,-0.073654,-0.336611,-0.197849,-0.664535,-0.459561,-0.275149,-0.093838,-0.372073,0.367580,0.293229,-0.023592,0.564144,-0.147704,0.018137,-0.413431,0.360039,-0.504750,-0.113972,-0.146462,0.229195,-0.354213,0.192912,-0.094876,-0.368860,-0.226228,0.084644,0.234744,0.152516,1.028433,0.054268,-0.355131,0.144217,0.378018,0.239253,-0.067553,-0.084584,0.446382,-0.109951,-0.194547,0.016483,-0.524286,0.025971,-0.182515,-0.259141,-0.386003,-0.150085,0.235995,0.297320,-0.731558,0.833578,0.023008,-0.429446,0.060404,-0.532144,0.375095,0.419004,0.097915,0.404513,-0.041132,0.236997,-0.312896,-0.088834,0.497974,-0.025524,0.009953,0.331434,-0.389212,-0.346069,-0.109099,-0.139526,-0.324916,-0.165766,-0.077736,0.006454,-0.206306,-0.146020,-0.567364,0.229334,0.042435,-0.322931,0.172063,-0.512309,-0.070482,-0.753242,-0.358849,-0.540948,-0.168393,0.149389,0.295679,-0.058054,0.753945,-0.665230,0.201659,0.599965,0.051890,-0.422290,0.686906,0.020513,-0.194837,-0.331894,-0.134623,0.351691,0.105850,0.509881,0.080227,0.333190,-0.339232,-0.071926,-0.645344,0.603347', '1298468', '25790555', '1414808', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34908189', '老友记重聚特辑', '喜剧', '《老友记》主演詹妮弗·安妮斯顿、柯特妮·考克斯、丽莎·库卓、马特·勒布朗、马修·佩里和大卫·施维默回到了这部标志性喜剧的原声舞台--第24号摄影棚，在伯班克的华纳兄弟制片厂为这部深受喜爱的电视剧举行了一场真实的无剧本庆祝活动。', '詹妮弗·安妮斯顿', '本·温斯顿', 9.2, 69129, 'tt11337862', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2649579601.jpg', 0.1, 0.8, 7.2, 22.4, 69.4, '0.112698,-0.268385,-0.852302,0.631668,0.604723,-0.233933,0.884176,0.665321,-0.200343,0.031772,0.524781,1.071441,-0.813166,0.158816,0.377951,0.146099,-0.754663,-0.334584,-0.409386,-0.095711,0.381365,-0.154043,-0.346357,0.095789,-0.164105,-0.408211,0.676936,-0.312831,-0.130245,0.373366,0.794294,0.060842,0.048212,-0.057887,0.435880,0.789495,0.505527,-0.109432,-0.857720,0.561642,0.375412,0.307829,-0.398626,0.147285,0.103413,0.231936,0.799116,0.113060,0.127671,0.164839,0.713363,-0.057622,-0.229687,-0.108535,0.041791,-0.047598,0.318043,0.285866,-0.052132,0.437570,-0.113061,-0.499709,-0.912519,0.327626,0.100182,0.349651,-0.335759,0.776868,-0.733373,-0.174984,0.110409,-0.349211,0.199650,0.055373,0.489570,0.207183,0.304875,0.019501,-0.018731,0.557854,0.486352,0.183375,-0.189625,0.681954,0.009402,-0.249643,-0.117371,-0.157216,-0.862678,0.284478,0.924573,-0.515271,0.134166,0.158188,-0.549465,-0.475615,-0.265640,-0.731727,0.044885,-0.510771,0.385894,-1.588023,-0.351120,-0.148185,0.667206,-0.700675,0.067151,-0.446747,0.588098,-0.652510,0.413056,0.404836,-0.047709,0.132628,0.432268,0.104162,0.304242,-0.186672,-0.033480,0.162449,0.158417,0.076866,0.137518,0.509874,0.163189,-0.345657,-0.746714,0.438680', '34961898', '24751811', '6517421', '2075345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34909282', '钱信伊：亚洲笑星闹美国', '喜剧', '喜剧演员、《每日秀》记者、《摘金奇缘》演员钱信伊推出自己的首个 Netflix 喜剧特辑《亚洲笑星闹美国》。钱信伊出生于马来西亚，在曼彻斯特、新罕布什尔、新加坡和澳大利亚长大，他大谈特谈自己迄今为止在美国的旅程。从评估消费主义的影响，到亚裔美国总统的办事效率有多高，钱在《钱信伊：亚洲笑星闹美国》中分享了他认为使美国变得强大的真正原因。《钱信伊：亚洲笑星闹美国》将于 2019 年 12 月 17 日在 Netflix 面向全球上线。', '钱信伊', 'Sebastian DiNatale', 8.1, 7261, 'tt11248800', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2594750424.jpg', 0.2, 1.4, 17.2, 52.8, 28.3, '-0.335753,-0.196840,-0.778146,0.368830,0.195859,-0.113277,0.046326,0.074960,-0.151061,0.244709,-0.156892,0.922093,-0.529646,0.274795,0.356135,-0.312254,-0.106981,-0.489557,-0.206857,-0.003855,-0.036133,-0.374371,0.009599,-0.414656,-0.190018,-0.213584,0.498635,0.077422,-0.444245,0.183499,0.476476,0.141787,-0.249970,0.412456,0.024555,-0.107849,0.284237,0.174326,-0.451220,0.622769,-0.087402,-0.211666,-0.041009,0.164959,0.362411,0.152584,0.554963,-0.066191,0.111614,-0.078772,0.698153,-0.205435,-0.376424,-0.212142,0.460981,-0.111937,-0.101400,0.073875,-0.210978,-0.196238,-0.151499,-0.212067,-0.226455,0.099796,0.182115,0.179481,-0.471219,0.578489,-0.235089,-0.043604,-0.171907,0.071961,0.222969,0.543381,0.091141,0.319947,0.443435,0.455040,-0.413303,0.484778,0.519188,0.029968,-0.379217,0.091306,-0.047764,-0.587819,-0.014034,-0.511741,-0.218841,-0.231570,0.145361,-0.794558,0.018014,0.310894,-0.201278,0.116402,-0.054753,-0.304097,0.186760,-0.194180,0.104296,-0.560836,0.079982,-0.667347,-0.034086,-0.214910,0.292195,-0.217593,0.936199,-0.614581,0.048509,0.837193,0.651915,-0.296851,0.558382,-0.068995,0.129255,-0.362227,-0.118356,0.462180,0.058922,0.106059,0.206107,0.181777,-0.214419,-0.304461,-0.153940,0.319034', '27602116', '26711487', '3072064', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34909343', '元首偷走了粉兔子', '剧情', '九岁的安娜和家人居住在柏林，1933年到来，一切都开始发生了变化，在她四周，一个陌生人的画像开始挂满在大街小巷，懵懂的安娜不知道发生了什么。不久之后，她和她的家人踏上了一场逃亡之路，安娜在旅途中充满了好奇和困惑，而她也无法忘记陪伴自己童年的那只粉色玩具兔，可惜兔子早已被落在了柏林的家中，逐渐被黑暗所包围。', '丽娃·克里马洛夫斯基', '卡罗莉内·林克', 7.6, 7742, 'tt9106672', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2576212449.jpg', 0.1, 2.7, 28.8, 53.9, 14.6, '0.638020,0.065238,-1.147160,0.366209,-0.232473,-0.128467,1.120812,-0.079881,-0.566036,-0.200658,0.375904,1.016336,-0.334025,0.450363,0.219267,0.132646,-0.380777,-0.969860,0.139024,-0.342639,-0.179703,-0.426447,-0.080862,0.084876,-0.074659,-0.503619,0.513680,0.251563,0.292239,0.711960,0.157584,0.072042,-0.329331,0.839388,-0.276238,0.449105,0.177427,-0.104703,0.083692,-0.102833,0.065120,-0.557500,-0.234525,0.536575,-0.113789,0.315009,1.168094,-0.407018,-0.284760,0.031264,0.174343,-0.425283,0.161519,0.523038,0.338747,0.138750,0.040835,0.069635,-0.182127,0.107662,-0.063199,0.139332,-0.344288,0.075484,0.048941,0.592058,-0.714125,0.777384,0.040981,-0.183293,0.216818,-0.622700,0.351077,0.549584,-0.089208,0.485466,-0.318268,-0.094780,-0.903974,0.193977,1.010726,-0.077559,-0.298883,0.780301,-0.091194,-0.137224,-0.262609,0.113956,-0.811617,0.116798,0.592461,0.226173,-0.648225,0.548150,-0.774890,0.206329,-0.090873,-0.648505,-0.190864,-0.657848,-0.380196,-0.212886,-0.293214,-0.844062,-0.421342,0.030251,0.028163,-0.249718,0.508655,-1.076285,0.470101,0.345125,0.174828,-0.293000,0.654663,-0.163457,0.118832,0.157929,0.233050,0.272553,-0.113071,0.663402,0.244089,0.532118,0.013739,0.246060,-0.825056,0.688447', '4275444', '21619567', '3111650', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34912837', '女鬼桥', '恐怖', '电影故事原型来自真实传闻已久、发生在台中东海大学“女鬼桥”的校园灵异事件：相传有一位女学生被负心男抛弃，午夜时从桥上跳河自尽，自此那座桥就发生多次灵异现象，故被学生命名为“女鬼桥”。2018年时有一位学生凌晨独自到女鬼桥直播，期间有网友突然发现直播背景的树上疑似有一名身穿白衣女子飘在空中。当时这件“撞鬼直播”事件引爆网路讨论，《女鬼桥》的故事就由此延伸，更配合一连串以观众为第一视角、不间断的惊悚恐怖场面，务求令观众一路惊到尾，直奔最后惊人结局！', '乔湲媛', '奚岳隆', 6.3, 12656, 'tt11242242', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2588341885.jpg', 2.9, 15.5, 51.1, 24, 6.5, '-0.004282,-0.162097,-0.518652,0.178529,0.363831,0.435944,0.662551,-0.284625,-0.430140,-0.165442,0.575821,0.445796,-0.951743,0.145433,0.721905,-0.060948,-0.071810,-0.698591,0.129689,-0.308896,-0.510229,0.102272,-0.066431,-0.199818,-0.118368,-0.403891,0.603828,0.328945,-0.350868,0.224031,0.257104,0.227864,-0.500820,0.191419,-0.026473,-0.094719,0.171973,0.223702,0.280588,0.039867,-0.484508,-0.496385,-0.138191,-0.219495,-0.285632,0.060008,0.818196,-0.324455,-0.581442,0.229496,0.794801,0.022183,-0.083385,-0.058214,0.916639,0.109149,0.178982,0.172028,0.119145,-0.485115,-0.131407,-0.092312,-0.138439,0.199028,-0.034116,0.210416,0.132674,0.285704,0.014228,0.054482,0.304022,-0.073260,0.050433,-0.215476,0.488329,0.267204,-0.004440,-0.240208,0.050288,0.527518,0.703714,0.456100,-0.464501,0.365449,0.018263,-0.312463,-0.280023,0.033612,-0.153695,0.425324,0.406418,-0.037425,-0.432145,0.358951,-0.298518,0.028501,-0.046891,-0.004045,-0.117826,0.058626,-0.748953,-0.774332,-0.053283,0.133381,0.359968,0.120000,-0.384655,-0.147420,0.798025,-0.497108,0.365681,0.572102,0.078632,-0.083252,0.884154,-0.320807,0.076541,0.030265,0.002181,-0.123653,-0.049169,0.357840,-0.177518,0.224660,-0.402755,-0.356468,-0.380568,0.195084', '1322847', '10466639', '1292894', '26877406');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34913597', '老大不小', '剧情', '通过剧中小人物身上发生的诸多时间及现代社会对于金钱、欲望等诱惑而依旧保持初心并积极努力通过各种勤苦的工作来应对生活中的种种困难，传播小人物也有大能量，对生活、社会及自己都有着美好的向往和肯定。讲述了老北京人在现如今快速发展的时代中体现亲情、友情及爱情最真挚的一面。', '高炜', '安佳星', 6.5, 4450, 'tt12700888', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2613246507.jpg', 3.4, 15, 44.4, 29, 8.2, '0.158511,0.150317,-0.745061,0.775663,-0.205433,0.315999,0.539726,-0.204497,-0.582817,-0.308261,-0.054332,0.365031,0.081722,0.199596,0.148714,-0.698983,-0.507828,-0.770154,0.161918,0.017224,-0.246358,-0.366922,-0.400374,-0.168465,-0.635835,-0.285712,0.689958,0.351950,-0.229801,0.399131,-0.147773,0.128579,-0.097950,0.588573,0.018426,-0.472670,-0.090330,0.398327,-0.613031,-0.195446,0.327919,-0.145806,-0.052457,0.210501,0.051766,0.192685,0.487746,-0.507158,-0.418951,0.010168,0.436829,0.044091,-0.037777,0.090507,-0.026252,0.146388,0.043894,0.526414,-0.159352,-0.030413,-0.136042,-0.159461,-1.212008,-0.335818,0.239737,0.057366,-0.227357,0.355998,0.419764,-0.340165,0.122979,-0.245764,-0.176804,0.314116,0.757813,0.508961,-0.592810,0.098743,-0.071656,0.345662,0.565628,-0.036150,-0.766798,0.591210,-0.906664,-0.120875,-0.098317,-0.425955,-0.473140,-0.365995,-0.361785,0.369187,-0.156513,0.716536,-0.556753,0.700299,0.070231,-0.357781,0.369034,-0.671046,-0.125523,-0.859728,-0.526620,-0.891924,-0.204454,0.093107,0.514024,-0.593875,1.260610,-0.664074,-0.027358,0.488520,0.402576,-0.886558,0.737412,0.088634,0.152725,-0.397707,-0.379823,0.687539,-0.349306,0.172983,-0.492533,0.103955,-0.110052,0.201109,-0.078072,0.835503', '27602116', '24284209', '1303542', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34913671', '哆啦A梦：伴我同行2', '剧情', '某天，大雄（大原惠美 配音）偶然发现了童年时奶奶为自己缝制的玩偶熊，于是央求哆啦A梦（水田山葵 配音）去往过去看望已不再人世的奶奶（宫本信子 配音），大雄与奶奶重逢之后，奶奶希望能看到大雄长大结婚时的样子，答应奶奶的大雄与哆啦A梦则再一次的返回了未来，婚礼如期举行的那天，所有人都到了场，但最重要的新郎成年大雄（妻夫木聪 配音）居然不在现场，情急之下，哆啦A梦让大雄假扮成年时的自己与静香结婚（嘉数由美 配音），然而真正的成年大雄究竟去了哪里呢？', '水田山葵', '八木龙一', 7.1, 84506, 'tt13428402', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2641407963.jpg', 1.1, 6.7, 41.8, 36.8, 13.7, '-0.173848,-0.085464,-0.676231,0.143795,0.272187,-0.615109,0.225218,0.078792,-0.087494,-0.528081,-0.072931,0.803619,-0.207302,0.476094,0.060658,0.223716,-0.173825,-0.574168,-0.140350,0.172583,-0.575747,-0.178546,0.404352,0.094374,0.165137,0.066496,0.214972,-0.127706,0.139551,0.403864,0.348918,-0.102728,-0.005861,0.136251,-0.221330,0.223918,-0.004681,0.455702,-0.317040,0.166217,0.017164,0.241620,-0.360021,0.103917,0.323186,0.124674,0.563579,-0.614858,-0.318012,-0.167280,0.425663,-0.065686,-0.135168,0.200681,0.035567,-0.217684,0.355252,0.103247,-0.080178,-0.070983,-0.162067,-0.126383,-0.414413,0.379708,-0.122662,-0.221129,-0.482102,0.162707,0.030654,0.010452,0.399162,-0.395895,0.397675,0.607877,0.073388,0.307849,-0.328530,0.165123,-0.330679,0.091410,0.842413,0.208108,0.172713,0.539672,0.236776,-0.382971,0.009567,-0.273899,-0.323974,0.392330,-0.032029,0.063371,-0.529440,0.166649,-0.307749,-0.334332,-0.265488,0.048007,0.167243,-0.249074,-0.357079,-0.128336,0.123452,-0.188352,-0.056907,0.208605,0.125004,-0.353665,0.750809,-0.807660,0.254969,0.235084,0.340173,-0.147175,0.581189,0.031047,0.048021,-0.231961,0.098109,-0.384610,-0.077400,0.113549,0.464883,0.200795,-0.072993,-0.161588,-0.646720,0.179669', '1292219', '1292720', '1458896', '35048413');
