INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34925383', '正义骑士', '剧情', '故事讲述马库斯的妻子在一场悲剧的火车事故中身亡，马库斯要赶回家陪女儿玛蒂尔德。这场事故似乎是一场意外，但一位数学极客，也是火车中的一位乘客，与他的两个同事现身，说出他们确信这场事故背后另有隐情。', '麦斯·米科尔森', '安诺斯·托马斯·延森', 7.3, 7244, 'tt11655202', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2626880626.jpg', 0.8, 5, 37.7, 41.9, 14.6, '0.141260,-0.013784,-0.598555,0.390876,0.110814,0.039781,1.052562,-0.505827,-0.598832,-0.594779,0.483032,1.089231,-0.378675,0.348607,0.601955,-0.109748,-0.430363,-0.522982,0.342249,0.084550,-0.309499,-0.578822,0.057828,-0.563668,-0.165282,-0.087171,0.512349,0.355443,-0.338810,0.917792,0.361400,0.398415,-0.519910,0.278928,0.235576,0.044330,0.128094,0.482894,-0.211842,0.091270,0.210518,-0.406892,-0.419661,0.474290,0.205734,0.506985,0.461766,-0.063262,-0.106549,0.054946,0.044281,-0.766939,-0.052122,0.282560,0.889715,-0.004586,0.520500,0.464477,0.233571,0.004525,-0.214582,0.140143,-0.473106,-0.300966,0.022936,0.167440,-0.458954,0.377574,-0.030180,-0.132740,-0.009018,0.127607,0.372876,0.332499,0.491030,0.528138,-0.186511,-0.158497,-0.433838,-0.123939,1.177404,-0.265034,-0.046567,0.587479,0.244939,-0.450053,-0.247094,0.085741,-0.820441,0.684604,0.258855,-0.390195,0.003198,0.406606,-0.326054,-0.202131,-0.640347,0.001593,-0.428356,-0.096382,-0.046044,-0.524703,0.249262,-0.249732,-0.136731,0.136639,0.042417,-0.285179,0.486548,-0.326710,0.144823,0.449417,-0.281590,-0.414154,0.366908,0.573432,0.734567,-0.442159,0.094032,-0.329624,-0.287274,-0.468665,-0.266785,0.217158,-0.081035,-0.064103,-0.379191,0.141789', '25721544', '1307956', '1296534', '30353869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34925598', '腿', '剧情', '钱钰盈（桂纶镁饰）的丈夫郑子汉（杨祐宁饰）在腿部截肢手术后不幸离世，钱钰盈想拿回丈夫被截肢的腿，却被医院百般刁难、互踢皮球，于是一场异想天开的“夺腿计划”就此展开！她缠着外科医生要求帮忙，跑到一般人从未见过的医院地下室，在一包包检体中寻找丈夫的腿，甚至找上内勤人员监控医院合作车辆的GPS，闹到医院院长都来关切…而这段充满黑色幽默的寻腿旅程中，也勾起钱钰盈与郑子汉从相识、相爱到相互亏欠的过往回忆。郑子汉对美丽的国标舞者钱钰盈一见钟情，在照相馆朋友约翰（张少怀饰）的牵线之下成为她的舞伴，两人坠入爱河、步入婚姻，是人人称羡的神仙眷侣。但郑子汉一心想要赚大钱让妻子过美好日子，却让两人的感情逼入绝境，最终形同陌路，没想到两颗心再次靠近时却是在医院里将面临生离死别的时候…', '桂纶镁', '张耀升', 6.4, 7084, 'tt12921022', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2621401958.jpg', 2.8, 13.8, 50.4, 26, 7, '0.287475,-0.106972,-0.617600,0.365033,0.077526,-0.402917,1.023174,0.031531,-0.541910,0.172423,0.284636,0.587677,-0.322138,0.324693,0.346440,0.046178,-0.097376,-0.929659,-0.048345,-0.040086,-0.513404,-0.325065,-0.048543,0.025714,-0.061176,-0.106067,0.553966,0.176849,-0.138025,0.520017,0.061890,0.118378,-0.243057,0.518036,-0.265059,-0.009955,-0.024825,0.468518,-0.529659,0.160437,0.343316,-0.228341,-0.164696,0.050333,-0.174859,0.241593,0.638944,-0.000990,-0.082912,0.005414,0.162723,-0.290198,-0.108631,0.358755,0.303029,0.198542,0.143795,0.173159,-0.324106,0.013529,0.227377,-0.015184,-0.731033,0.079686,0.013735,0.053905,-0.709561,0.359219,-0.060693,0.226096,0.152898,-0.258090,0.297606,0.187095,0.338133,0.500017,-0.334856,0.042310,-0.435982,0.141451,0.750175,-0.054419,-0.101966,0.445455,-0.245912,-0.283552,0.008042,-0.172010,-0.530144,-0.158223,0.210681,0.014526,-0.354921,0.187375,-0.368103,-0.078110,-0.232985,-0.063006,0.024336,-0.520231,-0.080537,-0.412524,-0.102456,-0.274924,-0.313588,0.281912,0.222943,-0.362553,0.370648,-0.602007,0.263065,0.497506,0.322409,-0.497710,0.861173,0.271347,0.195602,-0.259368,0.018621,0.391476,0.053479,0.366372,0.168301,0.156174,-0.274788,0.277206,-0.600820,0.284602', '1291835', '1292211', '1296370', '25917973');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34927643', '六号车厢', '剧情', '一个芬兰女人为了逃避在莫斯科的一段秘密婚外情，登上了前往北极港口摩尔曼斯克的火车。她被迫与一名俄罗斯矿工在狭小的卧铺车厢里度过漫长的旅程。这次意外的邂逅使他们开始面对，自己所渴望的，人与人之间接触的真相。', '塞迪·哈拉', '尤霍·库奥斯曼恩', 7.7, 11253, 'tt10262648', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2868385032.jpg', 0.6, 2.6, 27.6, 49.2, 20.1, '0.397675,0.085740,-0.994558,0.619431,-0.010296,-0.040257,1.087186,-0.264215,-0.793696,-0.106204,0.359258,0.930308,-0.160545,-0.012931,0.480369,0.229237,-0.508522,-0.683320,0.007895,-0.461436,-0.503450,-0.403243,-0.451643,-0.531201,0.035394,-0.150654,0.990379,0.620083,-0.253890,0.418695,0.139847,0.109439,-0.352059,0.797025,-0.153650,-0.309963,0.190454,0.165668,-0.380561,-0.015720,-0.257954,-0.413774,-0.158655,0.197444,-0.057081,0.238786,0.861199,-0.377847,-0.062424,-0.120482,-0.143337,-0.324556,-0.183462,-0.035297,0.224764,0.012418,0.330583,0.499365,-0.214281,0.008023,0.035558,-0.082180,-0.537304,0.110557,-0.164631,0.105945,-0.336431,0.683340,-0.117854,0.127281,0.317999,-0.419433,0.210789,0.714503,0.272135,0.443746,-0.444586,-0.014264,-0.397417,0.043726,1.269433,-0.075883,-0.252941,0.330965,-0.183527,-0.357695,-0.108559,-0.204156,-0.701492,-0.116663,0.352593,-0.132785,-0.420919,0.420747,-0.801915,0.287593,-0.254145,-0.112561,-0.004680,-0.340109,-0.157160,-0.739794,0.118643,-0.231058,-0.089504,0.147916,0.160763,-0.220988,0.612283,-0.603964,0.318761,0.887894,0.453254,-0.394210,0.940010,0.182167,0.505032,-0.515437,0.022355,0.561800,-0.155098,0.558480,-0.224321,0.412559,-0.517121,0.460578,-0.692244,0.413340', '25721544', '1291835', '3606973', '1437109');
