INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34927935', '长安伏妖', '奇幻', '长安六骑司前首领延东的墓遭遇盗墓贼，镇压妖王的玄牝珠被盗，导致长安城妖孽四起，民不聊生。大内总管鱼公公（罗家英 饰）命六骑司的马三（吴孟达 饰）、王诸葛（贾冰 饰）、雷燕（徐冬冬 饰）等人镇压群妖和追寻玄牝珠，并策划着一场惊天的阴谋。盗墓贼逃到一家客栈躲避，结果玄牝珠被厨师李长安（保剑锋 饰）误食。为了心爱的恋人公孙玉（克拉拉 饰）以及解救长安百姓，李长安通过重重考验进入六骑司，最后置之死地而后生，发动玄牝珠的神奇力量伏妖除魔……', '保剑锋', '王凯', 4.2, 4768, 'tt15295036', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2631436526.jpg', 27.7, 46.2, 19.7, 3.5, 2.9, '-0.373079,0.258099,-0.284456,0.464862,0.276315,0.050017,0.366957,0.105876,-0.500621,-0.409338,0.135128,0.038984,-0.292722,-0.121796,0.316830,-0.100167,0.191861,-0.465263,-0.511312,0.094519,-0.184482,0.212721,-0.121353,-0.151708,-0.289991,-0.074913,0.203315,0.413447,-0.135551,0.253307,0.365298,0.541511,-0.675967,-0.043651,0.058863,0.306432,-0.165633,0.292118,-0.248419,0.034002,-0.169086,-0.365204,-0.148649,0.225143,0.221538,0.006428,0.355478,-0.653197,0.185277,-0.425069,-0.163156,-0.134859,-0.286912,0.091111,0.311505,0.052752,0.107469,0.103028,-0.160480,-0.250367,0.188618,0.080734,-0.425702,0.067039,0.280682,0.007632,-0.236011,-0.085427,-0.007380,0.221754,-0.190365,-0.370873,0.391464,0.253521,0.027898,-0.240289,-0.115889,-0.306153,-0.464061,0.341429,0.464542,-0.328354,0.161680,-0.606593,0.403595,-0.370125,-0.034666,-0.038443,-0.035646,0.145399,0.603252,-0.198412,0.337346,-0.052978,-0.382741,-0.558719,-0.399487,0.141698,-0.032865,0.262632,-0.001857,-0.562788,0.369869,-0.315486,-0.077660,-0.093071,0.222339,-0.101015,0.353628,-0.366959,0.206584,0.042120,0.169822,-0.490921,0.083120,-0.469595,0.314011,-0.465796,-0.276881,-0.034519,0.170024,0.397004,0.460483,0.245995,-0.329647,-0.168409,-0.385722,0.218307', '35132915', '26661191', '34970316', '1306490');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34929859', '漫长的告白', '剧情', '少年时代的立冬（张鲁一 饰）曾爱慕过一位叫阿川（倪妮 饰）的女子，但在某一天阿川的突然失踪成为了他十几年解不开的心结。为一解思念，立冬与哥哥立春（辛柏青 饰）去到与阿川同名的柳川，只为再见她一面。随着他们的再次相遇，很多过去的故事的真相浮出水面，立冬也知晓了阿川当年离开的真正原因，而他对阿川深藏的爱，却在这场远赴“她”乡的深情告白中愈演愈烈……', '倪妮', '张律', 6.5, 25276, 'tt11569670', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2877091221.jpg', 4.2, 15.5, 42, 30.2, 8.1, '0.098959,0.073976,-0.841360,0.361343,-0.069679,-0.394661,0.967200,-0.228111,-0.547990,-0.119762,0.178015,0.834048,-0.224194,0.372075,0.224525,0.184605,-0.018846,-0.734031,0.341950,-0.473217,-0.166394,-0.306368,-0.427142,0.171506,-0.058949,-0.052434,0.741001,0.217262,-0.110937,0.621645,0.335792,0.230618,-0.189452,0.683323,-0.178583,0.223396,-0.248832,0.324375,-0.585761,-0.031429,0.204637,-0.292234,-0.495017,-0.003439,-0.404391,0.232119,0.542977,-0.295585,-0.384281,0.158649,0.360781,-0.331716,0.030773,0.078476,0.265231,0.071305,0.182525,0.483021,-0.337930,0.047293,-0.214823,0.124461,-0.281496,0.276539,-0.002439,0.307289,-0.676889,0.464630,-0.180846,-0.316731,0.215147,-0.537941,0.089690,0.342603,0.060721,0.426001,-0.642025,0.067280,-0.370872,0.291026,0.850137,0.136408,0.156838,0.553788,0.285830,-0.228229,-0.140880,0.030467,-0.493506,0.114599,0.091519,0.126335,-0.304558,0.296409,-0.545553,-0.031245,-0.238192,0.088816,0.138670,-0.508541,-0.262539,-0.169997,-0.272364,-0.508358,-0.367728,0.104464,0.266559,-0.392186,0.810251,-0.887072,0.417068,0.436728,0.288816,-0.576658,0.605193,0.566788,0.085051,-0.238642,-0.024032,0.375931,-0.240052,0.172744,0.076857,0.325936,0.162849,0.008187,-0.675779,0.357439', '4275444', '25721544', '3111650', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34929897', '无间行者之生死潜行', '剧情', '黑帮「福和」的丁卓飞（谢天华 饰）与反黑队督察段一凡（周柏豪 饰）是双方安插对方阵营的卧底。 丁卓飞在「福和」做了十年卧底，为了掩饰真实身份，他比别人更加心狠手辣，亦因此渐渐接近核心。但亲手拷问同袍，看著他们惨死，令丁卓飞开始厌倦这没有尽头的卧底工作…… 另一边，段一凡在反黑组步步高升，更有望成为最年轻的总督察。事业爱情皆美满的段一凡，开始渴望做一个真真正正的警察。他处心积虑想摆脱宋先生（陈启泰 饰）和他背后的「东利贸易」…一次「福和」及「东利」的毒品交易，原来是「福和」话事人找出双方叛徒的骗局。一黑一白两个警察，各自为自己的正义之途，走上你死我亡的对峙局面……', '谢天华', '黄家辉', 4.4, 3634, 'tt10300286', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2624920379.jpg', 15.2, 52.4, 28.8, 2.4, 1.2, '0.183251,-0.306871,-0.224990,0.374225,-0.214342,-0.240018,0.538919,-0.023199,-0.445419,-0.299864,0.194935,0.832557,-0.123797,-0.041136,0.134853,-0.009895,0.105684,-0.757115,-0.064417,-0.204371,-0.185044,-0.628614,-0.464668,-0.165135,-0.195167,0.015990,0.700187,0.174312,-0.117158,0.306726,0.538550,0.214043,-0.046039,0.242300,0.099406,-0.160273,0.059778,0.063552,-0.576129,-0.182088,-0.052772,-0.472621,-0.403043,0.276914,-0.205720,0.134364,0.435684,-0.353597,-0.043017,-0.165047,0.178174,-0.644981,-0.213787,0.057249,0.199991,-0.180313,0.069881,0.626231,-0.141768,-0.169155,-0.081720,0.053650,-0.885431,-0.052189,0.093014,-0.020621,-0.690790,0.506900,-0.033207,-0.063001,0.257319,-0.122788,0.256574,0.703088,0.100358,0.216641,-0.287998,-0.200919,-0.609458,0.240975,0.630946,0.211089,-0.097604,0.107299,0.152205,-0.250218,-0.080804,-0.226535,-0.216107,-0.125149,0.250108,-0.196861,0.016286,0.210714,-0.412729,0.238810,-0.200672,0.074142,-0.061166,-0.563278,0.022070,-0.369928,-0.354422,-0.568741,-0.102287,0.205157,0.005248,-0.440768,0.393650,-0.801906,-0.086301,0.418291,0.078215,-0.943811,0.499492,0.468635,0.296269,-0.689148,-0.279558,-0.060945,0.056760,0.210234,0.308825,0.110448,-0.128679,0.089209,-0.084941,0.150892', '26678784', '30345227', '1307694', '1949320');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34938649', '富二代', '喜剧', '格里戈（米洛斯·比柯维奇 Milos Bikovic 饰）是衔着金汤匙出生的千金大少爷，从小就过着娇生惯养、养尊处优的日子，在蜜糖罐里泡大的格里戈自然培养出了蛮横娇纵不学无术的摆烂个性，并且因为他的横行霸道，惹出了种种的麻烦要他老爸给他擦屁股。终于，在又一次闯祸之后，格里戈的老爸忍无可忍，他决定好好的教育一下自己的儿子。格里戈的老爸和他的好友——一位精神病学家一起盘下了一座废弃多年的村庄，将它重新修整成为了19世纪的模样，之后，两人策划了一场车祸，当格里戈从昏迷中醒来后，震惊的发现自己“穿越”回了19世纪，成为了当时的一位有钱人家的奴隶。©豆瓣', 'Sergey Abroskin', '克里姆·斯彭科', 7.4, 7401, 'tt11418452', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2579801640.jpg', 1.1, 4.1, 34.2, 44.3, 16.2, '0.305154,0.215885,-0.610717,0.508362,-0.443987,-0.746130,0.629834,0.175803,-0.670234,-0.214700,0.028817,0.755766,-0.298495,0.547694,0.378663,0.227638,-0.183173,-0.708037,-0.158736,-0.332941,-0.234489,-0.401419,-0.279928,-0.091133,0.099886,-0.273953,0.028613,-0.162635,0.029096,0.119200,0.225320,0.123641,0.317044,0.166051,-0.327463,0.153070,0.028731,0.116930,0.008101,0.107864,0.245058,-0.321990,-0.014634,0.149489,0.282438,0.214033,0.507385,-0.164836,0.011076,-0.205830,0.325960,-0.047119,-0.136056,0.094625,0.371464,-0.149507,0.073008,-0.021576,-0.379452,0.002084,0.129065,-0.260201,-0.504084,-0.087686,-0.244530,-0.101393,-1.009764,0.578897,0.016820,-0.042666,-0.261750,-0.411964,0.020536,0.442457,0.215247,0.536840,-0.281582,0.098166,-0.485927,0.271862,0.609310,-0.119623,-0.181543,0.190851,-0.013213,-0.310707,0.221162,-0.503809,-0.523011,-0.179028,0.599681,-0.202136,-0.356107,0.397601,-0.547537,-0.160447,-0.461431,-0.131183,0.083720,-0.012503,-0.331680,-0.317172,-0.099420,-0.387094,-0.067700,0.126622,-0.119885,-0.126621,0.669130,-0.651330,0.441425,0.444684,0.202566,-0.366826,0.483882,-0.114389,0.149635,-0.104485,0.199719,-0.006125,0.040717,0.340804,0.443970,0.581056,0.011078,-0.188990,-0.216412,0.606413', '1299965', '1895119', '1309069', '1876765');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34943015', '宝可梦：皮卡丘和可可的冒险', '剧情', '《宝可梦：皮卡丘和可可的冒险》是陪伴中国观众多年的《宝可梦》系列第23部剧场版，讲述森林遭遇危机时，小智、皮卡丘与可可一同挺身而出，为保护森林中的宝可梦而战。除了一贯的可爱的宝可梦形象外，本片还着重刻画了萨戮德与可可之间超越血缘的父子情谊。', '松本梨香', '矢岛哲生', 6.6, 13413, 'tt11819890', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2619351418.jpg', 1.7, 10.2, 51.7, 27.4, 8.9, '0.425807,-0.088547,-0.431040,0.806349,0.543957,-0.303502,0.142404,-0.051152,-0.406384,-0.038147,0.280462,0.843777,-0.237028,0.370709,0.178037,0.249108,-0.268004,-0.608966,-0.485308,0.140740,-0.054495,-0.225752,-0.490422,0.254360,-0.203901,-0.869365,0.657717,-0.158571,-0.170956,0.865412,0.252020,0.273922,-0.713132,0.131338,0.141616,0.065681,0.288440,0.180432,-0.560066,-0.095165,-0.286205,0.183069,0.016241,0.098651,0.191943,0.160224,1.013291,-0.482981,-0.089078,-0.185668,0.355671,-0.169063,0.002864,-0.009471,0.271655,-0.118691,0.493295,0.596443,0.220045,0.417601,-0.262661,-0.234076,-0.891708,-0.033133,0.230303,0.048672,-0.468660,0.399097,0.088135,-0.152394,0.741790,-0.133176,0.068628,0.256734,0.329203,0.474785,-0.507114,0.281412,-0.056218,-0.139654,0.562952,-0.343152,-0.199708,0.320412,-0.068752,-0.283105,-0.099864,-0.303141,-0.555606,0.104309,-0.154019,0.191581,0.009959,0.467708,-1.233183,0.252891,-0.161582,-0.173559,0.370716,-0.456424,-0.248823,-0.761579,-0.239391,-0.879406,-0.252840,0.186878,-0.033634,-0.247205,0.971472,-0.550043,0.046621,0.271904,0.231504,-0.233791,0.923651,0.128123,0.024260,-0.171641,0.065270,-0.029340,-0.172397,-0.163710,0.034861,0.089127,0.094808,-0.110436,-0.512594,0.274763', '4181031', '26290398', '3811356', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34947678', '卡拉什尼科夫', '传记', '第二次世界大战如火如荼，德国进攻苏联的一场战役中，年轻的普通士兵米哈伊尔·卡拉什尼科夫中弹受伤，住进了野战医院的他，无法在回到前线战场，然而，这位爱国者并没有善罢甘休，虽然他不能手握武器重返战场，却让战场上的战士们都用起了一把以他名字命名的突击步枪——AK47', '奥尔佳·勒曼', '康斯坦丁·布罗斯洛夫', 7.3, 11480, 'tt11547520', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2595106068.jpg', 0.6, 3.9, 40.7, 39.4, 15.3, '0.093655,0.160315,-0.938939,0.646632,-0.303800,-0.109241,0.912763,-0.551993,-0.217706,-0.046102,0.702161,0.860313,0.548258,-0.065717,0.005076,-0.210990,-0.094282,-0.925704,-0.132230,0.092576,-0.520285,-0.345541,-0.437300,-0.257094,-0.161029,-0.249489,1.037986,-0.060546,-0.475718,0.409624,0.253777,0.156278,0.376629,0.748475,-0.400749,-0.374886,-0.172708,-0.276644,-0.293589,0.179780,-0.191237,-0.333030,-0.384975,0.555490,0.140509,0.298324,0.852842,-0.744533,0.304849,-0.281528,0.009571,-0.163376,0.053349,0.138064,0.481782,0.206842,-0.242591,-0.309162,0.168134,0.414427,-0.216830,0.072776,-0.564376,0.077634,-0.243693,0.167162,-0.762518,0.784915,-0.671730,0.316104,-0.187272,-0.149605,0.353163,0.541613,0.089509,0.220090,-0.530265,0.035421,-0.618297,0.357014,0.890280,-0.008349,-0.517342,0.047431,-0.191088,-0.484160,-0.060315,-0.696051,-0.445166,-0.076084,0.476908,-0.290802,0.025639,0.303128,-0.494406,0.261770,-0.333584,-0.680672,-0.100267,0.116946,-0.041941,-0.733410,0.184032,-0.424581,-0.458574,0.433502,-0.038175,0.210618,0.897133,-0.827814,-0.199132,0.262867,0.326886,-0.200951,0.386358,0.432423,0.267204,0.044132,-0.197588,0.576513,-0.025110,0.715294,0.492330,0.528908,-0.146759,-0.332788,-0.305656,0.576131', '1478066', '21619567', '1826173', '1303624');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34947776', '守岛人', '剧情', '电影《守岛人》讲述了王继才（刘烨 饰）与其妻子王仕花（宫哲 饰）32年守护祖国边陲小岛开山岛的故事。王继才生前是江苏省灌云县开山岛民兵哨所所长，与妻子以岛为家，与海相伴，把美好的青春年华奉献给了祖国海防事业。影片选取王继才夫妇守岛生涯的经典片段和闪光瞬间，从不同侧面展现了王继才夫妇丰富的内心世界和“守岛就是守国”的家国情怀。该片不仅还原了王继才夫妇32年与恶劣自然环境顽强抗争的经历，更将主人公爱国奉献的价值追求贯穿影片始终，对于各行各业坚守平凡、创造非凡的人们，都深具心灵观照和精神滋养。', '刘烨', '陈力', 7.4, 27498, 'tt14799356', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2660246504.jpg', 2.8, 8.7, 26.1, 43.1, 19.3, '-0.306101,-0.317248,-0.448967,0.614391,0.249110,-0.178435,0.452220,0.018355,-0.494400,0.081266,0.047411,0.577318,0.302229,0.117899,0.360621,-0.129836,-0.419360,-0.815667,-0.259999,0.220239,-0.006816,-0.207166,-0.313377,-0.094485,-0.034463,-0.703214,0.778842,0.180609,-0.384176,0.355847,-0.120537,0.254781,-0.215996,0.040608,-0.150399,0.015328,-0.212397,0.303108,-0.714627,-0.241037,-0.301843,-0.255770,-0.157453,0.104928,-0.185269,0.237651,0.837747,-0.305370,-0.295614,-0.206467,0.333962,-0.115948,-0.087672,0.102021,-0.015109,0.266980,0.077078,0.561398,-0.160716,-0.206659,-0.006085,-0.409602,-0.710250,-0.452693,0.417918,-0.263528,-0.495116,0.589051,0.066173,-0.142884,0.231643,-0.147157,0.167278,0.077739,0.156801,0.577692,-0.149067,-0.035419,-0.006325,0.877361,0.590404,-0.183061,-0.169738,0.295656,-0.317859,-0.407590,-0.125134,-0.351690,-0.533248,-0.057714,-0.088979,0.096122,0.101158,0.370175,-0.807903,0.208312,-0.267006,-0.273371,0.407093,-0.412315,-0.151710,-0.418844,-0.479856,-0.469885,-0.147722,0.034288,0.128129,-0.110612,1.233507,-0.555924,0.084103,0.221117,0.200366,-0.374154,0.959412,-0.017054,-0.052257,-0.430826,0.278986,0.480166,-0.054686,0.267534,-0.255854,-0.020946,-0.344993,0.041066,-0.390541,0.608657', '27602116', '1908036', '26647163', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34951210', '阿依达，你往何处去？', '剧情', '1995年7月，斯雷布雷尼察。艾达是联合国的一名翻译。当塞尔维亚军队入侵波什尼亚克飞地并接管那里的权力时，她和她的家人和其他成千上万的人一样，在联合国营地寻求保护。激烈的政治谈判开始了，阿伊达不得不进行翻译，通过翻译她得知了致命而残酷的信息。但尽管信息的爆炸性极强，她还是坚持着逃脱迫在眉睫的命运的希望。', '雅丝娜·杜里契奇', '亚斯米拉·日巴尼奇', 7.9, 8081, 'tt8633462', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2621425792.jpg', 0.5, 1.4, 21.1, 55.7, 21.2, '0.321473,0.124703,-0.619906,0.731302,-0.104300,0.112631,0.305216,-0.124799,-0.673821,-0.200698,0.102180,0.650047,0.156941,-0.083337,0.197440,-0.046044,-0.523859,-0.640230,0.000711,-0.118979,-0.258065,-0.699820,-0.365783,-0.430900,-0.066287,-0.570429,0.596745,0.148371,-0.315395,0.332496,0.048266,0.217290,-0.017537,0.464271,0.080358,-0.130195,0.215937,-0.318885,-0.360318,0.269179,0.161362,-0.136060,-0.345214,0.562719,0.141125,0.575379,0.287293,-0.522254,0.146081,0.049724,0.365141,-0.501762,0.158314,0.084010,0.158048,0.067313,0.023376,0.435951,-0.221972,-0.167791,-0.037335,-0.005553,-0.888336,-0.207543,0.009313,0.281619,-0.412748,0.495887,-0.320950,0.403798,-0.013772,-0.257922,0.025611,0.752817,-0.085372,0.319922,-0.396336,-0.046024,-0.535286,0.164718,0.717163,-0.098534,-0.509274,-0.295903,-0.285697,-0.476240,-0.011115,-0.408453,-0.203049,-0.132990,0.248651,0.275368,-0.319937,0.211408,-0.527110,0.189396,-0.414787,-0.479948,0.091165,-0.446794,0.029960,-0.913150,-0.200655,-0.438136,-0.176424,0.186917,0.115107,-0.073038,0.921910,-0.724611,0.172386,0.942209,0.495883,-0.433010,0.387527,0.162514,0.181686,-0.420333,-0.031893,0.422624,0.131853,0.301469,0.240064,0.260029,0.159092,-0.179522,-0.186485,0.409901', '25932086', '27009869', '3769423', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34951277', '与爱同居之永恒的爱', '爱情', '在系列事件发生之后，Tharn和Type已经约会了四年。 他们仍然非常热恋，他们记得Type第一次将Tharn介绍给他的家人，但是Type的父亲可能不像他们希望的那样支持他。', '苏帕西·宗澈瓦', 'Tee Sintanaparadee', 8.4, 13585, 'tt13033542', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2587583674.jpg', 1.4, 3.1, 17.6, 32.1, 45.8, '0.518014,-0.491942,-0.832194,0.655088,-0.152968,-0.258909,0.666162,-0.137337,-0.604862,-0.492500,0.078158,1.111076,-0.165470,0.234527,0.225564,-0.388409,-0.208271,-0.880031,0.123008,-0.249514,-0.223143,-0.597669,-0.205351,0.051793,-0.032606,-0.381467,0.628840,-0.033925,-0.136184,0.757626,0.071212,0.051711,0.274128,0.795428,-0.509073,-0.026749,0.046411,0.602190,-0.720579,0.353566,0.168895,-0.063813,0.188771,0.626000,0.344478,0.184574,0.694779,-0.487866,-0.773543,0.440909,0.394269,-0.255486,0.112436,0.565544,0.428599,0.129504,0.634662,0.604708,-0.251928,-0.491325,-0.227906,-0.062383,-0.850249,0.393240,0.100972,0.289018,-0.862992,0.679974,0.194598,0.352108,0.318386,-0.251986,0.462694,0.990346,0.418269,0.363120,-0.539415,-0.317578,-0.811834,0.247334,1.100780,-0.391968,-0.141276,0.830749,-0.157080,-0.275043,-0.404855,-0.037488,-0.757561,0.692390,-0.012202,0.072597,-0.774352,0.331946,-0.367861,-0.267331,-0.017848,-0.381364,0.062662,-0.761973,0.161280,-0.708365,-0.332659,-0.763101,-0.632615,-0.007153,0.182672,-0.519019,0.677984,-1.328773,0.419688,0.376204,0.513142,-1.073479,0.981458,0.667272,-0.218619,-0.581081,0.247683,-0.014329,0.320351,-0.042466,0.264510,0.573383,0.385028,-0.140927,-0.446855,0.443841', '1949320', '1299062', '2052978', '4145476');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34953719', '黑匣子', '剧情', '一架从迪拜飞往巴黎的班机，在阿尔卑斯山不幸坠毁。一位年轻又才华横溢的法国航空事故调查人员马修（皮耶尼内饰演），被指派为这起空难的首席调查员。这是驾驶失误？还是技术故障？或是恐怖攻击？当这起调查结案时，马修开始怀疑证据发生问题。当他再度聆听黑匣子的内容时，竟发现一些严重干扰的细节。黑盒子的磁带是否遭到修改？而他对真相的痴迷与追求，是否又会因为违背上级命令，让他的生命遭到威胁？', '皮埃尔·尼内', '雅恩·戈斯兰', 7.6, 16808, 'tt10341034', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2632062377.jpg', 0.3, 1.8, 29.6, 53.2, 15, '0.188950,0.173071,-0.699816,0.511135,-0.027827,0.158308,0.622893,-0.035100,-0.454404,-0.405716,0.427509,0.866048,-0.160742,-0.138441,0.250202,-0.019468,-0.487740,-0.682080,0.224323,0.056876,-0.624353,-0.799898,-0.029985,-0.354637,0.362212,-0.397276,0.555446,0.398395,-0.781205,0.124592,0.077384,0.540685,-0.257947,0.561814,-0.081919,-0.440630,0.195073,0.156434,0.029555,0.183437,0.161717,-0.654912,-0.006863,0.174831,-0.169066,0.679138,0.682316,0.045029,-0.755110,-0.196305,0.498553,-0.419152,0.431354,0.035123,0.568904,0.370433,-0.279349,0.462223,-0.206737,0.069514,-0.094341,0.254151,-1.056559,-0.297486,-0.040803,0.158830,-0.225700,-0.104615,-0.625209,0.128150,0.120018,0.008224,0.369431,0.595277,0.314499,0.336636,-0.239028,0.172172,-0.156144,-0.005615,0.542841,-0.008673,-0.342451,0.286799,0.089618,-0.667216,0.000889,-0.067875,-0.199409,0.435835,0.312295,0.241879,-0.124484,0.227414,-0.333636,-0.218955,-0.552026,-0.393635,-0.210028,-0.233770,-0.108894,-0.834456,0.115725,-0.044208,-0.271977,-0.094909,0.193710,-0.101505,0.487481,-0.485641,0.275665,0.680237,0.071549,-0.789975,0.319796,0.306943,-0.163983,-0.384422,-0.085500,0.130453,0.236507,0.245297,-0.391973,-0.084818,0.398106,-0.423271,-0.152606,-0.005933', '26678784', '27073234', '1297689', '1307442');
