INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34954819', '巨鳄岛', '动作', '电影《巨鳄岛》讲述了单亲爸爸林浩在与女儿林伊归国航班中，不幸遭遇飞机失控，飞机紧急迫降巨鳄岛，险中逃生。却不想一波未平一波又起，幸存乘客遭遇巨型鳄鱼猛烈袭击。林浩不惜屡次犯险，鳄口夺人。幸存乘客能否鳄口逃生？惊心动魄的绝命逃生战即将上演！', '罗嘉良', '徐仕兴', 3, 2900, 'tt12598910', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2622035728.jpg', 65.3, 25.6, 5, 1.7, 2.5, '-0.447742,-0.067656,-0.755504,0.317078,0.821454,-0.068324,0.458481,-0.445370,-0.219053,0.188051,0.972236,0.401817,0.047382,0.070570,0.125328,-0.271619,-0.320583,-0.041385,0.205843,0.481170,-0.402148,0.300728,-0.345695,-0.183200,0.352412,-0.105006,0.643900,0.598030,-0.468483,0.334287,0.158519,0.368195,-0.671386,0.497196,-0.065338,-0.023424,-0.353997,0.091840,-0.362930,0.109819,-0.373427,-0.170489,0.041338,0.186239,0.340273,0.556207,0.934896,-0.294108,-0.028583,-0.502329,-0.111022,-0.516201,0.205678,-0.026081,0.451942,0.029155,0.073814,-0.144344,0.101640,-0.253389,-0.076526,0.287708,-0.154812,0.084540,-0.392420,-0.170424,-0.127819,-0.053619,-0.518377,0.432195,0.255619,0.131932,0.076660,0.459051,0.234771,-0.091041,-0.104590,0.097035,0.016706,0.391287,1.158700,-0.343459,-0.110566,0.102871,0.315368,-0.411586,0.416418,-0.451863,-0.245100,0.077171,0.860114,-0.032268,-0.528708,0.636618,-0.013056,0.070195,-0.831799,-0.117561,-0.457509,0.008057,-0.361081,-0.683400,0.565030,0.337862,0.341477,0.262804,-0.116633,0.080032,0.492921,-0.292896,-0.061896,0.682037,0.346695,-0.091299,0.448665,0.034628,-0.030699,-0.098095,0.289454,0.494604,-0.290698,0.389166,0.026738,-0.265423,-0.229387,0.191140,0.017409,-0.151212', '1292846', '26761688', '3011051', '35287558');
