INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34957970', '漫画威龙之大话特务', '喜剧', '特务变身网漫作家，史上最ㄎㄧㄤ斜槓人生？韩国国家情报局秘密组织「防牌鸢」，专将孤苦无依的小孩培训成顶尖特务，其中身手矫健的特务阿俊(权相佑饰)由魔鬼教头千德奎(郑俊镐饰)亲自训练，他快狠准的身手一举歼灭无数罪犯，成为恐怖份子都闻之丧胆的金牌特务…然阿俊心裡却有个小小梦想－成为超人气网路漫画家！于是，他决定在一次任务中诈死脱身，隐姓埋名努力画画15年，但他的漫画却被网民嫌到爆，甚至被讥为靠太太美娜(黄雨瑟惠饰)养的中年鲁蛇。某夜鬱鬱不得志的阿俊藉酒消愁，将他的特务人生画成漫画上传一夕爆红，无心之举掀起网民空前轰动，更引来情报局和恐怖份子的大追杀…', '权相宇', '崔元燮', 6.5, 9417, 'tt11649614', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2583254358.jpg', 2, 11.4, 53.4, 24.5, 8.7, '0.018905,-0.401173,-0.246100,0.352542,-0.040075,-0.163535,0.508001,-0.123391,-0.429878,-0.021308,0.294731,0.598860,-0.298207,0.069201,0.257291,-0.316485,0.017785,-0.924725,-0.114965,-0.128584,0.133876,0.033308,-0.343993,0.044255,-0.160980,-0.203450,0.760459,-0.110070,-0.182943,0.112531,0.180493,0.066360,-0.068765,0.163751,-0.140509,-0.080469,0.401593,-0.360190,-0.115694,0.087849,-0.157196,-0.432651,-0.049764,-0.018908,-0.364348,0.015566,0.528933,-0.241762,0.038026,-0.460288,0.530061,-0.633151,-0.358453,-0.127718,0.354263,0.208195,0.155184,-0.018197,0.063137,-0.000327,-0.025082,-0.135842,-0.716933,0.096608,0.346045,0.028258,-0.283359,0.208041,-0.273632,0.275280,0.024112,-0.109355,0.085001,0.059693,0.164706,0.099864,0.044269,0.469642,-0.490822,0.530470,0.271789,-0.001105,-0.333304,-0.075655,-0.013006,-0.406358,0.334185,-0.662869,-0.248811,-0.080815,0.192267,-0.321029,-0.156613,0.220685,-0.455747,-0.002226,-0.315321,-0.125947,-0.124337,-0.064038,-0.258156,-0.492337,-0.162051,0.028708,-0.032692,-0.015651,0.417554,-0.339453,0.927785,-0.468368,-0.178429,0.529743,-0.059764,-0.366275,0.430284,-0.044341,0.027543,0.089201,-0.101572,0.069334,0.202360,0.485334,0.109521,0.263131,-0.187523,-0.494394,-0.195204,0.138723', '27602116', '25880986', '1920765', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34958725', '逃走的女人', '剧情', '남편이 출장을 간 사이 ‘감희’는 세 명의 친구를 만난다. 두 명은 그녀가 그들의 집들을 방문한 것이고, 세 번째 친구는 극장에서 우연히 만났다. 우정의 대화가 이어지는 동안, 언제나처럼, 바다 수면 위와 아래로 여러 물결들이 독립적으로 진행되고 있다.', '金敏喜', '洪常秀', 7.2, 16470, 'tt11697690', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2615399825.jpg', 1, 4.8, 40.3, 41.8, 12.2, '0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000', '10001432', '10047547', '10174444', '10342838');
