INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34960201', '列夫·朗道：娜塔莎', '剧情', '1950年代，娜塔莎在苏联一家秘密的研究所内经营食堂，这里汇集了研究所的员工、科学家和外国访客。 娜塔莎的世界很小，她白天在食堂干活，晚上和年轻同事奥利亚一起喝酒，倾诉对浪漫的渴求和对未来的幻想。 在一次聚会之夜，娜塔莎与来访的法国科学家卢克·比格变得亲密起来。 第二天，当克格勃的弗拉基米尔·阿奇波将军对她进行讯问时，她的生活发生了戏剧性的转变。', '娜塔利娅·别列日纳娅', '叶卡特琳娜·奥特尔', 6.3, 9121, 'tt11697832', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2596413150.jpg', 6.4, 16.5, 42.9, 24.3, 9.8, '0.547456,-0.087188,-0.960896,0.353191,-0.164992,-0.194036,0.994500,0.211990,-0.444678,-0.239950,0.125720,0.886128,-0.391812,0.501447,0.569385,-0.156923,-0.624586,-0.712805,-0.014550,0.004878,-0.099288,-0.562589,-0.248963,-0.515767,-0.115420,-0.371778,0.125367,0.103151,-0.150086,0.466098,-0.062045,0.099801,-0.042018,0.598509,-0.170195,-0.427684,0.773058,0.179959,-0.567508,0.060570,0.183351,-0.008573,-0.163842,0.039765,0.309947,0.131884,0.558148,-0.050440,-0.148910,-0.190991,0.222327,-0.022970,-0.054306,-0.008773,0.655953,0.110393,0.125617,0.320269,0.115744,-0.228429,-0.223218,-0.090976,-0.451223,0.119567,0.111383,0.132854,-0.390678,0.591830,-0.051109,0.084745,0.224602,-0.325217,0.323323,0.614121,0.197892,0.534138,0.216214,0.058225,-0.404763,0.152633,0.782108,-0.089386,-0.292796,0.243616,-0.485560,-0.412084,0.029385,0.122958,-0.560434,-0.168567,0.047174,-0.389117,-0.315517,0.526603,-0.797256,0.084819,-0.089173,-0.357466,0.280390,-0.232228,-0.252081,-1.180596,-0.064943,-0.510968,-0.076789,0.218106,0.229003,0.030614,0.789361,-0.908700,0.238859,0.642114,0.554814,-0.466782,1.055025,0.043800,0.018613,-0.429723,-0.016426,0.141108,-0.262658,0.243648,-0.099566,0.575744,0.158193,0.226320,-0.463220,0.349588', '10466639', '1306860', '26687241', '11541282');
