INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34962956', '缉魂', '科幻', '著名集团董事长王世聪惨死家中，负责此案的检察官梁文超（张震 饰）与妻子刑警阿爆（张钧甯 饰）在调查中得知：死者的儿子王天佑（林晖闵 饰），年轻的新婚妻子李燕（孙安可 饰），多年合伙人万宇凡（李铭顺 饰），甚至死去的前妻唐素贞（张柏嘉 饰），每个人之间都有着错综复杂的关联 。阿爆更是发现隐藏在案件背后的惊人秘密……电影根据江波小说《移魂有术》改编。', '张震', '程伟豪', 6.8, 195246, 'tt13598976', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2629413230.jpg', 1.1, 7.8, 45.6, 38.9, 6.5, '0.122444,-0.200551,-0.491301,0.552692,0.191737,-0.008466,0.453773,0.118370,-0.668730,-0.847365,0.463351,0.323021,-0.167842,0.181118,0.105387,-0.146385,-0.216613,-0.689538,-0.082168,0.054635,-0.091543,-0.520863,-0.335387,-0.237840,0.055269,-0.035474,0.504780,-0.007258,-0.065796,0.325056,0.356333,0.454192,-0.693804,-0.061507,0.197663,0.147854,0.370341,0.157617,-0.615053,-0.043157,-0.065191,0.039514,0.030337,-0.122079,-0.044195,0.383866,0.500165,-0.169437,-0.274443,-0.068200,0.612083,0.163226,-0.035566,-0.094522,0.569256,0.281977,0.405021,0.557504,-0.309275,-0.103065,-0.058216,0.185601,-0.708358,-0.130732,0.624283,0.217457,-0.371885,0.212568,-0.205981,0.069127,0.084874,-0.248381,0.394533,0.184097,0.065537,0.344223,0.249409,0.215047,-0.389817,0.454955,0.345510,0.066364,0.089148,-0.249919,-0.059317,-0.308131,-0.306640,0.028741,-0.367677,0.327193,0.274087,-0.168356,0.296791,0.221940,-0.161317,-0.118207,-0.067521,0.391256,0.200649,0.039256,-0.128970,-0.500529,-0.200572,-0.400175,-0.328281,-0.019950,0.029285,-0.391222,0.517487,-0.549618,0.011332,0.120688,0.019316,-0.574053,0.450670,0.062490,-0.025979,-0.723832,-0.461457,0.184983,0.262990,-0.069572,-0.094530,-0.103434,-0.223212,-0.254091,-0.085305,-0.157447', '3670447', '26348798', '11776289', '35192111');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34964056', '陈情令之乱魄', '奇幻', '故事发生在清河聂氏处理其祖传刀墓事件时期。聂明玦带领聂怀桑为百姓安康，将古墓恢复原状，确保聂氏安稳。这使得聂怀桑从顽皮弟子的心态变得愈加成熟，聂明玦也从中更了解弟弟，帮助他成长为下一代宗主。', '纪李', '裘仲维', 5.4, 35768, 'tt12484916', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2609410523.jpg', 15.6, 23, 43.4, 11.5, 6.6, '-0.266100,0.123134,-0.242493,0.182701,0.140825,0.107826,-0.119509,0.401599,-0.860982,-0.281111,0.408509,0.288458,0.049651,-0.104762,0.154612,-0.353774,-0.231206,-0.118208,0.320560,0.094351,0.127218,-0.147619,-0.108020,-0.354949,-0.106864,-0.833197,0.643217,0.101880,-0.139017,0.342145,-0.240115,0.049297,-0.187897,-0.008776,-0.031762,-0.112214,-0.432300,0.158566,-0.455957,-0.120898,-0.192530,-0.303527,-0.112159,0.101457,0.048505,0.153208,0.516735,-0.158211,-0.666388,-0.214863,0.284442,-0.024601,-0.379162,0.083256,0.323145,0.422921,-0.192020,0.794457,-0.390250,-0.176907,-0.312196,-0.146523,-0.555303,0.247857,0.359702,0.337023,-0.315062,-0.052337,-0.110385,-0.134534,0.246854,-0.530051,0.306405,0.929688,0.393968,0.078428,-0.325624,0.162052,-0.277452,0.051850,0.539724,-0.651217,-0.006519,0.274026,-0.099132,-0.297672,0.243156,-0.306234,-0.095471,0.171424,0.209599,0.151080,-0.072615,0.903042,-0.042541,-0.030519,-0.323106,-0.230903,0.144354,-0.171319,0.099382,-0.307497,-0.432838,0.125199,-0.018997,-0.602644,-0.226842,-0.599488,1.198427,-0.392739,0.057702,-0.083857,0.402197,-0.714084,0.111855,-0.357848,0.687801,-0.312299,-0.342356,0.391419,0.224749,0.037350,-0.331644,0.010222,-0.267367,-0.092206,-0.084341,-0.172791', '5996800', '27602116', '24284209', '26965165');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34964410', '法医宋慈', '悬疑', '本片讲述了一夜之间二十七具尸体被悬挂当街，且都被抽去了骨头，死相诡谲。向来不信邪的宋慈以一种追求极致真相的态度与女助手雨墨深入调查。通过对死者关系网的盘查，宋慈发现这是起随机杀人案，有价值的是“27”这个数字，这与十年前的波旬教案有关，他向恩师耿知年请教，谁知当天二十七具尸体就在府衙中自燃，虽灰飞烟灭却有迹可寻，宋慈不得不怀疑这一切正和当年负责波旬教案的耿知年有关。与此同时，怀揣着隐秘身世的雨墨也已渐渐接近“真相”，那是她同样无法接受的真相……', '于震', '胡国瀚', 5.7, 6395, 'tt11798718', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2584700822.jpg', 6.3, 22.3, 54.2, 12.6, 4.7, '0.239827,-0.000565,-0.604053,0.388769,-0.044929,-0.249365,0.708549,-0.125856,-0.704026,-0.452606,0.039990,0.419636,-0.210728,0.140152,-0.011448,-0.055193,-0.163740,-0.674714,-0.477962,-0.465013,-0.341032,-0.563065,-0.060802,0.043647,-0.016476,-0.156384,0.300655,0.141529,-0.136014,0.325184,0.335635,0.452726,-0.102487,0.394261,-0.286741,0.007636,-0.234150,-0.011869,-0.019061,-0.118828,0.229540,-0.639266,-0.051107,0.079106,-0.189727,0.540457,0.750726,-0.185595,-0.386440,-0.003668,0.434002,-0.332776,-0.135770,0.289652,0.576941,0.242008,-0.092246,0.448076,-0.186228,-0.266877,-0.107735,0.049171,-0.934837,-0.180243,0.175383,0.282656,-0.399844,0.329151,-0.241413,0.240261,-0.189260,-0.323110,0.335583,0.277957,0.065547,0.302416,-0.195533,-0.189634,-0.612539,0.182849,0.530965,0.272222,-0.052489,0.294099,-0.118235,-0.452830,-0.139262,-0.217448,-0.059532,0.190140,0.277060,0.399747,-0.109895,0.233022,-0.397581,-0.158129,-0.250160,-0.113854,0.082078,-0.323795,-0.231881,-0.279017,-0.457257,-0.416219,-0.473996,-0.047934,0.202965,-0.375071,0.576399,-0.483760,0.192352,0.337950,0.190018,-0.344313,0.584737,0.067526,-0.105011,0.066566,-0.024176,0.095355,0.169553,0.447333,0.006608,0.333079,0.343943,-0.401981,-0.556220,0.249223', '1299195', '3785918', '1793491', '26678784');
