INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34966343', '极盗行动', '喜剧', '本片改编自一个真实的银行抢劫案。2006年，一群盗贼抢劫了位于阿卡苏索的里约热内卢银行，这被认为是历史上最著名、最聪明的银行抢劫案之一。他们抢劫银行所采用的方式和在那之后发生的一系列事情都让人惊讶不已。', '古勒莫·法兰塞拉', '艾列尔·维诺格拉德', 7, 20763, 'tt10948718', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2696630894.jpg', 0.4, 3.2, 49, 42.1, 5.3, '0.534304,-0.340926,-0.939548,0.737133,0.243877,0.026803,0.830789,-0.304878,-0.557465,-0.586063,0.287137,0.920383,-0.204051,-0.135584,0.470176,-0.093410,-0.079456,-0.478009,-0.375916,-0.644378,-0.450927,-0.309824,-0.179640,-0.402913,0.006893,-0.076676,0.422923,0.333265,-0.272530,0.366892,0.665740,0.621892,-0.057402,0.252505,-0.047513,-0.067518,0.483985,0.051217,-0.004409,0.077227,-0.173411,-0.581726,-0.000792,0.469891,-0.027398,0.232918,0.636312,-0.288706,-0.443888,0.041480,0.417867,-0.636382,-0.330256,-0.057648,0.348229,-0.361384,0.262026,0.371030,-0.565926,-0.035228,0.382714,0.186772,-1.473329,-0.305654,0.059791,0.004342,-0.744768,0.278263,-0.155036,0.051011,-0.122494,-0.550238,0.568142,0.542494,0.488129,0.263485,0.112223,-0.342465,-0.832505,0.387280,0.948543,-0.097981,-0.144998,0.362539,-0.301292,-0.609476,-0.153891,-0.474624,-0.145247,0.184068,0.365290,-0.345505,-0.182097,0.392664,-0.685408,-0.129159,0.189548,-0.526099,-0.030290,-0.414436,-0.158067,-0.583769,-0.268626,-0.747541,-0.312961,0.074814,-0.009830,-0.125290,0.651371,-0.671414,-0.172248,0.873916,0.155734,-0.501625,0.764806,-0.039539,0.024034,-0.229726,-0.363629,-0.192386,0.705116,0.431153,-0.131847,0.532321,0.126758,-0.545114,-0.112217,0.459474', '1793491', '30163500', '26678784', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34966922', '甘古拜·卡蒂娅瓦迪', '剧情', '甘加·哈吉万达斯(阿莉雅·布哈特 饰)出生于Kathiawar的一个富裕家庭，她的梦想是成为一名宝莱坞女演员。在16岁时，她爱上了拉姆尼克·拉尔(瓦伦·卡普尔 饰)。拉姆尼克答表示甘加可以在他的姨妈希拉的指导下进入电影行业，因此他们私奔到孟买。但是，她的生活从此发生了翻天覆地的变化。因为他以1000卢比将她卖给了卡马提普拉的一家妓院，她不得不开始卖淫。后来，她成了有势力的妓院老板娘甘古拜·卡蒂亚瓦迪，并赢得了她居住地区（卡马提普拉）的选举。唐·拉希姆·拉拉打了一个强奸她的同伙后，成为她的结拜兄弟。甘谷后来爱上了一个年轻的裁缝阿夫萨恩。她曾经倡导妇女权利和性工作者的平等权利。', '阿莉雅·布哈特', '桑杰·里拉·彭萨里', 7.7, 15734, 'tt10083340', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2868031426.jpg', 0.9, 3, 26.6, 46.7, 22.8, '0.550939,0.121484,-0.670285,0.541576,-0.500297,-0.592510,0.785517,0.321866,-0.386205,0.035954,0.249341,0.883474,0.014640,0.173106,0.354701,0.348020,-0.285554,-0.701861,0.325145,-0.172898,-0.069883,-0.438579,-0.195278,-0.252611,-0.323552,-0.393505,0.127230,-0.250593,-0.189956,0.169809,0.299026,0.297667,0.377274,0.264154,-0.113673,0.310838,0.349031,-0.285873,-0.139275,0.499229,-0.264018,0.007556,-0.107084,0.124527,0.100529,0.608512,0.373086,-0.221618,0.164454,-0.081860,0.420757,-0.100940,0.034866,0.174098,0.135930,-0.234932,-0.079343,0.020863,-0.325219,-0.126583,0.111848,-0.113416,-0.507191,-0.048748,0.089726,0.235293,-0.874243,0.518186,-0.224701,-0.232414,0.021305,-0.358367,-0.089369,0.440472,0.186946,0.165766,0.047574,-0.040734,-0.860043,0.240090,0.659458,-0.087015,-0.253159,0.149245,-0.393480,-0.548681,-0.085515,-0.343697,-0.512396,-0.094359,0.525891,-0.314956,-0.198737,0.275657,-0.565561,-0.227329,-0.319864,-0.305574,0.017839,-0.257620,-0.044579,-0.324232,-0.206458,-0.518990,-0.392661,-0.345281,-0.003732,-0.212657,0.627311,-0.810635,0.375596,0.637363,0.360493,-0.338289,0.519498,0.172781,0.275351,0.012496,-0.007407,0.398673,0.088473,0.415781,0.077142,0.508020,0.143530,-0.185687,-0.166431,0.653078', '1309069', '1783461', '10774184', '26678509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34967407', '德州电锯杀人狂', '惊悚', '梅洛蒂（莎拉·亚金饰演）和她的妹妹莱拉（艾尔西·费舍尔饰）与朋友但丁（雅各布·拉铁摩尔饰）和露丝（尼尔·哈德森饰）一同前往偏远的德克萨斯州哈洛镇，开始一项理想主义的新商业冒险。但他们的梦想很快就演变成了一场噩梦，因为他们不小心破坏了人皮杀人魔的家，这个疯狂连环杀手的血腥事迹，让当地人至今心有余悸，其中包括莎莉·哈迪斯（欧文·弗热瑞饰），作为人皮杀人魔 1973 年大屠杀中的唯一幸存者，她决心寻求复仇。', '莎拉·亚金', '大卫·布鲁·加西亚', 5.1, 10065, 'tt11755740', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2867287933.jpg', 14.1, 35.1, 37.6, 8.9, 4.3, '0.302512,-0.169208,-0.455317,0.501220,-0.089600,-0.264686,0.623008,-0.160284,-0.539315,-0.333909,0.212328,0.771440,-0.034761,-0.033128,0.385324,0.211756,-0.465161,-0.535043,0.081340,-0.044957,-0.424796,-0.377760,-0.347533,-0.482399,-0.010512,-0.239408,0.327905,0.223843,0.072053,0.516899,0.321471,0.542836,-0.170705,0.317336,0.221689,0.032171,0.283469,-0.241796,-0.377436,0.170523,-0.073523,0.173849,-0.146760,0.490558,-0.021546,0.423389,0.368053,-0.504908,0.383744,-0.252721,-0.018229,-0.343953,-0.067555,0.234092,0.092831,-0.245959,0.206585,0.147171,-0.123972,-0.314626,-0.022175,-0.234279,-0.771243,0.100709,0.122852,0.127862,-0.306199,0.471453,-0.237434,0.236680,0.223489,-0.027700,0.066685,0.331530,0.508003,0.064309,-0.122633,-0.204595,-0.297540,0.202976,0.633362,0.057528,-0.145326,0.000378,-0.332865,-0.382301,0.018161,-0.311375,-0.412516,0.024638,0.466039,-0.078650,-0.032763,0.464006,-0.841923,-0.368325,-0.374380,-0.120935,-0.065773,-0.250079,0.006362,-0.513834,-0.197337,-0.369371,-0.039864,-0.206677,-0.154906,-0.188955,0.459396,-0.774957,0.483457,0.616091,0.205222,-0.309326,0.419659,-0.076494,0.370638,-0.233421,-0.052652,0.478464,0.235638,0.097453,0.134100,0.296618,0.213894,-0.073819,-0.035088,0.558961', '1308585', '2032339', '2988294', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34967976', '我是大哥大 SP', '剧情', '特别篇中，仲野太贺继续饰演今井胜俊，新川优爱、樱井日奈子加盟出演不知为何对今井热情高涨的女大学生。', '贺来贤人', '福田雄一', 7.9, 20762, '我是大哥大 特别篇', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2602513070.jpg', 0.4, 2.5, 25.5, 45.1, 26.5, '-0.083955,-0.062710,0.003236,-0.038467,-0.024390,-0.010925,0.165161,-0.392191,0.173018,-0.383154,0.135019,0.477610,-0.622634,0.141598,0.849524,-0.058960,-0.654968,-0.184442,-0.289625,-0.373845,0.479194,-0.102833,-0.296764,0.547761,-0.221328,-0.028061,1.199783,-0.027815,0.054274,0.787464,1.039326,0.655072,-0.094777,-0.190222,1.003163,0.372304,0.736136,0.473983,-0.042854,0.483505,-0.095056,-0.492369,-0.887019,-0.240731,0.422750,0.376066,0.470206,-0.163982,0.174145,-0.356960,0.703070,-0.169939,-0.043511,0.339720,0.337769,0.534414,0.434994,-0.148912,0.010014,0.070475,-0.058555,-0.577588,-0.140176,0.037349,0.724872,0.290726,0.399746,-0.122186,0.055280,-0.607341,0.602006,-0.114181,-0.379421,-0.030438,1.187588,0.051930,-0.241940,0.628485,0.358460,0.298002,0.702770,0.405278,0.145605,0.107278,0.286090,-0.709887,0.113705,-0.115986,-0.683384,0.115304,-0.729562,0.209621,-0.073867,0.011062,0.011329,-0.169654,-0.112366,0.042206,0.153536,-0.187360,-0.047040,-0.874978,0.417427,-0.270748,1.211845,0.042885,0.617534,-0.496968,1.043682,-1.207931,-0.043224,0.187339,0.837639,-0.274493,0.341402,0.717003,-0.012046,-0.304946,-0.304307,-0.285181,0.410331,-0.207393,-0.044803,0.377953,-0.266002,-0.230460,-0.089035,-0.188525', '1316589', '25922902', '26784898', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34968329', '黑帮大佬和我的365日', '情色', '马西莫（迈克尔·莫罗内 Michele Morrone 饰）出生于一个非常繁盛的西西里黑手党家族之中，从小肩上就背负了继承家业的重任。身为族长的父亲遭人暗杀，尽管马西莫对与黑道这点事情毫无兴趣，但作为家族唯一的继承人，他只能接替父亲的位置，成为了首领。劳拉（安娜·玛丽亚·西克拉克 Anna Maria Sieklucka 饰）是一家非常豪华的大酒店的总监，虽然她年纪轻轻就已经攀登上了事业的顶峰，但内心的极度空虚和感情世界的一片空白常常令她感到备受折磨。为了排遣心中的苦闷，劳拉叫上好友一起踏上了前往西西里群岛的度假之旅，哪知道竟然在那里遭到了马西莫的绑架，更让劳拉没有想到的是，自己竟然会爱上这位穷凶极恶的绑匪。©豆瓣', '米凯莱·莫罗尼', '芭芭拉·比尔拉瓦斯', 5.8, 57901, 'tt10886166', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2609396514.jpg', 9.7, 26.1, 40.4, 14.4, 9.5, '0.194242,0.037950,-0.844555,0.704922,0.019222,-0.422527,0.515012,0.224416,-0.796407,-0.411906,0.202862,1.042758,0.097595,0.447244,0.485705,0.173282,-0.141780,-0.571786,-0.273205,-0.240225,-0.258940,-0.514338,-0.363526,-0.137079,-0.139524,-0.187824,0.763351,0.185199,-0.261497,0.366141,0.433535,0.650789,0.184556,0.442505,-0.203230,-0.020421,0.221978,0.124835,-0.148455,0.118272,0.080069,-0.170491,0.090811,0.450784,0.020015,0.348751,0.270097,-0.314318,-0.123268,-0.337713,0.154615,-0.278595,-0.069992,0.035252,0.284654,-0.207855,0.257462,0.381503,-0.321083,-0.124803,0.284752,-0.050071,-0.991050,-0.021675,0.225691,0.029068,-0.686703,0.323045,-0.104020,-0.382863,0.007237,-0.376986,0.334768,0.345749,0.139897,0.452059,-0.265001,0.074106,-0.583736,-0.273541,0.871310,0.097160,-0.022948,-0.008045,-0.254505,-0.281208,0.062619,-0.669776,-0.400641,-0.110437,-0.038560,0.061399,0.074107,0.412157,-0.399834,0.164646,-0.349943,-0.312743,0.165775,-0.475006,0.085449,-0.422665,-0.194300,-0.325496,-0.251640,-0.075360,0.141275,-0.332046,0.624208,-1.064101,0.186386,0.280740,0.342144,-0.521872,0.620603,0.204390,0.178640,-0.105152,-0.202596,0.313592,0.069248,0.181455,-0.116733,0.025868,-0.076122,-0.406712,-0.203806,0.580268', '1793491', '1783461', '27056396', '24875409');
