INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34970316', '昆仑神宫', '动作', '该片讲述的是摸金校尉胡八一、Shirley杨、王胖子为解开雮尘珠的秘密，与想要找到“水晶尸”的香港古董商人明叔一行人组成探险队，共同前往古格王国的遗址、喀拉米尔的龙顶冰川寻找古格银眼、冰晶尸骨，却意外遭遇神秘巨兽大白猿以及白狼王等危机，几经波折最终脱离险境的冒险故事。', '王龙正', '张羽', 3.6, 6716, '鬼吹灯之昆仑神宫', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2628271537.jpg', 39.8, 42.6, 14.5, 2.5, 0.6, '-0.179630,-0.173181,-0.710845,0.409955,0.421748,-0.198501,0.612783,-0.330157,-0.581024,-0.449141,0.246783,0.125808,-0.061699,-0.074966,-0.044818,0.030286,-0.115609,-0.398749,0.054350,-0.054451,-0.329180,-0.170569,-0.700337,-0.044641,0.008873,-0.295108,0.694605,0.595643,-0.215854,0.395718,0.113206,0.489365,-0.847367,0.281729,-0.208316,-0.023265,0.134307,0.181663,-0.429018,-0.076546,-0.225795,-0.114426,-0.139102,0.054371,-0.088601,0.355333,0.610725,-0.568884,0.017039,-0.225154,-0.151640,-0.304447,-0.080343,-0.150488,0.446006,0.067630,0.327153,0.222291,-0.031171,-0.156686,0.116625,0.016594,-0.455079,-0.142451,0.341421,0.515671,-0.425151,-0.025665,0.099001,0.246993,0.065815,-0.445268,0.432791,0.385080,0.661914,0.240320,0.043187,0.273710,-0.126385,-0.167217,0.513035,-0.105777,0.075233,-0.218871,0.104231,-0.762000,0.097529,0.215643,0.088170,0.234915,0.681034,0.274659,-0.077600,0.255231,-0.888486,-0.330956,-0.347028,-0.153199,0.209033,-0.223087,-0.037146,-0.678053,-0.244812,-0.018377,0.074906,0.058543,-0.003321,-0.134674,0.331606,-0.059371,0.342111,0.343165,0.046568,-0.195841,0.321389,-0.423830,0.256782,-0.403106,0.170520,0.195450,0.165098,0.451162,0.068436,0.054198,0.140126,-0.164083,-0.529590,-0.012532', '30336307', '24827406', '3097525', '7056398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34970325', '无辜者', '惊悚', '在一个暑假，四个小伙伴脱离了父母的监管，并发现他们都有隐藏的能力。当这些天真无邪的孩子在附近的森林里使用这些新能力时，不知不觉吸引了黑暗的东西，奇怪的事情开始发生。', '雷克·蕾诺拉·弗洛特姆', '埃斯基尔·沃格特', 7, 22035, 'tt4028464', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2669238453.jpg', 2.3, 7.4, 39.4, 40.2, 10.7, '0.710049,0.039648,-0.824070,0.323080,-0.451704,0.043049,0.832847,-0.243420,-0.640333,-0.772508,0.045239,0.582566,-0.076707,0.451295,-0.247132,-0.118580,-0.311636,-0.724753,-0.077747,-0.374258,-0.564531,-0.372181,-0.457581,-0.282771,0.039670,-0.667292,0.473321,0.263834,-0.245405,0.198495,0.092931,-0.222569,-0.403512,0.736364,-0.243202,0.059837,0.313459,0.147657,0.069358,0.262319,-0.426499,-0.115929,-0.253765,0.093254,0.120740,0.481098,1.068736,-0.254484,-0.686855,0.082598,0.366271,-0.154675,-0.281776,0.163547,0.625860,0.064151,-0.068010,-0.226253,-0.157314,0.293486,-0.385021,0.092594,-1.095618,-0.255547,0.027968,0.143621,-0.604563,0.148105,0.522288,-0.246034,0.149915,-0.552975,0.576621,0.394771,-0.088009,0.506718,-0.271528,0.002253,-0.635172,-0.042443,0.852802,-0.670571,-0.334103,0.695326,-0.316325,-0.471868,-0.280722,0.127138,-0.343595,0.239387,0.362972,0.371095,-0.472808,0.449927,-0.783642,0.337186,0.273274,-0.450283,-0.179861,-0.673498,-0.159877,-0.427635,-0.024690,-0.316038,-0.445995,0.321786,-0.171335,-0.082234,0.873746,-0.930652,0.496167,0.675305,0.191405,-0.692557,0.558010,-0.172894,0.318525,-0.112938,-0.366105,0.057539,0.249852,0.463673,0.014289,0.648142,0.028754,-0.236767,-0.638908,0.574869', '1793491', '25774050', '3262091', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34970503', '孤儿怨：首杀', '悬疑', '故事发生在上一作之前，伊斯特（伊莎贝拉·弗尔曼 Isabelle Fuhrman 饰）冒名顶替了一个在幼时失踪的女孩的身份，来到了翠西亚（朱丽娅·斯蒂尔斯 Julia Stiles 饰）和艾伦（罗西弗·萨瑟兰 Rossif Sutherland 饰）夫妻两人的家中，面对失而复得的女儿，艾伦显得非常的激动，而伊斯特所展现出的在艺术上的天赋让这对“父女”之间很快就建立起了亲密无间的关系。谁知道伊斯特的一举一动都被翠西亚看在眼里，随着时间的推移，她逐渐开始怀疑，眼前的女孩，和他们失踪的女儿并非同一人。刚开始，伊斯特只是准备将这个富有的家庭洗劫一空之后一走了之，可对于艾伦的眷恋令她留了下来，可这个决定也令她的真实身份被翠西亚知晓了。©豆瓣', '伊莎贝拉·弗尔曼', '威廉·布伦特·贝尔', 5.5, 18815, 'tt11851548', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2876102847.jpg', 6.9, 30.4, 48.1, 10.8, 3.8, '0.773766,0.292088,-0.979542,0.596659,-0.008716,-0.475603,0.788330,0.098518,-0.740798,-0.374762,0.077963,0.969859,-0.526518,0.134832,0.316588,0.159467,-0.525080,-0.822647,-0.257279,-0.446853,-0.239630,-0.569327,-0.088473,-0.061786,-0.152107,-0.278726,0.464830,-0.016739,-0.014731,0.518215,0.366462,0.413336,0.206593,0.432522,-0.018562,0.261187,0.037334,-0.039832,-0.169171,0.024576,0.228122,-0.100953,0.081510,0.325903,-0.040257,0.339044,0.777040,-0.539734,-0.175016,-0.013576,0.300928,-0.128962,0.091085,0.198767,0.423220,-0.067644,0.084393,0.228114,-0.508087,-0.096525,0.108508,-0.096214,-0.799086,0.376002,0.213864,0.304271,-0.598566,0.362735,-0.175115,-0.296417,0.073245,-0.378763,0.441439,0.717151,0.246829,0.404705,-0.113679,-0.178657,-0.541443,-0.228890,0.754723,0.107029,-0.110475,0.414941,-0.535040,-0.390633,-0.308551,-0.287642,-0.376316,-0.042929,0.108515,0.281437,-0.006141,0.399566,-0.561859,-0.034954,-0.417167,-0.131380,-0.127932,-0.774492,-0.137316,-0.302145,-0.385834,-0.589080,-0.539774,0.100650,0.011291,-0.287309,0.752898,-0.895896,0.283870,0.491203,0.533626,-0.241138,0.389500,-0.012036,0.081285,-0.108374,-0.287389,0.454384,0.209100,0.083332,0.102248,0.514295,0.033797,-0.056859,-0.265151,0.727460', '1301022', '3213250', '24756472', '1481233');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34973399', '你的婚礼', '爱情', '游泳特长生周潇齐（许光汉 饰）在一次打架事件中，对初来乍到的转校生尤咏慈（章若楠 饰）一见钟情，周潇齐对尤咏慈默默守护，接踵而至的却是女孩的不告而别。随后的人生，周潇齐并没有考上大学，在做网管的间隙突然发现了尤咏慈的踪迹，于是周潇齐复读考上了尤咏慈的大学，为的只是再次站在她面前再续前缘。两人的相遇并没有像想象中那种甜蜜，“恋爱的时机”总是不属于周潇齐，尽管死党张放（丁冠森 饰）等人想尽办法帮助周潇齐追爱，可尤咏慈的身边已经有了学长（梁靖康 饰）的陪伴。毕业后的两人天各一方，命运却再次让他们相遇，此后的人生，15年的爱情长跑。你的婚礼，也是我的成人礼。©豆瓣', '许光汉', '韩天', 4.6, 160430, 'tt14503918', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2639318976.jpg', 20.6, 37.9, 32.1, 7.2, 2.1, '0.337505,-0.248683,-0.776991,0.672465,-0.141321,-0.557454,0.845104,-0.070939,-0.441711,-0.108692,0.034605,0.767906,-0.368139,0.505197,0.180345,-0.207379,-0.173525,-1.175491,0.212332,-0.214795,-0.439359,-0.356925,-0.065367,0.122296,-0.056127,-0.104153,0.810433,0.161005,-0.006848,0.831527,0.245380,-0.046025,0.136611,0.775397,-0.410087,-0.190884,-0.077012,0.621640,-0.331627,0.080225,0.130837,-0.325545,-0.261977,-0.007816,0.140480,0.324407,0.748934,-0.241936,-0.181108,0.016747,0.372649,-0.261251,-0.081383,-0.055607,0.309597,-0.036332,0.205535,0.230699,-0.031981,0.157346,-0.120106,-0.244203,-0.582423,-0.053329,0.161038,0.091729,-0.575987,0.721732,0.158522,-0.160726,0.242050,-0.041627,0.110645,0.510409,0.427456,0.449302,-0.404703,0.089395,-0.404600,0.262261,0.712583,0.031555,-0.263681,0.710007,-0.141652,-0.537308,-0.114936,0.129064,-0.447695,0.164517,0.011005,0.209601,-0.267172,0.138224,-0.418741,-0.026765,0.034229,0.029134,0.167405,-0.688559,-0.090738,-0.454032,-0.080953,-0.524726,-0.574078,0.195338,0.062682,-0.319263,0.590398,-1.128672,0.131752,0.375588,0.445707,-0.472146,0.929762,0.357318,0.039672,-0.208684,0.060173,0.285944,-0.172726,0.291002,-0.045527,0.460487,0.265729,-0.117681,-0.381796,0.701774', '4202326', '2027925', '35030151', '25777330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34981939', '偷窥者', '惊悚', '皮帕和托马斯搬进了他们梦寐以求的公寓，他们注意到他们的窗户正对着对面的公寓——邀请他们亲眼目睹街对面这对迷人夫妇的不稳定关系。但当他们试图以匿名方式介入他们的生活时，他们不知不觉地引发了一系列将导致灾难的事件。', '西德妮·斯威尼', '迈克尔·莫汉', 6.8, 20754, 'tt11235772', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2681328483.jpg', 1.1, 7.7, 49.2, 33, 9, '1.083946,0.141437,-0.814054,0.505904,-0.073528,-0.060792,0.810782,0.281524,-0.632231,-0.154360,0.211428,0.916486,-0.293882,0.061830,0.361572,-0.041540,-0.493734,-0.757421,-0.229869,-0.041643,-0.593032,-0.283847,-0.358933,-0.480626,-0.016163,-0.128684,0.369788,0.273961,-0.376472,1.003585,0.262317,0.374961,-0.097953,0.591127,-0.092249,0.200911,0.244298,0.220212,-0.442410,0.233824,-0.299330,-0.601877,-0.159664,0.506813,0.131845,0.334085,0.839056,-0.103080,-0.484926,0.012970,0.189706,-0.402827,-0.071385,0.389255,0.665520,0.021821,0.203121,0.499777,-0.413585,-0.400978,-0.054763,0.025857,-0.936692,0.100625,0.002220,-0.006901,-0.365328,0.518131,0.076193,-0.321781,0.197470,-0.145016,0.482289,0.725520,0.232386,0.189513,-0.334341,-0.406466,-0.794771,-0.161024,0.874200,-0.207543,-0.089863,0.472976,-0.530228,-0.335314,-0.349730,-0.323434,-0.217043,-0.055117,0.504008,0.337782,-0.295641,-0.078927,-0.574038,-0.246663,0.014979,-0.435579,0.080753,-0.693846,-0.007224,-1.137653,-0.266410,-0.889292,-0.450916,0.149228,-0.576521,-0.029153,0.493437,-0.766906,-0.018439,0.733152,0.784938,-0.595894,1.222783,-0.148727,0.335586,-0.348227,-0.248400,-0.191619,0.033722,0.570372,0.294474,0.499307,0.009082,0.146910,-0.526013,0.612304', '3055049', '3147969', '3326747', '1296339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34982759', '玫瑰岛的不可思议的历史', '喜剧', '有天赋却被人误解的工程师乔治奥跌入了人生谷底，他被解雇了，父母也不和他讲话，并且在他意外令自己和女友被捕后（说来话长…），女友抛弃了他。厌倦了 60 年代末沉闷的意大利社会，乔治奥制定了一个不可能的计划；他要在海中建造自己的岛。在一群革命者和被驱逐者的加入下，玫瑰岛共和国成立并宣布独立，乔治奥被任命为总统。然而，他们的团队价值观和应变能力将受到考验，因为意大利总理认为乔治奥的理想岛是意大利的头号敌人。《玫瑰岛》由希德尼·希比利亚（《玩命毒师》三部曲）执导，由 Grøenlandia（《The First King》）出品，是一部基于真实故事改编的滑稽喜剧，剧中充斥着反叛精神。', '埃利奥·杰曼诺', '希德尼·希比利亚', 8, 31460, 'tt10287954', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2624341545.jpg', 0.4, 1.4, 20.8, 51, 26.4, '0.250564,0.271543,-0.982808,0.886489,0.002746,-0.069704,0.502804,0.144147,-0.387045,-0.252263,-0.027656,1.005751,-0.066000,-0.006927,0.403780,0.172937,-0.332007,-0.590511,-0.164170,-0.240738,-0.241746,-0.598771,-0.019966,-0.458304,-0.314937,-0.449057,0.810698,0.193134,-0.571115,0.077171,0.322204,0.550053,0.343152,0.569068,0.077835,0.134351,0.430159,-0.296574,-0.224753,0.191893,0.154857,-0.021152,0.071998,0.526642,0.082357,0.426519,0.730955,-0.399246,-0.059888,-0.219921,0.252850,-0.507574,0.128947,-0.021934,0.480030,-0.009777,-0.033662,0.538247,0.036788,-0.130437,0.160189,-0.359278,-0.873524,-0.111947,0.269068,-0.044539,-0.551440,0.509413,-0.314895,0.289377,-0.149876,-0.091452,0.219193,0.478437,0.547425,0.420649,0.253459,0.062970,-0.482578,0.372012,0.947648,0.004332,-0.490166,0.286832,-0.468323,-0.464230,-0.201012,-0.301686,-0.420328,-0.166063,0.411616,-0.303126,-0.078435,0.391808,-0.568114,-0.027809,-0.374801,-0.221825,-0.242975,-0.561876,0.168459,-0.331025,-0.110747,-0.111815,-0.138853,0.003558,-0.054282,-0.105311,0.661126,-0.759739,0.264630,0.676011,0.449486,-0.505525,0.778561,0.123799,-0.121703,-0.552923,-0.065847,0.420222,0.061665,0.031013,0.282711,0.353356,0.211760,-0.239730,-0.400831,0.412527', '30163500', '26678784', '1303034', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34983332', '白虎', '剧情', '巴尔朗·哈勒维（阿达什·古拉夫饰）讲述了他从贫穷村民成长为当代印度成功企业家的史诗般、充满黑色幽默的人生历程。我们年轻的主人公足智多谋而又雄心勃勃，设法成为了刚从美国回来的阿肖克（拉吉·库玛饰）和粉红夫人（朴雅卡·乔普拉饰）的司机。社会将巴尔朗训练成一名仆人，他便努力将自己打造成富有主人的得力帮手。但经过一夜之间的背叛，他意识到主人们会不择手段地陷害他以进行自救。在失去一切的边缘，巴尔朗决心反抗被操纵的人生和不平等的制度，奋起成为新型的主人。该影片改编自《纽约时报》畅销书和 2008 年曼布克奖获奖小说。', '阿达什·古拉夫', '拉敏·巴哈尼', 7.6, 23757, 'tt6571548', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2631140996.jpg', 0.4, 2.5, 30.8, 49.2, 17, '-0.010020,0.266575,-0.590395,0.724006,-0.112140,-0.541204,0.713080,0.141817,-0.187716,-0.182055,0.324087,0.737178,-0.110137,0.046145,0.498679,0.078082,-0.343640,-0.764169,-0.080471,0.109871,-0.080924,-0.333128,-0.103456,-0.278143,-0.226062,-0.390179,0.692010,0.001608,-0.370310,0.087581,0.323050,0.559916,0.209234,0.261832,-0.220534,0.178845,0.001932,-0.256654,-0.258308,0.192715,0.154282,-0.075633,-0.177228,0.071986,-0.074310,0.028164,0.538718,-0.438050,0.088048,-0.173144,0.626600,-0.294271,0.074554,0.339763,0.294840,0.052848,-0.341340,0.347781,-0.129696,0.111223,-0.056343,-0.162119,-0.935142,-0.209018,0.029957,0.122438,-0.664837,0.141632,-0.212905,-0.117773,0.107565,-0.285922,0.067517,0.371352,0.262824,0.210493,0.095790,-0.039905,-0.624639,0.188302,0.534336,-0.148738,-0.396515,0.178002,-0.265976,-0.523232,-0.043188,-0.408654,-0.473052,-0.170605,0.374351,-0.066934,-0.151029,0.431559,-0.511781,-0.238186,-0.334339,-0.361917,0.025883,-0.306233,-0.104524,-0.553784,-0.212214,-0.127268,-0.115771,0.016813,0.011924,-0.446539,1.065228,-0.805305,0.176976,0.636990,0.210036,-0.451511,0.531358,-0.133993,0.153223,-0.120928,0.057675,0.366296,0.186659,0.425422,0.199146,0.355491,-0.150914,0.054440,-0.141800,0.552546', '27602116', '24284209', '25928048', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34984272', '惊声尖叫5', '惊悚', '曾被一连串残酷的杀人事件蹂躏的宁静小镇伍兹柏勒，事隔了25年，一不明杀手再度戴上鬼脸面具，对一群青少年展开虐杀，迫使小镇居民重新面对过往的秘密。', '大卫·阿奎特', '马特·贝蒂内利-奥尔平', 5.7, 9397, 'tt11245972', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2695539565.jpg', 7.9, 24.8, 47.2, 14.9, 5.3, '0.244218,-0.004047,-0.030159,0.399566,0.088813,0.117359,0.836264,-0.241573,-0.685618,0.029950,0.567723,0.448071,-0.524124,-0.112470,0.467890,-0.210795,-0.030278,-0.689433,-0.268924,-0.398104,-0.505656,-0.177742,-0.415307,-0.371894,0.193479,-0.356775,0.372469,0.427627,-0.354754,0.570768,0.605331,0.371599,-0.582066,0.482362,-0.305097,-0.301905,0.056841,-0.000635,-0.518659,-0.037116,-0.605030,-0.654323,-0.237172,0.264039,-0.705124,0.329092,1.346210,-0.650055,-0.425572,-0.404114,0.241196,-0.601836,-0.483335,0.172058,0.612500,0.286241,-0.074162,0.313950,-0.164853,-0.277148,0.046311,-0.292047,-0.163875,-0.012639,0.058992,-0.017412,-0.311117,0.297168,-0.143187,0.558992,0.131651,0.191475,-0.067111,0.037057,0.761280,0.643957,0.223574,0.102009,0.206267,0.452173,0.509399,-0.015189,-0.189097,0.324799,-0.457119,-0.180037,0.062900,-0.485087,-0.269451,0.053870,0.309200,-0.472400,-0.697470,0.751131,-0.816194,-0.415992,-0.695993,-0.374932,0.314627,-0.340081,-0.853598,-0.547573,-0.279378,0.157078,-0.083806,0.349676,-0.265699,0.344088,0.584267,-0.977331,0.517059,0.575150,0.119016,-0.244856,-0.090930,-0.010686,0.056197,0.096848,0.172798,0.624470,0.589197,0.560559,-0.117994,0.187909,-0.367899,-0.167298,0.010486,0.552412', '35327724', '5364978', '10581450', '26761688');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('34991572', '大鱼', '爱情', '电影讲述了子豪生活在海边小镇归港，过着靠海吃饭的日子。一日，他偶遇神秘的女孩小艺，并开始照顾小艺生活。子豪父亲所在的远洋号，捕鱼船归来船员却全体失踪。经历丧父之痛的子豪在小艺的照顾下走出了阴霾，两人也在一起了。但好景不长，一个名叫老金的神秘中年人来到归港，揭开了小艺的真实身份——小艺竟然是人鱼族！子豪能否接受小艺的身份，小艺能否守住种族的秘密？', '付梦妮', '殷悦', 3.8, 3290, '', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2590614329.jpg', 40.5, 35.3, 20.7, 0.9, 2.6, '0.159803,0.002301,-0.383854,0.097958,-0.147923,-0.351053,0.482170,0.069839,-0.653197,-0.152253,0.570009,0.627971,0.241009,0.451566,0.446706,0.398043,-0.560679,-0.304100,0.131478,-0.167068,-0.144888,-0.299005,-0.043399,0.163957,0.366102,-0.413934,0.445615,-0.101225,-0.047696,0.763014,-0.240303,-0.124382,-0.582945,0.511140,-0.244555,0.089542,0.211464,0.073042,-0.731627,0.128011,-0.203638,-0.163906,-0.184381,0.188986,0.139362,0.303335,0.704101,-0.117423,-0.362654,0.283462,-0.052112,-0.255168,-0.075770,-0.290774,0.265638,-0.000383,0.268562,0.576877,-0.210709,0.252746,-0.456024,0.003863,-0.361098,0.224685,0.230494,0.463204,-0.511535,0.641372,-0.024669,-0.344291,-0.077033,-0.669236,0.094726,0.472341,-0.194519,0.615971,-0.326792,0.348185,-0.457059,-0.006784,0.782695,-0.080633,0.052589,0.348363,0.136715,-0.199835,0.049981,-0.097548,-0.679965,0.166561,0.121800,-0.073101,-0.528017,0.331487,-0.728819,0.390220,-0.405807,-0.156223,0.124363,-0.288121,-0.581226,-0.515108,-0.092046,-0.361752,-0.427699,-0.107957,-0.051952,-0.393714,0.879807,-0.905980,0.232848,0.445624,0.485061,-0.442263,0.712527,0.302002,0.209865,-0.226572,0.025664,0.337558,-0.396487,0.439588,-0.304792,0.291281,-0.242761,-0.194739,-0.477313,0.058399', '3445516', '1292219', '1292720', '1301562');
