INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35009298', '猪', '剧情', '一名松露猎手(凯奇饰)独自居住在俄勒冈州的野外，当他心爱的觅食猪被绑架后，他必须前往波特兰，带着自己被抛弃的过往，去拯救那只猪。', '尼古拉斯·凯奇', '迈克尔·萨诺斯基', 6, 14847, 'tt11003218', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2660101405.jpg', 6.3, 21.5, 44.7, 20.4, 7, '0.204633,0.056130,-1.025075,0.475420,-0.561050,-0.434661,0.836767,0.135239,0.079014,-0.061636,0.329722,1.150641,0.516503,0.664273,0.124082,0.399923,-0.364312,-0.419497,-0.300649,-0.200202,-0.514566,0.135186,-0.290824,-0.026635,0.138189,0.057241,0.562599,-0.301386,-0.307295,0.529066,0.301546,0.537630,-0.130038,0.509502,-0.913010,0.182725,0.498344,-0.015591,0.085524,0.360521,-0.130406,-0.246767,-0.048455,0.014411,-0.128969,0.277357,0.982391,-0.721419,0.053887,-0.583413,-0.093783,-0.640003,0.175785,0.587007,0.094099,-0.157076,-0.064413,0.059020,-0.333960,0.502531,0.245654,-0.151661,-0.855360,-0.510226,-0.050301,0.117446,-1.053868,0.392843,0.185444,0.206762,0.718814,-0.216218,0.341004,0.017834,-0.292456,0.457476,0.088517,0.071366,-0.985926,0.481922,1.164693,-0.271364,0.346850,-0.059639,0.168893,-0.354659,0.521761,-0.380537,-0.530415,-0.239106,0.747844,-0.158785,-0.709974,0.004091,-0.829671,-0.188164,-0.236150,-0.335124,-0.272110,-0.380266,-0.297550,-0.656100,0.512946,-0.574774,-0.220627,0.294407,0.183101,-0.136079,0.441890,-0.533506,0.664434,0.990480,0.288567,-0.725049,0.552536,0.043613,0.429732,0.119346,0.081805,0.560308,0.672351,0.866677,0.253043,0.342583,0.072398,0.031301,-0.944040,0.873862', '1309069', '21619567', '1904722', '1293908');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35017064', '老去', '剧情', '这是一个完美的海滩假日，至少有一家人、一对年轻夫妇、几个游客和一个流亡者都这么认为，他们来到了同一个幽静、田园般的小海湾，那里有岩石池和沙滩，四周环绕着绿油油的、植被茂密的悬崖。但这个乌托邦背后隐藏着一个黑暗的秘密：首先是在水晶般清澈的水中有一具漂浮的女性尸体。还有一个诡异的事实正在上演：所有的孩子都在迅速衰老。很快，每个人都都发现他们正在变老——每半小时一次——而且他们似乎没有任何办法离开这个小海湾。沙马兰说这部电影是受到 Pierre Oscar Levy和艺术家Frederik Peeters创作的法国图画小说《沙堡》（Sandcastle）的启发。《沙堡》的故事里有13个人，他们无法离开一个神秘，僻静的海滩，那里隐藏着涉及时间的黑暗秘密。不过漫画里并没有给出这个时间谜团出现的原因，更像是一个关于生存与死亡预言故事。但《OLD》并不是直接改编自这部图像小说，所以沙马兰本人会来讲完这个故事和脑洞。', '盖尔·加西亚·贝纳尔', 'M·奈特·沙马兰', 6.4, 27565, 'tt10954652', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2868189951.jpg', 2.5, 13.8, 52.1, 25.9, 5.7, '0.327876,-0.117961,-0.838649,0.950918,0.094329,0.180298,1.221027,-0.098177,-0.400573,-0.456270,-0.002723,0.826233,-0.075724,0.312699,-0.210198,0.051014,-0.603659,-0.536039,-0.214755,-0.260389,-0.437914,-0.569915,-0.465991,-0.120248,-0.108923,0.048714,0.627843,0.336696,-0.280304,0.391081,0.158439,-0.086237,-0.180572,0.413943,-0.408625,-0.013200,-0.007567,0.053580,0.012851,0.304395,-0.065253,0.136696,-0.104728,0.104824,-0.099768,0.408547,0.620568,-0.355803,-0.476675,0.152869,0.398422,-0.345592,-0.035123,0.028467,0.477119,-0.273371,0.415898,0.023526,-0.110040,0.101340,0.095533,-0.261747,-0.950304,-0.160654,0.084943,0.594981,-0.372276,0.244119,0.383881,-0.433861,0.025185,-0.151760,0.423983,0.107813,0.414561,0.210621,-0.335276,-0.064913,-0.783875,0.051027,0.582911,0.256922,-0.510768,0.542604,-0.307519,-0.558385,-0.229734,0.178788,-0.219800,0.175084,0.185826,0.094490,-0.433690,0.095444,-0.806072,0.441129,0.046037,-0.423037,-0.144694,-0.511360,-0.375586,-0.678724,-0.089961,-0.343619,-0.253154,0.264147,-0.199673,-0.210904,0.938187,-0.470373,0.340156,0.436709,0.241954,-0.308781,0.955671,0.089889,0.105655,0.060226,-0.082572,0.324229,0.029957,0.347586,-0.089726,0.374829,0.043510,-0.201313,-0.819