INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35027709', '猎谎者', '剧情', '三个月前，某市发生了一起恶性绑架杀人案。三个月后，凶手与被害人都死于车祸。初出茅庐的女警韩烨找到了案件的幸存者林超凡，向他求证案件发生的经过。但随着调查的深入，韩烨发现林超凡的很多证词都存在漏洞，再三逼问之下，林超凡无奈坦白了另一个版本的故事，但案件真相远没有这么简单，几乎每个人都在说谎，而故事也开始不断反转。', '王茂蕾', '廉欣', 6.9, 27838, 'tt12644232', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2611124274.jpg', 0.7, 8.2, 46.9, 34.3, 10, '0.095891,-0.180328,-0.714965,0.457569,0.072842,-0.086857,0.845361,-0.408539,-0.729405,-0.476114,-0.043277,0.098122,-0.397943,0.135827,0.221553,-0.664559,-0.280315,-0.756333,0.099222,-0.415537,-0.748377,-0.989339,0.051030,-0.615611,-0.022612,0.199084,0.255071,0.310858,-0.316479,-0.059383,0.446513,0.299655,-0.526092,0.500367,-0.052448,0.167234,0.131214,0.161544,-0.341538,0.381518,0.280915,-0.228416,-0.382507,0.074764,-0.055500,0.434279,0.598515,-0.290595,-0.797701,0.024248,0.758817,-0.331012,-0.205422,-0.147279,0.734530,0.368929,0.191024,0.431585,0.054030,-0.357505,0.194249,0.204942,-0.491601,0.083955,0.181870,0.347975,-0.370910,-0.149983,0.076944,0.148850,-0.024232,-0.274072,0.322440,0.672756,0.520639,-0.013971,-0.114804,0.030100,-0.641019,0.225340,0.709941,0.425024,-0.364380,0.132711,-0.048982,-0.765985,-0.495277,0.006330,0.138282,0.532829,0.153161,0.175285,-0.350610,0.381537,0.001182,-0.153499,-0.129315,0.008440,-0.425298,-0.559402,-0.081323,-0.513571,-0.205035,-0.239460,-0.432097,0.115728,-0.066661,-0.360043,0.446965,-0.361352,0.238778,0.394375,0.255480,-0.552034,0.293425,-0.000779,0.047349,-0.131276,-0.038127,0.324525,0.388597,0.326768,0.186413,0.424173,0.011892,-0.119063,-0.500994,0.030762', '1300299', '5353344', '5279640', '1293182');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35027719', '兴安岭猎人传说', '悬疑', '东北民间流传着关于“皇围猎人”的神秘传说，他们世代生存于深山，为帝王守护兴安岭这片龙兴之地的气脉运转。 传闻猎人除了精通狩猎之法，更知晓驱鬼通神之术。在东北一处偏僻的山村里，悄然发生一起灭门惨案，在村民们的恳求下，最后一代皇围猎人刘二爷（尚铁龙 饰）决定出山调查真相，不想过程中怪事屡现，老林子里的秘密也被渐渐揭开....', '尚铁龙', '刘轩狄', 5.9, 28641, 'tt15303274', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2635669599.jpg', 3.1, 19.5, 58.4, 16.6, 2.5, '0.042128,-0.060829,-0.609764,0.614293,0.305347,0.391526,0.096811,-0.217881,-0.869207,-0.755645,0.157749,0.424941,0.075193,0.126790,-0.029253,-0.273116,-0.055267,-0.185446,-0.038961,-0.311304,-0.179492,-0.100229,-0.339376,-0.297524,-0.290039,-0.333715,0.314930,0.790816,-0.444520,-0.065287,-0.021091,0.405956,-0.603573,-0.073366,-0.540732,-0.292317,-0.049288,0.041551,-0.344860,-0.049415,-0.446276,-0.375700,-0.229948,-0.124351,0.190242,0.041242,0.421654,-0.453443,-0.024541,-0.320417,0.084885,-0.079336,-0.182126,-0.027332,0.606600,-0.120359,0.493306,0.819610,0.021913,-0.372252,-0.074861,-0.118128,-0.525635,-0.046808,0.325601,0.371308,-0.329776,-0.029514,0.244275,-0.009445,-0.222261,-0.496225,0.469011,0.335540,0.298736,-0.105648,0.148961,-0.175401,-0.238631,0.245968,0.795752,-0.376991,-0.012741,-0.177754,0.179960,-0.534949,0.283670,-0.334110,-0.313581,0.140913,0.183144,0.037930,-0.183455,0.761268,-0.313059,-0.080273,0.054337,-0.212099,0.193655,0.052052,-0.242401,-0.515620,-0.011075,-0.052660,-0.118442,0.035362,0.193688,-0.043785,0.469402,-0.494363,0.543899,0.497367,-0.104328,-0.629397,0.607158,-0.279303,0.552067,-0.251310,-0.201064,0.286122,0.170142,0.649600,-0.117897,0.181850,-0.375836,-0.143157,-0.477446,0.143790', '5384590', '4767216', '1291861', '24827406');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35030151', '五个扑水的少年', '喜剧', '在我们普通的青春里，最疯狂的高光时刻会是什么？张伟（辛云来 饰）是一个长相普通、成绩中游的高二学生，是老师和妈妈眼中的「差生」。面对多方打压，他也渐渐对自己失去了信心，直到意外被任命为学校组建的男子花样游泳队队长，他一点点被改变……从来没有被人相信过的他面对队友高飞（李孝谦 饰）、陈铭涵（冯祥琨 饰）、蛐蛐（王川 饰）、王子（吴俊霆 饰）的信任，第一次有了想要赢一次的想法。为了心中重燃的热血，少年们决定一起迎接这场“男子花样游泳”的青春反击战……', '辛云来', '宋灏霖', 7.2, 140666, 'tt15163768', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2873274244.jpg', 1.1, 4.6, 37.6, 44.6, 12.1, '0.142347,-0.100211,-0.624206,0.554040,-0.428328,-0.086612,0.596412,-0.180568,-0.829783,-0.137756,0.231100,0.696399,-0.281244,0.195731,0.116811,-0.301449,0.067688,-0.760732,-0.182696,-0.062304,-0.226272,-0.314175,-0.226594,-0.083731,-0.268674,-0.245472,0.864838,-0.005329,-0.134717,0.905921,0.453892,0.128205,0.426965,0.376485,0.122145,-0.294451,0.097696,0.015898,-0.031483,0.328127,0.103918,-0.108772,-0.230109,0.351590,0.033119,0.395487,0.644420,-0.164355,-0.151976,-0.112221,0.183104,-0.248370,0.089117,0.358056,0.263159,0.079265,0.239328,0.181246,0.159041,0.012672,-0.043992,-0.152330,-0.710543,0.015262,0.297274,0.029070,-0.726257,0.691975,-0.008665,-0.177737,0.474890,-0.140126,0.086850,-0.056218,0.433247,0.251945,-0.229383,-0.111973,-0.330248,0.314441,0.981402,-0.019886,-0.282248,0.248829,-0.426355,-0.309012,-0.119581,-0.341589,-0.545431,0.286421,0.122379,0.148472,0.021329,0.021648,-0.400376,0.161265,-0.150642,-0.081041,-0.076666,-0.447807,0.054772,0.071997,-0.061852,-0.459137,-0.403794,0.196361,-0.142604,-0.211025,0.929867,-1.273772,0.037127,0.549961,0.398341,-0.400985,0.506017,0.238420,-0.112682,-0.249830,0.024023,-0.071361,-0.155709,0.065834,-0.090006,0.366444,-0.095118,-0.332610,-0.140830,0.490613', '1826173', '3445516', '1292219', '1395231');
