INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35055448', '双鱼陨石', '奇幻', '私营小老板王唯正在为养生馆的经营焦头烂额时，二十年前阴差阳错加入科考队而失踪多年的父亲王得志突然出现在面前。 时隔二十年，父亲竟然容貌未老，记忆错乱，仿佛从另一个时空而来。父亲向王唯讲起当年科考队的故事：一行人驾车进入荒漠进行科学勘察，准备返程时，发现了一艘本该出现在地球另一端的潜水艇。更令人意想不到的是，潜水艇中有一枚来自外星的“双鱼陨石”，任何人一旦触碰将开启平行时空，带来另一个时空的自己，为了活命，只得展开了一场厮杀……', '丁鹤', '丁小洋', 6.6, 16405, 'tt13057578', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2682753930.jpg', 2, 10.9, 46.6, 33.8, 6.7, '-0.070307,0.289119,-0.827672,0.616345,-0.100691,-0.437588,0.787483,-0.082382,-0.659328,-0.383372,0.149364,0.887564,-0.047046,0.202322,0.215676,-0.039627,-0.213910,-0.387480,-0.295813,-0.370333,-0.686299,-0.201587,-0.323369,-0.054645,-0.032751,-0.296002,0.572018,0.120451,-0.338149,0.227009,0.067711,0.140014,-0.552258,0.395034,-0.368876,-0.044459,0.053896,0.270780,-0.515523,0.186441,-0.146498,-0.220659,-0.084256,-0.036511,-0.462849,0.166583,0.813909,-0.461160,-0.254748,-0.479281,0.649157,-0.133326,-0.212439,-0.260113,0.319425,0.432505,-0.087075,-0.050084,-0.467558,0.026852,0.106643,-0.296422,-0.530826,0.165112,-0.233907,0.131936,-0.260295,-0.163709,0.008006,-0.099092,0.084692,-0.502287,0.408408,0.704974,0.491641,0.192256,-0.457227,0.047473,-0.270251,0.012878,0.790050,-0.062213,-0.264292,0.281818,0.308083,-0.366587,0.076077,0.001544,-0.215646,0.064950,0.236286,0.110953,-0.079417,0.376377,-0.658218,0.287062,-0.525829,-0.159269,0.183076,-0.206238,-0.588422,-0.661659,-0.002564,0.166186,-0.226641,0.435891,0.025847,-0.173042,0.519412,-0.674842,0.480395,0.620130,0.137897,-0.239591,0.703423,-0.153622,0.126086,-0.473837,0.128817,0.293574,0.204742,0.635896,-0.206556,0.217095,-0.255305,0.068091,-0.414837,0.302792', '34461680', '1453067', '27042738', '26682880');
