INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35057107', '我是真的讨厌异地恋', '爱情', '要相信：熬过异地，就是一生。故事围绕赵一一（任敏 饰）和许嘉树（辛云来 饰）展开，高考之后，赵一一终于向暗恋多年的许嘉树表白，却阴差阳错开启一场异地恋。他们坚信：熬过异地，就是一生。可远距离恋爱的天然阻碍考验着他们，明明相爱，却不断缺席对方的生活。赛赫（陈宥维 饰）的出现以及闺蜜乔乔（周雨彤 饰）和李唐（李孝谦 饰）一波三折的爱情都让赵一一感触良多。当异地恋升级为异国恋，是继续坚持，还是一别两宽，各自成长的二人不得不面对自己内心的答案……', '任敏', '吴洋', 4.4, 29745, 'tt18358032', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2870257091.jpg', 22.6, 42.7, 26.6, 5.8, 2.1, '-0.239241,-0.099129,-0.609851,0.659235,0.069520,-0.466535,0.680068,-0.441461,-0.271544,-0.123379,-0.185541,0.154408,-0.585893,0.553926,0.064958,-0.340107,-0.026170,-0.839243,-0.017100,0.149777,-0.366411,-0.460762,-0.239533,0.006640,-0.278604,0.083975,0.730608,0.232285,-0.144570,0.341066,0.679334,0.170299,-0.384875,0.449389,0.028277,-0.237285,-0.188203,0.478757,-0.884677,-0.128947,0.138146,-0.338855,-0.210800,0.172891,0.035519,0.190741,0.769488,-0.338969,-0.220244,0.231580,0.362426,-0.270003,-0.370294,0.006628,0.022131,0.065000,0.198811,0.108891,-0.082162,-0.052043,-0.071502,-0.038671,-0.508975,-0.224154,0.360570,-0.189285,-0.523558,0.228561,0.093227,-0.001966,0.067740,-0.444764,-0.062044,0.477001,0.844065,0.498672,-0.456908,-0.061856,-0.191471,0.303250,1.023741,0.092779,-0.488841,0.282096,-0.068430,-0.422424,-0.043075,0.000761,-0.621898,0.145733,-0.020061,0.165826,0.204891,0.210992,-0.546372,-0.014951,-0.254442,-0.103882,0.515117,-0.727357,0.264025,-0.314982,-0.169722,-0.626061,-0.665652,0.375302,0.023576,-0.617582,0.650288,-0.665219,0.327993,0.223514,0.195889,-0.800060,0.767605,0.601837,0.281961,-0.156638,0.433889,0.486164,-0.119063,-0.064400,0.046794,0.321556,0.037561,0.229341,-0.542526,0.550915', '27008393', '10535447', '1291546', '4145476');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35058077', '最后的前线', '战争', '这部电影讲述了1941年10月波多尔斯克军校学员在莫斯科郊外英勇抵抗的故事。波多尔斯克步兵和炮兵学校的学员被派往伊林斯基防线，与苏联第43军的部队并肩作战，阻止德军的前进，直到增援部队到达。由于寡不敌众，这些年仅十多岁的年轻人在一场持续近两周的战斗中献出了自己的生命。这场战 斗旨在阻止远为优势的德国军队向莫斯科推进。这部电影不仅关于战争。它也关乎爱情，真正的友情，以及从童年到成年的道路。大约3500名学员和他们的指挥官被派去坚守莫斯科郊外的最后一道防线。他们大多数人永远留在那里。', '阿尔乔姆·古宾', '瓦季姆·舒梅列夫', 7.7, 7105, 'tt12216986', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2603405556.jpg', 0.6, 3, 29.3, 46.8, 20.3, '0.093658,-0.107077,-0.802483,0.818367,0.332681,-0.201964,0.429575,-0.153210,-0.122603,-0.026484,0.188471,0.542602,0.256010,0.019883,0.381379,-0.706699,-0.281315,-0.771655,-0.149467,-0.170548,-0.469671,-0.222681,-0.045056,-0.087021,0.022254,-0.437343,1.156066,0.438079,-0.314611,0.390500,0.093532,0.222163,-0.022887,0.349613,0.260356,0.110247,0.191220,-0.372163,-0.411950,0.295348,-0.173096,-0.078688,-0.232274,-0.094449,0.035480,0.340999,1.062064,-0.311666,0.261538,0.247320,0.091649,-0.410693,-0.028651,0.049352,0.600927,-0.117046,-0.146235,0.199037,0.134657,0.168325,-0.653274,-0.213423,-0.611403,-0.128385,0.052588,-0.100660,-0.794403,0.655319,-0.104790,0.314174,0.258189,-0.110130,-0.025952,0.940374,-0.000723,0.368335,-0.358964,-0.084945,-0.609398,0.058024,0.927178,-0.099095,-0.533589,-0.076260,0.016744,-0.337519,-0.141868,-0.507068,-0.449476,0.172562,0.362423,-0.292610,0.219010,0.341592,-0.797532,0.112155,-0.317797,-0.592451,0.209675,-0.451584,0.088908,-0.908637,0.147155,-0.332608,-0.000216,0.375595,0.038640,0.076425,0.877135,-0.485968,0.056086,0.690202,0.477784,-0.414773,0.653758,0.157847,0.315853,-0.196201,0.088809,0.551473,0.059718,0.594848,0.221953,0.364669,-0.110870,-0.143958,-0.528623,0.426073', '1294917', '1381964', '5403927', '10467125');
