INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35068653', '误杀2', '剧情', '林日朗（肖央 饰）与妻子阿玲（文咏珊 饰）、儿子小虫（王昊泽 饰）一直过着清贫但幸福的生活，直到儿子小虫突发意外急需救治，几经周折，走投无路的林日朗为了救儿子决定放手一搏。他制定了一个惊天计划.....本片改编自电影《迫在眉梢》。', '肖央', '戴墨', 5.7, 329949, 'tt16117346', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2770857575.jpg', 5.5, 25.6, 50.3, 15.4, 3.2, '-0.527248,-0.195843,-0.564980,0.518007,0.109985,-0.380575,0.427545,0.216716,-0.582853,-0.449287,0.405347,0.472550,0.187276,0.152682,0.167532,0.041617,-0.134661,-0.288944,0.128037,0.115760,0.119646,-0.165329,-0.349993,-0.244948,0.082872,-0.262440,0.770478,0.171092,0.243537,0.607250,0.373813,0.240067,-0.236300,0.043173,-0.092055,-0.023522,-0.257580,0.140091,-0.537819,0.193921,0.230049,-0.237082,-0.450605,0.339206,0.072358,0.350947,0.759343,-0.202984,-0.389263,-0.230149,0.363718,-0.276869,-0.020001,0.186913,-0.062473,0.008054,0.549615,0.235223,-0.175344,-0.137169,0.253404,-0.158239,-0.716050,-0.036542,0.180914,-0.102546,-0.725395,0.275778,-0.311143,-0.022878,0.257293,-0.548209,0.249627,0.395400,0.332591,0.376964,-0.592286,0.223768,-0.464753,0.730235,0.441113,-0.324090,0.141240,0.481799,-0.233813,-0.139885,0.101849,-0.316231,-0.641378,0.153255,0.235125,0.047791,-0.508699,0.027574,0.010282,-0.249121,-0.220061,0.280249,-0.045632,-0.383053,0.142550,-0.204840,-0.186530,0.195327,-0.328702,0.308346,-0.172708,-0.277369,0.423981,-0.488172,0.285703,0.646614,0.090247,-0.566860,0.311360,0.288400,0.252955,-0.373992,0.105787,0.192571,-0.340942,-0.181475,0.235518,-0.216004,-0.026751,-0.153576,-0.321805,0.011526', '30180781', '30279170', '4840388', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35068654', '遇见你', '爱情', '女孩在最美好的青春里，遇到了一个想要勇敢去爱的男孩。18岁那年，被同学嘲笑为“垃圾桶”的余骄阳遇见了让她一见钟情的转校生周灿。她帮助周灿实现梦想，将周灿视为命中注定，并努力和周灿考到了一个城市，陪伴周灿成长。步入社会后，工作和生活琐碎逐渐占据了他们的恋爱时光，二人思维和轨迹不再同频， 女孩的期望逐渐变成失望，分手导火索也意外降临......一年后，周灿和骄阳再次相遇，种种回忆涌上心头，凝结成了意难平，明明相爱的我们，为何会分开?', '李汶翰', '落落', 5.2, 8744, 'tt18570412', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2877132523.jpg', 22.1, 29.3, 24.5, 14.1, 10.1, '0.241639,0.012045,-0.739710,0.410376,-0.288329,-0.589405,0.862540,0.078793,-0.431823,0.038376,-0.121614,0.702189,-0.270095,0.538266,0.491782,-0.227618,-0.217683,-0.937528,0.138380,-0.255390,-0.300176,-0.381320,0.086021,-0.046936,-0.015290,-0.506626,0.920243,0.298891,0.047576,0.593822,0.044129,0.097707,0.037456,0.585053,-0.157313,0.008975,-0.022072,0.399790,-0.396753,0.191660,-0.177546,-0.231976,0.059179,0.083534,-0.351179,0.095201,0.943141,0.008168,-0.205902,-0.281340,0.397857,-0.435308,-0.249115,0.190092,0.093528,0.260637,-0.036865,0.244018,-0.320165,-0.079595,-0.112948,-0.347023,-0.621044,-0.029490,-0.000244,-0.088890,-0.609662,0.343425,0.287103,-0.184039,0.392329,-0.313140,0.066881,0.406643,0.585850,0.381414,-0.467858,0.030442,-0.303030,0.288221,1.220802,-0.047886,-0.446044,0.699528,-0.262187,-0.133315,-0.124303,0.082781,-0.541811,0.013879,0.059386,0.275694,-0.452541,0.481969,-0.632539,-0.058186,-0.129201,0.068689,0.278539,-0.736427,-0.194950,-0.072691,-0.559574,-0.371838,-0.385716,-0.027408,-0.052340,-0.424759,0.938233,-0.861132,0.315047,0.497631,0.469062,-0.415959,0.788653,0.250476,0.016882,-0.501139,0.473678,0.533637,-0.318072,0.275880,-0.185217,0.172278,-0.309102,0.515009,-0.634107,0.538363', '25721544', '30209018', '2081098', '4861627');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35069014', '明天你是否依然爱我', '剧情', '是不是每个人的人生里都有一个爱不到的人？当毫无存在感的IT男费力（李鸿其 饰）遇见闪闪发光的女孩赵希曼（杨颖 饰），他找到了自己必须去冒险的理由。世间每一种限定浪漫，都是暗恋者的良苦用心。当明天到来，你还会记得最纯粹的感动和爱吗?如果有幸等到你，这个冬天一起去看极光吧⋯⋯', '杨颖', '周楠', 4, 20758, 'tt13149106', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2628574640.jpg', 36.2, 35.2, 21.7, 5.1, 1.8, '-0.174860,-0.107549,-0.969724,0.544281,-0.650263,-0.218083,0.697451,-0.236667,-0.172998,-0.178958,-0.151035,0.481580,0.154240,0.399153,0.254795,0.286906,-0.241401,-0.442468,-0.012110,-0.377928,-0.659919,-0.171554,-0.262596,-0.189404,0.141326,0.004912,0.369061,0.169246,-0.094423,0.107265,0.363058,0.045542,0.263821,0.755372,-0.431349,-0.249325,-0.085119,0.377203,-0.172720,0.100468,0.186821,0.120513,0.049223,0.318023,-0.158185,0.137520,0.276042,-0.301353,-0.165650,-0.014501,0.343551,-0.107521,0.047846,0.099823,-0.117341,-0.305985,0.361215,-0.020831,-0.032368,0.104669,-0.007316,-0.007339,-1.116737,-0.138774,0.300430,0.031432,-0.350296,0.453768,0.245793,-0.304926,0.302818,-0.335701,0.285843,-0.080158,0.327230,0.267510,-0.053721,-0.303658,-0.481283,0.386519,0.950419,0.126363,-0.200691,0.354297,-0.037687,-0.361733,0.157559,-0.081146,-0.625576,0.456160,0.066004,-0.031528,-0.205793,-0.316103,-0.512979,0.107299,0.229340,0.020304,0.077734,-0.676244,0.226454,-0.162286,0.320433,-0.518475,-0.293531,0.364255,0.283106,-0.527289,0.707968,-0.701904,0.397654,0.809557,0.339866,-0.741993,1.046431,0.476083,-0.240265,-0.132001,0.008264,0.169756,0.069780,0.286429,-0.113577,0.364082,0.346273,0.111358,-0.387837,0.561379', '30163500', '3785918', '6874741', '4604803');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35069506', '一点就到家', '剧情', '魏晋北（刘昊然 饰）、彭秀兵（彭昱畅 饰）、李绍群（尹昉 饰）三个性格迥异的年轻人从大城市回到云南千年古寨，机缘巧合下共同创业，与古寨“格格不入”的他们用真诚改变了所有人，开启了一段非常疯狂、纯真的梦想之旅。', '刘昊然', '许宏宇', 6.5, 263458, 'tt12740326', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2621101922.jpg', 1.8, 11.9, 49.9, 30.3, 6.1, '0.053353,0.071744,-0.306732,0.738043,0.076151,0.055271,0.565507,-0.011917,-0.627111,-0.246475,-0.135675,0.665246,-0.442083,0.432914,0.315046,-0.208959,-0.047463,-0.340627,-0.093992,-0.224501,-0.193693,-0.218615,0.001745,-0.044182,-0.186610,-0.172905,0.694931,0.399208,-0.352853,0.611027,0.191865,0.249033,-0.589858,0.265236,-0.263237,-0.119013,-0.361924,0.266292,-0.308187,0.005984,-0.283435,-0.268755,-0.219901,0.109298,-0.260658,0.109616,0.668708,-0.410012,-0.297607,0.048981,0.374839,0.230739,-0.593812,0.237587,0.023009,0.129560,-0.055468,0.250481,-0.290787,-0.024998,-0.019160,-0.366948,-0.452893,0.079716,0.062878,0.040408,-0.661472,0.336518,0.572228,-0.101922,0.010275,-0.554451,0.019557,0.553123,0.603396,0.266454,-0.090838,-0.051061,-0.170104,0.437639,0.803214,0.235229,-0.368541,0.215576,-0.183373,-0.421180,-0.186647,0.099052,-0.569028,0.137635,0.299211,-0.251916,0.425456,0.154887,-1.019852,-0.017273,0.026809,-0.102548,0.200806,-0.214454,0.007868,-0.783977,-0.137801,-0.643536,-0.245482,0.153573,-0.063496,-0.345930,0.833995,-0.891457,-0.178612,-0.032642,0.136568,-0.630244,0.422379,-0.342670,-0.018920,-0.648750,-0.007263,0.937032,0.073896,0.166540,-0.067102,0.628338,-0.671937,0.315529,-0.538460,0.610986', '26290398', '3811356', '10174444', '25785314');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35069520', '亲爱的房客', '剧情', '林健一（莫子仪 饰）是住在顶楼的房客，但他不只照顾年迈患病的房东周秀玉（陈淑芳 饰），还收养了她9岁的孙子王悠宇（白润音 饰），这一切看似超出普通房客的行为动机，在周秀玉去世后受到质疑，很多人怀疑他是为了顺理成章的获得遗产，他百口莫辩，因为这些举动背后隐藏着一段不被承认的感情，也更是他思念一个人的方式，而那个人正是房东已经过世的儿子…', '莫子仪', '郑有杰', 7.5, 15071, 'tt12359272', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2617989427.jpg', 0.5, 3.2, 33.1, 47.3, 15.9, '0.317916,-0.076008,-0.876921,0.569155,-0.663258,-0.111816,0.966301,0.094902,-0.785537,-0.521470,0.209919,0.762900,0.050084,0.431878,-0.076964,0.306820,0.025328,-0.372328,0.031881,-0.093812,-0.189718,-0.534984,-0.064447,-0.493943,-0.302000,-0.413880,0.459458,0.154136,-0.347398,0.192490,0.495537,0.321778,0.205567,0.618748,-0.360619,0.119158,-0.166469,-0.067024,0.131019,-0.101100,-0.129881,-0.419244,-0.006082,0.610399,-0.298385,0.591683,0.600807,-0.198676,-0.392190,-0.117246,0.342388,-0.487609,-0.075402,0.274667,0.564254,-0.099454,0.425221,0.323038,-0.533271,0.161648,0.098590,-0.216184,-0.964266,-0.002002,0.132470,0.235121,-0.712915,0.537221,-0.422647,-0.163554,-0.163661,-0.455236,0.187785,0.205820,-0.013762,0.483850,-0.563114,-0.181589,-0.585460,0.136179,0.905275,-0.086908,-0.195654,0.626238,-0.516816,-0.457437,-0.212885,-0.252126,-0.687343,0.223827,0.131039,0.107223,-0.347821,-0.021827,-0.268412,-0.082091,-0.086965,-0.018983,-0.226694,-0.714588,-0.120544,-0.185934,-0.353640,-0.687766,-0.653835,-0.031892,0.094720,-0.447117,0.645002,-0.813308,0.163313,0.396497,0.467119,-0.642427,0.763296,0.042084,0.126044,-0.155796,-0.158263,0.190799,0.014166,-0.220578,0.136830,0.214089,0.036328,-0.205089,-0.090653,0.535259', '1296370', '1304977', '6745433', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35073033', '没有过不去的年', '剧情', '年关将至，中年编剧王自亮（吴刚 饰）独自背负层层重压，周旋在事业、家庭、人际关系等多重问题中，倍感“年关难过”，母亲（吴彦姝 饰）最大的愿望，就是和四个儿女一起回老家吃年夜饭，然而，复杂的成人世界牵扯着孩子们。母亲的一次意外受伤，一家人的关系降至冰点，三代人的矛盾被推上 了风口浪尖……经过选择和考验，儿女们回归亲情，意识到“妈在的地方才是家”，日子再难，没有过不去的年。', '吴刚', '尹力', 5.6, 3562, 'tt12319512', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2628762684.jpg', 9.9, 27.5, 40.8, 15.5, 6.4, '0.009048,-0.178185,-0.688197,0.320139,-0.144829,-0.486600,0.553200,0.391320,-0.795243,-0.318446,0.102377,0.488822,-0.144967,0.409448,0.239620,-0.372933,0.061135,-0.777660,0.184456,-0.233979,-0.395068,-0.569466,0.166597,-0.033377,-0.356705,-0.323519,0.585293,-0.039085,0.050867,0.289220,0.473771,0.151995,-0.223111,0.522184,-0.291611,-0.096393,-0.092059,0.176822,-0.752449,-0.130139,-0.125734,-0.122335,-0.189417,0.171212,0.188643,-0.024439,0.759311,0.034695,-0.236489,-0.063029,0.234891,-0.088805,-0.276603,0.077063,0.723303,0.081514,0.177790,0.562982,-0.250025,-0.105536,0.180841,-0.286396,-0.502996,-0.064140,0.242704,-0.065792,-0.827675,0.580642,0.112444,-0.366547,0.116339,-0.211416,0.416867,0.489409,0.329752,0.847757,-0.485054,0.116517,-0.153201,0.169929,0.965125,-0.279832,0.038453,0.284784,-0.287537,-0.045400,-0.072969,-0.384905,-0.489374,-0.055122,0.151853,0.320111,-0.464951,0.696576,-0.339435,0.194152,-0.245916,-0.259073,0.133888,-0.429309,0.189925,-0.203647,-0.153884,-0.388499,-0.408672,0.277186,0.145696,-0.206154,0.858094,-0.374770,0.378998,0.413812,0.470255,-0.597983,0.838650,0.274771,0.547835,-0.418398,0.096201,0.035797,-0.414514,-0.134394,0.152016,-0.008389,-0.617858,0.176165,-0.150404,0.449172', '4066127', '26321184', '4861627', '2080130');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35073565', '门锁', '剧情', '单身貌美的方卉（白百何 饰），独自在大城市打拼，过着两点一线的生活。一天夜里，她突然听见门外有人暴力拉拽门把手试图闯入。虽然没有看清门外是谁，但通过保安小吴得知，自己楼层的监控坏了。这让方卉平静的独居生活突然笼罩在惊恐不安的阴影之中。当夜晚再次降临，熟睡中的方卉隐约察觉有人进入了她的房间，但她醒来后却没有发现任何迹象。渐渐，她的精神状态也开始变得越来越差。身边反复出现的几个男人，房屋中介高齐、保安小吴、公司领导李总、宠物医生郑飞，他们似乎都有自己不可告人的目的。随着好闺蜜乔小曼的离奇失踪，独居，几乎成为了方卉的梦魇……', '白百何', '别克', 4.3, 121740, 'tt13010918', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2685382025.jpg', 22.1, 46.3, 26.3, 4.2, 1.1, '0.376289,0.346967,-0.879804,0.331629,-0.158120,-0.199615,1.125732,0.090155,-0.543620,-0.486096,0.258882,0.232106,-0.394804,0.555437,0.123731,-0.062078,-0.315870,-0.714996,-0.171421,-0.069788,-0.393417,-0.024562,-0.407489,-0.205162,-0.178501,-0.009127,0.401373,0.142427,-0.168175,0.180466,0.211553,-0.126192,-0.094327,0.791272,-0.298446,-0.006000,0.269337,0.086766,0.091388,0.016020,0.116636,-0.371312,-0.396889,-0.023308,-0.018828,0.501312,0.426437,-0.099580,-0.386431,0.154746,0.303845,0.018375,-0.246070,-0.153573,0.411833,0.141901,0.123424,-0.134519,-0.168001,-0.107777,-0.172629,0.105968,-0.249525,0.344814,0.067030,0.213479,-0.291813,-0.012086,-0.013385,-0.146715,0.107151,-0.360508,0.234639,0.237552,-0.048305,0.386126,-0.213245,0.257507,-0.721516,-0.045306,0.486263,-0.092735,-0.316051,0.435446,-0.274914,-0.716063,-0.007144,0.174699,-0.389233,-0.148382,0.296764,0.072581,-0.396229,0.047596,-0.327286,0.063866,-0.012496,-0.212195,-0.328383,-0.267438,-0.175651,-0.448125,-0.250636,-0.200212,-0.162169,0.456997,-0.385861,-0.118856,0.418223,-0.864500,0.361349,0.355280,0.425853,-0.294048,0.731805,-0.152337,0.132865,0.026987,-0.019937,0.201121,0.033758,0.582194,0.339502,0.446948,-0.401104,-0.076159,-0.475555,0.482893', '27617348', '21348112', '1307807', '1304862');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35073886', '分手的决心', '剧情', '在山区调查一起谋杀案的海俊（朴海日 饰）遇到了死者的妻子瑞莱（汤唯 饰）。“我担心他没有从山上回来，以为他最终可能会死。”瑞莱对丈夫的死没有表现出任何激动的迹象，并且她的行为与悲伤的亲戚大相径庭，警方认为她就是嫌疑人。当海俊审问和监视瑞莱时，他意识到他正在逐渐对她产生兴 趣。与此同时，尽管被指控犯罪，但瑞莱开始对海俊采取大胆的行动。一个隐瞒真相的嫌疑人。同时想要怀疑嫌疑人的侦探。他们有了分手的决定。', '汤唯', '朴赞郁', 7.6, 144143, 'tt12477480', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2873816122.jpg', 0.8, 3.6, 29.3, 47.9, 18.4, '0.532614,-0.189107,-1.091536,0.406928,-0.168875,0.001344,0.776276,0.007433,-0.672785,-0.333777,0.246978,0.500203,0.020813,0.050528,-0.092818,-0.209219,-0.241482,-0.772061,0.003553,-0.065315,-0.331434,-0.696939,0.029009,-0.312290,-0.016589,-0.127050,0.380088,0.109692,-0.451346,0.340823,0.428162,0.298195,0.004679,0.749883,0.078707,0.011886,0.075921,-0.186848,-0.308055,0.172383,0.277623,-0.325053,0.050425,0.628973,0.002684,0.656894,0.642183,-0.152127,-0.536036,0.223219,0.447101,-0.283638,0.126407,0.356427,0.449398,-0.035752,-0.112170,0.443180,-0.332036,-0.326786,0.133694,0.225549,-1.050995,0.084598,0.061439,0.513352,-0.423275,0.158347,-0.254904,-0.010035,0.203999,-0.229142,0.318827,0.401259,0.249015,0.040895,-0.146853,-0.147162,-0.592453,0.062566,0.701412,-0.204308,-0.044646,0.261056,-0.227424,-0.358231,-0.122212,-0.196553,-0.221232,0.090651,0.237638,0.114158,-0.581877,0.124877,-0.097302,-0.439216,-0.186306,-0.108983,-0.041585,-0.251680,0.051374,-0.089528,-0.176430,-0.275842,-0.449728,-0.049236,-0.173726,-0.319842,0.213893,-1.075429,0.279588,0.842091,0.423110,-1.033919,0.460049,0.300247,-0.308804,-0.327445,0.012805,0.219595,0.077056,0.112601,0.311799,0.168339,0.399328,-0.114490,-0.267394,0.056019', '1301022', '1947080', '1293265', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35076714', '扎克·施奈德版正义联盟', '动作', '布鲁斯·韦恩（本·阿弗莱克饰）为了确保不让超人（亨利·卡维尔饰）白白牺牲，他决定与戴安娜·普林斯（盖尔·加朵饰）联手并计划招募一支超能力者团队来保护世界免遭即将到来的灾难性威胁。但这项任务比布鲁斯想象中要困难，因为每位成员都必须面对并跨越自己过去的心魔，团结起来，最终形成一个前所未有的英雄联盟。 蝙蝠侠、神奇女侠、海王（杰森·莫玛饰）、钢骨（雷·费舍饰）、闪电侠（埃兹拉·米勒饰）现在必须联合起来，否则就无法阻止荒原狼（塞伦·希德饰）、狄萨德（彼得·吉尼斯饰）以及达克赛德（雷·波特饰）毁灭地球的可怕计划。', '本·阿弗莱克', '扎克·施奈德', 8.1, 286599, 'tt12361974', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2634360594.jpg', 0.5, 2.6, 19.5, 44.5, 32.9, '-0.296000,0.266417,-0.263112,0.337610,0.161180,-0.068438,0.420148,0.110766,-0.077663,-0.281602,0.081374,0.518760,0.215640,-0.323726,0.495828,-0.153515,-0.366893,-0.351269,0.229093,0.070462,-0.371458,-0.461273,-0.517687,-0.536099,-0.022760,-0.467527,0.629128,0.081322,-0.246260,0.229460,0.202500,0.496680,0.023003,0.131352,0.245370,-0.255378,0.126611,-0.096729,-0.585732,0.198243,-0.260311,0.446010,0.049940,0.662454,0.064410,0.043805,0.115333,-0.662412,0.182625,-0.463744,-0.032978,-0.211015,0.129506,0.005335,0.299077,-0.327950,0.047774,0.218860,0.232228,0.271273,0.200586,-0.181165,-1.201407,0.204799,0.350825,-0.086176,-0.237471,0.031154,-0.329368,0.275742,0.080028,0.004475,-0.379867,0.335434,0.616155,-0.004733,-0.246071,0.105528,-0.369568,-0.151456,0.296101,-0.163662,-0.156368,-0.114254,-0.132018,-0.258842,-0.392471,-0.216782,-0.248233,0.128293,0.313037,0.093360,0.147127,0.487471,-0.632909,-0.295480,-0.568946,0.037749,-0.122117,-0.341208,0.260434,-0.692640,0.194157,0.193725,0.023410,0.057626,0.143280,-0.172204,0.439004,-0.393212,0.063567,0.428867,0.175766,-0.397621,-0.065200,0.199721,0.418191,-0.501175,-0.096412,0.480428,0.255111,0.328692,0.056942,-0.057744,0.359351,-0.118880,0.157297,0.635987', '6844861', '27073234', '1293605', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35081918', '卧鱼', '剧情', '根据小说《余罪》改编。在接连失去几名特勤卧底后，省缉毒警队来到台海体育学院招人，缉毒经验丰富的许平秋看中了以余最为首的学渣团，他们虽然学习不好，风评两极分化，但却各有所长，知进退、有底线。然而想要争取对自己并不信任，也没有警察梦的余最以及学渣团，并不容易。', '王栎鑫', '米昊易', 4.4, 3073, '“Bad” Boy', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2616131569.jpg', 24.5, 42, 23.8, 8.4, 1.4, '0.484344,-0.543441,-0.458360,0.692390,-0.059016,-0.268378,0.569893,0.083716,-0.809397,-0.618572,0.064913,0.564922,0.280739,-0.337857,-0.004961,-0.349523,-0.293995,-0.583315,-0.262149,-0.385673,-0.457908,-0.650276,0.026820,-0.320387,-0.272630,-0.050097,0.789269,0.197886,-0.523334,0.093716,0.189443,0.377485,0.292151,0.661635,-0.157034,-0.112467,0.314185,0.115112,-0.110651,0.064319,0.072802,-0.232034,-0.547298,0.155938,0.405429,0.383222,0.337877,-0.124065,-0.461367,-0.111092,0.284276,-0.394138,-0.044276,-0.400965,0.650038,-0.177320,0.229614,0.214873,-0.102600,0.257142,-0.377380,-0.197857,-0.975805,0.005539,0.363903,0.068262,-0.535861,0.504550,-0.100980,-0.231357,0.058379,0.134455,0.112218,0.599710,0.194858,-0.186569,0.129760,-0.078825,-0.468548,0.271809,0.816352,0.316832,-0.218351,0.386353,-0.351686,-0.843642,-0.201709,-0.337560,-0.065348,0.070127,0.249964,0.323593,-0.055525,-0.063188,0.110822,0.135081,0.284469,-0.175667,-0.164562,-0.752386,0.125886,-0.474563,-0.055144,-0.544996,-0.539367,0.101151,0.061729,-0.019534,0.897503,-1.293871,-0.024677,0.562093,-0.106742,-0.793293,0.855984,0.443645,-0.052584,-0.741599,-0.329565,0.131479,0.505442,0.499664,-0.003292,0.317489,-0.148475,-0.862251,0.000504,0.133536', '1877596', '35030151', '1293265', '3811342');
