INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35087486', '黑道与家族', '剧情', '凭借《新闻记者》荣获2019年日本电影学院奖最佳影片的藤井道人导演，其最新力作转而呈现黑帮家族史诗，以1999，2005，2019三个年份为切入点，故事线跨越平成与令和时代的风云变迁，以极度压迫性的镜头语言诠释现代社会中的黑社会真相以及黑道族人的生存准则。绫野刚再度贡献影帝级别的表演，实力演绎年少漂泊被黑帮收留的主人公贤治，自此一生陷入残酷恶斗与亲情挚爱的两难之中。', '绫野刚', '藤井道人', 7.8, 18101, 'tt13356884', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2625912897.jpg', 0.5, 2.9, 24.9, 49.4, 22.3, '-0.165515,0.077018,-0.125520,0.865557,0.344836,0.057906,0.282400,-0.040020,-0.616278,-0.230575,0.087744,0.855612,-0.112397,0.118836,0.534898,-0.596952,-0.221793,-0.984510,-0.360893,0.013180,0.181821,-0.184097,-0.397987,0.010286,-0.377503,-0.379881,1.300366,0.100247,-0.628265,0.296127,0.233776,0.544556,-0.440926,-0.193334,0.030432,-0.139153,0.157775,-0.035227,-0.908555,0.147670,-0.350811,-0.323361,0.146211,0.306827,-0.435862,-0.019793,0.775549,-0.510510,-0.004433,-0.347547,0.669228,-0.294949,-0.571715,-0.086742,0.202601,-0.057439,0.440213,0.519861,0.265232,-0.021378,-0.128725,-0.185499,-1.082985,-0.383270,0.422255,0.072082,-0.262429,0.153452,0.043064,-0.149285,-0.077245,0.216956,0.080512,0.074976,0.950986,0.394748,-0.098258,0.041126,-0.035054,0.514556,0.472789,-0.069535,-0.567665,0.231772,-0.160661,-0.624609,-0.316108,-0.895687,-0.392765,0.001929,-0.039977,0.024370,0.033164,0.759597,-0.734867,0.059726,0.043972,-0.141659,0.226370,-0.400844,-0.114433,-0.606547,-0.667016,-0.399512,-0.085670,-0.207581,0.399195,-0.335950,0.985128,-0.538023,0.001725,0.096406,0.018176,-0.273270,0.746919,-0.072894,0.119922,-0.466987,-0.065407,0.432406,-0.081875,0.091999,-0.403937,-0.003542,-0.297877,0.006785,-0.063035,0.477465', '25880986', '26759820', '22265687', '27602116');
