INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35101435', '斯宾塞', '剧情', '讲述1990年代早期关键性的一个周末，戴安娜下了决心：她跟查尔斯王子的婚姻不会有好结果，必须背离那条“皇后预备役”的道路。影片故事发生在3天内，圣诞假日期间的桑德灵汉姆庄园。', '克里斯汀·斯图尔特', '帕布罗·拉雷恩', 6.5, 24029, 'tt12536294', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2678164205.jpg', 2.1, 14, 47.5, 28.4, 8, '0.251612,0.066337,-0.609075,0.676472,0.284547,0.070025,0.582352,0.071245,-0.306316,-0.190904,0.572975,0.578334,-0.244563,0.226345,0.449047,0.010211,-0.632690,-0.414820,0.248705,-0.230205,-0.373248,-0.517670,-0.065826,-0.142713,-0.050189,-0.587672,0.498487,0.022000,0.030784,0.082412,0.274123,0.044536,0.202277,0.245808,-0.250038,-0.026644,0.230590,0.008659,-0.391537,0.154048,0.259515,-0.144098,-0.295512,0.110971,0.345672,0.286736,0.429823,-0.280797,-0.112414,0.107267,0.647602,-0.179456,0.020573,-0.055614,0.565943,-0.014412,0.188876,0.935654,0.072845,-0.376623,-0.080594,-0.346485,-0.491760,-0.105577,0.174536,0.231848,-0.302602,0.571510,-0.075088,0.155583,0.447102,-0.520797,0.155442,0.436411,0.894511,0.064895,0.081444,0.042200,-0.674802,0.378806,0.876965,-0.079703,-0.327346,0.455298,-0.387324,-0.211699,-0.217898,0.020750,-0.568983,0.335857,0.498181,-0.361363,-0.713252,0.400762,-0.324592,-0.134308,-0.317896,-0.504396,0.240077,-0.409908,-0.208640,-0.545726,-0.080113,-0.407203,-0.063661,0.033241,0.035340,-0.095717,0.608672,-0.569043,0.340622,0.598956,0.115619,-0.579500,0.957682,0.230589,0.336031,-0.151112,0.503856,0.014413,-0.515832,0.297192,-0.253081,0.330265,0.106684,-0.013806,-0.548244,0.608721', '3055049', '30159567', '1309177', '1291564');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35115642', '平行森林', '科幻', '杜燕在车祸中失去了年幼的儿子，万念俱灰的她住在自家经济不景气的森林会所，失去了生活的动力。丈夫白岭的贴心关怀，反倒平添她的伤感。一个清晨，巡视森林的她遇到了另一个“自己”，跟随着那个人，她来到了一个平行世界的进出口并踏过了那扇门，而这也是一场噩梦的开始。在不同的空间里，她遇到了性格完全不同的丈夫、哥哥，而且每个空间的现实都不尽相同，同时，她也遭遇到了各种危险，并差点丧命。最终她得出结论，要杀掉某个空间的自己取而代之，才可以平息这一切。可善良的她终究难以下手，渐渐的，她成了游荡在平行空间中的鬼魂一样的存在，直到不经意间，她回到了看似自己原来空间的地方，而这一场梦境，似乎还未结束。', '唐小然', '郑雷', 6.4, 6755, 'tt12740606', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2692942421.jpg', 3.1, 15, 44, 33.3, 4.5, '0.501059,0.377243,-1.084180,0.663014,-0.407112,-0.309228,1.241052,0.141749,-0.565104,-0.219657,0.295754,0.888614,-0.027966,0.347699,-0.068574,0.052615,-0.178607,-0.552978,-0.219267,-0.282516,-0.609328,-0.233562,-0.402344,-0.186201,-0.070153,-0.228255,0.642093,0.280746,-0.109717,0.043692,0.037250,-0.056197,0.011662,0.889937,-0.521651,0.295888,-0.103140,0.147494,-0.027777,0.142605,0.020775,-0.277283,-0.089612,0.534852,-0.297137,0.425098,0.924385,-0.339038,-0.214423,0.083458,0.501171,-0.283784,-0.165337,0.101077,0.225971,-0.202991,0.161292,-0.036821,-0.276831,0.192386,0.052771,-0.048877,-0.901938,0.040677,0.041637,0.122682,-0.384594,0.444815,0.412840,-0.155061,-0.150098,-0.307246,0.225999,0.412509,0.311306,0.417206,-0.591411,-0.148512,-0.589611,0.084197,0.837935,-0.256527,-0.646168,0.781898,-0.273532,-0.482239,-0.225139,-0.145913,-0.518765,-0.039615,0.495760,0.260500,-0.503460,0.319818,-0.768208,0.205005,-0.159193,-0.280950,-0.410495,-0.523128,-0.257784,-0.165030,-0.304587,-0.580341,-0.445918,0.219514,0.003241,-0.142562,0.460548,-0.985897,0.318079,0.845820,0.130360,-0.512758,0.496870,0.106914,0.169165,-0.210418,0.065102,0.542378,-0.214556,0.574821,0.130111,0.544363,-0.076629,0.200621,-0.699990,0.752836', '21619567', '3059036', '1308197', '1867335');
