INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35123985', '平行母亲', '剧情', '简尼斯（佩内洛普·克鲁兹 Penélope Cruz 饰）人到中年，意外的得知自己怀孕了，虽然这个孩子来得有些突然，在简尼斯的人生计划之外，但她还是欣喜若狂的接受了这个稚嫩的新生命的到来。和简尼斯境遇相似的还有名叫安娜（米莱娜·斯米特 Milena Smit 饰）的女子，但和简尼斯不同，安娜并不能够坦然的接受这一场人生的变调，这个孩子除了带给她身体上的变坏外，还带来了焦虑和恐惧。就是这样两个大相径庭的女人，她们在上帝的指引之下住进了同一间病房，在长长的医院走廊里，常常会出现她们结伴交谈的身影。两个女人，两位母亲，两段命运，在这个时空中发生了纠葛。©豆瓣', '佩内洛普·克鲁兹', '佩德罗·阿莫多瓦', 7.2, 13196, 'tt12618926', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2874073857.jpg', 0.6, 3.8, 41.8, 43.3, 10.6, '0.602666,0.037330,-0.922959,0.536943,-0.030744,-0.246940,1.209787,0.122328,-0.517266,-0.465797,0.195436,1.076827,-0.296368,0.457001,0.320639,0.156048,-0.432919,-0.730346,-0.149916,-0.164789,-0.402057,-0.585326,-0.168304,-0.256119,-0.157506,-0.287854,0.369576,0.025284,-0.038021,0.727963,0.348132,0.062121,-0.162040,0.443653,-0.196896,0.243603,0.110272,0.139797,0.050585,-0.216893,0.210739,-0.073596,-0.082444,0.485406,0.071601,0.465015,0.482793,-0.246335,-0.178965,-0.076573,0.315945,-0.076884,-0.130720,0.257339,-0.044195,-0.361420,0.205142,0.058127,-0.167093,0.007812,0.055142,-0.068570,-0.845397,0.341577,-0.052800,0.395290,-0.509843,0.324843,-0.074277,-0.180766,0.102010,-0.371397,0.271937,0.472675,0.209957,0.477505,-0.459335,-0.236780,-0.648304,-0.118531,0.661526,0.178171,-0.462965,0.336754,-0.498624,-0.484444,-0.392721,0.148392,-0.722446,0.141170,0.258854,0.332278,-0.317873,0.330073,-0.557248,0.037398,-0.342184,0.038314,-0.172108,-0.577264,-0.207714,-0.606982,-0.163450,-0.830718,-0.793168,0.113206,0.071239,-0.416538,0.678232,-0.971617,0.151525,0.311192,0.495753,-0.326637,0.692425,0.315962,0.355048,-0.096517,-0.001405,0.401139,-0.266552,0.044727,-0.004366,0.645593,-0.136591,0.212730,-0.680803,0.551559', '1296534', '4275444', '3111650', '1292062');
