INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35131347', '一周的朋友', '剧情', '胜华高中的复读班上，新来了一个转学生林湘之（赵今麦 饰），她文静聪明却总是孤独一人，不跟其他的同学做朋友。但这样的她却吸引了班上的学渣徐又树（林一 饰）的注意。在徐又树不断想跟林湘之做朋友的过程中，他和古灵精怪的宋晓楠（沈月 饰）、高冷学霸蒋吾（汪佳辉 饰）发现了林湘之的秘密，原来她患了一种特殊的疾病，她对朋友的记忆只有七天。为了帮助这个孤独的女孩，他们四个人组成了“末日生存”小队不断为她创造惊喜和属于他们的记忆。殊不知，林湘之的疾病背后却有个更悲伤的秘密......影片根据叶月抹茶同名漫画改编。', '赵今麦', '林孝谦', 4.5, 24747, 'tt17506728', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2874367740.jpg', 23.2, 38.7, 28.7, 6.9, 2.6, '0.234460,0.069759,-0.594965,0.929354,-0.352993,-0.197601,0.909550,-0.043644,-0.349378,-0.479928,-0.202040,0.623844,-0.121588,0.526539,0.014715,-0.134762,-0.041361,-0.716617,0.052945,-0.140396,-0.477881,-0.259756,-0.321955,-0.301285,-0.223762,-0.018226,0.367943,0.086418,-0.192627,0.274300,0.335875,0.268470,-0.064828,0.591544,-0.084528,0.024587,0.000181,0.123146,0.064976,-0.187654,0.160306,-0.444209,-0.141147,0.205585,0.032638,0.462666,0.925282,0.033575,-0.229492,-0.186044,0.326635,-0.232468,0.021103,-0.274957,0.271957,-0.064893,0.083452,-0.209947,0.092395,-0.162146,0.027681,-0.016771,-0.811196,0.017974,0.411505,0.262255,-0.327977,0.489967,0.054803,0.058948,-0.050382,-0.159449,0.295239,0.299841,0.320719,0.313711,-0.306874,-0.119105,-0.405049,0.432568,0.602462,0.052439,-0.126459,0.588365,-0.542606,-0.681627,-0.048823,0.114944,-0.477798,0.044376,0.302652,-0.088306,-0.084133,0.100907,-0.690786,0.003808,0.221967,0.146951,-0.152238,-0.653413,0.270348,-0.264442,-0.046044,-0.453150,-0.444899,0.227205,0.075013,-0.404870,1.101765,-0.753650,0.015075,0.448613,0.287240,-0.719807,0.702674,0.025443,0.121000,-0.303899,0.134961,0.314127,-0.004657,0.092774,0.100459,0.726999,0.012640,-0.079138,-0.661347,0.508059', '2053515', '26283288', '26348103', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35131427', '馗降：粽邪2', '恐怖', '《馗降：粽邪2》延续第一集宫庙民俗的侧写，将镜头伸向传统送肉粽仪式中最重要的桥段—跳锺馗，通常会由事主家属聘请专门的法师扮演锺馗，将上吊亡灵的怨气送到海口祭吊煞，以达到驱邪避凶之效。本片锺馗便由影帝饰演，李康生在剧中的角色自幼带有天命能见阴阳，他却因此命运多舛，所幸由雷洪饰演的金龙师点化开悟，成为锺馗身为民除煞。然而他的命运却没有从此一帆风顺……今年因为疫情肆虐，戏院排片也饱受影响，目前《馗降：粽邪2》仍定档今年农曆七月，希望鬼门大开之时，藉由鬼王出巡的气势，为大家驱疫除害。', '李康生', '廖士涵', 6, 7337, 'tt13212006', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2613127431.jpg', 5.7, 20.5, 48.4, 18.1, 7.3, '-0.030562,0.001141,-0.270896,0.383117,0.051715,0.219412,0.257588,0.468534,-0.068067,-0.311656,0.352342,0.455433,-0.186279,-0.286980,0.251805,-0.381571,0.096596,-0.329444,-0.078333,0.001013,0.057042,0.054878,-0.119128,0.304941,-0.537205,-0.552041,0.576746,0.025516,-0.027574,0.186646,0.231112,0.386916,-0.058378,-0.052151,-0.029749,-0.158733,-0.364437,-0.149620,-0.108541,0.452730,-0.090242,-0.416896,-0.245724,0.105069,-0.233206,0.386469,0.633760,-0.369500,-0.150357,-0.120965,0.480174,-0.184520,-0.217687,-0.020055,0.319599,0.058366,0.145949,0.446091,-0.028810,-0.044053,-0.176741,-0.077502,-0.818791,0.015250,0.408849,-0.046858,-0.181870,0.316896,0.030978,-0.019670,-0.042349,-0.128344,0.162510,0.121679,0.065443,0.375370,-0.078792,0.051220,-0.184552,0.335320,0.393328,-0.374022,-0.199891,0.337428,-0.026747,-0.456854,0.172628,-0.252836,-0.252022,-0.014115,0.166665,0.210659,0.284890,0.031948,-0.271332,-0.136188,-0.127019,-0.031053,0.174917,0.215876,0.018983,-0.429890,-0.075311,-0.197697,0.201160,-0.243641,0.424423,-0.322776,0.504179,-0.491471,0.332740,0.285449,0.086466,-0.353195,0.815450,0.169214,0.207597,-0.250665,-0.211210,-0.019523,-0.078568,0.530653,-0.008774,-0.071419,-0.151584,-0.161554,-0.291602,0.426014', '26759820', '25880986', '26635323', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35131877', '工作细胞：细胞大作战', '喜剧', '这是人类的体内。许许多多的细胞勤奋工作的世界。某日白细胞(中性粒细胞)与红细胞，遇见了收留迷路乳酸菌的一般细胞。为了将乳酸菌护送至同伴身边，白细胞(中性粒细胞)与一般细胞向肠道出发。然而他们却与来者不善的最强敌人重逢。「我和你们到底谁才是正义的一方，趁这次弄个清楚吧」再次现身的癌细胞。以及遭到坏菌破坏的肠内环境。体内遭遇前所未有的大危机！？「束手就擒吧 癌细胞！」为了守护这个世界，白细胞们(中性粒细胞)向赌上世界命运的大战发起挑战。', '花泽香菜', '小仓宏文', 6.8, 9567, 'tt13054188', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2635186282.jpg', 0.9, 6.5, 52, 33.3, 7.3, '-0.082133,0.212981,-0.495817,0.286241,-0.192180,-0.140589,0.708625,-0.050073,-0.174504,0.037325,-0.194886,0.781093,-0.127721,0.160786,0.119013,0.039466,0.038130,-0.595725,-0.411919,0.029771,-0.699591,-0.002472,-0.255354,-0.007836,0.231191,-0.571034,0.767575,0.306343,-0.313884,0.395957,-0.080656,0.668487,-0.272787,0.470319,0.068842,-0.379608,-0.243626,-0.245924,-0.300142,0.317374,0.353529,0.090903,-0.024777,0.090477,-0.026989,-0.201697,0.775844,-0.464710,-0.212914,-0.674674,0.235019,-0.285212,0.009222,0.151499,0.410263,0.128496,0.356960,0.331090,0.171713,0.380666,0.061018,-0.104227,-1.070482,-0.114691,0.061032,0.213379,-0.095820,-0.003963,0.496017,-0.339216,0.194687,-0.144885,0.314509,0.634356,0.383804,0.285911,-0.764939,-0.354459,-0.547840,-0.608672,0.952153,0.332336,-0.484498,0.088397,-0.052010,-0.318790,-0.231199,-0.014783,-0.319657,0.245010,0.047859,0.556536,-0.194011,0.489080,-0.826768,0.259017,0.078094,-0.324810,0.098512,-0.086260,0.017773,-0.655494,-0.364508,0.115510,-0.165415,0.411518,0.310950,-0.225972,0.703781,-0.506519,0.170860,0.660161,0.494546,-0.815527,0.436979,0.089420,-0.041388,-0.133626,-0.054993,0.067419,0.158870,0.295989,-0.164470,0.162462,-0.243430,0.425351,-0.406721,0.328096', '26678784', '25774050', '25827286', '26667010');
