INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35132974', '我的父亲焦裕禄', '剧情', '电影回溯焦裕禄同志短暂而光辉的一生。全片从“一名党员”“一位干部”“一个亲人”三个不同的角度全面立体的回顾了焦裕禄同志光辉的一生。根据焦裕禄二女儿焦守云口述改编。', '郭晓东', '范元', 7.5, 6816, 'tt16277056', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2673163209.jpg', 2.7, 5.3, 29.4, 38.5, 24.1, '0.032710,-0.268513,-0.151463,1.278967,-0.034420,-0.559836,0.592984,0.103660,-0.302198,-0.500235,0.508990,0.878763,-0.075581,0.465131,0.326240,-0.362256,0.091935,-0.809640,-0.355987,0.252031,-0.061722,-0.729674,-0.258370,-0.069879,0.230634,-0.473971,0.919445,0.072876,-0.089888,0.475786,0.031986,-0.127463,-0.180161,-0.491526,-0.128180,-0.467654,0.241619,0.102177,-0.642567,0.148311,-0.143543,-0.430325,-0.007209,0.198686,-0.668250,0.135070,0.704059,-0.242094,-0.311494,0.362323,1.030686,-0.058343,-0.160623,-0.006612,0.587963,0.139536,-0.081384,0.285367,0.074452,0.069900,-0.578226,-0.529551,-1.191385,-0.674229,0.181326,0.347379,-0.668892,0.451673,0.147260,-0.328457,0.124528,-0.164617,0.061819,-0.198184,0.059331,0.957786,-0.696281,-0.137740,0.365614,1.185752,0.376166,0.072277,-0.689282,0.640711,-0.588914,-0.176255,-0.169681,0.395264,-0.500425,0.436150,0.200501,-0.277529,0.166804,0.297427,-0.630831,0.239181,-0.195644,-0.157695,0.145661,-0.381481,0.329811,-0.566890,-0.548126,-0.116512,0.077106,-0.220867,0.083288,-0.116221,1.408899,-0.479662,-0.018049,0.248014,-0.665393,-0.464228,0.898227,0.522066,0.150277,-0.731370,0.793706,0.063970,0.443122,0.315105,-0.346866,0.433795,-0.465351,0.066873,-0.363936,0.271467', '27602116', '22265121', '3603547', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35134724', '魔法满屋', '动画', '讲述一个非同寻常的家庭——马利加家族的故事，他们隐居在哥伦比亚的山区一座神奇的房子里，生活在一个充满活力的小镇：一个奇妙的、充满魅力的地方，奇迹谷。奇迹谷的魔力使这个家庭的每个孩子都拥有独特魔法天赋，从超强大神力到治愈他人的能力……除了米拉贝（斯蒂芬妮·比翠丝 Stephanie Beatriz 配音）。但是，当她发现围绕奇迹谷的魔法处于危险之中时，米拉贝下定决心，她这唯一无魔法天赋的马利加人，将成为这个特殊家庭的希望。', '斯蒂芬妮·比翠丝', '杰拉德·布什', 6.4, 67604, 'tt2953050', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2807936075.jpg', 1.4, 12.3, 54.8, 25.7, 5.8, '0.118855,0.392854,-0.841435,1.098409,-0.184150,0.311302,0.811686,0.020486,-0.568850,-0.707111,0.011972,0.969395,0.152982,0.477164,0.042273,-0.056722,0.064670,-0.265768,0.020793,-0.068871,-0.769660,-0.328644,-0.497017,-0.458603,-0.150334,-0.805284,0.581671,0.395736,-0.470593,0.082579,-0.220276,0.500366,-0.120682,0.204179,-0.316308,-0.211849,0.281273,0.275480,-0.275585,0.455311,-0.284177,0.353772,0.151115,0.382737,-0.062516,0.041540,0.897242,-0.313186,-0.317809,-0.067365,0.528857,-0.150743,-0.252791,-0.169809,0.173451,-0.240478,0.013370,-0.225916,-0.102603,-0.234624,-0.091450,-0.298197,-1.257925,-0.500284,0.487522,-0.028360,-0.243169,0.171868,0.302873,-0.407022,-0.168963,-0.205457,0.051298,0.151049,0.355161,0.591286,-0.340641,0.333934,-0.588918,-0.160837,0.711045,-0.275618,-0.767437,0.525643,-0.693045,-0.712840,-0.336895,-0.174913,-0.658101,0.033528,0.177176,0.277323,-0.127856,0.248920,-0.793942,0.208020,-0.205012,0.146073,-0.060915,-0.645983,-0.187903,-0.630120,-0.128557,-0.263883,-0.542663,0.304902,0.148441,-0.317317,1.084624,-0.648553,0.396158,0.727229,0.157671,-0.389115,0.847990,-0.312134,0.309198,-0.434489,-0.424139,0.809552,0.137360,0.230087,-0.144242,0.542772,-0.113986,0.165885,-0.586038,0.896540', '1303542', '24284209', '26667010', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35134764', '上帝之手', '剧情', '荣获奥斯卡金像奖的编剧兼导演保罗·索伦蒂诺（《大牌明星》《绝美之城》《年轻的教宗》）以 20 世纪 80 年代动荡的那不勒斯为背景，讲述男孩法比托·斯基萨的故事。《上帝之手》中既有意料之外的惊喜，例如足球传奇人物迭戈·马拉多纳的到来，也有同样出乎意料的悲剧。对法比托而言，在欢乐与悲剧相互交织中，命运的齿轮已然开始转动。索伦蒂诺回到家乡讲述了他最具个人色彩的故事，故事主旨为命运与家庭、体育与电影、爱与失去。', '菲利波·斯科蒂', '保罗·索伦蒂诺', 7.7, 21675, 'tt12680684', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2688141684.jpg', 0.6, 3, 27.2, 48.1, 21.1, '0.152775,0.045554,-0.383730,0.674833,0.202340,-0.131857,0.712085,0.209996,-0.469595,-0.308651,0.018345,1.132253,-0.258709,-0.008983,0.657457,-0.159794,-0.520385,-0.831965,0.054340,-0.021702,0.292743,-0.632965,-0.243378,-0.006505,-0.166963,-0.512887,0.871728,0.172590,-0.267156,0.308497,0.222819,0.368386,-0.086733,0.036055,-0.018095,0.275513,0.114538,0.289192,-0.684889,0.081047,-0.110643,-0.107809,-0.306056,0.401250,-0.446634,0.095039,0.455767,-0.630855,0.051144,-0.232281,0.580346,-0.224911,-0.149151,0.035736,0.185238,0.377868,0.432346,0.422563,0.131372,0.049893,-0.104507,-0.500314,-0.794685,0.025492,0.372107,0.102960,-0.396760,0.307466,-0.022381,-0.138255,0.307849,-0.063711,0.254015,0.080646,0.662179,0.702017,0.081114,0.121943,-0.054627,0.207323,0.477694,0.348039,-0.689692,0.467539,-0.245103,-0.413164,-0.347956,-0.398027,-0.583587,0.329122,0.218223,0.125990,0.229234,0.803436,-0.462882,0.206808,-0.083506,-0.113700,0.041362,-0.432350,-0.328764,-0.528431,-0.230739,-0.289257,-0.056020,-0.210999,0.268762,-0.144263,0.943411,-0.795230,0.101200,0.298967,-0.053052,-0.121404,0.878865,0.137079,-0.010055,-0.549962,-0.231940,0.473184,-0.367615,-0.042488,-0.582486,0.114259,-0.172353,-0.094644,-0.337847,0.703606', '1870681', '1303034', '27602116', '30349667');
