INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35141706', '东北往事：我叫刘海柱', '剧情', '上世纪80年代初的东北，爱慕同事周萌的工人刘海柱因帮扶弱者，爱打抱 不平，招惹上了不良分子并给自己的家人朋友带来危险。在经历被坏人打伤， 被工厂开除等人生打击低谷后，刘海柱更面临危及生命的挑战。但此时，这个 神奇的男人竟然还能重新站起来，面对一个个惊天的挑战，令世人震惊的完成 着属于他的精彩传奇。', '许君聪', '周润泽', 5.2, 8503, '', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2617291342.jpg', 10.2, 37.1, 40.5, 9.1, 3.2, '0.311739,0.069898,-0.565085,0.247255,-0.225473,-0.204417,0.679599,0.139145,-0.538042,0.260133,0.363284,0.560124,-0.155773,0.291432,0.336785,-0.183644,-0.076141,-0.779965,-0.098003,0.110620,-0.668444,-0.288467,-0.316170,-0.067730,-0.211827,-0.269946,0.584919,0.179641,-0.396515,0.471089,0.122275,0.110073,0.244232,0.529994,-0.276523,-0.177748,-0.052655,0.131187,-0.294412,0.094643,-0.325304,-0.165896,0.142818,0.423952,-0.336165,0.176827,0.421132,-0.097441,-0.263284,-0.319253,0.600979,-0.409640,-0.167864,0.222044,0.280836,-0.017035,0.068655,0.025899,0.158308,-0.206079,0.055205,-0.085234,-1.054083,0.016575,0.080119,-0.035356,-0.519811,0.526617,0.240851,0.290852,0.073519,0.131278,0.278415,0.228501,0.185062,0.510854,-0.327919,0.018534,-0.253981,0.252683,0.678330,-0.373407,-0.119138,-0.065126,-0.264847,-0.025569,0.154738,-0.491319,-0.726242,0.249745,0.185877,0.138273,-0.263589,0.194877,-0.379991,0.219414,-0.220163,0.127686,0.036963,-0.582067,-0.442565,-0.184325,-0.244242,-0.152517,-0.413528,0.211103,0.313194,-0.392386,0.674224,-0.548548,0.264355,0.493459,0.505654,-0.270004,0.593780,0.170705,-0.046128,-0.138982,-0.281844,0.325655,-0.218707,0.370980,-0.176343,0.054460,-0.163489,-0.018364,-0.049616,0.315406', '30163500', '26678784', '1793491', '26635323');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35142915', '行骗天下JP：英雄篇', '喜剧', '信用诈欺师系列继香港、马来西亚，第三部电影版将舞台拉到了欧洲！眼见不一定为真，真金可能不用火炼，这场以世界遗产为舞台、尔虞我诈的游戏正要展开！被称作「英雄」的诈欺师〈第三代槌之子〉去世。而过去曾在第三代槌之子底下接受训练的达子、小少爷、理查三人，为了继承当代第一〈槌之子〉的称号，在世界遗产都市─马尔他岛・瓦莱塔进行对决。本次的目标，是西班牙前黑道手中的梦幻秘宝─古希腊凋像〈起舞的维纳斯〉。螳螂捕蝉，黄雀在后。好不容易钓上了大鱼，却没注意到警察与国际刑警佈下天罗地网正在身后…。信用诈欺师行骗天下的最大骗局正式开始！！究竟是谁，才能获得胜利女神的眷顾！？真正的〈英雄〉、最后的〈真实〉到底是─！？', '长泽雅美', '田中亮', 7.2, 17989, 'tt17008472', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2873795999.jpg', 0.8, 4.6, 40.5, 40.1, 14.1, '-0.030628,0.316717,-0.636295,0.486999,0.094566,-0.088469,0.016427,-0.160687,-0.347223,-0.228193,0.545885,0.685533,0.101460,0.024073,0.424199,0.095563,-0.143422,-0.551571,-0.406073,-0.218935,-0.450185,-0.237165,-0.468488,0.373672,-0.231143,-0.191549,0.735590,-0.017314,-0.254841,0.140490,0.770526,0.268379,-0.094124,-0.025556,-0.229587,-0.165757,0.303877,0.153449,-0.617908,0.166947,-0.245455,-0.300740,-0.152363,0.133877,-0.001136,-0.027449,0.452260,-0.520599,0.241406,-0.311492,0.428718,-0.179869,-0.143524,-0.109367,0.518470,-0.024386,0.242765,0.305087,0.243287,-0.125338,-0.058553,-0.308091,-1.015636,0.060153,0.300822,-0.085526,-0.392576,0.238624,-0.220757,-0.087533,0.076707,0.014069,0.383164,0.362719,0.478144,0.225026,-0.140259,-0.077932,-0.340774,0.363976,0.508958,0.141641,-0.232290,0.184185,0.380838,-0.503717,-0.070568,-0.585096,0.046471,0.053948,0.331449,-0.008974,0.150030,0.256502,-0.503629,-0.101783,-0.213289,-0.210564,0.409115,-0.272361,-0.025899,-0.447795,0.008006,-0.083997,0.119939,0.097305,0.155528,-0.336841,0.693022,-0.847092,0.314298,0.552089,0.080932,-0.315952,0.606323,0.238028,0.184397,-0.417903,-0.248479,-0.045875,0.129307,0.403116,-0.046090,0.074286,-0.031871,-0.331601,-0.298505,0.263527', '1793491', '4301278', '25880986', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35144311', '雄狮少年', '剧情', '阿娟（大昕 配音）的父母在大城市打工养家，他留守在故乡，因为孱弱的体格和怯懦的性格常常遭到旁人的欺负。一次偶然中，阿娟邂逅了和自己同名的舞狮少女（秋木 配音），少女飒爽的英姿和如雷贯耳的话语激起了阿娟对舞狮这项传动活动的兴趣，他打算参加舞狮大赛来证明自己的能力，很快，阿娟的好友阿猫（大雄 配音）和阿狗（郭浩 配音）也加入了这个计划之中。可是，舞狮哪有这么容易学，为了拜师，阿娟一行人找到了开鱼铺的咸鱼强（李盟 配音）。咸鱼强虽然现在活得窝囊，但曾经却是舞狮比赛的冠军，三个少年蓬勃的朝气和真挚的眼神打动了咸鱼强，重新唤醒了他对于舞狮的热爱。©豆瓣', '大昕', '孙海鹏', 8.2, 438150, 'tt16345484', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2702755317.jpg', 1, 2.1, 15.6, 46.1, 35.2, '0.114305,-0.100096,-0.709334,0.635383,-0.382428,-0.278494,0.570138,0.059724,-0.496539,-0.096951,0.018107,0.820323,-0.006924,0.142711,0.110766,-0.139712,-0.008298,-0.639104,-0.097172,0.099659,-0.123381,-0.351125,-0.142204,-0.029514,0.043660,-0.291159,0.449383,-0.003788,-0.459777,0.838136,0.401891,-0.236962,0.141568,0.206686,-0.185101,-0.034364,0.076310,0.276127,0.046407,0.134506,0.014161,-0.143001,-0.324662,0.211935,-0.051505,0.485564,0.581859,-0.073341,-0.366950,-0.053541,0.316811,-0.135434,-0.068558,0.020406,0.030298,-0.150175,0.250328,0.047123,0.013825,0.013249,-0.195502,-0.167167,-0.890856,0.178919,0.181769,-0.031357,-0.625807,0.611609,0.050630,-0.086391,0.050360,-0.229164,0.073927,0.084509,0.075269,0.553988,-0.033330,0.142184,-0.336293,0.443473,0.722612,0.083782,-0.217211,0.386770,-0.165542,-0.563706,-0.107951,-0.404761,-0.257203,0.196611,0.280615,0.013793,-0.290546,-0.014352,-0.603881,0.172692,0.062442,-0.009624,-0.069944,-0.320157,-0.007230,-0.581598,0.026335,-0.413351,-0.188237,0.041026,0.136631,-0.441593,0.907267,-1.027590,0.114167,0.454142,0.165231,-0.512706,0.589364,0.077685,-0.010697,-0.192457,-0.235766,-0.169649,-0.121194,0.183378,0.288742,0.459862,-0.021181,-0.377150,-0.438306,0.603330', '35030151', '4127270', '1292219', '27602116');
