INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35148918', '如果有一天我将会离开你', '剧情', '交换生李小李（谢承泽 饰）来到日本东京偏僻的“渊野边”留学一年。呆板木讷的他一心想要打工却屡屡碰壁，终于在老同学邱邱（邱天 饰）的帮助下找到一家中华料理店。代理店长管唯（齐溪 饰）收留照顾他、店员青木（牛超 饰）视他为情敌、后厨大师傅老万（陈永忠 饰）小师傅宋哥（宋宁峰 饰）倒都对他爱答不理……李小李的到来打破了地下一层的沉寂、也卷入进每个人的生活之中。时间稍纵即逝。下一个春天到来前、有人留下，有人离开，而那些刚刚羁绊成型的“限定亲情、临时友情、类似爱情”又会何去何从？', '齐溪', '李亘', 7, 12734, 'tt14891930', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2869336995.jpg', 1.1, 3.9, 44.3, 44.9, 5.8, '-0.013321,0.119875,-0.440785,0.297507,-0.156674,-0.396869,0.656888,0.109909,-0.280213,-0.327206,0.349542,0.548388,-0.106936,0.163944,0.258978,0.061822,-0.228290,-0.498781,0.040610,-0.289693,-0.267656,-0.135448,-0.295394,-0.146666,-0.035261,0.225599,0.377888,0.209590,0.031491,0.483000,0.118666,0.017721,-0.148269,0.396135,-0.170327,0.090775,-0.143181,0.147375,-0.316482,-0.020767,-0.173643,-0.189951,-0.114665,-0.154092,0.098723,0.458843,0.428069,-0.053844,-0.241522,-0.123464,0.281938,-0.101193,-0.161610,0.050410,0.142741,0.084001,0.287168,0.131268,-0.413350,0.421662,-0.079899,-0.061389,-0.403780,0.178848,-0.047401,0.060999,-0.451810,0.306383,0.191190,-0.036457,-0.123556,-0.450449,0.110138,0.305742,0.297274,0.421079,-0.278209,0.180089,-0.155394,0.040411,0.686835,-0.371965,-0.201988,0.216061,-0.066533,-0.102407,0.326202,0.090019,-0.499793,-0.234199,-0.002245,-0.048475,0.115584,-0.175776,-0.761002,-0.033962,-0.183746,-0.032452,0.161302,-0.235768,-0.118037,-0.399722,0.012608,-0.268002,-0.492363,0.362424,0.198706,-0.177884,0.577831,-0.715874,0.306132,0.330536,0.402259,-0.400952,0.532309,0.025268,0.121694,-0.291777,-0.039277,0.407249,-0.090815,0.388919,-0.133595,0.131749,-0.027483,-0.159351,-0.266265,0.061529', '1292219', '1308755', '1303036', '5977789');
