INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35151491', '奇奇怪怪：整容液', '动画', '人气恐怖悬疑韩漫《#整容液#》的改编动画电影发布预告！《整容液》出自韩国漫画家吴城垈脑洞大开的“奇奇怪怪”系列网络漫画，讲述一款名为“整容液”的产品能让人轻易改变容貌与身材，像捏黏土一样轻松变美，女主在使用整容液后成了受欢迎的“女神”，却因其副作用而出现了逐渐失控的展开。影片将于今年8月在韩国上映。', '문남숙', '赵庆勋', 6.2, 17845, 'tt12354886', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2616803984.jpg', 2.5, 15.7, 55.9, 20.2, 5.5, '-0.001220,0.418202,-0.274893,0.455976,0.284043,0.175635,0.496723,0.194533,-0.129174,0.100448,0.046706,0.570358,-0.724238,-0.152246,0.078982,-0.302484,-0.024702,-0.489673,0.034698,0.070087,-0.114214,0.050271,-0.527494,-0.181406,0.031772,-0.912814,0.975443,0.022518,-0.553130,0.148569,0.413764,-0.130481,-0.117710,-0.254392,0.111335,0.045566,-0.153469,-0.132974,-0.131936,0.589520,0.039403,-0.259125,0.387739,-0.201789,-0.173902,-0.006777,0.938554,-0.125991,-0.415260,-0.157098,1.222287,-0.056501,-0.414947,-0.130392,0.183081,0.352313,0.031904,-0.181565,-0.285970,-0.088498,0.111584,-0.281084,-0.891289,-0.028708,0.365228,0.463498,-0.275644,0.339947,-0.314601,0.002179,0.011568,-0.230195,0.097335,-0.002527,0.520411,0.483349,0.139244,0.175276,-0.286975,0.775105,0.076919,0.274380,-0.919508,0.716406,-0.212449,-0.238880,-0.387182,-0.581031,-0.085298,0.432353,0.155717,0.129750,-0.088194,0.103430,-0.554540,-0.069973,-0.014782,-0.245584,0.227356,0.153318,-0.207970,-0.901084,-0.253156,-0.132584,0.109165,-0.296685,0.249918,-0.464652,0.929221,-0.560756,-0.087332,0.272807,0.276462,-0.577020,0.351353,-0.253201,-0.397028,0.062988,-0.296910,0.273235,0.010278,0.217908,0.086058,0.604450,0.017277,-0.170025,-0.354896,0.465774', '26759820', '22265121', '27602116', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35154957', '消失的情人节', '喜剧', '公车司机阿泰（刘冠廷/饰），是一个动作慢吞吞、连手表的时间、地震的感应都比别人慢的奇葩。他每天都会去邮局，找柜员杨晓淇（李霈瑜/饰）寄一封不知道给谁的平信。柜员杨晓淇和阿泰完全相反，是个凡事抢拍的超级急性子，唯独感情生活毫无进展，年近三十还是母胎单身。情人节前夕，杨晓淇被天菜阳光男刘老师（周群达Duncan/饰）搭讪，终于情窦初开的晓淇和刘老师天雷勾动地火；想不到一觉醒来，刘老师再无音讯、而且情人节居然已经过了？！每天来寄信的阿泰也再也没出现过...毫无记忆的杨晓淇，开始了一趟寻找真相的奇幻旅程...', '刘冠廷', '陈玉勋', 7.3, 27829, 'tt13105824', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2618456760.jpg', 0.7, 5, 38.4, 41.9, 13.9, '0.079945,-0.366789,-0.707235,0.330139,-0.294266,-0.406647,0.414673,-0.162308,-0.450622,-0.268313,-0.298200,0.351512,-0.571028,0.024190,0.161772,-0.030403,-0.207306,-0.507156,0.016509,-0.116272,-0.483968,-0.128588,-0.134593,0.154949,0.126564,-0.035686,0.081992,-0.230066,-0.116400,0.413910,0.366966,-0.115394,0.119370,0.584610,-0.377545,0.067101,-0.062632,0.191179,0.207566,0.233161,0.215521,-0.224438,-0.116669,0.186737,0.064759,0.520335,0.406837,0.093123,-0.343442,0.150894,0.603157,0.003520,-0.258979,-0.032646,0.365100,-0.045431,0.079760,0.040203,-0.124283,0.024535,0.089560,-0.051564,-0.590165,0.381757,-0.158411,0.202786,-0.322723,0.251001,-0.093360,-0.240384,-0.123490,-0.697019,0.261087,0.259840,-0.028771,0.132630,-0.157533,-0.294594,-0.538283,0.289109,0.452815,0.118675,-0.323273,0.656049,-0.070267,-0.324906,-0.037600,-0.114730,-0.472247,0.367253,-0.030706,0.195688,-0.264966,-0.105917,-0.518580,-0.018304,-0.232997,-0.337932,-0.007060,-0.269531,-0.317914,-0.403212,0.140560,-0.517378,-0.558451,0.211353,0.302451,-0.111813,0.600756,-0.718987,0.242195,0.672942,0.310454,-0.376224,0.896439,-0.031559,-0.389777,0.002895,0.333097,-0.168514,0.078836,0.589961,0.275757,0.399718,0.141969,-0.254340,-0.138346,0.292632', '2052978', '1307811', '25876760', '2046839');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35155748', '金刚川', '剧情', '1953年，抗美援朝战争进入最终阶段，志愿军在金城发动最后一场大型战役。为在指定时间到达，向 金城前线投放更多战力，志愿军战士们在物资匮乏、武装悬殊的情况下，不断抵御敌机狂轰滥炸，以血肉 之躯一次次修补战火中的木桥。一段鲜为人知的历史，在暗流涌动的金刚川上徐徐展开......', '张译', '管虎', 6.5, 294014, 'tt13000980', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2623301908.jpg', 5.9, 14.2, 38.8, 29.1, 12, '-0.365057,0.284048,-0.799105,0.566017,0.524120,0.240032,0.548049,-0.239253,-0.210648,0.034170,0.859496,0.173985,-0.000928,-0.324392,-0.050873,-0.841833,-0.229550,-0.499239,0.142503,0.005944,-0.527996,-0.203337,-0.612865,0.081226,0.056742,-0.792290,1.039294,0.530423,-0.366491,0.065473,-0.237612,0.158442,-0.150209,0.431661,-0.040513,-0.230935,-0.160200,-0.337394,-0.298376,0.490410,-0.263810,-0.470601,-0.455652,-0.324356,0.065038,0.101833,1.156643,-0.469528,0.133428,0.004966,0.161232,-0.264912,-0.064826,0.169333,0.562587,0.360603,-0.101510,0.036592,-0.260954,0.341821,-0.377808,-0.092325,-0.580726,-0.388709,-0.335981,0.034052,-0.533777,0.470279,0.055894,0.107385,0.119128,-0.530666,-0.280163,0.793553,-0.065655,0.337378,-0.857522,0.012456,-0.308548,0.040600,0.766034,0.085711,-0.333333,0.065482,0.077028,-0.286710,-0.334196,-0.405004,-0.046666,-0.456010,0.229710,0.011673,0.261482,0.798824,-1.011069,0.307429,-0.352801,-0.800799,0.093715,0.208330,-0.296991,-1.052754,-0.141869,-0.135099,-0.000879,0.427979,0.040190,0.072047,0.970745,-0.574165,-0.065422,0.572420,0.353131,-0.206529,0.324622,-0.059733,0.235203,0.140475,0.099772,0.365848,-0.234155,0.766926,0.341057,0.228057,-0.446337,0.153927,-0.278938,0.470347', '2369613', '35058077', '5403927', '1292444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35158124', '盛夏未来', '剧情', '即将高考的陈辰（张子枫 饰）因发现妈妈（郝蕾 饰）与王叔叔（祖峰 饰）的“外遇”而心情低落，却在这时与校园网红郑宇星（吴磊 饰）因为一个谎言意外相识。两人在未解的青春里，携手面对成长的种种难题，勇敢地面对真实的自己，亦在这个夏天过去后，见证了彼此的成长和蜕变……', '张子枫', '陈正道', 7.1, 228934, 'tt13575838', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2673420377.jpg', 1.6, 6.7, 36.5, 44.7, 10.5, '0.108593,0.153264,-0.815722,0.514579,0.142208,-0.405326,1.009329,0.175809,-0.440504,-0.312973,0.058259,0.595884,-0.497788,0.391621,0.254263,-0.313911,-0.184299,-0.854290,0.154648,0.012726,-0.351478,-0.116075,-0.575623,-0.124693,-0.378251,-0.040592,0.766188,0.240509,-0.008129,1.142090,0.382289,0.233613,-0.288622,0.669834,-0.096879,0.050017,-0.098382,0.514005,-0.356067,-0.143266,0.271831,-0.285467,-0.116394,0.120099,-0.015498,0.476257,0.725577,-0.375832,-0.363822,0.006442,0.377956,-0.343898,-0.048971,0.443120,0.252856,0.145924,0.165105,0.091661,-0.204239,0.039288,-0.109044,0.016092,-0.705343,-0.050851,0.137634,0.262538,-0.547340,0.656619,-0.069541,-0.349900,0.351816,-0.300787,0.180478,0.591431,0.269966,0.554006,-0.500725,-0.109762,-0.247190,0.194278,0.523157,0.169752,-0.252399,0.661619,-0.050755,-0.350504,-0.396472,0.183472,-0.590554,0.140629,0.248063,0.146827,0.018205,0.354771,-0.742179,-0.173351,-0.234596,0.136226,-0.090930,-0.493725,-0.338279,-0.197302,-0.278388,-0.611787,-0.533396,0.141032,-0.064364,-0.201525,0.699734,-1.038589,0.126169,0.178313,0.293924,-0.428295,0.435323,0.299997,0.227657,-0.579082,-0.064866,0.410556,-0.452414,0.306359,-0.064279,0.474980,-0.225829,0.342942,-0.867231,0.513343', '2365260', '25911595', '35030151', '25723081');
