INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35158375', '法比安', '剧情', '1931年的柏林。一个介于分租房和黑社会之间的环境，妓院是艺术家的工作室，纳粹在街上大肆辱骂，巴贝尔斯堡则梦想着制作"心理电影"。生活在澎湃，社会在发酵，在腐蚀。只要还有工作，拥有德国研究博士学位的雅各布·法比安白天写广告文案，晚上就和斯蒂芬·拉布德一起频繁出入城市中比较荒诞的场所。他的朋友-后来承认自己"在生活和职业的课题上"失败了-在谈到共产主义和性的时候，是个有进取心的人，而法比安却依然清醒而疏离。他等待着"体面的胜利"，却没有真正相信它。他对柯内莉亚的爱是唯一让他质疑自己讽刺宿命论的东西。她成了他崩溃生活中的一缕希望。尽管与今天这个被人诟病的世界有很多相似之处，但要让埃里希·凯斯特纳深沉悲凉的自传体小说《法比安》-魏玛共和国最重要的小说之一-走出阴暗的生存环境是一个挑战。多米尼克·格拉夫出色地驾驭了这一挑战。他的风格是微妙的尖锐，冷血的轻快，却又安静忧郁。这部电影就像一个缓慢转动的迪斯科球，讲述了性行为和空冰箱之间的联系，以及幸福梦想的瓦解。', '汤姆·希林', '多米尼克·格拉夫', 8.4, 7588, 'tt13846414', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2686474863.jpg', 0.9, 1.7, 12.8, 43.2, 41.4, '0.477589,0.098078,-0.681723,0.764994,-0.081361,-0.134987,1.035774,0.253828,-0.357873,-0.150722,0.050935,0.865641,-0.106286,0.107323,0.082802,-0.006014,-0.301498,-0.712758,-0.142132,-0.094218,-0.195279,-0.530078,-0.427053,-0.349444,-0.164590,-0.371639,0.634827,0.254992,-0.418214,0.365997,0.153121,0.238445,0.145058,0.553453,-0.243151,-0.214891,0.099840,0.105165,-0.100365,0.040319,0.150016,-0.137359,-0.205365,0.283769,0.098151,0.443765,0.532754,-0.103318,-0.265042,0.169093,0.328739,-0.213430,-0.254774,0.010941,0.165846,-0.137710,0.086775,0.262677,-0.066601,-0.034873,-0.159070,-0.138276,-1.076670,-0.152308,0.180470,0.259957,-0.501074,0.715794,-0.043034,-0.148647,0.053180,-0.196746,0.210856,0.221243,0.216043,0.597922,-0.037272,0.080871,-0.472104,0.233795,0.572810,0.046282,-0.560808,0.414624,-0.696572,-0.345986,-0.173511,-0.364624,-0.538006,-0.332734,0.251509,-0.109735,-0.194602,0.233331,-0.734456,0.258648,0.055255,-0.153836,-0.049056,-0.583851,-0.050944,-0.565575,-0.179165,-0.549041,-0.382965,0.099569,0.077179,-0.361716,0.957153,-0.858405,0.284274,0.739784,0.289938,-0.425727,0.833782,0.236078,-0.137653,-0.161276,0.004613,0.288750,-0.132463,0.173211,0.030986,0.532600,0.1