INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35161256', '夺魂连线', '恐怖', '六名好友在居家隔离期找了一位灵媒，想要通过Zoom进行降灵仪式。然而事情的发展远超他们的想象，一个恶灵似乎回应了他们的召唤，并且侵入了每个人的家中……', '海莉·毕晓普', '罗布·萨维奇', 6.3, 8862, 'tt12749596', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2615652585.jpg', 3.6, 14.9, 50.3, 24.2, 7.1, '0.276444,-0.167442,-0.348661,0.936526,-0.428658,0.051512,0.671961,0.204908,-0.275735,-0.624402,0.149484,0.840200,-0.158032,-0.186908,0.093671,-0.334665,-0.198491,-0.731350,0.128536,-0.026379,-0.502902,-0.075659,-0.123045,-0.435745,-0.039097,-0.618781,0.588798,0.108872,-0.465558,0.236553,-0.041667,0.151778,-0.283837,0.555556,-0.132719,-0.413080,0.671337,0.239412,0.025054,0.605452,-0.604772,-0.192299,-0.027425,0.561798,-0.180375,0.668758,0.570167,-0.515862,-0.272135,0.086889,0.111157,-0.285780,-0.111944,0.586315,0.247761,0.383071,-0.020115,0.090674,-0.384381,0.042167,-0.052828,-0.038190,-1.253079,-0.317301,0.235026,0.005393,-0.540812,0.484722,0.314231,0.133616,-0.137366,-0.141240,0.155154,0.479229,-0.284562,0.372933,-0.144285,-0.342056,-0.839653,0.262288,0.762449,-0.275696,-0.710634,0.530718,-0.080230,-0.739766,-0.657099,0.228346,-0.462650,-0.106494,0.245252,0.403166,-0.382363,0.255583,-0.636846,-0.202222,-0.277278,-0.178014,-0.340663,-0.371658,0.044236,-1.077769,-0.083406,-0.041556,-0.458294,-0.151383,0.054440,-0.173679,1.174624,-0.745841,0.087157,0.650993,0.216002,-0.893898,0.726304,0.236651,0.484159,-0.464078,-0.181284,-0.228014,0.161687,0.542675,0.401323,0.674866,-0.266555,-0.027689,-0.626960,0.607222', '27602116', '3318306', '30163500', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35161768', '夏日友晴天', '喜剧', '故事发生在意大利里维埃拉地区的一个美丽海滨小镇，讲述了男孩卢卡（雅各布·特伦布莱 配音）在令人难忘的夏季，所经历的成长故事，充满了意式冰淇淋、意大利面和无尽的摩托车骑行。卢卡与好友阿贝托（杰克·迪伦·格雷泽 配音）和新朋友茱莉娅（艾玛·伯曼 配音）共赴冒险，但所有的乐趣都受到一个深藏不露的秘密威胁——他们两人是来自水面下另一个世界的海怪。', '雅各布·特伦布莱', '埃里康·卡萨罗萨', 7.3, 109781, 'tt12801262', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2675958609.jpg', 0.1, 2.8, 40.9, 43.3, 13, '0.241322,-0.192462,-0.534157,0.720413,-0.116465,0.038700,0.919638,0.106926,-0.467354,-0.106732,0.115338,1.212901,-0.138827,0.176248,0.473368,0.117381,-0.417504,-0.545559,0.198377,-0.279057,-0.116216,-0.529181,-0.423167,-0.090186,0.022006,-0.199486,0.535737,-0.143185,-0.110770,0.343555,0.263124,0.187008,-0.348272,0.549858,-0.022886,0.266037,0.547110,0.036513,-0.290303,0.245396,-0.226482,0.180132,-0.095694,0.194197,0.028085,0.026590,0.616954,-0.298504,0.070224,-0.123466,0.138315,-0.122012,0.089227,-0.066557,0.120427,-0.070735,0.363804,0.339982,0.077287,-0.224250,0.000328,-0.210253,-0.460675,-0.007916,0.075115,0.295503,-0.399047,0.389219,-0.054820,-0.138168,0.260076,-0.291256,0.188251,0.113837,0.611432,0.517722,-0.043914,0.049852,-0.344186,0.057938,0.596660,0.153842,-0.410151,0.220754,-0.438659,-0.306699,-0.005259,0.157296,-0.799953,0.157631,0.371776,-0.032751,-0.190700,0.687960,-1.057576,0.243885,-0.209016,-0.408130,-0.021152,-0.291906,-0.389009,-0.924831,-0.176936,-0.455334,-0.108106,-0.175156,0.200347,-0.159723,0.879175,-0.606429,0.241813,0.700638,0.032137,-0.041499,0.608540,0.164002,0.386209,-0.180780,0.061469,0.599977,-0.145129,0.054312,-0.094858,0.518459,-0.179463,0.089474,-0.553076,0.521421', '30162520', '26290398', '26611806', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35164328', '扫黑·决战', '剧情', '该片是国内首部以“扫黑除恶”行动为题材、展现全国扫黑办督办案件的影视化作品，讲述某扫黑专案组组长宋一锐带领组员由一起征地案深入调查，突破层层阻挠，与幕后的黑恶势力展开激烈斗争，最终揭开腐败官员利用公职权力充当犯罪保护伞的虚伪面具，将犯罪分子绳之以法的故事。', '姜武', '吕聿来', 6, 167301, 'tt13655044', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2634025511.jpg', 3, 19.4, 55.2, 18.7, 3.7, '0.050353,-0.404350,-0.040025,0.475595,0.208329,0.455105,0.014399,0.326945,-0.321997,-0.173797,0.403424,0.088478,-0.088584,-0.444031,0.156581,-0.550580,-0.542768,-1.073522,-0.297707,0.285073,0.029828,-0.457248,-0.225352,-0.209765,-0.055091,0.057238,1.072370,0.277039,-0.422936,0.244817,0.668670,0.051046,-0.682364,-0.030663,0.369918,-0.801747,0.407833,-0.281530,-0.856640,0.142195,-0.181621,-0.624722,-0.065427,-0.053861,-0.060747,0.261033,0.438920,-0.025123,-0.064891,-0.430016,0.626562,-0.894566,-0.029086,-0.001280,0.516101,0.766175,-0.062093,0.920445,-0.360817,-0.241726,0.000850,-0.654380,-1.050916,-0.464088,0.389084,0.131271,-0.279956,-0.290303,-0.132935,0.633387,0.167031,0.206483,0.101741,0.210315,0.603576,0.234468,0.386303,0.357704,-0.147810,0.607775,0.235031,-0.213133,-0.327514,-0.478033,-0.059250,-0.094807,0.064037,-0.412369,0.362501,-0.214291,-0.175854,-0.344304,0.320544,0.466454,-0.627437,-0.568538,-0.298126,-0.123216,0.094908,-0.109036,0.127685,-0.735923,-0.780691,0.425838,0.098590,-0.146328,0.193936,-0.447425,0.255815,-0.532764,-0.228333,0.612959,0.210645,-0.958014,0.282485,0.414861,0.518789,-0.470707,-0.424169,-0.349764,0.324597,0.354062,-0.164896,-0.072222,-0.137749,-0.642511,0.007795,-0.211332', '26984538', '27073234', '1307914', '26996640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35165314', '明天会好的', '喜剧', '这是一部非常真实的爱情喜剧电影，每个人都能从中找到自己的影子。年近30岁但一事无成的女生萧渝（papi酱 饰）在经历被炒鱿鱼、合租闺蜜突然宣布要抛弃她住进男友房子后，搬进了五环外一个简陋的出租屋内，这是她在这个大城市第九次搬家。迫于生计的萧渝决定去剧组看看机会，为了省钱把房子短租给了一个同样潦倒的小歌手季野（张超 饰）。可是很快萧渝又被剧组辞退，只能提前回京可季野的租期未满，萧渝竟成了沙发客。两人从窘迫到搭伙过日子，生活越来越甜蜜，发生了许多啼笑皆非的事情……生活总是一地鸡毛，但水逆总会过去，相信明天会好的！', '姜逸磊', '袁媛', 4.8, 19801, 'tt10850034', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2638146404.jpg', 21.3, 34.5, 31.9, 9.3, 2.9, '0.184446,0.025788,-0.503835,0.118261,-0.213806,-0.317213,0.743071,0.209764,-0.269604,-0.403394,0.037399,0.616366,-0.091715,0.565127,0.293553,0.086136,-0.100508,-0.426531,0.054564,-0.513466,-0.456234,-0.225804,-0.027967,-0.205716,-0.101996,0.223451,0.504707,0.150570,0.029933,0.167432,0.415478,-0.120614,0.071641,0.561750,-0.446755,0.104819,-0.105261,0.076404,-0.216885,0.170669,0.029023,-0.107306,-0.135309,-0.042647,0.223670,0.232379,0.635088,0.172743,-0.357473,0.321516,0.489405,0.042068,-0.322952,0.060729,0.288474,0.003093,0.320196,-0.048494,-0.455265,0.284270,0.096829,-0.174075,-0.570887,0.264598,0.028591,-0.052078,-0.640766,0.497902,0.169553,-0.048292,-0.035523,-0.602024,0.267521,0.405848,0.251724,0.507753,-0.260447,0.204254,-0.665585,0.221195,0.729614,0.046743,-0.146903,0.455125,-0.177594,-0.099980,0.032441,-0.271107,-0.531397,0.023491,0.278171,-0.212479,-0.320315,-0.007884,-0.577866,-0.123142,-0.163585,-0.235897,0.050077,-0.474064,-0.073863,-0.360765,-0.074105,-0.215508,-0.250808,0.161426,0.065870,-0.341802,0.539922,-0.640011,-0.012224,0.438422,0.294135,-0.547986,0.520968,0.196713,0.423050,0.121085,0.214900,-0.028332,0.033919,0.508128,0.237198,0.455295,-0.073603,-0.212108,-0.615194,0.284664', '21619567', '1299965', '26857170', '2081098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35168646', '外太空的莫扎特', '喜剧', '任大望（黄渤 饰）一心想把喜好天文的儿子任小天（荣梓杉 饰）培养成钢琴演奏家，为此父子争吵不断。一天，神秘外星人莫扎特意外出现，从此，莫扎特帮助任小天开启了和爸爸“斗智斗勇”的生活。令任小天没有想到的是，莫扎特来到地球竟另有任务……', '黄渤', '陈思诚', 4.3, 64545, 'tt13516976', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2875247130.jpg', 30.3, 34.9, 25.1, 6.6, 3.2, '-0.008518,-0.176956,-0.746656,0.360920,-0.173439,-0.134752,0.424134,-0.031012,-0.695911,-0.368658,0.049623,0.725416,-0.373494,0.171357,0.114310,-0.308122,-0.244551,-0.684229,0.109448,-0.037270,-0.202481,-0.579952,0.016237,-0.314568,0.055290,-0.430934,0.296750,-0.172269,-0.139730,0.481610,0.224591,0.477047,-0.410763,0.124952,-0.560446,0.286244,0.242047,0.355643,-0.269588,0.186773,-0.140284,0.224830,0.040467,-0.032724,-0.089552,0.090966,0.650129,-0.138247,-0.239766,-0.124367,0.490073,-0.154519,-0.181545,-0.193262,0.446326,0.291505,0.076814,0.259860,-0.286006,-0.008134,0.196199,-0.237975,-0.521429,0.191779,0.152968,0.107916,-0.456406,0.069160,0.019329,-0.497998,0.149127,-0.164114,0.569137,0.569377,0.775980,0.550536,0.003151,0.339219,-0.350805,0.010502,0.623578,-0.251383,-0.019175,0.417638,0.099616,-0.059507,0.180764,-0.282218,-0.168716,0.141219,0.080218,0.076061,0.066577,0.226029,-0.436755,-0.015716,-0.054631,0.035854,0.357611,-0.420433,-0.292853,-0.485198,-0.089563,0.111031,-0.131097,0.445765,-0.030214,-0.568281,0.775581,-1.072038,0.339266,0.110802,0.352553,-0.718875,0.645146,0.087975,-0.060787,-0.422728,0.340611,0.214162,0.017015,-0.079911,-0.130816,0.173455,0.068647,-0.043276,-0.169555,0.311682', '2052978', '1293265', '35030151', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35172695', '不要忘记我爱你', '剧情', '2022年情人节，用一部电影告白——不要忘记我爱你。星玥（娜扎 饰）爱上了一个特别的人，她的男友陆尧（刘以豪 饰）每天醒来都会忘记昨天发生的一切。昨日的亲密爱人转眼变成陌生人，一次次的重来，是不堪承受的伤痛煎熬，还是人生只如初见的幸运？爱的直觉，是否真的无法隐藏、不会忘记？', '古力娜扎', '黄真真', 3.1, 12049, 'tt17023920', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2868255579.jpg', 58.3, 29.8, 10.2, 1.4, 0.3, '0.013519,-0.441790,-0.548469,0.226101,-0.151669,-0.083123,0.879451,-0.349485,-0.295272,-0.300510,0.130864,0.496366,-0.272449,0.532463,0.242833,0.193423,-0.068367,-0.845496,0.280096,0.160175,-0.172449,-0.345432,-0.041171,-0.111274,0.182041,-0.386420,0.671338,0.280108,-0.181882,0.108985,0.268662,0.088488,0.221994,0.639882,-0.090303,0.080225,-0.169308,0.274445,-0.227197,-0.044773,0.270283,-0.173865,0.105252,0.447873,-0.252362,0.087544,0.623591,-0.376758,-0.600452,0.069543,0.736492,-0.365470,0.006771,-0.017202,-0.279941,0.002627,0.158207,0.253231,-0.171217,-0.005262,0.141018,0.135992,-0.835597,-0.033508,0.279156,0.091729,-0.255934,0.568462,-0.291761,0.530855,0.114110,-0.303786,0.145078,0.050358,0.337524,0.331792,-0.298775,-0.058900,-0.462954,0.446055,1.288542,0.041576,-0.352291,0.802229,-0.161669,0.008085,-0.053135,-0.313517,-0.777786,0.822562,-0.242654,0.193164,-0.524723,0.251704,-0.067859,-0.070179,-0.272870,-0.311907,0.244721,-0.431333,-0.321250,0.096036,-0.240777,-0.652556,-0.510385,0.152658,-0.221033,-0.404667,0.382744,-0.769290,0.409407,0.414706,0.175472,-0.543196,0.859411,0.396609,-0.591073,-0.077156,0.404631,0.781062,-0.181961,-0.192893,0.216136,-0.087534,0.391945,0.479028,-0.441052,0.459622', '1308804', '25858759', '4728584', '25721544');
