INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35183042', '独行月球', '喜剧', '人类为抵御小行星的撞击，拯救地球，在月球部署了月盾计划。陨石提前来袭，全员紧急撤离时，维修工独孤月（沈腾 饰）因为意外，错过了领队马蓝星（马丽 饰）的撤离通知，一个人落在了月球。不料月盾计划失败，独孤月成为了“宇宙最后的人类”，开始了他在月球上破罐子破摔的生活……', '沈腾', '张吃鱼', 6.8, 441177, 'tt14557302', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2876409008.jpg', 3.1, 10.5, 41.1, 32.9, 12.4, '-0.195588,0.316056,-0.713039,0.213618,-0.272867,0.142023,0.134258,0.024207,-0.363246,0.291838,0.417217,0.602356,-0.292703,-0.252272,0.391250,0.147663,-0.424860,-0.309957,0.199507,-0.355838,-0.620953,-0.282774,-0.036668,-0.477207,0.131810,-0.428711,0.951459,0.601640,0.241780,0.263175,-0.362315,-0.134750,-0.097971,0.778475,0.056258,0.176612,-0.211571,-0.143789,-0.293739,0.526454,-0.815550,-0.090158,0.084823,0.206332,-0.082711,0.449792,0.699690,-0.288686,0.162578,-0.533358,0.505672,-0.535662,0.128741,-0.181346,0.668878,0.237326,-0.427519,0.009387,-0.176248,-0.222432,0.391593,-0.447502,-0.265578,0.380154,-0.139891,-0.295231,-0.760399,0.546612,-0.464840,0.472202,-0.002918,-0.227640,0.398799,0.997448,0.275597,0.152932,-0.334088,0.295138,-0.158689,0.270681,0.464601,-0.190487,-0.464622,-0.105629,0.389818,-0.601828,-0.610965,-0.289891,0.257584,-0.323220,0.429604,0.375405,-0.428241,0.159160,-0.384584,0.161429,-0.079081,-0.327803,-0.006883,-0.461831,-0.413378,-1.026540,0.215537,0.046075,-0.207064,0.291396,0.045205,0.143216,0.585254,-0.787671,0.206919,0.631100,0.563208,-0.455143,0.460537,0.010103,-0.091916,-0.289410,0.396961,0.455089,-0.422100,0.813985,0.187534,0.364683,-0.004425,0.257308,-0.211450,0.301525', '2369613', '1300371', '3871833', '3073124');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35184151', '杀手寓言 第二章', '喜剧', '任何目标都能在六秒内解决，有如传说般存在的天才杀手「寓言」（冈田准一 饰），是个让黑社会闻风丧胆的狠角色。因应「老板」（佐藤浩市 饰）命令，他与搭档（木村文乃 饰）乔装兄妹档，并化名「佐藤明」过着普通人生活，更不得在大坂居住的这一年内杀害任何人…。某天，他偶然遇见神祕的轮椅少女（平手友梨奈 饰），以及看似关爱孩子未来的非营利组织创办人宇津帆（堤真一 饰）。种种不寻常的一切，让寓言回想起四年前的暗杀任务。面对风雨欲来的重重危机，寓言能否继续遵守不杀人的命令，守护自己与身边的亲友呢？', '冈田准一', '江口幹', 7.5, 8124, 'tt13017204', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2626807774.jpg', 0.7, 2.9, 32.7, 47.3, 16.4, '-0.019337,-0.132425,-0.414743,0.491175,-0.112637,-0.119399,0.514576,-0.018908,-0.412851,-0.580186,0.268631,0.646487,0.028717,-0.154620,0.174354,-0.102502,-0.184008,-0.452760,-0.266430,-0.281950,-0.241919,-0.322639,-0.141878,-0.198677,-0.153327,-0.062909,0.526554,0.079171,-0.104215,0.308203,0.161404,0.351346,-0.161391,0.164184,-0.246949,-0.237858,-0.099105,0.328218,-0.388476,0.226598,-0.280824,-0.047042,-0.107272,0.364321,-0.089673,0.090871,0.293010,-0.606201,-0.186154,-0.389326,0.023754,-0.353987,-0.206451,0.112022,0.358130,-0.199484,0.253015,0.465619,-0.084149,-0.017381,0.084940,-0.156408,-0.884108,-0.114587,0.122305,0.250759,-0.431890,0.175882,-0.125873,-0.063353,-0.047042,-0.084568,0.116030,0.191760,0.334654,0.160706,-0.423002,-0.041798,-0.511664,0.293175,0.704133,0.219909,-0.072992,0.226363,-0.051024,-0.423453,-0.211099,-0.283249,-0.394443,0.115311,0.007862,-0.019447,-0.209808,0.251351,-0.358939,-0.036867,-0.118911,0.261609,-0.020370,-0.504551,-0.084407,-0.657073,0.205272,-0.270372,-0.438182,0.252850,0.394516,-0.196935,0.621287,-0.981368,0.153910,0.507381,0.335039,-0.350233,0.512228,0.362720,0.096198,-0.195717,-0.051053,0.199848,0.282106,0.472804,-0.227412,0.216363,-0.105707,-0.047006,-0.179032,0.204599', '1793491', '1420088', '4301278', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35192111', '掮客', '剧情', '相铉（宋康昊 饰）经营洗衣店，可惜生意淡静更负债累累。好兄弟东秀（姜栋元 饰）本身是孤儿，为“婴儿暂存箱”机构工作。在一个雨夜，他们竟秘密带走其中一个箱里的男婴。翌日，年轻的母亲文素英（李知恩 饰）却找上门要求领回自己的孩子羽星！本想报警揭发，但素英最终竟同意让两个“中间人”为儿子寻觅更好的父母，并决定跟随两人同行。另一边厢，刑警秀珍（裴斗娜 饰）联同后辈李刑警（李珠英 饰）原来一直跟踪着他们，暗中收集证据，决心拉人定案！剧情由暂存箱里的婴儿引发，牵连周遭5个关键人物，展开一段意想不到的独特旅程，触动最微妙的世故人情。', '宋康昊', '是枝裕和', 6.7, 37536, 'tt13056052', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2876193091.jpg', 1.2, 8.4, 52.3, 30.2, 7.9, '-0.133772,0.033146,-0.407235,0.307257,-0.116283,-0.244922,0.515003,0.223916,-0.579693,-0.608297,0.082327,0.269489,0.108674,-0.034635,0.169884,-0.293606,-0.294289,-0.323258,-0.040454,-0.034457,-0.312819,-0.364633,-0.084908,-0.299595,-0.164851,-0.043039,0.509572,0.162545,-0.001281,0.233589,0.325983,0.098254,-0.475535,0.151264,-0.051326,-0.047351,-0.040994,0.184912,-0.361464,-0.096869,-0.111526,-0.163441,-0.067466,-0.018726,0.127690,0.415136,0.663201,-0.117250,-0.170308,-0.224742,0.139282,-0.092735,-0.179500,-0.266896,0.189045,0.216042,0.354839,0.190011,-0.227536,-0.063654,0.132668,-0.080363,-0.465260,-0.026664,0.609136,0.083439,-0.335620,0.034016,-0.128492,0.312869,-0.092536,-0.350227,-0.062772,0.206165,0.130906,0.254867,-0.084285,0.193859,-0.250798,0.334253,0.216593,-0.213276,0.292919,0.176593,-0.294449,-0.442434,0.277602,-0.010327,-0.225933,0.112567,0.330841,0.006869,0.171231,-0.093357,-0.240159,-0.152123,-0.220871,0.422040,0.113846,-0.526775,0.306317,-0.451009,0.123779,0.097531,-0.169149,0.242897,0.081911,-0.031639,0.611481,-0.092910,0.114883,0.378148,0.230093,-0.697753,0.337732,-0.120430,0.371260,-0.670429,-0.101767,0.039822,0.172149,-0.056378,0.042078,-0.041091,-0.081348,-0.323375,-0.026463,-0.359630', '3179758', '1421278', '3670447', '34962956');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35192672', '边缘行者', '动作', '1997年回归前夕，多方势力矛盾激化，暴力事件频发。巨变当前，黑帮龙头林耀昌（任达华 饰）对亲信阿骆（任贤齐 饰）委以帮派重任。多重身份的阿骆在黑白边缘行走，一场除暴行动正悄然掀开反杀的序幕。', '任贤齐', '黄明升', 5, 32405, 'tt18500636', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2871147122.jpg', 10.8, 40.5, 39.5, 7.2, 1.9, '-0.279260,0.342860,-0.440265,0.345457,0.702721,0.377788,0.315299,0.305993,-0.300569,-0.680575,0.232420,-0.194114,-0.232848,0.013719,0.660538,-0.615171,-0.114408,-0.857036,-0.213370,0.174540,-0.454262,-0.166411,-0.552788,-0.429353,-0.190790,-0.198575,0.660172,0.757639,-0.491695,0.491493,0.682298,0.123828,-0.580801,0.707773,0.448521,-0.282549,-0.005284,0.312484,-0.681858,-0.080975,-0.237583,-0.978726,-0.129556,0.005026,0.178164,0.240825,0.690491,-0.598671,0.415284,-0.362214,0.191937,-0.172743,-0.028660,-0.308013,1.069954,-0.207225,-0.201347,0.147831,0.241752,0.087203,0.080515,-0.435969,0.114300,-0.366883,0.390036,0.164656,-0.389368,0.487423,-0.291364,0.397819,-0.298531,-0.057710,-0.081052,0.479330,0.669982,0.201791,0.216819,0.530405,-0.206888,-0.089352,0.735556,0.143682,0.115767,-0.351549,-0.011804,-0.722256,-0.445216,-0.250086,-0.058670,-0.282414,0.779568,-0.466568,0.657056,0.767607,-0.331968,-0.278070,-0.135814,-0.078327,0.114498,0.043628,0.684576,-0.375889,-0.313344,-0.214969,0.265251,0.532133,-0.186809,-0.210036,0.231766,-0.280998,0.132362,0.162903,0.040953,-0.413822,0.072898,0.014894,0.799392,-0.722418,-0.107674,0.147731,0.257065,0.207902,0.322059,-0.056062,-0.435042,0.261385,0.466664,-0.003242', '26357945', '5996801', '26935283', '26852888');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35196097', '关于我妈的一切', '剧情', '妈妈季佩珍（徐帆 饰）是这个家的灵魂所在，她像有分身术一样能照顾到每一个人。在她的面面俱到之下，这个家看上去井然有序，然而事实并非如此。在妈妈季佩珍眼里女儿李小美（张婧仪 饰）永远都是最优秀的，却不知在北京工作生活的她还有另一面。女儿对妈妈的掌控有多抵触，季佩珍更是不了解。医生丈夫李文舫（许亚军 饰）因几年前的一次失误，至今还无法拿起手术刀。婆婆患有阿尔兹海默症，生活都无法自理……就在身为教师的季佩珍刚刚退休，似乎能松一口气多拥有些自己的时间，却被查出了恶性肿瘤四期。如果妈妈只剩下四个月的生命，这家人的生活又该如何继续下去呢？', '徐帆', '赵天宇', 6.3, 54394, 'tt13649566', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2684251260.jpg', 4.3, 17.2, 45.9, 26.1, 6.6, '0.033097,-0.044482,-0.594708,0.281350,-0.449339,-0.400706,0.792429,0.071398,-0.626549,-0.364496,0.244211,0.567922,0.239906,0.386415,-0.215147,0.017375,-0.204245,-0.404695,0.186322,-0.147398,-0.364806,-0.372595,-0.213242,0.022471,-0.076812,-0.215721,0.446993,0.012432,0.073914,-0.098709,-0.020291,0.185419,0.224458,0.317583,-0.503963,0.101260,-0.183683,0.201832,-0.240621,0.141611,0.443660,0.029138,-0.194437,0.273500,0.098107,0.325179,0.577243,-0.039016,-0.328963,-0.090741,0.517275,0.012658,-0.242868,0.003524,0.200845,-0.105359,0.316647,0.069961,-0.282522,0.190588,-0.060443,-0.073053,-0.955544,-0.011475,0.240841,0.304221,-0.710684,0.385742,-0.098311,-0.239906,-0.008946,-0.497673,0.164538,0.412610,-0.050802,0.666014,-0.426308,0.079902,-0.713921,0.219713,0.822660,0.031469,-0.493966,0.535508,-0.334534,-0.331263,-0.078801,-0.573250,-0.579662,0.135453,-0.210207,0.188396,-0.349818,0.123858,-0.072268,0.446457,-0.097869,-0.147622,0.172952,-0.557434,-0.161619,-0.025708,0.008981,-0.568780,-0.452438,0.253700,0.095092,-0.388696,0.781500,-0.885610,0.249898,0.279298,0.341355,-0.554266,0.613022,0.503717,0.125737,-0.181553,-0.032235,0.310395,-0.161683,0.303623,0.065535,0.211482,0.186188,-0.142497,-0.336333,0.393888', '1877596', '1793491', '1308805', '34875369');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35197765', '一江春水', '剧情', '30多岁的蓉姐容颜姣好却一直未婚，靠着洗脚城按摩的工作独自一人在异乡抚养弟弟。叛逆的弟弟无心学业终日和女友静厮混，而此时，姐姐正面临着老板的哄骗利用，和客户田阿姨布置好的滔天陷阱……待风波平息，蓉姐终于守得云开时，静怀孕的消息再度打破蓉姐来之不易的平静生活……', '李妍锡', '高启盛', 7.1, 7821, 'tt15109218', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2824138487.jpg', 0.7, 5.2, 42.6, 42.8, 8.7, '-0.312498,0.038812,-0.564847,0.355253,-0.288959,-0.512516,0.613362,0.569948,-0.391764,-0.533692,-0.114488,0.001009,-0.186964,0.738956,0.444113,0.109297,-0.285457,-0.699322,-0.271390,0.417370,0.026624,-0.227702,0.206346,-0.119186,0.027814,-0.439562,0.650369,0.080148,0.161839,0.204904,0.179233,0.174991,-0.331019,0.281345,-0.016397,-0.184351,-0.357442,0.331348,-0.405760,0.161200,0.172963,-0.462184,-0.025777,-0.103178,0.374878,0.131279,0.747197,-0.134095,-0.288189,0.028843,0.161736,-0.298682,-0.225620,-0.101591,0.244156,-0.375354,0.301363,0.192321,-0.527562,-0.249698,-0.176541,-0.496606,-0.109907,0.183601,0.327250,-0.060332,-0.639988,0.534556,0.151672,0.074742,-0.203883,-0.236486,0.384866,0.700698,-0.093641,0.682920,-0.355163,0.468265,-0.039284,0.142293,0.514215,0.028670,0.147916,0.427764,-0.128255,-0.102682,0.353609,-0.160485,-0.781481,-0.048002,-0.284039,0.129753,-0.233060,0.140985,-0.417554,-0.186394,-0.465415,0.008984,0.235589,-0.613228,-0.137415,-0.514312,-0.266958,-0.239036,-0.296140,0.442730,-0.053405,-0.310136,0.729746,-0.951927,0.356140,0.136342,0.139151,-0.553432,0.476708,-0.003226,0.247021,-0.422848,-0.224238,0.183437,-0.487300,0.127730,0.227630,-0.018636,-0.476863,0.021513,-0.511881,0.174945', '3445516', '1306544', '33218345', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35198827', '当男人恋爱时', '爱情', '当男人恋爱时会是什么样子？以讨债为生的小混混阿成（邱泽 饰）看似凶狠却本性善良，遇到了欠债人的女儿浩婷（许玮甯 饰）后，对浩婷一见钟情的阿成开始变得温柔又幼稚，笨拙地为浩婷打点一切。就在浩婷终于卸下防备接受追求的时候，他们之间却遭遇了接二连三的变故，阿成默默承受着一切。阿成最终也没有忘记告诉浩婷那句藏在心底的表白：第一次见到你，我就喜欢你了。', '邱泽', '殷振豪', 6.3, 98937, 'tt14428606', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2656407373.jpg', 2.7, 14.4, 53.5, 24.8, 4.6, '0.195639,-0.088348,-0.600530,0.264551,-0.507176,-0.361349,0.700418,-0.138386,-0.323026,-0.093763,0.195784,0.362644,-0.250313,0.207593,0.052360,0.131619,-0.118029,-0.580719,-0.091658,0.166313,-0.006806,-0.346113,-0.195369,-0.105212,-0.013122,-0.142883,0.327130,0.109496,-0.259394,0.241982,0.411381,0.010757,0.121887,0.724545,-0.148296,-0.071942,-0.222893,0.398409,0.006637,-0.218936,0.121567,-0.328187,-0.235880,0.476051,-0.096052,0.387276,0.464583,-0.223507,-0.417038,0.244526,0.203114,-0.141897,0.076712,0.212675,0.030042,-0.094978,0.176308,0.091990,-0.156605,-0.212983,-0.001909,0.141208,-0.429976,-0.086693,0.023758,0.125891,-0.634596,0.268354,-0.148106,0.218533,0.278481,-0.562963,-0.021518,0.056497,0.474524,0.517689,-0.134743,-0.066504,-0.195543,0.033122,0.752656,-0.119817,-0.297221,0.508843,-0.251075,-0.109683,0.129756,-0.087271,-0.508016,0.141963,-0.106526,-0.062700,-0.397041,0.423842,-0.145965,-0.147052,0.009901,0.178666,0.040351,-0.587348,-0.114612,-0.146946,-0.153981,-0.416207,-0.541719,0.060265,-0.189559,-0.165167,0.487071,-0.920434,0.367077,0.544279,0.220354,-0.568351,0.272403,0.338756,-0.344345,-0.093867,0.090376,0.170541,-0.151407,-0.004456,0.043745,0.238979,0.137615,0.074321,-0.031388,0.542622', '1308755', '1301022', '1299965', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35198986', '血腥地狱', '惊悚', '一个有着神秘过去的男人逃离了这个国家，逃脱了自己的个人地狱-只是到达了一个更加糟糕得多的地方。', '本·奥图尔', '阿里斯特·格里尔森', 6.9, 13792, 'tt9772374', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2630884254.jpg', 1.7, 7.6, 43.1, 36.9, 10.6, '0.793681,0.210158,-1.033027,0.800630,-0.698389,-0.187073,1.322092,-0.071726,-0.156649,0.080395,0.430117,1.132410,-0.064192,0.345508,-0.027111,0.371033,0.007874,-0.187699,-0.101976,-0.488551,-0.796989,-0.333342,-0.801587,-0.297720,-0.262489,0.028337,0.873482,0.595284,-0.159928,-0.104420,0.001913,-0.225168,0.277305,0.979163,-0.598590,-0.088095,-0.178628,-0.209386,0.318033,0.658717,0.316907,0.067631,-0.389934,0.626738,-0.623770,0.388310,0.345312,-0.450833,-0.545519,0.021718,0.730547,-0.460488,-0.526085,-0.166576,0.050359,-0.585194,-0.113326,-0.377202,-0.315934,0.122383,-0.129755,0.084735,-1.025705,0.247388,-0.079033,0.222672,-0.716537,0.148755,-0.081002,-0.272419,-0.014736,-0.933725,0.371277,0.217624,-0.123732,0.451673,-0.583398,0.020129,-1.105280,-0.051922,1.096309,0.220184,-0.699635,0.144006,-0.158826,-0.725844,-0.653798,-0.407062,-0.365228,-0.006656,0.964624,-0.425158,-0.434038,-0.000705,-0.903832,0.333966,-0.471387,-0.034126,-0.547128,-0.572017,-0.259889,-0.112476,-0.307542,-0.073903,-0.530478,0.197397,0.108799,-0.506003,1.107450,-0.737953,0.001154,1.419255,0.529477,-0.806911,0.600275,-0.006570,0.413770,0.055043,-0.034363,0.447934,0.109464,0.647788,0.150805,0.861221,-0.478000,-0.106304,-0.509438,0.675174', '1867335', '1308784', '26718282', '1294941');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35202363', '新鲜', '喜剧', '诺阿（黛西·埃德加-琼斯 Daisy Edgar-Jones 饰）是一个喜欢通过交友软件来结识新人的女孩，某一日，在进行了一场糟糕的约会之后，诺阿在超市里邂逅了名叫史蒂夫（塞巴斯蒂安·斯坦 Sebastian Stan 饰）的男子，两人交换了联系方式。之后，诺阿和史蒂夫开始了约会，并且最终碰撞出了爱情的火花。虽然诺阿的好友茉莉（乔尼卡·T·吉布斯 Jojo T. Gibbs 饰）并不是非常信任这个凭空出世的男人，但诺阿坚信这一次，自己遇到了真爱。史蒂夫邀请诺阿去旅行，并且将她带到了自己的一幢别墅中，在这幢没有信号的豪宅里，史蒂夫给诺阿下了药，并且囚禁了他。等待着诺阿的，是比死亡更悲惨的命运。©豆瓣', '黛西·埃德加-琼斯', '米米·凯夫', 6.4, 18953, 'tt13403046', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2868322956.jpg', 2.2, 13.3, 55.2, 22.9, 6.4, '0.419625,0.245198,-0.745047,0.640657,0.053392,-0.586922,0.797149,0.213305,-0.057806,-0.232220,0.127066,0.574463,-0.248164,0.309887,0.205258,-0.119370,-0.510005,-0.756335,-0.197655,-0.521919,-0.587384,-0.583352,0.033549,0.046567,-0.068964,-0.288909,0.169764,0.022558,-0.042854,0.096678,0.335871,0.267111,0.242829,0.697706,-0.300985,0.131638,0.373289,-0.048618,-0.406476,0.485988,0.293492,-0.192271,0.235992,0.436271,0.176212,0.300136,0.964557,-0.810526,0.039945,-0.108526,0.388597,0.285432,0.056936,-0.046986,0.211788,-0.179080,-0.000364,-0.067511,-0.266616,-0.129907,0.265405,-0.098896,-0.625067,-0.141429,0.050061,0.162021,-0.651184,0.353935,0.097499,0.300437,-0.109317,-0.200818,0.243394,0.177744,0.424351,0.299121,0.160786,0.110510,-0.411853,0.073083,0.815616,0.013298,0.004138,0.447921,-0.588684,-0.561062,0.114442,0.308416,-0.690614,0.123879,0.716188,-0.263295,0.138359,0.283565,-0.563721,-0.028522,-0.272782,0.173953,-0.032613,-0.325351,-0.179337,-0.817010,-0.039251,-0.275199,-0.052583,0.115991,-0.210319,-0.201284,0.494042,-0.919598,0.106859,0.693670,0.542799,0.017975,0.785486,-0.110428,0.087227,-0.544290,0.173346,0.213953,0.046919,-0.088634,0.397047,0.539337,0.310824,0.017849,-0.360631,0.613256', '3055049', '2032339', '3326747', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35205446', '铁道英雄', '剧情', '抗日战争时期，在日军肆虐横行的鲁南地区，临城枣庄英勇的“铁道队”穿铁轨、扒火车，截取武器和物资，用胆识和智慧与敌人斗争到底，殊死捍卫家园，为抗战胜利作出突出贡献。本片是根据发生在1935年-1945年间，洪振海、王志胜、杜季伟、刘金山等“铁道队”队员的真实事迹改编，将最大限度地还原“铁道队”的英雄故事。', '张涵予', '杨枫', 5.8, 52896, 'tt13859694', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2684720964.jpg', 3.4, 22.9, 55.9, 14.9, 3, '-0.295085,-0.090986,-0.503227,0.525686,0.316822,0.158832,0.140422,-0.256101,-0.317569,0.140487,0.473774,0.447602,0.200005,-0.474748,0.292518,-0.624675,-0.397753,-0.924606,-0.091789,0.221285,-0.242593,-0.357477,-0.315613,-0.098388,0.105252,-0.441898,1.037041,0.252515,-0.380572,0.388524,0.196137,0.285580,-0.001416,-0.058190,-0.161783,-0.111467,0.102884,-0.154524,-0.542997,-0.131034,-0.414639,-0.247043,-0.290996,-0.197083,0.077164,0.036637,0.966657,-0.435983,-0.093554,-0.015853,0.089198,-0.266143,0.206471,-0.046267,0.558225,0.273337,-0.099789,0.600539,0.343610,-0.007945,-0.082996,-0.105169,-0.738429,-0.496466,0.166397,-0.009925,-0.617847,0.599097,-0.178962,0.339533,0.542557,-0.336969,0.285015,0.694028,0.599506,0.389615,-0.266763,-0.108714,-0.455125,0.294464,0.448406,-0.315719,-0.129684,-0.077881,-0.181474,-0.407013,-0.153679,-0.434777,-0.205408,0.062202,-0.200352,-0.381707,0.308233,0.418339,-0.948093,0.098469,0.029750,-0.444498,0.408116,-0.328520,-0.122728,-0.613919,-0.117316,-0.382208,0.058512,0.358432,0.209922,0.022240,0.902820,-0.602694,-0.305946,0.487532,0.046727,-0.389777,0.507812,0.145136,0.094205,-0.255706,0.330864,0.158430,-0.112101,0.490244,0.043287,0.404936,-0.295922,-0.207687,-0.337409,0.276394', '26759820', '1292444', '5403927', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35206186', '诡扯', '喜剧', '影片翻拍自2004年在韩国上映的《时失两公里》，剧情描述黑警锋哥（陈柏霖 饰）要在48小时内找回被兄弟小强（侯彦西 饰）黑吃黑的钻石赃物，他循着手机讯号来到某村庄，却怎么也找不到对方。在诡异气氛下，与徐伯（陈以文 饰）为首的村民，展开一连串心战与斗智，局面陷入混乱时，竟还有女鬼（陈意涵 饰）来捣乱，情节诡谲之余又有许多突如其来的笑点贯穿全片。', '陈柏霖', '许富翔', 6.8, 9808, 'tt15445440', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2678219077.jpg', 2.1, 9.6, 45.2, 33.8, 9.3, '-0.119858,-0.069252,-0.509247,0.363304,0.380083,-0.130017,0.886984,-0.038099,-0.336537,-0.225689,0.326273,0.281942,-0.790213,-0.226588,0.258525,-0.250360,-0.496867,-0.474104,-0.130324,-0.271311,-0.075537,-0.026109,-0.370043,-0.086238,0.073429,-0.047713,0.308782,0.327109,-0.418908,0.108843,0.075711,0.293732,-0.404831,0.469227,-0.014953,0.231016,-0.278900,-0.112497,-0.199223,0.041613,0.152444,-0.614348,-0.441421,-0.086450,-0.173998,0.267860,1.020837,-0.200385,-0.206874,0.342621,0.291350,-0.055476,-0.396959,-0.163099,0.197871,0.022746,0.339888,-0.007458,-0.284773,0.279050,0.175812,-0.113978,-0.270336,0.501547,-0.084447,0.362736,-0.222804,0.188575,-0.324987,-0.065510,0.224905,-0.470244,0.154398,0.212624,0.372144,0.372478,-0.191448,-0.102856,-0.390146,0.169128,0.522381,0.245867,0.019549,0.087312,-0.003145,-0.661374,-0.164899,0.013130,-0.135899,-0.062499,0.504306,-0.185238,0.077478,0.107960,-0.610958,0.011723,0.005718,-0.311238,-0.030628,-0.423934,-0.351070,-0.843156,-0.149592,-0.163345,-0.102624,0.334285,0.156585,0.116408,0.373810,-0.575599,0.123093,0.240504,-0.001006,-0.120683,0.294519,-0.148932,-0.135400,-0.130309,-0.166953,-0.209319,0.044701,0.492415,0.418645,0.174871,-0.313022,-0.147410,-0.373641,0.098531', '10466639', '2159244', '4706257', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35206315', '夏目友人帐：石起和可疑来访者', '动画', '以短篇集的形式，推出两篇人气故事“唤石”与“可疑访客”。讲述天生拥有能够看见妖怪能力的夏目，和强大妖怪“斑”组成跨越人与妖怪的组合，为夏目崭新的高中生涯带来众多不同的邂逅…《唤石》篇夏目在森林中遇见小妖怪－「三美」，据它说，它身负著名为「唤石」的职责，负责将具备神格名叫「岩铁」的妖怪从沉睡中唤醒。不过猫咪老师和妖怪们垂涎任务完成后能得到的美酒奖赏，计画要夺取唤石一职。夏目担心三美，决心出手相助――。《可疑的访客》篇田沼身边出现一位不可思议的客人。每天都会出现在他身边，只跟他说了一些话便离去。夏目得知该位客人的真实身分是妖怪后虽然很担心田沼，但田沼本人却对跟妖怪的交流乐在其中。虽然这妖怪似乎无意作恶，但田沼的身体却日渐虚弱。', '神谷浩史', '大森贵弘', 9, 14418, 'tt13210990', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2630613895.jpg', 0.3, 0.6, 8.3, 30.9, 59.8, '0.147623,0.060873,-0.432661,0.504251,-0.051854,0.033964,0.862230,-0.101060,-0.500874,-0.399833,-0.037417,0.634395,-0.122428,0.138817,0.212630,-0.178812,-0.016917,-0.384548,-0.134747,-0.145001,-0.217398,-0.303033,-0.385600,-0.240684,-0.220107,-0.629427,0.521129,0.065972,-0.393933,0.462626,0.174063,0.308276,-0.232219,0.303704,-0.348815,-0.276746,0.000293,0.278491,-0.054303,0.146272,-0.193804,-0.098863,-0.106382,0.045924,0.045085,0.077059,0.513336,-0.339579,-0.461861,-0.087157,0.137741,-0.191664,0.002819,0.161681,0.414634,0.129546,0.431766,0.061127,0.134801,0.041069,-0.313850,-0.190313,-0.931565,-0.025082,0.190112,0.329552,-0.402432,0.157087,0.134464,-0.088327,0.195368,-0.288041,0.161030,0.153816,0.192838,0.348505,0.045954,0.151354,-0.462029,-0.082826,0.506854,-0.151625,-0.324798,0.303268,-0.102182,-0.633846,-0.015391,-0.206322,-0.121112,0.268431,-0.077973,0.420498,-0.062297,0.083436,-0.621882,-0.111780,-0.051438,-0.048096,-0.117042,-0.448398,-0.165327,-0.341694,-0.116808,-0.328344,-0.310823,0.173159,0.403616,-0.379809,1.013016,-0.898387,0.194341,0.430268,0.358668,-0.598888,0.700589,0.177307,0.111457,-0.356756,-0.299052,0.061645,0.078499,0.229727,0.038594,0.187129,0.083815,-0.146828,-0.589208,0.229121', '24284209', '3005387', '27602116', '1793491');
