INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35211578', '逃避虽可耻但有用 新春特别篇', '剧情', '森山实栗（新垣结衣 饰）和津崎平匡（星野源 饰）之间的事实婚姻愉快而又轻松的进行着，在日常生活的摩擦中，他们逐渐接受了彼此不同的生活步调，关系越来越亲密融洽。在这个节骨眼上，实栗发现自己怀孕了。好不容易适应了“妻子”和“丈夫”的新身份，这对年轻夫妻再度迎来了下一个挑战——成为“父亲”和“母亲”。怀孕带来的不适让实栗和平匡之间屡屡发生摩擦，好在两人都是温柔细腻的人，他们依靠着对彼此的爱携手度过了一道又一道难关。终于，孩子降生了，可与此同时，可怕的肺炎疫情爆发了。为了保证妻儿的安全，平匡将实栗和孩子送回了娘家。©豆瓣', '新垣结衣', '金子文纪', 8.4, 35713, 'tt13761140', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2629717359.jpg', 0.3, 1.5, 15.5, 41.2, 41.5, '0.251442,0.172854,-0.739929,0.546863,-0.094168,-0.127011,0.732457,0.338874,-0.550416,0.073702,0.009641,0.854539,-0.271599,0.255074,0.167011,-0.078884,-0.121262,-0.906705,0.093355,-0.048666,-0.418933,-0.533391,-0.173770,-0.138372,-0.209710,-0.475682,0.461966,0.130335,-0.127804,0.557830,0.160766,0.085748,-0.251028,0.678648,-0.205764,0.180528,-0.086308,0.359894,-0.421928,0.132947,0.164383,-0.297358,0.026025,0.229375,-0.010116,0.432903,0.760196,-0.448233,-0.347611,-0.046271,0.356433,-0.243559,-0.205664,0.333586,0.221487,0.243273,0.191751,0.355390,-0.489552,-0.100542,-0.031123,-0.154627,-0.607651,0.195891,0.107453,0.051721,-0.632836,0.777570,0.133988,-0.374855,0.296765,-0.285141,0.404500,0.905625,0.189657,0.549429,-0.618761,0.286323,-0.183880,-0.111742,0.987904,-0.033440,-0.415455,0.434971,-0.496646,-0.359579,-0.186880,-0.346749,-0.476835,-0.269937,0.280765,0.310218,-0.253598,0.467417,-0.499930,0.124128,-0.113030,-0.048189,0.010872,-0.491977,0.185586,-0.324517,-0.343039,-0.748344,-0.464681,0.293335,-0.126823,-0.466712,0.714225,-0.817278,0.252440,0.561831,0.585036,-0.431557,0.576931,0.366039,0.415104,-0.273832,-0.034594,-0.000849,-0.216022,0.137760,0.352494,0.439762,-0.257862,0.419332,-0.537270,0.430864', '25721544', '24325798', '1292219', '26809007');
