INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35215390', '狙击手', '剧情', '影片根据抗美援朝战争“冷枪冷炮”运动中神枪手群体事迹改编。1952年冬至1953年初，中国人民志愿军与联合国军在朝鲜战场形成僵持，双方发起了低强度的密集狙击战，史称"冷枪冷炮运动"。在连长（张译 饰）带领下的狙击五班战士枪法过人，成为敌军的心头大患，班长刘文武（章宇 饰）更成为重点狙击对象。为重创狙击五班，敌方调配精英狙击小队，配以最先进的武器装备，更迫使狙击五班战士大永（陈永胜 饰）等人为救同伴进入其设好的险境之地。但正当敌军打响自己如意算盘之时，他们未料到，被他们当作诱饵的侦察兵亮亮（刘奕铁 饰）身上其实隐藏着更大的秘密......', '陈永胜', '张艺谋', 7.7, 294284, 'tt13317320', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2738601191.jpg', 0.5, 3.2, 24, 55.3, 16.9, '-0.058871,-0.363488,-0.636597,0.505888,0.160673,0.320903,0.194266,-0.243873,-0.178417,-0.270165,0.439476,0.262255,0.052232,-0.420853,0.130204,-0.651855,-0.084448,-0.681598,-0.210146,0.102635,-0.399195,-0.273673,-0.472498,-0.164390,0.022251,-0.278200,0.683952,0.085793,-0.458742,0.254801,-0.063446,0.149849,0.239725,0.266973,0.199350,-0.153748,0.041036,-0.439327,-0.348080,0.258488,-0.289818,-0.367271,-0.272831,-0.078604,0.004411,0.196914,0.786569,-0.377728,0.072892,-0.448872,-0.136626,-0.340730,0.036717,-0.127528,0.687451,0.195083,0.242902,-0.212850,0.379003,0.411350,-0.291807,0.019211,-0.540272,0.166430,0.219840,-0.356593,-0.381534,0.305170,-0.315179,0.429338,0.238877,-0.014848,0.227092,0.364800,0.343936,-0.064181,-0.567411,-0.122906,-0.264267,0.184846,0.449599,-0.236343,-0.168200,-0.334363,0.112540,-0.636590,0.120243,-0.274914,-0.035288,0.059355,0.202369,-0.016922,0.343256,0.332119,-0.555018,0.208771,-0.217733,-0.156909,-0.095011,-0.224506,-0.015281,-0.745218,0.087953,-0.181961,-0.203161,0.545932,0.004098,0.029013,0.815003,-0.666828,-0.183986,0.225162,0.398695,-0.315088,0.271566,0.036635,0.301656,-0.147375,-0.064282,0.025402,0.051543,0.208384,0.229078,0.229459,-0.402246,-0.404765,-0.076247,0.019961', '25863940', '2369613', '25912924', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35225280', '中国飞侠', '剧情', '李安全是一位外卖员，他期望用自己的努力让妻子和女儿在北京过上体面生活。但却接连遭遇打击：女儿重病，需要一笔高额手术费；夫妻不睦，妻子断然离开；偷着去干代驾，又撞了豪车……一个外乡人，如何在北京站稳脚跟？一个中年人，如何用信念征服现实？一个好人，如何在世俗和偏见中坚守善良本真？李安全用行动向我们呈现了生命的硬度！', '许君聪', '陈静', 5.9, 9018, '', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2628416332.jpg', 7.6, 24.2, 44.2, 16.3, 7.6, '-0.334055,0.374759,-0.565690,0.724925,-0.570467,-0.603573,0.901126,0.190164,-0.143723,-0.175179,0.220228,0.539254,0.444616,0.308188,-0.047339,-0.015204,-0.079057,-0.303813,0.252266,-0.086458,-0.471428,-0.390834,-0.202911,-0.306855,-0.131008,0.107730,0.509941,0.178561,-0.199995,-0.043715,0.299905,0.132976,-0.105672,0.523350,-0.333836,-0.161498,-0.135296,0.231170,-0.517135,0.232795,0.286590,-0.372080,-0.093951,0.055493,-0.026674,0.276615,0.743511,-0.104912,-0.304349,-0.137681,0.273118,-0.139911,-0.017662,0.419254,-0.063690,-0.065447,-0.085797,-0.311608,-0.170436,-0.231638,-0.041345,-0.087610,-0.581825,-0.543315,0.053834,-0.019000,-1.070130,0.382543,-0.240863,-0.105709,-0.259423,-0.488359,0.168417,0.463008,0.285796,0.565757,-0.436198,0.360423,-0.520013,0.129204,1.010767,0.164147,-0.175139,0.044591,-0.465754,-0.461998,0.126119,-0.408421,-0.815469,-0.166526,0.289141,-0.316063,0.055880,-0.124127,-0.271091,-0.011920,-0.294161,0.005671,0.097519,-0.581549,0.189566,-0.187646,0.208608,-0.505482,-0.551337,0.024032,0.276830,-0.389559,0.936510,-0.379195,0.075150,0.749423,0.674016,-0.790485,0.753519,0.219422,0.353437,-0.338978,0.024352,0.198957,0.165189,0.170177,0.190876,-0.032272,-0.170421,0.342499,-0.129093,0.475927', '1297606', '1291565', '1877596', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35225859', '小妈妈', '剧情', '母亲的身影，总是这麽近，又那麽远。外婆去世，八岁的奈莉随妈妈回旧居收拾，但大人哀伤的世界却容不下孩子走进。与爸爸相依的奈莉独自走到森林寻找妈妈儿时搭建的树屋，遇上同龄的玛莉安，名字跟母亲一样，两人开展了一段短暂而亲密的友谊。继《燃烧女子的肖像》（2019）后，瑟琳·席安玛以细腻的女性触觉，潜入小孩敏感而脆弱的内心，在如幻似真的童梦里任时空暗换，与新相识相知相遇，分享悲喜哀乐，实现每个孩子心里都曾有过的美丽童话。如何去爱那个不完美的人生。', '约瑟芬·桑兹', '瑟琳·席安玛', 7.9, 13282, 'tt13204490', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2677331311.jpg', 0.4, 2, 23.4, 48.4, 25.8, '0.197800,-0.159361,-0.969517,0.499431,-0.299675,-0.571907,1.083009,0.055560,-0.413900,-0.042825,-0.099240,0.808428,-0.087261,0.670062,0.064747,0.196930,-0.102808,-0.628892,-0.003229,-0.266208,-0.176653,-0.384200,-0.112725,-0.167119,0.160450,-0.287651,0.658389,0.072774,-0.031783,0.583209,0.028204,-0.122114,-0.688608,0.300475,-0.459988,0.112476,-0.143301,0.694760,-0.547235,-0.066647,0.068077,0.242649,-0.160413,-0.276199,-0.209089,0.167993,0.707102,-0.364897,-0.288555,0.199799,0.547438,0.029701,0.031525,0.053457,0.065335,0.138447,0.160210,0.143907,-0.199832,-0.040745,-0.268551,-0.154943,-0.361882,0.199734,0.222104,0.065077,-0.573184,0.325675,0.048448,-0.204587,0.333305,-0.415867,0.310714,0.317523,0.067713,0.860421,-0.289385,0.151623,-0.190875,0.077787,1.001320,0.025248,-0.301459,0.404509,-0.208305,-0.273602,0.132556,-0.170792,-0.398002,0.163437,-0.077351,0.147274,-0.137596,0.338095,-0.531878,0.204369,-0.239287,0.334219,0.293823,-0.704949,-0.213864,-0.272402,-0.306998,-0.562344,-0.339907,0.111424,0.077489,-0.313231,0.781899,-0.816355,0.502199,0.489579,0.403259,-0.438803,0.778792,0.147848,0.085812,-0.254186,0.312868,0.780450,-0.177159,0.064646,-0.077994,0.263646,-0.201946,0.508789,-0.855661,0.258177', '1291835', '1296534', '2081098', '25858759');
