INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35231379', '浴血无名川', '历史', '影片讲述了抗美援朝战争时期，我国志愿军三排排长孟大关（任天野 饰）临危受命，带领小队前去解救被困敌后的侦察排，经历了一系列艰难险阻，三排与“杜神枪”杜川（李东学 饰）带领的侦察排成功汇合。为了避免大部队更大伤亡，孟大关与杜川在危急关头果断决定困死无法补充供给的敌方重炮营，一次次小规模战斗在这个无名水川暗暗展开……', '李东学', '翌翔', 6.1, 5885, '', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2659737720.jpg', 4.5, 17.5, 53.1, 19.2, 5.6, '-0.261847,-0.042817,-0.960506,0.763069,0.453062,0.054624,0.341887,-0.257818,-0.170395,-0.233175,0.253620,0.234891,0.173487,0.025330,0.247538,-0.946116,-0.005724,-0.742062,-0.263113,0.276979,-0.650100,-0.430063,0.081841,-0.467646,0.061999,-0.116384,0.590180,0.468298,-0.329067,0.465249,0.227555,0.657598,-0.115814,0.325297,0.155565,0.292799,0.042878,-0.518027,-0.366910,0.239595,-0.307865,-0.322962,-0.224822,0.083168,0.407106,0.156454,0.963871,-0.316691,-0.123672,0.109683,-0.115887,-0.274486,0.174579,-0.159126,0.607247,0.270164,-0.186141,-0.142268,-0.021094,0.434938,-0.278696,-0.445739,-0.526781,-0.130807,-0.104516,-0.589057,-0.883691,0.111719,0.016901,0.557773,0.342462,-0.016709,-0.085560,1.140768,0.642077,-0.394769,-0.401916,-0.145668,-0.405094,0.361780,0.440384,-0.202782,-0.064601,-0.209979,0.201548,-0.345250,-0.401980,-0.244792,-0.003333,0.055675,0.429954,0.102561,0.320528,0.210703,-0.504529,0.100982,-0.315043,-0.268527,-0.017491,-0.003189,0.198076,-1.006344,-0.140088,-0.232394,-0.182378,0.833117,-0.174868,0.024454,0.685713,-0.276402,-0.196725,0.045383,0.008430,-0.691098,0.187735,0.375619,0.243993,-0.000510,0.664479,0.340464,-0.191178,0.449307,0.712130,0.225545,-0.476538,0.106491,-0.171056,-0.019439', '1464618', '35058077', '1424551', '1424552');
