INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35234581', '大话西游：缘起', '喜剧', '大闹天宫的五百年前，佛祖座前的灯芯紫霞（马心瑞 饰）即将燃尽，只有找到点灯人拔出宝剑方能化解。紫霞借助月光宝盒看到她的点灯人是五百年后大闹天宫的齐天大圣！但这一世他只是一位名叫至尊宝（吴昊宸 饰）的普通人，并准备继承父亲（吴孟达 饰）的面馆。一世点灯，三世结缘，紫霞命运几何？至尊宝是那个意中人吗？', '吴昊宸', '董伟', 5.8, 9440, '大话西游之缘起', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2867706736.jpg', 9.3, 19.2, 50.2, 16.8, 4.5, '-0.188861,0.306470,-0.535916,0.502856,-0.529261,-0.254387,0.481168,-0.007440,-0.469691,-0.370367,0.198558,0.678265,-0.090859,0.183959,-0.070694,0.387027,0.155203,-0.489698,0.340830,-0.060998,-0.241883,-0.194902,-0.363454,-0.013882,-0.067055,-0.153848,0.769981,0.232669,0.203588,0.202519,0.202345,-0.205305,0.060426,0.131440,-0.483710,0.215902,-0.437330,0.388607,-0.057601,0.201533,-0.124921,-0.305735,-0.198008,0.105442,-0.412185,0.372463,0.108626,-0.490322,-0.055804,-0.240457,0.367573,0.018313,-0.241145,-0.001881,0.069036,-0.137087,-0.133264,0.251445,-0.104550,0.056236,0.013310,-0.200953,-0.548091,-0.073266,0.040577,-0.114796,-0.533613,0.433561,0.005180,-0.010963,-0.161258,-0.226177,0.258598,-0.034318,0.201602,0.207820,-0.495824,-0.569066,-0.871015,0.519588,0.325290,-0.341539,0.090720,0.830473,0.217147,-0.240547,-0.286592,-0.010024,-0.161540,0.188042,0.367601,0.173758,0.218220,-0.330013,-0.363183,-0.261377,-0.269573,0.312620,0.128169,-0.159082,-0.007806,-0.552337,0.004607,-0.226967,-0.333786,-0.158510,0.351005,-0.459853,0.604820,-0.499008,0.390463,0.249477,-0.148498,-0.239990,1.031741,0.060596,0.296259,-0.293156,-0.221637,0.523726,-0.099163,0.285440,-0.060581,-0.097284,0.056452,0.169814,-0.372446,0.284673', '25876760', '3055049', '2046839', '1307200');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35235502', '驾驶我的车', '剧情', '中年舞台剧演员家福撞破了身为编剧的妻子音的一次出轨，然而，他安静地关门悄然离开，仿佛什么都没发生过一样，一如往常与妻子融洽且恩爱地生活在一起。直到妻子去世，家福都没能对妻子坦诚，这变成他的心结。随后，尚未从悲伤中走出来的家福开始准备《万尼亚舅舅》的话剧演出，准备把自己沉 浸在工作里。不同国籍的演员们在家福的指导下，以各自的母语反复研读剧本，还加入了手语的表达，感人深切。剧场为家福雇佣了一位女性司机渡利，每天接送家福前往排练场地。渡利性格沉默，但车技高超。在相处中，家福开始逐渐和渡利交流自己的内心世界，渡利心中也有一段不愿面对的秘密往事，两人的创伤在最后的返乡之旅中坦然拨开，彼此的相拥与宽慰使尘封的往事得以重新审视，一丝慰藉与释怀在心中升腾。', '西岛秀俊', '滨口龙介', 7.9, 89451, 'tt14039582', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2639821491.jpg', 0.7, 2.8, 23.7, 48.2, 24.7, '0.352216,-0.000092,-0.746431,0.616817,-0.047020,-0.469835,0.875546,0.108494,-0.498494,-0.208117,0.194589,0.818391,-0.342586,0.449737,0.251706,-0.226595,-0.519117,-1.011218,-0.227480,-0.086208,-0.003991,-0.483603,-0.231695,0.067284,-0.258765,-0.139789,0.559224,0.119048,-0.012687,0.654604,0.125113,0.087493,-0.159939,0.378345,-0.221353,0.013825,-0.135469,0.315155,-0.365563,-0.115018,0.332418,-0.221780,-0.363502,0.047323,0.139643,0.422012,0.830098,-0.110398,-0.202441,0.332690,0.192883,-0.106554,-0.059730,0.332156,0.090994,0.467265,0.218632,0.399246,-0.252333,0.136927,-0.355549,0.163932,-0.559637,0.076660,0.150889,0.122170,-0.717106,0.538244,0.021402,-0.130231,0.054500,-0.371785,0.302043,0.360999,0.240699,0.660457,-0.208531,0.187591,-0.164947,0.286343,0.720870,0.125711,-0.199247,0.554770,-0.287122,-0.369516,-0.025057,-0.062296,-0.453929,-0.356674,0.018517,0.333375,-0.243772,0.300994,-0.602426,-0.019282,-0.235211,-0.100324,0.031225,-0.533757,-0.036564,-0.660573,-0.280429,-0.548682,-0.230932,0.073470,-0.021391,-0.213052,0.772939,-0.909506,0.238847,0.091142,0.154082,-0.361749,0.636837,0.283107,0.182480,-0.121277,0.122781,0.234523,-0.199915,0.229924,0.172009,0.474116,-0.203778,0.221452,-0.713296,0.336052', '1307146', '3155839', '2365260', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35235813', '祝你好运，里奥·格兰德', '剧情', '一部关于爱、欲、和满足的喜剧片。艾玛·汤普森饰演的55岁寡妇Nancy Stokes迫切渴望冒险、人类联结和性，渴望她人生中第一次很棒的性爱。丈夫Robert给了她住宅、家庭和看起来像样的生活，然而他已经走了，如今Nancy觉得“连有些修女都比我性生活更 丰富”，她一向是行动派，且当过老师，相当有条理，于是她马上开始实施计划：做了一些研究之后，Nancy雇佣了一个20岁出头的性心理治疗师Leo Grande，准备重启对自己身体的认识。', '艾玛·汤普森', '苏菲·海德', 8.2, 69727, 'tt13352968', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2872943472.jpg', 0.4, 1.5, 16.6, 50.2, 31.2, '0.387014,-0.197495,-0.606054,0.522699,-0.388945,-0.372928,0.591168,-0.022505,-0.557885,-0.275289,-0.286482,0.799863,0.002523,0.382187,0.170991,-0.129783,-0.234757,-0.512810,-0.072651,-0.047970,-0.215395,-0.392384,-0.255156,-0.091671,-0.142665,-0.554169,0.576787,-0.081956,-0.147846,0.417829,0.157387,0.080141,0.551078,0.502966,-0.120431,-0.217137,0.104072,-0.092393,-0.109004,0.159040,0.157229,-0.000246,0.027622,0.261635,-0.109427,0.611938,0.480353,-0.169063,-0.582749,-0.232739,0.556742,-0.061302,-0.255389,0.289151,0.018482,0.224463,0.100355,0.167889,-0.047199,-0.097876,-0.184218,-0.452310,-0.987711,0.012988,0.221576,-0.126598,-0.764606,0.096048,-0.120685,0.130222,0.242417,-0.371976,0.032835,0.460373,0.156489,0.405272,-0.192925,-0.054971,-0.363333,0.395521,0.781981,0.037304,-0.233765,0.600412,-0.456866,-0.489451,0.195546,-0.265967,-0.559216,0.106525,-0.035071,-0.001960,-0.233023,-0.058930,-0.431164,0.265315,-0.068191,-0.138506,0.068391,-0.605622,0.101483,-0.412665,-0.449602,-0.614024,-0.286765,-0.258001,0.056205,-0.452218,0.854974,-0.994914,0.025934,0.408017,0.317631,-0.750124,0.648092,0.192153,-0.035498,-0.276789,0.210257,0.166881,-0.333240,0.082852,-0.012673,0.437262,0.132230,-0.189907,-0.486342,0.588929', '1877596', '1793491', '1308805', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35238569', '黑色电话', '恐怖', '故事发生在1978年美国科罗拉多州的一座小镇中，芬尼（梅森·泰晤士 Mason Thames 饰）是生活在那里的一名少年。芬尼有一个妹妹名叫格温（玛德琳·麦格劳 Madeleine McGraw 饰），两人的母亲在早年间去世了，如今，他们兄妹两人和性格暴躁的父亲（杰瑞米·戴维斯 Jeremy Davies 饰）过着相依为命的日子。小镇上接连发生了5起儿童失踪的案件，在犯罪现场均留下了黑色的气球。谁也没有想到，芬尼成为了绑架犯的下一个目标。当芬尼从昏迷中醒来时，发现自己被囚禁在了地下室中，地下室的墙上有一台断了线的古董电话，神奇的是，这台电话竟然响了。电话那头的，是曾经被绑架犯残忍杀害的孩子们，他们决定用他们各自的力量，来帮助芬尼死里逃生。©豆瓣', '梅森·泰晤士', '斯科特·德瑞克森', 6.8, 16479, 'tt7144666', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2687007137.jpg', 1.8, 10.1, 46.5, 31.7, 9.9, '0.444461,-0.056080,-0.834553,0.477510,-0.302424,-0.191801,1.130472,-0.046265,-0.606231,-0.340299,0.243356,0.839506,-0.310599,0.317231,0.177288,0.022361,-0.211712,-0.776633,-0.087884,-0.265932,-0.393344,-0.583472,-0.358558,-0.096573,0.167398,-0.417573,0.147338,-0.158515,0.017290,0.367149,0.342388,0.508785,-0.307372,0.269114,-0.329268,0.286612,0.217918,0.219589,0.046622,0.188258,-0.085220,-0.377955,0.152636,0.023056,0.070281,0.388446,0.586411,-0.217571,-0.181785,-0.197965,0.244465,-0.050993,-0.213501,0.012914,0.681279,0.214825,0.265666,0.198539,-0.450945,-0.269701,0.154663,0.024841,-0.530755,-0.000072,0.036633,0.320822,-0.622000,0.417654,-0.309098,-0.144045,-0.027550,-0.601087,0.513537,0.323929,0.121336,0.490008,-0.153031,-0.049089,-0.741463,0.050517,0.788011,-0.130440,-0.146863,0.245523,-0.127233,-0.289818,0.036835,-0.211439,-0.456887,0.059857,0.530434,-0.140355,-0.500267,0.161851,-0.399268,-0.073867,-0.345487,-0.345498,0.007222,-0.288327,-0.503164,-0.459899,-0.291369,-0.423304,-0.486581,0.191276,-0.282024,-0.118993,0.648972,-0.915722,0.444174,0.369111,0.183591,-0.111562,0.666455,-0.030202,0.170228,0.274887,0.354689,0.157673,0.203961,0.214484,0.167958,0.315463,-0.200985,-0.053634,-0.507349,0.426615', '1296534', '1302384', '1292211', '1308755');
