INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35240920', 'X', '恐怖', '麦克西恩（米娅·高斯 Mia Goth 饰）是一个做梦都想要出名的女孩，可现实是，她沉浸于毒品带来的幻觉和快感之中，并且即将出演一部由她的男友（马丁·亨德森 Martin Henderson 饰）指导的色情片。为了拍摄，麦克西恩和男友、摄影RJ（欧文·坎贝尔 Owen Campbell 饰）、场务洛林（珍娜·奥尔特加 Jenna Ortega 饰），以及另外的一对主演杰克森（卡迪小子 Kid Cudi 饰）、波比（布兰特妮·斯诺 Brittany Snow 饰）驱车来到了一幢地处偏远的宅子处。宅子的所有者是名叫霍华德（史蒂芬·乌瑞 Stephen Ure 饰）的老人，他对于这帮年轻人的到来似乎并不欢迎。尽管如此，影片还是按照计划开拍了，在此过程中，年轻的肉体和浓烈的荷尔蒙似乎唤醒了深藏在霍华德妻子体内的某种欲望。©豆瓣', '米娅·高斯', '缇·威斯特', 5.9, 23009, 'tt13560574', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2871463253.jpg', 5.2, 23.6, 48.8, 17.7, 4.7, '0.370423,0.017577,-0.623320,0.555238,-0.107224,-0.305287,0.959754,0.236345,-0.480234,-0.408071,0.223733,0.583546,-0.167645,0.107387,0.293650,0.299291,-0.474286,-0.458078,-0.129247,-0.000367,-0.054680,-0.401674,-0.461268,-0.169796,0.029357,-0.521628,0.598785,0.057440,-0.146281,0.320514,0.375368,0.451653,0.017634,0.242451,0.016414,0.023814,0.323890,-0.338361,-0.408808,0.206016,0.108631,-0.139065,0.006037,0.230388,0.051636,0.379593,0.540759,-0.167882,0.036761,0.205184,0.237628,-0.057196,0.091444,0.050767,-0.017121,-0.207579,0.408715,0.072637,-0.152734,0.093728,0.082580,-0.309876,-0.677829,0.099226,0.181668,0.226838,-0.327587,0.429656,-0.235492,-0.043839,0.200141,-0.282963,0.013539,0.047539,0.233470,0.456720,-0.158909,-0.143710,-0.357704,0.168386,0.310951,0.003339,-0.109309,0.457885,-0.392375,-0.499491,-0.331921,0.217442,-0.656420,0.032811,0.401850,0.070434,0.049420,0.085263,-0.548405,-0.002779,-0.254604,-0.147702,-0.016720,-0.213777,-0.098891,-0.821183,-0.056020,-0.400762,-0.055936,-0.218170,0.181467,-0.096950,0.480261,-0.726724,0.236360,0.700475,0.012190,-0.106583,0.501577,0.054866,-0.010614,-0.356757,-0.209791,0.197608,-0.054430,-0.001800,-0.004925,0.551232,0.133569,-0.206056,-0.272437,0.684964', '1316693', '1301686', '3005387', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35241052', '解禁男女', '喜剧', '郑智厚（李浚荣 饰）是刚刚专职到公关部的代理，巧合的是，在公关部有一个名叫郑智宥（徐珠贤 饰）的职员，两人的名字竟然意外的相似。因为名字相似，某日，郑智宥误收了寄给郑智厚的包裹，打开之后震惊的发现里面竟然是一条情趣狗链，不过，这两人的关系因为这场社死而意外的变得亲密起来，郑智宥对于郑智厚开始有了别样的感觉。一天，郑智厚向郑智宥提出了请求，希望她能够成为自己的主人，出于对对方的感情，郑智宥答应了这个请求，并且开始了对于BDSM领域的探索，两人定下了为期三个月的契约，在这三个月里，郑智宥将每周对郑智厚进行一次调教活动。©豆瓣', '徐贤', '朴贤真', 6.6, 32708, 'tt15553956', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2851252642.jpg', 2.5, 12, 48.6, 27.4, 9.5, '0.570165,0.199484,-0.753266,0.595297,-0.237292,-0.242157,0.647803,0.191570,-0.884456,-0.087482,0.229916,0.512725,-0.640283,0.009045,0.284828,-0.050869,0.083285,-0.862379,-0.253597,-0.406510,-0.453169,-0.779790,-0.328212,0.160073,-0.183799,-0.371390,0.324186,-0.161576,-0.053032,0.707781,0.556506,0.174448,0.013743,0.577322,0.227017,-0.002321,-0.029371,0.063328,-0.317808,0.179678,0.004500,-0.045133,-0.124781,0.217924,0.096971,0.439490,0.804015,-0.177162,-0.477397,-0.034623,0.430868,0.007154,-0.294086,0.219195,0.146049,0.449331,0.428976,0.363848,-0.316250,-0.130705,0.008954,-0.028102,-0.998023,0.303226,0.031621,0.322806,-0.577995,0.459191,-0.268724,-0.320426,0.032197,-0.558157,0.146490,0.572871,0.368609,0.578746,-0.182690,0.103625,-0.221733,-0.264745,0.748936,-0.082442,-0.520512,0.476510,-0.115364,-0.411177,-0.135795,0.368998,-0.223330,0.315482,0.348210,0.181132,-0.102792,-0.098741,-0.751290,0.008608,-0.061933,-0.156147,0.100008,-0.356661,0.041083,-0.219197,-0.341249,-0.336964,-0.392963,0.035451,0.030307,-0.386627,0.777580,-1.088037,0.305540,0.519056,0.462485,-0.409011,0.595595,0.373895,0.162352,-0.158878,-0.073886,-0.104304,-0.252029,0.141406,0.153634,0.715481,0.086889,-0.316705,-0.580159,0.250668', '35030151', '1301022', '21360412', '35144311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3524289', '病院惊魂', '惊悚', '20世纪五六十年代，慌乱的少女克莉丝汀（艾伯·赫德 Amber Heard 饰）奔走在旷野之上，她点燃了附近的农舍，不过最后还是被警察抓去，继而送进了北湾精神病院。由于克莉丝汀极具攻击性，因此她被安排进了特殊病房，在这里她的自由受到限制，能见到的除了冷冰冰的医生护士，便是隔壁的女孩艾米莉（玛米艾·古默 Mamie Gummer 饰）、柔伊（劳拉·雷赫 Laura-Leigh 饰）、艾瑞丝（琳德赛·方赛卡 Lyndsy Fonseca 饰）等人。从女孩们的口中，克莉丝汀得知神秘的斯金格医生（杰拉德·哈瑞斯 Jared Harris 饰）似乎一直在女孩们的身上做某项实验，与此同时，仿佛有一个恐怖的恶灵逡巡在精神病院内，时刻准备夺取女孩们的性命……©豆瓣', '安柏·赫德', '约翰·卡朋特', 6.2, 6353, 'tt1369706', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1015647902.jpg', 2.7, 15.8, 54.4, 21.3, 5.9, '0.503563,0.058004,-0.592319,0.200399,-0.201274,-0.166251,0.808377,0.104717,-0.506823,-0.215499,0.442455,0.450566,-0.175032,0.308443,0.230741,0.305560,-0.532723,-0.654942,-0.128256,-0.333804,-0.617445,-0.284137,-0.041457,-0.151429,-0.009674,-0.323968,0.199115,-0.167450,-0.090996,0.248007,0.159481,0.379930,-0.227730,0.366463,-0.064057,0.042404,0.301397,-0.462386,0.161819,0.285266,0.252053,-0.212856,-0.270274,0.045617,0.291276,0.358410,0.617081,-0.311490,0.229018,0.030458,0.141109,0.129396,0.191754,0.053711,0.122260,-0.224363,0.126418,-0.041636,-0.309451,-0.127054,0.344807,-0.080263,-0.343855,0.171838,0.070169,0.229331,-0.460267,0.293071,-0.030485,0.048096,0.210151,-0.197318,0.146168,-0.000924,-0.163141,0.424259,0.007455,0.001680,-0.318121,-0.018398,0.152575,0.088198,-0.280437,0.108759,-0.392108,-0.361865,-0.091872,0.168351,-0.521530,-0.124730,0.667962,0.088062,-0.146695,0.028823,-0.405859,-0.167744,-0.463387,-0.121245,-0.133728,-0.091444,-0.409737,-0.731037,0.238474,-0.073738,-0.192056,0.219202,-0.176803,0.043044,0.557322,-0.711883,0.299016,0.501039,0.269473,0.138877,0.454457,-0.486987,0.189145,-0.003176,-0.199744,0.423462,0.177411,0.370736,0.375323,0.504532,-0.156369,0.057347,-0.436457,0.455508', '1316693', '10466639', '1297659', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35242938', '瀑布', '剧情', '《瀑布》的故事灵感来自导演钟孟宏友人发生的真实故事，以电影《瀑布》中层层暗喻与不停撞击两个女主角的故事为设计概念主轴，就有如海报中的草丛，缓缓持续着围绕这着母女，像是保护他们又像是被团团困住。而她们背后的蓝色帏幕象征未完工且令人期待的未来，蓝色的基底又像是层层水幕，大量的水花如瀑布般向下坠落。', '贾静雯', '钟孟宏', 7.7, 42197, 'tt15119668', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2678037153.jpg', 0.5, 2.8, 27.8, 50.5, 18.4, '0.201452,0.021836,-0.688826,0.848555,0.524814,0.528690,1.265884,0.383904,-0.131326,-0.003482,0.406912,0.238528,-0.575267,0.021768,-0.065655,-0.007394,-0.359589,-1.078096,-0.329752,-0.137679,-0.267955,-0.174848,-0.424261,0.108766,0.086344,-0.231681,0.715781,0.163269,-0.138675,0.289762,0.054351,0.289769,-0.674333,0.224190,-0.161009,-0.073054,-0.474488,0.449478,-0.091784,0.079963,-0.239876,-0.172726,0.056899,-0.032318,-0.537593,0.468611,0.728075,-0.624514,0.265308,-0.226715,0.458697,-0.301746,0.472511,0.163196,0.144205,0.662409,0.593796,0.006267,0.029056,-0.111040,0.317386,-0.627016,-0.317545,-0.086463,0.291155,0.520574,-0.312468,0.013222,0.263623,-0.425992,0.381429,-0.113187,0.099866,-0.363090,0.405387,0.779673,-0.648643,0.010867,-0.526744,0.541428,0.279218,0.347670,-0.678783,0.464158,-0.168202,0.150777,-0.127428,0.177702,-0.057272,-0.305228,0.437639,0.350540,0.049183,0.422962,-0.780484,0.278892,-0.243761,-0.220369,-0.455062,-0.664554,-0.423089,-0.500935,-0.062973,-0.239399,0.242690,0.205126,-0.381240,-0.106303,0.650119,-0.281955,0.309296,0.555765,-0.038828,0.212602,0.435187,-0.082732,0.016277,0.029798,0.208873,-0.100920,-0.081180,0.063119,0.055993,0.389187,-0.206166,0.309004,-0.510597,0.437381', '1467779', '20451118', '1578663', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35242942', '倒霉性爱，发狂黄片', '剧情', '一段视频被病毒式传播，视频中，一男一女戴着面具做爱。不过，这名女子还是被认出来了。更糟的是，她是一名教师，本应当是一个榜样。而且这是在一个后社会主义社会，即将迷失在一个社会网络话语中，其中有治愈洁癖的态度，有伪政治万事通，有神圣沙文主义，有怪诞阴谋论。每个人都有自己的意见。辩论变成了一个法庭，关于双方同意的性、色情等等。拉杜·裘德（Radu Jude）一如既往地致力于创新的电影实验，在这个作品中精心制作了一个聪明的、讽刺性的三部曲：第一部分以不紧不慢的精准镜头对准布加勒斯特街头日常熙攘生活中的疯狂幽默，向我们展示纪录-虚构界面的当代电影的样子。第二部分是一系列平淡无奇的静态影像，旨在作为我们这个时代符号的百科全书。影片的大结局（虽然是开放式的）是在学校举行的讨论，对女主角的存在的理由作出裁决。', '克劳迪娅·耶利米亚', '拉杜·裘德', 7.2, 16944, 'tt14033502', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2638021971.jpg', 2.1, 7.5, 33.9, 41.4, 15.1, '0.443746,0.233245,-0.496070,0.903903,-0.272169,0.317819,0.816818,-0.086005,-0.369901,-0.287390,0.278501,0.813139,-0.305613,0.128878,0.121429,-0.061741,-0.213070,-0.746776,-0.346317,-0.152019,-0.362329,-0.505758,-0.320784,-0.157773,-0.175493,-0.373316,0.623700,0.012284,-0.644895,0.171396,0.431295,0.267734,0.051193,0.137438,-0.340776,-0.266426,0.130930,-0.221237,0.010166,0.316908,0.027126,-0.263113,-0.107420,0.297540,-0.387075,0.479907,0.819805,-0.199448,-0.243214,0.139094,0.864730,-0.246753,-0.386355,0.223414,0.356215,0.059398,0.033947,0.192420,-0.063896,0.144081,-0.051601,-0.169876,-1.166190,-0.342231,0.044032,0.499395,-0.480829,0.539804,0.012260,-0.376538,0.074909,-0.208968,0.273211,0.045705,0.671146,0.539186,0.109798,0.007438,-0.426501,0.288474,0.299708,0.287000,-0.792838,0.620533,-0.398952,-0.566297,-0.114662,-0.188229,-0.372412,-0.095482,0.296545,-0.296752,-0.183025,0.157714,-0.704709,0.226589,0.054236,-0.419947,-0.073473,-0.421611,-0.212451,-0.842318,-0.284562,-0.630066,-0.251382,-0.087096,0.008980,-0.305212,1.183374,-0.790929,0.076959,0.490483,0.014116,-0.490009,0.885217,0.448983,0.082909,-0.116582,-0.105495,-0.103366,0.160584,0.201049,-0.281134,0.616355,0.191357,-0.344117,-0.498513,0.693461', '27602116', '24284209', '2027945', '