INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35245762', '神偷军团', '动作', '本片为《活死人军团》的盛大前传，讲述小镇出身的银行员迪特接受神秘女子的招募，加入一支劫案团队。这个团队的成员全是遭国际刑警通缉的罪犯，目标是攻破欧洲各地最安全的传奇保险箱，迪特就此卷入毕生难遇的刺激冒险。', '马提亚斯·施维赫夫', '马提亚斯·施维赫夫', 6.2, 17154, 'tt13024674', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2704531912.jpg', 3.2, 16.9, 54.4, 19.1, 6.4, '-0.034629,0.069746,-0.324914,0.469543,0.085137,0.405816,0.446676,-0.235989,-0.490037,-0.231904,0.702594,0.817811,0.375758,-0.187162,0.665974,-0.036603,0.148836,-0.519854,-0.384733,-0.346199,-0.291086,-0.150689,-0.304457,-0.376182,0.214944,-0.397299,1.182898,0.549199,-0.716826,0.218340,0.332857,0.657812,-0.443315,0.011077,-0.166516,-0.304729,0.348577,-0.107381,-0.326149,0.215495,-0.789775,0.094461,-0.106406,-0.134049,0.055148,0.171024,0.591880,-0.147888,-0.078666,-0.346842,0.573072,-0.736329,-0.385455,-0.718638,0.652198,0.211602,0.104113,0.238832,0.145330,-0.014949,-0.294982,-0.176371,-1.438151,-0.116080,0.826829,0.078615,-0.537932,0.277815,-0.168720,0.219685,0.047244,0.144980,0.227431,0.623492,0.325418,0.040025,0.274284,0.382580,-0.585549,0.488256,0.700293,-0.433877,-0.323411,-0.364904,-0.284589,-0.504485,0.145738,-0.714669,-0.407599,0.150644,-0.044232,-0.316769,0.155571,0.459519,-0.752414,-0.184528,-0.217146,-0.418683,0.406074,-0.271963,-0.055633,-0.951767,-0.073593,0.380275,0.053716,0.037657,0.105603,-0.020116,0.880270,-0.418929,0.055898,0.852642,0.097813,-0.669450,0.662405,-0.006061,0.406505,-0.252218,-0.191219,0.487158,0.778344,0.303561,-0.344402,0.044463,-0.107229,-0.607136,-0.202673,0.008371', '27073234', '3861846', '1468527', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35250237', '亡命救护车', '动作', '本片翻拍自2005年同名丹麦电影，功勋退伍士兵威尔·夏普（叶海亚·阿卜杜勒-迈丁 饰）为救妻子情急之下找到养兄弟丹尼（杰克·吉伦哈尔 饰）求助，却因此被卷入洛杉矶史上最大金额银行抢劫案。在脱身中出现的致命差池，迫使二人挟持了一辆载有一名垂危警察和一位顶尖急救专家卡姆·汤普森（艾莎·冈萨雷斯 饰）的救护车。在这场持久的高速追逐中，威尔和丹尼极力躲避全城警察的大规模搜捕、保证人质的生命安全、努力不对兄弟拔刀相向，同时完成这场洛杉矶有史以来最疯狂且惊险刺激的逃脱。', '杰克·吉伦哈尔', '迈克尔·贝', 5.6, 25520, 'tt4998632', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2871800734.jpg', 5.7, 27.3, 50.1, 13.9, 3, '-0.010178,-0.091623,-0.392190,0.237892,0.230329,-0.050204,0.641107,-0.200735,-0.240616,-0.223300,0.707624,0.601751,-0.044924,-0.390805,0.525332,-0.203930,-0.284441,-0.551086,0.109882,0.203956,-0.144790,-0.406336,-0.394672,-0.281924,-0.150086,-0.325866,0.598560,0.003200,-0.122942,0.610078,0.268694,0.300946,-0.120145,0.206446,0.307581,0.001199,0.374636,-0.362772,-0.431460,0.475048,-0.114915,-0.463651,-0.110101,-0.061596,0.108163,0.381290,0.575375,-0.135501,0.271698,-0.076385,0.041156,-0.456613,-0.015416,-0.026975,0.074390,-0.156811,0.143534,0.089957,-0.155067,-0.169862,-0.029747,0.035125,-0.648079,0.044599,0.043406,0.090669,-0.552214,0.051810,-0.543050,0.126007,0.126214,-0.160018,0.007902,0.317705,0.074263,0.112082,-0.215464,0.077611,-0.429775,0.066652,0.555882,-0.344166,-0.064359,-0.132150,-0.113364,-0.404584,0.186201,-0.403759,-0.615188,-0.085742,0.469809,-0.138295,0.061355,0.299722,-0.395979,-0.101569,-0.537602,-0.253216,-0.072196,-0.132213,0.082763,-0.784756,0.049364,-0.024379,-0.101611,0.071711,0.089336,-0.198766,0.532825,-0.353304,0.123190,0.504008,0.183534,-0.198799,0.496958,0.177815,0.542996,-0.221140,-0.150838,0.274227,0.402883,0.225432,0.040495,0.085478,-0.079245,-0.213547,-0.015937,0.153333', '3147969', '4014397', '10466639', '2369613');
