INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35256235', '燃野少年的天空', '喜剧', '只身来到海南复读的老狗（彭昱畅 饰），结识了一群臭味相投的“咸鱼少年”，遇见了一群参差不齐的“杂草少女”，缺乏自知之明的他们，要一起参加舞动奇迹大赛。他们迈过偏见与隔阂、战胜自卑和怯懦，放飞青春、肆意起舞，燃过烈日颱风，野遍大街小巷！这个夏天，一起跳舞吧！', '彭昱畅', '张一白', 4.5, 58951, 'tt14866426', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2667843404.jpg', 33.7, 28.3, 24.4, 7.8, 5.9, '0.427786,-0.081907,-0.680282,0.346641,-0.207152,-0.148029,0.611907,0.363902,-0.138261,0.083365,0.195618,0.568736,-0.387359,0.653255,0.207483,-0.505144,-0.045491,-0.669291,0.193557,-0.019366,-0.143093,-0.031888,-0.168554,0.045836,-0.171300,0.107148,0.855019,0.030922,-0.083205,1.412296,0.366939,-0.353038,-0.207107,-0.006726,-0.600612,-0.479717,0.139053,0.528264,-0.260391,0.019574,-0.458712,0.027641,-0.092148,-0.452904,-0.170586,-0.038562,0.696329,0.068549,0.105010,-0.071831,0.322508,-0.353426,0.053944,0.257097,0.323190,-0.137416,0.023768,-0.009664,0.332926,-0.123509,-0.290664,-0.393217,-0.162899,0.182610,0.126074,0.215072,-0.695749,0.389466,0.520012,-0.198138,0.103261,-0.057845,-0.045867,0.106253,0.329771,0.164595,-0.105945,-0.181514,-0.536633,0.151716,0.975749,0.036019,-0.297940,-0.059397,-0.187780,-0.005380,0.019591,-0.005486,-0.316013,-0.176842,-0.004984,-0.488348,-0.102167,0.190694,-1.041362,0.234180,0.031106,0.300727,-0.130070,-0.175819,0.017097,-0.558733,0.011517,-0.419551,-0.478813,0.336856,0.193746,-0.138453,0.621365,-0.572681,0.281858,0.597856,0.390265,-0.447502,0.545273,-0.076057,-0.038450,-0.063928,-0.088419,0.301874,-0.142562,-0.112349,-0.079810,0.624509,-0.361560,0.163244,-0.541757,0.169987', '1451563', '26365262', '25723081', '26469862');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35258381', '天鹅挽歌', '剧情', '《天鹅之歌》以不久的将来为背景，通过卡梅伦的眼睛讲述了一段充满力量和情感的旅程。卡梅伦是一位慈爱的丈夫，被诊断患有绝症，医生向他提出了另一种解决方案，以保护他的家人免受悲痛。当卡梅伦挣扎着是否要改变他的家庭命运时，他学到了比他想象的更多关于生活和爱情的知识。《天鹅之歌》探索了我们将走多远，以及我们愿意牺牲多少，为我们所爱的人创造更幸福的生活。这部苹果原创电影由两次奥斯卡奖得主马赫萨拉·阿里、奥斯卡奖提名人娜奥米·哈里斯和八次奥斯卡奖提名人格伦·克洛斯主演。该片还包括金球奖得主奥克瓦菲娜和金球奖提名人亚当·比奇。《天鹅之歌》由奥斯卡获奖导演本杰明·克利里执导，亚当·舒尔曼、雅各布·柏林、乔纳森·金、丽贝卡·伯克、马赫萨拉·阿里和米米·瓦尔德斯制作。', '马赫沙拉·阿里', '本杰明·克利里', 8.1, 39079, 'tt13207508', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2717809625.jpg', 0.4, 1.6, 20.4, 48.5, 29, '-0.235730,-0.350474,-0.365836,0.751898,0.052497,-0.474510,0.658261,0.175075,-0.220502,-0.094708,0.018288,1.015891,-0.215566,0.235951,0.366986,-0.041947,-0.631009,-0.514706,0.188902,-0.038554,-0.029620,-0.566704,-0.158573,-0.213211,-0.144172,-0.438742,0.724610,-0.316806,-0.047768,0.304393,0.276354,0.110863,0.085110,0.014008,0.079725,0.164422,0.267579,-0.152520,-0.520081,0.416052,0.217657,0.048345,-0.321380,0.234309,-0.068276,0.228291,0.433117,-0.216939,0.121173,-0.168884,0.432354,-0.329347,0.191102,0.032298,-0.298376,-0.054056,0.091989,0.311501,-0.047330,-0.012209,0.099384,-0.298456,-0.926031,-0.167365,0.072783,0.290163,-0.439703,0.105325,-0.355633,0.086747,0.307353,-0.020863,-0.056534,0.253931,0.209868,0.305841,-0.324139,-0.092828,-0.513063,0.299219,0.463650,-0.105843,-0.408657,0.235575,-0.269065,-0.590437,-0.159315,-0.190352,-0.647301,0.243852,0.405699,0.028959,0.156660,0.506194,-0.421345,-0.129911,-0.250465,-0.305312,0.033821,-0.288799,0.279711,-0.730345,-0.059016,-0.197342,-0.115842,-0.426289,0.302775,-0.641153,0.858897,-0.357661,0.253685,0.400111,0.548517,-0.237043,0.719219,-0.019662,0.211774,-0.260705,0.041787,0.420074,-0.046340,-0.034757,0.145551,0.315872,0.290563,0.001502,-0.386618,0.618901', '1870681', '1793922', '27602116', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35259282', '援助', '剧情', '莎拉（朱迪·科默 Jodie Comer 饰）从小就成长在否定之中，却从在阳光护理中心做护理员的经历中找到了自己人生的价值和方向。善解人意的她非常擅长同患者沟通，总是能够很容易的就获得患者的信赖。在众多的患者之中，一位名叫托尼（斯蒂芬·格拉汉姆 Stephen Graham 饰）的中年男子让莎拉颇为费心，托尼患有早发型阿兹海默症，还伴随着暴力行为，整个护理中心，只有莎拉一人能够镇得住他。新冠疫情爆发了，医院里的情势发生了翻天覆地的变化，接连不断出现的疫情和意外让莎拉开始怀疑起了自己的能力和选择。当局对于疫情错误的判断也让莎拉开始重新思考起医疗体系的漏洞和脆弱。©豆瓣', '朱迪·科默', '马克·穆登', 7.9, 7097, 'tt13649036', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2687792757.jpg', 0.4, 1.5, 23.3, 52.5, 22.2, '0.282312,0.216295,-0.830259,0.436251,-0.252731,0.007954,0.763939,0.052710,-0.540831,-0.267692,0.209330,0.647411,-0.176079,0.233057,0.430130,0.008976,-0.264829,-0.717476,-0.036380,0.006530,-0.564103,-0.571843,-0.528181,-0.407192,-0.135547,-0.706219,0.350381,0.050118,-0.488976,0.237596,0.130129,0.482658,0.012507,0.527014,-0.121258,-0.164738,-0.045454,-0.126605,-0.244402,0.299554,0.351139,-0.381430,0.173562,0.508328,0.073458,0.479157,0.708658,-0.525871,-0.257153,-0.053594,0.432349,-0.000316,0.071178,0.242518,0.246159,0.034137,0.129064,0.121717,-0.357962,0.267637,-0.061031,-0.031211,-0.905569,-0.089045,0.283700,0.487634,-0.666729,0.230719,0.008659,-0.477264,0.221443,-0.394982,0.055860,0.339837,0.086984,0.589005,-0.367561,-0.171917,-0.411983,-0.015572,0.506889,0.036434,-0.566379,0.318235,-0.561940,-0.557474,-0.107304,-0.090809,-0.295399,-0.109341,0.211345,0.152319,-0.080637,0.273477,-0.330849,0.350243,-0.352979,-0.376147,-0.237673,-0.194198,0.005315,-0.602821,-0.058912,-0.433542,-0.474418,-0.000205,-0.173775,-0.373017,0.634991,-0.912242,-0.007360,0.361532,0.187209,-0.404084,0.273831,0.022722,0.324597,-0.197702,0.028848,0.075898,-0.250272,0.351319,0.012472,0.507420,0.056013,-0.255493,-0.429607,0.506554', '3006892', '1793491', '26787574', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35262731', '浅草小子', '剧情', '传奇喜剧演员兼导演北野武在日本乃至全世界都广为人知，其实这背后有其导师以及友人的功劳。他师从曾叱咤舞台但鲜为人知的喜剧演员深见千三郎，获得了众多同期演员的帮助，并开拓出自己的成名之路，最终却发现获得名气和成果要付出很大代价：代价就是那些曾经帮助他获得成功的人。故事背景设定在 20 世纪 60 年代中期的浅草，那里是东京较为脏乱的地区，北野武为了寻求更好的生活而从大学辍学，在被誉为脱衣舞和喜剧表演名人堂的浅草法兰西座找到了一份工作，并在不久之后成为了传奇喜剧演员深见千三郎的学徒。深见是一位喜剧大师，他的学生包括许多著名的喜剧演员，比如东八郎和萩本钦一，他们对电视表演形式没有兴趣，只信奉现场表演。北野武在深见的教导下努力工作，不断磨练自己的技艺，最终实现了梦想，成为一名成功的喜剧演员。然而，随着家庭电视越来越受欢迎，现场喜剧逐渐式微。', '大泉洋', '剧团一人', 8.3, 17420, 'tt13528562', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2675919720.jpg', 0.3, 1, 16.2, 48.1, 34.4, '-0.116121,0.049781,-0.602510,0.752571,-0.039912,-0.205136,0.473656,0.065238,-0.393230,-0.455758,0.316967,1.015803,0.006405,0.186234,0.298425,-0.353373,-0.146990,-0.773691,0.024814,-0.298596,-0.145679,-0.410634,-0.409795,-0.035720,-0.443210,-0.646724,0.964437,0.195072,-0.412888,0.337220,0.437838,0.097527,0.155533,0.251892,-0.322004,0.022259,0.358480,0.145552,-0.405775,0.141879,-0.020644,-0.260021,-0.352799,-0.027772,-0.006584,0.197763,0.495433,-0.067307,-0.168558,0.178115,0.452102,-0.310301,-0.127214,-0.029169,0.440909,0.021064,0.353081,0.404232,0.087318,0.044135,-0.200694,-0.232516,-1.092096,-0.229891,0.463493,0.177665,-0.599665,0.422915,0.080222,-0.181025,-0.055654,-0.119783,0.087003,0.180144,0.307303,0.301521,-0.212925,0.168785,-0.317985,0.599775,0.734467,0.112001,-0.202992,0.584978,-0.195650,-0.606453,-0.216172,-0.609789,-0.239498,0.111347,0.191820,-0.089185,-0.039750,0.055969,-0.504529,0.129775,0.016817,-0.358574,0.236795,-0.279657,0.027647,-0.693217,-0.196929,-0.394981,0.021667,-0.111707,0.061442,-0.768323,1.265510,-0.941207,-0.027985,0.494620,0.185318,-0.497528,0.889895,0.057422,0.167755,-0.114976,-0.230570,0.183461,-0.199363,0.316424,-0.229089,0.328154,-0.006703,-0.497438,-0.401676,0.486737', '27602116', '25880986', '242842