INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35262994', '铁血战士：猎物', '动作', '本片以300年前的科曼奇族为背景，讲述了一个名叫纳鲁的年轻女子的故事，她是一位凶猛且技艺高超的战士。她在大平原上一些传奇的猎人阴影下长大，所以当危险威胁到她的营地时，她要保护她的族人。当她发现自己面对的猎物是一个高度进化的外星掠食者，且拥有先进的技术武器，一场恶战开始了！', '安伯·明迪桑德', '丹·特拉亨伯格', 6.4, 28228, 'tt11866324', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2876641124.jpg', 3.7, 14.3, 49.1, 25.2, 7.7, '0.382190,0.199743,-0.595466,0.767713,-0.243221,0.039956,0.936910,-0.163847,-0.246520,-0.220507,0.813006,0.869427,0.303805,0.178585,0.015408,0.064156,0.090123,-0.358615,-0.178223,0.015395,-0.646878,-0.071187,-0.772931,-0.244976,0.055018,-0.579455,0.711916,0.078868,-0.453704,0.112209,0.077580,0.235196,0.153715,0.300153,-0.487158,-0.256662,-0.049247,0.001540,0.029987,0.319901,-0.398114,-0.269314,-0.344133,0.189952,-0.278165,0.284527,0.821319,-0.216221,-0.201578,-0.303743,0.349920,-0.298302,0.201143,0.016373,0.557841,-0.127443,-0.021534,-0.072651,0.294798,-0.017176,-0.356289,-0.064748,-1.093160,-0.151770,0.045688,0.067452,-0.832829,0.224548,-0.120814,0.034166,0.111491,-0.269218,0.060415,0.197105,-0.012816,0.429227,-0.147236,0.028741,-0.580277,0.231826,0.727336,-0.074789,-0.400115,0.268677,-0.146460,-0.862806,-0.256115,-0.517660,-0.684751,-0.040997,0.412250,-0.050363,-0.227146,0.265625,-0.834132,0.129962,-0.293783,-0.192575,-0.114575,-0.243100,-0.257047,-0.281632,-0.009911,-0.519983,-0.464920,0.312903,0.151603,-0.320226,1.213854,-0.580993,0.174332,0.822425,0.214008,-0.584550,0.630148,-0.225024,0.154464,-0.068269,-0.042038,0.221906,-0.076801,0.073584,-0.023877,0.466952,-0.078070,-0.077983,-0.502550,0.766360', '24284209', '27602116', '1302661', '1308784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35270213', '万物生灵：2020圣诞特别集', '剧情', '圣诞特别集的故事将从圣诞夜讲起。这是Helen和Hugh婚礼的前一天，James还处于心碎中，试图掩饰自己的痛苦。但斯盖尔谷宅邸正在举行一年一度的圣诞聚会，而James邀请了自己的新女友Connie作为客人。准备工作井然有序地进行着，Tristan用槲寄生装饰了门厅，Hall太 太准备了一桌盛宴，期盼着自己儿子Edward回家过圣诞节。Siegfried对于Dorothy的出现十分欣喜，思索着是否该不再那么小心翼翼了。大家都聚在宅邸里欢庆节日时，James接到了Bert Chapman寻求帮助的电话，他家的狗分娩不顺。James不得不离开聚会，而Helen表示她想一同前去，远离大家对婚礼的讨论，James对此十分意外。来到Chapman家，James需要处理一只卡在产道的小狗。Helen看得出来他十分热爱兽医这个职业。到要离开时，James震惊地发现大雾已经降临，两人被困在了谷地高处，得等到第二天清晨才能离去。James给宅邸打去电话，保证会让Helen在婚礼举行前回到达罗比。与此同时，他纠结于自己能否抑制住对Helen的真实感情。', '尼古拉斯·瑞夫', '安迪·海伊', 8.8, 10138, 'tt12055126', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2634607946.jpg', 0.4, 0.7, 9.6, 39.2, 50.2, '0.184615,0.104432,-0.859728,0.354543,0.142226,-0.166513,0.672250,0.155388,-0.402502,-0.374757,0.063649,0.578410,-0.330311,0.520257,0.615652,-0.199494,-0.420201,-0.496297,-0.125051,-0.136406,-0.361523,-0.327119,0.219061,-0.153665,-0.077330,-0.210233,0.296132,0.248197,-0.004064,0.504871,0.204969,0.216835,-0.000074,0.828890,-0.397531,-0.339593,-0.261557,0.233878,-0.375169,0.323129,0.264594,-0.131148,-0.380249,0.333713,0.419468,0.155042,0.729482,-0.282949,-0.414726,0.066886,0.245381,-0.224191,0.049960,0.395502,0.266821,0.302762,0.184900,0.183539,-0.360609,0.265131,-0.002800,-0.389228,-0.562992,0.259693,-0.083582,0.190893,-0.772317,0.541266,-0.028864,-0.026211,0.259570,-0.570782,0.487546,0.639948,-0.024178,0.507197,-0.116321,0.030139,-0.525113,0.039478,0.772559,-0.001572,0.341643,0.370615,-0.005151,-0.415226,0.250472,0.094881,-0.465618,-0.011596,0.088749,0.313561,-0.199075,0.050017,-0.566145,-0.290175,-0.076394,-0.671702,0.260855,-0.637502,-0.252655,-0.834134,0.026935,-0.017137,-0.292273,0.133504,0.019010,-0.124699,0.432178,-1.285984,0.339705,0.370269,0.335615,-0.323101,0.632099,0.172884,0.151778,-0.179016,-0.116227,0.