INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35275115', '2020去死', '喜剧', '2020：如此[insert dire adjective of choice here]的一年，就连《黑镜》的创作团队也编不出这样的故事，但这并不意味着他们没有可发挥的余地。《再也不见 2020》是一部喜剧，回顾了这可怕的一年，也许一切尚未结束？在这部具有里程碑意义的纪录片式特辑中，一些全球最著名的人物（虚构）采访结合过去 12 个月的真实影像，交汇成一部叙事合唱曲。', '塞缪尔·杰克逊', '阿尔·坎贝尔', 7.3, 20244, 'tt13567480', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2628834126.jpg', 1.1, 4.8, 38.4, 41.6, 14.1, '0.459026,-0.027006,-0.763156,0.888805,0.097232,0.106829,0.782769,-0.545221,-0.472408,-0.358749,-0.076038,0.759706,-0.440837,-0.229109,0.126071,-0.445234,-0.416033,-0.601078,0.099300,-0.466988,0.076006,-0.369854,-0.392781,0.000597,-0.093646,-0.129660,1.204731,0.379921,-0.356431,0.075698,0.336868,-0.102612,0.263518,0.353630,-0.048396,0.274985,-0.205493,0.224602,-0.130530,0.472036,0.128923,-0.331401,-0.252546,0.437627,-0.390339,0.154868,0.550927,-0.476560,-0.365182,0.206044,0.896608,-0.148468,-0.394017,-0.172716,0.333757,-0.117566,0.484532,0.297169,-0.157440,0.168001,-0.158157,-0.181443,-1.356054,0.029751,0.219505,0.278093,-0.432037,0.431770,-0.099914,-0.433289,-0.256177,-0.230833,0.255559,0.352941,0.588237,0.295682,-0.118787,-0.108859,-0.551497,0.846676,0.593715,-0.078395,-1.035555,1.060294,0.111076,-0.645132,-0.681254,-0.577471,-0.233521,0.351655,-0.017645,0.231752,-0.225460,-0.025276,-0.674580,0.162267,0.182379,-0.356830,-0.220454,-0.608654,-0.005460,-0.708295,-0.329620,-0.481117,-0.044888,-0.043759,0.294053,-0.428648,0.804470,-0.802682,0.030977,0.031867,-0.073761,-0.259823,0.825288,0.272103,0.062096,-0.278000,0.070148,0.206316,-0.114983,0.113943,0.113261,0.519155,0.503687,-0.250484,-0.424488,0.777775', '6844861', '26759820', '35360296', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35280911', '角色', '悬疑', '山城圭吾（菅田将晖 饰）一直梦想着能够成为漫画家，创作出脍炙人口的优秀作品。虽然圭吾的画功扎实编剧一流，但因为他本身是老好人的性格，所以一直无法创作出真实有冲击力的反派形象，因此，圭吾的事业总是停滞不前，知道现在依然只是一介名不见经传的漫画助手。一次偶然中，圭吾成为了一场凶杀案的目击者。这特殊的经历改变了圭吾的性格，他决定以案件的犯人为原型，创作名为《34》的原创漫画。没想到，这部漫画一下子就火了，读者们纷纷被漫画中描绘的可怕犯人的形象所折服。但好景不长，没过多久，社会上就出现了以漫画内容为蓝本进行犯罪的模仿犯。©豆瓣', '菅田将晖', '永井聪', 6.6, 12229, 'tt14118266', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2633773335.jpg', 1.6, 10.1, 51.1, 28.6, 8.6, '0.496703,0.175367,-0.187012,0.721602,0.256770,-0.160190,0.361037,-0.168954,-0.760725,-0.590551,0.113794,0.904895,-0.180099,0.315638,-0.147251,-0.169006,-0.329512,-0.670336,-0.290049,-0.042351,0.045287,-0.176427,-0.401418,0.227809,-0.334847,-0.298111,0.930341,0.048789,-0.248326,0.275811,0.312049,0.113668,0.207461,0.326224,0.106398,0.103360,-0.192186,0.185976,-0.039335,0.079279,0.197552,-0.450464,-0.184897,0.124850,-0.398624,0.283502,0.617187,-0.430671,-0.406465,-0.034506,1.066592,-0.307975,-0.051212,-0.011002,0.257105,0.092049,0.227386,0.099934,-0.195865,0.279251,-0.228143,-0.161718,-1.290689,-0.404169,0.419058,0.297500,-0.488789,0.148526,-0.127669,-0.114874,0.009007,-0.414792,-0.137253,-0.223409,0.869452,0.349639,-0.121571,0.047538,-0.250215,0.357991,0.631061,0.113604,-0.634018,0.354248,-0.335524,-0.498531,-0.203920,-0.743130,-0.307204,0.310240,0.027222,0.243733,0.012225,0.157658,-0.532741,-0.148681,0.045925,-0.060565,-0.205913,-0.165829,-0.249961,-0.560788,-0.192300,-0.327745,0.014851,-0.230037,0.176356,-0.733161,1.053681,-0.899271,-0.012364,0.656462,0.102151,-0.377715,0.755449,0.259982,-0.164740,-0.092121,-0.163084,0.011212,-0.166579,0.249845,-0.211341,0.364361,0.203677,-0.668711,-0.467486,0.476442', '27602116', '6844861', '27098364', '24284209');
