INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35284253', '青春变形记', '喜剧', '13岁的女孩小美（姜晋安 配音）成长于一个典型的亚裔家庭之中，家里经营着一间作为旅游景点对外开放的祠堂，祠堂里供奉着家族的祖先。小美的母亲（吴珊卓 Sandra Oh 饰）是一个对孩子关怀备至又略微有些神经质的女人，在母亲面前，小美总是扮演着乖乖女的角色，可实际上，小美和所有的同龄孩子一样，调皮、好动，并且开始对异性产生了兴趣。在学校里，和小美玩的最好的是普利亚（麦特里伊·拉玛克里斯南 Maitreyi Ramakrishnan 配音）、米莉安姆（艾娃·摩士 Ava Morse 配音）和艾比（朴惠仁 配音）三个女孩，她们四人都是当红的偶像歌手团体4*Town的迷妹。一场意外中，小美在巨大的压力之下变身成为了一只小熊猫，就此揭开了隐藏在她家族里的秘密。©豆瓣', '姜晋安', '石之予', 8.2, 252465, 'tt8097030', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2868096837.jpg', 0.5, 1.7, 18.4, 45.4, 34.1, '0.407133,-0.035142,-0.576756,0.724526,-0.235658,-0.051097,0.811512,0.151606,-0.494791,-0.266700,0.049226,0.871231,-0.111316,0.712751,0.127781,0.015815,-0.215142,-0.668841,-0.583633,-0.155050,-0.203248,-0.433667,-0.380631,-0.232045,-0.263533,-0.253026,0.471365,-0.232126,-0.148053,0.321767,0.560831,0.073031,-0.269849,0.250025,-0.140751,0.139629,0.221914,-0.009784,-0.043899,0.150947,-0.057322,-0.118096,-0.053203,0.202165,0.179060,0.277821,0.694608,-0.479408,0.050733,-0.352890,0.275405,0.037177,-0.344603,0.138585,0.385670,-0.097276,0.595137,0.047038,-0.153403,0.073377,0.259520,-0.349768,-0.488578,0.043940,0.401395,0.318465,-0.701883,0.575232,0.098170,-0.133609,0.225300,-0.164898,0.178867,-0.139209,0.161284,0.613499,-0.220871,0.271587,-0.267373,0.036214,0.388675,0.100941,-0.359190,0.279061,-0.350161,-0.420118,-0.075709,-0.159669,-0.799218,-0.112417,0.062642,-0.227941,-0.020752,0.306853,-0.576033,0.134605,-0.197023,-0.009487,-0.064027,-0.386710,-0.109774,-0.512920,0.029060,-0.525763,-0.279846,0.092180,0.038413,-0.341657,0.943186,-0.953162,0.081587,0.424217,0.265262,-0.263513,0.659814,-0.038690,0.430302,-0.269622,-0.296096,0.067239,-0.149687,-0.082826,0.031737,0.563722,-0.360280,-0.099722,-0.217063,0.571191', '1292219', '26348103', '1292720', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35286583', '蜡笔小新：谜团！花之天下春日部学院', '动画', '在好友风间彻（真柴摩利 配音）的邀请之下，野原新之助（小林由美子 配音）、妮妮（林玉绪 配音）、阿呆（佐藤智惠 配音）和正男（一龙斋贞友 配音）来到了名叫“天下春日部学院”的超级精英学校中进行为期一周的体验入学，风间希望自己能够通过这一周的优秀表现来获得这所学校的入学资格。在天下春日部学院里，有一套非常严格的评分系统，每个人所佩戴的徽章严格的监视着所有学生的一言一行，如有不慎就会遭到扣分的处罚。在和不求上进只管捣乱的小新大吵了一架之后，风间跑进了矗立在学校内的钟楼里，第二天，风间被发现晕倒在钟楼里，屁股上有一个印记，等他醒来之后，众人震惊的发现，风间变成了笨蛋。就这样，“吸皮皮鬼”的传闻在校园里流传开来。小新一行人决定调查事件的真相，并且找到让风间恢复原样的方法。©豆瓣', '小林由美子', '高桥涉', 9, 26815, 'tt13642590', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2666651888.jpg', 0.2, 0.8, 8.4, 28.7, 61.8, '0.352331,0.199038,-0.617699,0.481534,-0.226199,-0.069802,0.320067,0.066873,-0.549706,-0.242323,0.154050,0.532139,-0.433382,0.681092,0.343130,0.023678,-0.358893,-0.667468,-0.334202,-0.467588,-0.357072,-0.363303,-0.029872,-0.137037,-0.081277,-0.360897,0.594434,-0.060900,-0.271692,0.400152,0.213765,0.197694,-0.081350,0.161510,-0.127830,0.001281,0.316871,0.158288,0.221030,0.522650,-0.167107,-0.142818,-0.152211,-0.000524,0.204969,0.187571,0.707810,-0.088065,-0.237250,-0.094988,0.577642,-0.181544,-0.268412,0.323699,0.635009,0.159752,0.261204,0.206481,-0.269755,0.302583,-0.139363,-0.101208,-0.501250,-0.244958,0.031659,0.297265,-0.514327,0.533965,-0.015532,-0.311355,0.338327,-0.309551,0.092072,0.239041,0.298955,0.374070,-0.095782,0.080724,-0.368454,-0.006411,0.513608,-0.357759,-0.166515,0.052313,0.212043,-0.474859,0.034552,-0.040503,-0.139688,-0.027368,0.219513,0.047806,-0.166386,-0.236325,-0.511387,0.038668,-0.048986,-0.420558,-0.100365,-0.282580,-0.200647,-0.984110,0.120263,-0.270058,-0.385266,0.339960,0.009654,-0.308796,0.767158,-1.114577,0.156823,0.367067,0.257896,-0.123109,0.475642,0.002872,0.094977,-0.053777,-0.021654,-0.152685,0.301029,0.702814,0.111717,0.636045,-0.125764,-0.310775,-0.561275,0.268954', '1826173', '1316589', '25723905', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35287558', '有答案的男子', '剧情', '维克多自幼和奶奶生活在希腊的海边小镇，奶奶去世后，他决定开车去往德国，开始一段公路旅行。在前往意大利的船上，维克多偶遇英俊、自由、奔放的德国男人马蒂亚斯，二人相互吸引，越走越近。在驱车北上的过程中，马蒂亚斯逼迫维克多走出舒适区，二人因此发生激烈的冲突。当旅行临近结束，他们各自的问题是否能找到答案？', '瓦西里斯·马古里奥蒂斯', '斯特里奥斯·卡米蒂斯', 7.8, 13651, 'tt9320140', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2642244414.jpg', 0.7, 2.9, 26.7, 44.2, 25.6, '0.545922,0.009412,-1.069816,0.242069,0.274234,-0.420140,0.312411,-0.007380,-0.403830,-0.126161,0.118664,0.852505,-0.138694,0.095254,0.683174,-0.131365,-0.679838,-0.349473,0.341569,-0.156298,-0.344123,-0.612032,0.205475,-0.371209,0.027300,-0.231577,0.550510,0.224675,-0.090704,0.571099,0.015264,0.065912,-0.486083,0.528043,-0.441321,0.065373,0.297330,-0.017089,-0.683955,0.456297,0.163666,0.197420,-0.247257,-0.265968,0.252200,-0.008341,0.834761,0.052220,-0.060447,0.170010,0.109926,-0.033243,0.149347,0.045052,0.506585,0.013422,0.074308,0.298980,-0.221651,-0.128109,-0.434880,-0.053965,0.396466,0.330310,-0.020255,0.074714,-0.391203,0.223166,0.142408,-0.140314,0.506062,-0.590815,0.184027,0.733115,0.223945,0.255595,0.153756,0.069861,-0.354998,-0.107968,1.181914,-0.073212,-0.111441,0.065120,-0.022307,-0.197980,0.060709,-0.091583,-0.332190,-0.215000,0.441983,0.062857,-0.047054,0.259557,-0.461533,0.166361,-0.289252,-0.162717,0.310997,-0.304973,-0.047106,-1.142982,0.145741,-0.328574,0.176603,0.186055,-0.318244,0.017063,0.331607,-0.397331,0.362348,0.480980,0.570789,-0.312678,0.615140,0.108295,0.512740,-0.386544,0.144015,0.663931,-0.167576,0.332956,-0.151160,0.241495,-0.204919,0.172527,-0.600117,0.357643', '3871833', '1296339', '3036464', '2079017');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35287908', '雀斑公主', '科幻', '影片讲述着在一个拥有50亿用户的元宇宙U中，每个人都能开启自己的人生。17岁高中生铃，因年幼时母亲离世而变得沉默寡言。她不愿与父亲交流，不愿再开口唱歌，甚至对一直守护自己的阿忍也渐行渐远。为逃离灰色的生活，铃选择进入元宇宙的世界，摇身一变迅速走红成为闪耀的顶流歌姬。此时，她的巨星之路随着“竜”的意外闯入，而演变成一场充满未知的冒险出逃。雀斑公主和神秘“恶竜”的真身有着怎么样的纠葛？他们又该如何用爱和勇气对抗现实的刺痛？', '中村佳穗', '细田守', 6.3, 21676, 'tt13651628', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2878908060.jpg', 2.5, 17.6, 51.6, 21, 7.3, '-0.158612,0.309165,-0.731945,0.787145,-0.263622,-0.185356,0.963540,0.088472,-0.378169,-0.250447,0.003075,0.860191,-0.109804,0.328434,0.227263,-0.026519,0.136801,-0.680742,0.211653,-0.200523,-0.030103,-0.355874,-0.141464,-0.160443,-0.139121,-0.504796,1.070618,0.262910,-0.314588,0.255671,0.397857,0.241589,-0.290525,0.558090,-0.100924,-0.214307,-0.310181,0.313596,-0.289568,0.021084,-0.101984,-0.044881,-0.038273,0.193775,-0.299182,0.171136,0.800445,-0.410800,0.056636,-0.137883,0.483851,-0.261498,-0.268465,0.002658,-0.003197,0.173838,0.123868,0.013097,-0.050239,0.091116,-0.208505,0.101750,-0.770219,0.094300,0.040786,0.216496,-0.496780,0.077589,0.107228,-0.208940,0.133380,-0.143965,0.160509,0.450783,0.286574,0.465469,-0.396352,-0.024307,-0.385443,0.069945,0.895244,-0.057215,-0.399075,0.500279,0.015992,-0.467037,-0.288031,-0.395406,-0.682123,-0.106594,-0.080555,0.178747,-0.049701,0.374431,-0.630732,0.065651,-0.042543,-0.110774,0.219078,-0.602859,-0.053838,-0.327115,-0.210280,-0.419017,-0.299606,0.177106,0.135842,-0.477746,0.886230,-0.867185,0.128185,0.493865,0.500739,-0.656391,0.717977,0.038049,0.088445,-0.390101,0.038460,0.642957,-0.225859,0.210569,-0.136281,0.039376,-0.122352,0.383144,-0.618611,0.416196', '25880986', '30401849', '25721544', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35288767', '革命者', '剧情', '1927年4月26日，距离李大钊被执行绞刑还有38小时。此时，我党各方力量仍在积极组织着对他的营救行动，而敌人也在千方百计对他施以酷刑，但依旧毫无进展。焦灼之时，一个年轻警察进入狱中欲对守常先生施以新刑，而关于守常先生一生的革命回忆，也就此拉开帷幕……', '张颂文', '徐展雄', 7.5, 85200, 'tt14922172', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2666303410.jpg', 1.9, 5.5, 32.2, 38.5, 21.9, '-0.098667,-0.044200,-0.710903,0.399987,-0.039393,-0.148862,0.504942,-0.037517,-0.655396,-0.253550,0.316375,0.424536,-0.087714,-0.046994,0.302052,-0.382211,-0.239050,-0.879218,0.032738,-0.108863,-0.132074,-0.742061,0.072774,-0.058850,-0.213979,-0.385557,0.535355,0.465676,0.210724,0.488421,0.009255,0.179165,-0.001422,0.928704,0.225119,-0.544357,0.100625,-0.357278,-0.445561,0.351500,0.458940,-0.733136,-0.420121,0.032434,-0.369588,0.459848,0.685636,-0.497560,-0.510890,0.013347,0.436693,-0.659362,-0.044493,0.327134,0.497939,0.210327,-0.162012,0.838186,-0.011337,-0.212749,-0.062520,-0.441936,-0.463627,0.174739,-0.069773,0.178680,-0.440233,0.718811,-0.206361,0.380795,0.032665,-0.271357,0.010973,0.774992,0.156840,0.400598,-0.577916,0.013901,-0.296975,-0.014312,0.508698,-0.028199,-0.174454,-0.029647,0.036464,-0.504618,0.159155,-0.383391,-0.317143,-0.205804,0.102687,0.291910,-0.301769,0.151649,-0.354389,0.411757,-0.269180,-0.155950,-0.036378,-0.408189,0.006668,-0.725508,-0.258980,-0.209669,-0.309879,0.226424,0.423732,-0.297801,0.827417,-0.993106,0.388104,0.565328,0.611834,-0.640453,0.658418,0.172081,-0.194038,-0.116096,-0.240899,0.409057,-0.117486,0.491891,0.166676,0.222317,0.137964,0.097690,-0.054758,0.053499', '1301022', '4127270', '1826173', '4739952');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35293160', '在糟糕的日子里', '喜剧', '《在糟糕的日子里》一对出现婚姻问题的夫妇前往一个遥远的小屋重新修好，但他们都有杀害对方的企图。就在他们执行计划前，意外的访客来了，他们面临着更大的危险。', '劳米·拉佩斯', '托米·维尔科拉', 7.5, 20518, 'tt13109952', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2690943591.jpg', 0.7, 3.3, 32.4, 48, 15.6, '0.385546,0.060162,-1.180136,0.611620,-0.059067,-0.076037,1.087706,-0.016242,-0.324910,-0.189824,0.566287,0.684787,0.072749,0.061311,0.257089,-0.000980,-0.400917,-0.585084,0.092174,-0.364672,-0.602584,-0.671216,-0.424017,-0.572517,0.221186,-0.080286,0.383164,0.429367,-0.160871,0.391673,0.061531,-0.180081,-0.259174,0.789654,-0.329630,0.076043,0.208913,0.425373,-0.067933,0.279165,0.148700,-0.186399,-0.280294,0.291495,0.036329,0.764735,0.570119,-0.281883,-0.791409,0.385505,0.142918,-0.476263,-0.080883,0.282879,0.779037,-0.025263,-0.023869,0.272479,-0.505134,0.022874,-0.129102,-0.302773,-1.039731,0.356835,0.052851,0.344236,-0.665371,0.842934,0.048586,-0.093753,0.232070,-0.430967,0.320923,0.831652,0.482367,0.214059,-0.302131,0.034927,-0.622955,-0.039386,1.092772,-0.337791,-0.360618,0.161406,-0.247766,-0.366997,-0.325546,-0.147101,-0.666415,-0.084316,0.605364,-0.094964,-0.476353,0.303913,-0.566407,0.203938,-0.259451,0.024352,-0.133619,-0.129939,0.021676,-0.574470,0.195493,-0.219944,-0.725818,0.479284,0.029145,-0.326906,0.717388,-0.596812,0.349858,0.665222,0.679963,-0.713683,0.800344,0.163066,0.539974,-0.182094,-0.446425,0.028755,-0.181914,0.558085,0.143781,0.235515,-0.117056,-0.037047,-0.501002,0.394130', '1294941', '1306801', '1947080', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3529375', '厉鬼将映', '惊悚', '电影放映员谦（Ter-Chantavit Dhanasevi 饰）因沉迷大麻而陷入经济危机，毒瘾发作之际甚至不惜典当女友诵（Punch-Vorakarn Rojjanavatchra 饰）的手表，为此诵愤然离开。决心洗心革面的谦此时仍在泥潭之中，为了还上欠款，他被黑道人物逼迫盗录还未上映的新片，以谋取不义之财。某晚，谦和好友育在影院盗录一部即将上映的恐怖片《厉鬼》。中途打瞌睡的谦醒来，却发现育已不见踪影，最后竟发现育的尸体出现在影片之中。不久后他得知，影片根据一个真实事件改编，片中死于吊颈的扶桑嫂竟然确有其人。他和诵共同走访案件发生地，却无意中得知了影片拍摄过程中的秘密……©豆瓣', '沃拉甘·罗娜瓦查拉', '索分·沙达菲斯', 7.1, 56734, 'tt1307057', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2526716812.jpg', 1.2, 6.7, 42.7, 36.3, 13.1, '0.006351,0.266089,-0.774856,0.375346,0.690495,-0.222613,0.584301,0.006908,-0.315794,-0.582995,0.225322,0.446208,-0.614780,0.121162,0.064217,-0.169029,-0.357359,-0.906662,-0.227559,-0.004852,-0.236139,0.003021,-0.409416,0.189643,-0.200457,-0.246670,0.692695,0.388198,-0.305280,0.445203,0.263112,0.185539,-0.437968,0.343708,-0.017036,0.180489,-0.060534,0.062236,-0.235061,0.113215,0.261416,-0.713419,-0.217094,0.074783,-0.148689,0.661211,0.887497,-0.261193,-0.263221,0.023089,0.557093,-0.299401,-0.378104,-0.002599,0.364381,0.307876,0.350985,0.321172,-0.306773,0.279571,-0.219638,-0.057592,-0.680830,-0.114179,-0.028369,0.379889,-0.110010,0.219150,-0.137378,0.410670,-0.113125,-0.180225,0.235408,0.085552,0.239970,0.337023,-0.156292,-0.013376,-0.574562,0.436249,0.281435,-0.141532,0.038113,0.618112,0.228238,-0.351292,0.071749,-0.117904,-0.362672,0.205141,0.262019,0.008221,-0.418295,0.194536,-0.305823,-0.131913,-0.393373,-0.024767,-0.024762,0.053586,-0.381013,-0.775831,-0.271416,0.081523,-0.035507,-0.006302,-0.105770,-0.328962,0.289505,-0.551385,0.203511,0.360106,0.131767,-0.325758,0.602077,-0.127525,0.048366,-0.037208,-0.176271,0.290801,0.093066,0.004627,0.065104,-0.189497,-0.230993,-0.259306,-0.463236,0.152468', '20440456', '25723905', '7152895', '1432699');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35294995', '我和我的父辈', '剧情', '继2019年《我和我的祖国》、2020年《我和我的家乡》，国庆三部曲之《我和我的父辈》接棒定档2021年国庆。由吴京、章子怡、徐峥、沈腾导演，“中国电影追梦人”再次集结，以革命、建设、改革开放和新时代为历史坐标, 通过“家与国”的视角描写几代父辈的奋斗经历，讲述中国人的血脉相连和精神传承，再现中国人努力拼搏的时代记忆。', '吴京', '吴京', 6.5, 244075, 'tt15465312', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2683055011.jpg', 2, 11.3, 53.4, 27.5, 5.7, '-0.303799,-0.336458,-0.447893,0.607994,0.237751,-0.403434,0.098935,-0.311771,-0.506311,-0.262427,-0.207965,0.808727,0.147990,0.320779,0.341100,0.018911,-0.306330,-0.926117,0.234482,0.214573,0.099661,-0.052831,-0.255907,-0.263496,-0.130293,-0.439909,0.863671,0.077651,-0.044543,0.323521,0.007008,-0.048352,0.119787,-0.137419,-0.118724,0.247829,-0.105598,0.213805,-0.836604,-0.098097,-0.072545,-0.513454,-0.376039,0.019742,-0.128633,0.182026,0.521597,0.013235,-0.067670,-0.296774,0.499156,-0.346114,-0.400663,-0.232434,-0.042854,0.397185,0.259611,1.073515,0.261809,-0.393831,-0.641247,-0.606502,-0.668836,-0.296285,0.143465,-0.098040,-0.390512,0.642308,-0.079594,0.212930,0.049878,-0.441025,0.254058,0.461695,0.561762,0.648192,-0.391394,-0.088009,-0.032969,1.000984,0.687939,-0.111038,-0.335644,0.297952,0.042771,-0.457221,-0.174479,-0.089186,-0.735199,0.270539,-0.103192,-0.063085,-0.313556,0.563264,-1.019324,0.128603,0.030956,-0.508882,0.562159,-0.321185,0.320148,-0.510451,-0.614093,-0.541209,-0.085327,-0.293508,0.113967,-0.524809,1.287980,-0.659988,0.105814,0.396323,0.439943,-0.802344,0.979762,-0.001515,-0.067434,-0.560502,0.279456,0.378650,-0.405072,0.329804,-0.199186,0.153803,-0.011967,0.073932,-0.519096,0.711769', '34947776', '27602116', '1908036', '26647163');
