INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35303777', '我们的新生活', '剧情', '该片由《云上音乐会》《广场恩仇录》《一路前行》《冷静冷静》《最燃不过夕阳红》五个故事单元组成，讲述新时代平凡人物追求美好生活的奋斗故事。', '李汶翰', '申奥', 4.8, 10317, '我和我的生活', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2668174426.jpg', 18.4, 34.8, 37.4, 7.1, 2.4, '-0.449790,-0.146258,0.221554,0.462308,0.369294,-0.030010,0.269220,0.103845,-0.060673,-0.398559,0.038261,0.126134,0.173751,0.160200,0.708058,-0.124190,-0.270540,-0.154437,0.016925,0.224806,0.422335,-0.476307,0.080155,-0.310398,0.001178,-0.283690,0.701630,0.239824,-0.202716,0.390307,0.651864,-0.034534,-0.650642,-0.552718,-0.141552,-0.132897,0.148919,0.313788,-0.571356,-0.188681,-1.093442,0.052104,-0.413476,-0.145937,-0.193429,-0.080882,0.909927,0.171767,-0.192906,0.000761,0.405909,-0.085423,-0.413269,-0.657946,0.343083,0.787755,0.332444,0.549965,0.821780,0.035140,-0.957146,-0.625733,-0.443893,0.028887,0.129456,0.237801,-0.466045,-0.021122,0.183112,-0.165263,0.210216,-0.107676,0.100898,-0.117329,1.530972,0.373044,0.007104,0.187085,0.327137,0.473826,0.391055,0.093596,-0.691230,0.857457,-0.300863,-0.081735,-0.131268,-0.282697,-0.398912,0.076514,-0.419433,0.049744,0.181782,0.350212,-0.082897,0.324078,0.384663,-0.428176,0.337036,-0.555939,0.006408,-0.858145,-0.022953,0.159563,0.130481,-0.176227,-0.523383,-0.342861,1.203313,-0.018002,0.136001,0.053008,-0.407082,-0.580609,0.550675,0.032046,0.065911,-0.492636,0.923084,0.778907,-0.650316,-0.221349,-1.061160,0.117947,-1.079048,-0.018185,-0.608230,0.907060', '34811098', '30428359', '30488584', '30168032');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35303842', '迷失之城', '喜剧', '洛蕾塔·塞琪（桑德拉·布洛克 饰）是一位才华横溢但与世隔绝的作家。在她的畅销爱情冒险小说里，总会出现许多奇异的地方。而作为本书的封面模特，艾伦（查宁·塔图姆 饰）一生都在致力于展现书中英雄角色“达什”的个人魅力。 ” 在与艾伦一起宣传新书时，洛雷塔被一位古怪的亿万富翁（丹尼尔·雷德克里夫 饰）绑架。这位亿万富翁坚信，洛蕾塔的新书能带领他找到失落古城中的宝藏。 与此同时，艾伦为了证明自己可以成为现实中的英雄，而不仅仅是洛蕾塔虚构的人物，决定前去营救她。这对极不对付的搭档需要共同努力，才能在险恶的丛林中生存下来，并在亿万富翁赶到前找到古老的宝藏。', '桑德拉·布洛克', '艾伦·尼', 5.3, 15477, 'tt13320622', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2876461859.jpg', 5.8, 33.3, 52.8, 6.8, 1.4, '0.230458,0.000498,-0.582694,0.695267,-0.041023,-0.045170,0.772506,-0.087403,-0.458339,-0.405720,0.423813,0.849761,0.052649,0.180384,0.317015,0.100825,-0.388448,-0.601307,-0.017357,-0.409718,-0.262535,-0.406953,-0.764248,-0.263061,-0.272323,-0.412912,0.875028,0.280354,-0.250565,0.224266,0.360557,0.399915,-0.115453,0.201546,-0.297071,-0.246352,0.244557,0.013288,-0.344008,0.335635,-0.193457,-0.126184,-0.137738,0.313678,0.031967,0.089920,0.417871,-0.388193,0.056005,0.307966,0.426131,-0.174254,-0.045960,-0.037204,0.221328,-0.053199,0.320612,0.212517,-0.123911,0.124946,-0.122903,-0.358385,-1.143520,-0.109517,0.253036,0.484272,-0.678461,0.285290,-0.027039,-0.346635,0.117731,-0.228222,0.187541,0.088840,0.392431,0.245235,-0.000002,0.149405,-0.494411,0.299587,0.331607,0.057097,-0.239260,0.425858,-0.205035,-0.489877,-0.073552,-0.165545,-0.659158,0.017265,0.182197,0.053258,-0.022977,0.233834,-0.643662,0.084633,-0.269191,0.007937,-0.098347,-0.492328,-0.272903,-0.496069,-0.231978,-0.040578,0.049323,0.123563,0.196528,-0.638899,0.974662,-0.805024,0.160788,0.542674,-0.001060,-0.404866,0.862825,0.196992,0.085960,-0.272038,-0.222786,0.350609,0.094026,0.148258,-0.307205,0.151792,0.090320,-0.318297,-0.586335,0.774583', '1793491', '25880986', '27602116', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3530403', '云图', '剧情', '《Cloud Atlas》是大卫.米切尔的第三部小说。这本书由六段故事构成，从1840年一位美国人从悉尼旅行到旧金山的日记、二十世纪三十年代初居住在比利时的年轻作曲家、1975年卷入加利福尼亚灾难的年轻记者、当今伦敦出版回忆录的黑道、1984年韩国发生的故事与一个老人叙 述当时在夏威夷的青春自语为终结。 《Cloud Atlas》入围2004年布克奖（Man Booker Prize）©豆瓣', '汤姆·汉克斯', '汤姆·提克威', 8.1, 385474, 'tt1371111', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1719175505.jpg', 0.9, 2.8, 19.9, 42.6, 33.8, '0.054577,-0.319189,-0.396985,0.509322,0.328828,-0.176778,0.670077,-0.202572,-0.490465,-0.510103,0.185813,1.014479,-0.574219,0.429380,0.731251,-0.083805,-0.127468,-0.715896,-0.064685,-0.336881,-0.221034,-0.226826,-0.221607,-0.046906,-0.048365,-0.672891,0.698022,0.307849,-0.306369,0.362271,-0.062871,0.369118,-0.162736,-0.156490,-0.252917,-0.016078,0.224488,0.262009,-0.553329,0.350447,-0.488311,-0.427896,-0.486295,-0.361237,-0.051928,0.090599,0.800577,0.137333,0.051327,0.247498,0.859466,-0.039691,-0.688056,-0.413237,0.506377,0.019119,-0.120383,0.616756,0.085626,-0.083732,-0.498054,-0.545394,-0.425965,0.074669,-0.225645,0.438531,-0.300789,0.791673,-0.289250,0.397520,-0.236299,-0.413978,0.219721,0.361790,-0.117349,0.704798,0.236899,0.330436,-0.486778,0.876599,0.698467,0.024878,-0.496763,0.206017,0.137116,-0.455329,-0.137463,-0.192567,-0.568462,0.428344,0.007985,-0.345922,-0.295747,0.530333,-0.664760,0.030806,0.047149,-0.535618,0.607500,-0.061460,-0.673592,-0.495943,-0.541192,-0.278536,-0.011758,-0.166206,0.310956,-0.297172,1.272297,-0.305704,0.498230,0.699678,-0.021805,-0.242799,1.197637,-0.047777,-0.098027,-0.330625,0.054667,0.531810,-0.176034,-0.040821,-0.299052,0.191403,-0.138259,-0.525203,-0.297458,0.354724', '1908036', '27602116', '26647163', '3448362');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35307456', '穿过寒冬拥抱你', '剧情', '2020年1月23日，农历腊月二十九，武汉宣布封城。本片聚焦这一特殊时刻，以温情和治愈为基调，刻画了普通市民守望相助、真挚动人的爱情群像。快递员阿勇（黄渤 饰），骑手武哥（贾玲 饰），钢琴老师叶子扬（朱一龙 饰），中年夫妇刘亚兰（徐帆 饰）和李宏宇（高亚麟 饰），退休老医生谢咏琴（吴彦姝 饰）和餐厅老板沛爷（许绍雄 饰），实习护士夏晓（周冬雨 饰），滞留旅客张哲（刘昊然 饰）和君君（乔欣 饰）。疫情下，爱给了他们挺身而出的勇气和力量。他们以笑做盾，以爱为矛，冲破凛冽寒冬和恐惧，勇敢拥抱。爱在武汉的烟火气下蔓延，抵御一切苦难，最终见证奇迹。', '黄渤', '薛晓路', 6, 110113, 'tt16287604', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2801718909.jpg', 9.8, 22.8, 37.3, 19, 11.1, '-0.338592,-0.143251,-0.140876,0.180029,0.033069,0.061723,0.512078,0.238702,-0.247503,-0.007429,0.269253,0.193199,-0.281275,0.131317,0.333394,-0.131739,-0.222956,-0.654152,0.108808,0.254468,-0.145293,-0.179407,-0.144562,-0.007604,0.028300,-0.276482,0.335048,0.205270,0.354400,0.763312,0.345782,0.144975,-0.138542,0.263373,0.179510,-0.169141,-0.080090,0.060236,-0.662691,-0.028603,-0.165552,-0.269016,-0.250666,-0.002132,-0.046302,0.088844,0.617458,0.013061,0.148376,-0.124483,0.307638,-0.225337,-0.014685,0.228649,0.017000,0.190579,0.206600,0.118523,-0.160533,0.016856,0.039323,-0.117824,-0.183674,-0.043616,0.210129,-0.050378,-0.294943,0.580362,-0.226328,0.109345,0.254484,-0.252140,0.054454,-0.111583,0.190425,0.429717,-0.196080,-0.053738,-0.088310,0.507799,0.261293,-0.105299,-0.247983,0.131993,-0.391170,-0.354668,-0.121575,0.172671,-0.434127,0.170868,0.143760,0.078152,0.197955,-0.126000,-0.625939,-0.298079,0.018339,0.022974,0.057573,-0.266557,-0.146715,-0.660329,-0.002896,-0.501319,-0.182936,0.193367,0.256095,0.017681,0.675322,-0.525445,0.137854,0.148434,0.368614,-0.148397,0.565245,0.005091,-0.042776,-0.326569,0.095658,0.172709,-0.311518,0.281622,0.183904,0.426386,-0.293235,0.336541,-0.126069,0.075776', '26365262', '3041753', '3811356', '1432699');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35307624', '渔港的肉子酱', '动画', '明石家秋刀鱼首度企画动画电影作品！改编西加柰子原作小说，STUDIO4℃制作的动画电影《渔港的肉子酱》将于今年初夏公映！故事围绕着生活在渔港的“肉子酱”母女的成长展开。《海兽之子》导演渡边步执导，小西贤一担任作画导演，剧本则由《凪的新生活》的大岛里美担当。', '大竹忍', '渡边步', 8.1, 20640, 'tt13758684', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2871666892.jpg', 0.3, 1.6, 20.6, 48.3, 29.3, '-0.269284,-0.465795,-0.179677,0.782318,0.471474,-0.109745,0.238202,0.607357,0.026282,-0.339846,0.314783,0.631865,-0.088975,0.184661,0.305661,0.017816,-0.382601,-0.333692,-0.354180,0.233253,0.332488,-0.089697,-0.204003,-0.072358,-0.193923,-0.221642,1.121674,-0.190104,-0.259291,0.238086,0.287658,-0.169257,-0.524840,-0.284100,0.496621,0.308588,0.293368,0.014505,-0.561026,0.335829,-0.419328,-0.310492,-0.177093,-0.173257,0.300964,0.080993,1.132150,-0.503228,-0.025979,-0.031024,0.528394,-0.409157,-0.160460,-0.292825,0.145660,0.143463,0.061782,0.146487,-0.243349,0.262340,-0.448875,-0.631777,-0.693821,-0.325017,0.474266,0.277095,-0.239994,0.196227,-0.233999,0.009569,0.267239,-0.323888,-0.098593,-0.087933,0.603321,0.342273,-0.067569,0.693027,-0.100275,0.628537,0.105248,0.230637,-0.045398,0.443110,-0.048267,-0.297830,-0.410473,-0.192785,-0.531784,0.031690,-0.085604,-0.125844,0.259822,0.174556,-0.744902,-0.077704,0.217172,-0.238371,0.614888,-0.125326,-0.146101,-0.914319,0.060688,-0.118409,0.117723,-0.501227,0.241842,-0.447642,1.033088,-0.416071,-0.025567,0.272368,-0.183273,-0.064763,0.545321,0.174975,-0.154191,-0.299167,0.100505,0.100401,-0.233980,0.089200,0.158474,0.367467,-0.087673,-0.251066,-0.632795,0.455895', '5403927', '1322847', '26759820', '30434174');
