INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35312401', '月老', '爱情', '惨遭雷击而死的阿纶（柯震东 饰）来到阴间，生前所有的记忆归零。他必须做出选择：投胎转世却可能变成蜗牛；或是担任神职，累积阴德再修转世为人的正果？阿纶决定成为月老新鲜人，他与个性爆冲粉红女Pinky（王净 饰）搭档，来到人间执行任务，当阿纶遇见狗狗阿鲁以及牵着他的主人小咪时，他前世的记忆都回来了，小咪（宋芸桦 饰）就是他生前的挚爱。阿纶希望能帮助阳间的小咪寻得新的姻缘，但每一条绑在小咪手上的红线竟然都被烧毁。原来，有些事，一万年也不会变……同一时间从阴间逃到人间的鬼头成（马志翔 饰），展开腥风血雨的复仇行动，找上五百年前背叛且杀害自己的马贼兄弟。当阿纶还在为小咪绑不上红线雀跃时，鬼头成却将小咪视为下一个要毁灭的目标……', '柯震东', '九把刀', 6.7, 8848, 'tt15456878', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2732882844.jpg', 4.8, 11.3, 41.6, 29.7, 12.6, '-0.075745,0.021523,-0.459548,0.374489,-0.290418,-0.408118,0.386170,0.077844,-0.182622,0.106172,0.152741,0.531898,-0.021897,0.210518,0.108303,0.103077,-0.185396,-0.705301,0.021311,-0.165166,-0.505391,-0.169322,-0.377667,0.045606,-0.006477,-0.226121,0.652791,-0.051432,0.122335,0.101189,0.499873,0.128647,-0.170414,0.140745,-0.445632,0.135130,-0.462019,0.146841,0.090064,0.131854,-0.209137,-0.055191,0.068978,-0.173555,-0.157234,0.254690,0.726194,-0.505800,-0.117414,-0.399019,0.268756,-0.486563,-0.114182,0.068850,0.075441,0.300357,0.304068,0.419632,-0.280387,-0.074917,0.241121,-0.188336,-0.712186,0.207416,0.193013,0.233338,-0.407925,0.088743,0.025810,0.222456,0.237694,-0.642969,0.096016,0.199316,0.370855,0.332838,-0.405094,0.093970,-0.553201,0.045961,0.669174,-0.243340,-0.136179,0.103552,0.268831,-0.266960,0.092203,-0.321841,-0.145015,0.078682,0.142130,0.274790,-0.205075,0.469074,-0.605226,-0.141426,-0.338860,0.120013,0.044995,-0.258194,-0.134047,-0.308839,-0.027096,-0.210026,-0.241831,0.340277,0.322838,-0.335588,0.555892,-0.544143,0.335396,0.281735,0.273088,-0.480115,0.726313,-0.009985,0.127036,-0.278015,0.009866,0.413266,0.127628,0.464205,0.067349,-0.215775,-0.015906,0.159262,-0.482698,0.426643', '26759820', '4301278', '2080130', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35312437', '奇迹·笨小孩', '剧情', '二十岁的景浩（易烊千玺 饰）独自带着年幼的妹妹来到深圳生活，兄妹俩生活温馨却拮据。为了妹妹高昂的手术费，机缘巧合之下，景浩得到一个机会，本以为美好生活即将来临，却不料遭遇重创。在时间和金钱的双重压力下，毫无退路的景浩决定孤注一掷，而他陷入困境的平凡人生，又能否燃起希望的火花？电影《奇迹》是中宣部国家电影局2021年重点电影项目，也是2021年重点建党百年献礼片，描述十八大以后新时代年轻人在深圳创业的影片。', '易烊千玺', '文牧野', 7.4, 479460, 'tt15783462', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2842327103.jpg', 1.8, 4.9, 32.8, 43.4, 17, '-0.352206,0.051531,-0.631416,0.417271,0.053566,-0.291984,0.386539,0.082096,-0.541121,-0.304180,0.217988,0.504781,-0.040981,0.370372,0.132206,-0.188969,-0.143945,-0.506549,0.235011,0.025324,-0.067378,-0.183633,-0.191261,-0.105357,-0.022652,-0.294870,0.644822,0.378781,-0.098516,0.235509,0.161715,0.227082,0.036856,0.330916,-0.262161,-0.129232,-0.208828,0.294807,-0.681865,0.348313,0.002603,-0.209914,-0.491947,0.202194,-0.020842,0.141395,0.635379,0.052245,-0.292259,-0.105910,0.545772,-0.173377,-0.125177,-0.201316,0.114791,0.033197,0.292643,0.239609,-0.029111,-0.033696,-0.150275,-0.584344,-0.670641,0.121081,-0.037580,-0.053677,-0.559549,0.764103,0.089898,0.172297,0.125702,-0.329486,0.001490,0.517183,0.547946,0.331146,-0.688392,0.295562,-0.296518,0.390506,0.661692,-0.007416,-0.220087,0.628654,-0.403808,-0.334270,-0.149881,-0.250508,-0.518668,0.119555,0.208756,0.088517,-0.376985,0.295731,-0.392105,0.241935,-0.319927,-0.196266,0.232860,-0.409278,-0.061159,-0.365332,-0.084200,-0.154223,-0.422985,0.213615,0.219891,-0.439005,0.829010,-0.582343,0.125336,0.480312,0.329073,-0.489556,0.713859,0.005159,-0.112079,-0.349972,0.096818,0.233472,-0.444899,0.224758,0.127276,-0.189760,-0.314686,-0.038795,-0.182623,0.502786', '27602116', '26021055', '1308424', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3531406', '再生门', '悬疑', '平静的郊外社区，小有名气的画家大卫·安德纳赫（麦德斯·米科尔森 Mads Mikkelsen 饰）与隔壁女邻居有染。某天当他鬼混时，女儿里奥妮（Valeria Eisenbart 饰）却在自家泳池溺毙。该事件直接导致他和妻子玛雅（洁西卡·史瓦兹 Jessica Schwarz 饰）的婚姻破裂，悲伤自责的大卫自暴自弃，一度试图自杀了结生命。被好友马克思（Tim Seyfi 饰）从死亡边缘拉回后的夜晚，大卫跟随一只神秘而美丽的蝴蝶穿过一条通道，竟意外回到了5年前事故发生的那一刻，成功救下女儿的性命。悲剧人生似乎发生转机，然而随后一连串的连锁事件却让他陷入命运漩涡，难以抽身……本片荣获2010年德国影评人协会最佳影片奖。©豆瓣', '麦斯·米科尔森', '安诺·绍尔', 7.4, 14066, 'tt1223934', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p992163182.jpg', 0.4, 3.1, 35.6, 47.9, 13, '0.141302,0.251122,-0.590688,0.236084,0.372345,-0.348000,0.837789,0.279419,-0.355470,-0.271329,0.152825,0.695291,-0.521174,0.142471,0.404211,0.063372,-0.354815,-0.815647,0.081008,-0.101076,-0.363395,-0.195507,-0.156724,-0.245420,0.096080,-0.273551,0.518699,0.314465,-0.150151,0.413247,0.353819,0.770916,-0.390520,0.397978,0.103880,0.176910,0.256867,0.065332,-0.400179,0.089169,-0.085356,-0.339095,-0.005682,0.154515,-0.012041,0.266099,0.794881,-0.224265,-0.051363,-0.126782,0.437637,-0.273133,-0.018831,0.016307,0.222212,-0.133403,-0.036320,0.084377,-0.118961,-0.229131,0.394625,-0.225993,-0.457524,0.143948,-0.123694,0.248402,-0.268667,0.018078,-0.097921,0.149642,0.190300,-0.160521,0.189257,0.245186,0.368688,0.135938,-0.369796,0.267359,-0.290042,0.147042,0.783181,-0.104921,-0.158671,0.234988,-0.305811,-0.392614,0.002704,-0.088324,-0.583236,0.203740,0.604997,0.061246,-0.149281,0.504647,-0.357604,-0.381992,-0.582564,0.049285,-0.217098,-0.133912,-0.179071,-0.315662,-0.042443,-0.064501,-0.361209,-0.020244,-0.309933,0.015648,0.088502,-0.320119,0.600937,0.417604,0.129671,-0.093855,0.528344,-0.139224,0.277245,-0.242085,0.082646,0.631011,-0.038952,0.138749,0.036890,0.106791,-0.059454,0.066423,-0.300082,0.353919', '3148064', '1292528', '26588308', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35318021', '正发生', '剧情', '上个世纪60年代，法国禁止堕胎。高中女孩安娜因为一次放纵而不小心怀孕，因非法堕胎而面临的法律和生命危险，以及牺牲在学业和未来之间做出选择，寻求各种办法偷偷堕胎的故事。', '安娜玛丽亚·沃特鲁梅', '奥黛丽·迪万', 7.9, 12299, 'tt13880104', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2872897338.jpg', 0.4, 1.5, 21.7, 54.3, 22.1, '0.289077,-0.094221,-0.815794,0.288860,-0.228104,0.115481,0.473749,-0.056362,-0.507627,-0.418344,0.052622,0.766761,0.219347,0.413195,0.479578,-0.279122,-0.249527,-0.669643,0.643495,0.101094,-0.644368,-0.540724,0.317769,-0.445306,-0.355611,-0.565485,1.033286,-0.039795,-0.514060,0.218100,0.019976,0.511385,-0.191333,0.114086,0.135255,-0.496769,-0.114544,0.164408,-0.634819,0.389980,0.665204,-0.443388,-0.092672,0.223411,0.077214,0.558364,0.711312,-0.185886,-0.322698,-0.635546,0.841095,-0.469593,-0.088277,0.064701,0.233491,-0.059913,0.295467,0.792585,-0.063596,-0.004700,0.251532,-0.250580,-0.597019,-0.116265,0.474965,0.333539,-0.473105,0.288355,-0.118495,0.098596,0.308942,-0.280768,-0.067192,0.734824,0.920057,0.364651,-0.890020,-0.039647,-0.482083,0.019527,0.796471,-0.210457,-0.212594,0.312044,-0.168313,0.039971,0.299671,-0.470277,-0.561793,0.313791,-0.316475,0.190162,-0.799807,0.490173,-0.280053,-0.180975,-0.212255,-0.265578,0.419172,-0.250142,0.045032,-0.673944,0.167662,-0.282585,-0.305327,0.174848,0.268402,-0.324599,0.489596,-0.839676,0.161376,0.609738,0.922962,-1.139439,0.583265,0.595651,0.357257,-0.368279,0.096188,0.558375,-0.201283,-0.190483,-0.540051,-0.411951,0.331173,0.041578,0.068895,0.119024', '1484760', '1293265', '30345227', '1428876');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3532614', '夺命金', '剧情', '香港世道不景气，普通人的日子不好过，连黑白两道的人也日陷窘境。打拼多年的黑道小人物三脚豹（刘青云 饰）诚实忠义，但在利益至上的年代他的忠义既珍贵又可笑。好不容易帮助当年的好兄弟凸眼龙（姜皓文 饰）经营黑市期指，偏偏当天就赶上了大股灾，凸眼龙破产在即。二人合计，决定从放债 人锺原（卢海鹏 饰）的手中骗抢一千万现金。谁知出手前却遭遇另一组劫匪，锺原更因此陈尸车中。银行职员特丽莎•陈是锺原的客服与投资顾问，面对突然留在自己手中的巨款，长久以来倍感压抑的她面临一次重大的选择。受命调查锺原遇害案的警队督察张正方（任贤齐 饰）刚直不阿，老父患绝症、妻子私下挪用存款。在巨大的现实压力面前，三个身处不同社会阶层的人经历着前所未有的波澜……©豆瓣', '刘青云', '杜琪峰', 7.4, 110604, 'tt1371585', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1375774449.jpg', 1, 4.5, 33.7, 46.3, 14.5, '-0.023656,0.019246,-0.537770,0.272535,0.016814,-0.305555,0.435699,0.379124,-0.536136,-0.327664,0.503993,0.493849,0.164876,-0.017622,0.266657,-0.071534,0.050999,-0.538983,0.003082,-0.077343,0.067993,-0.458177,-0.366954,-0.149627,-0.197961,-0.015346,0.256173,0.234974,-0.099667,0.352628,0.298889,0.225624,-0.116085,0.400037,0.077301,-0.118907,0.117323,0.325331,-0.447131,-0.081216,-0.066467,-0.386910,-0.107946,0.055326,0.317619,0.432529,0.346757,-0.148717,-0.278577,-0.023774,0.414309,-0.126287,-0.368852,-0.177296,0.258855,0.063250,0.307708,0.209726,-0.363773,-0.047389,0.202051,-0.147187,-0.686559,-0.039759,0.130530,0.011639,-0.621742,0.470715,-0.151257,0.158151,-0.232401,-0.135504,0.033755,0.311569,0.190253,0.256436,-0.083745,0.056563,-0.329521,0.266569,0.631934,-0.108419,-0.349462,-0.045981,-0.098188,-0.414120,-0.101588,-0.404635,-0.366261,0.023200,0.287907,-0.007984,-0.186390,0.243885,-0.477028,0.265433,-0.222802,0.106385,0.099451,-0.079271,-0.031363,-0.263936,-0.192768,-0.245041,-0.263994,0.198306,0.287737,-0.205796,0.477911,-0.370296,0.064357,0.340467,0.302540,-0.521417,0.439674,0.150865,0.019332,-0.333609,-0.231456,-0.014409,0.027802,0.322354,0.108292,-0.245262,-0.265895,-0.156463,0.063940,0.291358', '26678784', '25917239', '25908042', '1299799');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35327724', '鬼灭之刃 柱众会议・蝶屋敷篇', '动画', '今回放送する『鬼滅の刃』＜柱合会議・蝶屋敷編＞は、アニメ『鬼滅の刃』の第22話～第26話で構成された『竃門炭治郎 立志編』の完結編であり、『劇場版「鬼滅の刃」無限列車編』へと続くストーリー。劇場版にも登場する炎柱・煉獄杏寿郎（れんごく・きょうじゅろう）をはじめとする“鬼殺隊”の主軸をなす最強剣士である“柱”たちが初めて一堂に会し登場する“柱合会議”を含む重要エピソードだ。主人公・竃門炭治郎（かまど・たんじろう）が隊士でありながら鬼となった妹・禰豆子（ねずこ）と共に行動していることに対して“隊律違反”を犯したと“柱”たちから裁判を受ける。また那田蜘蛛山で負傷した炭治郎と、同期で仲間の我妻善逸（あがつま・ぜんいつ）、嘴平伊之助（はしびら・いのすけ）の“蝶屋敷”での修行模様や、劇場版へ続くエピソードまでを描いている。＜柱合会議・蝶屋敷編＞のキービジュアルはアニメーション制作のufotableが今回のために特別に描き下ろした新作ビジュアルだ。9人の柱たちが一堂に会したインパクトある今回のビジュアルは、ファンにはたまらない特別なビジュアルとなっている。さらに、今回の＜柱合会議・蝶屋敷編＞は、この放送のために制作された新規映像などが追加された特別編集版となることが決定！ufotable描き下ろしによる新規提供イラストやスペシャルエンドロール、さらには新作映像が加わったこの＜柱合会議・蝶屋敷編＞はまさに必見！鬼滅ファンの方はもちろん、アニメ『鬼滅の刃』を初めてみる方も、これから『劇場版「鬼滅の刃」無限列車編』を見る方、さらにはすでに劇場版をみた方も含め、楽しめる要素満載の特別編集版となってい', '花江夏树', '外崎春雄', 8.7, 9242, 'tt14882302', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2632682629.jpg', 0.5, 1.3, 11.9, 36.7, 49.5, '-0.435199,-0.072520,0.133503,0.516091,0.477958,0.042840,-0.091071,0.310789,0.738714,-0.378076,0.052378,-0.011531,-0.515253,-0.025334,-0.079531,-0.443976,0.389514,-0.222169,0.029085,-0.129727,-0.310468,0.408880,0.000415,0.416868,-0.204682,-0.201403,0.206119,-0.060368,-0.017192,-0.295955,0.251557,0.478684,-0.110922,-0.054310,0.183862,0.104546,-0.218335,0.200439,0.234539,-0.082369,-0.295453,-0.380121,0.064391,-0.062771,0.469820,0.121874,1.203854,-0.199145,0.126728,-0.175626,0.334599,0.380213,-0.402048,-0.232658,0.193793,0.254706,-0.241826,-0.135003,0.008433,0.178784,-0.024934,-0.492987,-0.174249,-0.468802,0.435143,-0.314275,-0.139695,-0.193073,-0.306907,0.426717,-0.155567,0.011906,0.244937,-0.339425,0.479706,0.097730,0.400044,0.019186,-0.025477,0.445570,-0.133335,-0.146578,-0.403275,0.039104,0.135899,-0.281651,-0.138298,0.082278,0.370577,-0.024487,0.266465,0.031222,0.304235,-0.224691,-0.158875,-0.4