INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35335784', '名侦探柯南：绯色的不在场证明', '剧情', '真实身份谜团重重、每个人都有着复杂背景的危险一家——赤井家族。 在来叶崖假死的FBI探员赤井秀一，《名侦探柯南 绯色的不在证明》以他为中心展开，揭开了赤井秀一、世良真纯、羽田秀吉、玛丽等人的个性，以及他们几人之间的关系。 故事的高潮则在讲述赤井秀一华丽复活的“绯色”系列 。在某个事件中，赤井秀一的宿敌、代号为波本的安室透从FBI那打听到了“线索”。之后，安室透便深入调查赤井秀一与冲矢昴的关系。在经过了一系列的高智商攻防战后，赤井秀一的回归给所有人带来了冲击。 而在这一连串的“不在场证明剧”的真相背后，都有着柯南的身影—— 《名侦探柯南》系列中不可缺少的赤井一家，该总集篇将彻底解剖他们至今为止的行动轨迹、以及他们与柯南的关系。', '高山南', '山本泰一郎', 6.9, 12261, 'tt13884166', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2874825358.jpg', 2.1, 8.6, 45, 29.1, 15.2, '0.507737,-0.023832,-0.730629,0.710922,0.121731,-0.313540,0.736560,0.035516,-0.369294,-0.331220,0.305218,0.948055,-0.337308,-0.051891,0.365473,0.054263,-0.360895,-0.737184,-0.335926,-0.518881,-0.387800,-0.632152,-0.190662,-0.157911,-0.007545,-0.203640,0.464506,0.055319,-0.348201,0.541240,0.318525,0.226117,-0.435292,0.520580,0.021910,0.157117,0.169262,-0.084270,-0.169938,0.244984,0.055486,-0.386009,-0.100155,0.396255,-0.283535,0.610157,0.826770,-0.530429,-0.059165,0.103275,0.256754,-0.173335,-0.294124,0.204605,0.544929,-0.153920,0.086704,0.607483,-0.274358,0.054853,0.043999,0.079310,-1.267093,-0.240759,0.156832,0.600789,-0.346310,0.331298,-0.207395,-0.218064,0.258225,-0.319469,0.305856,0.426152,0.451076,0.312073,-0.205337,0.066222,-0.280647,0.113817,0.660806,0.131243,-0.159339,0.453798,-0.318805,-0.434759,-0.637506,0.040137,-0.177561,-0.205040,0.537121,0.217851,-0.242982,0.177655,-0.675498,-0.273985,0.124833,-0.332405,-0.218134,-0.390256,-0.202058,-0.432372,-0.295031,-0.528377,-0.305675,0.157846,0.264936,-0.200003,0.866609,-0.855506,0.010983,0.498061,-0.056696,-0.317829,0.436575,0.194271,0.038183,-0.082718,-0.152827,-0.069768,0.220919,0.498124,0.127528,0.694513,-0.019114,-0.285526,-0.451294,0.293440', '26678784', '25928048', '1793491', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35337517', '四海', '喜剧', '在码头做摩托车特技表演顺便拉客的年轻人吴仁耀（刘昊然 饰），他多年不见的浪荡父亲吴仁腾（沈腾 饰）；梦想大城市生活的餐馆服务员周欢颂和他浮夸真诚的哥哥周欢歌。一支从没有赢过一场比赛的“不败传说”车队频频出战，一群可笑又可爱的小人物命运交织。阿耀和欢颂都立志活成自己亲人的反面，想彼此取暖，彼此独立，却又总不在一个频道上。世事无常，他们不得不背井离乡，迎接一场未知旅途，阿耀的一身技能竟会用在一个自己都意想不到的场合，他的亲情友情和爱情最终又将会是如何……', '刘昊然', '韩寒', 5.3, 207807, 'tt14509614', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2867433563.jpg', 12.3, 31, 37.8, 14.9, 4.1, '0.181198,0.011274,-0.462900,0.773788,-0.312783,-0.222162,0.849843,0.179639,-0.217849,0.017948,0.475126,0.948905,-0.107379,0.161347,0.085210,-0.033226,-0.207650,-0.693596,0.075813,0.223111,-0.226577,-0.270909,-0.299357,-0.344003,0.058385,0.189818,0.491297,0.114241,-0.179597,0.306646,0.427548,-0.024724,-0.252726,0.603538,-0.512255,-0.000188,0.063926,0.534399,-0.140366,-0.218652,-0.161203,-0.380111,-0.494701,0.294313,-0.146159,0.068174,0.806196,-0.141765,-0.098305,0.079619,0.154160,-0.238307,0.070696,-0.084761,-0.044445,-0.225014,0.171122,0.073911,0.228608,-0.035008,0.008302,0.079637,-0.827839,0.005463,0.014432,0.039450,-0.423725,0.848807,-0.096201,-0.098076,0.138019,-0.286119,0.053839,0.219373,0.449574,0.346433,-0.426701,-0.200140,-0.567775,0.587400,0.929044,0.256001,-0.367471,0.501885,-0.367969,-0.379887,-0.234927,-0.166402,-1.065905,-0.154507,0.245220,-0.346001,-0.109611,0.169278,-0.727826,0.219935,-0.021935,-0.004963,0.077905,-0.620022,0.085286,-0.348948,-0.101778,-0.602388,-0.468273,0.249508,0.248163,-0.080848,0.972955,-0.745883,-0.058379,0.600920,-0.137331,-0.562788,0.741498,0.444185,-0.031306,-0.293759,0.019737,0.082666,-0.162956,0.274104,0.177781,0.510657,-0.018796,0.439762,-0.389611,0.539433', '30162520', '4847665', '4817024', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35341588', '男人', '恐怖', '丈夫过世之后，哈珀（杰西巴克利 饰）来到一处美丽的英国乡村疗伤，然而，这里的树林中似乎有某人或某物在跟踪她，这些潜藏在她心中隐约的恐惧，随着时间逐渐转变成具体的恶梦……', '杰西·巴克利', '亚历克斯·加兰', 6.9, 14476, 'tt13841850', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2867939386.jpg', 3.7, 9.6, 39.2, 35.6, 11.9, '0.354601,0.119413,-0.917639,0.542290,0.239983,-0.383281,1.223736,-0.013290,-0.773132,-0.468377,0.315443,0.351159,-0.332356,0.528416,-0.101552,0.190826,-0.595544,-0.601447,-0.203214,-0.297712,-0.241623,-0.237805,-0.611521,-0.246910,-0.173953,-0.086766,0.654549,0.439111,0.079115,0.504506,-0.144591,0.411575,0.024877,0.555382,-0.177119,0.040186,0.384234,-0.151849,-0.025163,0.090392,0.342842,-0.225779,-0.170639,0.051936,-0.095677,0.617867,0.826954,-0.059779,-0.343539,-0.049039,0.463194,0.083441,0.252138,0.140171,0.192380,-0.061064,0.402445,-0.155899,-0.374366,0.180120,-0.194769,0.387058,-0.205710,0.118155,-0.195139,0.433391,0.128425,-0.150215,0.021815,-0.280284,0.204202,-0.531736,0.316033,0.203890,-0.036708,0.179789,-0.419598,0.035484,-0.394437,0.026177,0.612131,-0.051210,-0.124091,0.368813,-0.340617,-0.225925,0.345086,0.213522,-0.262372,-0.392457,0.288426,0.344060,-0.158951,0.372109,-0.364032,0.071570,-0.246285,-0.264409,-0.250366,-0.098832,-0.486703,-0.502872,-0.335894,-0.338998,-0.172909,-0.312793,-0.056251,0.107080,0.338365,-0.862315,0.747011,0.501940,0.039042,-0.010201,0.224964,-0.245307,0.139662,-0.099813,-0.128048,0.573200,-0.223848,0.282140,-0.205711,0.290882,0.067206,0.147843,-0.755424,0.551353', '21348112', '20451118', '10733357', '1302488');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3534824', '空气人偶', '剧情', '他（坂尾创路 饰）是一个唯唯诺诺在餐馆打工的侍应生，她（裴斗娜 饰）是一个只值5000多日元过时的充气人偶。在孤独漫长的夜晚，她慰藉着他空虚的心灵与肉体。对他来说，她也许只是寄托情感的替代品。不知曾几何时，她有了自己的思想和知觉，每天在他上班之后，她便穿上衣服独自外出，用好奇的大眼睛注视着这个忙碌的大都市。最终，她在一家录影带出租店停留，仿佛银幕上交错变换的虚幻情节恰恰映射着她那匪夷所思的生命，其心中涌起阵阵波动。她渐渐喜欢上店里的男孩纯一，在这个人人生而空虚的世界上，她的爱情故事不算故事……本片根据日本漫画家业田良家的同名作品改编。©豆瓣', '裴斗娜', '是枝裕和', 7.5, 40028, 'tt1371630', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2162533098.jpg', 0.5, 3.7, 33.5, 47.2, 15.1, '0.351592,0.232400,-0.979411,0.753133,-0.126127,-0.009368,1.260113,0.344724,-0.317284,-0.095350,0.470005,0.812113,-0.037348,0.390981,-0.045552,0.238760,-0.278956,-0.647987,-0.007141,-0.128940,-0.179151,-0.334496,-0.382162,-0.196259,-0.152299,-0.205184,0.598852,0.115774,-0.125553,0.356088,0.339099,0.058970,0.074928,0.658238,-0.316526,0.045486,-0.151165,0.135105,0.212784,-0.059100,0.014854,-0.431523,-0.148580,0.259405,-0.396204,0.398031,0.923866,-0.135929,-0.249003,0.083269,0.583033,-0.140704,-0.221243,-0.100565,-0.136654,0.174802,0.017836,-0.320599,-0.286411,-0.064669,0.020264,0.077790,-0.742317,-0.263599,0.025666,0.389715,-0.784538,0.665237,-0.124713,-0.186125,0.007391,-0.461198,0.084279,-0.139231,0.125592,0.418405,-0.227878,-0.054150,-0.502304,0.637509,0.409114,0.245946,-0.610910,0.721767,-0.667915,-0.355319,-0.355369,-0.045278,-0.740625,-0.286263,0.288565,-0.048402,-0.301343,0.043268,-0.648895,0.289875,0.194709,-0.345422,-0.174834,-0.292992,-0.191024,-0.375835,-0.298560,-0.644083,-0.459415,-0.009588,0.107551,-0.267527,0.735101,-0.716075,0.200629,0.979240,0.266636,-0.155151,0.898872,-0.003948,-0.085741,-0.047927,-0.235546,0.295394,-0.337069,0.244350,0.274535,0.617561,-0.121543,0.508663,-0.699704,0.910637', '21619567', '4233625', '1783772', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35360296', '偶然与想象', '剧情', '影片由三个短片构成——《魔法（比魔法更不真切）》《开着的门》《再来一次》。女性角色的多重性和镜像性是滨口之前的作品中的主题，在他的新作《偶然与想象》中也是如此。前作《欢乐时光》和《夜以继日》，从字面上看，颇有小说的味道，而《偶然与想象》则可以说是一部短篇小说集。叙事节奏 更强化了这一印象：三集，每集围绕一个女性角色展开，又分为三幕。三个短片讲述了一个意想不到的三角恋、一场未遂的诱惑和一个因误会而相遇的故事。尽管零散，但仍保持了有机的叙事流程，甚至还强调了这一点。虽然大部分的动作都发生在一个空间里，而且只有两个演员参与，这部电影却不让人觉得像一出室内剧。这不仅仅是由于对话的缘故，还在于其复杂的时空概念，最后一集几乎变成了科幻片。我们所见证的时刻都与感人的普遍命运相连，以选择、遗憾、欺骗和巧合为标志，它们是影片真正的主角。', '古川琴音', '滨口龙介', 8.3, 59518, 'tt14034966', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2687984714.jpg', 0.4, 1.4, 14.6, 49.5, 34.1, '0.274136,-0.161387,-0.550949,0.978073,0.264141,-0.007106,1.137801,-0.046437,-0.370106,-0.321010,0.104697,0.852115,-0.369863,-0.212011,0.129400,-0.372150,-0.315414,-0.382294,-0.181074,-0.087498,-0.233593,-0.446118,-0.347362,-0.041276,-0.090525,-0.390452,0.714732,0.116078,-0.680046,0.241199,0.336338,-0.058502,-0.177721,0.288687,-0.007961,-0.103157,-0.111758,0.287604,-0.168912,0.212828,0.051647,-0.282178,-0.126463,0.274172,-0.295309,0.402653,0.776886,-0.414647,-0.344913,0.164989,0.522019,-0.180561,-0.376528,-0.086382,0.181602,0.096677,0.558419,0.158924,-0.013034,0.262618,-0.063253,-0.102757,-1.396764,0.032609,0.315584,0.234323,-0.309156,0.508266,0.175843,-0.221798,-0.029404,-0.181413,0.218309,0.221849,0.685618,0.444734,-0.305550,-0.246303,-0.496847,0.225363,0.672187,0.072007,-0.564189,0.946910,-0.280910,-0.590688,-0.393691,-0.162448,-0.397513,0.391251,-0.000034,0.156743,-0.083167,0.141309,-0.803048,0.229100,0.121226,-0.240789,-0.161886,-0.768484,0.074598,-0.743110,-0.227885,-0.480630,-0.277769,-0.053697,0.271485,-0.517341,0.896713,-0.644833,0.031902,0.390118,0.125206,-0.466627,0.901955,0.506554,0.124865,-0.079993,-0.015513,-0.021851,0.007257,0.012601,0.019074,0.620371,0.096864,-0.217906,-0.525555,0.621173', '6844861', '27666513', '2053