INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35360684', '新神榜：杨戬', '动作', '商周之战一千五百年后，天界衰落，蒙冤落魄的杨戬以赏银捕手为业谋生。一日，杨戬接受了一位神秘访客的赏银去追捕一位少年，意外发现少年竟是自己的亲外甥沉香。沉香立志要寻回宝莲灯，劈山救母，却将酿成大祸。杨戬踏上追寻沉香并揭开尘封往事的旅程……', '王凯', '赵霁', 7, 127060, 'tt19757204', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2878224156.jpg', 1.6, 8.1, 39, 39.2, 12.2, '-0.160296,0.419136,-0.123957,0.269480,0.030488,-0.725772,0.685150,-0.027690,-0.402433,-0.179020,0.609247,0.527455,0.055056,-0.031786,0.333347,0.262513,0.172911,-0.408546,0.220470,-0.312684,0.081515,0.206255,-0.404041,0.206876,-0.036356,-0.145101,0.686017,0.269230,-0.140739,0.608114,0.090698,-0.103847,-0.481373,0.319446,-0.246331,0.280478,-0.342041,0.355674,-0.090555,-0.033689,-0.184213,-0.678914,-0.378159,0.060939,-0.476164,0.391312,0.344651,-0.355567,-0.220054,-0.363240,0.309417,-0.037053,-0.264187,0.338070,0.125878,0.278605,-0.344748,0.405982,-0.072528,-0.045664,0.048329,-0.163537,-0.131015,0.090658,-0.007412,0.155364,-0.508531,0.268077,0.092273,0.227834,-0.182158,-0.538887,-0.159967,0.269234,0.403911,0.196627,-0.165943,-0.011631,-0.274542,0.724679,0.460304,-0.520888,0.258241,0.066390,0.263762,-0.255566,0.254054,-0.350423,-0.498563,0.241506,0.426598,-0.012320,0.237238,0.402521,-0.472919,-0.408523,-0.954701,0.238924,-0.183201,0.187258,-0.160447,-0.145268,-0.076418,0.370427,-0.544474,-0.251091,0.429742,-0.453381,0.561281,-0.276597,0.293709,0.687722,-0.052707,-0.482729,0.445898,-0.034063,0.183370,-0.444250,-0.155616,0.696602,-0.234998,0.460991,-0.265547,-0.103158,-0.270582,0.022316,-0.290194,0.273202', '1307023', '1844413', '1298095', '3804746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35372415', '套装', '剧情', '雷纳德（马克·里朗斯 Mark Rylance 饰）是一位手艺精湛的裁缝，一场火灾之后，他离开了伦敦，来到芝加哥，在这里经营着一间属于自己的裁缝店。店里的员工除了雷纳德自己外，还有一个名叫梅布尔（佐伊·达奇 Zoey Deutch 饰）的姑娘，梅布尔的父亲是一个臭名昭著的恶棍，背负着父亲的“盛名”，梅布尔下定决心要攒够钱，去看一看这个肮脏黑暗的街区以外的世界。一天深夜，黑帮大佬罗伊（西蒙·拉塞尔·比尔 Simon Russell Beale 饰）的儿子里奇（迪伦·奥布莱恩 Dylan O''Brien 饰）和他的副手弗朗西斯（强尼·弗林 Johnny Flynn 饰）闯入了店中，里奇身受重伤，在弗朗西斯的威胁之下，雷纳德处理了里奇的伤口，将他从死亡线上救了回来，但与此同时，他也被卷入了这个黑帮家族的纷争之中。©豆瓣', '马克·里朗斯', '格拉汉姆·摩尔', 7.9, 56918, 'tt14114802', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2868098898.jpg', 0.3, 1.4, 22.2, 54.1, 22, '0.400180,0.099069,-0.595027,0.444016,-0.221893,-0.413704,0.846742,0.225673,-0.618643,-0.302511,0.287914,0.993816,0.052272,0.441681,0.434969,0.450200,-0.368326,-0.643679,-0.105993,-0.324442,-0.341491,-0.592314,-0.428618,-0.308952,-0.142734,-0.193438,0.252776,0.241927,0.013301,0.407490,0.277742,0.319418,0.083822,0.439877,-0.060479,0.253816,0.380967,-0.467012,-0.138807,0.364740,0.038620,-0.180968,-0.021470,0.179554,0.208928,0.466963,0.445195,-0.191339,0.477853,-0.193869,0.209300,-0.119344,0.148883,0.209668,0.328109,-0.381951,0.006601,0.204038,-0.398298,-0.093440,0.122808,-0.187017,-0.673093,0.026688,0.067698,0.204264,-1.004485,0.465168,-0.292965,-0.083836,-0.139491,-0.227038,0.351463,0.176402,0.087207,0.313747,-0.010522,-0.003602,-0.651590,0.026518,0.401127,-0.165525,0.043737,-0.019061,-0.165939,-0.331157,-0.185816,-0.181193,-0.558172,-0.214921,0.642731,-0.265038,-0.026109,0.047378,-0.665859,-0.017063,-0.361283,-0.355711,-0.239253,0.001008,-0.297604,-0.688713,0.017122,-0.298290,-0.452091,-0.142987,-0.022763,-0.165216,0.494010,-0.647041,0.104127,0.599481,0.271877,-0.077115,0.651508,-0.227319,0.606728,0.130300,-0.189296,0.364010,0.238622,0.282023,0.376920,0.574661,0.027361,-0.213665,-0.066632,0.472457', '1309069', '1895119', '11525673', '1