INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35376457', '爱情神话', '剧情', '离异多年的画家老白（徐峥 饰）经朋友介绍认识了同样离异，带着一个孩子的李小姐（马伊琍 饰），老白对李小姐一见倾心，可是李小姐似乎对这段感情有所顾虑，一直止步不前。老白在家里开设了美术班，教成年人画画，格洛瑞亚（倪虹洁 饰）是他的学生之一。热情奔放的格洛瑞亚虽然已经结婚，但是丈夫远在国外常年不回家，她似乎对老白有着超越了师生的感情。蓓蓓（吴越 饰）是老白的前妻，两人虽然已经离婚多年，而且是蓓蓓背叛了老白，但老白的母亲还是希望两人有朝一日可以复婚。在上海的弄堂里，一个男人和三个女人的故事徐徐拉开序幕。©豆瓣', '徐峥', '邵艺辉', 8.1, 622983, 'tt16606348', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2772925591.jpg', 0.5, 2, 17.5, 52.3, 27.8, '0.385875,-0.272875,-0.589566,0.612530,-0.331063,-0.405397,0.599291,-0.083074,-0.713463,-0.318285,-0.039921,0.740564,-0.059315,0.559501,-0.115109,0.090016,-0.004332,-0.637891,0.140103,-0.184871,-0.197356,-0.687975,-0.190445,0.031380,-0.382199,-0.194429,0.468678,-0.082303,0.072699,0.549066,0.365610,-0.264580,-0.168143,0.399178,-0.171707,0.061261,0.062600,0.263678,-0.516618,-0.006728,0.191508,-0.036090,0.002100,-0.126183,0.179109,0.374389,0.447649,0.047874,-0.193600,0.263426,0.352823,-0.082264,-0.212078,0.041255,0.401848,-0.005190,0.578377,0.360904,-0.141411,-0.182866,-0.168941,-0.165087,-0.273499,0.041931,0.231643,0.105644,-0.777916,0.826012,-0.069694,-0.234026,0.048289,-0.343117,0.140788,0.112604,0.037507,0.571203,-0.220552,0.094263,-0.389054,0.113582,0.580259,0.161987,-0.147055,0.426813,-0.265445,-0.320190,-0.263405,0.133373,-0.692849,0.145837,-0.058263,-0.213453,-0.396662,0.067855,-0.337589,-0.004544,0.035454,0.200672,0.220596,-0.569618,0.171141,-0.242076,-0.251954,-0.889355,-0.387684,0.105487,0.188645,-0.347616,0.882374,-1.023240,0.266218,0.283979,0.443922,-0.797556,0.889751,0.358273,0.077126,-0.293189,0.031682,0.263678,-0.251907,-0.244461,0.366664,0.313698,0.088231,-0.146857,-0.259543,0.419569', '1292720', '25907086', '3445516', '1390020');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35377026', '熊出没·重返地球', '喜剧', '有点懒又有点馋的熊二虽然总是各种失误犯错，内心却一直梦想成为一位英雄，以此获得大家特别是哥哥熊大的认可。一块外星原核的坠落打破了狗熊岭的平静，熊二意外的与外星原核合体，成为了拥有外星智慧能量的熊！随之而来的是“外星人”阿布的抢夺。阿布为了夺回原核，故意制造事端，让熊二众叛亲离。就在阿布将要成功的时候，一支神秘高科技军团的攻击彻底打乱了计划，导致熊强组合甚至整个地球于巨大的危难之中。阿布隐藏的身份以及来到地球的真正目的到底是什么？神秘的高科技军团背后有何故事？自暴自弃的熊二能否振作起来实现他的英雄梦？他们能否挽救地球的危机？', '张秉君', '林汇达', 6.5, 25695, 'tt17081112', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2856825681.jpg', 2, 12.6, 51.4, 25.8, 8.2, '0.064604,0.402688,-0.606936,0.460405,-0.357867,-0.126091,0.405000,-0.221791,-0.413481,-0.170859,0.192920,0.615633,0.042212,0.247706,0.036362,-0.043337,0.081605,-0.230757,-0.070282,0.096360,-0.318438,-0.321108,-0.847317,-0.195111,-0.030395,-0.320913,0.935781,0.237694,-0.673799,-0.033434,0.287011,0.662588,-0.130273,0.382261,-0.285726,-0.075463,-0.069964,0.045574,-0.312375,0.035460,-0.165233,-0.079927,0.080983,0.499158,-0.172502,-0.003072,0.635583,-0.656195,-0.155114,-0.232619,0.447789,-0.461500,-0.055916,-0.115433,0.250162,0.003188,-0.074959,0.005247,0.080549,0.025786,0.109765,-0.024984,-1.123877,-0.238577,0.143126,0.160551,-0.312824,0.149071,0.199291,-0.057866,0.315041,-0.139389,0.197648,0.614880,0.451381,0.449809,-0.401232,0.111340,-0.363497,-0.165748,0.845171,-0.098837,-0.523785,0.106139,-0.124056,-0.547484,-0.167852,-0.300384,-0.098418,0.004249,0.309776,0.217593,0.019742,0.522022,-0.853735,0.121115,-0.338884,-0.148411,0.102377,-0.438498,0.042190,-0.261573,-0.064410,-0.190932,-0.097173,0.088318,0.127791,-0.201857,0.819481,-0.784860,0.187063,0.632502,0.224152,-0.434763,0.126243,0.133455,-0.085415,-0.444305,-0.024437,0.084348,-0.015802,0.193662,-0.218170,0.100943,0.219539,-0.076171,-0.395448,0.659849', '26667010', '3213270', '3001114', '1308585');
