INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3541415', '盗梦空间', '剧情', '道姆·柯布（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）与同事阿瑟（约瑟夫·戈登-莱维特 Joseph Gordon-Levitt 饰）和纳什（卢卡斯·哈斯 Lukas Haas 饰）在一次针对日本能源大亨齐藤（渡边谦 饰）的盗梦行动中失败，反被齐藤利用。齐藤威逼利诱因遭通缉而流亡海外的柯布帮他拆分他竞争对手的公司，采取极端措施在其唯一继承人罗伯特·费希尔（希里安·墨菲 Cillian Murphy 饰）的深层潜意识中种下放弃家族公司、自立门户的想法。为了重返美国，柯布偷偷求助于岳父迈尔斯（迈克尔·凯恩 Michael Caine 饰），吸收了年轻的梦境设计师艾里阿德妮（艾伦·佩吉 Ellen Page 饰）、梦境演员艾姆斯（汤姆·哈迪 Tom Hardy 饰）和药剂师约瑟夫（迪利普·劳 Dileep Rao 饰）加入行动。在一层层递进的梦境中，柯布不仅要对付费希尔潜意识的本能反抗，还必须直面已逝妻子梅尔（玛丽昂·歌迪亚 Marion Cotillard 饰）的处处破坏，实际情况远比预想危险得多……', '莱昂纳多·迪卡普里奥', '克里斯托弗·诺兰', 9.4, 1934111, 'tt1375666', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p513344864.jpg', 0.1, 0.2, 3.5, 23.9, 72.2, '0.052247,0.066650,-0.434086,0.414841,-0.035662,-0.395333,0.469611,0.320718,-0.461864,-0.599075,0.035669,0.473124,-0.133956,-0.212495,0.225441,0.140839,-0.645056,-0.368723,0.084941,0.180900,-0.124714,-0.783974,-0.337013,-0.495099,0.008295,-0.410341,0.717208,-0.058258,-0.331654,-0.037296,0.227314,0.789230,-0.028426,0.113418,0.415044,-0.015429,0.396315,-0.332090,-0.654534,0.188915,-0.000109,0.081065,-0.186293,0.215267,0.210625,0.470034,0.201850,-0.417499,0.263516,-0.043827,0.251664,-0.168167,0.092016,-0.020940,0.184740,-0.281748,0.008666,0.320528,-0.041293,0.054919,0.241463,-0.068254,-0.626329,-0.049088,0.318628,0.107895,-0.371506,0.100888,-0.271508,0.322933,0.216356,-0.127808,-0.304873,0.238121,0.277604,-0.017452,-0.060346,-0.031591,-0.319673,-0.001227,0.192243,-0.093596,-0.184172,0.240844,-0.280803,-0.201032,-0.231113,-0.157934,-0.380484,-0.126540,0.399728,-0.030012,0.128894,0.526133,-0.328452,-0.357895,-0.527183,-0.034019,-0.041530,-0.156002,0.243598,-0.777818,-0.044479,-0.030066,-0.172587,-0.195203,-0.007208,-0.182350,0.125895,-0.562276,0.067573,0.652713,0.200902,-0.132967,0.207388,-0.015511,0.115632,-0.521126,-0.119290,0.432