INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35414623', '咒术回战 0 剧场版', '动画', '自幼感情极好的乙骨忧太与祈本里香约好长大后要结婚，却不料里香因死亡车祸化为强大怨灵依附在忧太身边，为此所苦的忧太一心求死，之后在五条悟的带领下进入咒术高专结识了新同学：禅院真希、狗卷棘与熊猫，他决定在这里找到活下去的自信并解除里香的诅咒。意欲夺取里香强大怨灵力量的夏油杰宣布在12月24日举行「百鬼夜行」，在新宿与京都释出上千个诅咒。面临如此重大浩劫，忧太能否阻止夏油的野心并解开里香的诅咒？', '绪方惠美', '朴性厚', 8.2, 27006, 'tt14331144', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2708190250.jpg', 0.7, 1.8, 17.6, 45, 34.8, '-0.142957,0.260379,-0.572384,0.289139,0.118834,0.068883,0.424841,-0.073208,-0.298789,-0.304701,-0.061433,0.588584,-0.005178,0.315110,0.168111,-0.055072,0.021487,-0.548414,0.243485,-0.343490,-0.162171,-0.265946,-0.313424,0.166717,-0.112570,-0.641857,0.697098,0.634903,-0.108651,0.377864,0.242809,0.205527,-0.208581,0.586558,-0.081170,-0.120023,-0.393318,0.181648,-0.309666,0.343238,0.090545,-0.400169,0.079397,0.237685,0.117791,0.095391,0.469760,-0.766043,-0.222140,-0.386612,0.343456,-0.416223,-0.190441,0.191509,0.338911,0.224142,0.246666,0.435873,-0.466025,-0.044311,-0.210296,-0.141423,-0.622933,-0.208835,0.196164,0.000847,-0.486956,0.323266,0.305043,0.074537,0.030075,-0.042282,-0.021662,0.413091,-0.093275,0.403128,-0.215872,0.056271,-0.329355,-0.317605,0.771867,-0.487206,-0.021961,-0.020953,0.130995,-0.223272,0.073626,-0.159191,-0.096699,-0.147388,-0.071963,0.580760,-0.124606,0.147496,-0.625288,0.165936,-0.152885,0.443116,0.042417,-0.337407,-0.077975,-0.656292,-0.081346,-0.094159,-0.221463,-0.028145,0.223507,-0.429113,0.434381,-0.879311,0.388550,-0.008882,0.741756,-0.447435,0.374366,0.126205,0.408319,-0.157022,-0.225902,0.523006,-0.144578,0.342285,0.206203,0.094392,-0.160425,0.093314,-0.655746,0.303001', '26759819', '26670686', '26316956', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35418583', '余命10年', '剧情', '20岁的茉莉因患病被告知仅剩10年寿命。为了不对活着这件事抱有执念，她决定不再恋爱。直到她在同窗会遇到了和人...原作者小坂流加和主人公茉莉一样身患绝症，并于2017年2月文库本发行前夕离世。', '小松菜奈', '藤井道人', 7, 9473, 'tt16444750', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2781473147.jpg', 1, 7.6, 46.2, 32.7, 12.5, '0.014579,-0.186519,-0.674882,-0.163478,-0.127536,-0.135318,0.710401,-0.231805,-0.842559,-0.574932,-0.059468,0.710815,-0.449387,0.376223,0.402191,-0.409418,-0.077881,-0.674702,0.126834,-0.615612,-0.202266,-0.412283,0.229352,-0.189088,-0.433873,-0.594708,0.724342,0.052471,0.370543,0.491074,-0.126848,0.571488,0.383739,0.230529,-0.051445,0.176564,-0.233804,0.255306,-0.419102,0.473743,0.250673,-0.266653,0.001846,-0.154530,-0.090668,0.360742,0.805693,-0.239227,-0.303410,-0.291799,0.527919,-0.262194,-0.245408,0.118725,0.316364,0.092005,0.212892,0.882055,-0.413565,-0.458470,-0.115821,-0.571889,-0.245042,0.176348,0.031603,0.260921,-0.406293,0.564817,-0.350791,0.515682,0.215859,-0.433695,-0.022891,0.876475,0.187106,0.290645,-0.178646,0.064698,-0.742856,0.682037,1.113796,-0.036348,-0.146449,0.483197,-0.100946,-0.317677,-0.164571,-0.369804,-0.507317,0.406211,-0.060240,0.433486,-0.477727,0.348338,-0.079159,-0.110332,0.035077,-0.148023,0.628626,-0.405967,-0.203392,0.086751,-0.543049,-0.584233,-0.354611,-0.026169,0.186566,-0.514789,0.888524,-1.148922,0.649505,0.400027,0.763038,-0.654208,1.085851,0.271236,-0.175532,-0.043931,0.474608,0.540715,-0.492170,0.105142,0.281682,-0.233503,0.493031,-0.136547,-0.193523,-0.117578', '25721544', '35030151', '3212120', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35422807', '扬名立万', '剧情', '月黑风高之夜，一群电影人被秘密召集到一起，欲将轰动一时的血案翻拍成电影，借此扬名立万。殊不知他们正身处案发现场，并步步陷入一个巨大迷局之中，而凶手就在他们中间……伴随着利欲熏天的创作风暴，案件背后的故事似乎也更加扑朔迷离，戏中戏、案中案、局中局、人外人，环环相扣，一场野心与良心的较量愈演愈烈。究竟是命悬一线，还是另有惊天逆转？爱与温暖的血色花又能否从快将干涸的血河中终极绽放？一切都有待揭开。', '尹正', '刘循子墨', 7.4, 650697, 'tt16043930', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2724443759.jpg', 1, 5.2, 31.3, 48.9, 13.6, '-0.034592,0.069777,-0.709295,0.404912,0.248601,0.155745,0.880935,-0.060062,-0.470381,0.107897,0.270242,0.448636,-0.545369,0.003982,0.159266,-0.110187,-0.252884,-1.003191,-0.181005,-0.097643,-0.121779,-0.297842,-0.624840,0.120205,0.068349,0.022647,0.632276,0.680987,-0.239392,0.134935,0.320645,0.189082,-0.786195,0.603687,-0.034870,-0.173687,-0.233763,0.028609,-0.317167,-0.015969,-0.048530,-0.617561,-0.342530,0.304288,-0.342758,0.282599,0.670677,-0.549994,0.075332,-0.050074,0.168774,-0.538516,-0.219580,0.233598,0.137765,0.118914,0.270010,0.504542,-0.163886,-0.033498,0.066863,-0.340758,-0.790190,0.022628,0.288166,0.098115,-0.324698,0.166949,0.123861,-0.200972,0.186002,0.058180,0.145075,-0.009090,0.487014,0.375847,-0.221817,-0.277322,-0.542007,0.044809,0.619576,-0.030131,-0.227026,0.316477,0.180613,-0.193004,-0.364993,0.010524,-0.033149,-0.171797,0.599315,0.076008,-0.016723,0.451586,-0.546635,0.312861,-0.194498,-0.098679,-0.334711,-0.460507,-0.194032,-0.199053,-0.491875,0.307960,-0.064793,0.310533,0.150240,-0.158038,0.371352,-0.280849,0.282349,0.584249,-0.059787,-0.187769,0.329031,0.098321,0.115813,-0.202510,-0.354758,-0.113125,-0.039331,0.296390,0.127658,0.181681,-0.310527,0.103630,-0.440113,0.539783', '25828589', '25909236', '21339377', '4023433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3543262', '夏威夷男孩', '剧情', '追寻着杂志上报道的月虹，日本男孩玲雄（冈田将生 饰）和女友来到夏威夷岛旅行，邂逅了岛北端霍诺卡坷村镇上的老式影院。半年后，从大学休学的玲雄独自回到镇上，在影院担任放映助理。他逐渐融入当地简单安详的生活，并和擅长料理又爱恶作剧的比婆婆（倍赏千惠子 饰）成为了朋友。比婆婆邀请玲雄每天到她家享用美食，两人结伴到山谷中等待月虹。一天玲雄结识了活泼爱笑的姑娘玛莱亚（长谷川润 饰），后者很快成为他生活中的阳光。被冷落的比婆婆闷闷不乐，玲雄却浑然不觉。生日当晚玲雄带玛莱亚到比婆婆家吃饭，玛莱亚因比婆婆的料理过敏入院。玲雄打电话质问比婆婆，却得知她突然失明的消息。同时玲雄工作的影院正面临停业。在夏威夷轻柔吹拂的海风中，男孩悄然经历着成长的抉择。影片改编自吉田玲雄的同名随笔故事书，以作者的亲身经历写成，书中许多人物实际存在。主题曲《虹が消えるまで》由小泉今日子演唱，她和作者是多年的好朋友。', '冈田将生', '真田敦', 8.1, 17342, 'tt1375730', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2202387821.jpg', 0.3, 1.8, 22.1, 46.6, 29.2, '0.160990,-0.086359,-0.474203,0.335896,0.036950,-0.161406,0.436203,0.228779,-0.436111,-0.259596,0.134518,0.668132,-0.298146,0.481048,0.498602,-0.118880,-0.362949,-0.349016,0.243330,-0.119565,-0.105415,-0.323402,-0.123361,-0.021691,-0.005553,-0.359653,0.404723,-0.046233,0.014433,0.423320,-0.012004,0.143698,-0.240898,0.242813,-0.170211,0.090367,-0.115962,0.234979,-0.292124,0.231517,-0.061671,-0.176232,-0.310675,-0.314368,0.355134,0.276995,0.529435,-0.099846,-0.222268,-0.207063,0.528004,-0.115040,-0.231169,-0.009556,0.449934,0.251514,0.268446,0.187734,-0.378357,-0.030661,-0.263237,-0.462014,-0.202433,0.188450,0.355491,0.170742,-0.471384,0.292250,0.010228,-0.007570,0.254825,-0.423285,0.106085,0.168314,-0.098545,0.567972,0.059315,0.217748,-0.262844,0.407411,0.544188,0.033441,0.021316,0.322823,-0.026296,-0.086038,0.160604,-0.285501,-0.525198,0.149553,-0.058463,0.019825,-0.107634,0.283764,-0.361354,0.032910,-0.112831,-0.321692,0.365083,-0.308395,-0.347122,-0.853029,-0.053159,-0.384845,0.105312,0.022477,0.142407,-0.296890,0.672231,-0.750654,0.178081,0.404976,0.238036,-0.144281,0.485509,-0.071003,-0.032935,-0.195805,0.025400,0.300872,-0.066602,0.191932,0.073759,0.313992,-0.196851,0.072678,-0.471998,0.293585', '3811356'