INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3543318', '傲慢与偏见与僵尸', '动作', '不列颠向全世界扩张，他们在带回可观财富的同时，也带回了可怕的瘟疫。僵尸病毒旋即在英国肆虐，为了生存上流社会的贵族小姐们也不得不学习日本或中国武功保护自己。不久前爆发过僵尸骚乱的尼日斐庄园迎来新的主人查尔斯·宾利（道格拉斯·布斯 Douglas Booth 饰），住在隔壁的班纳特夫人第一时间带着五位身怀绝技且貌美如花的女儿去参加对方的晚宴，渴望建立一段美好的姻缘。晚宴之上，简·班纳特（贝拉·希思科特 Bella Heathcote 饰）与宾利互有好感，伊丽莎白（莉莉·詹姆斯 Lily James 饰）则和宾利的好友上校达西（萨姆·赖利 Sam Riley 饰）因为各种缘由而相互厌恶。丧尸危机接连爆发，达西将与伊丽莎白在战斗中加深理解……©豆瓣', '莉莉·詹姆斯', '布尔·斯蒂尔斯', 5.8, 28226, 'tt1374989', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2313785116.jpg', 6.2, 24.7, 47.9, 16.3, 5, '0.174282,-0.005580,-0.726657,0.581984,0.080735,-0.271968,0.838792,-0.028228,-0.455111,-0.278783,0.337843,0.734919,-0.400947,0.273850,0.349106,-0.028035,-0.275340,-0.474270,0.015887,-0.042050,-0.306502,-0.371717,-0.212956,-0.591947,0.087496,-0.377484,0.311471,0.130210,-0.126727,0.573312,0.206607,0.603284,-0.262789,0.419913,-0.087815,-0.222205,0.175364,-0.179953,-0.450694,0.169469,-0.022090,-0.150740,-0.079817,0.118194,0.221597,0.151451,0.699159,-0.452779,0.203962,-0.269928,0.074823,-0.094669,0.083237,0.254573,0.286357,-0.030331,0.088545,0.137294,0.010012,-0.032745,-0.128734,-0.051868,-0.580621,-0.056437,-0.070577,0.161512,-0.521587,0.563185,-0.114216,-0.232758,-0.024925,-0.221046,-0.073646,0.343633,-0.068053,0.126299,-0.121716,0.323092,-0.518791,0.012632,0.678265,0.049424,-0.226740,0.144181,-0.490326,-0.443001,-0.006668,-0.061567,-0.581334,-0.239535,0.556866,-0.043431,0.248280,0.586191,-0.733504,-0.158099,-0.403684,-0.284451,0.101324,-0.246759,-0.069392,-0.945349,-0.191618,-0.459901,-0.193605,-0.240519,0.334130,-0.099449,0.843711,-0.792530,0.219465,0.438664,0.464869,-0.452893,0.370233,0.020599,0.350737,-0.075589,-0.528402,0.227190,-0.001900,0.217183,0.098996,0.158648,0.076458,-0.145353,-0.290722,0.624327', '11541282', '3005387', '3811356', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35437945', '枕刀歌之尘世行', '动作', '“视而不见，与刽子手同罪”。系列首部超长剧场版，故事围绕发生在山东临清诸多江湖门派之间波诡云谲的斗争展开，主角漕帮少主罗通卷入了一场针对漕帮的阴谋，面对即将覆灭的漕帮，以及众多江湖门派的追杀，罗通在青梅竹马红娘、营造神工江渊、莽撞的义士龙顺的帮助下，一步步接近真相，每个人都有自己的信仰和坚持，并由此发生了一场场酣畅淋漓的热血战斗……', '藤新', '薛锦胜', 7.6, 8996, '', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2641407927.jpg', 1, 4.1, 28.3, 47.3, 19.2, '0.189590,-0.034306,-0.688789,0.414082,0.307784,0.445788,0.700902,-0.000657,-0.439274,-0.211795,0.537260,0.538125,-0.237488,-0.229016,0.355220,-0.595900,0.013739,-0.969597,-0.281095,0.148317,0.003571,-0.292621,-0.230417,-0.137526,-0.125268,-0.157014,0.792923,0.354728,-0.489653,0.314955,0.469129,0.285322,-0.610573,0.356003,0.095182,0.013457,0.089141,0.303009,-0.542261,-0.151244,-0.432987,-0.238662,-0.260651,0.115948,-0.227306,0.249490,0.602822,-0.534288,-0.114819,-0.029190,0.239779,-0.438529,-0.169747,-0.005495,0.504721,0.154574,-0.125358,0.617105,0.122684,-0.013733,-0.158480,0.129512,-1.062561,-0.118723,0.494290,0.263644,-0.363977,0.605436,0.339286,-0.013826,-0.032234,0.101377,0.133040,0.819289,0.682152,0.011189,-0.012899,-0.114112,-0.566450,0.294790,1.043847,-0.066465,-0.254907,0.120116,-0.031877,-0.019270,-0.095170,-0.536955,-0.273503,-0.135093,0.224661,-0.093594,-0.155535,0.809371,-0.540299,0.008427,0.025524,-0.223331,0.275867,-0.458949,0.079056,-0.710251,-0.555294,-0.465681,-0.203216,-0.124115,0.208398,-0.370625,0.841599,-0.718844,0.050563,0.537707,-0.009331,-0.628412,0.573633,0.289342,0.217717,-0.079352,-0.204236,0.189914,0.222065,0.205310,-0.227759,0.260795,-0.033662,0.118045,-0.128196,0.207970', '26678784', '25917239', '4301278', '25978126');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35441371', '隔窗恋爱', '喜剧', '拉奎尔疯狂且不可救药地爱上了迷人而神秘的邻居阿瑞斯。虽然她一直默默地关注着阿瑞斯，但令她沮丧的是，他们却从来没有说过一句话。但是拉奎尔的目标很明确：让阿瑞斯爱上自己。然而，她不是一个傻白甜女孩，她并没想过为此倾尽所有，更不会迷失自我······', '胡利奥·佩纳', '马塞尔·弗雷斯', 5.8, 11647, 'tt14463484', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2826255117.jpg', 6.7, 25.9, 43.6, 16, 7.9, '0.383034,0.100529,-1.102878,0.782614,-0.599851,-0.239255,1.318461,-0.466149,-0.791381,-0.118408,-0.029408,0.478571,-0.136272,0.150471,-0.087504,0.365014,-0.066685,-0.454419,0.318712,0.159272,-0.151827,-0.584833,-0.085205,-0.268996,-0.512950,-0.119024,0.478633,-0.004531,-0.269536,0.359261,0.302078,0.167850,0.444248,1.100124,-0.265888,-0.003560,-0.186189,0.135067,0.168400,0.092875,0.223919,-0.239585,-0.673384,0.985815,-0.335834,0.518311,0.116500,-0.392962,-0.164055,0.196679,0.051220,-0.741760,-0.027147,0.157396,0.171605,-0.190959,0.182347,0.102449,0.142455,-0.308886,0.095589,0.116248,-1.100013,0.031332,-0.058136,0.281524,-0.389443,0.422864,-0.418354,0.100766,0.004622,-0.375512,0.049051,-0.095281,0.247134,-0.070745,-0.353559,-0.129740,-0.444700,0.375064,0.903430,-0.150493,-0.301345,0.635622,-0.343218,-0.400339,-0.260695,-0.020960,-0.732888,0.336086,-0.167862,0.440107,-0.261722,0.255584,-0.272524,0.127756,-0.351729,-0.351978,-0.125238,-0.925094,0.004919,0.155815,-0.071207,-0.622173,-0.446065,-0.157704,-0.412248,-0.175148,0.529944,-1.033556,0.289427,0.485525,0.546883,-0.732503,0.520846,0.536518,-0.293908,0.035015,-0.106096,0.841500,-0.029716,-0.018661,0.408691,0.332871,0.354965,-0.203502,-0.267827,0.832352', '1296370', '3059036', '26352435', '1309171');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35444998', '李茂扮太子', '喜剧', '富家女杨家珍（马丽 饰）与小捕快李茂（常远 饰）成婚，虽夫妻恩爱，但始终得不到家珍父母的认可。李茂意外发现自己竟与当朝太子相貌相同，一个想进宫获得晋升，一个想出宫获得自由，二人交换身份，却不知正一步步卷入尚书的阴谋里……', '马丽', '高可', 4.3, 135108, 'tt17005404', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2812626447.jpg', 25, 43.6, 26.3, 4.1, 1.1, '0.161609,0.454944,-0.417357,0.736982,0.105832,-0.465244,0.665144,0.022612,-0.467370,-0.779206,0.220760,0.606655,-0.259543,-0.033022,0.077098,-0.046480,0.038729,-0.285923,0.365190,-0.211051,0.143397,-0.638421,-0.471223,0.053835,-0.268027,0.119828,0.884170,-0.165387,0.027311,0.799411,0.551331,-0.080527,-0.272948,0.330254,-0.146517,0.231953,0.103867,0.454426,-0.483483,-0.074104,-0.083985,-0.168559,-0.638958,-0.079407,0.238484,0.352293,0.280038,-0.321231,0.065865,-0.284880,0.301571,0.282734,-0.144599,0.405467,0.025503,0.436717,0.173806,0.128865,-0.060921,0.156326,0.201266,0.001583,-0.449637,0.183882,0.400363,0.165508,-0.067689,0.092081,0.007302,-0.218937,-0.162114,-0.359282,0.139832,0.407051,-0.011117,0.297582,-0.425137,0.098887,-0.646996,0.145884,0.772518,-0.082035,-0.079954,0.071719,-0.131718,-0.480866,0.426957,-0.389474,-0.298311,0.068909,-0.088484,0.435232,0.125060,0.187982,0.077284,0.027481,-0.625781,0.590241,0.169280,-0.455179,0.461548,-0.136443,-0.292971,-0.255509,-0.540689,0.254132,0.176373,-0.542164,0.416471,-0.563572,-0.022018,-0.038876,0.473999,-1.084377,0.517101,0.532277,0.449939,-0.453609,-0.338719,-0.045029,0.080468,-0.408449,-0.266094,-0.038327,-0.324228,-0.363947,-0.492796,-0.179944', '1484760', '1395445', '1300883', '3670447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35446144', '以年为单位的恋爱', '爱情', '故事开始于跨年夜那一天，独自在异乡打拼的陆鹿珊（毛晓彤 饰）和江宇（杨玏 饰）在机缘巧合之下相识了。这一天特殊的气氛让这两个年轻人感觉对方特别的亲切，凌冽的空气中，两颗寂寞的心迅速靠近。之后，陆鹿珊和江宇便火速展开了他们甜蜜的恋情。陆鹿珊从很小的时候就开始了漂泊独立的生活，常年的动荡让她格外的渴望一份只属于她的安全感。江宇则和大部分男人一样，像个长不大的孩子，对未来一片迷茫。正处于事业上升期的他似乎并没有打算把成家写进自己的行程表中。恋爱节奏的不统一让陆鹿珊和江宇之间屡屡爆发矛盾，几番争吵之后，两人都开始思索，对方是不是真的就是那个对的人。©豆瓣', '毛晓彤', '黎志', 5.2, 45609, 'tt18266996', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2715903096.jpg', 8.4, 36.3, 44.8, 8.5, 2.1, '0.332539,0.167813,-1.034939,0.701446,-0.142700,-0.284280,0.811712,0.214869,-0.649557,-0.043621,-0.070618,0.685071,-0.425939,0.409049,-0.030937,-0.069803,-0.317477,-1.079916,-0.350772,-0.081464,-0.290755,-0.188788,-0.243641,-0.032815,-0.297778,-0.144977,0.535117,0.120380,-0.201379,0.537986,0.183279,0.159792,-0.075479,0.979762,-0.240168,0.050546,0.046139,0.275100,-0.210952,-0.202638,0.380181,-0.145969,-0.193780,0.308587,0.115766,0.405764,0.919255,-0.330398,-0.274276,0.116461,0.222167,-0.177548,-0.514433,0.194394,0.233244,0.069002,0.320998,-0.030855,-0.167326,-0.033831,-0.084160,-0.036625,-0.624759,0.068655,-0.048556,0.239460,-0.444971,0.558332,0.026423,-0.123602,0.164779,-0.304834,0.292871,0.540635,0.086373,0.563014,-0.412915,-0.106533,-0.394823,0.171690,0.926157,0.007737,-0.264524,0.717026,-0.347195,-0.461540,-0.310122,0.362039,-0.592119,-0.287390,0.360878,0.048190,-0.222703,0.234484,-0.791441,0.259384,-0.127559,-0.040841,-0.180527,-0.634197,-0.223635,-0.246010,-0.298411,-0.767345,-0.403934,0.289663,0.040506,-0.300489,0.727250,-0.894075,0.252215,0.252082,0.257653,-0.568508,0.490748,0.015094,0.154573,-0.219582,-0.029558,0.232302,-0.394791,0.141007,0.295351,0.733214,-0.166373,0.197462,-0.468621,0.683904', '1301022', '1302109', '3077673', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35448536', '未来罪行', '剧情', '该片深入探索不远的未来，人类正在学习适应其合成环境，这种进化使人类超越自然状态，开始变形，改变他们的生物构成。有些人欣然接受超人文主义的无限潜力，而另一些人则试图控制它。不管怎样，“加速进化综合症”正在迅速蔓延。索尔·滕泽是一位深受喜爱的行为艺术家，他接受了加速进化综 合症，身体里长出了意想不到的新器官。滕泽和他的搭档卡普利斯一起将摘除这些器官的过程变成了一场奇观——在剧院里实时操作，让其忠实的拥护者们惊叹。但是在政府和奇怪的亚文化共同关注的情况下，滕泽被迫考虑什么将是他最令人震惊的表演。', '维果·莫腾森', '大卫·柯南伯格', 6.2, 14780, 'tt14549466', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2872980656.jpg', 5.2, 18.3, 44.5, 24.2, 7.8, '0.275755,0.068094,-0.575673,0.504270,-0.109431,0.156661,0.584689,0.064233,-0.431811,-0.188668,0.252648,0.517972,-0.381045,-0.038208,0.074412,-0.321432,-0.208737,-0.379913,-0.058185,0.116147,-0.643179,-0.336739,-0.432025,-0.389907,-0.258355,-0.441264,0.889596,0.044703,-0.639934,0.154366,0.017835,0.376561,-0.022909,0.329828,-0.042226,-0.134436,-0.065560,-0.310178,-0.151929,0.090335,0.146279,-0.078667,0.056604,0.464489,-0.219580,0.036779,0.831826,-0.538294,-0.236033,-0.297194,0.607335,-0.330654,-0.049406,0.107061,0.177622,0.426292,-0.072506,-0.281567,-0.149760,0.109150,-0.123302,0.183900,-1.069473,-0.161512,0.158029,0.244934,-0.418169,-0.002378,0.233056,-0.217172,0.093610,-0.341741,0.030704,0.543916,0.222590,0.396648,-0.341942,-0.049029,-0.334135,-0.176321,0.732375,-0.004964,-0.872566,0.332887,-0.484784,-0.605199,-0.342190,-0.301713,-0.255879,-0.272809,0.004025,0.518030,-0.034914,0.475587,-0.642755,0.195823,-0.156389,-0.440369,-0.132907,-0.288846,0.038252,-0.834673,-0.171298,-0.358889,-0.051924,-0.247148,0.004821,-0.591394,0.901650,-0.810180,0.020527,0.686250,0.368542,-0.605163,0.501551,-0.241471,0.183721,-0.365314,-0.378619,0.197847,0.063431,0.279297,-0.003805,0.487601,-0.000963,0.184087,-0.585160,0.679544', '26759820', '24284209', '26667010', '35377026');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35453728', '东北恋哥', '剧情', '二十世纪90年代末的哈尔滨，小青年于铁在替人收债时与借贷人的女儿金佳丽一见钟情。于铁通过自己的善良、爱与执着，打开了金佳丽封闭的内心。在两人即将携手奔赴幸福之时，突如其来的意外，打断了于铁所有的计划。', '包贝尔', '秦小珍', 4.6, 9905, 'tt14725096', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2695153935.jpg', 25.2, 34, 29.1, 7.5, 4.2, '-0.451811,0.140041,-1.225555,0.431937,-0.188529,-0.525989,0.957288,0.082246,-0.400893,-0.017554,-0.326731,0.725182,-0.063316,0.157676,1.009930,-0.243171,-0.007441,-0.685443,-0.802894,-0.073208,-0.159667,-0.325098,-0.090021,-0.560534,-0.293367,-0.415148,0.605848,0.234177,-0.598771,0.219732,0.590718,0.544754,-0.565632,0.274238,0.090070,-0.260129,-0.117985,0.381593,-0.781378,-0.068373,-0.200985,-0.226013,-0.172223,-0.018835,-0.168984,0.207541,0.746232,-1.028214,-0.156678,0.106416,0.247178,-0.085932,-0.286020,-0.334243,-0.363845,0.113045,0.131022,0.144053,-0.287312,0.031814,0.684560,-0.456547,-0.418490,-0.512659,0.250498,-0.163273,-0.453202,0.997176,-0.163652,0.525399,0.086454,-0.731756,0.103137,0.254571,0.343771,0.593803,-0.044228,-0.042569,-0.206552,0.168919,0.957888,0.542235,-0.510589,0.076041,-0.283718,-0.438364,-0.107929,0.003521,-0.564295,0.149667,0.804984,0.283502,-0.159598,0.707304,-0.537235,-0.186225,-0.050021,0.465847,0.392008,-0.299482,-0.206700,-0.423635,0.121368,-0.710007,-0.298672,0.136858,0.313392,0.020443,0.617848,-1.011381,0.282504,0.149851,0.025891,-0.420698,0.813845,0.062450,0.046933,-0.160830,-0.107685,-0.046077,0.083187,0.633387,0.294050,0.280610,-0.590115,0.071439,-0.514535,0.434024', '1292211', '26687241', '1296792', '27056299');
