INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3546019', '赵氏孤儿', '剧情', '《赵氏孤儿》豆瓣官方小站：http://site.douban.com/107923/春秋时期，晋灵公不喜权臣屠岸贾（王学圻 饰）当道，且厌丞相赵盾（鲍国安 饰）专横。赵盾之子赵朔（赵文卓 饰）双喜临门，不仅战功卓著，而且妻子庄姬（范冰冰 饰）也身怀六甲。屠岸贾视之为 心腹大患，设计在朝堂上投毒，借灵公之口，灭赵氏九族。庄姬在大夫程婴（葛优 饰）诊脉时，目睹夫君赵朔身亡，悲痛中决定生下婴儿。此时，屠岸贾手下韩厥（黄晓明 饰）前来灭种。临危之际，庄姬将婴儿托付程婴，让他交给公孙杵臼（张丰毅 饰），后拔剑自刎。韩厥因此被屠岸贾砍伤，后者下令封城，挨家挨户搜查婴儿。情急之下，程妻（海清 饰）把赵孤交上。程婴前去认领赵孤，程妻去见公孙杵臼。因封城，程妻母子被藏于影壁墙内。屠岸贾设苦肉计，逼程婴说出婴儿下落，相继诛杀公孙杵臼及程妻母子。程婴强忍悲痛，独自抚养赵孤。韩厥在求医时了解到真相，与程婴结下生死同盟。程婴携赵孤投奔屠岸贾门下，并让屠岸贾认下赵孤为义子。从此，展开了长达 15年的复仇计划……', '葛优', '陈凯歌', 6, 170986, 'tt1726738', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p819200277.jpg', 3.6, 17.8, 55.8, 18.8, 3.9, '-0.379557,0.250458,-0.445734,0.054075,0.241612,0.058892,0.365261,0.212346,-0.423632,-0.313572,0.347760,0.430216,-0.105737,0.058747,-0.025892,-0.288575,-0.089974,-0.520510,-0.253015,0.096595,0.035802,-0.318470,0.098886,-0.185712,-0.485370,-0.099116,0.422654,-0.122748,0.157368,0.433869,0.530657,0.227341,-0.505147,0.267164,0.155540,0.161240,-0.378205,-0.062694,-0.438040,0.273885,-0.106693,-0.294886,-0.144732,-0.117181,-0.235394,0.346375,0.529298,-0.234268,0.287679,-0.523617,0.239754,-0.067071,0.016346,0.324911,0.241769,0.076289,0.003728,0.393099,-0.211879,0.037188,0.305625,-0.226780,-0.239559,-0.061852,0.318425,-0.077729,-0.456689,0.301823,-0.274613,0.088618,0.042763,-0.358840,0.253141,0.272810,0.260093,0.040035,-0.259670,0.022097,-0.097118,0.496831,0.308963,-0.135194,0.428443,-0.207443,0.342811,-0.472091,0.475584,-0.115181,-0.164070,0.114312,0.390207,0.062327,-0.024785,0.141256,0.188442,-0.730335,-0.407099,0.682425,0.232988,-0.012872,0.257714,-0.099689,-0.075050,0.132211,-0.089027,-0.049718,0.202341,-0.267174,0.217588,-0.034850,0.224077,-0.144374,0.218453,-0.713932,0.168526,0.032921,0.342272,-0.125060,0.026980,0.265112,0.386230,0.000475,0.285510,-0.232225,-0.428925,0.011757,-0.257493,-0.259641', '1304021', '1302110', '4821046', '1305201');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3546035', '高考1977', '剧情', '1977年，搅扰中国人民整整十个年头的文化大革命业已结束。人民的生活重新步上正轨，在这百业待兴之际，中断了多年的高考也得以恢复。东北某农场内，生活着一群来自四面八方、身份各异的知青。他们将最好的年华献给了这片黑土地，却不知自己的明天将在何方。恢复高考的消息传到这里，让 年轻人们的心再次躁动起来。适逢农场负责人老迟（孙海英 饰）正在酝酿修路计划，只要在建设中取得良好表现就有机会受推荐去念大学。知青们为此蠢蠢欲动，而另有打算的老迟却把机会给了成分不好的女孩陈琼（周显欣 饰）。原来陈琼和老迟的爱将潘志友（王学兵 饰）是一对情侣，他打算借此将二人拆散，让潘扎根于此。然而充满着理想的年轻人是会紧紧抓住这个难得的机遇，还是随波逐流接受命运的安排？©豆瓣', '王学兵', '江海洋', 7.2, 24085, 'tt1562900', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2374048891.jpg', 1.2, 5.7, 37.9, 41.3, 13.9, '0.045574,0.206490,-0.618668,0.446644,-0.088452,-0.268827,0.442703,0.006759,-0.596529,-0.034815,-0.063310,0.405423,-0.118554,0.422654,0.277615,-0.131374,-0.248819,-0.667235,-0.152934,-0.045739,-0.098856,-0.168934,-0.307162,-0.107280,-0.264656,-0.291815,0.733620,0.292355,-0.005719,0.426785,0.174180,0.173287,0.141043,0.393993,-0.211272,-0.062101,-0.049183,0.045877,-0.388868,0.188736,0.092669,-0.359443,-0.207326,0.140304,0.122885,0.279156,0.770792,-0.071827,-0.290019,-0.020466,0.490166,-0.228842,-0.120221,0.171862,0.205255,0.103681,-0.038048,0.228829,-0.415854,0.108827,0.009429,-0.275715,-0.541009,-0.020139,0.149181,0.048726,-0.682191,0.465481,0.177902,-0.059957,-0.091084,-0.340114,0.254982,0.630677,0.190412,0.420411,-0.204817,-0.021990,-0.360199,0.316611,0.821497,-0.110115,-0.165232,0.086677,-0.295384,-0.435037,0.179803,-0.030398,-0.445713,-0.311736,0.219361,0.133380,-0.192756,0.093577,-0.484808,0.053559,-0.195454,-0.391288,0.206702,-0.392372,-0.110203,-0.391243,-0.155521,-0.218967,-0.306187,0.310072,0.165780,-0.210180,0.889355,-0.872674,0.166461,0.365206,0.183142,-0.542325,0.642941,0.036963,0.172389,-0.307021,-0.022494,-0.078290,-0.287816,0.452943,0.208086,0.237141,-0.307745,-0.376082,-0.462050,0.480988', '35030151', '3445516', '1826173', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35461732', '赘婿之吉兴高照', '剧情', '苏氏布行二房长子，曾经一心想要拿到掌印继承苏家，却在与妹妹苏檀儿的竞争中被宁毅击败。宁毅与苏檀儿离开江宁移居武都，走前将苏氏布行名义上交给他管理，本来已经对执掌苏家毫无希望的苏文兴，重燃热情。 看着蒸蒸日上的业绩，苏文兴将功劳归结于自己，只是他还有一顾虑，既然大房已经移居武都，为何苏愈还不将掌印传予自己。一次意外，他从家丁口中听到了真相，原来在众人眼中他只是苏氏布行的一个吉祥物。 自尊心受辱的苏文兴准备离开江宁前往富源做出一番事业，证明自己的能力，摆脱宁毅的阴影。但谁想来到富源接连受挫，甚至赔光了本钱。就在他绝望之际，昔日同窗突然出现，答应帮助他力挽狂澜，但有个条件......', '刘冠麟', '赵启辰', 5.8, 7486, '赘婿电影版', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2675423447.jpg', 5.1, 19.4, 58.2, 12.9, 4.3, '0.179170,0.317574,-0.978781,0.471412,-0.321219,-0.452938,0.544023,0.190667,-0.610682,-0.179928,0.216294,0.918505,-0.062951,0.165256,0.086874,0.079910,0.046744,-0.731888,0.051355,-0.141619,-0.075256,-0.672328,-0.201342,-0.277655,-0.124581,-0.090936,0.494839,0.265358,-0.218624,0.330247,0.250174,-0.038463,-0.025752,0.617663,-0.208827,0.096406,-0.174026,0.089516,-0.340202,0.197043,0.238857,-0.539642,-0.338978,0.281040,0.119185,0.288544,0.399529,-0.161301,-0.116136,0.003371,0.054740,-0.321846,-0.151751,0.378042,0.066590,-0.031530,0.020682,0.440889,-0.388233,-0.127003,0.035492,-0.232481,-0.768362,0.043134,0.043370,-0.024165,-0.864768,0.423241,-0.210160,-0.146509,0.005400,-0.530913,0.118051,0.438701,0.184122,0.347278,-0.567687,0.285069,-0.548900,-0.085517,0.800031,-0.138715,0.139313,0.133908,0.108936,-0.308972,-0.070651,-0.053756,-0.255264,0.044299,0.305420,0.114506,0.095997,0.068562,-0.338850,-0.117691,-0.409254,-0.215178,0.040527,-0.331738,0.055705,0.080119,-0.277302,0.027216,-0.525905,0.038519,0.398628,-0.310212,0.616219,-0.780285,0.024523,-0.011798,0.652100,-0.708072,0.377728,0.034636,0.302049,-0.002275,-0.076493,-0.157306,0.171632,0.174453,0.257343,0.059317,-0.078456,-0.219097,0.021933,0.382616', '1301022', '3215099', '1299965', '25908042');
