INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35465742', '在你面前', '剧情', '擅以极简手法挖掘男女情感关系的韩国名导洪常秀，新作《在你面前》让缪斯金珉禧退居幕后，邀来韩国影视资深女星李慧英饰演一位重新适应韩国生活的中年女子，埋着秘密和姊姊生活在一起，她和一名导演相约在首尔巷弄里的小酒吧見面，正当两人打开话题、酒酣耳热之际，外头突然下起倾盆雷雨。洪常秀以看似日常的举止，韵味十足的对白，男女一来一往间，竟也带出衰老与死亡的生命顿悟。', '李慧英', '洪常秀', 7.5, 7269, 'tt14776918', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2692035069.jpg', 1, 3.3, 30.4, 48, 17.3, '0.129764,0.232320,-0.470940,0.474852,0.074153,-0.204584,0.935692,0.161851,-0.255419,-0.406319,0.045639,0.665694,-0.464806,0.384624,0.486289,-0.316082,-0.456896,-0.730069,-0.310222,0.078414,-0.035457,-0.027758,-0.373263,0.135278,-0.303965,-0.341413,0.562674,0.014778,-0.458161,0.526644,0.432707,0.027955,-0.598815,0.277077,-0.074016,-0.254354,0.317048,0.424257,-0.524640,0.163167,-0.108158,-0.383785,-0.279119,-0.237369,-0.121928,0.117127,0.643983,0.086484,-0.005932,0.044509,0.341985,0.193421,-0.014200,-0.048357,0.366518,0.017531,0.418492,0.130054,-0.213741,0.067244,-0.220620,-0.201275,-0.368571,0.235633,0.131673,0.224263,-0.358210,0.190168,0.226028,-0.227179,0.070416,-0.282290,0.120315,-0.054933,0.570813,0.399919,-0.079864,0.121735,-0.416466,0.094778,0.553361,0.414433,-0.269887,0.372506,-0.397436,-0.520180,-0.188730,0.055638,-0.323565,-0.452379,0.017379,-0.111788,-0.072388,0.248887,-0.618133,0.264621,0.184700,0.229740,0.099665,-0.159532,-0.076071,-1.028493,-0.116992,-0.477109,-0.244710,-0.009937,0.406657,0.092153,0.757700,-0.541737,0.160613,0.349009,0.264930,-0.143373,0.739229,0.233782,0.271603,-0.229573,-0.203508,0.008115,-0.148442,0.103836,-0.073258,0.466462,-0.776810,0.111342,-0.554279,0.189389', '10466639', '1322847', '24751811', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35472124', '普吉岛的最后黄昏', '剧情', '即将迎接曼谷的大学生活，离开普吉岛之前，德要给欧儿一个特别的一天……', '普提蓬·阿萨拉塔纳功', '纳卢拜·库诺', 8.8, 22920, 'tt19777850', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2652268085.jpg', 0.9, 1.9, 10.5, 31.9, 54.9, '0.375162,-0.167763,-0.703497,0.940810,0.290005,-0.599304,0.110212,0.225888,-0.212349,-0.817013,-0.001703,1.166741,-0.244114,0.712238,1.145629,-0.013723,0.062504,-0.546126,-0.061774,-0.320202,-0.776353,-0.061899,-0.188583,0.115107,-0.159042,-0.321883,0.496554,0.368484,0.396943,1.195799,-0.307447,0.026530,0.389749,0.577203,-0.545611,-0.567781,0.195902,0.354215,-0.503900,0.548566,0.398369,-0.055044,-0.195515,0.108286,0.353061,0.274104,0.510716,0.307638,-0.349584,-0.388580,0.447972,-0.483572,-0.321435,0.002379,0.435055,-0.405415,-0.019586,0.237065,-0.418426,0.472151,-0.137626,-0.921204,-0.447847,-0.068028,-0.092611,-0.335675,-0.519304,0.441294,0.192905,0.205063,0.206670,-0.073209,0.523414,1.069277,-0.089110,0.839443,0.035802,0.553799,-0.478444,-0.001545,1.340162,-0.360433,0.026793,0.714481,0.268519,0.040717,0.420685,0.352088,-0.704129,0.455855,-0.467339,0.213862,-0.513901,-0.255281,-1.031456,0.137008,-0.517870,-0.153574,0.429950,-0.282284,-0.201732,-1.189841,0.177910,0.110887,0.190358,0.400264,0.142677,0.176525,0.304687,-0.420854,0.595271,0.193923,0.389381,-0.630313,0.598534,0.010776,0.286539,-0.221068,0.481716,0.243759,0.378167,0.482480,-0.858447,0.440805,-0.273254,-0.208827,-0.490503,1.175462', '3147969', '26687241', '11541282', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35489675', '济公之降龙降世', '动画', '赤城山脚下永宁村，为了让久病缠身的娘病愈，顽童李修缘一心想成为大英雄，却总是好心办坏事，让村庄鸡飞狗跳。在遭遇了一场场险遇后，李修缘得知自己就是大英雄降龙罗汉转世。其父李茂春受金翎蛊惑，为保护李修缘而抢夺金身，欲替儿子承担拯救世人的使命。却被金翎抢走金身献给金翅大鹏，金翅大鹏因此提前复活，欲毁灭人间。最后，李修缘父子为了大爱牺牲小爱，携手以肉身抵抗金翅大鹏，却终究以卵击石。濒死的李修缘，终于顿悟比金身更重要的是爱，最终化身降龙罗汉。经历人间疾苦后，降龙罗汉最终放弃果位。从此，天上少了一名降龙罗汉，世间多了一个云游天下，济世救人的活佛。', '朱婧', '刘志江', 4.5, 18192, 'tt15072480', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2660158329.jpg', 21.1, 43.1, 29.7, 4.8, 1.3, '-0.379321,0.217241,-0.605565,0.197839,0.093227,-0.498388,0.178634,0.142382,-0.084916,-0.222085,0.106454,0.642463,0.198518,0.051900,-0.018978,-0.046028,0.282165,-0.159027,-0.000054,0.322038,-0.095086,-0.105459,-0.342947,0.135440,-0.289501,-0.205037,0.408344,0.193242,0.108184,0.148858,0.463856,0.276288,0.015785,0.008257,-0.132014,0.046780,-0.368551,0.493619,-0.121357,0.143648,-0.254328,-0.206245,-0.276790,0.350895,-0.493037,0.033896,0.099645,-0.528851,-0.136796,-0.851363,0.315563,-0.345473,-0.009855,-0.122064,0.102263,-0.147644,0.244841,0.422415,-0.127520,-0.113690,0.215482,-0.024105,-0.916301,-0.143894,0.229194,-0.303558,-0.446063,0.234743,0.190556,0.282955,0.117962,-0.049938,0.173133,0.312841,0.332205,0.221092,-0.218243,0.010323,-0.146389,0.194093,0.625552,-0.307833,-0.083574,0.103738,0.180335,-0.084452,0.184111,-0.686267,0.048017,-0.034990,0.201966,0.324855,0.071114,0.471624,-0.186430,-0.228638,-0.734385,0.415760,-0.216162,-0.079384,-0.008089,0.002230,0.232315,0.113162,-0.152619,-0.130566,0.456932,-0.168587,0.949253,-0.449863,0.501186,0.513618,0.249174,-0.600908,0.626130,0.201171,0.456275,-0.318567,0.233238,0.173251,0.084342,0.616313,0.127368,-0.354024,-0.135793,0.240322,-0.302045,0.369895', '24284209', '27602116', '30163500', '3718665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35496803', '河豚', '剧情', '南方某市法院开庭审理了一起毒杀案，被告人蒋漫枝（钟欣潼 饰）涉嫌用河豚毒素杀害其丈夫柳慕阳（张睿 饰）。辩护人栾珠（蒙亭宜 饰）坚称柳慕阳是自己误食了毒酸奶而非预谋杀害，此时另一条线索表明，八年前的一起强奸案，被害人就是如今的蒋漫枝，而强奸犯许一城竟然和被害者柳慕阳长得一模一样，千丝万缕的联系预示着这两起案件远没有那么简单。蒋漫枝为何会爱上曾性侵过自己的人，她又为何会再次痛下杀手？', '钟欣潼', '邢健钧', 4.9, 7275, 'Pufferfish', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2668712956.jpg', 11.1, 41.6, 41.2, 4.9, 1.1, '0.022845,-0.089991,-0.453763,0.524581,0.028127,-0.070852,0.760702,0.054710,-0.431878,-0.107021,0.302799,0.405812,0.111525,0.028293,0.086419,0.119262,-0.231123,-0.746328,0.148956,-0.494181,-0.701622,-0.721317,-0.288204,-0.194972,0.287475,0.091021,0.338866,-0.013754,-0.063252,0.280977,0.586713,0.382850,-0.375298,0.321046,-0.157486,0.004606,0.132321,0.177593,-0.287963,0.289435,0.326718,-0.419174,0.067474,0.247961,-0.262158,0.773762,0.324069,-0.225640,-0.262976,-0.516168,0.521764,-0.317443,-0.003173,0.185705,0.535304,0.043763,0.547467,0.534108,-0.397589,-0.478818,0.414362,0.184886,-0.618093,-0.036378,0.167937,0.271228,-0.216148,0.242711,-0.261429,0.160637,0.059029,-0.075867,0.147326,0.296792,0.332656,0.111072,-0.003919,-0.457045,-0.635039,0.277164,0.615414,0.081560,0.157483,0.122091,-0.067617,-0.403738,-0.102622,-0.139109,-0.062121,0.138183,0.257312,-0.087378,-0.105788,0.313068,-0.221092,-0.319087,-0.423866,0.697255,0.093221,0.026546,-0.180828,-0.168923,0.018746,-0.286786,-0.392332,0.032826,0.117633,-0.361334,0.119901,-0.580557,0.202394,0.581254,0.288705,-0.735878,0.303128,0.274481,-0.099481,-0.224057,-0.247623,0.010662,0.193269,0.092912,0.377714,0.164605,0.138231,-0.022629,-0.402086,0.124967', '35073886', '25862560', '3263169', '1296217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3550132', '非常主播', '剧情', '生活优渥的单身贵族南贤洙（车太贤 饰）曾是一名失败的歌手，年过而立后，他迎来了事业的第二春。贤洙所主持的谈话类节目备受欢迎，尤其是近段时间单身妈妈静南寻找生身父亲的故事更掀起收听率飙升的高潮。某晚，贤洙正等待和女友共度浪漫一夜的时候，一对不速之客破坏了这一切。来者正是静南（朴宝英 饰）和她6岁的儿子纪东，而她所寻找的父亲竟然是贤洙！原来，贤洙初三时曾和邻居大他5岁的女孩相恋，这唯一一次恋爱、唯一一次肉体之欢导致了女儿的诞生。当年的恋人在分手后隐瞒了怀孕的事实，贤洙则背井离乡去追寻自己的梦想。女儿和外孙的到来，令这个过惯单身生活且孩子气的大男人倍感困扰，更主要的是，在这个混乱复杂的娱乐圈里，这样的绯闻会令贤洙好不容易经营起来的事业毁于一旦。他该如何面对这突如其来的一切呢？©豆瓣', '车太贤', '姜炯哲', 7.9, 166132, 'tt1360795', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p547516194.jpg', 0.2, 1.3, 23.1, 51.8, 23.5, '-0.040216,-0.238542,-0.747036,0.586540,-0.206336,-0.395168,0.775415,0.083882,-0.675616,-0.415154,0.093222,0.713419,-0.272401,0.551431,0.450167,0.065732,0.077105,-0.593409,-0.151249,-0.128877,-0.251847,-0.177719,-0.342283,0.008276,-0.006435,-0.051023,0.702022,0.032599,-0.135881,0.342618,0.519133,0.139780,0.096093,0.414013,-0.209682,0.113682,0.008173,0.544050,-0.382828,0.045537,0.066842,-0.248020,-0.102333,0.257119,-0.230451,0.334335,0.596663,-0.339862,-0.298681,-0.062727,0.620474,-0.362690,-0.300074,0.136510,0.235370,-0.024333,0.374532,0.171271,-0.223192,-0.247180,-0.256389,-0.135077,-0.784578,0.055118,0.139557,-0.157335,-0.560442,0.571506,0.022354,-0.161080,0.200931,-0.180868,0.099025,0.815834,0.165508,0.469575,-0.435865,0.027231,-0.259193,0.447876,0.937783,0.063326,-0.123083,0.680864,-0.330650,-0.354493,-0.032110,-0.389534,-0.724087,0.134750,-0.060008,0.076511,-0.159084,0.459914,-0.379377,-0.042721,-0.227109,-0.006766,0.246102,-0.465598,-0.319932,-0.276364,-0.247470,-0.556487,-0.321518,0.048778,0.067806,-0.455512,0.807834,-0.956693,0.203232,0.434841,0.235920,-0.656647,0.693361,0.320049,0.246904,-0.291190,-0.106301,0.293956,-0.206496,0.160168,-0.157859,0.142244,0.028422,-0.169625,-0.566341,0.497957', '1296569', '25721544', '5985887', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35505100', '这个杀手不太冷静', '喜剧', '魏成功（魏翔 饰）非常热爱表演，然而其貌不扬的他往往只能够在电影里觅得一个跑龙套的角色，可即便如此，魏成功还是无比认真的对待着自己的每一个甚至连名字都没有的角色，这股子劲头引起了当红女明星米兰（马丽 饰）的注意。米兰的弟弟米勒（黄才伦 饰）是一名电影导演，黑帮大佬哈维（陈明昊 饰）给他的电影投资了不菲的资金，哪知道亏得底裤都不剩，哈维一直爱慕着米兰，想要娶她为妻，可是米兰誓死不从。这一天，当哈维决定和姐弟两算总账之际，米兰告诉哈维自己认识他一直想要寻找的杀手卡尔（艾伦 饰）。哈维给了米兰一天的时间，让他把卡尔带到自己面前，实际上并不认识卡尔的米兰决定让魏成功来扮演这位冷酷的杀手。©豆瓣', '马丽', '邢文雄', 6.2, 481412, 'tt16254308', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2814949620.jpg', 3.2, 16, 53.6, 23.4, 3.8, '0.018789,0.096201,-0.690629,0.793708,-0.267903,-0.438294,0.422294,-0.110949,-0.551090,-0.403659,-0.044432,0.627232,-0.167930,0.004449,0.142996,0.038309,-0.127049,-0.675286,-0.210203,0.015991,-0.230025,-0.366168,-0.310182,-0.201179,-0.182951,0.183882,0.543125,0.119790,-0.079369,0.232990,0.689739,0.266476,0.445752,0.494389,-0.108140,0.100232,0.154659,-0.188811,-0.060908,0.411758,0.255349,-0.092812,-0.198445,0.405579,0.081644,0.416181,0.356541,-0.098166,0.088758,0.137491,0.377142,-0.128878,0.132859,0.174939,0.031149,-0.256302,0.299328,0.036118,-0.092984,0.111650,0.176764,-0.204252,-0.916392,0.164661,0.112570,0.261163,-0.834713,0.416142,-0.314951,0.167462,0.083559,-0.038671,0.230457,0.304551,0.403498,0.042116,-0.156330,-0.054920,-0.685124,0.249619,0.569449,0.243322,-0.034343,0.415922,-0.225776,-0.506480,-0.220863,-0.276179,-0.571375,0.087521,0.224078,0.075828,0.000076,-0.056565,-0.472846,-0.004514,0.076681,-0.159792,0.109163,-0.560251,0.133171,-0.435782,-0.159087,-0.498965,-0.339400,-0.016343,-0.172633,-0.334892,0.782818,-0.737166,-0.023588,0.571933,0.228005,-0.451819,0.915198,0.320121,0.011728,-0.266596,-0.096908,0.056914,0.170873,-0.056815,0.224025,0.421440,0.003304,-0.376040,-0.244958,0.590545', '1793491', '4301278', '1783461', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3552028', '弱点', '剧情', '黑人男孩奥赫（昆东•亚伦 Quinton Aaron 饰）自幼父母离异，无家可归。不过，木讷的他却因为极强的身体条件和运动天赋，幸运地进入了一家私立基督教高中。虽然，他科科零分，但是一些细节却让他显得与众不同。一次排球比赛后，他主动收拾垃圾的行为，引起了陶西一家的注意。于是，陶西太太（桑德拉•布洛克 Sandra Bullock 饰）决定收养奥赫，并把他培养成橄榄球选手。陶西太太让他感受到了家庭的温暖。同时，陶西的儿子还帮助奥赫训练，使他很快地融入了橄榄球队的生活，不断激发运动的潜能。终于，在一次比赛中，他因出色的表现崭露头角，开始获得了球探的关注，随之带来了一系列的甜蜜和麻烦……本片根据迈克尔•刘易斯（Michael Lewis）的原著《弱点：比赛进程》（The Blind Side: Evolution of the Game）改编，取材自2009年美国国家橄榄球联盟（National Football League）选秀状元迈克尔•奥赫的非凡经历。荣获第82届奥斯卡最佳女主角奖（Sandra Bullock）。', '桑德拉·布洛克', '约翰·李·汉考克', 8.7, 272660, 'tt0878804', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2577248102.jpg', 0.2, 0.7, 9.9, 41.1, 48.2, '0.062997,0.011657,-0.497812,0.572046,-0.265853,-0.491375,0.366220,0.224035,-0.613088,-0.069358,0.235018,0.816204,-0.375001,0.029250,0.195164,-0.054194,-0.167467,-0.621285,0.170991,0.092678,-0.086183,-0.380363,-0.269366,-0.111126,-0.025813,-0.504024,0.617636,-0.102269,-0.386762,0.487694,0.051155,0.076280,0.329884,0.351760,-0.028402,-0.039252,0.180164,-0.039041,-0.120798,0.243226,0.089145,-0.229657,-0.312722,0.140140,0.266397,0.445419,0.852225,-0.068617,-0.060013,-0.268235,0.634284,-0.018096,-0.259293,0.183136,0.238447,0.198421,0.266713,0.105295,0.014992,0.104223,-0.177211,-0.165811,-0.595908,-0.012893,0.282523,-0.047079,-0.438407,0.576334,-0.166713,-0.055918,0.047660,-0.039466,-0.161583,0.311455,0.180178,0.246541,-0.181519,0.203692,-0.128792,0.133703,0.584031,-0.310707,-0.444242,0.372584,-0.364522,-0.596190,-0.067427,-0.304234,-0.299764,0.114278,0.461843,0.235719,-0.072966,0.321295,-0.424776,-0.065083,-0.294038,-0.325722,0.026066,-0.379393,0.096043,-0.565542,-0.213426,-0.235395,-0.352599,-0.208104,-0.028319,-0.259576,0.829261,-0.761492,0.179137,0.666633,0.050988,-0.362686,0.424878,-0.017125,0.251664,-0.305336,-0.202418,0.264479,-0.1