INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3552328', '零的焦点', '剧情', '进入20世纪50年代，日本渐渐走出战败的阴影，开始进入经济高度增长期。在此背景下，供职于东洋第一广告公司的鹈原宪一（西岛秀俊 饰）经人介绍结识了美丽贤淑的祯子（广末凉子 饰），二人互相倾慕，不久完婚。婚后不久，鹈原受命前往位于金泽的分公司办事，却并未在预定日期回返。祯子无法继续等待，遂起身前往金泽。在这一过程中，祯子发现自己对丈夫并不了解，鹈原似乎隐藏着无数的秘密。随着调查的深入，莫名其妙的死者接连出现，祯子渐渐触摸到丈夫那不为人知的过去……本片根据日本推理小说作家松本清张的同名小说改编，也是松本清张诞辰100周年的纪念作品。©豆瓣', '广末凉子', '犬童一心', 7.1, 6378, 'tt1379211', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p544579033.jpg', 0.7, 3.8, 42.8, 42.9, 9.8, '0.180140,0.279106,-0.744786,0.476292,0.395058,-0.240801,0.325616,0.188609,-0.431525,-0.571314,0.184943,0.524981,-0.291593,0.101935,0.263420,-0.014185,-0.324204,-0.476737,-0.203184,-0.491895,-0.131513,-0.414772,-0.074500,0.048226,-0.181282,-0.131476,0.819338,0.266434,-0.274829,0.500980,0.212545,0.328472,-0.496033,0.383683,-0.178304,0.135023,0.044927,-0.008342,-0.483070,0.241136,-0.089844,-0.536833,-0.269913,-0.150508,0.016100,0.411419,0.729660,-0.405520,-0.165834,-0.033303,0.489821,-0.044453,-0.382064,0.047443,0.443833,0.270202,0.047134,0.359984,-0.459058,0.163666,-0.303902,-0.375134,-0.399959,0.012505,0.069925,0.514217,-0.345431,0.061904,-0.210114,-0.142943,0.131396,-0.541410,0.090422,0.489627,0.054652,0.114575,0.006623,0.394031,-0.069191,0.165723,0.666935,0.212355,-0.120985,0.197886,0.165145,-0.379667,-0.188478,-0.003268,-0.156660,-0.144336,0.369839,0.331385,-0.015127,0.094801,-0.419577,-0.051122,-0.135064,-0.222387,0.376281,-0.069827,-0.139872,-0.689404,-0.093496,-0.385336,-0.162485,0.078113,0.047899,-0.342913,0.603285,-0.842580,0.273419,0.445753,0.330839,-0.377578,0.514102,-0.016037,-0.066018,-0.249301,-0.207468,0.411009,-0.053199,0.334790,-0.043738,0.361282,-0.300765,-0.350409,-0.465799,0.217247', '2369613', '3266509', '6007281', '1507140');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3558661', '倔强萝卜', '喜剧', '中年人老赵（马书良 饰）和老罗（黄渤 饰）曾是一起当过兵的老战友，老赵投资房地产，向老罗及其亲戚、邻居举债，结果房子成了烂尾楼，前期投入打了水漂，作为保证人的老罗承受来自亲友的巨大压力，他和老赵的关系则变得分外紧张。由于老赵的抵赖，老罗被迫和妻子离婚，连儿子罗毅（杜海涛 饰）也对自己颇有微词。为了追回属于自己的四十万，老罗离群索居，准备采取高科技手段入侵老赵的公司，盗取现金。十五月圆之夜，他假意约出老赵叙旧，实则计划迷晕对方后外出行窃，制造不在场证明。只是天算不如人算，几起突发事件破坏了他的周密计划……©豆瓣', '黄渤', '田蒙', 5.4, 34670, 'tt14472590', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p452522089.jpg', 8.9, 28.5, 48.7, 11.4, 2.6, '-0.093036,-0.320002,-0.527425,0.264112,-0.291799,-0.264663,0.471654,0.040507,-0.432269,-0.419559,0.032662,0.202213,-0.006774,0.174552,0.076504,-0.292695,-0.039293,-0.217402,-0.080669,-0.011177,-0.183513,-0.592437,-0.111550,-0.376874,-0.208325,0.079572,0.238936,0.025221,-0.352055,0.169631,0.320300,0.140650,0.032841,0.534566,0.064156,0.017519,-0.334265,0.064171,-0.420856,0.010048,0.127101,-0.060707,-0.082835,-0.045709,0.370257,0.680772,0.325205,0.073000,-0.149205,-0.091463,0.169793,0.067226,-0.080802,-0.009188,0.260145,0.126832,0.244857,0.199447,-0.267876,-0.283783,0.219858,-0.112586,-0.555156,0.191285,0.199432,-0.159603,-0.574866,0.108797,-0.016938,0.260449,-0.147267,-0.323373,0.190700,0.425732,0.238313,0.286261,-0.051307,0.048509,-0.566334,0.215889,0.600383,0.008515,0.080297,0.063529,-0.177494,-0.262658,-0.049328,-0.134426,-0.210449,0.034266,0.189140,-0.301168,0.084147,0.056012,-0.430246,-0.273744,0.053876,0.066388,-0.003368,-0.361866,0.303657,-0.512241,-0.080189,-0.356386,-0.283312,0.157538,0.252860,-0.287789,0.410019,-0.551364,-0.196294,0.222921,0.527516,-0.684735,0.432182,0.062704,0.033573,-0.249467,-0.154887,-0.204939,0.016255,0.171936,0.458266,0.020269,0.117283,-0.231215,0.182601,0.198111', '35073886', '1308206', '1308805', '27060077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35608160', '喜羊羊与灰太狼之筐出未来', '喜剧', '喜羊羊、灰太狼与一众小羊组成的守护者队进入篮球顶级赛事决赛，但却意外地败北，团队分崩离析。虽然各散东西，但对篮球的热爱和对冠军的渴望让大家再次组队，参加新一届大赛，然而这次的对手更强大，他们面临更大的挑战！', '祖晴', '黄伟明', 6.8, 37061, 'tt17081130', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2797468943.jpg', 2.2, 10.6, 44.6, 31.7, 10.8, '-0.088678,-0.003133,-0.755290,0.612389,0.165970,-0.042474,0.517150,-0.049991,-0.393406,0.064471,0.182260,1.142306,-0.435449,-0.267155,0.096904,-0.531142,0.210925,-0.788143,-0.121008,0.075287,-0.309252,-0.158721,-0.257801,-0.016409,-0.026724,0.155195,1.386274,0.379743,-0.780483,1.020771,0.439204,0.147276,0.344255,0.496706,0.023926,-0.616221,0.343977,0.578209,-0.398180,0.469140,-0.125340,0.204971,-0.786669,0.443154,0.407817,-0.083481,0.607308,-0.547126,-0.008187,-0.280262,0.001764,-0.775187,-0.307457,0.242935,0.341148,0.599438,0.303351,0.075277,0.595987,0.318427,-0.202274,-0.577627,-1.007601,0.349420,0.397608,-0.074022,-0.310055,0.811225,-0.022443,0.193493,0.297871,0.142674,0.082918,0.489957,0.314725,0.190594,-0.301946,-0.014307,-0.321580,-0.235892,0.849233,-0.249444,-0.470104,-0.274357,-0.048551,-0.958585,-0.112971,-0.804643,-0.233993,0.476078,0.130152,0.521184,0.374152,0.195841,-0.913289,0.447208,0.097735,-0.526776,-0.118311,-0.743202,0.388154,-1.029968,0.164897,-0.116914,-0.617128,0.168763,0.234529,-0.502000,1.286775,-1.030516,0.184761,0.292692,0.359907,-0.687556,0.600071,0.327579,0.325081,-0.521182,-0.494848,0.037978,-0.128517,0.083786,-0.111993,0.399304,0.032340,-0.493789,-0.336183,0.567836', '26615753', '27602116', '25880986', '30391300');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35613853', '长津湖之水门桥', '剧情', '电影以抗美援朝战争第二次战役中的长津湖战役为背景，讲述了在结束了新兴里和下碣隅里的战斗之后，七连战士们又接到了更艰巨的任务……', '吴京', '徐克', 7.2, 311276, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2846021991.jpg', 5.5, 9.1, 29.2, 34.6, 21.6, '0.158791,0.246058,-0.590256,1.058288,0.472789,-0.460527,0.506171,-0.359879,-0.248180,-0.075856,0.217628,0.823431,-0.014175,-0.159761,0.526482,-0.711708,-0.652916,-1.118040,-0.441546,-0.048037,-0.664767,-0.432716,-0.184514,0.038923,0.262673,-0.322666,0.775970,0.489858,-0.306522,0.632146,0.318286,0.255167,0.212449,0.624722,0.082012,0.046497,0.005358,0.007369,-0.178746,0.568288,0.081114,-0.380542,-0.343807,0.256264,0.218101,0.267864,0.961980,-0.866416,-0.147767,-0.404678,0.080311,-0.214289,-0.081392,0.246737,0.562864,0.432350,0.524715,0.488579,-0.168347,0.343295,-0.405574,-0.290569,-0.906002,-0.176621,0.013229,0.169504,-0.701314,0.623277,0.022703,0.368294,0.288645,-0.237383,0.359721,0.871241,0.516838,0.523461,-0.635908,-0.282805,-0.175482,0.448410,0.752439,-0.172318,0.190951,0.119688,0.276741,-0.824527,0.062398,-0.271764,-0.058705,0.542246,0.156029,-0.065106,0.149610,0.410079,-0.885254,0.145487,-0.153925,-0.787887,-0.272917,-0.182089,-0.379418,-1.057479,0.056648,-0.135448,-0.668407,0.464511,-0.153733,-0.174599,0.861989,-1.214443,-0.058142,0.185929,0.158910,-0.078467,0.404036,0.345135,0.671790,-0.012446,0.593082,0.024160,-0.453560,0.724592,0.368983,0.538996,-0.633658,-0.576782,-0.510625,0.841147', '1420088', '4127270', '25723905', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3562446', '东风雨', '剧情', '1941年，太平洋战争前夕。世界局势动荡不安，新一轮大战一触即发。各国势力汇集魔都上海，暗流涌动，危机四伏。中共通过潜伏在日本高层中的共产党尾崎秀实，得到日军即将发动袭击珍珠港的计划，代号“东风，有雨”。经满铁高官中西正弘（三浦研一 饰）、中共情报人员安明（柳云龙 饰）之手，情报送往重庆，但珍珠港依然遇袭，太平洋战争旋即爆发。在此之后，日方抓获军统情报人员，并得知尾崎秀实和中共的关系。尾崎遇害，中共情报小组的交通员（王宝强 饰）、报务员（刘璇 饰），安明一组渐渐和组织失去联系。这时，一枚藏有日本政府重大秘密的胶卷辗转来到上海。各方势力为此展开新一轮的明争暗斗……©豆瓣', '柳云龙', '柳云龙', 5.5, 19863, 'tt1664641', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p475749127.jpg', 8.9, 28.1, 45.5, 13.2, 4.2, '-0.165365,-0.035438,-0.699507,0.279828,0.648048,0.443927,0.036946,0.130054,-0.728324,-0.248553,0.283256,0.222304,-0.013987,-0.261654,0.299439,-0.286398,-0.588619,-0.885111,-0.025512,-0.093862,0.130842,-0.363927,-0.199583,-0.128855,0.005984,-0.194659,0.867721,0.568575,-0.412608,0.429853,0.155365,0.552599,-0.697238,0.450320,0.376974,-0.172976,0.621161,-0.376437,-0.553402,0.261102,-0.339837,-0.376005,-0.102734,0.032270,0.165193,0.479732,0.528765,-0.171437,0.136799,-0.367573,0.132283,-0.131718,-0.383252,0.010121,0.946821,0.550555,0.045297,0.409489,-0.319549,0.093240,-0.215772,-0.100671,-0.181705,-0.143635,0.235089,0.395989,0.166728,0.155319,-0.191957,0.454259,-0.051647,-0.137372,0.143949,1.020680,0.178927,-0.218702,-0.137896,0.317598,-0.054167,-0.139356,0.711755,-0.392870,-0.053093,-0.253508,0.094717,-0.327996,-0.177645,-0.029656,0.286173,-0.117949,0.169325,-0.216649,0.216953,0.608854,-0.573417,-0.148742,-0.185390,-0.278877,0.296247,0.144310,-0.027205,-1.017401,-0.476611,-0.087645,-0.167137,0.343415,0.232701,0.284219,0.684759,-0.623434,0.031162,0.334763,0.011196,-0.343507,0.013738,0.084419,-0.092315,-0.501100,0.118725,0.264885,0.181384,0.336096,-0.174598,-0.073735,-0.356995,-0.358884,0.150142,-0.378021', '2369613', '25723905', '1424552', '2973528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3562827', '制造伍德斯托克音乐节', '剧情', '60年代末的美国，伴随着战争的残酷与遥远以至似乎不可相信的登月壮举，年轻人们寻找着自身与世界的呼应。在纽约州白湖临近的小镇上，犹太青年艾略特（Demetri Martin 饰）为了照顾吝啬的母亲，放弃纽约的设计师工作回家帮忙打理汽车旅馆的生意，为了改善举步维艰的经营，艾略特借自己当地商会会长的便利，筹备举办例行的音乐节活动。与此同时，第一次伍德斯托克音乐节由于原定举办地当地政府的反对宣告停滞，艾略特抓住这次机会，邀请主办方迁址自己家乡，当地居民对嬉皮士观众们可能造成的危害忧心忡忡，艾略特在发布会上放弃收取门票的宣言更让各地音乐爱好者蜂拥而至，观众人数达几十万之众，让举办地成为了陷入狂欢的独立共和国。随着音乐节的进行，艾略特一家的问题亦得到了缓解……本片根据Elliot Tiber的回忆录改编。©豆瓣', '迪米特利·马丁', '李安', 7.7, 25274, 'tt1127896', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p538200176.jpg', 0.3, 2.3, 28, 48.7, 20.7, '-0.022301,0.198499,-0.679799,0.379662,0.303373,0.060733,0.374445,0.107492,-0.382536,-0.127469,0.106361,0.719966,-0.087208,0.046830,0.521679,-0.277073,-0.376005,-0.579048,-0.241508,0.058091,0.042151,-0.399484,-0.215830,-0.284811,-0.281168,-0.278076,0.489641,0.340487,-0.462839,0.681392,0.273401,0.117425,0.072383,0.366362,-0.049389,-0.459704,0.138882,0.035292,-0.521999,0.342604,-0.110542,-0.137339,-0.049579,0.054201,0.197784,0.434415,0.605958,-0.172005,-0.122910,-0.123722,0.512172,-0.213415,0.146715,-0.048213,0.209198,0.211580,0.220709,0.189532,-0.402694,-0.001590,-0.121978,-0.269954,-0.721715,0.043420,0.411948,0.179091,-0.494180,0.526528,0.065939,-0.089791,-0.207982,-0.295958,0.165673,0.707382,0.242066,0.291024,0.095013,0.108474,-0.209942,0.310177,0.724525,-0.126550,-0.244361,-0.071352,-0.418484,-0.393425,0.068453,-0.265189,-0.318181,-0.060634,0.037439,-0.082974,0.203336,0.189635,-0.536919,-0.177797,-0.120434,-0.829389,0.165283,-0.216640,-0.027664,-1.130954,0.196691,0.074061,0.142958,-0.054476,0.299613,-0.262688,0.598016,-0.740179,0.193318,0.642424,0.560756,-0.378778,0.593554,-0.037935,0.260112,-0.353754,-0.350365,0.239555,-0.006452,0.269762,-0.235617,-0.071892,0.153447,-0.342344,-0.187496,0.448089', '24751811', '3178770', '2159244', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3563200', '长大成人', '喜剧', '1978年，有五虎之称的少年篮球队在赛事中最终获胜，他们的教练罗伯特鼓励少年们去夺取更大的人生胜利。三十年后，五虎之一的费德（亚当•桑德勒 Adam Sandler 饰）已经是好莱坞知名的大牌经纪人，他和妻子莱克斯（萨尔玛•海耶克 Salma Hayek 饰）生活无忧， 孩子们养尊处优。这天费德突然接到告知罗伯特教练逝世的电话，于是匆匆赶回新英格兰，和当年的四位队友一起参加葬礼。今日的家具商艾瑞克（凯文•詹姆斯 Kevin James 饰）、娶得老妻的卡林（罗伯•施奈德 Rob Schneider 饰）、吃软饭的科特（克里斯•洛克 Chris Rock 饰）以及西吉（大卫•史派德 David Spade 饰）和费德五个家庭一起回到年少时生活过的湖边别墅，他们在这里找到了被吵吵闹闹的日常生活淹没已久的珍贵情感……©豆瓣', '亚当·桑德勒', '丹尼斯·杜根', 7.3, 25427, 'tt1375670', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p494423627.jpg', 0.9, 5.2, 36.4, 41.9, 15.6, '0.149330,-0.134585,-0.529085,0.464649,-0.077381,-0.475007,0.491558,0.226648,-0.480287,-0.415369,0.054498,0.891968,-0.278546,0.381218,0.630928,-0.035383,-0.417306,-0.664624,-0.126040,-0.138594,-0.067059,-0.453213,-0.245695,-0.186020,0.091174,-0.356979,0.463364,-0.214689,0.056728,0.811614,0.268655,0.474101,0.052123,0.053473,-0.097364,0.318775,0.365198,0.035807,-0.544319,0.176642,-0.090475,0.143105,-0.365722,-0.077737,0.341514,0.133157,0.371961,-0.175201,0.199878,-0.089161,0.120838,-0.091469,0.009451,0.067575,0.322002,-0.147200,0.348622,0.430661,-0.075961,0.136982,-0.003851,-0.221625,-0.383013,0.123276,-0.013333,0.176048,-0.601030,0.596353,-0.084241,-0.019395,0.085820,-0.366846,0.173416,0.228586,-0.085475,0.326742,-0.010015,0.072550,-0.418480,0.316870,0.695484,-0.086148,-0.017378,-0.013883,-0.094773,-0.185801,-0.001271,-0.252258,-0.630194,0.025483,0.423356,-0.020654,0.072454,0.228381,-0.541975,-0.163201,-0.299010,-0.330645,0.176514,-0.197909,-0.019506,-0.970829,-0.042495,-0.360547,-0.314057,-0.024332,0.010869,-0.027789,0.754586,-0.721151,0.362340,0.272281,0.126135,-0.229255,0.554823,0.031915,0.466627,-0.136237,-0.098102,0.240218,0.058236,0.123737,-0.056491,0.399790,-0.169653,-0.139528,-0.352910,0.354834', '11541282', '26365262', '1303333', '3139191');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3564151', '再见，总有一天', '剧情', '时间是1975年，供职于日本东部航空（Eastern Airline）驻泰国分公司的东垣内丰（西島秀俊 饰）是一位年轻有为、稳重干练的“好青年”，他在同事中人缘极好，上司樱田善次郎（加藤雅也 饰）也对他赞赏有加，生活中丰也即将和女友寻末光子（石田ゆり子 饰）完婚。正当如此春风得意时刻，丰邂逅了美丽妖艳的贵妇人真中沓子（中山美穂 饰）。仿佛被施以魔咒一般，丰迅速陷入与沓子亦情亦欲的缠绵中。他情纵声色，忘却归路，几乎失去了宝贵的爱情与友情。光子对丰的情事隐隐有知，丰也不得不选择与沓子分手，谁知这一分别便长达25年之久……本片根据辻仁成的恋爱小说改编。©豆瓣', '中山美穗', '李宰汉', 7.5, 16534, 'tt1383251', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p544087016.jpg', 1.2, 5, 31.9, 41, 21, '-0.018004,-0.039547,-0.497256,0.559878,0.238960,-0.287873,0.311273,0.108353,-0.367758,-0.361223,-0.118391,0.308213,-0.349444,0.313798,0.310692,-0.151930,-0.095502,-0.802483,-0.343435,-0.114987,0.092190,-0.288624,-0.210288,0.096614,-0.227768,-0.219865,0.636872,0.211484,0.065578,0.639897,0.249050,0.386912,-0.047386,0.319806,-0.105682,-0.029302,0.064183,0.083278,-0.336922,-0.098465,-0.079211,-0.423198,0.038272,-0.026257,0.154499,0.241286,0.622874,-0.265549,-0.259224,0.005680,0.502535,0.028447,-0.104564,0.133989,0.376540,-0.024895,0.060129,0.355603,-0.441763,0.107449,0.098715,-0.200062,-0.384992,-0.137493,0.102121,-0.090102,-0.110690,0.387400,-0.085060,-0.056830,0.038325,-0.157031,-0.165507,0.065770,0.290792,0.142749,-0.072392,0.212491,0.027525,0.350399,0.591138,0.415203,-0.271371,0.270698,-0.330574,-0.436352,-0.136825,-0.214297,-0.246134,-0.024999,0.022124,0.080488,0.256242,0.240619,-0.263298,-0.008618,-0.317658,0.251190,0.182572,-0.153018,-0.191244,-0.625782,-0.255869,-0.780715,-0.469324,0.118389,0.266295,-0.011743,0.832430,-0.741733,0.052690,0.299972,0.300250,-0.245392,0.577299,0.134334,-0.175680,-0.244679,-0.164582,0.507503,-0.052648,-0.010525,-0.046084,0.260854,-0.430353,-0.003438,-0.261449,0.230510', '3811356', '1826173', '25922902', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3564315', '生人勿进(美版)', '剧情', '在一个时常为白雪覆盖的小镇，有一幢昏黄孤寂的公寓，少年欧文（Kodi Smit-McPhee 饰）和离异的母亲（Cara Buono 饰）居住于此。这个清秀的小男孩敏感怯懦，在学校时常受到别人的欺负，妈妈则笃信宗教，无暇他顾。欧文只能躲在自己的小房间，通过望远镜窥视外边的世界，或者扮作连环杀人狂，释放心中的压抑与愤怒。某个夜晚，美丽而神秘的可人艾比（Chloë Grace Moretz 饰）搬入公寓，成为欧文的邻居。这两个共同拥有独特气质的孩子相互吸引，渐渐成为了好朋友。与此同时，小镇上凶杀案件接连发生，欧文也无意中发现艾比身上令人难以置信的秘密……本片根据John Ajvide Lindqvist的同名小说改编，此前瑞典版一经上映大获好评。©豆瓣', '柯蒂·斯密特-麦菲', '马特·里夫斯', 7.1, 24678, 'tt1228987', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2212153200.jpg', 0.9, 5.1, 42.1, 39.6, 12.3, '0.347937,0.059483,-0.703553,0.603591,-0.135954,0.181026,0.925027,0.274846,-0.406993,-0.350090,0.257002,0.724719,-0.348336,0.390577,0.141008,-0.018130,-0.159719,-0.513521,-0.228623,-0.265610,-0.140357,-0.295954,-0.476551,-0.211493,0.033580,-0.435624,0.597622,0.181212,-0.284619,0.448571,0.244833,0.543486,-0.525120,0.237524,-0.196325,-0.132685,0.046733,0.110813,-0.135065,0.171868,-0.274476,-0.193514,-0.033972,0.052024,-0.201638,0.255316,0.909775,-0.108153,-0.465089,-0.166373,0.559304,0.182041,-0.095186,-0.026856,0.307845,0.052697,0.352285,-0.111454,-0.248292,0.014639,0.036106,0.037882,-0.559738,0.084669,0.555447,0.072503,-0.178098,0.375332,0.012111,-0.344087,0.210335,-0.293226,0.162023,0.041360,0.196431,0.483794,-0.089663,0.233184,-0.409224,0.035009,0.358118,0.094155,-0.218431,0.170071,-0.419246,-0.090986,0.128364,-0.113053,-0.580587,0.097372,0.250984,-0.020826,-0.006808,0.213058,-0.588786,-0.005694,-0.057785,-0.084798,0.032733,-0.470709,-0.268083,-0.830064,-0.278950,-0.331502,-0.131125,0.046534,-0.067185,-0.098272,0.616823,-0.644470,0.470053,0.560574,0.167852,-0.265776,0.644429,-0.043484,0.164461,-0.038800,-0.238779,0.479851,0.156759,0.118904,-0.212535,0.351126,-0.248959,0.068095,-0.663158,0.540511', '10466639', '2334814', '1467779', '3097044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3564327', '我想吃掉你', '剧情', '玛丽（朱迪斯•戴维斯 Judith Davis 饰）从乡下来到法国里昂国家音乐学院进修钢琴演奏，借住在童年好友艾玛（伊希尔•勒•贝斯柯 Isild Le Besco 饰）的公寓里。儿时很害羞少语的艾玛长大后变得成熟自信，让玛丽深深着迷，产生了不一样的感情。玛丽所在的学院学期末考核要求学生必须弹奏舒曼的狂欢节外加两首自选歌曲，因为课程上高标准的要求，玛丽不得不牺牲很多娱乐时间来严格练习钢琴。因而她大部分时间都是在艾玛陪伴下度过，二人分享着彼此生活的快乐，感情日益深厚。一次舞会上玛丽受到陌生男子的骚扰无法脱身时，艾玛及时相救，并给与安慰，使玛丽倍感温暖，二人的爱欲一触即发。但艾玛对玛丽日益强烈的控制欲却让事情走向了不可控制的方向….©豆瓣', 'Judith Davis', 'Sophie Laloy', 6.4, 6435, 'tt0783530', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2521066084.jpg', 1.9, 13.9, 54.9, 23, 6.4, '0.170937,-0.038258,-0.720466,0.605345,0.046633,-0.376576,0.677688,0.136244,-0.489613,-0.186608,0.029893,0.346105,-0.184836,0.420030,0.381717,-0.051863,-0.414002,-0.511745,0.016648,-0.047792,-0.245074,-0.336720,0.096038,-0.242178,-0.280541,-0.554066,0.484647,-0.056453,-0.299783,0.661371,0.056589,0.376059,-0.000512,0.547144,0.139069,-0.298374,0.337246,-0.054595,-0.234487,0.158610,0.244183,-0.036669,-0.130605,0.296347,0.183336,0.189235,0.718907,-0.275594,-0.153466,-0.076363,0.337345,-0.099670,0.061652,0.086837,-0.071110,0.069963,0.139137,0.171928,-0.250415,0.183499,-0.117518,-0.320075,-0.481246,0.076547,0.210830,-0.004524,-0.614762,0.389286,-0.234221,-0.159168,0.083271,-0.405243,-0.144912,0.208266,0.371877,0.348979,-0.094091,0.150371,-0.087781,-0.033006,0.812859,-0.043747,-0.335290,0.338978,-0.681740,-0.405020,0.042973,-0.078175,-0.673942,-0.049674,0.006106,0.220782,0.073335,0.236479,-0.375832,-0.097231,-0.160469,-0.233941,0.208844,-0.469188,0.130433,-0.856296,-0.140697,-0.313655,-0.315030,-0.246278,0.061827,-0.376829,0.835556,-0.979534,0.300676,0.631685,0.416894,-0.196330,0.489198,0.196660,0.126853,-0.151726,-0.200599,0.556037,-0.173903,0.007231,0.015947,0.350349,-0.006010,0.112080,-0.399503,0.829091', '3012032', '35030151', '5977789', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35652715', '杰伊·比姆', '剧情', '当一名部落男子因涉嫌盗窃而被捕时，他的妻子求助于一名人权律师以帮助伸张正义。', '苏利耶·西瓦库马', '塔·塞·纳纳维尔', 8.7, 51134, 'tt15097216', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2734251414.jpg', 0.3, 0.9, 10.2, 40.4, 48.2, '0.072409,0.139529,0.081242,0.753151,-0.401762,-0.509311,0.712871,0.457193,-0.272060,-0.750878,0.562814,0.891326,0.954435,0.492763,1.016395,-0.315734,-0.066194,-0.487749,0.171162,-0.163047,-0.349420,-0.207796,-0.073721,-0.431314,-0.522732,-0.527157,1.085439,-0.398012,-0.526935,0.337948,0.622721,0.733629,-0.169660,0.157526,-0.304782,-1.028214,0.755417,0.087169,-0.427069,0.459217,-0.594742,-0.362237,-0.182884,-0.010923,-0.688097,0.458683,0.566323,-0.221896,-0.368342,-0.992740,0.623783,-0.485940,0.321521,0.245791,0.468945,-0.070558,0.265603,0.491982,-0.059089,-0.427996,-0.051174,-0.172150,-1.110751,-0.292156,0.054877,-0.179482,-0.492402,-0.529194,-0.209542,0.063114,0.186852,-0.032271,0.091791,0.470070,-0.149912,0.133702,-0.569936,0.091648,-0.563502,0.565032,0.764947,-0.291925,-0.187886,-0.230798,0.280826,-0.643938,0.599896,-0.147431,-0.743330,-0.200276,-0.226521,-0.279559,-0.068695,-0.387874,-0.442321,-0.532533,-0.695747,0.064643,-0.062737,-0.075801,-0.112188,-0.225090,-0.015870,0.451687,0.038660,0.157569,0.248075,-0.086119,0.899315,-0.495557,0.124468,0.765747,0.289951,-1.098893,0.741041,0.056870,0.472356,-0.739269,-0.681652,0.136462,0.788022,-0.055277,-0.361957,-0.146831,-0.166541,-0.241810,0.471661,-0.308283', '26678784', '3670447', '25731059', '3001114');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3566266', '逆世界', '剧情', '这是一部由卢森堡、丹麦、加拿大、英国、美国、法国联合摄制的科幻爱情片。在一个上下颠倒的双生世界，人们像生活在平行世界中一般各自生活工作，互不干涉。法律规定任何人不能和另一个世界的人沟通，更不能试图跨越到另一个世界去。活在“下界”的Adam（吉姆·斯特吉斯 Jim St urgess 饰）与生活于“上界”的Eden（克斯汀·邓斯特 Kirsten Dunst 饰）在年少时已在高山的山顶上结识并互有好感。可惜一次意外，令Eden失忆，从此忘记Adam；而Adam虽对她念念不忘，亦无法在山上再碰到她。直至多年后的某一天，Adam无意间从电视中见到Eden ，霎时唤醒了这份埋藏心底的感情！对Eden仍然痴心一片的Adam，决心凭借他的科学天份，闯入天梯，取得高科技仪器，冲破空间引力界限，誓要与Eden再谈一场逆转天地的恋爱！他们的距离虽然并不遥远，但他们的相爱却注定远不仅仅是你情我愿那么简单……', '吉姆·斯特吉斯', '胡安·索拉纳斯', 6.4, 85197, 'tt1374992', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1873950376.jpg', 2.6, 14.6, 51.1, 24.2, 7.4, '0.218232,0.364589,-0.930483,0.813413,0.001674,-0.099734,0.762655,-0.004839,-0.438449,0.025513,-0.038905,0.886911,0.092939,0.050625,0.096439,-0.163370,-0.274144,-0.614930,0.184653,-0.352127,-0.320465,-0.470988,-0.519324,-0.195886,-0.286985,-0.395952,0.847242,0.272026,-0.264692,0.251010,-0.017284,0.058379,-0.266679,0.536025,-0.224931,-0.273978,0.008764,0.398639,-0.675030,0.067165,-0.135684,0.119174,-0.010276,0.169839,-0.205034,0.110676,0.482811,-0.417466,-0.246500,-0.072044,0.292458,-0.049408,-0.154465,-0.115323,0.135210,-0.131588,0.068890,0.434591,-0.146250,0.199557,0.051244,-0.128934,-0.584542,-0.040266,0.151599,0.273548,-0.320754,0.557465,0.011204,-0.292631,-0.320991,-0.143829,-0.193406,0.254738,0.483559,0.421796,-0.283661,-0.126216,-0.379599,0.028584,0.825721,0.053914,-0.671308,0.554685,-0.146193,-0.367244,-0.341983,-0.049441,-0.497582,-0.048050,0.170327,0.039862,-0.362448,0.451646,-0.661239,0.355240,-0.157248,-0.072125,0.073068,-0.617175,0.192789,-0.542413,-0.170357,-0.413847,-0.404316,0.169364,0.276331,-0.286689,0.522843,-0.734534,0.353921,0.455815,0.383886,-0.425036,0.926528,0.436665,0.064078,-0.391687,0.078517,0.718663,-0.103576,0.413053,-0.119953,0.200655,0.118571,0.207165,-0.492908,0.678497', '1291835', '3055049', '35287908', '3629232');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3566540', '荒村公寓', '惊悚', '数年前，奇幻作家郭径（余文乐 饰）曾写了一部名为《荒村》的小说，故事根据一个的古老传说改编。据说真心想爱的人到了荒村会受到祝福，而虚情假意的情侣则会遭遇不幸，它的凄婉与浪漫让无数青年男女心驰神往。霍强、韩小枫、苏天平、春雨这四个大学生对《荒村》痴迷不已，他们一心寻找真正的荒村所在，以及故事中的女主角胭脂。原本应是快乐轻松的探险之旅，不久却变成了一场噩梦，他们的爱情和生命遭受巨大的考验。另一方面，郭径的生活也骤起波澜，业已分手的女友欧阳小枝（张雨绮 饰）又突然闯入他的世界……本片根据蔡骏的同名小说改编。©豆瓣', '余文乐', '罗志良', 3.9, 14433, 'tt1708427', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p588793418.jpg', 35.1, 39.4, 21.4, 3, 1.1, '0.151007,-0.171307,-0.500624,0.754972,0.171456,-0.033199,0.943421,-0.016205,-0.535788,-0.200557,0.334951,0.686377,-0.314023,0.205538,0.353792,-0.026834,-0.170861,-0.397668,-0.031061,-0.177841,-0.083963,-0.160716,-0.435424,-0.240804,0.078311,-0.192160,0.800670,0.245706,-0.321071,0.641757,0.237397,0.352395,-0.388492,0.327039,-0.042850,0.320816,-0.027235,0.493363,-0.310760,0.012788,-0.126749,-0.149252,-0.156364,0.079901,-0.403509,0.197902,0.780456,-0.354415,-0.299155,-0.049004,0.734994,-0.165693,-0.178407,-0.063126,0.128823,-0.004522,0.476678,0.073119,-0.073178,0.011228,-0.061476,-0.241128,-0.716770,-0.127859,0.303299,0.159323,-0.272065,0.332706,0.064193,-0.034405,0.262885,0.154338,0.268897,0.301180,0.750023,0.615296,-0.100793,-0.141577,-0.218913,0.606325,0.575204,0.048294,-0.231142,0.531148,-0.209970,-0.404023,-0.156699,0.044644,-0.630979,0.281085,0.418427,-0.019120,-0.131583,0.252820,-0.747146,0.124035,0.038234,-0.089705,0.156598,-0.396272,-0.229893,-0.618071,-0.216445,-0.351825,-0.137287,-0.158888,0.115000,-0.411925,0.911476,-0.695101,0.317091,0.415122,-0.160326,-0.501461,0.468729,0.275861,-0.034370,-0.209209,0.047380,0.609149,-0.250375,0.369063,-0.052281,0.246345,-0.007787,-0.028130,-0.478715,0.650820', '2053515', '1296992', '3811356', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3567857', '换精计划', '剧情', '凯西（詹妮弗·安妮斯顿 Jennifer Aniston 饰）是个年近四十的单身女人，她有工作，有朋友，尽情享受单身生活，也萌生了生一个小孩独自抚养的想法。联系相关机构后，凯西找到和合适捐精人——完美先生罗纳德（杰夫·高布伦 Jeff Goldblum 饰），不想在好友为她举办的“受孕派对”上，她最好的朋友沃利（杰森·贝特曼 Jason Bateman 饰）在卫生间气恼地换掉了罗纳德的精液。原来沃利一直爱着凯西，只是二人做好友太久了，已经失去了走在一起的最佳时机，就这样眼睁睁看着凯西离开自己。一别七年，凯西再次回来纽约居住时，带回了7岁的早熟小孩塞巴斯蒂安，迎接他们归来的沃利轻易发现塞巴斯蒂安和自己的相似，他想适时告诉凯西真相顺便表白，不想罗纳德也再度出现在凯西生活里……©豆瓣', '詹妮弗·安妮斯顿', 'Josh Gordon', 6.4, 13609, 'tt0889573', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1730691329.jpg', 1.2, 10.8, 59, 24.1, 4.8, '0.243701,-0.098773,-0.786985,0.325753,-0.409460,-0.565775,0.641443,-0.049185,-0.368335,-0.318708,0.000789,1.027776,-0.149988,0.515341,0.301827,0.326753,-0.504639,-0.636004,0.052913,-0.278668,-0.288897,-0.583971,-0.019294,-0.340905,0.097234,-0.194554,0.323185,-0.388466,0.208177,0.465248,0.251474,0.022940,-0.018392,0.463331,-0.223259,0.158048,0.176530,-0.075187,-0.276442,0.336036,0.183302,-0.109137,-0.128604,-0.008729,0.371898,0.242860,0.518290,-0.087225,-0.125358,0.199886,0.101283,-0.111290,-0.040141,0.100632,0.072041,-0.259270,0.199899,0.005890,-0.453239,-0.074411,0.131276,-0.167657,-0.509356,0.141202,-0.214485,0.120346,-0.590949,0.605309,-0.118312,-0.014386,0.316591,-0.426406,0.077820,0.457417,0.094561,0.226703,-0.128131,0.104300,-0.219211,0.109926,0.675447,0.116195,-0.126650,0.239519,-0.180853,-0.257439,0.133467,-0.079428,-0.508946,-0.162832,0.284897,0.061718,-0.354215,0.169353,-0.305305,-0.187852,-0.295766,0.055867,0.097925,-0.381147,0.005080,-0.371090,-0.134867,-0.287132,-0.424576,0.112527,-0.140474,-0.367379,0.487871,-0.781621,0.402876,0.461776,0.503042,-0.400136,0.854067,0.037806,0.149938,-0.169362,0.124389,0.305297,-0.063266,0.219769,0.314505,0.368601,0.175848,-0.122124,-0.569060,0.254925', '1302384', '1292207', '1915403', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35683855', '带你去见我妈', '喜剧', '泽凯跟静珊交往两年了，两个人在深圳一起打拼，相伴相依甚是幸福。但在汕头老家的妈妈，却不知道泽凯已经有了女朋友，不停地给泽凯找对象，甚至安排人跑到深圳来跟泽凯相亲。泽凯知道，要让妈妈接受静珊是很难迈过去的坎，因为静珊有过一段婚姻，所以迟迟没有跟家人介绍过静珊。但妈妈不停地催婚，泽凯不得不面对，最终决定跟静珊领证结婚，带她回家，跟妈妈坦白一切。', '郑润奇', '蓝鸿春', 7.4, 15778, 'tt17008712', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2831589600.jpg', 0.7, 4, 30.7, 51.2, 13.3, '0.242712,-0.482055,-0.653036,0.242077,-0.236929,-0.265993,0.192887,0.037423,-0.476905,-0.096062,-0.317197,0.637705,-0.156310,0.307683,-0.092979,-0.037264,-0.018805,-0.625980,0.460012,-0.214126,-0.255757,-0.619738,0.560465,0.139066,-0.202051,0.042936,0.254193,-0.309288,0.340076,0.657601,0.008715,-0.021529,-0.266483,0.680993,-0.331179,0.211574,-0.129581,0.362527,-0.772002,0.066852,0.618413,0.198811,-0.311138,0.174611,0.479068,0.307383,0.083713,0.221879,-0.267118,0.442845,0.050342,-0.393695,-0.397090,0.110911,0.251058,-0.150408,0.352155,0.540660,-0.232488,-0.344111,0.017088,0.083157,-0.247118,0.391420,0.232313,0.134822,-0.839938,0.389549,-0.043273,0.037101,0.150239,-0.701017,0.384516,0.570026,-0.217060,0.522554,-0.264224,0.019847,-0.527624,0.395559,1.295674,0.001646,0.353959,0.587250,-0.139907,-0.028675,0.144751,0.020348,-0.933428,0.277840,-0.537592,-0.054916,-0.644321,-0.232014,-0.185490,-0.238301,-0.288765,-0.108883,0.123620,-0.861033,0.123776,0.100676,-0.258496,-0.729828,-0.489934,0.407834,-0.212905,-0.347150,0.698806,-1.160592,0.207228,0.535174,0.871270,-0.961664,1.044314,0.580481,0.008463,-0.328138,0.464641,0.016080,-0.433012,-0.048783,0.269564,0.218534,0.260270,0.022546,-0.474127,0.101394', '1308035', '4145476', '1419416', '1299062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35685660', '2021去死', '喜剧', '比起2020年，2021年可说是不遑多让。本片以黑暗喜剧手法，结合真实新闻画面和照稿演出的访问，回顾这风云变幻的一年。', '休·格兰特', 'Jack Clough', 7, 7866, 'tt16301388', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2804529364.jpg', 1.5, 5.7, 46, 36.7, 10.1, '0.205545,-0.621339,-0.288462,0.618006,0.668784,-0.164260,0.630045,-0.332058,-0.622913,-0.540602,-0.010968,0.245061,-0.786372,-0.191937,0.279949,-0.283182,-0.344856,-0.673781,-0.095311,0.035174,0.125742,-0.349540,-0.485458,-0.405146,0.189267,-0.689618,0.702571,0.459101,-0.316501,0.387343,-0.000246,-0.013398,-0.084307,0.017747,0.067897,-0.316039,-0.098559,0.832642,-0.528530,0.126547,0.121974,-0.996289,-0.575228,-0.031053,0.063428,-0.212870,0.701908,-0.110996,-0.403197,0.313090,0.907825,-0.275777,-0.642752,-0.166315,-0.019334,-0.023464,0.343217,0.473210,-0.274033,0.185909,-0.676050,-0.513495,-1.076090,0.153467,0.146011,-0.136798,-0.315337,0.711187,-0.535508,-0.112623,-0.166174,-0.035766,0.042012,0.302148,0.587443,0.769073,0.239481,-0.316324,-0.203008,0.600808,0.736272,0.576087,-0.585547,0.666329,-0.229073,-0.476907,-0.626394,-0.767148,0.004826,0.742395,-0.037537,-0.092888,0.013826,0.782500,-0.687200,0.007185,0.035908,-0.622333,0.351359,-0.284890,-0.548532,-0.555141,-0.664364,-0.731884,-0.233995,-0.388404,0.253095,-0.658344,1.123356,-0.783291,0.094961,0.400632,0.177170,-0.485829,1.290146,0.124876,-0.207501,-0.397691,0.171661,-0.194086,-0.052043,0.120173,0.245157,0.230144,0.004705,-0.302787,-0.505362,0.508792', '27602116', '24284209', '2027945', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3569910', '自杀小队', '动作', '阿曼达（维奥拉·戴维斯 Viola Davis 饰）身为政府秘密机构的领导人，面对社会中出现的层出不穷的暴力恐怖袭击事件，决心启用一批被关押在监狱中判了无期徒刑的超级反派们，他们是小丑女（玛歌特·罗比 Margot Robbie 饰）、死亡射手（威尔·史密斯 Will Smith 饰）、回旋镖队长（杰·科特尼 Jai Courtney 饰）、复仇恶魔（杰伊·赫尔南德兹 Jay Hernandez 饰）和杀手鳄（阿德沃尔·阿吉纽依-艾格拜吉 Adewale Akinnuoye-Agbaje 饰）。他们所要面对的，是拥有强大法力的魅巫（卡拉·迪瓦伊 Cara Delevingne 饰），她和她的哥哥一起制造了一种非常危险的武器，企图用此控制全人类。除此之外，阿曼达还必须提防为了解救女友小丑女而不惜一切手段的危险人物小丑（杰瑞德·莱托 Jared Leto 饰）。', '威尔·史密斯', '大卫·阿耶', 6.6, 282934, 'tt1386697', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2363084076.jpg', 2.6, 13.8, 44.6, 27.1, 11.8, '0.098438,-0.282474,-0.356307,0.392075,-0.061687,0.127409,0.455509,0.226643,-0.350928,-0.436243,0.461177,0.642251,-0.138951,-0.312911,0.279773,-0.163927,-0.387216,-0.518315,-0.052992,0.021690,-0.142571,-0.515172,-0.327937,-0.401828,-0.008788,-0.467272,0.455725,-0.201064,-0.128509,0.111658,0.417912,1.079359,-0.122473,0.185806,0.238016,-0.328412,0.409514,-0.554323,-0.234544,0.143177,-0.146938,0.014129,0.127722,0.369187,0.066566,0.260245,0.479246,-0.560239,0.375377,-0.471050,0.114746,-0.368213,0.113420,0.122673,0.149649,-0.401279,0.018181,0.248584,0.157142,-0.027168,0.294221,-0.225458,-0.880396,-0.183218,0.259601,0.115833,-0.488906,0.032681,-0.243787,0.179095,0.217669,0.032006,0.028481,0.038637,0.225634,0.093481,-0.056910,-0.154637,-0.567865,-0.123264,0.256919,-0.168473,-0.218871,-0.025869,-0.242103,-0.621321,-0.355986,-0.279749,-0.408435,-0.097723,0.392480,-0.180882,0.181994,0.341058,-0.577884,-0.442616,-0.539310,0.216207,-0.070491,-0.291038,-0.029841,-0.725901,0.228598,-0.265490,-0.266383,0.025534,0.113650,-0.105965,0.527599,-0.605512,0.106007,0.730048,0.383716,-0.219565,0.264435,-0.120444,0.145781,-0.305696,-0.263145,0.312239,0.186351,0.057481,0.080581,0.124217,0.182778,-0.276821,0.068287,0.464433', '30382416', 