INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3569911', '全面回忆', '动作', '欢迎来到Rekall，它是一个能够把你的梦境变成现实的工厂。主人公道格拉斯·奎德（柯林·法瑞尔 Colin Farrell 饰）是一名普通的工厂工人。尽管他有一位漂亮的妻子（凯特·贝金赛尔 Kate Beckinsale 饰），两人看似恩爱，但他内心似乎依然不满足。思绪旅行听起来像是个完美的假期，让他从沮丧的生活中得到放松——作为一名特工的真实记忆可能正是他所需要的。但是当这个过程出现可怕的异常时，奎德变成了一个被追杀的逃犯。他发现自己正在躲避受考哈根长官（布莱恩·科兰斯顿 Bryan Cranston 饰）控制的警察，没有一个人是奎德可以信任的，除了一名叛军的女战士（杰西卡·贝尔 Jessica Biel 饰），她为地下抵抗组织的首领（比尔·奈伊 Bill Nighy 饰）工作。幻想和现实之间的界线变得模糊，他的命运凶吉难卜，因为奎德发现了他的真实身份，他的真爱，还有他真正的命运。本片改编自菲利普·K·迪克的著名短篇小说《We Can Remember It For You Wholesale》。', '科林·法瑞尔', '伦·怀斯曼', 7.1, 112519, 'tt1386703', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1659575372.jpg', 0.8, 5.3, 43.1, 39.9, 10.9, '0.571655,0.208182,-0.651989,0.619238,-0.260173,-0.248085,1.129177,0.069504,-0.478275,-0.476714,0.336187,0.813459,0.061029,0.113330,0.127166,0.271659,-0.371174,-0.570995,-0.085392,0.035598,-0.076949,-0.499038,-0.542467,-0.266425,-0.160769,-0.394095,0.630526,0.133476,-0.147122,0.313740,0.345905,0.429873,0.308779,0.386034,-0.129562,-0.069783,0.328561,-0.225837,-0.085678,0.106649,-0.124933,0.040039,-0.088743,0.361706,-0.198733,0.438479,0.537098,-0.188600,-0.261513,0.192983,0.439310,-0.260736,-0.009078,0.101247,0.064010,-0.052587,-0.057390,-0.058367,-0.085527,0.055546,0.107358,-0.011110,-1.062457,0.050153,0.161010,0.449407,-0.370662,0.348229,-0.167800,-0.181950,0.147349,-0.294227,0.089466,0.292478,0.289627,0.397898,-0.125018,0.090922,-0.591430,0.306851,0.681595,-0.107761,-0.684971,0.482585,-0.439923,-0.540776,-0.254554,-0.200520,-0.559632,-0.114519,0.276240,0.064762,-0.275114,0.221655,-0.504785,-0.090378,-0.421092,-0.233342,-0.385153,-0.422184,-0.209011,-0.352585,-0.230210,-0.513341,-0.331160,-0.073759,-0.116055,-0.371316,0.703127,-0.913965,0.205412,0.678838,0.031593,-0.356674,0.572071,0.174096,0.025770,-0.254704,-0.107156,0.447882,0.151047,0.094