INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3569915', '二流警探', '喜剧', 'Highsmith（塞缪尔·杰克逊 Samuel L. Jackson 饰）和Danson（道恩·强森 Dwayne Johnson 饰）是一对无坚不摧的完美搭档，纽约警局里的超级精英，也是警界人士的崇拜对象。相比两人，一副呆子样的Allen（威尔·法瑞尔 Will Ferrell 饰）和身手好但脾气暴躁的Terry（马克·沃尔伯格 Mark Wahlberg 饰）却是底层警员，除了扶老太太过马路或者劝架之类闲杂事等，他俩几乎无所事事。一次偶然机会，却让他们得以替补偶像出更，两人自然不会放过这个出头的机会，但二人不性格不同、办事风格更是南辕北辙……最终，这一对难兄难弟是否能顺利完成任务，让众人对他们刮目相看？©豆瓣', '马克·沃尔伯格', '亚当·麦凯', 6.2, 13250, 'tt1386588', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p582563282.jpg', 2.9, 18.2, 52.8, 19.9, 6.1, '0.215914,-0.261154,-0.469973,0.693101,-0.264352,-0.341308,0.603865,0.017693,-0.801229,-0.079988,-0.051468,0.712761,-0.360215,-0.000876,0.113723,-0.158465,-0.269443,-0.515201,-0.015401,-0.178114,-0.169191,-0.414465,-0.367344,-0.332229,-0.163651,0.002764,0.374921,-0.326495,-0.050987,0.658254,0.480974,0.244372,0.107367,0.281418,-0.032313,-0.366945,0.055024,0.007584,-0.279869,-0.086293,0.071850,0.085585,-0.256706,0.347951,0.259793,0.316567,0.332815,-0.228556,-0.203972,0.007213,-0.122397,-0.197906,-0.023319,0.230113,0.165776,-0.474065,0.551231,0.256631,0.166357,0.077646,-0.092269,0.147189,-0.665598,0.268586,0.089255,0.071849,-0.430439,0.331195,-0.049149,-0.320358,-0.119202,-0.305736,0.041229,0.088784,0.426185,0.111215,-0.065159,-0.090685,-0.420007,-0.057700,0.556766,0.265565,-0.173267,0.397118,-0.161602,-0.387052,-0.144976,-0.313001,-0.494596,0.159655,0.081035,-0.220511,0.128280,-0.012649,-0.520726,0.040857,-0.156854,0.088375,-0.368075,-0.433812,0.290159,-0.625626,0.061455,-0.547291,-0.636632,0.187855,0.086519,-0.107179,0.605608,-0.665584,-0.345907,0.141502,0.014779,-0.609411,0.701478,0.177835,0.249808,-0.394201,-0.144838,-0.273708,0.056268,-0.104718,0.080427,0.535171,0.123011,-0.500274,-0.086989,0.261847', '4301278', '3284768', '3000078', '2137060');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3569943', '命运规划局', '爱情', '本影片根据菲利普·K·迪克的短篇小说《规划小组（Adjustment Team）》改编。天生就适合走上政治舞台的大卫·诺里斯(马特·达蒙 Matt Damon 饰)，是一名政坛的明日之星，他在信心满满的参选纽约州参议员期间，意外认识了认识美丽的芭蕾女演员爱丽丝(艾米莉·布朗特 Emily Blunt 饰)，两人一见钟情，正当情意正浓时大卫突然被一群穿黑西装、戴黑帽和墨镜的神秘人士绑走。这群自称是隶属于联邦的人生命运调整局的人，告诉大卫他命里该当总统，伊丽丝也会成为世界著名的编舞家，他们的相爱会使两人的前途都成为泡影。规划局想尽一切方式阻止两人再次相遇。知道真相的大卫是会追求自己的梦想而放弃爱丽丝？还是为了真爱，对抗命运调整局呢？©豆瓣', '马特·达蒙', '乔治·诺非', 7, 83361, 'tt1385826', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2498175169.jpg', 0.7, 6, 46.5, 37, 9.8, '0.048178,0.000952,-0.417915,0.425968,-0.196520,-0.173339,0.268851,0.093561,-0.363797,-0.315557,0.216034,0.960447,-0.086001,0.015769,0.342040,0.034587,-0.407132,-0.826951,-0.038739,-0.063313,-0.218358,-0.522596,-0.371061,-0.237009,0.156306,-0.480098,0.699030,0.077251,-0.367408,0.456414,0.739096,0.350198,0.033244,0.172320,-0.084292,-0.198443,0.371445,-0.206204,-0.483505,0.202926,-0.257431,0.105466,-0.091961,0.246717,-0.218635,0.147466,0.393854,-0.140389,-0.108641,-0.013524,0.447902,-0.249612,-0.017927,0.066887,0.235702,-0.068094,-0.010183,0.448223,-0.058361,0.078152,0.099317,-0.105578,-0.647157,0.119177,0.121569,0.247802,-0.572178,0.183497,-0.142933,-0.155432,0.203318,-0.093236,0.190519,0.312020,0.531509,0.342097,0.346214,0.072477,-0.405922,0.123239,0.658583,-0.088910,-0.232067,0.281312,-0.326669,-0.143430,-0.185844,-0.004703,-0.458517,-0.039773,0.296039,-0.100524,0.120460,0.108741,-0.286954,0.082885,-0.216960,0.024556,0.115091,-0.516069,0.056894,-0.519850,-0.229849,-0.325937,-0.192201,-0.029219,-0.049766,-0.224953,0.598491,-0.663438,0.151758,0.451330,0.074951,-0.604180,0.771410,0.390262,0.093336,-0.472859,-0.140808,0.345327,-0.118322,-0.056353,-0.204947,0.338253,0.154007,-0.103333,-0.418686,0.342342', '4301278', '30162520', '35048413', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3569954', '侦探拍档', '喜剧', '纽约警局老干探吉米（布鲁斯•威利斯 Bruce Willis 饰）笃信沉默是金，办案一丝不苟。他有个黑人拍档保罗（崔西•摩根 Tracy Morgan 饰）刚升为探员，自以为奥巴马做了美国总统，腰杆子就硬了。不但对小毛贼颐指气使，而且对老干探也不那么尊敬。因为一张1952年的珍贵棒球卡盗窃案，吉米和保罗联手出击。不过，这次的麻烦似乎没那么容易摆平。在调查中，一连串案件浮出水面，包括墨西哥美女绑架案、黑帮分子毒品交易案等等。这对搭档其实没有经过什么大风大浪，所以这次如临大敌。而且，他们还都出现了后院起火的症状：吉米莫名其妙搞丢了女儿出嫁举办婚礼的一大笔钱，而保罗虽然像只呆头鹅，却被妻子怀疑有出轨劣迹。这种事令两人非常闹心。他们不得不一边办案，一边苦口婆心地对家人解释自己的清白，这种两头忙的窘境快把他们逼疯了……©豆瓣', '布鲁斯·威利斯', '凯文·史密斯', 6.2, 8640, 'tt1385867', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2326578755.jpg', 2.1, 13.6, 59.3, 20.2, 4.8, '0.394610,-0.423935,-0.510454,0.270604,-0.223370,-0.211047,0.496258,-0.016042,-0.450664,-0.161154,0.202682,0.595963,-0.331044,-0.069512,-0.010623,-0.037006,-0.330960,-0.666919,0.110100,0.012967,-0.172285,-0.575442,-0.308589,-0.265527,-0.199473,0.073684,0.047762,-0.042792,-0.009832,0.366473,0.322314,0.216832,0.210574,0.421619,-0.155720,-0.017054,0.180144,0.189263,0.001498,-0.003774,0.294096,-0.131396,-0.007296,0.248813,0.392969,0.502398,0.150378,-0.231399,-0.326628,-0.050173,0.218146,-0.534327,-0.013599,0.315795,0.437967,-0.052492,0.213513,0.160736,-0.111720,-0.279144,0.238359,-0.012502,-0.706432,0.187794,-0.104296,0.180717,-0.514591,0.117870,-0.246820,0.131700,0.008652,-0.040940,0.218138,0.464925,0.345762,0.159157,-0.070763,0.148118,-0.624022,0.145901,0.486937,0.038831,-0.146160,0.201449,-0.083078,-0.250662,-0.078526,-0.330009,-0.244302,0.114154,0.115722,-0.331985,-0.092560,0.128628,-0.132486,-0.089313,-0.184705,-0.002705,-0.220578,-0.418354,-0.205500,-0.268666,-0.054055,-0.425924,-0.346595,0.018295,0.107492,-0.113056,0.326265,-0.466158,-0.040251,0.525715,0.236530,-0.577038,0.372886,0.291031,-0.090268,-0.286166,-0.297126,-0.209318,0.170268,0.136973,0.393633,0.332415,0.350577,-0.479764,0.125160,0.080237', '1299799', '1307442', '1295318', '3215099');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3569969', '孩子们都很好', '剧情', '影片参加了2010年的圣丹斯电影节，发行版权以480万美元的价格被焦点影业买走，成为了那届圣丹斯上最值钱的电影。妮可（安妮特·贝宁 Annette Bening 饰）和朱尔斯（朱丽安·摩尔Julianne Moore 饰）是一对相伴很久的同性伴侣。并有2个孩子：马上要18岁的乔妮（米娅·华希科沃斯卡 Mia Wasikowska 饰）和15岁的莱塞（乔什·哈切森 Josh Hutcherson 饰）。妮可的医生职业很有压力常常忽视了朱尔斯日子还算太平的过着，直到有一天，莱塞向姐姐建议，他想和那个捐出自己精子的男人见一面。因为姐姐已经到了18岁，她有权利向家里提出这个要求。妮可和和朱尔斯同意了姐弟俩的愿望，他们见到了在生物学上的父亲保罗（马克·鲁弗洛 Mark Ruffalo 饰）。可是见面之后会发生什么呢？这个平静而美满的家庭会因此出现裂缝么？©豆瓣', '朱丽安·摩尔', '丽莎·查罗登科', 7.5, 32744, 'tt0842926', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p587667124.jpg', 0.3, 2, 33, 52.1, 12.6, '0.220562,-0.203888,-0.600776,0.398644,-0.177502,-0.450308,0.804649,0.193042,-0.557593,-0.150510,-0.168149,0.914340,-0.477626,0.369617,0.515870,0.285473,-0.344260,-0.647896,0.131521,-0.270198,-0.162942,-0.545714,-0.112815,-0.139417,-0.120096,-0.383335,0.165732,-0.161670,0.194866,0.534642,0.599946,0.094129,0.361737,0.454297,-0.053971,0.176113,0.095679,0.078049,-0.125403,0.452037,0.205338,-0.084926,-0.218183,-0.059488,0.190543,0.417807,0.275958,-0.073097,-0.093984,0.153434,0.350273,-0.245553,0.134565,0.279614,0.133754,-0.290426,0.170057,0.156883,-0.252833,-0.033632,0.195408,-0.286221,-0.546541,0.212482,0.079555,0.264952,-0.833554,0.366648,-0.251415,-0.194168,0.064868,-0.425433,0.221582,0.756812,0.152181,0.214200,-0.260457,-0.092034,-0.895464,0.222499,0.507457,0.027107,-0.247169,0.190617,-0.173288,-0.653842,-0.241471,-0.188349,-0.587422,0.152934,0.452360,-0.020737,-0.050937,-0.038292,-0.766660,-0.129279,0.029118,-0.426549,0.106951,-0.340883,0.080874,-0.420486,-0.101194,-0.800795,-0.469073,-0.099630,-0.039581,-0.407680,0.748414,-0.820450,0.332653,0.278521,0.633244,-0.377975,0.926987,0.079347,0.059071,-0.077108,0.078462,0.098531,-0.070300,0.176627,0.093070,0.415114,0.450234,-0.359784,-0.112104,0.554917', '3055049', '1783461', '26809592', '1302384');
