INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3574495', '天国的邮递员', '剧情', '申在俊(金在中 Jaejoong Kim 饰)是一名IT界的精英，事业成功的他我行我素，个性张扬。因为一次车祸的意外变成了植物人，上帝用再给他两周的寿命作为条件让在俊来担任天国的邮递员。在俊就这样往返于天国和人间送信，给失去爱人的人们带来生存的希望，对于爱的理解渐渐改变和变得深刻。赵荷娜（韩孝珠 Hyo-ju Han 饰）因为无法释怀爱人的去世，总是给死去的爱人邮寄充满怨恨的信件。两人一次偶然的过程在草原的天国邮筒处相遇，机缘巧合之下在俊决定让荷娜担任自己人间的助手。在和在俊传送信件的日子中，荷娜逐渐从过去的感情阴影中走出来，并对在俊渐生情愫。而此时，眼看在俊两周的寿命却已然到期……©豆瓣', '金在中', '李亨民', 7, 25180, 'tt2012626', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p651873601.jpg', 1.3, 7.8, 43.8, 32.8, 14.3, '0.105141,0.374140,-0.632610,0.881164,-0.073484,-0.296128,0.856328,0.105809,-0.472014,-0.085828,0.081538,0.897219,-0.015955,0.426677,0.273718,-0.268031,-0.121948,-0.646931,-0.173533,-0.380704,-0.503732,-0.382895,-0.324179,-0.160865,-0.053593,-0.722943,0.954892,0.241127,-0.174896,0.646266,0.258618,0.243414,-0.067720,0.541647,-0.302787,-0.164801,-0.176160,0.236014,-0.433873,0.191391,0.123038,-0.445822,-0.177497,0.196086,-0.146340,0.236099,0.973797,-0.255624,-0.537286,0.094401,0.393664,-0.384465,-0.307235,0.014148,0.278455,-0.054219,-0.080411,0.452836,-0.430127,0.230590,0.006958,0.013486,-0.784882,0.060674,-0.059987,0.282902,-0.619725,0.611729,-0.024350,-0.175995,0.208365,-0.510803,0.234894,0.346426,0.046497,0.539002,-0.411216,0.186535,-0.425281,0.332737,0.705487,-0.013132,-0.298834,0.527379,-0.384045,-0.397884,-0.180012,-0.219639,-0.520086,0.045141,0.167022,0.084341,-0.232942,0.415970,-0.536252,0.019479,-0.216035,-0.237443,0.131363,-0.617578,-0.239362,-0.581954,-0.465510,-0.457971,-0.225705,0.438439,0.199636,-0.267141,0.686907,-0.697722,0.397957,0.419740,0.294243,-0.608001,0.872895,0.384140,-0.105622,-0.267588,-0.083769,0.386729,0.153153,0.384681,0.074467,0.126309,-0.152934,0.282098,-0.552298,0.547482', '30401849', '35287908', '27666513', '27062637');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3574559', '一路有你', '剧情', '小夫妻张谦（印小天 饰）和陆茵(黄奕 饰)在高速公路旁经营一家小餐馆。深夜，张谦骑车回家，因接到陆茵电话，没留意路况，被许城亮(古天乐 饰)驾驶的货柜车撞到。张谦死亡，赶来医院陆茵发现自己怀孕，却决定生下孩子，重开餐馆经营。城亮对车祸心存愧疚，事隔数月，鼓起勇气走进陆茵 的餐馆用餐，更在女友苏珊(莫文蔚 饰) 体谅下，主动帮忙店内杂务，两人渐成好友。后陆茵发现城亮就是撞死丈夫的司机，着城亮被张谦弟张军痛打致重伤……城亮回到家中与苏珊矛盾加深，发现两人之间已存在差异，经常大吵。陆茵进院生产，城亮守候照顾，陆茵感动，但她深信城亮只是责任，后把餐馆结束，带儿子回家乡重过新生活，并请城亮回到苏珊身边。但城亮却发觉一切都不复从前，最终跟苏珊分手。半年后，城亮再回国内找寻他相信的东西，去餐馆找陆茵，却发现已经人走楼空……©豆瓣', '古天乐', '赵崇基', 6, 14552, 'tt1797547', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p777795291.jpg', 3.7, 19, 56, 17, 4.2, '0.059888,0.057682,-0.561060,-0.097654,0.202887,-0.391316,0.531478,0.206431,-0.423704,-0.536344,0.036613,0.545843,-0.248244,0.450621,0.228663,-0.248727,-0.440575,-0.247797,0.335339,-0.063249,-0.139528,-0.321357,0.195824,0.030902,-0.087686,0.174931,0.203922,0.034930,0.016033,0.646168,-0.075865,-0.170801,-0.320993,0.657978,-0.063729,0.217161,-0.208408,0.165126,-0.389379,0.108866,0.154001,-0.040280,-0.352268,-0.143157,0.402575,0.358924,0.386884,0.316564,-0.474175,-0.000574,0.201202,-0.037541,-0.010458,0.075874,0.258571,0.204063,0.172988,0.019281,-0.418161,-0.071434,0.009939,0.008525,0.121342,0.361430,-0.082635,-0.188334,-0.593460,0.238311,-0.095730,0.014675,0.013196,-0.579489,0.337596,0.343216,0.045219,0.521830,0.005182,0.178709,-0.460796,-0.129769,0.562037,-0.177865,0.237261,0.475660,0.188271,-0.246235,0.193767,0.075892,-0.271454,-0.043117,-0.065637,0.168919,-0.130536,-0.261091,-0.158756,-0.192311,-0.300441,-0.147532,0.117593,-0.260231,-0.153630,-0.702698,0.086222,-0.168720,-0.344885,0.368548,0.012563,-0.040250,0.069132,-0.604457,0.223968,0.197450,0.596855,-0.632937,0.701193,-0.131004,0.182255,-0.133949,0.125556,0.526613,0.048449,0.235724,-0.021692,-0.079995,-0.427496,-0.041379,-0.528732,0.050011', '1305543', '5977835', '2990737', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35760330', '黄阿丽：风流女子', '脱口秀', '喜剧人、作家、演员黄艾丽回归 Netflix，带来她的第三部原创喜剧特辑 《黄艾丽：大佬范儿》。正值情人节之际，艾丽袒露了她最狂野的幻想、一夫一妻制带来的挑战，以及她对单身人士的真实看法。《黄艾丽：大佬范儿》在新泽西州贝西伯爵剧院录制，于 2022 年 2 月 14 日在 Netflix 面向全球首播。', '黄阿丽', 'Nahnatchka Khan', 8.3, 9494, 'tt17542000', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2867822926.jpg', 0.4, 1.5, 16.7, 44.8, 36.5, '-0.122961,-0.456238,-0.293314,0.383563,0.365888,0.362656,0.532005,0.165719,-0.589628,-0.081128,0.481235,0.506512,-0.599430,0.062554,1.113190,-0.361151,-0.418368,-0.595851,-0.033495,-0.080281,0.366153,-0.045931,-0.150166,-0.137873,-0.074305,-0.468404,1.049849,0.020148,-0.275401,0.219712,0.414330,0.011560,-0.065346,0.285503,0.236793,-0.149614,0.448396,-0.067497,-0.523104,0.580169,-0.185548,-0.610317,-0.086919,0.273682,-0.062911,-0.012724,0.772639,-0.497425,0.096681,0.251605,0.974240,-0.187606,-0.387170,0.025952,0.021566,0.067583,0.420431,0.224062,0.268694,-0.143231,-0.187242,-0.643958,-0.294757,-0.043422,0.263556,0.291851,-0.245079,0.960938,-0.231832,0.271593,0.060785,-0.194215,-0.040311,-0.134446,0.115257,0.448910,0.336709,0.331674,-0.244832,0.821056,0.512607,0.360329,-0.292978,0.234069,-0.225004,-0.589269,-0.334752,-0.337646,-0.949679,0.038778,-0.001016,-0.076606,0.063078,0.585748,-0.484922,-0.057528,0.191718,-0.497032,0.363789,-0.354678,-0.079854,-0.826739,-0.264658,-0.067389,0.401887,-0.298840,0.463628,-0.459094,1.111737,-1.086025,0.223837,0.583229,0.485559,-0.364458,1.051855,-0.021619,-0.027150,-0.311183,-0.429089,0.444835,-0.144853,-0.036027,-0.120590,0.239234,-0.298729,-0.490520,0.029130,0.422759', '2338019', '1316589', '1322847', '4144683');
