INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35774719', '一个星期四', '剧情', '当一名幼儿园老师——亚米·高塔姆绑架了 16 名小学生并提出一系列要求时，不仅震撼了孟买警察和城市，而且在全国及其政界人士中引起了反响。', '亚米·高塔姆', '毕查德·汉巴塔', 7.7, 17595, 'tt13028258', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2868457745.jpg', 0.6, 3.1, 28.2, 46.4, 21.7, '0.337594,-0.132307,-0.650186,0.623472,-0.106018,-0.117108,0.436421,0.039318,-0.721759,-0.271256,-0.011015,0.885326,-0.380908,0.386894,0.535653,-0.425600,-0.395970,-0.667907,-0.186923,-0.535298,-0.474413,-0.682088,-0.179068,-0.176141,-0.136460,-0.578814,0.052295,-0.011920,-0.452069,0.821924,0.162503,0.023779,0.085997,0.585988,0.128900,-0.040333,0.962393,0.172224,-0.003794,0.326310,-0.396484,-0.086012,-0.187740,0.112365,0.206853,0.489097,0.362014,0.015584,-0.597552,-0.203152,0.579179,-0.159544,0.065301,0.269893,0.699158,-0.156312,0.518777,0.079377,-0.086254,0.201697,0.159974,-0.304201,-0.383703,0.292491,0.201580,-0.357146,-0.357285,0.326627,0.007774,0.098619,-0.004890,-0.120723,0.239146,0.164352,0.028517,0.615283,-0.139349,-0.045618,-0.240882,0.293166,0.404589,-0.022159,-0.447448,-0.318797,-0.411907,-0.611200,0.017865,0.009068,0.027100,0.465345,0.413127,-0.049331,-0.199855,0.090716,-0.187572,-0.446346,-0.194928,-0.469525,-0.173513,-0.110029,-0.279068,-0.956696,0.228014,-0.095196,0.073789,-0.234222,0.149880,0.152377,1.084513,-0.780476,0.088329,0.486928,0.429332,-0.464545,0.394756,0.012819,0.022862,0.150007,-0.274469,-0.502024,0.194548,0.388258,-0.044628,0.328998,-0.221419,-1.020407,0.116242,0.306263', '25922902', '3003137', '3205624', '1301172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3578920', '兄弟出头天', '喜剧', '在经历了28年的牢狱之灾后，沃尔（阿尔·帕西诺 Al Pacino 饰）终于重新回到了自由的怀抱，久违的老友道克（克里斯托弗·沃肯 Christopher Walken 饰）前来迎接，两人都无法抑制各自内心的激动和喜悦。尽管在沃尔服刑期间，世界发生了翻天覆地的变化，但和老朋友之间的友情依然坚定而持久。之后，老友赫希（艾伦·阿金 Alan Arkin 饰）也加入了沃尔和道克的狂欢之中，他们一边回忆着旧日往事，一边尽情享受着自由带来的快乐和放纵。快乐总是短暂的，在道克的心里，藏着一个让他感到沉重无比的秘密。原来，道克受黑帮老大所托，意图除掉刚刚出狱的沃尔。看着沃尔毫无防备的面孔，在友情和道义之间，道克无法做出选择，而他用来完成任务的时间已经所剩无几。©豆瓣', '阿尔·帕西诺', '费舍·史蒂芬斯', 7.8, 20566, 'tt1389096', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1849776760.jpg', 0.5, 3.1, 28, 45.4, 23.1, '0.114806,0.188063,-0.818376,0.840770,0.242259,-0.405707,1.078451,0.068981,-0.483729,-0.146314,-0.225040,0.605106,-0.296177,0.420241,0.544622,-0.136954,-0.475474,-0.848457,-0.150326,-0.282272,-0.233209,-0.529195,-0.323463,-0.379120,-0.243366,-0.307139,0.516340,0.092250,0.263114,0.862203,0.238535,0.499665,-0.042507,0.527970,-0.049415,-0.124051,0.130517,0.069021,-0.640295,-0.061532,0.618903,-0.168228,-0.275567,0.496941,0.129952,0.208366,0.727803,-0.655580,-0.364526,0.316405,-0.013864,-0.225525,0.142127,0.054364,-0.038620,0.028316,0.078728,0.212234,-0.292877,0.351919,0.383417,-0.135129,-0.805165,-0.022993,0.045269,0.226986,-0.445955,0.765204,0.035834,0.089576,0.230854,-0.446885,0.111423,0.555222,0.406672,0.474489,-0.519887,-0.016381,-0.465093,0.080200,0.764316,-0.160569,-0.273722,0.325362,-0.498821,-0.205915,-0.242655,-0.164304,-0.637330,-0.262663,0.211080,0.389815,-0.045928,0.635383,-0.535767,-0.056649,-0.161316,-0.267969,-0.021276,-0.677368,0.000339,-0.633747,-0.484828,-0.388573,-0.246353,0.196852,0.059003,-0.177614,0.635494,-1.004331,0.310400,0.471447,0.045258,-0.218493,0.483165,0.113322,0.291251,-0.367506,-0.069120,0.336609,-0.044308,0.206471,0.419325,0.396121,-0.215089,0.348159,-0.305913,0.646820', '1308755', '25911595', '2161696', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3578925', '我家买了动物园', '剧情', '作家本杰明·密（马特·达蒙 Matt Damon 饰）生性喜爱冒险，然而半年前的丧妻之痛令他至今无法释怀，儿子迪伦和小女儿洛希同样不能适应失去母亲的生活，迪伦因偷窃和阴暗的美术创作导致被学校开除，本杰明没有听从哥哥邓肯的建议，拒绝从新的爱情中获取乐观心态，也放弃了专栏写 作，筹划和儿女换到全新的环境继续生活。而本杰明的新家居然是一座荒废的动物园！因为看到了洛希和动物的友好接触，本杰明决定接收这座还收留着众多动物的野生动物园，并带领管理人凯莉（斯嘉丽·约翰逊 Scarlett Johansson 饰）率领的留守团队重新修葺动物园，希望在夏季开放之前，迎来动物园的再度营业和自己家庭的新生……©豆瓣', '马特·达蒙', '卡梅伦·克罗', 7.8, 111329, 'tt1389137', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1286451166.jpg', 0.2, 1.7, 26.7, 50.6, 20.8, '0.423954,0.019789,-0.624812,0.521699,-0.211999,-0.155986,0.590206,0.317265,-0.585379,-0.329522,0.026703,0.641253,0.024328,0.472003,0.153002,-0.202264,-0.404538,-0.390478,-0.068198,0.086855,-0.094673,-0.486000,-0.168356,-0.252134,-0.023906,-0.424738,0.849167,0.092872,-0.272405,0.575769,-0.034826,0.219080,-0.019973,0.348781,-0.032778,-0.052512,0.049987,0.289830,-0.375973,0.296396,-0.077341,0.140321,-0.048510,-0.012056,0.319546,0.355667,0.725528,-0.357876,-0.416524,-0.181553,0.440190,-0.135627,-0.032377,0.221977,0.201303,0.081025,0.052488,0.192577,-0.209760,0.168330,-0.160458,-0.287044,-0.690710,-0.062632,0.165494,0.090795,-0.596453,0.444179,0.085831,-0.138220,0.169619,-0.406257,0.027155,0.303226,0.325865,0.510872,-0.094440,0.220397,-0.291729,0.167116,0.551274,-0.274768,-0.336473,0.206985,-0.417221,-0.393359,0.257772,-0.285891,-0.560221,0.039447,-0.076909,0.200487,-0.360189,0.062736,-0.641579,-0.032762,-0.196871,-0.463134,0.330202,-0.589751,0.009498,-0.855055,-0.043111,-0.221912,-0.145943,-0.127199,0.047324,-0.468162,0.524774,-0.938767,0.252946,0.351403,0.368367,-0.641951,0.684749,-0.046294,0.176284,-0.117522,0.078039,0.460323,0.126855,0.404158,0.002738,0.114603,0.092911,-0.206792,-0.429834,0.405894', '2369613', '1420088', '30229667', '3014200');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3578939', '缩小人生', '剧情', '一项伟大的新技术被科学家们发明了出来，通过这项技术，能够将人类缩小到仅5英尺那么高，这也就意味着，人类将因此消耗更少的资源，获得更大的活动空间。保罗（马特·达蒙 Matt Damon 饰）和奥黛丽（克里斯汀·韦格 Kristen Wiig 饰）是一对深陷贫困之中的夫妻，为了享受更好的生活，他们决定去接受缩小实验。哪知道就在实验即将进行的前一秒，奥黛丽竟然反悔了，只有保罗一人缩身成功。刚开始，对于变小的保罗来说，一切都是那么的新奇，他住进了专门为缩小人所建立的社区之中，有了前所未有的全新体验。但随着时间的推移，问题逐一显现，小人的社会和大人比起来，并没有好过到哪里去，更糟糕的是，保罗和妻子因为身形的巨大差异，感情出现了裂痕。©豆瓣', '马特·达蒙', '亚历山大·佩恩', 5.6, 25447, 'tt1389072', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2505684182.jpg', 6.4, 29.9, 45.7, 13.9, 4.1, '0.217177,0.084764,-0.841791,0.503441,-0.254715,-0.223260,0.743487,0.037626,-0.526138,-0.181146,0.049848,0.600967,-0.182871,-0.077538,0.082577,-0.163677,-0.375648,-0.508696,-0.048292,-0.441410,-0.517626,-0.651135,-0.393666,-0.244774,-0.199795,-0.490508,0.660995,0.177920,-0.375684,0.200828,0.179438,0.064772,0.238092,0.493676,-0.222110,0.015219,-0.117233,0.056289,-0.269826,0.297573,0.272946,-0.006363,0.021890,0.211007,0.020113,0.207859,0.550393,-0.524269,-0.286486,-0.196290,0.370820,-0.113475,-0.124797,0.090960,0.310229,0.227099,0.083804,0.018843,-0.375302,0.352920,0.033530,-0.376586,-0.961456,0.149595,0.034782,-0.006943,-0.635287,0.249881,0.033360,-0.414276,0.065125,-0.453015,-0.071792,0.561696,0.274198,0.338254,-0.424508,-0.083841,-0.514025,-0.020643,0.619295,-0.002363,-0.518894,0.490171,-0.290061,-0.609033,-0.392052,-0.300910,0.088361,-0.124697,0.242892,0.407030,-0.134568,0.391588,-0.713090,0.290686,-0.315176,-0.356550,-0.041251,-0.508556,-0.138595,-0.538126,-0.159847,-0.133784,-0.230949,0.168816,0.008706,-0.760798,0.827440,-0.938969,0.217474,0.490017,0.625787,-0.356493,0.492558,-0.287063,0.300389,-0.285761,-0.233796,0.082431,-0.057926,0.386589,0.098745,0.253785,0.134521,-0.174614,-0.357395,0.756927', '1793491', '3769423', '1811755', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3578981', '叶问2：宗师传奇', '动作', '叶问（甄子丹 饰）携家眷来到香港，艰难度日。叶问开武馆宣扬咏春拳术，但无人问津。某日，黄梁（黄晓明 饰）登门拜访，比武之后，甘愿携一班兄弟，拜在叶问门下。黄梁因故与洪拳门下斗殴，结果被捉。叶问来救，却巧遇昔日对手金山找（樊少皇 饰），两人冰释前嫌，却不想被洪拳掌门洪震南（洪金宝 饰）拦下，以致众人被警察（郑则仕 饰）拘捕。洪震南提醒叶问，欲在香港开武馆，必须接受各大门派挑战。于是叶问单刀赴会，最终与洪震南对决，不分伯仲，叶问因拒绝缴纳会费，而遭到洪门寻衅滋事，以致武馆被关。背地里，洪震南替英国警察操持华洋比赛，但始终未有报酬，深感不平。拳击冠军龙卷风来到中国，在比赛现场中侮辱中国武术，打伤中国拳师。洪震南挺身而住，血溅现场。为了中国武术的荣誉，叶问接受了龙卷风的挑衅，为民族大义而战……©豆瓣', '甄子丹', '叶伟信', 7.4, 246214, 'tt1386932', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1556481862.jpg', 0.6, 3.5, 36.5, 44.8, 14.7, '-0.021888,0.107597,-0.219671,0.219202,0.189595,-0.353604,-0.010857,0.393940,-0.248812,-0.410051,0.491924,0.505053,-0.074189,-0.007222,0.069308,-0.612029,0.173076,-0.518039,-0.053029,0.026485,0.059428,-0.258679,0.339141,0.078986,-0.527300,0.113064,0.373771,0.163367,-0.378710,0.594971,0.582893,0.360738,-0.162750,0.345376,0.006695,-0.082902,0.106938,0.234123,-0.624013,0.287263,-0.259870,-0.581028,-0.368496,0.060376,-0.009882,0.433353,0.144097,0.400939,0.059642,-0.434460,0.079684,-0.444222,-0.047162,0.350634,0.349524,0.354529,0.362904,0.092916,0.193149,0.167190,0.088698,-0.190533,-0.051679,0.371878,0.423439,-0.232880,-0.411880,0.488780,-0.287741,0.009291,-0.295835,0.015944,0.045462,0.163890,0.370949,-0.010083,0.085915,-0.069012,-0.352668,0.119113,0.571143,-0.533752,0.244795,-0.208107,0.326017,-0.109085,0.562993,-0.387176,0.158871,0.039872,0.310978,-0.186526,0.097623,0.029222,-0.264650,-0.078754,-0.224459,0.074482,-0.282683,-0.343350,0.231293,-0.832611,0.085551,0.086301,-0.098825,0.027171,0.213297,-0.117164,0.347422,-0.559111,0.074075,0.094483,0.375864,-0.436361,0.492006,0.152898,-0.059065,0.038171,-0.103772,0.047999,0.402945,0.425379,0.018988,0.034598,-0.080709,-0.094507,-0.039626,-0.129088', '24751811', '3230460', '25833539', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3582181', '海洋深处', '剧情', '故事发生在1820年的冬天，一条名为埃塞克斯号的捕鲸船航行在广袤的南太平洋，让所有船员们都没有想到的是，此时的海底，潜伏着一条拥有着高超智商和强烈的复仇意识的鲸鱼，正准备执行它的复仇计划。很快，捕鲸船就遭到了鲸鱼三番五次的猛烈进攻，脆弱的船身在体型庞大的鲸鱼的撞击下很快就变得支离破碎，船员们伤亡惨重。包括大副欧文（克里斯·海姆斯沃斯 Chris Hemsworth 饰）、船员尼克森（汤姆·赫兰德 Tom Holland 饰）、马修（希里安·墨菲 Cillian Murphy 饰）在内的一群幸存者们挤在小船上，在茫茫大海中漂泊了90天。在这90天里，人间地狱的景象在小船中轮番上演。©豆瓣', '克里斯·海姆斯沃斯', '朗·霍华德', 7.5, 36670, 'tt1390411', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2267432237.jpg', 0.2, 2.7, 33.3, 48.2, 15.6, '0.245423,-0.194618,-0.995025,0.670296,0.176094,-0.011959,1.124053,0.003562,-0.414928,0.075882,0.435227,0.547020,-0.279279,0.015230,0.212345,-0.108132,-0.460208,-0.585352,-0.520083,-0.032257,-0.463017,-0.493266,-0.363477,-0.290117,0.183622,-0.524054,0.453418,0.186841,0.002806,0.398503,0.187159,0.059709,-0.114236,0.458072,-0.450504,-0.001872,0.114810,-0.247635,0.304908,-0.039959,-0.409381,-0.212172,-0.040762,0.071523,0.029149,0.254801,0.985162,-0.689988,-0.012064,0.104220,-0.047163,-0.260719,0.162464,0.125649,0.565092,-0.108244,-0.309417,-0.065074,-0.264167,0.102323,0.215790,0.018502,-0.694184,-0.088252,-0.344306,0.452224,-0.509863,0.360857,-0.016549,0.092692,-0.026817,-0.459493,0.041855,0.123346,-0.122509,0.517511,-0.033794,0.285140,-0.548276,0.042834,0.906888,0.110931,-0.505169,0.009514,-0.267060,-0.121601,-0.211594,-0.160378,-0.401936,-0.557283,0.722375,-0.027730,-0.335249,0.479602,-0.795004,0.320598,-0.359647,-0.882669,-0.451095,-0.016007,-0.607979,-0.781888,-0.012539,-0.464120,0.038753,0.440113,-0.084523,-0.104029,0.861610,-0.720689,0.451014,0.610865,0.030415,-0.031876,0.583360,-0.090562,-0.046972,0.197383,-0.111269,0.086528,-0.024843,0.343561,0.304756,0.506961,-0.315781,0.042356,-0.375058,0.591740', '21619567', '1473795', '2269893', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3582229', '麦田', '剧情', '战国时代，赵国小城潞邑的城主剧葱大人（王学圻 饰）在祭司（王姬 饰）的主持下，举行了与佳人骊（范冰冰 饰）大婚之礼。此时，突然传来秦国大军压境，逼近长平的消息，剧葱达人只得率兵奔赴前线。结果，长平之战，赵国全军覆没。战后，身为秦国锐士的暇（黄觉 饰）为回乡割麦所以临阵脱逃，却在半路碰到了贪生怕死的辄（杜家毅 饰）。两人为了躲避秦王诛杀令，阴差阳错闯进了潞邑。为了活命，他们只得假冒赵国的士兵，并编造了赵国战胜秦国的誓言。骊和祭司聆听着他们的讲述，一方面对胜利的结果感到心安，另一方面却觉得此事另有蹊跷。大嘴巴的侍女不断把谎言的片段传播出去，全城的女人都为之动容，她们期待着自己男人的归来。然而，却等来了无恶不作的强盗（王志文 饰）……©豆瓣', '范冰冰', '何平', 5, 18659, 'tt1388901', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1334308069.jpg', 13.9, 34.7, 39.5, 9.6, 2.3, '-0.070682,0.176629,-0.575680,0.535785,0.087087,0.022289,0.483154,0.350327,-0.765465,-0.168426,0.409221,0.416771,-0.257352,-0.270907,0.315986,-0.111976,-0.269057,-0.595215,-0.054009,-0.147736,0.066301,-0.135555,-0.100630,-0.244472,-0.202908,-0.117161,0.471513,0.195377,-0.067967,0.595366,0.232312,0.217057,-0.121347,0.717038,0.080090,0.025956,-0.300292,-0.164500,-0.239995,0.078742,-0.183579,-0.377951,-0.460734,0.291983,-0.264243,0.430774,0.622403,-0.608094,0.259717,-0.209460,0.240386,-0.454034,0.230909,0.070337,0.096785,0.140792,0.182555,0.366185,0.073956,-0.091870,0.126721,0.069967,-0.617071,0.307875,0.091930,0.224261,-0.585128,0.543492,-0.176133,-0.010099,0.148804,-0.302075,0.297791,0.519973,0.122617,0.164972,-0.352420,-0.099786,-0.613479,0.190646,0.585896,-0.052098,-0.001908,-0.165978,0.105333,-0.526368,0.257613,-0.123228,-0.431394,-0.012269,0.152336,-0.051548,0.060766,0.079046,-0.290912,-0.250354,-0.521748,0.001299,0.156841,-0.194058,-0.070529,-0.312118,0.120886,-0.002236,-0.304326,0.132633,0.430882,0.093061,0.472216,-0.588779,-0.307791,0.521747,0.650749,-0.597994,0.309967,0.188087,0.048170,0.094396,-0.357138,0.075577,0.086579,0.322127,0.114439,0.067624,-0.271383,-0.227944,-0.438468,0.179443', '1301022', '1395445', '35030151', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3586725', '金氏漂流记', '剧情', '金盛瑾（郑在泳 饰）因公司重组而失去了工作，同时债台高筑，妻子也离他而去，对人生彻底失望的金盛瑾爬上了汉江的大桥，纵身一跃…… 然而金盛瑾醒转过来之后，发现自己漂流到了汉江的江心小岛上，短暂的脱身努力失败后，金盛瑾在城市的边缘陷入了鲁宾孙一般的境地，回想起现代生活的局促忙碌，金盛瑾放弃了自杀的念头，开始依靠小岛上的各种废品过起了化外人生。与此同时，在城市高楼中，一位有自闭症的金小姐（郑丽媛 饰）恰巧用相机目睹了金盛瑾自杀的情形，这个一年中只在演习时窥探大街的女孩生活中自此闯入了一个外星人般的都市鲁宾孙。金小姐在夜晚时分进入对她来说危机四伏的街道，以便给金先生送出自己的信号，而金盛瑾则用沙滩上的大字来回应，这对儿奇妙的笔友慢慢维系着这份情谊，但是在纷乱的都市中，这段关系会走向何方呢？©豆瓣', '郑在泳', '李海俊', 8.3, 61890, 'tt1499666', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p617595199.jpg', 0.4, 1.5, 15.9, 48.1, 34.1, '0.288991,0.358132,-0.796000,0.556970,0.062233,-0.347905,0.759115,0.102819,-0.511908,0.086914,0.215496,0.728086,-0.030031,0.361298,0.378727,0.110321,-0.258505,-0.642319,-0.023692,-0.410006,-0.538504,-0.459504,-0.363541,-0.160796,-0.117142,-0.165097,0.533646,0.352779,-0.237988,0.520284,0.125167,0.056471,-0.065693,0.615056,-0.178627,0.060112,-0.123133,0.197344,-0.152445,0.353669,-0.052126,-0.443970,0.008192,0.149383,-0.003576,0.280772,1.024627,-0.340196,-0.118241,-0.055088,0.435170,-0.121565,-0.102912,0.056795,0.331450,0.092653,-0.145424,0.041365,-0.566156,0.006596,0.083028,-0.127850,-0.425726,-0.039324,-0.068317,0.126173,-0.748516,0.476822,0.137825,-0.232457,0.059512,-0.425802,0.394507,0.362616,0.307267,0.482119,-0.245749,0.026671,-0.329860,0.242686,0.672542,0.124341,-0.202476,0.400767,-0.086663,-0.375621,-0.216872,-0.024324,-0.298347,-0.487848,0.297345,0.103498,-0.446097,0.122267,-0.655324,0.255861,-0.143057,-0.202983,-0.111909,-0.310973,-0.453919,-0.554918,0.011319,-0.239312,-0.096443,0.102747,-0.161448,-0.162238,0.513863,-0.748011,0.334401,0.560094,0.288634,-0.078455,0.811792,-0.047456,0.224380,0.000285,0.101258,0.320583,-0.186041,0.731738,0.129996,0.141912,-0.489940,0.162181,-0.568243,0.548057', '21619567', '1309194', '26418093', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35871767', '东北告别天团', '喜剧', '范大明白（崔志佳 饰）在东北从事着白事行业，与众不同的是，范大明白愿意接纳刑满释放的人，为他们提供工作机会。这一天，一名叫做牛硬朗（宋晓峰 饰）的男人来到店里，抛出了豪华大单——三百万的葬礼，范大明白及团队惊讶不已……在办葬礼的过程中，范大明白和牛硬朗才发现，原来二人之间的渊源不止如此……', '崔志佳', '崔志佳', 5.9, 21305, 'Goodbye', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2872048832.jpg', 4.1, 19.1, 56.3, 15.9, 4.6, '-0.099662,0.136939,-0.981047,0.305787,-0.172028,0.066414,0.384234,-0.175830,-0.540779,-0.568253,0.050971,0.646701,-0.167781,0.320392,0.588516,-0.338995,0.200041,-0.243408,-0.370753,-0.348677,-0.053574,-0.853633,-0.337000,-0.310934,0.022777,-0.460828,-0.022889,0.344729,-0.062056,0.576876,0.675156,0.106030,0.057039,0.055528,-0.128386,-0.128390,-0.040060,0.213711,-0.393814,-0.056722,-0.187308,0.388198,-0.171252,0.034097,0.119169,0.022640,0.273931,0.096999,-0.531261,0.150329,0.455765,0.099481,0.074880,-0.207239,0.337555,0.138133,0.304757,0.050341,-0.341207,0.191561,0.280179,0.077933,-0.585449,0.366689,0.154546,0.147184,-1.044770,0.373986,0.082354,-0.118404,-0.329968,-0.818352,0.206314,0.461751,0.677418,0.607134,0.341034,0.447931,-0.628044,0.136921,0.755282,-0.132747,-0.102167,0.312658,-0.106891,-0.564851,0.033855,-0.140488,-0.049519,-0.046137,-0.028283,0.103060,0.119138,-0.361453,-0.105993,-0.192051,0.028253,-0.180786,-0.076323,-0.371453,-0.231028,-0.396070,-0.288394,-0.352747,-0.191062,0.445166,0.050610,-0.532644,0.583310,-0.748921,0.217946,0.351054,0.316675,-0.683411,0.932250,0.149498,0.027735,-0.517128,-0.495338,-0.262720,0.091188,-0.454844,0.157544,0.057873,-0.487373,-0.604451,-0.291683,0.018913', '1303485', '1293607', '2990737', '25908042');
