INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('35914264', '山村狐妻', '悬疑', '民国年间，一场大雨困住了准备渡河前往喇叭沟唱红事的戏班子。雷雨交加的夜晚，与戏班子一同避雨的竟还有杀人如麻的山匪、身份不明的巡捕…一群各怀鬼胎的人，竟都与十五年前的狐妻事件密切相关···', '盛冠森', '刘轩狄', 6.5, 11368, 'tt21158910', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2874021395.jpg', 1.7, 12, 50.2, 31.1, 5.1, '0.321461,-0.434555,-0.378228,0.440635,0.245242,-0.078266,0.694474,0.182564,-0.637622,-0.394161,0.358369,0.274687,-0.290770,0.143873,0.366893,-0.361795,-0.413481,-0.901238,-0.431441,-0.256737,-0.364983,-0.095824,-0.085861,-0.106187,0.284163,0.039860,0.390988,0.534877,-0.189208,0.598863,0.362513,-0.180232,-0.795127,0.553415,-0.301784,-0.137821,0.005594,0.274698,-0.376280,-0.293760,-0.425754,-0.642761,-0.442859,-0.390062,0.012127,0.572879,0.485477,-0.556886,0.007643,0.045067,-0.040489,-0.216305,-0.015778,0.220867,0.710475,0.043732,0.364969,0.375277,0.089808,-0.222472,-0.083721,-0.060892,-0.470509,0.494407,0.302110,-0.074379,-0.472486,0.435617,0.237719,0.039093,-0.019324,-0.208511,0.329279,0.297577,0.169306,0.642284,-0.094797,-0.285727,-0.606155,0.336175,0.803112,0.006674,-0.043395,0.071520,0.207198,-0.518349,-0.055836,-0.132323,-0.171977,0.068056,0.176246,-0.473939,-0.201293,0.541628,-0.669399,-0.066215,-0.240748,-0.130824,0.052176,0.037502,-0.232317,-0.794183,0.117710,0.021010,-0.091536,0.595912,0.571766,0.374911,0.303863,-0.453837,0.221468,0.624399,-0.059569,-0.324537,0.650548,0.065975,0.222509,0.185948,-0.204478,-0.333392,-0.043985,0.615089,0.125269,0.263590,-0.425681,-0.016447,-0.251476,0.254118', '10466639', '25723905', '3147969', '3387546');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3592853', '饥饿游戏', '动作', '北美洲在一场大战后被摧毁，在美国原来的废墟上，人们建立了新的家园，但新政权规定：管辖下的12个地区每年都必须进贡少年男女，参加一档电视直播节目“饥饿游戏”（Hunger Game）。节目的规则很简单——杀人或者被杀。凯妮丝Katniss Everdeen（詹妮弗·劳伦斯 Jennifer Lawrence 饰）的妹妹不幸在12区“选择日”时被选中，由于要保护妹妹，凯妮丝自告奋勇要替妹妹上场 。她不得不与心上人盖尔Gale Hawthorne（利亚姆·海姆斯沃斯 Liam Hemsworth 饰）分开，跟同时被选为12区贡品代表的皮塔Peeta Mellark（乔什·哈切森 Josh Hutcherson 饰）进入游戏。尽管凯妮丝自小就进行狩猎，拥有过人的弓箭技巧，对节目里的重重障碍都能应付自如，但她在比赛中要与残忍强壮的他区选手互相周旋，要想成为最后的赢家就必须成为一个没有人性的杀人机器，这对她是一个极大的考验。《饥饿游戏》是美国作家苏珊·柯林斯（Suzanne Collins）同名青少年科幻小说三部曲中的第一部（其余两部分别名为《星火燎原 Catching Fire》和《自由梦幻 Mockingjay》）。', '詹妮弗·劳伦斯', '盖瑞·罗斯', 7.1, 347869, 'tt1392170', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209718348.jpg', 1.7, 7.4, 40.2, 37.7, 13.1, '0.168181,0.106575,-0.545420,0.505507,0.016052,-0.050788,0.530527,-0.106479,-0.252417,-0.094999,0.250424,0.923116,-0.131719,-0.021782,0.200031,-0.040969,-0.375888,-0.553911,-0.123284,-0.142033,-0.384227,-0.507715,-0.126481,-0.069190,-0.100268,-0.402633,0.763325,-0.042007,-0.238631,0.314038,0.290488,0.124515,-0.004643,0.145572,-0.171398,-0.260503,0.291389,-0.083333,-0.335501,0.418012,-0.174662,0.032124,-0.281593,0.213825,0.198966,0.376636,0.681716,-0.419446,0.091747,-0.096196,0.316453,-0.322686,-0.061230,0.167189,0.170883,0.055996,0.291892,0.218933,0.020450,0.074238,-0.024043,-0.383620,-0.903435,-0.057473,0.353353,-0.031738,-0.468708,0.541213,-0.056022,-0.044908,0.018895,-0.109101,0.098176,0.346670,0.456176,0.251510,-0.102286,-0.126231,-0.422988,0.195052,0.756527,-0.034317,-0.267824,0.211745,-0.109131,-0.527248,-0.089171,-0.473255,-0.448287,0.025656,0.265946,-0.114190,-0.069971,0.258344,-0.762937,0.104680,-0.218990,-0.316140,-0.043624,-0.426720,0.084880,-0.628448,0.161401,-0.307841,-0.151054,0.135784,0.269394,-0.341744,0.868006,-1.002616,0.271703,0.570562,0.475734,-0.474723,0.596588,0.28