INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3592854', '疯狂的麦克斯4：狂暴之路', '动作', '未来世界，水资源短缺引发了连绵的战争。人们相互厮杀，争夺有限的资源，地球变成了血腥十足的杀戮死战场。面容恐怖的不死乔在戈壁山谷建立了难以撼动的强大武装王国，他手下的战郎驾驶装备尖端武器的战车四下抢掠，杀伐无度，甚至将自己的孩子打造成战争机器。在最近一次行动中，不死乔的得力战将弗瑞奥萨（查理兹·塞隆 Charlize Theron 饰）带着生育者们叛逃，这令不死乔恼羞成怒，发誓要追回生育者。经历了激烈的追逐战和摧毁力极强的沙尘暴，弗瑞奥萨和作为血主的麦克斯（汤姆·哈迪 Tom Hardy 饰）被迫上路，而身后不仅有不死乔的追兵，还有汽油镇、子弹农场的重兵追逐。末世战争，全面爆发……©豆瓣', '汤姆·哈迪', '乔治·米勒', 8.6, 491159, 'tt1392190', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2236181653.jpg', 0.5, 1.4, 11.8, 37.6, 48.7, '-0.125153,0.078982,-0.904193,0.571895,0.115949,0.160192,0.777089,-0.058015,-0.122655,0.026542,0.370517,0.455588,0.017387,-0.270039,-0.057850,-0.434752,-0.112549,-0.527589,-0.181831,0.329341,-0.563811,-0.164208,-0.367173,-0.445340,-0.067954,-0.535596,0.868866,0.262963,-0.397660,0.280236,0.061771,0.349469,0.026764,0.504599,-0.305549,-0.153209,-0.155283,-0.163277,-0.138779,0.112244,-0.254747,-0.073105,-0.102514,0.240268,0.064171,0.147504,0.799177,-0.324596,0.145399,-0.432233,0.288293,-0.372727,0.035054,-0.022352,0.477950,-0.073796,-0.085347,0.201827,0.084214,0.000382,0.058739,0.003383,-0.811325,-0.116539,0.019138,-0.250608,-0.540033,0.443294,-0.121710,-0.134497,0.118092,0.233858,0.254466,0.475798,0.177715,0.215813,-0.071276,-0.162156,-0.703593,0.171637,0.582985,-0.243357,-0.519393,-0.089238,-0.331030,-0.423482,-0.356983,-0.739976,-0.516365,-0.205272,0.509433,-0.085176,-0.041868,0.595029,-0.748290,0.192776,-0.130478,-0.316093,0.102888,-0.091386,-0.353148,-0.820571,-0.274919,-0.486114,-0.196757,0.293799,0.027233,0.056616,0.714818,-0.552073,-0.043537,0.513427,0.430078,-0.548730,0.419676,-0.046705,0.209229,-0.107940,0.038449,0.359156,0.049299,0.301173,0.490873,0.063860,-0.055982,0.142026,-0.082722,0.534326', '1578502', '26667010', '1294917', '10747855');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3592859', '囚徒', '剧情', '凯勒（休·杰克曼 Hugh Jackman 饰）是一名木匠，一次意外中，他的女儿安娜（艾琳·格拉西莫维奇 Erin Gerasimovich 饰）同小伙伴乔伊（凯拉·德鲁·西蒙斯 Kyla Drew Simmons 饰）一起莫名失踪。对于女儿遭遇的不测，心急如焚的凯勒向警方寻求帮助，很快，案件的负责人洛基（杰克·吉伦哈尔 Jake Gyllenhaal 饰）就将目标锁定在了一位名叫艾利克斯（保罗·达诺 Paul Dano 饰）的男子身上。不幸的是，由于证据不足，警方不得不在四十八小时之后释放了艾利克斯，对警方失望透顶的凯勒决定靠自己的力量寻找女儿的踪迹。经验丰富的凯勒亲手捉住了艾利克斯，他希望能够通过武力获取关于女儿的讯息。安娜和乔伊最终能够获救吗？坚称自己无辜的艾利克斯又是否真的就是罪魁祸首呢？©豆瓣', '休·杰克曼', '丹尼斯·维伦纽瓦', 8.1, 107552, 'tt1392214', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2119799056.jpg', 0.3, 1.2, 17.3, 54.7, 26.6, '0.364028,-0.078480,-0.640009,0.461304,-0.085023,-0.423521,0.342154,-0.067025,-0.576220,-0.444058,0.495016,0.786946,-0.140936,0.141411,0.161110,0.206931,-0.454846,-0.673254,0.170609,-0.401415,-0.446502,-0.764331,-0.295045,-0.345462,0.046387,-0.475263,0.408488,-0.225265,0.064395,0.280117,0.303469,0.666463,0.174233,0.306020,-0.024076,0.237311,0.307475,-0.353106,-0.319266,0.521472,0.382323,0.046076,-0.044574,0.413301,0.135067,0.437083,0.651057,-0.523015,0.145245,-0.016645,0.163396,-0.294224,0.382768,0.145714,0.227291,-0.248413,0.165345,0.261237,-0.377689,-0.334549,0.300735,-0.081923,-0.612812,-0.068332,0.110891,0.227706,-0.314899,-0.028322,-0.404481,0.114029,0.340634,-0.317539,-0.094689,0.429100,0.326236,0.291340,-0.130085,-0.061528,-0.111709,-0.158159,0.327492,0.044123,0.009840,0.204926,-0.390094,-0.369074,-0.117312,-0.156667,-0.564508,0.129659,0.635217,0.278667,0.121905,0.499731,-0.268758,-0.348395,-0.765700,-0.021067,-0.058497,-0.286678,0.091486,-0.430465,0.039531,-0.077751,-0.119354,0.146333,0.000701,-0.203337,0.445793,-0.658583,0.193832,0.720053,0.342911,-0.136425,0.322385,-0.094572,0.051860,-0.452852,-0.020154,0.358011,0.340028,0.116573,0.345935,0.189842,0.139526,-0.291621,-0.274727,0.334231', '3014957', '1309069', '20277632', '1478582')