INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3596502', '唐山大地震', '剧情', '1976年7月27日夜，唐山地区爆发7.8级强烈地震，房屋倒塌，灾民无数。面对即将坍塌的危楼，丈夫方大强（张国强 饰）和妻子李元妮（徐帆 饰）都要去救被困的龙凤胎儿女方登（张子枫 饰）、方达（张家骏 饰）。危急时刻，方大强拦住了妻子，冲进去营救时不幸罹难。李元妮在震后发现，一双儿女被困在一块水泥板两端，若要营救，必然牺牲一方。情急之下，她做出了艰难选择——救弟弟。此事成为方登心中难以磨灭的隐痛。后来，她被军人王德清（陈道明 饰）夫妇收养。高考后，方登（张静初 饰）进入杭州医学院学习，并与研究生师兄杨志（陆毅 饰）产生了感情……方达被救却断了胳膊，李元妮以无私的母爱抚养他成人。成年后的方达（李晨 饰）去杭州闯荡，娶了媳妇小河（王子文 饰），并干出了一番事业。32年后，这家人的命运却因为5·12汶川地震再次发生了交叠……©豆瓣', '徐帆', '冯小刚', 7.8, 427336, 'tt1393746', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p545837150.jpg', 0.7, 2.6, 24.4, 49, 23.2, '-0.313544,-0.047372,-0.537815,0.160313,0.207816,-0.301394,0.602111,0.206215,-0.426051,-0.161099,0.438383,0.541740,-0.120046,0.256516,0.173150,-0.107309,-0.136702,-0.526775,0.192260,0.007239,-0.225058,-0.164000,-0.027611,-0.090125,0.025683,-0.150886,0.564459,0.131566,0.068020,0.566111,0.097997,0.201737,-0.106627,0.290921,0.054513,0.271847,-0.156572,0.260342,-0.350918,-0.008225,-0.166798,-0.309439,-0.057389,-0.088924,-0.047169,0.325558,0.490972,-0.092579,0.073577,-0.274109,0.407969,-0.203861,0.032029,0.295599,0.262954,-0.026916,0.160365,0.359930,-0.164070,-0.150689,0.385122,-0.259911,-0.233807,-0.040982,0.274960,-0.216917,-0.780972,0.244479,0.021373,0.056212,-0.022022,-0.266894,0.131658,0.411079,0.139388,0.331570,-0.592322,0.200942,-0.227923,0.309176,0.669275,-0.302452,0.106599,-0.038029,-0.068850,-0.337942,0.032748,-0.328356,-0.424806,0.116408,0.422221,0.199835,-0.165983,0.183465,-0.172439,-0.300083,-0.435245,0.074697,0.104908,-0.180294,-0.057155,-0.119497,-0.034421,-0.046554,-0.246344,0.174969,0.084851,-0.260761,0.501898,-0.366190,0.198759,0.218901,0.376178,-0.544950,0.460057,-0.049982,0.205727,-0.241520,0.142597,0.391300,-0.221348,0.322291,0.039319,0.084509,-0.143765,-0.048257,-0.114541,0.227506', '1306505', '25721544', '1316525', '1308035');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3596513', '天水围的夜与雾', '剧情', '香港天水围发生了一件令人惨不忍睹的血案。丈夫残忍地杀害了妻子和双胞胎女儿后自杀。案发后，天水围的女人们纷纷在电视里看到，死者竟然曾是跟自己一同生活的晓玲（张静初 饰），她是四川人在酒楼做服务生，她的丈夫是中年离异靠综援救济的无业游民李森（任达华 饰）。李森平日里总担心妻子红杏出墙，因此总虐待她，两人情感早已破裂。想当年，李森是嫖妓时认识了晓玲，两人因性生爱，并且她还怀了他的小孩。为此，他跟前妻离婚，陪来到了她的老家——四川，帮岳父家装修了房子，并正式办了婚事。但是，心术不正的李森在此期间强奸了晓玲的妹妹。后来，晓玲产下一对双胞胎，两人搬到了天水围，但迫于经济压力，两人矛盾重生，当晓玲准备独立时，李森却开始用变态的手法折磨她……本片是许鞍华导演继《天水围的日与夜》后，拍摄的第二部反映“天水围”的影片。©豆瓣', '任达华', '许鞍华', 7.6, 46670, 'tt1392249', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2157922192.jpg', 0.4, 2.4, 31, 50.9, 15.3, '0.228285,-0.416503,-0.594188,0.154640,-0.194705,-0.168149,0.535279,0.390364,-0.577169,-0.057615,0.392850,0.782148,-0.143010,0.500715,0.168211,0.157860,-0.255732,-0.834530,0.035121,0.054387,-0.212690,-0.241207,0.014415,-0.233703,-0.055036,-0.281744,0.248944,-0.086853,-0.079248,0.253641,0.268798,0.114216,-0.319885,0.377349,-0.196869,0.327081,0.059090,0.157576,-0.339260,0.165301,-0.157778,-0.193609,-0.171185,-0.052100,0.133446,0.525584,0.623926,0.037806,-0.155599,-0.157157,0.338479,-0.296959,-0.321698,0.229904,0.273467,-0.077232,0.482567,0.348650,-0.295252,-0.113670,-0.001377,0.015223,-0.414806,0.242064,0.136427,-0.123825,-0.722118,0.435301,-0.023739,0.010859,0.041152,-0.207891,0.222626,0.267099,-0.234628,0.494377,-0.099112,-0.000135,-0.297520,0.389502,0.784525,0.036477,-0.018698,0.403147,-0.085862,-0.141839,-0.004322,-0.091971,-0.502094,0.089754,0.252132,-0.075389,-0.233183,0.126012,-0.447758,-0.215170,-0.389258,0.125073,0.108181,-0.166083,-0.151018,-0.513218,-0.277416,-0.551979,-0.243861,-0.140823,0.090172,-0.109865,0.556049,-0.525770,0.085680,0.208167,0.340859,-0.734636,0.574789,0.275161,0.105184,-0.147608,-0.070749,-0.136734,-0.269928,0.210607,0.277554,0.211835,-0.054070,-0.055876,-0.329112,0.186439', '30162520', '1308035', '1299584', '1418613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3597344', '枪声俱乐部', '剧情', '“一张照片，也许可以改变世界”----它根据故事中的两位主角Greg Marinovich和Joao Silva的回忆录改编，讲述一位图片编辑Silva（玛琳·阿克曼饰）与她的四位战地摄影师，其中包括主角Greg Marinovich（瑞恩·菲利普饰演），他们组成枪声俱乐部，深入南非用自己的相机和镜头记录和揭示了这里的秘密和罪恶。影片的背景设置在90年代初南非种族隔离后的第一次自由选举时期，他们来到这片充满了血腥和暴力的所在，在枪声和威胁中拍摄了极端优秀的作品，这些作品后来也获得了当年的普利策奖，与此同时，他们也付出了沉重的代价。。。◎幕后制作影片充满诚挚与刺激,在揭露道德与真相的同时,也有裸露和性感镜头造势。而摄影爱好者大概不能错过电影中各式相机的出场,有老式胶片机也有现代数码相机。', '瑞恩·菲利普', '史蒂文·西尔弗', 8.1, 7088, 'tt1173687', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1523818491.jpg', 0.5, 2, 19.3, 50.6, 27.5, '0.165971,-0.086420,-0.683191,0.849918,0.149684,0.225133,0.856434,-0.138767,-0.197678,-0.110169,0.185704,1.087073,-0.259294,0.126870,0.233025,-0.184280,-0.594305,-0.855978,-0.277215,-0.188531,-0.349187,-0.506127,-0.382437,-0.274079,-0.069521,-0.435193,0.872130,0.119598,-0.649262,0.443451,0.409444,0.023298,-0.343289,0.186408,0.049268,-0.099205,0.224944,0.125308,-0.408772,0.136143,-0.067615,-0.363951,-0.152012,0.276676,-0.069868,0.441171,0.723217,-0.384474,-0.178871,0.219070,0.505819,-0.125685,-0.123596,0.027183,0.052191,0.207911,0.520841,0.411890,-0.147397,0.086191,-0.315806,-0.131964,-1.070345,-0.315437,0.208432,0.081937,-0.389860,0.418423,-0.232840,-0.009474,0.247092,-0.145927,0.524796,0.106621,0.483031,0.318250,-0.002888,-0.169896,-0.368955,0.475079,0.297425,0.037096,-0.326060,0.428747,-0.355280,-0.540633,-0.381621,-0.189186,-0.450729,0.199177,0.499471,0.025123,-0.096814,0.103025,-0.724729,0.050170,0.105986,-0.484551,0.093470,-0.312828,-0.147963,-0.989141,-0.428536,-0.553974,-0.183181,-0.176770,-0.006044,-0.392709,1.097966,-0.649980,0.105939,0.402407,0.194081,-0.421897,0.939518,0.144641,0.032583,-0.142215,-0.122594,0.055582,-0.010033,0.221878,0.014987,0.286580,0.034418,-0.320971,-0.463783,0.556867', '3318306', '27602116', '2027945', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3598221', '家族荣誉', '喜剧', '毕业于汉城大学法律系的高材生朴大书（郑俊浩 饰）本来生活平静，相处六年的女友关系稳定，事业也蒸蒸日上，但是这一切在一次与著名黑帮“三J帮”龙头千金张真庆（金晶恩 饰）莫名其妙的同床后改变了……原来张氏黑帮深感自身素质顽劣，为了家族荣誉想要引起一名高学历的女婿，朴大书不幸进入张氏三兄弟视野，被设计安排与真庆同床。此后，张氏三兄弟以同床事件为口实，展开了对大书的威逼利诱。另一方面，张家老爷子对这位未来女婿也颇为中意，朴大书只得受命拜见未来“岳父”，魂飞胆散又深感为难，而真庆虽然出身黑道家庭，可身上并无暴戾之气，在三兄弟的逼迫算计与真庆的柔顺性格的夹击下，独木难支的大书动摇了……©豆瓣', '郑俊镐', '郑兴顺', 6.5, 5415, 'tt0330316', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1846175881.jpg', 1.4, 10, 58, 23.9, 6.6, '0.054176,-0.148458,-0.541395,0.612236,0.094002,-0.428832,0.390794,0.469102,-0.738277,-0.518185,0.126046,0.575085,-0.095404,0.113428,0.262375,-0.291201,0.105199,-0.705324,-0.073798,-0.167762,0.054403,-0.409030,-0.063159,-0.199048,-0.113026,-0.192398,0.681438,0.078772,-0.246361,0.620348,0.244287,0.253394,-0.109052,0.024677,-0.076512,-0.104333,-0.226858,0.418141,-0.716241,-0.008798,-0.106773,-0.121067,-0.015834,0.139917,0.203460,0.219209,0.506432,-0.209605,-0.317029,-0.295050,0.286787,0.015678,-0.159461,0.197772,0.675022,-0.052668,0.264041,0.530469,-0.022000,-0.207032,-0.019855,-0.058592,-0.760928,0.185242,0.251811,-0.217030,-0.789698,0.548380,0.017906,-0.395533,-0.290350,-0.200555,0.010016,0.556365,0.262139,0.431129,-0.285820,0.593954,-0.184648,-0.053736,0.617599,0.105067,0.120094,0.074410,-0.053930,-0.116856,0.146788,-0.566684,-0.447548,-0.006439,0.060540,0.180256,0.103172,0.373661,-0.425422,-0.117953,-0.303734,0.008496,0.191701,-0.598669,0.304618,-0.237909,-0.326131,-0.427875,-0.314336,-0.060244,0.369976,-0.187967,0.757385,-0.835966,0.011160,0.074856,0.255018,-1.040489,0.496987,0.623741,0.407306,-0.296785,-0.216861,-0.094520,-0.018863,-0.035197,0.058739,0.061482,-0.200424,-0.327844,-0.021956,0.047801', '1293265', '1877596', '26678784', '4723944');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3600972', '宝贝和我', '喜剧', '在读高中的俊秀（张根锡 饰），衣食无忧却不爱读书，老是和朋友翘课鬼混，打起架来以一敌十七也绰绰有余。某天，俊秀的父母实在无计可施，留下10万韩元后就离家出走了。当晚，一个名叫乌兰（文梅森 mason 饰）的小婴儿从天而降，正好落在他的购物车里，身上带有一张纸条指明是俊秀的孩子。俊秀只好一边当起奶爸，一边找孩子的妈妈，生活变得忙碌起来。由于无人照顾，俊秀只好带着孩子去上学，却被学校勒令退学。同班的天才美少女金星（金星 饰），自愿帮他照看孩子，还一起为了收集母乳四处奔波。当俊秀对乌兰的感情加深时，乌兰身世之谜也慢慢被揭开……Mason是加拿大及韩国混血儿，与张根锡在合作拍摄的三个月中，建立了亦父亦友的感情，张根锡看见Mason疲倦时，还会唱Wonder Girls的名曲《Tell Me》给他提神，甚至扮鬼脸引他笑。©豆瓣', '张根硕', '金镇英', 7, 41390, 'tt1720044', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2093775786.jpg', 0.8, 5.9, 46.7, 35.2, 11.5, '0.102038,-0.163583,-0.453999,0.585870,-0.380315,-0.462371,0.514499,0.188089,-0.250839,-0.108750,-0.008545,0.502132,-0.051839,0.687533,0.171224,0.004922,-0.343617,-0.632093,-0.116372,-0.116653,-0.265744,-0.323281,-0.143611,0.215648,-0.237055,-0.274577,0.241064,-0.295604,0.079528,0.655962,0.256218,-0.065554,-0.304008,0.249993,-0.295954,-0.177578,-0.445434,0.090554,0.047401,0.150282,0.205346,-0.180174,-0.034504,-0.204350,0.239497,0.288342,0.789017,0.075799,0.192820,-0.296467,0.177322,-0.107019,-0.230409,0.084305,0.292403,0.114710,0.365694,0.024849,-0.238273,0.000802,0.112136,-0.227131,-0.486811,0.306422,0.195839,0.118755,-0.535524,0.506479,-0.115072,-0.135270,0.351046,-0.249004,0.138449,0.172068,-0.003670,0.510993,-0.157793,0.434569,-0.367438,0.305341,0.204097,0.120539,0.148773,0.166312,-0.105325,-0.017722,0.392849,-0.140189,-0.368017,0.070868,-0.019497,-0.023106,-0.064058,-0.093266,-0.385630,0.056477,-0.132795,-0.052403,0.190864,-0.399524,-0.212815,-0.401015,0.036158,-0.329481,-0.208879,0.259458,0.286718,-0.134245,0.833300,-0.470609,0.122254,0.252281,0.366915,-0.387120,0.607957,0.226040,0.102706,-0.078674,-0.222612,0.146637,-0.067720,0.232875,0.111538,0.298879,-0.245896,-0.112939,-0.419420,0.284740', '1307146', '3811356', '25922902', '1945253');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3602084', '波普先生的企鹅', '喜剧', '波普先生（金·凯瑞 Jim Carrey 饰）是一个极富工作热情的高效率商人，在公司里备受重用，但却常常因此牺牲了与家人共处的时光。这个冬天，当他正在全力以赴地争取一位伤脑筋的合伙人时，前妻阿曼达（卡拉·古奇诺 Carla Gugino 饰）也准备开始自己的下一段恋情。 然而这一切随着一个快递箱子的到来而发生了意想不到的逆转——波普先生从已故父亲那里继承到了最不寻常的财产：一只活企鹅。就在他束手无策的时候，竟又收到了另外五只活企鹅。企鹅们一度将波普先生的规律生活与工作弄得一团糟，但他的小儿子却十分喜爱这些企鹅。然而，在纽约这样的大都市里，养企鹅虽是趣事，却绝对不是易事……电影改编自理查德和佛罗伦萨·阿特沃特（Richard and Florence Atwater）共同撰写的同名儿童小说。©豆瓣', '金·凯瑞', '马克·沃特斯', 7.5, 72421, 'tt1396218', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p948036118.jpg', 0.3, 3.1, 34.6, 46.4, 15.6, '0.299270,0.001520,-0.561958,0.572981,-0.067281,-0.354712,0.756960,0.295192,-0.472384,-0.414318,0.011113,0.783758,-0.189623,0.285484,0.142258,0.035548,-0.334864,-0.487781,0.031307,-0.141108,0.010782,-0.222111,-0.366408,-0.164957,-0.150529,-0.036677,0.619326,-0.024809,-0.027367,0.387625,0.145948,0.261779,0.042954,0.482197,-0.302231,0.038837,0.090256,0.207135,-0.012368,0.117808,0.129508,-0.099800,-0.160559,0.226444,0.151386,0.286034,0.450278,-0.403241,-0.257709,-0.089500,0.541576,-0.185614,-0.000927,0.151965,0.322005,0.084754,0.286002,0.114411,-0.284824,0.000796,0.066421,-0.117409,-0.952234,-0.018270,-0.107860,0.326221,-0.666057,0.356857,-0.204576,-0.032634,-0.022761,-0.375244,0.251570,0.483318,0.163662,0.374515,-0.246060,0.048469,-0.616443,0.223150,0.717165,0.035064,-0.294180,0.550022,-0.219288,-0.430180,0.043062,-0.192731,-0.583960,-0.178804,0.206318,-0.067316,-0.047017,0.275728,-0.615461,0.165556,-0.264341,-0.258600,0.014379,-0.460489,-0.169652,-0.561820,-0.018606,-0.471822,-0.321271,-0.017221,0.229523,-0.342344,0.890010,-0.666474,0.147539,0.624241,0.001600,-0.321132,0.710986,0.110138,0.249293,-0.053034,-0.102009,-0.003401,0.147172,0.344066,0.153968,0.333086,0.121840,-0.352402,-0.381042,0.651739', '1793491', '25928048', '2053515', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3603547', '绿头苍蝇', '剧情', '08年韩国独立电影界最震撼人心的作品，由新人导演梁益俊自编自导自演的自传式作品。塑造了一个来自底层的暴力人物，他的青春，他的发泄，他的爱情如同燃烧的火焰。', '金花雨', '梁益准', 8.3, 21980, 'tt1373120', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1969897650.jpg', 0.6, 1.8, 15.9, 46.9, 34.7, '0.255416,-0.243414,-0.618679,1.069577,-0.155963,0.197814,0.940895,0.272601,-0.273579,-0.076797,0.672843,0.904450,-0.234623,0.254295,0.261985,-0.096973,-0.029160,-0.748897,-0.197797,0.162644,0.309230,0.229494,-0.351842,-0.109056,-0.048436,-0.295452,1.178959,0.073022,-0.326185,-0.064242,0.437665,0.217356,0.259480,0.161331,0.071421,-0.198840,-0.006880,0.093937,0.006832,0.316576,-0.115011,-0.412974,0.044206,0.363455,-0.650167,0.368080,0.690326,-0.321910,0.436594,-0.276820,1.056895,-0.635488,-0.206765,-0.187926,-0.156863,0.050145,0.156891,0.152618,-0.032090,0.141300,-0.195339,-0.581382,-1.285318,-0.525174,0.200458,0.087107,-0.570710,0.890939,0.242273,0.120977,0.148419,0.091416,0.036491,-0.530560,0.063117,0.337554,-0.302163,0.174717,-0.430785,1.290368,0.331404,0.056731,-0.723512,0.613841,-0.751044,-0.499510,-0.274233,-0.621702,-0.792541,-0.186969,0.056367,-0.006199,-0.062287,0.204363,-1.035956,-0.031836,-0.002716,-0.227669,-0.018380,-0.620085,-0.330291,-0.602202,-0.589633,-0.132837,0.158807,-0.476125,0.018624,-0.319758,1.424785,-0.391894,-0.245304,0.689540,-0.100552,-0.390161,0.824079,0.144638,-0.378000,-0.229285,-0.163404,0.424620,-0.252195,0.132463,0.010440,0.416850,0.020227,-0.153847,-0.450357,0.946985', '27602116', '22265121', '26310114', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3604148', '小丑回魂', '剧情', '1989年，位于缅因州的德里市，正被恐怖的阴影所笼罩。从上一年开始，儿童失踪案接连发生，似乎某个可怕的未知存在悄然来到了人们中间。痛失弟弟的少年比利（杰顿·李博赫 Jaeden Lieberher 饰），决定和艾迪、瑞奇、史丹利等伙伴利用暑假寻找弟弟乔治的下落。不久之后，遭小坏蛋们欺负的小胖子本、被疯传放荡的坏女孩贝弗莉以及父母死于大火的孤儿麦克相继加入这个受到嗤笑的窝囊废联盟。在这一过程中，他们经历了一连串的超自然的恐怖体验。少年们发现，在这个被诅咒的城市，每隔27年非正常死亡人数就会飙升。狞笑着的小丑（比尔·斯卡斯加德 Bill Skarsgård 饰），深入每个人的心底，挖掘他们最恐惧的部分……本片根据斯蒂芬·金的同名原著改编。©豆瓣', '比尔·斯卡斯加德', '安德斯·穆斯切蒂', 7.4, 185774, 'tt1396484', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2452537144.jpg', 0.9, 4.5, 32.9, 45, 16.7, '0.342761,-0.273618,-0.840014,0.258503,0.000310,-0.044780,0.812736,0.112487,-0.483236,-0.254795,0.218988,0.717131,-0.450506,0.306813,0.215901,-0.128532,-0.236357,-0.541683,-0.365187,-0.347135,-0.313997,-0.261900,-0.332834,-0.192240,-0.053332,-0.425180,0.447826,0.103307,-0.147985,0.410351,0.270072,0.537480,-0.170516,0.255631,-0.134357,0.258174,0.252356,-0.144830,-0.085930,0.100079,-0.128566,-0.071616,0.055636,-0.181406,-0.134598,0.284019,0.767029,-0.353172,0.018884,-0.328835,0.364564,-0.263393,-0.256654,0.140147,0.238732,-0.128547,0.069341,0.114765,-0.153527,-0.020007,-0.052622,-0.168541,-0.793037,0.106297,0.094327,0.153618,-0.452292,0.278071,0.076303,-0.095924,0.246795,-0.173783,0.153411,0.346025,0.106799,0.307929,-0.182650,0.021201,-0.387483,0.098913,0.592811,-0.117359,-0.505578,0.017152,-0.102491,-0.264610,-0.217400,-0.168875,-0.414036,0.129157,0.578364,0.110569,-0.370688,0.502249,-0.675182,-0.018347,-0.199509,-0.432590,0.025787,-0.211015,-0.594799,-0.717777,-0.346713,-0.297551,-0.169177,0.052003,-0.068052,-0.119177,0.789316,-0.758306,0.574670,0.520819,0.188866,-0.402283,0.366014,-0.024116,0.110956,-0.114372,-0.052033,0.417101,0.219432,0.415378,0.137443,0.294276,-0.191962,-0.201482,-0.293502,0.432908', '3005387', '25928048', '4079119', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3606971', '飓风营救2', '剧情', '为了弥合与家人的鸿沟，前中情局特工布莱恩·米尔斯（连姆·尼森 Liam Neeson 饰）邀请情感方面正遭受挫折的前妻丽诺尔（法米克·詹森 Famke Janssen 饰）以及正处在青春期的女儿小金（玛姬·格蕾斯 Maggie Grace 饰）前往伊斯坦布尔度假。然而， 他们的快乐假期还没开始，一伙匪徒便盯上了这一家人。一番激烈的较量过后，布莱恩和丽诺尔沦落敌手，小金则成为最后被追捕的对象。而这一切始于布莱恩当初捣毁阿尔巴尼亚黑帮，当初埋下的仇恨种子生根发芽，围着一家人带来前所未有的灾难。身陷囹圄的布莱恩利用身藏的迷你电话指导女儿如何自救求生，而这一边他也想方设法摆脱匪徒的控制。生死攸关，刻不容缓……©豆瓣', '连姆·尼森', '奥利维尔·米加顿', 6.9, 110179, 'tt1397280', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1611003652.jpg', 0.6, 6, 50.8, 33.4, 9.2, '0.039216,-0.201885,-0.555993,0.363286,0.006871,-0.276277,0.521162,0.110364,-0.447973,-0.223965,0.136866,0.327978,-0.134546,0.186741,0.389525,-0.100136,-0.583918,-0.557635,0.107145,0.115598,-0.118446,-0.407379,-0.379527,-0.154299,0.107404,0.018179,0.715600,0.125638,-0.094610,0.440341,0.301677,0.601484,-0.084262,0.246451,0.018923,0.127523,0.103396,-0.115062,-0.485232,-0.043704,0.168250,-0.120889,0.046416,0.129989,0.054241,0.248520,0.590112,-0.282135,0.254248,-0.443646,0.184442,-0.445732,0.003534,0.329767,0.247664,-0.164039,0.173312,-0.112048,-0.105620,-0.287949,0.195071,-0.177405,-0.779312,0.048889,0.045323,-0.004388,-0.224463,0.220128,0.022753,0.306440,0.036913,-0.278628,-0.006814,0.737129,0.303973,0.228945,-0.487299,-0.214273,-0.398528,-0.065632,0.710673,-0.246862,-0.102701,0.125156,-0.063627,-0.127765,0.138794,-0.298793,-0.347696,-0.314707,0.356870,0.212705,-0.059696,0.505447,-0.486482,-0.095708,-0.518133,-0.082369,0.130090,-0.443962,-0.160576,-0.638393,-0.208815,-0.106298,-0.273957,0.071789,0.130131,-0.158056,0.500638,-0.630817,0.293454,0.540682,0.283326,-0.422378,0.308161,0.063027,0.437678,-0.412524,-0.333801,0.473816,0.046196,0.279335,0.111713,0.067879,-0.139495,-0.006847,-0.175286,0.144056', '2369613', '5157137', '5910040', '25978126');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3606973', '地心历险记2：神秘岛', '动作', '历险新片《地心历险记2：神秘岛》，源于17岁的肖恩•安德森（乔什•哈切森饰演）收到的一组发自无人知晓的神秘岛密码求救信号。因为无法劝阻肖恩追踪信号来源，肖恩的继父汉克（道恩•强森饰演）只能陪着他一起踏上这段南太平洋之行。而他们最终的目的地，是一座没几个活人亲眼见过的岛屿。那里风光旎丽，鸟语花香；珍禽异兽，应有尽有；金山火山，叹为观止；是座无奇不有的神秘天堂。他们俩只找到一个，愿意跟他们铤而走险的直升机驾驶员，嘎巴托（路易斯•古兹曼饰演），和他美丽，坚强的女儿凯兰尼（凡妮莎•哈金斯饰演），四人一起踏上了这段寻岛之旅。一路上他们不仅仅拯救了岛上唯一的人类居民，更在地震冲击波淹没岛屿，埋葬其无限宝藏之前，逃出生天。这一切的一切，都发生在《地心历险记2：神秘岛》上，这是继2008年全球大获成功的《历险之旅1：地心游记》后，另一段惊心动魄的历险故事。©豆瓣', '道恩·强森', '布拉德·佩顿', 6.4, 81796, 'tt1397514', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1557589605.jpg', 2.1, 13.2, 54.7, 23, 7, '0.000807,-0.183304,-0.961359,0.734053,0.155722,-0.085864,0.708719,-0.231632,-0.433119,-0.029030,0.101677,0.722301,-0.311690,0.287516,0.246542,0.249611,-0.410387,-0.304504,-0.236527,-0.365072,-0.283493,-0.348255,-0.345460,-0.069052,-0.019168,-0.178507,0.671094,0.291118,0.011251,0.513314,0.269008,0.187407,-0.245790,0.215259,-0.299262,0.229988,-0.074874,0.054669,-0.328764,0.016738,-0.321298,-0.092449,-0.250233,0.172448,0.086167,0.072565,0.535558,-0.245816,0.009165,0.004991,0.158251,-0.385473,0.107172,-0.129267,0.085612,-0.270160,0.207473,0.273069,-0.131861,-0.139770,0.184967,-0.074199,-0.623999,-0.141096,0.034620,0.032802,-0.384860,0.101307,-0.047267,-0.010428,-0.037318,-0.363959,0.173403,0.280604,0.215507,0.340111,-0.104878,-0.035532,-0.399076,0.141750,0.863787,-0.056472,-0.184569,0.371376,-0.050774,-0.457500,-0.304808,-0.022421,-0.457585,0.160727,0.380282,0.136074,-0.073539,0.163982,-0.549013,0.184577,-0.247182,-0.385852,-0.110034,-0.367651,-0.185180,-0.757230,-0.164896,-0.345917,-0.101306,0.141310,-0.093328,-0.261648,0.594298,-0.396054,0.162835,0.529402,0.094666,-0.194534,0.647658,0.155306,0.026459,-0.234578,0.255204,0.401694,0.050476,0.401889,0.067026,0.202702,-0.028169,-0.070411,-0.713819,0.261296', '34461680', '1293019', '10558440', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3606975', '孔子', '剧情', '公元前六世纪，孔子（周润发 饰）受到鲁定公（姚鲁 饰）赏识，从中督宰晋升为大司寇，这让他得以实行自己的以礼治国的执政理念。但是，三桓独霸朝纲，也让孔子感受到了重重阻力。他因阻止季桓子（陈建斌 饰）家奴免受陪葬，而与之结怨。他随鲁定公赴齐国会盟，与齐景公（马精武 饰）和大夫黎鉏（王绘春 饰）斗智斗勇，维护了鲁国的利益，讨回三城，因此出任代国相。他提出隳三都的政策，引发佞臣谋反，在平叛之后，季桓子假传圣旨，罢黜了孔子。从此，孔子率颜回（任泉 饰）、子路等弟子开始游历各国。在卫国，孔子得到卫灵公的尊重，获俸粟6万石。他见到了卫灵公的夫人南子（周迅 饰），并在交谈中展现了正气凛然的君子风范……本片主题曲《幽兰操》为歌后王菲息声多年后复出之作。©豆瓣', '周润发', '胡玫', 5.6, 85300, 'tt1397498', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2036524094.jpg', 11.1, 23.4, 45.5, 14.9, 5.1, '-0.055431,0.230672,-0.641317,0.689350,0.150889,-0.068819,0.267312,0.636208,-0.416092,-0.299983,0.162967,0.696870,-0.293143,-0.075121,0.263977,-0.084622,0.062262,-0.704868,-0.061047,0.086005,0.254439,-0.332094,0.006258,0.036985,-0.540748,-0.245069,0.481325,0.035096,-0.230131,0.607342,0.028531,0.015520,0.136332,0.450596,0.093562,0.085101,-0.148528,0.134944,-0.386261,0.068474,-0.151774,-0.588554,-0.410723,0.102988,-0.150133,0.446878,0.199447,-0.435186,0.116931,-0.307025,0.386366,-0.135219,0.179695,0.171285,0.173817,0.270342,0.101284,0.571234,-0.069709,0.285017,0.102427,-0.102172,-0.588409,-0.122155,0.048242,0.054141,-0.426874,0.592876,-0.103387,-0.395277,-0.048086,-0.099869,0.319676,0.497313,0.207678,0.051613,-0.168489,0.014849,-0.293753,0.325428,0.319871,-0.269883,-0.178782,-0.170813,0.136915,-0.559805,0.392294,-0.415196,-0.167942,-0.305824,0.196864,-0.211670,0.243827,0.124285,-0.159656,-0.310710,-0.256635,0.060551,0.132793,0.069407,0.376856,-0.268525,-0.295514,-0.414612,-0.144107,0.070431,0.468656,-0.458151,0.588346,-0.518934,0.002654,0.191791,0.444898,-1.034253,0.476239,0.164404,0.051849,0.003233,-0.133986,0.026590,0.196296,0.221707,0.080995,0.238166,0.065943,-0.130518,-0.276121,0.156568', '1302110', '1294693', '1305143', '1297574');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3607666', '高兴', '剧情', '故事发生在陕西，农民刘高兴（郭涛 饰）是个喜欢设计飞行器的有心人。迫于生计，他跟好兄弟五富（冯砾 饰）一起来到西安打工，在老乡韩大宝（林雪 饰）的一间破旧仓库落脚，邻居包括东北大汉黄八（海一天 饰）和一对夫妇种猪（巴多 饰）和杏胡（苗圃 饰）。高兴的工作是收废品，虽然工作不那么光鲜，但是高兴却乐在其中，这种积极的心态感染了五富和邻居夫妇。另外，碰到小流氓石热闹（黄渤 饰）寻衅滋事，也是高兴挺身而出惩恶扬善。一次偶然的机会，高兴结识了按摩小姐孟夷纯（田原 饰），两个人在接触中擦出了爱情的火花。她为了给弟弟（胡清蓝 饰）上学筹钱，她曾委身商人韦达（张兆辉 饰）。高兴得知此事后，决定跟他并不富裕的伙伴们开始了积极的筹款。然而，在他们解决这个难题之后，按摩小姐却因为一次意外锒铛入狱，高兴还能跟她的爱情还会继续吗？……本片根据贾平凹的同名小说改编，开创内地首部歌舞喜剧片类型。', '郭涛', '刘晓光', 6.5, 42400, 'tt1479241', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p916253236.jpg', 3, 12.2, 47.4, 29.5, 8, '0.187804,-0.211791,-0.568829,0.231655,-0.046816,-0.194717,0.453523,0.186409,-0.486781,-0.284897,-0.039244,0.461324,-0.153774,0.279631,0.004787,-0.031575,-0.329887,-0.321217,0.337627,0.037460,-0.060713,-0.321258,-0.094184,-0.574507,-0.176467,-0.111538,0.030641,0.230798,-0.062290,0.609848,0.489227,0.083349,-0.185122,0.416019,-0.172147,0.053219,-0.057741,0.261230,-0.300347,-0.048039,-0.064963,-0.026099,-0.059278,-0.051062,0.500788,0.334009,0.498929,0.037476,-0.315206,0.227309,0.270586,-0.076263,0.076557,0.058824,0.195834,-0.102923,0.389127,-0.142302,-0.121078,0.022970,-0.003520,-0.289474,-0.406096,0.052633,0.264532,0.038203,-0.595697,0.495061,0.103804,-0.039961,-0.061558,-0.322606,0.238939,0.456646,0.274792,0.223295,-0.018973,0.175956,-0.472175,0.588676,0.742702,-0.008669,0.167565,0.407287,-0.190649,-0.336575,-0.028089,-0.066550,-0.405016,0.158646,0.389840,-0.294229,0.056214,-0.172511,-0.460229,-0.126269,-0.095366,0.145061,0.108622,-0.314008,0.130623,-0.297944,0.115043,-0.411508,-0.292487,0.157170,0.077515,-0.331329,0.619251,-0.805432,0.025749,0.323731,0.233723,-0.744773,0.595160,0.178174,0.048534,-0.382724,-0.027517,-0.160705,0.042072,-0.000099,0.201596,0.311557,0.064078,-0.252813,-0.284901,0.035531', '1308035', '1299062', 