INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3608742', '冲出康普顿', '剧情', '1980年代中期，加州康普顿的街头因犯罪、毒品、黑帮等问题成为美国最危险的地方之一，五个出身此地的年轻人：爱斯·库柏（小奥谢拉·杰克逊 O''Shea Jackson Jr. 饰）、MC Ren（阿尔迪斯·霍吉 Aldis Hodge 饰）、德瑞博士（科里·霍金斯 Cor ey Hawkins 饰）、DJ耶拉（小尼尔·布朗 Neil Brown Jr. 饰）、Eazy-E（杰森·米切尔 Jason Mitchell 饰）集合起来，组成了说唱组合N.W.A，将他们的成长经历转化成粗鲁直接的音乐，并借此向当局传达他们的反抗心声。', '科里·霍金斯', 'F·加里·格雷', 7.8, 14945, 'tt1398426', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2249238790.jpg', 0.6, 2.7, 26.4, 45.8, 24.4, '0.357468,-0.109679,-0.512238,0.417541,-0.228970,-0.053055,0.570685,0.162525,-0.377332,-0.188923,-0.011582,0.606345,-0.015872,0.036738,0.281036,-0.088358,-0.462163,-0.634287,0.288569,-0.098331,-0.285488,-0.508993,-0.355067,-0.309008,-0.285684,-0.293241,0.288952,-0.372436,-0.353204,0.392244,0.333825,0.523173,0.102773,0.003735,0.141647,-0.059874,0.332061,-0.350179,-0.247387,0.170219,-0.209010,0.044024,-0.112950,-0.104101,0.077979,0.372407,0.474581,-0.173606,0.589673,-0.436963,-0.061851,-0.088270,-0.068982,-0.094279,0.189115,-0.060970,0.078706,0.183381,-0.096510,-0.085442,0.177049,-0.049502,-0.765699,0.262772,0.202734,0.165753,-0.111808,-0.047024,-0.056146,-0.168212,-0.051182,-0.393400,-0.128280,0.168441,0.308353,0.154825,0.058390,-0.050787,-0.338109,0.024493,0.232684,-0.178075,-0.448217,-0.018537,-0.208400,-0.504139,-0.211178,-0.168068,-0.155990,-0.031813,0.317383,-0.050546,0.149424,0.219528,-0.687288,-0.114486,-0.246193,-0.144741,-0.062920,-0.191165,0.106312,-0.773827,0.064281,-0.137407,-0.224105,-0.206619,0.152442,0.223466,0.705241,-0.084941,0.041856,0.430667,0.460757,-0.084119,0.197627,-0.077245,0.397645,-0.190326,-0.376689,0.515185,0.092990,0.034147,-0.007222,0.348199,-0.060564,-0.274396,-0.110200,0.320656', '3318306', '1293433', '26577354', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3610047', '变形金刚3', '动作', '距今50多年前，一艘来自赛博坦的飞船坠落月球，由此引发了美苏两国的太空竞赛。人类争相登上月球，只为一探飞船残骸中的秘密。时间回到21世纪初，经过几番征战，汽车人终于挫败霸天虎的入侵，继而与人类合作，共同保卫美丽的地球。然而发生在切尔诺贝利的事件却将尘封已久的月球计划重新摆到桌面。为了防止霸天虎找到能量柱为非作歹，擎天柱与战友飞赴月球，更从当年的飞船中救出了汽车人的先代领导者——御天敌。御天敌是能量柱的发明者，将上百根能量柱集合在一起便可制造太空桥，实现物质的瞬间传送。忙着找工作以及和女友卡莉（罗茜·汉丁顿-惠特莉Rosie Huntington-Whiteley 饰）经营爱情的山姆（希亚·拉博夫 Shia LaBeouf 饰）无可避免地卷入其中，他渐渐发现霸天虎的操纵一切的阴谋，却不知更大的阴谋和危机隐藏在那月影背后……©豆瓣', '希亚·拉博夫', '迈克尔·贝', 7.2, 332039, 'tt1399103', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1056093671.jpg', 1.2, 5.9, 38.6, 38.7, 15.6, '0.060664,0.136993,-0.890586,0.623516,0.105269,0.045185,0.679226,-0.137832,-0.310384,-0.015961,0.338975,0.741191,-0.179944,0.030570,0.293924,0.024389,-0.435425,-0.644381,-0.095055,-0.261686,-0.628574,-0.385219,-0.394066,-0.191018,0.164879,-0.410048,0.920385,0.367665,-0.112583,0.256275,-0.128236,0.192770,-0.557990,0.490696,-0.323607,-0.139461,-0.155471,0.106374,-0.276297,0.007277,-0.390475,-0.429006,0.001280,0.082963,-0.087584,0.258489,0.731314,-0.552000,0.253334,-0.205416,0.086401,-0.354085,0.112358,-0.181438,0.447007,0.403877,-0.274863,0.308254,-0.266637,-0.025457,0.344350,-0.143368,-0.568256,-0.247657,-0.152409,0.071516,-0.364684,0.313530,-0.039874,0.051684,0.008469,-0.043406,0.310937,0.539713,0.182983,0.233153,-0.309550,0.255421,-0.414507,-0.102343,0.607031,-0.081923,-0.410547,0.300418,0.049898,-0.240185,-0.357642,-0.104348,-0.050999,-0.430354,0.438272,0.143595,-0.070348,0.645357,-1.076960,0.138145,-0.392004,-0.158549,0.105203,-0.200928,-0.081791,-0.878586,-0.298079,-0.168769,0.051428,0.318179,-0.019263,-0.145300,0.673812,-0.621854,0.158914,0.626551,0.413537,-0.222038,0.525737,-0.232802,0.096048,-0.340575,0.115804,0.097234,-0.137227,0.619896,-0.148038,0.367966,0.125035,0.050310,-0.342198,0.272636', '26290398', '20274039', '1294917', '1856675');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3610676', '冬天的骨头', '剧情', '密苏里州西北部奥萨克地区17岁的少女芮（詹妮弗·劳伦斯 Jennifer Lawrence 饰）独自照看生病的母亲、12岁的弟弟和6岁的妹妹。芮的父亲屡次因制毒成为警察追捕的目标，这次也不例外，数月潜逃未归。眼看出庭日近，芮得知若父亲不出现，作为抵押，全家居住的老屋就要 被法院收走。芮决定寻找父亲的下落，哪怕这意味着她必须接触她那些靠制毒贩毒为生的危险远房亲戚。芮最先求助于叔叔“泪滴”（约翰·哈克斯 John Hawkes 饰），却被赶了出来；她又去找远亲茉莱（德尔·迪克 Dale Dickey 饰），还是被无情驱逐。眼看上庭日迫在眉睫，芮也顾不得众人的劝阻，在这个贫困而又危险的农业社区里一步步接近真相……本片获柏林国际电影节C.I.C.A.E.奖和青年影院陪审团奖（Tagesspiegel），以及圣丹斯电影节评审团大奖和华道索尔剧本奖。©豆瓣', '詹妮弗·劳伦斯', '黛布拉·格兰尼克', 7.3, 35314, 'tt1399683', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2510515532.jpg', 0.6, 4.1, 37.7, 45.2, 12.5, '-0.015052,-0.228370,-0.699935,0.342004,-0.062894,-0.244365,0.580175,0.072430,-0.196588,-0.406101,-0.030476,0.773019,-0.038286,0.346764,0.357311,0.197359,-0.192281,-0.565351,0.055114,-0.353725,-0.136494,-0.246131,-0.089874,-0.186880,-0.031480,-0.021399,0.430740,0.193937,-0.048941,0.479437,0.411051,0.469775,-0.216349,0.363671,-0.080839,-0.067818,0.400534,-0.080082,-0.161730,0.347254,0.203468,-0.459291,-0.034606,0.142508,0.308864,0.638364,0.537615,-0.147995,0.179088,-0.185103,0.400910,-0.513673,0.145582,-0.062706,0.366359,-0.344331,0.113400,0.185916,-0.058371,-0.158308,0.079819,-0.336645,-0.537400,0.205857,0.386556,0.034038,-0.879045,0.235016,-0.137459,0.175784,-0.191262,-0.140570,0.350281,0.381611,-0.174161,0.114370,-0.109491,-0.047505,-0.473034,0.281032,0.371977,-0.142991,-0.023381,0.010204,-0.140722,-0.501566,0.304862,-0.440473,-0.381575,-0.035466,0.301909,-0.038478,-0.027239,0.050552,0.062550,-0.137995,-0.284263,-0.133441,0.017821,-0.108363,0.101631,-0.508608,0.139427,-0.254639,-0.121384,0.058555,0.037098,-0.181795,0.338725,-0.300497,0.131507,0.262146,0.524747,-0.632584,0.591562,0.054184,0.108636,-0.454025,-0.015847,0.268491,0.227182,0.333277,0.036382,-0.015925,0.297696,-0.242720,-0.224834,0.280236', '25908042', '1292584', '1316525', '21354767');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3612790', '鲁邦三世VS名侦探柯南', '动画', '君主制国家威斯帕尼亚王国因发现奇妙的矿石而引起世界关注，然而此时却发生悲惨事件，该国女王萨克拉•阿尔蒂亚和王子吉尔•加乌尔突发意外身亡。公主米拉•朱丽叶拒绝继承王位，与此同时国内也掀起反对米拉合要求取消君主制的狂潮。在这种纷乱的情况下，米拉和奇斯伯爵出访日本。在公主的欢迎宴会上，米兰险遭暗算，无法忍受这一切的她偷偷逃了出去，却在日本街头遭遇与自己长相一样的小兰，渴望正常人生活的米拉于是和小兰互换了身份。倍感蹊跷的柯南偷偷展开调查，而另一方面，大盗鲁邦三世潜入威斯帕尼亚企图偷窃该国世代相传的钻石王冠。事态变得混乱起来……本片为日本电视台开播55周年和读卖电视台开播50周年共同纪念作品。©豆瓣', '栗田贯一', '龟垣一', 7.5, 27841, 'tt1397219', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2200294397.jpg', 0.7, 3.9, 35.3, 41, 19.2, '0.283104,0.333715,-0.782529,0.454122,0.359473,-0.012662,0.775751,0.238588,-0.478818,-0.218854,0.409940,0.630425,-0.360881,-0.236239,0.432113,0.125667,-0.678825,-0.657801,0.098342,-0.006844,-0.096316,-0.290404,-0.268538,-0.305432,-0.305629,-0.567168,0.581576,0.146474,-0.147645,0.541632,0.459853,0.546797,-0.172841,0.531996,0.354277,0.035953,0.224285,0.027940,-0.427132,0.371885,-0.026525,0.117275,-0.260504,0.337852,0.160579,0.229164,0.301539,-0.386822,0.022321,-0.380300,0.455844,-0.358464,-0.045200,0.303004,0.488523,0.053567,0.141565,0.087403,-0.246794,-0.141611,0.188416,0.101129,-0.349478,0.336604,0.183961,0.450464,-0.352068,0.145093,-0.561023,-0.020062,0.158585,-0.221540,0.202969,0.786156,0.423743,0.111559,0.102411,0.051512,-0.501937,0.025147,0.611955,-0.025353,-0.403157,-0.197268,-0.232511,-0.290515,-0.156290,-0.162703,-0.296812,0.031698,0.362787,-0.204687,-0.092827,0.813921,-0.496166,-0.216940,-0.417740,-0.471797,0.233208,-0.375662,0.013245,-0.868688,-0.214690,-0.113419,-0.117114,-0.283467,0.295634,-0.270573,0.301324,-0.687856,0.186389,0.559672,0.404567,-0.258397,0.245490,0.092631,-0.096584,-0.114674,-0.379784,0.277651,0.133115,0.221149,-0.219032,0.098408,0.286923,-0.211238,-0.250197,0.456660', '1297715', '3871833', '1306723', '3804683');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3614963', '不明身份', '剧情', '马丁·哈里斯博士（连姆·尼森 Liam Neeson 饰）到柏林参加学术交流，却不幸遭遇了一场车祸，昏迷中醒来的他发现自己整个人生都被偷走了，妻子伊丽莎白（詹纽瑞·琼斯 January Jones 饰）不再认识他，而另一个人（艾丹·奎因 Aidan Quinn 饰）  取代了他的身份，成了哈里斯博士，光明正大出现在学术会议里，似乎所有人都认为那才是真正的哈里斯博士，令马丁十分迷惑。没有人相信马丁的说辞，柏林当地警署对他的申诉置若罔闻，又似乎有人开始追杀他。异国他乡，举目无亲，身陷险境，是人们的记忆被偷走了？还是自己脑袋出了问题？又或者背后有惊天阴谋？马丁走投无路之时，一个神秘女人吉娜（戴安·克鲁格 Diane Kruger 饰）出现了，似乎能帮他找到事情的真相……©豆瓣', '连姆·尼森', '佐米·希尔拉', 7.1, 52687, 'tt1401152', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p726152647.jpg', 0.4, 4.2, 45.4, 40.7, 9.3, '0.272133,0.153187,-0.871336,0.368947,-0.372646,-0.243312,0.881415,-0.081482,-0.649492,-0.395424,0.319096,0.824822,-0.300327,0.281792,0.253336,0.406232,-0.473541,-0.765554,0.152590,-0.262207,-0.232066,-0.466883,-0.358503,-0.242229,-0.045379,-0.126584,0.305122,0.107911,-0.125927,0.290477,0.195153,0.605226,0.252460,0.703722,-0.081557,0.410077,0.241323,-0.147191,0.016697,0.154360,0.114570,-0.422407,-0.230970,0.569629,-0.272293,0.424467,0.424016,-0.239181,-0.050020,0.033517,0.269771,-0.484898,0.008115,0.291527,0.157108,-0.149628,0.173654,0.182591,-0.129688,-0.099713,0.353092,0.264127,-0.528146,0.254682,-0.088828,0.455749,-0.459888,0.110439,-0.277811,0.059974,-0.043107,-0.255164,0.260156,0.041937,0.325883,0.187816,-0.134609,-0.111114,-0.698509,0.072736,0.654185,-0.218024,-0.304830,0.153276,-0.099054,-0.434288,0.212516,-0.185357,-0.208703,0.111715,0.428085,-0.011506,-0.167557,0.277439,-0.238842,-0.061024,-0.414248,-0.154821,-0.390786,-0.303085,-0.120064,-0.337951,-0.276984,-0.113029,-0.368336,-0.175411,-0.143192,-0.290801,0.395953,-0.790176,0.245865,0.597323,0.119000,-0.287395,0.405213,0.038631,-0.052299,-0.288539,-0.018942,0.103458,0.024041,0.271599,0.074723,0.211380,0.291581,-0.251662,-0.338407,0.482279', '1309080', '1308755', '25870679', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3621404', '机动部队—绝路', '剧情', '香港庙街，各路势力云集，犬牙交错。身体残疾、在黑帮老大烟铲乐手下讨生活的盲辉（曾国祥 饰）与大陆偷渡过来的女孩小惠相恋。PTU部队利用盲辉端掉黑社会团体和联胜的贩毒窝点，引发和联胜老大丧昆与烟铲乐的冲突。丧昆追杀盲辉之时，遭到乐之手下火爆的伏击，坠楼而死。鉴于恶性案件时有发生，警局展开大规模扑杀行动，庙街中由黑社会把持的店铺被迫关闭。烟铲乐恼羞成怒，迁怒盲辉，致使其与女友流落街头。李永森（任达华 饰）执勤途中逮捕了滋事的小惠，令盲辉对这个导致自己幸福破碎的沙展萌生恨意……©豆瓣', '任达华', '刘国昌', 6.5, 7072, 'tt1401663', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1630104184.jpg', 2.5, 12.4, 53, 23.7, 8.4, '0.245426,-0.019206,-0.645498,0.089205,0.207167,0.087030,0.573525,0.278615,-0.344570,0.228297,0.333002,0.568765,-0.031556,0.173180,0.276121,-0.360087,0.078104,-0.884938,-0.116094,-0.044602,-0.034346,-0.032875,-0.263631,-0.158558,-0.083837,-0.188457,0.317545,0.230496,-0.546584,0.727420,0.225096,0.573439,-0.566116,0.345504,-0.027229,-0.005984,0.029085,-0.136548,-0.364334,-0.105079,-0.194505,-0.392334,0.106025,0.045316,0.102941,0.365836,0.731703,-0.015376,-0.081499,-0.622508,0.104475,-0.524332,-0.229284,-0.025039,0.698109,0.060503,0.160644,0.161626,-0.183892,-0.025306,0.032161,0.200622,-0.575978,0.033437,0.193860,0.188938,-0.390679,0.182897,-0.087295,-0.004546,0.037181,-0.003626,0.305742,0.693511,0.376223,0.064657,-0.080443,0.168094,-0.591810,0.034055,0.623478,-0.327307,0.097390,-0.328428,0.055140,-0.112598,0.058464,-0.250288,-0.173977,-0.296905,0.238104,-0.395003,-0.131619,0.284632,-0.571084,-0.264014,-0.085372,0.198313,0.175694,-0.049488,-0.253147,-0.843497,-0.325051,-0.251899,-0.032038,0.285889,0.245106,0.230549,0.332380,-0.565788,-0.091275,0.507107,0.371586,-0.764036,0.152623,0.100311,0.018637,-0.176124,-0.146197,0.137546,0.436871,0.408031,0.157928,0.036930,-0.350284,-0.250156,-0.074079,-0.156639', '1298104', '1294227', '3387546', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3621418', '机动部队—人性', '剧情', '重案组肥棠（林雪 饰）嗜赌成性，欠下高利贷，终日被放债人陈耀雄（林家栋 饰）追讨。肥棠被逼无奈，竟打起警署内赃款的主意，他盗取赃款却仍填不上债务窟窿，只好藏进小旅馆躲避阿雄。PTU的沙展阿森（任达华 饰）得知肥棠私盗赃款，想方设法保护和帮助好友，却毕竟能力有限。偶然机会，肥棠和隔壁四个潮州同乡相识，更因其专业车手的经历和技术得到对方赏识。不曾想这四人竟是内地过来的悍匪，他们力邀肥棠入伙，为金钱和道义所惑的肥棠踟蹰不定。迷途的警察能否找到归来的路……©豆瓣', '任达华', '吴耀权', 6.3, 6736, 'tt1401664', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1630103561.jpg', 1.6, 12.6, 58.6, 21.3, 5.8, '-0.176170,-0.026378,-0.324514,0.323314,-0.134070,-0.448484,0.541878,-0.048049,-0.438476,-0.160668,0.102095,0.304108,0.258778,-0.150823,0.008866,-0.263456,-0.217405,-0.407559,0.132424,-0.088496,-0.126758,-0.319637,-0.457360,0.009855,-0.349388,0.069743,0.452594,0.185300,-0.054494,0.389272,0.402574,0.252739,-0.422916,0.300222,-0.042288,0.121498,0.026479,0.147946,-0.308545,-0.077476,-0.099599,-0.327559,-0.226100,-0.066111,0.285616,0.580118,0.379334,0.065990,-0.075152,-0.060691,0.024240,-0.290024,-0.005361,0.038675,0.058915,0.079053,0.529273,0.172642,-0.300084,0.004323,0.177688,-0.026800,-0.738002,0.106802,0.346476,-0.126300,-0.494823,0.113659,-0.255212,-0.036273,-0.187371,-0.205427,-0.106410,0.056280,0.128798,0.074569,-0.155979,-0.132227,-0.443868,0.213046,0.353097,-0.252956,0.171667,-0.018531,0.009536,-0.427758,0.173088,-0.147836,-0.160520,-0.112963,0.559999,-0.014980,-0.200532,-0.041381,-0.384342,-0.063460,-0.227866,0.316520,-0.068000,-0.305389,0.136845,-0.493549,-0.184329,-0.121416,-0.182201,0.222256,0.188503,-0.210877,0.202749,-0.357036,-0.261183,0.468826,0.395882,-0.698620,0.487849,0.037352,0.184084,-0.252809,-0.219104,-0.011159,0.449920,0.277192,0.147647,-0.171416,-0.091206,-0.222344,-0.208124,-0.032193', '1302110', '3670447', '26747274', '1293350');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3623024', '我的初恋情人', '剧情', '年仅8岁的垣野内逞（小林海人 饰）在医院结识种田医生（仲村亨 饰）的女儿茧（熊田圣亚 饰），初次相会便结下无法割舍的羁绊。逞被诊断患有心脏病，无法活过20岁。这一噩耗在两个孩子心间播下种子，他们相互约定，好好治疗，携手走入婚姻的殿堂。岁月流转，逞（冈田将生 饰）和茧（井上真央 饰）渐渐长大，他们就读同一所中学同一班级，二人相互依赖，情深意笃。爱情的力量甚至让原本在学业上有较大差距的两人考上同一所高中。但是童年时代由种田医生道出的谶言始终困扰着这对青年男女，他们能否携手跨过死神的阻拦呢……本片根据青木琴美同名畅销少女漫画改编。©豆瓣', '井上真央', '新城毅彦', 7.3, 77629, 'tt1401656', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2202987131.jpg', 0.7, 5, 38.2, 40.6, 15.4, '0.042677,-0.088711,-0.426857,0.301332,0.101163,-0.378495,0.572613,0.282292,-0.370828,-0.249918,0.108207,0.480894,-0.157922,0.440340,-0.015817,-0.405359,-0.134152,-0.620063,0.197937,-0.320553,-0.290117,-0.388622,-0.096210,0.141520,-0.198566,-0.233585,0.858291,-0.053884,0.074611,0.422566,-0.043197,0.226638,-0.352013,-0.155506,-0.346407,0.025314,0.031304,0.199079,-0.442703,-0.143223,-0.064962,-0.097322,-0.114564,-0.157184,-0.080383,0.159846,0.932627,-0.109916,0.013677,-0.106384,0.534910,0.032272,-0.251896,0.233222,0.011475,0.135979,0.188502,0.258249,-0.132834,0.088486,-0.230105,-0.224373,-0.290230,0.037592,0.155917,0.341195,-0.505133,0.532281,0.134892,-0.307500,0.115678,-0.015681,-0.310502,0.510495,0.342984,0.433184,-0.460124,-0.117660,-0.339731,0.182442,0.642103,-0.106949,-0.371562,0.316372,-0.447757,-0.388789,-0.216200,0.024908,-0.509650,-0.121820,0.135601,0.097191,-0.086227,0.242186,-0.151882,-0.146434,0.072838,0.320195,0.277799,-0.276527,0.010398,-0.525660,-0.260542,-0.362380,-0.533090,0.214174,0.399346,-0.218113,0.883193,-0.651121,-0.049876,0.331803,0.461389,-0.095626,0.725679,0.026870,0.230858,-0.409511,-0.118958,0.443131,-0.142568,0.235719,0.107354,0.515699,-0.019746,0.338501,-0.537213,0.154835', '3811356', '3667102', '5403927', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3626364', '快乐的大脚2', '喜剧', '将踢踏舞带回南极大陆的曼波，也将笑语欢歌带回了这片寒冷的土地。他每天和同伴们跳舞唱歌，帝企鹅家族沉浸在无尽的欢乐中。可是曼波的儿子艾利克（Ava Acres 配音）似乎完全不擅长歌舞，他在同伴面前出了丑，内心觉得分外沮丧，于是和两个好朋友离开了帝企鹅的地盘。他们跟随雷蒙来到了久违的Adeline，这里狂热的歌舞所包围。原来，一只会飞的企鹅萨文不久前来到此地，他历经千辛万苦，也见识了世界的沧桑巨变，Adeline的企鹅们全部视他为先知。在萨文的帮助下，艾利克决定和曼波回家。可是此时大地发生震动，温室效应变得愈加明显，冰川融化，积雪消融，南极大陆面临着一场巨大的变动……©豆瓣', '伊利亚·伍德', '乔治·米勒', 7.3, 29603, 'tt1402488', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1290384075.jpg', 0.7, 4.3, 38.9, 41.1, 15, '0.209364,0.163263,-1.020721,0.581668,0.001502,0.003467,0.790867,0.175160,-0.443320,-0.032487,0.073459,0.766544,-0.252878,0.366247,0.381938,0.062474,-0.259192,-0.675978,-0.271060,-0.164294,-0.194609,-0.127394,-0.369301,-0.129660,-0.138677,-0.547440,0.506882,0.307741,-0.046174,0.662991,0.075796,0.029498,-0.180187,0.643586,-0.277877,0.047168,-0.055611,0.128945,-0.270470,0.063947,-0.197635,0.039367,-0.208862,0.214985,0.001010,0.120605,0.673359,-0.332317,-0.149867,-0.101387,0.270365,-0.475365,0.132283,0.058954,0.343207,-0.017808,0.157422,0.176004,-0.166671,0.149158,-0.091242,-0.178598,-0.547219,0.244674,-0.031889,0.189167,-0.497396,0.434279,0.162047,-0.192597,-0.108592,-0.274505,0.571048,0.255657,0.170592,0.607167,-0.240021,0.057765,-0.442556,-0.011222,0.935373,-0.003563,-0.124899,0.203375,-0.229041,-0.217407,-0.164054,-0.037736,-0.414974,-0.202787,0.196455,0.230084,-0.246657,0.419368,-0.877830,-0.082807,-0.127616,-0.619222,-0.143563,-0.538444,-0.410951,-0.473699,-0.204151,-0.315015,-0.033907,-0.040088,0.016636,-0.177170,0.854795,-0.703476,0.370478,0.357889,0.327220,-0.061068,0.433872,-0.127786,0.088757,0.015887,-0.155248,0.307214,0.051491,0.435992,0.338209,0.384549,-0.213626,0.137318,-0.656016,0.523987', '34461680', '1458900', '5977789', '34429100');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3626365', '记住我', '剧情', '21岁的泰勒（罗伯特·帕丁森 Robert Pattinson 饰）十分的叛逆，与舍友挤在一幢狭小的公寓里，整日沉溺于书籍和尼古丁之中，脾气暴躁甚至因斗殴而被警察拘留。面对自己成功的企业家父亲查尔斯（皮尔斯·布鲁斯南 Pierce Brosnan 饰），泰勒充满了抵触，并且把哥哥的自杀和妹妹早熟的性格全部归咎于父亲对他们的疏忽。泰勒和艾丽（艾米莉·德瑞文 Emilie de Ravin 饰）的交往始于一场斗殴事件，泰勒因斗殴而被一名警察（克里斯·库珀 Chris Cooper 饰）拘留，几天后，泰勒的室友发现那名警察的女儿艾丽居然和他们在同一所学校。在室友的怂恿下，泰勒和艾丽开始了交往。面对生活中的种种不幸，泰勒选择了用对抗去保护自己，而与他有着类似不幸遭遇的艾丽却用乐观豁达的态度去享受生活……©豆瓣', '罗伯特·帕丁森', 'Allen Coulter', 7.3, 55397, 'tt1403981', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p502662220.jpg', 0.7, 4.9, 38.8, 41.1, 14.5, '0.660049,-0.352009,-0.673979,0.457507,-0.388391,-0.298940,1.036585,0.304412,-0.613885,-0.370594,0.178057,0.725062,-0.389092,0.312784,0.460878,-0.227960,-0.331222,-0.733207,-0.101296,-0.010180,-0.315842,-0.646163,-0.177704,-0.330320,-0.102319,-0.359970,0.620644,-0.254337,-0.214162,0.703049,0.241385,0.630094,-0.156763,0.506382,0.184517,-0.040622,0.043567,-0.072738,-0.212732,0.143729,0.261707,-0.187368,0.092070,0.111456,0.139716,0.515117,0.714716,-0.207290,0.012192,0.014741,0.254943,-0.123476,-0.168486,0.406317,0.313690,-0.164895,0.229299,0.171691,-0.179685,-0.064953,0.109974,-0.025373,-0.451180,-0.015537,-0.034876,0.098210,-0.579985,0.565681,-0.028175,0.005668,0.304088,-0.263390,-0.104205,0.361360,0.147558,0.573683,-0.076831,-0.106454,-0.372779,-0.150545,0.625465,-0.143644,-0.063504,0.245226,-0.379225,-0.230311,-0.053486,-0.238630,-0.969606,-0.005715,0.160216,-0.255391,-0.041607,0.351380,-0.577701,-0.217006,-0.238704,-0.006111,-0.008519,-0.367503,-0.109598,-0.678425,-0.099018,-0.618759,-0.495581,-0.190034,0.039977,-0.217716,0.631238,-1.042426,0.223872,0.434927,0.284567,-0.456969,0.565349,0.260760,0.383394,-0.056040,-0.249274,0.305898,0.373842,0.123201,0.203486,0.398811,-0.018771,0.014529,-0.273579,0.344352', '1308755', '2002744', '1296534', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3626372', '大地惊雷', '剧情', '因父亲被害，14岁的玛蒂·罗斯（海莉·斯坦菲尔德 Hailee Steinfeld 饰）抵达案发地史密斯堡，作为长女代表家人处理后事。杀死父亲的凶手汤姆·切尼已不知去向，在这枯燥又忙碌的西部小镇上，没人关心杀死异乡人的逃犯何时落网。玛蒂决定自己雇佣警察为父亲报仇，经人介绍，她选择与醉醺醺的警长罗斯特·考波恩（杰夫·布里吉斯 Jeff Bridges 饰）合作，同时，一名来自德克萨斯的骑警拉博夫（马特·达蒙 Matt Damon 饰）亦希望抓获汤姆·切尼，好在德州获得高额悬赏，为了让切尼在本地被正法，玛蒂必须在拉博夫之前抓到杀父仇人。成熟而坚强的玛蒂与罗斯特踏入了保留地，在那里有众多不法之徒，以及暂时逍遥法外的仇人……©豆瓣', '杰夫·布里吉斯', '乔尔·科恩', 8.3, 106282, 'tt1403865', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1046956087.jpg', 0.2, 0.8, 14.8, 50.9, 33.3, '0.051787,-0.099336,-0.497843,0.112136,-0.287522,-0.531175,0.554691,0.218062,-0.429613,-0.443865,0.292176,0.773087,0.337410,0.105017,0.360802,0.161668,-0.410767,-0.499227,0.145120,-0.365378,0.065194,-0.804431,-0.381530,-0.316245,0.049885,-0.516604,0.417725,-0.026226,0.150236,0.503221,0.247522,0.524259,0.001438,0.083447,-0.132448,-0.021973,0.386980,-0.260203,-0.494848,0.361500,-0.171254,0.198760,-0.104514,-0.110940,0.274351,0.612875,0.349579,-0.065104,0.011432,0.031007,0.122075,-0.459397,0.259624,0.297710,0.252456,-0.215362,0.180837,0.360190,-0.436051,-0.361688,0.096225,-0.005413,-0.729609,-0.035961,0.286168,0.319784,-0.557507,0.354597,-0.431239,-0.022458,0.242223,-0.312762,-0.077367,0.620553,-0.034135,0.275738,0.119317,-0.012782,-0.520577,0.040637,0.618250,-0.143261,0.041723,-0.400847,0.050983,-0.186789,0.310039,-0.356157,-0.286207,-0.119660,0.569375,-0.097465,-0.051664,0.355545,-0.218652,-0.321311,-0.518088,-0.012943,-0.016667,-0.315155,-0.164186,-0.597524,0.029058,-0.075618,-0.220537,-0.210821,0.090185,-0.300196,0.456850,-0.635731,0.554285,0.425182,0.394465,-0.358645,0.327320,0.242737,0.268198,-0.277054,-0.213299,0.383017,0.612773,0.319759,0.085232,-0.142810,0.026773,-0.259017,-0.388179,0.269421', '20277632', '3006783', '1309069', '1293145');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3626416', '十月围城', '剧情', '1905年，香港中环。革命志士惨遭暗杀。知悉孙中山（张涵予 饰）即将抵港，清廷遂派遣将军阎孝国（胡军 饰）前来剿杀。他收买赌徒沈重阳(甄子丹 饰)作密探。适逢商人李玉堂(王学圻 饰)之子李重光(王柏杰饰)考学庆典，沈重阳见前妻月茹(范冰冰 饰)与幼女已成他人家眷，黯然离去。为护孙，《中国日报》社长陈少白（梁家辉 饰）邀戏班班主（任达华饰）出手，令其惨遭灭门，其女方红(李宇春 饰)侥幸生还。陈少白被擒，与阎孝国相见，师生决裂。独子游行好友被擒等变故，使李玉堂投身革命，引得探长史密夫(曾志伟 饰)查封报馆。其间，李玉堂帮车夫阿四(谢霆锋 饰)与恋人阿纯（周韵 饰）订婚。月茹夜会沈重阳，要他弃暗投明。打女方红、小贩王复明(巴特尔 饰)、乞丐刘郁白(黎明 饰)等人也先后加入护孙行列。一场惊心动魄的全城追杀由此展开……本片投资1.5亿人民币，史上首度以 1：1的比例，在上海重铸了1905年的香港中环。', '甄子丹', '陈德森', 7.7, 305989, 'tt1403130', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1697172942.jpg', 0.7, 3.2, 28.2, 47.3, 20.6, '-0.277015,0.153203,-0.256035,0.065867,0.307538,-0.236801,0.325319,0.258749,-0.347763,-0.135023,0.283936,0.340246,-0.347708,0.217214,0.277216,-0.179088,-0.058427,-0.499729,-0.025605,0.044668,0.037477,-0.053700,0.007233,-0.193116,-0.311501,0.142585,0.358437,0.193032,-0.077859,0.678120,0.610225,0.242611,-0.152549,0.264500,0.132088,0.212043,-0.043006,0.078012,-0.595690,-0.014920,-0.286872,-0.518033,-0.325943,-0.379445,-0.066306,0.454286,0.492185,-0.088009,0.205351,-0.398858,0.116023,-0.191268,-0.019627,0.208587,0.331188,0.155594,0.065215,0.102138,-0.207395,-0.091328,0.123153,0.043218,0.012119,0.235744,0.452992,-0.019942,-0.319552,0.125265,-0.348077,0.350586,-0.159603,-0.129667,-0.006946,0.297791,0.075602,-0.184837,0.251656,0.034206,-0.291781,0.826607,0.457549,-0.099926,0.266186,-0.303279,0.126083,-0.441788,0.159430,-0.152372,-0.146856,0.209166,0.508023,-0.419898,0.471863,0.183343,-0.366738,-0.562877,-0.412551,0.280279,-0.075416,0.077782,0.188139,-0.671749,-0.093736,-0.239242,-0.070567,0.076222,0.508244,-0.022549,0.239232,-0.305783,-0.016616,-0.193115,0.223234,-0.674777,0.333944,-0.026757,0.050267,-0.254983,0.033913,0.063604,0.168290,0.129594,0.225280,-0.021015,-0.180023,-0.077990,0.189521,-0.126061', '10