INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3628370', '阿黛拉的非凡冒险', '喜剧', '1912年。为了拯救深陷重度昏迷的妹妹，聪明果敢的法国女记者阿黛拉·干白（露易丝·布尔昆 Louise Bourgoin 饰）上天入地，走遍世界寻找治病良药。她不顾出版商去秘鲁印加古果探险的要求，自顾自来到埃及寻找传说中法老名医的木乃伊。经过一番险象环生的对决，阿黛拉总算得到木乃伊，启程返乡。与此同时，位于巴黎的自然博物馆发生奇怪之事。一枚恐龙蛋突然孵化出一只翼手龙，当晚，翼手龙袭击了前警察局长的专车，该事件惊动全国上下，政府要求警方24小时内破案。即将复活的木乃伊，以及危险的翼手龙，阿黛拉即将迎来新的冒险……本片根据雅克·塔蒂（Jacques Tardi）同名畅销漫画改编。©豆瓣', '露易丝·布尔昆', '吕克·贝松', 6.9, 72809, 'tt1179025', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p574618287.jpg', 1.3, 8.3, 46.4, 34.4, 9.6, '-0.067308,0.013661,-0.499664,0.078229,0.466708,-0.091139,0.341044,-0.405951,-0.232267,-0.370101,0.293939,0.507231,-0.208202,-0.069371,0.488230,-0.000257,-0.514852,-0.465864,-0.097443,-0.096029,-0.284635,-0.259350,-0.308081,-0.245818,0.252388,-0.248602,0.361793,0.135969,0.033170,0.435811,0.179599,0.416093,-0.452711,0.224055,-0.039287,-0.085120,0.342468,0.114225,-0.314422,0.378559,0.055956,0.044718,0.050008,-0.157865,0.060868,0.212463,0.493153,-0.533995,-0.031410,-0.247709,0.546109,-0.140219,-0.029436,-0.199460,0.348229,0.135215,0.135055,-0.042082,-0.168439,0.074891,0.011327,-0.343350,-0.307646,0.055275,0.120805,0.373460,-0.186375,-0.024679,-0.022675,0.367208,0.129354,-0.367662,0.346277,0.484346,0.332909,0.371539,0.185124,0.299183,-0.231695,0.247245,0.606156,-0.067007,-0.130668,-0.011816,0.032644,-0.512810,0.302295,-0.187521,-0.027036,0.062907,0.332462,0.043020,-0.078908,0.179638,-0.459517,-0.357055,-0.341480,-0.338796,0.150789,0.190960,-0.078660,-0.584149,0.155264,0.263134,0.161070,-0.045264,0.269007,-0.244281,0.415139,-0.369276,0.322273,0.332912,0.123621,-0.411404,0.376649,-0.341438,0.191638,-0.356265,-0.106248,0.539479,0.192887,0.483734,-0.169058,-0.010420,0.140604,-0.389198,-0.478875,0.036140', '3871833', '2159244', '35287558', '6007281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3628407', '机动部队—伙伴', '剧情', '曾混迹黑社会的印度裔男子维路出狱后，一心过回正常人生活，可惜人在江湖，身不由己。他最疼爱的弟弟跟随当年好友混入黑道；曾经的老大黑摩利据说也返回香港，图谋杀害机动部队陈督察；警官肥棠（林雪 饰）则隔三差五找到维路了解线索。维路不胜其扰，却又无可奈何。另一方面，香港油尖旺鱼龙混杂，各方势力暗流涌动。森（任达华 饰）和May（邵美琪 饰）所率领的机动部队一面要平息黑道势力的争斗，同时还要四处追查黑摩利雇用的刀手。最终形势将朝何方发展？©豆瓣', '任达华', '刘国昌', 6.1, 5826, 'tt1403854', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1630102684.jpg', 2.5, 16.3, 59.4, 17.2, 4.6, '-0.192522,-0.180388,-0.402243,0.521826,0.296885,-0.090108,0.206927,0.337204,-0.598790,-0.527542,0.101908,0.297769,0.320399,-0.088149,0.137550,-0.181495,-0.414990,-0.642849,-0.051350,-0.177288,0.092853,-0.201672,-0.447667,-0.133645,0.060077,-0.040517,0.654930,0.389575,-0.146843,0.449533,0.308875,0.565159,-0.448748,0.187924,-0.118737,-0.205883,0.118481,0.094375,-0.522832,-0.093607,-0.054885,-0.327828,-0.060665,-0.142048,0.373319,0.440974,0.424230,0.038860,0.130551,-0.271276,-0.004478,-0.213896,-0.126846,-0.016025,0.613006,0.028581,0.107468,0.211926,0.065293,-0.159634,-0.264062,0.036027,-0.515097,0.055952,0.520182,0.150097,-0.445337,-0.098384,-0.199750,-0.029391,-0.202604,-0.167266,0.284518,0.635258,-0.060240,-0.080766,0.095595,0.384628,-0.313318,0.034563,0.771660,-0.006540,0.205988,-0.224743,0.068505,-0.255722,-0.072041,-0.283618,-0.081540,-0.292244,0.155918,-0.444550,0.014519,0.459945,-0.494446,0.026960,-0.107018,0.127064,0.133231,-0.050953,0.236862,-0.536098,-0.141979,-0.240592,0.192238,0.086637,-0.074455,0.055070,0.692155,-0.441916,-0.120022,0.503575,0.422155,-0.878942,0.341580,0.000299,0.108813,-0.526871,0.003196,0.442913,0.418925,0.232644,-0.088960,-0.194392,-0.294385,-0.671261,-0.035941,-0.200214', '1482541', '1484760', '3412882', '1299250');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3629232', '带我去远方', '剧情', '故事发生在海边宁静的小渔村里。女孩阿桂（李芸妘饰幼年，游昕饰成年）从小眼中的世界，就跟其他人不同——她是个色盲。虽然这注定了她与周遭现实的格格不入，但却没有让她失去对生活的希望，她拿着爸爸送的多色眼镜，发现了不同颜色的天空。跟她一样对生命充满向往的还有她最崇拜的堂哥阿贤 （林柏宏饰）。阿贤 告诉她，在遥远的南太平洋有一座色盲岛，岛民都是跟阿桂一样不能分辨颜色的人。美丽的故事安慰了阿桂，让她觉得自己并不孤单一人，也因此对阿贤哥产生了朦胧的爱恋。阿贤的秘密是他沉浸在同性的爱情世界里。他们都在守护彼此的秘密，一起计划离开生活的小渔村，奔赴不会被人当做异类的自由天堂。©豆瓣', '林柏宏', '傅天余', 7.5, 25640, 'tt1976614', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p672737349.jpg', 0.4, 3.4, 35, 44.6, 16.6, '0.387081,-0.040696,-0.994246,0.778297,-0.462359,0.098237,1.230583,0.043423,-0.541234,-0.008374,0.066666,0.964283,0.059232,0.292980,-0.067409,0.179926,-0.402555,-0.633684,-0.036858,-0.303071,-0.264106,-0.539957,-0.203939,-0.132695,-0.117136,-0.318450,0.746371,0.140196,-0.319706,0.281193,0.039986,-0.145866,-0.054973,0.711060,-0.526837,0.026794,-0.276713,0.427005,-0.165881,-0.088705,-0.009345,0.136798,-0.160951,0.368582,0.008372,0.202604,0.834734,-0.441542,-0.342106,0.050223,0.028151,-0.314869,-0.055207,0.081665,-0.007278,-0.150979,0.078712,0.062580,-0.047442,-0.186803,0.062087,0.063625,-0.705686,0.168875,0.319388,0.405614,-0.461367,0.720863,0.124851,-0.312825,0.235020,-0.228807,0.437900,0.015139,0.347580,0.578125,-0.083381,-0.021278,-0.669405,0.188201,0.884674,0.012780,-0.388835,0.573412,-0.819461,-0.386348,-0.225000,-0.002071,-0.719768,0.031896,0.067491,0.004216,-0.571976,0.388691,-0.622987,0.312051,0.275704,-0.312322,-0.030716,-0.837695,-0.052495,-0.106684,-0.266083,-0.867106,-0.450875,0.178253,0.172495,-0.235189,0.847509,-0.953316,0.420269,0.520584,0.494948,-0.609812,1.117687,0.325362,-0.142542,-0.464000,0.058790,0.423846,-0.092000,0.221692,0.124813,0.314383,0.002222,0.179613,-0.701817,0.734675', '3055049', '24756472', '4275444', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3631187', '离婚不分手', '剧情', '在朋友们的眼中，西勒斯特（拉什达·琼斯 Rashida Jones 饰）和杰西（安迪·萨姆伯格 Andy Samberg 饰）是天设地造的一对。两人的爱情从高中一直延续至今，热烈、持久、充满了激情。可是，随着时间的流逝，在这两个人的眼中，对方的身影已经不再如当初那样美好，杰西的玩世不恭和不思进取让西勒斯特无法忍受，而西勒斯特的高高在上和咄咄逼人也时常让杰西觉得很受伤。在两人的面前，似乎只剩下离婚一条道路。虽不能结为夫妻，可两人之间深厚的感情依然存在，因此两人定下了分手不分居，做不了夫妻做朋友的约定，在同一屋檐下展开了各自新的感情生活。可现实没有想象的那么美好，逐渐的，西勒斯特发现自己依然深爱着杰西，并且这爱意竟愈演愈烈。更让她感到痛苦的是，曾经自以为无比了解的杰西变得越来越陌生起来。©豆瓣', '拉什达·琼斯', '李·托兰·克里格', 7, 6432, 'tt1405365', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1599209190.jpg', 1.2, 5.9, 44.4, 36.6, 11.8, '0.513346,-0.348869,-0.793557,0.610578,0.435411,-0.480994,1.061972,0.259722,-0.604530,-0.233511,-0.137066,0.654493,-0.371268,0.113283,0.386650,-0.159865,-0.451196,-0.645584,-0.166639,-0.267570,-0.054779,-0.731882,-0.213082,0.089591,-0.372404,-0.250002,0.774409,-0.015629,0.034282,0.711243,0.335924,0.014092,0.118026,0.416625,-0.206186,-0.197033,0.055911,0.272744,-0.504068,-0.088762,0.305012,0.280467,-0.267901,0.364413,-0.132842,0.234167,0.398089,-0.311299,-0.257021,0.077363,0.255881,-0.024144,0.051829,0.237222,-0.095693,-0.273935,0.432253,0.284131,-0.112646,-0.160602,0.179306,0.111945,-0.761707,0.264037,-0.066511,0.404669,-0.597957,0.495948,-0.017320,-0.241115,0.361710,-0.339171,0.203610,0.544203,0.147342,0.444520,-0.189464,-0.303241,-0.599014,-0.211226,0.806110,0.328081,-0.536122,0.598851,-0.429802,-0.244874,-0.167189,-0.113617,-0.556459,-0.237140,0.015761,0.203721,0.028239,0.702173,-0.622720,0.142460,-0.122821,-0.063805,0.101501,-0.590595,0.040616,-0.474594,-0.478805,-0.841160,-0.508946,0.184431,-0.233447,-0.388477,0.570874,-1.154317,0.191687,0.203424,0.463853,-0.082538,0.535720,0.606076,0.046561,-0.338884,-0.218344,0.361975,0.299941,0.041925,0.356549,0.334439,0.089654,0.314448,-0.409256,0.751421', '1308755', '4275444', '35030151', '20277433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3632506', '台北飘雪', '剧情', '来自青岛的女歌手May（童瑶 饰）因不幸失声突然从唱片公司和媒体视线中消失，出走的May在陌生的菁桐小镇遇见了奔忙的青年小莫（陈柏霖 饰），小莫为人仗义，将烂醉的May搀扶到旅店，又为其找到了暂居之所，May在小莫朋友的店中找到了一份临时差事，虽然偶尔有人偶尔认出她或是骚扰，但这份工作缓解了May对制作人阿雷（杨佑宁 饰）的思念。另一方面，阿雷对May失踪的关注很快被忙碌的工作所吞没。小报记者杰克接受上峰任务，一路追查May的下落，并渐渐接近了避世中的May。小莫与May的情愫在滋长，但是他发现，这次旅行所包含的意义令May难以触及……©豆瓣', '陈柏霖', '霍建起', 5.6, 10885, 'tt1538399', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1493285285.jpg', 7.5, 27.9, 47.9, 12.8, 3.9, '0.360817,0.030975,-0.717206,0.506581,-0.093421,-0.030043,0.692542,0.159987,-0.634854,-0.191129,0.087385,0.812308,-0.312293,0.349682,0.412904,-0.133686,-0.093407,-0.587051,-0.012961,-0.276582,-0.293903,-0.372315,-0.199330,-0.277251,-0.277076,-0.291398,0.619559,0.505239,-0.300577,0.659137,0.121446,0.284588,-0.353621,0.867468,-0.012082,-0.115251,0.083551,0.107380,-0.020045,0.183284,0.177701,-0.564780,-0.061116,0.210720,0.045554,0.605823,0.825694,-0.195933,-0.301937,0.170477,0.290875,-0.317446,0.243149,-0.034535,0.160492,0.202738,0.045473,0.080020,-0.580977,0.048384,-0.165098,0.066190,-0.602897,-0.014453,0.325884,0.109886,-0.606564,0.534673,-0.121393,-0.136346,-0.008223,-0.257318,0.321885,0.263840,0.125957,0.378839,-0.043587,0.067346,-0.391884,0.162448,0.470456,-0.117821,-0.072545,0.506965,-0.204934,-0.513352,0.122872,-0.001122,-0.251758,-0.095162,0.319263,0.394738,-0.190187,0.142078,-0.638969,-0.086197,-0.168139,-0.282397,-0.020757,-0.526353,-0.335542,-0.683437,-0.133371,-0.110165,-0.043868,0.062554,0.121425,-0.193075,0.644139,-0.943919,0.215617,0.682439,0.238857,-0.526562,0.766569,-0.169328,0.206256,-0.170477,-0.258139,0.267004,0.249416,0.463601,0.157241,0.108028,-0.191998,-0.405802,-0.535942,0.274493', '1309194', '3326747', '1304687', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3632509', '泪王子', '剧情', '1954年的台湾正处于戒严时期，教美术的仇老师写生闯入禁区被几名军人带走，小周便再也没有看见过他。小女孩小周和姐姐小立还有妈妈金皖平（朱璇 饰），以及当空军的爸爸孙汉生（张孝全 饰）住在清泉一村，他们过着童话般快乐的日子。经常来他们家做客的丁叔叔（范植伟 饰）脸上有块很大的伤疤，还曾经把妹妹小周吓哭。妈妈有一次去参加学校的活动时遇到同学刘霞君的妈妈欧阳千君（关颖 饰），两个人好像认识。有一天，爸爸妈妈突然被宪兵抓走，爸爸被指控匪谍罪，妈妈被指为思想左倾，爸爸的手风琴被宪兵给扯烂了，家也被封了，小立和小周一下子无依无靠，还好有丁叔叔托人照顾他们。小立听人说爸爸是被丁叔叔诬告，因为丁叔叔想娶妈妈，小周则发现丁叔叔每天都在写报告。不久刘霞君家好像也受到牵连，爸爸刘将军（曾江 饰）被送到军事法庭，妈妈欧阳自杀了，而刘霞君被送到了台北妇朕总会。后来事情果然像人们说的那样子，妈妈被释放了，而且和丁叔叔结了婚……本片入围2009年第66届威尼斯电影节主竞赛单元。', '范植伟', '杨凡', 6.4, 6087, 'tt1498834', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p700311473.jpg', 3.2, 14.4, 50, 25.6, 6.7, '0.074381,-0.482330,-0.353477,0.210071,-0.293542,-0.499019,0.456542,0.170724,-0.664861,-0.352845,-0.328735,0.474098,-0.249490,0.660107,0.212129,0.034028,0.027450,-0.536608,-0.035737,0.014794,-0.299341,-0.328646,0.428031,0.023367,0.139901,-0.172484,0.000077,-0.369705,-0.083569,0.490523,0.225043,0.037220,-0.134253,0.439344,-0.114976,0.406908,0.067399,0.155885,-0.214874,0.092690,0.255357,-0.119615,0.080021,-0.325674,0.381978,0.131066,0.398394,0.036262,-0.005688,0.012518,0.166351,-0.298975,0.145904,0.263123,0.342951,0.049938,0.312730,0.102397,-0.213587,-0.028645,0.103590,-0.328901,-0.017964,0.093501,0.264356,-0.085527,-0.527921,0.446837,-0.130801,0.166634,0.275943,-0.231709,0.596990,0.262721,0.027258,0.487132,-0.198304,0.074114,-0.578134,0.208697,0.549704,-0.223344,0.206117,-0.182054,0.233084,-0.209030,0.259111,-0.040104,-0.330978,0.664705,0.267449,-0.468816,-0.339445,0.074551,-0.383691,-0.384965,0.007194,-0.040654,-0.014989,-0.385234,-0.080141,-0.166312,0.272881,-0.251083,-0.049515,0.262452,-0.071859,-0.159546,0.716414,-0.703777,0.448700,-0.002486,0.592083,-0.492001,0.614956,0.125322,-0.085158,-0.179672,0.264800,-0.051936,0.342313,0.459160,0.669996,0.305506,-0.062759,-0.258179,-0.084222,0.093502', '1306544', '1292219', '1427834', '1469441');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3637220', '皱纹', '剧情', '最近，埃米利奥（Charo Díaz 塔乔·冈萨雷兹 配音）总是丢三落四的，惹出了一堆的麻烦，因此，他的家人将埃米利奥送进了养老院。埃米利奥对于养老院感到非常的恐惧，对于他来说，这里更像是一座监狱。幸运的是，埃米利奥在养老院里结识了米基尔（阿尔瓦罗·格瓦拉 Álvaro Guevara 配音）和安东尼奥两位新朋友，在养老院枯燥的日子里，三人之间很加快就结下了深厚的友谊。米基尔和安东尼奥发现，埃米利奥逐渐显示出了阿兹海默症的早期症状，为了不让他被送进仿佛集中营一般的养老院最上层，三个老人决定执行他们疯狂的计划。©豆瓣', 'Tacho González', '伊格纳希奥·法雷拉斯', 8.7, 14439, 'tt1407052', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1393072931.jpg', 0.1, 0.4, 9.5, 46.6, 43.4, '0.787943,-0.207666,-0.509210,0.443177,-0.125818,-0.507334,1.014874,0.339501,-0.829456,-0.240877,-0.175197,0.666594,-0.194774,0.201986,0.402695,-0.084976,-0.552329,-0.453584,-0.152878,-0.445697,-0.081175,-0.640924,-0.410082,-0.143140,-0.268348,-0.420320,-0.039989,-0.184016,0.013804,0.556776,0.159840,0.381741,0.101716,0.411353,-0.063848,0.012736,0.292808,-0.149651,-0.105309,0.146637,0.249870,0.228242,0.065179,0.044447,0.279992,0.408584,0.424341,-0.084243,-0.059070,-0.100714,0.210996,-0.161847,0.018947,0.123539,0.206434,0.092127,0.297283,0.114698,-0.300849,0.105212,0.139910,-0.335876,-0.684046,0.211399,0.131425,0.184765,-0.587019,0.363517,-0.130161,-0.171668,0.281897,-0.471683,0.145227,0.324316,0.309583,0.565921,-0.469351,-0.322349,-0.620185,-0.077765,0.764454,-0.123439,-0.196394,0.096947,-0.449550,-0.294056,0.082914,0.085219,-0.347393,-0.188889,0.404593,-0.175328,-0.095107,0.641694,-0.541007,-0.105218,-0.358330,-0.417494,-0.177791,-0.428856,0.066821,-0.817916,-0.037699,-0.306458,-0.270350,-0.056397,-0.034671,-0.263327,0.607680,-0.643864,0.539386,0.472669,0.246083,-0.000733,0.612767,-0.091075,0.462249,0.076022,0.053634,0.180968,0.037154,0.422766,0.263282,0.620416,-0.057793,-0.335881,-0.289101,0.649148', '1301686', '1853181', '1309172', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3641108', '兔子洞', '剧情', '霍维（艾伦·艾克哈特 Aaron Eckhart 饰）和贝卡（妮可·基德曼 Nicole Kidman 饰）原本过着悠哉快活的中产阶级生活，夫妻恩爱，儿子丹尼乖巧伶俐，但是一场车祸夺去丹尼的性命，也彻底摧毁霍维夫妇的生活。贝卡从此将自己禁锢在家中，虽然试图通过各种方法消解心中的悲痛，然而她久久无法将儿子的身影从记忆中抹去；霍维试图装作一切从未发生，结果反与妻子的关系日益紧张，争吵不断。贝卡偶然遇见那个导致儿子死亡的高中男孩，她开始有意识地去接近他。烦躁孤独的霍维，则似乎正寻找一个心灵的港湾……本片根据大卫·林赛-阿贝尔（David Lindsay-Abaire）的百老汇同名戏剧改编。©豆瓣', '妮可·基德曼', '约翰·卡梅隆·米切尔', 7.3, 37474, 'tt0935075', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1762809157.jpg', 0.4, 3.2, 39.5, 45, 11.9, '0.250674,0.198999,-0.659466,0.587485,-0.084024,-0.496106,0.842302,0.076148,-0.524672,-0.232977,0.135395,0.589501,0.038422,0.341652,0.221438,0.008445,-0.463906,-0.695351,0.066481,0.199541,-0.044671,-0.486057,-0.372843,-0.144664,-0.084191,-0.359135,0.610778,-0.175727,0.008614,0.506389,0.066610,0.391392,-0.417637,0.499467,-0.072759,0.236363,0.127896,-0.065843,-0.459091,-0.039713,0.186349,-0.234742,-0.199811,0.246654,0.008818,0.339717,0.787548,-0.402466,-0.086922,-0.019198,0.317484,-0.103413,0.013701,0.317628,-0.023171,0.152025,0.169388,0.058407,-0.265993,0.060158,0.189114,-0.009890,-0.614130,0.149251,0.038159,0.182752,-0.311617,0.292960,-0.051744,-0.110490,0.196648,-0.395127,0.221076,0.329897,0.386787,0.386275,-0.552810,0.105642,-0.227528,0.107128,0.634165,-0.090829,-0.256913,0.507613,-0.240528,-0.114242,-0.052703,-0.151466,-0.552444,-0.065917,0.409892,0.331173,-0.287978,0.644128,-0.421834,0.001907,-0.392545,-0.112201,-0.017344,-0.298679,0.023717,-0.525805,-0.290606,-0.273439,-0.299707,-0.316355,-0.197025,-0.301808,0.346096,-0.503169,0.301263,0.469370,0.158973,-0.145062,0.230380,0.121009,0.330103,-0.168810,-0.123386,0.774399,0.007427,0.181038,0.086125,0.242660,-0.057434,0.310637,-0.326221,0.720294', '1292528', '1305666', '2365260', '3097044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3642835', '黑衣人3', '喜剧', '月球最高监狱，穷凶极恶的伯格罗多星人鲍里斯（杰梅奈·克莱门特 Jemaine Clement 饰）越狱逃亡。他在1969年犯下邪恶罪行，最终被年轻的K（乔什·布洛林 Josh Brolin 饰） 砍掉一只手臂，送入监狱。此次他逃脱的目的，就是穿越时空杀死K。与此同时，J （威尔·史密斯 Will Smith 饰）和K（汤米·李·琼斯 Tommy Lee Jones 饰）一如既往处理各种外星人引起的混乱，因对鲍里斯的案件三缄其口，两个好搭档心生隔阂。崭新的一天，J发现K消失不见，周围更几乎没人知道K这个人。此时的K已在40年前被鲍里斯杀死，他所建立的A网也不复存在。在这危急时刻，伯格罗多星人大举入侵地球。为了保护家园，J必须穿越时空再次改变历史……©豆瓣', '威尔·史密斯', '巴里·索南菲尔德', 7.7, 275986, 'tt1409024', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1731774258.jpg', 0.3, 2.3, 29.2, 49.1, 19.1, '-0.046034,0.037768,-0.790690,0.180729,-0.090694,0.011577,0.898859,-0.018931,-0.306522,-0.478573,0.269555,0.506388,-0.213724,-0.025695,0.262887,-0.181494,-0.416461,-0.548957,-0.023297,-0.274580,-0.495451,-0.249570,-0.575139,-0.479728,0.035344,-0.352080,0.739083,0.286661,-0.260519,0.317719,0.175418,0.481757,0.131085,0.344075,-0.084266,0.045384,-0.039307,-0.198080,-0.192301,-0.077394,-0.272985,-0.220479,-0.139067,0.221980,-0.267517,0.436284,0.533838,-0.369787,-0.072210,-0.209216,0.320722,-0.594776,-0.103277,-0.045976,0.370883,-0.222073,-0.209673,0.236029,-0.345791,-0.180972,0.310226,-0.123391,-0.705056,-0.030022,-0.001585,0.148963,-0.348954,0.106167,-0.237997,0.243289,-0.090797,-0.316891,0.146277,0.391126,0.227154,0.288937,-0.049006,0.012477,-0.635900,0.055566,0.638788,-0.223770,-0.286749,-0.139218,-0.088620,-0.285896,-0.090485,-0.309398,-0.203338,-0.017016,0.525898,-0.022148,-0.155223,0.480601,-0.321707,-0.272901,-0.255521,-0.234831,0.011957,-0.437519,-0.264486,-0.526609,-0.385698,0.009748,-0.243070,0.246168,-0.200461,-0.161417,0.480449,-0.611685,0.396831,0.447505,0.175621,-0.511791,0.497433,0.020099,0.265902,-0.250423,-0.091026,0.509583,0.525073,0.288536,0.136511,0.133608,0.040929,-0.090539,-0.336580,0.458906', '25828589', '26588308', '1428054', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3642843', '星际迷航2：暗黑无界', '动作', '在尼比鲁星球探查期间，企业号舰长柯克（克里斯·派恩Chris Pine 饰）为营救史波克（扎克瑞·昆图 Zachary Quinto 饰）采取了胆大妄为的举动，几乎危及全舰队员的生命，他也为此付出代价。不久，柯克官复原职，而伦敦发生一起死亡超过四十人的恐怖袭击事件。该事件的始作俑者约翰·哈里森（本尼迪克特·康伯巴奇 Benedict Cumberbatch 饰）正来自联盟内部。此后他驾驶飞机袭击了高层会议，柯克最为敬重的派克将军不幸遇难。为了阻止哈里森的外逃阴谋，柯克重新率领企业号启程追击。危机重重的旅途，他和舰员、朋友之间的信任也受到巨大考验。当他们最终找到哈里森，才终于知晓他的真实身份，以及伦敦袭击事件背后的阴谋和黑幕……©豆瓣', '克里斯·派恩', 'J·J·艾布拉姆斯', 8, 208652, 'tt1408101', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1907669506.jpg', 0.4, 1.8, 21.1, 50.3, 26.4, '-0.015840,-0.077340,-0.722644,0.382337,0.367232,-0.030166,0.442781,0.131508,-0.332366,-0.442696,0.449586,0.559374,-0.037775,-0.109912,0.627281,-0.133478,-0.516747,-0.515070,-0.069259,-0.228792,-0.468550,-0.762633,-0.155833,-0.564716,0.250546,-0.390907,0.634381,0.207957,-0.161249,0.460285,0.471795,0.551704,-0.044207,0.607296,0.272000,-0.114168,0.334894,-0.116540,-0.523136,-0.009927,-0.230837,-0.174121,-0.049351,0.402810,0.119224,0.437201,0.524627,-0.442852,0.011398,-0.372234,0.038132,-0.459735,0.294900,-0.281058,0.655859,-0.040054,-0.001579,0.615632,-0.056569,-0.010944,-0.029110,0.021533,-0.492229,-0.031916,0.070066,0.062327,-0.291857,0.014212,-0.241295,0.221995,0.126906,0.024256,0.111653,0.624678,0.274927,-0.106916,-0.064049,-0.013895,-0.443220,-0.215274,0.659793,-0.206173,-0.165168,-0.049509,-0.180897,-0.352939,-0.059675,-0.483241,-0.212649,0.116060,0.187253,0.066050,0.047396,0.574058,-0.322271,-0.200146,-0.581913,-0.311289,-0.119473,-0.373510,0.146833,-0.957315,-0.017461,-0.054379,-0.084397,0.013978,-0.135243,-0.003892,0.405142,-0.499476,0.178982,0.611287,0.266353,-0.670362,0.480375,0.165830,0.236773,-0.551276,-0.100211,0.332961,0.283577,0.147741,-0.195973,-0.134486,0.195021,-0.235309,-0.111706,0.105124', '3871833', '1293572', '1293537', '2973528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3642866', '维多利亚一号', '剧情', '某银行话务员邓丽嫦（何超仪 饰）自幼生长在一个平民家庭，她始终有一个情结，那就是努力赚钱买一套可以看得见大海的房子。为了这个目标，阿嫦努力工作，下班后还干着两份兼职，甚至和同事利用职务之便聚敛外快。眼看就要存够豪华大厦维多利亚一号的首付，但是偏偏赶上楼市疯涨的时候，签合 同当天房主反悔，宁可赔付违约金也不愿按原价出售。为了房子而不懈努力的阿嫦遭受巨大打击，在万圣节前夜，这个几近崩溃的女子带着一身杀意走进了维多利亚一号……©豆瓣', '何超仪', '彭浩翔', 7.3, 63383, 'tt1407972', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p499375003.jpg', 1.1, 4.8, 36.8, 44.2, 13.1, '-0.044882,0.115746,-0.649775,0.299298,-0.324993,-0.320237,0.575490,0.613739,0.160017,-0.298698,0.246905,0.650757,0.109367,0.328193,0.279049,0.028886,-0.032057,-0.210555,-0.064601,-0.057111,0.020872,-0.375188,-0.018835,-0.110889,-0.026460,-0.019169,0.396676,0.184909,-0.024538,0.319222,0.491785,-0.069216,0.088257,0.287549,-0.236998,-0.419449,0.112809,0.086624,-0.099269,0.386092,-0.008587,-0.180530,0.242357,-0.128416,0.120635,0.390243,0.558772,0.167997,-0.123417,0.152960,0.317753,-0.044740,-0.088164,0.125984,0.114387,-0.037875,0.272362,0.015245,-0.550336,0.021997,0.195470,-0.309481,-0.731319,-0.264731,0.020016,-0.083640,-0.608483,0.422180,-0.031992,0.117506,-0.062286,-0.371108,-0.042456,0.350462,0.017434,0.529935,-0.177445,0.043594,-0.717660,0.310880,0.410809,-0.233196,0.035075,0.475360,-0.170051,-0.164593,0.229925,-0.114922,-0.458240,-0.159098,0.167103,0.050860,-0.119641,-0.280360,-0.665349,0.210900,-0.179185,-0.377388,0.139769,-0.295126,-0.247095,-0.515307,-0.048179,-0.152776,-0.035618,0.354135,0.369639,-0.130044,0.385859,-0.448660,0.107322,0.541966,0.658004,-0.689151,0.616537,-0.145357,0.243293,0.025390,0.022165,-0.144898,-0.024442,0.527145,0.004399,0.038116,0.038695,-0.224991,-0.187956,0.525510', '1299932', '2133293', '3215099', '4300640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3642895', '佐州自救兄弟', '喜剧', '影片主角为一个吊儿郎当的警察，他企图破坏他妹妹和一个精神病医生的婚约，想尽办法让妹妹的未婚夫出丑。', '艾斯·库珀', '蒂姆·斯托瑞', 6.3, 5221, 'tt1408253', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2151430664.jpg', 2.3, 14.2, 57.8, 19.5, 6.2, '0.093496,-0.158594,-0.043786,1.218795,-0.765514,-0.482121,1.235813,0.193202,-0.498520,-0.378690,0.409964,1.004879,-0.125875,0.459125,0.313211,0.192272,0.025020,-0.720171,0.047364,0.549506,-0.286588,-0.251897,-0.304408,-0.331623,-0.084107,-0.228619,0.625656,-0.456328,-0.078474,0.216397,0.445725,-0.110952,-0.166181,0.113233,0.079262,-0.067296,0.162283,-0.449422,-0.351002,0.488462,0.246331,-0.207266,0.306928,0.551130,-0.665313,0.471959,0.932304,0.081984,-0.201538,-0.432353,0.706411,-0.488403,0.090364,0.378951,-0.100485,-0.462942,0.486952,-0.054350,-0.194488,-0.555767,0.091365,0.031141,-0.727048,-0.008488,0.127915,-0.069007,-0.558277,0.796903,-0.220617,0.319946,0.105268,-0.021410,0.345322,0.284155,0.165592,0.422410,-0.916752,0.039319,-0.631087,0.141081,0.474516,0.065274,0.446510,0.464615,-0.128913,-0.012249,0.185184,-0.348833,-1.284026,0.356985,0.168475,-1.025558,-0.454507,0.081785,-0.438480,-0.471741,-0.609260,0.503882,-0.431592,-0.814140,0.401842,0.148417,0.132869,0.319233,0.093399,-0.039297,0.114639,-0.308865,0.802212,-0.534660,-0.035639,0.898662,0.467569,-1.308150,0.771763,0.675053,-0.041045,-0.714859,-0.325709,-0.392529,0.395153,0.121605,-0.078659,0.580885,0.504314,-0.182115,-0.393355,0.310907', '30201003', '26856202', '25885827', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3645150', '开罗时间', '剧情', '朱丽叶·格兰特（派翠西娅·克拉克森 Patricia Clarkson 饰）从加拿大飞到埃及开罗与聚少离多的丈夫马克（汤姆·迈克卡玛斯 Tom McCamus 饰）共同度假，却没曾想刚下飞机就被告知因为加沙地带新爆发的武装冲突，负责联合国难民营管理工作的丈夫暂时不能离开。马克托前安全官，埃及人塔列克（亚历山大·希迪格 Alexander Siddig 饰）照顾朱丽叶。朱丽叶在使馆晚会上结识了跟她处境相似的年轻女子凯瑟琳（埃琳纳·安娜亚 Elena Anaya 饰），二人结伴游览白沙漠，凯瑟琳向她描述了自己与一个埃及人的旧日爱情。之后，塔列克带朱丽叶畅游开罗的绝美风光，朱丽叶发现在与塔列克不断的接触中自己竟对他渐生情愫。微妙的感情令朱丽叶无比忧伤 ……本片获加拿大多伦多国际电影节最佳本土电影奖。©豆瓣', '派翠西娅·克拉克森', '鲁巴·纳达', 7.9, 18195, 'tt0896529', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1505408000.jpg', 0.3, 2, 23.6, 49.5, 24.5, '0.199950,0.049784,-0.851050,0.663803,0.365663,-0.360902,0.692531,0.063073,-0.386221,-0.002643,0.370308,1.141172,-0.420931,0.175718,0.186426,0.318228,-0.819479,-0.715629,-0.044355,-0.089237,-0.286858,-0.359360,-0.146650,-0.066673,-0.221402,-0.314055,0.438010,0.015513,-0.077304,0.542635,0.009953,0.370477,-0.257086,0.360037,-0.100906,-0.041475,0.286794,-0.012249,-0.470916,0.178920,0.130275,-0.015408,-0.391470,0.158110,0.373675,0.478321,0.702208,-0.148158,0.225703,-0.055273,0.110912,-0.040570,0.300374,0.075169,0.020118,-0.172452,-0.036483,0.039262,-0.314984,-0.137774,0.062032,-0.199009,-0.211796,0.347013,0.069961,0.126690,-0.461441,0.396091,-0.182742,-0.093763,0.417491,-0.085673,0.083981,0.409565,0.164912,0.171307,0.291242,0.116880,-0.338478,0.182573,0.596945,-0.064612,-0.343738,0.301899,-0.329024,-0.393343,-0.169789,0.102120,-0.353334,-0.129899,0.502011,-0.393073,0.063142,0.377062,-0.702828,-0.157868,-0.393198,-0.068945,-0.089022,-0.219128,0.088490,-0.784362,-0.165977,-0.581197,-0.305948,-0.068605,0.137971,0.151855,0.293017,-0.638270,0.351671,0.538891,0.315131,-0.274774,0.603678,0.122809,-0.161884,-0.374235,-0.098402,0.702759,-0.058428,0.129372,0.138950,0.368651,0.038190,-0.010035,-0.430335,0.554284', '4319218', '34461680', '1303333', '1297239'