INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3647523', '金钱帝国', '犯罪', '六十年代，香港警察受贿成风，赌档粉档与中间人、警方组成的利益链大肆吸金，十年内警方受贿数额达当时的百亿港币之巨。九龙城区便衣火麒麟（黄秋生 饰）为破案不择手段，上峰施压，火麒麟如常去街上拉人顶罪，大学生韩志邦（方力申 饰）遭其陷害毒打，韩母托老警员找到警方与帮会的中间人猪油仔（王晶 饰）出面搭救得脱。人称乐哥的徐乐功（梁家辉 饰）时任华人总探，为人狂妄，出手大方。陈细九（陈奕迅 饰）心地善良尤擅察言观色，深得乐哥赏识，短短五年之内由普通便衣晋升至筲箕湾区探长，但代价之一是家中为掩人耳目收留了各位大哥的九名情妇……1974年，香港的贪污恶风震动国际，廉政公署成立，长官严国梁（林保怡 饰）聘用大学生韩志邦、失意警员火麒麟等组成第一批廉政专员队伍，严厉打击香港的地下规则。陈细九因贪污案发人财两空之际，却意外的发现了此生真爱……©豆瓣', '梁家辉', '王晶', 6.6, 53603, 'tt1409831', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486533228.jpg', 2, 10.8, 51.6, 28.2, 7.4, '-0.286659,-0.019133,-0.284439,0.131732,-0.198869,-0.056522,0.175848,0.315950,-0.455839,-0.227085,0.303567,0.302083,0.021299,-0.082261,0.303280,-0.140599,-0.013875,-0.483418,-0.083112,-0.232932,0.090316,-0.233842,-0.248003,-0.208916,-0.285918,-0.112011,0.239419,0.161884,-0.023508,0.431603,0.443455,0.279121,-0.166635,0.041453,0.066535,-0.222650,0.258708,-0.170843,-0.308718,-0.037999,-0.433077,-0.276631,0.126546,-0.190973,0.091352,0.493148,0.329550,0.074114,0.001789,-0.443409,0.395529,-0.269435,0.026180,-0.271871,0.478998,0.200870,0.475486,0.342800,-0.291167,-0.079409,0.043085,-0.162804,-0.448575,-0.049714,0.153798,0.039965,-0.335024,0.119166,-0.322573,0.164717,-0.162474,-0.027773,-0.103851,0.183347,-0.028565,0.117255,0.151992,0.254043,-0.412044,0.448103,0.462732,-0.077023,0.061664,-0.261273,0.105534,-0.490005,0.205422,-0.339426,0.058873,-0.057263,0.120906,-0.308906,0.303806,-0.132732,-0.387697,-0.223685,-0.357002,0.221447,-0.043199,-0.063541,-0.067697,-0.482736,-0.087332,-0.085543,0.018790,-0.015761,0.361512,-0.140310,0.269377,-0.224550,-0.019734,0.475728,0.343181,-0.561092,0.632479,-0.030491,0.090070,-0.240578,-0.249939,-0.266110,0.359040,0.334603,0.077604,-0.175813,-0.112205,-0.506398,0.192951,-0.418021', '30159567', '1307200', '4100696'