INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3649049', '金陵十三钗', '剧情', '1937年，日军入侵南京，战火中，六朝古都化为废墟，众多中国军民被困城中。一支十数人的国军德械教导队余部在长官李教官（佟大为 饰）指挥下，从日军手中救出了一批教会学校女学生，而李教官等人，至此丧失了出城的机会。幸免于难的书娟（张歆怡 饰）等学生返回文彻斯特教堂，随她们一 起来到的，还有受雇远道至此收敛神父遗体的美国人约翰·米勒（克里斯蒂安·贝尔 Christian Bale 饰）。此时的南京城中，逃难的人们蜂拥进安全区和教堂寻找庇护，十四名风尘女子强行进入教堂避难，其中精通英语的玉墨（倪妮 饰）希望借助约翰的身份为一行人提供更多保护。教堂的墙壁，并不能阻挡日军的铁蹄，教堂内的人们，将面临孰生孰死的选择……©豆瓣', '克里斯蒂安·贝尔', '张艺谋', 8.3, 656593, 'tt1410063', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1322247572.jpg', 0.7, 1.7, 15.6, 46.1, 35.8, '0.248955,-0.012337,-0.681813,0.445769,-0.014655,-0.125868,0.748620,0.101822,-0.375467,-0.157492,0.385957,0.431700,0.107976,0.080845,0.271656,-0.291350,-0.498470,-0.556445,-0.234944,-0.329487,-0.450792,-0.140364,-0.145444,-0.409279,-0.236158,-0.411477,0.566217,0.554132,0.053128,0.418119,0.004748,0.259516,-0.140920,0.344778,0.107175,0.111461,0.087743,-0.307819,-0.152944,0.234096,-0.333695,-0.345219,-0.402764,0.015511,-0.004864,0.151961,0.852899,-0.176759,0.350269,-0.315531,-0.120317,-0.268846,0.063340,0.091731,0.414303,-0.151848,0.099753,0.105299,-0.042081,0.108291,-0.184016,0.062269,-0.284608,0.036781,0.258038,0.150668,-0.632693,0.100241,-0.124584,0.106996,0.048665,-0.414758,0.152109,0.218016,0.021443,0.223961,-0.160238,-0.085843,-0.685556,0.228839,0.514100,-0.275117,-0.098405,-0.591799,-0.115164,-0.487935,0.112046,0.091875,-0.361914,-0.198430,0.255231,-0.202060,0.357347,0.001011,-0.520314,-0.074063,-0.420760,-0.408114,-0.051758,-0.264654,-0.046483,-0.901872,0.197808,-0.000181,0.099563,0.224580,0.233890,0.279323,0.791135,-0.452645,0.208303,0.278716,0.470269,-0.401197,0.515800,-0.177366,0.355236,0.074408,-0.040900,0.252539,0.274227,0.626172,0.118182,0.331421,-0.279660,-0.265629,-0.286743,0.194258', '1307897', '2159244', '1294917', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3652297', '星际传奇3', '动作', '孔武有力的瑞迪克（范·迪塞尔 Vin Diesel 饰）终于坐上组织的宝座，强兵悍将拜倒阶下，与此同时又有更多野心家蠢蠢欲动，时刻准备取代他的位置。直到某天，瑞迪克被亲信哄骗离开舰队，启程返回阔别已久的家乡，谁知竟被带到一颗充满凶险的蛮荒星球，进而更遭到随从的背叛和追杀 。侥幸逃得一命的瑞迪克满身伤痕，而这颗行星上到处都是凶猛的野兽和可怕的异形。为了求生，他只有将自己化身为杀气十足的杀神，以驯服这群时时刻刻想要吃掉他的异界生物。当然，更大的挑战和危险远远不止这些，迪瑞克依然活着的消息传遍全宇宙，由此引来一波又一波的赏金猎人试图割下他的脑袋。生死之战，在陌生的星球展开……©豆瓣', '范·迪塞尔', '大卫·杜西', 6.5, 26221, 'tt1411250', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2022462385.jpg', 2.4, 12.2, 51.5, 24.8, 9.1, '0.024731,0.195920,-0.855750,0.441947,0.105448,-0.008197,0.726316,-0.073363,-0.215149,0.121232,0.133488,0.709367,-0.058937,0.017949,0.206278,-0.123286,-0.119933,-0.475519,-0.140531,-0.177183,-0.410785,-0.193490,-0.449334,-0.153299,0.215722,-0.451541,0.793199,0.324604,-0.218865,0.335337,0.317617,0.533806,-0.001215,0.656563,-0.424639,-0.046561,-0.124782,-0.255139,-0.020303,0.214357,0.000396,-0.240049,-0.165416,0.344362,-0.241846,0.153320,0.618997,-0.531575,0.029166,-0.325240,0.119653,-0.617929,0.091843,-0.056042,0.336091,-0.133872,-0.051317,0.126796,0.078063,0.044414,0.164521,-0.025099,-0.954621,-0.050249,0.027103,0.054382,-0.510316,0.142386,0.013717,0.224485,-0.017051,-0.092764,0.325377,0.334478,-0.183671,0.113451,-0.115857,0.054858,-0.462707,-0.266560,0.793910,-0.036758,-0.235126,-0.201869,0.013899,-0.361196,0.091242,-0.581344,-0.385707,-0.178218,0.544196,0.231490,-0.083630,0.231593,-0.595505,0.091341,-0.509413,-0.191798,0.012823,-0.269973,-0.398694,-0.462392,-0.093708,-0.085799,-0.134568,0.284289,0.165806,-0.121741,0.702597,-0.510050,0.314811,0.445814,0.431140,-0.434722,0.329107,-0.231891,-0.084272,-0.080086,-0.264766,0.365456,0.453466,0.346841,0.244878,0.003194,-0.377914,0.036105,-0.315579,0.627505', '26667010', '25828589', '30163500', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3652302', '爱情无线牵', '喜剧', '在亚当（阿什顿•库奇 Ashton Kutcher 饰）的成长经历中，艾玛（娜塔丽•波特曼 Natalie Portman 饰）总是时不时的出现，所以两个人可以算是朋友。一次，亚当探望自己明星父亲时发现，父亲居然和自己的前女友同居了，这让亚当无论如何也不能接受，在遭遇情感的重创之后，亚当决定要随便找一个女性朋友上床发泻抑郁。宿醉的亚当醒来之后，发现自己居然裸着身体在艾玛家里，在达成“只谈性不谈爱”的协议之后，两人便开始时不时的幽会。随着时间的推移，亚当发现自己似乎对身边这个特立独行的女孩动了心，但是艾玛却表示不能接受亚当的爱意，所以他们最终决定结束这种关系。但是，分手之后二人才发现，他们早已习惯了彼此……©豆瓣', '娜塔莉·波特曼', '伊万·雷特曼', 6.6, 92095, 'tt1411238', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p791084395.jpg', 1, 8.6, 55.1, 28.3, 7, '0.443625,0.175021,-0.879628,0.445274,-0.129004,-0.585182,0.577677,0.001942,-0.728620,-0.457273,0.053204,0.729784,-0.461696,0.525365,0.217527,-0.014502,-0.517303,-0.990453,0.247368,-0.183943,-0.443500,-0.519395,-0.120914,-0.132551,-0.279164,-0.175668,0.674834,0.002644,-0.069078,0.475259,0.343683,-0.095936,0.201256,0.778823,0.015320,0.029461,0.261191,0.126095,-0.448547,0.241086,0.420916,-0.006873,-0.052171,0.310592,-0.008651,0.300168,0.527788,-0.390471,-0.424011,-0.028903,0.362873,-0.164356,-0.083385,0.222201,0.212219,0.016081,0.563864,0.020828,-0.136962,-0.124152,-0.082618,0.344089,-0.418406,0.340913,-0.185175,0.123238,-0.552602,0.242363,-0.036598,0.004480,-0.002577,-0.394558,0.102881,0.593068,0.453620,0.323428,-0.500541,0.022588,-0.279909,-0.247111,0.794396,0.028073,-0.243386,0.630627,-0.156795,-0.371228,-0.013606,-0.070616,-0.220852,0.037507,-0.053674,0.365630,-0.425698,0.189892,-0.556974,-0.282779,-0.285006,-0.060560,0.076418,-0.494813,0.038881,-0.553512,-0.425065,-0.410293,-0.438405,0.232793,-0.014427,-0.333268,0.486856,-0.979447,0.409393,0.495211,0.387929,-0.598597,0.635224,0.248082,0.052442,-0.350936,0.211816,0.300542,-0.082640,-0.114904,0.353539,0.219941,0.163956,0.092513,-0.458350,0.402087', '1301022', '30345227', '1302109', '2027925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3654340', '宿醉2', '喜剧', '《宿醉2》由原班人马打造，延续上集的搞笑风格。上集中经历了情感纠葛的Stu （艾德赫尔·姆斯 Ed Helms 饰）这集中新婚，众好友Phil（布莱德利·库珀 Bradley Cooper 饰）、Alan（扎克·加利费安纳基斯 Zach Galifianakis 饰）和 Doug（贾斯汀·巴萨 Justin Bartha饰）前去泰国参加他的婚礼。不料宿醉事件又发生了，一帮兄弟醒来后发现身在曼谷，并且新娘的弟弟（李淳 饰）神秘失踪，亚洲黑帮“周先生”（肯·郑 Ken Jeong 饰）突然出现，于是一场疯狂冒险在异国又卷土重来！值得一提的是李安的儿子李淳在片中饰演了新娘的弟弟，一名成绩优秀的高材生。©豆瓣', '布莱德利·库珀', '托德·菲利普斯', 6.9, 111607, 'tt1411697', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1016132295.jpg', 1.1, 7.8, 48.5, 32.3, 10.2, '0.062037,-0.115514,-0.655242,0.484316,0.231327,-0.253979,0.705587,0.168652,-0.360193,-0.421574,0.267694,0.620546,-0.284839,0.319247,0.508521,-0.020940,-0.387800,-0.806997,0.017056,0.072088,-0.122015,-0.309605,-0.195825,-0.250083,0.236354,-0.234631,0.353331,-0.129290,-0.096374,0.744526,0.730204,0.426834,-0.182061,0.263259,0.234670,0.238419,0.210002,0.148266,-0.180413,0.090071,-0.098317,-0.248579,-0.099185,-0.015939,0.320709,0.307875,0.632227,-0.105418,0.221043,-0.174869,0.410374,-0.147412,-0.041504,0.184902,0.422818,0.126082,0.014588,0.013916,0.013205,-0.088633,0.129777,-0.201114,-0.164300,0.258980,0.112368,0.168307,-0.608971,0.401409,-0.186263,-0.090223,-0.078860,-0.299811,0.218015,0.496309,0.279224,0.151580,0.226045,-0.030850,-0.118231,0.428343,0.583224,-0.165335,-0.053098,0.134234,0.048147,-0.494183,-0.017419,-0.175382,-0.370278,0.143802,0.423469,-0.198746,0.162518,0.414167,-0.606210,-0.275973,-0.092655,-0.098969,0.052238,-0.002565,0.117580,-0.844930,-0.227877,-0.357184,-0.209392,0.006350,-0.066984,-0.151113,0.409085,-0.600520,0.077513,0.368525,-0.029007,-0.407720,0.433722,0.075708,0.292342,-0.077998,-0.078699,0.283451,0.132650,0.021869,0.058052,0.370541,-0.179888,-0.049241,-0.276964,0.252259', '1292050', '25723905', '25833539', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3654346', '拯救小兔', '喜剧', '在过去的四千多年里，复活节岛上的兔子都辛勤劳动为世界各地的孩子们带去糖果和欢乐。然而今年却出了点状况，即将接任父亲成为下一任复活节兔子的伊比（拉塞尔·布兰德 Russell Brand 配音）似乎对这个职业毫无热情，一心想成为一名乐队鼓手，周游世界。远在千里之外的加州，已过弱冠之年的弗雷德（詹姆斯·麦斯登 James Marsden 饰）也遇到了同样的烦恼，一直不肯找工作的他终于在今年被父母建议搬出去住。得益于姐姐的暗中帮忙，弗雷德将前往她老板的一幢别墅暂住，然而此时兔子伊比也为了梦想来到加州街头，不巧竟被弗雷德的车撞了个正着，惊吓之余弗雷德也只好答应收留伊比让他养伤。在豪华别墅中，弗雷德开始和兔子伊比一起生活，磕磕碰碰中也不乏温情笑料，然而两人都没有料到，彼此的命运竟也不知不觉地交织在了一起……©豆瓣', '詹姆斯·麦斯登', '蒂姆·希尔', 6.6, 11136, 'tt1411704', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2284788107.jpg', 1.6, 9.6, 53.7, 26.8, 8.4, '0.427020,0.035794,-0.957282,0.548407,-0.122919,-0.455020,0.664518,0.085495,-0.276317,-0.241480,0.042973,0.816867,-0.368446,0.533356,0.300965,-0.033556,-0.299116,-0.600284,-0.154961,-0.128062,-0.259418,-0.358318,-0.075833,0.019624,-0.209547,0.060296,0.334310,0.106277,0.353637,0.741182,0.263978,0.231126,-0.112130,0.476474,-0.348662,0.073474,0.317967,0.030510,0.049541,0.198643,0.093581,-0.296271,-0.252001,-0.000966,0.285618,0.262725,0.607153,-0.242919,-0.047872,0.081019,0.094329,-0.045446,0.200919,0.242365,0.413132,-0.018745,0.222589,0.014380,-0.256291,0.261592,0.157699,-0.143775,-0.533348,0.271449,-0.010520,-0.050383,-0.640289,0.471162,0.007828,-0.230126,0.106194,-0.533282,0.270819,0.279075,0.121909,0.555682,-0.312035,0.256876,-0.664223,-0.163502,0.728750,-0.098345,0.026152,0.138163,-0.159865,-0.306949,0.010680,-0.053787,-0.518964,-0.261450,0.335202,0.035669,-0.191355,0.218347,-0.605238,0.170861,-0.265169,-0.294211,-0.039511,-0.365829,-0.091195,-0.609544,0.210811,-0.218309,-0.286720,0.202111,0.239087,-0.316545,0.606331,-0.701147,0.405332,0.439068,0.262630,-0.231450,0.729123,-0.001733,0.408272,0.049170,0.001264,0.119153,0.123945,0.372597,0.442315,0.502427,-0.055781,-0.155030,-0.498569,0.612061', '3055049', '26687241', '1296538', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3660428', '金色梦乡', '剧情', '居住在仙台的宅急送工作人员青柳雅春（堺雅人 饰）是一个情感细腻、善良温和的青年。2年前，他曾因救助被歹徒威胁的当红女明星凛香（貫地谷しほり 饰）而成为当地家喻户晓的英雄人物。某天，他接到大学好友森田森吾（吉岡秀隆 饰）一同钓鱼的邀请，于是欣然前往。但是令青柳出乎意料的是，森田似乎把自己骗入一个陷阱之中。是日，正在故乡仙台视察的金田首相（伊藤ふみお 饰）遭到炸弹袭击身亡，而青柳则成为了头号嫌疑人。警察总署综合情报科迅速部署天罗地网，而知晓内幕的神秘势力也急于杀害青柳以灭口。在好友和陌生人的帮助下，青柳被迫在小小的仙台展开绝命逃亡，“对他人的信任”是他所拥有的唯一武器……本片根据伊坂幸太郎的同名原著改编。©豆瓣', '堺雅人', '中村义洋', 8.3, 75170, 'tt1413529', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2208009845.jpg', 0.5, 1.8, 15.8, 43.9, 38.1, '0.225664,-0.018047,-0.530647,0.538819,-0.017708,0.247556,0.450100,0.208280,-0.645289,-0.274298,0.472817,0.692898,0.084528,0.163031,0.337973,-0.016601,-0.076910,-0.602706,-0.146508,-0.305716,-0.220243,-0.548842,-0.431122,-0.125855,-0.081796,-0.364535,0.772304,0.219676,-0.246080,0.409462,0.276065,0.615756,-0.311608,0.357699,-0.157626,0.014487,0.176751,-0.139161,-0.310262,0.414858,-0.420466,-0.363148,-0.071440,0.203152,-0.208279,0.523432,0.576606,-0.206300,-0.255276,-0.120674,0.473769,-0.392382,0.011311,0.164899,0.564405,0.051736,-0.000919,0.289135,-0.363071,0.151701,0.208214,-0.117010,-0.820841,-0.149655,0.271793,0.256022,-0.443981,0.346109,-0.225767,-0.023124,0.123612,-0.174694,0.232442,0.279781,0.268788,0.109605,-0.162453,0.106757,-0.265705,0.249958,0.611346,0.115686,-0.094387,0.032611,-0.091652,-0.372746,-0.008203,-0.339281,-0.157092,0.073631,0.220214,-0.003154,0.036969,0.078639,-0.450148,-0.205089,-0.249444,0.105792,0.136118,-0.324233,-0.184634,-0.762611,-0.156422,-0.175037,-0.206845,-0.038189,0.255286,-0.100308,0.928673,-0.876193,0.133326,0.722754,0.175189,-0.536213,0.593950,0.099078,-0.186379,-0.189759,-0.018746,0.131411,0.504460,0.318224,-0.064380,0.193977,-0.150010,-0.384323,-0.254773,-0.046033', '27602116', '2369613', '3811356', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3660508', '海瑟', '剧情', 'T.J（戴文·波切Devin Brochu 饰）是个刚刚因车祸失去母亲的13岁男孩，因为父亲承受不了打击开始整天嗑药，他只好和祖母生活在一起。就在T.J最低落的时候，一个古怪的家伙闯进祖母的老房子，他长发油腻，满身纹身，疯疯癫癫，仇恨社会，自称名叫海瑟（约瑟夫·高登-莱维特 Joseph Gordon-Levitt 饰），就此赖下不走。附近的杂货店员妮可（娜塔丽·波曼 Natalie Portman 饰）时常关心T.J，令他对她产生暧昧感情，同时妮可和海瑟的关系也在发展。一个普通女孩，两个各自带着内心伤痛的“大”“小”男人，他们的人生都在被彼此改变。©豆瓣', '约瑟夫·高登-莱维特', '斯邦瑟·舒瑟', 7.2, 11556, 'tt1403177', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p922961851.jpg', 1, 6.3, 38.8, 39.5, 14.4, '0.349450,-0.039384,-0.699995,0.505077,-0.483276,-0.127773,0.993758,0.287740,-0.519431,-0.172660,0.385012,0.789713,-0.114007,0.441894,-0.084208,0.014365,-0.201269,-0.508158,0.008290,-0.031692,-0.432429,-0.470649,-0.079501,-0.304181,-0.345800,-0.297347,0.346661,-0.253273,-0.156375,0.319872,0.396870,0.226961,-0.064827,0.404788,-0.249119,0.103774,0.151943,-0.032492,0.129178,-0.015541,0.301276,-0.206428,0.066259,0.112613,-0.037045,0.285817,0.754178,-0.290566,-0.149065,-0.075493,0.110207,0.027546,-0.121970,0.163165,0.169622,-0.257007,0.193639,0.022013,-0.219544,-0.094851,0.150033,0.088025,-0.358045,0.170868,0.033377,0.338733,-0.677417,0.685347,-0.124972,-0.265409,0.239900,-0.343440,0.096299,0.164096,0.099957,0.532677,-0.229507,0.087015,-0.477666,0.085014,0.567854,0.125504,-0.166381,0.336679,-0.634141,-0.110147,-0.197911,-0.099177,-0.634809,-0.074654,0.135825,-0.109324,-0.273531,0.342764,-0.485397,0.104981,-0.078348,-0.029724,0.035485,-0.375527,-0.113097,-0.311092,-0.262151,-0.619171,-0.427202,0.162675,0.123008,-0.055432,0.709849,-0.677418,0.328277,0.399242,0.304855,-0.399843,0.595895,0.092609,0.074672,-0.324484,-0.158980,0.443404,-0.057823,-0.083490,0.364995,0.469481,-0.088876,0.325145,-0.105151,0.562413', '21619567', '3111650', '25723780', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3660583', '怎么又是你', '喜剧', '所有美国高校里都有一个美丽的啦啦队队长，当然也会有一个其貌不扬受人排挤的丑小鸭，玛妮（克里斯汀·贝尔饰）是丑小鸭故事里的励志小鸭，长大后除去眼镜摘掉牙箍终于成为了公关公司受人追捧的魅力主管。而噩梦是回老家参加哥哥威尔（詹姆斯·沃克饰）的婚礼，未来大嫂就是那位曾经带头欺负她的啦啦队队长头乔安娜（奥黛塔·雅丝曼饰）。回到家后，所有家人都围绕在美丽的乔安娜身边，玛妮不堪回首的回忆又涌上心头。故事总有不可思议的巧合，玛妮的妈妈盖尔（杰米·李·柯蒂斯饰）中学时期的死对头竟然是乔安娜的姑姑拉蒙纳（西格妮·韦弗饰）。误解、报复、争吵、妒忌、重归于好……男人永远无法理解的女人间的斗争在这两代人当中开战。©豆瓣', '克里斯汀·贝尔', '安迪·菲克曼', 6.4, 10144, 'tt1414382', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p489438365.jpg', 1.6, 10.7, 57.8, 25.3, 4.6, '0.200522,-0.228249,-0.461965,0.458023,-0.162359,-0.351190,0.799676,0.067379,-0.386631,-0.187790,0.216482,0.662972,-0.225138,0.638961,0.393665,0.202786,-0.358966,-0.734285,-0.065446,-0.162725,-0.175250,-0.451303,-0.223591,-0.266012,0.099890,-0.156848,0.356162,-0.142782,-0.291758,0.373416,0.529975,0.226221,0.059136,0.302102,0.142851,0.165268,0.329591,0.046050,-0.038179,-0.141537,-0.013351,0.057352,0.063068,0.148035,0.205678,0.029842,0.394262,-0.277077,0.321222,-0.267298,0.381243,-0.300490,0.039017,0.054362,0.257813,-0.149572,0.348802,-0.002466,-0.080928,-0.227331,0.149454,-0.087862,-0.475780,0.199562,0.270997,0.261831,-0.557966,0.262172,0.172349,-0.017013,0.401535,-0.000937,0.110723,0.121632,0.282588,0.478398,0.114626,0.227484,-0.261572,0.146991,0.638534,0.023352,-0.327684,-0.028976,-0.366731,-0.143712,0.134360,-0.090914,-0.628813,0.025519,0.064823,-0.288748,0.126366,0.551535,-0.311519,-0.133303,-0.057617,0.138890,0.132199,-0.495830,-0.057689,-0.539724,-0.248695,-0.490390,-0.198647,-0.026565,0.058002,-0.293127,0.730173,-0.713271,0.235882,0.364617,0.163150,-0.299527,0.627842,0.192609,0.129788,-0.194312,-0.005504,0.489022,-0.069280,-0.029859,-0.137579,0.309592,0.046035,-0.101059,-0.233557,0.502193', '30162520', '1307146', '1292720', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3667102', '乐与路', '剧情', '井上芽衣子（宮崎あおい 饰）、种田成男（高良健吾 饰）、加藤贤一（近藤洋一 饰）、小谷爱（伊藤歩 饰）、比利（桐谷健太 饰），这五个人是大学时期在轻音社结识的伙伴。除了留级王加藤外，其他四人毕业后皆走入职场。他们终日奔波，却仍坚持抽空聚在一起享受音乐的快乐。厌倦了职场的枯燥，芽衣子和恋人种田相继辞职，种田全身心投入音乐的创作，无奈在汹涌的商业大潮下，他们的音乐乏人问津。短暂的沉沦过后，种田决定积极面对生活，而残酷的命运终止了他的脚步。爱人和挚友的离开，让这群青春男女承受着莫大的悲痛。芽衣子最终选择拿起吉他，歌唱爱人用心谱写的旋律……本片根据漫画家浅野いにお的原著改编。©豆瓣', '宫崎葵', '三木孝浩', 7.5, 16085, 'tt1415228', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p596454928.jpg', 0.4, 3.5, 35, 43.9, 17.2, '-0.117266,-0.066688,-0.368975,0.358518,0.042139,-0.260635,0.433496,0.304839,-0.109189,-0.367820,0.018329,0.494751,0.023643,0.626546,0.207445,-0.157713,-0.380541,-0.697524,-0.063563,0.188607,0.119810,-0.046053,0.164984,-0.205183,-0.266829,-0.101637,1.029671,0.153509,-0.118260,0.735850,0.207987,0.115061,-0.082651,0.078680,0.008010,0.188825,0.214436,0.159313,-0.340408,-0.120632,-0.134709,-0.128281,-0.284311,-0.121440,0.178896,0.051838,0.944871,-0.133061,0.047828,0.059161,0.504386,-0.326713,-0.213773,0.075293,-0.060884,0.139940,0.140983,0.143102,-0.225517,0.111681,-0.069619,-0.084940,-0.599889,-0.106357,0.116520,0.233111,-0.247860,0.513875,0.030767,-0.218081,0.274158,-0.227707,-0.116625,0.245991,0.535930,0.444178,-0.350212,0.159948,0.167332,0.570205,0.880855,-0.002349,-0.423201,0.203899,-0.401763,-0.316957,-0.097581,-0.267865,-0.475727,-0.560284,0.109511,0.254094,-0.110225,0.136242,-0.463327,0.064247,0.354320,-0.167924,0.222600,-0.508710,-0.180658,-0.834183,0.044363,-0.489677,-0.315191,0.127228,0.234902,-0.279141,0.997990,-0.577395,0.117329,0.533204,0.025501,-0.305682,0.437612,0.077714,0.168650,-0.169321,0.064195,0.563754,-0.086502,0.230962,0.146874,0.331025,-0.204022,0.343367,-0.683962,0.401674', '5403927', '3811356', '2369613', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3670447', '大内密探灵灵狗', '喜剧', '庄严的皇宫内，十二位以属相命名的大内密探肩负着贴身保护皇上的重任，其中高天九外号“灵灵狗”（古天乐 饰）是一位满脑子充满奇想秒招的发明家。他靠各种“法宝”在保护皇上的过程中屡建奇功，但对于自己风情万种却功艺高强的未婚妻梅希望（大S 饰）的一片痴心，“灵灵狗”的反应却表现的相当木讷。为了让这“灵灵狗”这个木瓜开窍，梅希望想出了一个试探“灵灵狗”的办法。深宫之类忠奸难辨，暗藏杀机。围绕公主选附马一事，各方面的力量都暗自勾结，企图谋权篡位并消灭以“灵灵狗”为首的大内密探，皇上安危遭受威胁，十二密探面临前所未有的挑战。©豆瓣', '古天乐', '王晶', 5.2, 150362, 'tt1475330', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1143572677.jpg', 12.5, 31.1, 42.7, 10.4, 3.3, '0.028243,0.054032,-0.366488,0.982294,0.166838,0.272481,0.628210,0.061440,-0.504853,-0.704089,0.383790,0.460429,-0.119532,-0.129386,0.174115,-0.278466,0.178295,-0.379802,-0.369173,0.032616,-0.150936,-0.463874,-0.344151,-0.245773,-0.216427,-0.276261,0.555309,0.128803,-0.110321,0.208800,0.516001,0.373840,-0.045548,0.331785,0.067693,-0.266218,-0.005611,-0.187986,0.067584,0.230181,-0.120280,-0.423452,-0.110226,0.502894,-0.088410,0.289052,0.371944,-0.476053,0.011966,-0.297249,0.213148,-0.162181,-0.114243,0.164411,0.205580,-0.131065,0.006118,0.181428,-0.086594,0.100567,0.175483,-0.069453,-1.230925,-0.304151,0.531745,-0.088797,-0.476806,-0.053139,0.048168,-0.012163,-0.084926,0.071078,0.108426,0.112078,0.091280,0.332057,-0.278213,0.001434,-0.632813,-0.058861,0.236837,-0.145813,-0.117660,-0.013212,-0.021005,-0.458314,-0.000802,-0.390964,-0.097534,-0.181666,-0.180860,0.130704,0.301193,-0.052463,-0.340933,-0.033502,-0.277224,-0.067779,-0.129152,-0.436995,0.200169,-0.286233,-0.021800,-0.462642,-0.254535,0.125032,0.366655,-0.195217,0.688701,-0.558278,-0.067676,0.332292,-0.065185,-0.993986,0.449579,0.393921,0.043920,-0.279443,-0.629865,0.151995,0.155539,-0.166074,-0.156243,0.271802,-0.048939,-0.349754,-0.350840,0.240117', '26678784', '1302110', '30163500', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3671986', '魔法保姆麦克菲2', '喜剧', '战火纷飞的年代，英国乡间的一处农场维持着宁静的风景。格林太太（玛吉·吉伦哈尔 Maggie Gyllenhaal 饰）独自经营着这处家庭农场，等待参军服役的丈夫归来。农场和家里三个调皮捣蛋的孩子令她费劲心神，败家的亲戚菲尔（瑞斯·伊凡斯 Rhys Ifans 饰）又不时上门纠缠。原来菲尔自己在外欠下了赌债，企图拿格林家的农场抵债，屡遭拒绝仍贼心不死。更令格林太太头疼的是，她的侄子和侄女要从城里来乡下长住以躲避战火。这对养尊处优的堂兄妹与格林家的三个孩子格格不入，双方一见面便引发了家庭大混战，失控的局势令格林太太几近崩溃。魔法保姆麦克菲（艾玛·汤普森 Emma Thompson 饰）适时出现在了格林太太面前。她施展神奇的魔力迅速终止了这场混战，并从此留在格林家里教导这些孩子。在农场生活中，麦克菲教会了孩子们五堂终身有益的人生课程，也令自己原本丑陋的样貌逐步发生着改变……本片是2005年电影《魔法保姆麦克菲》的续集，但两部故事并无直接关联。', '拉尔夫·费因斯', '苏珊娜·怀特', 7.6, 35561, 'tt1415283', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p452830210.jpg', 0.3, 2.4, 32.3, 46.3, 18.7, '0.262466,-0.013157,-0.636897,0.394005,0.095630,-0.423825,0.634135,0.341916,-0.380664,-0.347659,0.125850,0.617964,-0.133746,0.356060,0.028092,-0.062362,-0.525935,-0.571277,-0.185343,0.019644,-0.003535,-0.518678,0.062546,-0.312400,-0.186178,-0.403528,0.204299,-0.082821,-0.058151,0.292795,-0.024653,0.047696,-0.078644,0.179595,-0.136752,0.127322,0.023753,-0.069198,-0.304795,0.066497,0.109196,-0.060707,-0.221806,0.192686,0.447603,0.364713,0.788341,-0.348455,0.128574,-0.155579,0.164035,-0.026609,-0.034533,-0.037741,0.378338,-0.210850,0.100428,0.021533,-0.271671,-0.075933,0.127259,-0.211099,-0.295331,0.280002,0.047189,-0.002649,-0.552995,0.281076,0.066731,-0.232158,-0.045020,-0.320321,0.087384,0.419348,0.281134,0.331000,-0.206793,0.213267,-0.434235,0.073138,0.582998,-0.129473,-0.234370,0.285150,-0.423939,-0.286716,0.042148,-0.337230,-0.896176,-0.040322,0.281037,-0.140756,0.063674,0.503252,-0.700453,0.075189,-0.572395,-0.173708,-0.010921,-0.383042,-0.126132,-0.656142,-0.128015,-0.270468,-0.387641,-0.127313,0.183558,0.054548,0.535276,-0.582490,0.179819,0.522494,0.319295,-0.372191,0.429526,-0.001754,0.402647,-0.019795,-0.233765,0.168384,0.069266,0.278619,0.177722,0.233445,-0.078187,0.147982,-0.139691,0.568709', '35161768', '1419992', '5503303', '1482086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3673923', '赏金猎手', '喜剧', '因沉迷赌博而负债累累的赏金猎手米洛·博伊德（杰拉德·巴特勒 Gerald Butler 饰）接到工作追捕自己的前妻，记者妮可·赫莉（詹妮弗·安妮斯顿 Jennifer Anniston 饰）。妮可因追踪一件离奇自杀事件，错过自己袭警交通案的出庭而被法院通缉。对自杀事件内情紧追不舍的她想尽了一切办法逃跑，使得本来就因彼此憎恨而离婚的两人关系更加糟糕，直到有神秘杀手突然出现要至妮可于死地。米洛这才发现自己对妮可一直不能忘情。为了保护妮可的安全，米洛带她来到了二人当初渡蜜月的“丘比特庄园”，前尘往事涌上心头，二人也都对是否应重续前缘而举棋不定。与此同时，米洛的赌债和妮可的调查只将情况搞得更加复杂……©豆瓣', '詹妮弗·安妮斯顿', '安迪·坦纳特', 6.1, 16288, 'tt1038919', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p458572895.jpg', 2, 15.8, 59.6, 19.1, 3.5, '0.414200,-0.336013,-0.774586,0.350748,0.021898,-0.366451,0.765950,0.148768,-0.476840,-0.237200,0.394845,0.620854,-0.348828,0.027529,0.381176,0.110413,-0.161671,-0.790981,0.213553,-0.103662,-0.197053,-0.569448,-0.139879,-0.423841,-0.087604,-0.122687,0.556966,0.081059,-0.193571,0.354882,0.409136,0.536326,-0.353377,0.584185,0.085983,-0.062676,0.108979,0.004172,-0.238368,0.151109,0.356967,-0.429649,-0.094817,0.298027,-0.129409,0.490900,0.538175,-0.247341,-0.355568,0.018535,0.289687,-0.659981,0.008969,0.166824,0.292817,-0.017453,0.092134,0.314135,-0.501087,-0.100757,0.125600,0.066919,-0.656693,0.269289,0.057088,0.228774,-0.337534,0.146587,-0.371005,0.114546,0.241672,-0.239232,0.139394,0.402461,0.259778,0.170455,-0.251084,-0.130647,-0.361770,-0.123263,0.629830,-0.120813,0.066090,0.297453,-0.073606,-0.242876,-0.081398,-0.011586,-0.392007,0.050567,0.378029,0.148982,-0.050613,0.348304,-0.412809,-0.166327,-0.362128,-0.116768,-0.194771,-0.285338,-0.068534,-0.459169,-0.264885,-0.114120,-0.273750,-0.014370,0.092233,-0.203750,0.305210,-0.614994,0.127920,0.662191,0.262221,-0.830141,0.215994,0.106638,0.092115,-0.130248,-0.226196,0.315933,0.142161,0.145916,0.142878,-0.007655,0.179455,-0.024300,-0.248686,0.376327', '35073886', '1309116', '1301022', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3681613', '大闹天宫', '动画', '在遥远的东方傲来国，一枚承受了日精月华的石头突然炸裂，从里面蹦出了一只石猴（李扬 饰）。石猴在附近的花果山占山为王，逍遥自在，好不快活。只可惜他虽天赋神力，却没有一件得心应手的兵器。在老猴的建议下，美猴王入龙宫，强从东海龙王（陈凯歌 饰）那里讨来定海神针金箍棒。龙王一纸诉状告到天庭，玉帝（陈道明 饰）接受太白金星（张国立 饰）的建议，先后将美猴王骗到天宫作弼马温、管理蟠桃园。发觉被骗的美猴王怒砸马栏、破坏蟠桃宴，返回花果山自命齐天大圣。由此和十万天兵天将展开了惊心动魄的大战……本片根据中国古典四大名著之一的《西游记》改编，是上海美术电影制片厂经典名作的重新修复的版本。©豆瓣', '李扬', '万籁鸣', 7.9, 14965, 'tt11941418', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2500167606.jpg', 2.3, 3.8, 22.1, 38, 33.8, '0.160321,0.359701,-0.701017,0.675606,0.022884,0.013957,0.444716,0.162062,-0.291604,0.239400,0.211418,0.563561,-0.179392,-0.147068,-0.175179,0.255000,0.134941,-0.148506,-0.050759,0.064048,0.115526,-0.142489,-0.484767,0.084610,-0.264505,-0.272317,0.386244,0.058344,-0.183957,0.272757,0.132037,-0.074534,-0.278317,0.077507,-0.241545,0.187403,-0.232342,0.442018,0.180748,0.355158,-0.218581,-0.469900,0.006778,0.155721,0.018098,0.252714,0.347371,-0.425644,-0.179626,-0.169818,0.393201,-0.032090,-0.281285,0.004072,0.327261,0.122773,-0.064430,-0.051522,-0.331000,0.220913,0.201437,-0.296475,-0.316727,-0.372479,0.085840,0.113259,-0.485092,0.558041,-0.050580,-0.008040,-0.240093,-0.358768,0.291396,0.113675,0.053937,0.406566,-0.008502,0.013024,-0.424647,0.669387,0.368152,-0.118553,-0.067544,0.147930,0.253313,-0.358301,-0.133806,-0.129871,0.017446,-0.035334,0.580773,-0.195358,0.066831,-0.048654,-0.535577,-0.204906,-0.182789,-0.067350,-0.212438,-0.159501,-0.038426,-0.359229,-0.015510,-0.066398,-0.103153,-0.285364,0.373980,0.180268,0.723079,-0.352746,0.142637,0.245193,-0.127863,-0.090525,0.624613,-0.138163,-0.068103,-0.131416,0.075575,0.062826,0.231647,0.392053,0.245589,0.416784,0.032192,-0.322080,-0.437152,0.330669', '27602116', '2027945', '22265121', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3683409', '夜·店', '喜剧', '那夜超市人未眠。粗心的24小时超市老板娘打错了彩民何三水（徐峥 饰）的彩票，使何三水错失9500块钱的奖金。在几次讨说法未果的情况下，何三水带着愣头愣脑的侄子决定非讨个说法，然而两个夜班营业员李俊伟（乔任梁 饰）和唐晓莲（李小璐 饰）并不能解决此事。在几番令人啼笑皆非的折腾之后，何三水在李俊伟的帮助下，终于找到了快速拿到9500块钱的方法。正当所有人认为事情要圆满落幕之时，半路状况频发，先是老板娘横空出世，其后劫匪也赶来凑热闹，但是结尾时却又让人生出几分意外的惊喜。这部电影是橙天和中影“青年导演计划”的最新力作，也是青年导演杨庆的银幕处女作。©豆瓣', '徐峥', '杨庆', 6.8, 173021, 'tt1514426', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p516451928.jpg', 1.8, 9, 46.3, 33.6, 9.2, '-0.190506,0.084215,-0.474738,0.363393,0.032173,-0.376504,0.408039,0.169936,-0.603728,-0.211664,0.084183,0.423003,-0.477533,0.215922,0.607112,-0.204055,-0.321862,-0.303865,0.122882,-0.094321,-0.254955,-0.323800,-0.116320,-0.253545,0.071046,0.088557,0.414381,0.379885,-0.145675,0.319733,0.599482,0.073018,-0.334686,0.608543,0.094070,0.393681,0.118095,0.020995,-0.315782,0.170141,0.261933,-0.486128,-0.598287,0.320055,0.044179,0.369771,0.479028,0.130403,-0.540844,0.366040,0.417027,-0.159075,-0.129382,-0.341216,0.169086,-0.085730,0.363166,-0.078578,-0.040232,0.083884,0.134202,0.045689,-0.609832,0.197090,0.031244,0.036819,-0.591858,0.190913,-0.128652,0.180035,0.053216,-0.412614,0.024266,0.385533,0.391119,0.230377,-0.171550,-0.078094,-0.493175,0.283383,0.323531,0.265596,0.158760,0.399587,0.044202,-0.516977,-0.229746,0.159212,-0.409216,0.336839,0.555334,0.160034,-0.193423,-0.275658,-0.375205,-0.071056,-0.230048,0.017375,-0.015103,-0.125009,-0.143166,-0.587801,0.179491,-0.132265,-0.244120,0.129683,0.332556,-0.176407,0.484109,-0.599009,-0.240769,0.213223,0.099106,-0.390914,0.462671,-0.041927,-0.201141,-0.231521,0.083792,-0.596073,-0.034669,0.174052,0.245431,0.385281,-0.108742,-0.416692,-0.200486,0.332527', '26649095', '1793491', '1401533', '1299649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3683521', '在某处', '剧情', '好莱坞著名的男明星约翰尼（斯蒂芬·多尔夫 Stephen Dorff 饰）是一个终日与酒色作伴的浪荡子，他住在酒店里过着花天酒地的生活。突然有一天，素未谋面的女儿克里奥（艾丽·范宁 Elle Fanning 饰）闯入了他的生活，由于克里奥的妈妈将外出办事，约翰尼不得不暂时扮演回父亲的角色，甚至要带着女儿去参加意大利电影节。在与女儿的短暂相处中他们渐渐建立起了感情，一切都在微妙的变化中，在女儿回家后，约翰尼开始重新审视起自己的生活。本片获得第67届威尼斯电影节金狮奖。©豆瓣', '艾丽·范宁', '索菲亚·科波拉', 6.5, 11342, 'tt1421051', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1682401087.jpg', 2.9, 14.2, 46.7, 27.4, 8.8, '-0.066468,-0.045844,-0.809647,0.639401,-0.111773,-0.451365,0.771924,0.223101,-0.690328,-0.167929,0.109050,0.903465,-0.045009,0.528093,0.554671,0.103014,-0.590674,-0.676831,-0.266679,-0.278315,0.010838,-0.396776,-0.364857,0.031815,-0.193959,-0.356759,0.473314,-0.304688,-0.043165,0.519673,0.473147,0.040566,-0.194570,0.585177,-0.322580,0.137190,0.110385,0.087492,-0.584101,0.419223,0.387482,-0.249635,-0.338636,-0.077939,0.369660,0.237305,0.820815,-0.287552,0.096319,-0.067208,0.372139,0.058599,-0.222933,0.012749,0.036297,0.166239,0.249888,0.350673,-0.338334,0.362600,0.087313,-0.349810,-0.315443,0.062321,0.158584,0.253318,-0.761012,0.535431,-0.075211,-0.228314,-0.024292,-0.394505,0.233276,0.318544,0.095296,0.349558,-0.081476,0.174226,-0.451519,0.321808,0.604429,0.037915,-0.206221,0.266446,-0.187096,-0.274013,-0.004098,-0.257229,-0.745724,-0.255137,0.371750,-0.169142,-0.138378,0.595510,-0.606463,-0.059756,-0.089828,-0.328039,0.219085,-0.239871,0.071775,-0.636878,-0.117290,-0.388554,-0.278985,-0.145660,-0.171280,-0.394748,0.579370,-1.051365,0.275998,0.591653,0.390881,-0.276949,0.533575,0.101887,0.480398,-0.053735,-0.058338,0.329963,-0.204547,0.351163,0.096543,0.499483,-0.135761,0.063042,-0.375804,0.683342', '30450313', '1292219', '2027925', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3690289', '春风沉醉的夜晚', '剧情', '在南京开小书店的王平（吴伟 饰）背着妻子林雪（江佳奇 饰）与男同性恋者姜城（秦昊饰）有染。对丈夫行为生疑的林雪委托罗海涛（陈思成 饰）跟踪王平，发现了姜城的行踪。气愤的林雪到姜城任职的旅游公司大闹，迫使其与王平分手。罗海涛有一个在制衣厂做工的女友李静（谭卓 饰），但他却在跟踪的过程中对姜城产生了好感。罗海涛与分手后情绪低落的姜城交往，二人关系日渐亲密，但与此同时他又难舍李静。在三人共同出游的过程中，李静发现了罗海涛与姜城的暧昧关系，伤心落泪。一座城，许多人，都在感情的路上崎岖前行。本片被提名2009年第62届戛纳电影节金棕榈奖，并获最佳编剧奖。©豆瓣', '秦昊', '娄烨', 8.1, 120066, 'tt1422119', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p463651314.jpg', 0.4, 1.8, 18.2, 50.8, 28.8, '0.153645,-0.104357,-0.786432,0.537786,0.204521,-0.440065,0.550054,0.417130,-0.798338,-0.216768,0.139129,0.589347,-0.334258,0.182814,0.228485,-0.234527,-0.288859,-0.667603,-0.027826,-0.252509,-0.049956,-0.419436,0.008441,-0.045855,-0.237670,-0.145561,0.275008,-0.184046,-0.338508,0.756120,0.478549,0.014375,-0.333761,0.570350,0.064533,0.319097,0.290662,0.439596,-0.657150,0.239956,-0.168179,-0.121465,-0.270884,-0.092451,0.125098,0.463612,0.749257,0.242203,-0.266732,0.098908,0.388451,-0.259900,0.116282,0.042859,0.541290,0.122310,0.169661,0.288759,-0.311288,0.018445,0.197866,-0.014908,-0.408953,0.265994,0.302932,0.296602,-0.520248,0.528322,-0.106540,-0.099651,0.034906,-0.461072,0.331579,0.648128,0.276056,0.226011,-0.135844,0.009000,-0.374069,0.181122,0.714650,0.125252,0.035337,0.124882,-0.216287,-0.467316,-0.251538,0.200797,-0.516074,-0.196142,0.571040,-0.097219,-0.145576,0.242055,-0.496999,-0.116969,0.137232,0.293607,-0.099336,-0.165563,0.298827,-0.646507,-0.084205,-0.630189,-0.235194,0.047471,-0.016315,-0.182874,0.282633,-0.683663,0.323526,0.267892,0.605287,-0.472779,0.510141,0.328486,-0.016138,-0.316895,-0.211878,0.272183,-0.017747,0.287400,0.033296,0.435067,-0.234997,-0.375152,-0.294803,0.145014', '25856453', '1302987', '3401409', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3692602', '丛林奇航', '喜剧', '影片根据迪士尼乐园游玩项目“丛林巡航”改编，故事发生在野心家与探险家并起的上世纪初，勇敢无畏的女科学家莉莉·霍顿博士（艾米莉·布朗特 饰） 来到亚马逊寻找有治愈魔力的神树，并雇佣了玩世不恭的弗兰克船长（道恩·强森 饰）开启探险。在这史诗般的冒险途中，看似不对盘的两人在茂密雨林中遭遇了无数的危险和超自然力量。但随着这棵神奇古树的秘密逐渐揭开，莉莉和弗兰克的命运，乃至整个人类的命运都岌岌可危。', '道恩·强森', '佐米·希尔拉', 6.1, 39629, 'tt0870154', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2710065784.jpg', 1.6, 15.3, 63.8, 16.6, 2.7, '0.178510,0.004524,-0.575798,0.542720,0.152331,-0.011024,0.857652,-0.064183,-0.371996,-0.049274,0.215268,0.800268,-0.128099,-0.005518,0.362045,0.102657,-0.601111,-0.289840,-0.145111,-0.096820,-0.209220,-0.525242,-0.503481,-0.070097,0.171462,-0.617618,0.821995,0.059804,-0.431568,0.451166,-0.133012,0.281309,-0.365310,0.240745,-0.318479,-0.051000,0.221274,0.134707,-0.348570,0.114814,-0.132506,-0.189464,0.039504,-0.190942,-0.105363,0.217822,0.559910,-0.753229,-0.108217,0.044191,0.344962,-0.261414,0.080549,-0.124692,0.358121,0.039489,-0.105598,0.366230,0.123521,0.124142,0.101199,-0.405146,-0.735920,-0.071706,0.244488,0.414225,-0.424946,0.214069,0.163122,-0.012250,0.059604,-0.414851,0.142092,0.348506,0.253164,0.270707,0.006446,0.032950,-0.443894,0.044758,0.522782,0.015926,-0.545325,0.332302,-0.389109,-0.466802,-0.326596,0.108240,-0.423179,-0.113054,0.373401,0.147440,-0.118196,0.488675,-1.040829,0.348483,-0.099741,-0.314774,-0.034798,-0.220621,-0.187155,-0.884069,-0.232254,-0.408183,-0.259437,0.121992,0.186838,-0.299992,0.642922,-0.842947,0.384732,0.677674,0.196376,-0.110823,0.430828,-0.288107,-0.043886,-0.378135,-0.162808,0.592370,-0.177611,0.621655,-0.078157,0.460746,0.198796,-0.267237,-0.334196,0.426777', '26290398', '20274039', '1309056', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3696535', '极道鲜师电影版', '剧情', '日本警方接到报案，某飞机被恐怖分子劫持，机上乘客沦为人质。对方提出了无理要求，如果不答应，就会有人牺牲。而山口久美子（仲间由纪惠 饰）刚好和闺蜜一起旅游，乘坐的就是这次班机，她的正义感再次被点燃，经过一番搏斗，最终她制服了歹徒。就在日本警方严阵以待，准备接受恐怖分子的请 求时，直播的大屏幕却显示对方已经投降，而作为胜利者走出机舱的确是山口，面对镜头，她还大方征婚，令人咋舌。回到赤铜学院的课堂，送走了毕业班，新升上来的三年级D 班里调皮捣蛋的学生也不少，一点也没让山口省心。还好她在黑银学院的学生小田切龙在旁。学生高杉怜太得罪了暴走族，以致后者大闹校园。校长猿渡五郎给了山口最后通牒……本片是热播了7年的《极道鲜师》的完结篇。©豆瓣', '仲间由纪惠', '佐藤东弥', 6.6, 7776, 'tt1392158', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1029138051.jpg', 2.3, 10.8, 51.5, 23.9, 11.4, '0.343388,-0.095535,-0.380604,0.313623,-0.202973,-0.275518,0.436260,-0.002372,-0.388354,-0.100309,0.362020,0.559455,-0.266813,0.392897,0.338998,-0.074790,-0.331913,-0.590446,-0.057831,-0.126269,-0.268613,-0.259037,0.098231,-0.159122,-0.051382,-0.145557,0.665237,0.125151,-0.265507,0.427200,0.410848,0.098557,0.081423,0.418914,-0.206191,-0.019392,0.079206,-0.091914,0.095197,0.213920,-0.180714,-0.434401,-0.110099,0.108938,0.353128,0.345716,0.605800,0.173479,-0.169224,-0.097944,0.301669,-0.613286,-0.015230,0.209310,0.652644,-0.045469,0.209438,0.228713,-0.044282,0.051642,-0.067926,0.059809,-0.244863,0.074479,-0.115999,0.038377,-0.471950,0.507277,-0.245915,0.015461,0.230006,0.038054,-0.002659,0.141330,0.081709,0.076612,-0.083237,-0.123299,-0.302256,0.182297,0.428524,-0.069226,-0.082539,0.015612,0.072279,-0.607296,0.200575,-0.174987,-0.221201,0.069063,0.373288,-0.215229,-0.109695,-0.183331,-0.263883,-0.247641,-0.298529,-0.372280,0.150958,-0.381135,-0.037274,-0.946822,0.188362,-0.053147,-0.359573,0.297299,0.058501,0.102362,0.726774,-0.810586,-0.007242,0.602462,0.361403,-0.349792,0.440890,-0.003867,-0.224133,-0.071951,0.110900,-0.311449,0.200587,0.735212,0.226080,0.419963,-0.069596,-0.543627,-0.204660,0.121596', '25723905', '2369613', '1316589', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3699737', '新铁血战士', '动作', '一道极强的亮光，将分处五大洲的8个人带到了一片未知所在。他们身背降落伞从高空坠落，继而落入一望无边的雨林。这群人中有车臣部队战士、以色列国防军、墨西哥特种部队成员、FBI通缉的要犯、日本黑帮稻川会头目以及一名与其他人格格不入的医生。他们彼此互不相识，也不知道为何被带到了这片陌生丛林。在罗伊斯（阿德连·布隆迪 Adrien Brody 饰）的带领下，众人开始朝制高点进发，最终发现他们竟然置身在一颗外星球中。与此同时，凶猛邪恶的猛兽接连向他们袭来，罗伊斯意识到，他们不过是一群外星生物选出的猎物，而这片雨林正是外星人的狩猎场。危机四伏，这些无所依靠的人类不得不去面对身形巨大、嗜好杀戮的铁血战士……©豆瓣', '艾德里安·布洛迪', '尼姆罗德·安陶尔', 6.4, 31148, 'tt1424381', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2172621483.jpg', 2.1, 12.7, 55.9, 22.8, 6.5, '0.424472,-0.231096,-0.927612,0.658391,-0.099869,0.148041,0.855281,-0.079169,-0.615315,-0.047507,0.504593,0.699420,0.145632,-0.121591,0.173162,-0.057152,-0.101370,-0.512145,-0.574300,-0.433130,-0.529054,-0.189009,-0.414211,-0.264453,0.100208,0.012474,0.835640,0.190755,-0.280127,0.442322,0.010799,0.415969,-0.580831,0.508923,-0.253578,-0.112251,0.137907,-0.210882,-0.317423,0.261642,-0.406911,-0.123039,-0.255872,0.142396,-0.339010,0.272031,0.849701,-0.473196,0.080346,-0.214718,0.197071,-0.438073,0.011387,0.208203,0.581544,-0.121463,-0.018080,-0.322242,0.354623,0.183300,-0.168169,-0.043302,-0.468545,-0.028473,-0.121340,0.388245,-0.488295,0.364521,0.129599,-0.296877,0.153641,-0.243722,0.223151,0.046856,0.001819,0.297034,-0.089955,-0.151162,-0.560563,-0.251656,0.868238,-0.079311,-0.433878,-0.164143,-0.099489,-0.583711,-0.132394,0.088669,-0.160854,-0.362168,0.518626,0.168943,-0.134417,0.366942,-0.870963,0.371501,-0.065835,-0.600404,-0.150804,-0.296888,-0.423879,-0.520366,-0.079999,-0.319175,-0.101262,0.497262,-0.005594,0.248020,0.613540,-0.800969,0.156217,0.612021,0.303004,-0.186912,0.487370,-0.450448,0.175929,-0.108776,-0.065343,0.195662,0.596086,0.620140,0.169886,0.224336,-0.278872,-0.028537,-0.296221,0.024377', '21619567', '1856675', '3011051', '1438591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3706859', '狗牙', '剧情', '本片讲述了一个与世隔绝的奇怪家庭。家庭成员由一对父母和大儿子、两个女儿组成，一家五口终日生活在一座隐秘的大宅子里。三个孩子自小被父亲隔离于此，他们不能接触除父母外的人，对高墙之外的世界几乎一无所知。父亲上班后，他们就与母亲在屋子里学习、玩耍。他们所有的知识都由父母教导，父亲告诉他们，外面的世界极其危险，而孩子们如果想要出去，必须等到“狗牙”脱落。父亲是唯一可以驾车到外面去的人，他有一份正常的工作，会为孩子们带回生活必需品以及奖赏，他有时也会带回公司里一个女员工——克里斯蒂安，她是受雇来满足大儿子的性需求的。而她的几次到来，正在悄悄地改变这个家庭……©豆瓣', '赫里斯托斯·斯泰尔伊约格卢', '欧格斯·兰斯莫斯', 7.6, 22337, 'tt1379182', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1559253638.jpg', 1, 3.8, 29.5, 47.4, 18.2, '0.156708,-0.200956,-0.833668,0.599037,-0.480415,-0.184392,0.812155,0.134499,-0.738101,-0.434518,0.021998,0.953131,0.402378,0.636198,0.099516,0.021723,-0.232591,-0.594404,-0.241323,-0.317505,-0.483365,-0.418916,0.015464,-0.634124,-0.260347,-0.162818,0.389120,-0.055949,0.048794,0.247882,0.124432,-0.029684,-0.397150,0.303626,-0.360517,-0.053624,-0.131055,0.094101,-0.363150,0.136707,-0.108970,0.196663,-0.138612,0.030114,0.261377,0.246911,0.726821,-0.141551,-0.287077,-0.309636,0.217906,-0.023390,-0.108138,0.294555,0.432153,-0.112342,0.574855,0.311384,-0.381630,0.121302,-0.102773,-0.188498,-0.723519,-0.131913,0.201104,-0.073749,-0.805975,0.376394,0.342555,-0.203392,0.071432,-0.525679,0.456839,0.356013,-0.095220,0.693945,-0.323883,-0.036065,-0.435629,0.113434,0.876139,-0.340206,-0.010370,0.141500,-0.395882,-0.123751,0.004879,-0.178720,-0.771565,0.106138,0.130368,0.206629,-0.351764,0.052452,-0.417356,0.129346,-0.114104,-0.284973,0.123790,-0.531773,0.060938,-0.600925,0.175517,-0.300223,-0.372247,0.227950,0.134483,-0.257036,0.978837,-0.743290,0.258116,0.346376,0.437753,-0.925621,0.830495,0.048843,0.648552,-0.215391,0.047496,0.002008,0.185113,0.231668,-0.132544,0.282686,0.034771,-0.003790,-0.411704,0.311043', '1292337', '1296770', '4861627', '20470260');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3706862', '危狱惊情', '剧情', '谨慎恭敬的杰克·马尔比（罗伯特·德尼罗 Robert De Niro 饰）在某政府部门供职，每天的工作便是对那些申请假释的犯人进行审核。他年复一年干着这份枯燥无味的工作，与妻子麦迪琳（Frances Conroy 饰）的关系也分外冷淡。他的心中隐藏着蓬勃的欲望，却又不得不用端正的表象去掩饰。在杰克即将退休的时刻，已经蹲了八年大牢的纵火犯乔治·“石头”·克里森（爱德华·诺顿 Edward Norton 饰）来到他的桌前。乔治希望早日走出大墙，为此巧言令色试图博取杰克的信任，甚至不惜让美艳的妻子卢赛塔（米拉·乔沃维奇 Milla Jovovich 饰）色诱这个看似一本正经的君子。杰克心中的欲望渐渐失控，而企图通过宗教包装自己的乔治也仿佛听到来自上帝的福音……©豆瓣', '爱德华·诺顿', '约翰·卡兰', 5.8, 6747, 'tt1423995', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p641877993.jpg', 3.7, 24.8, 51.9, 15.5, 4.1, '0.287239,0.147653,-0.691369,0.809405,-0.293989,-0.450499,0.825698,0.339197,-0.343542,-0.243649,0.359384,0.492064,-0.209846,0.158432,0.132986,0.117697,-0.524132,-0.683889,-0.338539,0.105865,-0.150287,-0.417864,-0.236274,-0.419424,-0.349659,-0.167824,0.506439,-0.004154,0.063743,0.360192,0.242128,0.392687,0.305419,0.370554,0.009031,-0.134341,0.064864,-0.262652,-0.247148,-0.044281,0.314045,-0.198932,-0.238671,0.278317,0.065111,0.396459,0.452115,-0.246251,-0.130412,0.193893,0.299990,-0.233506,0.147175,0.367344,0.009948,0.056413,-0.199916,0.289458,-0.361248,0.172443,0.250940,-0.175138,-0.807309,-0.049625,-0.211990,0.282187,-0.399056,0.465028,-0.272657,0.157004,0.216637,-0.188548,-0.055296,0.179132,0.003352,0.439335,-0.239903,-0.003330,-0.387985,0.049532,0.017913,0.093401,-0.203526,0.251107,-0.426701,-0.375464,0.127751,-0.039999,-0.458534,-0.503641,0.295163,-0.055320,-0.011220,0.323088,-0.648074,-0.120430,-0.359556,-0.070368,-0.039723,-0.477182,0.028461,-0.722460,-0.101655,-0.446413,-0.170492,0.008932,0.097401,-0.267868,0.548348,-0.621974,0.280413,0.577433,0.061787,-0.262442,0.319776,0.041269,-0.034281,-0.163920,-0.404516,0.538454,0.071192,0.454781,0.123649,0.460120,0.165545,-0.039046,-0.295558,0.736044', '35158375', '27666513', '4924694', '26369884');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3707070', '我杀了我妈妈', '剧情', '不幸的童年经历让十六岁的少年于贝尔（泽维尔·多兰 Xavier Dolan 饰）早早过上了同母亲（安妮·杜尔瓦勒 Anne Dorval 饰）相依为命的生活，然而，随着年龄的增长和叛逆期的到来，于贝尔渐渐发现，自己和母亲之间开始变得越来越难以沟通，两人之间的距离渐行渐远 。内心充满了痛苦和矛盾，于贝尔开始了艰难的尝试，企图重塑他和母亲之间破裂的亲情与信任，可是，就在于贝尔的努力逐渐产生成效之时，他和同性男友安东尼（弗朗柯斯·阿诺德 François Arnaud 饰）之间的关系曝光了，这让他同母亲之间的关系再次回归了冰点之下。在安东尼的帮助下，于贝尔从寄宿学校出逃，偌大的天地之间，他能够寻找到一片得以藏身其中的小小天地吗？©豆瓣', '泽维尔·多兰', '泽维尔·多兰', 8.3, 59223, 'tt1424797', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p490697335.jpg', 0.3, 1.3, 15.1, 48.4, 34.9, '0.454230,0.126805,-0.891428,0.675777,0.110399,-0.444134,0.972047,0.337961,-0.635116,-0.185183,-0.319212,0.738400,-0.442804,0.305292,0.358972,-0.289943,-0.215598,-1.013301,0.018144,-0.225889,-0.246436,-0.793893,-0.427274,-0.005096,-0.344452,-0.515876,0.720201,0.124647,-0.181806,0.575065,0.106383,0.291674,-0.175685,0.547809,-0.108245,0.100424,0.113250,0.170064,-0.388939,-0.076550,0.194079,-0.028495,0.152063,0.163597,-0.095508,0.471946,0.714835,-0.187422,-0.016689,-0.094601,0.358370,0.169456,-0.045687,0.269475,0.192461,0.157542,0.289914,0.287999,-0.346697,-0.071984,0.019443,-0.086226,-0.540908,0.294839,0.074332,-0.053135,-0.510440,0.440344,0.223244,-0.367628,0.402806,-0.326071,0.225215,0.804050,0.211064,0.465715,-0.379469,-0.167755,-0.282600,-0.241279,0.981322,-0.133943,-0.285333,0.561563,-0.401644,-0.322235,-0.240755,-0.098222,-0.451326,-0.420231,0.270349,0.561373,-0.157466,0.629755,-0.718658,-0.070041,-0.273819,0.039586,0.034519,-0.485264,0.213572,-0.416988,-0.704906,-0.844519,-0.292143,0.196523,-0.123282,-0.565495,0.620331,-0.904364,0.378862,0.290062,0.378612,-0.292767,0.603528,0.076402,0.426430,-0.188732,0.099944,0.399003,-0.286594,0.221406,0.277750,0.249794,-0.125445,0.423374,-0.490697,0.650168', '24325798', '26857860', '1302109', '25810920');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3711718', '女高怪谈5：结伴自杀', '恐怖', '某教会女子高中，清纯美丽的女孩言珠（张京雅 饰）、尹素伊（孙银书 饰）、李幼珍（吴妍瑞 饰）、金恩英（宋敏静 饰）是同一年级不同班的好友，其中言珠与素伊更是亲密无间的死党。某晚，四个女孩许下“不能同生、但愿同死”的誓言，相约自杀。然而，最终只有言珠一人从生活关的顶楼跳下来。事后，素伊她们相约保守秘密，既为了远离麻烦，也是为了避免因自杀失败而被同学嘲笑和鄙视。只是世上岂有不透风的墙？很快，她们曾和言珠相约自杀的消息便在同学中流传开来。另一方面，冥冥中似乎有个黑暗的魅影时刻逡巡在她们的身边。誓言岂可轻易许下？又怎能随便违背？©豆瓣', '刘信爱', '李宗容', 5.9, 11457, 'tt1565058', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1655619261.jpg', 4.5, 21.4, 54.5, 14.5, 5.1, '0.261341,-0.161230,-0.504285,0.300663,-0.143760,-0.167989,0.527850,0.137841,-0.333587,-0.119157,0.106368,0.539918,-0.147880,0.360302,0.115637,-0.264942,-0.142010,-0.649189,0.109412,-0.355997,-0.245629,-0.342206,0.277765,-0.391485,-0.031271,-0.132673,0.656605,0.096359,-0.250615,0.276602,0.540545,0.354182,-0.743970,0.227051,-0.243716,-0.293651,-0.140318,0.369823,-0.344532,0.078344,-0.189264,-0.054318,0.026134,0.012372,-0.074387,0.241716,0.453554,-0.542045,-0.157534,-0.110578,0.249361,-0.015665,-0.003854,0.045289,0.257636,-0.174841,0.304628,0.393677,-0.145787,0.011160,0.091306,-0.051867,-0.523365,0.001875,0.528495,0.058148,-0.165909,0.693647,0.100998,-0.145440,0.270860,0.095209,0.007075,0.151971,0.571239,0.210405,-0.141310,-0.083075,-0.339998,-0.183360,0.636047,0.163442,-0.011672,0.227521,-0.217254,-0.263324,0.216459,-0.037214,-0.401855,0.252997,0.143631,0.099781,0.059285,0.019680,-0.327141,-0.118945,-0.172268,0.466508,0.239092,-0.628636,-0.020534,-0.137780,0.223156,-0.142313,-0.553130,0.390727,0.067674,-0.239260,0.557708,-0.909270,0.171656,0.327965,0.452833,-0.541336,0.646832,0.342219,0.218062,-0.169397,0.017965,0.502082,0.099195,0.188088,-0.108038,-0.102187,-0.238553,0.117006,-0.365485,0.131447', '35030151', '30345227', '25858760', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3711760', '倩女幽魂', '剧情', '燕赤霞（古天乐 饰）年轻时爱上了小倩（刘亦菲 饰），但出于猎妖师的责任，他只能忍痛割爱。他没有杀小倩，而是使之失忆。他和夏雪风雷（樊少皇 饰）联手对付黑山老妖（惠英红 饰），后者牺牲了左臂封住了老妖。某日，宁采臣（余少群 饰）被派到黑山村来帮村民寻找水源。村长（徐锦江 饰）等人明知山上有妖，却没有对他道出实情。在村民铁牙（李菁 饰）的陪同下，宁采臣带着一群死囚上山找水。当他们来到兰若寺，竟然发现了水源。而他也第一次遇到了小倩。两人一见钟情。此事被黑山老妖得知，严刑拷问。燕赤霞屡次劝阻宁采臣不要陷入人妖之恋，奈何后者与小倩情深意重，明知是妖，却屡屡犯险，毫无退意。燕赤霞感到纠结，而此时黑山老妖已经开始了她的复仇……©豆瓣', '刘亦菲', '叶伟信', 5.4, 111164, 'tt1861421', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p936102091.jpg', 10, 28.9, 45.2, 11.1, 4.8, '0.210271,-0.038200,-0.665037,0.388304,-0.247884,-0.289505,0.692615,0.058993,-0.466087,-0.210338,0.355403,0.410508,-0.023322,0.077800,-0.273253,0.065846,0.020080,-0.288856,0.048952,-0.003899,-0.029299,-0.081023,-0.190878,0.026991,-0.365364,-0.034221,0.478504,0.017473,-0.130780,0.506278,0.342226,0.342046,-0.123250,0.714923,0.034803,0.277612,-0.050532,-0.111309,-0.033229,0.274342,0.092692,-0.374866,-0.415355,0.351247,-0.198461,0.671117,0.526801,-0.365289,-0.231087,-0.028751,-0.010802,-0.681631,0.033863,0.164166,0.298730,-0.289706,0.279102,0.154668,-0.086375,-0.084794,0.088498,0.175905,-0.172137,0.430674,0.239596,0.263548,-0.592978,0.302458,-0.238858,0.064568,0.044421,-0.531182,-0.007416,0.117833,0.311333,-0.020302,-0.074130,-0.287115,-0.544042,0.163107,0.737960,-0.240974,0.217906,0.115512,0.052457,-0.390098,0.182391,-0.133309,-0.134179,0.002770,0.451380,-0.000037,-0.422772,0.082777,-0.443674,-0.181216,-0.376682,0.111199,-0.169000,-0.186888,-0.011151,-0.361672,-0.153716,-0.319348,-0.399794,-0.044205,0.222499,-0.041723,0.427352,-0.846686,-0.002361,0.433273,0.302722,-0.559731,0.469379,-0.100558,-0.097198,0.014603,-0.036472,0.057214,-0.046907,0.648980,0.526484,0.281732,0.104318,-0.118280,-0.350174,-0.095464', '1308755', '1301022', '25870679', '30210700');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3715144', '烈日当空', '剧情', '故事发生在2007年的香港。在迎接08年奥运的大环境下，影片讲述一群临近中五会考的中学生之间有关成长的青春故事。一部手机短片，一连串的荒谬事件，引发了九个少男少女之间的矛盾冲突。本来的信任依赖，渐渐发展成了彼此的猜忌与摩擦。站在懵懂与长大的十字路口，这些孩子们面对着友情与爱情的双重考验。而随之而来的家庭问题和现实世界的真实残酷，九位少年又当如何应对？青春的故事有很多，影片用幽默跳脱的手法细细讲来。《烈日当空》是由曾志伟监制的两岸三地“九降风”系列同名电影的香港篇。©豆瓣', '林耀声', '麦曦茵', 7.4, 8449, 'tt1365026', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p796219488.jpg', 0.9, 4.7, 34.2, 42.9, 17.3, '0.386744,0.001219,-0.590706,0.612732,0.280993,0.202549,0.760144,0.126722,-0.424517,-0.234037,0.064576,0.595452,-0.499013,0.315864,0.197914,-0.470524,-0.166105,-0.850015,-0.173075,0.092677,-0.213789,-0.555837,-0.081149,-0.153952,-0.084238,-0.387485,0.779068,0.163268,-0.527555,0.284065,0.328865,0.123329,-0.360029,0.098986,-0.199607,-0.116659,-0.111452,0.431928,-0.465671,-0.090069,-0.108146,-0.302203,-0.380932,-0.157107,-0.197376,0.265096,0.886601,-0.250094,-0.328950,0.175533,0.790513,-0.172661,-0.281318,-0.197113,0.303947,0.300827,0.204670,0.299297,0.084005,-0.064731,-0.334587,-0.300523,-0.809810,0.000793,0.058633,0.226932,-0.501997,0.406405,0.132410,-0.250604,0.229836,-0.251410,0.158882,0.472982,0.579234,0.801602,-0.221098,0.028949,-0.159185,0.327015,0.912168,0.157351,-0.526056,0.649142,-0.386569,-0.353406,-0.526899,-0.206356,-0.585969,0.096536,0.222006,-0.092777,-0.246780,0.663874,-0.763654,0.230209,0.119212,-0.281948,0.200073,-0.517931,-0.115658,-0.679756,-0.555053,-0.629880,-0.317474,-0.182212,0.315366,-0.311657,1.316158,-0.633559,0.149061,0.547301,-0.031454,-0.539025,0.580520,0.384252,0.008345,-0.272128,-0.132393,0.222777,-0.255357,-0.165916,-0.043916,0.374923,-0.161552,0.136160,-0.434272,0.396526', '27602116', '3811356', '24284209', '26790961');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718269', '暴力街区', '剧情', '故事发生在美国底特律，不断升高的犯罪率和持续扩大的犯罪势力让警方苦不堪言，为了控制这些“不稳定的因素”，警方划出了“红砖特区”，用以隔离罪犯和平民。在特区之中，以毒枭特里梅因（罗伯特·菲茨杰拉德·迪格斯 RZA 饰）为首的犯罪集团掌控着大部分的资源和权利，构筑了一种岌岌可危的微妙平衡。一场意外让利诺（大卫·贝尔 David Belle 饰）成为了特里梅因的眼中钉，为了引出利诺，特里梅因绑架了他的女友罗拉（卡塔利娜·丹尼斯 Catalina Denis 饰），与此同时，野心勃勃的探员达米安（保罗·沃克 Paul Walker 饰）亦希望能够将作恶多端的特里梅因捉拿归案，个性迥异但境遇相同的利诺和达米安走到了一起，决定联手。©豆瓣', '保罗·沃克', '卡米尔·狄拉玛', 7.1, 80764, 'tt1430612', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2192302960.jpg', 1.3, 6.4, 41.7, 37, 13.6, '0.482068,0.030263,-0.578192,0.626162,0.013730,-0.180668,0.703433,0.514576,-0.535588,-0.130676,0.093446,0.579097,-0.100508,-0.218082,0.364073,-0.093548,-0.475648,-0.848489,-0.008287,-0.198486,-0.204970,-0.855367,-0.448580,-0.373396,-0.096401,-0.540929,0.422582,-0.078057,-0.126236,0.242313,0.137031,0.577965,-0.137295,0.206115,0.161908,0.130232,0.199624,-0.516350,-0.508552,0.327465,0.008107,0.001116,0.065876,0.255997,0.177239,0.340059,0.556447,-0.300956,0.271406,-0.081058,0.121422,-0.217932,0.018856,0.367282,0.261774,-0.206666,0.048512,0.338655,-0.334951,-0.118570,0.329399,-0.086557,-1.040453,0.134208,0.255478,0.229648,-0.556166,0.496593,-0.247267,-0.132164,-0.042351,-0.233946,0.099919,0.763811,0.322887,0.326794,0.020397,0.063562,-0.608216,-0.308987,0.499082,-0.148844,-0.447743,-0.250583,-0.526944,-0.185537,-0.354022,-0.238288,-0.398888,-0.359233,0.611871,0.026413,0.186251,0.603873,-0.561420,-0.075605,-0.364268,-0.303777,-0.291208,-0.279336,0.123703,-0.549368,-0.271864,-0.419959,0.067710,-0.025131,0.106298,-0.163552,0.419462,-0.736555,0.074834,0.682568,0.395523,-0.213262,0.251410,0.054844,0.331634,-0.356348,-0.418195,0.165243,0.244362,0.097070,0.249231,0.419066,0.067432,-0.221496,-0.135763,0.260918', '1307442', '1793491', '27009869', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718273', '滑稽戏', '剧情', '酷爱歌舞表演的女服务员艾丽（克里斯蒂娜•阿奎莱拉Christina Aguilera 饰）决定离开生活的小镇，奔赴洛杉矶追寻自己的明星之梦。然而这件事从一开始便并不那么容易，她不仅被人偷走了所有积累，而且只得到在日落大道的一家滑稽戏俱乐部作服务员的工作。因为没有钱付房租，她只好借住在极具创作天份的酒保杰克（凯姆•吉甘戴Cam Gigandet 饰）的家里。俱乐部老板苔丝（雪儿 Cher 饰）是一位面冷心热的女人，此时她正面临巨额债务和俱乐部被收购的窘境，在艾丽的多次请求下，苔丝最终决定给予她上台的机会，杰出的天份很快让艾丽很快在众多女演员中脱颖而出并成为整个俱乐部的头牌舞娘。俱乐部走到了生死存亡的关键时刻，此时小有名气的艾丽开始受到各种诱惑，在情感与名利的漩涡里，艾丽最终会做出何种决择，俱乐部将会面对什么样的命运……本片集结了克里斯蒂娜•阿奎莱拉和雪儿两位歌坛天后，华丽的歌舞场面让人叹为观止。【金球奖1项获奖】最佳歌曲“You Haven''t Seen The Last of Me”【另2项提名】最佳影片（音乐/喜剧类）、最佳歌曲“Bound to You”', '雪儿', '史蒂芬·安汀', 7.8, 18747, 'tt1126591', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p612483698.jpg', 0.6, 3.1, 26.1, 44.5, 25.8, '0.085566,0.261063,-0.626802,0.465429,-0.169147,-0.168818,0.564684,0.323593,-0.467274,-0.141591,0.256272,0.851341,-0.249098,0.195290,0.604649,-0.048130,-0.181119,-0.749811,0.040375,-0.068838,-0.199745,-0.398932,-0.103413,-0.162129,-0.233017,-0.136340,0.731761,0.043000,-0.239110,0.293082,0.480096,0.220812,0.036858,0.521404,-0.076529,0.051372,0.365970,-0.103544,-0.269601,0.499531,0.114616,-0.294446,-0.273594,0.225828,0.140895,0.062772,0.577598,-0.210053,0.110128,0.188221,0.499011,-0.227615,0.178536,-0.006361,0.097224,-0.185260,0.277646,0.085901,-0.277785,0.043878,0.043562,-0.175731,-0.736229,-0.010369,0.208233,0.117759,-0.658998,0.334983,-0.162165,0.048654,0.132374,-0.236170,-0.118115,0.337157,0.283307,0.295022,-0.054026,0.032027,-0.421356,0.279023,0.713394,0.174807,-0.305317,0.352142,-0.205835,-0.589512,-0.161847,-0.281841,-0.575902,0.028787,0.560002,0.197229,0.261082,0.112466,-0.599250,-0.059157,-0.125346,-0.434723,0.115229,-0.364230,-0.014602,-0.752817,-0.183884,-0.132273,-0.207937,-0.126704,0.092895,-0.124912,0.832389,-0.819141,0.134444,0.456177,0.100737,-0.395805,0.528652,-0.022350,0.368202,-0.021123,-0.249185,0.242507,-0.116101,0.253927,-0.077382,0.267230,0.042308,-0.247668,-0.383617,0.434373', '4301278', '3811356', '30162520', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718279', '死侍', '喜剧', '油嘴滑舌的雇佣兵韦德·威尔森（瑞恩·雷诺兹 Ryan Reynolds 饰）与俏皮可爱的瓦内莎（莫蕾娜·巴卡林 Morena Baccarin 饰）邂逅，但在爱情最美满的时刻，他被诊断患有晚期癌症，留在世上的时间所剩无几。极度绝望之际，他接受了弗朗西斯（艾德·斯克林 Ed Skrein 饰）私人组织的邀请，对其基因做了改造，以谋求体能的突变。在忍受了一系列的残酷折磨后，韦德终于治好了癌症，蜕变成拥有不死之身的超级战士，但是代价却是失去了人类的面容。狡猾的弗朗西斯逃之夭夭，而韦德却无法以恐怖的面容去面对女友。在此之后，他化身死侍，穿梭于每一个黑暗角落，寻找阿贾克斯的踪影……©豆瓣', '瑞安·雷诺兹', '蒂姆·米勒', 7.8, 439751, 'tt1431045', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2309264212.jpg', 0.5, 2.4, 25.7, 47.9, 23.5, '-0.213812,0.130208,-0.484876,0.417630,-0.250294,-0.204831,0.848962,0.145620,-0.322524,-0.240768,0.167488,0.607670,-0.029486,0.174479,0.216017,-0.227207,-0.008936,-0.512760,-0.018763,0.007114,-0.502118,-0.338446,-0.411972,-0.385103,0.006488,-0.554376,0.892479,0.140677,-0.216289,0.141456,0.324693,0.435857,0.231271,0.411096,-0.162989,0.042478,-0.042624,-0.267247,-0.149529,0.405148,0.315415,-0.131284,-0.054598,0.344609,-0.272329,0.192265,0.759780,-0.525573,-0.055024,-0.228825,0.428576,-0.245792,-0.088661,0.135842,-0.047935,-0.226124,0.160482,-0.077987,-0.276234,-0.172464,0.204240,0.062037,-1.102029,-0.028587,0.079609,0.079469,-0.452014,0.236485,-0.092846,0.100976,0.047274,-0.282996,0.012798,0.243043,0.226026,0.450519,-0.175940,-0.049532,-0.422622,0.062727,0.438293,0.006787,-0.877869,0.459691,-0.492988,-0.458279,-0.240534,-0.661252,-0.335993,-0.100927,0.266621,0.138582,-0.129317,0.406076,-0.521545,0.023554,-0.576967,-0.092461,-0.253681,-0.258035,-0.207106,-0.595291,-0.127622,-0.318498,-0.377749,0.095618,-0.183586,-0.262295,0.662219,-0.775944,0.163103,0.327587,0.052233,-0.512899,0.579812,-0.145273,0.301819,-0.150128,0.041263,0.880069,0.178724,0.265828,0.172862,0.263898,-0.110346,0.358048,-0.570218,0.680612', '10440076', '26667010', '26759820', '4927785');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718323', '韩赛尔与格蕾特：女巫猎人', '动作', '在童年时代便消灭了糖果屋女巫的孤儿兄妹韩赛尔（杰瑞米·雷纳 Jeremy Renner 饰）与格蕾特（杰玛·阿特登 Gemma Arterton 饰），多年来成为邪恶女巫的最大克星。在帮助小镇奥古斯伯格寻找失踪的孩子以及隐藏女巫之时，兄妹二人发现三天后即将出现“血月”（月蚀），这对女巫们来说是无比重要和神圣的时刻。两兄妹迅速投入行动，而讨厌他们俩的警长也招来一伙人马追查女巫们的行踪。未过多久，女巫头目（法米克·詹森 Famke Janssen 饰）率领手下袭击小镇，与兄妹二人展开正面冲突。激战过后，格蕾特遭到重创，韩赛尔也随着女巫消失下落不明。正邪的较量渐次升级，兄妹俩在这一过程中也渐渐知晓关于他们童年以及父母背后的秘密……©豆瓣', '杰瑞米·雷纳', '托米·维尔科拉', 6.1, 22332, 'tt1428538', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1759034880.jpg', 2.9, 16.7, 56.9, 18.5, 5.1, '0.194790,-0.265376,-0.668987,0.449337,0.151403,-0.176811,0.639163,-0.063345,-0.463600,-0.421754,0.116850,0.605166,-0.068127,-0.120060,0.585125,-0.167960,-0.438866,-0.592315,0.000212,-0.345629,-0.150193,-0.528548,-0.226867,-0.287680,0.013070,-0.621345,0.301551,0.148030,-0.127885,0.660816,0.376791,0.359847,-0.746306,0.300860,0.173217,0.075172,0.371217,-0.082961,-0.530850,0.261537,-0.202211,0.146301,-0.090426,-0.125416,-0.072369,0.269300,0.745283,-0.627550,-0.057376,-0.276631,0.011688,-0.505567,-0.026409,0.098613,0.672346,-0.042532,0.303282,0.343789,-0.021215,-0.146101,-0.136599,-0.106086,-0.514630,0.149158,0.293168,-0.038164,-0.544068,0.271091,0.124468,-0.102790,0.285555,-0.161606,0.317045,0.728583,0.269173,0.109019,0.024486,-0.174048,-0.423329,-0.173374,0.714386,-0.221080,-0.194791,-0.035449,0.100447,-0.312744,-0.167512,-0.152264,-0.123614,-0.031746,0.474766,0.285233,-0.021178,0.635040,-0.608369,-0.044676,-0.388471,-0.013183,0.246400,-0.402636,-0.022130,-0.969563,-0.205381,-0.397662,-0.263280,0.197858,-0.030197,-0.067624,0.655110,-0.847304,0.565238,0.199271,0.427301,-0.270052,0.368874,0.094495,0.500994,-0.319155,-0.160948,0.227267,0.413036,0.127875,0.093790,0.088280,-0.109251,0.123618,-0.129455,0.150992', '3147969', '2369613', '1306809', '1914923');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718424', '金刚狼2', '动作', '位于加拿大的深山老林，背负着永生之苦的“金刚狼”罗根（休·杰克曼 Hugh Jackman 饰）隐居于此。在一次与猎人的冲突中，他得到东瀛女子雪生（福岛莉拉 饰）的帮助。雪生是罗根二战期间的旧相识矢志田派来的下属，似乎不久于人世的老友渴望死去之间再见罗根一面。跨越重洋的罗根终于见到在虚弱的矢志田，对方希望他能够保护自己的孙女真理子（冈本多绪 饰）。随着老人谢世，葬礼上突然战火点燃。罗根在雪生的帮助下拼死救出真理子，而矢志田的儿子信玄（真田广之 饰）似乎另有所图。逃亡途中，罗根意外发现他丧失了自愈的能力，金刚狼最大的危机降临……本片根据弗兰克·米勒（Frank Miller）的原著漫画改编。©豆瓣', '休·杰克曼', '詹姆斯·曼高德', 6.6, 193449, 'tt1430132', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2151837713.jpg', 2.2, 12.5, 47, 27.6, 10.7, '-0.181278,0.085742,-0.677667,0.374714,0.151943,-0.540651,0.535481,-0.042593,-0.430575,-0.462346,0.172460,0.582150,0.043984,0.275887,0.230412,-0.127911,-0.122807,-0.417875,-0.120927,0.145719,-0.414352,-0.183946,-0.505457,-0.340994,-0.251183,-0.328050,0.732251,0.339080,-0.285995,0.376346,0.209063,0.555727,-0.202723,0.319103,-0.213986,0.099376,-0.320680,0.045510,-0.552399,0.097788,-0.038131,-0.107477,-0.196168,0.071153,-0.084591,0.327532,0.646830,-0.541313,-0.058696,-0.290775,0.404677,-0.247711,0.008492,-0.082213,0.252855,0.028076,0.048607,0.175127,-0.050275,-0.200316,-0.026832,-0.170656,-0.477422,-0.233447,0.106804,0.209961,-0.358996,0.382853,-0.092638,0.119413,0.259621,-0.230229,-0.062862,0.339656,0.251042,0.180117,-0.242665,0.104697,-0.347139,0.066753,0.503455,-0.051353,-0.120257,0.138174,-0.228941,-0.480161,-0.111328,-0.154254,-0.313602,-0.075205,0.466670,0.162022,-0.075090,0.313608,-0.260796,-0.333846,-0.317939,0.257098,0.047680,-0.129852,-0.074965,-0.566569,-0.015080,-0.358572,-0.127307,0.187096,0.117716,-0.299535,0.580684,-0.655564,0.511362,0.374787,0.171741,-0.083711,0.485535,0.023029,0.139590,-0.353972,-0.086771,0.681852,0.103248,0.245109,0.210430,0.006190,-0.056990,0.205002,-0.349590,0.474131', '2383207', '1482099', '2369613', '4889554');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718447', '三枪拍案惊奇', '喜剧', '荒漠中的麻子面馆，风情万种的老板娘（闫妮 饰）向波斯商人订购了一把左轮手枪，后者还展示了大炮的威力。炮声引来了巡逻队，老板娘跟情人李四（小沈阳 饰）将枪藏匿后，插科打诨，好饭招待，这才稳住了精明的队长（赵本山 饰）。队长的得力助手张三（孙红雷 饰）知悉老板娘与李四的暧昧关系，但未说破。原来，他跟老板（倪大红 饰）之间还有勾当。店员六暗恋店员七，二人被老板克扣工钱，同命相连，六曾试图向老板讨薪，惨遭痛骂。老板怀疑老板娘偷人，并对她动用死刑。密室中，张三告知老板真相，老板听后，怒不可遏，前去痛扁二人，被老板娘用手枪喝退。事后，老板与张三密谋买凶杀人，由此引发一场令人啼笑皆非的血案……本片改编自科恩兄弟的电影《血迷宫》，为张艺谋继奥运会开幕式后首度执导贺岁喜剧。©豆瓣', '小沈阳', '张艺谋', 4.7, 113199, 'tt1428556', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p776980060.jpg', 21.7, 34.3, 32.9, 8.1, 3, '-0.086879,-0.146255,-0.189268,0.204937,0.137051,-0.303633,0.774376,0.127608,-0.239102,-0.063371,0.307983,0.434213,-0.506122,-0.123142,0.323699,-0.064990,-0.078704,-0.664920,-0.149868,-0.069011,0.070173,-0.273435,-0.109680,-0.204688,-0.151671,0.127747,-0.077603,-0.078156,-0.279650,0.366590,0.511528,0.087631,-0.295977,0.159952,-0.033441,0.247763,0.099871,-0.030083,-0.486751,-0.004516,-0.079530,-0.302281,-0.194959,0.100721,0.066686,0.505224,0.453200,-0.198288,-0.083572,-0.165555,0.043431,0.092663,-0.023201,0.173664,0.323653,0.170809,0.357234,-0.005525,-0.166326,0.043880,0.109032,0.068102,-0.308247,0.345200,0.055568,-0.199355,-0.490351,0.051684,-0.214144,0.077271,0.056036,-0.202473,0.268085,-0.098131,0.452632,0.107874,0.193275,0.161072,-0.462522,0.283922,0.215512,0.036252,0.424096,0.144357,0.282241,-0.221587,-0.062796,-0.001277,-0.389750,0.247191,0.478590,-0.137808,0.227324,-0.070573,-0.735774,-0.310534,-0.258279,0.004107,0.022984,-0.132665,-0.228830,-0.646776,-0.134011,-0.186179,-0.000076,-0.142329,0.484157,-0.021986,0.338597,-0.332583,-0.106572,0.144351,0.302748,-0.378006,0.358274,0.032944,-0.018788,-0.239285,-0.332955,-0.551802,0.366816,0.250666,0.440979,0.391342,-0.130521,-0.517277,0.074089,-0.012580', '1578663', '10466639', '1394176', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718457', '亚瑟·圣诞', '剧情', '每年的圣诞节前夕，圣诞老公公的馈赠是全世界儿童最大的期盼。时至今日，圣诞老人也与时俱进，现役圣诞老人马尔科姆（Jim Broadbent 配音）乘坐最先进的S1飞行器，与成千上万的小精灵在圣诞夜飞遍全世界，给数亿儿童送去礼物。而他的长子史蒂夫（Hugh Laur ie 配音）则坐镇位于北极的中央控制室，通过最先进的设备指挥礼物的发放工作。崇尚技术的史蒂夫坚信自己将成为下一年的圣诞老人，无奈父亲老当益壮，丝毫没有退休的意思。可惜百密一疏，今年居住在英国某郡的小女孩没能收到礼物。被父亲称为麻烦精的亚瑟（James McAvoy 配音）不忍女孩失望，于是和他那丝毫不服老的爷爷——上一代圣诞老人（Bill Nighy 饰）乘坐被封存在仓库里的雪橇踏上补送礼物的征程。距离天亮还有两小时，亚瑟和爷爷争分夺秒向英国冲刺……本片荣获2012年安尼奖最佳配音奖（Bill Nighy）。', '詹姆斯·麦卡沃伊', '莎拉·史密斯', 7.6, 11636, 'tt1430607', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1319489055.jpg', 0.4, 2.9, 32.4, 45.2, 19.1, '0.129699,0.030632,-0.710705,0.497340,-0.101204,-0.160588,0.426285,-0.085794,-0.349827,-0.265536,0.174126,0.759336,0.074942,0.115774,0.207779,-0.104363,-0.344996,-0.196609,-0.098667,-0.264110,-0.323602,-0.524823,-0.165315,-0.009523,0.042349,-0.239308,0.443907,-0.076176,0.039358,0.559397,0.350396,0.040303,0.144713,0.287295,-0.486321,-0.090285,0.190647,-0.134163,-0.158490,0.343122,-0.131497,-0.207312,0.123350,0.044497,0.184681,0.204357,0.635764,-0.199436,-0.028483,0.020988,0.389565,-0.249375,-0.125642,0.093346,0.059876,0.184679,-0.033418,0.078747,-0.172451,0.170130,0.025431,-0.301189,-0.631810,0.012170,-0.072496,-0.025118,-0.728659,0.637137,-0.154239,0.057561,0.302297,-0.498971,0.420052,0.225162,-0.061397,0.479854,-0.096490,0.370028,-0.375018,0.364680,0.376992,-0.125078,-0.010647,0.188468,-0.091403,-0.413698,0.207389,-0.359345,-0.593326,0.042254,0.176382,0.059325,0.153491,-0.023392,-0.589556,0.030448,-0.022491,-0.654567,0.157060,-0.387078,-0.076834,-0.775856,0.431985,-0.292702,-0.065842,0.149280,0.349651,-0.306207,0.849403,-0.479607,0.315063,0.376912,0.444591,-0.280401,0.926436,-0.000657,0.087182,-0.369474,-0.102415,0.077421,0.085373,0.314965,0.059196,0.166280,0.014527,-0.264004,-0.492351,0.487131', '1870681', '25951736', '1306860', '1308609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718460', '巴尼的人生', '剧情', '该片改编自加拿大作家Mordecai Richler1997年的同名传记体小说。男主角保罗·吉亚玛提曾获第68届金球奖最佳男主角奖项。巴尼·潘诺夫斯基（保罗·吉亚玛提 Paul Giamatti 饰）是一个电视导演，同时又是一个曲棍球爱好者。酗酒、抽烟、言语粗俗，这些缺点无一例外跟随着他。65岁之时，他开始追忆自己的一生。他遇过不同的女人：第一任妻子克拉拉（蕾切尔·李费佛 Rachelle Lefevre 饰）相信自由的灵魂。第二任P夫人（明妮·德里弗 Minnie Driver 饰）是个富有的犹太人。第三任妻子米利亚姆（罗莎曼德·派克 Rosamund Pike 饰）美丽贤惠。而保罗与父亲伊西（达斯汀·霍夫曼 Dustin Hoffman 饰）的关系似乎缺少一种真正的亲情。暮年的他，回忆起过往的种种，又会是怎样一种情绪......©豆瓣', '保罗·吉亚玛提', '理查德·J·刘易斯', 8.3, 9938, 'tt1423894', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1150554855.jpg', 0.3, 1.3, 16.3, 49.8, 32.3, '0.257613,-0.112982,-0.470021,0.715327,-0.113888,-0.366002,0.935796,0.130717,-0.579405,-0.384189,0.079330,0.894650,-0.222651,0.164764,0.177188,0.206601,-0.225881,-0.591383,0.245729,-0.248513,0.260722,-0.528047,-0.471391,0.102868,-0.058251,-0.503727,0.404537,-0.389274,0.027202,0.350069,0.538897,0.487060,0.354369,0.158972,0.051056,0.117777,0.227696,-0.144158,-0.240683,-0.000338,0.009075,-0.002490,-0.230493,0.104197,-0.131873,0.245983,0.580155,-0.162552,0.119623,-0.112115,0.595113,0.150449,0.019739,0.068234,0.048859,-0.196337,0.251626,0.281330,0.117893,-0.139869,0.156477,0.047378,-0.575255,-0.218672,-0.022308,0.426814,-0.253499,0.128397,-0.422699,-0.049542,-0.026671,-0.134413,-0.069810,0.040033,0.308879,0.212106,-0.029992,-0.130403,-0.194284,0.544546,0.413948,0.080055,-0.544215,0.522336,-0.500197,-0.372246,-0.105439,-0.247344,-0.844151,0.104297,0.295924,-0.120386,0.185343,0.451846,-0.439378,-0.100318,-0.209115,-0.032456,0.045306,-0.288534,0.014535,-0.423206,-0.304666,-0.482767,-0.137531,-0.381548,0.165027,-0.347851,0.819348,-0.560453,0.376061,0.518655,-0.008549,-0.266965,0.587884,0.272607,-0.004674,-0.263060,-0.006231,0.717271,-0.027172,-0.261149,-0.372416,0.412044,0.217485,-0.061094,-0.184486,0.586783', '26348103', '1296