INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718493', '终极快递', '喜剧', '《终极快递》是法国电影大师吕克·贝松自《的士速递》系列后有意打造的又一个系列飙车电影。山姆（迈克尔·扬 Michaël Youn 饰）是一个信使。他每日飞车穿过巴黎，常常无视交通的基本规则。他必须出席婚礼以试图挽救与女友纳迪娅（杰拉尔丁·纳卡什 Géraldine Nakache 饰）的关系，然而这天他没有选择地只能接受他的老板紧急差事，去送一个快件。为了完成任务他不得不扮演罪犯的帮凶，将价值连城的珠宝送至巴黎市中心的豪华酒店。当他一身快递装扮进入大厅时，前台经理有些嗤之以鼻，但在山姆报上名号后，经理态度则180度大转弯，令人忍俊不禁。山姆也没有想到自己能入住总统套房，而在房间里还有一位美女等着他.......©豆瓣', '迈克尔·扬', '埃尔韦·雷诺阿', 6.5, 8595, 'tt1429429', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p736801777.jpg', 2.2, 10.2, 54.4, 27.6, 5.6, '0.174616,0.159830,-0.431350,0.600402,-0.213972,-0.253160,0.547707,0.274198,-0.410798,-0.435663,0.269143,0.942599,-0.201713,0.083196,0.497622,0.147985,-0.351781,-0.263262,-0.122948,-0.219611,-0.169865,-0.534965,-0.030635,-0.285721,-0.042968,-0.056440,0.204914,-0.121776,-0.072543,0.260833,0.590709,0.080898,-0.199480,0.522892,-0.214235,-0.219870,0.279487,-0.106984,-0.231901,0.405401,0.115406,-0.044509,-0.104451,0.184999,0.224069,0.282506,0.567738,-0.074441,-0.116051,0.084163,0.428013,-0.080863,0.131651,-0.115775,-0.007193,0.005919,0.207524,0.084332,-0.228683,0.039364,0.304491,-0.173029,-0.663223,0.036787,0.004619,-0.147848,-0.439290,0.288099,-0.567339,0.107755,0.024947,-0.576571,0.183277,-0.029295,0.266623,0.267226,0.117311,-0.052716,-0.700555,0.221482,0.432234,0.173880,-0.040217,0.381966,-0.270867,-0.417639,-0.034479,-0.078796,-0.427032,0.116661,0.188849,0.032721,0.177377,-0.310039,-0.407947,-0.278498,-0.336745,-0.340021,0.034616,-0.289615,-0.126502,-0.810259,0.225257,-0.055794,-0.095286,-0.085459,0.126418,-0.052831,0.308765,-0.727370,-0.053294,0.444589,0.196644,-0.481982,0.887193,-0.011681,0.198308,-0.243961,-0.115330,-0.026462,0.201276,0.492477,0.084810,0.483096,0.061013,-0.350105,-0.225108,0.425777', '1829654', '1308842', '2973543', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718665', '诈欺游戏 电影版', '剧情', '大学生神崎直（戸田恵梨香饰）某日不慎被卷入一个名为Liar Game的可怕游戏，游戏方式是对手们相互欺骗来获得巨额奖金。小直信奉着“人性本善论”，游戏过程中，不管遭遇多少谎言和背叛，她都以最诚挚的态度对待每个人。另一参赛者天才诈欺师秋山深一（松田翔太饰）凭借着他的天才智慧脱颖而出，也护佑着小直一次次化险为夷，逃出劫数。Liar Game决赛举行，11位参赛者巅峰对决。此次的主题是“伊甸园的果实”，只要集满红苹果，全员都能获胜，否则众人将面临被流放失乐园的悲惨境地。有多少人性的弱点将被暴露出来？秋山将使出怎样的天才招数力压群雄？小直的美好信念能帮助大家逃出Liar Game的生天，还是会再次被残酷的现实击溃？©豆瓣', '户田惠梨香', '松山博昭', 7.9, 31650, 'tt1423953', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2243119390.jpg', 0.7, 2.5, 23.2, 47.5, 26.1, '-0.122896,0.469121,-0.314992,0.477546,-0.173428,0.257350,0.209248,-0.031813,-0.392972,0.072523,0.354380,0.682791,-0.278366,-0.001667,0.166426,-0.245179,0.217446,-0.606556,-0.245318,-0.032721,-0.512035,-0.319571,-0.177315,0.057312,-0.132768,-0.278921,0.601957,0.286188,-0.468230,-0.000214,0.420858,0.528377,-0.083422,0.264826,0.013182,-0.097092,0.047061,0.066876,-0.355299,0.438844,-0.434368,-0.163476,-0.277571,0.348176,-0.159268,0.027130,0.687821,-0.290598,-0.009526,-0.137782,0.430945,-0.533953,-0.342736,0.375957,0.276054,-0.074119,0.152397,0.289658,0.258247,0.236791,0.131477,-0.158146,-1.238021,-0.312017,0.177010,-0.087874,-0.324975,0.227282,0.065262,-0.050779,0.064468,-0.017286,-0.071497,0.178075,0.566856,0.105795,-0.259694,-0.170360,-0.529708,0.114706,0.778306,-0.223352,-0.357635,0.068762,-0.136349,-0.557997,-0.129696,-0.843439,-0.284937,0.122049,0.447694,0.222082,-0.115659,0.336812,-0.485702,0.055538,-0.124030,-0.257223,0.127353,-0.452140,-0.083746,-0.286711,-0.068988,-0.216287,-0.752659,0.113380,0.223882,-0.517932,1.272282,-0.761636,-0.018529,0.616673,0.266657,-0.239703,0.510161,0.218171,0.023575,-0.019988,-0.110774,0.332665,0.157919,0.252960,0.138540,0.200015,-0.321423,-0.022448,-0.215961,0.480080', '27602116', '24284209', '30163500', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718678', '拉芙蕾丝', '传记', '本片主要讲述《深喉》女主角Linda Lovelace在拍摄《深喉》前后的生活。Linda Boreman（阿曼达·塞弗里德 Amanda Seyfried 饰）本来是弗罗里达州一个普通少女，然而她的人生在遇见酒保Chuck Traynor（彼得·萨斯加德 Peter Sarsgaard 饰）后完全改变了。两人沉浸在疯狂激烈的性爱游戏中不可自拔，Linda离家出走与Chuck结了婚。不久Chuck被捕入狱，两人陷入金钱危机中，于是Chuck强迫Linda去拍摄色情片赚钱。Chuck把Linda介绍给电影人Nat Laurendi和Anthony Romano，并通过一段自制视频展现了Linda的特殊技能。Linda开始拍摄电影《深喉》，这部电影后来成为色情电影史上的奇迹，Linda也因此一炮而红，改名为Linda Lovelace。然而伴随着成名而来的却并非Linda一帆风顺的人生......', '阿曼达·塞弗里德', '罗伯·爱泼斯坦', 6.3, 11137, 'tt1426329', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2036619897.jpg', 1.4, 12.2, 60, 21.2, 5.2, '0.225290,0.119290,-0.518197,0.563916,0.215805,-0.086623,0.733731,-0.020390,-0.398273,-0.265383,-0.019224,0.637105,-0.482350,0.004348,0.422435,-0.259825,-0.568372,-0.704204,0.009272,-0.044022,0.039013,-0.273915,-0.249732,-0.020374,-0.061319,-0.430085,0.826584,-0.037222,-0.553837,0.534470,0.246716,0.262761,-0.198994,0.229866,0.210170,0.195351,-0.008515,-0.015151,-0.525529,0.341076,0.125872,-0.343813,-0.059065,0.092687,0.061079,0.299260,0.749282,-0.357371,-0.051319,0.219198,0.723680,-0.299100,-0.372010,-0.054311,-0.084877,0.251132,0.353901,0.097055,-0.195566,0.284173,-0.241064,-0.242272,-0.887595,-0.029217,-0.022759,-0.028248,-0.342732,0.296256,-0.027162,-0.044518,0.238732,-0.127671,0.158845,0.291109,0.561082,0.381892,-0.213972,0.026083,-0.490973,0.589178,0.710685,-0.043290,-0.357145,0.674771,0.171814,-0.371862,-0.227948,-0.201425,-0.517191,0.157739,0.281148,0.119572,-0.235853,0.255418,-0.534137,0.073274,-0.216260,-0.312191,0.177889,-0.360811,-0.345213,-1.046332,-0.367400,-0.171606,-0.242518,-0.446056,-0.080233,-0.559279,0.601584,-0.616375,0.251828,0.543021,0.132429,-0.159190,0.710248,0.029936,0.391859,-0.151942,-0.095058,0.452406,0.144132,0.148333,0.052421,0.117385,-0.153256,0.028465,-0.453747,0