INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718709', '神奇海盗团', '喜剧', '19世纪，大不列颠帝国雄霸海上，维多利亚女王骄扬跋扈（伊梅尔达·斯汤顿 Imelda Staunton 配音），但是横行四海的海盗仍令她愤恨不已。这群不法之徒中，海盗船长（休·格兰特 Hugh Grant 配音）则显得有些寒酸，他手下跟着一帮老弱病残，每次打劫虽然斗志昂扬，却总是了无所得。这一天，他在血色之岛上受到了业内高手黑鬼贝拉（杰里米·皮文 Jeremy Piven 配音）和弯刀莉兹（萨尔玛·海耶克 Salma Hayek 配音）等人的嘲笑。为了证明实力，赢得年度海盗大奖，船长开始四处劫掠，结果意外结识了生物学家达尔文（大卫·田纳特 David Tennant 配音）。达尔文发现，船长的宠物竟然是早已灭绝的渡渡鸟。于是他花言巧语劝诱船长去伦敦参加年度科学家大赛，而船长也离他的海盗之路越来越远……本片为英国阿德曼公司首部3D粘土停格动画。©豆瓣', '休·格兰特', '彼得·洛伊德', 7, 11173, 'tt1430626', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1549478974.jpg', 1, 6.2, 46.1, 35.5, 11.2, '-0.135754,-0.174242,-0.582483,0.424249,0.159400,-0.407149,0.513027,-0.151840,-0.376186,-0.150290,0.156577,0.642643,-0.122472,0.056057,0.307450,0.011569,-0.512468,-0.191933,-0.083613,-0.176986,0.309607,-0.106819,-0.225423,-0.302781,-0.228110,-0.354947,0.673578,-0.018829,-0.064882,0.531745,0.234274,0.022700,0.050676,0.389529,-0.012145,0.019216,0.428123,-0.258787,-0.023227,-0.057047,-0.105639,-0.097302,-0.185472,0.072873,0.004474,0.337517,0.460511,-0.192360,0.162074,-0.357143,0.231290,-0.502195,0.098408,-0.187879,0.447994,-0.211919,0.220740,-0.106081,0.327227,-0.138488,-0.062555,0.029651,-0.412833,0.272584,-0.002183,0.227629,-0.100971,0.219785,-0.273302,0.191246,-0.176405,-0.216515,0.140821,-0.195606,0.324240,-0.017038,0.150546,0.124589,-0.423196,0.268522,0.510449,-0.073139,-0.154033,-0.024991,0.018651,-0.561869,0.171418,-0.597108,-0.350976,-0.057975,0.225208,-0.462580,0.045161,0.395320,-0.550242,0.084169,-0.302030,-0.225089,-0.245390,-0.169727,0.090499,-0.704644,0.254894,-0.126146,-0.001385,-0.012978,0.348526,-0.176163,0.424978,-0.562769,0.082109,0.648930,0.338079,-0.228175,0.316663,-0.135117,-0.001023,0.016936,-0.259488,0.069274,0.199845,0.285540,0.073192,0.182157,0.246728,-0.591319,0.067188,0.333313', '20274039', '317877