INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3718782', '又一年', '剧情', '工程师Tom（吉姆·布劳德本特 Jim Broadbent 饰）和心理咨询师Gerri（鲁斯·西恩 Ruth Sheen 饰）是一对生活在伦敦的中年夫妻。单身女性Mary（莱丝利·曼维尔 Lesley Manville饰）是Gerri的同事。春天，Gerri邀请Mary来到家中吃饭，Mary告诉他们，她正存钱买一辆汽车，当晚Mary喝醉了，在Gerri家过了一夜，早晨遇见了Tom和Gerri的儿子Joe（奥利弗·莫尔特曼 Oliver Maltman 饰）。夏天，Mary终于买下了一辆二手汽车，她来到Gerri家参加一次朋友聚会，又遇到了Tom的老朋友Ken（彼得·怀特 Peter Wight 饰），然而同样孤独的Mary对Ken的求爱只感到了恐慌。秋天，Joe把他的女朋友Katie（卡瑞娜•费尔南德斯 Karina Fernandez 饰）带回了家，碰巧Mary也来了，她看见Joe和他的女朋友，心里很不是滋味。冬天，Tom的哥哥Ronnie（大卫·布拉德利 David Bradley 饰）的妻子去世了，参加完葬礼的Tom邀请他来伦敦住几天。心情糟糕的Mary想找Gerri，碰上了独自看家的Ronnie。两人言不由衷地聊了一会，后来Tom和Gerri回来了，在餐桌上，大家又开始聊天，Mary却感到了寂寞......', '吉姆·布劳德本特', '迈克·李', 8, 14263, 'tt1431181', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p648233277.jpg', 0.5, 1.9, 21.1, 50.7, 25.7, '0.428138,-0.302499,-0.564957,0.211989,-0.179728,-0.603370,0.607465,0.340563,-0.575316,-0.281486,0.065467,0.929638,-0.385297,0.568765,0.563231,0.189595,-0.415516,-0.389663,0.358025,-0.168898,-0.126999,-0.404661,-0.002788,-0.144800,0.283302,-0.212838,0.101456,-0.075494,0.305242,0.726951,0.215263,0.198254,0.210733,0.605204,-0.457963,0.031755,0.192185,0.125695,-0.178701,0.177892,0.035860,-0.186862,-0.087434,0.039173,0.375553,0.298770,0.479657,0.169792,-0.124867,0.084554,0.174479,-0.087748,0.104292,-0.113763,0.315247,0.017328,0.387489,0.090906,-0.187299,0.018349,-0.117430,-0.038303,-0.196469,0.590832,-0.096180,-0.083282,-0.813887,0.671506,-0.293352,-0.174031,0.127920,-0.500315,0.543454,0.407488,-0.015303,0.629408,0.093055,-0.004605,-0.651191,0.209060,0.914924,-0.056822,0.223928,0.446992,0.075353,-0.227687,0.221905,-0.006745,-0.459531,0.070488,0.259968,-0.136573,-0.281820,-0.103382,-0.773622,-0.081761,-0.275114,-0.242290,0.213502,-0.319786,-0.002766,-0.676243,0.125481,-0.282362,-0.371599,0.092863,0.010477,-0.055684,0.331548,-0.918008,0.255837,