INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3725295', '断线', '剧情', '虚拟的社交网络连了线，真实的人际关系却断了线。聊天室的每句对话、脸书上的一张照片一条短片，背后隐藏着人渴望与人接触的欲望，但却分分钟带来不堪设想的后果。日理万机的大律师无暇与家人相处沟通，直到儿子出事才悔恨爱得太迟；一对婚姻枯燥无味的夫妇各自在网上寻求慰藉，但网络世界何来秘密；孤僻宅男网上会女神，原来一直被玩更误堕色欲陷阱；顽童网上欺凌同学，乐极生悲；女记者为爆独家猛料，故意接近未成年色情网男模，道德界线难划清。几条故事线纠缠交错，每个荡失于虚拟世界的主人翁，只是渴望找到与人真正的联系和沟通。', '杰森·贝特曼', '亨利·亚历克斯·鲁宾', 8, 21469, 'tt1433811', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1885248563.jpg', 0.3, 1.8, 20.6, 53.1, 24.3, '0.477054,-0.011494,-0.378155,0.559854,0.087536,-0.162017,0.397012,0.076976,-0.568208,0.026582,0.005366,0.334397,-0.619790,0.028894,-0.065164,0.009890,-0.212550,-0.824231,0.038900,-0.231044,-0.074962,-0.371610,-0.176230,-0.188063,-0.105221,-0.272467,0.643850,0.029111,-0.308255,-0.010300,0.290615,-0.062442,-0.566760,0.178095,-0.056566,-0.239361,-0.097255,0.113275,-0.275753,-0.268676,-0.132523,0.099059,0.073262,0.050462,-0.085109,0.245081,0.651371,-0.205916,-0.211945,0.096037,0.575408,-0.195667,-0.077917,0.120186,0.422678,0.061871,0.671280,0.181182,-0.040244,-0.155299,0.035417,-0.003471,-0.706664,-0.071540,0.038040,0.370668,0.004009,0.388536,-0.156181,-0.031875,0.040167,-0.052371,0.215193,0.013897,0.401674,0.317282,-0.064072,-0.057968,-0.104909,0.311594,0.536588,0.101369,-0.423711,0.297762,-0.174295,-0.149519,-0.317232,-0.166233,-0.573574,-0.045370,0.412468,0.004912,-0.546105,0.483868,-0.634210,0.224623,-0.079557,0.360989,0.129924,-0.609634,-0.123454,-0.648558,-0.499307,-0.261173,-0.064989,0.127922,0.273446,-0.111604,0.919267,-0.695868,0.096451,0.551807,0.366846,-0.515337,0.916546,0.328681,-0.215394,-0.325075,0.074612,0.240182,0.170300,0.078894,-0.034015,0.006503,-0.302211,-0.003422,-0.281710,0.269171', '4301278', '27602116', '25863940', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3725320', '极速复仇', '动作', '经历了长达十年常人难以想象的牢狱生活，绰号“司机”的男子（“巨石”强森 Dwayne Johnson 饰）重返自由。但是他并不想就此展开平静的日子，而是迅速向当年的仇人展开血腥复仇。十年前，司机和哥哥加里等人打劫银行，并凭借其出色的车技成功摆脱警察的追捕。然而他们却遭到另一伙人的暗算，现金被一抢而空，哥哥和伙伴们遭到杀害，司机也鬼门关前走上一遭。凭借手中的资料，司机逐一展开报复。与此同时，手法干练的杀手（奥利弗·杰森·科恩 Oliver Jackson-Cohen 饰）和即将退休的警察（比利·鲍勃·桑顿 Billy Bob Thornton 饰）也紧随司机的脚步。三个人展开了一场极速的生死追逐战……©豆瓣', '道恩·强森', '小乔治·提尔曼', 6.3, 18380, 'tt1433108', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1086821153.jpg', 1.9, 13.8, 56.4, 21.4, 6.4, '0.073492,-0.265626,-0.283468,0.469460,-0.112540,-0.389087,0.776350,-0.063729,-0.580736,-0.198322,0.262186,0.547094,0.111999,-0.016677,0.524559,-0.225422,-0.363533,-0.802168,-0.081550,0.025816,-0.207741,-0.200053,-0.116160,-0.259468,0.065891,-0.297649,0.565205,-0.015186,0.118197,0.737807,0.230521,0.147174,-0.367356,0.289847,-0.027195,0.137742,0.093860,-0.021348,-0.575282,0.085929,-0.079157,-0.440484,-0.034359,0.039526,-0.198694,0.295329,0.511266,0.042462,-0.190030,-0.197615,0.148740,-0.341541,-0.097251,0.071598,0.287803,0.193664,0.091542,0.311568,0.007369,-0.151495,-0.059075,-0.202545,-0.491507,0.269232,-0.207891,-0.198884,-0.539715,0.394610,-0.273514,0.369260,-0.096620,-0.231826,-0.133082,0.132460,0.288700,0.029075,-0.246480,-0.149759,-0.448821,0.005049,0.631469,0.042013,-0.122725,0.197355,0.061944,-0.378093,-0.246858,-0.285817,-0.302549,0.061161,0.483345,0.216251,-0.256534,0.239240,-0.555881,0.066231,-0.477150,-0.019719,-0.135285,-0.200177,-0.167427,-0.778773,0.093129,-0.241044,-0.284021,0.154959,-0.114890,-0.160121,0.410696,-0.353978,0.283297,0.377724,0.344121,-0.408874,0.443890,-0.352774,0.221587,-0.243757,-0.151791,0.298830,0.377018,0.550478,0.181163,0.187656,-0.191417,-0.032548,0.006798,0.485508', '10466639', '11541282', '1292050', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3726986', '十三刺客', '动作', '已是江户时代后期，时有明石藩江户之家老间宫图书（内野聖陽 饰）在幕府老中土井大炊头（平幹二朗 饰）的宅前自杀，此举引起朝野震动。一切皆由明石藩主齐昭（稲垣吾郎 饰）而起。齐昭系现任将军的异母弟弟，其人嗜血如命、暴虐无常，引起朝廷上下诸多人等的不满，然齐昭已内定成为下任老中。为免苍生遭其荼毒，土井授意岛田新作卫门（役所広司 饰）在齐昭回藩途中予以刺杀。新左卫门召集了仓永左平太（松方弘樹 饰）、三桥军次郎（沢村一樹 饰）、平山九十郎（伊原剛志 饰）等13名刺客，在齐昭的必经之地布下层层埋伏……本片翻拍自工藤荣一1963年同名经典名作，新版剧本由著名导演今村昌平之子天愿大介担任，该片荣获2010年日本电影旬报十佳影片第4名。©豆瓣', '役所广司', '三池崇史', 7.7, 17085, 'tt1436045', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p656541463.jpg', 0.5, 2.6, 25.4, 52.3, 19.2, '-0.289337,-0.026248,-0.341713,0.317940,0.628048,0.051869,-0.022114,0.526885,-0.453381,-0.504684,0.269810,0.441373,-0.127515,0.093754,0.435144,-0.081296,-0.147789,-0.450494,-0.278788,-0.376731,0.009817,-0.230222,0.101745,0.071942,-0.448951,-0.336209,0.588855,0.105676,-0.047075,0.319490,0.552170,0.662635,-0.157642,0.021537,0.218175,0.316345,0.188886,-0.329634,-0.090085,0.149064,-0.655624,-0.353644,-0.402497,-0.026902,0.125237,0.326788,0.633780,-0.383097,-0.060257,-0.377278,0.286511,0.067141,-0.264480,0.171334,0.696023,0.123324,-0.000304,0.644773,-0.338992,0.069640,-0.073445,-0.048498,-0.472959,-0.064070,0.380947,0.125784,-0.015959,0.031619,-0.172557,-0.085367,-0.002325,-0.110787,-0.088470,0.184646,0.374510,-0.144795,-0.132998,0.207343,0.117565,0.445074,0.333219,-0.114705,-0.029648,-0.094790,0.377549,-0.158368,-0.170248,-0.399497,-0.311085,0.055992,0.137610,-0.188750,0.443454,0.232352,-0.164913,-0.331576,-0.145534,-0.053984,0.372453,0.269570,-0.132742,-0.454118,0.036359,-0.208960,-0.167786,0.131300,0.372013,0.052055,0.682928,-0.426721,-0.058812,0.293477,0.016355,-0.199022,0.319491,0.068599,-0.215524,0.002522,-0.053780,-0.178611,0.510770,0.351622,0.060687,0.204968,-0.323692,-0.401736,-0.132669,-0.145597', '25912924', '2065021', '3811356', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3727603', '歇斯底里', '喜剧', '本片根据真人真事改编。怀抱着救人理念的年轻医生莫蒂默（休•丹西 Hugh Dancy 饰）因为和许多医院的经营理念不合，数度被辞退。在寻找工作的过程中，找到了达尔林善尔医生的诊所。这是一家专门服务女性，治疗学名为“歇斯底里症”疾病的地方。莫蒂默在这里学会了手指按摩法，也在这邂逅了医生的2位性格迥异的女儿。姐姐夏洛蒂（玛吉•吉伦哈尔 Maggie Gyllenhaal 饰）是位女权主义者，开着救济所；而妹妹艾米丽（菲丽希缇•琼斯 Felicity Jones 饰）则是位大家闺秀。医院的生意越来越好，却让莫蒂默的手吃不消。因一次手痉挛，莫蒂默没能让一位顾客得到满意，因此被医生扫地出门。回到朋友埃德蒙（鲁伯特•艾弗雷特 Rupert Everett 饰）家中，看到其发明的电动鸡毛掸，莫蒂默产生了一个奇妙的想法。而这个想法给女性们带来福音和欢乐，无形中也支持着女性的解放。一出充满趣味和爱意的故事就此上演。', '玛吉·吉伦哈尔', '谭雅·维克斯勒', 7.2, 8597, 'tt1435513', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1528645929.jpg', 0.4, 3, 43.8, 42.9, 10, '0.232744,-0.029310,-0.463850,0.517603,-0.104385,-0.415085,0.901195,0.235127,-0.451966,-0.453711,-0.007389,0.565198,-0.094487,0.391749,0.577678,0.042082,-0.294939,-0.429746,0.065592,0.084167,-0.383484,-0.444863,-0.030693,-0.362945,-0.120751,-0.518459,0.254934,-0.012462,-0.348863,0.491143,0.241344,0.659470,0.093531,0.375487,-0.119013,0.018662,0.194624,-0.064787,-0.272358,0.229529,0.450089,-0.104015,-0.148509,0.154566,0.088463,0.344457,0.551040,-0.132147,-0.076382,-0.095011,0.386905,-0.053894,0.344072,0.006393,0.192120,0.120717,0.269224,-0.151620,-0.284126,0.223475,0.297827,-0.241364,-0.648537,-0.039077,0.214193,0.162144,-0.688144,0.265291,-0.220408,-0.234094,-0.170238,-0.289940,0.247117,0.053754,0.425477,0.427861,-0.194573,0.205078,-0.677845,-0.111027,0.323303,0.180679,-0.002674,0.296676,-0.454048,-0.612104,0.106421,-0.142015,-0.476899,-0.122341,0.330993,-0.158000,0.042579,0.266706,-0.343198,-0.347021,-0.236622,-0.285471,-0.066998,-0.448246,0.063986,-0.485987,0.023837,-0.219974,-0.173455,-0.081845,0.261580,-0.160850,0.761543,-0.657603,0.158426,0.352869,0.106430,-0.422249,0.613904,0.067685,0.209947,-0.325144,-0.303782,0.254473,0.224412,0.178520,0.488653,0.524468,0.065041,-0.063984,-0.394436,0.64717