INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3727653', '重力小丑', '剧情', '清洗墙壁涂鸦的春（冈田将生 饰）无意中发现了多处涂鸦，这些涂鸦与最近在仙台发生的多起纵火案件有着千丝万缕的联系，总是出现在纵火案现场附近。觉得暗藏玄机的春找来了哥哥泉水（加濑亮 饰）商量，二人作为秘密侦探开始跟踪这系列纵火案。与此同时，24年前某案件的犯人（渡部笃郎 饰）刑满释放。看似没有联系的两起案件，背后却紧密交织着。随着案件的深入，被掩盖的秘密一一浮出水面，有震惊有无法接受。最终的真相是什么，兄弟二人能否解决危机，一切都是未知……本片改自伊坂幸太郎的同名小说，这也是他的作品第六次被搬上荧幕。©豆瓣', '加濑亮', '森淳一', 8, 17534, 'tt1427241', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p959347394.jpg', 0.3, 1.6, 21.4, 51, 25.7, '0.408714,-0.239443,-0.691698,0.232313,0.202367,0.107339,0.811780,-0.001715,-0.580520,-0.421500,0.202658,0.320329,-0.481139,0.061533,-0.116456,-0.082008,-0.272294,-0.841760,-0.000706,-0.309893,-0.327232,-0.534424,-0.334215,-0.129207,-0.089265,-0.100745,0.637954,0.359731,-0.321542,0.193469,0.486765,0.494507,-0.597411,0.418770,-0.103545,0.145688,-0.085208,0.162672,-0.248182,0.102188,0.025813,-0.347341,0.067292,-0.025101,0.118923,0.530688,0.726034,-0.071983,-0.397561,0.273002,0.681320,-0.135720,0.031439,0.132922,0.559629,0.396303,-0.187007,0.419020,-0.361041,-0.317679,0.086552,0.079342,-0.668981,-0.148686,0.432596,0.698091,-0.314935,0.206123,-0.116483,-0.025889,-0.014153,-0.082619,0.432426,0.423832,0.489324,0.168441,0.109459,0.017672,-0.490589,0.077877,0.471822,0.095320,-0.013804,0.232615,-0.264628,-0.178934,-0.207075,0.035577,0.181524,0.184642,0.330300,0.073405,-0.191835,0.419143,-0.504224,-0.157196,-0.104445,-0.080606,0.120933,-0.242251,-0.269160,-0.620234,-0.258230,-0.342819,-0.435992,-0.004156,0.139126,-0.387502,0.418515,-0.706448,0.066891,0.682563,0.115329,0.036180,0.553861,0.148520,-0.137857,-0.039133,0.061356,-0.196679,0.117804,0.375469,0.037995,0.401291,0.220709,-0.242348,-0.673779,0.025547', '3263169', '4023433', '1947080', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3727658', '咒怨：黑少女', '恐怖', '少女芙季子某天在学校突然晕倒，原本以为没事的母亲季和子将女儿带回家，谁知女儿竟再次晕倒，并对父亲横田弘（胜村政信 饰）说出阴森恐怖的奇怪话语。芙季子随即被送往医院，经检查发现她的腹部出现未知囊肿。从这一刻起，各种怪异之事频繁发生。好色的横田寻找女同事，却离奇地成为了杀人犯；护士裕子（加护亚依 饰）三番五次目睹发生在芙季子身上的恐怖景象，精神几近崩溃；裕子的邻居彻也（濑户康史 饰）好奇于隔壁发出的一样噪音，结果因此丧命；季和子拜托身为巫女的妹妹真理子（中村由里 饰）拯救女儿，继而见到令人难以置信的恐怖场面。原本以为除灵顺利完成，但邪恶的咒怨才刚刚开始……本片为日本恐怖片《咒怨》系列的十周年纪念作品第二部，另一部名为《白老妇》。©豆瓣', '加护亚依', '安里麻里', 5.4, 11470, 'tt1422674', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1026388250.jpg', 8.9, 31.5, 43.9, 10.9, 4.7, '0.108875,0.120879,-0.556654,0.082033,0.191360,-0.060141,0.750175,0.009997,-0.465045,-0.538860,0.389919,0.454412,-0.380286,0.262659,0.340059,0.197320,-0.053815,-0.443081,-0.142653,0.019276,-0.100094,-0.165180,-0.140849,-0.156287,-0.002467,-0.485682,0.349150,0.172750,-0.124527,0.441186,0.332576,0.454896,-0.357393,0.313173,0.234691,0.044304,-0.057156,0.175614,-0.066401,-0.032545,0.077781,-0.214499,-0.170029,0.191247,-0.141210,0.240547,0.526643,-0.254007,-0.352010,-0.213322,0.643378,-0.065483,-0.152956,0.302660,0.037593,0.176470,0.295991,-0.040916,-0.312988,-0.033192,0.322298,0.186130,-0.368958,0.347180,0.194201,0.149416,-0.193413,0.033270,-0.167079,-0.129652,0.399244,-0.300553,0.193596,0.110741,0.419272,0.600642,-0.266531,0.285394,0.045611,-0.052733,0.295514,-0.275821,-0.273765,0.236396,0.261543,-0.326397,0.195066,-0.144441,-0.143069,0.434260,0.036850,0.200959,-0.153596,0.101881,-0.364544,-0.245954,-0.199016,-0.115238,-0.075446,-0.140782,-0.454324,-0.395709,-0.088436,0.063950,-0.186890,0.026826,0.062285,-0.284704,0.441284,-0.586623,0.230910,0.262520,0.104197,-0.234207,0.012508,-0.049932,-0.214239,-0.139681,-0.156525,0.220724,0.034560,0.292460,0.009419,0.238127,-0.017159,-0.039898,-0.189763,0.275065', '1302488', '21348112', '1296534', '30257386');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3727661', '咒怨：白老妇', '恐怖', '矶部一家六口人搬到新的房子，自搬入之日起，矶部家次子笃平的性情便开始发生转变。随着又一次司法考试的失败，笃平在圣诞前夜将母亲、兄长、嫂子以及两个侄女残忍杀害，随后带着小侄女未来的头颅来到深山野岭，上吊自杀。死前留下了录有古怪留言的录音带。凶案发生第二天，快递员田宫（铃木裕树 饰）送货至矶部家，在一系列诡异事件后，他发现了凶案现场，却从此被拿着篮球的白色老女的怨灵所纠缠；由于怨灵作祟，未来的小学同学小茜也在凶案次日失去了父亲（宫川一朗太 饰）。这起灭门惨案至此告一段落，但在七年之后，已经上了高中的小茜（南明奈 饰）再次被带回旧日的噩梦之中……本片为日本恐怖片《咒怨》系列的十周年纪念作品第一部，另一部名为《黑少女》。©豆瓣', '南明奈', '三宅隆太', 6, 16446, 'tt1422675', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1026382862.jpg', 5.2, 22.5, 48.6, 16.6, 7.2, '0.237235,0.134997,-0.532160,0.191774,0.152909,-0.155067,0.663520,0.156194,-0.514703,-0.329069,0.335854,0.632064,-0.340203,0.385324,0.241251,0.056456,-0.131900,-0.642893,-0.180130,-0.335956,-0.374979,-0.268243,0.005421,0.072135,0.053725,-0.225708,0.525837,0.207797,0.062800,0.516807,0.340846,0.235464,-0.413170,0.183725,-0.059037,0.261552,-0.097483,0.125903,-0.167733,0.196230,-0.011658,-0.381746,-0.055506,-0.008184,-0.104484,0.298333,0.974974,-0.347870,-0.250488,-0.251538,0.511591,-0.095495,-0.312756,0.219091,0.500594,0.274031,0.121536,0.467413,-0.601349,-0.171828,-0.071984,0.015654,-0.321928,0.125749,0.002731,0.265192,-0.424394,0.481187,-0.094048,-0.030418,0.416098,-0.372952,0.086284,0.378868,0.260765,0.264265,-0.136305,0.144291,-0.050080,0.329722,0.539600,-0.277567,0.028924,0.192332,0.164457,-0.194279,0.061806,-0.165252,-0.130958,0.302338,0.481692,0.019904,-0.055654,0.352193,-0.718619,-0.223720,-0.248985,-0.187345,0.162660,-0.203987,-0.364157,-0.543884,-0.110636,-0.075364,-0.171085,-0.001413,0.136256,-0.174367,0.411327,-0.623809,0.396284,0.403417,0.013896,-0.180584,0.151870,-0.095258,0.063570,-0.031347,-0.003379,0.064778,0.195106,0.535647,0.113087,0.273824,-0.010816,-0.191996,-0.397824,0.350759', '1309194', '1467779', '21619567', '5364978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3731463', '杀人犯', '剧情', '半岛大厦天井，警员徐泰被发现时身负重伤，奄奄一息。同时，警方还在现场找到了昏迷不醒的督察凌光（郭富城 饰）。结合近期发生的电钻杀人案，警方怀疑此案为同一凶手所为。凌光苏醒后失忆，导致其无法解释与徐泰相会之事，因此陈安哲（钱嘉乐 饰）等警员指责其为凶手。余总警司（董勇 饰）让他不要插手此案。凌光深感委屈，身边只剩好友阿鬼（张兆辉 饰）力挺。记事簿显示，凌光在案发时均在请假，他询问妻子希爱（张钧甯 饰）和养子仔仔（谭真一 饰）希望唤起当时的记忆，无济于事。他的脑中不停闪现血腥场面，精神极度失控，不但冷淡妻儿，而且忽视了刚离婚的妹妹凌敏（何超仪 饰）。收集证据时，凌光赫然发现，几名死者竟然跟自己有着特殊的关系，而且这背后还隐藏着更大的阴谋……©豆瓣', '郭富城', '周显扬', 6.7, 17768, 'tt1437362', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p451156937.jpg', 4.1, 10.7, 41.6, 33.5, 10.2, '-0.008195,-0.048275,-0.619410,0.305006,0.272835,-0.062363,0.638719,0.209761,-0.686690,-0.516699,0.316047,0.385816,-0.223848,0.160453,0.042998,-0.301066,-0.256657,-0.677808,0.032255,0.100201,-0.354603,-0.575066,-0.125349,-0.106275,-0.076302,-0.333010,0.280518,0.161925,-0.158242,0.396395,0.186602,0.249718,-0.443511,0.498630,0.149111,-0.101976,0.076908,0.106425,-0.221520,-0.043393,0.230041,-0.244605,-0.106910,0.233160,-0.144092,0.463878,0.626808,-0.039264,-0.342403,-0.200108,0.363517,-0.071623,0.054640,0.128517,0.215208,0.134121,0.196989,0.197764,-0.347975,-0.035236,0.209955,0.420480,-0.621455,0.030559,0.007885,0.269745,-0.330107,0.057881,-0.354172,0.008290,0.285317,-0.052364,0.250262,0.355160,0.105965,0.046836,-0.290064,-0.083556,-0.469290,0.110177,0.307661,0.041053,0.126577,0.215655,-0.067710,-0.356064,-0.099868,0.149994,-0.121111,0.090902,0.149335,0.176389,-0.121668,0.166114,-0.177441,-0.358875,-0.115064,0.237833,-0.238105,-0.190057,-0.143106,-0.375712,-0.194488,-0.043103,-0.266500,0.067871,0.075028,-0.206420,0.216529,-0.620879,0.187144,0.217994,0.334488,-0.470650,0.385190,0.239225,0.039811,-0.306726,-0.339207,-0.071721,0.344130,0.171350,0.177786,-0.002202,-0.049779,-0.279872,-0.347948,-0.070278', '35073886', '3263169', '1301022', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3731581', '里约大冒险', '喜剧', '阿蓝（Jesse Eisenberg 配音）是一只世界上极其稀少的蓝色金刚鹦鹉，当他还是雏鸟时，便被可鄙的偷猎者从里约的热带丛林中掳到美国。阴差阳错，他变成了小女孩琳达的宠物，从此相伴多年，如今的阿蓝俨然一个养尊处优的宅男，甚至到忘记了如何飞行。某天，名叫图里奥（Rodrigo Santoro 配音）的鸟类学家经过琳达（Leslie Mann 配音）经营的书店，他被阿蓝所震惊，并希望能将阿蓝带回里约，与世上仅存的另外一只雌鸟繁衍后代。虽然心怀不安，但是考虑到蓝色金刚鹦鹉的命运，琳达还是带着阿蓝来到里约。阿蓝顺利见到了美丽的同类茱儿（Anne Hathaway 配音）。茱儿则一心逃离樊笼，回归大自然。与此同时，一伙犯罪分子盯上了这群可爱的小生灵……©豆瓣', '杰西·艾森伯格', '卡洛斯·沙尔丹哈', 8.3, 301397, 'tt1436562', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2170811687.jpg', 0.1, 0.8, 16.1, 49.1, 33.8, '0.193931,0.124100,-0.606324,0.401905,-0.274342,-0.296165,0.743032,-0.137347,-0.313985,-0.145274,0.093841,0.558861,-0.126598,0.452215,0.229812,0.096618,-0.061444,-0.360556,-0.187783,-0.172191,-0.142194,0.005879,-0.503711,-0.035796,-0.084862,-0.167693,0.611639,-0.024446,-0.061583,0.355431,0.067333,0.114370,-0.515782,0.215007,-0.287436,0.063019,0.053194,0.004551,0.132393,0.264828,-0.139755,0.049484,0.125436,0.030826,-0.106642,0.258100,0.925252,-0.633889,-0.047054,-0.298772,0.299944,-0.150434,-0.083343,0.177736,0.263991,0.161047,0.177966,-0.022966,-0.249821,0.087775,0.018975,-0.212820,-0.650521,0.096365,-0.082222,0.202948,-0.425120,0.303296,0.172068,-0.186086,0.178434,-0.488148,0.118927,-0.027110,0.133670,0.571698,0.011902,0.322111,-0.407026,0.015058,0.548304,0.026871,-0.273371,0.288358,0.047123,-0.442875,0.224084,-0.175143,-0.410692,-0.222762,0.390755,0.164159,-0.228719,0.141200,-0.682529,0.113757,-0.395384,-0.046835,-0.050125,-0.333933,-0.209176,-0.198773,0.072597,-0.396357,-0.218464,0.173656,0.258390,-0.220807,0.735002,-0.784923,0.285023,0.420378,0.248947,-0.261146,0.504188,-0.236474,0.116929,-0.146022,-0.104136,0.368268,0.191015,0.260693,0.154290,0.283804,-0.162973,-0.156045,-0.490779,0.474430', '21619567', '25774050', '5364978', '6974439');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3731598', '布卢明顿', '剧情', '一个成长期的女孩在学校里寻求独立过程中，邂逅了美丽的女教授。她们的关系迅速发展，直到一次机会，促使她做出了改变一生的决定。Jakie，一个22岁的热爱电视表演的女孩，从加利福尼亚来到了这。她已经准备探索新的生活并体会独立，甚至她生活中从未体验过的生活。不久她迷恋上了她的老师。。。。。。。。。她们会最终走爱一起么，还是一时激.情？（@悸花网）', 'Sarah Stouffer', 'Fernanda Cardoso', 7.4, 12008, 'tt1409004', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p498708338.jpg', 0.9, 5.4, 35.7, 37.9, 20.1, '0.229343,0.138397,-0.635634,0.733846,-0.523344,-0.439527,0.610055,0.048939,-0.555319,-0.165372,0.249025,0.674373,-0.077313,0.531971,0.337763,0.092268,-0.368490,-0.918915,0.166217,-0.216255,-0.451565,-0.036157,-0.335924,-0.194180,-0.116000,-0.130233,0.750546,-0.018838,-0.199914,0.411612,-0.033513,-0.281800,0.101493,0.693197,-0.143464,-0.057972,0.263334,0.331625,-0.396942,0.173420,-0.020756,-0.397534,-0.020839,0.062024,-0.038741,0.273093,0.880018,-0.431940,-0.209201,-0.211492,0.398702,0.274391,-0.232592,0.163005,-0.000825,0.055564,0.206233,0.288765,-0.134088,-0.141141,-0.220501,-0.265824,-0.737968,0.010372,-0.108906,-0.006239,-0.557721,0.519008,0.349816,-0.050833,0.044307,-0.182793,0.018893,0.333712,0.553293,0.264733,-0.264698,0.059961,0.070823,0.577891,1.043708,-0.168116,-0.375752,0.684709,-0.445880,-0.408319,-0.015447,-0.103020,-0.720170,0.025879,-0.041508,0.198728,-0.579716,0.182259,-0.591369,0.367993,-0.438507,-0.136546,0.244288,-0.393654,0.056949,-0.575646,-0.234682,-0.387008,-0.394675,-0.013974,-0.264138,-0.433534,0.826234,-0.935902,0.198924,0.731285,0.419461,-0.711704,0.955745,0.140362,0.003304,-0.259164,0.123289,0.760711,-0.627374,0.474575,-0.203827,0.508938,-0.017090,0.190496,-0.495743,0.770751', '3230462', '1309177', '30162520', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3731626', '当你熟睡', '悬疑', '人过中年的塞萨尔（Luis Tosar 饰）是某幢公寓的管理员，上班期间他兢兢业业，和每个经过他面前的邻居问好，认真处理所有事务，偶尔帮助住户照看小狗；休息时则前往医院看望母亲，为其讲述一天的经历和见闻。然而看似老实内向的塞萨尔，却有着不可为人道的秘密。每天晚上，他都偷 偷潜入青春靓丽的女住户克拉拉（Marta Etura 饰）的房间，用药物令其陷入深深的熟睡之中，日常海发各种言辞热辣的短信进行骚扰。然而这一切似乎并非处于近乎疯狂的迷恋，他的行为背后隐藏着更深的企图。在此期间，克拉拉的身体状况愈来愈差，她的生活也由此变得一团糟。在他乖张的行为进行过程中，一切朝着不可逆转的方向发展……©豆瓣', '路易斯·托萨尔', '豪梅·巴拉格罗', 7.3, 46586, 'tt1437358', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1255071486.jpg', 1.2, 3.8, 36.6, 46.2, 12.3, '0.257787,-0.121794,-0.594276,0.588358,-0.191374,0.053635,0.683046,0.230071,-0.642871,-0.460657,0.042501,0.200678,-0.039766,0.285453,0.285783,-0.202488,-0.415795,-0.583418,-0.332140,0.166544,-0.194940,-0.218995,-0.148621,-0.274394,-0.121135,-0.338821,0.285852,0.119902,-0.189532,0.398763,-0.120064,0.395825,-0.215591,0.434537,-0.014033,-0.185139,-0.016137,-0.065058,-0.132148,0.076118,0.212482,-0.374264,-0.139657,0.135230,0.040348,0.564652,0.764065,-0.182053,-0.517157,-0.005119,0.452868,-0.138733,-0.068410,0.315162,0.238399,0.254106,0.231632,0.217556,-0.409516,0.221293,0.001896,-0.164432,-0.828661,-0.198824,0.251478,0.184167,-0.409029,0.300241,-0.064572,0.083296,0.112683,-0.409775,0.053925,0.236742,0.076758,0.377755,-0.057203,-0.074997,-0.307639,0.002387,0.398357,0.130252,-0.318056,0.333472,-0.405117,-0.129314,0.127892,-0.138327,-0.419898,-0.083545,-0.113466,0.174711,-0.149783,0.282670,-0.426348,0.074825,0.002311,-0.636641,-0.036506,-0.385558,-0.346548,-0.926789,-0.126225,-0.655981,-0.328702,-0.107949,-0.030407,-0.093741,0.398222,-0.709071,0.104447,0.415501,0.245720,-0.534606,0.702385,-0.208321,0.233297,-0.128550,-0.180136,0.281706,0.115288,0.258484,-0.029915,0.240792,-0.186579,0.078711,-0.608598,0.434830', '2334814', '26577354', '1298197', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3731662', '刺杀游戏', '动作', '两名顶级杀手各为其主，双方进行了多次较量，但他们亲人的惨死使得他们开始冷静思考自己的未来，并最终两人成为惺惺相惜的好友，并联手对付那些凶残的敌人。', '尚格·云顿', 'Ernie Barbarash', 6.4, 5332, 'tt1436568', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1114217623.jpg', 1.6, 12.1, 57.1, 22.5, 6.6, '0.614618,-0.104431,-0.585964,0.424879,-0.025830,-0.110436,0.516880,-0.161764,-0.694504,-0.379755,0.512415,0.866502,0.081868,0.065620,-0.192737,-0.896964,-0.052972,-1.178132,0.228176,0.245892,-0.040156,-0.442903,-0.477078,-0.365357,-0.172351,0.155949,0.947796,0.174767,-0.263339,0.547353,0.203381,0.224153,-0.138708,0.442761,0.041463,-0.304530,0.050514,-0.204217,-0.841633,0.166786,-0.471517,0.199480,-0.203634,0.432507,-0.088337,0.774768,0.545785,-0.328014,-0.479663,0.122990,-0.068296,-0.580961,-0.102485,0.640365,0.621810,0.102458,0.125274,0.217184,0.404668,-0.117815,-0.628541,0.353081,-1.372621,0.241081,0.086865,-0.372726,-0.467159,0.563289,0.386829,0.015416,-0.250858,0.251764,0.231794,0.653270,0.471535,-0.231989,-0.458440,-0.417089,-0.080742,-0.017067,1.169827,-0.129026,-0.416466,-0.001591,0.139073,-0.626096,-0.424252,-0.855589,-0.085205,0.025604,0.469883,0.515330,-0.089665,0.373009,-0.945630,0.066743,-0.409117,0.122033,-0.038039,-0.700974,0.565409,-0.879046,-0.355162,-0.681465,-0.835888,0.007287,-0.099257,-0.508698,0.992509,-0.926346,-0.229832,0.474088,0.365139,-1.140182,0.353899,0.351685,0.332699,-0.060036,-0.384115,0.513634,0.173480,-0.263301,0.216501,0.152061,-0.058974,0.727617,-0.107890,0.003857', '26678784', '4301278', '25917239', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3731893', '生命最后一个月的新娘', '剧情', '普通的上班族长岛千惠（荣仓奈奈 饰）最大愿望就是能够披上婚纱做一个美丽的新娘。她跟赤须太郎（瑛太 饰）在某次展览会上结识并开始交往。在幸福刚刚降临的时候，她却被诊断出了乳腺癌。千惠无法接受这个事实，又不知道怎样向太郎开口。几个月后，千惠向太郎坦白了自己的病情，为了不给太郎添麻烦她选择彻底离开。然而什么也无法阻挡太郎对千惠的爱，他苦苦追寻千惠来到屋久岛，并要求同千惠一起对抗病魔。千惠被太郎的爱情打动，她忍受着病痛折磨，积极配合治疗，期望奇迹的降临。然而，此时噩耗传来，太郎和千惠的家人被告知千惠只剩下一个月的生命……©豆瓣', '荣仓奈奈', '广木隆一', 7, 6586, 'tt1435613', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p939647081.jpg', 0.8, 4.9, 46.5, 36.8, 11, '0.100843,0.208644,-0.395534,0.244956,-0.217910,-0.397223,0.668863,-0.009342,-0.203306,-0.449369,0.222406,0.542289,0.017910,0.080910,0.205014,0.107785,-0.277660,-0.708899,0.208354,0.111385,-0.115377,-0.587239,0.237291,-0.094363,-0.284720,-0.350287,0.795822,0.169151,0.159309,0.344501,0.488427,0.339105,0.276787,0.455511,-0.075612,0.182060,-0.112636,-0.046599,-0.363379,0.408586,0.075339,-0.332458,0.000278,0.782326,-0.097786,0.205370,0.554959,-0.390701,-0.427722,-0.135419,0.274864,-0.551788,-0.008429,0.543007,-0.152120,0.048407,0.105048,0.295565,-0.284875,-0.290892,0.288614,0.029663,-0.556226,0.090029,0.125402,0.411389,-0.361132,0.176008,-0.318047,-0.090800,0.229935,-0.331186,0.185413,0.634541,0.235814,0.261647,-0.858603,0.167502,-0.317431,0.344600,1.033308,-0.100939,-0.005840,0.510046,-0.222473,-0.144340,-0.149560,-0.262955,-0.399824,0.193779,-0.336175,0.436931,-0.439289,-0.087634,-0.240302,-0.199424,-0.380016,-0.237072,0.219772,-0.630858,0.048564,-0.507717,0.050984,-0.377532,-0.542099,0.183193,0.046669,-0.532514,0.710687,-0.811354,0.011350,0.597188,0.833062,-0.171081,0.408038,0.116914,-0.369843,-0.220111,0.040524,0.569126,-0.153854,0.326362,0.123115,0.441663,0.286693,0.190414,-0.731585,0.265584', '30345227', '1937946', '1978369', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3732499', '初三大四我爱你', '剧情', '一次偶然的机会，读初一的小男生纳认识了在普吉开店的女网友珍，两个人通过网络熟识，以msn联系了三年，直到纳初三毕业。纳决定来普吉跟珍见面。纳的哥哥梯是医学院大四的学生，由于外形俊朗成绩优秀，所以备受女孩青睐，不少女孩主动投怀送抱，以至于让他对爱情产生了游戏的态度。但是，当他在街上偶遇女孩淳的时候，他才知道原来爱情犹如电击。巧合的是，珍和淳是普吉的一对姐妹花，而且年龄分别与纳和梯相仿。纳来到普吉与珍见面，尾随而至的梯赫然发现淳竟然是珍的姐姐。初三的这对恋人，情窦初开，对爱情充满了甜蜜的憧憬与想象。大四的这对，面临毕业走向社会，他们的抉择似乎拥有一种更理性的光辉。在风光旖旎的普吉岛上，兄弟俩和姐妹俩上演了浪漫的爱情故事……©豆瓣', '莎若查·棠杰拉兰', '海曼·查泰密', 7.1, 59792, 'tt2635846', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p459985157.jpg', 0.8, 5.3, 41.9, 39.8, 12.1, '0.389295,-0.373811,-0.776726,0.780798,-0.032960,-0.216676,0.676029,0.015261,-0.466021,-0.248766,-0.079028,0.878101,-0.696940,0.471299,0.394950,-0.147430,0.017517,-0.696595,0.141774,-0.472125,-0.354474,-0.459857,0.123196,0.098407,0.127572,-0.405950,0.663366,0.031157,-0.238407,0.726837,0.380864,0.243123,0.121122,0.466101,-0.348323,-0.071523,-0.043416,0.402021,-0.377803,0.073574,0.113760,-0.142212,-0.161260,0.019640,0.180036,0.317704,1.014078,-0.201638,-0.275789,0.039011,0.511369,-0.208975,-0.269323,0.101886,0.348172,0.065264,-0.021956,0.088315,-0.067334,-0.113138,-0.097684,-0.406608,-0.399492,0.261591,0.245089,-0.134729,-0.492890,0.586772,0.199477,-0.048849,0.036671,-0.101130,0.165609,0.378383,0.011192,0.621068,-0.126132,-0.000998,-0.448290,0.008518,0.814185,0.190293,-0.335743,0.807217,-0.297397,-0.429094,-0.019826,-0.034965,-0.473055,0.156452,0.043917,-0.012075,-0.198387,0.133082,-0.648014,-0.135149,-0.230634,0.209795,0.318048,-0.707414,-0.193865,-0.689019,-0.249637,-0.716199,-0.404850,0.331109,0.041440,-0.444759,0.889788,-1.051110,-0.043651,0.405359,0.601082,-0.652052,0.992000,0.211925,-0.094785,-0.536666,-0.190832,0.330590,-0.025294,-0.197217,-0.117463,0.384697,-0.142214,0.116864,-0.521892,0.520328', '1292219', '3445516', '3041753', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3732550', '蜡笔小新 呐喊！春日部野生王国', '动画', '某日，小新（矢岛晶子 配音）在河堤上捡到了一瓶神秘的液体，把它带回家放在了冰箱里。哪知道美伢（楢桥美纪 配音）和广志（藤原启治 配音）在无意之中将其喝下，隔天竟然变异成为了动物。之后，一个神秘的环保组织SKBE掳走了小新一家人，而为首的，竟然是双叶里的里长四膳守（山寺宏一 配音）。原来，四膳首是一位激进的环保主义着，妄图通过一种神秘的药物将破坏环境的人类全部都变成动物，而小新捡到的神秘液体就是还尚处于测试阶段的药物，四膳守准备将美伢和广志当做实验对象进行研究。在神秘女子维多利亚（后藤邑子 配音）的帮助下，小新一行人成功出逃，他们和春日部防卫队一起，决心破解四膳守的阴谋。©豆瓣', '矢岛晶子', '鴫野彰', 8.3, 10127, 'tt1388333', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p937103322.jpg', 0.2, 1.3, 17.6, 43.3, 37.7, '0.302267,0.191488,-0.562843,0.467706,-0.265051,-0.063131,0.492148,0.180837,-0.265961,-0.102865,0.302663,0.408459,0.033190,0.303577,0.073778,0.100643,-0.207448,-0.488834,-0.233235,-0.089355,-0.626884,-0.213383,-0.465256,-0.074569,-0.034409,-0.455939,0.480768,-0.005257,-0.303720,0.152589,0.097783,0.307260,-0.419994,0.151424,-0.024878,0.001183,0.257340,-0.271111,-0.017628,0.392490,-0.332949,-0.274045,-0.034245,0.026577,0.166461,0.287315,0.840865,-0.444055,-0.105661,-0.220342,0.141680,-0.335757,-0.169987,0.296139,0.348836,0.139050,-0.017614,0.043627,-0.459975,0.033664,0.117647,-0.025082,-0.741069,-0.181917,0.004163,0.292355,-0.516497,0.288469,0.100001,-0.170245,0.303238,-0.578934,0.161422,0.009296,0.242824,0.333180,-0.068954,0.163460,-0.330069,0.051532,0.473148,-0.277183,-0.104247,0.307467,0.147986,-0.284247,0.063733,-0.074437,-0.189291,-0.141873,0.203855,-0.038835,-0.168515,-0.178241,-0.927610,0.058027,-0.126117,-0.098807,0.266171,-0.174452,-0.322474,-0.635515,-0.099223,-0.138481,-0.228232,0.214737,0.268829,-0.216767,0.899405,-0.644497,0.108777,0.646189,0.030185,-0.285502,0.230727,-0.105531,0.041690,-0.058653,-0.164951,-0.232865,0.269475,0.434253,0.191305,0.637393,-0.207428,-0.051196,-0.691827,0.131074', '4181031', '25774050', '5403927', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3732780', '第36个故事', '剧情', '台北市的一角，伫立着一间清静雅致的咖啡店。它的主人朵儿（桂纶镁 饰）和蔷儿（林辰唏 饰）是一对美丽的姐妹花，朵儿经营咖啡店的想法由来已久，偶然的机缘下，她得以实现自己的梦想。虽然倾注了大量的心血，但是在开业之初的喧嚣后，咖啡店渐渐归于平寂。正当姐妹俩为此烦恼不已之时，一本朋友庆贺开业送的泰文食谱启发了鬼灵精蔷儿的灵感。她鼓励姐姐在咖啡店内开展以物易物的服务，吸引各色人等云集于此，寻找、交换彼此的心爱之物。咖啡店渐渐热闹起来，拥有36个城市故事的周群青（张翰 饰）的到来，也改变着姐妹的人生……本片荣获2010台北电影节观众票选奖和最佳音乐奖。©豆瓣', '桂纶镁', '萧雅全', 7.6, 140834, 'tt1682949', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p918663787.jpg', 0.6, 4.1, 30.9, 43.6, 20.8, '0.152139,0.136793,-0.495677,0.547072,0.055673,-0.224051,0.677265,0.350367,-0.323728,0.048155,0.312770,0.721326,-0.209098,0.400847,0.445871,0.126583,-0.204279,-0.546001,-0.076126,-0.151882,0.192372,-0.254550,-0.377522,-0.025592,-0.184522,-0.277910,0.459902,0.181519,0.071175,0.479431,0.276509,-0.157564,-0.268625,0.311625,-0.081643,-0.029479,0.148327,0.202214,-0.442761,0.069335,-0.328800,-0.419126,-0.248796,0.054462,0.123136,0.143233,0.854603,-0.184795,-0.221627,-0.052877,0.568287,0.017321,0.073737,-0.074876,-0.071496,0.088617,0.370921,0.002803,-0.411180,0.042881,0.062738,-0.116779,-0.606551,-0.013859,0.410312,-0.000824,-0.433449,0.605407,0.190860,-0.039906,-0.072176,-0.413756,0.398065,0.404220,0.093083,0.320198,-0.144239,0.022566,-0.482410,0.346183,0.489797,-0.142999,0.042113,0.539134,-0.439293,-0.458161,0.078123,0.130053,-0.579240,-0.311750,0.285596,0.088904,0.272989,-0.054572,-0.793251,0.016427,0.055913,-0.396504,0.282383,-0.421350,-0.123471,-0.859507,-0.089384,-0.164624,-0.168010,-0.054891,0.114320,-0.331848,0.977729,-0.770665,0.084985,0.554863,0.000024,-0.326990,0.876876,-0.147268,0.167050,-0.069834,-0.286429,0.107733,-0.274482,0.272765,-0.181925,0.452660,-0.062790,0.028943,-0.768608,0.582125', '3811356', '1418179', '2027945', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3732800', '我们天上见', '剧情', '上世纪70年代末，时代的狂潮正渐渐退去热度。在南方某个古朴的小镇，小女孩蒋晓兰（朱一诺 饰）和姥爷（朱旭 饰）相依为命。晓兰的父母早年下放边疆，在学校她又因与“最大的阶级敌人”同姓而倍受欺负和排挤。破旧的小院是晓兰最为自由的天地，而家里的大衣柜则是她最后的避难之所。早年 因战乱和疾病，姥爷几乎失去所有的亲人，因此这个调皮又善良的外孙女成了他生活的全部。时光缓缓流逝，细雨绵绵的小镇永远带着化不开的愁绪，渴望成为体操冠军的晓兰（姚君 饰）一天天长大，而那个永远牵挂着她的姥爷却慢慢地老去……本片为著名影星蒋雯丽的导演处女作，也是人艺老演员朱旭的封镜之作。影片荣获2009第14届釜山电影节观众最喜爱影片奖。©豆瓣', '朱旭', '蒋雯丽', 8.7, 71064, 'tt1515202', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p459518618.jpg', 0.1, 0.7, 9.9, 40.4, 48.9, '-0.104009,-0.048118,-0.679675,0.705786,-0.037090,-0.263103,0.821520,0.313043,-0.437927,-0.150920,0.144690,1.041959,0.086122,0.527877,0.019715,-0.093477,-0.096668,-0.632962,-0.239966,-0.157861,-0.178544,-0.049080,-0.174781,0.112135,-0.182038,-0.204715,0.926049,0.131025,-0.073861,0.360156,0.331306,0.119255,-0.090742,0.246102,-0.377962,0.081546,-0.138072,0.159118,-0.327760,-0.055271,-0.101736,-0.335880,-0.215172,0.025364,-0.145271,0.028286,0.869658,-0.044451,0.099731,-0.267177,0.573717,-0.378696,-0.200887,-0.127354,0.245040,-0.052089,0.294641,0.042784,-0.036302,-0.015648,-0.008780,-0.192058,-0.573767,0.052292,0.329301,0.183649,-0.555696,0.709080,0.167648,-0.177992,0.096133,-0.376121,0.289799,0.269825,-0.134032,0.479960,-0.476482,-0.048080,-0.306396,0.458508,0.363201,-0.078688,-0.382157,0.438711,-0.410832,-0.290134,0.210672,-0.418687,-0.871150,-0.104662,0.197011,0.124079,-0.100407,0.485254,-0.594073,0.164274,0.184237,-0.281577,0.237663,-0.467387,-0.062020,-0.639887,-0.197630,-0.744839,-0.129822,-0.039394,0.125537,-0.077733,0.860568,-0.610612,0.536229,0.416368,0.068868,-0.401819,0.660577,0.117580,0.215710,-0.096519,-0.064957,0.568094,-0.265442,0.291321,-0.068863,0.245621,-0.362231,0.027862,-0.417464,0.747853', '1299663', '3811356', '1870681', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3732861', '左右情缘', '剧情', '阿Sam（张国荣 饰）是一位曾赴法国留学的银行家，虽做着外人看似传统的工作，实则对绘画很有研究，钟爱艺术。他和女友Carol（邱淑贞 饰）一起生活的六年，感情甜蜜。近来，Carol的画廊正在争取与法国的一位艺术家合作，相关事宜需要面谈，她却因工作繁忙走不开，阿Sam便主动请缨帮忙前去，同时，Carol还委托了独居巴黎的表妹阿Jane（张柏芝 饰）协助联系艺术家。等阿Sam抵达巴黎，不料那位艺术家却需出差德国长达一个礼拜，他只好同阿Jane消磨时间。初见姐夫的阿Jane对这个银行家很不屑，直到慢慢惊诧于他的绘画才华和成熟魅力，她竟渐渐对他暗生情愫。沉浸在钟爱的艺术之都巴黎，面对着敢爱敢恨的妙龄少女，一切都那么浪漫新鲜，仿佛用惯了右手的人突然想试试左手一般，阿Sam将如何选择……本片是张国荣自导自演的一部音乐特辑，在巴黎取景拍摄完成，于1999年10月10日在翡翠台首播。', '张国荣', '张国荣', 8.3, 8357, '', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2593601531.jpg', 0.3, 1.7, 20.2, 39.3, 38.6, '0.060709,-0.024553,-0.662973,0.657984,0.082778,-0.533295,0.497593,0.106698,-0.160445,-0.633272,-0.009963,0.357986,-0.146525,0.371302,0.289210,-0.343255,-0.351665,-0.734124,-0.085936,-0.107787,0.065622,-0.321089,-0.213797,0.019486,-0.217657,-0.261520,0.501814,0.058565,0.035050,0.488374,0.251854,0.093576,0.032299,0.622740,-0.250661,-0.408370,0.011238,0.203827,-0.442714,0.073633,0.368227,-0.331138,-0.134313,-0.215430,0.158065,0.258760,0.786881,-0.046402,-0.057803,-0.064141,0.527840,0.011862,0.251157,0.007899,0.132562,0.150862,-0.012524,0.073404,-0.311966,-0.066267,0.187613,-0.443611,-0.439747,-0.001667,0.196777,0.138329,-0.523876,0.320076,-0.229437,0.001283,-0.044765,-0.381742,-0.007936,0.331507,0.278186,0.522646,0.279138,0.317389,-0.190204,0.547908,0.665005,0.280738,-0.036686,0.322824,-0.271349,-0.680661,0.163015,-0.088547,-0.398947,-0.006514,0.008554,-0.309854,0.198215,0.191782,-0.456527,0.066712,0.043370,-0.022955,0.216791,-0.592305,0.423218,-0.901479,0.007829,-0.435086,-0.022558,0.072384,0.452770,-0.105219,0.715024,-0.731092,0.234135,0.637636,0.490334,-0.404347,0.888380,0.202567,-0.097699,-0.435995,-0.086424,0.246015,-0.184094,-0.029921,0.035570,0.451378,0.291262,-0.012990,-0.515748,0.335492', '3811356', '5403927', '24751811', '1302050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3734112', '风声', '剧情', '1942年10月10日，汪伪政权举行了盛大的国民政府庆典。然而，一系列的军政要员遇刺事件，让身为特务处长王田香（王志文 饰）如坐针毡。在对女刺客（刘威葳 饰）的酷刑审问中，他获得了一条关键的情报——代号为老鬼的地下党已经混入了剿匪司令部。立功心切的王田香立刻向日本皇军特务机关长武田（黄晓明 饰）做了汇报。二人随即在裘庄布下了一个圈套，意图通过放出假消息逼老鬼现身。在被怀疑的对象中，有司令的侍从官白小年（苏有朋 饰）、军机处长金生火（英达 饰）、剿匪大队长吴志国（张涵予 饰）、译电组组长李宁玉（李冰冰 饰）以及行政收发专员顾晓梦（周迅 饰）。在怀疑与排查中，武田与王田香不择手段软硬兼施，然而事情的发展却出乎意料……©豆瓣', '周迅', '陈国富', 8.4, 559175, 'tt1434423', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1599059779.jpg', 0.2, 0.9, 13.9, 49.8, 35.2, '-0.072911,-0.132682,-0.510863,0.380100,0.127850,0.065625,0.244718,0.185072,-0.501665,-0.284108,0.423157,0.341031,-0.296877,-0.545950,0.276282,-0.075008,-0.245461,-0.727356,-0.385466,-0.239796,0.019947,-0.492630,-0.188582,-0.236804,-0.047112,-0.174864,0.447756,0.176737,-0.144602,0.417165,0.610243,0.326973,-0.136453,0.221391,0.181405,-0.133444,0.520325,-0.300209,-0.268532,-0.020535,-0.047787,-0.517417,-0.215233,-0.012916,0.083315,0.531264,0.479257,-0.511984,-0.095854,-0.239355,0.223436,-0.364851,-0.136667,0.007607,0.462547,0.357140,0.010480,0.499723,-0.370046,0.120559,0.158754,-0.210906,-0.594437,-0.043605,0.233279,0.297297,-0.217175,0.094048,-0.259389,0.244384,0.129861,-0.228536,0.406884,0.454830,0.134294,0.217590,-0.145379,0.065679,-0.283320,0.392215,0.302370,-0.022769,-0.021455,-0.134785,0.231495,-0.422350,0.036983,-0.101181,0.101562,0.012491,0.202146,-0.246320,0.025413,0.006305,-0.453047,-0.322352,-0.258517,0.077774,-0.008491,-0.231426,-0.113877,-0.769906,-0.030714,-0.214650,-0.189963,0.107286,0.251913,-0.032727,0.293685,-0.756238,-0.024204,0.340898,0.094275,-0.551995,0.377426,0.169784,-0.014276,-0.355057,-0.153747,-0.248910,0.293512,0.559175,0.217187,0.417237,-0.202204,-0.703123,-0.174458,-0.341639', '25723905', '3266509', '6041191', '3387546');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3735003', '新天师斗僵尸', '喜剧', '高中生查理·布鲁斯特（安东·尤金 Anton Yelchin 饰） 和母亲生活在位于拉斯维加斯腹地的宁静社区内，他像其他同龄人一样，聊聊闲天儿，憧憬一下美丽的女同学。这一天，查理的生活出现波澜，名叫亚当的同学失踪，童年时代的好友埃德（克里斯托夫·梅兹-普莱瑟 Christopher Mintz-Plasse 饰）怀疑亚当的失踪与吸血鬼有关，于是胁迫查理一同寻找。与此同时，布鲁斯特家的隔壁搬来了一名新邻居，帅气俊朗的成年男子杰瑞（柯林·法瑞尔 Colin Farrell 饰），他迷人的气质与外表征服了查理的妈妈，但是他的真实身份似乎又与埃德调查的吸血鬼有关。阴云密布的社区，诡异事件悄然发生……本片翻拍自1985年的同名影片。©豆瓣', '安东·叶利钦', '克雷格·吉勒斯佩', 6.1, 7235, 'tt1438176', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1082379014.jpg', 3.1, 16.8, 56.5, 19.1, 4.5, '0.406350,-0.177201,-0.516989,0.487991,-0.100271,-0.378574,0.943168,0.255432,-0.566736,-0.475346,0.161030,0.763495,-0.273588,0.408566,0.581665,0.181962,-0.567878,-0.643122,0.044960,-0.175677,0.034324,-0.408163,-0.441917,-0.275145,0.270425,-0.522541,0.357717,-0.300290,0.029698,0.687581,0.100048,0.273989,-0.283840,0.146801,-0.055182,0.014039,0.171127,-0.014594,-0.467762,0.146606,-0.091001,0.089330,-0.017696,-0.059594,0.079865,0.420502,0.552882,-0.087925,-0.134536,-0.066200,0.434637,0.218110,-0.075559,0.115278,0.309030,-0.027470,0.123800,0.250683,-0.039440,-0.290435,-0.066973,-0.146534,-0.380759,0.328363,0.081050,0.535680,-0.149557,0.395634,0.044414,-0.192436,0.254550,-0.140679,0.184350,0.183584,0.168545,0.454627,0.183291,0.312598,-0.255762,0.258359,0.461226,0.242947,-0.263931,0.262557,-0.390739,-0.242765,-0.120279,0.051041,-0.628725,0.089656,0.135268,-0.178533,0.034784,0.525706,-0.705414,-0.111457,-0.181569,0.020590,-0.117479,-0.074013,-0.208272,-0.786562,-0.343062,-0.585725,-0.166206,-0.284242,0.058817,-0.089773,0.454252,-0.846309,0.256453,0.413971,0.260855,-0.226813,0.524618,0.036615,-0.012952,-0.256720,-0.109468,0.611058,0.226342,0.044852,-0.137481,0.406149,-0.111240,-0.181750,-0.344073,0.410406', '1296534', '30137576', '1309172', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3735015', '大海啸之鲨口逃生', '动作', '宁静的澳洲海滩上，宿醉的救生员乔许（泽维尔·塞缪尔 Xavier Samuel 饰）让女友蒂娜（沙妮·文森 Sharni Vinson 饰）的哥哥罗利替他去海上例行检查防鲨网的设置，结果罗利遭到了鲨鱼的袭击，罗利的死对乔许和蒂娜造成了很大的心理阴影，乔许为此对女友充满了歉疚，乔许为此放弃了救生员的工作去超市做了理货员，蒂娜也远赴中国学习舞蹈。一年后，当蒂娜重新返回澳洲后，和乔许在超市不期而遇，与此同时，超市里风起云涌，偷窃、抢劫……就在这起突发事件白炽化的时候，地动天摇，海啸铺天盖地而来，超市立刻沦为孤岛，大鲨鱼随之而来，一场人鲨大战瞬间展开……©豆瓣', 'Richard Brancatisano', '金波·兰道', 5.5, 18851, 'tt1438173', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1712836294.jpg', 8.3, 26.9, 49.6, 11.9, 3.3, '0.237776,-0.069753,-0.741836,0.381034,0.059089,-0.155164,0.894612,0.391743,-0.253206,0.083582,0.219737,0.679638,-0.323490,0.011962,0.355488,0.059926,-0.546370,-0.615900,-0.031921,-0.152568,-0.378826,-0.339609,-0.289908,-0.111012,0.118758,-0.325848,0.226417,0.054523,0.027667,0.581211,0.247346,0.264489,-0.106943,0.753144,0.180649,0.219396,0.133403,0.133129,-0.052815,0.321531,0.148618,-0.168363,-0.198577,0.208822,0.104189,0.393839,0.744555,-0.040836,-0.054072,-0.398715,0.201479,-0.300550,0.207770,0.077055,0.444223,-0.000302,0.070718,0.065800,-0.366390,0.127292,0.172385,-0.000957,-0.232882,0.049976,-0.154942,-0.177233,-0.525150,0.293511,-0.056691,0.015911,0.266581,-0.289953,0.062331,0.485788,0.207714,0.404420,-0.054445,0.181791,-0.329203,0.186816,0.516720,-0.093080,0.088137,0.173274,-0.005517,-0.167672,0.033421,0.020629,-0.240697,-0.236197,0.490003,-0.097514,-0.360327,0.166879,-0.757107,-0.158378,-0.493785,-0.535074,-0.297140,-0.129171,-0.310830,-1.048630,0.242667,-0.179671,0.063505,0.018651,0.093724,-0.045794,0.380357,-0.706302,0.290824,0.724594,0.268031,-0.224091,0.373261,-0.341992,0.059970,0.036065,0.145884,0.100271,-0.130256,0.716207,0.306582,0.366141,0.208051,-0.109097,-0.143296,0.606063', '2159244', '10466639', '3178770', '1309110');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3736637', '苏乞儿', '剧情', '曾为清廷第一猛将苏灿（赵文卓 饰）抛弃大好前程回到家乡，本想自此钻研武学，开宗立代，和妻子袁英（周迅 饰）还有儿子从此不再分离，尽享天伦。不料因为上代恩怨，义兄袁烈（安志杰 饰）练就魔功，杀死苏父，并掳走苏灿妻儿。河滨一战，苏灿败北，性命攸关之际，妻子舍身相救，后又得遇隐居山野尝遍百草的高人于大姐（杨紫琼 饰）救助，两人得以保全性命。苏灿因右臂筋脉断裂而灰心丧气，终日醉酒逃避现实，在妻子的精心照料与鼓励之下，苏灿最终重新振作。苏灿与袁烈再次交手，一雪前耻，但因意气用事却未能及时救出被袁烈埋入地下的袁英。妻子去世之后，伤心欲绝的苏灿与儿子流浪至中俄边境，此时的苏灿形同乞丐。在一次醉酒之后，他遇到曾经在幻象中与自己切磋的“武神”（周杰伦 饰），在与武神交手过程中，他领悟到一套于醉酒之中展示武术精妙的拳法——醉拳。面对国人受辱，好友与儿子身陷危难，苏灿挺身而出，与俄国大力士展开激战，最终靠醉拳战胜敌人。', '赵文卓', '袁和平', 5, 62657, 'tt1425257', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p466623093.jpg', 14.4, 34.2, 39.3, 8.6, 3.5, '-0.194905,-0.094451,-0.557382,0.494904,0.163354,-0.597839,0.446010,-0.085912,-0.526547,-0.514582,0.402084,0.747231,0.045489,0.201216,0.181775,-0.464422,0.105650,-0.921608,0.157302,0.157661,-0.025506,-0.212773,-0.212135,0.154310,-0.404397,-0.376379,0.820242,0.097463,-0.393649,0.564742,0.066487,0.307315,-0.391995,0.350905,-0.193769,0.060510,-0.378225,0.213686,-0.827556,0.197900,-0.042140,-0.399637,-0.236404,0.089574,-0.261416,0.217548,0.592501,-0.319866,0.055077,-0.384003,0.190704,-0.116939,-0.125883,0.148473,0.090606,0.010430,0.521540,0.159603,-0.079897,-0.106403,0.005171,-0.104674,-0.393194,-0.049564,0.106773,-0.315323,-0.373947,0.401983,-0.084225,0.156617,0.060086,-0.294208,0.039413,0.454972,0.396759,0.266230,-0.398615,-0.060009,-0.259931,0.115205,0.668915,-0.052745,0.267672,0.170952,0.361363,-0.224314,0.258983,-0.548485,-0.211447,-0.052646,0.288408,0.278540,-0.044819,0.519370,-0.226837,-0.144702,-0.546729,0.313302,0.023462,-0.034939,0.002656,-0.274454,-0.222096,-0.091122,-0.254517,0.125686,0.187811,-0.292532,0.370645,-0.858792,0.325719,-0.105005,0.298804,-0.347767,0.469073,0.221095,0.348903,-0.153479,-0.084604,0.490686,0.181633,0.130447,0.042252,-0.097250,-0.262192,0.379307,-0.514327,0.119134', '30345227', '1433736', '4202326', '1301381');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3736691', '特工强档', '喜剧', '谁都无法想到，外表美丽可爱的安秀智（金荷娜 饰）竟是一名有着六年工作经验的资深情报人员。鉴于职业的敏感性，连秀智的男朋友李在俊（姜志焕 饰）也不知道女友的真实身份，也因此两人误会丛生。即使在俊即将前往俄罗斯留学之际，秀智依旧为抓捕罪犯无暇他顾，两人的恋情就此定格。三年时光转瞬即逝，从俄罗斯学成归国的在俊如今是一名国际会计师，而他的真实身份竟也是一名情报人员。刚刚入行不久的他纰漏不断，此时他奉命回国调查某俄罗斯黑帮分子。因缘巧合，他邂逅伪装成清洁工的秀智。两人不知道对方的身份，更不知道他们执行的是同一桩任务……©豆瓣', '金荷娜', '申太罗', 6.7, 35386, 'tt1432078', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1298048006.jpg', 1.1, 8.1, 52.1, 31, 7.7, '0.335995,0.063834,-0.603127,0.621079,-0.208799,-0.037168,0.508750,-0.115387,-0.524166,-0.631694,0.379768,0.774894,0.014161,0.118239,0.167026,-0.105503,-0.125107,-0.677873,0.038686,-0.419027,-0.093786,-0.442760,-0.430022,-0.091180,-0.063640,-0.235353,0.798324,0.178407,-0.299164,0.341929,0.652244,0.396018,-0.270274,0.448598,-0.057666,-0.321589,0.303360,0.225345,-0.189583,0.067893,0.051169,-0.592761,-0.208283,0.031812,-0.077191,0.454092,0.468179,0.125673,-0.436437,0.007476,0.361723,-0.448066,-0.101103,-0.002941,0.588787,-0.281264,0.126219,0.459672,-0.084323,0.268107,0.093872,-0.049060,-0.739569,0.140275,0.126142,0.528436,-0.404606,0.305136,-0.362384,-0.243368,-0.048763,-0.307148,0.061049,0.630743,0.104116,0.096392,0.012561,0.200962,-0.560359,0.411823,0.944893,0.302281,-0.201481,0.479198,-0.276698,-0.620626,-0.281466,-0.215173,-0.334157,0.156514,-0.128474,0.077046,-0.208028,0.256509,-0.298347,-0.110361,-0.198835,0.073122,-0.197065,-0.369312,0.083051,-0.496557,-0.333033,-0.607861,-0.395656,0.316137,0.139027,-0.166095,0.537659,-0.962181,-0.074909,0.477883,0.151295,-0.725575,0.663055,0.402718,-0.103199,-0.509034,-0.106648,0.138416,0.170964,0.047261,-0.083395,0.302216,0.114697,-0.390513,-0.281905,0.136338', '25721544', '1293265', '1301022', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3737102', '艋舺', '剧情', '蚊子（赵又廷 饰）17岁那年搬到艋舺，因为一根鸡腿踏入了黑道，认识了和尚（阮经天 饰）、志龙、阿伯还有白猴四个好兄弟，五人结为太子帮。太子帮秉持只识意气，不问意义的精神，凭借志龙的父亲Geta（马如龙 饰）的黑道地位在学校呼风唤雨。踏入黑道就意味着要经历腥风血雨，然而和尚作为众人的守护神总能帮他们化解危机。艋舺传统的黑道秩序遭受着现代文明的威胁，外省人灰狼（钮承泽 饰）要求和艋舺的老大们合作遭到拒绝。此时，和尚由于得知父辈们之间的事情对Geta心怀不满，加之文谦的怂恿而卷入一场阴谋。艋舺局势暗潮汹涌、杀机四伏，五兄弟在黑道与友情的决择中，演绎了一段关于青春的悲情故事。导演钮承泽称《艋舺》是“生猛又华丽的青春动作片”。本片于2010年春节档在台湾上映，首周票房达6000万新台币，刷新了台湾本土电影的首周票房纪录。©豆瓣', '赵又廷', '钮承泽', 7.7, 263963, 'tt1604900', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1521593812.jpg', 0.4, 2.2, 27.3, 51.4, 18.8, '-0.153278,-0.080363,-0.259258,0.409358,0.309914,0.077877,0.461899,0.304822,-0.469084,-0.117559,0.264505,0.517405,-0.169161,-0.004769,0.393977,-0.352017,0.066279,-0.667298,0.077010,-0.028797,0.361852,-0.170249,-0.339155,0.000011,-0.314604,-0.278090,0.641227,0.282352,-0.367425,0.541702,0.388687,0.082677,-0.329325,0.157721,0.104488,0.040820,-0.002533,0.142198,-0.672897,0.247357,-0.161106,-0.279990,-0.109169,-0.122742,0.007107,0.151226,0.425391,0.005770,-0.092474,0.108440,0.317878,-0.186643,-0.365452,0.177670,0.469516,0.017487,0.331421,0.460935,0.043680,0.183545,-0.053249,-0.272746,-0.640218,-0.026508,0.125107,0.224388,-0.458920,0.546601,-0.210922,-0.093445,0.041936,0.027207,0.018163,0.243958,0.400757,0.429539,-0.010244,0.256417,-0.427738,0.266055,0.693921,-0.071324,0.044759,0.109979,0.177076,-0.355103,-0.404378,-0.478347,-0.273834,0.154411,0.208613,-0.275689,-0.301679,0.411794,-0.667728,0.041927,0.021164,-0.163215,0.170909,-0.186737,0.104764,-0.569146,-0.367470,-0.490082,-0.051339,0.027073,0.339443,-0.161104,0.825329,-0.626808,0.183973,0.200412,0.286745,-0.457530,0.606738,0.344723,0.090153,-0.342841,-0.000273,-0.021244,-0.098774,0.098410,0.105430,-0.000110,-0.151136,-0.450932,-0.001516,0.077679', '4301278', '27602116', '3811356', '1308424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3737117', '秋喜', '剧情', '1949年10月1日，解放战争进入第三阶段末期，国民党盘踞东南重镇广州顽抗，但固守无望的形势下，国民党方面计划在撤往台湾之前破坏广州市基础设施以阻挠解放。潜伏国民党内部的中共情报员晏海清（郭晓冬 饰）跟随军统处长夏惠民（孙淳 饰）多年，此次接受组织任务，由夏惠民处窃取阻挠计划的详细内容。肃杀气氛笼罩下的广州，晏海清在险若踩钢丝的碟报工作中小心前行，身边只有一个年轻单纯的女佣秋喜（江一燕 饰）陪伴，面对后者感恩般的爱意，晏海清态度躲闪无法正视，与此同时，夏惠民对这位可疑下属的看法也似乎超越了一般意义的工作关系，潜藏着别样的内容……©豆瓣', '郭晓东', '孙周', 5.9, 8690, 'tt6286308', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2375014807.jpg', 5.2, 21.7, 51.1, 18, 4.1, '-0.025396,0.143495,-0.508500,0.619892,0.051086,0.138282,0.164963,0.284777,-0.459329,-0.203298,0.083599,0.012175,0.097528,-0.341472,0.111100,-0.320034,-0.300847,-0.743949,-0.105363,-0.209122,0.014771,-0.520091,-0.234913,-0.431549,-0.083186,-0.096586,0.647679,0.564943,-0.386402,0.231125,0.117924,0.199578,-0.406471,0.339879,0.359195,-0.453886,0.147600,-0.048020,-0.488998,0.200638,-0.132187,-0.140054,-0.147389,-0.010840,0.173397,0.509989,0.532422,-0.202670,-0.262199,-0.119363,0.339434,-0.129567,0.123717,0.073520,0.468481,0.350103,-0.014923,0.398739,-0.168173,-0.003275,-0.161631,-0.281876,-0.487971,-0.183482,0.111876,0.178798,-0.451273,0.176115,0.034718,0.356867,-0.159878,-0.403935,0.044258,0.537764,0.272320,0.259154,-0.074288,0.325836,-0.003016,0.207501,0.528667,-0.060176,-0.315423,-0.113895,-0.322918,-0.279473,-0.039452,0.006295,-0.137742,-0.231779,-0.064716,0.099365,0.166648,0.040570,-0.209478,-0.039477,-0.082083,-0.012411,-0.136813,-0.142332,-0.007758,-0.541937,-0.157926,-0.279263,-0.261321,0.197512,0.211013,0.026246,0.462171,-0.552952,0.130637,0.423584,0.355102,-0.442057,0.524894,0.268004,-0.046977,-0.428806,-0.108488,0.522644,-0.192222,0.188162,-0.103823,0.049783,-0.383130,-0.215740,-0.123238,0.119298', '6041191', '6101834', '25723905', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3737278', '寻找成龙', '喜剧', '16岁的男孩张一山（张一山 饰）是一个生在北京长在印尼，并且中文不太灵光的小华侨。在成龙功夫片风靡世界的时代，张一山也不例外，成为了成龙大哥最坚实的Fans之一。他进入功夫学校学习武功，做梦和写作文都离不开成龙，最大的愿望就是亲眼见见自己的偶像。某日，张一山得知成龙正在北京潭柘寺拍戏，为了见到偶像，他一反常态决定回北京的姥姥家。这个鬼灵精的男孩并未按奶奶要求的那样去姥姥（田华 饰）那学习中文，而是直接坐上出租车前往潭柘寺。只不过，他这次吃了中文差的亏，原本要去潭柘寺，结果反被司机（王学兵 饰）拉到了清石观。自此，张一山开始了一波三折并且险象环生的寻找成龙之旅……本片为成龙首次投拍的儿童片，由中影集团副总经理江平执导，中国电影界老中青四代演员联袂出演。©豆瓣', '张一山', '方刚亮', 3.9, 16064, 'tt1478291', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1570153120.jpg', 37.8, 35.2, 21.5, 3, 2.5, '0.081444,-0.074576,-0.661200,0.412377,-0.014979,-0.446056,0.192415,0.212509,-0.305795,-0.367668,0.265397,0.822481,-0.002410,0.189533,0.225328,-0.011170,-0.187174,-0.255024,0.057914,-0.046789,0.102344,-0.268335,-0.113710,0.213120,-0.054681,-0.047659,0.523573,-0.271759,-0.254121,0.437761,0.412178,-0.086507,0.203923,0.084108,-0.327999,0.256589,-0.002352,0.079597,-0.221639,0.318187,0.184124,-0.055297,-0.024492,-0.046775,0.035404,0.130138,0.476572,0.024263,-0.070082,-0.112523,0.328940,-0.338281,-0.373745,-0.090132,0.204736,-0.010491,0.438811,0.092120,0.090390,0.206368,-0.143163,-0.302562,-0.526231,0.262373,0.236064,0.031486,-0.646315,0.267383,-0.002079,-0.238877,-0.061840,-0.608273,0.182914,0.333074,0.079640,0.272124,-0.246396,0.244869,-0.324768,0.599700,0.699101,0.075494,0.089437,0.428228,0.146769,-0.384595,0.107362,-0.264107,-0.299971,0.245975,0.029509,-0.199793,-0.255635,-0.133653,-0.376343,-0.077331,-0.109596,-0.065948,0.149969,-0.210045,0.008173,-0.537281,0.035415,-0.320857,0.266598,-0.358727,0.046778,-0.242005,0.674082,-0.761791,0.088221,0.232739,0.282414,-0.492450,0.762700,0.095528,-0.029765,-0.396350,-0.023531,0.005120,-0.061670,0.407988,-0.178657,0.311769,0.061625,-0.507808,-0.345993,0.241322', '1292720', '26958479', '2080130', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3737287', '袁隆平', '剧情', '《袁隆平》讲述的是袁隆平30岁至60岁阶段的故事，以杂交水稻始祖——“三系配套”的研究为主线展开。看完影片后，来自隆平种业的谭志军、范小兵告诉记者，虽然他们熟悉袁院士，不过影片以鲜活艺术手法再现的科学家心忧天下、造福人类、自强不息、淡泊名利等情操，依然十分动情、感人。', '果靖霖', '史凤和', 9, 8388, 'tt11496490', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2650578179.jpg', 0.8, 1.2, 8.6, 24.1, 65.3, '-0.044988,-0.202832,-0.223761,0.654450,0.071327,-0.072450,0.417124,-0.133116,-0.733129,-0.535092,-0.152011,0.179876,-0.123026,0.364132,0.249233,-0.315131,-0.172649,-0.195165,-0.193893,0.306350,-0.093508,-0.404700,-0.156751,-0.170611,-0.235660,-0.224004,0.397289,0.110372,-0.153933,0.485807,-0.094774,0.106618,0.081888,0.004661,0.082481,-0.142343,-0.108376,-0.036523,-0.610824,-0.076445,0.297313,-0.275074,-0.091234,0.016684,-0.313637,0.237640,0.406418,-0.172644,0.001301,-0.106277,0.785119,-0.080777,-0.051848,-0.124543,0.304250,0.374095,0.110303,0.007597,0.251505,0.172588,-0.355663,-0.346826,-0.803154,-0.041282,0.262826,0.155922,-0.315240,0.083496,0.125832,0.289782,0.059554,-0.373396,-0.051237,-0.178142,0.660832,0.609541,0.247009,0.070404,-0.187499,0.550366,0.306813,0.180554,-0.526727,0.287486,-0.162800,-0.907309,0.102920,-0.379605,-0.229544,0.156079,-0.011493,0.135956,0.380342,0.008504,-0.533890,-0.004223,0.141216,0.065998,0.102279,-0.170543,-0.184702,-0.556209,0.024970,-0.506165,-0.012113,0.041550,0.292513,-0.686834,1.053894,-0.495440,-0.136946,-0.355929,-0.146431,-0.336643,0.718186,-0.250783,-0.306930,-0.573888,-0.317702,0.369582,-0.050810,0.129064,-0.033968,0.212588,-0.025230,-0.426493,-0.515697,0.400976', '27602116', '22265121', '24284209', '35280911');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3742360', '让子弹飞', '剧情', '民国年间，花钱捐得县长的马邦德（葛优 饰）携妻（刘嘉玲 饰）及随从走马上任。途经南国某地，遭劫匪张麻子（姜文 饰）一伙伏击，随从尽死，只夫妻二人侥幸活命。马为保命，谎称自己是县长的汤 师爷。为汤师爷许下的财富所动，张麻子摇身一变化身县长，带着手下赶赴鹅城上任。有道是天高皇帝远，鹅城地处偏僻，一方霸主黄四郎（周润发 饰）只手遮天，全然不将这个新来的县长放在眼里。张麻子痛打了黄的武教头（姜武 饰），黄则设计害死张的义子小六（张默 饰）。原本只想赚钱的马邦德，怎么也想不到竟会被卷入这场土匪和恶霸的角力之中。鹅城上空愁云密布，血雨腥风在所难免……本片根据马识途的小说《夜谭十记》中的《盗官记》一章改编。©豆瓣', '姜文', '姜文', 9, 1575891, 'tt1533117', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1512562287.jpg', 0.3, 0.7, 8.2, 32.3, 58.5, '-0.039019,-0.154649,-0.211728,0.522167,0.025001,-0.370908,0.336240,0.221483,-0.311914,-0.431260,0.416090,0.294943,0.119466,0.135837,0.097983,-0.095079,-0.038301,-0.270586,-0.228578,-0.001937,0.171410,-0.401814,-0.258894,0.011547,-0.075966,0.217413,0.253184,0.250627,-0.297690,0.326942,0.512955,-0.125042,-0.261140,0.161595,0.029853,0.343403,-0.126177,-0.115561,-0.281231,-0.276193,-0.063845,-0.415649,-0.105701,-0.274333,0.214491,0.336533,0.436137,-0.201115,0.018310,-0.044351,0.236945,-0.407318,0.092343,-0.008616,0.431884,-0.106621,0.269200,-0.143227,-0.185669,0.086983,0.058690,-0.116100,-0.295198,0.158433,0.213620,0.090899,-0.352445,0.074675,-0.004618,-0.044287,-0.008238,-0.161860,0.283238,0.139083,0.154937,0.113045,0.096098,0.153721,-0.560285,0.584571,0.362009,0.004493,0.125116,-0.407792,0.262518,-0.277140,0.094785,-0.231088,-0.303169,0.039565,0.268471,-0.349766,0.268489,0.069557,-0.443628,-0.089378,-0.337105,0.327031,-0.031483,0.154526,-0.116045,-0.244591,-0.101789,-0.035442,0.250778,0.126609,0.460127,-0.156478,0.253013,-0.181253,0.023651,-0.168874,0.010160,-0.347695,0.344812,0.254414,0.116374,-0.306536,-0.149795,-0.206581,0.553815,0.281736,0.201880,0.146609,-0.333845,-0.385029,0.300083,0.265370', '1307747', '3892449', '6753166', '4707596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3742937', '超级战舰', '动作', 'NASA在2005年的时候发现了一个太阳系外的类地行星，并判断其上可能存在智慧生命。为了能与外星智慧生物接触，NASA启动“灯塔计划”，在夏威夷启用深空通信阵列基地，向其发射高功率信号进行试探。几年后，外星飞船不期而至。身处夏威夷的太平洋联合海军演习舰队受命进行接触。男主角海军中尉阿历克斯（泰勒·克奇 Taylor Kitsch 饰）所在的导弹驱逐舰及其他两艘军舰被作为侦查小队，受命接触外星舰船。却因此受到攻击，损失惨重。由于外星舰船展开的护盾原因，联合舰队的其他舰船无法实施支援，完全只能靠自己苦苦支撑。最后，三艘现代舰船被全部摧毁。由于无船可用，但是又必须摧毁被外星人占领的通讯站，只能启用被改为海上博物馆的密苏里号战列舰进行最后的攻击。二战时期的王牌战列舰对阵外星高科技舰船，谁能胜出？地球的命运到底如何？©豆瓣', '泰勒·克奇', '彼得·博格', 6.7, 127171, 'tt1440129', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1505422082.jpg', 2.1, 10.8, 47.7, 30.4, 9, '0.106541,0.178832,-0.963441,0.690659,0.191561,0.255368,0.328529,-0.265610,-0.362639,-0.016177,0.164872,0.447296,0.450256,-0.443434,-0.085123,-0.061220,-0.469185,-0.259218,0.052413,-0.037592,-0.540039,-0.594996,-0.396504,-0.219337,0.406716,-0.630609,1.009349,0.160730,-0.477464,0.001515,-0.023675,0.399434,-0.032192,0.596526,-0.011451,-0.513806,0.063081,-0.419118,-0.249783,0.381042,-0.636707,-0.029654,0.282660,0.124327,-0.237914,0.380446,0.999480,-0.332556,0.183822,-0.604275,-0.114772,-0.154840,0.349191,-0.075892,0.651302,0.158277,-0.617555,-0.069747,0.102561,0.156343,0.171713,0.340054,-0.712758,-0.290803,-0.177939,-0.302836,-0.055933,-0.253579,-0.501272,0.265731,-0.344156,-0.028235,0.228972,0.807981,0.368370,0.025871,-0.469474,0.466729,-0.602769,0.038971,0.531580,-0.255414,-0.600210,0.099695,0.142950,-0.540590,-0.460224,-0.725054,-0.099575,-0.105332,0.249209,0.262789,0.021203,0.368306,-0.981290,0.357902,-0.600709,-0.618454,-0.078808,-0.373336,0.037464,-1.212721,0.273512,-0.132678,-0.182593,0.601604,0.153210,0.126707,0.783938,-0.432790,-0.086048,0.678663,0.570325,-0.413401,0.557438,0.275646,-0.065035,-0.557556,0.247215,0.385112,-0.041385,0.564070,-0.097644,0.017329,0.313198,-0.130354,-0.103566,0.110288', '2369613', '1306809', '1307897', '1293013');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3742987', '小小的白色谎言', '剧情', '每一年，餐馆老板马克思（弗朗索瓦·克鲁塞 François Cluzet 饰）都会请他的朋友们来到他在海边的别墅度假，而这一年的假期，却被一场发生在卢多（让·杜雅尔丹 Jean Dujardin 饰）身上的严重车祸蒙上了阴影。为了冲淡悲伤，朋友们决定像往常一样前往海边。文森特（伯努瓦·马吉梅 Benoît Magimel 饰）的心情非常沉重，他发现他对自己同性好友马克思的爱意随着时间的流逝愈演愈烈，已经到了无法掩饰的地步，但事实是，他们均已结婚生子。玛丽（玛丽昂·歌迪亚 Marion Cotillard 饰）也不轻松，她身边围绕着一群她并不喜欢的男人，真正爱着的，却是此刻躺在病床上生命垂尾的前男友卢多，并且，在这个节骨眼上，她发现自己有了身孕。一向对自己的魅力充满自信的安东尼（Laurent Lafitte 饰）却被劈腿，表面上豁达的他却不能克制的一遍遍的质问心上人为何将他抛弃。每个人都想在这宁静的海边短暂的忘却烦恼，但烦恼又是如此狡猾的在千疮百孔的生活中无孔不入，于是，作为成年人，他们不得不互相编制起小小的，善意的白色谎言。', '玛丽昂·歌迪亚', '吉约姆·卡内', 8.2, 15303, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p693375939.jpg', 0.4, 1.9, 17.9, 47.2, 32.5, '0.239978,0.193139,-0.896734,0.602771,-0.358386,-0.044222,1.100993,0.059080,-0.567744,-0.118046,0.227052,0.660008,-0.304417,0.374487,0.101973,0.167916,-0.228539,-0.682925,0.004460,-0.099060,-0.256994,-0.452604,-0.389965,-0.223173,-0.239971,-0.191257,0.422787,0.226763,0.028499,0.353619,0.386408,0.287888,0.210319,0.830792,-0.201532,0.031733,-0.123516,0.089308,0.101108,-0.063416,0.175373,-0.274165,-0.165394,0.454201,-0.061846,0.383512,0.774278,-0.048205,-0.243558,0.063256,0.306030,-0.242126,0.087774,0.283423,0.178852,-0.006855,0.112149,0.227135,-0.113476,-0.112909,0.148432,0.146170,-0.646488,0.078183,-0.011469,0.256817,-0.633337,0.813695,-0.087019,-0.065463,-0.169341,-0.345277,0.033709,0.090888,-0.029759,0.371068,-0.288849,-0.104040,-0.565131,0.129003,0.778033,0.180680,-0.326119,0.606754,-0.658845,-0.250529,-0.164898,-0.257824,-0.503254,-0.239698,0.123736,0.191787,-0.277874,0.297186,-0.422044,0.029752,-0.167185,-0.163667,-0.151003,-0.589839,-0.002722,-0.320338,-0.157333,-0.715504,-0.610704,0.161144,0.025625,-0.266381,0.589435,-0.783114,0.256958,0.506768,0.253432,-0.308493,0.604203,0.335460,-0.101713,-0.110974,-0.151074,0.477288,-0.151992,0.218486,0.318072,0.418029,-0.101312,0.107105,-0.643785,0.850677', '1307561', '1292211', '1417428', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3743049', '潜水艇', '剧情', '十五岁的奥利弗（克雷格•罗伯兹 Craig Roberts 饰）坐在教室里的时候脑中总是充满各种幻想，周围的一切对他来说都是普通中蕴含奇异的存在。在同学里他总是显得不合群，他注意到同学祖娜（雅思敏•派吉 Yasmin Paige 饰）也是如此。祖娜在铁桥下约见奥利弗并拍下两人亲吻的照片以此来刺激前男友，奥利弗为此付出了被祖娜前男友教训的代价，而这却让两个人真正走在一起了。奥利弗的父母关系紧张，眼下他又发现母亲和隔壁新搬来的格雷厄姆走的很近，他开始试图挽救自己的家庭。而祖娜的母亲正患脑瘤，奥利弗想要解决问题却分身乏术，和祖娜误会重重最终导致两人分手。最后他的父母重归于好，祖娜的母亲也病愈。而他和祖娜将走向什么结局呢？©豆瓣', '克雷格·罗伯兹', '理查德·艾欧阿德', 7.7, 23119, 'tt1440292', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1145040438.jpg', 0.4, 2.6, 28.9, 47, 21.1, '0.550626,0.059073,-0.728515,0.482153,-0.280790,-0.362814,0.948859,0.146876,-0.461665,-0.287523,-0.006952,0.872687,-0.246420,0.453521,0.005276,0.095311,-0.266949,-0.665341,0.027100,0.016371,-0.419118,-0.539596,-0.112828,-0.100500,-0.199210,0.001757,0.322515,-0.023719,-0.229402,0.416705,0.223277,0.189407,0.003399,0.745838,-0.103134,0.124532,-0.141443,0.120804,0.065045,0.068787,0.327937,-0.384181,-0.185173,0.414747,-0.028332,0.560557,0.574856,-0.171697,-0.068378,0.127119,0.232798,-0.321633,-0.115301,0.314383,0.137042,-0.059418,0.195525,0.216921,-0.289600,-0.031090,-0.017630,0.095073,-0.690277,-0.046936,0.018909,0.128180,-0.689789,0.543180,0.065658,-0.065011,0.335590,-0.230084,0.219895,0.442827,-0.060261,0.389546,-0.277353,-0.147728,-0.419526,-0.037839,0.807431,-0.102428,0.025223,0.445632,-0.485851,-0.289652,-0.036739,-0.118348,-0.376850,-0.139644,0.136628,0.097544,-0.126825,0.004751,-0.457321,0.041204,-0.205131,-0.020936,-0.234200,-0.574634,-0.066844,-0.476466,-0.214118,-0.634548,-0.458801,0.076222,-0.100531,-0.410881,0.519194,-0.663329,0.052171,0.520211,0.461104,-0.283947,0.711259,0.226036,-0.064452,-0.223376,-0.164330,0.219303,-0.083868,0.276271,0.138155,0.197938,0.082386,0.084014,-0.473307,0.598177', '1296370', '1309172', '3111650', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3743052', '完美感觉', '剧情', '这是一场发生在世界末日即将来临时的末世之恋。流行病学家苏珊（伊娃·格林 Eva Green）与餐厅主厨麦克（伊万·麦克格雷格 Ewan McGregor）相识、相恋，但无奈此时此刻的世界正在遭受一场新型流行病的侵袭。随着流行病的蔓延，患者会伴随着情绪失控逐渐丧失味觉、嗅觉 、听觉、直至最后丧失视觉。虽然苏珊和麦克都尽量努力避免患病，但当作为厨师的麦克不再能尝出食物的味道，作为科学家的苏珊也渐渐丧失感觉，这对末世情人便已知晓无人能够逃脱这场灭顶之灾。两人于是选择珍惜仅有的彼此，最后在逐渐模糊的视线中拥抱住对方。©豆瓣', '伊万·麦克格雷格', '大卫·马肯兹', 7.6, 24449, 'tt1439572', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1708029562.jpg', 0.6, 3.7, 30.6, 45.7, 19.5, '0.147886,0.214328,-0.477956,0.312171,0.244220,-0.010851,0.915073,0.170695,-0.579188,-0.202095,0.191191,0.608771,-0.215079,0.162299,0.257854,-0.288699,-0.407386,-0.854178,-0.123212,-0.003157,-0.176235,-0.343943,-0.447850,-0.183148,-0.160947,-0.232166,0.633648,0.159899,-0.472907,0.477569,0.025543,0.228700,0.060000,0.686177,0.059932,-0.078861,0.115372,-0.239879,-0.667768,0.012738,0.507087,-0.192528,-0.109861,0.164825,-0.068506,0.243572,0.748554,-0.420501,-0.235213,-0.070197,0.177958,-0.151167,0.086420,0.180791,0.220011,0.057533,0.053880,-0.028886,-0.055494,0.074526,-0.034789,0.290812,-0.703179,0.207448,0.091170,0.339108,-0.009377,0.154902,0.098069,-0.061532,0.210630,-0.053453,-0.064555,0.430136,0.516799,0.486294,-0.381653,0.051162,-0.376440,-0.214842,0.953023,-0.071600,-0.542604,0.556098,-0.599456,-0.771446,-0.100842,-0.167996,-0.409187,-0.005172,0.142437,0.768581,-0.278939,0.846327,-0.527610,0.045920,-0.186104,-0.492008,0.049132,-0.234144,-0.047419,-0.826907,-0.597180,-0.337247,-0.085784,0.168833,-0.080944,-0.200001,0.497660,-0.821327,0.393998,0.502492,0.016815,0.051760,0.482227,0.169284,0.104424,-0.290039,-0.124299,0.616525,-0.312330,0.337665,0.353576,0.210629,0.027764,0.361782,-0.294705,0.575236', '25828589', '11541282', '3059036', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3743114', '黄海', '剧情', '为了能让妻子去韩国打工，出租车司机久南（河正宇 Jeong-woo Ha 饰）不惜借6万块钱的巨款。妻子已经有六个月没有消息了，久南每日只能用酒精和赌博来麻醉自己的神经。一天，在债主的介绍下，久南认识了绵先生。绵先生不仅愿意帮助他偷渡到韩国寻找妻子，而且愿意为他还掉所有 的债务，条件是让他在首尔杀一个人。几经波折，久南最终渡过茫茫黄海到达首尔，然而要杀死被严密保护的对象并不那么容易，久南一边开始周密的计划，一边开始到处打听妻子的下落。妻子就像从人间消失了一样音讯全无，而并没有杀人的久南却因出现在凶案现场而成为警方通缉的疑犯。此时，由于怕买凶杀人的事情暴露，从延边赶来的绵先生也极力致久南于死地，久南几乎陷入绝望的境地……河政宇凭借此片获得第47届百想艺术大赏颁奖礼最佳男演员奖。©豆瓣', '河正宇', '罗泓轸', 8.5, 204568, 'tt1230385', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1075586949.jpg', 0.2, 0.9, 12, 47.1, 39.8, '-0.070383,0.156309,-0.502936,0.397963,-0.136427,-0.185740,0.317752,0.087405,-0.520778,-0.336453,0.019965,0.678717,0.083258,0.005274,0.123820,0.083131,-0.182828,-0.623601,-0.083818,-0.142502,-0.255436,-0.512285,-0.040722,-0.143234,-0.054655,-0.208676,0.521562,0.252338,-0.098302,0.409298,0.445417,0.094347,-0.147938,0.623835,-0.260043,0.053461,0.084820,0.167269,-0.395231,0.544224,0.083553,-0.361931,-0.021059,0.168130,0.113059,0.287749,0.555305,-0.097221,-0.176677,0.149848,0.359250,-0.430690,-0.111722,0.224275,0.443289,-0.087862,0.416818,0.137323,-0.483212,0.197386,0.286200,0.084467,-0.898955,-0.149652,0.088501,0.029730,-0.570868,0.203101,-0.154700,0.033931,0.033454,-0.260626,0.352728,0.387803,0.150791,0.135147,-0.201556,-0.182438,-0.510013,0.277160,0.808038,-0.126326,0.154129,0.326444,0.017234,-0.290650,0.023452,-0.403896,-0.167924,0.112035,0.223153,0.128660,-0.284195,0.065246,-0.251622,-0.035536,-0.241972,-0.386086,0.006697,-0.297383,-0.164824,-0.322090,-0.008806,-0.022835,-0.107771,0.228426,0.048265,-0.406870,0.350749,-0.644475,0.220927,0.870101,0.401678,-0.598543,0.519898,0.200098,-0.095863,-0.193386,-0.256178,0.072224,0.087322,0.565643,0.354049,-0.041851,-0.167768,-0.289644,-0.380757,0.201955', '26678784', '25908042', '1835843', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3744545', '漂亮朋友', '剧情', '根据“短篇小说之王”莫泊桑的同名小说《漂亮朋友》改编而成。老兵乔治·杜瓦洛（ 罗伯特·帕丁森Robert Pattinson 饰）退伍后从非洲只身来到巴黎，在铁道局打杂过着清苦交加的日子。偶然机会碰到昔日战友，在其帮助下进入《法兰西生活报》担任编辑一职，苦心钻营成为“瓦尔特帮”的重要写手，参与倒戈阴谋。凭借一张漂亮的外表和一些取悦女人的伎俩辗转于贵妇人之间，克罗蒂尔德（克里斯蒂娜·里奇 Christina Ricci 饰），玛德莱纳（乌玛·瑟曼 Uma Thurman 饰），瓦尔特夫人（克里斯汀·斯科特·托马斯 Kristin Scott Thomas 饰）都成为他平步青云的牺牲品，他无耻的利用女人来发迹，大搞投机冒险，步步为营跻身上流社会，并最终通过拐骗报馆老板瓦尔特的女儿苏珊（霍利·格林格 Holliday Grainger 饰），与之结婚成为报社总编辑，将权钱名并入囊中，成功得取远大前程。', '罗伯特·帕丁森', 'Declan Donnellan', 6.1, 17299, 'tt1440732', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1653824923.jpg', 3.1, 18.3, 54.2, 19.2, 5.2, '0.024309,0.128079,-0.398088,0.411733,-0.101041,-0.215306,0.297050,0.069445,-0.401281,-0.205906,-0.004707,0.616043,-0.202499,-0.024120,0.445066,0.034771,-0.381636,-0.546014,0.198153,-0.144606,0.208153,-0.545723,-0.449889,-0.101653,-0.081128,-0.394307,0.499004,-0.059259,-0.139723,0.135279,0.413816,0.319250,-0.102431,-0.077189,0.114989,-0.014292,0.433606,-0.113416,-0.544559,0.260000,-0.289584,0.069271,-0.126161,-0.351109,0.094954,-0.003441,0.365761,-0.179694,0.180456,-0.231611,0.309089,0.021394,0.084705,-0.046971,0.136610,0.131922,0.201489,0.359609,-0.140462,0.118024,0.163842,-0.260591,-0.527527,0.204710,0.184953,0.028171,-0.453094,0.139704,-0.208530,0.087963,0.013675,-0.448238,-0.007350,0.324497,0.262548,-0.003265,0.091601,0.490656,-0.336979,0.202669,0.443209,0.010269,-0.217434,-0.080728,0.080784,-0.204918,0.288024,-0.437887,-0.332887,-0.021392,0.202291,-0.327601,0.211149,0.294050,-0.428620,-0.158690,-0.383861,0.120828,0.361097,-0.110181,0.054032,-0.725469,-0.129813,-0.067125,-0.144299,-0.150572,0.136212,-0.436567,0.525249,-0.500968,0.157022,0.475203,0.178015,-0.395284,0.551337,-0.012749,0.237859,-0.239559,-0.346796,0.378616,0.380536,0.169137,-0.018591,0.176088,-0.020628,-0.280444,0.1