INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3744561', '美国人', '剧情', '特立独行、技术高超的杀手杰克（乔治·克鲁尼 George Clooney饰）来到意大利乡下的一座田园小镇，打算执行完这次任务后金盆洗手——为女杀手组装一支专用步枪。在这相对简单平静的环境里，原本低调谨慎的杰克出乎意料的与当地居民建立了深厚的友谊。不仅如此，他还邂逅了美丽的妓女克莱拉（薇奥兰特·普拉西多 Violante Placido饰），一段浪漫的爱情由此展开。然而，这杀手生涯中的最后一次任务，却远没有想象中的简单。本片根据马丁·布斯的小说《一位非常低调的绅士》改编而成。©豆瓣', '乔治·克鲁尼', '安东·寇班', 6.5, 13455, 'tt1440728', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p514879329.jpg', 1.8, 11.7, 53.1, 26.6, 6.8, '0.504961,0.177045,-0.664572,0.904619,-0.264326,-0.205832,0.834027,-0.071528,-0.260959,-0.266862,0.285771,0.626452,0.014607,-0.317299,0.421373,0.064992,-0.695651,-0.447910,-0.006897,-0.222955,0.011746,-0.636284,-0.493866,-0.293310,-0.168759,-0.128672,0.511578,0.177149,-0.007055,0.637210,0.022362,0.112772,-0.102310,-0.012994,-0.125040,-0.157052,0.377835,-0.025813,-0.334058,0.225545,-0.025618,0.034651,-0.117615,0.248916,0.086182,0.511409,0.543320,-0.305256,-0.252658,0.208877,0.473766,0.037787,-0.123532,-0.064085,0.255998,0.097293,0.141237,0.022833,-0.160243,0.012128,-0.182356,-0.517442,-0.884511,0.054442,0.169521,-0.055199,-0.357829,0.718350,-0.215796,0.048242,-0.109795,-0.318195,-0.075099,0.270520,0.640653,0.241793,0.122499,0.264705,-0.096360,0.389817,0.539562,0.042287,-0.492115,0.474610,-0.351647,-0.617316,-0.055939,-0.348116,-0.358347,-0.072459,0.314889,-0.155435,0.179054,0.236283,-0.744622,0.271067,-0.418735,0.034292,-0.114262,-0.106423,-0.243591,-0.837176,0.062022,-0.394427,-0.125036,-0.104592,-0.192165,-0.206677,0.711609,-0.617134,0.201820,0.416856,0.103060,-0.183750,0.437133,-0.054783,0.350182,0.005262,-0.333759,0.335148,0.036966,0.214692,0.106365,0.699250,0.068301,-0.487311,-0.414205,0.523507', '2053515', '1293433', '1793922', '10763928');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3745292', '初恋红豆冰', '喜剧', '这是一个发生在90年代大马天空下的初恋故事。botak（阿牛 饰）是憨厚老实的卖咖啡的儿子，喜欢上了青梅竹马的单亲家庭女孩“打架鱼”周安琪（李心洁 饰），却一直不敢表达。花痴女孩马丽冰（梁静茹 饰）一心喜欢botak，马丽冰的哥哥马麟帆（ 曹格 饰）却喜欢着打架鱼，botak的胖妹妹暗恋着“白马王子”（黄品冠 饰），.经过一系列的事件众小青年们都换来了人生的成长，看似搞笑的故事中夹杂了亲情、爱情、友情、乡愁。《初恋红豆冰》是阿牛（陈庆祥）的处女作，参加演出的几乎都是来自马来西亚的本土歌手，本片上映时在马来西亚的票房大获350万，几乎刷新当地最高票房纪录。©豆瓣', '阿牛', '阿牛', 7.6, 59698, 'tt1780796', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p616165318.jpg', 0.5, 3.6, 31.3, 45.9, 18.6, '0.031819,-0.098516,-0.512360,0.630060,0.023467,-0.033913,0.634952,-0.014071,-0.284204,0.024246,0.223919,0.519438,-0.275988,0.375221,0.146531,-0.135746,-0.145929,-0.683663,-0.149317,-0.007337,0.057180,-0.086488,-0.273115,0.144134,-0.207713,-0.186665,0.489642,0.055987,-0.287873,0.466918,0.686352,-0.032705,-0.064384,0.184054,-0.155479,0.114892,0.042465,0.218568,-0.224939,-0.069345,-0.296617,-0.200812,-0.015938,-0.078125,0.074269,0.278211,0.649683,-0.310576,0.016372,0.018153,0.538395,-0.123891,-0.146006,-0.112632,0.193475,0.091492,0.526177,-0.010820,0.198297,0.087989,0.059697,-0.101148,-0.570155,-0.005072,0.214795,0.296566,-0.454074,0.557284,0.032890,-0.035214,0.156379,-0.202545,0.111610,-0.208900,0.374083,0.578579,-0.167594,0.188618,-0.523247,0.617756,0.601629,0.118840,-0.256331,0.460992,-0.378972,-0.494848,-0.111898,-0.286224,-0.580040,0.336273,0.038685,-0.229438,-0.116068,0.353677,-0.706660,0.129598,0.321766,-0.329185,0.144536,-0.279417,-0.374755,-0.467263,0.049231,-0.695702,-0.210142,-0.041298,0.154888,-0.363044,1.037752,-0.579345,0.093336,0.528015,0.069354,-0.331905,0.766084,0.364126,-0.194676,-0.240519,-0.225951,0.335256,-0.165081,-0.391387,-0.116997,0.250671,-0.132125,-0.307801,-0.514687,0.609348', '27602116', '26283288', '26348103', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3748544', '美国派(番外篇)7：索爱天书', '喜剧', '距第一部美国派已有10年，三个没救的新处发现了藏在高中图书馆的“索爱天书”。不过不幸的是，书已经残缺不全了。靠着书中不完整的建议，三人踏上了滑稽的破处之旅。', 'Eugene Levy', 'John Putch', 5.9, 14954, 'tt1407050', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1446577153.jpg', 5, 22.7, 52.5, 14, 5.8, '0.665310,-0.220568,-0.563561,0.488839,0.426865,-0.516589,0.430664,-0.258979,-0.496363,-0.315686,-0.065900,0.532278,-0.000152,0.403527,-0.028058,0.175421,-0.113759,-0.556017,-0.149055,-0.494129,-0.617742,-0.650413,-0.252804,-0.049911,-0.318739,-0.568262,0.531799,0.408183,-0.286028,0.596949,0.206552,0.084599,-0.219809,0.147119,-0.670354,0.069458,0.232420,0.253971,0.178333,0.481486,-0.196131,-0.428463,-0.150276,0.029223,-0.005101,0.751201,0.640866,0.138229,-0.308893,0.321304,0.662090,-0.316051,-0.877132,0.078924,0.526599,0.199488,0.104489,0.126861,-0.325211,0.171138,-0.115249,-0.443165,-0.888053,-0.265223,0.242937,0.111990,-0.677672,1.047910,-0.129776,0.038343,-0.089771,-0.545863,0.442715,0.543956,0.007104,0.547028,0.345129,-0.125271,-0.677025,0.293381,0.494859,-0.056827,-0.250542,0.816753,0.343745,-0.455777,-0.060038,-0.209328,-0.081933,0.415027,0.406866,0.111536,-0.236979,-0.235249,-0.968908,0.051393,-0.122058,-0.214930,-0.043344,-0.453271,-0.263814,-0.165190,-0.460336,-0.360203,-0.357632,0.112357,-0.170306,-0.496438,0.802607,-0.643381,0.520916,0.232805,-0.304066,-0.467119,1.068281,0.056141,-0.300115,0.013745,0.476801,0.101072,-0.072647,0.579010,0.268457,0.491674,0.011591,-0.909972,-1.025045,0.489972', '5327188', '1473562', '3236520', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3749172', '超人与蝙蝠侠：公众之敌', '剧情', '近未来，金融危机席卷美国，失业率和犯罪率飙升，各大主要城市纷纷爆发抗议与动乱。始终与超级英雄作对的莱克斯•卢瑟摇身一变成为总统候选人，他采取强硬的手段镇压暴动，并向选民许下美好前景，最终他如愿以偿当上美国总统。上任之初，卢瑟强化国家集权，先后将原子队长、黑闪、力量女神、武士刀等超级战士招至麾下，其声势空前壮大。而超人和蝙蝠侠对卢瑟的做法心存顾虑，始终不与之合作。与此同时，一颗小行星飞临地球。卢瑟以联手阻止小行星为由与超人会面，结果却派出金属电子人对超人进行攻击。一番激战过后，超人在蝙蝠侠的帮助下侥幸逃脱，而金属电子人则被神秘之人杀害，卢瑟据此栽赃超人。曾经的超级英雄一瞬间成为公众之敌……©豆瓣', 'Kevin Conroy', 'Sam Liu', 7.4, 6147, 'tt1398941', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2236463160.jpg', 0.4, 3.8, 37.8, 40.9, 17.1, '-0.227941,0.036621,-0.696788,0.665185,0.186825,0.079321,0.502391,0.163427,-0.411867,-0.238205,0.295525,0.820285,-0.297376,-0.279419,0.200956,-0.569556,-0.099060,-0.720996,-0.119148,0.087497,-0.056145,-0.502506,-0.458585,-0.143428,-0.080125,-0.369755,0.866669,0.025769,-0.467742,0.374340,0.356722,0.455952,-0.248966,0.587377,0.065774,-0.527345,0.086064,-0.154711,-0.641623,0.431637,-0.248347,-0.220965,0.204673,0.199623,-0.398579,0.142010,0.389162,-0.575706,0.153824,-0.665736,0.123219,-0.448805,-0.038153,0.095839,0.448513,0.135724,0.059532,0.291695,0.215336,-0.123193,0.053086,-0.094275,-0.770395,-0.059983,0.042409,-0.182042,-0.396916,0.179677,-0.185849,0.130734,0.049137,-0.083396,-0.026980,0.374897,0.233759,0.176081,-0.261904,0.157458,-0.291534,-0.084382,0.725818,0.067581,-0.600385,-0.213420,0.153125,-0.324615,-0.268664,-0.585474,-0.213031,-0.120372,0.107209,0.276033,0.314734,0.558945,-0.745329,-0.097603,-0.429030,-0.099320,0.220819,-0.407880,0.251790,-0.674258,-0.203582,-0.042297,-0.071127,-0.032101,0.193908,-0.193364,0.809709,-0.724012,-0.029842,0.379849,0.651132,-0.661440,0.322509,-0.129478,0.012888,-0.429901,-0.097221,0.138037,0.233110,0.355417,-0.136629,-0.076183,0.085326,-0.155951,-0.037883,0.181575', '5308201', '1308837', '4301278', '26615753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3749943', '到也门钓鲑鱼', '剧情', '鲑鱼专家琼斯博士（伊万·麦克格雷格 Ewan McGregor 饰）供职于英国渔业部门，中年危机让他倍感生活的无趣与疲惫。有一天，琼斯博士突然接到一个看似天方夜谭的任务。一位富有的也门酋长通过其年轻的秘书哈莉特（艾米莉·布朗特 Emily Blunt 饰）联系到琼斯博士，希望借助琼斯博士的智慧帮助他实现在也门钓鲑鱼的梦想。同时，英国政府在这个计划中发现了巨大的政治意义，于是英国首相新闻发言人（克里斯汀·斯科特·托马斯 Kristin Scott Thomas 饰）也兴致勃勃加入了进来。随着工作的进行，琼斯博士与哈莉特之间发生了微妙的变化。但面对已伴随一生的妻子，面对战争归来的男友，琼斯博士和哈莉特的选择将会何去何从？这个横跨两国的神奇计划又将在英国政府的加入后发生什么变化？酋长在也门钓鲑鱼的梦想究竟能否成功？这是一个关于爱、信仰与选择的故事。本片根据英国作家保罗·托迪（Paul Torday）2007年同名小说改编。', '伊万·麦克格雷格', '拉斯·霍尔斯道姆', 7, 15295, 'tt1441952', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1515123002.jpg', 0.6, 5.5, 46.5, 37.9, 9.5, '0.222835,-0.042365,-0.561381,0.607137,0.132187,-0.395266,0.618245,0.044153,-0.498888,-0.459305,-0.003361,0.731846,-0.134547,-0.147945,0.630513,-0.041027,-0.401341,-0.573689,0.146204,0.019429,-0.079426,-0.758105,-0.391216,-0.386954,0.018669,-0.425093,0.688315,-0.019039,-0.146011,0.533068,0.260107,0.488038,-0.091210,0.349108,0.135838,0.031004,0.544333,-0.011069,-0.655575,0.278738,0.220684,0.029524,-0.039005,0.027515,-0.012211,0.191520,0.430390,-0.385742,-0.204319,0.089857,0.383140,-0.231282,0.091047,0.112407,0.374358,0.220533,-0.170711,0.430220,-0.199897,-0.098678,-0.042667,-0.292841,-0.758841,-0.093208,0.105113,0.524077,-0.153926,0.231817,-0.201118,-0.148293,0.171316,-0.288266,0.052891,0.555609,0.471682,0.519077,-0.043279,0.279741,-0.304611,-0.063797,0.511285,-0.023022,-0.396751,0.238042,-0.223705,-0.441846,-0.021598,0.024345,-0.320951,0.101816,0.155643,0.108515,-0.046405,0.418213,-0.640053,0.064353,-0.318029,-0.234379,0.227741,-0.364643,-0.069246,-0.699652,-0.049288,-0.155366,-0.062860,-0.057543,0.153906,-0.274764,0.794065,-0.714068,0.197028,0.509453,0.178954,-0.294063,0.533185,0.138811,0.225344,-0.534601,-0.028534,0.337401,0.058607,0.150236,-0.201130,0.195748,0.332091,-0.260875,