INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3749947', '四重唱', '剧情', '故事发生在一间专门面向歌剧退休演员开放的养老院里，维尔福（比利·康诺利 Billy Connolly 饰）、雷吉（汤姆·康特奈 Tom Courtenay 饰）和茜茜（宝林·科林斯 Pauline Collins 饰）是那里的明星居民。每一年，这三个出色的演唱者都会通过他们的三重唱向社会募集资金，用以维持养老院的运作。虽然养老院的规模不大，但每一个老人都能在那里找到快乐和安宁。简（玛吉·史密斯 Maggie Smith 饰）的出现打破了众人宁静的生活，这个高傲又好斗的女人是歌剧界名声大噪的歌唱家，同时，她还是雷吉的前妻。受生活所迫，简不得已住进了这间养老院，前夫雷吉的存在更是让她心中愤愤不平。由于简的加入，三重唱变成了四重唱，但排练的效果并没有因为一个得力唱匠的加入而有所提高，麻烦和争执接踵而至。©豆瓣', '玛吉·史密斯', '达斯汀·霍夫曼', 8.1, 16872, 'tt1441951', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1812411449.jpg', 0.3, 1, 19.5, 52.5, 26.7, '0.343178,0.009451,-0.556500,0.388990,-0.061940,-0.100722,1.001986,0.127387,-0.534537,-0.303765,0.094657,0.781585,-0.149462,0.277994,0.103828,-0.082644,-0.140476,-0.399670,-0.011171,-0.033892,-0.082673,-0.358662,-0.300621,-0.490398,-0.159717,-0.230141,0.367033,0.080840,-0.248979,0.398541,0.414619,0.320901,0.192225,0.170510,-0.121610,0.188544,0.082234,0.052243,-0.065908,0.185252,-0.038771,-0.265059,-0.222951,0.044929,0.343928,0.384856,0.509254,-0.066279,-0.148559,0.064341,0.304625,-0.115973,-0.223351,0.107688,0.126620,-0.051204,0.261952,0.291814,-0.323690,0.140868,-0.200074,-0.258753,-0.867350,0.218188,0.297736,0.259675,-0.557296,0.639879,0.095169,-0.166225,-0.333268,-0.159293,0.244368,0.254732,0.230508,0.516967,-0.115033,0.104765,-0.523415,0.157915,0.736873,0.126902,-0.523432,0.206232,-0.522003,-0.522939,-0.190360,-0.290192,-0.588967,0.066962,0.000760,-0.062830,0.072283,0.038968,-0.578255,0.172191,-0.227139,-0.280573,-0.065981,-0.427571,-0.146478,-0.879270,-0.036184,-0.524121,-0.356160,0.032995,-0.022042,-0.293932,0.717180,-0.921394,0.068226,0.283705,0.364115,-0.459121,0.749766,0.105425,0.341811,-0.105997,-0.053276,0.225923,-0.124548,0.335497,0.159072,0.325452,-0.041313,-0.321075,-0.406254,0.470789', '3005387', '2002744', '3055049', '1308755'