INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3749974', '皮囊之下', '科幻', '不知从何时起，萧索的苏格兰街头出现了一个神秘女子（斯嘉丽·约翰逊 Scarlett Johansson 饰），她身着皮草，驾驶一辆汽车，不苟言笑的面庞隐约间弥散着摄人魅力。她时不时地与路边的男人搭讪，向他们问路，间或载着相中的男人同归。她走向黑暗的劲头，被欲望支配的男人们紧随其后，却全然未能觉察自己步入了怎样的深渊。男人有如飞蛾扑火，被抽取了骨血，只剩空空皮囊，薄如蝉翼。直到某个晚上，女人搭载了一个相貌极其丑陋的男子。他宛如怪物一般，自知丑陋而深深隐藏自己。女人如往常一样接纳了他，而从第二天起，似乎女人发现自己在悄悄发生着变化。她发现了这幅皮囊的可欣赏之处，享受作为女人的乐趣，却几乎忘记了本来的面目……本片根据米歇尔·法贝尔（Michel Faber）的小说改编。©豆瓣', '斯嘉丽·约翰逊', '乔纳森·格雷泽', 6.3, 42203, 'tt1441395', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2169890968.jpg', 4.2, 16.7, 47.7, 24.2, 7.2, '0.227229,0.174944,-0.739125,0.472082,-0.453054,-0.168156,1.111621,0.371961,-0.404079,-0.095555,0.426265,0.570781,-0.213515,0.190347,0.251662,0.104199,-0.170145,-0.677455,-0.264497,-0.111942,-0.120111,0.115543,-0.397013,0.068873,0.240209,-0.463654,0.660881,0.096531,-0.155759,0.221086,0.186986,0.083632,-0.244110,0.684510,-0.236478,-0.199234,-0.193267,0.066344,0.317779,0.081898,-0.104252,-0.426188,-0.255318,0.141767,-0.843561,0.475725,1.010400,-0.420770,-0.134508,-0.144689,0.433123,0.140159,0.074366,0.313924,-0.201643,0.047982,-0.036883,-0.202646,0.043132,-0.201025,0.250599,0.076551,-0.166350,-0.002482,-0.227726,0.472486,-0.516231,0.415429,-0.175847,-0.072286,0.106072,-0.355750,0.089043,-0.349359,0.028878,0.391344,-0.075761,0.017828,-0.887295,0.211815,0.213221,0.449754,-0.509626,0.568580,-0.468832,-0.458421,-0.196911,-0.151999,-0.453271,-0.384825,0.407311,0.145786,-0.299444,0.069674,-0.687881,0.198412,-0.043415,0.119953,-0.309474,-0.392728,-0.504275,-0.445588,-0.164271,-0.372039,-0.144653,0.107000,-0.131970,-0.182009,0.571739,-0.581088,0.185718,0.691794,0.026482,-0.161310,0.713995,-0.366757,-0.128535,-0.107347,-0.194692,0.432010,0.157431,0.213729,0.238290,0.561804,-0.446736,0.203778,-0.443438,0.759595', '21619567', '1467779', '20451118', '25884436');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3750088', '双面玛莎', '剧情', '《双面玛莎》根据真实事件改编，曾入围2011年圣丹斯电影节和戛纳电影节一种关注单元，影片在圣丹斯公映后备受好评，被认为是2011年的《冬天的骨头》。年轻女孩玛莎（伊丽莎白·奥尔森 Elizabeth Olsen 饰）曾误入邪教，被教主帕里克（约翰·哈克斯 John Hawkes 饰）洗脑，并以宗教仪式的名义“被强奸”，好不容易才逃脱邪教控制得以脱身。随后她找到姐姐露西（莎拉·保罗森 Sarah Paulson 饰），和姐姐与姐夫泰德（休·丹西 Hugh Dancy 饰）开始了新的生活，并对过去失踪时发生的事闭口不提。在日复一日的看似正常与平静的生活里，玛莎努力忘记不堪回首的过去。但邪教组织的生活如噩梦般在玛莎脑海里挥之不去，她感到恐惧和不安，甚至开始分不清什么是真实，什么是幻觉……©豆瓣', '伊丽莎白·奥尔森', '肖恩·德金', 6.3, 6171, 'tt1441326', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1194065787.jpg', 2.5, 13.7, 53.7, 24.4, 5.7, '0.182738,-0.028775,-0.472397,0.414681,0.154854,0.002373,0.849568,-0.294003,-0.842666,-0.511950,-0.029551,0.620892,-0.599725,0.288915,0.278172,0.159019,-0.311548,-0.800389,0.046004,-0.251265,-0.052503,-0.404841,-0.320183,0.001591,-0.108095,-0.406385,0.416645,0.238775,-0.139769,0.515002,0.439401,0.395622,-0.158619,0.249786,-0.103597,0.079937,-0.091202,-0.013809,-0.434612,-0.045783,0.351048,-0.270336,-0.251270,0.158774,0.184769,0.284878,0.528548,-0.493000,-0.324789,0.062077,0.423642,-0.324994,-0.125211,0.375085,0.200125,0.156626,0.148683,0.341694,-0.037251,0.129444,0.033455,-0.119026,-0.464003,0.195468,0.082511,0.303264,-0.562053,0.302983,-0.050066,0.049693,0.071862,-0.229606,0.186346,0.232355,0.417788,0.400687,-0.109409,-0.019109,-0.485809,0.264830,0.794741,-0.114220,-0.309256,0.497478,-0.140789,-0.326138,-0.254326,-0.285678,-0.416048,0.331792,0.025143,-0.027426,-0.372843,0.506714,-0.305478,-0.398897,-0.267622,-0.365211,-0.082801,-0.325860,-0.128486,-0.478698,-0.282372,-0.395680,-0.141136,-0.160305,-0.112241,-0.375525,0.393628,-1.084129,0.510449,0.357968,0.196375,-0.365131,0.414388,0.222116,-0.104480,-0.204738,-0.104146,0.481093,0.176839,0.011975,0.026761,0.240545,0.075750,-0.014333,-0.348734,0.445233', '1308755', '35030151', '1301022', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3750103', '质数的孤独', '剧情', '幼年时的一场滑雪事故，令爱丽丝（阿尔芭·洛尔瓦彻 Alba Rohrwacher 饰）摔伤了腿，并且这伤痛将永久的伴随和改变她的一生。天才少年马蒂亚（卢卡·马里内力 Luca Marinelli 饰）在他友善纯洁的外表下掩藏了一个十分黑暗的秘密。他那智力发育不全的孪生妹妹带给他的并非怜惜或是责任感，正相反，他希望永永远远的丢开这个恼人的累赘，一天，他真的这么做了。幼年的创伤带给孩子的有时是超越预期的打击，爱丽丝和马蒂亚这两个普通又特殊的人，他们带着创伤长大，成熟。他们就像数列里的质数，冰冷、孤独、坚硬，渴望着同类的出现和靠近，却又无法自持的要去彼此伤害。他们相遇，相爱，相互折磨然后分离去寻找各自的伴侣，但命运又注定他们无法分开。在这个秋天，这两个质数一般的男女，他们能否相互拯救，又或者，等待着他们的，是共赴隐藏在黑暗中的寂灭。©豆瓣', '阿尔芭·罗尔瓦赫尔', '萨维里奥·科斯坦佐', 7, 7569, 'tt1441373', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p612854731.jpg', 1.3, 7.8, 41.9, 36.1, 13, '0.326184,0.034335,-0.717984,0.661633,-0.328264,-0.246060,1.261323,0.211443,-0.188752,0.168658,0.258525,0.806108,0.141003,0.199162,-0.078425,0.083833,-0.276148,-0.670490,0.020626,-0.111039,-0.351727,-0.428676,-0.507228,0.030227,0.122825,-0.246583,0.606830,0.093372,-0.226784,0.530018,0.205072,0.133604,-0.095803,0.562594,-0.450426,0.060666,-0.256132,0.187262,-0.145588,-0.011469,0.147855,-0.065510,0.084859,0.303058,-0.353264,0.426643,0.675412,-0.459015,-0.061148,-0.118164,0.356128,-0.370452,0.031577,0.379839,-0.026032,-0.075475,0.061561,-0.015221,-0.138371,-0.027554,0.108629,0.271865,-0.969504,-0.021922,0.254570,0.252753,-0.781648,0.679647,0.142365,-0.115267,0.139728,-0.076014,0.110396,0.431711,0.123354,0.467213,-0.335448,-0.198240,-0.529031,-0.052148,0.842236,-0.159727,-0.559792,0.172716,-0.584101,-0.484659,-0.163368,-0.330712,-0.704514,-0.197924,0.440517,0.316478,-0.325626,0.316188,-0.705518,0.215211,-0.047407,0.075989,-0.341174,-0.773332,0.100212,-0.450927,-0.104710,-0.830064,-0.611770,0.005419,0.189261,-0.428569,0.807715,-0.646268,0.410865,0.817935,0.457260,-0.390418,0.659972,0.384985,0.244220,-0.142438,-0.171002,0.491681,-0.165991,0.300738,0.223994,0.574021,0.178284,0.586377,-0.661984,0.766167', '26884422', '1417428', '35158375', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3750554', '彩虹照耀', '剧情', '托马斯（约翰·贝尔 John Bell 饰）从小就失去了父母，成长在孤儿院中，因为口吃，托马斯自幼就是一个并不自信，性格内向的男孩，在孤儿院里常常受人欺负。一天，托马斯因为闯了祸而被请进了院长办公室，在那里，他遇见了名为玛丽（康妮·尼尔森 Connie Nielsen 饰）的女士，就这样，玛丽成为了托马斯的新妈妈。玛丽的丈夫埃里克（艾丹·奎因 Aidan Quinn 饰）并不喜欢托马斯，他想要一个更自信、更阳光的孩子，因此对托马斯十分的冷淡。好在托马斯还是很快就结识了很多新的好友，在他们的带领下，托马斯的性格渐渐的开朗起来。在一个神秘的山洞里，托马斯遇见了一只海豹，他为它取名为斯马奇，一人一动物之间结下了深厚的友谊。©豆瓣', 'Connie Nielsen', 'Vic Sarin', 8.8, 16162, 'tt1014774', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2634561281.jpg', 0.2, 0.5, 8.7, 40.2, 50.4, '0.631156,0.066624,-0.599341,0.543103,-0.481073,-0.570202,0.871739,0.331126,-0.495476,-0.136376,0.079761,1.058611,-0.110673,0.410576,0.177462,0.190156,-0.279404,-0.375840,-0.046498,-0.197133,-0.234397,-0.549424,-0.328001,-0.252961,-0.137931,-0.274016,0.339732,-0.154079,0.076884,0.556707,0.242619,0.100041,0.355614,0.609957,-0.271357,0.215944,0.320096,-0.084211,0.090307,0.198773,0.106967,-0.194362,0.089412,0.378647,0.043138,0.171760,0.517316,-0.434419,-0.139197,-0.237109,0.187441,0.097345,0.054513,0.075994,0.482288,-0.262784,0.278877,0.218060,-0.354124,0.253788,-0.101356,-0.068098,-0.617572,0.130294,0.001693,0.238506,-0.693222,0.429692,-0.043770,-0.202853,0.170456,-0.407466,-0.152000,0.231920,-0.040017,0.292442,-0.317438,-0.018870,-0.341491,-0.062142,0.581033,-0.089763,-0.134969,0.481449,-0.405309,-0.298784,0.143742,0.110365,-0.675844,-0.154772,0.552543,-0.225535,-0.148263,0.299298,-0.683430,0.179361,-0.254690,0.074695,-0.144222,-0.423686,-0.095709,-0.373318,-0.114888,-0.435025,-0.317643,-0.115322,-0.183376,-0.186459,0.785212,-1.055483,0.291768,0.485756,0.173925,-0.156864,0.546980,0.089114,0.226132,-0.069147,0.056763,0.367304,0.101929,0.234547,0.141381,0.742459,0.170404,-0.158540,-0.136941,0.698848', '1292219', '1292720', '1292062', '1481233');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3750569', '爱与黑暗的故事', '剧情', '《爱与黑暗的故事》发生在1940年代末期的耶路撒冷，书中通过作者童年的视角写出了他母亲身患精神疾病的困扰和父亲的无助，同时也展现了以色列建国的重大历史事件。', '娜塔莉·波特曼', '娜塔莉·波特曼', 7.1, 4624, 'tt1135989', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2262469516.jpg', 0.9, 6.9, 42.9, 35.4, 13.8, '0.247784,-0.030838,-0.788918,0.737440,0.201534,0.101766,0.836583,-0.119719,-0.537935,-0.252616,0.392159,0.994546,-0.113832,0.430470,0.383073,-0.174476,-0.243937,-0.975959,0.226168,-0.001477,-0.339783,-0.523432,-0.407971,-0.389934,-0.062457,-0.709747,0.755471,0.150188,-0.563752,0.035228,-0.288455,0.665083,-0.311323,0.298476,-0.146234,0.210907,-0.076490,0.213996,-0.571841,-0.152456,0.284641,-0.362882,-0.110422,0.347769,-0.381110,0.254251,0.790632,-0.684635,-0.548094,0.061188,0.978117,-0.264462,-0.315551,-0.112226,0.215602,0.312372,0.227163,0.672593,0.246801,-0.474471,-0.186958,-0.083381,-0.915514,-0.288207,0.166361,0.629249,-0.239901,0.684237,-0.309171,-0.135759,0.426337,-0.297748,0.376821,0.443294,0.423682,0.837914,-0.309620,-0.013807,-0.279131,0.567600,0.505191,-0.157229,-0.799265,0.535850,-0.670223,-0.357439,-0.138513,-0.319485,-0.580323,0.447180,0.187279,-0.060356,-0.764813,0.842887,-0.570254,0.092015,-0.063317,-0.369161,0.263274,-0.307937,-0.382104,-0.221206,-0.700210,-0.557538,-0.238732,-0.351394,0.078286,-0.431950,1.101551,-0.609372,0.497474,0.487613,0.067908,-0.509091,0.850534,0.414707,-0.074686,-0.093836,0.211063,0.471280,-0.462220,0.328993,-0.379518,0.077110,0.224275,0.043711,-0.751776,0.846204', '27602116', '26647163', '1303263', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3754946', '锦衣卫', '剧情', '明朝末年，皇帝昏庸，曾保家卫国屡建功勋的锦衣卫被奸佞利用，沦为暗杀工具，令世人闻风丧胆。因谋权篡位而被施以刖刑的庆亲王（洪金宝 饰）虽被流放塞北多年，然野心不死，暗中勾结大太监贾精忠（罗家英 饰），企图卷土重来。贾精忠在中土掀起一场腥风血雨，不愿苟从者格杀勿论。锦衣卫指挥史青龙（甄子丹 饰）在执行任务过程中因发现贾精忠阴谋而被追杀，身受重创后委身正义镖局以图保护玉玺。茫茫大漠，青龙在镖头之女乔花（赵薇 饰）以及天鹰帮帮主大漠判官（吴尊 饰）的帮助下准备阻止庆亲王与贾精忠的阴谋，此时，庆亲王义女——拥有绝世武功的脱脱（徐子珊 饰）身负追杀青龙的使命亦赶至雁门关……©豆瓣', '甄子丹', '李仁港', 6, 136511, 'tt1442571', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p776030044.jpg', 3.8, 19, 54.7, 18, 4.5, '-0.355110,0.236902,-0.513837,0.850250,0.242248,0.140984,0.296869,0.614241,-0.571093,-0.547808,0.396394,0.404984,0.089449,-0.336700,0.304108,-0.415000,0.185724,-0.695262,-0.250510,-0.136493,-0.059497,-0.342753,-0.298931,-0.366511,-0.464795,-0.420722,0.531431,0.334387,-0.141722,0.542927,0.729136,0.379821,-0.398525,0.401804,0.095465,-0.138851,0.043565,-0.223854,-0.400108,0.109849,-0.161979,-0.686675,-0.108266,0.197174,-0.394037,0.140042,0.415371,-0.500017,0.256405,-0.590021,0.229116,-0.314118,0.118107,-0.041913,0.438472,0.033550,-0.005308,0.543127,0.108613,0.100223,0.241498,-0.000577,-0.689363,-0.317514,0.386403,0.013188,-0.401006,0.267217,-0.113221,0.179298,-0.264617,-0.117881,0.285811,0.343032,0.515334,-0.033268,0.122325,0.206455,-0.730719,0.330050,0.442880,-0.238684,0.201073,-0.408509,0.467184,-0.266872,0.209716,-0.429194,-0.297678,-0.045295,0.461127,-0.344548,0.140326,0.315606,-0.222750,-0.291416,-0.555189,0.509809,-0.107097,0.174649,0.203473,-0.327939,-0.235175,-0.202368,0.003051,0.181195,0.333209,-0.196170,0.327637,-0.626683,0.181162,0.222115,0.072010,-0.916236,0.237440,0.302602,0.353682,0.010748,-0.035462,0.137994,0.655999,0.364231,0.341042,-0.243112,-0.295746,-0.337407,-0.121862,-0.040067', '3670447', '1302110', '1292287', '1297710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3755531', '哆啦A梦：大雄的新魔界大冒险之7个魔法师', '科幻', '大雄最近有点儿倒霉，在学校因为功课被老师训斥，打棒球技术差被伙伴们嘲笑，房间太乱遭到妈妈责骂。伤心的他异想天开，希望有某种魔法能帮他搞定这一切。在哆啦A梦的“假如电话亭”的帮助下，他们的世界变成了一个魔法的世界，不幸的是大雄依然是最差的那个。与此同时，神秘天体正在接近 地球，魔界之王戴玛奥企图统治世界，他预测到大雄和他的朋友们将是他前进道路上的阻碍，于是他派出魔女美杜沙铲除这些绊脚石。大雄他们遇到了空前的危机……©豆瓣', '水田山葵', '寺本幸代', 8.2, 11612, 'tt1260351', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1048182650.jpg', 0.4, 1.3, 19.4, 44.5, 34.4, '0.247091,0.234865,-0.646822,0.363716,-0.201702,0.106469,0.522036,-0.017723,-0.288875,-0.128926,0.215540,0.733593,-0.043244,0.221455,-0.075051,-0.142919,-0.013621,-0.607270,-0.027969,-0.061400,-0.647736,-0.340678,-0.276381,-0.154203,-0.157660,-0.459215,0.490842,0.150824,-0.368712,0.026192,0.130774,0.359936,0.081058,0.443424,-0.514931,0.178497,0.064144,-0.032847,-0.149347,0.165667,-0.123877,0.151320,-0.016272,0.359076,-0.089857,0.011464,0.520665,-0.201992,-0.305063,-0.206054,0.372138,-0.615065,-0.088330,-0.029171,0.660539,-0.197135,-0.128017,0.051908,0.107654,-0.092826,0.011316,0.000167,-1.062898,0.018809,0.158024,-0.014651,-0.663465,0.282486,0.098443,-0.009831,0.133319,-0.161367,0.278828,0.396003,0.258629,0.298204,-0.126856,0.091284,-0.523486,-0.097357,0.819963,-0.097432,-0.315834,0.220024,-0.220508,0.028773,-0.135311,-0.288952,-0.492607,0.079720,0.425105,-0.146781,-0.388468,0.228735,-0.502628,0.016189,-0.196994,-0.236487,-0.012219,-0.594402,-0.268658,-0.360458,0.048548,-0.265569,-0.327829,0.106231,0.038116,-0.256209,0.943533,-0.937261,0.154349,0.809523,0.557534,-0.444829,0.746110,0.120961,-0.030094,-0.224150,-0.044681,0.000427,0.051252,0.446731,0.176533,0.325333,0.039242,-0.140423,-0.555489,0.497540', '30163500', '24284209', '1793491', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3757161', '七天爱上你', '剧情', '在世界各地留下足迹的录音师子淇（贺军翔 饰）离开香港，抵达北京，在这里，他偶遇了开着房车的神秘女孩白叶（李小璐 饰），后者邀请他上车。在攀谈中，两个陌生人发现彼此对于旅行的计划竟然惊人的一致，于是他们约定同行，并将在坝上分手。从长城开始，举止过火的白叶给子淇造成了不小的困扰，在唇枪舌剑和大胆的玩笑中，这个敬佩余纯顺行为的女孩一次次令子淇失去掌控。不久，子淇接到了白叶父亲的电话，始知道旅伴身患绝症，子淇在剩下的旅程中帮助白叶找到了传说中的树屋，然而此时白叶却神秘的死去……六个月后，子淇偶遇了和白叶一模一样的富二代作家晏青，才知道事情的真相……©豆瓣', '贺军翔', '张坚庭', 5.6, 8117, 'tt6446754', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2374290660.jpg', 10.7, 24.9, 44.4, 15.5, 4.5, '0.477432,0.223524,-0.798542,0.451992,-0.082307,-0.204336,0.629781,-0.154458,-0.705000,-0.335083,0.162435,0.766564,-0.318329,0.290254,0.306971,-0.146341,-0.302240,-0.498517,-0.016056,-0.247218,-0.298806,-0.495896,-0.122582,-0.003103,-0.160419,-0.140389,0.521390,0.163034,-0.201776,0.855014,0.270707,0.017547,-0.300710,0.645847,-0.292913,0.242235,0.103599,0.234231,-0.313045,0.200990,-0.137515,-0.257410,-0.044437,0.233708,-0.040298,0.464406,0.697011,-0.310647,-0.331498,0.195327,0.258184,-0.203872,-0.116140,0.104191,0.372168,0.247856,0.322099,0.066267,-0.372264,-0.093393,-0.081371,0.143650,-0.337221,0.192949,-0.099892,0.245969,-0.606730,0.458678,0.017491,-0.250831,0.238742,-0.511262,0.344138,0.379146,0.281338,0.369008,-0.105128,0.034299,-0.448953,-0.024437,0.673984,-0.005468,-0.066860,0.457830,-0.104875,-0.468365,-0.078017,0.114107,-0.221686,0.047901,0.264170,0.150759,-0.247993,0.158263,-0.459117,-0.065386,-0.061474,0.035372,0.011621,-0.448070,-0.306834,-0.691881,-0.167906,-0.377148,-0.336887,0.226393,-0.064248,-0.200667,0.613541,-0.964947,0.205809,0.452198,0.522158,-0.433233,0.545821,0.103622,-0.076373,-0.354318,-0.062908,0.246461,-0.061648,0.292315,0.154696,0.447041,-0.117038,-0.101756,-0.595741,0.216016', '35030151', '1292219', '1915403', '3401409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3769423', '守护者联盟', '动画', '圣诞老人诺斯（亚历克·鲍德温 Alec Baldwin 配音）、复活节兔子（休·杰克曼 Hugh Jackman 配音）、牙仙（艾拉·菲舍尔 Isla Fisher 配音）和沙人，这些童年的守护者个个长生不老、力量强大又动作敏捷，他们的任务就是尽其所能保护所有孩子的天真与想象力，但一个心怀不轨的坏蛋出现了，他打算抢夺孩子们的希望和梦想来抹去守护者的存在。此时这群深受喜爱的英雄需要杰克冻人（克里斯·派恩 Chris Pine 配音）助其一臂之力，但这位新加入的守护者却只喜欢玩雪，对拯救世界毫不关心。从北极最深的隐蔽处、上海的屋顶到新英格兰的迷你小镇，守护者在世界各个角落进行一场规模浩大的战争以对抗邪恶又擅于蛊惑人心的的食虫人（裘德·洛 Jude Law 配音）。他的阴谋是到处散布恐惧来征服全世界，而唯一能够阻止他的就是相信的力量，以及守护者拥有的神奇魔力。', '克里斯·派恩', '彼得·拉姆齐', 8.2, 93290, 'tt1446192', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1758887194.jpg', 0.3, 1.7, 20.3, 45.3, 32.3, '0.006177,0.126308,-0.596074,0.710685,-0.358437,0.006769,0.693300,-0.098529,-0.261650,-0.153988,0.155912,0.817918,0.163623,0.116955,0.164718,0.120793,-0.152517,-0.394636,-0.110083,-0.160490,-0.154568,-0.329090,-0.507105,-0.477577,0.032801,-0.563210,0.677514,0.220496,-0.323152,0.171281,0.383015,0.256467,-0.301504,0.381884,-0.216312,-0.265447,-0.048761,-0.175737,-0.292968,0.152055,-0.202514,0.163001,-0.243245,0.310466,-0.162924,0.048053,0.572104,-0.632633,0.048056,-0.193192,0.381192,-0.534661,0.057636,0.135483,0.179222,-0.169340,0.074184,-0.064037,0.182477,0.107166,0.021936,-0.347872,-1.181659,-0.098756,0.118528,0.167775,-0.450607,0.319816,-0.027413,-0.137423,0.243053,-0.144661,0.199707,0.081523,0.128568,0.544195,-0.103887,0.125742,-0.324500,-0.055228,0.548645,-0.207663,-0.295285,0.299222,-0.259054,-0.421285,-0.170996,-0.476922,-0.507698,-0.109779,0.177408,0.001263,-0.095467,0.284798,-0.758406,0.051145,-0.256175,-0.291766,-0.030905,-0.465465,-0.012987,-0.659298,-0.064141,-0.215399,0.013835,0.101770,0.298473,-0.437106,1.057825,-0.904288,0.205416,0.803743,0.291029,-0.471586,0.563196,-0.002280,0.056845,-0.299134,-0.351172,0.330578,0.226131,0.198723,-0.013467,0.382681,0.092194,0.028847,-0.403860,0.561226', '24284209', '