INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3771562', '普罗米修斯', '科幻', '21世纪末，人类的科技水平已高度发达，克隆人技术和宇宙航行早已实现，不再是梦想。与此同时，许多科学家仍孜孜不倦追索着人类起源的秘密与真相。通过对许多古老文明的考察与对比，科学家伊丽莎白·肖（Noomi Rapace 饰）和查理·赫洛维（Logan Marshall-Green 饰）发现，人类可能是来自一个遥远星系的外星人创造的。在Weyland公司资助下，他们乘坐维克丝（查理兹·塞隆 Charlize Theron 饰）所掌管的宇宙飞船普罗米修斯号前往那颗未知的星球。经过对当地的考察，地球人的设想成功得到印证。可是他们贸然探查“神的秘密”的行为，也将自己引入万劫不复的深渊……©豆瓣', '劳米·拉佩斯', '雷德利·斯科特', 7.6, 332894, 'tt1446714', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1548920463.jpg', 1.2, 4.4, 30, 44.4, 20, '0.115703,0.338060,-0.848493,0.687237,-0.176342,0.181439,0.547769,-0.391655,-0.532091,-0.196442,0.035410,0.833331,0.042365,0.007874,0.365352,-0.031292,-0.508842,-0.422534,0.071034,-0.384947,-0.361701,-0.803230,-0.571765,-0.459610,-0.038355,-0.503293,0.898375,0.348373,-0.580984,0.037149,-0.288647,0.582344,-0.384426,0.365868,-0.318834,-0.273924,0.142292,0.046812,-0.404810,0.063044,-0.271606,0.062283,0.066497,0.190408,-0.275235,0.227318,0.506041,-0.699210,-0.120575,-0.223792,0.284361,-0.396263,0.053200,-0.170657,0.479792,0.081603,-0.321531,0.357136,0.067873,0.072184,0.100462,-0.201605,-1.094499,-0.270700,0.326442,0.201537,-0.348490,0.043283,-0.056122,-0.059974,-0.167480,-0.275717,0.230704,0.589176,0.426420,0.495160,0.051612,0.045296,-0.451465,0.244739,0.490179,0.061377,-0.377027,0.258124,-0.255152,-0.827599,-0.553537,-0.189830,-0.525571,-0.047493,0.200836,0.279160,-0.085937,0.532404,-0.880751,0.137919,-0.351727,-0.528069,0.295032,-0.450900,0.188244,-0.801345,-0.206812,-0.382535,-0.214659,0.078311,0.328231,-0.378384,0.812985,-0.793828,0.114431,0.591205,0.468725,-0.623935,0.848854,-0.355192,-0.122654,-0.719137,0.023902,0.580892,0.148572,0.429958,-0.421898,0.228248,0.361285,-0.105051,-0.389484,0.445610', '3769423', '1793491', '1308585', '1294893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3775163', '舞力对决', '爱情', '《舞力对决》又名《街舞3D》，影片被誉为是英国首部3D电影。青春靓丽的舞者卡莉（妮可拉·布利 Nichola Burley 饰）的人生正值风光之时，她拥有迷人的帅哥男友杰伊，两人加入的舞蹈团体也刚打入英国街舞冠军总决赛，但杰伊在这个关键时刻却突然离开卡莉及舞团。残酷的现实不仅令卡莉心碎，也让其他团员的梦想岌岌可危。芭蕾舞学校校长海伦娜（夏洛特·兰普林 Charlotte Rampling 饰）被卡莉及其舞团的舞技和热忱打动，伸出援手。他们可以在芭蕾舞学院的豪华舞蹈教室练舞，但要跟芭蕾舞者一起训练，才能得到免费的训练场地。高贵的芭蕾、草根的街舞，这本是两个毫无瓜葛并且还有些不共戴天的舞蹈形式就这么走到了一起。当芭蕾与街舞这两种南辕北辙的舞蹈正面交锋时，冲突随即展开。卡莉的冠军梦想能否最终达成呢？©豆瓣', '妮可拉·伯利', '马科斯·吉瓦', 6.8, 6545, 'tt1447972', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p514351142.jpg', 1.1, 8.6, 47.9, 31.4, 10.9, '0.216738,0.000685,-0.482939,0.599543,0.114936,-0.445095,0.575390,0.152057,-0.130339,-0.009367,0.261235,0.837598,-0.331644,0.300025,0.448151,-0.132582,-0.278844,-0.897233,-0.148516,0.076555,-0.088292,-0.208597,-0.075907,0.137829,-0.111150,-0.236825,0.896614,-0.161201,-0.404701,0.816385,0.480031,-0.032766,-0.065154,-0.114556,-0.346061,-0.302527,0.410334,0.267255,-0.421145,0.293589,-0.002960,-0.043973,-0.402734,0.108543,-0.003722,-0.059866,0.537762,-0.043910,0.273385,0.003503,0.517378,-0.045435,-0.078912,0.095102,0.175564,-0.099177,0.242173,-0.077744,0.284744,0.094043,-0.061646,-0.327290,-0.965083,0.219925,0.233547,0.027785,-0.415371,0.534397,0.035737,-0.213093,0.360400,-0.016785,0.070203,0.280887,0.378609,0.328217,-0.104993,0.096732,-0.448507,0.309968,0.684388,0.079989,-0.400445,0.306321,-0.417058,-0.695824,-0.203136,-0.296920,-0.304980,-0.044926,0.204387,-0.027328,0.288753,-0.018731,-0.779800,0.022553,-0.055553,-0.057844,0.004866,-0.458783,0.218551,-0.847504,-0.100780,-0.377185,-0.330218,-0.000806,0.213812,-0.250194,0.967265,-0.984658,0.147742,0.476981,0.165765,-0.307884,0.742800,0.293952,0.111947,0.071715,-0.251988,0.230426,-0.202858,0.172277,-0.156855,0.777492,0.155778,-0.204017,-0.627922,0.593085', '3811356', '27602116', '25880986', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3775167', '铁血精英', '动作', '美国著名的海军特种部队海豹突击队的前精英队员丹尼·布莱斯Danny（杰森·斯坦森 Jason Statham 饰）如今，正卷入一场跨国的“秘密杀戮”事件当中。他的对立面——斯派克Spike（克里夫·欧文 Clive Owen 饰）则是来自另一个国家的超强特工，此人同样心黑手狠，并正打算以一切手段除掉丹尼。经过一番激烈的厮杀交手之后，对强悍的丹尼似乎无能为力的斯派克打起了其特战导师亨特Hunter（罗伯特·德尼罗 Robert De Niro 饰）的主意，并打算以亨特为诱饵设置一个天衣无缝的陷阱来猎杀丹尼，结果经过超强特训以及身经百战磨砺后的丹尼之战斗力已然超出了斯派克一伙甚至军方的想象。丹尼不但在殊死一战后救出了老恩师亨特，还对斯派克一伙造成了巨大的杀伤。影片改编自兰奴夫·费因斯（Ranulph Fiennes）的纪实性文学作品《男人的羽毛/羽人》（The Feather Men）。', '杰森·斯坦森', '加里·麦肯德莱', 6.6, 27682, 'tt1448755', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1084402027.jpg', 1.3, 10.2, 54.4, 26.8, 7.3, '-0.005520,-0.270692,-0.699101,0.742323,0.063625,-0.343949,0.670934,0.044799,-0.465305,-0.309589,0.465809,0.574500,0.045339,-0.256433,0.271575,-0.357144,-0.447553,-0.659036,-0.402125,0.062894,-0.295747,-0.610307,-0.575857,-0.175029,0.077036,-0.340540,0.551836,-0.135680,-0.423744,0.411137,0.424628,0.233639,-0.014253,0.318286,0.177362,-0.053606,0.460751,-0.260888,-0.469871,0.090588,-0.049935,0.048320,-0.232064,0.254941,-0.198765,0.326991,0.495435,-0.521268,-0.007402,-0.420825,0.100372,-0.240141,0.075421,0.067940,0.471615,0.001616,0.212948,0.164483,0.095997,0.317507,0.042718,-0.005228,-1.089131,0.004685,0.110843,-0.094745,-0.336335,0.371809,-0.076984,0.190852,-0.047354,-0.077122,-0.218854,0.229067,0.254397,0.060524,-0.080226,0.003415,-0.233839,0.019865,0.570563,-0.131785,-0.161615,0.057687,-0.068403,-0.397671,-0.152137,-0.391332,-0.114643,0.006939,0.460585,-0.171086,0.044952,0.302133,-0.572906,0.021565,-0.619720,0.001234,-0.297463,-0.187259,-0.000072,-0.771902,-0.174959,-0.239129,-0.379917,0.132953,0.107936,-0.018376,0.601120,-0.753078,-0.073405,0.619791,-0.051962,-0.159457,0.052249,0.067128,0.208657,-0.248964,-0.478214,0.221845,0.181023,0.324461,0.083880,0.387234,0.140102,-0.476034,-0.138636,0.213655', '1793491', '1307442', '1874704', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3777800', '月满轩尼诗', '喜剧', '香港湾仔，电器行老板娘（鲍起静 饰）丈夫早亡，她和妹妹共同抚养儿子阿来（张学友 饰）。但后者终日沉迷侦探小说，41岁依然单身，还常会跟想象中的亡父对话。在一场相亲宴上，阿来见到了洁具行售货员爱莲（汤唯 饰），起初有点尴尬，后来在茶餐厅，两人谈笑风生。不过，爱莲一直挂念狱中的古惑仔男友阿旭（安志杰 饰），所以对这门亲事只是敷衍。阿来同样接到了前女友（张可颐 饰）的邀请，出任男模，两人似乎重新擦出了火花。虽然阿来和爱莲各怀心事，但两人却在轩尼诗道再度重逢。与此同时，老板娘却因为报税之事跟老相好（李修贤 饰）闹了别扭，而且，一直蒙在鼓里的她还目睹了阿旭与爱莲牵手逛街。经受不住打击的她彻底崩溃、住进了医院。此后，阿来跟前女友，爱莲跟阿旭的感情却发生了变化……©豆瓣', '张学友', '岸西', 6.7, 85243, 'tt1447800', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p455551214.jpg', 1.4, 9.4, 49.9, 32, 7.4, '0.182830,-0.021878,-0.650695,0.238216,0.284267,-0.705761,0.707726,0.320271,-0.442537,-0.278522,0.080964,0.506450,-0.482086,0.257769,0.136792,-0.076436,-0.262980,-0.661372,0.199286,0.011263,0.046647,-0.341287,0.046239,0.207926,-0.195318,-0.103620,-0.047446,-0.159835,-0.066763,0.653485,0.385433,0.028214,-0.241373,0.733348,-0.069596,0.189405,0.019265,0.392431,-0.334463,-0.159564,0.276423,-0.292444,-0.193032,0.032733,0.283394,0.384835,0.564370,-0.179426,-0.120800,0.040796,0.147019,-0.044180,-0.057463,0.068433,0.300889,-0.073630,0.476055,-0.112833,-0.121102,0.015248,0.080825,0.185270,-0.198303,0.302136,0.197513,0.070518,-0.567660,0.458307,-0.061812,-0.048715,0.053941,-0.346617,0.229956,0.274844,0.137203,0.458514,-0.334267,0.195528,-0.496949,0.290414,0.660394,0.147899,0.162640,0.450709,-0.135656,-0.381985,-0.076096,0.065620,-0.490143,0.112777,0.003902,-0.101469,-0.041530,0.173031,-0.363448,-0.256551,-0.180279,0.264499,0.107621,-0.528999,0.079375,-0.466356,-0.192869,-0.475737,-0.334819,-0.085255,0.055872,-0.130003,0.286625,-0.699471,0.164245,0.257441,0.279924,-0.376999,0.654724,0.388308,0.051509,-0.275558,-0.096058,0.064353,-0.247290,0.059832,0.375492,0.365592,0.049421,0.069474,-0.227590,0.040538', '1308755', '10355329', '26687241', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3781860', '兄弟情人', '剧情', '托马斯（Rafael Cardoso 饰）刚出生时，好几个星期双眼仍旧紧闭，身为医护人员的母亲认为，只要孩子准备好，便会自己睁开眼。而最先映入托马斯眼帘的，便是比自己大6岁、同母异父的哥哥弗朗西斯科（Jocatilde Gabriel Vasconcellos 饰）。那一眼，似乎注定了两人无悔的爱情。随着年龄增长，托马斯对弗朗西斯科日渐崇拜，弗朗西斯科对托马斯更是呵护备至。两人互动亲昵过火，让父母不知所措。虽担心兄弟俩逾越「常轨」，但家人仍选择包容他们相爱的可能。经过人事物的变迁，弗朗西斯科和托马斯终于成为爱侣。然而托马斯需要为奥运赛事远赴俄国泳训三年。血浓于水的两人是否禁得起分离的考验？本片为巴西最具争议的同志电影。导演跨越血缘与性向，讲述一对兄弟间至死不渝的爱情，在梦幻与冲突、乱伦与唯美之间传达动人的画面效果。©豆瓣', '朱莉娅·莱莫兹', '阿卢希欧·阿巴瑞奇', 7.1, 14507, 'tt1440741', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1252217264.jpg', 1.9, 8.7, 37.6, 34.7, 17.1, '0.099617,-0.186557,-0.636399,0.513667,0.258390,-0.410285,0.677021,0.170364,-0.501499,-0.128596,0.084115,0.575024,-0.324753,0.021464,0.365269,-0.138425,-0.168987,-0.885010,-0.113003,-0.153956,-0.065811,-0.609579,-0.177857,-0.122715,0.003951,-0.361330,0.726585,0.045904,-0.098154,0.650164,0.147958,-0.052186,-0.113494,0.126079,0.045708,-0.231487,-0.047439,0.240189,-0.705400,-0.065792,0.081144,0.132631,-0.199980,0.042164,-0.227618,0.212995,0.558552,-0.433323,-0.295447,-0.060982,0.258289,-0.058040,0.089267,0.277168,-0.051165,0.139157,0.346553,0.274890,-0.041104,-0.076281,-0.098920,-0.115491,-0.402218,0.229823,0.224466,-0.010594,-0.439068,0.492212,-0.035484,-0.302994,0.342394,-0.163640,-0.080181,0.425775,0.350290,0.829588,-0.378844,0.060627,-0.043620,-0.151131,0.527816,0.243414,-0.353364,0.429119,-0.424079,-0.414797,-0.171133,-0.198953,-0.469375,0.186286,0.188288,0.242588,0.226776,0.675015,-0.262959,0.118602,-0.159941,0.051627,0.102014,-0.626730,0.122107,-0.569158,-0.238606,-0.603587,-0.369875,0.212293,0.096602,-0.285702,0.761350,-0.593577,0.312828,0.237272,0.251495,-0.453461,0.766617,0.371255,0.072141,-0.602878,-0.228958,0.507327,-0.172821,-0.221986,-0.077891,-0.035670,-0.003141,0.337889,-0.272537,0.254641', '35048413', '25777330', 