INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3785918', '污垢', '剧情', 'Bruce（詹姆斯·麦卡沃伊 James McAvoy 饰）是一个苏格兰警察，有一个美丽的妻子和一个可爱的女儿，他们婚姻幸福令人称羡。一个日本人在一条隧道里被人杀害，警局非常重视这个案子，同时警局最近有一个升职名额，Bruce和他的几个同事们都跃跃欲试。而Bruce深信通过他出色的办案能力再加上一些小手段，只要他能破了这个案，他定能得到提拔。在调查谋杀案的过程中，Bruce又接手了另一个案件——调查到底是谁老是给他的好友Bladesey的妻子打骚扰电话。在办案的过程中，Bruce不断向观众展示了一个出色的警察是如何利用邪恶的人性来达到他的目的的......本片改编自《猜火车》作者埃文·威尔什的同名小说。©豆瓣', '詹姆斯·麦卡沃伊', '乔·拜尔德', 7.8, 33124, 'tt1450321', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2175466371.jpg', 0.5, 2.8, 25.6, 46.7, 24.4, '0.210398,-0.124634,-0.484387,0.917408,-0.565847,-0.078414,0.675086,-0.061505,-0.393913,-0.154992,0.156559,0.796979,-0.084930,0.297560,-0.034259,-0.063128,-0.164473,-0.667825,0.008532,-0.225794,-0.545702,-0.508752,-0.380731,-0.502811,0.148800,0.046186,0.400305,0.077927,-0.204170,0.161368,0.416905,0.216147,-0.112797,0.361765,-0.306715,0.026429,0.392436,-0.235839,0.106716,0.326353,-0.066323,-0.180866,-0.150132,0.242860,-0.099724,0.492106,0.605438,-0.019972,-0.315994,-0.036499,0.598775,-0.316446,-0.001275,0.076569,0.278327,0.017493,0.199776,0.135879,-0.204026,-0.246284,-0.012897,-0.105052,-1.298364,-0.158303,-0.006279,0.168643,-0.475716,0.189526,-0.091534,-0.182511,0.064377,-0.196777,0.204818,0.341952,0.061604,0.320477,-0.164194,0.079397,-0.623300,0.302450,0.675701,0.065178,-0.211169,0.268585,-0.180863,-0.464662,-0.025554,-0.158699,-0.444688,0.121805,0.560234,-0.358183,-0.101409,0.006286,-0.390993,-0.024448,-0.298396,-0.081394,-0.236875,-0.553300,-0.078396,-0.327090,-0.152306,-0.287275,-0.516986,0.010549,0.140889,-0.351610,0.967108,-0.724513,-0.149287,0.927151,0.052758,-0.736909,0.878423,0.362367,0.120002,-0.211328,-0.211519,-0.243741,0.366257,0.213299,0.062401,0.574948,0.066329,-0.294621,-0.589238,0.299438', '30163500', '26678784', '30368448', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3785958', '头七', '恐怖', '某晚，出租车司机地图王（林家栋 饰）接到同行求助，原来一个小货车司机想找人带路去日月村，然此地无人知晓，万般无奈之下，他们找到了地图王。起先，地图王因某种原因不愿接手，但耐不住朋友的恳求和重金的诱惑，他带领小货司机小马（张智霖 饰）出发前往日月村。路上，两人通过电台聊天，无意中提及村中的春雷饭店。三十年前，一场大火将该饭店烧毁殆尽，而其中的秘密却鲜为人知。地图王和小马讲述了各自所知的实情，一段尘封而凄惨的旧事在他们截然相反的叙述中重新浮现，而他们这一晚的旅途也注定不平凡……©豆瓣', '张智霖', '邱礼涛', 6.3, 9197, 'tt1450672', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1946335362.jpg', 2.3, 13.2, 58.2, 21.7, 4.5, '0.250415,0.323532,-0.507830,0.672448,0.224960,-0.069159,0.554436,0.011035,-0.655719,-0.465957,0.016762,0.608975,0.092594,0.357094,0.230266,-0.101641,-0.451323,-0.184654,0.097797,-0.231007,-0.415177,-0.428319,0.020876,-0.396334,-0.000302,0.154235,0.405718,0.409533,-0.052664,0.629836,0.237316,0.081085,-0.716996,0.409953,-0.118554,0.186880,-0.128808,0.238778,-0.317451,-0.204357,-0.202478,-0.375416,-0.246125,-0.170145,0.214766,0.407324,0.596358,0.030418,-0.221321,-0.021289,0.066090,-0.265540,-0.076617,-0.017621,0.470107,0.155445,0.331332,0.177658,-0.356085,-0.374963,-0.169284,0.131396,-0.399220,0.134275,-0.024843,0.124436,-0.645401,0.222837,-0.108821,0.022481,0.013647,-0.273775,0.495754,0.333904,0.268242,-0.017389,0.202167,-0.386504,-0.585534,0.284262,0.784374,0.042902,0.261915,0.212547,0.111601,-0.178012,-0.030737,0.263554,-0.436921,0.169258,0.305755,0.083155,-0.215277,-0.164255,-0.566834,-0.287648,-0.343667,0.015026,0.056118,-0.484115,-0.164825,-0.804309,0.047613,-0.195447,0.083999,0.135441,0.192819,0.206488,0.523933,-0.454564,0.058956,0.075050,0.211792,-0.374041,0.631645,-0.126024,0.174884,-0.531789,0.269728,0.139371,0.196971,0.512443,0.291438,0.127625,-0.205904,-0.170972,-0.547851,0.097445', '3147969', '10466639', '1294917', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3788587', '再生号', '剧情', '1998年11月11日，汤有亮（刘青云 饰）一家游玩途中遭遇严重车祸，汤当场身亡，妻子程希文（林熙蕾 饰）和一双儿女侥幸逃生，只是女儿汤乐儿双眼从此失明。转眼十年过去，时间并未治愈汤氏一家心中的创伤，他们久久沉浸在失去丈夫和父亲的悲痛之中。乐儿（阎青 饰）不愿母亲继续折磨自己，她尝试着将一家人的经历写成小说，而书中的情节和现实截然相反。在小说里，乐儿和母亲、弟弟死于车祸，父亲则活了下来，成为一个由菲佣照顾起居的盲人。父亲相信鬼魂的存在，时刻期盼与妻儿重逢。死去的乐儿在另一个世界当上了小孟婆，她利用手中的职权让母亲和弟弟重新回到父亲身边。汤和妻儿心照不宣地享受着失而复得的幸福生活……乐儿的小说让母亲的脸上绽放出久违的笑容，一家人的生活终于步上正轨，然而一场残酷的灾难不期而至……©豆瓣', '刘青云', '韦家辉', 6.6, 10561, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2264283912.jpg', 2.7, 13, 46.4, 28.8, 9.2, '-0.168103,0.067438,-0.482581,0.528311,0.049197,-0.533540,1.015432,0.163697,-0.542302,-0.187058,0.169882,0.954686,-0.005119,0.608828,0.238983,-0.119991,-0.308671,-0.866304,-0.141302,-0.027287,-0.162652,-0.283967,-0.052761,-0.074417,-0.031450,-0.424089,0.620965,0.218833,0.208389,0.738521,-0.048235,0.085973,-0.317613,0.381028,-0.044436,0.259171,-0.380559,0.120609,-0.576730,0.218072,0.351822,-0.201398,-0.187190,0.194124,0.037209,-0.112556,0.981822,-0.267767,-0.299669,-0.310432,0.342557,-0.258471,-0.093716,0.096373,-0.085424,0.051770,0.464888,0.223930,-0.374927,-0.117868,0.056300,-0.099618,-0.660836,-0.102875,-0.011150,-0.003507,-0.580632,0.517014,-0.069412,0.105714,0.177678,-0.334522,0.478292,0.372546,0.300548,0.799029,-0.731321,0.206692,-0.397916,0.361816,0.628404,-0.225179,0.035498,0.323990,-0.173301,-0.110977,-0.098287,-0.353408,-0.625984,0.190995,0.226016,0.313970,-0.425811,0.514519,-0.246590,0.045939,-0.366768,-0.095554,0.217005,-0.386125,-0.218111,-0.251883,-0.145742,-0.238140,-0.474560,-0.013843,0.015223,-0.370268,0.641198,-0.560797,0.556025,0.178054,0.152023,-0.508229,0.807038,0.256817,0.349741,-0.229093,0.256355,0.486511,-0.237564,0.100486,0.208874,-0.074440,-0.236737,0.472279,-0.425783,0.387066', '2365260', '26884422', '1296534', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3789848', '怪兽大学', '喜剧', '自幼憧憬惊吓专员职业的大眼仔麦克·华斯基（比利·克里斯托 Billy Crystal 配音），终于如愿考入曾走出过无数传奇人物的怪兽大学惊吓学院。对于这个相貌讨喜、丝毫没有任何恐怖气场的小怪物来说，死啃书本似乎是实现梦想的唯一途径。与之相对，系出惊吓名门的同学毛怪詹姆士·苏利文（约翰·古德曼 John Goodman 配音）天生是周围同学关注的焦点，完全一副什么都无所谓的浪荡公子哥做派。倒霉的是这两个脾气完全不合的家伙惹到了极其严格的院长迪安·哈德斯克莱博（海伦·米伦 Helen Mirren 配音），结果在期中考试时被三振出局，驱逐出惊吓学院。不甘失败的大眼仔抓住一线机会，集结团队报名参加兄弟会举办的惊吓游戏，只要获胜的话便有机会重返惊吓学院。而在高手云集的赛场上，大眼仔与毛怪即将迎接前所未有的挑战……本片为皮克斯动画片《怪兽电力公司》的前传。©豆瓣', '比利·克里斯托', '丹·斯坎隆', 8.3, 345594, 'tt1453405', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2033476722.jpg', 0.1, 1, 16.8, 49.5, 32.6, '0.242580,-0.215923,-0.554015,0.372885,-0.064082,-0.130229,0.450643,0.061315,-0.542508,-0.194920,0.124195,0.496044,-0.550208,0.475661,0.302668,-0.297876,0.028428,-0.345491,-0.367107,-0.254015,-0.002332,-0.383526,-0.101203,0.073475,0.171600,-0.486336,0.697639,-0.181995,-0.546584,0.596286,0.390263,0.186010,-0.041154,0.237798,0.051697,-0.299116,0.313253,0.100470,0.099811,0.096984,-0.212490,0.044329,-0.228235,0.059302,0.136227,0.239240,0.450379,-0.275650,-0.276985,-0.041806,0.508800,-0.315714,-0.135421,0.094571,0.323587,-0.322530,0.297073,-0.104929,0.521652,0.012740,-0.023446,-0.238654,-0.581428,0.059581,0.186970,0.292792,-0.445827,0.652094,0.128597,-0.074364,-0.038275,-0.026851,0.175875,0.235047,0.110341,0.313216,-0.074831,0.380810,-0.357642,0.057286,0.506185,-0.113620,-0.433274,-0.006187,-0.146037,-0.678138,0.128166,-0.349249,-0.333061,0.200922,0.126356,0.057205,-0.253345,0.353373,-0.370340,0.047200,-0.341060,-0.007296,-0.041243,-0.402772,-0.054743,-0.850877,0.055976,-0.270994,-0.301524,0.034520,0.200134,-0.205193,0.819965,-0.831402,0.180188,0.411868,0.187113,-0.193661,0.640030,-0.084109,-0.016193,-0.058257,-0.282933,0.108932,0.308422,0.331817,-0.100993,0.341060,0.097092,-0.469613,-0.005754,0.534698', '26259202', '25922902', '1316589', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3789921', '消失在第七街', '悬疑', '毫无征兆的夜晚，黑暗突然降临。这宛如鬼魅的黑暗，吞噬掉大都会中所有的能源。随着能源的丧失，人类也宛如蒸发了一般凭空消失，只留下衣服和随身物品，宣告着他们一曾存在。白日缩短，黑夜延长，少数的幸存者仍试图对抗逡巡四周的死神。在一家尚有光亮的小酒馆里，电视台主持人卢克（海登·克里斯滕森 Hayden Christensen 饰）、孤僻的放映师保罗（约翰·雷吉扎莫 John Leguizamo 饰）、寻找尚在襁褓中孩子的临床医师罗斯玛丽（桑迪·牛顿 Thandie Newton 饰）以及12岁的黑人男孩詹姆斯（雅克布·拉铁摩尔 Jacob Latimore 饰）聚集于此。芝加哥似乎是他们最后的希望，他们必须想尽一切办法逃离永恒黑暗的吞噬……©豆瓣', '约翰·雷吉扎莫', '布拉德·安德森', 5.5, 6475, 'tt1452628', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p740320405.jpg', 9.2, 28.2, 44.4, 13.8, 4.3, '0.008151,0.203454,-0.566526,0.390347,-0.093948,-0.266092,0.957697,0.184379,-0.093453,-0.493684,0.297533,0.543665,-0.094684,0.014022,0.031797,-0.144687,-0.577334,-0.701283,-0.441086,-0.025114,-0.216353,-0.437337,-0.580130,-0.095321,-0.018574,-0.307682,0.532110,0.302810,-0.091459,0.255111,0.022810,0.216706,-0.352282,0.501549,-0.088789,-0.132476,0.009265,-0.070216,-0.198564,0.079139,-0.110723,-0.088033,0.104008,-0.143229,-0.128083,0.350507,0.628732,-0.529847,0.524824,-0.146836,0.248459,-0.210121,-0.081047,0.122143,0.090013,-0.024377,0.116955,-0.162249,-0.188996,-0.012527,0.145449,-0.097462,-0.706351,-0.058067,0.161755,0.376739,-0.273501,0.296630,0.233949,0.086904,0.218649,-0.173999,0.147008,-0.243109,0.018741,0.260962,-0.121727,-0.139767,-0.671563,0.062541,0.059300,-0.205944,-0.737151,0.095615,-0.523803,-0.320462,-0.130212,0.197608,-0.261458,-0.367080,0.567179,0.258984,0.039282,0.498547,-0.776510,-0.075147,-0.169327,-0.419083,-0.116989,-0.090152,-0.375474,-0.809536,0.158923,-0.128657,-0.043785,0.173221,0.003218,0.031000,0.560884,-0.480854,0.518305,0.527494,0.307473,0.146706,0.553680,-0.452383,0.512227,-0.129751,-0.132716,0.439116,0.096869,0.512442,0.235369,0.239236,-0.183309,0.321876,-0.475300,0.595959', '1316693', '25884436', '20451118', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3792508', '亲爱的伽利略', '剧情', '泰国女孩小樱（楚缇玛•提潘娜特Chutima Teepanart 饰）和小棉（贾琳珀恩•朱凯特Jarinporn Jookiat 饰）是一对好友，出于不同的目的，两人决定结伴到欧洲修学旅行。身处他乡，两个女孩享受着异国的美好与新奇，并结交了形形色色的朋友，同时也经历着生存与奋斗的种种艰辛，忍受着孤独与思念家人的煎熬。在彼此的互相扶持下，小樱和小棉一路走过了伦敦、巴黎和威尼斯。在旅行中，单纯柔弱的小棉逐渐坚强，并从失恋的阴影中走了出来，个性强烈的小樱逐渐学会理解并包容他人，而她所拥有设计才华也逐渐被挖掘出来。原本看似不会结束的旅行，却因为一场意外戛然而止，受牵连的小棉被遣送回国，小樱自责不已，担心小棉不肯原谅自己。最终，当小樱回到家乡，机场迎接她回国的亲友之间，会不会出现小棉的身影呢？©豆瓣', '楚缇玛·提潘娜特', '尼提瓦·塔拉吞', 7.9, 53347, 'tt1865460', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1074543362.jpg', 0.6, 2.9, 25.1, 44.3, 27.1, '0.302588,-0.059046,-0.721814,0.515134,0.115958,-0.202707,0.722367,0.074284,-0.517576,-0.292899,0.157338,0.735529,-0.247892,0.614564,0.235097,-0.116644,-0.437980,-0.568494,-0.227556,-0.163821,-0.431111,-0.404858,-0.146934,-0.054733,-0.274586,-0.205863,0.585390,0.289909,-0.233193,0.737226,0.359221,0.045526,-0.330294,0.549482,-0.014180,-0.152573,-0.162938,0.366896,-0.306275,-0.076663,0.190454,-0.235047,-0.228580,0.021271,0.211949,0.226695,0.939520,-0.437384,0.018562,-0.056768,0.183483,-0.206792,0.114480,0.156831,-0.225343,0.061431,0.289503,0.135242,-0.125473,0.159073,0.211559,-0.185391,-0.481423,0.130828,0.097376,0.075490,-0.541417,0.500818,0.153486,-0.204085,0.357039,-0.596701,0.046787,0.332878,0.211997,0.420100,-0.337883,0.071228,-0.291258,0.198776,0.977169,0.175517,-0.203716,0.323511,-0.588446,-0.262795,0.068652,-0.114650,-0.604781,-0.179576,0.278755,0.132351,-0.172831,0.493962,-0.603555,0.188968,-0.136437,-0.046853,0.048292,-0.493577,0.162929,-0.479582,-0.232611,-0.679234,-0.290197,0.229468,-0.025342,-0.313437,0.684168,-0.896466,0.269604,0.512928,0.442811,-0.429267,0.527666,0.088608,0.120211,-0.202316,-0.117830,0.551267,-0.180075,0.091367,0.086007,0.352068,-0.176084,0.277452,-0.644159,0.284693', '1292219', '35030151', '1299433', '2365260');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3792787', '长江7号爱地球', '动画', '狄爸（石仁茂 配音）与儿子小狄（徐娇 配音）居无定所，他每日在各建筑工地打零工，干最辛苦的活，可为了儿子将来有个好的前途，他勒紧裤带把儿子送进一所贵族学校。一天，狄爸在拉圾箱里捡到外星生物7仔，7仔像是一个万能的工具，它不但能帮小狄解决生活中遇到的各种麻烦和问题，还能源源不断地产生无尽的能量。小狄的同学蛋挞头的爸爸在一家研究所工作，发现7仔的神奇作用后，心生贪念，提出高价收购，狄氏父子根本不为金钱所动。恼羞成怒的他绑架7仔到研究所内，利用仪器压榨7仔身体内的能量。狄氏父子焦急万分，深夜潜入研究所内，救出了已经奄奄一息的7仔......©豆瓣', '徐娇', '袁建滔', 6.3, 8795, 'tt1453967', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p540441562.jpg', 5.1, 16.6, 47.2, 20.7, 10.3, '-0.062176,-0.172881,-0.676307,0.237079,-0.206152,-0.228932,0.331583,0.037610,-0.480331,-0.251509,-0.131323,0.407009,0.057952,0.351525,0.076136,-0.090628,-0.126955,-0.222258,0.115068,-0.131247,-0.252525,-0.215261,-0.291859,-0.480418,-0.146715,-0.150529,0.416647,-0.006612,-0.116738,0.096277,-0.039362,0.167839,-0.072711,0.427260,-0.159378,-0.112802,-0.089111,0.020060,0.086562,0.407856,-0.004478,0.015197,0.171518,-0.252894,0.362085,0.080505,0.753022,-0.151152,-0.214920,-0.337250,0.362363,-0.225292,-0.163294,-0.014629,0.167140,0.108695,0.320926,0.016416,-0.474631,0.152794,0.371468,-0.263576,-0.716181,-0.523932,-0.125995,-0.063047,-0.664523,0.151856,0.065859,-0.106392,-0.003696,-0.329416,0.463471,0.218607,-0.100438,0.600639,-0.408195,0.195319,-0.432095,0.158056,0.547911,-0.531731,-0.148192,0.260800,0.088910,-0.214404,0.221528,-0.102864,-0.324862,-0.144011,0.165083,0.270899,-0.419375,0.062118,-0.573154,0.092501,-0.156326,-0.137189,0.019005,-0.348771,-0.107631,-0.494618,-0.067311,-0.149400,-0.141778,0.106053,0.244742,-0.409802,0.559431,-0.499842,0.100106,0.460832,0.289305,-0.525360,0.512337,-0.161848,0.317086,-0.037582,-0.497226,-0.034575,0.280594,0.546015,0.039396,0.143638,0.122142,-0.264115,-0.061673,0.156820', '25928048', '10581450', '1300303', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3792799', '岁月神偷', '剧情', '60年代的香港，风云变幻。一面要忍受港英政府的压制，一面又受到内地运动的波及，更要面对不时登陆的台风暴雨。老字号的永利街就处在这样一个风暴的旋涡中心。鞋匠罗一家四口，在街尾以做鞋为生。罗先生（任达华 饰）做得一手好鞋，在那个混乱的年代仅能养家糊口；罗太太（吴君如 饰）为人辛辣直率，人称“侠盗罗嫂”。大儿子罗进一（李治廷 饰）16岁，品学兼优，是运动会的冠军，全家人的希望，也是永利街的骄傲；小儿子罗进二（钟绍图 饰）8岁，在父母溺爱之下，天性顽劣，出了名的顽皮整蛊……一家人艰难度日，也算其乐融融。然而大儿子与富家小姐芳菲（蔡颖恩 饰）之间一段纯美的初恋、一场扫荡整个香港的飓风暴雨、更有一场潜伏已久的噩梦，让这个普通家庭的平安幸福在一夜之间陡生变故、支离破碎……面对岁月这个最大的“神偷”，顽强不屈的人该如何去抵抗？2010第60届柏林电影节“新生代单元”最佳影片水晶熊奖，第29届香港电影金像奖最佳编剧、最佳男主角、最佳新演员、最佳原创电影歌曲4项大奖。', '吴君如', '罗启锐', 8.7, 549712, 'tt1602572', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p456666151.jpg', 0.2, 0.8, 10.6, 39.9, 48.5, '-0.217189,-0.118071,-0.555714,0.451905,0.118340,-0.193002,0.545809,0.314771,-0.393137,-0.174598,0.441854,0.745434,-0.300602,0.161375,0.216774,-0.136871,0.108261,-0.508690,-0.159357,0.015683,-0.011421,-0.016305,-0.307388,0.165894,-0.016183,-0.076702,0.449823,0.227404,-0.068362,0.340851,0.613270,0.140598,0.072279,0.045202,-0.192609,-0.017059,-0.066524,0.246144,-0.449111,0.210166,-0.187085,-0.236896,-0.196553,-0.042950,0.010410,0.146611,0.724317,-0.103223,0.056404,-0.054023,0.595383,-0.183439,-0.358927,0.103071,0.394273,-0.324042,0.198610,-0.112775,-0.163429,0.160538,-0.008872,-0.165432,-0.625864,-0.020637,0.263564,0.050124,-0.484988,0.240786,0.027194,0.001735,0.000773,-0.075807,0.116101,0.335230,0.146830,0.477071,-0.214929,0.237008,-0.320057,0.557490,0.542247,0.035213,-0.346511,0.241989,-0.270150,-0.255539,0.089948,-0.561202,-0.651953,-0.065206,0.302487,-0.230896,0.059329,0.244865,-0.537254,0.066673,0.026926,-0.132340,0.109780,-0.181566,-0.192920,-0.658321,-0.070836,-0.348467,0.102229,0.056605,0.165250,-0.297714,0.728558,-0.477424,0.247479,0.384972,-0.032046,-0.187816,0.617205,0.189820,0.260957,-0.231070,-0.215599,0.118534,-0.205861,0.245146,-0.108978,0.419738,-0.158725,-0.2