INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3792816', '精武风云·陈真', '动作', 'http://site.douban.com/106750/精武风云·陈真豆瓣小站为弘扬民族正气，精武英雄陈真（甄子丹 饰）当年在上海虹口道场击杀日本武术高手。在此之后他更名改姓，背井离乡，远赴法国务工。一战后陈真化名齐天元，重返阔别已久的祖国，并以实业家的身份结识了上海大亨刘禹天（黄秋生 饰）及性感妖艳的夜总会女郎KIKI（舒淇 饰）。刘张扬跋扈，大发战争财，但尚存中国人的骨气；KIKI表面单纯，实则是日本女间谍，长期潜伏夜总会搜集情报。一战虽然结束，但战争的阴影远远没有散去。陈真加入秘密的抗日组织，并希望争取到刘禹天的支持。与此同时，以皇军大佐力石猛（木幡龙 饰）为首的暗杀军团开始向爱国志士痛下杀手。鱼龙混杂、暗流涌动的上海滩，已是黑云压城，暴雨将至……©豆瓣', '甄子丹', '刘伟强', 6.1, 70678, 'tt1456661', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p620331226.jpg', 3.8, 17.5, 54.7, 19, 5, '-0.064385,0.057499,-0.569731,0.286054,0.181063,-0.142450,0.189876,0.256699,-0.382064,-0.209609,0.234029,0.361216,0.152503,-0.117036,0.152445,-0.120832,-0.007087,-0.528652,-0.173868,-0.161840,0.207846,-0.072030,-0.253554,-0.031086,-0.168005,-0.192541,0.706689,0.641167,-0.345101,0.675733,0.374672,0.216983,-0.129340,0.415750,-0.048860,-0.234868,0.021021,-0.045976,-0.494385,0.109608,-0.208693,-0.453204,-0.222210,0.107735,-0.019819,0.354278,0.364338,-0.005939,0.211952,-0.287408,0.213170,-0.233507,-0.323963,-0.024118,0.501958,-0.126836,0.110731,0.222951,0.281681,-0.054798,-0.113067,-0.184693,-0.527094,-0.055410,0.357045,0.082530,-0.423030,0.470276,-0.260882,-0.055385,-0.009754,-0.061929,-0.073466,0.218693,0.117701,0.053291,0.000278,0.315612,-0.431977,0.423674,0.678967,0.127351,-0.091317,-0.121153,-0.041217,-0.347468,0.007095,-0.401064,0.023832,-0.185276,0.211622,-0.427815,0.247969,0.129511,-0.559919,-0.030937,-0.149524,0.006836,0.135005,0.032780,-0.002188,-0.677417,-0.220476,-0.247062,0.003068,-0.073311,0.209789,0.044770,0.773907,-0.858011,-0.023362,0.465652,0.306381,-0.522751,0.489893,-0.038444,-0.070485,-0.133274,-0.196352,0.286884,0.202429,0.387653,-0.113104,0.225817,-0.411555,-0.341869,0.136070,0.110541', '1316589', '1826173', '25922902', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3792848', '相助', '剧情', '上世纪60年代，在密西西比州，黑佣艾比里恩（维奥拉•戴维斯 Viola Davis 饰）勤勤恳恳照顾女主人的女儿，后者因产后抑郁症只顾与闺蜜贪欢。密西西比大学毕业生斯基特（艾玛•斯通 Emma Stone 饰）在报社负责家庭主妇信箱，并由此开始黑佣的生存状态。其中，希利（布莱丝•达拉斯•霍华德 Bryce Dallas Howard 饰）无疑是反面教材，她态度傲慢，对黑佣米妮（奥克塔维亚•斯宾瑟 Octavia Spencer 饰）抱有偏见，并力主黑佣不能与主人共用厕所。最终因不堪受辱，米妮愤然离去，并以牙还牙，假借道歉之机让她蒙羞。斯基特开始采访艾比里恩和米妮，希望了解黑佣的生存状态，并为自己的新书积累素材。与此同时，马丁路德金领导的平权运动正在如火如荼地开展，而斯基特所在的密西西比州正是斗争的前沿，因为黑人遭射杀的血案，种族隔离开始，一场肤色之争在所难免……', '艾玛·斯通', '泰特·泰勒', 8.8, 99431, 'tt1454029', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1225179026.jpg', 0.1, 0.4, 7.4, 41.8, 50.3, '0.308588,-0.078192,-0.360578,0.351757,0.013122,-0.318678,0.500458,0.307899,-0.524060,-0.416948,0.065134,0.425041,-0.149142,0.034114,0.181129,-0.009954,-0.506313,-0.394892,-0.025772,0.002229,-0.015279,-0.395889,-0.111918,-0.228106,-0.246428,-0.351530,0.390410,-0.139107,-0.204929,0.379572,0.112717,0.431693,0.303384,0.118497,0.335187,-0.193376,-0.070458,-0.284864,-0.513260,0.147934,0.201729,-0.013960,-0.030689,0.277695,0.345462,0.362775,0.393652,-0.370279,0.206536,-0.349858,0.380757,0.091427,0.130202,0.280543,0.311876,-0.109680,0.343913,0.262647,-0.151710,0.040567,0.058162,-0.303115,-0.396813,0.063357,0.111510,0.183079,-0.276659,0.528506,-0.291551,-0.074336,0.187869,-0.023428,-0.307905,0.244934,0.292760,0.391496,0.057135,-0.011149,-0.120050,-0.035770,0.190067,0.045558,-0.085033,0.353740,-0.132106,-0.340087,0.098506,-0.153517,-0.287851,-0.285858,0.066052,-0.083461,0.058520,0.670789,-0.445592,0.176904,-0.466050,-0.216482,-0.063937,-0.141507,-0.039279,-0.695279,-0.013326,-0.146399,0.005808,-0.028124,-0.029949,-0.215545,0.267583,-0.695569,0.282047,0.462500,0.302011,-0.259482,0.378937,0.159084,0.290762,-0.441669,-0.091877,0.621103,0.127617,0.074948,0.004496,-0.044573,0.090543,-0.278209,0.063960,0.571618', '2034997', '3075921', '1945337', '2367243');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3793023', '三傻大闹宝莱坞', '剧情', '本片根据印度畅销书作家奇坦·巴哈特（Chetan Bhagat）的处女作小说《五点人》（Five Point Someone）改编而成。法兰（马德哈万 R Madhavan 饰）、拉杜（沙曼·乔希 Sharman Joshi 饰）与兰乔（阿米尔·汗 Aamir Khan 饰）是皇家工程学院的学生，三人共居一室，结为好友。在以严格著称的学院里，兰乔是个非常与众不同的学生，他不死记硬背，甚至还公然顶撞校长“病毒”（波曼·伊拉尼 Boman Irani 饰），质疑他的教学方法。他不仅鼓动法兰与拉杜去勇敢追寻理想，还劝说校长的二女儿碧雅（卡琳娜·卡普 Kareena Kapoor 饰）离开满眼铜臭的未婚夫。兰乔的特立独行引起了模范学生“消音器”（奥米·维嘉 Omi Vaidya 饰）的不满，他约定十年后再与兰乔一决高下，看哪种生活方式更能取得成功。本片获孟买电影博览奖最佳影片、最佳导演、最佳配角（波曼·伊拉尼）、最佳剧本等六项大奖，并获国际印度电影协会最佳影片、最佳导演、最佳剧情、最佳摄影等十六项大奖。', '阿米尔·汗', '拉吉库马尔·希拉尼', 9.2, 1751708, 'tt1187043', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p579729551.jpg', 0.2, 0.5, 4.9, 25.6, 68.8, '-0.101144,-0.117358,-0.352008,0.703968,0.166685,-0.196663,0.290260,0.068535,-0.163968,-0.238563,0.152606,0.678624,-0.382692,-0.136167,0.354039,0.045176,-0.568494,-0.623023,0.007620,-0.097049,0.044442,-0.550839,-0.273660,-0.027816,-0.272926,-0.339974,0.652072,-0.306433,-0.318523,0.368429,0.499838,0.200390,0.129412,-0.051446,0.104005,0.013552,0.423611,-0.042656,-0.341467,0.355785,0.106589,-0.072132,-0.256601,0.146877,0.363768,0.244433,0.451503,-0.161950,0.403205,0.196241,0.575364,-0.218341,-0.039536,0.059248,0.153420,-0.518704,0.299813,0.063960,0.075942,0.254689,0.008839,-0.225952,-0.543507,-0.159954,0.312844,0.118784,-0.413028,0.467240,-0.207897,-0.081717,0.084332,-0.013007,-0.132075,0.126902,0.221766,0.125696,0.100018,-0.275303,-0.189459,0.469024,-0.117039,0.046977,-0.278513,0.148191,-0.255722,-0.713434,0.068147,-0.130601,-0.537285,-0.017739,0.296083,-0.169192,0.333138,0.009114,-0.427431,-0.196672,-0.174127,-0.029732,-0.024420,-0.325283,0.273998,-0.945297,0.028179,-0.274929,-0.127366,-0.240073,0.159798,-0.265910,0.623636,-0.494622,-0.031241,0.316192,0.064887,-0.218489,0.535988,0.095391,0.077420,-0.433829,-0.273146,0.256611,0.106687,0.107518,-0.007005,0.516843,0.232189,-0.373244,-0.222197,0.468299', '1298616', '30397916', '10508921', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3793783', '地心引力', '科幻', '深邃浩瀚的外层空间，蔚蓝的地球与深不见底、漆黑一片的宇宙形成鲜明对比。一台隶属美国的空间站，数名宇航人员正进行太空漫步，对所属卫星做着例行检查。初上太空的瑞安·斯通博士（桑德拉·布洛克 Sandra Bullock 饰）在经验丰富的宇航员麦特·科沃斯基（乔治·克鲁尼 George Clooney 饰）的协助下，有条不紊地检查每一个部件。此次是科沃斯基退休前的最后一次飞行，他幽默风趣地活跃着团队的氛围。就在此时，休士顿总部传来骇人消息，不久前行将废弃俄罗斯卫星被导弹击毁，碎片以超过子弹的速度在地球轨道上散开，并意外击中其他卫星，引起连锁反应制造了新的碎片。瑞安一行遭到碎片重创，有的同伴不幸身亡，而她和科沃斯基失去控制坠入宇宙深处。幸存的二人不得不彼此信赖，拼尽全力朝向故土前进……©豆瓣', '桑德拉·布洛克', '阿方索·卡隆', 7.9, 418608, 'tt1454468', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2159078612.jpg', 1.1, 2.9, 22.7, 46.8, 26.5, '0.084504,0.141600,-0.834359,0.671293,0.186789,0.061957,0.765707,0.135479,-0.255473,0.085243,0.333452,0.609002,-0.204351,-0.207429,0.104164,0.068027,-0.563389,-0.478064,-0.379353,0.095612,-0.502483,-0.688891,-0.421466,-0.041411,0.176002,-0.567723,0.560851,0.043338,-0.214348,0.403047,-0.312140,0.352654,-0.237370,0.433101,-0.180163,-0.131285,0.072785,-0.210486,-0.315962,0.246583,-0.291742,0.064153,0.068071,0.009398,-0.173873,0.530111,0.684429,-0.136022,0.231575,-0.207269,0.100636,-0.176878,0.192930,0.015430,0.382575,0.308597,-0.072909,-0.047462,-0.189425,0.145546,0.161925,0.113036,-0.594743,-0.092693,-0.022023,0.132740,-0.335572,0.389636,-0.285031,0.011241,-0.079177,-0.300328,0.287606,0.342820,0.002511,0.252708,-0.243380,0.129366,-0.326352,-0.125002,0.569619,0.011960,-0.721486,0.145267,-0.124575,-0.367265,-0.215933,-0.111699,-0.293766,-0.404090,0.484228,0.077138,0.276086,0.303822,-0.778686,0.373372,-0.520359,-0.549732,-0.326279,-0.167449,-0.208414,-0.958877,0.186967,-0.292128,-0.412308,0.143339,-0.113300,0.072886,0.507808,-0.456145,0.283114,0.595085,0.208898,0.056641,0.498982,-0.200240,0.121443,-0.366241,-0.051272,0.164582,0.108797,0.623011,-0.128267,0.373483,-0.164194,-0.093468,-0.485922,0.292974', '3008263', '1307897', '2159244', '1293433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3796613', '与玛格丽特的午后', '喜剧', '肥胖、粗俗而不失善良的50多岁男人基曼（杰拉尔·德帕迪约 Gérard Depardieu 饰）住在母亲花园旁的房车里，平时打理菜园，和朋友们泡小酒吧，时而和年轻女友安妮特（索菲·吉耶曼 Gisèle Casadesus 饰）在小窝里浪漫温存，过着平静的生活。然而，他的内心却有着不为人知的脆弱和苦楚，母亲在不想要他的情况下怀上了他，从来不知道父亲是谁；老师因为他的愚笨嘲弄；哥们儿喜欢他却又常常嘲笑他。女友想要个孩子，他却因自卑一直不肯答应，导致两人关系紧张。有一天，基曼在公园里遇到了一边养着鸽子一边在大声读小说章节的玛格丽特（吉赛勒·卡扎德絮 Gisèle Casadesus 饰），他荒芜的脑袋里开始萌芽。知识渊博的玛格丽特是一个退休的农艺学家，几乎花了她一生的时间用来周游世界和阅读文学作品。从此，基曼把午后的时间交给了玛格丽特的阅读......©豆瓣', '热拉尔·德帕迪约', '让·贝克', 8.9, 44491, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p855075428.jpg', 0.1, 0.4, 7.1, 38.4, 54, '0.471894,0.048206,-0.652263,0.617110,-0.227845,-0.396968,1.012819,0.168988,-0.440303,-0.204339,-0.079873,0.519638,-0.091829,0.620042,-0.097817,0.198965,-0.507573,-0.637586,-0.063013,0.018407,-0.171579,-0.325686,-0.144761,-0.247933,-0.091809,-0.205568,0.332673,-0.029925,0.019011,0.246773,0.253845,0.116373,0.051911,0.391891,-0.392734,0.062973,-0.116372,0.030531,0.012805,0.086346,0.220834,-0.252491,-0.277700,-0.054120,0.427471,0.248973,0.682078,-0.151606,-0.214671,0.039093,0.381806,0.027008,-0.036755,0.115050,0.197488,-0.138082,0.387871,0.016909,-0.174668,0.045396,0.095304,-0.253172,-0.564520,-0.064843,-0.108343,0.186417,-0.551979,0.566813,-0.119417,-0.099163,0.074696,-0.492499,-0.009659,0.022706,0.021569,0.461646,-0.108316,-0.060411,-0.474207,0.187749,0.315208,0.045944,-0.105993,0.499197,-0.377563,-0.273313,0.061402,-0.213545,-0.701490,-0.200213,0.172704,-0.154678,-0.405126,0.218653,-0.409541,0.206105,-0.110755,-0.175145,0.039955,-0.428675,-0.413727,-0.142356,-0.012785,-0.555937,-0.444605,0.001104,0.113371,-0.180742,0.817960,-0.872440,0.356788,0.628675,0.284254,-0.248477,0.754169,0.191890,-0.035671,-0.015453,-0.026897,0.349117,-0.052386,0.144121,0.365051,0.436881,-0.090400,-0.102994,-0.538150,0.472967', '1292062', '1783772', '4233625', '1303077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3804436', '街角的小王子', '剧情', '《街角的小王子》是台湾首部“宠物愈疗系电影”。片中最重要角色，穿针引线的猫主角“小王子”事实上是由七只小猫轮流扮演的。单亲家庭的小静（郭碧婷 饰）是美术系学生，是网路上一笔一笔画着猫咪故事的超人气图文画家。但现实生活中，自从母亲过世后，她就一直活在自己封闭的内心。阿军（杨佑宁 饰）是摇滚乐团的吉他手，看似阳光的他乐声中却总是有着难以言说的忧郁。直到有一天当小静遇到一只叫“小王子”的小猫咪，也与这个似曾相识的摇滚乐手相遇，两人的命运渐渐发生了改变。这只街角的奶黄色小猫咪，串起了他们的爱情故事，也揭开了一个十多年来未解的谜。两人也逐渐发现彼此的命运早在十多年前就有着奇异的关联……©豆瓣', '杨祐宁', '林孝谦', 6.3, 10797, 'tt1848959', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p569390252.jpg', 2.3, 14.6, 54.5, 21.9, 6.7, '0.303968,-0.143783,-0.486459,0.600709,0.094587,-0.072638,1.015898,0.074077,-0.527118,-0.132045,0.320602,0.829153,-0.205518,0.470716,0.058119,0.093874,-0.099085,-0.762095,-0.114926,-0.197765,-0.031497,-0.247704,-0.392885,0.028612,-0.002947,-0.180543,0.773270,0.096143,-0.080816,0.336145,0.430958,0.023355,-0.261211,0.310252,-0.287697,0.133520,-0.047809,0.218594,0.193859,-0.120853,0.074190,-0.346204,-0.093193,0.103408,-0.245217,0.376977,0.693406,-0.503949,-0.120848,-0.042467,0.405204,-0.188488,-0.364933,-0.122330,0.299385,-0.002852,0.353386,0.038179,-0.118921,0.000872,-0.129760,0.012994,-0.551314,0.009123,0.135820,0.504879,-0.457839,0.347414,0.117268,-0.127524,0.260843,-0.415616,0.237930,0.023079,0.365075,0.425685,-0.107791,0.084739,-0.486705,0.292399,0.458253,0.084603,-0.511721,0.654754,-0.569858,-0.520292,-0.240918,-0.186224,-0.452871,0.044229,0.315759,0.142712,-0.378527,0.233124,-0.705043,0.200793,-0.022763,-0.038727,0.029039,-0.480453,-0.062299,-0.465624,-0.303336,-0.672457,-0.342448,0.148088,0.160019,-0.301544,0.696688,-0.905056,0.383485,0.531733,-0.188649,0.011868,0.753749,0.092461,-0.027434,-0.162755,0.259675,0.183526,-0.230880,0.009422,0.024404,0.482273,-0.022444,-0.050857,-0.509555,0.578455', '1292062', '1467779', '4275444', '5416009');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3804470', '分手说爱你', '剧情', 'Joe（房祖名 饰）与阿花（薛凯琪 饰）是一对相亲相爱的快乐小情侣，但是因一些微不足道的原因，Joe最终被女友踢出局。这个伤心的21岁男孩决定自杀，却在给亲友发电邮留遗书时发现一个奇怪的分手网站。该网站的法则是：只要Joe能够拆算其他情侣，他就可以跟自己的女友复合。正值此时，香港电影人黄真真和郑丹瑞筹拍一部爱情电影，他们向社会征集青年男女们的爱情故事，Joe也应征前往。黄真真对Joe分手后的经历非常感兴趣，于是拿出一部DV，请Joe将挽回女友的全过程拍下来。好友Sunny（邓健泓 饰）为了Joe勇于献身，在拆散Sunny及其女友后，阿花竟真地回到Joe的身边……©豆瓣', '房祖名', '黄真真', 7.4, 78092, 'tt1517633', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p633976563.jpg', 0.9, 4.7, 34.6, 44.3, 15.5, '0.342196,-0.025911,-0.417425,0.521569,-0.038947,-0.290034,0.807242,0.088348,-0.345045,-0.204817,0.041794,0.796335,-0.329985,0.443211,0.261576,-0.058047,-0.241154,-0.718170,-0.012817,-0.177434,-0.165485,-0.451139,-0.198642,0.008293,-0.245485,-0.076666,0.925954,-0.082755,-0.226596,0.438956,0.570270,0.092099,-0.119731,0.294993,-0.129324,0.138146,-0.118619,0.180134,-0.560155,0.071143,0.108830,-0.032808,0.043155,0.079276,-0.172596,0.191983,0.838012,-0.265321,-0.360925,0.019606,0.679516,-0.127857,-0.086788,0.209592,0.067595,0.120119,0.498372,-0.027010,-0.134879,0.033648,0.186278,-0.061267,-0.756334,0.137510,0.102793,0.140971,-0.520206,0.233963,-0.068308,0.003641,0.340181,-0.387892,0.232453,0.602594,0.340805,0.455447,-0.306008,0.064390,-0.433265,0.441361,0.652728,0.219769,0.122846,0.585283,-0.131665,-0.401602,-0.069807,-0.011036,-0.641357,0.196597,0.264824,-0.062924,-0.040434,-0.054439,-0.752561,-0.199071,-0.051451,0.041436,0.162901,-0.569412,0.100402,-0.556837,-0.160145,-0.324178,-0.229351,0.029839,0.265096,-0.407142,0.905513,-0.742417,0.052653,0.305976,0.417700,-0.753375,0.695265,0.382851,0.038326,-0.289566,0.011488,0.014156,-0.048762,0.092530,0.047664,0.114126,0.090632,-0.144107,-0.505700,0.229651', '4301278', '26759820', '3811356', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3804629', '招魂', '悬疑', '20世纪七十年代，罗杰（朗·里维斯顿 Ron Livingston 饰）与卡罗琳（莉莉·泰勒 Lili Taylor 饰）两夫妇带着他们五个可爱美丽的女儿，搬到了位于罗德岛哈瑞斯维尔的一幢旧宅居住。房屋虽然古旧沧桑，历史悠久，但是却让佩隆一家体会到回归田园的快乐与喜悦。谁知好景不长，接二连三的怪异事件相继出现，令女孩们惊声尖叫，也让佩隆夫妇的神经绷到极点。为此，他们辗转找到当时最负盛名的沃伦夫妇。丈夫埃德（帕特里克·威尔森 Patrick Wilson 饰）是天主教会唯一认可的驱魔师，妻子洛琳（维拉·法米加 Vera Farmiga 饰）则拥有窥见灵体的能力。他们不费吹灰之力便确定这座阴气十足的大房子的症结所在，而为了征得教会除灵的许可，他们必须深入期间搜集恶灵存在的证据……©豆瓣', '维拉·法米加', '温子仁', 8, 312102, 'tt1457767', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1936517673.jpg', 0.3, 1.7, 21.7, 49.5, 26.8, '0.059215,-0.032726,-0.684107,0.462484,-0.050009,-0.294005,0.762666,0.195923,-0.600474,-0.419717,0.185454,0.667353,-0.231383,0.222128,0.226229,0.215029,-0.276649,-0.270299,0.204361,-0.246314,-0.015996,-0.370217,-0.339408,-0.282479,0.103467,-0.557170,0.433722,0.177407,-0.042403,0.551568,0.096100,0.378357,-0.254725,0.053878,-0.226000,0.028333,0.227152,0.022700,-0.305701,-0.055185,-0.242626,0.035334,-0.150024,0.081850,-0.043181,0.298365,0.460681,-0.134946,-0.062819,0.061024,0.184630,-0.037392,-0.213644,0.286503,0.271901,-0.159246,0.035281,0.254735,-0.395684,-0.035522,0.145128,0.051692,-0.668145,0.140316,0.382314,0.099645,-0.400838,0.490944,-0.042437,-0.286002,-0.039698,-0.242617,0.147234,0.279038,-0.016364,0.591133,-0.022299,0.129078,-0.542959,-0.195814,0.489249,-0.229340,-0.158300,0.086417,-0.404460,-0.484619,-0.080576,-0.149393,-0.293073,-0.033700,0.276781,0.334621,0.130792,0.162940,-0.641676,-0.177880,-0.535721,-0.109012,0.068532,-0.441862,-0.054209,-0.877725,-0.105006,-0.316187,-0.044634,0.008795,0.060460,-0.313719,0.666788,-0.406317,0.204933,0.198155,0.251613,-0.310769,0.411348,-0.023226,0.298012,-0.248918,-0.216488,0.486542,0.206501,0.195237,0.146079,0.287619,-0.224482,-0.133891,-0.293545,0.399637', '10466639', '19965431', '1297659', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3804656', '冰球坏小子', '喜剧', '酒吧保安道格·格拉特（西恩·威廉·斯科特 Seann William Scott 饰）体格强壮，行事略有呆气，在一次观看冰球比赛时将不满观众嘘声的球员痛揍，他的壮举经好友拍摄公布后引起大众注意，阴差阳错加入当地一支冰球队从头学起，充当队中暴徒角色。一场场血战为道格赢来了知名度，在教练的请托和引荐下，道格进入职业小联盟的刺客队，刺客队中有因为受伤而产生心理阴影的昔日王牌球员泽维尔，而道格的任务，即是保证泽维尔等队友在场上的安全。道格在比赛之外结识了热爱冰球的姑娘伊娃（艾丽森·皮尔 Alison Pill 饰），他向姑娘笨拙的表达着自己的爱慕。另一方面，王牌冰场打手罗斯在前方等待着道格的挑战……©豆瓣', '西恩·威廉·斯科特', '迈克尔·道斯', 7.4, 7176, 'tt1456635', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1343676410.jpg', 0.7, 3, 35.9, 44.3, 16.1, '0.008441,0.011291,-0.347684,0.650144,-0.106428,-0.225151,0.428757,0.133778,-0.361448,0.053392,0.645735,0.723766,-0.174511,0.023195,0.365668,-0.312334,-0.164628,-0.693700,-0.289801,-0.074074,-0.280757,-0.477435,-0.132165,-0.225758,-0.010666,-0.585505,0.567068,-0.082848,-0.404199,0.330968,0.362686,0.216567,0.256204,0.155641,0.030291,-0.142190,0.282674,-0.428050,-0.308061,0.235604,-0.073159,-0.171771,-0.468091,0.033881,0.349407,0.283087,0.965622,-0.395644,0.106700,0.058194,0.336636,-0.225771,0.404185,-0.059716,0.287952,0.060237,0.011900,-0.045801,0.233834,0.177777,-0.199448,-0.049082,-0.471552,0.325674,-0.017672,0.305513,-0.771425,0.709100,-0.269398,0.041730,0.184346,0.024893,0.000871,0.215643,0.140688,-0.154832,-0.052557,-0.002317,-0.171499,0.052971,0.501262,0.059470,-0.129007,-0.164845,-0.294251,-0.493554,0.011154,-0.223795,-0.386538,-0.230019,0.542654,-0.169360,0.260304,0.125667,-0.457171,0.170197,-0.068910,-0.270293,-0.099904,-0.544520,-0.135206,-0.969075,0.097124,0.138771,-0.177524,0.004190,-0.061683,-0.196855,0.839731,-0.969121,-0.052241,0.799739,0.210112,-0.130273,0.685763,-0.084930,0.088039,-0.218205,-0.339183,0.110591,0.136712,0.060027,0.092287,0.502689,-0.123964,-0.357991,-0.084519,0.269464', '3811356', '1316589', '4127270', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3804683', '教皇诞生', '剧情', '随着老教皇的去世，红衣主教团齐聚梵蒂冈准备选出新一任教皇。世界各地虔诚的教徒和各路记者聚集在圣彼得广场，翘首以待那股从烟囱中飘出的白烟。可是在梵蒂冈内部，教皇的选举进行得并不顺利。有希望当选的候选红衣主教们纷纷互相推脱，经过几轮的挣扎选定了红衣主教梅尔维尔（米歇尔·皮寇利 Michel Piccoli 饰）。可是梅尔维尔完全没有做好成为教皇的心理准备，不仅在第一次与公众见面的阳台演说上临阵脱逃，甚至离家出走消失在罗马的大街小巷里。梵蒂冈一边对外安抚民众，一边全力搜寻落跑的教皇！在没有教皇的日子里，梵蒂冈里会发生什么不一样的状况？而回到民间的梅尔维尔又会在离家出走的几天里获得什么别样的感悟？©豆瓣', '南尼·莫莱蒂', '南尼·莫莱蒂', 7.6, 6178, 'tt1456472', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2555368392.jpg', 0.5, 2.7, 28.3, 54.2, 14.3, '0.498585,-0.014809,-0.908707,0.448021,-0.013249,-0.053335,0.784483,-0.013716,-0.552245,-0.332728,0.473054,0.794417,-0.496029,0.269115,0.333761,-0.057504,-0.641728,-0.769670,0.015872,-0.095447,-0.060850,-0.474041,-0.403354,-0.146118,-0.466655,-0.344689,0.538004,0.267718,0.090671,0.269561,0.251005,0.093934,0.123144,0.310818,0.022685,-0.130657,0.326307,-0.027383,-0.062694,0.278497,0.144311,-0.282396,-0.441514,0.147774,0.438895,0.479006,0.124432,-0.676153,0.343348,0.175867,0.440365,-0.369698,0.237174,0.538196,0.396222,0.330855,0.069918,0.288550,-0.036191,0.008245,-0.273364,-0.079304,-0.516567,0.053125,-0.022601,0.668247,-0.555459,0.596436,-0.097527,-0.142404,0.179130,-0.255586,0.151541,0.373163,-0.156035,0.398271,-0.168891,0.011505,-0.624007,-0.139548,0.574918,0.051447,-0.382789,-0.154657,0.059236,-0.293785,-0.057078,-0.039740,-0.332870,-0.216838,0.066043,0.075972,0.167280,0.517307,-0.590830,-0.114139,-0.374712,-0.648566,0.141035,-0.053531,-0.144066,-1.257870,-0.102747,-0.143276,0.014307,-0.103207,0.138578,-0.001202,0.457037,-0.953952,0.431618,0.205176,0.235606,-0.495247,0.599302,0.128199,0.311249,0.070824,-0.135603,0.266042,0.258988,0.503790,0.208744,0.365556,0.082542,-0.211041,-0.194084,0.306628', '3178770', '1297715', '25833539', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3804746', '花田喜事2010', '喜剧', '花田国太后思女成疾，国王沧海（古天乐 饰）急召公主遗珠（杨颖 饰）回国冲喜。遗珠公主前往中原学习多年，并与中原护花大将军麦炳荣（郑中基 饰）私定终身。在大将军护送公主回国途中，从海上救起落水女子黄莺（熊黛林 饰），后一行人遭遇“索玛丽”海盗抢劫，混战之中公主落水失踪。破产富豪黄百万（黄百鸣 饰）走投无路，只好让从水中捞来的失忆公主遗珠假冒女儿黄莺投靠指腹为婚的亲家吴尚书，不料却遭尚书胞妹势利眼吴温柔（吴君如 饰）的百般刁难，一行人纠缠于尚书府笑料百出。此时，黄莺被送进皇宫封为郡主，而女扮男装的公主遗珠却被国王沧海挑中参加比武招亲。女扮男装的公主遗珠、护花大将军麦炳荣以及和黄莺一见钟情的尚书之子吴上进（潘粤明 饰），三人通过重重比试，在“武痴”国王沧海的裁决下居然判定手无缚鸡之力的遗珠获胜。有情人能否终成眷属，真公主能否顺利归位，一切在喜闹中终见分晓。', '黄百鸣', '黄百鸣', 5.3, 75385, 'tt1456520', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p815404632.jpg', 10.4, 30.6, 46.3, 9.7, 3, '-0.107306,0.361347,-0.294539,0.370575,0.223562,-0.395947,0.584016,0.274529,-0.470355,-0.293275,0.614302,0.274274,-0.355014,-0.199056,0.518954,0.133924,-0.009208,-0.314420,-0.115023,-0.110602,0.058908,-0.272887,0.194643,0.004849,-0.079058,-0.172062,0.623380,0.008534,-0.009761,0.670302,0.454505,0.020725,-0.503580,0.406571,-0.164800,0.175171,0.018731,0.238080,-0.411604,0.294340,-0.033953,-0.261406,-0.145899,-0.089893,0.015547,0.044631,0.311390,-0.718582,0.466245,-0.275453,0.212786,0.029393,-0.012570,0.212184,0.417952,-0.179549,0.060585,0.120859,-0.111699,-0.145627,0.107173,0.012131,0.188204,0.305718,0.031325,0.122088,-0.333286,0.051492,-0.208395,-0.011024,-0.104347,-0.273911,0.291086,0.249869,-0.058207,0.052650,-0.030595,0.237684,-0.486237,0.432158,0.613211,0.047673,0.117877,-0.259760,0.503819,-0.434987,0.513020,-0.409244,-0.315587,0.297373,0.292802,-0.306458,0.286376,0.364421,-0.080212,-0.165660,-0.855691,0.375444,0.300928,-0.333853,0.107275,-0.258332,0.084936,-0.028365,-0.000749,-0.265195,0.652296,-0.113860,0.367313,-0.707657,0.120844,0.112819,0.163878,-0.691436,0.176522,0.207521,0.088791,-0.204990,-0.211732,-0.022396,0.063727,0.474787,0.054080,0.086352,-0.223358,-0.242698,-0.286436,-0.340367', '1307023', '1305060', '1293518', '3412830');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3804891', '无人区', '剧情', '小有名气但利欲熏心的律师潘肖（徐峥 饰），凭借扎实的法律知识和巧舌如簧的庭辩技巧，成功帮盗捕国家珍禽阿拉泰隼并残忍杀害一名警察的西北盗猎团伙老大（多布杰 饰）洗脱罪名。老大承诺十天后付清余款，潘肖则要求对方用一辆红色轿车抵押。在此之后，他驾驶着新车踏上从西北荒漠返回大都会的路程。谁知路上险情不断，先是和一对开卡车拉茅草的哥俩（王双宝 & 巴多 饰）发生摩擦，导致人伤车损，接着又不慎撞飞一个似乎拦车求助的男子（黄渤 饰）。自知摊上人命的潘肖辗转来到一家专事不法勾当的黑店，并在此结识了受困于此的妓女（余男 饰）。与此同时，盗猎老大尾随其后，似乎另有凶险计划。此时潘肖还没真正意识到，他前方是怎样一条充满凶险的旅途……©豆瓣', '徐峥', '宁浩', 8.3, 502356, 'tt1456660', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2159072475.jpg', 0.3, 1, 14.2, 50.5, 33.9, '0.162526,-0.015563,-0.339609,0.326033,0.159522,-0.145237,0.597625,0.101444,-0.386344,-0.042029,0.334632,0.300513,-0.009717,-0.186407,0.301284,-0.060138,-0.229191,-0.334843,0.202784,-0.133330,-0.234218,-0.434473,-0.052657,-0.151369,-0.082053,-0.032780,0.395582,0.217934,-0.216993,0.463556,0.244019,0.115681,-0.493200,0.224869,-0.243709,0.012237,0.057419,0.088954,-0.122447,0.036735,-0.197103,-0.339707,-0.065891,-0.319312,-0.086490,0.499986,0.666487,-0.003645,-0.174170,-0.019985,0.151951,-0.243994,-0.019241,-0.162253,0.166082,-0.000352,0.134484,0.235000,-0.191374,-0.028499,0.199584,0.106337,-0.332265,-0.136427,-0.170678,-0.097818,-0.511327,0.127859,-0.066774,-0.009423,-0.051360,-0.360575,-0.015412,0.184726,0.231372,0.061618,-0.020623,0.193614,-0.529362,0.053944,0.513974,-0.055662,0.063136,0.149261,0.012480,-0.491000,0.038168,-0.086611,-0.204559,-0.273791,0.470298,-0.118068,-0.152626,0.038044,-0.366312,0.083028,-0.292845,0.001648,-0.021805,0.021218,-0.220573,-0.352641,0.174762,-0.312886,-0.167996,0.327464,0.103104,0.015742,0.084603,-0.348478,0.026345,0.440402,0.192115,-0.304034,0.454163,-0.034497,0.109464,-0.143501,-0.392186,0.097422,0.260733,0.410292,0.107695,0.151901,-0.146477,-0.292435,-0.020599,0.140211', '21619567', '1394470', '26882457', '26897427');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3805091', '死亡实验', '剧情', '失业不久的特拉维斯（阿德里安·布洛迪 Adrien Brody 饰）在报纸上看到一则招工启事，酬劳为两周14000美元。为此所吸引，特拉维斯欣然前往。原来这是某机构发起的实验，研究者宣称实验将在州立监狱进行，包括特拉维斯在内的26名参与者被分成狱警和囚 犯，狱警必须按照严格的规定来管理囚犯，不服从命令者将受到惩罚。原本只以为是一场有钱可拿的角色扮演游戏，但随着实验的进行，权力的意志渐渐得到体现，所有的人都似乎迷失在角色之中……本片根据2001年的德国影片《Das Experiment》改编，故事取材自马利奥·乔丹努（Mario Giordano）的小说《黑盒子》。©豆瓣', '艾德里安·布洛迪', '保罗·舒尔灵', 7.3, 40893, 'tt0997152', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2189162724.jpg', 0.9, 5.1, 36.8, 43.2, 14, '0.305280,-0.113241,-0.428391,0.605258,-0.054236,0.048091,0.340048,-0.178477,-0.557756,-0.152775,0.244542,0.690351,-0.220230,0.012616,0.310132,-0.177850,-0.518200,-0.629482,-0.379883,-0.176675,-0.274666,-0.689568,0.119232,-0.246095,-0.124992,-0.602389,0.811468,-0.234319,-0.157265,0.024834,0.262359,0.409315,0.007869,0.070827,0.126310,-0.051401,0.175140,-0.260121,-0.108821,0.245543,0.065987,-0.231257,-0.113614,-0.006388,0.304827,0.414773,0.537312,-0.500991,-0.128537,-0.090930,0.712212,-0.340935,-0.143518,0.062402,0.232170,0.296165,0.117404,0.297156,-0.290823,0.367671,-0.045858,-0.343244,-0.849910,-0.548073,0.339589,0.204779,-0.485036,0.261282,-0.222740,0.133921,-0.066587,0.035007,-0.029812,0.300040,0.432417,0.451594,0.080068,-0.134620,-0.626159,0.263472,0.339055,-0.084822,-0.267575,0.190192,-0.179770,-0.567921,0.016762,-0.218912,-0.251898,0.146446,0.142773,-0.056223,0.138147,0.169966,-0.731380,-0.060952,-0.042576,-0.659560,0.040373,-0.459027,-0.398072,-0.804248,-0.038292,-0.047940,0.036892,0.114744,0.319354,-0.401509,0.605770,-0.786344,0.133832,0.533202,0.119481,-0.404010,0.546091,-0.010831,0.175914,-0.220542,-0.190644,0.034832,0.498987,0.393007,0.208632,0.075052,0.113245,-0.469888,-0.215725,0.568996', '26759820', '27073234', '1793491', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3805946', '比悲伤更悲伤的故事', '爱情', '从小被父母遗弃的电台制作人凯伊（权相宇 饰）和因交通事故痛失双亲的作词人洛琳（李宝英 饰），两人似家人、朋友和恋人一样生活在一起，填补了彼此生活里的空席。但一场绝症让凯伊只剩下200多天生命，他不舍得留下洛琳一人决定隐瞒病情为她寻找一个可以托付终身的男人。事业有成、温柔体贴的牙医朱焕（李凡秀 饰）适时的出现，凯伊决定让他成为照顾洛琳的最佳人选。首次见到洛琳的朱焕便对其一见钟情，不可自拔，而洛琳也似乎对他存有好感。一切都在凯伊的计划中，洛琳和朱焕顺利发展着感情，并到了谈婚论嫁的地步。凯伊亲自为洛琳挑选了结婚的礼服，带着留恋和真挚的祝福在教堂牵着她的手一步一步走到朱焕身边。最后没有任何遗憾的凯伊离开了人世，而事实上，故事，远比这里所写更悲伤......©豆瓣', '权相宇', '元泰渊', 7.7, 90564, 'tt1454545', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2020728553.jpg', 0.8, 3.9, 28.4, 42.7, 24.2, '0.216852,-0.026987,-0.742193,0.651683,-0.226730,-0.336370,0.795039,0.232310,-0.336018,-0.160538,0.164901,0.850272,-0.023618,0.309571,0.196304,-0.022196,-0.300247,-0.752379,0.009030,-0.038000,-0.288320,-0.501083,-0.009920,-0.123795,-0.298883,-0.265742,0.640921,-0.034325,-0.019210,0.634226,0.153645,-0.042238,-0.155001,0.584939,-0.125759,0.165036,0.053271,0.131731,-0.609819,0.224491,0.098073,-0.047574,-0.059641,0.337743,-0.055413,0.236256,0.738418,-0.162860,-0.202836,0.024289,0.296065,-0.275314,0.119404,0.142780,0.024460,0.110638,0.112365,0.346308,-0.344010,0.001775,0.243853,-0.162128,-0.726447,-0.009925,0.040704,0.210622,-0.764443,0.534765,-0.037339,-0.187618,0.272032,-0.388614,0.253025,0.215327,0.137922,0.295159,-0.375901,0.033529,-0.413056,0.234624,0.648729,-0.079882,-0.045834,0.540661,-0.282129,-0.415295,-0.093724,-0.027529,-0.702552,0.016448,0.032431,0.368115,-0.272424,0.145252,-0.286646,-0.057076,-0.114856,-0.085007,0.090477,-0.786533,0.237152,-0.450202,-0.178402,-0.463362,-0.518594,0.105395,0.039698,-0.440939,0.648280,-0.593679,0.275130,0.336744,0.468983,-0.647532,0.701110,0.289110,0.199562,-0.224475,0.096227,0.495694,-0.340690,-0.063948,0.285813,0.138655,-0.008655,0.254540,-0.506012,0.550002', '1456503', '26021055', '30140107', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3805953', '不能没有你', '剧情', '台北市中心，一个衣衫褴褛的男子李武雄（陈文斌 饰）怀抱着不满10岁的女童（赵祐萱），准备跳天桥自杀，这引起了警方和媒体的围追堵截。在电视机前，很多民众关注着事态的发展。面对警方，武雄口中疾呼“社会不公”，引起了大家的好奇。原来，武雄与前女友同居时育有一女，即他怀抱中的女童，孩子名叫妹仔。后来，前女友改嫁，音讯全无。武雄独立抚养女童，两人相依为命，生活悲惨。为了讨生活，武雄从事了多项高危工作，潜水排污就是其中之一。妹仔到了适学年龄，但是依照法律，法定监护人——即生母和继父才有资格办理手续。武雄虽为生父，却因无法律依据，无法行使监护人的权利，为了妹仔可以如愿入学，武雄踏上了一条艰辛的维权之路……本片取材于2003年一则社会新闻，获得第46届金马奖最佳影片、最佳导演、最佳原著剧本、年度台湾杰出电影4项大奖。©豆瓣', '陈文彬', '戴立忍', 8.2, 31696, 'tt1456584', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p936364155.jpg', 0.3, 1.1, 16.7, 49.7, 32.2, '0.009381,-0.073289,-0.586056,0.602651,0.124058,-0.100220,0.441467,0.245607,-0.384576,-0.152652,0.150256,0.648627,-0.112981,0.440746,0.235558,-0.159992,-0.105167,-0.549713,-0.270134,-0.245670,-0.161031,-0.368443,-0.095743,-0.006349,-0.571250,-0.087341,0.858378,-0.039369,-0.098230,0.384433,0.438854,0.150475,-0.312104,0.216619,-0.215842,0.003683,0.408479,0.067572,-0.433090,0.152221,-0.039268,-0.300382,-0.042710,0.160959,0.023397,0.277139,0.599141,-0.062669,-0.108999,-0.248222,0.612529,-0.122370,-0.199439,0.051005,0.521937,-0.098247,0.230269,0.321728,0.048411,-0.088222,-0.088332,-0.304819,-0.576586,-0.089657,0.225754,0.259783,-0.330876,0.315105,-0.323503,-0.044734,-0.001932,-0.115580,0.043262,0.334914,0.290199,0.279029,-0.198920,0.229180,-0.153041,0.520611,0.438266,-0.040607,-0.294681,0.263858,-0.298999,-0.545098,0.118094,-0.339616,-0.556243,0.059238,0.367845,0.010618,-0.248004,0.088183,-0.071522,0.048995,-0.026017,-0.186996,0.139586,-0.201259,-0.075578,-0.322901,-0.088648,-0.252320,-0.054160,0.121029,0.139192,-0.434328,0.878471,-0.540346,0.006334,0.412415,0.273251,-0.612511,0.637762,0.142887,0.311278,-0.402256,0.101666,0.159290,-0.171802,0.224214,-0.109950,0.012672,-0.092332,-0.249683,-0.145243,0.101641', '27602116', '25880986', '1908036', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3808604', '危情三日', '剧情', '匹兹堡的文学教师约翰（罗素·克劳 Russell Crowe 饰）本来有个幸福的三口之家，但这天警察突然登门，将他的妻子劳拉（伊丽莎白·班克斯 Elizabeth Banks 饰）以谋杀罪逮捕。几乎所有证据都指向劳拉是杀害自己女老板的嫌凶，连律师也认为翻盘无望，劳拉压力过大甚至尝试自杀。约翰执着的相信妻子的清白，他不需要妻子的解释，他信任妻子，这就足够了。想要救出妻子的约翰开始筹划越狱，他请教曾经多次越狱的越狱专家，仔细观察匹兹堡监狱的所有角落，一个越狱计划开始逐渐成型。然而监狱方面突然准备提前转移劳拉，约翰的时间，只剩下了三天。眼看出卖房屋筹集资金无法实现，约翰决定铤而走险抢劫毒贩，这个平时温和的男人，要为拯救妻子变身为强悍的战士！©豆瓣', '罗素·克劳', '保罗·哈吉斯', 8.1, 84883, 'tt1458175', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p657278407.jpg', 0.2, 1.3, 20.1, 52.4, 26, '0.251513,-0.032930,-0.570671,0.253403,-0.359973,-0.400680,0.627433,-0.007411,-0.291359,-0.401626,0.246784,0.490810,0.185582,0.094951,0.187891,0.045310,-0.317277,-0.625115,-0.068484,0.091183,-0.109866,-0.643013,-0.177870,-0.544347,-0.051537,-0.139018,0.482416,0.054674,0.112587,0.183672,0.227342,0.274156,0.277077,0.351805,-0.037304,-0.045356,0.213753,-0.252991,-0.411520,0.260976,0.102605,0.019201,0.082757,0.350352,-0.189319,0.620328,0.244388,-0.053885,-0.249217,-0.181928,0.526997,-0.374170,-0.095686,0.344193,0.238990,-0.085833,0.096880,0.136226,-0.189639,-0.330895,-0.046880,0.013709,-0.874649,0.034698,0.183813,-0.105834,-0.496326,-0.047450,-0.245145,0.376226,0.109503,-0.300182,0.002851,0.401360,0.062095,0.133541,-0.148741,0.117843,-0.415236,0.188706,0.524726,-0.369147,-0.011118,0.126952,-0.073882,-0.218156,0.160679,-0.259353,-0.337599,-0.048523,0.095505,0.149430,-0.193665,0.133460,-0.252437,-0.251607,-0.437973,-0.088726,0.119160,-0.377537,-0.032734,-0.412175,-0.156912,0.228046,-0.125722,-0.018783,-0.012006,-0.347389,0.451167,-0.577856,0.209440,0.448000,0.410244,-0.643467,0.511511,0.142146,0.114771,-0.319553,-0.006349,0.300298,0.167168,0.243400,0.099762,0.118593,0.262522,-0.223697,-0.318658,0.311202', '26678784', '35073886', '30163500', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3811342', 'Laughing Gor之变节', '剧情', 'Laughing（谢天华 饰）本认是警方的卧底，但政因为一择宗贩毒案件，被警司潘SIR（黄日华 饰）追捕。其实Laughing加入警队之前，本就是个黑帮成员，一直跟随其老大一哥（黄秋生 饰）在道上打拼。一哥对Laughing照顾有加，Laughing视一哥有如亲兄。一哥为了保护自己的地盘及非法生意，竟要求Laughing投考警队，让他可以掌握警方行动。Laughing在警校成绩优异，可惜天意弄人，他根本没机会待在警队，因为反黑警司冼SIR（元彪 饰）被Laughing的黑道气味所吸引，竟指派他做卧底探员。就这样，Laughing竟成了"双重卧底"，一哥也乐得Laughing被送进社团去对付自己的同门座头（吴镇宇 饰）。在这已经复杂的状况下，一件事情令Laughing的处境更复杂，他竟爱上了座头的妹妹Karen（陈法拉 饰）。面对法治、恩义、感情的抉择，Laughing将如何自处？无论选择哪一边，都是一场变节，Laughing最后将投向哪一方？', '谢天华', '邱礼涛', 6.5, 24381, 'tt1483421', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1359679594.jpg', 1.6, 10.4, 55.8, 25.7, 6.5, '0.112316,-0.047563,-0.405520,0.544483,-0.167273,-0.132008,0.219283,0.179433,-0.735907,-0.241515,0.235120,0.466448,0.117711,-0.078337,0.135139,-0.040854,-0.188518,-0.733118,-0.084167,-0.174335,-0.276361,-0.330314,-0.281704,-0.195204,-0.021932,0.053504,0.552057,0.159035,-0.330500,0.123860,0.531502,0.311990,-0.128203,0.395822,0.019722,-0.255985,0.108716,0.129496,-0.274810,0.067421,0.108863,-0.457418,-0.004940,0.160667,0.262096,0.313266,0.380648,-0.213403,-0.247593,-0.165023,-0.029680,-0.426057,0.072313,0.159667,0.410067,-0.097025,0.210253,0.323272,-0.191229,0.101045,0.096082,0.015853,-0.945870,-0.089433,0.278696,0.013214,-0.661843,0.234005,-0.184790,-0.074671,-0.050776,-0.198775,0.188201,0.328970,0.115760,0.179394,-0.160003,0.040106,-0.334922,0.333796,0.652056,0.063010,0.170380,-0.008657,0.073082,-0.371378,-0.112573,-0.307311,-0.186222,-0.028438,0.157894,-0.261041,0.202443,0.064292,-0.232899,-0.179123,-0.041234,-0.070103,-0.188827,-0.499471,0.271373,-0.166180,0.002150,-0.172356,-0.362277,0.146198,0.178802,-0.180940,0.484309,-0.768744,-0.021153,0.455547,0.248446,-0.691059,0.531619,0.254410,0.142938,-0.347843,-0.280690,-0.019283,0.286211,0.314573,0.285900,0.212377,-0.00