INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3811353', '机动战士高达00 剧场版：先驱者的觉醒', '科幻', '【故事简介】利翁兹·奥马克与天人的战斗以真正的改革者刹那·F·清英等人的胜利拉上了帷幕。独立治安维和部队A-Laws解体，世界终于走向了和平。这样过了两年，西历2314年，表面上消失了的天人为了防止战争发生仍然在暗处活动着，这时，新的战争打响了信号。再次集结起来的高达驾驶员们乘坐着新式高达，开始了战斗！【STAFF】企画：sunrise原作：矢立肇、富野由悠季脚本：黑田洋介人设原案：高河弓动画人设：千叶道德机体设定： 海老川兼武、柳濑敬之、福地仁、鹫尾直广、寺冈贤司、中谷诚一、大河原邦男动画机体设定： 中谷诚一美术设定：须江信人（KUSANAGI）美术监督：若松荣司（KUSANAGI）色彩设计：手岛明美（Wish）音响监督：三间雅文摄影监督：葛山刚士（旭Production）旁白：古谷彻制作人：池谷浩臣（sunrise）、佐々木新（sunrise）监督：水岛精二制作：创通、sunrise', '宫野真守', '水岛精二', 7.5, 7741, 'tt1726286', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p709249778.jpg', 2.5, 6.7, 30.4, 35.4, 24.9, '0.009093,-0.129142,-0.425859,0.285430,0.416692,-0.211167,0.088030,0.429146,-0.066819,-0.480383,0.335817,0.525362,-0.430704,-0.185101,0.272303,-0.135195,-0.646107,-0.545281,-0.319092,-0.084986,-0.276846,-0.379547,0.213384,-0.184477,-0.165706,-0.420097,0.682477,-0.108227,-0.205290,0.227950,0.053409,0.113654,-0.219760,-0.081323,0.211640,-0.038976,0.090280,-0.346753,-0.042531,-0.002579,-0.520396,-0.213733,-0.271002,0.080854,0.072387,0.288423,0.797880,-0.360498,0.120521,-0.138430,0.162943,-0.211704,0.013877,-0.184368,0.268086,0.071926,-0.052376,0.292069,-0.056600,0.074139,-0.169115,-0.429136,-0.395517,-0.177381,-0.371420,0.220285,0.085353,0.295281,-0.170148,0.101859,0.126593,-0.171962,-0.049229,0.159074,0.531988,0.219953,-0.349536,0.121406,-0.140200,0.280018,0.445472,0.001407,-0.289600,0.480029,-0.038323,-0.514412,-0.641760,-0.166587,-0.315804,-0.251235,0.349263,-0.223073,0.324726,0.136479,-0.603367,-0.074011,-0.041227,-0.125065,0.101150,0.124436,0.040265,-0.771334,-0.085694,-0.108566,-0.097108,0.158540,-0.026240,-0.194474,0.856952,-0.713690,-0.062663,0.433194,0.260263,0.003026,0.281129,-0.064560,0.208102,-0.171604,0.132386,-0.215553,-0.209524,0.591372,0.149932,0.371634,-0.071216,-0.188140,-0.