INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3811356', '摇滚新乐团', '剧情', '刚满16岁的高中生田中幸雄（佐藤健 饰）是一个平凡无奇的男孩，被人称作小雄的他经常受到别人的欺负，对一切都倍感无聊，某天，他偶然结识了带着一条牛头梗的帅气男孩南龙介（水嶋ヒロ 饰）。龙介早年在纽约求学，为了完成音乐的梦想回到祖国。但是他狂放不羁的性格和对音乐的执着使之与乐队决裂。在此之后，龙介网罗了说唱歌手千叶恒美（桐谷健太 饰）、贝司手平义行（向井理 饰）等人，自组乐队BECK，准备再战江湖。受龙介的感染，小雄也苦练琴技，更借因缘和爱好架子鼓的转校生樱井裕志（中村蒼 饰）一起加入了BECK，他宛若天籁般的声线引领着这群年轻人向音乐的圣殿迈进……本片根据ハロルド作石的同名原作漫画改编，应作者的要求，影片中小雄的歌声采取消声处理。©豆瓣', '水岛宏', '堤幸彦', 7.6, 8043, 'tt1587118', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p894733361.jpg', 1.2, 5, 29.2, 42.5, 22.2, '0.145118,-0.090954,-0.300483,0.475802,-0.191698,-0.143885,0.481772,0.417216,-0.203731,-0.366742,0.106327,0.762572,-0.102584,0.321319,0.300056,-0.037795,-0.126864,-0.715014,-0.116560,-0.000250,0.141343,-0.132268,0.175581,-0.010721,-0.231113,-0.292958,0.700711,-0.086683,-0.312139,0.726273,0.314188,0.250308,-0.008152,0.079085,-0.154699,0.031057,-0.119477,0.128485,-0.035735,0.129705,-0.175689,-0.295472,-0.182208,-0.024354,-0.138518,0.266218,0.897035,-0.127002,0.019521,-0.157109,0.360903,-0.230195,-0.150816,-0.096400,0.201747,0.188195,-0.044562,0.352410,-0.138516,-0.022895,-0.053598,-0.148287,-0.594278,0.046530,0.133777,0.175945,-0.371259,0.421476,-0.041604,-0.059295,0.172127,-0.178064,-0.024785,-0.010769,0.335332,0.260613,-0.156940,0.207047,-0.199905,0.344785,0.601081,-0.009774,-0.170352,0.389173,-0.277075,-0.441075,-0.240167,-0.281535,-0.505478,-0.100516,0.126213,-0.229628,0.047559,-0.173031,-0.581894,-0.112988,0.222431,-0.029469,0.074246,-0.349250,0.008942,-0.879550,0.042633,-0.416125,-0.145404,-0.020793,0.286329,-0.239416,1.115052,-0.771970,0.049052,0.571743,0.172991,-0.298198,0.504074,0.015333,-0.123651,-0.095771,-0.099031,0.180555,0.106983,0.073589,0.033800,0.537804,-0.122341,-0.176813,-0.512445,0.226221', '5403927', '25922902', '25863940', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3813779', '剑雨', '动作', '八百年前，天竺人罗摩来至中原弘法，其死后尸体被人盗取并分为两部分。传说拿到罗摩尸体的人能练成绝世武功，因此江湖上风波骤起。时有转轮王（王学圻 饰）操控的黑石杀手集团，专为朝廷杀害谋逆相左之人。转轮王率徒众夜袭藏匿半具达摩尸首的首辅张海端（李庆祥 饰）宅邸，但是他的手下细雨 （林熙蕾 饰）却带着残尸绝走江湖，致令转轮王发出江湖追杀令，引出一阵血雨腥风。为避追杀，细雨易容，更名曾静（杨紫琼 饰），逃亡期间结识了木讷善良的江阿生（郑宇成 饰）。一段时间相处，二人渐渐萌生感情，更喜结连理。但是江湖恩怨，因蔓不断，怎可轻易了结……©豆瓣', '杨紫琼', '苏照彬', 7.6, 200446, 'tt1460743', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p636665128.jpg', 0.8, 4.6, 30.8, 42.1, 21.7, '-0.316301,0.072527,-0.354332,0.474656,0.358583,0.061574,0.393026,0.213037,-0.444952,-0.474424,0.220720,0.201305,0.005207,-0.130972,-0.102518,-0.335535,0.113872,-0.549820,-0.048648,-0.188636,-0.167188,-0.068381,-0.188492,-0.217345,-0.268291,-0.244202,0.576349,0.433551,-0.113005,0.432407,0.195337,0.125023,-0.418573,0.240881,-0.308374,-0.157461,-0.268256,0.191030,-0.312118,-0.193368,-0.549364,-0.452923,-0.191606,-0.323758,-0.211828,0.388245,0.567508,-0.244383,0.116657,-0.365300,0.204128,-0.234643,-0.085484,-0.127044,0.388575,0.155707,0.201093,0.488825,-0.173406,-0.283733,0.134613,-0.030985,-0.390397,0.142220,0.077474,0.071963,-0.272551,0.235944,-0.170328,0.224366,-0.199889,0.046744,0.205923,0.232874,0.271592,-0.155577,0.004036,-0.039121,-0.471651,0.366095,0.382365,-0.190269,-0.012402,0.028055,0.291043,-0.391961,0.055356,-0.288930,0.153212,-0.247400,0.491410,-0.243374,0.196793,0.524737,-0.382309,-0.362489,-0.266362,0.345199,0.171931,-0.031030,0.086728,-0.614915,-0.269213,-0.096406,-0.262945,-0.111013,0.370511,-0.002838,0.533187,-0.392239,0.269314,0.082070,-0.072582,-0.429059,0.369740,-0.012194,0.079606,0.022772,-0.208193,0.420318,0.373840,0.211601,0.113782,0.138394,-0.187326,0.160086,-0.070724,0.013722', '2369613', '25723905', '20274039', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3815920', '恋爱前规则', '剧情', '在北京工作的台湾动画设计师陆飞（陈柏霖 饰）平静的宅生活被一名醉酒女孩冉静（王珞丹 饰）打破，从一次两人都很被动的借宿事件开始，空姐冉静似乎对这位抱持“不恋爱主义”的木讷大男孩产生了兴趣，几次接触后，冉静带着大包小卷以及数不清的“共同居住”规则分享了陆飞的居所，陆飞自在的单身状态宣告终止，心有不甘之余却又渐渐适应了在冉静的督促照顾下生活工作，后者的到来，更使陆飞因久无灵感而搁浅的动画创作出现了转机。陆飞还未来得及细细体味爱情的甜蜜，一场变故迫使他做出改变两人生命轨迹的抉择……本片根据网络小说《和空姐同居的日子》改编。©豆瓣', '陈柏霖', '蒋钦民', 5.1, 29450, 'tt2215604', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p509215484.jpg', 12.3, 34.5, 42.9, 8.4, 1.9, '0.141512,0.102275,-0.642416,0.449784,0.033335,-0.250841,0.725372,0.160289,-0.380544,-0.289921,0.300941,0.416028,-0.497788,0.283263,0.288164,-0.365964,-0.385634,-0.651612,0.092204,0.231785,-0.182609,-0.109917,-0.102334,-0.141725,-0.277011,-0.324508,0.790331,-0.014032,-0.315883,0.348882,0.037096,0.069884,-0.141994,0.634124,-0.009106,0.033949,-0.094762,0.298037,-0.321663,-0.023153,0.223938,-0.495868,-0.374129,0.169470,-0.050916,0.533297,0.999777,-0.152705,-0.442630,0.030485,0.584057,-0.122860,-0.219662,-0.081774,0.130428,0.192501,-0.071127,0.043719,-0.127958,0.141509,0.004100,0.052916,-0.322015,0.164226,-0.035260,0.323502,-0.376354,0.419945,-0.001425,-0.135665,0.024794,-0.412697,-0.046286,0.525811,0.521720,0.351793,-0.210773,0.261524,-0.218887,0.400880,0.692627,0.022513,-0.458805,0.603121,-0.369212,-0.575871,-0.179924,0.160104,-0.465332,-0.153872,0.148733,0.151487,-0.247906,0.328953,-0.638497,0.014139,-0.068308,-0.212665,0.028706,-0.471482,-0.056131,-0.939667,-0.298344,-0.320641,-0.266828,-0.013394,0.260724,-0.251106,0.640554,-0.843711,0.073908,0.335421,0.058673,-0.551379,0.493921,0.262662,0.034655,-0.324347,0.039214,0.437951,-0.355451,0.083192,0.219566,0.389192,-0.043680,0.135296,-0.245414,0.511476', '5403927', '3811356', '1302050', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3818565', '梦宅诡影', '剧情', '在一个飘雪的季节，小有成就的出版人威尔·艾藤森（丹尼尔·克雷格 Daniel Craig 饰）辞去工作，带着妻子莉比（瑞切尔·薇兹 Rachel Weisz 饰）和一双可爱的女儿离开喧嚣的纽约市，来到安静的新英格兰镇展开新的生活。新的环境，新的磨合，表情冷淡甚至露着敌意目光的邻居，化着浓重哥特妆容不请自来的小青年，都令维尔的的幸福显得那么脆弱不堪。与此同时，女儿们似乎也受到神秘诡异的事物所侵扰。随着奇怪的事情不断涌现，艾藤森夫妇渐渐察觉他们的房子当年曾经发生过凶杀案。威尔偷偷对房子的过去展开调查，而这个平凡的四口之家好像也成了他人锁定的目标……©豆瓣', '丹尼尔·克雷格', '吉姆·谢里丹', 6.3, 10940, 'tt1462041', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1199857657.jpg', 2.6, 16.4, 51.9, 22.2, 6.8, '0.353946,-0.196124,-0.742341,0.524802,-0.147909,-0.093512,0.867532,0.399142,-0.286437,-0.396658,0.131590,0.543489,-0.203233,0.324416,0.424037,0.057792,-0.273738,-0.567832,-0.159926,-0.174488,-0.062269,-0.339527,-0.114312,-0.399192,0.088871,-0.380311,0.409343,0.325564,-0.107312,0.625226,0.222848,0.323161,-0.141234,0.444778,0.056102,-0.170043,-0.003222,-0.022801,-0.163823,0.027533,-0.044231,0.003890,-0.226043,0.303839,0.029754,0.457291,0.883215,-0.169813,-0.466306,0.023635,0.380385,0.043463,0.123737,0.193542,0.248566,0.069637,0.044545,0.061404,-0.174940,-0.142842,-0.043985,-0.168588,-0.473389,0.327037,0.130144,0.202329,-0.250699,0.346559,0.087935,-0.215790,0.075599,-0.557941,0.204727,0.221425,-0.017924,0.564419,-0.015731,0.538549,-0.414617,0.066296,0.356591,0.106868,-0.420837,0.405798,-0.411793,-0.316288,-0.228495,-0.134634,-0.576036,-0.083763,0.334550,0.020499,0.136024,0.516137,-0.822252,-0.123722,-0.096008,-0.280300,0.069338,-0.317871,-0.158473,-0.755303,-0.238396,-0.436622,-0.394107,0.130400,-0.158592,-0.209189,0.318830,-0.731610,0.491513,0.297948,0.129608,-0.441568,0.324585,-0.153757,0.273583,-0.034059,-0.633225,0.492870,0.179500,0.367585,0.204038,0.345479,-0.054923,-0.035851,-0.375837,0.568703', '25884436', '2269893', '4706257', '3097044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3819871', '蒂莫西的奇异生活', '剧情', '吉姆·格林（乔尔·埃哲顿 Joel Edgerton 饰）和辛蒂（詹妮弗·加纳 Jennifer Garner 饰）是一对婚后多年的夫妻，他们琴瑟合璧，生活无忧，美中不足的是一直没有小天使降临夫妻之间，虽然尝试各种办法，可最终一无所获，这也成为夫妻俩心中的隐痛。这一晚，格林夫妻将心中的渴望写在纸上，埋在院子里。是夜，狂风暴雨席不期而至。而伴随着大雨来到格林夫妻家中的，竟是一个满身泥泞、乖巧伶俐的十几岁小男孩。男孩自称蒂莫西（卡梅隆·CJ·亚当斯 Cameron ''CJ'' Adams 饰），与格林夫妇为孩子预先取的名字一样。许是上苍听到了夫妻的愿望，为他们派来这样一个可爱贴心的小天使……©豆瓣', '詹妮弗·加纳', '彼得·赫奇斯', 7.8, 41576, 'tt1462769', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1844152382.jpg', 0.3, 2.4, 26.7, 47.5, 23.1, '0.295755,-0.048618,-0.688974,0.709423,-0.031249,-0.472210,0.912598,0.192016,-0.665995,-0.160326,0.136894,0.646926,-0.527267,0.326663,0.169402,-0.026398,-0.340280,-0.549790,-0.193041,-0.212446,0.012651,-0.486408,-0.249511,-0.157367,-0.153430,-0.132846,0.443882,-0.050583,0.553491,0.607479,0.398254,0.128695,-0.312626,-0.010297,-0.353750,0.065742,-0.058658,0.218129,-0.246082,0.168329,-0.024039,0.236496,-0.080331,0.109757,-0.131425,0.412007,0.662148,-0.574764,0.060252,-0.028317,0.132178,-0.278123,0.068570,0.181149,0.339583,-0.158573,0.398851,-0.093445,-0.196784,-0.198222,0.144574,-0.117950,-0.366471,0.224533,0.284149,0.169099,-0.698795,0.551221,-0.120592,-0.197851,0.192666,-0.336049,0.314569,0.401082,0.353715,0.617305,-0.161558,0.274606,-0.402785,-0.067377,0.571168,-0.131988,0.001091,0.430024,-0.456910,-0.374573,0.138514,-0.045619,-0.648859,-0.132078,0.082370,0.051477,0.047758,0.021300,-0.669825,0.145614,-0.462662,0.190308,0.156457,-0.594897,-0.027867,-0.550685,-0.049582,-0.570890,-0.427064,0.078320,0.069625,-0.079162,0.762547,-0.523213,0.226912,0.117807,0.006127,-0.020875,0.662200,0.355029,0.188292,-0.206433,0.039315,0.371766,0.013784,-0.165779,0.214656,0.189729,-0.137582,0.284944,-0.343514,0.394273', '3111650', '25723780', '21619567', '1414808');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3819877', '活埋', '剧情', '在伊拉克的美国承包商保罗（瑞安·雷诺兹 Ryan Reynolds 饰）醒来的时候，发现周围一片黑暗什么都看不见。经过自己的不断摸索，发现手边有一个打火机，一把小刀和一部手机，而自己仿佛是被关在了一口棺材中活埋在了沙漠的某处。他记不清自己如何被关在这里，在这黑暗狭小的环境下，保罗不断尝试与外界联系，想知道自己身上到底发生了什么事情。随着时间的推移，保罗终于知道自己发生了什么。不过，目前最危急的情况是，怎么才能逃出困境。能与外界联系的仅有一部手机，而且电也快耗尽了。如何合理利用这仅有的东西？保罗终于用手机与美军有关部门联系上了，可是自己完全不知道自己所在，怎么办？©豆瓣', '瑞安·雷诺兹', '罗德里戈·科尔特斯', 7.9, 138931, 'tt1462758', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p598565639.jpg', 0.7, 2.5, 22, 50.1, 24.6, '0.287234,0.177238,-0.952331,0.419590,0.006736,-0.019161,0.768802,-0.270768,-0.474441,-0.509557,0.057065,0.552836,-0.110695,0.046333,-0.259933,0.138773,-0.440339,-1.046402,0.208980,-0.319613,-0.889625,-0.569934,-0.637531,0.137925,0.289758,0.036437,0.454406,0.270855,-0.266934,-0.201332,0.073175,0.071328,-0.055295,0.781325,-0.209086,0.066876,0.057694,-0.031026,0.002097,0.050489,0.397261,-0.455876,-0.299399,0.207911,0.252102,0.473582,0.387611,-0.236380,-0.320889,0.301046,0.245599,-0.076713,-0.062688,0.128555,0.293455,0.008031,0.108604,-0.215597,-0.403562,-0.107125,-0.051141,0.281378,-0.829039,0.034031,-0.320196,0.330690,-0.577446,0.161366,-0.147232,-0.266093,-0.028889,-0.559492,0.617019,0.601077,0.213940,0.302997,-0.466559,-0.394347,-0.789237,-0.274046,0.638106,0.004781,-0.235044,0.606746,-0.001795,-0.326425,-0.463089,0.088363,-0.305660,-0.179445,0.353981,0.320904,-0.506696,0.174290,-0.319052,0.248496,-0.161214,-0.550954,-0.089452,-0.515437,-0.252055,-0.129241,-0.536506,-0.482464,-0.246513,-0.018291,0.048134,-0.205388,0.554942,-0.878363,0.075709,0.606315,0.176750,-0.261050,0.540992,0.138620,0.029428,-0.037941,0.102302,-0.115717,0.255508,0.508670,0.389803,0.338980,0.440664,-0.116391,-0.638451,0.365428', '1947080', '25870679', '1306801', '1299292');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3819939', '极恶非道', '动作', '隶属于关东头号黑帮组织山王会的池元组头目（国村隼 饰）曾在监狱与小组织村濑组头目（石桥莲司 饰）结为兄弟。山王会野心勃勃，时刻觊觎村濑的地盘和毒品生意。在山王会若头加藤（三浦友和 饰）的授意下，池元命令麾下的大友组向村濑组发起挑战。大友（北野武 饰）的猛烈攻击和山王会老大（北村总一郎 饰）的毒辣计谋令村濑节节败退，被迫退休，组内的生意也易作他主。大友组人才辈出，若头水野（椎名桔平 饰）和干部石原（加濑亮 饰）亲自主持在某非洲国家使馆开辟赌场，一时间财源滚滚。然而风云变幻，在早已抛弃了传统仁义道德的黑帮社会，各种阴谋纷纷浮现，大友组风雨飘摇……©豆瓣', '北野武', '北野武', 8, 57635, 'tt1462667', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2254632477.jpg', 0.3, 1.5, 21.5, 52.5, 24.2, '-0.179417,-0.010375,-0.297307,0.358418,0.114292,0.206351,0.048958,0.566478,-0.579189,-0.150075,0.491913,0.627323,0.126232,-0.174738,0.140904,-0.160923,0.034474,-0.514217,-0.137350,-0.138037,0.136190,-0.303039,-0.240032,-0.464858,-0.065666,-0.175786,0.651317,0.221941,-0.308956,0.367361,0.556741,0.613681,-0.200636,-0.052874,0.004367,-0.115190,0.288379,-0.032688,-0.349716,0.155970,-0.774767,-0.251378,-0.335499,0.153006,0.347624,0.318582,0.366292,-0.226511,-0.070332,-0.452888,-0.037539,-0.358558,-0.081981,0.311321,0.789365,-0.202165,0.077724,0.573228,-0.042929,-0.130188,0.199410,-0.076136,-0.428067,-0.119759,0.256785,0.185444,-0.383085,0.318217,-0.072529,-0.058610,0.163583,0.002658,-0.056280,0.350028,0.288967,0.133217,-0.071538,0.213725,-0.193420,0.262193,0.461187,-0.146492,0.084279,-0.258414,0.151371,-0.311171,-0.365262,-0.433467,-0.140973,-0.412261,0.237946,-0.327268,0.056360,0.282089,-0.485156,-0.091353,0.225708,-0.038872,0.327777,-0.206540,0.054248,-0.764952,-0.098150,-0.452717,-0.192256,0.596571,0.247585,0.326785,0.651108,-0.966598,-0.186614,0.426117,0.156528,-0.314736,0.235437,0.362933,-0.333828,-0.151011,-0.065769,-0.285113,0.285809,0.352626,0.040978,0.215726,-0.230060,-0.383117,-0.082958,-0.145411', '1316589', '25723905', '2369613', '26999591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3820191', '杜拉拉升职记', '剧情', '杜拉拉（徐静蕾 饰）是个初入职场的小白领，由于前任老板总是对她性骚扰，所以她决定跳槽，进入了著名跨国企业DB。DB的销售部金牌经理王伟（黄立行 饰）与HR副总监玫瑰（莫文蔚 饰）是一对地下情人，但是由于两人的工作压力都很大，以至于谁也无暇顾及家庭，双方大方分手。杜拉拉刚来DB，遇到了互相斗法的伊娃（李艾 饰）和海伦（吴佩慈 饰）。因为一次巧合，在电梯里邂逅了患有幽闭恐惧症的王伟，两人从此熟识。因为总公司高层要来中国分公司视察，因此中国区总经理和HR主管商量要重新装修公司。然而玫瑰却在此时患病需要动手术，其他人也避之不及，唯有初出茅庐的杜拉拉勇挑重担，并以其坚强不屈完成了这个重大的任务，受到了上司的赏识。而且，公司还在泰国举办了庆祝派对，期间杜拉拉与王伟擦出了爱情的火花，但是这段办公室恋情却遭遇了重重的阻力……本片是徐静蕾的第四部导演作品，根据李可同名畅销小说改编。', '徐静蕾', '徐静蕾', 5.6, 207398, 'tt1621780', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p458323215.jpg', 6.7, 24.5, 52, 13.9, 2.9, '0.176569,-0.019571,-0.643397,0.389534,-0.078702,-0.211632,0.494621,0.322496,-0.462025,-0.378531,0.162643,0.705912,-0.417530,0.385220,0.374580,-0.100171,-0.056311,-0.556760,0.027021,-0.037206,-0.139456,-0.511618,-0.273770,-0.081368,-0.187009,0.053570,0.407632,0.007399,-0.332906,0.450109,0.555365,0.125527,-0.104028,0.603662,0.138694,-0.085901,0.190274,0.181855,-0.427403,0.073277,0.251496,-0.305302,0.014691,0.002207,0.426876,0.535899,0.302449,-0.082440,-0.208349,0.016576,0.601188,-0.239613,0.169402,-0.143811,0.536066,0.092361,0.347775,0.248748,-0.252949,0.220675,-0.034899,-0.295134,-0.575626,0.204074,0.224090,-0.054681,-0.648076,0.606860,-0.068032,-0.044237,0.003582,-0.319139,0.292125,0.518533,0.363689,0.236715,-0.063370,0.123689,-0.387601,0.293896,0.572860,0.293794,-0.166586,0.407335,-0.236385,-0.534449,-0.339919,-0.092801,-0.280993,0.096554,0.220375,-0.034739,0.039531,-0.075660,-0.598649,-0.162768,-0.126360,-0.058648,-0.023927,-0.268150,0.194674,-0.799777,-0.110710,-0.489500,-0.268480,-0.006509,0.169820,-0.222914,0.402622,-0.951888,-0.041574,0.402251,0.264835,-0.702556,0.698478,0.260627,0.160812,-0.174191,-0.001540,0.085370,0.057606,0.328579,0.176284,0.440688,0.017378,-0.345477,-0.135643,0.022664', '27060077', '3139191', '1301022', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3821067', '一代宗师', '剧情', '广东佛山人叶问（梁朝伟 饰），年少时家境优渥，师从咏春拳第二代传人陈华顺学习拳法，师傅“一条腰带一口气”的告诫，支持他走过兵荒马乱、朝代更迭的混乱年代。妻子张永成（宋慧乔 饰）泼辣干练，二人夫唱妇随，琴瑟合璧。1936年，佛山武术界乱云激荡。八卦拳宗师宫羽田（王庆祥 饰）年事已高，承诺隐退。其所担任的中华武士会会长职位，自然引起武林高手的关注与觊觎。包括宫羽田的独生女宫二（章子怡 饰）在内，白猿马三（张晋 饰）、关东之鬼丁连山（赵本山 饰）、咏春叶问等高手无不将目光聚焦在正气凛然的宫羽田身上。拳有南北，国有南北乎？最有德行之人才堪会长重任，然这浮世虚名却引得无数迷乱之人狂醉奔忙，浪掷残生。生逢乱世，儿女情长埋藏心底，被冷若寒冰的车轮碾作碎泥……©豆瓣', '梁朝伟', '王家卫', 8.1, 570583, 'tt1462900', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2217557172.jpg', 0.8, 2.5, 18.9, 45, 32.7, '-0.106497,-0.083588,-0.213942,0.466067,0.360606,-0.138940,-0.001505,0.342913,-0.505074,-0.445088,0.431083,0.520021,-0.035171,-0.170345,0.128329,-0.201951,0.149277,-0.692422,-0.246313,-0.146833,0.279229,-0.190716,-0.055635,0.150096,-0.484909,-0.085267,0.391909,0.293633,-0.141123,0.348661,0.235611,0.223075,-0.260868,0.038050,-0.215303,-0.156466,-0.002121,0.024609,-0.242370,-0.236338,-0.512055,-0.270042,-0.067615,-0.031964,-0.058258,0.037046,0.299534,0.041825,0.184164,-0.270610,0.145584,0.133596,-0.156746,0.044444,0.336230,0.100657,0.316981,0.393166,0.005920,0.074604,0.014707,-0.086665,-0.173789,-0.023430,0.462044,0.127437,-0.238987,0.313209,-0.088033,-0.333841,-0.309036,-0.125196,0.283892,-0.069609,0.303342,0.192095,0.108080,0.094047,-0.126051,0.497392,0.185860,-0.106597,-0.174107,-0.203188,0.099109,-0.220918,0.057144,-0.529201,-0.302772,-0.262785,0.223048,-0.070036,0.364935,0.432652,-0.242184,0.068178,-0.009256,0.011072,0.051856,-0.148361,-0.163937,-0.136302,-0.230656,-0.407337,-0.197579,-0.081652,0.475574,-0.052050,0.907870,-0.570885,0.055407,-0.194411,-0.005432,-0.212907,0.458200,-0.167742,-0.069804,-0.111080,-0.248022,0.452389,0.091375,0.274983,-0.367572,0.201518,-0.277317,-0.202535,-0.099564,-0.110734', '27602116', '25922902', '1908036', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3822631', '卧底肥妈3', '喜剧', 'FBI探员马刚（马丁·劳伦斯 Martin Lawrence 饰）最近很高兴地得知自己的继子特伦特（布兰登·T·杰克逊 Brandon T. Jackson 饰）刚刚被杜克大学录取。然而特伦特却对升学毫无兴趣，只想签一份唱片合同，未成年的他唯有求助于马刚。马刚当然不同意，况且他正忙着一个重要案件，为了追踪一名俄黑帮成员，马刚的一名线人在任务中牺牲，储存有重要信息的内存驱动器也下落不明，唯一的线索是驱动器的一个副本被藏在乔治亚州女子艺术学校。而另一边，不愿放弃的特伦特决定在马刚执行任务途中继续争取他签下合同。然而一次突发事件让他们的身份暴露，马刚只好又使出了他的拿手好戏，再次伪装成雪莉的祖母，还把特伦特伪装成了自己的大侄女。至此，一场笑料百出又紧张刺激的卧底好戏上演了……本片为美国犯罪喜剧电影《卧底肥妈》续集。©豆瓣', '马丁·劳伦斯', '约翰·怀特塞尔', 6.5, 6314, 'tt1464174', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2676014755.jpg', 1.7, 10.8, 55, 24.7, 7.7, '0.304319,-0.007159,-0.623063,0.726618,-0.250890,-0.268802,0.377847,0.058026,-0.370015,-0.171175,0.346172,0.759785,-0.019331,0.056220,0.117480,0.025558,-0.264664,-0.566395,0.061187,-0.167270,-0.171175,-0.554114,-0.204034,-0.325993,-0.131809,-0.096677,0.687491,0.050783,-0.201765,0.157468,0.554702,0.296491,-0.081650,0.419486,0.097902,-0.100121,0.272775,-0.193661,-0.103238,0.258469,0.271543,-0.271438,-0.207017,0.283594,0.253240,0.518360,0.553920,0.019884,-0.237863,0.033711,0.412581,-0.456320,-0.089331,0.046648,0.214728,-0.065127,-0.041074,0.199686,-0.258148,-0.085123,0.015901,-0.068586,-0.871235,-0.049414,0.054016,0.249077,-0.384799,0.413831,-0.474040,0.129420,0.102145,-0.331257,-0.005362,0.385423,0.310437,0.074195,-0.144150,0.025632,-0.511373,0.238695,0.358310,-0.161316,-0.012287,0.237044,-0.075807,-0.401073,0.060019,-0.263269,-0.379559,0.105896,0.421385,0.009901,-0.141743,-0.049535,-0.396821,-0.176400,-0.353366,-0.299240,-0.175743,-0.513561,-0.001319,-0.520032,-0.012564,0.095023,-0.282319,-0.013394,0.190421,-0.325149,0.662465,-0.522079,0.096872,0.756689,0.104683,-0.587514,0.353438,0.287118,0.372788,-0.346007,-0.120924,-0.018011,0.218469,0.202402,0.235681,0.188243,0.118772,-0.525106,-0.263488,0.214266', '3785918', '30163500', '26678784', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3822687', '神秘海域', '动作', '足智多谋的内森·德雷克（汤姆·赫兰德 饰）和经验丰富的寻宝者维克多·苏利文（马克·沃尔伯格 饰）组成搭档，追寻费迪南·麦哲伦500年前遗失的宝藏。一开始，这似乎只是个简单的寻宝工作，但很快演变成了一场惊险刺激、横跨全球的竞赛。他们必须赶在冷酷无情的蒙卡达（安东尼奥·班德拉斯 饰）之前寻得宝藏。蒙卡达坚信他和他的家族才是宝藏的正当继承人。若内森和苏利文能破译线索，解开这世界上最古老的谜团，他们便能找到价值50亿美元的宝藏，甚至还可能找到内森失踪已久的哥哥……但首先，他们必须学会通力合作。', '汤姆·赫兰德', '鲁本·弗雷斯彻', 6.3, 97347, 'tt1464335', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2869751944.jpg', 1.9, 15.4, 54.2, 23.8, 4.8, '0.200583,0.020446,-0.747504,0.558573,0.008203,-0.397299,0.449076,-0.367890,-0.406761,-0.234593,-0.086689,0.786109,0.096635,0.081730,0.255882,0.296331,-0.692723,-0.494690,0.181991,-0.571769,-0.147633,-0.756055,-0.708710,-0.354872,0.118178,-0.357660,0.653099,0.258690,0.082462,0.278133,0.281832,0.255316,0.116151,0.260326,-0.311089,-0.084629,0.380767,-0.011830,-0.380694,0.068459,0.021646,0.110184,-0.140519,0.279282,0.132151,0.408514,0.102626,-0.491088,0.127657,0.180741,0.054844,-0.373111,-0.101354,-0.074751,0.343034,-0.121365,0.179130,0.454701,-0.097193,-0.078284,0.125662,-0.142917,-0.899837,-0.203475,0.251524,0.281812,-0.280034,0.150525,-0.116359,0.004797,-0.113094,-0.428977,0.207372,0.624154,0.346924,-0.094156,-0.092757,-0.199309,-0.763035,0.072971,0.413637,-0.268287,-0.161498,0.283016,0.097169,-0.730419,-0.040855,-0.349598,-0.140617,0.107935,0.642963,0.014348,0.114533,0.063561,-0.544019,0.004583,-0.534839,-0.213723,-0.045219,-0.459467,-0.018973,-0.546072,-0.259471,-0.215971,-0.294216,0.180150,0.041519,-0.392939,0.677256,-0.497061,0.080731,0.524085,0.124533,-0.331428,0.571189,-0.093226,0.103756,-0.434437,-0.085352,0.315720,-0.084252,0.318609,-0.161347,0.197707,0.419204,-0.303329,-0.273609,0.623202', '1793491', '1308585', '1307442', '1297689');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3822842', '白夜行', '爱情', '太阳到达最高点的时候，它的影子便消失了。刑警韩东秀（韩石圭 饰）为了证实自己对一起已有定论的杀人案的猜想，致使自己的儿子意外身亡，从此变得意志消沉起来。14年后，一桩杀人案似乎和当年这起案件有着某种联系，当韩东秀再一次开始关注起当年一名被害人的儿子有汉（高修 饰）时，意外认识正在帮助财团老板调查未婚妻柳美皓（孙艺珍 饰）的私家侦探，从私家侦探那里得知这名叫柳皓美的女人正是当年被认为是畏罪自杀的凶手的女儿李佳。当年这两个韩东秀曾经有怀疑过的小孩子如今长大成人，而且又同样因为凶杀案出现在他的周围。在韩东秀的追查过程中，他发现了当年凶杀案以及近期凶杀案的真相，而真相背后，却是一对永远不能在光天化日之下见面的苦恋情侣。影片改编自日本著名推理小说家东野圭吾的同名小说《白夜行》。小说曾在日本被拍成电视剧，并大获成功。©豆瓣', '孙艺珍', '朴信宇', 7, 58643, 'tt1533114', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p465542953.jpg', 1.4, 7.4, 43.8, 36, 11.5, '0.308341,-0.062694,-0.745903,0.531746,0.028219,-0.179978,0.637422,-0.015768,-0.858126,-0.559920,0.235592,0.637648,-0.352365,0.249271,0.112482,-0.124801,-0.271069,-0.738827,-0.108493,-0.364270,-0.215452,-0.495845,-0.307230,-0.173280,-0.024205,-0.229849,0.537020,0.276539,-0.219249,0.462049,0.465832,0.273101,-0.276184,0.193881,-0.053481,0.055495,0.070139,0.274049,-0.404483,0.350776,0.095116,-0.359008,0.142882,0.130690,-0.171415,0.302623,0.566167,-0.195788,-0.527042,-0.100598,0.582266,-0.104601,-0.135424,0.217467,0.625888,0.143600,0.348459,0.288336,-0.255735,-0.251036,-0.040082,0.133381,-0.749175,0.043972,0.226196,0.290213,-0.402187,0.026909,-0.143279,0.090549,0.094544,-0.306800,0.356727,0.441510,0.471900,0.237088,-0.171213,0.066651,-0.459276,0.281279,0.719799,-0.012998,-0.018211,0.278680,0.079473,-0.336000,-0.225820,0.023620,-0.185040,0.525210,0.331724,-0.049095,-0.331778,0.442961,-0.227513,-0.201832,-0.131458,0.144085,0.065347,-0.171676,-0.195665,-0.400342,-0.341848,-0.193270,-0.234923,0.031103,-0.054454,-0.539910,0.443498,-0.773391,0.416954,0.555015,0.088064,-0.516817,0.468181,0.151851,-0.083458,-0.319033,-0.167389,0.214176,0.126463,0.118271,-0.141798,0.015159,0.012263,-0.351824,-0.392868,0.079279', '1301022', '35073886', '3263169', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3824274', '刺猬的优雅', '剧情', '国会议员一家四口住在巴黎左岸的高级公寓里。议员的小女儿芭洛玛（Garance Le Guillermic 饰）古灵精怪，喜欢透过摄影机洞察世界，是名不满12岁的天才小哲学家。不愿成为鱼缸中命运已被注定的金鱼，芭洛玛策划着一场生日当天的自杀。公寓女门房荷妮（乔丝安·巴拉思科 Josiane Balasko 饰）是个肥胖丑陋的54岁寡妇。她小心翼翼的维持着门房粗俗的形象，为自己在密室内筑起一个丰富的精神世界。但是芭洛玛隐约发现了这个秘密，新搬来的日本绅士小津格郎（伊川东吾 饰）亦觉察到了荷妮不为人知的一面。在小津彬彬有礼的引领下，不仅荷妮逐渐卸下卑微的伪装，芭洛玛亦开始重新审视生活与死亡。本片改编自法国女作家妙莉叶·芭贝里的同名小说。©豆瓣', '若西安·巴拉斯科', '莫娜·阿查切', 8.8, 135675, 'tt1442519', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p489369851.jpg', 0.2, 0.8, 8.9, 38.3, 51.8, '0.308403,0.285606,-0.448619,0.448129,-0.377009,-0.016820,0.712576,0.168907,-0.297105,-0.290409,0.350337,0.799138,-0.150596,0.486205,0.240811,0.072516,-0.172858,-0.455628,-0.311686,-0.201685,-0.120655,-0.361686,-0.542113,-0.081796,-0.032016,-0.421672,0.338873,0.004118,0.063986,0.334758,0.369295,0.242457,-0.273482,0.161345,-0.205580,-0.077858,0.269189,-0.050424,-0.026533,0.087378,-0.291591,-0.174081,-0.026858,0.197478,-0.146049,0.340982,0.774076,-0.401649,-0.275385,-0.038251,0.617263,0.094959,-0.242715,0.250066,0.370445,0.032803,0.068435,0.002090,-0.256786,0.184222,0.156615,-0.088698,-0.575634,-0.052602,0.226630,0.051984,-0.523091,0.404077,0.012778,-0.197672,0.043352,-0.342464,0.090819,0.045853,0.276307,0.455342,-0.037695,0.257835,-0.410770,0.190596,0.117865,0.096383,-0.271932,0.377290,-0.286578,-0.227064,0.160542,-0.330642,-0.691959,-0.201598,0.182280,-0.077672,-0.102055,0.073410,-0.597394,-0.045012,-0.192322,-0.038310,0.197083,-0.283052,-0.268760,-0.509163,-0.233390,-0.316402,-0.000641,0.038531,0.033240,-0.193343,0.768931,-0.626917,0.328317,0.461260,0.095526,-0.077839,0.782861,-0.122233,0.121683,-0.145507,-0.089735,0.317527,-0.035324,0.220238,-0.075666,0.594292,-0.374517,-0.129035,-0.403299,0.570456', '1292925', '4233625', '26677495', '21350559');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3824339', '关键第四号', '动作', '外星人丹尼尔（亚历克斯•帕蒂弗 Alex Pettyfer 饰）以及与自己有着相同命运的孩子们为了躲避侵略他们星球的茅迦人的追杀而逃到地球，几年来，丹尼尔不断的感知到自己同伴遇害，为了活命，他在自己保护者亨利的陪伴下一直过着流亡的生活。在天堂镇，丹尼尔邂逅了美丽的少女萨拉（迪安娜•阿格隆 Dianna Agron 饰）并且认识了胆小懦弱却又痴迷于外星人的萨姆（卡兰•麦克奥利菲 Callan McAuliffe 饰）。恐怖的茅迦人最终找到了丹尼尔的行踪，这一次，丹尼尔没有选择逃避，他决定要用自己逐渐强大的超能力战胜敌人。然而要想战胜强大的茅迦人并不容易……本片改编自系列漫画的第一部，由电影《变形金钢》系列的导演迈克尔•贝（Michael Bay）监制。©豆瓣', '亚历克斯·帕蒂弗', 'D·J·卡卢索', 6.1, 65350, 'tt1464540', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1337790443.jpg', 3.2, 16.6, 54.7, 20.8, 4.7, '-0.011823,0.017365,-0.786433,0.831845,-0.050989,-0.201671,0.786467,0.075853,-0.212661,-0.258356,0.193956,0.905297,-0.013617,0.015394,0.041125,0.165840,-0.303127,-0.532574,0.043706,-0.054323,-0.348828,-0.455516,-0.547737,-0.514763,-0.086656,-0.387671,0.682256,0.043307,-0.269015,0.204503,0.306308,0.310983,0.050136,0.393787,-0.130726,0.057902,-0.050650,-0.291805,-0.292325,0.321263,0.226757,0.008420,-0.293133,0.450479,0.045367,0.260433,0.704486,-0.543267,0.113317,0.030001,0.291110,-0.303369,0.007255,-0.103149,0.144218,-0.405922,-0.052745,0.079751,0.043654,-0.051050,0.171554,0.034556,-0.980566,0.050572,0.062977,0.117463,-0.557660,0.307196,-0.214458,0.146440,0.193717,-0.366419,-0.060658,0.365260,0.198216,0.180028,-0.141727,-0.099009,-0.396394,0.358039,0.776647,0.170504,-0.481816,0.295873,-0.467973,-0.302975,-0.369332,-0.481558,-0.729466,0.029977,0.470456,0.106630,-0.250918,0.354602,-0.559196,-0.156973,-0.382468,-0.073658,-0.085892,-0.488065,0.016279,-0.642611,-0.224392,-0.348361,-0.210228,-0.128961,-0.179298,-0.323091,0.782789,-0.859598,0.249816,0.960805,0.343994,-0.401322,0.566484,0.045030,-0.079139,-0.206541,-0.278894,0.648452,0.175653,0.270668,0.224751,0.270364,0.231963,0.091642,-0.353355,0.613786', '3769423', '25928048', '34890458', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3824500', '魔侠传之唐吉可德', '剧情', '话说某朝某代，蜀中有一户唐门，祖上本是武功高强的盖世英雄，传至唐方海一辈，则一心教授四个儿子饱读圣贤之书。然而唐家第三子唐吉（郭涛 饰）字可德，无心圣贤，专好武侠神怪小说，以至于走火入魔，不辨虚实。这一日，唐吉可德佩戴祖宗的甲胄和霸王枪，骑着家中的瘦马爪黄飞电离家出走，他访名山，会高友，指望打通任督二脉成为爵士奇侠。当他路过桑家村，恰巧撞见豪强富贵强抢民女翠花（林嘉欣 饰）。唐吉可德挺身而出，凑巧打败豪强的狗腿子令狐有味（刘桦 饰），但是翠花早已被人掳向长安。唐收当地羊倌桑丘（王刚 饰）为仆，为了伟大的正义事业和美丽的香香公主一路向长安进发……©豆瓣', '郭涛', '阿甘', 4.4, 7165, 'tt2027223', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p544535503.jpg', 31.7, 32, 24.9, 7.7, 3.8, '0.265566,-0.188468,-0.204190,0.398222,0.161453,-0.204766,0.157440,0.194762,-0.479268,-0.525694,0.215343,0.573461,0.085672,-0.085085,0.106983,0.135751,0.291845,-0.233531,0.134148,0.135192,0.229543,-0.111316,-0.051110,0.021026,-0.252297,-0.151925,0.214121,-0.008376,-0.234397,0.603221,0.127753,0.209139,-0.108669,-0.187582,-0.348955,0.439250,-0.198714,-0.024403,-0.197781,-0.052826,-0.340459,-0.124377,-0.186049,-0.262055,-0.133506,0.228180,0.325384,-0.093032,0.247466,-0.156364,0.312045,-0.063264,-0.084992,0.037031,0.336494,0.067313,0.357685,0.219452,0.170419,-0.033951,0.169313,-0.017323,-0.368638,-0.000533,0.358214,0.001945,-0.334573,0.359295,-0.166253,-0.203020,-0.038111,-0.231794,0.195881,-0.056879,0.012140,0.123921,0.046667,-0.106626,-0.509551,0.388278,0.350796,-0.105528,0.141658,0.015522,0.346482,-0.077237,0.534415,-0.378389,-0.370443,0.033484,0.257184,-0.111558,-0.001381,0.031712,-0.205807,0.083757,-0.194865,0.441511,0.173579,-0.003322,-0.235624,-0.152504,-0.083532,-0.122882,0.011422,-0.055649,0.541254,-0.021789,0.609480,-0.380822,0.024331,0.077854,0.050170,-0.485803,0.643823,0.019808,-0.020696,0.067965,-0.386908,0.070127,0.330985,0.371286,-0.079708,0.192937,-0.266990,-0.223607,0.006100,0.198191', '3236520', '1301136', '1304758', '4307000');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3824672', '听说', '剧情', '阳光男孩黄天阔（彭于晏 饰）的父母经营着一家便当店，某天，他在为听障游泳队送便当时邂逅了清纯美丽的姐妹花——小朋（陈妍希 饰）和秧秧（陈意涵 饰）。姐妹俩的父亲是一名传教士，常年在非洲工作。为了保障姐姐顺利参加听障奥运会，秧秧担负起赚取家用的重任。她每日来去匆匆，辛苦打着几份工。本身即掌握手语的天阔自然而然融入了姐妹俩的生活当中，为了接近心仪的秧秧，他时常在体育馆门口做生意，还费尽心思为秧秧制作爱心便当。相识时间虽短，却让两个年轻人的心越走越近。然而某次约会中，一个小小的误会阻断了他们的交往，与此同时，小朋也遭遇了一场灾难……©豆瓣', '彭于晏', '郑芬芬', 8.1, 378389, 'tt1562328', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2250788664.jpg', 0.2, 1.4, 19.8, 48.8, 29.8, '-0.007631,0.080314,-0.401888,0.451485,-0.103874,-0.375018,0.361432,0.188660,-0.210266,-0.208875,0.084221,0.608561,0.012143,0.236456,0.267651,-0.085377,-0.039646,-0.464914,-0.174204,-0.041798,-0.229478,-0.219881,-0.254527,-0.206682,-0.173063,-0.234609,0.253178,0.083532,-0.009944,0.708244,0.354923,-0.113929,-0.268620,0.339246,-0.202935,-0.146241,0.079562,0.252684,-0.288874,0.147983,-0.059094,-0.210280,-0.115138,-0.037672,0.189472,0.228760,0.695064,0.050975,-0.097879,-0.188494,0.331038,-0.073309,0.033447,-0.043195,0.188246,0.152544,0.286872,-0.021193,-0.507339,0.214712,0.123608,-0.203501,-0.626281,0.118750,0.134430,-0.098885,-0.579442,0.525686,0.127782,-0.237672,0.186430,-0.227080,0.203245,0.540663,0.106670,0.412820,-0.196667,0.189181,-0.387971,0.515241,0.761230,-0.098024,0.111579,0.403177,-0.308418,-0.240970,0.168694,-0.064492,-0.464982,-0.026671,0.082201,-0.261939,0.118793,-0.026200,-0.555573,0.163517,-0.133532,-0.020373,0.228066,-0.424878,0.011384,-0.570609,0.079095,-0.395656,-0.319912,0.052622,0.098088,-0.307171,0.831907,-0.663371,0.202974,0.586362,0.288237,-0.469983,0.807657,0.175893,0.318711,-0.207205,-0.148393,0.014678,-0.114626,0.272108,0.126020,0.423689,-0.022827,-0.049570,-0.293991,0.292032', '3811356', '10876425', '3445516', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3826526', '矮仔多情', '喜剧', '蓝子杰（王祖蓝 饰）虽矮却多金，生活奢靡。秘书（官恩娜 饰）失误，抛掉了公司的股票，他却因祸得福，幸运地躲过了金融危机的侵袭，身价缩水不多。他在游船上偷腥，为补偿未婚妻珠珠（周秀娜 饰），他订了昂贵的钻石项链，却意外遗失，自己也搞得十分狼狈。珠珠见到阿杰的落魄相，误以为他已破产，索性分手。低潮期的阿杰十分痛苦，碰巧遇见了有爱心的Angel（Angelababy/杨颖 饰），每次失意均受到她温柔抚慰与谆谆劝导。此后他又相继结识了两姐妹：芭蕾舞导师Christy（黄婉伶 饰）与舞女Christine（黄婉伶 饰），盲人按摩师嘉嘉（贾晓晨 饰），江湖大佬刀疤珊（徐子珊 饰），一系列恋情让他爱潮激荡……本片导演阮世生邀请了众多香港美女出演，并有天王嫂熊黛林的友情客串。主题曲由王祖蓝亲自操刀，一曲《跌落凡间的天使》唱出了真情的千回百转。©豆瓣', '王祖蓝', '阮世生', 6.3, 17719, 'tt1463188', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2266795164.jpg', 4.6, 14.2, 52, 22, 7.3, '0.075695,0.051315,-0.441641,0.316591,0.115345,-0.297774,0.565056,0.381245,-0.290250,0.007421,0.411271,0.637291,-0.426273,0.130874,0.154076,0.016669,-0.042570,-0.401768,0.152033,0.128929,0.045382,-0.106481,-0.313276,0.123703,-0.152739,-0.194419,0.357897,-0.090082,-0.149245,0.704484,0.657635,0.061580,-0.081433,0.499369,-0.048806,0.094499,0.012519,0.297311,-0.157389,-0.064958,-0.096073,-0.471917,0.049383,0.091350,-0.086345,0.449578,0.422993,0.067304,-0.010772,0.067772,0.480898,-0.130851,0.132131,-0.152524,0.139124,0.003506,0.302393,0.000130,-0.315881,0.040270,0.127031,0.086279,-0.523735,0.117235,0.290047,0.141618,-0.445196,0.582678,-0.160462,0.198969,-0.097626,-0.050185,-0.049016,0.017896,0.120942,0.113367,-0.029003,0.117853,-0.225050,0.615900,0.475089,0.208516,-0.154324,0.425392,-0.272194,-0.546664,0.005629,-0.209305,-0.328173,0.135755,0.324031,-0.132842,0.104781,0.096565,-0.432083,-0.191214,-0.269587,0.173721,-0.176945,-0.169386,0.061847,-0.447023,-0.096362,-0.388234,-0.364579,-0.169228,0.187559,-0.113518,0.626514,-0.647927,-0.035110,0.378723,0.256539,-0.403806,0.522319,0.029032,-0.184481,-0.062401,-0.193220,0.231548,-0.251175,0.000051,0.189689,0.198993,-0.105197,-0.199281,-0.203878,0.162237', '35144311', '3811356', '35030151', '1418179');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3829499', '芳心终结者', '喜剧', '男人总是花心的，所以不知情的女人就遭殃了。为了改变这个状况，亚历克斯（罗曼•达瑞斯 Romain Duris 饰）挺身而出，跟姐姐、姐夫组成了拯救三人组，专门对付那些负心人。他们的原则有两条：不拆散真心相爱的情侣。不对客户动真情。他们采取的手段是，由亚历克斯向女人主动示爱，而姐姐姐夫后场支援。他会让这个女人爱上自己，并认清花心男友的本质，再与之分手。得手多次之后，他们已经做出了品牌。但是，由于债台高筑，他不得不接受了一单生意：富豪对女儿朱丽亚特（凡妮莎•帕拉迪丝 Vanessa Paradis 饰）的婚事不满意，看不上他的未来女婿，所以他要求亚历克斯在婚前10天去拆散他们。从蛛丝马迹，层层推敲，他们发现两人是真心相爱。但是箭在弦上，他只能硬着头皮开始了工作。他假扮朱丽亚特的贴身保镖，接近她，并通过姐姐姐夫搜集的情报，不断投其所好。然而，日久生情，他发现一切都变得不同……', '罗曼·杜里斯', '帕斯卡尔·舒梅', 6.8, 10524, 'tt1465487', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p555335415.jpg', 1, 6.9, 49.7, 34.2, 8.2, '0.332261,-0.191740,-0.530418,0.472799,-0.414466,-0.164739,0.405112,-0.055900,-0.517652,-0.023215,0.256840,0.621010,0.006148,0.010447,0.063973,0.317919,-0.296172,-0.695778,0.366882,-0.085195,-0.101532,-0.618633,-0.039365,-0.453329,-0.189168,-0.048466,0.623931,-0.145046,-0.097068,0.222802,0.510086,0.029591,0.177094,0.618242,0.103002,0.048629,-0.056942,-0.002870,-0.345469,0.166141,0.094584,-0.058133,-0.123515,0.329403,-0.071719,0.601962,0.330707,-0.266498,-0.226369,-0.073907,0.305684,-0.379223,0.156713,0.303380,0.018387,-0.283940,0.252208,0.266928,-0.148098,-0.223994,-0.099488,0.056747,-0.419557,0.134476,0.151694,0.033345,-0.687810,0.140245,-0.383596,-0.055892,-0.060231,-0.457405,0.070784,0.497885,0.329637,0.123886,-0.380596,-0.140020,-0.585023,-0.097116,0.772700,0.269696,-0.135429,0.449668,-0.354551,-0.333406,-0.148976,-0.317283,-0.499893,0.079537,0.039068,-0.035563,-0.060553,0.227763,-0.598961,-0.128005,-0.117912,0.036295,0.108525,-0.783879,0.240091,-0.244194,-0.294888,-0.373727,-0.578909,0.062706,-0.022206,-0.423095,0.645643,-0.955266,-0.134151,0.659956,0.730045,-0.920878,0.763579,0.224362,-0.075183,-0.483222,-0.121253,0.135058,0.014161,-0.023261,0.154866,0.257816,0.481462,-0.128189,-0.204514,0.346627', '1949320', '1421278', '1308805', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3829512', '灭门', '动作', '香港社团“同联顺”众成员赴大陆购买制作伪钞所用电版，归程时其当家骆祥安（张兆辉 饰）为公安捉获，并最终被执行死刑，一时间骆氏遗产的分配成社团中骨干阿富（任达华 饰）、阿雄等人瞩目的焦点。岂料在黄律师（林雪 饰）主持下，遗产尽归骆祥安妻弟丽萍（廖碧儿 饰）、骆祥福所有。阿富等人大感不平，各怀鬼胎，而骆家庶出的儿子阿牛（安志杰 饰）却对这一切看似漠不关心，每日只与哑妹（蒋璐霞 饰）苦练搏击。不久，黄律师意外身亡，接着骆祥富也死于汽车炸弹，为避免死于遗产争夺，骆丽萍将所有财产在遗嘱中留给慈善组织后，又找到阿牛，以亲情说服他为自己铲除社团各位干部，于是阿牛与哑妹两人迅速向社团发难，连场血战中，遗产争夺战的幕后主使人渐渐浮出水面……©豆瓣', '任达华', '罗守耀', 4.4, 5634, 'tt1465499', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1702837352.jpg', 26.5, 37.9, 27.3, 5.3, 2.9, '-0.290084,0.118147,-0.441719,0.262776,0.085187,-0.287595,0.289210,0.227953,-0.447461,-0.219730,0.074316,0.620840,-0.018105,0.180368,0.216762,-0.354712,-0.257781,-0.825079,-0.307519,-0.097874,-0.105578,-0.398328,-0.025303,-0.247351,-0.250991,-0.047071,0.593712,0.268674,-0.064225,0.330456,0.559962,0.249406,-0.350657,0.245665,0.127424,-0.188499,-0.051462,0.019617,-0.456777,-0.121849,-0.277401,-0.331338,-0.175136,-0.064685,0.199552,0.252141,0.644821,-0.159292,0.044393,-0.439029,0.228543,-0.322604,-0.016289,-0.074877,0.362008,0.171937,0.145580,0.487001,-0.268859,0.039786,0.235108,-0.067148,-0.615476,-0.145496,0.233268,0.218953,-0.463604,0.353212,-0.132964,0.087625,-0.041901,-0.108690,0.317523,0.323303,0.238090,0.168853,-0.242621,0.055441,-0.231965,0.393328,0.450230,-0.143374,0.120085,-0.257782,0.101473,-0.377057,0.182071,-0.183911,0.007948,-0.054235,0.298540,0.220685,0.387976,0.238591,-0.450098,-0.213253,-0.088338,-0.282635,0.048348,-0.453014,0.091973,-0.704266,-0.094071,0.033885,-0.152791,0.056162,0.303766,-0.156950,0.594373,-0.591559,0.058240,0.044554,0.184394,-0.734545,0.252931,0.028961,0.487757,-0.304590,-0.106996,-0.213874,0.316417,0.298341,0.052000,-0.023761,-0.236758,-0.266776,-0.060341,-0.083016', '4301278', '25723905', '26991880', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3834175', '很想和你在一起', '爱情', '欧阳冠楠（诗雅 饰）与施徒捷（洪卓立 饰）是一对校园中常见的欢喜冤家，俩人同样热爱摄影，性格也同样争强好胜，彼此吸引却总是以斗嘴作为相处方式。虽然吵闹不断，但两个青葱少年的爱情仍在潜滋暗长，在后山彩虹下留下约定，却因毕业时的一场误会，错失掉缘分。四年后，二人在周年校庆重逢，顺理成章成为情侣，甜蜜不断之时，阿捷一次失约埋下祸根。再见面已是人鬼殊途，阿楠和阿捷，虽然阴阳两隔，却仍能看到彼此，但在旁人眼中，阿楠已经成了喃喃自语的神经病。和老爸（许绍雄 饰）争吵不断，加上师兄（陈家乐 饰）一直在身边默默关怀付出，阿楠终要面对阿捷已经不在人世的事实……©豆瓣', '洪卓立', '江玉仪', 7.4, 19360, 'tt1517475', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2374980197.jpg', 1.1, 5.4, 34.2, 40.9, 18.4, '0.167252,0.086968,-0.740021,0.348927,0.133439,-0.362176,0.922473,-0.060467,-0.489993,-0.150266,0.125369,0.540924,-0.417867,0.352325,-0.010212,-0.309796,-0.151497,-0.731256,0.082384,-0.217370,0.031907,-0.371141,-0.195404,0.179485,-0.340685,-0.093630,0.565976,0.151052,0.063990,0.681026,0.324590,0.051290,-0.623272,0.490874,-0.125496,-0.180735,0.031151,0.472428,-0.579716,-0.236725,-0.012565,-0.189926,-0.216916,-0.130973,-0.111909,0.287778,0.652036,-0.296473,-0.230889,-0.016132,0.237770,-0.109242,-0.146754,0.188078,0.194695,-0.191647,0.703674,0.230056,-0.065572,-0.070254,-0.099890,0.076193,-0.335169,0.083643,0.246238,0.287444,-0.388146,0.785202,0.244443,-0.127997,0.124028,-0.333677,0.124231,0.235778,0.579877,0.433442,-0.420606,-0.173072,-0.395982,-0.126392,0.855039,0.295957,-0.179571,0.544282,-0.114492,-0.186665,-0.062679,0.059482,-0.556267,0.079353,0.111771,0.104571,-0.107459,0.421263,-0.430315,0.078759,0.103872,0.296791,0.160148,-0.760362,0.209130,-0.512513,-0.157660,-0.825598,-0.612650,0.382539,0.183340,-0.394422,0.496118,-0.832821,0.213381,0.155810,0.102953,-0.332887,0.637675,0.479580,0.067152,-0.312011,-0.053277,0.279611,-0.232146,-0.093598,0.256796,0.306377,-0.058126,0.303843,-0.383382,0.368222', '1308755', '2071525', '1307561', '1304989');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3836070', '孤独的幸存者', '剧情', '阿富汗国会大选召开在即，为了保证大选的顺利进行，美国海军陆战队联合特种部队对辖区进行一系列彻底的清查。在某个动荡的地区，前塔利班头目艾哈迈德·沙赫趁机做大，成为了一个美国急欲除掉的眼中钉。根据线报，沙赫的武装部队隐藏在某个山区，海豹侦察小队中尉麦克·墨菲（泰勒·克奇 Taylor Kitsch 饰）带领丹尼·迪茨（埃米尔·赫斯基 Emile Hirsch 饰）、麦特·阿克塞尔森（本·福斯特 Ben Foster 饰）以及马库斯·拉特尔（马克·沃尔伯格 Mark Wahlberg 饰）三名队员前去搜寻情报。但是他们的行踪很快被当地的牧羊人发现，虽然对方是普通的平民，可却为小队提出了难题。处决牧羊人，小队将面临军事法庭的审判；释放牧羊人，这四个美国军人将可能陷入前所未有的灭顶之灾中……本片根据马库斯·拉特尔（Marcus Luttrell）的同名回忆录改编。', '马克·沃尔伯格', '彼得·博格', 8.1, 60361, 'tt1091191', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2170861821.jpg', 0.5, 1.6, 18, 50.9, 29, '0.325437,0.012148,-0.583943,0.516700,0.231315,-0.042074,0.368273,0.065938,-0.358838,-0.283408,0.123089,0.743135,0.068691,-0.259189,0.403515,-0.057370,-0.724900,-0.707687,-0.250019,-0.204005,-0.213772,-0.530674,-0.305099,-0.384547,0.143319,-0.283634,0.617213,-0.024112,-0.235530,0.476473,0.328482,0.774993,0.085025,0.203793,0.045453,-0.049838,0.574831,-0.714592,-0.337862,0.231071,-0.172977,-0.101837,-0.083832,0.081849,0.260517,0.530714,0.545406,-0.440617,0.204773,-0.346068,0.011208,-0.495288,0.138610,0.072270,0.534512,0.092264,-0.256532,0.259243,-0.176490,0.213223,0.022506,-0.249280,-0.801659,0.009049,0.159715,0.313475,-0.308243,0.149494,-0.269713,0.285981,0.090647,0.094659,0.060636,0.767685,0.152031,0.075595,-0.002700,0.025015,-0.648385,-0.216928,0.436705,-0.390714,-0.311058,-0.458768,-0.073797,-0.637690,0.171450,-0.113686,0.050217,-0.085134,0.415537,-0.310257,0.276856,0.308725,-0.573173,-0.199454,-0.598175,-0.462223,-0.179494,-0.282091,-0.124870,-1.003130,0.095781,0.040534,-0.354015,0.111282,0.075684,0.188428,0.607904,-0.516199,0.053636,0.522793,0.237645,-0.384777,0.280995,0.152907,0.492459,-0.299254,-0.116777,0.409477,0.581181,0.278661,0.141167,0.277008,0.028323,-0.322268,-0.023051,0.196359', '2028645', '10463953', 