INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3836490', '东之伊甸剧场版1：伊甸之王', '动画', '2009年4月～6月に放送された人気TVアニメの完結編となる劇場版2部作の第1部。監督は「攻殻機動隊　STAND ALONE COMPLEX」の神山健治。2011年2月19日、日本を襲った60発のミサイル攻撃を誰にも知られることなく阻止した滝沢朗は、その半年後、こつ然と姿を消す。彼を見守ってきた森美咲は、滝沢が残した謎の携帯電話「ノブレス携帯」にあった情報から、滝沢がいると思われるニューヨークへ向かうが……。', '木村良平', '神山健治', 7.7, 7029, 'tt1460738', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2206691170.jpg', 0.9, 3.8, 28.8, 43.5, 22.9, '-0.360324,-0.252415,0.242552,-0.612538,0.287455,0.127347,-1.091289,0.441135,-0.016113,-0.152883,-0.013964,-0.225467,-0.977601,-0.399046,0.883689,0.235265,-0.209609,-0.143398,-0.058010,-0.838431,0.156864,-0.041146,0.344211,0.303701,-0.308548,-0.669089,0.580741,0.172508,1.369789,0.645630,-0.097435,1.150269,-0.195755,-0.334171,1.102985,0.551014,-0.483544,0.187854,0.190460,0.527517,-1.059910,-0.852291,-1.095039,-0.382259,0.252976,0.223614,1.128062,0.148877,0.289887,-0.819571,0.509055,0.020540,-0.926697,-0.011488,0.762103,-0.303336,-0.409262,0.907078,-0.547754,-0.502696,-0.122783,0.176829,0.671544,-0.027952,-0.002269,-0.110089,-0.010721,-0.069487,-0.568012,0.024635,0.209166,0.103901,-0.395219,-0.175765,-0.019784,0.224679,-0.016148,0.209297,-0.000954,-0.101596,0.449582,-0.433746,0.264802,-0.369361,0.943801,-0.378127,-0.672763,-0.486234,0.244671,-0.181569,-0.683488,0.195297,-0.221025,-0.618942,0.329759,-0.225730,-0.273078,0.048516,0.278341,0.083002,-0.045731,-0.911462,0.280386,-0.250955,-0.161088,0.725105,0.781612,0.004184,0.891230,-0.587304,0.005505,0.627335,0.789456,0.282466,0.620155,-0.134919,-0.815216,0.017348,0.198455,0.084828,-0.082032,0.074088,0.572884,0.055768,-0.513555,0.270255,0.073360,-0.565682', '11639344', '27030639', '35206186', '25758898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3837666', '海滩游侠', '喜剧', '电影版《海滩护卫队》（Baywatch）最引人注目的角色“C·J·帕克”（C.J. Parker）的演员人选今天终于尘埃落定，女模凯莉·罗尔巴赫（Kelly Rohrbach）将出演这个当年一举捧红帕梅拉·安德森（Pamela Anderson）的角色。《海滩护卫队》（Baywatch）根据同名经典美剧改编。该剧1989年开播，到2001年共播出11季。这部讲述一群加州海滩救生员故事的美剧在90年代风靡一时，捧红了该剧主演大卫·哈塞尔霍夫（David Hasselhoff）和帕梅拉·安德森（Pamela Anderson）等。剧中美女帅哥在海滩上奔跑的慢镜头常被人津津乐道和模仿，是很多宅男心中的神剧。影版《海滩护卫队》会是一部喜剧片，由《恶老板》的塞斯·高顿（Seth Gordon）导演，巨石强森（Dwayne Johnson）和扎克·埃夫隆（Zac Efron）主演。派拉蒙还计划把大卫·哈塞尔霍夫、帕梅拉·安德森等该剧演员请回来客串。', '道恩·强森', '赛斯·戈登', 5.8, 17408, 'tt1469304', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2461006293.jpg', 4.4, 25.7, 52.5, 12.6, 4.9, '0.166401,-0.344176,-0.415549,0.579216,0.322335,-0.198420,0.669983,0.069707,-0.300254,-0.092345,0.120249,0.963499,-0.869293,0.156203,0.598814,0.016787,-0.634935,-0.578154,-0.226032,-0.104508,0.024302,-0.190051,-0.468230,-0.197159,-0.216144,-0.309697,0.724960,-0.270241,0.030549,0.236143,0.732354,0.162737,0.059230,-0.097258,-0.023581,0.460983,0.203578,-0.470389,-0.392670,0.290621,-0.012141,-0.183410,-0.182045,-0.268022,0.180079,0.180943,0.635657,0.151109,0.333129,0.115632,0.331183,-0.414428,0.120866,-0.170585,0.474862,-0.238375,0.281185,0.158371,0.054670,0.124092,-0.392539,-0.403408,-0.378308,0.287757,0.260061,0.406871,-0.445106,0.215549,-0.329879,0.180098,0.127692,-0.263927,0.020023,-0.349021,0.384051,0.173278,0.298732,-0.024939,-0.155119,0.741292,0.117490,0.186404,-0.040207,0.432445,0.078162,-0.420606,-0.211423,0.096919,-0.633935,0.172843,0.459817,-0.433780,0.113498,-0.013601,-0.523934,-0.163352,-0.029386,-0.392112,-0.051272,-0.250421,-0.179557,-1.111487,-0.081264,-0.208395,0.404468,-0.187059,0.178818,-0.125735,0.780529,-0.281627,-0.138545,0.317879,-0.071353,-0.029768,0.651619,0.038124,0.092597,-0.038845,0.182504,0.111463,0.034177,-0.013992,0.001323,0.458919,-0.124147,-0.499508,-0.373703,0.406190', '34961898', '1322847', '30397916', '26611806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3861846', '火影忍者疾风传剧场版：火之意志的继承者', '动画', '为追踪4名血继限界继承者的下落，小樱（中村千絵 配音）、漩涡鸣人（竹内顺子 配音）、卡卡西（井上和彦 配音）和佐井奉命前往。但在岩隐和草隐交界的须弥山失去目标，鸣人和佐井也身受重伤。在此之后，自称卑留呼（保志総一朗 配音）的前木叶村忍者单方面宣战，他之前因修习鬼芽罗术而被逐出木叶，而今他企图集齐5个血继限界成为不死的完美忍者，进而发起第四次忍界大战。在此危急时刻，卡卡西感受到来自卑留呼的召唤。失去最重要的导师，鸣人、木叶村乃至忍者诸国面临前所未有的挑战……本片为漫画家岸本齐史的同名原著的剧场版。©豆瓣', '竹内顺子', '村田雅彦', 7.2, 9111, 'tt1481363', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1031797948.jpg', 1.1, 5.7, 42.5, 34.3, 16.4, '-0.151861,-0.094729,-0.303883,0.468469,0.352635,-0.182358,0.093625,0.188806,0.084634,-0.622882,0.215825,0.799011,0.179554,-0.012888,0.349852,-0.151935,-0.055103,-0.452579,-0.337339,0.069760,-0.348610,-0.138368,0.121186,-0.004955,-0.390085,-0.417026,1.233591,0.313911,-0.478272,0.356932,0.219398,0.524775,-0.344745,0.229990,0.261157,0.099362,0.137133,-0.143704,-0.183011,0.542044,-0.101261,0.048608,-0.000173,0.286063,-0.122802,0.237575,0.471551,-0.346069,0.107735,-0.393658,0.296798,-0.373847,-0.301669,0.299119,0.638095,-0.124045,-0.134368,0.145415,0.099770,-0.291342,-0.194762,-0.028011,-0.984842,-0.061890,0.096973,-0.009212,-0.192795,0.391083,-0.130572,-0.032517,0.468669,-0.227505,0.178258,0.507859,0.278938,-0.170305,-0.348940,0.174136,0.108839,-0.169478,0.628014,-0.339314,-0.084429,-0.244457,-0.079718,-0.268994,-0.307948,-0.457189,-0.116521,-0.048872,-0.011118,0.128586,-0.044371,0.213988,-0.297707,-0.010984,-0.136784,-0.120388,0.071975,0.029184,-0.088713,-0.873159,0.070824,-0.160516,-0.208533,0.095969,0.222500,-0.322755,0.824168,-0.885425,0.141323,0.656137,0.385157,-0.072121,0.405683,0.287362,0.107539,-0.562327,-0.249101,0.340209,0.204428,0.534236,0.228697,0.062630,-0.069894,0.164220,-0.360907,0.232910', '2369613', '25880986', '26759819', '2051813');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3862627', '扑克王', '喜剧', '澳门赌场的老板刚刚去世，对头况小姐（何超仪 饰）突然前来挑衅，幸好代掌柜卓一（刘青云 饰）及时赶到，才化险为夷。原来，赌场太子张人杰（古天乐 饰）远在加拿大，赌场生意遵遗嘱由卓一打理。在卓一的安排下，张人杰千里迢迢回来奔丧，但各位股东均感到这个小伙子缺乏经验。在跟卓一的单挑中，张人杰更是屡遭戏弄。张人杰整天沉迷网络扑克，结识了一个牌友（应采儿 饰）。二人相约在扑克邀请赛相会。虽然在刻意安排下，二人同桌，但是由于张人杰缺乏实战经验，所以屡尝败绩。在众人嘲笑声中，黯然离场。在张人杰一蹶不振的时候，他遇到了命中贵人——笑容（邓丽欣 饰）。在她的帮助下，他恢复了信心，不但扑克技艺大涨，两人也日久生情，但是他们的命运此时却发生了改变……©豆瓣', '古天乐', '陈庆嘉', 5.5, 22794, 'tt1471236', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1108442595.jpg', 7.2, 27.5, 52.2, 10.2, 2.8, '0.082562,0.226049,-0.606823,0.219679,0.020204,-0.314210,0.409180,0.334636,-0.298454,-0.359815,0.475204,0.629697,-0.206364,0.243855,0.251077,-0.337910,-0.111134,-0.493146,0.145176,-0.233055,-0.017034,-0.333308,-0.191092,-0.110832,-0.213528,-0.313258,0.188450,0.150864,-0.133530,0.815326,0.243587,-0.232980,-0.238137,0.702402,0.014312,0.131969,0.066637,0.191298,-0.432384,0.016635,0.029387,-0.390834,-0.286256,-0.005089,0.305144,0.384997,0.428141,-0.081803,-0.271992,0.246732,0.195270,-0.027156,0.034074,0.051812,0.434618,-0.102368,0.135525,0.209219,-0.243886,0.186466,-0.097026,0.179703,-0.316238,0.287853,0.168520,0.061567,-0.483480,0.489630,-0.182062,0.046005,-0.371746,-0.414594,0.230091,0.360835,0.194243,0.090906,-0.154659,0.224289,-0.456300,0.029244,0.608194,0.064640,0.066673,0.120549,0.027207,-0.354831,-0.024478,-0.042149,-0.249721,0.037111,0.333541,-0.247177,-0.022783,0.012564,-0.434216,-0.050914,-0.102712,0.169160,-0.182349,-0.190797,0.051454,-0.723918,-0.151271,-0.286879,-0.306175,0.197145,0.239353,-0.228278,0.431607,-0.828622,-0.050368,0.246970,0.288078,-0.503191,0.503531,0.069053,-0.029301,-0.089321,-0.331560,0.008634,0.133621,0.124317,0.087033,0.267680,-0.225352,-0.154512,-0.283112,0.054029', '3139191', '1307186', '26365262', '1302987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3863845', '钢铁骑士', '动作', '“钢铁骑士”曾是美泰一款风行全球的男孩人偶玩具，也曾被拍成电视系列动画片，此次真人电影版的故事是《雷神2：黑暗世界》（Thor: The Dark World）编剧克里斯托弗·约斯特（Christopher Yost）原创的。故事讲述16岁男孩麦克斯（Max McGrath）和母亲居住在一个小镇上，他的科学家父亲当年在他出生后不久就神秘死亡，麦克斯拥有一种他自己都无法控制的超强能量，直到遇到有着先进技术的外星人Steel后，才学会运用它，“钢铁骑士”就此诞生！', '本·温切尔', '斯特瓦特·亨德尔', 3.7, 4141, 'tt1472584', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2391931833.jpg', 36.9, 45.2, 15.1, 2.3, 0.5, '0.059464,0.003572,-0.579198,0.663299,-0.149259,-0.169987,0.794370,-0.210928,-0.535992,-0.509300,0.600251,1.033626,-0.161044,0.358177,-0.001167,0.284539,-0.232645,-0.419532,0.040680,-0.059289,-0.135519,-0.186421,-0.437823,-0.064944,0.122899,-0.720745,0.893781,-0.251356,-0.436276,-0.055148,-0.019088,0.099516,-0.152974,0.137850,-0.309580,0.262786,0.059108,0.009660,-0.097671,0.254189,-0.136250,-0.133815,0.148210,0.085118,-0.452139,0.072399,0.678173,-0.414532,0.040736,-0.256550,0.603024,-0.074592,-0.171876,-0.124767,0.467443,0.168927,0.245185,0.007558,0.270758,-0.134434,-0.211511,-0.191273,-0.604294,-0.247161,0.131314,0.002421,-0.455497,0.288075,-0.185005,0.253834,0.096802,-0.371869,0.007105,-0.130871,0.334807,0.511014,0.013028,0.152661,-0.439208,0.589073,0.421916,-0.200464,-0.631593,0.505492,-0.129536,-0.591711,-0.545164,-0.574693,-0.808611,0.296456,0.300582,0.022512,-0.227047,0.327880,-0.771845,0.107503,-0.071896,-0.020031,0.193647,0.046679,0.027087,-0.661877,-0.134712,-0.302375,-0.060682,-0.258314,0.133346,-0.429851,0.938909,-0.631423,0.492826,0.493146,0.211365,-0.141890,0.704226,-0.472742,-0.144357,-0.194344,0.324158,0.398123,-0.025687,0.160524,-0.059221,0.419937,0.318599,-0.045826,-0.251314,0.818537', '1870681', '3882427', '22265121', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3868141', '单身日记：好孕来袭', '喜剧', '布里切特·琼斯（蕾妮·泽尔维格 Renée Zellweger 饰）偶然邂逅了帅气的亿万富翁杰克（帕特里克·德姆西 Patrick Dempsey 饰），同时，与她有着复杂情史的达西先生（柯林·费尔斯 Colin Firth 饰）也重新回她的身边。两个完美男人同时闯入布里切特的生活，并且给她带来了一个巨大的“惊喜”，让她深陷甜蜜的烦恼之中。而布里切特的真命天子究竟是谁呢？', '蕾妮·齐薇格', '莎伦·马奎尔', 7.2, 56460, 'tt1473832', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2403803540.jpg', 1.1, 6.9, 38.8, 36.9, 16.3, '0.245270,0.088771,-0.622210,0.736402,-0.027499,-0.683186,1.068554,0.257018,-0.192470,-0.052853,0.004111,0.544013,0.044036,-0.046861,0.327179,0.579564,-0.710334,-0.715685,0.430600,-0.517862,-0.057028,-0.658060,-0.691142,-0.202486,0.200494,-0.398444,-0.082485,-0.057775,0.197020,0.496753,0.604180,0.609895,0.051099,0.519090,0.147481,0.084325,0.507706,-0.144620,-0.182964,0.166863,0.141938,0.140156,-0.116030,0.315147,0.049179,0.269857,0.420687,-0.284693,0.144108,0.043267,0.143219,0.094406,0.210347,0.139018,-0.407228,-0.327981,0.312357,-0.058026,-0.387229,-0.104217,0.505838,-0.123757,-0.627950,0.155917,-0.045332,0.218157,-0.555090,0.184836,-0.163810,-0.186035,0.241140,-0.192517,-0.036171,0.524240,0.539269,0.151073,-0.039893,0.018500,-0.230233,-0.077819,0.365795,0.332816,-0.363405,-0.035434,-0.621787,-0.359651,0.059553,0.046682,-0.888919,-0.015601,0.642152,-0.247986,0.336774,0.412264,-0.648478,-0.233065,-0.789484,0.124729,-0.289018,-0.446660,-0.131702,-0.382411,-0.050730,-0.372400,-0.492806,-0.152433,0.000867,-0.241940,0.566615,-0.590969,0.428971,0.565449,0.210486,-0.000556,0.543971,-0.012112,0.270941,-0.168704,-0.434574,0.430167,0.006268,-0.008122,0.151427,0.662248,-0.007704,0.153314,-0.407912,0.730695', '1578663', '1298442', '23424586', '1292831');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3871833', '怪兽', '剧情', '六年前，美国太空总署观测到地外文明，但是派出勘测的飞船返航时在墨西哥坠毁。从此之后，墨西哥许多地区受到外星神秘生物的感染，无数百姓丧生。美国方面派出军队与巨大的外星怪兽作战，彼此伤亡惨重。洛杉矶的记者安德烈·卡特（斯科特·麦格纳瑞 Scoot McNairy 饰）接受 某富翁的请求，前往墨西哥感染区寻找其女儿萨曼莎·温登（惠特尼·阿贝勒 Whitney Able 饰）。安德烈顺利见到萨曼莎，二人随即踏上开往美国的列车，然而列车却在中途折返。他们被迫寻找其他归国的途径，只是命运难测，回国之路似乎充满险阻。万般无奈，安德烈和萨曼莎只得步行穿越危险重重的感染区……©豆瓣', '惠特尼·阿贝勒', '加里斯·爱德华斯', 6, 8479, 'tt1470827', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p585963195.jpg', 7, 20.8, 43.9, 20.9, 7.4, '0.240304,0.064425,-0.900536,0.517935,0.404581,-0.134459,0.543810,-0.117612,-0.294598,0.016673,0.290136,0.740200,0.031761,-0.025875,0.405868,-0.043425,-0.669201,-0.228226,0.131854,-0.080116,-0.398246,-0.343162,-0.199075,-0.229847,-0.027834,-0.298812,0.784631,0.520908,-0.218180,0.636878,-0.152471,0.595733,-0.531679,0.570263,-0.098839,-0.033134,0.295476,-0.156912,-0.400999,0.247504,-0.209133,0.049365,-0.178374,-0.099177,0.035292,0.350747,0.699502,-0.105327,0.035906,-0.368282,0.092783,-0.330986,0.157223,-0.210690,0.411322,0.139042,-0.179131,-0.008142,0.062688,0.017526,0.060959,0.298215,-0.006305,-0.016580,-0.115189,0.135467,-0.152718,-0.166346,-0.149413,0.128190,-0.020083,-0.333072,0.179115,0.665380,0.063431,0.041380,0.138159,0.194850,-0.324714,-0.075295,0.845684,-0.218075,-0.585702,-0.271061,-0.065431,-0.585468,0.197152,-0.274357,-0.274125,0.011980,0.318176,0.139529,-0.029554,0.468568,-0.627224,0.138328,-0.488491,-0.499143,-0.048395,-0.117891,0.087379,-1.289177,0.439809,-0.217906,-0.090025,0.345974,0.173417,0.103120,0.367103,-0.333268,0.308006,0.543049,0.472731,-0.656583,0.570784,-0.240341,0.128189,-0.249087,0.180977,0.639629,0.005385,0.510946,-0.179440,-0.032706,-0.075653,-0.069622,-0.181073,0.161963', '34961898', '2075345', '2159244', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3874981', '全城戒备', '动作', '奇艺坊马戏团在马来西亚巡回演出，团员们偶然听说二战时期日本人留下的宝藏的消息。在飞刀高手张大初（邹兆龙 饰）的带领下，他们一行五人杀害寻宝者，一心想成为飞刀行家的小人物桑尼（郭富城 饰）尾随前来，亲眼目睹大初一众行凶全过程。他被迫随众人下洞，却无意开启日军留下的生化武器。经过一番难以想象的艰苦磨难，桑尼侥幸逃生，却变成奇怪的摸样。与此同时，香港接连发生数起抢劫案。行凶者赤手空拳，手段残忍，他们正是受毒气感染发生变异的张大初等人。这一连串事件震惊全港，警方从内地请来个中高手孙皓（吴京 饰）与程秀华（张静初 饰）协助调查。而桑尼也摇身一变成为与邪恶对抗的正义使者……©豆瓣', '郭富城', '陈木胜', 4.6, 45258, 'tt1691832', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p564132460.jpg', 21.3, 37.2, 32.8, 6.2, 2.5, '-0.016017,-0.218807,-0.657539,0.240417,0.095279,0.240432,0.647869,-0.417354,-0.526698,-0.342774,0.575673,0.601672,-0.388285,-0.068394,0.251027,-0.450784,-0.145102,-0.492136,-0.028737,-0.145126,-0.122841,-0.064000,-0.445931,-0.264135,0.118149,-0.357485,0.335490,0.232026,-0.416096,0.650588,0.479712,0.502554,-0.635269,0.128247,-0.046972,0.142160,0.248939,0.075718,-0.357065,-0.065569,-0.567252,-0.511997,-0.346443,-0.002613,-0.079145,0.319648,0.550923,-0.241754,-0.133901,-0.273657,0.055668,-0.491955,-0.237839,0.136392,0.604730,0.201323,0.266198,-0.020549,0.049137,0.076822,-0.105889,0.180932,-0.820337,0.104572,0.259868,0.171026,-0.248144,0.137153,-0.031891,0.103922,-0.023245,-0.279614,0.086093,0.270080,0.249546,0.127313,0.035169,-0.044183,-0.340880,0.119475,0.871828,-0.223036,-0.192529,-0.036777,0.271301,-0.487884,0.097888,-0.327843,0.032085,0.244473,0.457725,-0.073540,-0.177253,0.345733,-0.357070,-0.153009,-0.266325,-0.096300,-0.162809,0.045619,-0.071036,-0.859169,0.046451,-0.187550,-0.383774,0.249096,0.132254,-0.085019,0.517920,-0.483748,0.121469,0.165453,0.155293,-0.481870,0.326308,-0.109921,0.037343,0.087691,-0.309943,0.001755,0.439066,0.310390,0.056411,0.332840,-0.320606,-0.271934,-0.122287,-0.204029', '3147969', '10466639', '1294941', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3878007', '海王', '动作', '许多年前，亚特兰蒂斯女王（妮可·基德曼 Nicole Kidman 饰）和人类相知相恋，共同孕育了爱情的结晶——后来被陆地人称为海王的亚瑟·库瑞（杰森·莫玛 Jason Momoa 饰）。在成长的过程中，亚瑟接受海底导师维科（威廉·达福 Willem Dafoe 饰）的严苛训练，时刻渴望去看望母亲，然而作为混血的私生子这却是奢望。与此同时，亚瑟的同母异父兄弟奥姆（帕特里克·威尔森 Patrick Wilson 饰）成为亚特兰蒂斯的国王，他不满陆地人类对大海的荼毒与污染，遂谋划联合其他海底王国发动对陆地的全面战争。为了阻止他的野心，维科和奥姆的未婚妻湄拉（艾梅柏·希尔德 Amber Heard 饰）将亚瑟带到海底世界。宿命推动着亚瑟，去寻找失落已久的三叉戟，建立一个更加开明的海底王国……©豆瓣', '杰森·莫玛', '温子仁', 7.6, 842967, 'tt1477834', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2541280047.jpg', 0.9, 4.5, 30.5, 43, 21.1, '0.087259,0.287279,-0.849535,0.758485,0.014930,-0.153512,0.751777,0.072356,-0.382875,-0.082895,0.201164,0.729415,0.143088,0.025899,0.331625,0.221968,-0.566973,-0.427808,0.050005,0.037059,-0.229767,-0.462923,-0.739459,-0.297491,-0.022930,-0.545908,0.762484,-0.025436,-0.234764,0.346618,0.037821,0.415251,-0.171036,0.212957,-0.110558,-0.033808,0.132388,0.090443,-0.512395,0.068011,-0.322662,0.324773,-0.009435,0.264162,0.062846,0.238115,0.475886,-0.588571,0.359048,-0.503185,0.147397,-0.352207,0.050365,-0.019478,0.363451,-0.105079,-0.170424,0.376790,-0.045160,-0.218216,0.186030,-0.117954,-0.726155,-0.027554,0.137714,0.174263,-0.573708,0.399266,0.017346,-0.195053,0.033612,-0.175575,-0.006409,0.422375,0.180859,0.301589,-0.100627,0.192409,-0.179442,0.132420,0.590737,-0.198708,-0.396545,-0.010473,-0.253314,-0.377488,-0.123875,-0.174255,-0.588146,-0.339823,0.261126,0.059591,-0.009349,0.681356,-0.897273,-0.038756,-0.433870,-0.102453,0.307566,-0.448606,-0.065743,-0.613089,-0.116148,-0.367075,-0.163164,-0.248458,0.152378,-0.231994,0.696562,-0.521541,0.267350,0.514928,0.398451,-0.445387,0.745092,0.195466,0.081539,-0.463752,-0.143234,0.809116,0.064917,0.103620,-0.134151,0.086897,0.218933,0.211044,-0.284040,0.485256', '26290398', '1309031', '1915381', '25890017');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3878157', '电锯惊魂7', '悬疑', '吉尔·塔克（贝茜·拉塞尔 Betsy Russell 饰）向警方和盘托出竖锯事件的始末，而侥幸逃脱死亡威胁的马克·霍夫曼（科斯塔斯·曼迪勒 Costas Mandylor 饰）则向警方发出警告，势要杀掉吉尔不可。警署上下如临大敌。另一方面，自称竖锯游戏幸存者的波比·达根（肖恩·派特里克·弗兰纳里 Sean Patrick Flanery 饰）高调现身，演讲、出书、接受电视台专访、组织幸存者自救会，风光无限之时名利双收。然而波比只是一个为搏出位的骗子，他的谎话骗过了大多数人，却骗不了竖锯约翰（托宾·贝尔 Tobin Bell 饰）。一场针对波比及其团队的残酷生存游戏拉开序幕……本片为电锯惊魂系列第七部，制作成3D影片上映。©豆瓣', '托宾·贝尔', '凯文·格劳特', 7.8, 97914, 'tt1477076', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p689612649.jpg', 0.8, 3.4, 28.2, 42.4, 25.1, '0.054769,-0.145400,-0.306114,0.323177,0.222685,-0.075774,0.540915,-0.067698,-0.101059,0.043823,0.403904,0.135872,-0.389978,-0.254605,0.197980,-0.148778,-0.453734,-0.477104,0.106549,0.120941,0.128751,-0.295579,-0.209756,-0.483374,-0.071287,-0.122343,0.624880,-0.102544,-0.290591,0.140044,0.532789,0.744090,0.002804,-0.193572,0.359041,-0.052657,0.082787,-0.385622,-0.505993,0.284326,-0.220216,-0.075379,-0.313337,0.214319,-0.184128,0.490046,0.340200,-0.222318,0.100123,-0.186439,0.452710,-0.502133,0.051356,-0.026876,0.249065,-0.002582,0.109919,0.022273,0.064279,-0.052534,0.042598,0.011746,-0.631904,0.144472,0.090007,0.333574,-0.088946,-0.001775,-0.417912,0.425502,-0.147844,-0.132713,-0.283806,0.016439,0.585118,0.029305,0.099326,0.249620,-0.313980,0.075164,0.261751,-0.093896,-0.239808,0.047823,0.066302,-0.228944,-0.047280,-0.214683,-0.367919,0.118433,0.420993,-0.272004,0.227468,0.692872,-0.415619,-0.279125,-0.434273,-0.205861,0.021354,-0.207018,-0.140835,-0.970046,0.121248,0.237173,-0.050341,0.055603,0.257145,-0.277002,0.187909,-0.258104,-0.063667,0.366639,-0.013476,-0.093745,0.303459,-0.027869,0.018060,-0.158243,-0.013479,0.230841,0.385000,-0.070335,0.185945,0.095396,0.293989,-0.428785,-0.230698,0.334186', '4014397', '6517421', '2369613', '34961898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3880545', '伴娘', '喜剧', '人到中年的安妮（克里斯汀·韦格 Kristen Wiig 饰）仍旧一事无成，浑噩度日。交往已久的男友只是把她当做情人，并无与她组建家庭的打算。此时，安妮的好友莉莉安（玛娅·鲁道夫 Maya Rudolph 饰）突然要结婚了，并邀请了包括她在内的几名女性好友组成伴娘团。伴 娘团之中的海伦（萝丝·拜恩 Rose Byrne 饰）家底深厚且八面玲珑，倾力为莉莉安打造奢华订婚礼。安妮不满海伦主导订婚礼筹备，处处与其针锋相对，试图向莉莉安昭告她深厚的情谊，但每次努力都令众人不悦，反而引致莉莉安的不满。同时，安妮也开始面对人生中的诸多问题。交警罗兹（克里斯·奥多德 Chris O''Dow 饰）的出现似乎为安妮打开了另一扇窗。安妮能否摆脱这些困境，步入生活的正轨呢？©豆瓣', '克里斯汀·韦格', '保罗·费格', 6.9, 60987, 'tt1478338', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1242698807.jpg', 1.6, 8.5, 45.5, 34, 10.3, '0.439051,0.088879,-0.416248,0.361819,0.031225,-0.493406,0.647193,0.261748,-0.475009,-0.380959,-0.051126,0.457460,-0.372244,0.262440,0.328913,0.153021,-0.466014,-0.716495,0.090625,-0.017446,0.025632,-0.537040,-0.047319,-0.258772,-0.173453,-0.119532,0.567438,-0.252978,0.129655,0.376426,0.357147,0.366905,-0.202890,0.354283,0.249898,0.012389,-0.016212,-0.385494,-0.435743,-0.011339,-0.192120,0.018589,-0.085905,0.352862,0.342326,0.456285,0.558776,-0.054778,0.136751,-0.063872,0.220647,0.111134,0.195129,0.208827,-0.027424,0.127242,0.162452,0.253347,-0.037437,0.105480,0.228667,-0.313008,-0.553848,0.191207,0.217043,0.099769,-0.513290,0.415857,0.003637,0.039887,0.062377,-0.084454,-0.106147,0.494173,0.132329,0.396335,-0.172009,0.323732,-0.296547,-0.015988,0.334659,0.163436,-0.148643,0.341856,-0.374147,-0.102796,0.093326,0.068701,-0.709849,-0.238174,0.146099,0.277592,0.343301,0.398313,-0.599060,-0.135095,-0.497051,0.083974,0.068196,-0.367524,0.118236,-0.724883,-0.098680,-0.410841,-0.490316,-0.192181,-0.042708,-0.213554,0.590382,-0.804196,0.125013,0.220518,0.446323,-0.310371,0.368109,0.232951,0.407634,-0.178879,-0.231456,0.339127,-0.246904,0.094970,0.099456,0.066147,0.121774,-0.065478,-0.172228,0.241814', '1299556', '3626365', '1301022', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3882427', '我在雨中等你', '剧情', '影片改编自Garth Stein所著同名畅销小说，聚焦一只名叫恩佐的狗狗，和他的主人——职业赛车手Denny Swift，恩佐跟着Denny学会了很多生活哲学。', '凯文·科斯特纳', '西蒙·柯蒂斯', 8.4, 59651, 'tt1478839', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2557226052.jpg', 0.3, 1.2, 15.4, 46.7, 36.4, '0.347352,-0.433579,-0.221407,0.792767,0.079344,-0.126183,0.611904,-0.097740,-0.012480,-0.548279,0.116563,1.313027,-0.058956,0.043763,0.166337,-0.225493,-0.071448,-0.573766,0.021082,0.202880,-0.026526,-0.302211,-0.288975,-0.087875,-0.208767,-0.468407,0.948573,-0.421069,-0.353596,0.255075,0.370885,0.352724,-0.206406,-0.339117,-0.528026,0.124221,0.045960,-0.320619,-0.145892,0.238645,0.080437,0.203795,-0.061254,-0.415044,0.041097,-0.374060,0.666586,-0.308657,-0.206733,-0.105122,0.464366,-0.092435,-0.258960,-0.299043,0.052802,0.232089,0.403428,0.075124,0.245703,0.217236,-0.407351,-0.126408,-0.773408,-0.116764,0.232016,0.344058,-0.669113,0.113866,-0.073708,-0.245134,-0.055171,-0.402181,0.310736,-0.122583,0.359125,0.360848,0.173344,0.327800,-0.201844,0.521324,0.270448,-0.118767,-0.110244,0.744898,-0.073688,-0.653559,-0.333958,0.010124,-0.509727,-0.017429,0.170106,-0.109232,-0.558352,0.229400,-0.719766,0.025199,0.278695,-0.544258,-0.141820,-0.537856,0.015795,-0.456290,0.221693,-0.570311,0.212120,-0.251020,0.109677,-0.529132,1.184183,-0.913866,0.034304,0.262372,-0.186753,-0.356582,0.851330,-0.333823,-0.141044,-0.208467,-0.004639,0.533502,0.338846,0.123616,0.102808,0.577074,0.208972,-0.145668,-0.411741,0.982725', '1870681', '27602116', '25880986', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3892235', '火星没事', '喜剧', '小男孩没事（孙天宇 饰）跟养父罗秉文（黄磊 饰）相依为命。5岁时，没事语出惊人，说自己来自火星人，令其父很是无奈。罗秉文为某公司高级白领，风骚同事Tina（谢娜 饰）暗恋着他，不但暗送秋波还激情示爱，但均被罗秉文婉言谢绝。倒是顶头上司陆小凤（刘仪伟 饰）对她情有独钟。罗秉文喜欢的是没事的幼儿园老师陈雨（关悦 饰）。不过，没事整天闯祸，搞得两人焦头烂额，大家都开始相信没事是个火星人。财神（王晶 饰）跟陆小凤谈生意，其实另有图谋。他想骗钱十万，用于股市救急，没成想东窗事发。此时，没事离家出走，陆小凤和Tina刚找到他，就被财神一伙绑架了。财神发现了没事具有超能力的秘密，而罗秉文等人则要维护正义，一场对决就此展开……©豆瓣', '黄磊', '刘仪伟', 4.9, 21098, '火星宝贝之火星没事', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1935705600.jpg', 18.4, 31.8, 39.1, 8.3, 2.5, '0.137842,-0.343621,-0.438512,0.042755,-0.262679,-0.078943,0.480221,0.008193,-0.423227,-0.300149,-0.044134,0.458585,-0.296054,0.368109,0.110184,0.186004,-0.193436,-0.451341,0.131356,-0.112745,0.089872,-0.390041,0.060998,-0.024425,-0.149113,-0.106393,-0.035158,-0.108652,-0.158481,0.446062,0.361272,0.210967,0.122738,0.289680,-0.113146,0.014894,-0.155999,0.171725,-0.130319,0.136298,0.131315,0.003661,0.008224,0.146247,0.188318,0.194205,0.180176,0.077514,-0.206265,-0.026591,0.126912,-0.340530,0.033528,0.134560,0.475079,-0.033110,0.541678,-0.118276,-0.085070,0.069340,0.214475,0.062282,-0.381124,0.260787,0.228749,-0.177820,-0.409541,0.267306,-0.052619,-0.154274,0.087811,-0.196366,0.332008,0.388931,0.312335,0.202456,0.079530,0.185403,-0.602040,0.216554,0.490503,0.108404,0.267907,0.361491,0.292698,-0.127654,0.017486,-0.094120,-0.217249,0.215001,-0.129682,-0.285587,-0.076507,-0.153956,-0.311162,-0.005941,0.153698,0.077319,-0.183391,-0.374494,0.058715,-0.246162,-0.059291,-0.486378,-0.265331,0.101547,0.149447,-0.203817,0.523252,-0.735511,0.034716,0.391917,0.321330,-0.673513,0.612991,0.184744,-0.408559,-0.359428,0.090161,-0.314186,0.082919,0.020752,0.437794,0.270929,0.374323,-0.571462,-0.021270,0.024443', '2079632', '1308755', '1418613', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3892449', '熊猫大侠', '喜剧', '南宋年间，金国老狼主派出刺客叽里咕噜潜入临安，图谋在临安城举办“天下一心”文艺汇演之时刺杀励精图治的大将军（任泉 饰）。二人多方打探得知演出当天将有一只从卧龙运来的会跳舞的熊猫表演，于是便想出计策冒充接镖人绑架大熊猫以图接近大将军。家居四川年逾四十却又一事无成的飞镖师傅王老吉（刘桦 饰）被误认为是“天下第一镖师”而接手押运大熊猫一差，王老吉为了证明自己可以吃镖师这碗饭，遂怀揣押镖秘籍一本，义无反顾的上路了。不料半路遭遇女山贼金莲（阿朵 饰），而且又一次被误认为是苦等多年的恋人黄老吉；到达临安又认识怀才不遇的女捕头（邓家佳 饰），而且被误以为是进行野生动物贩卖的罪犯；叽里咕噜这时也出现在食全食美大酒楼，企图以冒充身份骗走大熊猫。多方力量汇集于食全食美大酒店，王老吉最终能否顺利完成押镖任务？又能惹出什么让人啼笑皆非的故事？©豆瓣', '刘桦', '王岳伦', 4.4, 27556, 'tt2365970', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1388842478.jpg', 25.5, 36.8, 31.2, 5.1, 1.3, '0.064565,-0.060183,-0.313246,0.322395,0.037559,-0.054481,0.218211,0.091455,-0.490443,-0.208544,0.395984,0.532749,-0.177856,-0.054189,0.357761,0.025592,0.181008,-0.486307,0.192491,-0.396242,0.054194,-0.162642,-0.246778,-0.067946,-0.048426,-0.197389,0.127152,0.091337,-0.091570,0.470761,0.473489,0.215198,-0.290651,0.285855,-0.224178,0.009621,0.205099,-0.064240,-0.107577,0.324489,-0.113741,-0.663237,-0.027379,-0.111284,-0.053786,0.205118,0.670302,-0.093264,0.031467,-0.197956,0.194556,-0.226361,-0.069396,0.018270,0.407291,0.197726,0.099254,0.066458,-0.174261,-0.119847,0.074899,-0.093746,-0.516453,0.007158,0.212944,-0.010426,-0.518407,0.140380,-0.048598,0.122738,0.010883,-0.257371,0.261471,0.357414,0.430352,0.177747,0.258409,0.023465,-0.723269,0.275234,0.618451,-0.134852,0.205932,-0.001815,0.336350,-0.342845,0.517058,-0.341908,-0.032235,0.231194,0.323232,-0.162296,-0.128356,-0.119570,-0.483892,0.040225,-0.455430,0.062340,0.231920,-0.147915,-0.156576,-0.380747,0.140259,-0.102100,-0.041996,0.065763,0.423149,0.001611,0.530116,-0.670134,-0.043277,0.489341,0.151443,-0.683291,0.452906,0.039699,-0.181596,0.044457,-0.137619,-0.262148,0.311323,0.435142,0.041803,0.215029,-0.198388,-0.498978,-0.394838,-0.053796', '1297710', '1366853', '1292829', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3893805', '老雷斯的故事', '动画', '在一个名叫特尼镇的所在，鸟语花香，草木清新，生活富足，只是这些都是表面的假象，所有的树木都由人工材料做成，并通过电脑和电力维持运作。虽然空气质量糟糕，可是当地的人民乐于享受这便利的现代化生活，更何况有欧海尔先生（Rob Riggle 配音）为他们提供新鲜的桶装空气呢！小青年泰德（扎克·埃夫隆 Zac Efron 配音）暗恋美丽的姑娘奥黛丽（泰勒·史薇芙特 Taylor Swift 配音），为了帮助女孩实现见到真正树木的梦想，他铤而走险离开特尼镇，来到满目疮痍、阴霾污浊的外部世界寻找传说中知晓关于树木一切信息的老万。从老万口中，泰德了解到这个曾经的成功商人以及当初棉花树满布的乐园变成荒山的全过程。乐土从此一去不返，除非……本片改编自著名苏斯博士（Dr. Seuss）1971年经典同名原著，并荣获2012年青年选择奖最佳配音（Taylor Swift）和最佳动画片奖。', '扎克·埃夫隆', '克里斯·雷纳德', 6.9, 26062, 'tt1482459', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1466520213.jpg', 1.1, 7.8, 47.5, 31.8, 11.8, '-0.016189,0.034820,-0.474003,0.518289,0.029226,0.007319,0.402004,-0.014356,-0.466632,-0.468042,-0.009192,0.472771,0.102202,-0.057748,0.199924,0.127030,-0.405527,-0.256126,-0.028003,-0.209386,-0.110787,-0.325279,-0.472527,-0.220461,-0.176196,-0.441097,0.858537,0.264819,-0.178924,0.315673,-0.020020,0.091474,-0.104323,-0.080242,-0.227695,-0.137042,0.054326,-0.024509,-0.708748,0.142089,-0.347421,0.036749,0.006587,-0.149368,0.258681,0.169871,0.543611,-0.252301,-0.251758,0.216976,0.426445,-0.244374,0.062676,0.043008,0.081876,-0.234164,0.315160,0.122845,-0.189322,-0.003471,-0.094266,-0.388620,-0.825176,-0.096663,0.259255,0.030883,-0.129806,0.331273,0.232954,-0.260255,-0.071800,-0.294323,0.346372,0.014604,0.287075,0.496232,-0.107637,0.221947,-0.249439,0.346793,0.433506,-0.047916,-0.377559,0.480779,-0.419631,-0.308135,-0.066175,-0.152848,-0.348168,0.179868,-0.002484,0.141155,0.081893,0.219549,-0.724723,0.218131,-0.004776,-0.439806,0.399426,-0.219412,-0.455306,-0.723461,-0.145236,-0.074592,-0.013704,-0.160370,0.088819,-0.566991,0.644576,-0.677808,0.292128,0.350937,-0.037077,-0.276952,0.471039,-0.166633,0.066159,-0.325173,-0.476662,0.671413,0.239023,0.339918,-0.312720,0.103680,0.052818,-0.353652,-0.408785,0.226081', '2369613', '26759820', '25880986', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3893814', '大都会', '剧情', '未来，纽约，年轻巨富埃里克·帕克（罗伯特·帕丁森 Robert Pattinson 饰）坐在豪华轿车里，在保镖贴身保护下，前去从小就熟悉的那家理发店。一路上，他遇到形形色色的人，各种怪异的事：他的年轻妻子爱丽丝（莎拉·加顿 Sarah Gadon 饰）与他若即若离，只能在路上偶遇；一位中年女人（朱丽叶·比诺什 Juliette Binoche 饰）前来和他做爱然后告知他艺术品信息；人民币持续升值令他眼睁睁看着财产损失，车窗外的曼哈顿逐渐陷入一场暴乱，还有人在追踪他，似乎想要杀死他。攻击从一个蛋糕上升到子弹，空气中的一切充满恐慌和末世感，如期抵达理发店的帕克也想知道这混乱的一天该如何结束……©豆瓣', '罗伯特·帕丁森', '大卫·柯南伯格', 5.5, 7947, 'tt1480656', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2666374525.jpg', 12.8, 29.2, 34.8, 16.3, 6.8, '0.001335,0.122087,-0.822602,0.451280,-0.152575,-0.073441,1.011303,0.130201,-0.391102,-0.344679,0.490986,0.809748,-0.270215,0.233247,0.467184,0.158825,-0.465768,-0.655986,0.028043,-0.140489,-0.455114,-0.246802,-0.350296,-0.439104,0.214599,-0.194178,0.442191,0.236970,-0.151568,0.496133,0.214964,0.205121,-0.190103,0.715136,-0.277978,0.044462,0.099300,-0.059502,-0.227890,0.115054,-0.025502,-0.320186,-0.261077,-0.062069,0.055912,0.147849,0.699167,-0.043191,-0.153852,0.249201,0.029412,-0.119014,0.009558,0.171419,0.186790,-0.050300,0.074084,-0.131740,-0.409039,0.169067,-0.034856,0.269092,-0.424733,0.177591,-0.344272,0.144777,-0.679966,0.398257,-0.123379,-0.061152,0.298404,-0.442434,0.116945,0.181009,0.058000,0.449272,-0.098432,-0.038493,-0.598999,0.025483,0.713504,0.247335,-0.234920,0.332741,-0.158146,-0.298695,-0.243865,0.035026,-0.582539,-0.101260,0.438806,0.024190,-0.163886,0.225837,-0.572961,-0.023111,-0.029049,-0.424427,-0.205045,-0.266467,-0.375762,-0.692388,-0.051660,-0.428391,-0.293578,0.166814,0.007256,-0.083343,0.468846,-0.473422,0.346562,0.614336,0.251634,-0.321843,0.593803,-0.005660,0.079515,-0.174257,-0.557726,0.189454,0.084666,0.355986,0.131749,0.319137,-0.225015,0.197765,-0.489987,0.494809', '3011051', '1296534', '21619567', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3895511', '遗落战境', '动作', '2017年，母星遭到毁灭的外星流亡者入侵地球。人类虽然用核武器打败对手，但也付出失去家园的惨痛代价。在接下来将近半个世纪的时光中，人类移民泰坦星（土卫六），不过仍有极少部分人类留在故土，扫荡残存的外星掠夺者。杰克·哈珀（汤姆·克鲁斯 Tom Cruise 饰）与维多利亚（安德丽亚·瑞斯波罗格 Andrea Riseborough 饰）即是留守者中的一员，他们的主要任务为保障遍布各地守护水萃取塔的无人机正常运行。看似永无止境的任务终于接近尾声，而就在此刻，不明飞行器坠落一处无人区。杰克在当地发现数名人类伤员，可是他们却遭到无人机的屠杀。危急时刻，杰克救下了一个名为茱莉亚（欧嘉·柯瑞兰寇 Olga Kurylenko 饰）的女子。这一事件令杰克无意中知晓了掠夺者以及自身背后隐藏的秘密……©豆瓣', '汤姆·克鲁斯', '约瑟夫·科辛斯基', 7.1, 151175, 'tt1483013', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1870772842.jpg', 0.9, 6, 43, 37.8, 12.2, '0.070966,0.267313,-0.707932,0.422353,0.062680,0.070691,0.795215,-0.399172,-0.262181,-0.250110,0.443914,0.606017,0.255795,-0.301081,0.365150,-0.046303,-0.418231,-0.225980,-0.101324,-0.237231,-0.560463,-0.303892,-0.554784,-0.292241,-0.213112,-0.592259,0.879247,0.426426,-0.254402,0.291011,-0.052115,0.496045,-0.350040,0.428943,-0.011989,-0.171268,0.193040,-0.349520,-0.134048,0.301274,-0.293444,-0.101337,-0.040191,0.261709,-0.196966,0.434508,0.661000,-0.516599,0.113325,-0.287862,0.140206,-0.378228,0.027216,-0.022003,0.528491,-0.066040,0.071974,0.118999,-0.109490,0.074217,0.090256,-0.014775,-0.849099,-0.256735,0.222534,0.045453,-0.223142,0.388190,0.002455,0.157530,0.008976,-0.193074,0.187484,0.547443,0.294907,0.230651,-0.209831,-0.093275,-0.469537,-0.053477,0.552866,-0.228419,-0.541643,0.076223,-0.215182,-0.573279,-0.272133,-0.438393,-0.280076,-0.102111,0.126950,0.213894,-0.064915,0.716432,-0.920171,0.224199,-0.561013,-0.428299,-0.145603,-0.181393,-0.286587,-0.728140,-0.013286,-0.269515,-0.173665,0.338326,0.229045,-0.168138,0.830469,-0.747521,0.355053,0.575763,0.278773,-0.300237,0.413361,-0.105433,0.271045,-0.361603,-0.082588,0.609329,0.277600,0.389723,-0.143387,-0.034257,-0.019326,-0.205458,-0.246083,0.457587', '1578502', '26667010', '26290398', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3897667', '窈窕绅士', '喜剧', '曾在香港名燥一时的名媛吴嘉倩（林熙蕾 饰）转战内地开了家营销公司，经营惨淡。曾天高（孙红雷 饰）虽年轻有为，腰缠万贯，但却因为土佬帽的气质在慈善晚会上追求名模芳娜结果碰一鼻子灰。于是他决定让吴嘉倩签一份“买一赠一”的活动，不但把自己新产品的宣传企划交由吴嘉倩全权负责，而且由她对自己进行全面“改版升级”，从而能够赢得美人芳心。从此，吴嘉倩便开始了对曾天高“内外兼修”的全面打造过程，戒烟、谈吐、品味，面面俱到，终于曾经的乡巴佬变成了窈窕绅士，并成功的吸引了名模芳娜主动投怀送抱……本片由吴宇森担当监制，是著名影星杨紫琼旗下星城娱乐于2009年推出的亮相之作。©豆瓣', '孙红雷', '李巨源', 6.1, 63632, 'tt1608787', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1108477890.jpg', 3.5, 16.7, 55.6, 20.2, 4, '0.023366,0.246654,-0.403849,0.409793,-0.003672,-0.181091,-0.047217,0.217238,-0.453761,-0.067644,0.073838,0.669325,-0.326495,-0.016730,0.345542,-0.026176,0.087580,-0.674088,-0.109013,0.045757,0.096241,-0.218928,-0.347323,-0.128726,-0.197882,-0.156241,0.496126,0.058320,-0.353972,0.311373,0.597269,-0.066487,0.080310,0.091345,-0.100046,-0.262444,0.239730,0.142650,-0.468174,0.385833,-0.099928,-0.495909,-0.070454,-0.010097,0.137876,0.282555,0.396631,0.059904,-0.241099,-0.102610,0.712438,0.053583,0.042801,-0.033497,-0.017934,0.304860,0.291398,0.181475,-0.368901,0.005695,0.147058,-0.381148,-0.711989,-0.038558,0.286878,-0.182376,-0.485366,0.401812,-0.207638,0.095542,-0.150300,-0.189205,-0.075708,0.037162,0.392232,0.143447,0.250659,0.431208,-0.239554,0.632087,0.403966,0.370456,-0.246579,0.356500,-0.086112,-0.452419,-0.025233,-0.477157,-0.236126,-0.003988,0.083526,0.132633,0.270830,-0.037564,-0.680834,0.007424,-0.209321,-0.235381,0.343216,-0.155177,0.149701,-0.651640,-0.126635,-0.253387,-0.069934,-0.186084,0.286462,-0.304718,0.796620,-0.893870,-0.094024,0.281684,0.251842,-0.827508,0.510022,-0.055674,0.019153,-0.054757,-0.221260,-0.017480,-0.127436,0.223707,-0.064303,0.257602,-0.066243,-0.647959,-0.256953,0.285356', '27602116', '4301278', '1316589', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3899297', '心魔', '剧情', '本片根据真实事件改编。23岁的青年德仔（徐天佑 饰）与酗酒的母亲（惠英红 饰）相依为命。除了帮衬母亲的小杂货铺，德仔平日里无所事事，与附近高中15岁的少女盈（黄明慧 饰）谈起了恋爱，并发生了性关系。德仔与盈之间的情事被盈的父母发现，对方大发雷霆，向德仔的母亲索要一笔巨款，并威胁说要对德仔提出诉讼。软弱的德仔惊慌失措，心急的母亲找到离婚的德仔父亲借钱，却依然无法使盈的父母放弃诉讼。情急之下，德仔与两名朋友约了盈和其好友到郊外谈判，却没想到言语不合出手杀人。已经一无所有的母亲，究竟该如何面对儿子闯下的这无法收场的惨剧呢？本片获第29届香港电影金像奖最佳女主角、亚洲电影奖及香港影评人协会最佳女主角奖（惠英红）。©豆瓣', '惠英红', '何宇恒', 6.3, 7179, 'tt1483799', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p451150694.jpg', 2.2, 12.7, 58.6, 22.2, 4.3, '0.096971,-0.018320,-0.585086,0.449437,0.168300,-0.432330,0.616490,0.108819,-0.332305,-0.418599,0.131995,0.808208,-0.195257,0.312805,0.106932,-0.241101,-0.010386,-0.682570,-0.182165,-0.150025,0.069042,-0.478257,-0.147959,0.226409,-0.275869,0.097770,0.575175,-0.208262,-0.292207,0.521586,0.730529,0.210026,-0.277234,0.189355,0.019796,0.146604,-0.024265,0.380121,-0.646854,-0.078484,0.174594,-0.263886,-0.146716,0.123668,0.112345,0.519405,0.701821,-0.026380,-0.225089,-0.015832,0.689953,-0.037802,-0.081120,0.208767,0.373481,-0.210353,0.256044,0.230884,-0.066567,0.068613,-0.070157,-0.005775,-0.515397,0.150235,0.239845,0.115414,-0.486717,0.056448,-0.030236,0.099427,-0.050436,-0.193663,0.030971,0.453560,0.072218,0.333920,-0.262493,-0.027564,-0.353299,0.470587,0.561353,0.029089,-0.053098,0.397282,-0.199842,-0.493621,0.083867,-0.516389,-0.532147,0.256308,0.087826,0.026165,-0.091944,0.058051,-0.145443,-0.311116,-0.185944,0.133452,0.136969,-0.193091,0.047815,-0.500344,-0.205592,-0.415703,-0.387626,0.074458,0.193784,-0.216994,0.383887,-0.650890,0.126053,0.268082,0.455797,-0.637983,0.500364,0.309096,0.115551,-0.386953,-0.320482,0.259796,-0.110421,-0.068427,-0.081731,-0.087470,0.091097,-0.199567,-0.179079,0.024035', '4301278', '27601006', '1307922', '3804470');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3902408', '黎巴嫩', '剧情', '影片讲述了一个真实的故事，1982年6月黎巴嫩战争的第一天，四名年轻的以色列士兵独自驾驶一辆坦克，被要求配合一队地面士兵作战。该部队的第一个任务是进入黎巴嫩平民村庄，清除那些看上去明显是巴解放组织的恐怖分子。指挥官贾米里描述特派团的行动要领是要“迅速简单”，然而随着士兵进入村庄，看似简单的任务很快变得复杂，最终变成了一场屠杀噩梦。在特派团出动那一刻起，他们和其他部队失去联系，四名士兵就被带到了一个死亡陷阱当中。《黎巴嫩》表现了混乱复杂的中东战争，这部电影不可避免要涉及到政治问题。但最重要的则是，导演希望通过电影描绘四个二十出头年轻人的惊醒，他们突然发现自己身处杀害平民的残酷现实中，杀人成为他们必需做的事情。他们都不是英雄，也没有人想成为英雄。他们的生存本能和人性价值观在激烈斗争，这是一出毛骨悚然的人间悲剧。', 'Yoav Donat', '塞缪尔·毛茨', 7.1, 6883, 'tt1483831', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1580504468.jpg', 2.2, 6.8, 35.2, 44.1, 11.8, '0.455697,0.060597,-0.543675,0.413767,-0.072659,0.217774,0.842095,-0.383841,-0.487695,-0.260126,0.477191,0.660805,0.112680,-0.256659,0.259220,-0.259433,-0.396586,-0.724232,-0.298632,-0.101840,-0.411318,-0.525684,-0.236892,-0.621146,0.011370,-0.416952,0.849141,0.392004,-0.433611,0.362007,0.206666,0.258206,-0.227099,0.320580,0.081715,-0.170966,0.351974,-0.361512,-0.303668,0.145560,-0.453522,-0.028257,-0.224557,0.247644,-0.131591,0.570006,0.653199,-0.395730,-0.235834,0.074101,0.229032,-0.468789,-0.364429,0.081775,0.462502,0.018188,0.176569,0.065239,0.219606,0.025778,-0.396130,-0.158239,-0.862673,-0.087314,0.159146,0.199895,-0.473761,0.375740,0.077617,0.106922,0.285212,-0.017362,0.226964,0.437202,0.523441,0.470136,-0.033746,-0.056978,-0.485263,0.291194,1.025800,-0.209615,-0.478791,0.355559,-0.210364,-0.544602,-0.133262,-0.519643,-0.090468,0.133782,0.232704,-0.118428,-0.160108,0.272455,-0.508762,0.265468,-0.242360,-0.522867,-0.212144,-0.357863,-0.013285,-0.358755,-0.170768,-0.190313,-0.240614,0.306035,-0.179503,0.033571,0.991217,-0.710278,0.065182,0.484453,0.255702,-0.568206,0.402992,0.186196,0.196487,-0.281162,0.263330,0.218556,0.042335,0.256756,0.025611,0.361448,-0.130134,-0.252203,-0.289769,0.285614', '25721544', '27602116', '26678784', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3903715', '红线', '动作', '遥远的未来，飞行交通工具已经取代了汽车，但是赛车这项运动仍然在各个星球广受欢迎。著名的“红线”赛事是赛车界级别最高的比赛，也是众多车手的终极梦想。在竞争红线赛的资格赛——“黄线”比赛中，赛车手JP（木村拓哉 配音）幸运的与“少男猎手”索诺西（苍井优 配音）一同晋级红线。本届红线赛在枪弹横飞的“机器世界”举办，令本就暴虐刺激的赛车更具吸引力。然而主办星球的统治者因担心自己星球的秘密暴露，决定在比赛中全力阻击一众车手；另一方面，JP在幼年时曾与索诺西相识，然而后者似乎忘记了这一切。红线赛如期在枪林弹雨中拉开了帷幕……©豆瓣', '木村拓哉', '小池健', 8.6, 9300, 'tt1483797', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p709489485.jpg', 0.5, 1.5, 13.2, 36.4, 48.4, '-0.149134,0.255957,-0.699000,0.536428,0.209915,0.078223,0.332382,-0.144293,-0.300419,0.095757,0.461214,0.845411,-0.503496,-0.179874,0.392023,-0.382339,0.100622,-0.741452,-0.237246,-0.114676,-0.487841,-0.392647,-0.183696,0.086061,0.139391,-0.474655,1.123709,0.316326,-0.616914,0.643694,0.322571,-0.031971,-0.396961,0.327943,-0.388523,-0.534258,0.313259,0.173040,-0.284693,-0.005903,-0.519771,-0.135008,-0.047285,0.070801,0.333568,0.270152,0.658760,-0.399095,0.236704,0.250470,0.224058,-0.378530,0.023163,-0.214922,0.600187,0.186628,0.003539,0.060017,0.261108,0.237558,-0.155249,-0.330417,-0.790856,-0.077097,0.046174,0.114741,-0.458969,0.756858,-0.054008,-0.147342,-0.010245,0.100840,0.520854,0.042941,0.131857,0.052154,-0.105100,-0.042173,-0.312066,0.377988,0.716513,-0.052800,-0.422024,0.300799,-0.130560,-0.709793,-0.418187,-0.461165,-0.266599,-0.035597,0.546789,0.047845,-0.096075,0.519872,-0.632390,0.238550,0.105832,-0.273812,0.072279,-0.176084,0.006229,-0.774840,0.047174,-0.406948,-0.144251,0.025391,-0.098251,-0.312340,0.835360,-1.145812,0.285524,0.720448,0.155518,-0.154406,0.848790,0.165141,0.551340,-0.308629,-0.275650,0.257204,-0.317481,0.300071,-0.276378,0.439967,-0.099437,-0.326823,-0.425571,0.686074', '1826173', '26615753', '25880986', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3908423', '夏日大作战', '喜剧', '高中生小矶健二是一个老实内向的数学天才，夏日的一天，他应邀来到美丽的学姐——阵内夏希的家乡打工。结果发现，打工的内容竟是假扮夏希的男友。阵内家祖上曾是与德川军团殊死激战的武士家族，数百年过去，刚硬顽强的性格仍在深深植根于这个家族的灵魂之中。最初的拘谨过后，健二渐渐融入这 个热闹的大家庭。在当时的世界，一个名为“OZ”的网络虚拟平台风靡全球，16亿人为之神魂颠倒。它拥有号称世上最安全的防御系统，但其登录密码无意中被健二所破解。神秘黑客入侵OZ，虚拟网络和现实社会顿时陷入混乱。危急时刻，阵内一家重拾武士家族的责任与荣誉，与破坏者A.I.展开了紧张激烈的夏日大作战……©豆瓣', '神木隆之介', '细田守', 8.5, 172349, 'tt1474276', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1031772057.jpg', 0.4, 1.6, 14, 38.3, 45.7, '0.208294,0.510950,-0.713297,0.690691,-0.102088,0.102348,0.472098,-0.097106,-0.447960,-0.454769,0.270368,0.713823,-0.078425,0.303694,0.315217,-0.100348,0.084746,-0.669126,-0.220427,-0.147634,-0.100663,-0.197814,-0.370133,-0.186171,-0.120549,-0.518062,0.898358,0.411083,-0.286709,0.222265,-0.057364,0.288841,-0.425147,0.234561,-0.106075,-0.146959,0.194529,-0.092412,-0.316491,0.051697,-0.466433,-0.073890,-0.002262,0.283457,-0.040530,0.177081,0.791414,-0.342051,-0.291683,-0.085697,0.620746,-0.122596,-0.604445,-0.070372,0.517629,-0.036882,0.332449,-0.067062,0.167783,-0.136673,-0.198459,-0.162720,-0.841599,-0.168719,0.291576,-0.052222,-0.197919,0.438237,-0.098929,-0.223088,-0.146754,-0.113515,0.081644,0.455384,0.379670,0.442022,-0.208770,0.308428,-0.180006,0.134040,0.409265,-0.069062,-0.637272,0.293772,-0.202498,-0.436254,-0.124447,-0.622361,-0.594368,-0.090036,0.173058,-0.041615,-0.022276,0.449154,-0.899377,0.224380,-0.032929,-0.226507,0.207695,-0.388224,-0.353710,-0.520052,-0.360961,-0.222722,-0.179201,0.282627,0.008989,-0.057072,1.032611,-0.818821,0.117787,0.481375,0.116994,-0.218231,0.610889,0.118120,0.019368,-0.221388,-0.100251,0.274369,0.184874,0.398612,-0.175816,0.319406,-0.300037,0.043317,-0.582737,0.423181', '27602116', '24284209', '25880986', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3914500', '小红帽', '剧情', '在静谧的黑暗森林边缘，有一个不知名的村庄，长久以来，关于狼人的各种传闻在这里广为流传。美丽的少女瓦莱丽（阿曼达•赛弗里德Amanda Seyfried 饰）已到成婚之年，家人把她许配给了村子里有钱人家的儿子亨利（马克斯•艾龙斯 Max Irons 饰），然而瓦莱丽真心爱着的却是与自己青梅竹马的樵夫彼得（希罗•费南德兹Shiloh Fernandez 饰）。为了追求真爱，瓦莱丽和彼得决定私奔。然而正当他们计划逃走之时，狼人出现并杀死了瓦莱丽的妹妹。村民们长久的积怨终于在这一刻爆发，他们决定要铲除威胁村民的狼人。残酷的战斗之后，村民们在一座山洞里杀死了一只巨狼。然而山洞中的巨狼并不是传说中的狼人，真正的狼人其实一直隐藏在村民之中……本片由《暮光之城：暮色》的女导演凯瑟琳•哈德威克（Catherine Hardwicke）执导，惊悚片《孤儿》的编剧大卫•约翰森（David Johnson）负责剧本改编。浓郁的哥特风格和大量的黑暗元素让人对此片印象深刻。', '阿曼达·塞弗里德', '凯瑟琳·哈德威克', 5.7, 53075, 'tt1486185', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p824737315.jpg', 5.1, 25, 51.7, 14.4, 3.7, '0.195067,-0.071005,-0.707952,0.616130,-0.017827,-0.190372,0.946429,-0.005639,-0.502987,-0.436533,0.242151,0.663066,-0.110388,0.030186,0.271482,-0.041601,-0.341290,-0.400038,-0.251339,-0.202865,-0.045777,-0.402486,-0.348048,-0.322086,-0.140303,-0.322417,0.681871,0.329849,-0.046885,0.285680,0.105034,0.254088,-0.211461,0.342049,0.111397,0.004436,0.286131,-0.226342,-0.289458,-0.003785,-0.236830,0.093794,-0.089901,0.172448,0.051960,0.243613,0.729927,-0.599248,0.001822,-0.145859,0.149515,-0.249194,0.110209,0.012533,0.232366,-0.429523,0.476085,0.172561,0.109126,-0.248174,-0.124549,-0.299612,-0.445478,0.081834,0.109856,0.145317,-0.496851,0.503893,0.091790,0.042750,0.092289,-0.205587,0.112173,-0.073132,0.146288,0.261756,0.002777,-0.129306,-0.441105,0.160442,0.677104,-0.136323,-0.194248,0.233131,-0.311656,-0.567365,-0.151058,0.017204,-0.599993,-0.012017,0.513148,0.160538,-0.404045,0.366672,-0.712562,-0.024482,-0.252860,0.000108,0.012502,-0.489254,-0.247582,-0.470283,-0.211907,-0.139130,-0.231192,-0.062042,0.033624,-0.082354,0.609097,-0.839772,0.390642,0.550369,0.273026,-0.150874,0.582530,-0.147202,0.142682,-0.108157,-0.268001,0.354002,0.151171,0.138453,0.148217,0.264994,-0.113575,-0.236074,-0.472286,0.504493', '21619567', '1296534', '3005387', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3914512', '如果的事', '剧情', '在一场热闹的派对上，瓦莱丝（丹尼尔·雷德克里夫 Daniel Radcliffe 饰）和钱特利（佐伊·卡赞 Zoe Kazan 饰）相遇了，四目相交的电光火石之间，两颗心都沦陷了。然而，此时的钱特利已经有了稳定交往的男友阿兰（亚当·德赖弗 Adam Driver 饰），无法割舍这段感情的钱特利和瓦莱丝达成了共识，两人只能做朋友。然而，人的感情哪是这样轻易可以控制的呢？虽然约法三章，但在相处的过程里，这对有情人还是无法抗拒彼此的吸引力而距离越来越近。某日，钱特利告诉瓦莱丝自己要去台湾工作了，面对即将分道扬镳的命中真女，瓦莱丝会做出怎样的选择呢？©豆瓣', '丹尼尔·雷德克里夫', '迈克尔·道斯', 6.7, 5508, 'tt1486834', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2183132298.jpg', 1.2, 9.5, 52.4, 28.4, 8.3, '0.416475,-0.172111,-0.669241,0.286322,0.101173,-0.415426,0.649948,0.297556,-0.207926,-0.129249,-0.092048,0.524617,-0.202263,-0.100706,0.311686,0.010582,-0.349114,-0.882842,0.304338,-0.328839,-0.056996,-0.752167,-0.288804,-0.038083,-0.190633,-0.193327,0.410825,0.202248,0.069636,0.525887,0.382834,0.088969,0.210045,0.461747,0.106459,-0.147588,0.070918,0.157013,-0.463525,0.188611,0.222287,0.158132,-0.189629,0.215540,0.323242,0.617915,0.408786,-0.214132,0.139223,0.340557,0.039336,-0.063150,0.354454,0.196207,-0.035022,-0.113955,0.256315,0.110367,-0.427593,-0.144793,0.227916,0.087946,-0.574273,0.391646,-0.060056,0.080844,-0.569095,0.726223,-0.044355,-0.018335,-0.084589,-0.356438,0.213808,0.494582,0.357608,0.333946,-0.384810,-0.211837,-0.662502,-0.128337,0.868808,0.054314,-0.396696,0.358165,-0.459066,-0.339321,-0.555564,-0.182798,-0.401246,-0.211187,0.416116,0.461594,-0.155116,0.642793,-0.699142,-0.088607,-0.360716,0.175984,-0.025364,-0.652734,0.243654,-0.564645,-0.382033,-0.590716,-0.452322,0.217243,0.146361,-0.266200,0.482140,-0.849755,0.019159,0.585218,0.666515,-0.092040,0.873009,0.485037,0.158547,-0.074059,-0.132572,0.322494,-0.028903,-0.076198,0.330001,0.490023,0.415794,0.189550,-0.273987,0.534542', '1292338', '5327188', '1308755', '4604803');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3914513', '马戏之王', '剧情', '《马戏之王》取材自真人真事，好莱坞全能巨星休·杰克曼在片中饰演“马戏团鼻祖”、传奇人物P.T.巴纳姆。故事讲述了身处社会底层的巴纳姆依靠自己无穷想象力和锲而不舍的精神，从经营博物馆到一手开创世界上第一家马戏团的故事。巴纳姆的奇思妙想最开始并不被大众所认可，几乎没人花钱欣赏，他的家人好友帮他度过一次次绝境。在经历了一系列挫折、与合作伙伴的分歧之后，秉持梦想的他终于成为全美甚至全世界最为知名的“造梦大师”。', '休·杰克曼', '迈克尔·格雷西', 7.7, 182728, 'tt1485796', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2511346392.jpg', 0.5, 2.9, 28.3, 45.9, 22.4, '0.099921,0.063836,-0.768329,0.488342,0.216963,-0.107293,0.344045,-0.081609,-0.689709,-0.362298,0.226370,0.814991,-0.156229,0.068950,0.397632,-0.202079,-0.347605,-0.542381,0.048144,0.002306,-0.258740,-0.230564,-0.309970,-0.191976,-0.379729,-0.424794,0.492140,0.074998,-0.472388,0.008864,0.188722,0.443511,0.089321,0.213043,-0.237259,0.204984,0.369127,0.262959,-0.506239,0.128342,-0.052343,-0.261115,-0.310750,0.239598,-0.142232,-0.174144,0.557321,-0.655371,0.172213,0.064377,0.403778,-0.546722,-0.120158,-0.019650,0.041652,-0.203007,0.485785,0.124332,0.068926,-0.086191,0.067478,-0.346362,-1.036378,-0.454325,0.199474,0.170402,-0.613266,0.284700,0.056927,-0.038896,0.000536,-0.279472,0.143876,-0.001588,0.513337,0.194403,-0.022117,-0.051381,-0.265277,0.543780,0.705709,0.103775,-0.389137,0.517616,-0.321592,-0.484476,-0.332357,-0.352425,-0.604186,-0.043276,0.233051,-0.165860,-0.060423,0.741034,-0.633757,-0.145457,-0.102501,-0.267527,0.154501,-0.521775,0.050536,-0.674230,-0.417726,-0.050823,0.326821,0.045533,0.244483,-0.410454,0.843819,-0.719526,0.174750,0.387392,-0.002092,-0.125617,0.716796,-0.242347,0.115658,-0.449405,-0.191569,0.596402,0.217113,0.148152,-0.180509,0.254619,0.038470,-0.104785,-0.420477,0.828072', '27602116', '1793491', '27098364', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3914547', '乌鸦', '悬疑', '影片虚构了爱伦·坡死前“神秘”的5天里发生的事情。巴尔的摩发生了一件母女同时被害的残忍凶杀案，当地警官艾迈特（卢克·伊万斯 Luke Evans 饰）调查后发现凶手的犯罪手段和爱伦·坡（约翰·库萨克 John Cusack 饰）小说中的手段一模一样。正当爱伦·坡被叫去警局询问时发生了另一件凶手案，手法依旧和参考他的小说。了解到凶手的方法后，艾迈特邀请爱伦·坡担当顾问协助破案。而随着案件的进一步深入，艾迈特发现，爱伦·坡会成为这个残忍杀人凶手的下一个行凶目标。正当大家全力保护爱伦·坡的安全时，岂料凶手竟然绑架了的他情人艾米丽（爱丽丝·伊芙 Alice Eve 饰）。到底谁才是真正的凶手，爱伦·坡是不是能用自己的小说来揭开这场杀人的游戏呢？©豆瓣', '约翰·库萨克', '詹姆斯·麦克特格', 6.6, 14198, 'tt1486192', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1541462454.jpg', 1.1, 8.7, 56.2, 27.6, 6.5, '0.368885,-0.262158,-0.518974,0.662424,0.016559,-0.004429,0.464911,-0.105676,-0.149323,-0.526649,0.267101,0.552646,-0.112043,0.009680,0.175790,0.192905,-0.596434,-0.711067,0.085683,-0.289990,-0.601141,-0.541440,-0.199520,-0.551523,0.192917,0.134599,0.141331,0.184161,-0.212506,0.279273,0.494921,0.599042,-0.324907,0.255670,0.261120,-0.021856,0.460188,-0.067612,-0.393634,0.424937,0.311465,-0.118232,-0.129440,0.254860,-0.100983,0.433310,0.593263,-0.270526,-0.237149,0.027285,0.395043,-0.238852,0.348677,0.069680,0.506101,-0.313588,-0.102428,0.468553,-0.116524,-0.237170,0.113015,0.013190,-0.745299,-0.028128,0.108253,0.121144,-0.182390,-0.247762,-0.221650,0.200853,0.214233,-0.158061,0.227820,0.365086,0.672562,0.051541,0.002497,-0.170187,-0.466452,0.004657,0.431336,0.066065,-0.006500,0.327928,-0.012520,-0.511038,-0.047735,0.015267,-0.110945,0.201097,0.401439,-0.046413,-0.312247,0.287877,-0.292503,-0.349452,-0.472512,0.189815,-0.192669,-0.209631,-0.192344,-0.498577,-0.190791,-0.076168,-0.088197,-0.150246,-0.079777,-0.501597,0.184693,-0.423291,0.186195,0.675550,0.043628,-0.363961,0.362433,0.054299,-0.061044,-0.062922,-0.312021,0.135825,0.356447,0.405461,0.049560,0.188187,0.385680,-0.325903,-0.207514,0.336516', '2988294', '1307442', '1297547', '1293936');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3915458', '海贼王剧场版10：强者天下', '动画', '在一个风和日丽的日子，草帽海贼团正悠闲地在海上航行。突然，天空中出现一个漂浮的小岛，娜美及时通知各位规避即将到来的龙卷风，她的能力引起了小岛上海贼的注意。这个海贼首领非同寻常，他名叫金狮子史基，在大海贼时代到来前曾和哥鲁德•罗杰拼杀争霸。罗杰被俘后，史基也被投入海底监狱，但他却斩断双脚逃亡，并决心向东海展开复仇。史基意欲拉娜美入伙，双方不可避免发生纷争，经过一波三折，娜美最终落入史基手中。为了救出伙伴，并阻止东海毁灭计划，草帽海贼团将和史上最强大的敌人展开对决……本片根据尾田荣一郎同名原著改编，系《海贼王》的第十部剧场版动画，尾田荣一郎亲自担任制作总指挥。©豆瓣', '田中真弓', '境宗久', 8.7, 27035, 'tt1485763', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2203803601.jpg', 0.3, 1, 12.2, 37.4, 49.1, '-0.071303,0.074750,-0.508395,0.418644,0.555332,0.019456,0.581307,0.097688,0.029380,-0.251905,0.203334,0.573840,-0.073962,0.139292,0.354456,0.040090,-0.477946,-0.576424,-0.166385,0.271482,-0.086921,-0.314379,-0.467792,0.120632,-0.010089,-0.282077,0.820616,0.082787,-0.233410,0.726789,0.431549,0.166693,-0.470169,0.520893,-0.095883,-0.035770,0.101035,-0.116447,-0.331793,0.181859,-0.383267,-0.177882,0.012796,0.066398,0.180770,0.146693,0.830544,-0.502792,-0.004917,-0.293159,0.264916,-0.496352,0.171001,0.011950,0.622581,-0.116020,-0.426033,0.187727,0.089594,-0.120820,-0.050301,-0.340861,-0.570569,0.250136,0.054871,0.017427,-0.282554,-0.087586,-0.010968,0.195427,0.276969,-0.068085,0.083144,0.385901,0.487934,-0.243256,-0.095059,0.303516,-0.373506,0.147344,0.623536,-0.215689,-0.110923,0.038450,0.257726,-0.296508,-0.339338,-0.202662,-0.073750,-0.022769,0.508942,0.085828,-0.033678,0.254952,-0.673240,-0.026684,-0.420601,-0.328954,0.065555,-0.193961,-0.303576,-0.843742,-0.052772,-0.024202,-0.121332,0.141896,-0.108015,-0.184322,0.467326,-0.441159,0.163915,0.680829,0.087516,-0.074668,0.503392,0.226253,0.163989,-0.285225,-0.068776,0.382490,0.293877,0.286564,0.029177,0.080677,-0.015315,-0.176917,-0.328356,0.242479', '20274039', '24879819', '2159244', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3927734', '乐高大电影', '喜剧', '艾米特（克里斯·帕拉特 Chris Pratt 配音）是乐高世界中一个普通到没有存在感的建筑师，他每天精神饱满，乐观向上，按照说明书的指示从事一天的活动。某天收工后，他意外掉入一个深洞，后背还黏了奇怪的东西，随后就被兼具凶暴和善良两面的警察（利亚姆·尼森 Liam Neeson 配音）带走问话。原来统治乐高世界的生意王（威尔·法瑞尔 Will Ferrell 配音）对那些极富创造力的小人极为不满，他讨厌不同系列的乐高世界相互交叉，更讨厌脱离了说明书独辟蹊径的发明创造。因此他将所有世界隔开，囚禁了那些创意大师，还策划着一场可怕的阴谋。艾米特危机时刻被露西（伊丽莎白·班克斯 Elizabeth Banks 配音）救下，并被先知维特鲁维斯（摩根·弗里曼 Morgan Freeman 配音）认定为救世主。暴风雨般的迫害袭向创意大师们，想象力贫乏的艾米特能否担此重任？', '克里斯·帕拉特', '菲尔·罗德', 7.9, 58944, 'tt1490017', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2158676090.jpg', 0.6, 2.4, 22.9, 47.7, 26.4, '0.325238,0.133801,-0.637095,0.470560,-0.114472,-0.164518,0.680727,0.062673,-0.235611,-0.370632,-0.040685,0.487405,-0.400013,-0.065390,0.267168,0.174729,-0.215510,-0.535837,-0.289492,-0.040696,-0.280594,-0.526296,-0.287304,-0.492646,-0.165164,-0.548120,0.337798,0.074178,-0.354656,0.026372,0.252577,0.363687,0.042218,0.407389,-0.064522,-0.043573,0.331800,-0.196642,-0.110373,0.243148,0.033052,0.214347,-0.062890,0.375576,-0.215964,0.107751,0.485991,-0.479890,-0.090289,-0.139953,0.383176,-0.299505,0.136893,0.114768,0.307492,-0.210881,-0.166020,-0.002357,0.082138,0.084537,0.236714,-0.237091,-0.826067,-0.212816,-0.051661,0.107690,-0.401997,-0.035343,-0.124592,0.006539,-0.095500,-0.297983,0.093084,0.021458,0.611690,0.405177,0.125861,0.143709,-0.114291,0.113308,0.375173,0.182850,-0.545776,0.269315,-0.574117,-0.360472,-0.084048,0.004974,-0.515448,-0.149023,0.500891,-0.201401,0.169715,0.296987,-0.600572,0.003818,-0.235395,-0.140271,-0.222463,-0.343037,0.009204,-0.649986,-0.030096,-0.049420,-0.115386,-0.090502,0.100594,-0.209179,0.549167,-0.579861,0.405178,0.572581,0.208948,0.013649,0.415841,-0.003897,-0.156744,-0.284582,-0.177564,0.313602,0.236198,0.027860,0.138295,0.443995,0.177304,-0.134549,-0.287282,0.668787', '3769423'