INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3927736', '高材生', '喜剧', '讲述一对好友、两个学术天才和一群朋友在高中毕业前夕意识到她们应该少学习而多玩，为了不落后同龄人，她们开始了一项任务：将4年的快乐时光填满一个晚上。', '比妮·费尔德斯坦', '奥利维亚·王尔德', 7.1, 20898, 'tt1489887', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2557679669.jpg', 1.3, 6.3, 40.7, 38.6, 13, '0.524859,-0.228887,-0.380270,0.641962,-0.453237,-0.282472,0.626567,-0.184458,-0.275489,-0.628375,-0.186157,0.793789,-0.267694,0.548340,0.290881,-0.461698,-0.131715,-0.611310,0.388845,-0.398258,-0.294034,-0.502517,0.390859,-0.390589,-0.331419,-0.270471,0.534771,-0.163078,0.311333,0.686777,-0.024516,-0.405078,-0.161177,0.136879,-0.163202,-0.388188,0.510781,0.428852,-0.255535,0.339638,-0.073396,0.148290,-0.194687,-0.132619,0.244993,-0.376659,0.996498,0.236086,-0.270586,-0.031696,0.319630,-0.347861,-0.459422,-0.057926,0.442375,0.181902,0.418946,0.284667,0.027363,0.288837,-0.407550,-0.561026,-0.538878,0.152075,0.057671,-0.158364,-0.402727,0.774918,0.224837,-0.092580,-0.044542,-0.517814,0.139345,0.747968,0.108459,0.535020,-0.169779,-0.066146,-0.336063,0.524066,1.330418,-0.575289,0.081735,0.815888,0.154355,-0.199811,-0.091614,-0.131044,-0.240405,0.076580,0.066144,-0.103672,-0.447128,0.557769,-0.826028,0.331618,0.101428,-0.342845,0.273529,-0.811190,-0.013865,-0.260621,-0.249484,-0.411598,-0.389152,0.438903,0.245021,-0.583778,1.516943,-0.916112,0.161421,0.747745,0.128612,-0.612813,0.890228,0.159463,0.321889,-0.624904,0.372306,-0.021235,0.089013,-0.058596,0.030824,0.408240,-0.601617,0.145525,-0.606569,0.353996', '26790961', '1307741', '3811356', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3927749', '乌龙特工', '喜剧', '会计师卡尔文（凯文·哈特 Kevin Hart 饰）在高中时代曾是学校的体育明星，他热心张罗高中同学聚会，于是在Facebook上联系到了老同学鲍勃（道恩·强森 Dwayne Johnson 饰），他没想到这个在高中时常受欺负的老同学现在已经是CIA的职业杀手，而他也万万没想到自己将被卷入制止军事秘密泄露的任务中。', '道恩·强森', '罗森·马歇尔·瑟伯', 6.4, 32140, 'tt1489889', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2286630113.jpg', 1.7, 13.3, 55.7, 22.1, 7.2, '0.547715,-0.009034,-0.821309,0.551463,-0.475472,-0.245678,0.477222,-0.043616,-0.719046,-0.127852,0.275607,0.921009,-0.374703,0.456498,0.369256,0.038925,0.018200,-0.757715,0.241341,-0.292729,-0.434361,-0.650729,-0.230941,0.011342,-0.107750,-0.297415,0.243700,-0.171753,-0.284014,0.538443,0.319608,0.265223,0.095362,0.756858,-0.279886,0.146721,0.289216,0.113048,0.154930,0.097891,0.267124,-0.560005,-0.210155,0.171239,0.374065,0.626826,0.400644,0.175415,-0.151997,0.148975,0.321316,-0.512900,0.091357,0.040344,0.526787,-0.159371,0.035854,0.223963,-0.238426,0.157045,0.159339,-0.094207,-0.422430,0.041236,0.143815,0.064460,-0.839840,0.502648,-0.106023,-0.051683,-0.101285,-0.259830,0.134894,0.469431,-0.102734,0.198164,0.132235,0.194110,-0.392145,0.317184,0.652656,-0.309612,-0.151329,0.165507,-0.107236,-0.102174,-0.096619,-0.165216,-0.647379,0.025032,0.135364,-0.319782,-0.281352,0.121519,-0.462172,-0.302417,-0.052691,-0.059312,-0.037841,-0.405433,-0.034153,-0.408420,-0.273808,-0.267125,-0.678127,0.086480,0.023044,-0.270496,0.556734,-1.176708,0.101208,0.674337,0.349712,-0.317229,0.816966,0.321533,0.029539,-0.179919,0.020058,-0.056313,0.311863,0.439817,0.191704,0.493700,0.344539,-0.567334,-0.290819,0.381385', '1302384', '22964524', '35030151', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3927750', '两男变错身', '喜剧', '本片是导演大卫·道金、《宿醉》编剧乔恩·卢卡斯联合制作的最新喜剧作品。整部影片的拍摄周期只用了62天，在英国的片名叫做《与孩子见面》。Dave（杰森·贝特曼 Jason Bateman 饰）是一位成功的家庭男人，有可爱的孩子 和迷人的老婆（莱斯利·曼恩 Leslie Mann 饰），每日埋头工作，照顾家庭。而长相英俊的Mitch（瑞恩·雷诺兹 Ryan Reynolds 饰）则是一个花花公子，夜夜笙歌与姑娘们鬼混。两人渐渐对自己现有的生活感觉厌倦，想尝试下彼此的生活。两人对着喷泉里“女神”讲出了“我想要你的生活”的愿望。怎料第二天愿望就在这样实现了。藏在Mitch的Dave能和性感的Sabrina（奥利维亚·维尔德 Olivia Wilde 饰）约会，而藏在Dave身体里的Mitch只好目睹他美貌老婆却什么都不能做……©豆瓣', '瑞安·雷诺兹', '大卫·道金', 6.8, 37448, 'tt1488555', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p958822792.jpg', 0.9, 7.4, 52.8, 30.8, 8, '0.015004,-0.186447,-0.547877,0.656193,-0.149101,-0.362856,0.779487,0.188767,-0.320583,-0.067787,0.136385,0.795443,-0.346437,0.367095,0.235085,0.210823,-0.462126,-0.755844,-0.024117,0.058841,-0.070307,-0.336867,-0.267423,-0.248872,-0.008787,-0.317050,0.607334,-0.154315,-0.060369,0.124322,0.369460,0.066058,-0.012603,0.251685,-0.388124,-0.082115,-0.017455,-0.056854,-0.287992,0.308517,0.184496,-0.094602,-0.215758,0.030923,0.118281,0.194244,0.696955,-0.326919,-0.065164,0.113859,0.296567,-0.080915,-0.013226,0.110858,-0.055388,-0.198581,0.360749,0.138807,-0.232260,-0.094420,0.120542,-0.198956,-0.804821,0.029990,0.107737,0.199014,-0.548529,0.476731,-0.182326,-0.113094,0.283636,-0.372061,0.161524,0.218302,0.184599,0.521695,0.015858,0.160805,-0.482830,0.486053,0.468980,0.216437,-0.270877,0.703626,-0.392436,-0.286368,-0.302387,-0.084418,-0.771614,-0.065653,0.107858,-0.079945,-0.146441,0.074396,-0.572674,0.169004,-0.140029,-0.136109,0.031355,-0.452961,-0.037495,-0.661554,-0.213212,-0.532018,-0.303374,-0.017713,0.106527,-0.237541,0.920658,-0.897150,0.002911,0.461223,0.331660,-0.421044,0.911525,0.368019,0.000337,-0.132737,-0.011572,0.145945,-0.298611,-0.025520,0.189446,0.588884,0.079004,0.064201,-0.427452,0.581589', '3230462', '30162520', '3811356', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3928370', '越光宝盒', '喜剧', '个性莽撞的玫瑰仙子（孙俪 饰）渴望能够像紫霞仙子一样找到一世珍爱，于是从日月神灯前盗取那把曾见证旷古爱恋的紫青宝剑来到凡间，希望找到能拔剑出鞘的真命天子。山贼清一色（郑中基 饰）只想本本份份做个山贼，不料却拔出玫瑰仙子的紫青宝剑，之后俩人又意外通过越光宝盒穿越时空，亲历赤壁之战。在穿越的日子里，玫瑰仙子对于拔剑出鞘的清一色百般示爱，而一心想重新踏上穿越时空之路的清一色却对玫瑰仙子只是假意奉承，在利用玫瑰仙子从曹操（郭德纲 饰）手里夺回越光宝盒之后，他毅然弃玫瑰仙子于不顾，独自回到曾经。然而再次偶到玫瑰仙子之时，清一色却发现有一份爱早已在自己的心头生根发芽……本片借经典影片《月光宝盒》之东风，58位明星倾情加盟，并重新演绎近年来多部影片中的精彩片段，“笑果”非比寻常。©豆瓣', '孙俪', '刘镇伟', 5.3, 156369, 'tt1612143', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p798688444.jpg', 14.1, 29.1, 39.2, 12.6, 5, '0.024987,0.487583,-0.496606,0.574698,0.084772,-0.233322,0.583011,-0.177541,-0.399454,0.074743,0.286315,0.520937,-0.242772,0.067874,0.369428,0.139553,0.104141,-0.757894,-0.095424,-0.273173,0.193093,0.034545,-0.342291,0.320181,-0.258775,-0.506251,0.765495,-0.007218,0.172825,0.631645,0.325218,-0.014510,-0.412851,0.218560,-0.232632,-0.104772,-0.210110,0.443336,-0.712676,0.528775,0.009135,-0.283130,-0.094771,0.047072,-0.174286,0.046959,0.586157,-0.610700,0.042415,-0.038694,0.472731,0.168296,0.001478,0.036892,-0.055452,0.210679,0.143431,-0.172653,-0.296541,0.125958,0.218047,-0.419066,-0.211001,-0.172890,0.303063,0.202203,-0.565710,0.075982,-0.236395,0.255416,0.189707,-0.339878,0.244794,-0.188604,0.531493,0.204235,-0.115284,-0.364486,-0.435584,0.613787,0.479366,0.018540,0.011264,0.511538,0.110849,-0.158405,-0.023909,0.158194,-0.288159,0.171767,0.557294,0.190414,0.137750,0.151587,-0.549503,0.095557,-0.189483,0.360507,0.260349,-0.500104,-0.180163,-0.294095,0.060188,0.024704,-0.052842,0.069214,0.281970,-0.297472,0.722207,-0.821260,0.444289,0.107580,0.000289,-0.212323,0.415423,-0.014829,-0.300317,-0.111898,-0.199964,0.595041,0.238724,0.501103,-0.208966,0.299563,-0.231762,-0.252541,-0.367251,-0.043475', '4127270', '26784898', '30345227', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3929374', '雪场女孩', '喜剧', '19岁的女孩金（菲丽希缇·琼斯 Felicity Jones 饰）热爱滑板并是前滑板冠军，然而在一次意外中她的母亲不幸逝世，金不得不放弃滑板，开始打工帮助父亲补贴家用。一次偶然的机会，金的朋友介绍她到阿尔卑斯山的一个滑雪场工作，因为之前的员工摔断了腿，金勉强答应。然而从未接触过滑雪的金似乎与周围一切格格不入，无聊之余，她开始在屋外自学滑板，米基（肯·杜肯 Ken Duken 饰）看到后便主动教其滑雪，并发现了金的惊人天赋，遂推荐她参加比赛，金果然不负所望拿下了冠军和奖金。就在大家都觉得金会在滑雪的路上再创佳绩之时，金却发现自己每次跳跃都会想起母亲的车祸，这个心理阴影总是她滑雪的障碍，而与约翰尼（爱德·维斯特维克 Ed Westwick 饰）刚刚萌芽的爱情也被对方母亲坚决反对，众多烦恼使金萌生了离开此地回家的想法，就在此时，她的爸爸却以过世母亲的期望劝其留下来再尝试一次比赛。金能否在这次竞赛中克服障碍，赢得自己呢？', '菲丽希缇·琼斯', '菲尔·特雷尔', 6.8, 6059, 'tt1487118', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1212034103.jpg', 0.9, 6.9, 52.3, 31.2, 8.6, '-0.184091,0.171675,-0.911073,0.524840,-0.007173,-0.597844,0.466869,-0.102614,-0.460348,-0.299793,-0.031996,0.704913,-0.133770,0.399492,0.321847,-0.274034,-0.204567,-0.556012,0.171300,0.021058,-0.510961,-0.376975,-0.100674,-0.121669,-0.280651,-0.233587,0.346784,0.197083,-0.307225,0.696222,0.406180,0.013548,0.159870,0.636149,0.041523,-0.195785,0.017112,0.488308,-0.152030,0.121152,0.157399,-0.315210,-0.208865,0.262713,0.365706,0.357553,0.634571,-0.252028,-0.219244,-0.019666,0.246352,-0.020261,0.298917,-0.009746,0.069573,0.129852,0.191424,0.083960,-0.122135,0.117445,-0.023682,-0.133086,-0.434073,0.029815,-0.112556,-0.055352,-0.666804,0.403353,0.100690,0.131183,-0.049040,-0.330061,-0.192505,0.316279,0.207341,0.047699,-0.453637,-0.015359,-0.308258,0.293022,0.608174,0.018437,-0.185308,0.407582,-0.065034,-0.505133,-0.001069,0.103156,-0.319534,0.200144,0.449709,0.245398,-0.013552,0.145711,-0.553852,-0.147992,-0.253671,-0.039721,0.037546,-0.190723,0.114473,-0.329000,0.293273,-0.121409,-0.558478,0.099540,-0.075610,-0.409978,0.452366,-0.870271,0.405320,0.498565,0.395798,-0.500148,0.556246,0.139106,0.170159,-0.217888,-0.102222,0.298211,-0.108012,0.306882,0.089398,0.224306,0.133096,-0.246151,-0.5134