INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3929463', '宇宙英雄之超银河传说', '动作', '最强战士贝利奥斯因为渴望人工太阳火炬的力量而坠入黑暗，但他的叛乱最终被奥特之王平定，并被打进宇宙监狱……多年以后，被扎布拉星人救出的贝利奥斯重回光之国，打败了众奥特战士，成功夺走人工太阳火炬并到怪兽墓场去。失去了火炬的奥特之星瞬间冻结，成功逃离的就只有梦比优斯、初代和赛文。此时，盘龙号在特顿星遭遇怪兽的袭击。在雷将怪兽消灭后，梦比优斯把雷带走，并向他求救。两人与初代、塞文会合后，便一同前往怪兽墓场……其后，盘龙号再次遭受怪兽袭击，而此次被戴拿出手相救。在杰顿星人口中得知奥特之星的灾难后，盘龙号也飞往怪兽墓场……另一方面，在K76行星接受雷欧兄弟特训的赛文之子·ZERO在听闻奥特之星的危机后，也动身到怪兽墓场……', '南翔太', '坂本浩一', 7.8, 10734, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2212140210.jpg', 1.2, 3.9, 27.7, 38.2, 29, '0.017503,0.283479,-0.910306,0.405239,0.432611,-0.154153,0.796778,-0.092620,-0.087225,-0.021469,0.208457,0.679829,-0.193634,0.073982,0.532557,-0.032865,-0.116046,-0.330354,0.009683,-0.138520,-0.523585,-0.389346,-0.210894,-0.051774,0.194321,-0.770386,0.841043,0.351852,0.040336,0.326593,-0.162528,0.493915,-0.125907,0.484486,-0.044335,0.104761,-0.090984,-0.091708,-0.103133,0.719221,-0.219888,-0.101918,0.025146,0.473354,0.067455,0.093762,0.689519,-0.808310,0.510848,-0.363988,0.049934,-0.437132,0.010571,0.115402,0.610125,-0.279314,-0.434854,-0.144138,0.007167,0.192042,0.145732,-0.286511,-0.541681,-0.137610,-0.159812,0.004080,-0.705403,0.309540,0.198212,0.344508,0.224526,-0.095714,0.232946,0.308830,0.107048,0.274440,-0.151111,0.082894,-0.421789,-0.174989,0.789981,-0.369352,-0.345442,-0.221873,0.086523,-0.623375,-0.369158,-0.077198,-0.131312,-0.054782,0.942885,0.400299,-0.084510,0.593771,-0.899710,-0.202319,-0.549748,-0.324713,-0.059555,-0.271661,0.044158,-0.783146,0.198780,0.102940,0.013201,0.466652,0.121000,-0.178850,0.280331,-0.655845,0.680984,0.551034,0.423766,-0.107209,0.514205,-0.335377,0.148123,-0.208885,0.242026,0.580676,0.804228,0.705985,0.394672,-0.042864,-0.138590,-0.046706,-0.208741,0.286994', '3011051', '1856675', '1298586', '3610047');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3986152', '同栖生活', '剧情', '位于东京某公寓的单元内，居住着四个年轻人，他们是迷恋前辈女友的大学生杉本良介（小出恵介 饰）、深爱着作为演员男友的无业女大河内琴美（贯地谷しほり 饰）、一心想成为插画师的相马未来（香里奈 饰）以及终日为工作奔波忙碌的电影公司职员伊原直辉（藤原竜也 饰）。他们性格各异，倒 也情投意合，生活波澜不惊。某天，一个年仅18岁的男妓小悟（林遣都 饰）闯入他们的世界，表面平静和谐的生活就此失衡。与此同时，隔壁的神秘邻居以及附近不断发生的行凶事件也令这个充满躁动的世界进一步崩塌……本片根据吉田修一的同名原著改编，并荣获第60届柏林电影节国际影评人费比西奖。©豆瓣', '藤原龙也', '行定勋', 7.7, 7235, 'tt1493070', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p564006141.jpg', 0.6, 2.3, 27.8, 52.1, 17.3, '-0.042985,-0.040859,-0.438324,0.367642,0.169841,-0.065919,0.568410,0.333430,-0.235008,-0.447474,0.244028,0.673140,-0.321152,0.342715,0.460841,-0.084813,-0.165919,-0.545331,-0.171865,-0.115385,0.264965,-0.168133,-0.177143,-0.135082,-0.188199,-0.331546,0.689966,0.126254,-0.120780,0.479664,0.405972,0.411880,-0.318217,0.153396,0.120471,-0.016199,0.242629,0.205834,-0.221164,0.062414,-0.420825,0.091305,0.093239,-0.174624,0.020118,0.335090,0.699385,-0.103210,-0.277182,-0.043478,0.540837,0.081278,-0.465991,-0.037192,0.539821,-0.092868,0.095891,0.276739,-0.224503,0.157876,-0.018461,-0.153427,-0.502806,-0.107766,0.314412,0.115148,-0.261685,0.409135,0.162561,-0.237053,-0.051680,0.013914,0.130595,0.270571,0.410013,0.229972,-0.100111,0.307529,-0.057191,0.246132,0.322845,0.290014,-0.266679,0.216141,-0.401251,-0.442758,-0.108743,-0.154574,-0.522982,-0.015547,-0.116796,-0.198369,0.101039,0.129268,-0.359867,0.019055,0.082114,-0.295516,0.291480,-0.215988,-0.122536,-0.778456,0.003664,-0.332976,-0.113445,-0.080490,0.224287,-0.198561,0.805828,-0.735554,0.051417,0.426752,0.225256,-0.315930,0.657121,0.109012,-0.075506,-0.247906,-0.408172,0.331133,-0.093442,0.353604,-0.365220,0.352054,-0.244652,-0.311133,-0.328870,0.251999', '3811356', '1322847', '25922902', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3987383', '惊天动地', '剧情', '2008年5月12日，我国四川省发生特大地震。刚演习归来的某集团军摩步旅在返回营区途中，因与上级通讯中断，旅长唐新生（侯勇 饰）果断命令部队赴灾区救援。此时，十万大军响应中央号召，已从四面八方赶往灾区，其中就有唐的妻子军医魏霁虹（童蕾 饰）。灾区映川此刻变成人间地狱，县委书记仼玥（岳红 饰）顾不上家中年迈的母亲（宋春丽 饰），带领众人冲在救人第一线。原准备结婚的教师齐红玉（王嘉 饰）不知未婚夫张向川（徐箭 饰）的生死，坚强地带学生互救自救。她不知道张向川此时正在前往灾区的路上。救援工作异常艰难，加之阴雨连连，在大家感到万分无助的时候，援军赶来了，唐新生在救援的队伍里看到了妻子的身影……©豆瓣', '侯勇', '王珈', 6.9, 4878, 'tt1849786', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2874447310.jpg', 6.2, 10, 36.3, 27.4, 20.1, '-0.036360,-0.050513,-0.835462,0.164933,0.336409,0.051294,0.240878,0.148552,-0.622568,-0.314241,0.124776,0.288397,0.034333,0.139053,0.478788,-0.516572,-0.293299,-0.516240,-0.438875,-0.029694,-0.305407,-0.184028,0.047078,-0.282147,0.047994,-0.295332,0.513837,0.357711,0.215062,0.780210,0.197767,0.353915,-0.201671,0.685590,0.072531,-0.017609,0.123009,0.165809,-0.259288,0.191646,-0.136607,-0.328830,-0.220584,-0.033081,0.133165,0.464263,0.577853,-0.210599,0.118331,-0.116193,0.264254,-0.249234,0.245418,-0.026750,0.537131,0.135072,-0.055527,-0.194288,-0.104486,0.087382,-0.169746,-0.177179,0.055045,-0.048486,0.115601,0.303185,-0.672454,0.042530,-0.299630,0.267889,0.403055,-0.606964,0.259396,0.735706,-0.105521,0.221839,-0.163210,-0.106671,-0.385303,0.313890,0.735735,0.004978,0.135980,-0.221919,-0.182567,-0.531192,0.285182,0.089814,-0.462528,0.004567,0.081103,0.083060,0.196055,-0.035210,-0.102213,-0.089789,-0.157315,-0.245384,-0.231520,-0.011803,-0.212733,-0.759245,0.299002,0.005407,0.037509,0.409642,-0.066588,0.272873,0.493348,-0.713329,0.097263,0.010546,0.296236,-0.457506,0.518144,-0.014867,0.134774,-0.333817,0.394292,0.260830,-0.114352,0.587077,0.101397,0.127132,-0.519179,-0.178007,-0.232396,0.041997', '1451563', '1419918', '1302987', '25856453');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3988857', '正义联盟：两个地球的危机', '动作', '平行宇宙中，任何事情都可能发生，即使是拥有同一个名字同一种能力的人，他们也可能分出善恶两面，甚至更复杂的特性。在我们熟悉的地球空间中，正义联盟的伙伴们超人（Mark Harmon 配音）、蝙蝠侠（William Baldwin 配音）、闪电侠、绿灯侠相互砥砺合作，共同维护这个世界的和平。而就在平凡的一个早晨，看起来有些不同寻常的莱克斯·卢瑟（Chris Noth 配音）突然出现在闹市中央。这个卢瑟来自于另一个平行世界，在那个世界里，他和小丑作为正义战士出现，但是不久前他遭到了邪恶超人、闪电侠等组成的罪恶集团的残酷打击。侥幸逃到这个世界的卢瑟，只有求助于熟悉而又陌生的正义联盟……©豆瓣', 'Mark Harmon', '刘山姆', 7.6, 8683, 'tt1494772', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2227929985.jpg', 0.3, 1.9, 33.6, 46.9, 17.3, '0.430569,0.323059,-0.866090,0.694032,-0.209102,0.149892,0.789318,0.007124,-0.393743,-0.267976,0.237133,1.003614,0.146216,0.186281,0.183168,-0.153175,-0.086900,-0.583422,-0.007463,-0.339951,-0.401246,-0.550107,-0.604754,-0.368700,-0.017623,-0.199493,0.723240,0.215111,-0.349798,0.256345,0.389104,0.173336,-0.472163,0.640929,-0.185044,-0.199180,0.116464,0.144149,-0.445992,0.027056,-0.297189,0.335253,0.044282,0.315394,-0.620809,0.352096,0.423956,-0.633754,-0.293820,-0.091907,0.619912,-0.303835,-0.396338,-0.084322,0.446256,-0.114520,0.007988,0.010129,0.273798,0.123382,-0.198955,0.173151,-1.132906,0.066698,0.122366,0.490805,-0.224994,0.548313,0.239048,-0.414539,0.095320,0.049787,0.324153,0.318467,0.718327,0.399119,-0.177379,0.051060,-0.323020,-0.101787,0.729731,0.049257,-0.854264,0.295145,-0.327861,-0.503789,-0.346231,-0.227956,-0.594997,-0.203143,0.074849,-0.051089,-0.051612,0.284954,-0.994493,0.463942,0.078815,0.135936,-0.181851,-0.426075,-0.054538,-0.549393,-0.161889,-0.407175,-0.170017,0.354274,0.123220,-0.359318,0.895021,-1.019988,0.158349,0.612093,0.474990,-0.586076,0.797260,0.269025,0.181097,-0.548214,-0.247751,0.498058,0.110820,0.280206,-0.320489,0.282761,0.057755,0.254153,-0.392063,0.551282', '24284209', '1874704', '3769423', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3990098', '黑夜传说4：觉醒', '动作', '终于有一天，人类向日渐增多的血族和狼族宣战，这两个族群遭到大肆围剿与屠杀，人类取得绝对的优势。塞琳娜（凯特·贝金赛尔 Kate Beckinsale 饰）和约翰也在这场浩劫中遭难，当她再次醒来时，却发现自己被名为抗原研究所的机构囚禁起来，编号实验品1号。她奋力突破了束缚，根据共视的能力在黑暗的都市中寻找实验品2号——约翰。途中她遭遇血族的同伴相助以及狼人的袭击，当她找到被狼人们追逐的实验品2号时却发现，眼前竟是一个从没见过面但有着极为恐怖力量的小女孩——伊薇（英迪娅·埃斯利 India Eisley 饰），而她是血族与狼族的混血儿。在这个陌生的时代，塞琳娜注定继续过着血雨腥风的生活……©豆瓣', '凯特·贝金赛尔', '曼斯·马林德', 6.7, 50403, 'tt1496025', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1513813303.jpg', 1.2, 9.2, 52.1, 28.4, 9, '0.258832,0.289758,-0.589419,0.622252,0.006069,-0.192147,0.906231,-0.189152,-0.430945,-0.268848,0.281667,0.582437,0.047816,0.271956,0.254889,-0.130370,-0.202170,-0.523767,-0.027548,-0.088087,-0.401157,-0.149795,-0.698862,-0.036982,0.007801,-0.680916,0.776352,-0.091203,-0.413975,0.362231,0.205391,0.385364,-0.198763,0.636917,-0.200058,0.027720,0.270407,-0.079358,-0.172571,0.364096,-0.243510,-0.123634,-0.213302,0.186721,-0.299134,0.292365,0.722727,-0.676339,-0.015568,-0.562308,0.248466,-0.428712,-0.178729,0.216641,0.565939,-0.047558,-0.038432,0.121585,0.041904,-0.029816,0.062523,0.115826,-0.897432,0.005661,0.150843,0.244775,-0.485411,0.382964,-0.040515,0.096257,0.047565,-0.151195,0.064763,0.526086,0.195987,0.267222,-0.150455,-0.103600,-0.762463,-0.119679,0.689441,-0.061758,-0.496812,0.116190,-0.142244,-0.714654,-0.031132,-0.261696,-0.427734,-0.130841,0.405898,0.138887,-0.284114,0.532652,-1.072115,0.132593,-0.422941,-0.381231,0.035154,-0.328880,-0.182344,-0.758636,-0.246395,-0.418785,-0.279029,0.230221,-0.072914,-0.276923,0.672145,-0.836142,0.306132,0.650329,0.386825,-0.180396,0.566580,0.008750,0.151887,-0.130042,-0.223301,0.424738,0.267294,0.272470,-0.006490,0.146188,-0.016532,0.020457,-0.309338,0.718181', '26290398', '25774050', '1578502', '1308784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3990500', '机器侠', '喜剧', '公元2046年，科技发展之下，为人类服务的机器人已经非常普遍，智能机器人K-1（方力申 饰）被秘密派到小镇协同人类执行警务，受警察队长徐大春（胡军 饰）监管。化名“德明”的K-1外表不凡，风流倜傥，内置程序支持完美社交模式，很快赢得小镇女人的欢心，女警素梅（孙俪 饰）也对他芳心暗许，惹得暗恋素梅的大春大吃飞醋。两人明争暗斗正欢，那边厢体内程序出现偏差的机器人K-88（吴京 饰）到处惹祸，德明和大春联手前去缉拿，大战七十二回合之后，K-88一番“机器人也要自由”的理论撼动了德明，不明真相的素梅也唤起德明内心只有人类才有的爱……©豆瓣', '孙俪', '刘镇伟', 5.3, 42619, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1507616164.jpg', 14, 29.3, 38.8, 12.8, 5, '-0.070731,0.107150,-0.565877,0.421711,-0.264233,0.026444,0.176111,0.091835,-0.409047,-0.031568,0.219909,0.290012,-0.382906,-0.113947,0.225032,-0.222753,-0.152869,-0.398651,0.003019,-0.051914,-0.178911,-0.158502,0.036983,-0.447689,-0.234313,-0.500192,0.573473,-0.151487,-0.113895,0.263314,0.136814,0.248609,-0.103998,0.243684,-0.028908,-0.093462,0.086684,-0.287948,-0.266387,0.072329,-0.267619,-0.014396,0.065860,0.003463,-0.235886,0.103379,0.657652,-0.317019,-0.183079,-0.271555,0.205611,-0.046361,-0.031157,-0.214496,0.524564,-0.015055,0.044681,0.109563,-0.060397,0.212224,0.047943,-0.057166,-0.487162,-0.160405,0.273764,-0.114295,-0.211495,0.251670,-0.313464,-0.043003,-0.086508,-0.179258,-0.033909,0.243490,0.510991,0.383654,-0.023855,0.072824,-0.452583,0.077135,0.327615,0.170096,-0.331244,0.254970,-0.279107,-0.523807,-0.114592,-0.575220,-0.227088,-0.014241,0.060235,-0.042795,-0.034074,0.201945,-0.611602,0.181579,-0.148726,-0.027001,0.038138,-0.492294,0.064350,-0.692893,-0.306968,-0.567724,-0.205302,0.022412,0.225700,-0.110272,0.857904,-0.750830,-0.043150,0.355694,0.283215,-0.612347,0.480213,0.116734,-0.170538,-0.358004,-0.196963,0.010716,0.100198,0.303850,-0.025567,0.291927,-0.138615,-0.328971,-0.281955,0.151708', '25863940', '10174444', '25922902', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3992381', '不可饶恕', '惊悚', '最近，城市里发生了可怕的杀人事件，一具被切割成6块的女尸的曝光和凶手的逍遥法外引起了社会的恐慌。作为休假的交换条件，搜查科研究员姜民浩（薛景求 饰）接下了这个棘手的案件。行事雷厉风行的他和推理天才闵瑞英（韩惠珍 饰）联手，调查取得了突飞猛进的进展，嫌疑人李圣浩（ 柳承范 饰）的名字渐渐浮出水面。李圣浩一经逮捕就对自己所犯的罪行供认不讳，可是姜民浩却发现事实并不是他所说的那么简单。就在这个节骨眼上，姜民浩的女儿突然失踪，他明白这绝对和李圣浩脱不了干系。李圣浩告诉姜民浩，若想要得知女儿的下落，就必须和他玩一个解谜的游戏——解开他留在尸体上的谜题。一场以生命为筹码的赌注开始了。©豆瓣', '薛景求', '金亨俊', 7.8, 76185, 'tt1662557', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2407347002.jpg', 0.5, 2.3, 24.6, 50.1, 22.5, '0.329212,0.084755,-0.630250,0.508071,-0.266558,-0.008161,0.779539,-0.026129,-0.444683,-0.055936,0.212923,0.699255,-0.223979,0.022036,0.173370,-0.058792,-0.326587,-0.868964,0.015408,-0.330956,-0.250909,-0.760518,-0.348312,-0.269119,0.159299,-0.128310,0.700511,0.203243,-0.365617,0.254774,0.442184,0.109884,0.011179,0.495126,-0.102919,-0.064685,-0.173428,0.226836,-0.080652,0.202920,0.189306,-0.303218,0.204255,0.269285,-0.058486,0.582470,0.484836,-0.376265,-0.375586,0.043309,0.563089,-0.621936,-0.051860,0.111514,0.431982,0.014956,-0.037832,0.516672,-0.380301,-0.298712,0.151955,-0.045628,-0.967778,-0.066854,0.255998,0.358035,-0.481391,0.161346,-0.186821,-0.004879,-0.111645,-0.108126,0.298889,0.379048,0.402994,0.276785,-0.284168,-0.135298,-0.565117,0.177278,0.402065,-0.182099,-0.101396,0.252078,0.051317,-0.462893,-0.198179,-0.220065,-0.012742,0.084027,0.183541,-0.034982,-0.412015,0.130290,-0.279620,-0.238518,-0.366362,-0.168883,-0.117640,-0.439513,-0.044113,-0.150238,-0.361839,-0.129736,-0.479677,0.126603,0.217503,-0.499630,0.383016,-0.702034,-0.024421,0.507399,0.205719,-0.687688,0.299198,0.113077,0.078763,-0.452126,-0.164956,-0.034951,0.367750,0.310489,0.055995,0.354415,0.348658,-0.401842,-0.416374,0.307369', '25862560', '35073886', '2027938', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3993250', '黑岩射手', '剧情', '旭日初升，清纯少女黑衣麻陶（花泽香菜 配音）终于迎来了期待已久的初中入学式，水手服标志着青春的开始。在学校门口，她邂逅了乘坐豪华轿车上学的同班同学小鸟游优美（泽城美雪 配音），顿时为对方的成熟知性气息所吸引。她主动上前搭话，两人很快成为开心畅谈的好朋友。家境优渥又怎样？履历平平又如何？这些都没有成为障碍，麻陶和优美的友情不断加深。快乐无忧的第一学年转眼过去，升入二年级后，麻陶和优美分入了不同的班级。开朗外向的麻陶似乎很快适应了新的环境，也结交了新的朋友；而一向内向恬静的优美虽然默不作声，心底却依稀升起几分落寞。那种莫名的情感，让少女的友情失衡……©豆瓣', '花泽香菜', '吉冈忍', 6.9, 6429, 'tt1827378', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p679886269.jpg', 1.8, 9.7, 44.9, 30, 13.7, '0.528170,0.257038,-0.625515,0.754134,-0.189314,-0.504372,0.701224,0.305721,-0.230080,-0.032574,-0.090406,0.554014,-0.328107,0.578544,0.390966,-0.078015,-0.153068,-0.627808,-0.140097,-0.224994,-0.218539,-0.030154,-0.180269,0.317327,0.149228,-0.284243,0.741510,-0.027294,-0.059039,1.049043,0.186404,-0.046228,-0.155814,0.506130,-0.387083,-0.146875,0.012323,0.214369,-0.069134,-0.162913,0.026142,-0.211433,-0.236195,0.026680,-0.172954,0.419434,0.868660,0.151649,-0.319033,0.083221,0.535391,0.256408,0.007399,0.068231,0.180691,0.228147,0.058980,-0.255556,0.003518,0.114629,-0.329708,-0.040758,-0.327934,0.223484,0.063453,0.132779,-0.123829,0.635029,0.200081,-0.382379,0.458567,-0.186535,-0.234816,0.154148,0.218449,0.510632,-0.242730,0.491571,-0.090966,0.263354,0.665111,0.433383,-0.686892,0.537630,-0.618558,-0.351181,0.198596,-0.078709,-0.182313,-0.131527,0.380386,0.305793,0.134131,0.219294,-0.651187,0.081888,0.029202,0.089415,-0.031642,-0.700999,-0.148215,-0.655768,-0.257446,-0.487962,-0.311011,-0.089060,0.081741,-0.170133,0.979418,-1.009512,0.131075,0.357996,0.140486,-0.169436,0.321880,-0.033853,0.031002,-0.209037,-0.217852,0.344887,-0.190961,0.346398,0.023815,0.754050,-0.371849,-0.026604,-0.562243,0.562151', '25922902', '3811356', '1826173', '20390013');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3993588', '狼图腾', '剧情', '上世纪60年代，北京知青陈阵（冯绍峰 饰）和杨克（窦骁 饰）来到了内蒙古额仑大草原插队，加入了蒙古族牧民毕利格老人（巴森 饰）以及他的儿媳噶斯迈（昂哈尼玛 饰）一家的生产队，从此开始若干年的放牧生活。在与狼群的接触过程中，陈阵带着强烈的好奇，逐渐了解了这种动物，甚至有了想自己养一 只小狼的念头。蒙古人民崇敬狼，热爱草原，而汉人则功利地掠夺土地，这导致了狼群与人之间的“战争”。以场部主任包顺贵（尹铸胜 饰）为首的生产队最终发起了一场灭狼运动，让狼群和人类之间的关系陷入到了剑拔弩张的地步…… 自然与人的关系也遭遇了前所未有的挑战。电影改编自姜戎同名小说，耗时5年拍摄完成。©豆瓣', '冯绍峰', '让-雅克·阿诺', 6.9, 190559, 'tt2909116', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2225291257.jpg', 2, 8, 44.6, 35.3, 10.2, '0.411541,0.001909,-0.619030,0.637099,0.271888,-0.133997,0.526910,0.195914,-0.524297,-0.008040,0.050426,0.529826,-0.081089,-0.103604,0.264482,-0.206268,-0.209151,-0.694358,-0.194299,0.001316,-0.224167,-0.257345,-0.167534,-0.326537,-0.044286,-0.297296,0.605655,0.234927,-0.260068,0.684399,0.038291,0.141631,0.110934,0.362110,-0.019600,0.044179,0.107620,0.045709,-0.305243,0.008368,-0.086584,-0.095476,-0.177698,-0.018962,-0.024818,0.264890,0.924816,-0.408432,-0.034804,-0.283950,0.264319,-0.117179,-0.046242,0.068443,0.509292,0.032784,0.175280,0.379380,0.220628,0.046340,-0.027859,0.018807,-0.498460,0.210357,0.031281,0.103600,-0.528466,0.653296,0.240424,-0.082373,0.115232,-0.124011,0.230198,0.505198,0.431832,0.417961,-0.046200,-0.225733,-0.402627,0.201329,0.850775,-0.150386,-0.192006,0.093390,-0.393158,-0.695166,-0.170830,-0.261420,-0.326365,-0.158074,0.251594,-0.006259,-0.386020,0.487625,-0.991179,0.110660,0.097497,-0.139439,0.166113,-0.306151,-0.035602,-0.548073,-0.368987,-0.712280,-0.178347,0.111409,0.226491,-0.074561,0.733735,-0.636744,0.050359,0.455103,0.486138,-0.381355,0.721659,-0.126260,-0.059867,-0.186085,-0.045125,0.220268,-0.244865,0.345878,0.297489,0.272556,-0.209385,-0.069335,-0.064674,0.532876', '26290398', '3811356', '1310175', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3993632', '命运之夜 剧场版', '动画', '人気アニメシリーズ「空の境界」の原作者・奈須きのこ率いる「TYPE-MOON」が原作を務め、ゲームやTVアニメなどさまざまメディアで展開する「Fate/stay night」の劇場版。少年・士郎は街を焼き尽くすほどの大災害で全てを失い、魔術師を名乗る男に引き取られる。それから10年、士郎はふとしたことから「聖杯戦争」と呼ばれる魔術師同士の争いに巻き込まれ、幼い頃に起きた惨劇を繰り返さないために、壮絶な戦いに身を投じることになる。', '杉山纪彰', '山口祐司', 7.3, 9882, 'tt1587156', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2222786604.jpg', 1.2, 5.7, 36.9, 38.3, 17.9, '0.056728,-0.232785,0.607808,-0.546850,-0.257479,-0.224037,-0.369134,0.725112,0.403818,-0.051872,0.031056,0.071435,0.131130,-0.501688,0.521272,-0.284499,-0.078874,-0.090370,0.054038,-0.359432,0.393448,0.290938,0.448407,0.390130,-0.818822,-0.384023,0.796773,-0.495863,0.183432,-0.168745,0.774763,0.418417,-0.468800,-0.361128,0.162189,0.560500,-0.550132,0.073299,0.772092,0.135007,-1.010802,-0.607796,-0.621159,-0.398306,0.258359,-0.060485,1.050367,0.313973,0.217933,-0.470674,0.328502,0.509375,-0.782014,-0.184360,0.202713,-0.017001,-0.256158,0.140674,0.192176,-0.444631,0.383948,0.337892,0.334654,-0.088566,0.417491,-0.336881,-0.143499,0.092582,-0.093179,0.154760,0.258818,0.359033,-0.405717,-0.678335,-0.204596,-0.129520,0.391102,0.135929,-0.034526,0.253784,0.019506,-0.391814,0.012465,-0.559596,0.328624,-0.467247,-0.646738,-0.293190,0.025722,-0.283839,-0.261767,0.245236,0.082141,-0.319327,-0.358859,-0.337889,-0.090536,0.304446,0.191416,0.086753,-0.109294,-0.071930,0.077669,0.139645,0.260269,0.498759,0.891511,-0.438585,0.847363,-0.069714,-0.415276,0.494971,-0.192258,0.098113,0.530561,-0.224445,-0.263446,-0.040488,0.125208,-0.151668,-0.264703,0.192504,0.386518,-0.165646,-0.521477,0.314112,-0.193588,0.266748', '26635321', '27030639', '27011740', '35307624');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3993708', '火龙对决', '动作', '重案组探长文方（黎明 饰）自两月前妻子遇害后，脾气变得暴躁古怪，因对犯人动粗经常被人投诉。一桩妓女被杀案的调查过程中，文方认识了总区重案的高级督察纪少群（任贤齐 饰），并派手下帮他找回了被偷走的手机。妓女被杀案调查与一宗枪火案交织在一起，重案组和调查枪火案的分队联合行动，不料伏击行动遭泄露，双方在茶楼展开激战，文方手下兄弟身受重伤，纪警官也随后赶到，在协助追赶嫌犯途中被嫌犯开枪击中。妓女被杀案嫌犯初步锁定重案组探员高祥安（廖启志 饰），文方因包庇手下被停职。在众多兄弟的协助下，重案组抓到高祥安口中的戴渔帽的嫌犯，嫌犯对杀人案供认不讳。在压送嫌犯过程中嫌犯打个手铐并打伤祥安逃脱，接二两三的事故让文方对警界内部人员产生怀疑，在探员小美（叶璇 饰）的协助下，文方终于找出隐匿于警界之中的“老鬼”……©豆瓣', '黎明', '林超贤', 6.2, 19966, 'tt1602500', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1991536437.jpg', 2, 13.9, 61.7, 18.8, 3.6, '0.220428,-0.316684,-0.367444,0.194395,-0.196682,0.082987,0.586833,0.053327,-0.617933,-0.155675,0.502342,0.388439,-0.270719,-0.031098,0.519720,-0.303280,-0.295706,-0.782477,-0.233401,-0.182464,-0.427492,-0.636278,0.008789,-0.188006,0.267707,-0.126423,0.356659,0.120230,-0.263640,0.565662,0.213289,0.479342,-0.760465,0.321008,-0.007088,0.073719,0.401662,-0.363164,-0.359936,0.267416,0.085893,-0.399542,0.210398,-0.104549,0.213492,0.474322,0.703790,-0.124518,-0.241518,-0.174376,0.009318,-0.343596,-0.046319,-0.147123,0.840011,0.352262,-0.021755,0.542528,-0.289104,0.021959,-0.061546,0.007280,-0.598094,0.248759,0.337467,0.146202,-0.381689,0.048026,-0.366169,0.404875,0.103789,0.101818,0.373026,0.397239,0.016409,0.014685,0.112660,0.040097,-0.506323,0.143304,0.344354,-0.220969,0.143509,-0.393027,0.183815,-0.360665,-0.061530,-0.121365,0.135669,-0.072797,0.288693,-0.103697,-0.052865,-0.115739,-0.160352,-0.244003,-0.217667,0.179050,-0.295216,-0.295796,-0.123591,-0.719880,-0.088643,0.018140,-0.261023,0.164812,0.174427,-0.152420,-0.018646,-0.607836,0.157164,0.417659,0.148570,-0.464800,0.132079,0.226225,0.209725,-0.353436,-0.332511,-0.327020,0.850740,0.694940,0.434790,0.223920,-0.497937,-0.369339,-0.289854,-0.544908', '3387546', '2357707', '4189695', '27126336');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3998385', '旺角监狱', '剧情', '精神分裂的细辉（张家辉 饰）假释出狱。当年，他一人砍死几十人，却因遭警察（廖启志 饰）冷枪而被捕。29年后，老帮主已死，新帮主候选人有两个：箭猪与彼得（谭耀文 饰）。前者好色胆小，后者心机颇重。叔父们想挺箭猪上位，让他去接细辉出狱，拉拢他对抗彼得。箭猪准备给细辉接风，后者非但不领情，还当面救走了箭猪要对付的三个人:皮条客蛋挞（王晶 饰）、妓女大凤（莫小奇 饰）、小凤（孟瑶 饰）。原来，大凤是蛋挞手下的妓女，曾受到箭猪强暴。当她得知弱智的妹妹小凤被拐骗到香港，便奋不顾身前去营救。为此，得罪了箭猪。细辉带她们回自己家，细辉的母亲（鲍起静 饰）已经老年痴呆，认不出儿子，却倍感亲切。此后，细辉和大凤产生了感情，然而他却成为了帮派的焦点，而且被枪王盯上了……©豆瓣', '张家辉', '王晶', 6.3, 9789, 'tt1547640', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2200703330.jpg', 3.2, 14.4, 52.6, 23.8, 5.9, '-0.048286,-0.171113,-0.337043,0.203204,-0.279452,-0.265964,0.580547,0.203976,-0.366470,-0.179218,0.287797,0.523516,-0.068972,0.104936,0.099891,-0.091173,0.040436,-0.348491,0.110236,0.074080,-0.196256,-0.065302,-0.180699,-0.160726,-0.123697,-0.047096,0.264379,-0.255728,-0.120795,0.532584,0.463778,0.283652,-0.045416,0.342669,-0.260613,0.432763,-0.004832,-0.031177,-0.075760,0.076817,-0.027818,-0.259268,-0.186465,0.188632,-0.050774,0.429135,0.397667,-0.028411,-0.033485,-0.470238,0.120295,-0.355739,-0.004188,0.164175,0.251913,-0.054759,0.198879,0.094519,-0.117556,-0.048514,0.104119,0.035103,-0.535852,0.366948,0.059690,-0.036716,-0.570319,0.218792,-0.288710,0.198616,0.081424,-0.075511,0.197457,0.048720,-0.109025,0.229380,-0.051236,0.052812,-0.605095,0.190035,0.650289,-0.072212,0.127134,-0.083305,0.206184,-0.291659,0.232555,-0.351695,-0.133907,0.129148,0.453098,-0.114211,-0.195557,0.031346,-0.406807,-0.315562,-0.363703,0.258765,-0.004641,-0.412731,0.041845,-0.225734,-0.099360,-0.251076,-0.264006,0.142043,0.209591,-0.169236,0.466366,-0.570420,0.128369,0.322610,0.367719,-0.878549,0.389229,0.155200,-0.081281,-0.092149,0.013831,-0.133525,0.326516,0.039561,0.387908,0.120075,-0.127447,-0.343347,-0.256831,0.011033', '1297710', '1302110', '1305915', '1300857');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3999549', '悸动的心', '剧情', '伊诺（亨瑞·霍珀 Henry Hopper 饰）是一个有点奇怪的年轻人，他似乎对生活毫无兴趣，却喜欢在陌生人的葬礼上游荡。在一次葬礼期间，他偶然邂逅了一位独特的女孩安娜贝尔（米娅·华希科沃斯卡 Mia Wasikowska 饰），两人渐渐成为无话不说的好朋友。伊诺向安娜贝尔介绍自己的一个鬼魂朋友浩（加濑亮 饰），安娜贝尔则与伊诺分享她为之痴迷的达尔文学说。然而好景不长，就在两人关系日渐亲密，生活的乐趣也慢慢复苏之时，安娜贝尔告诉了伊诺一个事实——她是一个将不久于世的癌症病人。面对着一边是难以割舍的韶华时光，一边是无法改写的死之永夜，这段不寻常的爱情将以怎样的方式对抗生命的流逝……©豆瓣', '米娅·华希科沃斯卡', '格斯·范·桑特', 7.3, 8344, 'tt1498569', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1324680158.jpg', 0.7, 4.8, 39.3, 40.5, 14.7, '0.502247,-0.025229,-0.534688,0.746562,-0.287832,-0.342444,1.069159,0.113914,-0.472731,-0.145333,0.354162,0.968461,-0.118210,0.323974,0.264861,0.334873,-0.375629,-0.924936,0.193247,-0.092258,-0.189374,-0.691854,-0.358628,0.053373,-0.187774,-0.342879,0.632155,-0.216971,0.006664,0.543658,0.165530,0.375337,-0.069850,0.669438,-0.201441,-0.083311,0.112280,-0.136548,-0.326435,0.026890,0.129466,-0.184953,-0.174311,0.409267,-0.151531,0.177332,0.709226,-0.452537,-0.009371,-0.075664,0.394398,-0.166479,0.161007,0.183059,0.046287,-0.149969,0.293351,0.259096,-0.204600,-0.099023,0.070748,0.052431,-0.815945,0.234590,-0.059907,0.519781,-0.607939,0.746120,-0.025843,-0.350559,0.174588,-0.484572,0.057255,0.581815,0.410173,0.483958,-0.297577,-0.108339,-0.407650,0.062944,0.762082,0.325044,-0.414488,0.773702,-0.322916,-0.142913,-0.149948,0.031430,-0.943622,-0.193147,0.267961,0.144073,-0.164240,0.511947,-0.680802,0.127177,-0.345011,-0.146913,0.153579,-0.383354,-0.126708,-0.495862,-0.124665,-0.623310,-0.503249,-0.231559,0.073159,-0.486497,0.862785,-1.030010,0.092120,0.715114,0.317746,-0.361296,0.667791,0.129331,0.097425,-0.289581,-0.070495,0.511279,-0.170018,0.064806,0.202592,0.633000,0.241800,0.317720,-0.539451,0.752540', '24756472', '4275444', '1309172', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('3999737', '午夜出租车', '恐怖', '午夜时分，一辆出租车驶进一条胡同里。两女一男三名乘客谋财害命勒死女司机之后却发现女司机的尸体不翼而飞，这时车外出现可怕的鬼影……北漂作家徐子（陈小春 饰）怀才不遇，在北京和女友林贞（邓紫衣 饰）一起生活。为了贴补家用和寻找小说素材，在女友的鼓励下，徐子开始做起了“的哥”。开车的辛苦在徐子眼里倒也无所谓，然而一件接一件的怪事却让徐子摸不着头脑。为了搞清楚发生在那辆诡异的出租车为何凭空消失，里面若隐若现的影子是人是鬼，徐子在女友的陪伴下开始了午夜的追踪。在此期间，与徐子要好的同事积劳成疾，最终而心肌梗塞而离开人世。几经波折之后，徐子终于追踪到了那个盗用自己出租车的“鬼影”。然尔，让他始料不及的是他还发现另一件事情……©豆瓣', '陈小春', '张江南', 3.8, 7920, 'tt4177328', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2171262755.jpg', 46.1, 31, 15.8, 2.9, 4.1, '0.591952,0.036671,-0.692014,0.390432,-0.341709,-0.340800,1.086714,0.135177,-0.867724,-0.324776,0.266477,0.424814,-0.258896,0.283594,0.529684,0.069528,-0.208312,-0.440317,0.252876,-0.129392,-0.346765,-0.283221,-0.434054,-0.234604,-0.104834,-0.021021,0.375900,0.549990,0.291733,0.570365,0.539987,-0.123257,-0.426393,0.682912,-0.100773,0.137398,-0.025391,0.234144,0.193576,0.306902,-0.104078,-0.398451,-0.055836,-0.078570,-0.116350,0.173760,0.597781,0.230156,-0.261367,0.181614,0.329536,-0.366751,0.070382,-0.013615,0.246640,0.099588,0.396867,-0.088809,-0.207948,-0.099065,-0.018163,0.481235,-0.403647,0.272666,-0.258834,0.021280,-0.860296,0.327842,-0.316935,-0.091784,0.161555,-0.724180,0.514253,0.341770,0.333653,0.319483,-0.197859,0.010612,-0.504594,0.320911,0.623794,0.086715,-0.083886,0.380118,0.042460,-0.310246,-0.132842,0.182003,-0.189188,-0.237943,0.443026,0.075108,-0.389212,-0.157230,-0.377084,0.005656,-0.066682,-0.114719,-0.159917,-0.270357,-0.282134,-0.390592,0.040521,-0.364506,-0.060651,0.339152,-0.010676,-0.138513,0.347536,-0.621913,0.463696,0.411732,0.024599,-0.294355,0.624826,-0.128952,0.090146,0.021729,0.086421,0.012771,0.056847,0.592872,-0.083297,0.391681,-0.188014,-0.258157,-0.566504,0.226035', '21619567', '1306670', '20380318', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4004715', '恶老板', '喜剧', '尼克（杰森·贝特曼 Jason Bateman 饰）在公司苦熬八年，起早贪黑卖命工作，老板戴夫（凯文·史派西 Kevin Spacey 饰）明明许诺他升职，却临时反悔还狠狠奚落了他一番；戴尔（查理·戴 Charlie Day 饰）是个牙医助手，早就对上司朱莉娅（詹妮弗·安妮斯顿 Jennifer Aniston 饰）放肆的性骚扰忍无可忍；科特（杰森·苏戴奇斯 Jason Sudeikis 饰）本被视为公司接班人，哪想老板突然暴毙，其子鲍比（柯林·法瑞尔 Colin Farrell 饰）擅自接手公司，得意洋洋发挥自己的二世祖精神，眼看就要把公司搞垮。三个在恶老板手下受挫的老友在酒吧聚头，突发奇想决定集体干掉老板，且三人分别避开自己老板出手，就能逃开嫌疑，成就完美谋杀。经过精心策划，三位老友各出奇招，一场笑料百出的“杀掉老板”计划就此展开……©豆瓣', '杰森·贝特曼', '赛斯·戈登', 7, 55086, 'tt1499658', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1242787570.jpg', 1, 6.1, 44, 39.4, 9.5, '-0.226662,0.102588,-0.190374,-0.000436,-0.197799,-0.458713,0.278210,0.320017,-0.062698,-0.176220,0.347951,0.478793,-0.345411,0.079760,0.502998,-0.029073,-0.189821,-0.514769,0.271521,0.059736,0.454527,-0.577806,-0.113015,-0.452340,0.108398,-0.153422,0.060724,-0.475800,-0.141570,0.167408,0.407592,0.159091,0.039577,0.221825,0.140476,0.240646,0.507448,-0.273211,-0.414981,0.056352,-0.010599,-0.159845,-0.000476,0.036515,0.289853,0.293113,0.321539,0.011093,-0.196878,-0.160574,0.387675,-0.232795,0.047484,0.178551,0.443044,-0.140781,0.104075,0.267217,-0.201523,-0.021842,0.318814,-0.117748,-0.472376,0.205850,0.027611,-0.182984,-0.563706,0.117980,-0.194770,0.259806,-0.076172,-0.351910,-0.197494,0.226354,0.386767,0.041874,0.153504,0.241589,-0.392114,0.135776,0.300868,-0.038510,0.119111,0.059325,0.373795,0.024531,0.184895,-0.053454,-0.312384,-0.242826,0.472905,-0.478708,0.326443,0.061438,-0.282315,-0.429328,-0.611918,-0.034473,0.129080,-0.265891,0.076778,-0.543741,0.070153,0.211503,-0.141454,0.072994,0.212006,-0.127886,0.066335,-0.518176,-0.034428,0.393621,0.279474,-0.465580,0.309394,0.161907,0.149909,-0.338488,-0.164526,-0.091397,0.382516,0.145499,0.257520,0.277105,0.149067,-0.238086,0.048732,0.077729', '6517421', '1292222', '3183490', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4004731', '海洋天堂', '剧情', '刚过21岁生日的大福（文章 饰）是个孤独症患者，父亲王心诚（李连杰 饰）在妻子去世后，一个人将大福养大，如今王心诚身患肝癌，自感时日无多，虽然楼下开小卖店的柴姨（朱媛媛 饰）时常给这对父子无私的帮助，但如何安置大福的未来还是王心诚放不下的牵挂，他甚至有了和儿子一同赴死的想法。王心诚试图将大福送回培智学校，但是学校、福利院一连串的拒绝令他倍感失落。而且在大福的世界里，水是他最好的朋友，这个能像海豚一样畅游的孤独症患者也无法离开水族馆，在水族馆，大福结识了善良的杂技女子玲玲（桂纶镁 饰），而王心诚急于教会大福生存的技巧，他的时间已经不多了……©豆瓣', '李连杰', '薛晓路', 8, 140869, 'tt1498858', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p504314075.jpg', 0.3, 1.8, 22.8, 50.1, 25, '0.085239,0.114677,-0.593244,0.332082,-0.196307,-0.440284,0.497207,0.317714,-0.843864,-0.299798,0.238138,0.745228,0.225625,0.296819,-0.100021,0.121820,-0.129736,-0.225966,0.052475,-0.006544,-0.319855,-0.271104,-0.114537,-0.212763,-0.018587,-0.198061,0.193110,-0.141298,0.062782,0.454288,0.094826,0.149410,0.194720,0.351752,-0.350071,0.280204,-0.074814,0.210825,-0.450871,0.122311,0.256794,0.109265,-0.241583,-0.136779,0.121031,0.274670,0.651959,-0.227641,-0.491316,-0.187806,0.432902,-0.278842,-0.074714,0.333810,0.053615,-0.062127,0.391258,0.066548,-0.349111,-0.029295,0.153031,-0.114854,-0.751232,-0.115292,0.267288,0.062329,-0.785372,0.417929,-0.125986,-0.377066,-0.003337,-0.437606,0.371334,0.419316,-0.115539,0.472029,-0.342533,-0.110330,-0.514181,0.364761,0.609245,0.028454,-0.147987,0.226076,-0.342119,-0.457791,0.077140,-0.132383,-0.725462,0.074205,0.134654,-0.000624,-0.403515,-0.007130,-0.345740,-0.076917,-0.331685,0.071949,0.120150,-0.425553,-0.196802,-0.124827,0.074675,-0.405490,-0.252481,-0.163225,0.320995,-0.184591,1.005990,-0.797770,0.202749,0.291749,0.372685,-0.405181,0.950119,0.159817,0.026375,-0.356409,-0.034826,-0.011119,-0.168817,0.382203,0.221098,0.347508,0.027497,-0.345389,-0.415480,0.452857', '1292720', '26348103', '3445516', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4005190', '死亡飞车2', '动作', '影片是08年《死亡飞车》的前传。后工业时代，各种大型私人城市监狱被建造起来，其中最臭名远扬的就是“绝命岛”监狱。有“条子杀手”称号的卡尔（鲁克·高斯 Luke Goss 饰）被押往这里，接受无期徒刑。一心要在电视领域闯出天下的女典狱长琼斯（劳伦·科汉 Lauren Cohan 饰）掌权时期。政府将监狱的运行权交给了蔚蓝公司。在蔚蓝眼中牢房在新时代的商业运作体系下一样是有利可图的。这帮囚犯对于他们来说正是绝好的真人玩命体育比赛的选手，将他们你打我杀的画面转播出去一定大受欢迎。而蔚蓝公司精心设计的比赛项目就是“死亡飞车”。卡尔成了一名赛车手，为了自由不惜与众多监狱人员搏命，为自由而奋战着，却不知自己正走上一条传奇之路。©豆瓣', '鲁克·高斯', '罗伊·雷内', 6.4, 16937, 'tt1500491', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2733014201.jpg', 2.5, 14, 53.9, 22, 7.6, '0.132632,0.264284,-0.501656,0.608601,0.009446,-0.135009,0.556951,0.093702,-0.500932,-0.126603,0.347991,0.656774,0.067196,0.205613,0.237451,-0.092075,-0.333642,-0.531943,-0.595198,-0.443941,-0.376157,-0.403095,-0.161406,0.092363,-0.128626,-0.370995,0.788350,0.113256,-0.138842,0.004950,0.454431,0.360497,-0.070146,0.131940,-0.250390,-0.326072,0.299094,-0.168903,-0.470734,0.200817,-0.317167,-0.134486,-0.112868,0.069590,0.055731,-0.047347,0.510411,-0.107276,0.047320,-0.384776,0.438375,-0.282071,-0.070243,-0.135686,0.364654,-0.046693,0.105107,0.251527,-0.018761,0.029673,0.161473,-0.298547,-0.795778,0.065738,0.050340,-0.012252,-0.546264,0.171832,-0.167048,-0.036933,0.008639,-0.287705,0.251928,0.178126,0.468443,0.369951,-0.101088,0.003741,-0.732994,0.297377,0.525966,-0.101927,-0.285557,0.073235,-0.056644,-0.448103,-0.032755,-0.417675,-0.229456,-0.244267,0.482597,-0.306443,-0.120551,0.198532,-0.498715,0.236071,-0.150981,-0.547722,0.068748,-0.302634,-0.244391,-0.772895,0.140221,-0.112447,-0.180057,0.089319,0.151173,-0.286882,0.570808,-0.762980,0.200154,0.636162,0.209102,-0.546783,0.784659,-0.288131,0.170656,-0.173793,0.005488,0.005728,0.400852,0.623593,-0.057119,0.298640,-0.054453,-0.268734,-0.286305,0.567437', '1793491', '1308842', '4301278', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4009651', '斗牛', '剧情', '抗日战争时期，一队八路军来到了沂蒙山区的堡垒村马牧池，随他们一同前来的还有国际友人捐赠的奶牛。长年生活在大山中的村民从没见过这种黑白相间、奶量充足的牛，他们备感惊奇。不久，日军船尻部队逼近，八路军紧急撤退，临行前将奶牛托付给村民喂养。贫穷胆小的村民担心奶牛会带来灾难，他们通过抓红豆的方式选出养牛人，小寡妇九儿（闫妮 饰）帮破落户牛二（黄渤 饰）抓阄，最终使牛二成了这倒霉的“幸运儿”。残酷血腥的扫荡过后，村民们全被杀害，只有牛二和奶牛成为幸存者。尚未得到喘息之时，另一队日军部队路过此地，并将伤员留在这里。从这天起，肩负着保护奶牛重任的牛二想尽办法和日军、土匪、江湖郎中等各色人等展开周旋，而那头倔脾气的搭档也让他头疼不已……©豆瓣', '黄渤', '管虎', 8.2, 191641, 'tt1500703', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1835458850.jpg', 0.4, 1.7, 17.4, 50.8, 29.7, '0.022188,-0.295071,-0.655203,0.261115,-0.166139,-0.094473,0.575304,-0.020729,-0.570037,0.022766,0.300527,0.550912,0.271309,0.110540,0.064604,-0.377448,-0.251672,-0.327052,-0.379174,0.130414,-0.241426,-0.043886,-0.064982,-0.424104,0.009537,-0.269942,0.476793,0.179805,0.037533,0.662574,0.155134,0.080644,-0.314526,0.273469,-0.263333,0.148043,0.071539,-0.235470,-0.169127,-0.043766,-0.214504,-0.078002,-0.021555,-0.083631,0.149769,0.260545,0.803477,-0.368702,-0.090738,-0.203857,-0.076907,-0.195066,0.130502,0.058019,0.543257,-0.062681,0.268972,-0.032934,-0.025400,0.215368,-0.176902,0.012201,-0.452669,0.128619,0.042465,-0.069902,-0.693794,0.195426,0.185819,0.225720,0.219781,-0.342899,0.137873,0.584515,0.036850,0.347256,-0.024058,0.173460,-0.396537,0.162763,0.665860,-0.342611,0.018872,-0.183061,-0.165098,-0.366425,0.532968,-0.344039,-0.250204,0.040654,0.498954,-0.075844,-0.178921,-0.046495,-0.672308,0.168912,-0.164106,-0.277371,0.109109,-0.005070,-0.397989,-0.538482,0.232079,-0.242699,-0.138028,0.335329,0.342112,0.078747,0.715565,-0.466721,0.031815,0.455514,0.288129,-0.422568,0.341132,-0.221828,0.283388,-0.084111,-0.012671,-0.035030,0.016643,0.665726,0.492324,0.147927,-0.329689,-0.245338,-0.194485,0.001079', '21619567', '1466273', '1856675', '1298694');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4014396', '神奇四侠2015', '动作', '天才少年理查德（迈尔斯·特勒 Miles Teller 饰）凭借物体传送装置的发明得到正研究量子门的富兰克林•斯通的赏识，他将理查德招至麾下，通过和维克多（托比·凯贝尔 Toby Kebbell 饰）、约翰尼（迈克尔·B·乔丹 Michael B. Jordan 饰）、苏珊（凯特·玛拉 Kate Mara 饰）等才华横溢的青年们的通力合作，量子门的研究终于取得突破性进展。不久之后，不甘成果被政府攫取的年轻人们叫上理查德的朋友本（杰米·贝尔 Jamie Bell 饰），偷偷潜入那个未知的世界探险，谁知却被神秘的能量所感染。在此之后，他们拥有了身体伸缩、控制火焰、岩石化以及隐形等能力。为了能过回复从前的样子，年轻人们再次走向量子门，而对面的世界还有一个当初被丢下的同伴等待着他们……©豆瓣', '迈尔斯·特勒', '乔什·特兰克', 4.8, 46974, 'tt1502712', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2239463272.jpg', 21.7, 34.6, 31.5, 7.9, 4.3, '0.163199,0.154802,-0.511926,0.563021,-0.226213,-0.278608,0.592017,0.241077,-0.325899,-0.384472,0.055033,0.581188,-0.356104,0.239536,0.136702,0.008652,-0.449082,-0.574711,-0.046251,-0.200719,-0.366184,-0.286331,-0.475493,-0.258483,-0.096386,-0.624525,0.820838,-0.011190,-0.132409,0.262148,-0.086901,0.404373,-0.077036,0.355538,-0.132579,-0.116651,0.357724,-0.237991,-0.129066,0.223101,-0.183934,-0.076299,0.084895,0.022074,-0.129513,0.159696,0.581035,-0.540817,0.158646,-0.342777,0.072593,-0.006005,0.203517,0.131795,0.133179,0.207705,-0.047974,0.039012,-0.061830,0.013254,0.184062,-0.199426,-0.729582,-0.162163,0.005552,0.170875,-0.389191,0.097717,-0.287126,-0.228872,0.129887,-0.300284,-0.110365,0.328969,0.317402,0.335497,-0.251717,0.192233,-0.463416,-0.178688,0.123542,-0.356848,-0.489975,0.353226,-0.051096,-0.398142,-0.060220,0.055310,-0.353360,-0.139023,0.618156,0.329062,0.169536,0.101021,-0.637793,-0.006717,-0.428611,-0.078368,-0.085013,-0.243360,-0.153181,-1.121488,-0.159914,-0.090426,-0.150431,0.029857,-0.095475,-0.216306,0.740729,-0.598016,0.194753,0.322381,0.257915,-0.393128,0.462509,-0.271621,0.155914,-0.372881,-0.246822,0.339043,0.197031,0.392162,0.085950,0.469044,0.171920,-0.264457,-0.255565,0.440777', '2369613', '20274039', '3318306', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4014397', '绝地战警：疾速追击', '喜剧', '曾制作《珍珠港》、《壮志凌云》、《加勒比海盗》系列等爆款电影的好莱坞金牌制片人全新倾力打造的《绝地战警：疾速追击》，讲述了迈阿密警员麦克（威尔·史密斯饰）遭遇神秘黑帮势力的暗杀伏击，为了迎战势力庞大火力惊人的黑帮分子，解决隐藏在暗处的危机，麦克找回曾经的搭档马库斯（马丁·劳伦斯饰），“嘴炮二人组”再度集结开启沙雕模式，不仅时刻上演逗比互怼，更在迈阿密街头与黑帮展开空前绝后的飙车枪战大戏。这对最佳搭档究竟能否在枪林弹雨下突出重围，找出幕后黑手完成绝地反杀？', '威尔·史密斯', '阿迪尔·埃尔·阿比', 5.7, 35091, 'tt1502397', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2614950073.jpg', 3.6, 25.1, 58.5, 10.7, 2.1, '-0.131987,-0.259652,-0.500726,0.429099,0.400997,0.257491,0.325021,-0.084220,-0.169474,-0.190667,0.749451,0.506266,-0.174317,-0.400422,0.339644,-0.426174,-0.327600,-0.586197,-0.169165,0.295477,0.057232,-0.194616,-0.934577,-0.179018,0.327190,-0.190026,0.700961,0.302075,-0.606548,0.122761,0.360444,0.557038,-0.405460,0.038115,0.038733,-0.181710,0.299784,-0.221313,-0.764905,0.510083,-0.299618,-0.397396,-0.105626,0.081249,-0.006302,0.187508,0.524955,-0.247918,0.263026,-0.004090,0.186868,-0.356672,-0.218951,-0.225104,0.432830,-0.043334,0.033287,0.171615,0.147894,-0.037347,-0.185378,-0.159880,-1.009244,0.100640,0.206691,-0.006444,-0.273051,-0.056120,-0.162910,0.470307,0.362128,0.136312,-0.042925,0.362790,0.710692,-0.138014,0.123741,0.181005,-0.390115,0.255190,0.432835,-0.240086,0.098103,-0.172494,0.456084,-0.288169,-0.159203,-0.375781,-0.073778,-0.161535,0.606249,-0.334834,0.104827,0.309470,-0.659766,0.072292,-0.074599,-0.146698,0.094338,-0.245509,-0.096431,-1.366758,-0.148252,0.161627,0.155439,0.067465,-0.027569,0.005683,0.432645,-0.535994,0.019205,0.761188,0.018144,-0.289786,0.322263,0.031007,0.009217,-0.287617,-0.236625,0.226314,0.219632,0.247605,-0.067763,0.118361,-0.137711,-0.323616,-0.161094,0.222923', '2369613', '6517421', '3318306', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4014405', '狂暴飞车', '动作', '《狂暴飞车3D》由帕特里克·卢西尔执导，是尼古拉斯·凯奇的第一部3D电影。弥尔顿（尼古拉斯·凯奇 Nicolas Cage 饰）是一个十恶不赦的暴徒。为了阻止邪教徒在月圆之夜用他的唯一孙女的鲜血完成祭祀，从监狱逃脱了。可他只有三天时间，同时也面临着三面夹击。第一，要对 面被恶魔附体的邪教头子乔安王。第二，警察因为一桩杀人案找上了门来。第三，撒旦派来神秘杀手The Accountant（威廉·菲德内尔 William Fichtner 饰）将他带回地狱。还好路遇性感女招待派伯（艾梅柏·希尔德 Amber Heard 饰）义无反顾地和他一起复仇。三天之内，弥尔顿可以救出自己的孙女、搞定难缠的警察、消灭撒旦的杀手，完成自己的救赎之旅吗？©豆瓣', '尼古拉斯·凯奇', '帕特里克·卢西尔', 5.9, 32357, 'tt1502404', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1283654144.jpg', 5.7, 22.3, 49.9, 16.5, 5.5, '-0.045121,-0.012164,-0.482606,0.553545,-0.251717,-0.115392,0.752106,-0.101194,-0.273289,-0.255976,0.230628,0.612783,-0.078088,0.095851,0.419525,0.178041,-0.169317,-0.567435,-0.125201,-0.267684,-0.412916,-0.331037,-0.230055,-0.492724,0.248240,-0.209339,0.408080,0.141091,0.059115,0.092475,0.517928,0.250947,-0.001321,0.280710,-0.069979,-0.026790,0.077754,-0.377251,-0.063068,0.662125,0.022677,-0.088604,-0.103700,0.237249,-0.052251,0.420259,0.353136,-0.441402,0.206222,-0.203377,0.142350,-0.644670,-0.160563,0.088630,0.287216,-0.193348,-0.051965,0.383830,-0.109718,-0.196651,0.165215,-0.382938,-0.957436,0.039865,-0.090279,-0.036560,-0.666775,0.190237,-0.261648,0.241711,0.162613,-0.296972,0.136244,0.313526,0.196217,0.329129,-0.089834,-0.034445,-0.710415,0.327004,0.598890,-0.221704,-0.115647,-0.153149,0.255125,-0.309522,-0.002503,-0.348642,-0.164647,0.052908,0.588129,-0.132269,-0.105748,0.070432,-0.371524,-0.440170,-0.576594,-0.058906,-0.121687,-0.369400,0.022348,-0.802263,-0.037645,0.011326,-0.091538,-0.116809,0.101573,-0.291990,0.524435,-0.583821,0.319081,0.671259,0.264559,-0.347365,0.539622,0.199909,0.193047,-0.172218,0.035526,0.265989,0.447973,0.477598,0.473410,0.315834,0.058285,-0.029881,-0.102226,0.319166', '1793491', '3785918', '1301345', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4017146', '月光光心慌慌', '惊悚', '在万圣节前夜，杀人狂迈克尔·麦尔斯逃走了，开始前往伊利诺伊州的哈登菲尔德，这是他最原始的屠杀地。一直负责治疗迈克尔·麦尔斯的精神病专家兰比尔·萨坦博士，警长弗兰克·霍金斯在疯狂寻找迈克尔·麦尔斯的下落，后者继续着他的残杀，并无情地接近着上次屠杀中唯一的幸存者劳瑞。劳瑞死里逃生所带来的创伤与压力，使她在精神上伤痕累累并开始疑神疑鬼，这也导致女儿凯伦与她渐渐疏远 。', '杰米·李·柯蒂斯', '大卫·戈登·格林', 5.9, 23082, 'tt1502407', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2519765769.jpg', 6.1, 21.8, 48, 18.1, 6, '0.144452,-0.225700,-0.704355,0.446909,-0.190786,-0.486786,1.020386,0.022299,-0.432328,-0.370997,0.306961,0.704790,0.017299,0.429633,0.284322,0.102802,-0.488186,-0.448950,-0.183688,0.018644,-0.162462,-0.731557,-0.248232,-0.348283,0.109295,-0.444969,0.478965,0.037126,-0.327120,0.446061,0.227965,0.431012,0.202224,0.726782,0.021262,0.283572,0.097026,-0.492474,-0.288871,0.061036,0.465211,-0.255492,-0.069916,0.414276,-0.011745,0.630234,0.623611,-0.699064,0.171074,-0.236289,0.215710,-0.575646,0.158819,0.300501,0.161478,-0.103555,0.114326,0.320386,-0.017201,0.199260,-0.073496,0.025899,-0.661181,0.114340,-0.182118,0.356212,-0.433398,0.514837,-0.082456,0.253195,0.032911,-0.322528,0.025656,0.388891,-0.219979,0.151765,-0.454292,-0.089067,-0.381461,-0.074216,0.680312,-0.066531,-0.077943,0.209947,-0.183301,-0.440057,0.019214,-0.157119,-0.493837,-0.244824,0.504494,0.221160,-0.015332,0.476226,-0.547821,0.089652,-0.355555,-0.266475,-0.239921,-0.147221,-0.042985,-0.794012,0.049256,-0.301983,-0.246840,-0.296613,-0.259858,-0.528273,0.354102,-0.703899,0.175452,0.873763,0.337753,-0.319269,0.165016,0.160441,0.214767,-0.141136,-0.615073,0.739866,0.177799,0.704250,0.351980,0.318688,0.347593,0.084984,-0.169427,0.737395', '1309172', '1316693', '3735015', '1306723');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4022090', '下一站，说爱你', '喜剧', '梅丽（Cris Horwang 饰）年逾30，至今未婚。眼瞅着身边的朋友出双入对，自己却始终孤身一人，难免悲从中来。情人节参加完最后一个单身朋友的结婚派对，喝得醉熏熏的梅丽在车祸后意外遇到在轻轨公司上班的大伯（Theeradej Wongpuapan 饰），大伯的热心和帅气令梅丽一见倾心。为了结束自己长达三十年的单身生涯，梅丽决定把握机会，主动出击。终于鼓起勇气走到大伯面前，可是却频发状况，还被邻居的花心小妹妹阿宝抢占先机。好不容易找到一点恋爱的感觉时，梅丽却意外在大伯扔掉的背里发现一些东西。追求爱情的路上布满荆棘，梅丽最终能否赢得属于自己的爱情？本片取得了2009年泰国电影票房冠军，并荣获泰国媒体选择大奖最佳电影大奖，两位主演凭借此片获得包括泰国媒体选择最佳男女主角在内的多项大奖。©豆瓣', '提拉德·翁坡帕', '埃迪森·特斯利卡森', 7.8, 53559, 'tt1621642', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p459846512.jpg', 0.5, 2.5, 25.8, 47.4, 23.8, '-0.188095,0.002803,-0.416743,0.240596,0.117961,-0.626393,0.324944,-0.023222,-0.458406,-0.281171,0.086006,0.547828,-0.477792,0.222450,0.375590,-0.231810,-0.190570,-0.505784,0.216357,-0.006279,-0.027440,-0.193696,-0.287067,0.332368,-0.357503,-0.172251,0.683653,-0.111930,0.003567,0.624489,0.437087,-0.131741,-0.034851,0.342919,0.028323,-0.063884,0.252537,0.177107,-0.752851,0.413145,-0.038296,-0.127873,-0.158296,0.139544,0.166790,0.202845,0.506783,0.140295,-0.187013,0.094278,0.524653,-0.127159,-0.187087,0.099108,0.210292,-0.012849,0.418865,0.085398,-0.062517,-0.002420,0.122958,-0.210843,-0.486297,0.127516,0.106455,0.134662,-0.574024,0.512613,-0.078014,0.179883,0.063514,-0.298299,0.106373,0.278506,0.277387,0.198321,-0.418703,0.218699,-0.564720,0.248002,0.632795,-0.173112,-0.126059,0.373978,0.124602,-0.526525,0.070987,-0.284079,-0.444443,0.462620,0.035474,0.193256,-0.175213,-0.007514,-0.404903,-0.056464,-0.037037,-0.241372,0.341218,-0.321008,0.039697,-0.670199,-0.019985,-0.141030,-0.359049,0.008850,-0.049852,-0.375143,0.535568,-0.473599,0.200974,0.649930,0.311215,-0.438449,0.854693,0.375632,0.105093,-0.352539,-0.333264,0.302784,-0.225866,-0.009588,-0.033175,-0.085229,-0.187680,-0.422852,-0.218346,0.400092', '1307200', '25881781', '1829654', '1780122');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4022138', '海边旅店', '剧情', '在一个深山老林中，却伫立着一座海边旅店。某日，各色人等云集于此，上演了几多好戏：103室，推销员龟田雅之（生田斗真 饰）偶遇应召女郎Candy（麻生久美子 饰），两个以骗为生的男女玩起了感情的斗牛游戏；202室，小混混朝仓阳介（山田孝之 饰）和女友二宫留衣（成海璃子 饰）躲避于此，却仍逃不过组织的追杀；203室，厌恶了枯燥婚姻的怪蜀黍太田胜俊（古田新太 饰）决定趁老婆外出之际出轨寻欢，然而令他始料未及的事情发生了；102室，色欲冲天的石冢达也（池田鉄洋 饰）准备和陪酒女郎马琳（山崎真実 饰）欢度春宵，不过好事多磨。不平凡的一昼夜，精彩故事接连上演……本片根据岡田ユキオ的原著漫画《MOTEL》改编。©豆瓣', '生田斗真', '守屋健太郎', 7.2, 6870, 'tt1669801', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p628024920.jpg', 0.6, 4.9, 38.7, 42.9, 12.8, '0.308701,-0.169928,-0.499561,0.204044,0.138804,-0.141752,0.685571,0.186974,-0.288261,-0.438742,0.236924,0.401878,-0.533747,0.264681,0.253354,-0.140948,-0.180064,-0.505793,-0.245473,0.096489,0.141039,-0.069945,-0.071729,0.057408,-0.251353,-0.029036,0.543978,0.087180,-0.088498,0.386632,0.440724,0.600407,-0.449287,0.149481,0.191550,0.090491,0.098428,0.322639,-0.148436,-0.011781,-0.202180,-0.337906,-0.245285,0.019112,0.026180,0.271497,0.840912,-0.155626,-0.291767,-0.239514,0.410948,0.075982,-0.155929,0.100349,0.192560,-0.270252,0.305838,0.181124,-0.066384,-0.029666,0.173267,0.070518,-0.377159,0.138716,0.169313,0.150144,-0.077871,0.346248,-0.242177,-0.219182,0.144407,-0.053238,-0.105658,0.235548,0.592978,0.083903,-0.227833,-0.023552,-0.344946,0.411056,0.408509,0.186774,0.062717,0.611003,0.092505,-0.312821,-0.052842,-0.040590,-0.470017,-0.247491,0.170424,-0.129464,-0.039423,0.012609,-0.580484,0.045134,0.170225,0.085317,0.130121,-0.112860,-0.281091,-0.819889,0.199319,-0.348610,-0.345563,0.258306,0.350436,-0.067879,0.422197,-0.565551,-0.070737,0.515036,-0.100599,-0.295929,0.553113,0.125658,0.037962,0.148724,-0.100903,-0.137522,0.109374,0.194408,0.009981,0.441676,-0.091859,-0.154016,-0.497413,0.206491', '10466639', '5403927', '1322847', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4023433', '九死', '剧情', '洛杉矶接连发生9起绑架案，被绑架者来自各行各业，有神父（马克·麦克雷 Marc Macaulay 饰）、检察官（梅丽莎·乔·哈特 Melissa Joan Hart 饰）、演员还有俱乐部老板，彼此间似乎没有任何关联，而绑架案却都由一人所为，一个戴着蓝色面具、一身黑衣的男子。此案惊动洛城，警方全员出动，却始终找不到任何头绪。与此同时，在城市某各个角落黑暗潮湿的地下室内，9个被绑架者迎来了人生中最为痛苦难熬的时刻。蒙面人要求他们思考被绑架的原因，然后每个10分钟便杀掉一人，直到他们找到原因为止。人质们激烈争论，相互攻讦，抑或检讨人生中所犯下的错误。时间一分一秒地流逝，死神的判决越来越近……©豆瓣', 'Melissa Joan Hart', 'Chris Shadley', 6.2, 10900, 'tt0959329', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1335182737.jpg', 3.7, 16.8, 50.6, 23.2, 5.7, '0.078363,-0.072975,-0.558784,0.330399,0.081201,-0.066240,0.966511,-0.152405,-0.585047,-0.714644,0.282318,0.440504,-0.284506,0.118320,0.366571,-0.278570,-0.342814,-0.974148,-0.108928,-0.299734,-0.421951,-0.477756,-0.115982,-0.258692,0.024929,0.116263,0.670130,0.285943,-0.081619,0.236836,0.322313,0.257856,-0.372093,0.584811,0.133100,-0.239942,0.452571,-0.215449,-0.139617,0.189664,-0.119652,-0.275751,-0.066569,0.261332,-0.246779,0.598540,0.688394,-0.383797,-0.143900,-0.093315,0.307415,-0.286862,-0.033621,0.224288,0.514542,0.024064,0.258795,0.350146,-0.031849,-0.076688,0.095752,0.125023,-0.737111,0.128315,0.130972,0.562605,-0.176228,0.394573,-0.099292,-0.092274,-0.043415,-0.183037,0.192623,0.213479,0.369107,-0.001064,-0.268277,-0.164090,-0.401177,0.078498,0.623927,-0.010331,-0.435803,-0.068938,-0.332805,-0.415317,-0.077587,-0.046919,-0.181171,-0.054594,0.275607,0.349471,0.055581,0.133356,-0.418953,0.162599,-0.179379,-0.366112,-0.133502,-0.379914,-0.319323,-0.695725,0.078239,-0.092880,-0.295598,0.265547,0.046190,0.158328,0.277487,-0.410532,0.199964,0.605793,0.152130,-0.185624,0.538184,0.105643,0.386422,-0.182813,-0.074511,0.243877,0.153458,0.345738,0.082954,-0.015962,-0.185675,-0.046023,-0.303103,0.080790', '1316693', '10466639', '1306449', '2988294');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4023638', '国王的演讲', '剧情', '约克郡公爵（柯林·菲尔斯 Colin Firth 饰）因患口吃，无法在公众面前发表演讲，这令他接连在大型仪式上丢丑。贤惠妻子伊丽莎白（海伦娜·邦汉·卡特 Helena Bonham Carter 饰）为了帮助丈夫，到处寻访名医，但是传统的方法总不奏效。一次偶然的机会，她慕名来到了语言治疗师莱纳尔罗格（杰弗里·拉什 Geoffrey Rush 饰）的宅邸，传说他的方式与众不同。虽然公爵对罗格稀奇古怪的招法并不感兴趣，首次诊疗也不欢而散。但是，公爵发现在聆听音乐时自己朗读莎翁竟然十分流利。这让他开始信任罗格，配合治疗，慢慢克服着心理的障碍。乔治五世驾崩，爱德华八世继承王位，却为了迎娶寡妇辛普森夫人不惜退位。艾伯特临危受命，成为了乔治六世。他面临的最大挑战就是如何在二战前发表鼓舞人心的演讲……©豆瓣', '科林·费尔斯', '汤姆·霍伯', 8.4, 575963, 'tt1504320', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p768879237.jpg', 0.1, 0.6, 12.7, 50.1, 36.4, '-0.051437,0.149376,-0.599046,0.822626,0.143649,-0.304353,0.450236,0.200766,-0.600862,-0.559029,0.435991,0.741364,-0.139924,0.010753,0.321449,0.100041,-0.583536,-0.395422,0.491500,0.101457,-0.073742,-0.706981,-0.066106,-0.632917,-0.367207,-0.493593,0.368151,-0.030619,-0.171909,0.103311,0.249555,0.372971,0.474891,0.460577,-0.140535,-0.116100,0.347944,-0.169894,-0.367212,0.227820,0.233390,-0.217480,-0.233388,0.483299,0.058797,0.281573,0.323853,-0.630380,0.164684,0.070812,0.288358,-0.224598,0.168364,0.414201,0.115926,-0.028354,0.246018,0.358416,0.119782,-0.180704,0.004177,-0.150156,-0.567792,0.005889,0.021729,0.272745,-0.272762,0.385152,-0.410635,0.003560,-0.047600,-0.244084,-0.058303,0.297699,0.286606,0.137746,-0.230553,0.229182,-0.364847,0.026722,0.410668,0.106786,-0.308731,0.172780,-0.241663,-0.514072,0.255999,-0.418192,-0.401164,0.024111,0.025576,0.081649,0.085944,0.420085,-0.364095,-0.218050,-0.678166,-0.190364,0.339589,-0.163655,0.063767,-0.798607,0.075314,-0.120516,-0.141338,-0.227003,0.094801,-0.367153,0.586394,-0.811535,0.178701,0.498590,0.195094,-0.341997,0.523992,0.246462,0.020865,-0.298358,-0.442786,0.503049,-0.025938,0.144285,-0.010935,0.235273,0.355288,-0.072502,-0.024765,0.569652', '3284768', '26259202', '1301172', '3075921');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4023725', '夏天协奏曲', '剧情', '2006年夏天，清苦学生林明宽（张睿家 饰）在网络上看到全台湾钢琴大赛第一名的陈文青（林逸欣 饰）心生好感。而后阿宽见到了来金门过暑假的小青，机缘巧合，两人相识。那个夏天阿宽和好友沙虫（李嘉文 饰）载着小青，游遍了金门风光，在阳光和星空下看见金门的美丽，也一同感受了初恋的酸甜青涩。小青喜欢用手机纪录拍照，一切深刻的画面都纪录在手机里。小青每天练琴的时候，阿宽就在屋外聆听，那是他每天最幸福的时刻。小青跟阿宽过完最美好的暑假，承诺回去后会天天给阿宽E-mail，也承诺明年夏天，会回到他身边！从此每天接收E-mail是阿宽最期待的事，第二年夏天钢琴声果然再次响起，可阿宽却觉得这个小青有所不同。直到有一天阿宽和沙虫经过墓地，看到小青的墓碑，死亡日期竟然是2006年10月18日。这究竟是怎么回事？是恶作剧？还是小青专程回来遵守自己的承诺……©豆瓣', '张睿家', '黄朝亮', 6.8, 23124, 'tt3160290', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p471696374.jpg', 1.5, 8.9, 46.9, 31.5, 11.2, '-0.165579,0.095232,-0.746194,0.511142,0.055415,-0.314869,0.485591,-0.138874,-0.415824,-0.173184,0.044060,0.409700,-0.360832,0.557303,0.169256,0.163521,-0.403914,-0.554498,-0.040079,-0.457062,-0.520898,-0.144775,0.063878,0.083108,0.139655,-0.131347,0.251007,0.043274,0.185506,0.621137,0.255500,-0.305041,0.025172,0.534942,-0.346507,-0.117514,-0.104244,0.282558,-0.234253,-0.046501,-0.050659,-0.325233,-0.278162,-0.073369,0.175480,-0.023285,0.604375,-0.094778,-0.281490,0.015996,0.390449,-0.004591,-0.079489,-0.044449,0.433375,0.102699,0.325218,0.075467,-0.211635,-0.005449,-0.145986,-0.157507,-0.200043,-0.035696,-0.203336,0.091070,-0.424544,0.493010,-0.129505,0.017244,0.316713,-0.505640,0.209257,0.177621,0.072157,0.582636,-0.159472,0.151134,-0.293925,0.127897,0.663170,-0.044107,0.051408,0.328797,-0.080245,-0.551393,0.036377,0.166829,-0.336753,0.215335,0.177264,-0.033831,-0.123780,0.090362,-0.537272,0.177816,0.145954,-0.225045,0.095034,-0.231583,-0.385977,-0.268508,-0.094369,-0.484459,-0.429479,0.269200,-0.057965,-0.347388,0.706989,-0.757700,0.452565,0.432141,0.406601,0.035349,0.790227,0.234290,-0.059534,-0.277410,0.154485,0.124948,-0.243004,0.290884,0.160472,0.277228,0.071450,-0.062980,-0.526082,0.505151', '1306544', '3055049', '26354526', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4030411', '蜗牛餐厅', '剧情', '绰号苹果、居住在奶子山的伦子（柴咲コウ 饰）自幼生长在一个破败的家庭，母亲与男人们纠缠不清，流言不断。倍感难为情的伦子中学毕业后便独自跑到东京奶奶的家中，跟随奶奶学得一手好厨艺。奶奶去世后，伦子努力打拼，力争开一家独具特色的餐厅，结果却被外籍男友骗财骗色。25岁的伦子落寞地回到奶子山，此时母亲靠男人过着养尊处优的生活，只疼爱那头白色的宠物猪，对女儿分外冷漠。虽然屡受挫折，但是伦子依旧没有放弃开餐厅的梦想。奶奶的餐饮秘籍以及奶子山的秀丽风光最终给她以灵感和信心，这个不屈不挠的女孩在这里建造起了属于自己的蜗牛餐厅……©豆瓣', '柴崎幸', '富永麻衣', 7.2, 8150, 'tt1535476', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p563978359.jpg', 0.9, 5.8, 39.5, 39.4, 14.5, '0.146849,0.000738,-0.620104,0.594684,-0.146222,-0.517579,0.754411,0.537037,-0.516818,-0.213507,0.177876,0.617270,0.155935,0.834140,0.017915,0.058967,-0.143019,-0.460787,-0.049163,-0.003400,-0.033943,-0.144147,0.039577,-0.062841,-0.156990,-0.166850,0.506483,-0.020911,-0.017081,0.407800,0.120351,-0.007482,-0.039257,0.363377,-0.550883,0.194062,0.092408,0.184700,-0.151793,0.120427,0.107605,-0.240383,-0.070580,0.078313,0.205736,0.157280,0.813787,-0.228422,-0.316666,-0.111189,0.289186,0.159865,-0.116715,0.249114,0.501414,-0.019164,0.421427,-0.007028,-0.152983,-0.120326,0.108258,-0.318135,-0.357865,-0.108582,0.273621,-0.074470,-0.885067,0.526316,-0.039732,-0.099422,0.047789,-0.634655,0.068455,0.082892,-0.017253,0.615150,-0.459733,0.643798,-0.453211,0.079951,0.522969,-0.005834,0.056543,0.378715,-0.325296,-0.249113,0.228650,-0.372063,-0.695958,-0.067822,0.122490,-0.058674,-0.143544,-0.062591,-0.601246,0.031075,-0.161199,-0.131055,0.176945,-0.398831,-0.422569,-0.314942,0.021858,-0.512245,-0.215200,0.249682,-0.065729,-0.019206,0.829084,-0.797253,0.296146,0.302836,0.341659,-0.214534,0.656842,-0.176567,0.031914,-0.137472,-0.172076,0.484439,-0.315823,0.307977,0.127674,0.420146,-0.195568,-0.139486,-0.576963,0.515513', '25731805', '1292219', '26348103', '3796613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4030657', '勒阿弗尔', '剧情', '马塞尔（安德烈·维尔姆斯 André Wilms 饰）曾经是一个小有名气的作家，可是，热爱自由的他厌倦了作家高高在上的枯燥生活，于是来到了勒阿弗尔，摇身一变成为了一个快乐的擦鞋匠。勒阿弗尔可爱而又热情的居民让马塞尔找到了心灵的归宿，在这里，马塞尔过上了梦寐以求的平静而又安定的生活。一个非洲男孩的出现打破了马塞尔规律的生活，出于同情和本能，马塞尔收留了这个被警察追得到处跑的可怜男孩。屋漏偏逢连夜雨，在此节骨眼上，马塞尔的妻子阿勒提（卡蒂·奥廷宁 Kati Outinen  饰）患上了恶疾需卧床休养，一边是凶神恶煞的警察，一边是病危的妻子，马塞尔一下子被推到了命运的十字路口。©豆瓣', '安德烈·维尔姆斯', '阿基·考里斯马基', 8.1, 9880, 'tt1508675', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1833432884.jpg', 0.4, 1.3, 18.2, 55.1, 25, '0.412380,0.046208,-0.402788,0.408865,-0.224211,-0.271929,0.885441,0.358652,-0.485756,0.167113,0.119009,0.752847,-0.129798,0.475991,0.666544,0.323192,-0.315242,-0.655483,0.246263,-0.063526,-0.302565,-0.381477,-0.363434,-0.259214,-0.180988,-0.496827,0.464437,0.060050,0.065010,0.550445,0.334486,0.530630,0.274791,0.325659,-0.617826,0.096463,0.008663,-0.179371,0.056313,0.208592,-0.128226,-0.045596,0.001795,0.083477,-0.044103,0.378697,0.555194,-0.296611,0.018432,0.076140,0.489682,-0.567977,0.012645,0.017027,0.220260,-0.139681,-0.060186,-0.297466,-0.321959,-0.184517,0.185817,-0.215971,-0.647217,-0.036144,0.055213,0.312999,-0.888740,0.707691,-0.121209,-0.201185,-0.064641,-0.260047,0.292954,0.469309,0.074872,0.731993,0.033892,-0.074145,-0.232181,0.187286,0.600364,-0.209770,-0.412725,0.445550,-0.350098,-0.213129,0.188320,-0.403712,-0.767434,-0.461607,0.250269,-0.097320,-0.373078,0.115737,-0.577561,0.050791,-0.379048,-0.092746,-0.052240,-0.454431,-0.302644,-0.292393,-0.065352,-0.435217,-0.258866,-0.023093,-0.036771,-0.252226,0.781653,-0.613387,0.188259,0.604073,0.059394,-0.396025,0.697559,0.170304,0.281308,0.104688,0.032889,0.477917,0.231573,0.444527,0.257848,0.555890,-0.269294,0.034183,-0.350901,0.609986', '26884422', '4847665', '1297606', '2002744');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4032539', '爱丽丝的失踪', '惊悚', '丹尼尔（马丁·康普斯顿 Martin Compston 饰）和长相彪悍的维克特（埃迪·马森 Eddie Marsan 饰）在狱中相识，维克特胆大凶狠，一心干票大买卖远走他乡。服刑期间他将目光锁定在20岁的富家女爱丽丝·克莉德（杰玛·阿特登 Gemma Arterton 饰）身上，于是出狱后策划和丹尼尔绑架爱丽丝勒索巨额赎金。经过一番缜密策划，他们成功将爱丽丝劫持到事先准备好的公寓。绑架、伪装、制作勒索短片，一切似乎尽在掌握之中，然而短短的几天内意想不到的事情接连发生，两个绑匪和一个人质如同坐在一辆失控的汽车之上，朝着未知的方向急速狂奔，前途未卜……本片为J Blakeson的长片处女作。©豆瓣', '马丁·康普斯顿', 'J·布莱克森', 7, 9890, 'tt1379177', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p790162756.jpg', 0.9, 5.2, 43.3, 42.1, 8.5, '0.284910,-0.049575,-0.733727,0.324031,0.046525,-0.113346,0.831569,-0.090145,-0.181623,-0.300285,0.293963,0.514138,-0.377614,0.003669,0.584221,0.012835,-0.491944,-0.865407,-0.318740,-0.159020,-0.210842,-0.692893,-0.338557,-0.157992,-0.044548,-0.297968,0.404451,-0.031196,0.102411,0.685785,0.432091,0.308051,-0.439069,0.151598,0.026909,0.037247,0.126698,-0.039046,-0.299833,0.356289,0.008279,-0.337210,-0.039029,-0.042459,0.056618,0.386525,0.739621,-0.103509,-0.262903,-0.047835,0.291487,-0.231596,0.023952,0.137135,0.114398,0.251428,0.152805,0.198593,-0.493853,0.019124,0.119420,-0.235879,-0.455856,-0.178574,-0.149958,-0.120249,-0.687933,0.076869,-0.034284,0.031397,0.205080,-0.575644,-0.025311,0.283927,0.294645,0.340640,-0.035160,0.189558,-0.457390,-0.077992,0.610854,-0.106670,0.023240,0.298807,0.389415,-0.175963,-0.050331,-0.077557,-0.363824,0.002219,0.468935,-0.053856,0.097685,0.107067,-0.198621,-0.169904,-0.394264,-0.188663,-0.072404,-0.371020,-0.241409,-0.647885,-0.109382,-0.238079,-0.260771,0.252023,-0.026925,-0.153482,0.213510,-0.399049,0.312527,0.484125,0.205270,-0.262302,0.266946,-0.293002,0.298467,-0.040046,-0.258439,-0.028405,0.383313,0.214959,0.131591,0.224822,-0.154380,-0.066892,-0.409311,0.384002', '1306449', '1292533', '1773217', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4034047', '世界奇妙物语 2009秋之特别篇', '悬疑', '1、检索女加奈子（井上真央饰）平时喜欢随时用手机检索情报，联谊派对上，她认识了名为三宅亮的男子，加奈子在手机上却查到两个“三宅亮”，一个是贵公子，另一个却是杀人犯，眼前的这个到底是？2、自杀者再回收法一男子（生田斗真饰）跳楼自杀，却在半空中被撒网救下，醒来后，他发现自己和一帮人被关在一个密闭的空间，并被宣布将被更有效地为国家利用生命，包括器官移植、做新药临床试验、执行特种任务等。3、理想的火锅和树（伊藤淳史饰）上门求婚，晚餐是他的最爱：日式火锅，可是女友一家的火锅做法和吃法都和他理想中的日式火锅相差了十万八千里。4、诅咒杀人一名家庭主妇（釈由美子饰）以陪审员身份参与一起法庭审判，嫌疑犯被控以诅咒连杀8人的罪名，一开始6名陪审员都感到荒诞不经，但诅咒似乎真的发生了……5、梦的检阅官每个人的梦境都由一支团队检阅和传送至梦中，一名女子丧失了爱子，检阅官（石坂浩二饰）不得不小心翼翼地处理她梦境的内容。', '石坂浩二', '吉田直树', 7.6, 8182, 'tt1528845', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1973453541.jpg', 0.3, 1.9, 31.6, 48.3, 18, '0.379253,-0.037990,-0.274915,0.462923,-0.273373,-0.105736,0.673621,0.228381,-0.273106,-0.307781,0.278322,0.720783,-0.233320,0.068766,0.159838,0.054653,-0.272426,-0.767570,-0.177340,-0.081615,-0.365084,-0.548256,0.074922,-0.228211,-0.004181,-0.101757,0.498381,-0.072691,-0.074195,0.111193,0.409304,0.036413,0.030961,0.437945,-0.148078,-0.286682,0.220201,-0.074562,-0.056792,0.282953,-0.280694,-0.406227,-0.000584,0.319450,-0.041535,0.375038,0.432144,-0.180858,-0.260517,-0.269656,0.211225,-0.267844,-0.354017,0.260415,0.303157,0.155741,-0.001707,-0.009315,-0.170541,0.054842,-0.051195,-0.065564,-0.836054,-0.168920,0.146422,0.099436,-0.278596,0.209911,-0.252690,0.080863,0.142477,-0.145672,0.256958,0.118589,0.380027,0.475269,-0.129681,-0.055695,-0.547600,0.171875,0.468632,-0.076979,-0.112782,0.151322,-0.342127,-0.582184,-0.054719,0.046149,-0.114312,-0.004290,0.016431,0.042784,-0.183132,0.021152,-0.624683,0.071463,-0.155889,-0.297444,-0.059342,-0.448287,-0.326012,-0.567139,0.053639,-0.011206,-0.375613,0.219241,0.232534,-0.238499,0.594110,-0.753469,0.135024,0.535115,0.121574,-0.437092,0.535211,0.314667,-0.005037,-0.262682,-0.020585,0.016203,0.244478,0.324013,-0.009280,0.431857,-0.108541,0.054248,-0.616666,0.289822', '4301278', '1793491', '25928048', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4035906', '三个火枪手', '动作', '在一次行动，三剑客被米莱迪（米拉•乔沃维奇 Milla Jovovich 饰）和白金汉公爵（奥兰多•布鲁姆 Orlando Bloom 饰）背叛暗算，以失败归隐告终乡间。三年后，练就一手好剑术的达达尼昂（罗根•勒曼 Logan Lerman 饰）初出茅庐，来到巴黎投奔火枪队长特雷维尔（马修•麦克费登 Matthew Macfadyen 饰），与三剑客不打不相识，意外成为惺惺相惜的好友，同时也偶遇王后侍女，与之一见倾心。不久后众人意外得知权倾朝野的红衣教主黎塞留（克里斯托弗•沃尔兹 Christoph Waltz 饰）为了自己的灭国计划，想要挑拨英法两国关系，意欲制造一起皇室丑闻，使国王路易十三对王后安娜产生误会。富有正义感的众人为了抗击红衣教主的邪恶阴谋，维护安娜王后的清白，保持英法两国的和平关系，和敌人展开了斗智斗勇的比拼。达达尼昂更是凭借出色的剑术和足智多谋的头脑在这场争斗中崭露头角….该片改编自法国作家大仲马的代表作《三个火枪手》。', '罗根·勒曼', '保罗·安德森', 6.7, 56437, 'tt1509767', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1056072904.jpg', 1.3, 8.9, 51.2, 30.9, 7.7, '0.143844,-0.001657,-0.545369,0.668879,0.193236,-0.270380,0.507021,0.128450,-0.519423,-0.530617,0.361556,0.813114,-0.307000,-0.312973,0.464365,-0.151835,-0.373496,-0.898066,-0.016745,-0.074547,0.147234,-0.493988,-0.325620,-0.272384,-0.363564,-0.465725,0.583229,-0.076465,-0.301702,0.630837,0.363945,0.403850,-0.060216,0.081946,0.061384,-0.022623,0.251143,-0.159665,-0.714043,0.310859,0.006237,-0.132854,-0.286644,0.212192,-0.000397,0.204878,0.453169,-0.493823,0.355664,-0.359987,0.167932,-0.297451,0.045779,0.275343,0.292537,-0.029936,0.275812,0.371097,0.103839,-0.164979,0.105599,-0.167932,-0.600366,0.187930,0.175776,-0.043649,-0.402434,0.570983,-0.306883,-0.038625,0.177072,-0.050043,-0.047380,0.687703,0.527856,0.046969,0.005716,0.144010,-0.431133,-0.158701,0.604016,-0.045335,-0.204369,-0.063674,0.112018,-0.443877,0.068223,-0.356493,-0.312640,-0.055321,0.424550,-0.324997,0.493690,0.653503,-0.629635,-0.247027,-0.555044,0.282762,0.107529,-0.293956,0.264247,-0.697549,-0.240660,-0.399101,-0.198921,-0.049572,0.144389,-0.020996,0.564312,-0.743312,0.004224,0.219505,0.198489,-0.469829,0.317376,0.252579,0.109869,-0.355416,-0.417845,0.401236,0.033637,-0.155352,0.062008,0.237844,0.082181,-0.062904,-0.214759,0.039923', '25978126', '1780122', '4301278', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4036000', '80''后', '剧情', '80’后女孩沈星辰（刘冬 饰）自小家庭不幸，母亲与人私奔，父亲因此车祸死亡，她从小寄居舅舅家。80’后男孩明远（黄明 饰）小时候曾和沈星辰家是邻居，明远父母私下从事走私，明远父亲扛下一切入狱，得知明远母亲跟了别人后在狱中自杀，给明远的内心带来重创。数年后，升至高中的沈星辰和明远被分在同一个班级，儿时的友谊发生了微妙的转变。然而，各自家庭的不幸让两人背负着巨大的心灵创伤，渴望被爱却不懂得如何爱人，关于“爱”与“生命”的思考，也在两人的分分合合中延续。本片改编自网络小说《天长地久》，曾获东京国际电影节大奖提名。导演李芳芳16岁时曾写出青春小说《十七岁不哭》，同名电视剧在当年引起全国中学生热烈追捧。©豆瓣', '刘冬', '李芳芳', 7, 71490, 'tt1538533', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p524307932.jpg', 3.2, 9.7, 37, 34.3, 15.8, '0.207218,0.083404,-0.795865,0.374170,0.072354,-0.440059,0.687326,0.167028,-0.883810,-0.053338,0.188341,0.877534,-0.203032,0.348416,0.125737,-0.162041,-0.200902,-0.882100,-0.054130,-0.073564,-0.117142,-0.525317,-0.039256,0.216691,-0.159388,-0.512664,0.513423,-0.085596,-0.036286,0.629410,0.006794,0.441484,-0.219390,0.121347,-0.197662,0.455548,0.085635,0.574305,-0.719288,0.143367,0.195848,-0.212838,-0.231539,0.071774,0.025014,0.190282,0.695433,-0.140951,-0.339254,-0.307825,0.564678,-0.052323,-0.289577,0.020143,0.263515,0.257140,0.760375,0.215575,0.050324,-0.036074,-0.131158,0.133615,-0.237332,-0.203699,0.435517,0.144242,-0.470606,0.551858,0.027385,-0.027238,0.187959,-0.247688,0.147800,0.384202,0.183911,0.412966,-0.437146,0.089699,-0.305496,0.561880,0.967489,-0.190083,-0.170260,0.330322,-0.434873,-0.179996,-0.019589,-0.336496,-0.732844,0.520256,0.285918,0.112450,-0.200864,0.533691,-0.303837,-0.136187,-0.051910,0.287508,0.247132,-0.665031,-0.314937,-0.330248,-0.456628,-0.502785,-0.157018,-0.266478,0.180532,-0.385098,0.898410,-0.893911,0.570378,0.177460,0.223791,-0.475894,0.640902,0.155650,0.078469,-0.226181,0.422633,0.076066,-0.088300,0.082402,-0.258017,-0.077102,0.053718,0.143187,-0.380786,0.354764', '25721544', '3445516', '35030151', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4038184', '第三颗星', '剧情', '年近三十的詹姆斯（本尼迪克特·康伯巴奇 Benedict Cumberbatch 饰）发现自己患上了癌症，在巨大的打击之下，他开始思考起了生命的意义。在他的回忆里，位于威尔士西部的巴拉方德湾是一个充满了回忆的地方，站在人生的十字路口上，他决定故地重游，重温美好的过往。就这样，詹姆斯和三个好友踏上了前往巴拉方德湾的旅程，他们分别是迈尔斯（JJ·菲尔德 JJ Feild 饰），戴维（汤姆·伯克 Tom Burke 饰）和比尔（Adam Robertson 饰）。作为詹姆斯的好友，迈尔斯一行人有义务陪伴詹姆斯度过人生中最艰难的时刻，然而，这趟略带伤感的旅程对于他们来说有着更加重要的意义。一路上，麻烦接踵而至，四人之间的友情不断的遭受着考验，但他们都明白，人生就如同一场旅行，只要不断向前，就总有达到目的地的那一天。©豆瓣', '休·博纳维尔', 'Hattie Dalton', 8.2, 6822, 'tt1510906', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2261888564.jpg', 0.4, 1.2, 19, 48.9, 30.5, '0.402032,-0.193237,-0.785972,0.608770,0.269311,-0.357842,0.883924,0.000540,-0.515590,-0.067277,0.224553,0.605033,-0.138423,0.409568,0.593103,-0.232120,-0.389041,-0.638768,0.148194,-0.204097,-0.315447,-0.688228,-0.229596,-0.174358,-0.106788,-0.392890,0.503564,0.240792,-0.040630,0.519843,0.212515,0.354920,0.081949,0.523379,-0.106489,0.031405,0.195625,0.211288,-0.361077,0.173761,0.161246,-0.049558,-0.049062,0.297697,-0.148469,0.340905,0.670859,-0.396864,-0.143504,0.164443,0.159591,-0.299980,-0.110612,0.052587,0.053704,0.181230,0.066372,0.335470,-0.195010,0.091241,0.034035,-0.188010,-0.590883,-0.075974,-0.015126,0.234082,-0.682260,0.640198,0.082749,-0.132726,0.163571,-0.422585,0.191841,0.396405,0.369043,0.364221,-0.240994,-0.174099,-0.399304,0.117058,0.766238,-0.029312,-0.307389,0.469108,-0.283197,-0.356388,-0.115248,-0.039263,-0.344286,-0.133935,0.243831,0.117396,-0.075006,0.388912,-0.698748,0.442036,-0.252544,-0.491081,-0.026701,-0.455877,-0.045476,-0.556226,-0.049701,-0.517527,-0.496339,0.301630,-0.031368,-0.423094,0.627955,-0.631627,0.307243,0.652030,0.098884,-0.122348,0.706894,0.071369,0.243319,-0.334074,0.181260,0.478695,-0.267665,0.079689,-0.006822,0.226475,-0.199553,0.141186,-0.415801,0.852594', '1309172', '1292211', '3055049', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4043647', '超级英雄', '剧情', '雷恩·威尔森与艾伦·佩姬曾在《朱诺》中有过合作。衰男法兰克（雷恩·威尔森 Rainn Wilson 饰）的美丽妻子莎拉（丽芙·泰勒 Liv Tyler 饰）和一个名叫雅克（凯文·贝肯 Kevin Bacon 饰）的毒贩搞在了一起，并因此离开了法兰克。这让弗莱克很是崩溃，于是他拉上在当地漫画店里打工的患有精神病的可爱女孩莉比（艾伦·佩吉 Ellen Page 饰）协助他一起，化身一对蒙面英雄组合，誓要打垮毒贩雅克。但莉比与法兰克到底是一起行侠仗义、犀利复仇，只是为了瞎搅和？一切似乎渐渐失控……©豆瓣', '雷恩·威尔森', '詹姆斯·古恩', 6.7, 12164, 'tt1512235', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p866287362.jpg', 3.3, 10.8, 42.8, 31.7, 11.5, '0.219584,-0.308048,-0.465278,0.302329,-0.131041,-0.476404,0.766352,-0.038232,-0.296388,-0.203726,-0.043257,0.669174,-0.243625,0.167637,0.489447,0.374964,-0.541031,-0.750098,0.112605,-0.079432,0.047623,-0.903326,-0.327828,-0.092784,-0.003227,-0.377283,0.401017,-0.459971,0.119502,0.716375,0.488394,0.525545,-0.246554,0.246017,0.091245,0.098961,0.219393,-0.400703,-0.331004,0.089653,-0.079312,0.022696,-0.116727,0.165449,0.148833,0.240232,0.301757,-0.448230,0.303234,-0.139934,-0.056208,0.026350,0.008194,0.076410,0.249182,-0.190537,0.456498,0.054534,-0.268149,-0.091513,0.426313,0.108476,-0.431194,0.435590,0.194811,0.227163,-0.670258,0.159632,0.098187,-0.065278,0.345042,0.043794,0.061958,0.319339,0.324779,0.129510,0.081658,0.057013,-0.395607,-0.037809,0.478791,0.141132,-0.077872,0.236654,-0.130749,-0.090816,-0.082576,0.080982,-0.453746,0.000413,0.202153,-0.173090,0.005325,0.369020,-0.633352,-0.100455,-0.522000,0.095789,-0.264207,-0.214253,0.037327,-0.543974,-0.152958,-0.400833,-0.222534,-0.020070,-0.172726,-0.150477,0.434961,-0.941753,-0.022848,0.462062,0.237213,-0.294177,0.308315,0.357261,0.168748,-0.032010,-0.437173,0.328295,0.184681,-0.037071,0.213984,0.451396,0.155030,-0.045636,-0.209768,0.528496', '1299556', '26340522', '1297239', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4043763', '恋人絮语', '剧情', '《恋人絮语》讲述的是都市中错综复杂的爱恨纠葛，其中包含了暗恋、单恋、不伦恋等不同形态爱情。阿磊（陈奕迅 饰）和阿琪（范晓萱 饰）表面维持着正常的恋爱关系，暗中却与阿兰（林嘉欣 饰）相恋，这一切终被阿琪和阿兰男友阿宝（向佐 饰）发现，这段错位的爱情将何去何从？阿宝也隐藏这自己的秘密，年少时的阿宝（陈伟霆 饰）爱慕同学黎广生(陈家乐 饰)的母亲黎太太（陈洁仪 饰），还曾帮黎太偷拍黎先生（曾志伟 饰）的婚外情；长大后的黎广生（彭于晏 饰）成了牙医，街区洗衣店的店员阿芝(谢安琪 饰)一直暗恋他，每天幻想着各种与黎广生相处的情景，却在现实中无法开口表白……这一系列错综复杂的关系，是否能够修成正果？或许终是剪不断理还乱。©豆瓣', '陈奕迅', '曾国祥', 6, 40065, 'tt1772958', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p758178913.jpg', 3.6, 19.3, 54.2, 19, 3.9, '0.205844,-0.104852,-0.552224,0.584562,0.129117,-0.295416,0.850834,-0.066155,-0.521637,-0.433249,-0.222293,0.166556,-0.547198,0.441413,0.162997,-0.029241,-0.183473,-0.820276,0.038686,-0.067772,-0.165936,-0.449224,-0.359010,0.214616,-0.324995,-0.006209,0.585297,0.083988,-0.210009,0.391953,0.523135,0.141533,-0.439529,0.294228,-0.174172,0.300954,-0.084317,0.318969,-0.402253,-0.400236,0.116918,-0.225586,0.174822,0.091345,0.016323,0.297020,0.708326,-0.317807,0.049891,0.233459,0.350065,0.054288,0.057101,0.234870,0.309895,0.014869,0.373117,0.223909,-0.266215,-0.008014,0.095662,0.156134,-0.508206,-0.082555,0.307644,0.263651,-0.422971,0.418854,0.003245,-0.059464,-0.006564,-0.032605,0.242478,0.363136,0.445683,0.269506,-0.128101,-0.131085,-0.361057,0.328037,0.372921,0.161344,-0.134562,0.509032,-0.351993,-0.388616,-0.437369,0.136612,-0.508932,-0.046287,0.124287,0.029105,-0.023177,0.348637,-0.533587,-0.084100,0.100242,0.248572,0.038603,-0.498080,0.067953,-0.500013,-0.389617,-0.957800,-0.417749,0.010411,0.067177,-0.361716,0.447936,-0.743773,0.058176,0.176865,0.288830,-0.410521,0.611873,0.402220,0.136434,-0.301911,-0.090554,0.450514,-0.174680,-0.135116,0.216985,0.363830,0.145558,0.123279,-0.567693,0.240064', '26354526', '24839498', '30389258', '3033092');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4049700', '茱莉娅的眼睛', '惊悚', '朱莉娅和莎拉（Belen Rueda 分饰）是一对孪生姐妹，这对美丽的姐妹花正当盛年时却罹患功能退化症。1年前，莎拉的双目完全失明，而朱莉娅的视力也在渐渐减退。某个晦暗之夜，莎拉上吊自杀。冥冥中自有感应，朱莉娅心中备感不安，次日她和丈夫艾萨克（Lluis Homar 饰）驱车赶往妹妹的住所，等待他们的恰是难以置信的噩耗。然而种种迹象表明，莎拉似乎并非自杀身亡，她生前的最后一段时光仿佛有一个神秘的男子作陪。朱莉娅尝试着追寻这些蛛丝马迹，她的举止令艾萨克甚为焦躁不安，而种种恐慌也让她的视力加速衰退。在黑暗即将降临的时刻，朱莉娅也隐约感知到一个来去无踪的男子时刻逡巡在自己的身旁……©豆瓣', '贝伦·鲁埃达', '吉列尔莫·莫拉莱斯', 6.9, 19097, 'tt1512685', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2166633569.jpg', 1, 7.1, 47.1, 34.8, 10, '0.067227,0.274027,-0.927848,0.670572,-0.108825,0.040118,1.062435,0.247264,-0.650487,-0.386291,0.355521,0.665390,-0.529393,0.457902,0.215190,0.093838,-0.294558,-0.656841,-0.014681,0.019159,-0.192752,-0.394373,-0.393763,-0.032594,-0.034826,-0.443157,0.374469,0.331539,-0.166498,0.566037,0.249986,0.215933,-0.042162,0.960417,0.087809,0.034972,0.028442,0.115133,0.279984,-0.134525,0.450670,-0.444967,-0.162632,0.388641,-0.202592,0.519961,0.820324,-0.308226,-0.222458,0.098256,0.289146,-0.199355,0.199561,0.337792,0.135478,-0.121013,-0.242003,-0.274522,-0.357344,-0.201060,-0.042785,0.386344,-0.656424,0.336927,0.232497,0.324382,-0.449163,-0.039674,-0.130446,-0.118213,0.332705,-0.234742,0.175419,0.455894,0.204090,0.420368,-0.156804,-0.274694,-0.398903,0.013142,0.358029,0.198617,-0.584483,0.339566,-0.531226,-0.614209,-0.209275,0.543218,-0.488735,-0.299223,0.555747,0.449553,-0.219195,0.444360,-0.376331,-0.048311,-0.207952,-0.103539,-0.303221,-0.568204,-0.090870,-0.645084,-0.075943,-0.761454,-0.295890,-0.010587,0.173052,-0.338269,0.459014,-0.644280,0.454727,0.503375,-0.109768,-0.449729,0.548028,-0.103347,0.072420,-0.267233,-0.109079,0.882206,-0.027661,0.171788,0.153138,0.473449,-0.280055,0.552775,-0.615530,0.855745', '21348112', '1309172', '3742987', '3097044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4051753', '大侦探福尔摩斯2：诡影游戏', '动作', '奥地利皇储突然自杀案件，让沉寂6个月的福尔摩斯（小罗伯特·唐尼 Robert Downey Jr. 饰）再次启动。这次，福尔摩斯有了一个强有力的对手——智力上与福尔摩斯相当的莫里亚蒂教授（杰瑞德·哈里斯 Jared Harris 饰）。为了调查清楚皇储的自杀案件，福尔摩 斯与华生（裘德·洛 Jude Law 饰），在吉普赛占星师西姆（劳米·拉佩斯 Noomi Rapace 饰）的帮助下，和莫里亚蒂展开了在整个欧洲大陆上的较量，从英国到法国、德国……虽然被称为最聪明的人，但是莫里亚蒂教授仿佛能预知福尔摩斯的行踪，都能先一步福尔摩斯逃之夭夭。莫里亚蒂教授死亡名单上的人一个个被抹杀，历史可能就此被改编，面对如此强大的对手，福尔摩斯如何应对？©豆瓣', '小罗伯特·唐尼', '盖·里奇', 7.7, 219143, 'tt1515091', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1327387815.jpg', 0.4, 2.7, 28.4, 49.3, 19.3, '0.474306,0.150359,-0.502452,0.610531,0.208275,-0.511853,0.653916,0.083452,-0.442347,-0.283822,0.116436,0.697459,-0.315775,0.082161,0.524654,-0.048317,-0.470689,-0.511980,0.114986,-0.184245,-0.555774,-0.804727,-0.444377,-0.441180,0.035162,-0.033885,0.526543,0.028654,-0.311957,0.308924,0.233257,0.589084,0.324380,0.400509,0.008939,0.019135,0.202331,-0.203492,-0.224481,0.488892,0.267272,-0.200790,-0.200873,0.254238,-0.096883,0.187738,0.529956,-0.651582,0.143891,-0.095465,0.395399,-0.474167,0.148197,0.311206,0.345688,-0.108676,-0.121794,0.432420,-0.059876,-0.091289,0.181619,-0.151512,-0.623695,0.114361,0.035337,0.338117,-0.416615,0.018973,-0.359327,0.170420,-0.126285,-0.207131,0.066560,0.416617,0.327680,-0.014207,0.005446,0.042029,-0.536500,-0.207641,0.293793,0.091125,-0.504122,-0.020792,0.097241,-0.642689,-0.205714,-0.410042,-0.275365,0.001791,0.437232,0.071369,0.055724,0.386892,-0.434771,-0.299222,-0.437318,-0.091940,-0.306547,-0.465582,0.006096,-0.538247,-0.252601,-0.246360,-0.153916,-0.115596,0.118564,-0.240306,0.704443,-0.497313,0.120886,0.368638,-0.007994,-0.229944,0.380776,-0.096626,0.112938,-0.247312,-0.247544,0.307630,0.332573,0.381499,0.236045,0.523146,0.293301,-0.113990,-0.194945,0.502481', '2998270', '30160393', '26848640', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4058933', '一个明星的诞生', '剧情', '杰克（布莱德利·库珀 Bradley Cooper 饰）是一位小有名气的乡村歌手，但酗酒的恶习屡屡让他的事业停滞不前。一天，在酒吧里，杰克邂逅了名为艾利（Lady Gaga 饰）的驻唱歌女，在艾利的身上，杰克发现了惊人的天赋。曾经，艾利对音乐事业怀有着热情和梦想，可是现实一次又一次的令她失望，久而久之，艾利失去了前进的动力。虽然拥有着出色的创作能力，但是艾利在酒吧里从来不唱自己写的歌，同时她也明白，听众们虽然喜欢她的声音，却对她算不上好看的外表敬而远之。杰克被艾利深深的吸引了，决定帮助她找回初心，在此过程中，两颗孤独的心慢慢靠近。©豆瓣', 'Lady Gaga', '布莱德利·库珀', 7.4, 119055, 'tt1517451', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2524354600.jpg', 0.9, 5.8, 35.3, 39.2, 18.8, '0.215492,0.318268,-0.770066,0.879526,-0.263081,-0.209325,0.927743,0.190874,-0.704145,-0.153689,0.078078,0.816584,-0.135632,0.335143,0.077529,0.201046,-0.162615,-0.675033,0.125367,-0.122572,-0.150604,-0.379587,-0.433368,-0.132515,-0.418102,-0.564082,0.385989,0.211930,-0.198817,0.593050,0.406143,0.083502,0.383618,0.579454,-0.092141,-0.114946,0.097354,-0.119176,0.017438,0.145418,0.201864,-0.250242,-0.258525,0.323915,-0.032697,0.294047,0.762223,-0.188495,-0.202994,0.162499,0.380265,-0.251602,0.064976,0.051580,0.083907,0.205246,0.164335,0.052185,-0.248415,0.015285,-0.019852,0.027007,-0.888461,0.052277,0.132475,0.177339,-0.828757,0.499625,-0.198723,-0.126397,0.096307,-0.294922,-0.077744,-0.154205,0.398167,0.485036,-0.289772,0.209374,-0.389279,0.088051,0.831354,0.089919,-0.467429,0.593728,-0.404181,-0.428295,-0.313976,-0.149321,-0.721353,-0.140504,0.186509,0.185191,-0.202221,0.118232,-0.523037,0.083539,-0.068750,-0.266495,-0.166526,-0.529828,-0.131222,-0.400877,-0.262143,-0.536569,-0.241158,-0.058368,-0.029201,-0.355290,1.053514,-1.072080,0.327625,0.687482,0.180900,-0.345421,0.827198,0.280110,-0.090306,0.001793,-0.317964,0.534307,-0.202594,-0.083378,0.058357,0.521169,-0.107437,-0.268770,-0.581314,0.930669', '3230462', '26283288', '35030151', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4058963', '非常小特工之时间大盗', '喜剧', '表面上， 玛丽莎·柯兹·威尔逊（杰西卡·阿尔芭 饰）有着叫人艳羡的生活…嫁给了著名的特务追踪电视新闻记者，刚生下了一个可爱的小宝宝，还有一对聪明伶俐的继子继女，但其实玛丽莎是个退休的特务。当疯狂的时间控制者（杰里米·皮文 饰）发出警告说要偷走时间并征服全世界的时候，玛丽莎的生活发生了翻天覆地的变化。继女瑞贝卡和继子塞西也被卷入了战争，而他们发现自己无聊透顶的继母居然是曾经最棒的特务。带着令人眼界大开的新奇装备，非常小特务们非常有可能依靠智慧再一次拯救世界，并且让全家人团聚。©豆瓣', '杰西卡·阿尔芭', '罗伯特·罗德里格兹', 5.8, 8951, 'tt1517489', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1437481786.jpg', 6.5, 23.5, 48.9, 14.8, 6.4, '0.088740,-0.166037,-0.515311,0.370140,-0.192540,0.049524,0.839959,0.006493,-0.587182,-0.142572,0.128303,0.762294,-0.415862,0.169128,0.257953,0.179269,-0.318634,-0.756075,0.137139,-0.206440,-0.345557,-0.266901,-0.040698,-0.288925,0.003021,-0.350559,0.399513,-0.099127,-0.109658,0.272505,0.284836,0.120132,0.120574,0.396638,-0.275373,0.020501,0.010468,0.027599,0.087097,0.047407,0.098083,0.167376,-0.180560,0.058975,0.071680,0.230366,0.523367,-0.405291,-0.101432,-0.274032,0.230394,-0.169118,-0.068258,0.125090,0.025933,-0.179693,-0.003559,0.006495,-0.077941,-0.220071,0.283259,-0.051846,-0.788530,0.306472,0.105188,-0.076382,-0.442382,0.129576,0.032541,0.047377,0.208038,-0.148682,0.198918,0.346693,0.284361,0.506557,-0.114018,0.252997,-0.427662,0.035318,0.410356,-0.081667,-0.435618,0.379612,-0.696132,-0.162597,-0.109801,-0.313329,-0.739340,-0.069233,0.259389,-0.154485,-0.313111,0.461028,-0.662443,0.014079,-0.165513,-0.214259,0.144004,-0.475679,-0.115303,-0.534409,-0.195258,-0.553175,-0.375996,-0.062372,0.013840,-0.357461,0.997131,-0.779243,0.110329,0.432606,0.216944,-0.518858,0.766324,0.163939,-0.072525,-0.271213,-0.090292,0.420226,0.153452,0.044389,0.055573,0.443370,0.005516,-0.351633,-0.305366,0.542915', '26348103', '25882279', '24284209', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4059245', '观音山', '剧情', '豆瓣《观音山》官方小站：http://site.douban.com/114064/在四川的小县城里，彷徨着3个充满迷茫的年轻人：远离家庭纷扰的女孩南风（范冰冰 饰）、对父亲（方励 饰）心怀芥蒂的丁波（陈柏霖 饰）以及家庭富裕却得不到半点温暖的肥皂（肥龙 饰）。他们天 天聚在一起玩乐喧闹，品味着青春的快意与失落。因所租的房屋改建，他们辗转租住了京剧演员常月琴（张艾嘉 饰）的房子。这是一个有着坎坷命运的女人，上苍的不公令她与周围的人格格不入，更不要说这几个与之同住一个屋檐下、无论从年龄还是阅历都有着莫大鸿沟的孩子。南风各自的生活中本就烦恼不断，与常月琴更是摩擦重重。然而随着时间的推进，这几个孤独的人儿都从彼此的身上感受到了些微的温暖……2010年第23届东京国际电影节最佳女演员-范冰冰。韩寒和范晓萱两个重量级人物携手助阵为影人创作主题词曲。©豆瓣', '张艾嘉', '李玉', 7.1, 188620, 'tt1745713', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p860965126.jpg', 1.2, 5.6, 40.9, 41.3, 11, '0.169062,-0.207727,-0.625404,0.782598,0.153679,-0.121736,1.033869,0.374908,-0.603293,-0.051564,0.231847,0.715044,-0.186330,0.518565,0.183125,-0.184020,-0.286697,-0.755702,-0.140258,-0.207281,-0.113972,-0.217400,-0.173200,-0.022744,-0.289762,-0.034142,0.676303,0.174887,0.022386,0.564875,0.257508,-0.096413,-0.414357,0.422269,-0.333034,-0.042598,0.110029,0.279332,-0.344374,-0.113720,-0.110018,-0.048944,-0.289065,-0.054067,-0.250681,0.270646,0.771272,-0.232470,-0.038999,0.102849,0.322217,0.091857,-0.179581,0.008013,-0.047424,-0.077670,0.300911,0.286217,-0.150009,0.213148,0.073190,-0.070042,-0.644261,0.168604,0.200747,0.302309,-0.550403,0.809975,0.219379,-0.198573,0.064505,-0.306249,0.222865,0.036452,0.152637,0.610422,-0.487324,0.010037,-0.241341,0.246262,0.523004,0.251341,-0.092131,0.362510,-0.575166,-0.480102,-0.088034,-0.072321,-0.784889,-0.314258,0.141708,0.140013,-0.046378,0.311175,-0.760816,0.241891,0.146581,-0.123316,0.084810,-0.507419,0.006867,-0.670482,-0.291691,-0.691526,-0.315915,0.239126,0.402975,-0.217293,0.977168,-0.730358,0.031988,0.465805,0.149243,-0.362044,0.706454,0.074068,0.086195,-0.084030,-0.333353,0.283425,-0.404919,0.151161,0.022271,0.592213,-0.509020,-0.015796,-0.339350,0.489265', '3811356', '26348103', '24839498', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4061047', '惊恐小镇', '喜剧', '牛仔、印地安和小马共同居住在宁静乡间的一幢大房子中。晴朗的一天，恰逢小马的生日。牛仔和印地安决定为好朋友办一场篝火晚会。印地安通过网络订购50块砖头，结果却阴差阳错变成了50万块。傍晚，小马和朋友、邻居们举行了欢快、热闹的生日晚宴，却没想到那余下的几十万块砖头引发了巨大的灾难。次日，印地安和牛仔在小马的率领下重建房屋，但是他们修到一半的房子第二天总是会被人偷走。越来越多离奇的事情相继发生……本片荣获2009年奥斯汀奇幻电影节观众大奖、2009年葡萄牙埃斯平霍国际动画电影节最佳影片奖、2009年Sitges – Catalonian国际电影节最佳动画片奖。©豆瓣', '斯特凡·奥比尔', '斯特凡·奥比尔', 8.1, 13615, 'tt1433540', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p546354367.jpg', 0.4, 2.5, 19.5, 46.9, 30.7, '-0.099079,-0.116667,-0.694770,0.296766,0.204034,-0.016930,0.466742,0.118290,-0.370911,-0.208877,0.232288,0.899751,-0.771630,0.149965,0.654968,-0.061411,-0.428454,-0.521809,0.118625,-0.194477,-0.181821,-0.175473,-0.176448,-0.134228,0.133995,-0.266227,0.430227,0.456629,0.309828,0.821159,0.238874,-0.055634,-0.037830,0.246587,-0.171624,0.027948,0.330875,0.294449,-0.280465,0.260022,-0.293809,-0.279233,-0.203625,-0.082566,0.413284,0.123315,0.757997,-0.012411,-0.164308,0.041126,0.414801,-0.176843,-0.070165,0.036454,0.457430,0.050911,0.392052,0.205390,-0.207862,-0.020571,0.092419,-0.498442,-0.196292,0.350163,0.002332,-0.100941,-0.433656,0.827174,0.007352,0.119076,-0.118968,-0.257942,0.402237,0.282157,0.219464,0.499060,0.201688,0.043725,-0.617188,0.405543,0.685974,-0.056912,0.034132,0.312054,-0.067731,-0.459626,0.073270,-0.280035,-0.258926,0.287852,0.540280,-0.307335,-0.127027,0.039733,-0.753565,-0.050421,0.015886,-0.742771,0.240502,-0.247283,-0.181439,-0.683470,0.151213,-0.040275,-0.050386,0.141239,0.140560,-0.157396,0.725818,-0.622825,0.315197,0.365109,0.323438,0.039908,0.568396,-0.354377,0.250818,0.043513,-0.043955,-0.331779,-0.243238,0.308115,0.088577,0.277495,-0.046458,-0.377941,-0.339775,0.507109', '26365262', '3139191', '26687241', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4062922', '72家租客', '喜剧', '香港旺角的西洋菜街，商铺林立，游人络绎不绝。哈公（曾志伟 饰）和石坚（张学友 饰）的手机店隔街相望，两家为抢生意各出奇招，互不相让。其实二人多年前本为好友，当年二人智斗包租婆的故事至今仍传为佳话，结果最后却为争小桃红（袁咏仪 饰）反目成仇。如今，已为哈嫂的小桃红和哈公相亲相爱，但在心底对曾经的好朋友石坚也仍关爱有加。两家的儿女们私下也有所往来，并逐渐互生好感。大业主租金要翻三倍，商户们为此伤透脑筋。频频有神秘人从高处扔硫酸水，生活在小街的人们陷入恐慌。为了维护生存的权益，为了还西洋菜街以安宁，商户们决定团结一致，共同捍为自己的家园……本片由邵氏和TVB合作拍摄，因集结两岸三地的100多位明星参演，所以有港版《建国大业》之称。©豆瓣', '张学友', '曾志伟', 6.6, 76669, 'tt1602474', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p936338641.jpg', 1.8, 10.1, 50.1, 29.8, 8.1, '0.012055,-0.076023,-0.556200,0.325070,0.314166,-0.266509,0.522723,0.269954,-0.606352,-0.228279,0.135456,0.783058,-0.222604,0.083014,-0.058974,-0.291185,-0.256392,-0.571852,-0.126816,-0.028699,0.162301,-0.331570,-0.161279,-0.128352,-0.520107,0.145563,0.344374,0.047375,-0.137282,0.464200,0.316681,-0.026690,-0.302992,0.111247,-0.221343,-0.087755,-0.057317,0.245136,-0.651384,-0.209466,-0.368988,-0.169350,-0.502500,-0.164443,0.157308,0.601995,0.503849,-0.083366,-0.184823,-0.097371,0.091121,-0.035862,-0.013764,0.104687,0.256123,0.167938,0.462935,0.229676,-0.196825,0.015132,0.075602,-0.000600,-0.585984,0.158057,0.414940,-0.046291,-0.497674,0.629788,0.161581,-0.233785,0.055461,-0.149170,0.026350,0.415253,0.219344,0.128143,-0.229014,0.150998,-0.393951,0.182166,0.698627,0.102727,0.094034,0.208749,-0.247952,-0.311508,0.084163,-0.102885,-0.438626,-0.246566,0.175233,0.052868,0.120123,0.485292,-0.808169,0.145742,-0.048618,-0.146873,0.279122,-0.335614,0.119313,-0.730902,-0.285090,-0.560077,-0.206205,0.126094,0.397011,-0.085861,0.904098,-0.613113,-0.024943,0.137133,0.283497,-0.858975,0.657961,0.405620,0.100353,-0.109308,-0.505590,-0.004805,-0.059957,0.134042,0.056820,-0.110222,-0.273658,-0.181353,-0.156644,0.115762', '4301278', '1296770', '1294009', '26646649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4066125', '谜一样的双眼', '剧情', '本杰明·艾斯玻希多（里卡杜·达林 Ricardo Darín 饰）是一名退休的检察官，几十年的司法工作经验让他积攒下诸多素材，而多年前一起奸杀案始终让他念念不忘，他希望将其付梓出版，了却心愿。25年前，23岁的美丽女教师莉莉安娜·科洛托（Carla Quevedo 饰）和银行职员里杜卡·莫拉莱斯（帕博罗·拉格 Pablo Rago 饰）相识相恋，然而就在两人已谈婚论嫁之际，莉莉安娜在公寓被人残忍强暴并杀害。是时司法腐败，为求尽快结案，本杰明的同事甚至随便找个外来移民顶罪。也许是为莉莉安娜死亡现场所震撼，本杰明执着地展开调查，从此卷入这桩扑朔迷离的爱恨疑案之中……本片荣获2010年第82届奥斯卡金像奖最佳外语片奖；2009年哈瓦那电影节观众奖、最佳男主角奖（Ricardo Darín）、最佳导演奖、最佳音乐奖、评审团特别奖。©豆瓣', '里卡多·达林', '胡安·何塞·坎帕内利亚', 8.2, 87879, 'tt1305806', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p452819688.jpg', 0.5, 1.8, 16.7, 47.2, 33.8, '-0.028390,-0.107360,-0.408181,0.326107,0.021825,-0.478859,0.455207,-0.130085,-0.411072,-0.134964,0.118086,0.808333,-0.322108,0.313675,0.396501,0.048102,-0.567201,-0.833996,-0.082325,-0.296711,0.066216,-0.435863,-0.304083,0.119972,-0.272185,-0.201523,0.546929,-0.113736,0.157459,0.375262,0.533819,0.135083,-0.179588,0.231256,0.194123,0.008823,0.534592,-0.118686,-0.447913,0.380485,-0.073520,-0.376994,-0.249086,-0.028753,0.127908,0.244603,0.614985,-0.094688,-0.067877,-0.153765,0.613503,-0.306676,-0.069984,0.173782,0.284008,-0.014446,0.273882,0.336659,-0.310242,-0.008538,0.170206,-0.232033,-0.566296,0.142721,0.178113,0.031705,-0.290216,0.136327,-0.113499,0.282137,0.006345,-0.004966,0.047827,0.276481,0.416407,0.027471,-0.046238,-0.097009,-0.152545,0.652709,0.497483,-0.026171,-0.360831,0.008995,-0.185600,-0.608893,0.072873,-0.119586,-0.411954,0.041882,0.342876,0.196313,0.113644,0.311569,-0.263552,-0.166491,-0.376015,0.106515,-0.057414,-0.128965,-0.001692,-0.632051,-0.136972,-0.024568,-0.280585,-0.147197,0.136655,-0.431469,0.551070,-0.135948,0.470343,0.512168,0.285985,-0.157394,0.747085,0.105549,0.259183,-0.070601,-0.236523,0.374002,-0.247416,0.186009,0.044363,0.169697,-0.053423,-0.329786,-0.103419,0.374231', '1297368', '1302279', '1780122', '1829654');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4066127', '爸...你好吗？', '剧情', '这是一部由十个小故事组成的短片集。面对不同的社会横截面，父亲的样子往往是相通的。无法带孩子入院看病的穷爸爸、身为黑帮老大的富爸爸、对自己都无力负责的失业小父亲、子孙满堂的喧嚣中寂寞的老父亲，清晨下班还骑着三轮车载孩子赶火车的工人父亲，为救孩子在海中身亡的悲剧父亲……十位父亲，无私，近无我，就算与孩子之间的交流总会隔膜，但无处不满溢着浓浓的爱。本片被选为2009年台北电影节开幕影片。©豆瓣', '高捷', '张作骥', 8.2, 7700, 'tt1519641', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p459565569.jpg', 0.3, 2.2, 19.1, 46.1, 32.3, '-0.084857,-0.317799,-0.770045,0.458864,-0.171372,-0.220602,0.697794,0.048834,-0.439386,-0.127845,0.163294,0.683796,0.121945,0.684607,0.031105,-0.067019,-0.091603,-0.412194,-0.297389,-0.132908,-0.285990,-0.333555,-0.024377,-0.180217,-0.159287,-0.164526,0.717499,0.038152,-0.002506,0.394269,0.404400,-0.003484,-0.225844,0.254699,-0.296165,-0.099255,-0.171910,0.135713,-0.235384,-0.070930,0.183877,0.001561,-0.089382,-0.130319,0.056369,0.303532,0.761895,-0.154027,0.053953,-0.206899,0.302229,-0.151962,-0.130578,-0.151642,0.165484,0.221422,0.494747,0.273424,-0.002624,-0.002403,-0.071944,-0.102776,-0.516056,0.114642,0.281094,0.064158,-0.642547,0.528928,-0.077506,-0.274603,0.323520,-0.372853,0.202696,0.124342,0.059554,0.984050,-0.125714,0.264714,-0.507014,0.201252,0.746527,-0.160769,-0.174546,0.348590,-0.411111,-0.153214,0.115480,-0.588148,-0.751148,0.119218,-0.095222,-0.221363,-0.284771,0.404791,-0.210910,0.149890,0.001360,-0.032025,0.003554,-0.319539,0.104172,-0.335686,0.165659,-0.427880,0.001936,0.282414,0.528264,-0.154850,0.993713,-0.505291,0.496932,0.274970,0.393219,-0.513107,0.968801,0.304991,0.026205,-0.479905,0.095525,0.224683,-0.161981,0.117763,0.172797,0.007523,-0.142913,0.039460,-0.253267,0.411317', '25738406', '25882279', '26348103', '1945253');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4066206', '全城热恋', '喜剧', '本片讲述了6段烈日中的爱情故事：香港的中年司机（张学友 饰）因故结识了深圳的洗脚妹（刘若英 饰），两人日久生情；深圳，Wasabi（徐若瑄 饰）一直苦等酱油师傅（吴彦祖 饰）对爱的回应，但对方却心怀苦衷；香港，海滩卖遮阳伞的大叔（刘家辉 饰）推销笑话，但内心始终牵挂着亡妻；深圳，修理工阿威（谢霆锋 饰）邂逅了飞车女（徐熙媛 饰）碰撞出了火花；北京摄影师（段奕宏 饰）对模特的表现不满，后者负气离去，而他却突然失明，在助手（付辛博 饰）的陪伴下，他们追到深圳，各怀心事；20年前的镇江，乡下男孩（井柏然 饰）爱慕纺织女工（Angelababy 饰），并接受了在烈日下苦等100天的爱情誓约……本片由众多位明星联袂出演，其中不乏张曼玉、阿Sa、余文乐、容祖儿等友情客串。©豆瓣', '张学友', '夏永康', 6.2, 246608, 'tt1519640', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p485353992.jpg', 2.3, 14, 57.3, 21.6, 4.7, '0.000864,-0.175512,-0.435124,0.328482,0.199359,-0.249617,0.544801,0.388946,-0.204202,-0.111225,0.356924,0.590423,-0.404843,0.436035,0.217086,-0.129968,-0.254613,-0.464644,0.187559,-0.065209,-0.042084,-0.128476,-0.173582,-0.016299,-0.393319,0.016529,0.412515,0.121088,0.094901,0.708400,0.691685,-0.037978,-0.169513,0.429584,-0.081911,0.083927,0.080799,0.252047,-0.287996,0.020328,-0.152859,-0.420708,-0.067195,-0.079405,0.029687,0.367211,0.616545,0.060510,0.198873,0.079907,0.183096,-0.088243,0.158085,-0.080893,0.150248,0.077639,0.234399,0.067148,-0.114944,0.054730,0.001482,0.133972,-0.194300,0.166565,0.141970,0.132767,-0.599163,0.397580,-0.079666,-0.128120,0.019908,-0.187838,0.149347,-0.273092,0.265891,0.371533,-0.131422,0.136254,-0.235794,0.725832,0.164251,0.146259,-0.034960,0.529796,-0.261377,-0.380467,-0.084514,0.165391,-0.529783,-0.072140,0.204517,-0.072360,0.109232,-0.269407,-0.458868,-0.125231,0.013893,0.163802,-0.158828,-0.409757,0.010575,-0.804747,-0.044803,-0.636657,-0.133425,0.069423,0.330683,0.285763,0.643297,-0.551876,-0.013751,0.335468,0.248097,-0.456075,0.714856,0.267415,-0.155838,-0.279701,-0.071478,0.331803,-0.255643,-0.257100,-0.085456,0.324126,-0.256407,-0.057955,-0.295347,-0.003306', '1418179', '3811356', '1908036', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4067285', '空想新子和千年的魔法', '剧情', '昭和30年，位于山口县的防府市，是一个依山傍水、空气清新的美丽所在。就读小学三年级的青木新子（福田麻由子 配音）自幼生长在这里，她最喜欢听爷爷讲述的关于这个小町千年前古国国筑的故事。某天，一个来自大都市的转学生走入新子所在的班级。这个名叫岛津贵伊子（水沢奈子 配音）有着白皙的皮肤，受过良好的教育，与土生土长的孩子们截然不同。新子与略显拘谨的贵伊子结为好友，更带领贵伊子融入了这片充满了幻想和魔法的田园生活……本片根据高樹のぶ子的自传体小说《マイマイ新子（空想新子）》改编，并荣获2010年第14届日本文化厅传媒艺术节最佳动画片奖。©豆瓣', '福田麻由子', '片渊须直', 7.7, 8122, 'tt1517216', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2198419957.jpg', 0.4, 3, 29, 45.9, 21.6, '0.262561,-0.319913,-0.322620,0.720669,0.328954,-0.090555,0.389657,0.129464,-0.481761,-0.422058,-0.091762,0.784266,-0.159276,0.473110,0.366401,0.070681,-0.191680,-0.384334,-0.219631,-0.295012,0.034427,-0.234346,0.041061,0.391302,-0.143415,-0.271639,0.929918,-0.106291,-0.340874,0.668848,0.094338,0.313718,-0.121841,-0.265131,-0.255222,0.097415,0.104307,0.243738,-0.132126,0.233513,-0.361091,0.002235,0.009545,-0.204956,0.185988,0.210020,0.616706,-0.058053,-0.102554,-0.216384,0.532179,-0.153877,-0.489452,0.192157,0.375986,-0.070124,0.236967,0.165755,-0.248135,0.194234,-0.238601,-0.533119,-0.468607,-0.201736,0.341696,0.142489,-0.321269,0.489549,0.405657,-0.491101,0.134033,-0.339994,0.199572,0.239924,0.005363,0.383453,-0.255232,0.260893,0.015298,0.260041,0.463636,-0.043418,-0.163463,0.333662,-0.168526,-0.538903,-0.077125,0.028927,-0.238428,0.076250,-0.131754,-0.017615,0.002613,0.156097,-0.752098,0.066606,0.208308,-0.435299,0.480441,-0.253158,-0.236942,-0.692786,-0.152304,-0.585955,-0.104627,0.028632,0.171539,-0.229846,1.010961,-0.935552,0.126852,0.215220,0.239545,-0.099307,0.639121,0.207350,-0.004492,-0.254132,-0.204341,0.501283,0.085500,0.398542,-0.328863,0.563918,-0.321705,-0.230752,-0.606690,0.303900', '10174444', '25922902', '3811356', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4068816', '蛇舌', '惊悚', '游荡在东京涉谷街头的19岁女孩路易（吉高由里子 饰）对生活充满绝望，某日她在迪斯科中邂逅朋克青年阿玛（高良健吾 饰）。阿玛穿钉打孔、纹身分舌，造型时尚前卫。在阿玛的介绍下，路易对蛇舌颇感兴趣。他们一同来到纹身师阿柴（ARATA 饰）的小店，穿钉和纹身的痛楚让路易体验到前所未有的快感，而双性恋且有着虐待欲的阿柴也被眼前这个娇小的女子迷住。和冷峻的甚至有些阴森的阿柴不同，阿玛外表恐怖，而内心温柔。他深爱路易，甚至为了心爱的女人和黑社会分子大打出手，这却为他的悲剧埋下了伏笔……©豆瓣', '吉高由里子', '蜷川幸雄', 6.8, 17857, 'tt1254249', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p700066069.jpg', 1.8, 9.4, 45.9, 30.5, 12.5, '0.043775,-0.187154,-0.663845,0.646856,-0.421313,-0.135618,1.119780,0.226319,-0.410181,0.023856,0.560296,0.688296,-0.489386,0.365708,0.414328,0.338456,-0.043190,-0.745815,-0.019445,0.039529,-0.266316,0.048490,-0.185961,-0.182928,-0.081423,-0.408188,0.645989,0.079817,-0.081115,0.592679,0.557706,0.414239,-0.053912,0.410905,-0.474724,-0.142001,-0.181568,-0.139786,0.137994,-0.115655,-0.024961,-0.103288,0.064401,0.230605,-0.456182,0.287971,0.817553,-0.393152,-0.025068,-0.138162,0.405507,0.107505,0.016524,0.450771,-0.189424,0.038675,0.129178,-0.001098,-0.155804,-0.104072,0.289902,-0.034386,-0.448480,0.181572,0.055786,0.261804,-0.457866,0.701080,-0.156766,-0.103125,0.262185,-0.249643,0.060751,-0.146007,0.257367,0.510024,-0.189753,0.176257,-0.314254,0.086754,0.286840,0.276101,-0.185390,0.160197,-0.535965,-0.237464,-0.040284,-0.185306,-0.413079,-0.100356,0.212234,-0.162021,-0.152762,0.286131,-0.851925,-0.101342,0.074084,-0.025870,-0.011017,-0.366960,-0.390557,-0.332587,-0.451344,-0.873055,-0.246337,0.213540,0.361583,-0.077818,0.305094,-0.704893,0.075021,0.594071,0.255895,-0.379041,0.683324,0.067059,-0.266821,-0.160718,-0.452200,0.510094,0.010237,-0.044183,-0.012190,0.647147,-0.244572,0.198818,-0.638286,0.811072', '21442760', '1467779', '24839498', '1299261');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4071762', '芭比与三剑客', '动画', '动画改编自法国作家大仲马的同名小说《三剑客》。科琳娜（Kelly Sheridan 配音）出生在一个民风淳朴而又保守的小镇之中，从小，科琳娜的性格就有些像男孩子，勇敢而又执着。她一直梦想着能够前往大都市巴黎，在那里成为一名剑客，然而，在那个年代，女孩子想要成为剑客，那简直就是一件不可能发生的事情。幸运的是，科琳娜结识了三位和她志同道合的姑娘们——艾拉米娜（Kelly Sheridan 配音）、薇薇卡（Cassidy Ladden 配音）和蕾妮（坎迪斯·麦克卢尔 Kandyse McClure 配音），三人一拍即合，决定相互帮助，实现她们彼此的梦想。在巴黎，三个姑娘不仅女扮男装，混入化装舞会，甚至在机缘巧合之下拯救了王子的性命，充满了刺激的冒险就此拉开序幕。©豆瓣', 'Kelly Sheridan', 'William Lau', 8.2, 5724, 'tt1484922', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2501852105.jpg', 0.3, 1.7, 21.5, 38.7, 37.8, '0.540878,-0.034491,-0.472615,0.609654,-0.058500,-0.205948,0.443179,0.041690,-0.177836,-0.246891,0.411531,1.005261,0.034054,0.247316,0.332073,-0.051291,-0.311828,-0.591183,0.090359,-0.326081,-0.058456,-0.467784,-0.079886,0.014983,-0.138061,-0.512140,0.707254,-0.105157,-0.112499,0.477465,0.507210,0.234703,-0.208770,0.206673,-0.099213,-0.038949,0.532189,0.037633,-0.391667,0.456459,0.038198,0.235603,-0.247515,0.043023,0.033144,-0.000405,0.592649,-0.368463,0.056154,-0.035193,0.463676,-0.269180,0.112902,0.012169,0.240275,-0.308398,0.333616,0.033141,-0.042196,0.110204,0.240092,-0.145141,-0.624150,0.273124,0.311325,0.142479,-0.492683,0.250140,0.058346,-0.127186,0.136893,-0.329903,0.170091,0.351877,0.283533,0.247588,-0.077381,0.003868,-0.482690,0.390930,0.851836,0.140650,-0.514530,0.343825,-0.193971,-0.487269,-0.139796,-0.241370,-0.767998,0.026797,0.306917,-0.239134,-0.237862,0.299557,-0.537610,0.126333,-0.263724,-0.058349,0.078819,-0.370332,0.075010,-0.626452,-0.143178,-0.187163,-0.082169,-0.180741,0.072722,-0.424198,0.962949,-0.962230,0.008102,0.685729,0.173633,-0.451691,0.789908,0.295575,0.135237,-0.067541,-0.216740,0.471584,-0.113810,-0.042625,-0.071858,0.425408,-0.062493,0.026895,-0.374961,0.436352', '1292720', '3811356', '1870681', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4071781', '克里蒂，童话的小屋', '动画', '纳塔将满7岁，却一直不能识字。他对姑妈遗留给他的藏书失望不已。直到夜晚降临，书中的人物纷纷现身，告知纳塔他们面临永远消失的危险。于是纳塔投身于一场冒险，来拯救他的朋友和他们的故事。他来得及读出拯救他们的咒语吗？', '让娜·莫罗', '多米尼克·蒙法尼', 8, 6296, 'tt1429430', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2134908313.jpg', 0.2, 1.5, 23.2, 49.9, 25.2, '0.370030,0.119448,-0.762905,0.466443,-0.198816,-0.056851,0.682706,-0.330106,-0.635081,-0.267338,0.212331,1.005613,-0.088239,0.130760,0.223221,-0.017616,-0.569523,-0.590204,0.203520,-0.026389,-0.220941,-0.216380,-0.181045,-0.253704,0.033541,-0.291122,0.326432,0.331582,-0.000082,0.517507,-0.120805,0.229219,-0.172050,0.705503,0.046139,0.169010,-0.121144,0.154077,-0.393497,0.282322,0.033448,-0.015906,-0.554858,0.247242,-0.306950,0.331456,0.373066,-0.227922,0.040135,0.142410,0.360292,-0.750988,-0.079778,0.050116,-0.157452,-0.106314,-0.041777,0.169271,0.022826,0.049670,-0.206434,-0.017709,-0.958857,0.010658,0.208855,0.319662,-0.522137,0.161555,-0.099877,0.050049,0.219230,-0.322345,0.278238,0.166194,0.059366,0.291345,-0.269390,-0.258615,-0.551990,0.221171,0.749584,-0.513297,-0.021827,-0.053817,-0.085029,-0.478531,0.105022,-0.209225,-0.537156,0.050090,0.201552,0.152933,-0.419867,0.353039,-0.470061,-0.453591,-0.178398,-0.567150,0.041799,-0.547117,-0.016767,-0.291649,-0.077637,0.121333,-0.417251,0.271084,-0.054265,-0.374594,0.778267,-0.494471,0.618660,0.374762,0.304004,-0.303277,0.715718,0.300586,0.144065,-0.278553,-0.285142,0.572871,0.124870,0.451476,0.068842,-0.250634,0.247302,-0.022281,-0.529042,0.468145', '30163500', '34890458', '30162520', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4074009', '花水木', '剧情', '1996年，北海道道东。因一次不容错过的考试，美丽的女孩平泽纱枝（新垣结衣 饰）邂逅了阳光爽朗的男孩木内康平（生田斗真 饰）。不过这次相逢并不顺利，康平因驾驶汽车出了车祸延误了纱枝的考试，自己也被学校责令退学。糟糕的开始并非有一个糟糕的结局，康平与纱枝由此相知相恋，结为情侣。随着毕业的临近，他们的感情也面临着考验。康平继承家业，成为一名与大海搏斗的渔夫，纱枝则经过艰辛的备战，考上了东京的名府早稻田大学，时间和空间成为他们之间最大的障碍。在此期间，康平的家面临破产，生计举步维艰。纱枝也在求职的道路上不断受挫。两人的恋情似乎慢慢走向了消亡……本片创意来自根据一青窈的同名歌曲。©豆瓣', '新垣结衣', '土井裕泰', 7.2, 52769, 'tt1629284', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p640233159.jpg', 0.6, 5.2, 41.2, 38.7, 14.2, '0.422597,0.049884,-0.647503,0.296113,0.201599,-0.329861,0.661810,0.180592,-0.238454,-0.046892,0.270113,0.647263,-0.205376,0.171727,0.284889,-0.213244,-0.327274,-0.741429,0.169252,-0.176697,-0.139961,-0.516184,-0.026671,0.326156,-0.084161,-0.184678,0.859940,0.277977,-0.004226,0.853264,-0.029418,0.198367,-0.042874,0.257520,-0.136207,-0.014514,0.069161,0.404733,-0.357269,0.122423,0.011688,-0.279040,-0.113466,-0.087870,-0.016328,0.410864,0.785136,-0.081195,-0.203786,-0.055800,0.593050,-0.268512,-0.204448,0.061729,0.521453,0.050375,0.020421,0.476597,-0.312690,0.057019,-0.305513,-0.105959,-0.728330,0.157306,0.206780,0.105799,-0.219428,0.622787,0.183563,-0.414677,0.103129,-0.445479,0.001867,0.561869,0.441624,0.327176,-0.528585,0.316784,-0.406410,0.135358,0.942625,0.003339,-0.341449,0.349330,-0.076975,-0.343908,-0.019541,-0.165573,-0.380665,-0.007673,0.308693,0.122464,-0.081699,0.220200,-0.511724,0.169191,-0.334656,-0.158514,0.081310,-0.121998,-0.142974,-0.497953,-0.032162,-0.474396,-0.443893,0.015001,0.091449,-0.330857,0.786133,-0.700812,-0.032159,0.472262,0.500190,-0.417062,0.524042,0.233668,0.412581,-0.284198,-0.074825,0.156932,-0.244015,0.303485,0.091118,0.348569,-0.093082,-0.006308,-0.348425,0.428466', '3811356', '1826173', '35030151', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4074292', '凉宫春日的消失', '喜剧', '距圣诞节仅有8天时间，SOS团在凉宫春日的号召下，不出意料地策划了一场圣诞狂欢派对。但就在12月18日这天早晨，阿虚却发现周围的世界有了些许变化。1年9班消失不见，朝比奈学姐视其形同路人，甚至早已死去的朝仓也代替凉宫春日坐在了阿虚的后面，而春日则如同人间蒸发一般无人知晓。当他冲向SOS团的教室时，只看到了孤零零坐在角落里看书的长门有希，一向淡定自若、冷如冰霜的长门大神也变成了怯懦害羞的乖乖女。从前一日长门留下的蛛丝马迹中，阿虚判断出这个世界似乎被某人重组了一番。此时的阿虚，握有连接两个绝然不同世界的钥匙，他面临着重大的选择……©豆瓣', '平野绫', '石原立也', 9.1, 33261, 'tt1572781', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2246432125.jpg', 0.4, 0.8, 7.5, 25.3, 66, '0.405273,0.324276,-0.589249,0.136165,-0.150606,-0.183491,0.745857,0.267254,-0.310714,-0.137904,0.090465,0.518697,-0.457943,0.485027,0.294798,-0.165278,-0.414534,-0.804469,-0.483873,-0.487499,-0.182612,-0.499538,-0.083877,-0.086922,-0.057449,-0.230437,0.734527,0.220499,0.158066,0.469291,0.064209,-0.047200,-0.100813,0.663207,0.072298,-0.060265,-0.002016,0.430513,0.297049,0.363373,-0.031579,-0.148735,-0.435310,0.182601,-0.080697,0.389384,0.780401,-0.520607,-0.358097,-0.134902,0.532415,-0.115304,-0.206928,0.027218,0.707758,0.077982,-0.095810,0.123754,0.005283,-0.035484,0.019339,0.009379,-0.315262,0.186824,-0.021700,0.341336,-0.265712,0.589449,0.066804,-0.104086,0.131053,-0.626449,0.414878,0.309548,0.407787,0.474870,-0.376835,0.140440,-0.384027,0.056478,0.321165,0.189823,-0.526729,0.400829,-0.246594,-0.144965,-0.265317,-0.052781,-0.237895,-0.071518,0.160699,0.211050,-0.215668,0.112777,-0.419638,0.066739,-0.113416,-0.252515,-0.186172,-0.297270,-0.403734,-0.775366,0.042537,-0.103875,-0.247150,0.440039,0.103554,-0.144860,0.677597,-0.930377,0.356601,0.208045,0.153460,0.139875,0.625182,-0.007923,-0.203613,-0.097689,0.078989,0.353547,-0.135615,0.422632,0.228618,0.471397,-0.196361,0.082092,-0.508713,0.405418', '1826173', '2245683', '26999591', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4074733', '禁运品', '剧情', '克里斯·法拉德（马克·沃尔伯格 Mark Wahlberg 饰）曾是无所不能的走私高手，如今已金盆洗手，与妻子凯特（凯特·贝金赛尔 Kate Beckinsale 饰）和两个儿子过着隐世生活。直到有一天，凯特的弟弟安迪搞砸了一单毒品交易，凶残无情的老板蒂姆·布里格斯（吉奥瓦尼·瑞比西 Giovanni Ribisi 饰）威胁要让他们付出惨痛代价。为了帮安迪还清债款，克里斯只好重出江湖，召集了老搭档塞巴斯蒂安·艾比尼（本·福斯特 Ben Foster 饰）和丹尼·雷默（卢卡斯·哈斯 Lukas Haas 饰），决定前往巴拿马偷运假钞。途中却不巧遇到了克里斯父亲的冤家船长（J·K·西蒙斯 J.K. Simmons 饰），后者更是收了老板的好处要监视克里斯完成任务。而与此同时，在家中的凯特和儿子们也受到了来自杀手的威胁，甚至是艾比尼的冒犯。面对着计划变故，老板紧逼，警察追踪还有家中妻儿的一线安危，克里斯能否生出三头六臂，最终挽救局面呢？本片翻拍自2008年冰岛犯罪片《雷克雅未克-鹿特丹》。', '马克·沃尔伯格', '巴塔萨·科马库', 6.5, 12387, 'tt1524137', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1312526233.jpg', 0.8, 8.1, 60.1, 25.6, 5.4, '0.058201,-0.185048,-0.411209,0.439368,0.175084,-0.605811,0.435549,0.376844,-0.357623,-0.342172,0.236561,0.487947,0.003064,-0.149089,0.429467,0.186405,-0.550007,-0.401463,0.095866,-0.251094,-0.135168,-0.746441,-0.430806,-0.465181,-0.069188,-0.436305,0.223964,-0.042153,0.068584,0.366805,0.514639,0.463944,-0.017149,0.352670,0.156326,0.142973,0.343762,-0.234397,-0.507412,0.293344,0.031151,0.018419,-0.372665,0.149393,0.378896,0.513762,0.342984,-0.232004,0.113481,-0.281822,-0.269630,-0.195734,0.242325,0.025398,0.042862,-0.450793,0.198038,0.543802,-0.226622,0.079112,0.305422,-0.145298,-0.622019,0.018778,-0.001069,0.109641,-0.635370,0.206510,-0.495457,0.181666,0.080575,-0.383109,-0.050341,0.296100,0.085122,0.166295,0.055104,-0.036046,-0.550825,-0.017540,0.599568,-0.322918,0.082973,0.154449,-0.170224,-0.230941,-0.204482,-0.344553,-0.579775,0.181313,0.401837,-0.073810,0.115951,0.534418,-0.419623,-0.303120,-0.680455,-0.113801,-0.061123,-0.172778,0.091034,-0.637567,-0.016456,-0.165980,-0.315191,0.007699,0.016620,-0.065175,0.484369,-0.534646,0.178571,0.539665,0.170094,-0.347335,0.314501,0.169569,0.185785,-0.319876,-0.291074,0.102129,0.187530,0.176166,0.210762,-0