INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4075568', '假期历险记', '喜剧', '鲁斯蒂（艾德·赫尔姆斯 Ed Helms 饰）和妻子黛比（克里斯蒂娜·艾伯盖特 Christina Applegate 饰）结婚多年，两人共同养育了两个孩子詹姆斯（斯凯勒·吉桑多 Skyler Gisondo 饰）和凯文（斯蒂尔·斯特宾斯 Steele Stebbins 饰），随着时间的流逝，激情渐渐淡漠，鲁斯蒂决定带着家人一起驱车前往亲子圣地威利鹿乐园，以修补彼此之间的亲情。就这样，一家人上路了，迎接他们的，是各种各样的挫折和意外，再加上鲁斯蒂的妹夫斯通（克里斯·海姆斯沃斯 Chris Hemsworth 饰）——一位“风情万种”的金发肌肉男的掺和，他们一行人真的能够顺利的抵达目的地吗，而这趟旅途所带来的结果，又是否能够如鲁斯蒂所愿呢？©豆瓣', '艾德·赫尔姆斯', '乔纳森·M·戈尔茨坦', 7.3, 27844, 'tt1524930', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2258450504.jpg', 1, 5.6, 37.2, 40, 16.1, '0.324948,-0.099059,-0.539167,0.641805,0.002496,-0.577042,0.473462,0.311845,-0.427456,-0.270109,0.062101,0.778003,-0.133918,0.211107,0.316230,0.046859,-0.617400,-0.532949,0.182887,-0.215771,-0.388940,-0.565420,-0.076877,-0.304873,0.203163,-0.289664,0.399393,-0.072775,0.325530,0.821820,0.248378,0.112552,-0.255107,0.271490,-0.210683,0.090104,0.327015,0.121941,-0.434879,0.355587,0.218338,0.290083,-0.182169,0.051771,0.165704,0.214994,0.669297,-0.231614,0.075736,-0.063822,-0.074209,-0.125743,0.385682,0.182912,0.036644,-0.247692,0.376960,0.431495,-0.204549,-0.081035,0.020862,-0.127654,-0.516006,0.285532,-0.205868,0.087236,-0.505862,0.348266,0.105061,-0.296399,0.279078,-0.439202,0.110381,0.714154,0.321000,0.295920,-0.137960,-0.194629,-0.351406,0.116606,0.660911,-0.067362,-0.222470,0.349840,-0.238993,-0.173308,-0.031783,-0.009631,-0.715409,-0.105341,0.493776,0.229158,0.142047,0.348967,-0.620384,0.038456,-0.664995,-0.118957,0.031949,-0.477892,0.264152,-0.817702,-0.010860,-0.521361,-0.328612,0.348227,0.062555,0.018391,0.606132,-0.565799,0.462822,0.428516,0.237621,-0.528017,0.526171,0.056668,0.081438,-0.383229,-0.069957,0.308400,-0.012737,0.020249,0.299647,0.422487,0.071016,0.127484,-0.277065,0.447596', '1292403', '1296339', '11541282', '1297239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4078562', '决战刹马镇', '喜剧', '三十年代纵横西北的土匪胡栓子殒命刹马镇，而传说中他留下的宝藏也埋在了这里……多年之后，刹马镇村长唐高鹏（孙红雷 饰）为了发展经济，携带数件“文物”寻求专家鉴宝，希望达到宣传效果，而此行中，他拿出的胡栓子留下的金牌引起了文物大盗周定邦（李立群 饰）的注意，周定邦了解此金牌中隐藏了胡栓子宝藏的秘密，遂与毛总（黄海波 饰）合作，前往刹马镇以发展经济为名寻找宝藏。另一方面，周定邦派出的手下在刹马镇打听消息，阴错阳差将这里埋有宝藏的消息广播给全镇村民。唐高鹏与老相好春娘（林志玲 饰）等人希望发展旅游事业，周定邦一行的到来点燃了他们致富的梦想，而众人心照不宣关于宝藏的秘密则引发了各方一轮轮的明争暗斗……©豆瓣', '孙红雷', '李蔚然', 6.1, 58506, 'tt1929278', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p580208004.jpg', 5, 18.9, 48.1, 21.5, 6.5, '-0.092839,0.012645,-0.572048,0.613053,0.220858,0.192292,0.069406,0.136733,-0.527183,-0.171550,-0.036155,0.345437,-0.092306,-0.041195,0.077500,-0.073587,-0.349778,-0.362634,-0.022787,-0.251581,-0.141340,-0.311901,-0.392572,-0.215855,-0.506245,0.007565,0.279401,0.597738,-0.420722,0.444266,0.332666,0.149428,-0.378886,0.321078,-0.033244,0.014881,0.283796,-0.047358,-0.384684,0.076623,-0.029571,-0.292014,-0.089339,0.221995,0.136266,0.430434,0.351430,-0.113676,0.116527,-0.017414,0.123399,-0.067537,0.018749,-0.154162,0.479341,0.026054,0.139288,0.370863,-0.129751,-0.024120,0.113583,-0.083474,-0.686630,0.028875,0.368687,0.185421,-0.458247,0.116108,0.047557,0.151192,-0.004993,-0.267215,0.575307,0.719258,0.443321,-0.034420,-0.119025,-0.003108,-0.394093,0.534902,0.288483,-0.473809,0.281218,-0.154733,-0.047770,-0.659218,0.031405,0.118527,-0.141737,0.079200,0.624567,0.116524,-0.038584,0.148951,-0.594224,-0.119651,-0.102547,-0.189456,0.362078,-0.139074,-0.093949,-0.870416,-0.196003,-0.084143,-0.109736,0.106686,0.190970,-0.241918,0.841950,-0.199616,-0.051073,0.274120,0.307417,-0.646411,0.664216,-0.253452,0.397967,-0.328039,0.046189,-0.071162,0.249340,0.434776,0.133399,-0.018718,-0.273043,-0.651926,-0.091558,0.066935', '3318306', '4212172', '1298155', '1468527');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4078592', '上海王', '剧情', '电影讲述了20世纪初上海滩十里洋场、黑帮势力的角逐纷争。纷杂乱世中，奇女子筱月桂（余男 饰）与三代上海王之间充满传奇色彩的爱恨情仇。在妓院做丫头的乡下女孩小月桂（李梦 饰），“个高、胸大、没裹脚”，让老板新黛玉（白灵 饰）很不满意，却深得洪门老大常力雄（胡军 饰）欢心，成为一代上海王的女人。常力雄在与同盟会代表黄佩玉（秦昊 饰）接触过程中被暗杀，小月桂孤助无援，产女后流落乡下。历经数年艰辛，小月桂成立滩簧班子，重返大上海，在第二代上海王黄佩玉帮助下，成为“申曲名伶”筱月桂（余男 饰）。功成名就的筱月桂从没忘记要寻找杀死常力雄，也就是她女儿父亲的凶手。当她发现自己爱上黄佩玉时，也证实了“洪门内奸的真正身份”。她与常爷的前跟班余其扬（凤小岳 饰）合谋除去内奸，助余其扬成为洪门第一个银行家，新的“上海王”。', '胡军', '胡雪桦', 4.8, 9144, 'tt5482570', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2426952758.jpg', 16.2, 40.2, 33.2, 8.3, 2.1, '-0.272564,0.314203,-0.417492,0.256839,0.093525,-0.193522,0.265754,-0.078235,-0.606872,-0.346396,0.016135,0.531293,-0.073508,0.317788,0.087150,0.022726,-0.229420,-0.489042,-0.158756,-0.238422,-0.197614,-0.230844,-0.041646,0.017947,-0.264217,0.154797,0.597804,0.236197,-0.446178,0.255210,0.536664,0.148367,-0.053793,0.074563,-0.347511,0.107673,0.238805,0.172593,-0.293357,-0.030044,-0.184580,-0.231375,-0.272814,-0.260262,0.140833,0.111631,0.435099,-0.275611,0.090765,-0.560306,0.293646,0.047212,-0.163338,-0.200559,0.400687,-0.097188,0.158849,0.287978,-0.294383,-0.347079,0.165588,-0.227403,-0.438921,0.252251,0.520631,0.068004,-0.447928,0.086544,-0.046151,-0.013419,0.119495,-0.249336,0.283988,0.333617,0.276953,0.030212,-0.035056,0.211706,-0.493034,0.607310,0.701292,0.225817,0.019174,-0.096718,0.037465,-0.423869,-0.203986,-0.194782,-0.246785,-0.050926,0.249496,-0.238239,-0.001175,0.265690,-0.277370,-0.141037,-0.193853,0.254406,0.416690,-0.120847,-0.211807,-0.344797,-0.320640,-0.421892,-0.166306,0.001359,0.273302,-0.215158,0.711942,-0.785991,0.239152,0.192893,0.250191,-0.504114,0.674866,0.099897,0.070427,-0.584464,-0.174072,0.140827,0.063871,0.029550,0.051684,0.217523,-0.535381,-0.294608,0.012727,0.029540', '5985887', '25721544', '35030151', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4079117', '杀戮都市', '动作', '某个平凡的傍晚，大学生玄野计（二宫和也 饰）在电车站重逢初中时代的好友加藤胜（松山健一 饰）。为了救助一个跌落铁轨的男子，他们二人遭到电车的强烈撞击。然而转眼之间，他们便毫发无损地来到一间密闭的屋子内。这里还有另外七个男人以及一个巨大的黑色球体。根据黑球的指示，这群人需要穿上战服拿起武器去刺杀葱星人。有的人为了奖金投入了杀戮游戏，有的人为了生存而冷酷无情。生死关头，懦弱的阿计和善良的阿胜也不得不投入其中，而前方还有更多的考验等待着他们。此外，名为GANTZ的系统又隐藏着怎样的秘密？本片分前后篇两部，根据漫画家奥浩哉的同名原著改编。©豆瓣', '二宫和也', '佐藤信介', 6.6, 26367, 'tt1525835', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p878825165.jpg', 2.6, 11.7, 47.2, 28.6, 9.9, '0.250933,-0.157758,-0.671003,0.691148,-0.238957,-0.057345,0.845341,0.230980,-0.157515,-0.257328,0.506952,0.732077,0.002712,0.015620,0.168320,-0.064407,-0.336094,-0.516605,-0.320061,-0.274001,-0.473800,-0.424173,-0.173461,-0.280845,0.057214,-0.127841,0.742370,0.198483,-0.165805,0.266522,0.454141,0.237975,-0.376122,0.395214,-0.221623,-0.139388,-0.135940,0.139882,-0.048182,0.231876,-0.194218,-0.150451,-0.093361,-0.033401,-0.195685,0.401219,0.822344,-0.287176,-0.034136,-0.071247,0.367401,-0.045265,-0.181051,-0.171967,0.285332,0.070337,0.249130,0.132984,-0.115979,0.064755,0.095921,-0.141447,-0.763581,-0.111600,0.138971,0.059967,-0.376529,0.658539,-0.041117,-0.146641,0.263512,-0.193000,-0.044170,0.368189,0.260710,0.186822,-0.308067,-0.258554,-0.380050,0.096780,0.415415,-0.088886,-0.229005,0.230923,-0.225473,-0.519483,-0.149312,-0.248463,-0.292626,-0.191166,0.378550,0.224361,-0.087378,-0.084975,-0.766148,0.522036,-0.018542,-0.160491,0.010369,-0.455941,-0.335354,-0.651842,0.028988,-0.245892,-0.315847,0.259184,0.103549,-0.197592,0.956412,-0.588970,0.096218,0.580853,0.374414,-0.305404,0.717943,-0.048162,0.112767,-0.236560,-0.322012,0.050243,0.060574,0.439336,-0.019491,0.383146,-0.342184,-0.049174,-0.516775,0.376135', '3811356', '2053515', '25863940', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4079119', '杀戮都市2', '动作', '为了复活死去的好友加藤胜（松山健一 饰）以及其他逝者，玄野计（二宫和也 饰）与战友们5个月来不断与各种外星人作战，赢取更多的分数。在这一过程中，不断有新丁加入Gantz，而新丁似乎又对这个看似陌生的异类世界有着莫名的熟悉感。某天，本应死去的加藤突然出现在现实世界，这令玄野等人大为不解。而之后的战斗也显现出了诸多奇怪之处，比如在与黑衣星人的战斗中，敌我双方竟然同时出现在人满为患的地铁车厢内，以致于血流成河，引起巨大伤亡。现实与虚幻的界限开始模糊，来势汹汹的外星人也准备向Gantz的总部发起最后的攻击……本片根据奥浩哉的同名漫画改编。©豆瓣', '二宫和也', '佐藤信介', 6.6, 18827, 'tt1525836', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p905604539.jpg', 2.7, 12.5, 47.4, 27.1, 10.3, '0.211269,0.112657,-0.885436,0.545325,0.317568,-0.114715,0.987427,-0.032505,-0.429514,-0.325627,0.229567,0.809949,-0.292359,0.111813,0.319551,-0.446536,-0.268553,-0.695622,-0.414988,-0.346094,-0.451469,-0.414772,-0.359935,-0.225522,-0.139409,-0.329996,0.794483,0.291971,-0.202949,0.613591,0.207942,0.368974,-0.230250,0.549947,-0.050695,-0.040790,-0.082388,0.112234,-0.181715,0.048363,-0.111863,-0.018019,-0.282908,0.026445,-0.357883,0.345268,0.937041,-0.579230,-0.409548,-0.055667,0.476503,-0.203092,-0.191848,0.086123,0.287356,0.066851,0.107349,-0.029038,0.037530,0.123492,-0.049105,0.053499,-0.950554,0.159441,0.044595,0.299013,-0.243818,0.313067,0.041159,-0.231789,0.201972,-0.122356,0.090588,0.600351,0.494660,0.374055,-0.531287,-0.074983,-0.262069,-0.141777,0.616819,0.297520,-0.443346,0.219292,-0.165877,-0.510491,-0.288373,-0.171460,-0.164424,-0.167112,0.308438,0.246147,0.042590,0.402278,-0.897033,0.291020,0.077062,-0.394989,-0.076569,-0.284544,-0.419775,-0.781242,-0.268985,-0.434740,-0.336935,0.365708,0.200712,-0.054644,0.963794,-1.038267,0.173347,0.373858,0.348591,-0.302119,0.577804,0.118656,-0.073377,-0.139142,-0.397321,0.022868,0.086331,0.456342,0.044807,0.314863,-0.279488,-0.004079,-0.626709,0.333674', '25774050', '3005387', '3811356', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4082101', '喜羊羊与灰太狼之虎虎生威', '动画', '在一个月黑风高的夜晚，灰太狼（张琳 配音）和一众同伴相约，杀进羊村捕捉小肥羊，为老婆和孩子送上情人节的饕餮大宴——涮羊锅。与此同时，羊村正在举行大白菜成功培育一千周年的庆典，节日的欢乐气氛却被突如其来的灰太狼所破坏。正当灰太狼与喜羊羊（祖丽晴 配音）激战正酣之际，狂暴骄纵的虎威太岁（贾译 配音）率领众多手下来到羊村，扬言要在这里修建游乐场。转眼之间一座豪华的游乐场拔地而起，小肥羊们被迫沦为这里的工人，连高傲自大的灰太狼也难以幸免。面对这个突如其来的虎威太岁，羊羊和灰太狼被迫联手……本片荣获2010年第十六届上海电视节国产动画片白玉兰金奖、2010第七届金龙奖最佳动画长片奖等多个奖项。©豆瓣', '谢天华', '赵崇邦', 7.5, 39377, 'tt2193269', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1572542661.jpg', 1.8, 5.6, 33.5, 35, 24.2, '-0.007580,-0.144222,-0.631862,0.281405,0.219962,0.070870,0.578728,0.269391,-0.158800,-0.216946,0.197152,0.574288,-0.467377,0.082689,0.211886,-0.447289,0.036179,-0.330592,-0.292647,0.124248,0.161221,0.026936,-0.120920,0.094265,-0.028046,-0.062327,0.615057,0.017877,0.041785,0.605431,0.713843,0.000344,-0.191407,0.165195,-0.169724,-0.044995,0.182104,-0.001552,-0.014652,0.450044,-0.598465,-0.224490,-0.020122,-0.006564,-0.058837,-0.020829,0.806110,-0.366301,-0.153436,-0.442809,0.309994,-0.495596,-0.172185,0.187410,0.387054,-0.206446,0.388711,-0.104417,-0.095199,0.316779,-0.004937,-0.195814,-0.715844,0.171007,-0.021349,-0.004276,-0.456083,0.398353,0.364790,0.290375,0.141953,-0.160397,0.198296,0.068252,0.220664,0.394260,0.045262,0.263866,-0.411427,0.296907,0.754506,-0.270338,0.182442,0.144154,0.174489,-0.334732,0.185271,-0.195671,-0.285882,0.146208,0.231934,0.033968,-0.131227,0.068049,-0.869291,-0.127085,-0.000905,-0.499265,0.020237,-0.171334,-0.223747,-0.900277,0.193978,-0.156938,-0.044979,0.090366,0.181894,-0.087753,0.436560,-0.652543,0.271717,0.229545,0.206519,-0.049922,0.466507,0.016943,0.052560,0.173754,-0.171526,-0.228320,0.147343,0.120241,0.131013,0.372878,-0.036297,-0.294726,-0.441090,0.413016', '1294917', '2159244', '3147969', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4082544', '西风烈', '剧情', 'http://site.douban.com/106682/西风烈豆瓣小站张宁（夏雨 饰）是一名香港黑拳手，为了向女友孙静（杨采妮 饰）证明自己，张宁受雇在香港杀人，案发后与女友踏上了逃亡之路。一年后，甘肃警方昔日的“四大名捕”——“豹子”向西（段奕宏 饰）、“藏獒”何建中（倪大红 饰）、“羊倌儿”杨晓明（吴京 饰）与“牦牛”韩朝东（张立 饰）齐聚戈壁，追捕张宁。与此同时，因张宁偷拍了雇主的照片，并以此作为要求警方不追究孙静的筹码，成名已久的国际杀手麦高（吴镇宇 饰）受命携师傅的孙女阿诺（余男 饰）不远千里追索张宁，以毁灭证据。一时间，三方在戈壁为各自生存或使命激烈碰撞，展开了连场激战……©豆瓣', '段奕宏', '高群书', 6.1, 43021, 'tt1810858', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p684366252.jpg', 5.6, 18.3, 46.8, 22.9, 6.4, '-0.076542,-0.070031,-0.406589,0.526265,0.297278,-0.209769,0.306270,0.287891,-0.583041,-0.275248,0.272382,0.244106,0.013012,-0.144326,0.285349,-0.225048,-0.298304,-0.519447,0.068943,0.009029,-0.049234,-0.237590,-0.216076,-0.135696,-0.102007,0.081213,0.600604,0.072915,-0.222025,0.637330,0.535454,0.239901,-0.537221,0.154519,0.209312,-0.060515,-0.049225,0.154048,-0.539659,0.219528,-0.183743,-0.271307,-0.241634,-0.108155,-0.088089,0.436723,0.700206,-0.099935,0.125865,-0.375046,0.206841,-0.306359,0.192944,0.069074,0.285696,-0.007134,0.297005,0.211206,-0.061475,0.050134,0.191040,0.127305,-0.303483,0.049344,0.206140,0.191036,-0.474815,0.447172,-0.462892,-0.125937,0.201041,-0.361116,0.015138,0.411481,0.097712,0.029566,0.075367,-0.054903,-0.217683,0.557331,0.369107,0.261188,0.337033,-0.233100,0.189879,-0.583376,-0.185580,0.171454,-0.363374,-0.129612,0.551706,-0.115390,0.146489,0.026048,-0.593923,-0.232178,-0.082797,-0.025025,0.029835,0.030238,-0.040426,-0.611795,0.068759,-0.409970,-0.050226,-0.079955,0.246915,-0.051848,0.274662,-0.604090,-0.130326,0.217690,0.242532,-0.438011,0.249136,-0.023374,0.089754,-0.249969,-0.024654,-0.002894,0.242810,0.246853,0.224380,0.037760,-0.062994,-0.210558,-0.082111,0.159696', '26365262', '1780122', '6068516', '21941770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4086853', '忧郁症', '剧情', '浪漫之夜，才华横溢的美丽少女贾斯汀（克斯汀·邓斯特 Kirsten Dunst 饰）和心爱的麦克（亚历山大·斯卡斯加德 Alexander Skarsgård 饰）步入婚礼殿堂，姐姐克莱尔（夏洛特·甘斯布 Charlotte Gainsbourg 饰）和家人们为了她一掷千金，尽心操持。然而莫名的恐慌与悲伤袭上心头，令贾斯汀整晚郁郁寡欢，她的婚姻刚刚开始就已到了破败的边缘，与亲友同事的关系也变得分外紧张。克莱尔试图将妹妹带出忧郁症的困扰，然而收效甚微。与此同时，一颗神秘的小行星正向地球飞速逼近，似乎正是它带来了贾斯汀的忧郁，又似乎那原本郁结心中的烦恼只不过被它释放了而已……本片荣获2011年第64届戛纳电影节最佳女演员奖。©豆瓣', '克斯汀·邓斯特', '拉斯·冯·提尔', 7.1, 31451, 'tt1527186', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1222275765.jpg', 2.5, 9.5, 35.4, 35.3, 17.2, '0.107305,0.062605,-0.900032,0.522486,0.298940,-0.400456,0.979729,0.141979,-0.472084,-0.154836,0.036688,0.386226,-0.409784,0.384672,0.599454,0.080260,-0.177182,-0.532351,-0.070889,-0.158126,0.040911,-0.147334,-0.395807,-0.200195,-0.153963,-0.576835,0.357463,0.173657,0.163136,0.744415,0.408892,0.547383,-0.044254,0.558715,0.241139,0.064390,0.040673,-0.083033,-0.177954,-0.208493,0.269159,-0.317115,-0.042551,0.165873,0.128198,0.455718,0.571044,-0.068505,0.110556,-0.139425,0.258892,-0.139712,0.022200,0.145808,-0.077336,-0.079876,0.001463,-0.135493,-0.230858,0.018673,0.216257,-0.273924,-0.589074,0.490036,0.149221,0.164325,-0.395182,0.285788,-0.176602,-0.080741,0.138340,-0.247647,0.303459,0.128459,0.299200,0.322715,-0.165880,0.034872,-0.343211,0.209507,0.424705,0.102820,-0.461744,0.266671,-0.489646,-0.369956,0.049602,-0.097358,-0.512608,-0.015987,0.502276,0.038528,0.205789,0.509104,-0.577794,-0.215471,-0.276189,-0.171005,-0.056532,-0.424348,-0.013821,-0.455218,-0.205743,-0.300774,-0.186184,0.010439,0.046029,-0.240766,0.507913,-0.575233,0.411540,0.445178,0.155349,-0.190586,0.345358,-0.013261,0.191863,-0.087572,-0.234422,0.599572,-0.280255,0.246285,0.037786,0.236627,-0.248786,0.128618,-0.437077,0.566308', '3011051', '1292528', '4896894', '4312232');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4095250', '老爸当家', '喜剧', '布拉德（威尔·法瑞尔 Will Ferrell 饰）是一位电台经理，在邂逅了名为萨拉（琳达·卡德里尼 Linda Cardellini 饰）的女子并同她坠入情网之后，他有了两个可爱的继子梅根（斯嘉丽·埃思特维兹 Scarlett Estevez 饰）和迪伦（欧文·瓦卡罗 Owen Vaccaro 饰），从此，布拉德的人生备忘录上又有了新的的目标——成为两个孩子眼中最棒的继父。然而，一个男人的存在令这个目标看上去遥不可及，那个男人就是萨拉的前夫，孩子们的亲生父亲马龙（马克·沃尔伯格 Mark Wahlberg 饰）。这个看上去不修边幅，整日里游手好闲的男人屡屡骚扰着布拉德的生活。虽然马龙看上去是这么的不靠谱，但他的出现却总是能够受到孩子们的热烈欢迎。©豆瓣', '威尔·法瑞尔', '西恩·安德斯', 6.5, 8962, 'tt1528854', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2325863893.jpg', 1.7, 10.9, 55.3, 24.1, 8, '0.512961,-0.019869,-0.603355,0.686920,-0.456342,-0.452144,1.043418,0.401844,-0.536121,-0.232991,0.250212,0.963960,-0.114219,0.399467,0.181081,0.312572,-0.213566,-0.619687,-0.085383,-0.225206,-0.051307,-0.475471,-0.393452,-0.169042,-0.190274,-0.317091,0.463113,-0.232831,0.059589,0.335175,0.567103,0.323425,0.410440,0.240265,-0.326924,0.143337,0.281054,-0.245574,0.113459,0.209465,0.014110,0.143946,-0.033170,0.292057,-0.257054,0.453320,0.507255,-0.305166,0.033529,-0.184559,0.400701,-0.074207,0.019672,0.157256,0.108553,-0.312893,0.215095,-0.089026,-0.105482,-0.162979,0.270208,-0.174629,-0.556226,0.154924,0.063561,0.451662,-0.724848,0.514666,-0.194136,-0.247331,0.133685,-0.327929,0.040615,0.097623,0.163923,0.348734,-0.153746,0.129438,-0.575481,-0.024338,0.336943,0.107328,-0.553234,0.264319,-0.457133,-0.427086,-0.075004,-0.223710,-0.920257,-0.011207,0.340845,-0.323562,-0.066079,0.331123,-0.728056,0.239530,-0.413474,0.031897,-0.117517,-0.335776,-0.223032,-0.548908,-0.060509,-0.703590,-0.614735,-0.002747,-0.047088,-0.275211,0.838253,-0.867301,0.262805,0.493887,0.016344,-0.368243,0.693886,0.344181,0.227299,-0.145251,-0.164547,0.408741,0.149501,-0.153369,-0.119066,0.478544,-0.015065,-0.140398,-0.235057,0.793848', '1292062', '26677495', '2002744', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4095296', '信任', '剧情', '英俊沉稳的威尔（克里夫·欧文 Clive Owen 饰）和妻子林恩（凯瑟琳·基纳 Catherine Keener 饰）还有青春期的女儿安妮（丽亚娜·莱伯拉托 Liana Liberato 饰）一起住在一个太平的社区，事业一帆风顺，生活安稳而美满，是一个令人羡慕的幸福家庭。可这一份平静随着女儿新结交的网友开始发生改变。14岁的安妮在网上认识了一个名叫查理的16岁男孩。而威尔和林恩起初并未太介怀，也对安妮的交友表示赞同。直到有一天安妮和查理安排了见面，让她吃惊的是：原来那个每天在网上与她交流的16岁英俊男孩并不真正存在。真正与她每天交谈的人竟然是一个可悲的的40岁中年男子。而更可怕的事情发生率，这个有恋童癖的陌生人强奸了安妮，从此威尔一家发生了天翻地覆的改变。而从来做事冷静的威尔终于忍不住爆发，他要为14岁的女儿讨回公道……©豆瓣', '克里夫·欧文', '大卫·休默', 7.2, 9295, 'tt1529572', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1341280008.jpg', 0.5, 3.8, 40.8, 44.2, 10.7, '0.334271,-0.171042,-0.545624,0.352398,-0.480020,-0.377098,1.023347,0.121345,-0.515827,-0.320796,0.164611,0.960715,-0.306157,0.210140,0.567175,0.250440,-0.067614,-0.604795,0.231133,-0.002440,-0.028332,-0.601966,-0.275532,-0.239226,-0.079775,-0.284098,0.392608,-0.204228,0.202086,0.755806,0.391673,0.181492,0.302295,0.493411,-0.102084,-0.012528,0.100971,0.006768,0.032453,0.006922,-0.089778,-0.168227,-0.053842,0.309952,-0.105640,0.477666,0.403006,-0.104640,-0.411323,-0.016403,0.569786,-0.154216,-0.206578,0.199942,0.174803,-0.326866,0.249457,0.089552,-0.055821,-0.211225,-0.036368,-0.085525,-0.666213,0.158061,0.016170,0.327999,-0.564200,0.509616,-0.119333,-0.379366,0.283634,-0.210538,0.110639,0.687980,-0.051138,0.329342,-0.332889,0.024488,-0.395400,0.156833,0.538945,0.174352,-0.542343,0.509896,-0.232548,-0.351931,-0.066139,-0.167621,-0.937006,0.071342,0.012276,0.009139,-0.250563,0.249155,-0.577072,0.007148,-0.211967,-0.132648,0.139727,-0.520051,-0.221460,-0.482383,-0.414151,-0.798070,-0.534838,-0.203472,-0.143459,-0.435445,0.742930,-1.015129,0.172607,0.452769,0.197429,-0.590187,0.744841,0.277572,0.219210,-0.134602,0.030527,0.340840,-0.183351,0.046192,-0.151900,0.485366,0.111686,-0.237683,-0.507922,0.543743', '1292720', '2002744', '1292062', '4301215');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4097023', '新少林寺', '剧情', '20世纪20年代，时局动荡，天下大乱，华夏大地无有一片宁静之所。时群雄并起，军阀混战。军阀少帅侯杰（刘德华 饰）纵横捭阖，骄横跋扈，视平民如草芥，却难逃自身劫数。正所谓城头变换大王旗，侯杰转眼间辉煌不在，副官曹蛮（谢霆锋 饰）伺机上位、妻子颜夕（范冰冰 饰）离去、女儿身亡，种种打击令这个昔日的乱世修罗万念俱灰。落魄至少林寺期间，侯杰先后结识悟道（成龙 饰）、净能（吴京 饰）、净海（余少群 饰）、净空（释延能 饰）等僧众，并慢慢领悟了宿世的罪障因果，遂放下贪嗔痴慢疑之心，诚心向佛。与此同时，更大的磨难正向少林袭来……少林寺住持释永信担任该片监制。©豆瓣', '刘德华', '陈木胜', 6.1, 131438, 'tt1533749', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p788475809.jpg', 3.8, 17.6, 52.4, 19.9, 6.4, '-0.199068,0.202414,-0.403458,0.104880,0.104176,-0.112730,0.447277,0.488535,-0.475947,-0.173303,0.178129,0.404642,0.051669,-0.083881,0.052338,-0.158454,-0.004178,-0.530563,-0.150482,-0.075931,0.435313,-0.008163,-0.257819,0.108331,-0.260240,-0.244861,0.600233,0.261235,-0.044553,0.447871,0.251039,0.089462,-0.267908,0.245540,-0.138011,0.104100,-0.233644,0.172215,-0.506668,-0.271033,-0.332501,-0.559570,-0.344550,0.214550,-0.612823,0.085655,0.430884,-0.345089,0.005017,-0.495071,0.438286,-0.014860,-0.065379,0.217633,0.118358,-0.007864,0.029460,0.168841,0.262957,0.264346,-0.158973,-0.057140,-0.122742,-0.033302,0.137012,0.104327,-0.088171,0.413460,-0.171171,-0.234893,-0.258806,-0.062128,-0.093391,0.162608,0.385292,0.213191,-0.151616,-0.489076,-0.359458,0.582565,0.227666,0.034961,0.026395,0.233948,0.043112,-0.246699,0.158610,-0.198438,-0.305564,-0.229712,0.395668,-0.062447,0.348861,0.382683,-0.123047,-0.005594,-0.214703,0.395139,-0.158011,0.045954,-0.105704,-0.459031,-0.264885,-0.278168,-0.115979,-0.028749,0.416498,0.001956,0.578222,-0.499722,0.207463,0.079165,0.017700,-0.333279,0.291700,-0.090241,0.178542,-0.186928,-0.002510,0.628453,-0.300123,0.421879,-0.140844,-0.067021,-0.310060,-0.121068,0.040282,-0.026967', '1306998', '1483630', '25922902', '1432699');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4099231', '辉夜姬物语', '动画', '住在深山老林里的老爷爷（地井武男 配音）一早进山砍竹子，结果竟在附近的一根发光的竹笋中发现了只有掌心大小的娃娃。没有子女的老爷爷兴奋不已，他双手捧着娃娃回到家中，而小家伙竟然在老奶奶（宫本信子 配音）的手中越变越大。之后的岁月里，舐犊情深的爷爷小心呵护他的公主（朝仓亚纪 配音），小女孩则以惊人的速度生长，她与村里的孩子们周游乡间，结识了诚实可靠的舍丸哥哥（高良健吾 饰），而一首莫名的歌曲却令她潸然泪下。老爷爷在山里先后发现金子和美丽布匹，他决心让公主过上贵族的生活，于是举家搬到了京城的豪宅中。公主超凡脱俗，貌美绝伦，从此“辉耀姬”的名字在京城贵族间广为传颂。然而美丽女孩的笑容渐渐退去，这似乎并不是她所向往的生活……本片根据日本民间传说《竹取物语》的故事改编。©豆瓣', '朝仓亚纪', '高畑勋', 8.5, 83432, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2155612579.jpg', 0.2, 1.1, 13.6, 42.8, 42.4, '0.177974,-0.014822,-0.509035,0.656340,-0.008070,-0.175088,0.887361,0.207485,-0.612199,0.000196,0.253649,0.489069,-0.210512,0.581453,0.089576,0.196551,-0.226803,-0.466750,-0.338963,-0.164719,-0.100404,-0.102957,-0.201181,-0.160374,-0.023921,-0.234641,0.507379,0.066380,0.073636,0.530089,0.047106,-0.189923,-0.299024,0.370410,-0.449062,0.080419,-0.144967,0.137890,0.039401,0.123271,0.017971,-0.360783,-0.071562,0.025214,-0.077450,0.225897,0.754411,-0.556324,0.115036,-0.197640,0.355921,0.085929,-0.051985,0.094914,0.294523,0.050489,0.377907,-0.153752,-0.149143,-0.083538,0.103954,-0.411724,-0.198269,0.047133,0.256310,0.276472,-0.696320,0.391849,0.096052,-0.107187,0.153388,-0.566408,0.286239,-0.188807,0.187927,0.379028,-0.243752,0.098272,-0.408178,0.494111,0.349564,-0.055606,-0.120610,0.307736,-0.307848,-0.572005,-0.061834,-0.180139,-0.534592,-0.098490,0.189827,0.025392,-0.170553,0.212473,-0.506957,0.021615,-0.156880,-0.069029,0.102572,-0.380403,-0.313424,-0.330988,0.090807,-0.442582,-0.103992,0.030148,0.264117,-0.121554,0.905170,-0.684874,0.211639,0.398109,0.017296,-0.068956,0.497746,-0.311531,-0.065181,0.002797,-0.370940,0.371394,0.017821,0.234666,0.055146,0.506995,-0.372892,-0.064867,-0.459709,0.592019', '1467779', '26348103', '21619567', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4099242', '超时空来电', '悬疑', '结束了破败的婚姻，美丽而怅然的女子玛丽·纪（Rachelle Lefevre 饰）独自搬入一处有着半个多世纪历史的老旧公寓。入住没多久，她便接到一同陌生来电。对方是个叫罗丝（Lorna Raver 饰）的女人，她在找她的男人。玛丽起初并未在意，可是罗丝反复来电，令她不胜其扰，而且她在偶然的情况下发现，这可能是一通穿越了时空的电话。电话线的另一头，罗丝是一名生活在20世纪70年代末的不幸女子。两个女人有了短暂的深入交流，谁知玛丽一句玩笑话导致了罗丝杀死她的丈夫。在此之后，近乎错乱的罗丝盯上了玛丽，而后者也几近崩溃，加上前夫史蒂文（Ed Quinn 饰）的骚扰更令她痛苦不堪。一切朝着不可预知的方向发展……©豆瓣', '史蒂芬·莫耶', 'Matthew Parkhill', 7, 7697, 'tt1525890', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1440147551.jpg', 0.8, 6.1, 43.2, 40.1, 9.8, '0.244463,0.194750,-0.752630,0.507127,-0.341069,-0.112625,0.981913,-0.014428,-0.569132,-0.388176,0.217921,0.688674,-0.287219,0.226232,0.401965,0.325995,-0.094413,-0.445564,0.202415,-0.220242,-0.376652,-0.395023,-0.265935,-0.496585,0.156942,-0.549537,0.398009,0.207321,-0.430514,0.233558,0.125755,0.187807,-0.190080,0.644219,-0.264725,0.155617,0.150482,0.049692,-0.036577,0.238517,0.093341,-0.375807,-0.165006,0.297517,-0.386136,0.596039,0.530748,-0.235529,-0.286312,0.113541,0.646703,-0.132702,-0.325813,-0.053469,0.467172,-0.113360,0.067253,0.049619,-0.323258,-0.107384,0.304023,0.156738,-0.339858,0.206138,-0.160141,0.164172,-0.378293,0.536389,-0.085261,-0.035803,-0.083402,-0.394362,0.165122,0.163275,0.228721,0.359705,0.059317,-0.037044,-0.373772,0.191290,0.623074,0.232135,-0.370398,0.570351,-0.266754,-0.477060,-0.072170,-0.050564,-0.658752,-0.027311,0.470756,0.136677,-0.328239,0.088620,-0.379347,0.137227,-0.444157,-0.162349,-0.122962,-0.400273,-0.269444,-0.442013,-0.201756,-0.400535,-0.370247,0.184285,-0.173695,-0.102988,0.527815,-0.744618,0.258962,0.571585,0.264423,-0.545003,0.663371,0.208719,-0.034875,-0.193231,0.226338,0.493274,-0.130622,0.160488,0.180539,0.324764,-0.168928,-0.039464,-0.526273,0.550649', '1309080', '1292217', '1296534', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4100696', '美丽密令', '喜剧', '身手敏捷、青春阳光钟爱芳（蔡卓妍 饰）终于成为像他爸爸钟点工（许绍雄 饰）一样的警察，她第一天上班就遇到一起大案。重案组为了指证黑帮分子天爷（王晶 饰），四处寻找重要证人肥威（林雪 饰），而天爷也欲杀肥威灭口。爱芳初露锋芒，打败天爷手下，抓住肥威。而肥威提出一个要求，只要警方能保护他参加华夏杯青春小姐选美的女儿君君（李曼筠 饰），他便同意出庭作证。重案组警司陆志昂（陆毅 饰）派爱芳混入选美队伍，暗中保护君君，与此同时，陆志昂和警队精英袁子丹（樊少皇 饰）、男人婆铁玛丽（吴君如 饰）也混入电视台，相机而动。天爷知晓君君身世，遂派出杀手向她袭来。各方势力云集于此，连番较量在所难免……©豆瓣', '蔡卓妍', '王晶', 5.4, 43273, 'tt1611907', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2631638588.jpg', 9.5, 28.1, 47.9, 11.7, 2.8, '-0.169768,-0.105130,-0.269294,0.198695,-0.063516,0.065149,0.187916,0.276666,-0.247762,-0.153529,0.311153,0.352634,0.155427,0.093678,0.375989,-0.217620,-0.216444,-0.744389,-0.054003,0.020480,-0.034776,-0.031180,-0.054999,-0.203930,0.281543,-0.027802,0.482921,-0.141796,-0.147329,0.740280,0.479924,0.363778,-0.324557,-0.056801,0.258190,-0.163732,0.339372,0.019465,-0.497745,0.228717,-0.443815,-0.104754,-0.035254,0.025808,0.185869,0.096410,0.265230,0.016307,0.067503,-0.395600,0.244655,-0.457232,0.033484,-0.140154,0.433847,0.057265,0.218855,0.151379,-0.039991,0.182775,0.052969,-0.170181,-0.443248,0.122587,0.511320,0.087624,-0.228086,-0.084419,-0.219222,0.117481,0.003371,-0.125712,0.108807,0.063997,0.014769,-0.149833,0.120697,0.136320,-0.424725,0.321677,0.495631,-0.123810,0.360351,-0.375727,0.307206,-0.323346,0.228613,-0.231597,-0.051146,0.158704,-0.064127,-0.362148,0.158918,-0.264779,-0.210684,-0.235703,-0.141628,0.220311,-0.061144,-0.169283,0.475461,-0.647621,-0.042362,0.068532,-0.194779,0.128259,0.114480,-0.059311,0.494143,-0.481415,0.041318,0.576166,0.315315,-0.650272,0.277961,0.045817,0.071883,-0.264499,0.030913,-0.284245,0.243538,0.020175,-0.014208,0.105207,-0.041403,-0.436403,-0.022343,-0.480709', '25723905', '26365262', '2209368', '1307914');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4109746', '他和她的孤独情事', '剧情', '该片讲述了一对住在纽约的夫妇经历婚姻危机的故事，麦卡沃伊饰演一家餐馆的老板，而查斯坦则饰演他的妻子，一位婚后重回大学读书的女人。影片最大的特点就是将有两个剧本，拍成两部影片，一部以丈夫的视角进行叙事，而另一部则以妻子的视角来叙事，均由内德·本森担任编剧和导演。', '詹姆斯·麦卡沃伊', '内德·本森', 6.7, 5888, 'tt3729920', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2198831317.jpg', 1.4, 9.2, 52.7, 28.2, 8.5, '0.167118,-0.448954,-0.316092,1.085990,0.261742,-0.299877,0.659211,0.523741,-0.103410,-0.478335,0.373703,1.044179,-0.082960,0.452865,0.547952,-0.210901,-0.201104,-0.617850,-0.331841,0.026778,-0.011983,-0.408295,-0.111680,-0.168621,0.156633,-0.241956,0.957632,-0.395019,-0.338200,0.096862,0.695779,0.395365,-0.386757,-0.099762,-0.027356,0.086607,-0.118792,-0.120666,-0.700454,0.450271,0.079548,-0.189711,-0.047934,-0.086752,-0.243469,0.269117,1.059702,-0.146648,-0.022492,0.077583,0.846209,-0.123038,-0.130154,-0.200736,0.260745,0.080883,0.415767,0.266242,-0.216178,0.055597,-0.095830,-0.582084,-1.144789,-0.086583,0.233824,0.050601,-0.537448,0.397878,-0.007940,-0.182440,0.030861,-0.343058,0.071554,0.363262,0.494780,0.628382,-0.213621,0.164912,-0.192230,0.401675,0.472585,0.027006,-0.027499,0.758413,-0.048245,-0.325490,-0.207091,-0.350183,-0.645090,0.198910,0.184020,-0.281551,0.079766,-0.124973,-0.514140,-0.080341,-0.128516,-0.264948,0.351682,-0.459174,0.054000,-1.034761,-0.194026,-0.224093,0.095331,-0.302294,0.304733,-0.482474,0.899330,-0.666486,-0.093979,0.347336,-0.002101,-0.632984,1.045043,0.218634,0.451015,-0.606594,0.097860,0.278689,0.119635,-0.093194,-0.124066,0.295161,-0.186946,-0.170144,-0.467104,0.644225', '22265121', '2027945', '25880986', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4111335', '致命切割', '悬疑', '一个红衣屠夫赫然出现在泰国国内，他全身上下被血红色的雨衣所包裹，手里拖着巨大的红色行李箱。红衣屠夫行踪诡异，手段残忍，专以成年男性为猎杀对象，死者生前无不遭到痛苦折磨，而且全部遭到阉割。在此期间，连政府官员的纨绔公子哥也被杀害。红衣屠夫在全国上下引起轰动，警方更是压力巨大，焦头烂额。阿泰是一名因杀人罪而入狱10年的重刑犯，他童年时的一个玩伴与红衣屠夫有着类似的手段。警方据此线索，开始将突破口锁定在阿泰身上。为了尽快离开监狱，阿泰许诺将抓住凶手，警方也承诺还其自由。阿泰根据屠夫留下的种种线索试图还原真相，不过这却是一场费解而危险的猫鼠游戏……©豆瓣', '亚瑞克·阿莫苏帕西瑞', '罗宁·提姆', 7.6, 15802, 'tt1603807', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p481917076.jpg', 0.8, 3.6, 29.7, 46.2, 19.6, '0.122496,0.000371,-0.428292,0.341322,-0.190539,0.224385,0.862308,-0.099069,-0.538453,-0.573198,0.460469,0.517175,-0.110788,-0.001595,-0.015199,-0.069490,-0.017762,-0.712097,-0.170380,-0.023721,-0.271018,-0.159746,-0.227178,-0.383977,0.060411,-0.239200,0.508144,0.112450,-0.080066,0.466880,0.452999,0.613149,-0.455021,0.401687,-0.316306,-0.225010,0.072576,-0.402593,-0.124778,0.217866,-0.045255,-0.438575,0.236043,0.448462,-0.548599,0.218024,0.912741,-0.180762,-0.324610,-0.276319,0.418158,-0.335088,-0.042734,0.499946,0.433598,0.111477,0.284018,0.401227,-0.166519,0.040593,0.234391,-0.104141,-0.858522,-0.129776,0.095790,0.323674,-0.199290,0.216984,-0.302633,0.310547,0.125372,-0.254937,0.037217,-0.016653,0.193631,0.197329,-0.311165,0.285929,-0.482009,0.175150,0.498197,-0.223479,-0.169299,-0.120457,-0.156181,-0.302707,0.050653,-0.159953,0.072632,0.017526,0.488835,0.153613,-0.410369,0.209051,-0.695995,-0.069133,-0.440731,-0.073927,-0.229693,-0.104798,-0.512903,-0.290472,-0.268920,-0.054145,-0.365515,0.232007,0.089465,-0.142910,0.418143,-0.276490,0.233259,0.732988,0.193369,-0.395641,0.252746,-0.151978,0.326737,-0.029056,-0.405987,0.246891,0.490667,0.477310,0.187162,0.081372,-0.299155,-0.264593,-0.189880,0.289270', '2988294', '25774050', '1307800', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4111400', '宝米恰恰', '喜剧', '宝妮（黄姵嘉 饰）和米妮（黄姵嘉 饰）是一对个性迥异，但是却长得一模一样的双胞胎，从小默契无双，而被人搞混更是家常便饭。随着年龄的增长，二人的生活总是被周围的人置于被比较的状态，这让姐妹俩特别是姐姐宝妮非常烦恼。青春期是一个少女的情愫开始蔓延的季节，一个演辩社的男生优果（欧阳伦 饰）闯入了两姐妹的生活，可以很清楚分清两姐妹的优果开始通过各种方式追求妹妹米妮。然而优果和米妮两人的恋爱却谈的坎坷而疲惫，如何相处成了他们之间的障碍，原本应该轻松而甜蜜的恋爱俨然变成了苦于应付的谈判。于是苦恼的优果总是喜欢找宝妮来排解忧愁，而宝妮自己却也陷入了一场纠葛的感情中，一个高大而又呆笨的男生徐永平（姜康哲 饰）在误会重重下错把米妮当成了与自己互有好感的宝妮来追求。这种分不清的状态让宝妮和米妮都非常痛苦，直到二人在临近毕业的时候姐妹敞开心扉…该片获2012年第49届台湾电影金马奖多项提名，第14届台北电影节最佳剧情长片奖。', '黄姵嘉', '杨贻茜', 7.1, 15486, 'tt1534000', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1814728441.jpg', 0.7, 5.3, 44, 39.7, 10.3, '0.503275,-0.175771,-0.604469,0.606038,-0.070137,-0.269647,0.731754,0.229349,-0.530497,-0.017104,-0.018321,0.495461,-0.366048,0.299690,0.287819,-0.104097,0.008397,-0.785392,-0.078557,-0.094656,-0.049907,-0.389203,-0.270695,0.055946,-0.231239,-0.319782,0.607752,-0.144312,-0.110407,0.615682,0.370489,0.127032,-0.030201,0.508442,-0.042212,-0.059292,0.009168,0.229488,-0.269029,0.010514,-0.028105,-0.208162,-0.026220,0.180118,-0.076969,0.387580,0.875072,-0.218876,-0.123450,0.117266,0.441988,-0.226061,-0.310416,0.184994,0.373601,-0.050511,0.227418,-0.057127,-0.133882,0.137202,0.042083,-0.088662,-0.605822,0.209757,0.268638,0.080122,-0.531966,0.485829,0.157389,-0.168175,0.137323,-0.225512,0.133284,0.438676,0.452088,0.509643,-0.326423,-0.128948,-0.512194,0.057403,0.843148,0.085019,-0.394857,0.494385,-0.543477,-0.473874,-0.093353,-0.231828,-0.423656,-0.084111,0.184159,0.114828,-0.154287,0.272494,-0.677624,0.183761,0.001344,-0.033249,-0.170113,-0.697108,0.146627,-0.519500,-0.388613,-0.841042,-0.335978,-0.008207,0.152573,-0.467252,0.713707,-0.849909,0.170634,0.238992,0.135137,-0.438496,0.640050,0.407594,0.063457,-0.321845,-0.206484,0.229470,-0.318143,-0.110423,0.054215,0.513999,-0.201910,0.000787,-0.508211,0.488031', '26354526', '24839498', '25777330', '1309161');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4111416', '无人驾驶', '剧情', '这是关于一群生活在都市中男男女女的爱情故事，他们因为种种机缘深陷于情感的漩涡，上演着一出出犹如无人驾驶般横冲直撞的燥动与狂乱。事业处于低谷期的志雄（刘烨 饰）意外遭遇初恋女友（高圆圆 饰），曾经的美好与重获的激情让志雄决定和结婚七年的妻子（李小冉 饰）离婚；女儿车祸中丧生，妻子（张延 饰）重病在床，自己又丢了工作，王遥似乎走到了人生的绝境，此时一个带给他希望的女人（林心如 饰）神奇的出现，这个女人用拥抱给予他继续生活的希望，然而王遥最终发现，给予希望的拥抱只是一个温柔的陷阱；里加（黄轩 饰）是一个放荡不羁的年轻人，他喜欢在狂飙的赛车上和短暂的一夜情中寻找刺激，然而，聋哑少女李欣（王珞丹 饰）的出现让他最终懂得爱的真谛……©豆瓣', '刘烨', '张杨', 6.2, 70102, 'tt1666661', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p524956088.jpg', 2.6, 15.8, 56.4, 21.3, 3.9, '0.303016,0.229100,-0.747502,0.694127,-0.173521,-0.154287,1.089476,0.064352,-0.359798,-0.193700,0.329688,0.612204,-0.218924,0.451124,0.407885,-0.175699,0.004753,-0.844003,0.017044,0.226451,-0.166712,-0.365621,-0.339655,-0.043083,-0.186440,-0.394731,0.833652,0.314806,-0.192651,0.576676,0.317916,0.418700,-0.187437,0.517755,-0.202442,0.074361,-0.147919,0.377481,-0.455232,0.283942,0.002117,-0.172834,0.024776,0.188614,-0.232955,0.147880,0.824614,-0.382699,-0.203882,0.096688,0.548488,-0.196797,-0.176543,0.173145,-0.169375,0.126429,0.271374,0.032463,-0.333589,0.024801,0.291513,-0.028830,-0.660438,-0.189672,0.162198,0.179887,-0.572621,0.387504,0.087193,-0.152257,0.318332,-0.141436,0.266199,0.399099,0.485815,0.677962,-0.410365,0.115093,-0.319246,0.202416,0.690043,-0.059949,-0.329945,0.445356,-0.312647,-0.313316,-0.046209,-0.157361,-0.517871,-0.016896,0.134779,0.128268,-0.412407,0.296924,-0.583520,0.118197,-0.091783,-0.079389,0.003061,-0.554672,-0.368021,-0.364388,-0.191534,-0.440710,-0.368950,0.163058,-0.063798,-0.495234,0.634924,-0.878853,0.390786,0.496547,0.168694,-0.444081,0.845349,0.277894,-0.081503,-0.254439,-0.040881,0.460748,-0.204938,-0.059815,-0.126259,0.317302,-0.362286,0.194314,-0.540409,0.434954', '1417036', '1291835', '1292211', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4116480', '菲利普船长', '剧情', '2009年，美国货轮“马士基·阿拉巴马”号在船长理查德·菲利普（汤姆·汉克斯 Tom Hanks 饰）的带领下执行在非洲角区域的货物运输任务。该次任务的航线途径海盗猖獗的索马里地区海域。虽然菲利普船长和船员都进行过抗击海盗的训练和演习，但是他们完全没有料到在启程不久就遭遇了四名索马里海盗的登船袭击。菲利普船长在保护船员和货物的搏斗中不幸被海盗劫为人质并带离货船。美国海军等部门接到情报后立即展开大规模营救菲利普船长的行动。本片根据真实事件改编。这是近200年以来美国船只首次遭到海盗的劫持。©豆瓣', '汤姆·汉克斯', '保罗·格林格拉斯', 8.2, 105786, 'tt1535109', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2055407162.jpg', 0.2, 0.8, 15.5, 54.2, 29.3, '0.166185,-0.409310,-0.780912,0.554754,0.345745,-0.101220,0.452051,-0.422551,-0.552422,0.006142,0.367825,0.692016,0.162185,-0.194528,0.605253,-0.076325,-0.848324,-0.507797,-0.234724,-0.099957,-0.458452,-0.536203,-0.217290,-0.539850,0.181070,-0.595480,0.808870,0.237215,-0.008123,0.791564,0.061421,0.136812,-0.379562,0.675746,-0.091890,-0.115305,0.672406,-0.257096,-0.373220,0.283413,-0.411117,-0.192076,0.086452,-0.040735,0.346370,0.754924,0.761791,-0.333988,0.015704,-0.112125,-0.382673,-0.511166,0.273950,-0.166313,1.056399,-0.001349,-0.240850,0.386589,-0.073018,0.012503,-0.337888,-0.053843,-0.546024,-0.122059,0.071316,0.080817,-0.244991,0.266894,-0.523657,0.477431,-0.041755,-0.269388,0.143280,0.585275,0.260394,0.099189,0.088964,0.330233,-0.561628,0.292747,0.655490,-0.257980,-0.078687,-0.195936,-0.073912,-0.677561,-0.051468,-0.565669,0.026168,0.054265,0.320379,-0.247370,-0.259780,0.271650,-0.786886,0.114772,-0.471228,-0.716139,-0.064823,-0.097534,-0.199644,-1.229302,0.428100,-0.370125,-0.081139,0.518300,0.174923,0.331336,0.524253,-0.662141,0.206504,0.847191,0.342930,-0.579363,0.380972,0.209412,0.260380,-0.380274,0.112136,0.105789,0.224171,0.513407,0.228980,0.157050,0.089186,-0.510194,0.030618,0.015929', '1293572', '3871833', '26718836', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4116481', '极乐空间', '剧情', '22世纪中叶，地球并未借助文明和科技的进步变得更加美好，反而在各种贪欲荼毒之下变成毫无希望的废墟荒原。少数极度富有之人抛弃生身故乡，在漂浮于地球之上的空间站上建立了宛若天堂般美好的乐土，继续过着享乐奢靡的幸福生活。而绝大多数的穷苦人不得不留在千疮百孔的地球上，在绝望的混乱之中苟延残喘，同时被迫忍受各种严苛可笑的联邦法规的压迫。他们在富人建立起来的工业系统下努力赚取稀薄的营生，时而仰望苍穹，幻想着早日移民空间站开始新的生活。无奈在政府官员德拉库特（朱迪·福斯特 Jodie Foster 饰）的铁腕掌控下，偷渡者一次次化作宇宙中的碎片。工作中受到强辐射的普通人麦克斯（马特·达蒙 Matt Damon 饰），除非借助空间站先进的医疗系统，否则五天后将一命呜呼。纵使仅有一线生机，也要朝着极乐世界挺进……©豆瓣', '马特·达蒙', '尼尔·布洛姆坎普', 6.4, 97669, 'tt1535108', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2091268902.jpg', 1.9, 12.6, 54.7, 24.2, 6.6, '0.206583,0.432574,-0.902593,0.701974,-0.057847,-0.043581,0.643300,0.185341,-0.424878,0.208662,0.244447,0.608508,0.105064,0.179799,0.240048,-0.051847,-0.459989,-0.491608,-0.338473,-0.109233,-0.346786,-0.475331,-0.578482,-0.296351,-0.365390,-0.460016,0.908322,0.479290,-0.148924,0.091449,-0.261074,0.292445,-0.148859,0.388936,-0.481731,-0.149002,-0.252695,0.088417,-0.412048,0.151086,-0.127442,-0.228259,0.010700,0.149144,-0.117318,0.003039,0.687662,-0.463257,0.115353,-0.391023,0.480174,-0.195742,-0.305276,0.106433,0.081749,0.049049,-0.091683,0.187714,-0.240377,0.182612,0.301317,-0.109838,-0.796133,-0.300529,0.180685,0.016733,-0.516743,0.459008,0.143428,-0.266440,-0.099026,-0.276448,0.075421,0.376570,0.136189,0.655026,-0.197096,0.135895,-0.406452,0.331791,0.630957,0.041422,-0.878444,-0.045118,-0.365610,-0.262306,-0.208721,-0.495631,-0.568154,-0.681126,0.296066,0.077214,-0.059086,0.690292,-0.852182,0.411000,-0.084844,-0.577927,-0.181432,-0.220520,-0.248207,-0.568844,-0.017403,-0.267399,-0.098870,0.273374,0.217412,-0.286247,0.687562,-0.769285,0.420023,0.518128,0.477446,-0.322152,0.392217,-0.203243,0.201551,-0.012018,-0.281957,0.640304,-0.080148,0.708417,-0.054790,0.029503,-0.241849,0.166800,-0.316260,0.734814', '26667010', '1578502', '1304496', '2364054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4117274', '灵动：鬼影实录2', '惊悚', '单身父亲丹尼尔·雷（布赖恩·波兰德 Brian Boland 饰）与美丽的克里斯蒂（Sprague Grayden 饰）结为夫妇，并育有可爱的孩子亨特（William Juan Prieto 饰），连同丹尼尔的女儿艾丽（Molly Ephraim 饰），一家四口过着幸福快乐的生活。2006年的某一天，他们的房子被人闯入，东西翻得乱七八糟，却几乎没有丢失任何东西。此后不久，丹尼尔请人在房子的不同角落安装了摄像头。夜深人静，万籁俱寂，摄像头却记录下一幕幕令人难以置信的画面。雷家的奇怪事件层出不穷，且愈演愈烈，连一向不迷信的丹尼尔也变得深为惶恐。最令他们担忧的是，一切似乎全部指向了那个刚刚1岁多的孩子——亨特。夜晚变得可怕而漫长……©豆瓣', 'Josh Bredehoft', '托德·威廉姆斯', 6.1, 12667, 'tt1536044', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2565329314.jpg', 4.7, 18.5, 50.5, 19.9, 6.4, '0.238872,-0.167247,-0.778768,0.360628,0.005665,-0.114337,1.067429,0.022378,-0.847727,-0.402239,0.105275,0.447989,-0.490433,0.229748,0.058043,0.218376,-0.262336,-0.562221,-0.177518,-0.173144,-0.378746,-0.460038,-0.367165,-0.663099,0.150875,-0.349961,0.275953,0.317853,0.209709,0.228052,0.074799,0.241283,-0.125678,0.441653,-0.111781,0.011367,-0.119176,-0.000243,-0.038064,-0.243993,-0.218126,-0.228452,-0.316430,0.141790,0.106773,0.510305,0.607607,-0.129159,-0.444308,0.035717,0.355526,0.149139,-0.355961,0.098426,0.084788,-0.151661,0.221539,0.134850,-0.153739,-0.189706,0.153990,0.022030,-0.570677,0.180339,0.208028,0.177122,-0.486137,0.694792,-0.373373,0.077662,-0.015398,-0.449269,0.152735,0.002789,0.049173,0.677765,0.058203,0.034296,-0.493910,0.079225,0.490969,0.104531,-0.393249,0.474060,-0.372880,-0.241440,-0.274977,-0.026508,-0.555075,0.277340,0.458772,0.077303,-0.086782,0.455252,-0.577312,0.015079,-0.197961,-0.194136,0.000101,-0.361410,-0.537012,-0.474829,0.083657,-0.452657,-0.538218,0.136315,-0.131148,-0.062649,0.762988,-0.526733,0.198514,0.368326,0.104253,-0.201832,0.642914,-0.130754,0.057106,-0.046475,-0.378630,0.234868,0.051330,0.106330,0.326610,0.268016,-0.318308,0.015508,-0.406403,0.469002', '3005387', '21619567', '1304862', '1417428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4117302', '倾国之恋', '剧情', '故事取材自辛普生夫人沃利斯生平事迹，是麦当娜继2008年《下流与智慧》之后执导的第二部影片，制片成本几乎都是她一个人自掏腰包，影片的总投入达到了3600万美元。影片采取双线结构的，一条讲述英王爱德华八世（詹姆斯·达西 James D''Arcy 饰）和美国女人沃丽丝·辛 普森（安德丽亚·瑞斯波罗格 Andrea Riseborough 饰）之间的传奇罗曼史。“不爱江山爱美人”爱德华以爱情为名却让沃丽丝一生背负了所有的骂名。另一条线是1998年，纽约女子沃丽·维特若普（艾比·考尼什 Abbie Cornish 饰）在面对丈夫冷暴力的同时，着迷于沃丽丝和爱德华的爱情故事。她收集一切关于沃丽丝的资料，一遍又一遍地参观沃丽丝遗物拍卖会的展览。而在多次参观展览馆后邂逅了那里的保安（奥斯卡·伊撒克 Oscar Isaac 饰），让她找到了许久不见的热情。©豆瓣', '艾比·考尼什', '麦当娜', 7.8, 26687, 'tt1536048', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1511949360.jpg', 0.4, 2.8, 26.2, 45.8, 24.7, '-0.062150,-0.133535,-0.485115,0.583628,0.106417,-0.486785,0.651957,0.045646,-0.382571,-0.168354,0.078728,0.747073,-0.355774,0.056786,0.358759,0.242118,-0.476074,-0.761079,-0.003034,-0.113036,-0.153700,-0.581985,-0.216961,-0.296994,-0.086579,-0.375897,0.292494,0.037544,-0.124525,0.317007,0.418905,0.181827,0.056479,0.189616,-0.044436,0.225006,0.252212,-0.086604,-0.288556,0.197775,-0.061521,-0.194330,-0.387104,0.024274,0.005636,0.227806,0.583601,-0.325005,0.138953,0.056527,0.519284,-0.131052,0.048004,-0.083003,0.059958,0.022839,0.270468,0.526279,-0.255598,-0.079961,0.267721,-0.135954,-0.654458,-0.068774,0.046059,0.262374,-0.464108,0.488885,-0.494955,0.042358,-0.048292,-0.232543,0.000838,0.036056,0.326626,0.375807,0.000126,-0.086706,-0.267026,0.483077,0.397217,0.261233,-0.255091,0.368275,-0.120811,-0.422094,-0.229426,-0.237829,-0.473637,0.158692,0.267008,-0.068186,0.110481,0.405557,-0.712324,-0.226483,-0.348228,-0.350940,0.123237,-0.322754,-0.095991,-0.756079,-0.276296,-0.317167,-0.273932,-0.336469,0.182667,-0.331579,0.696311,-0.396996,0.149426,0.414734,0.096847,-0.458298,0.808506,-0.172778,0.016305,-0.003310,0.067079,0.259005,0.048708,0.061372,0.069766,0.378879,0.160891,0.025603,-0.382425,0.638073', '30162520', '2027945', 