INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4118060', 'B+侦探', '剧情', '故事接着《C+侦探》展开。阿探（郭富城 饰）的破案能力得到了充分证明，好友风泽（廖启智 饰）也倍感风光，但风泽却在警局内仍不得志，被调到以争功闻名的卢长官（谭耀文 饰）手下。风泽调任不久，辖区内便发生连环凶案，先后四名死者互无关联，且凶手同样在现场留下了颇为刻意的线索。阿探协助风泽，在卢长官的白眼下提出了凶手的多种可能，最后初步锁定凶手为一名精神分裂症患者。在排查期间，嫌疑犯梁伟业（张兆辉 饰）病发劫持人质，阿探施计将其擒获，但遗憾的发现梁并非真凶。不久，阿探被卢警官的手下恐吓，而风泽又被人撞伤，怒不可遏的阿探找到卢警官，却被告知这个嫌疑犯的攻击性超出他的想象……©豆瓣', '郭富城', '彭顺', 5.8, 31880, 'tt1534786', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p986355464.jpg', 3.8, 21.9, 56, 15, 3.3, '0.298157,0.065306,-0.412965,0.532410,-0.078468,-0.218250,0.661360,0.090813,-0.681218,-0.620071,0.106933,0.186222,-0.233037,0.046329,0.298909,-0.433497,-0.009703,-0.654748,-0.058069,-0.215844,-0.426510,-0.670835,-0.241376,-0.443957,0.015331,-0.012426,0.293755,0.265772,-0.240527,0.354290,0.329796,0.375863,-0.300536,0.580422,0.005206,0.232498,0.226272,-0.165271,-0.210157,0.225424,0.187282,-0.496342,0.104277,0.189736,-0.181522,0.498496,0.676816,0.025588,-0.366779,0.115882,0.353143,-0.327600,0.194992,0.211626,0.613546,0.027878,-0.067693,0.217580,-0.344396,-0.055133,0.101748,0.120904,-0.732059,0.025583,0.366714,0.133566,-0.211691,0.165492,-0.228485,0.100148,-0.183628,-0.134790,0.354079,0.402101,0.384672,0.017517,0.019621,-0.000993,-0.614045,0.260130,0.401987,-0.055629,-0.164123,-0.193528,-0.057981,-0.723586,-0.113298,-0.019492,0.045220,0.185565,0.537912,0.084781,-0.044176,-0.168463,-0.147024,-0.330522,-0.474336,0.275026,-0.515939,-0.161697,0.192740,-0.518815,-0.003240,-0.188964,-0.202304,0.071893,0.053589,-0.387751,0.281750,-0.603158,0.014264,0.122526,0.043235,-0.516839,0.239177,0.202488,0.186118,-0.444350,-0.204181,0.173450,0.573111,0.497407,0.374803,0.258723,-0.269932,-0.403788,-0.330218,0.017456', '1300299', '4132395', '3263169', '4903581');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4120583', '幻影追凶', '剧情', '女主角安娜（米拉·乔沃维奇 Milla Jovovich 饰）偶然在街头目睹一场凶杀案，被歹徒发现后追杀，慌乱的搏斗中安娜受伤跌入河中而幸免一死。安娜成了唯一活下来并看到过凶手真面目的目击证人。警察决定要从安娜身上找到连环杀人案破案的突破口。受伤的安娜一周后从昏迷中苏醒，却发现她看到的每一张脸都在不断变化变形——她再也不能辨认出身边人的脸，包括自己的男友和父亲。这种症状医学上称为“人面失认症”，又称“脸盲症”。凶手似乎也知道了安娜因脑伤患上脸盲症的秘密。为了测试安娜是否真的不能认出自己，凶手不断通过各种手段对安娜进行试探挑衅，安娜感觉到凶手如影随形，随时就在身边威胁着她的生命。最终，凶手确认安娜只能通过衣服的颜色和领带的式样等特征来辨认不同的人，决定挺身而走险，换上了安娜前男友的衣服领带来见安娜，准备伺机将安娜带到偏僻处除掉。然而百密一疏，凶手一个细节上的失误让安娜突然警觉到眼前的男人不是自己的前男友，正是要置她于死地的罪犯。警察接到安娜报警后赶来营救安娜，展开生死较量，并最终将凶手抓捕归案。', '米拉·乔沃维奇', '朱利安·麦格奈', 6.2, 12875, 'tt1536410', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1789678815.jpg', 2.2, 15.3, 58.9, 19.8, 3.9, '0.239982,0.065613,-0.435502,0.403515,-0.117271,-0.135086,0.918539,-0.155088,-0.411244,-0.297118,0.574918,0.782429,-0.230802,0.100171,0.263928,0.211698,-0.753571,-0.921807,0.058560,-0.181318,-0.713524,-0.527687,-0.185331,0.011975,0.185959,-0.347830,0.523064,-0.141780,-0.290739,0.517579,0.265573,0.057529,-0.277860,0.454824,0.082308,-0.107827,-0.096526,-0.313380,-0.325581,0.468083,0.226232,-0.252949,-0.112921,0.485900,-0.213046,0.493785,0.708565,-0.402091,-0.084936,-0.035810,0.227029,-0.207545,0.053753,0.368655,0.130739,-0.043121,0.456729,0.043018,-0.241767,-0.091694,0.211709,0.244418,-0.690961,0.260427,0.153398,0.407372,-0.330499,-0.055163,-0.238029,0.058927,0.177028,-0.438279,0.167476,0.277203,0.358343,0.332256,-0.287602,-0.004817,-0.550143,-0.301073,0.377839,-0.190181,0.010616,0.152407,0.114693,-0.236265,0.073893,-0.047836,-0.042397,0.156980,0.381962,0.216560,-0.467756,0.034906,-0.397362,-0.124116,-0.516536,0.028474,-0.266789,-0.292565,-0.284069,-0.439036,-0.202281,-0.027635,-0.274652,0.030857,-0.040595,-0.442022,0.104256,-0.755696,0.193081,0.589076,0.348654,-0.306954,0.297942,0.160883,-0.053914,-0.415143,-0.300490,0.284107,0.374852,0.528471,0.192008,0.181336,-0.095376,-0.010261,-0.384607,0.295678', '2988294', '1316693', '1298214', '27006896');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4122194', '银魂剧场版：新译红樱篇', '喜剧', '故事发生在日本的江户时代，一名神秘的男子出现在了武士桂小太郎（石田彰 配音）的面前，他手握妖刀“红樱”，要求试刀，这个夜晚之后，桂便下落不明。桂的宠物伊丽莎白（高松信司 配音）找到万事屋的神乐（钉宫理惠 配音）和新八（坂口大助 配音），委托他们寻找主人的下落。同时，银时（杉田智和）也受到委托，寻找四处作恶的红樱的下落。三人的线索汇聚到了一艘空中飞艇上，由于远离警察的管辖范围，飞艇里的恶势力一手遮天。在那里，银时遇见了曾经的战友现在的对手高杉晋助（子安武人 配音），高杉正带领着自己的鬼兵队企图毁灭江户。一面是穷凶极恶的恐怖分子，一边是暴虐嗜血的妖刀红樱，身受重伤的银时能够平安脱险拯救江户吗？此次剧场版重制了《银魂》动画中的《红樱篇》，其中，在原作中未出场的真选组也将在故事中大显身手。©豆瓣', '杉田智和', '高松信司', 9.1, 27478, 'tt1636780', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p612363092.jpg', 0.3, 0.7, 8.3, 26.7, 64, '0.330378,0.048145,-0.483220,0.558719,-0.047717,-0.058815,0.634897,0.018944,-0.227953,-0.177475,0.385592,0.698914,-0.035041,0.312329,0.257194,0.026986,-0.236666,-0.613044,-0.371120,-0.042608,-0.406212,-0.450513,-0.398559,-0.090314,-0.235755,-0.153763,0.733460,0.197664,-0.149616,0.401401,0.389185,0.310850,-0.454948,0.204428,-0.233327,0.014664,0.086707,-0.219839,0.052935,0.444294,-0.171099,-0.524947,-0.017263,0.291045,0.028793,0.355052,0.818071,-0.341762,0.185385,-0.239713,0.078052,-0.253339,0.002364,0.035423,0.399341,-0.074425,0.061255,0.086996,-0.043442,-0.021090,-0.215066,-0.131162,-0.760576,-0.155040,0.059028,0.360810,-0.441317,0.183812,-0.135164,0.095214,0.321509,-0.249203,0.348042,0.101531,0.265609,0.039305,-0.349375,0.034308,-0.443371,0.167759,0.419076,-0.184758,-0.167457,0.008796,-0.011577,-0.393245,-0.399475,-0.161322,-0.291700,-0.268628,0.379344,0.127080,-0.218237,0.013604,-0.542834,-0.047667,-0.033590,-0.141787,-0.086041,-0.033416,-0.112038,-0.680260,0.143018,-0.410193,-0.111899,0.071078,0.076196,-0.212807,0.728409,-0.695670,0.096249,0.659734,0.247683,-0.116644,0.379777,0.038978,0.225587,-0.045188,-0.101596,0.013005,0.247869,0.483842,0.306127,0.274900,-0.118025,-0.107201,-0.578253,0.386410', '25928048', '10467125', '3811356', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4122701', '鬼乱5', '恐怖', '本片分为5个故事：《索命棕榈祭》为了逃避法律责任，母亲将儿子送到偏远的寺庙当苦行僧。少年跟随师傅们来到一个山村，师傅向其讲述了当地用棕榈祭台祭祀饿鬼的风俗。少年本不以为然，最终却发现师傅言之凿凿；《同房鬼病人》青年因车祸骨折，不得已被安置在一间多人病房养伤。不过病房内只有两人，除他之外还有一个脑死亡的老人。夜幕降临，老人竟然起身向青年袭来；《亡命背包客》一对来自日本的青春男女行至泰国境内，他们拦下一辆闷罐卡车。行至半路，车厢后传来连续的敲击声，噩梦就此降临；《亡魂二手车》某二手车行女老板，为了盈利经常将出过车祸的汽车翻新后卖给别人。某晚，她的儿子小德在车行玩耍时失踪，诡异恐怖的事情相继发生；《惊魂鬼片场》一个摄制组正在拍《连体阴2》，扮演女鬼的小根妹突然昏倒在片场，工作人员手忙脚乱将其送到医院。正当摄制组担心进度时，小根妹又重返片场。©豆瓣', '吉拉育·拉翁马尼', '班庄·比辛达拿刚', 7.3, 33013, 'tt1521846', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p768894038.jpg', 0.9, 4.5, 38.1, 43.2, 13.3, '0.032182,-0.168266,-0.431823,0.104673,0.039454,-0.206689,0.871879,0.257945,-0.336418,-0.464520,0.665167,0.546352,-0.121564,0.284769,0.404811,-0.073370,-0.183460,-0.323317,-0.270093,-0.091931,-0.463076,0.070400,0.186387,-0.286119,-0.031450,-0.134779,0.207758,-0.128399,-0.043019,0.351657,0.200306,0.191023,-0.692582,0.150828,-0.314762,0.064450,0.117110,-0.061752,-0.160088,0.314945,-0.231519,-0.357748,-0.180131,-0.285852,-0.128400,0.271618,0.731358,0.021013,-0.314743,-0.023591,0.356261,0.043511,-0.214313,-0.006132,0.226592,0.021731,0.373739,-0.128430,-0.153260,-0.037636,-0.020190,-0.059745,-0.001464,0.234910,-0.242199,0.035804,-0.533846,0.269096,0.036873,0.170334,0.132496,-0.455324,0.304301,0.198595,0.027644,0.491414,-0.132141,0.179792,-0.377159,0.064293,0.579956,-0.159126,-0.007748,0.401872,0.133579,-0.306772,0.205528,0.091144,-0.277268,0.037093,0.396236,-0.187261,-0.129419,-0.076273,-0.313784,-0.251311,-0.261079,-0.176428,0.048360,0.148886,-0.511103,-0.629834,0.259366,0.222372,0.060989,0.231505,0.139272,0.234294,0.347767,-0.320209,0.423733,0.493536,0.129467,-0.219114,0.492947,-0.469938,0.236105,-0.143833,-0.113745,0.099344,0.327186,0.769471,0.060905,0.138977,-0.405735,-0.045330,-0.556574,-0.048175', '10466639', '20451118', '21619567', '20380318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4124917', '虹猫蓝兔火凤凰', '动画', '作恶多端的黑龙被封印在深不可测的天音湖中，每隔五百年便要举行凤凰大典，利用凤凰的叫声加固封印。有一个五百年如期而至，谁知在典礼进行的途中发生了意外，凤凰孵化失败，黑龙挣脱了束缚重返人间，世界陷入了水深火热之中。想要再度封印黑龙，必须前往天音谷寻找七件神器，它们共同吹奏出的乐曲能够催化凤凰蛋。不幸的是，虹猫（谢娜 配音）沉睡在天音湖底，无奈之中，蓝兔（袁慧敏 配音）只得独自和天音大师（张怀武 配音）踏上了寻找神器的旅途。途中，两人遇见了魔术师小狸（谢娜 配音），小狸于无意之中展现出了神奇的能力，成为了行动中不可缺少的重要环节。©豆瓣', '谢娜', '贺梦凡', 7.5, 4437, 'tt1664684', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1365114936.jpg', 3, 6.4, 30.1, 34.8, 25.7, '-0.003569,0.457298,-0.646110,0.412057,0.225783,0.020296,0.312905,-0.016417,-0.433067,0.002317,0.218147,0.398409,-0.216041,-0.077007,0.101085,0.127197,-0.011387,-0.397199,0.198920,-0.096655,-0.149616,0.065592,-0.390873,0.063743,-0.007932,-0.661242,0.899608,0.262533,-0.338123,0.285128,0.025259,0.378573,-0.532289,0.275502,-0.482339,-0.020411,0.183864,0.122634,0.045902,0.656648,-0.141657,-0.397126,0.064887,0.322532,-0.201180,0.111822,0.581030,-0.652003,0.042336,-0.204236,0.186885,-0.248260,-0.377142,-0.095942,0.377298,0.180250,0.185954,0.240198,-0.496280,0.232735,0.010943,-0.242748,-0.697919,-0.102167,0.078756,0.163937,-0.201252,0.178620,0.382382,0.209699,0.194744,-0.351042,0.164649,0.292220,0.441390,0.265204,-0.029054,0.024455,-0.357183,0.057913,0.588795,-0.587869,-0.219525,0.374293,0.198040,-0.443857,-0.112849,-0.274208,-0.031987,-0.006509,0.615107,0.540389,-0.145826,0.204496,-0.655785,-0.105924,-0.397060,-0.171972,-0.166748,-0.150692,-0.243561,-0.535760,0.035143,0.084492,-0.091613,-0.291574,0.048996,-0.241628,0.493090,-0.896303,0.496406,0.603021,0.149641,-0.050255,0.450246,-0.184838,0.316083,-0.231284,0.278235,0.002575,-0.307280,0.668214,0.191127,0.096867,0.305488,0.292547,-0.815797,0.225968', '2051813', '26759819', '3861846', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4126925', '圣杯神器：骸骨之城', '动作', '克莱瑞（莉莉·柯林斯 Lily Collins 饰）打记事起就一直生活在布鲁克林和单亲妈妈乔瑟琳（琳娜·海蒂 Lena Headey 饰）一起过着简单平静的生活。然而，她却突然看到了一些不可思议的惊人怪事，而母亲也在一次暴力冲突后消失不见。就在她和最好的朋友赛蒙（罗伯特·席安 Robert Sheehan 饰）寻找她母亲的过程中，克莱瑞开始发现了隐藏在暗影猎手世界中的黑暗秘密和更加邪恶的危险力量。几个世纪以来，具有一半天使血统的暗影猎手一直在默默保护人类免受邪恶力量的侵害。被恶魔、巫师、吸血鬼、狼人和其他超自然生灵所包围的暗影世界迎来了克莱瑞的加入，她和年轻的暗影猎手杰斯（杰米·坎贝尔·鲍尔 Jamie Campbell Bower 饰）、伊莎贝拉（杰迈玛·韦斯特 Jemima West 饰）和艾雷克（凯文·席格斯 Kevin Zegers 饰）寻找到了关乎克莱瑞母亲未来的古老圣杯，并携手保护圣杯不被坏人抢走。年轻的克莱瑞发掘了自身具备的前所未知的超能力和勇气，并以实际行动证明自己是对抗危险敌人的强大的新生战斗力量……', '莉莉·柯林斯', '哈罗德·兹瓦特', 5.7, 29046, 'tt1538403', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2163975137.jpg', 7.4, 26.9, 44.7, 14.5, 6.5, '0.260208,0.033718,-0.724799,0.510694,-0.227474,-0.177778,0.975034,0.069907,-0.399879,-0.228890,0.209947,0.859604,0.068382,0.045922,0.251769,0.155387,-0.366254,-0.672057,0.065350,-0.225375,-0.403759,-0.598172,-0.480865,-0.293514,-0.033430,-0.827741,0.576438,0.035882,-0.139493,0.346939,-0.020648,0.318617,-0.291028,0.459498,-0.160242,-0.108204,0.284714,-0.105155,-0.387800,0.178781,0.109554,0.023945,-0.191312,0.470451,-0.103805,0.059043,0.467933,-0.735621,0.167169,-0.174528,0.124150,-0.312070,-0.016973,0.060641,0.393745,-0.234447,0.066966,0.186722,0.175659,0.065047,-0.068253,0.030907,-1.012044,-0.019087,0.068014,0.331846,-0.511724,0.555430,0.087229,-0.085354,0.278397,-0.142393,-0.009066,0.178230,0.048134,0.260121,-0.391092,0.115660,-0.386734,-0.107736,0.411387,-0.232050,-0.453953,0.402517,-0.351773,-0.429648,-0.363436,-0.115251,-0.516794,-0.121018,0.477521,0.273237,-0.085387,0.478062,-0.855986,0.003031,-0.301358,-0.016128,-0.113615,-0.343404,-0.182310,-0.628413,-0.258176,-0.465185,-0.365057,0.113430,0.001498,-0.173442,0.770714,-1.021996,0.398568,0.735982,0.438949,-0.317799,0.378856,-0.131470,0.281404,-0.302020,-0.144598,0.315895,0.137354,0.336873,0.184018,0.381756,0.258794,0.186912,-0.162435,0.725877', '3769423', '3005387', '3006892', '10440076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4127270', '精舞门2', '语言:', '由乐天（陈柏霖 饰）领衔的街舞团体“encore”内高手如云，其中编舞王子（邱胜翊 饰）和二号人物peter等人都是街舞界的高手，他们团结一致令无数挑战者铩羽而归。冉秋（谢天华 饰）和绵绵（周奇奇 饰）是一对跳拉丁舞的情侣，为了备战拉丁舞大赛，冉秋希望借鉴街舞那富有感染力的形式为自己的编舞加分，于是令绵绵向乐天学习。从小经历严苛舞蹈训练的绵绵对街舞的“不入流”嗤之以鼻，乐天用自己的言传身教渐渐扭转着绵绵的成见，却不料encore内部出现了分裂：王子为筹措母亲的治疗费离开了团体。乐天为帮助王子决定参加比赛赢取奖金，而他和绵绵的感情，也在慢慢的成长着……©豆瓣', '陈柏霖', '刘宝贤', 4.7, 3823, 'tt4270866', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2459880145.jpg', 23.3, 33.3, 33, 6.4, 4, '0.003226,-0.197017,-0.488029,0.584295,-0.000089,-0.084506,0.382404,0.198534,-0.402510,-0.021202,0.486143,0.558651,-0.204527,0.044582,0.455380,-0.219145,-0.124641,-0.911197,-0.150340,0.148621,-0.031532,-0.233262,-0.103598,-0.039190,-0.099789,-0.332366,0.609536,-0.181802,-0.392087,0.798233,0.294826,-0.056629,0.074700,0.061195,0.126072,-0.131461,0.126349,0.167415,-0.333939,0.286575,0.057480,0.005356,-0.369156,-0.016208,0.019267,0.373070,0.794628,-0.458134,0.198482,-0.018162,0.304128,-0.325321,-0.106163,0.039782,0.059303,0.383121,0.200700,0.309902,-0.006162,0.244866,0.106420,-0.131661,-0.818724,0.067247,0.318609,0.174242,-0.554920,0.619655,-0.057353,-0.367159,0.290996,-0.194029,0.085429,0.325068,0.259649,0.336751,-0.308069,0.144763,-0.311488,0.384680,0.531398,0.112279,-0.161971,0.065232,-0.315952,-0.547685,0.066603,-0.206166,-0.258363,-0.222713,0.074797,0.040223,0.136500,0.175524,-0.633491,0.249028,0.052306,-0.289715,-0.084580,-0.640584,0.069435,-0.634384,-0.117425,-0.292191,-0.159764,-0.123581,0.166257,-0.337664,1.131364,-1.154917,-0.053867,0.442037,0.274442,-0.422075,0.624642,0.101499,-0.017257,-0.192854,-0.379801,-0.099650,-0.472752,0.293221,0.009013,0.611104,0.097562,-0.315163,-0.237474,0.324167', '1826173', '25922902', '26784898', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4132395', '国民警卫队', '喜剧', '爱尔兰都柏林戈尔韦郡探长格里•博伊尔（布莱丹•格里森 Brendan Gleeson 饰）收拾了瘾君子车祸暴毙的残局，迎来了新来报到的探员麦克布莱德，他们勘察犯罪现场，从证据推断杀手的类型，可惜两人思维大相径庭。博伊尔思维极其吊诡，令麦克布莱德完全不得要领。他们曾一同审问嫌疑犯，却发现他只是替死鬼，真凶仍逍遥法外。博伊尔虽然玩世不恭，但却是个孝子，其母大限将至，他挖空心思逗老人家开心。为了破获黑市价值5亿的毒品走私案，美国FBI探员温德尔（唐•钱德尔 Don Cheadle 饰）开始为警官们做案情分析，却屡屡遭博伊尔打断，正当上司要将博伊尔开除时，后者却一针见血地指出了报告中的最大漏洞——四名嫌疑犯中已有一人躺在太平间。这令温德尔对这个拿种族歧视开玩笑的博伊尔刮目相看。麦克布莱德在执勤中意外遭到哲学范儿歹徒杀害，他的妻子上门寻夫，让博伊尔倍感责任重大，他与温德尔踏上了缉凶之旅……', '布莱丹·格里森', '约翰·迈克尔·麦克唐纳', 7.5, 8819, 'tt1540133', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1615452423.jpg', 0.5, 3.5, 31.6, 48.1, 16.3, '0.217659,-0.126644,-0.464131,0.339968,-0.279140,-0.215081,0.798961,0.191632,-0.741751,-0.253745,0.128596,0.549123,-0.208881,0.019860,0.415921,-0.034842,-0.359775,-0.583404,0.039836,-0.132741,0.086832,-0.626154,-0.259664,-0.306929,-0.137200,-0.059647,-0.018466,-0.086700,-0.035073,0.369245,0.216634,0.449016,-0.006835,0.477292,0.045571,-0.001686,0.406179,-0.282221,-0.136066,0.123438,0.151521,-0.194846,-0.238529,0.084525,-0.011380,0.550591,0.423071,-0.088150,-0.028168,-0.066423,0.243266,-0.378365,0.153172,0.152959,0.311550,0.035256,0.025647,0.162011,-0.141574,-0.062314,0.166292,-0.075761,-0.633719,0.112014,-0.021097,0.248920,-0.371142,0.059355,-0.416813,0.185362,-0.176179,-0.051635,0.151125,0.204184,0.295882,0.213209,0.108145,-0.041456,-0.317814,-0.022110,0.182218,-0.116122,-0.150518,-0.010490,0.030673,-0.477230,0.339893,-0.011623,-0.186300,-0.013302,0.215790,-0.218999,0.018528,0.131611,-0.266779,-0.156323,-0.523460,0.101202,-0.358104,-0.234742,-0.040279,-0.594179,-0.011031,-0.017408,-0.262849,-0.023411,0.140554,-0.029253,0.129975,-0.294945,0.023898,0.314982,0.073109,-0.293229,0.296854,0.179849,-0.088535,-0.352618,-0.198566,0.181901,0.444592,0.253242,0.159023,0.337930,0.108269,-0.429945,-0.136612,0.