INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4132407', '捕蝇纸', '喜剧', '男主人公特里普（帕特里克·德姆西 Patrick Dempsey饰）来到银行换钱，刚跟女柜员凯琳（艾什莉·贾德 Ashley Judd饰）搭上话，却悲催的碰到银行被打劫。银行保安系统开启，所有人都成了笼中之鸟。而更巧合的是居然有两伙抢劫犯。由此一段阴差阳错中展开的猫鼠大战拉开序幕。无辜的人质跟笨拙的劫匪间处处周旋，波澜中高潮不断。©豆瓣', '帕特里克·德姆西', '罗伯·明可夫', 7.8, 52771, 'tt1541160', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1119448570.jpg', 0.4, 2.3, 24.8, 51.8, 20.7, '0.535438,-0.121397,-0.462684,0.040326,0.186457,-0.222119,0.982424,-0.232597,-0.235157,0.019217,0.218819,0.272521,-0.796882,0.054337,0.274581,-0.168847,-0.037050,-0.510873,0.054307,-0.086523,-0.062958,-0.193017,-0.504369,-0.030744,-0.250620,-0.165778,0.353841,0.004143,-0.170174,0.292594,0.550964,0.272784,-0.534367,0.361480,0.104794,0.135993,0.223577,-0.003973,0.037404,0.004204,-0.135690,-0.202680,-0.177338,-0.086697,-0.192867,0.562016,0.532352,-0.283615,0.219252,0.114194,0.303350,-0.207562,-0.249832,0.075048,0.423433,0.114852,0.333443,0.021561,-0.035126,-0.116571,0.286392,-0.162773,-0.359968,0.126205,-0.223554,0.412253,-0.271955,0.061553,-0.055513,0.334284,0.131214,-0.180522,0.098369,0.065129,0.455493,0.344810,-0.040673,-0.145462,-0.423938,0.119446,0.434290,-0.091012,-0.249953,0.298391,0.180441,-0.444968,0.406991,-0.101585,-0.279297,-0.135721,0.389135,-0.124517,-0.045703,0.195212,-0.797781,-0.077310,-0.399405,0.145240,-0.249587,-0.354086,-0.247865,-0.682293,0.056306,-0.202610,-0.000491,0.558341,0.315839,-0.092883,0.319454,-0.748611,-0.002652,0.461174,0.222537,-0.238224,0.343035,-0.290537,0.186453,0.055143,-0.169107,-0.110134,0.385562,0.352179,0.420457,0.235282,-0.265774,-0.218880,0.038417,0.261475', '20451118', '10466639', '1301686', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4133814', '线人', '剧情', '为了侦破棘手案件，警方往往借助线人之手获取情报。然而在行动过程中，却常常有意无意置线人于危险之地。一年前，线人废噏（廖启智 饰）的悲惨下场让香港警察李沧东（张家辉 饰）的身心备受煎熬，表面的荣迁始终洗刷不掉铭刻其心中的罪恶感。而如今，他不得不再次与新的线人合作。这次，他找到了命运多舛的小混混何细鬼（谢霆锋 饰）。为了搭救身陷水火的妹妹，细鬼无奈接受了李沧东的任务，打入金行大盗华天（陆毅 饰）的团伙内部获取情报。在细鬼的帮助下，警方掌握越来越多的证据，抓捕的罗网也渐渐收拢。与此同时，细鬼的境遇也愈加危险。一年前的悲剧似乎将再次重演，李沧东该如何选择……©豆瓣', '谢霆锋', '林超贤', 7.4, 140333, 'tt1535492', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p586242594.jpg', 0.3, 2.8, 36.3, 48.2, 12.3, '-0.210023,0.007224,-0.451771,0.426405,0.106531,-0.022280,0.345927,0.061002,-0.625924,-0.133008,0.317990,0.356012,0.030526,-0.094541,0.161158,-0.238511,-0.309260,-0.616783,0.104001,-0.147456,-0.229279,-0.457246,-0.565010,-0.276475,-0.082068,-0.131727,0.793698,0.571106,-0.215161,0.225429,0.194151,0.548491,-0.333633,0.469521,0.038505,-0.123508,0.042777,0.066425,-0.247830,0.150745,0.357959,-0.516383,-0.127472,0.212532,0.033493,0.421741,0.628894,-0.248859,-0.276793,-0.185032,0.392397,-0.415766,-0.085280,-0.068626,0.087200,0.175431,0.221125,0.397847,-0.433526,-0.018567,0.117642,-0.032132,-0.976159,-0.091224,0.415081,0.138756,-0.275113,0.210116,-0.192418,0.298817,-0.089173,-0.309384,0.023801,0.489575,0.382175,0.164184,-0.426744,-0.131644,-0.310064,0.120050,0.564315,-0.026606,-0.101628,0.139191,-0.044234,-0.385638,-0.159358,-0.300530,-0.012610,0.014122,0.441025,0.329405,-0.149956,0.367913,-0.382377,-0.172183,-0.162753,0.131750,-0.076389,-0.307298,0.066214,-0.424347,-0.166892,-0.041663,-0.248765,0.060218,0.192397,-0.196977,0.493753,-0.552563,0.202150,0.556205,0.090117,-0.466431,0.249097,0.143661,0.184519,-0.351378,-0.212550,0.213977,0.302206,0.482954,0.284303,0.000050,-0.151047,-0.339064,-0.274686,0.225998', '26678784', '27073234', '3001114', '35377026');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4133988', '枪王之王', '动作', '在IPSC实战射击赛中，警员庄子维（吴彦祖 饰）打破了赛会纪录，但新纪录很快被香港基金经理关友博（古天乐 饰）改写，后者夺魁。赛后，关友博巧遇蒙面歹徒打劫解款车，解款员被歹徒打死。此时，一个交通警（连凯 饰）路过，被歹徒打伤。为救人，关友博击毙了4名劫匪，并报警。另一歹徒落荒而逃，同时4亿美元债券遭抢。交警获救，护理他的是关有博的女友（蔡卓妍 饰）。因非法持枪伤人，关友博被拘。庄子维审问时发现对方超常冷静。面对检方控诉，关友博沉着应对，结果当庭获释。女上司（李冰冰 饰）接他回家，但他对她的殷勤并不领情。关友博的账户存在资金周转问题，他正想方设法拖延还款时间。庄子维在查案中毫无头绪，于是请教老枪王（方中信 饰），从对话中，他似乎嗅到了关键性的线索……©豆瓣', '古天乐', '尔冬升', 6.7, 138166, 'tt1535495', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p530615773.jpg', 0.8, 7.2, 55.1, 30.9, 6, '0.034830,0.170895,-0.371317,-0.021465,-0.149735,-0.011114,0.560752,-0.076199,-0.278450,-0.277180,0.182671,0.254252,-0.257143,-0.117844,0.241572,-0.213369,-0.183302,-0.542229,0.033026,0.034430,-0.291437,-0.383848,0.005186,-0.184682,-0.066120,-0.003989,0.244108,0.052696,-0.266726,0.403838,0.212809,0.174091,-0.199588,0.485870,-0.094777,0.119993,0.145092,-0.406071,-0.055312,0.139670,0.070800,-0.363657,-0.220132,-0.051404,-0.021518,0.737877,0.501053,0.125969,-0.074562,0.016771,0.191142,-0.185386,-0.021004,-0.061407,0.301497,-0.072345,0.029931,0.171528,-0.166264,-0.055965,0.198338,0.051639,-0.416729,0.249512,-0.231093,0.127895,-0.234460,0.100226,-0.360509,0.353206,-0.074119,0.091663,0.067220,0.142902,0.351755,-0.119352,0.064831,-0.178922,-0.536676,0.271782,0.097478,-0.108941,0.198516,0.324584,-0.264667,-0.529845,0.251186,-0.275058,0.022667,0.017678,0.585226,-0.146288,-0.188884,-0.319883,-0.054677,-0.202577,-0.422008,0.140998,-0.399406,-0.343905,-0.288476,-0.474734,0.052664,0.092875,-0.321265,0.186684,0.120805,0.118485,0.159557,-0.408052,-0.201476,0.478587,0.390472,-0.242283,0.334911,-0.088735,-0.154716,-0.237073,-0.205033,-0.069918,0.387208,0.391223,0.187193,0.118579,-0.238951,-0.359987,-0.007247,0.010248', '1947080', '2968611', '26235349', '1301345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4134631', '叶问前传', '动作', '20世纪之初，国际局势瞬息万变，古老的中国更处在生死存亡的危急时刻。远在广东佛山，少年叶问和异姓兄弟天赐拜入咏春拳名师陈华顺（洪金宝 饰）门下学习拳法。叶问天资聪颖，资质不凡，十年期间便在师兄弟之间跃然而出。成年后，叶问（杜宇航 饰）告别从小一起长大天赐（樊少皇 饰）和小师妹美慧（陈嘉桓 饰），只身来至香港读书。在此期间，他教训了歧视中国人的洋鬼子，不仅名震香江，更藉此拜入咏春宗室梁赞之子——梁壁（叶准 饰）的门下。回到佛山，叶问因梁壁咏春正统与否的问题与大师兄吴仲素（元彪 饰）一度发生分歧。不久，精武会馆主席被人谋害。心怀鬼胎的日本人蠢蠢欲动，而昔日好友天赐似乎又完全变了模样……©豆瓣', '杜宇航', '邱礼涛', 5.8, 23270, 'tt1641638', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2631652150.jpg', 4.7, 22.4, 56.5, 13.2, 3.3, '0.012883,-0.052354,-0.544189,0.355974,0.006556,-0.419997,-0.049368,0.388978,-0.646995,-0.429582,0.369335,0.751063,-0.123366,0.084765,0.230000,-0.144826,-0.033043,-0.506894,0.169923,-0.354705,0.101339,-0.394364,-0.038747,0.037278,-0.246369,-0.363967,0.390768,0.041034,-0.189922,0.596077,0.042963,0.002975,-0.130766,0.309091,-0.159007,0.154562,0.106539,0.243494,-0.475438,-0.107391,-0.062538,-0.314327,-0.252523,-0.120395,-0.088930,0.196285,0.335380,0.012920,-0.055958,-0.541921,0.190967,0.123335,-0.429891,0.014626,0.515439,0.132627,0.403362,0.457983,0.210375,0.168732,-0.140450,-0.166451,0.088077,0.418382,0.428575,-0.029351,-0.372745,0.661761,-0.036483,-0.209641,-0.193889,-0.478395,0.103940,0.470279,0.110300,0.142135,-0.044621,0.020843,-0.319874,0.285210,0.489378,-0.083445,0.069013,-0.072505,0.386196,-0.399489,0.119467,-0.363059,-0.025733,0.052729,0.325444,-0.217321,-0.107862,0.490482,-0.237414,0.321331,-0.072250,0.358894,-0.078662,-0.178960,0.081504,-0.645042,-0.108852,-0.409341,0.036348,-0.274463,0.189910,-0.162672,1.073208,-0.670523,0.111293,-0.135896,0.472667,-0.276274,0.564683,0.008678,0.037125,-0.319322,-0.452599,0.198396,-0.056851,0.354705,-0.222141,0.211969,-0.190307,0.035736,0.036317,0.015396', '25922902', '27602116', '3811356', '1483630');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4135434', '雪花秘扇', '剧情', '十九世纪初的中国，妇女还保留着裹小脚的复苏。在湖南的某个小镇，百合（李冰冰 饰）与雪花（全智贤 饰）按照当地风俗结为老同，自幼生活在一起，靠着女书交流彼此的心事，她们之间深厚的情感无 人能够取代。随着年龄的长大，百合与雪花必须嫁作人妇，从此开始了各自的苦难人生。21世纪 初，尼娜（李冰冰 饰）即将因公赴美，却在临行前夕得知好友索菲娅（全智贤 饰）车祸住院的消息。索菲娅是她自学生时代便在一起的好友，她们更按照古老的风俗结为老同。这场车祸，让久久失去联系的两人重新聚首……本片根据美籍华裔畅销作家邝丽莎所著小说《雪花与秘扇》改编。©豆瓣', '李冰冰', '王颖', 5.8, 76270, 'tt1541995', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1263875538.jpg', 6.3, 24.5, 48.1, 16.3, 4.7, '0.268280,0.077767,-0.545954,0.499627,0.226176,-0.145195,0.448115,0.209724,-0.467464,-0.273088,0.128927,0.794701,-0.278565,0.308072,0.343272,-0.055545,-0.383033,-0.920969,0.069224,-0.151243,-0.199257,-0.451123,-0.077608,0.080753,-0.252196,-0.454863,0.850307,0.040398,-0.181077,0.698239,-0.004649,0.008975,-0.555337,0.090056,-0.406815,0.016189,0.020361,0.332637,-0.781462,-0.104676,-0.027875,-0.244040,-0.076264,-0.225629,0.016055,0.239919,0.732283,-0.206322,0.058373,-0.025141,0.501861,0.221279,-0.171889,-0.004770,0.439638,0.053263,0.483722,0.410170,-0.076346,0.116061,-0.030303,-0.082544,-0.143275,0.031131,0.349751,0.267770,-0.508786,0.491487,0.134436,-0.011242,0.046476,-0.223739,0.200242,0.405297,0.093199,0.525862,-0.011622,-0.090466,-0.195623,0.549055,0.657775,0.210698,-0.184620,0.337439,-0.403271,-0.352781,-0.214697,0.265843,-0.397521,0.026092,0.321119,0.058208,-0.195629,0.386248,-0.645456,-0.139274,0.042778,-0.009125,0.485187,-0.361432,0.136250,-0.824994,-0.417890,-0.680543,-0.144040,-0.000803,0.328744,-0.207124,0.905238,-0.824759,0.334370,0.301482,0.240089,-0.298009,0.412741,0.222538,0.259485,-0.357812,0.099257,0.455933,-0.293118,-0.017614,-0.026807,0.266597,-0.172898,0.370096,-0.357852,0.257836', '3811356', '26365262', '1780122', '25922902');
