INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4135443', '恶人', '剧情', '在一个彷徨空洞的夜晚，青春靓丽却虚华浮躁的保险公司推销员石桥佳乃（満島ひかり 饰）陈尸福冈的三濑岭。她生前曾通过交友网站与土木作业工人清水祐一（妻夫木聡 饰）交往，后为攀援富贵而转投大学生増尾圭吾（岡田将生 饰）的怀抱，这种轻浮行径直接导致了她死亡的悲剧。在此之后，增尾成为主要嫌疑人受到警方盘查。而痛苦的清水则通过网络结识了孤独的服装店营业员马込光代（深津絵里 饰），两个惺惺相惜的疏离之人展开了绝路逃亡……本片根据吉田修一的原著小说改编，并荣获2010年电影旬报十佳影片第1名、日本单元最佳导演、最佳剧本和最佳男配角奖；第34回日本电影学院金像奖最佳男主角、最佳女主角、最佳男配角、最佳女配角和最佳音乐奖。©豆瓣', '妻夫木聪', '李相日', 7.7, 23632, 'tt1542840', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p684630800.jpg', 0.5, 3.1, 28.1, 47.6, 20.6, '0.037113,-0.151258,-0.301931,0.594270,0.285206,-0.269560,0.478276,0.226481,-0.323222,-0.130144,0.185028,0.861664,-0.154397,0.079755,0.268466,-0.066258,-0.247618,-0.746756,-0.390373,-0.188618,-0.051310,-0.157745,-0.298669,0.361500,-0.173241,-0.163382,0.776629,-0.062120,-0.088587,0.577138,0.580831,0.075984,-0.193279,0.004731,0.106293,0.105056,0.105802,0.033404,-0.393333,0.381675,-0.155459,-0.403670,-0.227009,-0.120142,-0.036667,0.425289,0.927081,-0.160366,-0.120138,0.024007,0.848328,-0.170068,-0.385569,0.007209,0.307141,-0.183735,0.209180,0.058891,-0.135402,0.296879,-0.066478,0.047316,-0.793670,-0.044497,0.076868,0.202454,-0.274937,0.293967,0.045751,0.076570,0.142695,0.085885,-0.007035,-0.037521,0.467994,-0.047956,-0.291780,-0.011681,0.159251,0.802371,0.107003,0.178102,-0.322137,0.512104,-0.184368,-0.608943,0.014722,-0.212034,-0.371978,-0.066249,0.612850,0.120893,0.137336,-0.086831,-0.547674,-0.133170,0.079569,-0.113464,0.011820,-0.018381,-0.112121,-0.891493,0.091060,-0.119777,-0.078719,-0.077248,0.223903,-0.192860,0.685344,-0.446274,0.213055,0.608180,-0.043067,-0.454291,0.636795,0.175188,0.091834,-0.326818,-0.197280,0.217311,-0.110760,0.599655,-0.095563,0.323099,-0.396801,-0.285024,-0.592381,0.298953', '22265121', '2027945', '1322847', '1388176');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4135710', 'Hello！树先生', '剧情', '树（王宝强 饰）的父亲亲手杀死了树的大哥，后来父亲去世了，但两人影像却时常浮现在他脑海。在汽修铺工作中，他开始眼花，后来出了工伤，住进医院，护士苹苹（何洁 饰）给他拆线时，厂长将他辞退了。他的家面临拆迁，因为村长小舅子在这开矿，他感到十分无助，没事在村里闲逛，与朋友喝酒， 没钱就向弟弟伸手。某天，他碰到了朋友的表妹张小梅（谭卓 饰），一见钟情。但在相亲中，他发现小梅是个聋哑女孩。然而，这并没有阻隔他们的爱情。朋友结婚，他卖力地张罗，却无意中得罪了村长的小舅子，受到侮辱。一气之下，他来到城里找朋帮忙。在朋友的奥校打工时，他见证了朋友搞婚外情的事实。他通过短信跟小梅传情，最终决定与她结婚。然而，这场婚礼却进行得异常艰难……©豆瓣', '王宝强', '韩杰', 8.2, 256055, 'tt2043878', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1271999126.jpg', 0.6, 2.1, 17.4, 44.3, 35.6, '0.348158,-0.133905,-0.692291,0.279724,-0.296135,-0.321231,0.715276,0.241089,-0.510579,-0.294045,0.218565,0.716193,-0.192385,0.453180,0.213556,0.049047,-0.208265,-0.489640,0.380367,0.055564,-0.207867,-0.251622,0.105474,-0.138411,-0.093604,0.021872,0.374194,-0.054353,-0.033763,0.468180,0.020258,0.015788,0.006403,0.494639,-0.204609,0.350764,0.058656,0.177747,-0.281027,0.169585,0.149594,-0.282760,-0.224310,0.223993,0.102340,0.560772,0.498541,0.119442,-0.270212,0.076316,0.242102,-0.317682,0.009284,0.180307,0.188088,0.091048,0.291148,0.163827,-0.306877,-0.210252,0.040337,-0.042588,-0.335204,0.247854,0.047544,0.062354,-0.689792,0.491070,-0.118403,0.142655,-0.001221,-0.506594,0.375527,0.282925,-0.051557,0.350773,-0.380439,-0.009113,-0.523363,0.357625,0.757968,-0.084579,0.124975,0.394622,-0.194536,-0.211864,0.233604,-0.012328,-0.482191,0.127180,0.230447,-0.084830,-0.516007,0.072907,-0.431659,-0.231302,-0.066264,-0.050998,-0.082952,-0.429202,-0.223880,-0.217887,-0.253574,-0.260647,-0.528674,0.040501,-0.191878,-0.280374,0.359242,-0.942091,0.097349,0.557071,0.517082,-0.385336,0.786391,0.312303,0.018741,-0.263183,-0.055191,-0.157132,0.042735,0.439441,0.359696,0.144068,0.076392,-0.039643,-0.406265,0.315870', '1302384', '2990737', '1308755', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4136036', '晚秋', '剧情', '《晚秋》根据李满熙导演1966年的同名电影改编而成，影片以美国西雅图为背景，讲述两名男女在异国他乡的爱情故事。本在监狱服刑的安娜（汤唯 Wei Tang 饰）因母亲过世获得三天假期，七年来首次踏上归家之路，并于长途汽车上邂逅了勋（玄彬 Bin Hyeon 饰）。不够车钱的勋用手表做抵押借了安娜的钱，约定到西雅图再见。一个是弑夫假释的女犯，一个是专门“吃软饭”的情场骗子，两个互相隐瞒了身份的陌生人就这样在邂逅中渐生情愫，在短短三天内谈了一场浪漫恋爱。©豆瓣', '汤唯', '金泰勇', 7.1, 234840, 'tt1542482', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1486436454.jpg', 1.2, 7.1, 42.1, 36.7, 12.9, '0.207426,0.117330,-0.466279,0.420391,0.042037,-0.219942,0.558635,-0.097846,-0.157501,-0.396097,0.240315,0.792312,-0.316361,0.238942,0.408250,-0.186915,-0.312601,-0.712729,0.071029,-0.556298,-0.131981,-0.522129,0.003175,0.239358,-0.006740,-0.219360,0.616733,-0.181354,-0.011009,0.512609,0.284608,0.028985,-0.077015,0.025061,-0.337154,0.146010,0.171673,0.265396,-0.602938,0.323502,-0.073454,-0.366048,-0.056822,-0.101769,0.023063,0.342095,0.806138,-0.047795,-0.281012,0.003173,0.503673,0.066993,-0.331694,-0.245142,0.267114,0.082685,0.262747,0.519275,-0.396346,0.329344,-0.041182,-0.207875,-0.618940,-0.041917,-0.199341,0.035233,-0.574333,0.554114,-0.040828,-0.105146,-0.060457,-0.414440,-0.007740,0.246525,0.114831,0.585462,-0.121658,-0.072946,-0.585427,0.614792,0.664368,0.212714,0.028700,0.729915,0.143700,-0.441230,0.027939,0.023478,-0.500415,0.148274,0.184995,-0.408092,-0.167042,0.116996,-0.713860,0.019327,-0.189564,0.009885,0.373345,-0.414153,-0.072599,-0.738090,-0.174668,-0.371159,-0.335560,-0.058114,0.374802,-0.386857,0.443707,-0.672157,0.254981,0.583009,0.204509,-0.620020,0.816303,0.400989,0.153401,-0.140581,0.244309,0.127237,0.033940,0.088543,0.112610,0.306554,-0.073021,0.138747,-0.491062,0.350524', '6858739', '3811356', '4301278', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4139833', '最后的约定', '剧情', '清洁公司职员益子悟（大野智 饰）、保险公司营销人员富泽友纪夫（樱井翔 饰）、咖啡厅店员棚田昭（相叶雅纪 饰）、快递公司速递员后藤望（松本润 饰）、保安中心派遣职员山际修司（二宫和也 饰），这五个生命中几乎没有任何交集的年轻人，却因一起意外事件而被绑在了一起。某天，他们同时出现在位于东京的能源生物公司大楼内，而一伙武装分子突然冲了进来，封闭所有出口，将大厦内的所有人挟持为人质，并要求刚好外出的社长新见朋彦（津川雅彦 饰）在九十分钟之内缴纳高达三亿日元的赎金，否则将炸毁整栋大厦。难以预测的命运和结局，尽在这九十分钟……©豆瓣', '大野智', '佐藤祐市', 7.2, 7158, 'tt1573889', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2157158421.jpg', 0.9, 5.5, 42, 34.1, 17.4, '0.021017,0.075027,-0.580685,0.117492,0.165167,-0.091289,0.794193,0.376198,-0.266573,-0.267021,0.222681,0.585297,-0.149593,-0.008915,0.393720,-0.207308,-0.207298,-0.608890,-0.615440,-0.386487,-0.286571,-0.345859,0.253212,-0.277989,-0.068718,0.061772,0.607033,0.171931,0.200117,0.373178,0.289263,0.215018,-0.477322,0.259733,0.240561,-0.062918,0.373444,-0.137907,-0.207371,0.184451,-0.596197,-0.130083,0.161079,0.024143,0.072996,0.272118,0.568809,-0.102126,-0.065846,-0.142052,0.088367,0.036687,-0.094424,0.052046,0.505899,0.011808,0.375754,0.284078,-0.467431,0.035552,0.356190,0.048282,-0.738618,-0.151638,-0.079528,0.194255,-0.281617,0.411194,-0.105189,0.058776,0.077808,-0.013539,0.047056,0.162727,0.161486,0.043370,-0.168989,-0.053638,-0.396680,-0.044254,0.294749,-0.268265,-0.018407,0.156360,-0.098337,-0.307338,-0.339837,0.069358,-0.118192,-0.159296,0.113800,0.118109,0.318630,-0.334296,-0.641070,-0.124236,-0.047773,-0.308632,-0.020230,-0.195621,-0.142227,-0.993077,0.370950,-0.246064,-0.249192,0.535513,0.303760,0.139769,0.324869,-0.666732,-0.180226,0.522980,0.578089,-0.312088,0.730066,-0.330457,0.212449,-0.115595,-0.197510,-0.124852,0.187730,0.830812,0.101498,0.356844,-0.135344,-0.303593,-0.224840,-0.078792', '10466639', '25723905', '1307897', '1297659');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4139888', '穿越时空的少女', '爱情', '高中生芳山光（仲里衣纱 饰）已成年，但是在她的脑海里，父亲长谷川政道的印象只是儿时分别的背影。身为电影摄影师的他总是很忙碌，似空中飞人，芳山光唯有与母亲芳山和子（安田成美 饰）为伴。因为在大学药学研究工作取得了成果，母女俩的生活出现了转机。然而，不幸接踵而至。和子遭遇车祸，昏迷中留下一句“回到过去，再见一面深町一夫”。光决定帮母亲实现心愿，于是她利用母亲开发的药物，穿越时空回到了70年代。但由于技术失误，光把时间搞错了，回到了1974年而非1972年，所以寻不到一夫的线索。无奈之下，她只得求助偶然遇见的大学生凉太（中尾明庆 饰），后者陪她一起寻找一夫。在凉太的狭小公寓里，光协助他完成电影梦想，而后者却渐渐爱上了她……©豆瓣', '仲里依纱', '谷口正晃', 7, 15641, 'tt1614408', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p612359096.jpg', 1.2, 8, 43.5, 34.8, 12.4, '0.015032,0.031476,-0.397878,0.245637,0.097610,-0.445547,0.466403,-0.046557,-0.579419,-0.589604,0.078845,0.518089,0.029185,0.409828,0.166022,-0.096823,-0.266246,-0.663271,0.396733,-0.243292,-0.149363,-0.369512,-0.013205,-0.042280,-0.092993,-0.415852,0.782257,0.163582,0.028848,0.396362,-0.156907,0.153830,-0.090204,0.393004,-0.050084,0.108540,-0.119627,0.248923,-0.341633,0.264671,0.290144,-0.331568,-0.212637,-0.108010,0.181653,0.332603,0.772375,-0.108743,-0.307119,-0.087446,0.383081,-0.359602,-0.317742,0.026379,0.048722,0.345689,0.168657,0.199313,-0.323894,-0.042112,-0.107082,-0.003526,-0.374185,0.121682,0.121714,0.118854,-0.541069,0.419443,-0.171414,-0.061488,0.005382,-0.493655,0.117863,0.120863,0.350183,0.340604,-0.451087,0.275265,-0.307279,0.245972,0.661401,-0.065762,-0.032237,0.708903,-0.041615,-0.258431,-0.051428,-0.171534,-0.186843,0.155316,-0.086400,0.096038,-0.250456,0.068184,-0.515909,-0.014893,-0.195386,-0.001591,0.179717,-0.330069,-0.192962,-0.357455,-0.048172,-0.057347,-0.486941,0.115005,-0.071238,-0.540113,0.435120,-0.692944,0.101888,0.419611,0.299701,-0.361158,0.900477,0.044183,0.094396,-0.207657,0.317387,0.503161,-0.226872,0.165446,0.040415,0.005860,-0.101852,-0.127657,-0.559174,0.212812', '1417036', '2124718', '3025450', '27191829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4144556', '时光倒流的话', '爱情', '欧阳中（王合喜 饰）在某个暴雨天去市郊维修街灯时，意外发现了一个自己学生时代曾用过的旧式电话亭，他尝试拨出了一个号码，居然可以穿越时空，接通到二十年前就已去世的女友司徒心心（薛凯琪 饰）。在之后的几次电话聊天中，欧阳回忆起在与心心恋爱时，常常因为心心家电话占线而误会心心与别人煲电话粥，冷落了自己。现在他才发现，原来那个曾经每晚与心心一直在电话里聊天的男人，竟然是二十年后的自己……欧阳回想起与现在的妻子（汤宝如 饰）初次相识，就是在心心的葬礼上。然而却不知道，一个更大的秘密正在等待着他……©豆瓣', '薛凯琪', '麦启光', 7.2, 6333, 'tt1712554', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2376294181.jpg', 0.6, 4.7, 40.9, 40.5, 13.3, '0.099861,0.219466,-0.843417,0.713858,-0.276364,-0.401104,0.936399,-0.110634,-0.914265,-0.467253,-0.321422,0.820535,-0.269261,0.606420,0.436684,0.024524,-0.324068,-0.813031,0.102329,-0.118280,-0.532821,-0.393090,-0.450792,-0.099922,0.000942,-0.049417,0.131692,-0.027039,-0.087132,0.597064,0.039146,-0.006972,-0.249329,0.854962,-0.047917,0.210862,-0.080776,0.564259,-0.127687,0.244636,0.089863,-0.574433,-0.214747,0.165309,0.164947,0.465920,0.293580,-0.232785,-0.261803,-0.099877,0.098959,-0.168357,-0.331017,0.260781,0.351661,0.249025,0.771927,-0.026502,-0.528682,0.044512,0.014364,-0.018741,-0.272162,-0.044555,-0.390573,0.120537,-0.545034,0.489826,-0.547999,-0.054700,0.120109,-0.638286,0.618285,0.362646,0.208487,0.611430,-0.663519,-0.351734,-0.543487,0.250163,0.638932,0.219204,0.168855,0.469717,0.449323,-0.425853,-0.248108,0.354802,-0.616555,0.059564,0.302455,0.026602,-0.372258,-0.037368,-0.361093,-0.215443,-0.027322,-0.099112,0.110794,-0.545238,-0.479710,-0.439148,-0.218670,-0.502984,-0.486474,0.480854,-0.024585,-0.152286,0.435038,-1.409106,0.453739,0.324163,0.025293,-0.367754,0.545505,0.258309,-0.053691,-0.146801,0.308698,0.315197,-0.066000,0.365830,0.027171,0.383822,-0.297495,0.028838,-0.593585,0.412607', '1308755', '2052978', '1296332', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4144683', '神秘博士：火星之水', '科幻', '《火星鬼水》是《神秘博士》2009特别篇第二弹，于11月15日在BBC1播出。制作人Russell T Davies透露，这集会和接下来的2集关系密切，但并不是三部曲的第一部分。本集献给2009年10月过世的前"神秘博士"编剧兼制作人Barry letts。故事发生于2059年，火星。博士有了新搭档Adelaide Brooke（Lindsay Duncan饰演），火星殖民地Bowie基地1号基地的首领。她可以说是迄今为止博士遇到的最聪明、最坚强的伙伴。Peter O''Brien客串演出Adelaide地副手Ed Gold。David Tennant 饰演 博士David Tennant 于1971年4月18日出生在苏格兰的West Lothiam.原名为David JohnMcDonald..在他3,4岁的时候,由于看了BBC的剧集《神秘博士》（该剧首播于1963年），他决心要成为一名演员，并在上学之前就在在电视上露了脸。David Tennant在Bathgate长大，是TheProclaimers乐队的超级乐迷。他毕业于Paisley Grammarschool，在那期间他写下了自己是多么想成为一名职业演员并在《神秘博士》中出演主角。DavidTennant在参加一个周六青年俱乐部的聚会时被苏格兰电视台发现。他在苏格兰皇家音乐戏剧学院学习表演。 2005年，DavidTennant的梦想实现了。他在BBC新一季的《神秘博士》里扮演博士。自此之后，David Tennant的名字就广为人知了。Lindsay Duncan 饰演 Adelaide Brooke英国女演员Lin', '大卫·田纳特', '格雷姆·哈珀', 9.1, 7506, 'tt1413314', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2151616662.jpg', 0.5, 0.7, 6.7, 26.1, 66, '-0.057896,-0.126061,-0.590820,0.436492,-0.117806,-0.188733,0.525108,-0.150450,-0.506754,-0.366625,0.199554,0.958862,-0.296190,0.338026,0.479663,-0.157726,-0.232365,-0.655879,0.002965,-0.533659,-0.080164,-0.439943,-0.114297,-0.132029,0.117017,-0.688198,0.957336,-0.034590,-0.061165,0.357342,0.293105,0.162767,0.143106,0.209561,-0.269423,-0.083259,0.315483,0.077638,-0.329968,0.507854,-0.123155,-0.397116,-0.191113,-0.266630,0.078076,0.094216,0.746557,-0.172312,0.014259,0.011322,0.638678,-0.341879,-0.296503,-0.176271,0.585924,0.201599,0.141559,0.486179,-0.084039,-0.086738,-0.202574,-0.513433,-0.791120,0.024474,0.248108,0.352409,-0.649424,0.783455,-0.259865,-0.064323,0.151067,-0.297385,0.341730,0.151941,0.111331,0.466597,0.016931,0.248255,-0.291701,0.702942,0.593782,0.020566,-0.260926,0.411978,0.108416,-0.648013,-0.164719,-0.227939,-0.337822,0.308187,0.071341,-0.132798,-0.196475,0.103833,-0.511933,0.115207,