INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4145476', '得闲炒饭', '剧情', '律师Macy（吴君如 饰)在为被控虐妻的广告公司老板Robert（张兆辉 饰)辩护时两人发生一夜情致使Macy怀孕。心理矛盾的她去参加单亲妈妈心理辅导班，却不想意外遇到中学时的恋人Anita(周慧敏 饰)。之前Anita和十九岁的Mike（陈伟霆 饰)也因初次约会发生一夜情不幸中招怀孕。当年浪漫回忆涌现眼前，发现两人仍然钟爱对方，决定再走在一起。Anita想与Macy一起生活共同抚养孩子，可Macy对待感情却不敢承担，她的好友惠惠（谷祖琳 饰)和Eleanor（万绮雯 饰)也都为她担心。同时，Anita在公司饱受不公平待遇，惠惠和Eleanor召集了一群同性恋人士进行示威。Macy也第一次真实面对自己不安定的感情态度。Robert和Mike作为孩子的父亲也想对此负责。最终Macy是否会勇敢去承担自己的职责？这四个人打破常规男女关系的人会有如何的命运？', '周慧敏', '许鞍华', 7.1, 60300, 'tt1694518', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p685532303.jpg', 0.6, 5.3, 43, 40.5, 10.6, '0.199720,-0.222847,-0.830173,0.291537,-0.174968,-0.027294,0.618587,0.127657,-0.450667,-0.454244,0.184605,0.747088,-0.027944,0.323941,0.108763,-0.196289,-0.274847,-0.659200,0.210345,0.091508,-0.188436,-0.422335,0.027536,-0.285453,-0.112017,-0.128076,0.512270,-0.106226,-0.213764,0.466769,0.515546,0.223489,-0.255930,0.521156,0.096924,-0.172759,0.106397,0.584583,-0.485936,-0.054650,0.195872,-0.145098,-0.172663,0.214315,0.188067,0.354955,0.583447,-0.068231,-0.373759,-0.118430,0.281502,-0.218169,0.063432,0.237177,0.145922,-0.038872,0.300471,0.369490,-0.057998,0.067072,0.061861,-0.001701,-0.693288,0.033344,0.433366,0.016993,-0.517950,0.507911,-0.160479,-0.190226,0.216844,-0.160798,0.140213,0.606071,0.416549,0.381684,-0.319099,0.021926,-0.240322,0.182310,1.148508,0.133356,-0.059657,0.305081,-0.434353,-0.341993,0.012018,-0.236093,-0.542555,0.269256,-0.247266,0.200549,-0.419419,0.319488,-0.277694,-0.033193,0.015971,0.165132,0.099367,-0.617504,0.252897,-0.237750,-0.205937,-0.602724,-0.441514,0.045620,-0.013203,-0.273428,0.518674,-0.811914,0.089152,0.453882,0.507340,-0.991170,0.852451,0.627528,-0.020312,-0.347085,0.020631,0.126726,-0.244949,-0.061643,-0.145672,-0.009559,0.382744,-0.020300,-0.089347,0.054950', '25721544', '1293265', '1308035', '1494897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4146512', '致命急件', '动作', '速递员威利（约瑟夫·高登-莱维特 Joseph Gordon-Levitt 饰）的自行车是一辆经过改装的fixed gear，钢制车架，，再加上他的车技和灵敏的反应，每天都能在拥挤的街道上穿行。一天，一个女人给了他一个“非常重要的急件”，要他在90分钟内把这个东西送到唐人街。可是在半路上，却又警察把威利拦了下来，并用强迫的方法要威利交出那个急件。走投无路的威利只好私自拆开了信封，并发现了一个惊人的秘密。那么，发现秘密的威利能在90分钟内把这个消息准确送达么？他的自行车能跑得过警车和黑帮的速度么？©豆瓣', '约瑟夫·高登-莱维特', '大卫·凯普', 7, 31699, 'tt1547234', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1629759330.jpg', 1.1, 5.2, 44.7, 39.5, 9.4, '0.599033,0.302791,-0.592737,0.735617,-0.232750,-0.196243,0.656193,-0.004769,-0.578767,-0.034345,0.125419,0.737320,-0.083075,-0.082732,0.270234,0.200642,-0.310485,-0.597318,0.103665,-0.345689,-0.679869,-0.514175,-0.276841,-0.482584,0.195084,-0.222237,0.112879,-0.051313,0.181072,0.322733,0.327118,-0.252138,0.077445,0.552761,-0.558314,0.146680,0.133718,-0.301467,0.241918,0.507358,0.050453,-0.558710,0.171240,0.215846,0.025016,0.349209,0.632732,-0.122447,-0.274945,0.480697,0.208434,-0.205114,-0.073488,0.032988,0.212139,-0.184682,0.030731,0.188796,-0.399996,0.168973,0.093311,0.136316,-0.792437,-0.136048,-0.503485,0.146927,-1.067542,0.365355,-0.472913,0.092218,-0.107814,-0.720432,0.337775,0.227442,-0.238311,0.484722,-0.194318,-0.256257,-0.828642,-0.018864,0.361951,-0.186019,-0.063015,0.495340,-0.067978,-0.559739,-0.184846,-0.253886,-0.443177,-0.097845,0.854939,-0.020236,-0.325115,-0.312882,-0.664521,-0.014931,-0.364962,-0.342476,-0.369552,-0.368748,-0.218438,-0.330264,0.374737,-0.512633,-0.200829,0.459406,0.019931,-0.042304,0.536567,-0.485313,0.194457,0.656342,0.171132,-0.357347,0.673928,0.179763,0.044132,0.153855,-0.147461,-0.251732,0.370057,0.755470,0.264350,0.769115,0.132429,-0.613937,-0.643427,0.554552', '1316560', '1805685', '1303462', '1297347');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4146683', '樱桃', '剧情', '中日合拍影片《樱桃》入围了第20届东京电影节亚洲风单元，第38届印度国际金孔雀电影节，第11届上海国际电影节等各国影展。该片启用非专业演员出演本片的男主角，是一部纯粹的纪实性原生态影片。而一张女主角全裸的电影海报在媒体上惊现，引起了重重纷议。片中扮演女主角“樱桃”的是内地实力派演员苗圃。在整部影片中，苗圃一直以疯癫邋遢的形象示人。这种非正常状态的演绎对演员来说是颠覆性的挑战，更有许多非常态的状况需要面对。而本片中，需全裸出镜就是一项。在全裸海报中能够看到“樱桃”一丝不挂从水中站起来，扬起美丽的水花。这个场景被选为电影海报，也符合该片原生态的意境。它表现这位智障母亲“樱桃”的内心与她的身体一样，是最原始最纯真的状态，洁净，无杂质。本片在电影节上放映后，得到了众多影人的一致好评，片中至高无上的母爱感动了所有观众，放映现场一片抽泣声。苗圃在影片中表现的精湛演技和专业态度得到了各国影人的肯定。这是一部歌颂母爱的电影，讲述了大山深处一位智力有障碍的美丽女子渴望孩子、抚养孩子、保护孩子的感人故事。剧本根据真人真事改编，讲述了智障女樱桃曲折的人生故事。从小失去双亲被同村的好心人葛望的母亲收留的樱桃，与患有小儿麻痹的葛望结为夫妻。善良的樱桃偶然在路边捡回一个小孩，不顾家境贫困收养了她。葛望将养女红红偷偷送给别人，樱桃知道后伤心欲绝，挨家挨户寻找红红并最终将其找回。红红上学后，因为母亲的缘故常被同学嘲笑，因此对母亲产生了反感，开始孤立母亲。一次樱桃因冒雨给红红摘樱桃掉进了河中，红红终于体会到母亲对自己的爱。为了报答母亲，红红发奋读书，最终考上了大学，并在大学毕业后回到了家乡。《樱桃》是旅日导演张', '苗圃', '张加贝', 7.7, 5444, 'tt1619892', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1215987152.jpg', 0.8, 3.6, 28, 45.3, 22.2, '0.014384,0.102760,-0.523695,0.735070,0.086586,-0.160705,0.630442,0.129183,-0.380761,0.167497,0.233218,0.865820,-0.347893,0.368321,0.143720,-0.121194,-0.274463,-0.552042,-0.315787,-0.110791,-0.056948,-0.246495,-0.204069,0.143738,-0.170156,-0.381289,0.765709,-0.007689,-0.372575,0.432253,0.417858,0.031002,-0.057972,0.084634,-0.068976,0.155536,-0.136546,0.139097,-0.351307,0.260615,0.084228,-0.265973,-0.113976,0.100686,-0.085768,0.293267,0.714405,-0.268467,-0.186464,-0.174205,0.704410,-0.269566,-0.139705,0.182958,0.299017,0.010455,0.412427,-0.170213,-0.161445,0.347912,-0.041810,-0.305778,-0.622112,-0.164591,0.314307,0.331680,-0.519349,0.342767,0.016622,-0.093032,0.251731,-0.280665,0.240821,-0.003838,0.213467,0.479907,-0.129565,0.214722,-0.240610,0.512404,0.342107,0.026752,-0.197999,0.644218,-0.455923,-0.539457,0.109205,-0.356135,-0.388306,0.255429,0.291839,-0.018199,-0.207494,0.073453,-0.476037,-0.109151,-0.005599,-0.362719,0.028356,-0.330658,-0.154007,-0.598370,-0.207391,-0.411012,-0.021425,-0.221887,0.083361,-0.419153,0.994466,-0.707851,0.144341,0.409737,0.068846,-0.401726,0.583837,0.160818,0.026296,-0.116743,-0.093772,0.330089,-0.119388,0.055285,-0.144776,0.304228,-0.244017,-0.089295,-0.445536,0.469740', '27602116', '3811356', '25880986', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4146762', '旧日噩梦', '悬疑', '派特·贝克（托尼·德普 Tony Doupe 饰）是小镇的一位警长。然而他的儿子科特·贝克（亚伦·布莱克利 Aaron Blakely 饰）却有着极其黑暗的过去。十三年前，他因残酷地杀害了自己的亲生母亲而被关进了精神病院。然而噩梦就在科特逃离精神病院那刻开始了。精神错 乱的科特不仅大开杀戒，更展开了可怕的复仇杀戮。心急如焚的派特四处搜寻儿子科特，试图阻止他的疯狂行为。然而令他意想不到的是，正当派特发现线索来到丛林的时候，他居然发现了自己的女儿萨拉·贝克（阿莱娜·哈米特 Alena Dashiell 饰）正和朋友在这座森林里露营，众人旋即陷入命悬一线的险境之中。©豆瓣', 'Aaron Blakely', 'Norbert Caoili', 7.3, 16886, 'tt1125188', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1516849863.jpg', 1.8, 5.7, 34.4, 43, 15, '0.372999,0.029762,-0.895305,0.535909,0.023063,-0.530342,0.890956,0.146331,-0.691016,-0.312613,0.289580,0.653144,-0.134467,0.257228,0.294904,0.325091,-0.386991,-0.622598,-0.142295,-0.176369,-0.312898,-0.459608,-0.469210,-0.307812,0.106278,-0.327068,0.439711,0.224830,-0.045208,0.211089,0.120929,0.521113,0.032274,0.668340,0.039342,0.313150,0.274684,-0.132543,-0.153433,0.225000,0.088128,-0.320143,-0.413412,0.492514,-0.147081,0.620884,0.660947,-0.393499,-0.000395,-0.147841,0.335554,-0.358627,-0.064903,0.276258,0.236737,-0.329341,0.020098,-0.007317,-0.263503,0.077092,0.015150,-0.059819,-0.523343,0.159750,-0.045865,0.180870,-0.679317,0.113113,-0.194423,0.028999,0.248422,-0.397408,0.208622,0.098106,0.101201,0.266199,-0.192207,-0.306513,-0.599680,-0.263811,0.481499,-0.260884,-0.127537,0.271890,-0.208830,-0.301838,-0.026565,-0.125548,-0.462857,-0.276632,0.469290,-0.010587,-0.228822,0.357412,-0.513219,-0.119209,-0.533744,-0.188580,-0.355266,-0.245866,-0.374360,-0.448633,-0.015540,-0.172612,-0.302006,0.040745,-0.255630,-0.156089,0.186434,-0.652118,0.387941,0.697173,0.097346,-0.266581,0.510264,-0.101809,0.083519,-0.100363,-0.131157,0.580171,0.370139,0.369183,0.225690,0.142996,-0.033781,-0.183157,-0.461368,0.751663', '2002683', '1309172', '1309171', '3114200');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4151110', '山楂树之恋', '剧情', 'http://site.douban.com/106309/山楂树之恋豆瓣小站20世纪70年代初，响应毛主席号召，知识青年上山下乡。老师（成泰燊 饰）带着教育革命实践小组来到西坪村采风编教材。高中生静秋（周冬雨 饰）被安排在老村长（李雪健 饰）家，村长媳妇（萨日娜 饰）介绍情况时，提到了一个名叫老三（窦骁 饰）的小伙子。他是地质勘探队成员，平日作业，很少回家。静秋对老三很好奇，终于两人相见，以山楂树为话题，袒露心扉，互有好感。老三送她钢笔，陪她解忧，慢慢两人暗生情愫。但静秋返城时，听到老三有女友的传闻，态度骤冷。静秋的父亲被打成右派，母亲（奚美娟 饰）在劳动改造，她和弟弟妹妹课余帮母亲糊信封，生活很艰苦。为了能留校，静秋还要辛勤打工。被误会的老三，只得暗暗想方设法帮助静秋，直到两人重归于好。但他们的事被静秋的母亲撞见了。为了静秋的前途，老三在逼迫下许下了彼此不再见面的誓言……', '周冬雨', '张艺谋', 7.1, 320458, 'tt1554523', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p649179543.jpg', 1.5, 7, 41.2, 35.3, 14.9, '0.135158,-0.458171,-0.299051,0.306528,-0.006889,-0.359365,0.209968,0.338594,-0.699409,-0.268974,0.201923,0.492843,-0.064056,0.303208,0.022294,-0.234545,-0.327655,-0.463011,0.074319,0.050734,-0.004621,-0.368480,0.400728,0.137154,-0.065516,-0.138499,0.253377,-0.435556,0.026260,0.537175,0.158534,0.456871,-0.117307,0.195683,-0.177991,0.136522,0.168501,0.007639,-0.641464,-0.001957,0.113971,0.075089,-0.320528,-0.127171,0.102844,0.186998,0.703501,0.225572,-0.176996,-0.110355,0.072251,-0.016935,-0.070643,0.201768,0.377880,0.127801,0.396141,0.457300,-0.033282,-0.008969,0.055733,-0.212206,-0.079418,0.288642,0.303234,0.109370,-0.663488,0.268015,0.003511,0.016481,0.202428,-0.427402,0.215305,0.279138,0.133900,0.397183,-0.321176,0.062107,-0.289699,0.333505,0.436123,-0.211352,0.308056,0.384386,-0.142759,0.076877,0.454550,0.176042,-0.603832,0.173917,-0.013586,-0.239270,-0.182255,0.078485,-0.608261,-0.235018,-0.092153,0.167514,0.325498,-0.475093,-0.179020,-0.269941,-0.280292,-0.205666,-0.338821,0.062474,-0.082997,-0.216425,0.765311,-0.754606,0.099062,-0.019586,0.287823,-0.527136,0.494211,0.313436,-0.011973,-0.508645,0.090985,-0.146859,-0.284420,0.256576,0.268032,0.209014,-0.069079,-0.315454,-0.003533,-0.084950', '3445516', '25922902', '1292219', '1480318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4151284', '我和妻子的1778个故事', '剧情', '牧村朔太郎（草剪刚 饰）是一个痴迷科幻题材的小说家，他早年从工厂辞职，专心于科幻小说的写作。虽然科幻小说的风头渐渐被言情小说抢尽，他却甘于寂寞，始终为了理想笔耕不辍。朔太郎的妻子节子（竹内结子 饰）深爱着这个有些天然呆的丈夫，她白日里在银行努力工作，夜晚和假日则尽心操持着他们平凡的小家，照顾朔太郎的衣食起居。某天，节子突然病倒，经诊断却得知罹患了晚期肠癌，只有不到一年的寿命。得知这一消息，朔太郎决心每天为妻子写一个小故事，让节子保持快乐的心情。故事一篇篇写出，在喜乐悲欢之中，他们结伴走过了4年多的人生时光……本片根据作家眉村卓和他妻子悦子的真实故事改编。©豆瓣', '草彅刚', '星护', 7.4, 7083, 'tt1545979', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p977101504.jpg', 0.7, 4.1, 34.9, 43, 17.3, '-0.225046,-0.019262,-0.294680,0.392677,0.241440,-0.233960,0.554750,0.213728,-0.464792,-0.555780,-0.002615,0.494904,-0.088251,0.470376,0.198464,-0.174396,-0.370662,-0.458083,-0.154618,0.004071,0.103799,-0.350970,-0.027363,-0.152712,-0.393476,-0.173272,0.705514,0.005795,0.213812,0.435876,-0.024947,0.234477,-0.105341,0.089289,-0.173415,0.223466,-0.040519,0.057063,-0.253234,0.034504,0.143274,-0.231821,-0.318020,0.077728,0.055053,0.227332,0.898497,-0.208801,-0.447266,0.162913,0.616272,-0.080169,-0.275084,-0.090524,0.085300,0.102224,0.220130,0.380254,-0.280894,-0.078089,-0.100194,-0.160726,-0.620410,-0.169700,0.287248,0.368033,-0.183318,0.314885,-0.323936,-0.050287,0.086581,-0.338525,0.087688,0.285183,0.214879,0.551966,-0.501897,0.367175,-0.125281,0.723097,0.602767,0.033652,-0.207825,0.629383,-0.292454,-0.084057,-0.156620,-0.209899,-0.608878,-0.077767,-0.045294,-0.115633,-0.228812,0.253937,-0.303317,0.108951,-0.019534,-0.120384,0.249464,-0.247319,-0.307661,-0.255519,0.031367,-0.313558,-0.202099,0.049710,0.177097,-0.372033,0.955119,-0.585677,0.214192,0.483241,0.103931,-0.372631,0.752666,0.068373,0.004593,-0.115985,0.144389,0.434371,-0.081818,0.131768,-0.093369,0.334167,-0.100761,-0.030631,-0.682610,0.487335', '1908036', '3811356', '25738406', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4154632', '一万年以后', '动作', '环境恶化、资源枯竭、道德沦丧，人类文明在一场毁灭性的灾难后，湮灭殆尽，整个星球满目疮痍。历经万年，许多部落和新物种诞生并繁衍，西域孕育出一个全新的文明 。新人类将上一纪元称为“上古”，曾毁灭上古文明的巨大能量被封存在一个叫“众神遗迹”的禁地。一万年以后，乌族的部落首领“乌神”从众神遗迹窃取了上古魔法，为了满足自己的野心，居然想让地球重回邪恶的上古时代；小女孩珠玛在西域各部落勇士支持和帮助下跨过千难万险，前往古格找寻抗击乌神的办法，与此同时，西域最后的堡垒-伽罗城正与乌神的乌罗大军展开终极之战。', '珠玛', '易立', 5.4, 11838, 'tt4657400', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2234972965.jpg', 17.4, 24.9, 34.6, 14.3, 8.9, '-0.161174,0.730883,-0.746934,0.581872,0.245177,0.204979,0.480222,-0.396449,-0.492596,-0.115729,-0.030460,0.755784,0.217218,-0.013377,0.232106,-0.174615,-0.143585,-0.213712,-0.141482,-0.202999,-0.647517,0.038386,-0.611590,0.021867,-0.109087,-0.920682,0.929515,0.411605,-0.470311,0.025320,-0.405163,0.431805,-0.522445,0.168537,-0.402598,-0.119904,-0.215163,0.121878,-0.428797,0.141237,-0.804045,0.038199,-0.108914,0.410935,-0.420828,-0.084322,0.284756,-0.843692,0.172376,-0.768562,0.136088,-0.332331,-0.343769,-0.052832,0.607306,-0.051140,0.103380,0.475496,0.184790,-0.249742,0.074872,-0.181112,-1.153953,-0.333827,-0.029542,0.064339,-0.475175,0.377659,0.543361,-0.075908,-0.133285,-0.348507,0.203598,1.061039,0.483594,0.375193,-0.185458,-0.032929,-0.431191,0.039516,0.681331,-0.509351,-0.427489,-0.116698,0.074446,-0.768830,-0.259688,-0.434272,-0.417362,-0.213259,0.234692,0.042139,0.282028,0.692336,-1.383659,0.189131,-0.419234,-0.603812,0.477059,-0.038867,-0.198877,-0.348090,-0.327991,0.239232,-0.286204,0.130948,0.360727,0.023237,1.059213,-0.520953,0.522900,0.457804,0.637171,-0.465357,0.465917,-0.273529,0.071377,-0.368899,0.122028,0.723177,0.138503,0.768689,-0.198205,-0.022117,0.039709,0.247265,-0.354757,0.668546', '26290398', '25827286', '6982558', '35377026');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4154669', '痞子英雄之全面开战', '剧情', '被疑有“暴力倾向”的警察吴英雄（赵又廷 饰），第一次办案就上演搏命飞车追逐大戏，撞毁了几条街道，被勒令停止办案的他，仍在追踪一出离奇案件。而在海港城另一头，自称“三联会三级干部”的黑道上班族徐达夫（黄渤 饰），为了女人挪用帮派黑金走私钻石，交易时突遭神秘队伍乱枪扫射，混 乱之中来到现场的吴英雄，本以为只是一场黑市交易，但在逮住徐达夫之后，一场大灾难开始了……在特警部队+外国杀手+神秘美女（杨颖 饰）的连环夺命，直升机+重机枪+火箭弹的全城追杀下，一个正义感过头的警察，和一个喜感十足的黑帮，不得不组成另类“双雄”，除了逃亡，他们还得面对一场浩劫，因为那口装着钻石的箱子没那么简单，36个小时后，海港城就将毁灭，而真正的敌人，似乎永远都比他们快一步……©豆瓣', '黄渤', '蔡岳勋', 6.3, 87112, 'tt2414370', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1579241791.jpg', 3.2, 13.8, 52, 24.4, 6.5, '0.277326,-0.036785,-0.609315,0.468803,0.064969,0.044459,0.789749,-0.074613,-0.275728,-0.030153,0.486493,0.377849,-0.373732,-0.036372,0.378534,-0.333419,-0.136023,-0.577281,-0.284817,-0.161858,-0.486655,-0.331117,-0.318184,-0.490624,0.028559,-0.062188,0.445053,0.461921,-0.147155,0.265150,0.535988,0.083096,-0.207438,0.440044,-0.229511,-0.170582,0.210689,0.037221,-0.122516,0.189200,-0.165246,-0.376333,-0.012969,0.125002,-0.025829,0.258452,0.654910,-0.252216,0.034849,-0.098946,0.146192,-0.221968,-0.110616,-0.108901,0.737292,-0.157544,0.153023,-0.101128,-0.003814,0.009668,0.307672,0.049259,-0.491888,0.191727,-0.048944,-0.037583,-0.489783,0.244640,-0.001395,0.213669,0.001056,0.036767,0.283146,0.307104,0.488371,0.093621,-0.043192,0.096854,-0.658502,0.464069,0.698698,0.072863,-0.204391,0.002803,0.184998,-0.536055,-0.214221,-0.316251,-0.241222,-0.072721,0.606504,-0.525367,-0.024210,0.078896,-0.676794,0.112884,-0.082239,-0.012699,-0.265672,-0.203724,-0.261214,-0.725078,0.252468,-0.229078,-0.012355,0.529279,0.051508,0.166930,0.551978,-0.659920,-0.042010,0.560880,0.050699,-0.464719,0.407297,0.030558,0.011815,-0.191655,-0.152873,-0.087470,0.298922,0.551041,0.397342,0.468104,-0.252030,-0.342571,0.162834,0.351623', '10466639', '21619567', '1293515', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4156402', '背水一战', '喜剧', '位于亚利桑那州的平静小镇山默顿，曾在洛杉矶缉毒组供职的警长雷·欧文斯（阿诺·施瓦辛格 Arnold Schwarzenegger 饰）尽职尽责维护当地的治安。这一日，数名不速之客造访小镇，更有一名农夫遭人谋杀。与此同时，在另一边的拉斯维加斯，FBI探员约翰·班尼斯特（福里斯特·惠特克 Forest Whitaker 饰）正在押运臭名昭著的大毒枭加布里尔·科尔特兹（爱德华多·诺列加 Eduardo Noriega 饰）。谁知科尔特兹半路被人救出，其本人在劫持一名女探员后驾驶经过改装的跑车飞速逃离，趁夜朝着位于墨西哥边境的山默顿逼近。小镇的宁静生活被彻底打破，欧文斯警长即将经历充满枪火与杀戮的混乱一天……©豆瓣', '阿诺·施瓦辛格', '金知云', 6.9, 40960, 'tt1549920', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2154377141.jpg', 0.9, 6.5, 48.9, 34.6, 9.2, '0.285489,-0.148825,-0.679574,0.218572,0.358744,-0.034554,0.631825,0.340953,-0.445808,-0.401682,0.465792,0.787595,-0.141103,0.032165,0.759991,-0.027429,-0.371442,-0.419077,-0.077966,-0.243722,-0.310504,-0.337159,-0.196129,-0.172279,0.177114,-0.560457,0.348839,0.077268,0.095987,0.505311,0.176853,0.685364,-0.235185,0.295984,-0.199685,0.102406,0.664216,-0.370938,-0.251480,0.032408,-0.332940,-0.212870,-0.184310,-0.303023,0.147174,0.337030,0.612748,-0.179477,-0.000761,-0.177515,0.010493,-0.309320,0.134194,-0.248139,0.391357,-0.238792,-0.201502,0.352631,-0.223117,-0.088552,-0.019522,-0.375241,-0.108723,0.298720,-0.105696,0.147877,-0.478368,0.163828,-0.101717,0.063375,0.009182,0.028218,0.047603,0.384629,-0.170895,0.149857,0.323906,0.038040,-0.393229,0.012932,0.646352,0.027916,-0.173229,-0.054423,-0.010151,-0.309946,0.093924,-0.225280,-0.439946,-0.226940,0.492251,-0.392798,-0.087262,0.307314,-0.490327,0.026619,-0.615697,-0.131694,-0.057475,-0.011182,-0.443067,-1.033901,0.280123,0.024466,0.050437,0.269087,-0.149652,0.263710,0.238877,-0.749542,0.253063,0.394376,0.277248,-0.038846,0.357098,-0.333255,0.157584,-0.286311,-0.131553,0.438112,0.561390,0.560203,0.093537,0.282717,-0.444725,-0.319445,-0.247439,0.303836', '25833539', '3036464', '2075345', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4160441', '哆啦A梦：大雄的人鱼大海战', '剧情', '小夫的炫耀一如既往让大雄气愤不已，为了帮大雄实现潜水的心愿，哆啦A梦将整个城市变成了虚拟海洋，并利用道具引来了海洋中的生物。一个美人鱼来到了城市里，却阴差阳错被困了下来。她名叫苏菲亚，是人鱼一族的公主。据说，人鱼族在五千年前生活在另一颗星球，爱好和平的他们因受到另一族的侵略而来至地球避难，从此在这里扎根。大雄、静香他们很快和苏菲亚成为好朋友，并答应帮她寻找人鱼族传说的宝物“人鱼之剑”。正当小伙伴们在深海中尽情玩耍之时，危险不期而至。当初侵略了人鱼族家乡的外星恶魔也来到地球寻找人鱼之剑，小伙伴们即将展开新的冒险……本片为哆啦A梦剧场版开播30周年纪念作品。©豆瓣', '水田山葵', '楠叶宏三', 7.4, 8782, 'tt1613031', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2219319337.jpg', 0.8, 4.7, 39.9, 34.5, 20.1, '-0.041858,0.262508,-0.642763,0.517363,0.089283,-0.025421,0.644614,-0.119635,-0.348888,-0.107097,0.092077,0.853543,-0.013449,0.168392,0.217917,0.097391,-0.271170,-0.363861,-0.191569,-0.096050,-0.348564,0.126820,-0.178578,-0.076981,-0.208400,-0.283517,0.685889,0.096914,0.014007,0.376144,0.056491,0.392293,-0.514919,0.312017,-0.282280,-0.032761,-0.036294,0.055405,-0.377729,0.336749,-0.453081,0.118497,0.057837,0.361166,-0.021643,-0.099332,0.743665,-0.729508,0.013513,-0.431934,0.180475,-0.234724,-0.056674,-0.306945,0.364480,-0.236466,0.246065,-0.058721,0.034511,0.085420,0.146612,-0.297701,-0.701874,0.051744,0.027319,0.105403,-0.401359,0.224829,0.290260,-0.013670,0.248896,-0.248476,0.329521,0.302024,0.319246,0.225776,-0.210336,0.112026,-0.211036,0.232275,0.685015,-0.131442,-0.107852,0.192618,-0.109160,-0.518238,0.157623,-0.068727,-0.215917,-0.109035,0.339182,0.128988,-0.277189,0.625762,-0.990870,0.082690,-0.139901,-0.293122,0.297328,-0.499707,-0.274297,-0.463150,0.144021,0.118888,-0.028950,0.023994,0.136302,-0.264287,0.802069,-0.940077,0.330130,0.605753,0.320700,-0.492161,0.571726,-0.263743,0.130809,-0.075769,0.083760,0.454802,0.186155,0.543821,-0.084846,-0.069682,-0.065277,0.047026,-0.613616,0.486984', '26290398', '1457926', '25774050', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4160477', '夏娃的时间', '剧情', '未来世界，科技高度发达，极度仿真的高智能人形机器人深入到社会的方方面面，成为人类的得力助手。只是狂妄自大的人类似乎单单将机器人看作服务自己的奴隶，而忽略了他们悄悄滋长的万千情感。正就读高中的向坂陆夫（福山润 配音）如很多“钻头系”（过度依赖机器人的族群）一样，日常生活全部交由机器人萨美（田中理惠 配音）处理，并且绝对相信机器人三大法则的规定。可是近一段时间发现，萨美时常会去一些指令之外的地方。倍感困惑的陆夫约请好友真崎正树（野岛健儿 配音）根据萨美的数据记录来到了一家名为“夏娃的时间”的咖啡馆，他们惊奇地发现这里聚集了许多刻意消除掉标志性光环的机器人，此时的他们与人类无异，并且也有着各自的快乐和烦恼。与此同时，针对人型机器人“自我”状况愈加明显的情况，以伦理委员会为首的部分组织开始展开行动……©豆瓣', '福山润', '吉浦康裕', 8.4, 6397, 'tt1715210', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p640102354.jpg', 0.6, 1.7, 14.7, 42.9, 40.2, '0.403235,0.059201,-0.635412,0.578790,-0.194840,0.085697,0.479232,0.086286,-0.512724,-0.373795,0.089279,0.511851,0.023441,0.108118,0.127357,-0.425507,-0.290701,-0.411744,-0.232259,-0.213453,-0.422105,-0.448627,-0.171365,-0.576384,-0.076984,-0.584748,0.871793,-0.016517,-0.278719,0.330354,-0.139266,0.449207,-0.307540,0.309003,0.062268,-0.287642,0.055477,-0.330085,-0.216148,0.021714,-0.239512,0.156708,0.104475,0.190829,-0.215847,0.221742,0.909683,-0.359999,-0.342204,-0.261758,0.493482,-0.213159,0.042501,-0.116640,0.349630,0.205826,-0.057401,0.057481,-0.047945,0.221195,0.090090,-0.180151,-0.871775,-0.185175,0.125112,0.252662,-0.189931,0.261507,0.025772,-0.055992,0.072900,-0.340689,0.054601,0.173491,0.359570,0.521144,-0.251443,0.103617,-0.317791,0.079291,0.399705,0.124024,-0.568893,0.421330,-0.278390,-0.522973,-0.462940,-0.242422,-0.125221,-0.210876,0.027608,0.406020,-0.166245,0.504846,-0.858253,0.106132,-0.045404,-0.361550,0.129760,-0.514259,0.099602,-0.949599,-0.032138,-0.470683,-0.079086,0.046231,0.215344,-0.259942,0.860506,-0.863360,0.065992,0.466973,0.186924,-0.640112,0.478273,-0.268080,0.067784,-0.300900,-0.169981,0.155079,0.219663,0.372259,0.006115,0.241070,-0.124150,-0.077348,-0.429863,0.430696', '2369613', '26759820', '10174444', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4160524', '花神咖啡馆', '剧情', '电影由两个短片组成。故事发生在蒙特利尔，安东尼（Kevin Parent 饰）是一名DJ，在事业经营得风生水起的同时，他的感情生活却是一团乱麻。罗斯（伊夫林·布洛初 Evelyne Brochu 饰）是安东尼的新爱人，与此同时，安东尼和旧爱卡罗琳（Hélène Florent 饰）之间却依然藕断丝连。每日，安东尼觉得自己犹如走在一座独木桥之上，稍稍失足，等待他的就是无尽的深渊。镜头转向1969年的巴黎，杰奎琳（凡妮莎·帕拉迪丝 Vanessa Paradis 饰）和患有唐氏综合症的儿子相依为命，长久以来，杰奎琳牺牲了自己的一切，只希望儿子能够拥有一段短暂但快乐的人生。然而，对于杰奎琳的儿子来说，母亲所构筑的世界早已无法满足他的好奇心和求知欲了，他更加向往的，是外面真正的世界。©豆瓣', '凡妮莎·帕拉迪丝', '让-马克·瓦雷', 7.5, 7680, 'tt1550312', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1341266980.jpg', 1.1, 5.3, 32.2, 40.1, 21.2, '0.059276,0.105328,-0.681602,0.650901,-0.106570,-0.333666,0.941602,0.187645,-0.710033,-0.194368,0.234266,0.696247,-0.041477,0.486227,0.032798,0.130269,-0.160820,-0.814017,-0.136600,-0.181623,-0.154945,-0.477900,-0.355926,-0.236430,-0.297711,-0.429636,0.794986,0.150363,-0.046834,0.066968,0.318886,0.353479,0.035269,0.445243,-0.125808,-0.039482,-0.107286,0.038322,-0.494417,-0.031988,0.075249,-0.047470,-0.255689,0.266469,-0.156375,0.086267,0.634146,-0.278406,-0.115146,-0.104594,0.374111,-0.067988,0.034492,0.038208,0.079140,-0.024926,0.259032,0.125385,-0.232887,-0.141094,0.233536,-0.212675,-0.805702,-0.150378,0.051987,0.383122,-0.580910,0.484120,-0.141708,-0.136586,0.225433,-0.309058,0.061412,0.300491,0.385332,0.717618,-0.420335,0.113129,-0.395778,0.212528,0.743785,0.142735,-0.347122,0.606228,-0.575075,-0.151566,-0.480143,0.005425,-0.702816,-0.140275,0.359056,0.206406,-0.095470,0.585394,-0.601747,0.160313,-0.147199,-0.272618,0.059942,-0.694406,0.085680,-0.327841,-0.126401,-0.552838,-0.310044,0.022322,0.084481,-0.446504,0.780145,-0.815491,0.341513,0.357096,0.090472,-0.249876,0.723992,0.142993,0.198922,-0.219921,0.202411,0.665292,-0.261805,-0.011646,0.013373,0.403031,-0.013674,-0.036996,-0.608829,0.885688', '24756472', '1303077', '4058933', '1304641');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4160540', '机械姬', '科幻', '效力于某知名搜索引擎公司的程序员加利·史密斯（多姆纳尔·格利森 Domhnall Gleeson 饰）幸运地抽中老板纳森（奥斯卡•伊萨克 Oscar Isaac 饰）所开出的大奖，他将受邀前往位于深山的别墅中和老板共度假期。在与世隔绝的别墅中，纳森亲切地接待了这位员工。 事实上他邀请加利到来还有另一个目的，那就是协助他完成其所开发的智能机器人的测试。天才一般的纳森研制了具有独立思考能力的智能机器人伊娃（艾丽西亚·维坎德 Alicia Vikander 饰），为了确认她是否具有独立思考的能力，他希望加利能为伊娃进行著名的“图灵测试”。似乎从第一眼开始，加利便为这台有着宛如人类般姣好容颜的机器人所吸引。在随后的交流中，他所面对的似乎不是冷冰冰的机器，而更像是一个被无辜囚禁起来的可怜少女……©豆瓣', '艾丽西亚·维坎德', '亚历克斯·加兰', 7.6, 210561, 'tt0470752', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2208934451.jpg', 0.4, 2.5, 29.8, 50.9, 16.3, '0.276941,0.301630,-0.590589,0.625009,-0.377656,-0.320047,0.795562,0.091211,-0.289083,-0.210642,0.185339,0.706069,-0.016799,0.157273,0.208890,0.239999,-0.358317,-0.349914,-0.437840,-0.246994,-0.130865,-0.557358,-0.407449,-0.279629,0.205615,-0.574058,0.623015,-0.150300,-0.235747,0.247548,0.087670,0.489342,-0.075984,0.335294,-0.061004,-0.291008,0.287275,-0.149515,-0.259136,0.278296,-0.280521,0.120196,0.080168,0.180789,-0.082260,0.392076,0.478568,-0.498018,-0.069970,-0.270469,0.274793,-0.063582,0.180799,0.169624,0.028623,0.124805,0.091773,-0.002787,-0.207605,0.273193,0.268790,-0.243502,-0.986979,-0.226243,0.201266,0.219030,-0.287845,0.207525,-0.279214,-0.248865,0.200702,-0.146306,-0.045020,0.247062,0.228586,0.399028,0.037745,0.224923,-0.459354,0.123167,0.271251,0.032517,-0.509525,0.387423,-0.282074,-0.699746,0.082485,-0.170046,-0.353364,-0.181505,0.247682,-0.062143,0.145482,0.127403,-0.596351,0.016269,-0.328485,-0.168777,-0.206000,-0.287741,-0.225010,-0.902363,0.011476,-0.188751,-0.047254,-0.133885,0.163062,-0.476706,0.751818,-0.912411,0.228923,0.592159,0.254836,-0.077870,0.487693,-0.126292,0.044288,-0.257498,-0.200829,0.153624,0.254178,0.401046,-0.230155,0.408658,0.152572,-0.215011,-0.457175,0.603207', '1793491', '3769423', '1420088', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4164444', '127小时', '剧情', '英国导演丹尼·鲍耶（Danny Boyle）将为福克斯探照灯公司拍摄《127小时》（127 Hours），该片根据真人真事改编，讲述了美国登山青年阿伦·拉斯顿（Aron Ralston）断臂自救的故事。2003年5月美国登山爱好者阿伦·拉斯顿在犹他州一座峡谷攀岩时，因 右臂被石头压住被困5天5夜，为了逃生，他强忍剧痛，花了一个多小时的时间，先后将桡骨和尺骨折断，用自己的运动短裤当作临时止血带，然后用小刀从肘部将右前臂硬生生切断。从岩石下脱身后，为了与失血抢时间，他以超人的毅力爬过狭窄和风力强劲的峡谷，缘绳下到60英尺深的谷底，再步行5英里后与营救人员相遇，终于成功生还。©豆瓣', '詹姆斯·弗兰科', '丹尼·博伊尔', 8.1, 128445, 'tt1542344', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p839469694.jpg', 0.2, 1.1, 18.1, 53, 27.6, '-0.246833,-0.165637,-0.363503,0.301864,0.476375,-0.292188,0.622995,0.000862,-0.089296,0.198089,0.418158,0.446979,-0.368243,-0.057754,0.094828,-0.178167,-0.518682,-0.922877,-0.081784,-0.114582,-0.962976,-0.279667,-0.108907,-0.063526,0.130680,-0.261363,0.654521,-0.029516,0.013999,0.508290,-0.114548,0.082101,0.074815,0.378647,-0.330246,-0.007051,-0.209020,-0.247058,-0.139853,0.362085,0.092868,-0.279037,-0.171671,-0.100086,-0.201719,0.747043,0.869529,-0.022716,0.248010,-0.216340,0.082302,-0.121834,0.036581,-0.146992,0.274355,0.027338,0.260029,0.131936,-0.389357,-0.019535,0.271032,-0.257792,-0.241525,0.044033,-0.382766,-0.280308,-0.697966,0.125249,-0.392569,0.098878,0.089169,-0.536518,-0.122466,0.354864,0.183938,-0.002804,-0.538321,-0.029892,-0.123608,0.150192,0.467633,-0.153725,-0.346240,0.148339,0.181159,-0.475578,-0.136617,-0.228454,0.272598,-0.470777,0.569962,0.208719,-0.391341,0.064181,-0.577411,-0.031806,-0.343421,-0.272609,0.000494,-0.212998,-0.434280,-0.506989,0.029418,0.063926,0.156637,-0.050592,0.172212,-0.104552,0.352031,-0.188988,0.118232,0.609375,0.298125,0.255912,0.818594,-0.522028,0.214355,0.110749,0.178238,0.279981,-0.135103,0.717297,0.541894,0.617164,-0.294878,0.070465,-0.725287,0.347702', '2301242', '1316560', '1291564', '26845362');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4166487', '肩上蝶', '剧情', '电影《肩上蝶》，改编自傅玉蓬的网络文章《你的肩膀上有蝴蝶吗？》。故事发生在一个遭受致命传染病威胁的小岛。著名生物学家严国（陈坤 饰）专注于研究，希望找到治愈疾病的方法，但自己却被病魔所侵生命垂危。未婚妻宝宝（江一燕 饰）同神秘生灵定下契约：变成蝴蝶三年来交换严国的康复。严国恢复了健康却失去了爱人，变得忧郁孤僻。变成蝴蝶的宝宝只能够看着他一天天消沉但无能为力。严国得到了邻居白兰（桂纶镁 饰）和女记者杨霖（梁咏琪 饰）的关心。在严国和杨霖之间产生了爱意，这让宝宝满心痛苦。在宝宝可以变回人类期限前的最后一年，小岛也爆发了疫情，宝宝发现自己能够找到严国研究的解药的关键配方。危险的旅途让她的翅膀变得残破，但她依然没有放弃。伤痕累累的宝宝能够带给严国需要的药材配方飞回到他的身边吗？她会再次变成人类吗？严国最终会选择谁？©豆瓣', '陈坤', '张之亮', 4.9, 21714, 'tt1990256', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1070583269.jpg', 18.6, 34.7, 33.7, 9.5, 3.5, '-0.024128,0.070413,-0.393843,0.449644,-0.092335,-0.055990,0.727731,0.131893,-0.356854,-0.021726,0.116410,0.502424,-0.011393,0.278988,-0.068123,0.185201,0.001781,-0.524337,0.165366,0.005226,-0.270146,-0.310323,-0.374540,-0.252056,-0.000607,-0.502654,0.850673,0.088138,-0.014768,0.320513,0.038571,0.149172,0.100912,0.517440,-0.222086,0.042174,-0.282502,-0.042462,-0.128186,0.407362,0.433819,-0.025720,0.114321,0.324085,-0.001996,0.106035,0.871982,-0.178413,-0.337410,-0.246797,0.565809,-0.029057,0.061514,0.163042,0.059110,0.160003,0.148101,-0.093060,-0.233515,-0.070953,0.167202,0.078594,-0.584265,0.018346,0.000646,0.372214,-0.417791,0.466357,-0.063388,0.042226,0.104899,-0.401981,0.263375,0.401844,0.311967,0.397019,-0.354871,0.135737,-0.537459,0.075444,0.419453,-0.211489,-0.441552,0.485749,-0.403519,-0.635566,-0.126797,-0.258422,-0.247064,0.101266,0.342870,0.248008,-0.553852,0.147402,-0.473245,0.002736,-0.266373,-0.178628,-0.066136,-0.252608,-0.041414,-0.108109,-0.058326,-0.228204,-0.425135,0.000053,0.021743,-0.560838,0.867496,-0.790509,0.369965,0.394551,0.382953,-0.412816,0.423092,0.095544,-0.108320,-0.213971,0.016000,0.500648,-0.250003,0.334023,0.328882,0.069265,0.072775,0.162220,-0.518359,0.407412', '26759820', '10174444', '5416009', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4168733', '更好的生活', '剧情', 'Carlos Galindo（德米安·比齐尔 Demián Bichir 饰）是一个从墨西哥偷渡到美国的无户籍人士。老婆早已离他而去，如今的他和14岁的儿子Luis Galindo相依为命。儿子在学校因为自己的特殊身份遭受同学的歧视和欺负，但他总是沉默对待父亲的询问，隔阂在两人间越来越深。为了能让自己和儿子过上更好的日子，Carlos努力干活ping命令赚钱。他的一个园丁，平日里的工作就是为了各式各样的美国富人修剪草坪。他的老板因为想回国而出售自己的二手卡车和园丁必备工具。希望可以转更多钱的Carlos找自己的妹妹借了钱买来了人家淘汰的旧卡车和园丁必备的工具。可是有一天，Carlos赖以生存的旧卡车竟然被街区里的小混混Santiago（卡洛斯·琳娜蕾丝 Carlos Linares 饰）偷走。在焦急中父子两第一次坦诚相对，恢复以往的亲情。父子两共同踏上了寻车之路……', '德米安·比齐尔', '克里斯·韦兹', 8.1, 9948, 'tt1554091', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1244179894.jpg', 0.3, 0.8, 18.1, 53.8, 26.9, '0.406762,-0.149921,-0.528947,0.627048,-0.406173,-0.457870,0.777618,0.100052,-0.491338,-0.223006,0.038613,0.765140,0.228121,0.271498,0.008299,0.195731,-0.261827,-0.598074,0.034780,-0.273000,-0.342176,-0.454749,-0.370389,-0.258504,-0.176358,-0.137839,0.371555,0.002264,-0.017791,0.395936,0.225148,-0.063625,0.049065,0.348503,-0.447435,-0.091496,-0.086339,0.252202,-0.271054,0.064652,0.063877,-0.162288,-0.102756,0.102843,0.223421,0.606740,0.625518,0.042806,-0.101455,0.036489,0.200991,-0.104514,-0.033879,0.131527,0.257255,-0.086060,0.320262,0.109764,-0.312049,0.135159,0.133494,-0.001444,-0.682045,-0.072411,-0.005720,-0.135612,-0.893926,0.720279,-0.060966,-0.133123,0.164705,-0.416756,0.412425,0.401263,-0.003049,0.546770,-0.284057,-0.173572,-0.677971,0.381486,0.661806,-0.186912,0.031254,0.431802,-0.311775,-0.178225,0.137324,-0.444620,-0.556132,-0.328351,0.426119,-0.148951,-0.269567,0.082419,-0.846690,0.154365,-0.148667,-0.231024,0.050149,-0.513561,0.042787,-0.403712,0.071377,-0.680309,-0.252643,0.330212,0.287063,-0.508442,0.743792,-0.792098,0.172165,0.465129,0.473801,-0.743576,0.751271,0.081634,0.221291,-0.197760,-0.195077,-0.027957,0.092530,0.330063,0.068350,0.279283,-0.080934,-0.133559,-0.299747,0.411274', '1299965', '3055049', '3111650', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4173292', '歌舞青春', '歌舞', '源自迪士尼风靡全球的青春歌舞电影系列， 讲述一群来自不同背景、性格鲜明的年青人在校园发生的青春故事。一场即将举行的"超级校际演唱大赛"，唤起了同学们追求音乐梦想的愿望，不料在选拔过程中却掀起阵阵风波，最后各人在困难面前作出了突破自我的选择。', '张峻宁', '陈士争', 4.2, 4465, 'tt1556143', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p574874221.jpg', 42.3, 24, 19.8, 8.3, 5.5, '-0.069227,0.276888,-0.702443,0.725695,0.303151,0.156086,0.645166,0.096137,-0.340826,-0.298138,0.203859,0.523682,-0.540447,0.195900,0.491542,-0.648491,-0.134609,-0.890749,-0.029145,0.024462,0.169991,-0.093378,0.078799,0.123227,-0.032315,-0.621825,1.076476,0.137358,-0.677508,0.614233,0.646403,0.114654,-0.303141,0.219320,0.071002,-0.400809,0.503399,0.396603,-0.510913,0.206564,-0.287828,-0.341286,-0.396142,-0.023376,-0.264614,0.016067,0.969119,-0.205174,0.060015,0.215835,0.978733,-0.032670,-0.143263,0.005105,0.273258,0.327539,0.242211,0.168571,0.284287,-0.013111,-0.186523,-0.563490,-0.809225,-0.035106,0.432597,0.235958,-0.155534,0.485691,0.401498,0.030357,0.168968,0.042270,0.052974,0.247322,0.802755,0.506375,-0.040373,0.396537,-0.345962,0.586995,1.197949,0.060569,-0.535548,0.627043,-0.397300,-0.349583,-0.395082,-0.372579,-0.541789,0.188127,-0.055291,0.026522,-0.024308,0.389715,-0.743422,0.118689,0.194997,-0.560562,0.323437,-0.274984,-0.131309,-1.043229,-0.374871,-0.074065,-0.200733,-0.323982,0.138782,-0.446759,1.352032,-1.032858,0.046366,0.563861,-0.175263,-0.185812,0.723622,0.349312,0.292076,-0.161405,-0.085894,0.267263,-0.420147,0.025037,-0.528751,0.362550,-0.250986,-0.119523,-0.641981,0.816244', '27602116', '3811356', '5403927', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4173583', '唐伯虎点秋香2之四大才子', '喜剧', '富二代唐伯虎（黄晓明 饰）自幼习得一身出色武功，然而唐母（朱咪咪 饰）为了完成其父遗愿，禁止伯虎用武功在外生事，并用计约束其苦读以考取功名。其时唐伯虎与“畏妻才子”文征明（周立波 饰）、“无聊发明家”徐昌谷（任贤齐 饰）、“好赌才子”祝枝山（陈百祥 饰）三人交好，街坊称之“四大坏友”。祝枝山因贪图钱财，介绍唐伯虎入僧人无量（樊少皇 饰）主持的及第斋求学，令伯虎不期然与女子倩倩（张静初 饰）相遇，从此伯虎对倩倩魂牵梦绕，但倩倩身上，似乎隐藏着不能为外人道的秘密。与此同时，四大坏友在无尽的互相捉弄中偶然揭开了及第斋背后清风寺神秘的一角，这座寺院，并没有表面那么平和……©豆瓣', '黄晓明', '李力持', 4, 32013, 'tt1756773', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p521230578.jpg', 36.9, 35.3, 22, 3.9, 1.9, '0.172666,0.019862,-0.350777,0.494665,0.014647,-0.068413,0.468221,0.330445,-0.568074,-0.577646,0.012542,0.564862,-0.062310,0.219559,-0.014218,-0.093459,0.118439,-0.539615,0.055834,-0.381683,0.252375,-0.121506,0.013640,0.081987,-0.496370,-0.120285,0.340090,0.161905,-0.165252,0.632910,0.456724,0.165130,-0.574897,0.060422,-0.141874,-0.230646,-0.151844,0.279831,-0.231767,-0.111259,-0.357724,-0.493185,-0.171237,-0.310603,-0.060456,0.092511,0.542922,-0.198449,-0.014668,-0.158712,0.215108,0.298803,0.080202,0.062204,0.146142,0.026958,0.452790,0.388031,0.004892,0.068012,-0.005516,-0.149190,-0.302704,-0.107249,0.732080,-0.021416,-0.154269,0.391045,0.094270,-0.224717,-0.403628,-0.157558,-0.022853,-0.091797,0.265867,-0.048483,0.103700,0.020496,-0.284749,0.648126,0.085658,-0.059039,0.207030,-0.013178,0.082556,-0.121449,0.387004,-0.423271,-0.271079,0.056692,0.370851,0.092006,0.451776,0.087127,-0.294921,-0.209094,-0.062347,0.559436,0.028356,-0.045067,0.094229,-0.472500,-0.122097,-0.354464,-0.272722,-0.083373,0.266074,-0.467708,0.505007,-0.821403,0.056047,0.102988,0.049505,-0.429124,0.672866,-0.105465,0.432069,-0.072775,-0.361347,0.254565,0.132184,0.025051,-0.301609,0.322619,-0.125797,-0.233320,-0.091067,0.086779', '3445516', '22964524', '1306544', '1302425');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4176542', '杀生', '剧情', '中国西南、与世隔绝、群山环抱中有个寨子，是个人皆长寿、规矩自成之地，清时皇帝赐名“长寿镇”。某日突爆传染病，地方官派医生（任达华 饰）前往诊治，他在镇子外发现奄奄一息的牛结实（黄渤 饰）。进寨后，往日温厚的村民一反常态，不仅对牛结实拒施援手、避若瘟疫，更迁怒于医生多 管闲事，老镇长（马精武 饰）亲自带着长寿镇医生（苏有朋 饰）和接生婆（梁静 饰）、油漆匠，老族长等人千万百计的阻挠医生对牛结实的救援，牛结实最终没能被救活，医生也找不到此人暴毙的原因。镇民们对医生的不欢迎不合作态度，令医生很沮丧，正当他准备离开的时候，无意中发现了一个被全镇民众一起隐藏在山崖上的一个秘密，带着重重疑惑医生决定暗中走访长寿镇，直到他偶遇一个男孩，长寿镇迷案的真相才一步步揭开……该片改编自陈铁军的中篇小说《儿戏杀人》。©豆瓣', '黄渤', '管虎', 7.8, 223900, 'tt2290645', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1513799776.jpg', 0.7, 2.8, 23.2, 50.1, 23.2, '-0.046681,-0.145908,-0.420308,0.226586,0.010641,-0.033992,0.594683,0.102958,-0.552561,-0.226646,0.163605,0.336375,0.006201,0.117638,-0.056721,0.074987,-0.189297,-0.098946,-0.222614,0.069805,-0.393107,-0.192246,-0.203752,-0.196837,-0.201160,-0.126742,0.095021,0.015385,-0.065273,0.562660,0.115645,0.135312,-0.038295,0.297772,-0.244832,0.060361,0.229824,-0.120977,-0.223494,0.099662,0.154170,-0.176808,-0.257818,0.115120,-0.028264,0.433767,0.388548,-0.139828,-0.290025,0.054645,0.089693,-0.217440,0.097788,0.216793,0.385354,-0.005517,0.241435,0.259987,-0.187279,-0.093888,-0.077920,0.027303,-0.287357,0.128233,0.427595,0.312682,-0.588437,0.253896,0.034446,-0.077561,-0.103100,-0.489631,0.283073,0.166865,-0.067819,0.263252,0.089243,0.044615,-0.459526,0.226127,0.518572,-0.029111,0.066398,-0.094363,-0.108696,-0.486015,0.351469,-0.119194,-0.436090,0.158486,0.277355,-0.305260,-0.090447,-0.118181,-0.137189,-0.173422,-0.342585,0.059926,-0.135908,0.031561,-0.077659,-0.241978,0.261837,-0.130921,-0.050346,0.115449,0.181875,0.035225,0.561777,-0.367689,0.225516,0.362505,0.348589,-0.458836,0.611745,0.026453,0.055337,-0.309704,-0.127560,-0.044504,0.238568,0.604029,0.352749,0.337632,-0.138289,-0.419672,-0.316883,0.045521', '4004731', '1303444', '1307873', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4179012', '东方快车谋杀案', '剧情', '本片改编自阿加莎·克里斯蒂的同名小说。Poirot（大卫·苏切特 David Suchet 饰）到访伊斯坦布尔之际，替英国军方解决了一起复杂的案件。在返回伦敦的途中，他遇到了老友国际客车公司的董事Bouc先生，他为Poirot在最后一刻订到了东方快车的车票。在列车上，Poirot遇到美国富商Samuel，他告诉Poirot自己的生命受到威胁，愿意支付重金让他保护自己，但却遭到了Poirot的拒绝。第二天清晨醒来之际，Poirot发现列车受困于暴风雪中而Samuel已被人谋杀在包厢里。在Bouc先生和Constantine医生的协助下，开始对凶案展开调查，他是否能顺利解开这桩扑朔迷离的惊天大案呢？©豆瓣', '大卫·苏切', '菲利普·马丁', 8.2, 47338, 'tt1554113', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2172410560.jpg', 0.2, 1.1, 17.2, 52.3, 29.3, '0.440639,0.300371,-0.879621,0.403510,0.188456,-0.127832,0.483237,0.136024,-0.513850,-0.157439,0.232321,0.812835,-0.273319,0.154328,0.440391,0.069099,-0.348634,-0.688790,0.145437,-0.086614,-0.465578,-0.644064,-0.144691,-0.202565,0.012316,-0.212813,0.408841,0.570732,-0.007835,0.551540,0.180123,0.372583,-0.134880,0.697688,-0.055962,-0.007384,0.242705,0.091450,-0.308813,0.618432,0.334662,-0.440607,-0.069288,0.236079,0.094814,0.434466,0.511549,-0.057124,-0.246487,0.124404,0.425265,-0.452183,0.204521,-0.009563,0.265405,0.185950,0.022123,0.363815,-0.432166,-0.114096,0.032596,0.081926,-0.471565,0.080669,0.022432,0.114043,-0.606491,0.168131,-0.398119,0.241563,0.007935,-0.431264,0.389002,0.527625,0.242123,0.217187,-0.040300,0.055086,-0.658722,0.149434,0.719697,-0.087505,-0.113344,0.215375,-0.010877,-0.306458,0.113931,-0.019368,-0.354225,0.103377,0.309406,0.020008,-0.285685,0.071443,-0.451887,-0.181741,-0.412577,-0.199996,-0.132982,-0.335820,-0.128951,-0.817771,-0.080937,-0.035593,0.005299,0.120545,0.204480,-0.290891,0.351324,-0.764391,0.212207,0.644238,0.464289,-0.303743,0.798032,0.005507,0.178128,0.094916,0.015319,-0.139034,0.256755,0.478709,0.169820,0.061678,0.047201,-0.128360,-0.344786,0.051770', '25908042', '3285622', '1302987', '2079017');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4181031', '欢乐树的朋友们', '喜剧', '欢乐树的朋友们是美国一部暴力血腥的动画片，主要讲述了可爱的小动物们快乐地在森林里以各种各样的方式死去。', '沃伦·格拉夫', 'Rhode Montijo', 9.1, 7287, 'tt1391548', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2690517448.jpg', 1, 0.7, 7.5, 25.1, 65.8, '0.645468,-0.048259,-0.600155,0.805095,0.067234,0.310882,0.960565,-0.024911,-0.259191,0.175547,0.152865,0.609922,0.233111,0.797325,-0.220013,0.056872,-0.368298,-0.421087,-0.692248,0.275586,-0.360878,0.114121,-0.572139,-0.717031,-0.132637,-0.185676,0.555598,0.131486,-0.139354,0.594410,0.426304,0.243539,-0.112330,-0.340782,-0.325923,-0.199009,0.181312,0.048988,-0.315168,-0.194989,-0.420870,-0.021215,-0.325867,-0.029516,0.138876,0.082256,1.426447,-0.592303,-0.091171,-0.217295,0.513493,-0.178352,0.103658,0.387861,0.189566,0.042103,0.794180,-0.167562,-0.030412,0.321728,-0.140675,-0.084335,-1.356110,-0.020474,-0.195221,0.106101,-0.210996,0.309768,0.669969,-0.098197,0.715739,-0.652466,0.082457,-0.242377,0.187588,0.722225,-0.015701,0.200204,0.144563,0.418386,0.865123,-0.150556,-0.418296,0.578718,-0.786209,-0.343351,-0.106688,-0.488497,-0.676846,-0.156172,0.605258,-0.507193,-0.529279,0.517031,-1.512114,0.421880,0.075952,-0.623455,-0.107871,-0.093925,-0.612403,-1.039806,0.181568,-0.699891,-0.212902,-0.254819,0.153553,-0.124967,1.851433,-0.589117,0.197037,0.788450,-0.276432,-0.695574,0.597672,0.308612,-0.114890,0.189154,-0.190447,0.421011,-0.164275,0.064257,0.287119,0.441120,-0.029797,0.023645,-0.992576,0.624916', '24284209', '1302661', '5403927', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4181108', '乡谣情缘', '剧情', '凯莉（格温妮斯·帕特洛 Gwyneth Paltrow 饰）是著名的乡村音乐歌后，数月前因一次登台意外导致了流产，而意外正是凯莉本人酗酒过度之后出现精神恍惚所致，因此她被送去了勒戒所，演唱事业也一度停滞。期间她认识了一个才华横溢的乡村音乐作曲家比奥（加内特·赫德兰 Garrett Hedlund 饰），温柔英俊的比奥给了她莫大的安慰。为了重振演艺事业，凯莉的丈夫兼经纪人詹姆斯（蒂姆·麦格罗 Tim McGraw 饰）开始安排她的复出巡回演唱会，在选择暖场歌手的时候，凯莉推荐了唱作俱佳的比奥，詹姆斯则选中了年轻漂亮的前选美小姐查尔丝（莉顿·梅斯特 Leighton Meester 饰）。然而，在无数媒体和歌迷的强烈关注下，尚未彻底恢复状态的凯莉，在巡回演出中状况连连。每日都要面对镜头的围追堵截，凯莉是否能顶住压力，把握住最后一次的复出机会？她和丈夫的关系是否开始发生改变？在这次巡演中，四个人又该如何面对自我，如何面对彼此之间的关系……', '格温妮斯·帕特洛', '莎娜·费斯特', 7, 5730, 'tt1555064', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p668201335.jpg', 0.7, 6.7, 46.2, 35.9, 10.6, '-0.089351,0.072207,-0.642414,0.546314,0.105777,-0.330824,0.568658,0.248190,-0.442316,-0.343239,0.117707,0.568433,-0.466907,0.147947,0.345020,-0.263290,-0.227281,-0.694321,0.096534,0.046753,-0.352328,-0.293626,-0.227285,-0.088010,-0.081153,-0.492108,0.412409,-0.158241,-0.235487,0.600478,0.489879,0.361719,0.268739,0.439211,0.204211,0.033243,0.331018,-0.067007,-0.302068,0.352403,0.374865,-0.376348,-0.157139,0.335066,0.022941,0.490143,0.653006,-0.171102,0.037079,0.034147,0.473132,-0.064057,0.202886,0.163720,0.192312,-0.065253,0.235760,0.171859,-0.387333,0.128079,-0.062451,-0.097329,-0.702816,0.134225,0.229229,0.193838,-0.634810,0.556655,-0.113182,-0.016920,-0.036670,-0.289669,0.057023,0.493001,0.322558,0.325147,-0.005163,0.064610,-0.189688,0.073367,0.780404,0.148094,-0.322844,0.542419,-0.154348,-0.355689,-0.106347,-0.272298,-0.542729,0.218343,0.203128,0.062552,0.147980,0.318772,-0.140969,-0.254252,-0.515807,-0.135302,-0.121328,-0.347247,-0.021741,-0.637716,-0.038893,-0.202282,-0.124662,-0.086144,-0.081685,-0.302038,0.547508,-0.881178,0.404252,0.561595,0.190846,-0.369352,0.441558,0.249465,0.283634,-0.182983,-0.202990,0.158276,-0.025906,0.017692,0.081183,0.178714,0.013926,-0.261134,