INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4185834', '丧尸乐园2', '喜剧', '《僵尸之地》是鲁本·弗雷斯彻的导演处女作，上映后好评如潮——获得了烂番茄89%的惊人好评率，此片一举奠定了鲁本在好莱坞商业领域的地位。首映周末以2500万美元登顶冠军的《僵尸之地》，是受到几年前《僵尸肖恩》的启发进行创作的，影片讲述了一种致命病毒席卷了美国，只要被病毒感染，就会变成僵尸。最终，只有几个幸存者没有被感染病毒，决定逃离，获得生存的机会。两个性格迥异的男人凑到了一起，前者对待僵尸的进攻别有心得（制定了一大堆“规则”），后者则是个暴力崇尚者，企图杀光所有的僵尸。在他们逃亡的途中，邂逅了两个精明的女幸存者，他们四人决定一起分享对付僵尸的经验，获得逃生的机会。然而，在杀戮过程中，他们遭遇的危险超出了所有人的想象。按照好莱坞卖座片的类型规律，像《僵尸之地》这种投资仅2000多万美元，没有一线大牌主演的僵尸片，基本都是烂片集中营的当家老大，但此片的成功却来的非常迅猛。这全归功于导演的创意，影片结尾高潮处在游乐园大战僵尸一段，观赏性极强。《僵尸之地》的主演杰西·艾森伯格、伍迪·哈里森、艾玛·斯通、阿比盖尔·布莱斯林，目前已确定愿意回归剧组参加续集的拍摄，但剧本仍然在创作之中，预计10年上半年开机。电影《僵尸之地》(Zombieland）导演鲁本.费雷斯彻（Ruben Fleischer）近日在接受采访时透露《僵尸之地》续集有望2010年年底正式开拍。“我们正在与制片方接触，我们有一些点子它们也非常喜欢。我们肯定会以3D的形式拍摄这部续集。索尼现在已经有自己的3D部门了，我们将在周二（3月2日）参观索尼的3D部门。我知道所有原班人马都很激动回归续集，这将是1部拍摄过程十分精彩有趣的', '伍迪·哈里森', '鲁本·弗雷斯彻', 6.9, 47872, 'tt1560220', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2564153041.jpg', 1.4, 7.8, 47.2, 33.7, 9.9, '0.059650,-0.119291,-0.542070,0.435275,0.181150,0.117322,0.466129,-0.075851,-0.302725,-0.168503,0.188648,0.665401,-0.390842,-0.145797,0.147704,-0.395708,-0.154334,-0.410728,-0.237764,-0.059332,-0.113206,-0.174957,-0.448366,-0.133873,-0.145702,-0.384378,0.887649,0.229200,-0.327194,0.196444,0.147895,-0.006620,0.015436,0.248081,0.037150,-0.009195,0.159878,-0.265812,-0.386658,0.540609,0.071362,-0.051508,-0.106882,0.111963,0.060556,0.295215,0.672039,-0.165470,-0.208295,0.100522,0.567133,-0.312395,-0.140155,-0.020246,0.417077,-0.052296,0.401795,0.256067,0.037225,0.030951,-0.197255,-0.293818,-0.978724,-0.001772,0.175888,0.204828,-0.365802,0.358898,0.101084,0.128035,-0.053271,-0.280185,0.138615,0.321388,0.448410,0.158296,0.160329,-0.119189,-0.420461,0.359707,0.633140,-0.107100,-0.451046,0.356032,-0.113415,-0.637889,-0.261234,-0.364228,-0.297404,0.259081,0.373934,0.104776,-0.336139,0.236756,-0.601958,0.090933,-0.115606,-0.338868,-0.142814,-0.258517,0.028046,-0.976961,-0.147151,-0.171622,-0.021089,-0.183846,0.255912,-0.436775,0.807831,-0.736075,0.061053,0.546993,0.315567,-0.459650,0.684829,-0.156545,0.022326,-0.187985,0.087981,0.055635,0.006768,0.127298,0.201362,0.380978,0.094386,-0.444799,-0.277977,0.632687', '2369613', '3318306', '26275494', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4189695', '撕票风云', '动作', '连串黑帮老大遭绑架、勒索以及撕票，警方对此案调查毫无头绪。警队B组队长张博文（任达华 饰）曾为警队立下汗马功勋，但从其妻子遭黑帮报复被杀后，加上A组队长的排挤，他开始消极处世。警方接到报案，又一黑帮头目遭绑架，新任总警司古国强（陈法拉 饰）召集两组人马对此案展开全面侦察。由于A组队长轻敌，加之犯罪分子做案手法高明，配合严密，在一次行动中警方遭受重创。此时，在古警司的请求下，张博文带领手下仅有的两名探员开始暗中调查此案。经过慎密调查之后，张博文把犯罪分子的头目目标锁定为曾为警方督察的何湛森（苗侨伟 饰），他的手下包括多名原飞虎队成员，而何湛森绑架黑帮老大的真实目的是为其被黑帮报复杀害的弟弟的报仇……©豆瓣', '苗侨伟', '姜国民', 5.9, 8914, 'tt1572168', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p783254678.jpg', 2.9, 18.9, 59.5, 15.3, 3.4, '0.194410,-0.275533,-0.409124,0.599044,-0.090705,-0.024385,0.350881,-0.046998,-0.841730,-0.293759,0.485964,0.297359,0.192060,0.022217,0.240258,-0.384893,-0.243822,-0.850867,-0.306712,-0.084924,-0.214089,-0.772411,-0.128127,-0.088457,0.262385,-0.161480,0.365779,0.045041,-0.494907,0.481774,0.346489,0.518028,-0.305705,0.215612,0.263828,-0.145469,0.529424,-0.445045,-0.420066,-0.008979,0.132692,-0.494273,-0.186143,0.004434,0.113944,0.716577,0.579745,-0.053376,-0.391102,-0.338114,0.225030,-0.477227,0.030279,-0.033845,0.944140,0.410449,0.116487,0.556380,-0.244008,0.027686,-0.216301,0.121407,-0.975722,-0.016711,0.531562,-0.077526,-0.479555,-0.108487,-0.505553,0.437068,0.199396,-0.102573,-0.045933,0.606082,0.260068,-0.016194,0.283338,0.299650,-0.256087,0.149340,0.745677,-0.191809,0.031441,-0.691615,0.368617,-0.438005,0.062534,-0.250956,0.027930,0.048058,0.399632,-0.412030,0.185133,0.039485,-0.391922,-0.279172,-0.572940,-0.098022,-0.150994,-0.090629,-0.042342,-0.608487,-0.160146,0.074107,-0.103766,0.301068,0.189905,-0.032754,0.435146,-0.766738,0.085842,0.401718,0.083296,-0.889999,0.130242,0.304716,-0.045442,-0.298098,-0.181916,-0.294367,0.811988,0.512058,0.291375,-0.052144,-0.116832,-0.686972,0.106060,-0.481872', '26352445', '3811342', '3136507', '1307106');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4190211', '致命伴旅', '剧情', '美国游客Frank独身远赴欧洲一心治疗情伤，却在火车上邂逅了背景神秘的性感女子Elise，正当Frank陶醉在二人世界之际，危机却渐渐迫近，自巴黎开始被追踪监视，来到威尼斯更惹来各方人马追杀……随着Elise的真正身份揭开，Frank 才惊觉自己卷入了一场精心布局的危险游戏！©豆瓣', '约翰尼·德普', '弗洛里安·亨克尔·冯·多纳斯马尔克', 6.6, 153464, 'tt1243957', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p787822263.jpg', 1.6, 11.1, 49.6, 29.1, 8.6, '0.007715,0.347626,-0.893358,0.257959,0.058228,0.068347,0.397791,0.205001,-0.449575,-0.136085,0.466924,0.516877,-0.276039,0.009596,0.514651,-0.000087,-0.173488,-0.716467,0.039939,-0.245314,-0.256039,0.037191,-0.505308,-0.092527,0.146849,-0.478932,0.511447,0.556780,-0.427987,0.550889,0.051770,0.160824,-0.884953,0.867400,-0.201629,-0.327698,0.310741,0.167341,-0.226523,-0.020587,-0.264107,-0.857501,-0.292226,0.088536,-0.359180,0.257934,0.747140,-0.077695,-0.274943,0.002314,0.397738,-0.403766,-0.076348,-0.120617,0.597353,-0.228685,-0.038173,-0.007576,-0.164438,0.230822,-0.391177,0.035143,-0.249799,0.400985,0.096739,0.079994,-0.285698,0.144329,-0.136484,-0.122679,0.034641,-0.281981,0.099465,0.551954,0.195412,0.092440,0.095091,0.169718,-0.298627,0.151457,0.891706,0.030168,0.190640,0.237074,0.079674,-0.087917,0.070149,-0.189317,-0.125725,-0.205518,0.556488,0.105311,-0.010587,0.323640,-0.536907,0.177148,-0.464931,-0.217816,0.114590,-0.385890,-0.079278,-0.889988,-0.301969,-0.018920,0.026329,0.251529,-0.004030,-0.153477,0.486192,-0.438811,0.243395,1.137819,0.116623,-0.608046,0.390315,-0.134396,0.022318,-0.206236,-0.245718,0.550691,-0.066484,0.330892,-0.210940,0.227482,-0.401853,0.068988,-0.357532,0.379642', '1306723', '3147969', '3871833', '1292846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4191644', '一天', '剧情', '1988年7月15日，一所大学为毕业生的狂热所充盈。籍着这股躁动，轻浮的德克斯特（吉姆·斯特吉斯 Jim Sturgess 饰）穿过层层人墙，寻找可以与之共度这最后狂欢与浪漫之夜的尤物。他将目光锁定在艾玛（安妮·海瑟薇 Anne Hathaway 饰）的身上，一个来自普 通工薪家庭的聪慧女孩。然而短短的交流过后，他们之间什么也没发生，却又注定改变了彼此的一生。在之后的岁月里，两人以友人知己的身份时聚时散，彼此分享着人生的苦辣酸甜和各种感悟。德克斯特经历着事业和婚姻的起落，艾玛品味着底层人生的辛酸。他们是远在天边心也紧紧相连的知己，是深锁心中最为笃真却相隔最远的爱恋……本片根据英国作家大卫·尼克尔斯（David Nicholls）的同名畅销小说改编。©豆瓣', '安妮·海瑟薇', '罗勒·莎菲', 7.9, 461456, 'tt1563738', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1103205323.jpg', 0.4, 2.5, 24.4, 45.2, 27.5, '0.365811,-0.249806,-0.752354,0.833315,0.272195,-0.479070,0.871997,0.084964,-0.443031,-0.142900,-0.020592,0.572128,-0.501374,0.215961,0.364913,-0.109631,-0.251652,-0.971349,-0.292537,-0.307949,-0.119951,-0.475842,-0.347893,0.182722,-0.248312,-0.183063,0.775622,0.185340,0.056498,0.432193,0.180582,0.257502,-0.174595,0.309888,-0.148883,0.064689,0.023643,0.142346,-0.442909,-0.020279,0.138688,0.015918,-0.229123,-0.033019,-0.243314,0.223132,0.776641,-0.388259,0.124664,0.066050,0.354627,-0.049997,0.073968,0.030655,-0.139542,0.190631,0.195803,0.319356,-0.281203,-0.155069,0.078178,0.027004,-0.603227,-0.021651,0.030768,0.210289,-0.402227,0.569364,0.082590,-0.227416,0.076613,-0.164494,0.037863,0.330024,0.254146,0.568537,-0.186200,0.020541,-0.334278,0.213309,0.886005,0.231303,-0.486961,0.321375,-0.569242,-0.459746,-0.131732,-0.066682,-0.679481,-0.202462,0.246898,0.484766,0.056880,0.643424,-0.675151,0.267901,-0.120051,0.060401,0.266424,-0.706455,-0.097651,-0.677336,-0.453708,-0.555212,-0.526604,0.005315,0.274192,-0.300226,0.809766,-0.916250,0.035376,0.658166,0.241600,0.079241,0.901389,0.082552,0.162743,-0.106553,-0.100940,0.552800,-0.140640,0.245074,0.104146,0.510139,-0.017375,0.352699,-0.498365,0.618883', '3230462', '30162520', '25777330', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4193254', '义兄弟', '剧情', '面貌清秀的宋志元（姜东元 饰）是来自朝鲜的谍报人员，在代号441的老间谍影子的带领下，他们闯入首尔一幢公寓，刺杀了本国叛逃人员及其一家。期间，他们遭遇韩国安全部门的追捕，一番激烈枪战过后宋志元等侥幸逃脱，但他被上级认为有叛变之心而从此弃用。另一方面，行动的失败导致韩国一方的行动队长李仁奎（宋康昊 饰）遭到革职处分，他只得开设侦探所，靠收钱追踪逃跑的越南新娘养家糊口。不久，金正日和金大中实现历史性的会见，朝韩双方局势缓和。六年后，李仁奎在某个越南人工厂偶遇宋志元，他希望抓住志元及神秘的影子赚大钱，而志元也想利用仁奎洗脱自己叛变的罪名。两人别有用心住在了同一屋檐下，随着了解的加深，他们的想法渐渐发生改变……©豆瓣', '宋康昊', '张勋', 7.1, 13369, 'tt1535491', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p472769826.jpg', 0.5, 4.5, 43.1, 41.1, 10.8, '0.266031,0.054698,-0.728069,0.399901,-0.117548,0.117268,0.498274,0.144199,-0.347268,-0.286353,0.397865,0.674854,-0.084648,-0.010427,0.271231,-0.269904,-0.236150,-0.688179,0.031872,-0.023781,-0.145129,-0.447443,-0.364614,-0.324356,-0.049910,-0.134522,0.678364,0.374949,-0.401866,0.417662,0.426926,0.279034,-0.222962,0.276881,0.017714,-0.066916,0.137268,-0.210616,-0.381994,0.275376,-0.092963,-0.499966,-0.019999,-0.024560,-0.058435,0.573896,0.576653,-0.091600,-0.383345,-0.085363,0.286910,-0.541324,-0.245378,0.150599,0.555856,0.146140,-0.204272,0.430790,-0.260616,-0.113154,-0.081923,0.178667,-0.562601,0.063131,0.210667,0.075956,-0.473355,0.314562,-0.008987,0.044125,-0.002082,-0.280267,0.201135,0.834117,0.273463,0.022194,-0.108904,0.106617,-0.578821,0.024700,0.781845,-0.165631,-0.219378,-0.135863,-0.021835,-0.303553,0.132814,-0.230129,-0.029257,-0.119397,0.312274,-0.056087,-0.130081,0.020843,-0.352244,-0.132337,-0.346788,-0.141261,0.018017,-0.394392,0.111855,-0.827642,-0.241064,-0.211799,-0.269480,0.164856,-0.051141,-0.227635,0.314499,-0.773003,0.154293,0.550596,0.423179,-0.789920,0.403311,0.170803,0.154165,-0.149287,-0.048403,0.092881,0.272814,0.223065,-0.036026,-0.005210,-0.232492,-0.232128,-0.193954,-0.042030', '1296947', '5157137', '25978126', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4195568', '蓝盐', '剧情', '黑帮老大金万吉突遭意外，命在旦夕。危难之际，金要求将名叫尹斗宪的男子带来。斗宪（宋康昊 饰）曾是组织内的得力干将，但他多年前早已引退，隐居在某海滨小镇学习料理。不过这个背负着黑暗过去的男子终要回到原来的世界，随着金万吉去世消息的传来，斗宪的内心波涛骤起，而围绕老大继承人的话题也在组织内争论不休。另一方面，与斗宪一同学习料理的美丽少女赵世彬（申世京 饰）实则是某组织派来监视斗宪并伺机实行暗杀的杀手。可是在相处的过程中，世彬冰冷封锁的心门渐渐渐渐为斗宪所打开，她的感情也悄悄发生着变化。风起云涌的时节，彼此的命运皆无法把握……©豆瓣', '宋康昊', '李铉升', 6.1, 6323, 'tt2015315', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1283985864.jpg', 3.3, 18.6, 52.4, 18.9, 6.8, '0.016563,0.153430,-0.784523,0.582483,0.012925,-0.079723,0.722167,0.156291,-0.607691,-0.456495,0.195501,0.341708,0.225025,0.163756,0.475520,-0.204128,-0.126656,-0.759871,-0.237032,-0.305011,-0.153419,-0.318376,-0.208479,-0.218196,-0.082246,-0.389976,0.678348,0.220589,-0.124644,0.248278,0.246715,0.383269,-0.480718,0.583693,-0.058207,-0.314340,0.076120,-0.001937,-0.441109,0.188442,-0.105301,-0.363124,-0.093189,0.044155,-0.110376,0.396103,0.685749,-0.364799,-0.156682,-0.117155,0.298663,-0.143885,-0.131301,-0.125263,0.481202,0.322843,0.025450,0.514746,-0.304966,-0.112128,-0.200379,-0.281065,-0.637318,0.221257,0.443539,0.246693,-0.483496,0.331965,0.089787,-0.190034,-0.110665,-0.218327,0.220734,0.363588,0.376132,0.260275,-0.138958,0.400446,-0.221326,-0.074350,0.644299,0.003460,-0.193920,0.183575,-0.142878,-0.154782,0.066057,-0.156910,-0.353489,-0.149065,0.132986,0.191406,-0.178577,0.452197,-0.403579,0.086920,-0.106530,-0.167319,0.241942,-0.278553,-0.208448,-0.558847,-0.285772,-0.223803,-0.160464,0.244315,0.083773,-0.060842,0.625619,-0.934914,0.231116,0.424461,0.036668,-0.429660,0.528449,0.102753,0.239237,-0.263451,-0.190282,0.287638,0.143280,0.392139,-0.082086,0.098129,-0.260805,-0.178066,-0.371406,0.078803', '1301022', '35030151', '1293265', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4196129', '天使之恋', '剧情', '14岁那年，美丽可爱的女孩小泽理央（佐佐木希 饰）经历了人生前所未有的变故，在此之后她自甘堕落，和相熟好友们依靠援交和诈骗聚敛金钱，光鲜亮丽的外表下，掩饰不住内心莫名的绝望与空虚。一个意外，让理央邂逅了和自己同姓的大学教师小泽光辉（谷原章介 饰）。光辉那英俊正直又略显呆板木讷的外表和气质刹那间攫住了理央的心。她被阴云笼罩的灵魂仿佛被光辉发自内心的灿烂光芒驱散，她渐渐喜欢上这个大男孩。然而光辉始终无法全心全意投入恋情，因为数年之前，他已被诊断患有恶性肿瘤，留在人间的时间所剩无几……本片根据同名手机网络小说改编。©豆瓣', '佐佐木希', '寒竹百合', 7.4, 109844, 'tt1538401', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2211779255.jpg', 0.9, 5.1, 34.1, 41.1, 18.8, '0.094827,0.239305,-0.705083,0.642427,-0.190898,-0.129957,0.912980,0.253821,-0.392141,-0.319847,-0.067237,0.730336,-0.329611,0.585953,0.049945,-0.001163,-0.077075,-0.797101,-0.224577,-0.150406,0.047285,-0.151611,-0.256996,0.129132,0.024917,-0.547555,0.692776,0.250701,-0.019525,0.781576,0.148720,0.381984,0.027822,0.438244,-0.048523,-0.202745,-0.115510,-0.007054,0.169282,-0.045472,0.020092,-0.524472,0.041595,0.415363,-0.339265,0.422817,0.897033,-0.038021,-0.308928,-0.293013,0.555933,-0.131554,-0.172841,0.244007,-0.094002,0.173007,0.013211,-0.118620,-0.236249,-0.140839,0.125110,-0.166385,-0.693612,0.022337,0.123904,0.164420,-0.383904,0.505543,0.034357,-0.203705,0.228204,-0.249233,-0.048533,-0.272563,0.141560,0.450964,-0.354639,0.152772,-0.226789,0.534411,0.520158,0.203789,-0.640366,0.683536,-0.787529,-0.128167,-0.089353,-0.190680,-0.542066,0.098042,0.293276,0.224386,-0.092843,0.600072,-0.664161,-0.006074,-0.136760,0.163558,-0.275426,-0.482458,-0.172059,-0.303857,-0.820089,-0.507710,-0.473921,-0.009117,0.008644,-0.049891,0.802865,-0.789653,0.127709,0.254534,0.174914,-0.196969,0.519453,0.174593,-0.288491,-0.054118,0.078976,0.441873,0.064073,0.298492,0.169026,0.299388,-0.533541,0.391281,-0.529320,0.593848', '1296992', '24839498', '4817024', '2365260');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4196227', '随波逐流', '喜剧', '丹尼（亚当·桑德勒 Adam Sandler 饰）年轻时经历了一场失败的恋爱，深感被女人欺骗的他偶然间发现了婚戒的妙用，从此伪装成已婚男人四处逢场作戏。多年后丹尼已是一名成功的整形医生，他在一次派对上认识了美丽的女孩帕莫尔（布鲁克琳·黛克 Brooklyn Decker 饰），两人一夜定情。次日醒来，发现了婚戒的帕莫尔误以为丹尼已婚，表示要退出复杂的关系。为挽留心仪的女孩丹尼只得再次编造谎言，并央求医院的助手凯瑟琳（詹妮弗·安妮斯顿 Jennifer Aniston 饰）扮演即将与自己离婚的妻子。只是谎言如同雪球般越滚越大，凯瑟琳的两个孩子、丹尼的兄弟艾迪等人都被卷入其中。当一行人来到夏威夷度假并遇上凯瑟琳的死对头德芙琳（妮可·基德曼 Nicole Kidman 饰）后，失控的事态朝着意外的方向发展了……©豆瓣', '亚当·桑德勒', '丹尼斯·杜根', 7.2, 58942, 'tt1564367', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p769069805.jpg', 0.5, 4.5, 40.4, 42.7, 12, '0.509312,-0.090645,-0.729008,0.273149,-0.093696,-0.508084,0.702769,0.088949,-0.552550,-0.262845,0.197328,0.764084,-0.488485,0.238159,0.442852,0.242606,-0.440173,-0.772623,0.030954,-0.197641,-0.394951,-0.382977,0.010983,-0.170549,-0.009813,-0.306377,0.370755,-0.179303,-0.029431,0.560101,0.555424,0.130852,-0.196961,0.467208,0.083376,0.109733,0.290832,0.111889,-0.431024,0.357413,0.080066,-0.086102,-0.073713,0.034072,-0.274680,0.357952,0.626537,-0.159826,0.010443,-0.271333,0.242620,-0.224122,-0.037332,0.081462,0.160333,-0.056674,0.221265,0.149547,-0.094770,-0.105065,0.262604,-0.093488,-0.263760,0.435498,-0.004513,0.161344,-0.598504,0.465864,-0.065943,-0.078763,0.116151,-0.387023,0.110885,0.183631,0.106251,0.291567,-0.109170,0.109562,-0.278290,0.043461,0.442254,0.205999,-0.129629,0.550583,-0.080983,-0.418237,0.029330,-0.006299,-0.593175,0.148943,0.446582,0.195773,-0.311911,0.165293,-0.510658,-0.125092,-0.623625,0.040474,-0.073624,-0.326833,0.031838,-0.582770,-0.090069,-0.284215,-0.354856,0.012572,-0.047699,-0.112051,0.424839,-0.597520,0.197239,0.575779,0.262775,-0.494102,0.566895,0.192228,0.096397,-0.430402,-0.113658,0.369945,0.003804,-0.028634,0.039109,0.318242,-0.101457,-0.155206,-0.331099,0.271944', '3111650', '3326747', '1309172', '4319218');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4202204', '王的盛宴', '历史', '两千年前的中国，秦王暴政，诸侯起义。血雨腥风的战场之外，散落着建立在密林深处的城邦。项羽（吴彦祖 饰）和刘邦（刘烨 饰），两个反对秦暴政的起义领袖，带领各自的势力，为自由与安乐一路厮杀，同时也在向那座象征着无上权力与无限财富的王朝核心——秦王宫步步逼近。历史的过程总是曲折而模糊的，结果却只有一个：刚烈而冲动的霸王项羽在“鸿门宴”上错失了杀掉刘邦的机会，只能将一腔热血洒向乌江，与自己深爱的女人虞姬（何杜娟 饰）含泪诀别。刘邦和他的吕后（秦岚 饰），他的谋臣韩信（张震 饰）、张良（奇道 饰）、萧何（沙溢 饰）们，则忍辱抗击到最后，成为了辉煌宫殿最终的主人。在那座奢华的大房子里，君临天下的刘邦仿佛早已忘记了和曾经的盟友并肩战斗的岁月，甚至渐渐开始对身边的兄弟们满腹狐疑。另一段杀戮，由此开始在森森耸立的帝国高墙内，无声蔓延……©豆瓣', '刘烨', '陆川', 5.7, 74549, 'tt1919137', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1774799364.jpg', 12.5, 25.3, 36.9, 17, 8.4, '0.041513,0.330312,-0.941845,0.995311,0.212736,-0.253968,0.837335,0.205123,-0.519862,-0.078653,0.440735,0.552803,0.071639,0.154341,0.120992,-0.291956,-0.176363,-0.909116,-0.406519,-0.105833,-0.176624,-0.209778,-0.390126,-0.255461,-0.312132,-0.048241,0.957057,0.255246,-0.077568,0.426284,0.279709,0.183358,-0.335892,0.508900,-0.316327,-0.009485,-0.071377,0.029584,-0.513135,0.063780,-0.226436,-0.456904,-0.456171,0.280438,-0.423512,0.192309,0.625281,-0.665570,0.176801,-0.140850,0.261739,-0.152052,-0.081876,0.283927,0.255467,0.060463,0.182869,0.447339,0.055254,-0.054933,0.039961,-0.084634,-0.683583,-0.261144,0.089606,0.170206,-0.688295,0.843873,0.092033,-0.368930,0.261179,-0.272868,0.295395,0.321748,0.112521,0.278984,-0.464581,-0.135981,-0.608220,0.356100,0.500090,0.159207,-0.130474,-0.021447,-0.028877,-0.420055,-0.206989,-0.140664,-0.527842,-0.319859,0.426132,0.004580,0.215090,0.436600,-0.945708,0.033319,-0.101979,-0.127888,0.085290,-0.294221,-0.018564,-0.354103,-0.200593,-0.427833,-0.192640,0.334093,-0.005921,-0.023441,0.637714,-0.629037,0.108018,0.272808,0.281415,-0.512565,0.636713,-0.001321,0.128407,0.080725,-0.169574,0.480099,-0.072057,0.350137,0.157994,0.304163,-0.316845,0.005429,-0.533432,0.683342', '6875863', '25903033', '21619567', '26761256');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4202302', '借东西的小人阿莉埃蒂', '动画', '虽然患有心脏方面的疾病，但是少年翔（神木隆之介 配音）的父母依然对他疏于呵护。为了准备即将到来的手术，翔来到了位于偏远乡间的姨婆（竹下景子 配音）家静养。姨婆家位于一片幽静的丛林中，这是一幢有着上百年历史的欧式别墅。这里除了生活着姨婆和女佣阿春（树木希林 配音）外，还有一个奇特的三口之家，“借东西一族”——小人阿莉埃蒂（志田未来 配音）和她的爸爸（三浦友和 配音）妈妈（大竹忍 配音），他们生活在别墅的地板下，只有几公分高，过着不为人类察觉的生活。遇到所需的日常用品时，便会在夜深人静之时偷偷潜入厨房借出来。翔无意中瞥见阿莉埃蒂的身影，他有心接近这些传说中的小人，却不知不觉打扰了他们的生活…… 本片根据英国作家玛丽·诺顿的原著《借东西的小人》改编，并荣获2011年日本电影学院奖最佳动画片奖。©豆瓣', '志田未来', '米林宏昌', 8.9, 513542, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p617533616.jpg', 0.1, 0.4, 8.1, 38.3, 53.2, '0.153538,-0.004838,-0.528141,0.550210,0.207460,-0.256507,0.762563,0.200457,-0.406259,-0.681630,0.158151,0.711104,-0.057550,0.301682,0.106185,0.220546,-0.329780,-0.404389,-0.291219,-0.127859,-0.253715,-0.168624,-0.141728,-0.113414,-0.246464,-0.117353,0.548360,0.047016,-0.159090,0.252765,-0.212181,0.250366,-0.228329,0.113400,-0.190141,-0.013510,0.066526,0.040990,-0.404151,0.008643,-0.001903,-0.205211,-0.180784,0.006648,0.225539,0.222651,0.673473,-0.215376,-0.295779,-0.050630,0.242745,0.080808,-0.129262,-0.181421,0.376880,-0.257441,0.441026,0.137406,-0.115371,0.125777,-0.058443,-0.208906,-0.566784,-0.112354,0.021084,0.094647,-0.445564,0.373517,-0.003786,-0.020480,0.072010,-0.375013,0.290856,0.099737,0.117257,0.423496,-0.371200,0.104899,-0.469670,0.164641,0.434225,0.042731,-0.042782,0.474814,-0.260005,-0.383494,0.127051,-0.173065,-0.516794,-0.019645,0.212088,-0.065870,-0.149748,0.029521,-0.494956,0.058184,0.015662,-0.366442,0.274655,-0.207824,-0.287943,-0.721487,0.015697,-0.402853,-0.297468,0.025629,0.129890,-0.283918,0.650899,-0.744605,0.307517,0.485385,0.251797,-0.173695,0.790468,-0.283833,0.183858,-0.051283,-0.186213,0.240796,-0.136810,0.278096,0.048233,0.340909,-0.094012,-0.276520,-0.577537,0.386937', '3055049', '2334814', '3811356', '30401849');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4202326', '近在咫尺的爱恋', '爱情', '台湾某私立大学拳击社因人气低迷，正面临这被学校关闭的命运。该社的教练也将就此失业，这令教练的女儿——同时也是拳击社的女经理人——丁小葵（郭采洁 饰）忧心忡忡。万人迷社长赵大杰（彭于晏 饰）虽然身有旧伤，却仍决定全力拼搏，在选拔赛上取得优异成绩，同时也为了却心中夙愿。正 值此时，两名大陆学生转到这所学校。男孩陈家翔（明道 饰）是北京综合大学拳击队前主将，曾取得全国大赛的冠军，却因一场车祸留下头疼的后遗症，从此与拳击绝缘；女孩迟姗姗（苑新雨 饰）拉的一手优美的小提琴，同时也是家翔的粉丝。在小葵和珊珊的激励下，家翔决定走回拳台。青春男女为了各自的理想挥洒汗水……(正在采用)©豆瓣', '彭于晏', '程孝泽', 6.2, 20760, 'tt1725809', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2359526939.jpg', 2.5, 14.8, 56.3, 21, 5.3, '-0.040536,0.188352,-0.374176,0.437094,0.093559,-0.253414,0.348643,0.249722,-0.191203,-0.078046,0.415876,0.586584,-0.186821,0.343557,0.181730,-0.210685,-0.116875,-1.007876,-0.137848,-0.045155,-0.185492,-0.073592,0.066863,0.278324,-0.201482,-0.213712,0.869898,0.049453,-0.188867,0.737394,0.500087,0.404803,-0.084471,0.232487,-0.084821,-0.076761,-0.111319,0.112287,-0.338751,-0.133707,0.341469,-0.338015,-0.364678,0.116261,0.248453,0.281567,0.711608,0.120537,0.055429,-0.128094,0.354724,-0.324677,-0.090351,-0.026158,0.428278,0.044582,0.315087,0.091651,0.143835,0.091823,0.086273,-0.022987,-0.581952,0.102496,0.368443,0.014122,-0.443258,0.913973,-0.183220,-0.021507,0.029135,-0.017957,-0.072142,0.313906,0.003945,0.153892,-0.151636,0.131018,-0.125273,0.398940,0.704164,-0.050504,0.074819,0.152397,-0.188615,-0.359996,-0.014507,-0.177077,-0.128575,0.065562,0.135369,0.088905,0.326456,-0.102868,-0.296152,0.104561,-0.358668,-0.133684,0.125609,-0.347035,-0.006747,-0.525006,0.150544,-0.187538,-0.238597,0.166733,0.211021,-0.142350,0.619075,-0.902505,-0.211621,0.221568,0.211394,-0.205689,0.544192,-0.026548,0.163013,-0.185869,-0.378415,0.101460,-0.372758,0.394078,-0.063282,0.439265,0.072453,-0.354011,-0.245330,0.546241', '1826173', '26615753', '26365262', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4202982', '冰雪奇缘', '喜剧', '在四面环海、风景如画的阿伦黛尔王国，生活着两位可爱美丽的小公主，艾莎和安娜。艾莎天生具有制造冰雪的能力，随着年龄的增长，她的能力越来越强，甚至险些夺走妹妹的生命。为此国王紧闭宫门，也中断了两姐妹的联系。悲哀的海难过后，艾莎（伊迪娜·门泽尔 Idina Menzel 配音 ）终于到了加冕的年龄，各国王公齐来祝贺。艾莎战战兢兢，唯恐被人识破隐藏了多年的秘密。然而当听说安娜（克里斯汀·贝尔 Kristen Bell 配音）将要和初次见面的南埃尔斯王子汉斯（圣蒂诺·方塔纳 Santino Fontana 配音）结婚时，依然情绪失控露出了马脚。在此之后她逃到山中，构建了属于自己的冰雪王国，而阿伦黛尔也陷入可怕的寒冷之中。安娜独自来到山中，在山民克斯托夫（乔纳森·格罗夫 Jonathan Groff 配音）的帮助下总算来到姐姐的宫殿，她能否让国家重新找回失落的绿意？', '克里斯汀·贝尔', '克里斯·巴克', 8.4, 653629, 'tt2294629', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2166640945.jpg', 0.2, 0.9, 14.3, 46.6, 38.1, '0.105194,0.263264,-0.629171,0.622957,-0.074332,-0.323207,0.562209,0.176096,-0.392757,-0.249768,0.226473,0.678186,-0.147813,0.191896,0.354399,0.131015,-0.616476,-0.426197,-0.070153,-0.198683,-0.184776,-0.401022,-0.233122,-0.204638,-0.048365,-0.730510,0.567216,0.024615,-0.145378,0.343478,0.004267,0.084197,-0.252616,0.379234,0.167975,0.200344,0.323297,-0.130982,-0.129954,0.197119,-0.066556,-0.067378,-0.263727,0.322672,0.191289,0.430420,0.450379,-0.492337,0.119373,-0.013857,0.203323,-0.212636,0.296593,0.123811,0.203053,-0.216380,0.170990,0.007885,-0.242362,-0.071259,0.034968,-0.196181,-0.561936,0.378189,0.269580,0.024812,-0.481509,0.312993,-0.014040,-0.193976,0.170239,-0.290710,0.069829,0.487899,0.037679,0.474295,-0.127427,0.257750,-0.249657,-0.252105,0.524494,-0.053737,-0.484571,0.086508,-0.202774,-0.423020,-0.144928,-0.232176,-0.554884,-0.093770,0.426828,0.028595,0.068139,0.493677,-0.614640,-0.218673,-0.484148,-0.095398,-0.040305,-0.329327,-0.156374,-0.552918,-0.064558,-0.402932,-0.083122,-0.073285,0.218808,-0.216122,0.513002,-0.767470,0.431498,0.465526,0.279057,-0.211328,0.330682,-0.167461,-0.013406,-0.095278,-0.267325,0.658845,-0.105220,0.332397,0.205109,0.290727,-0.197556,0.013999,-0.448563,0.505541', '4126925', '30401849', '1303034', '10440076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4202983', '血色孤语', '喜剧', '杰瑞（瑞安·雷诺兹 Ryan Reynolds 饰）是工厂里的打包工，和一猫一狗过着相依为命的生活。同事眼中的杰瑞乐观开朗，对工作充满了热情，可实际上，杰瑞患有严重的精神分裂症，需要依赖药物控制病情，更糟糕的是，杰瑞并没有按照医嘱服用药物！因为一旦吃了药，他就无法和家里的阿猫阿狗对话了。杰瑞喜欢着广告部的女同事菲奥娜（杰玛·阿特登 Gemma Arterton 饰），一场意外中，菲奥娜命丧杰瑞刀下，杰瑞将菲奥娜的尸体带回家，将她的头切下来藏在了冰箱里。让杰瑞感到震惊的是，菲奥娜的头竟然也开始说话了，菲奥娜恳求杰瑞替她找一个伴儿，于是，杰瑞将目标放在了菲奥娜的好友丽萨（安娜·肯德里克 Anna Kendrick 饰）身上。©豆瓣', '瑞安·雷诺兹', '玛嘉·莎塔琵', 7.2, 11336, 'tt1567437', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2222036287.jpg', 1.1, 4.9, 37.6, 43.7, 12.7, '0.501892,-0.140847,-0.528164,0.301752,-0.279973,-0.487310,0.957091,0.231817,-0.487808,-0.011038,0.066441,0.560793,-0.018332,0.174518,0.043889,0.331450,-0.528295,-0.725772,-0.076610,-0.009611,-0.304173,-0.478057,-0.040628,-0.406667,-0.125239,-0.411196,0.082654,-0.235864,-0.027234,0.590578,0.202570,0.128263,0.217168,0.672687,-0.032375,0.084575,0.036433,-0.416194,-0.105558,0.386483,0.471525,-0.005758,-0.033422,0.502171,0.414632,0.547750,0.482714,-0.150312,-0.169648,0.103398,0.111412,-0.097151,0.050175,0.145894,0.175186,0.079474,0.294891,-0.039744,-0.295978,0.124158,0.322618,0.164705,-0.797181,0.005796,-0.150709,0.197475,-0.616635,0.397669,-0.198140,-0.004114,0.156782,-0.242628,0.277995,0.088080,0.151475,0.436429,-0.093367,-0.009473,-0.400894,0.048941,0.244563,-0.076389,-0.010602,0.392033,-0.524541,-0.364282,0.071938,-0.078527,-0.416839,-0.077587,0.487857,0.052927,-0.265328,0.266619,-0.358200,0.010562,-0.169696,-0.256393,-0.113014,-0.159714,-0.064348,-0.402033,-0.093545,-0.439467,-0.464862,-0.367243,0.047579,-0.217002,0.559863,-0.764577,0.180737,0.420032,0.419039,-0.041528,0.445137,0.095414,0.084291,0.002566,-0.160363,0.134867,-0.112023,0.234133,0.628098,0.568132,0.169750,-0.052965,-0.465208,0.365918', '1308755', '1297996', '21348112', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4206357', '龙纹身的女孩', '剧情', '《千禧年》杂志的财经记者米克尔·布隆克维斯特（丹尼尔·克雷格 Daniel Craig 饰）正被一桩报导引起的诽谤诉讼案搞得焦头烂额之际，却意外接到了瑞典顶尖家族企业范耶尔工业集团的创始人亨利·范耶尔（克里斯托弗·普卢默 Christopher Plummer 饰）的邀请。表面上米克尔要为对方写传记，实则是帮迪奇调查一桩40年前发生在家族里的悬而未决的杀人案。米克尔认真梳理堆积如山的资料，与家族成员交流攀谈。却在关键时刻，被一个边缘女孩莉丝贝丝·沙兰德（鲁妮·玛拉 Rooney Mara 饰）入侵电脑盗取了资料。他找到同要具有非凡调查能力的莉丝，邀请她一同调查，却发现面前是一个深不见底的欲望黑洞……本片根据瑞典小说家斯蒂格·拉尔松（Stieg Larsson）的原著改编。©豆瓣', '丹尼尔·克雷格', '大卫·芬奇', 8.1, 225391, 'tt1568346', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1473779689.jpg', 0.3, 1.5, 19.6, 51.9, 26.7, '0.492254,0.028889,-0.571075,0.620662,0.332589,-0.256438,0.547758,0.185045,-0.455203,-0.465621,0.013837,0.475801,-0.467427,-0.001241,0.209575,0.215891,-0.376404,-0.707009,0.100308,-0.231754,-0.085661,-0.536788,-0.470404,-0.237724,-0.100551,-0.304851,0.486313,0.066830,-0.352089,0.233665,0.139810,0.483658,-0.158979,0.336161,0.108237,-0.178336,0.365524,-0.164687,0.007313,0.347399,-0.000107,-0.285084,-0.093617,0.202212,0.178262,0.488924,0.422510,0.008992,0.111095,0.054081,0.533714,-0.214298,0.114113,-0.032795,0.737302,0.103076,-0.122224,0.333305,-0.367985,-0.458757,0.180098,-0.086294,-0.976829,-0.202838,0.121058,0.591083,-0.422827,0.315187,-0.408328,0.230053,-0.163174,-0.223273,0.257973,0.224921,0.240173,0.148258,0.390533,0.141922,-0.397047,0.250331,0.133971,0.176573,0.006945,-0.015751,-0.318675,-0.315028,-0.043516,-0.286511,-0.377638,0.112943,0.337918,-0.106932,0.043358,0.472615,-0.433749,-0.229368,-0.437276,-0.169473,-0.077578,-0.501842,-0.075967,-0.968831,-0.363757,0.090258,-0.237580,-0.154435,0.080797,-0.237273,0.630720,-0.420725,-0.018757,0.707751,0.051802,-0.043305,0.617360,-0.066495,0.054861,-0.147225,-0.181470,0.001329,0.366690,0.085114,-0.091121,0.295977,0.271044,-0.478395,-0.274101,0.135951', '3318306', '1293433', '1293656', '4014397');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4206436', '战马', '剧情', '1914年，在德文郡小镇，男孩艾尔伯特（杰瑞米·艾文 Jeremy Irvine 饰）目睹了幼驹乔伊的诞生。在集市上，它被频繁叫价，最终被艾尔伯特的父亲泰德（彼得·穆兰 Peter Mullan 饰）用30几尼的天价收入囊中，跛脚的他也因此得罪了地主。艾尔伯特与乔伊尽情 嬉戏，与朋友分享。然而，好景不长，地主登门拜访，称如果乔伊不能犁地将立刻将其带走，于是泰德赌上了全部家当。于是，艾尔伯特在逼迫之下，为乔伊套上了鞍蹬，强迫它犁地，甚至还使用了皮鞭，却不能让它屈服就范。为了还债，泰德亲自上阵犁地，功夫不负有心人，辛苦换来了收成，但是一场大雨毁了一切。德军来袭，父亲被迫将马变卖给骑兵军，换了30几尼。艾尔伯特虽然难以割舍也只能含泪送别乔伊踏上了前途未卜的战场。战争中，乔伊的主人不停在变，从英国上尉，法国老农与孙女，到德国骑兵，然而它真正等待的是艾尔伯特，他们能够重逢吗……', '杰瑞米·艾文', '史蒂文·斯皮尔伯格', 8.2, 222663, 'tt1568911', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1248524406.jpg', 0.3, 1.5, 18.4, 47.4, 32.4, '0.146041,0.230869,-0.535979,0.281173,-0.270888,-0.494079,0.374537,0.010005,-0.351023,0.165427,0.196476,0.745427,0.004135,0.045054,0.180503,-0.053245,-0.185692,-0.595298,0.129628,0.097204,-0.241759,-0.430827,-0.066956,-0.251883,-0.306040,-0.165626,0.436472,0.086942,0.061169,0.393115,0.260397,0.212089,0.143049,0.378492,-0.342108,0.114469,-0.162793,-0.212825,-0.275136,0.342764,0.007219,-0.335755,-0.125155,0.149402,0.214775,0.291096,0.673919,-0.451800,0.144076,-0.134633,0.039680,-0.293390,0.182859,0.246629,-0.087598,0.067529,0.031617,0.092390,-0.224235,0.005724,0.219312,0.027302,-0.418003,0.120900,-0.039406,-0.074807,-0.822505,0.394747,-0.101811,0.102480,-0.026854,-0.337371,0.167670,0.344531,0.199588,0.112447,-0.375201,-0.091482,-0.605789,0.177351,0.478391,-0.199534,-0.069086,0.205953,-0.014356,-0.295781,0.135341,-0.478955,-0.445975,-0.091620,0.446622,0.318128,-0.205907,0.265986,-0.615113,-0.198209,-0.543749,-0.406788,-0.061613,-0.413422,-0.025961,-0.307592,0.074320,-0.232432,-0.308992,0.172459,0.313386,-0.181613,0.452057,-0.438229,0.068535,0.451955,0.392820,-0.114156,0.405210,-0.107969,0.219061,0.004867,0.027093,0.128841,0.170547,0.445644,0.519750,0.123766,0.041448,0.067892,-0.257194,0.668553', '10773239', '