INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4206468', '抓住外国佬', '剧情', '影片讲述了一个职业罪犯（梅尔·吉布森 Mel Gibson 饰）被墨西哥警方抓捕后送往一个充满毒品和犯罪的监狱，在一个9岁男孩的帮助下，他学会了如何在这样的监狱里生存下来。本片由梅尔·吉布森和《启示》（Apocalypto）的原班人马在墨西哥的伊格阿连德监狱拍摄完成。梅尔 ·吉布森不会亲自执导这部影片，而是让《启示》的第一助理导演Ad rian Grunberg来当导演。不过这部影片的剧本是吉布森自己创作的，而且他也将亲自主演。', '梅尔·吉布森', '阿德里安·格鲁伯格', 7.4, 11127, 'tt1567609', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1653838655.jpg', 0.5, 2.6, 37, 47.6, 12.3, '0.144805,0.042847,-0.531259,1.084113,-0.096997,-0.275226,0.908146,0.063365,-0.173817,-0.142360,0.310661,1.219493,-0.112468,0.163982,0.230933,0.023004,-0.697384,-0.635069,-0.420886,-0.164967,-0.376833,-0.527954,-0.456672,-0.015110,-0.030368,-0.201234,0.868273,-0.047887,-0.079747,0.264745,0.430733,0.192919,0.315943,0.256261,0.123414,0.312974,0.482767,-0.366565,-0.212405,0.756659,0.406705,-0.327903,-0.259531,0.198131,0.020610,0.288106,0.572730,0.011947,-0.105538,-0.097008,0.690167,-0.530594,0.011409,-0.099063,-0.015070,-0.063389,0.278054,0.330023,-0.379538,0.372918,-0.073861,-0.353809,-1.298809,-0.136567,0.121371,0.154112,-0.763938,0.215065,-0.242657,0.222931,-0.079433,-0.337541,0.113964,0.266876,0.348447,0.303823,-0.267646,-0.021763,-0.733263,0.660638,0.410990,-0.162829,-0.226410,0.358653,-0.017943,-0.677937,-0.115736,-0.056252,-0.655599,0.166468,0.509419,-0.467101,-0.239343,-0.246961,-0.483054,-0.278203,-0.335009,-0.390003,-0.207594,-0.528172,0.088626,-0.999638,-0.181767,-0.109175,-0.077076,-0.451287,0.312631,-0.382344,0.804305,-0.516879,0.135453,0.781273,0.012039,-0.352399,0.740850,0.127204,0.250871,-0.149986,0.061348,-0.010334,0.326676,0.489596,0.226624,0.572231,0.248697,-0.408151,-0.680253,0.520913', '34890458', '1297503', '25731059', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4206477', '窗台上的男人', '惊悚', '尼克·卡西迪（萨姆·沃辛顿 Sam Worthington 饰）曾经是一名正直负责的警察，却因涉嫌盗窃4000万美元的钻石而获刑25年监禁。他唯一一个离开监狱的机会就是参加父亲葬礼，并在葬礼上趁机逃跑。然而令人不解的是，他并没有出境，而是到曼哈顿酒店开了个24楼的房间，精心擦洗一番后，只为在最繁华的纽约的注视中坠楼。他的举动很快引来了大批警察和媒体，一名年轻的谈判专家莉迪亚（伊丽莎白·班克斯 Elizabeth Banks 饰）试图将其劝回屋内，然而在循序渐进的劝说中，莉迪亚意识到尼克是被钻石的拥有者大卫（艾德·哈里斯 Ed Harris 饰）陷害入狱的，目的则是为了高额保险金。然而更令莉迪亚想不到的是，尼克的自杀只是一个声东击西的幌子，他的弟弟和女友正在街对面的珠宝库大楼中实施复仇计划……©豆瓣', '萨姆·沃辛顿', '阿斯各·莱斯', 7.2, 26421, 'tt1568338', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1226364053.jpg', 0.4, 3.8, 40.4, 44.7, 10.6, '0.393453,0.174537,-0.744305,0.661962,-0.418493,-0.251100,0.928807,0.082536,-0.562100,-0.316209,0.402039,0.689187,-0.013549,0.230882,0.369121,0.127528,-0.222768,-0.610269,-0.224179,-0.155383,-0.416552,-0.684029,-0.178694,-0.204678,-0.015903,-0.206580,0.579291,0.122815,-0.017752,0.445818,0.567944,0.404416,0.021254,0.453774,-0.077828,-0.137272,0.338739,-0.093977,-0.194936,0.345465,-0.119055,-0.549771,-0.192528,0.368911,-0.009641,0.494355,0.614558,-0.211226,0.147169,-0.062042,0.311824,-0.399811,0.062688,0.175082,0.416947,-0.054755,0.315548,0.380394,-0.402063,-0.026690,0.233516,-0.251791,-0.866315,-0.035970,0.158234,0.135556,-0.444470,0.367257,-0.194229,0.112410,0.113138,-0.283580,0.279135,0.242972,0.119534,0.333652,-0.259814,-0.082629,-0.688180,0.201482,0.481810,-0.059100,0.088202,0.325182,-0.077424,-0.427853,0.125090,-0.154119,-0.256273,-0.144479,0.446907,-0.026451,-0.155196,-0.205193,-0.482166,-0.190236,-0.591147,-0.408981,-0.004878,-0.348797,-0.130235,-0.792795,0.021067,-0.216698,-0.284180,0.144555,-0.061031,-0.280446,0.326778,-0.891116,0.101597,0.722404,0.149174,-0.469182,0.705355,-0.040329,0.092638,-0.023404,-0.255812,0.175654,0.343456,0.318764,-0.179714,0.262951,0.022452,-0.393207,-0.362020,0.452880', '1301686', '1307442', '3326747', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4212172', '十二生肖', '喜剧', '当年英法联军火烧圆明园，致使大批珍贵文物流落海外，其中四尊十二生肖兽首最引人关注，不仅惹出国内外的广泛争论，更有收藏家开出天价竞拍这几尊珍品。当然，其间不乏奸邪的文物贩子，试图通过偷盗的手段获取宝贝。以此为契机，正在度假的国际大盗JC（成龙 饰）隆重登场。JC背后有一支 Simon（权相宇 饰）、David（廖凡 饰）、Bonnie（张蓝心 饰）等人共同组成的超专业团队，他们一同远赴巴黎，寻求国宝鉴定专家Coco（姚星彤 饰）的帮助。经过周密细致的准备，JC等人一步步逼近重兵把守的兽首，而围绕珍宝不可避免爆发连番惊险火爆的打斗与追逐。在这一过程中，JC似曾被利益和金钱泯灭的爱国之心渐渐苏醒……©豆瓣', '成龙', '成龙', 6.8, 336637, 'tt1424310', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1826580562.jpg', 1.9, 9.5, 47.8, 30.7, 10.1, '0.083377,-0.082760,-0.842695,0.407437,0.376604,0.193017,0.390820,-0.028417,-0.569589,-0.081546,0.493849,0.524547,-0.286406,-0.419398,0.244847,-0.243602,-0.175044,-0.493560,0.025147,-0.009158,-0.196589,-0.145485,-0.493996,-0.106373,-0.239736,-0.350023,0.514585,0.266693,-0.194611,0.562920,0.178355,0.332819,-0.276661,0.050243,-0.149031,-0.305787,0.365940,0.293846,-0.300652,0.101482,-0.276368,-0.392547,-0.162511,-0.013020,-0.232441,0.266569,0.541143,-0.282127,0.112640,-0.012070,0.307783,-0.258407,0.049382,0.074392,0.079416,0.354117,0.226221,0.199442,-0.462936,0.149557,0.216831,-0.180388,-0.898204,-0.124289,0.469680,0.075457,-0.270712,0.221242,0.196836,0.100557,0.091903,-0.114877,0.253961,0.464434,0.293653,-0.039063,0.067850,-0.098482,-0.431490,0.481592,0.368476,-0.167819,0.048868,0.088834,-0.120136,-0.454148,0.212536,-0.470200,0.095581,-0.243597,0.557784,0.029953,0.280914,0.062917,-0.930639,0.101264,-0.167992,-0.187888,0.090356,-0.086898,-0.091196,-0.931380,-0.196209,-0.365993,0.062051,0.193526,0.209451,-0.115460,0.937531,-0.347180,0.058611,0.533900,0.236999,-0.479608,0.491751,-0.378443,-0.009518,-0.233445,-0.514937,-0.141897,0.062425,0.147180,-0.249978,0.017751,0.038062,-0.358415,-0.175409,0.152491', '3318306', '4181031', '19965431', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4215662', '神秘博士特别篇：时间尽头(上)', '语言:', 'The Ood have given a warning to The Doctor. The Master is returning yet that is not the biggest threat. A darkness is coming which brings with it The End of Time.', 'David Tennant', 'Euros Lyn', 9.2, 7031, 'tt1415016', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2508913152.jpg', 0.2, 0.6, 6.3, 22.4, 70.5, '0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000', '10001432', '10047547', '10174444', '10342838');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4215755', '神秘博士特别篇：时间尽头(下)', '剧情', 'The Doctor faces the end of his life as the Master''s plans hurtle out of control. With the sound of drums growing louder, and an ancient trap closing around the Earth, the Doctor and Wilf must fight alone. But sacrifices must be made, and the deadly prophecy warns: "He will knock four times."', '大卫·田纳特', '尤洛斯·林', 9.4, 8212, 'tt1415017', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2151699747.jpg', 0.5, 0.5, 4.8, 17.4, 76.7, '0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000', '10001432', '10047547', '10174444', '10342838');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4215790', '疯狂愚蠢的爱', '剧情', '卡尔·韦弗（史蒂夫·卡瑞尔 Steve Carell 饰）人到中年，中年危机如约到来——妻子艾米丽（朱丽安·摩尔 Julianne Moore 饰）提出离婚，令他面对儿女不知所措。重回情场的卡尔发现自己已经脱离男欢女爱的时代了，幸而遇到泡妞高手雅各·帕尔默（瑞恩·高斯林 Ryan Gosling 饰），帮他重整行头，教他当今最时髦的方法俘获女人芳心。卡尔重战情场了，反而是雅各遇上感情烦恼，他遇见一个叫汉娜（艾玛·斯通 Emma Stone 饰）的姑娘，令他发现真爱原来和招数、游戏根本无关，他不再在意是否“泡到”她，宁愿和她聊一整夜。女人缘变好的卡尔渐渐发现家庭仍是自己最大牵挂，雅各渐渐发现自己愿意为汉娜放弃花花公子的日子，加上卡尔13岁的小儿子也开始情窦初开为爱烦恼，爱有多疯狂，又有多愚蠢，在汉娜邀请雅各回家吃饭的那刻，终于见了分晓……©豆瓣', '史蒂夫·卡瑞尔', '格伦·费卡拉', 7.3, 76050, 'tt1570728', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1068933494.jpg', 0.5, 3.7, 37.6, 44.8, 13.3, '0.222018,0.025980,-0.652884,0.037846,-0.307303,-0.330686,0.415424,-0.053874,-0.460402,-0.469711,0.078860,0.575473,-0.102866,0.272358,0.348820,0.015888,-0.191108,-0.580209,0.376938,0.053329,-0.028809,-0.418789,-0.103862,-0.247927,-0.009957,-0.595784,0.338383,-0.000485,0.085553,0.177792,0.535609,0.231738,0.217827,0.562264,0.109859,-0.018693,0.064115,0.135290,-0.347853,0.193541,-0.005736,0.095155,-0.151960,0.134998,-0.115809,0.240417,0.277900,-0.013849,-0.064176,-0.112841,0.443700,0.000672,-0.055223,-0.054289,-0.096264,-0.239669,0.037573,-0.021656,-0.042710,0.051095,0.074017,0.036970,-0.167029,0.261268,0.010751,-0.040470,-0.429357,0.116964,-0.344661,-0.060785,0.018786,-0.318768,-0.014762,0.255772,0.378851,0.161423,-0.007299,0.091956,-0.335503,0.136949,0.563650,0.235990,-0.128122,0.457978,-0.038052,-0.196385,0.231733,-0.375588,-0.363946,-0.057369,-0.005877,0.082488,-0.241831,0.403037,-0.320847,-0.007216,-0.254913,0.036373,0.239453,-0.339561,0.026244,-0.242341,-0.250811,-0.306116,-0.292924,-0.005647,-0.043796,-0.445372,0.640391,-0.737987,0.273614,0.394894,0.336772,-0.475335,0.577505,0.152658,-0.163326,-0.294585,-0.035935,0.748359,-0.183048,-0.155877,-0.015829,-0.031330,-0.039830,-0.225078,-0.140035,0.457257', '1292720', '