INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4216624', '数码宝贝大冒险：我们的战争游戏！', '科幻', '在网路上，突然出现了一隻数码蛋，这隻蛋破壳后，出生了一隻数码宝贝，它疯狂地吞噬着整个电力网络系统，给电力网络运行造成了重大影响，而且它不断地进化，食量也越来越大。太一在开始的时候和素娜吵架了，阿和和阿武外出了，美美去玩了，阿助……只有光子郎和太一在，阿武和阿和找到了电脑来支援太一，后来那个数码宝贝又一次进化了！这时候，发生了一件意想不到的事情……©豆瓣', '藤田淑子', '细田守', 8.9, 6632, 'tt0313441', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2562994505.jpg', 0.3, 0.6, 9.9, 31.8, 57.4, '0.223347,0.064824,-1.051427,0.499156,0.139235,-0.499243,0.901816,0.139615,-0.220184,-0.035859,-0.367765,0.799273,-0.611695,0.155214,-0.017816,-0.144180,-0.390102,-0.477889,-0.007270,-0.097313,-0.665216,-0.327787,-0.084366,0.002151,0.202097,-0.449149,0.184284,-0.188258,-0.373319,0.504403,0.282025,-0.117685,0.124563,1.033264,-0.241080,0.443608,-0.132674,0.125522,0.488674,0.352436,0.411126,-0.431118,0.037053,0.253529,0.207547,0.111084,0.878547,-0.703466,-0.276304,-0.377552,0.307889,-0.227075,-0.265418,-0.147139,0.651994,0.008774,0.025117,-0.256138,-0.356606,0.053077,0.277014,-0.014794,-0.875117,-0.236569,-0.454886,0.279174,-0.641999,0.057264,-0.032255,-0.114222,0.264454,-0.568958,0.368532,1.001815,0.154513,0.377311,-0.449440,0.055600,-0.624306,-0.006798,0.739188,-0.068098,-0.211794,0.583055,0.016449,-0.631874,-0.629227,0.162599,-0.285939,-0.232766,0.764791,0.184705,-0.419688,0.437653,-0.935930,0.087409,0.129575,-0.420374,-0.231456,-0.279434,-0.198855,-0.401287,-0.151592,-0.474273,-0.311032,0.248446,-0.042351,-0.190353,0.920138,-1.015150,0.106936,0.693005,0.730839,-0.238011,0.438047,-0.021650,0.202242,-0.004245,0.174664,-0.602143,-0.035040,0.901538,0.677666,0.822582,0.351785,-0.001830,-0.661954,0.423828', '26670686', '1866424', '1457926', '1438591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4217426', '大奥', '剧情', '18世纪初，日本正处于德川幕府统治时期。是时一种名为“赤面疱疮”的恶疾在岛内流行，患病者无一例外皆为男性，此恶疾顽固难治，致令死亡人数不断攀升，更令日本国内男女比例严重失调。居住在江户的旗本武士水野家家境贫困，为帮父母缓解压力，19岁的少年武士祐之进（二宫和也 饰）作别青梅竹马阿信（堀北真希 饰），决然前往大奥供职。由于男性稀少，大奥成为了各色美男的天下。这群男人为了权力和地位乃至将军的宠幸争风吃醋，明争暗斗，与女子不遑多让。不久，新任将军吉宗公（柴咲コウ 饰）入住江户，男性后宫由此再起波澜……本片根据よしながふみ的同名少女漫画改编。©豆瓣', '二宫和也', '金子文纪', 7.1, 39299, 'tt1571235', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p781790774.jpg', 0.8, 5.6, 43.4, 38, 12.3, '-0.109066,0.022764,-0.401349,0.222192,0.120962,0.175554,0.502014,0.398030,-0.546286,-0.445353,0.388553,0.754017,-0.078234,0.122347,0.383964,-0.169198,0.050862,-0.401169,-0.316970,-0.128333,-0.160786,-0.138747,-0.264410,-0.220302,-0.538565,-0.747556,0.966227,0.173986,-0.235846,0.434367,0.234380,0.535818,-0.241656,0.138239,-0.119785,-0.337072,0.080046,-0.175196,-0.268982,0.197434,-0.381633,-0.414443,0.169210,-0.161762,-0.177320,0.278143,0.682427,-0.264147,0.039058,-0.323390,0.543215,0.101107,-0.330794,0.180043,0.556239,-0.183694,0.311036,0.207457,-0.081056,0.133324,-0.270869,-0.019472,-0.511580,-0.067432,0.477978,0.269381,-0.188357,0.614112,-0.120913,-0.384539,0.201403,0.038645,0.167216,0.453301,0.028392,0.280449,0.035734,0.231678,-0.209558,0.234598,0.579188,0.156306,-0.294159,-0.121317,-0.321407,-0.519601,-0.064705,-0.488039,-0.325407,-0.155684,-0.226694,-0.097368,0.196978,0.450109,-0.324576,0.089745,-0.076129,-0.013933,0.260006,0.065896,-0.053411,-0.427119,-0.095018,-0.556594,0.007547,0.024377,0.515922,-0.053520,1.048850,-0.646397,-0.027271,0.374958,0.583956,-0.646050,0.501752,0.042376,0.112384,-0.082718,-0.492341,0.358827,0.063291,0.003412,-0.180153,0.102227,-0.337479,-0.164579,-0.204787,0.030153', '27602116', '3811356', '25880986', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4217526', '铠甲勇士之帝皇侠', '科幻', '铠甲勇士们战胜了暗影黑魔兽，地球重新回归了平静和安宁，然而，唯一没有被封印的魔兽10号成为了美真（杨亚 饰）的心头大患，她找到了子阳（唐禹哲 饰），将保护世界和平的重任交付给了他。子阳和阿介（袁成杰 饰）是从小到大的好友和玩伴，两人共同经营着一辆名为“幸福一口”的餐车，生意十分红火。巴豆（廖晓晨 饰）是沉迷于网络世界的宅男，同时亦是经验丰富的网络黑客。现实中，巴豆个性内向毫不起眼，甚至常常受到周围人的欺负。暗影护法相中了巴豆，两人定下了契约破坏铠甲，与此同时子阳和阿介因为误会而产生了矛盾，重要的铠甲召唤腰带亦遭到损坏。在如此危机的情势之下，子阳最终能够反败为胜吗？©豆瓣', '唐禹哲', '郑国伟', 7.5, 7784, '铠甲勇士 / 铠甲勇士之皇帝侠', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2311446485.jpg', 3.2, 6.5, 30.4, 32, 27.9, '0.123634,0.150920,-0.495087,0.540255,-0.052916,0.084378,0.527785,0.241483,-0.447024,-0.177498,0.240341,0.649795,-0.021600,0.048516,0.224779,-0.036150,0.040986,-0.640643,-0.013314,-0.070101,-0.337466,-0.248892,-0.403827,-0.150717,-0.147902,-0.690292,0.794657,0.154834,-0.190733,0.258851,0.246962,0.417621,-0.198721,0.449199,-0.212047,-0.158255,-0.020818,-0.074640,-0.136354,0.133535,-0.256119,-0.068019,0.164916,0.457615,0.003694,0.118495,0.790078,-0.519896,-0.308994,-0.285342,0.298855,-0.270987,-0.076024,-0.098533,0.300026,-0.013100,0.181409,0.203644,-0.169062,0.069196,0.291244,0.146682,-0.629423,-0.085136,0.246767,-0.060343,-0.538629,0.554487,-0.091500,-0.246408,-0.090021,-0.091022,0.257609,0.190257,0.450751,0.236127,-0.189193,0.153582,-0.456354,0.050936,0.547437,-0.025457,-0.351948,0.275361,-0.324805,-0.336365,-0.186439,-0.364381,-0.310790,-0.020056,0.495726,0.228657,-0.169579,0.349170,-0.798759,-0.050888,-0.028977,-0.140894,0.153727,-0.418714,-0.090685,-0.449213,-0.326608,-0.333028,-0.277477,0.076363,-0.042602,-0.171474,0.836406,-0.914559,0.074473,0.160779,0.321669,-0.450123,0.656773,0.090291,0.265047,-0.055231,0.053473,-0.049425,0.016660,0.207912,0.368234,0.216700,-0.140884,-0.001489,-0.282921,0.273754', '1826173', '26759820', '25880986', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4218768', '画皮2', '剧情', '妖狐小唯（周迅 饰）因救人违反妖界规则，被封冻在寒冰地狱中度过了五百年，痛苦不堪。在命运面前，逃离冰窟的小唯只有两个选择：要么被寒冰地狱的冰舌抓回去，要么获得一颗“主动奉献”的人心真正成人。小唯四处寻找目标，直到偶遇逃婚并因一次意外被毁容的靖公主（赵薇 饰）。小唯很快发现，公主有一颗与众不同的心，她把变成人的理想全部寄托在公主身上。公主现身白城让曾经青梅竹马又极负罪恶感的霍心（陈坤 饰）惊讶不已。面对公主，他无法接受公主逃婚并准备和自己私奔的突如其来的现实。小唯发现靖公主与霍心微妙的心理状态，她的计划顺应诞生。她向靖公主灌输男人对女人的爱只不过是色欲之爱，以此暗示公主相貌的丑陋是霍心不敢接受公主爱情的唯一原因，并不惜用妖法迷惑霍心，当公主披着小唯的皮诱惑霍心，并初次体验到了肉体的欢娱时，她开始相信小唯所说的美丽的力量。此时，天狼国步步逼近意欲抢婚，霍心试图只身抵抗以死赎爱。关键时刻却又反被靖公主营救，这一切极大的刺激了霍心。他明白了什么是爱，以爱的名义在一起，哪怕是死在一起，这才是爱的真谛。死亡的诀别戏剧性地改变了两个女人的人生态度，小唯与公主的关系从引诱、胁迫转至合谋，霍心则在得知了二人换心换皮的真相后刺瞎双眼，更试图用自己的心换回公主的心。公主为爱而死的决心，霍心为真心而战的勇气，小唯为改变命运而竭尽全力的努力，在日食之刻最终产生奇迹……', '周迅', '乌尔善', 6.1, 257718, 'tt2371411', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1580617877.jpg', 4.5, 19, 51.1, 18.9, 6.3, '-0.032019,0.391958,-0.592613,0.592870,-0.077994,-0.183867,0.782414,0.102709,-0.374456,-0.115338,0.356545,0.449034,-0.138094,0.082133,0.223831,-0.002621,0.031034,-0.458169,-0.187070,-0.075381,-0.182370,-0.284600,0.087052,-0.185121,-0.192447,-0.451047,0.872599,0.156192,-0.124858,0.254641,0.657835,0.187338,-0.005812,0.582231,-0.074706,-0.142065,-0.353506,0.098501,-0.281919,0.269845,0.193377,-0.366932,-0.029517,0.630471,-0.387326,0.186508,0.567892,-0.694775,0.046115,-0.246898,0.438318,-0.293152,-0.035909,0.259298,0.052714,-0.259582,0.095666,-0.014970,-0.176574,-0.034305,0.415115,-0.006504,-0.746009,-0.124998,0.178822,0.079624,-0.533494,0.180968,-0.034369,0.021984,0.229229,-0.271529,0.161577,0.142865,0.261467,0.269184,-0.471289,-0.144720,-0.338809,-0.020267,0.822651,-0.035348,-0.079318,0.309674,-0.215980,-0.485097,0.060650,-0.305131,-0.312478,0.066236,0.167322,0.251801,-0.298100,0.367971,-0.313517,-0.265632,-0.482972,0.196165,0.189237,-0.812718,0.155182,0.073848,-0.224526,-0.260267,-0.045839,0.120726,0.306785,-0.438248,0.463155,-0.907317,0.154998,0.532608,0.221323,-0.711661,0.463900,0.181228,-0.309058,-0.290764,-0.055870,0.539010,-0.076277,0.311070,-0.053009,0.253138,0.095411,0.340434,-0.581859,0.455330', '35287908', '6974439', '1293265', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4221462', '掠食城市', '动作', '一次灾难性事件毁灭了文明，数千年后，人类已经适应，并进化出了新的生存方式。如今，巨大的移动城市在地球上漫步，无情地吞噬着小牵引城镇。汤姆·纳茨沃西（罗伯特·席安饰），来自大牵引城市伦敦的低层，在遭遇了危险逃犯海特·肖（海拉·希尔莫饰）后，不得不开始为生存而奋战。两个截然相反，本不该相遇的人，却意外结盟，他们注定将改变未来。', '海拉·西尔玛', '克里斯蒂安·瑞沃斯', 6.3, 62214, 'tt1571234', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2543972440.jpg', 2.5, 16.4, 50.5, 24.6, 6, '0.195755,0.577300,-0.838300,0.498109,-0.092980,-0.030175,0.687665,0.275653,-0.452238,0.024030,0.300105,0.581508,-0.126165,-0.019420,0.231089,-0.127015,-0.336365,-0.376960,-0.158292,-0.183395,-0.791167,-0.524508,-0.444372,-0.674211,0.103962,-0.315212,0.552178,0.459680,-0.744654,0.202251,-0.023601,0.176694,-0.408417,0.566765,-0.049542,-0.035487,-0.062095,0.190544,-0.355162,0.088214,-0.164698,-0.177284,-0.097627,0.166614,-0.185722,0.399337,0.669081,-0.624244,-0.078319,-0.638083,0.250241,-0.269755,-0.141047,-0.138438,0.264947,-0.021591,-0.221965,0.090079,0.103938,-0.134806,0.085243,-0.177584,-0.653776,0.177633,-0.196064,0.056345,-0.395702,0.513115,0.423929,-0.090333,-0.059537,-0.406583,-0.016261,0.705732,0.637379,0.301252,-0.105058,0.123141,-0.365353,0.003779,1.151193,-0.185652,-0.715546,0.238702,-0.502470,-0.533516,-0.486496,-0.278079,-0.410943,-0.055240,0.261376,0.318708,-0.190564,0.898555,-0.730921,0.183879,-0.493197,-0.222221,0.036564,-0.341367,-0.030709,-0.532116,-0.014941,-0.114217,-0.281309,0.314368,0.014964,-0.150825,0.694285,-0.651562,0.442940,0.894343,0.577907,-0.483886,0.454091,-0.229101,0.249111,-0.424679,0.123746,0.704300,-0.144973,0.745680,0.185277,-0.013017,-0.088373,0.298718,-0.357820,0.776508', '1453067', '1294941', '1307311', '6532822');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4221515', '危险方法', '剧情', '影片《危险方法》(A Dangerous Method)原名《谈疗法》(The Talking Cure)，根据英国编剧Christopher Hampton（《赎罪》）的同名舞台剧本改编。萨宾娜·斯皮勒林（凯拉·奈特莉 Keira Knightley 饰），出身俄罗斯犹太家庭。1904年被送到苏黎世去治疗歇斯底里症，成为了精神病医生荣格（迈克尔·法斯宾德 Michael Fassbender 饰）精神分析患者中的一员。荣格发现她有受虐倾向，是一个性瘾患者，同时又有深深地自责心。而在诊治过程中，他们之间发生了秘密的、不论之爱。但荣格重视自己的声誉，想要隐藏这段感情，声称萨宾娜是一名臆想狂。而这种欺骗的行为也让荣格在理念上与恩师——精神分析学派创始人弗洛伊德（维果·莫特森 Viggo Mortensen 饰）分道扬镳。©豆瓣', '凯拉·奈特莉', '大卫·柯南伯格', 6.6, 15457, 'tt1571222', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193305014.jpg', 1.1, 9.8, 52.3, 29.3, 7.4, '0.214073,-0.110297,-0.401207,0.522109,0.188295,-0.032807,0.644369,0.070929,-0.575250,-0.582130,0.069372,0.720929,-0.153452,0.134828,0.374346,0.049869,-0.258669,-0.687905,0.132379,-0.268799,-0.475656,-0.820571,-0.151436,-0.548144,-0.188614,-0.507632,0.440784,-0.103005,-0.609743,0.306436,0.183550,0.842587,0.034322,0.117370,0.315618,-0.042554,0.289704,-0.182566,-0.430162,0.295383,0.214971,-0.101669,-0.073814,0.097018,-0.155482,0.442435,0.351191,-0.225094,-0.078620,-0.079627,0.526844,-0.213193,-0.162776,0.170803,0.272387,-0.006614,0.126273,0.375786,-0.067606,0.031931,-0.011082,-0.116018,-0.830634,-0.089951,0.041137,0.304369,-0.534401,0.399967,-0.117183,-0.159038,-0.194659,-0.079548,0.176054,0.075617,0.377894,0.438184,-0.134553,-0.056088,-0.428094,0.122972,0.656369,0.081245,-0.302766,0.301511,-0.619174,-0.360883,0.078590,-0.192960,-0.501027,-0.083812,0.228009,-0.013691,-0.267240,0.385304,-0.262681,-0.152994,-0.223431,0.053094,-0.133964,-0.052284,0.304980,-0.412633,-0.296673,-0.346567,-0.301114,-0.437188,0.205292,-0.403760,0.853108,-0.752209,0.163676,0.567877,0.035874,-0.601174,0.654524,0.240994,0.070784,-0.086755,-0.221411,0.466828,0.126932,-0.195654,-0.052888,0.206982,0.439151,0.077351,-0.181964,0.201431', '27056396', '27602116', '25