INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4230918', '结婚礼服', '剧情', '本片讲述一段感人至深的母女情：单亲妈妈高云（宋允儿 饰）带着女儿素雅（金香奇 饰）一起生活。身为婚纱设计师的她忙于事业，疏于对素雅的照顾。所以素雅一方面性格独立，但另一方面却相当不合群甚至稍显乖戾。 高云在查出绝症之后，抓紧所剩不多的时间为素雅打算。她为了弥补素雅，不仅对其有求必应 ，而且主动通宵为准备郊游的素雅学做紫菜包饭。她为了改善素雅的人际关系，为其举办生日聚会，但素雅连一位朋友也没请来。 起初，倔强的素雅并不了解高云的良苦用心。但是在觉察到高云的病情之后，她好像一下子懂事了。年幼的她不仅要装作完全不知道高云命不久矣的事情，而且还想方设法地完成高云的所有愿望……韩国首屈一指的“国民娃娃”金香奇出演本片女儿少拉这一角色。©豆瓣', '宋允儿', '权炯辰', 8.6, 93098, 'tt1754866', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2163657305.jpg', 0.2, 1, 13.1, 42, 43.6, '0.022575,0.142728,-0.486428,0.586802,-0.330816,-0.400336,0.435587,0.273622,-0.630558,-0.724674,0.092478,0.406499,0.222752,-0.204338,0.349896,0.079921,-0.340528,-0.300439,0.106525,0.131817,0.024473,-0.228605,-0.148807,0.089772,-0.392717,-0.255670,0.512036,-0.127848,0.141180,0.617379,0.127718,0.006094,0.296140,0.393997,0.002688,-0.108990,-0.191746,0.153637,-0.255434,0.203567,0.184801,-0.080945,-0.256917,0.329862,0.035983,0.583832,0.523527,0.111053,-0.194578,-0.125357,0.584484,-0.201073,0.135864,0.119020,0.173184,0.027395,0.664667,0.194427,-0.429865,0.171603,0.308337,-0.400857,-0.671835,0.147781,0.563844,0.032066,-0.473749,0.454900,-0.382277,-0.339716,0.145071,-0.369626,-0.113382,0.552096,0.252363,0.329925,-0.259991,0.153840,-0.557666,0.330744,0.541020,0.066983,0.145790,0.690302,-0.478832,-0.321395,0.165156,-0.487349,-0.448579,0.174494,-0.157795,0.103817,-0.107967,-0.064171,-0.320263,-0.063605,0.113090,-0.095759,0.058243,-0.485147,-0.088915,-0.412131,-0.088301,-0.608648,-0.332693,-0.352943,0.089555,-0.284826,0.684251,-0.940480,0.078911,0.160067,0.128781,-0.829363,0.563652,0.358537,0.250055,-0.067044,-0.133276,0.068508,-0.246949,0.014711,0.031164,0.373373,0.060211,-0.556567,-0.310561,0.299473', '1877596', '6963575', '3445516', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4233625', '新熟女时代', '剧情', '小说家吉田良夫（ユースケ・サンタマリア 饰）每每创作陷入瓶颈之时，便会偷听咖啡馆内客人的谈话，从中获取灵感，创造出一个又一个独具特色的时代女性。《倾盆大雨之女》：男人（柏原崇 饰）邂逅了一个谜样的女孩（相武紗季 饰），她终日蜷缩在男人的家中，无论多饿也要等着男人带着便当回来；《个人破产之女》：待业青年安藤（高良健吾 饰）结识了酒醉的女孩玛丽（水川あさみ 饰），他不惜一切讨玛丽的欢心，不惜帐户透支；《梦之女》：男孩（小柳友 饰）在车站看见了雍容端庄的女性（小雪 饰），她的生活却有如梦境；《平日公休之女》：失恋的哲人（塚本高史 饰）与化妆品销售员智里（優香 饰），他却始终对抛弃自己的女友无法忘怀；《无聊的女人》：被催稿逼急，吉田讲述了和自己朝夕相处的无聊的女友（長谷川京子 饰）。本片根据吉田修一的小说改编。©豆瓣', '相武纱季', '行定勋', 7.4, 6713, 'tt1649388', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2362731329.jpg', 0.6, 3.1, 34.5, 47.9, 13.8, '0.104712,0.072620,-0.351173,0.366942,-0.236522,-0.381201,0.936037,0.336369,-0.356281,-0.158505,0.347647,0.778651,-0.303745,0.294538,0.458115,0.217138,-0.168972,-0.596753,0.009093,-0.027821,-0.057839,-0.169562,-0.259574,-0.116883,-0.155982,-0.259100,0.485869,-0.213851,-0.116433,0.288704,0.217389,0.158702,-0.101436,0.475009,-0.086480,0.058172,-0.075260,0.189853,0.116364,0.044219,-0.131479,-0.444195,-0.126240,0.001651,-0.204152,0.225111,0.754381,-0.173315,-0.049274,-0.078814,0.534522,0.037988,-0.087614,-0.033446,0.092106,-0.122546,0.284676,0.039552,-0.190850,-0.041584,0.177161,0.005015,-0.517746,-0.125762,0.205539,0.148839,-0.432865,0.436989,-0.149417,-0.010608,0.190851,-0.351170,-0.097770,0.036706,0.246780,0.348986,-0.131772,-0.038424,-0.439214,0.692803,0.089036,0.028847,-0.159545,0.444330,-0.371548,-0.312758,-0.085731,-0.243237,-0.799499,-0.173919,0.318574,-0.156079,-0.164517,0.043274,-0.554622,-0.085865,-0.109009,0.026289,0.173081,-0.314552,-0.230885,-0.532000,-0.126231,-0.320842,-0.236796,0.141601,0.332449,-0.022020,0.840269,-0.744943,0.071749,0.765462,0.117209,-0.322654,0.681051,0.070442,-0.046085,-0.138355,-0.058853,0.389116,-0.088565,0.220152,-0.054363,0.460042,-0.203372,0.117710,-0.592495,0.351416', '3811356', '1908036', '1418179', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4237863', '一场风花雪月的事', '动作', '08年夏天，失踪多年的国宝——金佛，重现在韩国头号黑帮——金氏家族之手。警方在金氏次子正熙（在熙 饰）潜入深圳境内避难时，安排女警吕月月（Angelababy 饰）以全程保护正熙之名追查金佛下落，两人经历了险象环生的黑帮追杀后情愫暗生，导致月月与警察男友薛宇（黄晓明 饰）的关系变得紧张。正熙答应配合警方的行动，却在哥哥正泰的安排下，携金佛潜逃。正熙失踪的日子里，月月与薛宇逐渐重修就好，正熙突然出现将金佛归公，月月陷入在正熙和薛宇之间选择的两难境地……©豆瓣', '杨颖', '高群书', 4.5, 28951, 'tt3136490', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2069500674.jpg', 26.7, 34.6, 28.4, 6.4, 3.9, '-0.112718,-0.259273,-0.471224,0.066793,0.075342,-0.217296,0.008546,0.118247,-1.003539,-0.094776,0.503005,0.273542,-0.530593,0.000582,0.485503,-0.181159,-0.459174,-0.802212,0.034454,-0.753011,-0.173408,-0.559648,-0.046275,-0.025851,0.196820,-0.148243,0.481662,0.112592,0.425261,0.484994,-0.052546,0.250765,-0.446499,0.308633,0.474532,-0.001329,-0.055430,-0.191781,-0.515656,0.346961,-0.252982,-0.205435,-0.225266,-0.233549,0.399610,0.238551,0.720040,-0.339870,-0.210792,-0.244557,0.445615,-0.318246,-0.413310,-0.317709,0.621038,0.207159,0.204559,0.720733,-0.456033,-0.728609,0.037513,-0.468575,-0.157944,0.796481,0.074629,0.029005,-0.450506,0.272639,-0.135886,0.496724,-0.010311,-0.328723,0.251451,0.856653,0.259193,0.437845,-0.193657,0.352712,-0.062978,0.246888,0.614227,-0.197524,0.049062,-0.314622,0.327224,-0.158050,-0.318395,-0.204568,0.060335,-0.172282,0.235258,0.252881,-0.322267,0.265398,-0.043735,0.027638,-0.276950,0.169185,0.184057,-0.255753,-0.243567,-0.723508,-0.166644,-0.318295,0.055879,0.101810,0.215148,-0.069752,0.484672,-0.817272,0.314265,0.266954,0.785663,-0.508491,0.409933,-0.187222,-0.035558,-0.154112,-0.399724,0.259543,-0.248502,0.067201,0.304602,-0.029634,-0.252276,0.320849,0.073015,-0.424233', '1807966', '10765742', '1305179', '1291864');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4237879', '人在囧途', '喜剧', '大老板李成功（徐峥 饰）遇上挤奶工牛耿（王宝强 饰）之后，旅途便频出状况。被情人逼迫回长沙老家跟老婆摊牌的李成功，机场遭遇到前往长沙讨债的乌鸦嘴牛耿。牛耿人如其名，不但耿直憨厚，而且透出一股傻气。先是登机前安检一口气喝完一大罐牛奶，后来又飞机上让乘务员开窗，好不容易折腾到飞机到达长沙上空，结果让他咒得因长沙大雪飞机被迫返航。无奈挤上火车硬座车厢的李成功刚松了一口气，却又一次在人群中看到牛耿。牛耿就像李成功生命中的瘟神一样，只要他“金口一开”，便会出现如他所言的意外。由于途中的频频意外，两人从火车换乘巴士，又从巴士爬上拖拉机。尽管牛耿的乌鸦嘴让李成功吃尽苦头，但这个混身透着傻气的青年却用自己真诚与乐观感染着李成功。一路的颠簸之后，两人最终到达长沙又回到各自的生活轨迹中去，然而旅途中所遭遇的种种却影响着两人之后的生活……本片由香港资深电影人文隽担当监制。', '徐峥', '叶伟民', 7.8, 591946, 'tt1737237', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p500548437.jpg', 0.5, 2.3, 25.7, 49.8, 21.7, '0.082605,0.546928,-0.879589,0.680946,0.125487,-0.588786,0.756460,-0.016676,-0.347198,0.016880,0.193710,0.446984,-0.372714,0.286365,0.433509,-0.225030,-0.311264,-0.409945,-0.005452,-0.025720,-0.600085,-0.084028,-0.099235,0.134467,-0.117956,0.000590,0.277443,0.526691,-0.198327,0.594949,0.191372,0.007247,-0.193264,0.726286,-0.217726,0.270137,-0.176417,0.385164,0.097312,0.070684,0.307173,-0.474762,-0.220187,-0.055215,0.209444,0.329016,0.737438,-0.016620,-0.403269,0.017965,0.077046,-0.254475,-0.044167,-0.065732,0.388144,0.205886,0.086575,-0.376944,-0.047448,0.081920,-0.149963,0.237382,-0.196451,0.122380,-0.390311,-0.151247,-0.528956,0.023334,-0.141534,0.026161,0.008935,-0.464622,0.175931,0.202736,0.383726,0.526613,-0.280664,0.251583,-0.578796,0.061482,0.633613,0.209696,-0.324268,0.258498,-0.155502,-0.507660,0.239988,-0.120565,-0.287854,-0.041604,0.578917,-0.076534,-0.148128,-0.009110,-0.354770,-0.055027,-0.313909,-0.057860,-0.092816,0.021420,0.166009,-0.773308,0.282522,-0.345991,0.018451,0.308165,0.060960,-0.093258,0.244256,-0.335452,0.264962,0.273107,0.022865,-0.324443,0.385807,-0.083617,0.221800,-0.092181,0.322921,0.130745,0.015990,0.535504,0.364599,0.592320,-0.453273,-0.056501,-0.383228,0.338119', '3011051', '4832825', '1309110', '1306670');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4238950', '不当交易', '悬疑', '震惊全国的强奸幼女案，在嫌疑人被击毙后，警察厅压力重重。在青瓦台，总统关注下，警察厅长决定让毫无背景的崔哲基警长（黄正民 饰）了结此案，并许诺事成即可升迁。崔哲基找到了线人张锡邱（刘海镇 饰）。此前，他曾以竞标贿赂罪拘留了房地产大亨金会长，帮张锡邱拿到了海东大厦的所有权。所以张锡 邱也答应崔哲基找人顶包。他威逼利诱，迫使第二嫌疑人李东石认罪。而崔哲基没想到，张锡邱受到金会长挑衅后，竟派人在高尔夫球场暗杀了他，并拍下了检察官柱阳（柳承范 饰）与金会长谋面的照片。而柱阳收到照片如惊弓之鸟。他在紧盯案件过程中，意外发现了崔哲基与张锡邱的不当交易，而他也向崔哲基提出了另一个交易。于是，一场由检察官、警察、线人共同演绎的离奇戏码开始了……本片获第32届韩国电影青龙奖最佳影片、最佳导演、最佳编剧三项大奖。©豆瓣', '柳昇范', '柳昇完', 7.5, 24845, 'tt1843120', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p661034309.jpg', 0.5, 3, 34.1, 46.1, 16.3, '-0.143914,-0.030628,-0.487510,0.427395,0.145834,-0.043461,0.330233,0.466931,-0.541697,-0.016046,0.284433,0.591096,-0.382319,-0.016408,0.529913,-0.105241,-0.371729,-0.782703,-0.107427,-0.152656,-0.302139,-0.591355,0.025926,-0.257785,0.092758,0.026188,0.482884,0.029929,-0.275115,0.346355,0.594863,0.170469,-0.086869,0.381229,0.073906,0.085784,0.206160,0.031759,-0.490703,0.385230,0.111498,-0.487841,-0.042989,0.138591,0.161479,0.516444,0.474221,-0.181031,-0.212053,0.027591,0.231388,-0.508218,0.004800,0.022226,0.380653,0.074970,0.171002,0.381285,-0.281277,0.015213,0.297477,-0.173436,-0.496607,0.020358,0.036651,0.178334,-0.414549,0.324812,-0.142460,0.428467,-0.139982,-0.014822,0.080507,0.201143,0.214867,-0.136120,0.043934,0.050949,-0.305048,0.579624,0.209995,0.057735,-0.120115,-0.012249,0.068179,-0.555579,-0.196536,-0.210927,0.073864,0.186089,0.666289,-0.049953,0.096041,-0.180360,-0.402673,-0.385516,-0.252159,0.037790,-0.047969,-0.377471,-0.049050,-0.569265,0.033734,0.081042,-0.266409,0.047743,0.197007,-0.295335,0.263516,-0.561103,0.048305,0.364639,0.316054,-0.446258,0.533596,0.149932,0.002359,-0.484623,-0.081290,-0.289927,0.406542,0.637544,0.366177,-0.065096,-0.106739,-0.432901,-0.097025,-0.050605', '25723905', '21360417', '26636537', '1295547');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4241887', '花', '剧情', '昭和初年，崇尚自由的少女凛（蒼井優 饰）不愿重复母亲那为夫命是从的人生，在婚礼当天穿着礼服跑出家去；昭和中叶，凛的三个女儿各自经历不同的人生，长女薰（竹内結子 饰）与爱人经历生离死别，对亡夫久久无法忘怀。次女翠（田中麗奈 饰）是一家期刊的编辑，她一心做一名出色的女强人。小女慧（仲間由紀恵 饰）拥有幸福的小家庭，在第二个生命即将到来之际，她的生命却受到死神的威胁；21世纪之初，慧的两个女儿也品味着人生的种种：幼女佳（広末涼子 饰）拥有幸福的三口之家，乐在其中。长女奏（鈴木京香 饰）远赴东京追寻梦想，却不得不面对残酷冰冷的现实。三代女人，不同的人生，有如花开花落，周而复始……本片由著名化妆品牌资生堂赞助拍摄。©豆瓣', '苍井优', '小泉德宏', 7.5, 9583, 'tt1637681', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p617428557.jpg', 0.6, 2.8, 32.5, 46.9, 17.2, '-0.138456,0.188272,-0.421419,0.475792,0.039545,-0.206927,0.510953,0.382484,-0.324462,-0.432812,0.266180,0.790563,0.007832,0.177069,0.372180,-0.047593,0.092239,-0.642336,-0.002082,-0.005174,0.012409,-0.237501,0.230714,0.112476,-0.216028,-0.255135,0.708904,0.105665,0.077656,0.474668,0.510235,0.385718,-0.409003,0.053061,-0.207594,-0.152099,-0.067645,0.345456,-0.607996,-0.059610,-0.185774,-0.079968,-0.210973,0.208007,-0.152429,0.085063,0.760940,-0.387637,-0.168418,-0.255003,0.677103,0.179152,-0.372026,0.066907,0.054689,0.040657,-0.048295,0.258132,-0.105735,-0.052880,-0.020890,-0.147520,-0.941998,-0.249811,0.350684,0.115847,-0.420723,0.582481,-0.061020,-0.135253,0.157389,-0.118487,0.097849,0.117916,0.042538,0.555028,-0.176575,0.224186,-0.159401,0.655538,0.719351,0.048797,-0.248947,0.504478,-0.411675,-0.117607,-0.108019,-0.454554,-0.873572,0.224509,-0.055267,0.229839,-0.054356,0.121960,-0.471139,0.123056,-0.337682,-0.072852,0.542099,-0.273024,-0.133689,-0.365904,0.076488,-0.665776,-0.441565,0.146615,0.144826,-0.460461,0.716590,-0.677127,0.089606,0.328863,0.185804,-0.511616,0.701203,0.150561,0.153530,-0.382063,0.052343,0.648517,-0.255286,-0.068169,-0.281884,0.176927,-0.049958,0.361034,-0.440109,0.432744', '30279170', '26647163', '1307884', '26635323');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4246125', '追逐繁星的孩子', '动画', '在一片宁静的小山村，少女渡濑明日菜（金元寿子 配音）时常站在山顶，用父亲留给她的神秘矿石作二极管，收听着来自外面世界的美妙音乐。在一次放学途中，明日菜遭到一头怪兽的袭击，关键时刻她被俊美少年瞬（入野自由 配音）救下，纯洁的友谊在少男少女之间开始萌芽。明日菜体味着友谊的甜蜜，却不知瞬在某天悄然离开人世。新来的男老师森崎龙司（井上和彦 配音）为孩子们讲述了死国的传说，明日菜这才意识到瞬正是来自另一个世界雅戈泰的人。森崎真实身份隶属某个神秘组织，他和明日菜的心中都有想要复活的人，于是经过一波三折，他们随着瞬的弟弟心一同来到了传说中的雅戈泰。在这个绝美而凄惶的国度，他们展开了似乎永无止境的旅程……©豆瓣', '金元寿子', '新海诚', 7.4, 62098, 'tt1839494', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1957577564.jpg', 1, 5.6, 35.3, 38.6, 19.6, '0.150068,0.268236,-0.873011,0.504575,-0.279664,-0.054899,0.669715,0.425582,-0.375780,-0.225510,0.178648,0.643072,-0.215818,0.334946,0.378318,0.037611,-0.447078,-0.580307,-0.151318,-0.388096,-0.352829,-0.170004,0.066495,-0.163701,0.119814,-0.354372,0.498705,0.239297,0.023450,0.347032,-0.044913,0.140933,-0.390116,0.521441,-0.307401,-0.046918,0.123133,0.005589,-0.309927,0.186693,-0.032933,-0.186548,-0.369578,0.165114,-0.260298,0.100723,0.810118,-0.318171,-0.103226,-0.026328,0.237742,-0.104207,-0.097035,-0.085681,0.397854,-0.078206,0.009799,0.067500,-0.132795,0.016673,-0.089238,-0.275275,-0.459008,0.055305,-0.091266,0.192444,-0.304067,0.523172,0.071733,-0.058963,0.283016,-0.369656,0.300918,0.237810,0.418089,0.464176,-0.061445,0.098400,-0.280434,0.173451,0.709235,0.144463,0.007488,0.368522,-0.177531,-0.415095,-0.062680,0.065168,-0.393891,-0.039123,0.394121,0.210343,-0.212804,0.336715,-0.712871,0.063639,0.033035,-0.137136,0.030059,-0.404517,-0.468736,-0.478184,-0.126743,-0.097039,-0.104194,0.312296,0.112539,0.060757,0.994720,-0.785001,0.447422,0.658591,0.215699,-0.128801,0.622709,-0.045420,-0.074785,-0.310169,-0.159733,0.198481,0.067494,0.222768,0.196655,0.411207,-0.301848,0.343628,-0.581854,0.396146', '3811356', '5977789', '2081098', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4249355', '孤胆特工', '剧情', '住在小女孩小米（金赛纶 饰）隔壁的当铺大叔（元斌 饰）除过生意之外和邻居们从不来往，颓废的造型以及沉默的性格让人们对于他的身份有诸多怀疑。天真的小米从不理会这些传言，时常造访这位神秘邻居竟然使他俩慢慢的成为朋友。小米的妈妈牵连到黑帮的毒品抢夺之中，最终使自己和小米陷入危险之中。目睹小米和妈妈被人绑架的当铺大叔为了救出小米和妈妈，开始和黑道展开斗争。此时，警方也在着手调查这起案件，当铺大叔元泰锡的真正身份慢慢浮出水面。被摘除所有值钱器官的小米妈妈的尸体在一辆汽车的后备箱里被发现，但是，和她一起失踪的小米却依然下落不明……《旅行者》中扮演“真希”的小罗莉金赛纶和换上颓废造型的“花样美男”元斌一起演绎的韩版《这个杀手不太冷》，成为2010年韩国最卖座的电影。©豆瓣', '元斌', '李桢凡', 8.2, 195317, 'tt1527788', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p548237786.jpg', 0.3, 1.6, 17.8, 47.5, 32.8, '0.507380,-0.125316,-0.625334,0.149400,-0.188403,-0.341673,0.776797,0.143473,-0.609020,-0.393002,0.194012,0.645692,-0.191782,0.141319,0.198735,0.117090,-0.341275,-0.751207,-0.279151,-0.027067,-0.066553,-0.229293,-0.357715,0.079037,-0.156094,-0.166054,0.584719,-0.199088,-0.206209,0.627314,0.288483,0.316044,-0.319682,0.288979,-0.046377,0.100927,0.198859,-0.047611,-0.335107,0.155482,0.079695,-0.158837,0.022200,0.072479,0.084525,0.161310,0.748132,-0.312818,-0.312423,0.006048,0.100292,-0.309613,-0.285763,0.045890,0.321755,0.095520,0.381388,0.282258,-0.315361,0.078029,0.324543,0.216568,-0.597063,0.074409,0.204318,0.415226,-0.398607,0.099147,-0.143759,-0.270948,0.143527,-0.596734,0.578303,0.229445,0.140685,0.305292,-0.275294,0.097273,-0.663480,0.085307,0.652808,0.068838,0.220927,0.155521,-0.129892,-0.099953,0.103910,-0.312012,-0.542659,0.186588,0.098736,-0.102380,-0.290856,0.365546,-0.785371,0.075338,0.002770,-0.313122,0.061597,-0.268969,-0.197558,-0.555478,-0.322442,-0.514579,-0.103256,-0.263692,-0.019969,-0.166090,0.623556,-0.958016,0.308716,0.171029,0.394447,-0.379522,0.505293,-0.015758,0.033321,-0.116007,-0.309440,-0.149691,0.231614,0.343202,-0.038323,0.312534,0.028060,-0.316160,-0.387521,0.053118', '1308755', '1301022', '35030151', '3111650');
