INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4253448', '第四张画', '剧情', '男童朱云翔（毕晓海 饰）的父亲过世，生活无人照顾，来自大陆的老校工张先生（金世杰 饰）外冷内热，在朱云翔生母吴春兰（郝蕾 饰）到来前照顾了小翔一段时间。吴春兰十几年前由大陆赴台，短暂的迷梦破灭后又经历了牢狱之灾，如今栖身于风尘场所。靠摆摊维持生活的继父（戴立忍 饰）被恨意所填充，对小翔的到来颇多怨气。幸好小翔结识了当地的小混混手枪仔（纳豆 饰），手枪仔用偷来的轻骑带小翔兜风，配合手枪仔盗窃和强抢小学生之类虽然很不正当，可也给小翔枯燥的生活增添了几许刺激。如非必要，小翔很少画画，可也给父亲和手枪仔分别画了一幅，第三幅画，是关于小翔梦中的哥哥，而失踪三年的哥哥实际为继父所害。小翔的第四张画，会画下什么内容？©豆瓣', '毕晓海', '钟孟宏', 7.7, 18825, 'tt1703914', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p635775687.jpg', 0.3, 1.9, 27.5, 54.2, 16.1, '-0.124192,-0.246339,-0.185130,0.481283,-0.136518,-0.323932,0.570271,0.067891,-0.466119,-0.414480,0.008209,0.416848,-0.097457,0.464569,0.109871,-0.115986,-0.254646,-0.362319,-0.088078,-0.053946,-0.246363,-0.190057,-0.214511,0.004179,-0.271466,-0.201063,0.412290,-0.089262,0.009656,0.462657,0.032981,0.134119,-0.176461,0.222587,-0.215358,-0.124213,-0.223069,0.297413,-0.260337,-0.065454,0.173817,-0.295520,0.011069,-0.107869,0.269760,0.167954,0.853983,0.004562,-0.195882,-0.239994,0.369613,-0.057139,-0.067637,-0.225596,0.200386,0.259224,0.248147,0.027322,-0.394638,0.192247,0.074020,-0.249564,-0.297090,-0.041307,0.369761,-0.082681,-0.637223,0.605706,-0.251404,-0.034181,0.025754,-0.175135,0.444023,0.326454,0.189652,0.427626,-0.095818,0.165778,-0.360506,0.418809,0.416108,-0.145787,0.044205,0.196023,0.025208,-0.254756,0.131096,-0.129182,-0.338403,0.219829,-0.060906,-0.199325,-0.428825,0.177910,-0.552013,-0.016373,-0.140911,0.136955,0.017332,-0.385963,-0.309160,-0.483067,-0.045190,-0.605892,-0.108778,-0.056616,0.424909,-0.148470,0.538344,-0.556896,0.339682,-0.108726,0.068965,-0.222908,0.607051,0.167324,-0.058099,-0.228697,-0.019879,0.267012,0.146235,0.257977,0.074816,0.171103,0.061285,-0.291196,-0.159831,0.397396', '24839498', '1296044', '3155839', '5279593');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4258485', '活该你单身', '喜剧', '英俊潇洒的栗正（贺军翔 饰）在家姐栗影（高菲 饰）的“真爱俱乐部”担任“真爱调查员”，出面接触委托人的未婚妻或者女友，为这些多疑男人的婚姻大事把脉，栗正的这份工作做起来得心应手，同时倍感疲惫。栗影的俱乐部接待了一位新的委托人——钻石王老五萧枫（吴大维 饰），栗影芳心大动，指派弟弟再次出马，令其勾引萧枫的未婚妻菲尔（林心如 饰），好促成自己和萧枫。任心理咨询师的菲儿颇有主见，使栗正大感棋逢对手，数次接触之后，栗正竟对菲儿暗生情愫。另一方面，栗影以调查做借口介入萧枫的生活，但随着四人的了解渐渐加深，栗家姐弟发现事情并没有那么简单……©豆瓣', '贺军翔', '蔡心', 5, 12152, 'tt2374914', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p513025771.jpg', 14.8, 33.2, 42.3, 8, 1.8, '0.130982,-0.027934,-0.473264,0.548932,-0.258187,-0.054031,0.327793,0.228614,-0.623145,-0.382384,0.008122,0.446548,-0.130818,0.177901,0.277210,-0.187971,0.093326,-0.446894,0.064580,0.045831,0.024890,-0.625922,-0.151609,-0.224911,-0.111116,-0.160460,0.461917,-0.079600,-0.176090,0.370383,0.516170,0.277397,0.219328,0.215102,0.115514,-0.257866,0.076768,0.329187,-0.384660,0.028258,0.047281,0.185330,-0.069237,0.117861,0.064980,0.465541,0.311540,0.087485,-0.419870,-0.442622,0.463189,0.090106,0.256982,-0.258764,0.058569,0.310592,0.152139,0.175233,-0.216310,-0.049551,0.107277,0.064347,-0.545173,0.197179,0.299909,-0.136357,-0.354725,0.071009,-0.236682,-0.062154,-0.189261,-0.138079,0.156160,0.450259,0.130120,0.010285,0.017736,0.206638,-0.157438,0.253477,0.467844,0.242369,0.021864,0.364902,-0.269599,-0.325646,0.123046,-0.220252,-0.318896,-0.020487,-0.135221,0.278743,0.086000,0.148440,-0.292789,-0.154880,-0.130924,0.111699,0.177081,-0.533377,0.237636,-0.450209,-0.295990,-0.290126,-0.298642,-0.025157,0.069438,-0.402155,0.423586,-0.906501,-0.000350,0.277881,0.224464,-0.919921,0.477742,0.350736,-0.000730,-0.351495,-0.300996,0.143361,-0.129391,-0.258357,0.118108,0.239427,-0.025292,-0.246213,-0.277442,-0.080337', '1293265', '1949320', '1305915', '1295746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4265409', '算计：七天的死亡游戏', '惊悚', '年轻的无业者结城理久彦（藤原龙也 饰）为了工作伤尽了头脑，偶然机缘，他结识了美丽的女孩须和名祥子（绫濑遥 饰）。在对方的启发下，结城报名参加了一个时薪高达11万日元的实验。与之一同参加实验的还有祥子、岩城（武田真治 饰）、安东（北大路欣也 饰）等9人。他们被两辆白色的豪 华汽车带到位于郊外的一幢房子内，在接下来的7天里，他们将在此全封闭度过。然而高回报往往伴随着高风险，在此期间，不断有人死于非命，幸存者不仅要小心保住自己的性命，还要积极追查潜在的凶手。小小的房间内，暗影重重，危机四伏……本片根据米泽穗信的推理小说改编。©豆瓣', '藤原龙也', '中田秀夫', 5.7, 11647, 'tt1586753', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p684667814.jpg', 6, 25.4, 51.2, 13.7, 3.7, '-0.052029,0.015274,-0.695129,0.364730,0.091073,0.006531,0.566850,0.138438,-0.333554,-0.275126,0.359871,0.596383,-0.072975,0.028013,0.225618,-0.114541,-0.276653,-0.457637,-0.248983,-0.235877,-0.385840,-0.371191,-0.257861,-0.213809,-0.121148,-0.109439,0.509257,0.341998,-0.126965,0.357728,0.214416,0.355538,-0.319066,0.193476,-0.183303,-0.037619,0.073122,0.030587,-0.071645,0.317099,-0.001170,-0.454436,-0.058273,-0.127877,0.199265,0.453255,0.658074,-0.182429,-0.183458,0.128959,0.220769,-0.263278,-0.063926,-0.010332,0.276820,-0.043275,0.215875,0.354122,-0.355577,0.128723,0.117462,-0.184508,-0.719624,-0.089485,0.213382,0.086400,-0.520072,0.584940,-0.010141,-0.116856,0.121425,-0.160630,0.086013,0.358507,0.108827,0.055661,-0.256048,-0.011669,-0.450156,0.266006,0.553341,0.025374,0.057325,0.083410,-0.155660,-0.455797,-0.064144,-0.292808,-0.182388,-0.098493,0.546541,-0.090385,0.077114,-0.301740,-0.476830,-0.047460,-0.218872,-0.228568,-0.051487,-0.198390,-0.167834,-0.562289,0.316956,-0.314152,-0.219217,0.318199,0.174510,-0.351830,0.672879,-0.770156,0.145787,0.627467,0.312910,-0.439662,0.504786,-0.223649,0.344022,-0.053538,-0.171759,-0.138286,0.161056,0.453488,0.149964,0.398952,-0.081608,-0.231111,-0.516403,0.137413', '25928048', '3005387', '3811356', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4267948', '安妮·李斯特的秘密日记', '剧情', 'BBC新剧《The Secret Diaries of Miss Anne Lister》（暂译：安妮 李斯特的秘密日记）《The Secret Diaries of Miss Anne Lister》（暂译作：安妮 李斯特的秘密日记）是一部大胆并且充满热情的新电视剧，该剧由Jane English编写、James Kent执导，Maxine Peake担当主演并将在BBC2台播出。Anne Lister(1791年—1840年)是约克郡的一个地主、企业家、旅行家和日记作者。同时她还是一个女同性恋。尽管当时的社会需要她最大限度地保守这个秘密，而她则以与同性爱人同居的方式来反抗社会传统观念。Anne用一本四百万字的日记，事无巨细地记载了她的生活、爱情和情感，字里行间充满了吸引力和令人心痛的真诚。日记中相当大的一部分都是用密码记录的，最近对这部日记的解密工作让人们在惊讶之余进一步了解这位号称英国现代女同性恋第一人的她。Anne Lister那非凡的日记和她那真实却又不同寻常的生活，奠定了《The Secret Diaries of Miss Anne Lister》（安妮 李斯特的秘密日记）这部影视作品的基础。这部只有一集，时长90分钟的剧集汇集了众多闪耀的明星，包括Anna Madeley；Susan Lynch；Christine Bottomley；Gemma Jones；Dean Lennox Kelly和Tina O’Brien。与此片同步推出的纪录片由喜剧作家兼推广人的Sue Perkins向我们讲述Anne Lister的故事，并跟我们解密她的日记。BBC2台的管理员', '安娜·梅德利', '詹姆斯·肯特', 7.6, 7757, 'tt1555126', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2367402104.jpg', 0.4, 2, 32.6, 46.8, 18.2, '0.277872,-0.119321,-0.542545,0.980142,0.095643,0.080556,0.798288,-0.167419,-0.483407,-0.234680,0.045501,0.945655,-0.274585,0.237483,0.180484,0.059378,-0.372532,-0.704796,-0.223814,-0.352136,-0.183250,-0.417507,-0.450652,-0.368111,-0.092043,-0.271842,0.851035,0.124310,-0.529358,0.180694,0.246952,0.199415,-0.007065,0.291659,-0.013670,0.109836,-0.085946,-0.044194,-0.104395,0.051716,0.170071,-0.254049,-0.284729,0.197781,0.005685,0.400443,0.693322,-0.188549,-0.271749,0.259466,0.646119,-0.237306,-0.325443,-0.116014,0.034438,0.149226,0.301751,0.469044,-0.051674,0.001690,-0.215812,-0.250659,-1.292052,-0.384599,0.160176,0.230115,-0.483862,0.596106,-0.437370,-0.011869,0.006894,-0.304656,0.019558,0.170955,0.177420,0.540123,-0.139092,-0.052732,-0.260432,0.676292,0.067146,0.218474,-0.380598,0.553251,-0.288974,-0.625493,-0.396930,-0.078750,-0.607248,0.147345,0.352954,0.044384,-0.178065,0.191415,-0.805375,0.051598,0.017753,-0.431627,0.180249,-0.651190,-0.086564,-0.781166,-0.346199,-0.522804,-0.113924,-0.336399,0.449133,-0.345914,1.280630,-0.582708,0.092002,0.519307,0.090320,-0.484942,0.800625,0.297548,-0.130606,-0.224279,-0.158239,0.166536,-0.076079,0.453877,0.026858,0.408957,0.350759,-0.226946,-0.616375,0.743081', '27602116', '22265121', '2027945', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4268598', '告白', '剧情', '一所平凡的中学，1年B组即将迎来春假。不知天高地厚的学生们肆意吵闹，殊不知一场绵亘数月的风暴正向他们袭来。级任教师森口悠子（松隆子 饰）全然无视这片混乱，静静地向学生们做出最后的告白。这个单亲妈妈独自抚养着可爱的女儿（芦田爱菜 饰），然而女儿最终在游泳池中溺水身亡。警察 认定这是一起意外，森口则认定女儿死于班上两个学生之手。她不动声色地指责着犯人A和B，并宣布用自己的方式进行复仇。在此之后，森口辞去教师职务，1年B班的学生也心怀惴惴迎来了春假。新学期开始，残酷的风暴袭向了这群无知无畏的少男少女……本片根据湊かなえ的原作改编，并成为2010年电影旬报十佳影片；第34届日本电影学院奖最佳作品、最佳导演、最佳剧本和最佳剪辑4项大奖。©豆瓣', '松隆子', '中岛哲也', 8.8, 636441, 'tt1590089', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p689520756.jpg', 0.5, 1.1, 9.7, 37.5, 51.2, '0.035459,-0.220491,-0.310005,0.486154,0.031011,-0.143505,0.445072,0.024937,-0.355291,-0.413474,0.151779,0.580582,-0.131644,0.529196,0.554457,-0.197203,-0.224674,-0.958616,-0.520900,-0.063364,0.027622,-0.205205,0.049058,-0.103936,0.021184,-0.284649,0.866365,-0.070756,-0.052856,0.639133,0.639492,0.249037,-0.077605,0.073097,0.195899,-0.011384,0.251257,0.141023,-0.345203,0.355963,-0.193124,-0.384890,-0.349478,-0.060748,-0.042026,0.258727,1.071985,-0.139193,-0.134423,-0.183191,0.793410,-0.566889,-0.291588,0.307810,0.529931,0.079458,0.130360,0.068250,0.150812,0.396306,-0.100412,-0.407104,-0.562441,-0.096273,0.001869,-0.036444,-0.282034,0.459345,0.151301,0.185484,0.140103,0.029267,-0.024863,0.011262,0.291722,0.421250,-0.461294,0.008627,0.029443,0.610877,0.403624,0.095346,-0.345868,-0.037864,-0.142397,-0.421893,0.183332,-0.340284,-0.535133,0.110247,0.258677,0.206647,-0.031574,0.166532,-0.398507,-0.038063,0.006701,-0.257379,0.222952,-0.422304,-0.075192,-0.829089,0.256664,0.133648,-0.148360,-0.000334,-0.021987,-0.327861,0.852960,-0.489868,0.240469,0.452788,0.090219,-0.376747,0.634240,0.200342,0.191584,-0.295486,-0.163546,0.103496,-0.127636,0.403921,-0.012446,0.240749,-0.201394,-0.303037,-0.224578,0.218067', '5403927', '3811356', '1322847', '4135443');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4270672', '心底的逆流', '剧情', '《心底的逆流》讲述秘鲁海边一位已婚的深柜男子在保守环境和挚爱男鬼间做出艰难抉择的超现实故事。原片名“Contracorriente”直译作“回头浪”，指浪花在前后阻力中折回、反向、汇聚、重叠冲击海岸的形态，暗喻主人公米古（Cristian Mercado 饰）和桑迪亚哥（Manolo Cardona 饰）之间一波三折的禁忌之爱。米古即将为人父，但悄爱着画家桑迪亚哥溺水而死的鬼魂。为能长相厮守，他藏匿了桑迪亚哥的尸体，却给自己的生活带来不能承受之重。最终米古对这段感情的放手令桑迪亚哥的灵魂得到了救赎。本片获得2010年圣丹斯电影节的世界电影观众大奖（World Cinema Audience Award），并代表秘鲁角逐2011年奥斯卡最佳外语片奖。©豆瓣', '克里斯蒂安·梅卡多', '哈维尔·弗恩特斯-莱昂', 8.4, 8852, 'tt1368491', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1072403855.jpg', 0.3, 1.4, 16.1, 44.4, 37.8, '-0.271214,-0.261605,-0.512947,0.745003,0.125004,-0.052830,0.663256,0.009458,-0.294460,0.020266,-0.043727,0.688631,-0.388230,0.018351,0.388835,-0.160660,-0.043744,-0.697016,-0.174252,0.096605,-0.263532,-0.216057,-0.392313,-0.256797,-0.136835,-0.297151,0.644028,0.180877,-0.193052,0.365384,0.365153,0.155929,-0.141958,0.172463,-0.186250,-0.009464,-0.370417,0.218969,-0.420290,0.237322,-0.042236,-0.164399,0.018154,0.100274,0.113863,0.156069,0.826991,-0.334580,0.052775,0.082258,0.496543,-0.220033,0.002715,-0.117848,-0.244884,-0.175980,0.079247,0.239615,0.098348,-0.085918,0.313343,-0.428941,-0.576262,-0.077960,0.137511,0.114814,-0.264135,0.330455,-0.047831,0.065414,0.043549,0.053151,0.092890,0.115809,0.551896,0.486743,-0.362932,-0.147631,-0.339626,0.447529,0.607744,0.081964,-0.473269,0.184162,-0.495450,-0.601497,-0.520565,-0.143704,-0.434904,-0.007133,0.299472,0.208356,0.028536,0.362523,-0.462690,-0.277224,0.079501,-0.067029,0.135045,-0.417005,0.022721,-0.387433,-0.221179,-0.130719,0.035201,0.073616,0.002398,-0.427202,0.706831,-0.254314,0.421542,0.495412,0.414695,-0.274144,0.841293,0.135479,0.016500,-0.244545,0.043295,0.753223,-0.139852,0.162887,-0.017146,0.118192,-0.101371,0.070477,-0.444386,0.391154', '26647163', '30349667', '30162520', '1292925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4271832', '完美嫁衣', '喜剧', '性感美丽的洛昕（杨千嬅 饰）是一个小有名气的婚礼策划师，在她的妙手设计下，一桩桩独具特色的婚礼相继诞生。她见证了无数温馨浪漫的场面，然而自己的感情道路却颇多坎坷，甚至遭遇了婚礼之际未婚夫落跑的悲惨局面。种种打击让洛昕对所谓的真爱不再那么笃定。偶然机会，她重逢曾有过一夜情的男子风（林峯 饰）。由于债务等方面的原因，风被迫进入洛昕的公司“卖身还债”。二人珠联璧合，合作愉快，奉献出一场又一场的精彩婚礼策划，彼此间的感情也日益加深。当他们彼此放下心结之时，各种考验开始挡在他们的面前。洛昕的前男友Joe（葛民辉 饰）幡然回头，风也遇到一名可爱的女孩。他们的感情将何去何从……©豆瓣', '杨千嬅', '黄真真', 6.5, 41231, 'tt1756679', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p799723773.jpg', 1.8, 11.4, 54.4, 26.1, 6.2, '0.147422,0.087508,-0.692874,0.545401,-0.044458,-0.105884,0.850237,0.010693,-0.282720,-0.088964,0.305491,0.736410,-0.441904,0.476821,0.427209,-0.180948,0.018092,-0.770265,0.167187,-0.001624,-0.205094,-0.157707,-0.392185,-0.051968,-0.064641,-0.165718,0.714082,0.490802,-0.174457,0.450911,0.445941,0.058431,-0.261489,0.592967,-0.254130,-0.051336,-0.078169,0.509729,-0.528085,-0.180219,-0.090964,-0.342304,-0.290171,0.332756,-0.192120,0.297247,0.661246,-0.172934,-0.329762,0.067957,0.545146,-0.204540,0.154993,0.153320,0.205803,0.132895,0.201728,0.322652,-0.172430,-0.210125,-0.007484,-0.110816,-0.773280,0.129622,0.114380,-0.131122,-0.474314,0.606852,-0.023837,0.003810,-0.056637,-0.255900,0.120605,0.550421,0.554015,0.221153,-0.351124,0.125685,-0.351420,0.304114,0.924872,0.207637,-0.058248,0.635996,-0.305196,-0.434270,-0.173615,-0.108225,-0.311390,0.048797,0.408780,-0.151995,-0.028755,0.212306,-0.652099,-0.044497,-0.243885,0.128231,-0.010336,-0.507092,0.003051,-0.551599,-0.231579,-0.452098,-0.544262,0.203170,0.068654,-0.359467,0.746296,-0.664596,-0.019446,0.427831,0.168892,-0.537574,0.529144,0.354491,0.209988,-0.122755,-0.220094,0.256203,-0.409837,-0.122465,0.155520,0.365760,-0.007702,0.131329,-0.142672,0.467263', '30162520', '25828589', '2053515', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4271894', '非诚勿扰2', '喜剧', '《非诚勿扰2》豆瓣官方小站：http://site.douban.com/108514/在秦奋（葛优 饰）全然做好与笑笑（舒淇 饰）白头到老的准备之时，笑笑对秦奋的感情却仅仅止步于好感。在秦奋好友李香山（孙红雷 饰）和芒果（姚晨 饰）离婚典礼的启发下，秦奋与笑笑决定试婚。然而，好感毕竟不等同于爱情，共同生活期间，秦奋深沉的爱意 在笑笑那边却变成无形的压力， 两个最后只能分道扬镳。距离远了，感情似乎也就淡了，就在两人似乎已经忘记对方的时候，他们生活的轨迹又一次发生重合。老友李香山罹患重症，在他的人生告别会上，秦奋和笑笑再次相遇，在即将离世的老友点化下，笑笑似乎明白了婚姻的真谛……©豆瓣', '葛优', '冯小刚', 6.6, 315360, 'tt1810602', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p725272302.jpg', 2.4, 11.8, 50, 27.6, 8.3, '0.189614,0.136545,-0.806232,0.594158,-0.025956,-0.465588,0.978845,0.276218,-0.076584,-0.151797,0.122122,0.590855,-0.335734,0.390577,0.190203,-0.465856,-0.312510,-0.704521,-0.001963,-0.219157,-0.071167,-0.590522,-0.201378,0.191524,-0.139991,-0.075597,0.567424,0.038520,-0.293851,0.639996,0.338720,0.081648,-0.210253,0.938286,-0.016481,0.217129,0.033120,0.479295,-0.744044,-0.177661,0.312275,-0.310110,-0.206556,0.212831,0.036226,0.240423,0.681202,-0.183880,-0.427375,0.088781,0.035382,-0.081944,-0.037942,0.129900,0.199000,0.249966,0.108077,0.136531,0.006506,0.150592,-0.000942,0.010627,-0.324117,0.142549,-0.053118,0.237551,-0.434932,0.772225,0.022242,-0.221582,-0.104882,-0.690968,0.298591,0.491236,0.513379,0.421525,-0.451961,0.091192,-0.386538,0.182936,0.785668,0.370565,-0.294066,0.641992,-0.154789,-0.431104,-0.287287,0.454225,-0.148668,-0.115416,0.190690,0.201900,-0.058947,0.367273,-0.472292,-0.114685,0.194619,0.068349,-0.028182,-0.694411,0.305391,-0.603055,-0.362932,-0.640076,-0.503425,0.155014,0.189282,-0.394533,0.402289,-0.842197,0.383074,0.010443,0.344222,-0.445144,0.613536,0.497769,0.018831,-0.304290,0.092946,0.294970,-0.369005,0.180436,0.272797,0.331266,0.015652,0.134000,-0.275257,0.435072', '21348112', '1308755', '34973399', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4275444', '有一天', '剧情', '女孩欣颖（谢欣颖 饰）和妈妈一起住在高雄旗津，并在往来高雄和金门的客轮上当福利社店员。欣颖的生活和其他居民一样平静安恬，唯一的不同就是他总是梦见一个男孩对她大声呼喊，但是她听不清他在喊什么，也看不清他的脸，欣颖一直以为那是她已故的爸爸。然而有一天，她在渡轮上遇见了一名服兵役的男孩阿聪（张书豪 饰），阿聪竟然声称自己是她未来的恋人，而且此刻他俩正身处一场可以改变彼此命运的梦中。欣颖觉得这荒唐极了，然而接连发生的一连串事件却让她渐渐相信了男孩的话。随着梦中的爱恋渐渐清晰起来，冥冥中的命运也像渡轮般慢慢朝他们逼近……本片是“高雄城市映像”系列电影之一，曾入围柏林影展青年导演论坛单元。©豆瓣', '谢欣颖', '侯季然', 6.6, 7325, 'tt1616203', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p665503472.jpg', 1.8, 12.8, 49.2, 28.3, 7.9, '0.251095,-0.047034,-0.715436,0.575211,0.130318,-0.170854,1.036799,0.046081,-0.458713,-0.078738,0.278211,0.841914,-0.227850,0.355119,0.080463,0.132684,-0.234345,-0.750959,-0.070706,-0.029156,-0.022521,-0.450615,-0.121352,0.072029,-0.089776,-0.131023,0.642686,0.052084,-0.179003,0.346556,0.374570,-0.035733,-0.211535,0.601636,-0.293374,0.155455,-0.060856,0.164893,-0.181323,-0.156909,0.065675,-0.180087,-0.358661,0.137588,-0.167213,0.267841,0.486063,-0.285566,-0.361483,0.270894,0.239077,-0.184285,-0.184179,0.130358,0.220637,0.058138,0.221565,-0.051779,-0.102507,-0.210537,-0.000315,0.229252,-0.423198,0.211013,0.120333,0.527533,-0.306267,0.309390,0.002161,-0.102270,0.190910,-0.346158,0.221723,0.192247,0.219764,0.382915,-0.395397,-0.011483,-0.590507,0.222790,0.833725,0.228406,-0.278159,0.556892,-0.289144,-0.343153,-0.296033,-0.035513,-0.694528,0.158971,0.087139,-0.115510,-0.349483,0.143695,-0.282407,0.193286,-0.023150,-0.356174,-0.169468,-0.430177,-0.099788,-0.387089,-0.097098,-0.649055,-0.200365,0.081981,-0.108865,-0.279828,0.631337,-0.966884,0.229443,0.554060,0.300333,-0.187087,0.631572,0.292498,-0.129058,-0.152925,0.043933,0.262062,-0.115523,0.122353,0.063230,0.347078,0.044940,0.156877,-0.273236,0.546235', '1308755', '1296534', '1296370', '1309080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4280102', '能召回前世的布米叔叔', '剧情', '布米叔叔（Thanapat Saisaymar 饰）得了急性肾衰竭，因此回到乡里，边静养边等待死神来临。在乡下，他每天安静的吃饭、纳凉、看家人劳作，一个清凉的夏夜，布米叔叔、侄子和妻妹在院子里吃饭闲聊，布米叔叔去世很久的妻子竟然出现了，和他们诉说近况和多年思念，稍后，布  米叔叔失踪很久的儿子也出现了，变成了一只红眼黑毛猩猩，却没有人受到惊吓。阴阳相隔的几个人平静地拉着家常，平静的果园，平静的微风，蜜蜂每日平静的劳作，发生的一切事情都那么自然，每个风景都早在那里了，每个故事都像一个梦……本片获戛纳电影节金棕榈大奖。©豆瓣', '萨那帕卡·塞塞玛', '阿彼察邦·韦拉斯哈古', 7.3, 14062, 'tt1588895', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2493056005.jpg', 2.7, 7.8, 31, 38.2, 20.4, '0.155547,-0.284017,-0.696193,0.203277,-0.103723,-0.307405,0.850889,0.408405,-0.398235,-0.343271,0.102994,0.586727,-0.382934,0.443419,-0.022882,0.070384,-0.447595,-0.594005,-0.129839,0.068725,0.009564,-0.075372,-0.121788,-0.092613,0.123357,-0.244130,-0.182350,-0.065894,0.388723,0.703070,-0.031052,-0.200523,-0.277364,0.460405,-0.285929,0.204552,0.051171,0.336564,-0.169327,0.118810,-0.066839,-0.120564,-0.176411,-0.315123,0.289031,0.336857,0.612947,-0.098817,-0.431519,0.233730,0.151054,-0.434314,0.083856,0.134044,0.586624,-0.066768,0.255226,-0.008178,-0.300257,-0.036183,-0.238328,-0.050374,-0.446519,0.010971,-0.075675,0.734952,-0.437036,0.792328,0.195015,-0.119177,-0.124205,-0.408607,0.527505,0.247362,-0.176227,0.569583,-0.165373,0.105618,-0.652658,0.135427,0.785834,-0.111936,-0.176587,0.328667,-0.130923,-0.241025,0.100443,-0.125482,-0.596028,0.066822,-0.015737,-0.158701,-0.307780,0.278841,-0.506799,0.095298,0.095500,-0.386190,-0.100083,-0.361489,-0.256178,-0.470796,0.165578,-0.383307,-0.466716,0.177462,0.047213,-0.142278,0.575720,-0.412349,0.774875,0.191119,0.263887,-0.082653,0.633154,-0.072650,0.157234,-0.097484,0.114410,0.164594,-0.054166,0.342795,0.445231,0.334145,-0.256722,0.283768,-0.725437,0.331152', '26687241', '1292211', '1296534', '6753096');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4280770', '看见恶魔', '剧情', '供职于国情局的青年警员金秀贤（李秉宪 饰）即将和心爱的女孩珠燕走入婚姻的殿堂，但是在一个飘雪之夜，独自驱车夜归的珠燕被人残忍杀害并分尸。秀贤痛不欲生，他找到四个主要嫌疑人的照片，开始独立追查凶手。经过一番调查，终于将目标锁定在为某学院包车的中年大叔张京哲（崔岷植 饰）的身上。张生活坎坷，性格极度扭曲，他经常袭击夜归的女子，并将她们无情杀害。秀贤找到张的据点，对其进行残酷的惩罚，却最终手下留情。侥幸活命的张反而由此激发所有的兽性，一场野兽对野兽的修罗之战渐次激烈……本片也部分镜头过于血腥而成为韩国首部被限制上映的商业影片。©豆瓣', '李秉宪', '金知云', 7.9, 89542, 'tt1588170', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p555826078.jpg', 1, 3, 23.4, 46.5, 26.2, '0.006626,0.040238,-0.350839,0.602916,-0.070513,-0.024723,0.959535,-0.082372,-0.253307,-0.223446,0.517286,0.602522,-0.153753,0.364883,0.354008,-0.245989,-0.058403,-0.609326,-0.353207,-0.000692,-0.309995,-0.352655,-0.102987,-0.114592,0.059122,-0.216793,0.977842,0.355865,-0.578021,0.188835,0.322964,0.195501,-0.388270,0.435760,0.007284,-0.290033,-0.100157,-0.157324,-0.348217,0.052457,-0.102541,-0.509898,-0.167458,0.234532,-0.363988,0.334862,0.941215,-0.305344,-0.289316,-0.202818,0.546664,-0.514649,-0.166533,0.227872,0.313307,-0.007570,0.254428,0.273306,-0.195155,0.053695,0.003260,-0.144622,-0.813050,0.065806,0.231374,-0.020884,-0.236299,0.438507,-0.038753,0.178809,0.116485,-0.176296,0.082050,0.143788,0.455433,0.290327,-0.155357,0.071040,-0.187188,0.163443,0.565163,-0.164826,-0.195861,0.135558,0.006744,-0.580721,0.012464,-0.290907,-0.264364,0.026516,0.520835,0.042518,-0.297848,0.216618,-0.656941,-0.062564,-0.419129,-0.211023,-0.129537,-0.298196,-0.043496,-0.818552,-0.230848,-0.213128,-0.081553,0.189057,0.100488,-0.289673,0.593310,-0.552173,0.218595,0.523966,0.224900,-0.605693,0.304491,0.184164,0.170359,-0.155952,-0.206204,0.509212,0.516371,0.202357,-0.016038,0.257585,-0.232130,0.003562,-0.180756,0.406113', '10467125', '24879819', '26759820', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4282653', '向着炮火', '战争', '本片根据朝鲜战争中的真人真事演绎而来。1950年八月，朝鲜人民军攻克汉城，一路南下。韩国方面征召学生入伍，组成“学徒义勇军”顽强抵抗。学徒兵吴张帆（崔胜贤/T.O.P 饰）所在的部队被人民军连连击退，为补充兵员，数十名学徒兵加入战斗序列，其中包括父母被人民军杀害的不良 学生甲赵（权相宇 饰），这些学徒兵组成了一支71人的小队，由吴张帆担任队长率队防卫浦项，而韩国部队则转移至釜山之前最后的防线——洛东江。孤零零的学徒兵小队在一所废弃的学校中布防，他们将要面对的，是朝鲜人民军精锐的766部队，人民军少校朴武郎（车胜元 饰）为完成最高领袖的任务，下令向距离釜山更近的浦项进攻……©豆瓣', '权相宇', '李宰汉', 6.9, 8749, 'tt1587729', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p775971530.jpg', 2.5, 9, 43.4, 32, 13.1, '0.215910,-0.295584,-0.380391,0.900198,0.150751,0.052129,0.381109,-0.159217,-0.439654,-0.408768,0.128688,0.187557,0.592429,0.049954,0.455697,-0.526984,-0.129507,-0.759724,-0.505119,-0.341671,-0.422193,-0.350308,-0.117923,-0.333664,-0.145530,-0.223022,1.005146,0.341275,-0.154973,0.433145,0.335623,0.520305,-0.028297,0.214605,0.297974,0.125622,0.299810,-0.661108,-0.117493,0.237506,-0.502476,-0.263538,-0.152512,-0.279662,0.222634,0.441705,1.064608,-0.036152,0.385281,-0.321318,-0.044950,-0.238645,0.110067,-0.122017,0.838661,0.420398,-0.021330,-0.227677,0.193864,0.432243,-0.389005,-0.390678,-0.575095,-0.222237,0.370713,-0.267633,-0.627472,0.359995,-0.112350,0.530396,0.376998,-0.314577,-0.015398,0.670536,0.073704,0.269868,-0.191914,0.010506,-0.405579,0.354001,0.640404,-0.162935,-0.136853,-0.691580,-0.077048,-0.606585,0.021474,-0.333357,-0.049192,0.213441,-0.149871,-0.081651,0.843336,-0.129171,-0.710056,-0.090699,-0.105394,-0.332980,-0.007219,-0.151293,0.152510,-0.917562,0.547289,-0.022315,-0.049337,0.475375,-0.009447,0.398145,0.793688,-0.591899,-0.241370,0.210881,0.470341,-0.540134,0.400384,-0.093108,0.464033,-0.247789,0.278240,0.131897,0.228794,0.534339,0.384731,0.380956,-0.509335,-0.552083,-0.042152,0.046868', '5403927', '2369613', '3266509', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4284085', '团圆', '剧情', '台湾老兵刘燕生（凌峰 饰）到上海，寻找自己失散几十年的妻子乔玉娥（卢燕 饰）和从没见过面的儿子。乔玉娥当年和刘燕生失散三年后，和陆善民（徐才根 饰）组成家庭并生有两个女儿。刘燕生了解到乔玉娥和丈夫情感不好，就希望能带乔玉娥和他一起到台湾生活，并承诺拿出自己一生的积蓄，来补偿乔玉娥的丈夫和这个家庭的子女。但立刻引发这个家庭的剧烈震荡，激烈的争吵使几十年的亲人团聚变成了彼此的再次伤害，直到陆善民脑溢血生命垂危……乔玉娥无法抗拒分离的命运再次降临，只好在几十年前相同的上海码头，再次送走自己深爱的刘燕生……©豆瓣', '卢燕', '王全安', 7.9, 15385, 'tt1587878', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2128713173.jpg', 0.5, 2, 22.3, 51.9, 23.3, '0.049497,-0.105909,-0.974181,0.652657,-0.149202,-0.534948,0.776211,0.005395,-0.501536,-0.145204,0.068658,0.995429,0.031025,0.638632,0.047903,-0.106741,-0.056559,-1.146242,0.089067,-0.075613,-0.499618,-0.385477,-0.041186,-0.154393,-0.222105,-0.279095,0.629005,0.022082,0.036983,0.592452,0.192447,0.301378,-0.188842,0.466898,-0.553039,0.358918,-0.227095,0.539653,-0.814323,0.065540,0.136738,-0.044083,0.080278,0.203900,-0.001680,0.415957,0.640226,-0.115171,-0.264646,-0.110291,0.405176,-0.021821,-0.244111,0.183125,0.354264,0.262984,0.362814,0.188860,-0.378269,-0.187052,-0.039038,0.113108,-0.597571,-0.062047,0.220243,-0.096980,-0.840367,0.422862,0.193955,-0.234067,0.153271,-0.251794,0.293480,0.695150,-0.018787,0.624066,-0.705255,0.067674,-0.311588,0.366536,1.007755,-0.365257,-0.392917,0.311713,-0.227644,-0.187044,-0.040434,-0.398101,-0.673612,-0.070805,0.062913,0.373018,-0.283305,0.324422,-0.677082,-0.021072,-0.182886,-0.128583,0.573440,-0.524497,0.208580,-0.480385,-0.542075,-0.663363,-0.402807,0.374823,0.160134,-0.356033,0.710637,-0.711950,0.514271,0.447789,0.473078,-0.849846,0.652656,0.353287,0.274084,-0.336413,0.313256,0.386982,-0.113358,0.183223,0.052290,-0.038751,-0.003159,0.521228,-0.535396,0.413767', '1294713', '30345227', '4861627', '1299584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4286017', '速度与激情5', '动作', '蛰伏2年之后，多米尼克（范•迪塞尔 Vin Diesel饰）与布莱恩（保罗•沃克 Paul Walker 饰）再度联手把火车中的神秘豪车盗走，遭到了警察和黑帮分子的火线追杀。布莱恩和米亚（乔丹娜•布鲁斯特 Jordana Brewster 饰）到里约寻找援兵，并与多米会和。为了寻找多米等人的下落，FBI王牌探员卢克（“岩石”道恩•强森 Dwayne Johnson饰）挺身而出，组成精英部队，追查来到里约。他雇佣了丧夫的美丽女警艾莲娜（埃尔莎•帕塔奇 Elsa Pataky 饰），一同寻找多米。与此同时，里约的地头蛇也对这些不速之客开火。三股势力开始相互缠斗。期间，因米亚怀孕，布莱恩决定陪她一起逃亡，所以多米只得依靠昔日老友探寻新车的秘密。在罗曼、韩等人的帮助下，多米终于找到了这辆车的秘密——芯片，并由此揭开了其中隐藏的一个不可告人的计划……©豆瓣', '范·迪塞尔', '林诣彬', 8.5, 349555, 'tt1596343', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p898634801.jpg', 0.2, 1, 13.9, 45.4, 39.4, '0.307008,-0.334466,-0.599979,0.441958,0.144328,-0.122187,0.637262,-0.036077,-0.545171,-0.209178,0.080233,0.531856,-0.219300,0.158312,0.565891,-0.112271,-0.674307,-0.698515,0.135443,-0.369059,-0.315196,-0.529054,-0.463649,-0.300836,0.053431,-0.225507,0.503312,0.110170,0.077768,0.680224,0.015010,0.436941,-0.417154,0.380068,0.066557,-0.159845,0.312310,-0.348827,-0.156179,0.378310,-0.165387,-0.223983,0.180898,-0.019948,0.276225,0.566609,0.601003,-0.381415,0.435763,-0.138355,-0.384575,-0.247714,0.271966,-0.095134,0.295899,-0.067103,0.289314,0.399031,-0.310161,0.008466,0.032503,-0.094427,-0.473736,0.034686,0.167776,0.018281,-0.603675,0.195975,-0.180070,-0.232910,0.198104,-0.184152,0.232128,0.497126,0.174525,-0.033323,0.020165,-0.017443,-0.515393,-0.318534,0.260004,-0.161731,0.297440,-0.072857,0.233845,-0.298205,-0.141817,0.102306,-0.245962,-0.267546,0.413367,0.120280,0.126875,0.042184,-0.902559,0.007449,-0.597368,0.033249,0.054193,-0.438876,-0.075297,-0.798428,0.032144,-0.079316,0.038803,0.375190,0.000842,0.012728,0.483579,-0.450448,0.170479,0.469848,0.615696,-0.400558,0.465151,-0.175021,0.190185,-0.377114,0.040763,0.134573,0.090479,0.319772,0.022397,0.227935,0.067250,-0.241636,-0.279780,0.092037', '1297659', '20274039', '3008263', '1309056');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4290704', '月代头布丁', '喜剧', '33岁的游佐弘子（友阪理惠 饰）是一名终日奔波忙碌的职场女性，因为向往工作，两年前她和丈夫离婚，独自拉扯着6岁的儿子友也，日夜不得闲暇。某天，母子二人遭遇了一名武士打扮的奇怪男子，他自称中岛安兵卫（錦戸亮 饰），是效力于德川家族的幕臣，不知因何种原因穿越到了现代社会。因无可依靠，安兵卫借住在游佐母子家中。古现代的价值观由此发生激烈碰撞，也闹出不少的笑话。大男子主义的安兵卫渐渐放下武士的高贵身段，担当起家庭妇男的角色，并且和母子的关系日渐融洽，也最终在这个陌生的社会取得了可喜的成就……本片根据荒木源的同名原作改编。©豆瓣', '锦户亮', '中村义洋', 7.7, 26381, 'tt1595354', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p845905043.jpg', 0.3, 2.1, 28.3, 49.7, 19.6, '0.239071,-0.027311,-0.626855,0.355248,-0.209565,-0.177438,0.607126,0.169673,-0.544970,-0.579731,0.321164,0.670158,-0.061511,0.409051,0.503122,-0.302764,-0.001952,-0.586214,-0.106658,-0.079996,-0.093679,-0.342368,-0.409288,-0.121919,-0.413239,-0.450604,0.716671,-0.067812,-0.165267,0.407533,0.349987,0.300444,-0.293441,0.067327,-0.148665,-0.008865,-0.089357,0.301885,-0.319577,-0.105686,-0.193125,-0.406807,-0.099751,-0.011921,-0.000214,0.443469,0.679974,-0.147749,-0.321440,-0.181310,0.779292,0.188611,-0.348998,0.099981,0.638484,0.039922,0.019650,0.217917,-0.075356,-0.182097,-0.169104,0.000263,-0.605069,0.128168,0.379875,0.040538,-0.512535,0.716651,-0.049250,-0.481994,0.025467,-0.148936,0.072091,0.675361,0.148118,0.476490,-0.145106,0.163475,-0.425087,0.305994,0.669049,0.219777,-0.379112,0.372369,-0.521124,-0.431695,-0.267349,-0.603520,-0.654108,-0.336511,0.099727,0.000249,-0.128716,0.302710,-0.402190,0.210607,0.014373,0.135874,0.292361,-0.203902,-0.000520,-0.376017,-0.174210,-0.846555,-0.336801,0.176518,0.200295,-0.239244,0.877122,-0.773220,-0.068843,0.382048,0.077418,-0.602738,0.678759,0.136565,0.261251,-0.112099,-0.104929,0.299281,0.001458,0.043557,-0.066476,0.293872,-0.199698,0.091203,-0.352160,0.192883', '26354526', '6963575', '24284209', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4291275', '到阜阳六百里', '剧情', '心高气傲的年轻女子曹俐（秦海璐饰）本想一探外面的世界，一路从深圳打拼到光鲜亮丽的大都市上海。背井离乡的曹俐，努力逃离她失败的婚姻和生意经营的失败。然而她却仍生活在社会的最底层。她与中年妇女谢琴（唐群饰）合租在两平米不到的简陋小房内，每日疲于奔命地打工挣钱。同乡狗哥骗来一辆旧巴士，邀曹俐入伙推销阜阳返乡车票，哄骗二十八个阿姨乘车返乡。虽然离上海老家只有六百里，但她依旧不敢踏上回家的路。本部仅用18天就拍摄完成、低成本制作的影片《到阜阳六百里》，用一个冥冥中自有注定的安排，结合了一连串看似善意的骗局，讲述了一段欺骗中常存温暖的回家故事。本片不仅入围2011年第48届台湾电影金马奖最佳剧情片提名，荣获第48届台湾电影金马奖最佳原著剧本、最佳女配角大奖，导演邓勇星更凭借此片获得第14届上海国际电影节亚洲新人奖的最佳导演，主演秦海璐荣获第18届北京大学生电影节和第13届华语电影传媒大奖双料最佳女主角大奖。', '秦海璐', '邓勇星', 7.7, 22212, 'tt1733271', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1240205536.jpg', 0.3, 2.2, 26.8, 52.4, 18.2, '-0.228985,-0.001560,-0.619048,0.601675,0.400552,-0.260099,0.238697,0.152335,-0.128907,-0.048260,0.261644,0.734398,-0.092641,0.143122,0.448325,-0.154353,-0.276557,-0.343029,-0.142490,-0.282258,0.180157,-0.054455,-0.265023,0.248489,-0.130684,-0.046462,0.798657,0.164839,-0.227918,0.395262,0.570284,-0.210246,-0.247902,0.053227,-0.231155,0.101469,0.307039,0.321698,-0.579125,0.564279,-0.152931,-0.247599,-0.345267,-0.301980,0.225084,0.261829,0.654989,0.163736,0.088201,0.370515,0.780145,-0.226949,-0.594390,-0.346416,0.196862,0.069616,0.301745,0.273705,-0.048388,0.361755,-0.160566,-0.351336,-0.651811,0.048136,0.204274,-0.039013,-0.583500,0.260721,-0.045287,0.166603,-0.131393,-0.284764,0.106413,0.172945,0.263047,0.199071,0.018670,0.289144,-0.370935,0.747373,0.526838,0.084542,-0.334719,0.337314,0.017153,-0.490688,0.137339,-0.467433,-0.515689,0.188950,0.136442,-0.271841,0.021832,-0.221005,-0.418912,-0.095413,-0.085913,-0.377703,0.214165,-0.147654,0.101581,-0.898402,0.090946,-0.143207,0.059967,-0.159869,0.258020,-0.347572,0.520024,-0.340120,0.195737,0.571268,0.203710,-0.376950,0.821176,0.277783,0.146427,-0.390581,-0.092052,0.181480,-0.310556,0.437502,-0.195072,0.213859,-0.345551,-0.341436,-0.410289,0.444360', 