INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4296852', '神秘博士：圣诞入侵', '科幻', '本集讲述博士和泰勒回到当代的伦敦渡过圣诞节。然而，外星人希克拉库斯（Sycorax）却在这时入侵地球。最终，因重生过后昏倒的博士及时醒来，击退入侵者。在英国，这集有980万人收看，并取得正面的评价。这是扮演第十任博士的大卫·田纳特首次出演整部《神秘博士》剧集。此前，他在《背水一战》的最后一幕出场。同时，这是《神秘博士》首部的圣诞特辑。自此以后，BBC One每年均会制作一部圣诞版的《神秘博士》剧集。', '大卫·田纳特', '詹姆斯·哈维斯', 8.9, 7351, 'tt0562994', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2508912731.jpg', 0.3, 0.6, 9.5, 30.7, 59, '-0.096094,0.054285,-0.685568,0.390390,0.434645,-0.246779,0.420607,-0.199880,-0.143811,-0.569728,0.376851,0.736166,-0.407840,0.014260,0.462872,-0.047618,-0.318070,-0.228888,-0.047985,-0.155373,0.126253,-0.228844,-0.391381,0.249814,0.265385,-0.521393,0.743235,-0.071692,-0.377552,0.774143,0.210648,0.557240,-0.030593,0.398344,0.219628,0.214283,0.408089,-0.147733,-0.539114,0.622583,0.008703,-0.094032,-0.112529,-0.084592,-0.101117,0.227056,0.626821,-0.527616,-0.205787,0.302144,0.737745,-0.469409,-0.333399,-0.041780,0.459802,0.231371,0.112710,0.303147,0.103308,0.098402,-0.215351,-0.130062,-0.751423,-0.206753,0.063622,0.266436,-0.209038,0.369135,-0.233444,0.255933,0.191925,-0.309196,0.205196,0.346062,0.405958,0.331785,0.228788,0.230225,-0.260736,0.329031,0.553669,-0.133284,-0.310076,0.145265,0.114941,-0.431543,0.193806,-0.180527,-0.432468,0.706091,0.229126,0.104610,0.115363,0.278687,-0.333901,-0.012522,-0.392752,-0.269844,0.245202,-0.228298,-0.266845,-1.206268,-0.130151,0.284551,0.093251,-0.225576,-0.038251,-0.587084,0.520609,-0.727096,0.333959,0.297689,0.200512,0.095726,0.562011,0.349697,0.072771,-0.292066,-0.206350,0.383244,0.079079,0.355697,-0.302818,0.182459,0.266193,-0.399534,-0.490397,0.330646', '2369613', '24751811', '26275494', '34961898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4296866', '神秘博士：逃跑新娘', '剧情', '失去了罗斯的博士正在心灰意冷，而正在举行婚礼的多娜却被突然传送到塔迪斯里。博士带坏脾气的多娜返回地球，却被一群外星机器人追杀，塔迪斯上演了一场公路飚车。后来博士发现多娜身上带有异常含量的Huon粒子，而该粒子来源于上一代宇宙霸主。而博士的母星加利弗雷在宇宙中崛起时，已经消灭了所有的Huon粒子。最终博士揭开了一个藏于地球40亿年的秘密。', '大卫·田纳特', '尤洛斯·林', 9, 7121, 'tt0827573', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2326413901.jpg', 0.2, 0.7, 8.5, 32, 58.6, '0.193533,0.368970,-0.790861,0.524929,-0.106235,-0.504820,0.923073,0.085405,-0.126912,-0.321785,0.176124,0.780358,-0.352405,-0.013069,0.483750,0.339946,-0.256021,-0.315895,0.012061,-0.282900,-0.551115,-0.533501,-0.297946,-0.018666,0.152056,-0.636420,0.854515,0.066007,-0.149814,0.464795,-0.138427,0.385201,-0.192178,0.716244,-0.261500,0.054390,0.268436,-0.339865,-0.034803,0.269148,0.036973,-0.032092,0.116460,0.155751,-0.386398,0.087353,0.870542,-0.414398,0.487512,-0.234526,0.296502,-0.568314,-0.193071,-0.045448,0.731279,0.078606,-0.317847,0.050712,0.054832,-0.104410,0.426376,0.123097,-0.561630,-0.259030,-0.313131,0.242757,-0.397580,0.139717,-0.040508,-0.044587,-0.045937,-0.156340,0.502868,0.365822,0.148964,0.411841,-0.115715,-0.107996,-0.497277,-0.121622,0.438015,-0.372061,-0.395492,0.361312,0.013354,-0.436683,-0.102346,-0.145430,-0.472074,-0.127037,0.429284,0.263164,-0.160283,0.658314,-0.899339,0.165088,-0.656900,-0.433496,0.216751,-0.346806,-0.459180,-0.885334,-0.380260,-0.092170,-0.016075,0.106192,0.138909,0.014217,0.612081,-0.824259,0.347491,0.506504,0.125192,-0.173519,0.378958,-0.125381,0.025320,-0.231444,-0.044121,0.088905,-0.177671,0.938286,-0.089475,0.391759,0.024272,-0.114277,-0.408452,0.487534', '3735015', '1307897', '1306809', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4296871', '神秘博士：诅咒之旅', '剧情', '博士的塔迪斯被追尾，肇事船居然是泰坦尼克号。原来一家外星旅游公司仿照泰坦尼克号制造了一艘巨大的泰坦尼克号宇宙飞船。但是飞船却连续遭遇不幸：防护罩被毁，装上陨石群，船长死去，服务机器人嗜杀成性……。', '大卫·田纳特', 'James Strong', 9, 6216, 'tt1061123', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2508912578.jpg', 0.3, 0.4, 8.7, 31.1, 59.5, '0.147386,0.030899,-0.555813,0.237437,0.125863,-0.076258,0.997471,-0.157095,-0.068954,0.024981,0.627120,0.781689,-0.134194,-0.246128,-0.037852,0.526816,-0.274108,0.320058,-0.118468,0.117611,-0.607471,-0.278397,-0.252469,-0.244227,0.409667,-0.149532,0.749909,0.107107,-0.005514,0.182199,-0.103747,0.396275,-0.278171,0.379960,-0.438159,0.164538,0.308412,-0.162938,0.408136,0.081718,-0.950120,-0.259246,0.931192,-0.051975,-0.180345,0.229487,0.861930,0.007759,-0.172629,-0.558807,0.145662,-0.463244,0.354237,-0.266092,0.498289,0.420917,-0.339945,-0.293408,-0.036741,-0.425498,0.657791,0.104561,-0.606107,-0.141399,-0.348347,-0.660202,-0.210379,0.071755,-0.437820,0.184927,-0.327739,0.030819,0.640616,-0.110558,0.889765,0.175030,-0.254353,0.698927,-0.827052,0.243878,0.624047,-0.152029,-0.785841,0.550287,0.103044,-0.082948,-0.098995,-0.628015,-0.328079,0.127086,0.636411,-0.498518,-0.281363,0.263993,-0.885827,0.169062,-1.055887,-0.371125,-0.489325,-0.034965,-0.526275,-0.891087,0.404584,0.073443,-0.078822,0.183256,-0.194148,0.008267,0.550234,-0.164340,0.072270,0.825451,0.204426,-0.113254,0.730585,-0.190342,-0.398832,-0.007504,0.312412,-0.038660,0.093163,0.401452,-0.101107,0.054420,0.194755,-0.230177,-0.141224,0.334555', '10466639', '24879819', '21619567', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4297254', '黑色闪电', '动作', '影片中被称作“黑色闪电”的车是一辆伏尔加（Volga）跑车，是当年苏联GAZ公司的顶级汽车品牌，曾经作为俄罗斯官员御驾。莫斯科大学的学生Dima（吉里格力·多布金 Grigoriy Dobrygin 饰）的梦想就是拥有一辆好车，然后和漂亮的女同学Nastya（叶卡捷琳 娜·维柯娃 Ekaterina Vilkova 饰）约会。生日那天，他收到了父亲的生日礼物—一辆老牌的“Volga21”。偶然的机会下，他发现这是一辆会飞的车子。他的生活从此不再平静，依靠这辆会飞的车子，他赚到了前所未有多的钱。他在拥堵的莫斯科城上空盘旋。但好景不长，灾难从天而降，Dima不得不肩负起重担。从此，莫斯科上空出现了“黑色闪电”，一位随时向市民伸出援手的无所畏惧的英雄......©豆瓣', '吉里格力·多布金', 'Dmitriy Kiselev', 6.4, 6686, 'tt1569364', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p507758495.jpg', 3, 12, 54.5, 25.1, 5.5, '0.257018,0.122677,-0.568699,0.652654,0.053842,-0.139523,0.866501,0.198773,-0.264109,0.001078,0.517698,0.996054,0.035464,0.258037,0.434655,0.282049,-0.289073,-0.549704,0.180918,-0.027865,-0.307795,-0.255034,-0.231743,-0.105246,0.219878,-0.133234,0.614619,0.261806,0.247422,0.544433,0.304791,0.177685,-0.053763,0.369552,-0.506086,-0.154356,0.005868,0.091569,0.022906,0.153319,-0.428162,-0.277192,0.153477,0.057480,0.057454,0.058240,0.539394,-0.038988,0.015972,-0.138570,0.213823,-0.195928,0.250040,-0.348869,0.199518,0.135739,0.169508,-0.171888,-0.031323,-0.224452,-0.176360,-0.210311,-0.307104,0.049333,-0.404503,-0.132795,-0.814318,0.497993,-0.265957,-0.176922,0.161187,-0.471828,0.208483,0.105893,-0.108371,0.240626,-0.247494,0.282423,-0.642224,0.159752,0.673070,0.070358,-0.328330,0.542087,-0.370455,-0.225892,-0.219042,-0.303893,-0.569667,-0.165723,0.578808,-0.235304,0.002034,0.066469,-0.530515,-0.113258,-0.399437,-0.356668,0.039048,-0.049619,-0.284654,-0.354591,0.296532,-0.394678,-0.060693,0.359322,-0.003503,-0.008409,0.646634,-0.794957,0.277593,0.423053,0.551122,-0.283679,0.841099,-0.445638,0.011931,-0.103516,-0.042633,0.209324,-0.051211,0.390067,-0.188531,0.170535,-0.139304,-0.291886,-0.136677,0.639771', '3055049', '30162520', '1302384', '1292207');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4300640', '奶奶强盗团', '剧情', '抽烟喝酒的三个另类老奶奶亭子（罗文熙 饰）、英姬（金秀美 饰）和申子（金惠玉 饰）都来自拮据的贫寒家庭，她们家家都有本难念的经。支撑她们活下去的唯一希望就是攒钱去夏威夷旅行。为去夏威夷她们省吃俭用甚至定期去超市盗窃，终于在8年后攒够了837万韩元的旅费。就在她们按照旅行社的要求去银行存钱的时候，被两名银行强盗把钱打劫一空。三人立誓要追回存款，一次偶然的机会她们发现其中一名劫匪俊锡（林昌正 饰）的藏身之处，却被告知钱被另一名劫匪私吞。亭子忍无可忍决定效法俊锡抢劫银行。英姬和申子无奈同意后，她们让俊锡担任她们的教练。每天的体能训练，让她们苦不堪言。三个老奶奶的强盗之路笑料百出、困难重重。她们能否抢劫成功，去夏威夷旅行的夙愿能否实现呢……©豆瓣', '金惠玉', '姜孝镇', 7.7, 21028, 'tt1832533', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p486302575.jpg', 0.3, 2.4, 28.8, 48.8, 19.7, '-0.096488,-0.048734,-0.415274,0.195489,-0.220752,-0.564681,0.395552,-0.008931,-0.174271,-0.281580,0.049096,0.493404,0.211758,0.174866,0.299809,-0.158563,-0.183007,-0.330878,-0.083328,-0.234849,-0.351131,-0.209795,0.099343,-0.125387,-0.241885,0.070843,0.271266,0.102512,0.085605,0.475755,0.288374,0.151271,-0.144142,0.176833,-0.216698,-0.008206,0.031350,0.014823,-0.223825,0.087320,-0.155309,0.040509,-0.362253,-0.064327,0.427949,0.264986,0.539710,0.187410,-0.011542,0.021165,0.085578,0.064968,-0.020343,0.356440,0.070187,-0.025455,0.271797,0.160858,-0.382977,0.066641,0.160359,-0.079862,-0.703885,-0.037756,0.019222,-0.168959,-0.669899,0.352486,0.053815,-0.066761,0.067884,-0.485776,0.080590,0.545975,0.177516,0.217285,-0.197097,-0.060502,-0.779892,0.505358,0.596213,-0.077913,0.259090,0.238060,0.072817,-0.286522,0.178294,-0.166211,-0.233511,0.095961,0.418920,-0.155603,-0.220030,-0.375193,-0.619412,-0.193009,-0.168955,-0.262435,0.094408,-0.294217,-0.046903,-0.643777,0.245237,-0.029512,-0.351857,0.460480,0.361467,-0.150094,0.647987,-0.329689,0.136116,0.818185,0.427331,-0.754309,0.715615,-0.110532,0.229890,-0.119826,-0.120756,-0.212792,0.322714,0.606516,0.179092,0.216103,-0.142962,-0.075889,-0.084758,0.088503', '1293908', '5973984', '1303989', '6030611');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301043', '传染病', '剧情', '影片讲述了一种新型致命病毒在几天之内席卷全球的故事。贝丝（格温妮丝·帕特洛 Gwyneth Paltrow 饰）从香港出差回明尼阿波利斯的家后突发疾病死亡，丈夫托马斯 （马特·达蒙 Matt Damon 饰）协助Dr. Erin Mears （凯特·温斯莱特 Kate Winslet 饰）调查真相。可怕的是同样病症的患者在世界范围内大规模出现，病毒在不停蔓延。阴谋论记者阿伦（裘德·洛 Jude Law 饰）趁机散布对政府和医疗机构不利的舆论。Dr. Leonora Orantes （玛丽昂·歌迪亚 Marion Cotillard 饰）被派往香港调查病因，但却被本土医生（黄经汉 Chin Han 饰）扣留作为交换疫苗的人质。在Dr. Ellis Cheever （劳伦斯·菲什伯恩 Laurence Fishburne 饰）和年轻医生Ally Hextall（詹妮弗·艾莉 Jennifer Ehle 饰）的努力下，终于研制出治疗病毒的疫苗，事件终于得以平静。 值得一提的是本片还有港星何超仪和徐天佑的卖力出演。', '玛丽昂·歌迪亚', '史蒂文·索德伯格', 7.1, 142284, 'tt1598778', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1213203384.jpg', 0.9, 6.6, 42.9, 36.9, 12.7, '-0.155861,0.071013,-0.357120,0.356963,0.168963,0.161318,0.574433,0.120707,-0.520235,-0.300036,0.125948,0.452396,-0.359593,0.052260,0.217602,0.021473,-0.345970,-0.523319,-0.009299,0.040468,-0.495158,-0.435903,-0.450028,-0.496521,0.089412,-0.537496,0.117217,0.098879,-0.394180,0.273041,0.271806,0.972571,-0.287939,0.397935,0.150730,-0.201005,0.192396,-0.379195,-0.504051,0.483681,0.619192,-0.334859,-0.051176,0.059809,0.160088,0.401631,0.646199,-0.144938,0.074449,-0.049563,0.481141,-0.165340,0.182050,0.051357,0.405673,0.161262,0.022384,0.191356,-0.251561,0.003448,0.130745,-0.037531,-0.568666,-0.023272,0.109727,0.384584,-0.492980,0.314589,-0.296171,0.106401,0.038891,-0.135919,0.303244,0.351516,0.211460,0.261875,-0.094935,0.284646,-0.373277,0.152666,0.207411,-0.092480,-0.328311,0.256503,-0.286790,-0.549823,-0.224949,0.031199,-0.377247,0.067344,0.446827,-0.064717,-0.065631,0.293422,-0.310507,-0.363017,-0.489100,-0.452899,-0.047582,0.154819,-0.026383,-0.992628,-0.124637,-0.168173,-0.182274,-0.040157,0.101478,-0.074751,0.531130,-0.525823,0.238551,0.450986,0.038718,-0.628463,0.195798,-0.117907,0.175988,-0.197485,-0.206890,0.391007,0.207026,0.342915,0.229734,0.413088,0.031264,-0.222857,-0.186868,0.231523', '6517421', '1306809', '2369613', '25995508');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301056', '新年前夜', '喜剧', '随着璀璨的太阳落下，新年前夜的幕布缓缓铺开，在这本该充满着希望与温馨的一夜里，却仍有一群人各自身陷烦恼。时代广场表演秀主持人摩根（希拉里·斯万克 Hilary Swank 饰）正在紧张地做最后排演；朵伊（莎拉·杰茜卡·帕克 Sarah Jessica Parker 饰）正在与非要和男友过除夕的女儿海莉（阿比盖尔·布蕾斯琳 Abigail Breslin 饰）闹别扭；漫画家兰迪（阿什顿·库彻 Ashton Kutcher 饰）还沉浸在被前女友甩了的懊恼中，除夕只会让他更烦躁；而可怜的哈里斯（罗伯特·德尼罗 Robert De Niro 饰）已经到了癌症晚期，只希望看最后一次时代广场的新年落球仪式……他们和众多被生活困扰的纽约人一样，在自己的小位置上忙碌，却来不及睁开眼睛看看，新年的恩泽已悄悄降临……©豆瓣', '阿什顿·库彻', '盖瑞·马歇尔', 6.5, 10226, 'tt1598822', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1273197404.jpg', 2.2, 12.1, 52.5, 25.1, 8, '0.184615,-0.012118,-0.835761,0.384901,0.105519,-0.497624,1.037136,0.364191,-0.187857,-0.083468,0.253113,0.646780,-0.687692,0.435428,0.455314,0.203970,-0.573160,-0.863219,-0.014230,-0.057851,-0.159058,-0.356985,-0.155485,-0.135911,0.074577,-0.226598,0.308258,0.059846,0.249212,0.480927,0.429935,0.068934,-0.073083,0.705094,-0.201713,0.058273,0.001079,0.008945,-0.139859,-0.033788,0.174987,-0.307982,-0.313184,0.190479,0.152703,0.307250,0.760115,-0.400059,0.154847,0.043229,0.255109,-0.143425,0.070616,0.277707,0.221262,0.019940,0.224314,-0.170241,-0.155754,-0.036834,0.031716,-0.092970,-0.627035,0.448204,-0.075764,0.382682,-0.482037,0.667434,-0.067139,0.069194,0.267501,-0.282974,0.249718,0.377159,0.058869,0.505904,-0.163167,-0.106976,-0.288871,0.295847,0.409136,0.162697,-0.157701,0.503915,-0.283523,-0.131637,0.007776,0.116184,-0.587353,-0.265104,0.499203,0.081365,-0.069759,0.265894,-0.472522,0.071276,-0.212617,-0.502789,-0.128981,-0.327827,-0.172098,-0.619365,0.084299,-0.378710,-0.394050,0.182076,0.088577,-0.166081,0.428187,-0.612038,0.456271,0.437014,0.247333,0.074116,0.634863,0.144610,0.101420,-0.038991,-0.328413,0.232211,-0.233905,0.367716,0.330294,0.474783,-0.190672,-0.027205,-0.569892,0.640024', '21348112', '1301582', '1309172', '1301464');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301181', '特种部队2：全面反击', '动作', '在公爵（钱宁·塔图姆 Channing Tatum 饰）的率领下，特种部队给恐怖组织“眼镜蛇”以沉重的打击。虽然眼镜蛇指挥官等中心人物落网，但白幽灵（李秉宪 饰）等组织骨干依然逍遥法外，时刻准备向特种部队和全世界展开反扑。在干净利落解决某中东国家的核危机后，特种部队突然遭 到来自美国政府的惨烈打击，公爵等队员英勇殉职，只有拦路虎（道恩·强森 Dwayne Johnson 饰）、杰伊小姐（阿德琳妮·帕里奇 Adrianne Palicki 饰）和弗林（D·J·科特罗纳 D.J. Cotrona 饰）三人侥幸逃生。原来眼镜蛇早已渗透到美国高层，他们藉此抹黑特种部队，栽赃重要成员之一的蛇眼，其目的是为了找出并解救被囚禁的指挥官。名义上已经“死亡”的拦路虎三人，必须想尽各种办法阻止眼镜蛇的邪恶计划，为死去的战友和特种部队正名……©豆瓣', '道恩·强森', '朱浩伟', 6.6, 103411, 'tt1583421', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1811974432.jpg', 1.8, 11, 51.6, 27.3, 8.3, '-0.075888,-0.237084,-0.482527,0.511288,0.135417,-0.237925,0.634556,-0.042271,-0.468014,-0.173276,0.594190,0.446959,0.212303,-0.223082,0.445824,-0.260099,-0.516170,-0.744297,-0.225195,-0.093870,-0.222952,-0.534405,-0.448107,-0.368745,0.254384,-0.424311,0.721501,0.148629,-0.070611,0.438132,0.381566,0.648388,-0.295948,0.247161,0.192431,-0.327003,0.280738,-0.416169,-0.526361,0.084933,-0.043095,-0.161555,-0.014499,0.178287,0.144237,0.420384,0.383053,-0.585894,0.122105,-0.263063,-0.047769,-0.713038,0.056607,0.095954,0.404061,-0.239493,0.154052,0.243022,0.195152,0.022969,-0.043427,-0.022075,-1.092674,-0.130396,0.383355,0.115896,-0.476882,0.377837,-0.333507,0.333838,0.404489,-0.198583,0.208094,0.428787,0.343683,0.233543,-0.128672,0.351587,-0.464050,-0.029801,0.436962,-0.296780,-0.153459,-0.481138,0.093803,-0.290505,0.141723,-0.282835,0.066114,-0.073285,0.379578,-0.038089,0.137456,0.121664,-0.530280,-0.205214,-0.371838,-0.397577,-0.036013,-0.465312,-0.006955,-0.635421,0.101353,0.035186,-0.024696,0.483038,0.151794,0.058315,0.540823,-0.551429,0.088351,0.383560,0.192209,-0.538232,0.118493,-0.059960,0.215580,-0.261133,-0.190053,0.094516,0.393330,0.412656,0.242849,0.114578,-0.000279,-0.374290,-0.206588,-0.131864', '27073234', '26678784', '2