INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301215', '孕期完全指导', '剧情', '减肥教练朱尔斯（卡梅隆·迪亚茨 Cameron Diaz 饰）和搭档伊万（马修·莫里森 Matthew Morrison）的孩子比结婚戒指来的要更早一些。经营婴儿用品商店的温蒂（伊丽莎白·班克斯 Elizabeth Banks 饰）和她年轻的岳母同时有了身孕，但她发现本该充满幸福的怀胎十月似乎并没有想象中的那么美好。摄影师霍莉（詹妮弗·洛佩兹 Jennifer Lopez 饰）决定领养一个孩子，可在此之前，她需要的是一桩房子和一份工作，并且，她的丈夫对于成为一名合格的父亲感到压力很大。洛熙（安娜·肯德里克 Anna Kendrick 饰）和马克（切斯·克劳福 Chace Crawford 饰）经营着各自的餐车，在竞争中擦出了火花，意外的怀孕让洛熙开始正视与马克的这段露水情缘，而随之而来的失去更让她开始思考作为一个母亲的责任和义务。五对情侣五个故事，在并行的时空中又有着暗中的交错，这些在职场上春风得意的女人们，面对着腹中幼小的生命，会发生怎样有趣又感人的故事呢？', '卡梅隆·迪亚兹', '柯克·琼斯', 6.4, 6972, 'tt1586265', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1569333495.jpg', 1.7, 12.1, 58.2, 22.8, 5.2, '0.249198,-0.135598,-0.677063,0.511403,-0.238018,-0.324675,1.126379,0.156905,-0.574035,-0.304483,0.129292,0.840668,-0.153814,0.284144,0.228229,-0.029138,-0.207764,-0.640645,0.086636,-0.016234,-0.308112,-0.635787,-0.263772,-0.125520,-0.185381,-0.270588,0.599208,-0.026103,0.162894,0.444483,0.337983,0.181299,0.231460,0.392399,-0.148317,0.097485,0.070035,0.215386,-0.141738,0.161895,0.260558,0.007845,-0.270235,0.255258,0.049444,0.311850,0.592549,-0.145134,-0.152512,-0.145145,0.461961,-0.061797,0.180493,0.158171,0.110519,0.006772,0.211582,0.214364,-0.264039,-0.050070,0.139789,-0.112718,-0.801126,0.145765,0.201418,0.264339,-0.783745,0.396127,-0.165196,-0.081970,0.368096,-0.225803,0.014818,0.595056,0.106233,0.500877,-0.383322,0.019470,-0.548778,0.088669,0.576637,0.103250,-0.169621,0.477492,-0.425727,-0.334552,-0.181769,-0.049801,-0.724522,0.002318,0.252106,0.175035,-0.070573,0.391662,-0.538683,0.078940,-0.191271,-0.176593,-0.069380,-0.564770,0.031691,-0.546372,-0.065813,-0.628663,-0.449811,0.016140,0.262243,-0.343725,0.860237,-0.896986,0.225396,0.426933,0.168966,-0.486528,0.499044,0.346578,0.322585,-0.329268,-0.163803,0.282213,-0.142587,-0.170813,-0.010448,0.448208,0.1