INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301224', '沉睡魔咒', '奇幻', '在宁静祥和的摩尔王国，广袤的大森林中，动物与精灵和谐相处，无忧无虑。那一年，天真无邪的小仙女玛琳菲森（伊莎贝尔·莫洛伊 Isobelle Molloy 饰）邂逅了人类小男孩斯特凡（迈克尔·希金斯 Michael Higgins 饰）。他们两小无猜，成为亲密无间的好朋友， 更在万物的守护下坠入爱河。但是随着年龄的增长，斯特凡（沙尔托·科普雷 Sharlto Copley 饰）褪去了往日的纯真，被人类的贪欲所吸引。而玛琳菲森（安吉丽娜·朱莉 Angelina Jolie 饰）则成长为法术强大的仙女。愚蠢的人类向摩尔王国开战，斯特凡为了成为王位继承者，残忍地割下了玛琳菲森的翅膀。肉体的痛苦和心灵的创伤，让玛琳菲森变成了满怀仇恨的冷酷魔女，为了复仇她给斯特凡的女儿爱洛公主（艾丽·范宁 Elle Fanning 饰）施下了沉睡魔咒……©豆瓣', '安吉丽娜·朱莉', '罗伯特·斯特罗姆伯格', 7.4, 303232, 'tt1587310', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2185343341.jpg', 0.8, 4.9, 36.8, 40.7, 16.8, '0.016354,0.243868,-0.382151,0.695496,-0.316861,-0.205006,1.017852,0.226017,-0.208829,0.061364,0.126062,0.574765,-0.187408,0.197458,0.266945,0.142207,-0.314111,-0.560936,-0.265890,-0.007397,-0.119309,-0.313440,-0.457365,-0.151387,0.053765,-0.661424,0.755415,0.145805,-0.071360,0.324263,0.120512,0.243004,-0.178561,0.226450,-0.247088,-0.006055,-0.094233,0.027601,-0.261635,0.063428,-0.177206,0.096545,0.152593,0.158754,-0.188870,0.083432,0.699760,-0.634391,0.135904,-0.537794,0.448560,-0.215181,0.136102,0.201585,0.132786,-0.125750,0.070267,-0.111027,-0.046921,-0.235272,0.187225,-0.269424,-0.854718,0.214613,0.112680,0.083188,-0.487354,0.568248,0.204234,-0.148467,0.357377,-0.093129,-0.002475,0.316944,0.419628,0.664143,-0.248857,0.227701,-0.387136,-0.021578,0.481128,0.176062,-0.520923,0.261037,-0.682566,-0.644792,-0.151825,-0.403731,-0.550166,-0.281553,0.601983,-0.015558,0.022176,0.881168,-0.757651,-0.266191,-0.369438,-0.018321,-0.060746,-0.660497,-0.265343,-0.402538,-0.165102,-0.531564,-0.227494,0.001423,0.374067,-0.343712,1.040445,-0.815892,0.444334,0.506527,0.471463,-0.330144,0.425640,-0.090040,0.022467,-0.226418,-0.099027,0.902414,-0.050047,0.249029,0.295682,0.275042,-0.188077,0.520645,-0.500922,0.806403', '10746430', '26348103', '10533913', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301268', '通往仙境', '剧情', '巴黎，美国男人（本·阿弗莱克 Ben Affleck 饰）邂逅了单亲妈妈法国女人（欧嘉·柯瑞兰寇 Olga Kurylenko 饰），他带着她还有她的女儿一起来到美国生活。美国，美国男人和法国女人幸福生活着，虽然还没有结婚，但她的女儿已渐渐把他当成父亲。不过很快，女儿厌倦了异国他乡的生活，而法国女人的签证也过期了，母女两人只能回巴黎。牧师（哈维尔·巴登 Javier Bardem 饰）宣扬着上帝与爱。美国，美国男人和青梅竹马的美国女人（瑞秋·麦克亚当斯 Rachel McAdams 饰）意外重逢，重燃爱火。巴黎，女儿跟她的父亲住在了一起，法国女人找不到工作，开始厌倦巴黎，于是收拾行李来到美国，找到美国男人，准备跟他结婚。但一切似乎并没有那么简单。©豆瓣', '本·阿弗莱克', '泰伦斯·马力克', 6.6, 7258, 'tt1595656', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1901380666.jpg', 4.2, 14.8, 39.5, 28.2, 13.3, '0.194531,-0.240025,-0.930515,0.436798,-0.284678,-0.534855,0.657813,0.172030,-0.470509,-0.085069,-0.283671,0.918434,0.215392,0.533876,0.315557,0.384994,-0.776933,-0.870234,0.290990,-0.229560,-0.130858,-0.472744,0.015007,-0.426432,-0.197136,-0.073430,0.521379,-0.164504,0.353090,0.420714,0.276450,-0.037237,-0.038012,0.811858,-0.495157,0.079995,0.052470,0.197381,-0.686822,0.454314,0.388361,0.061340,-0.128478,0.164936,0.073407,0.136373,0.428033,0.075953,0.189544,-0.433163,0.164603,-0.077808,-0.181298,0.106290,0.002883,-0.232412,0.521831,0.193786,0.023797,-0.369719,0.360243,-0.180118,0.159477,0.479552,-0.094656,-0.026100,-0.619467,0.464933,-0.400677,0.209323,0.128681,-0.500460,0.387345,0.289138,0.205490,0.240411,-0.191336,0.059003,-0.690207,0.471876,0.649545,-0.002642,0.001702,0.408907,-0.124059,-0.258739,0.145996,-0.182589,-0.735076,0.194714,-0.079054,-0.222585,-0.365652,0.089255,-0.571724,0.066632,-0.125291,-0.141916,0.106735,-0.654749,0.177099,-0.550494,-0.222776,-0.570801,-0.537255,0.050899,0.132140,0.068535,0.529283,-0.780233,0.290083,0.727377,0.744866,-0.761637,0.773666,-0.007056,0.098757,-0.448266,0.029191,0.506156,-0.423272,0.047806,0.181707,0.221808,0.019978,0.236945,-0.139333,0.524675', '1857175', '26718282', '1308637', '1294039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301274', '灵魂冲浪人', '剧情', '影片只用了40天便拍摄完成，全片使用35mm的胶片摄制。影片改编自2004年出版的传记文学《灵魂冲浪：一个关于信念、家庭和重新站上冲浪板的真实故事》。成长在夏威夷考艾岛的贝瑟尼·汉密尔顿（安娜索菲亚·罗伯 AnnaSophia Robb 饰）是一个天生的冲浪天才，从小就展示出了在冲浪方面的过人的才华。她与好友埃兰娜（洛琳·尼科尔森 Lorraine Nicholson 饰）一起参加了全国的冲浪比赛，并且获得了不俗的成绩。但在她13岁那一年的一个早晨，在她在冲浪的时候一条14英尺长的虎鲨袭击了她，咬下了她的左臂。一瞬间，她的生活和未来都被冲垮了。就在所有人都在准备为她另谋出路的时候，她决定用自己残缺的身体重返冲浪的赛场。在好朋友汤姆、切瑞和萨拉的帮助下，她用自己惊人的毅力重新起立，站在了冲浪板和浪头之上。©豆瓣', '安娜索菲亚·罗伯', '肖恩·麦克纳马拉', 8.2, 20252, 'tt1596346', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p842406558.jpg', 0.2, 1.3, 18.7, 48.3, 31.6, '0.245871,-0.068780,-0.796393,0.766941,-0.113349,-0.205631,0.655486,0.205143,-0.194243,0.056040,0.387304,1.002271,-0.293889,0.289957,0.261133,0.035027,-0.313933,-0.923851,-0.003651,-0.068920,-0.487187,-0.436572,-0.424766,-0.125030,0.062017,-0.566936,0.669492,-0.125178,-0.112871,0.449323,0.066174,-0.217143,0.292017,0.458846,-0.464375,0.018060,-0.003935,-0.004379,0.147234,0.410807,0.055153,-0.461436,-0.159056,0.185922,-0.008940,0.343681,0.837748,-0.290079,-0.051057,0.167065,0.274764,-0.354646,-0.001931,0.093389,0.201268,-0.121684,0.053343,0.147357,-0.213751,0.052443,0.060665,-0.220479,-0.865036,-0.237560,-0.057700,-0.042193,-0.914455,0.836208,-0.236847,-0.079359,-0.034278,-0.493889,-0.025640,0.299763,-0.046904,0.335907,-0.290229,-0.100012,-0.480874,0.495168,0.643578,0.082330,-0.339652,0.374585,-0.202522,-0.484685,-0.477327,-0.197938,-0.476069,-0.202189,0.528843,0.027329,-0.322451,0.012280,-0.768127,0.126648,-0.129958,-0.439457,-0.092832,-0.483724,-0.167184,-0.580188,-0.199347,-0.447469,-0.250246,-0.069871,0.019453,-0.465367,1.080211,-0.877143,0.171247,0.630992,0.187343,-0.251291,0.891842,-0.137629,0.125859,-0.001347,0.057087,0.101004,-0.128089,0.355772,0.235254,0.719691,0.055724,0.148906,-0.637859,0.930126', '30162520', '1870681', '130