INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301278', '特工争风', '喜剧', '导演McG靠拍摄音乐录影带和电视广告片起家，曾经执导过电影《终结者2018》，以拍摄电影《霹雳娇娃》出名。Tuck（汤姆·哈迪 Tom Hardy 饰）和FDR Foster（克里斯·派恩 Chris Pine 饰）是美国中情局的顶尖探员，两人是生死与共的好拍档、好朋友。两人各自身怀绝技，任何任务遇到他们都会迎刃而解。可这两个好朋友却有一个共同的硬伤——都是单身。后来两人分别使用交友网站找到了自己心仪的对象，并认定对方就是可以厮守终身的人。造化弄人，两人竟然爱上同一个姑娘——事业有成的女强人Lauren（瑞茜·威瑟斯彭 Reese Witherspoon 饰）。 为了赢得美人芳心，两个昔日好友大打出手，各自使出独门看家本领，更不惜出动中情局的特技武器。而Lauren也因他们各自拥独树一格的特有魅力陷入两难，究竟谁才会成为她的真命天子呢?©豆瓣', '瑞茜·威瑟斯彭', '约瑟夫·麦克金提·尼彻', 6.6, 32146, 'tt1596350', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1541592719.jpg', 1.6, 10.8, 52.1, 28.4, 7.2, '0.134057,-0.395266,-0.454172,0.622676,0.002545,-0.178656,0.490989,-0.050733,-0.419246,-0.367890,0.224669,0.923302,-0.179453,0.071053,0.101561,-0.042393,-0.164430,-0.939585,-0.021481,-0.018694,-0.143178,-0.255263,-0.482650,-0.154025,-0.076308,-0.033926,0.660695,-0.193886,-0.129051,0.208328,0.738256,-0.041541,-0.170970,0.156213,-0.241474,0.068572,-0.020512,-0.017506,-0.583262,0.249715,-0.081829,0.070540,-0.146830,0.077307,0.026424,0.147359,0.492002,0.012125,-0.053849,0.014719,0.268375,-0.171477,-0.048312,-0.018169,0.096921,-0.207149,0.579681,0.182378,0.134259,0.103005,0.010051,0.202460,-1.011470,0.175878,0.301708,-0.176205,-0.321491,0.227132,-0.095407,-0.225037,-0.040908,-0.195725,0.138115,0.266740,0.420749,0.009147,-0.026016,-0.077029,-0.517226,0.292201,0.722997,0.092395,-0.175019,0.403448,-0.035712,-0.545065,-0.267889,-0.437506,-0.427249,0.196760,0.177541,0.058999,0.293403,0.023342,-0.672083,0.038167,-0.073943,0.125222,0.199036,-0.614855,0.186566,-0.827742,-0.220969,-0.349765,-0.419390,0.082681,0.124467,-0.342739,0.976394,-0.851061,-0.074035,0.357669,0.061455,-0.755112,0.799309,0.305767,0.071972,-0.274192,-0.297924,0.149667,0.115784,-0.024826,0.027990,0.043849,0.029130,0.042637,-0.321176,0.177641', '27602116', '26