INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301285', '藏身之所', '动作', '传奇间谍托宾·福斯特（泽尔·华盛顿 Denzel Washington 饰）曾经是CIA训练出的最顶尖的谍报工作者，也是CIA历史上最大的叛徒。因为他把很多秘密情报卖给了外国的谍报结构，给美国造成的损失难以估计。而CIA也派出了大量的人力和物力来追踪他，只是一无所获。在隐匿了十几年之后，福斯特因为被追杀，不得已进入大使馆，从而浮出水面，回到了众人的视线里。马特·威斯顿（瑞恩·雷诺兹 Ryan Reynolds 饰）作为开普敦“安全屋负责人”的一名新人感到百无聊赖。福斯特正在被CIA送到自己的安全屋中，威斯顿已经做好全然的准备来迎接这个“贵客”。但是刚刚到达这个安全屋，一群雇佣兵就从天而降，他们是来追杀福斯特的。在护卫人员全部被杀之后，威斯顿不得不带着福斯特逃走。在东躲西藏的过程中，两人化敌为友，最后威斯顿可以证明自己的实力吗？福斯特又会面对怎样的命运？', '丹泽尔·华盛顿', '丹尼尔·伊斯皮诺萨', 7, 25147, 'tt1599348', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1562010884.jpg', 0.4, 4.7, 49.4, 37.4, 8.1, '0.379352,0.170529,-0.644454,0.560762,-0.275699,-0.487851,0.780659,0.103859,-0.671624,-0.372237,0.275320,0.918080,0.036832,-0.076420,0.180190,0.052748,-0.430922,-0.611969,-0.145821,-0.616876,-0.585218,-0.515346,-0.374682,-0.131237,0.043173,-0.238411,0.406075,0.117603,-0.210115,0.209958,0.282142,0.440008,-0.006662,0.511416,-0.344724,0.166294,0.252688,-0.439216,-0.172094,0.577788,0.001907,-0.304536,-0.214545,0.412906,0.132530,0.217542,0.467752,-0.064773,-0.104613,0.065416,0.108424,-0.604424,-0.065368,0.164313,0.342668,-0.037566,0.063386,0.120461,-0.351606,0.300045,-0.065479,-0.031391,-1.023491,-0.013497,-0.032364,0.146615,-0.783930,0.269495,-0.166484,-0.189342,0.101124,-0.272313,0.246836,0.708352,0.224361,0.236981,-0.026648,0.007876,-0.648804,0.078207,0.481656,-0.197200,-0.063283,0.114509,-0.010342,-0.454064,0.069187,-0.267623,-0.127000,-0.246291,0.434367,0.178394,-0.097927,0.165553,-0.580645,-0.081234,-0.466615,-0.540815,-0.135129,-0.427356,-0.104259,-0.859777,-0.187908,-0.521767,-0.297887,0.165286,0.053201,-0.061740,0.528857,-0.802793,0.295897,0.730251,0.214223,-0.209920,0.275289,-0.220994,0.241807,0.063865,0.037032,0.026365,0.473216,0.675810,0.145594,0.174099,0.011103,-0.484148,-0.399707,0.126017', '1793491', '130