INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301613', '明星之恋', '喜剧', '令从小到大都普通到不能再普通的女生洁西卡（丹妮拉·坎贝尔 Danielle Campbell 饰）难以想象的是，那个令诸多少女尖叫和倾慕好莱坞少女杀手克里斯多弗（斯特林·克耐特 Sterling Knight 饰）此刻正坐在自己的身边。更让洁西卡激动不已的是，他们刚刚结束了一场充满了浪漫和柔情的美好旅程，而两人之后的关系会怎样发展？对此洁西卡的内心充满了期望和憧憬。然而，当洁西卡得知克里斯多弗竟然对他们两人的关系矢口否认的时候，一切美好的想象都停止了，单纯的她陷入了无尽的悲伤和猜疑中去，甚至开始怀疑曾经经历的美好只是她的幻想。克里斯多弗为什么要这么做？其中究竟有着怎样的隐情？洁西卡决定问个水落石出。©豆瓣', '斯特林·奈特', 'Michael Grossman', 6.2, 5872, 'tt1579247', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p501450925.jpg', 3.6, 16.2, 55.2, 17.9, 7, '0.402305,0.087629,-0.869285,0.459625,0.094358,-0.166217,1.007192,-0.124772,-0.414301,-0.255241,-0.028340,0.574468,-0.452342,0.255598,0.332067,0.042334,-0.566637,-0.977704,-0.067787,-0.193413,-0.338634,-0.457160,-0.111492,-0.097587,-0.030781,-0.221551,0.603287,0.201419,-0.114289,0.471138,0.380641,0.507771,0.100642,0.732550,0.195417,0.055082,0.123968,0.403926,-0.281635,-0.075966,0.474657,-0.168132,-0.299868,0.599683,-0.046410,0.235458,0.537977,-0.290783,-0.001182,0.147720,0.199279,-0.148291,0.076423,0.122417,-0.001306,-0.317998,0.002403,0.151198,-0.139176,-0.196476,0.144663,0.173759,-0.859656,0.055224,0.302538,0.262461,-0.353124,0.232708,0.054561,-0.133451,0.334253,-0.133191,0.127799,0.237816,0.440857,0.466764,-0.084230,-0.100389,-0.477583,0.119945,0.879955,0.220503,-0.126707,0.409832,-0.464929,-0.400038,-0.227476,-0.084488,-0.643750,0.131323,0.086257,0.249851,-0.098272,0.490858,-0.566993,-0.160241,-0.309427,-0.073729,-0.199169,-0.735220,-0.175149,-0.397250,-0.270394,-0.671016,-0.298973,0.053995,0.007852,-0.382002,0.745948,-0.905657,0.194726,0.275357,0.297054,-0.401070,0.551811,0.158030,0.001081,-0.161907,-0.219154,0.550470,-0.184494,-0.219476,-0.011184,0.425436,0.149145,0.066625,-0.434116,0.479435', '1308755', '4275444', '1301022', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301659', '危险藏匿', '剧情', '影片讲述了汤姆·哈迪饰演的一名前罪犯，想洗心革面重新生活，于是成为了一名酒吧调酒师。不过这家酒吧同样也是当地黑帮接头进行现金交易的地方，而调酒师再次面临命运抉择……', '汤姆·哈迪', '迈克尔·R·罗斯卡姆', 6.5, 6041, 'tt1600196', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2190225177.jpg', 1.9, 12.2, 53, 25.7, 7.3, '0.180322,0.151503,-0.051343,0.533838,0.130799,-0.430303,0.778880,0.349769,-0.195672,-0.421389,0.388269,1.002595,0.384491,0.427745,0.550581,-0.140621,-0.549792,-0.849769,-0.041933,-0.120379,-0.383843,-0.147739,0.120756,-0.257894,0.020720,0.188044,0.582207,-0.059241,-0.047777,0.140109,0.402936,0.507207,-0.071253,0.117118,-0.004469,-0.368367,0.806243,-0.165028,-0.778691,0.426910,-0.106303,-0.301040,0.011521,0.030950,0.051961,0.252580,0.493202,0.304688,-0.389135,-0.453823,0.277717,-0.241854,-0.178039,-0.046030,0.526809,0.224285,0.297272,-0.055796,-0.148161,-0.218645,-0.233684,-0.198897,-0.827974,0.060506,0.088587,0.024856,-0.148078,-0.270425,0.236365,0.045246,-0.040642,-0.076473,0.162499,0.177991,1.044650,-0.084214,0.029645,-0.084639,-0.443145,0.125699,0.762782,0.128324,-0.131292,0.485931,-0.191999,-0.499758,-0.018879,-0.121373,-0.363214,-0.019242,-0.023589,-0.060933,-0.256909,-0.109336,-0.590023,-0.247059,-0.236613,-0.320405,0.349589,-0.013909,0.022491,-1.147156,-0.490582,-0.025575,-0.145354,-0.453415,0.036664,0.043560,0.600939,-0.544960,0.021000,0.862494,-0.041717,-0.733074,0.551459,0.225663,0.423242,-0.137311,0.410396,0.267724,0.059016,0.281948,-0.349873,0.179258,-0.162462,-0.287450,-0.058924,0.316232', '4014397', '6517421', '34961898', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4301662', '太空一号', '动作', '未来世界，美国开发出名为“太空一号”的空间站，实则是一座戒备森严的最高警戒监狱，这里现关押着约500名罪大恶极的囚徒，他们无一例外被冷冻起来，处于昏睡之中。某日，现任美国总统的女儿艾米丽·沃纳克（玛姬·格蕾斯 Maggie Grace 饰）为考察人权问题登上太空一号，谁知在对犯人采访时意外发生，一阵混乱过后，所有的罪犯都从沉睡中苏醒，太空一号瞬间被占领，艾米丽以及工作人员沦为人质。与此同时，特工斯诺（盖·皮尔斯 Guy Pearce 饰）遭到陷害，即将遣送太空一号。可是为了营救总统的女儿，他短暂获得了自由，由此进入太空一号寻找目标人质以及掌握着他被陷害重要证据的搭档梅斯。以少敌多的对决在外太空就此展开……©豆瓣', '盖·皮尔斯', '詹姆斯·马瑟', 6.2, 31178, 'tt1592525', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1636456224.jpg', 2.4, 15.3, 58.4, 19.3, 4.6, '0.057686,0.201022,-0.822602,0.439151,0.007636,0.095369,0.543073,0.076930,-0.476020,-0.329243,0.353068,0.585927,-0.155379,0.164219,0.396405,0.104230,-0.502783,-0.576967,-0.400294,-0.181493,-0.412348,-0.664737,-0.374631,-0.164978,0.028624,-0.380449,0.700112,0.215812,-0.334309,0.056091,0.100923,0.399330,-0.215044,0.348615,-0.003243,-0.358012,0.616398,-0.268864,-0.345681,0.516231,-0.604396,-0.159393,0.238879,0.004388,-0.047187,0.354408,0.770187,-0.358022,0.003352,-0.151471,0.335113,-0.446803,-0.106364,0.042152,0.549287,0.034990,-0.258517,0.243462,-0.311774,0.113183,0.102314,-0.200464,-0.718644,-0.123954,-0.004579,-0.063579,-0.235435,0.251826,-0.330501,0.317860,0.092179,-0.016007,0.513436,0.565598,0.119709,0.257529,0.017197,0.311471,-0.353423,0.051776,0.683908,-0.349495,-0.283765,-0.157059,0.128276,-0.415114,0.141578,-0.283494,-0.285439,-0.198091,0.258166,0.028056,0.023056,0.411977,-0.358583,0.152060,-0.537289,-0.508647,-0.021173,-0.148150,-0.169821,-0.788758,-0.002178,0.171033,-0.091683,0.105129,-0.097179,-0.049402,0.422698,-0.601861,0.501823,0.581082,0.136995,-0.427430,0.493017,0.105157,0.358265,-0.367493,-0.088710,0.268525,0.414461,0.500740,-0.093125,0.031922,-0.146334,-0.307412,-0.343030,0.009957', '6007281', '5157137', '1303447', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4304212', '当爱来的时候', '剧情', '16岁的来春（李亦捷 饰）有两个妈妈，当年爸爸“黑面”入赘大妈家却因为大妈不能生育，于是又娶了小妈。来春很享受这个大家庭里家人的关心，但有时她又觉得很有压力。来春意外怀孕之后，男友便消失了，但阿春却固执的坚持要把小孩生下来。爸爸因为过度饮酒而病危入院，整家人乱作一团，面对家庭的变故，来春好像一下子长大了。她渐渐理解了对自己要求严苛的小妈，而且也学会照顾和体谅家人，同时，一股温暖的感觉在她的体内伴随着孕育的生命一同成长……本片在2010年第47届台湾金马奖获得14项提名，并最终囊获包括最佳剧情片在内的多项大奖。©豆瓣', '李亦捷', '张作骥', 7.4, 9334, 'tt1829658', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p665598468.jpg', 0.6, 3.3, 35.5, 46.5, 14, '-0.070127,-0.057652,-0.637721,0.353523,-0.093786,-0.407077,0.540198,0.256601,-0.574171,-0.254342,-0.037318,0.693496,-0.099465,0.366302,0.087366,-0.026980,0.004855,-0.386072,-0.023798,0.084920,-0.221439,-0.255500,0.029638,0.155472,-0.178294,-0.266423,0.474617,-0.125203,0.004430,0.688524,0.202323,0.081762,0.282557,0.589227,-0.123913,0.235459,-0.068367,0.224474,-0.112568,0.173266,0.292477,-0.087656,-0.025185,0.117971,0.286994,0.355595,0.628578,-0.116966,-0.243140,-0.115597,0.554252,-0.123380,-0.220478,0.089554,0.130129,0.173774,0.249969,0.214143,-0.204234,0.142000,-0.085005,-0.058934,-0.573139,0.061755,0.322419,-0.014363,-0.578806,0.235395,0.061679,-0.036333,0.002110,-0.135753,0.217921,0.376623,0.022701,0.634161,-0.570894,0.171890,-0.411299,0.124535,0.660732,-0.387838,-0.372647,0.372671,-0.482482,-0.407403,0.249063,-0.232433,-0.594351,0.119997,-0.068088,0.410945,-0.267436,0.169268,-0.229249,-0.009975,-0.114201,-0.064030,-0.005104,-0.522540,-0.039368,-0.039823,-0.231207,-0.209633,-0.187351,-0.047904,0.048037,-0.368401,0.866625,-0.661618,0.383147,0.312336,0.462482,-0.653119,0.585112,0.387189,0.244184,-0.277698,0.036909,0.283634,-0.248552,0.049429,0.097015,0.182239,-0.194616,-0.036805,-0.235481,0.252123', '3445516', '6963575', '1292720', '25882279');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4304402', '精英部队2：大敌当前', '剧情', '4年前，臭名昭著的拉西欧监狱发生了一场暴动，这一事件引起里约热内卢州社会的广泛争论，也不同程度改变了许多人的命运。直接领导精英部队（BOPE）的罗伯特·纳西贝托中校（Wagner Moura 饰）由此荣升为安全局的副秘书长，拥有更大的施展空间；而他的爱将安德鲁·马蒂亚斯（André Ramiro 饰）被政客当作替罪羔羊，踢出了BOPE部队。当然，纳西贝托也遭受着来自政坛、战友和家人各方面的压力，他将一腔愤懑转化到工作中，不仅扩编强化了BOPE的实力，还通过一次次铁腕的打击荡涤了贫民区毒贩的罪恶势力。毒贩销声匿迹，黑暗的阴霾却未散去。以罗卡（Sandro Rocha 饰）等人为首的腐败警察势力进入贫民窟，他们欺行霸市，官匪勾结，成为里约州另一个难以祛除的顽疾……©豆瓣', '瓦格纳·马拉', '何塞·帕迪里亚', 8.7, 77745, 'tt1555149', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p858211193.jpg', 0.3, 1, 11, 39.7, 48, '0.297290,0.026138,-0.660695,0.566262,-0.174841,-0.098392,0.733027,0.397793,-0.553840,-0.042728,0.214511,0.560066,-0.074612,-0.043010,0.288898,-0.342947,-0.315623,-0.705336,-0.079503,-0.154056,-0.219008,-0.319450,-0.492014,-0.318370,-0.078520,-0.461706,0.613492,0.275784,-0.307112,0.130346,0.139901,0.513879,-0.128486,0.684570,0.028540,0.031494,0.206990,-0.270033,-0.184531,0.118819,-0.041815,-0.215986,0.071523,0.203344,-0.108147,0.255989,0.694742,-0.257605,0.226905,-0.368593,0.392561,-0.399574,-0.148554,0.144736,0.576588,-0.011110,0.004081,0.269876,-0.125911,0.013103,0.068444,-0.025247,-0.820422,-0.256578,0.119360,0.016153,-0.467306,0.388340,0.088334,-0.044221,-0.113834,-0.108240,0.206499,0.313087,0.056882,0.459040,-0.033878,-0.000197,-0.569122,0.030708,0.637305,-0.374020,-0.403972,-0.333349,-0.387161,-0.441074,-0.154317,-0.660592,-0.191468,-0.202172,0.286474,-0.065852,-0.052127,0.376601,-0.529553,0.011978,-0.366504,-0.365532,-0.127683,-0.338938,0.049686,-0.724724,-0.363186,-0.147798,-0.177515,-0.067697,0.414264,0.052637,0.684185,-0.572228,-0.137697,0.727823,0.335242,-0.498844,0.457889,-0.166191,0.265185,-0.264893,-0.192098,0.101410,0.165177,0.621857,0.232705,0.450433,-0.143154,-0.148957,0.117868,0.303888', '25928048', '1793491', '26921827', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4305436', '志明与春娇', '剧情', '一纸戒烟令让狭窄的后巷成为新型社交区域，无数抽数的男男女女不得不躲进那里抽烟。无论身居何位，所为何事，在那里他们都只是一个烟民，大家所做的无非是一起吞云吐雾、一起科插打诨。来自广告公司的志明（余文乐 饰）和在化妆品专柜工作的春娇（杨千嬅 饰）在那里相识，志明的不幸遭遇以及为春娇点烟的举动让春娇对这个斯文的男人略生好感。在接下来的几个日日夜夜，两人不时的传送短信和相约街角吸烟。感情通过拇指传送，爱情在烟雾之中滋生，最终一条暧昧的短信导致春娇和男友家豪（黄德斌 饰）分手。就当春娇准备全身心投入与志明的恋情时，志明的态度却变得含混不清。烟雾继续在街角后巷萦绕，但却不能弥合二人之间出现的隔阂。伴随着增加烟草税的决意颁发，广大烟民们开始搜寻和囤积香烟。在寻烟过程中，志明和春娇在他们第一次遇见的便利商店重逢，这晚，两人相约一起去找烟……本片在五个星期15个拍摄日便完成拍摄，拍摄时间相当短。由于粗口写实镜头过火，《志明和春娇》在香港上映时被定为三级片。', '杨千嬅', '彭浩翔', 7.9, 472992, 'tt1602479', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1456854668.jpg', 0.5, 2.1, 23.6, 48.2, 25.6, '0.323796,-0.025478,-0.663071,0.482140,0.220102,-0.228611,0.754773,0.209783,-0.345927,-0.101042,0.076175,0.710030,-0.504194,0.203502,0.053400,-0.299934,-0.280848,-0.742307,-0.122599,-0.126983,-0.239366,-0.396494,-0.134890,0.000902,-0.150426,-0.074045,0.544099,-0.004031,-0.068386,0.666808,0.276119,-0.034829,-0.506548,0.451900,-0.220072,-0.109807,0.249283,0.108068,-0.463499,0.025674,0.074457,-0.377860,-0.185117,-0.129992,0.155794,0.336163,0.756194,-0.024997,-0.218264,0.206355,0.342350,-0.103379,-0.161379,-0.055684,0.199425,0.194720,0.578415,0.156318,-0.397358,0.361433,-0.198126,0.066930,-0.567261,0.123387,0.079668,0.326315,-0.383544,0.533005,0.038180,-0.254129,0.119616,-0.436131,0.255302,0.364680,0.206889,0.263005,-0.366190,-0.098810,-0.457825,0.039989,0.618953,0.050639,-0.019712,0.425604,-0.141087,-0.119061,-0.063551,0.253140,-0.383850,-0.288061,0.097196,0.075962,-0.103238,-0.004992,-0.883626,0.101641,0.043335,-0.022072,0.299088,-0.286951,-0.272606,-0.975412,-0.131813,-0.442037,-0.217032,0.305559,0.164297,-0.165270,0.568140,-0.676585,0.069271,0.385879,0.382841,-0.434029,0.822119,0.259764,0.132863,-0.253722,0.040952,0.003879,-0.067742,0.266944,0.232363,0.438753,-0.144606,0.07706