INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4307000', '财神到', '喜剧', '剧情梗概财神总管训导众财神，凡间近年多灾多难，正所谓“人间有难，天上有爱”，财神们除了送钱，还要把爱心散播凡间。因今年是非常时期，财神总管也决定亲自上阵，带同“如、意、吉、祥”下凡派钱，众财神们向人间进发……开场：天庭天庭传来一把洪亮的声音：“财神到！”，一众男女财神云集天庭内。财神总管训导众“运财财神”，凡间近年多灾多难，正所谓“人间有难，天上有爱”，“运财财神”除了送钱，还要把天上的爱心，散播凡间！正因今年是非常时期，财神总管也决定亲自上阵，带同“如、意、吉、祥”下凡派钱！财神总管带领一众“运财财神”高呼口号，誓师出发，众财神们向人间进发！《沈阳部份》：大胖假扮十岁女孩(小娇)接近杨大姐财神大胖奉命下凡，来到沈阳巿，把一亿巨款送给善心护士杨素娟。满以为轻而易举，却不小心被杨素娟误会是色狼！为了亲近杨素娟，大胖只好施法变身为十岁小女孩小娇。杨素娟眼见小娇孤苦无依，把她接回家中。奈何“小娇”本性难移，既贪吃又贪睡，还险些穿帮，暴露身份。学校里，小娇认识了胖男孩小秋，两个“胖子”一见如故。小秋不知道小娇实是男儿身，还暗暗的喜欢了她！小区里经营电器维修店的林贵，亦偷偷倾慕着杨素娟。二人是多年邻里，互相照应，夜来一起对酌闲聊。惜林贵始终没勇气跟杨素娟表白。小娇屡次找机会送钱给杨素娟也不成功。反过来，却时常跟着杨素娟一起行善，给生活有困难的公公婆婆送饭菜。渐渐，小娇亦感染了杨素娟助人为乐的精神，利用法力，给邻舍、同学带来欢乐。好心得好报，小娇也得着奇遇，欣赏到闻名沈阳的“二人转”表演！完成任务的期限迫近，小娇幸终想出办法，化身食品公司职员，给杨素娟带来一亿元的幸运大抽奖奖金！没料，杨素', '谭咏麟', '阮世生', 5.6, 9765, 'tt1602480', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2631498602.jpg', 8.5, 24.4, 50.3, 12.7, 4.1, '0.040128,0.137802,-0.406300,0.090675,-0.208044,-0.167077,0.120777,0.266988,-0.327640,-0.071411,-0.041939,0.318592,-0.007202,0.229576,0.240443,0.036645,-0.121317,-0.327148,-0.145838,0.076694,0.214610,-0.148274,0.009343,0.186649,-0.323446,-0.232143,-0.333869,-0.175381,0.209350,0.475818,0.325607,0.123313,-0.130757,0.101533,-0.336605,0.159886,0.038216,0.047249,-0.323371,0.261894,-0.177346,-0.003325,-0.194665,-0.106383,0.238054,0.140376,0.241646,0.016839,-0.230774,-0.273183,0.353359,-0.003783,-0.106306,0.066218,0.155398,0.158862,0.190147,0.103551,-0.104370,0.275093,0.096383,-0.173519,-0.318210,0.371458,0.307008,-0.026209,-0.566186,-0.061139,0.145904,-0.045784,0.046057,-0.320638,0.193212,0.012004,-0.069759,0.358256,-0.024966,0.100771,-0.485963,0.253640,0.612278,-0.136514,0.241785,0.111156,0.242792,-0.025654,0.676062,-0.088089,-0.257268,0.212362,0.062677,-0.094832,0.169694,0.037381,-0.373683,0.109369,-0.332504,-0.012010,0.040100,-0.222675,0.004586,-0.418176,0.023694,-0.172868,-0.225594,0.032811,0.444802,-0.067301,0.776489,-0.216339,0.141588,0.491056,0.427726,-0.561370,0.698503,0.091073,-0.017812,-0.319491,0.009109,-0.421711,0.019541,0.428927,0.076123,0.011173,-0.112733,-0.354729,-0.068417,-0.009913', '26646649', '1296770', '1306530', '1307741');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4307349', '父后七日', '剧情', '得到父亲（太保 饰）去世的消息，女儿阿梅（王莉雯 饰）从台北回到乡里，和哥哥一起为父亲操持后事。在师公严格指挥下哭丧，折纸莲花的唠叨妇女们，被太阳晒爆的罐头塔……阿梅时时被荒诞的乡下丧葬习俗、彼此联系诡谲的乡里人情弄得哭笑不得，与父亲的往事一幕幕涌上心头，成年以来的二人  疏离，在回忆中才慢慢贴近。繁琐冗长、笑多过泪的丧事终于处理结束，阿梅独个回到城市繁忙生活。几个月后，阿梅过境香港机场，习惯性想买一条“黄长寿”烟给父亲，突然惊觉父亲已经不在了，一直没好好流过的泪此刻终于决堤……本片改编自“林荣三文学奖”首奖作品，散文作者刘梓洁亲自执导。©豆瓣', '王莉雯', '刘梓洁', 8, 16757, 'tt1745704', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p719996829.jpg', 0.4, 1.7, 20.1, 53.6, 24.2, '-0.060238,0.047944,-0.502021,0.295955,0.231797,-0.446494,0.508481,0.145389,-0.436627,-0.178030,-0.007011,0.594133,-0.435146,0.462713,0.104648,-0.183562,-0.548690,-0.594243,-0.048364,-0.221041,-0.211275,-0.147692,0.082270,0.064469,-0.331525,-0.063058,0.156369,0.050031,0.205178,0.362748,-0.002861,0.085120,-0.413623,0.250858,-0.327725,0.120854,-0.182070,0.130410,-0.168109,-0.150249,0.233107,-0.144808,-0.285745,-0.234351,0.294828,0.152899,0.486133,-0.093719,-0.239051,-0.102362,0.333127,-0.028854,0.067030,0.046011,0.168376,0.357609,0.255148,0.071159,-0.437805,-0.005165,-0.199883,-0.481767,-0.291858,0.150597,0.050842,0.103756,-0.768620,0.228768,-0.203571,0.049810,0.209039,-0.449059,0.420122,0.316665,0.117207,0.831070,-0.188993,0.339754,-0.061315,0.479745,0.512008,-0.169653,0.124017,0.234672,-0.000444,0.068613,0.298234,-0.063312,-0.242623,0.108437,0.231353,0.036200,-0.119589,0.311550,-0.411022,-0.132069,-0.101167,-0.357338,0.216101,-0.146934,-0.276714,-0.343784,-0.185602,-0.105613,-0.049567,0.037706,0.174200,-0.091174,0.647304,-0.380060,0.509554,-0.055348,0.095047,-0.286095,0.381566,0.012661,0.129443,-0.177103,0.345322,0.174861,0.036873,0.234175,0.370911,0.253844,-0.299837,0.148106,-0.298057,0.242405', '25731805', '27594653', '1876765', '4066127');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4308001', '在劫难逃', '剧情', '年轻人内森（泰勒·洛特纳 Taylor Lautner 饰）拥有一个看上去颇为完美的家庭，从小他生活在一个幸福的环境当中，不过自懂事起，内森总觉得自己过着形同虚设的生活，直到有一天他无意在失踪人口的网页里看到有人在寻找自己，盯着显示器里自己幼年的照片，内森才 明白自己朝夕相处的“双亲”，竟然另有特殊身份，内森这才明白原来20多年来，自己一直活在一个精心编织的谎言当中。内森准备查明真相，他清楚自己所谓的“父母”根本信不过，于是他只能将这一切告诉邻居凯伦（莉莉·柯林斯 Lily Collins 饰）。正当内森和凯伦想搞清楚这是怎么一回事时，却意外的遭遇了职业杀手的追杀，他的“父母”在自己的眼前被害，警察把他当成凶手来追捕，于是内森和凯伦只能开始了惊心动魄的逃亡生涯，而他也在逃亡当中，离真相越来越近……©豆瓣', '泰勒·洛特纳', '约翰·辛格顿', 5.8, 17270, 'tt1600195', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1623268050.jpg', 5.1, 24, 53.2, 13.4, 4.3, '0.237397,-0.069683,-0.931789,0.564176,-0.317677,-0.245312,0.847867,-0.256712,-0.665265,-0.497135,0.229838,0.907018,-0.011822,0.605521,0.221423,0.363095,-0.356500,-0.674284,-0.007797,-0.256997,-0.209727,-0.641367,-0.535973,-0.302893,0.012810,-0.049001,0.352646,-0.031799,-0.081578,0.178795,0.278140,0.065358,-0.075992,0.529180,-0.195132,0.125856,0.071640,-0.037699,-0.140270,-0.141288,0.229300,-0.214252,-0.291429,0.419879,-0.009209,0.285411,0.649805,-0.431519,-0.250244,0.180482,0.307202,-0.328847,-0.069995,0.159234,0.231401,-0.063843,0.180309,0.062488,-0.331951,0.084460,-0.029306,0.034357,-0.857671,-0.009263,-0.250572,0.159730,-0.586417,0.262487,-0.073493,-0.114576,0.218455,-0.401034,0.187655,0.476420,0.235746,0.380682,-0.346425,-0.026406,-0.533945,0.125592,0.711887,0.007619,-0.224371,0.523169,-0.171361,-0.175652,-0.160593,-0.036892,-0.658848,-0.129135,0.349088,0.027740,-0.411457,0.126477,-0.245037,0.122950,-0.280895,-0.159631,-0.037958,-0.388350,-0.391015,-0.099401,-0.236148,-0.438641,-0.591829,-0.048966,-0.294935,-0.543953,0.450524,-0.841590,0.165484,0.610036,0.071053,-0.503876,0.604386,0.306781,0.145087,-0.114662,-0.265732,0.398521,0.091838,0.324778,0.229038,0.148311,0.151818,0.001359,-0.376227,0.505770', '1866424', '1783461', '1304977', '25763555');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4310059', '报应', '惊悚', '虽已身价千万，功成名就，但是大老板王浩潮（黄秋生 饰）身心始终得不到放松。在外有征地事宜搅扰不堪，内有女儿黛丝（文咏姗 饰）青春叛逆，沉湎毒品无法自拔。在一次父女争吵过后，黛丝神秘失踪，不久一段绑架录像便送到王的手中。起初以为是女儿布下的骗局，王只得被迫就范。谁知五千万赎金奉出，女儿仍不见下落。万般无奈，他委托忠心耿耿的保镖——曾经混过江湖的阿初（任贤齐 饰）调查女儿行踪，最终见到的却是黛丝冰冷的尸体。王悲痛欲绝，发誓要让绑匪付出代价。他向所有人隐瞒黛丝已死的事实，单单倚重阿初与其一起踏上复仇的征途。因果报应，丝毫不爽……©豆瓣', '黄秋生', '罗永昌', 5.8, 9270, 'tt1604670', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1594025426.jpg', 3.5, 21.9, 58.5, 13.3, 2.8, '-0.329326,0.142207,-0.671474,0.311600,-0.102530,-0.396841,0.508127,-0.075204,-0.517104,-0.518046,0.192321,0.262086,0.014413,0.243227,0.172336,-0.164100,-0.143177,-0.413356,-0.188520,-0.059568,0.044180,-0.270705,-0.050355,-0.245864,-0.239549,-0.016080,0.565305,0.219220,-0.130282,0.232477,0.559603,0.177697,-0.427329,0.275882,-0.080550,-0.013379,-0.055486,0.118378,-0.637746,-0.064716,0.024483,-0.368808,-0.117143,-0.107288,0.115809,0.190486,0.396651,-0.230088,-0.306082,-0.113025,0.356498,-0.335302,-0.063336,0.060593,0.106729,0.102244,0.306037,0.303774,-0.445059,-0.267148,0.199433,-0.020718,-0.466902,-0.031192,0.197372,0.042825,-0.511095,0.053112,-0.341502,0.279222,-0.093182,-0.186405,0.192160,0.220142,0.163207,0.055698,-0.059843,0.087062,-0.297145,0.154101,0.640466,0.088976,-0.021274,-0.182468,0.155709,-0.197432,0.238505,-0.355610,-0.482685,0.363176,0.220977,0.190773,-0.118401,0.378333,-0.008899,-0.450949,-0.356123,0.015922,0.209365,-0.415224,-0.030233,-0.233264,-0.166052,-0.100587,-0.313011,0.231486,0.084986,-0.170760,0.293461,-0.443327,0.268744,0.206567,0.203494,-0.756557,0.249178,0.268038,0.083399,-0.149112,-0.040981,0.423702,0.227355,0.087725,0.220314,-0.202502,0.096260,-0.097237,-0.201543,0.163688', '1484760', '1293265', '1428876', '26996783');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4312232', '人间喜剧', '喜剧', '年轻杀手司徒春运（杜汶泽 饰）和老前辈夕阳（许绍雄 饰）受雇从内地来至香港，由于消息走漏，二人中途分别，并相约在某大厦露台会面。身无分文的春运没有等到夕阳，却等来寒流与重感冒，最终昏倒在地。住在大厦内的小编剧诸葛头揪（王祖蓝 饰）发现春运，这个心地善良却又有点儿婆婆妈妈的小男人将其带回自己家中悉心照料。苏醒后的春运几度想杀头揪灭口，对方则一根筋地爱心泛滥，甚至大谈与野蛮女友徐天爱（薛凯琪 饰）浪漫又悲惨的恋爱史，全然不知危险所在。随着时间的流逝，这个杀手和编剧之间的友情日益加深。春运冷酷的心渐渐融化，头揪也学会了坚强和自信……©豆瓣', '杜汶泽 Chapman To', '陈庆嘉', 7.4, 53172, 'tt1612142', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p516135005.jpg', 1.2, 4.6, 31, 47.1, 16, '-0.098608,0.157407,-0.781057,0.314445,0.081226,-0.282648,0.962390,0.321760,-0.225970,-0.034108,0.184343,0.400343,-0.400739,0.317995,0.511094,-0.154846,-0.375655,-0.735627,0.021233,-0.146598,-0.313378,-0.152333,-0.169326,0.110655,-0.116552,0.201267,0.590678,0.149483,-0.151190,0.609147,0.374432,-0.110407,-0.222655,0.550819,-0.286083,-0.099220,-0.047047,0.119704,-0.000882,0.039810,0.047889,-0.190745,-0.125002,-0.208555,0.047096,0.486204,0.590595,-0.143148,-0.088813,0.104084,0.281976,-0.356325,-0.017879,0.160260,0.333959,0.023473,0.178781,-0.088770,-0.293043,-0.086371,-0.059350,-0.215714,-0.552685,0.157072,0.142147,-0.038816,-0.381522,0.251598,-0.003562,-0.094592,0.075080,-0.519116,0.178746,0.253793,0.050483,0.482258,-0.169912,0.089100,-0.087356,0.064166,0.213944,0.091477,-0.116240,0.215343,0.086913,-0.351907,-0.003657,0.069812,-0.265244,-0.296712,0.496864,0.189994,-0.124373,0.363624,-0.495313,0.069352,-0.076703,0.050128,0.026046,-0.343198,-0.259920,-0.345973,-0.199356,-0.464639,-0.015241,0.255746,0.226715,0.019722,0.498300,-0.578842,0.243447,0.340800,0.229487,-0.429761,0.317487,0.295007,-0.195248,0.050748,-0.111948,0.416068,-0.060564,0.513727,0.100691,0.294609,-0.309063,0.045929,-0.377560,0.161989', '21348112', '26342391', '21619567', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4312428', '虎胆龙威5', '动作', '虽饱经枪林弹雨洗礼，但是孤胆英雄约翰·麦克莱恩（布鲁斯·威利斯 Bruce Willis 饰）与儿子杰克（杰·科特尼 Jai Courtney 饰）之间依然如同普通父子一样，有着不可逾越的深深隔阂。失去联络许多年，好不容易得到儿子消息的约翰，却发现杰克因多项罪名的指控在莫斯科沦为阶下囚，面临死刑威胁。他未作迟疑，启程前往遥远的俄罗斯。开庭当天，一伙身份不明之人连环爆炸袭击法庭，其目标直指同样遭到指控的俄罗斯富翁尤里·科马罗夫（塞巴斯蒂安·科赫 Sebastian Koch 饰）。混乱之中，杰克护送尤里逃脱，其囚徒背后的秘密身份正逐渐浮出水面。异国他乡，孤立无援，麦克莱恩父子只有依靠彼此逃出生天……©豆瓣', '布鲁斯·威利斯', '约翰·摩尔', 6.4, 58462, 'tt1606378', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1896808402.jpg', 2.2, 13.8, 54.2, 23.5, 6.3, '0.097346,0.053227,-0.732418,0.175451,0.274094,-0.006503,0.643427,0.248105,-0.537055,-0.360056,0.291623,0.532338,-0.037641,-0.057774,0.168411,-0.252136,-0.466502,-0.543515,0.080317,-0.294836,0.060680,-0.772795,-0.438683,-0.113345,-0.019414,-0.202462,0.575951,0.088267,-0.200901,0.498329,0.384060,0.559856,-0.457945,0.524798,0.000059,-0.110024,0.267550,-0.137771,-0.628412,0.085505,-0.150620,0.013785,0.136644,0.196650,-0.359883,0.539082,0.524578,-0.357076,-0.001509,-0.242918,0.054337,-0.386266,-0.148928,0.132542,0.333875,-0.013849,0.044143,0.208795,0.108762,-0.073298,-0.019770,-0.011671,-0.195915,0.019401,0.146966,0.371302,-0.168127,0.049060,-0.202913,0.157092,0.024910,-0.091668,0.034351,0.124021,0.305338,0.256507,-0.238821,0.133947,-0.490669,-0.272906,0.569753,-0.089723,-0.346372,-0.204724,-0.210131,-0.175982,0.150014,-0.404482,-0.187548,-0.113941,0.327678,0.226123,0.002851,0.571642,-0.159680,-0.167031,-0.653772,0.257179,-0.107085,-0.412061,0.030995,-0.743378,-0.054624,-0.052212,-0.232386,0.283705,-0.046174,-0.138047,0.115726,-0.341876,0.416943,0.083523,0.230426,-0.181306,0.201577,0.084201,0.281974,-0.540605,-0.033690,0.730164,0.326531,0.011711,-0.061465,-0.431065,-0.305267,0.101579,0.080555,0.220542', '7916027', '3871833', '20277632', '2034997');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4313109', '登陆之日', '剧情', '日本殖民朝鲜时期，日本将军之孙长谷川辰雄（小田切让 Jô Odagiri 饰）与贫贱子弟金俊植（张东健 Dong -gun Jang 饰）竞逐长跑，直至奥运选拔。尽管俊植涉险夺冠，却被诬陷违规。愤愤不平的民众与军方发生冲突，最终俊植被充军。他和兄弟们屡遭日军凌辱。一次野战，俊植意外俘获了专门射杀日军的狙击手斯莱（范冰冰 饰）。上将辰雄来前线督战，令俊植受辱。他每晚坚持长跑，却被烧了跑鞋。他不愿做敢死队，索性集体出逃。俊植看到苏军压境，决定跑回送信。结果，日军惨败，辰雄和俊植被俘。冰天雪地，俊植见到了此前出逃的兄弟众泰，但后者已成冷血。一次骚乱之后，俊植和辰雄角斗，结果俊植宽容了对手。此后，德军疯狂反扑，俊植和辰雄在敢死队同历生死。他们为了逃命，同甘共苦，翻山越岭，来到德军占领地。两人失散，再见竟是诺曼底的德军阵营，辰雄再次见到了那个奔跑着的身影……©豆瓣', '张东健', '姜帝圭', 7.4, 24473, 'tt1606384', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1749048668.jpg', 2.2, 6.1, 32.4, 39.1, 20.2, '0.044458,-0.243961,-0.545224,0.406516,0.321042,-0.316452,0.397073,0.052004,-0.307959,0.054138,0.376059,0.475514,-0.075691,0.028098,0.037390,-0.373089,-0.221689,-0.726357,-0.252386,-0.043230,-0.142518,-0.194175,-0.084144,-0.173323,0.208485,-0.131528,0.705293,0.202255,-0.302330,0.654908,0.286943,0.100824,-0.010940,0.481995,0.013065,-0.003638,0.180661,-0.312531,-0.348907,0.084534,-0.395248,-0.431955,-0.442028,-0.082611,-0.033532,0.448374,0.721309,-0.182804,-0.043138,-0.289322,-0.038383,-0.498138,0.036099,0.379115,0.296282,-0.094385,-0.022639,0.153208,0.256614,0.122664,-0.104010,0.192507,-0.107517,0.281213,-0.255579,-0.054452,-0.504902,0.493290,-0.234749,0.279838,0.184936,-0.172454,0.132888,0.525968,0.212983,-0.135513,-0.240166,0.188752,-0.498117,0.245332,0.816976,-0.215330,-0.079592,-0.173215,0.035716,-0.241501,0.457049,-0.521000,-0.275836,-0.044717,0.415182,-0.280906,0.098418,0.210264,-0.514683,-0.043996,-0.492720,-0.178204,-0.243081,-0.057462,-0.128193,-0.609740,-0.060484,-0.275778,-0.435313,0.550483,-0.025024,0.260769,0.435871,-0.278446,-0.273305,0.424879,0.355309,-0.553763,0.213246,0.330836,-0.235415,0.195725,0.119517,0.352849,-0.004771,0.509998,0.264201,0.109228,-0.284203,-0.006526,-0.377492,0.005675', '3078390', '30299515', '1294227', '35256235');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4319218', '午夜巴黎', '剧情', '吉尔（欧文•威尔逊 Owen Wilson 饰）携未婚妻伊内兹（瑞秋•麦克亚当斯 Rachel McAdams 饰）陪着岳父岳母来巴黎度假。他希望留在巴黎完成自己的第一部小说，但是伊内兹及其父母坚决反对。在一次用餐时，伊内兹遇到了昔日同学保罗夫妇，他们一同出游。保罗到处卖弄，跟导游（卡拉•布吕尼 Carla Bruni 饰）喋喋不休，令吉尔反感不已。午夜时分，他独自走在巴黎的街头，却被一辆路过的马车吸引住了。他随马车来到了一个名流派对，阴差阳错地结识了海明威、毕加索、菲茨杰拉德、达利（阿德里安•布洛迪 Adrien Brody 饰）、斯坦因（凯西•贝茨 Kathy Bates 饰）等，而且他更是迷恋上了毕加索和莫迪尼亚里的情人阿德里亚娜（玛丽昂•歌迪亚 Marion Cotillard 饰）。他乐此不疲地穿越，而由此发生的一切都让他无可救药地爱上了巴黎这座城市……伍迪艾伦凭此片获69届金球奖最佳编剧', '欧文·威尔逊', '伍迪·艾伦', 8.3, 301023, 'tt1605783', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p944234798.jpg', 0.2, 1.4, 15.6, 46.7, 36, '0.351037,-0.018869,-0.754441,0.499718,-0.001259,-0.426900,0.573515,0.303476,-0.527024,-0.094637,0.208990,1.023166,-0.415922,0.340157,0.560478,0.309775,-0.572548,-0.481916,0.294525,-0.050669,0.072961,-0.497104,-0.193301,-0.237294,-0.179689,-0.211315,0.211390,-0.062777,0.111800,0.765589,0.211481,0.200100,0.049645,0.418574,-0.123637,0.231801,0.438421,0.008061,-0.218855,0.408452,0.063177,-0.096234,-0.227269,-0.058567,0.111091,0.117501,0.553606,-0.147294,0.260248,0.030875,0.162122,-0.193567,0.235211,0.162312,0.015445,-0.140925,0.094832,0.237549,-0.236536,0.082734,0.158967,-0.053317,-0.191536,0.347074,-0.115970,0.087728,-0.533413,0.613352,-0.404174,-0.013433,0.139829,-0.351315,0.177108,0.122008,0.054583,0.109661,0.096427,0.018821,-0.465558,0.169611,0.411579,0.004201,-0.010675,0.256520,-0.094424,-0.174173,0.044692,-0.084867,-0.669985,-0.030153,0.347237,-0.192401,-0.103035,0.064956,-0.462262,-0.268193,-0.379243,-0.225227,-0.077754,-0.321905,-0.019644,-0.892266,0.110525,-0.395757,0.019795,-0.224501,-0.047287,-0.137918,0.369593,-0.404843,0.290226,0.531580,0.167277,-0.292145,0.798154,-0.018284,0.059503,-0.049484,-0.127231,0.449303,0.073875,0.155119,0.196601,0.404318,0.146066,-0.048621,-0.350081,0.507323',