INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4319234', '超级名模2', '喜剧', '《超级名模2》的故事发生在第一部的10年之后，故事发生地在罗马。当年的名模祖兰德（本·斯蒂勒 饰）和汉塞尔（欧文·威尔逊 饰）已经被人遗忘，他们不得不重新奋斗，上演一段搞笑之旅。', '本·斯蒂勒', '本·斯蒂勒', 4.8, 7461, 'tt1608290', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2291118782.jpg', 20.1, 36.8, 30.8, 7.8, 4.4, '0.362419,-0.094817,-0.635133,0.119418,0.503614,-0.272845,0.741915,-0.042785,-0.681186,-0.288172,0.159223,1.034093,-0.799970,0.000873,0.779078,-0.064246,-0.585480,-0.889853,0.170464,-0.305409,0.183475,-0.588306,-0.435736,-0.164390,0.090529,-0.706364,0.452460,-0.080918,-0.263978,0.277785,0.437595,0.242290,0.000204,0.117391,-0.107962,0.524638,0.320940,0.264590,-0.311167,-0.192809,-0.066789,-0.398886,-0.392105,-0.174120,-0.011498,-0.080694,0.687576,-0.496545,-0.035092,0.066694,0.300243,-0.297941,-0.349225,-0.175270,0.026036,0.119356,0.232679,0.682027,-0.066864,-0.062083,0.142293,-0.401050,-0.747968,0.065148,0.130467,0.409417,-0.353603,0.896046,-0.235220,0.196467,0.292115,-0.496360,0.083894,0.387146,0.844241,0.287074,0.063638,0.022799,-0.446741,0.792726,1.070364,0.271545,-0.368264,0.496893,0.363975,-0.153353,-0.482661,-0.055392,-0.631716,0.461829,0.380147,-0.221379,-0.246649,0.859620,-0.836663,-0.317030,-0.395758,-0.395462,0.055465,-0.249500,-0.210153,-0.706319,-0.402332,-0.396923,0.157446,-0.166743,0.024712,-0.128923,0.640483,-0.617413,0.638623,0.268532,-0.117503,-0.091770,0.483466,0.122846,0.135330,-0.069014,-0.170530,0.493348,-0.154987,0.485521,-0.023055,0.413777,0.090368,-0.287345,-0.503758,0.606820', '30162520', '11541282', '26687241', '35161768');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4319445', '人狼大战', '剧情', '冰天雪地极度严寒的阿拉斯加荒原，来自各地的杀人犯等非法之徒加入某石油公司，在这个蛮荒之地辛苦作业。约翰·奥特维（连姆·尼森 Liam Neeson 饰）是这家公司的守护猎人，专门负责猎杀野狼以使工人灭受残害。他日夜思念妻子，于生早已了无所望。某天，他和工人们乘坐的飞机遭受空难，当他再次醒来时，发现自己正置身在暴雪纷飞的冰原。与之一同侥幸逃生的汉德里克（Dallas Roberts 饰）、迪亚兹（Frank Grillo 饰）、博克（Nonso Anozie 饰）、塔尔盖特（Dermot Mulroney 饰）、弗兰纳瑞（Joe Anderson 饰）以及赫南德兹（Ben Bray 饰）等6人。虽然暂时逃生，但在救援迟迟不曾到来的危机时刻，他们的生命依然受到威胁。性格各异的7名幸存者，即将踏上似乎永无止境的求生之路……©豆瓣', '连姆·尼森', '乔·卡纳汉', 6.5, 27208, 'tt1601913', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1453092871.jpg', 2.5, 12, 50.4, 28, 7.1, '-0.004085,-0.099855,-0.800336,0.219081,0.317874,-0.191795,0.556040,0.299835,-0.471249,-0.549950,0.360021,0.531432,0.186486,0.137910,0.263453,-0.145114,-0.395267,-0.459711,-0.102662,-0.082793,-0.281327,-0.131624,-0.316040,-0.065909,-0.062937,-0.240794,0.642272,0.408470,0.041709,0.500983,0.104245,0.560839,-0.213319,0.599318,-0.249196,-0.255339,0.246337,-0.205256,-0.325106,-0.028321,-0.209835,-0.182003,-0.166949,0.022282,0.017577,0.501718,0.704408,-0.519413,-0.059761,-0.204515,0.048762,-0.388684,0.219166,-0.015207,0.273558,-0.351270,0.027394,0.188746,-0.100275,0.148819,0.049988,-0.064605,-0.725283,-0.134634,-0.120157,0.183634,-0.412613,0.207279,-0.082352,0.112522,0.039005,-0.072986,0.190189,0.318368,-0.024928,0.257163,-0.114329,-0.037431,-0.490755,0.043708,0.546940,-0.028247,-0.183476,0.081613,-0.203692,-0.386839,0.121536,-0.245758,-0.502118,-0.250433,0.354353,0.179032,-0.088965,0.173028,-0.791070,0.110265,-0.225721,-0.324760,-0.010463,-0.137211,-0.227202,-0.868376,0.200364,-0.190046,-0.154515,0.310669,0.200261,0.031443,0.475844,-0.730357,0.460606,0.394560,0.257950,-0.483067,0.449051,-0.070818,0.131986,0.012586,-0.099077,0.558900,0.191808,0.430430,-0.031508,-0.015185,-0.027946,-0.024986,-0.242703,0.261602', '2159244', '2369613', '1307897', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4320236', '杀手欧阳盆栽', '剧情', '他叫欧阳盆栽（萧敬腾 饰），是一个刚入行的菜鸟杀手。没有人知道他真实的姓名，他师从骗神（曾志伟 饰），师徒俩天生不适合当杀手，拿起刀手都软，因此他们只利用人性杀人。通过制造种种意外事故，在七天之内让目标从世上消失。骗神的生意多年来稳定，即将退休的他将盆栽推向前台，将徒弟 介绍给心狠手辣的黑道大哥（黄立成 饰）。可是盆栽始终无法狠下心来杀人，为了拯救被杀者以及自己的性命，盆栽找来了黑道医生全叔（张国柱 饰）、性感黑客娜娜（周秀娜 饰）、无良保险业务员曾阙德（马念先 饰）共同制造了一桩桩艺术级的假死事件。再完美的骗局也有败露的一天，不合格的杀手欧样盆栽将自己置身莫大的危险之中……©豆瓣', '萧敬腾', '李丰博', 5.4, 22019, 'tt2231605', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p797472352.jpg', 10.1, 28.9, 44.8, 12.1, 4, '0.280488,-0.029679,-0.272662,0.374942,-0.690773,0.161610,0.387757,-0.126602,-0.600793,-0.212512,0.397513,0.604751,0.031847,-0.154383,-0.089422,0.089951,0.136367,-0.653584,-0.041841,-0.147462,-0.297665,-0.404223,-0.431203,-0.320123,-0.225640,-0.103600,0.442230,0.037703,-0.258821,0.170692,0.374941,0.232054,-0.153068,0.192654,-0.136514,-0.100687,0.059966,-0.006197,-0.266925,0.224021,-0.030328,-0.445302,0.095978,0.325621,-0.141661,0.375148,0.407198,-0.282242,-0.130975,-0.150712,0.451609,-0.358623,-0.037463,-0.003340,0.211744,-0.019039,0.089163,0.345398,-0.269583,-0.067123,0.220408,-0.097743,-0.790283,-0.108359,0.277837,-0.044494,-0.708307,0.446911,-0.331368,-0.097957,0.104930,-0.218403,0.251497,-0.021626,0.414796,0.207730,-0.025660,0.001107,-0.485341,0.510352,0.455462,0.086272,-0.099794,0.312496,-0.057264,-0.420918,-0.092634,-0.466323,-0.232106,0.066960,0.312794,-0.100924,-0.169038,-0.073922,-0.509680,-0.080958,-0.200507,0.038017,-0.024615,-0.388456,-0.245193,-0.144639,-0.125897,-0.109381,-0.266751,0.068324,0.149883,-0.348092,0.721225,-0.693618,0.256123,0.512977,0.029515,-0.376661,0.561680,-0.121951,0.067175,-0.252334,-0.103362,-0.063319,0.185785,0.356648,0.169040,0.309447,0.016256,-0.123148,-0.146674,0.137008', '1793491', '27602116', '1877596', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4323691', '打擂台', '剧情', '公司小职员梁景祥（黄又南 饰）为人懦弱，是个时常受气的角色。这日他为公司奔赴某村收地，不料路上被几个恶人暴打，幸有罗新门高徒林良淳（梁小龙 饰）出手相救。梁景祥感佩良淳，追索至罗记茶楼试图拜其为师。罗新门罗新师傅（泰迪罗宾 饰）三十年前名动武林，但因在一次比武中不幸中风昏迷至今，导致罗新门败落，只有首徒陈德成（陈观泰 饰）与林良淳二人勉力维系一门生计，昔日武馆也早已沦为茶楼。梁景祥的到来，激起了罗新门与庞青（陈慧敏 饰）一派的旧日恩怨；更因特殊身份卷入了罗新门与开发商的冲突。混乱中，昏迷的罗新师傅突然醒转，老师傅的第一个重要决定，便是参加由庞青主办的擂台比赛……©豆瓣', '黄又南', '郭子健', 7.1, 18063, 'tt1611823', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p767173507.jpg', 1.5, 6.6, 40.3, 40.5, 11.2, '0.111253,0.057361,-0.269384,0.154027,0.110466,-0.274841,0.335573,0.235465,-0.722856,-0.520417,0.337561,0.667470,-0.083452,0.279603,0.234223,-0.404592,0.260204,-0.580646,-0.038642,0.003826,-0.137254,-0.234994,0.020383,-0.070854,-0.370039,-0.222380,0.570635,0.240254,-0.256366,0.568173,0.240742,0.306409,-0.271385,0.162550,-0.047034,-0.090619,0.015192,0.188071,-0.485597,0.034327,-0.239891,-0.507684,-0.283565,-0.046462,-0.006104,0.583386,0.454732,-0.060013,-0.213124,-0.395878,0.236039,-0.173943,-0.103037,0.097524,0.455209,0.088841,0.336002,0.251062,-0.283896,-0.145938,-0.030209,-0.147888,-0.575050,0.299812,0.400778,-0.168739,-0.584212,0.452644,-0.124886,-0.173320,-0.196165,-0.098107,0.154339,0.372142,0.292398,0.067987,-0.056773,-0.118147,-0.286917,0.312108,0.558558,-0.111450,0.030917,0.232188,0.281574,-0.219786,0.286776,-0.505891,-0.109890,0.007003,0.226442,-0.076545,0.222874,0.228969,-0.275040,-0.030366,-0.310337,-0.025391,0.053703,-0.138326,-0.062672,-0.451809,-0.048942,0.070421,-0.043289,-0.012759,0.245613,-0.068400,0.348597,-0.741071,0.218387,0.096984,-0.021396,-0.542132,0.591642,0.097308,0.420567,-0.273148,-0.146094,-0.100408,0.021936,0.063877,-0.040222,-0.004175,-0.121817,-0.145728,-0.266273,-0.063060', '35030151', '1297747', '30345227', '22964524');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4323732', '大笑江湖', '动作', '吴迪（小沈阳 饰）以修鞋为生，最大乐趣就是看武侠漫画《飞剑》。某日，他遇到了修鞋女子月露（林熙蕾 饰），后者是皇上（陈志朋 饰）的表妹，因不愿做皇后，逃之夭夭。皇上派遣大内高手杨过（曾志伟 饰）追杀。吴迪盲打误撞杀了淫贼田扒光，救了月露。为了把鞋还给月露，吴迪前往泰山。途中，吴迪遭遇河盗独孤鸿（赵本山 饰）及其弟子（程野 饰），在世外高人的暗中帮助下，他击退了独孤鸿。老人临别时输给他深厚内力，赠给他一本《九阴真经》，由于他只看图，随手丢在一边。田扒光的神农教同门姐妹粉凤凰和红凤凰找他算账，结果他毫发无损，对方损兵折将。逃避追杀时，他掉进了万丈深渊，却遇到了世外高人的敌人（吴宗宪 饰），好在有惊无险。不过，最终吴迪还是住进了神农教主（恬妞 饰）开的黑店，并遇到了心上人月露……©豆瓣', '小沈阳', '朱延平', 4.8, 88662, 'tt1825731', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p735552334.jpg', 20.1, 35.4, 34.3, 7.2, 3, '-0.151488,-0.129597,-0.114766,0.426985,-0.339624,-0.033505,0.275593,0.067629,-0.486280,-0.034666,0.564750,0.748315,0.074639,0.041695,0.070583,0.157684,-0.177642,-0.481492,0.309854,-0.146307,-0.134052,-0.032524,-0.186589,0.027063,-0.104084,-0.077141,0.253297,0.058006,-0.250052,0.088945,0.230860,-0.030545,-0.341996,0.364092,-0.264113,0.395272,-0.280203,-0.024288,0.040289,0.489894,-0.086496,-0.412607,-0.306755,0.043176,0.016186,0.457173,0.294425,-0.141952,0.160443,-0.176420,0.092485,-0.163218,-0.047626,0.013588,0.230025,-0.144538,0.329466,-0.012502,-0.078936,0.021375,0.199088,-0.070301,-0.275412,0.362583,0.191000,-0.085759,-0.509163,0.548654,-0.253033,0.199458,0.026608,-0.348906,-0.060361,0.038419,0.292721,-0.193005,-0.208723,-0.134519,-0.505014,0.441104,0.217021,-0.083573,0.498829,0.108758,0.326463,-0.206982,0.071910,-0.377338,0.040782,0.006228,0.705146,-0.076383,-0.034789,0.091465,-0.265925,-0.201210,-0.249446,0.223908,-0.164621,-0.157672,-0.170419,-0.317889,0.161838,-0.219988,-0.261482,-0.098646,0.271227,-0.360062,0.403549,-0.431698,-0.054882,0.261452,0.069746,-0.432983,0.524127,-0.218426,-0.112509,0.022083,-0.243159,0.153959,0.106357,0.436698,0.359011,0.346005,0.001400,-0.119243,-0.064581,-0.056960', '1309069', '1295824', '1300857', '1308866');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4326412', '吸血鬼猎人林肯', '动作', '19世纪上半叶，后来在美国历史上留下重要足迹的亚伯拉罕·林肯（本杰明·沃克 Benjamin Walker 饰）还只是一个背负着杀母仇恨的年轻人。在一个充满不祥气息的夜晚，他举枪刺杀了仇人，但已经遭受了致命伤的仇家却凶恶反扑。关键时刻，林肯被名叫亨利·斯特吉斯（多米尼克· 库伯 Dominic Cooper 饰）的男人所救。从亨利口中得知，他险些被变成吸血鬼的仇家杀害。经过一番艰苦特训，林肯成为吸血鬼猎人。正值此时，吸血鬼业已蔓延整个美国南部，并渐次向北方推进。在亨利的指示下，林肯返回城镇，展开了针对吸血鬼似乎永无止境的猎杀，而吸血鬼制造者杰克·巴兹（Marton Csokas 饰）也注意到了这名“索命死神”的存在……©豆瓣', '本杰明·沃克', '提莫·贝克曼贝托夫', 6.3, 37292, 'tt1611224', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1560108474.jpg', 2.3, 14.9, 53.1, 23.6, 6.1, '0.251829,0.014159,-0.585793,0.487362,-0.083232,-0.203227,0.928205,-0.037961,-0.378621,-0.265967,0.496841,0.833717,-0.038794,-0.073892,0.379369,0.133578,-0.138617,-0.513612,0.019608,-0.079179,-0.228999,-0.406788,-0.551678,-0.308164,0.191376,-0.437019,0.545188,0.256077,-0.174998,0.417312,0.258607,0.516999,-0.120434,0.506681,-0.267457,-0.017586,0.298107,-0.460828,-0.066275,0.299205,-0.231179,-0.262126,0.110775,0.163953,-0.450229,0.559477,0.516870,-0.428576,0.146797,-0.358387,0.327969,-0.422431,-0.080621,0.191037,0.649407,-0.101716,-0.126187,0.370534,0.178827,-0.057839,-0.080263,0.023900,-0.671895,0.065723,-0.045642,0.417093,-0.702616,0.434829,-0.126765,0.130829,0.053136,-0.283273,0.150588,0.050856,0.150745,0.242144,0.040168,0.017816,-0.568989,-0.089872,0.750853,-0.206691,-0.400067,0.105369,-0.203511,-0.454790,0.033982,-0.161991,-0.240149,-0.241408,0.554214,0.057383,-0.372556,0.413685,-0.538469,0.002090,-0.414192,-0.229836,-0.125134,-0.082739,-0.338400,-0.702661,-0.130529,-0.271446,-0.180334,0.057548,-0.068891,-0.091518,0.442312,-0.464943,0.503131,0.689061,0.253804,-0.211426,0.407759,-0.075503,0.049281,0.015070,-0.252444,0.717487,0.324304,0.413608,0.063020,0.044110,-0.255434,-0.245015,-0.087158,0.513342', '25828589', '1316693', '1298095', '1307311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4328442', '遍地狼烟', '动作', '电影《遍地狼烟》同名小说出自网络知名作家“菜刀姓李”（李晓敏）之手。网络付费总点击量超过3千万，曾参选第八届茅盾文学奖，成功跻身81部入围作品。牧良逢（何润东 饰）牧良逢是一个生长在湖南怀化市一个名叫风铃渡镇上的山里孩子，无父无母，从小跟着爷爷在森林里以打猎为生。牧良逢对枪天生有着一种独特的天赋，练就了一手好枪法，猎物百打百中，在山里过着平静安详的生活。因为茶馆老板娘柳烟（小宋佳 饰）抱不平，刀砍兵痞，被带到军营。途中，一场狙击战显露其神枪手潜质，后被猛子（梁家辉 饰）编入狙击排，从此与小伍（何晟铭 饰）等一起踏上了狙击手的生涯……©豆瓣', '何润东', '胡大为', 5.8, 6862, 'tt2319805', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2633710180.jpg', 6.4, 21.6, 50.1, 17.5, 4.4, '-0.126217,-0.099311,-0.249520,0.485195,0.035609,0.250017,0.230226,0.156448,-0.399288,-0.018885,0.252864,0.563254,0.148163,0.194063,-0.077960,-0.263776,0.129689,-0.400712,-0.146586,-0.133712,-0.119909,-0.023937,-0.215426,0.223869,-0.043378,-0.339943,0.513198,-0.203998,-0.355484,0.651034,0.250772,0.027734,-0.267567,-0.094497,-0.428105,-0.019212,0.117973,-0.128969,-0.261410,0.325051,-0.263623,0.056732,-0.057455,-0.449795,0.105397,-0.081611,0.853213,0.160025,-0.101709,-0.127476,0.394204,0.140599,-0.114193,-0.166018,0.401513,0.131877,0.347112,-0.114137,0.083483,0.261390,-0.020401,-0.281634,-0.464297,-0.145094,0.170665,-0.042282,-0.847711,0.233006,0.089165,-0.154497,-0.054074,-0.152444,0.118689,-0.149402,0.219101,0.196246,0.038020,0.074393,-0.230873,0.574749,0.324164,-0.267412,-0.098197,0.250842,0.226290,-0.358998,0.072914,-0.044366,-0.499048,0.091172,0.373586,-0.226254,-0.299514,-0.035071,-0.617325,0.307286,0.058517,0.039659,0.086245,-0.142976,-0.152600,-0.492092,0.124631,-0.203331,-0.140154,0.071003,0.156512,-0.045902,0.786563,-0.497330,0.286390,0.164377,-0.011229,-0.187600,0.583805,0.047290,0.048409,-0.077953,-0.019650,0.365682,0.232996,0.283922,-0.015048,0.389619,-0.219209,-0.342710,-0.475180,0.455975', '3811356', '1302661', '1908036', '26926321');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4328444', '翡翠明珠', '剧情', '电影取材自麦炳荣和凤凰女的粤剧戏宝《凤阁恩仇未了情》。嫣公主（蔡卓妍 饰）一心远嫁藩国当皇妃，在漫漫的出嫁途中，与负责护送的程将军（林峰 饰）成为斗气冤家，岂料两人日渐生情。二人不顾此情天地不容，交换陪嫁明珠与家传翡翠，以作定情之时，却遇山贼来袭。混乱之中，嫣失足堕崖，程落入山贼之手。一对有情人失散，各有一段奇遇。程被山贼女首领祝三娘（容祖儿 饰）带回山寨，嫣大难不死，却失去记忆，被说书人凌感开（王祖蓝 饰）救起。出走山寨寻找公主的程将军，一片痴情形影相随的祝三娘；流落民间失去记忆的嫣公主，平凡一生说书度日的失意才子。有一天，当他们相遇在一起，会发生怎样的故事……©豆瓣', '林峯', '秦小珍', 5.2, 8658, 'tt1711475', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p539099415.jpg', 12.4, 31.6, 43.4, 9.3, 3.4, '0.088749,0.101946,-0.297841,0.532005,0.460185,-0.225276,0.796188,-0.017289,-0.440218,-0.358618,0.159701,0.402506,-0.292979,0.230505,0.349937,-0.057217,0.053762,-0.676130,-0.027189,-0.233177,-0.028532,-0.310448,0.188689,0.186746,-0.292721,-0.291923,0.709497,0.256991,0.004285,0.612582,0.601013,0.290829,-0.814084,0.319850,-0.356534,0.194698,-0.188842,0.175381,-0.474513,-0.049341,0.026175,-0.230067,-0.189463,-0.406226,-0.126237,-0.022808,0.900382,-0.403268,0.254660,-0.337815,0.370014,0.021272,0.225284,-0.080150,0.438347,-0.143178,0.197739,-0.013102,-0.177223,-0.160469,0.288234,-0.143005,0.000625,0.131721,0.409350,-0.023743,-0.501759,-0.033723,0.163322,0.305384,-0.001279,0.139059,0.401845,0.225892,0.341020,0.140720,0.012900,-0.035717,-0.555850,0.367746,0.735433,0.009739,-0.092822,0.213982,0.292924,-0.452115,0.126295,-0.141516,-0.650844,0.284938,0.465944,-0.096491,0.020691,0.286292,-0.394606,-0.138720,-0.483921,0.368108,0.338116,-0.295614,-0.010156,-0.329105,-0.129265,-0.231058,-0.197975,0.096748,0.428348,-0.215277,0.760335,-0.645583,-0.060714,-0.124085,0.002139,-0.758596,0.525393,-0.079182,0.265351,-0.155207,-0.031612,0.458544,0.035368,-0.026909,0.093926,-0.006342,-0.385278,0.284441,-0.373185,0.035377', '3445516', '26754643', '21619567', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4603531', '明日之丈', '剧情', '落魄拳手丹下段平（香川照之 饰）因欠债被黑社会追打，路人矢吹丈（山下智久 饰）仗义出手，凭借出色的击打本能将黑社会击退。前科累累的孤儿矢吹丈因这次斗殴入监，段平十分欣赏丈的天赋，希望教授其拳击技术，然而只求眼下开心的丈无心学拳，直到他在狱中遇到劲敌力石彻（伊势谷友介 饰），曾为职业拳手的力石轻松将丈击败，感到自尊受挫的丈自此开始按照段平寄来的拳击指导勤加练习。白木财团千金白木叶子（香里奈 饰）与监狱合作举办狱中拳击赛，丈得以和白木的拳手力石再次较量，并凭借交叉拳打成平手。不久二人先后出狱，力石再度登上拳台，而丈则跟随段平开始进军职业拳赛。两人未了的胜负，终究需要一个结局……©豆瓣', '山下智久', '曾利文彦', 6.8, 6176, 'tt1606595', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p889860520.jpg', 2.2, 10.1, 46.9, 28.3, 12.5, '0.120655,-0.138784,-0.241619,0.391298,0.016822,-0.161218,0.078518,0.114381,-0.291829,-0.413261,0.592012,0.437259,-0.204846,0.001978,0.321255,-0.693444,0.398079,-0.620517,-0.047157,0.215538,0.060867,-0.407079,-0.264444,0.139742,-0.413323,-0.180256,0.704278,0.100973,0.007987,0.855591,0.201839,0.402116,-0.043881,0.074826,0.023374,-0.268598,-0.130843,0.106139,-0.525233,0.175595,-0.270343,-0.280406,0.064270,-0.305179,0.030968,0.262013,0.491384,-0.101917,-0.029694,-0.241144,0.356425,-0.041619,-0.077204,0.101230,0.407595,0.197119,0.305428,0.185080,-0.021965,0.041814,0.088974,-0.152534,-0.295111,-0.011771,0.295117,-0.124306,-0.428910,0.566567,-0.179237,0.047669,-0.009524,0.152906,-0.435186,0.225099,0.353553,0.033154,-0.209299,0.099298,-0.071406,0.032498,0.577064,-0.152619,-0.010224,-0.034014,0.292366,-0.399467,0.030508,-0.487848,0.135533,0.073118,0.302521,0.204339,0.061380,-0.025275,-0.273062,0.018435,-0.335243,0.149756,0.135785,-0.127099,0.095168,-0.489070,-0.009902,-0.022207,-0.239690,0.167631,0.109782,-0.417652,0.412193,-0.666347,-0.083296,0.104928,0.341127,-0.006390,0.360984,0.035797,-0.080439,-0.194482,-0.140803,0.258055,0.159787,0.179225,0.010748,0.212650,-0.030494,-0.204921,-0.088711,0.301311', '3230460', '26365262', '4202326', '3139191');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4604803', '安非他命', '剧情', '金融业才俊丹尼（白梓轩 饰）在香港偶然遇见了游泳教练观奇（彭冠期 饰），他们一个事业成功，是国际公司的中坚，坚信自己的取向；另一个为生病的母亲时时担忧，为了赚钱只得多份兼职奔忙，从裸体模特到送货样样做得……在两人相遇的时候，观奇与自己女友的关系正走到了尽头，丹尼慢慢介入 了观奇的生活，他们一同出游，分享技能与记忆，但丹尼尝试阐明自己的爱意之时，却被观奇谨慎的回绝了……观奇自己一段悲惨的遭遇所折磨，痛苦的记忆横亘在他和丹尼的关系之间，丹尼未有放弃，他引导着观奇，指着建设中的跨海大桥声称“如果大桥联通，就是你能接受我的时刻”……©豆瓣', '彭罡原', '云翔', 6.3, 18248, 'tt1603789', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p649626586.jpg', 4.1, 18, 46.9, 22.9, 8.1, '0.281408,-0.001562,-0.751049,0.596159,-0.093238,-0.409008,0.607570,0.230057,-0.311021,-0.139844,0.259510,0.802373,-0.058462,0.281108,0.162286,0.057952,-0.100054,-0.841359,0.208669,-0.039378,-0.337968,-0.538667,-0.137359,-0.093930,-0.185862,-0.274920,0.488736,0.104884,-0.356377,0.380989,0.189739,0.076597,-0.289540,0.618798,-0.277802,-0.121412,0.098559,0.167570,-0.341126,0.018871,0.028231,-0.365391,-0.055783,0.036537,0.079553,0.434191,0.626288,-0.180764,-0.179867,0.244316,0.187611,-0.150764,0.148360,0.138237,-0.021494,-0.008760,0.138362,0.191029,-0.342574,-0.087899,-0.015939,-0.023018,-0.943077,-0.018301,-0.089094,0.270868,-0.733813,0.437990,-0.060227,-0.208814,0.237044,-0.417626,0.114172,0.418173,0.201742,0.312734,-0.224636,0.091254,-0.371358,0.190269,0.883133,0.034108,-0.122269,0.381714,-0.238878,-0.113712,0.024185,-0.116715,-0.523509,-0.203286,0.232293,0.006683,-0.240184,0.297554,-0.648270,0.189380,-0.200324,-0.005381,0.043729,-0.427960,0.046510,-0.523701,-0.173416,-0.463161,-0.377772,-0.020821,0.106388,-0.540053,0.530115,-0.837173,0.054192,0.796707,0.292631,-0.638770,0.964032,0.219276,0.191175,-0.259205,-0.001086,0.300302,-0.132861,0.320551,0.114433,0.344741,0.183992,0.121162,-0.564632,0.515555', '25908042', '1306916', '26021055', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4604914', '爱情36计', '喜剧', '留着一撇小胡子的十三豆（刘桦 饰）是个终年研习兵法、靠写剧本为生的中年怪蜀黍。某天，十三豆原本想靠预测大师的名头骗网友咖喱小猫（谢娜 饰）上床，却被对方狠狠整治，醒过来后又被轿车拉到大奸商王天贵（孙兴 饰）的办公室。由于拖欠王天贵的稿子和定金，十三豆被迫要接下王总交给他的一个缺德任务，那就是拆散付满伦（陈晓东 饰）和辛心欣（田中千绘 饰）这对相亲相爱的小情侣。看在钱的份上，十三豆接下这单任务，并迅速集结了李先梭（周晓鸥 饰）、溜溜（黄娟 饰）等一干名不见经传的演员，组成了一个棒打鸳鸯剧组。一场没有硝烟的爱情攻坚战悄悄拉开帷幕……©豆瓣', '刘桦', '吴兵', 5, 5453, 'tt6447804', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p678870532.jpg', 13.5, 36, 40.8, 7.5, 2.2, '0.247554,0.012361,-0.335809,0.372704,-0.180487,-0.264605,0.658406,0.301661,0.199689,0.081192,0.151347,0.476293,-0.212203,-0.093067,0.016352,-0.069854,-0.095402,-0.657403,-0.201910,0.100359,-0.156611,-0.322380,-0.075329,0.190902,-0.012962,0.086986,0.386341,-0.066388,-0.085355,0.502509,0.524761,-0.051888,0.049998,-0.108275,-0.092999,0.251322,0.061018,0.151379,0.161185,0.122274,-0.207459,-0.231078,-0.012459,-0.064253,0.093851,0.432421,0.552869,-0.192456,-0.066652,-0.078420,0.125572,-0.258292,-0.319328,0.010436,0.167501,-0.056178,0.237280,-0.001619,-0.028994,0.053363,0.226381,-0.006111,-0.686884,-0.106839,0.007204,0.135483,-0.719992,0.518584,-0.183787,-0.005850,-0.037421,-0.413275,0.150779,0.088318,0.130692,0.364414,-0.082438,0.135945,-0.499325,0.544259,-0.072892,0.082892,0.274698,0.399417,0.106112,-0.185665,0.139386,-0.063149,-0.225089,-0.099499,0.467261,-0.268293,-0.139069,-0.311454,-0.552398,-0.059376,-0.087532,-0.319834,0.098368,-0.279954,-0.116095,-0.445603,-0.123196,-0.486599,-0.366529,0.244729,0.411647,-0.142109,0.554804,-0.337833,0.096908,0.221125,-0.001032,-0.241072,0.427482,0.388675,-0.070242,-0.127725,-0.076949,-0.413518,0.076347,0.388391,0.425670,0.585353,0.066623,-0.385088,-0.439542,0.294508', '1316560', '1805685', '1578663', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4706257', '鼠来宝3', '喜剧', '愉快的假期来到，戴夫（杰森·李 Jason Lee 饰）带着花栗鼠艾尔文（贾斯汀·朗 Justin Long 配音）、西蒙（马修·格雷·古伯勒 Matthew Gray Gubler 配音）以及鼠姐妹登上豪华游轮，展开快乐自在的旅行。但是艾尔文他们玩的实在太High，在船上惹出不少的乱子，令戴夫颇为光火。顽皮的花栗鼠们玩耍风筝，谁知却令它们和戴夫以及老对头伊恩（David Cross 饰）一起坠入大海，漂流到一座荒岛之上。小家伙们在未知的丛林中展开了求生大冒险，与此同时还结识了美丽的女子佐伊（珍妮·斯蕾特 Jenny Slate 饰）。看似如天堂般的小岛，却隐藏着不为人知的秘密……本片荣获2012年美国少年选择奖最受喜爱奖项。©豆瓣', '贾斯汀·朗', '迈克·米切尔', 7, 16989, 'tt1615918', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1290403201.jpg', 1.3, 7.3, 44.6, 31.4, 15.4, '0.135502,-0.165087,-0.704773,0.501463,0.101675,-0.193095,0.866547,0.056975,-0.332724,0.001853,0.354685,0.402676,-0.382302,0.405447,0.422083,-0.127682,-0.489210,-0.233642,0.006402,-0.083338,0.078172,-0.328270,-0.274933,-0.060082,-0.087218,-0.172535,0.474068,-0.062097,0.079239,0.494189,0.350415,0.177363,-0.507912,0.354779,-0.249009,-0.043546,0.147256,0.366514,-0.084208,0.029507,-0.178680,0.023544,-0.281595,-0.177826,0.222882,-0.068684,0.821170,-0.453849,0.051334,-0.122642,0.032303,-0.168695,0.181721,-0.043660,0.171595,-0.107997,-0.067599,-0.091168,0.000892,0.111051,0.344470,-0.383461,-0.087472,0.196126,0.152143,0.310393,-0.312942,0.072909,0.171825,0.056777,0.059619,-0.239114,0.018697,-0.055388,0.273172,0.119109,0.133473,0.376737,-0.338158,0.213346,0.401069,0.081831,-0.274572,-0.133219,-0.389944,-0.340119,-0.098348,-0.091548,-0.443089,-0.149687,0.513736,-0.307229,0.083119,0.338706,-0.796958,0.051845,-0.033746,-0.335229,-0.160036,-0.337828,-0.133017,-1.008148,0.311759,-0.373263,-0.143215,0.134906,-0.133565,-0.211210,0.663506,-0.535643,0.229153,0.435007,0.084791,0.007907,0.523064,-0.053947,0.140724,-0.179811,-0.159758,0.413313,-0.105136,-0.126514,0.060270,0.307928,-0.383625,-0.133933,-0.476896,0.420303', '10466639', '2159244', '2269893', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4707209', '摇摆de婚约', '剧情', '与时尚杂志社编辑王顺佳（姚晨 饰）风生水起的爱情相比，她的事业近来陷入低谷。即将结婚的消息惹来单身女上司的妒忌，因此工作上屡屡受挫。还好男朋友的哥们张俊浩（朱雨辰 饰）意外出现在他们的生活里，为他们的生活又带来一些新鲜的趣味。正当顺佳全身心投入即将迈入婚姻殿堂的喜悦之时，她的男朋友吴巨源（郭晓冬 饰）却由于移情别恋而向她提出分手。顺佳失恋后，俊浩不仅给予顺佳无微不至的关心，而且为了安抚她的情绪，甚至陪着她去登记结婚。就这样，一对丝毫没有感情基础的男女莫名其妙的结婚了，不知这个美丽的错误能否成就一段浪漫的故事……©豆瓣', '姚晨', '鄢钷', 5.7, 37565, 'tt7149536', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p506963644.jpg', 4.9, 23.5, 56.2, 13.2, 2.3, '0.144054,0.116141,-0.826865,0.611707,-0.152729,-0.358589,0.751492,0.160831,-0.291333,-0.265746,0.053800,0.459654,-0.234228,0.362598,0.408991,-0.050266,-0.108506,-0.601215,0.166340,0.077058,-0.126052,-0.251572,-0.277074,0.026716,-0.314127,-0.188947,0.656686,0.061435,-0.198995,0.603380,0.214510,0.112849,0.056923,0.610463,-0.001126,0.059959,0.055872,0.438605,-0.476248,-0.112204,0.065335,-0.193466,-0.006868,0.420707,-0.110887,0.334301,0.727053,0.027068,-0.416856,0.087199,0.870826,-0.077947,0.104003,0.126752,0.131825,0.187514,0.174250,0.175141,-0.257952,0.119092,0.010734,-0.176210,-0.703174,0.053152,-0.041409,0.117856,-0.424207,0.539718,-0.028745,-0.085287,0.200409,-0.213634,0.068779,0.576667,0.313535,0.475177,-0.488264,0.206674,-0.262817,0.307241,0.727412,0.083887,0.015114,0.655226,-0.318473,-0.308537,0.011699,-0.026353,-0.716009,-0.065658,-0.008167,0.052270,-0.156093,0.311872,-0.442894,0.041652,-0.019992,-0.013860,0.109224,-0.431386,-0.026628,-0.552361,-0.173708,-0.395775,-0.540810,-0.046835,0.162434,-0.397597,0.599480,-0.815486,0.181585,0.591448,0.423649,-0.847227,0.653451,0.374692,0.089888,-0.316768,-0.304996,0.431525,-0.331762,0.010805,-0.175357,0.168302,-0.001678,-0.005562,-0.384967,0.552438', '27191829', '1301022', '5446226', '10574468');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4707225', '不是闹着玩的', '喜剧', '电影一直与阳春白雪相关，似乎很少有人把它与下里巴人联系在一起。可河南某小镇某小村，却发生了一件事，让电影与下里巴人进行了一次对接。村里的电影放映员蔡有才（李易祥 饰）一直有一个梦想，那就是亲自拍一部电影。这不是闹着玩的，有才果真开始实践起了拍电影之梦。围绕着鬼子进村的主题，有才开始寻找演员，构造场景，可这些非专业出身的演员和资金的限制，让片场状况百出也笑话百出，经过各种磨难，有才还是咬牙坚持了下来。本片为真人真事改编，全程用河南话进行对白。真实情形为河南许昌县灵井镇兴元铺村的农民赵兰卿发动村民一起自编自导自演了一部名为《鬼子进村》的电影，开创了农民自己拍电影的先河。©豆瓣', '李易祥', '卢卫国', 7.3, 5191, 'tt7547258', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2382564717.jpg', 2.5, 6.3, 32.1, 40.1, 19, '0.293872,-0.258316,-0.546332,0.586484,0.295314,-0.285455,0.667041,-0.105044,-0.429423,-0.172939,0.159067,0.552213,-0.446734,0.037986,-0.107717,-0.036812,-0.637464,-0.646251,-0.021737,0.050798,0.018214,-0.092227,-0.158982,0.014129,-0.210079,0.074831,0.568599,0.170072,-0.402028,0.097289,0.364370,-0.005421,-0.004224,0.261289,-0.100982,0.072809,-0.109903,0.016054,-0.306751,0.170144,0.259527,-0.312695,-0.377931,-0.009384,0.108813,0.320386,0.571731,-0.131071,-0.240243,0.151696,0.373296,-0.153154,-0.000147,-0.062363,0.264686,0.293525,0.413396,0.073428,-0.104426,0.190516,-0.233882,-0.086201,-0.795825,-0.053025,0.149241,0.082741,-0.461220,0.158467,0.077375,-0.208533,-0.001607,-0.354816,0.242624,0.403185,0.713853,0.320509,-0.294279,-0.223970,-0.424150,0.499283,0.647738,0.058837,-0.303505,0.551975,-0.034318,-0.429002,0.076891,-0.115621,-0.169751,0.192592,0.166954,-0.301801,-0.307177,-0.068604,-0.652127,0.154495,0.027591,-0.409979,0.090337,-0.230537,0.042105,-0.820298,-0.089790,-0.322587,-0.127438,-0.174439,0.323522,-0.204869,0.735200,-0.685482,-0.117690,0.658227,0.290546,-0.522512,0.544037,0.030863,-0.055123,0.007512,0.224722,-0.306396,-0.161546,0.581554,0.251565,0.444001,0.080715,-0.282659,-0.227838,0.570503', '3318306', '25928048', '2053515', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4707230', '恋爱通告', '喜剧', '流行乐坛大明星杜明汉（王力宏 饰）虽然功成名就，风头无量，但是内心的空虚却与日俱增，爱情之树更迟迟未能开花结果。一次车祸，让他邂逅了上海音乐学院民乐系的女孩宋晓青（刘亦菲 饰）。明汉为晓青超凡脱俗的气质所吸引，更被她优美绝伦的琴声所打动。在此之后，他和乐团伙伴兼好友魏志柏（陈汉典 饰）经过一番伪装打扮，悄悄潜入音乐学院。在此期间，二人和宋晓青、陶丽（曾轶可 饰）组成四人乐团参加学校的演出，明汉还帮助晓青追求民乐系才子慕凡（乔振宇 饰），期间更是闹出不少笑话。脱去繁华世界的虚伪装扮，明汉重返青涩纯真校园，收获了人生最为难得的礼物……本片为王力宏自导自演的处女作。©豆瓣', '王力宏', '王力宏', 5.9, 134629, 'tt1646214', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p574326303.jpg', 6.5, 22.3, 47.4, 16.6, 7.2, '-0.083155,0.008276,-0.398232,0.583123,-0.102341,-0.102474,0.575530,0.145345,-0.343432,-0.194515,-0.052613,0.421884,-0.371629,0.126236,0.280179,-0.220437,-0.190685,-0.497874,0.231185,0.079282,0.227902,0.105545,-0.065018,0.347728,-0.169722,-0.462309,0.750821,0.164212,-0.348109,0.633468,0.520013,0.069619,-0.273479,0.258599,-0.099228,-0.124190,0.039743,0.416071,-0.173716,0.052532,-0.216675,-0.496964,-0.375237,0.297308,-0.210102,-0.040334,0.703873,0.035230,0.036516,-0.079990,0.548808,-0.021322,0.117960,-0.179438,0.070106,0.080384,0.450994,0.218936,-0.034796,0.116680,-0.027395,-0.185904,-0.450790,0.198012,0.432292,-0.164161,-0.365231,0.479762,0.009727,-0.111579,0.047036,-0.216261,0.083616,-0.045058,0.222498,0.269008,-0.073837,0.137066,-0.277850,0.595923,0.518809,0.055950,-0.081160,0.472566,-0.336836,-0.393234,-0.071107,-0.294000,-0.537033,0.427802,0.092663,-0.155960,0.283910,0.033224,-0.636877,-0.115835,-0.263392,0.101982,0.055750,-0.465467,0.074777,-0.863078,-0.206139,-0.251823,-0.211732,-0.096204,0.343192,-0.312922,0.806668,-0.643209,0.060789,0.270128,-0.018693,-0.466788,0.485734,0.080524,0.092707,-0.150013,-0.279180,0.262575,-0.206464,-0.044517,-0.179216,0.491452,-0.179985,-0.387508,-0.410941,0.272088', '3811356', '5403927', '1322847', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4707237', '我的野蛮女友2', '喜剧', '一个月前，尚真（熊黛林 饰）来到韩国首尔，偶遇了向女友求婚失败的书店老板健宇（立威廉 饰），健宇为人温厚善良，让沉浸在遭受男友背叛的痛苦中的尚真忽然萌生了一个想法：要利用健宇帮自己破坏男友的婚礼。于是，健宇跟随尚真来到中国，回家的尚真暴露出了“野蛮”的一面，对远道而来的国际友人疏于照顾。尚真的表妹永真（冯媛甄 饰）和姐姐一样令男人头疼，担任跆拳道教练的永真班中有一名缺乏男子气概的学员志凯（何炅 饰），志凯对永真仰慕有加，但却时常在永真的拳脚下吃亏。健宇陪伴尚真进行破坏婚礼的准备工作，却在演习中得罪陌生人，而此时，距离婚礼的日期越来越近了……©豆瓣', '熊黛林', '马伟豪', 3.8, 8083, 'tt1997605', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p688188139.jpg', 40.8, 34.4, 20.6, 2.7, 1.5, '-0.076960,-0.007746,-0.527590,0.485407,-0.086573,-0.337079,0.547327,0.232956,-0.365229,-0.329992,0.385220,0.623121,-0.240371,0.286658,0.531591,-0.232720,0.009409,-0.697710,-0.077969,-0.027368,-0.111239,-0.389210,0.024483,-0.192771,-0.232087,-0.371252,0.671941,0.126399,-0.145995,0.636703,0.187661,0.154089,0.011819,0.562501,-0.091927,-0.179040,0.058274,0.268249,-0.387029,0.200450,0.062591,-0.155256,-0.073592,0.101021,-0.016573,0.334319,0.552769,-0.157197,-0.203314,-0.171023,0.352990,-0.199825,0.002777,0.118442,0.265537,0.057926,0.165100,0.030507,-0.291251,0.154233,-0.091674,-0.212663,-0.291853,0.028517,0.296940,-0.132806,-0.620278,0.553468,-0.145053,-0.062302,0.244968,-0.384943,0.147797,0.474896,0.212793,0.382049,-0.209818,0.430267,-0.187259,0.009846,0.679972,0.092417,0.080549,0.205418,-0.195357,-0.251663,0.193161,-0.016626,-0.566008,0.044453,-0.129092,-0.179910,0.056600,-0.016281,-0.459279,-0.205137,-0.126942,0.164412,0.092069,-0.565227,-0.133415,-0.626777,0.032282,-0.287393,-0.175292,0.156358,0.054193,-0.311451,0.606601,-0.955113,0.344635,0.457063,0.543091,-0.543586,0.704697,0.308948,0.008163,-0.136416,-0.205347,0.216138,-0.106554,0.094234,-0.129819,0.179806,-0.100724,-0.324534,-0.397564,0.211769', '3445516', '35030151', '1292219', '1395231');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4707585', '战国', '剧情', '《战国》豆瓣官方小站：http://site.douban.com/113652/战国时代，七雄并起。传说一代纵横家鬼谷子将毕生绝学传给得意门生——尚未被膑便自称为膑的孙膑（孙红雷 饰），遂引得各方诸侯相机而动。在齐魏之战中，孙膑凭借才学大挫齐国锐气，虽然沦为阶下囚，但深得齐王（中井贵一 饰）赏识，将其推荐为田忌（姜武 饰）之女田夕（景甜 饰）的座上宾。不久，河洛大会举行，各国勾心斗角，局势紧张。孙膑危急之时代表齐国赛马，大出风头。在此之后，他被同门师兄庞涓（吴镇宇 饰）引入魏国。魏王为人多猜忌，庞涓又忌恨孙膑独得鬼谷子的绝学，故而设计剜去孙膑的膝盖骨。一场混杂了友情和奇谋的旷世传奇就此拉开血腥的大幕……©豆瓣', '孙红雷', '金琛', 3.9, 42107, 'tt1885448', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p920568280.jpg', 41.3, 30.7, 21, 4.9, 2.1, '-0.058178,0.375285,-0.436663,0.663238,0.304316,0.013808,0.061418,0.235680,-0.499790,-0.266114,0.223051,0.720479,-0.373589,-0.234195,0.092639,-0.247698,0.113868,-0.834895,-0.192165,-0.013659,0.166187,-0.131729,-0.260040,-0.006780,-0.367575,-0.104338,0.551684,0.295780,-0.389923,0.432867,0.337123,0.065569,-0.126656,0.506295,-0.056206,-0.175312,-0.193435,0.037246,-0.356619,-0.217982,-0.258958,-0.572892,-0.281812,0.098474,-0.225955,0.091937,0.360628,-0.296157,0.246480,-0.259747,0.309764,0.046657,-0.010718,0.106978,0.395403,0.117735,0.142709,0.267139,0.178867,-0.018158,-0.048668,-0.034414,-0.606560,-0.141415,0.222166,-0.038024,-0.316049,0.779285,-0.175928,-0.193804,-0.304745,-0.300900,0.169371,0.173179,0.397247,-0.042884,0.126840,-0.212570,-0.332407,0.343581,0.348297,-0.211769,0.079837,-0.168035,0.373742,-0.429511,0.272692,-0.430587,-0.292455,-0.011079,0.631381,-0.194802,0.402472,0.423504,-0.331149,-0.335693,-0.169553,0.238025,0.166461,0.007342,0.259407,-0.374524,-0.152348,-0.204569,-0.190652,-0.188136,0.709062,-0.339459,0.844465,-0.420702,-0.072941,-0.065619,-0.017698,-0.542835,0.252281,0.124691,0.415406,0.057698,-0.413247,0.117112,0.294704,0.253604,0.207316,0.372063,-0.309156,-0.356204,-0.370045,0.153086', '27602116', '30465281', '1765009', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4707596', '财神客栈', '喜剧', '在小小的白马城，居住着两个情投意合的好哥们儿龚少爷（谢霆锋 饰）和巴少爷（张家辉 饰），二人携手报名当捕快，无奈虽然空有一身本领和远大志向，却只能委身厨房洗衣间，做一名任人驱使任任打骂的实习捕快。这一日，城中大户张员外家进入强梁，全家老小悉被杀害，无一幸免，家中价值连城的白玉观音也不知去向。龚少爷勘查现场，对凶手作出了正确的推断。虽然被率领十二金衣捕快的神捕头铁无情（何家劲 饰）采纳，结果反被同一衙门的前辈屈打成招，问下死罪。幸而在牢中结识了“Twins侠盗”水龙女（黄奕 饰）和火龙女（蔡卓妍 饰），一番打斗后终于逃出生天。为了追查白玉观音的下落，他们一路前往关外的财神客栈，一段江湖传奇就此展开……©豆瓣', '谢霆锋', '王晶', 5.3, 47394, 'tt1941705', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1034383450.jpg', 9.9, 30.4, 46.3, 10.4, 2.9, '0.265149,0.067179,-0.318886,0.272877,0.031102,-0.243582,0.561178,0.167899,-0.604141,-0.378329,0.388708,0.597286,-0.152205,0.115122,0.171594,-0.162073,-0.148631,-0.610747,-0.293653,-0.235433,-0.155102,-0.225411,-0.044203,0.009494,-0.114752,0.025912,0.099688,0.309775,0.160191,0.626695,0.549121,0.198765,-0.540386,0.100403,-0.325212,0.128443,0.103622,0.069370,-0.168842,0.087574,-0.206718,-0.130647,-0.069601,-0.126219,0.096558,0.387169,0.551153,-0.418182,0.025528,-0.166102,0.030460,-0.113777,0.198778,0.300744,0.358153,-0.033020,0.203675,0.365164,-0.113745,-0.069564,0.021042,-0.051414,-0.507437,0.134114,0.499976,-0.107243,-0.627508,0.051164,-0.064145,-0.124203,-0.093087,-0.277640,0.099832,0.182944,0.235254,-0.016646,-0.039425,-0.044265,-0.606107,0.481262,0.464853,0.037957,0.237434,-0.279412,0.301130,-0.472238,0.032755,-0.209506,-0.118683,-0.169736,0.324686,0.052179,0.022293,-0.317785,-0.331986,-0.123730,-0.358743,0.226358,-0.188946,-0.196337,0.026435,-0.471584,0.146683,-0.183068,-0.268162,0.141516,0.282997,0.116974,0.474654,-0.451460,0.022077,0.072429,0.294640,-0.474715,0.597042,-0.028675,0.149831,-0.161876,-0.129107,-0.136834,0.516761,0.561459,0.310518,0.428476,-0.280495,-0.274567,-0.439959,0.048626', '2976123', '1305440', '1451563', '1306313');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4709671', '胡佛', '剧情', '年过七旬的美国联邦调查局局长埃德加·胡佛（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）应《犯罪纪实》之邀口述个人回忆录。胡佛向回忆录代笔作者讲述了他自1919年以来的重要人生历程：逮捕左翼分子领袖、缉拿臭名昭著的黑帮头目、破获震惊全美的林德伯格绑架案等等。依据胡佛的讲述，他力排众议，改组联邦调查局，引入高科技侦查手段，尽心尽力为美国社会的和平与稳定而操劳。然而另一方面，他的私人生活却成为了他想要极力掩饰的部分。就在胡佛回顾自己一生的时候，美国社会依然有诸多动荡因素存在。胡佛任用多年的私人助理克莱德·托尔森（艾米·汉莫 Armie Hammer 饰）也似与他保持着不寻常的关系……©豆瓣', '莱昂纳多·迪卡普里奥', '克林特·伊斯特伍德', 7.2, 44732, 'tt1616195', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1351876164.jpg', 0.4, 3.7, 43.1, 42, 10.8, '0.206786,-0.050714,-0.589416,0.653937,0.090475,-0.238099,0.580097,0.088477,-0.569153,-0.452365,0.152083,0.542132,0.028933,-0.090292,0.143751,0.006857,-0.498190,-0.716623,-0.026773,-0.037347,0.072367,-0.573964,-0.552283,-0.547786,-0.148358,-0.409266,0.543024,0.060972,-0.273768,0.115034,0.124359,0.502536,0.036660,0.309834,0.188068,-0.132973,0.283965,-0.128929,-0.480953,-0.096270,-0.031402,-0.404312,-0.207153,0.167246,0.103453,0.438341,0.311980,-0.280453,-0.202433,0.014225,0.402411,-0.416324,-0.065268,0.002034,0.416025,0.169220,-0.039993,0.705908,-0.138691,-0.157387,-0.072800,-0.119319,-0.687122,-0.341860,0.071519,0.367396,-0.395719,0.437325,-0.281693,0.128794,-0.203856,-0.321136,-0.036504,0.334152,0.212701,0.272884,0.071677,0.194641,-0.267667,0.510999,0.365546,-0.087593,-0.487470,-0.067684,-0.466969,-0.356315,-0.071373,-0.358912,-0.371200,-0.274355,0.117327,-0.271913,-0.081341,0.600508,-0.363021,-0.106883,-0.352879,-0.213340,-0.112889,-0.259500,0.155893,-0.635000,-0.383854,-0.393534,-0.183703,-0.168622,0.153691,-0.378087,0.666221,-0.579333,0.171181,0.719036,0.073430,-0.537514,0.676143,0.253553,0.132063,-0.440678,-0.079577,0.360537,0.122071,0.104818,-0.028812,0.065924,0.103983,-0.172913,0.055172,0.220459', '25932086', '1293433', '4301278', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4709904', '前度', '爱情', '恋爱超过一次的人，分了手的人，属于过去的人；毕竟都是我们爱过的──《前度》。刚从外地回港的陈均平(陈伟霆 饰)及其现任女友阿诗(诗雅 饰)，在机场巧遇前度女友──周怡(钟欣桐 饰)。周怡与旅行作家阿树(周俊伟 饰)正准备出发前往长途旅行，却发生争执闹至分手。为这次旅行而下定决心辞职、退掉公寓的周怡，一时无家可归，获对她念念不忘的陈均平和其女友阿诗收留。周怡前往二人的新居暂住，发现眼前追求物质生活的陈均平，早已不是曾经拥有梦想，一起共渡患难的陈均平。唯一不变的，是陈均平对周怡这位曾经分分合合，纠缠多年的前度思念如昔，始终没有放下过。短短两天内， 面对新居中熟悉的一事一物，处处勾起周怡与过往前度的回忆，30小时，回顾六年来的爱情游历。在和陈均平分手后，她遇上为她治疗失恋情伤的医生(杜汶泽 饰)，也爱过刺激浪漫的古惑仔阿升(向佐 饰)，有些人在她生命中仅短暂停留却刻骨铭心，有些人守候在身边却浑然不觉，就像陈均平的死党阿苏(曾国祥 饰)，见证着周怡与陈均平的几度复合与分手，只是默默地以朋友的身分守护着二人。每一次分手都是遇上下一位的机会，每一次错误结合令大家成为“前度”。可是周怡与陈均平又再共处一室，连番斗气却又极具默契，明明关系亲密却又刻意保持距离，二人曾经相爱的证据一一涌现，多年来纠缠累积的思念瞬间爆发……', '陈伟霆', '麦曦茵', 7, 201955, 'tt1611818', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p509221460.jpg', 1.4, 7.6, 41.7, 37.2, 12.1, '0.158720,-0.289417,-0.725372,0.534679,-0.055762,-0.541672,0.935111,-0.028783,-0.569102,-0.283588,0.156800,0.560789,-0.272424,0.326625,0.403738,-0.188012,-0.073397,-0.690467,0.164884,-0.132042,-0.164304,-0.381294,-0.173396,0.135435,-0.097377,-0.162819,0.652372,0.030290,-0.072965,0.649334,0.265654,0.029089,-0.414612,0.616008,-0.090475,-0.075145,-0.092033,0.415233,-0.695775,0.027260,-0.043955,-0.184551,-0.317319,-0.102954,-0.104301,0.325752,0.520100,0.010489,-0.128133,0.034877,0.183313,-0.092269,-0.158972,-0.103019,0.137859,0.246801,0.417213,0.307645,-0.256801,0.013757,-0.027351,-0.011112,-0.418458,0.191531,0.102344,0.029994,-0.639674,0.657516,-0.139897,-0.103694,0.215620,-0.248846,0.067800,0.454738,0.347661,0.368733,-0.262909,0.085042,-0.238550,0.203108,0.836085,0.211480,-0.216295,0.374326,-0.119548,-0.342258,-0.001939,-0.083909,-0.467916,0.065765,-0.117076,0.188554,-0.127627,0.213003,-0.574684,0.090809,-0.275137,0.043063,0.410646,-0.433059,0.023210,-0.538528,-0.232715,-0.493843,-0.462466,0.259087,0.079642,-0.393106,0.374996,-0.813244,0.269908,0.383706,0.560146,-0.576857,0.678568,0.509581,-0.065829,-0.238194,-0.002422,0.471025,-0.119968,0.278318,0.110328,0.174026,-0.036614,0.426139,-0.545228,0.393738', '1308755', '1291835', '3111650', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4711195', '爱出色', '喜剧', '北漂女汪小菲（姚晨 饰）来时尚杂志面试，女老板ZOE（陈冲 饰）因丈夫出轨正闹离婚，无暇顾及，让她从实习生做起。该杂志约画家栾亦鸿（刘烨 饰）拍摄时尚照片。在换衣间，一帐之隔，亦鸿偷窥到跳舞的小菲，遭到后者痛击。两人不打不相识，亦鸿追求小菲，并帮其谋得了跳舞减肥班老师的职位。小菲刚开始对他产生好感时，却发现他的前女友柯敏（莫小奇 饰）竟然还在纠缠。一怒之下，小菲扯谎要嫁，逼得亦鸿在时尚发布会上发狂。几经周折，正当小菲下定决心，接受亦鸿时，后者却逃避现实，留信一封，去了纽约……本片有20大国际知名名牌赞助，号称国内第一步时尚大片，汇集了洪晃、俞飞鸿、高圆圆、吕燕、岳敏君、ZING（王菲御用造型师）等诸多明星©豆瓣', '姚晨', '陈奕利', 5.9, 47066, 'tt1639822', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p766644636.jpg', 4.8, 20.7, 54.3, 17.1, 3.2, '0.057093,-0.043079,-0.595217,0.188423,0.085805,-0.058639,0.285864,0.364563,-0.024440,-0.211920,0.178748,0.652513,-0.425558,0.190057,0.320556,-0.014360,-0.111963,-0.565726,0.341002,0.039158,0.046640,-0.017730,0.007748,0.092458,-0.145349,0.086353,0.325081,-0.191470,-0.304059,0.405700,0.588271,0.013382,-0.256019,0.523073,-0.075973,0.007702,0.087225,0.155924,-0.130169,0.089077,0.051294,-0.260507,-0.074612,0.100943,0.045923,0.280741,0.480188,0.355733,0.122774,0.132730,0.603859,-0.054953,0.063281,0.029185,0.373723,0.125508,0.059484,0.028522,-0.189339,0.231423,-0.070627,0.070174,-0.241981,0.154380,0.209621,0.067167,-0.372631,0.525656,-0.085950,-0.030412,0.100214,-0.263193,-0.047821,0.135188,-0.013628,0.124118,0.180439,0.238814,-0.228304,0.388616,0.234338,0.316331,0.257312,0.243164,0.041890,-0.133445,-0.021408,0.122384,-0.402972,-0.132301,0.228110,-0.253645,0.030272,-0.117041,-0.438561,-0.249812,-0.130281,0.136585,0.104588,-0.103423,-0.019139,-0.772435,0.048718,-0.038608,-0.130745,-0.051877,0.199963,-0.367623,0.435089,-0.456972,-0.145768,0.445769,0.426139,-0.622916,0.475586,0.103745,-0.088016,-0.170675,-0.292616,0.135442,-0.026741,0.030069,-0.042592,0.291873,-0.004500,-0.143819,-0.177718,0.103597', '1484091', '34961898', '24751811', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4712730', '雌雄莫辨', '剧情', '影片改编自乔治·摩尔（George Moore）的短篇小说《阿尔伯特·诺伯斯的奇异生活》。Albert Nobbs（格伦·克洛斯 Glenn Close 饰）在一家专门给上层人士提供寻欢作乐的场所的酒店工作。他生性害羞做事谨慎，深得客人和老板的赏识，并坚守着最大的秘密 ——“他”其实是一个女人。他忙碌但乐在其中，甚至悄悄积攒了一大笔钱，却没有人生目标。直到同样是女扮男装的粉刷工 Hubert Page（珍妮·麦克蒂尔 Janet McTeer 饰）来到酒店，Albert的内心第一次有了期盼，他决心走出自己的孤独世界，寻找自己的人生伴侣。于是他选中了酒店最美丽的女仆Helen（米娅·华希科沃斯卡 Mia Wasikowska 饰），可Helen心系新来的杂工。Albert能完成自己的人生目标吗？©豆瓣', '格伦·克洛斯', '罗德里戈·加西亚', 7.4, 16463, 'tt1602098', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1642052134.jpg', 0.5, 2.7, 36.1, 46.4, 14.3, '0.144237,-0.020364,-0.547638,0.563183,-0.429197,-0.335944,0.766962,0.392979,-0.510290,-0.343947,0.421973,0.744863,0.170878,0.127186,0.417943,0.352665,-0.369665,-0.400788,0.098704,-0.211529,-0.020179,-0.376502,-0.293839,-0.485683,-0.060557,-0.220775,0.386583,0.060459,0.110794,0.166639,0.228215,0.241141,0.125530,0.440025,-0.171550,-0.126305,0.435388,-0.075762,-0.050133,0.127631,-0.101177,-0.033446,-0.275615,0.215178,0.228952,0.422086,0.439123,-0.180187,-0.222190,0.047342,0.204822,-0.200185,0.066767,0.057147,-0.080885,-0.166293,0.341752,0.140919,-0.194569,-0.034279,0.035862,-0.232927,-0.885474,-0.115814,0.206542,0.096393,-0.579122,0.593988,-0.154128,-0.115148,0.038501,-0.434934,0.096424,0.254669,0.222115,0.246583,-0.020381,0.123057,-0.619324,0.270301,0.415348,0.015005,-0.054056,0.501284,-0.594051,-0.376185,0.084388,-0.144353,-0.840138,-0.284010,0.348713,0.029140,-0.040125,-0.085791,-0.634995,-0.018514,-0.233337,-0.268843,0.198954,-0.522155,-0.167990,-0.666644,-0.150130,-0.446189,-0.238113,-0.189918,0.007454,-0.296341,0.756524,-0.960339,0.230702,0.708953,-0.004821,-0.603912,0.902202,0.048900,0.115183,-0.171406,-0.178130,0.484915,-0.093879,0.429335,-0.170844,0.405050,-0.001012,-0.236092,-0.393356,0.626556', '1793491', '1308842', '1783461', '25911694');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4713748', '当我们离开', '剧情', '婚姻不幸的土耳其女子乌马伊（西贝尔·凯基莉 Sibel Kekilli 饰）不仅跟丈夫毫无爱情可言，更时常遭受丈夫的家庭暴力。悲剧的婚姻致使乌马伊带着儿子逃回了娘家德国。然而她悲剧的命运并没有因此终止，迎接她的非但不是一个可以依靠的温暖的家，而是家人的冷嘲热讽。为了声誉，家人居然极力劝她按照传统习俗，把儿子送回给土耳其的丈夫抚养。面对家人的冷眼和唾弃，善良宽容的乌马伊并没有放弃，她坚持自己抚养儿子，不得已下寄居在朋友家。然而这仅仅是悲剧的序曲，乌马伊带着儿子去看望病危的父亲，却不曾想到，等待她的，居然是自己弟弟的枪口。本片不仅荣获2010年第60届柏林国际电影节欧洲院线大奖，还获得欧洲电影奖、德国电影奖在内的六次提名，三项大奖。©豆瓣', '西贝尔·凯基莉', '菲奥·阿拉达戈', 8, 6730, 'tt1288376', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2433599695.jpg', 0.6, 2.2, 20.7, 51.6, 25, '-0.218385,-0.040823,-0.838310,0.743722,-0.062903,-0.346975,0.398255,0.279813,-0.387887,-0.121254,0.297408,0.743355,0.217872,0.216074,0.216529,-0.094185,-0.174039,-0.584465,-0.187913,0.301067,-0.105626,-0.425755,-0.043747,-0.099040,-0.074720,-0.343480,0.630323,-0.108629,-0.311823,0.312066,0.424037,0.265846,0.002791,0.385109,-0.299122,0.321498,-0.019843,0.194527,-0.526296,0.444538,0.158528,-0.252045,-0.166531,0.487726,0.116623,0.443830,0.553297,-0.346885,0.056076,-0.240185,0.545370,-0.414190,-0.122261,0.100643,0.118411,-0.203897,0.301703,0.353666,0.004459,-0.016627,0.371206,-0.190129,-0.803600,-0.011130,0.229365,-0.116371,-0.752037,0.652779,-0.210634,0.169444,0.010976,-0.098553,0.233723,0.301915,0.041443,0.320802,-0.478619,0.215536,-0.616673,0.382856,0.627895,-0.212717,-0.180518,0.252675,-0.353119,-0.187385,0.275752,-0.673812,-0.706381,0.271826,0.170808,0.069106,-0.118619,0.245075,-0.146531,-0.079848,-0.353949,-0.265670,0.374893,-0.615760,0.134572,-0.343772,0.139894,-0.249345,-0.435661,-0.085415,0.029792,-0.435718,0.610231,-0.435610,0.393976,0.588184,0.509784,-0.693025,0.802404,0.390004,0.184109,-0.134791,-0.138237,0.410839,-0.085486,0.031039,-0.013969,-0.251886,0.099167,-0.065701,-0.075729,0.526181', '30163500', '1456503', '30279170', '1397550');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4718369', '白鹿原', '剧情', '传说中白鹿庇佑的白鹿原上，世代居住着同根家族白、鹿两姓子孙。时代变迁，清朝覆灭，民国建立。现任族长白嘉轩（张丰毅 饰）之子白孝文（成泰燊 饰）、乡约鹿子霖（吴刚 饰）之子鹿兆鹏（郭涛 饰）与白家长工鹿三之子黑娃（段奕宏 饰）情同手足，成年后各赴前程。黑娃与渭北郭举人家的小女人田小娥（张雨绮 饰）私通败露，田小娥亦被族长拒于祠堂之外，两人遂迁至慢坡窑洞内度日。加入共产党的鹿兆鹏从城里带回革命浪潮，黑娃成为中坚力量，国共分裂后兄弟俩被迫逃亡。鹿子霖乘机霸占独自留守的田小娥，并设计利用她陷害下任族长白孝文，引发族内轩然大波……风云变幻的时局下，素有“仁义”之名的白鹿村内纷争不断，古老的土地面临着翻天覆地的变化。本片改编自陈忠实先生第四届茅盾文学奖作品《白鹿原》。原著时间跨度长达半个世纪，影片截取其中1912年到1938年间的动荡变迁，原生态的秦腔演绎与苍茫的麦田取景令人沉醉。', '张丰毅', '王全安', 6.4, 120925, 'tt1727396', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1624660243.jpg', 2.9, 13.6, 49.4, 26.9, 7.2, '-0.109853,0.195485,-0.564916,0.452531,0.603175,0.079890,0.345300,0.277601,-0.492539,-0.361409,0.278802,0.510514,-0.004643,0.043897,0.148266,-0.176098,-0.314323,-0.455531,-0.362481,-0.035830,0.060834,-0.032242,-0.242047,0.041089,-0.339336,-0.162864,0.663531,0.308913,-0.403772,0.421495,0.059829,0.224594,-0.692749,-0.129191,-0.025678,0.304190,-0.192899,0.206477,-0.584211,0.007487,-0.498577,-0.131825,-0.179963,-0.314164,-0.085051,0.216477,0.439321,-0.499780,0.188689,-0.468516,0.344096,-0.167348,-0.297556,0.097467,0.461062,0.134271,0.336252,0.669675,-0.133259,-0.123616,0.115199,-0.290658,-0.421625,0.044896,0.350440,0.199930,-0.551079,0.415676,0.257549,-0.331141,-0.141455,-0.220742,0.201783,0.437883,0.352435,0.223906,-0.249334,0.099538,-0.449681,0.336140,0.445562,-0.161620,-0.141232,-0.393524,0.052490,-0.327457,-0.020600,-0.490437,-0.429410,-0.131780,0.313886,-0.151507,0.285547,0.636126,-0.536062,-0.075602,-0.217411,-0.005761,0.418893,-0.115733,-0.013469,-0.471133,-0.288020,-0.167479,-0.011350,0.016061,0.373086,-0.347676,0.472900,-0.270854,0.197074,-0.119977,0.243195,-0.582069,0.285153,-0.021964,0.309267,-0.229553,-0.155791,0.366308,0.097158,0.296239,-0.096568,0.031907,-0.266235,-0.203536,-0.120253,0.071513', '1303390', '1300060', '35087486', '26575103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4719384', '哀乐中年', '剧情', '1920或30年代的上海。创办小学多年并自任校长的陈绍常（石挥）早年丧妻，独自抚养两子建中、建平和一女建英。与他一起生活的大姐劝他续弦，他虽也有心，却因目睹挚友的爱女刘敏华备受后母虐待，断了念头。不久，挚友亡故，敏华辞别他后随后母迁居外地，一别十年。两人再见面时，敏华（朱嘉琛）已成长为独立自强却不失贤淑的新女性，因不愿再受后母摆布，她拜托绍常介绍一份工作。随后，她成为绍常的同事。成年的建中（韩非）如愿以偿成为某家银行的职员，因得经理赏识，他结识其女冯丽君（李浣青），很快变作其乘龙快婿，社会地位日益提高。建中夫妇认为绍常卑微的小学校长身份丢了他们的脸，劝他退休在家做老太爷，绍常虽一百个不情愿，却也乖乖听命。敏华接下他的工作。只是赋闲在家的日子不好过，每日时间都似他那块坏掉了的老怀表般静止不动。而将无聊心情讲给家人听时，家人或怨他有福不懂享、或自忙自事无暇顾他，他的失落一日多过一日，与建中夫妇的矛盾亦越来越多。又到一年清明时，拜祭亡妻时，绍常遇见前来祭母的敏华，感慨人到老年只能等死，敏华却认为人在中年的他正处于事业的黄金期，劝他再回学校教书。而听从敏华建议偷偷瞒着建中再回学校教书一事漏泄后，建中对他的态度更加冷淡，但他已铁了心。“天意怜幽草，人间爱晚晴”，其后，他无意间发现自己与敏华早已两情相悦，决定与她结婚，此事更令建中夫妇大为恼火。', '石挥', '桑弧', 9.3, 14265, 'tt1580409', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2151942226.jpg', 0.2, 0.2, 3.7, 27.4, 68.5, '0.040966,0.102098,-0.562827,0.214445,-0.110036,-0.639923,0.376657,0.411952,-0.594955,-0.305207,0.130925,0.728079,0.061568,0.282224,0.001350,-0.078731,-0.194009,-0.364468,0.169330,-0.129392,0.134939,-0.321591,0.262152,0.056980,-0.217091,-0.114100,0.420241,-0.219044,0.146116,0.474568,-0.002986,0.162390,0.216056,0.414421,-0.176936,0.140010,-0.133449,0.201466,-0.453900,-0.105098,0.263607,-0.185463,-0.466383,0.000631,0.109106,0.231926,0.477301,0.134756,-0.348531,-0.349305,0.331573,-0.106715,-0.043022,0.070142,0.309267,0.083002,0.127128,0.495807,-0.386462,0.018629,-0.076166,0.143722,-0.311868,0.116539,0.062521,0.052630,-0.454111,0.418695,0.031136,-0.025121,-0.202840,-0.328252,0.025691,0.358468,-0.195199,0.220697,-0.238463,0.117902,-0.263446,0.363314,0.640898,0.058815,-0.107339,0.203965,0.064993,-0.112309,0.431411,-0.278570,-0.598741,-0.123533,-0.021087,0.102368,-0.275284,0.226059,-0.134870,0.018870,-0.408207,0.194990,0.121561,-0.400257,-0.037534,-0.140845,-0.083723,-0.398330,-0.445621,-0.137564,0.331385,-0.219752,0.489596,-0.572283,0.172147,0.097276,0.514597,-0.640033,0.554675,0.235133,0.243693,-0.307357,0.066474,0.125404,-0.138531,0.169164,0.176924,-0.031106,0.027323,-0.118893,-0.277931,0.118006', '1308035', '6890343', '1299624', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4723944', '飞砂风中转', '喜剧', '和义盛坐馆火水（方中信 饰）在筛选马仔后备军时，被一个开餐馆的厨师火腩（陈小春 饰）所吸引，后者做的叫花鸡味道鲜美，令他难忘。从此，他对火腩特别照顾，委以重任。找到了保护伞的火腩可以继承祖业，跟妻子（叶璇 饰）夫唱妇随经营义盛小馆，并盘算让儿女进入名校就读。正在此时，金融危机来临，方中信遇到困难，堂主之位不保，此时他希望能够让火腩做接班人，稳定军心。然而，和义盛开山祖师后人十三妹（余安安 饰）却力荐刚出狱的儿子燕子文（郑伊健 饰）出任堂主之位。于是，两个本不想做堂主的后起之秀被架上了PK台。火腩只想安心经营自己的饭店，而燕子文则希望进入大学进修，无心恋战的两人将面临一场怎样的对决呢？©豆瓣', '郑伊健', '庄文强', 6.4, 18652, 'tt1611840', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p767197706.jpg', 3.4, 14.4, 49, 25.9, 7.2, '0.031883,-0.084873,-0.454833,0.450544,-0.026785,-0.241660,0.316199,0.564728,-0.416420,-0.259825,0.071189,0.671049,-0.037552,0.308851,0.192609,-0.024332,0.106762,-0.712181,0.085143,-0.141091,-0.007774,-0.187052,0.052632,-0.096852,-0.141039,-0.071356,0.697636,0.188122,-0.089952,0.323149,0.307728,0.097435,0.213032,0.187705,-0.082360,-0.164428,-0.104878,0.102707,-0.402935,0.231162,0.083365,-0.284888,-0.173644,-0.028879,0.346467,0.177272,0.530662,-0.151130,-0.168465,-0.311404,-0.043730,-0.229281,0.041714,0.121349,0.019771,0.068919,0.104972,0.315065,-0.260955,0.001618,0.066997,-0.239346,-0.782796,0.033782,0.237121,-0.011512,-0.578736,0.371042,-0.127205,-0.075473,0.111646,-0.196572,0.314985,0.484753,0.323490,0.396415,-0.264119,0.341922,-0.479098,0.321931,0.613245,-0.022076,0.053203,0.097085,0.267511,-0.296060,0.220185,-0.320678,-0.260080,0.074967,0.232832,0.289410,0.199949,-0.159918,-0.265468,-0.146560,-0.250313,-0.151479,0.167371,-0.496827,0.069454,-0.323895,0.033646,-0.021937,-0.050536,0.063942,0.208833,-0.457879,0.750027,-0.767441,0.050775,-0.067131,0.303256,-0.797095,0.579200,0.216743,0.257828,-0.420426,-0.068474,-0.132098,0.121618,0.234261,0.254995,0.211526,-0.225171,-0.372403,-0.193660,-0.007908', '26678784', '1877596', '4301278', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4724373', '死神来了5', '惊悚', '某公司组织一次远游，虽然员工们各怀心事，不过他们还是踏上了欢乐的旅途。在经过一座巨大的吊桥时，年轻人山姆（Nicholas D''Agosto 饰）突然看到幻象，幻象中大桥开始垮塌，包括他、同事、朋友在内无数人在这起事故中遇难。当他从幻象中醒来时，周边的种种迹象表明那场灾难即将到来。慌乱之中，他和朱莉（艾玛·贝尔 Emma Bell 饰）、皮特（Miles Fisher 饰）、坎蒂丝（Ellen Wroe 饰）、奥利维亚（Jacqueline MacInnes Wood 饰）等8个人下了车。灾难随即发生，山姆等人成为车上仅有的幸存者。但是命运并未偏袒这几名幸运儿，死神仍时刻逡巡在他们的周围。死神来了，无论逃到天涯海角也没有用……©豆瓣', '麦尔斯·费舍', '史蒂文·奎里', 6.8, 111008, 'tt1622979', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1084300022.jpg', 1.3, 8.9, 50.1, 28.5, 11.2, '0.219936,0.006187,-1.013875,0.138773,0.062672,-0.056637,1.079651,-0.153014,-0.696908,-0.156219,0.501152,0.710478,-0.394026,0.225693,0.337896,-0.244623,-0.806764,-0.718317,-0.011787,-0.329107,-0.446299,-0.096346,-0.287648,-0.167244,-0.143140,-0.112182,0.516175,0.443421,0.120219,0.485530,0.219895,0.251928,-0.439919,0.750715,-0.090416,0.117363,0.133930,0.037954,-0.162074,0.037459,-0.290305,-0.468699,-0.359684,0.222069,-0.053842,0.471529,0.687289,-0.493545,0.008260,0.100261,-0.128006,-0.104655,0.226880,0.239993,0.455852,0.052776,0.269894,0.194161,-0.102753,0.006095,-0.057483,0.163948,-0.473947,0.001058,-0.059191,0.403441,-0.400345,0.440630,0.181193,0.029980,0.172637,-0.174046,0.305132,0.190787,0.434695,0.128343,-0.208979,-0.088813,-0.356218,-0.054616,0.755878,-0.011783,-0.257291,0.307224,-0.154677,-0.252368,-0.213485,0.206276,-0.278326,0.072786,0.452109,0.276194,-0.128692,0.363129,-0.555881,0.138097,-0.217196,-0.378521,-0.482783,-0.238354,-0.311319,-0.632665,0.062046,-0.272120,-0.213351,0.242930,-0.088473,0.049092,0.581401,-0.713364,0.276117,0.351743,0.176034,-0.270416,0.641787,-0.134099,0.194032,-0.237067,-0.025918,0.181557,-0.114935,0.506857,0.048264,0.331610,0.005608,-0.034300,-0.136057,0.355366', '3011051', '10733357', '1309297', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4724586', '我家乐翻天', '喜剧', '十二岁的小多（Chawin Likitjareonpong 饰）出生于喜剧世家，他的父亲和爷爷都是十分优秀的喜剧演员，所以，父亲希望小多能够和他一样，在舞台上给观众们带来快乐和欢笑。然而，这对于小多来说却是一个几乎不可能完成的要求，无论现场的气氛被炒得多热烈，只要他一出场，变立刻如同坠入冰窟之中。和小多不同，他的妹妹则有着超强的喜剧基因，随着时间的推移，父亲将寄于在小多身上的期望，渐渐转移到了女儿身上，使得小多深深觉得受到了冷落。之后，小多遇见了美丽善良的医生冰冰（宝拉·泰勒 Paula Taylor 饰），他那些使观众陷入冷场的笑话，却总能逗得冰冰哈哈大笑。在冰冰的身上，小多找回了久违的温暖。©豆瓣', '查温·利基恰容旁', '维塔亚·东俞扬', 7.7, 7318, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p603466774.jpg', 0.6, 3.3, 27.7, 45.9, 22.5, '0.309274,0.139647,-0.817552,0.533764,-0.167559,-0.324887,1.138537,0.147187,-0.482293,0.128740,0.138019,0.866597,-0.413591,0.337806,0.074038,0.005601,-0.291766,-0.643412,-0.365105,-0.247948,-0.214965,-0.332708,-0.191992,0.217688,-0.152979,-0.426371,0.496338,-0.003404,-0.262956,0.505199,0.330150,0.130741,0.277268,0.584937,-0.126782,0.269135,-0.201054,0.063546,-0.139505,0.087633,0.344809,0.093353,-0.062992,0.285921,0.045365,0.098453,0.703886,-0.381827,-0.457540,-0.042376,0.459864,-0.156513,0.060086,0.054200,-0.048861,0.244354,0.516757,-0.067263,-0.243406,0.125728,0.023700,-0.002602,-0.886570,0.355016,0.324945,0.122631,-0.499448,0.392035,0.193348,-0.295268,0.218898,-0.416961,0.315752,0.138809,0.026620,0.701075,-0.506038,0.188278,-0.392705,0.009212,0.822182,0.039458,-0.398506,0.502888,-0.347841,-0.277246,0.004524,-0.453541,-0.232045,0.126368,0.289230,0.231094,-0.087874,0.486593,-0.412837,0.263061,0.002813,-0.360289,-0.051158,-0.668932,-0.215008,-0.165333,-0.331699,-0.575122,-0.268247,0.087141,0.178876,-0.434246,1.257790,-0.920381,0.239727,0.294522,0.499633,-0.134908,0.352723,0.115902,0.108252,0.091737,-0.113424,0.020506,-0.067484,0.381555,0.307811,0.422617,-0.306726,-0.243579,-0.592741,0.549730', '24284209', '26283288', '3005387', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4724739', '单身男女', '喜剧', '为追寻爱情，苏州女孩程子欣（高圆圆 饰）随男友来至香港，在一家金融公司供职。谁知男友移情别恋，令子欣备受打击。偶然机缘，她结识了正处于瓶颈期的建筑师方启宏（吴彦祖 饰），二人互相勉励，子欣丢掉了关于前男友的一切，启宏也决定重新出发，并相约一周后给子欣看最新的设计图。谁知约会当晚，子欣却失约了。原来在子欣的办公室对面，另一家公司的老板张申然（古天乐 饰）长久以来一直注视着她。在她失落期间，两人通过彩色贴纸交流，子欣也渐渐喜欢上了这个大男孩。子欣忘记了和启宏的约定，与申然约在某咖啡厅见面，而申然却睡在了另一个女人的床上。阴差阳错，让三个人的缘分暂时中断。直到三年后的一天，未了的情缘继续上演……©豆瓣', '古天乐', '杜琪峰', 6.8, 281094, 'tt1776143', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p918517782.jpg', 2, 9.3, 46.4, 33, 9.2, '0.304452,0.204874,-0.674080,0.329844,0.140475,-0.570526,0.544519,0.363587,-0.486393,-0.260631,0.096419,0.673501,-0.369842,0.547278,0.361244,-0.143496,-0.310897,-0.708923,0.022728,-0.193606,-0.356530,-0.348020,-0.011456,0.100289,-0.031666,-0.050415,0.487411,-0.077338,0.093874,0.474191,0.344642,-0.124062,-0.379684,0.629346,-0.166307,0.005800,0.166236,0.295037,-0.386393,0.303018,0.088684,-0.325434,-0.003496,-0.018463,0.014438,0.259072,0.740811,0.032700,-0.285552,-0.009788,0.248874,0.029289,-0.061555,-0.024019,0.332967,0.001723,0.359160,0.200314,-0.430216,-0.162486,0.012034,0.025398,-0.358279,0.193410,-0.089957,0.048638,-0.451338,0.822767,0.034169,-0.065712,0.130039,-0.394166,0.099853,0.656643,0.134443,0.190078,-0.198864,-0.020272,-0.274891,0.291078,0.455599,0.135391,0.171196,0.652635,0.169105,-0.214957,-0.016442,0.161388,-0.382837,-0.099172,0.275498,0.128434,-0.282233,-0.161282,-0.686006,0.059279,-0.167676,0.056238,0.165707,-0.543896,-0.009954,-0.666538,0.001792,-0.191172,-0.252408,0.200390,0.067951,-0.252783,0.441584,-0.794764,0.209677,0.545691,0.309958,-0.415357,0.781178,0.168348,0.103112,-0.260490,0.095249,0.142194,-0.209044,0.304198,0.169962,0.321015,-0.063564,0.207038,-0.561515,0.362938', '5327188', '26687241', '1915403', '34973399');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4727460', '好想告诉你', '剧情', '高中女孩黑泽爽子（多部未华子 饰）纯真善良，乐于助人，她就像神话中的座敷童子一般坚持日行一善。可是童年时代流行的《午夜凶铃》却成为爽子多年的梦魇，由于留着一头乌黑靓丽的头发，以及不善与人交往的性格，爽子被人误解为有着阴森气质的贞子。所有人都躲着她走，只有一个人是例外，那就是爽朗帅气的同班同学风早翔太（三浦春马 饰）。在风早的感召下，同班同学渐渐接受了内向的爽子，她也结交到绫音、千鹤两名好朋友。青春的男女，彼此间充满了暧昧和别扭，何况爽子这样一个不谙世事的女孩子。虽然和翔太互有好感，可是她始终不知该如何回应对方的热情。复杂的情感在心中如杂草般蔓延……本片根据椎名轻穗的原著漫画改编。©豆瓣', '多部未华子', '熊泽尚人', 7.1, 46342, 'tt1632544', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p666945712.jpg', 1.1, 7.2, 43.8, 33.7, 14.2, '0.445237,-0.005627,-0.444220,0.636218,-0.314975,-0.001170,0.821302,0.145575,-0.287798,-0.150705,0.243174,0.639339,-0.241116,0.379155,0.052585,0.031845,-0.071114,-0.438449,-0.208781,-0.092273,0.065450,-0.233790,-0.365986,0.190906,-0.091679,-0.322290,0.750633,0.085380,-0.230945,0.478822,0.445612,0.285120,-0.145477,0.347649,-0.181452,-0.088704,-0.280365,0.211687,0.228535,-0.080867,-0.053982,-0.042788,-0.068208,0.026421,-0.297729,0.452805,0.493957,-0.195239,-0.339430,0.133425,0.443954,-0.111857,-0.182597,0.231707,0.251180,-0.073320,0.173965,-0.066070,0.061942,0.163246,-0.011947,-0.054461,-0.496044,0.092714,0.285066,0.457514,-0.613189,0.611614,0.107215,-0.388247,0.179769,-0.150549,-0.170405,-0.247863,0.185831,0.489851,-0.196617,0.294414,-0.276104,0.321013,0.620032,0.409822,-0.632462,0.500633,-0.606731,-0.342332,-0.081515,-0.263633,-0.629721,0.023507,-0.072026,-0.095213,-0.198030,0.160941,-0.470715,0.063488,0.062989,0.160789,-0.113655,-0.627235,-0.127508,-0.319837,-0.283653,-0.774191,-0.416480,0.020136,0.064187,-0.238418,1.062414,-0.874158,0.087616,0.362869,0.038681,-0.246978,0.574942,0.172630,-0.313132,-0.142727,-0.258538,0.470762,-0.065784,-0.079814,0.136804,0.610555,-0.299457,-0.042678,-0.359797,0.295817', '26348103', '6963575', '26283288', '1390020');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4727962', '拉瑞·克劳', '剧情', '《拉瑞·克劳》由汤姆·汉克斯自导自演。海军退伍之后，拉瑞（汤姆·汉克斯 Tom Hanks 饰）勤勤恳恳在卖场工作了20几年。他为人和善，几乎从不发脾气，是明星工作人员，顾客喜欢他，老板也对他颇为赏识。可是裁员风暴还是让他失去了工作。空闲的他向当地社区里的大学报了名，并很快就和各色人等结成了好朋友。有流浪汉、有贫民窟的孩子，大家都希望到这里改善自己的生活。在公共演讲的课堂上，拉瑞出乎意料地爱上了自己的老师梅赛德斯（朱莉娅·罗伯茨 Julia Roberts 饰）。但她是一个已婚女子，并且她把自己的精力都放在了教学上，无暇顾及学生的爱慕。现在，一切难题似乎都到了拉瑞的身上......©豆瓣', '汤姆·汉克斯', '汤姆·汉克斯', 6.6, 7148, 'tt1583420', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1234429680.jpg', 1.3, 10.4, 53, 27.9, 7.5, '0.312703,-0.212032,-0.657357,0.392431,-0.560507,-0.359775,0.759285,0.155721,-0.602515,0.116383,0.141356,0.815340,-0.100964,0.465947,0.249475,0.226893,-0.545809,-0.963160,0.001800,-0.087642,-0.210967,-0.569816,-0.257282,-0.506007,-0.374918,-0.398046,0.328764,0.038594,0.082171,0.105803,0.264848,-0.106745,0.348125,0.893117,-0.171879,0.174159,0.117456,-0.078570,0.093293,0.095551,0.154678,-0.263443,-0.342827,0.359545,0.436380,0.597876,0.532365,0.032005,-0.103339,0.227550,0.223045,-0.363161,0.231585,0.114682,0.399552,-0.028025,0.278432,0.159423,-0.177159,0.014759,-0.089660,0.018922,-0.470519,-0.081391,0.016463,0.107592,-0.845020,0.755415,-0.089197,-0.121981,-0.130771,-0.437707,0.059428,-0.005538,-0.005955,0.231352,-0.123316,0.054379,-0.377934,0.578445,0.489613,0.210626,-0.236115,0.361640,-0.482987,-0.543672,-0.204148,-0.105324,-0.548148,-0.189236,0.231684,-0.047274,-0.001963,0.145927,-0.589516,0.056070,-0.024650,-0.383751,-0.193930,-0.620407,-0.072302,-0.576455,0.047436,-0.411525,-0.450335,-0.152224,0.215076,-0.167530,0.917850,-0.993368,-0.005207,0.706776,0.237379,-0.459509,0.833621,-0.095065,0.231548,-0.208575,-0.251801,0.014604,-0.114812,0.479780,0.312496,0.557956,0.135554,-0.205901,-0.291468,0.799184', '1308609', '3230462', '1298880', '5262027');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4728076', '幻想之爱', '剧情', '本片曾参加了2010年戛纳电影节的“国际影评人周”单元，并获得不“青年致敬奖”。Francis（泽维尔·多兰 Xavier Dolan 饰）和Marie（莫妮亚·乔柯里 Monia Chokri 饰）是一对默契十足的异性好朋友。在一次晚宴上，他们碰到了刚来到这座城市的乡村男孩 Nicolas（尼尔斯·施内德 Niels Schneider 饰）。随着和这个漂亮的男孩的进一步交往，这两个平日亲密无间的好朋友却发现周遭的种种莫名发生了改变，似乎有一种新的情绪影响着彼此。不久，Francis和Marie发现自己都不知不觉地爱上了这个不可捉摸的少年Nicolas，而两个人昔日坚不可摧的友情也第一次面临着挑战。爱情和友情，到底哪一个才是他们真正的归宿呢？©豆瓣', '泽维尔·多兰', '泽维尔·多兰', 7.6, 16723, 'tt1600524', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p699224369.jpg', 0.5, 3.7, 30.9, 45.5, 19.3, '0.408997,-0.144554,-0.719115,0.797881,-0.098823,-0.277328,0.922077,0.019315,-0.528242,-0.276252,0.088451,0.900945,-0.624319,0.358971,0.347916,-0.112361,-0.118076,-0.799212,-0.124284,-0.148160,-0.350767,-0.387608,-0.602144,0.047763,-0.026420,-0.158671,0.619698,0.093049,-0.089594,0.652725,0.462926,-0.000267,0.028202,0.587315,-0.301782,0.046686,0.287013,0.438839,-0.289178,0.017864,0.008701,-0.241633,-0.296193,0.148484,-0.221324,0.499423,0.550598,-0.279913,-0.444623,0.093030,0.531086,-0.111325,-0.045860,0.021808,0.238003,-0.150124,0.174682,0.175801,0.024309,-0.068729,0.006381,-0.158782,-0.479772,0.127884,0.174550,0.066171,-0.553768,0.721099,0.301405,-0.179295,-0.028612,-0.251975,0.235482,0.505931,0.301316,0.261448,-0.277534,-0.096164,-0.653734,0.170996,0.959156,0.158241,-0.430825,0.492182,-0.309320,-0.768638,-0.285767,-0.067362,-0.584712,0.153833,0.296195,0.108940,-0.112798,0.030189,-0.823807,0.116614,0.096225,-0.061560,0.158417,-0.647115,0.231200,-0.748949,-0.348277,-0.768854,-0.497288,0.206611,-0.105980,-0.267924,0.881067,-1.033976,0.244222,0.497956,0.249720,-0.533922,0.846582,0.150402,-0.069414,-0.310979,-0.272652,0.141093,-0.087213,0.010201,0.002491,0.571225,-0.058731,0.138027,-0.305289,0.574233', '30162520', '1292219', '25721544', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4728342', '为你钟情', '爱情', '阿颖（卫兰 饰）父亲意外去世，遗言中嘱咐她打开实验室的冷冻装置，里面竟然是她被冰冻二十年的亲生母亲方颖芝（文咏珊 饰），虽然身为两代人，但外表年龄相仿，于是阿颖开始带着阿芝适应现代生活。醒来的阿芝时时沉浸在回忆中，和她年轻时代恋人——阿颖的生父张伟杰（李治廷 饰）度过的甜蜜时光历历在目，二个年轻人共同喜欢哥哥张国荣，阿芝经常听阿伟弹吉他唱《为你钟情》，二人一起去看哥哥89告别演唱会，却在路上遭遇车祸……往事如烟，如今醒来的阿芝一心想找到阿杰，从美国留学回来、现代感十足的阿颖也被母亲的回忆带到充满怀旧感的八十年代，深受感动，开始帮助母亲寻找生父如今的踪迹……©豆瓣', '卫兰', '郭子健', 6, 5037, 'tt1611845', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p754904665.jpg', 5.3, 21.4, 49, 17.7, 6.6, '0.057796,0.010195,-0.649224,0.315403,-0.225707,-0.397627,0.875921,-0.116589,-0.719270,-0.575930,-0.091313,0.697038,-0.172532,0.600336,0.100888,0.033425,-0.356696,-0.504327,0.026993,0.114579,-0.149196,-0.330553,0.008005,0.160844,-0.074511,-0.430814,0.350619,-0.039571,-0.018027,0.755862,0.098695,0.137500,-0.437644,0.419345,-0.312728,0.093554,-0.058335,0.389841,-0.440016,0.143789,0.138161,-0.063036,0.051861,-0.022650,-0.083331,0.122853,0.559314,0.121827,0.063054,-0.039197,0.358391,0.058893,-0.228285,0.095915,0.193585,0.310394,0.296384,0.179865,-0.267289,-0.147204,-0.339738,-0.141009,-0.130737,0.123599,0.293675,-0.102991,-0.623689,0.229529,-0.028331,0.067934,0.323590,-0.304378,0.387749,0.116548,0.214786,0.783325,-0.100912,0.241406,-0.374791,0.116021,0.616388,-0.422907,0.115587,0.442885,-0.014577,-0.186681,0.094101,-0.033736,-0.508168,0.349186,-0.123324,-0.026453,-0.330562,0.106585,-0.269074,0.020237,-0.047709,-0.046989,0.167256,-0.400307,-0.222790,-0.384127,-0.138871,-0.502759,-0.304119,0.074998,0.058319,-0.477459,0.590802,-0.643691,0.381427,0.154647,0.232855,-0.434090,0.664512,0.244081,0.015123,-0.455920,0.099945,0.652720,-0.166878,-0.259956,-0.080870,0.055955,-0.178982,0.126662,-0.760190,0.318452', '35225859', '1296534', '2365260', '2122766');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4728471', '神奇侠侣', '喜剧', '在一个远离京城的幽静田野，胡子拉碴的保长欢哥（古天乐 饰）慵懒倦怠，过着百无聊赖的生活。他的老婆红姐（吴君如 饰）经营一家包子铺，厨艺上佳，持家有道。夫妻俩看似讷言平庸，胸无大志，却很少有人知道他们曾经有着怎样的传奇经历。遥想当年，京城出了两个名震江湖的侠客——炯炯侠和香香侠，他们济弱扶贫，惩恶扬善。两个大侠互相较劲，狭路相逢，却由此一见钟情，携手归隐江湖。他们隐藏着自己的一身武功和令人惊叹的超能力，决心安顿下来买间房子再生个孩子。谁曾想事与愿违，夫妇俩始终没有孩子令他们颇为烦恼，而就在此时一场武林大会突然在小山村召开，他们沉静的生活被彻底打破……', '古天乐', '谷德昭', 5, 50900, 'tt1623759', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p797829016.jpg', 13.5, 35, 40.8, 8.2, 2.5, '0.180970,-0.076172,-0.602563,0.513899,-0.238478,-0.280986,0.700277,0.189708,-0.696927,-0.442643,0.292733,0.774424,-0.097925,0.434453,-0.111528,-0.203082,0.065655,-0.484659,0.020459,0.048719,0.177027,-0.236266,-0.280613,0.144287,-0.162121,-0.027467,0.480494,0.148854,-0.018796,0.536267,0.215190,0.035901,-0.328568,0.330278,-0.631094,-0.117188,-0.047386,0.266074,-0.369031,-0.112296,-0.088576,-0.178487,-0.405402,-0.084943,-0.109030,0.080539,0.581184,-0.024005,-0.373470,0.168572,0.207304,-0.086538,-0.228776,0.099147,0.356781,-0.303230,0.226286,0.224432,-0.016937,-0.210938,-0.113034,0.025623,-0.539996,0.111201,0.279454,0.130693,-0.627416,0.638945,0.098788,-0.320921,-0.244871,-0.294248,0.217139,0.396263,0.291114,0.287923,-0.093000,0.109277,-0.749671,0.311925,0.770206,0.199512,0.004751,0.306782,-0.186011,-0.277590,0.114652,-0.360749,-0.711695,-0.082946,0.232296,-0.388498,-0.390396,0.144448,-0.445006,0.367926,-0.067934,0.141670,0.075202,-0.386873,-0.062262,-0.464233,-0.233928,-0.488018,-0.384689,0.114189,-0.002502,-0.168420,0.691330,-1.049622,0.014200,0.277540,0.031479,-0.461597,0.706677,0.035051,0.157617,-0.207816,-0.178798,0.203348,0.074349,0.148182,0.100362,0.572221,-0.050669,0.082970,-0.320751,0.414081', '35030151', '1292219', '1302384', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4728507', '庐山恋2010', '剧情', '上世纪80年代，美丽时尚的女孩周筠（张瑜 饰）与耿桦（郭凯敏 饰）在风景秀丽的庐山谱写出一段感人至深的恋情，至今周筠的美好影响仍久久驻留人们的心田，令人无法忘怀。时间进入21世纪，当年那清秀可人的女孩已经成为叱咤商界的女强人，她的女儿耿菲儿（秦岚 饰）更出落成一位不输母亲当年风采的可人。自海外学成归国之后，菲儿决心闯出一番事业，最终却与同样混迹商界的韦宁（方中信 饰）谱写了一段没有结局的恋情。分手之后，菲儿在旅途中结识了摄影师马缰（李晨 饰），时尚的女孩与不相信爱情的摄影师，新的故事正在发生，老的故事却还在继续，三角恋情难取难舍……©豆瓣', '秦岚', '张瑜', 4.8, 8855, 'tt6141382', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p651758381.jpg', 17.3, 36.6, 37.5, 7, 1.7, '0.024299,0.249425,-0.625501,0.567635,0.020003,-0.279962,0.782280,-0.095011,-0.667996,-0.125470,0.233938,0.558633,-0.266223,0.396935,0.470196,-0.090399,-0.444776,-0.810930,0.196145,-0.195796,0.079102,-0.126593,-0.357922,0.299698,-0.132444,-0.171919,0.849210,0.249915,-0.105117,0.482504,0.252866,-0.000287,-0.300482,0.232942,-0.362637,0.078046,-0.006817,0.455573,-0.409975,-0.125243,0.022246,-0.364233,-0.263429,-0.050765,-0.295563,0.055446,0.566141,-0.391511,-0.042903,0.168094,0.621183,0.128701,-0.132134,-0.040056,0.084290,0.018154,0.354298,0.274869,-0.220987,-0.062813,0.027002,-0.144802,-0.397585,0.131859,0.321771,0.355245,-0.413187,0.572600,-0.106263,-0.156320,0.029812,-0.324196,0.018137,0.213019,0.632658,0.353685,-0.151001,0.406744,-0.291125,0.638496,0.762082,0.398485,-0.351358,0.389400,-0.286406,-0.553348,-0.400287,-0.250685,-0.596236,0.093565,0.121012,0.042346,-0.111775,0.336398,-0.582837,0.051222,-0.226511,0.145045,0.152509,-0.175034,-0.285723,-0.635493,-0.309344,-0.644468,-0.118638,0.108119,0.047768,-0.247615,0.827023,-0.678126,0.063336,0.096720,-0.015847,-0.296258,0.882582,0.210485,0.135184,-0.229156,-0.099872,0.797739,-0.423084,0.080590,-0.217124,0.418560,-0.256106,-0.149600,-0.389541,0.439200', '1302050', '26354526', '26647163', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4728584', '不再让你孤单', '剧情', '找到相爱的人，便可以不再孤单。来北京掘金的港女李佩如（舒淇 饰）在光棍节的晚上，邂逅身为警察的方镇东（刘烨 饰）。李佩如顶着巨大的生活压力，希望用青春为家人换来衣食无忧的生活，被妻子抛弃的方镇东带着有人际交往障碍的弟弟方镇聪（田亮 饰）一起生活。也许是寂寞气质的吸引，抑或是命中注定，两人彼此吸引，日渐亲近。佩如生意起步需要投资，加之镇聪要结婚，方镇东毫不犹豫的卖掉自己的祖屋，可是佩如却由于生意不顺忽然失踪。此时镇东查出患有脑血管性失忆症，而且很快丢掉了工作，镇东一家的生活霎时陷入了窘境。回到香港的佩如发现自己始终不能忘记镇东，于是返回北京，在几经波折后找到镇东，却发现镇东此时身患重症。这一次，佩如没有退缩，她选择与自己的爱人相互陪伴……©豆瓣', '刘烨', '刘伟强', 7, 104885, 'tt1934335', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1036746606.jpg', 1.6, 8.3, 41.8, 36, 12.3, '0.057391,-0.007691,-0.620696,0.330728,-0.014390,-0.367583,0.700930,0.266344,-0.483322,-0.346848,0.161481,0.690663,0.154297,0.394018,0.175615,-0.095117,-0.080814,-0.577376,0.214963,-0.090964,-0.167557,-0.328748,-0.068417,-0.138321,-0.122804,-0.350340,0.725009,0.302171,-0.094174,0.574797,0.095398,0.238414,-0.107012,0.622422,-0.261745,0.041471,-0.146671,0.189617,-0.564850,0.274189,0.094840,-0.067446,-0.099486,0.052386,0.143211,0.334256,0.683819,-0.014467,-0.379948,0.014710,0.409573,-0.046377,-0.150717,-0.085520,0.183195,0.035338,0.135457,0.119387,-0.531889,-0.055794,0.191572,0.040047,-0.491482,0.034752,0.250279,0.269281,-0.603206,0.392653,0.056589,-0.233568,-0.069833,-0.319460,0.267834,0.584797,0.253591,0.357321,-0.179326,0.362301,-0.420659,0.184530,1.143576,-0.130247,-0.223487,0.501848,-0.289469,-0.147088,0.245808,-0.358738,-0.435761,-0.031743,0.075532,0.251239,-0.245534,0.149274,-0.410789,0.037700,-0.011551,-0.111069,0.340956,-0.359652,0.024683,-0.472840,-0.132303,-0.383486,-0.308866,0.234611,-0.043055,-0.342760,0.472224,-0.868747,0.240186,0.478125,0.496968,-0.671018,0.750243,0.108883,0.119554,-0.202828,-0.001896,0.414919,-0.089273,0.287718,0.162708,-0.097383,-0.286766,0.063983,-0.408894,0.391124', '25721544', '1308035', '4145476', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4728881', '青少年', '剧情', '尽管自己并不承认，但麦维斯（查理兹·塞隆 Charlize Theron 饰）就是一个标标准准的大龄剩女。她独居，没有朋友，吃垃圾食品，写垃圾小说，更可悲的是，她的小说卖的并不好。某一天，她收到了喜当爹的前男友巴迪（帕特里克·威尔森 Patrick Wilson 饰）的邮件，却错误的认为这是巴迪发给她的求偶信号。麦维斯振奋不已，决定改头换面，重返学生时代住过的水星镇，拯救她深陷婚姻漩涡的前男友。在水星镇，她遇见了曾经嘲笑过的胖子马特（帕顿·奥斯瓦尔特 Patton Oswalt 饰），马特让她赶紧打消挖墙脚的念头，因为巴迪的生活其实非常幸福美满，他的妻子也是一个非常有魅力的家庭主妇。麦维斯当然不相信，无奈现实狠狠的甩了她一个耳光，在旧日同学面前出尽了洋相的麦维斯猛然醒悟，巴迪快乐的生活让她充满嫉妒，但自己的生活又何尝不是他人眼中“最好的生活”。一夜之间，麦维斯终于从一个“青少年”变成了一个真正的“成年人”。', '查理兹·塞隆', '贾森·雷特曼', 6.8, 13324, 'tt1625346', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1307803757.jpg', 1.1, 8, 47.6, 34.2, 9.2, '0.442960,-0.097078,-0.268519,0.730020,-0.214337,-0.373942,0.731781,0.139170,-0.315803,-0.347935,-0.029382,0.735248,-0.081498,0.260508,0.084879,0.172593,-0.212393,-0.352055,0.249774,-0.140540,-0.103784,-0.421520,-0.158857,-0.177008,-0.149400,-0.172635,0.552834,-0.224545,-0.203319,0.192357,0.352210,0.436390,0.495431,0.532448,-0.271120,0.175592,0.190395,-0.156780,-0.075678,0.007175,0.064261,-0.005229,0.064207,0.436747,0.058994,0.247165,0.455140,-0.159335,-0.289096,0.039552,0.355478,-0.241490,-0.217331,-0.035903,-0.067220,-0.364861,-0.035888,-0.126602,-0.085201,-0.064369,0.193366,0.048131,-0.701639,-0.051249,0.038093,0.093294,-0.491431,0.519841,-0.245844,0.024116,0.035520,-0.074797,0.034355,0.066218,0.169847,0.286826,-0.149795,0.001362,-0.558676,0.323264,0.556997,0.113498,-0.389423,0.409510,-0.593251,-0.389385,0.135998,0.057164,-0.666111,-0.028529,0.258773,-0.111710,-0.283145,0.450989,-0.495939,-0.046720,-0.450475,-0.222947,0.151829,-0.685355,-0.229269,-0.132034,-0.269567,-0.201363,-0.487630,-0.224659,-0.059614,-0.313607,0.615415,-0.926976,0.287868,0.492571,0.113463,-0.272698,0.644127,0.338222,-0.061618,-0.413256,-0.056850,0.369862,0.060873,0.197030,0.065140,0.206652,0.188454,-0.329571,-0.245103,0.851377', '1292062', '35158375', '24756472', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4735944', '龙凤店', '喜剧', '正德皇帝朱厚照（任贤齐 饰）自小长于深宫，虽有太监宫女们扮演各色人物的“百姓街”供他进行“假装微服私访”的游戏，但正德对假模假式的表演早已厌倦，遂借皇太后为他操办婚事的机会，随史官司马西（罗家英 饰）、指挥使陈珍珍（梁小龙 饰）以及太医一同微服出宫。正德一行体察民情游历到江南小镇，误入江南四大才子的赌局，将玉玺和银两统统遗落，只得加入丐帮盛会抢食，岂料混乱中正德与司马西等人失散又失去了记忆，落魄的正德因一碗善面结识龙凤店老板娘凤姐（徐熙媛 饰），并进入龙凤店担任小二。另一方面，宫中图谋篡位的宁王获悉正德失忆，派出手下欲将正德的人生限制在龙凤店中……©豆瓣', '徐熙媛', '钟澍佳', 5.1, 47591, 'tt1907717', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p598445761.jpg', 12.8, 34.9, 41.7, 7.8, 2.8, '0.149653,0.154570,-0.217496,0.435955,0.149871,-0.111651,0.398134,0.415664,-0.816355,-0.151772,0.485633,0.505667,-0.276691,-0.029996,0.342710,-0.174402,-0.251547,-0.415392,0.039471,-0.019358,0.189447,-0.209622,0.026053,-0.290274,-0.358859,-0.076137,0.380108,-0.114779,0.158856,0.698321,0.208636,-0.041511,-0.416888,0.346262,-0.098673,0.223246,0.020890,-0.119079,-0.287262,0.004472,-0.339542,-0.515726,-0.557205,-0.077279,0.271169,0.139886,0.405461,-0.544215,0.258927,-0.434124,0.355698,0.137396,-0.052094,0.096391,0.114298,0.455994,0.114697,0.437273,-0.211778,0.161239,-0.160600,-0.071533,-0.239630,0.166893,0.390137,-0.029381,-0.370605,0.359466,0.038478,-0.281953,-0.134401,-0.263160,0.337412,0.258539,0.075899,-0.069901,0.075130,-0.019150,-0.592111,0.496262,0.287018,-0.185693,0.192489,-0.067131,0.225023,-0.273350,0.234442,-0.317358,-0.029172,-0.017893,0.164022,-0.154780,0.198506,0.209958,-0.264948,-0.066074,-0.259662,-0.077628,0.296234,0.176099,-0.000485,-0.582310,-0.041467,-0.130653,-0.186604,-0.310336,0.445687,0.065901,0.399431,-0.469775,0.156261,0.267847,0.095617,-0.921320,0.433922,0.078186,0.381285,-0.103687,-0.374978,-0.059803,0.067057,0.220780,-0.058770,0.117297,-0.353686,-0.398092,-0.290755,0.051336', '3606975', '1300060', '24745500', '1305060');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4739952', '初恋这件小事', '剧情', '初中生小水相貌平平，家境一般，所以在学校里并不受重视。但是她心地善良，又有一群死党，日子过得倒也开心。某天，她遇见了帅气的学长阿亮（马里奥·毛瑞尔 Mario Maurer 饰），春心萌动，无 法遏制。她喜欢看他踢足球，看他拍照，如痴如狂。上英语课时，她不停地给死党传纸条 表达对阿亮的爱慕。然而，英语老师则指出她除了英语一无是处。回到家，叔叔从美国捎来了父亲的消息，说如果她能考全校第一，就可以去美国。于是，她按下决心要努力加油。某天，小水等人在买饮料时，碰到篮球队员蛮横插队。阿亮挺身而出，为她们教训了对方，并挨了校长的责骂。小水也第一次听说，阿亮的父亲因为射失点球而退役的事情，理解了他心中的隐痛。由于舞蹈队是给美女准备的，所以小水等一干姐妹准备在话剧社大展身手，没想到学长也来到这个社团。两人还扮演王子公主，他们的恋情会由此展开么？……©豆瓣', '平采娜·乐维瑟派布恩', '普特鹏·普罗萨卡·那·萨克那卡林', 8.5, 934557, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1505312273.jpg', 0.3, 1.3, 14.8, 41.9, 41.6, '0.178957,-0.123629,-0.438822,0.408139,-0.262673,-0.366254,0.391959,0.066121,-0.340336,-0.084308,-0.045010,0.511976,-0.159962,0.333243,0.224987,-0.008147,-0.258626,-0.639258,0.222998,-0.141397,-0.187444,-0.266457,0.124102,-0.247366,0.028309,-0.189483,0.165151,-0.369899,-0.176508,0.457723,0.126857,-0.196800,0.291852,0.394639,-0.253489,0.075270,-0.150669,0.256751,-0.061947,0.238774,0.240504,-0.131728,-0.234633,0.048536,0.331662,0.321657,0.442921,-0.010418,-0.136663,0.109326,0.267637,-0.402281,0.035438,0.222232,0.258197,-0.003233,0.300510,-0.145628,0.061032,0.047565,-0.038407,-0.137676,-0.364954,0.161218,-0.220962,-0.023535,-0.476608,0.666132,-0.101758,0.039081,0.137991,-0.311330,0.100852,0.141225,0.041676,0.296929,-0.247110,-0.002060,-0.222626,0.174712,0.545586,-0.044180,0.089352,0.272352,-0.010291,-0.309097,0.270465,0.012922,-0.435574,0.143101,0.150085,0.004086,-0.172352,-0.062123,-0.204960,-0.070495,-0.129424,-0.106845,0.006174,-0.565110,-0.164858,-0.295802,-0.012685,-0.193368,-0.347598,0.043357,0.259074,-0.141004,0.849215,-0.994019,0.066737,0.527539,0.356782,-0.602724,0.619914,0.280052,-0.246778,-0.124204,-0.243570,-0.045479,-0.029470,0.265400,0.171109,0.550186,-0.029746,-0.393688,-0.233779,0.193358', '1292219', '3445516', '25922902', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4739986', '东风破', '剧情', '女主角官恩娜曾因此片获得2012 澳大利亚悉尼金考拉国际华语电影节最佳女主角奖。一个因此长期滥用药物而频临死亡的的华裔女孩(官恩娜 饰)，离开熟悉的旧金山就为去香港见一个只在网上聊天的网友三藩市。途中遇到一个终日待在棺材铺，不与外界节流的坏脾气老伯(泰迪·罗宾 Te ddy Robin 饰)。而旧金山另外一个几十年没有怎么出远门的女中医(苗可秀 饰)，不得不为了一份速递屋契回去久别的香港。南北行药材铺少东家(周俊伟 饰)，却从来不喜欢自己的家族生意。这些人的相遇到底是巧合还是命运的安排，看似陌生人似乎能给对方带去不同凡响的影响......©豆瓣', '官恩娜', '麦婉欣', 7.6, 6818, 'tt1756487', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1825601947.jpg', 0.6, 4.1, 28.9, 46.9, 19.4, '0.181076,-0.026396,-0.459001,0.517083,-0.134673,-0.149922,0.478331,0.126809,-0.524691,-0.431841,0.266297,0.918400,0.116453,0.024041,-0.090466,0.223936,-0.239112,-0.345178,-0.066947,-0.255953,-0.357293,-0.286825,-0.311598,-0.031602,-0.168771,0.012739,0.413745,0.149645,-0.193705,0.320912,0.401663,0.188776,-0.208882,0.340380,-0.300903,-0.069068,0.047188,0.098268,-0.363183,0.280489,0.149308,-0.215641,-0.245553,-0.049045,0.216034,0.282365,0.573698,0.019579,-0.169735,-0.125971,0.556396,-0.156965,-0.010755,-0.134078,0.330789,-0.175667,0.492411,-0.045316,-0.258163,0.067443,0.145223,0.013830,-0.550755,0.139003,0.181321,0.276032,-0.480678,0.408150,-0.104221,-0.083335,-0.205124,-0.397950,0.167472,0.350650,0.315107,0.119084,0.114545,0.249570,-0.470597,0.327280,0.818649,0.220419,-0.103199,0.337518,-0.116686,-0.558836,-0.025431,-0.228376,-0.451830,0.101335,0.247220,-0.003018,-0.099802,-0.177069,-0.605353,-0.001458,-0.183829,-0.109885,0.278778,-0.190781,-0.073277,-0.677111,0.136687,-0.390734,-0.143083,0.070434,0.392567,-0.058976,0.588591,-0.648008,0.309689,0.574462,0.257913,-0.583695,0.815502,0.068329,-0.009712,-0.199606,-0.218933,-0.015885,0.060608,0.197489,0.009693,0.206528,0.222630,-0.197729,-0.235502,0.236964', '30162520', '1829654', '4301278', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4745364', '惊魂半小时', '喜剧', 'Nick（杰西·艾森伯格 Jesse Eisenberg 饰）是小镇上的一个普通披萨送餐员，他一直都过着平凡的生活。一天，他的平凡生活和两个有计划犯罪的罪犯——Dwayne（丹尼·麦克布耐德 Danny McBride 饰）和Travis（尼克·斯旺森 Nick Swardson 饰）碰撞到一起。疯狂的两个罪犯绑架Nick去抢劫银行。就在这短短的半个小时里，Nick在他的朋友Chet（阿兹·安萨里 Aziz Ansari 饰）的帮助下，完成了不可能完成的任务。时间滴答滴答的在流走，这两个罪犯必须同警察、雇佣的刺客还有别人手中拿着的喷火器，甚至是他们两人自己出现的分歧做斗争......©豆瓣', '杰西·艾森伯格', '鲁本·弗雷斯彻', 6.3, 9523, 'tt1622547', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1294523060.jpg', 2, 13.7, 56.8, 22.4, 5.1, '0.471081,-0.118679,-0.642031,0.493933,-0.236511,-0.270669,0.979474,0.079720,-0.011117,-0.243202,0.331709,0.616299,-0.037575,0.194800,0.174476,-0.030633,-0.535648,-0.867683,-0.064449,-0.297946,-0.569159,-0.519174,-0.360623,-0.451350,-0.027500,-0.165124,0.323170,-0.075169,0.181165,0.455954,0.469672,0.078994,-0.220849,0.372425,-0.489938,0.036450,0.367923,-0.055050,-0.222379,0.246481,0.093119,-0.100609,0.066188,-0.047672,0.194530,0.520131,0.513894,-0.139198,-0.042900,0.045715,0.141804,-0.338157,-0.216673,0.013322,0.321590,-0.048668,0.155294,0.373923,-0.294014,0.089076,0.203105,-0.001253,-0.880317,-0.064891,-0.095936,0.404415,-0.787288,0.647010,-0.137227,-0.138453,-0.105148,-0.305298,0.149131,0.428145,0.088350,0.290506,-0.129582,-0.229143,-0.851861,0.271000,0.669491,-0.129523,-0.220975,0.189706,-0.169131,-0.449240,-0.189647,-0.173187,-0.350145,-0.300749,0.328108,-0.287339,-0.174687,-0.030838,-0.832611,0.252960,-0.169674,-0.238747,0.050956,-0.326905,-0.129174,-0.684823,0.119258,-0.661379,-0.846869,0.276352,0.042548,-0.212922,0.608056,-0.608519,0.227570,0.809699,0.373425,-0.180020,0.649992,0.276515,0.243315,-0.172665,-0.052300,-0.142368,0.273368,0.470854,0.391759,0.603044,0.170285,0.191755,-0.444873,0.597327', '1947080', '1299932', '4944008', '10774184');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4746257', '明日边缘', '动作', '未来世界陷入外星人入侵的恐慌中，军事演说家凯奇少校（汤姆·克鲁斯 Tom Cruise 饰）畏惧上战场，他从没想过将军（布莱丹·格里森 Brendan Gleeson 饰）会让他去指挥即将开始的“诺曼底战役”，拒绝接受命令之后将军居然恶整了他，那就是把他当做逃兵扔进了军 营中。凯奇被归入了J小队中进行战斗，战役的第一天就惨死在战场，没想到这一死让他拥有了时空循环的能力，而唯一相信他的人就是被称为“全金属战士”的丽塔·沃拉塔斯基（艾米莉·布朗特 Emily Blunt 饰）。二人开始了时空循环作战，在训练凯奇的同时他们发现了控制时间的奥秘，这与外星人“主脑”欧米茄有关，但是唯一能取得胜利的方法就是让凯奇不断死去、不断重启时间。在不断重复登陆那天的战斗的同时，凯奇越来越不想失去丽塔……©豆瓣', '汤姆·克鲁斯', '道格·里曼', 8.2, 451866, 'tt1631867', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2185073849.jpg', 0.2, 1.3, 18.2, 51.2, 29, '0.013902,0.318522,-0.860357,0.616269,-0.104788,-0.310442,0.697819,-0.113756,-0.661617,-0.051371,0.305179,0.503604,-0.012333,-0.148731,0.262016,-0.206532,-0.550180,-0.761546,-0.159809,-0.109671,-0.509246,-0.394277,-0.246188,-0.405793,0.202969,-0.783283,0.718229,0.042322,-0.247163,0.106890,-0.053642,0.361067,0.110722,0.644031,-0.087260,0.224250,0.352428,-0.305872,-0.209952,0.402923,-0.002893,0.019000,-0.098312,0.354026,-0.105366,0.215274,0.824303,-0.615500,0.076329,-0.231692,0.102541,-0.261141,-0.069482,0.017931,0.236879,0.051636,0.080499,0.080362,0.017861,0.030094,0.074563,0.017963,-0.885958,-0.044331,-0.129494,0.243020,-0.417144,0.301304,-0.262250,0.006171,0.079636,-0.238758,0.191546,0.544607,0.570310,0.188641,-0.279564,-0.183800,-0.542760,0.167499,0.648223,-0.277637,-0.431127,0.234020,-0.056313,-0.335654,-0.156523,-0.369208,-0.323186,-0.044959,0.328976,0.139370,-0.146671,0.521939,-0.582673,0.026118,-0.409397,-0.485470,-0.041270,-0.413248,-0.060343,-0.590844,-0.168442,-0.138126,-0.127737,0.189920,-0.075386,-0.215321,0.625650,-0.988623,0.294116,0.664624,0.336988,-0.309727,0.539008,0.266840,0.097780,-0.172855,0.262063,0.202569,0.060795,0.439367,0.301348,0.422732,0.164276,-0.114188,-0.241843,0.722554', '2032339', '1793491', '21360412', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4767216', '憨豆特工2', '喜剧', '英国军情七处顶级特工约翰·英格利士（罗温·艾金森 Rowan Atkinson 饰）自5年前在莫桑比克的行动中失手后，从此销声匿迹，隐居在深山的寺院中修炼身心。但是他的人生注定充满波澜，受军情七处的召唤，约翰返回阔别已久的伦敦。此时他的老东家早已改组，新任领导帕梅拉（吉莲·安德森 Gillian Anderson 饰）命令他前往香港，阻止针对中国领导人的暗杀计划。令他意想不到的是，他的对手是一支名为“旋风”的全顶尖杀手的暗杀集团。5年时间让世界发生天翻地覆的变化，但约翰凭借修行得来的坚韧意志和智慧与杀手集团进行连番精彩刺激的较量，当然在这一过程中也闹出不少笑话。道高一尺，魔高一丈，约翰能否拯救前所未有的危机呢……©豆瓣', '罗温·艾金森', '奥利弗·帕克', 7.3, 80102, 'tt1634122', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2209714613.jpg', 0.8, 5.4, 39.3, 39.5, 15.1, '-0.105565,0.049748,-0.743810,0.552934,0.149906,-0.129766,0.395733,0.040621,-0.676214,-0.341163,0.182697,0.562601,-0.047239,-0.110308,0.428371,-0.283233,-0.055157,-0.676074,-0.045856,-0.258240,-0.095501,-0.259222,-0.377217,-0.264013,0.048912,-0.472345,0.609714,0.569268,-0.390023,0.261381,0.220182,0.502795,-0.036888,0.483677,0.067922,-0.236287,0.271154,0.098383,-0.318722,0.199695,-0.009639,-0.211427,-0.131087,0.295619,0.019951,0.305734,0.335716,-0.288446,-0.044808,-0.193623,0.277350,-0.352978,-0.213235,-0.091110,0.493833,-0.037575,0.042340,0.384038,-0.159207,-0.086016,-0.234402,-0.176075,-1.014615,-0.151104,0.170789,0.121272,-0.403607,0.234320,-0.116495,0.128025,-0.271387,-0.033581,0.278744,0.502889,0.328281,0.168888,-0.021300,0.125694,-0.336350,0.052630,0.777056,-0.272638,-0.239321,0.025005,-0.166095,-0.432898,-0.173732,-0.583443,-0.287385,-0.045149,0.089113,-0.059108,-0.069399,0.461096,-0.469068,0.013859,-0.281963,-0.103722,-0.096461,-0.295627,-0.025726,-0.803104,-0.198881,-0.243563,-0.165310,-0.049867,0.175356,-0.158397,0.606656,-0.767211,0.225205,0.493242,-0.041707,-0.391909,0.594120,-0.028592,0.247971,-0.341258,-0.127635,0.385760,0.198573,0.344797,-0.102620,0.269869,0.104517,-0.233083,-0.108883,0.332090', '1793491', '1874704', '30163500', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4798707', '爱', '剧情', '导演迈克尔·哈内克凭借本片再度勇夺金棕榈大奖。本片的两位老戏骨分别是威尼斯影后和戛纳柏林双料影帝。Anne（埃玛妞·丽娃 Emmanuelle Riva 饰）和Georges（让-路易斯·特林提格南特 Jean-Louis Trintignant 饰）这对老夫妻已经 80多岁了，他们都是退休的，有教养的音乐教师。他们的女儿Eva（伊莎贝尔·于佩尔 Isabelle Huppert 饰）也是一个音乐工作者，目前生活在国外。可是有一天，Anne突然中风，随后偏瘫，卧床不起。而正是从这一天开始，她和乔治斯的爱情，在某种程度上开始了考验......©豆瓣', '让-路易·特兰蒂尼昂', '迈克尔·哈内克', 8.6, 83251, 'tt1602620', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1566292031.jpg', 0.4, 1.1, 10.5, 42.4, 45.7, '0.042190,-0.271993,-0.668844,0.639079,-0.042354,-0.403264,0.696786,0.237091,-0.616581,-0.020292,0.262413,1.207062,-0.508185,0.319461,0.316131,0.125256,-0.510864,-0.809543,-0.009214,-0.266209,-0.286614,-0.528712,-0.378976,-0.042516,-0.102293,-0.462320,0.596321,-0.155880,0.081955,0.643820,0.543471,0.162476,0.522201,0.268748,-0.373416,0.376174,0.427983,0.043656,-0.157653,0.224451,0.291098,-0.277638,-0.257588,0.088947,0.166930,0.384773,0.315437,-0.152155,0.225111,0.184490,0.443531,-0.373831,-0.064374,-0.061223,0.436348,-0.284011,0.352347,0.253770,-0.151404,-0.010199,-0.074658,-0.248004,-0.545783,0.136682,0.008582,0.213690,-0.602372,0.524041,-0.181516,-0.324322,-0.044913,-0.029246,0.178746,0.323912,0.000887,0.391953,-0.104671,-0.090068,-0.523986,0.366122,0.501578,0.008037,-0.498590,0.591479,-0.248371,-0.779452,-0.269753,-0.303738,-0.425008,-0.065335,0.273596,-0.145833,0.141456,0.006716,-0.495545,0.318453,-0.139701,-0.222746,-0.136813,-0.308177,0.128067,-0.663530,-0.234378,-0.631448,-0.274879,-0.129939,0.135277,-0.300899,0.986856,-0.770113,0.132560,0.431234,0.182524,-0.240287,0.947515,0.123812,0.155792,-0.210509,-0.034719,0.097266,-0.099745,0.246535,0.191433,0.688552,0.251206,-0.146233,-0.254237,0.691470', '30162520', '1870681', '1292720', '3882427');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4798888', '叫我第一名', '剧情', 'BoBo（詹姆斯•沃克 James Wolk 饰）患有先天性的妥瑞氏症，这种严重的痉挛疾病，导致他无法控制地扭动脖子和发出奇怪的声音。而这种怪异的行为，更是让他从小不被周围的人理解，在学校里老师经常批评他，同学们更是对他冷嘲热讽，就连他的父亲也对他失望透顶。只有他的母亲一直是他的坚实臂弯，母亲的坚持与鼓励，让他能够在正常人的生活里艰难前行。然而面对这个不能理解他的世界，BoBo一直在痛苦的漩涡里挣扎。直到在一次全校大会上校长在众人面前巧妙的让大家了解了BoBo的真实情况，让他有了成为一名关爱学生的教师的坚定梦想，即使因为这个病症让BoBo在寻求教师梦想的道路上遭到众人怀疑，屡屡受挫，但他始终坚持着自己的这份梦想, 为了找到一个愿意接受自己的学校，不抛弃梦想，不放弃信念，默默的努力。而他曾经曲折的人生道路在他的坚持下也开始慢慢好转…该片根据布拉德•科恩的真实故事改编。', '詹姆斯·沃克', '彼得·维纳', 8.7, 183540, 'tt1292594', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p628364149.jpg', 0.1, 0.6, 10.9, 43.2, 45.2, '0.343425,0.207723,-0.931086,0.751570,-0.222662,-0.171225,0.909822,-0.038969,-0.705119,-0.060327,0.349003,0.827138,0.032655,0.421644,-0.123922,0.156713,-0.058890,-0.792701,-0.019839,0.147728,-0.369288,-0.507505,-0.299958,-0.450366,-0.481959,-0.250520,0.709380,0.274857,-0.347578,0.464238,0.215617,0.306750,0.489974,0.694130,-0.274425,-0.030962,-0.075753,-0.013189,0.059619,0.017703,0.512583,-0.329926,-0.176698,0.555370,-0.138174,0.467063,0.572786,-0.257219,-0.373778,0.211992,0.419830,-0.490933,-0.036115,0.364829,0.095890,0.015729,0.148523,0.161248,-0.179837,0.023317,-0.154900,0.157807,-0.961181,-0.308841,0.125903,0.414613,-0.868827,0.610520,-0.088073,-0.088321,0.140076,-0.282705,-0.009689,0.280301,0.160235,0.491419,-0.603395,0.037665,-0.279806,0.197698,0.824162,0.006768,-0.635406,0.308760,-0.655441,-0.270188,-0.134650,-0.317500,-0.885272,-0.151499,0.051319,0.288026,-0.464549,0.171975,-0.260581,0.056723,-0.053882,-0.295822,-0.191111,-0.581309,-0.021675,-0.286098,-0.070920,-0.527469,-0.359035,-0.174670,-0.161888,-0.628271,0.878191,-1.044179,0.250417,0.692242,0.439542,-0.504955,0.845956,0.337105,0.052570,-0.068798,-0.139110,0.468689,-0.169440,0.280959,0.173733,0.546625,0.086509,0.179653,-0.550234,0.766392', '4058933', '35030151', '3230462', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4807924', '泰迪熊', '喜剧', '该片是导演塞思·麦克法兰首次进军大银幕，自编自导的作品，片中的泰迪熊也是由他本人配音。孤僻的约翰儿时许了一个愿，希望他的玩具泰迪熊可以活过来，成为他真正的朋友。奇迹发生了，泰迪（塞思·麦克法兰 Seth MacFarlane 配音）有了生命，并和约翰一起生活了二十多年。如今老大不小的约翰（马克·沃尔伯格 Mark Wahlberg 饰）无所事事，整天和泰迪一起抽烟喝酒吸大麻，过着醉生梦死的生活。直到他遇上美丽的劳丽（米拉·库妮丝 Mila Kunis 饰），决心要改变自己。可是，泰迪却并不喜欢约翰的新女友劳丽，总是处处给劳丽找麻烦，甚至破坏约翰和劳丽的感情。面对陪伴多年的老友，和刚刚俘获的女友，约翰要如何处理两者之间的关系？他是不是能找到一个平衡点呢？©豆瓣', '塞思·麦克法兰', '塞思·麦克法兰', 7.1, 259384, 'tt1637725', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1588315198.jpg', 1, 6.2, 41.1, 38.3, 13.3, '0.266052,-0.111223,-0.464049,0.551491,-0.267808,-0.512888,0.724342,0.096584,-0.291143,-0.363358,-0.190313,0.845276,-0.160495,0.443231,0.127159,0.099188,-0.328095,-0.674720,0.213917,0.081539,-0.114061,-0.488213,-0.406339,-0.255252,0.017795,-0.249981,0.463984,-0.157780,-0.034003,0.338521,0.394126,0.301801,0.014520,0.371989,-0.065751,0.094203,0.101700,0.132358,-0.329414,0.120964,0.233123,0.142192,-0.011196,0.173103,0.285087,0.131533,0.361954,-0.225718,-0.068954,-0.040208,0.106203,-0.133014,0.123014,-0.051922,-0.015796,-0.219641,0.229349,0.200538,-0.032513,0.040158,-0.014775,-0.188904,-0.628728,-0.038968,-0.071749,0.315805,-0.598740,0.318238,-0.077242,-0.045111,-0.062290,-0.270730,0.113496,0.342514,0.320792,0.278358,-0.143781,0.083512,-0.580373,0.240411,0.690120,0.110653,-0.209717,0.479879,-0.404993,-0.254010,-0.185703,-0.234819,-0.740155,0.122473,0.065684,-0.102365,-0.239056,0.229334,-0.542683,-0.067971,-0.326035,0.099580,0.255191,-0.487913,0.092238,-0.632980,-0.054146,-0.547666,-0.185185,-0.015855,-0.034942,-0.483304,0.599873,-0.797832,0.214694,0.725497,0.163676,-0.458176,0.648696,0.380476,0.027045,-0.250550,0.073587,0.273958,-0.051729,-0.126059,0.074975,0.155570,0.358138,-0.099702,-0.362081,0.582440', '30162520', '34890458', '4275444', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4810698', 'X计划', '喜剧', '汤玛斯（汤玛斯·曼 Thomas Mann 饰）要过生日了，他在学校里的两个好友科斯塔（奥利弗·库珀 Oliver Cooper 饰）和JB（乔纳森·丹尼尔·布朗 Jonathan Daniel Brown 饰）打算为他筹办一场最疯狂的party，洗刷掉三人的屌丝身份。趁汤玛斯父母出去度周末，三人开始着手准备，他们向高中所有能接触到的同学发出了邀请，用假身份证买了酒，还搞来了摇头丸。入夜，原本担心无人前来的三人看着一波波人潮心花怒放，尤其是其中还有许多陌生美女，令三人更加荷尔蒙爆棚。人越来越多，派对也越来越疯狂，邻居投诉不断，无法阻止人们上楼和进父亲书房……汤玛斯感到越来越不安，但是科斯塔始终鼓动他享受疯狂，随着近两千人聚集，事态再也非三个少年能掌控……©豆瓣', '托马斯·曼', '尼玛·诺里扎德', 7.1, 17035, 'tt1636826', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1580563295.jpg', 2.5, 8.8, 38.1, 34.2, 16.4, '0.120136,-0.186710,-0.734422,0.210970,0.096297,-0.298608,0.723605,0.194181,-0.504425,-0.289741,-0.319280,0.514544,-0.396181,0.211538,0.418412,-0.373604,-0.246446,-0.516091,0.002109,-0.093883,-0.163136,-0.230964,0.029672,-0.359355,-0.263897,-0.219208,0.112828,-0.116935,-0.023980,0.515060,0.423729,0.209346,-0.098108,0.706163,-0.210009,-0.073518,0.122094,-0.269805,-0.258783,0.185633,0.232286,-0.124471,-0.317895,0.151672,0.216507,0.071024,0.576936,0.056986,-0.082602,-0.009504,0.277552,-0.019535,-0.102413,0.185386,0.294300,0.019954,0.245587,-0.130876,-0.171781,0.297314,0.080527,-0.116097,-0.312681,0.393728,-0.028542,0.157384,-0.385622,0.080267,-0.047314,-0.056117,0.233973,-0.425000,0.077020,0.261327,-0.300614,0.313534,-0.212860,-0.402761,-0.528831,-0.051022,0.688112,0.078277,0.243182,0.265026,-0.177575,-0.126563,-0.033142,0.094860,-0.449373,-0.035740,0.323126,0.284934,-0.003052,0.216578,-0.584339,-0.071503,-0.027527,-0.500656,-0.037999,-0.381849,-0.001250,-0.793286,-0.154149,0.033475,-0.009555,0.296123,-0.007751,-0.109853,0.546651,-0.607332,-0.108574,0.438430,0.309912,-0.426119,0.270148,-0.059974,0.083138,0.038293,-0.204280,-0.124378,0.236335,0.216678,0.288375,0.640290,-0.187555,-0.026493,-0.293254,0.296002', '3011051', '1296500', '10466639', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4811807', '亚当斯一家', '喜剧', '米高梅定格动画版《亚当斯一家》组建团队，除此前确定的奥斯卡·伊萨克，查理兹·塞隆、艾莉森·珍妮、科洛·莫瑞兹、菲恩·伍法德、尼克·克罗尔、贝特·迈德尔也加盟。讲述一个诡异古怪的家庭与一个狡猾的真人秀主持人对峙，这个家庭同时也在为新生命的到来做准备，将举办一场亚当斯式的庆祝派对。伊萨克和塞隆为戈麦斯＆莫提西亚·亚当斯夫妇配音，莫瑞兹配Wednesday ，伍法德配Pugsley ，迈德尔配祖母，克罗尔配Fester叔叔，珍妮配反派Margaux Needler。康拉德·弗农(《香肠派对》《马达加斯加3》《怪物史瑞克2》)和格雷格·蒂曼(《香肠派对》)执导，漫画家、该系列电视剧、电影的制作人查尔斯·亚当斯和Matt Lieberman、Pamela Pettler(《僵尸新娘》《怪兽屋》《机器人9号》)共同编写剧本，北美2019年10月11日北美上映。原版漫画由查尔斯·亚当斯创作，围绕戈麦斯＆莫提西亚·亚当斯夫妇及他们的孩子Wednesday、Pugsley和一群亲戚展开故事。亚当斯一家属于典型哥特式家庭，富有但古怪，亲人之间的复杂关系和家产争夺让他们的生活陷入混乱之中。1964年首次被改编成真人版电视剧，之后又陆续开发了动画版，三部真人电影分别于1991、1993、1998年上映，还被改编成音乐剧登陆百老汇。', '查理兹·塞隆', '格雷格·蒂曼', 7.3, 23005, 'tt1620981', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2553145804.jpg', 0.9, 5.5, 37.3, 39.1, 17.1, '0.219518,-0.255590,-0.277780,0.421868,0.433791,-0.269565,0.566089,0.119871,-0.279908,-0.235889,0.070499,0.971081,-0.500695,0.040329,0.437628,0.005984,-0.571555,-0.615609,-0.006986,-0.021327,0.300859,-0.456144,-0.237154,-0.355050,0.135277,-0.480076,0.633937,-0.285325,0.088763,0.471725,0.289631,0.150224,-0.161802,-0.135138,0.407888,0.268975,0.495685,-0.192262,-0.554300,0.291056,-0.279860,0.247057,-0.146950,-0.206549,0.139449,0.270009,0.607920,-0.198563,0.232010,-0.268161,0.383773,-0.059632,-0.076935,0.092366,0.181401,0.178142,0.282161,0.370146,-0.025315,0.044956,-0.173001,-0.456460,-0.628707,0.363293,0.073126,0.075907,-0.319286,0.439071,-0.321337,0.037238,0.154708,-0.217125,0.155958,0.341613,0.715874,0.525908,0.161381,0.217749,-0.235230,0.412863,0.418558,0.038486,-0.306716,0.256381,-0.066481,-0.368086,-0.216918,-0.186239,-0.480219,0.141655,0.356195,-0.258334,0.109027,0.444574,-0.728755,-0.199725,-0.254227,-0.355606,0.145652,-0.371390,0.049247,-1.071152,-0.116734,0.015549,0.023619,-0.242282,0.207441,-0.189692,0.636153,-0.438692,0.184088,0.