INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4811813', '独立日2：卷土重来', '动作', '经历过外星人大举入侵地球后，人类知道，这些入侵者有一天一定会再回来。人类运用先前外星人所遗留下来的科技文明，发展出一套强大的地球防御系统以抵御外星人的再度入侵。然而，20年后，这些外星人却带着人类前所未见、更先进强大的武力再次入侵地球，带来更大的全球灾难，几位勇敢的年轻人，他们挺身而出，将再一次为人类生存而战斗……©豆瓣', '利亚姆·海姆斯沃斯', '罗兰·艾默里奇', 5.7, 115461, 'tt1628841', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2362976267.jpg', 8.1, 25.8, 46.3, 14.8, 5.1, '-0.194386,0.405637,-0.617207,0.657416,-0.133328,0.168262,0.445917,-0.766478,-0.455397,-0.236921,0.114930,0.664921,0.224088,-0.082018,0.053470,-0.455041,-0.103004,-0.084974,0.157215,-0.190266,-0.813056,0.030173,-0.849930,-0.528830,0.003793,-0.538433,0.755372,0.262243,-0.735493,0.092045,-0.282709,0.318178,-0.051074,0.557751,-0.114160,-0.351427,-0.483653,0.071737,-0.525105,0.327893,-0.095523,0.129281,-0.211308,0.492853,-0.598509,-0.208969,0.413788,-0.667177,-0.238189,-0.742731,0.641454,-0.394083,-0.087278,0.038991,0.361510,0.111883,-0.290074,0.115103,0.392004,0.121076,-0.123676,-0.021539,-0.992581,-0.187522,-0.407181,-0.340134,-0.269264,-0.109839,0.075202,0.183034,-0.168554,-0.305492,0.057062,1.100944,0.618442,0.463107,-0.219855,-0.004238,-0.493161,0.099041,0.710712,-0.194004,-0.707143,0.173246,-0.168471,-0.623753,-0.249575,-0.940406,-0.496520,0.335885,0.043271,0.220184,-0.278084,0.893515,-1.257052,0.369168,-0.413739,-0.441860,0.182652,-0.124364,0.089592,-0.831733,-0.274286,-0.311152,-0.271315,0.331312,0.299428,-0.378942,1.304837,-0.823447,0.140047,0.997059,1.016504,-0.868594,0.233945,-0.431959,0.075244,-0.039774,-0.135354,0.386013,0.068565,0.621541,-0.247370,0.414153,0.439917,0.002144,0.082355,0.579168', '24284209', '7155241', '27602116', '1960313');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4812830', '魁拔之十万火急', '动画', '在偏远的兽国窝窝乡，蛮吉（刘婧荦 配音）和蛮大人（王凯 配音）这两个“独行族妖侠”，整天为了取得象征着成功和光荣的“妖侠纹耀”而刻苦修炼“脉术”，却把他们所生活的“窝窝乡”弄得鸡犬不宁，村民们绞尽脑汁想把他们赶走。一天，消灭魁拔的征兵令突然传到窝窝乡，村民们惊愕之余，村长（李立宏 配音）趁机忽悠蛮大人和蛮吉从军参战。然而，在这个一切都以“纹耀”来说话的世间，仅凭蛮大人现有的一块杂牌纹耀，不要说参军，就连住店的资格都没有。因此在树国客栈，受尽歧视的蛮吉和蛮大人决定，混上那艘即将启程去消灭魁拔的巨型战舰——曲境一号，直接去挑战魁拔，用热血获取至高的荣誉。绿叶港码头，龙国妖侠卡拉肖克•潘（张杰 配音）被军官（张震 配音）责打羞辱却不敢还手。已经和蛮大人成功混上战舰的蛮吉挺身而出，替潘打抱不平却受到了粗暴打压。正当蛮吉陷入挣扎与绝望时，巨大的魁拔脉兽突然出现并将蛮吉“吞噬”……', '刘婧荦', '王川', 8.1, 70645, 'tt2557868', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1091122584.jpg', 0.8, 2.6, 19.4, 43, 34.2, '0.175575,0.053381,-0.515864,0.580765,-0.006005,-0.403247,0.518204,0.058476,-0.393425,-0.307301,-0.084731,0.486588,-0.021559,0.207718,0.228350,-0.384717,-0.160969,-0.168179,-0.182246,0.158782,-0.327380,-0.260061,0.102195,-0.125226,-0.326919,-0.227841,0.658018,-0.069096,-0.264967,0.307917,0.153711,0.243012,0.118730,0.440101,-0.397487,-0.090477,-0.166021,-0.197587,0.026432,0.034154,-0.275558,-0.046131,-0.213660,0.208443,0.351128,0.283094,0.492308,-0.434229,-0.137676,-0.197547,0.083518,-0.361080,0.026965,0.114544,0.353748,-0.095020,0.133200,-0.072540,-0.084637,-0.072898,0.041671,-0.206565,-0.873835,-0.088262,-0.083651,-0.078398,-0.589636,0.085955,0.438819,0.244020,0.199804,-0.170295,0.136878,0.500512,-0.007635,0.386074,-0.140280,0.070805,-0.622839,0.151901,0.742750,-0.096354,0.024940,0.015643,0.140273,-0.521862,0.146074,-0.265180,-0.238511,-0.248155,0.246629,-0.040408,0.151053,-0.052281,-0.493742,-0.134653,-0.163847,-0.351785,0.000789,-0.472495,-0.229766,-0.429816,0.027053,-0.073444,-0.060671,0.247328,0.330760,-0.114598,0.659226,-0.797441,0.040596,0.421997,0.287514,-0.361407,0.541296,0.234622,-0.064609,-0.036769,-0.274826,-0.047641,0.439035,0.398216,0.421061,0.231447,-0.123387,-0.246790,-0.232910,0.521928', '1793491', '1811755', '30163500', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4813493', '挑战者联盟', '动画', '在南美某个安静祥和的小镇，少年阿玛迪奥（Rupert Grint 配音）痴迷于酒吧里的桌面足球，他出色的技巧赢得了女孩劳拉（Eve Ponsonby 配音）的放心，也击败了高傲自大的少年格罗索（Diego Ramos 配音）。此去经年，孩子们都已长大，阿玛迪奥依然不改对桌面足球的喜爱，即使劳拉即将去外地念书他也找不到合适的言辞应对。这一天，早已成为国际球星的格罗索突然高调返回，他买下小镇，并准备在此修建奢华的宇宙星河球场。格罗索不顾相亲的反对，率先推翻曾让他蒙受耻辱的酒吧，更带走了劳拉。阿玛迪奥痛哭流涕，谁知木头做的桌面足球队长突然活了过来。面对这群肩作战多年的老战友，阿玛迪奥似乎鼓起拯救劳拉和小镇的决心……本片根据Roberto Fontanarrosa的短篇故事《一位右前锋的回忆录》改编。©豆瓣', '鲁伯特·格林特', '胡安·何塞·坎帕内利亚', 7, 7275, 'tt1634003', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196369839.jpg', 1.5, 7.4, 43.1, 35.9, 12.2, '0.089410,0.138231,-0.622351,0.482881,-0.181158,-0.435521,0.485005,0.141031,-0.185372,-0.079112,0.288020,0.736937,-0.081194,0.196874,0.369983,0.000526,-0.193867,-0.603549,-0.199391,-0.053869,-0.117721,-0.368185,-0.316504,-0.291876,0.097798,-0.163877,0.455154,-0.146765,-0.150683,0.414219,0.231724,-0.033056,0.149208,0.308682,-0.260557,0.122681,-0.038986,0.124655,-0.197602,-0.117962,-0.032648,-0.139719,-0.349843,-0.011673,0.138177,0.282724,0.448726,-0.167919,0.042899,0.035633,0.397934,0.017262,0.097272,0.014753,0.174107,-0.160944,0.063081,0.114580,-0.049936,0.137782,-0.120782,-0.324560,-0.508260,0.103239,-0.020952,0.020032,-0.486115,0.495988,-0.090067,-0.076895,0.003748,-0.249503,0.043155,0.098984,0.144934,0.376281,0.005385,0.224020,-0.133079,0.258250,0.361776,0.097480,-0.322466,0.011402,-0.245581,-0.317522,0.094782,-0.382182,-0.533857,-0.004708,0.295894,-0.276125,-0.091333,0.111246,-0.419297,0.002000,-0.233815,-0.312013,0.147769,-0.293314,-0.053516,-0.632480,-0.040262,-0.151483,-0.109475,-0.057164,0.053394,0.038712,0.773705,-0.499175,0.170405,0.620222,0.080855,-0.326734,0.552025,0.034982,0.134254,-0.086702,-0.039874,0.330764,-0.123948,0.212667,-0.025770,0.406415,-0.002957,-0.101796,-0.536834,0.525372', '1870681', '3811356', '30162520', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4813645', '橡皮轮胎杀手', '喜剧', '一望无际的荒漠旷野之上，盘桓着十多名不同身份不同年龄的普通人，他们手里各自拿着一个望远镜，透过镜片兀自眺望着远方。其中一人发现了一处垃圾场，所有的人也都向那里望去。视野中，一只蒙满沙尘的轮胎动了起来，匪夷所思的是，它的动作完全没有借助任何外力，仿佛全由其自身掌控一般。它蹒跚学步，磕磕绊绊，碾压着路上的空瓶子和蝎子。偶然间，轮胎似乎发现自己具有神奇的能力，只要集中注意力盯着（如果它有眼的话）前方的生命体数秒钟，对方就会脑袋炸裂爆头倒毙。“哦耶！这简直太给力呐！”轮胎心中一定这样想到。于是，它滚着矫健的步伐，向前方走去，一路上掀起血雨腥风。而那群完全没有头脑的观着，始终注视着这离奇的一切……©豆瓣', '罗克珊·梅斯基达', '昆汀·杜皮约', 6.5, 6839, 'tt1612774', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p905651269.jpg', 5.8, 13.8, 41.5, 28.2, 10.7, '0.466326,0.074731,-0.912338,0.604809,0.048141,0.045904,1.057415,0.097977,-0.134089,-0.090334,0.138380,0.422872,-0.128052,-0.134093,-0.135786,-0.077086,-0.344833,-0.700397,-0.650351,0.007745,-0.611383,-0.329709,-0.389665,-0.079407,-0.069018,-0.063447,0.384331,0.149605,-0.261374,0.525064,-0.002091,-0.345776,-0.081951,0.357531,-0.398305,-0.066190,-0.389054,-0.065049,0.306434,0.270450,-0.041627,-0.281801,-0.091401,0.335332,-0.399096,0.179365,0.772872,-0.370501,-0.157249,0.055386,0.069077,-0.233929,0.207886,0.202275,0.298642,0.098869,0.100020,-0.419106,0.136869,-0.095808,0.314069,0.302832,-0.493886,-0.166689,-0.261444,0.494589,-0.499104,0.146376,0.235303,-0.261681,-0.039382,-0.248815,0.305801,-0.189281,0.027764,0.312760,-0.564216,-0.040353,-0.690931,-0.315069,0.221114,0.271492,-0.525745,0.135529,-0.136807,-0.388303,-0.358193,0.194931,-0.238627,-0.418986,0.535339,0.609640,-0.149328,0.089095,-0.351404,0.584754,0.060758,-0.468213,-0.394123,-0.405765,-0.253523,-0.348641,0.208402,-0.599778,-0.296144,0.386392,-0.109300,-0.161104,0.438303,-0.110691,0.075846,0.595030,0.226809,0.363343,0.736268,-0.477220,-0.067079,0.158583,-0.298807,-0.015067,0.104385,0.532677,0.187392,0.492383,0.056591,0.056559,-0.451725,0.631334', '20451118', '26342391', '21619567', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4816602', '魔境仙踪', '奇幻', '奥斯卡（詹姆斯·弗兰科 James Franco 饰）是个只会雕虫小技的马戏团魔术师，却无意中被龙卷风从尘土飞扬的堪萨斯城带到了神奇美妙的奥兹国。那里的居民认为他是传说中的大魔法师从天而降，祈求他击败穷凶极恶的邪恶女巫拯救奥兹国，可心术不正的奥斯卡却把这境遇看作是发大财的绝佳良机。三位自称是奥兹国守护者的女巫赛多拉（米拉·库妮丝 Mila Kunis 饰)、伊诺拉（蕾切尔·薇姿 Rachel Weisz 饰）和 格琳达（米歇尔·威廉姆斯 Michelle Williams 饰）却对奥斯卡的身份各有怀疑。当黑暗势力压境，奥斯卡被迫卷入纷争，他才发现自己必须擦亮双眼，分辨出这些美艳女巫们究竟孰善孰恶，是敌是友，不然一切美好都要灰飞烟灭。奥斯卡决定放手一搏迎战邪恶女巫，可自己的魔术伎俩，要如何才能抗衡女巫强大而邪恶的魔法？奥兹仙境的前途，又将何去何从？©豆瓣', '詹姆斯·弗兰科', '山姆·雷米', 6.4, 49304, 'tt1623205', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1776534018.jpg', 2.5, 14, 53, 23.7, 6.8, '-0.034469,0.148783,-0.298768,0.475607,-0.245870,-0.015679,0.639617,-0.076562,-0.096759,-0.213941,0.315349,0.770784,-0.140311,-0.075735,0.110163,0.294403,-0.134757,-0.719910,-0.119924,-0.208249,-0.110917,-0.485676,-0.570072,0.029619,0.146168,-0.345467,0.627215,0.116515,-0.355038,-0.070745,0.546973,0.361895,-0.225879,0.242721,-0.160255,-0.186118,0.060298,-0.100081,-0.258219,0.095447,-0.255556,-0.090904,-0.335323,0.440456,-0.023223,0.191137,0.453089,-0.581953,0.209270,-0.074308,0.305709,-0.400714,0.035688,0.291389,0.045781,-0.358333,-0.058127,-0.092665,0.272625,-0.079454,0.234855,-0.025687,-1.079904,0.125532,0.221566,0.070598,-0.478473,-0.056641,0.057705,-0.189205,0.143442,0.128448,0.089931,0.016528,0.288244,0.302299,0.144009,-0.061953,-0.496482,-0.101481,0.450237,0.019272,-0.571690,0.184312,-0.278144,-0.446407,0.024267,-0.415838,-0.580556,-0.133060,0.474145,0.016816,0.135301,0.455522,-0.400188,-0.128031,-0.440592,-0.042961,-0.141185,-0.248574,0.022906,-0.264703,-0.146240,-0.304940,-0.393588,-0.109461,0.195426,-0.223654,0.765416,-0.689980,0.192733,0.737110,0.210143,-0.251009,0.555448,0.042796,0.051220,-0.013999,-0.286406,0.226063,0.085225,0.108041,0.002932,0.329240,0.275929,-0.194598,-0.204603,0.525054', '24284209', '1793491', '27098364', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4817024', '宠物情人', '剧情', '恩熙（金荷娜 Ha-Neul Kim 饰）是个在工作上得心应手却不擅长人际交往的海归女强人，在经历了被未婚夫抛弃的打击之后，接踵而至的职场受挫又让她被调去女性时尚杂志做编辑工作。听到同事们对她背后的议论，恩熙一个人默默苦恼，心情烦闷至极准备养一只宠物狗。机缘巧合让他与体贴可爱的仁浩（张根锡 Keun-Suk Jang 饰）相遇。仁浩是一个外形完美，年轻帅气的古典芭蕾的天才，无家可归的他因为朋友恩秀的原因住进了恩熙的家中，意外的扮演起了宠物情人的角色。两人就此过起了了主人和宠物的浪漫幸福生活。同居生活让二人的感情产生了微妙的变化，直到恩熙大学时期暗恋的学长车前辈出现，并明显的表露着对恩熙的爱恋，宠物和学长到底谁能住进恩熙的心中的家…该片改编自日本漫画家小川弥生的超人气漫画《宠物爱人》。©豆瓣', '张根硕', '金炳坤', 5.8, 25902, 'tt2040605', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1249580465.jpg', 6.8, 23.5, 49.8, 14.3, 5.5, '0.477807,-0.221900,-0.517675,0.674725,-0.129557,-0.261136,0.790863,0.177766,-0.365003,-0.166097,0.209747,0.847673,-0.175033,0.461425,0.248301,-0.016671,-0.056797,-0.714286,-0.019145,0.086644,0.045402,-0.196880,-0.244169,-0.084959,-0.136855,-0.350813,0.663496,-0.167096,-0.102812,0.526189,0.387360,0.204982,-0.117459,0.219947,-0.232234,0.070913,0.205391,0.300060,-0.121518,0.082205,-0.018929,-0.117675,0.082467,0.280644,0.022898,0.259749,0.822705,-0.092395,-0.447024,-0.035065,0.485953,-0.071737,-0.048274,0.135513,0.344426,0.068693,0.236709,-0.050694,-0.137260,0.107939,0.032671,-0.062672,-0.754122,-0.011853,0.055973,0.065790,-0.480958,0.670618,0.007585,-0.188424,0.154385,-0.329947,0.266055,0.171753,0.204048,0.496570,-0.234999,0.445044,-0.153766,0.405832,0.602369,0.148761,-0.275003,0.567087,-0.531016,-0.427128,-0.049027,-0.306556,-0.773173,-0.001406,0.223971,-0.030868,-0.355169,0.200526,-0.658689,-0.038259,0.004320,0.161091,-0.072876,-0.677478,-0.155455,-0.329272,-0.201383,-0.482220,-0.386925,-0.132175,0.125429,-0.261757,0.979168,-1.085456,0.039167,0.557924,0.152131,-0.527769,0.641158,0.236773,-0.092355,-0.142885,-0.112683,0.181192,-0.212185,0.082528,0.159116,0.482451,-0.114598,-0.166689,-0.401018,0.407469', '1292219', '3445516', '6963575', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4817901', '潜伏', '惊悚', '在高中担任教师的乔什·莱姆波特（帕特里克·威尔森 Patrick Wilson 饰）和身为自由音乐人的妻子兰娜（罗丝·拜恩 Rose Byrne 饰）拥有一个幸福的五口之家。然而自他们乔迁新居之后，恐慌和不安便尾随而至。尚在襁褓中的女儿凯莉经常莫名大哭，次子福斯特（Andrew Astor 饰）对卧室充满恐惧，而长子达尔顿（Ty Simpkins 饰）更在一次惊吓过后陷入长久的昏迷之中。在此之后，各种奇怪恐怖的事件接连发生。莱姆波特夫妇不胜其扰，精神几近崩溃，他们最终决定搬离这个不祥之地。但是一切并未就此结束，侵扰他们的魔鬼似乎尾随莱姆波特一家来至新的住所，更扬言要占据达尔顿的身体……©豆瓣', '罗丝·伯恩', '温子仁', 7.8, 146607, 'tt1591095', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p919571676.jpg', 0.5, 2.8, 25.8, 47.1, 23.8, '0.108889,-0.076816,-0.820569,0.416206,0.157920,-0.309389,0.872580,0.353749,-0.850316,-0.572227,0.327108,0.781967,-0.308525,0.230672,0.382075,0.006494,-0.285115,-0.493706,0.092055,-0.149697,-0.171947,-0.336681,-0.359077,-0.374322,-0.027315,-0.409415,0.350838,0.129025,0.102538,0.751309,0.214565,0.658239,-0.085836,0.589847,0.056020,0.043061,0.153409,-0.164295,-0.244669,0.011103,0.099741,-0.068468,-0.165969,0.063374,-0.024651,0.238046,0.757258,-0.297071,-0.134844,-0.222940,0.355683,-0.219272,-0.169920,0.358015,0.201006,-0.063379,0.128007,0.092595,-0.317073,0.077408,0.044673,-0.089553,-0.606319,0.298795,0.083235,0.369957,-0.309293,0.284364,-0.188482,-0.063933,0.314919,-0.159378,-0.024506,0.442410,0.105120,0.540452,-0.372070,-0.051949,-0.450258,-0.256764,0.581642,-0.235325,-0.231000,0.131710,-0.339401,-0.351993,-0.016426,-0.030987,-0.575420,-0.171181,0.284660,0.374435,0.062583,0.429180,-0.519463,-0.303677,-0.355408,-0.218310,-0.139603,-0.305014,-0.130766,-0.748742,0.008754,-0.052918,-0.013070,-0.083697,0.082273,-0.192093,0.388000,-0.724574,0.559702,0.187832,0.271246,-0.296052,0.198650,-0.043711,0.417884,-0.116095,-0.110239,0.575664,0.133425,0.154308,-0.015094,0.106738,-0.053459,0.262644,-0.291179,0.653626', '4896894', '1465415', '30137576', '26684564');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4819988', '房间', '剧情', 'Johnny（托米·韦素 Tommy Wiseau 饰）是一个成功的银行家，对朋友家人很好，尤其是他的未婚妻Lisa（Juliette Danielle 饰）。然而Lisa是个两面派，一边若无其事地和Johnny相处，另一边却勾引他最好的朋友Mark（格雷戈·赛斯特罗 Greg Sestero 饰），他们背着Johnny多次发生不正当关系。这天，Johnny升职未果，意志消沉的他回家后得到Lisa安慰。可是Lisa背着他，对其他人撒谎称Johnny不仅喝醉了，还动手打她。Johnny最终能不能发现未婚妻的谎言以及她和他最好的朋友之间的不正当关系？©豆瓣', '托米·韦素', '托米·韦素', 4.2, 10299, 'tt0368226', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2511492546.jpg', 56.7, 14.6, 6.6, 3.6, 18.4, '0.509441,-0.178549,-0.625567,0.651556,-0.337668,-0.202124,0.690463,0.004458,-0.508016,-0.317579,-0.041450,0.710536,-0.228348,0.123094,0.038771,0.228063,-0.235875,-0.743055,0.159348,0.162545,-0.201320,-0.508165,-0.429745,0.070585,-0.402237,0.014944,0.320957,-0.177523,-0.216497,0.466225,0.487795,0.243237,0.272251,0.702475,-0.378098,-0.024991,-0.034906,0.153851,-0.190020,0.412460,0.390094,-0.099258,-0.026413,0.331018,0.237551,0.493194,0.304347,-0.183571,-0.155981,0.153599,0.184106,-0.471574,0.111973,0.337219,0.142673,-0.211386,0.403201,0.408996,-0.015884,-0.141051,0.124444,0.145486,-0.620888,0.108956,0.183757,0.092587,-0.590730,0.634261,-0.213070,-0.028824,0.062434,-0.294947,0.292192,0.460677,0.160024,0.158075,-0.228112,-0.059603,-0.730307,-0.016846,0.680480,0.181519,-0.008073,0.492695,-0.149462,-0.269741,0.068561,-0.315244,-0.628049,0.012922,-0.026835,0.167642,-0.276403,-0.181997,-0.302760,-0.190259,-0.061615,0.090481,0.011247,-0.640238,0.207357,-0.205664,-0.155687,-0.761282,-0.669095,0.046784,-0.187120,-0.408320,0.525190,-0.949427,0.018330,0.502046,0.508602,-0.583183,0.761673,0.621371,-0.190436,-0.309296,-0.024051,0.038344,0.160946,-0.126822,0.229874,0.381989,0.289289,-0.223172,-0.250186,0.344316', '1308755', '2071525', '1301022', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4820775', '蝙蝠侠：红影迷踪', '动作', '这一集由蝙蝠侠连载同名故事改篇。这一次故事从蝙蝠侠的助手Jason Todd——第二任罗宾被小丑谋杀开始，之后很长一段时间蝙蝠侠都活在悔恨的情绪中。在蝙蝠侠继续守护这个罪恶城市的多年之后，突然高谭出现了一位神秘的Red Hood。他以暴制暴地压制坏人，面对残忍的暴力就用更强大的暴力去镇压。这个横空出世的Red Hood一边让犯罪分子们头痛不已，一边也引起了蝙蝠侠的高度关注。而蝙蝠侠的死对头——小丑也一点不让他省心，继续制造多起麻烦。蝙蝠侠为维持正义、拯救城市，必须与神秘的Red Hood展开对战。Red Hood的真实身份是谁？他除了惩治罪犯还有其他目的吗？©豆瓣', '布鲁斯·格林伍德', '布兰登·维埃迪', 8.5, 13817, 'tt1569923', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2164031149.jpg', 0.2, 0.7, 13.6, 44.3, 41.1, '0.190092,0.087359,-0.589634,0.715332,-0.219726,-0.110739,0.803795,-0.100174,-0.317776,-0.265084,0.280302,0.734508,-0.221197,0.223890,-0.057693,-0.180339,-0.463024,-0.616653,-0.138240,0.004112,-0.309698,-0.272609,-0.413070,-0.405274,0.068503,-0.131108,0.614386,0.202647,-0.344217,0.087272,0.611590,0.126975,-0.138363,0.271406,-0.191566,-0.259263,-0.047276,-0.066147,-0.166727,0.272787,0.275939,-0.204665,-0.156267,0.417233,-0.330967,0.240308,0.559122,-0.449652,-0.293023,-0.111385,0.548560,-0.523408,-0.165963,-0.054545,0.084604,-0.214905,0.069368,0.217674,0.006912,0.121439,-0.005117,0.034779,-1.232856,-0.055838,-0.063924,0.154377,-0.423324,0.270062,-0.120317,-0.177733,0.337475,-0.109314,0.110953,0.278734,0.471564,0.314954,-0.277248,0.102385,-0.247287,0.273689,0.641503,0.020729,-0.315388,0.210882,0.057430,-0.203837,-0.246769,-0.509852,-0.394797,-0.177182,0.124556,-0.162820,-0.051586,0.402195,-0.645638,0.097220,-0.247191,-0.202664,-0.048203,-0.363466,-0.248669,-0.535935,-0.122849,-0.113796,0.107615,-0.058985,0.141309,-0.450578,0.859582,-0.577369,0.250376,0.891910,0.281835,-0.740880,0.360609,0.352570,-0.018799,-0.127126,-0.295887,0.136980,0.200957,0.428972,0.141456,0.161788,0.133077,-0.151296,-0.287169,0.655725', '26678784', '30163500', '30368448', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4821015', '守望者：罪恶迷途', '剧情', '楚小莉（黄圣依 饰）和三名好友结伴寻访库依族文化，途中他们希望借宿小莉父亲的朋友家，然而主人不在，只有一个阴森森的男人接待了他们，恐惧也旋即降临。某国营厂青年职工周栋（陈思成 饰）来到潘家镇探访退休职工黄老爷子，他在东风旅社偶遇一名满面沧桑的中年男子。周栋和他成为朋友，并现身说法为其上了一堂现代男女辩证关系课。殊不知他自以为是的说教，会造成怎样无法挽回的后果。二十年的牢狱之灾过后，颓废落寞的男子重新站在生命的岔路口。何去何从，全然无有头绪，就在这个关键时刻，一起突发事件推着他迈出至关重要的一步。©豆瓣', '任达华', '非行', 6.9, 18408, 'tt1876441', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p876107391.jpg', 3.6, 9.9, 37.9, 36.1, 12.5, '0.281302,-0.004688,-0.596967,0.241235,-0.186608,-0.402253,0.809309,0.351032,-0.346678,-0.164987,0.571300,0.631706,-0.070059,0.497219,0.313211,-0.223690,-0.094421,-0.415017,-0.013768,-0.070046,-0.313218,-0.186975,-0.053057,-0.247106,-0.083111,-0.107382,0.616047,0.171141,-0.101509,0.464441,0.220600,0.134859,-0.289317,0.596802,-0.231277,-0.009648,0.199223,0.107226,-0.217961,0.073424,-0.049494,-0.463166,-0.230475,0.091700,-0.365696,0.361552,0.471335,0.094491,-0.310817,0.111944,0.332483,-0.129690,0.014269,0.198456,0.199177,-0.194298,-0.011291,0.348158,-0.014071,-0.135001,0.003039,0.015939,-0.356030,0.057869,-0.166232,0.423703,-0.767994,0.639118,0.133441,-0.230591,0.047475,-0.259601,0.087822,0.330781,0.153275,0.245239,-0.172321,-0.015972,-0.473157,0.282456,0.632164,0.048376,-0.189212,0.248352,-0.168815,-0.368645,0.047956,0.112357,-0.480545,-0.199752,0.175952,-0.054990,-0.061631,-0.019449,-0.468222,0.079035,-0.050159,0.135808,-0.201347,-0.234156,-0.075604,-0.382216,-0.046273,-0.360542,-0.453858,0.175243,0.234447,-0.101699,0.505014,-0.578517,0.112545,0.354393,0.320253,-0.337006,0.671087,-0.095205,0.148006,-0.447971,-0.122486,0.153958,-0.099566,0.480047,0.061517,0.290524,-0.076405,0.197774,-0.207266,0.302684', '21619567', '3111650', '1302384', '1783772');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4821046', '关云长', '动作', '东汉末年乱世中，刘备的两位夫人、以及一位未过门的小妾绮兰（孙俪 饰）受困曹营，关云长（甄子丹 饰）为存忠义投降曹操（姜文 饰），但始终不能原谅曹操操控汉室的狼子野心，希望能够重回刘备身边。曹操倾慕关羽之将才以及仁者之心，试图用天下苍生之利益说服后者。适逢袁绍起兵伐曹，关云长于阵斩杀颜良，获封汉寿亭侯，并与张辽（邵兵 饰）结下同袍之谊。曹操将两位刘夫人遣返后，在关云长酒中加入春药，欲使其与绮兰发生不义关系——关云长昔日对同乡绮兰暗怀情意，甚至曾经不惜为她杀死官兵，这段感情终究被叔嫂之礼阻断，清醒过来的关云长携绮兰投奔刘备，沿路冲破重重关卡，留下“过五关斩六将”的千古传奇……©豆瓣', '甄子丹', '麦兆辉', 5, 87098, 'tt1648093', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p957241818.jpg', 14.5, 34.6, 39.5, 8.6, 2.8, '-0.002562,0.232942,-0.517898,0.654121,0.260913,-0.070264,0.320704,0.237541,-0.457058,-0.469220,0.036369,0.478192,-0.040089,0.062932,-0.219940,-0.308279,0.191608,-0.737843,-0.058688,-0.110725,0.249827,-0.299312,-0.327536,0.127205,-0.682961,0.029180,0.815593,0.112302,-0.136783,0.438343,0.185062,0.083515,-0.017625,0.561637,0.119481,0.220397,-0.502357,-0.023565,-0.783226,-0.091584,-0.182405,-0.425337,-0.343693,0.059368,-0.276797,0.061261,0.349619,-0.410274,0.220108,-0.244932,0.138001,-0.064709,0.377381,0.119666,0.019267,0.074448,0.089297,0.525633,0.225216,-0.072228,0.189986,-0.031674,-0.491370,-0.131701,-0.021742,-0.256616,-0.397555,0.325789,-0.162499,-0.094294,-0.040514,-0.202316,0.065597,0.391801,0.370978,-0.062653,-0.293996,-0.153515,-0.428967,0.306562,0.493118,-0.163511,-0.017765,-0.125799,0.311058,-0.379620,0.396882,-0.098785,-0.507683,0.195575,0.405718,0.068483,0.288862,0.336302,0.026341,-0.411724,-0.463154,0.780573,0.220360,0.102992,0.341699,-0.199245,-0.207164,-0.328423,-0.449397,0.043315,0.644541,-0.046865,0.504970,-0.434829,-0.388479,-0.090737,0.226984,-1.013590,0.491213,0.413539,0.195545,0.122846,-0.074287,0.363674,0.241925,-0.155129,0.353118,-0.043417,-0.537853,0.119525,-0.309015,0.127131', '1294693', '1484760', '2135981', '3606975');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4822829', '白夜行', '剧情', '昭和五十五年的一桩密室谋杀案，由于上司急于升迁，所以最终草草结案，惟有警探笹垣润三（船越英一郎 饰）对此案不能释怀。多年后，当年嫌犯的女儿西本雪穗已改名唐泽雪穗（堀北真希 饰），并且过着与之前毫不相干的生活。但是，仿佛她有幸运之神的庇护一样，凡是给她制造麻烦的人，都会发生意外。后来，雪穗的好友江利子（绿友利惠 饰）与有钱人家的少爷篠冢一成（姜畅雄 饰）相恋，但最终一成却选择了与雪穗结婚。此时，笹垣虽已退休，但他始终没有放弃追杀当年谋杀案的真相，而且，他的目标最终锁定了当年被害人的儿子桐原亮司（高良健吾 饰）和雪穗……本片改编自东野圭吾的同名小说。©豆瓣', '堀北真希', '深川荣洋', 6.9, 63702, 'tt1613028', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p889409962.jpg', 1.6, 9.7, 43.6, 33.3, 11.8, '0.153486,0.059553,-0.434170,0.484754,0.025639,-0.471841,0.682320,0.147903,-0.586873,-0.527599,0.082101,0.748213,0.010003,0.134810,0.022222,0.095380,-0.164740,-0.552436,0.116855,-0.150111,-0.098331,-0.645845,-0.316413,0.067978,-0.201886,0.082687,0.704791,0.254002,0.116869,0.276378,0.249700,0.225247,-0.127206,0.348010,-0.028494,0.175643,-0.047392,0.410002,-0.220540,0.161874,0.099728,-0.276947,-0.128225,0.197715,0.125099,0.681570,0.487490,-0.304700,-0.266660,-0.074337,0.369814,-0.280058,-0.063611,0.157593,0.258925,-0.067975,0.375871,0.639107,-0.228958,-0.207902,0.028546,0.139973,-0.630794,-0.034563,0.451487,-0.012339,-0.347732,0.474015,-0.194208,0.079783,-0.093241,-0.349883,-0.010131,0.349754,0.357478,-0.007447,-0.393497,-0.006872,-0.495374,0.401935,0.591913,-0.053609,-0.174155,0.329633,0.014944,-0.452458,-0.287310,-0.404812,-0.449148,0.228058,0.210868,0.321206,-0.217375,0.253943,-0.231482,-0.453330,-0.216792,0.320949,0.093679,-0.316299,0.148437,-0.248367,-0.032003,-0.555037,-0.354194,0.112577,0.187722,-0.360744,0.448578,-0.606938,0.113260,0.359971,0.169224,-0.581027,0.531503,0.324234,0.119668,-0.089885,0.012912,0.119582,0.133303,0.282258,0.341518,0.049601,0.225448,-0.331264,-0.255784,0.161292', '25721544', '10546747', '1301022', '26729194');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4822845', '戒烟不戒酒', '剧情', '人到中年的严保久（朱时茂 饰）凭借过人酒量，叱咤商海多年，所获颇丰。如今身为广告公司副总的他，不仅有令人羡慕的高收入，还有一个幸福美满的家庭。一次喝醉签错合同丢掉了饭碗，而且当晚居然阴差阳错的进错门，躺在了过气女演员白兰（杨恭如 饰）的床上。严保久在朋友的鼓励下振作精神，打算自己创业，可是创业过程并不顺利，还好白兰几次出手相助，才让他的广告公司慢慢走上正轨。此时，严保久与白兰关系甚密让妻子陶刘雁（邬君梅 饰）一度怀疑丈夫出轨，而女儿蒙蒙（刘欣 饰）和自己公司的小林（乔任梁 饰）也展开了地下恋情。事业的重新起步，家庭危机的崭露，严保久将如何面对……本片集结娱乐圈老中青三代多位明星，由著名笑星朱时茂自导自演，其强大的明星阵容，堪称国产片之最。©豆瓣', '朱时茂', '朱时茂', 6.1, 15154, 'tt2473754', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p813149092.jpg', 4.6, 17.9, 52.4, 20.7, 4.5, '-0.112368,0.095061,-0.677290,0.612792,-0.135473,-0.300228,0.417354,0.298695,-0.524188,-0.439574,0.099245,0.625506,-0.132071,0.378461,0.230289,-0.196789,0.098701,-0.718779,-0.090143,0.204550,-0.267577,-0.315021,-0.467613,-0.088159,-0.418690,-0.030482,0.611436,0.169108,-0.243382,0.145562,0.492964,0.032702,-0.117138,0.424671,0.080158,0.066246,0.157581,0.341924,-0.433725,0.123681,0.060603,-0.438197,-0.076749,0.115793,0.332477,0.204567,0.356840,0.214098,-0.251858,-0.086220,0.470222,-0.122284,-0.063991,-0.015750,0.436846,0.079294,0.239454,0.139129,-0.202252,0.014581,0.060053,-0.278560,-0.706517,-0.082243,0.273418,-0.258202,-0.749116,0.377275,-0.093363,-0.052684,-0.214086,-0.273261,-0.005757,0.490203,0.341770,0.128066,-0.200657,0.405087,-0.498116,0.357858,0.345533,0.162042,-0.252038,0.313683,0.079262,-0.504810,-0.196386,-0.273803,-0.424065,0.064133,0.423446,-0.013865,0.106900,0.094619,-0.358375,-0.108732,-0.125604,0.014280,0.052312,-0.127806,0.197915,-0.363721,-0.169553,-0.397100,-0.223048,0.059582,0.029172,-0.467036,0.648933,-0.593726,-0.037458,0.193664,0.206092,-0.607544,0.525827,0.080510,0.116192,-0.179575,-0.107065,0.135633,0.027942,-0.013278,0.383051,0.163431,-0.263804,-0.265986,-0.014881,0.261097', '6101834', '4301278', '1301022', '1308989');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4822848', '武林外传', '喜剧', '电影版《武林外传》豆瓣小站：http://site.douban.com/112058贼奸商图谋七侠镇，众伙计力保同福居。郭芙蓉（姚晨 饰）脾气再度发作，怒打客人令佟湘玉（闫妮 饰）出钱赔礼、感叹生意难做。被打客人乃是六品户部京官裴志诚（岳跃利 饰），他此来七侠镇有着不可告人的目的。为防止裴志诚再惹麻烦，同福众人将其看押，裴志诚在杀手姬无力帮助下始得脱身，开始实施七侠镇河西改造计划，大肆收购河西土地，对于部分拒售户主，由姬无力出面行凶搞定。裴志诚当众宣布西河大开发，引发房价疯涨，白展堂（沙溢 饰）、吕秀才（喻恩泰 饰）顿感男人的压力。无双（倪虹洁 饰）与小六调查镇上的凶杀案，反被裴志诚先发制人，险些性命不保。炒地幕后大老板潘公公令姬无力清除裴志诚，迫使后者与同福众人合作，揭发炒地内幕……©豆瓣', '闫妮', '尚敬', 6.4, 186885, 'tt1943048', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p815559561.jpg', 3, 14.6, 48.7, 24.7, 9, '-0.152845,0.101912,-0.199630,0.192466,0.274242,0.212921,0.050115,0.420721,-0.434033,-0.215339,0.043943,0.199836,-0.341693,0.013166,0.085808,-0.322012,0.184266,-0.348440,0.055842,0.038306,0.178040,-0.188307,0.020167,-0.688455,-0.234422,0.096962,0.263723,0.405188,-0.583685,0.109519,0.533309,0.339949,-0.269853,0.005755,0.115526,-0.046024,-0.048299,-0.242218,-0.225891,0.171836,-0.326806,-0.427146,-0.083532,-0.105795,0.365518,0.537591,0.217772,-0.036758,-0.296766,-0.387467,0.179786,-0.041337,0.134171,0.139319,0.295639,0.026013,0.045299,0.262511,-0.431915,-0.197164,0.277667,-0.219168,-0.371628,0.194779,0.475136,-0.217000,-0.488214,-0.087453,-0.069705,0.244853,-0.283792,-0.109692,0.087986,0.344608,0.267291,-0.179082,0.252397,0.177635,-0.318845,0.315942,0.412857,-0.121230,0.442288,-0.308109,0.170632,-0.168234,0.057555,-0.189750,0.095277,-0.068685,0.339743,-0.140191,0.340247,0.104736,-0.141078,-0.398643,-0.351409,0.102162,-0.055566,0.238550,0.006991,-0.362905,-0.105416,0.192030,0.032987,-0.022920,0.388949,-0.098214,0.291800,-0.381743,-0.385453,0.316572,0.417643,-0.792404,-0.035709,-0.109118,0.202980,-0.379945,-0.266102,-0.311331,0.364622,0.222952,0.356517,-0.015220,-0.343085,-0.339722,0.073651,-0.122245', '1302110', '1484760', '2214140', '1297710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4824223', '日照重庆', '剧情', '年过半百的航运船长林权海（王学圻 饰）在14年后重返重庆家中，他一心忙于事业，以致接连遭遇两次失败的婚姻，而在他外出期间，25岁的儿子林波（子义 饰）也因在超市抢劫、伤人被警方当场击毙。对林权海来说，这个阔别已久的城市有着太多太多让他难以理解的变化。在此之后，他接连拜访前妻李育英（丁嘉丽 饰）、朋友老金（王奎荣 饰）、老金的儿子昊子（秦昊 饰）、女店员玲子、被劫持的人质竹青（范冰冰 饰）、林波的女友小雯（李菲儿 饰）以及击毙林波的刑警刘成（张嘉译 饰），只为看清儿子真正的面目和内心，以及十数年落转所失落的情感碎片……本片取材自发生在重庆的一起真实事件。©豆瓣', '王学圻', '王小帅', 6.4, 24125, 'tt1646123', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p689816226.jpg', 2.3, 12.4, 52.6, 26.8, 5.9, '0.072650,0.059590,-0.619302,0.370606,0.014770,-0.329237,0.653809,0.082860,-0.640901,-0.468446,0.294886,0.413576,-0.142292,0.295043,0.244661,-0.157549,0.019164,-0.473544,0.003897,-0.091895,-0.163987,-0.310063,-0.235348,-0.132253,-0.220444,-0.254632,0.641574,0.119866,0.052886,0.469167,0.402388,0.409038,-0.131335,0.436104,0.014772,0.274610,0.028056,0.171045,-0.477400,-0.103416,0.110621,-0.406843,0.051899,0.203562,-0.173057,0.385601,0.800685,0.040635,-0.272993,-0.063393,0.421030,-0.193448,-0.004604,0.006329,0.407344,-0.009561,0.195325,0.188273,-0.290491,-0.065917,0.273460,0.116718,-0.461771,-0.050937,0.288675,0.030606,-0.558635,0.454004,-0.259436,0.126024,0.118967,-0.241340,0.109999,0.476954,0.163460,0.281435,-0.310439,0.029984,-0.349716,0.593955,0.682476,-0.034661,0.027599,0.181845,-0.284763,-0.382635,-0.078477,-0.257267,-0.450940,0.158933,0.224824,-0.015338,-0.208121,0.185802,-0.361842,-0.234674,-0.209622,0.144670,0.022069,-0.236232,-0.023656,-0.511702,-0.132054,-0.634050,-0.241885,-0.021501,0.141156,-0.209808,0.448965,-0.711352,0.107484,0.244709,0.097760,-0.430819,0.513020,0.109720,0.160622,-0.337844,-0.094272,0.311702,0.101029,0.097433,-0.087991,0.193335,-0.038423,-0.128573,-0.171699,0.250038', '1301022', '35030151', '1293265', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4824512', '驯龙高手2', '动画', '年轻英勇的维京勇士小嗝嗝 （杰伊·巴鲁切尔 Jay Baruchel 配音）驯服受伤的龙，更与它成为好友。经过五年时间，博克岛居民的生活彻底渗入龙的气息。博克岛现已是个维京人与龙和平共存的天堂。然而，成长却意味着责任。为了寻找答案，小嗝嗝与忠诚的没牙仔开始了他们的冒险旅程，但结果却超乎预料。一方面，小嗝嗝发现神秘的驯龙骑士，正是失踪多年的亲母沃尔卡（凯特·布兰切特 Cate Blanchett 配音）；另一方面，嗜权的德雷格（杰曼·翰苏 Djimon Hounsou 配音）与龙猎人埃雷特（基特·哈灵顿 Kit Harington 配音）结盟，威胁到博克岛上人与龙的和平。为了保护深受大家喜爱的龙，阿丝翠德（亚美莉卡·费雷拉 America Ferrera 配音）、高博（克雷格·费格森 Craig Ferguson 配音），维京伙伴们：鼻涕虫（乔纳·希尔 Jonah Hill 配音）、鱼脚司（克里斯托夫·梅兹-普莱瑟 Christopher Mintz-Plasse 配音）及双胞胎拉芙纳特（克里斯汀·韦格 Kristen Wiig 配音）、特夫纳特（托德·约瑟夫·米勒 T.J. Miller 配音）都出手相助，加上小嗝嗝、身为部族的首领的父亲斯多戈（杰拉德·巴特勒 Gerard Butler 配音）及母亲连手合作。在这期间，小嗝嗝一直追寻的答案就在不知不觉以意想不到的方式出现了……', '杰伊·巴鲁切尔', '迪恩·德布洛斯', 8.1, 281944, 'tt1646971', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2192713707.jpg', 0.2, 1.4, 20.4, 50, 28, '0.000189,-0.255521,-0.355797,0.539598,-0.111157,-0.371000,0.318710,-0.003637,-0.475552,-0.354170,-0.163866,0.780458,-0.100956,0.066232,0.409247,-0.069308,-0.262471,-0.438234,0.133378,0.265992,0.235739,-0.431406,-0.424262,-0.536974,-0.187643,-0.584187,0.397987,-0.024651,-0.184557,0.417930,0.178996,0.493875,-0.252110,0.229727,0.225411,0.178042,0.258658,-0.175253,-0.262721,0.059300,-0.110192,0.064124,-0.162695,0.236980,0.275596,0.295409,0.329059,-0.436208,0.146480,-0.306550,0.192275,-0.558101,0.118652,-0.020123,0.187320,-0.071615,0.484467,0.141221,0.151670,0.088367,-0.066161,-0.169165,-0.766510,0.196741,-0.168962,0.163750,-0.285995,0.351242,-0.285306,-0.037663,0.111015,-0.231696,0.182096,0.237095,0.059217,0.186841,-0.256463,0.109540,-0.362373,-0.130331,0.684488,-0.016227,-0.387788,0.080698,0.043178,-0.738688,-0.007343,-0.233019,-0.272815,0.025890,0.257880,0.233563,0.088963,0.342510,-0.591484,-0.051085,-0.359785,-0.238191,-0.107855,-0.310708,-0.062343,-0.805222,-0.056927,-0.300525,-0.060419,0.041631,0.122809,-0.235743,0.506697,-0.744871,-0.001460,0.333511,0.106277,-0.399240,0.412858,-0.030552,0.315525,-0.256238,-0.068025,0.589230,0.161600,-0.259743,0.175028,0.030517,0.117027,0.220864,-0.402713,0.581829', '1420088', '26259202', '11541282', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4824515', '诸神之怒', '动作', '结束了与北海巨妖的战争，英雄珀修斯（萨姆·沃辛顿 Sam Worthington 饰）与儿子赫利俄斯（约翰·贝尔 John Bell 饰）在一座小村庄过着平静的生活。但是奥林匹亚的战火从未停歇，以宙斯（连姆•尼森 Liam Neeson 饰）为首的众神与泰坦巨人进行着旷日持久的惨烈战争，甚至连被宙斯囚禁良久的三神（天神宙斯、海神波塞冬、冥王哈迪斯）之父——克洛诺斯也即将复活。战争的天平渐渐向泰坦巨人一方倾斜，在冥王哈迪斯（拉尔夫·费因斯 Ralph Fiennes 饰）的策划下，宙斯误入冥界，神力尽失，遭到囚禁。为了驱逐黑暗，将光明带回大地，珀修斯重披铠甲，与一众英雄前往冥界营救宙斯，诸神的战火迎来了最关键的时刻……本片为2010年3D电影《诸神之战》的续集。©豆瓣', '萨姆·沃辛顿', '乔纳森·里贝斯曼', 6.1, 57179, 'tt1646987', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1493840861.jpg', 3, 18.2, 56.1, 17.6, 5.2, '-0.274455,0.351254,-0.781938,0.593843,0.487587,-0.240075,0.835951,0.058602,-0.098830,-0.414361,0.585736,0.775401,-0.177748,-0.263043,0.524822,-0.079531,-0.538490,-0.550280,-0.210595,0.303716,-0.242304,-0.083573,-0.452515,-0.009060,-0.087437,-0.741173,0.897007,0.215767,0.115538,-0.041595,0.121253,0.432089,-0.267205,0.215421,-0.153047,-0.085163,-0.398939,-0.195174,-0.439028,0.442908,-0.459378,-0.180124,-0.360303,0.335452,-0.311700,0.145080,0.545227,-1.112191,0.377914,-0.461190,0.319419,-0.514005,-0.147898,0.309535,0.547447,-0.161396,-0.133016,0.452388,0.250003,-0.125331,0.174855,-0.327399,-0.720459,-0.076758,-0.418491,0.229501,-0.346709,0.841472,0.215746,0.323101,0.336992,-0.129615,0.302814,0.385949,0.224915,0.339357,-0.248970,-0.096425,-0.284914,0.053386,0.552760,-0.140074,-0.260347,-0.048689,0.101537,-0.573533,-0.434670,-0.321648,-0.649913,-0.172112,0.590939,0.128665,0.425634,0.975019,-1.036879,-0.357570,-0.411688,-0.470889,0.033710,-0.052531,-0.014142,-0.647085,-0.251001,-0.324879,-0.093898,-0.020811,0.103032,0.089880,0.385342,-0.731611,0.642537,0.405525,0.276328,-0.255420,0.488235,-0.031555,0.371695,-0.109001,-0.086173,0.513768,0.135715,0.474993,0.354475,-0.025097,-0.032913,0.074710,-0.163943,0.383788', '25808075', '1298586', '26759819', '25890017');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4824982', '杨门女将之军令如山', '动作', '时为北宋仁宗年间，君不君，臣不臣，大宋江山内忧外患。危难之际，杨继业率领的杨家将与异族抗战，却相继命丧沙场。及至天门关陷落，杨家虎将杨宗保（任贤齐 饰）战死，北宋江山岌岌可危。在这关键时刻，天子擢升杨家老太君佘赛花（郑佩佩 饰）为监军、宗保之子杨文广（肖明玉 饰）挂帅统领一万人马对抗西夏国十万大军。 此时杨门男儿多以战死，为报国恩，身怀绝世武功的杨门女将在佘太君、穆桂英（张柏芝 饰）等人的率领下朝向关外行进。本该是如花美眷刺绣描兰的的女儿家，为了国家大义捐弃身血在所不惜，由此谱写了六方百年的杨门女将的不朽传奇……©豆瓣', '张柏芝', '陈勋奇', 3.6, 23109, 'tt2106514', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2173427564.jpg', 49, 30.7, 15.4, 2.9, 2, '-0.372516,0.140089,-0.533428,0.341001,0.411657,-0.000566,0.130115,0.380780,-0.529466,-0.279591,0.501894,0.464346,0.307880,-0.252098,0.153445,-0.325141,0.145972,-0.605315,-0.251168,-0.109822,0.167110,0.078909,-0.116669,-0.185267,-0.383516,-0.250894,0.716246,0.415252,0.159310,0.525692,0.251774,0.189773,0.044207,0.112324,-0.164571,0.198568,-0.318663,-0.273823,-0.324663,0.119858,-0.486391,-0.326659,-0.278326,-0.061152,-0.257187,0.039891,0.377406,-0.473476,0.344691,-0.320741,0.101994,0.031180,-0.058028,-0.036928,0.430950,0.066570,0.019399,0.476091,0.082134,-0.258951,-0.171793,-0.044606,-0.609494,-0.247762,0.254819,-0.167451,-0.575806,0.642347,-0.204950,-0.099692,0.251329,-0.227496,0.366829,0.685813,0.274772,0.111301,-0.117871,-0.187276,-0.596370,0.568123,0.396530,-0.150652,0.179528,-0.293682,0.421232,-0.323490,0.160764,-0.428309,-0.405276,0.002276,0.071015,-0.224527,0.654738,0.277960,-0.127460,-0.008933,-0.450834,0.247634,0.204999,0.063421,-0.040751,0.073557,-0.094590,-0.194504,-0.130578,0.312598,0.506655,0.216526,0.746128,-0.280613,-0.251793,-0.040336,0.213265,-0.707999,0.642325,0.117801,0.105470,0.046947,-0.116620,0.188251,0.159595,0.376441,0.073251,-0.179008,-0.512649,-0.094618,-0.301638,0.098952', '6101834', '1478066', '4723944', '6424814');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4825006', '喋血孤城', '剧情', '1943年，侵华日军为了挽救必然失败的命运，挥军进犯湘西北军事重镇常德。驻守当地的国军第74军57师临危受命，八千代号虎贲的将士在师长余程万（吕良伟 饰）带领下，准备与数倍于己的敌人决一死战。战云密布的前夜，连长冯宝华（袁文康 饰）推迟了与未婚妻婉清（安以轩 饰）的婚事以全力备战，同日军有国仇家恨的当地苗族青年黄二虎（谢孟伟 饰）踊跃参军，敌兵未至，常德军民斗志已燃！然而在日军的优势火力迫压下，德山与河伏先后失守，常德成为一座孤城。余程万下令全师与城共存亡，虎贲将士在毒气与炮火中与日军展开一寸寸土地的争夺。最终57师用覆亡的代价谱写下抗战史中不朽的一页。©豆瓣', '吕良伟', '沈东', 7.4, 12689, 'tt1773370', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p605521063.jpg', 2.8, 4.5, 30.6, 42.3, 19.8, '-0.133888,0.124958,-0.626081,0.650607,0.497676,0.118365,0.208509,0.093181,-0.323862,0.086651,0.316687,0.494386,0.395423,-0.335021,0.159332,-0.558622,0.019870,-0.937103,-0.224465,-0.145329,-0.055615,-0.431373,-0.294015,0.011016,0.111305,-0.147521,0.674434,0.453001,-0.007139,0.665381,0.088864,0.204866,0.088906,0.423128,0.234604,0.165458,-0.193475,-0.617686,-0.609066,0.185764,-0.394297,-0.429107,-0.252509,-0.076904,-0.129287,0.315055,0.906101,-0.538914,0.213024,-0.087634,-0.161003,-0.149576,0.051846,0.269311,0.378003,0.119326,0.053879,0.377655,-0.196924,0.103838,-0.199349,-0.082495,-0.576879,-0.212661,0.353331,-0.052541,-0.579644,0.584504,-0.164138,0.384871,0.175268,-0.332817,0.029747,0.886890,0.150789,0.009703,-0.473150,-0.256261,-0.419220,0.291125,0.673224,0.017706,0.027315,-0.535753,0.196630,-0.226552,-0.031987,-0.350697,-0.295013,-0.002325,0.034026,-0.189911,0.580462,0.126543,-0.896806,-0.077738,-0.448703,-0.040289,-0.036820,0.208609,-0.129241,-0.405036,0.014350,-0.334214,-0.139834,0.353209,0.370682,0.347095,0.653342,-0.617309,-0.218681,0.039983,0.621778,-0.452880,0.294956,0.281373,0.215723,0.159566,0.096487,0.150768,-0.179251,0.718838,0.254343,0.116991,-0.507021,-0.146241,-0.218469,0.170750', '3078390', '1424551', '1307201', '3074408');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4826330', '炮友', '喜剧', '杰米（米拉•库妮丝 Mila Kunis 饰）是一位在纽约供职的猎头，为了将身在洛杉矶的迪伦（贾斯汀•汀布莱克 Justin Timberlake 饰）挖角到纽约，她提供的不仅是丰厚薪资，还给了这位初来乍到者真挚的友情，带着他领略了纽约的美好夜晚。“挖角”成功了，两人成  了最好的朋友，也难免受到对方吸引。此时恰逢迪伦与前任分手，而曾经受过情伤的杰米也不想进入一段正式关系，于是两人商定只谈性不谈爱。在迪伦的鼓励下，杰米在公园搭讪到令她动心的人——医生帕克（布赖恩•加连保格 Bryan Greenberg 饰），可是很快发现对方只是想把她搞上床，令她再度受伤。为了帮杰米走出阴霾，迪伦带杰米回到自己家乡，两人隐隐意识到对彼此的感情，却在这当口发生一场误会。唯有失去才会懂得珍惜，迪伦在杰米心灰意冷独自回纽约后，明白自己已经深深爱上她，而她却仿佛在他生活中消失了，迪伦不知该怎样迈出挽回杰米的那一步……在第38届美国人民选择奖上，本片被提名最佳喜剧电影和最佳喜剧女演员（米拉•库妮丝）', '贾斯汀·汀布莱克', '威尔·古勒', 6.6, 90720, 'tt1632708', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1297811248.jpg', 1, 8.5, 56.5, 27.8, 6.3, '0.413652,0.228676,-0.873547,0.333566,-0.128867,-0.443183,0.814761,0.049445,-0.510198,-0.022999,0.239439,0.871856,-0.235832,0.252296,0.415400,0.176230,-0.338606,-0.636734,0.264129,-0.366615,-0.094653,-0.437326,-0.315014,0.020936,-0.130864,-0.442881,0.442705,0.041644,-0.093313,0.389094,0.339560,0.244660,0.094561,0.641771,0.010431,0.247010,0.174954,0.072928,-0.399914,0.342525,0.235048,-0.350403,-0.353217,0.111053,0.105803,0.266530,0.540168,-0.074548,-0.068602,0.285212,0.251441,-0.392152,0.074464,0.162380,0.112379,-0.166927,0.098578,0.079735,-0.224605,0.073578,0.132541,0.000115,-0.633924,0.159093,0.013599,0.320592,-0.721087,0.413005,-0.124381,-0.142889,0.190266,-0.476219,0.026854,0.323695,0.236943,0.262673,-0.130869,0.024310,-0.402203,0.113208,0.843865,-0.018750,-0.228929,0.283131,-0.202282,-0.451926,0.040198,-0.037937,-0.308938,-0.104843,0.549284,0.161908,-0.102464,0.113411,-0.399449,-0.288613,-0.209188,-0.324674,-0.175612,-0.687550,0.158575,-0.558032,-0.216582,-0.447955,-0.183979,0.009346,0.071908,-0.474162,0.277197,-0.940379,0.516753,0.659318,0.270252,-0.377806,0.471744,0.226176,0.226762,-0.186403,-0.077606,0.466294,-0.083088,0.266207,0.291936,0.191373,0.099244,0.013135,-0.388048,0.447782', '1308755', '1301022', '2990737', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4826419', '金福南杀人事件始末', '剧情', '在首尔金融业独自打拼的单身女子郑海媛（池成媛 饰）自然承受来自方方面面的巨大压力，她的情绪越来越紧张，最终不得不被迫休假。利用假期，海媛回到阔别已久的家乡无岛。这里风景秀美，民风粗犷甚至有些野蛮，男尊女卑的现象依然十分严重。海媛重逢了童年的玩伴金福南（徐英姬 饰），这是一个温和开朗、任劳任怨的女人，但是她的丈夫和家人都视其为猪狗，任意欺负和凌辱。福南希望女儿小燕拥有更好的人生，只是在这个蛮荒所在，人的尊严被肆意践踏。巨大的压力下，逆来顺受的福南化身为悲剧的复仇女王……本片为韩国名导金基德的导演助理张哲秀的长片处女作。©豆瓣', '徐英姬', '张哲洙', 8.6, 226676, 'tt1646959', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p596526266.jpg', 0.2, 0.7, 10.4, 46.5, 42.1, '-0.127365,-0.140639,-0.571161,0.592262,-0.043375,-0.171114,0.746786,0.371738,-0.429102,-0.188325,0.267906,0.763171,0.043090,0.381934,0.273117,-0.074127,-0.155914,-0.335994,-0.226990,0.208840,0.047625,-0.102284,-0.321237,-0.138079,-0.146669,-0.300091,0.749681,0.072753,-0.222063,0.421406,0.171747,0.213607,-0.061707,0.454840,-0.385446,-0.020189,-0.118934,0.165426,-0.306598,0.066818,-0.082881,-0.140079,0.054665,0.429511,-0.222120,0.204503,0.603798,-0.320609,-0.415600,-0.209170,0.593497,-0.250969,-0.246397,0.263528,0.021831,-0.123571,0.378863,0.025399,-0.211443,0.052017,0.114948,-0.191732,-0.619677,-0.036164,0.241954,0.088774,-0.483989,0.645828,0.224890,-0.202501,0.111269,-0.275130,0.043446,0.169675,0.120434,0.550650,-0.422924,0.392999,-0.201862,0.230089,0.759874,0.108403,-0.426893,0.230356,-0.525990,-0.370833,0.196856,-0.590235,-0.797180,-0.109679,-0.165628,0.032862,-0.096316,0.272007,-0.635600,0.151341,-0.090887,-0.040763,-0.075727,-0.601578,-0.195798,-0.399264,-0.257354,-0.435101,-0.161099,0.094024,0.058596,-0.336207,0.843668,-0.716731,0.293920,0.569802,0.351512,-0.652712,0.423404,0.204819,0.067376,-0.030133,-0.304714,0.622583,-0.021840,0.190944,-0.147844,0.112664,-0.286227,-0.000455,-0.136439,0.612764', '26348103', '4817024', '3445516', '4847665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4830236', '冰冷热带鱼', '剧情', '富士见市某经营热带鱼的商店，居住着社本一家三口。户主信介（吹越满 饰）在妻子去世后不久便娶了美丽的妙子，此举令女儿美津子大为不满，因此家中的气氛总是压抑凝重，妙子更是小心翼翼，生怕因自己惹出事端。某晚，美津子因在行窃被超市所扣留，社本夫妇匆忙前往，多亏热情的陌生男子村田幸雄出面方得以脱身。村田也是一家热带鱼商店的老板，他诚恳地邀请社见一家到他的店中做客，并愿意聘用美津子为职员。社本夫妇虽有些无所适从，却不自觉地被村田牵着鼻子走。不久后，村田邀请信介为合作人，结果竟在信介的面前杀死了一个质疑自己的男人。一向唯唯诺诺的信介，被迫成为了疯狂的村田毁尸灭迹的帮凶……本片根据1993年震惊日本的琦玉爱犬家连续杀人事件改编。©豆瓣', '吹越满', '园子温', 7.7, 43773, 'tt1632547', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p931311610.jpg', 1.1, 3.6, 27.5, 45.8, 22, '0.114943,0.113769,-0.587296,0.212941,-0.017173,-0.446355,0.461487,0.342806,-0.581614,-0.389406,0.389053,0.689850,-0.119134,0.331641,0.338192,0.050687,0.034998,-0.251713,-0.189063,-0.075617,0.123473,-0.196088,-0.008173,-0.447848,-0.164192,-0.124819,0.354059,0.259134,-0.093933,0.645807,0.244316,0.535767,-0.272528,0.525793,0.093008,0.264930,0.177739,0.154460,-0.153271,0.052579,-0.322792,-0.497029,-0.147370,0.094793,0.213626,0.538962,0.630485,-0.049266,-0.519170,-0.154145,0.396427,-0.061825,-0.225586,0.285378,0.413092,-0.058834,0.116075,0.172863,-0.598530,-0.013172,0.080119,0.124141,-0.499621,0.114420,0.241638,0.001883,-0.433983,0.383944,-0.031696,-0.119872,0.061394,-0.202289,0.116341,0.135457,0.264989,0.273925,-0.120275,0.343529,-0.258743,0.082169,0.470043,-0.011270,0.117417,0.141060,-0.324838,-0.313214,0.202790,-0.279672,-0.523412,-0.081192,0.210285,0.172706,0.007863,-0.004985,-0.296502,-0.480053,-0.290149,0.011364,0.238003,-0.288667,-0.036637,-0.613105,0.212019,-0.195090,-0.150844,0.053149,0.049292,-0.059870,0.382570,-0.488955,0.107953,0.480396,0.324159,-0.278511,0.345928,-0.024755,-0.025639,-0.104356,-0.351870,0.006131,0.304272,0.225821,0.238198,0.280686,-0.172532,-0.114172,-0.135915,0.112730', '1465415', '5503303', '3326747', '1292849');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4830478', '海扁王2', '喜剧', '自“大老霸”牺牲后，“超杀女”明蒂（科洛·莫瑞兹 Chloe Moretz 饰）不忘匡扶正义的使命，依然穿梭城市的每一个角落惩治邪恶。而“海扁王”戴夫·莱泽斯基（亚伦·约翰逊 Aaron Johnson 饰）为了能和超杀女组成新的搭档，心甘情愿接受对方的各种严苛训练。另一方面，收养了明蒂的马库斯（Morris Chestnut 饰）希望她能过回正常校园女孩的生活，享受恋爱和友情点缀的人生。眼见明蒂放弃了正义使者的身份，戴夫只得转向由洗心革面的黑帮打手“上校”（金·凯瑞 Jim Carrey 饰）组成的正义永存联盟，和一群原本生活中的废柴为了正义而奋斗。与此同时，失去父母的克里斯（克里斯托夫·梅兹-普莱瑟 Christopher Mintz-Plasse 饰）狂性大发，更名“臭屁王（MotherFu*ker）”，他网罗了一群亡命之徒，发誓摧毁海扁王及其伙伴们的正义事业。正邪大乱斗在这座城市里拉开帷幕……', '亚伦·泰勒-约翰逊', '杰夫·瓦德洛', 6.4, 68437, 'tt1650554', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2009848638.jpg', 2.5, 14.4, 52.8, 22.9, 7.4, '0.070590,0.186758,-0.319331,0.504073,-0.080675,-0.470454,0.627248,0.159730,-0.063180,-0.317810,0.067977,0.469133,0.255468,0.073253,0.403773,-0.210857,-0.350554,-0.580585,-0.230119,0.070574,-0.123415,-0.324395,-0.310912,-0.409653,-0.286844,-0.221096,0.668593,-0.094330,-0.101785,0.305778,0.635508,0.412436,0.015084,-0.053598,-0.041426,0.052721,0.093312,0.033939,-0.521443,-0.078499,-0.344140,0.063889,-0.179518,-0.050533,0.120955,0.152490,0.605920,-0.540090,0.224109,-0.571533,0.248535,-0.349034,-0.196613,0.189511,-0.012387,-0.119006,0.271442,0.022965,0.063556,-0.142609,0.209065,-0.259095,-0.867325,-0.278746,0.160995,0.124005,-0.285768,0.422736,0.126649,-0.009220,0.213921,-0.028836,0.043951,0.260968,0.312269,0.209554,0.089828,0.197063,-0.361325,0.230993,0.722630,0.098865,-0.404732,-0.145787,-0.320785,-0.143819,-0.012375,-0.287408,-0.570014,-0.360190,0.323173,-0.037006,0.270248,0.313311,-0.690006,-0.217526,-0.262548,-0.050201,0.104446,-0.465494,-0.064755,-0.545633,0.049643,-0.258258,-0.097986,0.180977,-0.107708,-0.154394,0.703885,-1.024812,0.120763,0.216740,0.252536,-0.586268,0.563521,0.260577,0.322381,-0.343025,-0.113439,0.493387,0.257610,0.320407,0.045902,0.199419,-0.195811,-0.023695,-0.19355