INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4830483', '喋血战士', '动作', '电影根据勇士漫画改编，讲述由范·迪塞尔扮演的士兵雷·加里森在战斗中意外阵亡，被RST公司利用尖端纳米技术起死回生，变身即时自愈、媲美超级电脑的超级英雄——喋血战士。苏醒的他执着于脑海中残存的记忆碎片，踏上为爱妻的复仇之路，却发现自己竟无法分清真实与虚幻...', '范·迪塞尔', '戴夫·威尔逊', 5.5, 27944, 'tt1634106', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2614385032.jpg', 4.7, 29.7, 53.3, 10.1, 2.1, '0.069626,0.184864,-0.387972,0.532098,0.383081,-0.134147,0.760846,-0.255798,-0.273917,-0.569933,0.292914,0.496351,0.019097,-0.100885,0.258198,-0.662628,-0.062870,-0.620369,-0.232542,0.415978,-0.113089,-0.396218,-0.851798,0.062444,-0.074487,-0.744298,1.227566,0.342356,-0.470698,0.319890,-0.172768,0.209513,-0.481851,0.122284,-0.046353,0.054962,-0.216283,0.030498,-0.285610,0.005590,-0.331045,-0.242137,0.210691,0.190266,-0.388503,0.291039,0.774233,-0.517418,0.076370,-0.115177,0.702557,-0.178691,-0.146412,-0.309293,-0.014751,0.537409,0.032742,-0.324700,0.299078,-0.154127,-0.121838,0.069787,-1.239355,-0.372941,0.307761,0.170344,-0.554400,-0.078911,-0.413748,0.195030,0.272177,-0.060915,0.103003,-0.259975,0.586366,0.479686,-0.049025,0.034388,-0.216011,0.337994,0.392141,-0.024808,-0.710493,0.276033,-0.002211,-0.578817,-0.354288,-0.507844,-0.097241,0.149732,0.123428,0.311058,0.225583,0.505984,-0.416474,-0.041697,-0.331031,-0.161549,-0.207899,-0.111981,-0.172651,-0.587103,-0.153380,0.388577,0.079541,0.131193,0.089690,-0.520467,0.741050,-0.804084,0.231285,0.299417,0.088644,-0.372678,0.427161,-0.217295,-0.031181,-0.440985,0.160791,0.640625,0.355091,0.071081,0.004199,0.076002,-0.354788,0.289530,-0.735344,0.613753', '26759820', '25880986', '26759819', '10440076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4830911', '街角洋果子店', '剧情', '在繁华的东京一隅，坐落着名为Coin de Rue的洋果子店（西点店），从主厨到下属员工都尽心尽力做出美味的点心奉献给慕名前来的食客。这一日，单纯直率的女孩臼场夏目（蒼井優 饰）从遥远的鹿儿岛来到东京，寻找立志成为著名糕点师傅的男友海千寻（尾上寛之 饰）。然而阿海并不在其信上所说的街角洋果子店，失望的夏目请求留在店里帮工，但她糟糕的蛋糕制作技术却遭到同事们十分挑剔的指摘。不过夏目毫不气馁，以执着的韧劲开始了她在东京修业之旅。在此期间，夏目和性格各异的同事们从争吵到包容，也结识了传说中的名西点师十村辽太郎（江口洋介 饰），而她不懈的努力开始得到了回报……©豆瓣', '江口洋介', '深川荣洋', 6.9, 28006, 'tt1653950', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p911909907.jpg', 0.7, 6.5, 48.9, 34.3, 9.7, '0.300215,0.154045,-0.668097,0.447162,-0.189665,-0.169743,0.583209,0.582888,-0.375867,-0.047574,0.286094,0.666911,0.050939,0.155854,0.398700,0.033124,-0.066525,-0.377114,0.025890,-0.169297,0.009222,-0.355656,0.049551,-0.400528,-0.263926,-0.178225,0.444661,0.174833,0.009993,0.488398,0.113391,0.119220,-0.023391,0.519691,-0.331571,-0.002791,0.194032,0.114895,-0.251210,0.088221,-0.170845,-0.422971,-0.330847,0.169900,0.308265,0.338804,0.701929,-0.235413,-0.457004,0.283708,0.293760,-0.119880,-0.024632,0.185060,0.191310,0.282331,-0.015690,-0.073841,-0.225186,0.193794,-0.029172,-0.163888,-0.484031,-0.160194,0.218035,0.240195,-0.625407,0.627605,0.051415,-0.163028,0.194651,-0.664374,0.053761,0.039979,0.042649,0.215328,-0.028195,0.302790,-0.430801,0.305262,0.646762,0.139292,0.015106,0.255165,-0.208736,-0.507157,0.231965,-0.255124,-0.490267,-0.069173,0.051598,0.035263,0.053305,0.010252,-0.869655,-0.015333,0.149481,-0.374869,0.443734,-0.088976,-0.313612,-0.809089,0.187074,-0.436655,-0.326793,-0.069303,0.219173,-0.281770,1.065490,-1.055288,0.069358,0.620337,0.153445,-0.337356,0.766043,-0.236618,-0.118189,-0.077246,-0.564282,0.295375,0.090401,0.366377,-0.019965,0.518957,-0.002620,-0.237517,-0.497950,0.217405', '3811356', '25922902', '1418179', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4832288', '奇迹', '剧情', '一段破败的婚姻，让两个尚未成年的好兄弟天各一边。哥哥航一（前田航基 饰）随母亲大迫希美（大塚寧々 饰）回到位于鹿儿岛的外婆家，弟弟龙之介（前田旺志郎 饰）则和追寻音乐梦想的“废柴”父亲木南健次（小田切让 饰）在福冈居住。兄弟俩有了各自的朋友圈，父母也似乎渐渐安定下来。可 是，他们无论如何还是希望重新聚在一起。鹿儿岛开往福冈的新干线“燕”和福冈开往鹿儿岛的“樱”号途中会有一次短暂的交汇，传说这时许下心中愿望的话，奇迹就会降临。晴朗的一天，两兄弟各自带着朋友朝着心中的奇迹之地出发……本片荣获第26届高崎电影节最佳新人男演员奖（前田兄弟）和最佳新人女演员奖（内田伽羅）。©豆瓣', '前田航基', '是枝裕和', 8.8, 66415, 'tt1650453', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1172845476.jpg', 0.1, 0.4, 7.8, 42.1, 49.7, '-0.171987,-0.132346,-0.607060,0.579532,0.522549,-0.364562,0.467377,0.203751,-0.536175,-0.121604,0.111709,0.922760,-0.210329,0.388230,0.544986,0.035093,-0.442383,-0.646202,-0.133636,-0.360009,-0.316884,-0.503033,0.024917,0.016408,-0.180238,-0.004574,0.762035,0.266552,0.296481,0.627766,0.390991,0.155642,-0.323312,0.071843,-0.229199,0.168453,0.097328,0.262255,-0.496534,0.376355,0.037554,-0.048490,-0.267701,0.104635,0.321456,0.099354,0.876773,-0.190981,-0.108518,0.101555,-0.049923,-0.201670,-0.258393,0.011417,0.147177,-0.157511,0.373647,0.310378,-0.063401,-0.016651,-0.139967,-0.113133,-0.345297,0.023945,0.163291,-0.067511,-0.531632,0.496068,0.043389,0.007510,0.250577,-0.269983,0.407482,0.455892,0.170916,0.383997,-0.372479,0.163887,-0.026911,0.235106,0.698471,0.154143,-0.012822,0.222767,-0.013881,-0.383801,-0.209834,-0.024507,-0.368080,-0.026277,0.230044,0.236405,0.211830,0.054350,-0.517051,-0.125146,-0.098778,-0.210366,0.393209,-0.342579,0.150789,-0.430340,0.345342,-0.283856,-0.240798,0.441187,0.099578,-0.082993,1.028507,-0.858857,0.228185,0.384810,0.258443,-0.223782,0.578108,0.049804,0.105457,-0.425313,0.151301,-0.040206,-0.288183,0.332448,0.147740,0.241449,-0.442762,-0.133919,-0.560975,0.195936', '3811356', '25922902', '1292219', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4832825', '海啸奇迹', '剧情', '本片取材于2004年印度洋海啸时发生的一桩真实事件。玛莉雅（娜奥米·沃茨 Naomi Watts 饰）和亨利（伊万·麦克格雷格 Ewan McGregor 饰）带着三个儿子，一同前往泰国共渡圣诞佳节，不料就在圣诞节隔天，当这幸福的一家人在泳池旁享受着悠闲时光时，一股猛兽般的万呎滔天巨浪竟迎面袭来。被眼前景象震慑住的玛莉雅，一时反应不及，不幸惨遭巨浪袭卷；而尽管亨利及时抓住两个儿子准备逃亡， 一切仍旧太迟，凶猛的大水最后仍冲散了他们。一度被巨浪击昏的玛莉雅，醒来后发现自己正漂浮在海面，而原本围绕在身旁的所有景物，都已被淹没于水面下，她深信家人们皆已罹难的同时，竟发现自己的大儿子卢卡斯，竟然就漂浮在距离她仅有几公尺远的海面上。玛丽雅顿时犹如被打了一剂强心针，她决定想尽办法，要带着大儿子卢卡斯一起活着离开......©豆瓣', '娜奥米·沃茨', 'J·A·巴亚纳', 7.8, 80364, 'tt1649419', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1839461050.jpg', 0.3, 2, 26.3, 50.7, 20.6, '0.197286,0.129151,-1.049185,0.375015,0.364282,-0.194198,0.784539,0.220212,-0.228120,-0.344460,0.207765,0.560106,-0.454746,0.319868,0.344366,0.020431,-0.124867,-0.753603,-0.199239,0.039537,-0.297989,-0.085799,-0.227288,-0.108309,-0.003662,-0.241077,0.080409,0.026499,0.262998,0.633180,0.196634,0.079340,-0.193390,0.627368,-0.248921,0.126487,-0.059982,0.039222,-0.106271,0.324413,-0.073692,-0.376033,-0.172997,0.094486,-0.198004,0.230933,0.878160,-0.271211,0.126256,0.126472,0.143816,-0.505014,0.269153,0.363758,0.308399,-0.109350,-0.026449,-0.183745,-0.365270,-0.128165,0.446257,-0.160295,-0.168124,0.204722,-0.263056,-0.006319,-0.373521,0.231524,0.158800,-0.111949,0.212886,-0.048593,-0.058069,0.126671,-0.154218,0.507432,-0.227759,0.079528,-0.465103,-0.007771,0.795468,0.008087,-0.309100,0.168353,-0.231099,-0.013343,-0.021041,-0.043710,-0.165796,-0.281909,0.620534,0.309629,-0.187685,0.487694,-0.469677,0.048049,-0.600202,-0.207610,-0.309154,-0.251853,-0.388816,-0.499446,-0.028688,-0.130682,-0.177134,0.432212,-0.056071,0.084190,0.318048,-0.150863,0.486611,0.556130,-0.021489,0.196978,0.433257,0.036342,-0.029215,0.254645,0.061293,0.169400,0.005367,0.412643,0.461375,0.224698,-0.310445,0.208206,-0.366746,0.555378', '3011051', '25786077', '4919019', 