INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4836871', '天空上三公尺', '剧情', '她, 一个接受良好教育的富家乖乖女。他, 一个热衷于非法摩托车赛的狂野青年。两个属于不同世界的人相遇相识, 会擦出怎样的火花？你是否也在期待天空之上三公尺的幸福？', '玛利亚·瓦沃德', '费尔南多·冈萨雷斯·莫利纳', 7.2, 8380, 'tt1648216', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p552348436.jpg', 2.5, 8.6, 36.6, 33, 19.3, '0.117315,0.434056,-0.889643,0.683043,-0.206813,-0.271457,0.896430,-0.054305,-0.021075,0.103302,0.460929,0.765282,-0.128140,0.316596,0.278623,0.092144,0.168720,-0.743424,-0.254251,-0.128430,-0.537395,-0.359102,-0.395454,-0.256412,0.128033,-0.066556,0.353603,0.249797,-0.256507,0.475244,0.399513,0.071518,-0.226963,0.176050,-0.726487,-0.655290,-0.221384,0.429565,-0.236278,-0.179386,-0.344315,0.237850,0.136166,-0.022663,-0.281302,0.049359,0.915341,-0.248635,-0.067443,0.031607,0.489188,0.112086,-0.030539,-0.047962,0.250236,-0.137922,-0.074338,-0.356191,0.255713,-0.168217,-0.249576,-0.026220,-0.748876,-0.159284,-0.131576,0.485632,-0.636751,0.900334,0.184781,-0.531769,0.099211,0.157676,-0.242007,0.263946,0.337262,0.632954,-0.468975,0.244418,-0.285557,0.312742,0.884642,0.217502,-0.595240,0.233082,-0.555647,-0.358812,-0.087597,-0.335826,-0.750842,-0.111321,0.370985,-0.271126,-0.272756,0.128963,-0.609718,0.101662,-0.237702,0.144275,0.063942,-0.348636,-0.178834,-0.590591,0.053684,-0.462032,-0.678827,0.003042,0.070275,-0.374447,1.071561,-1.036918,0.296476,0.471340,0.169175,-0.526994,0.905770,0.506248,-0.098674,-0.454185,-0.250740,0.319313,0.274711,-0.276509,-0.245648,0.685985,-0.116809,0.524141,-0.110126,0.479256', '1292219', '3445516', '26283288', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4840388', '新喜剧之王', '剧情', '大型影视基地，胸怀明星梦的女子如梦（鄂靖文 饰）已经在影视圈摸爬滚打了十多年，却依旧还是籍籍无名的龙套演员。平日里，在片场饱受剧组和其他演员的欺凌嘲笑，回到家则被恨铁不成钢的老爹指责，甚至扬言断绝父女关系。然而如梦一律微笑面对，天大的委屈也藏在心中，死皮赖脸地抓住每一个希望渺茫的机会。在此期间，她结识了热衷于跑龙套的李洋，早已过气却自视甚高的童星马可（王宝强 饰），更彻彻底底看清了自己以及爱情的真相。她是过于平凡的小人物，是一个不该有梦的女孩，是一个直到宇宙灭亡也永远不会得到演戏机会的可悲龙套……©豆瓣', '王宝强', '周星驰', 5.7, 389090, 'tt9368628', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2555440969.jpg', 13, 25.3, 35.4, 16.8, 9.5, '0.045897,0.190392,-0.536192,0.451901,-0.147694,-0.211367,0.745500,0.081077,-0.599525,-0.080193,0.302465,0.695934,-0.240030,0.267917,-0.022108,-0.165620,-0.150256,-0.665571,-0.287872,-0.123666,-0.065002,-0.179020,-0.294344,-0.111396,-0.205227,-0.156826,0.973002,0.168489,-0.273313,0.105041,0.501994,0.150502,-0.015396,0.492227,-0.342669,0.139669,0.058185,0.186148,-0.264746,-0.061179,-0.261375,-0.161182,-0.182407,0.199685,-0.148390,0.284986,0.446250,-0.063834,-0.206827,0.134696,0.488643,-0.336635,-0.246619,0.014729,0.007756,-0.283789,0.320495,0.133864,0.078605,0.005538,0.091181,-0.061176,-0.997876,0.020885,0.359547,0.307625,-0.532159,0.570228,0.102604,-0.043520,0.076151,-0.148897,0.142476,-0.113918,0.265569,0.329527,-0.196945,0.315001,-0.552227,0.546727,0.585897,0.272556,-0.325521,0.494621,-0.227996,-0.335831,-0.233119,-0.482079,-0.675858,0.059208,0.093706,-0.220501,-0.355588,0.300929,-0.283112,0.031105,-0.091244,0.051163,0.202937,-0.676829,-0.102234,-0.308488,-0.047108,-0.322296,-0.372813,0.135873,0.220712,-0.303565,0.717142,-0.812875,0.194087,0.626269,0.116109,-0.464592,0.804819,0.210285,-0.088227,-0.145681,0.090054,0.418789,0.022198,0.177112,-0.094318,0.139200,-0.244812,-0.158271,-0.195166,0.345308', '30279170', '1793491', '26635323', '6101834');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4842877', '蓝色骨头', '剧情', '网络写手钟华（尹昉 饰）是一个边缘人物，他是地下摇滚歌手，也是专业黑客。他帮音乐公司的老板徐天（果静林 饰）做些见不得人的勾当。一次意外他勾搭上了一个没名气的小歌手萌萌（黄幻 饰），而不幸的是，她居然是老板的情人……正当钟华迷茫之时，他接到了多年没有音讯的父亲钟振清（赵 有亮 饰）发来的邮包，其中竟然藏着一段在文革岁月中的凄婉故事，故事的主人公是个叫施堰萍（倪虹洁 饰）的女文青，她有着一段与众不同的岁月，与同学陈东（黄轩 饰）写了一首改变她一生的歌曲，而她竟然与钟华有着千丝万缕的关系。钟华看着上一辈人的故事，逐渐了解了他们，他与父亲、母亲最终在一首歌曲中破镜重圆，而他也走上了属于自己的路。©豆瓣', '赵有亮', '崔健', 6.9, 27006, 'tt3342430', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2202807266.jpg', 2.3, 11.4, 40.4, 32.5, 13.5, '0.341198,0.071793,-0.560781,1.122547,-0.181677,-0.197633,0.924021,0.033994,-0.770339,-0.210891,0.135512,0.693986,-0.162901,0.358291,-0.023107,0.105870,-0.163751,-0.854164,0.126593,-0.175371,-0.235621,-0.552130,-0.459786,-0.123990,-0.168077,-0.137130,0.648900,0.067892,-0.201503,0.385756,0.469630,0.027689,-0.217623,0.534247,-0.143115,0.220289,0.149127,0.258151,0.054389,-0.126169,0.105647,-0.574996,-0.223627,0.094478,-0.246702,0.535667,0.561250,-0.120801,-0.058959,0.183260,0.412154,-0.222645,-0.136826,-0.147839,0.221771,-0.063459,0.473102,0.275116,-0.191786,-0.291928,0.038300,0.009111,-0.678745,-0.119471,0.082137,0.374801,-0.639398,0.553861,-0.216576,-0.025309,0.071938,-0.531136,0.355369,-0.026095,0.470910,0.399374,0.038497,-0.021416,-0.356556,0.550679,0.597930,0.193593,-0.171996,0.558053,-0.291515,-0.512389,-0.315853,-0.103988,-0.737626,0.118655,0.375807,-0.283441,-0.121944,-0.023240,-0.536077,0.039454,0.054609,-0.004876,-0.070483,-0.464303,-0.054460,-0.227634,-0.265987,-0.646676,-0.346573,-0.026913,0.124796,-0.392406,0.975792,-0.749842,0.067813,0.492316,-0.161797,-0.404858,0.971021,0.014695,-0.093490,-0.028792,0.123699,-0.067654,-0.295871,0.021251,0.170111,0.463684,0.058988,-0.126591,-0.319681,0.507906', '26283288', '1303542', '26677495', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4843637', '最爱', '剧情', '20世纪90年代，中国一个偏僻落后的山村。在利益驱动下村民不惜卖血赚钱，却也将世纪绝症艾滋感染上身，生命以秒计算。老柱柱（陶泽如 饰）的长子赵齐全（濮存晰 饰），天良丧尽，他作为“血头”成为村里最先富起来的人，为此牺牲村民乃至家人也不悔改。心怀愧疚的老柱柱将染病并受到歧视的村民集中到废弃的小学统一照顾，一同前往的还有他的次子赵得意（郭富城 饰）。无人垂怜的死亡孤岛，病者在生命最后一刻还在心中贪欲的驱使下钩心斗角，令人全然看不到半点希望。在此期间，得意和堂兄弟小海（蔡国庆 饰）的媳妇琴琴（章子怡 饰）惺惺相惜，到互生爱意。本就饱受歧视的二人，此刻更成为背叛了全世界的恶人生命一点点流逝，他们依旧全力奔跑，追逐渺小易逝的可悲幸福……©豆瓣', '章子怡', '顾长卫', 7.4, 171079, 'tt1664704', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1019045726.jpg', 0.7, 3.8, 34, 47.3, 14.2, '-0.012160,-0.045223,-0.725656,0.296583,-0.175979,-0.138658,0.781581,0.118999,-0.354607,0.095297,0.416283,0.488411,-0.039885,0.262567,-0.101145,-0.368013,-0.022319,-0.366738,-0.173733,0.075230,-0.185945,-0.320522,-0.131455,-0.329702,-0.368572,-0.284273,0.678203,0.462388,-0.093168,0.494075,0.156462,0.068074,-0.011946,0.525093,-0.190448,0.135197,-0.331708,-0.013196,-0.195837,-0.174930,-0.050264,-0.226311,-0.017236,0.148490,-0.188637,0.321721,0.782302,-0.182687,-0.144325,-0.110647,0.446496,-0.338585,0.019512,0.074418,0.131283,-0.282240,-0.026342,0.184182,-0.153850,0.196424,0.053895,0.149094,-0.839897,-0.080100,0.228966,0.074369,-0.618989,0.590807,0.108821,-0.190427,0.089866,-0.295573,0.215211,-0.016593,0.027782,0.491069,-0.416764,0.066017,-0.444205,0.363392,0.635567,-0.196443,-0.323221,0.036965,-0.392396,-0.373156,0.083409,-0.287284,-0.555769,-0.176467,0.232494,0.176234,0.018497,0.382642,-0.555799,0.095825,-0.018793,-0.076190,0.189680,-0.581332,-0.015728,-0.345899,-0.079353,-0.301805,-0.175906,0.278626,0.428953,-0.346815,0.776143,-0.515777,0.301258,0.361767,0.453108,-0.592349,0.514542,0.049819,0.148620,-0.011668,-0.391858,0.697477,0.103682,0.394690,0.036381,-0.032128,-0.317716,0.232277,-0.189969,0.412282', '21619567', '26667010', '26678784', '10746430');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4844731', '境·界', '动作', '从小异于常人的黑崎一护（福士苍汰 饰），在一次机缘巧合下遭遇女死神“朽木露琪亚”（杉咲花 饰）。 露琪亚是将灵魂从现实世界引领到尸魂界的收魂者之一，他们为保护人类 不被“虚” 侵害，一直在与这些怪物战斗。在与一只异常强大的“虚” 战斗时，露琪亚身负重伤，无奈只能将死神 的力量暂时转给黑崎一护，让其代为战斗。两人经过一段时间的磨合后并肩战斗，终于战胜了当年害死一护母亲的“虚”，但在这期间，露琪亚的兄长朽木白哉（石原贵雅 饰）强迫她不顾黑崎一护的生命安危收回法力。露琪亚为保护一护，拖延到与“虚”的战斗结束，并清除了一护的记忆……', '福士苍汰', '佐藤信介', 4.8, 11588, 'tt5979872', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2524786233.jpg', 14.3, 42, 35.6, 6.6, 1.5, '-0.008313,0.253208,-0.422967,0.127363,-0.282217,-0.458200,0.783010,0.088838,-0.428841,-0.525445,0.380944,0.731127,0.026226,0.101667,0.003410,-0.275373,0.024006,-0.641114,-0.354533,0.137718,-0.548302,-0.413359,-0.245377,0.056261,-0.406749,-0.809091,1.047764,0.089657,-0.285089,0.237642,-0.063830,0.499295,-0.296836,0.428363,-0.028620,-0.142756,-0.256957,0.152801,-0.335885,0.295217,-0.135238,-0.310194,-0.276143,0.357078,-0.006012,0.197427,0.867473,-0.570896,-0.112231,-0.169961,0.221697,-0.362985,-0.065220,0.160799,0.284713,-0.090023,-0.166305,0.196180,-0.159342,0.239397,0.047371,-0.056798,-0.968254,-0.195059,-0.111626,0.041389,-0.530742,0.552359,0.062148,0.027346,0.260804,-0.231175,0.079272,0.557995,0.171862,0.218594,-0.776392,-0.186137,-0.131625,-0.055175,0.691231,-0.195607,-0.231103,0.393319,-0.186162,-0.449550,-0.764634,-0.293666,-0.167099,-0.113962,0.165547,0.524344,-0.316670,0.439435,-0.615436,-0.440682,-0.073468,-0.071976,-0.248226,-0.491882,0.201537,-0.522063,-0.034197,-0.522185,-0.401625,-0.040791,0.370888,-0.323324,0.630609,-0.953068,0.216837,0.701791,0.286926,-0.248224,0.223336,-0.055257,0.214465,-0.170852,0.022295,0.456992,0.309187,0.491717,0.639408,0.363297,0.093796,0.295193,-0.661544,0.389321', '26759819', '26759820', '2051813', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4844903', '家庭作业', '爱情', '本片曾入选了2011年的圣丹斯电影节。乔治（弗莱迪·海默 Freddie Highmore 饰）是一个聪明的孩子，一直逃避学习的他总是在课堂上各种涂鸦，因此从未完成任何一门功课，将要面临无法毕业的困境。而校花莎莉（艾玛·罗伯茨 Emma Roberts 饰）在极受欢迎的外表下掩藏着忧伤的内心世界。莎莉和乔治发现彼此有着许多相似的地方而成为朋友，并且互相产生了好感。乔治在得知自己难以获得高中毕业证书后不顾一切地想要逃离高中生活，因为有一手绘画的绝活，所以想用此来约束自己，于是做了艺术家达斯汀（迈克尔·安格拉诺 Michael Angarano 饰）的学徒。达斯汀看到了乔治身上的潜质，乔治也似乎找到了人生的方向，但他长期以来的懒散作风却阻碍着他的进步......©豆瓣', '弗莱迪·海默', '加文·维森', 6.9, 29980, 'tt1645080', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1234422202.jpg', 0.9, 8.1, 48.6, 30.8, 11.6, '0.317878,-0.027426,-0.692882,0.882600,-0.221455,-0.267399,0.645234,0.027437,-0.507817,-0.393538,0.054051,0.798341,-0.247200,0.464194,0.168752,0.064507,-0.214781,-0.799399,0.092729,-0.217459,-0.304404,-0.531930,-0.393491,-0.287169,-0.240749,-0.435937,0.706032,0.119280,-0.112966,0.422639,0.298513,0.142221,0.283000,0.466772,-0.145425,-0.125784,0.036679,0.073104,-0.113766,0.050606,0.288551,-0.258815,-0.321272,0.191937,0.093702,0.346972,0.588870,-0.057039,-0.109603,0.116217,0.501171,-0.232852,0.073494,0.157011,0.279244,0.010494,0.065769,0.099353,0.108716,0.055960,0.142671,-0.223166,-0.738008,-0.035076,0.040889,0.193090,-0.581059,0.404526,-0.007079,-0.014673,-0.092857,-0.400682,-0.012338,0.206966,0.239275,0.154058,-0.286895,0.143871,-0.476492,0.082047,0.585999,-0.121271,-0.323460,0.335591,-0.460284,-0.521859,-0.141709,-0.331761,-0.548200,0.011736,0.269602,0.178608,-0.183707,0.104685,-0.484221,-0.018037,-0.149903,0.050466,-0.064861,-0.557509,0.092313,-0.715979,-0.098739,-0.586060,-0.542709,-0.193830,0.004076,-0.570103,0.860164,-1.012473,0.250055,0.600507,0.196297,-0.304056,0.765910,0.032851,0.083062,-0.065331,-0.255178,0.518652,-0.203034,0.045316,-0.054980,0.550254,0.172636,-0.233523,-0.173909,0.789365', '1870681', '1301172', '3230462', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4845414', '我知女人心', '喜剧', '百分百纯爷们的广告公司创意总监孙子钢（刘德华 饰）在公司里活得逍遥自在，本来马上就要升迁作执行创意总监的他忽然被传闻中的“广告杀手”李仪龙（巩俐 饰）抢了心仪已久的职位，这件事让他极其愤慨。一次意外触电，孙子钢突然能听到女人心里想什么。在片刻的荒乱之后，他开始利用这项特 异功能与叛逆的女儿沟通、讨女同事欢心，以及对付工作中的对手李仪龙。然而，能听到女人心思的他，居然开始慢慢的懂得女人的心思，并从内心学会尊重别人。而与李仪龙之间的关系，也从开始的对峙慢慢变成了惺惺相惜……本片翻拍自好莱坞的经典喜剧《偷听女人心》（What Women Want）。©豆瓣', '刘德华', '陈大明', 5.6, 74735, 'tt1667150', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p811766580.jpg', 5.5, 25.6, 55, 11.5, 2.6, '0.126242,0.087689,-0.707784,0.634614,-0.201502,-0.281215,0.476065,0.066935,-0.679897,-0.123518,-0.187306,0.564300,-0.410568,0.230604,0.311049,-0.037514,-0.225299,-0.823639,0.037641,0.125552,0.000103,-0.351868,-0.192383,-0.509262,-0.132972,-0.139117,0.607157,0.037266,-0.098278,0.080946,0.440530,0.143386,0.006328,0.541010,-0.054131,-0.144847,-0.019607,0.085214,-0.225595,0.087962,0.300958,-0.126538,-0.193468,0.181657,0.018387,0.395845,0.319423,-0.292096,-0.137258,-0.137988,0.392628,0.107445,-0.000061,-0.000981,-0.004054,0.027927,0.448151,0.295454,-0.069578,0.277377,0.148765,-0.168923,-0.523338,0.032062,-0.036318,-0.039529,-0.340868,0.099333,-0.176638,0.100778,0.112607,-0.119600,0.353611,0.095803,0.316481,0.518902,-0.378798,0.148067,-0.320291,0.235158,0.390207,0.117754,-0.149041,0.567715,0.264436,-0.579734,-0.085093,-0.206632,-0.047676,-0.159586,0.317320,0.239914,-0.076325,0.105504,-0.542063,0.087969,0.150124,0.325612,-0.069463,-0.538664,0.032515,-0.218717,-0.203167,-0.241056,-0.061712,0.124005,0.123444,-0.260727,0.546309,-0.902318,-0.264760,0.260723,0.262530,-0.500919,0.306000,-0.101801,-0.199927,-0.432566,-0.230355,-0.083952,-0.105308,0.092277,0.098476,0.345530,0.186201,-0.380495,0.015635,0.511764', '1301022', '30345227', '35030151', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4845723', '死亡录像4：启示录', '剧情', '原本为某消防队执行拍摄任务的女记者安吉拉（曼奴拉·沃拉斯科 Manuela Velasco 饰），却意外在巴塞罗那一幢公寓里遭遇了毕生无法忘怀的恐怖噩梦。最恐怖的经历过后，安吉拉被潜入公寓的特种部队成员救出。当她再度醒来时，发现自己置身在一个陌生所在，接受身份不明的医护人员的检查。另一方面，特种部队成员古兹曼（Paco Manzanedo 饰）和幸存的战友也遭到隔离，他们发现这是一艘漂泊大海中央与世隔绝的油轮，所有与外界的联系全部中断，军方和医护人员掌握着这里的一切。进行着秘密实验的政府人员其任务失败，可怕的丧尸病毒在密闭的空间内肆虐爆发。没有人能够逃离，包括安吉拉在内，所有生者都成为丧尸的狩猎对象……©豆瓣', '曼努埃拉·贝拉斯科', '豪梅·巴拉格罗', 5.7, 9519, 'tt1649443', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2212045225.jpg', 7.7, 26.1, 46.8, 12.6, 6.8, '0.266211,-0.133934,-0.768456,0.492685,-0.006940,0.220351,0.957851,-0.215541,-0.664812,-0.571103,0.348367,0.618454,0.019892,0.017957,0.218902,-0.282742,-0.416094,-0.694238,-0.517965,-0.060928,-0.550227,-0.398039,-0.314405,-0.327907,0.136527,-0.319896,0.934741,0.219012,-0.326051,0.190689,0.098219,0.451030,-0.517637,0.477771,-0.036743,-0.128851,0.335374,-0.190914,-0.224459,0.243649,-0.345032,-0.074999,0.027076,0.199361,0.035611,0.247780,0.778282,-0.379245,-0.221127,-0.197515,0.143514,-0.398160,-0.036072,0.127283,0.392058,0.142403,0.075023,0.088807,-0.162505,0.107126,0.064342,0.056481,-0.909239,-0.324507,0.220617,0.187128,-0.338064,0.354306,-0.182438,0.155553,0.052672,-0.121041,0.294967,0.364724,0.078527,0.416165,-0.080939,0.069989,-0.439580,0.064800,0.879539,-0.409377,-0.435323,0.000525,-0.367845,-0.563526,-0.135284,-0.191623,-0.472335,0.102859,0.171687,0.479730,-0.163062,0.379436,-0.644506,0.015816,-0.232513,-0.517557,-0.320635,-0.296218,-0.257045,-1.007492,-0.204538,0.068212,-0.248552,0.276136,-0.150699,-0.137571,0.509060,-0.865487,0.370756,0.387306,0.290658,-0.387722,0.581145,-0.167729,0.471985,-0.281500,-0.073756,0.368567,0.223947,0.832166,0.108230,0.292421,-0.241486,-0.203534,-0.596272,0.143908', '2369613', '1306809', '1307897', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4846693', '隔绝', '科幻', '纽约市一场灾难性的核爆炸后，乔什（米洛·文提米利亚 Milo Ventimiglia 饰）、米奇（迈克尔·比恩 Michael Biehn 饰）、玛丽琳（罗姗娜·阿奎特 Rosanna Arquette 饰）、萨姆（罗姗娜·阿奎特 Rosanna Arquette 饰）、达尔文（考特尼·万斯 Courtney B. Vance 饰）、伊娃（劳伦·日尔曼 Lauren German 饰）、艾德里安（阿什顿·霍尔莫斯 Ashton Holmes 饰）、波比（迈克尔·艾克朗德 Michael Eklund 饰）这8个陌生人躲进了一座公寓大楼的地下室中。突然一群身着核生化防护服的武装人员出现，掳走了幸存者中的小女孩并准备要杀死剩下的所有人，幸存者们反抗并杀死了武装人员。但地下室的大门被武装人员从外面封死了，人们被困在了地下室中。随着时间的流逝，幽闭恐惧症让这次从避难所变成了牢笼人们开始绝望，已经开始心理扭曲，做出了一些常人难以想象的的事……', '劳伦·日尔曼', '泽维尔·吉恩斯', 6.7, 26325, 'tt1535616', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1482124712.jpg', 2.6, 11.1, 43.7, 31.6, 11, '0.363685,-0.024992,-0.547410,0.234437,0.128749,-0.315628,1.172404,0.158302,-0.354120,-0.455487,0.000354,0.327925,-0.367338,0.141358,0.264255,0.138304,-0.809724,-0.486158,-0.165959,-0.522556,-0.556607,-0.344591,-0.005401,-0.588904,0.136595,-0.250193,0.404623,0.141784,0.058580,0.360122,0.261495,0.513334,0.138426,0.357058,0.226980,0.162022,0.367454,-0.420916,-0.043739,0.097155,-0.123804,0.129765,-0.064346,0.266931,0.006736,0.328968,0.706500,-0.500638,0.322740,-0.124498,0.054981,0.031360,0.056852,0.236052,0.340396,-0.369688,-0.094300,-0.115156,-0.090312,0.294025,0.416866,-0.055433,-0.188174,-0.004542,0.024702,0.175815,-0.313070,0.239769,-0.168641,0.168604,-0.055477,-0.117012,-0.168097,0.107399,0.122641,0.303427,-0.048255,-0.084361,-0.576361,-0.238184,0.160861,-0.227953,-0.469268,0.250893,-0.307150,-0.598643,-0.232747,0.425680,-0.464616,-0.287569,0.619342,-0.084109,0.038708,0.341118,-0.635536,-0.186674,-0.635318,-0.249828,-0.420140,-0.006912,-0.299966,-0.735237,-0.055709,0.005769,-0.133181,0.290493,-0.348806,0.256863,0.160131,-0.368762,0.248454,0.317636,0.235504,0.188043,0.265792,-0.508944,0.362782,0.081543,-0.018731,0.293544,0.192196,0.447476,0.235220,0.623160,-0.016423,-0.210558,