INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4847665', '壁花少年', '剧情', '查理（罗根·勒曼 Logan Lerman 饰）是个害羞和孤独的高中新生，拥有超越年龄的敏感和泪腺，总是默默观察身边的家人和朋友，是个典型的「壁花少年」。他的青春期充满各种挫折，先后经历了阿姨为给他买生日礼物去世、最好朋友自杀、受同侪排挤欺负、单恋没有回应等各种事情。然而查理还不是最惨的，因为和他一样被生活逼入墙角罚站的人实在太多。他幸运的拥有一个开明的老师和两个高年级的好友：叛逆娇俏的少女珊（艾玛·沃森 Emma Watson 饰）和自信满满的同志男生帕特里克（埃兹拉·米勒 Ezra Miller 饰），他们让查理明白了有时候不能永远旁观，必须要参与进来才能拥有属于自己的精彩。《壁花少年》改编自同名畅销原著，由作者史蒂芬·克伯斯基自编自导，《朱诺》原班监制倾力打造，集合90后一众人气偶像，在自杀、霸凌、性向、毒品等诸多敏感争议的话题中，书写一篇献给LOSER的励志日记。', '罗根·勒曼', '斯蒂芬·卓博斯基', 8, 189297, 'tt1659337', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1682183756.jpg', 0.2, 1.9, 23.1, 47.3, 27.5, '0.296398,-0.327098,-0.490628,0.558684,-0.325090,-0.295166,0.893729,0.012678,-0.410309,-0.188460,0.039262,0.885849,-0.239441,0.209943,0.309239,-0.045508,-0.200982,-0.578691,-0.091445,0.011043,-0.110986,-0.503971,-0.162124,0.017196,-0.281449,-0.420531,0.623704,-0.279009,-0.345368,0.536373,0.405504,0.358639,0.068718,0.182789,-0.115862,0.025000,0.101580,-0.023990,-0.230740,0.081419,0.098239,0.070408,-0.068677,0.212279,0.046388,0.094683,0.519001,-0.195304,-0.199104,0.076305,0.499141,-0.331505,-0.182240,0.202279,0.218240,0.016399,0.439257,-0.085308,-0.066087,0.014851,-0.083520,0.006468,-0.877908,-0.168172,0.306000,0.139288,-0.467614,0.517368,0.088253,-0.104352,0.342120,-0.252225,0.102228,0.122323,0.270544,0.464810,-0.110138,0.000762,-0.120084,0.270859,0.466642,-0.120433,-0.161622,0.313828,-0.270855,-0.142434,0.078687,-0.328915,-0.835040,0.218435,0.052149,-0.065759,-0.103305,0.153527,-0.412896,-0.144377,-0.022717,-0.135696,0.122668,-0.561376,-0.159256,-0.366527,-0.151273,-0.417447,-0.233448,-0.060047,0.104258,-0.323522,0.994201,-0.661896,0.250961,0.459434,0.253546,-0.571196,0.700547,0.330650,0.014809,-0.221539,0.002449,0.144857,0.065432,0.006510,0.101928,0.444090,0.074295,-0.224600,-0.358774,0.371349', '27602116', '24284209', '26348103', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4848115', '你看起来好像很好吃', '剧情', '哈特（山口胜平 饰）是一只被草食性恐龙养大的霸王龙。其实，早在它破壳而出时，草食性恐龙的首领就曾命令哈特的母亲（原田知世 饰）抛弃它，但母亲却最终还是偷偷把它养大。随着年龄的增长，每天只吃野果的哈特每天饥饿难耐，最终还是抵不住本能的驱使，开始了自己食肉的残暴生涯。然而，由于母亲的影响，在哈特的内心深处，始终涌动着一颗善良的心灵。一天，偶尔遇到一只破壳而出的食草恐龙宝宝，哈特阴差阳错的被恐龙宝宝误认为是“爸爸”，而且为小恐龙取名为“很美味”，自此开始了又一段奇异的恐龙父子情。然而，伴随着生存环境的恶化，恐龙们的生存遭受着前所未有的破坏，哈特和它的亲人最终能否经得起考验……本篇由日本知名漫画家宫西达也的同名漫画改编，本书曾获剑渊绘本乡绘本奖大奖。©豆瓣', '山口胜平', '藤森雅也', 8.9, 312771, 'tt1734113', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p709670262.jpg', 0.2, 0.6, 8.9, 35.4, 54.9, '0.060169,-0.046084,-0.474835,0.500085,-0.017575,-0.168673,0.773638,0.161262,-0.457051,-0.057207,0.206493,0.519468,-0.097632,0.295695,-0.160309,0.036515,0.157092,-0.152604,-0.043737,0.155006,-0.024213,-0.051573,-0.544231,-0.002708,-0.018106,-0.216032,0.761880,-0.136329,-0.199514,0.379391,0.044691,0.310873,0.016947,0.345987,-0.278528,0.002079,-0.216507,-0.049897,0.125262,-0.070064,0.312070,-0.263150,-0.057518,0.149627,-0.106952,0.217811,0.761806,-0.701699,-0.149254,-0.437293,0.413818,-0.267310,0.116051,0.232149,0.418523,0.107083,0.298285,-0.188452,-0.075962,0.156700,0.068267,0.073351,-0.615909,-0.169942,-0.068569,0.261363,-0.570264,0.204600,0.035030,0.129510,0.381656,-0.438256,-0.148015,0.152037,0.023400,0.539305,-0.385682,0.178072,-0.413280,0.004450,0.637322,-0.205586,-0.455203,0.135449,-0.240584,-0.594940,0.055293,-0.318155,-0.512770,-0.146968,0.354891,0.392004,-0.586736,0.463422,-0.807135,0.240848,-0.319259,-0.489915,-0.027625,-0.224981,-0.149200,-0.351550,0.044347,-0.293728,-0.125772,-0.064491,0.234155,-0.328708,0.996076,-0.709702,0.531397,0.652439,0.092725,-0.143889,0.427053,0.029055,-0.079027,0.058151,-0.044573,0.496180,0.018626,0.025188,0.246311,0.368827,0.285669,-0.086799,-0.348001,0.769002', '4181031', '2977870', '10746430', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4849728', '第一夫人', '剧情', '影片讲述的是美国前总统约翰·肯尼迪在1963年11月22日遇刺身亡的前四天时间里，发生在前第一夫人杰奎琳·肯尼迪身上的故事。娜塔莉·波特曼将出演杰奎琳，也就是Jackie。据该片的全球联合出品方和制片方熙颐影业透露，对于主创团队选择娜塔莉·波特曼出演杰奎琳·肯尼迪，业界并不感到惊讶。除了她精湛的演技之外，更是在于她独特的知性气质。', '娜塔莉·波特曼', '帕布罗·拉雷恩', 6.6, 31522, 'tt1619029', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2508339738.jpg', 0.9, 9.9, 55.2, 28.4, 5.6, '-0.212586,-0.084853,-0.695357,0.700217,0.463058,-0.158190,0.501305,-0.241615,-0.661801,-0.417648,-0.056656,0.727836,-0.469208,0.260665,0.478126,-0.225354,-0.644232,-0.794972,-0.527720,-0.325004,0.108548,-0.487940,-0.212955,-0.218664,-0.230621,-0.387022,0.746826,-0.037261,-0.312186,0.611051,0.378240,0.326636,-0.139682,0.297264,0.216641,0.100437,0.297522,-0.129009,-0.519579,0.369850,0.593229,-0.254060,-0.070738,0.204357,0.308757,0.402693,0.320551,-0.314739,-0.116461,-0.120926,0.573079,0.043560,-0.051297,-0.180774,0.390288,0.123422,0.511213,0.635925,-0.225602,-0.040407,-0.113227,-0.366136,-0.960968,0.326217,0.235955,0.171648,-0.214681,0.522458,-0.506728,0.064457,0.159151,-0.296798,0.313257,0.156467,0.367593,0.254783,0.055034,0.404906,-0.221832,0.144618,0.507387,0.227921,-0.301222,0.512277,-0.219282,-0.587127,-0.395765,-0.273167,-0.104554,0.461112,-0.070260,-0.013998,0.347775,0.189789,-0.200424,-0.150592,-0.202169,-0.401557,0.142900,-0.144156,0.086829,-1.056023,-0.202460,-0.573752,-0.231591,-0.475413,0.239181,-0.545925,0.479884,-0.779094,0.226331,0.160844,0.322397,-0.204314,0.905018,-0.194536,0.221303,-0.029645,-0.323983,0.602789,0.069247,-0.425386,-0.184148,0.345069,-0.075673,-0.453653,-0.083715,0.226958', '24751811', '1293656', '26275494', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4853478', '人鬼情未了', '剧情', '缠绵悱恻的爱情故事不分国界，人鬼情未了的故事这次发生在了女强人，公司大老板星野七海（松岛菜菜子 饰）身上。七海和命定之人——来自韩国的陶艺家金举诺（宋承宪 饰）在日本相遇了，于茫茫人海中邂逅了属于自己的那个人，七海和举诺很快就陷入到热恋之中。一切都像童话故事般美好，直到七海因为意外而丧生，留下了举诺孤身一人。没有了七海在身边，没有了心爱之人的陪伴，举诺起初完全不能接受这样的事实。但是，七海其实一直未曾离开过举诺，她虽然没有了实体，但她的灵魂仍然围绕在举诺身边，陪伴着他、照顾他、守护者他。本片改编自好莱坞同名的经典电影。©豆瓣', '松岛菜菜子', '大谷太郎', 6.3, 4677, 'tt1655400', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p710889090.jpg', 3.3, 14.6, 53.5, 21.2, 7.4, '0.416928,0.183331,-1.027890,0.464613,-0.089117,-0.282584,1.028038,0.136322,-0.507329,-0.184952,0.087047,0.940136,-0.104210,0.236003,0.220105,0.273913,-0.395984,-0.941909,-0.181867,-0.172865,-0.094510,-0.397001,-0.353631,0.153342,-0.432706,-0.183609,0.772057,0.088305,0.023745,0.486469,0.093279,0.137496,-0.087388,0.651618,-0.262361,0.347145,0.150595,0.397912,-0.274654,0.274193,-0.153681,-0.265534,-0.169830,0.456739,-0.013916,0.269515,0.529785,-0.481859,-0.131373,-0.017979,0.145653,-0.223952,-0.231606,-0.021235,0.219130,-0.149432,0.521282,0.134728,-0.197050,0.056395,0.289881,0.042152,-0.847360,-0.047648,0.175396,0.495639,-0.414648,0.594317,-0.092520,-0.269490,0.216311,-0.394024,0.269550,0.110154,0.592434,0.128101,-0.175885,0.045857,-0.544666,0.454496,0.975989,0.175154,-0.433115,0.677613,-0.159242,-0.364649,-0.494912,-0.336606,-0.520399,0.197536,-0.016040,0.446998,-0.520918,0.444088,-0.423935,0.052990,0.147167,-0.324107,0.036229,-0.407335,-0.192656,-0.346809,-0.175921,-0.670276,-0.373794,-0.031421,0.126511,-0.110994,0.732846,-1.043456,0.309773,0.640085,0.298025,-0.181223,0.848662,0.373715,-0.255775,-0.048141,0.153470,0.236128,-0.013822,0.305925,0.362851,0.298605,0.003274,0.082780,-0.712773,0.386032', '4275444', '1308755', '1296370', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4856162', '裸', '情色', '在位于新泻的田园乡间，18岁的美丽女孩山濑广美（渡辺奈緒子 饰）结束了高中学业，她和男友英介携手前往东京闯荡。平日里广美做着一份稳定的机场地勤工作，但是她的心中始终怀有一个演员的梦想。偶然机缘，她在街头邂逅了娱乐公司的经纪人夏本正人（光石研 饰），不曾想对方竟是一家AV公司的负责人。经过一番考虑，广美决定以拒拍AV为底线，正式进入这家公司。随着极度诱惑的平面写真的流行，广美渐渐积攒着人气，同时也遭到来自英介和家乡好友的压力。而在一过程中，她离那条底线也越来越近……本片根据AV女星美广（Mihiro）的自传改编，美广本人亦在片中出演了角色。©豆瓣', '渡辺奈緒子', '小沼雄一', 5.8, 6688, 'tt1660399', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p699556753.jpg', 4.2, 23.8, 55.1, 13.4, 3.5, '0.094506,0.158307,-0.624414,0.633308,0.224027,-0.182772,0.398933,0.398067,-0.332247,-0.245809,0.180439,0.748016,-0.093324,0.314777,0.475819,-0.177726,-0.172740,-0.513503,0.065112,-0.316352,0.114875,-0.376806,-0.200742,-0.001935,-0.277520,-0.168917,0.773590,0.222492,-0.106575,0.371763,0.324450,0.063575,-0.281187,0.383085,-0.033611,-0.068778,0.117739,0.103301,-0.298634,0.206947,0.043959,-0.423978,-0.130400,-0.098092,0.209058,0.471640,0.816580,0.094669,-0.236626,0.081970,0.579435,0.004784,0.024995,-0.040488,0.358904,0.050060,0.300314,0.285812,-0.432306,0.030422,-0.006215,-0.368621,-0.586697,-0.125358,0.198854,0.011327,-0.444773,0.442918,-0.114349,-0.101314,0.093112,-0.249734,0.066224,0.325301,0.187543,0.212518,-0.121246,0.225328,-0.161356,0.389972,0.621192,0.171468,-0.021151,0.363828,-0.160772,-0.428022,-0.301452,-0.140305,-0.510824,-0.093346,0.095371,0.072664,-0.234005,-0.097878,-0.491733,0.084458,-0.069894,-0.237481,0.180605,-0.280089,0.026083,-0.640496,-0.119042,-0.195770,-0.065085,-0.046849,0.162064,-0.282417,0.621981,-0.893822,0.020765,0.737546,0.331220,-0.337779,0.804500,0.044986,0.034337,-0.291792,-0.151477,0.312826,-0.197519,0.324409,-0.020223,0.356134,-0.126559,-0.298740,-0.397964,0.363230', '3811356', '4144683', '25880986', '3014200');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4858775', '假装情侣', '喜剧', '善良的保险公司销售员陈文（黄渤 饰）在广场邂逅了一个疯疯癫癫的女孩，谁知在去精神病院的路上女孩化身成清秀美丽的佳人。虽然惹得一堆麻烦上身，不过陈文次日还是应约与这个叫做沈露（江一燕 饰）的女孩见面。沈露要求陈文做他的假装情侣，而陈文也欣然接受。在接下来的日子里，陈文变成一个随叫随到的小仆人，他按照沈露的要求做着各种各样难为情却又好玩的事情，两人度过了一段难忘的美好时光。在此期间，陈文慢慢喜欢上了这个古灵精怪的女孩，沈露的心中似乎也经历着某种矛盾纠葛。某一天，沈露突然音讯全无，再见面时她却提出结束和陈文这段假装情侣的游戏……©豆瓣', '黄渤', '刘奋斗', 6.1, 54150, 'tt1990255', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1037533201.jpg', 6.4, 18.7, 46, 21.3, 7.6, '0.491934,0.178381,-0.674179,0.473794,-0.232719,-0.305664,1.098679,-0.028383,-0.317231,-0.181073,0.194043,0.600339,-0.465674,0.658961,0.484795,0.216996,-0.356669,-0.624196,0.075444,-0.204888,-0.066557,-0.324646,-0.116411,-0.146194,0.121162,-0.072845,0.434861,0.078985,0.067041,0.534523,0.357570,-0.099727,-0.103140,0.657937,-0.164354,0.039875,-0.033901,0.360799,0.047873,-0.109652,0.185625,-0.343938,-0.297142,-0.059917,-0.120438,0.424364,0.630072,-0.189482,-0.513105,0.160378,0.422962,-0.262476,-0.034686,0.001792,0.238335,-0.098525,0.375525,-0.111113,-0.209328,-0.088874,0.209348,0.009846,-0.420909,0.178847,0.006870,0.203091,-0.422637,0.581009,0.069484,0.015914,0.165675,-0.531184,0.033143,0.277862,0.341432,0.382221,-0.254865,0.075671,-0.446248,0.302646,0.653513,0.346467,-0.226973,0.473542,-0.223337,-0.405749,-0.066238,-0.019954,-0.484835,0.058971,0.227998,-0.311096,-0.310273,0.043070,-0.578832,0.134210,-0.047067,0.118742,-0.087043,-0.377799,-0.193918,-0.467789,-0.058228,-0.485805,-0.478726,0.095644,0.092559,-0.184468,0.693879,-0.659143,0.177094,0.572463,0.199146,-0.390827,0.561501,0.342191,0.152271,-0.285480,-0.163487,0.065645,-0.409925,0.143278,0.115160,0.648374,0.023332,0.087615,-0.480454,0.430055', '21348112', '1296534', '1296500', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4861402', '深海之战', '动作', '济州岛最南端的海域上，石油勘探船“月食号”深入海底2500米下的第七矿区石油开发区进行石油勘探。船员们都雄心勃勃，斗志昂扬，梦想着开发巨大的油田，报效国家。然而，无数次的勘探作业都以失败告终。因此，总部下达了撤离矿区的命令。总部派来船长郑万（安圣基 饰）劝说大家撤离。因为父亲曾经葬身这片海底，设备管理员俊海（河智苑 饰）不愿辜负父亲所望就此离去。她坚信这片海底藏有石油，因此拒绝听从撤离命令。本部发出最后通牒，所有船员必须在一个月内整理撤退。当俊海和船员们正在进行最后一次石油探测尝试时，突然，与本部联系的信号中断了。惊恐之中，船员们感觉到有什么东西正潜伏在这片大海中，怪异恐怖的氛围笼罩了“月食号”。接着，船上的人一个接着一个离奇地死去……©豆瓣', '河智苑', '金志勋', 5.3, 9526, 'tt1934381', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1259589256.jpg', 9.6, 32.6, 45.4, 9.5, 2.9, '-0.211507,0.106299,-0.944976,0.585198,0.196823,0.066660,0.398579,-0.076362,-0.396609,-0.131837,0.237567,0.491166,0.138921,0.054377,0.085540,0.121924,-0.729324,-0.524198,-0.361045,-0.174460,-0.358780,-0.375097,-0.057479,-0.228223,0.000600,-0.111906,0.560700,0.440299,-0.214061,0.392295,-0.063408,-0.001743,-0.289743,0.737658,0.106861,-0.232881,0.260849,-0.306540,-0.219801,0.074053,-0.538853,0.011997,-0.026397,-0.054386,0.385449,0.521520,0.638185,-0.369573,-0.091900,-0.171380,0.108869,-0.327980,0.120639,0.110227,0.401153,0.278784,-0.140236,0.263927,-0.398761,0.004891,-0.117088,-0.085010,-0.514492,-0.215814,-0.193467,0.088048,-0.373459,-0.104851,0.047613,0.241180,-0.035797,-0.383467,0.232283,0.211024,0.175462,0.117838,-0.290440,0.199842,-0.215231,0.062704,0.825826,-0.207294,-0.097521,-0.336775,0.158438,-0.426899,0.014999,0.039649,-0.277727,-0.190830,0.143284,0.351278,-0.131286,0.166073,-0.786545,0.092503,-0.421897,-0.788788,-0.170034,-0.177718,-0.285727,-0.971182,0.280866,0.229753,-0.076938,0.413221,-0.087950,0.103715,0.540635,-0.244871,0.236491,0.400842,0.412009,-0.488503,0.484770,0.052073,0.220063,-0.272977,0.108443,0.309152,0.121403,0.722894,0.032546,0.043407,-0.244350,-0.095243,-0.498999,-0.015911', '2159244', '3871833', '1300868', '2079017');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4861408', '恋爱操作团', '喜剧', '如何对心仪的他或她正确的表达出心中所想，且被成功接受，这是个困扰无数陷入爱情漩涡中男男女女的问题。而“大鼻子情圣恋爱操作团”则专门为应对这个问题而诞生。其创始人邴勋（严泰雄 饰）之前经营剧团，相信爱情也可以按照剧本有条不紊的进行。恋爱操作团接到的第一个任务被顺利完成。从打造男主角的形象，到摸清女主角的想法喜好，最终帮助男主角告白成功。一切都在设定的剧本里。紧接着，恋爱操作团迎来的另一位顾客尚勇（崔丹尼尔 饰），他心仪的女孩熙中（李敏贞 饰）恰巧是邴勋的前女友。于是难题展开，一方是自己的顾客，应该竭尽全力的服务；另一方面，看着自己的前女友和别人愈走愈近，邴勋心里很不是滋味。设定的剧本没有了存在的意义，原来恋爱无法操作……该片翻拍自法国同名电影《大鼻子情圣》，而其灵感则来自于法国作家罗斯丹的名剧。©豆瓣', '严泰雄', '金炫锡', 6.7, 12641, 'tt1786668', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p594945513.jpg', 1.2, 8.6, 52.7, 30.9, 6.7, '0.295855,0.122001,-0.476724,0.736488,-0.120910,0.099294,0.613562,-0.118069,-0.339166,-0.388524,0.149847,0.774820,-0.127607,0.198863,0.371438,-0.234632,-0.291942,-0.651116,-0.072101,-0.069623,-0.138749,-0.574085,-0.274761,-0.129096,-0.179172,-0.046940,1.016187,-0.065509,-0.254139,0.069271,0.490395,0.582331,0.008403,0.259410,0.042762,-0.075624,0.050910,-0.053369,-0.402546,0.324735,0.068004,-0.120706,-0.085418,0.393961,-0.232383,0.349572,0.827667,-0.399248,-0.201813,-0.048711,0.655601,-0.315975,0.020120,0.012096,0.019578,0.300498,0.281944,0.158059,-0.019539,0.125523,-0.089338,-0.287713,-1.084229,-0.296351,0.246390,0.259682,-0.366819,-0.002912,-0.152975,-0.072449,-0.011888,-0.249059,0.057873,0.254858,0.792348,0.312444,-0.440242,0.070755,-0.243789,0.353727,0.568272,0.193715,-0.290751,0.661308,-0.274414,-0.571834,-0.098162,-0.077343,-0.344387,0.023257,0.115481,0.287536,0.080929,-0.070369,-0.545185,0.103894,-0.025880,-0.178786,0.015544,-0.520437,-0.144144,-0.464186,-0.277463,-0.178422,-0.268176,-0.212766,0.081129,-0.193360,0.732777,-0.874100,-0.229721,0.426994,0.047807,-0.699910,0.606981,0.408336,-0.071544,-0.666816,-0.143401,0.201422,-0.240927,-0.021047,-0.255131,0.211391,0.226548,-0.341184,-0.408722,0.489194', '26759820', '25880986', '6844861', '26834930');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4861627', '和声', '剧情', '女犯人贞慧（金允珍 饰）在狱中生下儿子珉宇，小珉宇就像上帝派来的小天使，让这些和贞慧一样曾犯下罪过的女人在围墙之内品味久违的温情。一次慰问演出让贞慧萌生了在监狱里组建合唱团的想法，可是贞慧不仅五音不全，而且完全没有相关经验。小珉宇满18个月后将被领养，为了得到在领养之前与儿子一起外出的机会，贞慧决定无论组建合唱团有多困难都要坚持下去。在众多善良狱友的帮助下，合唱团终于小聚规模，然而令贞慧没想到的是，一起与儿子外出的日子也是与儿子的离别之日。合唱团就像一个幸福的大家庭，它不仅带给那些失去自由的犯人们欢乐，而且也在逐渐弥合曾经的苦难记忆留在他们内心的殇痛……©豆瓣', '金允珍', '康大奎', 8.5, 63793, 'tt1588356', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p543621113.jpg', 0.2, 1, 12.8, 43.5, 42.6, '0.011125,-0.032485,-0.897897,0.498618,-0.182018,-0.309589,0.714693,-0.080891,-0.598963,0.002423,0.050847,0.720752,-0.048786,0.519922,0.080045,-0.371512,-0.200256,-0.786489,-0.044329,-0.137689,-0.206947,-0.498442,-0.128987,-0.005260,-0.061000,-0.556344,0.734030,0.146586,0.138690,0.383526,0.281216,0.155524,-0.078458,0.347599,-0.448440,-0.042591,0.047603,0.369004,-0.352204,0.193735,0.093475,-0.011857,-0.128392,0.140013,0.153182,0.102768,0.674275,-0.419264,-0.412059,-0.112773,0.349400,-0.028529,-0.088922,0.154432,0.105770,0.177980,0.420850,0.357771,-0.226521,-0.022219,0.034351,-0.241696,-0.783117,0.008322,0.244983,0.040848,-0.781991,0.429031,0.134345,-0.083487,0.146756,-0.279634,0.337186,0.406729,0.288256,0.659552,-0.422292,0.207620,-0.338735,0.060466,1.107417,-0.183129,-0.203374,0.336341,-0.373698,-0.273375,0.112798,-0.287692,-0.396020,0.196700,-0.013777,0.014251,-0.487109,0.256179,-0.431286,0.099227,-0.191302,-0.081639,0.176467,-0.477401,0.022548,-0.391116,-0.063898,-0.106022,-0.320653,0.251514,0.345616,-0.447629,0.886741,-0.971407,0.535640,0.550236,0.305104,-0.762451,0.678741,0.242000,0.042854,0.049551,0.097175,0.145814,0.019598,0.131650,0.152379,0.175135,-0.163186,-0.115963,-0.445831,0.443081', '25721544', '35030151', '1870682', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4864908', '影', '剧情', '战乱年代，群雄并起。割据一方的沛国安于现状，一任国主沛良（郑恺 饰）慨歌太平。要冲之地境州早年为强邻炎国借去，而今据而不还。沛国都督子虞（邓超 饰）前往讨伐，却中了对方大将杨苍（胡军 饰）的拖刀，重伤不愈。心有不甘的子虞暗中派出替身境州（邓超 饰）假扮自己，总理军政，内则使令夫人小艾（孙俪 饰）襄助。真假子虞切磋战法，寻求破解杨苍刀法的绝技。而另一方面，沛良恼怒子虞私自约战杨苍，不惜将妹妹青萍（关晓彤 饰）嫁于杨苍之子为妾媾和。淫雨霏霏，连日不开。境州上空，杀戮与机谋纠缠撕裂……本片根据朱苏进的剧本《三国•荆州》改编。©豆瓣', '邓超', '张艺谋', 7.2, 557707, 'tt6864046', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2530513100.jpg', 1.6, 6.1, 35.5, 43.8, 13.1, '-0.098125,0.221457,-0.350258,0.457719,0.357909,0.010539,-0.070422,0.159722,-0.590286,-0.602270,-0.034401,0.162245,0.171912,0.000869,0.101170,-0.072262,0.069017,-0.509209,-0.281757,0.195893,0.052984,-0.052037,-0.199929,-0.302548,-0.277551,-0.113393,0.686671,0.383311,-0.195504,0.452318,0.462615,0.196940,-0.347308,0.471562,0.027503,0.142534,-0.376905,0.031058,-0.337281,0.077436,-0.187295,-0.592607,-0.199922,-0.129057,0.001009,0.588415,0.399014,-0.278075,0.454291,-0.383849,0.158302,-0.168690,0.077334,0.160611,0.138429,0.167335,0.211853,0.136881,-0.236823,0.025016,0.060589,-0.052345,-0.410472,-0.151052,0.469284,0.029635,-0.251165,0.227852,-0.547966,-0.078641,-0.311036,-0.142641,0.110428,0.398228,0.286484,-0.173741,-0.087185,-0.245475,-0.247959,0.310757,0.245672,-0.037039,0.181621,-0.263156,0.051345,-0.374402,-0.000633,-0.314168,-0.227824,-0.250962,0.351128,-0.216780,0.400017,0.252824,-0.249598,-0.384560,-0.324220,0.544728,0.007603,-0.057681,0.257611,-0.214968,0.197964,-0.251477,0.127687,-0.057573,0.594574,-0.071682,0.083084,-0.545702,-0.164338,-0.047787,0.315041,-0.428146,0.211775,0.274791,0.062253,-0.249180,-0.000929,0.084405,0.160441,-0.003554,0.154088,0.252151,-0.009462,-0.187949,-0.263990,0.053561', '11627068', '1294693', '3264045', '1305143');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4873490', '失恋33天', '剧情', '高端婚礼策划师黄小仙（白百何 饰）做梦也想不到，相恋七年的男友居然和自己的闺蜜走到了一起，这让一向刻薄强势的她无论如何也不能忍受。可是地球并不会因为某人的失恋而停止运转，黄小仙在面对情感失意的同时，还不得不面对工作上的压力。但是，在没有了爱情的这段时间里，黄小仙发现了很 多以前根本不会去注意的东西，例如那个总是与自己针峰相对的娘娘腔同事王小贱（文章 饰）并没有那么讨厌，例如钻石王老五与河南籍港台腔女子的结合到底是什么原理，还有如何走到金婚的秘诀。在明白了种种之后，也就是在黄小仙失恋的第33天里，在那个灯火阑珊的城市里，她发现“那人”其实一直伴她左右……本片改编自豆友大丽花写的人气网络小说。©豆瓣', '白百何', '滕华涛', 7.2, 571485, 'tt2115388', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1252876266.jpg', 1, 5, 39.4, 41.1, 13.6, '0.534738,-0.197221,-1.031396,0.706636,-0.261962,-0.231030,0.878237,-0.022317,-0.532930,-0.293531,0.052491,0.744641,-0.370576,0.159510,0.058293,0.080674,-0.159481,-0.639181,0.056162,-0.250233,-0.290005,-0.451133,-0.255279,0.019465,-0.068067,-0.195200,0.645054,0.154769,-0.246108,0.296106,0.471709,0.025769,-0.005167,0.806225,-0.173405,0.061054,-0.191160,0.226946,-0.100047,0.082377,0.329086,-0.322932,-0.108289,0.232472,0.070369,0.262878,0.445657,-0.302789,-0.300572,0.361377,0.403236,-0.229018,-0.253918,0.053771,0.217261,-0.270178,0.446813,0.230995,-0.092491,0.273816,0.028077,0.072576,-0.809400,0.029224,0.119679,0.303842,-0.663175,0.535041,-0.007546,-0.239220,-0.021798,-0.344646,0.311945,0.265120,0.265301,0.385118,-0.388958,-0.269071,-0.613642,0.150915,0.703844,0.273989,-0.184929,0.748512,-0.020727,-0.411910,-0.325887,-0.289958,-0.448842,0.093855,-0.275027,0.123713,-0.412803,0.048450,-0.554248,0.185646,0.147346,-0.148904,-0.048856,-0.551773,-0.090800,-0.311714,-0.195369,-0.871074,-0.310044,0.155018,0.132275,-0.429120,0.771712,-1.048186,0.125767,0.635406,0.523080,-0.630849,0.780492,0.471869,-0.275088,-0.079894,-0.343084,0.204395,-0.087923,0.356540,0.012989,0.344353,0.250522,-0.421825,-0.361659,0.583487', '1296370', '4275444', '24756472', '1438708');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4876722', '钢的琴', '剧情', '上世纪90年代初，东北某重工业城市。原钢厂工人陈桂林（王千源 饰）在下岗后，独自拉起了一支乐队，终日奔波在婚丧嫁娶、店铺开业的营生之中，生活勉强维持。他的妻子小菊（张申英 饰）离家出走，转投有钱的假药商人怀抱。如今小菊光鲜回归，不仅要与桂林离婚，还要争夺独生女小元的抚养权。桂林慨叹自己失败的命运，于是一心要将女儿培养成钢琴家。为了得到女儿，他四处筹措买钢琴的钱，甚至和女友淑娴（秦海璐 饰）以及当年钢厂的好哥们夜入学校偷钢琴。当所有的办法都失败后，桂林偶然翻到一本关于钢琴的俄国文献，于是叫上伙伴们在早已破败的厂房中开始了手工制造钢琴的征途……©豆瓣', '王千源', '张猛', 8.5, 350383, 'tt1723118', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p511447359.jpg', 0.2, 0.9, 12.1, 47.8, 39, '0.196246,0.262283,-0.550177,0.331870,-0.070532,-0.374093,0.283845,0.137987,-0.548735,-0.148063,0.036477,0.549023,0.245678,0.441797,0.255803,0.115308,-0.396582,-0.774893,-0.109822,-0.101305,-0.203460,-0.284589,-0.074218,-0.085595,-0.419461,-0.072504,0.587471,0.145337,0.080141,0.223653,0.268757,0.142394,-0.120620,-0.021231,-0.396201,0.049297,-0.030875,0.290985,-0.399243,0.089588,-0.066193,-0.285071,-0.064521,-0.111133,0.379294,0.124765,0.693007,0.106843,0.302172,-0.246184,0.344501,0.330421,-0.126670,-0.086789,0.235355,0.154536,0.296521,0.181098,-0.347890,-0.018212,0.127106,-0.234229,-0.371457,-0.074322,0.309705,-0.186101,-0.736643,0.316023,0.043976,0.240369,-0.008332,-0.438101,0.356810,0.392954,0.028379,0.461470,-0.157415,0.189769,-0.520303,0.716576,0.444726,-0.011296,0.160584,0.176548,-0.039724,-0.171450,0.051434,-0.358851,-0.505678,-0.048212,0.238336,-0.048733,-0.042535,-0.024323,-0.773761,0.007687,0.074222,-0.217551,0.412991,-0.052777,-0.106584,-0.566491,0.151896,-0.217815,-0.080867,0.045050,0.129842,-0.269270,0.536500,-0.609349,0.107673,0.327542,0.276128,-0.441443,0.507596,-0.125094,0.356604,-0.135684,-0.040864,0.088441,-0.218937,0.440747,-0.016656,0.020943,-0.169993,-0.290888,-0.281151,0.519373', '26926321', '3041753', '1296769', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4881121', '七小罗汉', '喜剧', '休休大师（曾志伟 饰）有七个弟子，他分别用乐谱的七个音符来命名，毎日向他们传授北斗七星罗汉阵。一天，休休大师下山给人看病，临行留下书信一封，告诫徒儿们好生习武，震守山门。常言道，山中无老虎，猴子称大王，师父一走，山上立刻乱了套。古寺中藏有震庙之宝，寺外歹人早就虎视耽耽，趁休休下山，以九纹龙（陈思成 饰）为首的四人盗宝组化装进香游客伺机盗宝。没想到他们低估了七小罗汉，一交手便落入七小罗汉看似不经意编织的陷阱，就在小罗汉们感到胜券在握之机，恼羞成怒的九纹龙炸毁了寺庙，并挟持了一名小罗汉，在休休的禅房中歪打正着地得到了震庙之宝。目睹此景，小罗汉们后悔万分，悔不该不听师父的话，如今误了大事……©豆瓣', '曾志伟', '傅华阳', 5.2, 5365, 'tt2044847', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p532593821.jpg', 15.8, 30.3, 37.8, 10.9, 5.3, '0.115688,-0.282374,-0.545847,0.499223,0.065631,-0.228305,0.410197,-0.107970,-0.429186,-0.423058,0.425417,0.489442,-0.215893,0.197672,0.075816,-0.169648,0.066062,-0.209830,-0.196382,-0.367960,-0.045959,0.047932,0.087150,-0.116422,-0.227801,-0.212088,0.144796,0.004774,-0.087750,0.306633,0.150932,-0.032815,-0.310753,-0.018537,-0.167167,0.262585,-0.110540,-0.013419,0.178110,-0.075823,-0.415214,-0.308334,-0.518151,0.004259,-0.115898,0.259107,0.409864,-0.385280,-0.265869,-0.218472,-0.162110,-0.055982,0.121374,0.245917,0.197678,0.028545,0.336170,0.030563,-0.322463,0.236417,0.113485,-0.227682,-0.186066,0.323453,0.182287,-0.020022,-0.340174,0.079565,-0.032534,0.112629,-0.115544,-0.427950,0.080503,0.033389,0.224576,0.183426,0.119143,-0.383456,-0.542732,0.107267,0.226499,-0.382853,0.311549,0.003093,0.598318,-0.206987,0.284321,0.074829,0.028974,0.143283,0.607176,-0.199170,-0.026682,-0.005615,-0.207894,-0.168307,-0.363318,0.095120,-0.248685,-0.098911,0.029147,-0.519346,0.454909,0.144624,-0.263203,0.291095,0.403026,0.244751,0.808763,-0.433314,0.299178,0.159952,-0.062818,-0.316347,0.633303,-0.200537,-0.101804,-0.150808,-0.067277,-0.263859,0.122345,0.602130,0.528905,0.418805,-0.236679,-0.166149,-0.280820,-0.230299', '1301136', '25882279', '1302661', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4881217', '被拒人生', '剧情', '劳瑞尔（朱丽安·摩尔 Julianne Moore 饰）是一位办案经验非常丰富的警探，在岗位上23年，劳瑞尔的办案能力从来都没有输给过任何的一个男同事。然而她有一个秘密，那就是她是一名同性恋者，为了保护自己在警局里的地位，她必须对这个秘密严防死守。某日，劳瑞尔在一场活动中邂逅了名叫黛西（埃利奥特·佩吉 Elliot Page 饰）的女子，黛西是一名汽车修理工，虽然他们两人无论是身份还是年龄都悬殊巨大，但恋人还是彼此吸引最终走到了一起。不幸的是，劳瑞尔发现自己患上了癌症，命不久矣，她打算把自己的养老金转到黛西的名下，以保证她在自己去世之后依然能够拥有她的房子，但劳瑞尔的申请很快就遭到了拒绝。©豆瓣', '朱丽安·摩尔', '彼得·苏列特', 7.6, 15561, 'tt1658801', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2264867391.jpg', 0.5, 3, 32.8, 45.2, 18.5, '0.364949,0.106483,-0.506422,0.366086,-0.388979,-0.173536,0.879258,0.073085,-0.690830,-0.169647,0.366618,1.032757,0.180846,0.149082,0.090919,0.038441,-0.345336,-0.565864,0.277498,-0.214224,-0.306652,-0.649247,-0.512020,0.098465,-0.349624,-0.463568,0.550376,-0.292483,-0.133546,0.492571,0.275678,0.080079,0.204284,0.620562,-0.141409,0.034428,0.346470,-0.048579,-0.052193,0.326693,-0.048597,-0.360670,-0.105668,0.310345,0.067589,0.530533,0.187138,-0.083116,-0.182033,0.146051,0.236131,-0.320690,0.077196,0.288766,0.388329,-0.225696,0.130192,0.306319,-0.471332,0.124818,0.107696,-0.075395,-0.919983,-0.097135,0.163614,0.268781,-0.737472,0.437606,-0.276823,-0.271547,-0.025865,-0.184939,0.034269,0.333988,-0.019367,0.306760,-0.241420,-0.018772,-0.483064,0.063840,0.541860,0.032908,-0.407597,0.307082,-0.167598,-0.482270,-0.197036,-0.358788,-0.596033,-0.000282,0.074221,0.059356,-0.192621,0.154328,-0.580255,0.072991,-0.376774,-0.370279,-0.116271,-0.272109,-0.012537,-0.278032,-0.168721,-0.646015,-0.559749,0.067068,0.079015,-0.443388,0.730945,-0.993387,0.191298,0.534068,0.390864,-0.519960,0.830720,0.231373,0.443375,-0.067785,0.055473,0.180832,0.008363,0.248045,0.004288,0.433995,0.281362,-0.235035,-0.306263,0.597447', '1783461', '1793491', '1292720', '1291577');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4881604', '回马枪', '喜剧', '2010年某夜，北京惊堂博物馆。犯罪集团“兰花盗”的两名盗贼潜入其中，偷走了价值连城的名画《聂隐娘》。谁知二贼过于鲁莽，在与保安周旋的过程中，竟用香烟将画烧出一个洞。为了尽快修复古画，“兰花盗”决定找到早已从江湖隐遁多年的修画名家神手。他们认定中年男子李贞木（任达华 饰）——一个功成名就、身边美女如云的香水专家，就是他们苦苦寻找的神手，于是想尽办法逼其就范。一计不成，再施一计，性感妖娆的女贼闵悦（伊能静 饰）被派往李贞木的身边，接连使出美人计。与此同时，李的前妻去世，女儿苗心回到他的身边生活。却由此衍生出新的混乱。猎人与猎物，彼此搞不清自己的身份……©豆瓣', '任达华', '李远', 4, 5092, 'tt1967478', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1106129942.jpg', 35.2, 35.4, 25.1, 3, 1.3, '0.212525,0.017948,-0.300917,0.624077,-0.316915,-0.273437,0.543630,-0.128942,-0.450730,-0.363805,0.390903,0.488961,-0.132932,0.145990,-0.006591,0.063583,0.015807,-0.778116,-0.119201,-0.099313,-0.213596,-0.056677,-0.453308,0.018802,-0.241572,-0.050390,0.612676,0.164637,-0.225898,0.226564,0.246006,0.311159,-0.451089,0.057675,-0.281472,-0.042279,-0.011375,-0.159517,-0.296436,0.213812,0.015000,-0.634304,-0.119646,-0.159165,-0.217751,0.176453,0.755574,-0.275732,0.079978,-0.175312,0.334649,-0.220021,-0.188464,-0.086238,0.222923,0.096834,0.204054,-0.110783,-0.466155,-0.047171,0.168345,-0.128766,-0.687123,-0.019898,0.221552,-0.040066,-0.484940,-0.005828,-0.172250,0.245231,-0.068007,-0.387116,0.142059,0.094699,0.305002,0.022999,-0.131070,0.004153,-0.557948,0.247326,0.274609,-0.067719,0.073430,0.081970,0.107880,-0.192101,0.224312,-0.322131,-0.016096,-0.136946,0.628241,-0.072003,0.017834,-0.058700,-0.487884,-0.129880,-0.358260,0.212216,0.265855,-0.109154,-0.282904,-0.568743,-0.164817,-0.023889,-0.123835,0.027598,0.188781,-0.051277,0.526622,-0.403897,0.160898,0.262983,0.018593,-0.515789,0.493776,-0.236868,0.011306,-0.206457,-0.233718,0.176752,0.390980,0.361182,0.249898,0.255388,-0.106304,-0.094601,-0.507847,0.110781', '10467125', '6101834', '25880986', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4881607', '撒娇女人最好命', '喜剧', '女汉子张慧（周迅饰）从大学时期起就暗恋同学蠢萌宅男龚志强（黄晓明饰），可惜龚志强一直都把她当哥们儿，而且还坚持在事业有成之前保持单身，张慧只好就默默等待着。一次出差，志强邂逅了台湾软妹蓓蓓（隋棠饰），在蓓蓓的撒娇攻势下志强缴械投降，两人瞬间爱的天雷勾地火。张慧得知情况后大受打击，好在闺蜜——号称上海撒娇女王的阮美（谢依霖饰）出手相救，还找来了长江以南最强撒娇天团相助，誓要教张慧训练为撒娇达人，夺回真爱。一场腥风血雨的男神争夺战势在必行，究竟鹿死谁手？本片改编自罗曼夫的畅销情感书籍《会撒娇的女人最好命》。©豆瓣', '周迅', '彭浩翔', 5.7, 206913, 'tt3313908', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2213388572.jpg', 7, 25.2, 49.2, 14.6, 3.9, '-0.272231,-0.187210,-0.526325,0.305125,0.082091,-0.258475,0.037385,0.105365,-0.246215,0.074513,0.302481,0.316843,-0.165963,0.283686,0.199530,-0.129894,-0.101057,-0.630076,-0.056507,0.231091,-0.042728,-0.032513,-0.176833,0.286480,0.001869,-0.288184,0.198315,-0.232121,-0.253344,0.306902,0.635202,0.072998,0.022249,0.427458,-0.103521,-0.051212,-0.142657,0.119594,-0.450520,0.251726,0.295126,-0.023662,-0.037476,0.056589,0.201027,0.088729,0.478454,-0.062502,0.086223,0.077329,0.270222,-0.237335,-0.106353,0.179690,0.249024,-0.264132,0.394729,-0.067747,-0.215781,0.017823,0.105560,-0.015480,-0.237008,0.147237,-0.050532,-0.082658,-0.423406,0.250397,-0.021002,0.181774,0.193989,-0.276534,0.086652,0.294376,0.164441,0.266537,-0.238124,0.129552,-0.254790,0.364417,0.436809,0.108529,0.022419,0.146280,0.361847,-0.188280,0.056056,-0.290353,-0.597930,0.060742,0.040341,-0.156640,-0.137998,-0.122183,-0.366674,-0.054105,-0.022226,0.264881,0.271277,-0.283661,-0.229390,-0.434893,0.036988,-0.018540,0.005204,-0.052447,0.098650,-0.285527,0.750593,-0.691031,0.057438,0.370933,0.330032,-0.464689,0.496326,0.338529,-0.236219,-0.312271,0.069222,0.232327,-0.131262,0.162494,0.274752,0.315274,-0.064404,-0.163936,0.033020,0.369357', '1316589', '6963575', '25922902', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4883258', '死亡录像3：创世纪', '喜剧', '在一个阳光明媚的日子里，美丽的克拉拉（拉蒂西亚·多瑞拉 Leticia Dolera 饰）即将和英俊帅气的爱人科多（迪雅戈·马丁 Diego Martín 饰）步入婚礼殿堂。双方亲朋相聚在一起，载歌载舞，好不欢畅。然而正当婚礼晚宴进行到高潮之时，一个中年男子突然从楼上跌落，当他爬起身时，其形容大变，面目狰狞，随即狂躁地啃咬身边的人。现场有如炸锅一般，所有人的都四散而逃，而不知为何变成丧尸的人们追咬着每一个生者，丧尸的队伍越来越大，科多与克拉拉也在混乱中失散。教堂已然变成地狱，有如最后的审判日，人们身不由己……©豆瓣', '拉蒂西亚·多瑞拉', '帕科·普拉萨', 6.3, 24248, 'tt1649444', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p975644198.jpg', 4.9, 18.1, 45.7, 21.6, 9.6, '0.268721,0.081285,-0.929037,0.343627,0.126665,-0.428376,1.065317,0.277935,0.051632,0.217605,0.236535,0.733840,-0.651648,0.444042,0.496033,0.011334,-0.319762,-0.705672,-0.222748,0.067777,-0.205934,0.033468,-0.073073,-0.230213,0.048935,-0.104088,0.498101,0.129691,0.257534,0.560024,0.352852,0.233205,-0.193276,0.405756,-0.284971,-0.190792,0.155528,0.148611,0.086315,-0.053332,-0.238124,-0.207233,-0.410576,-0.004379,-0.323197,0.210315,0.539689,-0.438600,0.041134,-0.245134,0.242267,-0.350412,-0.085749,0.298193,0.348233,-0.096247,0.086053,-0.270794,0.115025,0.078540,0.100884,-0.181816,-0.354694,0.207166,-0.052557,0.344593,-0.403770,0.440139,0.088047,0.045199,0.246134,-0.030842,0.167732,0.274447,-0.107230,0.362617,-0.186918,-0.118703,-0.540438,0.052848,0.696711,0.111095,-0.556772,0.239221,-0.099037,-0.578631,0.224248,-0.029854,-0.307317,-0.404474,0.317559,0.243015,-0.254456,0.317153,-0.541279,0.121186,-0.349471,-0.215289,-0.311189,-0.203550,-0.597556,-0.643956,-0.069579,-0.237194,-0.016708,0.222916,-0.174283,0.104349,0.670586,-0.375173,0.282370,0.176496,0.090364,0.016181,0.442981,-0.324555,0.175671,0.245993,-0.103249,0.157142,-0.079396,0.402107,0.230260,0.376586,-0.444498,0.261286,-0.440672,0.734357', '1296534', '3011051', '2269893', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4883300', '莎拉的钥匙', '剧情', '本片通过女记者朱丽娅（克里斯汀·斯科特·托马斯 Kristin Scott Thomas 饰）的视角重现了二战期间发生在法国巴黎东赛馆事件中的一个悲伤的故事。1942年，在德国占领下的法国巴黎被要求交出居住在巴黎的犹太人。十岁的萨拉（梅路什·玛亚奇 Mélusine M ayance 饰）和她的家人也未能在这次浩劫中幸免于难。在军队搜捕来临之际，萨拉将年幼的弟弟悄悄锁进家中的衣柜保护起来，并小心翼翼地收好了衣柜的钥匙，满心希冀可以通过这个方法让弟弟免于德军的搜捕。可是向往集中营的萨拉意识到这次离开不是一天两天的时候，她拼命逃出集中营回到旧居。可是迎接她的不仅是已经搬进的新住户，还有在衣柜中已经不幸遇难的弟弟。朱丽娅因工作原因受命对这则故事进行挖掘。在采访的过程中她不仅发现了当年掩盖的真相，同时也发现了自己与萨拉一家千丝万缕却又好似命中注定的联系。©豆瓣', '克里斯汀·斯科特·托马斯', '吉勒·巴盖特-布赫内', 8.1, 8199, 'tt1668200', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1295517142.jpg', 0.2, 1.2, 19.8, 53.4, 25.5, '0.394039,0.122919,-0.756336,0.530481,-0.160630,-0.165257,0.881774,-0.128415,-0.672041,-0.294381,0.241268,0.718123,-0.048580,0.314796,0.256977,0.025822,-0.485858,-0.735688,-0.108499,-0.273545,-0.432157,-0.491507,-0.378850,-0.033030,0.043845,-0.561732,0.538601,0.270957,-0.069337,0.371988,0.091781,0.255102,-0.240517,0.546677,0.012745,0.046526,0.037977,-0.004355,-0.167921,0.333386,0.008363,-0.532458,-0.278863,0.282313,0.094298,0.515106,0.752984,-0.297716,-0.008954,0.133205,0.266707,-0.184713,-0.058314,0.188741,0.241135,-0.000780,0.045009,0.347100,-0.335889,0.142181,0.073812,-0.056218,-0.800243,0.000847,0.149006,0.163297,-0.715817,0.526308,-0.175849,0.153406,0.155530,-0.492961,0.313003,0.578921,0.081496,0.525011,-0.321056,0.080553,-0.631868,0.056616,0.578425,-0.253555,0.016923,0.315532,-0.069569,-0.347477,0.036257,0.024088,-0.450219,-0.114136,0.334527,0.117354,-0.294425,0.239538,-0.631387,-0.077207,-0.353162,-0.436044,0.089555,-0.331906,-0.030171,-0.630340,-0.157686,-0.278183,-0.205545,0.016863,0.018824,-0.294917,0.568420,-0.762008,0.286773,0.657078,0.218983,-0.385379,0.558721,0.028545,0.249729,-0.129466,-0.146383,0.354340,0.144351,0.488379,0.040421,0.306624,0.038252,-0.335323,-0.657646,0.545855', '1947080', '21619567', '3285642', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4883425', '花', '剧情', '一段绽放在北京的中法恋情凋谢后，花（任洁 饰）决定辞去在北京当老师的工作，前往巴黎寻回男友，但终究还是没能令其回心转意。在陌生的城市游荡，迷路的花偶遇了一位法国蓝领马修（塔哈·拉希姆 Tahar Rahim 饰），马修即刻向这位中国姑娘大放殷勤，并暴力地占有了她，而绝望的花也误打误撞地对马修萌生了情愫。虽然马修疯狂地爱着花，但他和他的朋友们却似乎一直把花当婊子看待，两人之间的裂缝渐渐判若鸿沟。在巴黎浑浑噩噩的度日以及与马修间的爱怨龃龉让花开始想家，她开始探寻，在性与爱之间，自由与乡愁之间，自己究竟想要的是什么……本片根据旅居巴黎的中国女作家刘捷的同名长篇小说改编。©豆瓣', '塔哈·拉希姆', '娄烨', 6.9, 21371, 'tt1650831', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1585749106.jpg', 2.1, 8.2, 43.3, 35.8, 10.6, '0.270180,0.128376,-0.704973,0.618819,0.055169,-0.518865,0.648928,-0.006213,-0.285075,-0.114146,-0.032381,0.796383,-0.297046,0.346459,0.190940,0.060132,-0.243848,-0.836021,-0.049470,-0.273852,-0.137730,-0.456611,-0.286003,-0.143850,-0.159655,0.072002,0.655103,0.253056,-0.084713,0.523775,0.361827,0.125957,-0.086167,0.518224,-0.319561,-0.050835,-0.067427,0.269304,-0.368991,0.055043,0.248633,-0.325701,-0.387295,-0.095859,0.121809,0.350438,0.703262,-0.170070,-0.074793,0.107857,0.225122,-0.129435,0.157651,0.037806,0.104647,0.075086,0.012546,-0.072016,-0.294939,0.021662,0.041270,-0.091208,-0.422411,0.082846,0.142824,0.057113,-0.714505,0.514582,0.087050,-0.114035,0.127208,-0.345285,0.074531,0.457009,0.106812,0.448454,-0.175229,0.007165,-0.404058,0.182899,0.459632,0.164006,-0.374443,0.482408,-0.336516,-0.422406,-0.111822,0.083211,-0.356525,-0.237280,0.323418,0.021036,-0.159632,0.342516,-0.893861,-0.169337,-0.139867,-0.082627,-0.012683,-0.570556,-0.066717,-0.374172,-0.163661,-0.566467,-0.116318,-0.014055,0.286715,0.007481,0.686907,-0.845673,0.339965,0.603619,0.209477,-0.578920,0.564955,0.304956,-0.164887,-0.150451,-0.267148,0.401223,-0.080874,0.382299,0.216912,0.351060,-0.036215,0.098616,-0.625780,0.445980', '21360412', '3155839', '1414808', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4885995', '了不起的亡灵', '喜剧', '一场风流案件，导致性感妇人铃子（竹内結子 饰）死亡，他的丈夫矢部五郎（KAN 饰）作为杀人凶手遭到指控。菜鸟律师宝生绘美（深津絵里 饰）受命担任五郎的辩护律师，五郎提供的不在场证明竟是案发当夜被鬼压。虽然匪夷所思，宝生还是独自前往那座诡异的山庄，结果真的见到了压了五郎的 武士幽灵——后北条氏家臣更科六兵卫（西田敏行 饰）。六兵卫生前忠心耿耿，却被诬陷勾结敌人而遭斩首。因为对五郎的遭遇深有同感，六兵卫同意和宝生出庭作证。为了让那个别人完全看不到的幽灵到场，宝生真是绞尽脑汁，煞费苦心。在她的努力下，史无前例的幽灵庭审拉开序幕……©豆瓣', '深津绘里', '三谷幸喜', 7.7, 24438, 'tt1677603', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2328523501.jpg', 0.6, 3, 28.2, 48.8, 19.4, '0.172306,-0.099996,-0.480430,0.273439,-0.239535,-0.020871,0.589375,0.116177,-0.513253,-0.540153,0.648302,0.499014,-0.135550,-0.021734,0.042172,-0.137364,-0.093540,-0.503662,-0.096767,-0.063934,0.020633,-0.495107,0.077093,-0.004856,-0.078740,0.009432,0.391121,0.038645,-0.069914,0.478237,0.222668,0.629029,-0.202098,0.179249,0.095480,0.205504,0.140367,0.030692,-0.124308,0.244149,-0.064440,-0.162252,-0.039463,0.193380,-0.150370,0.383128,0.556824,-0.534390,-0.280435,-0.414272,0.242583,-0.412851,-0.036143,0.595901,0.395519,0.047410,0.174356,0.369817,-0.164514,-0.145509,0.095259,0.282628,-0.661657,0.138203,0.359368,0.113378,-0.381727,0.226597,-0.145152,0.003784,0.104763,-0.216616,0.146254,0.133039,0.480773,0.109228,-0.329718,0.226049,-0.314967,0.136844,0.637436,0.041362,0.194076,-0.003465,0.017501,-0.249128,0.271307,-0.271375,-0.294256,0.265293,-0.032731,-0.081552,0.166148,0.075930,-0.429727,-0.265816,-0.329390,0.110650,-0.112973,-0.252458,-0.276304,-0.407569,0.013358,-0.336658,-0.350658,0.274325,0.124969,-0.285712,0.368373,-0.629207,0.005634,0.467418,0.408418,-0.378349,0.221249,0.146953,0.008497,-0.038144,-0.157166,-0.171703,0.257532,0.458732,0.337547,0.166140,-0.079148,-0.358027,-0.173338,0.060883', '2988294', '1301022', '35030151', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4886302', '名侦探柯南OVA10：怪盗基德孤岛决战', '动画', '在距离东京南部一千公里的小宅岛上，一家豪华酒店将迎来开业一周年的庆典，届时会场将展出名贵的钻石阿缇密斯之泪。理所当然，这颗钻石吸引了怪盗基德的注意，他再次发出盗窃预告。虽然中森警部作了周密部署，却依然防不胜防，阿缇密斯之泪最终失窃。与此同时，柯南、小兰等人也受铃木园子之邀参加了酒店的周年庆典。中森警部的出现引起柯南警觉，他继而发现基德的计划。狡猾的基德接连逃脱中森警部和柯南的围阻，不过却在少年侦探三人组元太、步美、光彦的面前大失身手，还暴露了真容，不过却被步美他们认作新一。另一方面，丢失了钻石的酒店方似乎另有企图……©豆瓣', '高山南', '儿玉兼嗣', 8, 7524, '怪盗基德 陷阱之岛', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2509378691.jpg', 0.3, 1.6, 23.2, 45.4, 29.6, '0.370618,0.391012,-0.649318,0.173016,0.215047,-0.197827,0.647211,0.013058,-0.025094,-0.123629,0.354907,0.431192,-0.524600,-0.018497,0.184499,0.069245,-0.315561,-0.477633,-0.210157,-0.388406,-0.102963,-0.079783,-0.337872,0.159923,-0.038769,-0.147943,0.267136,0.425272,-0.062453,0.667354,0.259373,0.125172,-0.033079,0.515601,0.310382,-0.012056,0.270514,-0.114527,0.074968,0.244008,-0.043817,-0.399475,-0.061872,0.247002,0.315398,0.462686,0.726197,-0.282654,-0.118756,-0.164851,0.230150,-0.226229,-0.019876,0.039488,0.472768,-0.095923,-0.169836,-0.031836,-0.475403,-0.026424,0.348326,-0.014577,-0.471150,0.208339,0.197668,0.117356,-0.242462,0.169820,-0.168601,-0.037567,0.073230,-0.244421,0.237572,0.246347,0.381671,-0.100555,-0.111791,0.137120,-0.342460,0.083744,0.393225,-0.265291,-0.042829,-0.062939,-0.081510,-0.731756,0.062037,0.016907,-0.031453,0.117623,0.433155,-0.060294,0.083058,0.188516,-0.558567,-0.147133,-0.435111,-0.302689,-0.243351,-0.300428,-0.220512,-0.852694,-0.027250,-0.165250,-0.178103,0.007486,0.025381,-0.066508,0.383889,-0.529836,0.061560,0.622762,0.411912,0.155708,0.270443,-0.071037,-0.003789,0.047364,-0.277862,0.018672,0.185488,0.448778,0.184842,0.395318,0.035062,-0.488030,-0.403206,0.337997', '2159244', '3735015', '21349734', '2357711');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4888853', '商海通牒', '剧情', '2008年经济危机爆发时，华尔街一家投资银行的分析师皮特·苏利文（扎克瑞·昆图 Zachary Quinto 饰）发现公司的财产评估有着巨大的漏洞，即将导致银行的破产。公司高层连夜开会希望挽救公司。富有经验的股票经纪人山姆·罗吉斯（凯文·史派西 Kevin Spacey 饰）、证券经纪人贾德·科恩（西蒙·贝克 Simon Baker 饰）、金融危机分析师萨拉·罗伯特森（黛米·摩尔 Demi Moore 饰）、老总约翰·图尔德（杰瑞米·艾恩斯 Jeremy Irons 饰）都来到了会议现场。会议决定，银行要以极低的价格抛售债权和股票。但此一举虽能使银行能得到暂时的安稳，但却会引发一系列连锁反应.......©豆瓣', '凯文·史派西', 'J·C·尚多尔', 7.9, 50996, 'tt1615147', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1119800463.jpg', 0.3, 1.8, 23.4, 51.9, 22.6, '-0.157777,0.159441,-0.421040,0.086749,0.659279,-0.414827,0.028135,0.637932,-0.399397,-0.434046,0.229752,0.541166,-0.243565,0.068251,0.425628,0.029274,-0.477822,-0.439895,0.043524,-0.170939,0.175500,-0.664432,-0.134975,-0.430788,-0.034429,-0.278401,0.297315,0.168053,-0.222755,0.204958,0.199083,0.496194,0.112752,0.241270,0.605564,-0.163747,0.482018,-0.298389,-0.584106,0.279842,0.158398,0.233820,-0.085397,0.138596,0.568571,0.280654,0.134802,-0.023974,0.181693,-0.095586,0.430550,0.065278,0.282785,-0.244125,0.384493,-0.031721,0.156901,0.394494,-0.535789,-0.148064,0.349303,-0.198380,-0.681541,0.012338,-0.116350,0.410370,-0.504461,0.150465,-0.477547,0.346762,-0.101809,-0.211929,-0.268483,0.596621,0.381078,0.029487,0.258362,0.090250,-0.603089,0.039491,0.094198,-0.071269,-0.315386,0.163819,-0.353749,-0.449778,-0.355411,-0.192710,-0.163129,-0.005261,0.519716,-0.007603,0.292969,0.445488,-0.476061,-0.354712,-0.429567,-0.514221,-0.004863,0.068871,0.055177,-0.938850,-0.131540,0.229206,0.097364,-0.071136,0.017793,0.166220,0.316246,-0.510511,-0.016526,0.612522,0.481804,-0.234389,0.270513,-0.507680,0.157816,-0.412110,-0.357674,-0.139994,0.225215,0.096063,0.061844,-0.233214,0.237015,-0.797051,0.338221,0.028289', '3003137', '1293572', '1439286', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4889554', '暮光之城4：破晓(下)', '剧情', '在远离喧嚣的崇山峻岭之中，原始密林中央，贝拉（克里斯汀·斯图尔特Kristen Stewart 饰）与爱人爱德华（罗伯特·帕丁森 Robert Pattinson 饰）以及友人们展开难得的幸福生活。贝拉正在学习控制体内躁动的吸血鬼欲望，因为她即将面对那个她和爱人共同孕育出来的小生命蕾妮斯梅。一切都得到修复与改善，小女孩在父母长辈的呵护下快乐成长。但是她们离群索居的秘密最终被艾瑞娜（玛姬·格蕾斯 Margaret Grace 饰）窥见。传说吸血鬼孩童因心智不成熟容易带来难以预料的灾难，因此必须被族人残酷抹杀。听取了艾瑞娜的报告，远在意大利的沃尔图里家族渐次逼近。贝拉坚信女儿绝非血族，云集世界各地的库仑家族与狼族相继云集密林木屋，一场史无前例的战争即将展开……©豆瓣', '克里斯汀·斯图尔特', '比尔·康顿', 7.2, 165269, 'tt1673434', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1725916674.jpg', 2.3, 8.1, 37, 32.5, 20, '0.154653,0.246358,-0.766497,0.466170,0.080372,0.016458,0.831079,0.046077,-0.205898,-0.202711,0.219465,0.547849,0.043402,0.193101,0.198789,-0.083714,-0.408568,-0.526274,-0.115288,0.120567,-0.236461,-0.343913,-0.360582,-0.237477,-0.140308,-0.609264,0.777034,0.247787,-0.125241,0.324955,-0.071379,0.474823,-0.294405,0.149409,0.046236,-0.057200,0.171885,-0.084308,-0.560145,-0.027098,-0.152167,-0.047759,-0.109659,0.384530,0.035826,0.180985,0.776960,-0.653741,0.060910,-0.277396,0.270933,-0.243652,0.133128,0.234186,0.145252,-0.206226,0.201439,0.192264,-0.045984,-0.129621,-0.135257,-0.232191,-0.688559,0.022360,0.277402,0.139884,-0.330051,0.273382,0.260930,-0.025688,0.336328,-0.145760,-0.017393,0.458002,0.163292,0.297835,-0.262154,-0.062656,-0.490536,-0.148650,0.698151,-0.149982,-0.323912,0.178723,-0.479840,-0.462528,-0.092491,-0.328204,-0.740283,-0.125837,0.462550,0.164179,-0.070388,0.825068,-0.428329,-0.073147,-0.386532,-0.278777,0.290742,-0.346653,-0.200511,-0.700503,-0.230541,-0.251330,-0.220605,-0.023688,-0.031340,-0.225084,0.905755,-0.692711,0.483543,0.584897,0.163106,-0.423523,0.411597,-0.274572,0.380622,-0.294877,-0.159977,0.815764,0.152104,0.082015,0.040392,-0.012043,-0.125813,0.355737,-0.327820,0.535046', '10533913', '10746430', '26667010', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4892342', '蔡李佛拳', '喜剧', '热爱武术的青年陈国成（王宝强 饰）从小在美国长大，他一度夺得大学校际拳击冠军。为了取得更高成就，他毅然返回家乡广东新会。谁知刚刚踏上祖国的土地，便遭遇接二连三的倒霉事，先是被人骗去手机，接着又因误会被少女晶晶和其师兄藏龙臭揍一顿，之后更是丢掉所有行李。另一方面，国成的老爹陈皮（吴孟达 饰）是蔡李佛拳的掌门人，他一心忙于生意，于是希望接这一机会将掌门之位传给儿子。谁知管家藏洞阴差阳错接回来一个黑人，结果闹出一连串的笑话。此时彷徨街头、无所依靠的国成又再次邂逅晶晶。经过一番解释，所有误会烟消云散。他也开始了新的武术人生……©豆瓣', '王宝强', '程东', 3.5, 3065, 'tt2472668', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p980935884.jpg', 49, 33.7, 13.5, 1.9, 1.8, '-0.091384,0.209583,-0.610697,0.453849,-0.050355,-0.558641,0.178644,0.000893,-0.424550,-0.179258,0.000517,0.837555,-0.111337,0.209552,0.341615,-0.028474,-0.119419,-0.596593,0.167780,-0.126481,-0.020657,-0.146453,0.039885,0.013527,-0.056170,-0.144730,0.393047,-0.162620,-0.406210,0.502129,0.287527,0.191975,0.065229,0.303977,-0.212161,0.526426,-0.046568,0.004841,-0.378001,0.088155,0.116209,-0.327386,-0.181507,0.141733,-0.046116,0.113587,0.588093,0.183994,-0.109015,-0.378131,0.369762,-0.120058,-0.169774,-0.091524,0.280849,0.145496,0.257054,0.179321,-0.220205,0.003253,0.303610,-0.170362,-0.229911,0.144148,0.100684,-0.134482,-0.486020,0.424674,0.071268,0.047217,0.029837,-0.316104,0.164520,0.450391,0.294938,0.294044,-0.170263,0.131817,-0.300727,0.339563,0.724968,-0.265733,0.344017,0.242550,0.305629,-0.046704,0.538801,-0.327950,-0.208114,0.110581,0.674762,0.018262,-0.188219,0.231520,-0.325149,-0.073383,-0.403619,-0.139140,0.290245,-0.339661,-0.044148,-0.140504,0.075408,0.068069,-0.297045,-0.113473,0.042609,-0.150825,0.627018,-0.706735,0.072055,0.214357,0.100724,-0.419983,0.220033,0.086914,0.256265,-0.079744,-0.041147,-0.104488,0.159299,0.567422,-0.055056,0.180665,-0.002591,-0.305944,-0.105288,0.169561', '1292219', '30345227', '1309069', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4894072', '刺痛我', '动画', '刚刚毕业的大学生张小军，工作刚满一年公司就倒闭了。在全球经融危机的大环境下，他只能混入失业的大部队，悲催地游荡在南京街头。他被超市保安误认为是小偷而遭受一顿毒打，又好心帮助一位老人却被无辜冤枉。此时的小军心中最大的愿望，就是能够回到农村当一位农民。相较于失魂落魄的小军，大洪显然是一个摸爬滚打也死不回头的主儿。两人意外的陷入一场权钱交易的凶杀风波，可这不义之财却没有给他们丁点儿希望。导演刘健“三年磨一剑”，集导演、编剧、原画、动画等工作于一身，被誉为中国“第一部黑色动画长片”。本部动画短片入选第50届昂西动画节最佳动画长片奖竞赛单元，并荣获多项国内外大奖。©豆瓣', '何烈波', '刘健', 7.8, 12147, 'tt1814830', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2497773924.jpg', 0.3, 2.4, 25, 51.2, 21.1, '-0.163140,-0.139564,-0.548732,0.351276,0.107268,-0.426049,0.578923,0.143649,-0.393705,-0.292362,0.194081,0.810037,-0.431488,0.191331,-0.018381,-0.194278,-0.163259,-0.454738,-0.230841,-0.122466,0.048348,0.022168,-0.261539,0.012804,-0.130245,-0.002846,0.812399,0.238343,-0.300480,0.297345,0.553514,0.200540,0.102638,0.277084,-0.121526,0.048866,0.283309,0.006070,-0.148754,0.290111,-0.137950,-0.384683,-0.329157,-0.053404,0.241500,0.090473,0.680864,0.100974,-0.294674,-0.002646,0.632091,-0.378809,-0.376994,-0.094452,0.459455,-0.139458,0.372745,-0.027014,-0.027988,0.282372,-0.021957,-0.281540,-0.733445,0.012629,-0.019632,0.034902,-0.584950,0.560411,-0.067671,-0.028921,-0.138488,-0.103318,0.195454,0.263687,0.408856,0.541491,-0.034207,0.183965,-0.498914,0.489722,0.536568,0.026275,-0.295496,0.393050,-0.174506,-0.514908,-0.056158,-0.372594,-0.376214,0.330636,0.381238,-0.320271,-0.181304,0.113834,-0.281775,0.179777,-0.180872,-0.459654,-0.115541,-0.116374,-0.232066,-0.578609,0.086619,-0.048776,-0.214810,0.198208,0.345138,-0.184467,0.604910,-0.513967,0.168134,0.479610,0.135700,-0.442796,0.603353,0.246371,0.063724,-0.127184,-0.234334,-0.058722,-0.120545,0.452221,0.167501,0.180057,-0.090760,-0.559648,-0.159548,0.268101', '25880986', '1908036', '27602116', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4894074', '午夜心跳', '恐怖', '妻子夏雪（刘雨鑫 饰）罹患癌症，致令某医院心脏外科专家顾振生（任达华 饰）备受打击，在巨大压力下，经他手术的病人不幸身亡。顾从此一蹶不振，精神恍惚，时常能看到诡异和恐怖的景象。与之类似，夏雪的妹妹夏晓雨（杨渝渝 饰）近一段时间也被噩梦所困扰，精神几近崩溃。为了带晓雨走出阴影，顾拜托同事——精神科医生麦翔昱（吴镇宇 饰） 为其治疗。麦为人圆滑自私，此前曾与女护士吴心遥（姚笛 饰）相恋，为攀援富贵转而追求院长的女儿温淼（李念 饰）。是时，314病房闹鬼的传闻甚嚣尘上，在鬼怪的阴影下，古老的背叛与忠贞的故事慢慢上演……本片由旅日导演张加贝执导。©豆瓣', '任达华', '张加贝', 3.3, 6478, 'tt1997606', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p696812016.jpg', 52.9, 32, 12.4, 1.4, 1.3, '-0.231995,-0.116665,-0.302996,0.205976,0.138663,-0.083719,0.960686,0.374089,-0.779883,-0.506556,0.300582,0.363865,-0.406099,0.331269,0.217678,-0.175297,-0.066981,-0.564650,-0.155858,0.147687,-0.332728,-0.139079,-0.228821,-0.423223,-0.031230,-0.460478,0.370422,0.283650,-0.342863,0.194385,0.107339,0.563261,-0.361893,0.242142,-0.031403,0.035281,-0.166412,0.178565,-0.621583,-0.143335,0.303907,-0.380342,-0.055421,0.063348,-0.180433,0.034141,0.619712,-0.088787,-0.421772,-0.256738,0.534058,-0.011597,0.001141,0.102105,0.139203,0.252267,0.597483,0.043127,-0.120822,-0.027840,0.151794,-0.072552,-0.442981,-0.004490,0.224665,0.259541,-0.382290,0.456358,-0.208747,-0.030367,0.148593,-0.094819,0.052876,0.156911,0.293330,0.468890,-0.249037,0.158278,-0.116469,0.510437,0.466065,0.214845,-0.153471,0.310343,-0.335669,-0.536049,0.098981,-0.134335,-0.494687,0.207973,0.235896,-0.166482,0.001664,0.331115,-0.190547,-0.293528,-0.199808,0.158316,-0.282127,-0.157965,0.029822,-0.358416,-0.045947,-0.103125,-0.082725,0.144712,-0.058865,-0.193018,0.542187,-0.564559,0.450985,0.080540,0.248990,-0.460664,0.501291,-0.077143,0.034139,-0.168715,-0.007303,0.551730,-0.151080,0.411897,0.151882,0.093191,-0.089933,0.056563,-0.396942,0.127594', '30257386', '1292528', '10508879', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4894075', '密室之不可告人', '悬疑', '三年前，东安俱乐部的会员Mike（袁成杰 饰）在攀岩时意外身亡，设备负责人林小玉因此自杀。该事件闹得满城风雨，悬疑小说作家柳飞云（苏有朋 饰）以此为题材写出新作，但是反响平平。三年后，正处于创作低谷的柳和经纪人李晓峰（胡明 饰）参加了一个豪华旅游团。夜幕降临，他们醒来却发现，车被开到偏远荒芜的山区，车上的人也大多数不知踪影。柳和李以及大书商卓然（杜俊泽 饰）、卓然妻子张惠（吴佩慈 饰）、小说枪手白秀清（史光辉 饰）、建筑设计师段新宇（刘小溪 饰）、画家林泉（林龙麒 饰）及妻子林梅（杨潇 饰）被安排在一幢位于山间的豪华别墅内休息。深更半夜，卓然却突然失踪，一时间人心惶惶，神秘事件接连发生……©豆瓣', '苏有朋', '张番番', 5.7, 17746, 'tt1764492', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2200292065.jpg', 7, 22.3, 50.4, 16.9, 3.3, '0.113337,0.142866,-0.556019,0.295809,0.529813,-0.151767,0.553949,0.127392,-0.746526,-0.723504,0.218540,0.295739,-0.568531,0.377314,0.325307,-0.143451,-0.221371,-0.461516,0.047106,-0.153635,-0.238761,-0.296748,-0.076703,-0.277121,0.011304,0.190672,0.470286,0.165149,-0.163001,0.594779,0.129066,0.151624,-0.266110,0.269822,0.245449,0.245194,0.339905,0.124941,-0.221316,0.082259,-0.213302,-0.522476,-0.096326,-0.167354,0.315999,0.161125,0.674247,0.062716,-0.290240,0.262039,0.570802,0.057143,-0.003636,-0.055046,0.442994,-0.118046,0.266191,-0.058394,-0.258491,-0.029056,0.056272,-0.165926,-0.023618,0.190944,0.153819,0.066407,-0.421254,0.431814,-0.267129,-0.121811,-0.051291,-0.373071,0.306333,-0.019692,0.337558,0.368312,0.153792,0.196329,-0.457364,0.455101,0.279358,0.244018,0.052344,0.143818,-0.019483,-0.538531,-0.214212,-0.032053,-0.200734,0.149590,0.478581,-0.275094,0.275216,-0.124215,-0.239154,-0.086697,-0.015537,-0.044382,-0.186233,0.101719,-0.414409,-0.750379,0.147302,-0.190849,0.051693,0.120119,-0.104459,-0.104939,0.340099,-0.565296,0.152041,-0.027062,-0.124381,-0.493592,0.504639,-0.356703,0.225015,0.020043,0.021085,0.123422,-0.060634,0.300864,0.164755,0.197322,-0.372633,-0.359034,-0.258665,-0.097955', '1465415', '1292894', '7152895', '1292272');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4896263', '将爱情进行到底', '剧情', '本片分三个章节，分别展现了杨峥（李亚鹏 饰）与文慧（徐静蕾 饰）在12年后的别样生活。第一章：杨峥与文慧在北京结婚多年，虽然物质生活已经让杨峥兑现了对文慧的承诺，但是精神方面却渐行渐远。终于在一次聚会后，杨峥第一次离家出走……第二章：大家在上海组织同学聚会，主办者分别邀请了汽车修理工杨峥和售货员文慧。前者正在与前妻闹离婚，而后者也是单独抚养一对双胞胎儿子。在聚会上，他们在同学们的怂恿下，又一次走进了对方……第三章：深夜里，杨峥接到了文慧的越洋电话。她在电话里哭着唱生日歌，令杨峥下定决心来法国找他。然而，在波尔多车站，杨峥才赫然发现文慧来接的不是自己，而是一个年轻的女孩，他们在葡萄庄园里享受美酒，但是杨峥却逐渐发现了文慧痛苦的根源……本片是1998年电视剧版的电影版续集，由原班人马打造。王菲、陈奕迅倾情献歌《因为爱情》。©豆瓣', '徐静蕾', '张一白', 6.5, 196475, 'tt1753976', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p797834801.jpg', 3.1, 12.4, 47, 29.4, 8.1, '0.067146,-0.085746,-0.698563,0.518675,-0.036745,-0.440558,0.691154,0.102531,-0.356048,-0.074529,0.035189,0.851600,-0.300058,0.549881,0.255265,-0.097711,-0.192027,-0.669790,0.181928,-0.130158,-0.193670,-0.343731,0.082116,-0.162943,0.002013,-0.077625,0.421344,-0.097259,0.047523,0.574773,0.392636,-0.083642,-0.307288,0.461100,-0.101087,-0.039970,0.185805,0.277221,-0.290456,0.323486,0.184319,-0.477026,-0.379578,0.146318,0.197000,0.346148,0.653300,-0.077904,-0.135496,0.177536,0.295074,-0.199913,-0.239764,-0.047108,0.277144,0.114721,0.378822,0.274714,-0.219866,-0.016744,-0.174590,-0.222079,-0.332149,0.150705,-0.058835,0.034220,-0.612008,0.803753,-0.129062,-0.088756,0.111534,-0.350549,0.406111,0.292612,0.121459,0.494816,-0.324010,-0.097234,-0.311166,0.334788,0.545554,0.120294,0.003312,0.531626,-0.047957,-0.349553,-0.038116,0.132966,-0.465369,0.166657,0.340376,-0.031281,-0.242700,-0.058374,-0.694878,-0.098004,-0.108257,-0.171071,0.135149,-0.410393,-0.054098,-0.739116,-0.241392,-0.407449,-0.207023,0.126280,0.060679,-0.148186,0.764497,-0.812175,0.254631,0.384726,0.210947,-0.636150,0.713550,0.239191,0.026156,-0.146973,0.223358,0.022930,-0.250074,0.092986,0.240957,0.313739,-0.163619,-0.002094,-0.505376,0.359929', '1292219', '3811356', '3041753', 