INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4896304', '龙门飞甲', '剧情', '明朝成化年间，朝纲腐败，奸邪当道。西厂东厂为宦官把持，混淆黑白，陷害忠良，朝野内外噤若寒蝉。时有赵怀安（李连杰 饰）等流亡剑客挺身而出，接连铲除东厂数名奸佞，致令阉贼胆战心惊。适值此时，风头正劲的西厂督主雨化田（陈坤 饰）出面干预。另一方面，宫女素慧容（范晓萱 饰）怀有身孕，绝命奔逃。被雨化田的爪牙追捕途中幸得神秘侠客凌雁秋（周迅 饰）相救。二人一路辗转逃往关外，来到曾经引起过腥风血雨的龙门客栈落脚。龙门客栈一如往昔，为凶险异常之所在。雨化田手下追赶至此，与先前而至的鞑靼商队剑拔弩张，关键时刻更有与雨化田长相极其相似的卜仓舟（陈坤 饰）与女侠客顾少棠（李宇春 饰）投宿客栈。不久，赵怀安一众也偷偷潜至龙门。各方势力云集于此，新的正邪之战即将展开，更有天大的秘密即将揭开……©豆瓣', '李连杰', '徐克', 6.8, 288921, 'tt1686784', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1311653469.jpg', 1.8, 8.6, 45.5, 33.8, 10.3, '-0.064026,-0.088921,-0.538833,0.312033,0.384749,0.111943,0.473377,0.334724,-0.744900,-0.419711,0.159314,0.179759,-0.283819,-0.033343,0.275811,-0.606760,0.105852,-0.548932,-0.304366,-0.155631,0.030400,0.056858,-0.317412,-0.122126,-0.599700,-0.054695,0.424004,0.448908,-0.166157,0.565937,0.478589,0.489479,-0.634122,0.424497,-0.071365,-0.027149,-0.003829,-0.039550,-0.504748,-0.173360,-0.328443,-0.682368,-0.387765,-0.042368,-0.180490,0.257035,0.391030,-0.310078,-0.016529,-0.335669,0.194720,-0.025758,-0.040354,0.182905,0.497326,0.019683,0.075827,0.208010,0.006577,0.015256,-0.149715,0.053194,-0.222262,0.113462,0.476154,0.061234,-0.228281,-0.123314,-0.072442,-0.015611,-0.097736,-0.339979,0.134684,0.423455,0.169096,-0.222233,0.162862,-0.108323,-0.588500,0.261294,0.527521,0.011075,0.196239,-0.335738,0.399126,-0.345522,0.281193,-0.148053,-0.182377,-0.014049,0.390127,-0.182539,0.357345,0.291752,-0.314076,-0.041860,-0.302280,0.353279,0.061151,0.056550,0.044449,-0.687746,-0.125983,-0.326928,-0.174082,0.250965,0.324252,0.237451,0.324785,-0.435639,0.148654,0.074679,0.288022,-0.706580,0.111158,-0.076667,0.485055,0.030817,-0.275796,0.068886,0.455702,0.200522,-0.132989,0.030024,-0.490421,-0.385579,-0.139898,-0.016798', '26826398', '5422105', '1306490', '1292287');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4896305', '辛亥革命', '剧情', '19世纪末20世纪初，清王朝三百年江山气数将近，内忧外患，时局动荡，正是乱世之际，英雄辈出，中华民族面临着重大的历史变革。以孙中山（赵文瑄 饰）为首的仁人志士意识到只有民主共和才能救中国，他们组成一个个革命政党，旨在推翻满清政府，建立人民当家作主的民主国家。在这一过程中，无数革命者流血牺牲，但是更多的革命家站出来与落后的封建体制作斗争，终于在武昌打响了辛亥革命的第一枪。在此期间，黄兴（成龙 饰）、黎元洪（姜武 饰）、隆裕太后（陈冲 饰）、袁世凯（孙淳 饰）、汪精卫（余少群 饰）、宋教仁（邢桂栋 饰）、秋瑾（宁静 饰）等各方人物你方唱罢我登场，谱写了中国近代史上最为辉煌的篇章……©豆瓣', '赵文瑄', '张黎', 6.5, 46765, 'tt1772230', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1240455745.jpg', 2.6, 11.4, 51.6, 25.3, 9, '-0.081157,0.245347,-0.672771,0.345444,0.338146,-0.153536,0.201642,0.177095,-0.361817,-0.122349,0.303425,0.581222,0.032979,-0.177943,0.381131,-0.241065,-0.402034,-0.708019,-0.095084,0.115002,-0.047927,-0.234120,-0.263621,-0.077400,-0.513387,0.130054,0.914961,0.464652,-0.225487,0.279828,0.339758,0.172431,0.196789,0.061069,-0.024642,-0.050959,0.061344,-0.185390,-0.690178,-0.186630,-0.283920,-0.466972,-0.411636,0.273989,-0.435982,-0.179905,0.203439,-0.561825,0.355924,-0.321000,0.674565,-0.185575,-0.605942,0.025985,0.372513,0.187448,0.095035,0.511225,0.202107,0.017573,-0.182573,-0.218380,-0.426949,-0.067829,-0.005107,0.409496,-0.267330,0.727668,0.018746,-0.066196,-0.035914,-0.236231,0.242015,0.733232,0.279717,0.445804,-0.216382,-0.098698,-0.545815,0.533915,0.339076,-0.099205,-0.410626,0.011233,-0.133787,-0.415081,-0.050962,-0.333803,-0.036093,-0.433197,0.125352,-0.475890,0.190430,0.461513,-0.802549,0.075742,-0.070620,-0.177299,0.452686,0.107862,0.019451,-0.230554,-0.495812,-0.551614,-0.258038,0.286396,0.088608,-0.066190,1.028199,-0.510784,-0.154953,0.070435,0.015941,-0.371041,0.470460,0.231966,0.093927,-0.216463,-0.093292,0.321258,-0.348877,0.233936,-0.330147,0.032124,-0.107611,-0.181158,0.027999,0.239452', '27602116', '1461370', '1424552', '1780122');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4896894', '斯托克', '剧情', '恬静娴淑的女孩印蒂雅·斯托克（米娅·华希科沃斯卡 Mia Wasikowska 饰）18岁生日之际，惊闻父亲理查德（德蒙特·莫罗尼 Dermot Mulroney 饰）死于意外的噩耗。相对于和丈夫一向不睦的母亲伊芙琳（妮可·基德曼 Nicole Kidman 饰），从小 和父亲一起打猎的印蒂雅自然承受难以排遣的哀伤与痛苦。葬礼当天，一名有着和善笑容却周身散发阴冷气息的男子毫无征兆出现在斯托克母女身边。他是理查德的弟弟查理（马修·古迪 Matthew Goode 饰），自称刚刚结束环球旅行赶来。伊芙琳对查理表现出不加掩饰的热情和好感，并主动留查理在家中居住。而印蒂雅对这个突然到来的叔叔怀有深深的抗拒与戒备之心。紧张的气氛在这个刚刚失去男主人的家中蔓延，斯托克一家朝向万劫不复的深渊疾驰……©豆瓣', '米娅·华希科沃斯卡', '朴赞郁', 7.5, 79090, 'tt1682180', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1854982383.jpg', 1, 4.2, 31.2, 44.8, 18.9, '0.135558,-0.135839,-0.854028,0.491606,-0.221802,-0.298773,0.942434,0.369482,-0.522464,-0.432533,0.154678,0.976478,-0.237165,0.286257,0.379830,-0.109662,-0.321370,-0.523650,-0.269093,0.066285,0.067409,-0.442843,-0.136915,-0.145726,-0.081682,-0.528732,0.270974,-0.187670,-0.031778,1.193285,0.276865,0.656476,-0.241227,0.688393,0.149531,-0.254295,-0.037561,-0.100539,-0.278521,0.122449,0.100088,0.060592,-0.194414,0.222618,0.086117,0.494965,0.527567,-0.040950,-0.139155,-0.150749,0.124751,-0.035799,0.268209,0.278625,0.030818,-0.229711,0.133414,0.135789,-0.199452,-0.167766,0.115654,-0.237711,-0.527414,0.157328,0.076427,0.411396,-0.278455,0.413937,-0.294591,-0.292039,0.316026,-0.372579,0.117068,0.264965,-0.102503,0.554366,-0.222955,0.208668,-0.298812,-0.443554,0.338316,-0.088927,-0.231656,0.242010,-0.398605,-0.295928,0.139839,0.110559,-0.792804,-0.074145,0.147726,0.287672,0.150535,0.391383,-0.423048,-0.249324,-0.125657,0.055706,-0.049216,-0.341397,-0.223623,-0.570978,-0.331275,-0.588551,-0.384825,-0.129449,0.040705,0.108606,0.312294,-0.789283,0.634924,0.111318,0.304147,-0.224017,0.490276,0.156127,0.124571,-0.255390,-0.255304,0.731509,-0.013617,-0.167772,-0.010222,0.147978,-0.105200,0.162470,-0.295105,0.536072', '25723081', '3111650', '4817901', '1292812');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4897786', '超决战！贝利亚银河帝国', '动作', '奥特战士们的故乡——M78·星云“光之国”遭到神秘敌人的突然袭击，年轻战士赛罗奥特曼对自己的力量过于自信，一度陷入危机。在父亲赛文奥特曼的帮助下，赛罗奥特曼成功突围并消灭了敌人。为了弥补自己的草率，赛罗奥特曼只身一人担负起一探敌人真正身份的任务。他戴着父亲给予他的万能物品——赛罗手镯，向着未知的宇宙空间，独自踏上旅途。在经历艰苦的旅途后，赛罗奥特曼到达了一颗行星。在拯救遭遇巨型机器人兵团蹂躏的行星上的人们时，他和身负重伤、奄奄一息的青年“岚”以及他的弟弟“小治”相遇。赛罗奥特曼被岚的勇气所感动，与他合为一体，以岚作为人类形态，拯救了岚的生命。之后，通过与行星艾斯美拉鲁达的公主艾美拉娜的会面，赛罗奥特曼知晓了敌人的真正身份……操控谜一般的敌方军团的幕后黑手，是“银河皇帝贝利亚”！曾被奥特战士们齐心打倒的邪恶奥特战士贝利亚复活了！他构筑起强大的银河帝国，展开了称霸宇宙的征程！与岚一心同体的赛罗奥特曼，为了粉碎皇帝贝利亚的野心，和小治、艾美拉娜公主一同乘坐宇宙飞船——皇家宇宙船，穿梭于浩瀚的宇宙之中！等待着向贝利亚银河帝国发起挑战的赛罗奥特曼和他的伙伴们的将会是……？', '宫野真守', '阿部雄一', 7.6, 7137, 'tt1682376', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2230440190.jpg', 1.3, 5.2, 30.2, 36, 27.3, '0.093696,0.239032,-0.560609,0.569985,0.036304,0.037236,0.896851,-0.019938,-0.161562,-0.061369,0.476335,0.835879,0.067329,0.174148,0.378539,0.079608,-0.234209,-0.401738,-0.263294,0.259928,-0.290715,-0.437819,-0.490072,-0.252462,0.111387,-0.668317,1.015559,0.024391,-0.133338,0.097438,0.166714,0.385817,-0.260046,0.381348,-0.171824,0.128400,-0.036937,-0.208445,-0.403692,0.381522,-0.299141,-0.040588,-0.050218,0.647097,-0.401429,0.003036,0.795060,-0.790738,0.322961,-0.576446,0.304718,-0.440271,0.141288,0.064784,0.203011,-0.025374,-0.300809,-0.139390,0.378963,0.023633,0.146581,-0.160463,-0.986884,-0.308085,-0.036369,-0.006602,-0.666628,0.437498,-0.029396,0.249097,0.359843,-0.151552,0.161700,0.493984,0.108940,0.150141,-0.404459,0.099024,-0.350093,0.082649,0.728068,-0.136616,-0.554557,-0.000723,-0.130380,-0.501861,-0.331332,-0.414153,-0.577910,-0.161852,0.471379,0.117404,0.031991,0.549424,-0.797010,-0.057343,-0.344407,-0.286467,-0.030547,-0.372852,-0.010993,-0.501129,0.047272,-0.398630,-0.252401,0.178113,0.073685,-0.131837,0.774311,-0.834295,0.265478,0.780655,0.461790,-0.334721,0.564671,-0.183051,0.113129,-0.228280,0.095427,0.252874,0.051120,0.454502,0.240554,0.157224,-0.022497,0.249077,-0.280158,0.541141', '26759819', '26667010', '25774050', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4901335', '暮色大电影', '喜剧', '17岁的少女贝卡（珍·普罗斯克 Jenn Proske 饰）随着父亲来到了一个无论怎么看都十分诡异的小镇上学，在这里，她和儿时的玩伴雅各布（克里斯·里吉 Chris Riggi 饰）重逢了，这个进入青春期的大男孩处处透露出一股奇怪的气息。在学校，打扮老土的她成为了同学们欺负的对象。这时，面色苍白瞳孔金黄的大帅哥爱德华（马特·兰特尔 Matt Lanter 饰）出现在了她的面前，两人一见钟情眉来眼去。欲火焚身的贝卡向爱德华求欢却惨遭拒绝，原来爱德华是吸血鬼，归属于庞大的库伦家族，一方面，爱德华对贝卡有着强烈的爱意，而另一方面，他还必须忍受着存在于他基因里的嗜血的欲望。爱德华带贝卡去见自己的家人，聚会却被贝卡搅得一团糟。伤心的爱德华深知他只能带给贝卡带来灾难而忍痛提出分手，而雅各布在成为吉娃娃人之后也终于向贝卡袒露了自己的爱意，作为一个默默无闻的平凡少女，突然间被两大帅哥同时追求的她该做出怎样的选择？', '珍·普罗斯克', '贾森·弗莱德伯格', 6.2, 22900, 'tt1666186', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2626696134.jpg', 5.8, 17.2, 46.6, 21.7, 8.7, '0.398171,0.057962,-0.915707,0.622874,-0.211244,-0.328344,0.927624,0.072100,-0.484865,-0.231777,0.216756,0.944998,-0.276043,0.502498,0.218350,0.247918,-0.101182,-0.655192,-0.106568,-0.116126,-0.157397,-0.326710,-0.307597,-0.128274,0.014862,-0.229214,0.504599,-0.080844,-0.157216,0.358203,0.484912,0.440938,0.188707,0.588385,-0.040648,-0.154637,0.060007,-0.095778,0.020906,0.092982,0.126356,-0.175810,-0.146119,0.300697,-0.142179,0.365188,0.702615,-0.363575,-0.094237,-0.118724,0.471845,-0.246892,-0.072217,0.199307,0.067135,-0.181672,0.109312,-0.083183,-0.152462,-0.076889,0.131381,-0.010220,-0.650554,0.187533,-0.037987,0.388938,-0.562280,0.452997,0.109449,-0.233113,0.338895,-0.336949,-0.068607,0.143091,0.078850,0.407409,-0.367813,0.090698,-0.444727,-0.140577,0.699861,0.073212,-0.346723,0.214766,-0.572177,-0.337443,0.064669,-0.240468,-0.628434,-0.138836,0.291638,0.048377,-0.181958,0.364014,-0.565758,-0.209980,-0.300609,-0.036262,0.008848,-0.429850,-0.350572,-0.480126,-0.254695,-0.532080,-0.434869,0.154459,0.000948,-0.234295,0.624721,-0.898086,0.137630,0.519601,0.333714,-0.414857,0.580034,0.135415,-0.009353,-0.140174,-0.376435,0.493279,0.041629,0.103374,0.228520,0.315612,0.057886,0.214401,-0.279357,0.563281', '4275444', '1296534', '3111650', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4901684', '孩子们', '悬疑', '1991年3月26日，韩国大邱。就读于城西小学的5个男孩子结伴上山，从此一去不回。该事件引起轩然大波，虽然警方出动上万搜查人员，却始终一无所获，孩子们的下落成为一个难以破解的谜团。4年后的一天，风光无限的电视制作人姜志胜因涉嫌造假而被总部流放至偏远的大邱，孤高气傲的他发 现当地的人们依然关注那起已为很多人遗忘的“青蛙少年失踪案”。为了早日翻身，姜志胜与一直关注此案的黄教授携手，沉疴多年的案件似乎有了新的转机……本片改编自发生在1991年韩国大邱的真实案件，该案件被称为“青蛙少年失踪事件”，是韩国三大未解谜案之一，失踪少年的尸体于2002年发现。另外两起案件已被拍摄为影片《杀人回忆》和《那家伙的声音》。©豆瓣', '朴勇宇', '李揆万', 7.5, 28593, 'tt1861982', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p676382454.jpg', 0.4, 2.5, 33.6, 49.2, 14.4, '0.067412,-0.247436,-0.529247,0.198924,0.189132,0.035450,0.598523,-0.143508,-0.799928,-0.472949,0.091560,0.492718,-0.427871,0.322814,0.353301,-0.257195,-0.244434,-0.765540,0.098291,-0.393308,-0.317838,-0.168874,-0.372735,-0.379264,-0.068695,-0.088692,0.642025,0.471358,0.050638,0.434858,0.193803,0.425735,-0.372608,0.323998,-0.099227,-0.204219,0.064479,0.121026,-0.040443,0.204740,-0.313649,-0.591687,-0.277483,-0.163926,-0.143489,0.298947,0.827913,-0.039918,-0.282603,-0.226294,0.524349,-0.390500,-0.319838,-0.070409,0.706943,0.184045,0.062473,0.508656,-0.311522,-0.270968,-0.001767,-0.288234,-0.485044,0.011874,0.244773,0.401770,-0.332414,0.417304,-0.160651,0.126079,-0.109703,-0.274981,0.075391,0.412132,0.242400,0.419898,0.002414,0.133367,-0.356918,0.397387,0.751071,-0.079680,-0.292121,0.011533,0.163169,-0.509021,-0.046320,-0.280259,-0.147862,0.384667,0.206432,0.037936,-0.311837,0.515452,-0.364390,-0.067175,-0.321492,-0.333887,-0.013187,-0.184468,-0.302495,-0.613825,-0.154003,-0.176585,-0.164397,-0.033552,0.218948,-0.163955,0.690117,-0.574039,0.278792,0.554329,-0.144311,-0.693977,0.508458,-0.013235,0.080313,-0.171735,-0.184348,0.182844,0.050866,0.270990,-0.093782,0.022859,-0.185452,-0.468506,-0.331043,0.006451', '6007281', '3811356', '1293265', '1788094');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4902100', '动物总动员', '喜剧', '广袤无际的非洲大草原上，饱受干旱所侵扰的动物们耐心却又焦灼地等待着洪水的到来。今年的汛期似乎姗姗来迟，动物们心中满是不安。他们无论如何也不会想到，不远处的峡谷间耸起一座大坝，人类用它拦截了本该滋润草原和万物的水源。与此同时，草原上迎来了几名罕见的来客：孤独的北极熊、聒噪的高卢鸡、相伴上百年沧桑岁月的乌龟夫妇、活泼的袋鼠以及爱放臭屁的笑笑。他们都是因为人类的颟顸与无知，而被迫离开赖以栖息的家园，只为寻找一个没有人类足迹的乐土。只是非洲草原的情况也不容乐观，来自异乡的动物们不得不和当地的动物朋友联合起来，踏上寻找水源的惊险之旅……©豆瓣', '克里斯托夫·玛丽亚·赫布斯特', '莱因哈德· 克洛泽', 6.6, 11162, 'tt1620449', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1066158941.jpg', 2.2, 12.1, 49.9, 26.9, 8.9, '0.298945,-0.095201,-0.869844,0.782794,0.161905,-0.014924,0.941506,-0.047077,-0.400373,0.137696,0.011850,0.631258,0.224861,0.396608,-0.067042,-0.105002,-0.284122,-0.422753,-0.367811,0.058944,-0.282580,-0.060204,-0.554382,-0.293892,-0.134307,-0.317967,0.736259,0.408341,-0.073373,0.674536,0.029265,0.195202,-0.206884,0.556941,-0.562706,-0.221300,-0.133695,0.141201,-0.119156,-0.107758,-0.244346,-0.194650,-0.231605,0.203590,-0.146780,0.327829,0.712574,-0.551128,-0.209233,-0.369087,0.100945,-0.445351,0.369513,0.218970,0.582644,-0.327597,0.105492,0.042924,-0.046459,0.187168,-0.084773,0.012766,-0.734286,-0.093673,-0.028852,0.334922,-0.513053,0.457101,0.454786,-0.289401,-0.009031,-0.448813,0.265478,0.318973,0.218057,0.553470,-0.122771,0.037745,-0.402556,-0.072307,0.950661,0.099045,-0.226295,0.135249,-0.378587,-0.668209,0.125466,-0.241578,-0.657134,-0.269973,0.154582,0.148934,-0.429131,0.396847,-1.150315,0.506530,-0.098536,-0.614668,-0.059115,-0.184590,-0.422581,-0.579540,0.179889,-0.642264,-0.224850,0.364775,0.373829,-0.036442,0.885626,-0.597732,0.346658,0.621766,0.186625,-0.300783,0.607500,-0.037978,0.011122,-0.019863,-0.096341,0.540205,-0.095554,0.487641,0.163532,0.137580,-0.261367,0.078205,-0.448003,0.618772', '26290398', '4181031', '34461680', '1308784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4903581', '追凶', '悬疑', '某晚，警察局来了一个不速之客军（王宝强 饰），他向当值探员报称自己杀了五个人，但他既说不出与受害者关系，又不能描述出受害者被杀过程或遇害地点。原来只是计划把五人杀死。探员在记下军的联络住址后便把他驱逐，在探员眼中，他只是一名无聊的精神不正常者。可是不久，督察汉（刘青云 饰）驻守的区域却发生了一件凶杀案：死者形状恐怖，汉认为这种处死方法带有不寻常的动机，不到一星期汉接手另一宗凶杀案，死者也是一名男子，死于一个废置的机械工场。他的死法十分残酷，死者的双脚被强行穿上细尺码的红色高跟鞋，脚面和两侧都钉上了十多口的铁钉。汉在翻查全港可疑人物和案例时，看到了当天军前来自首的记录。汉马上带队前往军的住所进行搜查，可是屋内空无一人，除了大量古旧童话书外，并无可疑之处。但这时候汉还不知道，一张被精密预设的大网张开了，而结局却更是匪夷所思，难以预料。©豆瓣', '刘青云', '彭发', 4.5, 11101, 'tt1854569', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1520727603.jpg', 22.3, 39.8, 30.3, 5.2, 2.4, '0.440257,-0.095508,-0.531542,0.398452,-0.005354,0.047104,1.035512,0.043334,-0.435645,-0.335913,0.202213,0.608276,-0.103754,0.000184,0.060484,-0.118958,-0.260703,-0.688013,-0.030309,-0.495304,-0.586556,-0.453252,-0.065251,-0.275195,0.114428,-0.209170,0.541435,0.174339,-0.185874,0.221578,0.128573,0.332770,-0.142013,0.578886,-0.137846,-0.143205,0.033146,-0.125676,0.196917,0.078103,-0.059181,-0.435023,-0.124216,0.353598,-0.298118,0.654892,0.854593,-0.335286,-0.298300,-0.030843,0.211133,-0.224223,-0.018316,0.272150,0.484370,0.157464,0.167645,0.269743,-0.075220,0.033813,0.253995,-0.029022,-0.755482,-0.029130,0.146320,0.272315,-0.520475,0.348100,-0.445151,-0.047004,-0.097837,-0.513604,0.360631,0.298531,0.269427,0.222398,-0.044246,-0.054032,-0.734394,0.198993,0.595761,0.098685,-0.253360,0.118323,-0.084201,-0.532022,-0.092652,-0.135203,-0.100957,0.103277,0.387562,0.026181,-0.087868,-0.251391,-0.392449,0.009370,-0.458347,-0.178237,-0.362626,-0.138660,-0.131782,-0.398508,0.043749,-0.185349,-0.371132,0.289302,0.186610,0.044483,0.338710,-0.491723,-0.014807,0.420504,0.251819,-0.432094,0.507111,0.080289,0.054149,0.012772,0.087341,-0.164742,0.450836,0.475678,0.295875,0.550398,-0.059908,-0.162584,-0.276060,0.159508', '21619567', '1578663', '1293515', '1394470');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4903613', '你好，陌生人', '喜剧', '泰国男生Dak（辰塔维·塔纳西维 Chantawit Thanasewee 饰）因拒绝与女友结婚而被抛弃。喝得烂醉后隔天独自踏上原先和女友预订的韩国旅程。宿醉语言又不通的Dak只能向，只能向一名泰国女生May求助（努娜能提妲莎彭 Noona Nuength ida Sophon 饰）。May有一位大男子主义，对她管得彻头彻尾的男友金哥，这一次是背着男友偷跑来韩国参加好友的婚礼。因为漏接金哥的电话导致两人大吵一顿最后分手。Dak一直留在她身边安慰，两人一起去酒吧，一起去参观韩剧的拍摄地点。虽然彼此都不知道对方的名字，但两人慢慢从冤家慢慢聊成知己，就在情愫渐生之时，Dak的女友突然出现。Dak是会选择重新回到女朋友的身边，还是这一对熟悉的陌生人最终会终成眷属。©豆瓣', '辰塔维·塔纳西维', '班庄·比辛达拿刚', 7.7, 73280, 'tt1725995', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p603471859.jpg', 0.4, 2.5, 29.7, 47.1, 20.3, '0.317139,-0.111080,-0.651760,0.498719,0.095439,-0.419536,0.667256,0.099569,-0.386420,-0.200333,-0.021003,0.964216,-0.414156,0.475503,0.415832,-0.075640,-0.253568,-0.743318,0.071240,-0.125044,-0.403041,-0.442261,0.181591,0.046248,-0.085637,0.127859,0.339757,-0.139120,-0.131536,0.547008,0.529668,0.229697,-0.238727,0.641443,-0.205463,-0.035134,-0.077276,0.122095,-0.305944,0.376499,0.283899,-0.021346,-0.114873,-0.057281,0.185275,0.208913,0.607237,0.018213,-0.107168,-0.075969,0.238764,-0.000932,-0.156058,-0.083601,0.336044,-0.087140,0.569400,-0.012487,-0.074010,-0.036479,0.026669,0.043460,-0.178514,0.312777,-0.056447,0.063246,-0.535137,0.411241,0.070287,-0.043264,0.237539,-0.387636,0.282967,0.528123,0.239352,0.477645,-0.089554,0.070752,-0.304133,0.017310,0.783387,0.313366,0.195545,0.460348,-0.147435,-0.311089,0.023775,-0.042396,-0.610477,0.092577,0.150504,0.144099,-0.158457,0.011157,-0.564072,-0.181495,-0.067528,0.036489,0.346614,-0.636678,0.119821,-0.618252,0.004885,-0.203229,-0.244660,0.346175,-0.094532,-0.084893,0.517095,-0.917891,0.146465,0.625936,0.511229,-0.610357,0.824710,0.412075,0.044452,-0.269653,0.257429,0.183791,0.011776,0.214842,0.201512,0.325523,0.007893,0.058325,-0.489401,0.106089', '1302384', '1292219', '26687241', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4903614', '真幌站前多田便利屋', '剧情', '在东京的附近有一座真幌市，这里介乎都市与乡村之间，生活悠哉散漫，甚至连天气预报也不准。在真幌车站的旁边，坐落着一家破败毫不起眼的小店——多田便利轩。店主多田启介（瑛太 饰）是一个有过失败婚姻的男子，他独自经营小店，兼带为他人提供各种各样的服务，生活平淡无奇。偶然机缘，多田重逢初中同学行天春彦（松田龙平 饰）。这个同样有着失败婚姻性格别扭的男子暂时住进了便利轩，却不知不觉成为了多田的合作伙伴。他们终日开着小卡车，穿梭在真幌的大街小巷，与各式各样的人擦肩而过，影响着彼此的人生……本片根据三浦紫苑的原著改编，荣获2011年电影旬报十佳第4名。©豆瓣', '永山瑛太', '大森立嗣', 8.2, 33206, 'tt1685576', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1126640909.jpg', 0.1, 1.4, 19.2, 48.3, 31.1, '0.451141,0.084214,-0.501642,0.562736,0.225950,-0.196658,0.537306,0.355669,-0.513960,-0.351905,0.185982,0.710998,-0.180157,0.300069,0.168605,-0.084196,-0.260589,-0.421624,-0.221281,-0.144271,-0.146094,-0.351112,-0.084548,-0.038399,-0.333301,-0.037493,0.670488,0.136638,-0.193340,0.460570,0.138261,0.177408,-0.306525,0.138513,-0.602242,0.024343,0.078754,0.295017,-0.302327,0.073087,-0.308216,-0.203668,-0.151407,-0.256089,0.096229,0.182500,0.803884,-0.073820,-0.708499,0.088283,0.489595,0.088000,-0.129812,-0.181699,0.236411,-0.155683,0.227563,0.064474,-0.334475,0.094846,0.002089,-0.098292,-0.548714,-0.044918,-0.015444,0.003152,-0.362467,0.555339,0.322830,-0.139410,-0.077035,-0.151710,0.125834,0.209117,0.330826,0.070121,-0.129056,0.080018,-0.625847,0.193930,0.614300,0.252979,-0.225325,0.464707,-0.553478,-0.241446,-0.228939,-0.113663,-0.598250,-0.003776,0.099446,-0.317522,0.044372,0.067388,-0.701940,0.285025,0.094566,-0.025158,0.382274,-0.116285,-0.166856,-0.858202,0.236092,-0.597768,-0.400060,0.118556,-0.014506,-0.320874,0.625111,-0.959069,0.035178,0.446950,0.436444,-0.201388,0.870552,0.045009,0.206578,-0.077608,-0.357826,0.198675,-0.086793,0.256676,0.244384,0.358323,-0.148267,-0.023998,-0.284332,0.458638', '3055049', '3811356', '1418179', '2334814');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4904026', '吐司', '剧情', '根据英国国宝级美食作家Nigel Slater的获奖图书《吐司：少年饥饿记》改编而成，将童年记忆与他对美食的挚爱将出现在大荧屏上。少年Nigel Slater（奥斯卡·肯尼迪 Oscar Kennedy 饰）的母亲从来不是个好厨子，连简单的熬汤都不会，一家三口最常 吃的就是土司。当母亲哮喘发作去世以后，父亲只能以罐头食品取代。后来那个精于烹调的清洁工（海伦娜·邦汉·卡特 Helena Bonham Carter 饰）借此抓住了父亲的胃，变成了他的继母。日益增长的敌意让Nigel选择参加了家政班，学习制作各种甜食，来挑战这个厨艺精湛的继母。父亲每天都要忍受两人不断的吵闹，并被强迫吃掉两个相继制作的没完没了的甜点。二人间的战争终于在父亲的猝死后停止。17岁的Nigel收拾行囊，在厨房中找到工作，登入了超凡厨艺的辉煌殿堂。©豆瓣', '海伦娜·伯翰·卡特', 'S·J·克拉克森', 7.5, 36511, 'tt1658851', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p850677807.jpg', 0.4, 3, 34.3, 47.1, 15.1, '0.358316,-0.056450,-0.442877,0.584576,-0.153745,-0.479454,0.633208,0.313875,-0.434247,-0.301041,0.031433,0.967041,-0.084203,0.533816,0.143798,-0.185924,-0.081286,-0.685882,-0.111939,0.008440,-0.254361,-0.310087,-0.099688,-0.276686,-0.181181,-0.178209,0.485189,-0.214486,-0.152814,0.283086,0.236158,-0.081307,0.245994,0.305518,-0.324586,0.022926,-0.040722,-0.165394,-0.219007,0.138807,0.141560,-0.389533,0.138599,0.253194,0.106583,0.158725,0.716859,-0.202878,-0.137362,-0.228031,0.455077,-0.206261,-0.187223,0.200310,0.225129,0.216482,0.087698,0.081284,-0.343518,0.219923,-0.166759,-0.113137,-0.902104,-0.300871,0.238162,-0.044369,-0.770183,0.314708,-0.029327,-0.109485,0.087214,-0.382109,0.265483,0.285259,0.085044,0.624538,-0.069195,0.132269,-0.442366,0.469197,0.542744,-0.139464,0.077219,0.334141,-0.149763,-0.315777,0.353608,-0.471180,-0.448002,0.026501,0.017943,0.071773,-0.030156,0.096558,-0.668060,-0.118342,-0.051771,-0.414487,0.325287,-0.136573,-0.296043,-0.738160,0.024146,-0.295064,-0.325804,-0.003067,0.058263,-0.235480,0.879290,-0.847331,0.314928,0.364782,0.128274,-0.318819,0.599600,-0.034556,0.161887,-0.028702,-0.165283,0.184584,0.145038,0.067278,0.028921,0.463620,0.195770,-0.114587,-0.508680,0.546124', '1793491', '25928048', '27602116', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4906427', '万有引力', '剧情', '这是四个与爱情有关的故事：审计员高远（文章 饰）三年来重复着两地奔忙的工作，在他前往外地送交一份重要文件之时，机场安检员石晓琳（白百何 饰）却将他扣留，耽误了航班的高远大怒，却发现石晓琳对他非常了解……；数学教师王勇（郭涛 饰）与妻子雪莲（张静初 饰）结婚多年，在朋友的启发下决定要个孩子，然而这对爱人的怀孕战役进行的异常艰难……；阿美（莫文蔚 饰）与情人遭遇因信号灯故障引起的车祸，阿美轻伤，而情人重伤昏迷，而这场车祸，似乎由阿美的丈夫云山（戴立忍 饰）一手策划……；跳伞运动员嘉欣（黄幻 饰）因吸毒被跳伞队开除，运动生涯宣告结束，她的男友兼搭档海桥（段博文 饰）决定不惜一切代价挽救她……©豆瓣', '文章', '赵天宇', 6.3, 89972, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p913359188.jpg', 2.6, 14, 53.7, 24.7, 5, '0.011955,-0.111466,-0.414203,0.352931,0.054698,-0.154467,0.667276,0.026043,-0.391536,-0.342797,0.404615,0.648765,-0.212081,0.067857,0.284154,-0.197511,-0.199573,-0.653327,0.206397,0.073340,-0.121911,-0.582337,0.188808,0.271774,-0.006681,-0.252442,0.702857,-0.019204,-0.020922,0.650667,0.229849,0.186039,-0.082244,0.339743,0.164799,0.115942,0.013440,0.188583,-0.326367,0.052148,0.205381,-0.304907,-0.069607,0.150762,0.053320,0.419444,0.787176,-0.028730,-0.320748,-0.168640,0.425879,-0.443942,0.144799,0.103769,0.293133,0.379969,0.240224,0.381116,-0.374173,-0.060822,0.065878,0.056572,-0.417724,0.019729,0.132716,0.032873,-0.745366,0.597719,-0.355361,0.125863,0.190017,-0.317627,0.142903,0.583977,0.168523,0.387160,-0.280042,0.039292,-0.246300,0.429015,0.543000,-0.247475,0.088250,0.316394,0.034305,-0.374999,0.103613,-0.060536,-0.397265,0.161902,0.140550,-0.215686,-0.153437,0.103904,-0.320486,-0.028577,-0.344685,-0.094107,-0.048122,-0.387268,-0.133399,-0.614143,0.112402,-0.204541,-0.241271,0.071618,0.156873,-0.200544,0.406266,-0.705507,0.218083,0.450362,0.111586,-0.626773,0.317116,0.436625,0.269183,-0.467943,0.113269,0.343411,-0.177267,0.190562,0.086668,0.075929,0.034111,-0.059420,-0.357672,-0.039688', '4202326', '30345227', '1301022', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4907844', '蜡笔小新 超时空！呼风唤雨的我的新娘', '动画', '某日，野原新之助（矢岛晶子 配音）正在公园里和风间（真柴摩利 配音）、妮妮（林玉绪 配音）等朋友们玩耍，意外遇见了一位名为金有久美子（钉宫理惠 配音）的神秘女子，久美子告诉小新，自己来自于遥远的未来世界，而彼时已经长大成人的新之助，正是自己的未婚夫。跟随着久美子，小新一行人来到了未来，在那里，金友电机的社长，亦是久美子的父亲金有增藏手握大权，并且绑架了一直和自己作对的新之助。得知小新的到来会阻碍自己的计划，增藏派出了刺客，在强大的敌人面前，小新能否顺利救出新之助，并且帮助面前这个陷入了黑暗之中的世界重新找回光明呢？©豆瓣', '矢岛晶子', '鴫野彰', 8.3, 18998, 'tt1623674', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2254635464.jpg', 0.4, 1.6, 17.3, 41.6, 39.1, '-0.094161,0.250143,-0.470045,0.339917,-0.172803,-0.356771,0.257305,0.212917,-0.439570,-0.481930,0.174125,0.566848,0.214093,0.614411,0.558487,0.188337,-0.240342,-0.687550,-0.241069,-0.035970,-0.400645,-0.452519,-0.434742,-0.057724,-0.222827,-0.422424,0.683239,0.066683,-0.178918,0.383859,0.321286,0.429653,-0.531314,0.223076,-0.064889,0.150496,0.330893,0.167226,-0.301514,0.237474,-0.315715,-0.113057,-0.066513,0.030093,0.188249,0.228906,0.511683,-0.297857,-0.152064,-0.334989,0.272613,-0.233569,-0.101962,0.202240,0.301086,0.115286,0.455978,0.187056,-0.328095,-0.142549,-0.063070,-0.224967,-0.663792,-0.035064,0.076149,0.061325,-0.401229,0.156983,0.042194,-0.310126,0.540331,-0.265881,0.317167,0.455272,0.275107,0.335184,-0.454702,0.091039,-0.000832,-0.142197,0.481249,-0.184828,0.026788,0.117707,0.255832,-0.140602,-0.175482,0.013397,-0.405202,0.017404,0.333700,0.259901,-0.067442,0.196558,-0.350290,-0.115442,-0.165977,0.131279,0.319681,-0.392723,-0.174237,-0.552384,0.026490,-0.350204,-0.130222,0.247752,0.188767,-0.281645,0.814608,-0.850141,0.323349,0.452935,0.271267,-0.144266,0.436792,0.032992,-0.033756,-0.368486,-0.082471,-0.060064,-0.035289,0.404679,0.114150,0.188799,-0.182719,-0.241969,-0.576767,0.261081', '10174444', '2369613', '1826173', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4910183', '跟踪孔令学', '喜剧', '中年男子孔令学（范伟 饰）是东北某市双全文武学校的语文老师，他上课认真负责，无奈所面对的是一群不知天高地厚，对祖国美好文字全无兴趣的新新人类。在一次课上，他没收了女孩刘萌（白卉子 饰）的手机，之后又阻止了追求刘萌的社会青年阿祥（支一 饰）的打架行为，由此惹来了一身麻烦。阿祥每天在孔令学下班后跟踪他，声称要“帮助辛苦的孔老师接送孩子下学”，这令一向忠厚本分的孔令学颇为恐慌。为了甩掉这个死缠烂打的小青年，他每天想尽各种办法，可是女儿的学校和家庭住址终于还是被阿祥搞清楚了。在这一过程中，孔令学的生活渐渐变成了一团乱麻……本片根据胡学文的原著小说《大风起兮》改编。©豆瓣', '范伟', '张骁', 6.7, 13154, 'tt1899193', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p933775270.jpg', 2.2, 10, 46.6, 32.1, 9, '0.106570,-0.074898,-0.363739,0.436784,-0.209704,-0.400076,0.309674,-0.010950,-0.523940,-0.132320,0.001383,0.466788,0.072384,0.432085,0.302249,-0.068357,-0.295855,-0.578060,-0.199236,-0.076595,-0.180525,-0.427368,-0.062810,-0.150212,0.024704,-0.256237,0.262491,-0.041875,-0.219527,0.364441,0.348838,0.083132,0.090021,0.333978,-0.184808,0.099128,-0.148585,0.058543,0.035245,-0.147657,0.302298,-0.328680,-0.282893,0.173641,0.089449,0.331144,0.638242,0.046458,-0.365454,0.032005,0.648451,-0.302393,-0.179117,-0.037153,0.383074,-0.034457,0.283679,-0.051172,0.000416,0.023267,0.076297,-0.044997,-0.506479,-0.136288,0.228071,-0.052271,-0.656592,0.379464,-0.047757,-0.100534,0.083522,-0.391100,0.118314,0.326119,0.237613,0.306953,-0.198784,-0.022642,-0.207686,0.648329,0.413652,0.088889,-0.120751,0.333640,-0.292664,-0.098143,-0.017838,-0.129307,-0.628355,-0.057687,0.269879,-0.138739,-0.387665,-0.056420,-0.366587,-0.063802,-0.014716,-0.156784,-0.106904,-0.518188,-0.190398,-0.306829,-0.022896,-0.356717,-0.280591,-0.092857,0.076313,-0.242982,0.875111,-0.879957,0.086801,0.481405,-0.010744,-0.437687,0.416741,0.126912,-0.052210,-0.084981,0.022070,-0.018513,0.158755,0.431123,-0.071642,0.649774,0.081952,-0.422926,-0.356101,0.433335', '25922902', '26593587', '3445516', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4913185', '杀戮', '剧情', '平凡的一天，名叫扎克利和伊森的小男孩在某公园内发生争执，前者用棍子将后者的嘴打破。这起不大不小的儿童纠纷，将两对本没有任何交集的夫妇拉到了一起。经营小百货商店的麦克·朗斯特里特（约翰·C·赖利 John C Reilly 饰）与身为作家的潘妮洛普（朱迪·福斯特 Jodie Foster 饰）是伊森的父母，他们在家中迎来扎克利的父母——律师艾伦·考温（克里斯托弗·沃尔兹 Christoph Waltz 饰）以及投资经纪人南希（凯特·温斯莱特 KateWinslet 饰）——的拜访。他们就孩子的伤害事件协商、讨论、争执、冷嘲热讽、旁敲侧击，时而强作欢颜，时而面露不快，可是又不得不面对面度过这难熬与痛苦的一天……本片荣获2011年波士顿影评人奖最佳群戏奖、2011年威尼斯电影节小金狮奖。©豆瓣', '朱迪·福斯特', '罗曼·波兰斯基', 8.3, 71495, 'tt1692486', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1305342680.jpg', 0.4, 1.8, 16, 48.2, 33.5, '0.215916,-0.220687,-0.517673,0.359061,0.127678,-0.464501,0.675573,0.401956,-0.411662,-0.231114,0.321174,0.589602,-0.416810,0.295353,0.325594,-0.118158,-0.376953,-0.664750,0.018997,0.026427,-0.008131,-0.712566,-0.351464,-0.239398,-0.038663,-0.095572,0.312961,-0.279082,-0.091226,0.623741,0.465009,0.237757,0.016397,0.240476,-0.048519,0.123846,0.250549,0.079295,-0.466031,0.207767,0.130691,-0.034516,-0.364228,-0.240603,0.386263,0.359054,0.619989,-0.203715,0.097809,0.030175,0.367838,-0.220446,0.048594,0.026317,0.273256,-0.099902,0.247857,0.270147,-0.380447,0.085337,0.365686,-0.059174,-0.393101,0.435058,-0.013494,0.237527,-0.491904,0.584672,-0.044799,-0.037532,-0.055714,-0.162931,0.160319,0.375029,0.107061,0.248114,0.112527,0.106348,-0.248109,0.148302,0.355539,0.140624,-0.133307,0.156898,-0.364329,-0.388186,-0.127457,-0.339287,-0.418012,-0.080349,0.416683,-0.152503,-0.089656,0.383826,-0.519956,-0.145030,-0.282064,-0.099868,0.136361,-0.038383,-0.051108,-0.926776,0.117373,-0.396763,-0.341220,-0.088852,0.125228,-0.118800,0.626222,-0.720484,0.121811,0.460491,0.318037,-0.037144,0.700643,0.153898,0.277817,-0.215948,-0.079991,0.207587,-0.032530,0.029246,0.130895,0.176987,0.135952,-0.001821,-0.119997,0.321379', '1292050', '11541282', '2297262', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4913200', '大魔术师', '剧情', '20世纪初，大清王朝气数已尽，各路军阀连年混战，拥兵自重，上演了一个又一个的逐鹿之争。时有直隶镇守使雷大牛（刘青云 饰）凭借旁门左道的刘昆山（吴刚 饰）大肆招募兵马，不断壮大，外有重兵，内有美眷，加上居心叵测的日本人大力扶持，正是春风得意时。与此同时，京城来了神秘的魔术师张贤（梁朝伟 饰），他凭借令人拍案叫绝、神乎其神的技艺绝倒京城，自然连雷大牛也早有耳闻。殊不知张贤是大牛的七姨太柳荫（周迅 饰）的青梅竹马，当年他外出求学时爱人被大牛掳走，抱憾终身，此外他还隶属某个神秘的组织，该组织时刻图谋绑架牛司令。在这个纷争乱世，张贤将上演怎样令人叹服感慨的魔术呢……本片根据张海帆的同名小说改编。©豆瓣', '梁朝伟', '尔冬升', 6.5, 159477, 'tt1869721', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1382183308.jpg', 2.6, 12.5, 49.1, 29.1, 6.6, '0.051254,0.110895,-0.748718,0.527445,0.277904,0.101961,0.274904,0.173220,-0.539234,-0.316918,0.238896,0.409075,-0.047242,0.030170,0.001864,-0.165279,0.039547,-0.639493,-0.073525,-0.036558,0.085805,-0.157375,-0.490920,-0.190348,-0.095350,-0.133377,0.304276,0.258941,-0.453717,0.291690,0.265613,0.277347,-0.200211,0.270091,-0.218136,0.067308,0.136757,0.054549,-0.150716,-0.168723,-0.235986,-0.457515,-0.105208,-0.132208,-0.120337,0.295480,0.499759,-0.211228,0.113983,-0.127020,0.502700,-0.130520,-0.328061,0.009871,0.506808,0.060197,-0.097777,0.065777,-0.030159,-0.094083,-0.174878,-0.036026,-0.821507,-0.101170,0.264280,0.031065,-0.470088,0.225285,0.047591,-0.153214,0.066282,-0.160747,0.225864,0.650345,0.303791,0.107629,0.191623,-0.049119,-0.436763,0.462108,0.672777,0.009855,-0.014253,-0.087014,0.279234,-0.321943,0.198373,-0.320925,-0.427397,0.083073,0.348243,-0.509472,0.201859,0.239623,-0.393985,0.015359,-0.151589,0.161525,0.163458,-0.116015,-0.144758,-0.499379,-0.211892,-0.364115,-0.057742,0.039820,0.361244,-0.112339,0.801155,-0.584885,-0.068297,0.556409,0.007211,-0.709255,0.387671,0.102143,0.038942,-0.082521,-0.273723,0.046952,0.110542,0.099223,0.025064,0.320664,-0.180259,-0.467128,-0.119561,0.132391', '27602116', '26678784', '30163500', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4913222', '大话天仙', '喜剧', '美若天仙的许金凌（孙俪 饰）拥有绝赞琴艺，传说她曾和一位神仙学琴，其琴声可以让听者毫无掩饰说出心声。金凌所在的赵府为女儿的婚事大宴宾朋，但是高傲的金凌当众让专横跋扈的赵夫人（郭德纲 饰）出丑。赵夫人恼羞成怒，将其下嫁给丑陋不堪、穷困潦倒的毛大龙（林雪 饰）。毛大龙和义弟毛松（郑伊健 饰）相依为命，新婚当夜，金凌窥探毛松的心事，发现自己似乎在十八年前和他有一段未了因缘。与此同时，花花公子施文胜（郑中基 饰）觊觎金凌的美貌，与表姐赵夫人暗中勾结，合谋给毛大龙下套。哥哥被抓，嫂嫂被抢，万念俱灰的毛松决心赴死，却在危急关头遇见两个外星人，他的命运由此发生转变……©豆瓣', '孙俪', '刘镇伟', 3.3, 31480, 'tt6448172', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2166743330.jpg', 57.3, 26.5, 11.3, 2.3, 2.6, '0.036488,0.054418,-0.485971,0.660668,-0.166983,-0.235833,0.751843,0.166842,-0.556858,-0.287184,0.190212,0.392057,-0.509077,0.332716,-0.016758,-0.043806,0.291872,-0.647769,0.046755,0.215477,0.048843,-0.354951,-0.182908,-0.132785,-0.215916,-0.113602,0.284813,-0.136044,-0.322303,0.482851,0.688673,0.280819,-0.184422,0.328201,-0.291063,0.239266,-0.240183,0.246457,-0.242841,-0.208799,0.035029,-0.363329,-0.022183,0.161101,-0.277207,0.308233,0.569803,-0.140852,-0.032885,-0.286329,0.600979,-0.139233,0.139053,0.318204,0.239590,-0.052423,-0.004337,-0.002054,-0.175308,-0.184951,0.351613,0.062122,-0.364821,0.064536,0.311302,0.025534,-0.458505,0.137253,-0.084192,0.064643,0.117021,-0.297121,0.304417,0.100818,0.249824,0.246861,-0.067092,0.171276,-0.654941,0.305772,0.613368,0.003468,0.310974,0.012105,0.104853,-0.237535,0.157296,-0.251149,-0.423024,0.178848,0.208647,-0.228910,0.138215,0.325180,-0.343138,-0.532409,-0.295750,0.387782,0.126941,-0.662739,-0.032013,-0.045040,-0.313087,-0.585101,-0.148312,0.135621,0.426192,-0.351522,0.458887,-0.561272,0.051832,0.009549,0.160406,-0.644816,0.557089,0.281805,0.150689,-0.089560,0.017733,-0.041847,0.162891,-0.093198,0.279250,0.272923,-0.077839,0.158133,-0.427611,0.151327', '1890558', '3033092', '1304091', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4914468', '冰川时代4', '喜剧', 'Chris Wedge《冰川时代4》讲述的依然是那些生活在冰川时期的特殊动物“家庭”经历的冒险故事。那只永远追着松果的无敌贱，又苦逼的小松鼠奎特（克里斯·韦奇 Chris Wedge 配音 ）这次搞出了更大的事件，一个不小心让大陆板块四分五裂，使得猛犸象曼尼（雷·罗马诺 Ray Roman o 配音）、树懒希德（约翰·雷吉扎莫 John Leguizamo 配音）以及剑齿虎迪亚哥（丹尼斯·利瑞 Denis Leary 配音）因此和家人、伙伴失散分离，在板块激烈的运动并分裂漂移后，只能使用一块流冰作为临时的船只，展开一段惊奇的海上大冒险，在海上他们会遭遇险恶的自然环境，也会遇到海盗，而回家与家人团聚是他们的终极愿望，他们最后能否顺利回家呢？©豆瓣', '阿兹·安萨里', '麦克·特米尔', 8.1, 216478, 'tt1667889', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1634625172.jpg', 0.2, 1.2, 19, 51.7, 27.9, '0.041853,-0.259059,-0.409568,0.454011,0.332615,-0.215792,0.555484,0.042199,-0.266060,0.012533,0.133936,0.775466,-0.075372,-0.031141,0.035838,-0.082805,-0.344365,-0.334633,0.116335,0.058094,-0.197779,-0.442484,-0.274553,-0.337193,0.110465,-0.318368,0.566948,-0.002971,-0.353792,0.299368,0.186077,0.122269,-0.486388,0.395885,-0.084505,0.077116,0.043030,0.226155,-0.310538,-0.096111,-0.042189,-0.026109,-0.042905,0.034612,0.258890,0.099167,0.670524,-0.389716,-0.120523,-0.201559,0.148231,-0.375822,0.051430,-0.156890,0.501949,-0.301127,0.386987,0.169847,0.099216,0.141371,0.066952,-0.162509,-0.682926,0.129342,0.075452,0.150353,-0.409700,0.341832,0.200942,-0.045309,0.122391,-0.218206,0.341334,0.544381,0.424924,0.342583,-0.245125,0.109053,-0.191876,0.220707,0.676465,-0.042118,-0.373069,0.236080,-0.189468,-0.336196,-0.202011,-0.464727,-0.546433,-0.010306,0.412275,0.071799,-0.406760,0.504373,-0.737441,0.071672,-0.281166,-0.283588,-0.063167,-0.314109,-0.116354,-0.707558,0.141568,-0.473906,-0.194699,-0.024899,0.067254,-0.247263,0.724940,-0.646060,0.291405,0.643348,0.200245,-0.220357,0.469624,0.193325,0.257218,-0.127841,0.122787,0.213068,-0.009705,0.251419,0.134208,0.349911,0.250414,0.057822,-0.245177,0.509749', '3811356', '35161768', '26290398', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4914627', '夺命心跳', '悬疑', '经过了心脏移植手术，美丽的女陶艺师林嫣（林熙蕾 饰）终于恢复健康，但是随之而来事情却让她倍感惶恐。林嫣的陶艺天赋顿然消失，技艺越来越差，而且夜晚经常被噩梦所困扰，甚至出现梦游的症状。种种迹象让她怀疑，这突如其来的一切都与身体里那颗神秘的心脏有关。她坚信梦中所经历一切绝非 虚幻，而都来自于心脏的主人，名叫江北燕的音乐女教师，这诡异的情形连林嫣的主治大夫蒋医生（梁家辉 饰）都甚为惊讶。不久，林嫣邂逅江北燕的男友，号称刚刚从美国学成归来的马本科。在江临终前居住过的大房子里，这个美丽的女教师死亡之谜被慢慢揭开……©豆瓣', '林熙蕾', '张琦', 5.1, 5153, 'tt1990211', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1062441679.jpg', 14.1, 31.2, 42.6, 9.3, 2.8, '0.025339,0.102261,-0.817657,0.675478,0.070340,-0.061506,0.855310,-0.084038,-0.663420,-0.877409,0.000242,0.513018,-0.487461,0.578329,0.247520,-0.043099,0.155654,-0.663351,-0.299682,-0.209740,-0.584942,-0.130084,-0.152498,-0.258546,-0.066991,-0.269644,0.494031,0.385170,-0.188135,0.516103,0.138889,0.278638,-0.110523,0.492443,-0.252147,0.057167,0.008140,0.219385,-0.096054,-0.240410,0.413812,-0.402165,0.186135,0.563910,-0.183391,0.267761,0.737180,-0.384861,-0.374902,-0.047628,0.374444,-0.144398,0.149809,0.201002,0.282263,0.160661,0.251891,-0.093038,-0.378222,-0.003190,0.070535,-0.064306,-0.610967,0.160431,0.397701,0.125209,-0.308729,0.066506,0.025777,0.253964,-0.126174,0.004620,0.470186,0.048709,0.350779,0.556286,-0.267882,0.102053,-0.137563,0.137424,0.690149,0.092050,-0.484891,0.557929,-0.373641,-0.542493,-0.113515,0.063154,-0.411806,0.415016,0.028481,0.180038,-0.120324,0.383815,-0.505311,-0.131515,-0.157524,0.024457,-0.413444,-0.036608,-0.120059,-0.396090,-0.275989,-0.430005,-0.108561,0.038281,0.013280,-0.333907,0.637567,-0.800716,0.257924,0.231087,0.029022,-0.511057,0.307887,-0.123531,0.161876,-0.043308,-0.226028,0.643507,0.113621,0.170652,-0.130630,0.533950,-0.257243,-0.035645,-0.499180,0.712484', '1291877', '30450313', '1301022', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4914656', '猫在巴黎', '动画', '一只名叫蒂诺的小猫，看尽巴黎的白天与黑夜。白天，它是小女孩佐伊（Oriane Zani 配音）宠物，每天早上为她带来小礼物。佐伊的父母都是警察，父亲被城中最大的恶棍维克托·科斯塔（Jean Benguigui 配音）杀害，母亲让娜（Dominique Blanc 配音）发誓将科斯塔绳之于法，渐渐忽略了对佐伊的关怀。小佐伊从此封闭了自己，不发一言。每到夜晚，蒂诺便跳出窗户，寻找它另一个生活在黑夜的朋友尼克（Bruno Salomone 配音）。尼克是一个身手敏捷的大盗，他神出鬼没，手法娴熟，不过蒂诺是他唯一的朋友。蒂诺穿梭往来，成为了两个完全不同的人儿间的奇妙纽带。某晚，佐伊跟着蒂诺溜出房间，却意外遭遇企图抢劫展览馆石像的科斯塔团伙。佐伊、尼克和让娜纷纷被卷入其中……©豆瓣', '多米尼克·布隆', '让-卢普·费利乔利', 7.8, 16066, 'tt1673702', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p788743927.jpg', 0.2, 1.4, 26.9, 50.1, 21.5, '0.113597,-0.203688,-0.256758,0.405485,-0.164751,0.040843,0.750015,0.190270,-0.354599,-0.270878,0.241051,0.914133,0.022704,0.186831,0.235447,0.189608,-0.360233,-0.676408,0.058044,-0.015569,-0.136914,-0.442819,-0.175782,-0.228826,0.002811,-0.255420,0.501059,-0.265969,-0.123604,0.413780,-0.006426,0.141647,-0.282498,0.362066,-0.270544,0.218382,0.321256,-0.289582,0.023821,0.081144,-0.230244,-0.002422,-0.304498,0.200388,0.008624,0.399367,0.639052,-0.395819,-0.008736,-0.040668,0.280784,-0.328646,0.075781,0.025551,0.161736,-0.051655,0.221711,-0.006943,-0.247783,-0.070969,0.214558,-0.236055,-0.744963,0.241287,0.122611,-0.053075,-0.309882,0.200085,-0.084430,-0.044314,0.335539,-0.380254,0.318725,0.015559,0.260690,0.282380,-0.116215,0.043962,-0.431697,-0.037259,0.376904,-0.150013,-0.372472,0.382214,-0.416669,-0.174741,0.047394,-0.118665,-0.329008,-0.146616,0.394058,-0.090797,-0.311845,0.389232,-0.507202,0.104566,-0.306315,-0.111015,-0.182108,-0.456572,-0.277170,-0.507935,-0.020247,-0.202187,-0.253001,0.032784,0.039377,-0.081477,0.509674,-0.701905,0.142329,0.745789,0.048259,-0.036614,0.799485,-0.279580,0.131255,-0.004330,0.128880,0.316045,0.382325,0.142983,0.148875,0.532258,0.026782,0.134618,-0.391299,0.532671', '30162520', '1299628', '34890458', '1949005');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4915135', '李小龙我的兄弟', '剧情', 'http://site.douban.com/108856/电影《李小龙》豆瓣小站1940年11月27日，香港粤剧界名伶李海泉（梁家辉 饰）于旧金山演出，忽闻太太何爱榆（钟丽缇 饰）临盆。孩子降生，取名李振藩，英文名Bruce Lee。次年，全家返港，李母为婴孩取名细凤。日军侵占香港，全家受辱，细凤心生惩恶扬善之心。细凤（李治廷 饰）自幼调皮多动，经常惹出乱子，遭到父母严惩。邻家文女（贡米 饰）对他情有独钟，但他却并不在意。细凤出道很早，不久成了童星。因酷爱跳恰恰舞，他结识了英国来的朋友刘连光（张一山 饰），几人组成“龙城四虎”。某日，细凤偶遇曹达华爱女敏儿（谢婷婷 饰），心生情愫，但因刘连光约会敏儿，而将此事埋藏于心。某日，在糖水店，他与校际拳赛冠军洋人查理发生口角，实力不济，被打。他为报仇，拜叶问为师，学习咏春，准备再战。此时，敏儿却向他发出了参加恰恰舞比赛的邀请……', '李治廷', '文隽', 6.3, 8070, 'tt1482989', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2633671760.jpg', 2.9, 13.1, 54.7, 23.9, 5.2, '-0.198750,-0.078820,-0.424115,0.090475,0.125319,-0.103100,0.231203,0.200814,-0.388666,-0.101651,0.026608,0.650681,-0.303627,0.381734,0.123057,-0.138105,0.072641,-0.415305,0.411573,0.057726,0.232151,0.061312,0.312747,0.001396,-0.195553,-0.223910,0.354257,-0.101415,-0.095099,0.722161,0.234980,0.141600,0.001619,0.104790,0.044780,0.058096,-0.192275,-0.001690,-0.273288,0.113322,-0.173714,-0.282031,-0.232202,-0.223393,0.143552,0.358755,0.628485,0.089883,0.025405,-0.663648,0.484651,-0.148055,-0.000019,0.071854,0.200176,0.156863,0.147247,0.217092,0.000058,0.046004,0.073671,-0.379553,0.010628,0.274334,0.295530,-0.005686,-0.358113,0.428910,-0.336556,-0.026903,-0.050949,-0.157250,0.219017,0.234774,0.078743,0.066808,-0.091262,0.129877,-0.207624,0.414503,0.499350,-0.208632,0.205200,0.123755,0.172232,-0.386429,0.469356,-0.151651,-0.280549,0.223710,0.082230,-0.163068,0.050491,0.102018,-0.123967,-0.163035,-0.116783,0.092257,0.200096,-0.169486,0.046738,-0.546851,-0.038140,-0.209709,-0.231466,-0.254995,0.232631,-0.111278,0.479541,-0.722369,0.193796,0.276735,0.331408,-0.499479,0.429440,0.023118,-0.068990,-0.261762,0.143306,0.247277,-0.254636,-0.180055,-0.053839,0.062429,0.002837,0.013009,-0.013240,-0.106825', '3139191', '2636526