INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4915857', '神偷奶爸2', '喜剧', '自从与玛戈（米兰达·卡斯格拉夫 Miranda Cosgrove 配音）、伊迪丝（达娜·盖伊 Dana Gaier 配音）和阿格蕾丝（埃尔希·费舍 Elsie Fisher 配音）三个可爱的小女孩实现宿命的邂逅，曾经的大坏蛋格鲁（史蒂夫·卡瑞尔 Steve Carell 配音）可真彻底转型了，他金盆洗手，转而化身为慈祥可亲的爸爸和做得一手烂口味布丁果冻的商人。当然凡事没有尽善尽美的，在此期间，憧憬大坏蛋传奇人生的老搭档纳法利欧博士（拉塞尔·布兰德 Russell Brand 配音）离他而去，另谋高就。某天，格鲁被身怀绝技却鲁莽的特工露西·王尔德（克里斯汀·韦格 Kristen Wiig 配音）绑架，原来露西所在的集团研制出可以改变生物基因的药物，可他们位于南极的实验室被神秘窃贼偷走，因此才委托有过坏蛋经验的格鲁做卧底。经过一番考虑，格鲁接受了这项任务，带着超萌的小黄人们，和露西组成了爆笑连连的追凶搭档……', '史蒂夫·卡瑞尔', '皮埃尔·柯芬', 8.1, 412461, 'tt1690953', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2164225595.jpg', 0.2, 1.5, 20.2, 49.2, 28.9, '0.294393,-0.233819,-0.273670,0.510741,-0.267953,-0.503021,0.625087,0.012369,-0.187503,-0.230027,0.029539,0.583447,-0.139342,0.104192,0.435545,0.256538,-0.455799,-0.404397,-0.006140,-0.117790,-0.049238,-0.673936,-0.212980,-0.048587,0.057074,-0.303117,0.468628,-0.323487,-0.113811,0.167133,0.237056,0.279162,-0.075699,0.007306,0.111088,0.150345,0.432882,-0.203273,-0.129738,0.163627,0.121644,0.114666,-0.065026,0.039295,0.046633,0.288955,0.313012,-0.378024,0.044871,-0.249419,0.332334,-0.378544,0.141682,0.008643,0.023807,-0.094270,0.181441,0.099263,0.022278,-0.206200,0.202596,-0.308614,-0.819922,0.074306,0.111616,0.046059,-0.369707,0.146697,-0.231443,0.084147,0.216058,-0.365029,-0.032730,0.225800,0.455571,0.380139,-0.086626,0.414570,-0.341947,0.057625,0.320558,0.124866,-0.329051,0.131919,-0.016368,-0.485566,0.068246,-0.182696,-0.586241,0.218077,0.365178,-0.147741,-0.148088,0.368667,-0.591520,-0.219700,-0.354922,-0.181583,0.064398,-0.145061,-0.160141,-0.785080,-0.116842,-0.350028,-0.242203,-0.299620,0.015611,-0.384433,0.604440,-0.795164,0.230358,0.589761,0.017709,-0.295756,0.409956,0.017229,0.095375,-0.318098,-0.050481,0.352097,0.115150,0.236508,0.386509,0.456358,0.295632,-0.225283,-0.263192,0.439300', '1793491', '11810348', '3769423', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4917698', '硬汉2：奉陪到底', '动作', '一桩策划已久的银行抢劫案，由于老三（刘烨 饰）挺身而出，歹徒最终落入法网。老三原本是一名潜艇兵，由于救战友溺水脑部受伤提前退伍。退伍之后，老三依旧每日坚持各种训练，并且不改见义勇为的本性。劫犯黑勇（刘承俊 饰）越狱，在见到已经成为植物人的弟弟之后，黑勇决定从警察的严密监护下救弟弟出院。老三的女友小惠（张梓琳 饰）是韩队长（焦恩俊 饰）的妹妹，为了达到目的，黑勇绑架了小惠。为了救出小惠，老三和韩队都开始用自己的方式与歹徒展开了殊死较量……本片由新锐导演丁晟执导，是2008年硬派幽默警匪电影《硬汉》的续作。©豆瓣', '刘烨', '丁晟', 6.4, 36872, 'tt1883397', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p907601843.jpg', 2.9, 12.9, 52.7, 24.8, 6.7, '-0.209907,-0.386083,-0.251292,0.178969,-0.143377,-0.350676,0.391447,-0.047355,-0.525932,-0.376105,0.620689,0.346011,-0.001282,0.011024,0.326259,-0.320662,-0.256200,-0.456653,-0.161783,0.251996,-0.153121,-0.234088,-0.171463,0.017484,0.124851,-0.248807,0.782155,-0.219768,-0.077686,0.544005,0.465326,0.318869,-0.117832,0.023516,0.273021,-0.005611,0.114586,-0.299645,-0.660998,0.171283,0.102244,-0.160539,-0.062716,-0.028805,0.098680,0.465024,0.727855,-0.113955,-0.128610,-0.070997,0.172248,-0.368866,-0.054414,-0.046806,0.287381,0.047168,0.430515,0.297064,-0.011256,-0.056191,-0.035468,-0.084920,-0.560392,-0.026296,0.279947,-0.126023,-0.415562,0.142312,-0.197870,0.334523,0.265520,-0.481668,0.047217,0.408240,0.245029,0.276361,-0.280899,0.136759,-0.362172,0.362980,0.548066,-0.230713,0.116940,0.140656,0.127956,-0.349175,0.231719,-0.358905,-0.254245,0.306136,0.204322,-0.254732,-0.303280,-0.024313,-0.438393,-0.254699,-0.195896,0.145930,0.001803,-0.113384,0.063139,-0.526873,-0.085383,-0.062024,0.040784,0.000017,-0.114989,-0.129474,0.498710,-0.771185,0.131240,0.230992,0.075980,-0.571805,0.234320,0.146151,-0.023475,-0.402117,0.043141,-0.170242,0.137979,0.382383,0.365800,0.196617,-0.141503,-0.379513,-0.034716,-0.097168', '2369613', '1293265', '30345227', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4917726', '阳光姐妹淘', '剧情', '25年前，高中生任娜美（沈恩京 饰）一家从全罗道搬到汉城，娜美入读真德女子高中，因方言浓重怯于开口的娜美幸运的得到了同班大姐头夏春花（姜索拉 饰）的维护，并与围绕在夏春花周围的执着于双眼皮的金玫瑰、满嘴脏话的黄珍熙、梦想成为作家的徐金玉、要成为韩国小姐的俞福姬以及沉默傲慢的美人郑秀智等五人结识。在一次和不良少女团对决之后，春花和娜美等七人组成了“Sunny”团体……多年以后，家庭主妇娜美在去医院探望母亲时偶然重逢了身患绝症住院的春花，后者希望在生命的最后两个月内，能够再见当年的Sunny成员。娜美找到金玫瑰，两人委托私家侦探寻找当年的同伴，而那些关于青春的回忆，也在一个个熟悉的名姓后面再次被唤醒。©豆瓣', '沈恩京', '姜炯哲', 8.8, 564699, 'tt1937339', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1374786017.jpg', 0.2, 0.8, 9.6, 37.9, 51.5, '-0.005712,-0.099365,-0.493171,0.517789,0.071454,-0.422751,0.673360,0.077146,-0.281966,-0.135907,-0.126098,0.611562,-0.341555,0.692520,0.394407,0.140604,-0.150289,-0.683261,-0.098035,-0.179604,-0.216477,-0.438554,0.188684,-0.054667,-0.048593,-0.266820,0.448891,0.078029,-0.079530,0.694249,0.195517,0.102327,-0.342909,0.230817,-0.058939,-0.049071,0.122541,-0.002712,-0.403212,0.290550,0.020052,-0.071918,-0.092017,-0.112132,0.266869,0.038813,0.852326,-0.433239,0.180863,0.041402,0.463005,-0.126421,0.084266,0.056338,0.357073,-0.174083,0.199725,-0.117997,-0.204957,-0.159873,0.116465,-0.216631,-0.631095,0.280174,0.241337,-0.118256,-0.649114,0.683755,0.279611,0.113432,0.333207,-0.008174,0.389641,0.287621,-0.072051,0.234171,0.117710,0.385039,-0.286098,0.343297,0.509300,0.193201,-0.010398,0.360453,-0.171297,-0.471878,-0.195148,-0.120577,-0.354257,0.173281,0.383701,0.134098,0.023781,-0.247611,-0.628639,-0.252042,-0.338878,0.073570,0.351507,-0.351575,-0.397867,-0.495039,-0.141084,-0.408703,-0.201076,0.295540,0.101837,-0.098654,0.895430,-0.857505,0.127852,0.446942,0.178477,-0.622795,0.617873,0.103470,0.083165,-0.060072,-0.164741,0.406127,0.118440,0.346353,0.326646,0.355545,-0.328049,0.268008,-0.412408,0.014708', '3811356', '25922902', '1292219', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4919019', '天际浩劫', '动作', 'Jarrod（艾里克•巴弗尔 Eric Balfour 饰）和妻子Elaine（斯考蒂•汤姆森 Scottie Thompson 饰）应朋友Terry（唐纳德•法森 Donald Faison 饰）之约，来洛杉矶参加他的生日派对。后者做生意发了横财，不但买了摩天楼的豪宅，一切电器全自动。而且身边美女如云，更重要的是，他准备拉Jarrod入伙。而此事却遭到了Elaine的强烈反对。原来，后者已经怀孕，这让Jarrod不知所措。当天夜里，他们先后发现一阵蓝色强光从窗外射入。有人被吸入强光之中丧命，Jarrod险些中招，幸好Terry相助才逃过一劫。此后，这强光先后从天际坠落，勇敢的Terry和Jarrod在天台赫然看到了不可思议的景象，Jarrod还拍下了照片：若干个散发着刺目蓝光的巨大外星生物先后在地球着陆，而他们的摩天楼也成为了外星人的猎物，周围的朋友一个个被吸走丧生，人类面临一场浩劫……', '艾里克·巴弗尔', '科林·施特劳斯', 4.7, 37635, 'tt1564585', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p678366194.jpg', 23.4, 32.8, 31.2, 8.8, 3.8, '-0.004142,0.002041,-0.956440,0.256242,0.149854,-0.062773,0.794065,0.193060,-0.219130,-0.076369,0.267386,0.750303,-0.523281,0.181935,0.304617,0.053403,-0.128592,-0.551058,-0.133824,-0.195223,-0.453832,-0.087862,-0.268053,-0.190669,0.078769,-0.257955,0.276091,0.140331,-0.027346,0.572431,0.372773,0.258580,-0.114602,0.652499,-0.068390,-0.141378,-0.160908,0.150574,-0.028068,0.184006,-0.149201,-0.397203,0.017737,0.125233,-0.162503,0.342271,0.549257,-0.255182,0.102421,-0.244407,0.276491,-0.430960,0.115960,0.243770,0.331045,0.138236,0.034630,-0.265652,-0.148156,-0.161244,0.111370,0.116256,-0.516145,0.058552,0.085621,-0.025579,-0.447041,0.317384,0.033329,-0.078377,0.070733,-0.237116,0.337753,0.292329,-0.017751,0.256980,-0.204747,-0.047986,-0.453387,-0.067768,0.447827,-0.145932,-0.272429,0.324607,-0.237927,-0.327729,-0.086435,0.189573,-0.170562,-0.002958,0.785506,0.138949,-0.059007,0.345920,-0.624542,0.034867,-0.102557,-0.316158,-0.407067,-0.249697,-0.243380,-0.536538,-0.202282,-0.164411,-0.430927,0.321904,-0.117174,0.146901,0.374749,-0.323531,0.199215,0.417622,0.445115,0.077706,0.632143,-0.195138,-0.001718,0.144432,0.019704,0.031689,0.381355,0.454494,0.173185,0.189697,0.010558,0.040578,-0.240918,0.370355', '3011051', '26882457', '4832825', '4724373');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4919232', '非法入侵', '剧情', '米勒一家似乎拥有所有人都梦寐以求的生活：豪宅、跑车、美满的家庭。在一个普通的日子，美丽的妻子萨拉（妮可·基德曼 Nicole Kidman 饰）迎接出差回家的丈夫，成功的钻石采购商凯尔（尼古拉斯·凯奇 Nicolas Cage 饰）。凯尔回家的同时青春期的女儿则艾弗瑞（丽亚娜·莱伯拉托 Liana Liberato 饰）瞒着父母偷偷溜出家门去参加朋友家的派对。可是天有不测风云，一伙由四人组成的抢劫团伙闯进米勒家，绑架了夫妇二人欲实施抢劫。艾弗瑞参加完派对回家也不幸撞到了家中正在发生的悲剧。面对丧心病狂的劫匪，米勒一家将怎样解除危机？他们是否会安然无恙？而这看似普通的抢劫背后是否又有不为人知的阴谋和肮脏的秘密？©豆瓣', '尼古拉斯·凯奇', '乔·舒马赫', 5.7, 10141, 'tt1674784', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1260906214.jpg', 5.6, 25, 52.1, 13.9, 3.4, '0.426313,-0.106844,-0.605770,0.206638,-0.171090,-0.158121,0.733391,0.183689,-0.167874,-0.349253,0.428731,0.603123,-0.053169,0.225751,0.537304,0.208367,-0.294329,-0.321230,0.172536,-0.024563,-0.256779,-0.336858,-0.228892,-0.195343,0.272262,-0.159000,0.202004,0.115613,0.102792,0.544639,0.495287,0.524412,-0.416997,0.209675,-0.106478,0.046178,0.324826,0.261018,-0.343799,0.134609,-0.065522,-0.043874,-0.123215,0.033232,0.186774,0.205745,0.489392,-0.111921,0.100363,-0.127715,0.270224,-0.217224,0.027646,0.270741,0.337560,-0.085019,0.132027,0.248783,-0.134802,0.013867,0.296228,-0.031894,-0.650972,0.188084,0.348693,0.013155,-0.538808,0.336175,-0.044380,0.005020,0.247149,-0.165594,0.125197,0.631491,0.167219,0.501312,-0.055669,0.200597,-0.786380,0.028409,0.876704,-0.211642,-0.014403,-0.020242,-0.130711,-0.101674,0.170723,-0.274001,-0.651483,0.032068,0.394648,-0.039835,-0.268822,0.189658,-0.507449,-0.091903,-0.387827,-0.041765,0.258129,-0.403835,-0.177223,-0.972336,0.104003,-0.258995,-0.361617,0.020961,0.063441,-0.197637,0.447317,-0.549630,0.220807,0.545089,0.328351,-0.566910,0.587978,0.019951,0.303304,-0.111377,-0.302867,0.143145,0.292956,0.193943,-0.187530,0.167826,0.127349,-0.136020,-0.081780,0.400485', '3147969', '10466639', '3183490', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4920389', '头号玩家', '动作', '故事发生在2045年，虚拟现实技术已经渗透到了人类生活的每一个角落。詹姆斯哈利迪（马克·里朗斯 Mark Rylance 饰）一手建造了名为“绿洲”的虚拟现实游戏世界，临终前，他宣布自己在游戏中设置了一个彩蛋，找到这枚彩蛋的人即可成为绿洲的继承人。要找到这枚彩蛋，必须先获得三把钥匙，而寻找钥匙的线索就隐藏在詹姆斯的过往之中。韦德（泰尔·谢里丹 Tye Sheridan 饰）、艾奇（丽娜·维特 Lena Waithe 饰）、大东（森崎温 饰）和修（赵家正 饰）是游戏中的好友，和之后遇见的阿尔忒弥斯（奥利维亚·库克 Olivia Cooke 饰）一起，五人踏上了寻找彩蛋的征程。他们所要对抗的，是名为诺兰索伦托（本·门德尔森 Ben Mendelsohn 饰）的大资本家。©豆瓣', '泰伊·谢里丹', '史蒂文·斯皮尔伯格', 8.7, 1279650, 'tt1677720', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2516578307.jpg', 0.4, 1.3, 11.9, 37.8, 48.6, '0.107851,0.138090,-0.535261,0.597949,0.003052,-0.278594,0.510532,-0.014743,-0.348198,-0.219537,0.070684,0.841481,-0.179592,0.059270,0.287179,0.377100,-0.584486,-0.729511,0.000375,-0.439310,-0.472751,-0.625939,-0.569644,-0.282592,0.048681,-0.257996,0.640049,0.134434,-0.144872,0.079910,0.142480,0.346130,-0.249683,0.099752,-0.303311,0.073902,0.271999,-0.067141,-0.309747,0.352840,-0.262949,0.006820,-0.118485,0.151206,0.286428,0.225957,0.512555,-0.499645,0.372084,-0.036460,0.036587,0.013265,-0.232690,-0.220437,0.050103,-0.090069,0.174611,0.330355,-0.318082,0.125911,0.294069,-0.547692,-0.916406,-0.063975,-0.009086,0.305800,-0.495174,0.257608,-0.198713,-0.081970,0.132737,-0.292092,0.274170,0.156944,0.400314,0.149248,0.006519,-0.276893,-0.473740,0.104147,0.169230,-0.168542,-0.121138,0.337621,-0.078459,-0.284762,-0.188172,0.018051,-0.499954,-0.117624,0.597702,0.192085,0.068683,0.269690,-0.911522,0.058278,-0.442964,-0.351668,0.304217,-0.170530,-0.172287,-0.824630,-0.005806,-0.200295,-0.278345,0.067335,0.017646,-0.348750,0.641865,-0.744073,0.263830,0.371889,0.157897,-0.199616,0.655991,-0.238142,0.430075,-0.315124,-0.048224,0.105032,0.092008,0.322948,-0.000999,0.309515,0.014754,-0.177549,-0.669791,0.610478', '1308585', '26577354', '25928048', '1793922');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4920528', '那些年，我们一起追的女孩', '剧情', '青春是一场大雨。即使感冒了，还盼望回头再淋它一次。人生就是不停的战斗，在还没有获得女神青睐时，左手永远都只是辅助！！！柯景腾（柯震东 饰）和他的一群好友，爱耍帅却老是情场失意的老曹（敖犬 饰），停止不了勃起所以叫勃起的勃起（鄢胜宇 饰），想用搞笑致胜却总是失败的该边（蔡昌 宪 饰），胖界的夺爱高手阿和（赦绍文 饰），从国中到高中，一直是不离不弃的死党。他们都对班花沈佳宜（陈妍希 饰）有着一种纠结的感情。一方面，他们瞧不起这种只会用功读书的女生，另一方面他们又为她的美好气质倾倒。因为学习成绩较差，柯景腾被老师安排坐在沈佳宜前面。因为他的一次英雄救美，她开始用强制的方式帮他补习功课。此事令其他兄弟羡慕嫉妒恨，但是大家都未说破。毕业后，柯景腾和沈佳宜在各自大学保持恋人般的联系。直到他举办自由格斗赛，事情才出现了变化…… 这一连串下，原本按兵不动的好友也都纷纷加入女神争夺战！但是麻吉诚可贵，青春价更高，若为女神故，是否二者皆可抛哩？！本片根据导演兼编剧九把刀在2007年的自传体小说改编。柯震东凭借本片获第48届金马奖最佳新演员。', '柯震东', '九把刀', 8.1, 848880, 'tt2036416', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1348910586.jpg', 0.5, 1.9, 20.7, 45.8, 31.2, '-0.018449,-0.196206,-0.549981,0.647197,-0.000757,-0.410645,0.478571,-0.002089,-0.238180,-0.148072,0.119138,0.489062,-0.273761,0.272157,0.065899,-0.336154,-0.232760,-0.697734,0.059588,0.020212,-0.130888,-0.219024,-0.164912,-0.009418,-0.177980,-0.243857,0.814441,-0.085062,-0.223203,0.360437,0.491563,-0.005614,0.125657,0.410456,-0.005607,-0.060982,-0.104506,0.264292,-0.297626,0.071869,0.203335,-0.291687,-0.261879,0.120848,0.185185,0.258725,0.644532,-0.264846,-0.187990,0.125488,0.449896,-0.330996,-0.107600,0.091539,0.167764,-0.002640,0.269645,0.176101,0.064544,0.213778,-0.036706,0.025012,-0.737972,-0.036898,0.213758,-0.010636,-0.371909,0.570184,-0.034133,-0.135293,0.195433,-0.182797,0.118307,0.303739,0.377763,0.297741,-0.312215,-0.096723,-0.138525,0.526432,0.754142,0.206320,-0.259309,0.452081,-0.096166,-0.422143,0.024475,-0.209927,-0.578381,0.143699,-0.081649,0.087870,0.125044,0.197068,-0.372728,-0.041868,0.061976,0.010224,-0.027197,-0.477928,0.132917,-0.431129,0.032503,-0.401495,-0.199480,0.106859,0.220678,-0.398026,0.784849,-0.867788,0.212548,0.400271,0.208748,-0.585878,0.670617,0.444581,-0.037458,-0.222621,-0.366177,0.185405,-0.117514,0.055334,0.088189,0.304898,0.069388,-0.102460,-0.272194,0.359356', '35030151', '5985887', '6101834', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4922789', '激浪青春', '爱情', '年轻貌美的皮划艇运动员阮小月（陈乔恩 饰），痛失即将结婚的教练男友何天华（黄晓明 饰），寻求真相心切的她，在有望成为未来之星的运动生涯关键时刻突然离队，带着种种疑惑，只身来到一所大学担任校龙舟队的临时教练。阮小月的到来，打碎了龙舟队的大男孩们一边嬉闹一边看美女的美梦，取而代之的是无止境的魔鬼式训练及麻辣教练臭脸相伴的噩梦，无限制地挑战着大男孩们的小心脏和小肌肉。导致以龙舟队队长（黄轩 饰）为首的队员们使劲儿作对，想尽办法逃出生天。倍受校方质疑的阮小月，黯然离开龙舟队，与此同时，大男孩们得知了阮小月的爱情秘密及无法言语的委屈，他们采取了一种特别的道歉方式，将阮小月请回龙舟队，并最终一举夺冠。阮小月终于明白了天华对自己无限的爱与支持，也终于理解了天华热衷于龙舟的真正原因，更找到了属于自己的未来……©豆瓣', '黄晓明', '梁柏坚', 4.2, 3907, 'tt8690024', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2183321312.jpg', 33.9, 34.2, 22.4, 4.5, 5, '-0.059424,0.053591,-0.472592,0.521615,-0.078066,-0.168011,0.380696,0.071885,-0.483640,-0.071207,0.291108,0.702247,-0.065727,0.422482,0.217306,-0.260698,-0.058951,-0.673221,-0.346649,-0.144950,-0.365041,-0.427216,-0.062645,0.121505,0.016252,-0.065909,0.736336,-0.085310,-0.263925,0.589406,0.505647,0.171793,0.236832,0.191050,-0.270237,0.022326,0.143426,0.137844,-0.303799,0.000564,0.151813,-0.032905,-0.369165,0.192943,-0.084362,0.185538,0.656236,-0.431215,0.037555,-0.144278,0.285263,-0.302921,0.037248,0.267286,0.071427,0.130619,0.063968,0.051912,-0.067050,0.250761,0.126838,-0.042085,-0.684216,0.089206,0.104200,0.215661,-0.535343,0.399010,0.020912,-0.205267,0.435332,-0.200317,-0.067005,0.353070,0.080139,0.332674,-0.438237,0.213494,-0.288474,0.178156,0.601709,0.021222,-0.139232,0.072064,-0.172988,-0.183215,0.018585,-0.292479,-0.478581,-0.147022,0.353066,0.275738,-0.033016,0.207357,-0.510285,-0.057217,-0.173394,-0.285517,0.072699,-0.381858,-0.064502,-0.617108,0.173404,-0.194802,0.111745,0.024757,0.190501,-0.187958,0.939478,-0.932017,0.107132,0.370509,0.241801,-0.611848,0.394347,0.340820,0.156291,-0.299143,-0.277175,0.259127,-0.123410,0.434346,-0.014530,0.396169,-0.180132,-0.244518,-0.370928,0.167385', '25922902', '3811356', '4127270', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4922850', '绝命岛', '喜剧', '亿万富豪龙哥（刘桦 饰）的独生子因意外身亡，悲痛之际，龙哥将儿子的心脏取出，发誓找到合适的人选将心脏移植过去，并继承自己的泼天财富。在管家阿雪（林雪 饰）的主持下，东南亚范围内7名与儿子有着同样罕见血型的男女进入龙哥视线，他们是时尚女孩山寨妹（霍思燕 饰）、史上最强二奶珍珠奶茶、台湾黑帮头目雷龙（戎祥 饰）、二人转演员小漠河、日本相扑花田、推理爱好者学生妹以及印度的瑜伽师。这7人被绑架到一座位于国际公海中心的孤岛上，被迫参加龙哥为他们量身定做的恐怖选拔赛。随着考验的进行，战况愈加激烈。而在这一过程中，一场阴谋也在悄悄地进行着……©豆瓣', '刘桦', '冯超', 3.1, 5980, 'tt6449204', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p638645213.jpg', 59.9, 26.5, 10.8, 1.6, 1.1, '0.024451,0.039551,-0.813987,0.518027,0.133507,0.091272,0.530541,0.019123,-0.533250,0.065011,0.404876,0.641357,-0.111568,0.093366,0.288940,0.077171,-0.139254,-0.599569,-0.392563,-0.156590,-0.382628,-0.307939,-0.179452,-0.019921,-0.070139,-0.335729,0.579642,0.025905,-0.288993,0.410098,0.442287,0.175322,-0.168589,0.182843,0.005888,-0.040462,0.196118,-0.088497,-0.257955,0.241911,-0.085888,-0.301911,0.202977,0.035006,0.013837,0.174029,0.781066,-0.302990,0.205130,-0.237385,0.426253,-0.147306,-0.261383,0.050647,0.310620,-0.026108,0.268284,0.066206,-0.047714,-0.018219,0.172852,-0.277367,-0.624853,-0.024968,0.285756,0.123765,-0.470876,0.425117,-0.110607,-0.106857,0.152848,-0.299216,0.289061,0.147024,0.359776,0.189535,-0.244958,0.117743,-0.150395,0.325954,0.591334,0.115903,-0.129253,-0.151214,-0.061611,-0.603752,-0.045382,-0.280506,-0.166073,0.018742,0.481442,-0.104717,0.081503,0.013293,-0.486250,0.049063,0.113496,-0.245551,0.131664,-0.033307,-0.140004,-0.647402,-0.051174,-0.358633,-0.143251,-0.050885,0.227087,-0.214412,0.640637,-0.753117,0.079653,0.664415,0.289683,-0.064318,0.599435,-0.196230,0.318355,-0.378962,-0.432356,-0.093645,0.046787,0.353144,0.048556,0.429387,-0.279740,-0.160287,-0.223545,0.143698', '3811356', '25928048', '3804656', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4924142', '时间规划局', '动作', '在未来，人类可以随心所欲的操控时间，改写年龄。在人类社会，不管这个人活多久，他的年龄被永远定格在25岁。因为没有了自然死亡，为了避免人口膨胀。人类社会抛弃了以往的货币，改用时间作为货币流通。一个人的时间用完之后，这个人就会死亡。一个名叫威尔（贾斯汀·丁伯莱克 Justin Timberlake 饰）的穷人，却意外获得了一笔巨大的财富，拥有了用不完的时间。但是却因为此事被锁定为一场谋杀案的嫌疑人，由此走上了逃亡之路。在逃亡过程中，绑架了时间银行的女继承人（阿曼达·塞弗里德 Amanda Seyfried 饰）。在整个逃亡过程中，他们之间迸发出了感情的火花。而且两人都对现有的时间管理机制都非常不满，进而联手起来对抗这个统治机构。仅凭两人之力能够推翻成熟的权力机构吗？©豆瓣', '阿曼达·塞弗里德', '安德鲁·尼科尔', 7, 210463, 'tt1637688', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1166966337.jpg', 1, 7.2, 43, 36.7, 12.1, '-0.058763,0.398737,-0.673506,0.611018,-0.276357,-0.204105,0.748944,0.119251,-0.496823,-0.198146,0.050344,0.538821,0.014090,-0.117303,0.193165,-0.350130,-0.326222,-0.736533,-0.048941,-0.269094,-0.490285,-0.416474,-0.199695,-0.338400,-0.273264,-0.462836,0.569891,0.132478,-0.238692,0.200843,0.000433,0.096617,0.068381,0.433046,-0.162748,-0.079961,0.265126,-0.139353,-0.195298,0.289832,0.014753,-0.212677,0.161423,0.330096,-0.213989,0.433466,0.665897,-0.280031,-0.156343,-0.254794,0.259501,-0.319119,-0.277417,0.072613,0.292090,-0.262955,0.316625,0.140038,-0.197780,-0.038676,0.177754,0.027765,-1.139245,-0.048593,-0.053844,0.228331,-0.406917,0.476462,0.016015,-0.152372,-0.277325,-0.321682,-0.009128,0.715666,0.407353,0.239790,-0.500864,-0.180922,-0.724359,0.113165,0.787922,-0.243344,-0.618679,0.516155,-0.506301,-0.603033,-0.556501,-0.372692,-0.263788,-0.318767,0.444743,0.096224,-0.181269,0.620627,-0.718965,-0.046155,-0.124474,-0.259662,0.120176,-0.541392,-0.023483,-0.355079,-0.291274,-0.538114,-0.484578,0.211490,0.282420,-0.375613,0.781063,-0.637427,0.044318,0.619795,0.495095,-0.562506,0.791824,-0.046703,0.266829,-0.151823,0.124103,0.240799,0.056396,0.480592,0.087319,0.205801,0.069339,-0.156253,-0.364547,0.791583', '26678784', '30163500', '1811755', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4924694', '自杀专卖店', '喜剧', '死气沉沉的法国小城，一家有口皆碑的老店却格外生意兴隆。原来这家祖传老店代代皆以贩卖自杀产品著称。在如此灰暗恐怖的小镇上，自杀成了当地居民稀松平常之事，这也是小店异常火爆的原因。经营此店的老板三岛了无生气，老板娘更是日日愁眉苦脸。他们早就丧失了对生活的热情，终日郁郁不安。长期贩卖自杀用品，让他们濒临崩溃的边缘。幸好他们的一双儿女还热爱着生活，尤其是他们的小儿子阿伦，笑容总是挂在他的脸上。然而，阿伦热爱生活的态度却威胁着老店的经营，父亲想尽办法让阿伦变得消沉，甚至把阿伦逼上了绝路……本部极富想象力的法国动画电影，改编自法国漫画家让·特磊的畅销小说。曾执导《理发师的情人》等影片的法国导演帕特利斯·勒孔特，此次首度尝试制作动画影片。影片不仅处处体现着法式特有的黑色幽默，还加入了大量歌舞元素，借这些载歌载舞的动画人物之口，道出生与死间的深刻哲理。©豆瓣', '贝纳德·阿兰尔', '帕特里斯·勒孔特', 7.3, 57031, 'tt1655413', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1558595836.jpg', 0.7, 5.2, 38.4, 39.8, 15.9, '0.143031,0.044771,-0.616416,0.716036,0.072152,-0.320885,0.692882,0.333383,-0.525733,-0.059043,0.177800,0.723041,-0.151709,0.231970,0.184927,0.110271,-0.175321,-0.341276,-0.391826,-0.026134,0.158281,-0.190704,-0.449260,-0.135247,-0.349008,-0.200163,0.404070,0.232840,-0.302811,0.352672,0.116657,0.175462,0.180281,0.281791,-0.120288,-0.086678,-0.053483,-0.108401,-0.190295,-0.102372,0.144488,-0.327970,-0.186465,0.202179,0.036822,0.418010,0.546659,-0.105302,-0.308362,-0.016918,0.419697,-0.220268,0.032784,0.248680,0.156602,-0.113046,0.266810,0.159268,-0.364899,-0.003397,0.094155,0.043913,-0.892577,0.108979,0.224972,-0.051403,-0.657412,0.354852,0.076151,-0.054240,-0.062361,-0.382833,0.222881,0.133353,0.218616,0.432845,0.079773,-0.017098,-0.499018,0.337268,0.580456,-0.092125,-0.348940,0.219581,-0.447391,-0.363530,0.127043,-0.504437,-0.617099,-0.087369,0.131157,-0.169146,0.145056,0.241566,-0.821805,0.212499,-0.029051,-0.205114,-0.013892,-0.165958,-0.092399,-0.960344,-0.069540,-0.434416,-0.233977,-0.122622,0.201617,-0.097040,0.668737,-0.582077,0.115782,0.457609,0.119637,-0.327068,0.486773,-0.024441,-0.083217,0.043058,-0.500127,0.239312,-0.054473,0.277599,0.108827,0.338872,0.061488,-0.067615,-0.153161,0.701654', '3318306', '19965431', '1793491', '10763928');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4924799', '伤心小号曲', '剧情', '肥胖忧郁的哈维尔（Carlos Areces 饰）出生于西班牙一个小丑世家，他的父亲死于内战，生前曾嘱咐这个背负了太多痛苦的儿子做一个悲伤小丑。时过境迁，成年后的哈维尔求职来到一家马戏团，遇到了当家小丑赛吉（Antonio de la Torre 饰）以及美艳的杂技女明星纳塔莉娅（Carolina Bang 饰）。他们是一对情侣，生活中的赛吉嗜酒狂暴，经常对纳塔莉娅饱以老拳，后者虽然痛苦不堪，却又无比沉缅于这份变态的暴力之中。哈维尔爱怜这株时常为暴风雨摧残的柔弱小花，而纳塔莉娅也渐渐喜欢上哈维尔的单纯善良。以此为契机，这三个人纠缠出了一段血腥的畸零人生……本片荣获2011年歌雅奖最佳发型设计、最佳特效奖；2010年威尼斯国际电影节最佳剧本奖和银狮奖最佳导演奖。©豆瓣', '圣地亚哥·塞古拉', '艾利克斯·德·拉·伊格莱希亚', 7.6, 7756, 'tt1572491', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p709363799.jpg', 1.2, 4.6, 27.7, 45.1, 21.4, '0.128974,0.048079,-0.353679,0.564270,-0.183971,-0.159763,0.829323,-0.025790,-0.509401,-0.129474,0.294297,0.998973,-0.236377,0.153468,0.213604,0.060848,-0.312157,-0.576354,-0.085917,-0.078243,0.151654,-0.244303,-0.511635,0.319331,-0.134286,-0.314059,0.541260,-0.127107,0.086520,0.574546,0.586075,0.308629,0.076964,-0.065039,-0.069942,0.079207,0.160650,0.216393,-0.216013,0.146867,-0.063717,-0.321472,-0.209300,-0.000777,-0.158957,0.148824,0.593270,-0.233260,-0.152038,-0.429393,0.654464,-0.219892,-0.195101,0.118811,-0.034950,-0.220409,0.400630,-0.142885,-0.324212,0.143740,0.059050,-0.283589,-0.797422,0.227979,0.068183,0.195645,-0.518011,0.424567,0.018359,-0.033821,0.064859,-0.042346,-0.006579,0.187041,0.313568,0.441739,-0.225498,0.021646,-0.149470,0.505248,0.442829,0.208237,-0.516126,0.250885,-0.369142,-0.394818,0.140745,-0.454863,-0.521166,0.026240,0.464532,-0.121424,-0.148225,0.378023,-0.678763,0.196938,-0.111692,-0.047827,-0.102837,-0.177735,-0.241790,-0.629831,-0.033253,-0.421170,-0.238944,-0.126109,0.115022,-0.321430,0.594302,-0.507312,0.382198,0.454838,0.150576,-0.284102,0.450890,0.152543,0.028849,-0.138789,-0.226341,0.493444,-0.307109,-0.187385,-0.038533,0.430707,-0.054114,-0.142725,-0.382288,0.610407', '34890458', '30162520', '1294434', '35161768');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4925418', '伤物语1：铁血篇', '喜剧', '樱花飞舞的3月25日，完成了一学期学业的午后。高二学生阿良良木历（神谷浩史 配音）从优等生羽川翼（堀江由衣 配音）那里听说了本町出现吸血鬼的传言。当晚，历在地铁站台见到了一个血淋林的女人。她四肢全无，痛苦求救。而女人的身后则站着一个金色头发却目光阴冷的身影，那难道就是传言中的吸血鬼？在这个夜晚，历与活了500年的吸血鬼姬丝秀忒•雅赛劳拉莉昂•刃下心（坂本真绫 配音）完成了命运的相逢……本片根据西尾维新的轻小说改编，将以剧场版三部曲的形式上映。©豆瓣', '神谷浩史', '新房昭之', 8.4, 9725, 'tt3138698', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2271912811.jpg', 0.9, 2.5, 15.3, 36.4, 44.9, '0.259109,-0.095913,-0.269092,0.490013,0.048291,-0.255667,0.641478,0.279379,-0.169734,-0.095771,0.352862,0.511486,-0.359627,0.298738,0.376820,0.093256,-0.215181,-0.730018,-0.337780,-0.407500,-0.224624,-0.084094,-0.043104,0.080889,0.008324,-0.386512,0.886828,0.069204,0.185240,0.529121,0.250957,-0.085633,-0.075271,0.008645,-0.024981,-0.086152,0.038340,-0.009953,0.220208,0.332319,-0.144111,-0.428500,-0.244321,-0.069190,-0.054324,0.273774,0.786789,-0.348286,0.059333,-0.227624,0.734475,-0.203656,-0.376718,0.117416,0.494293,-0.077482,0.090030,0.221359,-0.094414,-0.168678,-0.021287,-0.280529,-0.524829,0.090682,-0.286018,0.359777,-0.291582,0.459606,-0.201251,0.018631,0.262232,-0.246352,0.159354,-0.090469,0.265971,0.342532,-0.554679,0.085277,-0.180079,0.502678,0.166659,0.177684,-0.344881,0.227187,-0.117869,-0.451657,-0.348229,0.194096,-0.120543,-0.125649,0.318479,-0.052283,-0.255720,0.200081,-0.377423,-0.078261,0.076804,-0.169617,0.017551,-0.359808,-0.624426,-0.698882,-0.093136,-0.216197,-0.068767,0.030464,0.168448,-0.187716,0.756897,-0.746960,0.025090,0.615290,0.271264,0.273457,0.598425,-0.085545,0.062588,0.016875,-0.028677,0.177962,-0.030039,0.456752,0.372760,0.559003,-0.093917,-0.066998,-0.373714,0.416329', '3811356', '1322847', '10174444', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4926002', '举起手来2：追击阿多丸号', '喜剧', '1945年，第二次世界大战接近尾声，轴心国已成强弩之末，败局已定。许多战争中被俘虏的日本士兵经过改造后，陆续踏上回国的旅途，这其中便包括罗圈腿中村下等兵（潘长江 饰）。然而，即使在这垂死关头，帝国主义的贪婪仍旧没有收敛。轮椅太君（胡晓光 饰）伤愈出院，亲自负责指挥战舰阿多丸运送伤兵回国的重任，但是阿多丸还有一个秘密任务，那就是将从中国劫掠来的文物偷运出境。这个秘密被小刘（刘小微 饰）的父亲——一个文物老专家所得知，他掌握着所有文物的清单，也因此遭到日寇的追杀。临死之际，老教授将藏有清单的可乐瓶交给担任联络员的郭大叔（郭达 饰）。侦知到日本人的阴谋，八路军以及重庆方面的势力都行动起来。而在这一过程中，更大的阴谋也悄悄浮出水面……©豆瓣', '潘长江', '冯小宁', 5.4, 41316, 'tt6449936', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p608078423.jpg', 17.1, 25.8, 36.7, 13.1, 7.3, '0.199937,0.096263,-0.802299,0.472508,-0.064755,-0.310352,0.532633,-0.255645,-0.429128,-0.398295,0.218637,0.485988,0.131278,-0.095708,0.220392,-0.221446,-0.364453,-0.585693,-0.345240,-0.127294,-0.446124,-0.351126,-0.230746,-0.185668,-0.071093,-0.211351,0.612770,0.486898,-0.040683,0.523372,0.332168,0.306239,-0.067762,0.527703,0.044926,0.110716,0.220557,-0.407433,-0.152692,0.138327,0.011851,-0.480306,-0.025979,0.058774,0.019449,0.361265,0.813526,-0.202389,-0.020281,-0.097953,0.122722,-0.455402,0.024014,0.081961,0.500846,0.372426,-0.146692,0.322874,-0.412115,0.133174,0.076543,-0.078509,-0.614135,-0.199743,-0.004803,0.196945,-0.458304,0.142729,-0.158005,0.461312,-0.143683,-0.414104,0.407382,0.709331,0.127938,0.121041,-0.161091,0.066466,-0.763409,0.228282,0.402839,-0.255879,-0.026061,-0.144944,-0.002078,-0.513190,0.164333,-0.405309,-0.028082,-0.043422,0.357239,-0.075849,-0.128090,0.100556,-0.572235,-0.080550,-0.142180,-0.383992,0.052314,-0.098931,-0.119443,-0.690460,-0.137501,-0.255159,-0.223005,0.496343,0.336632,0.075985,0.858732,-0.332906,0.231353,0.471443,0.061727,-0.366400,0.363827,-0.078911,0.314167,-0.157899,-0.144653,0.071432,0.142627,0.596281,0.236078,0.341298,-0.152478,-0.484890,-0.312951,0.053781', '3811356', '25863940', '10467125', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4927785', '古城荆棘王', '科幻', '近未来，被世人称为“美杜莎”的后天性细胞硬化症候群（ACIS）泛滥全球，被感染者经过30~60的潜伏期后，在短短的12天内就会病发身亡。死时全身石化，其状恐怖。由于没有任何的特效药和对峙办法，人类世界陷入一片末日般的恐慌之中。就在此时，科学研发企业维纳斯门宣称可通过冷冻睡眠的办法为人类保留生命的希望，但是全球仅有160人有资格走入冷冻胶囊。女孩一色霞（花泽香菜 配音）幸运地成为160人中的一员，但是她也要被迫和相亲相爱的双胞胎姐妹生离死别。当小霞再次醒来时，发现维纳斯门总部情景怪异，接着一群奇怪生物袭击了这些人，最终只有极少数人侥幸活了下来。等待小霞的，将会是怎样残酷的命运……本片根据岩原裕二的同名原著漫画改编。©豆瓣', '花泽香菜', '片山一良', 7.5, 7579, 'tt1690483', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2233901739.jpg', 1.1, 4.2, 30, 45.9, 18.9, '-0.191948,0.205620,-0.551878,0.239458,0.229953,-0.009178,0.830392,-0.020594,-0.589421,-0.169576,0.196422,0.491867,-0.305286,0.138929,0.044817,-0.147912,-0.099829,-0.504431,-0.343357,-0.239160,-0.643303,-0.104924,-0.239981,-0.328647,0.119998,-0.442417,0.920745,0.229345,-0.292856,0.124543,-0.019515,0.280662,-0.397563,0.376291,0.069549,-0.085548,0.171253,0.037384,-0.344979,0.199920,-0.190458,0.107142,-0.025189,0.095763,-0.256987,0.246070,0.562115,-0.417654,-0.343610,-0.216593,0.373132,-0.157595,-0.443890,-0.012425,0.452700,-0.098880,0.261825,0.010283,0.102984,0.094597,-0.051909,0.104572,-0.992917,-0.086163,0.075337,0.231222,-0.247361,0.529757,0.128533,-0.156504,0.021077,0.002069,0.269436,0.265770,0.487313,0.484616,-0.216562,0.089041,-0.438626,0.211692,0.626830,-0.210373,-0.981699,0.522346,-0.259342,-0.445975,-0.236503,-0.328105,-0.175625,0.078406,0.260749,0.443816,-0.433553,0.328166,-0.555702,0.043948,-0.285437,-0.247129,-0.071439,-0.113407,-0.071336,-0.436380,-0.083552,-0.051687,-0.185022,0.292132,0.116641,-0.384343,0.809940,-0.692531,0.366810,0.253205,0.255455,-0.418226,0.466814,-0.046721,-0.005554,-0.245729,-0.161625,0.559208,0.106731,0.138680,0.130522,0.129670,-0.073159,0.068308,-0.316527,0.210930', '26667010', '24284209', '3718279', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4930393', '源氏物语：千年之谜', '剧情', '此版《源氏物语 千年之谜》由鹤桥康夫执导，不仅使用CG，还加入动作场面和科幻效果，制作费用高达十亿多日元(折合人民币7千8百多万)，于2011年12月10日在日本全国公映。影片把原著作者紫式部(中谷美纪 饰)身处的平安时期与光源氏（生田斗真 饰）所在天下相交错，两条线 索并行。一个空间中紫式部受藤原道长（东山纪之 饰）任命开始创作《源氏物语》，并与藤原道长发生了爱情牵绊。另一个空间是紫式部创作出的光源氏与藤壶女御（真木阳子 饰）、六条御息所（田中丽奈 饰）、夕颜（芦名星 饰）等众多女性的爱情纠葛。在关闭的创作进程中，紫式部现出了灵魂出窍的状态，与笔下对光源氏陷入苦恋而化为生灵的六条御息所的灵魂重叠。阴阳师安倍晴明（洼冢洋介 饰）发现了这个情况，开始追踪生灵……©豆瓣', '生田斗真', '鹤桥康夫', 6.6, 18404, 'tt1705064', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1235872084.jpg', 1.2, 9.7, 53.4, 27.8, 7.9, '-0.079628,0.141675,-0.250621,0.388155,0.299991,-0.142990,0.434191,0.171858,-0.263926,-0.605834,0.091072,0.523788,-0.445515,0.111148,0.147295,-0.146606,0.009968,-0.436249,-0.030534,-0.229977,0.062451,-0.347833,-0.049647,0.027667,-0.293653,-0.484006,0.812859,0.263322,-0.126364,0.120252,0.110448,0.461393,-0.465529,0.061670,0.211908,0.127158,-0.110480,-0.070723,-0.317398,0.338945,-0.445801,-0.329928,0.153462,-0.037426,-0.081341,0.156148,0.877528,-0.495366,-0.149301,-0.078346,0.510442,0.113006,-0.374979,0.099454,0.180490,0.220270,0.396935,0.341218,-0.287374,0.264210,0.047035,-0.201211,-0.395905,-0.265833,0.220920,0.278626,0.038756,0.147813,-0.125067,-0.321710,0.020385,-0.223897,0.098836,0.188308,0.609893,0.230872,-0.369936,-0.120667,-0.245120,0.211846,0.170326,-0.219260,-0.301564,0.412164,0.008968,-0.601324,-0.663980,-0.008254,0.071953,-0.014722,0.181549,0.186591,0.226651,0.363868,-0.697483,0.063289,-0.140809,-0.084405,0.027344,-0.090670,-0.009068,-0.610049,-0.155708,-0.375973,-0.147023,-0.003789,0.518115,-0.395657,0.659664,-0.307473,0.142101,0.190798,0.362272,-0.157158,0.533194,-0.218369,-0.261161,-0.128522,-0.026435,0.291831,-0.052788,0.232528,-0.002873,0.163692,-0.027138,0.091945,-0.328731,0.124961', '26759820', '1322847', '10174444', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4934987', '意外的幸运签', '剧情', '“我”（富泽风斗 配音）冥冥中来至天国，却被那个有些聒噪的使者普拉普拉拦住去路。在他所说，上帝给了十恶不赦的我一次重生的机会，以此体味和感受生命真正的价值。“我”不由分说被重新投回人间，灵魂进入了一个初三学生小林真的体内。小林真三日前见到了心仪的女孩桑园寻香（南明奈 配音）与中年大叔出入爱情旅馆，又见到母亲（麻生久美子 配音）不贞的举止，加上生活中的一切都让人绝望，于是他选择服毒自杀。苏醒后的“我”以小林的身份生活着，各有心计的家人，有些烦人的女同学唱子（宫崎葵 配音），以及投来异样目光的同学，都让“我”感到烦躁，而在这一过程中“我”似乎触摸到了生存的意义……本片根据森绘都的原作改编。©豆瓣', '富泽风斗', '原惠一', 8.2, 47365, 'tt1677561', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p766075680.jpg', 0.4, 1.6, 17.8, 47.1, 33.1, '0.217658,0.039817,-0.541816,0.617859,-0.412429,-0.430401,0.629650,0.161560,-0.545330,-0.163152,0.103842,0.684805,-0.135376,0.327204,0.361276,0.154382,-0.163240,-0.510275,-0.228291,-0.069209,-0.225985,-0.270363,-0.108716,-0.072181,-0.088704,-0.484087,0.523107,-0.114261,-0.202116,0.400102,0.112146,0.154409,0.009735,0.529842,-0.090967,0.149987,0.089115,0.007203,-0.073632,0.220490,-0.002671,-0.193945,-0.128502,0.434302,-0.159606,0.304657,0.707637,-0.169122,-0.098083,-0.006768,0.413696,-0.158411,0.015367,0.224859,-0.016668,0.037427,0.035770,0.306625,-0.250187,0.078639,-0.136785,0.094607,-0.781808,-0.019981,-0.012394,0.233386,-0.328414,0.331713,0.015219,-0.220008,0.284426,-0.307799,0.124401,0.030455,0.459061,0.428884,-0.397630,-0.077122,-0.223309,0.077432,0.713606,-0.078195,-0.201932,0.324250,-0.080060,-0.498615,-0.032991,0.169926,-0.332177,0.045909,0.262574,0.220963,-0.258711,0.193606,-0.660600,-0.098958,0.004349,-0.086180,-0.074519,-0.556654,-0.058490,-0.315530,-0.180067,-0.336753,-0.420042,-0.164560,0.339772,-0.256162,0.669621,-0.681463,0.123212,0.753433,0.326125,-0.129756,0.596445,0.181778,-0.188969,-0.208488,-0.150593,0.224031,0.031103,0.610223,0.119222,0.410635,-0.134693,0.068372,-0.438162,0.533194', '24733428', '2053515', '25928048', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4935011', '白兔糖', '剧情', '27岁的上班族河地大吉（松山健一 饰）赶回家乡参加外公的葬礼，意外见到了外公的私生女——美丽而可怜的鹿贺凛（芦田爱菜 饰）。凛自然无法得到鹿贺家族的认可，却引起了大吉的关注与同情。最终，大吉将这个年仅6岁、尚在尿床的小阿姨带回东京独自抚养。凛的到来彻底改变了单身汉大吉的生活，他半天在公司辛苦奔忙，回到家还要照顾凛的衣食起居，随着凛到了进入幼稚园的年龄，奔跑逐渐成为大吉生活的主题。在这一过程中，曾经紧紧封闭内心的凛逐渐向大吉敞开心扉，他们既是奇怪的父女，又是年龄倒错的阿姨和外甥，平淡的生活充满幸福……本片根据宇仁田由美的同名人气漫画改编。©豆瓣', '松山研一', '萨布', 8, 92572, 'tt1672214', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1787832904.jpg', 0.2, 1.5, 23.4, 49.7, 25.2, '-0.028703,0.116057,-0.625515,0.234614,-0.023078,-0.291554,0.514828,0.378616,-0.365878,-0.345372,-0.090954,0.679268,-0.046220,0.549454,0.355171,0.009580,-0.155423,-0.542020,-0.270444,-0.144369,-0.018766,-0.294555,0.135130,0.065974,-0.004056,-0.475885,0.494202,0.136442,0.060286,0.745206,0.176460,0.328498,-0.149347,0.182017,-0.456006,0.026147,-0.082552,0.203839,-0.470764,0.099041,-0.048768,-0.040909,-0.219302,0.123383,0.119523,0.290245,0.925698,-0.191528,-0.517720,0.051360,0.588299,-0.207444,-0.396205,-0.066585,0.416404,0.041254,0.014596,0.157296,-0.360356,0.160740,-0.303965,-0.433736,-0.731726,0.123012,0.429620,0.150217,-0.520086,0.487848,0.035232,-0.184682,0.261799,-0.178780,0.402252,0.516998,-0.168364,0.628206,-0.273708,0.487436,-0.227119,0.213200,0.731896,-0.025152,-0.258209,0.272508,-0.437387,-0.109537,0.238334,-0.319544,-0.694320,-0.017886,0.006760,0.196031,-0.054579,0.182064,-0.375008,-0.056014,-0.165764,-0.337069,0.520920,-0.362018,-0.239893,-0.396099,-0.124460,-0.555045,-0.109308,0.034384,-0.054887,-0.368928,0.823657,-0.877813,0.130341,0.241599,0.296991,-0.468479,0.801346,-0.101699,0.149878,-0.265296,-0.096693,0.207164,-0.054356,0.228219,-0.124254,0.326007,-0.054993,-0.110091,-0.648306,0.385299', '3445516', '3811356', '1292219', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4935242', '焦土之城', '剧情', '双胞胎姐弟珍妮（梅丽莎·德索蒙斯-波林 Mélissa Désormeaux-Poulin饰）跟西蒙（马克西姆·高德特 Maxim Gaudette饰）收到过世的母亲娜瓦尔（卢布娜·阿扎宝 Lubna Azabal饰）的遗嘱，可当宣读完内容之后，两姐弟却一时难以接受这样的遗嘱：一份是写给他们从未蒙面的父亲；一份是写给她的第三个孩子——他们更是不知道这个哥哥的存在。影片巧妙的游走在两个不同的时空：母亲终其一生苦苦寻觅自己的长子；姐弟遵循母亲的遗嘱前往中东寻找他们的父亲与兄长。可越是穷其究竟，他们面对的越是理不清的头绪跟令人震惊的真相。本片改编自加拿大著名法语作家瓦基迪·穆阿瓦德的同名剧作。导演丹尼斯·维伦纽瓦荣获第83届奥斯卡金像奖最佳外语片提名。©豆瓣', '卢巴纳·阿兹巴尔', '丹尼斯·维伦纽瓦', 8.6, 56665, 'tt1255953', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p981048348.jpg', 0.4, 1.1, 9.8, 43.9, 44.8, '0.130173,-0.354703,-0.760769,0.991816,0.233053,-0.298444,0.541528,0.050318,-0.528778,-0.428806,-0.013076,1.030665,-0.132603,0.250202,0.177631,0.176187,-0.493492,-0.583606,0.197055,-0.184385,0.068531,-0.804160,-0.299856,-0.105135,-0.081214,-0.099402,0.544848,-0.112622,-0.128154,0.225631,0.515588,0.379985,-0.300471,0.093868,-0.177060,0.317885,0.216331,-0.003254,-0.429022,-0.079072,0.293936,0.089122,-0.227302,0.169340,0.069965,0.367955,0.462380,-0.343893,0.111193,0.131069,0.525298,-0.312780,-0.020520,0.023037,0.128079,-0.202277,0.273719,0.387821,0.007954,0.025646,0.035968,-0.125071,-0.764509,0.092302,0.329873,0.305530,-0.514098,0.221284,-0.340499,0.059469,-0.071241,-0.258795,0.264313,0.594659,0.078909,0.334784,-0.243727,-0.109353,-0.534910,0.232405,0.478974,-0.091726,-0.007874,0.307260,-0.087517,-0.628336,-0.127656,-0.318016,-0.722245,0.365484,0.281203,0.341956,0.092454,0.074526,-0.350242,-0.359820,-0.378312,-0.150628,0.236595,-0.706491,-0.025958,-0.382927,-0.150205,-0.452953,-0.394670,0.005085,0.056262,-0.335050,0.787225,-0.361224,0.248637,0.135877,0.100231,-0.564039,0.724444,0.455756,0.099527,-0.416973,-0.079140,0.362013,0.203911,-0.114095,0.087236,0.175835,0.311884,-0.014739,-0.325849,0.345251', '1456503', '1295120', '4301278', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4942776', '武侠', '剧情', '1917年，中国西南边陲的刘家村。刘金喜（甄子丹 饰）和妻子阿玉（汤唯 饰）共同抚养两个儿子方正和晓天，日子平淡且幸福。直到某一天，两个不速之客打破了刘家村的平静，也摧毁着金喜一家的生活。这二人企图洗劫村中的钱柜，被刚好在此的金喜撞见，一阵混乱打斗，二匪稀里糊涂被金喜打死。由于其中一人是政府通缉的要犯，因此县官大喜过望，村里人也将金喜奉为大英雄。但是，这看似普普通通的盲打误杀却引起一个人的怀疑，他名叫徐百九（金城武 饰），是县衙的捕快。从蛛丝马迹上来看，二匪系死于武功高强人之手，徐百九由此留在村里，对金喜展开了连番的观察、调查与试探。在这一过程中，金喜神秘的真实身份渐渐浮出水面，而刘家村也面临着一场空前的危机……©豆瓣', '甄子丹', '陈可辛', 6.7, 155647, 'tt1718199', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1084310090.jpg', 1.7, 9.3, 49.2, 32.4, 7.5, '0.201993,0.047500,-0.577201,0.493445,-0.007039,-0.076014,0.762824,0.158314,-0.639537,-0.220283,0.222747,0.659435,-0.100776,0.116503,0.245789,-0.210343,-0.023650,-0.488226,-0.271207,-0.105277,-0.163636,-0.298128,-0.280068,-0.302634,-0.063835,-0.129522,0.148194,0.251310,-0.236195,0.596012,0.280352,0.157154,-0.423540,0.346411,-0.171923,0.042254,-0.057097,0.025208,-0.149358,0.099748,-0.175975,-0.408606,-0.177272,0.130459,-0.256634,0.567860,0.534653,-0.220959,-0.397018,-0.044134,0.327810,-0.403537,-0.276342,0.064969,0.543300,-0.050694,0.035618,0.231792,-0.340756,-0.038036,0.074830,-0.068248,-0.757024,0.176404,0.251101,0.187683,-0.575484,0.431569,0.101208,-0.240747,-0.191677,-0.072599,0.265543,0.626867,0.241036,0.260788,-0.195127,-0.055619,-0.384916,0.166220,0.601179,-0.186530,-0.049706,0.102915,-0.048925,-0.394915,0.253882,-0.329896,-0.376121,-0.034853,0.256460,0.051645,-0.241480,0.122992,-0.479972,0.042525,-0.289008,-0.104300,-0.101415,-0.305647,-0.215558,-0.394521,-0.214685,-0.376345,-0.473495,0.171833,0.096884,-0.179111,0.625576,-0.534985,0.167908,0.419250,-0.002557,-0.319782,0.478278,0.115879,0.141987,-0.073165,-0.179576,-0.084963,0.342855,0.236626,0.073554,0.370240,-0.267816,-0.311531,-0.355465,0.304959', '1294941', '3111650', '3119246', '27060077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4942778', '白蛇传说', '动作', '南宋年间，世道离乱，更有各方妖孽为害世间，亦有痴情种子因缘和合，演出千古传奇。某深山老林，一青一白二蛇修炼千年，化得人身，终日在山中畅意游玩，好不自在。二蛇偶遇上山采药的郎中许仙（林峰 饰），白蛇（黄圣依 饰）倾慕许仙，并偶然救得他的性命，自此凡心触动，决定下山寻找心上之人。适逢佳节，二蛇变作人形，以白素贞、青青（蔡卓妍 饰）之名来到城中。正所谓因缘际会，白素贞终与许仙相逢，结为夫妇。时有金山寺高僧法海（李连杰 饰）携弟子能忍（文章 饰）四方游历，降妖除魔。追寻二蛇期间，能忍为蝙蝠妖所伤，魔性大起，坚心动摇。其后师徒二人更与白素贞、青青二蛇上演正法与情缘的亘古纠葛……©豆瓣', '李连杰', '程小东', 4.8, 109744, 'tt1857913', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1221489031.jpg', 18.6, 35.9, 35.2, 7.6, 2.7, '-0.034918,-0.244107,-0.226730,0.139829,0.437090,-0.205558,0.280593,0.212106,-0.468771,-0.096476,0.214239,0.304868,-0.391620,0.032735,-0.049686,0.059871,-0.002568,-0.307519,0.306982,-0.137969,0.487678,0.138302,-0.279531,0.304118,-0.259773,-0.169298,0.573775,0.170296,0.131067,0.644267,0.262364,0.019120,-0.636837,0.081767,-0.367396,-0.054385,-0.412225,0.383379,-0.386235,-0.208397,-0.303561,-0.280681,-0.292687,-0.306529,-0.446254,0.003390,0.408066,-0.199893,-0.280892,-0.289930,0.211734,0.048638,-0.092474,-0.016591,-0.009822,-0.121612,0.470043,0.459657,0.031623,0.080723,0.061803,0.052267,0.065214,0.224789,0.362867,0.123662,-0.038576,0.166350,0.252728,-0.100769,-0.200060,-0.241819,-0.141965,0.148515,0.416883,-0.004743,0.036797,-0.488243,-0.285841,0.480683,0.285391,-0.138257,0.151584,0.235100,0.248561,-0.173664,0.438245,-0.071249,-0.134433,-0.059267,0.185598,0.021228,0.009558,0.490516,-0.534311,0.191680,-0.402137,0.649110,-0.056374,0.016156,0.001011,-0.539807,-0.224840,-0.105273,-0.314544,-0.124453,0.540668,-0.340351,0.664016,-0.391254,0.155278,0.041976,0.043522,-0.501120,0.687920,-0.072562,0.217401,-0.346348,-0.067981,0.578345,-0.391574,0.391232,-0.204635,-0.125599,-0.072354,0.366905,-0.389712,-0.152674', '34825976', '6068516', '5153254', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4942779', '真心话大冒险', '喜剧', '徐承康（黄维德饰）是一家策划公司总监，标准的“钻石王老五”，和朋友玩“真心话大冒险”而结识了身为演员的尤美（孟丽饰）。徐在家里举办一个生日宴会，请来了在美国念书的同学跆拳道教练唐菲（苗圃饰），合作公司的好朋友陶颍（秦海璐饰）。同一天，陶颍的小学同学王奔（文章饰）也在KTV召集了一个聚会。王奔是瑞康鞋业董事长的儿子，母亲早逝，心智不是很成熟，是个典型大男孩。王奔的父亲王总（孙兴饰）是个古董车爱好者，为了激励王奔好好做事，送了一辆有特殊含义的古董奔驰车给他，王奔非常兴奋，于是召集了包括酒吧歌手彭卓然（李威饰）在内的几个好朋友聚会庆祝。同一天的两场聚会都非常热闹，到了最后，两边的人不约而同的玩起了“真心话大冒险”的游戏。随着这个游戏的展开，虽然玩的不亦乐乎，但是“真心话”夹杂了谎言，而“大冒险”则付出了沉痛的代价……©豆瓣', '文章', '马志宇', 5, 8147, 'tt2321661', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1402873707.jpg', 17.2, 31.7, 38.9, 9.4, 2.8, '0.277866,-0.300085,-0.361194,0.615909,-0.246145,-0.186970,0.449737,0.349650,-0.372290,-0.289187,0.301749,0.790410,-0.321285,0.418125,0.324020,-0.008292,-0.093657,-0.350358,-0.103378,-0.068061,-0.054988,-0.560157,0.129787,-0.137716,0.035828,0.003508,0.126645,-0.204204,0.002053,0.677988,0.614157,0.078342,0.102212,0.228341,-0.160364,-0.216082,0.199890,0.212670,-0.295220,0.153349,-0.216916,-0.064988,0.063262,0.060450,0.385541,0.302256,0.575113,0.172683,0.004755,0.114874,0.311632,-0.144047,-0.054499,-0.176539,0.370731,0.113414,0.529692,0.096545,0.012154,-0.011611,0.067059,-0.325874,-0.773921,0.169409,0.298593,-0.139641,-0.608220,0.719993,0.075903,-0.162138,0.041385,-0.152024,0.474370,0.304635,0.188782,0.087480,0.099837,0.157667,-0.516314,0.480295,0.638605,0.057594,0.177732,0.294209,-0.376816,-0.485022,0.090271,-0.172437,-0.401138,0.173289,0.213472,-0.428000,-0.001061,-0.119938,-0.717500,-0.084411,0.237212,-0.377982,0.263836,-0.550617,0.181880,-0.608616,-0.053115,-0.358407,-0.169191,-0.037397,0.134133,-0.081199,1.012499,-1.054932,-0.259131,0.569827,-0.011188,-0.596807,0.848004,0.272096,-0.043951,-0.198014,-0.021938,-0.435224,0.012210,0.010303,-0.031988,0.652934,0.045448,-0.403978,-0.568970,0.305116', '1292219', '25922902', '6963575', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4943938', '黑暗塔', '动作', '在一个由“黑暗塔”联接的多重世界里，最后的骑士“枪侠”罗兰(伊德瑞斯·艾尔巴饰)与企图摧毁黑暗塔、以毁灭世界的“黑衣人”沃特·奥丁(马修·麦康纳饰)之间，处于永无止尽的正邪大战。', '伊德里斯·艾尔巴', '尼科莱·阿尔赛', 5.3, 15086, 'tt1648190', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2480303169.jpg', 8.9, 32.7, 44.9, 9.8, 3.7, '-0.004199,0.519223,-0.804246,0.714391,0.277118,-0.204347,0.968112,0.286422,-0.138544,-0.085064,0.288140,0.229650,-0.000370,-0.182722,0.719688,-0.014567,-0.651394,-0.569217,-0.196735,-0.367828,-0.713941,-0.524025,-0.696465,-0.066100,-0.393906,-0.795060,0.870749,0.170988,-0.200003,-0.561375,0.158795,0.832635,-0.360602,0.333314,0.234874,-0.196199,0.359935,-0.547170,-0.671018,0.328978,-0.309796,0.632425,-0.165345,0.242943,-0.273920,-0.128044,0.652173,-1.194500,0.766964,-0.284098,0.275686,0.019585,-0.201604,-0.303196,0.291309,-0.202738,0.019386,-0.040852,0.220745,-0.067638,0.315934,-0.145386,-0.473592,-0.315593,0.195016,0.274877,-0.173185,0.639956,0.100097,-0.109548,0.108012,0.133734,-0.013508,0.371387,0.695089,0.389532,-0.123731,-0.418405,-0.422889,-0.370498,0.093269,-0.045779,-0.905942,-0.271938,-0.410891,-0.191408,-0.505147,0.230283,-0.523714,-0.383998,0.757165,-0.039337,0.285379,1.234159,-1.070142,-0.037087,-0.600301,-0.000779,-0.122957,-0.433792,-0.190981,-0.789629,-0.016030,-0.032389,0.013071,0.081220,0.141437,0.428382,0.279540,-0.847590,0.766966,0.305668,0.580170,0.529200,0.534346,0.012435,0.627140,-0.605517,-0.122414,0.866192,0.168726,0.353958,0.242046,0.249235,0.095695,0.272323,-0.315215,0.816733', '1298586', '4824515', '1873750', '25786060');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4944008', '香肠派对', '喜剧', '故事发生在一间大超市之中，在陈列在此的商品间，流传着一个古老的传说，某一日，那位名为“顾客”的上帝会现身此处，把你带回家，从此你将登上人生的巅峰，享受无上的荣光。香肠弗兰克（塞斯·罗根 Seth Rogen 配音）和他的女友热狗面包布兰达（克里斯汀·韦格 Kristen Wiig 配音）最大的愿望，就是能被同一位顾客买回家，这样方可以过上向往已久的“合体”生活。然而，一瓶曾经被顾客买走之后又被退回超市的蜂蜜芥末（丹尼·麦克布耐德 Danny McBride 配音）却道出了事件的真相，那就是，根本不存在什么上帝，也并没有天堂，等待着它们的，有的只有残忍的生吞活剥，骨肉分离。为了验证蜂蜜芥末的话，弗兰克找到了神秘的龙舌兰酒（比尔·哈德尔 Bill Hader 配音），与此同时，因为意外而跌落货架滚至别处的布兰达亦和同样遭遇的贝果萨米（爱德华·诺顿 Edward Norton 配音）、亚美尼亚薄饼拉瓦西（大卫·克鲁霍尔特兹 David Krumholtz 配音）一起，寻找回家的路。', '塞斯·罗根', '康拉德·弗农', 7.2, 93272, 'tt1700841', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2371145119.jpg', 1.3, 6, 39.4, 39.5, 13.8, '0.586407,0.062343,-0.368904,0.568105,-0.137041,-0.438108,0.902409,0.373456,-0.263762,-0.127991,-0.027540,0.913712,-0.215617,0.112841,0.213712,0.174507,-0.341796,-0.388123,0.068109,-0.269552,-0.273219,-0.386631,-0.291595,-0.146663,0.029196,-0.004839,0.220652,-0.079922,-0.228312,0.186522,0.332651,0.179423,-0.053734,0.337593,-0.270187,0.121385,0.178633,-0.053988,-0.215057,0.334164,0.065904,-0.153694,0.045031,0.166036,0.173997,0.081787,0.281721,-0.220731,0.027429,0.111109,0.183003,-0.157877,0.242683,0.137530,-0.078427,-0.095062,0.043958,0.123871,-0.103916,0.136722,0.211716,-0.170339,-0.862899,-0.094796,-0.352717,0.263616,-0.352298,0.446082,-0.123038,-0.067926,0.219242,-0.223539,0.339191,0.270714,0.372606,0.363029,-0.061843,-0.094673,-0.760544,0.180350,0.502014,-0.016180,-0.021618,0.282838,-0.141713,-0.443478,0.068222,-0.008595,-0.417924,0.042412,0.461319,0.166767,-0.048483,0.140607,-0.789283,0.031251,-0.187301,-0.353542,0.154478,0.037936,-0.336003,-0.725035,0.030724,-0.240155,-0.323123,-0.174415,0.156317,-0.264267,0.642156,-0.513017,0.304676,0.669626,0.405796,-0.054266,0.710189,-0.063740,0.070434,-0.038814,-0.017173,0.433810,0.139946,0.371439,0.291306,0.445040,0.177016,0.028572,-0.443281,0.555759', '1309101', '30162520', '1299932', '26858510');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4946963', '光棍儿', '剧情', '张家口治下的顾家沟村里，四个老光棍聚在村头闲聊：梁大头在1966年为女社员贴身义务教学，结果付出了一只手的代价；顾林在1945年的光景上演了一出釜底加薪计只为摸两把姑娘；六软12岁成亲，但初夜经历却不堪回首；老杨（杨振君 饰）则三十年和同村二丫头维系着地下情，时常把收入输送给后者补习考大学的儿子，而二丫头背着村长丈夫，同时和多名光棍保持关系……老杨萌生了结婚的想法，花六千块从人贩子手中买下一名年轻漂亮的四川女子，村中人眼热，年轻力壮的俏三尤为突出。不久四川女子寻机出逃，俏三帮老杨将人截回，这次接触却令四川女子决意和俏三组成家庭，这打破了村中的平静……©豆瓣', '杨振君', '郝杰', 8.1, 47765, 'tt1652352', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p773609121.jpg', 0.8, 1.8, 18.3, 49.7, 29.4, '-0.037884,-0.117199,-0.314313,0.287631,-0.308547,-0.480397,0.653720,0.043153,-0.365718,-0.210651,0.035207,0.369340,-0.179210,0.443006,0.288975,-0.310128,0.136783,-0.537148,-0.356651,-0.197879,-0.154210,-0.194869,0.023632,-0.100787,-0.213309,-0.194199,0.242150,0.024372,0.057543,0.450401,0.457839,0.008643,-0.181074,-0.002101,-0.217733,0.008514,-0.018346,0.122674,-0.164611,0.024709,-0.145566,-0.305257,-0.146161,-0.342672,0.228457,0.532268,0.795518,0.012372,0.026280,-0.233257,0.148804,0.244590,-0.257319,0.034971,0.362396,0.234872,0.201368,0.178065,-0.374841,-0.182794,0.207535,-0.483006,-0.094533,0.331537,0.276678,-0.158101,-0.870168,0.196344,0.082783,0.098285,0.034427,-0.241181,0.097433,0.372431,0.192926,0.403464,-0.109724,0.244407,-0.367544,0.391195,0.641659,-0.244871,0.152677,-0.048189,-0.110669,-0.299674,0.147487,-0.253007,-0.229848,0.002583,0.225859,-0.159453,0.046063,0.057864,-0.411099,-0.029250,-0.159055,-0.056657,0.189848,-0.129786,-0.273128,-0.262340,-0.170086,-0.270682,-0.260834,0.304830,0.331346,-0.228365,0.853721,-0.310039,-0.075667,0.122797,0.413258,-0.544747,0.664346,0.119636,0.200930,-0.500065,-0.047670,-0.063575,0.039515,0.083447,0.341933,0.183425,-0.720650,-0.119037,-0.131945,0.360307', '1306505', '1291565', '25731805', '1316525');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4960076', '大玩家', '喜剧', '厨子二宝（孙兴 饰）是个42岁的中年男人，因为被老板炒鱿鱼，又跟妻子（姜宏波 饰）闹离婚，感觉人生无望，准备撞车自尽。没想到，他求死不成，遇到八仙女（谢娜 饰），后者具有超凡能力，可以帮他实现梦想。二宝欣喜若狂，先后尝试了多种角色：做大侠时，他（莫少聪 饰）与侠女（杨丽菁 饰）是武林高手；扮富人时，他（雪村 饰）却被表哥（梁天 饰）与段小姐（傅艺伟 饰）骗得团团转；当明星时，他（李修贤 饰）因拍戏不能见母亲临终一面而悲痛欲绝；做美女时，他（钟欣桐 饰）得面对色狼上司的穷追不舍；当皇帝时，他（焦恩俊 饰）遇到了一生中的真爱云儿（霍思燕 饰），却被皇太后（斯琴高娃 饰）生生拆散……最终，二宝还是在现实中找到了幸福的真谛……本片由多位明星联袂出演，并在全世界首创了“六星合一”表演格局。©豆瓣', '钟欣潼', '牛朝阳', 4.6, 6446, 'tt6450040', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p696959324.jpg', 26.5, 31, 31.7, 7.3, 3.6, '-0.175611,-0.005774,-0.355925,0.206389,-0.194865,-0.190119,0.564977,0.138411,-0.532989,-0.265820,0.281991,0.843630,-0.491575,0.238463,0.124618,-0.000167,-0.055975,-0.575465,0.410519,0.085318,0.131403,-0.030637,-0.155532,0.202236,-0.320532,-0.156042,0.607181,-0.244788,-0.009957,0.172508,0.560442,0.136348,0.023076,0.256321,-0.017016,0.116873,-0.012779,0.079723,-0.315389,0.168955,-0.156449,-0.330544,-0.163739,-0.046750,-0.214140,0.182635,0.478568,-0.207094,0.035558,-0.262094,0.433594,-0.076062,-0.089714,0.227534,-0.066826,-0.105027,0.336184,0.100926,-0.077382,-0.142666,0.393060,-0.112638,-0.657267,0.166350,0.385856,-0.132848,-0.513055,0.075815,-0.229242,-0.006744,0.270630,-0.216424,0.271141,-0.073226,0.416231,0.385917,-0.205084,0.007955,-0.426507,0.573636,0.478489,0.099340,0.058507,0.331326,0.032736,-0.420601,0.097287,-0.399655,-0.426238,0.304755,0.138570,0.010709,-0.123231,-0.123025,-0.248975,-0.066610,-0.279711,0.365297,-0.100145,-0.285567,-0.106255,-0.214303,0.065904,-0.416286,-0.192994,0.019475,0.150269,-0.320210,0.547613,-0.644023,0.026711,0.177621,0.210330,-0.637561,0.719191,0.231337,-0.102742,-0.369623,0.113407,-0.062882,-0.274561,0.068127,0.230161,0.256808,-0.062732,-0.111359,-0.113674,0.225307', '4301278', '34890458', '30162520', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('4960204', '房不剩防', '喜剧', '不会水的泳池救生员英铭（赵毅 饰）被揭穿后惨遭辞退，债主又派打手在街头围堵他，幸好有售楼员女友小柯（李念 饰）不离不弃，英铭向女友谎称自己是医生之余，又百忙中借来朋友的房子向未来岳母交差。岳母大人对婚房不满，英铭假戏真做把朋友的房子卖了出去，又如法炮制借房向小柯承诺未来的幸福生活，趁小柯挑剔之机，英铭再次把别人本来就是委托他卖掉的房子转手。一来二去，英铭发现了代理售房的利润，亦洞悉了隐藏在自己身上的售房天才，于是和失业的小柯一起，踏上了售房征途。英铭奇招尽出搞定了多个缺陷房，不料却被道中高手摆了一道，不甘失败的英铭决定向国际大项目迈进……©豆瓣', '赵毅', '孙达', 5.8, 4746, 'House Mania', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1711912687.jpg', 6, 20.3, 53.8, 16.5, 3.4, '0.158739,-0.049328,-0.311440,0.457118,-0.300577,-0.368544,0.605124,0.308249,-0.164591,0.121125,0.249308,0.599241,-0.133890,0.250603,0.254159,0.048377,-0.021480,-0.592200,-0.042780,-0.222131,-0.298715,-0.352066,-0.144415,-0.210110,-0.026144,-0.056270,0.245809,0.030762,-0.120604,0.122462,0.401503,0.241064,-0.086604,0.428324,-0.189083,0.250456,-0.047130,-0.042710,-0.326738,0.417144,0.011837,-0.205925,-0.118412,-0.007808,0.133397,0.399045,0.642010,0.243389,-0.181218,-0.052706,0.340117,-0.120648,0.186723,0.096250,0.219142,0.221654,0.188546,0.221811,-0.354581,-0.069466,0.305839,-0.064413,-0.373649,0.139546,0.025175,-0.221313,-0.830623,0.355702,-0.193184,-0.073624,-0.069489,-0.596617,0.087415,0.267496,0.134460,0.388965,-0.262432,0.284707,-0.513344,0.264514,0.373359,0.077633,0.279534,0.279046,0.190217,-0.199887,0.248799,0.090030,-0.492776,-0.161841,0.620220,0.031393,-0.057605,0.036286,-0.445525,-0.197742,-0.254246,-0.291261,0.070059,-0.521377,0.074429,-0.337248,-0.009072,0.156014,-0.216305,0.131569,0.306970,-0.093458,0.501247,-0.541269,-0.059388,0.447055,0.700842,-0.591540,0.754882,-0.161778,0.109223,-0.057516,0.119734,-0.295039,0.222221,0.558222,0.483522,0.247831,0.064372,-0.361720,-0.191989,0.278416', '1299965', '1293607', '1307639', '1306505');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5028328', '午宴之歌', '剧情', '“他”（艾伦·瑞克曼 Alan Rickman 饰）是伦敦一名默默无闻的图书编辑，经历了写作生涯的惨痛失败后，只能在工作之余写写诗，一边唾弃着他平淡无奇的工作，一边为曾经的失败爱情心怀遗憾，渐入颓唐中年。“她”（艾玛·汤普森 Emma Thompson 饰）是“他”的 旧情人，离开他之后嫁给了一位极负盛名的作家，在巴黎过着光鲜滋润的生活。分开15年后，两人再度相约在以前常去的餐厅共进午餐。满怀期待赴宴的“他”却发现，餐厅已面目全改，曾经熟悉的一切无迹可寻。“她”依然亮丽，却少了他记忆中的样子，食物依旧，话题却不尽人意。这一切只是他沉溺诗歌的幻想，还是他真的已经随着那老去的一切被遗弃了？本片改编自克里斯托弗·里德（Christopher Reid）的同名叙事诗，诗人携该诗于2010年获柯斯达文学奖（Costa Book Awards）“年度代表作”奖。', '艾玛·汤普森', '尼亚尔·迈克考米克', 8.6, 12641, 'tt1686812', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2165601333.jpg', 0.3, 1.3, 11.6, 40.1, 46.7, '0.025455,0.144197,-0.702619,0.487554,-0.032499,-0.658724,0.965202,0.061269,-0.609868,-0.335498,0.164361,0.718822,-0.097496,0.486920,0.215026,0.059123,-0.444489,-0.657244,-0.067252,-0.163532,-0.069444,-0.251138,-0.131278,-0.063556,-0.195493,-0.132624,0.552218,0.238386,-0.108049,0.427211,0.330806,-0.017879,0.036425,0.549788,-0.320567,0.107101,0.216897,0.040996,-0.287405,-0.131851,0.173578,-0.492521,-0.544697,0.135050,-0.033263,0.181168,0.691029,-0.098166,-0.227238,0.275616,0.421306,-0.154900,-0.097106,0.116956,0.155853,0.127814,0.192912,0.143027,-0.125325,-0.087226,-0.145668,-0.058506,-0.717746,-0.019846,0.014489,0.351121,-0.510608,0.813012,-0.086078,0.153807,-0.052843,-0.377169,0.085021,-0.109546,0.237994,0.327958,0.031244,0.035856,-0.363052,0.636726,0.654724,0.229536,-0.434322,0.575897,-0.356819,-0.347911,-0.101485,-0.234593,-0.594620,0.074818,0.200686,0.066611,-0.131312,0.315967,-0.517963,0.052164,-0.135388,-0.106913,-0.121251,-0.266423,-0.190716,-0.499138,-0.126401,-0.494590,-0.379000,-0.103787,-0.072798,-0.291528,0.710858,-0.645499,0.340033,0.711628,0.087204,-0.271999,0.701000,0.169663,0.015134,0.005072,-0.090429,0.646612,-0.343826,0.253176,0.126075,0.391965,0.121211,-0.121586,-0.549530,0.772915', '1309172', '