INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5028536', '致命黑兰', '剧情', '影片是导演奥利维尔·米加顿的第4部故事长片，主要辗转于巴黎、芝加哥、迈阿密、新奥尔良和墨西哥五个城市之间。卡塔丽亚·雷斯特雷波（佐伊·索尔达娜 Zoe Saldana 饰）在十岁时目睹自己的父母被哥伦比亚毒品大王唐·路易斯残酷杀害。逃出生天的卡塔丽亚逃到了芝加哥，投奔了叔叔埃米利奥，他也是一个黑帮分子。埃米利奥尽量让卡拉勒娅远离黑帮生活的影响，但卡塔丽亚一心想成为一名职业杀手。25岁的她终于变成了一个经验丰富、冷酷无情的刺客，她平时为叔叔埃米利奥工作，但内心里的目标却是为自己的父母展开复仇，干掉毒品大亨唐·路易斯。为了复仇，没有什么可以阻止卡塔丽亚，不管是舅舅埃米利奥、还是FBI、CIA官员，虽然卡塔丽亚为舅舅埃米利奥全家遇害而内疚，但更坚定了她复仇的决心，也让毒品大亨唐·路易斯和他的同伙陷入了死亡的恐惧中......©豆瓣', '佐伊·索尔达娜', '奥利维尔·米加顿', 7.1, 59046, 'tt1657507', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p989955567.jpg', 0.5, 4.6, 45.2, 38, 11.6, '0.054411,-0.197066,-0.449816,0.473248,-0.080880,-0.591278,0.921354,0.066205,-0.525614,-0.165398,-0.218260,0.831534,0.212804,0.177645,0.297067,0.474645,-0.469632,-0.567001,0.051736,-0.010305,0.127710,-0.691103,-0.420515,-0.334023,-0.000555,-0.206459,0.154190,-0.019974,0.025660,0.396240,0.361687,0.427299,0.206981,0.455303,0.278434,0.093223,0.463611,-0.454887,-0.389396,0.255852,-0.030885,0.048742,-0.221951,0.201594,0.187969,0.443605,0.314669,-0.185921,0.457572,-0.168954,0.206925,-0.615686,0.048640,0.157909,0.211861,-0.373974,0.233804,0.081196,-0.065184,-0.177392,0.094245,-0.035944,-0.654807,0.034791,0.301128,0.087165,-0.627565,0.235171,-0.510827,-0.185362,0.216191,-0.167623,0.135195,0.447031,0.301866,0.105226,-0.317314,-0.293616,-0.529811,-0.192014,0.664298,-0.019753,-0.078163,-0.124785,-0.386065,-0.557557,-0.001538,-0.263265,-0.443451,-0.227972,0.365642,-0.171644,-0.064188,0.660702,-0.517370,-0.371586,-0.505061,-0.342168,-0.222695,-0.293140,-0.053907,-0.462326,-0.063607,-0.457865,-0.193272,-0.154604,0.181470,-0.323714,0.566412,-0.622772,0.308534,0.639938,0.307238,-0.295155,0.505745,0.202713,0.352837,0.126826,0.022506,0.458923,0.050361,0.092786,0.112687,0.347120,0.085711,-0.330041,-0.144593,0.553553', '1299799', '10774184', '1293145', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5029050', '我们是夜晚', '剧情', '飞往柏林的国际航班上，血流成河，尸横遍野。在这残酷的地狱间却伫立着三个与众不同的女人，沉稳神秘的露易丝（Nina Hoss 饰）、雍容典雅的夏洛特（Jennifer Ulrich 饰）以及天真率直的诺拉（Anna Fischer 饰）。她们的真实身份是吸血鬼，终日游走世界各地，享受可口的鲜血和永无止境的奢华生命。在某个狂乱的夜总会里，对美丽眼睛分外痴迷的露易丝相中了18岁的问题少女丽娜（Karoline Herfurth 饰），于是不用分说吸食了对方的鲜血。不久后，身体发生巨大变化的丽娜成为了露易丝她们中的一员，从此一步登天，有着享不尽的名车、美食与奢侈品。她们有着世人渴望的一切，却也有着远远大于人类的孤独感……本片荣获2010年Sitges–Catalonian国际电影节评委会特别奖。©豆瓣', '卡洛琳·赫弗斯', '丹尼斯·甘塞尔', 6.5, 9396, 'tt1692504', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1713770109.jpg', 2.4, 13.8, 50.5, 24.4, 8.9, '0.282757,0.317753,-0.740680,0.524823,-0.069438,-0.104135,1.109572,0.159659,-0.557911,0.071373,0.356246,0.755671,-0.298191,0.203897,0.319890,0.240793,-0.304119,-0.672486,-0.250627,-0.327804,-0.072624,-0.202448,-0.338303,0.087160,-0.074767,-0.267375,0.562951,0.127594,-0.086535,0.667616,0.232454,0.153108,-0.125278,0.374164,-0.381970,-0.242966,-0.005334,0.086174,-0.123703,0.055372,-0.002489,-0.202130,-0.137629,0.023376,-0.283608,0.120538,0.722590,-0.460965,-0.123716,-0.116133,0.431593,-0.168072,-0.045916,0.238672,-0.036272,-0.137014,0.146384,0.008879,-0.158188,0.024093,0.161765,0.010132,-0.902766,-0.302769,0.101313,0.443657,-0.386130,0.718301,0.095657,-0.271604,0.209735,-0.219420,0.073637,-0.009142,-0.031750,0.521444,-0.019182,0.027161,-0.702353,0.203501,0.569746,0.328171,-0.538027,0.252896,-0.631146,-0.444915,-0.210177,-0.340040,-0.604140,-0.064674,0.262131,0.241450,0.018747,0.418406,-0.835128,0.192125,-0.020461,-0.298267,-0.040691,-0.282767,-0.476812,-0.588808,-0.317203,-0.913056,-0.325992,-0.040864,0.137889,-0.093837,0.831459,-0.858988,0.223777,0.368595,0.261645,-0.191342,0.728843,-0.093251,-0.055646,-0.078071,-0.463519,0.493574,-0.156701,0.226322,-0.068522,0.538545,-0.172048,0.127944,-0.400096,0.569457', '1292062', '24839498', '3005387', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5032144', '苔藓', '悬疑', '1978年，自感在越战中犯下杀孽的刘木刑返回韩国后信仰天主，为洗清罪孽，刘潜心修行并组织村民集资买地以供传道之用。刑警千永德（郑在泳 饰）怀疑刘木刑实为骗子，对后者进行迫害，不久却被刘感动，两人一起带上几名罪犯，远赴荒僻之地以求救赎。25年后，千、刘等人定居之地已经发展成一井井有条的村落。刘木刑身死，刘之子刘海国（朴海日 饰）从首尔奔丧，但村中众人貌似并不欢迎刘海国，时时期待他离开。刘海国心中生疑，主张对父亲进行尸检，同时他发现原本属于父亲名下的土地和钱财已被转入千永德名下。刘海国求助检察官朴民旭协助调查，同时村中女子英智在暗中观察刘海国，村中的一些阴暗往事，在刘海国的调查下渐渐浮出水面……©豆瓣', '郑在泳', '康佑硕', 7.1, 9673, 'tt1694019', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p662389962.jpg', 1, 5.6, 42.2, 39, 12.2, '-0.154229,0.292326,-0.509430,0.486466,0.325849,-0.060757,0.146015,0.170246,-0.735731,-0.445554,-0.131662,0.398071,0.019977,0.137765,0.169410,-0.221914,-0.516630,-0.655221,-0.159510,-0.268869,-0.228253,-0.284621,0.055751,-0.317490,-0.500425,-0.213662,0.401176,0.757416,-0.045890,0.523813,-0.112713,0.246415,-0.282234,0.228167,-0.042770,-0.169599,-0.002270,-0.070044,-0.314698,-0.092045,-0.325067,-0.514168,-0.227309,-0.045830,0.207020,0.385561,0.731658,-0.021960,-0.218228,-0.425425,-0.031025,-0.239856,-0.066098,0.137371,0.638761,0.036080,0.271829,0.440810,-0.196209,-0.182379,-0.038119,-0.432791,-0.556647,0.017126,0.175683,0.106623,-0.460046,0.114878,-0.140783,0.061352,-0.181505,-0.222785,0.341073,0.451161,0.221459,0.144337,-0.161360,-0.017484,0.004168,0.406054,0.600583,0.082036,0.249156,-0.422141,-0.350891,-0.374840,0.126745,0.103505,-0.116101,-0.091528,0.176884,0.016439,0.157542,0.270933,-0.309335,-0.209600,-0.480743,-0.207390,0.133809,-0.340471,-0.069459,-0.462837,-0.168275,-0.195619,-0.099041,0.113943,0.281787,-0.194855,0.211612,-0.605930,0.222289,0.116746,0.400031,-0.828206,0.399714,-0.268802,0.216369,-0.280520,-0.244043,0.495361,0.057070,0.362423,-0.087156,-0.124739,-0.240356,-0.344097,0.012450,-0.207219', '1366853', '1293265', '1292846', '23126901');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5041518', '在切瑟尔海滩上', '剧情', '影片讲述上世纪60年代西方性解放运动来临之前，受过良好教育且深爱对方的两位年轻人在面对新婚初夜时，因担忧和恐惧而产生误解，最终分道扬镳、终身不再来往的故事。', '西尔莎·罗南', '多米尼克·库克', 7.4, 16730, 'tt1667321', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2501790744.jpg', 0.6, 4, 36.6, 44.9, 13.9, '0.249737,-0.048258,-0.524567,0.266028,0.378404,-0.166613,0.668687,0.025905,-0.694856,-0.686066,0.201405,0.580011,-0.213840,0.307619,0.318719,-0.475184,-0.425740,-0.620546,-0.037013,0.022709,-0.264502,-0.378287,0.337689,-0.032528,-0.462466,-0.530533,0.681815,-0.031241,-0.509348,0.557665,0.132127,0.271134,-0.081760,0.184280,-0.187744,-0.383510,-0.126166,0.478913,-0.961276,-0.046516,0.113884,-0.193933,-0.285358,0.046085,-0.410700,0.274274,0.512649,-0.077699,-0.224368,-0.500815,0.595475,0.156353,-0.188963,0.331727,0.196496,0.330811,0.473623,0.478419,0.282848,-0.337268,-0.279835,-0.326772,-0.144252,0.133490,0.030204,0.118693,-0.345672,0.324496,0.182753,0.170665,0.055925,-0.164508,0.026306,0.251145,0.813785,0.505049,-0.243356,0.086459,0.017596,0.134556,1.085091,0.262958,-0.179082,0.448683,-0.322141,-0.345251,0.056756,-0.474229,-0.948079,0.264141,-0.235514,0.357138,-0.459448,0.710885,-0.538684,0.147281,-0.094628,-0.029280,0.160907,-0.336096,-0.133871,-0.702545,-0.367771,-0.672467,-0.417543,0.145769,0.167693,-0.347897,0.805024,-0.701071,0.613701,0.184086,0.413006,-0.868845,0.799304,0.558297,0.027962,-0.360474,-0.050915,1.042718,-0.404985,-0.454177,-0.490005,-0.168071,-0.586230,0.497575,-0.133205,0.579428', '10535447', '25721544', '1308038', '1309124');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5044737', '我11', '剧情', '20世纪70年代，西南三线地区，无数的上海人怀着崇高的理想来到这片贫瘠的土地建设国家，付出莫大的牺牲。此时此刻，文革的余威仍在，各国营单位乱相未除，而在子弟学校就读的少年王憨（刘文卿 饰）则和八拉头（张珂源 饰）、小老鼠（钟国流星 饰）、卫军（楼逸昊 饰）等几个伙伴过着无 忧无虑的快乐生活。王憨广播体操动作标准，被选为领操员，为此软磨硬泡求妈妈（闫妮 饰）为他做了一件崭新的白衬衣。可是他在河边玩时衬衣意外掉入水中，结果意外遭遇了被警察追捕的杀人犯谢觉强（王紫逸 饰）。时代的大背景下，放眼尽是令人百思不得其解的怪现象，小人物只有随波逐流，身不由己……©豆瓣', '闫妮', '王小帅', 7.4, 59888, 'tt2042432', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1522704777.jpg', 0.4, 3, 35.2, 48.2, 13.2, '0.074007,-0.055746,-0.670482,0.303072,-0.001880,0.036654,0.505331,0.411299,-0.561688,-0.262886,0.403958,0.464595,0.079885,-0.087303,0.037401,-0.162461,-0.142086,-0.546802,-0.085347,-0.128190,-0.188316,-0.166565,-0.312968,-0.186798,-0.214196,-0.196873,0.613314,0.404642,-0.053230,0.398103,0.397917,0.223563,-0.143218,0.250504,-0.286555,-0.133590,0.081011,0.285590,-0.225277,-0.077065,-0.336466,-0.180281,-0.217548,0.144518,0.002078,0.282087,0.658984,-0.210728,-0.146974,-0.128907,0.475967,-0.101938,0.085292,-0.107690,0.233967,0.070478,0.181273,0.108392,0.127779,0.101825,0.448882,-0.166878,-0.565320,-0.083562,0.443570,0.156154,-0.665872,0.669292,-0.133009,-0.214105,0.107365,-0.285751,0.128911,0.230588,0.314055,0.565904,-0.107201,0.188040,-0.393547,0.562118,0.502617,0.059105,-0.280055,-0.011363,-0.344779,-0.180685,0.051857,-0.342066,-0.438837,-0.154077,0.094827,-0.150896,-0.152017,0.213198,-0.517098,0.299003,-0.116484,-0.239843,-0.086883,-0.198329,-0.322119,-0.227766,0.204746,-0.325797,-0.142588,0.313449,0.130359,-0.128978,0.753176,-0.642725,0.079048,0.440924,0.315490,-0.386183,0.714904,-0.058604,0.080469,-0.192045,-0.072832,0.308875,-0.297920,0.203801,0.087028,0.188222,-0.393853,-0.270517,-0.304012,0.213902', '6101834', '1908036', '3445516', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5044741', '爱情维修站', '剧情', '一张中奖彩票，打乱了在婚姻登记处工作的葛大伟（郭涛 饰）和陈小玲（胡静 饰）原本平淡无味的夫妻生活。在小姨子的鼓动下，他们找来几位朋友，开办了一家旨在帮助处于婚姻危机中的男女，解决他们的婚姻危机的爱情维修站。在葛大伟与同事们的共同努力下，他们挽救了一段又一段的婚姻，其间发生了许多啼笑皆非的故事。然而由于资产支配不当，他们的收入并没有随着事业的发展成正比增长。几单生意不仅没有赚到钱，而且把自己的全部积蓄都赔了进去。此时，长期存在于葛大伟和陈小玲之间的矛盾激化，陈小玲最终选择了离家出走。夫妻关系和事业同时走到绝境，葛大伟将如何走出双重困境……本片集结英达、蔡少芬、张晋、苑琼丹等众多明星加盟，惊喜不断，笑声连连。©豆瓣', '郭涛', '王宁', 5.6, 9223, 'tt6419436', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p679389896.jpg', 7.4, 24.6, 51.5, 13.5, 2.9, '0.266462,0.017387,-0.648922,0.287114,0.057006,-0.561212,0.587122,0.369721,-0.164920,-0.205330,0.069112,0.491539,-0.200582,0.059998,0.201228,-0.634584,-0.071705,-0.684712,-0.081885,-0.037231,-0.279409,-0.465834,-0.283495,-0.122812,-0.539588,-0.022316,0.520200,0.156600,-0.357461,0.481817,0.216127,0.184378,-0.127454,0.484623,-0.057635,0.327859,0.143684,0.122050,-0.593778,0.036129,0.099781,-0.227982,-0.083524,0.050535,0.303444,0.269940,0.706103,-0.140523,-0.173572,0.269313,0.285896,-0.186634,-0.135058,0.050624,0.222478,0.081386,0.145664,0.268896,-0.591530,-0.123726,0.052328,-0.137611,-0.930035,-0.009802,-0.110956,0.183448,-0.655080,0.419074,0.141085,-0.079588,0.138723,-0.347634,0.134331,0.785216,0.239642,0.420693,-0.519538,0.041666,-0.689935,0.241005,0.895852,0.008402,0.038208,0.359133,-0.292090,-0.291031,-0.335012,0.043615,-0.428181,-0.133958,0.462788,0.151942,-0.063551,0.256963,-0.612563,0.036611,-0.150160,-0.276812,-0.019275,-0.533475,-0.032305,-0.709542,-0.389964,-0.362663,-0.273979,0.163557,0.246136,-0.242101,0.768223,-0.580314,-0.197358,0.369371,0.430058,-0.617274,0.623919,0.054896,0.471085,-0.227631,-0.212805,-0.184523,0.044791,0.482014,0.440078,0.248527,-0.071868,-0.041358,-0.203067,0.307632', '26678784', '25917239', '30163500', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5044748', '神奇', '剧情', '冰山（黄晓明 饰）是一位游戏软件开发的高手，生活中酷爱篮球。胡椒（冯德伦 饰）与小黑（陈建州 饰）都是冰山开发团队的同事，也都是篮球的狂热爱好者。新的公司CEO上任，并带来一个好消息：公司即将全力开发一款高端篮球游戏——“神奇”。但是原来的开发团队中只有冰山一人可以继续留下来，原有的团队必须解散。面临好友被辞退，冰山也不想继续留下来，可是与胡椒、小黑共同创业的原始资金却远远不够。而原公司开出的成功开发“神奇”后的奖金却是相当诱人。于是冰山决心为公司开发“神奇”。当“神奇”即将要对外发布之际，冰山却发现目前的“神奇”仍然存在漏洞，会对玩家造成神经损害。因此，他坚决反对“神奇”如期发布，并与CEO产生巨大的分歧。此时，女友伊琳（金雅中 饰）与CEO之间的暧昧关系也被他发现。一时间，情感、事业、生活的种种矛盾困扰着他。CEO仍然一意孤行如期发布“神奇”。冰山也决计通过各种手段拆开谎言，与商业利益的追逐者展开一场高智力、高科技的决斗……', '黄晓明', '胡雪桦', 2.9, 13579, 'tt3457380', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2126854605.jpg', 72.5, 15.9, 6.7, 2.2, 2.7, '-0.080440,0.405826,-0.640454,0.558182,0.023130,0.183886,0.413210,-0.007715,-0.462585,-0.206342,0.224887,0.516235,-0.204527,0.031588,0.000783,-0.261250,-0.108844,-0.550090,-0.098291,0.033809,-0.151686,-0.375432,-0.433157,-0.216359,-0.160294,-0.425138,0.894662,0.181710,-0.614387,0.311279,0.227170,0.167470,-0.244226,0.595495,0.179106,-0.392385,0.288985,0.241495,-0.442700,0.170940,-0.038461,-0.001687,0.075544,0.212115,0.103272,0.436355,0.337458,-0.245132,-0.495704,-0.109514,0.465026,-0.099118,-0.045717,-0.091951,0.304400,0.131474,0.342251,0.308892,-0.057415,0.126913,0.075689,-0.356529,-0.943444,-0.117794,0.261291,-0.017212,-0.247462,0.311302,-0.045616,-0.118046,-0.000927,-0.156408,-0.011652,0.184455,0.738960,0.326303,-0.278175,0.402283,-0.287523,0.248274,0.488176,-0.015313,-0.451575,0.384739,-0.337693,-0.503597,-0.204178,-0.392252,-0.237992,0.042552,0.145193,0.419653,0.067604,0.163822,-0.847645,0.223394,-0.156109,-0.144287,0.190565,-0.448845,0.122932,-0.719039,0.022851,-0.242379,-0.236063,0.211189,0.266916,-0.388042,0.811130,-0.677122,0.002797,0.441603,0.423608,-0.583985,0.438405,0.021785,-0.040662,-0.375114,-0.394049,0.107353,-0.070413,0.219382,-0.171654,0.123533,0.359189,-0.387046,-0.288401,0.496860', '27602116', '7155241', '25880986', '6844861');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5045678', '大鱼海棠', '剧情', '所有活着的人类，都是海里一条巨大的鱼；出生的时候他们从海的此岸出发。他们的生命就像横越大海，有时相遇，有时分开……死的时候，他们便到了岸，各去各的世界。四十五亿年前，这个星球上，只有一片汪洋大海，和一群古老的大鱼。在与人类世界平行的空间里，生活着一个规规矩矩、遵守秩序的族群，他们为神工作，掌管世界万物运行规律，也掌管人类的灵魂。他们的天空与人类世界的大海相连。他们既不是神，也不是人，他们是“其他人”。十六岁生日那天，居住在“神之围楼”里的一个名叫椿（季冠霖 配音）的女孩变作一条海豚到人间巡礼，被大海中的一张网困住，一个人类男孩因为救她而落入深海死去。为了报恩，为了让人类男孩复活，她需要在自己的世界里，历经种种困难与阻碍，帮助死后男孩的灵魂——一条拇指那么大的小鱼，成长为一条比鲸更巨大的鱼并回归大海。©豆瓣', '季冠霖', '梁旋', 6.9, 530726, 'tt1920885', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2361744534.jpg', 4.2, 10.7, 36, 31.7, 17.4, '0.115199,0.272554,-0.845092,0.692893,-0.464791,-0.044569,1.065799,0.084904,-0.296426,0.152383,0.079159,1.021438,0.155009,0.179648,0.083212,-0.118866,-0.168008,-0.509697,-0.049870,-0.236449,-0.526542,-0.215340,-0.434260,-0.193654,-0.096245,-0.407447,0.875609,0.202831,0.110773,0.280575,-0.253738,-0.088060,-0.316943,0.440792,-0.546681,-0.070981,-0.291247,0.293930,-0.097945,0.127465,-0.572488,0.220953,0.007120,0.313929,-0.350851,0.147725,0.888221,-0.655178,-0.157286,-0.451576,0.219997,-0.420958,-0.160195,-0.150082,0.534346,-0.180095,0.229078,0.146154,-0.069647,0.074507,0.023806,-0.247977,-0.781055,-0.343816,0.028555,0.341902,-0.311048,0.193569,0.330317,-0.344825,-0.077113,-0.432388,0.246909,0.267999,0.303029,0.540569,-0.383519,-0.161590,-0.646769,0.102845,0.801365,-0.229156,-0.483526,0.333713,-0.283118,-0.423762,-0.275492,-0.075953,-0.512533,-0.131928,0.237381,-0.005879,-0.536037,0.284218,-0.958634,0.392924,-0.194380,-0.307506,-0.229988,-0.535798,-0.284728,-0.238912,0.033658,-0.289413,-0.024920,0.191887,0.207416,-0.317459,0.883564,-0.543484,0.297298,0.603942,0.492225,-0.406164,0.978362,-0.073193,0.279295,-0.466272,0.216835,0.360990,0.114321,0.430301,-0.124074,0.227505,-0.096899,0.590587,-0.566406,0.731783', '21619567', '3055049', '26290398', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5045804', '康定情歌', '剧情', '1949年的一声春雷，使那沉睡已久的雪山也幡然惊醒，古老而神秘的土地上酝酿着一场翻天覆地的变化。1950年的一天，位于四川西南的甘孜迎来了一支红色的队伍，解放军进驻此地，开始修建连接藏区和外部世界的川藏铁路。刚刚大学毕业的地质专业技术员李苏杰（苏有朋 饰）随军前来，一腔热情报效祖国。偶然的机会，解放军搭救了一个落水的贵族，在李苏杰的提议下，贵族释放了两个农奴，其中包括名叫达娃（居文沛 饰）的藏族姑娘。李苏杰不仅砸烂了禁锢她的锁链，也打开了她蒙昧闭锁的心灵。在这片蓝天白云常在的圣地，革命版纯洁的恋情悄悄滋生……©豆瓣', '苏有朋', '江平', 6.7, 5971, 'tt1754001', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p678178958.jpg', 4.2, 11.5, 41, 30.5, 12.8, '0.231947,0.206967,-0.780427,0.696000,-0.059880,-0.016707,0.615197,-0.058299,-0.370879,-0.034703,0.191517,0.569673,-0.119258,0.204054,0.286187,0.022719,-0.070257,-0.606930,-0.275608,-0.135856,-0.413657,-0.064800,-0.378408,-0.155458,0.069158,-0.542528,0.608306,0.391956,-0.197047,0.572812,0.032373,0.192428,-0.141939,0.295951,-0.245345,0.052788,0.062700,0.036065,-0.151475,0.111106,-0.336291,-0.361656,0.054700,0.237756,-0.230461,0.421359,0.603578,-0.350740,0.114875,0.084738,0.370308,-0.238441,-0.026770,-0.004888,0.572616,0.206039,-0.002404,0.172391,-0.261615,-0.004528,-0.002991,-0.316696,-0.254271,-0.250520,0.136703,0.128423,-0.596434,0.647504,0.357943,-0.028879,-0.143760,-0.334299,0.196112,0.426264,-0.037314,0.508305,-0.118137,0.030411,-0.416197,0.309713,0.478004,-0.237630,-0.261704,0.217832,-0.366981,-0.463702,-0.085867,0.066553,-0.466088,-0.330998,0.485034,-0.114384,-0.189355,0.163885,-0.912440,0.027076,-0.220534,-0.125218,0.088506,-0.171988,-0.185185,-0.444484,-0.180756,-0.325102,0.004690,0.235372,0.183020,0.126151,0.856256,-0.666004,0.301061,0.646737,0.092110,-0.209466,0.528588,-0.009539,0.140242,-0.163736,-0.031129,0.228655,-0.210661,0.606522,-0.107599,0.554485,-0.441069,-0.058095,-0.616713,0.478369', '26290398', '5977789', '1414808', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5046033', '黑金', '剧情', '奥达（塔哈·拉希姆 Tahar Rahim 饰）和哥哥从小被寄养在纳萨比门下，纳萨比（安东尼奥·班德拉斯 Antonio Banderas 饰）在一次意外的发现了石油开掘后成为富甲一方的首领，逐渐与境外势力勾结，为了“黑金”置百姓与水深火热而不顾，并为了扩大权势将奥达与公主（芙蕾达·平托 Freida Pinto 饰）联姻。奥达的父亲带领阿拉伯平民，决心向纳萨比宣战，并鼓动自己的亲生儿子奥达的加入，但此刻纳萨比已占有高端军事武器，双方实力悬殊巨大。生性不好战的奥达挣扎在两个“父亲”、两个族群之间，不得不做出残酷的选择，为了百姓的生存与和平，与“不可战胜”的养父展开背水一战。©豆瓣', '芙蕾达·平托', '让-雅克·阿诺', 7.4, 6701, 'tt1701210', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2265669869.jpg', 0.9, 3.8, 34.7, 45.5, 15, '0.147327,0.025238,-0.484727,0.705358,0.111229,-0.169283,0.631762,0.415632,-0.629507,-0.299911,-0.009040,0.987177,0.206079,-0.193096,0.171258,-0.481030,-0.162485,-0.728446,0.020394,-0.049781,-0.005998,-0.875182,-0.226104,-0.563829,-0.275120,-0.488716,0.848202,-0.073798,-0.346514,0.529420,0.515495,0.368428,-0.216202,0.317279,-0.049280,-0.318473,-0.142259,-0.126493,-0.671628,0.194990,-0.200693,-0.051293,-0.120415,0.098916,0.346150,0.314503,0.525048,-0.785081,0.484605,-0.450139,0.087120,-0.473639,-0.037893,0.362790,0.225249,-0.170718,-0.028689,0.403477,-0.015641,-0.131708,0.183586,-0.309851,-0.873176,-0.054278,0.396004,-0.168055,-0.872642,0.688794,-0.060531,-0.265647,0.101115,-0.252876,0.073892,0.808931,0.227897,0.306678,-0.337141,-0.114730,-0.649553,-0.415736,0.741617,-0.121796,-0.169063,-0.094241,0.042512,-0.507823,-0.178984,-0.570219,-0.440017,-0.301317,0.217281,0.163260,0.135613,0.706303,-0.827076,-0.159275,-0.485588,-0.158215,0.380269,-0.514399,0.188714,-0.251734,-0.348896,-0.309428,-0.037262,0.295030,0.115412,-0.226963,0.565246,-0.844743,-0.020371,0.172683,0.656996,-0.721084,0.459550,0.235887,0.405447,-0.132686,-0.368984,0.467237,0.377883,-0.037934,-0.087223,-0.039850,-0.005661,-0.109688,-0.071124,0.149477', '26678784', '1308837', '30345227', '25794212');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5133063', '憨豆先生精选辑', '喜剧', 'Mr. Bean and Teddy venture into the loft to look for an umbrella and uncover items from past experiences, like the time Mr. Bean had to dress himself on the way to the dentist, or the time he fell asleep in moxia.cc church or when the Christmas turkey wound up on his head and even the time a tank crushed his Mini.', '罗温·艾金森', '约翰·伯金', 9.6, 9215, 'tt0291751', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2354179225.jpg', 0.3, 0.2, 2.1, 13.1, 84.3, '0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000', '10001432', '10047547', '10174444', '10342838');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5149279', '迷幻', '剧情', 'Simon Newton（詹姆斯·麦卡沃伊 James McAvoy 饰）是Delancy’s 拍卖行的一名高级工作人员，他尤其擅长在名画面临被盗时的保卫工作。这天，著名画家Goya的一副画《Witches In The Air》（空中女巫）正在拍卖，这幅画预计价值两千五百万英镑。同时，一个以Franck（文森特·卡索 Vincent Cassel 饰）为首的盗贼团伙正在策划盗走这幅画。Franck们的计划进行得十分顺利，而Simon在面对这种场面时也驾轻就熟，迅速将这幅画用袋子装起，进行转移。当Simon即将把画送到安全地方之时，Franck出现了，他用枪击打了Simon的头部，并抢走这幅画。Simon晕了过去。回到家的Franck惊讶地发现，他打开袋子，却发现里面空无一物。Simon苏醒后，Franck找到了他，原来Simon是和Franck一伙的。然而Simon的头部受伤失去了部分的记忆，他忘记了那幅画在哪里。于是Franck带着Simon去找了一个女催眠师Elisabeth（罗莎里奥·道森 Rosario Dawson 饰），希望能够通过催眠让他恢复记忆......', '詹姆斯·麦卡沃伊', '丹尼·博伊尔', 6.9, 19418, 'tt1924429', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1857364371.jpg', 1.3, 7.7, 45.4, 36.4, 9.3, '0.225569,0.193815,-0.378825,0.409825,-0.225402,-0.323228,0.805467,-0.064295,-0.185316,-0.333156,0.178216,0.598190,-0.168352,0.383190,0.259792,0.130341,-0.546110,-0.672541,-0.212859,-0.324188,-0.480179,-0.208961,-0.298158,-0.039363,0.016945,-0.476019,0.440693,-0.063617,-0.193702,0.335038,0.176486,0.203461,-0.171872,0.230686,-0.123528,-0.079994,-0.178448,-0.242232,0.064987,0.334267,0.099661,-0.277452,-0.009437,0.367443,-0.036563,0.282856,1.128450,-0.393680,-0.090479,0.113238,0.553773,-0.157698,0.001107,0.182669,0.080810,0.322619,-0.129613,-0.459609,-0.557321,0.060372,0.280262,-0.110740,-0.816641,-0.105192,0.073452,0.207100,-0.570590,0.262266,-0.179951,0.367547,0.016928,-0.514303,0.428497,0.470233,0.132951,0.347598,-0.036829,-0.027952,-0.732632,-0.033339,0.144151,-0.106461,-0.083328,0.492225,0.063123,-0.207680,-0.012928,-0.284361,0.111415,0.037663,0.501304,0.200344,0.026473,-0.446162,-0.578544,-0.292731,-0.344752,-0.266968,0.031712,-0.259169,-0.393401,-0.633809,-0.072687,-0.189282,-0.301043,-0.169412,-0.174198,-0.327418,0.569900,-0.508067,0.257766,0.482806,-0.094572,-0.174485,0.412075,-0.093270,-0.155503,-0.155992,-0.268477,0.066201,0.465451,0.637846,0.107027,0.445424,0.032779,-0.339330,-0.534984,0.539487', '21619567', '25774050', '1467779', '6877520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5150481', '蝙蝠侠：元年', '剧情', '《蝙蝠侠:第一年》原著漫画于1988年首次发表，作者弗兰克·米勒开创性地再造了蝙蝠侠的起源故事——他是什么人，他如何成为蝙蝠侠。本作从布鲁斯·韦恩第一次回到高谭市为开端，为这个传奇人物的诞生打下了新的基础，成为正史中最重要的一页。作为一切故事的开端，本集讲述了各个人物的来历。哈维·邓特不是令人瞩目的青年才俊，而是屡败屡战的检察官；猫女赛琳娜·凯勒不是上流社会的优雅贵妇，只是一名出身街头的穷妓女。在他们生存的哥谭市里，官员们同黑帮勾结，警察是罪犯的保护伞。新调来的警官詹姆斯·戈登想在一个堕落的城市做一名好警察；刚刚回到故乡准备扫尽罪孽的布鲁斯·韦恩则在流血中懂得，惟有让人恐惧才能叫人尊敬。在深夜中，他悄然出现，又随着宽大黑披风带起的一缕微风而没入黑暗。有人说他是野蛮的暴徒，有人说他是嗜血的疯子，也有人认为他只是一个都市传说。一切传说都有它的起源……©豆瓣', 'Ben McKenzie', '刘山姆', 8.3, 8759, 'tt1672723', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2368827266.jpg', 0.3, 0.9, 16.4, 50.1, 32.3, '0.245434,-0.023811,-0.426200,0.638924,-0.341709,-0.102404,0.720658,-0.093847,-0.584748,-0.366099,0.491979,0.901062,0.072966,0.081925,0.118094,0.144712,-0.239633,-0.640491,0.024694,-0.276552,-0.254281,-0.337955,-0.334663,-0.343287,-0.094882,-0.188250,0.508143,0.147032,-0.320829,0.073770,0.299172,0.296040,-0.057320,0.230340,-0.352413,-0.041366,0.059046,-0.010470,-0.248912,0.187191,-0.227040,-0.164707,-0.335132,-0.032749,-0.151335,0.175107,0.390513,-0.249811,0.059729,0.030174,0.526328,-0.368853,-0.212116,-0.053490,0.399267,-0.105564,0.027770,0.189475,0.218376,-0.088252,-0.139544,-0.194310,-0.932367,-0.158450,-0.145584,0.401885,-0.419490,0.514476,-0.072450,-0.101884,0.200598,-0.293135,0.216152,-0.075881,0.237665,0.368374,0.175711,0.125484,-0.495341,0.408260,0.593372,0.220156,-0.412350,0.229660,-0.306369,-0.520840,-0.177958,-0.111099,-0.452923,-0.132255,0.306509,-0.241871,-0.136850,0.509352,-0.609974,0.059374,-0.023209,-0.210866,0.050051,-0.243266,-0.377251,-0.276825,-0.204352,-0.259373,-0.028250,-0.154110,0.088675,-0.354204,0.953727,-0.892234,0.321297,0.626935,-0.070409,-0.436565,0.600160,0.001511,0.173564,-0.153235,-0.145488,0.216349,0.283523,0.352597,0.066514,0.287948,-0.166476,-0.216555,-0.276578,0.455325', '276