INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5151357', '梅子鸡之味', '剧情', '因为妻子摔破了自己心爱的小提琴，音乐家纳瑟·阿里（马修·阿马立克 Mathieu Amalric饰）决定自杀，绝食八天后他终于死去。在这八天里，躺在床上的他回顾了自己的一生。他想起了自己与弟弟的小时候，想起了自己的女儿和儿子，想起了自己失败的婚姻，想起了母亲临死前的场景。当然，他还想起了自己一生的挚爱——伊兰娜（格什菲·法拉哈尼 Golshifteh Farahani 饰）。年轻时的他，音乐造诣并不高，被老师评价为只有技巧缺乏感情。有一次，他在一家钟表店邂逅了美丽的伊兰娜。从此他的命运改变了方向，他与伊兰娜经历了一场难忘的恋爱。然而，命运弄人，他与伊兰娜最终还是分开了……《梅子鸡之味》改编自导演 玛嘉·莎塔琵的绘本作品。主人公原型是导演的伯父，是伊朗一位著名的音乐家。©豆瓣', '伊莎贝拉·罗西里尼', '玛嘉·莎塔琵', 8.1, 34541, 'tt1663321', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1733151422.jpg', 0.3, 1.6, 20.2, 48.7, 29.2, '0.050538,-0.014514,-0.570167,0.677281,-0.059137,-0.507911,0.918084,0.048370,-0.370594,-0.312734,0.388026,1.140948,-0.077194,0.515486,0.308986,0.540097,-0.447631,-0.895920,0.421455,-0.080996,-0.111024,-0.464453,-0.094112,-0.005644,0.055568,-0.483023,0.417697,-0.234443,-0.009389,0.280417,0.196778,0.000251,0.214536,0.493777,-0.024629,0.529669,0.212633,-0.070578,-0.174961,-0.061620,0.323987,-0.368528,-0.182460,0.260360,-0.126873,0.226048,0.714046,-0.416895,-0.024746,-0.235745,0.420567,-0.423357,-0.021590,0.165655,-0.001910,-0.127558,0.213415,0.303518,-0.218557,-0.216255,0.220716,0.064600,-0.700341,0.091765,0.042402,-0.124869,-0.846598,0.766140,-0.267903,0.050320,0.273652,-0.337857,0.230456,0.159672,0.291213,0.288816,-0.346392,-0.200846,-0.423461,0.396774,0.759419,-0.016594,-0.125264,0.666488,-0.137771,-0.615581,-0.128083,-0.268184,-0.507865,0.251391,0.448809,-0.057970,-0.360434,0.123991,-0.388626,-0.156254,-0.302308,-0.174766,0.003416,-0.428055,-0.237429,-0.168948,-0.273261,-0.596368,-0.456099,-0.284093,-0.119691,-0.534605,0.800734,-0.830354,0.038378,0.576593,0.097297,-0.287255,0.798429,0.200210,0.066455,-0.095192,0.233879,0.375002,-0.436296,0.169196,0.248328,0.320272,0.169730,0.283126,-0.332842,0.733815', '30162520', '1292207', '26958479', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5151890', '特种部队', '剧情', '一名法国战地记者女记者Elsa（黛安·克鲁格 Diane Kruger 饰）和她的同事在巴基斯坦采访期间遭到塔利班绑架。塔利班将被捕获的Elsa相关视频放倒了网络上，并声称在规定时间内，她将在摄像机面前被处死，却全世界的人民都可以通过网络看到全过程。在Elsa被行刑之前，一支由特种部队成员组成的救援小组被法国军方派来营救她。面对着极其残暴的塔利班亡命之徒，救援小组不畏艰险在第一时间就救出了Elsa，却与总部失去联系，不得不开始一场更为险恶的保卫战。一场在塔利班追捕者和救援小组之间的拉锯逃亡战不可避免的展开了。塔利班设下各种陷阱，未将救援小组一网打尽，而救援小组只有一个目标：成功营救Elsa逃离此地。©豆瓣', '黛安·克鲁格', 'Stéphane Rybojad', 6.7, 12136, 'tt1656192', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2318901523.jpg', 2.1, 11.5, 46.8, 29.5, 10.1, '0.425382,0.156401,-0.797707,0.650971,-0.008943,0.138449,0.430171,-0.290185,-0.452964,-0.030573,0.130841,0.617025,-0.116637,0.053194,0.245324,-0.518988,-0.394770,-1.043515,-0.625012,-0.230690,-0.514624,-0.485953,-0.251552,-0.145584,0.083694,-0.392423,0.922574,0.198298,-0.309616,0.440469,0.319051,0.272315,-0.451124,0.668552,-0.061316,-0.280762,0.486337,-0.468420,-0.320402,0.485775,-0.111923,-0.625856,-0.173627,0.318109,-0.104427,0.455943,0.853602,-0.362790,0.181800,-0.273257,0.136632,-0.722719,0.168273,0.112483,0.809284,0.215205,0.028813,0.393502,-0.174021,0.210147,0.025767,-0.062453,-0.957045,0.139218,0.095456,0.128346,-0.785130,0.361419,-0.346782,0.520625,0.145999,-0.226107,0.278746,0.903717,0.305977,0.045495,-0.142485,-0.150464,-0.647000,0.149819,0.975214,-0.204142,-0.138914,-0.220511,0.122073,-0.435360,0.189969,-0.267497,0.036316,-0.141705,0.489585,-0.225865,-0.073284,0.111580,-0.774194,0.099277,-0.504751,-0.512311,-0.091017,-0.548817,-0.011695,-1.268821,0.102439,0.111289,-0.344610,0.582254,0.212144,0.050447,0.854965,-0.902084,0.089655,0.784667,0.443868,-0.547234,0.448537,0.270434,0.221579,-0.121640,0.007300,-0.068973,0.566216,0.741645,0.274534,0.282876,-0.339851,-0.333745,-0.484063,0.117706', '2369613', '25723905', '6984051', '5157137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5151891', '暂告安全', '动作', '莱特（杰森·斯坦森 Jason Statham 饰）是一个不守规矩、只认死理的前纽约警察。一天，他在地铁站里看到一群持械的黑帮成员在围剿一个12岁的华裔女孩梅（凯瑟琳·陈 Catherine Chan 饰）。他心里的正义感油然而生，遂出手教育了这群黑帮，并把小女孩保护了起来。紧接着，香港的三合会成员、俄罗斯混混以及政客派来的杀手和警局里的恶棍源源不断地找上门来。无奈之下，莱特只得带着梅在纽约的版图上开始了东躲西藏的亡命生涯。原来，梅有着过目不忘的本领，她记下来了一连串的数字，而这些数字经过解密后是一个密码。知道了事件原委的莱特决定帮助梅度过难关。但是，的又等待他们是一场怎样的战斗呢？©豆瓣', '杰森·斯坦森', '鲍兹·亚金', 6.3, 17029, 'tt1656190', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1395328327.jpg', 2.3, 14.5, 54.9, 21.5, 6.9, '0.441079,0.012417,-0.700880,0.727392,-0.058286,-0.286827,0.704058,-0.186016,-0.676856,-0.170279,0.065109,0.691944,-0.175488,0.666879,0.284397,-0.118494,-0.337274,-0.766808,-0.358691,-0.285218,-0.454518,-0.497829,-0.196966,-0.477187,-0.037447,0.158761,0.322627,0.376926,-0.122587,0.416789,0.541285,0.424718,0.030602,0.438974,-0.152214,-0.052825,0.260280,-0.168908,0.124146,0.099028,0.195023,-0.538779,-0.067559,0.190640,0.088056,0.440220,0.685498,-0.396833,0.166706,-0.155810,0.306043,-0.534482,-0.159593,0.031886,0.458183,0.005311,0.117362,-0.046453,-0.049366,-0.019220,-0.016108,-0.175919,-0.732832,-0.131216,0.054679,0.260838,-0.880919,0.304966,-0.131567,0.130900,-0.064769,-0.216928,0.126034,0.308515,0.130020,0.312103,-0.091102,0.030061,-0.739683,0.004473,0.592046,0.060412,-0.103541,0.137029,-0.237880,-0.723312,-0.167178,-0.188136,-0.301854,-0.279536,0.412279,-0.385939,-0.147156,-0.202006,-0.601028,-0.012143,-0.219582,-0.195764,-0.255484,-0.326842,-0.097928,-0.562927,-0.070464,-0.491492,-0.463208,0.190549,-0.042242,0.028529,0.953616,-0.863791,-0.060258,0.619263,0.083980,-0.500999,0.448646,0.083159,0.145679,-0.018437,-0.048038,0.061836,0.364996,0.262681,0.201071,0.539115,-0.047277,-0.296958,0.030666,0.374517', '1292829', '1301022', '21360412', '26730542');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5151892', '劫案迷云', '剧情', '威尔·蒙哥马利（尼古拉斯·凯奇 Nicolas Cage 饰）的四人盗窃团伙在一次行窃银行金库时被埋伏在现场的FBI逮个正着，同伙文森特在混乱中中枪，而威尔将赃款付之一炬后独自被捕。八年后，威尔出狱，迎接他的是怀疑他当年私藏赃款的FBI探员安德森，以及女儿艾莉森（ 萨米·盖尔 Sami Gayle 饰）的敌视，威尔心力憔悴之际突然收到了文森特绑架艾莉森的消息。原来当年行窃失败后文森特陷入潦倒，为了讨还一千万中属于自己的部分他绑架了艾莉森。威尔试图向FBI求助却不被安德森信任，无奈只得独自拯救女儿，为此他不惜找到当年的搭档蕾莉(玛琳·阿克曼 Malin Akerman 饰)，准备再次犯案……©豆瓣', '尼古拉斯·凯奇', '西蒙·韦斯特', 6.1, 21358, 'tt1656186', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1678133022.jpg', 2.3, 16.5, 60.5, 16.7, 4.1, '0.128002,0.115743,-0.712742,0.167852,-0.309357,-0.590414,0.846314,0.107786,-0.576054,-0.179907,0.399384,0.714746,0.126215,0.136096,0.500923,0.291479,-0.411227,-0.657206,-0.267685,-0.108218,-0.204627,-0.860013,-0.430262,-0.435044,-0.110022,-0.398043,0.290750,0.171517,-0.223498,0.374817,0.248628,0.630790,-0.064331,0.443559,0.217292,0.053755,0.547367,-0.371098,-0.156377,0.240509,-0.041642,-0.578125,-0.169098,0.338887,-0.117588,0.594325,0.543249,-0.098181,0.154406,-0.139095,0.079069,-0.353939,-0.058048,0.135917,0.109366,-0.119688,0.361079,0.301825,-0.298354,-0.323306,0.312425,0.069838,-0.681863,0.137438,-0.195344,0.213045,-0.685301,0.358591,-0.473841,0.234282,0.508832,-0.404274,0.107672,0.496965,0.171517,0.147552,-0.212893,-0.168671,-0.339153,0.246056,0.265825,-0.123376,0.197134,0.125225,0.176114,-0.282009,0.319524,-0.054603,-0.399261,-0.028836,0.835987,0.079730,-0.124989,0.326407,-0.367455,-0.403142,-0.433216,-0.204944,0.009185,-0.276925,-0.194619,-0.746908,-0.051430,-0.022678,-0.448348,-0.081372,-0.035750,-0.106010,0.021624,-0.554913,0.451160,0.660839,-0.034445,-0.554080,0.330891,-0.116311,0.105259,0.094277,-0.054754,0.195941,0.400331,0.524896,0.362976,-0.039413,0.115033,-0.356382,-0.400222,0.426765', '1301345', '1316693', '4132395', '20277632');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5151939', '我与梦露的一周', '剧情', '刚刚踏入社会的英国青年科林·克拉克（埃迪·雷德梅恩 Eddie Redmayne 饰）不顾家庭反对，将满腔热情投入自己热爱的电影事业之中，希望能闯出一番天地。勤奋的他得到的第一个跟组机会，竟是担任他的偶像劳伦斯·奥利弗（肯尼思·布拉纳 Kenneth Branagh 饰）导演并主演的新片《游龙戏凤》剧组的第三助理导演。这部电影邀请了当时红遍全球的美国影星玛丽莲·梦露（米歇尔·威廉姆斯 Michelle Williams 饰）主演，而科林的工作便是统筹剧组的各项杂务。开拍之后，梦露与劳伦斯·奥利弗之间因表演方法不同而产生了激烈冲突，致使剧组进度远远落后预期。科林负责于当中调停，他开始与梦露频繁接触。不知不觉间，科林发现自己已为梦露的魅力所深深吸引……米歇尔·威廉姆斯凭借本片荣获2012年金球奖最佳女主角（喜剧/音乐类）。©豆瓣', '米歇尔·威廉姆斯', '西蒙·柯蒂斯', 7.3, 34639, 'tt1655420', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1346149420.jpg', 0.5, 3.6, 39.5, 45.6, 10.8, '0.145156,0.149112,-0.617021,0.526440,0.269951,-0.412721,0.337169,0.185631,-0.391540,-0.259052,0.119210,0.764292,-0.506725,-0.037082,0.494643,-0.135173,-0.457087,-0.858487,-0.129447,0.104855,0.145980,-0.370606,-0.406513,-0.096492,-0.259360,-0.522732,0.803551,-0.163543,-0.262828,0.504654,0.366749,0.094736,0.142925,0.208415,0.628222,0.155682,0.572834,-0.244397,-0.674713,0.489336,0.143745,-0.003103,-0.200490,0.250842,-0.045737,0.314094,0.472632,-0.013665,0.085639,-0.192452,0.688406,-0.028112,0.140097,-0.078042,0.111156,0.124308,0.424274,0.264572,-0.125550,0.212844,-0.088430,-0.231620,-0.623453,0.187202,0.133953,0.130248,-0.159925,0.161417,-0.231557,-0.083328,0.158903,-0.210209,-0.154071,0.265076,0.416660,0.250580,-0.153962,0.080541,0.029437,0.585590,0.380459,0.084062,-0.384981,0.552851,-0.151870,-0.410963,-0.161847,-0.171042,-0.433513,-0.021483,0.240491,0.075280,0.357671,0.297667,-0.305346,0.024663,-0.255175,-0.321284,-0.005204,-0.164647,0.156030,-1.177999,-0.323713,-0.141388,-0.020300,-0.528069,0.119612,-0.279217,0.708450,-0.674452,0.093234,0.555547,0.143453,-0.222595,0.630879,0.018250,0.258582,-0.187050,-0.223384,0.169460,-0.224365,0.033946,-0.051979,0.170352,0.120245,-0.428594,-0.202597,0.362741', '24751811', '3077791', '262