INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5152333', '艾玛好色', '喜剧', '新品种少女学。女孩艾玛有点色，色情电话来谈心，老板到老友，男女都可以，异想世界中通通恋上我的床，直到白马王子咚咚来，一个「擦枪走火」，从此引发好姊妹之间战火。当整个小镇与我为敌。身体乍萌的战慄与微微的迷惑。女孩之间转瞬变脸合纵连横的複杂关系，清新又坦荡，越要爱越要作 。追忆起那些汤汤水水的甜蜜事儿。青春微色，微涩。少女情怀总是湿。新世代少女站出来，导演雅妮克贾考森重写成长电影系谱，让鸡汤变清水，欲望可以很混浊也能很纯净，直触成长不可言说之蕊心，亲情友情爱情层次分明一次到位，还有激情和恋情，浑然天成毫不造作。荣获翠贝卡影展最佳剧本奖。每个女人心里都住著一位少女。每个少女心头都该有这部青春映画。', 'Julia Schacht', '杨尼克·西斯泰德·雅各布森', 6.5, 11843, 'tt1650407', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1326121395.jpg', 2.5, 12, 51.5, 26.6, 7.4, '-0.085500,0.102146,-0.541649,0.525305,0.125698,-0.249935,0.758391,0.003407,-0.230448,0.019968,-0.243844,0.413295,-0.333513,0.296390,0.258230,-0.059908,-0.303228,-0.706950,-0.113394,-0.175298,0.041111,0.042520,-0.097093,0.110876,-0.277859,-0.237418,0.511383,-0.020816,-0.123128,0.208084,0.340996,-0.120938,-0.212572,0.271690,0.010035,-0.229222,-0.156934,-0.045098,-0.328281,-0.117532,0.110766,0.010648,-0.158698,-0.005449,-0.145340,0.032520,0.498597,-0.070184,-0.223942,-0.078968,0.363664,0.254145,-0.052228,-0.049129,0.013667,-0.101740,0.346789,0.039423,0.136130,0.100649,0.129324,-0.025955,-0.430936,0.093364,0.014280,0.322155,-0.242084,0.215108,0.080606,-0.150335,0.217912,-0.057596,-0.021232,-0.191614,0.701077,0.480515,-0.179540,0.025195,-0.357791,0.338551,0.554655,0.412085,-0.164263,0.596291,-0.520060,-0.375855,-0.014031,0.076333,-0.501062,0.030609,0.099315,0.012222,0.177395,0.625184,-0.656237,0.111977,-0.009634,0.180787,0.006289,-0.373805,-0.024449,-0.203267,-0.392855,-0.139455,-0.288823,0.087737,0.438269,-0.239695,0.681893,-0.713417,-0.085302,0.362554,0.010265,-0.190287,0.214634,0.367571,-0.154590,-0.191658,-0.257502,0.459968,-0.358563,0.079553,-0.099661,0.521441,-0.277582,0.365387,-0.325320,0.433739', '3012033', '1292062', '10533913', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5152678', '丛林大反攻3', '动画', '讲述埃利奥特和他们所有的森林朋友一个全新的冒险，Boog他决定自己旅行，一个酷似马戏团的灰熊，接管他的位置。 布格的朋友准备把他从俄国旅行马戏团带回家。一连串有趣的事情。', 'Matthew J. Munn', 'Cody Cameron', 6.5, 4559, 'tt1646926', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1419573615.jpg', 1.4, 10.3, 56.5, 23.6, 8.2, '0.494271,-0.238153,-0.453179,0.897595,-0.367355,-0.235491,0.626893,0.145613,-0.136298,-0.461286,-0.008858,1.372149,0.011171,0.373739,0.129089,0.338810,-0.414170,-0.767995,-0.326203,0.172479,-0.394459,-0.328995,-0.308890,-0.665715,0.237496,0.059664,0.542241,-0.147788,-0.290819,0.342287,0.493686,0.025733,-0.249612,0.404087,-0.530179,0.028888,0.243325,0.244915,-0.182045,0.138345,-0.322932,0.254398,0.080793,0.332585,0.118624,0.391906,0.955085,-0.106423,-0.252819,-0.059681,0.190879,-0.500747,0.075424,0.162298,0.019198,-0.010436,-0.079138,0.110833,-0.217325,-0.218214,0.042650,-0.423190,-0.962635,-0.050390,-0.209418,-0.075344,-0.809311,0.358662,0.110967,0.231278,0.563006,-0.393226,0.131640,0.424007,0.070836,0.141730,-0.005070,0.020890,-0.101489,0.678068,0.853544,-0.299001,0.016220,0.332317,-0.174480,-0.293174,0.163400,0.278816,-0.526470,-0.005771,0.579662,-0.467116,-0.333340,-0.031468,-0.886170,-0.307381,-0.172017,-0.717921,0.095682,-0.465904,0.060136,-0.474655,-0.102642,-0.142796,-0.579524,-0.055853,0.032832,0.219210,0.730018,-0.537253,0.141629,0.915934,-0.210353,-0.538110,0.532279,-0.106054,0.240840,-0.789471,0.215702,0.033248,0.140292,0.364350,0.218024,0.692317,0.192391,0.006725,-0.938181,0.688504', '24733428', '30162520', '34890458', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5153144', '驯龙骑士', '动画', '屹立于中世纪的加布莱尼亚王国，曾经是骑士辈出的勇者之乡，但现如今司法已占据绝对的统治地位，舞刀弄剑不再受到褒扬，精通法律的人才会受到尊敬。瘦弱青年贾斯汀（弗莱迪·海默 Freddie Highmore 配音）是一名著名律师的儿子，他不愿像父亲那样走上法律的道路，而是希望成为爷爷罗兰爵士那样的传奇骑士。在祖母的鼓励下，贾斯汀踏上了追寻梦想的冒险旅程。路上他结识了酒吧女孩塔莉娅（西尔莎·罗南 Saoirse Ronan 配音）、怪怪巫师梅尔的您朋友，骑士的修行路上充满挑战。与此同时，贾斯汀所在的王国内，一伙罪恶之徒正悄悄实行着一系列邪恶的计划。命运将匡扶正义的使命交付在贾斯汀的手中……©豆瓣', '安东尼奥·班德拉斯', '曼努埃尔·西西里阿', 6, 8756, 'tt1639826', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2174081190.jpg', 6.6, 20, 49.4, 17, 7, '0.046008,0.033759,-0.274759,0.805118,-0.046798,-0.371870,0.457875,0.246703,-0.448481,-0.255436,0.607415,0.722085,0.300065,0.196090,0.698821,-0.149427,-0.282379,-0.468418,-0.126889,-0.010345,-0.142101,-0.536082,-0.110446,-0.138060,-0.439724,-0.590146,0.655431,0.151568,-0.286192,0.127781,0.314998,0.404245,-0.125799,0.267585,0.009885,-0.117963,0.300402,-0.155620,-0.349530,0.148587,-0.017984,0.002505,-0.027479,0.166949,0.127391,0.082689,0.193309,-0.443882,0.240087,-0.522854,0.389401,-0.307318,0.252410,0.098911,0.061699,-0.125470,-0.043959,0.133694,0.168401,-0.303402,0.180910,-0.429724,-0.673830,-0.116726,0.215716,0.344931,-0.811258,0.187117,-0.099055,-0.001242,0.078946,-0.271246,0.043883,0.237751,0.485301,0.170673,0.180169,-0.035716,-0.449147,0.148403,0.571526,0.214332,-0.435270,-0.256055,-0.420143,-0.550677,-0.039369,-0.149834,-0.841039,-0.187774,0.417734,-0.198220,0.134321,0.600973,-0.396437,-0.311067,-0.119162,-0.022652,0.261371,-0.413270,0.144613,-0.519121,0.276339,-0.352524,0.020649,0.024028,0.083407,-0.343443,0.684151,-0.762572,0.354983,0.472707,0.401613,-0.218462,0.651282,-0.165131,0.303648,-0.281634,-0.072168,0.862914,0.258089,0.318031,-0.010945,0.177094,-0.086034,-0.240925,-0.286720,0.685434', '1460341', '1870681', '1905462', '1972721');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5153254', '爱你，罗茜', '喜剧', '《親愛的，原來是你》(Love, Rosie)改編自全球破億經典愛情電影《留給最愛的情書》(PS, I Love You)原著小說作家Cecelia Ahern另一幽默感人作品《Where Rainbows End》。由基斯頓迪他(Christian Ditter)執導，《魔鏡•魔鏡:白雪公主決戰黑心皇后》莉莉歌蓮絲(Lily Collins)及《飢餓遊戲》系列森加芬(Sam Claflin)主演。故事講述青梅竹馬的二人，一同成長面對大世界，一直處於「友達以上，戀人未滿」的狀態，卻各自遇到戀愛上的酸甜苦辣，直到最後發現，最愛的原來就是對方。二人首次合作即默契十足，火花閃耀大銀幕。為今個聖誕，帶來最觸動人心、最浪漫感人的愛情喜劇。', '莉莉·柯林斯', '克利斯汀·迪特', 7.5, 160732, 'tt1638002', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2190768432.jpg', 1, 5, 32.3, 41.5, 20.3, '-0.085374,-0.265409,-0.505044,0.511136,0.384311,-0.162845,0.541841,0.123726,-0.689092,0.031936,0.343390,0.783930,-0.485494,-0.071439,0.337289,0.005147,-0.243525,-0.393760,-0.147697,-0.334003,-0.020771,-0.340020,-0.164078,0.049384,-0.087447,-0.047654,0.510408,-0.306505,0.040242,-0.012035,0.564363,-0.028486,-0.463128,0.342870,0.105808,0.008591,0.234497,-0.030128,-0.702305,-0.156317,-0.192021,0.205243,-0.518941,-0.174919,-0.464299,-0.100141,0.469247,-0.410380,-0.018211,0.019857,0.553180,0.062654,-0.138374,-0.272305,-0.094245,-0.323215,0.885191,0.464771,0.336978,0.009315,0.079520,-0.177777,-0.652374,0.207383,0.165731,-0.098006,-0.039429,0.290014,0.106319,-0.052104,0.474691,-0.118164,-0.078039,-0.143844,0.623761,0.225200,-0.377117,-0.116581,-0.032385,0.521819,0.408948,0.259419,-0.350371,0.571923,-0.186210,-0.459321,-0.097677,-0.207923,-0.298396,0.084642,0.360471,0.099036,0.205459,0.482694,-0.895118,0.128709,0.120001,0.051591,0.434624,-0.147276,0.089472,-0.596835,-0.239650,-0.236491,-0.256417,-0.084530,0.384629,0.110976,1.263761,-0.668786,0.082083,0.245908,-0.124200,-0.182859,0.755066,0.261473,0.077661,-0.268254,-0.094148,0.122871,-0.313395,-0.093235,0.015453,0.496803,-0.066818,-0.194004,-0.309641,0.407716', '27602116', '24284209', '1302661', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5153329', '名侦探柯南：天空的遇难船', '动作', '铃木园子的叔叔次郎吉不甘心失败，决定再次向怪盗基德发出挑战。这位坏脾气的大叔斥巨资制造了巨型的飞船贝尔·雪利二世号，并以镶嵌有名贵宝石“天空的贵妇人”的戒指作赌注，邀请基德前来挑战，看他能否在东京到大阪的这6小时时间内完成这项困难的任务。柯南、小兰等人理所当然也接到邀请，甚至电视台的人也兴师动众前来。随着时间的流逝，双方的对决悄悄展开。另一方面，恐怖组织红色暹罗猫也登上了飞船。此前不久，红色暹罗猫袭击了国立东京微生物研究所，并盗走一种致命的病毒。本片根据青山刚昌的同名漫画改编，是该动画的第14部剧场版。©豆瓣', '高山南', '山本泰一郎', 7.5, 90414, 'tt1636815', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2259010597.jpg', 0.5, 3.7, 34.2, 43.2, 18.4, '0.027605,0.135651,-0.532000,0.541797,0.256783,-0.191145,0.233070,0.080640,-0.210315,-0.061272,0.342018,0.386397,-0.115801,-0.173572,0.208693,0.118698,-0.452174,-0.332175,-0.122664,-0.308310,-0.333150,-0.222912,-0.155372,-0.350886,0.358927,-0.112722,0.568705,0.105528,-0.081487,0.544188,0.328343,0.314668,0.005499,0.287148,0.138869,0.031033,0.149487,-0.035982,-0.110853,0.303555,-0.107136,0.033408,0.032560,-0.074818,0.225237,0.397838,0.646344,-0.361673,-0.108816,-0.276561,0.383310,-0.189029,0.074593,-0.033812,0.428820,0.150864,-0.065346,0.163788,-0.179971,0.271809,-0.128591,-0.036035,-0.590232,0.138612,-0.035885,0.145979,-0.095059,0.446072,-0.212718,0.051389,0.122658,-0.287343,-0.124104,0.365169,0.154417,-0.059565,-0.157657,0.110808,-0.299578,0.295696,0.273311,-0.061257,-0.200484,0.270861,-0.012604,-0.462215,-0.169991,-0.226188,-0.020225,0.000482,0.469025,0.073708,-0.065322,-0.000973,-0.701675,-0.072463,-0.220523,-0.361832,0.206339,-0.213378,-0.101013,-0.917974,0.120007,-0.119052,-0.114000,0.018717,0.213638,-0.033460,0.523130,-0.504838,-0.055817,0.698042,0.300584,-0.065397,0.442586,-0.023861,-0.291485,-0.213910,-0.241961,-0.064891,0.175030,0.803953,0.060741,0.159917,0.418711,-0.261412,-0.429949,0.142515', '2369613', '20274039', '2159244', '6984051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5154197', '德州，北海', '剧情', '60年代的比利时，小男孩皮姆（杰尔·弗劳里佐恩 Jelle Florizoone 饰）和单亲妈妈伊薇特（伊娃·范·德·古奇特 Eva van der Gucht 饰）住在北海边的凋敝小镇上，当地最繁华的场所是一家叫做“德州”的酒吧。皮姆从小就很特别，他喜欢玩公主侍女游戏 ，喜欢绘画，喜欢英俊的男孩，喜欢收藏心爱人的物件。邻家男生吉诺（马提亚斯·瓦格尔斯 Mathias Vergels 饰）和妹妹萨布丽娜（妮娜·玛利亚·柯特卡斯 Nina Marie Kortekaas 饰）是皮姆青梅竹马的玩伴，皮姆和吉诺偷尝禁果引发一段暧昧而苦涩的初恋。当英俊的吉普赛青年卓坦（托马斯·库芒 Thomas Coumans 饰）意外出现后，皮姆的生活更是发生无可挽回的改变…《德州北海》改编自比利时女作家安德烈·索丽的成长小说《这是永远》。导演巴沃·德弗恩是位公开同志，他的短片多次在国际上获奖，其视觉效果被誉为“有着超脱世俗的顽劣和清新之风”。《德州北海》是巴沃·德弗恩的第一部剧情长片，“一般来说，成长电影往往结束于主人公找到自己的身份。但这并不是这部片的主题，它是关于爱，关于寻找自己的幸福。”本片获蒙特利尔国际电影节银丝带奖和影评人费比西奖，罗马国际电影节都市爱丽丝奖。', '杰尔·弗劳里佐恩', '巴沃·德弗恩', 7.4, 7121, 'tt1625150', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2515106386.jpg', 0.5, 3.8, 38.3, 41.6, 15.9, '0.228615,-0.103258,-0.502380,0.626806,0.217781,-0.054995,0.588422,0.055925,-0.266274,-0.160677,-0.011294,0.854533,-0.259882,0.241646,0.354027,0.286131,-0.394395,-0.519233,0.092886,-0.210958,0.017131,-0.369613,-0.403166,-0.076798,-0.170872,-0.454054,0.563785,0.203590,-0.214930,0.394071,0.522096,0.351900,-0.072545,0.147023,-0.248640,0.088411,0.130026,-0.016367,-0.405220,0.161067,0.057756,0.100321,-0.059210,0.017436,0.248273,0.141519,0.520118,-0.157169,-0.034668,-0.111327,0.565735,0.018551,-0.021193,-0.201409,0.172096,-0.177666,0.271222,0.062699,0.082162,-0.050864,0.044274,-0.397459,-0.439358,0.071788,0.351997,0.258629,-0.322394,0.311592,-0.143284,-0.205035,0.031976,-0.297443,0.153807,0.003602,0.383805,0.236416,0.219314,0.204564,-0.400245,0.354235,0.407418,0.230405,-0.469507,0.346365,-0.530038,-0.447919,-0.166053,-0.309885,-0.658538,0.246933,0.305571,-0.262489,0.056506,0.195856,-0.553859,-0.020124,0.020567,-0.114700,0.145605,-0.162954,-0.189189,-0.765131,-0.054518,-0.723882,-0.155573,-0.273637,-0.010582,-0.329801,0.745237,-0.735695,0.321578,0.509423,0.265765,-0.244757,0.772392,0.200253,-0.024088,-0.217420,-0.239400,0.591490,-0.056954,-0.175900,-0.239172,0.356858,0.025550,-0.265972,-0.358231,0.567218', '26611806', '30162520', '2338019', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5154496', '火鸡总动员', '喜剧', '蓝色脑袋的瑞基（欧文·威尔逊 Owen Wilson 配音）是一只特立独行、与众不同的火鸡，他清醒地认识到自己和同类降生到这个世界的命运，那就是变成感恩节餐桌上的晚餐。他一直在告诫伙伴们这个事实，可是同类们认贼作父，以敌为友，甚至认为被农夫抓走就会过上天堂一般的生活。又一年感恩节到来，瑞基阴差阳错成为被总统赦免的火鸡，继而来到总统一家过上养尊处优、快乐非常的逍遥日子。直到某一天，早已忘记那群傻同类的瑞基遭到绑架，那是号称来自自由火鸡战线的杰克（伍迪·哈里森 Woody Harrelson 配音）。杰克将带着瑞基乘坐时光机穿越时空，回到第一个感恩节，改变火鸡一族悲惨的命运。离奇而不可能的任务，两只火鸡能否改变历史……©豆瓣', '欧文·威尔逊', '吉米·海沃德', 6.1, 8793, 'tt1621039', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2172931578.jpg', 3.8, 17, 54.1, 19.4, 5.7, '0.243848,0.174927,-0.557030,0.334572,-0.172787,-0.205568,0.854211,0.031400,-0.270917,-0.198235,0.207681,0.799410,-0.181575,0.465620,0.452575,0.157223,-0.055762,-0.490663,-0.057218,-0.063601,-0.204516,-0.157739,-0.270554,-0.307974,0.094676,-0.096305,0.664589,-0.022111,-0.029952,0.484202,0.394209,0.236691,0.019179,0.215165,-0.602278,0.181999,0.102117,0.111232,-0.294557,0.084539,-0.186217,-0.056738,0.076830,0.267417,-0.248964,-0.101987,0.661797,-0.404424,-0.454789,-0.344422,0.295233,-0.442788,-0.175101,0.331981,0.579211,0.057800,0.041473,0.197005,0.074647,0.265951,-0.025132,-0.024561,-0.816035,0.022312,-0.268119,0.312115,-0.445790,0.118016,0.036523,-0.000275,0.000951,-0.480965,0.122239,0.303162,0.284539,0.574252,-0.021508,0.260704,-0.594394,0.077728,1.016572,-0.310655,-0.461756,0.304858,-0.055037,-0.256752,0.044254,-0.366429,-0.462539,-0.096190,0.206463,-0.085736,-0.310073,0.500803,-0.666787,0.080396,-0.266041,-0.409777,0.067960,-0.258626,-0.207289,-0.418241,-0.046080,-0.476934,-0.314712,0.241995,0.117859,-0.459770,0.688097,-0.836564,0.536542,0.590427,0.193019,-0.470707,0.627947,0.315021,0.084405,-0.199952,0.169407,0.455774,0.281309,0.073192,0.019036,0.157315,0.082284,0.021838,-0.484353,0.568438', '25721544', '25828589', '3055049', '26857170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5154799', '木星上行', '动作', '故事发生在遥远的未来，相貌平平的女孩朱庇特·琼斯（米拉·库尼斯 Mila Kunis 饰）自幼丧父，如今她以厕所清洁工的身份在茫茫人海中奋力求生。谁知毫无征兆的一天，朱庇特的命运彻底改变，来自外太空的“半兽人”赏金猎人凯恩（查宁·塔图姆 Channing Tatum 饰）将其劫持，而这一切都与朱庇特与生俱来的神秘基因有关。话说在浩瀚宇宙的最深处，存在着一个屹立数千亿年的埃布拉赛克斯王朝，在前代女王去世后，顺位第一继承人的巴勒姆（埃迪·雷德梅尼 Eddie Redmayne 饰）践祚，野心勃勃地开始了他的邪恶计划。但是朱庇特拥有和前代女王最为接近的血缘，从而对巴勒姆的王位构成了威胁。原本肩负杀掉女孩重任的凯恩，在和朱庇特奔走在炮火砍杀的过程中，内心渐渐发生了变化……©豆瓣', '查宁·塔图姆', '莉莉·沃卓斯基', 5.5, 81891, 'tt1617661', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2230222544.jpg', 8.8, 30.2, 44.7, 12.1, 4.2, '0.201761,0.317599,-0.931668,0.661926,0.043616,-0.069406,0.912933,0.171935,-0.544044,-0.372002,0.163720,0.822323,-0.153443,-0.093587,0.487185,0.029001,-0.250256,-0.645018,-0.140069,-0.199339,-0.265560,-0.676965,-0.328221,-0.183819,-0.006218,-0.772912,0.714334,-0.038805,-0.114590,0.136080,0.098753,0.512106,-0.118021,0.338292,-0.247704,0.018865,0.182668,-0.096943,-0.159331,0.234073,-0.023424,-0.163154,-0.148536,0.211658,-0.293404,0.254346,0.464197,-0.717082,0.236864,-0.100293,0.269888,-0.153974,-0.068306,0.104785,0.482197,-0.177606,-0.175337,0.415040,0.098776,-0.196787,0.291897,-0.216912,-0.748700,-0.169307,-0.108349,0.531860,-0.609702,0.480585,-0.117681,0.047661,0.239883,-0.343216,0.200028,0.262854,0.152526,0.391320,-0.161674,0.088664,-0.655329,-0.087198,0.354718,-0.000628,-0.537730,0.112181,-0.178597,-0.459188,-0.309110,-0.196080,-0.655538,-0.258992,0.469508,0.306915,-0.027710,0.763963,-0.607667,0.007051,-0.388183,-0.276736,-0.037985,-0.490184,-0.216623,-0.312306,-0.350836,-0.496802,-0.071725,-0.134048,0.122942,-0.187304,0.665782,-0.716104,0.481502,0.582168,0.168118,-0.263326,0.478797,0.143905,0.302045,-0.227572,-0.137980,0.608482,0.168528,0.255337,-0.063649,0.205219,0.052896,0.161076,-0.206803,0.810779', '4126925', '1293124', '1307311', '10440076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5155038', '猎头游戏', '悬疑', '表面上，罗杰（阿卡塞尔·亨涅 Aksel Hennie 饰）是一名成功的猎头，但他还有着另一个职业——艺术品大盗。罗杰和娇妻戴安娜（西诺薇·玛考迪·伦德 Synnøve Macody Lund 饰）住在一幢价值不菲的别墅中，戴安娜的画廊为罗杰的第二职业提供了得天独厚的信息网。一天，罗杰通过戴安娜认识了一名叫做柯勒斯（尼可拉·科斯特-瓦尔道 Nikolaj Coster-Waldau 饰）的男子，他得知柯勒斯的家中藏有一张鲁本斯的画作，价值连城，正面临经济危机的罗杰动心了。画作轻松的得手了，可也就在同时，罗杰撞破了柯勒斯和妻子的私情大受打击，这还不是最糟糕的，本以为在现场没有留下丝毫线索的罗杰发现，危险正在渐渐逼近他和他的搭档，有一个人，正处心积虑的想要置他们于死地，一场惊天大逃亡展开了。而究竟是谁泄露了秘密？一时间，包括妻子在内，身边的每一个人都显得可疑起来。', '阿卡塞尔·亨涅', '莫滕·泰杜姆', 7.7, 54555, 'tt1614989', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2212750982.jpg', 0.4, 2.2, 28.5, 51.6, 17.2, '0.332432,-0.015496,-0.763578,0.711850,-0.074847,-0.248721,0.931947,-0.008686,-0.401086,-0.320110,0.210728,0.725942,-0.094991,0.153279,0.270188,0.205576,-0.310665,-0.557435,-0.214789,-0.298458,-0.415276,-0.726841,-0.552211,-0.293989,-0.096284,-0.232744,0.425420,0.060766,-0.137600,0.289830,0.513884,0.292044,-0.001927,0.464992,-0.159528,-0.030895,0.209747,-0.158381,-0.127390,0.142493,0.031637,-0.169072,-0.241243,0.347710,-0.112936,0.426515,0.431722,-0.295623,-0.060969,0.133062,0.333453,-0.192413,0.254132,0.031584,0.179369,-0.285525,0.172942,0.008956,-0.202023,0.105387,0.558643,0.005829,-0.860687,-0.097595,0.226119,0.246622,-0.577980,0.513641,-0.201748,-0.015620,0.090501,-0.282040,0.326701,0.493657,0.154938,0.113328,0.078928,-0.005606,-0.822338,0.001395,0.434501,0.088243,-0.208073,0.237038,-0.136466,-0.558588,-0.106348,-0.186495,-0.334646,-0.077953,0.540092,0.014357,0.103061,-0.046775,-0.436585,0.091584,-0.230050,-0.099774,-0.282418,-0.239907,-0.167880,-0.484287,-0.218185,-0.396893,-0.394909,0.134450,-0.139585,-0.475780,0.665961,-0.701434,0.290983,0.506432,0.129110,-0.315488,0.525409,0.118707,0.250839,-0.000030,-0.463623,0.088040,0.254045,0.255560,0.208081,0.374911,0.110707,-0.225890,-0.136386,0.581310', '1299932', '3119246', '1867335', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5155169', '音乐永不停歇', '剧情', '亨利（J·K·西蒙斯 J.K. Simmons 饰）和儿子贾伯利（卢·泰勒·普奇 Lou Taylor Pucci 饰）同样喜欢音乐，但是他们喜欢的音乐却是迥然不同 的两种风格。20多年年，因为对政治的不同意见导致贾伯利离家出走再也没回来过。如今，贾伯利落魄地流落街头，并发现脑部有肿瘤送去医院做了切除手术。但是这颗肿瘤已经彻底破坏了他的大脑，他失去了创作新的记忆的能力，他的记忆永远停留在活在1968年。为了重新走进贾伯利的世界，亨利邀请研究脑瘤与音乐的专家黛安（朱莉娅·奥蒙德 Julia Ormond 饰）来治疗儿子的病情。黛安发现贾伯利对早期的的摇滚乐仍然有感知。但这种迷幻时期的摇滚乐对60多岁的亨利来说简直不能接受，但为了与儿子的沟通，他开始研究起60年代的所有摇滚乐团。©豆瓣', '朱莉娅·奥蒙德', '吉姆·科尔伯格', 8.5, 10210, 'tt1613062', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p848812520.jpg', 0.3, 1, 13.5, 45.7, 39.4, '0.079421,0.098819,-0.638772,0.614045,-0.382127,-0.258198,0.631842,0.032308,-0.708402,-0.506339,-0.283691,0.757516,-0.058955,0.215928,-0.013920,-0.031959,-0.191818,-0.654186,0.103790,0.062428,-0.492273,-0.594911,-0.103719,-0.291498,-0.093742,-0.467777,0.581800,0.120677,-0.271996,0.301212,0.130307,0.227659,0.379321,0.381601,0.018034,-0.038233,-0.112764,0.139047,-0.256107,0.193603,0.453333,-0.143359,0.040348,0.215451,0.054702,0.338312,0.563523,-0.274840,-0.185125,0.006763,0.592859,0.010477,-0.157280,-0.001604,0.202605,0.153440,0.078146,0.109904,-0.244313,-0.002790,-0.162030,-0.029781,-0.701832,-0.035522,0.127388,0.128732,-0.546567,0.340666,-0.127862,-0.079287,-0.284441,-0.327203,0.385906,0.341793,0.347881,0.528685,-0.279949,0.052047,-0.390894,0.101372,0.555585,-0.012113,-0.543319,0.556098,-0.476774,-0.620007,-0.275656,-0.339922,-0.247257,0.145883,-0.039164,0.308748,-0.515703,0.109935,-0.458690,-0.033214,-0.051953,-0.398766,0.166965,-0.301828,0.142751,-0.644738,-0.276033,-0.487330,-0.349758,-0.158216,0.030948,-0.394259,0.746783,-0.933213,0.419062,0.423897,0.067374,-0.647472,0.737712,0.046597,-0.003838,-0.233117,-0.198182,0.709635,0.061640,0.192371,0.079861,0.307979,0.182445,-0.294257,-0.438819,0.460138', '1292720', '35144311', '4301278', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5155577', '流浪的尤莱克', '剧情', '根据畅销书改编，在1942年的以色列，一个八岁的男孩从华沙集中营中逃脱。他千方百计地求生，他先是在森林里躲藏，然后隐瞒身份，在波兰农场中作为一个基督教的孤儿生活。经过了百般磨难，他内心的犹太信仰将要渐渐地失去了……', '赖纳·博克', '佩波·丹科瓦特', 8.4, 9045, 'tt1608516', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2406854085.jpg', 0.1, 0.7, 12.4, 52.9, 33.9, '0.308835,0.287423,-0.964790,0.768232,-0.143605,-0.314473,0.775371,-0.351077,-0.508148,-0.027679,0.226299,0.878998,0.243115,0.571606,0.132203,-0.145712,-0.635140,-0.842442,-0.510176,-0.319805,-0.254520,-0.310367,-0.508954,-0.344266,-0.272040,-0.162485,1.045968,0.324081,-0.318109,0.017432,-0.042859,0.504732,0.059772,0.240468,-0.432871,0.149511,0.228331,-0.011952,-0.186881,0.371676,-0.051260,-0.840164,-0.348341,0.205694,-0.066453,0.557046,1.039405,-0.638500,0.267822,-0.190944,0.383060,-0.130484,-0.320830,0.090894,0.293501,0.070250,0.023326,0.467249,-0.325547,0.332306,-0.130521,-0.141724,-0.558558,-0.600875,0.243560,0.238090,-0.944368,0.439519,0.151310,-0.066007,0.209422,-0.399625,-0.007941,0.286319,0.011062,0.623350,-0.354442,0.082417,-0.388151,0.295434,0.554392,-0.231460,-0.454522,0.204207,-0.459653,-0.607590,0.192584,-0.066731,-0.512084,-0.590885,0.554216,0.059772,-0.633746,0.672410,-0.813199,0.023734,-0.442855,-0.526799,-0.038152,-0.376701,-0.215130,-0.399068,-0.527592,-0.364572,-0.154051,-0.118350,-0.218487,-0.151676,0.882026,-0.827344,0.385224,0.794142,0.248342,-0.269923,0.401800,0.084630,0.150267,-0.106972,0.273969,0.815578,-0.164679,0.558836,-0.088451,0.288636,-0.081045,0.091093,-0.383518,0.653371', '21619567', '1467779', '3011058', '1438591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5156137', '唯神能恕', '剧情', '朱利安（瑞恩·高斯林 Ryan Gosling 饰）十年前因为一起谋杀从美国逃亡泰国避难，和哥哥比利（汤姆·伯克 Tom Burke 饰）在曼谷开了一家拳击俱乐部做幌子进行地下毒品交易。比利因为强奸并谋杀一位年仅十六岁的泰国少女遭到泰国警方的注意。少女的父亲在警察头子Chang（维他亚·潘斯林加姆 Vithaya Pansringarm 饰）的挑唆下杀了比利。朱利安和比利的生母克里斯朵（克里斯汀·斯科特·托马斯 Kristin Scott Thomas 饰）前往曼谷为长子收尸。复仇心切的克里斯朵见到软弱无能的次子朱利安不禁怒火中烧，雇了杀手想除掉一系列与比利死亡有关的人。朱利安本想就此放过Chang将此事了结，可是在母亲一步步疯狂的刺激和威逼之下不得不参与进这血腥的杀戮。本片是导演尼古拉斯·温丁·雷弗恩与瑞恩·高斯林继《亡命驾驶》后合作的第二部影片。', '瑞恩·高斯林', '尼古拉斯·温丁·雷弗恩', 5.9, 9834, 'tt1602613', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1945017578.jpg', 9.5, 23.5, 37, 21.9, 8.2, '0.217374,-0.076826,-0.553069,0.470482,0.129368,-0.396458,0.689426,0.076413,-0.363187,-0.304894,0.260656,0.752429,-0.157604,0.055256,0.513467,0.158190,-0.522385,-0.469964,-0.157919,-0.022083,-0.077087,-0.696878,-0.126510,-0.194765,-0.037720,-0.158730,0.451457,-0.072939,-0.162632,0.554763,0.613574,0.548334,-0.097422,0.185761,0.189844,0.034955,0.191386,-0.395959,-0.515658,0.356520,0.174662,-0.303777,-0.087904,-0.147386,0.229880,0.411309,0.430313,-0.305975,0.275499,-0.412297,0.151123,-0.209732,0.018917,0.199055,0.166327,-0.109886,0.100538,0.301117,-0.171798,-0.036982,0.245148,-0.050237,-0.602171,0.428106,0.003479,-0.089673,-0.661011,0.135166,-0.312153,0.226224,0.214853,-0.116014,0.231078,0.422209,0.209901,0.010890,-0.078548,0.085134,-0.331581,0.043030,0.685222,-0.062645,0.094830,-0.066144,0.055625,-0.227690,-0.070884,-0.153448,-0.291905,-0.011124,0.382102,-0.152155,-0.154635,0.320901,-0.450722,-0.378838,-0.587199,-0.099811,0.067707,-0.100110,0.001299,-0.794960,-0.050986,-0.105763,-0.191849,-0.116833,0.131737,-0.238297,0.190575,-0.536710,0.287139,0.645551,0.443105,-0.352318,0.405650,0.030814,0.070897,-0.120726,-0.205528,0.362276,0.393567,0.186152,0.136846,0.253297,0.188059,-0.236814,0.029057,0.200178', '1295225', '3326