INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5156574', '再过四年', '剧情', '瑞典政党领袖大卫·霍尔斯特（伯恩·谢尔曼 Björn Kjellman 饰）风流倜傥、幽默成熟，是下一届总理候选人的有力竞争者。英俊风趣的大卫被普遍看好，大家都认为大卫可以轻而易举的赢得这次选举的胜利。然而众望所归的胜利却遭遇了滑铁卢，对手政党获得选举胜利，并将在未来的四年中领导国家。就在大卫心灰意冷的时候，不期而遇的爱情却意外的降临到了大卫身上。然而这却是一场最不该发生的感情，已婚的大卫居然爱上了一个男人，还是一个来自对手政党的男人马丁（埃里克·埃里克森 Eric Ericson 饰）！面对着这份无法抗拒的感情，大卫辗转反侧苦苦挣扎。他开始挑战周遭的一切，他的家庭他的爱人，以及他不愿舍弃的政治生涯。©豆瓣', '伯恩·谢尔曼', '托娃·马格努松', 8.2, 8060, 'tt1598496', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1131212942.jpg', 0.3, 1.5, 19.1, 47.4, 31.7, '0.270715,0.123371,-0.719171,0.647564,-0.504457,-0.342466,0.678860,0.153890,-0.507497,-0.068136,0.368487,0.982963,-0.234649,-0.043208,0.243527,-0.107746,-0.074134,-0.863288,-0.075247,0.117676,0.004266,-0.564327,-0.327727,-0.193742,-0.042719,-0.128511,1.003067,0.250363,-0.318634,0.403194,0.534106,0.260889,0.424033,0.669254,-0.072722,-0.088285,0.269361,0.017930,-0.390991,0.193783,0.081269,-0.168065,-0.178780,0.675347,-0.194483,0.252708,0.333672,-0.363870,-0.097269,-0.079191,0.469712,-0.248149,0.029529,0.320260,0.279709,0.065230,0.073614,0.514975,0.147225,-0.101524,0.152247,0.022987,-0.969174,0.072885,-0.025940,0.311449,-0.445742,0.756923,-0.196185,0.151780,-0.062495,-0.188146,0.046824,0.330123,0.345597,0.172508,-0.351093,0.063839,-0.410604,0.150623,0.746655,0.053691,-0.621827,0.155083,-0.441841,-0.503501,0.085877,-0.501909,-0.685999,0.055942,0.366880,0.060938,0.055332,0.403435,-0.420778,0.196845,-0.251056,-0.196534,-0.097884,-0.617515,0.153104,-0.303159,-0.373104,-0.337135,-0.353430,0.005279,0.050062,-0.345212,0.804769,-0.798886,0.026289,0.674233,0.225982,-0.142839,0.586941,0.460371,0.093124,-0.315953,-0.316232,0.604404,-0.262918,-0.018437,-0.182030,0.319116,0.053561,-0.147100,-0.160449,0.697114', '1303034', '30163500', '1291577', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5157137', '勇者行动', '剧情', '洛克，即将成为人父，正准备与大家分享这份喜悦。却突然接到上级命令，带领自己的小队去营救被绑架的CIA人质。虽然与家人才团聚没有多久，但是时刻为祖国效命是海豹突击队员的职责。洛克所率领的小队很快集结，按照计划前往目的地营救人质。不过，在营救过程中，洛克却发现了恐怖分子布下的天罗地网，一场惊天阴谋正在酝酿实施中。如果不能加以阻止，美国本土很可能会遭受严重的恐怖袭击。因此，海豹突击小队，一刻都没有停息，在全球展开了一场大围剿……本片被认为是真人版的《战地3》，片方在全球多个地方取景，根据真实的事件改编。©豆瓣', '罗塞莉·桑切斯', '迈克·麦科伊', 7.7, 39785, 'tt1591479', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1557294204.jpg', 0.5, 3, 28.8, 45.9, 21.8, '0.073420,-0.119577,-0.991936,0.489938,0.009483,0.138678,0.355932,-0.135185,-0.515357,-0.238432,0.317990,0.554485,0.029086,-0.266351,0.290806,-0.214221,-0.459944,-0.780787,-0.327300,-0.120973,-0.213480,-0.395649,-0.335331,-0.313299,0.186884,-0.382669,0.836581,0.331898,-0.299144,0.494004,0.276284,0.430295,-0.381098,0.748480,0.129893,-0.166149,0.417503,-0.279685,-0.490244,0.386270,-0.045832,-0.358346,-0.280874,0.381023,-0.003883,0.587606,0.578722,-0.563661,-0.212462,-0.093537,0.052014,-0.626694,0.126328,-0.044416,0.600781,0.063461,0.103361,0.334214,-0.122773,0.221017,-0.195862,-0.248959,-1.039740,-0.124485,0.264595,0.057864,-0.643261,0.106902,-0.241143,0.034192,0.347886,-0.170714,0.321325,0.763161,0.618448,0.199620,-0.206781,0.008350,-0.525638,0.056295,1.083183,-0.216555,-0.122483,-0.039809,0.183288,-0.383991,0.112019,-0.175274,-0.239515,0.070285,0.188565,0.247925,-0.062786,0.156899,-0.338206,0.052027,-0.762071,-0.545591,-0.044806,-0.599015,0.059945,-1.021367,0.040511,0.159360,-0.066619,0.265234,0.071380,-0.071936,0.692085,-1.000796,0.323545,0.528704,0.268950,-0.582592,0.276193,0.301245,0.099741,-0.271628,0.174714,-0.127981,0.136472,0.415682,0.248457,-0.027878,-0.017835,-0.259039,-0.171004,0.274241', '2369613', '1870682', '1296947', '4767216');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5157400', '睡美人', '剧情', '影片剧本由自澳大利亚小说家茱莉亚·丽（Julia Leigh）创作，同时这也是她的导演处女作。这部作品入围了第64届戛纳电影节的主竞赛单元，但最终未能如愿以偿的获得些许殊荣。影片讲述了一个发生在现代女大学生身上的童话故事。露西（艾米莉·布朗宁 Emily Browning 饰）白天是一个单纯的女大学生，而到了晚上她则有另外一个身份——“睡美人”。这份特殊的工作让她在一个陌生的房间内沉沉睡去，醒来后则完全记不得任何事情，仿佛一切都未发生。在梦中她身处一个充满奇幻色彩的隐秘世界，那里美丽，同时充满着欲望。露西深陷迷惘之中，对每一晚发生的离奇经历逐渐产生疑问，她急切想知道，在她沉睡的时候到底发生过什么，她将如何找回自己……©豆瓣', '艾米莉·布朗宁', '茱莉亚·李', 5.7, 17501, 'tt1588398', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1415099460.jpg', 6.3, 26.1, 48.9, 14.1, 4.6, '0.149609,0.307683,-0.918492,0.622678,0.003339,0.047312,1.013303,-0.147520,-0.520633,-0.520161,0.241112,0.765285,-0.371162,0.428607,0.203083,-0.052532,-0.423531,-0.663907,-0.038835,-0.237528,-0.289875,-0.326897,-0.276892,0.222378,0.005991,-0.194549,0.742015,0.104246,-0.035812,0.133031,0.379388,0.172128,-0.206776,0.629293,0.059339,0.198039,0.151040,0.258717,-0.073320,0.249315,0.309963,-0.259531,-0.432762,0.184144,-0.040371,0.188804,0.696188,-0.272188,-0.411271,0.116499,0.673291,-0.052155,-0.168471,0.190137,-0.005699,0.162704,0.014340,0.028261,-0.060209,0.015310,0.082863,0.123194,-0.831539,-0.043552,0.119578,0.535630,-0.306997,0.336181,-0.035716,-0.072661,0.105306,-0.250502,0.262804,0.232071,0.426912,0.230659,-0.033352,0.023943,-0.551785,0.384740,0.665937,0.243280,-0.492475,0.710449,-0.381054,-0.423709,-0.116569,-0.120618,-0.513180,0.326564,0.220474,0.220180,-0.364428,0.188380,-0.338221,-0.039122,0.047035,-0.476560,-0.291967,-0.416103,-0.122859,-0.422923,-0.232600,-0.261171,-0.248718,-0.235909,0.022953,-0.377218,0.754748,-0.916744,0.338566,0.576456,0.150353,-0.225273,0.662598,0.078637,0.051944,-0.007760,-0.008370,0.343924,-0.218546,0.122917,-0.098681,0.508169,-0.059600,0.099967,-0.662145,0.600135', '4275444', '1304862', '1309080', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5158655', '狙击精英：重装上阵', '动作', '传奇狙击手托马斯·贝克特之子、美国海军陆战队布兰登·贝克特中士受命与战友们从阿富汗前往非洲刚果，对那里的政府军进行培训以使其能够反击叛军。上峰为了撤出滞留刚果边境的白人植物园主，派遣贝克特等人深入叛军盘踞的边境，贝克特一行在见到植物园主后遭遇叛军狙击手袭击，战友全部阵亡，贝克特被猎人马丁救出，侥幸逃生。贝克特携植物园主女儿凯莉返回营地，岂料半路昏厥……当他醒来时，父亲的好友米勒（比利·赞恩 Billy Zane 饰）要对他进行狙击训练，使他拥有复仇的能力，然而陆战队出身的贝克特不齿狙击手的“猥琐”，拒绝训练，但这是他唯一的复仇机会，况且他身上流淌着狙击手的血液……©豆瓣', '查德·科林斯', '克劳迪奥·法', 5.7, 4867, 'tt1571243', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2182019221.jpg', 5.4, 25.2, 53.5, 12.4, 3.5, '0.054002,-0.262173,-0.602867,0.560589,-0.028681,-0.123073,0.527695,-0.159833,-0.594666,-0.213054,0.480171,0.657181,0.253599,-0.193381,0.230354,0.045068,-0.358253,-0.581755,-0.179699,-0.060341,-0.222381,-0.441478,-0.442728,-0.345984,0.061710,-0.388270,0.718427,0.052679,-0.233744,0.447605,-0.015735,0.519093,-0.111475,0.361229,-0.183068,-0.087401,0.345362,-0.607977,-0.316951,0.391614,-0.123278,-0.139092,-0.078712,-0.000149,0.077367,0.508801,0.738735,-0.100964,0.269286,-0.383179,-0.177355,-0.489262,0.301202,0.238055,0.346738,0.005021,-0.089935,0.065626,0.339794,-0.038139,-0.231511,0.016456,-0.548819,0.001023,-0.186965,0.031701,-0.612725,0.239370,-0.339826,0.392418,0.099710,-0.137154,0.160265,0.431868,-0.080788,-0.078546,-0.105965,0.020942,-0.458223,0.024417,0.644856,-0.469320,-0.102748,-0.216241,-0.079832,-0.447553,0.405926,-0.249550,-0.319660,-0.091721,0.367934,-0.049777,-0.051030,-0.002147,-0.465802,-0.024256,-0.540712,-0.220678,-0.186182,-0.021251,-0.000417,-0.856720,0.053105,-0.012022,-0.284655,0.176718,-0.037883,0.204430,0.606988,-0.589399,0.171414,0.604466,0.526256,-0.535967,0.513956,0.215196,0.129738,-0.175785,0.114837,0.603658,0.264601,0.340654,0.119645,0.151190,-0.234454,-0.260862,-0.306236,0.070098', '2369613', '1899892', '1307897', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5159370', '人生不再重来', '剧情', '卡比尔（阿布依•多尔 Abhay Deol 饰），阿琼（赫里尼克•罗斯汉 Hrithik Roshan 饰），依姆兰（法拉汗•阿克塔尔 Farhan Akhtar 饰）是大学时期被誉为三个火枪手的好兄弟，大学毕业前约定要进行一次西班牙的公路旅行。因为各种原因与借口，这个计划拖延到了四年后卡比尔与娜塔莎（卡尔吉•柯伊切林 Kalki Koechlin 饰）结婚前夕，以卡比尔单身旅行为理由终于如愿以偿的实行。三个男人来到西班牙，挑战各自内心最惧怕的事物。怕水的阿琼学会了潜水，寻觅到了自己终身的爱人，潜水教练莱拉（卡特莉娜•卡芙 Katrina Kaif 饰）。在莱拉的影响下改变了以往金钱重于一切的观念，明白了自由和快乐的真谛。依姆兰挑战了自己恐高的极限去参加跳机训练，还如愿见到了自己的亲生父亲，并且鼓起勇气发表了自己的诗歌。而最后三人一起参加了奔牛节，在死亡的边缘挑战着内心的恐惧，而卡比尔也敢于面对自己对于结婚的犹豫。最终这次旅行让他们变得强大的去面对各自生活中事业，梦想，婚姻的抉择。', '赫里尼克·罗斯汉', '卓娅·阿赫塔尔', 8.1, 11310, 'tt1562872', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2178705675.jpg', 0.7, 2.5, 20.2, 44, 32.6, '0.090805,0.039276,-0.675853,0.688067,-0.001673,-0.598152,0.462740,0.096171,-0.338330,-0.242304,0.098171,0.629049,0.016009,0.181063,0.532742,-0.042270,-0.357921,-0.743703,0.210655,-0.121135,-0.336739,-0.569245,-0.072513,-0.071675,-0.286137,-0.298606,0.625642,0.008811,-0.109377,0.475635,0.310985,0.123447,0.258850,0.381144,0.071275,-0.197045,0.178758,0.092675,-0.473149,0.248437,0.154538,0.093325,-0.202521,0.321712,0.134175,0.262771,0.584189,-0.215944,0.144173,-0.096716,0.220054,-0.290471,-0.020834,0.314441,0.108294,-0.122930,0.133301,0.217567,0.000954,0.068204,0.046605,0.000546,-0.610508,-0.080126,0.041563,-0.027206,-0.823737,0.445132,-0.179652,-0.200067,0.211246,-0.395308,0.014116,0.580038,0.293119,0.320933,-0.321300,-0.121236,-0.298101,0.120886,0.794800,-0.151459,-0.232914,0.107766,-0.169980,-0.454375,0.080679,-0.220025,-0.348539,-0.040191,0.117991,0.286286,-0.253276,0.365260,-0.748305,-0.035756,-0.314537,-0.326377,0.027357,-0.517994,0.123268,-0.711729,-0.121511,-0.427846,-0.333094,0.034670,0.006238,-0.342149,0.542225,-0.816841,0.379560,0.583873,0.390343,-0.454999,0.546742,0.314401,0.320978,-0.327750,0.100898,0.503547,-0.248303,0.348213,-0.158832,0.243298,0.145663,0.087827,-0.395714,0.709066', '1652618', '26971054', '1986338', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5159694', '痛击', '剧情', '2009年，印度孟买闹市街头。衣着光鲜的成功人士巴赫在一间电话亭内进行一桩秘密交易。他是一名小有成就的银行家，从上到下一身名牌，妻子美艳，女儿乖巧，虽然有着令人欣羡的家境事业，但其为人傲慢，花心放荡，为了财富和荣誉不惜染黑双手。正当他准备离开电话亭时，一通陌生电话打了进来。对方知晓他一切罪恶勾当，并且正躲在附近某栋大厦内监控着他，稍有轻举妄动便会遭到狙击。不久之后，一名瘾君子死于电话亭前。神态惶恐的巴赫开始吸引路人注意，警察、媒体、政客乃至全国人民都聚焦在这个小小电话亭之上，巴赫被迫向全国人揭开自己的伪装，以及这个国家政坛背后的不为人知的惊天丑闻……©豆瓣', '桑杰·达特', '马尼·沙恩卡尔', 7.9, 7709, 'tt1558578', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p915459840.jpg', 1.1, 4.2, 21.9, 43.8, 28.9, '0.060473,0.061187,-0.569169,0.369302,-0.066473,0.068816,0.571622,0.047441,-0.688388,-0.312541,0.394979,0.699395,-0.170550,0.141117,0.263209,0.097509,-0.507687,-0.773153,-0.206909,-0.304807,-0.175923,-0.088281,-0.291471,-0.412504,-0.338504,-0.052918,0.402089,0.248079,-0.204092,0.350714,0.388057,0.169768,-0.315770,0.442822,-0.110844,-0.280791,0.133528,-0.328548,-0.284733,0.039274,-0.272846,-0.400873,-0.211421,0.167331,-0.156003,0.217464,0.470708,0.073301,-0.196682,-0.246426,0.489204,-0.009315,-0.058681,0.284336,0.373584,0.032871,0.253436,0.094271,-0.211924,0.007576,0.319261,-0.081035,-0.296489,-0.145642,-0.083521,0.277004,-0.319862,0.565403,-0.227030,0.083180,0.066428,-0.258708,0.102780,-0.140892,0.019344,0.260410,-0.118987,0.222725,-0.586914,-0.039837,0.354023,0.308665,-0.089899,-0.020829,-0.229214,-0.333795,-0.020135,-0.300871,-0.505028,-0.228719,0.282707,-0.082642,0.074351,0.285310,-0.363200,-0.030098,-0.127335,-0.112892,0.014564,-0.242980,-0.577441,-0.577634,-0.161512,-0.268031,-0.308440,0.268160,-0.060606,-0.001704,0.683912,-0.648494,0.041121,0.643171,0.298494,-0.424844,0.696396,-0.340648,0.333916,0.017864,-0.461574,0.255887,0.184402,0.503457,-0.188065,0.275475,-0.538247,-0.271358,-0.027680,0.325124', '1306860', '30162520', '1307146', '1303449');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5162334', '她的回忆', '科幻', '21世纪末，浩瀚无际的宇宙空间内，太空垃圾回收船日冕号正夜以继日地工作。船员伊万诺夫、大岛、海因茨等人既感烦躁，又觉无聊，只能通过插科打诨派遣抑郁的心情。就在此时，日冕号突然收到一段奇怪的求救信号。信号源自某个太空墓场，其间夹杂着女声所吟唱的普契尼著名歌剧《蝴蝶夫人》的段落。经过漫长跋涉，日冕号终于抵达太空墓场，海因茨和米格尔下船勘查，谁知却在这个与世隔绝的所在发现种种异状。在此之前，拥有传奇华美人生的歌剧演员艾娃似乎盘桓于此，如梦如幻的世界，海因茨和米格尔渐渐迷失在艾娃以及彼此的记忆中，他们深陷幻象无法自拔……本片为《回忆三部曲》中的一部。©豆瓣', '矶部勉', '森本晃司', 8.8, 23130, 'tt1530535', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2570341969.jpg', 0.2, 0.6, 8.7, 38.4, 52.1, '0.013595,-0.005437,-0.919264,0.585308,0.456839,-0.242629,0.852784,-0.115550,-0.575777,-0.346106,0.132542,0.582020,-0.332529,0.381236,0.453344,-0.021169,-0.789448,-0.495470,-0.188625,-0.204149,-0.158415,-0.434811,-0.282140,0.001622,0.078407,-0.367453,0.776533,0.470646,-0.241611,0.335063,-0.200764,0.393821,-0.531309,0.609746,-0.227404,0.008474,0.173944,0.075201,-0.162179,-0.171796,-0.254427,-0.132404,-0.161457,-0.207701,-0.067876,0.149667,0.838966,-0.323084,0.013529,0.250685,0.302716,-0.129231,-0.212736,-0.310064,0.092868,0.139029,-0.023759,-0.126280,-0.302404,0.128900,-0.379554,-0.065285,-0.553004,-0.056610,-0.218269,0.211250,0.085849,0.042018,-0.039040,-0.102039,0.095328,-0.162244,0.259322,0.049485,0.308809,0.617679,-0.150234,0.119363,-0.089529,0.167716,0.379204,0.160434,-0.503091,0.512089,0.024044,-0.510778,-0.228088,0.017655,-0.231759,-0.184298,0.359812,0.284576,0.016820,0.358207,-0.706561,0.338106,-0.189915,-0.515482,-0.198948,-0.291447,-0.457693,-0.916178,-0.075717,0.058398,-0.062013,0.144747,0.106156,0.079042,0.420184,-0.407091,0.618290,0.496316,-0.220925,0.102391,0.547773,0.044200,0.041786,-0.326514,0.128020,0.482417,-0.048089,0.459867,-0.110554,0.256619,-0.288487,0.033106,-0.810722,0.188715', '1316693', '10466639', '2159244', '4706257');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5183361', '在人海中遇见你', '剧情', '他是一个只愿宅在家里的网站设计师，她是一个做着橱窗设计的建筑师。在这个信息科技高速发达的年代，无论是他还是她都在经受不同程度的精神压抑。他们住在同一个城市同一条街道，但是却像两条平行的直线从未有过交点。他们分别和各自的伴侣约会、分手，各自在寻找着那个正确的人。她是玛丽安娜（碧拉尔·洛佩兹·德·阿亚拉 Pilar López de Ayala 饰），他是马丁（哈维尔·多罗拉斯 Javier Drolas 饰），他们是布宜诺斯艾利斯里两个普通人。可是因为内心的执着，让玛丽安娜从未放弃由一本儿时图画书引发的追寻。也所幸那些“不正确的人”的离开，终于让冥冥注定的相遇终于实现。©豆瓣', '哈维尔·多罗拉斯', '加斯塔夫·塔雷托', 7.8, 7878, 'tt1235841', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1305344626.jpg', 0.4, 2.6, 27.9, 45.9, 23.2, '0.547706,0.021134,-0.858078,0.855238,-0.119250,-0.269849,1.030787,-0.014337,-0.449790,-0.112764,0.418363,0.964270,0.002110,0.267865,0.061992,0.347051,-0.249620,-0.623386,0.360306,-0.203849,-0.287614,-0.715657,-0.411256,-0.239133,-0.096142,-0.122726,0.748878,-0.053108,-0.055611,0.345363,0.413336,0.114046,-0.104729,0.573680,-0.441858,-0.036256,0.133903,-0.139525,-0.087917,0.053806,0.008135,-0.105025,-0.210953,0.319833,0.010093,0.438355,0.590381,-0.396558,-0.091019,0.244955,0.302665,-0.281796,-0.036416,0.067427,0.102131,-0.261517,0.105052,0.233779,-0.219564,0.172789,0.157969,0.130259,-0.869922,-0.045327,0.268358,0.426842,-0.737171,0.593994,-0.195629,-0.351504,0.023381,-0.442107,0.144980,0.349295,0.173862,0.408946,-0.167216,-0.194229,-0.697070,-0.024701,0.817528,0.170304,-0.418929,0.298608,-0.525324,-0.369634,-0.345184,-0.066634,-0.795473,-0.147534,0.200347,0.058013,-0.369443,0.142020,-0.814007,0.296551,-0.018625,-0.225676,-0.009129,-0.561225,0.107013,-0.697486,-0.081783,-0.692393,-0.503179,-0.046777,-0.121006,-0.343900,0.821148,-0.918050,0.003747,0.683860,0.319316,-0.504435,0.961760,0.078090,0.074497,-0.216903,0.049262,0.309682,-0.115183,0.339334,0.030948,0.711589,0.373663,0.213888,-0.589826,0.956952', '3055049', '35158375', '24756472', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5194471', '画壁', '剧情', '深山古刹，进京赶考的书生朱孝廉（邓超 饰）被一个从壁画上跌落下来的仙女牡丹（郑爽 饰）带到了画中的仙境。在奇异的仙境之中，众多仙女在姑姑（闫妮 饰）的管理下，过着自由快乐的生活，但惟独不许她们与男人产生感情，而且对私自闯进仙境的男人也绝不手软。在仙境里，朱孝廉认识了仙女芍药（孙俪 饰）。在芍药的帮助下，朱孝廉躲过被姑姑发现的危险，顺利的返回人间。但是，由于担心牡丹的安危，在朱孝廉的请求下，古庙里的大师（曾志伟 饰）帮助朱孝廉重返仙境。然而仙境之中依旧歌舞升平，但朱孝廉却怎么也找不到仙女牡丹的身影……本片取材自《聊斋志异》，由陈嘉上导演执导。邓超、孙俪夫妻首次大银幕合作。©豆瓣', '邓超', '陈嘉上', 4.8, 131580, 'tt2062596', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1194538124.jpg', 20.9, 34.4, 32.9, 7.8, 3.9, '0.116279,0.194280,-0.735412,0.969231,-0.250579,-0.120147,0.720535,0.254242,-0.523504,-0.267265,0.172661,0.607459,-0.419532,0.369212,0.068630,0.087087,-0.043465,-0.373610,-0.244025,-0.336593,-0.159901,-0.222264,-0.291460,0.123443,-0.353269,0.000498,0.443339,0.352405,-0.059418,0.459308,0.144068,-0.211324,-0.423596,0.463152,-0.070065,0.203178,0.021495,0.358174,-0.240995,0.428752,0.056222,-0.376159,0.004825,0.035443,0.125648,0.078017,0.629687,-0.523140,-0.076124,0.110768,0.464647,0.103824,0.201891,0.289921,0.279294,-0.096120,0.097154,-0.136587,-0.200220,0.299019,0.230511,-0.391303,-0.299818,0.290171,0.479180,0.258916,-0.567342,0.282833,0.119308,-0.052017,-0.123084,-0.287060,0.407656,0.169953,0.458783,0.368130,-0.245810,0.141429,-0.799372,0.514210,0.495751,0.314075,-0.074258,0.152335,-0.095076,-0.555954,-0.049233,-0.075371,-0.367165,0.028897,0.354811,-0.199097,0.041080,-0.085826,-0.478396,-0.050564,-0.056345,0.285973,-0.440989,-0.291532,-0.035401,-0.439935,0.085775,-0.491266,-0.291715,0.218297,0.223152,-0.357070,0.540625,-0.699121,0.446029,0.173984,0.227093,-0.277015,0.927031,-0.175221,0.089084,-0.020970,-0.108257,0.413294,0.331461,0.517074,0.067074,0.470163,-0.453697,-0.206607,-0.251872,0.008083', '3055049', '1414808', '4842877', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5244092', '翻滚吧！阿信', '剧情', '宜兰青年林育信（彭于晏 饰）曾经在体操队度过了快乐的少年时代，那时活泼好动的小阿信拥有出色的天分而颇得教练器重，但年岁渐长，阿信先天的长短脚令他的体操水平难以提高，又拗不过开水果铺的母亲要求，只得终止训练卖水果，并与好友菜脯（柯宇纶 饰）日日在街头和各路人马拼斗，并因此结缘为他传递打杀通知的电话秘书559（林辰唏 饰）。为了替昔日体操队友的摊档出头，阿信和菜脯开罪黑道大哥之子木瓜（陈汉典 饰），并连番让木瓜出丑，木瓜诱使菜脯吸毒，为阿信设下陷阱，结果反被菜脯重伤。阿信和菜脯只得远赴台北躲祸，少年时的体操梦，此时已变得模糊不清……©豆瓣', '彭于晏', '林育贤', 7.4, 92899, 'tt2011076', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1142370502.jpg', 0.5, 4.4, 37.2, 42.1, 15.7, '-0.090895,-0.074662,-0.219710,0.579103,-0.165525,-0.299400,0.310101,0.609539,-0.454378,-0.221714,0.019847,0.605397,-0.043437,0.004881,0.162553,-0.292432,0.026733,-0.495295,-0.045979,0.078712,-0.074189,-0.372980,-0.074275,-0.076464,-0.124694,-0.214765,0.415963,-0.113931,-0.259168,0.543746,0.261881,-0.099715,-0.049350,0.157249,-0.074656,0.047003,-0.222308,0.146694,-0.258354,-0.006447,0.063646,-0.309451,-0.133266,-0.073577,0.185823,0.312423,0.455442,-0.051963,-0.245875,-0.184975,0.232179,-0.044308,0.022284,-0.047761,0.257320,0.092881,0.388834,0.009019,-0.065373,0.207524,0.030857,-0.137051,-0.546923,0.242114,0.354038,-0.310194,-0.414983,0.437450,-0.092485,0.017354,0.052956,-0.266779,0.028570,0.204430,0.082787,0.503278,-0.155904,0.035640,-0.331374,0.248179,0.483973,0.150722,0.256029,0.200212,-0.249649,-0.421390,0.024860,-0.401199,-0.147368,0.180758,0.077479,0.143914,-0.066619,0.048522,-0.298999,-0.037570,-0.161454,0.171195,0.035756,-0.229880,-0.226959,-0.402410,0.225957,-0.344281,-0.110198,-0.037058,0.201718,-0.096003,0.555412,-0.648828,0.121741,0.368792,0.091012,-0.247191,0.417421,0.060281,-0.038374,-0.203293,-0.285462,0.081063,-0.021072,0.090434,0.181099,0.100648,-0.166081,-0.233575,-0.484955,0.098037', '35144311', '3811356', '35030151', '26809007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5247058', '星守之犬', '剧情', '位于北海道的某个小城市，在市政府工作的奥津（玉山铁二 饰）正和同事前往密林深处，不久前此处发现一辆废弃的汽车，车内则有一具中年男子和一条狗的骸骨。汽车内外除了几张沿途消费小票外，没有任何能够证明该男子身份的证件。经对骸骨的检验得知，男人死后长达半年时间狗狗才随之死去。童 年有着养狗经历的奥津对男人的经历倍感好奇，他自费前往死者旅程的起点——东京调查，并在路上搭载了偷偷跑到东京选秀的同乡少女有希（川岛海荷 饰）。二人以购物小票为线索，一路追寻着中年男子“前田”（西田敏行 饰）及其爱犬Happy的足迹。经过探访，他们渐渐拼凑出“前田”先生那平凡寂寥的人生……本片根据村上たかし的同名漫画改编。©豆瓣', '西田敏行', '泷本智行', 8.3, 7676, 'tt1714850', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1012930740.jpg', 0.4, 1.7, 16.2, 43.9, 37.8, '-0.002407,-0.242149,-0.471429,0.502529,0.284992,-0.342143,0.683317,-0.053229,-0.618940,-0.436319,0.266887,0.480293,0.015947,0.307464,0.378393,-0.217573,-0.405778,-0.331110,-0.211229,-0.396023,-0.483457,-0.197331,-0.185986,-0.229672,-0.090974,-0.086754,0.584634,0.283146,0.023951,0.503337,0.138155,0.019015,-0.575445,0.113430,-0.196959,-0.016216,0.112812,0.260016,-0.235676,0.049340,-0.154213,-0.283472,-0.087360,-0.324218,0.087385,0.375875,0.913387,-0.038499,-0.342911,-0.076886,0.269316,0.232473,0.108771,-0.145024,0.320097,0.161921,0.227585,0.151828,-0.245495,-0.101060,-0.011641,-0.092639,-0.295130,-0.109920,-0.126482,0.298507,-0.295181,0.363907,-0.109317,-0.082877,0.232471,-0.535052,0.229900,0.170343,0.117093,0.064850,-0.025111,-0.027812,-0.361664,0.287474,0.332496,0.174528,0.062889,0.297730,-0.329258,-0.528010,-0.040142,0.093193,-0.273586,0.082468,0.099209,0.088273,-0.161054,-0.123247,-0.632673,-0.035505,-0.201785,-0.301208,0.144362,0.091869,-0.310049,-0.849329,0.041124,-0.306817,0.100800,0.118184,0.065403,-0.136408,0.450959,-0.568555,0.157954,0.372847,0.258837,-0.326663,0.672030,-0.337272,0.095724,-0.257808,0.000416,0.274472,0.235781,0.628420,-0.093935,0.155365,-0.290193,-0.277282,-0.570684,0.267254', '10466639', '2159244', '1309194', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5250341', '功夫·咏春', '动作', '咏春拳祖师严咏春（白静 饰）与曾经是少林俗家弟子的父亲因受人诬告，举家由广东迁入四川大别山一带，靠经营豆腐饭店为生。严咏春生性活泼好斗，时常用父亲传授的武功于街市打闹，偏偏这一日，父亲世交梁家的公子梁博俦（余少群 饰）奉长辈之命，不远千里入川与严咏春相亲，正好撞见咏春“行凶”，同样有功夫在身的梁博俦心下大骇，匆匆逃走。咏春自此苦学淑女做派，反而引来邻乡恶少调戏，为难关头，云游至此的少林五枚师太（惠英红 饰）收永春为徒，传授一套拳法令其大败恶少。梁博俦与父母再次拜访严家，两个年轻人以武切磋终于拉近了距离。而此时，少林叛徒金鹰（邹兆龙 饰）率领清廷鹰犬四处搜捕五枚师太等少林子弟，平和的大别山小镇，即将迎来连番激战……©豆瓣', '白静', '张同祖', 5.5, 3359, 'tt1900886', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p678843133.jpg', 7.6, 27.1, 50.7, 10.6, 3.8, '0.008557,-0.367069,-0.324923,0.598509,0.111982,-0.209371,-0.202717,0.374518,-0.609428,-0.503036,0.169602,0.578968,0.193605,0.174926,0.178989,-0.335804,0.356402,-0.455165,-0.113700,-0.075480,0.240074,-0.114114,0.224661,-0.210636,-0.111522,-0.224848,0.171593,0.309484,-0.450414,0.766625,0.416476,0.004610,-0.396051,0.049110,-0.229392,-0.054541,0.020975,0.225086,-0.387244,-0.077978,-0.235479,-0.555499,-0.174186,-0.320870,0.007943,0.520283,0.402116,0.164234,-0.109457,-0.253441,-0.059582,0.190967,-0.149978,0.000165,0.582389,0.028089,0.396661,0.108438,-0.008831,-0.074309,-0.130790,-0.211910,-0.025165,0.182750,0.553547,-0.484916,-0.428557,0.333080,-0.128855,-0.033120,-0.372619,-0.389026,-0.035193,0.294761,0.178166,-0.131375,0.239964,-0.144359,-0.125843,0.454959,0.359269,-0.197434,0.371994,-0.098290,0.147051,-0.076975,0.543971,-0.666216,-0.116569,0.039282,0.315878,-0.319910,0.215823,0.204564,-0.135069,-0.266003,-0.272000,0.496572,0.177408,0.003370,0.043214,-0.698439,0.103021,-0.300934,-0.031428,-0.147533,0.327322,0.105738,0.587957,-0.683096,0.136144,-0.213176,0.049351,-0.480726,0.451642,-0.094546,0.158155,-0.179557,-0.171136,0.027958,0.412274,0.224271,0.136488,0.285807,-0.264714,0.073678,-0.010729,-0.039886', '1307186', '26365262', '25922902', '25723081');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5250349', '冠军', '剧情', '叱咤马术界的神话级骑手承浩（车太贤 Tae-hyun Cha 饰）曾创下了连赢300场比赛的神话，光环和荣誉围绕的他拥有着光明的未来。然而一次意外的车祸夺去了他心爱妻子的生命，虽然存活下来的他却失去了对生活和骑术的信心，眼睛的视力也渐渐衰退，让他不得不放弃了马术生涯。生活总会发生转折，和女儿艺胜相依为命穷困潦倒的承浩在马场遇上了一匹因为车祸失去幼子并且瘸腿的赛马露娜，相似的经历让承浩重新振作了起来，极力的阻挠下了人们对露娜的捕杀，努力驯服并且着手练习准备比赛。人们对于一个败落的骑手和一匹瘸马取得比赛胜利持有的不屑态度，期间技术上练习的重重困难，都没有打到这一人一马，决心东山再起的承浩更是为了女儿决定放手一搏，全力以赴…该片改编自纪录电影《Champ》里一匹叫做露娜的跛脚马和它主人的真实的励志故事。©豆瓣', '车太贤', '李焕庆', 7.9, 16963, 'tt2136809', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1196183112.jpg', 0.5, 2.6, 24.9, 46.6, 25.4, '-0.106605,0.185742,-0.563164,0.786405,0.043644,-0.418588,0.646762,-0.027054,-0.218678,-0.321094,0.502368,0.663214,0.101073,0.170236,0.279538,-0.430409,-0.225649,-0.757631,0.001993,0.276657,-0.233762,-0.300857,-0.457884,0.022234,-0.079721,-0.446132,0.822335,0.227163,-0.425618,0.780374,0.282038,0.046641,0.359033,0.215235,-0.409752,0.014178,-0.263443,0.144834,-0.205043,0.236764,0.056929,-0.224303,-0.204725,0.164129,0.152673,0.084364,0.856632,-0.396175,-0.306512,-0.125679,0.340927,-0.265652,-0.038991,0.050801,0.165490,0.343974,0.040347,0.186430,0.033979,-0.049759,-0.068871,-0.040069,-1.112294,-0.041664,0.087130,0.064171,-0.707787,0.501665,-0.020043,0.048477,0.021288,-0.204517,0.070321,0.241808,0.403055,0.313808,-0.321794,0.260592,-0.603320,0.259365,0.873778,-0.218061,-0.229304,0.330041,-0.187266,-0.489964,-0.249905,-0.513459,-0.607854,0.153603,0.355280,0.142168,-0.211711,0.287769,-0.528574,0.149819,-0.231040,-0.360110,-0.053541,-0.457165,0.149431,-0.246294,-0.138586,-0.471586,-0.365229,0.081764,-0.033876,-0.463141,0.876299,-0.772957,0.301287,0.442489,0.200244,-0.533574,0.551193,0.120973,0.280740,-0.201906,-0.035638,0.285224,-0.225953,0.250377,0.033347,0.203616,0.014663,-0.030138,-0.534997,0.882581', '30163500', '1793491', '25903033', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5250583', '最强囍事', '喜剧', '《最强囍事》豆瓣官方小站：http://site.douban.com/111545/化妆师沈美（古天乐 饰）在上一档电视节目时出现了尴尬，原来平素娘娘腔的他为了生活一直在伪装。他化妆学校的同学郑宇强（甄子丹 饰）在深圳一家美容专柜做化妆师，以高超的技巧赢得无数粉丝，但惟独没有俘获初恋女友戴梦妮（刘嘉玲 饰））的芳心。后者为了写小说，总是通过易容来贴近人物。陈奇侠（黄百鸣 饰）是石油大亨，唯一怕的就是他女友Dream（闫妮 饰）。后者因为观看电视节目，成了沈美的粉丝。夫妻俩联手，让沈美签下了合同，成了其化妆品公司的CEO。沈美为钱所动，走马上任，发现公司同事清一色都是美女。身为娘子军的他，有一个朴实的助理简洁（张柏芝 饰）。一次偶然的机会，游艇王子滑溜溜（杜汶泽 饰）看上了简洁，两人开始约会。但是经常受到滑溜溜前女友Victoria（熊黛林 饰）的骚扰。在这个过程中，沈美却逐渐发现了简洁与众不同的美……', '张柏芝', '陈庆嘉', 5.2, 75204, 'tt1815769', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p827635815.jpg', 11.3, 31.3, 46, 9.1, 2.3, '0.274022,0.024813,-0.420942,0.659347,-0.112487,-0.037901,0.505718,0.245845,-0.459902,-0.308347,0.234717,0.553918,-0.306965,0.076689,0.043629,0.065112,-0.091821,-0.628879,0.005290,0.062974,-0.119456,-0.210454,-0.246936,-0.261233,-0.127873,-0.325145,0.491649,-0.120730,-0.183428,0.338801,0.601588,-0.015020,0.033871,0.317231,-0.007979,-0.016909,0.196064,0.125062,-0.158437,0.234154,-0.150785,-0.355433,-0.035565,0.072144,0.055462,0.424199,0.619735,0.223110,-0.228564,0.162967,0.658482,-0.033549,-0.003419,-0.089984,0.254233,-0.077996,0.522497,-0.249523,-0.184539,0.023675,0.380866,-0.018995,-0.649420,0.075143,0.331466,0.099883,-0.346810,0.574303,-0.328624,-0.067023,0.017711,-0.431780,0.180081,-0.015295,0.425351,0.038949,0.154925,0.261173,-0.389672,0.739549,0.389057,0.403533,-0.091379,0.596616,-0.272257,-0.372536,-0.053419,-0.255129,-0.432344,0.112085,0.227637,-0.216441,0.040666,-0.144709,-0.699431,-0.137569,0.055994,-0.079057,0.033796,-0.359395,-0.104533,-0.572459,-0.238225,-0.471357,-0.173310,0.151496,-0.007188,-0.355117,0.744455,-0.923068,-0.082267,0.425084,0.128568,-0.542387,0.832925,-0.042028,-0.114404,-0.099846,-0.294328,-0.042287,0.058968,0.021950,0.102376,0.421194,-0.160001,-0.377493,-0.257949,0.233761', '1418179', '3033092', '4301278', '2338019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5256418', '极速天使', '剧情', '一年前，出色车手韩冰（刘若英 饰）因未婚夫背弃自己、选择和她在流光速车队的搭档游镁（张柏芝 饰）牵手而遭受精神打击。如今，流光速车队教练高峰（韩宰硕 饰）再次找到沉溺于酒精的韩冰，邀请她参加亚洲巾帼杯大赛，并带来了出租车司机出身的新队员小依（汤唯 饰）。小依因心理紧张而迟迟不能进入状态，此时游镁归队与韩冰再度搭档。流光速车队的老对手樱冥殿车队在韩冰昔日未婚夫鬼冢的主持下高调登场，并将游镁招致麾下以致流光速再无寻找队员的时间。流光速只剩推出韩冰和小依搭档的唯一选择，而小依却又车祸受伤，流光速如何突破重重阻碍重现辉煌？©豆瓣', '汤唯', '马楚成', 5.1, 26851, 'tt2118727', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1351918654.jpg', 13.2, 34.7, 40.9, 8.2, 3, '-0.217875,0.244424,-0.283791,0.378467,0.033365,-0.415780,0.290307,0.198096,-0.228141,-0.117533,0.331634,0.654647,-0.269662,-0.079886,0.172000,-0.627730,-0.053878,-0.562974,-0.032439,0.066932,-0.256480,-0.092520,0.169695,0.037477,0.231119,-0.184150,0.833914,-0.086249,-0.229504,0.614040,0.296383,-0.024292,-0.418172,0.202370,0.085846,-0.062756,-0.072500,0.158199,-0.256060,0.224128,0.010422,-0.188375,0.045545,-0.030296,0.045773,0.414469,0.510044,0.061659,-0.039274,-0.197544,0.276795,-0.306621,0.178303,-0.154985,0.159435,0.037289,0.002343,-0.094093,0.342931,0.038343,-0.042728,0.026880,-0.632912,0.179568,0.075449,-0.123903,-0.583573,0.456592,-0.540043,-0.137362,0.106824,-0.305923,-0.011031,0.346499,0.252383,-0.064211,-0.372951,-0.011103,-0.092900,0.273144,0.481640,-0.112423,-0.352629,0.481090,0.060949,-0.425609,0.069660,-0.280214,-0.111572,0.070313,0.017369,0.462302,0.045206,0.182340,-0.201851,0.066265,-0.432030,-0.176806,-0.043977,0.101405,0.027938,-0.695239,0.084341,-0.275985,-0.024205,0.113718,-0.210188,-0.064494,0.428919,-0.504907,0.153611,0.340778,0.408340,-0.423761,0.720232,-0.142542,-0.093307,-0.300675,-0.132196,0.438448,-0.298689,0.306324,0.112234,0.290083,-0.347025,-0.182539,-0.308756,0.153583', '1780122', '2369613', '3861846', '6101834');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5258017', '神探夏洛克(试播集)', '剧情', '《神探夏洛克》是一部由BBC出品的英国迷你电视剧，该剧将原著的故事背景从19世纪大英帝国国势鼎盛的时期搬到了21世纪繁华热闹的大都市中。试播集为原型短剧，从未在电视上播出过，2010年8月28日作为DVD花絮放出。这一次夏洛克·福尔摩斯(本尼迪克特·康伯巴奇 Benedict Cumberbatch 饰)不仅是著名大侦探更是一名时尚潮人。这一集的故事从他与日后的好友兼得力助手约翰·华生（马丁·弗瑞曼 Martin Freeman 饰）如何相识说起。起初两人合租贝克街221B公寓时候，华生并不能忍受这个奇怪的室友。但在共同经历了离奇市民自杀案件后两人的关系明显改善。而华生原本左肩在战斗时中弹，留下了心理障碍导致的跛足，也在跟随夏洛克追踪凶手，穿越伦敦市区的过程中克服了心理上的伤残障碍而痊愈。之后还有多少精彩绝伦的故事，只有让BBC的正式剧集来告诉大家了。', '本尼迪克特·康伯巴奇', '科奇·吉尔佐', 9, 28541, 'tt1815240', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1126230263.jpg', 0.1, 0.3, 6.9, 35.1, 57.6, '0.264020,0.034326,-0.448793,0.371807,0.315208,-0.275027,0.622446,-0.054934,-0.784749,-0.232472,0.141671,0.698309,-0.457126,0.137622,0.282552,-0.135368,-0.473469,-0.579138,-0.025292,-0.264731,-0.351010,-0.426993,-0.201663,-0.201813,-0.010951,-0.427064,0.540949,0.196756,-0.213018,0.401116,0.305484,0.139007,-0.244766,0.231672,-0.217810,0.031572,0.066821,0.224783,-0.346887,0.258776,0.045001,-0.337506,-0.168638,0.026181,-0.031967,0.392932,0.720531,-0.148488,-0.216092,0.163791,0.625308,0.081990,-0.284314,-0.160031,0.314036,0.072814,0.379919,0.335320,-0.003687,-0.060491,-0.236503,-0.176498,-0.623398,-0.012423,0.005212,0.166390,-0.460983,0.519148,-0.233981,-0.170770,-0.016364,-0.209375,0.286816,0.445554,0.511004,0.299392,-0.024230,0.132621,-0.288922,0.495900,0.710804,0.102135,-0.313200,0.558902,-0.162103,-0.531168,-0.397843,-0.292550,-0.254174,0.171978,0.117113,-0.092786,-0.256608,0.218835,-0.571950,0.044920,-0.157047,-0.184961,0.099886,-0.062431,-0.174536,-0.789080,-0.077952,-0.425033,-0.032086,-0.135478,0.105257,-0.284749,0.703785,-0.699126,0.295308,0.506290,0.192200,-0.173726,0.839057,0.012892,0.085156,-0.148847,-0.113889,0.267531,-0.032617,0.240838,0.102361,0.315786,-0.073123,-0.352469,-0.380528,0.520906', '26259202', '1302050', '3811356', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5258036', '觉醒', '悬疑', '故事发生在1921年的英格兰，在一战中所经历的失败令压抑而又沉痛的气氛笼罩了在全国上下。弗洛伦斯（丽贝卡·豪尔 Rebecca Hall 饰）是一位打假义士，正义感极强的她将戳穿谎言揭露真相视为己任，她不相信世间有鬼魂存在，存在的只有险恶的人心。在一所男子寄宿学校中，盛传着闹鬼的传闻，在人们口中，一个非正常死亡的男孩的鬼魂终日徘徊在校园中不肯离去。为了打消学生和家长的恐惧，学校委托弗洛伦斯前来调查。弗洛伦斯很快便展开了工作，在她的精明强干之下，事件的真相逐渐浮出了水面。而正当她以为问题已经得到了解决准备离开时，却发生了一件足以颠覆她此生全部信仰的事件。©豆瓣', '丽贝卡·豪尔', '尼克·墨菲', 6.8, 11930, 'tt1687901', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1524906586.jpg', 0.8, 6.9, 52.9, 32.4, 7.1, '0.329530,0.093040,-0.824762,0.400829,-0.200142,0.128989,0.997126,0.002981,-0.653527,-0.306967,0.256538,0.586231,-0.249821,0.309350,0.425825,-0.270408,-0.142065,-0.777486,-0.038867,-0.452615,-0.132070,-0.501608,-0.320683,-0.386460,-0.135448,-0.530758,0.734379,0.573024,-0.257923,0.172130,0.285003,0.447141,-0.207319,0.687512,-0.067414,-0.070064,0.011164,0.061990,-0.165414,0.060563,0.100755,-0.541483,-0.232414,0.311381,-0.228545,0.177493,0.722376,-0.451316,-0.277782,0.071553,0.484716,-0.515945,-0.122817,0.240212,0.325379,-0.003585,0.006811,0.572454,-0.252632,0.025961,0.224331,0.071014,-0.716633,-0.126811,0.125386,0.505739,-0.478214,0.480129,-0.052566,-0.004152,0.043599,-0.310945,0.183301,0.226281,0.227571,0.474930,-0.090451,-0.118764,-0.627457,0.260584,0.957590,-0.212667,-0.337209,0.290690,-0.274655,-0.285565,-0.148219,-0.088204,-0.497069,-0.053023,0.228766,0.221575,-0.453991,0.548381,-0.289726,-0.325115,-0.244773,-0.275874,-0.034503,-0.434287,-0.270670,-0.363672,-0.368591,-0.109057,-0.290450,-0.082735,0.062556,-0.263264,0.742571,-1.045014,0.232098,0.600667,0.080029,-0.415489,0.543767,-0.129147,0.276372,0.011059,0.019089,0.291391,0.048830,0.506763,-0.037962,0.358302,0.004752,-0.117376,-0.339401,0.446210', '1308755', '1301022', '25721544', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5262027', '此间的少年', '剧情', '根据江南同名小说改编。故事发生在一个平行时空之中，那儿是宋朝嘉佑年间的汴京大学，四名大一新生（郭靖、令狐冲、杨康、段誉）成为一个宿舍的同学。命运像一根看不见的丝线，将他们联系在了一起。一次偶然的自行车事故，使郭靖认识了校园里著名的美女黄蓉。聪明而漂亮的黄蓉是标准的富家大小姐，无数人追求的对象。然而出乎所有人意料的是，她竟然对除了勤快老实以外一无所长的郭靖青眼有加。随着不断的打饭打水，上自习，吃包子，以及兄弟们的推波助澜，汴大历史上最不般配的一场恋爱渐渐酝酿成熟。与此同时，满怀着雄心壮志的令狐冲却经历了大学生活里第一次重大打击。希望大展雄才的他却被安排了一个琐碎无聊的职务——“班长”。新官上任，第一次班级舞会就遭遇到各种困难。幸亏有师兄乔峰仗义帮忙，替他摆平了不少麻烦。随着做事的经验逐渐丰富，令狐冲发现要大展雄才并不像自己想象的那样简单。乔峰是大四的师兄，篮球高手，跟这个宿舍颇有交情。他在舞会上认识了师妹阿朱，后来成了男女朋友。跟这些年轻人在一起，乔峰有时会给他们一点过来人的忠告，有时又会触景生情，想起属于自己那个时代的一些往事。杨康和穆念慈从中学开始就是同学。穆念慈一直钟情杨康，却不敢说出口，只是安静地陪在杨康身边，提醒他应该做的事，杨康反而躲着穆念慈，害怕她的啰嗦。同学会上，在黄蓉建议下精心打扮过的穆念慈仍未能引起杨康的注意，却吸引来另一位追求者。等她终于下定决心的时候，记录了这一切的日记本又弄丢了。时间流逝，少年们度过了大学的第一年。这个夏天，师兄乔峰就要毕业了。喝离别酒的那个晚上，乔峰抽起了最后一支烟，想起了一个叫康敏的女孩。酒喝干，人送尽，连最后一本旧书也已经送出。乔峰', '黄河清', '胤祥', 7.6, 27227, 'There They Were', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p953405720.jpg', 2.5, 6, 26.6, 40.8, 24.1, '0.490628,-0.027829,-0.613507,0.452259,-0.242307,-0.431288,0.705135,-0.038894,-0.500416,-0.278581,0.073094,0.731609,-0.271111,0.371197,0.104944,-0.125614,-0.153408,-0.719928,-0.046560,-0.190096,-0.218853,-0.332326,-0.097751,-0.031939,-0.210574,-0.074914,0.204065,-0.077608,-0.145345,0.515173,0.217068,-0.136222,0.021349,0.589432,-0.357131,0.109634,0.042537,0.235318,0.001364,0.072396,0.127518,-0.287464,-0.197407,0.020052,0.073034,0.317067,0.471284,0.157826,-0.345693,0.026774,0.392016,-0.056547,-0.125875,0.005985,0.476322,0.027437,0.274325,0.008686,0.055097,0.044131,-0.136848,-0.088877,-0.455150,0.056895,0.244348,0.080766,-0.656884,0.544520,0.031891,-0.098753,0.019009,-0.329806,0.180344,0.315698,0.331380,0.133647,-0.049649,-0.066087,-0.410104,0.316077,0.653553,-0.147287,0.013638,0.425105,-0.115106,-0.091367,0.113819,-0.159875,-0.339014,0.188215,0.183406,-0.107359,-0.291420,0.134975,-0.337195,0.031763,-0.036918,-0.084603,0.053614,-0.311744,-0.233088,-0.348008,-0.065586,-0.459227,-0.342515,0.014148,0.067606,-0.253432,1.003390,-0.761829,-0.028273,0.565718,0.048646,-0.350243,0.647911,0.252529,0.078807,-0.143540,0.065298,-0.066542,-0.176257,0.202734,0.092808,0.696780,0.000506,-0.278532,-0.492207,0.295390', '30162520', '1292219', '1307146', '1308609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5262338', '虞美人盛开的山坡', '剧情', '20世纪60年代初，从二战的沉重打击中复苏的日本，正以极快的速度在世人的注视下重新确立自己的地位。位于横滨某个海港小镇，松崎家四姐弟和住客过着平凡的生活。16岁的姐姐海（长泽雅美 配音）照顾所有人的衣食起居，清晨则例行升起祈愿平安航行的信号旗。偶然的机会，海结识了同校新闻部的男孩风间俊（冈田准一 配音），校园生活平添一道靓丽的色彩。与此同时，东京奥运会召开在即，学校内俊和一群好友所栖身的古旧建筑“拉丁区”面临拆毁的命运。为了保护心中的圣地，俊、海以及同好们联合起来。在此过程中，他们心中某种隐秘的情愫悄然滋长，但是意想不到的命运却挡在了彼此的面前……本片根据根据高桥千鹤、佐山哲郎1980年1~8月发表在少女杂志《好朋友（なかよし）》上的同名漫画改编。©豆瓣', '长泽雅美', '宫崎吾朗', 8, 115332, 'tt1798188', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1335271624.jpg', 0.2, 1.8, 23.1, 46.1, 28.9, '0.224225,0.007422,-0.622679,0.787910,0.273704,-0.158681,0.579921,0.249797,-0.370388,-0.210050,0.324464,0.712360,-0.311995,0.558447,0.410618,-0.127017,-0.415592,-0.665745,-0.410941,-0.179274,-0.252849,-0.282658,-0.181871,-0.144139,-0.086120,-0.209633,0.744981,0.293345,-0.046026,0.558901,-0.004260,0.268874,-0.416252,0.183197,-0.211359,-0.101459,-0.114534,0.063413,-0.387427,0.188328,-0.300675,-0.348024,-0.187293,0.084073,0.042125,0.298077,0.968718,-0.166243,-0.144264,-0.021761,0.478053,-0.118268,-0.054512,-0.051847,0.444341,0.063198,0.031057,0.139368,-0.239777,-0.087638,-0.253876,-0.309807,-0.545282,-0.083284,0.227531,0.139385,-0.204423,0.487345,0.105415,-0.044971,0.134245,-0.314209,0.111508,0.304184,0.090001,0.360510,-0.205516,0.304358,-0.226634,0.209079,0.610690,0.154765,-0.258386,0.149129,-0.402700,-0.280247,-0.207931,-0.042840,-0.379612,-0.160873,0.242875,0.143365,-0.030690,0.401450,-0.601571,-0.029826,-0.109651,-0.200495,0.252966,-0.313541,-0.293252,-0.829033,-0.167712,-0.406748,-0.166279,0.235055,0.166820,-0.115730,0.869588,-0.905500,0.192686,0.558715,0.169393,-0.057226,0.670946,-0.053102,0.011909,-0.153599,-0.306916,0.349172,-0.105426,0.423036,-0.232747,0.320202,-0.272482,0.128490,-0.528049,0.436789', '3811356', '5403927', '25922902', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5262339', '天才捕手', '剧情', '故事发生在上世纪20年代末，默默无闻的文学青年托马斯（裘德·洛 Jude Law 饰）来到了世界文化的中心纽约，他的兜里揣着他撰写的自传体小说，这本小说被一位名叫麦克斯（科林·费斯 Colin Firth 饰）的编辑相中了，要知道，麦克斯可是曾经挖掘出菲兹杰拉德、海明威等大文豪的伯乐。在对小说进行了大刀阔斧的改动之后，文本最终顺利出版，被取名《天使，望故乡》，小说一经出版，瞬间就点燃了文学界的热情，托马斯也一跃成为了圈内炙手可热的新星。之后，托马斯开始和麦克斯合作打造下一部作品，在此过程中，两人越发亲密的关系让托马斯的女友艾琳（妮可·基德曼 Nicole Kidman 饰）心中亮起了警灯。©豆瓣', '科林·费尔斯', '迈克尔·格兰达吉', 7.4, 48550, 'tt1703957', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2441824955.jpg', 0.2, 3, 37.1, 45, 14.8, '0.519891,0.287409,-0.684111,0.738357,0.396388,-0.160316,0.564508,0.004094,-0.388418,-0.092275,0.004471,1.038128,-0.608752,0.141327,0.288814,0.107938,-0.517372,-0.924239,-0.093781,-0.383354,-0.138278,-0.644726,-0.336937,-0.159578,-0.096089,-0.358003,0.486203,0.077086,-0.101869,0.352111,0.219395,0.157703,0.148819,0.179495,-0.111279,0.326204,0.316734,-0.074471,-0.196026,0.475889,0.179079,-0.193301,-0.055265,0.165988,0.104938,0.079918,0.552079,-0.261656,-0.003178,0.116626,0.606902,0.027510,0.019766,-0.157302,0.188625,0.228075,0.225401,0.147397,-0.051471,0.089958,-0.099651,-0.222088,-0.551881,0.050142,0.076780,0.293046,-0.571509,0.341604,-0.182606,0.116243,0.013164,-0.482143,0.114078,0.051598,0.596179,0.166717,0.285554,0.356220,-0.116215,0.479636,0.137128,0.069957,-0.321153,0.541693,-0.083182,-0.269494,-0.212167,0.112297,-0.479533,-0.196241,0.811605,0.035426,0.022494,0.249323,-0.585081,-0.059762,-0.198677,-0.214722,0.123659,-0.214245,-0.181713,-0.531360,-0.370232,-0.245119,0.006395,-0.134257,0.014671,-0.439469,0.901298,-0.526614,0.308086,0.347237,-0.043298,-0.141451,0.688019,-0.098045,-0.095070,0.063349,0.109473,0.228284,0.064143,0.412855,-0.012767,0.368313,0.141666,-0.287785,-0.267752,0.691677', '30162520', '1307146', '1870681', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5265471', '唯爱永生', '剧情', '亚当（汤姆·希德勒斯顿 Tom Hiddleston 饰）和夏娃（蒂尔达·斯文顿 Tilda Swinton 饰）是一对携手共同穿越了数百年时光的吸血鬼恋人，从中古走到现代，两人经历了人类社会的数度大起大落，目前分居底特律和坦吉尔两地。亚当是一名地下音乐人，他厌恶无能又残暴的人类，将他们称作“僵尸”，陷入了抑郁的情绪中无法自拔的亚当甚至购买了木质子弹，打起了自行了断的念头，得知了恋人的糟糕状态，夏娃千里迢迢赶到了亚当的身边。短暂的重逢为亚当带来了新的希望，但令他感到不快的是，夏娃那臭名昭著的妹妹艾娃（米娅·华希科沃斯卡 Mia Wasikowska 饰）亦闯入了他们的生活之中。艾娃的到来带来的是灾难和诅咒，她不仅杀死了亚当唯一的人类朋友伊兰（安东·尤金 Anton Yelchin 饰），更将姐姐和姐夫两人的生活搅得一团糟。©豆瓣', '蒂尔达·斯文顿', '吉姆·贾木许', 7.6, 40869, 'tt1714915', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2155683303.jpg', 1.2, 4.9, 30.2, 41.3, 22.4, '0.370622,0.028567,-0.469790,0.607943,-0.073505,-0.504319,0.912442,0.077765,-0.562333,-0.145143,0.201028,0.836000,-0.292527,0.163409,0.369964,0.098162,-0.371550,-0.610316,0.030476,-0.167995,-0.292227,-0.281427,-0.473354,-0.200429,-0.021781,-0.474042,0.512649,-0.136479,-0.085385,0.578287,0.023631,0.342613,0.041921,0.347726,-0.163355,0.283942,0.124048,-0.130588,-0.446142,0.132746,-0.075529,-0.208306,0.133299,0.424300,-0.184958,0.256498,0.660939,-0.365200,-0.016123,-0.159713,0.361938,-0.280268,-0.205480,0.107634,0.167790,-0.142573,-0.004400,0.202549,-0.238370,-0.036635,0.136306,0.126036,-0.754884,0.204629,-0.040561,0.180707,-0.460242,0.551747,-0.053309,-0.055939,0.218145,-0.180601,0.256847,0.405655,0.341228,0.563373,-0.137554,-0.239373,-0.447972,0.161743,0.769002,-0.106747,-0.390306,0.192287,-0.442556,-0.426058,-0.088053,-0.126596,-0.467199,-0.225741,0.450755,0.100234,-0.281074,0.740634,-0.722271,-0.099710,-0.279917,-0.146905,-0.025089,-0.343748,-0.053900,-0.571295,-0.298910,-0.624621,-0.343791,-0.216110,0.072449,-0.282376,0.647157,-0.770082,0.260859,0.581703,0.452903,-0.225934,0.565741,-0.050437,0.132442,-0.149069,0.121497,0.418860,-0.035568,0.226612,0.376977,0.367292,-0.177809,0.100626,-0.367466,0.540344', '25828589', '30162520', '1307311', '26630714');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5273304', '永恒', '剧情', '本片是一个在极端的情况下爱情消逝的故事。尚孟（阿南达·爱华灵咸 Ananda Everingham 饰）从小就父母双亡被叔叔木材富商帕博（Teerapong Liaorakwong 饰）收养长大。从缅甸森林大学毕业归来，他就帮叔叔打理林场。尚孟长的帅气文雅且没有不良嗜好，他的叔叔帕博可是个风月高手，这天帕博又把从曼谷遇到的美貌而富有智慧的女子玉帕蒂（赖拉·邦雅淑 Laila Boonyasak 饰）娶回了森林的家。在尚孟和玉帕蒂日常交往中互生好感，终于在帕博去曼谷时两人跨越了防线，发生了关系。之后两人经常幽会，帕博从曼谷回来后，很快发现了他们的事。愤怒的帕博为了惩罚他们，决定用大铁链把两人永远锁在一起。起初尚孟与玉帕蒂还庆幸两人永远能在一起再也不会分开，可随着时间流逝，事情在悄悄的发生着难以想象的变化......©豆瓣', '阿南达·爱华灵咸', 'M·L·蓬德菲尼普·杜瓦库', 7.4, 15824, 'tt1740482', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p751713327.jpg', 0.8, 4.5, 34.5, 42.3, 17.8, '0.187637,0.033347,-0.655282,0.333249,0.063602,-0.453301,0.623527,0.313759,-0.549445,-0.297176,-0.048032,0.661910,-0.318710,0.136602,0.186031,0.070850,-0.411083,-0.732168,0.240691,-0.370168,-0.232562,-0.410708,0.141745,0.017197,0.093449,-0.337451,0.393838,-0.124052,-0.154680,0.516649,0.088424,0.015621,-0.398016,0.410372,-0.329469,0.105095,0.016811,0.228577,-0.375866,0.122587,0.031323,-0.237410,-0.087512,-0.301266,0.219158,0.026697,0.773918,-0.090945,-0.173682,0.111577,0.045249,0.077581,-0.022603,0.115005,0.458614,-0.338622,0.100501,0.392343,-0.383341,0.123212,0.131511,-0.158406,-0.445437,0.276857,-0.009899,0.092781,-0.758910,0.473625,0.081614,-0.125843,0.207035,-0.473065,0.291563,0.664052,0.097039,0.364027,-0.230273,-0.047977,-0.580214,-0.117509,0.886174,-0.110330,-0.170266,0.404111,-0.181200,-0.301801,-0.302525,-0.066981,-0.380463,0.095896,0.312214,0.060946,-0.561850,0.396611,-0.521861,-0.126745,-0.158003,0.024959,0.064573,-0.326919,-0.083772,-0.438621,-0.101146,-0.419486,-0.480326,0.288977,-0.014464,0.000930,0.732545,-0.794031,0.429659,0.379414,0.511934,-0.396799,0.627330,-0.050149,0.091756,-0.137472,0.019349,0.172299,-0.077921,0.263289,0.267437,0.319351,-0.198118,-0.110660,-0.290432,0.259051', '1292219', '25721544', '1299062', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5279575', '世界奇妙物语 2010秋之特别篇', '悬疑', '《讨厌的门》（京极夏彦）：人生跌入谷底的男人（江口洋介 饰），偶然听说有一家只要住一晚就能获得幸福的旅馆。只是那永远的幸福，悲哉？幸哉？《最初的一步》（万城目学）：公司职员小肇（大野智 饰）做事过于周到小心，惹怒女友（田中丽奈 饰）而不自知，这时月老（伊东四朗 饰）突然降临；《书签爱情》（朱川凑人）：普通劳动者邦子（堀北真希 饰）喜欢上了留着长发的青年学生，她欲言又止，只能通过书签和对方展开心的交流；《杀意使用说明书》（东野圭吾）：灰溜溜的广告人木谷（玉木宏 饰）意外在公司找到一本《杀意使用说明书》，他按照其中的介绍一步步展开杀人计划；《燔祭》（宫部みゆき）：妹妹惨遭杀害的多田一树（香川照之 饰）无时无刻不渴望复仇，在邂逅了拥有超能力的青木淳子（广末凉子 饰）之后，他的愿望似乎即将实现……©豆瓣', '江口洋介', '佐藤祐市', 7.3, 12018, 'tt1698034', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1973451981.jpg', 0.4, 3.9, 38.5, 43.2, 14, '0.154823,0.035406,-0.348959,0.305122,-0.074475,-0.156969,0.266793,0.247668,-0.172515,-0.175550,0.296352,0.511742,-0.019029,0.172659,0.182985,0.235096,-0.138974,-0.436602,0.059815,-0.103814,0.005190,-0.329416,-0.145960,-0.049788,-0.119056,-0.200054,0.802925,0.193423,-0.065239,0.417745,0.214022,0.317070,-0.075394,0.189365,-0.000418,0.041487,0.030075,0.146383,-0.226125,0.082483,-0.318612,-0.157810,-0.149499,0.146758,0.026948,0.177739,0.528322,-0.229528,-0.283652,-0.090991,0.407590,-0.053258,-0.042641,0.093305,0.021584,0.076313,0.143218,0.087980,-0.289584,-0.037123,0.156068,-0.036741,-0.528999,-0.137629,0.193990,0.195871,-0.335525,0.307137,-0.162238,-0.031024,0.304377,-0.290025,-0.158765,0.037200,0.327420,0.028693,-0.167356,0.099482,-0.189565,0.290981,0.288860,-0.158874,-0.132217,0.442231,-0.125234,-0.237733,-0.182851,-0.044084,-0.376867,-0.007599,0.235253,0.243338,0.010548,-0.119563,-0.293218,-0.172605,0.140797,0.206609,0.200094,-0.248076,-0.175592,-0.440324,-0.088483,-0.273525,-0.403391,0.083242,0.114971,-0.271320,0.579322,-0.675233,0.104004,0.461870,0.330245,-0.013330,0.428065,0.053213,-0.197595,-0.262114,-0.037929,0.193401,-0.077327,0.249361,0.111975,0.266945,0.034415,0.074133,-0.244340,0.247237', '26759820', '25880986', '3861846', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5279593', '幸福的面包', '剧情', '厌倦了大都会的奔波忙碌和机械化枯燥无味的生活，自有充满幻想的理绘（原田知世 饰）与温柔体贴的丈夫逃离东京，定居在北海道月浦一个毗邻湖泊的小山丘上。水缟夫妇在此经营一家名叫Máni的面包咖啡店，二人分工做出美味的食品，宴请来往驻足的人们。那一年，伤心的齐藤香织（森カンナ 饰）与始终困在北海道的青年山下时生（平冈佑太 饰）结识，纯纯的情愫悄然而生；沉默的小女孩未久（八木优希 饰）与父亲（光石研 饰）抱持着对母亲的思念，在Máni找到了慰籍；病入膏肓的老妇人和先生来访于此，品味着人生最后的时刻。寒来暑往，爱聚离合，生命之河伴随着咖啡与面包的香气缓缓流淌……©豆瓣', '大泉洋', '三岛有纪子', 7.6, 23484, 'tt1726749', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1421989266.jpg', 0.8, 4.5, 31.4, 40.6, 22.7, '0.130679,-0.065786,-0.495411,0.413902,0.219667,-0.216306,0.920128,0.555690,-0.430992,-0.277096,0.255891,0.816035,-0.069421,0.341802,0.355916,-0.073262,-0.191198,-0.613167,-0.188671,-0.055811,0.026693,-0.255431,-0.078944,0.061156,-0.141500,-0.247365,0.600848,0.269593,0.015833,0.661015,-0.040671,0.261185,-0.397080,0.305379,-0.303692,-0.179895,-0.159351,0.316843,-0.425494,-0.057732,-0.168673,-0.352833,-0.044020,-0.216026,0.101811,0.230929,0.950320,-0.199808,-0.182671,-0.075646,0.168856,-0.216835,0.063412,0.052960,0.085940,-0.003069,0.046025,0.132584,-0.516048,-0.099638,0.059742,-0.097604,-0.485319,-0.194043,0.032835,0.316665,-0.542652,0.606741,0.192744,-0.428117,0.264300,-0.331988,0.129810,0.189866,0.004572,0.436631,-0.178449,0.092132,-0.395190,0.124167,0.431082,0.019299,0.016610,0.287630,-0.323717,-0.433113,0.001231,0.030819,-0.612745,-0.405613,-0.038442,0.171066,-0.074477,0.134522,-0.904192,0.116852,0.069823,-0.217848,0.587150,-0.150423,-0.499199,-0.749882,-0.014757,-0.655367,-0.276272,0.166573,0.193352,-0.034032,0.644265,-0.758533,0.192751,0.307098,0.051057,-0.217425,0.772092,0.133987,0.027925,-0.165348,-0.036897,0.554769,-0.194924,0.121192,0.109833,0.395942,-0.286054,0.452721,-0.581525,0.123058', '1467779', '3811356', '1309194', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5279640', '委托人', '剧情', '一宗离奇的尸体失踪案一起轩然大波，嫌疑人疑似死者的丈夫。面对“嫌疑人”的异常沉默和深入案件后涌现的诸多疑点，律师决定为当事人做“无罪辩护”。然而，提起公诉的检查官则认定“嫌疑人”就是手刃自己妻子的凶手，双方在法庭上唇枪舌剑、针锋相对。迷雾缭绕的案情背后，真相竟超乎所有人的预料……', '河正宇', '孙英胜', 7.3, 21064, 'tt2072962', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2173900318.jpg', 0.3, 2.6, 39.3, 45.1, 12.6, '0.475835,-0.434831,-0.639114,0.493055,0.023050,0.028886,1.007026,0.194162,-0.672831,-0.261012,0.503575,0.607608,-0.457900,0.105344,0.237642,-0.334866,-0.435930,-1.176134,-0.195056,-0.285069,-0.154746,-1.060235,-0.152628,-0.509278,0.052000,0.316732,0.712431,0.192305,-0.194941,-0.021880,0.595082,0.413137,-0.811859,0.474824,0.221666,-0.326402,0.247285,0.173490,-0.790312,-0.040191,-0.010220,-0.359557,0.062214,0.445904,-0.434230,0.436144,0.699842,-0.146743,-0.450608,-0.140679,0.485987,-0.687327,0.153403,0.441515,0.692443,0.251599,0.326127,0.770043,-0.146686,-0.602726,-0.146403,0.076008,-0.912056,-0.171493,0.431811,0.361108,0.038285,-0.033986,-0.167201,0.186862,0.062390,0.058733,0.169531,0.146442,0.306904,0.284485,-0.261579,-0.254525,-0.268626,0.069670,0.416904,-0.028550,-0.235638,-0.203165,-0.119292,-0.487817,-0.168717,-0.147638,-0.002573,0.051205,0.101980,0.287110,-0.123923,0.636406,0.011046,-0.448169,-0.506203,-0.120408,-0.308890,-0.270409,-0.202393,-0.252863,-0.589442,0.089924,-0.404848,-0.009404,0.144378,-0.298910,0.223917,-0.367378,0.004505,0.294864,-0.027074,-0.539479,0.349968,0.296639,0.235501,-0.522173,-0.320276,0.034490,0.243716,0.147125,0.026481,-0.161696,0.041614,-0.132095,-0.450311,-0.096494', '26331839', '1296217', '25862560', '3992381');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5279979', '简单西蒙', '剧情', '西蒙（比尔·斯卡斯加德 Bill Skarsgård 饰）是一个患有亚斯伯格症的男孩，他是个物理天才，但不能忍受和人发生肢体接触；他有严重的强迫症，一切都要依计划执行；他不高兴就会把铁皮桶当成太空舱，躲在里面不肯出来。西蒙的监护人是他的哥哥山姆（马丁·沃斯特罗姆 Mar tin Wallström 饰），从小到大只有山姆能理解他。山姆的女友因为不堪忍受和这对兄弟一起生活而愤然提出分手。看到哥哥沉浸在消沉难过中，一直被人照顾的西蒙决定要照顾哥哥一次：他要用科学的方法帮山姆物色一个新的女友......©豆瓣', 'Jimmi Edlund', 'Andreas Öhman', 8.2, 8690, 'tt1686313', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2330942068.jpg', 0.3, 1.3, 17.8, 50.1, 30.4, '0.216971,-0.317276,-0.617957,0.445121,-0.356030,-0.089063,0.754732,-0.029885,-0.636148,-0.256916,-0.063752,0.790457,-0.036051,0.273870,0.039168,0.381174,-0.363532,-0.586091,0.040094,0.133621,-0.459932,-0.701827,-0.054918,-0.564954,-0.264476,-0.441140,0.505923,-0.172626,0.049870,0.236794,0.303683,0.333154,0.334551,0.509156,-0.068438,-0.040066,-0.073418,-0.105896,-0.238574,0.299399,0.421204,0.228236,0.043137,0.311795,0.256919,0.203051,0.387217,0.014924,0.007435,0.106160,0.180793,-0.361266,-0.006609,0.140625,0.044505,-0.379832,0.094269,0.166065,-0.236317,-0.132068,0.145568,-0.008464,-0.814801,-0.022716,0.154131,0.279039,-0.898784,0.374872,-0.339625,0.094470,0.090250,-0.331832,0.188657,0.228026,0.281095,0.502264,-0.140740,-0.106275,-0.524720,0.011929,0.812448,-0.129533,-0.268826,0.267400,-0.485636,-0.170929,-0.000612,-0.384311,-0.794353,0.174958,-0.057215,-0.130129,-0.516905,0.157785,-0.108872,-0.230464,-0.171696,-0.164807,-0.032833,-0.381597,-0.016212,-0.089165,-0.006163,-0.408484,-0.432179,0.007363,-0.207622,-0.458559,0.716904,-0.929797,0.181865,0.584244,0.453521,-0.452547,0.929612,0.417499,0.064434,-0.342974,0.179435,0.199220,-0.016689,-0.242790,0.249934,0.439657,0.548773,0.074682,-0.303555,0.311043', '1877596', '1302384', '1783461', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5285669', '婚前试爱', '剧情', '琪琪（周秀娜 饰）在一个礼拜后就要与恋爱七年的警员男友阿泽（罗仲谦 饰）结婚，在几个好友的聚会上，琪琪偶遇摄影师JACK（沈志明 饰），并在酒后与其发生了一夜情，追悔莫及的琪琪欲迅速终止这段关系，然而第二天二人再次相遇，在好友的怂恿下，琪琪等人与JACK同看演唱会，当夜琪琪意外发现了阿泽偷情的表徵，遂拉上JACK一起捉奸但一无所获，后者在离去时邀请琪琪在结婚前陪自己再度三天；另一边，执行任务的阿泽与街头女孩阿宝（杨梓瑶 饰）调换了手机，从未有过背叛女友念头的阿泽自此落入了一段短暂又不可思议的关系。马上就要结婚的二人，走上了各自的爱情岔路……©豆瓣', '周秀娜', '叶念琛', 5.6, 58476, 'tt1810618', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1321437572.jpg', 7.1, 25.9, 49.9, 13.6, 3.5, '0.524286,-0.153745,-0.556468,0.144861,0.122304,-0.558921,0.577808,0.193481,-0.338124,-0.182689,0.244842,0.796021,-0.672258,0.322707,0.530222,-0.134413,-0.355334,-1.038797,0.209883,-0.268684,-0.331451,-0.561114,0.197250,0.072215,0.202178,-0.050245,0.568348,-0.297836,0.223922,1.093861,0.324497,-0.294268,-0.588263,0.583236,-0.047106,0.219040,0.255403,0.268286,-0.596456,0.296906,0.114879,-0.263814,-0.032070,-0.013857,0.030553,0.233851,0.699750,-0.033169,-0.281133,0.219729,0.301503,0.032817,-0.179107,0.022323,0.324679,0.010146,0.305246,0.400479,-0.260878,0.031160,0.181456,0.027855,-0.078849,0.414957,-0.220334,0.127586,-0.484078,0.740401,-0.004685,0.111359,0.374119,-0.320206,0.166634,0.737763,0.108521,0.491782,-0.342213,0.066879,-0.192287,0.176813,0.637825,0.142146,0.309707,0.591131,0.235377,-0.134932,-0.056006,0.390715,-0.423429,0.071044,0.421736,0.177734,-0.491887,0.200799,-0.738152,0.014251,-0.170562,0.310378,0.086144,-0.243563,-0.038740,-0.728341,-0.157791,-0.191531,-0.341781,0.323313,0.001927,-0.014439,0.288602,-0.975398,0.273218,0.455797,0.367003,-0.584116,0.674003,0.462370,0.161448,-0.280726,0.338830,-0.019194,-0.128441,0.372040,0.181210,0.334959,-0.046290,0.225101,-0.539481,0.156164', '26365262', '3078390', '1301562', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5286821', '极恶非道2', '动作', '自从五年前成功篡位以来，加藤（三浦友和 饰）在石原（加濑亮 饰）的辅佐下带领山王会蹿升为关东最大暴力团，他们以经济利益为主要导向并逐渐将触角伸向政界，一时间风光无限。另一方面，组织内老派干部受到排挤，心存不满；警方敏锐注意到山王会的动向，暗中部署有针对性的坏灭行动；狡猾的片冈刑警（小日向文世 饰）出于自身利益，谋划着以黑制黑的凶险棋局。片冈首先策动山王会干部富田（中尾彬 饰）结交关西头号黑帮组织花菱会，在这一步棋失败后，随即找来了曾被山王会覆灭的村濑组若头木村（中野英雄 饰）以及一度传闻惨死狱中的山王会大友组组长大友（北野武 饰）。两位曾经的仇家既往不咎，势要将布施（神山繁 饰）所统领的花菱会势力带入关东，上演一出两强相碰的黑帮大火并……本片为北野武自编自导自演同名黑帮影片的续集，并荣获2012年电影旬报十佳影片第三名。©豆瓣', '北野武', '北野武', 7.8, 36818, 'tt1724962', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1725840594.jpg', 0.2, 1.8, 26.1, 51.2, 20.8, '-0.138299,0.085253,-0.531672,0.460328,0.426157,0.070174,0.231764,0.383503,-0.699541,-0.291310,0.522863,0.392150,-0.091345,-0.249006,0.230430,-0.228978,-0.127732,-0.746145,-0.325425,-0.131685,0.054759,-0.261618,-0.527847,-0.209355,-0.252709,-0.168161,0.735565,0.139147,-0.330729,0.460072,0.580187,0.576994,0.030293,-0.018742,0.315987,-0.020432,0.019353,-0.146972,-0.476218,0.396644,-0.405997,-0.418480,-0.364117,0.114369,0.090113,0.382296,0.553848,-0.311735,-0.076724,-0.411054,0.402623,-0.427314,-0.155242,0.179707,0.683394,0.109075,0.132201,0.643809,-0.284937,0.282014,0.009423,-0.227417,-0.807050,-0.175837,0.312201,0.127897,-0.298183,0.244058,-0.008393,-0.150763,0.294397,-0.057315,-0.083984,0.488250,0.557289,-0.018982,-0.145301,0.253532,-0.060861,0.178484,0.570366,-0.234454,0.167388,-0.190764,0.099277,-0.333006,-0.348442,-0.437797,-0.020736,0.006533,0.390912,0.018741,0.276262,0.389355,-0.325558,-0.183547,0.058149,-0.110171,0.272850,-0.178153,0.101104,-0.628411,-0.241641,-0.367963,-0.122211,0.114610,0.114971,-0.103344,0.731882,-0.859512,-0.058737,0.582581,0.128324,-0.500868,0.110543,0.179165,-0.168703,-0.101913,-0.320406,-0.020410,0.183295,0.373852,-0.080878,0.093365,-0.053351,-0.530498,0.038298,-0.187493', '25723905', '1920765', '1826173', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5289186', '芭比之时尚童话', '动画', '这次的故事发生在现代。一直以来都生活得无忧无虑的芭比（Diana Kaarina 配音）竟然被炒了鱿鱼，心中充满了郁闷，芭比决定前往巴黎散心，投靠在巴黎开时尚屋的阿姨米丽森（Patricia Drake 配音）。到了巴黎，芭比才知道，由于遭到同行的暗算，时尚屋即将面临倒闭的厄运，不愿看到这样的悲剧发生，芭比和米丽森和助手爱丽丝（Tabitha St. Germain 配音）决定联手，帮助米丽森。一次偶然中，芭比和爱丽丝发现了一个秘密的时尚屋，时尚就是在这里诞生的。在时尚屋里，两个女孩结识了古灵精怪的时尚精灵，有了精灵的帮助，芭比能够帮助米丽森重整旗鼓吗？肯（艾德里安·佩特里 Adrian Petriw 饰）芭比的男友，追随着芭比的脚步，他亦千里迢迢来到了巴黎。©豆瓣', 'Diana Kaarina', 'William Lau', 8.3, 6652, 'tt1725929', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2155075507.jpg', 0.1, 1.4, 20.6, 39.7, 38.2, '0.344782,-0.110584,-0.712639,0.479859,-0.055779,-0.309916,0.546351,0.188293,-0.226229,-0.337791,0.115415,0.913178,-0.319572,0.332261,0.602208,0.086874,-0.323533,-0.581192,0.097530,-0.197261,-0.237622,-0.339503,-0.277849,-0.217276,0.075836,-0.446023,0.392917,0.189497,-0.036593,0.463531,0.463685,0.237082,-0.201353,0.315679,-0.184044,0.045016,0.376042,0.258226,-0.232878,0.472229,0.023909,-0.229482,0.059821,0.299538,0.150226,-0.006248,0.638255,-0.256795,-0.097931,-0.093549,0.526118,-0.088051,0.046842,0.018343,0.418398,-0.089472,0.154094,-0.005970,-0.271949,0.016892,0.134324,-0.230198,-0.544374,0.264302,0.116027,0.075006,-0.549952,0.267807,0.117555,-0.240796,0.231578,-0.424699,0.240872,0.488456,0.534921,0.490410,0.140873,0.435583,-0.640648,0.137311,0.695558,-0.010194,0.007389,0.386518,-0.086587,-0.450223,0.087162,-0.092383,-0.545402,0.050228,0.362958,0.042702,-0.168240,-0.029749,-0.611249,-0.110648,-0.203783,-0.194505,0.100385,-0.415559,-0.191158,-0.656107,-0.141020,-0.368422,-0.005453,0.166733,-0.040086,-0.126109,0.514185,-1.025317,0.306535,0.525092,0.384727,-0.504169,0.759504,-0.026818,0.165633,-0.057087,0.112350,0.279693,-0.018893,0.093494,0.070467,0.442271,0.077163,-0.199401,-0.466238,0.224661', '6858739', '3055049', '1292219', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5290729', '全球热恋', '喜剧', '从中国到海外，从地球到太空，黄家三个如花似玉的女孩上演了一出出精彩浪漫却又甜蜜与酸楚并行的爱情肥皂剧。长女玫瑰（刘若英 饰）几经努力，终于获得前往太空站工作的机会，不过与她搭档的竟然是早已分手的恋人迈克（郭富城 饰）。逼仄密闭的空间里，万般情愫被无限放大；次女百合（桂纶镁 饰）只身闯荡悉尼，早年失败的恋情让她遭受洁癖强迫症的困扰，渴望重整旗鼓的百合却阴差阳错邂逅了自豪的垃圾工Johnny（陈奕迅 饰），老天的玩笑？还是一次奇妙的爱情混搭？小女儿牡丹（AngelaBaby 饰）是时下当红的烂片明星，自13岁便闯荡演艺圈的她渴望能够亲身感受一下普通人的生活。在咖啡厅体验期间，她遇见了怀才不遇的青年作家闻风（井柏然 饰），浪漫与现实充盈其间，如何抉择是个问题……©豆瓣', '刘若英', '陈国辉', 5.6, 105796, 'tt1856038', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1154009068.jpg', 6.3, 25.5, 52.6, 12.3, 3.4, '-0.054005,0.217806,-0.667486,0.475685,0.000081,-0.255943,0.848251,0.125420,-0.531993,0.091861,0.389254,0.544097,-0.486302,0.362684,0.246259,0.159585,-0.127100,-0.625569,0.193173,-0.115497,-0.096941,-0.071971,-0.532166,0.093380,-0.065882,-0.285002,0.761795,0.293095,-0.216819,0.269901,0.272631,0.211239,-0.321830,0.514969,-0.208975,-0.071554,0.159234,0.468797,-0.527572,-0.005456,-0.089165,-0.269627,-0.161210,-0.069598,-0.164763,0.110502,0.785523,-0.091231,-0.075172,0.112502,0.554204,0.038494,-0.368231,-0.032142,-0.031480,-0.048292,0.198702,-0.035435,-0.091952,0.119643,-0.043152,-0.178305,-0.642662,0.024784,0.093264,0.001628,-0.485669,0.562206,0.028857,-0.245873,0.139916,-0.066848,0.020820,0.083685,0.447508,0.449504,-0.229427,0.151092,-0.190448,0.444759,0.670680,0.137803,-0.350489,0.662466,-0.450092,-0.390408,-0.033947,-0.214789,-0.651289,0.048269,0.279011,-0.097433,-0.149112,0.264281,-0.806894,0.176682,-0.266859,0.090304,0.194362,-0.316232,-0.071320,-0.541336,-0.224487,-0.427397,-0.374500,0.040918,0.344094,-0.319273,0.692559,-0.692941,0.111285,0.626607,0.036605,-0.453768,0.732002,0.190594,-0.159275,-0.244193,-0.065381,0.502165,-0.381544,0.125990,-0.114217,0.448781,-0.254063,0.096003,-0.489898,0.437721', '1291835', '4233625', '2334814', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5294324', '隐婚男女', '剧情', '崔民国（陈奕迅 饰）与老婆张静宜（白冰 饰）十分恩爱，但也深感房贷压力。某日，崔民国遇到了调香大师好友Tony（庾澄庆 饰），后者发现了他对气味的天分，拉他加盟公司。不过，由于老板（刘若英 饰）明令禁止招收已婚男人，所以崔民国只得隐瞒结婚事实。起初，他遭到了老板前任秘书的奚落，被女同事们嘲讽。但是，高薪水还是让他跟老婆有了交代，这对隐婚男女也对地下工作乐此不疲。在一次应对日本客户“回忆”难题时，崔民国挺身而出，精彩解围，得到了老板的赏识。此后，他被经常要求加班，哪怕节假日也不放过，引发老婆极大不满。在请教闺蜜——情感专家如小果（秦岚 饰）后，崔民国被老婆鉴定为出轨，夫妻关系闹得很僵。与此同时，崔民国却留意到老板对明星阿伦（林依伦 饰）的关注非同寻常……©豆瓣', '陈奕迅', '叶念琛', 5.6, 49288, 'tt1887955', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p913021996.jpg', 5.8, 25.3, 53.3, 12.9, 2.6, '0.054218,-0.194689,-0.504569,0.430077,-0.063643,-0.110661,0.418158,0.219190,-0.588635,-0.373128,-0.114313,0.463083,-0.515827,0.370721,0.201297,-0.352325,-0.042167,-0.433093,0.314656,0.088598,-0.108183,-0.550683,-0.002786,-0.318847,-0.542398,-0.031426,0.154395,0.025881,-0.329187,0.274655,0.607771,0.141000,0.213862,0.688065,0.057866,0.058735,0.257875,0.294721,-0.217080,0.004227,0.250233,-0.402028,0.046035,0.194855,0.292871,0.543055,0.193762,0.225166,-0.295574,0.037609,0.527181,-0.104796,0.256146,0.234608,0.528040,0.196847,0.236593,0.142377,-0.190725,-0.127538,-0.073119,-0.022409,-0.268377,0.342284,0.364503,-0.213290,-0.562460,0.281332,-0.206733,0.134432,-0.088723,-0.128136,0.253476,0.348411,0.391584,0.264243,0.152560,0.510620,-0.360365,0.318673,0.367108,0.107767,0.084232,0.396743,-0.295214,-0.471801,-0.032663,-0.167866,-0.380354,0.128158,0.091758,-0.121423,0.060680,-0.044147,-0.383379,-0.274051,0.003471,0.093019,-0.014758,-0.342367,-0.013180,-0.507728,-0.132662,-0.575979,-0.345160,0.017812,0.298913,-0.407902,0.699644,-0.660275,-0.100173,0.287843,0.424465,-0.896805,0.930108,0.345851,-0.002203,-0.343117,0.034229,0.080352,0.195873,-0.062730,0.162762,0.128798,0.106487,-0.379256,0.180195,0.137843', '1303674', '19967839', '1421278', '1297924');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5294326', '今天', '剧情', '在教会的仪式上，多惠（宋慧乔 饰）对于未婚夫的意外死亡表现得极为大度，她甚至原谅了肇事者——年仅17岁的智敏，还替对方写了请愿书向法官求情。然而，未婚夫的大姐却对此耿耿于怀，她甚至指责多惠没有让杀人凶手得到惩罚。临别时，大姐送给了多惠生日礼物。而这让多惠陷入了对亡夫的追忆之中：一年前的某个雨夜，未婚夫驾车载多惠一道回家，因为那一天是她的生日，他们回忆起恋爱时的美好回忆，感到无比幸福。此时，未婚夫接到了烂醉好友的电话，多惠体贴地让他先去照顾好友，自己乘公车回家。没想到，这次分别竟成为诀别。雨夜，未婚夫被智敏飞驰的摩托车撞死。闻悉噩耗的多惠，始终保持了隐忍和克制，不仅原谅了智敏，而且还以宽宥的心拍摄宽容的纪录片，并支持废除死刑的教会活动。期间，她采访了形形色色的人物，见证了人性的诸般形态。当她了解到智敏的不幸遭遇，颇感震惊……©豆瓣', '宋慧乔', '李廷香', 7.5, 9734, 'tt2085883', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1449855111.jpg', 0.9, 3.9, 34.1, 43, 18.2, '0.085016,0.011208,-0.646247,0.473185,-0.157624,-0.510824,0.604670,0.140059,-0.487862,-0.146805,0.403237,0.618488,-0.257618,0.211852,0.416648,-0.071029,-0.260520,-0.541042,-0.015288,0.082074,-0.158635,-0.433721,0.020320,0.093598,-0.074801,-0.186340,0.454643,0.026548,-0.018887,0.744910,0.101150,0.226198,0.244752,0.514093,-0.034251,0.025055,0.059543,0.200586,-0.270437,0.113887,0.176812,-0.283523,-0.068344,0.490633,-0.202427,0.420807,0.637529,-0.180939,-0.485227,0.010545,0.567148,-0.404048,0.090152,0.214035,-0.056553,0.214065,0.261109,0.237324,-0.276165,-0.085852,0.037576,0.091498,-0.739030,0.162372,0.016693,-0.090384,-0.582532,0.534380,-0.240135,0.121896,0.245745,-0.443998,0.370420,0.227754,0.096120,0.461732,-0.450527,0.041545,-0.364921,0.280925,0.584236,-0.077566,-0.085223,0.336548,-0.258709,-0.182372,0.194357,-0.154107,-0.493875,0.261098,-0.053783,0.115190,-0.327242,0.249515,-0.296458,-0.266080,-0.447674,-0.031238,0.061876,-0.646797,-0.220515,-0.344590,-0.144061,-0.093640,-0.358080,-0.221288,0.127441,-0.347604,0.584434,-0.723910,0.367497,0.415383,0.329440,-0.479088,0.802040,0.450503,-0.266879,-0.236558,-0.007942,0.263766,-0.037637,0.179148,0.000686,0.050961,0.043393,-0.170589,-0.540416,0.368870', '26021055', '2990737', '35144311', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5294344', '出轨的女人', '剧情', '万太太（夏文汐 饰）于无意中发现丈夫出轨的照片，十分痛苦伤心。朋友Jojo（叶璇 饰）和何太（吴家丽 饰）等人拉她去了邻近的某高级娱乐会所嫖男妓。Jojo与丈夫黑白哥（杜汶泽 饰）感情冷淡，生活不合，因此长期在外寻欢作乐。何太太的丈夫忙于生意，冷落了家庭，她寂寞孤寂之下也开始在外寻欢作乐。在会所里，何太和万太同时看上了帅气迷人的bill（陈伟霆 饰）。心灰意冷的万太却发现bill对她分外热情，两人在肉体金钱关系之外逐渐陷入了爱情。何太不愿万太霸占bill，于是两人开始了一场抢夺。某日清晨醒来万太发现身边的人不是bill却是他的同胞弟弟ben，故事慢慢展开了一场惊人的阴谋与纠葛......©豆瓣', '夏文汐', '潘源良', 5.8, 19617, 'tt1837529', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p860992945.jpg', 6.9, 23.3, 48, 15.7, 6, '0.089139,0.004555,-0.519610,0.218538,-0.034950,-0.132227,0.841145,0.249386,-0.790783,-0.386994,0.029991,0.619580,-0.263044,0.370407,0.333778,-0.086516,-0.093710,-0.572816,-0.111162,0.068952,-0.143891,-0.287509,0.003019,-0.238681,-0.166146,-0.232803,0.394931,0.099238,-0.300214,0.460825,0.314655,0.285891,-0.304996,0.577912,-0.059367,0.073071,-0.182259,0.199343,-0.345397,-0.132365,-0.076298,-0.330492,-0.165687,0.117886,0.002863,0.203290,0.640900,-0.087485,-0.356420,-0.179875,0.405977,0.018777,-0.097961,0.096316,0.266945,0.005858,0.516204,0.045160,-0.320278,-0.173693,0.073320,-0.031459,-0.336905,0.208881,0.105844,0.187896,-0.345690,0.527403,-0.005245,-0.199122,0.137921,-0.087105,0.130471,0.245713,0.126532,0.200015,-0.157491,-0.109412,-0.331128,0.326029,0.630860,0.181741,0.207016,0.569070,-0.161390,-0.182174,-0.130742,-0.281859,-0.577053,-0.122738,0.310037,0.124611,-0.042797,0.444429,-0.744372,-0.052954,0.014683,0.159069,-0.053325,-0.455167,0.062089,-0.374097,-0.309200,-0.689166,-0.249893,0.198292,0.112607,-0.169332,0.468677,-0.911111,0.312300,0.251072,0.443202,-0.601653,0.521409,0.287697,0.044451,-0.104044,0.011510,0.156972,-0.094554,-0.074648,0.202804,0.119994,-0.160486,0.079630,-0.307297,0.372210', '1308755', '10574468', '21766698', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5294432', '魔法老师', '喜剧', '在外星人的眼中，地球人就是供他们玩乐的消遣。一群外星人打了一个赌，赌注是地球的存亡。他们在地球上随机选了一个人，赋予他心想事成的超能力，如果这个人最终成为了贪得无厌的恶人，外星人就选择把地球毁灭，但如果这个人依然维持着善良的本性，则意味着地球仍然有着继续运转的意义。平凡而又内向的中学老师尼尔（西蒙·佩吉 Simon Pegg 饰）成为了这名干系到地球存亡的天选之子，在拥有了超能力后，尼尔的身边发生了一连串有惊无险令人不知该笑还是该害怕的意外。与此同时，尼尔默默爱慕的女子凯瑟琳（凯特·贝金赛尔 Kate Beckinsale 饰）也被卷入了危险之中。©豆瓣', '西蒙·佩吉', '特瑞·琼斯', 6.5, 23184, 'tt1727770', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2375394548.jpg', 1.6, 11.2, 54.5, 25.2, 7.6, '0.390544,0.372953,-0.768788,0.545177,-0.447109,-0.188121,0.857719,0.080810,-0.328984,0.151334,0.400719,0.889630,0.055388,0.166595,0.325362,0.364182,-0.347536,-0.538296,0.166419,-0.405251,-0.487167,-0.454250,-0.419877,-0.252477,-0.086691,-0.350445,0.537986,0.147172,-0.108268,0.334083,0.299237,0.175607,0.090314,0.648416,-0.164897,0.027902,-0.104997,-0.004987,0.062391,0.177618,-0.223009,-0.058311,0.055090,0.407766,-0.199850,0.262331,0.614483,-0.398686,0.018549,-0.278955,0.156478,-0.294675,-0.076806,0.153053,0.242514,-0.275178,-0.173419,0.042351,-0.025595,0.073442,0.396646,0.210422,-1.093020,-0.110559,-0.031875,0.358489,-0.613953,0.650851,0.048769,-0.409675,-0.175191,-0.152354,0.222570,0.302842,0.445546,0.375072,-0.203652,-0.059462,-0.508245,0.022797,0.563465,0.070235,-0.649908,0.355178,-0.337733,-0.479064,-0.306055,-0.368882,-0.435048,-0.160411,0.340598,0.075056,-0.268295,0.338478,-0.645199,0.232611,0.006208,-0.039075,-0.246427,-0.713043,0.029431,-0.357662,-0.031115,-0.431828,-0.383452,0.140233,0.080400,-0.236382,0.992522,-0.793780,0.107042,0.994234,0.294927,-0.513749,0.517259,0.346181,0.207845,-0.225068,-0.071297,0.305380,0.047934,0.489296,-0.016914,0.395617,0.239527,-0.012149,-0.096900,0.639537', '24284209', '30163500', '25932086', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5294851', '控方证人', '剧情', '威尔弗里德（拉尔夫·理查德森 Ralph Richardson 饰）是伦敦知名的辩护律师，最近因为心脏出现了问题，而被迫留在家中卧床修养。某日，律师梅林带来了一位名叫沃尔的委托人，沃尔遇到了大麻烦，希望法力无边的威尔弗里德能够帮助他，这让无聊的快要发霉的威尔弗里德顿时来了精神。原来，威尔结识了一位非常富有的女人，这位女士十分欣赏威尔弗里德的才华，甚至在自己的遗嘱上写下了威尔弗里德的名字。然而，之后没多久，这位女士就惨遭杀害，即将继承她的遗产的威尔弗里德自然成为了警方头号怀疑的对象。唯一能够证明威尔弗里德清白的，是他的糟糠之妻克里斯汀。©豆瓣', '拉尔夫·理查德森', '艾伦·吉布森', 9.4, 55466, 'tt0084911', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2367853261.jpg', 0.1, 0.2, 2.7, 21.2, 75.7, '0.217528,-0.011112,-0.556706,0.243253,-0.347809,-0.436123,0.579242,0.540913,-0.592157,-0.407918,0.196013,1.003091,-0.081031,0.012464,0.724852,0.345853,-0.023646,-0.405950,0.089248,-0.154186,-0.165388,-0.825166,-0.419575,-0.274019,-0.039252,-0.486766,0.273611,0.017256,-0.265328,0.342110,-0.068208,0.681934,0.569982,0.190234,0.137557,-0.097471,0.450507,-0.481684,0.072975,0.341225,0.141870,-0.129251,0.114367,0.388511,0.052570,0.331699,0.137611,-0.045247,-0.095798,0.077117,0.137888,-0.175746,0.283546,0.145757,-0.073542,-0.383397,0.502820,0.167899,-0.108027,-0.455447,0.226687,-0.150461,-0.834468,0.268744,-0.349277,0.305322,-0.586304,0.369307,-0.260357,-0.300064,0.327584,-0.351705,0.269453,0.388621,-0.106880,0.008355,-0.282587,-0.037580,-0.359528,0.018485,0.149712,0.107359,-0.306182,0.347929,-0.094540,-0.438713,0.036884,-0.039599,-0.605658,0.047443,0.615796,0.181571,-0.112689,0.243308,-0.382284,-0.200886,-0.468597,-0.354675,0.053228,-0.139460,-0.022291,-0.526487,-0.285141,-0.047657,-0.515996,-0.493710,-0.014667,-0.294231,0.644718,-0.891953,0.386991,0.691462,-0.293881,-0.397768,0.494783,0.202217,0.367100,0.215855,-0.272530,0.414646,0.239551,0.380903,0.057216,0.264851,0.152221,-0.401323,-0.599445,0.704240', '1309069', '1793491', '1783461', '1293145');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5295610', '第八日的蝉', '剧情', '一段不伦之恋，造成了两代人的人生悲剧。野野宫希和子（永作博美 饰）无法得到情人的身与心，还被迫杀掉了腹中的孩子。在一个瓢泼大雨的日子里，万念俱灰的希和子走入情人的家，抱走了他们尚在襁褓中的女儿惠理菜。此后的岁月中，她带着“女儿”薰辗转各地，只为寻求“母女”安身立命的宁静之所。此去经年，长大成人的惠理菜（井上真央 饰）经历着人生的种种，而她似乎正在走一条与“母亲”希和子相同的路。无论多么不愿回首，她仍按照宿命的指引追忆着与希和子共处的那段短暂而美好的时光……本片根据角田光代的同名原著改编，并荣获2011年电影旬报十佳第5名、最佳女主角奖（永作博美）、最佳女配角奖（小池荣子）；第36届报知电影奖最佳影片奖和最佳女主角奖。©豆瓣', '井上真央', '成岛出', 8.3, 22954, 'tt1727825', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p997313868.jpg', 0.3, 1.3, 16.1, 49.6, 32.6, '0.069245,-0.084825,-0.482981,0.714668,0.177551,-0.384528,0.709987,0.062935,-0.493372,-0.166428,0.159750,0.858058,-0.108149,0.391676,0.400847,0.004361,-0.338414,-0.805949,-0.428513,-0.320730,-0.075973,-0.200461,-0.313473,0.367460,-0.217664,-0.266218,0.937707,0.022433,0.212308,0.452252,0.482781,0.112697,-0.567046,0.072506,-0.324147,0.325005,-0.171968,0.271536,-0.403202,0.236313,0.019382,-0.560087,-0.461637,0.011426,-0.209751,0.282400,1.018076,-0.509944,-0.037383,-0.159399,0.561871,-0.325815,-0.299431,0.161284,0.191290,-0.135298,0.346157,0.424330,-0.184017,0.145360,0.093811,-0.080301,-0.682642,-0.117399,0.175411,0.221142,-0.623711,0.336575,0.070360,0.037255,0.341317,-0.076694,0.057197,0.292689,0.437457,0.374328,-0.522086,-0.079082,-0.304840,0.590724,0.638030,-0.049857,-0.222173,0.565715,-0.132195,-0.559864,-0.115305,-0.081895,-0.859240,-0.151161,0.378776,0.419750,-0.118520,0.261645,-0.440009,0.276030,-0.172891,-0.123461,0.151907,-0.398134,0.073585,-0.542954,-0.150004,-0.498892,-0.234789,0.110993,0.333084,-0.392689,0.629040,-0.425376,0.392017,0.499455,-0.011651,-0.371394,0.761659,0.309721,0.337411,-0.269671,-0.082056,0.453095,-0.366663,0.301780,0.036914,0.252554,-0.330498,0.043942,-0.613241,0.491713', '1299663', '1292925', '26759820', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5295974', '富江 无限制', '恐怖', '饭冢家两个女儿富江（仲村みう 饰）和月子（荒井萌 饰）在同一所学校读书，两人更是同时恋上了同一个男孩下田俊夫（大和田健介 饰）。面对一脸幸福的姐姐，心中略感失落的月子还是用手中的相机为姐姐拍下最美的一瞬。然而，近乎完美的富江就在月子的面前死于一场恐怖的意外。一年后，月子和父母共同庆祝富江的生日，而就在这一天本应死掉的富江重返家中。自此，饭冢夫妇的行为举止变得甚为古怪，月子也见到了姐姐极为恐怖的一面。未过多久，饭冢一家陷入极度恐慌的混乱之中，父亲更失手杀害了富江。可是，那却是一个如何也死不掉的妖艳魔女……本片根据日本著名恐怖漫画家伊藤润二的同名系列漫画改编。©豆瓣', '荒井萌', '井口升', 4.6, 6415, 'tt1728217', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1550592152.jpg', 25.6, 34.1, 28.3, 8, 4, '-0.054187,-0.022802,-0.446612,0.389676,0.067406,-0.588763,0.654494,0.173610,-0.345827,-0.347433,0.261322,0.768729,-0.477810,0.468576,0.193465,-0.075392,-0.176389,-0.383953,-0.397202,0.051251,-0.249729,-0.134199,-0.132821,-0.029947,0.034996,-0.055979,0.694612,0.066608,0.055201,0.505475,0.420612,0.236205,-0.277711,0.250173,-0.098784,-0.023909,-0.146943,0.154781,-0.161543,-0.016069,0.112630,-0.367024,-0.116466,0.232429,-0.081572,0.130521,0.736420,-0.120775,-0.477910,-0.304238,0.515557,-0.111884,-0.356929,0.149112,0.198234,-0.261522,0.353517,-0.058939,-0.391361,0.174251,0.040180,0.060985,-0.754261,0.020263,0.207646,-0.069764,-0.395957,0.410188,0.033134,-0.253553,0.336358,-0.204389,0.207097,0.403077,0.220742,0.648768,-0.463137,0.059185,-0.260804,0.216601,0.522369,0.001011,-0.063991,0.321430,0.046643,-0.399470,-0.194512,-0.225369,-0.481750,0.235669,0.008642,0.090840,-0.121788,0.381387,-0.513859,-0.095133,-0.251664,-0.111845,0.076484,-0.294351,-0.169833,-0.445551,0.013194,-0.327053,-0.520234,0.103396,0.279764,0.041417,0.575933,-0.657277,0.372883,0.001143,0.148493,-0.060317,0.297647,0.290680,0.069632,-0.173862,-0.190692,0.135307,0.041796,0.036822,0.236557,0.440414,-0.198599,0.060782,-0.570658,0.665046', '2357162', '5364978', '25880986', '30401849');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5296286', '空之境界 终章 空之境界', '动画', '“黑桐，你知道吗，杀人和杀戮是不一样的。据说，人一生只能杀一个人？”从心底里渴望成为“特别”的存在。这种愿望作出了错误的选择。不，应该说是被错误引导出了这种愿望。那时候，深信这是唯一的也是最好的方法。这是4年前也就是1995年和她相遇时发生的事。次年即1996年，她陷入了沉眠。然而，罪恶的萌芽却在不知不觉中发育成长。然后，两年后的1998年，她苏醒了，开始镌写新的时刻。与此同时，想得到她的意图也蠢蠢欲动……在，4年后的1999年。所有得到她的手段都本该有破绽的。可是，命运的齿轮偏离了轨道。4年之后再度反复的恶魔杀人事件。暗夜杀人犯是潜藏在她内心深处的杀人冲动和已经无迹可寻的“织”，已经想不起来。到底杀的是“谁”，为此，她徘徊在深夜的街头，为此，他为了她在黑夜里往复。杀人和杀戮的不同，是特别和普通的差异，是戾气和正气的差别。明明重要的不是这些而是自己的存在，却被这些对错所囚禁——明明希望的只是重要的人可以好好活着，这理所当然的事却背负上了曾经的罪孽——', '坂本真绫', '近藤光', 8.5, 11226, 'tt3868344', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2179546226.jpg', 0.7, 2.4, 14.7, 33.2, 49, '0.393465,0.116865,-0.870524,0.483829,-0.345495,-0.163263,0.970614,-0.278808,-0.606534,-0.277944,0.108847,0.582920,0.023455,0.184140,-0.025102,0.099634,-0.141230,-0.939285,0.036161,-0.412122,-0.301795,-0.495670,-0.428135,-0.236744,0.058425,-0.399388,0.664415,0.435128,-0.178120,0.119634,0.330737,0.458504,0.295432,0.748795,-0.379451,-0.186132,-0.287453,0.210190,-0.119062,0.021815,0.089678,-0.546268,-0.210593,0.411126,-0.139693,0.623232,0.493542,-0.587184,-0.269854,0.041075,0.360668,-0.582642,-0.312639,0.300082,0.144503,-0.164225,0.178000,0.419238,-0.198585,-0.085508,-0.109847,-0.050819,-1.317614,-0.285988,0.103201,0.111678,-0.636804,0.527029,0.005603,-0.058331,0.119051,-0.275972,0.438778,0.316710,0.382216,0.437322,-0.311605,-0.324125,-0.694376,0.110177,1.140590,-0.098945,-0.388743,0.553828,-0.282918,-0.581428,-0.326389,-0.430230,-0.270868,0.113148,0.052495,0.373427,-0.473383,0.320271,-0.481547,0.082928,0.028804,-0.197476,-0.027956,-0.636049,-0.320132,0.110451,-0.242140,-0.739407,-0.515421,0.015635,0.033005,-0.466165,0.686584,-1.114863,0.383084,0.741237,0.255863,-0.700057,0.940571,0.213109,-0.145621,-0.126117,-0.101834,0.117751,-0.139530,0.428658,0.184105,0.298622,0.35