INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5298995', '钢之炼金术师：叹息之丘的圣星', '剧情', '在亚美斯多利斯期间，爱德华・艾尔利克（朴璐美 饰）和弟弟阿尔方斯（钉宫理恵 饰）遭遇了还有两个月就可以刑满释放的越狱犯梅尔文（森川智之 饰），结果发现对方拥有不输于艾尔利克兄弟的强大炼金术。根据梅尔文在监狱留下的蛛丝马迹，兄弟二人前往西方的大国古雷达调查。在这里他们的火车遭到神秘黑蝙蝠的袭击，同时也遇到了梅尔文寻找的少女茱莉亚・克莱顿（坂本真绫 饰）。一番混乱之后，他们相继来到位于地下的贫困之镇米洛斯。米洛斯是大国夹缝中的牺牲品，而她的人民也决定利用圣星的利用重新复兴祖国与民族……本片根据荒川弘的漫画原著改编。©豆瓣', '朴璐美', '村田和也', 7.2, 11310, 'tt1776196', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1957471187.jpg', 1.2, 5, 38.8, 40.3, 14.8, '0.248836,0.027115,-0.754885,0.639153,0.267994,-0.189538,0.350659,0.028370,-0.488856,-0.320611,0.426909,0.662694,-0.155736,-0.055120,0.260123,0.022528,-0.499164,-0.725582,-0.066045,-0.436682,-0.451355,-0.429922,-0.250960,-0.223124,-0.129344,-0.264871,0.749075,0.163482,-0.351105,0.305232,-0.008056,0.407177,-0.424192,0.066569,-0.125187,0.226370,0.057160,-0.040145,-0.370353,0.270693,-0.060550,-0.039695,-0.221002,0.137046,0.047707,0.362285,0.805655,-0.433910,0.024398,-0.156628,0.200570,-0.158346,-0.242451,-0.090332,0.511531,-0.235611,0.021402,0.268696,-0.172819,-0.098419,0.161321,-0.072162,-0.631267,-0.193958,0.104552,0.131556,-0.442472,0.355268,0.024888,-0.179736,0.318578,-0.317759,0.291460,0.590468,0.367556,0.366575,-0.015152,-0.000821,-0.239456,0.093786,0.410102,-0.116894,-0.215894,0.074975,-0.154046,-0.553781,-0.221520,-0.259900,-0.206221,-0.136468,0.491419,-0.008306,-0.074129,0.283643,-0.695776,-0.120065,-0.410189,-0.252154,0.319193,-0.259659,0.005031,-0.852330,-0.104699,-0.456634,-0.123466,0.316162,0.099631,-0.192109,0.835089,-0.919272,0.182082,0.466342,0.328260,-0.345225,0.457461,-0.224030,-0.016791,-0.208438,-0.144098,0.191415,0.340151,0.451950,0.088920,0.179832,-0.001021,-0.138337,-0.379321,0.002917', '20274039', '2369613', '3811356', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5300054', '波西米亚狂想曲', '剧情', '本片是对皇后乐队、传奇主唱弗雷迪·莫库里以及他们音乐的致敬盛宴，这是一段充满爱、痛苦、接纳和音乐的旅程。弗雷迪·莫库里（拉米·马雷克 饰）曾是希思罗机场的一名普通搬运工，对音乐满腔热血的他，与布莱恩·梅（格威利姆·李 饰）、罗杰·泰勒（本·哈迪 饰）、约 翰·迪肯（约瑟夫·梅泽罗 饰）组成皇后乐队。这个殿堂级乐队的从无到有，从疏离到重聚，从低谷到巅峰，仿佛就是弗雷迪一生的缩影。在最后的日子里，弗雷迪做了生命中最重要的决定——在音乐史上最伟大的“拯救生命”大型摇滚乐演唱会上，将所有热血付诸于歌声。©豆瓣', '拉米·马雷克', '布莱恩·辛格', 8.6, 559183, 'tt1727824', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2549558913.jpg', 0.2, 1.3, 12, 38.6, 47.8, '0.158415,0.270964,-0.551366,0.834892,-0.053137,-0.360224,1.087379,-0.101842,-0.355948,-0.225004,0.089541,0.725377,-0.111136,0.481581,0.519919,-0.194725,-0.370908,-0.695276,-0.173352,-0.313221,-0.439619,-0.490717,-0.114083,-0.153913,-0.216506,-0.316426,0.629502,0.190159,-0.234129,0.332589,0.609067,0.523431,0.109322,0.203762,-0.142082,-0.063988,0.273486,0.060163,-0.356017,-0.084193,-0.044650,-0.236705,-0.253187,0.169921,0.134560,0.030063,0.513924,-0.534335,0.596253,0.105714,0.349780,-0.209546,0.089116,-0.122797,0.010257,0.085086,-0.090635,0.236066,-0.151601,0.086395,-0.234103,-0.399400,-0.865811,-0.091858,-0.153509,0.155902,-0.456823,0.271230,0.020198,-0.044403,0.343512,-0.171506,0.259866,-0.163642,0.284551,0.452369,-0.129399,0.109290,-0.495669,0.284360,0.763807,0.145850,-0.235019,0.329184,-0.219397,-0.798769,-0.279258,-0.261310,-0.448944,-0.187341,0.106365,-0.226262,0.610744,0.137224,-0.685057,-0.183168,0.105725,-0.392845,0.187645,-0.325792,0.025183,-0.788912,-0.114491,-0.572203,0.021747,0.070487,0.095358,-0.345537,0.944914,-0.662370,0.410191,0.259049,-0.215621,-0.096295,0.722582,-0.002226,0.332541,-0.299137,0.151481,0.550182,0.039025,0.010082,0.114832,0.409746,-0.016826,0.114159,-0.474734,0.892379', '2053515', '27666513', '30162520', '1793922');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5301572', '大宅门', '剧情', '电影版《大宅门》撷取了整部作品中最为精彩的前十五集———“复兴百草厅”作为电影的主要内容，讲述了因与官宦世家詹府惹下纠纷，险遭灭顶之灾、经营岌岌可危的百年老号———白草厅，如何在白家二媳妇“白文氏”的运筹帷幄下起死回生，再度复兴的故事。', '斯琴高娃', '郭宝昌', 9.3, 8278, '大宅门 电影版', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1964425586.jpg', 0.2, 0.4, 4.4, 25.5, 69.5, '0.071132,0.146209,-0.295123,0.555918,0.642437,-0.090152,0.393331,0.353030,-0.502724,-0.212424,0.277144,0.500868,-0.074041,0.107507,0.181788,-0.281381,-0.315168,-0.392091,-0.542050,-0.154525,0.048400,-0.008405,0.035643,0.026885,0.083284,0.019948,0.612060,0.510027,-0.456566,0.029534,0.078164,0.568275,-0.335338,-0.375375,-0.075906,0.354397,-0.163963,0.329891,-0.448011,0.014497,-0.261780,-0.498042,-0.563654,0.018044,0.062420,0.223052,0.484547,-0.373097,-0.113053,-0.374775,0.615796,0.322848,-0.387747,-0.119633,0.610588,0.122785,0.378011,0.660636,-0.019352,-0.293776,-0.268331,-0.134048,-1.280860,-0.042026,0.390159,0.114462,-0.580881,0.407095,0.000448,0.011467,-0.076337,-0.089090,0.190779,0.588975,0.683877,0.112757,-0.282895,0.250649,-0.483546,0.479796,0.467134,0.242018,0.030129,0.305187,0.142343,-0.250022,0.155234,-0.530154,-0.503479,-0.062830,0.621162,-0.230088,0.688130,0.482850,-0.414062,0.077853,-0.020878,-0.583185,0.571473,-0.150324,-0.052806,-0.683595,-0.371585,-0.147214,-0.319367,-0.403928,0.461600,-0.319781,1.164050,-0.310034,0.118172,0.092681,-0.188589,-0.636318,0.499066,0.018517,0.576437,-0.123935,-0.437108,-0.084474,-0.011936,0.535858,0.026777,0.198691,-0.431128,-0.358324,-0.257628,0.456407', '27602116', '3318306', '24284209', '3718665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5308201', '剑风传奇 黄金时代篇1：霸王之卵', '剧情', '百年战争，世事颠倒，人心糜烂，贪欲横行。各国之间兼并攻伐，血流成河。名叫格斯的男子（岩永洋昭 配音）凭藉一己之力在佣兵中打出名号，也引起另一个强大男人的观注。不久，他遭遇了令人闻风丧胆的佣兵部队“鹰之团”及其具有超凡魅力和实力的领导者统治者格里菲斯（樱井孝宏 配音）。格斯在挑战格里菲斯的战斗中败北，此后加入鹰之团，成为其中最为骁勇的战将。在连番激烈的战斗中，他与战友建立起坚不可摧的友情，更得到格里菲斯的赏识，后者甚至不顾自己的安全拯救被恶魔佐德折磨的格斯。但随着鹰之团成为米特兰王国的正规军，以及格里菲斯被封为贵族，淳朴的战友之情开始蒙上阴谋的鬼影……本片根据漫画家三浦健太郎的同名原作改编，为“黄金时代”三部曲第一部，其他两部为《多尔多雷攻略》、《降临》。©豆瓣', '岩永洋昭', '洼冈俊之', 8.5, 16543, 'tt2210479', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1462854862.jpg', 0.3, 1.1, 13.8, 43.7, 41.1, '0.179761,0.001436,-0.624327,0.706119,0.161839,0.035907,0.587970,0.040502,-0.445587,-0.280805,0.359189,0.752108,-0.076341,-0.032377,0.509679,-0.351326,-0.154631,-0.719649,-0.313364,0.065403,-0.017848,-0.373464,-0.548745,-0.110942,-0.301287,-0.650305,1.064188,0.134791,-0.417943,0.319706,0.163516,0.364639,-0.080020,0.148322,0.045972,0.130514,0.071533,-0.285560,-0.440933,0.256734,-0.360655,-0.159644,-0.229118,0.260053,-0.370692,0.270227,0.469385,-0.559248,0.219932,-0.454309,0.497399,-0.314633,-0.178905,-0.001575,0.341565,0.128997,0.136696,0.237519,0.158482,0.122779,-0.142531,0.055423,-1.081034,-0.035899,0.273863,0.233882,-0.364540,0.437961,-0.090274,-0.160897,0.134852,0.087694,0.066906,0.326745,0.296007,0.232311,-0.156492,0.199572,-0.336339,-0.003139,0.749865,-0.082266,-0.457488,-0.223913,-0.104259,-0.499801,-0.095309,-0.689088,-0.353275,-0.191650,0.129908,0.028642,0.468047,0.670268,-0.795960,0.095525,-0.279645,-0.108985,-0.143012,-0.202591,-0.099131,-0.788599,-0.329205,-0.325083,-0.138752,0.038951,0.323750,-0.361488,0.904536,-0.911491,-0.050580,0.335888,0.386014,-0.178991,0.315932,0.055562,0.187585,-0.111801,-0.312832,0.393634,0.226992,0.017221,0.117854,0.119407,-0.208640,-0.155835,-0.131701,0.429158', '26667010', '25880986', '27602116', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5308265', '西游降魔篇', '喜剧', '大唐年间妖魔横行，一小渔村因为饱受鱼妖之害请来道士（冯勉恒 饰）除妖，年轻驱魔人陈玄奘（文章 饰）前来帮忙却被误认为骗子，幸亏职业赏金驱魔人段小姐（舒淇 饰）帮助玄奘制服了鱼妖真身（李尚正 饰）。二人又在高家庄为制服猪妖猪刚鬣（陈炳强 饰） 而再次相遇，这次除妖没有成功 ，但是段小姐却对玄奘二见钟情。玄奘求助师父，得知除妖的办法是去找被压在五指山下的孙悟空（黄渤 饰）帮忙，于是他准备前往五指山，途中又遇到段小姐和手下五煞，段小姐连蒙带哄想与玄奘在一起却屡次遭拒，在四妹（周秀娜 饰）调教下想变得更有女人味却适得其反。二人决裂后玄奘独自上路，与此同时降魔师（释延能 饰）、天残脚（张超理 饰）、空虚公子（罗志祥 饰）也一同前往除妖。经过千辛万苦玄奘终于找到孙悟空，段小姐又再次出现并交给玄奘一件重要的东西，猪妖终于被降服，但是更大的危机又出现在了玄奘面前，原来孙悟空与传闻中不一样，玄奘的除魔之路能否继续？本片是周星驰多年之后的力作，演员阵容延续了以往，除了主演外，还请了诸如卢正雨、杨迪等网络红人加盟。', '文章', '周星驰', 7.2, 594518, 'tt2017561', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1856385532.jpg', 2, 7.1, 37.1, 38.6, 15.2, '-0.101658,-0.087599,-0.444752,0.471437,0.121997,-0.464805,0.366113,-0.071738,-0.397952,-0.328174,0.219280,0.500751,-0.203816,0.131681,0.026151,-0.053596,-0.001119,-0.347382,0.162932,-0.137126,-0.124785,-0.148642,-0.302343,0.141748,-0.308697,-0.385977,0.446347,0.016741,-0.041481,0.426339,0.370300,0.046630,-0.416423,0.603088,-0.134112,0.157720,-0.076005,0.167733,-0.219882,0.120905,0.051462,-0.391094,-0.174437,0.022937,0.098974,0.054977,0.414519,-0.471190,-0.072593,-0.021335,0.075506,-0.196158,-0.017494,0.126178,0.474126,-0.140852,0.527651,0.257150,-0.084896,0.138857,0.009848,-0.162702,-0.273381,0.205070,0.184819,-0.061103,-0.672599,0.291240,0.020473,0.062081,0.136693,-0.540448,0.130298,0.218707,0.467373,0.263514,0.120465,-0.004364,-0.320895,0.177806,0.472091,0.050296,0.378788,0.217028,0.429036,-0.443848,0.161729,0.021693,0.074249,0.288258,0.342349,-0.129506,-0.190399,0.061276,-0.483984,-0.176631,-0.436857,0.238439,0.001249,-0.251015,0.148533,-0.534305,0.184704,-0.192714,0.218627,0.067390,0.600967,-0.054474,0.553962,-0.574327,0.235886,0.326201,0.115172,-0.454060,0.431980,0.035275,0.144447,-0.053669,-0.178033,-0.221409,0.123997,0.472271,0.374026,0.286314,