INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5316733', '命运化妆师', '爱情', '作为人体化妆师的敏秀（谢欣颖 饰）早已见过无数的人体，为死者化妆，送他们最后一程，让死者的家属得到心灵的慰藉，是敏秀工作的意义。但这次横在敏秀面前的是她的高中老师陈庭（隋棠 饰）。自己身边的人以一个冰冷的姿态出现让敏秀的内心出现波动，过去的记忆也伴随着而来。而陈庭的未婚夫，作为精神科医生的聂城夫（吴中天 饰）对于陈庭的死抱着深深的痛苦，希望借由敏秀来了解他所不知道的陈庭的过去。参与这趟回忆之旅的还有刑警郭咏明（张睿家 饰），他认为陈庭的死不是认定的那么简单。随着三人接触的加深，三人间的关系发生了微妙的变化，原来所有的故事才刚刚开始……本片获得第十三届台北电影节最佳女演员（谢新颖）。©豆瓣', '隋棠', '连奕琦', 6.9, 6885, 'tt1854552', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1021782793.jpg', 1.5, 8.8, 44.3, 32.4, 13, '0.442253,-0.026389,-0.685970,0.683859,-0.072442,-0.263213,0.888364,-0.073503,-0.520425,-0.271959,0.325315,0.594930,-0.123609,0.134077,0.331028,-0.011956,-0.017084,-0.699773,-0.136728,0.012229,-0.475564,-0.580669,-0.238876,0.049186,-0.131412,-0.239720,0.598613,0.111871,-0.070325,0.783175,0.472543,0.298360,0.071012,0.473996,-0.076631,-0.037113,-0.249441,0.032584,-0.431552,0.133206,0.398321,-0.135295,-0.090629,0.268834,-0.214225,0.309289,0.656538,-0.105407,-0.229388,0.096342,0.589662,-0.290281,0.038327,0.069171,0.132878,0.262329,0.244676,0.264132,-0.277412,0.061428,0.065590,0.129514,-1.007669,-0.035199,0.259914,0.388886,-0.449914,0.384940,-0.097990,-0.194131,0.047466,-0.301979,0.329964,0.283102,0.218327,0.460132,-0.311313,-0.081723,-0.278643,0.153347,0.539983,-0.052480,-0.326437,0.424728,-0.348339,-0.454188,-0.199139,-0.208881,-0.267350,0.219142,-0.060941,0.214804,-0.258244,-0.013125,-0.444385,-0.093424,-0.045969,-0.190489,0.000359,-0.422652,-0.053971,-0.430167,-0.326017,-0.480867,-0.409987,-0.130700,0.152374,-0.520479,0.649153,-0.916046,0.285296,0.502808,0.213483,-0.478474,0.645585,0.162371,-0.029023,-0.297448,-0.318334,0.131727,-0.077820,0.225691,0.019271,0.474773,0.038263,-0.157082,-0.373804,0.414684', '1793491', '35144311', '3006892', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5317291', '西游记之大闹天宫', '动作', '魔界之王牛魔王（郭富城 饰）与玉帝（周润发 饰）为首的神界展开战斗，神界被毁，女娲（张梓琳 饰）化身晶石修补天庭，遗落下的一小颗晶石落到人间成了一只石猴，而牛魔王则战败被迫带着妻子铁扇公主（陈乔恩 饰）躲到了火焰山。若干年后石猴得到了菩提老祖（海一天 饰）的教导被赐名孙悟空（甄子丹 饰），孙悟空来到花果山自立为王，还抢走了东海龙王（刘桦 饰）的定海神针当武器。同时牛魔王立志东山再起，利用了孙悟空与青梅竹马的小狐狸精（夏梓桐 饰）的感情煽动孙悟空大闹天宫，又串通了二郎神（何润东 饰）一起破坏了南天门，孙悟空势在必得，天庭危在旦夕。©豆瓣', '甄子丹', '郑保瑞', 4.3, 139463, 'tt1717715', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2166490265.jpg', 29.8, 35, 26.9, 5.5, 2.8, '-0.086239,0.503056,-0.695584,0.790195,0.018643,-0.265463,0.323194,0.226796,-0.134767,0.084355,0.315963,0.628757,-0.398489,0.002883,-0.177032,0.051462,-0.046114,-0.365756,-0.083046,0.100786,-0.051791,0.271934,-0.531031,0.140015,-0.352953,-0.308859,0.766951,-0.215409,0.146143,0.138792,0.384309,0.159572,-0.251332,-0.070494,-0.235734,0.450760,-0.500598,0.324397,-0.032631,0.273230,-0.302678,-0.312038,0.151123,0.107694,-0.157148,0.240028,0.457544,-0.676837,0.136900,-0.675225,0.221280,-0.276058,-0.092626,0.069806,0.459668,0.100093,0.211212,0.074794,-0.298995,0.171383,0.570034,-0.282299,-0.127445,-0.084698,-0.002193,-0.010968,-0.212296,0.279320,0.136319,0.174917,0.036660,-0.305150,0.272988,0.376135,0.201315,0.236073,-0.184614,-0.187065,-0.502123,0.597897,0.211828,-0.372912,0.357503,0.076677,0.604019,-0.336764,-0.185189,-0.215129,-0.005217,-0.084613,0.781844,-0.083679,0.358611,0.341998,-0.698804,-0.584288,-0.358489,0.284262,-0.129408,-0.227909,0.095292,-0.380956,-0.043039,-0.209669,-0.148643,-0.018585,0.392624,0.166568,0.628739,-0.464364,0.216454,0.081153,0.083430,-0.511965,0.563696,-0.331494,0.066654,-0.455052,0.062792,0.372303,0.055507,0.236054,0.431335,0.145872,-0.084597,-0.009158,-0.266205,0.207499', '26290398', '2252594', '1302786', '3681613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5318665', '我爱HK 开心万岁', '剧情', '吴顺（梁家辉 饰）和托水龙（曾志伟 饰）原本是从小在屋村长大的一对好兄弟，可是三十年前，保管街坊所筹善款的托水龙却在筹款夜监守自盗，从此便杳无音信。时光荏苒，三十年后当做生意破产的吴顺托家带口的回到屋村后不久，托水龙意外出现。两人一起回忆往昔，感慨万千，吴顺心中的芥蒂也随之慢慢消除。吴顺对于阿龙所述自己多年来的离奇经历，只当是讲笑话。与吴顺青梅竹马的素贞（袁咏仪 饰）也回到了屋村，旧情人相见深夜裸身独处，被顺嫂（吴君如 饰）撞个正着的引发误会。不过两人很快冰释，一家人又合好如初。托水龙发起了“屋村活化计划”，让屋村的街坊们在大型超市、商场的夹缝里看到了生存的希望。可是，就在街坊们满怀信心的参与活化计划时，阿龙再次消失，领悟集团出现并要赶走众街坊。阿龙这些年到底遭遇了什么，屋村的街坊能否度过难关，阿龙会不会再次出现，所有问题的答案将在本片的结尾一一呈现。本片共邀请香港百位明星加盟，堪称继2010年《72家租客》之后港星的又一次“集结号”。', '曾志伟', '钟澍佳', 6.9, 40487, 'tt1845842', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2229857239.jpg', 1.3, 6.9, 45.3, 37.3, 9.3, '0.201381,-0.107297,-0.459973,0.224181,0.125806,-0.402722,0.631221,-0.002740,-0.573499,-0.188713,0.097571,0.656870,-0.439977,0.442727,0.110161,-0.221916,-0.181947,-0.648941,-0.021945,-0.192095,-0.158041,-0.316960,-0.004940,-0.086629,-0.129562,-0.187838,0.392746,0.196531,0.079046,0.455739,0.279886,0.038255,-0.363013,0.329276,-0.249554,0.209181,-0.082383,0.437570,-0.505980,0.007712,-0.149242,-0.331851,-0.218600,-0.124777,0.206367,0.107236,0.722136,-0.174133,-0.191348,0.145419,0.219840,-0.192782,0.024213,0.005888,0.399592,0.221595,0.225181,0.271048,-0.365648,-0.103679,-0.116613,-0.081254,-0.442125,0.152290,0.144152,0.025162,-0.644501,0.385580,0.128359,-0.110018,-0.071896,-0.256699,0.251179,0.570712,0.306795,0.288326,-0.196180,0.137783,-0.386088,0.177355,0.742009,-0.156246,-0.074268,0.392831,0.153223,-0.295023,-0.048536,0.217102,-0.143962,-0.010664,0.174121,0.149793,-0.145023,0.321019,-0.575123,-0.075699,-0.303693,-0.165655,0.228857,-0.298494,-0.048922,-0.588921,-0.252400,-0.219687,-0.219406,0.396082,0.167160,-0.003617,0.559077,-0.632126,0.274332,0.145826,0.308831,-0.460418,0.652731,0.008518,0.150172,-0.228048,0.014624,-0.037880,0.053651,0.322508,0.302761,0.223515,-0.100742,-0.138192,-0.283394,0.177662', '26687241', '11541282', '25721544', '1305364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5318669', '转山', '剧情', '本片改编自同名畅销书。台湾青年张书豪（张书豪 饰）在大四毕业时，遭遇了哥哥的亡故，正处在迷茫期的书豪意外发现了哥哥留下的骑行日志，这个不骑车的青年萌生了骑行滇藏线替哥哥完成未竟心愿的想法，在经历了女友的离去后，他义务反顾奔赴丽江。在路上，张书豪结识了来自云南的骑行者李晓川（李晓川 饰），并结伴前往拉萨。第五天，他们来到德钦，李晓川因无缘得见云雾中的梅里十三峰而沮丧不堪；第六天，他们住在盐井的藏民家中，书豪与淳朴的藏民依依惜别；第七天，他们在曲孜卡的山路艰难前行，李晓川意外坠崖重伤。冬季的滇藏线格外艰险，而剩下的路，张书豪必须独自前行……©豆瓣', '张书豪', '杜家毅', 7.9, 88377, 'tt2075232', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1264988566.jpg', 0.5, 2.7, 23.9, 47.2, 25.7, '0.275761,-0.155231,-0.646498,0.337451,0.202799,-0.537836,0.478639,0.210656,-0.361141,-0.166458,0.309522,0.725296,0.077945,0.491727,0.407847,-0.225337,-0.314586,-0.291631,0.168475,-0.345505,-0.165731,-0.358864,0.166172,0.200543,-0.019767,-0.291251,0.653103,0.363332,-0.032181,0.856433,0.014104,0.051755,-0.453473,0.354554,-0.207155,0.193608,-0.008182,-0.039694,-0.252308,0.110195,0.004031,-0.234534,-0.378361,-0.164666,0.039520,0.332205,0.898704,-0.068991,-0.304501,0.141604,0.217384,-0.320273,0.118063,0.038826,0.237827,0.118555,0.212188,0.121520,-0.081985,0.109039,-0.100407,-0.114057,-0.192894,0.394312,0.033265,0.275707,-0.799426,0.575788,-0.019106,-0.136038,0.300841,-0.621314,0.015985,0.465708,-0.042387,0.393079,-0.065823,0.315100,-0.353796,0.193864,0.657470,-0.121014,0.113014,0.317119,0.325217,-0.431710,0.289332,0.005284,-0.500070,0.129832,0.318490,0.113294,-0.177845,0.021386,-0.434472,0.247225,-0.335097,-0.061072,-0.253347,0.026695,-0.486815,-0.414467,0.192908,-0.399841,-0.062052,0.124818,0.009178,-0.132372,0.374287,-0.576569,0.246135,0.271068,0.224933,-0.242292,0.626749,0.010141,0.085892,-0.188194,0.041762,0.452024,-0.271236,0.674004,0.240838,0.157103,-0.321419,0.054874,-0.450933,0.323992', '1451563', '1299433', '5960606', '1296636');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5318758', '杀手乔', '惊悚', '22岁的毒贩克里斯（埃米尔·赫斯基 Emile Hirsch 饰）欠了一屁股债，高利贷主正威胁要追杀他。为保性命，他想到了唯一的办法，就是谋杀亲母阿黛尔以赚取高额保险，并联合了父亲、继母和妹妹多蒂（朱诺·坦普尔 Juno Temple 饰）一起瓜分这笔横财。然而克里斯不愿自己动手，遂瞄准了专业杀手乔（马修·麦康纳 Matthew McConaughey 饰），然而乔只做买卖不做慈善，筹不够钱不会动手。束手无策之时，克里斯只好先把妹妹暂时当“订金”交给乔。本以为万事办妥，只等坐收巨款的克里斯，却没想到事情竟往戏剧化的方向发展而去……本片曾获土星奖最佳独立电影、最佳男主角、最佳导演、最佳女配角、最佳编剧奖。©豆瓣', '马修·麦康纳', '威廉·弗莱德金', 6.6, 12617, 'tt1726669', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1585763181.jpg', 2.3, 10.5, 47.7, 31.8, 7.7, '-0.080990,-0.179031,-0.524670,0.447964,-0.126664,-0.527821,0.244147,0.204084,-0.101739,-0.406148,0.011415,0.708758,0.200488,-0.221202,0.190948,0.098435,-0.244002,-0.406963,-0.043213,-0.177914,-0.135206,-0.630171,-0.092011,-0.211307,-0.315498,0.159096,0.491593,0.011592,-0.030099,0.186622,0.565998,0.057516,0.125009,0.191390,0.160429,0.173231,0.009501,0.021030,-0.464116,0.530097,0.222994,-0.262062,-0.311485,0.267776,0.534428,0.472107,0.326613,-0.185814,0.023970,-0.100060,0.064836,-0.293639,0.071159,0.079173,-0.192692,-0.402248,0.487725,0.030596,-0.437131,0.095620,0.378038,-0.364297,-0.874066,0.264880,-0.138728,-0.293524,-0.666564,0.024092,-0.350951,0.381906,0.114525,-0.083807,0.201132,0.266184,0.360736,-0.074619,-0.233306,-0.122819,-0.414713,0.482718,0.463516,-0.103023,0.107855,0.445465,0.100893,-0.273968,0.015358,-0.349158,-0.281852,0.210854,0.456730,0.115185,0.185368,-0.140325,-0.056787,-0.263181,-0.288284,0.036222,0.010861,-0.328074,0.266997,-0.273207,-0.113415,0.116278,-0.203553,0.144171,0.116089,-0.363358,0.236448,-0.228547,0.017436,0.505486,0.221235,-0.938321,0.426609,0.121760,0.208840,-0.299797,-0.107609,-0.098220,0.306759,0.177821,0.255946,-0.430407,0.376164,-0.351056,0.392183,0.198689', '1302110', '26678784', '1304382', '3670447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5319819', '车手', '剧情', '本片主要讲述了一个以赛车为核心的纯正港产警匪故事。陈翔（余文乐 饰）是警队交通部精英“隐形车队”的新队员，血气方刚、嫉恶如仇的他驾驶伪装的警车，隐没在路上追缉目标。蒋薪（郭晓冬 饰）是专帮劫匪驾车逃亡的“车手”，他凭借一手“8000转，2迈”的直角原地悬浮漂移技术独霸车坛，出道以来未曾失手。而将退休的警察卢峰（黄秋生 饰）性格怯懦保守，作为陈翔的警队拍档，两人一起执行任务常常以互掐告终。在多年前与蒋薪的一次交手中，卢留下很深的心理阴影。这次，蒋薪重出江湖犯案，陈翔追进窄巷险些车毁人亡。为救陈翔，卢峰重驾“隐形战车”再战悍匪。一场惊心动魄、生死时速的警匪狂飙飞车大战一触即发。©豆瓣', '黄秋生', '郑保瑞', 6.1, 29914, 'tt1740002', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1587651062.jpg', 2.6, 17.1, 57.5, 18.9, 4, '0.168211,-0.134699,-0.433388,0.674064,0.001342,-0.196122,0.611363,-0.047136,-0.351219,-0.073252,0.676001,0.564256,-0.142442,-0.122473,0.300257,-0.428353,-0.040409,-0.585441,-0.383557,0.153245,-0.339163,-0.260140,-0.258557,0.031035,-0.160050,0.000877,0.857188,0.230069,-0.159914,0.564889,0.550790,0.181710,-0.468079,-0.058028,-0.000289,-0.171358,-0.033895,-0.061626,-0.339222,0.092891,-0.216078,-0.436007,-0.052642,-0.138189,-0.127540,0.390753,0.699906,0.082594,0.018119,-0.076940,0.200808,-0.474670,-0.235709,-0.394525,0.406486,0.171890,0.072101,-0.048738,0.121845,0.012228,-0.178011,0.202667,-0.596046,0.020141,-0.044868,-0.167241,-0.760048,0.312726,-0.186839,0.070657,0.095418,-0.105482,0.060853,0.166420,0.462553,-0.011695,0.060045,0.169433,-0.220872,0.303844,0.521694,-0.095039,-0.285978,0.160216,-0.035762,-0.305852,0.079658,-0.313240,-0.188521,-0.156701,0.383114,-0.255763,-0.038242,0.101789,-0.208325,0.200449,-0.321764,0.004219,-0.246331,-0.043465,-0.141176,-0.746721,0.124161,-0.333027,-0.003847,0.213214,-0.277980,-0.087262,0.230111,-0.646085,0.000285,0.330533,-0.071825,-0.403123,0.473854,-0.004271,0.143843,-0.353903,0.068233,0.128041,0.011988,0.258311,0.024257,0.367920,-0.216801,-0.088179,-0.360206,0.298796', '1294917', '10467125', '2369613', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5319835', '101次求婚', '爱情', '乐团的大提琴手叶薰（林志玲 饰）因为三年前的未婚夫许卓（高以翔 饰）因车祸缺席婚礼而受到伤害，三年来美丽高雅的她虽然身边追求者不断，自己却无法再爱上一个人。不期然的是，黄达（黄渤 饰），一个平凡的不能再平凡，在相亲路上饱受挫折的包工头闯入她的生活，打破了叶薰原本宁静的生活。二人因为一次黄达帮叶薰解围了一场演变成闹剧的相亲而相识，叶薰更是帮黄达要回了被拖欠许久的工程款。在一来一往的相处中，黄达逐渐被叶薰独特的气质吸引，不顾一切的展开了对叶薰的爱情攻势。而叶薰也在想方设法的回绝黄达的过程中对这个执着的为自己付出的男人渐生情愫。然而就在叶薰为黄达的真情所动时，消失了三年的许卓重新出现在了她的生活中，成了二人感情的最大障碍…该片改编自1991年的同名经典日剧《101次求婚》©豆瓣', '黄渤', '陈正道', 5.7, 188945, 'tt1674766', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1844760369.jpg', 5.9, 24.6, 51.6, 13.7, 4.2, '0.279222,0.193166,-0.622135,0.792689,-0.393806,-0.280608,0.961785,0.000072,-0.515452,-0.053001,0.141970,0.644926,-0.293120,0.338662,0.421435,-0.087831,0.208287,-0.963693,-0.030240,-0.222995,-0.305608,-0.447468,-0.014016,-0.169972,-0.240006,-0.137531,0.652111,0.239426,-0.031383,0.560450,0.440725,0.084108,-0.030411,0.676895,-0.118935,0.094507,-0.071796,0.174399,-0.189577,0.309588,0.095777,-0.648933,-0.205865,0.358225,-0.291183,0.339556,0.820140,-0.186573,-0.217365,-0.025354,0.626126,-0.405019,0.090183,0.070151,0.194528,-0.049948,0.221242,0.069442,-0.484118,0.085347,0.031888,-0.112918,-0.533469,0.148897,-0.125338,0.008153,-0.751231,0.845872,0.227424,0.092868,-0.177145,-0.111127,0.155258,0.322574,0.475008,0.336580,-0.454385,0.089750,-0.196187,0.371534,0.814715,0.039744,-0.272032,0.553858,-0.403125,-0.389547,-0.195993,-0.246413,-0.774895,-0.135344,0.281090,0.127481,-0.243192,0.119684,-0.708005,-0.032119,-0.131741,-0.128551,-0.078942,-0.334974,-0.126552,-0.416291,-0.428637,-0.672129,-0.275490,0.246307,-0.130388,-0.567255,0.595803,-0.866757,0.238586,0.429200,0.278313,-0.604254,0.610704,0.257247,0.050896,0.061189,0.033804,0.500352,-0.171664,0.074792,0.331688,0.486473,-0.087098,0.387388,-0.434931,0.696101', '25911595', '1301022', '3111650', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5320233', '李献计历险记', '爱情', '李献计（房祖名 饰）跟女友王倩（王子文 饰）分手之后，难以接受这个惨痛的现实，以至于重新回到了差时症的怪圈之中。他穿梭在自己的时空里，回忆着童年上学看课外书被老师罚站，对于父亲（姜武 饰）严厉批评的心不在焉，对于二叔（姚鲁 饰）精通电子维修的向往，对于视频游戏的痴迷，对于公司同事的冷漠厌恶，当然，还有对于他和女友恋爱的每个细节。他并不希望治愈差时症，因为他还对回到过去抱有幻想，甚至不惜卖肾、打造金属手臂来完成打通游戏的梦想，但是现实的残酷，却将他卷入了警察（白凯南 饰）、警察小殷（李响 饰）、马神医（范明 饰）、日本骗子（矢野浩二 饰）等各色人物的圈套之中……本片根据李阳2009年创作的著名网络动漫视频改编。©豆瓣', '房祖名', '郭帆', 6.4, 36462, 'tt2258443', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1199893304.jpg', 4.5, 14.8, 44.7, 27, 9, '0.237194,0.183282,-0.385829,0.512600,-0.030680,-0.237190,0.739484,-0.209052,-0.543422,-0.505720,-0.036714,0.286839,-0.251679,0.159081,0.110025,-0.098226,-0.381560,-0.741294,-0.109145,-0.043233,-0.387360,-0.415999,-0.195021,-0.233333,-0.235023,-0.120370,0.567898,0.106604,-0.261622,0.418385,0.230862,0.200968,-0.190559,0.378883,-0.067960,0.101345,-0.031600,0.212527,-0.429848,-0.005349,0.243407,-0.029812,0.114308,-0.028018,0.079433,0.170188,0.682708,-0.189792,-0.186527,0.126765,0.443716,-0.093761,-0.378189,0.073801,0.030544,0.268369,0.284788,0.021250,-0.061317,0.104860,-0.045515,-0.177724,-0.747626,-0.017844,0.221026,0.137075,-0.259268,0.407509,-0.312818,0.154656,-0.002335,-0.249113,0.067243,-0.048272,0.648489,0.571295,-0.161523,0.146549,-0.206652,0.549374,0.169355,0.126321,-0.176704,0.283593,-0.286035,-0.263601,-0.115745,-0.158500,-0.541306,0.279162,0.274368,-0.128864,-0.087056,0.187600,-0.509538,-0.083704,0.109094,-0.276309,0.145223,-0.390954,-0.113817,-0.494018,-0.091708,-0.415294,-0.287677,-0.017892,0.273432,-0.394240,0.665521,-0.822599,0.189505,0.293400,0.308057,-0.549487,0.625809,-0.031820,-0.043683,-0.505322,-0.147507,0.356003,0.087230,0.315122,0.100546,0.399102,-0.075184,-0.412876,-0.454983,0.435523', '4127270', '25880986', '6101834', '3033092');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5320600', '涉外大饭店', '剧情', '人生已至暮年的七位英国老人辗转前往印度斋浦尔度假。七人中，善解人意的伊芙琳（朱迪·丹奇 Judi Dench 饰）试图在丧夫后独立生活；患心脏疾病的大法官格雷厄姆（汤姆·威尔金森 Tom Wilkinson 饰）怀揣着无法启齿的秘密；道格拉斯（比尔·奈伊 Bill Nighy 饰）和琼希望能改善僵化的夫妻关系；老顽童诺曼和老来俏玛琪则时刻期盼着艳遇；至于穆瑞尔（玛吉·史密斯 Maggie Smith 饰），等待手术的她总是显得有几分冷漠刻薄。各怀心事的七人被异域风情广告吸引，不约而同下榻在玛丽戈德饭店。但是真实的饭店并不如广告宣扬的那般舒适，这趟印度心灵之旅也不似预想般尽如人意。在陌生的国度里，众人对余下的人生展开了新的思考，不希望抱憾终身的他们向着皆大欢喜的结局努力着。影片改编自英国女作家Deborah Moggach的小说《These Foolish Things》。', '玛吉·史密斯', '约翰·马登', 8, 36760, 'tt1412386', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1339873949.jpg', 0.3, 1.5, 21.5, 53.5, 23.2, '0.271105,0.038331,-0.641039,0.589102,0.160227,-0.269735,0.854877,0.346919,-0.388028,-0.115584,0.062405,0.676414,-0.154630,0.186302,0.329201,-0.007535,-0.465916,-0.485797,-0.226652,-0.042268,0.075029,-0.545837,-0.266063,-0.289963,-0.139515,-0.339821,0.372623,0.298131,-0.191323,0.430176,0.170757,0.366735,-0.194700,0.348764,-0.104771,-0.087355,0.081380,0.149340,-0.471225,0.281417,0.165376,0.000032,-0.155075,0.293377,-0.052216,0.269538,0.624370,-0.244888,-0.087329,0.183594,0.167321,0.102852,0.055122,0.264822,0.082357,-0.081169,0.152986,0.045145,-0.177725,0.050272,0.209007,-0.136979,-0.727680,0.001882,0.182755,0.521820,-0.314012,0.533214,-0.085855,0.069909,0.060856,-0.187120,0.064627,0.330108,0.373198,0.380222,0.120680,0.109408,-0.402766,0.331019,0.346059,0.224644,-0.377102,0.402510,-0.572499,-0.366286,-0.027681,-0.146517,-0.714486,-0.195328,0.385818,0.149843,-0.125418,0.315046,-0.380457,0.044707,-0.205048,-0.225063,-0.094051,-0.368519,0.001358,-0.882661,0.059250,-0.515624,-0.127120,0.022256,0.145520,-0.115003,0.759503,-0.744586,0.247666,0.568494,0.148953,-0.263540,0.612309,0.056389,0.157599,-0.217585,-0.127774,0.589323,-0.271388,0.049182,0.118008,0.443506,-0.236461,-0.042263,-0.527844,0.482079', '3811356', '3005387', '26611806', '2364001');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5322572', '马达加斯加企鹅：行动', '喜剧', '当Alex, Marty Gloria和Melman几个主角还在非洲悠闲度日（从《马达加斯加：逃往非洲》后），四只企鹅（首领Skipper, 智囊Kowalski, 最年轻的Private和最疯狂的Rico)已经回到了纽约中央动物园，并在此地执掌管理大权。与此同时他们还要执行各种秘密任务，时不时地他们就要从动物园逃出来执行任务。 正当这一队企鹅觉得自己已经运筹帷幄之际，新邻居——Julien，一只狐猴王搬来动物园。现在企鹅们必须为动物园首领的宝座与之展开角逐。四只肥嘟嘟、憨态可掬的企鹅简直喜爱到了无以复加的程度。这四只可爱的小家伙在动画片《马达加斯加》中作为配角出场，但是，它们的风头绝对盖过那四个言谈举止行为动作故作牵强滑稽状的狮子斑马河马和长颈鹿！你可以在这部影片的“附属产品”——《The Madagascar Penguins in a Christmas Caper》（中文译名：马达加斯加企鹅帮圣诞恶搞记）中欣赏到它们的精彩演出。', 'Tom McGrath', 'Nicholas Filippi', 8.3, 12873, 'tt1700493', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2577376709.jpg', 0.1, 0.8, 15.1, 51.9, 32.1, '0.156183,0.035301,-0.660297,0.631412,0.022078,-0.039767,0.605041,0.191847,-0.206496,0.028439,0.162174,0.763738,-0.246389,0.253023,0.211761,-0.114061,-0.181247,-0.461688,-0.384608,-0.033052,-0.002834,0.018757,-0.488251,-0.309486,0.094298,0.048162,0.766445,-0.113198,-0.156242,0.559023,0.371274,-0.016639,-0.407156,0.126941,-0.477567,-0.167794,0.103056,0.115518,0.169524,0.140336,-0.107487,-0.102487,-0.079315,0.162539,0.093289,0.131572,0.975578,-0.565556,-0.361849,-0.260428,0.128335,-0.278033,-0.104773,0.097488,0.487889,-0.248233,0.237957,-0.193963,0.099796,0.400297,-0.125877,-0.341932,-0.995458,-0.128994,-0.229834,0.378260,-0.520082,0.340703,-0.051462,0.188175,0.362286,-0.417382,0.069301,0.299727,-0.111932,0.594819,-0.030198,0.286780,-0.441506,0.121001,0.374062,-0.044051,-0.069961,0.357602,0.152343,-0.677698,-0.087579,-0.253941,-0.112649,-0.195207,0.314769,-0.096436,-0.225110,0.073490,-1.039250,0.116303,0.013418,-0.399063,-0.110943,-0.435365,0.081766,-0.829326,0.150501,-0.446824,0.009385,0.032849,0.296875,-0.023542,0.693732,-0.774071,0.127421,0.452606,0.078620,-0.379193,0.509793,0.098342,0.176454,-0.360703,-0.163106,-0.166985,0.274190,0.541702,0.151065,0.370449,0.027558,-0.540840,-0.770927,0.636955', '25774050', '1420088', '26290398', '26839466');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5322596', '超脱', '剧情', '亨利•巴赫特（艾德里安•布洛迪 Adrien Brody 饰）来到社区学校担任代课老师。学校因学生反叛、经营不善而濒临绝境，多丽丝（刘玉玲 饰）为首的一批教师备受煎熬。亨利的第一堂课就遭遇了顽劣学生的挑衅，但是被他巧妙地化解。他赢得了女教师萨沙（克里斯蒂娜•亨德里克斯 Christina Hendricks）的好感。同时，他的教学方式引起了同学们的兴趣，其中就包括因肥胖而苦闷的梅丽迪斯。她一直默默地承受着因体重带来的各种责骂与嘲笑。但是因为老师，她似乎又找到了一切的理由……但是，亨利其实内心也有很大的压力，他的爷爷处于弥留之际，他的母亲自杀阴影始终在脑海中萦绕。某天夜里，他在公车上黯然神伤，独自流泪。这情形被一个刚受到嫖客凌辱的雏妓艾瑞卡（萨米•盖尔 Sami Gayle 饰）看到了。她尾随他，希望获得他的帮助。他起初拒绝了她的要求，后来他还是把她带回了单身公寓……', '艾德里安·布洛迪', '托尼·凯耶', 9, 525515, 'tt1683526', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1305562621.jpg', 0.2, 0.7, 7.5, 33.3, 58.2, '0.410077,0.036001,-0.813517,0.494172,-0.156157,-0.324110,0.801116,0.260661,-0.551347,-0.297922,0.232528,0.527665,-0.159034,0.572632,0.200468,-0.027364,-0.111379,-0.466337,0.109150,0.052431,-0.134288,-0.375300,-0.043641,-0.399020,-0.184950,-0.446813,0.464643,0.050262,-0.169087,0.416281,0.261608,0.540732,0.400375,0.725855,-0.004858,0.193797,0.178820,-0.089431,0.290157,0.168593,0.286128,-0.403489,-0.136853,0.378367,-0.005135,0.519029,0.731766,-0.084598,-0.128492,0.108387,0.352850,-0.458689,0.099319,0.305784,0.177559,-0.028872,-0.008869,0.042796,-0.213670,0.053863,0.075308,0.102226,-0.485917,-0.131584,0.057299,0.112468,-0.575445,0.594409,-0.170559,0.018362,-0.027298,-0.153114,-0.031259,0.119934,0.117291,0.295228,-0.306986,-0.045191,-0.430476,0.136223,0.597268,-0.098685,-0.308869,0.061013,-0.595354,-0.422516,0.116094,-0.082248,-0.581359,-0.114024,0.322078,0.108521,-0.123033,0.083991,-0.436903,-0.099710,-0.385672,-0.173703,-0.238839,-0.427710,-0.023698,-0.494082,-0.060105,-0.204781,-0.408503,-0.107725,0.036257,-0.250236,0.653180,-0.817514,0.371267,0.737083,0.412311,-0.418984,0.602422,0.187625,0.090918,0.072762,-0.255167,0.449394,-0.035187,0.231656,0.301801,0.356700,-0.030131,-0.134405,-0.125135,0.606447', '3059036', 