INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5323380', '我们这样的人', '剧情', '和大部分这个时代的年轻人一样，经济上的不宽裕令山姆（克里斯·派恩 Chris Pine 饰）感到无处施展拳脚，就在一筹莫展之际，鲜少联系的父亲的过世给了他新的希望。原来，山姆的父亲是一位著名的唱片制作人，他的死意味着山姆即将得到他数量庞大的遗产。可是，令山姆无法理解的是，根据父亲的遗嘱，他必须分15万美金给他未曾谋面的姐姐弗兰基（伊丽莎白·班克斯 Elizabeth Banks 饰）。为了得到全部的遗产，山姆决定以假身份偷偷接近弗兰基以搜集不利于她的证据。没想到，在相处的过程中，弗兰基的善良和正直渐渐的感动了山姆，在弗兰基的身上，山姆找到了久违的亲人般的温暖。©豆瓣', '克里斯·派恩', '艾里克斯·库兹曼', 7.2, 5860, 'tt1716777', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1833766373.jpg', 0.5, 3.6, 41.2, 43.2, 11.5, '0.250447,0.198392,-1.018534,0.772484,-0.391545,-0.424694,0.557010,-0.032797,-0.539314,-0.276316,0.081812,0.864107,0.047647,0.331508,0.081752,0.228386,-0.052919,-0.602849,-0.227097,-0.183173,-0.306785,-0.736338,-0.518438,-0.195919,-0.262562,-0.433339,0.608290,0.074256,-0.058840,0.287349,0.193011,0.401491,0.288531,0.504872,-0.278191,-0.075826,0.030239,0.028324,-0.294707,0.178714,0.104755,-0.158872,0.096885,0.281207,0.006616,0.534121,0.527249,-0.267235,-0.168634,0.134815,0.456107,-0.055795,0.102245,0.108412,0.103510,-0.012038,0.175727,0.121576,-0.535314,-0.155090,0.112699,-0.028949,-1.125373,-0.091281,0.274599,0.179640,-0.674882,0.470680,-0.370295,-0.041313,0.212703,-0.516683,0.135573,0.284861,0.138615,0.515533,-0.120973,-0.058533,-0.474247,0.117195,0.744056,-0.097619,-0.299688,0.451399,-0.438104,-0.227829,-0.042232,-0.349984,-0.467046,0.086803,0.339961,0.248680,-0.179348,0.174054,-0.495177,-0.199286,-0.267824,-0.277468,0.104216,-0.439052,0.028851,-0.473891,-0.352744,-0.443210,-0.260377,-0.055181,0.186120,-0.507704,1.013247,-0.818304,0.224233,0.568954,0.190022,-0.432947,0.640869,0.156905,0.033699,-0.221502,-0.060981,0.187080,0.339881,0.093373,0.272356,0.144556,0.074874,-0.275631,-0.355270,0.644004', '30163500', '25932086', '1793491', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5323881', '伯尼', '剧情', '伯尼（杰克·布莱克 Jack Black 饰）是德州小镇迦太基的殡仪师，他专业技术过硬，为人厚道、慷慨、热心公益、在教堂担任领唱还参加社区剧团演出，赢得小镇所有人的欢心，但他始终单身，被人猜测要么奉承独身主义，要么是个基佬。镇上一位富商去世后，留下脾气古怪、被所有人讨厌的高龄寡妇玛佳丽（雪莉·麦克雷恩 Shirley MacLaine 饰）。伯尼本着“对每个家属赋以最真诚同情和善意”的原则，热心接近玛佳丽，很快赢得她的欢心，她负担起两人所有玩乐开销，让伯尼参与她的财产管理，甚至为他改动遗嘱。两年过去，人人都爱的伯尼几乎成了玛佳丽的私人所有物，她辞退所有用人，生活中的所有琐事都交予伯尼一手包办。好脾气的伯尼也有爆发的一天，而且是一步到位地结束了玛佳丽的性命，演着一出“玛佳丽中风了”的戏，伯尼撑着这个秘密，试图逃过法律制裁……本片根据发生在德州的一起真实事件改编。', '杰克·布莱克', '理查德·林克莱特', 7.2, 5956, 'tt1704573', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1655464413.jpg', 0.7, 3, 40, 46.4, 9.9, '0.112893,-0.034027,-0.687042,0.437693,-0.245136,-0.206649,0.402229,0.015364,-0.339861,-0.231743,0.128961,0.697342,-0.147325,0.082991,0.320188,0.079169,-0.150911,-0.610276,-0.237946,0.050863,-0.003308,-0.499643,0.119948,-0.438514,-0.410686,-0.485042,0.050477,-0.050170,0.085863,0.324702,0.709247,0.123441,0.053273,0.264537,0.004542,0.019064,0.077161,-0.261497,-0.193946,0.074054,-0.094378,-0.037529,-0.214073,0.037508,0.268314,0.319888,0.536552,-0.170659,-0.049180,0.215566,0.477872,-0.380696,-0.055469,0.095386,0.291283,-0.054552,0.040449,0.322077,-0.216537,0.182604,0.186603,-0.039586,-0.824447,-0.307870,0.149355,-0.031071,-0.613487,0.557703,0.014485,-0.056406,-0.073388,-0.186033,0.238634,-0.072766,-0.081489,0.228185,-0.030306,0.077314,-0.457781,0.401693,0.745936,0.024339,-0.362086,0.086137,-0.458403,-0.396592,0.118088,-0.559967,-0.499768,0.272098,0.165765,-0.330471,0.099567,0.267963,-0.447999,-0.069259,-0.129697,-0.302043,-0.021583,-0.526210,0.037670,-0.614980,-0.188782,-0.256363,-0.254182,-0.115688,0.076164,-0.218475,0.801096,-0.690534,0.043599,0.445607,0.219147,-0.755833,0.771065,0.194156,0.287283,-0.025918,-0.250968,0.160815,0.256545,0.143561,0.025189,0.097930,-0.059459,-0.344801,-0.288571,0.364518', '4301278', '26678784', '1877596', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5323911', '食人鱼3DD', '喜剧', '前一波的食人鱼攻击终于画上了终点，此时，科学家们惊恐的发现，搅得人们天翻地覆的食人鱼居然还是处在初级形态的幼崽，天知道等到它们长大之时，又会闹出什么乱子！上一次的惨剧给谢尔比（丹妮尔·帕娜贝克 Danielle Panabaker 饰）的心里留下了深深的阴影，当她得知叔叔要在某处建立大型的豪华水上乐园时，谢尔比感到了强烈的不安。果不其然，不靠谱的叔叔为了节省经费，直接引入了附近的湖水，就这样，一大波食人鱼也随之而来，对于它们来说，一场饕餮大餐即将开席。面对着惨叫哭号的人们，谢尔比内心强烈的正义感让她无法对此坐视不管，勇敢的她连同幸存的伙伴们展开了轰轰烈烈的救援活动。©豆瓣', '丹妮尔·帕娜贝克', '约翰·古拉格', 4.7, 15377, 'tt1714203', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1577132454.jpg', 20.9, 38.2, 31.2, 6.5, 3.2, '0.320335,0.076958,-0.752929,0.384944,0.322251,-0.216485,0.736528,0.033879,-0.449518,-0.148652,0.210188,0.360492,-0.287794,0.242069,0.158916,-0.237379,-0.160664,-0.376079,0.021953,-0.112534,-0.391566,-0.076989,-0.376077,-0.199823,-0.050042,-0.179634,0.262322,0.136040,-0.172661,0.409706,0.270504,0.337413,0.113265,0.503667,-0.013771,-0.075037,-0.062850,0.066670,-0.160221,-0.039131,-0.084991,-0.294019,-0.150174,0.115693,-0.001054,0.257018,0.571786,-0.479985,-0.250302,-0.060864,0.278090,-0.350533,0.113882,0.257937,0.141232,-0.080774,0.114558,-0.247896,-0.223419,-0.008179,0.156455,-0.060019,-0.554627,-0.120034,-0.080767,0.132435,-0.592158,0.212028,0.142013,0.033624,0.175407,-0.130287,0.165427,0.191704,-0.038357,0.458999,-0.247129,0.181942,-0.365174,-0.007730,0.815082,-0.004984,-0.373056,-0.019931,-0.159915,-0.390084,-0.024560,-0.375729,-0.259800,-0.079229,0.432413,0.340759,-0.328086,0.454777,-0.737615,0.040868,-0.377400,-0.427834,-0.152843,-0.139041,-0.146546,-0.524995,-0.053294,-0.212658,-0.116832,0.238359,0.005986,-0.129385,0.763141,-0.662001,0.345626,0.401376,0.027280,-0.300934,0.341519,0.135184,0.007180,0.003061,-0.060229,-0.023921,-0.126805,0.451265,0.291459,0.325362,0.008740,-0.090444,-0.148528,0.586541', '3005387', '2032339', '3626364', '5977789');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5323957', '安德的游戏', '动作', '并不遥远的未来，来自外星系的异星蜓入侵地球，造成超过一千万人死亡。危难时刻，勇敢的队长瑞克汉姆阻挡了侵略者扩张的步伐。利用这有限宝贵的时间，地球人致力寻找具有极高天赋的少年加以训练培养，以期他们能够成为挫败外星入侵者的领袖人物。身形瘦小、神色忧郁但目光无比坚定的安德·维京（阿沙·巴特菲尔德 Asa Butterfield 饰）正是这群少年中的一员，他也是国际舰队寄予厚望并重点培养的对象。经过数轮严苛的考评，安德的潜质得到战斗学校的指挥官格拉夫上校（哈里森·福特 Harrison Ford 饰）的肯定，他被上校带到了位于轨道空间站上的战斗学校，在全封闭的环境下，未来的英雄迎来新一轮的磨练……本片根据美国科幻小说作家奥森·斯科特·卡德（Orson Scott Card）的原作改编。©豆瓣', '阿萨·巴特菲尔德', '加文·胡德', 7.1, 186104, 'tt1731141', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2164556643.jpg', 1.5, 7.2, 40.3, 37.5, 13.6, '0.116129,-0.018062,-0.671917,0.768740,-0.084699,-0.158709,0.562861,-0.017642,-0.313064,-0.224527,0.393412,0.547058,0.235395,-0.100677,0.414580,0.040657,-0.420384,-0.427118,-0.207150,-0.222787,-0.179106,-0.578648,-0.438809,-0.260639,0.079277,-0.479184,1.021722,0.098583,-0.490552,0.359062,-0.135181,0.426609,0.197988,0.405858,-0.102001,-0.150933,0.419819,-0.403691,-0.183648,0.244037,-0.163949,0.101057,-0.116518,0.143759,-0.075511,0.289138,0.577171,-0.222994,-0.027554,-0.117499,0.338300,-0.362130,0.073829,-0.100780,0.471656,-0.034338,-0.078015,0.158806,0.238743,0.183975,-0.210508,-0.236890,-0.891692,-0.247823,0.013359,-0.007209,-0.516293,0.437183,-0.030724,-0.212510,0.100932,-0.132469,-0.073795,0.286261,0.370759,0.236149,-0.025490,0.181385,-0.304712,0.003243,0.391637,-0.074027,-0.794153,0.028150,-0.392038,-0.623008,-0.027909,-0.454766,-0.522682,-0.100611,0.372211,0.063389,0.120628,0.531032,-0.536677,0.337675,-0.412150,-0.422812,-0.005982,-0.327156,-0.042325,-0.876107,-0.219343,-0.475612,-0.333987,-0.121706,0.074199,-0.253633,0.880384,-0.689697,0.061283,0.702622,0.264431,-0.267015,0.443092,-0.014942,0.203736,-0.385911,-0.372635,0.432107,0.143017,0.547781,-0.219071,0.263441,0.081773,-0.158289,-0.205966,0.595295', '2369613', '25880986', '3861846', '2760