INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5323968', '环太平洋', '动作', '近未来，地球环境逐步恶化。神秘外星殖民者通过大洋底部的虫洞“缺口”将身形庞大、残冷迅猛、身藏剧毒的怪兽接连派往地球，有条不紊地实施着它们的殖民毁灭计划。为此，人类联手打造“贼鸥计划”，制造出与怪兽体型相当的机甲战士迎战，但随着怪兽渐次进化，机甲战士全面溃败，各国政要试图修筑偏于防守的“生命之墙”以阻挡侵略者的脚步，无奈很快遭遇挫折。在此危急关头，暗中仍推进“贼鸥计划”的斯特克·潘特考斯特将军（伊德瑞斯·艾尔巴 Idris Elba 饰）找回五年前曾遭受重大打击的“危险流浪者”驾驶员（查理·汉纳姆 Charlie Hunnam 饰），并通过严格选拔为他选择了新的搭档森麻子（菊地凛子 饰）。复活的“流浪者”即将与另外三台仅存的机甲战士迎战更强大的怪兽侵略者，同时寻找彻底扫除敌人的良机。苍茫的大海之上，人类保卫之战接连而起……©豆瓣', '查理·汉纳姆', '吉尔莫·德尔·托罗', 7.7, 440796, 'tt1663662', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2043625972.jpg', 0.9, 3.8, 27.9, 43.9, 23.5, '-0.188618,-0.004124,-0.451026,0.642499,0.298557,-0.051725,0.390615,-0.076687,-0.240679,-0.099549,0.445144,0.252515,0.235491,-0.479388,0.110577,-0.492914,-0.206647,-0.378896,-0.238613,0.212157,-0.336694,-0.202104,-0.582015,-0.440839,0.189589,-0.488138,0.946037,0.278813,-0.295168,0.265687,-0.308113,0.433712,-0.389268,0.210647,0.093427,-0.197771,0.071447,-0.370471,-0.401067,0.193469,-0.291155,-0.123969,0.087594,0.140196,-0.231809,0.305154,0.744562,-0.721122,0.017897,-0.568072,0.163504,-0.221809,0.134811,-0.046605,0.477267,0.099421,-0.092625,-0.186072,0.168788,0.029246,0.086876,-0.190480,-0.740375,-0.107008,-0.046739,-0.027248,-0.333043,0.282385,-0.146211,0.417841,0.233165,-0.169267,-0.150666,0.455136,0.338770,0.128187,-0.212551,0.211627,-0.349159,-0.154278,0.395652,-0.096117,-0.551129,-0.254338,-0.240845,-0.476593,-0.098440,-0.423308,-0.158015,-0.219953,0.467482,0.272877,0.065127,0.708534,-0.903290,0.158458,-0.555844,-0.105526,-0.069270,0.012202,-0.128492,-0.716120,0.140909,0.066360,-0.032948,0.294931,-0.112196,0.051044,0.508093,-0.607352,0.143903,0.633201,0.636585,-0.068991,0.144584,-0.399007,0.270837,-0.275436,-0.031475,0.332921,-0.078505,0.528336,0.219126,0.108938,0.005175,-0.138984,-0.163716,0.455319', '26759819', '2032666