INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5324813', '天际浩劫2', '动作', '影片设置于未来世界，讲述侦探马克(弗兰克·格里罗饰)的儿子被外星飞船吸走，而他需解救儿子，并对抗无时不在的外星生物。', '弗兰克·格里罗', '连姆·O·达诺', 5.3, 7241, 'tt1724970', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505141188.jpg', 8.7, 36.1, 41.9, 10.6, 2.7, '0.157111,0.116157,-0.611095,0.487634,-0.182045,-0.108502,0.702274,-0.161422,-0.355477,-0.163378,0.102207,0.511727,0.180897,-0.205381,0.524548,-0.061557,-0.049270,-0.079419,-0.081723,0.082575,-0.234062,-0.605907,-0.548791,-0.700216,0.127493,-0.841595,0.927135,-0.119073,-0.357820,-0.364435,-0.304588,0.587176,-0.322861,0.281228,0.006505,0.161201,0.033340,0.078139,-0.358742,0.199000,-0.274590,0.162351,0.207745,-0.021696,-0.475356,-0.132095,0.791780,-0.631325,0.288987,-0.811057,0.226419,-0.275463,0.282964,-0.198476,-0.035220,0.012590,-0.077212,0.237670,0.131573,0.061972,0.561594,0.021356,-0.631692,-0.277985,-0.065075,0.229262,-0.077020,0.110752,-0.430775,0.032547,-0.126440,-0.226067,-0.027052,0.234688,0.517011,0.447400,0.128169,-0.243255,-0.380830,0.092352,0.043851,-0.418246,-0.453825,0.638267,-0.454629,-0.269102,-0.370369,-0.296295,-0.834542,0.022420,0.267954,0.219048,-0.631109,0.819033,-0.455016,0.121697,-0.236608,-0.544386,0.196456,-0.531860,0.045325,-0.908860,-0.028017,0.071309,0.131875,-0.304433,0.377506,-0.250070,0.960251,-0.663362,0.104439,1.051376,0.305028,-0.472028,0.868117,0.173409,0.022412,-0.736946,0.300675,0.251208,0.225040,0.539826,-0.280673,0.098310,0.396785,0.102812,-0.296900,0.474402', '1302570', '2369613', '6772974', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5326539', '火影忍者疾风传剧场版：失落之塔', '动画', '为了追踪叛忍百足，五代目火影网手（胜生真沙子 配音）命令大和（小山力也 配音）率领小樱（中村千絵 配音）、漩涡鸣人（竹内顺子 配音）、佐井（日野聪 配音）等人前往楼兰。楼兰某处地下藏有蕴含巨大能量的龙脉查克拉，很久以前被第四代火影封印。而百足的目标则是解开封印，释放恐怖的力量。经过千钧一发的搏斗，鸣人变成孤身一人，他意外来到一座繁华的失落城市，在此遭到了傀儡部队的袭击，并得到神秘木叶忍者的救助。之后鸣人邂逅楼兰女王萨拉，而围绕这个美丽的女子，邪恶的阴谋正悄悄展开。时空错乱，旧日的影像浮现……本片根据漫画家岸本齐史的同名原著改编，是“疾风传”系列第四部剧场版。©豆瓣', '竹内顺子', '村田雅彦', 7, 10434, 'tt1703048', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2263727884.jpg', 1.9, 8.7, 44.5, 28.7, 16.1, '-0.095933,-0.100962,-0.374417,0.389898,0.218188,0.224077,0.546809,0.210806,-0.140310,-0.467541,0.445251,0.455114,-0.116401,-0.089818,0.110840,0.161909,-0.230988,-0.291009,-0.166935,-0.044174,-0.089821,-0.157331,-0.239126,-0.123826,0.125820,-0.500276,0.978843,0.221789,-0.258940,0.183417,0.041550,0.465476,-0.746259,0.198876,-0.076936,0.051602,-0.039648,-0.142571,0.151960,0.344116,-0.459209,-0.174090,0.055652,-0.005655,-0.280622,0.288441,0.682998,-0.237963,0.103105,-0.160378,0.382848,-0.231746,-0.244363,-0.025870,0.282779,0.171836,-0.075693,-0.112037,0.030091,-0.179165,-0.126737,-0.337666,-0.788223,-0.038578,0.036200,0.208580,0.010969,0.002565,0.066104,-0.226222,0.455254,-0.291128,-0.046373,-0.056452,0.466152,0.139533,-0.286553,0.498162,0.105987,-0.048862,0.143477,-0.474190,-0.424489,0.111057,0.071528,-0.390258,-0.379527,0.044596,-0.021638,0.046255,0.386063,0.316338,0.039146,0.301515,-0.717824,-0.102831,-0.288187,-0.129082,-0.089274,-0.013895,-0.398251,-0.806805,-0.304807,0.160151,-0.006841,0.056365,0.268611,-0.020158,0.536600,-0.611013,0.288355,0.670124,0.184308,-0.027516,0.238895,-0.086618,-0.160004,-0.358391,-0.032238,0.309532,0.138841,0.443532,0.082642,0.235600,0.148158,0.011139,-0.532839,0.275121', '2369613', '2051813', '3861846', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5327156', '被涂污的鸟', '剧情', '影片以一个小男孩的视角描写了东欧“二战”期间的悲惨景象。小男孩的父母把他送到乡下避难，但与他失去了联系。男孩开始在各个村庄之间流浪。因为他的黑头发、黑眼睛，村民认为他是吉卜赛人，会给村子带来不祥，以各种方式折磨他。他曾被埋在土里，只有脑袋露在外面，乌鸦将他啄得伤痕累累。他目睹人们在暴力、堕落和无知的牢固链环中彼此吞噬。当他躺在铁轨上，让火车从自己身上呼啸而过，他体会到的只有饱受凌辱却依然幸存的快乐。影片在黑白光影下呈现出绝美的视觉质感，一出战争浮生录在魔幻的视角下就此展开。', '彼得·科特拉尔', '瓦茨拉夫·马尔豪尔', 8.1, 10989, 'tt1667354', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2573100741.jpg', 0.7, 2.2, 16.9, 50.3, 29.9, '0.327522,0.222468,-0.846068,0.546020,-0.146599,0.120599,1.035443,0.105714,-0.472581,0.298885,0.498497,0.598238,-0.192219,0.421799,-0.047905,0.141790,-0.241423,-0.818252,-0.163605,0.142683,-0.458680,-0.171939,-0.300118,-0.208914,-0.071934,-0.440363,0.693259,0.225823,-0.450513,0.177447,0.054350,0.119470,-0.268813,0.324207,-0.595702,0.049987,-0.335023,-0.237733,-0.043648,0.121351,-0.108549,-0.554790,-0.065448,0.117803,-0.433302,0.269176,1.094052,-0.428068,-0.204513,0.080013,0.376793,-0.226068,-0.249272,0.324489,0.078345,-0.112108,0.170779,-0.028998,-0.042042,0.031052,0.187434,0.276718,-0.588347,0.023683,-0.156921,0.360231,-0.682574,0.654094,0.068320,-0.003404,0.208109,-0.442357,0.167760,-0.057469,-0.034125,0.494752,-0.176904,0.074023,-0.446239,0.278793,0.655089,-0.090657,-0.453226,0.356012,-0.474462,-0.305470,-0.180141,-0.306835,-0.362288,-0.186283,0.548457,-0.085325,-0.592175,0.342736,-0.668248,0.058143,-0.074678,-0.411997,-0.026826,-0.302143,-0.421797,-0.413485,-0.398878,-0.573131,-0.445699,0.187560,0.043308,-0.317231,0.661470,-0.684100,0.339077,0.702658,0.171117,-0.055965,0.790094,0.007700,-0.096744,0.215245,-0.032331,0.387124,0.136251,0.462252,0.250910,0.268721,-0.259756,0.387370,-0.654655,0.722256', '21619567', '1467779', '3534824', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5327188', '好景当前', '剧情', '高中生Sutter（迈尔斯·特勒 Miles Teller 饰）不学无术，爱泡妞、爱喝酒，同学都把他当笑话看。女朋友Cassidy甩了他和学生会主席在一起后，他不仅喝了很多酒，还醉驾，早上醒来时发现自己正躺在Aimee家的草坪上。Aimee（谢琳·伍德蕾 Shailene Woodley 饰）和Sutter不同，是一个认真读书的女孩，和妈妈还有继父住在一起，爱看科幻小说，没交过男朋友。原本八竿子打不着的两人竟产生了奇怪的交集。Sutter让Aimee帮她补习数学，Aimee欣然答应。两个人的感情迅速升温，共同分享着彼此的青春。然而毕业在即，Aimee就要去费城读书了；两个年青人也有着各自的家庭问题。他们将如何走向明天？©豆瓣', '迈尔斯·特勒', '詹姆斯·庞索特', 6.8, 8843, 'tt1714206', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2011726833.jpg', 1.1, 8, 49.5, 32.4, 8.9, '0.592231,-0.284860,-0.655025,0.298786,-0.341502,-0.604537,0.500475,0.421255,-0.286787,-0.035462,-0.264886,0.763441,-0.035868,0.551055,0.173906,-0.225127,-0.285176,-0.932827,0.064311,-0.046219,-0.240938,-0.633716,0.192625,-0.018822,-0.001975,-0.164423,0.202950,-0.501164,0.056626,0.587114,0.353269,-0.247249,-0.129622,0.606941,-0.363350,0.010135,0.031393,0.236153,-0.244936,0.173486,0.254775,-0.046817,-0.013395,-0.141076,0.233065,0.132671,0.627198,0.126685,-0.144117,-0.065001,0.179292,-0.094290,-0.170934,0.167714,0.240424,0.037106,0.283586,0.053845,0.043114,0.099217,0.074160,0.041581,-0.173307,0.026625,0.103590,0.059501,-0.690138,0.966691,0.095489,-0.365007,0.269987,-0.209281,0.229286,0.466430,0.008506,0.531602,-0.002751,0.137613,-0.560562,0.202235,0.668506,0.188798,0.157664,0.527943,-0.031991,-0.103842,0.026420,0.040623,-0.398019,-0.060247,0.029777,-0.147374,-0.121913,-0.128400,-0.713819,0.229880,0.188866,0.019945,0.126266,-0.614018,0.029000,-0.386822,-0.090626,-0.279369,-0.359333,0.166286,0.117688,-0.357909,0.842943,-0.761778,0.148717,0.425737,0.465580,-0.447329,1.004384,0.386445,-0.118461,-0.229233,0.013455,-0.087464,0.015070,0.149310,0.067950,0.543789,0.073264,0.105385,-0.465921,0.310150', '3212120', '1308609', '1915403', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5327189', '伦敦一家人', '剧情', '英国手绘动画电影，改编自Raymond Briggs以其父母真实人生为故事所绘的获奖和畅销绘本，讲述Raymond Briggs的父母，一对普通英国夫妇从1928年初遇相爱到1971年相继离世的故事，日子随男主人的发际线一起消逝，一生平淡无奇但相守终生温情动人，同时也是一部英国编年史，期间穿插着不少的历史事件。', '卢克·崔德威', '罗杰·梅因伍德', 8.9, 74347, 'tt1725969', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2421801088.jpg', 0.1, 0.3, 7.5, 37.9, 54.2, '-0.017185,-0.206606,-0.383683,0.842475,0.509759,-0.270403,0.562947,-0.125637,-0.571352,-0.253202,-0.089047,0.887074,-0.288408,0.232764,0.135427,-0.120388,-0.205824,-0.687111,0.283782,-0.234698,-0.134816,-0.281077,0.053349,-0.163512,-0.248162,-0.425771,0.718022,0.287520,0.127258,0.975549,0.121724,0.179107,-0.666078,-0.352346,-0.392654,0.060787,-0.037862,0.604526,-0.804250,-0.098328,-0.086213,-0.173597,-0.190054,-0.400549,-0.353787,-0.039085,0.927273,-0.000758,-0.054174,0.229970,0.864920,-0.182885,-0.369513,-0.152478,0.437551,0.574592,0.405504,0.690610,-0.280492,-0.169939,-0.218411,-0.152172,-0.519997,-0.078120,0.187977,0.169266,-0.386734,0.474266,-0.017413,-0.058988,0.196610,-0.239459,0.353793,0.205235,0.608739,0.580056,0.150931,0.229073,-0.292735,0.784049,1.002983,-0.066045,-0.274035,0.657176,-0.320952,-0.180358,-0.172073,-0.434187,-0.564674,0.585608,-0.054777,-0.106422,-0.067911,0.524100,-0.498759,0.035506,-0.202315,-0.200276,0.480958,-0.376383,-0.154768,-0.586622,-0.411826,-0.671256,-0.245943,-0.017464,0.286793,-0.416326,1.095372,-0.271677,0.438479,0.246451,-0.122635,-0.442299,1.092530,0.365733,0.255097,-0.262203,0.407496,0.623746,-0.030782,-0.455046,-0.250002,-0.134603,-0.110111,0.210393,-0.524972,0.520300', '22265121', '3811356', '26321184', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5327216', '爱情避风港', '剧情', '对于南港的居民们来说，凯蒂（朱莉安·浩夫 Julianne Hough 饰）的到来是一件大事，尽管这个年轻漂亮的姑娘彬彬有礼行为无可指摘，但有关她的猜测和质疑从未停歇。对于凯蒂来说，自由又宁静的南港是疗伤的好地方。可是，一个人无论逃得多远，都无法逃脱他的过去，凯蒂也是如此，她越想忘记曾经发生的可怕的一切，就越是被这段记忆所困扰，所以她明白，南港并不是久留之地。在南港，凯蒂结识了英俊帅气的青年艾利克斯（乔什·杜哈明 Josh Duhamel 饰），后者的温柔关怀动摇了凯蒂离开的决心，在日积月累的柔情陪伴之下，两个年轻人之间的距离越来越近。艾利克斯的出现能够改变凯蒂的命运吗？©豆瓣', '乔什·杜哈明', '拉斯·霍尔斯道姆', 6.6, 5662, 'tt1702439', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1753125939.jpg', 1.5, 10.6, 51.5, 28, 8.4, '0.758234,-0.004315,-0.781251,0.528206,-0.030000,-0.025047,0.851909,-0.233221,-0.582115,-0.560434,0.201862,0.564523,-0.137979,0.099688,0.109003,0.087276,0.018313,-0.488701,0.148336,-0.408633,-0.133527,-0.638257,-0.364524,-0.138649,-0.364071,-0.330996,0.597362,0.146070,-0.097660,0.441911,0.318316,0.238119,0.249951,0.709242,-0.128764,-0.117577,-0.214382,-0.013011,-0.326146,0.130044,0.228453,-0.140530,-0.086065,0.530658,-0.009857,0.273635,0.382277,-0.335419,-0.491442,0.248818,0.374722,-0.322675,0.107873,0.212631,0.276405,-0.275479,-0.087466,0.204827,-0.359921,-0.182348,0.158789,0.086441,-0.644345,0.110736,0.040790,0.409819,-0.579963,0.227971,0.063663,-0.333873,0.095382,-0.429808,0.192129,0.285303,0.279704,0.279407,-0.191200,0.007469,-0.495556,-0.076371,0.971368,0.217726,-0.418858,0.490481,-0.573295,-0.499917,-0.361076,-0.243009,-0.794179,0.186658,-0.134740,0.310964,-0.156335,0.397182,-0.220197,0.055093,-0.336895,-0.034524,-0.143801,-0.665600,-0.061292,-0.445018,-0.321698,-0.656540,-0.525039,0.153277,0.003948,-0.460603,0.654244,-0.936844,0.223308,0.594453,0.289392,-0.598611,0.643809,0.305491,0.056299,-0.083313,-0.193707,0.745333,-0.042191,-0.009168,-0.149822,0.397027,0.059828,-0.240879,-0.280845,0.547853', '1296370', '25721544', '4275444', '3059036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5327217', '忽然七日', '剧情', '萝伦奥立佛同名畅销小说改编。莎曼珊金斯顿(柔伊德区 饰演)在2月12日晚上发生意外，她感觉自己将永无止尽地坠落，但一个声响打断沉默，她醒过来了，闹钟已经响了二十分钟。现在是早上六点五十分，2月12日。意外过后，莎曼珊发现自己不断回到这一天，而她每一个不同的决定和选择，竟然都有深远的影响。她逐渐明白，自己仿佛肩负着某个使命，必须完成某些事、改变某些人的生命，也许，她一次又一次回到这一天，为的并不是要救自己，而是另一个人……', '佐伊·达奇', '莱·拉索-扬', 6.6, 11201, 'tt1691916', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2398644395.jpg', 2.2, 12.6, 47.6, 27.5, 10.1, '-0.035538,0.275012,-0.788335,0.457327,-0.074008,-0.269335,0.656263,0.064947,-0.463124,-0.484108,0.055044,0.717667,-0.415145,0.246203,0.222350,-0.031119,-0.440733,-0.703908,0.286466,-0.371427,-0.507681,-0.403237,0.269400,-0.176768,0.264376,-0.164640,0.438337,0.145215,-0.031720,0.400128,0.001068,0.151011,0.209998,0.879954,0.040684,0.113766,-0.316487,-0.112352,0.112178,0.273374,0.190227,-0.093263,-0.177656,0.392768,-0.133256,0.675871,0.463240,-0.387672,-0.457462,-0.259572,0.640414,-0.389317,-0.437326,-0.015612,0.263832,0.006289,0.101731,0.320612,-0.377144,-0.207341,-0.071242,-0.045325,-0.561315,0.114895,-0.176264,0.104898,-0.526947,0.394191,-0.110592,0.157421,-0.088569,-0.230918,0.210684,0.681565,0.053919,0.480045,-0.418129,-0.180689,-0.493897,-0.074462,0.976693,-0.150416,-0.252189,0.754773,0.271494,-0.465034,0.003138,0.037678,-0.198954,0.143343,0.123074,0.371294,-0.180662,-0.156635,-0.306916,0.104057,-0.354413,-0.376424,-0.146419,-0.622237,-0.157816,-0.322295,0.115601,-0.178984,-0.265754,0.177534,-0.087573,-0.481655,0.557107,-0.734764,0.341682,0.743688,0.276144,-0.418984,0.457092,0.048481,0.171028,-0.231062,0.228053,0.448280,-0.371178,0.199705,0.068404,0.146016,-0.002487,0.238009,-0.490581,0.437113', '1292064', '26718282', '2055699', '1293142');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5327224', '他们最好的', '剧情', '1940年的英国战争不断，每天都有敌军的空袭轰炸，但比满目疮痍伦敦更残破的是人民绝望的心，面对未知的生命无常，电影成了唯一的心灵慰藉。资讯局电影部想要提升国家士气和民心，开始拍摄政治宣传电影，为了增加电影中的女性观点，原本从事广告文案的凯瑟琳（杰玛·阿特登 饰）被邀请加入编剧小组，和主编巴克利（山姆·克拉弗林 饰）一起编写歌颂英国人在敦刻尔克行动中英勇事迹的剧本。大男人的巴克利遇上温柔的凯瑟琳，挖苦彼此的对白、斗嘴不断，但随着两人一起经历疯狂赶戏和剧本，默契和爱苗都悄悄滋长。然而战事持续恶化，电影拍摄也面临困境，凯瑟琳还要面对自己已婚的事实⋯⋯', '山姆·克拉弗林', '罗勒·莎菲', 7.7, 7907, 'tt1661275', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2493078663.jpg', 0.4, 2, 26.2, 52.9, 18.5, '-0.000571,-0.099289,-0.622754,0.569670,0.512892,0.020350,0.608548,0.070769,-0.350958,-0.113542,0.161914,0.366251,-0.402605,-0.069094,0.164389,-0.363991,-0.634364,-0.960559,-0.152062,0.339858,0.023516,-0.398994,-0.348034,-0.344181,-0.146549,-0.286563,0.720666,0.180479,-0.291035,0.404833,0.147646,0.220164,0.099274,0.372203,0.228401,-0.142793,0.093261,-0.124681,-0.521999,0.230393,0.287320,-0.019167,-0.245141,0.108774,0.055956,0.298628,0.624258,-0.080236,-0.035462,-0.227474,0.535338,-0.188866,-0.000571,0.091386,0.200168,0.373000,0.462614,0.094387,0.128703,0.048735,-0.107835,-0.271305,-0.743458,0.245412,0.077687,0.178972,-0.135798,0.297302,-0.190759,0.300804,0.260891,-0.184906,0.101475,0.375802,0.763949,0.331363,-0.397008,-0.192304,-0.416655,0.216676,0.568883,0.139297,-0.282328,0.315159,-0.417980,-0.293172,-0.180697,-0.357478,-0.494533,0.108454,-0.040846,0.027107,-0.014692,0.648092,-0.698072,0.235253,-0.056826,-0.493327,0.025308,-0.441026,0.044561,-1.067862,-0.413956,-0.441182,-0.164593,-0.034334,0.112065,-0.260202,1.075246,-0.525921,0.031817,0.581968,0.439923,-0.608848,0.623505,0.227353,-0.051099,-0.115988,0.020744,0.336345,-0.280311,0.050544,0.013264,0.055772,-0.121946,-0.067477,-0.268237,0.564820', '3318306', '5403927', '25863940', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5327268', '荒野猎人', '剧情', '休·格拉斯（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）是一名皮草猎人，在一次打猎途中被一头熊殴打成重伤后被同行的乘船船长安德鲁·亨利（多姆纳尔·格里森 Domhnall Gleeson 饰）救下，船长雇佣了两个人约翰·菲茨杰拉德（汤姆·哈迪 Tom Hardy 饰）和吉姆·布里杰（威尔·保尔特 Will Poulter 饰）来照顾他。约翰·菲茨杰拉德根本无心照顾格拉斯，一心只想着将格拉斯的财产占为己有，于是残忍的杀害了格拉斯的儿子，并说服吉姆·布里杰将格拉斯抛弃在荒野等死。两人原以为格拉斯就会这样离世，但格拉斯凭借坚强的毅力在野性的蛮荒之地穿行了好几个月，终于回到了安全地带并开始了复仇计划。影片根据迈克尔·庞克同名长篇小说改编。©豆瓣', '莱昂纳多·迪卡普里奥', '亚历杭德罗·冈萨雷斯·伊纳里图', 8, 399070, 'tt1663202', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2279945831.jpg', 0.3, 1.7, 21.3, 50.5, 26.2, '0.326981,-0.287784,-0.514326,0.089066,-0.071360,-0.582010,0.538812,0.254209,-0.407635,-0.102383,0.148227,0.875320,0.072334,0.118188,0.413166,0.297679,-0.764578,-0.283202,0.248029,-0.118764,0.049382,-0.766391,-0.226160,-0.337647,0.277690,-0.658494,0.439730,-0.195365,0.101481,0.539952,0.134647,0.466676,0.230984,0.224712,-0.117998,0.310818,0.378347,-0.592112,-0.096819,0.397677,-0.144374,0.274906,-0.214826,0.036521,0.113830,0.365382,0.639118,-0.363462,0.244622,-0.226945,0.239390,-0.299172,0.303507,0.300864,0.108846,-0.487220,0.216557,0.507640,-0.226147,-0.006957,0.159009,-0.101874,-0.530207,0.272041,-0.151708,0.152175,-0.909602,0.127026,-0.450027,0.066784,0.141468,-0.358788,-0.042437,0.316192,0.058207,0.287862,0.026493,-0.025007,-0.441773,-0.193690,0.328839,-0.244673,-0.170556,-0.032561,0.079321,-0.200065,0.018962,-0.151790,-0.311726,-0.339882,0.712531,-0.076089,-0.123874,0.288734,-0.490581,-0.359280,-0.750746,-0.183624,0.038267,-0.218253,-0.174644,-0.605373,0.189525,0.062293,-0.291438,-0.158170,0.114399,-0.104525,0.246136,-0.442044,0.532138,0.548046,0.145341,-0.281244,0.266092,0.107862,0.365115,0.114469,0.041249,0.676544,0.459522,0.081922,0.333412,0.497812,0.446001,-0.148834,-0.043678,0.588829', '1292269', '2010975', '1309069', '1418194');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5327463', '白雪公主与猎人', '动作', '很久很久以前，在一个美丽华贵的国度，善良而迷人的白雪公主（克里斯汀·斯图尔特 Kristen Stewart 饰）降生到这个世上。她用有让人欣羡的家境与童年，但是好景不长，他的母亲过早去世，祖国遭遇神秘的黑色军队袭击，更为绝望的是父王将偶然相遇的绝世美女拉文娜（查理兹· 塞隆 Charlize Theron 饰）迎为新的王后。拉文娜带来了难以想象的灾难，她狂暴与黑暗的欲望使她攫取了整个国家。在得知王后将要加害自己之时，白雪公主奋力从城堡逃脱躲入黑森林。不久，肩负着残酷使命的猎人（克里斯·海姆斯沃斯 Chris Hemsworth 饰）尾随而至……本片荣获2012年青年选择奖怒发冲冠奖（查理兹·塞隆）、最佳夏季电影女主角（克里斯汀·斯图尔特）、最佳夏季电影男主角（克里斯·海姆斯沃斯）。©豆瓣', '克里斯·海姆斯沃斯', '鲁伯特·桑德斯', 5.6, 69407, 'tt1735898', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1571501128.jpg', 5.4, 28.8, 51, 11.3, 3.6, '-0.017012,0.309281,-0.614584,0.640362,-0.000967,-0.071585,0.893099,0.127300,-0.419493,-0.294224,0.364221,0.938008,-0.179182,0.126325,0.329748,0.268541,-0.273454,-0.531424,0.041835,-0.231746,-0.188344,-0.110057,-0.340995,-0.153459,0.138796,-0.680254,0.697308,0.033525,-0.157750,0.400396,0.348924,0.426285,-0.084782,0.297381,-0.002563,0.001007,0.066375,-0.052108,-0.226225,0.383969,-0.164203,-0.361758,-0.290224,0.351461,-0.181810,0.176496,0.709583,-0.439603,-0.033375,-0.284147,0.607170,-0.378047,0.041241,0.153706,0.110693,-0.296260,-0.070651,0.140591,0.047536,-0.167455,0.160719,-0.376457,-0.725479,0.281727,-0.068379,0.189675,-0.414043,0.245136,-0.152994,0.070443,0.364173,-0.273112,0.137070,0.190971,0.123909,0.295697,-0.062734,0.065109,-0.310022,0.507127,0.617710,-0.097549,-0.403145,0.317565,-0.403841,-0.389444,-0.029024,-0.243373,-0.836141,0.137418,0.574931,-0.020833,0.059624,0.526871,-0.569032,-0.121485,-0.413437,-0.104216,0.062079,-0.156754,-0.236516,-0.576946,-0.285366,-0.234002,-0.241662,-0.039654,-0.009708,-0.273272,0.643211,-0.659861,0.488837,0.804305,0.173563,-0.265162,0.517163,-0.183838,0.038988,-0.147850,-0.059353,0.798673,0.125776,-0.143546,-0.076801,0.139676,-0.262946,0.209702,-0.380620,0.659778', '34890458', '1460341', '1296992', '382