INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5327474', '亚历山大和他最糟糕的一天', '喜剧', '《熊孩子亚历山大的糟心日》（Alexander and the Terrible, Horrible, No Good, Very Bad Day）根据同名青少年文学作品改编而来，该书曾入选美国教育协会推荐的“100本最佳童书”。该片由导演米古尔·阿塔执导，预计将于2014年10月10日在北美上映。', '史蒂夫·卡瑞尔', '米盖尔·阿尔特塔', 6.8, 7286, 'tt1698641', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2194255774.jpg', 0.9, 7.4, 52.4, 29.3, 10, '-0.379956,-0.411071,-0.348131,0.389411,0.479517,-0.373203,-0.356787,-0.158009,-0.611309,-0.228886,-0.262195,0.545908,-0.491765,0.112620,0.806764,-0.558090,-0.323674,-0.546791,-0.406582,-0.529851,0.294582,-0.486218,-0.249902,-0.298474,-0.115432,-0.560045,0.680832,-0.245594,-0.153529,0.339477,0.298585,0.130219,0.181551,-0.263067,-0.047053,0.038936,0.027250,-0.096595,-0.442383,0.666891,-0.131029,-0.225151,-0.339172,-0.617670,0.373233,0.130582,0.755030,-0.540765,0.054503,-0.419036,1.274127,-0.246915,-0.118250,-0.305393,0.339273,0.399789,0.304084,0.412060,-0.264249,0.163248,-0.040463,-1.156960,-0.428734,0.210827,-0.033490,-0.032736,-0.597563,0.357792,-0.367772,0.234149,0.230868,-0.358842,-0.103663,0.532494,0.230412,0.460497,-0.056663,0.243000,0.119523,0.895591,0.231963,-0.026110,-0.424454,-0.291826,0.254190,-0.582529,0.129353,-0.221515,-0.180921,0.390404,0.278871,-0.154464,-0.114419,0.282878,-0.435206,-0.170373,-0.157271,-0.598362,0.241307,-0.081977,0.289287,-1.050288,0.119293,0.153725,0.260377,-0.438781,0.740124,-0.232609,1.067754,-0.550422,0.770943,0.437186,0.477082,-0.378658,0.900163,0.152319,-0.034745,-0.157021,-0.017151,0.457528,0.040660,-0.032907,0.021596,0.450782,0.270596,-0.625376,0.011627,0.205921', '27121232', '30397916', '27167055', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5327655', '像男人一样思考', '喜剧', '几个渴望寻找真命天子的女人，几个一样在寻觅猎物的男人。这些人不期而遇，上演了几段关于爱情的闹剧。一开始，这群互相是朋友的男人还能在情爱关系中游刃有余，但是女人们很快就发现了自己的被动地位。为了改变这种情况，她们开始看书，用理论武器武装自己。这群女人看到是同一本书：《像男人一样思考，像女人一样做事》。在这本揭示男性心理的工具书的主导下，女人们在两性关系中获得了主导和主动的地位。随后，这群男人就在一起互吐苦水，什么柏拉图式的恋爱、什么距离产生美等等等等新鲜的玩意一起进入了他们的生活。突然有一天，他们恍然大悟，于是也找来那本书研习，希望能从中找到一些关于女性行为学的隐藏信息，好扭转局面，让自己在恋爱的关系中处于不败之地。', '梅根·古德', '蒂姆·斯托瑞', 6.8, 10222, 'tt1621045', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1570476817.jpg', 1.3, 7.4, 49.9, 32.4, 8.9, '0.630278,-0.143579,-0.679360,0.466962,-0.379639,0.030634,0.640198,-0.172947,-0.524899,-0.236305,0.204620,0.709226,-0.337930,0.254471,-0.019629,-0.200085,-0.387739,-0.962821,0.070754,-0.134987,-0.302694,-0.403206,-0.375753,-0.233277,-0.270488,-0.287895,0.640600,-0.081948,-0.398738,0.081699,0.309562,-0.064181,-0.077156,0.609242,-0.482060,-0.153549,-0.143865,-0.005203,-0.295717,0.204196,-0.028350,0.075770,-0.184090,0.119355,-0.053052,0.176085,0.712205,-0.450626,-0.298180,0.094280,0.289025,0.116620,-0.217771,0.274832,0.314532,-0.135771,0.239162,-0.103306,-0.054713,0.040581,-0.091592,0.130817,-0.726071,-0.200739,-0.120862,0.479343,-0.428394,0.164110,0.358685,-0.183082,0.158616,-0.141741,0.284922,0.311442,0.445697,0.415401,-0.143955,-0.235433,-0.522686,0.119847,0.771556,0.127863,-0.399698,0.583036,-0.225735,-0.269061,-0.303436,-0.002633,-0.317305,-0.270713,0.220205,-0.062273,-0.335665,0.259495,-0.793022,0.321989,0.268146,0.010956,0.124847,-0.702469,-0.001586,-0.522565,-0.249930,-0.373647,-0.309269,0.158115,0.146685,-0.626430,1.020556,-1.019898,0.044784,0.669013,0.339470,-0.751783,0.643616,0.112644,0.056833,-0.272564,-0.187890,0.119672,0.098465,0.068792,-0.102069,0.603755,0.082808,0.134983,-0.326444,0.533965', '3230462', '4301278', '4127270', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5330387', '青年马克思', '剧情', '1843年，君主专制下的欧洲饥荒肆虐、经济萧条，处处危机四伏。英国的工业革命改变了世界秩序，创造出新的无产阶级。秉持博爱共产理念，工人组织陆续成立。两名德国青年，马克思与恩格斯，将颠覆这些组织的乌托邦思想，改造他们的斗争及全世界的未来。马克思自大学毕业后，凭着犀利文笔与非凡思路迅速跃升《莱茵报》总编。然而因撰文抨击普鲁士王国被迫停刊，随后带妻子迁居巴黎。创办《德法年鉴》期间，马克思结识了家境富裕的恩格斯。恩格斯在英国曼彻斯特经营纺织工厂，拥有卓越手腕与经济知识。他的出现，于金钱、于学识，都大大支持了马克思的思想实践。尔后，两人受托起草「正义者同盟」规章，一同完成了经典政治文献《共产党宣言》。一位困苦拮据仍不改其志，一位含着金汤匙又满怀抱负。时代青年的聚首，即将让全世界风云变色！', '奥古斯特·迪赫', '哈乌·佩克', 6.6, 10459, 'tt1699518', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2521271645.jpg', 2.4, 12.5, 49.5, 26.3, 9.3, '0.015550,0.180416,-0.498463,0.577495,0.169023,-0.344756,-0.041702,0.145961,-0.387473,-0.246570,-0.007099,0.704350,0.095023,-0.029259,0.429491,-0.455960,-0.201696,-0.725859,-0.128746,0.124757,-0.053001,-0.444305,-0.353867,-0.301726,-0.597379,-0.261468,0.802683,0.211748,-0.487640,0.361987,-0.089292,0.393327,-0.052148,0.097700,-0.261226,-0.209443,0.290577,0.017162,-0.677649,-0.000483,-0.054038,-0.212923,-0.205595,0.007822,-0.189823,0.101543,0.289539,-0.048319,0.130030,-0.513247,0.725183,0.090883,-0.271485,0.130313,0.368967,0.410589,-0.181171,0.508745,0.089569,-0.281876,-0.043371,-0.372570,-0.428762,-0.333268,-0.024922,0.090109,-0.491307,0.472629,-0.080150,-0.017761,-0.257571,-0.143519,-0.100999,0.480575,0.358650,0.542402,0.189170,0.317203,-0.263345,0.461268,0.354370,0.013478,-0.647501,-0.141622,-0.499844,-0.376408,0.128102,-0.259916,-0.158936,-0.434039,0.049439,-0.169433,0.042799,0.601248,-0.814355,0.121889,-0.228696,-0.348251,0.415727,-0.112946,-0.006774,-0.684705,-0.312015,-0.344675,-0.230167,0.070443,0.286588,0.054813,1.071562,-0.625426,-0.012621,0.210159,0.405412,-0.613681,0.559169,-0.193741,0.267648,-0.189166,0.042025,0.414709,0.004783,0.229190,-0.120068,0.234438,0.058130,-0.058179,-0.103183,0.501428', '27602116', '25863940', '22265121', '10439358');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5332266', '恋之罪', '剧情', '在一处偏僻的住所里发生了骇人听闻的猎奇杀人事件，一具截成两段后又被砍掉手脚的女尸静静的散发出腐臭的气味，负责此案的女刑警吉田和子（水野美纪 饰）随即展开了调查，在此过程中，菊池泉（神乐坂惠 饰）和尾泽美津子（富樫真 饰）这两个神秘女人的身影渐渐浮出水面。作为著名小说家的妻子，菊池泉过着平静而又枯燥的生活，除了每天定时等先生回家外几乎无所事事。而美津子则是一所著名大学的副教授，在教育界和学术界享有着极高的声誉。这两个风马牛不相及的女人之间有着怎样的联系？和子也有着自己的秘密，表面上坚贞贤惠的她其实有着十分混乱的私生活，面对欲望逐渐扩大的欲望的黑洞，她要怎样才能够守住自己的底线？©豆瓣', '水野美纪', '园子温', 7, 17915, 'tt1743724', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2174526754.jpg', 1.8, 8.3, 42.1, 33.2, 14.6, '0.293520,0.008370,-0.836982,0.713356,0.006913,-0.110297,0.959951,0.290256,-0.491198,-0.306746,0.131425,0.606799,-0.075176,0.256298,0.051270,-0.038575,-0.167913,-0.698684,-0.299180,-0.366508,-0.255563,-0.403344,-0.362251,-0.047168,-0.026527,-0.127354,0.627631,0.167860,-0.207146,0.235087,0.313950,0.361358,-0.203491,0.388503,-0.189384,-0.265387,-0.053916,0.043767,-0.056767,0.094169,0.139034,-0.322496,0.062136,-0.060052,-0.161002,0.288905,0.779237,-0.267112,-0.348012,0.036881,0.463272,-0.219914,-0.096566,0.202458,0.393694,-0.047127,0.189685,0.204396,-0.366230,-0.119926,0.268555,-0.115916,-0.739805,-0.160414,0.095911,0.442526,-0.458771,0.546434,0.225212,-0.328329,0.117918,-0.134549,0.196026,0.292346,0.172965,0.351768,-0.246251,0.188204,-0.284784,-0.030120,0.435259,0.277528,-0.336352,0.249455,-0.450304,-0.379323,-0.122947,-0.318863,-0.254954,-0.359259,0.201115,0.172272,-0.123775,0.229847,-0.614073,0.216460,0.047859,-0.018752,-0.085200,-0.202176,-0.214316,-0.492599,-0.165479,-0.594658,-0.296193,0.066529,0.077338,-0.279625,0.622623,-0.772689,0.151682,0.448054,0.165303,-0.310608,0.488479,0.058642,0.094816,-0.100683,-0.290534,0.133412,0.139435,0.401079,0.034747,0.528557,-0.156690,-0.121140,-0.485849,0.484955', '21619567', '1467779', '24839498', '6021916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5332621', '我们约会吧', '剧情', '约会类电视节目《我们约会吧》收视率一路走低，眼看面临停播，制片人盛蓉（刘威葳 饰）决定孤注一掷，邀请话题人物参与节目录制以求翻身。珍妮（李菲儿 饰）调入《我们约会吧》，新人气盛接下了盛蓉的任务——邀请频频在八卦杂志亮相的富二代陆嘉森（王柏杰 饰）担任嘉宾。另一方面，珍妮的表姐顾迦（吴辰君 饰）痴守音乐人高梵（丹尼斯·吴 饰）十年，最近迫于家庭压力只得与各色人物相亲。盛蓉节目组的编导简晨为了歌手女友莎莎（曹苑 饰）事业发展，选择对外隐瞒了他们的恋情。新一期可能也是最后一期的《我们约会吧》将在情人节开始录制，围绕着剧组的几对年青人各自在思考真爱的意义……©豆瓣', '吴辰君', '周楠', 4.6, 7262, 'tt2473702', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p856015319.jpg', 25.1, 32.8, 33.5, 6.4, 2.3, '0.220803,-0.212515,-0.207049,0.296530,0.115965,0.161378,-0.094104,0.548671,-0.182250,-0.167930,0.293290,0.460368,-0.402799,0.091194,0.458963,-0.410187,-0.387151,-0.630347,0.320593,-0.039280,0.068488,-0.211473,0.204736,-0.135505,0.100654,0.105739,0.741089,-0.194662,-0.097382,0.428086,0.722787,-0.114293,-0.183664,0.212892,0.353861,-0.216476,0.381210,0.178121,-0.548914,0.441111,-0.084972,-0.295278,-0.023799,0.020387,0.370640,0.204062,0.666371,0.095976,0.062872,0.251001,0.435882,-0.193067,-0.067104,-0.120409,0.421049,0.326409,0.312534,0.412876,-0.042432,0.032775,-0.020279,-0.262561,-0.350180,0.344442,0.330151,0.252245,-0.316580,0.470596,-0.085889,-0.069842,-0.002102,-0.172183,0.076491,0.273960,0.414402,-0.017817,0.146717,0.251947,0.008788,0.785531,0.332630,0.044058,0.195818,0.259583,-0.033115,-0.307392,-0.247630,0.037248,-0.556681,0.029063,0.129352,-0.140853,-0.017756,0.057358,-0.540265,-0.149294,0.245533,-0.161830,0.175762,-0.442414,0.252378,-1.068485,0.108188,0.071157,0.102291,-0.148762,0.253339,-0.142877,0.710308,-0.601200,-0.162910,0.517428,0.300456,-0.763955,0.772399,0.295430,0.196624,-0.535485,0.123139,-0.117314,-0.435859,0.000486,-0.086543,0.021851,0.224048,-0.334918,-0.191603,0.064735', '24751811', '1322847', '3003137', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5337532', '无极限之危情速递', '喜剧', '青年吴极限（张翰 饰）是一名极限运动好手，每天从清晨开始，他就用出众的车技冲破一个个困难完成快递使命。然而这天，风驰电掣中的吴极限冲撞了小安（郑爽 饰）和风行子一干轮滑青年的表演，风行子大为光火，率众抢夺了吴极限运送的VIP包裹。包裹中的鹦鹉此刻与一宗商业争夺战联系到了一起，身手出众的工业间谍能让（释行宇 饰）为了抢夺这只隐藏着商业机密的鹦鹉不惜背叛组织。另一边，家境富裕的小安借吴极限上门讨要包裹之机离开了乏味的聚会，不料却与吴极限擦出了爱情火花，此时暗处的能让出面抢夺包裹。一场看似平常的快递任务，牵连出连场争夺……©豆瓣', '张翰', '傅华阳', 3.4, 9080, 'tt3729832', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1158427141.jpg', 65.1, 14.7, 10.5, 2.8, 7, '0.292292,0.429338,-0.566646,0.579315,-0.317065,-0.161994,0.458946,0.140978,-0.377649,-0.273904,0.131937,0.292707,-0.293094,0.041747,0.220379,-0.250501,0.163683,-0.606071,-0.210818,-0.020954,-0.445508,-0.293485,-0.427663,-0.268533,-0.307634,-0.129744,0.357991,0.299512,-0.477321,0.473860,0.497671,0.146806,-0.238078,0.500809,-0.134440,-0.326636,-0.083075,0.175007,0.018753,0.167031,-0.063419,-0.422506,0.195950,0.264156,0.098303,0.394129,0.582146,0.026852,0.290274,-0.322979,0.312166,-0.086395,0.009975,0.096118,0.334842,0.249779,-0.083789,-0.236571,-0.198553,0.029385,0.058234,-0.315796,-0.885104,-0.034192,0.354690,-0.188076,-0.553877,0.202462,-0.153102,0.025066,0.008063,-0.304314,-0.063623,0.269858,0.051351,0.313353,0.291991,0.155366,-0.661779,0.409563,0.693235,-0.219482,-0.088736,0.000626,-0.183615,-0.476417,-0.217423,-0.360222,-0.080022,-0.277313,0.518670,0.276959,0.196620,0.019689,-0.650329,0.022245,-0.100402,0.123765,0.021489,-0.108449,0.032487,-0.609551,0.058726,-0.538361,-0.124150,0.233178,0.061318,-0.159685,0.653607,-0.557017,-0.115529,0.361593,0.138339,-0.278813,0.624047,-0.156549,0.295022,-0.083597,0.056843,-0.172481,0.158787,0.525185,0.456128,0.411198,-0.158215,-0.104791,-0.243976,0.478085', '1793491', '30163500', '3318306', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5337555', '兔侠传奇', '喜剧', '皓月当空，诗情画意，一派美景背后却是江湖凶险。武林老盟主（濮存昕 配音）遭江湖败类熊天霸（张丰毅 配音）暗算，身染剧毒，命在旦夕。在危机时刻，老盟主得到卖炸糕的小贩兔二（范伟 配音）的救助，自知不久于人世的老盟主将毕生绝学传给兔二，嘱他前往京城虎啸武馆，将代表江湖至尊的令牌交给其女儿牡丹（闫妮 配音）。兔二信守诺言，忍受艰险一路来至虎啸武馆，此时熊天霸早已自立为武林盟主，霸占武馆，兔儿则稀里糊涂成为武馆厨房的杂役。另一方面，毫不知情的牡丹也和老盟主的徒弟两米（张一山 配音）返回京城，等待他们的将是一场震动江湖的正邪之战……©豆瓣', '范伟', '孙立军', 5.9, 6774, 'tt1876517', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1074438903.jpg', 13.4, 17.3, 41.6, 18.1, 9.7, '-0.141038,0.154682,-0.230656,0.329189,0.096119,0.027162,-0.038639,0.410236,-0.475584,-0.253621,0.515546,0.651339,0.116391,0.134532,0.161003,-0.233488,0.427084,-0.465358,-0.177260,-0.128383,0.210521,0.065119,-0.088476,0.067624,-0.209773,-0.104018,0.532358,0.184432,-0.359432,0.522731,0.408872,0.083337,-0.325531,0.095831,-0.280366,0.011366,0.110068,0.043494,-0.590189,-0.096707,-0.318603,-0.118249,-0.170398,-0.094606,-0.072756,-0.031705,0.375697,-0.043797,0.000647,-0.394669,0.340276,-0.148782,0.051200,-0.113313,0.495326,0.017756,0.123344,0.603938,-0.083819,-0.051794,-0.147155,-0.122103,-0.621559,0.001430,0.403750,0.151555,-0.302075,0.489878,-0.139065,-0.094818,-0.198780,-0.297081,0.066694,0.119500,0.136958,0.165326,0.018555,0.066797,-0.465742,0.275449,0.521768,-0.147171,0.205833,-0.149449,0.736919,-0.055284,0.371101,-0.621742,-0.331603,-0.017685,0.301480,-0.225300,0.061375,0.403125,-0.113862,-0.012930,-0.204889,-0.136829,0.253211,-0.165453,-0.294344,-0.562561,-0.044203,0.150983,0.110035,-0.305768,0.436911,0.147975,0.857824,-0.645917,0.216376,0.055669,-0.162103,-0.342731,0.556495,0.054286,0.282672,-0.221576,-0.231555,-0.088065,0.318651,0.614821,0.106077,0.088902,-0.328336,-0.189340,-0.212273,-0.145347', '27602116', '26266892', '3811356', '1438924');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5339081', '疯城记：万圣节特辑', '喜剧', 'Drew Aspinall超市员工,并且喜欢在废弃的建筑物里进行冒险.在Drew还很小的时候,当他在Kenchington护士的办公室瞎逛游时被抓住过,现在已经成人了,第一次的冒险吓得他灵魂出窍,第二次的冒险吓得他丢了小命.Phil Walker当地的金鱼碗节目的制作经理.当他发现了被遗弃的乌鸦岭医院的时候,Phil认为自己为节目Dale''s Overnight Ghost Hunts找见了很好的题材,他绝不会知道制作经理会是一个多么危险地工作.', '史蒂夫·佩姆伯顿', '马特·利普西', 8.8, 9683, 'tt1742968', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2508993106.jpg', 0.2, 0.6, 10.6, 37.9, 50.7, '0.243308,0.041404,-0.748772,0.411225,-0.393160,-0.241019,0.721971,0.304251,-0.489241,0.058487,0.346599,0.959395,-0.184447,0.349718,0.273003,0.305809,0.033288,-0.450296,-0.346330,-0.047158,-0.508165,-0.112708,-0.374163,-0.149830,-0.009334,-0.336968,0.447860,-0.017154,-0.338839,0.013868,0.090212,-0.152804,0.270718,0.659914,-0.217877,-0.056809,0.131917,0.006269,0.175214,0.197568,0.146809,-0.363229,-0.015074,0.345690,0.275370,0.398479,0.599292,-0.015270,-0.472664,0.033283,0.544782,-0.201462,0.009453,-0.115182,0.416397,-0.157074,0.358218,-0.085193,-0.288193,0.081449,0.094897,0.057408,-0.996298,-0.015649,0.089675,0.092948,-0.817867,0.348793,0.014520,0.341622,0.189421,-0.457996,0.300657,0.147758,0.086175,0.442303,-0.112782,-0.130009,-0.747828,0.431942,0.580445,-0.298900,0.023836,0.541223,-0.253406,-0.426604,0.017905,-0.159307,-0.418886,-0.015905,0.384936,-0.184580,-0.779765,-0.276694,-0.362028,-0.105136,-0.102306,-0.225454,-0.170551,-0.257587,-0.363386,-0.406709,0.160896,-0.258395,-0.373697,0.023089,-0.225170,-0.038740,0.491576,-0.678430,0.026481,0.989157,0.130927,-0.270799,0.970876,0.076655,-0.150470,-0.027346,0.053838,-0.154111,-0.019477,0.871107,0.491943,0.489697,0.241671,-0.657113,-0.665642,0.557516', '1308842', '27018354', '1949005', '30368448');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5343629', '秋之白华', '剧情', '独立新女性杨之华（董洁 饰）为追求新思想，离家来到聚集了众多进步青年的上海大学就读社会学，结识了蔡和森与其妻向警予，当时任上海大学社会学系主任的瞿秋白（窦骁 饰）声望卓著，杨之华从他的授课中感受到深沉的忧国之情。杨之华在家乡的丈夫沈剑龙不时赶赴上海探望，但日益加深的分歧令两人感到彼此已经疏远，杨之华在与瞿秋白的接触中愈发欣赏后者的人格魅力与学识。不久，瞿秋白妻子病重亡故，杨之华亦通过向警予入党，在父亲抵沪探望之际，杨之华提出了离婚的打算，但在革命斗争形势严峻的局势下，杨之华没有向瞿秋白表白的机会。不久瞿秋白迫于形势辞职，陪杨之华返乡面见沈剑龙……©豆瓣', '窦骁', '霍建起', 6.8, 9511, 'tt9501208', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1069481048.jpg', 2.4, 11.2, 44.7, 30, 11.7, '0.236737,0.033606,-0.919714,0.702847,0.006176,-0.450928,0.602096,0.320362,-0.596928,-0.319478,0.061087,0.720438,-0.188742,0.344644,0.371414,-0.498563,-0.057580,-0.647170,0.085286,0.083767,-0.131817,-0.661232,-0.235814,-0.082038,-0.415702,-0.144921,0.737666,0.304486,-0.426706,0.712465,0.167438,0.488950,-0.107808,0.523619,-0.067319,-0.250469,-0.010704,0.376077,-0.587380,0.205775,0.133824,-0.340277,-0.344424,-0.090672,-0.183000,0.294765,0.597794,0.046599,-0.034391,-0.139903,0.366173,-0.074830,-0.026001,0.236575,0.348460,0.293666,-0.028809,0.389761,-0.282259,0.077471,-0.311706,-0.108145,-0.027006,-0.115882,0.180514,0.200601,-0.706891,0.487468,-0.040740,-0.086351,-0.049794,-0.395290,0.033712,0.582416,-0.582958,0.437581,-0.213374,0.179462,0.010385,0.382472,0.578881,0.163586,-0.210806,-0.136147,-0.413246,-0.375368,0.387293,0.088586,-0.152956,-0.319869,0.211988,0.185669,0.062240,0.301907,-0.638190,-0.276869,-0.178992,0.286798,0.114575,-0.178426,0.150941,-0.637001,-0.430572,-0.442279,-0.092423,0.092496,0.060316,-0.526968,0.645090,-0.883971,0.198442,-0.268077,0.365555,-0.774024,0.722454,0.088646,0.060462,-0.432917,0.185490,0.495562,-0.306004,0.083866,0.048075,0.082841,-0.123618,-0.233228,-0.309903,0.308083', '1293265', '1306465', '1301022', '1897368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5345423', '宅男总动员', '喜剧', '宅男狗不理在网上开办一家名为“爱情世博汇”的爱情商店，没想到把剩女戴安娜牵扯进了自己的生活。狗不理以为捕捉到对方芳心，而戴安娜则视对方为“小屁孩”，不愿迈出重要的一步。因为网主职业道德，狗不理在网上帮戴安娜成功追求到她心仪己久的摄影师文森特。戴安娜发现狗不理对自己仍未死心，主动表明再怎么发展也只能是姐弟关系。正在这时戴安娜发现，文森特有一个缺点，而这个缺点是致命的......©豆瓣', '钟镇涛', '杨子', 3.6, 4428, 'tt1883399', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p921931746.jpg', 48.8, 29, 18.1, 2.9, 1.2, '0.520007,0.246158,-0.643328,0.348959,-0.259582,-0.357912,0.502108,0.085689,-0.276865,-0.390982,0.206505,0.647741,-0.151750,0.073570,0.013476,0.012629,0.180072,-0.412159,0.251052,-0.198345,-0.203385,-0.483631,-0.245332,-0.281665,-0.370636,0.021355,0.664992,0.042713,-0.363528,0.155201,0.518763,0.059250,0.018961,0.371213,-0.109254,0.117187,0.097139,-0.204449,-0.426434,0.297336,0.224845,-0.241519,-0.179432,0.211612,-0.067055,0.326766,0.566379,-0.023004,-0.307403,-0.019186,0.589475,-0.217787,-0.200261,0.229849,0.213289,-0.197427,0.117208,-0.049386,-0.020340,-0.116239,0.343354,0.051701,-0.704979,0.065810,-0.018887,0.206978,-0.394263,0.197314,-0.170733,-0.115488,0.195031,-0.507334,0.205944,0.033470,0.452757,0.132195,-0.275996,0.288365,-0.529314,-0.041230,0.653592,0.093112,-0.017889,0.693498,-0.074569,-0.165956,0.053156,-0.046512,-0.438634,-0.015118,0.018640,0.455835,-0.182639,0.009816,-0.446194,0.099292,-0.156200,0.042913,0.299876,-0.590196,-0.151443,-0.392595,-0.333990,-0.360537,-0.189219,0.156899,0.030673,-0.513241,0.593778,-0.855917,0.039690,0.670092,0.488627,-0.815000,0.892325,0.138371,-0.022540,-0.360118,-0.322239,0.275919,0.148962,-0.047435,-0.057531,0.098204,0.082397,-0.342258,-0.287590,0.280181', '2124718', '5985887', '4301278', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5346468', '生化危机：诅咒', '动作', '1991年，苏联解体，原隶属苏联体系下的社会主义国家纷纷宣布独立，东斯拉夫共和国正是众多新生国家中的一员。然而东斯拉夫两极分化严重，社会严重失衡，反叛军与政府军进行了长达十数年的战争。时间进入21世纪，双方的战争愈演愈烈，甚至传闻已有“怪物”加入进来，战争开始朝着不确定的方向发展。为了调查生化武器的实情，里昂获命来到东斯拉夫。混乱之中，他被反叛军抓获，可是遭到寄生虫操控的人类很快冲击了他们的栖息地和城市。与此同时，艾达也抱着神秘目的来到东斯拉夫。战争毁灭了一切，滋养着恶魔，里昂能否阻止事态进一步恶化呢……本片根据经典同名电子游戏改编。©豆瓣', '马修·默瑟', '神谷诚', 7.7, 40792, 'tt1753496', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1713599926.jpg', 0.5, 2.3, 27.9, 49.1, 20.2, '0.187566,0.272528,-0.735481,0.264487,0.475156,0.152866,0.369752,-0.312987,-0.465289,-0.181627,-0.032768,0.278168,0.027049,-0.516723,0.206868,-0.141596,-0.614453,-0.606357,-0.207548,0.119913,-0.424129,-0.513105,-0.409577,-0.451732,-0.181938,-0.295444,0.790118,0.409939,-0.691751,0.288721,-0.194231,0.623557,-0.410840,0.221006,0.149503,-0.069862,0.296799,-0.276826,-0.585818,0.367040,0.011887,-0.199717,-0.280579,0.231457,-0.179502,0.356673,0.381643,-0.676444,0.245747,-0.350672,0.307076,-0.470825,-0.396204,0.138743,0.672836,0.151223,0.160848,0.321616,0.090160,0.028664,-0.432613,-0.376789,-0.360104,-0.010567,-0.184475,0.265554,-0.333315,0.559870,0.127270,-0.059137,0.097113,-0.217770,0.088791,0.868060,0.313113,0.408894,-0.145263,-0.023981,-0.541436,-0.267606,0.775168,-0.005105,-0.787277,-0.012641,0.039089,-0.474754,-0.404352,-0.329297,-0.092066,-0.135296,0.249950,0.064920,0.159291,0.832233,-0.790486,0.373248,-0.472136,-0.688509,0.237466,0.261167,-0.022781,-0.633211,-0.317594,-0.147374,-0.222218,0.007205,-0.067771,0.017636,0.681139,-0.759266,0.101458,0.405529,0.610580,-0.894947,0.187387,-0.113503,0.291561,-0.445614,-0.319662,0.417245,-0.049473,0.418346,0.199118,-0.060921,-0.107782,-0.357991,-0.044935,0.153929', '1291824', '1303910', '1788431', '1305970');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5350027', '妖猫传', '剧情', '故事发生在盛唐时期的长安城，白乐天（黄轩 饰）本是朝廷要官，却为了收集写诗的素材而甘愿被贬为起居郎。长安城内连连发生离奇的死亡事件，就连当今圣上也难逃厄运离奇身亡，这一切都和一只神出鬼没的妖猫有关。日本僧人空海（染谷将太 饰）本为了替皇帝解咒远渡重洋而来，却和白乐天意气相投，两人决心携手调查案件真相。一首如怨如诉的《清平调》表明，妖猫作祟和三十年前倾国倾城的杨贵妃（张榕容 饰）之死有着千丝万缕的关联，追寻着曾经迷恋杨贵妃的阿部仲麻吕（阿部宽 饰）所留下的日记，白乐天和空海一同见证了大唐曾经的荣光，亦揭开了当年隐瞒至今的阴谋。©豆瓣', '黄轩', '陈凯歌', 6.9, 696434, 'tt6157626', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2530249558.jpg', 3, 9.5, 38.5, 35.3, 13.8, '0.168510,0.025399,-0.484825,0.631140,0.318513,0.006226,0.598608,0.077111,-0.577251,-0.498575,0.182639,0.545434,-0.178420,0.041131,0.297584,-0.246430,-0.004586,-0.794392,-0.037031,-0.240636,-0.020724,-0.445694,-0.136370,-0.258125,-0.296714,-0.184155,0.693241,0.186704,-0.110564,0.410766,0.517339,0.461511,-0.460201,0.217894,-0.122836,0.028823,-0.335397,0.305003,-0.271372,-0.132285,-0.011860,-0.567462,-0.175027,0.207401,-0.207836,0.119422,0.431793,-0.560151,-0.197557,-0.289197,0.500856,-0.089305,0.145271,0.183720,0.326797,0.221414,0.159226,0.725649,-0.211841,-0.247436,0.102434,0.123012,-0.864633,-0.140125,0.462663,0.326721,-0.203246,0.375494,-0.081811,0.060207,0.185147,-0.124118,0.422733,0.538012,0.499323,0.068676,-0.039605,-0.086063,-0.333411,0.579174,0.651886,-0.144401,0.054520,0.213061,0.054924,-0.281303,-0.158448,-0.010687,-0.129021,0.419617,-0.025991,0.055261,-0.127337,0.539543,-0.558226,-0.400490,-0.266206,0.175077,0.063346,-0.230045,-0.064193,-0.369175,-0.242873,-0.523868,-0.183542,-0.056864,0.495346,-0.222416,0.534290,-0.521055,0.194839,0.508110,-0.080779,-0.520231,0.561965,0.099056,0.131558,-0.052387,-0.169005,0.250440,0.166824,0.157992,-0.143682,0.047665,0.161764,-0.194376,-0.435527,0.153301', '26678784', '4301278', '26635323', '25918677');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5353344', '盲证', '剧情', '一场严重的车祸，让见习警察闵秀儿（金荷娜 饰）身负重伤，双目失明。她不仅因此失去做警察的机会，也与最亲的弟弟阴阳两隔。许是视觉器官的失灵刺激了其他器官的活跃，加上缜密的思维和判断力，秀儿能够觉察多许多正常人忽视的细节。在一次暴雨夜归途中，她自认为打上一辆模范出租车。谁知司机欲行不轨，两相推搡之时更发生车祸撞到一个路人。秀儿最终逃脱，并向警方报案，最终只有其貌不扬的赵警官相信她的判断力，于是和她一同调查肇事者。另一方面，时尚青年基夔（俞承浩 饰）声称曾目击车祸过程，但是他的陈述与秀儿多有不同，自然不被赵警官采信。然而，秀儿和基夔早已成为凶手意图灭口的对象，他们的生命危在旦夕……©豆瓣', '金荷娜', '安相勋', 7.5, 49425, 'tt2025506', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1097845082.jpg', 0.6, 2.8, 32.6, 49.4, 14.5, '0.306967,0.003400,-0.658405,0.386108,-0.292598,-0.233036,0.816725,-0.043972,-0.555920,-0.280256,0.239126,0.521893,-0.119900,0.006929,0.282298,-0.398030,-0.074080,-0.481088,0.286972,0.209450,-0.597752,-0.610306,-0.048809,-0.236478,-0.033889,-0.196862,0.405185,0.158705,-0.443393,0.244303,0.166376,0.127641,-0.271542,0.554288,0.121225,0.029527,-0.101581,-0.017453,-0.245916,0.059234,0.227502,-0.399555,-0.082715,0.155620,-0.292056,0.596680,0.529005,-0.111611,-0.532341,-0.150085,0.474823,-0.324556,0.150512,0.051229,0.298327,0.058595,0.078072,0.112913,-0.087933,-0.251268,0.111451,0.360020,-0.587835,0.159688,0.244070,0.067697,-0.350509,0.188606,0.010626,0.043264,-0.037203,-0.164788,0.219396,0.385620,0.220136,-0.030542,-0.188446,-0.098650,-0.578323,0.037752,0.854027,0.103601,-0.183018,0.366602,-0.118135,-0.428367,-0.135944,-0.189329,-0.304726,0.321997,0.370699,-0.008181,-0.426513,0.026182,0.018910,-0.068522,-0.441158,0.081841,-0.338422,-0.290616,0.231841,-0.389930,0.051226,-0.416407,-0.371892,0.160957,0.137695,-0.275645,0.456229,-0.593918,0.110539,0.447107,0.118324,-0.793604,0.469830,0.121646,-0.020616,-0.227362,-0.087450,0.212443,0.333398,0.163241,0.082590,0.187960,-0.039389,-0.147495,-0.172451,0.015837', '35073886', '1309116', '1292064', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5355187', '大武生', '剧情', '清朝末年，孟氏一族遭摄政王灭门，惟有小儿子孟二奎被大武生余胜英和徒弟关一龙所救。当年余胜英名满天下，可是却遭到岳江天的挑战，最终败北并丢掉摄政王赐给他“武生泰斗”的金匾，从此一蹶不振。多年后，关一龙（吴尊 饰）与孟二奎（韩庚 饰）已经长大成人，二人练就了一身本领，发誓要替师傅报仇。关、孟二人在上海初次登台，便战胜武生岳江天，为师父夺回“武生泰斗”的金匾，名声大震。而岳江天却不堪羞辱，当场自尽。岳江天的女徒弟刀马旦席木兰（徐熙媛 饰）与师父感情甚好，在亲眼见证师傅的死之后对二人恨之入骨，但为了保住岳家戏班，她最终答应戏院老板与关、孟二人同台演出。自此，在歌舞升平的大上海，一段关于报复与阴谋的故事拉开了序幕……本片由知名音乐人高晓松执导。©豆瓣', '吴尊', '高晓松', 5.2, 50966, 'tt1790669', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1205186585.jpg', 13.3, 31.1, 41.8, 10.5, 3.3, '-0.383170,0.115518,-0.360693,0.523119,0.176240,-0.409378,0.403681,0.263605,-0.634653,-0.392712,0.021177,0.813437,-0.228694,0.291974,0.378543,-0.341271,0.149658,-0.646297,-0.190252,-0.020226,0.007579,-0.386724,0.082619,-0.200715,-0.167500,-0.075717,0.518904,0.312057,-0.351473,0.543751,0.678945,-0.075655,-0.272171,0.206450,-0.075162,0.199991,-0.112753,0.272877,-0.574016,0.116403,0.015968,-0.303519,-0.235354,0.013961,0.011092,0.113110,0.223408,-0.147235,-0.115132,-0.200700,0.154665,-0.238887,0.022003,0.103792,0.336773,-0.125574,0.273495,0.331400,0.021278,-0.276264,0.019475,-0.223288,-0.233581,0.127294,0.557209,-0.421998,-0.686622,0.568277,-0.074004,0.196110,-0.222591,-0.077799,0.143843,0.169956,0.483685,0.164224,-0.125611,0.048541,-0.278584,0.466549,0.594650,-0.061080,0.257464,-0.121551,0.323352,-0.307080,-0.102968,-0.544627,-0.171526,0.112728,0.453355,-0.119512,0.083631,0.112665,-0.038884,-0.396454,-0.351524,0.294032,0.132673,-0.174505,0.338917,-0.349917,-0.129368,-0.234937,-0.023114,0.039275,0.214331,-0.439700,0.545650,-0.576643,0.350587,-0.338408,0.036692,-0.641968,0.335096,0.230702,0.251365,-0.071712,-0.118748,0.058777,0.222492,0.040630,0.246906,-0.012999,-0.173619,-0.090321,-0.169028,0.152105', '1307922', '1296978', '1297574', '3230460');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5355365', '寻龙夺宝', '动作', '故事开始于三千年前的中国北方，外敌入侵，皇帝为了得到强大的力量与其对抗而向神龙借来了宝珠。皇帝允诺战争胜利之后一定会将宝珠归还，然而他却在战斗中牺牲了，宝珠也就此失去了下落。一晃眼几千年过去，澳大利亚男孩乔西（路易斯·科贝特 Louis Corbett 饰）跟随着一支中澳联合考古队，千里迢迢来到了中国，来这里寻找自己的父亲切兹博士（山姆·尼尔 Sam Neill 饰），切兹博士在中国担任着考古队队长的职务。在机场，乔西偶然遇见了父亲的同事李博士（王姬 饰）和她的女儿小玲（李林金 饰），两个孩子相见甚晚，之后在误打误撞之中踏上了寻找龙珠的旅途。©豆瓣', '李林金', '马里奥·安德鲁西奥', 3.8, 5730, 'tt1708534', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p946838519.jpg', 40.5, 35.3, 19.3, 3, 1.9, '0.003323,0.265915,-0.789669,0.537525,-0.017383,-0.589348,0.499660,-0.069089,-0.627487,-0.043325,0.145438,0.812972,0.079467,0.059895,0.231662,0.146160,-0.339076,-0.606946,0.108549,-0.246408,-0.334756,-0.406863,-0.355547,-0.066669,-0.117042,-0.398856,0.613745,0.022848,-0.078295,0.560988,0.070477,0.278699,-0.195379,0.477698,-0.222026,0.024997,0.189733,0.119406,-0.405900,0.507836,0.183647,-0.312932,-0.224115,0.193464,-0.039370,0.054574,0.558526,-0.512484,0.251600,-0.334682,0.116659,-0.220530,-0.021118,0.059592,0.362381,0.215558,0.181850,0.355571,-0.264244,-0.010905,-0.029990,-0.107106,-0.268974,0.077102,-0.155936,0.223126,-0.645853,0.401922,-0.041294,-0.076802,0.190092,-0.614499,0.411701,0.685098,0.054469,0.174360,-0.330277,-0.142832,-0.568888,0.249286,0.599010,-0.236350,0.003129,0.107969,0.197236,-0.355582,0.038595,-0.037629,-0.369291,0.031380,0.501172,-0.085712,0.060718,0.260471,-0.805036,0.080674,-0.445063,-0.071480,0.153410,-0.317724,0.017708,-0.345581,-0.020602,-0.132266,-0.299931,0.053310,0.052484,-0.142935,0.697586,-0.796219,0.156954,0.775688,0.449581,-0.386865,0.511859,-0.137689,0.231453,-0.320742,0.193787,0.214159,-0.105260,0.564819,0.156519,0.127650,0.198398,0.022417,-0.391096,0.289302', '1438591', '34461680', '26393561', '1307755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5360033', '想爱就爱', '喜剧', '女孩Pim（奥密兹•苏查拉特 Aomiz Suchar 饰）因与前男友分手要求换宿舍，于是她和新来的学妹Kim（蒂娜·吉塔勒拉 Tina Jittaleela 饰）成了同居舍友。起初，Pim以为Kim是走错屋的小正太，直到对方袒露胸襟，她才赫然发现 其实是同类。第 一印象如此之差，让Pim怀疑其拉拉倾向严重，索性在宿舍中画定了三八线。尽管Kim百般讨好，但是Pim还是觉得她弹吉他、玩电玩很烦人。倒是Pim的闺蜜对Kim仰慕已久，大献殷勤。直到Pim随Kim回了家，夜晚听她弹吉他，两人才慢慢地敞开了心扉。Pim喜欢上了Kim做的菜。慢慢地，两人形影不离的关系，引起了Pim朋友们的嫉妒。甚至连熟识的哥哥也以男友自居，让她很受伤。在经历了多次波折之后，Pim赫然发现，原来当彼此的心心相印时，并不存在不能逾越的界限……©豆瓣', '苏查·玛娜英', '萨拉萨瓦蒂·翁索姆佩奇', 7.6, 127961, 'tt1906518', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2389681675.jpg', 0.7, 3.8, 32.7, 42.1, 20.7, '0.595485,-0.103782,-0.617948,0.320449,-0.085150,-0.403229,0.695851,0.191139,-0.599690,-0.017129,-0.137793,0.596602,-0.433079,0.212163,0.255378,-0.057630,-0.214366,-0.833366,-0.020815,-0.264028,-0.422879,-0.460938,-0.000417,-0.037852,-0.253695,-0.244748,0.181708,-0.201273,-0.167671,0.359582,0.319660,0.056050,-0.009870,0.538828,-0.054459,-0.148901,-0.012428,0.324275,-0.246584,-0.010521,-0.080078,-0.224896,-0.054601,0.057407,-0.052827,0.333677,0.650739,-0.237541,-0.313636,0.053322,0.195861,0.005165,-0.109773,0.007188,0.242353,0.032210,0.390673,0.061977,0.007622,-0.012112,0.082873,-0.013792,-0.418499,0.283778,0.176510,-0.126784,-0.487794,0.526312,-0.055315,-0.230826,0.095951,-0.370000,0.193250,0.299703,0.237472,0.370789,-0.163153,0.190081,-0.240147,-0.116882,0.529645,0.137704,-0.067841,0.501019,-0.206907,-0.310919,0.023773,-0.068228,-0.381234,-0.079273,0.001398,0.216820,-0.157513,-0.001850,-0.481689,-0.151912,-0.085704,0.027606,0.154832,-0.590433,-0.001236,-0.121448,-0.254079,-0.679820,-0.326178,0.056955,-0.033342,-0.173935,0.640372,-0.883456,0.177969,0.392210,0.350731,-0.389724,0.751788,0.309229,-0.275012,-0.188961,-0.044313,0.143381,-0.145658,0.032197,0.531262,0.409656,0.005100,-0.215853,-0.353016,0.369512', '1308755', '1292219', '2027925', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5360889', '月升王国', '剧情', '1965年，在一个叫新彭赞斯的小岛上，有一队童子军驻扎在艾凡赫营地里。童子军教官华德（爱德华·诺顿 Edward Norton 饰）在一个早上发现学童山姆（杰瑞德·吉尔曼 Jared Gilman 饰）留信出走，于是华德和一众童子军开始寻找山姆，小岛警察夏普（布鲁斯·威利斯 Bruce Willis 饰）也展开了环岛搜寻。原来山姆的出逃是计划已久的，他和“问题”女孩苏西（卡拉·海沃德 Kara Hayward 饰）一起出走，而苏西是岛上一对律师夫妻的女儿，父母视苏西为问题儿童。搜寻过程中，苏西的父亲（比尔·默瑞 Bill Murray 饰）似乎察觉到自己的妻子和警察有染。这支由一队童子军、童子军教官、警察、律师父母组成的搜查小队，终于找到了出逃的二人。由于山姆是孤儿，这次事件之后他必须被送去未成年人收容所。当晚，童子军队伍决定帮山姆和苏西二人再次出逃。一场大风暴将要从东部向小岛袭来，一行人将会遇到什么……', '杰瑞德·吉尔曼', '韦斯·安德森', 8.4, 127121, 'tt1748122', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1791964116.jpg', 0.3, 1.4, 15, 46.9, 36.5, '0.278233,-0.393078,-0.523658,0.404263,-0.082557,-0.386661,0.538325,0.000754,-0.726041,-0.316557,0.221377,0.823581,-0.020146,0.213401,0.468003,0.224424,-0.488073,-0.694768,-0.187041,-0.283374,-0.304180,-0.648909,-0.059433,-0.349693,0.236593,-0.260245,0.366329,-0.141894,0.064798,0.585540,0.309624,0.249450,-0.435034,0.413973,0.043920,0.117655,0.378869,-0.244509,-0.317619,0.286687,-0.036940,-0.029093,-0.264602,0.062082,0.085511,0.492762,0.791423,-0.115602,0.167025,-0.187601,-0.125668,-0.287287,0.064765,-0.024948,0.504463,0.018238,0.148153,0.248096,-0.033762,-0.041048,-0.154275,-0.096552,-0.086076,0.130378,0.097376,0.190210,-0.699001,0.174644,-0.124251,-0.021642,0.398387,-0.339726,0.168352,0.443235,0.093214,0.184521,-0.001064,-0.072397,-0.381265,0.071490,0.555798,-0.123339,0.193154,-0.006492,0.051252,-0.349621,0.086711,0.283668,-0.316318,0.048456,0.301442,-0.154165,-0.175892,-0.049133,-0.714721,-0.116870,-0.558373,-0.282693,0.001714,-0.245109,-0.083500,-0.748728,0.224917,-0.015347,-0.181630,0.192228,-0.131529,0.222646,0.489780,-0.750185,0.174447,0.547637,0.211167,-0.392850,0.378091,-0.129215,0.238075,-0.421294,0.092968,-0.034724,0.112394,0.431155,0.126330,0.201841,-0.066337,-0.355237,-0.291930,0.034079', '1309194', '11541282', '1292050', '1465415');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5360890', '羞耻', '剧情', '布兰顿（迈克尔·法斯宾德 Michael Fassbender 饰）是纽约衣着光鲜的白领。他酷爱成人电影，习惯自慰，并寻花问柳。不过，他与妹妹希西（凯瑞•穆里根 Carey Mulligan 饰）的关系却忽冷忽热。希西总给他电话留言，他却总是避之不及。然而，当希西搬来与他同住 ，他又表现出特别的关心。布兰顿和上司一同去听希西的演唱，结果上司被她的风姿所打动，而他却沉浸在她的歌声中潸然泪下。在妹妹面前，布兰顿表现的无所谓，而上司却大胆追求。这令布兰顿极为羞耻。某日，上司在与家人视频通话后，开始斥责布兰顿往电脑硬盘塞满了成人电影，称之为耻辱。气急败坏的布兰顿却对妹妹发火，令她十分伤心。布兰顿曾约会公司的黑人女秘书，却发现自己真正难以割舍的不是性瘾，而是心中惦念的兄妹之情……迈克尔•法斯宾德凭借本片获68届威尼斯电影节影帝©豆瓣', '迈克尔·法斯宾德', '史蒂夫·麦奎因', 7.3, 93084, 'tt1723811', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1499701469.jpg', 0.8, 4.5, 37.2, 42.8, 14.8, '0.142494,-0.034199,-0.557000,0.629168,0.071351,-0.453483,0.847688,0.434841,-0.412730,-0.331968,0.087372,0.615872,-0.577873,0.232313,0.101859,-0.025915,-0.355104,-0.530434,0.134587,-0.143038,0.184271,-0.180773,-0.185118,-0.124512,-0.183549,-0.305141,0.409593,-0.131633,-0.411660,0.356947,0.339278,0.473720,0.030871,0.595091,0.125649,0.105210,-0.025961,0.146749,-0.275148,-0.240324,0.076551,-0.097912,-0.317461,0.440922,0.192102,0.499382,0.410741,-0.121557,-0.075638,0.027313,0.423292,-0.083847,0.256908,-0.006094,-0.128286,-0.147106,0.351381,-0.127333,0.132768,0.071851,0.142950,0.013732,-0.453945,0.297311,0.048788,0.309935,-0.436235,0.454751,-0.502631,0.284762,-0.066199,-0.317219,-0.033187,-0.155698,0.125020,0.624398,-0.031680,0.080057,-0.638537,0.111232,0.356335,0.211740,-0.177860,0.524678,-0.349696,-0.313985,0.282141,-0.193336,-0.572508,-0.007299,0.141263,-0.114673,0.134431,0.212720,-0.380786,-0.310146,-0.247387,0.177884,0.077191,-0.513768,0.016998,-0.540069,-0.238722,-0.448829,-0.429697,-0.182868,0.146989,-0.331647,0.388195,-0.842564,0.020665,0.298158,0.316947,-0.393302,0.467767,0.270862,-0.093167,-0.168224,-0.146027,0.403564,0.047435,0.066856,0.105765,0.248241,0.105354,-0.066317,-0.480245,0.559330', '1308755', '1309080', '4275444', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5361544', '兵临城下之决战要塞', '剧情', '故事发生在1941年的6月，布格河畔回荡着欢声笑语，就在一片歌舞升平之际，几架飞机飞过投下了炸弹，将一切摧毁殆尽，霎时间，河畔边成为了鲜血和火焰的海洋。德国人的入侵让位于华沙和莫斯科之间的布列斯特要塞陷入了动荡和战争之中，为了保护自己的国家，八千名苏维埃红军战士们拿起了武 器，与亲人告别，走上了战场。草草建立的军队中人员情况十分复杂，但是，每个人心中的信念却是一致的，那就是顽强抵抗贼寇的入侵。粮食短缺，武器简陋，装备寒酸，在及其恶劣的条件之下，苏维埃青年们和装备精良的敌方展开了一场又一场险象环生的激烈战斗，并且最终获得了胜利。©豆瓣', '安德烈·梅尔兹利金', '亚历山大·科特', 8, 19266, 'tt1343703', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p830086491.jpg', 0.4, 2.2, 22.5, 48.1, 26.8, '0.222266,0.150826,-0.885886,0.648286,0.233919,0.026863,0.741918,-0.108645,-0.468630,0.178683,0.339166,0.611835,-0.034000,-0.133216,0.261824,-0.410857,-0.441705,-1.012756,-0.404716,-0.010993,-0.496660,-0.452786,-0.341907,-0.263147,-0.050741,-0.529815,0.750292,0.561411,-0.195413,0.346526,0.021348,0.271922,-0.159821,0.451414,-0.090364,-0.208450,-0.100204,-0.236144,-0.451953,0.172789,-0.327149,-0.297706,-0.296070,0.182412,-0.022731,0.293182,1.017892,-0.568273,0.129429,-0.086723,-0.043266,-0.485912,0.012745,0.250355,0.280946,0.205181,0.061755,0.037290,-0.215719,0.051728,0.053915,-0.131017,-0.530489,-0.128500,-0.097918,0.060093,-0.533241,0.838093,0.063303,0.108593,0.178407,-0.112797,0.348278,0.584661,0.076689,0.575930,-0.477235,-0.164752,-0.636103,0.101618,0.866204,-0.027206,-0.309585,-0.026692,-0.266663,-0.420240,-0.219151,-0.268238,-0.154186,-0.280320,0.360710,0.025736,0.222418,0.577249,-1.141948,0.283043,-0.286876,-0.760599,0.011019,-0.305186,-0.333416,-0.720679,-0.112169,-0.316969,-0.291850,0.537870,0.041248,0.145329,0.967625,-0.739105,-0.067897,0.187748,0.311626,-0.196030,0.286559,0.004877,0.306801,0.220657,0.045183,0.016894,-0.115473,0.501425,0.458242,0.189794,-0.345313,-0.022837,-0.224046,0.465760', '1856675', '26290398', '1292943', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5364905', '天机·富春山居图', '动作', '元代画家黄公望的名作《富春山居图》，被誉为“中国十大传世名画”之一。由于种种原因，该作的“无用师卷”和“剩山图”分处海峡两岸，隔海相望。2011年，《富春山居图》有望合璧展出，谁知这件保额即高达十亿的旷世杰作引来各国罪犯的觊觎。早些时候，“无用师卷”在台湾失窃，先失一着的日本文物走私大鳄山本俊雄（佟大为 饰）遂将目标锁定在深藏杭州的“剩山图”。与此同时，国内的老佛爷（斯琴高娃 饰）及欧美等国的文物贩子纷纷云集于此，蠢蠢欲动。在利欲薰心、刀光剑影的轮番交手中，香港警署海外缉私科特工肖锦汉（刘德华 饰）和身份莫辨的王雪晴（林志玲 饰）携手，与山本为首的走私犯周旋世界各个角落，接连过招，命悬一线。合璧展出之日逼近，国宝的命运难以勘破……©豆瓣', '刘德华', '孙健君', 3, 117727, 'tt2460488', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1978939367.jpg', 68.6, 19.5, 8.1, 1.5, 2.3, '0.206769,-0.206063,-0.899197,0.416113,0.427116,-0.034768,0.402578,-0.068251,-0.465495,-0.095665,0.238025,0.732491,-0.181301,-0.063692,0.166771,-0.221300,0.188496,-0.772633,-0.248947,-0.463956,0.043157,-0.240823,-0.588399,-0.018545,-0.565607,0.003508,0.558536,0.256577,-0.292378,0.459492,0.302674,0.457068,-0.532910,0.032661,-0.228414,-0.236047,0.065484,-0.173394,-0.528798,0.032779,-0.351299,-0.428608,-0.050304,0.013658,-0.279669,0.144243,0.607956,-0.277054,0.322604,-0.174238,0.247358,-0.105049,-0.255494,-0.064401,0.416494,0.153349,0.068374,0.252458,-0.414986,0.065246,0.283559,0.100227,-0.386036,-0.074963,0.507620,0.301701,-0.155991,0.451188,-0.242870,0.200731,-0.308819,-0.172203,0.386577,0.310134,0.229838,-0.030580,0.273346,-0.112455,-0.463837,0.492246,0.214285,0.075943,0.076795,-0.192109,0.241279,-0.451086,-0.163674,-0.558407,0.079177,-0.163307,0.449229,-0.151071,0.334104,0.326353,-0.687469,-0.065980,-0.008246,-0.112367,0.056126,0.029986,0.046262,-0.926219,-0.097727,-0.586180,0.026194,0.114516,0.549739,-0.052803,0.925900,-0.368985,0.066686,0.412596,0.204270,-0.309927,0.561200,-0.042834,0.097570,-0.022996,-0.413028,0.010175,0.280196,0.235335,-0.107788,0.211058,-0.008493,-0.363511,-0.201948,0.126914', '4212172', '25863940', '3811356', '26094129');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5364952', '世上最美的离别', '剧情', '电影《世上最美的离别》改编自韩国作家卢熙庆的同名原著及电视剧。卢熙庆因怀念自己因癌症去世的母亲而写就这本小说中刻画了一个平凡又伟大的母亲的一生。母亲（裴宗玉 饰）在婆婆身患老年痴呆后辛苦照顾她15年，只身挑起家中重担，为一家人操劳不休。而丈夫（金甲洙 饰）对家事丝毫不关心，女儿爱上了有妇之夫，儿子也面临着高考的艰难形势。家庭中的每个人似乎都有各自的烦恼各自的事情。她去丈夫上班的医院看病，丈夫却因为自己是一名薪资低的医生而不愿意在工作的地方见到她；她去看上班的女儿，想约她一起吃一顿午餐，哪怕只是简单的一碗乌冬面，而女儿却忙着和情人约会，推脱她；她心疼的儿子，考上了大学一身轻松，和女朋友约会喝酒，过自己的快意生活。而她却在此时被查出患有膀胱癌，并处于癌症末期的情况下。在发现母亲即将离世时，家中每一个人的态度都发生了改变......©豆瓣', '徐英姬', '闵奎东', 8.4, 32780, 'tt2557406', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1264695739.jpg', 0.5, 1.5, 15.3, 44.6, 38.1, '0.083055,-0.214168,-0.701661,0.526264,-0.253413,-0.392342,0.881089,0.295504,-0.400391,-0.407581,0.172479,0.846391,0.120502,0.558048,0.077478,0.095888,-0.101115,-0.659920,0.319404,0.135011,-0.266412,-0.117122,-0.041760,-0.355267,-0.042950,-0.246231,0.313555,-0.003551,0.150440,0.305352,0.159185,0.023256,-0.017854,0.648157,-0.163501,0.093126,-0.174000,0.281298,-0.156725,0.167364,0.315188,-0.212631,-0.256336,0.284155,0.131364,0.518704,0.513368,0.156288,-0.347949,-0.135330,0.518670,-0.157781,-0.102352,0.151505,0.262076,-0.001203,0.211373,0.131358,-0.178917,-0.012945,-0.105099,-0.110663,-0.706874,-0.056828,0.220436,0.153660,-0.711043,0.770203,-0.232193,-0.114127,0.005744,-0.343764,0.310760,0.305733,0.012453,0.631018,-0.297390,0.042586,-0.474789,0.715021,0.706039,0.055757,-0.068421,0.538527,-0.400942,-0.189966,0.118191,-0.474654,-0.802906,0.168180,-0.152539,0.032320,-0.415521,0.163647,-0.056567,0.128690,-0.050491,-0.202492,-0.037613,-0.446976,-0.036766,-0.151468,0.025294,-0.444238,-0.597910,-0.076358,0.113986,-0.417022,0.699103,-0.596836,0.206862,0.609928,0.306961,-0.818936,0.934931,0.336096,0.163385,-0.195155,0.016966,0.327418,-0.229855,0.078112,0.070873,0.094672,-0.003911,0.092956,-0.441368,0.513695', '1306916', '1297606', '26718282', '24879820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5364976', '温柔杀戮', '剧情', '一家由黑帮操控的地下扑克赌场，突遇三名悍匪抢劫。赌场老大如临大敌，势要找出幕后黑手。他们找来得力干将杰基·科恩（布拉德·皮特饰）介入调查，让他来找出肇事者重整地下秩序。作为一名老练的赏金猎人，杰基性情孤冷而深藏不露。本来这场由三个毛头小混混设计的抢钱计划，笨拙到一望而知，可赌场管理人马基（雷·利奥塔 Ray Liotta饰）无端被人殴打，老酒鬼米奇（詹姆斯·甘多菲尼 James Gandolfini 饰）无故被杀等事件的意外穿插，又使局面陷入一片混乱。杰基抽丝剥茧，开始了他的深入调查。然而，这正是这场腥风血雨的开始，一场帮派间的温柔杀戮一触即发。本片改编自乔治·V·哈金斯于1974年创作的小说《柯根的交易》。这部影片是布拉德·皮特和导演安德鲁·多米尼克在《神枪手之死》后再度合作的第一部长片，本片入围2012年第65届戛纳电影节主竞赛单元-金棕榈奖。', '布拉德·皮特', '安德鲁·多米尼克', 6.1, 11218, 'tt1764234', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1681312288.jpg', 3.7, 19.4, 51.3, 20.2, 5.4, '0.044431,-0.048704,-0.481653,0.279119,0.030200,-0.136318,0.460770,0.175147,-0.367538,-0.246393,0.238831,0.502668,-0.248839,-0.151859,0.457869,-0.263168,-0.345508,-0.693962,-0.405517,-0.113295,0.111437,-0.273976,-0.285941,-0.312295,0.090054,-0.236071,0.451824,0.193439,-0.227619,0.359080,0.572095,0.468653,-0.082957,-0.033300,0.200735,-0.126051,0.404837,-0.223356,-0.363395,0.243540,-0.171614,-0.274114,-0.367963,-0.011938,0.095461,0.507827,0.620673,-0.155086,0.137250,-0.052656,0.426049,-0.429543,-0.283975,-0.155698,0.515216,0.061817,-0.041895,0.276863,-0.062865,0.056727,0.038359,-0.448674,-0.735036,0.146175,0.037096,0.187139,-0.329828,0.055362,-0.101095,0.173398,-0.141950,0.114327,0.045260,0.247737,0.593807,0.029132,0.208116,-0.013526,-0.343964,0.160007,0.581529,0.016972,-0.169048,0.028524,0.178216,-0.492114,0.058009,-0.504651,-0.186536,0.090437,0.664091,-0.490048,0.093396,0.301430,-0.510838,-0.108757,-0.331427,-0.186955,-0.216126,-0.179580,-0.057521,-0.893964,-0.258909,0.133960,0.162709,0.013944,0.102186,-0.105494,0.397556,-0.494125,0.139229,0.591078,-0.113942,-0.388134,0.373331,0.100137,0.062383,-0.330895,-0.227832,-0.164803,0.409287,0.333472,0.151755,0.229642,-0.078283,-0.346015,-0.033711,0.071023', '4014397', '25723905', '1295547', '2028645');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5364978', '喜羊羊与灰太狼之兔年顶呱呱', '喜剧', '又是一年春节临近，灰太狼（张琳 配音）的心中却感受不到半点喜悦。反倒是无比悲凉，老婆红太狼（赵娜 配音）身怀六甲，小灰灰（梁颖 配音）日渐长大，嗷嗷待哺。偏偏灰太狼逮羊的业绩太差，狼堡因此遭到强拆。种种变故，让这个四口之家的顶梁柱叫苦不迭。为了扭转局势，灰太狼带领老婆孩子向羊村开始了绝地大反攻。与此同时，青青草原迎来了不速之客——来自月球的兔小弟。从他的口中，羊羊们得知原本为五彩斑斓的糖果所包围的月球被邪恶的苦瓜大王所占领，而喜羊羊（祖丽晴 配音）更知晓了关于父母的一切。为了找回美丽的糖果世界，羊羊们随着兔小弟飞赴月球，而灰太狼一家也阴差阳错被带了过去。一场全新的冒险就此展开……本片为动画片《喜羊羊与灰太狼》第三部电影剧场版。©豆瓣', '祖晴', '赵崇邦', 7.1, 21717, 'tt1997607', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173291833.jpg', 2.8, 8, 40.4, 27.7, 21.1, '-0.017634,-0.106748,-0.547417,0.380507,0.099258,-0.229398,0.583286,0.124668,-0.514968,-0.092964,0.005140,0.532865,-0.427455,0.181022,0.051831,-0.026405,-0.027038,-0.197447,-0.124891,-0.103767,0.038961,0.029613,-0.204154,-0.012883,-0.043139,-0.049518,0.822991,0.163820,-0.091098,0.404559,0.466979,0.039686,-0.149954,0.331478,-0.043016,0.313386,-0.276101,0.092311,-0.101771,0.142750,0.080094,-0.069083,-0.046808,0.200925,-0.210653,0.192890,0.992575,-0.291162,-0.225827,-0.537270,0.537410,-0.256499,-0.081896,0.114428,0.291029,0.042728,0.019447,-0.046384,-0.072620,0.113893,0.102491,-0.245037,-0.612037,0.228137,0.040277,0.054346,-0.270583,0.189411,-0.078612,0.021586,0.449649,-0.379657,0.056850,0.271895,0.196410,0.622996,-0.264683,0.323904,-0.350287,0.165174,0.637849,0.053810,0.145239,0.480855,-0.043583,-0.319049,0.132983,-0.258620,-0.348454,0.248528,0.286491,0.188293,-0.221605,0.487754,-0.765819,-0.139294,-0.170295,-0.417582,0.035815,-0.524690,-0.133149,-0.575101,-0.109288,0.030108,0.087332,0.108287,0.230339,-0.204012,0.719307,-0.785444,0.147342,0.363916,0.138989,-0.220719,0.310531,-0.111278,0.066673,-0.304457,0.130299,0.120889,0.146595,0.207815,0.270261,0.049134,-0.114446,-0.243396,-0.356907,0.433213', '26759820', '10174444', '5403927', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5364987', '孤岛惊魂', '悬疑', '雄踞东南亚的亿万富豪——OEC集团总裁陈家栋（姜皓文 饰）继承父亲的产业，并决心开发位于太平洋爪哇海上一个已经废弃40年之久的小岛。虽然父亲极力阻拦，但是利益熏心的家栋依然发起了一个孤岛探险的比赛。他开出100万元的巨额奖金，引得彭非（陈小春 饰）、沈依琳（杨幂 饰）、小野宏（叶山豪 饰）等8名青年男女搭上了前往小岛的游艇。一切看似顺风顺水，游艇却在航行中遭遇了离奇海难，致令8个青年被迫滞留小岛。在这座岛上，他们不仅遭到疯狂野猪的袭击，还发现了一座几成废墟的麻风病人的医院。此后不久，恐怖的事情接连发生，众人陷入一个无法退出的死亡游戏之中……©豆瓣', '陈小春', '钟继昌', 3.5, 50997, 'tt1980198', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1096834265.jpg', 53, 28.9, 12.6, 2.1, 3.3, '-0.106838,0.101408,-0.847493,0.558101,0.176404,-0.102279,0.612622,0.111321,-0.505228,-0.184903,0.441061,0.655739,-0.058984,0.163219,0.247768,0.068444,-0.034346,-0.434189,-0.105804,-0.187337,-0.210479,-0.302864,-0.288462,-0.124601,-0.114597,0.009104,0.734018,0.563086,-0.084637,0.449953,0.106663,0.156587,-0.270512,0.505921,-0.169755,0.027862,0.262268,0.073577,-0.119716,0.250117,-0.510290,-0.364489,0.073506,0.068894,0.007394,0.493551,0.844070,-0.139470,-0.289974,-0.117561,0.153112,-0.143918,-0.143551,0.050496,0.678692,-0.157359,-0.041648,0.286351,-0.430442,0.016691,0.097479,-0.120914,-0.411869,-0.169739,-0.046457,0.082686,-0.373206,0.531797,-0.009218,-0.028404,-0.393299,-0.211535,0.107263,0.382106,0.280123,0.084132,-0.235115,0.203263,-0.532299,0.077418,0.716328,-0.086480,-0.095974,0.297798,-0.026639,-0.304916,-0.252913,-0.263249,-0.352347,0.001599,0.335273,-0.096730,-0.168313,0.262451,-0.630911,0.117052,-0.518262,-0.366363,-0.159549,-0.067364,-0.351770,-0.660161,0.064111,-0.183697,-0.026366,0.253126,-0.094269,0.040795,0.375551,-0.461548,0.112304,0.380109,0.375805,-0.336585,0.430588,-0.176753,0.149487,-0.194379,-0.173232,0.376822,-0.061175,0.404909,-0.111683,0.045301,-0.208502,-0.372145,-0.150927,0.308876', '3011051', '1856675', '26418093', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5365963', '阿波罗18号', '科幻', '上世纪60、70年代，美苏两大发达国家进行了一场震惊世界的军事竞赛。为了赢得未来星球大战的制空权，两国相继将宇航员送入外太空。美国方面，在1972年以前先后发射了17艘宇航飞船前往月球，然而阿波罗18号却在飞行前夕被紧急叫停。根据最新解密的录像，本杰明·安德森（Warren Christie 饰）、内森·沃克（Lloyd Owen 饰）和约翰·格雷（Ryan Robbins 饰）三名宇航员以采集样本的名义登上了阿波罗18号，于1974年飞赴月球，进行为期一周的考察。本杰明和内森着陆月球，却接连发现奇怪的现象：不明身份者留下的脚印、惨死的苏联先行者以及各种奇怪的声音和若隐若现的生物。这不啻为一次无法回头的死亡之旅……©豆瓣', '沃伦·克里斯蒂', '贡萨洛·洛佩斯-加列戈', 6, 6857, 'tt1772240', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1288061824.jpg', 4.3, 20, 50.4, 19.9, 5.4, '0.064688,0.144940,-0.798584,0.803002,0.310720,-0.077323,0.403088,-0.297164,-0.502899,-0.093375,0.100146,0.657767,-0.249594,-0.026954,0.354765,0.066269,-0.597263,-0.507896,-0.257792,-0.352645,-0.546329,-0.587597,-0.398713,-0.207225,0.037607,-0.521464,0.757832,0.081735,-0.209977,0.595133,0.110507,0.362940,-0.167074,0.410101,-0.145335,-0.196119,0.255819,-0.074803,-0.411133,0.244744,-0.037250,-0.130066,-0.033824,-0.099028,-0.016194,0.357424,0.811499,-0.380950,0.069116,-0.304060,0.399286,-0.081026,-0.028467,-0.016596,0.511254,0.279502,-0.243182,0.263211,-0.063312,0.031534,0.220076,-0.033423,-0.612578,-0.017490,-0.115209,0.066049,-0.386920,0.487401,-0.563549,0.187014,-0.034669,-0.336025,0.217184,0.589131,0.369289,0.586223,-0.190709,0.044669,-0.267548,0.202855,0.529281,0.289382,-0.530439,0.172226,0.132156,-0.637861,-0.317053,-0.223948,-0.146009,0.042144,0.517349,0.154950,-0.069208,0.321388,-0.869211,0.184019,-0.317295,-0.848838,0.070053,-0.202078,-0.123769,-1.172697,0.123544,-0.396084,-0.200191,0.192455,0.184450,-0.210709,0.620241,-0.541011,0.250729,0.381068,0.201075,-0.253901,0.815669,-0.001021,0.070374,-0.402956,-0.069723,0.094924,0.116297,0.407037,-0.161765,0.370603,0.045901,-0.154900,-0.210349,0.161324', '2159244', '1307897', '1293656', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5366708', '巴黎宝贝', '剧情', '6年前，富二代马小顺（邓超 饰）来到法国巴黎留学，这座以浪漫著称的城市，俨然成了花花公子马小顺寻欢作乐的天堂。某天他和朋友胡打乱闹跑到精英精子库捐精，他的种子阴差阳错进入了绝望的中年女诗人艾玛（珍·玛琪 Jane March 饰）的体内。原本渴望生出一个金发碧眼可爱小孩的艾玛，最终却生了一个黄皮肤黑头发的小女孩。艾玛一怒之下将精子库告上法庭，造成这一切的马小顺也被勒令遣返回国。这一变故不仅让小顺面临遣返，同时即将走入婚礼殿堂的女友艾米（Clémence saint-preux 饰）也决然离开。为了继续留在法国，小顺必须想法让艾玛的小孩承认他亲生父亲的身份。为此他展开了一连串的留守大作战……©豆瓣', '邓超', '王菁', 5.5, 23439, 'tt1985176', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1139113405.jpg', 9.7, 26.4, 46.3, 13.6, 4, '0.080561,0.166734,-0.751382,0.439049,-0.290057,-0.230928,0.573094,0.242316,-0.278227,-0.115317,0.193375,0.830977,-0.267412,0.367759,0.437046,0.050439,-0.174779,-0.451172,-0.158995,-0.063675,-0.222498,-0.209457,0.048104,-0.165612,-0.011756,-0.204553,0.585007,0.108323,-0.146064,0.347100,0.404603,0.313490,-0.118449,0.268414,-0.128451,0.217820,0.137964,-0.017610,-0.064451,0.266601,-0.083052,-0.146264,0.190344,0.156349,-0.113450,0.179094,0.776675,-0.315980,-0.113813,-0.230511,0.413438,-0.349319,-0.386544,0.160972,0.170633,-0.157977,-0.027905,-0.032212,-0.286515,0.128722,0.392958,-0.271168,-0.518028,0.224851,0.004470,-0.116601,-0.582397,0.286668,0.126893,-0.001819,0.246964,-0.316211,0.160555,0.267715,0.095159,0.458440,-0.113196,0.332329,-0.432328,0.108522,0.598733,-0.085164,-0.124889,0.068808,-0.413581,-0.289177,0.180948,-0.260848,-0.454802,0.099194,0.266947,-0.113559,-0.222036,0.193835,-0.384825,-0.342116,-0.370192,0.063848,0.019874,-0.346731,-0.226199,-0.441467,-0.013158,-0.125941,-0.166554,0.091383,-0.049548,-0.088095,0.682882,-0.575466,0.104923,0.388544,0.268123,-0.798315,0.327713,0.041995,0.158842,-0.229807,-0.156279,0.522367,0.212600,0.319825,-0.009709,0.198993,-0.094405,-0.148550,-0.173756,0.431194', '25834735', '1316525', '26678784', '25731805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5374383', '我的黑色小礼服', '剧情', '毕业季，四个名牌大学表演系的闺蜜各自憧憬着进入社会的生活。慧智（朴韩星 饰）整天花天酒地美容美甲，忽悠大家及时行乐，却无意中成了广告红人。柳敏（尹恩惠 饰）决定跟师兄男友分手，原因是后者的小气和小心眼，在慧智的介绍下，她认识了富二代，并且找到了一份电视台助理的工作，并偶然遇见了中学的粉丝，彼此倾吐对工作的感受。秀珍（车艺莲 饰）处心积虑想做演员，可惜在屡屡受挫，待业的她偷偷篡改了学历为了获得家教的职位。敏姬（刘仁娜 饰）懒得看父母冷战到离异的杯具，决定上补习班拯救烂的要命的英语，却没想到遇到了一个冤家学弟。四个姐妹，分别遭遇了人生之中新的抉择和挑战，当爱情、事业向友谊挑衅的时候，她们又会如何应对……©豆瓣', '尹恩惠', '许仁茂', 7.1, 85264, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1664557181.jpg', 0.8, 5.6, 42.3, 39.8, 11.5, '0.345963,-0.224044,-0.334743,0.666866,-0.264136,-0.428650,0.370628,0.254906,-0.300079,-0.289506,-0.005310,0.711724,-0.321265,0.370352,0.232999,-0.207451,-0.088487,-0.790089,0.133947,-0.110233,-0.131538,-0.421133,-0.110119,-0.100053,-0.169450,-0.083757,0.543857,-0.048188,-0.292537,0.285832,0.384261,-0.005387,-0.052886,0.357839,-0.069442,0.035573,0.104958,0.442729,-0.357736,0.148479,0.090167,-0.135579,-0.055457,-0.029699,0.264229,0.327878,0.688235,0.137088,-0.135022,-0.122157,0.439401,-0.238161,-0.133818,0.132935,0.321165,0.121909,0.363142,0.018168,0.053227,0.015798,-0.019147,-0.079099,-0.585260,-0.088180,0.137068,-0.019305,-0.622399,0.572553,0.031307,-0.014804,0.015828,-0.264845,0.102154,0.259843,0.288803,0.471176,-0.070032,0.140313,-0.252898,0.513239,0.579615,0.151010,0.149110,0.407113,-0.094067,-0.365103,0.127277,-0.120250,-0.529139,0.004553,0.131487,0.004784,-0.172387,0.023067,-0.542925,-0.053510,0.069760,0.008406,0.271148,-0.722822,0.062926,-0.482338,-0.132246,-0.253889,-0.510551,0.118880,0.133139,-0.379196,0.772587,-0.978958,-0.124460,0.488802,0.366572,-0.704818,0.849652,0.380898,-0.081458,-0.415316,0.027798,0.026177,-0.156111,0.172816,0.078358,0.301615,-0.067653,-0.286781,-0.292456,0.221661', '35048413', '3445516', '4301278', '10876425');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5380185', '神秘博士：圣诞颂歌', '喜剧', 'It’s the deepest part of winter, the exact midpoint, Christmas Eve – half way out of the dark. Amy and Rory are trapped on a stricken space liner that’s plummeting through banks of thick icy fog to the surface of the planet below. Only one man has the power to save them; only one man is in possession of a machine that can clear the fog and let them land safely. That man is Kazran Sardick, a rich but lonely old miser who rules Sardicktown with a sky-mast of iron.The Doctor’s only chance of rescuing the ship’s 4,000 passengers is to save Kazran’s soul and show him that life is worth living. For this he needs to go back, way back, to when Kazran was a boy with a life full of promise. But can th', '马特·史密斯', '托比·海恩斯', 8.7, 6046, 'tt1672218', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2867456561.jpg', 0.4, 0.8, 12.7, 35.5, 50.5, '0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.