INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5380919', '红酒烩鸡', '喜剧', '怀才不遇的编剧的亨利（蒂尔·施威格 Til Schweiger饰）本来过着放荡不羁的单身生活，可却被一个相貌可爱古灵精怪的八岁女孩儿玛德莲娜（爱玛·施威格 Emma Schweiger饰）打破，还自称是他的女儿。半路杀出的“女儿”原来是八年前一夜情的结晶，毫无经验的亨利只能硬着头皮照料这位天降“女儿”。与此同时，亨利接到一桩改编畅销小说的大案子，跟他共同执笔的竟然是旧情人凯萨琳娜（雅斯明·格拉特 Jasmin Gerat饰）。亨利本想趁此良机追回最爱，可是调皮的玛德莲娜夹在中间，闹出了一连串啼笑皆非却温情满满的小插曲。亨利能否用拿手菜“红酒烩鸡”赢得小“女儿”的喜爱，又是否能复燃这段来之不易的爱情呢？本片荣获2011德国电影年度卖座冠军。©豆瓣', '蒂尔·施威格', '蒂尔·施威格', 7.8, 24722, 'tt1700258', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2197812094.jpg', 0.5, 2.7, 26.4, 47.8, 22.6, '0.090269,0.088575,-0.558316,0.635926,-0.180088,-0.573818,0.539123,0.070963,-0.353391,0.015016,0.060788,0.493459,-0.332905,0.118360,0.248679,0.219782,-0.129506,-0.485551,0.112903,-0.106018,0.050654,-0.456144,-0.632406,-0.006349,0.058789,-0.198085,0.443225,-0.238383,-0.009876,0.198828,0.737660,0.209970,0.053009,0.150672,-0.083158,0.324115,0.067108,0.076663,-0.212751,0.085557,0.106809,-0.184870,-0.249336,0.016934,0.072267,0.324923,0.388009,-0.369205,0.037122,-0.132207,0.398773,-0.261120,-0.007982,-0.095329,0.034696,-0.160737,0.368541,0.037704,-0.200355,0.036970,0.147791,-0.285011,-0.481373,0.231081,0.030832,-0.083130,-0.646805,0.412526,-0.213892,-0.147315,0.102235,-0.282228,-0.080545,0.306704,0.215925,0.393965,-0.161399,0.113058,-0.533990,0.037116,0.220815,0.171231,-0.197396,0.426011,-0.125566,-0.304278,0.135553,-0.385395,-0.502716,0.181522,0.350760,-0.159124,0.075621,0.232764,-0.432083,0.090174,-0.459264,0.103976,0.260796,-0.373342,-0.271819,-0.331334,0.084530,-0.362530,-0.431667,-0.090945,0.292798,-0.178791,0.789131,-0.531567,0.100698,0.465673,-0.123421,-0.068342,0.505629,0.461274,-0.077726,-0.095647,-0.341871,0.113362,-0.127023,-0.158268,0.196702,0.327575,0.044636,-0.292349,-0.312603,0.552225', '26348103', '1870681', '30361878', '35505100');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5382848', '鸡排英雄', '剧情', '汇集台湾各路美食小吃的八八八夜市，每日都洋溢着温情向上的气氛，阿珠牛排、满妹鸡排、国平（赵正平 饰）以及服务台的美香等人照例为南来北往的游客提供美味小吃。长于夜市的阿华（蓝正龙 饰）新近当选为夜市自治会长，自此与小兄弟阿七调解夜市纠纷，维护摊贩利益。女记者林亦南（柯佳嬿 饰）在夜市附近与小七发生冲突，阿华一见林亦南，心中的情愫不自觉间已被唤醒，但林亦南的生活却自此陷入了一连串混乱，领导痛批、男友分手，又因毁坏电路被惩在八八八进行社区服务，阿华与众摊贩充满人情味的举动渐渐化解了林亦南身在异乡的孤独，双方的关系不再紧张。不久议员张进亮（猪哥亮 饰）联合地产商欲强征八八八土地，阿华带领摊贩保卫夜市，而张进亮，就是多年前抛下阿华的人……©豆瓣', '猪哥亮', '叶天伦', 6.8, 13182, 'tt1887820', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1038845813.jpg', 1.8, 8.9, 45.8, 34.4, 9.1, '0.198324,-0.023441,-0.511606,0.314822,0.288521,-0.276909,0.415786,0.579583,-0.285886,0.003070,0.046793,0.290420,-0.476526,0.239042,0.421291,-0.403262,-0.309613,-0.546097,-0.224529,0.035492,0.016168,-0.251226,0.021388,-0.499118,-0.247149,0.058747,0.180485,0.262868,-0.194872,0.481843,0.201054,0.158226,-0.525089,0.363269,0.082732,0.001993,0.093529,-0.010572,-0.458339,-0.223963,-0.369906,-0.346658,-0.192912,-0.060160,0.267921,0.355722,0.678146,-0.139275,-0.147898,-0.035503,0.056164,0.222120,-0.020618,0.060821,0.330476,0.021424,0.183439,0.075772,-0.286885,0.074231,-0.008595,-0.041398,-0.165499,0.068359,0.091329,0.056630,-0.360477,0.558840,0.079766,-0.122293,0.099965,-0.120515,0.237300,0.207796,0.063579,0.269134,0.284844,0.073775,-0.227421,0.164174,0.510286,0.251437,0.095062,-0.026210,-0.441548,-0.266350,0.055694,0.094667,-0.170901,-0.304070,0.292563,-0.090381,0.216056,0.372724,-0.774879,-0.024465,0.025278,-0.300476,0.221452,0.060479,-0.157698,-0.828390,0.051779,-0.298832,0.006559,0.241208,0.358274,0.107707,0.700729,-0.687114,0.151969,0.132579,0.174195,-0.608157,0.479116,0.045718,-0.023914,-0.143275,-0.439102,0.023597,-0.013948,0.201606,0.265177,0.092935,-0.539039,0.035962,-0.180531,0.240931', '3041753', '3147969', '1294009', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5382887', '巨额交易', '剧情', '白领张泽（蓝正龙 饰）遭到公司辞退，他和无业多时的好友刘易郡（乔任梁 饰）拜访老大哥王云鹏（王云鹏 饰）寻找工作机会，恰逢后者得到了为温州房地产商销售迪拜楼盘的机会。于是兄弟三人不顾女友反对、出卖家传文物奔赴中东淘金，迪拜的风光还未尽收眼底，他们就收到了项目资金断裂的糟糕消息，而缺口高达二十亿。三人不甘失败，决定空手套白狼堵住缺口，在稳住地产商黄总（叶大鹰 饰）后，匆匆返回北京寻找资金。在接洽了熬死富翁老公的女富婆、大话连篇的前领导勤务员和粗犷的煤老板等一系列目标后，黄总对三人的耐心到了尽头，而他们此刻又纷纷后院起火，发财梦眼看破碎……©豆瓣', '蓝正龙', '马俪文', 4.7, 6998, 'tt2471282', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1303156340.jpg', 18.5, 38.4, 33.3, 7, 2.8, '-0.090954,0.032547,-0.583701,0.054585,0.169245,-0.307667,0.284997,0.356292,-0.482159,0.017629,0.018196,0.359102,-0.168207,0.010759,0.381864,-0.217262,-0.257781,-0.583704,-0.057790,-0.157966,-0.131166,-0.294458,-0.052614,-0.374219,-0.232310,-0.083938,0.441767,0.299475,0.038112,0.418256,0.280411,-0.031938,-0.296514,0.580135,-0.124394,0.134614,0.278430,-0.034724,-0.413424,0.449846,-0.070074,-0.178527,0.085953,0.006921,0.078455,0.599793,0.433882,0.236562,-0.045909,-0.023583,0.172730,-0.032631,0.012746,0.062872,0.462091,-0.031947,0.247140,-0.008590,-0.378866,-0.248986,0.150983,-0.083933,-0.416586,0.084539,0.080932,0.057767,-0.663347,0.409550,-0.148335,0.213174,-0.047640,-0.501272,0.275398,0.377516,0.103362,0.131666,0.006195,0.205367,-0.336037,0.472948,0.340097,0.019444,0.112041,0.088980,0.160234,-0.329130,0.070249,-0.051073,-0.216870,-0.188658,0.469287,0.225713,0.052681,-0.153233,-0.491966,-0.280799,-0.293655,-0.163477,0.174136,-0.127043,-0.108558,-0.634246,0.068372,0.164502,0.036181,0.342314,0.142712,0.149521,0.343918,-0.418735,-0.130331,0.300857,0.484695,-0.587723,0.620221,-0.515284,0.141301,-0.439560,0.072169,-0.163344,0.055820,0.399433,0.336636,-0.017246,-0.263077,-0.579560,-0.010089,0.083969', '25908042', '1293607', '25837175', '1431694');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5383158', '曼联重生', '剧情', '1956年，19岁的Bobby Charlton（杰克·奥康奈尔 Jack O''Connell 饰）在助理教练Jimmy Murphy（大卫·田纳特 David Tennant 饰）的帮助下第一次获得在曼联一线队的出场机会。当时的曼联队在主教练Matt Busby（多格雷·斯科特 Dougray Scott 饰）管理下，人才济济，拥有众多天才球员，被称为“巴斯比的孩子”。其中就有Mark Jones,，Duncan Edwards（山姆·克拉弗林 Sam Claflin 饰）和Eddie Colman等希望之星。曼联在欧洲冠军联赛客场对阵德国的拜仁慕尼黑，随后就要赶回英国参加联赛。在Busby的一再要求下，英国足总始终不同意推迟曼联的联赛，导致曼联刚在德国踢完球就得搭乘飞机返回英国。德国的暴风雪让飞机一再延迟起飞，在飞机作了最后一次尝试之后，不幸发生了.....这就是“慕尼黑空难”，许多天才球员因此丧生，Bobby Charlton要怎样和主教练Busby带领曼联重生？本片为BBC的电视电影。', '大卫·田纳特', '詹姆斯·斯特朗', 8.5, 7844, 'tt1777034', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2360432019.jpg', 1, 1.5, 15.2, 33.6, 48.7, '-0.327981,0.236101,-0.658861,0.457564,-0.000225,-0.528067,0.092148,0.096177,-0.462439,0.085490,0.297050,0.896724,-0.480613,0.040579,0.503177,-0.393018,-0.288527,-0.675178,0.124293,0.016262,-0.499165,-0.549176,-0.307489,-0.038586,0.266144,-0.302606,0.979415,0.199428,-0.026622,0.464029,0.029603,0.289011,0.677170,0.182563,-0.240820,0.175900,0.271365,0.196961,-0.438477,0.719605,0.093114,-0.055681,-0.521615,-0.245990,0.557750,0.180006,0.529639,-0.173186,0.262309,-0.119207,0.193279,-0.221724,0.150488,0.207844,0.427469,-0.085235,0.125426,0.277007,-0.034295,0.412732,-0.291634,0.107325,-0.532281,0.390180,-0.019203,-0.037344,-0.720979,0.745460,-0.595657,0.316521,0.142039,-0.102828,-0.026174,0.630918,0.142620,0.038144,-0.022711,-0.103762,-0.485527,0.017966,0.772279,-0.070902,-0.272085,-0.054127,0.058968,-0.286391,0.037584,-0.497676,-0.388515,0.295964,0.561545,-0.177134,0.157083,0.293069,-0.513921,0.248460,-0.278440,-0.719112,0.113125,-0.244246,0.234291,-0.773683,0.333185,-0.057306,-0.222144,0.167304,0.043567,0.143221,0.647373,-0.664971,0.227576,0.742673,0.208026,-0.230192,0.649898,0.107802,0.365872,-0.258282,0.014420,0.205666,-0.124773,0.100264,-0.250520,0