INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5384590', '墓地邂逅', '悬疑', '电视台制作人杰瑞•哈尔福德与信心满满的青年兰斯•普雷斯顿（辛恩·罗格斯 Sean Rogerson 饰）合作，制作了一档名为《墓地邂逅》的灵异纪实节目，他自称年少时曾遭遇超自然现象，所以长久以来一直致力于揭示灵魂的真面目。此次，他和他的团队来到了一家始建于1893年的医院——科林伍德精神病院，该医院曾受纳上千名病患，1963年因闹鬼被迫关闭。兰斯团队决定将自己反锁在医院8小时，通过摄像机以及其他高精仪器寻找鬼魂的蛛丝马迹。为了制造恐怖氛围，兰斯不惜弄虚作假，可是他很快发现这座医院真的有什么东西存在，他们将面临最为恐怖与难熬的不眠之夜……©豆瓣', '本·威尔金森', '柯林·米尼汉', 6.8, 20164, 'tt1703199', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2183938080.jpg', 2.5, 10, 42.7, 33.3, 11.6, '0.089419,-0.044340,-0.491586,0.202587,0.018452,0.109342,0.582590,-0.024127,-0.952717,-0.647122,0.196808,0.580401,-0.281477,0.034266,0.215173,-0.150284,-0.349380,-0.505917,0.021987,-0.332145,-0.439495,-0.402951,-0.292874,-0.440975,0.153373,-0.234418,0.485484,0.156067,-0.044859,0.088072,-0.060167,0.652168,-0.216910,0.275834,0.063691,-0.292286,0.144610,-0.037451,-0.379436,0.146389,0.059939,-0.312419,-0.219304,0.089456,0.009890,0.002908,0.496881,-0.074283,-0.304602,-0.115391,0.335387,-0.166327,-0.068137,-0.077816,0.200848,0.112014,0.236357,0.434856,-0.149769,-0.202847,0.101957,-0.206244,-0.589207,-0.057016,0.049821,-0.018732,-0.322625,0.163397,-0.241662,0.143968,0.137219,-0.339999,0.192561,0.393311,0.454899,0.332090,0.040707,-0.122017,-0.474407,0.088571,0.483778,-0.318530,-0.057550,0.174433,-0.252666,-0.530743,-0.213205,-0.225851,-0.358748,0.349804,0.188308,0.137993,-0.166468,0.225256,-0.529513,-0.163598,-0.260264,-0.243533,0.236461,-0.007458,-0.086882,-0.897850,-0.154635,-0.072462,-0.235373,-0.164118,-0.019585,-0.094903,0.600502,-0.755299,0.321063,0.535337,0.368364,-0.409441,0.775278,-0.275490,-0.041694,-0.212557,-0.007678,0.325821,0.033824,0.591699,0.042039,0.139392,0.158560,-0.083793,-0.268793,0.375226', '26341750', '1297659', '2297262', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5386987', '红手指', '悬疑', '两年前，加贺恭一郎（阿部寛 饰）尚为练马警署的一名刑警。适值此时，他的父亲（山崎努 饰）病重住院，加贺却从未探望，父子间的隔膜难以打破。这一日，加贺的辖区内发生一起命案。年仅6岁的女孩春田井优菜被人杀害，凶手是附近居民区的一名初中生，这个名叫直巳（泉澤祐希 饰）的男孩在学校备受欺负，在家中则将自己封闭起来。为了掩盖儿子的罪行，直巳的父母前原昭夫（杉本哲太 饰）和八重子（西田尚美 饰）费尽心思搬运尸体，伪造现场。虽则如此，但是目光如炬的加贺刑警依然从中看出了端倪……本片根据东野圭吾的同名原著改编，系同名电视剧的SP。©豆瓣', '阿部宽', '土井裕泰', 7.8, 16798, 'tt1789683', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2561702125.jpg', 0.3, 1.9, 27, 50.6, 20.2, '0.174718,-0.092023,-0.469402,0.411255,-0.106803,-0.272468,0.648435,0.054490,-0.613767,-0.684464,0.285056,0.553111,-0.174523,0.368132,0.135076,0.023302,-0.255445,-0.552291,-0.365636,-0.421323,-0.227946,-0.341511,-0.214138,0.061684,-0.219413,-0.185893,0.651879,-0.021386,0.011353,0.495644,0.333841,0.418768,-0.195450,0.075551,-0.054550,0.139045,0.172597,0.083022,0.059171,0.049421,-0.204067,-0.416947,-0.132322,0.122820,-0.111348,0.522640,0.818728,-0.132983,-0.079645,-0.251196,0.360712,0.078855,-0.155328,0.096049,0.642636,-0.062255,0.105256,0.342197,-0.393341,-0.147655,-0.061101,0.153816,-0.522613,-0.129450,0.380741,0.156728,-0.316393,0.292837,-0.159999,-0.029108,0.153524,-0.235826,0.005618,0.331330,0.133908,0.174375,-0.321967,-0.016245,-0.443419,0.213524,0.545549,-0.151150,-0.082745,0.161713,-0.339726,-0.312108,-0.148392,-0.366492,-0.533722,0.139801,0.015445,-0.042672,-0.055796,0.025193,-0.181270,-0.267654,-0.192679,0.126478,0.068576,0.032867,-0.107852,-0.583962,-0.040010,-0.431085,-0.199753,0.106030,0.177905,-0.314265,0.457273,-0.560781,0.113472,0.361947,0.202962,-0.072687,0.571290,0.131439,0.068135,-0.192824,-0.223450,0.009179,0.292217,0.360363,0.037267,0.370189,-0.184346,-0.391874,-0.568692,0.118980', '3811356', '27040737', '1306544', '1421734');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5387015', '蜡笔小新：呼风唤雨！黄金的间谍大作战', '动画', '某天，小新（矢島晶子 配音）闲逛的时候捡到一个动感超人的面具，戴上面具后，小新发现自己竟然能和动感超人通话。他被任命为代表正义的动感间谍，专门与邪恶势力作战，并且见到了他的搭档——7岁女孩苏诺萌·柠檬（愛河里花子 配音）。在柠檬的带领下，小新开始作为动感间谍的艰苦训练。在这一过程中，面向凶恶的怪大叔不断偷袭小新，而在这一系列事件背后，似乎又隐藏着两个神秘的国家——无声屁共和国与不放屁王国。看似善良的柠檬也变得正邪难辨。不久，小新更和柠檬闯入了困难重重的不放屁王国……本片根据臼井義人的同名原著改编，是《蜡笔小新》系列第19部剧场版。©豆瓣', '矢岛晶子', '增井壮一', 7.8, 9826, 'tt1887784', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1053499493.jpg', 0.4, 3.2, 30.4, 39.4, 26.7, '0.493771,0.093357,-0.550458,0.777268,0.030923,-0.184200,0.597110,0.103476,-0.250263,-0.070404,0.203487,0.582668,-0.187081,-0.108764,0.214092,0.017987,-0.440290,-0.591257,-0.457816,0.010296,-0.387005,-0.297633,-0.370036,-0.072700,-0.039256,-0.384136,0.629414,0.086713,-0.253712,0.408652,0.552026,0.210605,-0.249346,0.284153,-0.171034,0.022145,0.379603,-0.034981,0.164892,0.364454,-0.124393,-0.281342,-0.067162,0.120828,-0.213864,0.383295,0.711338,-0.426574,-0.164081,-0.296699,0.465646,-0.258957,-0.383795,-0.066871,0.400217,-0.049651,0.357197,0.259842,0.064183,0.131058,-0.063512,-0.230847,-0.732337,-0.022223,0.024338,0.413179,-0.421784,0.281984,-0.225747,-0.038391,0.458419,-0.207435,0.267679,0.452289,0.465993,0.404029,-0.064577,0.069745,-0.491155,0.280353,0.390792,0.140108,-0.292629,0.357659,0.006237,-0.438500,0.051439,-0.133615,-0.356999,-0.039781,0.212365,-0.163350,-0.177634,0.065211,-0.921081,0.127872,0.067537,-0.218530,0.051795,-0.407600,-0.358348,-0.541772,-0.213169,-0.521294,-0.140405,0.197704,0.141220,-0.157775,0.760731,-1.077616,0.053154,0.461315,-0.026031,-0.151393,0.420608,0.227331,-0.176392,-0.241064,-0.213413,-0.126219,0.274281,0.338399,0.234079,0.658274,-0.040834,-0.256444,-0.457438,0.259662', '1420088', '3044878', '4127270', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5387021', '嚎叫', '惊悚', '停车场内，乞丐目睹了一场自焚事件，毒贩在车内被熊熊烈火化为灰烬。警方随即封锁现场，仕途不得意的中年警官尚吉（宋康昊 饰），刚调入刑警队恩英（李娜英 饰），共同接手此案。经过尸检，尚吉发现死者的皮带扣中暗藏玄机，而且在事故发生前，死者曾经被烈性犬咬伤。尚吉和恩英顺藤摸瓜，查到了一个逼迫未成年少女卖淫、贩毒的犯罪集团。但是在查案过程中，贪功心切的尚吉并不向领导汇报，也不与同僚分享案情。与此同时，搭档恩英还要忍受被其他前辈羞辱。案发后，烈性犬继续伤人，而且目标准确，一击毙命，此案经媒体渲染后引起高层关注，恩英不顾尚吉阻拦，孤注一掷沿着训犬师的线索跟踪追查，逐渐接近了真相，然而死亡的威胁也随之而来……本片根据日本女小说家乃南朝获得日本直木奖的小说《冰冻的犬齿》改编拍摄。©豆瓣', '宋康昊', '庾河', 6.6, 7218, 'tt2186819', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1562644972.jpg', 1.6, 9.1, 55.9, 26.1, 7.4, '0.265411,-0.107440,-0.510214,0.292574,0.236801,0.103698,0.729824,-0.103829,-0.278333,-0.124426,0.437060,0.203690,-0.262710,-0.178282,0.183956,-0.252003,-0.360448,-0.565538,-0.048152,-0.131690,-0.259698,-0.479121,-0.146241,-0.315267,-0.076424,-0.249417,0.663350,0.183788,-0.418362,0.428514,0.274599,0.352269,-0.469661,0.431224,0.070903,0.095411,0.412410,-0.135432,-0.154145,0.257844,0.116163,-0.465472,0.103076,0.162280,-0.130215,0.628740,0.622134,-0.336496,-0.295180,-0.267580,0.326414,-0.372398,0.093065,0.224828,0.641951,0.204104,0.208613,0.477518,-0.296036,-0.002948,-0.060465,0.196499,-0.439854,-0.132890,0.222179,0.367735,-0.225923,0.001634,-0.194493,0.158455,0.079268,-0.047081,0.212433,0.324367,0.285485,-0.010827,0.027979,0.058808,-0.312830,0.217356,0.653048,-0.182417,-0.130748,0.123983,-0.041454,-0.447148,0.197882,-0.050252,-0.079133,0.049312,0.337138,0.079372,-0.170409,0.286540,-0.184138,-0.321665,-0.296662,0.076994,-0.194281,-0.112962,-0.132170,-0.582740,-0.170639,0.079754,0.008842,-0.049523,0.173027,-0.237011,0.309588,-0.333922,0.060193,0.513310,0.191330,-0.521587,0.306130,-0.027780,0.198216,-0.077893,-0.199016,-0.004508,0.604849,0.528362,0.074403,0.135268,-0.079153,-0.533958,-0.206959,-0.104478', '25919961', '4280770', '4023433', '3263169');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5387025', '厕所女神', '剧情', '在一个平凡的小镇，在酒店底层工作的单身妈妈植村洋子（夏川結衣 饰）独自抚养着四个儿女：桃子、光生、美绪和花菜（芦田愛菜 饰）。最小的花菜顽皮可爱，是家中的开心果，不过她也常常觉得自己不受重视，受到委屈后便跑到隔壁的外公（小林稔侍 饰）、外婆（岩下志麻 饰）家里哭鼻子。不久，慈祥的外公去世，外婆的脸上时时挂着落寞的神情。花菜搬到隔壁居住，祖孙俩相依相守，从彼此的身上得到了幸福与快乐。时间倏忽而去，转眼花菜（北乃きい 饰）长大，小小的房子再也无法圈住她的脚步，而外婆则一如既往鼓励着她持续前行……本片根据植村花菜的同名原著改编。©豆瓣', '北乃绮', '竹园元', 7.9, 16181, 'tt1789089', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2137602075.jpg', 0.3, 1.9, 24.8, 47.6, 25.4, '0.103255,-0.053196,-0.639536,0.508734,-0.129981,-0.494447,0.741603,0.705081,-0.211462,-0.091734,0.097770,0.576246,0.110878,0.782383,-0.092370,0.101600,-0.236445,-0.221378,-0.174297,-0.083479,-0.166332,-0.097180,0.042081,-0.167167,-0.096643,-0.119068,0.381696,-0.077625,0.193643,0.784596,0.211945,-0.065273,-0.372855,0.180232,-0.407688,0.359008,-0.117234,0.277094,-0.045388,0.061402,0.039615,-0.072383,-0.268821,-0.091331,0.134142,0.170331,0.885187,0.002302,-0.284159,0.055806,0.169454,0.004325,-0.073420,0.131620,0.279542,0.013294,0.340993,0.009038,-0.478674,0.327133,0.159656,-0.223488,-0.294075,0.042383,0.103228,0.212141,-0.605369,0.618926,-0.070380,-0.372170,0.429014,-0.482944,0.169123,0.288429,-0.150058,0.737040,-0.429849,0.325198,-0.405043,0.259857,0.427488,-0.217524,-0.059345,0.337439,-0.353062,-0.094030,0.132428,-0.304079,-0.631960,-0.038884,0.129186,0.042513,-0.133050,0.082103,-0.429976,0.157524,0.073144,-0.107830,0.195284,-0.484580,-0.091426,-0.489405,0.011658,-0.732725,-0.498372,0.199948,-0.005288,-0.164583,0.748607,-0.559914,0.442965,0.263619,0.223234,-0.208157,0.643917,0.029794,0.224977,-0.201650,0.143828,0.363945,-0.027499,0.242220,0.336194,0.249785,-0.288260,0.221049,-0.593069,0.387219', '4030411', '25790555', '3077680', '4066127');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5401681', '死亡的游戏', '动作', '李小龙真正的遗作：《死亡的游戏》（比《死亡游戏》多了个“的”字，主角叫“海天”，而不是“卢比利”）《死亡的游戏》于2000年发布，收录于《勇士的旅程》当中。《勇》是一部半纪录片半电影片。数十年来流传的“李小龙的最后之作”《死亡游戏》，其实真正的主演是唐龙，李小龙本人的原创镜头只有十几分钟，其余皆为唐龙替身演出，只是片尾的CAST表依然署上李小龙的名字，唐龙也因此成为了不是主演的主演。这部补拍的影片与李小龙原来的构思完全不同，原故事讲一班绝世高手到一座五层塔夺取一件宝物，塔内每层都由一位高手把关。当日除了李小龙还有其余两个演员（补拍版中两人的戏份被删除）一齐上塔闯关，而李氏在戏内一边打斗一边说出他的武学理论，在七九年上映的版本中却全部删剪了。唐龙原名金泰中，韩国功夫影星，主演过《死亡游戏》和《死亡塔》。在这里还要指出一点的就是《死亡塔》里根本就没有李小龙，里面的片段都是他身前所排的几部电影里的一些剪接片段，和唐龙（替身）的背影。在这部《死亡游戏》里面讲述的故事是：巨星奴彼力被黑帮追上杀而上演了一幕瞒天过海的死亡游戏，在暗中复仇。最后一举直捅了黑帮的老巢……很可惜的是，被修改过后的1978版《死亡游戏》根本不是李小龙当年的原始构思。剧中只保留了部分的打斗场面（李小龙当年所拍的原始片段），其中还删节掉了将近12分钟的李小龙对韩国合气道高手（豹殿）的精彩打斗（在香港上映的版本则有补上），还有在虎殿里对依鲁山度大师的二节棍打斗、以及对黑人贾巴尔的也有删节。所以我们看见的叫《死亡游戏》的根本不是真正的《死亡游戏》，也不是李小龙当年的原始构思。李小龙当年的原始构思是： 　　李小龙是一名少林弟', '李小龙', '大串利一', 8.6, 4870, 'tt0297038', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2526270491.jpg', 0.3, 0.7, 11.8, 42, 45.2, '0.352519,-0.058326,-0.579506,0.692615,0.126394,-0.124284,0.721161,-0.311849,-0.424794,-0.334226,0.382235,0.775921,-0.406000,0.195343,0.039042,-0.301680,-0.152153,-0.702198,-0.340871,-0.201818,-0.278767,-0.346144,-0.357006,0.046997,-0.256207,-0.286208,0.836119,0.182465,-0.460290,0.140686,0.404423,0.033128,-0.190517,0.238943,-0.081021,0.174996,-0.065927,-0.072607,-0.238981,0.338843,-0.014751,-0.285552,-0.162623,0.149547,-0.146391,0.489518,0.670895,-0.354104,-0.011571,0.210957,0.530073,-0.295050,-0.395527,-0.267686,0.430540,-0.030516,0.510793,0.323339,0.055158,0.259360,-0.280417,-0.178972,-1.091275,-0.170458,0.233619,0.177909,-0.320731,0.468773,-0.131414,-0.085163,0.094083,-0.104932,0.323459,0.056174,0.466799,0.396577,-0.078926,-0.248581,-0.506008,0.649881,0.346049,0.042672,-0.176443,0.574996,0.120281,-0.577665,-0.508876,-0.426859,-0.170370,0.254176,0.252441,0.015134,-0.169282,-0.000336,-0.622311,0.090738,-0.036550,-0.379549,-0.178619,-0.383839,-0.124950,-0.859722,-0.114016,-0.300443,0.017124,-0.126507,0.205227,-0.381626,0.897926,-0.719420,0.233737,0.380434,0.194600,-0.208369,0.705524,0.142414,-0.025178,-0.085905,-0.009163,0.109866,0.007969,0.172129,0.102900,0.399858,0.033058,-0.427314,-0.619595,0.722831', '25880986', '27602116', '3318306', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5403927', '轻音少女 剧场版', '剧情', '樱丘高中轻音乐部，平泽唯（丰崎爱生 配音）、秋山澪（日笠阳子 配音）、田井中律（佐藤聪美 配音）和琴吹紬（寿美菜子 配音）这四个搞怪不断、俏皮可爱的女孩即将迎来毕业的日子。为了纪念这最后的时刻，她们决定自行组织毕业旅行，经过一番令人捧腹的讨论后，最终女孩们将目的地锁定在英国伦敦。与她们同行的还有同属轻音部的学妹中野梓（竹达彩奈 配音）。唯等四人商量，要在毕业前为梓喵创作一首歌曲作为赠别礼物，她们一面应付旅途中的各种状况，一面又要尽快完成创作，古板的伦敦也被女孩们青春快活的气息所感染……本片根据日本漫画家Kakifly（かきふらい）的同名四格漫画改编。©豆瓣', '丰崎爱生', '山田尚子', 9.2, 17589, 'tt1909796', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2040458823.jpg', 0.3, 0.4, 6.2, 22.7, 70.4, '0.093715,0.035228,-0.048422,0.515092,0.135704,-0.099879,0.308558,0.158976,-0.138641,-0.370873,-0.041827,0.365800,-0.381055,0.507848,0.384034,-0.242163,-0.545216,-0.708898,-0.099460,0.000459,0.157539,-0.084594,0.244306,0.012362,-0.216067,-0.178953,0.757984,-0.104933,-0.009475,0.548402,0.433301,0.159633,-0.452389,-0.105419,-0.056056,0.018110,0.269041,0.112863,-0.146363,0.295496,-0.054576,-0.065900,-0.334404,-0.132413,0.157497,0.135456,1.037153,0.054520,0.042991,-0.054677,0.393342,-0.030816,0.073900,0.060923,0.247569,0.296335,0.401324,0.258980,-0.225063,0.199350,-0.309524,-0.282682,-0.464775,0.094349,0.239717,0.031014,0.022833,0.331745,0.037627,-0.007948,0.553576,-0.296531,-0.037498,0.271471,0.526118,0.256583,-0.136218,0.410296,0.123851,0.401209,0.604974,-0.148427,0.013261,0.358052,-0.013876,-0.387058,-0.021869,-0.202748,-0.211365,0.146783,-0.105228,0.119920,0.092378,-0.203538,-0.667559,-0.215899,0.059984,-0.236058,0.137806,-0.426034,0.065644,-1.042923,0.084126,-0.216697,-0.139414,-0.040293,0.288452,-0.138976,1.119481,-0.664067,-0.072012,0.556921,-0.057947,-0.194205,0.292915,0.294608,-0.020729,-0.257866,0.040674,-0.082882,-0.020831,0.238992,-0.019573,0.604525,-0.061118,-0.118561,-0.597171,0.322956', '3811356', '2369613', '10174444', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5407055', '爱情储蓄罐', '喜剧', '智雄（宋仲基 饰）大学毕业后便整日游手好闲。某天他认识了从对面天台跳过来捡瓶子的怪女人红实（韩艺瑟 饰）。守财如命的红实盯上了智雄住所的搬迁费，她暗中找到智雄的房东，把租房合同改到自己名下，令智雄无家可归。看到对方依旧乐观的样子，受到触动的红实承诺帮助他在短期内攒到巨款。毫不知情的智雄对红实的“善心之举”怀抱感激。他开始学习无条件听从红实的命令，但是时常暴露的败家本性又总会惹恼红实。红实虽然异常吝啬，内心深处却也有着女人的梦想。她把辛苦攒到的钱交给意中人（李相烨 饰）托管，期望有一天能成为配得上对方的好女人。却不料一日意中人与情人携款逃跑，令红实深受打击。而智雄也终于得知当初无家可归的内幕，感到被利用的他是否会原谅红实？©豆瓣', '宋仲基', '金正焕', 6.5, 10823, 'tt2115426', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1249968135.jpg', 1.5, 11.4, 53.5, 25.7, 7.9, '0.081782,0.186874,-0.611698,0.192634,-0.487274,-0.189392,0.318818,0.083069,-0.292281,0.009261,0.248545,0.515639,-0.057370,0.156758,0.287591,0.215412,0.135388,-0.538782,0.163213,-0.240983,-0.053136,-0.372733,-0.180571,-0.191822,-0.206775,-0.314203,0.488240,0.252301,-0.162839,0.362128,0.378658,0.369793,0.223765,0.469896,-0.270984,0.134494,-0.236939,0.181244,0.072140,0.048757,0.000927,-0.283425,-0.077956,0.230130,0.084002,0.366210,0.543049,-0.047507,-0.455959,-0.031250,0.481129,-0.213841,0.073869,0.119431,0.105435,0.121296,-0.032379,0.331823,-0.511814,0.096660,0.109703,0.054348,-0.500347,-0.179181,0.163408,-0.005696,-0.618656,0.166237,-0.149831,0.166216,-0.036915,-0.385978,-0.072722,0.196886,0.029242,0.242625,-0.187266,0.210311,-0.603764,-0.040266,0.345571,-0.241046,-0.005830,0.377593,-0.013440,-0.227201,0.306241,-0.333526,-0.329708,0.013924,0.119307,0.239101,-0.336522,-0.134156,-0.318378,-0.033810,-0.266614,0.076659,0.171375,-0.645184,-0.109470,-0.198122,-0.226772,-0.200281,-0.461085,0.131228,0.162822,-0.479938,0.702688,-0.622067,0.271662,0.573362,0.506199,-0.544571,0.482021,0.128269,-0.165936,-0.179114,-0.067404,0.202053,0.315600,0.205872,0.085700,-0.094830,-0.263025,-0.263926,-0.121400,0.279498', '1877596', '25907029', '1292719', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5407085', '火影忍者剧场版：血狱', '动画', '在一段晦暗的日子里，云隐、雾隐和岩隐的忍者接连遭到神秘忍者的袭击，而从这些地方发来的通缉令全部指向了木叶村的漩涡鸣人（竹内顺子 配音）。鸣人百口莫辩，最终被五花大绑，投入了“血狱”鬼灯城。鬼灯城地处大海中央的孤岛之上，四周波涛汹涌，怒浪滔天，小岛悬崖峭壁，地势险恶。此处囚禁着或罪大恶极或忠义至上的上忍，加上城主无为（寺杣昌纪 配音）严酷的统治及严密防卫，鬼灯城堪称绝对无法逃脱的死地。即使明知不可为，鸣人也要想方设法从此地逃脱。在这一过程中，令他蒙受不白之冤的阴谋渐渐浮出水面……本片根据日本漫画家岸本齐史的同名经典原著改编，为该系列电影版的第八部。©豆瓣', '竹内顺子', '村田雅彦', 6.9, 9618, 'tt1999167', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1157300597.jpg', 1.9, 9.4, 44.8, 29.4, 14.6, '0.015605,0.144681,-0.504988,0.836201,0.451380,0.126055,0.484799,0.260991,-0.437274,-0.166268,0.117486,0.559239,0.170821,0.141110,0.081305,0.086457,-0.193660,-0.479280,-0.565928,-0.371779,-0.432039,-0.190171,-0.132967,-0.146562,-0.170576,-0.087759,0.825414,0.729639,-0.261847,-0.035185,0.234787,0.438523,-0.554171,0.264751,0.058193,-0.233951,-0.181127,-0.203606,-0.020605,0.356195,-0.370943,-0.342041,-0.174101,0.225214,-0.102545,0.411621,0.887028,-0.346817,-0.221722,-0.137159,0.300387,-0.534547,-0.141525,-0.027092,0.544811,-0.147327,-0.107709,0.334450,-0.183236,-0.214392,0.024337,-0.264461,-0.706695,-0.230415,0.309710,0.053541,-0.294547,0.277840,0.092142,-0.195424,-0.041306,0.015321,0.073139,0.142637,0.283421,0.092688,-0.240121,0.000138,-0.077399,0.250765,0.421478,0.025890,-0.253426,-0.228784,-0.092386,-0.220119,-0.135374,-0.476646,-0.264898,-0.166555,0.334284,0.067522,-0.307766,0.411042,-0.322895,0.046829,-0.298772,-0.149695,-0.277976,-0.090666,-0.350916,-0.588327,0.160492,-0.106575,0.019800,0.108260,0.002705,0.058179,0.537690,-0.558891,0.147988,0.526568,0.076488,-0.024958,0.403271,0.074382,-0.079477,-0.010792,-0.229026,0.236776,0.195339,0.677201,0.231193,0.126500,-0.148542,-0.350376,-0.411338,0.394924', '10467125', '26759820', '25880986', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5413813', '纽约两日情', '喜剧', '玛丽昂（朱莉·德尔佩 Julie Delpy 饰）是一位职业摄影师，目前，她与做电台主持人的男友明格斯（克里斯·洛克 Chris Rock 饰）过着同居的生活，同时，与他们住在一起的还有两个孩子和一只猫，那两个孩子分别来自于玛丽昂和明格斯的上一段感情。虽然是这样特殊的四 口之家，但这对情侣的生活过的平静又充实，玛丽昂甚至开始策划起属于自己的摄影展来，没想到，正是这展览打破了她原有的宁静生活。听说女儿要在异国举办个展，玛丽昂的父亲带着她的妹妹以及妹妹的男友立刻踏上了通往纽约的旅程，他们丝毫没有想过，这突如其来而又莽撞的行为会给玛丽昂添多大的麻烦。果不其然，自从三人来到纽约并闹出各种笑话后，玛丽昂和明格斯之间的关系开始急转直下，在顾及亲人感受的同时，玛丽昂能否挽回这段珍贵的感情呢？©豆瓣', '朱莉·德尔佩', '朱莉·德尔佩', 6.7, 5460, 'tt1602472', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1671823387.jpg', 1.4, 8.9, 49.2, 32, 8.5, '0.439010,-0.092527,-0.792132,0.699095,0.069633,-0.444076,0.995062,0.009055,-0.531088,-0.164394,0.133667,0.720642,-0.343346,0.366142,0.330938,0.171016,-0.280995,-0.534655,-0.096540,-0.092000,-0.183292,-0.576849,-0.331913,0.017550,-0.038759,-0.284524,0.358160,-0.287151,-0.106640,0.618378,0.371821,0.252164,-0.028352,0.446534,-0.110479,0.085481,0.053982,0.274616,-0.503612,-0.031183,0.184868,-0.016273,-0.109175,0.261652,0.166537,0.348549,0.704887,-0.447955,-0.160043,-0.107753,0.306514,0.055091,-0.027587,0.049208,0.184663,-0.072115,0.178799,0.298393,-0.148480,0.050766,-0.004069,-0.137434,-0.696408,0.291413,-0.029442,0.249426,-0.636330,0.682466,-0.150090,-0.275443,0.096472,-0.385366,0.223830,0.577800,0.124402,0.470037,-0.220742,0.162168,-0.457181,-0.084251,0.816545,-0.031865,-0.174482,0.453024,-0.373771,-0.352301,-0.047702,-0.107473,-0.487522,-0.002608,0.085656,0.016287,-0.161326,0.227854,-0.604836,0.144132,-0.247604,-0.188806,0.246029,-0.489936,-0.135235,-0.713772,0.047319,-0.712892,-0.455105,-0.055365,0.079699,-0.366082,0.602718,-0.991218,0.229938,0.457337,0.302769,-0.495887,0.509119,0.376471,0.179912,-0.205315,-0.449141,0.174866,-0.106976,0.223350,0.260886,0.368346,0.341412,-0.074596,-0.137885,0.536364', '1308755', '3111650', '1292219', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5415301', '蔚蓝深海', '剧情', '二战后，英国律师William Collyer（西蒙·拉塞尔·比尔 Simon Russell Beale 饰）的妻子Hester Collyer（蕾切尔·薇兹 Rachel Weisz 饰）邂逅了退役的飞行员Freddie Page（汤姆·希德勒斯顿 Tom Hiddleston 饰）。生活空虚寂寞的Hester和年轻英俊的Freddie陷入了一段不伦之恋。此事不久即被Hester的丈夫William发现。后来，Hester认为Freddie不再爱她了，于是尝试自杀。她没有成功，Freddie在读完她的遗书后勃然大怒。最后，Freddie终于决定离开她，去一个遥远的地方继续他的飞行员生涯。Hester只能望着Freddie离开的背影黯然神伤......©豆瓣', '蕾切尔·薇兹', '特伦斯·戴维斯', 7.1, 18910, 'tt1700844', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1231920047.jpg', 0.8, 6.2, 42.5, 37.3, 13.2, '0.395486,0.106003,-0.683869,0.678536,0.044282,-0.718120,0.819253,0.245463,-0.233634,-0.284927,0.132327,1.039758,-0.168889,0.252299,0.111423,0.228125,-0.630088,-0.895494,0.029255,-0.579413,-0.189916,-0.626424,0.089687,0.078993,-0.051329,-0.167101,0.747107,-0.016771,0.213901,0.671385,0.193492,0.338008,0.340335,0.624923,-0.132672,0.221030,0.267571,-0.199376,-0.359604,0.171988,0.508310,-0.245613,-0.259093,0.263913,-0.017064,0.080544,0.698125,-0.235505,-0.020603,0.026972,0.230293,-0.269194,-0.053348,0.139826,0.196634,-0.043542,0.057718,0.191316,-0.413914,-0.103061,-0.093526,0.138015,-0.308596,0.074085,-0.232434,0.143957,-0.434758,0.337790,-0.360198,0.122479,0.128718,-0.357391,0.079193,0.447050,0.388250,0.404332,-0.042370,0.341018,-0.023912,0.403710,0.653466,0.134822,-0.299099,0.492261,0.018498,-0.330072,0.000835,-0.103753,-0.663855,-0.069650,0.720086,0.083493,-0.322325,0.081475,-0.450363,-0.212729,-0.598237,-0.219807,0.027690,-0.148797,-0.371893,-0.418347,-0.118652,-0.238745,-0.395160,-0.030620,-0.308011,-0.136669,0.500308,-0.804923,0.460480,0.519767,0.379834,-0.421257,0.618527,0.070181,0.157180,-0.048277,0.269728,0.895802,-0.277852,0.365941,0.315722,0.118455,-0.001043,-0.072721,-0.391792,0.366626', '1844413', '3645150', '1309172', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5416009', '草莓百分百', '剧情', '平凡的大三学生淳平（王辰昊 饰），梦想是成为一名导演。有一天，他在天台邂逅了一位穿草莓图案内裤的少女，对其夕阳下的身影一见钟情，但却不知少女的真实面貌和身份。在身边好友的推断下，淳平认为这草莓图案内裤的主人应该就是学校的风云人物西野（敦婧怡 饰）。在这过程中，淳平又先后认识了性格各异的东凌（任祉妍 饰）、北月（郭雪萌 饰）和南宫（臧雨丝 饰）。而谁是草莓内裤的主人则越来越让淳平分不清。热爱读书的东凌写了一部名为《荷尔蒙》的小说，淳平决定在大学的最后一个暑假把其用DV记录下来。在这个夏天，淳平与这四位女孩度过了最温柔最缠绵也最纠结的夏天，最终，淳平能否实现其梦想，而东南西北四个方向四个女孩，淳平选择的道路又是哪条？本片改编自河下水希创作的同名漫画《草莓百分百》，是青年导演张内咸自《待业青年》后的第二部作品。©豆瓣', '王辰昊', '张内咸', 6.9, 15624, '', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1083137672.jpg', 5.4, 10.8, 33.9, 33.7, 16.2, '-0.020932,-0.049747,-0.245700,0.745424,-0.005312,-0.170435,0.736676,0.241564,-0.212835,-0.285422,0.303196,0.638599,-0.063756,0.245289,0.366049,0.049889,-0.181196,-0.587760,-0.009930,-0.450868,-0.468640,-0.216959,-0.132546,0.236815,-0.024302,-0.124331,0.987569,0.279264,-0.030456,0.323096,0.711269,0.012082,-0.169425,0.218856,-0.241765,-0.017967,0.038561,0.105539,-0.070753,0.225511,-0.193815,-0.310584,-0.137485,0.179057,-0.155808,0.122231,0.937411,-0.258428,-0.075398,0.051321,0.484740,-0.084231,-0.195923,-0.020820,0.404166,-0.128504,0.222522,-0.005279,0.029306,-0.132408,0.009637,-0.063251,-0.670939,-0.015526,0.162086,0.440640,-0.508882,0.409637,-0.099678,-0.193022,0.204183,-0.450209,0.005231,0.025473,0.307368,0.300103,-0.182458,-0.048090,-0.435818,0.249979,0.377341,0.296001,0.013927,0.693596,-0.455122,-0.371879,-0.107262,0.032365,-0.461986,0.097247,0.148069,0.061729,-0.099578,-0.136510,-0.643391,-0.007532,0.165985,-0.151988,0.199291,-0.479843,-0.217634,-0.377044,-0.139824,-0.543457,-0.145967,0.014088,0.092650,-0.301500,0.973701,-0.890737,-0.099848,0.424805,0.121685,-0.327272,0.788398,0.261041,0.072058,-0.327613,-0.062581,0.212144,0.020952,-0.029520,-0.216196,0.730355,-0.071430,-0.202602,-0.762632,0.473257', '25880986', '3811356', '26759820', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5422105', '窃听风云2', '剧情', '香港证券商人罗敏生（刘青云 饰）驱车上班途中遭遇车祸，这起看似平平常常的车祸却引来反恐队的关注。原来警方在罗的车内发现军用窃听器，反恐队长何智强（古天乐 饰）怀疑有人正在策划恐怖袭击。随着何的调查，始终藏在暗处监视窃听的退伍军人司马念祖（吴彦祖 饰）也渐渐浮出水面。与此同时，罗将被窃听的消息告诉了“地主会”的元老们，这是一群自70年代起便操纵香港金融的业界精英，如今更成为只手遮天的抢钱大亨。地主会遭人窃听，无疑预示着他们的各种黑幕将大白于天下。原以为只会是普通的勒索案，却将罗、何、司马等人卷入了万劫不复的漩涡之中……©豆瓣', '古天乐', '麦兆辉', 7.6, 235621, 'tt1852904', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2075072996.jpg', 0.2, 2.2, 31.1, 51.7, 14.7, '0.268176,-0.113371,-0.592724,0.294146,0.043882,0.172593,0.547109,0.049709,-0.917040,-0.304134,0.314077,0.426938,-0.293293,0.151815,0.264759,-0.240398,-0.209932,-0.664106,-0.457375,-0.036699,-0.321688,-0.326937,-0.571356,-0.363815,-0.030292,0.050715,0.293447,0.574963,-0.449496,0.205653,0.481494,0.436390,-0.529145,0.518704,0.040060,-0.086893,0.082948,0.090525,-0.086295,0.083981,-0.079081,-0.644303,0.119124,-0.049666,0.187504,0.360086,0.484214,-0.139799,0.050234,-0.129622,0.382458,-0.524978,0.025453,-0.010893,0.581977,0.196519,-0.004805,0.228524,-0.399801,0.046819,0.069847,0.143522,-0.640692,0.051285,0.292754,0.295432,-0.409687,-0.052401,-0.004437,0.029145,0.018756,0.079311,0.462790,0.476506,0.252034,0.035468,0.067361,0.055340,-0.619243,0.310643,0.355262,-0.062317,-0.031027,-0.217671,0.036863,-0.415226,-0.106566,0.022625,-0.077738,-0.228800,0.476025,-0.038165,-0.070844,0.308989,-0.257782,-0.096259,0.001462,-0.065565,-0.141000,-0.274952,-0.097309,-0.912902,0.174505,-0.321574,-0.056504,0.331899,0.007450,0.004694,0.362262,-0.674925,0.136176,0.406804,0.065458,-0.460083,0.328601,-0.183149,0.072610,-0.235279,-0.178904,0.112409,0.464771,0.345626,0.027434,0.210334,-0.065461,-0.647451,0.059099,0.069896', '25723905', '3387546', '25870679', '3158432');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5432221', '性本恶', '剧情', '早在2010年的12月，安德森就有意改编托马斯·品钦的《性本恶》，不过由于另一部新片《大师》的资金到位较早，《性本恶》暂时被搁置了起来。《性本恶》有一个类似钱德勒侦探小说的外壳，洛杉矶私家侦探多克与前女友莎斯塔不期而遇，并从她那听说了一个无从佐证的故事，一桩离奇绑架案，受害者——她现在的情人——是一个“腰缠亿贯”的房地产商。多克明知道“爱情”是个含混不清、随时会惹出一串麻烦的词儿，还是鬼使神差地撞进了莎斯塔的故事，而且愈卷愈深，冲浪手、皮条客、贩毒者、摇滚乐手、犯了命案的高利贷者，各色人等，若隐若现……', '华金·菲尼克斯', '保罗·托马斯·安德森', 7.1, 11701, 'tt1791528', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2204216560.jpg', 2.3, 9, 37, 34.9, 16.9, '0.701030,-0.117843,-0.316991,0.317295,-0.194844,-0.088634,0.740950,-0.024933,-0.515649,-0.148773,0.274342,0.844460,-0.335721,-0.129210,0.108540,0.251327,-0.198143,-0.516728,0.276192,-0.303039,-0.203399,-0.752697,-0.122053,-0.013891,-0.002259,-0.074822,0.369347,0.206430,-0.011277,0.131531,0.358876,0.306830,0.021620,0.094917,-0.049927,0.250629,0.181732,-0.067567,0.215843,0.261641,0.238474,-0.241097,-0.181510,0.075726,-0.209179,0.575912,0.262550,-0.097080,-0.183395,0.264093,0.447619,-0.222717,0.084048,0.006166,0.259731,-0.098984,0.194409,0.253864,-0.301651,-0.154794,0.121023,-0.061354,-0.707043,0.199042,0.056619,0.308606,-0.407138,0.348798,-0.421682,0.157476,-0.273476,-0.234085,-0.065878,0.481568,0.298146,0.182724,-0.044141,-0.083344,-0.623724,0.250850,0.458261,0.389182,-0.296963,0.385645,-0.231096,-0.316367,-0.248031,-0.006995,-0.403962,-0.012475,0.705058,-0.274043,-0.309733,0.509357,-0.582331,0.111773,-0.252736,0.117217,-0.155444,-0.248078,-0.247711,-0.097861,-0.153191,-0.261534,-0.088026,-0.128024,0.335758,-0.099765,0.649165,-0.660122,0.083373,0.714462,0.061052,-0.109553,0.333498,-0.190504,-0.126279,-0.070420,-0.001498,0.138222,0.038877,0.115662,0.355430,0.481346,0.250761,-0.634847,-0.329091,0.334317', '1309069', '30160393', '4944008', '5973984');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5446197', '铁拳', '剧情', '曾经，比利（杰克·吉伦哈尔 Jake Gyllenhaal 饰）凭借着他凶猛冷酷的左拳享誉拳坛，一时之间无人能敌，是当之无愧的拳王。然而，一场意外的发生让比利失去了挚爱的妻子莫林（瑞秋·麦克亚当斯 Rachel McAdams 饰），这场悲剧彻底打垮了比利，他开始自暴自弃，不仅放弃了事业，甚至开始酗酒吸毒，因此，他被剥夺了女儿蕾拉（奥娜·劳伦斯 Oona Laurence 饰）的抚养权，蕾拉被送入了福利机构。女儿的离去让比利渐渐清醒了过来，他对自己糟糕的现状失望透顶，决定痛改前非。比利希望能够重新站在拳击擂台之上，他找到了教练威尔斯（福里斯特·惠特克 Forest Whitaker 饰），希望他能够帮助自己，夺回失去的一切。©豆瓣', '杰克·吉伦哈尔', '安东尼·福奎阿', 7.4, 37439, 'tt1798684', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2248204656.jpg', 0.4, 3.5, 36.2, 44.3, 15.6, '0.104741,0.365918,-0.732273,0.286110,-0.259479,-0.408665,0.548854,0.201133,-0.295229,0.006461,0.336235,0.671842,-0.067982,-0.049947,0.316849,0.126785,-0.322904,-0.932823,0.283523,0.107182,-0.094143,-0.500081,-0.348261,-0.209326,-0.247371,-0.380281,0.538489,-0.122557,-0.111383,0.436718,0.314889,0.386940,0.532982,0.411246,-0.009921,0.327173,0.172885,-0.409970,-0.418969,0.327253,0.307921,-0.120739,-0.162919,0.649948,0.083840,0.179138,0.552374,-0.244617,-0.008930,-0.105898,0.247916,-0.433552,0.001404,0.367070,-0.054678,-0.045716,-0.151818,0.102041,-0.143010,-0.106161,0.294294,-0.023945,-0.575758,0.160905,-0.096896,-0.000134,-0.732789,0.359733,-0.397126,0.061700,0.108488,-0.261558,0.067635,0.367277,0.288461,0.164123,-0.108767,0.251133,-0.353677,0.135436,0.681815,-0.304297,-0.343483,0.305513,-0.101682,-0.196102,-0.153064,-0.295168,-0.500606,-0.075869,0.772559,0.154012,-0.013398,0.372902,-0.247317,-0.277007,-0.611244,-0.330277,-0.124233,-0.441523,0.001332,-0.149306,-0.410957,-0.090710,-0.143250,-0.249670,-0.352595,-0.500134,0.539228,-0.673323,0.249190,0.377932,0.221257,-0.336902,0.260009,-0.038735,0.294162,-0.133229,0.030998,0.482052,-0.045562,0.279129,0.331856,0.226976,0.129543,0.085119,-0.148364,0.716136', '1309069', '1301022', '1292533', '1293829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5446226', '恋爱恐慌症', '喜剧', '在地球上的数十亿人之中，总有至少一个是你的真命天子，问题是，你如何才能找到他……梁若晴（林依晨 饰）在大学时有一段甜蜜的爱情，但男友艾伦（李易峰 饰）为了发展自己的音乐事业将若晴放弃，致使后者大为受伤。若晴从此加入了阿姨创建的失恋女互助组，历经五年的熏陶后，男人在她看来只是一群骗子。毕业后的若晴在医院做义工期间，结识了全院寄予厚望的主治医师陆哲翰（陈柏霖 饰），陆哲翰散发的耀眼光芒令若晴方寸大乱，她在互助组的开导下，为了抵御心动本能对陆哲翰展开了暗算计划，然而陆哲翰举止得当令若晴无法成功，就在若晴芳心暗动之时，她的感情轨迹再次出现了波动……©豆瓣', '林依晨', '龙毅', 5.5, 26341, 'tt2075241', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1228048966.jpg', 10.2, 28.3, 43.6, 11, 7, '0.011985,0.266656,-0.731650,0.596531,-0.243526,-0.184390,0.383696,0.078268,-0.400383,-0.061146,0.107557,0.462258,-0.204812,0.251516,0.042761,0.130108,0.001225,-0.711246,0.134014,-0.377449,-0.195215,-0.247746,-0.181558,-0.011895,-0.069041,-0.453325,0.669582,0.168692,-0.055344,0.213792,0.287875,0.220026,-0.013157,0.581614,-0.098991,-0.087532,-0.102133,0.297503,-0.381223,0.104499,0.177681,-0.453990,-0.025778,0.351739,-0.090140,0.208302,0.810317,-0.127381,-0.106680,-0.132659,0.291188,-0.229764,-0.070956,-0.114667,0.203871,0.022174,0.206188,0.303734,-0.221154,-0.044011,-0.013061,-0.000507,-0.630940,-0.035061,0.226077,0.001954,-0.654334,0.373215,-0.013342,-0.001283,-0.097516,-0.213203,-0.067546,0.357984,0.152229,0.334600,-0.302689,-0.035368,-0.442639,0.301729,0.660313,0.042758,-0.364346,0.609109,-0.214295,-0.258003,-0.010539,0.066062,-0.424354,-0.108042,0.151495,-0.088007,-0.339495,0.043154,-0.259848,0.025672,-0.270581,0.075818,-0.155102,-0.503849,0.035308,-0.247241,-0.088858,-0.218050,-0.378335,0.048914,0.115676,-0.429007,0.663671,-0.981246,0.093770,0.471266,0.273250,-0.574301,0.439931,0.128449,0.020082,-0.185633,-0.255737,0.313179,-0.302862,0.099424,0.146378,0.382805,0.037157,-0.047398,-0.312057,0.477910', '1301022', '35030151', '30345227', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5501711', '我的见鬼女友', '喜剧', '偶然的机会，街头魔术师马兆邱（李民基 饰）结识了面带忧郁和惆怅女子姜予丽（孙艺珍 饰）。予丽的神情给了他无限启发，他邀请予丽与之合作，共同编排的鬼魂表演引起巨大的轰动，整个团队都热情高涨。但是予丽从不参加团队的庆功宴，好不容易参加还大量酗酒，胡言乱语，闹得场面分外尴尬。在此之后，兆邱反而对予丽更加感兴趣，他尝试走入予丽的家中，却发现这个女孩身边却充满了可以看到的鬼魂。更可怕的是，鬼魂也跟在了兆邱的身边。以此为契机，两个完全有着不同人生的人彼此渐渐了解，兆邱也开始了解予丽悲惨的过去……©豆瓣', '孙艺珍', '黄仁浩', 6.8, 27146, 'tt2132405', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1544095343.jpg', 1, 7.9, 50.7, 31.2, 9.1, '0.151641,0.056862,-0.706664,0.658061,0.001752,-0.156442,0.778676,0.056270,-0.639848,-0.183208,-0.086607,0.589063,-0.430085,0.422735,0.328308,-0.296364,-0.168466,-0.692442,-0.116540,-0.022242,-0.313319,-0.320721,-0.235772,-0.366966,-0.239346,-0.127930,0.261299,0.363362,-0.374542,0.624864,0.381598,0.256515,0.003825,0.777289,0.008597,-0.163278,-0.132417,0.308031,-0.137339,-0.239504,-0.102155,-0.306554,-0.350675,0.370624,-0.010271,0.344320,0.490000,-0.063787,-0.407582,-0.048407,0.441230,-0.078382,0.065401,0.019831,0.239661,-0.007909,0.457719,-0.158402,-0.026200,0.039310,-0.051131,-0.084481,-0.717319,0.457117,0.229915,0.118321,-0.394700,0.392401,0.294499,-0.050026,0.111960,0.031699,0.164557,0.369420,0.343136,0.275586,-0.050735,-0.087050,-0.395845,0.195739,0.575366,0.076115,-0.228749,0.343009,-0.293985,-0.552987,-0.149812,-0.134747,-0.232442,0.100372,0.309448,0.060962,-0.088081,0.237225,-0.650101,0.118279,0.006271,0.091213,-0.032969,-0.463527,0.304060,-0.799286,-0.363619,-0.458220,-0.311389,0.126889,0.099435,-0.424226,0.669729,-0.741903,0.105662,0.247670,0.340190,-0.581039,0.631478,0.032873,-0.011803,-0.255378,-0.111408,0.036325,0.004501,0.148833,0.205404,0.320370,-0.026902,-0.091774,-0.114818,0.374927', '26341750', '34429100', '1301022', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5502697', '夺宝联盟', '动作', '曾轰动全球且价值高达300亿的钻石太阳之泪惊现中国澳门，某神秘人物委托混迹赌场的盗贼澳门朴（金允石 饰）组织人马侵入赌场金库，盗取钻石，事成之后报酬颇丰。在此之后，朴从韩国网罗了当年被他背叛的伙伴波派（李政宰 饰）、藏帕诺（金秀贤 饰）、耶妮可（全智贤 饰）、嚼皮糖（金海淑 饰）、佩希（金惠秀 饰），以及中国方面的陈（任达华 饰）、安德鲁（吴达庶 饰）、朱莉（李心洁 饰）、约翰尼（曾国祥 饰）等人。这些人中包括偷盗、绳索、路线、演技等各方面高手，实可谓一次强强联合。在澳门朴的周密策划下，偷盗行动有条不紊地展开。在此过程中两方人马暗暗较劲又相互帮衬配合，紧张有趣而意外迭出，上演了一出中韩盗贼大比拼……©豆瓣', '金允石', '崔东勋', 7.3, 177980, 'tt2330866', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1761853840.jpg', 0.6, 4, 39.6, 42.9, 12.9, '-0.012584,0.183100,-0.558072,0.301606,0.310848,0.156140,0.219262,0.205431,-0.570820,-0.002481,0.281358,0.147623,-0.481871,-0.263447,0.229174,-0.267693,-0.276574,-0.666512,-0.089612,-0.222411,-0.030730,-0.122754,-0.446459,-0.329199,-0.221996,-0.041279,0.124747,0.426263,-0.046987,0.387025,0.539955,0.330278,-0.351140,-0.067183,0.121257,-0.050066,0.329290,0.012666,-0.237604,0.034233,-0.248565,-0.193505,0.096679,-0.058153,0.399011,0.280969,0.569335,-0.111638,0.317920,-0.104952,0.111848,-0.021723,0.004470,-0.170200,0.351434,0.291991,0.312372,0.088752,-0.116671,-0.042959,0.356355,-0.086647,-0.728537,-0.070466,0.488015,0.050509,-0.303348,0.024288,-0.123063,0.224442,-0.215223,0.022135,-0.042814,0.267941,0.635449,-0.139341,0.389381,0.058193,-0.258066,0.608702,0.083723,-0.055852,0.182552,-0.174101,-0.043115,-0.682720,-0.142797,-0.162895,-0.083212,0.019086,0.552740,-0.336440,0.531501,0.037395,-0.539391,0.048384,-0.057598,0.010145,-0.051866,-0.050172,0.140798,-0.904233,0.067366,-0.422365,-0.051043,0.264021,0.166834,0.083616,0.563564,-0.304906,-0.174923,0.255787,0.262545,-0.435478,0.370830,-0.120535,-0.067270,-0.250360,-0.227969,0.074699,0.286463,-0.251883,0.042626,0.145435,-0.064285,-0.304958,-0.046805,-0.063003', '3318306', '4014397', '6517421', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5503303', '超级八', '科幻', '时间是1979年，美国俄亥俄州一个平凡小镇。少年乔·兰布（乔尔·科特尼 Joel Courtney 饰）痛失母亲，生死悲痛让他久久地沉默。数月后，他应好朋友查尔斯（雷利·格里芬斯 Riley Griffiths 饰）的邀请，决定约上几个朋友一起用超8摄像机（8 mm）拍摄一部恐怖电影。当然令他下定决心的，是那个令她心仪的美丽女孩爱丽丝（艾丽·范宁 Elle Fanning 饰）也参与其中。在某个夜晚，爱丽丝驾驶父亲的汽车载着伙伴们来到火车站拍戏，谁知却目睹了一场极其惨烈的火车事故。这起事故还只是一系列不寻常事件的开始，小镇上的人们相继离奇失踪，各种奇怪的事件也接连发生。少年们的摄像机记录关于这一切的秘密……©豆瓣', '乔尔·考特尼', 'J·J·艾布拉姆斯', 6.5, 36321, 'tt1650062', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1045362023.jpg', 2.1, 13, 50.9, 27.5, 6.5, '0.375801,-0.039820,-0.662066,0.400305,0.211767,-0.109247,0.690390,-0.102753,-0.519523,-0.432663,0.379313,0.784548,-0.469077,0.441677,0.288222,0.071671,-0.484899,-0.685942,-0.060309,-0.034650,-0.423593,-0.230122,-0.039542,-0.338756,-0.033989,-0.031760,0.426361,0.149630,0.239947,0.587612,0.285497,0.192948,-0.193524,0.437139,-0.117782,0.036231,0.182480,0.080313,-0.097372,-0.038740,-0.158607,-0.460577,-0.076645,0.222907,0.106752,0.351235,0.751375,-0.019202,-0.234385,0.112169,0.260704,-0.195864,0.074412,0.030773,0.378607,0.018762,0.034294,0.186031,-0.236601,-0.179141,-0.071656,0.227162,-0.275455,-0.008455,0.006000,0.168143,-0.463005,0.371084,-0.069467,0.056900,0.083287,-0.212288,0.071767,0.274555,0.314718,0.194816,-0.008755,-0.035944,-0.135302,0.347502,0.737647,0.081963,-0.126513,0.473501,-0.226846,-0.565102,-0.227392,-0.024063,-0.653760,0.289691,0.276097,-0.117425,-0.118831,0.255377,-0.498467,-0.046180,-0.362307,-0.193363,-0.126303,-0.156543,-0.082376,-1.015819,0.025889,-0.420255,-0.442054,0.055337,-0.105592,-0.085817,0.651420,-0.379081,0.136774,0.620897,-0.126151,-0.297301,0.478706,0.109688,0.202489,-0.139958,0.159282,0.269937,0.008710,0.057604,-0.167201,0.282467,-0.022693,-0.006831,-0.300115,0.325971', '10466639', '3811356', '2159244', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5908473', '火车', '剧情', '某个下雨的日子，经营宠物医院的张文浩（李善均 饰）带着还有一个月就要与之共赴婚姻殿堂的姜善瑛（金敏喜 饰）前往老家看望父母。途中文浩下车购物，而善瑛在接了一通电话之后便从男友身边神秘失踪。焦急的文浩四处寻找，结果却发现一桩桩令他难以置信的事实。善瑛曾于2007年债台高筑宣布破产，而当年的照片与他失踪的未婚妻竟完全是两个人。这个失踪的女人真身为何？她的背后又隐藏怎样的秘密和故事呢？本片根据日本作家宫部美雪的同名原著改编，“火车”来自佛教用语，指载着作恶亡灵前往地狱的冒火的车子。《观无量寿经》云：“人以恶应堕恶道，命欲终时，地狱众火俱至，必有火车来迎。”©豆瓣', '李善均', '边永柱', 7, 22412, 'tt2308725', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1625856871.jpg', 0.7, 5.4, 45.8, 37.9, 10.2, '0.085809,-0.073000,-0.647167,0.463955,0.162170,-0.256820,0.522647,0.064627,-0.447569,-0.361557,0.231202,0.603155,-0.272316,0.297572,0.364169,0.146575,-0.105718,-0.529682,-0.085535,-0.226009,-0.263106,-0.237335,-0.092970,-0.079410,0.146487,-0.102160,0.378914,0.214893,-0.074807,0.598167,0.410170,0.319540,-0.676197,0.405542,-0.264875,0.051074,-0.015068,0.367742,-0.174900,-0.107569,0.021535,-0.314225,-0.238246,-0.048411,-0.207300,0.357522,0.350540,-0.090170,-0.240520,0.004302,0.258115,-0.268063,-0.187746,-0.085514,0.502533,0.026510,0.176979,0.417220,-0.217444,-0.024852,0.053228,-0.044745,-0.548779,0.091325,-0.056044,0.164790,-0.383720,0.180618,-0.162705,0.207084,-0.021331,-0.303274,0.202070,0.366952,0.088824,0.610179,-0.195627,-0.043856,-0.443481,0.233985,0.423644,-0.086680,0.081492,0.271006,0.180204,-0.339085,-0.017231,0.139490,-0.485232,0.149820,0.331708,-0.086101,-0.252035,0.225322,-0.558445,-0.165113,-0.291292,-0.018566,0.196070,-0.215111,-0.237916,-0.589098,0.029346,-0.233785,-0.177633,0.110462,0.354003,-0.000039,0.558672,-0.567958,0.303149,0.390458,0.160825,-0.704957,0.548538,0.060909,-0.052502,-0.113693,0.159957,0.323030,0.123041,0.354210,-0.158366,0.060619,-0.020356,0.117015,-0.581917,0.350356', '1930829', '1303333', '35144311', '1304687');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5908477', '鸿门宴传奇', '剧情', '巍巍大秦，一统中原。然而好景不长，秦王朝以暴政治国，致令黎民百姓、公侯王卿噤若寒蝉，心生怨恨。最终义军并起，蚕食大秦江山。时有刘邦（黎明 饰）、项羽（冯绍峰 饰）两大英雄豪杰，引得樊哙（陈小春 饰）、张良（张涵予 饰）、范增（黄秋生 饰）、萧何（修庆 饰）等无数热血男儿和雄韬谋士来伏。楚怀王心知二人胸怀野心，难以控制，于是求得离间之计，与二人约定先入咸阳者可成王。在此之后，刘邦奇谋入住咸阳，最终导致刘项这对惺惺相惜的昔日盟友决裂。秦朝灭亡，随即拉开楚汉之争的大幕，上演了鸿门宴和霸王别姬的千古英雄传奇……©豆瓣', '黎明', '李仁港', 6.4, 101863, 'tt2102472', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1293056226.jpg', 5, 14.8, 45.3, 25.4, 9.5, '-0.164925,0.332218,-0.487824,0.401708,0.875222,0.043501,0.178304,0.442894,-0.634373,-0.361072,0.038547,0.439142,-0.210273,-0.191344,0.192159,-0.474339,-0.253343,-0.774868,-0.152202,0.072957,0.350382,0.077519,-0.206393,-0.002915,-0.501350,0.111871,0.774083,0.300177,-0.009869,0.621246,0.422182,0.095996,-0.110578,0.292548,0.072961,0.025723,-0.373907,0.071200,-0.836609,-0.048769,-0.338776,-0.350839,-0.599185,0.193634,-0.372389,0.104057,0.077764,-0.548239,0.288891,-0.401674,0.229047,-0.157013,-0.189890,0.032245,0.148040,-0.002824,0.092002,0.419569,0.296829,0.025160,0.176177,0.001638,-0.534429,-0.264170,0.222118,-0.108815,-0.231949,0.561912,-0.041681,-0.214785,-0.166702,-0.093662,0.205872,0.437527,0.616970,0.056908,-0.074849,-0.175073,-0.380221,0.215041,0.556880,-0.039835,-0.151124,-0.267097,0.288868,-0.512180,0.134240,-0.247790,-0.342312,-0.080416,0.459673,-0.051049,0.442744,0.411936,-0.389627,-0.456197,-0.300515,0.557989,0.369264,-0.157544,0.247002,-0.005911,-0.243618,-0.158218,-0.035231,0.209259,0.398848,-0.045841,0.558195,-0.527479,-0.498134,-0.272676,0.215512,-0.704130,0.168956,0.098892,0.172938,-0.089306,-0.112609,0.432733,-0.000091,0.036197,-0.099766,-0.150590,-0.424133,-0.058856,-0.213083,-0.058108', '4821046', '3230460', '25300674', '1780122');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5908478', '我爱你', '剧情', '飘雪的坡道上，送牛奶的老头子金万皙（李顺载 饰）邂逅了收废品的老太太宋怡芬（尹秀晶 饰）。他们的前半生各自背负着艰辛的人生：万皙年轻时我行我素，直到妻子病逝才深觉愧疚；怡芬被心爱的男人抛弃在城市角落，孩子夭折后至老未嫁。两位老人在每天凌晨寂静的街道上相遇，孤独而苦难的生活令他们渐渐靠近。在万皙孙女妍儿（宋智孝 饰）的穿针引线下，如初恋般的悸动萌发在了彼此心中。万皙的朋友、停车场管理员张军峰（宋在河 饰）一直耐心的看护着患有老年痴呆症的老伴。直到有一天，军峰得知老伴已患绝症。目睹她一次次痛苦病发，心如刀绞的军峰做出了悲伤的决定……影片改编自韩国著名网络漫画家姜草的同名作品，已公演的同名舞台剧亦受到好评。©豆瓣', '宋在浩', '秋昌旼', 9.1, 155363, 'tt1862020', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p824590592.jpg', 0.2, 0.6, 7, 30.8, 61.4, '-0.119471,-0.044826,-0.594451,0.333312,0.229160,-0.438318,0.752259,0.295243,-0.513386,-0.057288,0.593927,0.630418,-0.179209,0.642839,0.304401,-0.073180,-0.284598,-0.662306,-0.087920,-0.135901,-0.315253,-0.201756,0.030186,-0.159427,-0.012464,-0.286150,0.625901,0.076255,0.213778,0.323812,0.221112,0.114782,-0.247283,0.212140,-0.336592,0.140732,0.022134,0.117570,-0.371102,-0.097174,0.016932,-0.262337,-0.128342,-0.133291,-0.109431,0.218008,0.862537,-0.202541,-0.250803,-0.142248,0.652635,0.003960,-0.004897,0.038452,0.097708,0.225174,0.235044,0.106521,-0.243621,-0.062183,0.022144,-0.003465,-0.299379,0.183459,0.197193,0.171949,-0.549098,0.665697,0.028272,0.008179,0.071790,-0.302563,0.240569,0.052765,0.027958,0.543355,-0.317584,0.187640,-0.150239,0.463164,0.472196,0.047589,-0.202440,0.464524,-0.254817,-0.136431,0.099347,-0.267853,-0.840410,0.044716,0.269927,0.128677,-0.332608,0.321431,-0.409630,-0.000381,-0.009008,-0.025712,0.128246,-0.168021,-0.362251,-0.525512,-0.029047,-0.204546,-0.223559,0.147501,0.090264,-0.239126,0.781303,-0.429650,0.422946,0.454060,0.040061,-0.289809,0.678098,-0.055696,0.039384,-0.071705,0.040463,0.713986,-0.353797,0.167147,0.140308,0.131650,-0.534626,0.243222,-0.493417,0.426349', '4233625', '3732800', '1307146', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5908859', '四十而惑', '喜剧', '《一夜大肚》中的夫妻皮特（保罗·路德 Paul Rudd 饰）与黛比（莱斯利·曼恩 Leslie Mann 饰）如今年过四十，虽然黛比已经拥有一个不错的精品店，皮特也开了自己的唱片公司，然而生活的暗礁还是渐渐围困了这个家庭：不仅皮特开始需要借助“伟哥”，两人的父母也年岁渐衰，需要供养，皮特的唱片店近来也在艰难维系，两个还在上学的女儿更是每天把家里弄得鸡飞狗跳。夫妻二人深感走入了爱情坟墓的同时，连生活的激情与乐趣也将要被消磨殆尽。黛比在与朋友谈心之后，终于决定要挽救自己的婚姻，而此时，她已经怀上了皮特的第三个孩子……本片为导演在2007年的喜剧电影《一夜大肚》的一个独立续集。©豆瓣', '保罗·路德', '贾德·阿帕图', 6.6, 7050, 'tt1758830', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1803451903.jpg', 1.4, 10.3, 51.6, 29.2, 7.5, '0.153389,-0.044201,-0.689402,0.343048,-0.050391,-0.675009,0.773153,0.203823,-0.540418,-0.286892,0.039083,0.686754,-0.298388,0.520853,0.445139,-0.057834,-0.190912,-0.694896,-0.104365,-0.029063,-0.248699,-0.379343,-0.273445,-0.214677,-0.343847,-0.237782,0.644956,0.050689,0.317780,0.395394,0.175615,-0.077179,0.107636,0.366706,-0.262749,0.241730,0.011772,0.013148,-0.422745,0.125556,0.087193,-0.278665,-0.093264,0.032402,0.142629,0.396190,0.631883,-0.194050,-0.187216,0.029148,0.247958,-0.113458,-0.268279,0.160818,0.309753,-0.288734,0.472428,0.269231,-0.350535,0.078810,-0.025297,-0.207339,-0.974926,0.025337,0.122907,-0.171292,-0.820535,0.744045,0.168760,-0.151329,-0.028394,-0.337901,0.125029,0.607878,0.032724,0.745811,-0.375104,-0.066543,-0.661022,0.286229,0.625833,-0.008988,-0.212508,0.668100,-0.186631,-0.304179,-0.260869,-0.236321,-0.542426,-0.132733,0.244950,0.158978,-0.204074,0.135730,-0.793276,0.112493,-0.284966,-0.314941,0.220301,-0.513841,0.048518,-0.583210,-0.208807,-0.507376,-0.322519,0.151035,0.211414,-0.187541,0.777801,-0.751864,0.282604,0.407413,0.209528,-0.499945,0.664190,0.176566,0.418826,-0.097127,0.030368,0.092933,-0.180081,0.252658,0.365243,0.330172,0.041569,-0.159774,-0.492745,0.546286', '1793491', '1783461', '24879858', '26021055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5910040', '舞出我人生4', '剧情', '影片讲述一个富商的女儿艾米莉（凯瑟琳·麦考米克 饰）前往迈阿密想要成为一名专业的舞者，她结识了一个顶尖舞蹈团的领队西恩（瑞安·古兹曼 饰），并很快坠入爱河。为了舞团的生存，他们必须拿下一个很重要的赞助项目。但是这时艾米莉的父亲横插一脚，企图改变和拆散舞团，艾米莉、西恩和舞团的其他成员必须团结起来，捍卫并且实现他们的梦想。', '瑞安·古兹曼', '斯科特·斯皮尔', 7.6, 22963, 'tt1800741', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1287430917.jpg', 0.7, 3.3, 30.2, 44.9, 21, '0.284114,-0.089849,-0.426898,0.597817,-0.174389,-0.465955,0.748488,0.117228,-0.220198,-0.283392,0.253439,0.871510,0.297868,0.018664,0.636736,-0.098648,-0.296633,-0.645962,0.129867,-0.085801,-0.207694,-0.307242,-0.278310,-0.198536,-0.260488,-0.189766,0.949820,-0.209688,-0.143194,0.533146,0.296900,0.406635,0.012877,-0.054774,-0.037836,-0.148761,0.531963,-0.219491,-0.536306,0.428665,-0.311005,0.347040,-0.164027,0.021574,-0.025827,0.323805,0.131403,-0.261332,0.279980,0.012153,0.174152,-0.341655,0.126572,0.080758,0.055145,-0.100207,0.073783,0.262023,-0.149147,-0.209893,0.039635,-0.332091,-1.219549,-0.125869,0.416836,0.157494,-0.692129,0.173353,0.113729,-0.156416,0.113974,-0.261094,-0.068356,0.602077,0.435768,0.211125,-0.305835,0.159484,-0.635434,0.190862,0.860074,-0.146301,-0.156488,-0.041209,-0.060412,-0.336098,-0.181033,-0.056526,-0.466548,0.008938,0.599707,-0.127750,0.232645,0.019415,-0.554839,-0.231729,-0.337490,-0.351056,0.055194,-0.663372,0.304185,-0.838792,0.065775,-0.027908,-0.192557,-0.248770,0.142425,-0.281199,0.984042,-0.909410,0.112109,0.598692,0.430370,-0.591070,0.527965,0.240221,0.618460,-0.534073,-0.236839,0.447832,0.118667,0.255482,-0.257309,0.295228,0.121290,-0.235690,-0.221490,0.349024', '1793491', '30163500', '26678784', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5912977', '爱，不爱', '剧情', '本片改编自日本女作家井上荒野的短篇小说《不能回来的猫》，入围2011柏林电影节主竞赛单元，两位主演都是无酬劳出演该片。一对夫妻在经过五年的厮守之后，终于濒临分手的边缘。突然有一天妻子（林秀晶 饰）告诉丈夫（玄彬 饰），她有了别人。丈夫是个貌似沉默宽容的男人，他平静地接受了妻子外遇的事实，仍一如既往深情相待。一面帮妻子整理离去的行李，一面为她准备了美味的咖啡。他一边收拾着行李，一边希望也许就在这个短促而有限的空间，他们可以拾回往昔的记忆。然而，妻子却被丈夫的体贴搞得有点不耐烦，情感出现了波动。丈夫为分别前的最后一餐特别预定了餐厅，而为避雨四处躲藏的小猫又成为他试图挽留妻子的契机……外面的雨一直下个不停……最后他们真的会分手吗？©豆瓣', '玄彬', '李胤基', 6.8, 17535, 'tt1832453', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2571556449.jpg', 1.8, 11, 44.2, 29.9, 13.1, '0.068878,0.129087,-0.626718,0.628674,-0.088092,-0.534317,0.810730,0.336293,-0.252701,-0.256359,0.277579,0.621357,-0.122571,0.295171,0.155092,0.088954,-0.414233,-0.613095,-0.157248,-0.005069,-0.208709,-0.228977,-0.228485,-0.016393,-0.273477,0.073310,0.578242,0.057387,0.258907,0.266397,0.264566,-0.148771,0.095075,0.443310,-0.355167,0.071853,-0.085319,0.169726,-0.407343,0.315502,0.180683,-0.150219,-0.041765,0.248792,0.001412,0.316631,0.727932,-0.135587,-0.208122,0.147834,0.436964,-0.130510,0.125404,0.204368,0.169923,0.091461,0.354926,0.038972,-0.261875,-0.093573,0.078090,-0.010021,-0.597861,0.082643,-0.061098,0.189495,-0.474502,0.588622,-0.166407,0.077063,0.205119,-0.351974,0.157911,0.306437,0.339974,0.489057,-0.353125,0.105103,-0.412422,0.154162,0.460615,0.028452,0.170824,0.580300,-0.185188,-0.414210,0.160352,-0.160629,-0.640678,-0.085105,0.167870,0.158583,-0.238853,0.074253,-0.427899,-0.033226,-0.153561,-0.080162,0.067542,-0.515374,-0.002483,-0.429562,0.030592,-0.172030,-0.227363,0.071864,-0.030149,-0.275539,0.635673,-0.646812,0.342525,0.571749,0.265667,-0.533216,0.604653,0.326376,0.075985,-0.213144,0.210559,0.311513,-0.171339,0.232389,0.330906,0.361864,-0.038226,0.004304,-0.481904,0.338257', '30401849', '21619567', '4817024', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5912992', '熔炉', '剧情', '来自首尔的哑语美术老师仁浩（孔宥 饰）来到雾津，应聘慈爱聋哑人学校。天降大雾，他意外撞车，维修时邂逅了人权组织成员柔珍（郑有美 饰）。仁浩妻子早亡，8岁女儿天生哮喘由祖母照看，所以他不辞辛苦谋职养家。然而，双胞胎的校长与教导主任竟逼仁浩索贿5千万韩元。同时，仁浩逐渐发现学校笼罩着一种紧张压抑的气氛，令人窒息。有三个孩子引人关注：聪颖的金妍斗（金贤秀 饰）、贪吃的陈宥利（郑仁絮 饰）和弟弟自杀身亡的全民秀（白承焕 饰），民秀总是满脸淤青。下课后，仁浩还听到女厕所中有呼喊与哭泣，在门卫的阻拦下他未深究。之后。他意外目睹了校长行贿警察，教导员毒打民秀，宿导溺罚妍斗的行径。一个惊天的隐秘被慢慢揭开，真相令韩国震惊……本片取材于2005年光州一所聋哑障碍人学校的真实事件，改编自韩国作家孔枝泳的同名小说。©豆瓣', '孔刘', '黄东赫', 9.3, 874704, 'tt2070649', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1363250216.jpg', 0.1, 0.2, 3.3, 25, 71.4, '0.160003,-0.184248,-0.425488,0.213612,0.118093,-0.172118,0.495926,0.292717,-0.436720,-0.367722,0.404862,0.313173,-0.317771,0.353764,0.204950,-0.172715,-0.113882,-0.511128,-0.058798,-0.209470,-0.012954,-0.298533,-0.002282,-0.111933,-0.021297,-0.370955,0.186685,-0.120625,-0.100665,0.626184,0.180402,0.321314,-0.295265,0.287148,0.039097,-0.033388,0.267883,0.078708,-0.028654,-0.197448,-0.086663,-0.182658,-0.249541,0.026158,-0.110964,0.326407,0.610842,0.016541,-0.247719,-0.093997,0.469460,-0.155481,-0.215929,0.177187,0.202956,-0.113810,0.304892,0.258642,-0.110664,0.035069,0.044147,-0.039623,-0.277298,0.162397,0.073455,0.125373,-0.334659,0.358944,0.019284,-0.233446,0.250156,-0.201643,0.204152,0.121502,0.026998,0.535192,-0.156735,0.215182,-0.022858,0.534023,0.307800,-0.220524,-0.180705,0.086517,-0.275585,-0.293816,0.333582,-0.116477,-0.598894,0.323545,0.021528,-0.107580,-0.111873,0.021799,-0.292201,-0.246488,-0.249966,0.103825,-0.174993,-0.279311,-0.213893,-0.417354,-0.188735,-0.038357,-0.175921,-0.025286,0.101680,-0.092008,0.546035,-0.534693,0.209945,0.344788,0.129528,-0.294399,0.483585,-0.017062,-0.123403,-0.225543,-0.326155,0.046507,-0.063583,0.213863,-0.099248,0.297572,-0.166939,-0.181372,-0.049927,-0.083782', '3445516', '25922902', '3811356', '1306544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5915752', '你和我', '剧情', '那个晴朗的夜晚，静谧悠远的银河横亘夜空。“我”（坂本真綾 饰）抬头仰望，兀自出神，意外地完成了与你命运的邂逅。你（中村蒼 饰）是一名志愿成为漫画家的青年，青涩阴柔的面庞下有着对理想笃定不移的坚持。从你那里，我得到了“银王号”这个气势十足的名字。对于屡战屡败、屡败屡战的你来说，即使是这样毫不起眼的我也是生活中的负担。你希望为我找到温暖的家和和善的主人，可是最终无法割舍我们在短短数日内滋长起来的依赖。就这样，我和你在这间逼仄而温暖的小屋里，度过了十年漫长而幸福的岁月……本片根据やまがらしげと根据自身经历创作的网络人气Flash动画改编。©豆瓣', '中村蒼', '窪田崇', 8.2, 9869, 'tt1863296', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p804585493.jpg', 0.3, 1.7, 20, 42.6, 35.4, '-0.094702,0.366003,-0.735247,0.796182,-0.233887,-0.175234,0.853236,0.023664,-0.275943,-0.122171,0.036315,0.547740,0.167067,0.497787,0.163748,0.324658,-0.188658,-0.726826,-0.195871,-0.247349,0.012687,-0.404389,-0.481596,0.091505,-0.026303,-0.273903,0.935680,0.431412,-0.131226,0.410693,0.050912,0.082215,0.188081,0.321295,-0.401093,-0.144700,-0.131178,0.351250,-0.227932,0.199576,0.139514,-0.323833,-0.112158,0.138453,-0.092492,0.116219,0.581103,-0.179614,-0.569399,0.173770,0.405389,-0.219474,-0.223680,0.104045,-0.120452,-0.021105,0.022124,0.243584,-0.346068,-0.076615,-0.254602,-0.124279,-1.004448,-0.067962,-0.015709,0.185102,-0.576721,0.650675,0.042348,-0.396225,0.246101,-0.149956,0.101496,0.112091,0.386339,0.584120,-0.489091,0.103995,-0.377917,0.238065,0.612600,0.179616,-0.535247,0.417702,-0.421944,-0.427582,-0.021149,-0.162697,-0.618871,-0.010992,0.015554,0.074472,-0.019157,0.066728,-0.574205,0.256447,0.180099,-0.222388,-0.078788,-0.625280,-0.097612,-0.334756,-0.219277,-0.625898,-0.449335,0.065467,0.019824,-0.562031,0.916247,-0.831739,0.317886,0.408047,0.305705,-0.212843,0.835636,0.300207,0.022854,-0.237309,0.152179,0.272674,-0.194174,0.286196,0.226142,0.320430,0.007556,0.154074,-0.785684,0.550534', '25880986', '1303077', '1303542', '26021055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5919324', 'B区32号', '剧情', '自从富人沈昂买下亦商别墅B区32号时，他便饱受各种离奇怪异事件所困扰，最终导致精神失常，并对家人和医生宣称这幢别墅里有鬼出没。沈昂的妻子高雨彤（邓紫衣 饰）对这一说法难以置信，她约上好友麦克（TAE 饰）来到亦商别墅，在房地产中介丁先生的引领下走入了这幢已被封闭良久的豪宅。屋内阴森凄凉，令人不寒而栗。及至夜晚，更有许多奇怪的声音和事件困扰着雨彤，而且情况愈演愈烈。为了查明真相，麦克用随身携带的摄像机真实记录下白天和夜晚发生的一切……本片号称伪纪录恐怖片《鬼影实录》的亚洲版，由中国最具传奇色彩的编剧张二参与剧本创作，这也是他继《异度公寓》以来推出的又一经典巨作。©豆瓣', '邓紫衣', '吕建民', 2.4, 6401, 'tt1997281', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1167605243.jpg', 91.5, 4.5, 1.3, 0.3, 2.4, '0.063417,-0.021202,-0.669493,0.307318,0.436667,0.067120,0.926835,0.029625,-0.690095,-0.617042,0.242899,0.606441,-0.507200,0.218908,0.368112,-0.035971,-0.229174,-0.329130,-0.372170,-0.428038,-0.175087,-0.387885,-0.306457,-0.287503,0.106360,-0.050306,0.139929,0.307076,-0.406829,0.407847,0.361513,0.418553,-0.306141,0.551094,0.023174,-0.051233,0.119579,0.116406,-0.185122,-0.056859,-0.108910,-0.373569,-0.091765,0.230381,0.005312,0.228847,0.578679,-0.252886,-0.534104,0.169237,0.295628,-0.066561,-0.257849,0.089281,0.329733,0.055197,0.336997,0.442031,-0.269912,-0.100060,-0.084957,-0.108734,-0.759925,0.097794,0.269194,0.008176,-0.257234,0.185817,-0.137439,0.013136,-0.085375,-0.190496,0.250681,0.056905,0.579174,0.627426,-0.080098,0.041115,-0.209798,0.184528,0.386480,0.026055,-0.172182,0.253748,-0.184145,-0.494394,-0.107417,0.077293,-0.526120,0.054139,0.271298,-0.001199,0.118485,-0.061665,-0.607658,-0.037998,-0.012950,-0.282902,-0.105391,-0.094889,-0.154461,-0.690932,-0.098958,-0.263749,-0.124004,0.009957,0.050524,-0.146478,0.341005,-0.486101,0.389377,0.229169,0.254656,-0.373132,0.447478,-0.116375,0.144195,-0.014959,-0.312454,0.340227,0.065932,0.410619,-0.135811,0.302450,-0.178599,-0.376230,-0.438487,0.300600', '10466639', '1316693', '1292528', '1295674');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5919333', '大明猩', '剧情', '中国容华杂技团有一个尽人皆知的动物明星，它就是会打棒球的低地大猩猩灵灵。受老团长影响，灵灵很早便学习击打棒球，而从小和它一起长大的15岁驯兽师赵薇薇（徐娇 饰）与灵灵合作默契，并且能够用人类和猩猩的语言交流。可是老团长为了让山地大猩猩雷霆和灵灵组成击打组合而债台高筑，在他去世后，薇薇以柔弱的臂膀支持着杂技团的运营，却渐渐被债主逼到绝境。危急时刻，韩国职棒的金牌经纪人成忠秀（成东日 饰）找到薇薇，他花言巧语，邀请灵灵以正式球员的身份加入积分垫底的韩国斗山队。为了早日还清债务，薇薇带着灵灵背井离乡，展开了一段前途未卜的职棒之旅……本片根据韩国漫画家许英万的原作《第七个球队》改编。©豆瓣', '徐娇', '金容华', 5.5, 16386, 'tt2969458', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2018584477.jpg', 10.6, 25.7, 45.4, 13.6, 4.8, '0.054712,-0.294904,-0.218226,0.663202,-0.026885,-0.100221,0.264854,0.225589,0.069434,0.104904,0.449673,0.779987,-0.193345,0.335011,0.158432,-0.187475,0.121019,-0.958892,-0.084592,-0.131813,-0.098409,-0.597922,0.070859,0.269939,-0.137127,-0.174929,0.784944,-0.280754,-0.008365,0.744899,0.074370,-0.006158,0.002558,0.038744,-0.271624,0.072506,0.102541,-0.141759,-0.151261,0.271694,0.243933,0.179868,-0.148226,0.215276,0.087069,0.226736,0.645241,-0.510159,0.292920,-0.228056,0.432261,-0.109500,0.125814,-0.004124,0.403537,-0.122499,0.384336,0.218709,-0.185346,0.156462,-0.083149,-0.217651,-0.674248,0.430627,-0.075434,-0.250377,-0.750083,0.365077,0.108615,0.401993,0.184333,0.064205,0.141307,0.421459,0.122282,0.307473,-0.256841,0.295946,-0.059099,0.172726,0.465779,-0.272665,-0.516043,0.359976,-0.094620,-0.204373,-0.101318,-0.387549,-0.682843,-0.111067,0.317811,-0.092591,-0.122280,-0.148052,-0.623623,0.157110,-0.157052,-0.258889,0.115973,-0.018095,0.035610,-0.452942,-0.313679,-0.342197,-0.194062,-0.083065,0.033360,-0.238567,0.925836,-0.774673,-0.027181,0.676957,0.347660,-0.567517,0.664299,-0.106932,0.019693,-0.107787,-0.187270,0.074020,-0.213691,0.084006,0.339841,0.219210,-0.036366,-0.045693,-0.134531,0.293307', '3811356', '3445516', '6101834', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5919334', '痛症', '剧情', '因为年幼时失去家人的经历，让南顺（权相宇 饰）失去了感知疼痛的能力，在他的世界里，所有肉体上的疼痛都感知不到。看似很好的缺陷却给南顺带来了许多消极影响，慢慢的，似乎连心也麻木了。就在这时，他的生命中出现一个叫做朱冬绚（郑丽媛 饰）的女孩。与南顺相反，冬绚不仅能感知到疼痛，且极其敏感，一丝丝细微的伤痛对她而言都有可能有是致命的。但即使这样，冬绚依然是个活泼开朗的女孩，而这样的特质也渐渐感化着南顺。二人从最初的互看对方不顺眼，到被对方吸引，在一系列事件中融化了彼此的内心。但感知南辕北辙的二人面临的是重重考验，最终二人能否携手，一路走下去呢……本片改编自韩国漫画家江草的同名漫画，他的多部漫画被改编成电影、电视剧。©豆瓣', '权相宇', '郭景泽', 7, 12490, 'tt2063842', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1136236359.jpg', 0.7, 6.7, 46.8, 34.3, 11.6, '0.450676,0.047098,-0.882898,0.718655,-0.103320,-0.080490,1.008266,0.058776,-0.636355,-0.039785,0.248844,0.842561,-0.199260,0.010514,-0.067716,0.055811,0.090087,-0.806805,-0.186168,-0.180799,-0.444522,-0.289529,-0.580296,0.064804,-0.321933,-0.478532,0.717840,0.321439,-0.435847,0.318648,0.021163,0.176409,0.158511,0.834931,-0.160156,0.217953,-0.218323,0.016531,0.103935,0.176470,0.425397,-0.391301,-0.157513,0.479779,-0.420891,0.556163,0.818261,-0.322699,-0.255119,0.167558,0.514707,-0.259628,-0.101489,0.147723,0.201030,0.116618,0.158625,0.080543,-0.291057,0.080600,-0.002346,0.291688,-0.973402,0.005753,0.253893,0.399720,-0.566929,0.501808,0.088640,-0.235548,0.014721,-0.405463,0.215694,0.115940,0.263348,0.396103,-0.566731,-0.122967,-0.554961,0.073417,0.881525,0.086564,-0.666860,0.589607,-0.596979,-0.617810,-0.400481,-0.308510,-0.467204,-0.056942,0.188424,0.527514,-0.422535,0.233756,-0.527782,0.288545,-0.019675,-0.218727,-0.341148,-0.611000,0.081106,-0.547108,-0.658259,-0.844284,-0.311061,-0.021302,0.177522,-0.446455,0.934763,-0.815132,0.095411,0.655194,0.093633,-0.321350,0.682023,0.081341,-0.099045,0.032080,-0.098004,0.314242,-0.127531,0.215432,0.358390,0.623507,-0.153264,0.032726,-0.470844,0.847359', '24756472', '30162520', '35158375', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5919538', '只有你', '剧情', '哲民（苏志燮 饰）本是一名优秀的拳击手，现在却依靠白天送水晚上看更来谋生。哲民看更第一晚邂逅了美丽阳光的女生静华（韩孝珠 饰），遗憾的是静华的视力日渐退减再发展下去就是失明。沉默的哲民在静华面前慢慢打开心扉，两人由此相恋。原来哲民是一名孤儿，曾误入歧途做了打手 并因此入狱。如今的哲民决心从头来过，重新走上拳击生涯，一步步实现着他和静华设计的将来。然而，静华的眼疾越来越严重等不及她们去慢慢实现梦想。与之同时，哲民发现那场导致静华眼膜受损的车祸竟和自己当年的行差踏错有关系。强烈地内疚感使得哲民决定铤而走险参加地下拳击比赛，只为最快为静华筹到医疗费。静华能复明吗？哲民能活着和静华重聚吗？©豆瓣', '苏志燮', '宋一坤', 7.8, 58084, 'tt2082180', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2313669107.jpg', 0.3, 2, 28.3, 45.4, 24, '-0.234722,0.034647,-0.289988,0.203861,-0.106191,-0.484252,0.667991,0.150593,-0.236491,-0.322208,0.231472,0.652401,-0.028583,0.196222,0.194760,-0.160846,-0.282712,-0.843433,0.062003,0.063381,-0.280486,-0.377169,-0.218941,0.156670,-0.077019,-0.216986,0.653765,0.097291,-0.157284,0.507416,0.069020,0.032668,0.050313,0.281726,-0.118763,-0.069052,-0.163790,0.313520,-0.422564,0.104280,0.263312,-0.428872,-0.221727,0.158824,-0.102367,0.092968,0.335409,-0.113396,-0.294259,-0.239708,0.303993,-0.250368,-0.150293,0.080809,0.065390,0.148115,0.149798,0.126975,-0.294836,-0.033446,-0.155006,0.007164,-0.630220,0.310378,0.164562,-0.009391,-0.556225,0.187614,0.067081,-0.359937,0.182648,-0.323324,-0.008067,0.505378,0.098978,0.242873,-0.606726,0.073220,-0.296050,0.168170,0.788042,-0.029288,-0.144426,0.475101,0.157591,-0.336253,0.090758,-0.207393,-0.238870,0.184067,0.088888,0.258744,-0.132533,0.090435,-0.414900,0.056565,-0.249290,-0.097109,-0.119675,-0.213505,0.244860,-0.435309,-0.047190,-0.163638,-0.275083,0.203755,-0.017562,-0.608717,0.436122,-0.632258,0.395372,0.391959,0.446974,-0.596554,0.394352,0.033679,0.222104,0.038097,-0.051425,0.312081,-0.340767,0.254402,-0.086429,0.121940,-0.024568,0.022303,-0.367203,0.496604', '30345227', '25828589', '5985887', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5919548', '最终兵器：弓', '动作', '本片以“丙子胡乱”为背景。十三年前，忠臣崔平良以“叛逆”罪名遭到灭族，其一子一女南伊（朴海日 饰）与慈仁（文彩媛 饰）侥幸逃脱，崔平良力战至死。南伊带着父亲的弓箭和嘱托，和妹妹投奔父亲至交金武善一家。时光荏苒，1636年，金武善之子瑞俊向慈仁求婚，因父亲遭遇而消极度日 的南伊深感作为崔家后人身份敏感，欲拒绝这门亲事，无奈瑞俊一片诚意和金武善力主，崔、金两家喜结良缘，然而在大婚当日，后金入侵朝鲜。不久朝鲜仁祖投降称臣，瑞俊和慈仁被满族军队掳走，拥有出众射术的南伊自此沿路追踪，伺机搭救亲人，而南伊神出鬼没的狙杀与跟踪，亦引起了满族弓骑兵大将的注意……©豆瓣', '朴海日', '金汉珉', 7.2, 14410, 'tt2025526', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1308834050.jpg', 1.7, 5.7, 36.7, 42.9, 12.9, '-0.230203,-0.076008,-0.539546,0.673363,0.283431,0.092644,0.168589,0.153722,-0.517844,-0.560065,0.085518,0.655585,0.202984,0.033268,0.388894,-0.291792,0.152562,-0.532636,0.117027,-0.006629,-0.009039,-0.435572,-0.107231,-0.216973,-0.277836,-0.421298,0.562811,0.070449,-0.284352,0.864764,0.355326,0.494352,-0.353033,0.181351,-0.029736,-0.023755,-0.301647,0.086000,-0.584625,0.140729,-0.379305,-0.451367,-0.217906,-0.047528,-0.186378,0.330243,0.477982,-0.373000,0.084269,-0.557915,0.244017,-0.197702,0.072851,0.395461,0.523433,0.112748,0.205231,0.534903,-0.090463,0.027413,-0.064937,-0.007606,-0.595776,-0.064711,0.347293,-0.394744,-0.627178,0.370378,-0.193969,-0.029667,-0.004901,-0.240996,0.215396,0.658647,0.065887,0.142355,-0.305090,0.141720,-0.389823,0.036764,0.645757,-0.096475,0.023329,-0.299545,0.189611,-0.190417,0.371220,-0.274667,-0.410968,0.164004,0.283050,0.146766,0.062280,0.402932,-0.234404,-0.253625,-0.493935,0.383924,0.401582,-0.155767,0.132724,-0.333334,-0.151678,-0.336734,-0.434136,0.116858,0.209935,-0.040315,0.452295,-0.525653,0.102508,0.044804,0.586104,-0.917331,0.456563,0.360410,0.120768,-0.062634,-0.102095,0.229127,0.316074,-0.196077,0.051972,-0.368812,-0.223672,-0.228366,-0.110751,-0.115149', '1297574', '10604851', '3598221', '1482541');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5920220', '死亡笔记', '剧情', '凭借《纸上城市》（Paper Towns）而展露头脚的新人纳特·沃尔夫（Nat Wolff）最近正洽谈主演恐怖片《死亡笔记》（Death Note），该片由华纳兄弟公司出品，根据同名热门日本漫画改编。《死亡笔记》为大场鸫（Tsugumi Ohba）创作、小畑健（Takeshi Obata）绘画，是一套于2003年12月至2006年5月连载于集英社《周刊少年Jump》的心理悬疑推理漫画。故事主角是一个高中生，他无意中捡到了一个笔记本，发现自己只要把一个人的名字写在笔记本上，那个人就会立刻死去。这名高中生制造的一系列神秘死亡事件引起了一名侦探的注意，他开始追踪凶手，并试图解开事情的真相。《死亡笔记》在日本曾被改编成一套动画电视剧、两部真人电影和一套视频游戏。华纳几年前就买下了美版电影的版权，直到今年初才定下让《不速之客》（The Guest）的导演亚当·温加徳（Adam Wingard）来执导。', '纳特·沃尔夫', '亚当·温加德', 4.2, 7519, 'tt1241317', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2473039747.jpg', 33.9, 35.3, 22.7, 5.1, 3, '0.161359,-0.217431,-0.182765,0.595638,0.228624,-0.117469,0.342078,-0.180326,-0.522543,-0.554023,0.269055,0.780888,-0.508595,0.170727,0.297126,-0.000209,-0.411726,-0.766312,-0.171160,-0.271173,-0.128270,-0.212427,-0.330634,-0.218627,-0.085046,-0.251745,0.930119,0.103124,-0.455539,0.094587,0.339574,0.061057,-0.427800,-0.041254,0.132899,0.272678,0.210693,-0.218369,-0.094368,0.396743,-0.056907,-0.325105,-0.263409,0.074939,-0.107671,0.177219,0.983093,-0.024673,-0.255332,0.108618,0.965158,-0.049476,-0.311693,-0.323778,0.421324,0.325365,0.296547,0.264155,-0.104988,0.072394,-0.219262,-0.389486,-0.641189,0.047807,-0.075301,0.285468,-0.355668,0.183549,-0.512099,0.278710,0.126686,-0.354379,-0.028979,-0.033662,0.669888,0.310927,0.177398,0.039604,-0.213213,0.847213,0.048333,0.025845,-0.112204,0.563001,0.223560,-0.422200,-0.574949,-0.225106,-0.300762,0.428107,0.427452,-0.127782,-0.222717,0.043605,-0.638023,-0.006823,-0.082946,-0.479936,0.290459,-0.090073,-0.125292,-0.868293,-0.324045,0.283489,0.002502,-0.336248,0.273241,-0.441059,1.000447,-0.414003,0.260300,0.719668,-0.018750,-0.297846,0.524943,-0.033369,-0.229608,-0.141454,0.196106,-0.059760,0.176082,0.264122,0.102277,0.223172,0.204946,-0.433531,-0.323344,0.536384', '1322847', '22265121', '5403927', '27167055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5924362', '与犯罪的战争：坏家伙的全盛时代', '剧情', '1990年，韩国总统卢泰愚发起“与犯罪的战争”，在釜山警方的严打中，黑帮幕后人物崔翼贤（崔岷植 饰）因拘禁企业家落网，由此揭开了他游走于黑白两道的传奇故事……1982年，时任监督科公务员的崔翼贤在肥的流油的海关如鱼得水，但上司在遭到举报之际将崔翼贤推出背黑锅。前途晦暗的崔翼贤孤注一掷做起对日的毒品生意，得以结识了同族的黑帮大哥崔炯培（河正宇 饰），以崔氏望族出身自豪的崔翼贤很快与崔炯培结为同盟。二人凭借各自的人脉和暴力，在釜山的黑道世界创出天地。1985年，崔翼贤受企业家所托，入股夜总会与崔炯培里应外合将釜山黑帮头目金坂虎扳倒，崔氏黑帮蒸蒸日上之时，翼贤与炯培的关系，在混乱的时代洪流中出现了裂痕……©豆瓣', '崔岷植', '尹钟彬', 7.9, 65776, 'tt2082221', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1347785531.jpg', 0.2, 1.3, 23.1, 52.6, 22.7, '0.232347,0.049060,-0.584915,0.459920,0.180492,-0.014521,0.400871,0.338080,-0.808069,0.080034,0.044781,0.735619,-0.217561,0.145121,0.415215,-0.290640,0.107117,-0.994810,-0.089978,-0.154969,0.099469,-0.311360,-0.633173,-0.252447,-0.202691,-0.450466,0.622406,0.235270,-0.276821,0.432263,0.189145,0.292880,-0.264372,0.188359,-0.259285,-0.249008,0.076953,0.129703,-0.809256,0.129929,-0.139248,-0.568528,-0.061462,-0.198712,-0.007028,0.354063,0.517774,-0.167243,0.114640,-0.364286,0.383079,-0.293361,-0.289543,0.089918,0.694873,0.153890,0.049257,0.632546,-0.252714,-0.224966,0.057044,-0.207523,-0.801803,-0.250283,0.261773,0.100870,-0.526627,0.494232,-0.015997,-0.130491,-0.120012,-0.313189,0.123520,0.609110,0.269442,0.418777,0.014152,0.394030,-0.567986,0.246954,0.663983,0.085682,-0.168210,-0.036139,-0.041822,-0.406375,-0.102920,-0.406003,-0.177561,-0.340934,0.440866,-0.298024,-0.084543,0.536765,-0.841783,-0.212172,0.013148,-0.045037,0.281661,-0.158811,-0.103119,-0.504693,-0.464773,-0.456673,-0.096043,0.127179,0.423872,0.007017,0.617080,-0.892332,-0.062338,0.482970,0.364531,-0.571214,0.726641,-0.013108,0.227216,-0.282820,-0.234254,-0.117213,0.409041,0.269622,0.190971,0.153190,-0.417601,-0.335623,0.049936,0.128142', '26425068', '4301278', '30345227', '1308237');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5938000', '夜幕下的故事', '动画', '这是一部由六个“枕边故事”组合而成的剪影动画。夜幕下，老人、男孩和女孩三个人聚在一起，一个负责美工，一个设计服装，一个撰写剧情，一个个奇妙的故事就此诞生。“狼人的故事”，讲述了月圆之夜会化身成狼的王子和两个公主之间的故事；“堤忠与无人知晓的美人”，讲述了堤忠无意进入死亡国度之后，历经种种冒险的故事；“黄金城的神选者”，讲的是少年勇士对抗黄金城守护神的故事；“敲鼓男孩”，讲述了一个热爱敲鼓的少年和得到神鼓的故事；“不说谎的男孩”讲的是这样的故事：国王有一匹会说话的马，而更神奇的是，照顾马儿的男孩永不说谎，于是两个国王打赌，能否让男孩说谎；“化身鹿的女孩与建筑师之子”，建筑师的儿子和一名少女相恋，女孩却被一只怪兽变成一头胆小的鹿，于是，少年开始了历险之旅……©豆瓣', '朱利安·贝朗米斯', '米歇尔·欧斯洛', 8.3, 9386, 'tt1828229', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p841549791.jpg', 0.2, 1.3, 16.8, 47.2, 34.5, '0.224716,-0.214753,-0.270934,0.869343,-0.022168,-0.066138,0.956800,-0.138009,-0.420218,-0.219544,0.324030,0.887215,-0.258868,0.319155,0.411169,-0.013759,-0.066680,-0.573699,-0.240275,0.078138,-0.158735,-0.345604,0.026668,-0.160336,-0.068170,-0.286856,0.837637,-0.109369,-0.236310,0.331901,0.317717,-0.018992,-0.330566,0.083180,-0.311608,-0.006491,0.054993,0.182827,0.165103,0.187795,-0.254138,0.043003,-0.000979,0.022652,-0.545170,0.068201,0.872087,-0.833962,-0.067353,-0.325674,0.519927,-0.226430,-0.132262,-0.171361,0.350742,0.076766,0.428625,0.075219,0.325902,-0.341288,-0.084658,-0.388416,-0.567589,0.006986,0.094812,0.505693,-0.667349,0.144610,0.101220,0.084014,0.309151,-0.310404,0.197328,0.101180,0.648494,0.544019,0.176333,-0.062389,-0.505216,0.380753,0.623746,0.093709,-0.383925,0.444768,-0.176510,-0.668832,-0.275917,0.023478,-0.610718,0.250339,0.212523,-0.207961,-0.282972,0.243992,-0.839500,-0.062951,-0.244345,0.036881,0.087998,-0.637593,-0.261061,-0.229487,-0.079814,-0.182180,-0.081359,0.021301,0.297724,-0.242254,1.166675,-0.799688,0.140324,0.454865,0.035599,-0.287813,0.629432,0.021345,0.209362,-0.336032,0.196409,0.199846,0.088794,-0.168729,-0.167116,0.525789,-0.184092,0.044432,-0.652237,0.303003', '1467779', '2053515', '1302661', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5948613', '藏獒多吉', '剧情', '少年田劲的父母早年为了将西医带入藏地做出了无数的牺牲，由于无法适应高原的生活，田劲的妈妈带着尚在襁褓中的儿子返回内地，爸爸拉格巴则在高原继续着他的事业。数年过后，妈妈病故，无依无靠的田劲来到高原寻找爸爸，然而心中却藏着无数的怨恨。拉格巴终日忙碌行医，任凭儿子自行学习牧羊。某天，田劲遭到狗熊的威胁，幸亏一只金色的藏獒相助，后来更因种种机缘让他与这只名叫多吉的藏獒成为最亲密的朋友。与此同时，草原上出现了专门残害生灵的恶魔，牧民的平静生活被彻底打破……本片根据杨志军的小说《藏獒》改编，由中日两国联合制作，日本著名漫画家浦泽直树还担任了人设和导演的工作。©豆瓣', '刘婧荦', '小岛正幸', 8, 13536, 'tt2411128', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1095763116.jpg', 0.3, 2.3, 21.9, 49, 26.6, '0.153693,-0.033865,-0.637420,0.680272,0.139454,-0.294120,0.457651,0.129815,-0.564638,-0.350317,0.168560,0.517850,0.056343,0.225164,0.143440,-0.194009,-0.291196,-0.538249,-0.146247,0.107956,-0.050614,-0.198305,-0.357643,-0.072058,-0.296144,-0.305807,0.673349,-0.002510,-0.177660,0.479515,-0.032014,0.299419,-0.184631,0.382823,-0.292198,0.090196,-0.032096,-0.058341,-0.319922,0.250085,0.202155,-0.351013,0.054969,-0.062741,-0.104114,0.279752,0.812700,-0.547728,-0.101705,-0.345589,0.348999,-0.325070,-0.081632,0.036130,0.307120,-0.017229,0.193277,0.188979,-0.264801,0.158745,0.051596,-0.163932,-0.585846,-0.158249,0.197727,0.289432,-0.757571,0.295982,0.106742,-0.104439,0.163677,-0.435975,0.188871,0.526199,0.003651,0.516262,-0.217262,0.202577,-0.397270,0.354143,0.635569,-0.220311,-0.005574,0.108118,-0.199222,-0.508787,0.272705,-0.223814,-0.512756,-0.208613,0.296826,-0.175915,-0.213069,0.325436,-0.744683,0.034775,-0.167605,-0.283534,0.181129,-0.300099,-0.121845,-0.493460,-0.039326,-0.336478,-0.069315,0.027116,0.213107,-0.327315,0.826201,-0.768711,0.289658,0.326903,0.352983,-0.120986,0.616097,-0.067652,0.330402,-0.109077,-0.135120,0.364084,0.004977,0.362707,0.156584,0.138844,0.044879,-0.193495,-0.311238,0.376312', '3811356', '3445516', '21360412', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5948656', '爱情真可怕', '喜剧', '同样是模特，为何差距却如此的大呢？作为家庭购物的试吃模特，尚烈（林昌正 饰）时不时会有这样的想法。他正暗恋着内衣模特素妍（金圭丽 饰）。素妍拥有着天使的面容和魔鬼般的身材。在尚烈看来，二人根本不可能有发展的机会。自己，样貌、学历、职业都差强人意，素妍根本不可能看上自己。可偏偏，上天给了尚烈一次接近心中女神的机会。一个下雨的晚上，二人被困在了雨里，可能是气氛太合适，素妍向尚烈袒露了心中的困惑和工作中的不顺遂，二人边聊边喝。再次有意识时，已经是第二天早上，清醒的尚烈发现自己一丝不挂的躺在汽车旅馆的床上，而记忆里，是自己和女神绮丽的梦。难道他真的幸运的和素妍共度了一晚，还是说一切只是个梦？©豆瓣', '任昌丁', '郑宇哲', 6, 5902, 'tt1741669', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1075604195.jpg', 3.6, 17, 58.8, 16.2, 4.5, '0.269988,0.127416,-0.812283,0.474818,-0.150383,-0.285080,0.731139,0.218380,-0.531788,-0.260243,0.188632,0.744400,-0.242778,0.273944,0.187368,0.041059,-0.274184,-0.806925,-0.115194,-0.117564,-0.441978,-0.421507,-0.285087,-0.022119,0.027917,-0.293470,0.495259,-0.031419,-0.155409,0.354238,0.459938,-0.095778,0.148576,0.683218,-0.342523,-0.210889,-0.018484,0.286204,0.045072,0.306560,0.262627,-0.231213,-0.237564,0.353480,-0.021221,0.293231,0.365402,-0.229097,-0.478935,0.065172,0.351871,-0.145449,-0.045681,0.198921,0.141078,-0.329261,0.384486,-0.136817,-0.125321,-0.042504,0.101169,0.103841,-0.740485,0.122068,0.144720,0.246390,-0.667734,0.493877,0.147800,-0.330945,0.181703,-0.320548,0.218185,0.249229,0.342603,0.544302,-0.114763,-0.110972,-0.626204,0.116266,0.598486,0.402443,-0.137140,0.806759,-0.227619,-0.584742,-0.398544,0.007608,-0.491880,0.131035,0.013398,0.198240,-0.199607,0.000235,-0.499157,0.234335,-0.169426,-0.041803,-0.280450,-0.517755,-0.087376,-0.149570,-0.084767,-0.707165,-0.465567,0.262455,0.053297,-0.393024,0.608077,-0.909518,0.066235,0.574858,0.297893,-0.346308,0.823972,0.247707,-0.190444,-0.082522,0.039342,-0.047889,-0.312287,-0.067248,0.149110,0.402515,-0.004044,0.009357,-0.520167,0.437935', '1783461', '1306916', '1389971', '1937946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5954347', '赢家', '剧情', '巨源文化的项目总监王大利（王太利 饰）在人过中年时事业小有成就，妻子霍小燕（霍思燕 饰）美丽温柔，女儿可爱乖巧。但是他依然无法避免中年危机，大利和小燕的爱情似乎走到了尽头，夫妻俩要么冷眼相向，要么便激烈争吵。在一次夜晚的争吵过后，大利突遭车祸，在恍惚之间，他的灵魂似乎被震出了体外。在接下来的短暂时间内，他脑中的时间开始倒流，并在一段段对他来说具有十分重要意义的时间点定格，母亲去世、妻子生产、青涩的中学时代……爱情出了什么问题？人生出了什么问题？看似光鲜的王大利，究竟是人生的赢家还是输家？©豆瓣', '王太利', '肖央', 6.6, 14589, 'The Winner', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p944313458.jpg', 2.1, 11.3, 49.1, 30.3, 7.2, '-0.026944,0.391066,-0.741021,0.283190,-0.132279,-0.342231,0.921973,0.078313,-0.664349,-0.274839,0.148736,0.404158,-0.136767,0.148686,0.302023,-0.162624,-0.156513,-0.599636,0.066242,-0.108057,-0.198873,-0.367471,0.001480,-0.124738,-0.082182,-0.348483,0.505929,0.276172,0.028373,0.232158,0.162300,0.053773,-0.086442,0.633538,-0.153874,0.057731,0.014621,0.256700,-0.447258,0.012649,0.226631,-0.319190,-0.290927,0.143383,-0.179596,0.355902,0.653833,-0.355536,-0.440579,0.110289,0.530033,-0.160306,-0.208902,0.115904,0.357911,-0.081469,0.433253,0.173416,-0.096624,-0.149535,0.033062,0.017903,-0.541146,-0.166222,0.003357,0.211903,-0.420807,0.737544,0.085593,-0.365243,0.053229,-0.401513,0.288516,0.296098,0.453814,0.318790,-0.467056,0.195907,-0.345848,0.367521,0.672621,0.182647,-0.504048,0.690674,-0.290877,-0.521334,-0.464751,-0.358669,-0.231318,0.108910,0.251385,0.093444,-0.195945,0.336606,-0.376985,0.129108,-0.135617,-0.026645,-0.058399,-0.373471,-0.353527,-0.141478,-0.106489,-0.624143,-0.418568,0.146719,0.064098,-0.125705,0.664126,-0.746504,0.004726,0.485631,0.215820,-0.167103,0.469409,0.273447,0.253556,-0.647774,-0.081516,0.316747,-0.283618,0.233957,-0.030129,0.320759,-0.000365,-0.003852,-0.373658,0.641741', '1304989', '3742987', '1307561', '1304862');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5954505', '密室之不可靠岸', '剧情', '阔气豪爽的富二代董磊（杨坤 饰）即将于心爱的女友苏静静（倪虹洁 饰）完婚，他邀请圈内好友共同参加他的新婚豪华游轮蜜月游，推理小说家柳飞云（苏有朋 饰）及其经纪人李晓峰（孙一理 饰）都在名单之中。游轮上，帅哥靓女，美酒佳肴，劲歌热舞，俨然一个与世隔绝的快乐国度。柳重逢了小学时代暗恋的对象苏静静，也结识了苏的三个美丽女同事：肖扬（毛俊杰 饰）、朱迪（周韦彤 饰）和韩菲菲（吴辰君 饰）。夜幕降临，主宾涌向甲板参加化妆舞会，可就在这灯红酒绿、群情高涨的狂欢时刻，一宗宗杀人案接连发生。豪华游轮瞬间变成了杀气四溢的孤岛……©豆瓣', '苏有朋', '张番番', 5.2, 14942, 'tt2062978', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1262032915.jpg', 13.4, 30, 41.8, 11.7, 3, '0.162274,0.069372,-0.731094,0.553004,0.102347,0.040719,0.683877,0.217315,-0.178346,-0.037917,0.160491,0.413651,-0.507794,0.885638,0.713249,-0.066559,0.102713,-0.639189,-0.119716,0.006580,-0.207654,-0.220994,0.003909,-0.345026,0.129201,0.072189,0.492394,0.298406,0.197286,0.638391,0.904445,-0.028968,-0.278242,0.451206,-0.264201,-0.131990,0.367118,0.468009,-0.330970,-0.011069,-0.520770,-0.220162,0.178634,0.063078,0.234230,0.030286,0.688002,-0.091090,0.125952,0.079430,0.272695,-0.004529,0.208241,0.035404,0.523111,0.023931,0.175220,-0.168201,0.011315,-0.068242,0.118958,-0.139141,-0.015269,0.113854,0.330153,-0.158138,-0.077797,0.637296,0.018964,-0.104117,-0.159953,0.235658,0.140976,-0.067575,0.359391,0.114333,0.172837,0.330229,-0.328391,0.521426,0.333559,0.397102,-0.141437,0.217813,-0.198666,-0.533136,-0.170167,-0.162034,-0.392813,-0.246960,0.370321,-0.309637,0.209603,0.107348,-0.582569,-0.113976,0.148832,0.048123,0.094898,-0.042711,-0.225642,-0.863404,-0.104740,-0.385514,-0.031037,0.179728,0.069344,-0.095440,0.752826,-0.530962,-0.020015,-0.004812,-0.133493,-0.424432,0.797537,0.068678,0.125853,-0.013981,-0.036918,0.202971,0.065426,0.125835,-0.030931,0.419394,-0.475452,0.176451,-0.225967,0.326536', '26687241', '1418179', '25922902', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5955975', '自杀房间', '剧情', '富家子多米尼克（雅酷朴·盖尔秀 Jakub Gierszal 饰）有着宠惯他的父母，众多朋友和无忧无虑的生活。一次晚会上因为打赌输了他与班上帅哥亚历克斯（巴尔托什·格尔勒 Bartosz Gelner 饰）接吻，第二天整个过程变成了网络视频。亚历克斯一口咬定多米尼克“有 生理反应”，多米尼克一下成为了话题焦点。父母只知道用物质满足儿子，苦闷的他干脆辍学沉浸在网络聊天室中。一天他在网上结识了粉红头发的女孩席尔维亚（诺玛·格西洛斯卡 Roma Gasiorowska 饰），受邀进入到一个专门给有自杀倾向的少年准备的虚拟世界，那里被称做“自杀房间”......《自杀房间》采用真人和三维动画结合的方式，讲述了一个少年由于对现实绝望，自我流放到网络虚拟空间的故事，带领观众目睹了一场青春无因的反抗与自我毁灭。该片入围2011年柏林电影节全景单元，被誉为“波兰近20年最酷电影”。', '雅酷朴·盖尔秀', '扬·科马萨', 7.1, 19391, 'tt1808454', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1482439082.jpg', 1.3, 8, 42.5, 33.1, 15, '0.246810,0.139257,-0.562610,0.438452,-0.060678,-0.086603,0.590029,0.109140,-0.365757,-0.127385,0.074338,0.684295,-0.520688,0.485492,0.478480,0.039327,-0.419082,-0.761477,0.045395,-0.013096,-0.307343,-0.492041,0.041925,-0.112725,-0.064110,-0.588933,0.545800,-0.065232,-0.244118,0.398685,0.265315,0.250315,-0.040093,0.273204,0.144225,0.057071,0.209519,-0.091699,-0.264225,0.243131,-0.262222,-0.051784,-0.145691,0.018177,-0.012255,0.130368,0.749651,0.014799,0.007351,0.078080,0.507908,-0.256011,-0.274507,0.072150,0.308995,-0.145983,0.322688,-0.001536,-0.011308,-0.084830,0.069350,-0.116299,-0.489465,-0.008503,-0.045571,-0.005270,-0.212577,0.532748,-0.131628,0.046058,0.021419,-0.332527,0.032207,0.108820,0.409698,0.379109,-0.033286,-0.121881,-0.303479,0.398361,0.500964,0.024980,-0.406570,0.344633,-0.104935,-0.321138,-0.339728,-0.228094,-0.427304,0.141771,0.331820,-0.177931,-0.202928,0.339240,-0.608119,-0.120951,-0.143004,-0.392920,0.202812,-0.299275,-0.189846,-0.691367,-0.352415,-0.031111,-0.211736,-0.113687,0.083427,-0.303946,0.620679,-0.722176,0.298238,0.525394,0.180626,-0.288331,0.800791,0.145026,0.061394,-0.181368,0.113276,0.239608,0.144008,0.070675,0.012073,0.270461,-0.181951,0.041454,-0.583320,0.544375', '3811356', '25785124', '2334814', '1302050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5959260', '小亚细亚往事', '剧情', '位于亚洲西南部的安纳托利亚，一个远离城镇的蛮荒山区，肃杀静谧。正是黄昏时分，自山路的另一头驶来三辆汽车，最终停靠在路边一处喷泉旁边。车上的人走下来，似乎在辨认着什么东西。原来不久前发生一起命案，嫌疑人将尸体掩埋在荒原的某个角落。被捕后，嫌疑人带着当地的警察、法医、来自主 城镇的检察官以及其他不同身份的人四处寻找藏尸地点。犯人依稀记得几个标志性物件，却无法确定哪里才是真正的藏尸地。这群人彻夜奔波在山谷中，无聊之时便随意聊天，诉说着心中的隐秘以及对现状的不满。漫漫长夜似无尽头……本片荣获2011年戛纳电影节评委会大奖、2012年都柏林国际电影节影评人奖最佳导演奖、2011年亚太电影节最佳摄影、最佳导演和评委会大奖。©豆瓣', '穆罕默德·乌祖内尔', '努里·比格·锡兰', 7.8, 10068, 'tt1827487', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p986278389.jpg', 1.1, 3.6, 23, 47.7, 24.7, '0.191919,-0.060680,-0.663528,0.646646,0.411035,0.041886,0.794304,-0.050666,-0.645964,-0.156558,0.432404,0.692506,-0.165108,0.084520,0.247078,0.105611,-0.694644,-0.540379,-0.352526,-0.441538,-0.354806,-0.415631,-0.404815,0.080362,-0.153719,0.077481,0.529842,0.327248,0.103220,0.637663,0.271452,-0.121911,-0.688917,0.189588,-0.270962,-0.263014,0.479343,-0.070013,-0.334318,0.227500,-0.184352,-0.461374,-0.399652,-0.193536,0.182474,0.277207,0.746474,-0.047023,-0.069720,0.137872,0.259201,-0.258401,0.119703,-0.189726,0.512640,-0.257942,0.385428,0.191823,-0.133374,0.117876,-0.022173,0.044845,-0.265449,0.092804,-0.058125,0.380789,-0.267928,0.444289,0.196057,-0.081038,-0.158518,-0.205403,0.595770,-0.055920,0.116377,0.122398,0.057640,0.035794,-0.423377,0.021843,0.410236,0.034956,-0.157738,0.109168,-0.113228,-0.606473,-0.064807,-0.085902,-0.362212,-0.134408,0.384967,0.008218,-0.166109,-0.130415,-0.378287,0.261483,-0.013610,-0.446565,0.002263,-0.023276,-0.354498,-0.841944,0.281392,-0.113982,0.154533,0.025238,-0.030541,0.106369,0.321811,-0.309321,0.324721,0.573281,0.051599,-0.057670,0.646443,-0.369558,0.155407,-0.235973,-0.233942,0.258487,-0.053001,0.519909,-0.203792,0.182604,-0.365233,-0.267961,-0.464962,0.230692', '10466639', '2159244', '1316693', '21349734');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5959696', '星爸客', '喜剧', '大卫（帕特里克·华德 Patrick Huard 饰）是一个标准的废柴男，已经42岁的他依然在父亲的店里打工，而怀有他骨肉的女友瓦莱丽（朱莉·勒布勒东 Julie LeBreton 饰）最终选择了离开这个不称职的男友。一个访客的到来彻底改变了大卫失败的生命，他告诉大卫，大卫曾化名“星巴克”所捐赠的精子，如今已经变成了533个孩子，这也就意味着，在突然之间，大卫成为了533个孩子的生父。更严重的事情还在后面，这五百多个孩子里，有142个孩子联名对大卫提出了诉讼，他们要求大卫从“星巴克”这个假名的背后走出来，不要再遮遮掩掩。在好奇心的驱使下，大卫隐藏了真实身份，和他的孩子们开始了接触，没想到，正是这些孩子们给予了大卫新的人生希望。©豆瓣', '帕特里克·华德', '肯·斯科特', 7.4, 8823, 'tt1756750', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1384543509.jpg', 0.6, 3.5, 36.6, 46.1, 13.3, '0.334546,-0.073145,-0.667694,0.498755,-0.574249,-0.551917,0.723290,0.114826,-0.459545,-0.250480,0.141461,1.045487,-0.171148,0.331444,0.116589,0.110083,-0.308189,-0.514395,-0.075332,-0.294764,-0.468683,-0.672746,-0.110338,-0.142327,0.008625,-0.062425,0.405322,-0.164943,-0.090604,0.347267,0.618578,0.162046,0.328693,0.444745,-0.294358,0.296978,0.118289,-0.026241,-0.126577,0.291717,0.105823,-0.100072,-0.008852,0.317870,-0.071883,0.599319,0.445263,-0.260869,-0.194595,-0.017264,0.461257,-0.178607,0.000228,0.286725,0.229890,-0.125039,0.208265,0.099364,-0.302210,-0.038565,-0.017737,-0.036233,-0.853476,0.049214,-0.014010,0.168169,-0.746044,0.368865,-0.081868,0.019251,0.055020,-0.442659,0.157806,0.323587,-0.105494,0.360755,-0.364715,-0.085733,-0.528143,0.006966,0.646938,-0.099927,-0.201054,0.322717,-0.176870,-0.291395,0.028865,-0.068105,-0.588718,0.006807,0.318657,0.022461,-0.303952,0.215001,-0.398038,0.022568,-0.238956,0.003267,0.052994,-0.315546,0.024314,-0.353891,-0.135127,-0.339298,-0.354983,0.031703,0.073393,-0.250551,0.833323,-0.667429,0.260176,0.589177,0.412313,-0.580064,0.683877,0.222007,0.293876,-0.244774,-0.088944,0.168447,0.069742,0.199712,0.200300,0.491146,0.188608,-0.332965,-0.314960,0.476865', '34890458', '30162520', '1783461', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5960606', '再见我们的幼儿园', '剧情', '好朋友洋武因病退学，无法参加毕园典礼。与他同在朝阳幼儿园紫罗兰组的康娜（芦田爱菜 饰）、拓实（佐藤瑠生亮 饰）、美琴（本田望结 饰）、俊佑（黑田博之 饰）、优衣（庵原凉香 饰）偷偷溜出幼儿园，从新宿搭上了开往高尾的中央线列车，去寻找他们的好朋友。他们在换乘站不慎和优衣失散，还遭遇了会把人变成玉米的流浪汉大叔（岸部一德 饰）。总之，漫漫的旅途中充满了快乐与艰险，他们纯真的友情也经受着考验。与此同时，幼儿园和家长方面急作一团，担任紫罗兰组老师的万里（满岛光 饰）从优衣那里得到线索，独自踏上了寻找的旅程……©豆瓣', '芦田爱菜', '水田伸生', 8.8, 111021, 'tt1831754', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2173712235.jpg', 0.2, 0.8, 11, 36.7, 51.2, '0.361498,-0.221600,-0.488969,0.389521,0.045549,-0.274167,0.438494,0.413399,-0.273925,0.040132,0.152651,0.619524,-0.183885,0.326149,0.426710,0.156257,-0.459105,-0.694465,0.161578,-0.203221,-0.300719,-0.457111,-0.009217,0.077560,-0.020595,-0.174191,0.671932,0.152056,0.083995,0.798076,0.337303,0.312510,-0.433231,0.307289,-0.243443,-0.002250,0.044126,0.272366,-0.115320,0.099038,-0.068817,-0.173701,-0.043730,-0.155464,0.325758,0.236530,0.870608,-0.016502,0.092160,-0.114820,-0.039584,-0.140751,0.125948,0.052225,0.273732,0.056168,0.088395,0.381648,-0.237512,0.178292,0.067396,-0.142513,-0.268531,-0.080337,0.300489,0.147838,-0.586755,0.551365,-0.055285,-0.219058,0.460038,-0.403611,0.214554,0.314912,0.049263,0.212840,-0.086238,-0.086857,-0.353430,0.414825,0.601835,-0.162399,0.058538,0.127213,-0.094203,-0.295980,-0.115505,-0.049342,-0.393921,0.058771,0.297182,-0.047093,-0.096297,-0.119342,-0.701256,0.077068,0.015580,-0.234769,0.146224,-0.340878,0.045038,-0.832211,0.313391,-0.377877,-0.370300,0.290980,-0.058442,-0.096763,0.658733,-0.779504,0.137325,0.341690,0.361228,-0.214699,0.802335,-0.114311,0.242430,-0.242386,0.023337,0.115644,-0.182734,0.687538,0.186577,0.399012,-0.154487,-0.011522,-0.621962,-0.003202', '26365262', '3811356', '5403927', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5960681', '德州电锯杀人狂3D', '惊悚', '美丽女孩希瑟（亚历珊德拉·达达里奥 Alexandra Daddario 饰）原本过着平凡的生活，可却在某天得知自己并非现在父母所生。在此之后，她和男友瑞恩（Trey Songz 饰）、朋友妮基（坦妮娅·雷蒙德 Tania Raymonde 饰）、妮基的男友肯尼（Keram Malicki-Sánchez 饰）以及半路结识的陌生人戴瑞尔（肖恩·西珀斯 Shaun Sipos 饰）驱车前往位于德州的Newt镇。她的亲生奶奶一直生活于此，而希瑟此行的目的即是签署一份遗嘱声明，继承奶奶留给她的财产。财富从天而降，这群年轻人兴奋不已，却不知道有一个恐怖的杀人魔“皮革脸”藏在家中。血腥杀人夜悄悄降临，一切都与当年臭名昭著又令人闻风丧胆的索尔家族有关……©豆瓣', '亚历珊德拉·达达里奥', '约翰·卢森霍普', 5.7, 11699, 'tt1572315', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1757912861.jpg', 7, 25.2, 49.2, 13.2, 5.4, '0.051413,-0.067355,-0.585812,0.533147,-0.118884,-0.184977,0.772084,0.306118,-0.478353,-0.438140,0.167727,0.785490,0.054150,0.201745,0.305209,0.344355,-0.430436,-0.414862,0.136716,-0.164705,0.088291,-0.346938,-0.342738,-0.058327,-0.035802,-0.274946,0.427880,-0.139428,-0.048723,0.438811,0.408381,0.491101,-0.328017,0.329923,-0.230057,0.044875,-0.108989,0.181710,-0.392533,-0.066582,-0.140670,0.131785,-0.114390,0.167473,0.109080,0.263244,0.460948,-0.243864,0.064477,-0.139487,0.321907,-0.242448,0.067995,0.143877,0.185059,-0.217182,0.241580,0.206700,-0.180423,-0.234469,0.289123,-0.151952,-0.638108,-0.049986,0.268208,0.090922,-0.403637,0.319063,-0.367149,0.017000,0.075882,-0.294074,0.224730,0.232223,-0.076706,0.285521,0.071640,-0.098643,-0.346658,0.117198,0.560203,-0.087433,0.046887,0.015837,-0.322937,-0.224762,-0.063329,-0.204236,-0.572198,0.154447,0.105852,-0.031191,0.047753,0.447691,-0.556547,-0.197884,-0.329239,0.050367,0.310535,-0.445137,-0.215728,-0.358113,-0.100131,-0.312022,-0.315921,0.009964,0.047991,-0.208563,0.422903,-0.643954,0.346422,0.391374,0.416041,-0.320973,0.562720,0.099805,0.209107,-0.247898,-0.195704,0.482527,0.343660,0.091787,-0.127769,0.092727,0.057087,-0.001883,-0.156383,0.486483', '3119246', '34890458', '1296534', '1297418');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5964718', '一次别离', '剧情', '纳德（佩曼•莫阿迪 Peyman Moadi 饰）与西敏（蕾拉•哈塔米 Leila Hatami 饰）是一对夫妻，他们的女儿叫特梅（萨日娜•法哈蒂 Sarina Farhadi 饰）。西敏希望一家三口移居国外，但是纳德坚决反对，原因是纳德的父亲患有老年痴呆症需要照顾。两人为此对薄公堂，准备离婚，但是法院驳回了她的请求。西敏赌气回了娘家。西敏走后，纳德分身乏术，聘请了一位护工瑞茨（萨瑞•巴亚特 Sareh Bayat 饰）照顾父亲。但是，父亲如厕问题始终困扰瑞茨，依《古兰经》教义，她感到禁忌重重。瑞茨的女儿陪伴在她左右，也令她分神。几个回合下来，纳德某次回家发现，父亲被绑在床上，出离愤怒的他推倒了瑞茨。没想到怀孕的瑞茨竟然流产，瑞茨丈夫怒不可遏将纳德告上了法庭，他们各执一词，然而真相却出人意料……本片在61届柏林电影节获金熊奖、最佳女演员和最佳男演员银熊奖。', '佩曼·莫阿迪', '阿斯哈·法哈蒂', 8.8, 236995, 'tt1832382', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2189835254.jpg', 0.2, 0.7, 9.1, 41.3, 48.8, '0.063462,-0.056597,-0.741968,0.241233,0.204452,-0.479103,0.640575,0.242258,-0.187907,-0.375871,0.087844,0.719919,-0.167153,0.187161,0.440970,0.147703,-0.333921,-0.531809,0.355101,-0.047655,-0.244666,-0.625658,0.162862,-0.314256,-0.299869,-0.292847,0.231971,-0.275905,0.044226,0.400044,0.397413,0.366041,-0.197394,0.244389,0.003131,0.156628,0.111177,-0.179609,-0.309265,0.165520,0.249692,-0.081658,-0.328476,0.185986,0.297970,0.492611,0.285335,0.009028,0.012959,0.053374,0.265363,-0.303937,-0.129389,0.243463,0.287992,-0.274231,0.198613,0.127454,-0.290843,-0.133508,0.293770,-0.025952,-0.363611,0.351880,0.094426,-0.003932,-0.702283,0.432483,-0.284285,0.075161,-0.130235,-0.286581,0.211284,0.407408,-0.166310,0.295187,-0.159787,0.206681,-0.498833,-0.106303,0.410639,-0.274109,0.076119,0.306077,-0.184667,-0.318648,0.193261,-0.364644,-0.443615,0.043648,0.215073,0.008181,-0.128742,-0.065309,-0.053950,-0.434616,-0.478362,0.047524,-0.185888,-0.326684,0.185730,-0.312584,0.103980,-0.084750,-0.458293,0.040039,-0.100286,-0.151322,0.356584,-0.384827,0.349900,0.266172,0.524018,-0.328588,0.767874,0.267608,0.403803,-0.231244,0.059991,0.268357,0.134032,-0.251768,0.240922,0.189519,0.195750,0.038176,-0.261523,0.161998', '1302384', '2135476