INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5966609', '松林外', '剧情', '浪荡神秘的摩托车手卢克（瑞恩·高斯林 Ryan Gosling 饰）在嘉年华会的表演场上与旧时情人罗蜜尼亚（伊娃·门德斯 Eva Mendes 饰）意外重逢。卢克迫切地希望与罗蜜尼亚重修旧好，却惊讶地发现罗蜜尼亚不仅已经与另一个男人同居，并且自己与罗蜜尼亚还育有一个襁褓中的儿子。于是原本打算离开的卢克一厢情愿为了照顾儿子和罗蜜尼亚留在了这个小镇。为了弥补内心对儿子的愧疚，卢克决定和偶然相识的一位小镇上的男人去抢银行。在最后一次行动中，卢克遭遇了年轻巡警艾弗瑞（布莱德利·库珀 Bradley Cooper 饰）的围堵。年轻的艾弗瑞拥有一个爱他的妻子和同样在襁褓中的儿子。卢克和艾弗瑞，两个身份迥异的男人看上去本是毫无联系，可是他们谁也没有想到因为这起抢劫案，他们之间已经发生的千丝万缕的联系。©豆瓣', '瑞恩·高斯林', '德里克·斯安弗朗斯', 7, 13532, 'tt1817273', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1883430456.jpg', 0.9, 6.4, 46.7, 36, 10, '0.378681,-0.026058,-1.021461,0.668438,-0.294365,-0.433466,1.125329,0.015776,-0.500210,-0.468426,0.232034,0.949226,-0.134851,0.223467,0.282149,-0.061381,-0.458571,-0.736436,-0.165230,-0.130843,-0.315423,-0.588239,-0.423589,-0.118388,-0.140725,-0.224979,0.580202,0.132726,-0.050214,0.667456,0.436785,0.290696,-0.240541,0.387483,-0.274276,0.065153,0.154855,0.162136,-0.360626,0.197799,0.054169,0.197438,-0.265637,0.210731,0.142152,0.505550,0.576697,-0.247965,-0.064283,-0.019259,0.045650,0.093662,0.115625,0.246916,0.152601,-0.139368,0.314592,0.105491,-0.362184,-0.153757,0.266852,-0.052893,-0.702342,0.289526,0.089360,0.310781,-0.607838,0.481762,-0.190966,-0.414908,0.273860,-0.218698,0.214005,0.690211,0.330394,0.398708,-0.094892,0.207850,-0.558186,-0.285021,0.661235,0.164742,-0.220662,0.203379,-0.246475,-0.268775,-0.101961,-0.057040,-0.557535,0.056757,0.315212,-0.060765,-0.187816,0.416695,-0.502637,0.095486,-0.401033,0.121339,0.096778,-0.555355,-0.097253,-0.582672,-0.030848,-0.506252,-0.336792,0.010045,0.177873,-0.293485,0.618587,-0.961809,0.250191,0.403451,0.418296,-0.464491,0.649220,0.350348,0.068640,-0.526979,-0.204019,0.332088,0.115229,0.001288,-0.008092,0.330894,0.047912,-0.033962,-0.429883,0.472153', '3111650', '1296534', '1292211', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5967821', '白雪公主之魔镜魔镜', '剧情', '影片讲述了由朱莉娅·罗伯茨主演的邪恶的皇后窃取了国家的政权，而被流放的公主在七个足智多谋的小矮人的帮助下，重新赢回了属于她的权力。很久以前，有位相貌出众的公主名叫白雪（莉莉·科林斯 饰），白雪有位邪恶又毒舌的继母皇后（朱莉娅·罗伯茨 饰）。皇后不仅嫉妒白雪公主的美貌， 还成天痴迷着帅气的白马王子，并意图榨干他的财富与精力，却怎么也没想到白马王子竟然对白雪公主一见钟情；坏心的皇后见状立刻将白雪公主放逐到危机伺伏的幽暗森林，而白马王子也因中了坏皇后下的爱情魔药而沦为她的爱情俘虏。被驱逐到森林里的白雪公主不幸遇上了一帮矮人盗匪，在盗匪们的训练下，她成了七矮人山贼团的领袖！彻底改头换面的白雪公主，在偶然的机会下意外与白马王子重逢，但不甘心被坏皇后欺压的她，决定率领小矮人们一同进攻邪恶皇后的堡垒，誓言夺权复仇！而白雪公主和坏皇后两人，究竟谁最后能永远过着幸福快乐的日子呢？', '朱莉娅·罗伯茨', '塔西姆·辛', 6.2, 65634, 'tt1667353', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1475551013.jpg', 3.2, 17.9, 52.2, 20.1, 6.6, '0.262984,0.316492,-0.590887,0.825239,-0.256933,-0.245409,0.805594,0.029841,-0.424312,0.049313,0.484079,0.576008,-0.187635,0.212506,0.134108,0.193249,-0.307982,-0.520065,-0.209122,-0.133202,-0.303933,-0.227457,-0.277653,-0.196030,0.078141,-0.447832,0.511795,0.005095,-0.012017,0.200390,0.497961,0.037253,0.014453,0.442320,-0.165996,0.290535,0.063083,-0.073780,0.043415,0.116572,-0.077940,-0.488108,-0.224403,0.238737,-0.221598,0.178095,0.591455,-0.565784,0.172443,-0.314615,0.264389,-0.328676,0.122546,0.380261,0.318843,-0.275675,0.091104,0.152004,0.056416,-0.034030,0.219521,-0.052089,-0.768115,0.149615,0.042039,0.093607,-0.565526,0.566988,0.089128,0.085523,0.221951,-0.228038,-0.023485,0.012314,0.241214,0.362682,-0.277340,0.030817,-0.739102,0.349146,0.512803,-0.008785,-0.373471,0.182799,-0.137501,-0.505065,-0.004411,-0.307308,-0.594618,-0.134415,0.632763,-0.233657,-0.122133,0.533310,-0.674582,-0.115127,-0.251375,0.122564,-0.011681,-0.514810,-0.063763,-0.203588,-0.210140,-0.376875,-0.288931,0.104657,0.362512,-0.142769,0.778638,-0.739746,0.324862,0.730498,0.126710,-0.829886,0.400217,0.133011,0.091094,-0.008780,-0.315887,0.384898,-0.025045,0.240865,0.209945,0.329337,-0.297463,-0.205331,-0.490786,0.432787', '3670447', '3785918', '3769423', '1867335');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5967829', '永远的三丁目的夕阳之1964', '剧情', '1964年，战后的日本正处于经济高度增长期，东京奥运会召开在即，举国上下沉浸在沸腾的热情之中。我们所熟悉的夕日町三丁目，人们的生活也悄悄发生着改变。茶川龙之介（吉冈秀隆 饰）终于和温柔的广美（小雪 饰）结婚，养子淳之介（须贺健太 饰）已步入高中，正朝着东大努力，夫妻二人也即将迎来新的生命。可是龙之介一方面要面对新晋小说家的挑战，一方面又要重视和病危的父亲的关系。隔壁的铃木车行业扩大规模，并应入了新学徒。已成长为经验丰富老师傅的星野六子（堀北真希 饰）喜欢上凡天堂医院的菊池医生（森山未来 饰），但是一些不良传闻让小六苦恼不堪。随着奥运会的召开，美丽的三丁目迎来美好的一天……©豆瓣', '吉冈秀隆', '山崎贵', 8.3, 12897, 'tt1823067', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2517414830.jpg', 0.3, 1.2, 18.3, 45.3, 34.8, '0.083529,0.143422,-0.439069,0.365948,0.319536,-0.338342,0.505646,0.364998,-0.380377,-0.413435,0.220390,0.385417,-0.135163,0.417227,0.473081,0.056771,-0.237581,-0.682934,-0.078203,0.017950,-0.026549,-0.330114,-0.123956,-0.065867,-0.107891,-0.167214,0.802473,0.258804,-0.093091,0.504566,0.194953,0.274838,-0.130785,0.186878,-0.008052,-0.242006,0.126588,0.251328,-0.497880,0.065824,-0.142679,-0.199219,-0.092897,-0.002176,0.290162,0.147033,0.504017,-0.145939,-0.376300,-0.146760,0.511212,-0.081390,-0.258166,0.263273,0.500760,0.237813,0.157922,0.268692,-0.181571,0.113585,-0.259888,-0.285434,-0.585719,0.239717,0.172557,0.113921,-0.424925,0.498354,0.111688,-0.133916,0.307896,-0.211371,0.023393,0.559487,0.158856,0.503206,-0.305548,0.248687,-0.121022,0.011253,0.730731,0.029881,-0.086964,0.258370,-0.137357,-0.349834,-0.064840,-0.225434,-0.453527,-0.013403,-0.073040,0.121359,0.000501,0.282953,-0.433476,0.078978,-0.225729,-0.373559,0.346962,-0.054593,-0.009738,-0.648380,0.012650,-0.567549,-0.310979,0.023235,0.253291,-0.310071,0.864208,-0.880505,0.095581,0.373165,0.270803,-0.321233,0.426616,0.092288,0.061904,-0.332965,-0.307022,0.263491,-0.264803,0.398017,-0.241924,0.190179,-0.188969,-0.235777,-0.296014,0.356554', '1826173', '25922902', '1316589', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5968334', '丈夫得了抑郁症', '剧情', '婚后五年，在某网络公司上班的髙野干夫（堺雅人 饰）和毫不卖座的漫画家妻子小晴（宮﨑あおい 饰）过着平静的生活。干夫为人纤细，一丝不苟，习惯每天早上做便当，按照不同日期搭配便当的奶酪和领带。但是在巨大的工作压力下，干夫看似平静的内心渐渐失衡，他甚至一度企图自杀，经问诊才发现自己已经患了抑郁症。一向专注工作、神经大条的小晴回想，似乎早在几个月前干夫的身上便已出现了些许迹象。为了让丈夫尽快恢复健康，小晴以离婚相要挟迫使干夫辞职休养。失去了生活来源，髙野夫妇的生活陷入了前所未有的困境，但他们也在相互扶持的道路上获得了久违的快乐……本片为細川貂々根据和丈夫望月昭真实经历撰写的同名原作改编，望月昭本人亦在片中客串角色。©豆瓣', '宫崎葵', '佐佐部清', 8.1, 71074, 'tt1810833', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1156829401.jpg', 0.2, 1.2, 19.2, 49.6, 29.9, '0.032770,-0.015537,-0.567176,0.469879,0.058382,-0.276673,0.520659,0.410996,-0.479682,-0.286543,0.150382,0.537244,-0.167301,0.260342,0.405057,-0.139176,-0.371157,-0.858411,-0.155083,0.098913,-0.167626,-0.375958,-0.175618,-0.055264,-0.275631,-0.475401,0.734213,0.004209,0.081132,0.430131,0.034886,0.175117,-0.065223,0.393565,-0.079266,0.003207,-0.111359,0.040931,-0.337494,0.071355,0.285129,-0.334148,-0.044020,0.331711,0.113825,0.515148,0.776684,-0.130300,-0.643103,0.024776,0.565394,0.131136,-0.147417,0.135409,0.333110,0.327495,0.206135,0.327485,-0.470952,0.165736,-0.120619,-0.140717,-0.739468,-0.042468,0.199880,0.153363,-0.452749,0.621975,-0.058097,-0.066268,0.008288,-0.307739,0.143247,0.587531,0.141236,0.507520,-0.310639,0.220998,-0.177032,0.289501,0.491638,0.198496,-0.328016,0.498210,-0.333681,-0.220471,-0.176797,-0.267698,-0.335691,-0.099486,-0.065799,0.185187,-0.354958,0.272887,-0.441036,0.084747,-0.086638,-0.225870,0.054458,-0.202767,-0.024880,-0.561027,-0.177858,-0.404366,-0.223226,-0.026301,0.159337,-0.487787,0.468957,-0.897910,0.272611,0.261255,0.203343,-0.431903,0.467478,0.021086,0.065281,-0.203798,-0.007951,0.228345,-0.169001,0.172145,0.327583,0.191612,-0.075390,0.191638,-0.424241,0.488068', '4202326', '30345227', '26809007', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5968834', '摩天楼', '剧情', '2012年的圣诞前夜，韩国首尔市中心的120层摩天大楼Tower Sky内，中国餐厅女强人经理允熙（孙艺珍 饰）、性格内敛的大楼物业队长兼单身爸爸李泰浩（金相庆 饰）、张扬跋扈傲慢无礼的贵妇人、位居人上的会长、丢三落四的马虎小厨师……不同职业和身份的人按照各自的轨道行进，他们或彼此交错，或毫无干系，殊不知一场灾难即将降临他们的头上。夜幕降临，正当人们沉浸在人工降雪所营造的浪漫、幸福氛围时，意外突然发生。造雪专用的直升机受强气流影响失控撞上大厦，随即引发混乱和难以遏制的大火。刚刚还如天国般美好，奢侈华美的大厦瞬间变成残酷的人间炼狱……©豆瓣', '薛景求', '金志勋', 7.5, 52323, 'tt2554270', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1803259035.jpg', 0.5, 2.7, 32.7, 47.7, 16.4, '0.429793,0.336594,-0.693813,0.189757,0.161591,0.081106,0.872219,0.486599,-0.474915,-0.076178,0.445415,0.438000,-0.462836,0.169966,0.482956,-0.000256,-0.469338,-0.633050,-0.345560,0.103768,-0.072831,-0.131550,-0.159564,0.025653,0.150129,-0.055037,0.512001,0.241804,-0.154329,0.450663,0.183335,0.160481,-0.289884,0.419697,-0.136775,-0.344468,0.007902,0.285392,-0.354860,-0.250575,-0.406151,-0.232982,0.052504,-0.060776,0.033767,0.173921,0.695394,-0.240327,-0.276344,-0.242424,0.614075,0.059929,0.001969,0.114233,0.320976,0.009445,0.183789,0.037515,-0.064403,0.015419,0.060452,-0.189327,-0.506405,0.072582,0.156211,-0.028126,-0.106600,0.499308,0.221078,-0.188061,0.275581,-0.031922,0.149838,0.082161,0.355640,0.502515,-0.170258,-0.083971,-0.310201,0.238736,0.842064,0.176846,-0.745528,0.156657,-0.480351,-0.197197,-0.087905,-0.331172,-0.461036,-0.104408,0.111184,0.144203,0.151983,0.435271,-0.573053,0.109626,-0.063719,-0.201151,-0.234780,-0.261156,-0.402581,-0.806690,-0.112187,-0.536615,-0.010495,0.062001,0.011993,0.250733,0.262029,-0.770104,0.397277,0.244696,0.323168,-0.083764,0.567449,-0.241344,-0.041175,-0.141554,-0.232333,0.145087,-0.209435,0.428824,-0.295921,0.380395,-0.337071,0.016180,-0.019651,0.357004', '10466639', '26687241', '2269893', '27102569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5972040', '单车少年', '剧情', '11岁男孩西里尔（托马斯•多雷 Thomas Doret 饰）被送到了儿童福利院，他的父亲盖伊（杰瑞米•雷乃 Jérémie Renier 饰）不辞而别。西里尔迫切地希望与父亲见面，于是千方百计逃脱学监的看管，并引发了争执。他来到了父亲之前租住的房屋吃了闭门羹，还遭到了邻居的驱逐。他被学监带回了福利院，却开始寻找当时父亲买给他的单车。后来，好心的理发师萨曼莎（西西•迪•法兰丝 Cécile De France 饰）帮助西里尔买回了那辆已经被盖伊出售的单车。他骑着单车，继续寻找父亲。萨曼莎动了恻隐之心，帮她联系了盖伊。父子终于再度重逢，原来西里尔的母亲离家出走之后，盖伊深感无力扶养西里尔，为了在自己的料理店开始新生活，他希望萨曼莎帮人帮到底，照顾西里尔。然而，西里尔感受到被盖伊遗弃的痛苦，拼命地保护着单车，甚至为此结识了一群未成年毒贩，游走在犯罪的边缘……', '塞西尔·德·弗朗斯', '让-皮埃尔·达内', 8.2, 22501, 'tt1827512', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1357365330.jpg', 0.4, 1.2, 16.5, 52.7, 29.2, '0.275475,0.079384,-0.688055,0.427625,-0.165660,-0.693196,0.451825,0.362319,-0.371014,-0.255115,0.114538,0.683137,0.020944,0.467659,0.242967,0.217474,-0.368869,-0.591383,0.185708,0.116014,-0.444316,-0.325708,-0.002852,-0.299515,-0.078418,-0.149906,0.219288,0.114187,-0.051714,0.405656,0.098684,0.208610,0.065084,0.427072,-0.446191,0.304090,0.130412,-0.145174,-0.108286,0.260519,0.123287,-0.286834,-0.026449,0.121093,0.203896,0.472517,0.754248,-0.125214,0.101493,-0.019392,0.085736,-0.074103,0.286490,0.212347,0.008223,0.165569,0.015117,0.122026,-0.325718,-0.003153,0.306792,-0.100144,-0.396796,0.126721,-0.254403,-0.101737,-0.824786,0.412500,-0.184193,0.187687,0.280357,-0.253585,0.246663,0.466741,-0.129201,0.328186,-0.122156,0.099255,-0.428501,-0.017141,0.636478,-0.266202,0.268300,0.244774,-0.212053,-0.088569,0.247250,-0.153040,-0.400925,-0.043651,0.547774,0.028871,-0.311171,0.184744,-0.549186,-0.332457,-0.479078,-0.127406,0.087059,-0.303919,-0.057829,-0.444075,0.029905,-0.107624,-0.100516,-0.083333,-0.101877,-0.178618,0.392731,-0.631107,0.408074,0.694106,0.496090,-0.472012,0.392042,-0.088228,0.114784,-0.103235,-0.045213,0.403230,0.214835,0.499017,0.396842,0.125153,0.078834,0.012439,-0.363741,0.365726', '1299965', '1309069', '2063528', '25837175');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5973984', '野蛮人', '剧情', '影片改编自同名畅销小说，故事讲述了在洛杉矶的拉古纳海滩，两个最要好的毒贩子Chon和Ben拒绝了墨西哥大毒枭为其卖命的要求，后者便绑架了二人的“红颜知己”Ophelia并索要一大笔赎金，为了救出女伴，他们偷偷盗取大毒枭自己的货物以换取赎金；真不啻是一场危险的角逐。', '亚伦·泰勒-约翰逊', '奥利佛·斯通', 6.1, 6643, 'tt1615065', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1765989373.jpg', 4.3, 19.2, 50.3, 20.5, 5.7, '0.083315,-0.131036,-0.551411,0.598177,-0.095250,-0.338999,0.663673,-0.016304,-0.189042,0.063394,0.250248,1.037162,-0.014271,-0.172567,0.325961,0.303785,-0.144395,-0.623821,-0.299341,-0.214782,-0.197380,-0.670739,-0.376005,-0.310587,-0.076553,-0.095565,0.274483,-0.103627,-0.328282,0.441221,0.545293,0.109279,-0.112057,0.301584,-0.230851,0.107703,-0.053923,0.242404,-0.469880,0.436915,-0.221136,-0.237251,-0.253192,0.085662,0.225958,0.567076,0.484434,-0.237297,-0.046679,-0.154918,0.343054,-0.454830,0.142927,-0.192140,-0.043588,-0.095713,0.509503,0.341709,-0.463177,-0.044650,0.256623,-0.219107,-1.100440,0.036754,0.054009,-0.167895,-0.618933,0.393189,-0.012922,0.194250,0.182669,0.002846,0.104708,0.429795,0.157399,0.238095,-0.126190,-0.148220,-0.540117,0.575481,0.581654,-0.073580,0.214768,0.146380,0.035604,-0.439535,0.196252,-0.096425,-0.302520,0.023424,0.819577,-0.309224,0.086829,0.225078,-0.740045,-0.284827,-0.476105,-0.202475,0.301045,-0.428969,0.157046,-0.549288,-0.170294,0.043285,-0.138692,0.217003,0.540071,-0.320753,0.802338,-0.469986,-0.242065,1.047962,0.428263,-0.862047,0.352968,0.273619,0.163603,-0.062893,-0.192015,-0.105254,0.199901,0.308436,0.362905,-0.030223,0.101004,-0.165577,-0.274577,0.144130', '26678784', '3785918', '4820775', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5975197', '无价之宝', '喜剧', '漂亮妈妈江蕙妮（张柏芝 饰）是一名事业心很强的广告导演，常常疏于照顾家庭和孩子（Lucas 饰），这次更是执意要跟武打巨星大龙（郑中基 饰）前往广西的一座孤岛上拍摄广告大片。虽然岛上风光绮丽，景色怡人，然而蕙妮却发现剧组对拍摄广告似乎并不上心，拍摄过程也碰到种种意外，甚至在夜店还遭遇来历不明的人突袭，种种可疑迹象让蕙妮开始不安，原来他们拍广告只是一个幌子，众人登岛其实另有目的，而这一切皆源起于岛上的宝藏传说。与此同时，以眼镜蛇（刘烨 饰）为首的秘密团伙也已在藏宝图的引导下开始挖掘行动，一场针锋相对的寻宝较量即将爆发，无意被卷入其中的蕙妮又将如何应对这始料未及的险境呢？©豆瓣', '张柏芝', '姜国民', 3.7, 11491, 'tt1993433', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1168543852.jpg', 43.5, 34.7, 17.9, 2.5, 1.4, '0.073154,0.047387,-0.725704,0.460853,0.280679,0.008606,0.553433,0.189627,-0.429346,-0.263714,0.206623,0.236156,-0.469339,-0.317147,0.079827,0.041717,-0.500192,-0.546332,-0.079996,-0.056369,-0.105042,-0.100150,-0.404738,-0.099778,0.077897,-0.182792,0.617826,0.318280,-0.479220,0.294055,0.311162,0.356124,-0.488563,0.397744,0.070019,-0.172369,0.008958,0.224516,-0.267800,-0.057814,-0.182045,-0.367787,-0.415138,0.286745,0.104948,0.456203,0.708703,-0.117600,-0.369835,-0.046407,0.368646,-0.242819,0.094462,-0.113335,0.309628,-0.047531,0.494951,0.042215,0.016661,0.007523,0.170557,-0.291612,-0.734009,0.166884,0.282567,0.108162,-0.367480,0.181821,-0.005041,-0.098132,-0.082959,-0.078951,0.251440,0.556547,0.195504,0.015019,-0.011663,0.039410,-0.286887,0.197158,0.644614,0.096425,0.033731,0.396718,0.012331,-0.299553,-0.067532,0.045632,-0.216796,0.295706,0.129922,-0.029717,-0.104606,0.010509,-0.537287,0.208685,-0.348280,-0.125512,-0.299755,-0.402565,-0.070253,-0.850251,-0.155552,-0.226491,-0.487380,-0.084968,0.236992,-0.063578,0.501716,-0.712842,0.142739,0.515486,0.142377,-0.472601,0.405623,0.056532,-0.011412,-0.529971,-0.386869,-0.076360,-0.093300,-0.000250,-0.077668,0.243812,0.051000,-0.314801,-0.404897,0.291603', '2369613', '20274039', '6007281', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5975206', '记我的母亲', '剧情', '20世纪50年代末，已成为畅销作家的伊上洪作（役所广司 饰）百忙之中回到汤岛老家探望年迈的双亲。远在东京的家中，妻子美津（赤间麻里子 饰）、长女郁子（ミムラ 饰）和次女纪子（菊池亚希子 饰）正马不停蹄地帮他做着辅助工作，正值叛逆期的小女儿琴子（宫崎葵 饰）则有意无意反抗着父亲的强权。回到东京不久，老父亲隼人（三国连太郎 饰）的噩耗传来，留给洪作的是无法参透的万千情感。岁月流转，伊上一家时聚时散，女孩们渐渐长大，有着彼此的生活与心事，一向强势的洪作也渐渐尝到初老的孤独况味。与此同时，母亲八重（树木希林 饰）随着年岁的增长，记忆力逐渐衰退。一方面履行着身为人子的义务，一方面又因童年被母亲“抛弃”而心存芥蒂。万千情感之下，是永生无割舍的羁绊……本片根据日本作家井上靖创作的自传体小说《我的母亲（わが母の記）》（分“花下”、“月光”、“雪面”三部）改编。©豆瓣', '役所广司', '原田真人', 8.7, 14803, 'tt1818443', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1395004031.jpg', 0.2, 0.7, 9.5, 43.1, 46.5, '-0.013273,0.137521,-0.493944,0.605097,0.044378,-0.335405,0.411348,0.403224,-0.436726,-0.569103,0.198525,0.566462,0.195242,0.383115,0.242051,-0.195821,-0.145672,-0.538974,0.079474,0.046503,0.034279,-0.398745,-0.260357,0.059410,-0.301990,-0.271658,0.927170,0.150166,0.067260,0.321280,0.099417,0.405470,-0.291569,0.166034,-0.062151,0.165413,-0.183078,0.080046,-0.238988,0.053855,-0.187244,-0.325619,-0.132381,-0.112650,-0.045364,0.291393,0.794399,-0.066575,-0.025004,-0.265094,0.626411,0.008350,-0.102183,0.132761,0.338405,0.204330,0.229105,0.317793,-0.298143,0.006455,-0.038128,-0.126336,-0.342952,-0.260641,0.489726,0.226019,-0.527209,0.395379,-0.113088,-0.401645,0.188303,-0.334835,-0.058891,0.204232,0.046963,0.688072,-0.241048,0.176502,-0.050488,0.392048,0.480745,0.070838,-0.239637,0.278264,-0.254566,-0.171217,0.017724,-0.423821,-0.636348,-0.203591,0.060828,0.294470,0.025081,0.298053,-0.370248,-0.032506,-0.046939,-0.217795,0.229673,-0.253911,0.142283,-0.483758,-0.114254,-0.684733,-0.298093,0.020931,0.347762,-0.242707,0.814099,-0.603521,0.329593,0.366273,0.095092,-0.247696,0.434295,0.004316,0.030956,-0.165002,0.022657,0.636190,-0.190175,0.071221,0.057199,0.005710,-0.334853,0.106861,-0.429206,0.222859', '3811356', '3667102', '25880986', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5977478', '恋恋书中人', '喜剧', '凯文（保罗·达诺 Paul Dano 饰）是一名天才小说家，曾经凭借处女作跻身全国著名作家，可是到了第二部作品时却遇到了瓶颈。与此同时，他的生活也显得不尽如人意，自从初恋女友离开他以后，凯文一直孤身一人，甚至称自己是“不适合约会的类型”。于是，凯文开始在梦里虚构了一个自 己的理想型露比（佐伊·卡赞 Zoe Kazan 饰），并把梦中的露比记录下来预备做自己新书的题材。就这样，凯文过了几个晚上做梦白天写作的日子。直到有一天，凯文醒来发现梦中的露比竟然真真实实的出现在了他的生活里，更令人难以置信的是凯文竟然可以通过书写虚构的露比来改变现实生活中的露比……影片《恋恋书中人》由保罗·达诺与佐伊·卡赞这对现实中的情侣携手主演。©豆瓣', '保罗·达诺', '乔纳森·戴顿', 7.5, 39422, 'tt1839492', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1737906506.jpg', 0.4, 3.2, 32.7, 47.1, 16.6, '0.314213,-0.194386,-0.532916,0.579618,0.076060,-0.303459,0.759021,-0.045854,-0.370949,-0.338953,0.123436,0.787645,-0.440334,0.376812,0.251233,-0.118586,-0.418933,-0.678808,0.127562,-0.307667,-0.202806,-0.293374,-0.391424,0.048305,-0.248272,-0.263568,0.755663,0.078545,-0.410561,0.262610,0.116471,0.032377,0.105095,0.527959,-0.135997,0.032661,-0.026946,0.203862,-0.198563,0.243781,0.072741,-0.262298,-0.263534,0.178749,0.054891,0.332425,0.319074,-0.444138,-0.358521,0.187322,0.669722,-0.008736,-0.271940,0.018972,-0.014376,-0.108792,0.207274,0.213433,-0.078208,0.239320,-0.113417,-0.203970,-0.875698,0.032574,0.280462,0.268345,-0.605085,0.239389,-0.083467,-0.134699,0.284797,-0.272194,0.255137,0.272433,0.241501,0.330168,0.068773,-0.046185,-0.629944,0.497626,0.445243,0.019633,-0.438074,0.749100,-0.027289,-0.319230,-0.226358,-0.071702,-0.556493,0.272675,-0.142246,-0.019471,-0.199128,0.266997,-0.448539,0.072913,-0.127963,-0.235313,-0.182468,-0.162453,-0.298640,-0.519034,-0.118697,-0.539431,-0.380209,0.029872,-0.068055,-0.626698,0.609074,-1.002216,0.173282,0.432537,0.235482,-0.115173,0.807203,0.154788,-0.018184,-0.050869,-0.062803,0.297604,-0.147040,0.086417,0.133458,0.488667,0.055312,-0.225000,-0.535027,0.807056', '1783461', '1793491', '20472738', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5977789', '音为爱', '喜剧', '童年时候的小贝（哲拉予•拉翁马尼 Jirayu La-ongmanee 饰）在一次音乐课上对唱摇滚乐的小恩（娜塔莎•劳佳姆 Nattasha Nualjam 饰）产生奇妙的心动。小恩的家里是开唱片店的，而小恩的梦想是当一名歌手。为了更接近小恩的生活，对小恩朦胧的好感推动小贝这个从未接触过流行音乐的男孩开始学着听歌。然而不久后小恩随父母搬家离开了清迈，小贝从此和心仪的女孩失去了联系。直到几年后，曾经的小伙伴们都步入了高三，当年新奇的摇滚乐成了流行的中心，小恩的意外回归让小贝雀跃不已。此时的小贝一心想向音乐发烧友小恩证明自己的能力，恰巧这个时候小贝的好朋友小空（帕查拉•奇拉锡瓦特 Pachara Chirathivat 饰）追求风尚，吸引女孩的注意，准备组建一支乐队，就这样，小空小贝艾克这三个毫无音乐功底的热血男孩开始了坎坷而令人成长的乐团之路。©豆瓣', '吉拉育·拉翁马尼', '查亚诺普·布恩帕拉科布', 7.3, 23734, 'tt1869682', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2459342514.jpg', 0.8, 4.4, 37.9, 40.4, 16.5, '0.550572,0.009774,-0.771790,0.527249,-0.211954,-0.488492,0.692569,0.126923,-0.508706,-0.122214,0.111579,0.570239,-0.228694,0.444933,0.341765,0.242974,-0.175401,-0.826308,0.121221,-0.100837,-0.082136,-0.278121,-0.236775,0.127570,-0.267965,-0.337037,0.448943,-0.207653,-0.113010,0.799255,0.312261,-0.122224,0.141972,0.287368,-0.108409,0.151585,0.270710,0.026926,-0.214342,0.038476,0.067896,-0.079646,-0.049036,0.065102,-0.134705,0.256688,0.755498,-0.187597,-0.093240,-0.100730,0.485621,-0.013900,-0.131261,0.038552,0.100752,0.256876,0.202400,-0.182319,-0.126307,0.149422,-0.106646,0.009582,-0.464728,0.255940,0.108612,-0.022994,-0.558466,0.230644,0.089010,-0.186060,0.318868,-0.369632,0.205312,0.315684,0.179059,0.515528,-0.276697,0.312707,-0.291836,0.219132,0.812191,-0.072764,-0.357411,0.531128,-0.087441,-0.363991,-0.126893,0.078781,-0.637004,0.114037,0.301155,0.140544,-0.070356,0.069109,-0.824629,0.118610,-0.044193,-0.182592,0.095512,-0.189693,-0.195041,-0.562960,-0.122208,-0.340862,-0.181875,-0.097350,-0.062394,-0.386634,1.105512,-0.958617,0.193853,0.451218,0.243367,-0.369234,0.617918,-0.023418,0.019238,-0.140209,-0.068510,0.287129,-0.396977,0.218208,-0.066270,0.515865,0.059650,-0.266739,-0.479693,0.697788', '3811356', 