INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5977835', '桃姐', '剧情', '桃姐（叶德娴 饰）是侍候了李家数十年的老佣人，把第二代的少爷罗杰（刘德华 饰）抚养成人。罗杰从事电影制片人，五十多岁了仍然独身，而桃姐也继续照顾罗杰，成为习惯……一日，桃姐如常到街市买菜，回寓所煲汤、做好满桌的饭菜，在等待从内地出差回家的罗杰，桃姐看着窗外的街景打发时间 ，不知不觉间却竟昏迷在地上……桃姐醒来时发现自己身在医院，桃姐是中风了！一边手臂不能活动自如，必须利用物理治疗尽量恢复活动能力。罗杰在百忙工作中为桃姐找合适老人院，期间巧遇昔日电影拍摄认识的草蜢哥（黄秋生 饰），桃姐出院来到老人院，环境陌生，院友怪异，桃姐强装镇定。罗杰工余常到老人院探桃姐，主仆闲话家常一如母子，仍保持互相揶揄调侃习惯，桃姐嘴硬心甜，院友羡慕。罗杰特意带桃姐参加电影首映礼，桃姐首次刻意打扮准备，取收藏已久的名贵衣服出发赴会；首映礼上桃姐大开眼界，更终有机会见到电影明星，桃姐感叹自己有生之年已然无憾……', '叶德娴', '许鞍华', 8.3, 299537, 'tt2008006', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1455206048.jpg', 0.3, 0.9, 14.2, 50.6, 34.1, '-0.081961,-0.026655,-0.355392,-0.113665,0.007724,-0.287125,0.255090,0.298450,-0.407801,-0.617529,0.242018,0.458015,-0.179094,0.477309,0.148204,-0.263582,-0.515493,-0.284088,-0.085325,0.210173,0.012211,0.007748,-0.231371,-0.041243,-0.103596,-0.397374,0.013188,-0.078914,0.017271,0.671326,0.049426,-0.253334,-0.263085,0.360219,-0.308156,-0.109188,0.022355,0.012656,-0.510683,0.258148,0.114562,-0.168341,-0.363461,-0.201768,0.392341,0.174144,0.626133,0.421934,-0.287378,0.162012,0.320629,0.063659,-0.096497,0.113608,0.042735,0.144034,0.090900,-0.079635,-0.169988,0.237637,-0.113293,-0.244505,-0.217546,0.350729,-0.003774,0.157080,-0.594377,0.461638,-0.134741,0.080016,0.001621,-0.472111,0.233287,0.168005,0.119556,0.452996,0.111172,0.224449,-0.290506,0.377520,0.326647,0.105554,0.078350,0.504101,0.018558,-0.096867,0.353822,-0.054293,-0.276003,-0.049031,-0.100131,-0.080061,-0.082437,-0.062201,-0.116617,-0.118363,-0.095916,-0.208008,0.156520,-0.269834,0.051745,-0.975683,0.072398,-0.158037,-0.014016,0.108646,-0.014068,-0.235418,0.314480,-0.385918,0.341290,0.126532,0.125151,-0.326993,0.596999,-0.037749,0.090082,-0.359757,0.038501,0.277572,-0.088752,0.079819,0.236137,0.241823,-0.263130,0.031136,-0.629258,-0.043662', '34961898', '30253080', '2075345', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5977836', '逆战', '剧情', '国际安全局的王尚恩（安志杰 饰）率万飞（周杰伦 饰）等部下远赴约旦，押送制造天花病毒变体的科学家肯纳，岂料王尚恩叛变将肯纳劫走，万飞头部受重伤，他同队中的心上人也在这次任务中身亡。三个月后，王尚恩等人研制的病毒造成一艘货船上的人们尽数死亡，而他此时准备贩卖疫苗谋取暴利；万飞在医院中被告知头部的子弹无法取出，神经受损导致他两周后会有生命危险，万母向其透露他有一个失散多年的哥哥。为了完成母亲心愿，万飞前往吉隆坡寻找哥哥万阳（谢霆锋 饰）。飞机上与万飞同行的简博士恰巧是王尚恩一伙准备用来替换肯纳的病毒专家，简博士被王尚恩派出的万阳劫持，万飞出手相救。因为分属不同阵营，兄弟只得拳脚相见……©豆瓣', '周杰伦', '林超贤', 6.4, 81136, 'tt2063011', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1374419043.jpg', 2.7, 13.2, 52.1, 23.9, 8.1, '0.201873,-0.027482,-0.527287,0.267007,-0.103463,-0.188105,0.578257,-0.079148,-0.488608,-0.234212,0.229025,0.647860,-0.056251,-0.005979,0.175391,-0.022222,-0.204039,-0.436332,-0.051544,-0.131939,-0.512499,-0.393559,-0.165557,-0.202922,-0.060803,-0.253828,0.410901,-0.054624,-0.088737,0.580268,0.087706,0.481131,-0.217126,0.367439,0.107340,0.031329,0.022162,-0.259826,-0.123351,0.472863,0.136747,-0.337813,0.396744,0.046658,0.000731,0.437822,0.822980,-0.120634,0.189237,-0.514783,0.230577,-0.376295,0.291277,0.019549,0.291237,0.347332,0.119517,-0.005015,-0.268388,-0.144204,0.203229,0.050995,-0.662716,-0.158358,0.182146,0.009212,-0.418360,0.279316,-0.320765,0.131240,-0.072142,-0.330022,0.386973,0.461861,0.222807,0.031939,-0.282253,-0.093472,-0.502545,0.180704,0.595044,-0.456067,0.075483,-0.146986,0.018315,-0.429896,0.166173,-0.233741,-0.097423,0.038942,0.567070,0.147746,-0.123270,0.050504,-0.256193,-0.007201,-0.463052,-0.085073,-0.210670,-0.028118,0.188474,-0.808940,0.132729,-0.099635,-0.148025,0.124871,0.388175,-0.009861,0.526419,-0.427671,0.162399,0.431110,0.458754,-0.450344,0.309568,0.013844,0.273706,-0.220573,-0.078159,0.064243,0.244234,0.359445,0.237286,0.105744,0.025256,-0.027774,-0.365579,-0.147629', '2369613', '3147969', '1307897', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5977838', '高海拔之恋Ⅱ', '爱情', '位于香格里拉深山的自然景区，阿秀（郑秀文 饰）和大妹、小妹经营着林海旅馆。她的丈夫小田（李光洁 饰）七年前误入林海，生死不明，但阿秀始终没有放弃寻找的希望。某天旅馆来了一名不速之客，他就是当今红遍影坛、歌坛的天王巨星Michael刘伯谦（古天乐 饰）。刘不久前与女影星丁圆圆（高圆圆 饰）订婚，但在即将走入婚姻殿堂的一刻却被矿工张行（王宝强 饰）抢婚成功。刘自暴自弃，终日酗酒，为了躲避狗仔队来到云南，却醉酒时阴差阳错登上了阿秀的卡车。刘借此机会在这个僻静的所在静养，他偶然得知阿秀竟是自己的资深歌迷，而他甚至促成了阿秀和小田的姻缘。在这段时间的相处中，刘渐渐喜欢上了善良的阿秀，但阿秀心中始终有着一条难以逾越的鸿沟……©豆瓣', '古天乐', '杜琪峰', 5.9, 19508, 'tt1941536', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1308162454.jpg', 6.3, 23.1, 47.8, 17.4, 5.5, '0.285472,0.222525,-0.750609,0.591558,0.190251,-0.567913,0.916278,0.170924,-0.565380,-0.383683,0.139407,0.444623,-0.313673,0.452358,0.041005,-0.064679,-0.036993,-0.380071,-0.179710,-0.057564,-0.276794,-0.203154,-0.260208,-0.092172,-0.336232,0.325286,0.685321,0.333937,-0.296902,0.340784,0.453833,0.040142,-0.046803,0.530038,-0.340681,0.269492,0.108637,0.234940,-0.214049,-0.017190,0.166818,-0.555871,-0.081337,0.082764,0.076874,0.498087,0.442502,-0.209446,-0.074154,0.177517,0.373211,-0.208782,0.034983,0.127574,0.272747,-0.198916,0.094037,-0.253589,-0.220076,-0.130922,0.069551,-0.200230,-0.305289,0.112846,0.102076,0.064952,-0.582925,0.276106,-0.046516,-0.093954,0.047332,-0.501461,0.322668,0.356058,0.213528,0.138104,-0.232967,0.190905,-0.562314,0.367143,0.669860,0.347983,-0.075981,0.212490,-0.339015,-0.679805,-0.034671,-0.009391,-0.562676,-0.121203,0.594129,-0.146008,0.000644,0.011980,-0.324541,-0.193704,-0.070890,0.117478,-0.004711,-0.222147,-0.099600,-0.463367,-0.121389,-0.567189,-0.293802,0.093897,-0.055350,-0.361631,0.522155,-0.860758,0.242986,0.282997,0.071477,-0.474203,1.000216,-0.001345,0.295781,-0.162503,0.068155,0.571158,-0.041158,0.356897,0.195012,0.463241,-0.295858,0.048897,-0.297329,0.419939', '1302384', '3055049', '3033092', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5985887', '舞蹈皇后', '剧情', '普通律师成为了首都市长？家庭主妇成为了火热歌手？这不是耸人听闻的小报八卦，而是切实发生在韩国一个家庭的事。曾经号称“麦当娜”的正花（严正花 饰）如今嫁为了人妇，但体内那颗渴望舞动的心仍然未曾停止过。恰逢这时有了一个能当歌手出道的机会，正花想要把握住，实现曾被自己搁置过的梦想。可不凑巧的是，身为律师的丈夫政民（黄政民 饰）却告诉正花，他要参加首尔的市长选举了。这让兴致冲冲的正花如同被浇了一盆冷水，一边是要维护丈夫的形象，一边是自己的梦想，到底该如何取舍。梦想、奋斗与年龄无关，让我们看看这对夫妻如何改变自己。本片上映后获得多项大奖，且男女主角均以真名演出。©豆瓣', '黄政民', '梨晳勳', 7.5, 8384, 'tt2181885', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2166639533.jpg', 0.7, 2.5, 34.7, 44.9, 17.2, '0.042620,0.200905,-0.442140,0.398480,-0.094241,-0.359461,0.519433,0.117731,-0.364107,-0.160292,0.068370,0.601181,-0.297672,0.126667,0.184928,0.066593,0.001956,-0.847059,0.015745,-0.115600,0.038528,-0.314481,-0.260452,0.130482,-0.121291,-0.005337,0.750787,-0.128887,-0.103432,0.291851,0.606208,0.241417,0.229383,0.353219,-0.230764,-0.075700,0.047849,0.421779,-0.531330,0.288068,0.236093,-0.162635,-0.099063,0.211531,0.062658,0.389117,0.271982,-0.104088,-0.210096,-0.064689,0.582381,-0.338427,0.055783,0.259730,0.085631,0.147321,0.109514,0.163864,-0.042657,-0.167916,0.032713,-0.232344,-0.989253,-0.075600,0.320333,0.152675,-0.698184,0.320567,-0.176363,-0.263871,-0.018386,-0.081752,0.337882,0.391870,0.248352,0.319069,-0.300780,0.061696,-0.558548,0.566882,0.968705,0.158409,-0.201898,0.510187,-0.211552,-0.337867,0.183646,-0.430040,-0.451561,0.025395,-0.090944,0.134995,0.056986,0.059612,-0.344100,-0.098413,-0.267807,-0.065466,0.203092,-0.493664,-0.086145,0.091018,-0.223224,-0.398186,-0.243533,-0.169201,0.057739,-0.477104,0.903483,-1.027596,-0.007328,0.526772,0.262261,-0.668523,0.789707,0.425996,0.115861,-0.416360,-0.068611,-0.071933,-0.129252,0.327978,-0.189705,0.143613,0.215908,-0.392583,-0.381877,0.350788', '1877596', '4301278', '1308424', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5989818', '萤火之森', '剧情', '某年夏天，6岁小女孩竹川萤来到爷爷家度假，她闯进了传说住满妖怪的山神森林。正当她因为迷路而焦急万分的时候，一个戴着狐狸面具的大男孩出现在她面前，并引领着萤找到回家的路。虽然萤分外感激，可是男孩却禁止她碰触自己的身体，原来这名叫银的男孩并非人类，他一旦被人类碰触就会烟消云散。在此后的日子里，萤和银成为好朋友，他们走遍了森林的每一个角落玩耍。日复一日，年复一年，每到夏天的时候萤就会如约来到森林和好朋友见面。她遵守着和银的约定，无论如何也不碰触银的身体。随着年龄的增长，萤和银对彼此的情感都悄悄发生了变化，他们共同期待相聚的日子，共同期待拥抱对方……本片根据绿川幸的原作改编。©豆瓣', '佐仓绫音', '大森贵弘', 8.9, 494729, 'tt2061702', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1675053073.jpg', 0.2, 0.8, 9.6, 34.4, 55, '0.150812,0.077319,-0.763551,0.321016,0.001089,-0.080104,0.904361,0.169284,-0.284393,-0.222743,0.203039,0.681658,-0.312936,0.429029,0.161344,0.064377,-0.216416,-0.583574,-0.049698,-0.252825,-0.309143,-0.043271,-0.108193,-0.078907,0.099350,-0.341673,0.640665,0.111093,-0.081536,0.490271,0.118363,-0.083996,-0.243700,0.611046,-0.493359,-0.138049,-0.014796,0.277567,-0.021361,0.129696,-0.127496,-0.096951,-0.090382,0.054033,-0.018214,0.391159,0.831919,-0.288030,-0.389338,0.099471,0.198812,-0.326055,-0.163159,-0.006636,0.439670,-0.063555,0.139552,0.156297,-0.020656,0.014053,-0.244272,-0.227679,-0.553816,0.361526,0.217484,0.268040,-0.600740,0.459703,0.278331,-0.130923,0.157791,-0.462341,0.154040,0.289990,0.175036,0.168938,-0.265845,0.043767,-0.525987,0.006375,0.791048,-0.187094,-0.180721,0.333409,-0.360270,-0.518874,-0.106215,0.100800,-0.492881,0.011879,-0.063310,0.107446,-0.532961,0.139890,-0.689636,0.102538,-0.072458,-0.083462,0.223684,-0.590492,-0.273985,-0.433630,0.031035,-0.594294,-0.575417,0.126070,-0.072960,-0.227014,0.656979,-0.835948,0.376587,0.708415,0.530343,-0.334944,1.006127,-0.010131,-0.126727,-0.415354,-0.062710,0.523621,0.026431,0.353928,0.190339,0.221066,-0.157293,0.318200,-0.487805,0.691873', '3055049', '1292211', '1302384', '3629232');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5992865', '北村方向', '剧情', '首尔电影学院教授兼导演尚俊（刘俊相 饰）近来闲暇无事，决定去北村会老友电影评论家杨河（金相中 饰）。尚俊原先只是一个名气一般的导演，转行做教授后自感思想产生了偏执，对以往所拍的东西不断进行着反思。最近他已停止了拍片，他需要和各行业人物接触，以获取下一部戏的灵感，当然，不少的灵感来自自身的体验，这包括与学生们的交谈以及情妇带给他的两性感受。杨河性格孤癖且自闭，但人很坦率，平日除了做评论发稿件，他几乎足不出户，更谈不上有什么朋友，尚俊是他为数不多的故交中的一个。这次两人的会面会碰撞出什么火花......本片曾入围戛纳电影节©豆瓣', '刘俊相', '洪常秀', 7.7, 8785, 'tt1922561', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1133692403.jpg', 0.5, 2.8, 27.7, 50.4, 18.6, '0.326752,-0.227325,-0.412487,0.748963,0.155377,-0.148987,0.690283,0.185381,-0.608481,-0.557792,0.071682,0.634886,-0.458369,0.053539,0.119577,-0.320535,-0.320374,-0.643703,-0.061662,-0.095421,0.035157,-0.395111,-0.227338,0.070877,-0.330436,-0.166033,0.534742,-0.131012,-0.444293,0.335438,0.363085,0.096435,0.187255,0.418563,0.053975,-0.124078,-0.087637,0.260743,-0.356135,-0.098447,0.384704,-0.172845,-0.215009,0.030870,0.136202,0.403480,0.449010,-0.023715,-0.270272,-0.083952,0.602766,0.056566,0.199680,0.016537,0.080127,0.340682,0.514676,0.242874,0.057239,0.167853,-0.047041,0.036149,-0.718963,-0.077149,0.188221,0.319832,-0.359432,0.200018,0.073914,-0.161105,-0.196612,-0.296380,0.074348,0.227087,0.185931,0.132897,-0.137218,-0.080727,-0.154955,0.399848,0.770622,0.015074,-0.168547,0.475490,-0.386794,-0.499348,-0.140950,-0.231781,-0.338896,0.175636,-0.188049,-0.041416,-0.012329,0.188865,-0.484795,0.042186,0.312386,-0.263530,-0.003326,-0.360349,0.133221,-1.006094,-0.159770,-0.459211,-0.272982,-0.352649,0.428261,-0.348478,0.916818,-0.944223,-0.102750,0.491341,0.257930,-0.472337,0.763609,0.153044,-0.178207,-0.197475,-0.070205,-0.008217,-0.033571,0.072125,-0.033816,0.328851,0.167834,-0.402318,-0.163412,0.350445', '26259202', '4301278', '3811356', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5992987', '无头骑士异闻录：天下泰平', '动画', '映画馆へと向かう帝人と杏里。街头インタビューに立つ羽岛幽平。その姿を探す九瑠璃と舞流。テレビ鉴赏に勤しむセルティや新罗、门田达。穏やかに过ぎていく池袋の休日。しかしそこに现れる幽平杀害予告犯。さらに临也と静雄が遭遇した瞬间、その平穏は瓦解していき――！', '泽城美雪', '大森贵弘', 8.8, 5538, 'tt2025914', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2194457432.jpg', 0.4, 1, 9.8, 35.5, 53.3, '0.104809,-0.226039,-0.095826,-0.355157,0.677505,-0.225070,-0.041133,0.320655,0.199962,-0.563205,-0.028112,0.552547,-0.951539,0.031357,0.510498,-0.018734,0.095970,-0.794073,-0.049083,-0.176086,-0.097287,0.089046,0.141681,0.082016,-0.453567,-0.208105,0.137702,0.007482,-0.395445,0.368064,0.385031,0.786608,-0.221052,-0.068578,0.068972,0.142824,-0.348362,-0.043365,0.173140,0.320169,-0.482023,-0.526488,-0.784230,0.170902,0.487361,0.606433,0.867009,0.027788,-0.400580,-0.569119,0.011442,0.418739,-0.278443,0.155504,0.656444,0.301796,-0.615741,0.566300,-0.284852,-0.052205,-0.202990,0.139526,0.189072,-0.327823,0.376998,-0.208116,-0.026127,0.041059,0.106118,-0.187438,-0.042909,-0.292115,0.032204,-0.031044,-0.355692,0.220106,-0.185321,-0.127870,0.112168,-0.087237,0.432393,0.407015,0.051289,0.255899,0.031897,-0.188938,0.083264,0.160864,-0.149914,-0.084449,-0.209194,-0.361877,0.228800,0.008433,0.053011,-0.497648,-0.731998,0.159708,0.072005,0.593026,0.037058,-0.388465,0.186941,-0.274004,-0.318347,0.487007,-0.032996,0.068815,0.052805,-0.479649,-0.128145,0.564393,0.373268,-0.003361,-0.126569,-0.224315,-0.714622,0.388744,0.030666,-0.008068,0.074632,0.336531,0.242046,-0.346405,-0.375501,-0.233629,-0.089096,-0.135399', '35327724', '3836490', '35206186', '26323031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5993138', '王朝的女人·杨贵妃', '爱情', '巍巍大唐，如日中天。白衣会上，杨家有女初长成，绰约风姿抓住了帝王李隆基（黎明 饰）的视线，也由此注定了她一生的不平凡。为了防止杨玉环（范冰冰 饰）对自己后宫地位构成威胁，武惠妃（陈冲 饰）巧舌如簧，将玉环变成了她儿子寿王李瑁（吴尊 饰）的王妃。武惠妃雍容华贵，风韵犹存，可怕的是其骨子里流淌着如姑母武则天般对权力极度渴望的血液。为了让寿王践祚，她不惜设毒计构陷太子，致使东宫喋血，父子相杀。开元盛世走到顶点，王朝的荣光逐渐开始褪色。玄宗无法遏制对杨玉环的痴恋，他执拗地坠入了温柔乡，和这个他所珍爱的女子共同从繁华走向了黑暗身处……©豆瓣', '范冰冰', '十庆', 3.7, 47731, 'tt2080418', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2257475080.jpg', 45.1, 31.1, 17.5, 3.7, 2.6, '0.024000,0.547172,-0.646739,0.697228,-0.167533,-0.170479,0.821999,0.582797,-0.687904,0.100578,0.671857,0.574033,-0.104287,0.062395,-0.014641,0.264898,-0.008764,-0.650444,-0.389504,-0.117463,0.042245,-0.044039,-0.248774,-0.071231,-0.269559,-0.182922,0.778754,0.150582,-0.155830,0.185044,0.357411,0.269010,0.067362,0.413489,-0.415124,-0.075544,-0.153985,-0.043939,-0.262843,0.126747,-0.058285,-0.631081,-0.272110,0.437251,-0.548924,0.037164,0.574438,-0.479923,0.169481,-0.310552,0.677887,-0.253721,-0.138081,0.410245,0.005490,-0.081576,-0.232783,0.364578,-0.120219,-0.285704,0.089165,-0.106042,-0.549588,-0.077245,0.113805,0.272711,-0.408459,0.581902,-0.226614,-0.373006,0.353050,-0.202799,0.196879,-0.025484,0.039303,0.215600,-0.189797,-0.029473,-0.608334,0.453347,0.577424,0.235514,-0.280909,0.282566,-0.228701,-0.425188,0.028488,-0.359444,-0.486805,-0.343734,0.416761,0.271772,0.195365,0.580479,-0.366493,0.057269,-0.373801,0.146877,0.120032,-0.483876,-0.034214,0.035320,-0.643895,-0.786938,-0.227836,-0.013005,0.098159,-0.179460,0.620793,-0.591662,0.108390,0.559977,0.252381,-0.712492,0.612730,0.009625,-0.073354,-0.071760,-0.215446,0.374228,-0.196182,0.289916,-0.087984,0.229200,-0.387680,0.170455,-0.383868,0.513469', '1418605', '1292329', '30364976', '4202204');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5993185', '星空', '剧情', '在人生最最纯然且充满想象力的几年里，13岁的小女孩谢欣美（徐娇 饰）都与爷爷（曾江 饰）在深山里度过。古朴的小木屋和静寂迷人的夜空，是她记忆深处最遥远和笃定的依恋。可是终于有一天小美要离开这里，她随着爸爸（庾澄庆 饰）妈妈（刘若英 饰）回到城市生活。繁华的都市五光十色，却无法带给她些许的归属与感动。与小美有着类似地感受的是频繁随着父母搬家与转学的男孩周宇杰（林晖闵饰），相似的境遇与心境让他们走到一起，成为最要好的朋友。某一天，小美的爸爸妈妈选择分手，而她也终于决定回到深山，带着她的好朋友小杰，一同去仰望那久违已久的星空……本片根据著名绘本画家几米的同名原著改编。©豆瓣', '徐娇', '林书宇', 7.2, 131472, 'tt2084098', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1631281853.jpg', 1.1, 6.8, 39.8, 36.7, 15.5, '0.071048,-0.080615,-0.770321,0.752952,-0.062522,-0.289842,1.002065,0.126287,-0.495304,-0.278868,0.112966,0.842891,-0.079358,0.655361,0.231097,0.183513,-0.389235,-0.601217,-0.119699,-0.308780,-0.135772,-0.429455,-0.275011,0.200143,0.031038,-0.194705,0.849447,0.179065,-0.083761,0.657804,-0.026330,0.045781,-0.425205,0.395275,-0.401079,-0.060073,-0.154276,0.411789,-0.605811,0.054946,0.163154,-0.005720,-0.221223,-0.136160,-0.002438,-0.084315,0.823908,-0.089413,-0.320011,0.330139,0.387571,-0.054553,-0.263299,0.017705,-0.002727,-0.008769,0.386452,0.185523,-0.375009,-0.042838,-0.123591,-0.202347,-0.475849,0.190261,0.344449,0.065253,-0.408830,0.533578,0.210744,-0.390437,0.582951,-0.525815,0.328880,0.039145,0.084401,0.684970,-0.246375,0.200578,-0.262558,0.123007,0.702113,0.080419,-0.051619,0.304755,-0.221194,-0.385671,-0.060555,-0.007277,-0.625451,0.147072,0.087373,0.080524,-0.241611,0.263308,-0.782616,0.217313,0.024415,-0.220364,0.153089,-0.486605,-0.042170,-0.498305,-0.190098,-0.635579,-0.242059,0.210289,0.031649,-0.221120,0.852726,-0.830620,0.422040,0.274570,0.317589,-0.215571,0.876473,0.035163,0.014247,-0.285922,0.134659,0.499770,-0.264594,0.180899,0.004664,0.266165,-0.240656,0.153534,-0.802587,0.583160', '1296534', '3055049', '1291835', '6875863');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5995338', '如沐爱河', '剧情', '光怪陆离的国际大都会，日本东京。灯影暧昧的酒吧内，人们窃声交谈，笑语欢歌。酒吧一隅，穿着打扮与周遭格格不入的明子（高梨临 饰）面带焦虑。她是一名女大学生，为了学费而在声色场所出卖笑靥。此时此刻她正与多疑的男友（加濑亮 饰）在电话里纠缠。是日祖母突然来访，但明子犹豫不决是否该去车站看看老人。本就心情烦躁，加上店长（点点 饰）的工作安排更让她情绪失控。夜幕降临，失意的明子最终来至客人的住地。那是一位84岁的退休大学教授（奥野匡 饰），也许因为明子与亡妻容貌相似才让老人将女孩召唤至此。疲惫的女孩无暇享受老教授精心准备的美酒佳肴，简单交谈后便沉沉睡去，一夜无话。次日，教授驱车送女孩回校，心与心的交流仿佛仍未停止……©豆瓣', '奥野匡', '阿巴斯·基亚罗斯塔米', 7.7, 24727, 'tt1843287', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1678138538.jpg', 0.8, 3.2, 27.9, 48.1, 20, '0.233506,0.154193,-0.565457,0.255501,-0.108659,-0.365377,0.782157,0.426523,-0.526270,-0.471633,0.222745,0.384454,-0.197378,0.526579,0.387702,0.039605,-0.429497,-0.461575,-0.042097,-0.146433,0.038318,-0.358444,0.061210,-0.185762,-0.067238,-0.375965,0.250566,-0.025878,0.064812,0.689377,0.030434,0.032833,-0.219237,0.606133,-0.105624,-0.341138,0.044239,0.208779,-0.133237,-0.014068,0.083271,-0.286125,-0.318642,-0.059853,0.090834,0.344309,0.749418,0.035854,-0.212906,0.095774,0.190313,0.091061,0.004855,0.259394,0.162476,0.109562,0.427170,0.055896,-0.424173,0.049013,-0.141205,0.100277,-0.187559,0.502217,0.054616,0.232487,-0.287548,0.551211,-0.090045,-0.235605,0.151621,-0.380830,0.258353,0.078419,0.167206,0.482992,0.068011,0.054253,-0.147703,0.251939,0.513766,0.307495,0.130027,0.497920,-0.130162,-0.267738,0.234876,0.029161,-0.439514,-0.148245,-0.042454,0.061844,-0.044050,-0.029920,-0.463607,-0.066681,-0.288869,0.011312,-0.065864,-0.382804,-0.143672,-0.672871,-0.027848,-0.345695,-0.094965,0.070653,0.507643,0.291317,0.643332,-0.790061,0.226274,0.351422,0.217483,-0.313770,0.639800,0.007965,-0.070517,-0.102821,-0.056630,0.011200,-0.235087,0.307909,-0.043919,0.475509,-0.458886,0.060030,-0.457273,0.029153', '26687241', '3041753', '7052437', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5996409', '东京家族', '剧情', '2012年的一天，年届七旬的平山周吉（桥爪功 饰）和老伴富子（吉行和子 饰）结伴来到东京。这片繁华匆忙的土地上，生活着他们三个子女，在郊外开办诊所的长子幸一（西村雅彦 饰），与丈夫库造（林家正藏 饰）共同经营美发店的女儿滋子（中岛朋子 饰）以及担任歌舞伎美工的次子昌次（妻夫木聪 饰）。一家人久未团聚，自然心间充满喜悦。只是子女长大成人，荷担家业，从早到晚为了生计奔波劳碌，根本无暇带着父母游览东京。老两口先后在孩子们的家中小住，深深感受到他们的艰辛，而昌次对未来的茫然似乎也让平山夫妇多了一份担心。也许一切都会好起来，总要有放开手的时刻。短短几日盘桓，为人父母的心中涌起万千情感，却来不及一一道出……©豆瓣', '桥爪功', '山田洋次', 8.8, 53719, 'tt1796652', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1919295170.jpg', 0.1, 0.5, 8.1, 42.5, 48.8, '-0.228197,-0.100495,-0.847625,0.345081,0.144895,-0.529443,0.517964,0.308126,-0.721832,-0.358428,0.216636,0.630570,0.019341,0.577690,0.230100,0.017568,-0.230365,-0.504171,-0.035556,-0.222880,-0.105220,-0.247846,0.065802,-0.240513,-0.276334,-0.173515,0.353911,0.339468,0.506500,0.636629,0.054907,0.092629,-0.326571,0.305397,-0.120793,0.123302,-0.065205,0.275662,-0.443167,-0.199739,-0.037598,-0.182830,-0.549333,-0.155494,0.154458,0.280777,0.805941,0.092563,-0.191898,-0.103472,0.089486,0.056242,-0.025552,0.189840,0.153906,-0.083305,0.269772,0.285380,-0.599795,-0.022113,0.024039,-0.021366,-0.470803,0.031367,0.124102,0.052034,-0.599053,0.505081,-0.015687,-0.545457,0.106208,-0.558709,0.205019,0.468120,-0.111836,0.552739,-0.432944,0.339526,-0.292243,0.336494,0.750732,-0.121832,0.072889,0.074390,-0.256538,-0.111166,-0.027826,-0.138949,-0.497254,-0.407524,0.105361,0.158688,-0.020440,0.221528,-0.360304,0.150891,-0.139772,-0.279590,0.454814,-0.394820,-0.070064,-0.508612,0.033701,-0.609674,-0.456189,0.294637,0.363443,-0.029383,0.716443,-0.638780,0.263036,0.259308,0.191514,-0.344386,0.718041,0.006016,0.309103,-0.151033,-0.100762,0.107847,-0.194881,0.338633,0.357647,0.091034,-0.364731,0.181455,-0.304135,0.336749', '1300202', '1292219', '10573695', '1296044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5996799', '忠烈杨家将', '战争', '北宋年间，辽国兵马在耶律原（邵兵 饰）的率领下大举入侵中原，当今圣上着杨业（郑少秋 饰）和潘仁美（梁家仁 饰）两位重臣出兵抗辽。谁知潘仁美公报私仇，于金沙滩一役临阵撤兵，致令杨业陷入重围，困于两狼山城。杨家有子七人，依次为：延平（郑伊健 饰）、延定（于波 饰）、延光（周渝民 饰）、延辉（李晨 饰）、延德（林峰 饰）、延昭（吴尊 饰）和延嗣（付辛博 饰）。虽然前路凶多吉少，但为了营救父亲杨家七人依旧冒险出征。然而此一战凶险非常，一方面耶律原势要报当年杀父之仇，屠尽杨家父子；另一方面潘仁美作壁上观，意欲置杨家于死地而后快。苍凉两狼山，一曲忠义悲歌流传千古……©豆瓣', '郑少秋', '于仁泰', 6.2, 33239, 'tt2072220', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1902795588.jpg', 5.1, 17.6, 47.5, 20.7, 9.1, '-0.310492,-0.056366,-0.432691,0.569721,0.607694,0.120799,0.189271,0.419925,-0.625745,-0.355603,0.375381,0.488919,0.396540,-0.242374,0.157888,-0.177002,0.113824,-0.394725,0.057854,0.032779,0.353812,-0.364135,-0.166962,-0.115543,-0.291219,0.192566,0.701501,0.308400,0.050719,0.857569,0.405344,0.282405,-0.366638,0.281156,0.172267,-0.047675,-0.379412,0.044205,-0.698045,0.166881,-0.453526,-0.289912,-0.631260,0.129509,-0.252610,0.179069,0.287054,-0.315481,0.320954,-0.263663,0.154904,-0.186362,0.055129,0.178569,0.245248,-0.004757,0.355724,0.720089,-0.206243,-0.041635,0.098618,0.017612,-0.310280,-0.122435,0.350764,-0.266355,-0.441183,0.332960,-0.343700,-0.062774,0.159913,-0.263456,-0.021703,0.728568,0.422148,-0.093897,-0.112287,-0.236045,-0.483562,0.079285,0.523594,-0.111056,0.216786,-0.718010,0.708909,-0.326168,0.100315,-0.221008,-0.407988,0.121501,0.347715,-0.076026,0.313773,0.080948,-0.114710,-0.202365,-0.277940,0.419410,0.080024,0.205829,0.169995,-0.178184,-0.055366,-0.298376,-0.291328,0.078937,0.558230,0.128557,0.169367,-0.250122,-0.308955,-0.014554,0.057525,-0.913316,0.088247,0.629103,0.018983,0.067382,-0.232339,0.169305,0.216241,-0.130896,0.098272,-0.003287,-0.397854,-0.141584,-0.427955,-0.044531', '1300060', '1484760', '3264045', '1461031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5996800', '太极1：从零开始', '喜剧', '清朝中叶，内忧外患，传统崩溃，民生凋敝。小男孩杨露禅额头天生肉角、相貌奇异，却只会吃和傻笑，大家认定他这辈子只能混吃等死，唯独杨母（舒淇 饰）认为儿子露禅（袁晓超 饰）天赋异禀，将来必成大器。随着年龄增长，露禅渐渐展现异于常人的能力——对于种种拳脚招式，过目不忘，尤其是头顶肉角一旦被触动，更是力大无穷，无人能敌。高人指出，如能善用此天赋，他将成为绝顶高手，但若放任其颜色由红转黑，必有性命之虞。露禅一路颠沛流离来到陈家沟——太极拳的发源地，希望学拳保命。孰料陈家拳不传外人，所幸有神秘老人（梁家辉 饰）总在关键时刻暗中指点，露禅进步神速，令村民刮目相看。一向平静的山村，因为朝廷修筑铁道面临灭村危机。在陈家沟成长，从英国学成归国的直隶铁道总监造方子敬（彭于晏 饰），为了自己的前途，不惜牺牲乡亲的利益。玉娘（杨颖 饰）与子敬青梅竹马，面对爱人背叛，伤心欲绝，决定不惜性命保护家园。子敬率领机械怪兽“特洛伊”直捣村口，威胁村民限期搬离，否则夷为平地。露禅在神秘老人的指点下，与玉娘并肩作战，一举摧毁特洛伊，打退清兵，拯救全村。陷入疯狂的方子敬，誓言以更强大的火力报复，而玉娘也做出了一个重大决定……', '袁晓超', '冯德伦', 5.7, 98427, 'tt1981080', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1710333164.jpg', 8.1, 22.8, 47.8, 16.6, 4.7, '-0.333918,-0.057711,-0.298100,0.353621,-0.134996,0.103407,0.066577,0.170876,-0.545977,-0.265233,0.403582,0.433110,0.224151,-0.082295,0.127633,-0.516864,0.262568,-0.332248,0.105317,0.078479,-0.037618,-0.228136,-0.201705,-0.171834,-0.258221,-0.478515,0.425406,0.216135,-0.439309,0.333856,-0.004346,0.135061,-0.158212,0.093610,-0.037795,-0.199458,-0.393795,-0.148259,-0.428060,-0.046363,-0.179389,-0.183482,0.052787,0.106011,-0.306273,0.114303,0.453203,-0.208538,-0.302759,-0.417074,0.277927,-0.214620,-0.065349,0.281281,0.153306,0.009896,0.160191,0.249116,-0.004908,0.035242,0.053594,-0.042113,-0.685726,-0.023541,0.392440,-0.246654,-0.377115,0.084131,0.074191,-0.134582,-0.137109,-0.242239,-0.041579,0.273143,0.322628,0.196142,-0.278125,0.103467,-0.248555,-0.127617,0.402005,-0.248351,-0.104493,-0.123768,-0.070196,-0.150825,0.278028,-0.482081,-0.199001,0.082239,0.070025,0.109927,0.024367,0.333671,-0.047956,0.049151,-0.283239,0.275593,0.143943,-0.180296,0.019594,-0.270912,-0.111603,-0.204338,-0.206803,0.193213,0.128377,-0.264202,0.813642,-0.361322,0.047810,0.141690,0.286600,-0.549232,0.298686,-0.032779,0.112109,-0.252404,-0.136187,0.548303,0.040002,0.082351,-0.267483,-0.158033,-0.081974,0.014073,0.084201,0.312885', '27602116', '24284209', '3718665', '1308424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5996801', '狄仁杰之神都龙王', '动作', '唐朝麟德年间，唐高宗（盛鉴 饰）与武则天（刘嘉玲 饰）强硬派出大军远征，谁知舰队在大海中遇袭，遭到重挫。该事件震惊洛阳，都城百姓狂热祭拜龙王，缭乱众生的“花魁”银睿姬（杨颖 饰）更惹来各方势力觊觎。狄仁杰（赵又廷 饰）奉武后之命调查龙王一案，偏巧卷入绑架银睿姬的案件之中。在与劫匪搏杀过程中，狄仁杰遭遇亦敌亦友的大理寺卿尉迟真金（冯绍峰 饰），遂被对方投入大牢。银睿姬一案内龙王身影再现，使洛阳上空更添一道疑云。狱中狄仁杰凭借缜密推理博取回纥医工沙陀忠（林更新 饰）的信任，逃出大牢同查龙王真相。两起案件错综复杂，相互纠缠，引向全然未知的方向……©豆瓣', '赵又廷', '徐克', 6.5, 209643, 'tt2992146', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2099623528.jpg', 2.5, 11.9, 51.6, 27.1, 6.9, '-0.072027,0.196524,-0.465311,0.440152,0.633139,0.190092,0.490682,0.195830,-0.649325,-0.229705,0.353262,-0.009549,-0.272310,-0.301816,0.395016,-0.157085,-0.198567,-0.586498,-0.186024,-0.239133,0.166116,-0.301555,-0.219005,-0.240162,-0.134278,0.052247,0.509974,0.433689,-0.091343,0.468460,0.297416,0.375640,-0.692925,0.544482,0.322075,0.225051,-0.028668,0.078702,-0.297118,0.019049,-0.246684,-0.512187,-0.289609,0.129011,-0.152435,0.058756,0.596836,-0.476193,0.116082,-0.334691,0.352959,-0.184909,-0.019893,0.077690,0.523081,0.239594,0.007705,0.484327,-0.065614,0.026588,0.078589,0.021562,-0.099883,-0.036826,0.205196,0.115770,0.067119,-0.052256,-0.072936,0.107994,0.059417,-0.124182,0.123689,0.392496,0.280489,-0.115677,0.069549,-0.299391,-0.358965,0.450137,0.302347,-0.132318,0.122990,-0.625624,0.059646,-0.349521,0.090246,-0.109245,0.171367,0.091609,0.495884,-0.141289,0.210827,0.937033,-0.074768,-0.306541,-0.438241,0.205811,-0.057598,0.027142,0.134321,-0.551588,-0.218684,-0.108942,-0.008843,-0.189203,0.336352,0.065483,-0.054075,-0.228368,-0.005952,0.194859,0.184523,-0.540197,0.187437,-0.025214,0.114144,-0.105698,-0.318879,0.209349,0.339054,0.098751,-0.143076,-0.131610,-0.320308,-0.161600,-0.321871,-0.220361', '30423193', '26662798', '1303917', '26277156');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5997157', '年轻时候', '剧情', '一对夫妇过着平凡又重复的生活，直到他们遇见一对新鲜潮人。生活是变得丰富，还是终归各活各的。', '娜奥米·沃茨', '诺亚·鲍姆巴赫', 6.8, 10569, 'tt1791682', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2227669765.jpg', 1.1, 7.6, 48, 35.8, 7.5, '0.202228,-0.422940,-0.288647,0.763988,-0.126210,-0.667761,1.241391,0.124493,-0.532208,0.073915,0.257805,0.667295,-0.307719,0.334421,0.061377,-0.157649,0.013357,-0.252569,0.010095,0.196147,0.191149,-0.037535,-0.367050,0.112630,-0.060197,-0.119430,0.249857,0.026645,-0.055434,0.515798,0.101342,-0.263952,-0.432775,0.126713,-0.757449,-0.262185,-0.353822,0.754539,-0.502521,-0.557116,-0.043638,0.080261,-0.320480,-0.030497,0.260069,0.325670,0.871395,-0.122557,-0.786837,0.427463,0.099935,0.090273,-0.661087,0.221560,0.488680,0.574423,0.085033,0.178747,-0.280762,0.261076,-0.707845,0.105570,-0.614169,0.033299,0.391452,0.190643,-0.797091,0.864653,0.443674,-0.425918,-0.269916,-0.505991,0.224885,0.373110,0.433626,0.813578,0.550759,0.273044,-0.353817,0.515427,1.322893,0.161857,-0.674739,0.248408,-0.623237,-0.502245,0.234644,-0.292342,-0.734823,-0.051245,0.031793,-0.179625,-0.210819,0.487247,-1.015157,0.852361,-0.188129,-0.532186,0.485591,-0.315743,0.144385,-0.698464,0.145205,-1.383330,-0.802616,0.484638,-0.099770,-0.512284,0.972766,-0.859280,-0.097001,0.222543,0.137760,-0.542081,0.447632,0.537475,0.144373,-0.069307,-0.289621,0.664857,-0.128998,-0.297597,-0.146805,0.349161,-0.078555,0.467835,-0.373838,0.630784', '1307561', '26320029', '20398974', '1689787');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('5999381', '青蛙公主', '喜剧', '在菜市场靠卖青蛙为营的Tukky（苏达拉•布查蓬 Sudarat Butrprom 饰）从小到大都梦想有一日可以成为童话里受人瞩目的公主，然而丑陋的长相和矮小的身材让她成了街坊邻居嘲笑讥讽的对象。没想到，梦想总有成真的一天，一根小时候意外所得的青蛙项链让她被人错认为是青蛙共和国的公主带回皇宫。然而DNA的检测结果显示了她并非真正的公主，帅哥护卫队长Oop（路易斯•斯科特 Louis Scott 饰）则开出了一千万泰铢的酬劳请求Tukky假扮公主直到他找到真身。于是Tukky答应了Oop的请求，开始了公主课程的培训。然而她发现，原来公主的生活并不如童话里那么美好，繁重的学习任务压着她，每天忙碌于学习化妆，马术，品酒，舞蹈和听取民意。更危险的是，而叛军对她的追杀更是从未停止…©豆瓣', '苏达拉·布查蓬', 'พรชัย หงษ์รัตนาภรณ์', 5.7, 5245, 'tt1706515', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p871345533.jpg', 8.6, 22.9, 47.7, 15.2, 5.6, '0.100934,0.017232,-0.518442,0.745022,-0.168186,-0.185563,0.597040,-0.037359,-0.434198,-0.343018,0.270138,0.376689,-0.067198,0.093263,0.359668,-0.089389,-0.071319,-0.434975,-0.108025,-0.230823,-0.123771,-0.405585,-0.113944,-0.419767,-0.028046,-0.555882,0.556518,-0.025817,-0.076808,0.478134,0.355796,-0.101744,0.178754,0.378227,-0.272210,-0.164360,0.039332,0.283639,0.066125,0.208358,0.039125,-0.294561,0.021115,0.164474,0.050100,0.296399,0.498909,-0.414279,-0.076254,-0.195281,0.401759,-0.194840,0.089784,0.175121,0.307306,-0.088802,0.313086,-0.131697,-0.179385,0.016972,0.265654,-0.349084,-0.464008,-0.033487,0.149205,0.049773,-0.499253,0.392337,-0.026401,0.106050,0.103498,-0.271387,0.186790,0.139600,0.327024,0.336956,-0.005382,0.123209,-0.671832,0.402876,0.504808,-0.058039,-0.298366,0.272973,-0.228278,-0.499731,0.060480,-0.469247,-0.426676,0.221880,-0.022100,-0.024503,-0.211390,0.111086,-0.441570,-0.071639,-0.280430,-0.207092,0.158367,-0.640607,-0.027087,-0.379207,0.107734,-0.323059,-0.128060,0.054291,0.229078,-0.475192,0.607367,-0.827679,0.147254,0.373964,0.171965,-0.549986,0.665909,0.066373,-0.104006,-0.036638,-0.064737,0.179743,0.102866,0.206533,0.048351,0.347312,-0.036768,-0.219381,-0.476071,0.449948', '1308499', '7065238', '2052978', '3033092');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6001038', '爷爷的煤油灯', '动画', '在文明开化的明治时代，在一个小村庄里，有个叫巳之助的少年孤儿，平时靠帮村民干活养活自己。有次进城，他见到街上一盏盏被点亮的煤油灯，大开眼界的他第一次感受到“文明开化”，于是，他决心要用煤油灯照亮自己的小村庄。很快，方便好用的煤油灯受到村里人欢迎，巳之助的生意也越来越好，他顺利成为一名煤油灯商人。后来他与小雪结婚，并且有了一双儿女，日子过得很幸福。但是后来当他再次进城，却发现城里家家户户都装上了电灯，已经没有人用煤油灯了。这次的“文明开化”让他感到十分恐慌。随后巳之助的小村庄也传来了要通电的消息，巳之助感觉到自己的煤油灯将被电灯取代，却无法阻止通电计划。在一个夜里，他潜入区长的家里想要纵火，但是他突然意识到自己的错误，他把自己最重要的东西忘记了……《爷爷的煤油灯》是日本青年动画制作者育成计划的参赛作品。©豆瓣', '神谷浩史', '泷口祯一', 8.3, 7975, 'tt17047406', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2554363367.jpg', 0.2, 0.7, 15.1, 53.2, 30.9, '0.227888,0.145712,-0.683842,0.360526,-0.322554,-0.075239,0.662781,0.131589,-0.526811,-0.145061,0.114284,0.661871,0.072103,0.214974,0.039033,0.067636,-0.189475,-0.465291,0.269963,-0.189930,-0.257998,-0.283527,-0.329723,-0.196039,-0.385193,-0.238289,0.376216,0.275275,-0.108937,0.106067,-0.057138,-0.268976,0.362531,0.626014,-0.272831,0.021063,-0.059936,-0.202430,0.031988,0.035840,-0.216849,-0.247613,-0.284477,0.257769,-0.051442,0.399078,0.579135,-0.213560,-0.348700,-0.045317,0.315150,-0.150113,-0.193290,0.157422,0.347701,0.115266,-0.088714,-0.055655,-0.156312,0.079952,-0.042392,-0.139452,-0.686569,0.189213,0.163310,0.010970,-0.551398,0.266836,-0.116373,-0.006252,0.123265,-0.607263,0.364583,0.283738,-0.110027,0.520062,-0.322287,0.002831,-0.658550,0.179596,0.602520,-0.447140,-0.099605,0.646857,-0.356388,-0.419959,-0.040728,-0.037810,-0.454590,-0.070322,0.440660,-0.073777,-0.512187,0.089777,-0.560712,0.149673,-0.092985,-0.345249,0.088722,-0.166597,-0.028558,-0.370134,-0.052083,-0.354431,-0.335596,0.278292,0.030985,-0.094413,0.728649,-0.715693,0.129984,0.537715,0.281555,-0.196847,0.686392,-0.181784,-0.074834,-0.005407,-0.062298,-0.077484,0.070096,0.680709,0.228829,0.308805,-0.063693,-0.314667,-0.363764,0.350539', '3055049', '1783461', '25911694', '1907966');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6005591', '屋顶的公寓', '剧情', '27岁的都市女孩桂木麻子（长泽雅美 饰）大学毕业后在就职战线上备受挫折，好不容易经老爸托情在一家编辑部找到工作，平日里就喜欢美食的麻子负责相应版块可谓得心应手。可是好景不长，她的公司突然倒闭，麻子重新沦为无业的状态。对未来和爱情都倍感迷茫，自小养尊处优的麻子决定尝试着独自生活。她租住了一户有露台的公寓，在此期间结识了热情的邻居猪熊真希（坂井真纪 饰），还接收了婚姻危机中的好友由香（芦名星 饰）。经好心的前社长介绍，他来到工藤俊一郎（吉田荣作 饰）经营的公司就职。她的生活似乎重新步入正轨，身边的朋友，同事，亲人也在匆忙的都市脚步中渐渐找到自己的节奏。本片根据阿川佐和子的同名小说改编。©豆瓣', '长泽雅美', '吉田秋生', 7.2, 6998, 'tt1843229', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p883812742.jpg', 0.4, 4.2, 40.8, 42.2, 12.4, '0.231919,0.034709,-0.410457,0.366464,-0.020481,-0.520182,0.189715,0.391847,-0.467207,-0.251977,0.242603,0.599941,0.100163,0.674643,0.234579,0.023814,-0.339329,-0.706043,-0.145004,-0.147727,-0.057936,-0.199701,-0.153426,-0.099345,-0.080078,-0.251522,0.470611,0.108644,0.005852,0.496637,0.100476,0.123333,-0.102050,0.315351,-0.158087,0.309553,0.321130,0.100614,-0.405030,-0.001602,-0.144153,-0.281533,0.070071,-0.050257,0.370830,0.451834,0.799262,0.061638,-0.411769,0.049053,0.457218,0.144105,-0.114126,0.052647,0.611557,0.206172,0.265202,0.134781,-0.368019,0.064159,-0.183062,-0.221603,-0.500794,-0.064882,0.192504,0.114255,-0.443882,0.497125,0.093523,-0.124944,0.128740,-0.388226,0.141503,0.234680,0.335205,0.352754,-0.182975,0.356793,-0.150939,0.448451,0.414641,0.014707,-0.038345,0.479375,-0.209241,-0.305992,-0.036542,-0.160299,-0.472635,-0.253917,0.034163,0.056562,-0.318495,0.132279,-0.566014,0.162944,-0.059533,-0.036239,0.204553,-0.357435,-0.075907,-0.737314,-0.111735,-0.310786,-0.098809,0.068442,0.096121,-0.261775,0.689073,-0.709599,0.123406,0.451096,0.345141,-0.325857,0.676206,-0.085908,0.027985,-0.236585,-0.082612,0.230011,-0.060243,0.580690,0.046075,0.245606,-0.237601,-0.188176,-0.453319,0.544599', '3811356', '5403927', '3041753', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6006087', '假小子', '剧情', '男孩子气的女孩劳拉（佐伊·赫兰 Zoé Héran饰）时常被误认为是男生，而且她自己也不认同自己的女孩性别。一天，她跟随家人搬到了新的社区生活。在这里，劳拉干脆彻底把自己打扮成男孩“米克尔”，剪短发、穿男孩子的衣服，更像男孩子一样赤膊踢球、游泳。这很自然的吸引了女孩儿莉 莎（让娜·蒂森 Jeanne Disson饰）的注意力，两个年龄相仿的女孩相互倾慕，逐渐成为“两小无猜”的小情侣。劳拉这场瞒天过海的谎言，会随着暑假结束的到来而被拆穿么？©豆瓣', '佐伊·赫兰', '瑟琳·席安玛', 7.9, 26308, 'tt1847731', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2558535421.jpg', 0.2, 1.1, 22.3, 54.3, 22.1, '0.342639,-0.185349,-0.366793,0.130995,-0.570574,-0.019764,0.483532,0.110209,-0.161160,-0.191084,0.262221,0.781598,-0.400561,0.434622,0.416883,0.255255,-0.492593,-0.755772,0.078099,-0.147669,-0.364403,-0.256227,0.103702,-0.151223,-0.156076,-0.424971,0.568262,-0.421399,-0.048767,0.261036,0.479987,0.051740,0.176074,0.483490,-0.272892,0.099480,-0.004868,-0.241559,0.334022,0.136220,-0.105655,0.109066,0.089331,-0.000882,-0.139620,0.183823,1.033269,-0.266237,0.050391,-0.156368,0.558537,-0.192196,-0.018510,0.052482,0.324103,-0.225552,0.322552,-0.184816,0.048740,0.008125,0.369767,-0.173970,-0.046719,0.554560,0.361649,0.028883,-0.380538,0.405102,0.281989,-0.082033,0.215307,-0.277014,-0.024276,0.219834,0.249575,0.171258,-0.127350,0.014794,-0.601578,0.236969,0.604093,0.246350,-0.178681,0.476442,-0.678888,-0.085496,-0.055639,-0.212782,-0.663051,0.027704,0.351952,-0.122623,-0.253454,0.159838,-0.613821,-0.219275,-0.129300,0.081585,0.046151,-0.721140,-0.158245,-0.463005,-0.204482,-0.643496,-0.145330,-0.200554,0.009092,-0.293916,1.060073,-0.802780,-0.153877,0.553925,0.368460,-0.420061,0.522164,-0.117312,0.264679,-0.197174,0.034327,0.316662,0.067947,-0.215721,0.227393,0.710487,-0.321387,0.056696,-0.345754,0.534706', '3811356', '1309161', '5403927', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6006335', '机器人大爷', '剧情', '小林弘树（滨田岳 Gaku Hamada饰）、长井信也、太田浩二是家电制造商木村电器的职员，为了保住工作，无奈的情况下接受了社长要求其在短时间内开发直立行走的机器人为公司宣传的苛刻任务。但机器人“新海风”在展览会临近的日子意外跌落摔坏，走投无路的三人决定用人偶试镜的方式 选拔身材相符的真人假扮机器人来蒙混过关。铃木重光（五十岚信次郎 饰）是个已是七十三岁的年纪的独居老头，儿女不在身边的他，为了改变退休后孤独苦闷的生活状态决定寻觅一份新的工作。当报纸上看到了三人组的征聘广告，在不知情的情况下假扮起了机器人。然而展览会上因为意外性的事件一炮而红的“新海风”把事态引向了无法控制的局面，三人组不得不告知真相继续寻求铃木大爷的帮助。而此时酷爱机器人的女生叶子（吉高由里子 Yuriko Yoshitaka 饰）也开始渐渐怀疑起“新海风”的真实性…©豆瓣', '五十岚信次郎', '矢口史靖', 7.6, 10964, 'tt1805492', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1679036475.jpg', 0.3, 2.3, 28.4, 52.6, 16.4, '0.154766,0.153758,-0.339670,0.381821,-0.168377,-0.234914,0.355275,0.318480,-0.436346,-0.401886,0.413497,0.492741,0.090337,0.272027,0.291368,-0.077024,-0.423104,-0.446929,-0.183317,0.029081,-0.237982,-0.529080,-0.131811,-0.385829,-0.176928,-0.207089,0.896347,0.052457,-0.212307,0.350783,0.336028,0.196556,0.017659,0.320132,0.133841,-0.235616,-0.014834,-0.028796,-0.238168,0.280074,-0.235653,-0.365691,-0.013474,0.200217,0.210338,0.513841,0.665778,-0.176913,-0.355860,-0.147056,0.472223,-0.073805,-0.010182,0.147610,0.367107,0.187180,0.072114,0.009832,-0.409012,0.040914,0.055263,-0.073935,-0.741633,0.001028,0.140735,0.199802,-0.473798,0.329598,-0.275223,-0.100212,0.142335,-0.590197,-0.092360,0.344441,0.463878,0.343336,-0.392050,0.347685,-0.284118,0.228270,0.462267,0.116577,-0.201336,0.380706,-0.173244,-0.367506,-0.242541,-0.343926,-0.236497,-0.132600,0.041491,0.200556,-0.187664,0.088061,-0.501728,-0.025194,-0.058659,-0.256000,-0.091475,-0.317937,-0.092564,-0.575313,0.035785,-0.143811,-0.297330,-0.168163,0.206817,-0.339840,0.548900,-0.696262,-0.029085,0.591158,-0.020204,-0.338673,0.325730,-0.101317,-0.032049,-0.316792,-0.141779,-0.183521,-0.120112,0.582912,0.178740,0.351784,0.025676,-0.405579,-0.301340,0.168283', '26759820', '3861846', '2369613', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6007281', '名侦探柯南：沉默的十五分钟', '动画', '位于东京的东都线地铁开通当日，一起针对东京都知事朝仓优一郎的炸弹袭击事件爆发，导致东都线列车损毁。经过一番推理，柯南（高山みなみ 配音）等人认定这与8年前朝仓主持负责的北之泽水坝的修建有关。当年为了修建大坝，朝仓动员北之泽村的人民搬入新村，可是仍有许多人反抗到最后阶段。为了探明真相，柯南、灰原（林原めぐみ 配音）、少年侦探团以及毛利小五郎（小山力也 配音）等人开赴白雪皑皑的北之泽。在这片纯净的雪国，少年们尽情玩耍，与此同时他们也遇到了几名原北之泽村的村民，山尾溪介、远野瑞希、立原冬美等人。他们是从小一起长大的好朋友，而彼此之间似乎又有着某种芥蒂和秘密。真相究竟如何……本片为《名侦探柯南》第15部剧场版。©豆瓣', '高山南', '静野孔文', 6.8, 91797, 'tt1840372', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p981385980.jpg', 1.6, 10.3, 47.8, 27.5, 12.7, '0.105357,-0.283576,-0.685949,0.232745,0.119685,0.008358,0.348958,-0.048921,-0.472502,-0.426347,0.190629,0.553510,-0.243077,0.156421,0.152590,-0.146712,-0.591177,-0.499302,-0.080679,-0.286198,-0.152668,-0.395825,0.097546,-0.122774,0.072751,-0.194762,0.728230,0.248864,-0.034360,0.268535,-0.005424,0.250086,-0.451195,0.244380,0.164869,0.155390,0.081568,-0.117881,-0.170451,0.008480,-0.457960,-0.151693,-0.197396,-0.237413,0.218984,0.313542,0.708184,-0.092516,-0.176953,-0.080122,0.110158,-0.208844,0.016035,0.106629,0.540349,0.058900,0.078983,0.326928,-0.227636,-0.045657,-0.041856,-0.244006,-0.450014,-0.135828,0.271767,0.145734,-0.081689,0.298879,0.150884,-0.151938,0.211675,-0.257271,0.097906,0.534042,0.352909,0.311741,-0.256206,0.098981,-0.171673,0.015397,0.807860,0.000381,0.021295,0.082666,-0.027178,-0.410268,-0.187713,-0.197538,-0.139304,0.120101,0.041706,0.095003,-0.169935,0.150474,-0.491709,-0.128613,-0.039899,-0.226423,-0.037124,-0.264702,-0.025998,-0.854253,0.046565,-0.289145,0.131711,0.108968,0.294140,-0.192725,0.721949,-0.568184,0.026001,0.469557,0.261504,-0.410205,0.262521,0.018242,-0.050031,-0.328738,-0.172279,0.093890,0.120019,0.514299,-0.011263,0.101348,-0.095549,-0.182848,-0.429544,-0.017268', '2369613', '5403927', '20274039', '1507140');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6010171', '给桃子的信', '剧情', '11岁的小学6年级女孩宫浦桃子（美山加恋 配音）在父亲意外去世后，随母亲郁子（优香 配音）从东京迁到了濑户内海的汐岛。忙碌的母亲无暇顾及桃子，令桃子在新环境中时常感到孤单无助。桃子一直保留着父亲只写下了“给桃子”这样开头的一封信，但是始终无法明白父亲想要通过信件传达给她的话 。 初到汐岛，桃子打开了阁楼里一个装着描绘妖怪画册的旧盒子，从此开始察觉到身边一连串不可思议的事情。“汐岛上一定存在着什么东西”，怀抱着这样想法的桃子，在汐岛奇异而热闹的夏天里邂逅到的竟会是……？本片由日本知名动画公司Production I.G制作，是《人狼》导演沖浦啓之睽违多年的温馨治愈之作。©豆瓣', '美山加恋', '冲浦启之', 8.3, 68428, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1781641001.jpg', 0.2, 0.9, 16.4, 49.8, 32.8, '0.157817,0.101265,-0.579564,0.639848,-0.074974,-0.024960,0.605069,0.192101,-0.726762,-0.219144,-0.023865,0.629994,-0.078881,0.611890,0.063565,0.216175,-0.115505,-0.408953,-0.208013,-0.340439,-0.243660,-0.253360,-0.140247,-0.249727,0.008660,-0.293010,0.470369,0.233206,-0.032137,0.351126,0.035019,0.084527,-0.473461,0.468758,-0.008930,0.108633,-0.016496,0.107488,-0.090198,0.093206,0.093054,-0.196688,-0.178217,0.344734,0.049676,0.214083,0.704046,-0.313844,-0.301835,0.015777,0.420047,0.122047,-0.209783,-0.089547,0.278243,0.261677,0.237789,-0.195823,-0.341596,0.122712,0.029997,-0.236945,-0.294992,-0.014533,-0.064624,0.415712,-0.643701,0.317197,-0.150697,0.154627,0.247735,-0.449206,0.294165,-0.037677,0.275455,0.627965,-0.174212,0.204852,-0.292463,0.327640,0.350710,-0.088163,-0.025941,0.472561,-0.339090,-0.308913,0.168915,-0.179234,-0.388437,0.294541,0.126501,0.035131,-0.256348,-0.088698,-0.441480,-0.062046,-0.025420,-0.159516,0.327111,-0.378395,-0.261470,-0.222392,-0.030022,-0.098362,-0.218169,-0.049198,0.109288,-0.212266,0.802504,-0.629133,0.272556,0.602652,0.043686,0.052784,0.395655,-0.175116,-0.064192,-0.231582,0.037508,0.182391,-0.091748,0.171900,0.198581,0.283165,-0.042699,-0.173449,-0.613798,0.330674', '25731805', '1298468', '25738406', '5938000');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6011805', '一九四二', '剧情', '1942年，抗日战争与第二次世界大战正处于白热化阶段。燎原之火，生灵涂炭，天灾人祸，哀鸿遍野。当军事家和政治家的目光聚焦在一城一郭的征伐劫掠之时，几乎鲜少有人注意到古老的中原河南正爆发一场惨绝人寰的大旱灾。影片的主角老东家（张国立 饰），狡猾、市侩，典型的封建地主，可即便如此也无法对抗这史无前例的灾难，他被迫逃荒，亲眼见证着儿子、儿媳、老伴等亲人的种种死状。他的遭遇是三百万灾民的缩影，面对这群人的苦难，无论是高高在上的蒋委员长（陈道明 饰），还是深入民间报道灾难真相的美国记者白修德（阿德里安•布劳迪 Adrien Brody 饰），以及海内外的每一个人，如何能从这眼前的人间炼狱之景侧目。绝望无止的逃生坎途，中华民族多舛命运的苦难一斑……本片根据刘震云的小说《温故一九四二》改编。©豆瓣', '张国立', '冯小刚', 8, 296659, 'tt2113822', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1767278057.jpg', 1.8, 2.2, 19.5, 45, 31.5, '0.026662,-0.147199,-0.735402,0.403732,0.295981,-0.095482,0.794099,0.045203,-0.552178,-0.101836,0.342367,0.702820,-0.403223,0.163681,0.194407,-0.262895,-0.150508,-0.600960,-0.505702,0.140702,-0.144019,-0.135775,-0.515013,-0.198386,-0.107921,0.060676,0.630733,0.522101,-0.377371,0.241584,0.310853,0.232964,-0.156933,0.494790,-0.259998,-0.070982,-0.191100,0.163325,-0.430692,-0.150222,-0.072650,-0.483846,-0.436675,0.317290,-0.257908,0.092857,0.621043,-0.418911,0.031859,-0.086491,0.597069,-0.292627,-0.184586,0.319764,0.264746,-0.213569,0.177464,-0.023934,0.251657,-0.056754,-0.187047,0.109524,-0.831315,-0.200287,0.048160,0.221718,-0.404556,0.510897,0.207809,0.168144,-0.039507,-0.046471,0.229873,0.471385,0.301353,0.513789,-0.229233,-0.242122,-0.348683,0.559746,0.681244,0.105609,-0.516478,0.225214,-0.337271,-0.582611,-0.010247,-0.539261,-0.641343,0.136470,0.402294,-0.148490,-0.174716,0.789428,-0.587977,0.015250,-0.091258,-0.265680,-0.039680,-0.067101,-0.325042,-0.484102,-0.392883,-0.609939,-0.297829,0.246372,0.268237,-0.096992,0.991140,-0.283691,-0.035873,0.481831,0.076966,-0.339689,0.706587,0.152303,0.075000,-0.109005,-0.188151,0.461432,-0.003814,0.537596,-0.001166,0.039380,-0.088023,-0.170761,-0.146689,0.437710', '26647163', '27602116', '24284209', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6011806', '厨子戏子痞子', '喜剧', '民国三十一年，“虎烈拉”横行华北。北平城被日军封城。城外闹瘟疫，城里闹饥荒。流氓（黄渤 饰）饿得不行，蹲在胡同里劫大户，没想到却把两个日本人劫到了一家日本料理店里。店里只有店主夫妇和一个驻店唱戏的戏子。中国店主夫妇，厨子（刘烨 饰）胆小如鼠，厨子老婆（梁静 饰）残疾弱智。戏子（张涵予 饰）颠三倒四，神神叨叨。怎么处理这俩日本人成了难题。为了让其他俩人听自己的，流氓亮出枪，店主拔出刀，戏子干脆摸出来一手榴弹。三人陷入僵局，料理店外，此时日军和城中伪军正在进行全城地毯式搜查。之后事态发展却出人意料，闹剧迭出，情节爆笑百转。几人疯癫闹场的狂欢表象下，“曲线救国”的“愚人谍战”，才刚刚上演……©豆瓣', '刘烨', '管虎', 7.2, 294571, 'tt2645044', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1903751875.jpg', 1.8, 6.4, 35.6, 41.9, 14.3, '0.440253,-0.207269,-0.297517,-0.104417,0.130766,0.002247,0.567285,0.128949,-0.486962,-0.008482,0.210840,0.230509,-0.445922,0.118642,-0.021208,-0.212605,-0.405145,-0.624682,-0.114008,0.141607,0.053565,0.059301,0.040497,-0.251121,-0.286208,0.360731,-0.134676,0.187384,0.076270,0.259799,0.430506,0.134800,-0.449592,0.196139,-0.094193,0.157689,0.261518,-0.309078,-0.059455,0.181519,-0.182624,-0.180263,-0.190766,0.166134,0.186459,0.298566,0.659506,-0.044077,0.153958,-0.224975,0.103256,-0.101641,-0.470456,0.321221,0.413629,-0.246937,0.410752,-0.397448,-0.060464,-0.128731,-0.035025,0.130749,-0.211785,0.268325,0.034446,-0.082503,-0.444949,0.053847,0.065635,0.110531,-0.046632,-0.257518,0.352869,0.268056,0.493018,0.266276,-0.006883,-0.041778,-0.460471,0.387914,0.391359,-0.064764,-0.023773,0.080170,0.386913,-0.148619,0.207913,-0.204379,-0.072123,-0.133649,0.240246,-0.526743,-0.004119,-0.180911,-0.459330,0.029446,-0.132982,-0.156616,0.066193,-0.041109,-0.476626,-0.592552,0.256969,-0.186880,-0.173587,0.196203,0.297713,0.528326,0.320918,-0.134883,-0.317982,0.348260,0.016187,-0.327330,0.259119,-0.043434,0.009114,-0.047371,-0.067820,-0.367055,0.110507,0.407076,0.347916,0.462092,-0.365374,-0.316581,-0.054760,0.123892', '10466639', '1306670', '35206186', '1306449');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6013489', '规则改变', '剧情', '2008年，美国共和党候选人麦凯恩（艾德·哈里斯 Ed Harris 饰）与民主党候选人奥巴马竞争第44届美国总统。竞选中处于劣势的麦凯恩听从其高级竞选参谋（伍迪·哈里森 Woody Harrelson 饰）等幕僚的建议，决定选用一名女性作为副总统候选人以增加其竞争力。一番筛选后，阿拉斯加州长萨拉·佩林（朱利安·摩尔 Julianne Moore 饰）成功获选。然而，入选后的佩林无论是行为举止还是知识涉猎都频频令竞选团队大跌眼镜。虽然经过多次特殊培训后佩林的表现有所进步，甚至帮助竞选团队取得了一些不俗的成绩，但佩林的加入能否力挽狂澜，改变麦凯恩团队的命运呢？本片根据2010年发行的同名著作改编，由2008年拍摄重现2000年美国大选的《选票风波》导演杰伊·罗奇（Jay Roach）执导。©豆瓣', '朱丽安·摩尔', '杰伊·罗奇', 7.8, 5739, 'tt1848902', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1425470942.jpg', 0.4, 1.3, 23.1, 58.5, 16.7, '-0.250003,-0.031059,-0.204451,0.714865,0.161285,-0.317920,-0.187056,0.038860,-0.652100,-0.577620,0.051817,0.721077,-0.431173,0.094024,0.559671,-0.582248,-0.395518,-0.601003,-0.105517,0.043461,-0.079900,-0.726873,-0.533641,-0.291260,-0.205701,-0.446016,1.201751,-0.124091,-0.300904,0.442597,0.368122,0.229411,0.330243,-0.046228,0.338565,-0.393675,0.579699,-0.109508,-0.632943,0.369158,-0.010597,-0.155546,-0.481793,-0.261888,0.430259,0.480595,0.317360,-0.248555,-0.107176,-0.145345,0.719387,-0.052211,-0.119885,-0.036847,0.507104,0.532958,0.064911,0.636134,-0.052515,0.173119,-0.393352,-0.256229,-0.735541,0.042488,0.231612,0.140767,-0.378453,0.234813,-0.216997,0.167705,-0.105069,-0.091043,-0.300301,0.470382,0.394718,0.037473,0.058267,0.221803,-0.136412,0.117341,0.359292,-0.026209,-0.677055,-0.106954,-0.077281,-0.703962,0.169499,-0.684982,-0.053916,0.239280,-0.027301,0.196429,0.560237,0.126140,-0.356973,-0.299668,-0.362566,-0.623776,0.022520,-0.183727,0.275450,-0.848193,-0.431362,-0.032664,-0.184717,-0.436521,0.157201,-0.388955,0.917005,-0.715031,0.145223,0.090642,0.010390,-0.590796,0.619585,0.189550,0.372789,-0.522541,-0.388649,0.106959,-0.063373,-0.245465,-0.249598,0.151864,0.197026,-0.872738,0.020369,0.032046', '25880986', '2369613', '3266509', '386184