INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6013501', '大而不倒', '剧情', '影片讲述了于2008年爆发的全球金融危机，以美国财政部长汉克·保尔森（威廉·赫特 William Hurt饰）为主要线索，记录了在几周之内决定全球最大经济体命运的权力人物的决策与行动。为拯救全球经济，摆脱金融困境，不仅保尔森倾尽全力，美联储主席本·伯南克（保罗·吉亚玛提 Paul Giamatti饰）、纽约联邦储备银行行长蒂姆·盖特纳等人也动用了自己的私人关系和渠道。除此之外，沃伦·巴菲特（爱德华·阿斯纳 Edward Asner饰）、投资银行家、英国监管机构以及几乎所有的国会议员都参与到了这场没有硝烟的金融大战中。本片根据《纽约时报》首席记者及专栏作家安德鲁·罗斯·索尔金的畅销书《大而不倒》改编而成。影片荣获2012年第69届金球奖电视类最佳迷你剧提名、最佳男主角提名及最佳男配角提名等多项大奖。©豆瓣', '詹姆斯·伍兹', '柯蒂斯·汉森', 8.3, 25678, 'tt1742683', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1010261467.jpg', 0.3, 0.9, 14, 52.7, 32.1, '-0.378278,-0.048526,-0.663948,0.666232,0.427898,-0.298476,0.002831,0.164151,-0.449030,-0.395257,0.096612,0.752396,-0.240859,-0.156085,0.522192,-0.324246,-0.442508,-0.702383,-0.199234,-0.056452,-0.038786,-0.522037,-0.504166,-0.188064,-0.259675,-0.328160,0.781901,-0.132959,-0.300271,0.166494,0.424791,0.106836,0.133980,0.062479,0.359977,-0.090803,0.611158,-0.168911,-0.720132,0.506524,0.055157,-0.418604,-0.156494,0.094333,0.369685,0.235296,0.367713,-0.525657,0.320749,-0.085326,0.499363,-0.487803,-0.155620,-0.067997,0.219551,-0.013142,0.290442,0.580123,-0.264826,0.124628,0.128549,-0.274555,-0.893926,-0.172349,-0.043565,0.296462,-0.181129,0.293466,-0.463303,0.152071,-0.339549,-0.088362,0.058894,0.335415,0.250240,-0.011447,-0.058379,0.150551,-0.382149,0.530561,0.016643,0.037230,-0.666678,-0.069673,-0.012331,-0.529704,-0.171873,-0.488810,-0.036677,0.034470,0.477988,-0.058034,0.270609,0.438824,-0.487380,-0.152937,-0.106206,-0.781187,0.044796,-0.193142,0.122535,-1.038148,-0.226133,-0.039596,0.146124,-0.288354,0.270395,-0.279880,0.642554,-0.315631,0.068529,0.229877,0.074284,-0.351081,0.662989,0.033419,0.425391,-0.354179,-0.251128,0.017448,0.020971,0.214146,-0.039432,-0.028338,0.263959,-0.529524,-0.041492,0.346700', '3318306', '26990609', '3077791', '1293692');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6013880', '蔡李佛', '剧情', '英国泰晤士小镇，阳光青年陈家乐（洪天照 饰）在这里求学、打工。他的父亲陈天来（洪金宝 饰）是南拳——蔡李佛拳的传人之一，不仅在家乡开设拳馆，更将这门优秀的传统武术传播到世界各地。理所当然，家乐也得到父亲的一些真传，并因此结识了同样热爱武术的日本青年武田少佐（小杉健 饰）。某天早上，一伙混混大闹家乐和武田打工的餐馆，二人出手阻止，结果反遭老板解雇。此后不久，家乐接受父亲的建议启程回国，武田则出于对蔡李佛拳的向往随同来到中国。与此同时，陈家那间历史悠久却其貌不扬的拳馆正面临一场考验，财大气粗的泛美集团意图收购拳馆，作为传人之一的家乐将如何抉择……©豆瓣', '洪金宝', '黄明升', 3.7, 3737, 'tt1851871', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p894596893.jpg', 42.8, 35.5, 17.9, 2, 1.9, '0.114827,-0.040305,-0.597324,0.344190,-0.092079,-0.126630,-0.020657,0.228809,-0.402369,-0.517178,0.317819,0.820846,0.156371,0.459323,0.304339,-0.176829,0.157535,-0.242953,0.054404,-0.153998,0.077800,-0.311260,0.056072,-0.152019,-0.206171,0.030996,0.446186,0.243012,-0.443832,0.550059,0.267428,0.272263,-0.004287,0.178889,-0.203955,-0.147644,0.241286,0.083428,-0.481785,0.119056,-0.084977,-0.258950,-0.169493,0.120624,0.102991,0.332295,0.278188,0.230663,-0.067228,-0.378312,0.203779,-0.163115,-0.231764,-0.010231,0.579253,0.071611,0.123810,0.282518,-0.002157,-0.104881,-0.136272,-0.158257,-0.498092,0.081737,0.467478,-0.102283,-0.570783,0.352688,0.008444,-0.237862,-0.177016,-0.430476,0.131256,0.447545,0.141627,0.208202,0.046586,0.339102,-0.510948,0.311696,0.763007,-0.239295,0.179775,-0.074610,0.003508,-0.231633,0.328276,-0.250977,-0.148288,-0.070751,0.320445,-0.139081,0.187922,-0.167823,-0.237509,-0.013506,-0.173984,-0.127992,0.346992,-0.262771,-0.078030,-0.862080,0.101447,-0.273065,-0.161187,-0.069688,0.276068,-0.201101,0.795316,-0.837739,0.007801,0.149839,0.358839,-0.503919,0.433673,0.038277,0.080226,-0.351731,-0.426986,0.242724,0.384151,0.194343,-0.272677,0.214541,0.015939,-0.309386,-0.019283,0.160190', '2369613', '25922902', '25721544', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6019180', '开心家族', '剧情', '生无可恋的落魄青年尚万（车太贤 饰）屡次自杀未遂，最近一次被抢救醒来后发现自己竟能看见鬼魂。“烟鬼大叔”（高昌锡 饰）、“爱哭大婶”（张英南 饰）、“变态爷爷”和“吃货小鬼”都不请自来赖上了尚万，形影不离的粘在他身边。尚万求死不能、无奈苟活，还因为与鬼魂交流而频遭旁人白眼，烦恼更甚以往。为了请走难缠的四个鬼魂，尚万动身帮助他们完成在人间未了的心愿。在为鬼魂们奔走的过程中，他与善良的护士妍秀（姜艺媛 饰）渐渐靠近，生活也出现了新的转机。就在尚万庆幸自己终于能摆脱缠人的鬼魂们时，曾被遗忘的一幕幕过往却突如其来的浮出水面。原来，那些鬼魂一直陪伴在他生命中的每一刻，从未曾离开……©豆瓣', '车太贤', '金英卓', 8.6, 188560, 'tt1848926', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p892692364.jpg', 0.3, 1.2, 12.8, 40.8, 44.9, '0.011896,-0.179395,-0.514724,0.140317,-0.281381,-0.358676,0.878850,-0.098483,-0.496660,-0.246063,0.086638,0.518764,-0.317598,0.320905,0.205114,-0.288685,-0.085105,-0.678988,0.025644,-0.077829,-0.306869,-0.102794,-0.322121,-0.203151,-0.221352,-0.378765,0.479395,0.187902,0.149010,0.382718,0.239415,0.087942,-0.518889,0.375667,-0.423990,0.083588,-0.101649,0.127283,-0.057885,-0.116930,0.078738,-0.345373,-0.246558,0.114857,-0.086293,0.080769,0.840565,-0.413982,-0.301635,-0.158902,0.212551,-0.225849,-0.077312,0.174707,0.036826,-0.121896,0.374175,0.105219,-0.048672,0.036663,0.041561,0.149970,-0.613485,0.330909,-0.070050,0.098233,-0.614481,0.192564,0.207617,0.139131,0.225803,-0.450519,0.351325,0.416919,0.089309,0.421114,-0.363444,0.028786,-0.413575,0.258452,0.656108,0.070961,-0.316472,0.609598,-0.052304,-0.216546,-0.001796,0.018337,-0.400629,0.036591,0.111524,0.220643,-0.528918,0.272503,-0.532148,0.059440,-0.340601,0.240973,-0.251115,-0.243557,-0.401172,-0.403893,-0.132853,-0.235912,-0.226709,0.357157,0.015563,-0.336269,0.667289,-0.675702,0.392195,0.351754,0.237217,-0.517855,0.675494,0.129735,0.022748,-0.119072,-0.070491,0.448951,-0.034463,0.249929,0.175122,0.235366,-0.348430,0.136882,-0.462311,0.303914', '21619567', '1417036', '1467779', '2081098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6021916', '温暖的尸体', '喜剧', '他（尼古拉斯·霍尔特 Nicholas Hoult 饰）是一只生活在末世的僵尸，依稀只记得自己的名字里有个“R”。与世俗观念不同，作为僵尸他能够思考，依旧残存着些许生前记忆。R生活在废弃的班机上，喜欢收集唱片和饰品，除了吃人外似乎与常人没有两样。这一日，R和僵尸好友们外出觅食，期间遭遇一伙从隔离区来到污染区搜寻药品的人类。在残忍吞噬青年佩里（戴夫·弗兰科 Dave Franco 饰）的大脑后，R拥有了对方的记忆，由此也对和佩里同行而来的女孩朱莉（泰莉莎·帕尔墨 Teresa Palmer 饰）产生恻隐与好感。他将女孩带回自己的住地，通过数日的相处渐渐取得对方的信任，而美丽的朱莉也让R找回作为人类久违的温暖和复杂情感……本片根据艾萨克·马里昂（Isaac Marion）的同名小说改编。©豆瓣', '尼古拉斯·霍尔特', '乔纳森·莱文', 7.5, 125860, 'tt1588173', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1828783542.jpg', 0.6, 3.9, 32.6, 44.9, 18, '0.324719,0.020700,-0.726736,0.706853,-0.119165,-0.203689,1.185556,-0.090833,-0.562722,-0.408162,-0.011773,0.759364,-0.053688,0.174163,0.048754,-0.058680,-0.390443,-0.599965,-0.004107,-0.211094,-0.196697,-0.464725,-0.667498,-0.206693,0.001805,-0.678980,0.740135,0.004560,-0.431031,0.562009,-0.009602,0.208041,-0.193029,0.430174,-0.430344,-0.016140,-0.098098,0.124983,-0.222416,0.110360,0.084451,-0.095766,-0.085265,-0.073524,-0.006903,0.443193,0.975784,-0.445377,-0.333882,0.050246,0.159448,-0.014428,-0.027260,0.022472,0.068823,0.124467,0.248038,0.216283,-0.224375,0.087026,-0.028213,-0.064387,-0.793910,-0.124005,0.016599,0.367440,-0.506831,0.511550,0.021882,-0.093734,0.196860,-0.377425,0.241669,0.133007,0.111202,0.525687,-0.091491,-0.021013,-0.483322,0.137809,0.635576,-0.109998,-0.416333,0.445400,-0.505760,-0.529939,-0.294363,-0.087053,-0.473799,-0.056434,0.211045,0.328768,-0.230290,0.362308,-0.734574,0.197318,0.054802,-0.225408,0.094626,-0.391051,-0.063291,-0.754232,-0.417152,-0.596703,-0.452642,-0.187183,0.279388,-0.408630,0.883378,-0.948096,0.256896,0.324947,0.296194,-0.474884,0.716800,-0.057247,0.035801,-0.205779,-0.104369,0.486630,0.198065,0.129148,0.075174,0.500478,-0.087502,0.196275,-0.593291,0.649328', '3005387', '21619567', '1467779', '2301363');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6021917', '藏品', '动作', '音浪滚滚，群魔乱舞的夜店内，目睹男友出轨的艾莲娜（艾玛·费兹帕特里克 Emma Fitzpatrick 饰）无意中掣动某开关，致使寻欢场所顿时化作绞肉地狱，无数男女惨遭屠戮，搜尸者（Randall Archer 饰）静观这一血腥残酷场景，并在最终时刻虏走艾莲娜。混乱之中，饱经磨难的阿金（乔什·斯图沃特 Josh Stewart 饰）侥幸逃脱。正当他待在医院接受治疗时，受某富翁之托的警方找上门来，要求阿金在48小时之内找到艾伦娜。无论如何，阿金必须再次返回留下无数梦魇的魔窟，时间紧迫，尝试逃亡的艾莲娜时时处在危险之中。而阿金和警察部队也面临搜尸魔布下的致命陷阱。死神的脚步渐次清晰……©豆瓣', '克里斯托弗·麦克唐纳', '马库斯·邓斯坦', 7, 25645, 'tt1748227', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1723185096.jpg', 1.3, 7.6, 42.9, 35.3, 12.9, '0.009025,0.225638,-0.573017,-0.112050,0.466766,-0.139064,0.601221,0.031186,-0.227559,-0.329581,0.335148,0.125025,-0.231741,-0.151205,0.394456,-0.157956,-0.393993,-0.351795,-0.090594,-0.143264,-0.370401,-0.291627,-0.216465,-0.124010,0.016629,-0.208202,0.507292,0.341191,-0.001042,0.217238,0.103058,0.544096,-0.460892,0.574562,0.160429,-0.008556,0.225493,-0.116750,-0.482564,0.361155,-0.015182,-0.253296,-0.102223,-0.011777,-0.170882,0.120114,0.635176,-0.506867,-0.063664,-0.103573,0.301909,-0.219135,-0.147237,0.077580,0.106244,-0.240585,0.206082,-0.141409,-0.300080,0.147145,0.177667,-0.058662,-0.297727,-0.076939,0.131432,0.140392,-0.073858,-0.191298,0.050109,0.233260,0.240916,0.088162,-0.025701,0.156421,0.397112,0.287682,-0.131670,0.128757,-0.118235,-0.186577,0.396795,-0.187461,-0.307911,-0.153139,-0.149184,-0.201595,0.284444,-0.045551,-0.326528,-0.226217,0.419588,0.328839,-0.268853,0.511306,-0.354354,0.103335,-0.586287,-0.197077,-0.416000,-0.115598,-0.381433,-0.884179,-0.145801,0.184259,-0.040815,0.133498,-0.110598,0.007303,0.242602,-0.451100,0.626946,0.440173,0.258573,-0.004275,0.380126,0.013742,0.381479,-0.122718,-0.016845,0.754881,0.311051,0.515540,0.100006,0.004759,-0.078895,0.193991,-0.330838,0.210065', '3871833', '1309064', '1914923', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6024430', '周末时光', '剧情', 'Russel（汤姆·库伦 Tom Cullen 饰）是一个同性恋者，他在人群中小心翼翼地隐藏着自己，生怕被别人发现他是同性恋。一个周末晚上，参加完朋友聚会的他来到一家Gay Bar寻找一夜情。他遇见了Glen（克里斯·钮 Chris New 饰）。一夜之后，Glen让Russel录下了一段他对性的看法。Glen是个在美术馆工作的艺术家。之后他们又见了几次面，在一起讨论他们的过去，他们的人生，他们对同性恋的看法，Russel也了解到Glen关于同性恋的激进观点。Glen要去美国读书，在告别派对上，他们两人偷偷溜了出来，享受了最后只属于他们两人的时光。第二天，Glen即将离开，Russel得去参加朋友女儿的生日聚会。但在聚会上，Russel又无法停止对Glen的思念，他最终还是决定去找Glen......这部英国电影在2011年3月美国德克萨斯州奥斯丁的SXSW电影节上首映，收获了不少好评。', '汤姆·库伦', '安德鲁·海格', 8.2, 31750, 'tt1714210', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1398423664.jpg', 0.4, 1.7, 19.8, 43.9, 34.1, '0.469356,-0.002277,-0.813059,0.491161,-0.046121,-0.374654,0.696130,-0.055898,-0.569537,-0.090718,0.101537,0.930990,-0.453409,0.371632,0.307195,0.060660,-0.567637,-0.750857,0.109784,-0.423613,-0.386983,-0.423473,-0.025038,-0.163005,-0.117669,0.094719,0.241629,0.110256,-0.027788,0.555308,0.457487,-0.101314,0.077417,0.732487,-0.247480,0.047206,0.030019,0.072684,-0.293242,0.499853,0.242811,-0.419769,-0.468666,0.196104,0.251047,0.287183,0.764122,0.017827,-0.135831,0.186114,0.343875,-0.281024,-0.143899,0.268860,0.422298,0.190898,0.422760,0.242278,-0.090637,-0.016415,-0.172121,-0.082407,-0.352583,0.210927,-0.108745,0.259431,-0.761895,0.854061,0.027776,-0.011522,-0.057424,-0.653810,0.321974,0.346410,-0.006258,0.357075,-0.081678,0.019214,-0.512444,0.352989,1.073066,0.056587,0.179755,0.323198,-0.093599,-0.422218,-0.212521,-0.188413,-0.540206,-0.008813,0.504470,-0.064413,-0.490049,-0.009465,-0.676768,-0.012023,0.056213,-0.478143,0.099690,-0.435001,0.299258,-0.863362,-0.022244,-0.408669,-0.469681,0.078051,0.038434,-0.369504,0.712738,-0.985742,0.268685,0.897705,0.399673,-0.608488,1.093933,0.202571,0.021051,-0.091840,0.214163,-0.003943,-0.077075,0.327486,0.093836,0.507389,0.279417,-0.180469,-0.495778,0.486061', 