INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6030611', '追踪长尾豹马修', '喜剧', '丹（阿兰·夏巴 Alain Chabat 饰）是一位电视新闻记者，为拍摄独家新闻采访巴雅部落头领只身前往巴龙比热带丛林。巴比杜（贾梅尔·杜布兹 Jamel Debbouze 饰），生活在巴龙比当地的小镇，一直被他收养的孩子们称作“撒谎的人”。为了给自己收养的孤儿们还债，也为了证明自己说的都是真话：长尾豹马修确实存在并且救过他。巴布比图作为丹的丛林向导，与丹一起在巴龙比丛林中冒险，经历跌荡起伏，共同对阵邪恶的双面人植物学家老教授赫毛松（弗雷德·特斯托 Fred Testot 饰）。赫毛松为了让自己持续返老还童，他需要通过长尾豹马修带来的神奇兰科植物制作还春水，于是赫毛松不惜一切代价抢走了马修蛋。巴比杜和丹联合巴龙比当地驻军将军鲍彻罗（朗贝尔·维尔森 Lambert Wilson 饰）一起成功救出长尾豹马修的蛋。在马修的帮助下通过最后电视直播，巴布比图成功向他的孩子们证明了自己不是一个撒谎的人；丹也向父亲及电视台的人证明了自己是一个真正的新闻英雄。', '贾梅尔·杜布兹', '阿兰·夏巴', 7.4, 8559, 'tt1723642', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1436142380.jpg', 1.2, 4.4, 36.2, 41.3, 16.9, '0.000611,-0.193720,-0.489981,0.683355,-0.195655,0.006492,0.533270,-0.107744,-0.427393,-0.181026,0.148939,0.687046,0.136807,0.135094,0.051454,0.014358,-0.266383,-0.399888,0.197370,-0.051038,-0.336965,-0.425793,-0.240653,-0.236708,-0.009297,-0.575738,0.525160,-0.138029,-0.099799,0.289574,0.215758,0.418507,0.197288,0.096586,-0.224824,0.034529,0.085144,-0.175614,-0.209465,0.205665,-0.245474,0.067845,-0.132719,0.103367,0.265350,0.269082,0.401562,-0.303990,0.006099,-0.340182,0.053654,-0.165127,0.270445,0.083444,0.167519,-0.131131,0.382023,0.184873,-0.287963,0.068053,0.092561,-0.133395,-1.013636,0.014619,0.202054,0.020716,-0.757177,0.316916,-0.030616,-0.008619,0.252761,-0.113524,0.115886,0.366476,0.082201,0.268717,-0.189126,-0.160360,-0.710250,0.102558,0.684197,0.018569,-0.005313,0.089774,-0.286976,-0.425894,0.020737,-0.245260,-0.192613,0.145671,0.254351,-0.208355,-0.176274,0.200780,-0.491138,-0.157283,-0.324801,-0.236869,0.205913,-0.463339,-0.048893,-0.547754,0.151176,-0.188124,-0.179833,-0.208010,0.119037,-0.604499,0.848656,-0.528585,0.068014,0.735993,0.336435,-0.451794,0.652189,0.083739,0.041186,-0.252005,-0.313229,0.203193,0.504552,0.250193,0.294941,0.194138,0.237133,-0.158904,-0.205515,0.406943', '30163500', '1793491', '3785918', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6037517', '罗马浴场', '喜剧', '大约公元130年，强盛繁华的罗马帝国正处在哈德良（市村正亲 饰）统治的时代，时下罗马人民沐浴之风盛行，公共浴池更是受到广大民众的欢迎。随着奢华之风抬头，浴场设计师路西斯·慕德斯特（阿部宽 饰）那古朴简约的设计风格渐渐受到冷遇。某天，他意外通过公共浴场穿越到21世纪的日本 ，这群被路西斯称为“扁脸族”的人，其先进创新汤文化令路西斯大为羞愧和赞叹。在此之后，他多次穿越时空，将日本浴室中的创新理念带到古罗马，他由此咸鱼翻身，大受欢迎，甚至得到哈德良的赏识和重用。在此过程中，哈德良王朝落下帷幕，看似华而不实的凯奥尼乌斯（北村一辉 饰）成为新的皇帝。路西斯拒绝为凯奥尼乌斯设计浴室，他的命运来到了新的十字路口……本片根据漫画家山崎麻里的同名原著改编。©豆瓣', '阿部宽', '武内英树', 6.5, 13353, 'tt1867101', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2155948771.jpg', 1.9, 11.9, 53.8, 26.5, 5.9, '0.158576,0.378566,-0.564405,0.455556,0.370946,-0.112377,0.384638,0.204635,-0.420265,-0.281228,0.295799,0.669949,-0.246505,0.026242,0.614185,0.038303,-0.681323,-0.268390,-0.084740,-0.042418,-0.368651,-0.129099,-0.163809,-0.219581,-0.262875,-0.512218,0.778256,0.178533,-0.457040,0.271357,-0.081997,0.395605,0.006850,0.109619,-0.159742,0.348587,0.174072,-0.189235,-0.262559,0.032915,-0.512639,-0.107498,-0.358992,0.298949,-0.115731,0.284216,0.383893,-0.406934,0.072703,-0.195318,0.834038,-0.007956,-0.027587,0.092532,0.158352,0.149330,-0.027833,0.339242,-0.038531,-0.020600,-0.025925,-0.298382,-0.562926,-0.062353,0.057631,-0.022835,-0.138269,0.440598,-0.121740,-0.302996,0.114605,-0.292146,0.039614,0.124517,0.442992,0.604113,-0.036987,0.204464,-0.320734,0.030253,0.488387,0.073111,-0.491041,0.136869,-0.268531,-0.312400,0.056159,-0.263333,-0.144675,-0.367885,0.362744,-0.111622,0.392569,0.328323,-0.794799,0.028910,-0.196907,-0.270247,0.400666,0.121345,-0.311989,-0.772454,-0.020630,-0.449128,0.006656,0.002135,-0.049082,-0.168576,0.412925,-0.485644,0.115804,0.468867,0.363957,-0.245350,0.603585,-0.315136,0.008069,0.045128,-0.344759,0.573792,0.139989,0.169822,-0.124250,0.421183,-0.153484,-0.293159,-0.356750,0.478164', '22265121', '20283482', '26275494', '30397916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6037977', '饮食男女：好远又好近', '剧情', '一生只有一次的爱，便是一种纯粹的感情素食主义。唐士哲（曾江 饰）是杭州城内远近驰名的大厨，不仅做得一手好菜，对两个女儿的要求也非常严苛：每周末家庭聚餐必不可少，而且餐桌上摆的一定是素菜。两个女儿唐瓦儿（霍思燕 饰）、唐小兰（蒋梦婕 饰）崇尚一切现代文化，无肉不欢的她们从来对这种家庭仪式都抱着敷衍的态度，对自己各自感情生活也一知半解。唐瓦儿是典型的都市白领，经营着一家高级会所，跟游戏设计师张全（蓝正龙 饰）谈着一场姐弟恋。张全是一个典型的宅男，他所熟悉的世界是一个“一加一肯定会等于二”的程序世界，但这种简单直接的游戏规则在感情中却到处碰壁，让他不知所措。张全的大妈白苹（归亚蕾 饰）外表风骚、讲话口没遮拦，但其实内心寂寞空虚。把张全视为亲生儿子的她，一心想谈成张全和瓦儿的婚事，因此自告奋勇去杭州撮合，没想到过程有如刘姥姥进大观园，正事没谈成却吹皱了一池春水，将瓦儿和张全的关系搞得雪上加霜。张全和瓦儿面临分手，唐士哲突然宣布要关掉“好风水”菜馆。白苹误打误撞参加了唐士哲的餐厅关闭之前准备的最后的晚餐。谁料当最后一道菜上桌，却揭开了一段尘封了半个多世纪的往事，让所有人肝肠寸断。爱情究竟是可有可无的点缀还是终其一生的渴求？于是在这场素食痴恋面前，几个年轻人也都找到了属于自己的爱，和属于自己的那道菜……', '霍思燕', '曹瑞原', 5.3, 13342, 'tt1838515', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1464944471.jpg', 13.7, 30.1, 39.3, 12.4, 4.6, '0.325088,0.111325,-0.594043,0.554093,-0.267351,-0.142487,0.679333,0.228591,-0.441530,-0.198593,0.094686,0.764736,-0.161660,0.291052,0.241231,0.078718,-0.001449,-0.543809,-0.173944,-0.060635,-0.132473,-0.345283,-0.019524,-0.154133,-0.242522,0.067494,0.298957,0.014784,-0.182564,0.217418,0.383426,-0.002110,0.094630,0.278210,-0.157983,-0.116557,-0.060657,0.121859,-0.369066,-0.071078,0.033427,0.036654,-0.226818,0.383628,-0.015186,0.318309,0.364111,-0.139167,-0.353976,0.089439,0.333337,-0.193397,-0.304805,0.169580,0.304941,-0.094911,0.411911,0.159408,-0.171786,0.001328,0.137349,-0.101652,-0.696831,-0.120376,0.184317,-0.141087,-0.549539,0.480161,0.120709,-0.208361,-0.068012,-0.195119,0.202616,0.154925,0.447253,0.641059,-0.009821,0.055659,-0.446991,0.366700,0.662744,0.112441,-0.156070,0.619650,-0.274322,-0.287796,-0.083997,-0.294055,-0.389783,0.066392,0.011373,0.059374,-0.147288,0.050354,-0.632562,0.238664,-0.019855,-0.141914,0.229060,-0.490598,-0.048944,-0.340741,-0.074372,-0.447427,-0.439377,0.190373,0.232578,-0.089365,0.652067,-0.658954,0.074347,0.334786,-0.013590,-0.569072,0.649210,0.451843,0.066384,-0.162836,0.084582,-0.118141,-0.133580,0.017083,0.063007,0.600412,0.112317,-0.182664,-0.334475,0.523661', '30162520', '3230462', '1481233', '1456503');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6038071', '白色：诅咒的旋律', '恐怖', '与当红偶像团体Pure比起来，同为少女组合的Pink Dolls前景一片黯淡，不仅积分垫底，同时还面临着解散的命运。此外，该团体内部也是矛盾重重。领队银珠（咸恩静 饰）出身伴舞，加上年龄稍长，颇为珍妮（陈世妍 饰）、阿琅（崔雅拉 饰）、申智（金美达妮 饰）其他3名成员所不屑。某天，Pink Dolls搬到新的练舞室，银珠偶然在玻璃墙后发现一盒题为“White”的音乐录影带，她为屏幕上那模糊的舞蹈与歌声所感染，而Pink Dolls的老板也从中隐隐感到《White》的魅力，于是将其作为银珠等人的新曲推广。最终，Pink Dolls凭借《White》以及极具魅惑力的舞蹈实现败部大复活，名气也迅速窜升。然而在这一过程中，Pink Dolls的成员仿佛陷入莫名的诅咒之中……©豆瓣', '咸恩静', '金曲', 6.2, 7566, 'tt1984177', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1688740057.jpg', 4, 16.7, 51.8, 21.2, 6.4, '-0.091957,0.294880,-0.561635,0.701395,0.171360,-0.133717,0.596022,0.331547,-0.344821,-0.343969,0.017776,0.550667,-0.190825,0.170726,0.365573,-0.251592,-0.365500,-0.636892,-0.181425,-0.270171,-0.320221,-0.353860,-0.188412,-0.063457,-0.024400,-0.473640,0.691751,0.161668,-0.423573,0.456531,0.341271,0.172530,-0.181364,0.128235,0.140566,-0.108281,0.073498,0.065554,-0.059038,0.049967,-0.251237,-0.251326,-0.174930,0.015546,-0.091699,0.218924,0.768017,-0.374718,-0.014355,-0.186219,0.375538,-0.047038,-0.194422,-0.137184,0.117174,0.327000,0.329137,-0.082438,-0.309882,0.193331,0.137318,-0.137784,-1.037818,0.145875,0.373337,0.155075,-0.329697,0.296487,0.055937,-0.142698,0.168360,0.001991,0.026945,0.222581,0.211967,0.379866,-0.275011,0.058144,-0.422189,0.187197,0.413216,0.304186,-0.262597,0.183338,-0.296091,-0.557942,-0.289602,-0.096543,-0.104018,-0.189109,0.258079,0.426099,0.346480,0.175599,-0.685535,0.004406,0.112830,-0.107122,-0.136010,-0.473348,-0.038691,-0.625092,-0.234223,-0.314453,-0.200067,-0.022720,0.280814,-0.212258,0.998571,-0.885361,0.200068,0.161667,0.145667,-0.187247,0.391609,-0.077398,0.219458,-0.197639,-0.562363,-0.059332,-0.016540,0.085143,0.105101,0.335403,-0.348259,-0.301166,-0.387380,0.338138', '27602116', '24284209', '25880986', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6039412', '时光尽头的恋人', '剧情', '1908年，阿戴琳（布蕾克·莱弗利 Blake Lively 饰）出生了，一晃眼27年过去，曾经那个哇哇啼哭的小婴儿已经长大成人，组建了属于自己的家庭，成为了一名母亲。然而，就在这人生中最幸福的时刻，一场意外的发生让阿戴琳徘徊在生死的边缘并最终幸运的死里逃生，然而，很快，阿戴琳就发现，自己的身体发生了某些奇妙的变化，她竟然不再变老，而是永远的停留在了27岁。拥有永恒的生命这件事听起来很妙，但实际上却充满了痛苦，随着时间的推移，阿戴琳所爱的人们渐渐变老，并最终离开了她，留下阿戴琳一人在这世间，沉浸于无尽的孤独之中，阿戴琳封闭起了自己的内心，不再与外界交往，就这样过了近八十年，此时，一位名叫艾利（米契尔·哈思曼 Michiel Huisman 饰）的男人走进了阿戴琳的生命。©豆瓣', '布蕾克·莱弗利', '李·托兰·克里格', 6.7, 63313, 'tt1655441', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2234995897.jpg', 1.9, 11.6, 46.4, 28.8, 11.3, '0.185788,0.248070,-0.963439,0.396369,-0.203708,-0.454526,1.305385,-0.024255,-0.525418,-0.399434,-0.099053,0.670000,-0.228076,0.387389,0.361623,-0.087597,-0.112957,-0.887597,-0.009408,-0.313368,-0.287413,-0.259943,-0.178718,-0.084405,-0.261791,-0.339685,0.824902,0.448444,0.072945,0.429949,0.191242,0.029096,0.064980,0.566129,-0.244634,0.203548,0.014179,0.327318,-0.100336,0.043825,0.203451,-0.319928,0.049087,0.277816,-0.262370,0.240632,0.608004,-0.601402,-0.340055,0.013360,0.397057,-0.210038,-0.267008,0.125661,0.168607,0.015126,0.005759,0.042520,-0.396228,0.102946,-0.082750,0.101572,-0.802697,0.072178,-0.110614,0.264860,-0.435455,0.550650,0.191832,-0.172685,0.096665,-0.416852,0.211787,0.515357,0.069241,0.439498,-0.716938,-0.055315,-0.489719,0.142493,0.886730,0.043413,-0.596825,0.676832,-0.236305,-0.542405,-0.314359,-0.179171,-0.443476,-0.073338,0.215456,0.576636,-0.327921,0.537365,-0.500577,0.283964,-0.165077,-0.315994,0.057137,-0.467217,-0.146414,-0.153185,-0.417762,-0.522585,-0.506748,0.239628,-0.150899,-0.364013,0.738004,-0.775349,0.526472,0.528218,0.293873,-0.180795,0.563579,0.115565,0.328669,-0.054982,0.119815,0.838954,-0.288910,0.447669,0.087912,0.384442,-0.069304,0.118581,-0.670720,0.717251', '2131640', '25909236', '1292211', '2377539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6040982', '敢死队2', '动作', '再次经历了一番炮火密集的血雨腥风，巴尼（西尔维斯特·史泰龙 Sylvester Stallone 饰）、圣诞（杰森·斯坦森 Jason Statham饰）、贡纳（杜夫·龙格尔 Dolph Lundgren 饰）、比利（利亚姆·海姆斯沃斯 Liam Hemsworth 饰）、收费公路（兰迪·库卓 Randy Couture 饰）和凯撒（泰瑞·克鲁斯 Terry Crews 饰）这几个敢死队的铁哥们正享受大战之后的难得惬意。可是好景不长，某晚教堂（布鲁斯·威利斯 Bruce Willis 饰）找上门来，迫令他前往阿尔巴尼亚噶扎克山区找一架被击落飞机上的保险箱，并确保箱子不会落入敌人之手，教堂还委派麦琪·张（余男 饰）与这群硬汉同行。看似简单的任务实则充满凶险，比利被对手残忍杀害。这已不再是一项任务，而是一场关乎战士们友情与荣誉的战争……©豆瓣', '西尔维斯特·史泰龙', '西蒙·韦斯特', 7, 142032, 'tt1764651', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1604065274.jpg', 1, 6.6, 46.9, 33.8, 11.7, '0.259639,-0.103864,-0.383962,0.447046,0.172456,-0.289551,0.873997,0.074102,-0.185405,-0.238295,0.291751,0.493226,-0.157401,-0.317171,0.298533,-0.057994,-0.486950,-0.501558,-0.053319,0.006692,-0.193067,-0.355079,-0.226679,-0.184460,0.159947,-0.192555,0.369665,0.121346,0.081944,0.575985,0.528613,0.490745,-0.159216,0.317635,-0.048487,-0.133781,0.182777,-0.052375,-0.173041,0.031024,-0.368163,0.055979,-0.298771,0.052172,0.179352,0.242458,0.492374,-0.189126,0.022058,-0.258774,0.055138,-0.229063,0.227824,0.175030,0.185706,-0.037773,0.183485,0.148160,0.114093,0.046656,0.490740,-0.236940,-0.594171,0.159569,-0.120966,-0.118576,-0.318195,0.394066,-0.286067,0.061428,-0.059668,-0.084260,0.009041,0.279974,0.365896,0.106669,0.019010,-0.033060,-0.413551,0.160125,0.444954,-0.105371,-0.065673,-0.035822,0.065686,-0.523135,0.073976,-0.229510,-0.494019,0.079373,0.602378,-0.167217,0.244766,0.305297,-0.780524,0.012838,-0.661047,-0.304375,-0.172935,-0.219573,-0.019413,-1.017284,0.002666,-0.358265,-0.374044,0.292129,0.120628,0.112130,0.327122,-0.441221,0.257985,0.374014,-0.091739,-0.011114,0.301603,0.310038,0.195673,-0.109669,-0.209063,0.301618,0.269805,0.059510,0.111188,0.316299,0.081746,-0.248305,-0.119167,0.477577', '6517421', '10466639', '1316693', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6041191', '听风者', '剧情', '1949年，新中国建立之初。江山初定，百废待兴，和平的表象下没有硝烟的战争早已拉开序幕。败逃台湾的国民党接连向大陆派出特工，伺机破坏。为了应对接二连三的破坏活动，中共成立情报部门701局与敌方展开连番较量。同年10月初，701局控制的侦听局莫名消失，为了查清消失电台的下落，701局负责人老鬼（王学兵 饰）授命代号二〇〇的张学宁（周迅 饰）去上海寻找耳力超群的钢琴调音师罗三耳。结果阴差阳错，学宁找到了罗德小徒弟——耳力同样超群的盲人调音师阿兵（梁朝伟 饰）。阿兵不负众望，不仅通过层层严苛的考试，还在工作中一鸣惊人。在残酷的谍报战争中，阿兵和学宁之间某种情愫也暗暗滋生……©豆瓣', '梁朝伟', '麦兆辉', 6.9, 195266, 'tt2078768', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1400056430.jpg', 1, 6.9, 46.6, 36.4, 9.2, '-0.041246,0.199415,-0.602379,0.543203,0.093548,0.136542,-0.004655,-0.181657,-0.447703,-0.385868,0.262547,0.412372,-0.224683,-0.245746,0.181502,-0.383882,-0.237410,-0.847654,-0.279728,-0.062258,-0.184249,-0.317025,-0.473869,-0.085830,-0.152578,-0.025109,0.755315,0.325852,-0.358040,0.336771,0.221659,0.189025,-0.362328,0.165166,0.120704,-0.195787,0.062869,-0.138874,-0.520366,0.186131,-0.070911,-0.279688,-0.258330,-0.113833,0.061586,0.410041,0.467956,-0.335648,0.138787,-0.318755,0.375831,-0.319576,-0.294437,-0.231768,0.392851,0.355147,-0.006371,0.388614,-0.222642,-0.157820,-0.172046,-0.179831,-0.594844,0.017425,0.249205,-0.011368,-0.125052,0.212209,-0.095122,0.154753,-0.026396,-0.343096,0.257173,0.612374,0.313428,0.293580,-0.244517,0.190875,-0.191745,0.226646,0.503115,-0.047731,-0.256543,-0.158291,0.239543,-0.293620,0.155139,-0.318987,0.050371,-0.100788,0.225811,-0.099483,0.166840,0.289485,-0.579830,0.025023,-0.311330,-0.037999,0.039687,-0.343134,0.035744,-0.828180,-0.221784,-0.064454,-0.169669,0.229731,0.016517,-0.168262,0.494966,-1.004958,0.108049,0.409095,0.146955,-0.317690,0.254746,0.161447,0.189380,-0.281222,-0.153792,0.111421,-0.038333,0.436846,-0.000528,0.289839,-0.118546,-0.321146,-0.183661,-0.019409', '25723905', '2369613', '3266509', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6041199', '太极侠', '动作', '国际大都会香港，残忍冷酷的当纳卡（基努·李维斯 Keanu Reeves 饰）暗中组织地下黑拳，只手遮天。香港反黑组派出卧底潜入其中，然当督察孙靖诗（莫文蔚 饰）率队冲入现场时，却发现卧底早已被当纳卡无情杀害。在此之后，当纳卡四处网罗卓越出众的格斗高手。恰在此时，全国武术锦标赛隆重召开，出自灵空太极门的陈林虎（陈虎 饰）轻松击败夺冠热门，名震全场，也由此引起当纳卡的注意。接受到邀请的林虎赶赴香港，虽然认为用太极赚钱有辱师门，但为了改变师父所在的“灵空观”被拆除的命运和家人的生活现状，他还是选择成为当纳卡旗下的一名选手。在此过程中，誓不言败的绢秀注意到林虎的行踪，一切朝着不可预测的方向发展……©豆瓣', '陈虎', '基努·里维斯', 5.3, 23090, 'tt2016940', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2008239256.jpg', 10.6, 32.6, 42, 10.1, 4.7, '0.153257,0.189805,-0.583301,0.558567,0.013010,0.129567,0.080549,0.023035,-0.455328,-0.307499,0.285105,0.601902,-0.130557,-0.219902,0.361872,-0.137043,-0.031007,-0.786652,-0.225892,-0.213837,-0.090425,-0.342014,-0.349782,0.090913,-0.147709,-0.103364,0.736315,0.414749,-0.689826,0.614346,0.193579,0.452380,-0.309646,0.223389,0.079984,-0.296885,0.198584,-0.036932,-0.415754,0.358004,-0.305010,-0.283318,-0.202455,0.130733,-0.201632,0.338747,0.356241,-0.134605,-0.064348,-0.070649,0.405378,-0.332226,-0.200493,0.058988,0.531523,0.121794,0.060383,0.294725,-0.126087,0.287021,-0.245590,-0.085571,-0.918525,-0.089639,0.507187,0.055909,-0.432313,0.300486,-0.158904,-0.112618,-0.165323,-0.250390,0.232729,0.145865,0.374222,0.087084,0.082154,0.273526,-0.369182,-0.026214,0.805292,-0.059062,-0.064112,-0.210592,0.211033,-0.226641,0.015038,-0.589463,-0.057352,0.158502,0.087678,0.188350,0.242617,0.068265,-0.191713,-0.061677,-0.271835,-0.144592,0.072101,-0.303498,-0.074001,-0.821174,0.010060,-0.142204,-0.174170,-0.070623,-0.035501,-0.316254,0.681183,-0.865431,-0.005225,0.328188,0.296419,-0.553663,0.644731,-0.071250,0.182872,-0.297268,-0.441532,0.227268,0.468711,0.296090,-0.290476,0.186670,-0.134890,-0.549527,-0.142273,0.093171', '4301278', '2369613', '1793491', '24875409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6041200', '钱学森', '传记', '上世纪四十年代，加州理工学院终身教授钱学森（陈坤 饰）因为美国兴起的反共言论而备受打击。他的尖端技术研究被迫中止，并被责令出境。钱学森心系祖国，归心似箭，而意识到钱学森的巨大价值的美方又对其归国设置了重重障碍，甚至以间谍罪逮捕钱学森。最终，宣告无罪的钱学森被长期软禁在家 中。钱学森写信辗转与祖国取得联系，周恩来授命用11名美国战犯飞行员换回了钱学森。面对新中国技术、人才、工业等各方面的空白，钱学森带领科研人员从仿制入手，根据现有技术和条件逐步研究、完善，奠定了中国导弹的基础。1960年11月，第一枚导弹试射成功。1964年10月，第一枚原子弹试验成功，钱学森又承担起了研制火箭运载原子弹进行远程攻击的任务，他带领科研人员克服了天气地理等困难，完成两弹对接，1966年10月在罗布泊靶场成功试射新中国第一枚核导弹！晚年的钱学森对妻子（张雨绮 饰）充满愧疚，但妻子的理解让他倍感安慰。', '陈坤', '张建亚', 7.3, 28075, 'tt2566924', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1421556892.jpg', 1.6, 6.6, 35.6, 35.5, 20.8, '-0.178587,-0.108311,-0.546865,0.478803,-0.012057,-0.096405,-0.046934,-0.094590,-0.523636,-0.064081,0.235229,0.468082,-0.083506,-0.108246,0.054302,-0.119100,-0.452100,-0.347039,0.260547,-0.261508,-0.398699,-0.643804,-0.161758,-0.318373,-0.138025,-0.298247,0.808265,0.139613,-0.085643,0.433616,-0.239329,0.333249,0.325650,0.350790,0.130585,-0.329431,0.076327,-0.119375,-0.444483,0.214550,-0.014132,-0.347685,0.099977,-0.085764,-0.134214,0.325071,0.542723,-0.069194,0.044778,-0.395207,0.311929,-0.431892,-0.190579,0.002257,0.125397,0.561857,-0.367769,0.181449,-0.219489,-0.017414,-0.137758,-0.320654,-0.373505,-0.101324,0.030200,-0.368166,-0.362290,0.444080,-0.508264,0.503873,-0.136563,-0.278776,0.121079,0.566158,0.295591,0.650574,-0.635243,0.238243,-0.118827,0.591834,0.200242,-0.472474,-0.415849,0.017658,-0.212012,-0.515075,0.204729,-0.429001,0.090487,-0.221189,0.116366,0.243581,-0.076460,0.098985,-0.462366,0.238041,-0.461463,-0.377603,0.204468,-0.378601,0.128845,-0.891993,-0.021379,-0.145004,-0.252775,0.067264,0.174610,-0.340143,0.995015,-0.434806,0.091726,0.248288,0.430469,-0.458550,0.284289,-0.041022,-0.091488,-0.305819,-0.063914,0.325184,-0.239137,0.386205,-0.147298,0.133885,0.155693,-0.090484,-0.096200,0.093397', '2369613', '25863940', '5403927', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6041221', '爱情小说', '爱情', '名不见经传的小说作家曲周月（河正宇 饰）正在酝酿创作他的第二部小说，怎奈陷入了文思枯竭的困境。适逢他的出版公司会长要去柏林出差，曲周月便欣然答应一同前往，并充当翻译一职。在柏林的最后一天，曲周月参加了一个针对电影业内人士举办的派对。然而面对故作姿态的寒暄和虚情假意的热情，曲周月觉得厌倦得透不过起来，索性来到外面独自抽烟。就在此刻，他遇见了他今生的缪斯女神。一个名叫熙珍（孔孝珍 饰）的女人默默地走到他的身边，静静地抽了一根烟。这一幕让毫无恋爱经验的曲周月怦然心动，一见钟情。曲周月就这样一发不可收拾地爱上了她。©豆瓣', '孔晓振', '全桂洙', 6.7, 8332, 'tt2300995', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2153427676.jpg', 1.2, 9, 50.9, 29.6, 9.1, '0.153555,0.069939,-0.653429,0.282235,-0.124852,-0.476496,0.385305,0.172017,-0.520874,0.031566,0.267638,0.682862,-0.629241,0.176426,0.533114,-0.204517,-0.353748,-0.670350,-0.000799,-0.466274,0.174600,-0.343591,0.059019,-0.029984,0.114957,-0.041806,0.488125,0.082446,0.184273,0.566914,0.306392,-0.004495,0.174929,0.577474,0.129267,0.159503,-0.127570,-0.109914,-0.258501,0.341781,0.082629,-0.182983,-0.343755,0.019199,-0.026076,-0.049351,0.565059,-0.100770,-0.204427,-0.034598,0.718064,-0.415118,-0.096385,-0.185697,0.279528,0.313590,0.140359,-0.036894,-0.195704,-0.258607,-0.037899,-0.328707,-0.196564,0.445468,-0.196172,0.251478,-0.552394,0.426517,-0.083596,0.164312,0.016053,-0.320233,-0.020003,0.525055,0.242825,0.286388,-0.218234,0.213821,-0.299115,0.606163,0.425286,0.105218,-0.301873,0.303247,0.129964,-0.256263,-0.228731,-0.018809,-0.457006,-0.188306,0.106648,0.228982,-0.250178,-0.119327,-0.222926,0.340439,0.045000,-0.210556,0.359419,-0.251611,-0.219160,-0.760414,-0.089125,0.087703,0.111867,0.029363,0.320377,-0.296848,0.517265,-0.551568,0.350864,0.495597,0.400515,-0.259082,0.633570,0.147801,-0.240292,0.014435,0.013284,0.424128,-0.273635,0.548241,0.119881,0.500677,0.096465,0.148855,-0.435410,0.234778', '1484091', '24751811', '1294565', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6041817', '我们的存在(上)', '剧情', '许多年前，位于北海道的钏路高中，对高中生活充满畅想的女孩高桥七美（吉高由里子 饰）与同班男生矢野元晴（生田斗真 饰）相会。矢野阳光开朗，无论在学习还是体育方面都很优秀，帅气的他在同学中间非常有人缘，甚至传说有三分之二的女生暗恋矢野。最初的反感和误解过后，七美也渐渐喜欢上这个永远阳光的大男孩，可是似乎矢野的心中深藏一段令他久久悲伤的往事，无法坦然面对一段新的恋情。在一个烟花绚烂的夜晚，七美终于鼓起勇气向他表白。两人发誓携手同行，永不背叛，但这条恋爱的路上注定充满了磨难与荆棘……本片根据漫画家小畑友纪的同名原著改编，分两部上映。©豆瓣', '生田斗真', '三木孝浩', 7.4, 21697, 'tt1866931', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1287165814.jpg', 0.8, 4.7, 35.6, 41.1, 17.9, '0.071701,-0.240129,-0.491753,0.676446,0.213854,-0.354567,0.742417,-0.009595,-0.275443,-0.143306,0.127295,0.793553,-0.377122,0.533957,0.303210,-0.166572,-0.338941,-0.715408,-0.043406,-0.255957,-0.141010,-0.476885,-0.137533,0.251571,-0.312224,-0.111391,1.006039,0.183996,-0.065787,0.652950,0.247911,0.155482,-0.141236,0.252696,-0.169276,-0.142448,-0.060938,0.478146,-0.279758,-0.157956,-0.143005,-0.257597,-0.326815,-0.002407,0.021332,0.273906,0.636942,-0.091127,-0.395913,0.236373,0.462059,-0.089703,-0.356125,0.049619,0.277982,0.044009,0.212873,0.196604,-0.075130,-0.204490,-0.272530,-0.064075,-0.311152,-0.018683,0.257763,0.040778,-0.267537,0.636722,0.389522,-0.079627,0.430352,-0.235883,-0.001104,-0.122495,0.316649,0.360907,-0.334838,0.229253,-0.139766,0.279073,0.720837,0.315802,-0.323472,0.471691,-0.405609,-0.261041,-0.279287,0.034459,-0.696832,0.313651,0.064847,-0.034121,-0.103839,0.336855,-0.602513,0.150218,0.133622,-0.034526,0.197856,-0.473522,-0.002370,-0.581497,-0.208755,-0.690430,-0.326226,0.070601,0.136689,-0.350316,1.016333,-0.964708,0.102031,0.208836,0.173367,-0.321913,0.688929,0.378170,-0.136272,-0.209732,-0.058917,0.566395,-0.202865,-0.119274,-0.198038,0.499934,-0.269769,0.017224,-0.637332,0.567280', '25922902', '3811356', '3445516', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6053347', '畸形屋', '剧情', '根据侦探小说女王阿加莎·克里斯蒂同名小说改编的影片《畸形屋》在英国正式开拍。导演吉勒·巴盖特-布赫内，主演格伦·克洛斯、吉莲·安德森、克里斯蒂娜·亨德里克斯、马克斯·艾恩斯、斯蒂芬妮·马蒂尼。故事围绕私家侦探查尔斯·海沃德侦破一桩离奇死亡案件展开。影片将于2018年英国上映。', '马克斯·艾恩斯', '吉勒·巴盖特-布赫内', 6.3, 6908, 'tt1869347', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2514179114.jpg', 1.6, 13.2, 58.1, 21.8, 5.3, '0.324688,-0.206187,-0.422334,0.283184,0.983979,-0.430480,0.627789,0.044465,-0.340523,-0.297310,-0.047818,0.415532,-0.839310,-0.431204,0.595123,0.128049,-1.131991,-0.510156,0.043759,0.028453,0.188929,-0.622150,-0.246226,-0.705650,0.041210,-0.556746,0.384323,-0.376700,-0.055455,0.119621,0.522792,0.643777,-0.199035,-0.420906,0.711246,0.526650,0.794519,-0.387310,-0.704068,0.666599,0.336439,0.231548,-0.216074,-0.220133,0.259437,0.129136,0.594279,-0.243619,0.267937,-0.069073,0.666535,-0.207786,0.021722,-0.131623,0.087818,0.012088,0.011602,0.233141,0.212719,-0.400094,-0.180376,-0.522910,-0.098162,0.095708,0.041033,0.730443,0.238718,-0.171607,-0.805567,0.534245,-0.024350,-0.594174,-0.237988,0.055704,0.548957,0.218152,0.324498,0.299434,-0.237863,0.605196,-0.127469,0.114603,-0.352657,0.124488,-0.272798,-0.653599,-0.316976,0.604218,-0.507733,0.095402,0.662690,-0.617632,0.314415,0.785257,-0.247861,-0.486782,-0.719762,-0.244638,-0.194998,0.033740,0.157025,-1.194822,-0.285637,0.315689,0.013022,-0.544875,0.082505,-0.113063,0.406383,0.016454,0.813813,0.668637,-0.121043,0.439680,0.363671,-0.043025,0.349879,-0.428815,-0.085126,0.922058,0.138144,-0.391334,0.148652,0.269806,0.319687,-0.215104,0.020697,0.558570', '26335580', '34961898', '1293572', '25821461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6053679', '通灵男孩诺曼', '动画', '建立已三百年的懒洋洋小镇，生活着一个能看到鬼魂的小男孩诺曼（柯蒂·斯密特-麦菲 Kodi Smit-McPhee 配音）。可是这种能力给他带来无限困扰，周围的人甚至父母姐姐都认为他是个满口胡言乱语的神经病，只有学校里同样受大家嘲笑的小胖子奈尔（Tucker Albrizzi 配音）相信并愿意和诺曼做朋友。这一天，深居简出且疯疯癫癫的普兰德叔叔（约翰·古德曼 John Goodman 配音）找到诺曼。叔叔也是个通灵者，他告诉诺曼一个重大的秘密，当年建镇之初被人们杀死的女巫鬼魂即将苏醒，届时女巫要携着恐怖的僵尸实现对镇民的诅咒。不久，叔叔死去，而女巫注定苏醒的忌日即将到来。诺曼必须想方设法拯救他的小镇……©豆瓣', '柯蒂·斯密特-麦菲', '克里斯·巴特勒', 7.4, 52385, 'tt1623288', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1587011843.jpg', 0.3, 3.1, 39.2, 42.7, 14.6, '0.076357,-0.262345,-0.423486,0.312321,-0.380106,-0.188588,0.605089,-0.178166,-0.485845,-0.438081,0.088279,0.787921,-0.011491,0.456635,0.441523,0.106152,-0.123667,-0.270024,0.055155,-0.102674,-0.131812,-0.441636,-0.288824,-0.267972,-0.073280,-0.500864,0.463308,-0.007177,-0.017430,0.316083,0.097531,0.209079,0.087565,0.261272,-0.045946,-0.038656,0.048777,-0.197424,-0.159597,0.209429,-0.012681,0.138516,0.089437,0.235072,-0.174548,0.259841,0.284412,-0.445125,-0.193317,-0.294228,0.396685,-0.522091,0.184197,0.220598,0.179252,-0.184955,0.344566,0.268802,0.036582,-0.279868,-0.074381,-0.230091,-0.697398,0.049810,0.066754,0.282187,-0.398192,0.186487,0.189462,0.090641,0.182233,-0.336580,0.312615,0.169801,0.239072,0.525575,-0.219971,-0.114623,-0.681120,0.019386,0.505716,-0.241485,-0.191139,0.149517,-0.089546,-0.237716,0.314890,-0.229378,-0.811494,0.300430,0.041130,-0.063360,-0.309599,0.348048,-0.330315,-0.098491,-0.275410,-0.045264,0.070932,-0.343233,-0.076061,-0.394656,-0.004498,-0.095501,0.022872,-0.067402,0.093706,-0.313941,0.657493,-0.853464,0.537637,0.654131,0.469728,-0.320280,0.435373,0.048978,0.170161,-0.241884,-0.014352,0.345191,0.235369,0.271208,-0.008548,0.107898,0.355204,-0.179107,-0.204404,0.468069', '1793491', '1783461', '3769423', '1299628');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6053731', '超能失控', '剧情', '少年安德鲁（戴恩·德哈恩 Dane DeHaan 饰）就像绝大多数宅男那样，内向、不善言辞，还有轻度的社交恐惧。来自父亲的打骂以及母亲的病重，更让他对周遭的一切充满戒心，成了躲在镜头后面的拍摄狂人，整日陶醉在自己的小世界里。为了替安德鲁的未来打开局面，表哥麦特 （亚历 克斯·罗素 Alex Russell 饰）邀请他出席校园派对。聚会过程中，在表哥好友史蒂夫（迈克尔·B·乔丹 Michael B. Jordan 饰）的建议下，三人进行了一次惊险的野外探洞之旅，并意外获得了自由操纵物体的超能力。这成了他们生活的分水岭——强烈的好奇心与表现欲催促三人不停对自身能力的上限发起挑战，而安德鲁无穷的创意使得他成为了伙伴当中的佼佼者，聚会的明星。可惜好景不长，日渐增强的能力并没有带来幸福，不加节制的安德鲁越玩越过火，终致走向了一条不可挽回的毁灭之路……©豆瓣', '戴恩·德哈恩', '乔什·特兰克', 7, 51477, 'tt1706593', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1376559436.jpg', 1.5, 7.6, 42.3, 37.1, 11.4, '0.157458,0.064438,-0.649000,0.667832,-0.168681,-0.163095,0.808154,0.240834,-0.486021,-0.101191,0.108081,0.583342,-0.243621,0.242665,0.275839,-0.362502,-0.234231,-0.460456,-0.086486,0.052414,-0.215377,-0.406577,-0.285145,-0.284522,-0.258098,-0.498823,0.540620,0.007535,-0.305978,0.294842,0.223790,0.250552,-0.005463,0.575985,-0.008294,-0.076357,0.070626,-0.075948,-0.332231,0.180345,0.025995,-0.139012,-0.084434,0.272415,-0.001630,0.137287,0.751057,-0.316577,-0.078664,-0.324497,0.300603,-0.137663,-0.056388,0.066505,0.125780,0.051017,0.310195,0.142542,0.225694,0.133439,0.066252,-0.134545,-0.777434,0.058396,0.192479,0.179275,-0.408684,0.556257,-0.076463,-0.131378,0.073794,-0.244259,-0.177500,0.123295,0.216505,0.313309,-0.280445,0.016315,-0.255108,-0.009838,0.496469,0.026072,-0.428493,0.410880,-0.393129,-0.244840,-0.009277,-0.138376,-0.620984,-0.108927,0.255904,0.158779,-0.079899,0.472640,-0.617089,0.166017,-0.120318,-0.241369,-0.058029,-0.412898,0.062298,-0.819417,0.032617,-0.408568,-0.183018,0.128292,0.276259,-0.328398,0.619771,-0.788707,0.144196,0.493006,0.261910,-0.433104,0.539089,0.097031,0.122523,-0.238535,-0.146659,0.192621,-0.143949,0.223241,0.028074,0.349291,-0.063037,-0.080277,-0.399053,0.583114', '2334814', '6021916', '3005387', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6057942', '隐秘而伟大', '喜剧', '两年前，朝鲜5446秘密特殊部队派出五星组组长元柳焕（金秀贤 饰），潜入韩国某个村庄担当间谍。元化名方东久，以傻子的身份在一位吝啬的大妈家落脚，他清楚村中每一个人的身世和动向，同时为了不露马脚不得不经常做出一些傻里傻气令人啼笑皆非的事来。随着金正日离世，祖国方面似乎发生些许变化。当年与元互为竞争对手的黑龙组组长李海浪（朴基雄 饰）以及视元为导师恩人的后辈李海真（李玹雨 饰）相继出现在村中。孤独的东久在两位同志面前会稍稍作回自我，而在和“敌国”百姓的相处中，他心中的冰冷也慢慢地发生改变。某天，一道针对5446部队间谍的命令传来，三个年轻人的命运迎来了最严峻的关隘……©豆瓣', '金秀贤', '张哲洙', 7.9, 238707, 'tt2967578', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1947401961.jpg', 0.5, 2.7, 24.1, 47.3, 25.4, '0.197760,0.066041,-0.574657,0.747001,0.155482,0.084078,0.678903,0.124937,-0.667878,-0.552104,0.179137,0.573195,-0.047415,0.249270,0.408712,-0.357320,-0.141422,-0.587994,-0.172065,-0.261670,-0.265395,-0.406216,-0.245817,-0.367109,-0.238185,-0.220978,0.606616,0.249240,-0.146871,0.331560,0.321596,0.527750,-0.210299,0.245865,-0.108361,-0.131198,0.048581,0.021438,-0.314636,-0.025333,-0.026850,-0.204687,-0.136782,0.125550,-0.063028,0.337452,0.665505,-0.230015,-0.447956,-0.288449,0.295436,-0.053710,0.022221,-0.007989,0.507358,0.126944,0.254256,0.332139,0.014964,0.109865,-0.150842,0.010345,-0.748231,0.020390,0.305937,0.292161,-0.419180,0.123284,-0.008335,-0.035391,0.242207,-0.413833,0.253808,0.663144,0.285775,0.250993,-0.455499,0.193175,-0.344651,-0.045150,0.770096,0.084241,-0.237457,0.013417,-0.039026,-0.314689,-0.003764,-0.139370,-0.305815,0.135204,-0.046099,0.005736,0.153230,0.375687,-0.384844,-0.016915,-0.009266,-0.173136,0.211678,-0.318738,-0.174105,-0.489396,-0.055761,-0.444854,-0.118795,0.360898,0.033233,-0.087079,0.741128,-0.820096,0.085045,0.379165,0.203406,-0.513224,0.426134,0.049066,0.188267,-0.391783,-0.156059,0.025064,0.132001,0.157385,-0.147424,0.251825,-0.254057,-0.224128,-0.044387,-0.129549', '1301022', '1293265', '25721544', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6060652', '红灯', '剧情', '心理学博士玛格丽特·麦瑟森（西格妮·韦弗 Sigourney Weaver 饰）擅长用科学的手段分析各种难以解释的超自然现象，对于所谓的超能力更是充满质疑。在助手汤姆·巴克利（希里安·墨菲 Cillian Murphy 饰）的协助下，她们深入乡间，戳穿了一个又一个“灵媒”的骗局。与此同时，曾经在20世纪60~70年代引起轰动的超能力者西蒙·希尔沃（罗伯特·德·尼罗 Robert De Niro 饰）强势复出，引起新一波的热潮。玛格丽特曾让西蒙的弟子的原形毕露，可她始终回避与西蒙的正面对决。一些人的推波助澜似乎要将他们的对决变成可能，但玛格丽特却突然去世。悲愤交加的汤姆决定独自挑战西蒙，他不知道自己即将面对的是什么……©豆瓣', '基里安·墨菲', '罗德里戈·科尔特斯', 6.9, 8919, 'tt1748179', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1553117846.jpg', 1.5, 8.6, 44.3, 34.5, 11.1, '0.643251,0.126876,-0.599568,0.767102,-0.108576,-0.185957,0.638756,-0.020875,-0.549136,-0.547966,0.190581,0.636721,-0.270662,-0.092802,0.133402,-0.190070,-0.253476,-0.537049,0.120694,-0.096089,-0.300094,-0.657832,-0.459100,-0.436531,-0.034246,-0.383636,0.508840,0.068402,-0.504627,0.198071,0.417020,0.699234,0.209902,0.486341,0.147848,-0.096899,0.116684,-0.161580,-0.377082,0.072395,0.255013,-0.137298,-0.345283,0.448791,-0.111873,0.379205,0.311440,-0.555841,0.082266,0.130326,0.376264,-0.304691,0.026776,0.178964,0.241552,-0.273749,-0.024042,0.186719,0.113924,0.018010,0.046435,0.246211,-0.789239,-0.016078,0.038675,0.472956,-0.443308,0.190284,-0.130868,0.013187,-0.136703,-0.171385,-0.115338,0.297784,0.323373,0.296302,-0.043661,-0.115046,-0.306490,-0.024581,0.435042,0.206576,-0.338321,0.264648,-0.352757,-0.513286,-0.226261,-0.204705,-0.519263,-0.051782,0.261661,0.016663,-0.144457,0.383272,-0.490535,-0.187755,-0.448743,-0.085366,-0.073207,-0.355067,0.000155,-0.809428,-0.017059,-0.384953,-0.358703,-0.057853,0.145403,-0.236856,0.622283,-1.027708,0.161421,0.543974,0.146709,-0.258912,0.367600,0.137238,-0.072032,-0.404953,-0.397796,0.356802,-0.015781,0.020235,-0.025872,0.521499,0.508214,-0.206635,-0.029720,0.609615', '1793491', '1420088', '24753477', '1299851');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6061437', '真心话大冒险', '惊悚', '又是一年毕业季，英国某高校大学生聚首进行着毫无底线的大狂欢。期间他们玩起真心话大冒险，羞涩内敛的菲利克斯（汤姆·凯恩 Tom Kane 饰）鼓起勇气向心仪的女孩杰玛（弗洛芮丝·霍尔 Florence Hall 饰）告白，结果不仅被对方婉言拒绝，还遭到洁玛男朋友克里斯（杰克·戈登 Jack Gordon 饰）的殴打和羞辱。时过境迁，某天当年参加过聚会的杰玛、克里斯、保罗（连姆·博伊尔 Liam Boyle 饰）、伊莲娜（珍妮·杰奎斯 Jennie Jacques 饰）和路克（亚历山大•维拉霍斯 Alexander Vlahos 饰）接到邀请，将前往某个偏僻所在参加菲利克斯的生日聚会。谁只等待他们的不是菲利克斯，而是他的哥哥——曾在战场出生入死的军人贾斯汀（David Oakes 饰）。不久，他们得知了一个令人震惊的消息，而这次聚会真正的目的是……©豆瓣', '珍妮-雅克', 'Robert Heath', 5.8, 7789, 'tt1838722', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1683590150.jpg', 6.1, 23.2, 50.2, 15.8, 4.8, '0.286431,-0.101066,-0.713095,0.559146,-0.230340,-0.442788,0.650612,-0.055136,-0.456741,-0.380407,0.083508,0.628447,-0.553694,0.326896,0.538791,0.223395,-0.180419,-0.471631,0.166135,-0.097521,-0.126107,-0.592212,-0.254337,-0.209896,0.170545,-0.092816,0.245984,-0.177478,-0.158346,0.654715,0.714009,0.489600,0.070696,0.419030,0.024287,-0.086267,0.402997,0.196213,-0.257393,0.311798,-0.038080,-0.167030,-0.408954,0.057838,0.269693,0.393705,0.366218,-0.128774,0.172361,-0.074966,0.167198,-0.331887,0.148218,0.326581,0.272817,-0.096273,0.317366,0.211929,0.135527,0.279790,0.084163,-0.333743,-0.215229,0.173710,-0.117879,0.176018,-0.326514,0.554036,-0.346086,-0.114243,0.126742,-0.383379,0.096314,0.472562,0.153007,0.075595,-0.104163,-0.096173,-0.366807,0.195842,0.659939,0.123983,-0.087741,-0.131907,-0.041023,-0.457720,0.248886,-0.009796,-0.516166,0.306761,0.413417,-0.142690,0.015884,0.168163,-0.546423,-0.350043,-0.379517,-0.299978,0.164629,-0.297844,0.008859,-1.003998,0.065828,-0.308503,-0.457739,-0.050354,-0.079280,-0.151035,0.461338,-0.940692,0.319144,0.521277,0.269508,-0.309191,0.433164,0.325161,0.045178,-0.193605,-0.016218,0.365520,0.269948,0.067748,0.015054,0.292165,0.145310,-0.222963,-0.259496,0.350732', '25833539', '3