INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6062731', '亲密敌人', '剧情', '某投资银行的经理戴瑞克李（黄立行 饰）正忙于对某锂矿企业进行收购，而他的前任女友艾米梁（徐静蕾 饰）此时也来到香港，以另一家投资银行副总经理的身份担任该锂矿企业的财务顾问，这对昔日情人即将在职场展开对决。戴瑞克的得力助手瑞贝卡（梁咏琪 饰）试图以好友身份劝说艾米退出，而热门金融博主亨利（李治廷 饰）发现了李、梁二人的过往，原来艾米因戴瑞克事业繁忙，绝少时间陪伴自己而赌气分手，不久却在戴瑞克的安排下，亦加入了投行领域。戴瑞克与艾米在飞往伦敦的航班上巧遇，为了从收购案中胜出，二人连番缠斗，而随着事情的发展，这对儿亲密敌人的关系再度变化……©豆瓣', '徐静蕾', '徐静蕾', 5.6, 61314, 'tt2004211', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1328956552.jpg', 7.2, 26, 50.2, 13.6, 3, '-0.081982,0.139919,-0.651831,0.393725,0.074599,-0.481701,0.516427,0.380324,-0.364783,-0.341534,0.450181,0.573744,-0.271820,0.013488,0.487744,-0.152798,-0.477122,-0.632236,0.320472,-0.129516,-0.057254,-0.439216,-0.315403,-0.183731,-0.124947,-0.052849,0.599458,-0.171138,-0.175380,0.529008,0.606476,0.271885,-0.279709,0.571544,0.115440,-0.216300,0.463266,0.272340,-0.617694,0.243988,0.139134,-0.159832,-0.018786,-0.164956,0.283580,0.437756,0.595035,-0.119328,0.251415,-0.160826,0.265139,-0.354562,0.326745,-0.025339,0.435327,0.195277,0.121152,0.124989,-0.354437,-0.034967,0.008711,-0.251725,-0.368860,0.113574,0.287798,0.337672,-0.402301,0.332211,-0.374612,-0.038828,0.087769,-0.398514,-0.074517,0.577499,0.455273,0.208970,0.028107,0.176031,-0.181783,0.113984,0.433773,0.092940,-0.098963,0.331293,0.037030,-0.230934,-0.137502,0.021800,-0.237499,-0.353451,0.230658,-0.125488,0.359084,0.337437,-0.645523,-0.230405,0.027692,-0.147453,0.239526,-0.254301,0.116287,-0.871428,-0.006893,-0.632395,-0.094371,-0.037216,0.146763,-0.051045,0.203217,-0.723645,-0.037002,0.233299,0.509014,-0.471655,0.664010,0.153079,0.329322,-0.590506,-0.137752,0.226987,0.037592,0.309020,-0.044527,0.070042,0.037859,-0.134190,-0.311350,0.150611', '25723905', '2075345', '1296339', '1968438');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6064183', '海贼王3D电影版：追寻草帽', '动画', '平静明媚的一天，大海上突然传来路飞（田中真弓 配音）撕心裂肺的哀号，原来在他睡觉的时候，他最最钟爱的那顶草帽竟然不翼而飞。了解到草帽的重要意义，草帽海贼团的伙伴们齐心协力帮他寻找。在这一过程中，乔巴等人还救助了一个奄奄一息的老海贼（山口智充 配音）。不久，众人发现一只奇怪的秃鹫叼着路飞的草帽在空中盘旋，于是众人从天上到海上展开了一场大追逐。与此同时，海军也集结了最强大的力量围捕草帽海贼团。为了一顶草帽，空前绝后的战争由此上演……本片为漫画家尾田荣一郎原著《海贼王》第11部剧场版动画，首次采用3D制作，与3D版《美味猎人》同时公映。©豆瓣', '田中真弓', '佐藤宏幸', 7.6, 8835, 'tt1865467', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1597386145.jpg', 0.9, 5.1, 33.4, 36.7, 23.9, '0.027561,-0.066361,-0.824911,0.411705,0.285310,-0.188368,0.720221,0.117195,-0.160247,0.032568,0.544442,0.688495,-0.142031,0.154544,0.266607,0.032697,-0.469064,-0.540076,-0.167583,0.054077,-0.383380,0.029226,-0.464445,-0.176168,-0.156144,-0.322407,0.494775,0.237973,-0.209840,0.574066,0.569567,0.053112,-0.217391,0.396195,-0.254442,-0.031227,0.191522,0.134567,0.048461,0.210875,-0.326118,-0.294707,-0.264335,-0.028761,-0.242373,0.336288,0.850711,-0.374220,-0.030764,-0.159022,0.217274,-0.528546,-0.114373,0.119220,0.580192,-0.002436,-0.203749,-0.186312,0.066896,0.018226,-0.134460,-0.125761,-0.688017,0.061122,-0.179575,0.232294,-0.370726,0.328023,-0.049397,0.015789,0.622128,-0.326897,0.046246,0.131972,0.141264,0.198476,-0.197407,0.467775,-0.428831,0.289925,0.447115,-0.143344,-0.208269,0.227664,0.225747,-0.369267,-0.229259,-0.181033,-0.216396,-0.303998,0.661230,-0.094961,-0.228229,-0.003567,-0.693771,0.206872,-0.005519,-0.574065,-0.024288,-0.088660,-0.451580,-0.668271,0.146695,-0.386538,0.092039,0.312415,0.209252,-0.120121,0.853022,-0.326193,0.162361,0.634038,-0.278946,0.143608,0.323365,-0.005291,0.154299,-0.140864,-0.334715,-0.078263,0.065941,0.406673,0.365044,0.429401,-0.095985,-0.082894,-0.482335,0.352492', '4181031', '27069070', '1856675', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6068516', '东成西就2011', '喜剧', '出生在20世纪最无聊一天的尸体化妆师钟晓明（莫文蔚 饰）对爱情早已绝望，30多岁仍然孑然一身，而父亲阿B（钟镇涛 饰）和自己昔日同窗嘉嘉（黄奕 饰）的老少配婚姻则麻烦不断。嘉嘉接受周董（陈奕迅 饰）主办温拿纪念演唱会的订金后挥霍一空，阿B与钟晓明奔赴广州与周董谈判，于路意外结识梦想成为演员的出租车司机温奇（苏永康 饰）、玩音乐的富二代成玉（谭维维 饰）以及其随从小兵（房祖名 饰），一行人驾车撞上了聋哑白案师傅郑大雄（郑伊健 饰），不料郑大雄死而复生，原来他们几人分别是天龙八将转生，受命教化世人，并与叛徒夜叉展开宿命的对决……©豆瓣', '陈奕迅', '刘镇伟', 4, 55516, 'tt2091885', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1269672877.jpg', 39.6, 32.7, 20.1, 4.9, 2.7, '-0.088290,-0.227814,-0.176464,0.332413,0.065521,-0.321927,0.423776,0.330447,-0.407287,-0.441190,0.287043,0.533537,-0.012882,0.259694,0.388718,-0.177991,-0.257139,-0.579053,0.144423,0.013396,-0.123833,-0.297813,0.127798,-0.165885,-0.111294,-0.015882,0.565007,-0.051306,0.053693,0.808640,0.608015,0.050310,-0.432995,0.159036,-0.154860,0.166923,0.082748,0.242646,-0.432747,-0.126187,-0.224696,-0.216885,0.057330,-0.119712,-0.205362,0.154974,0.625922,-0.170192,0.179740,-0.290555,0.131997,-0.153656,0.069917,-0.135818,0.088598,0.121095,0.422222,0.150734,0.164886,-0.051762,0.013965,0.032384,-0.246990,0.148601,0.143373,-0.010855,-0.327840,0.483931,-0.066167,0.062846,0.065081,-0.210032,0.169568,0.147431,0.320018,0.241668,-0.113636,0.091187,-0.264401,0.544804,0.455275,0.130077,0.227530,0.297638,0.095443,-0.462469,-0.122949,-0.012179,-0.433176,0.175925,0.250312,-0.086152,0.339149,0.108566,-0.537532,-0.161220,-0.065893,0.286900,0.013213,-0.123754,0.238640,-0.697357,0.024482,-0.201761,-0.136590,0.081183,0.177610,-0.036201,0.584368,-0.538055,0.264121,0.080514,0.252197,-0.397757,0.704468,0.000799,0.062860,-0.578481,-0.102166,0.353892,-0.024347,0.041233,-0.072360,0.080497,-0.207617,0.085439,-0.135249,0.196712', '26365262', '3811356', '1780122', '3139191');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6068517', '华丽之后', '爱情', '干劲十足的乐坛天后J（容祖儿 饰），每天马不停蹄地穿梭各类型工作，生活忙得喘不过气。当脱下华丽舞衣，卸下妆容后身心累得一片空白。但对事业充满斗心的她仍希望努力拓展国内市场，令事业再创高峰。在认识了盲人按摩师胡明（胡歌 饰）之后，对生活燃起爱火，对繁忙的工作开始疏离厌倦，经纪人Man（杜汶泽 饰）为保住J的天后位置，激烈反对。R（林欣彤 饰）一夜成名成为乐坛新贵，更被视为威胁 J 的实力新人，对演艺圈的奢靡复杂生活，既向往又惶恐，但却渐与平凡低薪的男友 K（陈家乐 饰） 距离越来越远，无法再维系这段感情……左右她们命运的经纪人Man，利用种种卑鄙的手段，让J和R，从名不经传的爱唱歌的平凡女子，将她们培养成乐坛天后和天才新人，两个原本纯粹喜欢唱歌的女子，命运交错，经历数段刻骨感情的磨炼，重新确认自己的声音，找到自己的爱情。©豆瓣', '容祖儿', '麦曦茵', 5.8, 6184, 'tt2235184', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1594233332.jpg', 9, 23.6, 45, 12.2, 10.2, '-0.081297,0.163371,-0.454867,0.574687,0.056721,-0.111434,0.463540,0.140935,-0.489773,-0.312338,-0.017162,0.522998,-0.198110,0.097668,0.118049,-0.224166,-0.049223,-0.808776,0.097359,-0.019138,0.143971,-0.148718,-0.138311,-0.095426,-0.463185,-0.394276,0.830586,0.228150,-0.109632,0.488573,0.193087,0.000317,0.166920,0.292066,-0.153195,-0.232719,-0.062743,0.278968,-0.525624,-0.014959,0.083463,-0.136460,-0.059933,0.122092,-0.090400,0.058017,0.598308,0.085295,-0.158521,-0.020936,0.521955,-0.248714,-0.188339,0.086584,0.187358,0.133660,0.190248,0.075556,-0.211988,0.032709,-0.073404,-0.028824,-0.787500,0.020019,0.247030,-0.087544,-0.504839,0.587702,-0.042298,-0.290988,0.014106,-0.158737,0.077582,0.147102,0.397259,0.540918,-0.104270,0.333389,-0.238568,0.253867,0.686113,0.214795,-0.289284,0.562232,-0.379300,-0.294054,-0.234071,-0.473954,-0.474057,-0.401957,-0.027240,0.158876,0.040388,0.202544,-0.432806,0.188527,0.028566,-0.055959,0.122126,-0.741118,0.086603,-0.412387,-0.338906,-0.585688,-0.219185,-0.114369,0.225871,-0.453259,0.737022,-0.719081,0.057253,0.325431,0.164819,-0.733228,0.640851,0.314975,0.137374,-0.317171,-0.123675,0.378862,-0.303734,-0.027297,-0.028284,0.193360,-0.376273,0.075126,-0.462430,0.362332', '4301278', '6101834', '25880986', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6070226', '极速蜗牛', '喜剧', '在某个普通的郊外住宅区青草丛内，生活着一群普普通通的菜园蜗牛。这群慢吞吞的小家伙安于现状，朝九晚五，躲避着人类和乌鸦等强大天敌的袭击，享受着来自大自然的馈赠。但是，在它们中间却有一个异想天开的家伙，它叫特伯（瑞恩·雷诺兹 Ryan Reynolds 配音），极度崇拜方程 式赛车手盖·盖尼耶，梦想能够体验风驰电掣所带来的无上快感。在一次意外事件过后，特伯的身体悄悄发生了变化，它拥有梦寐以求的极速，俨然成为一辆蜗牛赛车，并且盲打误撞被带入人类社会。从此以后，印第安纳波利斯的500赛车赛不再是梦想，特伯注定在人类世界书写属于刺激的速度传奇……©豆瓣', '瑞安·雷诺兹', '大卫·索伦', 7.3, 52265, 'tt1860353', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2121756712.jpg', 0.5, 3.8, 38.3, 42.7, 14.7, '0.186268,0.134309,-0.604434,0.679050,-0.147972,0.159217,0.816066,0.158567,-0.363320,-0.158435,0.384404,0.637149,-0.069094,0.039886,0.200691,-0.213489,0.120041,-0.286999,-0.112335,-0.111349,-0.392404,-0.057192,-0.478001,-0.209440,-0.057631,-0.345218,0.629543,-0.108799,-0.541740,0.357181,0.249952,0.161150,-0.266958,0.257643,-0.736905,-0.170083,0.144488,0.141255,-0.320105,0.119869,-0.296012,0.030155,0.110508,0.092137,-0.285724,-0.326059,0.858315,-0.562963,-0.189844,-0.230191,0.264543,-0.280811,-0.113592,-0.112332,0.303939,0.084172,-0.063877,-0.230640,0.400838,0.236603,0.193430,-0.187231,-0.949229,-0.090105,-0.179317,0.208286,-0.437837,0.382093,0.308658,-0.138327,0.196522,-0.233576,0.089047,-0.068235,0.273768,0.492476,-0.167397,0.183027,-0.598699,0.221000,0.691904,0.058869,-0.657789,0.651190,-0.395065,-0.258959,-0.055234,-0.294806,-0.633802,-0.392406,0.340020,0.200498,-0.531692,0.395448,-0.753438,0.318177,0.004428,-0.274132,-0.076952,-0.383183,-0.224651,-0.631543,0.104389,-0.526490,0.011382,0.094070,-0.055137,-0.434033,0.660139,-0.757113,0.446580,0.768717,0.003824,-0.201674,0.565283,-0.296397,0.009930,-0.210933,-0.117872,0.489046,0.072483,0.488086,-0.085427,0.391133,-0.249092,0.248214,-0.474818,0.968068', '1793912', '1308784', '26667010', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6078003', '柳如是', '剧情', '才女柳如是与文人钱谦益的爱情传奇流传了几百年。柳如是（万茜 饰）是青楼的头牌，琴棋书画样样精通，她主张男女平等，关心家国大事。而在政治风波中历尽尔虞我诈的钱谦益（秦汉 饰），身心疲惫，纵情诗酒却又心怀社稷。机缘凑巧，他们以诗为媒，惺惺相惜，因为互相欣赏走到了 一起。然 而，山雨欲来风满楼，巨大的变故随之而来，一个朝代眼看就要沦亡。面临改朝换代，因观察历史的角度不同，钱、柳两人对时局的看法发生分歧，两人的感情出现裂痕：一个远去北上做了清廷的官员，一个南下去追寻抗清的南明军队。繁华过尽，他们又破镜重圆，在红豆山庄过着普通平淡的田园生活。©豆瓣', '万茜', '吴琦', 7.3, 28865, 'tt2460590', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1437356935.jpg', 1.5, 6.2, 34.9, 40.6, 16.8, '0.381816,0.104963,-0.512839,0.627084,0.351111,0.142353,0.860660,0.363357,-0.548035,-0.269091,0.045324,0.465781,-0.224138,0.083429,0.240525,-0.236675,-0.095330,-0.804660,0.126825,-0.046047,-0.070348,-0.277140,-0.125236,-0.369649,-0.558510,0.092727,0.486454,0.505199,-0.008741,0.638446,0.225149,0.011779,-0.280978,0.546309,-0.192916,-0.000491,-0.150596,0.362012,-0.499749,-0.048346,-0.042699,-0.470190,-0.429596,0.156983,-0.193295,0.137780,0.475575,-0.208453,0.006133,0.081034,0.341926,-0.011160,-0.139436,0.194477,0.358530,0.067033,-0.110378,0.329864,-0.009426,-0.038185,-0.084924,0.018783,-0.394173,-0.218304,0.158594,0.304458,-0.379745,0.936991,0.143361,-0.334573,-0.332483,-0.195728,0.228488,0.389022,0.532620,0.262535,-0.120367,0.016513,-0.495651,0.328481,0.748046,0.160128,-0.331013,0.245677,-0.377777,-0.295794,-0.116730,-0.437678,-0.228643,-0.279451,0.249509,-0.287729,0.101393,0.433454,-0.434732,0.191016,-0.102420,-0.025938,0.054945,-0.272871,-0.084727,-0.235835,-0.358396,-0.801048,-0.489870,0.201663,0.196062,-0.220482,0.785694,-0.596218,-0.177440,0.457426,-0.028601,-0.849184,0.586720,0.170449,0.112518,-0.276845,-0.183493,0.478666,-0.391945,0.037102,-0.199727,0.141617,-0.063699,0.155570,-0.141352,0.421338', '25721544', '1389980', '3212120', '27040921');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6080748', '紫宅', '爱情', '祖籍苏州的富家女周彤（佟丽娅饰）和自幼遭父母遗弃的李毅（汪东城饰）是一对青梅竹马的小恋人，经过多年的爱情长跑，两人最终结为夫妇，并在海外生活居住。一晃十年，接连失去亲人的周彤精神方面承受巨大的压力，只得靠药物缓解病情。某天，父亲的律师致电要求周彤办理遗产问题，于是夫妇二人启程返回了阔别十年的家乡。熟悉的古镇和宅邸并未给周彤一些许的安慰，反而让她陷入更严重的精神困扰之中。在此之后，周彤接连看到各种匪夷所思的诡异现象，这幢辉映着紫色幽光的邸宅仿佛正引领她进入万劫不复的恐怖旋涡之中。扑朔迷离的事件背后隐藏着被遗忘多年的秘密......©豆瓣', '汪东城', '潘恒生', 3.4, 9809, 'tt1883400', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2494089833.jpg', 54.3, 28.6, 13.2, 2.2, 1.7, '0.301275,-0.013004,-0.704313,0.557786,0.127070,-0.091186,0.812654,0.157126,-0.699437,-0.404239,0.209826,0.613291,-0.211601,0.572022,0.274352,-0.005984,-0.115031,-0.647931,-0.055998,-0.066438,-0.331799,-0.557580,-0.276351,-0.126249,-0.068237,-0.369984,0.412032,0.359607,-0.162171,0.494828,-0.043424,0.177289,-0.388279,0.434141,0.007919,0.015239,-0.023096,0.275551,-0.352753,0.030611,0.130577,-0.350286,0.064235,0.207578,-0.024060,0.255133,0.649781,-0.190133,-0.439846,-0.095021,0.328979,-0.223303,-0.232829,0.086751,0.260727,0.251692,0.282119,0.281128,-0.512056,0.034829,-0.000628,-0.117703,-0.511958,0.121159,0.204853,-0.114694,-0.479232,0.553537,0.219167,-0.118243,-0.015514,-0.316811,0.083340,0.435323,0.160935,0.513155,-0.341345,0.214063,-0.089332,0.199198,0.768531,-0.066002,-0.454383,0.125344,-0.430104,-0.241876,-0.090717,-0.059363,-0.284842,-0.074070,0.345527,0.344171,-0.147961,0.394906,-0.458002,0.221379,-0.325300,-0.087896,-0.061240,-0.241002,-0.152272,-0.516153,-0.399631,-0.362981,-0.183530,0.181317,0.050883,-0.139930,0.357119,-0.463052,0.367458,0.242559,0.268382,-0.509779,0.442572,-0.051561,0.165183,-0.186397,-0.081196,0.473426,-0.129877,0.228109,0.033877,-0.140564,-0.253309,0.210415,-0.339313,0.331756', '2365260', '1300958', '3014557', '26245360');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6080755', '金钱之味', '剧情', '在白家，谁的话都不算数，唯有金钱，被看做是至高无上的统治者。作为屋子里的女主人，白金玉（尹汝贞 饰）除了不断的想着法子往兜里捞钱外，还和自己年轻的男秘书英作（金康宇 饰）行着苟且之事，除了对金钱的无限欲望外，白金玉对于肉欲的渴求也似乎没有止境。对于夫人的不忠，尹会长（白允植 饰）完全不放在心上，对于他来说，只要有钱，其他的一切都阻止不了他前进的脚步。虽然生在如此腐败的环境中，白家的长女娜美（金孝珍 饰）好像并没有受到太大的影响，而感情丰富的她对于长相英俊的英作渐渐产生了好感。作为母女同时追求的对象，英作不知该何去何从，一方面，娜美年轻的身体吸引着他，另一方面，他又陷入了白金玉用金钱构筑的漩涡中无法自拔。©豆瓣', '金康宇', '林常树', 5.4, 8264, 'tt2106670', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1596917714.jpg', 8.5, 32.6, 43.5, 11.2, 4.2, '0.265505,0.159741,-0.693175,0.706797,-0.232468,-0.172835,0.932875,0.067302,-0.443349,-0.415722,-0.036437,0.433876,0.018686,0.063072,0.015928,-0.014965,-0.125801,-0.600691,-0.240180,-0.093097,-0.172059,-0.507938,-0.114324,-0.185647,-0.277425,-0.237976,0.588233,0.149950,-0.329035,0.106436,0.465940,0.203297,0.160820,0.580208,-0.083423,-0.038080,-0.188413,0.191826,-0.273447,-0.070221,0.080037,-0.203732,-0.101616,0.459121,-0.044936,0.318690,0.432576,-0.666265,-0.061632,-0.235791,0.300201,-0.199733,0.027835,0.198547,0.154995,-0.137096,0.319626,0.134529,-0.227529,0.039923,0.447269,-0.074853,-0.832723,0.037118,0.336792,0.277262,-0.365675,0.430456,-0.011935,-0.399093,0.074394,-0.077118,0.100772,-0.104015,0.167176,0.340646,-0.417715,0.162599,-0.471022,0.110985,0.575962,0.450342,-0.256203,0.429777,-0.451618,-0.490989,-0.062414,-0.290118,-0.512383,-0.300631,0.123194,0.476019,0.173131,0.168313,-0.361036,0.255572,0.086819,-0.263385,0.033830,-0.690150,-0.038976,-0.198271,-0.252825,-0.944200,-0.271231,0.190150,0.365722,-0.363703,0.665618,-0.874810,0.005484,0.259501,0.307954,-0.917397,0.467342,0.181776,-0.009828,-0.214443,-0.727234,0.306254,-0.047466,0.261649,0.086102,0.219597,-0.049544,-0.226502,-0.046038,0.587099', '3670447', '25828521', '1308206', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6080756', '公司职员', '剧情', '看似平凡的五金制造公司其实是一所铜金属一样冰冷无情的杀人公司。池炯道(苏志燮 饰)虽然整日西服革履，却是该公司业绩卓人的职业杀手。他为公司供职十年，没有一次失手，早已磨练出冷血气质和杀人不眨眼的狠心。但遇到来公司“打工”的新人罗勋(金东俊 饰)时，他突然看到了自己当年的影子。在和罗勋一起执行任务时，炯道有了片刻的恍惚。通过和罗勋的家人交流，他越来越感到亲情的温暖，更在遇到心爱的女人刘美妍(李美妍 饰)时，他的职业敏感发生了变化。在执行一次任务时，因犹豫而导致任务失败，这也让炯道第一次萌生退意，但事情远没有他想象的那样简单。一天之内，他从公司最有前途的职员变为公司的敌人，遭到原同事们追杀的“目标”……©豆瓣', '苏志燮', '林相润', 6.6, 17643, 'tt2371486', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1697767512.jpg', 1.1, 9.3, 54.2, 26.8, 8.5, '0.173855,0.089859,-0.714026,0.580757,-0.221810,-0.339352,0.856426,0.140496,-0.462462,-0.433377,0.285383,0.819211,-0.088319,-0.027376,-0.033534,-0.109321,0.013551,-0.623479,-0.076703,-0.253393,-0.149235,-0.417924,-0.006260,-0.273926,-0.046993,-0.161951,0.794470,0.174724,-0.151102,0.386487,0.247406,0.277240,0.094052,0.690347,-0.193025,-0.368904,0.159646,0.475571,-0.130846,0.054176,0.150751,-0.149600,-0.334946,0.244347,-0.078013,0.585242,0.388115,-0.001386,-0.660878,-0.098316,0.502363,-0.206711,-0.128495,-0.282785,0.458256,-0.017091,0.076647,0.143910,-0.190784,-0.077288,0.049678,0.055988,-0.953243,-0.002437,0.152110,0.023962,-0.606988,0.369382,-0.121025,0.057440,0.161067,-0.352458,0.182387,0.458234,0.413665,0.227924,-0.238326,0.168695,-0.423559,0.209621,0.797155,-0.080644,-0.386323,0.560348,-0.251475,-0.409097,-0.090785,-0.296866,-0.262185,0.135301,0.077698,0.131226,-0.440525,0.240408,-0.568361,-0.050357,0.017329,0.040678,-0.117961,-0.415055,-0.198923,-0.567914,-0.104211,-0.404110,-0.605660,0.136941,0.063474,-0.349212,0.459461,-1.039639,0.132419,0.571986,0.245154,-0.603923,0.676956,0.019345,-0.008208,-0.312259,-0.061550,0.043039,0.010691,0.344360,0.161628,0.413962,-0.063609,-0.198540,-0.228689,0.444157', '1793491', '1301022', '1304977', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6080772', '一八九四·甲午大海战', '剧情', '1867年，李鸿章（孙海英 饰）上书，清政府下令建立船政学堂，由洋人讲授西洋海军知识。邓世昌（陆毅 饰）前来报考，得刘步蟾兄妹相助，一鸣惊人。1877年，邓世昌送同学们赴英国皇家海军学院深造。4年之后，邓世昌代表朝廷迎接同学凯旋。他在伦敦街头偶遇刘步蟾妹妹（龚洁 饰），并教训了挑衅的洋人。毕业会上，邓世昌、刘步蟾与伊东佑亨（夏雨 饰）、东乡平八郎的对话，为日后两国海上交锋埋下伏笔。李鸿章组建北洋水师，向光绪帝（郭家铭 饰）启奏向英国定制的铁甲舰，得到了慈禧太后（吕丽萍 饰）准奏。与此同时，日本天皇号召朝野捐俸也购得了铁甲舰，伊藤博文还奉上了侵略的奏章。北洋水师提督丁汝昌（杨立新 饰）率刘步蟾、邓世昌等 “镇远”号、“致远”号将士出访日本，遭遇长崎事件，大战一触即发……©豆瓣', '陆毅', '冯小宁', 5.7, 10086, 'tt5371612', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1598097483.jpg', 16.5, 21.6, 35.1, 16, 10.8, '-0.057650,-0.141832,-0.461445,0.493749,0.592946,-0.109857,-0.127106,0.309347,-0.644445,-0.033741,0.331410,0.405577,0.085091,0.100706,0.428230,0.024818,-0.651383,-0.697496,-0.018274,-0.075488,0.131673,-0.427849,0.102936,-0.250777,-0.259471,-0.280075,0.584424,-0.053618,0.073208,0.763394,0.341406,0.198210,0.372079,0.442999,-0.041667,0.003027,0.066361,-0.005254,-0.325025,-0.068119,-0.370880,-0.390576,-0.263730,-0.341333,0.315921,0.025522,0.472955,-0.156102,0.412111,-0.279007,0.038508,-0.152384,0.165090,0.152911,0.422765,0.507098,-0.085121,0.507923,-0.025953,0.119174,-0.221493,0.084987,0.346926,-0.176235,-0.073145,-0.158023,-0.060442,0.523238,-0.377918,0.352223,-0.111241,-0.199577,-0.064737,0.591825,-0.016695,0.255361,-0.170805,0.300918,-0.109944,0.711309,0.299905,-0.145625,0.253847,-0.446792,0.305812,-0.304710,0.175185,-0.298275,0.022796,0.159929,0.054832,-0.434428,0.389629,0.213097,-0.616694,-0.413193,-0.424383,-0.256254,0.443887,0.188586,0.022518,-0.807920,0.115010,-0.215231,-0.341522,0.080685,0.497721,0.252362,0.570049,-0.155603,-0.174677,0.153563,0.405027,-0.420438,0.645038,0.231548,-0.195879,-0.073862,0.269534,-0.129702,0.036539,0.220896,-0.208457,0.154739,-0.048531,-0.322022,0.033197,-0.089375', '26365262', '1780122', '1293656', '2075345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6080775', '黄金大劫案', '剧情', '伪满时期，时局动乱。关东军如狼似虎，革命组织救国会相机而动。在这片看似晴朗的天空下，绰号小东北（雷佳音 饰）的无业青年游走大街小巷，靠坑蒙拐骗混日子。偶然的机会，他意外得知了一个秘密，关东军将有一批黄金送往防护措施严密的大和银行，而以女影星芳蝶（小陶红 饰）为首的救国会成员决定夺取黄金，进而阻止日本人向意大利购买军火的计划。看在黄金的份上。小东北死皮赖脸要插上一脚。虽然凭借小聪明屡屡得手，可是他也给芳蝶等人带来不少麻烦。而他们的对手——关东军大佐鸟山幸之助（山崎敬一 饰）阴险狡诈，成为他们最大的阻碍。夺取黄金的计划最终能否成功？©豆瓣', '雷佳音', '宁浩', 6.8, 219570, 'tt2393829', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1530053393.jpg', 2.2, 9.4, 43.8, 33.7, 11, '-0.077549,0.277347,-0.608518,0.573849,-0.055039,0.068993,0.130257,0.161417,-0.367138,0.019929,0.243889,0.442987,0.348322,-0.348088,0.162832,-0.007178,-0.223873,-0.563364,-0.029098,-0.085503,-0.353004,-0.322764,-0.574946,-0.412451,-0.089335,-0.260595,0.639667,0.376093,-0.334170,0.216096,0.379008,0.264825,-0.127011,0.246249,-0.095144,-0.251843,0.085235,-0.246337,-0.299970,0.392150,-0.310095,-0.498561,-0.117774,0.075992,0.189089,0.393504,0.601971,-0.239765,-0.074897,-0.198330,0.134319,-0.404791,-0.093627,0.108265,0.286552,0.015835,0.143215,0.083177,-0.239889,-0.149172,0.174314,-0.265142,-0.688053,-0.067473,0.141597,0.081658,-0.472094,0.490464,0.125552,0.240208,0.054717,-0.372559,-0.108875,0.542178,0.192289,-0.097233,-0.160711,0.258983,-0.308478,0.045529,0.385822,-0.157845,-0.107971,-0.084920,0.157072,-0.106154,0.047001,-0.422257,-0.035484,-0.118061,0.382423,-0.182969,0.029454,0.007831,-0.660332,0.022500,-0.264370,-0.170725,0.061769,-0.093865,-0.086786,-0.457206,0.057784,-0.180074,-0.366468,0.368988,0.382133,0.105949,0.737874,-0.538742,-0.088824,0.647344,0.451766,-0.297530,0.345777,-0.076539,-0.099023,-0.236197,-0.293750,-0.208446,0.326732,0.343949,0.192419,0.189898,-0.367679,-0.494000,-0.035460,0.161523', '25928048', '10467125', '27602116', '26921827');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6080840', '回家的路', '剧情', '金宗裴（高修 饰）和宋静妍（全度妍 饰）是一对平凡的夫妇，他们共同经营一家汽车修理店，并育有可爱的女儿慧琳。生活固然快乐，但是不免狂风暴雨的侵袭。宗裴曾给朋友秀载作担保，但秀载上吊自杀，它所欠的两亿巨额债务全部堆到了宗裴的身上。为了尽快还债，静妍找到了宗裴的后辈文道帮忙。文道声称在欧美发现金矿，需要有人带原石回国，并许以丰厚的报酬。静妍信以为真，谁知她却在法国海关被人抓住，并从行李箱里搜出大量的毒品。在此之后，静妍遭到羁押，言语不通的国度里，她不仅承受着巨大的孤独和恐惧，还有随时而来的羞辱与绝望。之后的两年时间里，宗裴为了妻子的清白奔走呼告。妻子的漫漫回家路，渐渐牵扯了所有国人的心……本片根据真实事件改编。©豆瓣', '全度妍', '方银振', 8.5, 50846, 'tt2797106', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2161532134.jpg', 0.2, 0.8, 12.4, 46.8, 39.7, '-0.153038,0.214179,-0.513788,0.696201,-0.011535,-0.184902,0.750623,0.022643,-0.415647,-0.301913,-0.182942,0.667316,0.007886,0.377153,0.120988,-0.014210,-0.001365,-0.425358,-0.164355,-0.230611,-0.464245,-0.387040,0.020899,-0.416192,-0.194579,-0.097836,0.484194,0.400764,-0.098541,0.444600,0.154739,0.265453,-0.213265,0.556697,-0.326062,0.151081,-0.225813,0.210051,-0.297756,0.037588,0.138092,-0.241426,-0.074813,0.162017,0.236574,0.460634,0.590391,-0.128900,-0.053428,0.099183,0.271776,-0.197101,0.202131,-0.005402,0.117928,0.163432,0.340282,0.224746,-0.586636,-0.057398,0.239848,-0.249558,-0.642976,-0.080060,0.247290,-0.136482,-0.549080,0.443521,-0.105274,0.184741,0.095976,-0.039424,0.147309,0.478759,0.150243,0.398492,-0.223665,0.185420,-0.585521,0.213069,0.594178,-0.250722,0.023227,0.149853,-0.221651,-0.378804,0.099532,-0.163689,-0.385061,-0.129056,0.556990,-0.000236,-0.090575,0.183268,-0.596226,0.033425,-0.311996,-0.148326,0.158639,-0.426888,-0.070111,-0.437236,-0.125746,-0.304961,-0.132987,0.177384,0.268851,-0.424518,0.647973,-0.464635,0.110317,0.381709,0.435534,-0.758255,0.590005,-0.192849,0.118742,-0.086609,-0.202054,0.270366,0.267014,0.370018,0.319762,0.011300,-0.146158,0.045001,-0.083220,0.373912', '26678784', '3119246', '27042738', '1299932');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6082346', '小镇怪客托马斯', '喜剧', '青年奥德·托马斯（安东·叶利钦 Anton Yelchin 饰）生活在加利福尼亚某个僻静小镇，当年母亲错把Todd登记成Odd（怪人），以致于他也被人称为怪咖托马斯。不过这个称号对他来说也算实至名归，因为托马斯能够看到幽灵，他时常为蒙受不白之冤的怨灵追查凶手，也由此和警长怀特·波特（威廉·达福 Willem Dafoe 饰）培养出父子般的信任。原本和女友史多梅·卢埃林（爱迪生·蒂姆林 Addison Timlin 饰）过着还算宁静舒适的生活，但某天托马斯发现怨念重重的血灵大量集聚在某个男人身旁，而不久前梦中的可怕场景又让他心有余悸。托马斯直觉感到，一场惨烈的屠杀可能即将到来，他必须想方设法阻止这一切发生……©豆瓣', '安东·叶利钦', '斯蒂芬·索莫斯', 6.9, 8982, 'tt1767354', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2125839056.jpg', 1.3, 8, 46.4, 34.5, 9.9, '0.033936,0.039840,-0.803117,0.421085,-0.228492,-0.144025,0.912929,0.014857,-0.650257,-0.380214,0.209995,0.765075,-0.172357,0.263401,0.416152,0.104941,-0.151198,-0.505369,0.066883,-0.157950,-0.161074,-0.470308,-0.436722,-0.418034,-0.023579,-0.447592,0.276541,0.195351,-0.139820,0.277349,0.218666,0.473243,0.106023,0.500065,-0.129778,-0.026247,0.065511,0.049620,-0.292756,0.041068,-0.033966,-0.133855,-0.068273,0.251558,-0.027312,0.206421,0.454292,-0.375962,-0.545644,-0.216647,0.314244,-0.290563,0.045498,0.276367,0.244958,-0.109527,0.122912,0.085842,-0.039763,-0.151153,0.080637,0.023675,-0.576617,0.294259,-0.166315,0.163442,-0.434012,0.338158,-0.051852,-0.041760,0.179892,-0.199278,0.286075,0.194099,0.429673,0.187811,-0.164079,0.050216,-0.477418,0.115228,0.690327,-0.017214,-0.213468,0.292165,-0.254319,-0.258207,0.014424,-0.091242,-0.373693,0.160014,0.144514,-0.017505,-0.220379,0.257736,-0.150524,-0.012603,-0.295016,-0.049935,-0.307536,-0.371608,-0.105371,-0.545756,-0.266204,-0.312142,-0.280150,-0.056936,-0.124722,-0.525664,0.385755,-0.556774,0.194555,0.654981,0.256785,-0.238870,0.313227,0.176787,0.122265,-0.187443,-0.176007,0.432505,0.286356,0.151477,0.124247,0.224083,0.203302,-0.026456,-0.075588,0.578967', '25909236', '1292217', '1307311', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6082517', '致命弯道4：血腥起源', '恐怖', '寒冷的冬天来到，丹尼尔（Dean Armstrong 饰）、肯妮娅（Jennifer Pudavick 饰）、布丽姬特（Kaitlyn Wong 饰）、让娜（Terra Vnesa 饰）等一众青年男女相约去雪山中度假。谁知他们迷了路，来到了一个完全陌生的所在。寒冷的暴风雪即将袭来，众人无可奈何找到了一幢废弃的建筑暂时栖身。从建筑中留下来的资料得知，这里曾是名为格伦威尔的疗养院，专门用来收容形容怪异、极度危险的边缘人群。早年间疗养院放生了一场恐怖血腥的暴乱，最终废弃不用。青年们在这里纵情欢歌，却没想到还有几个畸形人住在这里。他们似乎并不欢迎这群不速之客。夜幕降临，惨无人道的屠杀悄悄展开，青年们迎来了最为恐怖的假期……©豆瓣', '詹妮弗·皮达维克', '德克兰·奥布莱恩', 5.7, 18087, 'tt1865567', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1200547333.jpg', 10, 25.2, 43.3, 13.8, 7.7, '0.357833,-0.095786,-0.670053,0.121738,-0.005739,0.175244,0.944004,0.056584,-0.604238,-0.503422,0.446290,0.493835,-0.065996,0.440968,0.338659,0.146650,-0.332849,-0.237408,-0.267873,-0.309974,-0.472025,-0.108103,-0.237528,-0.182968,0.088926,-0.194482,0.311413,0.405835,-0.226750,0.639434,0.117408,0.398730,-0.481123,0.514844,-0.379523,-0.283888,0.263930,-0.016998,-0.099472,0.248761,-0.503665,-0.221277,-0.364428,0.184676,-0.027202,0.389707,0.698063,-0.232680,-0.276897,0.106879,0.318654,-0.071495,-0.099028,0.277743,0.333339,-0.396359,0.204378,-0.140785,-0.284228,0.189101,-0.106768,-0.267442,-0.418513,0.456444,-0.130470,0.137111,-0.377465,0.600396,0.322443,-0.367398,-0.009220,-0.160589,0.307685,0.033241,-0.043690,0.321358,-0.051208,-0.041836,-0.314137,-0.014994,0.800679,0.006115,-0.105758,0.137701,-0.225529,-0.277672,0.178021,-0.007329,-0.186102,-0.173085,0.200350,0.190407,-0.092504,-0.070409,-0.981411,0.095741,-0.277652,-0.268290,0.019109,-0.093274,-0.570263,-0.961776,0.096246,-0.108842,-0.098478,0.363555,-0.135054,0.149196,0.474217,-0.634624,0.227635,0.419734,0.185223,-0.209126,0.451526,-0.300642,0.162664,0.095494,-0.197991,0.243053,0.072450,0.544054,0.183108,0.414716,-0.241210,-0.210256,-0.523600,0.416141', '10466639', '2269893', '1853181', '1297659');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6082518', '超凡蜘蛛侠2', '动作', '能力越大，责任越大。蜘蛛侠彼得·帕克（安德鲁·加菲尔德 Andrew Garfield 饰）在全力和犯罪、灾难做斗争的同时，终于迎来了毕业的时刻。可是曾经的一段心结，让他和女友格温·斯坦西（艾玛·斯通 Emma Stone 饰）的关系降至冰点。格温应聘于为全城提供电力的 奥斯本集团公司，同一期间发生的两件事，不由得左右这家公司和彼得等人的命运。奥斯本的掌门人病故，他的儿子哈利（戴恩·德哈恩 Dane DeHaan 饰）以20岁的年龄接受这家市值2000亿美元的巨无霸。另一方面，极度崇拜蜘蛛侠的电力工程师麦克斯·威尔·迪伦（杰米·福克斯 Jamie Foxx 饰）在维修机组时意外身亡，当他再度醒来时发现自己变成了全身充满电能的超人类。感到受了欺骗的麦克斯与蜘蛛侠在时代广场展开对决，而彼得和哈利的友情也将遭到命运的戏弄……©豆瓣', '安德鲁·加菲尔德', '马克·韦布', 7.7, 278285, 'tt1872181', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2179858051.jpg', 0.6, 3.4, 29.7, 44.8, 21.5, '0.257378,-0.049123,-0.775658,0.388012,0.033085,-0.485718,0.660682,0.340722,-0.442758,-0.383294,0.203400,0.985539,-0.403593,0.237395,0.294829,-0.144578,-0.198456,-0.722619,-0.032944,-0.035740,-0.142468,-0.527586,-0.197464,-0.314852,-0.040050,-0.471463,0.620199,0.025837,-0.140028,0.303022,0.383558,0.566024,0.233075,0.486983,0.058924,-0.042119,0.250545,-0.211239,-0.316438,0.323048,0.044915,-0.082913,0.163971,0.157049,-0.141664,0.344282,0.610495,-0.227480,-0.129167,-0.222048,0.391280,-0.313990,0.009451,-0.101916,0.298088,0.036898,-0.050506,0.231572,-0.257135,-0.035296,0.295840,-0.029678,-0.813884,0.003072,-0.004050,0.048847,-0.445568,0.370748,-0.380578,0.035840,0.298001,-0.305726,-0.083774,0.325999,0.184557,0.479326,-0.304039,0.063918,-0.522231,-0.178740,0.484890,-0.013198,-0.351152,0.314938,-0.251850,-0.336017,-0.204221,-0.236131,-0.429454,-0.091073,0.323011,0.168098,0.100775,0.525790,-0.696260,-0.251985,-0.306164,-0.282371,-0.027246,-0.336021,0.030844,-0.732073,-0.189042,-0.415981,-0.108927,-0.133222,0.276559,-0.509614,0.435814,-0.812661,0.164913,0.375281,0.237887,-0.324855,0.569526,-0.018199,0.242570,-0.278778,-0.217291,0.222068,-0.104025,0.239242,0.129650,0.083138,0.171011,-0.021241,-0.133834,0.639717', '1783461', '3006892',