INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6082522', '这里有情况', '喜剧', '曹彼得（吴明轩 饰）是个人物，他是疑似西太平洋大学毕业生、通过百度百科学习超现实主义摄影的摄影师，在一连串求职折戟后，新青年摄影机构的老板（大海 饰）为彼得的不浮夸折服，将其留用。但彼得就是教人不省心，刚到岗就盯上了化妆师Fiona（侯雨桐 饰），他无视先在Fiona身上挂号的竞争者——后期设计师魏查理（杨博 饰），誓把情况做大做强，老板狂风暴雨般的呵斥也不能阻止他了。好花固然堪折，但无论彼得还是查理，始终都是场外选手。Fiona在化妆助理蕾蕾（车玉露 饰）的牵线搭桥下，早已和一名中年男人痴缠三年。彼得情场不得意，但却意外收获了助理GIGI（徐宏亮 饰）的菊花之谊……©豆瓣', '侯雨桐', '教练', 7.3, 6899, '', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1761588899.jpg', 3.5, 7.2, 31.1, 37.4, 20.8, '0.216804,-0.134856,-0.236790,0.568438,-0.220645,-0.245972,0.424939,0.247571,-0.183036,-0.204049,0.293265,0.356592,-0.281064,-0.132556,0.109590,0.093107,-0.264417,-0.655067,0.104326,-0.280166,-0.187901,-0.488435,-0.305924,-0.108284,-0.078758,-0.028485,0.425453,-0.175225,-0.210610,0.257213,0.377614,0.120350,0.272533,0.421838,-0.052187,-0.008436,0.345207,-0.200567,0.048650,0.036984,0.136782,-0.382250,-0.237633,0.132322,0.359783,0.302705,0.396328,0.016290,-0.101391,0.090754,0.231796,-0.042041,0.187534,-0.067378,0.231459,-0.197322,0.138669,0.071029,-0.039127,0.266788,0.145618,-0.041739,-0.572695,0.219852,0.157387,0.148364,-0.589362,0.318147,-0.388555,0.046720,-0.053741,-0.329573,0.125573,-0.081550,0.197194,0.419068,0.186927,0.109663,-0.494560,0.523897,0.347349,0.394375,-0.231255,0.331240,-0.271402,-0.340074,-0.083216,-0.083840,-0.519575,-0.024589,0.236743,-0.224417,0.059847,-0.154142,-0.212202,-0.170870,-0.166794,-0.038981,-0.269773,-0.239207,0.049163,-0.513811,-0.071541,-0.330879,-0.326376,-0.110452,0.164200,-0.263813,0.813460,-0.786467,-0.079908,0.374362,0.139685,-0.355931,0.830843,0.003499,0.093149,-0.088597,0.022118,-0.199943,0.092774,0.198310,0.141627,0.587524,0.099872,-0.526665,0.110974,0.236736', '6101834', '3230462', '1908036', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6083109', '蛋炒饭', '剧情', '上世纪七十年代，老北京胡同里住着三个孩子，王大卫、李红兵、苏茉莉，三人青梅竹马，一起从小玩到大。大卫（黄渤 饰）祖上是宫廷的御厨，公私合营后父亲在国营饭店掌厨，一身的绝学最终遗憾地带到另一个世界。大卫子承父业进入饭店，却因做了一个糟糕的蛋炒饭只能干些打扫的工作。时代沧桑巨变，社会越来越开放，人们都在这浮躁的气息中寻找明天的出路。红兵和茉莉相恋，最终却分手外出闯荡世界；怀有身孕的茉莉终究不愿接受爱恋自己的大卫，转而南下追寻心中的明星梦。借着新政策之力，大卫承包了国营饭店，开始干出一番事业。时光流转，旧日的好友你来我往，从不驻留，用各自或明或闇、光怪陆离的人生装点着这飞速变幻的离奇世界……©豆瓣', '黄渤', '陈宇', 7, 30790, 'tt2752028', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173334511.jpg', 2.1, 8.7, 40.8, 34.7, 13.7, '0.190656,0.220362,-0.700997,0.596584,-0.021939,-0.488982,0.671570,0.328677,-0.444781,-0.233004,0.030119,0.545091,0.007777,0.569192,0.208148,-0.157016,-0.322934,-0.472950,0.100416,-0.217407,-0.072107,-0.392453,-0.120531,-0.104346,-0.122869,0.046377,0.498493,0.287972,0.136095,0.178468,0.231670,-0.087506,-0.235207,0.352802,-0.196954,0.024446,0.163150,0.137885,-0.472553,0.000692,0.054485,-0.078977,-0.144629,-0.162047,0.083978,0.232555,0.681136,-0.070358,0.041255,-0.270047,0.446247,0.295995,-0.308625,-0.167350,0.263328,0.175212,0.224155,0.259202,-0.068739,-0.084428,-0.149839,-0.051964,-0.466828,0.126197,0.376386,0.094704,-0.578570,0.280430,0.217273,-0.138587,-0.149859,-0.396503,0.083852,0.205969,0.471321,0.460415,-0.069193,0.271290,-0.334004,0.310066,0.627306,-0.063767,-0.108734,0.307691,-0.375953,-0.024699,0.125100,-0.095353,-0.524980,-0.250270,0.084483,-0.044944,-0.215609,0.392360,-0.657850,0.193112,-0.013685,-0.110157,0.256475,-0.185073,-0.170716,-0.593469,-0.109287,-0.316157,-0.258236,0.098532,0.172684,-0.040714,0.522388,-0.521459,0.109685,0.376216,0.163246,-0.354420,0.752723,-0.094853,0.325333,-0.314446,-0.065948,0.514191,-0.369096,0.306416,-0.048208,0.478156,-0.180155,0.192863,-0.430177,0.460888', '3055049', '2334814', '1291835', '20645098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6091398', '啄木鸟和雨', '喜剧', '宁静的山村进入雨季。村中的老伐木工人岸克彦（役所广司 饰）为人古板，与儿子关系紧张。他在上工途中给东京来的新人导演田边幸一（小栗旬 饰）和副导演带路，由此被拉入一部丧尸电影的外景拍摄。在被迫充当临时演员后，克彦竟对电影产生了微妙的兴趣，他开始不请自来的帮助摄制组与村民沟通，开展工作，甚至忽略了本职与妻子的忌日。突然闯入的摄制组扰乱了山村的平静和克彦的生活，也改变了导演幸一自身。幸一生性腼腆缺乏自信，在摄制组中毫无威信。偶然间他发现自己的丧尸剧本竟为克彦所欣赏，不禁大受鼓舞，两人在数次的泡澡时间里进行了奇妙的沟通。在克彦的帮助下，幸一慢慢树立了自信，电影拍摄也步入正轨。然而临关机前的一场瓢泼大雨再次令拍摄陷入危机，克彦的缺席也令幸一惶恐无措起来……影片获第24届东京国际电影节评委会大奖。片中两位主演役所广司和小栗旬在现实中亦均担任过导演。©豆瓣', '役所广司', '冲田修一', 7.8, 14499, 'tt1867566', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1452248297.jpg', 0.3, 1.7, 24.3, 53.3, 20.4, '0.021255,0.004484,-0.750359,0.475298,0.241716,-0.269461,0.674628,0.317263,-0.351718,-0.133296,0.243147,0.704738,-0.413004,0.221647,0.494515,-0.277368,-0.623977,-0.617520,-0.336954,0.185812,-0.115832,-0.215869,-0.308456,-0.146661,-0.155155,-0.447305,0.758474,0.283615,-0.366763,0.569357,0.313243,-0.034661,0.010684,0.509733,0.130037,0.214321,0.106336,0.091434,-0.304297,0.182123,0.013044,-0.429576,-0.446646,0.123303,0.290620,0.558941,0.771469,-0.129848,-0.592843,0.165974,0.439340,-0.237484,-0.125393,0.090615,0.313984,0.235886,0.094846,0.084373,-0.256391,0.251537,-0.287041,-0.124547,-0.682307,0.169723,0.015239,0.140017,-0.392678,0.452408,0.069409,-0.006971,-0.009416,-0.229341,0.131859,0.378663,0.284727,0.437498,-0.213813,0.100931,-0.012390,0.432453,0.618460,0.020420,-0.301487,0.552287,-0.192177,-0.419281,-0.160267,-0.175772,-0.487213,-0.057459,0.179949,-0.136603,-0.064729,0.089696,-0.535505,-0.076637,-0.006122,-0.256151,-0.176514,-0.254360,0.039381,-0.958890,-0.107014,-0.124061,-0.164253,0.032575,0.223431,-0.337126,0.737629,-0.772633,0.218073,0.489521,0.165539,-0.245939,0.605254,0.037313,0.031120,-0.274522,0.020683,-0.026109,-0.074065,0.537136,0.210271,0.382887,-0.310077,-0.107116,-0.384301,0.165507', '3811356', '2369613', '20274039', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6097775', '艺术家', '剧情', '1927年，乔治·瓦伦丁（让·杜雅尔丹 Jean Dujardin 饰），是默片的最佳男主角。每次他在舞台上，都会逗得观众捧腹大笑。他的爱犬是黄金配角，其他女演员只有靠边站的份。一次，面对媒体采访，他无意中邂逅了一位表现欲超强的女子佩皮·米勒（贝热尼丝·贝乔 Béré nice Bejo 饰），尽管后者抢镜出风头，但是他还是儒雅以待。不过，这则头条新闻却压过了他的新戏，老板极为不满，老婆也醋性大发。后来，佩皮闯荡好莱坞，恰好与乔治重逢，这令他心神不宁，演戏频频NG。后来，与老板闹僵的乔治，决定自立门户，自编自导自演。与此同时，佩皮却借助有声电影的契机迅速蹿红，成为了首屈一指的明星。最终，他的默片与她的有声片档期撞车，一场在新与旧、情感与票房的争夺战拉开序幕……本片获69届金球奖最佳音乐片/喜剧片，让·杜雅尔丹获最佳音乐片/喜剧片影帝，及 64届戛纳影帝。', '让·杜雅尔丹', '米歇尔·阿扎纳维西于斯', 8.4, 93079, 'tt1655442', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1341276735.jpg', 0.4, 1.3, 15, 46.8, 36.5, '-0.140965,-0.080682,-0.646206,0.750667,0.149180,-0.138110,0.716558,0.151012,-0.409883,0.069939,0.156263,0.923561,-0.700688,0.144459,0.522618,-0.083280,-0.207362,-0.585475,0.042912,0.057251,0.238830,-0.152013,-0.592480,0.037404,-0.359284,-0.255873,0.832496,-0.011135,-0.323318,0.373634,0.754187,0.073666,0.246902,0.347944,0.063873,0.171183,0.109037,-0.007971,-0.232697,0.316722,0.205040,-0.414523,-0.355979,0.227276,0.293389,0.225236,0.355817,-0.100717,0.115357,0.284673,0.527121,-0.291468,-0.008908,0.082139,0.165390,-0.186609,0.441455,0.054352,-0.099314,0.046947,-0.086549,0.040645,-0.680931,0.220217,0.085117,0.040478,-0.405138,0.535581,-0.054417,0.111519,-0.113661,0.065008,0.201095,0.272590,0.306242,-0.012926,-0.027864,-0.047856,-0.303089,0.535334,0.535120,0.356165,-0.242622,0.564623,0.001321,-0.570670,-0.250491,-0.481142,-0.493570,0.182252,0.563131,-0.219516,0.166685,0.222182,-0.282328,-0.178753,-0.186836,-0.126787,-0.092168,-0.332427,0.059810,-0.677483,-0.100812,-0.364529,-0.183826,-0.260725,0.126159,-0.430307,0.647505,-0.682989,-0.010466,0.475693,0.051026,-0.284812,0.830445,0.182532,0.080129,-0.246208,-0.241533,0.016043,-0.128386,-0.061707,0.073579,0.372882,0.111947,-0.386333,-0.143671,0.481923', '34890458', '2338019', '34795703', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6101728', '租赁猫', '剧情', '美丽善良但举止性格多少有点儿怪异的小夜子（市川实日子 饰），和一群可爱的猫儿独自生活在近郊的旧宅中。她似乎天生就有招猫喜欢的气质，而她也如两年前去世的奶奶那样对这群可爱的小生灵格外疼爱。无忧无虑的小夜子，每日里将猫儿们装在小拖车内，便沿着河岸行走，边唱着独特的 “租赁猫”吆喝声。在这一过程中，她先后邂逅了家境殷实但孤独寂寞的老妇人吉冈寿子（草村礼子 饰）、独自赴任东京长达六年的中年人吉田五郎（光石研 饰）、在某租车公司打拼十二年之久的分店店长吉川（山田真步 饰）以及混迹黑道的中学时代同学吉泽茂（田中圭 饰）。慵懒炎热的夏日，以及随性自由的小夜子，和她的猫儿们见证着世间百态，喜怒哀乐……©豆瓣', '市川实日子', '荻上直子', 7.3, 8168, 'tt2246953', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1393566996.jpg', 0.6, 4.1, 39.4, 39.7, 16.2, '0.129705,-0.007691,-0.429873,0.386749,-0.289833,-0.113634,0.664696,0.271138,-0.553537,-0.244414,0.179286,0.554072,-0.001390,0.724914,0.054624,0.120690,-0.055324,-0.371594,-0.409343,-0.131403,0.156426,-0.112545,-0.250988,0.017705,-0.209045,-0.130603,0.434070,-0.034004,0.140598,0.660816,0.122116,-0.090277,-0.220506,0.125749,-0.490361,-0.022645,0.006238,0.333626,0.178328,-0.195353,-0.248126,-0.123407,-0.233163,-0.396840,0.165360,0.227144,0.830690,-0.409266,-0.254406,-0.231012,0.428725,0.093698,-0.050222,0.390848,0.282818,0.046389,0.363258,0.038136,-0.446441,0.053575,0.126636,-0.221547,-0.234530,-0.011970,0.048552,0.185912,-0.520841,0.468694,0.188451,-0.485639,0.417016,-0.454281,-0.113083,0.044851,0.255549,0.391814,-0.135321,0.220303,-0.276601,0.191707,0.493512,0.138784,-0.398729,0.327306,-0.357326,-0.336784,-0.096742,-0.349429,-0.538417,-0.297113,-0.063199,-0.316966,-0.221847,0.287807,-0.677673,0.459594,0.225345,0.058616,-0.000301,-0.071983,-0.450263,-0.744505,0.153363,-1.068069,-0.337860,0.226007,0.391384,-0.084952,0.889801,-0.723043,0.297569,0.407692,0.175342,-0.014826,0.561387,0.079238,0.019310,0.080018,-0.005164,0.358784,-0.070082,0.321838,0.104258,0.695175,-0.590806,-0.056714,-0.485081,0.546533', '25928069', '24839498', '3811356', '2361269');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6101834', '与时尚同居', '喜剧', '时尚杂志编辑周小辉（周渝民 饰）天赋才华，入职三年就坐上了副主编职位，却引发一手培养提拔他的杂志主编Alex（谭咏麟 饰）嫉妒。Alex耍手腕逼迫周小辉辞职，不甘心的周小辉试图带领手下精英另立门户，然而，只有一个不靠谱的编辑助理以及整天一身运动服、毫无时尚气质的素颜干物女英红（徐若瑄 饰）愿意追随。周小辉说服了好友——煤老板之子武阳（乔任梁 饰）出资，又召集了以拍摄时尚大片为梦想的农村土鳖摄影师（王太利 饰）等人组成新团队，创办新刊与老东家对垒。然而，这群乌合之众组成的团队既不专业又不靠谱，作为精英的周小辉再怎么努力，还是难以在圈中立足。就在周小辉绝望之际，英红的意外表现却唤起他的灵感，为杂志的定位找到方向。在团队成员的共同努力下，周小辉的理想在众人追寻梦想的过程中一点点实现……©豆瓣', '周渝民', '尹丽川', 5.6, 25897, 'tt2106763', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1230850024.jpg', 8, 25.5, 48.3, 14.6, 3.5, '0.045377,-0.003461,-0.383014,0.672597,-0.145099,-0.249683,0.113748,0.297363,-0.306559,-0.247293,0.214030,0.456309,0.101286,0.225164,0.158708,-0.349391,-0.271546,-0.820048,-0.047615,-0.012380,-0.137256,-0.249730,-0.242947,-0.277345,-0.103817,-0.232359,0.918652,0.147808,-0.267171,0.296241,0.433667,0.288070,-0.170471,0.174693,-0.066060,-0.126382,0.290808,0.004070,-0.101325,0.101727,-0.328553,-0.351006,-0.167141,0.008687,-0.021486,0.235060,0.568667,0.041262,0.048378,-0.024185,0.449585,-0.071870,-0.042482,-0.236814,0.177005,0.223902,0.210622,0.109219,-0.081915,0.040587,-0.095509,-0.168184,-0.897156,-0.098765,0.334429,0.237535,-0.740401,0.548437,-0.096942,-0.297275,0.071644,-0.172198,-0.177448,0.077225,0.242089,0.399075,0.103363,0.299854,-0.273461,0.503904,0.308319,0.180015,-0.234045,0.161863,-0.144883,-0.341669,-0.011912,-0.185240,-0.352302,-0.278949,0.073303,0.078949,0.325098,-0.078429,-0.516487,0.239071,-0.045515,0.079240,0.141307,-0.403156,0.064654,-0.502914,-0.011059,0.079344,0.000905,0.098577,0.247328,-0.297808,0.850750,-0.681001,-0.089342,0.259535,0.174155,-0.540144,0.751985,0.050631,0.042595,-0.311861,-0.061590,-0.118746,0.102948,0.226426,0.057738,0.242777,-0.196667,-0.305029,-0.269606,0.333500', '25880986', '27602116', '26759820', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6110546', '安娜·卡列尼娜', '剧情', '为了说和花心的哥哥奥布朗斯基（马修·麦克费登 Matthew Macfadyen 饰）和嫂子多丽（凯莉·麦克唐纳 Kelly Macdonald 饰）濒临破败的婚姻，美丽贵妇安娜·卡列尼娜（凯拉·耐特丽 Keira Knightley 饰）乘坐火车来到莫斯科。她在当地邂逅骑兵军官渥伦斯基（亚伦·约翰逊 Aaron Johnson 饰），后者风度翩翩，英俊迷人，令多丽的妹妹凯蒂（艾丽西卡·维坎德 Alicia Vikander 饰）神魂颠倒，也让已为人妇的安娜心中若有所动。忌惮周遭的风言风语，安娜压抑内心的情感，乘夜返回彼得堡的家中。醉心名利的丈夫亚历山大·卡列宁（裘德·洛 Jude Law 饰），似乎全然无法体恤妻子心中的苦闷。未过多久，渥伦斯基尾随来至彼得堡，安娜再也无法闭锁那充满爱火和渴望的心门……本片根据文豪列夫·托尔斯泰的同名经典名作改编，荣获2013年奥斯卡最佳服装设计奖。', '凯拉·奈特莉', '乔·赖特', 7.2, 77429, 'tt1781769', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1710344576.jpg', 0.9, 5.3, 38.5, 41.7, 13.6, '0.285072,0.004088,-0.714933,0.452479,0.340910,-0.463241,0.885330,0.267923,-0.347414,-0.285244,0.161058,0.488425,-0.180719,0.085298,0.549117,0.502109,-0.732192,-0.559539,0.207507,-0.242586,0.275116,-0.374203,-0.033717,-0.100160,-0.088589,-0.416713,0.409591,-0.196095,0.173181,0.665847,0.378847,0.510593,0.109877,0.171608,0.323964,0.129771,0.289290,-0.460984,-0.464148,-0.023158,0.137001,0.017923,-0.154115,0.172523,0.079390,0.143188,0.461607,-0.357958,0.316829,0.103744,0.339240,0.141278,0.475680,0.164028,-0.142292,-0.218380,0.035306,0.022216,-0.256010,0.156464,0.202012,0.074099,-0.316724,0.304951,0.123242,0.077746,-0.297835,0.429018,-0.483988,-0.024445,0.182475,-0.206282,-0.140259,0.071681,0.032879,0.225551,-0.106584,0.188927,-0.354394,-0.066961,0.252987,0.284995,-0.354097,0.244033,-0.366803,-0.218867,-0.056120,-0.091516,-0.907149,-0.103711,0.305639,0.105662,0.354141,0.458846,-0.353661,-0.359464,-0.558835,0.164398,0.026734,-0.086425,-0.110147,-0.488105,-0.268436,-0.441463,-0.199644,-0.289390,0.102299,0.053484,0.491623,-0.583365,0.213793,0.260098,0.194993,-0.064400,0.393290,0.152446,-0.003899,-0.160188,-0.368966,0.980679,-0.129648,0.050715,0.017902,0.365683,-0.043030,0.070373,-0.195424,0.564692', '489689