INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6110563', '不怕贼惦记', '剧情', '老裴（吴刚 饰）与家人枯守无人荒漠十年，为的是捍卫他发现的金矿，而十年来一直有金主欲买走该矿，而老裴迟迟不肯答应，金主盛怒之下派出杀手“解决”老裴，同时老裴与金矿的信息不胫而走，引起各路人马奔向荒漠。炒房三剑客：西风（应采儿 饰）、六条和八筒首先发难，借麻将局试图瓦解老裴与妻子秀嫂（岳秀清 饰）的互信，反被技高一筹的老裴赶出门去。导演灯哥携剧组与地质学博士张青和其病弱的女友月月先后赶到，两组人马拿出美人计和专业地质知识，试图在老裴的矿中得到蕴藏金子的切实证据。老裴、妻子和儿子小裴经历连番挑战，要为老裴的梦想而捍卫金矿到底。©豆瓣', '吴刚', '许传海', 4.4, 8655, 'tt2075261', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2173429747.jpg', 24.4, 37.3, 31.8, 4.7, 1.7, '-0.149078,-0.189598,-0.253371,0.574857,-0.151302,-0.276526,0.452251,-0.063527,-0.274725,-0.434023,-0.374930,0.415329,-0.122545,0.415040,0.368453,-0.187423,-0.079779,-0.454962,-0.167045,-0.022737,-0.326398,-0.752007,0.304257,-0.354799,-0.061110,0.312107,0.407095,0.343833,-0.085039,0.404040,0.497977,0.132953,-0.134686,0.468487,-0.122396,0.220332,-0.150316,0.004685,-0.246537,0.401591,0.667503,-0.135306,-0.298298,-0.139378,0.367109,0.142414,0.357873,-0.134105,0.323899,0.153131,0.351823,-0.204861,0.549289,-0.040166,0.446808,0.184025,0.070581,0.051327,-0.090405,-0.302883,0.324752,-0.400814,0.013545,0.455784,0.426552,-0.433598,-0.455932,0.021981,0.010473,0.577514,-0.086939,-0.191499,0.191746,0.587263,0.459986,0.198401,-0.211655,0.305905,-0.579831,-0.000873,0.320788,-0.033156,0.273300,-0.381306,0.265978,-0.630111,-0.131467,-0.291695,-0.201814,-0.163044,0.533691,-0.089525,0.161179,0.102649,-0.545641,-0.056774,-0.097957,0.206719,0.466100,-0.099117,-0.203516,-0.542137,-0.106935,-0.377339,0.412364,0.503858,0.397319,-0.347447,0.402195,-0.398073,0.062071,-0.081795,0.192471,-0.909560,0.949069,-0.073985,-0.048540,-0.373023,0.205932,0.149693,0.584508,0.449932,0.418007,-0.203090,-0.172311,0.036098,-0.040733,-0.152385', '30159567', '5294324', '2046839', '25876760');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6110568', '名侦探柯南OVA11：来自伦敦的秘密指令', '爱情', '受到英国方面的邀请，工藤新一（山口胜平 配音）、小兰、阿笠博士（绪方贤一 配音）启程前往伦敦。在日本这一边，似乎有什么人物盯上了住在步美（岩居由希子 配音）家的灰原哀（林田惠美 配音），而柯南（高山南 配音）也专程打电话告诫光彦（大谷育江 配音）不要让灰原靠近博士的家。与此同时，光彦意外在姐姐的时尚杂志上发现一个名叫Gress Aihara的模特和灰原长得极其相像，他推测灰原此时正身处危险之中。他和元太（高木涉 配音）秘密跟踪灰原和步美，以防危险的发生……本片为《名侦探柯南》的OVA作品，根据原作71、72卷收录的外传改编。©豆瓣', '林原惠美', '山本泰一郎', 7.2, 5563, '', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2509378339.jpg', 1.4, 6.5, 41.5, 30.7, 19.8, '0.470161,-0.266677,-0.388574,0.500862,0.217888,-0.093674,0.405187,0.110414,-0.196714,-0.556884,0.058714,0.729042,-0.203565,0.221936,0.286523,0.076825,-0.430670,-0.437683,-0.084915,-0.289209,-0.200600,-0.636002,-0.095480,0.006815,-0.073757,-0.222028,0.466489,-0.051792,-0.622317,0.609918,0.149920,0.168395,-0.560009,0.250744,0.224744,0.261364,0.244108,-0.087049,0.040524,0.320925,0.126828,-0.230246,-0.104360,0.102347,0.318510,0.450714,0.424162,-0.151876,-0.293784,0.235508,0.405317,-0.256745,-0.067157,-0.103175,0.389254,0.014713,0.140262,0.082639,-0.223199,0.218691,-0.126355,-0.007331,-0.684707,0.062571,0.290678,0.507344,-0.103513,-0.004315,-0.118374,-0.096892,0.329566,-0.287699,0.206517,0.207196,0.395557,0.087756,-0.193493,0.376539,-0.145155,0.022567,0.399083,0.071876,0.234999,0.172341,0.109234,-0.246981,-0.197137,-0.018723,-0.461010,0.212764,0.067988,-0.058210,0.057215,-0.165047,-0.328505,-0.269311,0.121698,-0.165674,-0.114116,-0.057748,-0.119198,-0.616922,0.156950,-0.406416,-0.094435,-0.056319,0.160941,-0.401541,0.725770,-0.679352,0.083863,0.743315,0.319430,-0.131851,0.458754,0.103152,-0.186498,-0.145085,-0.184852,-0.048604,0.164601,0.293228,0.024830,0.321607,0.055918,-0.539895,-0.558216,0.047362', '3811356', '27602116', '25880986', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6120832', '我的小公主', '剧情', '十岁的薇奥莉塔（安娜玛丽亚·沃特鲁梅 Anamaria Vartolomei 饰）和奶奶一起住，她的母亲汉娜（伊莎贝尔·于佩尔 Isabelle Huppert 饰）是个刚起步的摄影师，常年在外，极少顾家。直到一次她突然回家，开始诱导薇奥莉塔作她的模特儿，并将其打扮成华丽、黑暗、魅惑的小公主形象，拍摄一系列惊世骇俗的照片，一时间成为了巴黎的话题焦点。汉娜因此在其梦寐以求的上流社会赢得了一席之地，但薇奥莉塔在学校里遇到的却尽是嘲笑和排斥。然而，意识到女儿的童贞肉体是通向她成名之路的利器之后，汉娜在拍摄尺度上得寸进尺，甚至用威胁的方式想让薇奥莉塔拍摄与男性交媾的照片，这让母女关系迅速恶化。一边，汉娜不肯就此罢休，另一边，薇奥莉塔已不想再受其操控，眼看母女间的拉锯愈演愈烈，已到分崩离析的边缘……本片的灵感来自导演伊娃·爱洛尼斯科与其母亲的真实经历，后者就是著名罗马尼亚裔法籍女摄影家Irina Ionesco。', '伊莎贝尔·于佩尔', '伊娃·爱洛尼斯科', 7.5, 26642, 'tt1896788', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1495135266.jpg', 0.5, 3, 34.9, 45.2, 16.4, '0.377876,0.076847,-0.695937,0.575325,0.097291,-0.136889,0.787467,0.082342,-0.276371,-0.142670,0.340157,0.797986,-0.368023,0.321440,0.180974,0.024761,-0.239080,-0.870260,-0.097211,-0.110051,-0.173806,-0.417566,-0.118864,0.389024,-0.253085,-0.314334,0.518275,-0.192399,-0.311570,0.419903,0.378818,-0.005028,-0.072439,0.425274,-0.039779,-0.007892,-0.024959,-0.262734,-0.216927,0.146063,0.309711,-0.265017,-0.146307,0.362300,-0.043374,0.314367,0.716317,-0.355754,0.162525,0.015213,0.589979,-0.087316,-0.003579,0.211617,0.252454,-0.196990,0.254886,0.087390,-0.261558,-0.068921,0.214708,-0.048055,-0.723715,0.307979,-0.016798,0.089467,-0.417033,0.277578,0.041461,-0.001078,0.056738,-0.222950,0.261730,0.182974,0.166248,0.289642,-0.104351,0.095872,-0.173757,0.066682,0.588411,0.136048,-0.399977,0.566863,-0.199188,-0.202251,-0.090684,-0.530526,-0.645691,-0.126998,0.313778,0.132322,-0.130095,0.181861,-0.422148,-0.070483,-0.354317,-0.110203,0.102541,-0.075358,-0.013937,-0.505869,-0.261671,-0.488292,-0.125226,-0.056396,0.006662,-0.357276,0.584022,-0.692871,0.158632,0.584221,0.345775,-0.599070,0.557190,-0.027774,0.274664,0.006532,-0.204766,0.328125,-0.062952,0.223325,0.091237,0.332978,0.025541,-0.112622,-0.304276,0.483246', '30162520', '34890458', '1303034', '1300220');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6121141', '套利交易', '剧情', '60岁的罗伯特·米勒（理查·基尔 Richard Gere 饰）是个事业有成的亿万富翁，备受业界尊重和家人崇拜。然而这都是表象，实际上他不仅私自在公司的账目上动手脚以掩盖投资损失和欺诈嫌疑，还背着妻子在外偷腥。一天夜里，米勒因疲劳驾驶而发生车祸，情妇当场死亡，而他逃离现 场。为了掩盖涉嫌谋杀和保住商业洽谈，米勒开始疯狂地销毁和制造证据，然而随着探员布莱尔（蒂姆·罗斯 Tim Roth 饰）的层层介入，以及自己的女儿似乎也觉察了个中蹊跷，米勒渐渐发现，他在谎言的路上已经越走越远……©豆瓣', '理查·基尔', '尼古拉斯·亚雷茨基', 6.9, 8597, 'tt1764183', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1803645408.jpg', 0.9, 6.5, 47.3, 36.1, 9.1, '0.305196,0.006427,-0.700580,0.293328,-0.136406,-0.150222,0.717457,0.066601,-0.532571,-0.351264,0.312331,0.659575,-0.110790,0.188913,0.434224,-0.098488,-0.379612,-0.660662,0.091092,-0.104126,0.001832,-0.737909,-0.426410,-0.415470,-0.150418,-0.502535,0.570871,0.291495,-0.185317,0.522007,0.322062,0.325749,-0.012604,0.385881,0.131792,-0.082385,0.089891,-0.066784,-0.072553,0.127525,0.051411,-0.529176,0.052037,0.120425,0.045754,0.888370,0.450613,-0.216289,-0.134340,-0.144402,0.425660,-0.517241,0.115650,0.134140,0.192638,-0.044761,0.219688,0.440964,-0.377343,-0.213656,0.176611,0.149532,-0.854881,-0.104280,0.270102,0.161985,-0.578005,0.335005,-0.246145,0.003995,-0.026045,-0.178960,0.306661,0.314455,0.088094,0.366117,-0.238142,0.100050,-0.736503,0.032667,0.520805,-0.143576,-0.271222,0.197591,-0.112195,-0.143752,-0.004500,-0.333580,-0.360577,-0.117992,0.150251,0.055658,-0.087691,0.309229,-0.417213,0.005012,-0.378100,-0.211999,-0.313537,-0.448010,0.093273,-0.620016,-0.206191,-0.377398,-0.227126,0.006631,0.131323,-0.361475,0.161718,-0.527961,0.357705,0.508980,0.191280,-0.483359,0.580153,0.114307,0.197750,-0.174246,-0.377109,0.137262,0.229795,0.046459,0.030751,0.152960,0.221599,-0.275844,-0.074094,0.302884', '1307442', '1920730', '1299799', '25862560');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6123978', '庸才', '剧情', '前所未有的东日本大地震以及随之引发的海啸、核泄漏摧毁了无数人的生活，这其中包括15岁的中学生住田祐一（染谷将太 饰）。灾难过后，他与母亲（渡边真起子 饰）以及夜野（渡边哲 饰）、田村（吹越满 饰）等灾民住在自家的租船场，间或忍受滥赌的父亲（光石研 饰）和讨债的黑社会金子（点点 饰）的骚扰。同班同学中，茶泽景子（二阶堂富美 饰）是唯一欣赏住田的人，她记录住田每一句精彩的语录，自顾自闯入对方的生活。他们心甘情愿做一名毫无成就的普通人，却无法避免残酷的生活对他们无情碾压。在一个血腥的夜晚，住田犯下不可饶恕的罪行，由此展开了自毁的人生……本片根据漫画家古谷实的同名原著改编，并荣获2011年第68届威尼斯电影节最佳新人奖（染谷将太 & 二阶堂富美）。©豆瓣', '染谷将太', '园子温', 7.8, 23145, 'tt1900893', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1466061928.jpg', 1, 3.8, 25.5, 44.2, 25.5, '-0.096459,-0.228855,-0.572623,0.696063,-0.055808,0.002090,0.932835,0.062388,-0.343926,-0.255381,0.107910,0.662384,-0.296360,0.273578,0.432895,-0.321217,-0.064024,-0.551107,-0.260946,-0.033102,-0.262278,-0.243365,-0.106974,-0.045313,-0.245338,-0.073888,0.676349,0.193620,-0.386703,0.272657,0.495636,0.376264,-0.010360,0.050926,-0.082982,0.129126,-0.199129,0.237448,-0.276019,0.103366,-0.283348,-0.413212,-0.078118,0.173733,0.014957,0.245133,0.650487,-0.550973,-0.206171,-0.164263,0.439083,-0.384843,-0.267685,0.268978,0.038490,-0.179360,0.040630,0.145627,-0.258856,0.148812,0.275863,-0.171418,-0.854383,-0.165727,0.138518,0.106702,-0.334414,0.417531,0.154188,-0.098929,-0.094598,0.048898,-0.089054,0.323499,0.304102,0.164552,-0.361009,0.023470,-0.366732,0.516792,0.619311,-0.011599,-0.254208,0.198865,-0.360214,-0.385898,-0.226128,-0.393442,-0.484015,-0.004587,0.182212,-0.027705,-0.070814,0.259476,-0.485649,-0.206003,0.056427,-0.317190,0.052809,-0.195694,-0.224593,-0.696710,0.022179,-0.683022,-0.368912,0.286914,0.258564,-0.351003,0.674939,-0.570462,0.065670,0.251898,0.301962,-0.194049,0.375932,0.133364,0.032565,0.002041,-0.188108,0.198887,0.235682,0.437300,0.361578,0.452404,-0.148567,-0.149562,-0.117216,0.464459', '25828589', '26667010', '27666513', '35360296');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6124012', '四大名捕', '动作', '巍巍京城，气势磅礴。时有捕神（成泰燊 饰）率领的六扇门，高手云集，作风凌厉，成为朝廷只手遮天的人物。是时京城伪造铜币泛滥，六扇门头号捕快冷血（邓超 饰）策划抓捕疑犯，结果在醉月楼与另一组人马大打出手。对方是诸葛正我（黄秋生 饰）统领的神侯府，手下更有无情（刘亦菲 饰）、铁手（邹兆龙 饰）等身怀绝技的高手。捕神对神侯府的目的颇有猜疑，遂假意赶走冷血，令其潜入神侯府调查诸葛之真实目的。在此之后，冷血与无情、铁手以及江湖中人追命（郑中基 饰）组成四大名捕，声名显赫，而来自六扇门的姬遥花（江一燕 饰）似乎又暗藏不可告人的秘密与阴谋……本片根据温瑞安同名武侠小说改编。©豆瓣', '邓超', '陈嘉上', 5.4, 114575, 'tt2204340', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1607300196.jpg', 11.6, 29.2, 43.7, 10.8, 4.7, '-0.028554,-0.009510,-0.279040,0.362421,0.191552,0.473321,0.566445,0.356280,-0.686320,-0.394578,0.405603,0.338436,-0.021078,-0.305613,0.340360,-0.175744,0.004243,-0.757900,-0.467897,-0.585067,0.139238,-0.088300,-0.240560,-0.243679,0.076883,0.017808,0.461372,0.318079,-0.402642,0.303448,0.613334,0.570037,-0.627204,0.306917,-0.090656,-0.216959,0.229808,0.166067,-0.279784,-0.007602,-0.342481,-0.179723,-0.415833,-0.178837,-0.290413,0.368613,0.245916,-0.138812,-0.019222,-0.068704,-0.127102,-0.287053,-0.237961,-0.084863,0.387060,0.207642,0.198328,0.551104,0.238279,-0.063653,0.098498,-0.281714,-0.670730,-0.096270,0.564024,-0.009407,-0.318329,0.152389,-0.469708,-0.104146,-0.019698,-0.076937,0.249515,-0.013131,0.614793,-0.151638,0.282860,-0.204500,-0.514638,0.355375,0.190160,0.052915,0.172669,-0.282244,0.245902,-0.498026,-0.044264,-0.443625,0.014523,-0.040942,0.508900,-0.246935,0.216452,0.298615,-0.237161,-0.117065,-0.208390,0.375264,-0.135010,-0.423774,0.188193,-0.649120,-0.283157,-0.267343,-0.077745,0.026244,0.393750,-0.002918,0.606781,-0.700898,0.028202,0.015863,0.004380,-0.550116,0.332630,0.057527,-0.328397,-0.245829,-0.344461,-0.039649,0.429591,0.323348,-0.033165,0.339139,-0.315687,-0.449662,-0.142336,-0.210642', '25723905', '4301278', '2357707', '30465281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6124043', '赌博默示录2', '剧情', '时光流转，冷酷无情的一条圣也（伊势谷友介 饰）登上帝爱会操纵者的宝座，他凭借精明贪婪的头脑和狡诈无耻的手段让无数疯狂赌徒拜倒在自己的脚下，心甘情愿掏出所有积蓄，并最终沦为地下设施内不见天日的奴隶。与此同时，暂时从地下设施中逃脱出来的伊藤开司（藤原龙也 饰）设法要在14天内赚到2亿日元以解救那里的同伴。在这紧要关头，他结识了人生跌入谷底的坂崎孝太郎（生濑胜久 饰）以及老对头利根川幸雄（香川照之 饰），他们决定挑战帝爱会那台奖金高达10亿日元、被称为吃人沼泽的弹子机。石田大叔的女儿石田裕美（吉高由里子 饰）也参与进来，可是在计划的实施过程中险象环生，生死攸关的赌局就此拉开序幕……本片根据漫画家福本伸行的 “开司系列”（包括“默示录”、“破戒录”和“堕天录”）改编。©豆瓣', '藤原龙也', '佐藤东弥', 6.7, 14146, 'tt1904937', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1180505852.jpg', 1.7, 11, 49.2, 27.6, 10.4, '-0.142754,0.290692,-0.544756,0.445842,-0.095719,-0.152046,0.516979,0.073554,-0.247346,-0.080508,0.369250,0.570991,-0.092484,-0.175420,0.412311,-0.029078,-0.257381,-0.649090,-0.274395,0.003234,-0.120028,-0.318403,-0.213413,-0.092714,-0.345976,-0.122605,0.863198,0.362449,-0.135094,0.282209,0.477433,0.330775,-0.134343,0.158194,0.029155,0.048397,-0.130768,-0.108987,-0.049286,0.174083,-0.335023,-0.371399,-0.015961,0.057390,0.324085,0.357753,0.658852,-0.345277,-0.027439,-0.081477,0.139338,-0.170790,-0.298750,0.210321,0.146071,0.029207,0.087891,0.206899,-0.250578,0.029959,0.168240,0.008635,-0.928680,-0.348504,0.145150,-0.026548,-0.462911,0.246075,-0.038594,0.066465,-0.004085,-0.221883,-0.078115,-0.079502,0.174308,0.120042,-0.295567,-0.075683,-0.337833,0.208630,0.368636,-0.219942,-0.123206,0.184049,0.224269,-0.382043,-0.212296,-0.471826,-0.074517,-0.223855,0.307152,0.066069,-0.070050,0.119151,-0.634289,-0.016212,-0.081447,-0.301063,0.020861,-0.278139,-0.050722,-0.461614,-0.021788,-0.235777,-0.162798,0.223095,0.155875,-0.389781,0.638318,-0.541094,0.059496,0.394241,0.255063,-0.209881,0.487995,-0.238947,0.090727,-0.145742,-0.179153,0.085349,0.304797,0.444518,0.046379,0.332556,-0.157103,-0.179558,-0.391912,0.276907', '25880986', '26759820', '10467125', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6126442', '一步之遥', '剧情', '北洋政府统治时期，盘踞上海的军阀武大帅之子武七（文章 饰）为洗刷耻辱，辗转找到了前清遗老马走日（姜文 饰）求助。在此之后，马走日和在法租界当警督的发小项飞田（葛优 饰）联手策划了名为“花域总统选举”的大型选美活动，和马从小就认识的现总统完颜英（舒淇 饰）成功卫冕。谁知就在繁华喧嚣的最顶点，命运之车竟急转直下驶向深渊。在一个平凡的早上，完颜陈尸郊野，张皇失措的马走日找到武七的姐姐武六（周韵 饰）及其母亲齐老师（洪晃 饰），希望通过大帅帮自己洗刷杀人犯的罪名，结果却盲打误撞救下了险些被整死的项飞田。背负杀人犯之名的马绝路逃亡，而武六则以该事件拍摄了名为《枪毙马走日》的电影，马的命运愈加扑朔迷离……本片根据民国奇案“阎瑞生案”改编。©豆瓣', '姜文', '姜文', 6.6, 297115, 'tt2168000', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2210853894.jpg', 6, 13.7, 37.8, 28.5, 14, '-0.290437,-0.067964,-0.339388,0.515132,0.213677,-0.283612,-0.013463,0.377879,-0.267314,-0.312257,0.246599,0.440061,-0.126653,-0.067671,0.528372,-0.289056,-0.126203,-0.522665,-0.039786,0.203498,-0.246359,-0.286850,-0.011600,-0.214571,-0.014818,-0.068339,0.553862,0.338347,-0.250579,0.375623,0.554618,0.147360,-0.256618,0.123125,-0.273818,0.086056,0.030740,0.086707,-0.264826,0.080726,-0.192203,-0.379684,0.036501,-0.223370,0.039583,0.175588,0.506163,-0.280929,0.074870,-0.224116,0.558797,-0.328259,-0.136514,0.081207,0.304179,0.113149,-0.234078,0.109351,-0.260383,0.049355,0.114542,-0.155154,-0.528657,-0.034148,0.147562,-0.004251,-0.466473,0.371383,-0.103959,0.033815,0.145062,-0.141493,0.252963,0.364452,0.163357,0.284952,0.169141,-0.063226,-0.476971,0.320585,0.381237,-0.149842,0.034659,0.047023,0.274905,-0.508779,0.191248,-0.163960,-0.009696,0.073570,0.433567,-0.218831,-0.130395,0.190589,-0.280786,-0.311460,-0.228553,0.090859,0.049599,-0.303881,0.016400,-0.369921,0.048996,-0.242954,0.249908,0.167531,0.148801,-0.133197,0.306881,-0.377250,0.158588,0.216875,0.059995,-0.483318,0.449518,0.182450,0.099112,-0.166211,0.106360,0.187049,0.223013,0.510470,-0.011238,0.124582,-0.148312,-0.275449,-0.245766,0.368737', '6101834', '4135443', '26890502', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6128003', '爱在罗马', '喜剧', '美国游客Hayley（艾丽森·皮尔 Alison Pill 饰）在意大利旅行的时候，和意大利男子Michelangelo（弗拉维奥·帕伦蒂 Flavio Parenti 饰）坠入爱河，迅速订婚。Hayley的父母也从美国来到意大利和Michelangelo一家见面。Hayley的父亲Jerry（伍迪·艾伦 Woody Allen 饰）是一个退休的歌剧经纪人，他惊讶地发现Michelangelo父亲Giancarlo的歌剧才华，千方百计想把他推向市场......Antonio and Milly（亚历桑德拉·马斯特罗兰迪 Alessandra Mastronardi 饰）是一对新婚夫妇，从家乡来到罗马要开始新生活，Milly独自外出时却把手机弄丢了，找不到回去的路，更遇上了电影明星Luca Salta；而在酒店的Antonio则遇上了妓女Anna（佩妮洛普·克鲁兹 Penélope Cruz 饰），闹出了不少笑话......John（亚历克·鲍德温 Alec Baldwin 饰）回到了熟悉的意大利，认识了学建筑的学生Jack（杰西·艾森伯格 Jesse Eisenberg 饰），Jack正对他的女朋友的好友Monica（艾伦·佩吉 Ellen Page 饰）想入非非......一个普通的小职员Leopoldo（罗伯托·贝尼尼 Roberto Benigni 饰）一早醒来竟发现自己成了名人......在伦敦、巴塞罗那、巴黎之后，伍迪·艾伦又来到罗马，为您讲述发生在罗马的有趣故事。', '杰西·艾森伯格', '伍迪·艾伦', 7.6, 70318, 'tt1859650', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1502513719.jpg', 0.3, 2.6, 31.1, 48.4, 17.6, '0.325813,-0.128802,-0.648856,0.384807,-0.090624,-0.656317,0.698831,0.229192,-0.463390,-0.338617,-0.030358,1.068735,-0.299767,0.375329,0.479253,0.159971,-0.426408,-0.620594,0.249252,-0.309833,-0.197438,-0.464428,-0.099005,-0.245120,0.020764,-0.247226,0.195708,-0.172163,-0.058730,0.450670,0.321669,0.293736,0.028447,0.319141,-0.415020,0.156528,0.290168,0.096328,-0.205775,0.310149,0.008422,-0.025871,-0.180725,-0.028925,0.172107,0.158045,0.663405,0.034722,0.062284,0.084927,0.477058,0.035513,0.009279,0.108917,0.258239,0.048586,-0.003039,-0.124485,-0.228770,0.099020,0.202492,-0.154037,-0.216196,0.398334,-0.095581,0.277140,-0.720557,0.418105,-0.248813,-0.045206,0.143277,-0.483658,0.280678,0.375428,0.134391,0.386805,0.260517,0.199882,-0.513023,0.197145,0.593427,0.029262,0.050897,0.426200,-0.037202,-0.349693,0.183995,0.072682,-0.435363,0.021005,0.514406,-0.355981,0.079574,0.130643,-0.743297,-0.293810,-0.214182,-0.309347,-0.040773,-0.227835,-0.110270,-0.691835,-0.