INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6128922', '警戒结束', '剧情', '影片以近乎真实的镜头深入犯罪城市最黑暗的角落。影片于2012年9月17日在洛杉矶举行首映，首映当日前州长阿诺·施瓦辛格也亮相捧场。Taylor（杰克·吉伦哈尔 Jake Gyllenhaal 饰）和Zavala（迈克尔·佩纳 Michael Pena 饰）是一对工作上的搭档，同样，两个人也是生活中的好兄弟。他们一起在美国洛杉矶的街头巡逻，出生入死，也一起相互经历着结婚、孩子诞生等等家庭生活。可是，在一次例行的巡逻之后，他们发现了黑帮的一个秘密活动。而这个发现，也使得他们成为了洛杉矶最大的毒品贩子的眼中钉。于是，一场正邪较量、力量悬殊的猫鼠游戏就开始了……©豆瓣', '杰克·吉伦哈尔', '大卫·阿耶', 7.9, 26567, 'tt1855199', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1710215706.jpg', 0.5, 2.2, 21.3, 52.7, 23.3, '0.279466,-0.357923,-0.714171,0.626658,0.246020,-0.185835,0.650835,0.060212,-0.485937,0.012431,0.389666,0.871459,-0.417098,0.352795,0.378963,-0.197791,-0.448556,-0.888954,-0.194372,-0.182624,-0.331971,-0.331940,-0.195935,-0.116381,0.009492,-0.043074,0.587111,0.060406,0.123611,0.612657,0.391547,-0.211777,-0.119498,0.284343,-0.033878,-0.187907,0.248958,0.102926,-0.515022,0.219354,-0.158750,-0.156471,-0.312427,-0.048189,0.251520,0.154668,0.800043,-0.273772,-0.107205,-0.221547,0.367630,-0.331071,-0.240337,-0.087876,0.474090,-0.067250,0.473144,0.187089,0.057764,-0.015462,-0.211279,-0.196723,-0.574076,0.235998,-0.041648,0.092073,-0.456313,0.650177,0.225049,0.116150,-0.035776,-0.293534,0.344057,0.478170,0.393876,0.277846,-0.113123,-0.093885,-0.543369,0.264055,0.802111,-0.100707,-0.199357,0.150721,-0.015924,-0.595492,-0.239972,-0.261065,-0.456521,-0.064583,0.153430,-0.313208,-0.398458,0.352876,-0.976728,0.327176,-0.088969,-0.432202,0.084651,-0.318007,0.118395,-1.091943,-0.281672,-0.568189,-0.430783,0.144768,0.089237,-0.340762,0.705371,-0.815894,0.256381,0.775174,0.375337,-0.353524,0.889287,0.068382,0.337162,-0.234995,-0.021027,0.134242,0.158341,0.120057,0.094442,0.339503,-0.098630,0.073155,-0.382374,0.561768', '11541282', '3147969', '24751811', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6129642', '芭比之仙子的秘密', '动画', '公主格雷西莉亚（Alexandra Carter 配音）被仙子克里斯托（Brittney Wilson 配音）施展了爱情魔咒，不可救药的迷恋上了芭比（Diana Kaarina 配音）的男友肯（艾德里安·佩特里 Adrian Petriw 配音），为了得到肯，为了拆散他和芭比，格雷西莉亚不惜绑架了他。得知了男友被绑架的消息，一直以来水火不容的芭比和拉奇丽（布里特妮·厄文 Brittney Irvin 配音）决定联手。在同为仙子的好友佳丽（Cassandra Morris 配音）和泰勒（Kate Higgins 配音）的好心帮助下，两个女孩进入了仙子的世界——光之安吉利斯。不幸的是，被魔法蒙蔽了心智的格雷西莉亚怎能对两个女孩的“进犯”坐视不管？她毫不犹豫的把芭比和拉奇丽扔进了地牢。©豆瓣', 'Diana Kaarina', 'William Lau', 8.1, 4977, 'tt1800254', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2155073150.jpg', 0.6, 2.2, 23.3, 39.1, 34.8, '0.425408,0.136929,-0.451077,0.714457,-0.293656,-0.330657,0.595194,0.193638,-0.434299,-0.009761,-0.018344,0.673405,-0.543529,0.189706,0.469055,0.302156,-0.218015,-0.796556,-0.122873,-0.233916,-0.218626,-0.530276,-0.120384,-0.221169,-0.166441,-0.672959,0.405282,-0.445190,-0.262873,0.296522,0.546142,0.398528,-0.146372,0.265544,0.110521,0.372980,0.248649,-0.252086,-0.130680,0.678899,0.021244,0.028683,0.306310,0.132483,-0.082974,0.196623,0.590997,-0.537452,0.182257,-0.143509,0.364484,-0.413273,0.188084,0.256037,0.125648,-0.415548,0.162494,0.028454,-0.363181,-0.134135,0.481341,-0.264547,-0.544990,-0.095816,0.096028,-0.066876,-0.662060,0.346897,-0.265011,-0.061243,0.313970,-0.227540,0.125510,0.282443,0.383401,0.476483,0.078005,-0.020357,-0.434723,0.248392,0.433846,-0.015859,0.136117,0.357894,-0.238868,-0.492168,-0.105065,-0.238504,-0.696873,0.120188,0.804619,-0.222178,-0.070603,0.346551,-0.421543,-0.549543,-0.660864,0.111429,-0.113508,-0.891345,0.061966,-0.311333,-0.222894,-0.255430,-0.089506,-0.024942,0.041578,-0.282231,0.708519,-1.151950,0.246523,0.562026,0.409866,-0.151953,0.547839,0.139856,0.053899,-0.049797,0.100362,0.300257,0.398235,0.307886,0.324229,0.468101,0.161738,0.086067,-0.510870,0.194802', '30345227', '3044878', '4127270', '13