INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6147308', '我在路上最爱你', '剧情', '在一列南下的列车上，故事的主人公周涣与水晶不期而遇，共同度过一段美好时光，虽然这样的相遇在别人看来不可理喻，但此刻在他们心中却彼此慰籍。很多爱情故事往往都是讲述一段爱情的分离和结合，但这个故事讲述的确实爱情的开始……心灵愈合的开始就是爱情的开始。', '黄圣依', '金丰起', 3.6, 11429, 'tt4339118', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2175207456.jpg', 51.6, 26.6, 16, 3.5, 2.4, '0.826831,-0.095411,-0.780390,0.780071,0.079152,-0.232873,1.257247,-0.284038,-0.561608,-0.107882,0.173011,0.691361,-0.550931,0.445346,0.061582,-0.261679,-0.333805,-0.693671,0.199517,-0.063471,-0.178856,-0.723838,-0.101855,-0.024689,-0.071481,-0.128359,1.187116,0.449722,-0.330026,0.626017,0.018603,0.006943,-0.175859,0.329116,-0.474330,-0.014509,-0.364862,0.560258,-0.543938,-0.488230,0.232701,-0.280528,-0.049852,0.357218,-0.443585,0.212033,0.811409,-0.490154,-0.323771,0.570719,0.565830,-0.491602,-0.079113,0.027262,0.110079,0.489548,0.495056,0.299093,0.017644,-0.000543,-0.460857,0.252800,-0.819198,-0.163387,0.038250,0.313920,-0.391459,0.566087,0.322243,0.039139,0.088170,-0.352601,0.200020,0.656804,0.675647,0.656435,-0.558395,-0.286300,-0.619300,0.080531,1.350514,-0.043974,-0.407698,0.918265,-0.202184,-0.382405,-0.420696,0.334796,-0.465424,-0.096842,-0.077150,0.016807,-0.105716,0.729321,-1.074472,0.458396,-0.064998,-0.152706,0.366639,-0.757998,-0.014053,-0.690885,-0.654574,-0.780162,-0.575421,0.332155,0.414115,-0.738027,1.068875,-0.946727,0.159492,0.494512,-0.129587,-0.505465,0.583450,0.722230,0.138551,-0.398533,-0.008498,0.887688,-0.139495,-0.102553,-0.220371,0.395381,0.022971,0.604651,-1.091808,0.940989', '2053515', '25828589', '35287908', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6221409', '河东狮吼2', '喜剧', '话说古时有一绝世美女，名唤王月英（张柏芝 饰），她自幼为父亲王承彦（赵本山 饰）抚养长大，集万千宠爱于一身。但是月英痛恨男人的纳妾行为，有纳妾者见一个打一个，名震全城，也令饱受其压制的百姓怨声载道。王承彦早年丧妻，十五年过去，如今也有了再次婚配的念头。月英被逼无奈，提出要求，只要三日之内能找出一个男人说服她便不再干涉男人们的婚姻自由。王父辗转找到聪明绝顶的东方明亮（小沈阳 饰），请其与女儿展开辩论。一番唇枪舌剑，二人离下誓约，东方明亮立志在一年之内只爱月英一人，若能不变心则取月英为妻。正值兵马乱世，在大时代背景下，明亮和月英的心渐渐贴近……©豆瓣', '张柏芝', '马伟豪', 3.5, 31024, 'tt2361586', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1668856662.jpg', 51.9, 29.4, 14.5, 2.3, 1.9, '-0.454320,0.213416,-0.603314,0.371685,-0.073308,-0.138567,0.165775,-0.096725,-0.668506,-0.041745,-0.016795,0.536785,-0.369868,0.046733,0.346929,-0.114757,-0.073588,-0.589133,-0.052670,-0.470445,-0.093708,-0.527115,0.173241,-0.185694,-0.211929,-0.193511,0.480950,0.040579,0.183952,0.270828,0.281228,0.060283,0.022510,0.253943,-0.052488,-0.173701,-0.523449,0.021542,-0.379250,0.206995,-0.282962,-0.231184,-0.527465,-0.320041,-0.040144,0.182665,0.601933,-0.434361,-0.087829,-0.439010,0.523199,0.053817,-0.521582,0.037463,0.024075,0.131769,0.240062,0.309114,-0.238311,-0.407046,0.060189,-0.472265,-0.174598,0.165196,0.149458,-0.177670,-0.429527,0.299826,-0.107793,0.029431,-0.064032,-0.213264,-0.158521,0.172419,-0.090881,0.413824,-0.302507,0.229969,-0.316726,0.398595,0.496321,0.307210,-0.247762,-0.092765,-0.003270,-0.319838,0.131418,-0.417499,-0.319238,-0.130825,0.230797,0.258031,-0.154158,0.208963,0.078401,-0.018506,-0.266236,0.133552,0.442391,-0.390804,-0.213571,-0.068585,-0.076374,-0.299497,-0.169741,0.364527,0.416811,-0.173956,0.931935,-0.803600,0.254736,-0.197900,0.589840,-0.589602,0.630257,0.266238,0.341783,0.038659,-0.335264,0.361024,-0.161611,0.037365,0.113064,0.112298,-0.384699,0.234330,-0.202402,-0.064423', '6963575', '25922902', '3445516', '30159456');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6225992', '幸福额度', '喜剧', '孪生姐妹李晓红（林志玲 饰）与莫晓青（林志玲 饰）因父母离异而分开，两人的人生也变得迥然不同。任广告公关的李晓红做了多年上司的情人，终于不堪忍受等待而心生厌倦。莫晓青相恋四年的男友姜成（廖凡 饰）最近被朋友欺骗，导致二人的房产岌岌可危，晓青一怒之下考虑分手。晓红在酒店结 识了拥有“无限卡”的富二代张全（陈坤 饰），一番激情过后布下情网。失业的晓青寻找工作巧遇晓红，在后者安排下参加party，得以认识了家族公司的实力青年沈涛（杨佑宁 饰）。晓青办了多张信用卡奋力一搏，试图博得沈涛青睐，而晓红如愿得到了张全的求婚……性格不同的姐妹二人，能否得到各自的幸福？©豆瓣', '林志玲', '陈正道', 5.8, 65696, 'tt2095832', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1246519953.jpg', 5.2, 23, 51.9, 16.2, 3.7, '0.112824,-0.051641,-0.372078,0.408474,-0.064875,-0.243500,0.345843,0.322437,-0.383793,-0.132973,0.083847,0.594053,-0.314624,0.472309,0.301241,-0.380649,0.013263,-0.636919,0.002841,-0.029962,0.006084,-0.447989,0.104435,-0.007524,-0.152477,-0.218288,0.771218,0.078511,0.074943,0.468341,0.492701,0.117327,-0.307675,0.111231,0.117838,0.028612,0.023946,0.358441,-0.762014,0.165603,-0.005338,-0.082333,0.017094,0.028071,0.101367,0.218678,0.647327,0.154367,-0.205853,-0.067867,0.578830,0.082612,0.003660,-0.009461,0.191038,0.105207,0.200921,0.122412,-0.304890,-0.070032,0.199928,0.133345,-0.534251,0.048119,0.332384,-0.246695,-0.521909,0.378432,0.004998,0.010668,-0.056305,-0.351064,0.044917,0.472085,0.351585,0.257098,-0.007801,0.127944,-0.222001,0.446425,0.671132,0.077228,0.001222,0.320429,-0.235089,-0.259083,-0.006545,-0.204078,-0.566987,-0.025076,0.317579,0.191911,-0.009734,-0.004799,-0.332171,-0.211059,-0.298787,0.071050,0.275604,-0.563082,0.051864,-0.655548,-0.495062,-0.271350,-0.174339,0.223000,0.106471,-0.444961,0.518838,-0.797729,0.014557,0.246019,0.398978,-0.628590,0.513348,0.214347,0.161175,-0.325898,0.069010,0.252400,-0.015868,-0.127182,0.213525,-0.087861,-0.249297,0.153175,-0.262420,0.072998', '30345227', '4301278', '1293265', '3804470');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6301361', '第八页', '剧情', '本片是多伦多电影节的闭幕电影。Johnny Worricker（比尔·奈伊 Bill Nighy 饰）在MI5（军情5处）勤恳但安稳地工作了很多年。直到有一天，他最好的朋友兼上司Benedict Baron（迈克尔·刚本 Michael Gambon 饰）突然离奇死亡，唯一的线索就是他生前留下的一个让人费解的文件。当Johnny阅读完这些文件之后，他被里面的内容深深的震惊了，它揭示了许多内幕，甚至有动摇整个MI5的能力。因为Benedict的死，Johnny被迫离开了自己的工作岗位，而他唯一的目标就是解开事件的真相，找出好友的真正死亡原因。同时，Johnny的新邻居——漂亮Nancy（蕾切尔·薇兹 Rachel Weisz 饰）似乎对他有着不一样兴趣和关心。到底Nancy的真实身份是是谁，Johnny真的可以凭一己之力发现真正的答案吗？©豆瓣', '比尔·奈伊', '戴维·黑尔', 7.1, 6331, 'tt1797469', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1321256630.jpg', 0.9, 5.1, 44.1, 40.3, 9.6, '0.280524,0.101563,-0.718159,0.666841,-0.252146,-0.177446,0.562149,-0.031855,-0.587260,-0.406056,0.043824,0.813913,-0.019220,0.195162,-0.162945,0.171815,-0.296352,-0.814227,0.116974,-0.491997,-0.426707,-0.616499,-0.415693,-0.242606,0.047917,-0.209343,0.594817,0.190924,-0.027807,0.037883,0.386652,0.313390,0.204739,0.568962,-0.029289,0.029259,0.141071,-0.032899,-0.142812,0.031644,0.195020,-0.288874,-0.284746,0.636312,-0.108068,0.523978,0.531136,-0.314248,-0.469459,0.092456,0.452999,-0.380208,0.038800,0.091974,0.070531,-0.032352,0.282731,0.379069,-0.184785,-0.059129,0.121862,0.064279,-1.138611,-0.227807,0.003276,0.325352,-0.337867,0.249811,-0.287169,-0.220851,0.022761,-0.336846,0.417923,0.436605,0.254348,0.325438,-0.106302,0.026468,-0.420561,0.115168,0.597427,0.112357,-0.327538,0.633257,-0.318359,-0.433747,-0.237849,-0.156251,-0.250075,0.262024,0.451494,0.329241,-0.136762,-0.005814,-0.486778,-0.098605,-0.055084,-0.273051,-0.207282,-0.439078,-0.080780,-0.284852,-0.350576,-0.221583,-0.363353,-0.256487,0.095328,-0.484549,0.800389,-0.764812,0.178446,0.552429,0.118018,-0.662349,0.664422,0.120703,-0.094679,-0.192236,-0.007052,0.176804,0.174497,0.134675,0.074811,0.165069,0.193590,-0.318335,-0.426104,0.625019', '30163500', '26678784', '25932086', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6307447', '被解救的姜戈', '剧情', '1858年，美国南北战争前两年。德国赏金猎人金·舒尔茨（克里斯托弗·瓦尔兹 Christoph Waltz饰）从贩奴商人手中买下黑奴姜戈（杰米·福克斯 Jamie Foxx饰），让其重获自由。舒尔茨实则是要把姜戈培养成无法无天的赏金猎人，为其缉拿各种通缉犯以换取报酬。姜 戈的唯一条件是：从暴虐的糖果庄园主卡尔文·坎迪（莱昂纳多·迪卡普里奥 Leonardo DiCaprio饰）手中解救出自己的妻子布鲁姆希尔达（凯丽·华盛顿 Kerry Washington饰）。本片是昆汀向1966年由塞吉奥·考布西执导的经典意大利西部片《迪亚戈》的致敬之作。鬼才导演痞子昆丁三年磨一剑，继《无耻混蛋》后又一巨制力作。本片延续昆汀一贯低调奢华的风格，处处可见奇思妙想的幽默元素和血腥野性的动作场面，更有强档群戏，豪华卡司，可谓看点十足。《被解放的姜戈》荣获第85届奥斯卡金像奖-最佳原创剧本大奖，克里斯托弗·沃尔兹 Christoph Waltz则凭借此片荣获最佳男配角。本片同时荣获第85届奥斯卡金像奖最佳影片、最佳摄影和最佳音效剪辑提名。', '杰米·福克斯', '昆汀·塔伦蒂诺', 8.8, 567467, 'tt1853728', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1800813767.jpg', 0.2, 0.6, 8.7, 40.1, 50.4, '-0.337358,-0.127403,-0.373979,0.679141,0.200850,-0.410870,0.370281,-0.006118,-0.299065,-0.008846,0.040432,0.789390,-0.315900,-0.265015,0.525877,0.052402,-0.473366,-0.441173,-0.357394,-0.235598,0.302411,-0.371096,-0.515431,0.025891,-0.071938,-0.503835,0.600361,-0.330980,-0.162042,0.311818,0.907843,0.389431,0.188755,-0.236898,0.041189,0.018304,0.402061,-0.203366,-0.411331,0.457377,0.000495,-0.213220,-0.311210,-0.052457,0.178752,0.084023,0.626983,-0.284605,0.315930,-0.004619,0.753102,-0.144034,-0.263728,-0.145405,-0.052960,-0.136959,0.241641,0.212413,0.021987,0.223529,0.221345,-0.508801,-0.849624,-0.040192,0.126118,0.001077,-0.357776,0.147534,-0.263699,0.242750,-0.015887,-0.133864,-0.067885,-0.035849,0.427848,0.088672,0.125570,0.011665,-0.182699,0.492451,0.100902,-0.109280,-0.419618,0.193964,-0.258260,-0.689021,0.082044,-0.515568,-0.324329,-0.024264,0.503004,-0.138880,0.544074,0.137115,-0.598824,-0.331250,-0.281577,-0.115976,0.003402,0.015434,-0.037797,-0.806043,-0.052146,-0.088379,0.040707,-0.319686,0.147444,-0.268384,0.608834,-0.319916,0.230023,0.351421,-0.001216,0.064003,0.509857,-0.127450,0.095182,-0.261354,-0.235307,0.192312,0.228746,-0.016046,0.149583,0.356160,-0.017191,-0.499310,0.022870,0.545912', '3318306', '1424334', '22265121', '30397916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6307506', '吻我', '剧情', '米娅（鲁斯·维嘉·费尔南德兹 Ruth Vega Fernandez 饰）的爸爸莱斯（克里斯特·亨里克森 Krister Henriksson 饰）即将迎娶福瑞达（Liv Mjönäs 饰）的母亲伊莉莎白（莱娜·恩卓 Lena Endre 饰），在两人的订婚宴会上，米娅第一次和福瑞达相遇了。 随着时间的推移，尽管米娅已经有了未婚夫蒂姆（乔金·奈特奎斯特 Joakim Nätterqvist 饰），尽管米娅和福瑞达如今已经是没有血缘关系的姐妹了，可这并不能阻止她们之间的关系越来越亲密，一种炽热的感情正在以无法阻挡的速度席卷着两人的内心，而她们明白，一旦这种感情被公之于众，将会对各自的家庭带来多大的伤害。在迷惘和踌躇之间，两人的未来该何去何从？©豆瓣', '鲁斯.维嘉.费尔南德茨', '亚历桑德拉-泰雷斯·肯宁', 7.4, 13521, 'tt1859522', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1526654971.jpg', 0.6, 3.9, 38.5, 39.6, 17.5, '0.530803,-0.054840,-0.687559,0.647088,0.266760,-0.297972,0.858612,0.329190,-0.654113,-0.226675,-0.024857,0.555573,-0.347269,0.148633,0.395763,0.038346,-0.232086,-0.876535,0.045758,-0.163221,-0.365490,-0.868833,-0.288037,-0.015291,-0.145111,-0.219933,0.590494,-0.191335,-0.025322,0.635426,0.501693,0.207948,-0.089450,0.562327,0.053176,0.059288,0.175437,0.144463,-0.519191,-0.067451,0.351608,0.033869,-0.062076,0.282324,0.192312,0.478622,0.427544,-0.429534,0.065552,0.153586,0.186668,-0.100965,0.372052,0.252800,0.114454,-0.318338,0.283462,0.401666,-0.127075,-0.041767,0.133623,0.079847,-0.750907,0.364936,0.163233,0.223510,-0.570546,0.646769,-0.221905,-0.472296,0.249067,-0.188005,0.112249,0.798020,0.147069,0.508833,-0.439668,-0.270821,-0.389974,-0.295372,0.769378,0.206370,-0.284105,0.630531,-0.536951,-0.113250,-0.458313,-0.049180,-0.558666,-0.184702,0.282023,0.664533,0.036147,0.686341,-0.596503,-0.246399,-0.230401,-0.128778,0.021655,-0.597986,0.238203,-0.487225,-0.406396,-0.966195,-0.404700,0.252316,0.104574,-0.102007,0.437124,-1.073409,0.259256,0.291069,0.381257,-0.349398,0.426271,0.337486,0.112866,-0.217108,-0.188718,0.280030,-0.125514,-0.001430,0.166998,0.400694,0.485215,0.022425,-0.182909,0.634674', '20277433', '21766698', '24325798', '25810920');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6309365', '新妈妈再爱我一次', '剧情', '妻子小霖（景甜 饰）去世后，米一帆（陆毅 饰）就和五岁的儿子小乐（迷你彬 饰）相依为命。小霖去世前留下“下一年的雨季会回到人世”的诺言，父子俩将信将疑。没想到第二年雨季小霖真的出现，只是记忆全无，破碎的家庭再次团圆，虽然存有疑虑，但米一帆和小乐还是将他们的爱毫无保留地给了小霖，渐渐小霖也真正融入这个家庭，接受了妻子和母亲的角色，幸福的家庭看似美好，但人死真的可以复生吗？眼前这个失忆的小霖真的是他们的亲人吗？©豆瓣', '景甜', '金世勋', 4.7, 3737, 'tt2250554', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1752707170.jpg', 30.6, 27.1, 27, 8.2, 7, '0.060472,0.110792,-0.538773,0.205660,-0.328923,-0.514019,0.537503,0.082646,-0.526794,-0.186159,0.141660,0.923369,-0.007984,0.515217,0.033350,0.256447,-0.266238,-0.853436,0.044617,-0.254993,-0.151957,-0.561606,-0.132753,0.220125,0.070519,-0.137341,0.700063,-0.016306,0.238161,0.658052,-0.009788,0.150744,0.055306,0.392506,-0.284246,0.480981,-0.331954,0.234717,-0.507999,-0.007664,0.285314,0.247181,0.223376,0.181788,-0.083337,0.217893,0.809119,-0.189350,-0.511907,-0.247967,0.401671,-0.335394,-0.365798,0.103484,-0.011704,-0.074967,0.458719,0.300807,-0.209308,-0.173547,-0.019405,0.000732,-0.462640,0.105351,0.191098,-0.156549,-0.486199,0.377809,0.099170,-0.147652,0.263195,-0.466749,0.258575,0.553320,0.169885,0.851417,-0.839869,0.036317,-0.529033,0.145411,0.582818,-0.301881,-0.202365,0.623518,-0.166681,-0.184375,0.037194,-0.027357,-0.613317,0.436140,-0.085540,0.280110,-0.483982,0.396984,-0.497586,0.079397,-0.376287,0.040952,0.248991,-0.499436,-0.234503,0.029568,-0.271153,-0.328467,-0.684652,-0.025721,-0.244493,-0.462063,0.826767,-0.824788,0.497151,0.070259,0.664816,-0.431292,0.679040,0.353941,0.015274,-0.226378,0.239951,0.401273,-0.401841,0.118912,0.171811,0.055112,0.044847,-0.038683,-0.508110,0.416007', '1292720', '35048413', '30345227', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6311303', '加勒比海盗5：死无对证', '动作', '故事发生在《加勒比海盗3：世界的尽头》沉船湾之战20年后。 男孩亨利（布兰顿·思怀兹 Brenton Thwaites 饰）随英国海军出航寻找被聚魂棺诅咒的父亲“深海阎王”威尔·特纳（奥兰多·布鲁姆 Orlando Bloom 饰），却在百慕大三角遭遇被解封的亡灵萨拉查船长（哈维尔·巴登 Javier Bardem 饰）。获取自由的萨拉查屠尽加勒比海盗，征服了整个海域，手刃了“黑胡子”爱德华·蒂奇（伊恩·麦柯肖恩 Ian McShane 饰）的里海海盗王赫克托·巴博萨船长（杰弗里·拉什 Geoffrey Rush 饰）在女巫Haifaa Meni(格什菲·法拉哈尼 Golshifteh Farahani 饰)口中得知了萨拉查的真实目的：为寻找他的宿敌杰克船长（约翰尼·德普 Johnny Depp 饰）。海盗的命运皆压在落魄的老杰克被封印的黑珍珠号，以及天文学家卡琳娜·史密斯（卡雅·斯考达里奥 Kaya Scodelario 饰）口中的远古三叉戟上。', '约翰尼·德普', '艾斯彭·山德伯格', 7.2, 349171, 'tt1790809', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2459723975.jpg', 0.8, 5.9, 39.2, 40.1, 14, '0.093158,0.105131,-0.436095,0.347075,0.086808,-0.303106,0.687927,0.040111,-0.249075,-0.013136,0.345282,0.597713,-0.134692,-0.118660,0.387764,0.677320,-0.475519,-0.333473,0.085918,-0.099965,-0.116107,-0.431207,-0.711812,-0.050216,0.046293,-0.465014,0.451661,0.051954,0.007615,0.128570,0.183041,0.596946,-0.124730,-0.029326,-0.110935,0.028708,0.381187,-0.450686,-0.004830,0.179332,-0.394522,0.111193,0.091185,0.135123,-0.126321,0.387648,0.564604,-0.604744,0.591072,-0.141781,-0.004465,-0.202634,0.064803,-0.051700,0.304360,-0.122848,-0.290834,0.273364,-0.032351,-0.144541,0.387158,0.060825,-0.317076,0.009687,0.005362,0.479806,-0.125375,0.289415,-0.427457,0.199561,0.179082,-0.261467,0.172514,0.007336,0.260180,0.040478,0.097590,-0.028502,-0.422569,0.247477,0.036637,-0.300553,-0.035756,-0.224622,-0.029029,-0.446292,-0.090113,-0.107612,-0.304202,-0.126983,0.792048,-0.135358,-0.063898,0.641676,-0.727124,-0.280840,-0.622014,-0.293070,-0.080074,0.071494,-0.344135,-0.736322,-0.216089,-0.238671,0.105506,-0.210151,-0.042023,0.084403,0.218888,-0.371984,0.393164,0.592935,-0.131933,0.233352,0.385126,-0.052752,0.168087,-0.395497,0.049491,0.837839,0.298949,0.354191,0.074609,0.174326,0.348702,-0.200217,-0.301243,0.506141', '3227410', '1316693', '11606328', '25955779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6383498', '魔力麦克', '剧情', '十九岁的亚当（亚历克斯·帕蒂弗 Alex Pettyfer 饰）在工地上认识了麦克（查宁·塔图姆 Channing Tatum 饰），后来一次偶遇得知原来麦克是个脱衣舞男，而且还是脱衣舞场的台柱“魔力麦克”。第一次迷迷糊糊登台后，亚当尝到了赚快钱的滋味。于是麦克领着亚当入行，让他改变行头，教他跳舞的技巧以及如何取悦挑逗女性。将艺名改为“The Kid”的亚当，和舞场一众舞男里奇、肯特、提托以及泰山，度过了一个疯狂、刺激、纸醉金迷的夏天。另一方面，麦克并不想一直干舞男这一行，他想创办一所家具定制公司，然而他申请银行贷款却失败。同时，他发现自己爱上了亚当的姐姐，他决定不去迈阿密……影片根据主演查宁·塔图姆19岁时在弗罗里达州坦帕市做脱衣舞男的经历改编。©豆瓣', '查宁·塔图姆', '史蒂文·索德伯格', 6.6, 29702, 'tt1915581', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1572435248.jpg', 1.3, 10.3, 54.6, 25.6, 8.2, '0.228082,-0.057073,-0.549768,0.353037,-0.091825,-0.360335,0.630098,0.120664,-0.400940,-0.254354,0.126558,0.646126,-0.224566,0.366814,0.443065,0.205998,-0.391589,-0.591158,0.138836,-0.078105,-0.074823,-0.399677,-0.216573,0.027302,-0.091042,-0.263245,0.209555,-0.153097,0.033608,0.512977,0.657461,0.071616,0.320796,0.094349,0.208301,0.080593,0.570063,-0.128522,-0.197055,0.465617,0.068853,-0.137053,-0.150023,-0.042317,0.201442,0.308945,0.483044,0.071232,0.077686,-0.056114,0.429908,0.183471,-0.146863,0.116699,-0.010259,0.003770,0.161531,-0.049909,-0.121015,0.030699,0.008180,-0.082024,-0.610465,0.244427,0.011955,-0.066866,-0.455741,0.132820,-0.151753,0.196523,-0.114522,-0.278071,-0.129235,0.080694,0.485207,0.315337,-0.062472,0.031617,-0.353648,0.367299,0.819321,0.174757,-0.085000,0.312360,0.027830,-0.319955,-0.005635,-0.157879,-0.346616,0.167776,0.177709,-0.056471,-0.234692,-0.103206,-0.293593,-0.120355,-0.161769,-0.278642,0.071344,-0.126847,-0.025518,-0.733749,-0.197754,-0.180451,-0.034928,-0.262365,-0.048838,-0.276785,0.339150,-0.612185,0.109023,0.642392,0.134935,-0.205485,0.616531,0.101322,0.080137,-0.101495,0.028635,0.154933,0.107305,0.121997,0.213686,0.452573,0.050715,-0.287630,-0.334038,0.408148', '3326747', '3147969', '11541282', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6383536', '怨鬼之家', '恐怖', '经过长达14年的努力，阿提终于在清迈远郊的拉达乐园购买了一幢属于自己的房子。他事必躬亲打理房中的一切，满心欢喜等待妻子小斑和女儿小楠、儿子纳特从曼谷到来。正处在青春期的小楠被迫和好朋友以及一直照料自己的外婆分别，因此心中愤愤不平，对父亲时常语带讥讽。与此同时，阿提一家的快乐喜悦也并未持续多久。某天，同小区一户人家，警方发现缅甸籍女佣被人杀害，并藏尸冰箱之中。这一恶性事件令拉达乐园内人心惶惶，小斑更是充满不祥的预感。虽然勉强支撑，但是阿提也不可避免地被一些灵异事件所困扰。某日，阿提不幸失业，巨大的生活压力令他透不过气来，而周边发生的各种不祥事件也让他几近崩溃……©豆瓣', '萨哈拉·桑卡布理查', '索分·沙达菲斯', 6.3, 6516, 'tt2063782', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1010673042.jpg', 3.4, 15.3, 52.8, 22.2, 6.2, '-0.014919,-0.106356,-0.685849,0.143437,0.333861,0.015799,0.766395,0.087228,-0.808127,-0.523281,0.168441,0.560633,-0.221877,0.515363,0.273040,-0.004835,-0.216930,-0.532052,0.038349,-0.107922,-0.285223,-0.225584,-0.176205,-0.473198,-0.163573,-0.232410,0.294560,0.476902,0.067209,0.563614,-0.083363,0.510472,-0.345477,0.772665,-0.097910,-0.120242,0.042477,-0.061192,-0.063088,-0.125685,0.014518,-0.209841,0.004310,0.292290,0.277245,0.360251,0.643938,-0.185178,-0.357934,0.056843,0.070923,-0.245814,-0.061229,0.256062,0.292200,0.012736,0.203274,0.106866,-0.418296,-0.058523,-0.037460,-0.028775,-0.669318,-0.010964,0.021210,-0.221309,-0.293903,0.366701,0.141685,-0.012325,0.140510,-0.209894,0.315608,0.278150,0.143502,0.615156,-0.398896,0.237511,-0.311750,-0.121035,0.610386,-0.202475,-0.024304,0.246301,-0.347081,-0.209632,-0.021299,-0.115727,-0.445639,-0.066428,0.114775,0.378312,-0.201363,0.330577,-0.552861,-0.044087,-0.369364,-0.322519,0.097338,-0.352577,-0.206771,-0.355747,-0.224397,-0.263600,-0.197041,-0.020835,0.170875,-0.101185,0.420197,-0.573655,0.578205,0.464694,0.210333,-0.436517,0.291955,-0.152593,0.259677,-0.074377,-0.257198,0.490097,-0.052204,0.327603,-0.058981,-0.048918,-0.179943,0.013193,-0.193361,0.482723', '10508879', '4817901', '1308745', '25839662');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6383567', '猫：看见死亡的双眼', '恐怖', '美丽的女孩素妍（朴敏英 饰）多年来一直为幽闭恐惧症所困扰，只要待在密闭的空间里，她就会感受到莫大的压抑与恐怖。好在可爱顽皮的小动物抚慰了她脆弱的心灵，如今的素妍在一家宠物店担任动物化妆师，生活平淡而快乐。但是她的生活很快被一场意外所打破，她的一名客人在离开不久后便死在电梯内，素妍只得暂时帮她照料宠物猫小布。也就从这一刻起，她经常能够看到面容阴森、无处不在的短发小女孩。她的精神几近崩溃，而怪事却愈演愈烈，最终连她的好朋友宝姬也无端惨死。素妍隐约感到迄今所发生的一切恐怖事件，都与神秘的小布有关……©豆瓣', '朴敏英', '卞承旭', 6.2, 15251, 'tt1935094', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1075582118.jpg', 2.3, 15.9, 58.2, 18.4, 5.2, '-0.019375,0.235566,-0.876001,0.390939,-0.410572,0.015047,1.031653,0.278439,-0.705986,-0.271442,0.270519,0.752710,-0.294921,0.400298,0.049877,0.193291,-0.076797,-0.570435,-0.121853,-0.179674,-0.418221,-0.016553,-0.339065,-0.302505,-0.102817,-0.525516,0.482485,0.325857,-0.188336,0.314810,0.075473,0.044595,-0.268005,0.779393,-0.285629,-0.098583,-0.143645,0.190667,0.008819,-0.206087,0.203911,-0.375465,-0.085484,0.255553,-0.081199,0.177609,0.796959,-0.457499,-0.455535,0.284278,0.228975,-0.105040,-0.021087,0.207357,0.093099,-0.097823,0.399181,-0.085525,-0.553056,0.257062,0.056281,0.012989,-0.647919,0.150983,-0.101899,0.180888,-0.343453,0.611889,0.194243,-0.097304,0.364285,-0.353602,0.155325,0.208048,0.077127,0.560587,-0.371729,0.190809,-0.206356,0.105759,0.775896,-0.061839,-0.453514,0.531827,-0.391329,-0.332946,-0.119311,-0.063400,-0.577950,0.084055,0.210711,0.181472,-0.469880,0.283753,-0.599235,0.069487,-0.351865,-0.018343,-0.240443,-0.502576,-0.111829,-0.431149,-0.272740,-0.372318,-0.307776,0.219588,0.025402,-0.218461,0.639724,-0.836274,0.572092,0.512364,0.128267,-0.361315,0.453619,-0.146778,0.196615,-0.036807,-0.140962,0.477310,-0.113866,0.429955,0.355985,0.461597,-0.178512,0.180480,-0.475108,0.525626', '3059036', '21619567', '1308755', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6386345', '春娇与志明', '剧情', '张志明（余文乐 饰）与余春娇（杨千嬅 饰）在一起后，恋情也不可避免由热烈转向平淡，几番龃龉过后，二人平平淡淡、不知不觉地分手了。在此之后，志明接受前老板的邀请，和公公前往北京发展，他很快结识了美丽温柔的空姐尚优优（杨幂 饰），一段新的恋情由此展开。另一方面，春娇的化妆品牌决定关掉香港分店，于是她也和娥姐转战北京。曾经的恋人相见自是几多尴尬，而原以为早已平淡和忘却的情感竟在见面的一刻复萌。虽然志明有优优陪伴，春娇也意外邂逅了体贴稳重的SAM（徐峥 饰），但是他们仍然瞒着另一半偷偷见面，他们小心地保持着距离，心又不由自主地向对方靠近。已是从香港转战北京的爱情，将如何收场……©豆瓣', '杨千嬅', '彭浩翔', 7.3, 376636, 'tt2238839', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1372139719.jpg', 1.4, 5.3, 36.4, 40.7, 16.2, '0.276270,0.176937,-0.706691,0.450070,0.260259,-0.379644,0.420379,0.228723,-0.362816,0.112833,0.121764,0.668359,-0.351023,0.196202,0.262653,-0.113116,-0.343591,-0.717193,0.101468,0.000024,0.017142,-0.361280,-0.085946,0.100105,-0.023237,0.031413,0.326685,0.034477,-0.063234,1.033572,0.378594,0.057322,-0.476036,0.724282,0.054955,0.055444,-0.064970,0.366221,-0.669716,0.028635,0.351615,-0.350129,-0.258242,-0.112492,0.019102,0.565988,0.650961,-0.059054,-0.351846,0.427931,0.294511,-0.060167,-0.071988,0.059093,0.194754,0.272917,0.122220,0.356991,-0.524811,0.148692,-0.123634,0.137983,-0.282185,0.323694,0.169241,0.110845,-0.539147,0.538294,-0.001946,0.025348,0.191713,-0.301838,0.179866,0.632672,0.347051,0.306455,-0.145392,0.137359,-0.200738,0.185955,0.770351,0.247855,-0.175644,0.467541,-0.005499,-0.242764,0.068684,-0.024997,-0.510452,-0.032298,0.109688,0.200091,-0.023269,0.253179,-0.731528,-0.033295,-0.265505,0.134848,0.286477,-0.587910,0.121949,-0.492565,-0.287945,-0.572632,-0.483383,-0.173920,-0.072514,-0.126811,0.571615,-0.786528,0.077841,0.216426,0.476555,-0.403866,0.557872,0.177587,0.139483,-0.316213,0.064640,0.382644,-0.261911,0.297094,0.255748,0.337206,-0.083775,0.146907,-0.405011,0.258712', '35256235', '25856453', '3078390', '1451563');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6390823', '美国队长2', '动作', '渐渐习惯了现代生活的美国队长史蒂夫·罗杰斯（克里斯·埃文斯 Chris Evans 饰），在一次行动后隐隐嗅到神盾局内部所弥漫出来的凶险气味。而当得知神盾局正秘密进行的“洞察计划”后，他更为此感到愤怒。某天，神盾局指挥官尼克-法瑞（塞缪尔·杰克逊 Samuel L. Jackson 饰）遭到一群武装分子袭击，他拼尽全力将一支U盘交到美国队长手中，这里面藏着该局二战以来最重要且最可怕的秘密。在此之后，美国队长因涉嫌杀害尼克而遭到前局长亚历山大·皮尔斯（罗伯特·雷德福/Robert Redford 饰）的通缉和追杀，逃亡中他得到黑寡妇（斯嘉丽·约翰逊 Scarlett Johansson 饰）和退伍老兵“猎鹰”（安东尼·麦凯 Anthony Mackie 饰）的帮助。他们必须争分夺秒解开神盾局的秘密，阻止“洞察计划”的施行……©豆瓣', '克里斯·埃文斯', '安东尼·罗素', 8, 422107, 'tt1843866', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2169912867.jpg', 0.4, 1.5, 21.4, 49.5, 27.2, '0.053950,-0.037875,-0.751445,0.543198,0.069865,0.044278,0.463269,-0.111706,-0.382879,-0.463622,0.297575,0.498072,0.148672,-0.241075,0.332774,-0.065226,-0.349018,-0.637291,-0.037408,-0.186971,-0.256055,-0.430979,-0.513766,-0.185183,0.026979,-0.412250,0.637219,0.296714,-0.105638,0.319134,0.248680,0.622534,-0.117138,0.306049,0.228944,-0.294492,0.474091,-0.422185,-0.407356,0.232024,-0.001856,0.012297,-0.016998,0.420373,0.152557,0.305322,0.446786,-0.417925,0.112077,-0.396831,0.128734,-0.384798,-0.113828,0.035058,0.333857,0.399564,0.010537,0.439654,-0.142623,-0.002978,-0.040481,-0.007717,-0.670344,-0.033158,0.076006,0.067865,-0.237641,-0.253264,-0.398594,0.440216,0.067095,-0.322275,0.154682,0.350843,0.351541,-0.062731,-0.129536,0.054525,-0.480088,-0.165764,0.475354,-0.634320,-0.113061,-0.155700,-0.097473,-0.077732,0.110542,-0.169272,-0.195101,-0.090226,0.318320,0.080589,0.146182,0.174705,-0.464358,-0.046386,-0.275534,0.000208,-0.120599,-0.260748,-0.152252,-0.778839,-0.158862,-0.076697,-0.312133,0.068770,-0.068280,-0.045220,0.287462,-0.544257,0.269751,0.508977,-0.054011,-0.141965,0.078417,0.147845,0.238900,-0.361506,-0.222049,0.284521,0.333318,0.296090,0.011383,0.305263,0.058558,-0.405060,0.008941,0.137719', '4014397', '7916027', '11610281', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6390825', '黑豹', '动作', '位于非洲的神秘国家瓦坎达，凭借来自宇宙的振金而成为科技极度发达的国家，不过他们长久封闭，始终对外界保守这个秘密。在前国王死于联合国爆炸袭击后，特查拉王子（查德维克·博斯曼 Chadwick Boseman 饰）继任成为新的国王，同时他也是黑豹的继承者。登基之后，特查拉与前女友娜吉雅（露皮塔·尼永奥 Lupita Nyong''o 饰）、贴身侍卫奥姆烨（丹娜·奎里拉 Danai Gurira 饰）追查曾经盗取振金并杀害瓦坎达人的尤利西斯·克劳（安迪·瑟金斯 Andy Serkis 饰）。一番厮杀后，克劳侥幸逃脱，谁知最终死于合伙人艾瑞克·克尔芒戈（迈克尔·B·乔丹 Michael B. Jordan 饰）之手。艾瑞克同样具有瓦坎达血统，而且当年他的父亲死在了自己的兄弟——特查拉父亲的手中。怀着莫大的仇恨，艾瑞克踏足瓦坎达，去争夺至高无上的王位……©豆瓣', '查德维克·博斯曼', '瑞恩·库格勒', 6.5, 427451, 'tt1825683', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2512123434.jpg', 2.3, 12, 52.5, 26.7, 6.6, '0.098408,0.069752,-0.622338,0.550801,0.147752,-0.208355,0.430255,0.128761,-0.551126,-0.308435,0.276626,0.937153,0.138365,-0.066256,0.337316,0.335995,-0.586611,-0.404932,0.010249,-0.250711,-0.195199,-0.608228,-0.401865,-0.223205,-0.150759,-0.468332,0.825870,-0.197616,-0.144831,0.360566,0.317211,0.617738,-0.133716,0.321026,-0.033361,0.006680,0.298781,-0.284257,-0.379634,0.306402,0.065172,0.154351,-0.097093,0.268621,0.025208,0.272192,0.086016,-0.728010,0.453204,-0.465430,0.324396,-0.238352,-0.025992,-0.016121,0.153120,-0.151058,0.105653,0.513594,-0.146253,-0.184518,0.248353,0.008866,-0.569976,-0.046759,0.030337,0.048675,-0.484826,0.324985,-0.189816,-0.043390,0.209758,-0.148726,0.350260,0.405438,0.010973,0.150133,-0.069767,-0.018006,-0.541435,-0.177133,0.268996,-0.192367,-0.315866,-0.208203,0.028321,-0.531808,-0.042704,-0.503226,-0.509570,-0.069588,0.382508,0.071010,0.184094,0.510918,-0.487485,-0.172598,-0.620637,-0.044364,0.114795,-0.258358,0.012089,-0.475483,-0.145081,-0.183789,-0.224088,-0.168641,0.028946,-0.331566,0.407977,-0.733853,0.365360,0.505658,0.357036,-0.377343,0.315078,-0.004234,0.249926,-0.280527,-0.433812,0.671914,0.393435,0.001413,-0.096131,0.032011,0.282182,-0.173655,-0.125952,0.393665', '1482099', '2062677', '1303034', '34968329');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6390832', '迫降航班', '剧情', '机长维普·惠特克（丹泽尔·华盛顿 Denzel Washington饰）驾驶227航班驶离奥兰多。可穿越云层时，飞机却发生了始料未及的故障。紧急中，经验老道的维普迫降到一个小教堂门口的空地上。维普奇迹般地控制住了飞机，让所有人都安全地回到了地面。事故后维普成了国家英雄。可此后美国联邦航空局对飞行事故展开了调查，发现此次事故背后的真相，居然跟维普滥用药物以及酗酒有关。是英雄还是阶下囚，维普到底能否维护住自己的英雄形象？本片荣获第85届奥斯卡金像奖最佳男主角和最佳原创剧本提名，以及第70届金球奖电影类-剧情类最佳男主角提名。《迫降航班》的成本仅为3100万美元，这是导演罗伯特·泽米吉斯自1978年的处女作《一亲芳泽》后成本最低的一部电影。©豆瓣', '丹泽尔·华盛顿', '罗伯特·泽米吉斯', 7.4, 43782, 'tt1907668', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1884921666.jpg', 0.3, 2.5, 37, 47.4, 12.8, '0.006620,0.028751,-0.603249,0.553914,0.478056,-0.137800,0.425659,0.076971,-0.315592,-0.154852,0.429178,0.785861,-0.280862,-0.107837,0.381152,0.093810,-0.710577,-0.522828,0.009257,-0.321775,-0.378536,-0.441417,-0.471887,0.082118,0.091747,-0.239436,0.731657,0.206204,-0.239914,0.237408,0.550657,-0.025891,-0.121458,0.252012,-0.007929,0.045067,0.291990,-0.168655,-0.147746,0.513172,-0.123119,-0.445413,-0.017817,-0.028092,0.366830,0.281106,0.698782,-0.267883,-0.245573,0.059918,0.468497,-0.297162,-0.008971,-0.225354,0.308868,-0.007649,0.336655,0.204960,-0.120633,0.392754,-0.024383,0.086883,-0.644674,-0.014413,-0.234587,0.009120,-0.402590,0.046617,-0.270179,0.143004,-0.088572,-0.149037,0.260511,0.168878,0.408079,0.096993,-0.249752,0.057920,-0.259437,0.343215,0.322195,0.140245,-0.504813,0.361102,0.131675,-0.651815,-0.210515,-0.385857,-0.405263,0.262511,0.310229,0.006657,0.122783,0.174833,-0.281677,0.000241,-0.397988,-0.375870,-0.327877,-0.127063,-0.122847,-0.840143,0.261956,-0.028913,-0.048519,-0.173358,0.122344,-0.296941,0.443637,-0.267041,0.110171,0.495858,-0.046938,-0.235312,0.627140,-0.049036,0.201343,-0.127343,-0.012766,-0.074436,-0.179129,0.582782,-0.244640,0.161682,0.011091,-0.508799,-0.238271,0.359907', '1298616', '26275494', '30397916', '1298911');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6393127', '赛德克·巴莱(下)：彩虹桥', '剧情', '莫那鲁道（林庆台 饰）率领族人在公学斩杀异族血祭祖灵后，拥有了通过彩虹桥的资格，剩下来的，就是在英勇战斗后从容赴死。在日本方面，雾社的消息很快传达各处，陆军少将镰田弥彦率军队与警察组成的联合部队，迅速发起讨伐。马赫坡等社分头行动，利用地形优势和灵活战术给予日军先头部队重大杀伤。山地警小岛（安藤政信 饰）利用个人威望和部族矛盾成功劝说铁木瓦力斯（马志翔 饰）连同部落加入日军阵营，协助围攻莫那鲁道。在开战初期，随部落向密林转移的妇孺为了不拖累战士们，纷纷自尽，在矛盾中痛苦的一郎亦选择了切腹。镰田弥彦对部队的缓慢推进大为光火，不惜使用糜烂性炸弹对付赛德克人。满山火光中，莫那鲁道迎来了最后决战的时刻……©豆瓣', '马志翔', '魏德圣', 8.8, 85952, 'tt4164468', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1174627051.jpg', 0.3, 0.8, 9, 36.4, 53.6, '-0.013586,-0.072921,-0.718281,0.687431,0.241524,0.099387,0.185201,0.048117,-0.119942,-0.082598,0.291752,0.435810,0.389591,-0.331585,0.136502,-0.769607,-0.329192,-0.520687,-0.134608,0.004673,-0.434791,-0.511505,-0.029216,-0.689181,0.056228,-0.553808,0.879448,0.291612,-0.498613,0.677572,0.061790,0.518241,-0.242371,0.478669,0.216423,-0.095144,0.193298,-0.470266,-0.524807,0.311789,-0.556914,-0.035863,-0.252739,-0.062904,0.184444,0.409059,0.932494,-0.488658,0.126392,-0.212131,-0.239254,-0.360178,0.281600,0.103397,0.823178,-0.099483,0.003249,0.133923,-0.077916,0.195680,-0.236327,-0.171625,-0.703050,-0.041369,0.432559,-0.112519,-0.563041,0.362403,-0.091535,0.221534,0.437778,0.023302,-0.012428,0.718820,0.333374,-0.041880,-0.132603,0.012558,-0.435542,-0.254923,0.701923,-0.142561,-0.084913,-0.491989,0.073478,-0.332296,-0.083858,-0.449587,0.176297,-0.268722,0.293896,-0.093016,0.220927,0.349833,-0.601575,-0.177676,-0.239373,-0.266173,0.275167,-0.312517,0.083642,-0.779229,0.201422,0.050689,-0.111262,0.436263,0.017804,0.398052,0.908743,-0.556295,-0.160334,0.299361,0.559138,-0.610161,0.385856,-0.120606,0.007091,-0.169739,0.084577,0.142661,0.266394,0.381354,0.552059,0.213001,-0.338502,-0.007223,-0.098979,0.061979', '25863940', '2369613', '35058077', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6396294', '天使的一份', '剧情', '几名犯事的无业青年被法院判处社区服务，他们在管理者哈里（John Henshaw 饰）的监督下展开工作。他们中间，名叫罗比（Paul Brannigan 饰）的青年刚刚知晓女友里奥妮（Siobhan Reilly 饰）生产的消息，可是却被女友的哥哥们揍了一顿。之后沮丧的他更被曾被他暴力伤害的伤者及家属痛斥了一番。望着儿子那天使般的面庞，一向暴戾冷酷的罗比眼神中流露出无限的悔意，重新做人的念头在他心间悄悄生起。在此之后，哈里带领罗比他们参观了一家威士忌酒厂，罗比再次表现出求知的欲望，而他那此前从未被发现的敏锐嗅觉成为重生的绝佳利器。为了过上幸福的生活，罗比和社区服务的伙伴们展开行动……本片荣获2012年戛纳电影节评委会大奖、2012年圣塞巴斯蒂安国际电影节观众奖最佳欧洲影片奖。©豆瓣', '罗杰·阿拉姆', '肯·洛奇', 7.6, 7903, 'tt1924394', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1734489071.jpg', 0.4, 2.4, 30.6, 51.7, 14.9, '0.037378,-0.049271,-0.618538,0.657435,-0.145804,-0.398483,0.717536,0.117863,-0.555347,0.065572,0.129536,0.719269,-0.344676,0.373665,0.310677,-0.071927,-0.293450,-0.787339,-0.330904,-0.182850,-0.015263,-0.146350,-0.278991,-0.051914,-0.083072,-0.400561,0.489597,-0.153943,-0.036742,0.594310,0.409282,0.289708,0.218828,0.323903,-0.075451,-0.031365,0.249722,-0.121559,-0.261328,0.348099,0.062668,-0.401047,-0.311110,0.215765,-0.050016,0.271436,0.793655,-0.130175,-0.062575,-0.224498,0.414005,-0.282801,0.217018,0.315786,0.119816,0.033395,0.161845,0.126224,-0.108341,-0.003543,0.143252,-0.123752,-0.675433,0.063308,-0.032108,0.187447,-0.654653,0.314704,-0.224514,0.167458,-0.017026,-0.117041,0.213001,0.071440,0.051539,0.315399,-0.268595,0.157436,-0.309105,0.330834,0.474546,-0.110951,-0.191386,-0.003991,-0.346914,-0.558510,0.119988,-0.168762,-0.323008,-0.167305,0.661620,0.018825,-0.097717,0.347622,-0.548822,-0.143586,-0.191788,-0.272706,-0.240587,-0.176602,-0.105323,-0.795369,-0.047535,-0.292476,-0.389085,0.037535,0.068023,-0.121999,0.636858,-0.743096,0.282583,0.561987,0.339201,-0.313188,0.596307,-0.001417,0.168574,-0.020328,-0.400149,0.230179,0.061293,0.213779,0.106600,0.455096,-0.214548,-0.150245,-0.142517,0.564820', '3811356', '1299663', '11541282', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6396709', '世界奇妙物语 21世纪第21年的特别篇', '剧情', '整人频道：在网络媒体高速发展的时代，真壁洋辅（坂口憲二 饰）及其团队为了虚妄的点击率大搞整人节目，即使被当事人责骂殴打也在所不惜。为了冲击1亿点击率，他逼迫团队成员去策划一个绝佳的整人方案； 分身：老实木讷的田崎守（大森南朋 饰）早年忙于打拼事业，以至年届40尚未结婚。通过相亲他与美丽温柔的志保（杏 饰）走到一起。为了弄清妻子嫁给自己的原因，他虚拟了一个身份与妻子通过网路对话； 通算：老刑警山冈武（松山健 饰）即将退休，一群莫名其妙的人跳出来为他庆祝各种各样的人生纪录； 罐迷藏：童年的玩伴正一在玩罐迷藏时神秘失踪，30年后，已是成年的朋友们却再次看到少年时代的正一，而他们也逐一丧命； 宠物：小狗阿樱（谷村美月 饰）的主人结识新男友，于是阿樱便被抛弃了，她只得独自面对艰难的生活。©豆瓣', '大森南朋', '河毛俊作', 6.7, 5787, 'tt4814372', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1973450978.jpg', 0.7, 8, 55.8, 27.2, 8.3, '-0.041991,-0.013178,-0.548020,0.379238,-0.203365,-0.239981,0.276801,0.089116,-0.341049,-0.368080,0.230724,0.631683,-0.184598,0.358125,0.237768,-0.190622,-0.117943,-0.656150,-0.022811,-0.072907,-0.198013,-0.176785,0.021585,-0.240670,-0.113307,-0.095326,0.625368,-0.096607,-0.022318,0.340859,0.449412,0.298507,-0.379602,0.230796,-0.089235,-0.061921,0.178534,0.092503,-0.263805,-0.006724,-0.323376,-0.228801,-0.171475,-0.039640,0.052861,0.288185,0.704348,-0.260337,-0.080557,-0.183746,0.260962,-0.147860,-0.208170,-0.037673,0.449830,0.035281,0.353716,0.139088,-0.109781,0.004965,-0.073388,-0.256804,-0.776126,0.050369,0.047520,0.047940,-0.326835,0.240178,-0.037305,-0.001047,0.252140,-0.149920,0.027117,0.393535,0.288187,0.335443,-0.390294,0.298266,-0.148977,0.448798,0.497045,0.051652,-0.035473,0.408986,-0.070651,-0.218469,-0.007549,-0.357215,-0.385169,-0.104953,0.196120,0.011680,-0.247850,0.163894,-0.512516,0.014183,-0.170592,-0.051349,0.155144,-0.388630,-0.153906,-0.437584,0.007300,-0.124396,-0.125237,0.264412,0.095874,-0.347331,0.775520,-0.616463,0.007376,0.509027,0.169213,-0.664287,0.509194,0.054676,0.097037,-0.335987,-0.000062,0.157322,0.016997,0.140368,-0.036247,0.159028,-0.081415,-0.080369,-0.307567,0.392211', '26678784', '27602116', '25928048', '4