INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6402121', '逆转裁判', '喜剧', '近未来，各种恶性犯罪日益增长，为了应对这一现状，新的司法系统“序审裁判”得到推广。该系统允许辩护律师和检察官当庭辩论，并在三日之内迅速得到审判结果。当下，人称“天才检察官”的御剑怜侍（齐藤工 饰）大展才华，接连制胜，大有其恩师——40年间未尝败绩的完美检察官狩魔豪（石桥凌 饰）的风姿。与之相对，新人律师成步堂龙一（成宫宽贵 饰）的事业则步履维艰。某天，成步堂的上司绫里千寻（檀丽 饰）遭人杀害，千寻的妹妹真霄（桐谷美玲 饰）被指为凶手。成步堂自告奋勇为真霄辩护，与童年好友怜侍展开对决。谁知不久之后，怜侍也被当作另一宗命案的嫌疑犯逮捕，而这一切全都与15年前一起神秘的案件有关。成步堂能否成功为好友洗脱罪名呢？本片根据同名游戏改编。©豆瓣', '成宫宽贵', '三池崇史', 6.2, 6401, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1672444721.jpg', 4.3, 17.9, 48.6, 23.1, 6.2, '-0.040062,0.073344,-0.215480,0.457864,0.093833,-0.181855,0.203748,0.157174,-0.440631,-0.420885,0.351126,0.558979,-0.317072,-0.040312,0.490885,-0.008246,-0.209961,-0.776059,-0.008725,-0.183417,-0.223353,-0.521736,-0.062580,-0.058438,-0.145973,-0.005433,0.579893,-0.175406,0.014734,0.353806,0.414871,0.412560,-0.425182,0.176014,0.146761,0.071272,0.250358,0.124222,-0.602802,0.319307,-0.119425,-0.247204,0.005857,0.147682,-0.263193,0.188546,0.581608,-0.389392,-0.253112,-0.366185,0.571186,-0.255326,-0.011794,0.157986,0.372272,0.120154,0.241281,0.752005,-0.122760,-0.114412,0.098989,-0.139390,-0.702415,-0.176704,0.164562,-0.060719,0.143843,0.151322,-0.275136,0.077408,0.068337,-0.080474,-0.222933,0.305017,0.457992,0.129311,-0.353545,-0.102553,-0.139447,0.433138,0.276568,0.069695,-0.020762,0.175367,0.210214,-0.446397,0.192196,-0.402024,-0.024996,0.040672,0.223122,0.199713,0.217991,0.365471,-0.329300,-0.276944,-0.249553,0.281859,0.068744,-0.230357,-0.016160,-0.429941,-0.107132,-0.014930,-0.304491,0.104097,0.277277,-0.273506,0.575553,-0.810753,-0.079604,0.315132,0.168195,-0.520596,0.186371,0.163769,0.401146,-0.159009,-0.350157,-0.135141,0.308776,0.530990,-0.038422,0.034444,0.188111,-0.352121,-0.444736,-0.099368', '30345227', '25723905', '25880986', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6402464', '麒麟之翼 新参者剧场版', '剧情', '某个夜晚，在被称作东京起点的日本桥的麒麟雕像旁边，一名男子踉跄着跌倒，最终失血过多死亡。死者名叫青柳武明（中井贵一 饰），是金崎金属制造公司的本部长。颇令警方费解的是，青柳在腹部被刺的情况下并没有立刻叫救护车，而是隐忍着走了长达8分钟的路程。同一晚，无业青年八岛冬树（三浦贵大 饰）被卡车撞成重伤，昏迷不醒。因为他拿着青柳的公文包，所以警方将八岛看作重要嫌疑人。本案的种种疑点，令日本桥警署的刑警加贺恭一郎（阿部宽 饰）陷入思索之中。他不仅走访了青柳的家人、八岛的同居女友中原香织（新垣结衣 饰），还尝试着重走青柳生前在日本桥附近的生活足迹，种种谜团和各种情感纠葛渐渐浮出水面……本片根据推理小说名家东野圭吾自诩的系列“最高杰作”《麒麟之翼》改编。©豆瓣', '阿部宽', '土井裕泰', 7.3, 23531, 'tt1946285', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1691940892.jpg', 0.5, 3.1, 40.5, 42.4, 13.5, '0.192410,0.032206,-0.480493,0.323433,0.222495,-0.140712,0.577872,0.219707,-0.309236,-0.337068,0.520651,0.539611,-0.029050,0.227037,0.151847,0.054798,-0.188657,-0.666027,-0.159899,-0.115314,-0.370296,-0.359944,-0.194763,0.056067,-0.164392,-0.116923,0.698584,0.049528,-0.036839,0.649206,0.158650,0.443121,-0.361164,0.214565,-0.167485,0.146369,0.139066,-0.243773,-0.155676,0.047961,-0.092239,-0.374430,0.050773,0.244464,-0.185641,0.430203,0.693330,-0.137211,-0.288422,-0.068898,0.222807,-0.203154,-0.054666,0.019441,0.616945,-0.045630,0.020287,0.313578,-0.237113,-0.041023,0.259028,0.267856,-0.340648,-0.012028,0.073081,0.418550,-0.425802,0.482070,-0.201527,-0.031060,0.182349,-0.164127,0.146979,0.109796,0.216803,0.090017,-0.190549,-0.036405,-0.252280,0.311489,0.205025,0.045958,-0.132162,0.119904,-0.262983,-0.380552,-0.216556,-0.051356,-0.051068,-0.116560,0.322528,0.040007,-0.191968,0.004621,-0.434719,0.153834,-0.130816,-0.159585,-0.217180,-0.072234,-0.198200,-0.564894,-0.014028,-0.429425,-0.084164,-0.076339,0.124717,-0.031485,0.513916,-0.417860,0.077060,0.584636,0.107070,-0.129488,0.392549,0.056533,-0.107411,-0.107254,-0.039380,0.149971,-0.131286,0.585168,0.064669,0.256813,-0.172527,-0.123365,-0.588626,0.083775', '26365262', '3811356', '1309194', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6424025', '微妙爱情', '喜剧', '在浪漫氤氲的法国巴黎，年轻姑娘娜塔莉（奥黛丽·塔图 Audrey Tautou 饰）曾经拥有完美的爱情和快乐的工作，但在一天清晨，意外的车祸夺走了她丈夫的生命，也掐灭了她美好的生活轨迹。她开始沉溺新工作来试图麻痹自己，也拒绝别人的感情。然而，当一位其貌不扬的瑞士同事马库 斯（弗朗索瓦·达米昂 François Damiens 饰）来到公司后，两人竟鬼使神差地渐生情愫，生活的味觉也似在慢慢复苏。但他们的交往却并不为外界看好，面对朋友们的不解和追求者的阻挠，两人将如何小心保护这份意外的爱情美味……电影改编自大卫·冯金诺斯的同名小说，该书曾同时入围法国四大文学奖并荣获十项文学最高殊荣，在法国畅销突破75万册。©豆瓣', '奥黛丽·塔图', '大卫·冯金诺斯', 6.9, 10152, 'tt1828995', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1308234964.jpg', 0.9, 7.5, 48.1, 32.9, 10.6, '0.166161,0.192713,-0.737599,0.690039,-0.060250,-0.351246,0.731974,0.145118,-0.394803,-0.259984,0.189992,0.797335,-0.098934,0.180034,0.240733,0.022007,-0.220695,-0.741125,0.230375,-0.100425,-0.153907,-0.293759,-0.298958,-0.195569,-0.095599,-0.292997,0.762463,0.112924,-0.233956,0.529308,0.207270,0.099461,-0.130231,0.500287,-0.243060,0.037922,0.256700,0.186577,-0.493718,0.065713,-0.004251,-0.187925,-0.316437,0.215451,0.133698,0.235642,0.530892,-0.155799,-0.324060,0.151216,0.477295,-0.234696,0.126223,0.078543,0.072042,0.118541,0.146183,0.137209,-0.096245,0.099426,-0.068894,-0.127445,-0.810098,-0.080597,0.058356,0.148015,-0.383894,0.585052,0.019350,-0.077887,-0.026653,-0.197087,-0.112894,0.289915,0.186777,0.389408,-0.087450,0.232472,-0.325683,0.380545,0.559486,-0.144315,-0.498937,0.687534,-0.433883,-0.410870,-0.281829,-0.197437,-0.665998,0.070961,0.278645,0.338357,-0.041335,0.405143,-0.624725,0.048222,-0.061693,-0.105915,0.004934,-0.476864,0.029131,-0.489752,-0.126177,-0.303416,-0.471318,-0.122262,0.266519,-0.383116,0.759308,-0.659047,0.420563,0.644379,0.182718,-0.570141,0.717119,0.341427,-0.204004,-0.235827,-0.258335,0.697151,0.010556,-0.008185,-0.068741,0.296576,0.051244,0.143688,-0.477134,0.515924', '30279170', '1303034', '30162520', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6424184', '贞子3D', '恐怖', '不知从何时起，一段自杀直播的视频在网络上疯传，最为恐怖的是，凡是看过视频的人无一例外死于非命。某晚，就读于一所女子高中的女孩森崎典子坠楼身亡，她生前恰恰在网上寻找过那段视频。森崎的级任老师鲇川茜（石原里美 饰）由此对传闻产生怀疑。与此同时，警方也对该留言进行调查，结果发现的确所有看过视频的人都意外死亡。令人匪夷所思的是，即使视频删掉也如病毒一样在网络上疯传。最终，所有的矛头都指向了自杀视频的始作俑者柏田清司（山本裕典 饰）。他似乎借此在召唤某个带有强烈怨念的恶灵出现，真相究竟如何？©豆瓣', '石原里美', '英勉', 3.7, 9558, 'tt1844025', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1496018314.jpg', 44.2, 33.2, 17.1, 3.2, 2.3, '0.084682,-0.042376,-0.685636,0.320562,0.075257,0.391914,0.632556,-0.409665,-0.628465,-0.158274,0.318686,0.391837,-0.575343,0.221490,0.047754,-0.080993,-0.299537,-0.621639,0.050562,-0.432025,-0.406552,-0.358124,-0.328330,-0.221543,0.504970,-0.430462,0.516277,0.118812,-0.561194,0.094461,0.324805,0.461797,-0.538426,0.457466,0.088388,0.024014,-0.086330,0.199625,0.062765,-0.040616,-0.045398,-0.693003,-0.060597,0.194416,-0.172351,0.355641,0.800917,-0.182009,-0.494368,0.257601,0.855690,-0.257559,-0.200054,0.207395,0.520803,0.265580,0.144289,0.165312,-0.203144,-0.267910,-0.020867,0.479480,-0.843297,-0.219904,0.150183,0.560366,-0.111782,0.466131,-0.330587,0.185688,0.021368,-0.297543,0.192357,0.052893,0.231461,0.237262,-0.036975,-0.112752,-0.197525,0.371189,0.614199,0.140799,-0.325774,0.274229,0.043972,-0.366618,-0.350700,0.152321,-0.237253,0.341641,0.292858,0.089436,-0.373159,0.417995,-0.238020,-0.068209,0.122179,-0.267530,0.029854,-0.272966,-0.424698,-0.809580,-0.418826,-0.044904,-0.227674,-0.198230,0.100509,-0.367373,0.868118,-0.641150,0.373671,0.435371,-0.024931,-0.457195,0.370084,0.217882,-0.359527,-0.115002,-0.322142,0.276484,0.657439,0.353971,-0.078414,0.091974,0.128896,-0.532816,-0.576121,0.428684', '27602116', '2027945', '3318306', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6424756', '新蝙蝠侠', '剧情', '布鲁斯·韦恩（罗伯特·帕丁森 饰）化身蝙蝠侠于哥谭市行侠仗义两年后，罪犯皆闻风丧胆，他也因此深入接触到哥谭市的阴暗面。他潜行于哥谭市腐败的政要名流关系网中，身边仅有的几个值得信赖的盟友——管家阿尔弗雷德·潘尼沃斯（安迪·瑟金斯 饰）与詹姆斯·戈登警长（杰弗里·怀特 饰）。这位独行的“义警侠探”在哥谭市民心中已成为“复仇”二字最当仁不让的代名词。', '罗伯特·帕丁森', '马特·里夫斯', 7.3, 277325, 'tt1877830', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2868425292.jpg', 0.9, 5.6, 36.2, 44.6, 12.7, '0.176226,-0.379981,-0.442912,0.414325,0.024768,-0.466627,0.644542,0.043034,-0.522011,-0.409886,0.235713,0.788926,-0.115303,0.039683,0.370368,-0.097132,-0.432161,-0.663102,-0.197369,-0.309156,0.160599,-0.387808,-0.628039,-0.389573,-0.151842,-0.058807,0.359979,0.068194,-0.016061,0.412727,0.501910,0.422534,0.096868,0.220056,-0.044123,0.083632,0.468555,-0.274741,-0.463415,-0.060691,0.007927,0.000413,0.017774,0.339483,0.043493,0.144763,0.204867,-0.281210,0.097133,-0.268134,0.239305,-0.148500,0.205511,-0.116466,0.220913,-0.385981,0.183185,0.407856,0.187205,0.077991,-0.130734,0.089554,-0.747050,-0.065939,-0.001593,0.217000,-0.458559,0.192518,-0.145574,-0.167153,0.041926,-0.100643,0.061053,-0.024166,0.107288,-0.166006,-0.002839,0.233647,-0.362113,0.152492,0.357382,0.086446,-0.265886,-0.120640,-0.106253,-0.587744,-0.176150,-0.110697,-0.432255,-0.460208,0.233842,-0.305652,0.255930,0.731239,-0.634954,-0.096436,-0.142715,0.204138,-0.366836,-0.064036,0.198795,-0.743735,-0.258985,-0.470986,0.009416,0.024558,0.053839,-0.218459,0.685484,-0.614556,0.189617,0.278148,0.008130,-0.333432,0.569946,0.177479,0.302307,-0.408798,-0.163740,0.632049,0.378459,0.202578,0.020740,0.105309,-0.272970,-0.471272,-0.061307,0.308644', '4301278', '35161768', '1482099', '1793922');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6424814', '分歧者：异类觉醒', '动作', '一百年前，席卷全球的战争让几乎所有的国家都从地球上消失，幸存的人类聚集在破败的芝加哥。新世界的创始者为了谋求永久的和平，将幸存者们分成了无私派、诚实派、无畏派、友好派和博学派。每个派系都有自己专门的社会职责，他们通力合作促进这个世界的进步。美丽女孩碧翠丝（谢琳·伍德蕾 Shailene Woodley 饰）出生于无私派家庭，她和其他同龄人一样，将在16岁那年决定自己终身所属的派系。然而测试表明她是一个极为少见的分歧者，碧翠丝不顾测试官的劝阻，毅然选择了无畏派。在这个勇士的集团，她必须和伙伴们接受最为严苛的训练。而她所坚守的秘密，也将成为影响其终身的重要因素……©豆瓣', '谢琳·伍德蕾', '尼尔·博格', 6.6, 121195, 'tt1840309', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196353608.jpg', 2.4, 11.5, 49.1, 28.2, 8.9, '0.212523,0.306321,-0.651943,0.869039,-0.540008,0.021854,0.360001,0.123687,-0.376131,-0.250551,0.149334,0.989252,0.363859,0.307849,0.101059,-0.345997,0.093477,-0.743124,-0.476614,-0.280204,-0.391075,-0.500718,-0.013950,-0.323334,-0.312131,-0.385799,0.836318,-0.036638,-0.311902,0.285723,0.338332,0.370919,-0.163730,0.432229,-0.194158,-0.276529,0.292478,-0.062375,-0.340149,0.145732,-0.383686,-0.028579,0.046193,0.328279,-0.328355,0.365435,0.556511,-0.420229,-0.266487,-0.242135,0.429143,-0.507407,-0.169243,0.243537,0.460723,0.053991,-0.221190,0.534881,-0.034935,-0.117750,0.028457,-0.043482,-1.203291,-0.360654,0.570974,-0.040400,-0.984122,0.633456,0.123917,-0.245443,-0.059725,-0.140676,0.259786,0.881070,0.080563,0.249175,-0.171558,0.023183,-0.435047,0.299738,0.822210,-0.223695,-0.626128,-0.066444,-0.546076,-0.519363,0.221622,-0.682497,-0.352498,-0.166288,0.246432,-0.086914,0.119797,0.335354,-0.776853,0.189389,-0.076935,-0.650653,0.187231,-0.608509,0.169576,-0.644291,-0.108155,-0.474682,-0.454705,0.089694,0.168671,-0.213717,1.368236,-0.825582,0.102602,0.616718,0.293874,-1.037684,0.968105,0.013271,0.246063,-0.288560,-0.137981,0.312156,0.212713,0.567539,-0.162362,0.259465,-0.227882,-0.012741,-0.566918,0.369513', '27602116', '24284209', '30163500', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6425116', '倭寇的踪迹', '剧情', '万历年间，天下太平。早年倭寇横行，幸得戚继光和俞大猷两位将军平定，终于换得今日的内外祥和。此时武林由四大家族坐镇，任何人试图开宗立派须经四大门派同意方可。某天，城内刀光四起，两名手持倭刀的神秘之人令武林大乱阵脚。当年戚继光从倭刀的持法中悟出玄机，因此对倭刀进行改良，以彼之道还之彼身，令倭寇闻风丧胆。随着戚继光去世和天下安定，戚家倭刀渐渐失传，中原武林也斥之为邪道不予承认。这二人正是戚家军营的高手，他们挑战四大门派，只望为戚家倭刀正名。而武林各派也干脆将他们当作倭寇予以围捕，连归隐山中多年的霜叶城第一高手裘冬月（于承惠 饰）也下山擒贼……©豆瓣', '于承惠', '徐浩峰', 7.3, 32267, 'tt2044077', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1422970887.jpg', 2.2, 6, 33.4, 42.8, 15.6, '-0.027703,0.057373,-0.430822,0.479651,0.416164,0.237039,-0.143524,-0.170463,-0.835405,-0.446828,-0.000347,0.455607,0.229991,0.044789,0.183658,-0.456538,0.146482,-1.015192,-0.218413,-0.252169,0.095836,0.081870,-0.160276,-0.005881,-0.398447,-0.177438,0.508748,0.448366,-0.188608,0.546548,0.064027,0.280285,-0.266965,0.150340,-0.335070,-0.303089,-0.116556,-0.076838,-0.545661,-0.038948,-0.625163,-0.562273,-0.333188,0.085627,-0.183186,0.300881,0.050648,-0.308429,0.090131,-0.347440,-0.143716,-0.107458,-0.327411,0.057761,0.643377,0.039933,0.210817,0.627141,0.069683,0.162205,-0.437175,-0.086812,-0.585676,-0.015279,0.286258,-0.265728,-0.322979,0.333263,-0.100519,-0.345945,-0.328446,-0.214116,0.191814,0.447373,0.151658,-0.224119,-0.058267,-0.234588,-0.475451,0.515931,0.539962,-0.287344,-0.049627,-0.450243,0.650443,-0.301711,0.194217,-0.583823,0.020379,-0.191062,0.390866,-0.198512,0.383467,0.300010,-0.171660,-0.099473,-0.276244,-0.117211,0.147492,0.107847,0.046987,-0.441344,-0.093709,-0.248815,-0.252784,0.099585,0.450435,0.183663,0.847359,-0.532715,0.060713,-0.254890,0.011725,-0.625647,0.374204,0.050435,0.387358,0.100593,-0.412573,0.132885,0.401674,0.467212,0.099155,0.091985,-0.297436,-0.215787,-0.067768,-0.138315', '1295987', '1295703', '10561880', '1298443');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6425147', '我们的存在(下)', '剧情', '自钏路一别，高桥七美（吉高由里子 饰）和矢野元晴（生田斗真 饰）这对情意浓浓的小情侣，彼此可能谁也没想到，这次分别竟会如此之久。最初的日子里，他们按时发短信、传照片、打电话，相互鼓励。元晴在继续学业的同时，不得不背着学校打工贴补家用，虽然也结识了千见寺亚希子（比嘉爱未 饰）这样的好友，但越来越残酷的现实却将他的自信和乐观击得粉碎。渐渐的，他中断了和七美的联系，仿佛从她和好友竹内匡史（高冈苍佑 饰）的世界中凭空消失了一般。多年过去，如愿考取东京的七美也面临就职的重要时刻。只是无论时光如何流转，她对那个人的思念与寻找从未停止，这注定是七美，同时也是元晴一生的负累……本片根据漫画家小畑友纪的同名原著改编，分两部上映。©豆瓣', '生田斗真', '三木孝浩', 7.4, 17576, 'tt2002626', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1747235060.jpg', 0.8, 4.9, 36.4, 39.7, 18.2, '0.073463,0.125147,-0.647315,0.592430,0.034255,-0.237339,0.563481,-0.028685,-0.332303,-0.229070,-0.112715,0.833406,-0.328762,0.253974,0.029428,-0.093095,-0.178332,-0.859872,-0.087005,-0.268683,-0.042955,-0.417852,-0.296645,0.150413,-0.167489,-0.097814,0.577435,0.108113,0.056198,0.588184,0.299728,0.176072,-0.257724,0.522710,-0.041228,0.150169,-0.107930,0.475206,-0.246130,-0.052929,0.239443,-0.387592,-0.180011,0.137461,0.018263,0.451013,0.639476,-0.115775,-0.293509,0.194631,0.409476,-0.131113,-0.293120,0.085653,0.165060,0.051653,0.286891,0.384999,-0.210919,-0.173311,-0.062133,0.121523,-0.678191,0.013057,0.242533,0.052961,-0.351903,0.409023,-0.020809,0.011052,-0.025606,-0.149977,0.156966,0.363949,0.214890,0.310730,-0.379892,-0.073439,-0.116583,0.386281,0.691848,-0.119636,-0.318137,0.506688,-0.119037,-0.278724,-0.156713,-0.136303,-0.388727,0.017463,0.070409,0.166748,-0.096411,0.120790,-0.445490,0.052656,-0.180901,-0.148711,0.124476,-0.530509,-0.017648,-0.328738,-0.073223,-0.797222,-0.405196,0.106452,0.171026,-0.254776,0.898143,-0.821276,0.112793,0.396730,0.360567,-0.401614,0.647343,0.134128,0.021105,-0.165515,0.021635,0.133973,-0.107024,0.235241,0.336365,0.365843,0.077616,-0.000608,-0.511420,0.389679', '30162520', '1292219', '3811356', '26809007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6430835', '猎杀本·拉登', '剧情', '2001年震惊世界的911事件后， 美国发动追捕和猎杀行动，目标是基地组织头号人物——奥萨马·本·拉登。玛雅（杰西卡·查斯坦 Jessica Chastain 饰）是美国中情局一位干练坚韧的女探员，她被派赴美国驻巴基斯坦使馆工作，唯一的任务就是寻找到本·拉登。尽管对当时局内使用酷刑审讯恐怖分子感到不忍，但她坚信获得重要信息的前提高于一切。她将人生的10年锲而不舍的投入到一件事上：从浩如烟海的反恐情报中寻找到一根稻草，然后用它压死一只叫做本·拉登的骆驼。最终她的努力获得回报——2011年5月1日，美国海豹突击队根据她的情报潜入巴基斯坦展开斩首行动，成功击毙奥萨马·本·拉登。而在这一切结束后的玛雅却不知道该何去何从……由影史唯一一位奥斯卡女性导演凯瑟琳·毕格罗执导的《猎杀本·拉登》汇集前作《拆弹部队》的原班底，聚焦美国反恐十年，讲述世界上有史以来规模最大的一次追捕和猎杀行动。', '杰西卡·查斯坦', '凯瑟琳·毕格罗', 7.7, 58575, 'tt1790885', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1769852706.jpg', 0.7, 2.8, 28.2, 49.6, 18.7, '-0.068934,0.041721,-0.766908,0.644652,-0.109642,-0.056615,0.275164,-0.322216,-0.274573,-0.204402,0.334420,0.561294,0.105386,-0.193650,0.422198,-0.056212,-0.256952,-0.596691,-0.059421,-0.287618,-0.222220,-0.527301,-0.565053,-0.524298,0.218859,-0.491650,0.736378,0.203146,-0.343425,0.332557,0.219966,0.509784,0.088819,0.318211,0.024737,-0.353763,0.305079,-0.146829,-0.283228,0.367654,-0.144962,-0.316159,-0.276248,0.157254,0.061849,0.399479,0.609623,-0.501793,-0.178944,-0.327999,0.294625,-0.597731,-0.156563,-0.182329,0.420156,0.125979,-0.167668,0.463668,-0.094518,0.035944,0.003102,-0.365843,-0.845908,-0.307688,-0.035432,0.074343,-0.431978,0.071186,-0.363221,0.544527,0.062265,-0.398794,0.101322,0.582891,0.310570,0.098787,-0.039420,0.245629,-0.455876,0.310746,0.741145,-0.275683,-0.206931,0.035994,0.083230,-0.549120,-0.002972,-0.323688,-0.028877,-0.010655,0.198258,-0.000607,-0.071475,0.081473,-0.550146,-0.143421,-0.333220,-0.573600,0.014724,-0.337277,-0.010826,-0.699413,-0.122156,-0.153126,-0.246577,0.019509,0.221124,-0.251897,0.865997,-0.561573,0.238545,0.592288,0.088055,-0.593803,0.499832,0.078012,0.184720,-0.406194,-0.043911,0.373942,0.273397,0.399644,0.065284,0.058469,-0.079731,-0.297248,-0.471776,0.252208', '25928048', '30163500', '27602116', '3001114');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6431054', '夺命追踪', '剧情', '吉尔·帕瑞斯（阿曼达·塞弗里德 Amanda Seyfried 饰）下完夜班回到家发现她妹妹莫莉（艾米莉·维克夏姆 Emily Wickersham 饰）被绑架走了。吉尔一年前曾从某个绑架者手中逃脱，她相信这次还是这个罪犯找上门来要再次抓住她，没抓到她却把莫莉劫持走了。警察自上次吉尔报案没查到绑匪任何踪迹后就认为吉尔神经错乱，不愿意动用他们的资源帮助她。警方坚持茉莉只是一时失联应该很快就会回家，对吉儿的报案并不认真当一回事，但吉儿知道茉莉可能很快就会遭遇不测，心急如焚的她只能靠自己的力量，这次她必须再度跟她不愿面对的梦魇周旋。然而只剩12小时了，究竟一切只是她不正常的幻想还是真有其事？她是否还来得及救出亲爱的妹妹？她决定不顾危险自己一人去追查真相，所有答案再度指向那片树林静处，无人知晓的神秘深洞里……©豆瓣', '阿曼达·塞弗里德', '埃托尔·达利亚', 6, 11008, 'tt1838544', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1519273394.jpg', 3.4, 20.1, 55.6, 16.3, 4.6, '0.296569,0.299696,-0.699882,0.031441,-0.191559,-0.319507,0.466049,-0.237934,-0.414406,-0.214558,0.173065,0.262231,0.109050,0.077291,0.017460,0.339658,-0.601626,-0.634005,0.180613,-0.267319,-0.487536,-0.581049,-0.332984,-0.148075,0.044104,-0.063111,0.311752,0.037960,-0.181731,0.095599,0.295055,0.167037,-0.109554,0.809191,-0.138954,0.298245,0.028410,-0.052651,-0.099761,0.271768,0.288812,-0.274948,-0.156481,0.166291,0.056679,0.428589,0.224421,-0.139961,-0.127677,-0.010825,0.174555,-0.389523,0.068772,0.201734,0.222749,-0.293559,0.088768,0.122781,-0.444668,0.083714,0.091038,0.273389,-0.448456,0.185887,-0.188145,0.476158,-0.400063,-0.131174,-0.318619,-0.057746,0.217604,-0.315465,-0.061719,0.457748,0.025904,0.018677,-0.145535,-0.261803,-0.604476,0.048538,0.714849,-0.247823,0.052791,0.330670,0.124117,-0.329587,-0.018307,0.004671,-0.245134,0.219179,0.438935,0.524423,-0.394130,0.099993,-0.004285,-0.220003,-0.559600,-0.152579,-0.078137,-0.433432,0.056390,-0.212663,0.011504,0.002922,-0.430872,0.126856,-0.070027,-0.207888,0.185259,-0.522834,0.257131,0.629084,0.640403,-0.366102,0.335737,0.103683,-0.111426,-0.074336,0.179937,0.262540,0.190614,0.462152,0.356624,0.165078,0.575694,-0.285029,-0.272647,0.250959', '35073886', '3445575', '1292064', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6432898', '未来学大会', '科幻', '曾经名噪一时的女明星罗宾·怀特（罗宾·怀特 Robin Wright 饰）早已过气，45岁的她因为执拗和任性毁掉的很多机会，也让公司老板杰夫（丹尼·赫斯顿 Danny Huston 饰）渐渐失去了耐心。杰夫逼迫她签下演员生涯最后一份合约，从此罗宾的名字和三维扫描后的虚拟 形象只能出现在公司的展示墙上和数字时代的电影中。罗宾起初极度抵制，但在经纪人艾尔（哈威·凯特尔 Harvey Keitel 饰）的竭力劝说下，同时考虑到儿子亚伦（柯蒂·斯密特-麦菲 Kodi Smit-McPhee 饰）的状况，这个倔强的女人选择妥协。20年后，罗宾驱车前往亚伯拉荷马参加未来学大会，而那里是一个全动画封锁区。以动画形象示人的罗宾将经历一次难忘的旅程……本片根据波兰科幻、哲学、未来学作家斯坦尼斯拉夫·莱姆的短篇小说改编。©豆瓣', '罗宾·怀特', '阿里·福尔曼', 7.8, 12966, 'tt1821641', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2156549383.jpg', 0.8, 3.4, 24.4, 46.6, 24.8, '0.188283,0.109985,-0.439376,0.676024,0.003090,-0.466913,0.370406,0.125928,-0.471888,-0.163659,0.124779,0.810625,-0.244029,0.254155,0.495156,-0.123901,-0.553885,-0.710194,0.025438,-0.048135,-0.063729,-0.621535,-0.236996,-0.235093,-0.111315,-0.356683,0.743811,-0.245342,-0.275541,0.414697,0.340472,0.261252,-0.081716,0.236224,0.153528,-0.006569,0.295202,-0.212366,-0.382685,0.186185,0.093002,-0.089423,-0.056396,0.192518,0.003367,0.387501,0.481167,-0.317283,-0.002624,-0.140115,0.510714,-0.189894,-0.138913,-0.057974,0.017077,0.020125,0.285331,0.193817,-0.099955,-0.028123,-0.116974,-0.150015,-0.610613,0.024736,0.088321,0.284133,-0.597891,0.374531,-0.339743,0.077151,0.001373,-0.439479,-0.066065,0.082389,0.481569,0.167104,-0.042738,0.140459,-0.160428,0.248955,0.195330,0.037180,-0.359756,0.309167,-0.228065,-0.283447,-0.186338,-0.215732,-0.607520,0.076865,0.062126,0.002553,-0.088640,0.172121,-0.710394,-0.329281,-0.376294,-0.363650,0.105349,-0.222984,0.005784,-0.808066,-0.203842,-0.149316,-0.170753,-0.252932,-0.109919,-0.278071,0.605036,-0.613421,0.214347,0.410150,0.248465,-0.235578,0.652226,0.073283,0.108500,-0.237097,0.027227,0.467505,0.072305,0.062512,-0.123800,0.302286,0.267241,-0.364548,-0.230003,0.733058', '1870681', '1793922', '30229667', '3014200');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6433905', '大师', '剧情', '1949年，太平洋战争已经结束，备受军中无聊生活困扰的弗雷迪·杰奎（华金·菲尼克斯 Joaquin Phoenix 饰）终于返回美国，然而返家前的精神治疗没有给他实际的帮助，弗雷迪陷入了一种恍惚乏味的人生体验无法自拔。次年，在经历了一系列工作失败后，弗雷迪在醉后登上的客 船上结识了经历复杂的“大师”卡斯特（菲利普·塞默·霍夫曼 Philip Seymour Hoffman 饰）。卡斯特建立在时间理论之上的精神治疗法引起了弗雷迪的兴趣，在卡斯特的“引诱”下，弗雷迪尝试敞开心扉，寻求解决自己的问题，并越来越亲近卡斯特松散的“缘教”组织，为其摇旗呐喊、打击异议者。在“治疗”过程中，弗雷迪与卡斯特的关系分分合合，愈发复杂……©豆瓣', '华金·菲尼克斯', '保罗·托马斯·安德森', 7.4, 18656, 'tt1560747', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1861100192.jpg', 1.2, 5.8, 33.3, 41.3, 18.4, '0.340706,0.202289,-0.624118,0.327252,0.159618,-0.381993,0.607681,0.221936,-0.757769,-0.293377,0.075656,0.292619,-0.027785,0.103583,0.675845,-0.243265,-0.571631,-0.659234,0.199686,0.000416,-0.350417,-0.604124,-0.340757,-0.244128,-0.237871,-0.766959,0.549547,0.089846,-0.220912,0.610847,-0.072734,0.318007,0.235701,0.688485,0.080292,-0.013117,0.264729,0.148290,-0.407978,0.148167,0.051705,-0.335631,-0.227582,0.189186,0.094106,0.393814,0.555699,-0.094649,-0.260037,0.044793,0.235508,-0.112773,-0.045930,0.040817,0.101026,0.234845,-0.016676,0.212702,-0.293727,0.028976,-0.227583,0.010904,-0.822297,-0.027544,0.085428,0.101605,-0.440748,0.522228,-0.082148,-0.031960,-0.296123,-0.269312,0.009890,0.611391,0.542672,0.297873,-0.208943,0.019861,-0.077100,0.113580,0.752548,-0.210215,-0.458298,0.348014,-0.269179,-0.379455,-0.060577,-0.232943,-0.217061,-0.205699,0.260971,0.124954,-0.208527,0.396230,-0.686750,0.111788,-0.301746,-0.394996,-0.082406,-0.097909,0.172795,-0.698903,-0.381405,-0.197076,-0.420962,-0.115196,0.091511,-0.345318,0.411108,-0.762489,0.443976,0.435953,0.069474,-0.268329,0.526765,0.074629,0.323419,-0.228826,-0.061885,0.584264,-0.198886,0.209403,-0.091783,0.390504,0.049564,0.008311,-0.472105,0.378923', '11541282', '3104798', '4767216', '6790253');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6435936', '双雄', '动作', '夜深人静的英国伦敦，狡猾精明的犯罪分子雅克布·斯特恩伍德（马克·斯特朗 Mark Strong 饰）带领手下洗劫位于中心地带的银行。事成之后，他与手下驾驶摩托逃离现场，而勇猛果敢的警察麦克斯·莱温斯基（詹姆斯·麦卡沃伊 James McAvoy 饰）只身追赶，厮打过程中他被雅可布射中腿部，追捕以失败告终。三年后，藏身冰岛过着无忧无虑生活的雅可布接到一通电话，他的儿子卢恩（伊莱耶斯·加贝尔 Elyes Gabel 饰）被枪射中倒毙伦敦机场。经勘查发现，射杀卢恩的与当年伤及麦克斯的系同一把枪。爱子之死，促使雅可布冒险回到伦敦，而他与老对手麦克斯将展开久违的对决……©豆瓣', '詹姆斯·麦卡沃伊', '伊兰·克里维', 5.9, 7093, 'tt1684233', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2159525420.jpg', 3.4, 20.4, 57.7, 14.1, 4.4, '0.225296,-0.167549,-0.641147,0.465844,-0.058679,-0.199666,0.708354,0.014081,-0.158203,-0.178838,0.407869,0.771913,-0.202819,0.126020,0.416473,0.121165,-0.140090,-0.675401,-0.025995,0.143200,-0.366150,-0.493210,-0.134295,-0.265471,0.126031,-0.279619,0.364684,0.111459,-0.177377,0.709914,0.267062,0.528961,-0.219018,0.320963,-0.092693,0.090258,0.083668,-0.319790,-0.213168,0.245424,-0.068602,-0.147167,0.069903,0.091823,0.092081,0.499153,0.777461,-0.205462,0.395323,-0.313883,0.151864,-0.442886,0.007268,0.022491,0.278770,0.230947,-0.154786,0.103294,-0.130244,0.058692,0.050797,-0.102385,-0.499435,0.163913,-0.213436,-0.119106,-0.748571,0.206999,-0.376184,0.239618,0.008766,-0.232818,0.176245,0.321642,0.149326,-0.038361,0.099870,-0.169708,-0.468510,0.000427,0.465851,-0.542563,-0.223062,-0.063850,0.182922,-0.330542,0.292379,-0.261296,-0.272377,-0.273928,0.523460,-0.159570,0.003596,0.187316,-0.388518,0.006788,-0.627403,-0.094483,-0.112825,-0.167444,-0.193949,-0.837166,0.260462,-0.213521,-0.373420,0.214775,-0.228633,-0.062692,0.184569,-0.554006,0.153699,0.391981,0.439473,-0.114921,0.536401,-0.185310,0.268881,-0.181289,-0.049607,0.719574,0.668997,0.220099,0.196736,0.170055,-0.178626,-0.037202,-0.348242,0.488506', '1316693', '1309194', '1899892', '1308069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6436763', '影子爱人', '喜剧', '柯氏集团的继承人Paris（张柏芝 饰）神秘失踪后，Paris的恋人，总裁助理权正熏（权相宇 饰）为了保护她的继承权利益，策划了一个计谋，找到一个长相酷似Paris的女孩秦芯（张柏芝 饰）来代替她。在权正熏的指导下，秦芯搬进了柯氏大宅，接受作为企业女继承人的种种培训，掩 人耳目。而一心想篡夺Paris继承权的叔叔董傲年却伺机而动，企图揭穿秦芯的假面目。变成Paris的秦芯面临着多重考验，并在与权正熏的相处中暗生情愫，当她想要努力追求这段幸福时，真的Paris却又出现了……©豆瓣', '张柏芝', '潘源良', 4.1, 17326, 'tt2170536', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1533555576.jpg', 31.7, 38.5, 24.1, 3.6, 2.1, '-0.172164,0.155756,-0.469589,0.597807,-0.285657,-0.253452,0.552612,0.223290,-0.344640,-0.414299,0.299737,0.590584,-0.054731,0.468401,0.446451,0.145369,0.001523,-0.569649,-0.189205,-0.270998,-0.173637,-0.207527,-0.361512,-0.198618,0.042121,-0.334880,0.835744,0.016824,-0.150694,0.236486,0.468027,-0.013250,-0.178221,0.364074,0.119232,-0.033237,-0.024296,0.103453,-0.336613,0.089941,-0.190688,-0.303217,-0.149501,0.181974,-0.052258,0.460474,0.467928,-0.227974,-0.066442,-0.304271,0.295768,-0.478807,-0.087658,0.052429,0.243491,-0.021988,0.058331,0.398792,-0.468484,-0.270412,0.225721,0.045574,-1.024044,-0.127856,0.234342,0.134772,-0.527170,0.516177,-0.108989,-0.040043,0.019024,-0.220984,0.207959,0.288825,0.179665,0.495590,-0.201470,0.412267,-0.545286,0.250665,0.459358,-0.191687,0.084212,0.295238,-0.290118,-0.217504,0.130253,-0.172452,-0.523181,-0.257759,0.292416,0.122127,-0.145662,0.026888,-0.398141,-0.095328,-0.269618,0.192981,0.227934,-0.605566,0.127602,-0.449843,-0.301619,-0.323015,-0.174991,0.034621,0.134394,-0.470432,0.560359,-0.828913,-0.021836,0.517577,0.434699,-0.683357,0.428746,0.351937,0.127540,-0.291974,-0.389362,0.172683,0.043659,-0.034489,-0.113961,0.344740,-0.047981,-0.085741,-0.229969,0.172472', '1793491', '26678784', '30163500', '3670447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6436977', '男孩与鹈鹕', '喜剧', '故事发生在风景美丽如画的希腊小岛上，亚尼斯（弗朗索瓦-格扎维埃·德梅松 François-Xavier Demaison 饰）是生活在那里的一名14岁的少年。母亲在很早之前就离开了亚尼斯，现在他和父亲戴蒙思内（埃米尔·库斯图里卡 Emir Kusturica 饰）过着相依为命的日子。戴蒙思内是一个非常严肃和古板的男人，平日里不苟言笑，并且对亚尼斯缺少关怀，随着时间的推移，父子两人之间的距离越来越远。一次偶然中，亚尼斯在岛上发现了一只濒死的鹈鹕宝宝，善良的亚尼斯偷偷收养了这只小鹈鹕。因为害怕爸爸责怪自己，亚尼斯并不敢将鹈鹕的事情告诉爸爸，而这只渐渐康复长大的小鹈鹕这让亚尼斯成为了小岛上的风云人物。©豆瓣', '弗朗索瓦-格扎维埃·德梅松', 'Olivier Horlait', 8.1, 8493, 'tt1891942', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1029880661.jpg', 0.2, 1.2, 18.9, 54.1, 25.6, '0.399583,-0.124222,-0.669163,0.511973,0.284182,-0.343048,0.919290,-0.109450,-0.562767,-0.279959,-0.006560,1.073499,-0.091069,0.411265,0.243276,0.679715,-0.640805,-0.745237,-0.119380,-0.537475,-0.196026,-0.797068,-0.419005,0.108501,-0.196116,-0.637325,0.276656,-0.062096,0.069764,0.564509,0.166806,-0.068277,0.037694,0.166662,-0.048815,-0.015711,0.126473,-0.155615,-0.114166,-0.195809,0.113388,0.068086,-0.328710,0.305653,0.551500,0.345395,0.546843,-0.577021,0.103294,-0.141088,-0.069893,-0.252781,-0.081769,0.051722,0.035557,-0.371225,0.341210,0.352375,-0.329495,0.016335,-0.102474,-0.250818,-0.432763,0.652780,-0.256251,0.268861,-0.488929,0.491515,-0.087281,-0.140393,0.240507,-0.481310,0.118270,0.397139,-0.115204,0.251132,-0.271199,0.015601,-0.508625,-0.197851,0.686894,0.282427,-0.207863,0.284397,-0.505399,-0.466762,-0.396805,-0.526149,-0.467153,-0.215498,0.203733,0.132773,-0.357611,0.663025,-0.736916,0.185749,-0.383462,-0.233802,-0.109806,-0.218654,-0.306799,-0.345439,-0.103783,-0.849120,-0.547840,0.030252,-0.229562,-0.388169,0.692322,-0.858121,0.547186,0.399844,0.559497,0.018035,0.873252,0.281530,0.155146,-0.096734,-0.107958,0.509387,0.112559,0.038526,0.190146,0.300811,-0.089245,-0.262743,-0.668089,0.864923', '3230121', '3055049', '30162520', '26809592');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6511042', '梅奇知道什么', '剧情', '故事发生在繁华的大都市纽约，这里的生活对于年幼的女孩梅奇（阿娜塔·阿普洛 Onata Aprile 饰）来说却并不轻松。梅奇的母亲苏珊娜（朱丽安·摩尔 Julianne Moore 饰）是一个过气的摇滚明星，年老色衰的她日日郁郁寡欢，陷入愤怒的情绪中无法自拔，苏珊娜的丈夫比尔（史蒂夫·库根 Steve Coogan 饰）则是一个神经质的艺术品商人，两人的婚姻早已名存实亡，而梅奇的存在让他们都不甘心放手。眼看着离婚无法避免，争夺梅奇的抚养权成为了苏珊娜和比尔两人的头等大事，为此，他们甚至找到了林肯（亚历山大·斯卡斯加德 Alexander Skarsgård 饰）和玛歌（乔安娜·万德汉姆 Joanna Vanderham 饰）作为新的伴侣，以此增加各自手中的筹码。家庭中，每个人都在战斗，却没有人关心梅奇真正的想法，除了林肯和玛歌。©豆瓣', '阿娜塔·阿普洛', '斯科特·迈克吉', 8.2, 11428, 'tt1932767', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1891773672.jpg', 0.2, 1.3, 17.2, 52, 29.3, '0.349999,0.121585,-0.757821,0.597116,-0.150503,-0.281279,1.058554,0.160609,-0.455895,-0.365156,0.010121,0.810232,0.069602,0.304135,0.103992,0.083704,-0.470217,-0.800130,0.008727,-0.111144,-0.158326,-0.531843,-0.330825,-0.242754,-0.195168,-0.257191,0.593287,-0.024015,-0.035311,0.423399,0.345318,0.374699,0.030263,0.533427,-0.110158,0.044341,0.195289,0.016457,-0.338264,-0.069335,-0.023710,-0.005293,-0.043962,0.410116,0.124397,0.381675,0.528847,-0.475902,0.156500,-0.024978,0.186700,-0.263458,-0.070162,0.118311,0.070548,-0.302430,0.149819,0.133503,-0.269670,0.031987,0.340997,-0.042177,-0.948782,0.176565,0.346285,0.441403,-0.499958,0.660840,-0.263424,-0.163957,-0.031230,-0.187789,0.315309,0.284920,0.319385,0.444751,-0.212157,0.016358,-0.769369,0.169895,0.687942,0.234152,-0.447190,0.272640,-0.615023,-0.506718,-0.257016,-0.377155,-0.833012,-0.168604,0.373821,0.119097,0.020325,0.448084,-0.445427,-0.032204,-0.062046,-0.294766,0.093850,-0.458177,0.031697,-0.497532,-0.151600,-0.742587,-0.422556,-0.094696,-0.042813,-0.280766,0.724172,-0.759745,0.151674,0.353225,0.313014,-0.510927,0.838680,0.149058,0.256309,-0.306139,-0.030953,0.474062,-0.118587,-0.104567,0.082222,0.108971,-0.017379,0.009486,-0.189002,0.735260', '1417428', '1303077', '24756472', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6514083', '芭比', '剧情', '《芭比》入选了韩国的文化工程“电影，与韩国相遇”。扮演顺英的金赛纶和扮演顺子的金雅纶在现实生活中就是一对亲姐妹。善良淳朴的韩国少女顺英（金赛纶 饰）家中除了有一个智障的父亲和流氓叔叔望泽（李天熙 饰）之外，还有一个身体不健康的妹妹顺子（金雅纶 饰）需要她照顾，因此小 小年纪的顺英便充当起了整个家的家长。她和美国少女芭比（凯特·波茨沃斯 Kate Bosworth 饰）之间产生了一份跨越国境的真挚友谊。但是芭比的妹妹身体一直不好，为了获得拯救女儿性命的机会，芭比的父亲决定通过“跨国领养”这一国际制度来获取移植器官。而叔叔望泽在获悉通过国际领养能够让自己获利金钱的利益后，也打起了将侄女顺英送去美国人家领养的念头。妹妹顺子在知道这次机会以后千方百计希望可以取代姐姐去美国生活。但是她并不知道，等待她的将是什么......©豆瓣', '李天熙', '李尚宇', 7.1, 9392, 'tt2074334', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1740814407.jpg', 0.9, 5.1, 44.6, 37, 12.4, '0.062509,0.087216,-0.551935,0.699151,-0.356575,-0.369132,0.522109,0.159464,-0.277612,-0.083482,0.001538,0.805154,0.194057,0.338212,0.114222,0.195463,-0.180127,-0.532428,-0.026716,-0.160637,-0.199822,-0.504637,-0.199013,-0.108199,-0.172817,-0.319441,0.583774,-0.298283,-0.192159,0.438298,0.290823,0.010027,-0.039571,0.141224,-0.214027,0.051495,-0.034731,0.183860,-0.533645,0.384196,0.173728,0.155830,0.124045,0.149755,0.174082,0.325224,0.582084,-0.183253,0.034004,-0.302511,0.456524,-0.085445,0.083216,0.044017,0.085293,-0.070774,0.359561,0.139482,-0.252518,-0.070518,0.335033,-0.261658,-0.751535,0.055701,0.296210,0.084860,-0.705333,0.284484,-0.065798,-0.237555,0.194802,-0.428773,0.308492,0.518284,0.181213,0.395695,-0.371020,0.307042,-0.493580,0.212809,0.679249,-0.178982,-0.010796,0.343129,-0.373801,-0.356540,0.235275,-0.337440,-0.486051,0.029113,0.215248,-0.195876,-0.281105,0.101695,-0.530319,-0.077783,-0.162396,-0.144649,0.277616,-0.593794,0.243932,-0.288878,-0.163286,-0.363429,-0.213216,0.074724,0.296021,-0.353519,1.052241,-0.919133,0.138507,0.701041,0.592403,-0.678033,0.792587,0.203747,0.208602,-0.352848,0.105133,-0.155107,-0.056159,0.008870,-0.024877,0.156037,0.015008,-0.156772,-0.297381,0.241253', '35048413', '24284209', '3445516', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6514105', '夏日乐悠悠', '喜剧', '一次溺水意外，让夏米（杨颖 饰）失去了双亲，是渔夫叔叔给了她第二次生命。她发奋努力，凭借会唇语的优势，在律师事务所担任助理调查员，并适时地抓住机会，拿到了一次去马来西亚美丽海岛的调查机会，因为客户怀疑游乐乐（彭于晏 饰）在实行诈骗。她一上岛，就目睹了一场海盗劫持人质的事件，她及时出手相救，没想到竟然闹出笑话。原来，游乐乐喜欢独出心裁帮恋人制作创意婚礼。经过几次捣乱，游乐乐和夏米成了欢喜冤家。夏米假装不要工钱，替游乐乐打工，希望能够挖到他诈骗的犯罪证据。然而，在撮合了一对即将结婚却闹分手的恋人郝常（朱雨辰 饰）和苏菲亚（周扬 饰）之后，他们加深了了解，冰释前嫌，并且暗生情愫。而就在这时，客户出现了，夏米赫然发现他和游乐乐是同父异母的兄弟，而且在一番明争暗斗之后，她还揭开了一个惊人的秘密……©豆瓣', '彭于晏', '马楚成', 6.1, 47743, 'tt2062580', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1214074618.jpg', 5.9, 17.9, 47.4, 20.8, 7.9, '0.134685,-0.051239,-0.751995,0.300895,-0.181551,-0.407664,0.404276,0.052999,-0.406503,-0.059818,0.023191,0.512783,-0.418405,0.217382,0.137969,-0.143922,-0.182831,-0.579153,0.266527,-0.084916,-0.066191,-0.378797,-0.124675,-0.161789,-0.045319,-0.322187,0.311715,0.145895,-0.199237,0.436614,0.221779,-0.031209,-0.233744,0.551595,-0.026220,-0.046697,0.158529,0.198275,-0.501808,0.336447,0.020503,-0.258488,-0.078089,0.280165,0.043847,0.364930,0.630869,-0.038924,-0.352089,0.135481,0.295972,-0.320603,0.191603,0.042892,0.396933,-0.023990,0.167501,0.097247,-0.483158,-0.005880,0.277887,-0.115709,-0.399302,0.063578,0.051774,-0.233355,-0.562045,0.454387,-0.108046,0.089994,0.044112,-0.197822,0.255969,0.454108,0.407798,0.069221,-0.116898,0.137046,-0.423359,0.328368,0.657863,-0.146226,0.274343,0.561013,0.096959,-0.247975,0.050055,-0.133145,-0.040710,0.169376,0.459467,-0.247905,-0.279500,-0.037576,-0.414727,-0.228537,-0.413140,0.113198,0.013631,-0.397844,0.016381,-0.475838,-0.160299,0.013937,-0.236656,0.187119,0.051143,-0.421523,0.423572,-0.849395,0.061159,0.631100,0.213042,-0.756050,0.554214,0.187326,-0.157233,-0.371894,0.010468,-0.154270,0.102881,0.120617,0.197343,0.122115,0.152377,-0.148765,-0.113295,0.100838', '1301022', '25908042', '35073886', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6514136', '百家乐翻天', '喜剧', '舒奇（杜汶泽 饰）和香香（薛凯琪 饰）同为烂赌之人，二人因在澳门赌博时同时欠下巨额高利贷而相识，并由彼此互看不爽到互生爱意。于是回港后，两人决定结婚。婚后，两人的事业都风生水起。舒奇进入了电影圈并因投资人Michelle（胡然 饰）的垂青而担任男主角。香香则因为赌术精湛而被赌场老板Sam（伍允龙 饰）高薪聘请对付老千。同时，二人事业上的伯乐在生活中也对二人示好并展开追求，更为让舒奇与香香离婚，并且获得女儿的抚养权而不择手段。而最终舒奇和香香也发现，原来他们对彼此来说要比想象中的重要……©豆瓣', '杜汶泽 Chapman To', '王晶', 5.7, 13348, 'tt2308797', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1402120055.jpg', 6.7, 24.1, 50.2, 14.7, 4.4, '0.278491,-0.110068,-0.701759,0.474882,0.075914,-0.559321,0.533710,0.305161,-0.413138,0.054284,0.062432,0.826621,0.014483,0.054575,0.190978,-0.117519,-0.074686,-0.905929,0.000279,-0.202549,-0.052603,-0.614029,0.105081,0.199970,-0.441213,-0.036618,0.540985,0.001596,-0.066769,0.916578,0.475142,-0.140499,-0.252342,0.526809,0.362025,-0.118375,0.051847,0.498977,-0.842871,0.268927,0.097675,-0.055134,-0.153176,0.180209,0.006582,0.389578,0.513385,-0.269938,-0.059287,-0.301714,0.238371,-0.268325,-0.089308,0.186252,0.123300,0.160253,0.635995,0.374945,-0.170379,0.069815,0.116686,0.022904,-0.784944,0.347150,0.305634,-0.243846,-0.492625,0.299013,0.059502,-0.124349,-0.007264,-0.309614,0.044574,0.295384,0.253995,0.169733,-0.544393,-0.001023,-0.361587,0.112498,0.418101,-0.004649,0.232004,0.416347,0.017236,-0.332000,-0.010557,-0.302402,-0.268655,-0.033691,0.206051,0.290283,0.190044,-0.049190,-0.642788,0.084862,-0.072278,0.186485,0.112678,-0.603219,0.198637,-0.726174,-0.423046,-0.503809,-0.327237,-0.088208,0.501645,-0.631745,0.547578,-0.886234,-0.077949,0.330356,0.582057,-0.748509,0.538071,0.176472,0.210418,-0.515461,-0.453455,0.114509,-0.061440,-0.048160,-0.030217,-0.051021,-0.088754,-0.156402,-0.178655,0.279124', '4301278', '1306133', '1299556', '1418613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6515363', '人约离婚后', '剧情', '阿宝（佘诗曼 饰）在与Ryan（方力申 饰）婚礼一个月前，拿到了对方的手机并得到了其中的自拍偷情视频，在二人的婚礼上，阿宝为报复丈夫，将视频当众播放并宣布即刻离婚。但离婚的两人并未割断联系，阿宝租用Ryan的铺面开店，而Ryan则不时需要前妻救场，来赶走那些粘人不放的小情人。Ryan以给前妻找男友为借口，将阿宝诓骗到换妻聚会中，并结识了世杰（罗仲谦 饰）夫妻俩，Ryan与世杰妻子曼丽寻欢，而世杰亦对阿宝动心并展开攻势，阿宝防线终被世杰击破，但他们的交往却引起Ryan醋意。经此一事，Ryan意识到自己始终在乎阿宝，试图挽回失去的爱人……©豆瓣', '佘诗曼', '叶念琛', 6.1, 13879, 'tt1964887', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2072214373.jpg', 4.1, 16.5, 54, 20.4, 5, '0.350018,0.131527,-0.551627,0.416722,-0.023114,-0.337612,0.582093,0.074284,-0.267363,-0.215958,0.031354,0.544399,-0.220837,0.185318,0.039791,-0.061700,0.005276,-0.900430,0.246529,-0.042980,-0.156244,-0.441321,0.100011,0.133392,-0.094861,0.003668,0.578152,-0.317588,-0.202367,0.642533,0.382433,-0.085016,-0.256589,0.604342,0.056060,0.132907,-0.359962,0.234381,-0.545030,0.254811,0.102945,-0.158877,-0.011614,0.219412,-0.024374,0.571168,0.652205,-0.133345,-0.055781,0.007571,0.257464,-0.099273,0.172924,0.184775,0.159807,0.219354,0.333916,0.360797,-0.526847,0.162649,0.229194,0.073295,-0.458514,0.279101,0.041825,-0.013909,-0.336131,0.350258,-0.190701,0.119684,0.138981,-0.258007,0.181265,0.479185,0.040550,0.241170,-0.423769,0.156615,-0.417333,0.132615,0.347930,0.031041,0.451501,0.325358,0.137740,-0.121432,0.194894,-0.131472,-0.334884,-0.034895,0.218999,0.219337,-0.207818,0.076567,-0.549608,-0.247699,-0.215258,0.087430,0.207475,-0.556527,0.165999,-0.577813,-0.241693,0.074845,-0.226239,-0.038074,0.311122,-0.389473,0.345615,-0.827176,0.180156,0.552123,0.640703,-0.737117,0.361482,0.437745,0.163319,-0.299885,-0.176700,0.124262,0.152911,0.161798,0.103110,-0.158115,0.041469,-0.269016,-0.489436,0.321527', '30345227', '1301022', '25777330', '2027925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6516595', '阁楼', '惊悚', '一年前，小有名气的设计师文森特·史蒂文斯（卡尔·厄本 Karl Urban 饰）向好哥们卢克（温特沃斯·米勒 Wentworth Miller 饰）、克里斯（詹姆斯·麦斯登 James Marsden 饰）、马蒂（艾瑞克·斯通斯崔特 Eric Stonestreet 饰）和菲利普（马提亚斯·修奈尔 Matthias Schoenaerts 饰）提出一个大胆的想法，五个人共同出资购买一处位于市中心黄金地段的阁楼，将这里当作逃避世俗烦扰的秘密基地，其规则是绝对不能让各自的妻子知道。他们虽然拥有体面光鲜的工作和优渥富裕的生活，但是在物欲横流的时代里，如此一个密不可宣的所在正好迎合着彼此内心中最阴暗的欲望。在此之后，他们各自沉湎在温柔乡的猎奇之旅中，直到某天早上，一名女子的尸体突然出现在阁楼的床上，五个人的秘密昭然若揭……©豆瓣', '詹姆斯·麦斯登', '艾瑞克·范·洛依', 6.7, 7196, 'tt1850397', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2217470187.jpg', 1.1, 7.7, 53.6, 31.2, 6.4, '0.508072,0.075580,-0.798401,0.653191,0.008362,-0.120306,0.722742,0.226658,-0.475913,-0.420350,0.121426,0.765240,0.048886,0.330714,0.345383,0.073711,-0.341010,-0.583642,-0.145403,-0.565402,-0.380094,-0.485072,-0.357488,-0.343614,-0.228376,-0.168244,0.474798,0.172450,0.044729,0.248994,0.353123,0.385349,-0.124640,0.279311,-0.260208,-0.265870,0.359534,-0.138990,-0.325297,0.124612,-0.272355,-0.041480,-0.165592,0.143555,0.042748,0.214091,0.560426,-0.301005,-0.060169,0.036768,0.174046,0.141095,-0.096212,0.119659,0.045292,-0.372843,0.171769,0.258462,-0.240360,0.027373,0.151230,-0.179690,-0.822177,-0.061884,-0.019708,0.116827,-0.395970,0.470118,-0.043184,-0.141021,-0.109815,-0.330513,-0.014763,0.144378,0.111351,0.269369,-0.172915,-0.106247,-0.489100,-0.078528,0.381948,0.243073,-0.223057,0.201822,-0.307375,-0.375526,-0.054508,-0.107183,-0.670974,-0.413771,0.274005,0.027314,0.099019,0.087583,-0.665574,0.064018,-0.216112,-0.212464,0.094445,-0.268598,-0.108015,-0.526619,-0.062262,-0.311276,-0.359082,0.200991,0.051157,-0.092812,0.648015,-0.727106,0.193786,0.486699,0.202730,-0.379376,0.736739,-0.170943,0.445099,-0.171403,-0.220653,0.230397,0.092125,0.132135,-0.061942,0.420178,-0.178336,-0.072327,-0.439491,0.451857', '1793491', '3055049', '1481233', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6517421', '惊天魔盗团', '剧情', '不夜赌城拉斯维加斯，豪华的表演大厅内正在进行一场前所未有的魔术表演，由丹尼尔·阿特拉斯（杰西·艾森伯格 Jesse Eisenberg 饰）、亨莉·里维斯（艾拉·菲舍尔 Isla Fisher 饰）、杰克·怀尔德（戴夫·弗兰科 Dave Franco 饰）和梅里特·麦克金尼（伍迪·哈里森 Woody Harrelson 饰）四位魔术师组成的“四骑士”配合天衣无缝，在众目睽睽之下偷来了某法国银行金库内350万欧元纸币，此举在现场至全世界引起轰动。FBI探员罗德（马克·鲁夫洛 Mark Ruffalo 饰）和国际刑警埃尔玛·德雷（梅拉尼·罗兰 Mélanie Laurent 饰）奉命对四人展开调查，却一无所获。无奈之下，他们只得求助于极具名气的揭露魔术师布莱德利（摩根·弗里曼 Morgan Freeman 饰）。魔术师、盗贼、FBI探员，光影交错下最精彩的较量，连番上演……', '杰西·艾森伯格', '路易斯·莱特里尔', 7.8, 516094, 'tt1670345', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2151336415.jpg', 0.5, 2.6, 26.1, 49.6, 21.3, '0.042560,-0.097711,-0.481411,0.402935,0.369715,-0.114130,0.692335,0.208086,-0.188594,-0.429325,0.584583,0.679619,-0.572367,-0.019720,0.605076,-0.067422,-0.741468,-0.620772,-0.128356,-0.119035,0.129415,-0.685333,-0.399864,-0.282954,0.022366,0.010022,0.190048,0.007614,-0.029464,0.315215,0.460130,0.530275,-0.229383,-0.210761,0.283901,-0.016711,0.615528,-0.355852,-0.501768,0.106898,-0.131972,-0.106316,-0.192316,0.061776,0.302748,0.110009,0.392747,-0.440608,0.598204,0.068416,0.116887,-0.088138,0.029530,0.053074,0.123029,-0.263533,0.111689,-0.134519,-0.115601,0.056620,0.170360,-0.124132,-0.682809,0.337360,0.107505,0.263019,-0.264195,0.070626,-0.451318,0.108004,0.011243,-0.012693,-0.268374,-0.038759,0.440028,-0.206236,0.264526,-0.170500,-0.244559,0.026267,0.059175,0.282625,-0.207126,-0.203937,-0.347146,-0.378908,-0.088500,-0.200361,-0.220383,-0.194928,0.567694,-0.317811,0.663363,0.185987,-0.639401,-0.165737,-0.550005,-0.303150,-0.381188,-0.081087,0.026358,-1.383968,0.075317,-0.309454,-0.105789,-0.042403,-0.073264,0.063124,0.165687,-0.343090,-0.024300,0.232490,0.027928,0.267397,0.216763,-0.071851,0.326812,-0.063594,-0.391974,0.159286,0.315961,0.169610,0.268912,0.281438,0.192332,-0.130469,-0.096548,0.236916', 