INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6518638', '艾特熊和赛娜鼠', '动画', '一份跨越种族的深厚感情，一次直触心底的神奇旅程。从小生活在孤儿院的小老鼠赛娜几经波折，终于从地下鼠国逃出。可是当她跌跌撞撞地来到熊的王国时，却一路受尽鄙夷和白眼。疲惫的小赛娜沉沉地睡在垃圾桶里，一觉惊醒后发现一只体型硕大的大熊正要把她当作晚餐。然而经过此次的风波后，两人很快成为了朋友。原来这只名叫艾特的熊先生是名街头音乐家兼马戏团演员，多才多艺的艾特还从事过很多职业。热情的艾特带着赛娜到家里住，他们彼此扶持理解，相互鼓励帮助。一份看似不可能发生的友谊，正在挑战着现有的秩序和规则，也正慢慢变得越来越深厚坚实。《艾特熊和赛娜鼠》以温馨的水彩手绘画风和治愈系的内容剧情，荣获2013年第38届凯撒奖最佳动画片，入围2013年第3届北京国际电影节国外展映单元及2012年多伦多电影节“儿童片”展映单元。《艾特熊和赛娜鼠》系列绘本由比利时女作家嘉贝丽·文生创作，多种版本在世界各地畅销200多万册，深受孩子们甚至是成年人的喜爱。', '朗贝尔·维尔森', '斯特凡·奥比尔', 8.9, 42636, 'tt1816518', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1726788921.jpg', 0.1, 0.4, 7.7, 36.6, 55.3, '0.135523,-0.042440,-0.635186,0.570899,0.363383,-0.141059,0.461941,-0.065147,-0.378545,-0.111853,-0.023256,0.698685,-0.351922,0.467530,0.357024,-0.194625,-0.311621,-0.623590,-0.279013,-0.133743,-0.200956,-0.155979,-0.447885,-0.061998,-0.117718,-0.435091,0.534965,0.108502,-0.117358,0.619675,0.269940,0.189808,-0.252726,0.285298,-0.310067,0.071579,0.292134,0.221810,-0.114041,0.065727,0.004510,-0.164522,-0.414490,-0.185461,0.261232,0.045641,0.755081,-0.372577,-0.113011,-0.062624,0.471017,-0.083153,-0.290728,-0.072945,0.373120,0.218808,0.398563,0.240071,0.006984,0.342957,0.049102,-0.434784,-0.627495,-0.144075,0.056713,0.053869,-0.607196,0.420424,-0.099513,0.042657,-0.067833,-0.261691,0.083818,0.293242,0.103049,0.663714,-0.146058,0.324272,-0.354597,0.100082,0.555195,0.074492,-0.477963,0.262804,-0.185484,-0.549184,0.036164,-0.276460,-0.245220,-0.115416,0.377451,0.167862,-0.115025,0.131601,-0.809987,0.136840,-0.053623,-0.375213,0.163506,-0.392759,-0.087125,-0.688996,-0.044734,-0.480376,-0.056709,0.017837,0.210068,-0.407960,0.888794,-0.645918,0.406172,0.246167,0.099746,-0.184710,0.797556,-0.068760,0.041529,-0.055071,-0.060066,0.159529,-0.132076,0.149058,0.229013,0.474637,-0.181923,-0.144223