INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6518721', '夏日恋神马', '剧情', '单身一族的阿泽（方力申 饰）、阿犬（敖犬 饰）和小肥（小肥 饰）生活在香港不同的角落，人人都想尽快结束光棍生活。阿泽自诩“有梦青年”，日夜打着两份工，薪水微薄，伹他乐此不疲。阿泽自认品味高雅，心中的女神是靓模依依（刘羽琦 饰），妹妹笑他不自量力，伹良好的心态加之乐观的性格使阿泽不会气馁，他仍视依依为梦中情人。阿犬是阿泽的死党，同时也是个挂在网上的“全职宅男”，他们全族清一色男性，就连家里养的狗都是公的，伹这并不妨碍阿犬在网上专门诊疗他人婚姻爱情的疑难杂症。 但生活中的阿犬是个胆小懦弱的人，连狗都敢欺负他……©豆瓣', '方力申', '钱国伟', 3.9, 3954, 'tt2011257', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1094358630.jpg', 35.5, 38.9, 21.5, 2.9, 1.3, '0.121939,-0.272764,-0.272513,0.506826,-0.411728,-0.102632,0.500008,0.136054,-0.506178,-0.052489,0.135818,0.544485,0.190502,0.189264,-0.169953,0.180923,-0.195407,-0.550018,-0.166616,0.090512,0.061910,-0.136492,-0.208440,-0.217819,-0.351950,-0.081741,0.452830,-0.355610,-0.017105,0.370703,0.445051,0.069873,0.082570,0.188377,-0.354416,0.088726,-0.113675,0.049201,0.027790,-0.093593,-0.176711,0.018962,0.022441,0.139319,0.245311,0.308074,0.700711,-0.174971,-0.207025,-0.276301,0.207879,-0.055574,-0.175159,0.167228,0.229035,-0.226643,0.451082,0.157702,0.068016,0.004202,0.099212,0.075283,-0.719112,-0.015428,0.282697,0.135078,-0.281551,0.694732,-0.091379,-0.141850,0.130106,-0.224623,0.068507,-0.083736,0.181377,0.315687,0.115157,0.073811,-0.464939,0.423921,0.550688,0.303830,-0.229253,0.460629,-0.513587,-0.357895,-0.000868,-0.310464,-0.831022,-0.142042,-0.274558,-0.158770,-0.306302,0.105012,-0.513774,0.399600,0.142282,0.154500,-0.038889,-0.525904,-0.158781,-0.260545,-0.069311,-0.832317,-0.374083,0.066995,0.254744,-0.381187,0.721122,-0.989808,0.038534,0.496349,0.104399,-0.479191,0.875440,0.262822,-0.149436,0.005092,-0.122878,-0.005038,-0.002014,-0.077717,-0.079994,0.229874,0.133383,-0.194722,-0.253856,0.345047', '6963575', '3445516', '3033092', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6519403', '隔离区2：终点站', '科幻', '在一个平凡的夜晚，美丽的空中小姐珍妮（Mercedes Masöhn 饰）和朋友宝拉（Bre Blair 饰）登上天空航空公司飞往堪萨斯的318次航班，执行有一次看似平常的飞行任务。一如既往，这架小型飞机上聚集着各色各样的乘客，珍妮耐心友善地服务乘客，却不知危险正渐渐逼近。飞行途中，一名肥胖的乘客神态异常，在吐了珍妮一身秽物之后，竟发狂地冲向驾驶舱要求下飞机。机舱内一片混乱，万般无奈之下，飞机只得迫降于洛杉矶机场。而在这一过程中，宝拉也被胖子啃噬，情况危急。机组成员和乘客来到洛杉矶机场，却发现偌大的机场内空无一人，他们仿佛被世人囚禁于一个隔离的区域中……©豆瓣', '梅赛德丝·马索霍', '约翰·波罗', 6.1, 5995, 'tt1699231', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2166888473.jpg', 3.6, 17.7, 54, 19.3, 5.4, '0.429663,0.256684,-0.741249,0.562792,0.300450,-0.060788,1.035788,0.228785,-0.369008,0.029319,0.639874,0.708803,-0.225875,0.145807,0.564647,-0.055373,-0.592007,-0.370385,-0.408844,-0.150392,-0.557547,-0.379660,-0.220928,-0.158264,0.110832,-0.205962,0.531625,0.384789,0.164496,0.756612,0.028580,0.013571,-0.506564,0.758907,-0.264850,-0.324206,0.317243,-0.049668,0.204102,0.230021,-0.367251,-0.442780,0.087584,-0.107196,0.049454,0.459540,1.088601,-0.065191,-0.103242,-0.093373,-0.114688,-0.221867,0.074715,-0.009298,0.295462,0.009834,0.161824,-0.230690,-0.164163,0.176009,0.032571,0.190432,-0.181360,-0.026854,-0.176015,0.054459,-0.360215,0.501782,-0.361900,0.041914,-0.043495,-0.581684,0.213854,-0.093248,-0.155661,0.498928,-0.075388,0.163393,-0.474191,-0.087713,0.509880,0.181432,-0.397227,0.321125,-0.296725,-0.482272,-0.137026,0.007752,-0.523892,-0.467493,0.455924,0.099349,-0.114562,0.056559,-0.536313,0.264120,-0.399404,-0.608170,-0.497486,-0.189395,-0.465676,-0.853847,0.473140,-0.157685,-0.078273,0.312200,-0.235544,0.292095,0.487685,-0.697390,0.246094,0.352938,0.127836,0.048319,0.619392,-0.082194,0.320629,-0.066037,-0.132197,0.135909,-0.034183,0.712244,-0.123623,0.532844,-0.641707,0.020433,-0.601211,0.119234', '10466639', '3011051', '21619567', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6519514', '潮性办公室', '剧情', '被员工认为是没钱赚，没士气，没前途，没妞泡的老字号梅花油公司，周一到周六的上班生活枯燥无味。员工个个空虚懒散，毫无纪律性，上班迟到更是家常便饭。周先生（詹瑞文 饰）是这家公司的经理，喜欢调戏女员工，克扣员工工资。而公司还有缺乏性爱的会计小虾（杨诗敏 饰），猥琐的行政阿泰（邓智坚 饰），天然呆的性感秘书Rachel（吕慧仪 饰）和年老色衰的清洁员大姨妈几位职员。几个人过着打工仔的生活，终日性幻想无所事事。然而有一天，周经理接到大老板的电话，公司被中国成人保健集团收购，公司人事和市场面临全新调配。感到危机的几人决定统一战线，一致对抗新公司。一袭人来到新公司，新公司的总裁Pink（赵彤 饰）在入职第一天就宣布，他们划入催情香薰油部门，薪资将上涨百分之五十，然而几人中，将有人面临裁员。面对这惨烈的竞争，几人只得打起十二分的精神加入到新公司的培训中…该片改编自舞台剧《潮性办公室》。', '詹瑞文', '詹瑞文', 4.6, 6834, 'tt1935855', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1342984062.jpg', 23.3, 35.9, 31.8, 6.9, 2.2, '0.070422,-0.138316,-0.450828,0.061220,-0.151343,-0.229126,0.285775,0.644934,-0.472898,-0.347627,0.073146,0.384690,-0.200585,0.363340,0.564142,-0.301970,0.058940,-0.426676,-0.408478,0.005731,0.044336,-0.260091,0.102285,-0.323977,-0.191737,0.013904,0.429550,0.087773,-0.153573,0.380739,0.279748,0.199967,0.012574,0.422639,0.129703,-0.146205,0.463391,-0.009802,-0.298005,0.254668,0.142360,0.006688,-0.060457,-0.157669,0.525604,0.237325,0.200148,0.315909,-0.381583,-0.141428,0.815653,-0.157302,-0.147182,-0.172867,0.759330,0.343644,0.271374,0.058990,-0.490732,0.190351,-0.034454,-0.380976,-0.699552,0.085518,0.050089,-0.004347,-0.424192,0.360540,-0.164112,0.086486,0.084064,-0.285003,0.151605,0.398045,0.189550,0.367438,0.363847,0.358022,-0.537886,0.353608,0.507425,0.009131,-0.226288,0.077514,-0.176312,-0.134627,-0.022300,-0.284591,-0.259268,-0.146685,-0.042351,0.031819,0.119179,-0.287782,-0.740198,0.217979,0.103208,-0.537170,0.159129,-0.173066,-0.274215,-0.853364,-0.062987,-0.119666,-0.224608,0.233963,0.466603,-0.008829,0.507149,-1.018183,-0.095724,0.378829,0.504489,-0.668523,0.682848,-0.317918,0.153682,-0.265275,-0.075988,-0.350124,0.108845,0.399067,0.047580,0.256569,-0.242134,-0.305568,-0.016792,-0.039325', '20472857', '2