INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6519585', '飞天', '剧情', '能够去往太空中，是每个航天员的梦想。作为中国第一代航天员，张天聪（刘之冰 饰）在神舟七号的选拨中失利了。而他却并没有因此消沉或是选择离开，决定继续留在队里，作为新一代航天员的教官。而在张天聪的心中，依然有着航天梦。面对日益严峻的国际环境，建立永久性的太空空间站对于维护中国的利益，免于受到他国的侵犯有很重大的意义。于是，新一轮的选拨开始了。张天聪加强锻炼，希望实现自己的航天梦，但最终还是与之失之交臂。但张天聪依然不放弃希望，在危难时刻，他拯救了飞船、拯救了寄托所有人希望的航天梦，也实现了自己的梦想。©豆瓣', '刘之冰', '王珈', 3.5, 5796, 'tt2027098', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1095057488.jpg', 64.5, 12.3, 12.9, 5.3, 5, '-0.279425,0.418268,-0.767030,0.835190,-0.025492,-0.437742,0.628521,-0.018967,-0.519028,-0.185723,0.320577,0.746482,0.247038,0.460203,0.098554,-0.055394,-0.326655,-0.467048,-0.014736,0.006644,-0.382978,-0.608077,-0.082528,-0.052263,-0.420985,-0.207752,1.352098,0.278089,-0.460610,0.058678,0.224165,0.181837,0.111425,0.696526,-0.193015,-0.416158,-0.225427,0.110977,-0.628949,0.058090,-0.012579,-0.321273,-0.422670,0.378802,0.179749,0.291369,0.466240,-0.471333,-0.228024,0.040285,0.316618,-0.537368,-0.082020,-0.144476,-0.005015,0.068393,-0.229939,0.146453,-0.027737,0.062461,-0.068907,-0.100006,-0.963144,-0.273378,0.324057,0.202181,-0.439268,0.483869,-0.035567,0.066033,0.296541,-0.128816,0.158947,0.589248,0.527023,0.440153,-0.330111,0.430056,-0.472309,0.064454,0.856307,-0.105023,-0.635841,0.315427,-0.166845,-0.562978,-0.022218,-0.234584,-0.358010,-0.000803,0.094185,0.296919,-0.060631,0.406679,-0.560401,0.315480,-0.313197,-0.485970,0.177269,-0.424792,0.210108,-0.531471,0.002583,-0.406076,-0.284714,0.201492,0.087166,-0.574588,0.846949,-1.143223,0.237381,0.388844,0.180467,-0.537495,0.645411,0.442662,0.157068,-0.303451,0.092052,0.380638,-0.195352,0.456751,-0.447347,-0.068018,-0.050776,-0.045075,-0.167554,0.440442', '26759819', '3861846', '25880986', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6521506', '寒枝雀静', '剧情', '本片是导演有关人性的“生活三部曲”的终结篇章。影片没有线性叙事，由39个场景构成。镜头追随萨姆和乔纳森这对推销搞笑玩具的流动商人的足迹，伴随他们一户户上门兜售商品，如同导游带领观众在不同地点不同人群中游走。影片继承了导演一贯的执导风格，诗意，阴郁，黑色幽默又充满哲学思辨。', 'Holger Andersson', '罗伊·安德森', 7.9, 22344, 'tt1883180', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2209088482.jpg', 1.3, 3.5, 20.6, 46.5, 28.2, '0.385455,-0.268344,-0.355974,0.807938,0.284988,0.072279,1.063125,0.281390,-0.307601,-0.091283,0.297934,0.776005,-0.364029,-0.397995,0.359030,-0.293919,-0.648299,-0.382776,-0.412388,0.167075,0.268139,-0.451259,-0.036819,-0.239002,-0.072017,-0.305156,0.782816,-0.062223,-0.558768,0.727640,0.237113,0.118132,-0.205442,0.054048,-0.198507,0.084942,-0.000149,0.107419,-0.384533,-0.023463,-0.117864,0.061051,-0.218729,-0.262210,-0.260577,0.326750,0.789112,-0.049198,0.256640,0.250699,0.507629,-0.054810,-0.193101,-0.047078,-0.124044,0.361942,0.310004,0.250703,0.257102,-0.024378,-0.345588,-0.306495,-0.831602,-0.188173,0.289741,0.431053,-0.258911,0.304376,0.294469,-0.282821,0.120436,-0.293238,0.133399,-0.583401,0.693081,0.559339,0.451547,0.053651,-0.364884,0.436163,0.368485,0.054956,-0.389051,0.657993,-0.857752,-0.404869,-0.238591,-0.185385,-0.618113,0.013693,0.129514,-0.265153,0.024358,0.150019,-0.817483,0.122087,0.383435,-0.387441,0.068043,-0.538554,-0.105565,-1.192560,-0.200421,-0.492672,0.255958,-0.137590,-0.013210,-0.094400,0.818022,-0.521373,0.042979,0.249252,-0.102133,-0.501453,0.966162,0.015772,-0.400303,-0.569064,0.021069,0.186981,-0.003362,0.196663,-0.109857,0.364466,0.266826,-0.032878,-0.276022,0.567688', '1322847', '26611806', '10466639', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6527170', '一夜未了情', '剧情', '曾经的职业摄影师苏东（方中信 饰），在一次海外拍摄任务之后伤痕累累，身心俱疲。回国后他独自前往云南旅游散心，并在途中结识了美丽的空姐顾婷（李小冉 饰）。这对内心皆很孤独的男女结伴旅行，免不了引出情爱的火焰，然而突发的火灾打断了一切，似乎预示着他们并不顺利的情感交流。回到北京后，顾婷目睹苏东女友接站的一幕，自觉受到欺骗，与此同时与母亲多年来的矛盾也促使她寻找新的生活。另一方面，苏东最终和女友分道扬镳，他对顾婷念念不忘，终于在一份时尚杂志中找到线索。两个一曾断了线的人儿再次相见，一切又将朝着怎样的方向发展？©豆瓣', '李小冉', '江澄', 5.1, 9261, 'tt2473706', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1131823822.jpg', 15.1, 32.4, 39.6, 10.3, 2.7, '0.250181,0.016753,-0.810763,0.604157,0.013180,-0.414893,0.690054,0.045624,-0.598815,-0.258381,0.268443,0.807466,-0.234083,0.325781,0.318124,-0.182331,-0.306255,-0.575796,0.130530,-0.146469,-0.264358,-0.363972,-0.138350,0.004446,-0.056119,-0.156325,0.618370,0.197746,-0.062525,0.674901,0.248301,0.177516,-0.610513,0.744940,-0.093583,-0.066910,0.086474,0.439796,-0.395774,0.211762,0.230657,-0.357848,-0.274313,0.225681,-0.215183,0.306920,0.794044,-0.337106,-0.272731,0.034138,0.348830,-0.347941,0.126100,0.146013,0.018263,0.208973,0.163525,0.219139,-0.474714,-0.029546,0.011372,0.061276,-0.366870,-0.068189,-0.027580,0.303907,-0.669013,0.590123,0.093692,-0.030396,0.230730,-0.409565,0.206551,0.554656,0.472130,0.310476,-0.269460,0.136052,-0.137416,0.197346,0.971841,0.130289,0.018605,0.533522,-0.209279,-0.334323,0.033373,0.194347,-0.352071,0.004048,0.399406,0.412860,-0.249209,0.258178,-0.500991,0.168594,-0.322559,-0.200885,0.027560,-0.453715,0.063347,-0.836247,-0.197244,-0.329996,-0.233340,-0.009159,0.006340,-0.278333,0.609431,-0.809736,0.245585,0.476129,0.152693,-0.708717,0.413459,0.135722,0.045562,-0.391881,0.112550,0.454417,-0.050454,0.391144,-0.056118,0.282649,-0.181182,0.103579,-0.309557,0.498508', '25721544', '11541282', '1301022', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6527269', '危险关系', '剧情', '本片改编自法国著名放荡主义小说，曾经被多次改编成不同版本的电影、影集、舞台剧。三十年代，在日军枪炮下的上海上流社会依旧每天在纸醉金迷的狂欢中迷失。谢易梵（张东健 饰）是风月场上有名的花花公子，莫婕妤（张柏芝 饰）是风情万种却深藏城府的豪门遗孀，两人有着不可分割的亲密关 系。莫怂恿谢去勾引抛弃自己的富商即将迎娶的少女贝贝。而谢则觉得不够挑战，对出身名门的纯情寡妇杜芬玉（章子怡 饰）产生了兴趣。当即谢、莫两人展开了以杜为诱饵的赌局游戏，赌的内容是谢得到杜的身体，而奖品则是谢梦寐以求的莫的身体。对于谢的追求，杜从开始的抵抗到后来越陷越深，而谢也发现自己爱上了猎物，这一切令莫怒火中烧。当所有的道德、禁忌完全被打破，这些游戏的男女纷纷陷入欲望的河流，种下了悲剧的结果......©豆瓣', '章子怡', '许秦豪', 5.9, 84432, 'tt2071441', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1688048913.jpg', 5.8, 22.6, 47.9, 18, 5.7, '0.569864,0.180884,-0.536575,0.550094,-0.075887,-0.255606,0.731480,-0.014627,-0.449107,-0.254304,0.050390,0.431859,-0.441369,0.210032,0.285134,-0.148078,0.172504,-0.695493,-0.217893,-0.085181,-0.208888,-0.381388,-0.160616,-0.134100,-0.195697,-0.203970,0.695784,0.330158,-0.553246,0.312442,0.680382,0.478449,0.167735,0.470884,-0.065697,0.161217,-0.099144,0.127598,-0.435242,0.100272,-0.138594,-0.411885,-0.185026,0.137687,-0.058121,0.235024,0.603201,-0.264226,-0.005215,-0.002608,0.724685,-0.262284,-0.103634,0.103757,0.367134,0.149361,0.057092,-0.232459,0.010737,0.032020,0.173790,-0.275994,-0.536619,-0.317670,0.359808,-0.051052,-0.455880,0.304440,0.076036,0.138837,-0.183306,-0.017834,0.153488,-0.121619,0.493000,0.344235,0.007796,0.202372,-0.565644,0.369774,0.469913,0.373696,-0.383761,0.210821,-0.303382,-0.603170,-0.261574,-0.359969,-0.458011,-0.048915,0.376351,-0.007121,-0.084450,0.343399,-0.608621,-0.064216,0.183847,-0.107194,0.206835,-0.509558,-0.175996,-0.532905,-0.397633,-0.722536,-0.031875,0.049873,0.218924,-0.349436,0.742086,-0.906023,0.199023,0.279005,-0.092625,-0.718759,0.684913,0.323271,-0.064179,-0.022474,-0.108017,0.430877,-0.067940,0.146088,0.120685,0.316465,-0.151087,0.018104,-0.369545,0.714914', '26354526', '3033092', '6963575', '1438708');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6529847', '冬荫功2：拳霸天下', '动作', '坎（托尼·贾 Tony Jaa 饰）是一位武艺高强的拳师，精通碎象拳。他厌倦了尔虞我诈的江湖，和心爱的大象一起归隐田园，过着风平浪静的生活。然而，某日，黑社会出高价想要买走坎的大象，坎当然不会同意，谁知道第二天，大象便神秘失踪，这定和黑社会脱不了干系。与此同时，黑帮大 佬被人谋杀，而种种的迹象和线索均指向坎，一时间，坎成为了众矢之的，只能再度踏上逃亡的旅途。一路上追击他的，除了警方和黑帮分子，还有象园老板的一双侄女，除此之外，坎还必须争分夺秒，寻回心爱的大象。落入如此凶险的境地，坎能够获得最终的胜利吗？©豆瓣', '托尼·贾', '普拉奇亚·平克尧', 5.8, 8229, 'tt1925518', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2195386469.jpg', 6.4, 25.4, 46.7, 15.6, 5.9, '0.208250,-0.176583,-0.619442,0.377205,0.015278,-0.142703,0.364868,0.124487,-0.480004,-0.086892,-0.107825,0.717630,0.027718,0.052808,0.353620,-0.426536,0.030405,-0.644230,0.088451,-0.292257,-0.277035,-0.452123,-0.316689,-0.296928,0.097989,-0.306354,0.536736,0.384335,-0.272729,0.297606,0.457788,0.187658,-0.401745,0.372634,-0.461855,-0.108110,-0.071731,0.157020,-0.472541,-0.119053,0.037510,-0.214819,0.028926,0.007340,0.067595,0.026840,0.270301,-0.421322,0.094651,-0.030769,0.032835,-0.377294,-0.194848,0.078259,0.214824,-0.220636,0.030816,0.527360,0.132526,-0.433251,0.235363,-0.111558,-0.727846,-0.153297,0.127127,0.245324,-0.536646,0.218867,0.119574,-0.068830,-0.149771,-0.133972,0.304629,0.285003,0.359472,0.087263,0.003870,0.184977,-0.693775,0.037377,1.024344,0.286304,0.068681,-0.302110,-0.054584,-0.335602,-0.213959,-0.614715,-0.248545,0.193983,0.615715,0.103306,-0.438223,0.238241,-0.391405,0.055179,-0.340720,-0.020074,-0.022865,-0.416244,-0.084374,-0.316758,0.204686,-0.562003,-0.322935,0.381991,0.239289,-0.194016,0.473056,-0.701653,0.339632,0.505282,0.393929,-0.404335,0.937273,0.150761,0.073103,-0.351751,-0.089209,0.163897,0.189381,0.274437,0.054530,0.119557,-0.231861,-0.268440,-0.049019,0.448661', '25721544', '25908042', '3055049', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6529885', '樱桃', '剧情', '安吉丽娜（阿什丽·欣肖 Ashley Hinshaw 饰）再也无法忍受那让人头痛的生活了，母亲成天抱着酒瓶子醉醺醺的没有人样，而并非亲生的继父除了会对女人施以拳脚外基本上是一个没有什么大出息的窝囊废。在男友的建议下，安吉丽娜决定靠拍色情电影来谋生，虽然这过程让她心里很不是滋味，但当真金实银的片酬拿在手中时，其他的一切都变得不那么重要了。靠着这笔钱，安吉丽娜和朋友安德鲁（戴夫·帕特尔 Dev Patel 饰）来到了车水马龙的旧金山，在这里安吉丽娜遇见了她的真命天子弗朗西斯（詹姆斯·弗兰科 James Franco 饰）。弗朗西斯是一名富有的律师，在他的带领下，安吉丽娜见识到了所谓上流社会的纸醉金迷，同时，在几乎处于另一个时空的情色世界里，安吉丽娜正在以“樱桃”的艺名迅速走红。©豆瓣', '詹姆斯·弗兰科', '史蒂芬·艾略特', 5.6, 5474, 'tt1945062', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1836470947.jpg', 5.1, 27.7, 51.9, 11.9, 3.4, '0.421792,0.037810,-0.775459,0.586443,-0.347570,-0.207417,0.886717,0.269621,-0.544506,-0.162239,0.200663,0.834008,-0.086327,0.162755,0.277424,0.045860,-0.288407,-0.682468,-0.156935,-0.168022,-0.460983,-0.522413,-0.207151,-0.310039,-0.259402,-0.223715,0.393181,-0.186084,-0.052121,0.225717,0.362683,0.203301,0.224684,0.354948,-0.554643,0.097786,0.046767,0.023239,-0.064743,0.339695,0.200037,-0.226525,-0.166563,0.332663,0.149491,0.324269,0.508012,-0.383750,0.020828,0.059684,0.157392,-0.235473,-0.130073,0.003364,-0.019298,-0.307737,0.271701,-0.012217,-0.243471,-0.022532,0.382998,-0.129333,-0.805686,0.074553,0.078753,0.247029,-0.710080,0.549956,-0.231637,-0.232501,0.099826,-0.339078,0.286325,0.305351,0.032208,0.371897,-0.045703,0.003978,-0.652938,0.153955,0.624608,0.242597,-0.131851,0.606513,-0.316734,-0.303437,-0.317394,-0.203974,-0.592129,-0.178902,0.273878,-0.004823,-0.226796,0.012045,-0.553324,0.140630,0.049382,-0.212020,-0.075067,-0.422959,-0.282389,-0.278289,-0.117921,-0.595353,-0.334087,0.074052,0.058469,-0.204996,0.703217,-0.896536,0.133421,0.484502,0.180003,-0.352946,0.707567,0.169211,0.023760,0.001119,-0.207416,0.138788,0.122718,0.269724,0.150861,0.418656,-0.045023,-0.204532,-0.233523,0.706842', '1783461', '24756472', '1481233', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6531219', '情动假日', '剧情', '故事发生在1987年的美国，阿黛尔（凯特·温丝莱特 Kate Winslet 饰）和亨利（加特林·格里菲斯 Gattlin Griffith 饰）是一对相依为命的母子，一次偶然中，两人在购物途中遇见了满身是血的流浪汉弗兰克（乔什·布洛林 Josh Brolin 饰），误打误撞之下，阿黛尔和亨利将弗兰克带回了家，弗兰克亦诚恳地坦白了他灰暗的过往。原来，弗兰克是一名逃犯，他因为发现深爱的儿子并非自己亲生而在愤怒之中失手杀死了女友曼迪（Maika Buckley 饰）。随着时间的推移，弗兰克和阿黛尔之间的关系越来越亲密，两人决定带着亨利远走高飞，然而，正当计划即将顺利实施之时，亨利却将这个秘密告诉了早熟的女孩莲诺（布丽吉德·弗莱明 Brighid Fleming 饰），这一举动为阿黛尔和弗兰克带来了灾难性的麻烦。©豆瓣', '凯特·温丝莱特', '贾森·雷特曼', 7.8, 20696, 'tt1967545', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2184495959.jpg', 0.3, 1.8, 26, 49.6, 22.3, '0.302561,0.010487,-0.796128,0.481820,-0.015531,-0.374493,0.804226,-0.082802,-0.555442,-0.372770,0.027440,0.746332,-0.271829,0.154167,0.470388,0.047478,-0.257725,-0.822321,-0.035128,-0.230940,-0.234489,-0.751604,-0.336684,-0.229187,-0.070654,-0.377880,0.317596,0.056438,0.017519,0.648641,0.393995,0.301023,-0.160924,0.438514,-0.093944,0.202176,0.389084,0.041155,-0.350016,0.234209,0.118142,-0.142150,-0.058849,0.245909,-0.009782,0.537751,0.640830,-0.379959,-0.091907,-0.068413,0.222028,-0.206489,0.107510,0.162872,0.258839,0.011978,0.173581,0.242819,-0.319945,-0.097700,0.243459,-0.189142,-0.538623,0.335057,0.028175,0.123563,-0.645668,0.392278,-0.169970,0.054189,0.270121,-0.367042,0.272711,0.469880,0.460003,0.267083,-0.187751,0.023363,-0.274454,-0.116092,0.637237,0.051424,-0.040981,0.407617,-0.298351,-0.135717,0.040621,-0.005314,-0.460561,0.087158,0.591426,0.146264,-0.127560,0.478731,-0.480126,-0.261469,-0.437993,0.039352,0.002979,-0.380966,-0.080469,-0.416710,-0.077369,-0.556199,-0.404141,0.045798,-0.185464,-0.303788,0.461185,-0.633549,0.288108,0.509748,0.278840,-0.258274,0.480410,0.112152,0.286192,-0.209176,0.033144,0.211514,0.144399,-0.180577,0.223338,0.353938,0.032057,-0.049210,-0.248589,0.417368', '3111650', '6827727', '1301022', '5966609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6531251', '车在囧途', '喜剧', '汽车，这个普通的交通工具，在现代生活里占有愈来愈重要的作用。买车实际上成为了一种积极动态的投资，在社交的意义和精神需求上，使人与城市产生更活跃的交流，是其他个人投资方式所不能替代的。本片正是从这个立意点出发，“吝啬富商”郭立行（郭德纲 饰）、“单身剩妈包工头”严小莲（王一楠 饰）、“风流小资男”陈波（许绍洋 饰）、“网购控白领”伊容（张馨予 饰）四个人，因为不同的个人目的团购了一辆“车”，从而引发了一系列“囧”事，实际展示的是围绕车引发的价值观差异的冲突过程，细致刻画了都市生活中不同人群的众生相，涉及了如“拼车”、“摇号”、“限行”、“亚历山大”族等许多当前社会热议点，加入鲜辣的笑料，嬉笑怒骂中体现故事主人公的窘境，从侧面反映出奋斗在一线城市的年轻人的真实生活状态。©豆瓣', '郭德纲', '华原', 3.9, 18149, 'tt2357023', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1470662306.jpg', 37.9, 34.8, 21.8, 3.4, 2.1, '0.504763,0.220073,-0.451113,0.553023,-0.087273,0.229093,0.698655,0.269406,-0.393385,-0.097445,0.191637,0.526640,-0.132738,-0.080534,0.275109,-0.387119,-0.283157,-0.305773,0.102762,-0.016362,-0.190222,-0.475696,-0.193192,-0.351047,-0.237849,-0.331212,0.662258,0.153195,-0.611380,0.389998,0.248410,0.190617,-0.185867,0.207095,-0.149267,-0.311572,-0.061762,0.094813,-0.312573,0.017251,-0.366280,-0.206636,-0.007932,0.149758,-0.098340,0.333039,0.886078,-0.096087,-0.304310,0.160723,0.585887,0.104135,-0.151370,-0.115100,0.139583,0.056970,0.142032,0.114219,-0.085460,0.119437,-0.179126,-0.005957,-0.873149,-0.248089,0.234302,0.197201,-0.488094,0.506799,-0.002883,-0.481572,0.034330,-0.089564,0.182185,0.166157,0.335209,0.486013,0.052039,-0.026435,-0.385871,0.299810,0.605206,0.069449,-0.446246,0.622800,-0.641973,-0.534372,-0.413255,-0.129160,-0.298236,-0.270091,0.119910,-0.065670,-0.161051,0.230367,-0.800658,0.353583,0.149385,-0.312104,0.103911,-0.263405,0.034068,-0.836917,-0.323985,-0.547857,-0.013974,-0.001038,0.271860,-0.154920,0.936907,-0.748021,-0.109037,0.471686,0.140391,-0.792761,0.656046,-0.026389,0.211798,-0.467892,-0.217557,-0.069769,-0.122047,0.094684,-0.457668,0.414111,-0.099378,-0.126487,-0.290572,0.546715', '4181031', '3811356', '2053515', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6532822', '生化危机5：惩罚', '动作', '在上一集中，爱丽丝（米拉·乔沃维奇 Milla Jovovich 饰）救出了被冷冻的同伴们，众人在离开之际却被赶来的雇佣兵赶尽杀绝。T病毒使红皇后（Megan Charpentier 饰）的程序发生了错误，变得残暴嗜血的她想要杀死最后的人类毁灭地球。唯一能够阻止红皇后的只有爱丽丝一人。而此刻，失去了能力的爱丽丝却被保护伞公司囚禁在位于海底的秘密基地中。威斯克（肖恩·罗伯茨 Shawn Roberts 饰）通过病毒侵入了保护伞公司的系统，他放走了爱丽丝并告诉她，她是人类最后的希望，而为了拯救人类，他们必须冰释前嫌共同抵抗更强大的敌人。爱丽丝遇见了保护伞公司的前员工艾达王（李冰冰 饰），两人一路上奋勇杀敌结下了深厚的友谊。同时，爱丽丝旧日的战友们也组成了一个小分队，从外向内进行突围。保护伞公司在海底建造了逼真的模拟城市，并使用克隆人作为T病毒的实验对象，为了抵达出口，爱丽丝一行人必须穿越东京、纽约、华盛顿和莫斯科四座城市，而每座城市中，都有属于它的丧尸们在蠢蠢欲动。', '米拉·乔沃维奇', '保罗·安德森', 6.3, 187563, 'tt1855325', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1727862902.jpg', 4.5, 17.3, 45.8, 21.8, 10.6, '0.264838,0.288332,-0.772679,0.464157,-0.081378,-0.066225,0.801492,-0.091816,-0.390076,-0.024315,0.312959,0.717248,0.070845,-0.044613,-0.018214,-0.086669,-0.310370,-0.436912,-0.106720,-0.217307,-0.434830,-0.364939,-0.313057,-0.486638,-0.021153,-0.377844,0.786067,0.070908,-0.242236,0.115699,0.222133,0.262829,-0.232195,0.448186,0.034232,-0.096619,0.065380,-0.386786,-0.394774,0.322364,-0.251316,-0.086634,-0.046332,0.435223,-0.146129,0.376906,0.577715,-0.359778,0.060240,-0.395439,0.078856,-0.390581,0.084149,0.094643,0.335618,-0.098869,0.040313,0.237094,-0.124229,0.055536,0.126094,-0.004744,-1.018332,-0.043179,0.076370,0.092531,-0.387902,0.296260,-0.004466,0.129816,0.168077,-0.310114,0.136942,0.433821,0.251423,0.121635,-0.235599,0.007188,-0.634364,0.042824,0.738512,-0.298434,-0.387981,0.188002,-0.297799,-0.419723,-0.261943,-0.215980,-0.220282,-0.083801,0.454395,0.222037,-0.221208,0.363471,-0.846838,-0.118261,-0.358890,-0.274412,-0.131859,-0.423147,-0.034769,-0.713684,-0.046927,-0.092196,-0.218573,0.172537,-0.032230,-0.187643,0.685663,-0.807360,0.061439,0.793168,0.564341,-0.571445,0.426318,-0.057678,0.277146,-0.084847,-0.100922,0.411391,0.095041,0.670043,0.201349,0.164464,-0.111432,-0.053411,-0.387273,0.446476', '27009869', '1793491', '25828589', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6533054', '饥饿游戏3：嘲笑鸟(上)', '动作', '凯特尼斯·伊夫狄恩（詹妮弗·劳伦斯 饰），燃烧的女孩，虽然她的家被毁了，可她却活了下来。盖尔（利亚姆·海莫斯沃斯 饰）也逃了出来，凯特尼斯的家人也安全了，皮塔（乔什·哈切森 饰）被国会区抓走了。十三区并不真的存在，出现了反抗，出现了新的领导者，一个革命的序幕正在缓缓拉开。凯特尼斯从噩梦般的竞技场逃出来是已经设计好的，她是反抗运动的参与者，也是设计好的，而她对此并不知情。十三区从隐蔽处出来了，并计划推翻国会区的统治。似乎每个人都参与了这项精心策划的行动，而只有凯特尼斯依然蒙在鼓里。反抗运动将凯特尼斯卷入了漩涡，她被迫成为棋子，她被迫为许多人的使命负责，不得不肩负起改变帕纳姆国的未来的负责。为了做到这一切，她必须抛却愤怒和不信任，她必须要成为反抗者的嘲笑鸟――不管要付出多大的代价。', '詹妮弗·劳伦斯', '弗朗西斯·劳伦斯', 6.2, 166079, 'tt1951265', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2222078042.jpg', 4, 17.4, 50.1, 20.6, 8, '0.202173,0.148946,-0.765847,0.233900,-0.304453,-0.240525,0.842402,0.147448,-0.314261,0.015564,0.389418,0.755477,0.245740,-0.191438,0.272909,0.297425,-0.474532,-0.705598,-0.081307,-0.140739,-0.176683,-0.523125,-0.186749,-0.200276,-0.155994,-0.392416,0.645315,0.103663,-0.196184,0.208583,0.513044,0.035399,0.223770,0.643619,0.196908,-0.009188,0.076816,-0.381824,-0.076177,-0.000083,-0.230194,-0.177014,-0.316300,0.551915,0.128197,0.654974,0.316233,-0.342497,0.047823,-0.199886,0.126061,-0.655808,-0.015938,0.200669,0.037060,-0.165958,-0.084647,0.517625,-0.050902,0.039813,0.195259,-0.063950,-1.098790,0.083361,0.165757,0.344161,-0.753572,0.565719,-0.268432,-0.105746,0.001294,-0.210270,0.033863,0.483624,0.109650,0.086294,-0.280143,-0.064459,-0.779249,0.047076,0.730696,-0.239589,-0.461339,0.191179,-0.164388,-0.429064,-0.207838,-0.336028,-0.285888,-0.229892,0.333512,0.281981,-0.229939,0.292547,-0.549085,-0.102344,-0.476378,-0.574042,-0.028182,-0.722434,0.128903,-0.396916,-0.050124,-0.281965,-0.584883,-0.167857,-0.085855,-0.496916,0.619209,-0.952699,0.113695,0.615353,0.358643,-0.585208,0.369186,0.170697,0.214150,0.016919,-0.032893,0.291397,0.038500,0.591919,0.160689,0.376781,0.334950,-0.273008,-0.336391,0.569415', '30163500', '1793491', '25917239', '1306801');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6534064', '爆笑角斗士', '喜剧', '影片讲述了“福禄寿”三兄弟之间关于亲情、友情、爱情的故事，演绎了小人物为梦想打拼路上的点滴乐事。身兼数职辛勤打工的“禄蓝、捷寿、福祥”三兄弟，时常乌龙不断、处处闯祸，“禄蓝”（王祖蓝饰）向女友“凯琪”（薛凯琪饰）求婚，凯琪的父亲（曾志伟饰）认为蓝禄事业不成功而不肯将女儿嫁给他；福祥（阮兆祥饰）是一位单亲爸爸，一直没有稳定工作靠打零工干活的他总是遭到儿子祥仔白眼，让他非常苦闷。捷寿（李思捷饰）经常自称富二代，却日日打杂工被人笑。因缘巧合下，三个好兄弟获得了用与职业摔跤手擂台决斗赢取50万美金的机会，为了换取改变命运的筹码，三人登上擂台，在面对美国擂台高手的同时，也遇到了来自爱情、亲情、友情上的选择。©豆瓣', '曾志伟', '钟澍佳', 6.3, 10998, 'tt1997561', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2143871202.jpg', 3.6, 13.7, 53.6, 22.8, 6.3, '-0.142715,-0.240127,-0.224677,0.591503,-0.001178,-0.316077,0.347558,0.222743,-0.310454,-0.114943,0.196061,0.715509,-0.110821,0.176401,0.212580,-0.226320,0.000719,-0.713447,0.056248,0.089355,-0.065872,-0.389872,0.003166,-0.265330,-0.502458,-0.094029,0.512364,0.011397,-0.025378,0.409453,0.449058,0.234272,-0.159838,0.203590,-0.149173,0.008059,0.009410,0.284261,-0.567201,0.111800,-0.103087,-0.235010,0.039886,0.086690,0.238298,0.071782,0.575982,-0.071600,0.113566,-0.276991,0.135225,-0.144276,-0.057312,-0.040555,0.115262,0.013709,0.466676,0.403893,0.135229,-0.135452,0.235075,-0.255821,-0.717595,-0.052769,0.206385,-0.069759,-0.657667,0.590786,-0.082147,-0.013124,0.070475,-0.081913,-0.000567,0.199425,0.364120,0.300894,-0.488508,0.144184,-0.276352,0.384023,0.667550,0.056406,0.223391,0.447372,-0.160835,-0.065777,0.194094,-0.299680,-0.509589,0.061019,0.222897,0.007362,0.139469,0.203962,-0.502394,0.090691,-0.031915,-0.014130,0.288408,-0.546753,0.012036,-0.325639,-0.018857,-0.322505,-0.409593,0.225500,0.191414,-0.484497,0.818005,-0.786563,-0.034352,0.434949,0.441878,-0.595036,0.819209,0.320231,0.109196,-0.528154,0.051430,-0.006710,-0.147716,0.012563,0.199101,-0.127278,-0.321762,0.122111,-0.013334,0.340359', '35048413', '4301278', '26021055', '10876425');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6534248', '无敌破坏王', '喜剧', '无敌破坏王（约翰·C·赖利 John C. Reilly 配音）生活在一个80年代出品的低精度游戏中。他的设定身份是一个反派，每天的生活就是在游戏《快手阿修》中大搞破坏，其后由玩家操作的英雄人物快手阿修（杰克·麦克布瑞尔 Jack McBrayer 配音） 会及时赶到进行修补，赢得奖牌，包揽一切荣耀。身为反派，破坏王厌倦了自己的生活，眼看阿修被胜利者的光环围绕，自己却日复一日在无趣中过活，他终于决定改变。单纯的他以为只要自己也能得到一枚奖牌，就可以摆脱反派的身份，于是某日在游戏厅歇业后，破坏王偷偷离开了自己的游戏，前去闯荡其他电子游戏的世界。在途中，破坏王结识了来自《英雄使命》的冷酷队长（简·林奇 Jane Lynch 配音）和来自90年代糖果赛车游戏《甜蜜冲刺》的小女孩云妮（萨拉·丝沃曼 Sarah Silverman 配音）。后者梦想着能上场比赛，但其身份也不允许她梦想成真。破坏王所属的游戏《快手阿修》由于失去了他被认定为系统错误，如不尽快返回，则游戏就会被永久删除；而《甜蜜冲刺》的游戏世界则在悄悄酝酿着一场巨大的、威胁到整个游戏世界的阴谋。这也许是无敌破坏王实现梦想的机会，但也可能是一条不归路…… 他可以扭转乾坤，成为一名真正的英雄吗？', '约翰·C·赖利', '瑞奇·摩尔', 8.7, 500351, 'tt1772341', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1735642656.jpg', 0.1, 0.6, 10.4, 40.7, 48.2, '-0.029287,0.562928,-0.466041,0.595324,-0.253825,-0.078478,0.634251,-0.025628,-0.269642,-0.235149,0.269029,0.679897,-0.068680,-0.028936,0.188827,-0.106243,-0.229995,-0.537760,-0.082198,-0.090249,-0.362613,-0.238556,-0.391616,-0.399438,-0.199650,-0.298326,0.799439,0.107421,-0.520048,-0.022654,0.352878,0.175374,-0.118823,0.557388,-0.224734,-0.048953,0.082390,0.051120,-0.264002,0.422026,-0.062910,-0.028230,-0.032495,0.150667,-0.060677,0.031613,0.717197,-0.518934,-0.164105,-0.103103,0.343448,-0.577922,-0.287644,-0.008328,0.165759,-0.145244,0.056755,0.046171,-0.001538,0.155362,0.138633,-0.310759,-1.028948,-0.217169,-0.030976,0.136680,-0.404770,0.287666,-0.160961,-0.122099,0.054031,-0.242824,0.224414,0.253668,0.604267,0.293333,-0.270707,0.158024,-0.524146,0.522270,0.666794,0.030314,-0.436566,0.231747,-0.120364,-0.371179,-0.326395,-0.295398,-0.688883,-0.155506,0.427973,0.045482,-0.133604,0.276195,-0.552494,-0.095120,-0.186654,-0.226093,0.083788,-0.724481,-0.064913,-0.507326,-0.006735,-0.109027,-0.099123,0.136098,0.174154,-0.570458,0.699041,-1.115620,0.204354,0.609340,0.143065,-0.621991,0.617077,0.238300,0.163717,-0.456124,0.093143,0.278949,-0.090250,0.417280,0.129556,0.338063,0.042921,-0.084532,-0.401393,0.953063', '1793491', '3769423', '26759820', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6536180', '黑暗面', '剧情', '年轻指挥家亚德里安（奎姆·古铁雷兹 Quim Gutiérrez 饰）的女友贝伦（克拉拉·拉戈 Clara Lago饰）失踪了，活不见人死不见尸，只留下一段视频讯息。郁闷的亚德里安不断被警察怀疑和调查，烦不胜烦之下到小酒馆浇愁，一不小心喝的大醉，受到女招待法比安娜（玛蒂娜·加西亚 Martina García）照顾，两人迅速陷入新的恋情。很快，法比安娜住进亚德里安的大宅，敏感的她时时感到房子里面不对劲，浴室里面好像总有奇怪的声音，亚德里安对此不以为意，但法比安娜开始时时留心，还一度怀疑是他前女友的鬼魂作祟。一天，在卧室更衣的法比安娜拾到一把古怪的钥匙，似乎接近了一个天大的秘密……©豆瓣', '基姆·古铁雷斯', '安德烈斯·拜斯', 8.1, 212690, 'tt1772250', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2258872500.jpg', 0.2, 1.2, 18.2, 52.6, 27.7, '0.455039,-0.042834,-0.460078,0.063527,0.416564,-0.200351,0.633342,0.144537,-0.609083,-0.549623,-0.316331,0.505580,-0.472101,0.247479,0.224322,0.157859,-0.635073,-0.521269,0.097473,-0.244129,-0.295131,-0.491417,-0.161999,-0.204106,-0.189853,-0.650646,-0.257024,0.188522,0.000994,0.248443,0.380961,0.471120,-0.179886,0.637419,0.045626,0.278154,0.089902,-0.401492,0.226042,-0.260914,0.199770,-0.046460,-0.199190,0.030585,0.480472,0.365493,0.314211,-0.097864,-0.085222,0.198119,0.339837,0.077433,-0.142786,0.024790,0.203534,-0.187366,0.085272,-0.098410,-0.501765,0.176273,0.305105,-0.115685,-0.466919,0.151776,0.174898,0.054432,-0.255562,-0.015676,-0.335529,0.206249,0.098611,-0.044506,0.175231,0.215160,0.045133,0.387392,-0.058044,0.037890,-0.391430,-0.394211,0.199946,0.062935,-0.296482,0.205697,-0.049961,-0.311297,-0.355537,-0.079303,-0.388550,-0.189736,0.446858,0.032676,0.018709,-0.019025,-0.444924,-0.308672,-0.284583,-0.034123,-0.187977,-0.070570,-0.438959,-0.449888,-0.193803,-0.067815,-0.294822,-0.083073,-0.313552,-0.127007,0.151734,-0.472292,0.533079,0.409366,-0.005199,-0.103094,0.555029,-0.119225,0.146087,-0.187506,-0.139569,0.568013,0.409222,0.181686,0.467305,0.391209,-0.385773,-0.042861,-0.284027,0.239481', '1316693', '1309172', '3026572', '1302488');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6537486', '登堂入室', '剧情', '法国高校文学老师吉尔曼（法布莱斯·鲁奇尼 Fabrice Luchini 饰）给学生布置了一篇周记，要求他们如实记录周末的见闻。在众多乏味的作业中吉尔曼意外发现16岁少年克劳德（恩斯特·吴默埃 Ernst Umhauer 饰）的文章异常精彩。克劳德是一个安静的观察者，习 惯坐在教室的最后一排。他的作业是关于偷窥——讲述他如何潜入朋友家中、窥探对方一家生活的故事。吉尔曼被字里行间深深吸引，熄灭已久的文学激情亦被点燃。他不但决定单独辅导才华横溢的克劳德、鼓励他放手创作，还与妻子珍娜（克里斯汀·斯科特·托马斯 Kristin Scott Thomas 饰）一同分享克劳德的作文。然而成年人在阅读过程中竟渐渐忘记了虚构和现实的边界，更懵然不知自己的居室早已房门大开......法国鬼才导演弗朗索瓦·欧容曾凭借黑暗惊心的《八美图》、《泳池谋杀案》惊艳世界影坛。在《5×2》、《时光驻留》等温情文艺片后，新片《登堂入室》再次回归欧容最擅长的悬疑惊悚题材。电影改编自西班牙舞台剧《最后一排的男孩》，导演巧妙拼接偷窥文学与扑朔迷离的现实断面，用似真似幻、充满层次感的创作故事挑战情欲道德禁区。本片入围法国凯撒奖六项大奖，获多伦多电影节国际影评人费比西奖和西班牙圣塞巴斯蒂安电影节最佳影片金贝壳奖，同时入选欧洲年度最佳电影之一。', '法布莱斯·鲁奇尼', '弗朗索瓦·欧容', 8.5, 148232, 'tt1964624', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1581587840.jpg', 0.3, 1, 12, 45.5, 41.1, '0.043585,-0.083566,-0.282846,0.704122,0.381504,-0.146949,0.518133,0.100800,-0.360827,-0.218514,0.061680,0.700699,-0.467188,0.100979,0.375677,-0.300125,-0.547289,-0.671349,-0.063938,-0.160383,0.069874,-0.510362,-0.183589,-0.058527,-0.054600,-0.268382,0.671297,0.053205,-0.389843,0.337479,0.252243,0.089208,-0.198384,0.170062,0.022831,0.096504,0.393017,0.007682,-0.211138,0.037720,-0.062512,-0.257848,-0.482023,0.037908,0.014584,0.053091,0.719246,0.072209,-0.051924,0.226664,0.703463,-0.134426,-0.089496,-0.020686,0.048137,0.039532,0.322158,0.094440,0.164161,0.061920,-0.035216,-0.277262,-0.662332,-0.001105,0.249666,0.142002,-0.204517,0.395310,-0.031392,0.182390,0.051258,0.038493,-0.052670,0.000653,0.435168,0.202577,0.099518,0.081442,-0.092369,0.533513,0.084104,-0.114615,-0.272281,0.415926,-0.255890,-0.484761,-0.047991,-0.160815,-0.416403,0.094137,0.486037,-0.033015,0.143945,0.131655,-0.494027,-0.226021,-0.005259,-0.296253,-0.014925,-0.348150,-0.038691,-0.924828,-0.112600,0.033302,-0.104189,-0.212546,0.103610,-0.210396,0.798329,-0.398423,0.229846,0.389393,-0.073585,0.030288,0.785975,0.057104,-0.050762,-0.210555,-0.215496,0.392376,-0.022115,-0.000558,-0.176131,0.463552,-0.014701,-0.126413,-0.622391,0.497999', '1322847', '22265121', '2027945', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6537500', '速度与激情6', '动作', '俄罗斯莫斯科闹市中央，执行押送任务的军方部队遭到一伙训练有素的匪徒袭击，大战过后的现场惨不忍睹，重要的卫星元件遭到劫持。国际刑警霍布斯（道恩·强森 Dwayne Johnson 饰）查明，包括此案在内的一系列案件均系前特种部队军人欧文·肖（卢克·伊万斯 Luke Evans 饰）所为。为了将这群训练有素、老练凶狠的匪徒绳之于法，他辗转找到隐居世外桃源的多米尼克·托雷多（范·迪塞尔 Vin Diesel 饰）助拳。霍布斯开出的条件令人难以拒绝，他不仅可以将托雷多和布莱恩（保罗·沃克 Paul Walker 饰）一伙从前的犯罪记录一笔勾销，此外欧文一伙中竟然还有本该死去的拉蒂（米歇尔·罗德里格兹 Michelle Rodriguez 饰）。前所未有的危险战斗，为了安定平凡的生活，这群亡命之徒再上战场……©豆瓣', '范·迪塞尔', '林诣彬', 7.9, 255607, 'tt1905041', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2024579845.jpg', 0.4, 2.1, 24.6, 49.4, 23.5, '0.353658,-0.209083,-0.627025,0.539774,-0.090698,-0.126493,0.596028,-0.158930,-0.416312,-0.357119,0.286333,0.553350,0.074032,-0.022637,0.228116,-0.252947,-0.382135,-0.585796,-0.382654,-0.105193,-0.389162,-0.580288,-0.194736,-0.499338,0.080029,-0.063523,0.398873,0.244896,-0.019980,0.432753,0.342974,0.615265,-0.117905,0.043172,-0.007005,-0.279744,0.243540,-0.305917,-0.364482,-0.011683,-0.290824,0.013179,0.071318,0.167921,0.122079,0.398878,0.639219,-0.240634,-0.003816,-0.174690,0.200542,-0.321586,0.350150,0.072370,0.338522,-0.055778,-0.145489,0.355474,-0.084727,-0.031050,0.059745,-0.009961,-0.777410,-0.066938,0.176883,0.042225,-0.140612,0.075742,-0.125426,0.299093,-0.008785,-0.006663,0.136805,0.512620,0.424244,0.065136,0.226433,0.058059,-0.435714,0.105789,0.537225,-0.170551,-0.191336,-0.325940,-0.316953,-0.420588,0.158831,-0.404507,-0.146691,0.039636,0.407118,-0.271378,0.118017,0.274788,-0.495348,-0.088675,-0.263882,0.003601,-0.485160,-0.063208,-0.061356,-0.882772,0.000126,-0.209598,-0.317039,0.415328,0.014788,0.080045,0.412677,-0.144994,0.055753,0.538973,0.132101,-0.321878,-0.001311,0.072228,0.199747,-0.179571,-0.313630,0.407323,0.595247,0.235915,0.178263,0.124881,-0.136276,-0.301986,-0.063362,0.131314', '6517421', '2028645', '25995508', '1482080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6538697', '劫匪', '剧情', '故事发生于1934年的美国得克萨斯州，臭名昭著穷凶极恶的抢劫犯邦妮和克莱德越狱成功，重新开启了他们的杀戮之旅。在典狱长李（约翰·卡洛·林奇 John Carroll Lynch 饰）的建议之下，州长马福格斯（凯西·贝茨 Kathy Bates 饰）找到了已经退隐江湖的德州骑警弗兰克（凯文·科斯特纳 Kevin Costner 饰）和曼尼（伍迪·哈里森 Woody Harrelson 饰），委托他们讲暴徒捉拿归案。弗兰克和曼尼已经十几年没有见过面了，让弗兰克感到震惊的时，曾经意气风发的搭档，如今沦落成为了一贫如洗的酒鬼。弗兰克逐渐打消了和曼尼合作的念头，但是，对于曼尼来说，这个案子是他想要摆脱生活这个烂摊子的最后一次机会了。©豆瓣', '凯文·科斯特纳', '约翰·李·汉考克', 7.4, 15435, 'tt1860242', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2548750147.jpg', 0.6, 3.5, 36.6, 46.5, 12.8, '0.211101,-0.067716,-0.494892,0.508571,-0.191531,-0.672880,0.647031,0.000968,-0.772629,-0.464640,-0.154885,0.644699,-0.206001,0.092683,0.450063,-0.018044,-0.419416,-0.786111,0.177133,-0.249237,-0.053970,-0.826265,-0.403876,-0.348902,-0.138421,-0.253031,0.517808,-0.073105,-0.003101,0.579519,0.332213,0.530549,0.319286,0.435982,-0.136330,0.106375,0.524683,-0.121998,-0.569960,0.107310,0.117506,-0.065192,-0.115661,0.098020,0.235298,0.333767,0.453265,-0.161240,-0.070097,-0.225454,0.211905,-0.245176,-0.209395,0.039051,0.292383,-0.204937,0.085168,0.265231,-0.116837,-0.384402,0.224442,-0.096655,-0.731864,0.066825,-0.096296,0.201605,-0.668202,0.188868,-0.397219,0.214708,0.014705,-0.421676,0.196426,0.432079,0.480977,0.197646,0.030016,0.021090,-0.534759,0.125033,0.716121,0.055678,-0.272721,0.144903,-0.079583,-0.473811,-0.116209,-0.085600,-0.294781,0.111763,0.368954,-0.033852,-0.321515,0.557771,-0.498323,-0.420716,-0.511289,-0.286222,0.064970,-0.343740,-0.081384,-0.661771,-0.374360,-0.304147,-0.392996,-0.225082,-0.150404,-0.265528,0.489748,-0.881355,0.281211,0.370518,0.149130,-0.357354,0.663421,0.198831,0.225966,-0.317622,0.013650,0.150679,0.075230,0.332372,0.455254,0.463802,0.091267,-0.415143,-0.066939,0.492090', '26971054', '1307442', '1301022', '24325856');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6538807', '冰海陷落', '动作', '疯狂的芭堤雅将军杜罗夫（米哈伊尔·戈尔沃伊 Mikhail Gorevoy 饰）预谋发动第三次世界大战，他制造了一场巨大的水域爆炸，致使附近的美军潜艇队遇袭。美国海军派出了海底经验丰富但名声寥寥的乔·格拉斯潜水艇船长（杰拉德·巴特勒 Gerard Butler 饰）率领潜艇队前去调查。', '杰拉德·巴特勒', '多诺万·玛什', 6.7, 25650, 'tt1846589', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2540706012.jpg', 1.3, 8.9, 50.5, 31.8, 7.5, '0.130359,-0.118365,-0.732705,0.610107,0.351125,0.142675,0.423826,-0.040468,-0.506205,-0.097487,0.294890,0.611175,0.019498,-0.363899,0.264044,-0.001939,-0.344162,-0.334388,-0.024315,0.157624,-0.269884,-0.473508,-0.629208,-0.490007,0.264980,-0.148039,0.333892,0.199438,-0.258732,0.635961,0.022093,0.555356,0.302707,0.374217,0.384143,0.090044,0.313382,-0.445461,-0.116910,0.346157,-0.347984,-0.168489,0.048853,0.032702,0.223242,0.765962,0.617262,-0.291260,0.243334,-0.412967,0.057948,-0.494312,0.551720,0.188408,0.644850,0.270459,-0.112565,-0.032036,-0.027792,-0.087061,0.030360,-0.041471,-0.045436,0.202939,-0.083502,-0.317523,-0.223942,0.011767,-0.485532,0.209360,-0.140169,0.181891,0.197835,0.713275,0.190170,-0.430675,-0.001621,0.161629,-0.423731,-0.126047,0.467195,-0.315976,-0.077472,-0.136669,0.166646,-0.273086,-0.010950,-0.276971,-0.139781,-0.054737,0.555220,-0.540582,0.280221,0.387728,-0.635183,0.122538,-0.964489,-0.388003,-0.660961,0.291604,-0.052171,-1.064961,-0.145672,0.023037,-0.072681,0.193041,-0.131986,0.494198,0.191317,-0.012872,0.002560,0.523794,-0.016376,-0.021627,0.210226,-0.122041,0.033378,-0.162014,0.355171,0.384074,0.113642,0.132303,0.062281,0.374218,0.154698,-0.177780,0.023104,0.173087', '3871833', '6517421', '1303847', '1293537');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6538833', '内布拉斯加', '剧情', '老头子Woody（布鲁斯·邓恩 Bruce Dern 饰）收到一份广告，上面说他中了一百万大奖，对此他深信不疑，更决定从蒙大拿的比灵斯市步行到内布拉斯加的林肯市去领奖。他的妻子和两个儿子多次劝阻未果，最终小儿子David（威尔·福特 Will Forte 饰）决定开车载着他到林肯去领奖。去林肯的路上他们经过了Woody的老家，便决定去拜访那些久未谋面的亲戚们。Woody一家在那里短暂停留的几天里，整个小镇的人都知道Woody中了大奖，Woody顿时成了镇上的红人，接踵而来的是他的那些老债主们。David也渐渐了解了Woody那些不为人知的过去，对自己的父亲有了新的了解......©豆瓣', '布鲁斯·邓恩', '亚历山大·佩恩', 8.6, 45821, 'tt1821549', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2158863675.jpg', 0.2, 0.7, 9.9, 47.4, 41.8, '0.491147,0.154526,-0.969182,0.604343,-0.284281,-0.340069,0.719384,-0.032863,-0.614730,-0.075678,0.144295,0.975404,-0.128818,0.424712,0.250599,0.062846,-0.334527,-0.535571,0.017078,-0.472036,-0.379625,-0.458599,-0.314209,-0.076579,-0.186361,0.112825,0.120010,0.212517,0.196547,0.528143,0.313988,0.070466,0.185765,0.553765,-0.368201,0.489295,0.022112,-0.021026,-0.130590,0.204150,0.157916,-0.272736,-0.370008,0.105668,0.399869,0.601098,0.453432,-0.088508,-0.213535,0.269157,0.259903,-0.092602,-0.023446,0.239512,0.460609,0.237740,0.218368,0.179607,-0.417534,0.084648,-0.195666,0.222989,-0.544002,0.173561,-0.115982,0.100918,-1.115788,0.366922,-0.132491,-0.140017,-0.066385,-0.719753,0.368361,0.184638,-0.325481,0.263935,0.024223,0.002787,-0.489604,0.483453,0.805088,0.072203,-0.058173,0.103151,0.091418,-0.253607,-0.068948,-0.204792,-0.450615,-0.140626,0.636044,-0.007815,-0.266276,-0.045603,-0.520201,-0.028200,-0.190359,-0.631576,-0.047781,-0.356026,-0.052456,-0.691125,0.027877,-0.546168,-0.133954,0.073100,0.046426,-0.174322,0.657223,-0.724218,0.260672,0.522556,0.334405,-0.713221,0.725441,0.010451,0.233489,0.087508,-0.061092,-0.143567,-0.038971,0.511760,0.283806,0.522964,0.134949,-0.414829,-0.507662,0.603460', '21354767', '1299965', '1309069', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6538866', '极速车王', '剧情', '基于真实故事，聚焦由汽车设计师卡罗尔·谢尔比带领的一队美国工程师、设计师，以及他旗下的英国车手肯·迈尔斯，亨利·福特二世要求谢尔比打造一辆全新的赛车，希望能在1966年的勒芒世界锦标赛上打败长期占主导地位的法拉利。最终福特GT40在勒芒24小时耐力赛中成功击败法拉利，并蝉联了1967和1968年的冠军。', '马特·达蒙', '詹姆斯·曼高德', 8.5, 219218, 'tt1950186', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2568792942.jpg', 0.1, 0.6, 10.8, 51.6, 37, '-0.272006,0.331274,-0.216206,0.678737,0.188816,-0.484461,0.042661,-0.284822,-0.835934,-0.173756,0.178355,0.737111,-0.128602,-0.047368,0.838449,-0.000758,-0.238695,-0.390573,0.171461,-0.333258,-0.452953,-0.908762,-0.298109,-0.252352,0.201273,-0.136723,0.704171,-0.009348,0.051986,0.722147,0.537781,0.055807,0.221064,0.130604,-0.005223,-0.214397,0.423919,-0.071068,-0.574051,0.374659,-0.681456,-0.083210,0.145197,-0.453483,0.143724,-0.033557,0.387363,-0.054586,0.380866,-0.250940,0.056796,-0.083362,0.018013,-0.646551,0.200728,0.042892,0.067576,0.349836,0.121650,-0.076663,-0.156084,-0.271700,-0.422623,-0.025181,-0.206520,-0.374633,-0.782667,0.612228,-0.364272,0.180291,-0.102876,0.030485,0.015942,-0.005368,0.266117,0.221980,0.260869,0.289841,-0.739696,0.520922,0.498069,-0.028321,-0.274416,-0.012905,-0.137549,-0.463239,-0.371960,-0.719810,-0.667080,0.014923,0.352433,0.176105,0.055979,-0.004070,-0.414284,0.054437,-0.365659,-0.442699,0.380838,-0.322126,0.391083,-0.567936,0.214638,-0.190214,0.506507,0.093836,-0.229289,-0.278346,0.512014,-0.887191,0.220406,0.136934,0.397497,-0.182841,0.761699,0.054881,0.308138,-0.345999,-0.372907,0.429483,-0.145662,0.083868,-0.361600,0.377748,0.079167,-0.211243,-0.102376,0.546281', '22964524', '3139191', '35030151', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6539385', '我是杀人犯', '动作', '这么多年来，一直有一件事情让崔向久（郑在泳 饰）久久无法释怀。那是17年前，社会上发生了一件影响极其恶劣的女子连环凶杀案，而崔向久则是负责此案的警探。狡猾的凶手巧妙的躲过了正义的天罗地网，当15年诉讼有效期到来的那一天，当凶手彻底的逃脱了法律制裁的那一天，受害者的家属以死发出了对无能警察以及残暴凶手的控诉。正当大家以为惨剧带来的阴影即将消散之时，一本名为《我是杀人犯》的书的出版让所有的人都极为震惊，而书的作者不是别人，正是当年凶杀案的始作俑者李斗锡（朴施厚 饰）。可是，作为当年追捕凶手的警探，崔向久并不相信李斗锡就是当年的罪犯，一场激烈的猫鼠之争在两人之间展开。©豆瓣', '郑在泳', '郑秉吉', 7.5, 42957, 'tt2468774', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1751906410.jpg', 0.7, 3.3, 32.4, 48.6, 15.1, '0.302672,-0.251120,-0.558034,0.389157,-0.180778,0.010045,0.809499,-0.318886,-0.619861,-0.397419,0.345645,0.633486,-0.171550,0.051868,0.103548,-0.003080,0.032555,-0.744957,-0.267333,-0.256326,-0.233393,-0.454716,-0.342102,-0.189029,-0.062579,-0.138489,0.510044,0.454091,-0.108892,0.363818,0.443131,0.420404,-0.155085,0.449172,0.115472,-0.171318,-0.000288,0.065147,-0.170514,-0.028432,0.114073,-0.531874,-0.072684,0.391745,-0.263206,0.366248,0.533489,-0.499365,-0.576859,-0.037807,0.625682,-0.667555,-0.145894,0.270989,0.385536,-0.038340,0.239187,0.435946,-0.206869,-0.194482,0.066475,-0.031612,-0.965860,-0.157537,0.103190,0.164108,-0.253506,0.518997,-0.188142,0.134864,0.082313,-0.262685,0.265476,0.303808,0.288784,0.412587,-0.108488,-0.077603,-0.513578,0.318420,0.701306,0.038858,-0.336964,0.116976,-0.153379,-0.417709,-0.066636,-0.383465,-0.311632,0.193557,0.478889,0.075874,-0.296151,0.297508,-0.427494,-0.131076,-0.321918,0.081081,-0.089213,-0.421840,-0.337540,-0.186281,-0.145039,-0.425067,-0.297677,0.108253,0.069041,-0.538041,0.454906,-0.712122,0.330562,0.591112,0.020518,-0.405335,0.480845,0.170625,0.052018,0.092992,-0.250927,-0.043330,0.203832,0.330499,0.217506,0.179080,0.308049,-0.268853,-0.223410,0.332643', '25828589', '1874704', '5296286', '25921830');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6549903', '逃离德黑兰', '剧情', '1979年11月4日，伊朗的革命军攻进了美国在伊朗德黑兰的大使馆，将大使馆的工作人员劫为人质。有超过50名人员被关押，但有6人逃脱，并躲在加拿大驻伊朗大使Ken Taylor（维克多·加博 Victor Garber 饰）的家里。CIA高层Jack O''Donnell（ 布莱恩·科兰斯顿 Bryan Cranston 饰）找到专家Tony Mendez（本·阿弗莱克 Ben Affleck 饰），让他协助将那六个人带回美国。经过讨论后，CIA决定采取Tony的办法，以拍摄电影的名义，Tony到伊朗将那六个人带回。Tony联系了他在好莱坞的朋友，化妆师John Chambers（约翰·古德曼 John Goodman 饰），并联系了电影制片人Lester（艾伦·阿金 Alan Arkin 饰）。Tony在许多剧本中选中了《ARGO》，一部和《星球大战》极为类似的电影。于是他作为制片人带着剧本和各种道具前往伊朗，找到了那六个人，开始了艰苦的逃离德黑兰之路......本片根据真实故事改编，获得第85届奥斯卡最佳影片、最佳剪辑、最佳改编剧本等3项大奖。', '本·阿弗莱克', '本·阿弗莱克', 8.3, 276334, 'tt1024648', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1844091387.jpg', 0.4, 1.1, 15.5, 51.2, 31.8, '0.092636,-0.024637,-0.682351,0.703743,0.194362,-0.044411,0.361406,0.026981,-0.499011,-0.204188,0.052866,0.865354,-0.246928,-0.113228,0.498331,-0.060037,-0.728259,-0.754181,-0.082816,-0.361060,-0.329154,-0.474941,-0.295414,-0.219143,0.050369,-0.336758,0.742431,-0.001492,-0.173473,0.361657,0.273492,0.076989,-0.107742,0.290702,-0.013906,0.216838,0.214178,-0.435912,-0.460218,0.647958,0.070839,-0.214837,-0.167266,-0.049148,0.243979,0.607245,0.717556,-0.108883,0.138497,0.197033,0.328111,-0.364349,-0.257008,-0.019388,0.135383,0.191775,-0.062432,0.345457,-0.400631,0.456868,-0.030363,-0.212592,-0.766648,0.124222,0.131913,0.216742,-0.621482,0.440586,-0.293318,0.343399,0.029250,-0.204179,0.282236,0.484188,0.125859,0.198900,0.241382,-0.052144,-0.620324,0.694052,0.353530,-0.120481,-0.106635,0.137829,0.134751,-0.614466,-0.119810,-0.118073,-0.005130,0.044768,0.564278,-0.238693,-0.083097,-0.278043,-0.723922,-0.214988,-0.082507,-0.465084,0.011598,-0.479537,0.274350,-1.193332,-0.011227,-0.048728,-0.102535,-0.051031,0.144882,-0.127575,0.864281,-0.467236,0.026692,0.537234,0.431613,-0.470781,0.676887,0.111942,0.217699,-0.274063,-0.07822