INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6557030', '随风而逝', '喜剧', '德武（车太贤 Tae-hyun Cha 饰）是一名书店的老板，和好朋友杨氏终日痴迷于收集各种书本和西洋奇书。看似呆傻的德武其实是个知识渊博，聪明过人的家伙，他的真实身份是当朝右丞相的儿子。因为比金子还珍贵的冰块利益引发的政治纷争让左丞相心中不满，对于阻碍他前进的廉洁忠君的右丞相欲除之而后快。赵氏集团终因谋逆和受贿的罪名，害得右丞相和杨氏惨死，而东秀（吴智昊 Ji-ho Oh 饰）也因为对于冰库监管廉洁耿直而受到牵连。潜伏三年，德武想出一套将赵明秀团伙连根拔起的计划。他说服东秀和他的妹妹秀莲（闵孝琳 Hyo-rin Min 饰）加入自己的盗冰计划，并联合了一系列民间财力，易容，炸药，运输，潜水，情报等各个方面的高手组成了一个团队，按部就班的展开了这场疯狂的行动…该片获2012年韩国电影青龙奖第33届提名，被称为朝鲜时代版的《十一罗汉》。©豆瓣', '车太贤', '金周镐', 6.7, 7605, 'tt2448584', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1641765327.jpg', 1.1, 8.4, 52.7, 29.9, 7.9, '0.172728,0.042549,-0.639916,0.737875,-0.037047,-0.031542,0.487249,0.195162,-0.694920,-0.204671,0.133529,0.497981,-0.062508,-0.052309,0.098112,-0.168521,-0.048020,-0.728386,-0.323640,-0.068387,-0.072062,-0.622916,-0.351533,-0.313628,-0.274794,-0.389278,0.586390,0.128464,-0.231628,0.339560,0.404857,0.215700,0.019885,0.257484,-0.050798,-0.126506,-0.002766,-0.081330,-0.241505,-0.041865,-0.143688,-0.467381,-0.199545,0.197520,0.131329,0.368851,0.488430,-0.128780,-0.090977,-0.278932,0.416763,-0.331489,-0.291230,0.116847,0.497259,0.051688,0.066608,0.460342,-0.038026,0.093739,0.052069,-0.256965,-1.032309,-0.208449,0.428936,-0.044889,-0.602335,0.468797,-0.270403,-0.032424,-0.174022,-0.392332,0.188448,0.243486,0.327222,0.362233,-0.143879,0.107428,-0.480834,0.349497,0.406862,-0.019249,-0.124137,-0.016892,-0.106658,-0.467912,-0.101269,-0.494548,-0.258625,0.051045,0.331196,-0.153171,0.127796,0.286418,-0.520635,0.052164,-0.206287,-0.153339,0.105596,-0.322861,0.076047,-0.420636,-0.122347,-0.542585,-0.302221,-0.088856,0.357667,-0.344984,0.981415,-0.532902,-0.107068,0.374110,0.212650,-0.908979,0.506963,0.044489,0.090825,-0.111995,-0.231520,-0.240196,0.215085,0.079541,-0.009839,0.424926,0.079836,-0.443122,-0.113213,0.224234', '27602116', '3670447'