INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6557144', '青春期', '剧情', '当留级高中生汪小菲（王一 饰）在新班级见到同学程小雨（赵奕欢 饰）的一霎那，他宅男的幽暗世界仿佛起了石破天惊的变化，但程小雨显然不是惯常概念上的天使女孩儿，诸如和一班姐妹泡夜店翻墙逃课在男厕所抽烟之类不过是程小雨日常生活的点缀，而这一切看上去像是她对离异父母不负责任的一种报复。汪小菲不会在乎程小雨是怎样一个人，她汹涌的胸怀能够令他支棚并昏厥就已经证明了一切，汪小菲发动了频繁的纸鹤情话攻势，也能在程小雨堕胎时充当代人受过的托儿，汪小菲的努力终于屏蔽了一切不相干的外在烦扰，渐渐走到了程小雨敏感的内心世界中去。然而这时，一场牵涉到黑社会的阴谋把这班对世事懵懂的90后卷入了其中……©豆瓣', '赵奕欢', '管晓杰', 4.1, 41565, 'tt16106054', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1083225080.jpg', 38.2, 29.6, 23, 5.8, 3.5, '0.573415,0.138607,-0.598451,0.371120,-0.377234,-0.061196,0.910066,0.327167,-0.507347,-0.071476,-0.042090,0.299017,-0.148020,0.436171,0.344764,-0.155603,-0.027606,-0.643488,-0.260607,-0.062524,-0.480271,-0.493620,0.031563,-0.391952,-0.062110,-0.287686,0.263950,0.299645,-0.304544,0.259366,0.467808,0.054296,-0.245904,0.675899,-0.148696,0.014018,0.011561,0.287637,0.059514,0.164467,0.114699,-0.391984,-0.175501,0.245976,-0.172467,0.381698,0.678747,-0.170978,-0.167991,0.158830,0.396961,-0.293691,-0.056784,0.112567,0.243446,-0.108200,0.147096,-0.147446,0.019953,0.085505,0.144099,-0.171495,-0.314211,-0.161048,0.073237,0.081673,-0.430121,0.426072,0.090842,-0.274028,0.194980,-0.179423,0.268131,0.123726,0.132602,0.457629,-0.144784,0.064428,-0.381900,0.433737,0.517807,0.203454,-0.427885,0.561047,-0.270117,-0.370823,-0.174913,-0.001644,-0.529285,-0.047282,0.546076,0.029917,-0.276235,0.165773,-0.472403,0.088167,-0.019576,-0.039678,-0.316251,-0.539840,-0.102844,-0.199189,-0.249920,-0.527499,-0.160130,0.176069,-0.011917,-0.179629,0.709357,-0.946980,0.172927,0.399865,-0.149102,-0.332213,0.547455,0.043676,-0.161863,0.034276,0.200289,0.039277,-0.016341,0.323391,0.066267,0.560709,0.015938,0.153282,-0.211646,0.503856', '1308755', '3059036', '1304989', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6558801', '浪客剑心', '剧情', '经历了动荡的明治维新，日本迎来新的时代。在明治政府第十个年头，不祥的气息弥漫东京。恶德实业家武田观柳（香川照之 饰）操纵女医师高荷惠（苍井优 饰）研制新型鸦片，公开招揽落魄武夫，大肆收购周边土地，有条不紊地实现他的狼子野心。在此期间，以刽子手拔刀斋之名滥杀无辜的鹈堂刃卫（吉川晃司 饰）引起了前新選组头目斋藤一（江口洋介 饰）的注意，也迫令隐姓埋名多年的拔刀斋本尊绯村剑心（佐藤健 饰）登场。寄居在神谷道场的绯村渐渐融入神谷薫（武井咲 饰）和周边庶民的平和生活之中。然而武田欲壑难平，为了保护善良的人，剑心不得不拔出逆刃刀和相乐佐之助（青木崇高 饰）勇闯虎穴……本片根据漫画家和月伸宏的经典原作改编。©豆瓣', '佐藤健', '大友启史', 8.1, 84128, 'tt1979319', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1811862671.jpg', 0.4, 1.7, 20.3, 49, 28.6, '-0.120670,0.119002,-0.339108,0.233014,0.076819,-0.068636,0.290713,0.172006,-0.395486,-0.285636,0.368593,0.508140,-0.096131,0.013911,0.310244,0.045087,-0.106857,-0.569919,-0.263654,-0.087120,0.060924,-0.078541,-0.263772,-0.203223,-0.437595,-0.329335,0.783986,0.364855,-0.197422,0.401383,0.303013,0.560461,-0.174611,0.035178,0.078494,-0.102753,0.043703,-0.029375,-0.234252,0.166602,-0.379309,-0.295215,-0.102020,0.152398,0.087062,0.363490,0.650798,-0.260508,0.084301,-0.434337,0.448042,0.111936,-0.454295,0.085318,0.266073,0.342804,-0.105335,0.399640,-0.452363,-0.089281,-0.187094,-0.107700,-0.495177,-0.211344,0.346960,0.067166,-0.353467,0.251925,-0.136783,-0.217407,0.129229,-0.132447,0.038119,0.074164,0.466348,0.110721,-0.106280,0.039944,-0.087866,0.470711,0.451360,-0.222026,-0.315059,-0.077709,-0.031311,-0.267785,-0.192731,-0.341918,-0.053210,-0.525331,0.182061,-0.052209,0.114033,0.214413,-0.477573,-0.116779,-0.075063,-0.063251,0.442831,0.005460,-0.186315,-0.526700,-0.138193,-0.328441,-0.096347,0.046745,0.264643,-0.137532,0.777781,-0.686178,0.153081,0.415152,0.169049,-0.213116,0.112132,-0.186515,-0.230201,-0.192793,-0.325033,0.372644,0.241410,0.448732,0.067949,0.214923,-0.303979,-0.176458,-0.202879,0.121192', '3811356', '26759820', '2369613', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6560058', '雷神2：黑暗世界', '动作', '纽约大战后，雷神索尔（克里斯·海姆斯沃斯 Chris Hemsworth 饰）将弟弟洛基（汤姆·希德勒斯顿 Tom Hiddleston 饰）带回仙宫囚禁起来，此外帮助九大国度平定纷争，威名扶摇直上。虽然父王奥丁（安东尼·霍普金斯 Anthony Hopkins 饰）劝其及早即位，但索尔念念不忘地球的美丽女孩简·福斯特（娜塔丽·波特曼 Natalie Portman 饰）。与此同时，简在和黛西及其助手伊安调查某个区域时意外被神秘物质入侵，却也因此重逢索尔，并随其返回仙宫。令人意想不到的是，藏在简体内的物质来自远古的黑暗精灵玛勒基斯（克里斯托弗·埃克莱斯顿 Christopher Eccleston 饰）。在“天体汇聚”的时刻再次到来之际，玛勒基斯企图摧毁九大国度，缔造一个全然黑暗的宇宙。藏匿简的仙宫受到重创，而索尔和洛基这对冤家兄弟也不得不联手迎战宿命的强敌……', '克里斯·海姆斯沃斯', '阿兰·泰勒', 7.4, 320372, 'tt1981115', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2156839164.jpg', 0.6, 3.8, 36.2, 43, 16.4, '0.023686,0.241189,-0.824144,0.685592,0.125230,-0.194666,0.687618,0.323079,-0.428373,-0.443274,-0.021398,0.684544,-0.248525,-0.211695,0.201189,0.230341,-0.440264,-0.392033,0.083522,-0.035039,-0.262104,-0.330411,-0.405536,-0.316798,0.093627,-0.645367,0.402055,0.228243,-0.277748,0.044924,-0.016243,0.570333,-0.418079,0.389886,0.021394,-0.002791,-0.014262,0.023725,-0.494085,0.262781,-0.388980,0.006804,-0.158359,0.387094,-0.022620,0.088367,0.344305,-0.503418,0.267407,-0.420529,0.041279,-0.317248,-0.117960,-0.023677,0.349031,-0.242593,0.011652,0.290274,0.039523,-0.046651,0.157213,-0.226881,-0.527244,-0.009519,0.191199,0.102942,-0.177929,0.232279,-0.070144,0.051357,-0.104438,-0.201891,0.117598,0.448936,0.100908,0.117793,0.030462,-0.009598,-0.295274,-0.122825,0.273518,-0.261025,-0.330467,-0.177426,-0.117561,-0.379885,-0.258371,0.056956,-0.483145,-0.113494,0.387664,0.147340,0.354248,0.830125,-0.564823,-0.298024,-0.730182,-0.098875,-0.095726,-0.437849,0.047505,-0.709267,-0.170407,-0.054516,-0.153837,-0.087603,0.185745,0.058023,0.501962,-0.623210,0.542615,0.463272,0.348682,-0.147470,0.286149,0.025150,0.185808,-0.455266,-0.141660,0.769956,0.255278,0.084855,-0.085196,0.025159,0.070662,-0.072509,-0.233370,0.291122', '32