INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6601382', '活在当下', '剧情', '四年前，Tessa Scott被（达科塔·范宁 Dakota Fanning 饰）查出得了白血病，医生承认这是不治之症，于是她放弃了治疗。四年后的今天，她的父母已经分居，她和弟弟、父亲（帕迪·康斯戴恩 Paddy Considine 饰）住在一起，有一个好朋友Zoey（卡雅·斯考达里奥 Kaya Scodelario 饰）。她为自己列了一张临死前要做的清单。第一件就是进行她的第一次性行为，还有比如出名，嗑药，偷东西等等。Zoey的男朋友为她介绍了一个男生，然而在床上她却临阵逃脱了。接着她又认识了新搬来的邻居Adam（杰瑞米·艾文 Jeremy Irvine 饰），两人对彼此都有好感。Adam带着她去参加派对，开着摩托车载着她在马路上狂奔，在深夜的海里游泳，终于，他们成了情侣。然而这段感情一开始却遭到了Tessa父亲的反对。另一方面，Zoey意外怀孕，思虑再三她决定把孩子留下来。Tessa的病情正在逐渐恶化，她最后的心愿就是，能否在她离开人世之前见到Zoey的孩子？本片根据2007年Jenny Downham的小说《Before I Die》改编。', '达科塔·范宁', '欧·帕克', 7.6, 14993, 'tt1937264', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1851188222.jpg', 0.5, 4, 32.4, 43.6, 19.5, '0.279076,-0.018955,-0.672444,0.447182,-0.176990,-0.405701,0.669142,0.029865,-0.478975,-0.220083,0.164058,0.725462,-0.137791,0.399273,0.198611,0.219499,-0.368735,-0.583488,0.165165,-0.163224,-0.455464,-0.470518,-0.173757,-0.211021,-0.005053,-0.168200,0.208127,-0.153589,0.093748,0.344889,0.376991,-0.046936,0.229312,0.599177,-0.202777,0.308706,-0.063942,0.054720,-0.109855,0.202342,0.330379,-0.445540,-0.095389,0.149400,0.172703,0.531485,0.663223,-0.058000,-0.137305,0.035648,0.367855,-0.204665,0.049472,0.077753,0.310139,0.101193,0.216927,0.288246,-0.257420,-0.166490,-0.076828,0.011412,-0.409659,0.076555,0.031678,-0.030854,-0.800642,0.618248,-0.275831,0.071450,0.192533,-0.452033,0.155757,0.500748,0.051508,0.366544,-0.235462,-0.103597,-0.532803,0.370535,0.703546,-0.031908,0.061739,0.503583,-0.239771,-0.431149,0.075875,-0.152696,-0.392789,0.026294,0.349274,0.027951,-0.476007,-0.081681,-0.319842,-0.141485,-0.177939,-0.172054,0.025615,-0.339484,0.045831,-0.287877,-0.033246,-0.310727,-0.430361,0.035365,-0.143488,-0.323290,0.590089,-0.708116,0.292105,0.632519,0.336255,-0.637871,0.683354,0.192354,0.189635,-0.029306,0.095971,0.116768,-0.190420,0.377248,0.286849,0.388419,0.272596,0.127717,-0.426057,0.320998', '1299965', '2990737', '1302384', '1297606');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6710798', '恩娇', '剧情', '年逾七旬的国民诗人李适瑶（朴海日 饰）隐居在一处偏僻的别墅中，生活起居全由弟子徐志有（金武烈 饰）打点，而徐志有作为文坛新秀，即将推出他的第一本小说《心脏》。恩娇（金高恩 饰）的无意闯入打破了李适瑶和弟子平静的生活，恩娇年轻漂亮，又天真懵懂，李适瑶在她的身上似乎找回了一 点昔日的青春活力。看到自己敬仰的恩师居然和一个十七岁的女学生纠缠不清，而自己的地位正在逐渐下降，徐志有有一点难以接受，但更多的，是嫉妒。李适瑶以恩娇为主人公写了一篇短篇小说，被徐志有发现并以自己的名义发表，没想到这篇意淫的产物居然获得了当年的文学奖。李适瑶暴怒，与徐志有发生了激烈的争吵，原来徐志有并没有创作过小说，他不过是李适瑶的影子写手。这一切被刚好经过的恩娇看在眼里。恩娇也读了那篇小说，误以为徐志有对自己有意，这一点点的误会却为这三人错综复杂的关系带来了毁灭性的结局。©豆瓣', '朴海日', '郑址宇', 6.8, 26527, 'tt2390253', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1597191869.jpg', 1.3, 8.3, 49.8, 31.3, 9.3, '0.339861,-0.163523,-0.708239,0.904868,-0.047718,-0.368182,0.947643,0.055231,-0.547003,-0.456810,0.060817,0.753075,-0.416231,0.174156,0.090235,-0.232092,-0.075685,-0.678465,-0.230425,-0.202537,-0.161125,-0.395204,-0.317958,-0.077107,-0.216438,-0.289738,0.707913,0.228848,-0.432331,0.343054,0.358947,0.163981,0.091601,0.550406,-0.263628,0.215307,-0.103993,0.230452,0.132908,0.009325,0.042598,-0.531327,-0.143120,0.231599,-0.115109,0.455963,0.745480,-0.263128,-0.419157,0.140256,0.673438,-0.252331,-0.117553,0.172246,0.322172,0.070239,0.187684,0.034034,-0.051809,0.010476,-0.092317,-0.238479,-0.954655,-0.042295,0.233772,0.121096,-0.477185,0.657347,0.027026,-0.188285,-0.040247,-0.215412,0.273120,0.249934,0.404254,0.390592,-0.229468,-0.108425,-0.385545,0.384016,0.499853,0.120614,-0.293464,0.492790,-0.435595,-0.400351,0.019053,-0.266473,-0.496457,0.126985,0.225647,0.174011,-0.128664,0.294882,-0.400357,-0.067939,-0.052865,-0.337845,0.016984,-0.602619,-0.151172,-0.210769,-0.441796,-0.495096,-0.123744,-0.046795,0.204037,-0.435054,0.913963,-0.866835,0.222993,0.323702,0.179913,-0.602460,0.716126,0.115694,-0.131921,0.085620,-0.221063,0.214217,0.051187,0.336817,0.135442,0.349499,-0.001529,-0.341774,-0.403425,0.527643', '27602116', '1303542', '27666513', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6714088', '变身男女', '剧情', '电影《假如我是你》是国内首部涉及“换体”爱情的电影作品。千年难遇的太阳磁暴，把巨大的宇宙能量带到地球，鬼才发明家（午马 饰）带着刚发明的“情爱颠覆伞”来到人间。花心男单民（林志颖 饰）是一个在浙江音乐调频工作的DJ。内心渴望成为一名主持，却总因为紧张就结巴，终究未能如愿以偿。穿梭于情场的小艾（姚笛 饰）是一个酒托，从小在孤儿院长大的她，机灵善变，以骗男人为生，把欺骗当作保护自己的最好武器。两个人毫无关系的人在雷雨夜邂逅，正巧被“情爱颠覆伞”交换了灵魂，进入了对方的身体，于是一个成了伪娘，一个成了“春哥”。从高级商圈到魅惑夜场，从床头到床尾，这对错位男女经历了一次又一次身心的纠缠，各种啼笑皆非的身份换位，各种HOLD不住的百出笑料……©豆瓣', '林志颖', '李旗', 5, 21022, 'tt2457228', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1367790549.jpg', 13.5, 35.3, 40.1, 8.2, 2.8, '0.185064,0.189717,-0.680498,0.481508,-0.327446,-0.014351,0.767083,0.182302,-0.333756,-0.034195,0.237083,0.612113,-0.260981,0.295166,0.118356,0.066346,0.015909,-0.703817,-0.027916,-0.044604,-0.388654,-0.102219,-0.248841,-0.019156,-0.142654,-0.405028,0.633195,0.167744,-0.481391,0.111228,0.412138,0.137062,-0.077950,0.299216,-0.526647,0.016305,0.029160,0.041073,-0.133977,0.227410,-0.257927,-0.339646,-0.000241,0.119388,-0.230374,-0.023186,0.768039,-0.145601,-0.139660,0.046862,0.533394,-0.280230,-0.347681,-0.098924,0.110808,0.114237,0.044597,-0.191659,-0.271293,0.314967,0.291476,-0.052097,-0.938279,0.005641,-0.085539,0.162272,-0.647789,0.484520,0.055447,-0.138211,-0.111822,-0.198269,0.218108,-0.024465,0.154347,0.568615,-0.264038,0.112181,-0.463557,0.304679,0.608639,0.098210,-0.359395,0.573754,-0.054134,-0.346689,-0.090080,-0.143098,-0.511783,-0.169189,0.335957,-0.287459,-0.275814,0.279998,-0.691493,0.054182,-0.012567,-0.016946,0.189388,-0.489866,-0.034377,-0.463394,-0.235188,-0.511405,-0.184643,0.171396,0.285789,-0.243834,0.928451,-0.748999,0.193323,0.674005,-0.133652,-0.458310,0.648821,0.176125,0.045429,-0.229943,0.088461,0.248224,0.105495,0.360255,0.094550,0.644152,0.094415,0.224703,-0.529230,0.483115', '24284209', '25928048', '27602116', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6714930', '斯大林格勒', '动作', '1942年秋天，人类史上最惨烈的一场战争在寒冷的土地上爆发。德国人穿越伏尔加河抵达对岸斯大林格勒设防固守，苏联红军与对手展开城市争夺战，双方你来我往，城市化作废墟焦土，成千上万人死亡，放眼望去俨然人间地狱。在一次反攻行动中，苏军严重伤亡，仅有大尉格罗莫夫（彼得·费奥多罗夫 Pyotr Fyodorov 饰）率领的侦察小队到达对岸，占领了一栋破烂的建筑。他们在建筑内发现一名19岁少女卡嘉（玛丽亚·斯莫尔尼科娃 Mariya Smolnikova 饰）。卡嘉的父母早已死于战火，由于眷恋自由生长的城市和家园，女孩固守此地，麻木穿梭战火之中。鉴于建筑的位置极其重要，极度厌战的德国军官彼得·卡恩（托马斯·克莱舒曼 Thomas Kretschmann 饰）奉命夺回该据点。惨烈无情的修罗场，人性和兽性的角力永无休止……©豆瓣', '彼得·费奥多罗夫', '费奥多尔·邦达尔丘克', 6.3, 19784, 'tt1966566', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2155349825.jpg', 4.4, 16.6, 48.2, 23, 7.8, '0.043357,-0.188224,-0.836022,0.111043,0.327718,0.137866,0.789525,-0.147151,-0.381029,0.048360,0.577882,0.417047,0.030994,-0.220995,0.343405,-0.255378,-0.336041,-0.531673,-0.241966,-0.159131,-0.195704,-0.467062,-0.545130,-0.236132,0.166403,-0.452766,0.854385,0.509037,-0.184848,0.287524,-0.139882,0.099658,-0.259961,0.301737,0.082672,-0.270814,0.204860,-0.379124,-0.492315,0.096810,-0.819401,-0.108024,-0.124215,-0.044540,-0.262070,0.339187,0.997478,-0.305220,0.126785,-0.178019,0.116454,-0.159356,0.053946,0.237915,0.429968,-0.378157,-0.087134,0.081090,-0.021963,-0.091434,-0.215333,-0.247290,-0.109093,-0.003613,-0.037647,0.232079,-0.305464,0.893126,0.053702,0.010100,0.130208,-0.197089,0.073190,0.430967,0.200118,0.305179,-0.252839,-0.152243,-0.456610,-0.101173,0.673952,-0.065948,-0.393449,-0.163704,-0.166547,-0.382674,-0.006348,-0.363270,-0.417331,-0.185194,0.121216,-0.192415,0.127219,0.525104,-0.927202,0.148438,-0.373168,-0.429418,-0.194779,0.102497,-0.372907,-0.659860,-0.121279,-0.208163,-0.198614,0.295628,-0.212034,0.280259,0.463254,-0.409870,0.306251,0.273841,0.372149,0.053542,0.271560,-0.021709,0.240427,-0.278648,0.052195,0.850237,-0.088930,0.451185,0.063190,0.091104,-0.422615,-0.031570,-0.318712,0.498612', '21619567', '1856675', '