INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6717573', 'SPEC：天', '剧情', '掌控日本国家未来的御前会议上，众要员商议着以猎杀SPEC持有者为目标的“SIMPLE PLAN”，神秘的法蒂玛第三预言亦被提及。数天后，暗中执行猎杀计划的政府成员突然于游艇上全员木乃伊化死亡。案件交由未详系的当麻纱绫（户田惠梨香 饰）和濑文焚流（加濑亮 饰）负责。调查途中两人接到志村美玲（福田沙纪 饰）的求救电话，赶赴救援时与濑文的前同僚兼前恋人青池里子（栗山千明 饰）不期而遇。当麻将美玲带回未详系，原本已经死去的阳太/一十一（神木隆之介 饰）竟从容现身于她们面前。竭力压制着蠢蠢欲动的左手，当麻无力的目睹美玲匆忙留下“一定要阻止法蒂玛第三预言”的信息后被阳太带走。在阳太的恶意煽动下，普通人类与SPEC持有者间的矛盾日益激化。身处两者夹缝之中，当麻对法蒂玛第三预言和人类未来的走向充满了迷惑。玛利亚、白衣教皇、左手持火之剑的天使……预言中的关键人物们若隐若现，黑暗降临的未来是否终将无法避免？', '户田惠梨香', '堤幸彦', 7.5, 24891, 'tt1881045', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1691931793.jpg', 0.8, 4.7, 32.2, 41.2, 21.1, '0.175033,0.180829,-0.505372,0.339422,0.291337,-0.056612,0.526973,0.046284,-0.131643,-0.448643,0.172856,0.473399,-0.038287,0.012418,0.497705,-0.104062,-0.323873,-0.741947,-0.296004,0.033421,-0.324377,-0.358702,-0.275833,0.146023,-0.209758,-0.397448,0.780939,0.148844,-0.354277,0.443501,0.320191,0.718183,-0.496653,0.127291,-0.011389,-0.250837,0.065264,0.063400,-0.392823,0.168547,-0.258767,-0.260783,-0.016760,0.246783,-0.234289,0.227080,0.559041,-0.692502,-0.037816,-0.573565,0.193874,-0.346278,-0.189594,0.096502,0.456668,0.292212,0.161725,0.326596,-0.261010,-0.021096,0.101418,0.034415,-0.824562,-0.040079,0.116154,0.325115,-0.313250,-0.040235,0.013160,0.116662,0.279795,-0.153827,0.129688,0.370370,0.091496,-0.076218,-0.319786,-0.112069,-0.065814,-0.043270,0.383336,-0.007290,-0.138835,-0.102967,-0.056452,-0.244530,-0.105151,-0.115628,-0.253088,-0.084082,0.154405,0.382758,0.218865,0.379311,-0.560100,-0.304597,-0.279023,-0.128305,0.142241,-0.080391,-0.054884,-0.775201,0.035158,-0.292157,-0.371534,0.100268,0.355928,-0.073401,0.447988,-0.799065,0.241251,0.209390,0.354230,-0.295473,0.261056,0.217905,0.370676,-0.392698,-0.188781,-0.050770,0.115457,0.444074,0.115950,0.176699,-0.163321,0.003890,-0.466097,0.180160', '2369613', '25723905', '26759819', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6717574', 'SPEC：翔', '剧情', '经过长时间的休整，治疗眼伤的濑文焚流（加濑亮 饰）终于随着当麻（户田惠梨香 饰）重返阔别已久的未详，只是此时来自公安部公安五课的市柳（でんでん 饰）和吉川（北村一辉 饰）握得实权，令濑文等人颇为气闷。与此同时，在市井算命的觉被一掌握瞬间移动能力的黑衣男子射杀，同时遇害的还有觉的保镖以及几名无辜市民。父母双双遇害而作为幸存者并且目击了黑衣人真实容颜的少女久远望（谷村美月 饰）便成为对方追杀的目标。为了保护小望，未详同仁通力合作，并持续追索黑衣人的真面目以及其背后的阴谋。在此期间，当麻也展示了其不为人知的SPEC。一场斗智斗勇的战斗拉开了序幕……©豆瓣', '户田惠梨香', '堤幸彦', 8.5, 31173, 'tt1988184', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1818196069.jpg', 0.4, 1.4, 14.3, 42.7, 41.2, '0.064481,-0.166692,-0.318141,0.197380,0.192621,-0.072214,0.719701,0.073854,-0.441808,-0.450045,0.525220,0.427705,-0.217472,0.140658,0.356681,-0.329738,-0.247809,-0.893798,-0.314700,-0.165781,-0.431358,-0.218917,-0.277844,-0.323061,-0.134808,-0.315234,0.780655,0.204194,-0.119157,0.486653,0.234622,0.287123,-0.419840,0.381503,-0.046139,-0.146044,0.145328,-0.202989,-0.300112,0.155344,-0.161615,-0.429437,-0.018832,0.144839,-0.177908,0.480132,0.709250,-0.315430,0.011561,-0.055335,0.163205,-0.199328,-0.085928,0.159202,0.403388,0.052941,0.133107,0.162071,-0.342943,-0.098533,-0.055472,0.031437,-0.651340,0.001562,0.462908,0.254932,-0.252951,0.444708,0.005265,-0.238209,0.219651,-0.135217,0.043160,0.313489,0.170904,0.200933,-0.042945,0.110796,-0.037924,0.264224,0.326337,-0.110052,0.028485,0.116791,-0.112001,-0.502289,-0.224790,-0.140984,0.006945,-0.285914,0.402212,0.258209,0.225700,0.046502,-0.282394,-0.163372,-0.311980,-0.010670,-0.096180,-0.267416,-0.181996,-0.596173,-0.013227,-0.450350,-0.096315,0.494205,0.157391,-0.020500,0.604801,-0.746609,-0.007636,0.395782,0.229159,-0.142685,0.261097,-0.029654,0.168255,-0.146672,-0.289494,0.328789,0.229991,0.322483,0.146471,0.232347,-0.266343,-0.098948,-0.132483,0.070961', '25723905', '4202326', '10467125', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6717575', '开心魔法', '喜剧', '在世界上，很多不可思议，无法解释的事情，其实是有原因的，因为世界上存在着一个由“金、木、水、火、土”五行构成的魔法世界，世界上存在着形形色色的魔法师。康森贵（黄百鸣 饰）虽然表面上是一名大学教授，实际上却是一名水系魔法师。一天，由于名为毕野武（吴京 饰）的火系魔法师想通 过收集五行魔法，回到过去，找到康森贵，想夺取他的法力。一场对战之后，却阴差阳错的，康森贵的魔法却被转移到了自己学生陈美斯（吴千语 饰）身上。随着毕野武不断挑战各系魔法师，他收集的五行能量就差美斯身上的水系能力和金系能量。美斯在凌枫（吴尊 饰）的帮助下，找出了金系魔法师查理（松明 饰）的所在，并一同前往准备保护查理免受毕野武的侵害。然而，当他们赶到时，毕野武突然出现在查理表演的舞台上，一场大决斗即将展开。©豆瓣', '吴千语', '叶伟信', 4.4, 15753, 'tt2072164', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1309420639.jpg', 25.9, 37.7, 27.6, 5.4, 3.4, '0.318005,0.274026,-0.534589,0.625357,-0.128238,-0.004846,0.780114,-0.040824,-0.289972,-0.574027,0.316115,0.698334,-0.106349,0.275496,0.099467,-0.160497,-0.194595,-0.412679,0.028036,-0.172838,-0.632953,-0.601787,-0.576934,0.185876,-0.121620,-1.007138,0.793380,0.215799,-0.436566,0.100171,0.207156,0.181777,-0.137575,0.440981,-0.061194,-0.282650,-0.039829,0.132755,-0.017809,0.356194,-0.060771,-0.237985,0.105342,0.168429,0.081351,0.109234,0.676756,-0.535737,0.360520,-0.206688,0.362001,-0.381491,-0.003708,-0.007581,0.409855,0.348559,0.121627,-0.245923,0.021852,0.133637,0.069354,-0.084973,-0.995718,-0.050519,0.309871,0.142069,-0.556596,0.362698,0.124066,-0.268263,-0.290197,-0.509864,0.072244,0.046177,0.107843,0.369718,-0.408809,-0.084006,-0.292527,-0.222784,0.615894,-0.007066,-0.092929,0.399679,-0.212418,-0.509225,-0.566114,-0.184962,-0.295682,-0.144238,0.331923,0.497672,0.328994,0.058126,-0.954591,0.134579,-0.061571,-0.168301,0.082654,0.015018,0.131355,-0.630573,0.084533,-0.255358,-0.491105,0.096540,0.298452,-0.287385,0.922878,-0.881918,0.282251,0.535027,0.496757,-0.211770,0.484200,-0.068233,0.242955,-0.367441,-0.167116,-0.019938,0.163337,0.556138,0.187554,0.629082,-0.042707,-0.026818,-0.286330,0.737220', '3769423', '26667010', '2051813', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6719716', '僵尸胡安', '喜剧', '社会主义国家古巴，生活在社会最底层的中年男子胡安（Alexis Díaz de Villegas 饰）一事无成，他和老婆离婚，女儿卡米拉（Andrea Duro 饰）也全然不将其放在眼里。胡安终日和两位损友拉扎洛（Jorge Molina 饰）、加利福尼亚（Andros Perugorría 饰）胡混，未来全无希望。某天，平静的城市突然布满恐慌，一种莫名的僵尸病毒肆意蔓延，所有被感染的人类全部化身嗜血如命的丧尸。在人们心生惶恐、急欲逃离这座城市的时候，胡安却想出一条生财之道。他召集好友和其他市民组成一个小公司，专门负责帮那些不忍对亲人化作丧尸的正常人动手。他的事业蒸蒸日上，而与女儿的关系也渐渐弥合……本片荣获2012年布鲁塞尔国际奇幻电影节银鸦奖、2012年葡萄牙奇幻电影节最佳男主角奖（Alexis Díaz de Villegas）、2012年迈阿密电影节观众奖。', '安德烈娅·杜罗', '亚历杭德罗·布鲁格斯', 7.2, 15650, 'tt1838571', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1684700483.jpg', 1.4, 6.1, 37.5, 41.9, 13.1, '-0.286453,-0.116720,-0.558498,0.471187,-0.013741,-0.120564,0.675003,-0.020297,-0.454792,-0.038671,-0.008757,0.839382,-0.224049,0.217209,0.171043,-0.199653,-0.258150,-0.681203,-0.169300,-0.095911,0.015274,-0.070917,-0.245885,-0.409680,-0.153453,-0.295782,0.838033,0.081224,0.070843,0.446544,0.297537,0.259067,-0.177284,0.340607,-0.130158,-0.075595,0.028743,-0.140220,-0.302493,0.020648,-0.206376,-0.007074,-0.282039,0.131150,-0.033227,0.108337,0.738124,-0.111676,0.033808,-0.398256,0.418018,-0.289842,-0.050384,0.026760,0.206464,-0.240608,0.033510,-0.010861,-0.000190,-0.114382,0.233194,-0.341615,-0.463807,0.061678,-0.008082,0.178786,-0.351428,0.461145,0.015440,0.125295,-0.145914,-0.144764,0.193883,0.105119,0.126801,0.356318,-0.197163,0.141721,-0.456773,0.442191,0.546042,-0.003871,-0.432988,0.095672,-0.483330,-0.384528,-0.272088,-0.268957,-0.541565,-0.273627,0.341804,0.008539,-0.303550,0.606052,-0.632163,-0.035733,-0.010615,-0.276715,-0.030559,-0.181340,0.039857,-0.371221,-0.156069,-0.135306,-0.092094,-0.005762,0.142365,-0.067636,0.719488,-0.608915,0.259358,0.344994,0.414755,-0.613941,0.714743,-0.154113,0.022297,-0.174673,-0.380594,0.320584,-0.014409,0.242571,0.011565,0.168617,-0.205085,-0.025772,0.091762,0.354