INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6721670', '秦时明月之龙腾万里', '动画', '千年之前，一场可怕的战争燃烧了整片大地。蚩尤将战火引向各处，最终他被黄帝打败，遭到封印。然而野心勃勃的帝王秦始皇派出铁骑入侵楼兰，寻找传说中的可怕武器“兵魔神”。某边塞小镇，顽皮机警的少年荆天明（冯骏骅 配音）意外卷入一场最敬爱的吕老伯（程玉珠 配音）和神秘阴阳家的纷争之中，在被追杀的关键时刻，他得到了天下第一剑客盖聂（刘钦 配音）和项氏一族少主项小羽（沈达威 配音）的援助。吕老伯此前曾叮嘱天明将一个神秘物件送到楼兰，而他和盖聂、项小羽等人的邂逅，也无疑使他的命运发生巨大的转变。秦汉之际，风起云涌，英雄辈出，天明他们见证着一个又一个传奇时刻……©豆瓣', '冯骏骅', '沈乐平', 6.9, 30617, 'tt5545866', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1994460614.jpg', 4.3, 10.6, 39.4, 29, 16.6, '0.040976,0.121569,-0.594854,0.694454,-0.029113,0.247611,0.641753,-0.024327,-0.420500,-0.479070,0.354466,0.674685,-0.253820,0.063621,0.399201,0.015378,0.321812,-0.781469,-0.165871,0.251898,-0.228464,-0.097620,-0.624803,-0.143107,0.014240,-0.220389,0.491403,0.374738,-0.399846,0.400186,0.034016,0.199111,-0.391423,0.751976,-0.198021,0.115625,-0.056561,0.036722,-0.053051,0.291202,-0.231495,-0.493211,-0.052411,0.452947,-0.375117,0.301909,0.366628,-0.546506,0.145973,-0.211753,0.325271,-0.529365,-0.124065,0.143139,0.452313,0.061205,-0.077448,0.255754,-0.040885,-0.186090,0.042205,-0.221572,-0.679383,-0.009818,-0.006372,-0.105860,-0.485564,0.507156,0.317806,0.235641,0.036274,-0.069569,0.553829,0.318043,0.480742,0.081406,-0.027769,-0.131818,-0.278842,0.366928,0.619500,-0.396845,-0.082258,-0.086929,0.329320,-0.407436,-0.007466,-0.307370,-0.521878,0.103888,0.572765,-0.011458,0.128501,0.315451,-0.789025,-0.062877,-0.346737,-0.100147,-0.029061,-0.092675,-0.228516,-0.357326,-0.265795,-0.270470,-0.214779,0.038061,-0.024268,-0.273810,0.704784,-0.489548,0.019306,0.399176,0.080456,-0.395665,0.457729,-0.032199,0.188886,-0.017977,0.035569,0.241477,0.201662,0.422481,0.283182,0.217937,-0.272693,0.125374,-0.307028,0.410692', '1309031', '25828589', '30162520', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6722730', '五月的四天', '剧情', '德国，二战结束前的四天。一位率领着他的部队占领海边孤儿院的苏联军官。一支在海滩驻扎的纳粹德国国防军部队。一种反常的危险的爱。所有人都对战争感到疲惫，只有十三岁的孤儿彼得，想要证明自己是一个英雄，千万百计煽动两支部队。直到他意识到，真正的敌人早就潜伏在其他地方，而他所谓 的敌人，其实是如父亲般的朋友。这时划清的不是敌与友之间的界线，而只是善与恶之间的界线。', '帕维尔·文策尔', '阿希姆·冯·博里斯', 8.5, 11297, 'tt1699202', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1918431516.jpg', 0.4, 1, 11.6, 48.4, 38.6, '0.583677,0.015513,-0.904942,0.797220,-0.064740,0.043579,0.909478,-0.097780,-0.549850,-0.099733,0.341167,0.723311,0.395178,0.152552,0.184101,-0.122467,0.141380,-0.929430,-0.265892,-0.374938,-0.250453,-0.617168,-0.510061,-0.394835,-0.166991,-0.356146,0.888595,0.369143,-0.172241,0.382754,0.200815,0.279597,0.075651,0.544341,-0.117778,-0.358288,0.109926,-0.254074,-0.383974,0.012447,-0.234442,-0.008615,-0.127926,0.363376,-0.307085,0.431250,0.694280,-0.325080,-0.157732,-0.104052,0.155300,-0.404939,0.029918,0.008280,0.654621,-0.134708,0.040880,0.171385,0.230355,0.138207,-0.314050,0.092425,-0.732423,-0.203934,0.004068,0.268444,-0.493323,0.583974,-0.078286,-0.000809,0.399355,-0.157472,0.274489,0.756310,0.037018,0.323942,-0.449750,-0.061189,-0.680658,0.106549,1.087344,-0.278439,-0.300666,0.186388,-0.162582,-0.317120,-0.123242,-0.204972,-0.419924,-0.100794,-0.070860,-0.252468,-0.191302,0.135471,-0.772891,0.000344,-0.119828,-0.174116,0.030172,-0.486746,0.080600,-0.416937,-0.019284,-0.657443,-0.290227,0.464838,0.025262,0.007419,0.760346,-0.838012,0.175561,0.835147,0.282614,-0.387742,0.758500,0.182322,0.022753,-0.250303,0.139771,0.502375,-0.085441,0.263533,0.108888,0.238669,-0.096165,0.032014,-0.372622,0.482818', '25721544', '25828589', '1870682', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6722879', '她', '剧情', '《她》是讲述在不远的未来人与人工智能相爱的科幻爱情电影。主人公西奥多（杰昆·菲尼克斯 Joaquin Phoenix 饰）是一位信件撰写人，心思细腻而深邃，能写出最感人肺腑的信件。他刚结束与妻子凯瑟琳（鲁妮·玛拉 Rooney Mara 饰）的婚姻，还没走出心碎的阴影。一次偶然机会让他接触到最新的人工智能系统OS1，它的化身萨曼莎（斯嘉丽·约翰逊 Scarlett Johansson 声）拥有迷人的声线，温柔体贴而又幽默风趣。西奥多与萨曼莎很快发现他们如此的投缘，而且存在双向的需求与欲望，人机友谊最终发展成为一段不被世俗理解的奇异爱情......《她》主要在中国上海取景，由美国导演斯派克·琼斯历时3年筹备拍摄。电影融合了新奇的科幻设定与传统的浪漫气息，真人与虚拟共同谱写温暖治愈的恋曲。导演表示，这是一部探讨“亲密关系”的电影，因人类都渴望亲密关系，但是又对它害怕和抗拒；科技为沟通提供了便利，但也让人们躲在它后面，逃避真正的情感接触。《她》直接脱去科技冰冷的面纱，赋予它高度人性化和活色生香的情趣，让一段人机对话变成情人絮语。', '华金·菲尼克斯', '斯派克·琼斯', 8.4, 417532, 'tt1798709', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2166850749.jpg', 0.3, 1.4, 14.4, 44.5, 39.4, '0.270839,0.142842,-0.605279,0.842630,0.082550,-0.053753,0.893642,-0.024507,-0.334450,-0.137842,0.044588,0.649373,-0.315102,-0.025121,0.080887,-0.006367,-0.368092,-0.611031,0.195363,0.016376,-0.104414,-0.379294,-0.464125,-0.289355,-0.091942,-0.484908,0.918185,0.113250,-0.610282,0.381638,0.089521,0.064664,-0.212171,0.417585,-0.111303,-0.186949,0.046347,0.189260,-0.406919,0.172663,0.008714,-0.051069,-0.086210,0.240768,-0.245325,0.265185,0.572638,-0.319759,-0.241404,0.139467,0.492899,-0.116656,0.002000,0.096806,-0.108974,0.183823,0.211578,0.238224,-0.152433,-0.068827,-0.024579,-0.121146,-0.945511,0.068090,-0.083398,0.184216,-0.199243,0.427822,-0.101643,-0.164738,0.177135,-0.350535,0.130386,0.185903,0.501805,0.506836,-0.097125,0.157144,-0.245968,0.394375,0.673916,0.022964,-0.504945,0.815843,-0.431299,-0.622832,-0.231787,-0.272593,-0.515062,0.000708,0.169721,0.201161,-0.007295,0.294974,-0.873978,0.153066,-0.001255,0.059052,0.103670,-0.624147,0.312331,-0.719281,-0.488461,-0.488904,-0.370154,-0.218374,0.214186,-0.584257,0.895890,-0.732972,0.128413,0.500545,0.250115,-0.544618,0.934499,0.177232,-0.111046,-0.306696,-0.041026,0.473363,-0.071437,0.051600,-0.006069,0.402056,0.228972,0.183104,-0.430164,0.567779', '2053515', '35360296', '1303542', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6722888', '醉后一夜', '喜剧', '一觉睡醒，沈伟（余文乐 饰）和桐欣（张静初 饰）赫然发现陌生的彼此竟然赤裸相见，于是匆匆作别。更诡异的是，他们出门时发现自己置身于家具城中。宿醉的他们拼命回忆着昨晚发生的一切：沈伟记得是被一堆朋友约来给某女过生日，结果在嬉笑怒骂之后来到了夜店，歌舞升平之后，他便失去了记 忆。桐欣记得自己背负着导演要把30万巨款交给女演员的重任，但是酒过三巡，她似乎也失去了知觉。他们在混乱且游离的记忆中重返现实：沈伟发现新浪微博上竟是他迷醉的照片，令周围同事对他与娱乐圈某女的八卦乐此不疲。而桐欣则一直遭到导演的逼问事情的结果，而她在忙乱间回到了前男友的住所，并见到了她的继任者。阴错阳差之后，沈伟和桐欣重逢，回到了家具城，从前台领走了各自的物品。但是桐欣却找不到那笔30万巨款。在分析了蛛丝马迹之后，沈伟陪桐欣来到了公安局报警，结果警方却把一只无人认领的羊驼给了他们，两个人面面相觑……', '余文乐', '曾国祥', 5.4, 20552, 'tt2458256', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1557411020.jpg', 8.4, 28.3, 48.8, 11.5, 3, '0.344662,0.150992,-0.895807,0.142531,-0.020390,-0.478842,0.758758,0.051951,-0.731115,-0.331467,0.029089,0.789019,-0.432584,0.303606,0.255740,-0.051840,-0.284139,-0.870854,0.033340,-0.201451,-0.323467,-0.316330,-0.022981,-0.038721,-0.067728,-0.042320,0.157567,0.079437,-0.114173,0.576531,0.206935,-0.040946,-0.268939,0.822380,-0.135042,0.289954,-0.010908,0.213116,-0.138759,0.229736,0.216692,-0.398057,-0.346403,0.327320,-0.076224,0.408104,0.803108,-0.119673,-0.432073,0.232428,0.185562,-0.223420,-0.199737,0.195883,0.141732,0.230954,0.142205,0.020481,-0.463693,0.057276,0.006892,0.035170,-0.513566,0.180871,-0.133070,0.313606,-0.649775,0.494705,-0.049731,0.118459,0.085297,-0.316920,0.406896,0.348631,0.119837,0.446242,-0.014402,-0.007640,-0.551080,0.242612,0.556730,-0.051763,0.005841,0.627554,-0.079139,-0.451618,-0.207083,0.126958,-0.251998,0.053027,0.464914,0.196417,-0.240978,-0.116404,-0.712176,-0.165881,-0.156051,-0.325706,-0.264764,-0.402905,-0.225893,-0.322063,-0.253743,-0.193935,-0.385536,0.252769,0.015486,-0.098053,0.465069,-0.759423,0.183685,0.408423,0.197011,-0.565315,0.583812,-0.147746,-0.010305,-0.110972,0.083159,0.054153,0.224936,0.593584,0.502784,0.255161,-0.258667,-0.104090,-0.631452,0.275739', '1305224', '3111650', '1301022', '1293142');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6727307', '奥特曼传奇', '动作', '受到突如其来的怪兽袭击，地球上的人类几乎灭亡。为了人类最后的希望，由7名女性组成的TEAM·U守护着地球上最后的孩子。与此同时，因为听到呼唤而从其它宇宙前来的赛罗奥特曼、戴拿奥特曼和高斯奥特曼成功与TEAM·U会合。而侵略地球的幕后元凶百特星人，亦把魔手伸向地球上仅存的孩子……', '内藤大湖', '冈秀树', 7.5, 4872, 'tt2109245', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1787977985.jpg', 2, 6.8, 32.6, 33.7, 25, '0.173974,0.373142,-0.857078,0.690086,-0.090663,0.066127,0.907623,-0.053315,-0.226045,0.023954,0.203309,0.831014,0.064732,0.103109,0.362849,0.109457,-0.137687,-0.468683,-0.136787,0.124553,-0.597605,-0.276587,-0.437255,-0.128360,-0.004741,-0.464971,0.829407,-0.182827,-0.153869,0.453279,0.351654,0.387531,-0.500308,0.280283,-0.142177,-0.258643,-0.583343,-0.055429,-0.392269,0.392267,-0.243924,0.003061,0.441053,0.430001,-0.793970,0.101424,0.851867,-0.932860,0.545673,-0.849490,0.318345,-0.601594,-0.052584,-0.033669,0.323133,0.204841,-0.018187,0.080509,0.276808,-0.080871,0.435958,-0.121147,-0.951622,-0.047864,0.173242,0.106608,-0.461383,0.463412,0.085777,0.270322,0.316180,-0.052824,0.493316,0.552171,0.457160,0.462642,-0.320317,0.225143,-0.334715,-0.272515,0.452311,-0.421522,-0.277713,-0.097004,-0.020921,-0.470513,-0.226082,-0.486703,-0.461710,0.130299,-0.018269,0.318326,-0.307244,0.313043,-0.883152,0.064322,-0.050553,-0.424917,0.174162,-0.484560,-0.081671,-0.545410,0.170457,-0.200670,-0.061002,0.219036,0.450197,-0.080219,0.991876,-0.516236,0.369737,0.680252,0.763640,-0.133487,0.678210,-0.244055,0.196140,-0.311300,-0.124693,0.214733,0.345306,0.462360,0.060975,-0.138501,-0.323537,0.169808,-0.167135,0.511961', '25774050', '26667010', '3769423', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6730004', '爱', '剧情', '台湾富商马克（赵又廷 饰）跟名媛方柔伊（舒淇 饰）有染，但却无法给她承诺。这令她极为伤心，气急败坏离开酒店，在街头遭遇酒店服务生小宽（阮经天 饰）偷拍，柔伊怒砸相机，随即与富商陆平（钮承泽 饰）驾车离去。原来柔伊本是陆平的情人，但是却无法获得一纸婚约。倒是因为那次相遇，她和口吃的小宽发生了一段感情……小宽的妹妹宜珈（陈意涵 饰）是自行车选手，她的闺蜜是钮承泽的独女小霓（郭采洁 饰），后者习惯性跟她抱怨男友阿凯（彭于晏 饰）的诸般不好，但是宜珈却持相反意见并暗度陈仓。于是一道三角恋开始分割友情……马克去北京出差，欲购一套四合院，与房地产中介小姐小叶（赵薇 饰）不打不相识，并在民警的怂恿下，阴错阳差充当了她儿子豆豆的父亲。从此，一段海峡之恋由此展开……©豆瓣', '舒淇', '钮承泽', 6.9, 222446, 'tt2202471', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1382128012.jpg', 1.4, 7.8, 45.6, 35.3, 9.9, '0.347822,0.024295,-0.427876,0.556639,0.064004,-0.168576,0.678597,0.268743,-0.342714,-0.155919,0.268484,0.651867,-0.253951,0.327840,0.100018,0.035169,-0.134600,-0.491889,0.309720,-0.101785,-0.022510,-0.468551,0.028615,-0.122214,-0.144848,0.083100,0.401778,-0.127084,-0.229594,0.482424,0.515375,0.096699,-0.357841,0.519687,-0.112037,0.255343,-0.089178,0.138264,-0.428928,-0.129334,0.114214,-0.236259,-0.051144,0.098044,0.272303,0.448138,0.569528,-0.061864,-0.087781,0.034003,0.294254,0.004900,0.113449,0.134966,0.156094,0.064833,0.473445,0.062399,-0.199689,-0.112713,0.240214,0.016693,-0.001722,0.240928,0.072026,0.000324,-0.408356,0.477430,-0.374114,0.046557,0.028026,-0.376361,0.089910,0.154282,0.245620,0.113858,-0.099874,0.106362,-0.496559,0.301345,0.566520,0.186248,0.178893,0.492322,-0.142751,-0.457071,-0.213670,0.169772,-0.508420,-0.001815,0.328945,-0.184942,0.008281,0.012885,-0.540941,-0.140376,-0.310463,0.240920,0.130461,-0.307049,0.097278,-0.325544,0.018994,-0.516491,-0.276092,-0.007016,0.166082,-0.137240,0.366833,-0.690757,-0.057448,0.193325,0.407044,-0.427516,0.561014,0.141900,0.088059,-0.225945,0.076611,0.157180,-0.142918,0.010046,0.186661,0.316451,0.057705,-0.184017,-0.144448,0.172359', '1308755', '21766698', '1296534', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6731985', '大厨', '喜剧', '德高望重的亚历山大（让·雷诺 Jean Reno 饰）多年来一直是米其林餐厅的三星主厨，但是近来他的境遇却屡现危机。当下的法国料理界正是”分子料理”风靡，传统料理日渐衰落的时代，亚历山大所坚持的传统料理很有可能会在即将到来的星级评审中落败，餐厅的小开更是翘首以盼可以就此炒了他。正当亚历山大焦头烂额之时，一名名不见经传的小厨师杰克（迈克尔·扬 Michaël Youn 饰）出现了，杰克是亚历山大食谱的忠实追随者，却因对料理的狂热固执屡次失业，只好在养老院找了份油漆工作。一个偶然的机会，亚历山大让杰克到他的餐厅实习，杰克与生俱来的料理天分和另辟蹊径的烹调创意令亚历山大大为赏识，很快成为其左右手。星级评审越来越近，两位传统烹饪大师的合作能否在挑剔的”分子料理”派面前力挽狂澜呢？©豆瓣', '让·雷诺', '丹尼尔·科恩', 7.1, 14231, 'tt1911553', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2183246453.jpg', 0.4, 4.1, 45.4, 38.9, 11.1, '0.160732,0.135627,-0.574813,0.464716,-0.232786,-0.285038,0.394971,0.598239,-0.626838,-0.291232,0.282531,0.935718,-0.126695,0.255443,0.485951,-0.221120,0.037076,-0.493245,-0.085209,-0.188855,-0.180897,-0.243565,-0.391537,-0.346638,-0.321428,-0.217526,0.489731,0.041951,-0.230337,0.228668,0.326704,0.251178,0.205948,0.424830,-0.297577,-0.321382,0.434020,-0.260081,-0.383440,0.110029,0.076184,-0.259802,-0.123612,0.199919,0.087200,0.316353,0.446596,0.019989,-0.245775,-0.101488,0.383250,-0.203344,-0.003877,0.005341,0.409787,0.070835,-0.133625,0.212705,-0.054823,0.036051,-0.204965,-0.044198,-1.080485,0.091676,0.118584,0.041494,-0.710347,0.345771,0.086581,-0.077185,0.028870,-0.357136,0.072651,0.293789,0.195609,0.474937,0.298838,0.263212,-0.421854,0.415501,0.547825,0.185024,-0.167244,0.215478,-0.162233,-0.383821,0.172116,-0.445755,-0.370789,-0.148136,0.289247,0.135219,0.172736,0.208802,-0.532278,0.056452,-0.306526,-0.286883,0.332947,-0.238290,-0.002520,-0.972368,0.133865,-0.303079,-0.310269,-0.013464,0.228335,-0.096383,0.922783,-0.802484,0.108043,0.360001,0.099084,-0.404739,0.773618,0.164303,-0.043421,-0.135298,-0.334107,0.099957,-0.005288,0.157166,-0.033946,0.510884,0.308862,-0.437213,-0.310206,0.448018', '1793491', '3318306', '27602116', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6731993', '远大前程', '剧情', '故事发生在十九世纪的英国，皮普（杰瑞米·艾文 Jeremy Irvine 饰）从小成长于贫苦家庭之中，看着他长大的是个性暴躁的姐姐和杰夫乔（杰森·弗莱明 Jason Flemyng 饰）。一次偶然中，皮普来到了一幢神秘的庄园之中，在那里住着的是他的雇主哈文森姆小姐（海伦娜·伯翰·卡特 Helena Bonham Carter 饰）和她的侄女艾斯黛拉（霍利·格林格 Holly Grainger 饰）。随着时间的推移，皮普深深的爱上了性格冷艳高贵的艾斯黛拉，深知自己配不上她的皮普在内心里燃起了想要跻身于上流社会的念头。一笔突然到来的神秘财产让皮普得以实现了他长久以来的愿望，他来到了伦敦，开始了自己的“变身计划”，而此时的他并不知道，本以为是时来运转，但自己不过只是棋盘上的一颗棋子而已。©豆瓣', '拉尔夫·费因斯', '迈克·内威尔', 6.8, 7782, 'tt1836808', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1785311870.jpg', 1.1, 8, 50.3, 31.5, 9.1, '0.404904,0.275227,-0.810952,0.753052,-0.300360,-0.330843,0.891090,0.065021,-0.712549,-0.127296,0.048237,0.908920,-0.168638,0.557808,0.326955,0.387546,-0.234978,-0.648353,-0.170616,-0.254604,-0.002923,-0.720037,-0.410594,-0.213617,-0.155704,-0.404804,0.543945,0.296496,-0.039616,0.331902,0.413404,0.395540,0.122015,0.331206,-0.294186,0.078238,0.046605,-0.146642,-0.040550,0.034582,0.224177,-0.421214,0.011700,0.394832,0.075585,0.304359,0.562935,-0.342618,-0.017650,-0.141680,0.277493,-0.211017,-0.008773,0.126093,0.140766,-0.047512,0.262887,0.136720,-0.279772,0.019612,0.115193,-0.276535,-0.555707,0.056970,0.111310,0.218483,-0.944027,0.472918,-0.195056,-0.277942,0.000519,-0.509700,0.252053,0.275601,0.207543,0.200687,-0.357992,0.040521,-0.578346,0.022544,0.669105,0.142867,-0.224425,0.492663,-0.412957,-0.450738,-0.195633,-0.234530,-0.516209,-0.102411,0.346947,0.112946,-0.085164,0.354405,-0.519091,0.017849,-0.257603,-0.169616,-0.134934,-0.572779,-0.316521,-0.140408,-0.433233,-0.715394,-0.359722,0.059170,-0.079380,-0.425787,0.691930,-1.006828,0.290857,0.321481,0.228694,-0.306859,0.607173,0.032993,0.089636,-0.059849,-0.009199,0.242559,-0.205849,0.097719,0.055509,0.394179,0.005602,-0.083329,-0.332562,0.852710', '3230121', '1783461', '20277433', '1895119');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6738701', '哆啦A梦：大雄与奇迹之岛', '动画', '炎炎夏日，为了找到所向披靡的独角仙，大雄（大原めぐみ 配音）痛哭流涕，对哆拉A梦（水田わさび 配音）软磨硬泡。无奈之下，哆拉A梦和哆拉美（千秋 配音）拿出时光圈，帮大雄在500年前的新西兰寻找独角仙，谁知却意外抓到了早已灭绝的恐鸟。为了不至于让恐鸟走向灭亡，他们决定将其送往奇迹之岛。奇迹之岛是由未来的科学家开发的专门用来收留、保护、研究灭绝动物的小岛，传说岛上有一只黄金独角仙，它可为当地的生物注入生命的力量。一波三折，大雄和小伙伴们来到了这里，并且结识了和大雄极其相像的神秘少年达凯（野沢雅子 配音）以及善良的洛科洛族。与此同时，一个黑心商人图谋抓住黄金独角仙……本片为哆拉A梦诞生前100年的纪念之作。©豆瓣', '水田山葵', '楠叶宏三', 7.3, 7814, 'tt2271315', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1452237295.jpg', 1, 5.6, 40, 32.7, 20.6, '-0.446807,0.141865,-0.362606,0.436744,0.134483,0.119773,0.433516,-0.016864,-0.229615,-0.373670,0.176775,0.693292,-0.052845,0.114345,0.186194,0.032307,0.143242,-0.381609,-0.206506,0.014916,-0.328338,-0.048366,-0.568891,-0.092280,-0.234958,-0.447441,0.654011,0.053704,-0.196739,0.403876,0.180462,0.469467,-0.420663,-0.054483,-0.500470,-0.086127,-0.063959,0.237067,-0.130908,0.140581,-0.432371,0.221843,0.005126,0.019388,0.063402,0.039705,0.708324,-0.648251,-0.183772,-0.452634,0.155542,-0.292712,-0.096852,-0.178496,0.305304,-0.052477,0.239196,0.073398,-0.137332,-0.266253,0.166004,-0.259389,-0.930827,-0.003359,0.023099,0.067529,-0.394199,0.142156,0.157977,0.235569,0.131482,-0.239529,0.199015,0.388354,0.440216,0.291253,0.028314,0.264795,-0.156496,0.120035,0.596698,-0.117618,-0.054235,0.484292,-0.104035,-0.464568,-0.031256,-0.248426,0.070796,-0.017375,0.318969,0.115986,-0.197294,0.315222,-0.801857,-0.361620,-0.363311,0.061977,0.242386,-0.311459,-0.376685,-0.193275,0.103173,-0.034330,-0.159002,0.043781,0.247185,-0.183122,0.874384,-0.648256,0.261914,0.495711,0.253380,-0.123322,0.725945,-0.477119,-0.149962,-0.376574,-0.111617,0.186909,0.195411,0.418363,0.016086,-0.009229,-0.182637,-0.248097,-0.710258,0.149210', '24284209', '1302661', '25928048', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6738712', '女孩', '剧情', '繁华喧嚣的大都会东京，四个年龄在三十岁上下的女性正经历着人生种种蜕变。武田圣子（麻生久美子 饰）刚刚荣升公司主管，干劲十足的她首先遭到男权意识极强的下属今井（要润 饰）的连番轻视与挑衅，在这一过程中她忽略了温柔持家的丈夫（上地雄辅 饰）的感受；马上要三十岁的泷川由纪子（香里奈 饰）心中满是童话般的幻想，酷爱小女孩服装的她被客户讥诮，而与男友（向井理 饰）的关系也似乎到了该慎重考虑的时刻；小坂容子（吉濑美智子 饰）肩负起培养新人和田慎太郎（林遣都 饰）的职责，可她却不自觉地对这个小自己一轮的帅男孩动了心；单身妈妈平井孝子（板谷由夏 饰）与出轨的丈夫果断离婚，即使生活再艰辛，也咬牙扮演起身为父母的双重角色。女子本就生活不易，她们又如何能在这时代的洪流中找到前进的方向呢……©豆瓣', '香里奈', '深川荣洋', 7.2, 7447, 'tt1975169', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1338762473.jpg', 0.7, 4.6, 42.3, 40.6, 11.8, '-0.016013,0.148068,-0.515421,0.529191,-0.237648,-0.359307,0.565156,0.274374,-0.378982,-0.264496,0.213538,0.622553,-0.138179,0.240653,0.337541,0.107650,-0.148849,-0.616036,-0.142534,0.130744,-0.112579,-0.216706,-0.064142,-0.161883,-0.205026,-0.125873,0.666048,0.050109,-0.132515,0.242443,0.484185,0.247007,-0.007349,0.325732,-0.087673,0.050811,0.042186,0.136375,-0.149445,0.073760,-0.090763,-0.320244,-0.176727,0.129514,-0.062559,0.366695,0.627392,-0.140147,-0.188311,-0.188329,0.440385,-0.001685,-0.085109,0.311103,0.269591,0.031694,0.125675,0.131302,-0.169436,-0.126044,0.217693,-0.216405,-0.568270,-0.129801,0.142190,0.096897,-0.429630,0.368720,-0.065842,-0.185910,0.384318,-0.161747,-0.071481,0.238132,0.210674,0.276069,-0.472507,0.076304,-0.222824,0.263519,0.425767,0.306778,-0.186266,0.271599,-0.398520,-0.569754,-0.303689,-0.222937,-0.608796,-0.242704,0.070185,0.205725,-0.189097,0.138077,-0.384338,0.062045,0.026197,0.065811,0.051655,-0.425015,0.025533,-0.432993,-0.118456,-0.846812,-0.417248,0.213816,0.246879,-0.154727,0.702864,-0.751471,-0.008291,0.414880,0.211929,-0.458615,0.518930,0.221624,0.034015,-0.390725,-0.065267,0.306029,-0.175276,0.218233,0.075636,0.423451,-0.181570,0.007045,-0.295499,0.503590', '26354526', '1309161', '25924935', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6738735', '大追捕', '剧情', '二十年前因奸杀少女依芸入狱，重犯王远阳（张家辉 饰）在狱中历经凌辱，变成性格怪异、人见人惧的哑巴杀手。刚刚出狱的他，又卷入了一场惨绝人寰的命案之中：中英混血指挥家徐翰林被发现抛尸海边荒野，容貌尽毁遍体鳞伤，而徐翰林正是少女依芸的父亲。外号怒汉的警探林正忠（任达华 饰）一心查出真相，出狱后一直跟踪徐翰林幼女徐雪（文咏珊 饰）的王远阳，自然成为最大的嫌疑人，一场全港大追捕全面展开，然而，真相才刚刚开始被揭开……©豆瓣', '张家辉', '周显扬', 7.3, 83540, 'tt2171993', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1451250805.jpg', 0.6, 4.6, 37.6, 42.2, 15.1, '-0.068107,-0.026885,-0.444211,0.223307,-0.108630,-0.276150,0.702968,-0.240605,-0.670606,-0.541150,0.172356,0.426785,-0.514183,0.380434,0.411510,-0.074902,0.060620,-0.712324,-0.335702,-0.281579,-0.306608,-0.377607,-0.134903,-0.049500,0.028989,0.087807,0.518381,0.232586,-0.138826,0.323775,0.702398,0.356075,-0.400444,0.271574,0.141956,0.260513,0.090701,-0.083988,-0.288526,-0.072160,0.030381,-0.857389,0.035566,-0.020879,-0.286332,0.261639,0.715355,-0.384280,-0.170430,-0.615943,0.499125,-0.452031,-0.345097,0.205771,0.675473,0.176781,0.225694,0.247153,-0.156738,-0.070222,0.033205,-0.092259,-0.125850,0.157259,0.407735,0.100931,-0.031419,0.177235,0.044713,0.164699,-0.073524,-0.013956,0.212583,0.111026,0.397095,0.239700,-0.080597,0.022709,-0.450205,0.509525,0.590711,-0.094296,-0.076333,0.045533,0.218633,-0.505744,0.270041,-0.616436,-0.254819,0.291576,0.287577,-0.074944,-0.237993,0.383259,-0.081374,-0.286125,-0.583325,0.334505,-0.338356,0.016842,-0.296465,-0.264811,-0.333694,-0.360698,-0.055190,0.150031,-0.132020,-0.401802,0.209870,-0.429553,0.303535,0.129462,0.081510,-0.290186,0.018435,-0.087597,0.361492,-0.042062,-0.083040,0.444361,0.540247,0.161645,0.064606,0.012507,-0.358456,-0.286665,-0.097038,0.094772', '1773217', '30219670', '2364838', '26835911');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6738760', '倾城之泪', '剧情', '第一滴泪：罹患骨癌的美丽少女给力妹（周冬雨 饰）不曾被病魔吓倒，她以乐观的精神感染着医院内每一个病人。在她的感召下，本该阴郁忧伤的医院犹如人间天堂。这天，身患脑癌的富二代游乐（李治廷 饰）入住医院，他绝望愤怒的情绪很快就被给力妹及小朋友的笑容所消解，医院成为他们人生最后 的快乐驿站；第二滴泪：培育过无数人才的信义音乐学院面临破产，为了挽救学校，同时了却亡妻的心愿，陈校长决定召集毕业的学生回校召开一场音乐会。曾与同学——现今蜚声国际的小提琴演奏家杨琳（梁咏琪 饰）谈过恋爱的丁大可（任贤齐 饰）奉命邀请杨琳出席；第三滴泪：底层小青年陈升（窦骁 饰）经过艰苦打拼，终于在事业上有所成就。当他准备迎娶苦恋多年的女友小彩（陈乔恩 饰）之时，一场意外突然发生。©豆瓣', '周冬雨', '黄真真', 4.9, 54722, 'tt2170573', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1319547030.jpg', 17.5, 34.3, 35.9, 9.1, 3.2, '0.005848,0.005956,-0.534327,0.285669,0.016813,-0.350985,0.576019,0.112563,-0.394203,-0.302159,0.087115,0.414880,-0.432804,0.822352,0.304759,-0.165339,-0.147356,-0.604836,-0.189384,-0.001057,-0.108853,-0.024273,-0.143208,0.091472,0.047617,-0.113987,0.537798,0.243095,-0.007886,0.657418,0.300018,0.269680,-0.027759,0.406497,0.038918,-0.091452,0.131027,0.334453,-0.292838,-0.036162,0.175857,-0.409530,-0.085579,0.028044,0.016992,0.233052,0.565335,0.059788,-0.012945,-0.084678,0.452315,-0.184397,0.002423,0.034854,0.337896,0.144485,0.227464,0.159663,-0.114341,-0.134193,0.058034,-0.362566,-0.652940,-0.053297,0.272885,0.050031,-0.471009,0.486254,-0.110064,0.120030,0.100046,-0.273538,0.089310,0.286877,0.286142,0.520862,-0.398019,0.174223,-0.255511,0.594798,0.717371,-0.144977,-0.278783,0.205065,-0.290002,-0.462590,0.311309,-0.242025,-0.376724,0.242274,0.240736,0.037887,-0.026449,0.173754,-0.282403,-0.296232,-0.426693,-0.139116,0.038787,-0.133135,0.004535,-0.599841,0.064467,-0.120771,-0.249137,0.022968,0.303049,-0.140979,0.611187,-0.783209,0.337992,0.176381,0.042837,-0.474725,0.507142,0.078203,0.193946,-0.121025,0.056229,0.300447,-0.160388,0.414894,-0.023141,0.314519,-0.341267,0.104471,-0.286693,0.328494', '26687241', '1306544', '25922902', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6745433', '一件幸福的事', '剧情', '和大部分女大学生一样，芭芭拉（露易丝·布尔昆 Louise Bourgoin 饰）有着年轻美丽的外表和对未来无限的期望，和男友尼古拉斯（皮奥·马麦 Pio Marmaï 饰）的恋情更让她相信她正在经历的是一生中最美好的时光。一个孩子的到来将一切美好粉碎殆尽，她无法想象在心智上还是一个孩子的自己竟然要做母亲了。在犹豫和期待中，芭芭拉选择了将孩子留下，没想到，孩子的出生则成为了芭芭拉的另一个噩梦。面对眼前这个毫无防备的小小生命，在为人母的艰巨责任面前，芭芭拉退却了，她怎么也弄不明白的是，成为母亲，这明明是一件幸福的事情，为什么会有那么多的悲伤和恐惧深藏其中呢？©豆瓣', '露易丝·布尔昆', '雷米·贝占松', 7.9, 8259, 'tt1987018', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1389854620.jpg', 0.4, 1.5, 24.3, 51.3, 22.6, '0.085364,0.061502,-0.903511,0.541846,-0.573262,-0.228506,1.094599,-0.183448,-0.524301,-0.415962,0.064546,0.986320,-0.143234,0.344303,0.016641,0.144780,-0.254778,-0.704105,-0.301285,-0.086538,-0.389205,-0.513553,-0.302863,0.107079,-0.033415,-0.222413,0.838233,0.186634,0.113060,0.264333,0.582404,0.264221,0.074054,0.616722,-0.272119,0.027758,0.006693,0.151367,-0.137252,0.070475,0.155464,-0.114518,0.100639,0.450051,-0.356402,0.143201,0.653025,-0.282886,-0.264342,-0.162924,0.468786,-0.500712,0.020043,0.298820,-0.045061,-0.140489,0.143521,0.040827,-0.284097,-0.264273,0.302157,-0.044632,-1.259291,-0.037783,0.318280,0.368978,-0.830331,0.402359,0.076995,-0.196519,0.460374,-0.352992,0.206938,0.253106,0.348170,0.682459,-0.445441,-0.012714,-0.553275,-0.002430,0.770181,-0.060140,-0.293439,0.579628,-0.411262,-0.246047,0.053676,-0.289643,-0.712553,0.195017,-0.082022,0.282284,-0.132388,0.562449,-0.310344,0.057832,-0.307546,-0.096775,-0.026910,-0.861482,-0.276395,-0.003377,-0.086010,-0.616561,-0.730133,0.000133,0.221725,-0.541220,1.103506,-0.868937,0.206900,0.412078,0.479184,-0.480399,0.746194,0.426077,0.153369,-0.194744,0.221680,0.385369,-0.159635,-0.186703,0.060202,0.342393,-0.054390,0.055199,-0.449029,0.780268', '30163500', '3318473', '34875369', '4847665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6753091', '冰封之地', '剧情', '20世纪80年代初，站街流莺辛蒂（瓦妮莎·哈金斯 Vanessa Hudgens 饰）险些遭人杀害。与此同时，在阿拉斯加一处荒凉所在，一名女性尸体被人发现。警官杰克·海尔康伯（尼古拉斯·凯奇 Nicolas Cage 饰）从辛蒂处了解到，凶手手段残暴无情，并且可能是个连环杀手。由于背负着不堪回首的过去，杰克一方面决定保护这个侥幸从死神手中逃脱的女孩，另一方面将目标锁定在曾在70年代有过前科的男子罗伯特·汉森（约翰·库萨克 John Cusack 饰）身上。罗伯特道貌岸然，不动声色继续着他的猎杀活动，当他意外再度出现在辛蒂面前时，正邪双方的对决即将到了关键时刻……本片根据真实事件改编。©豆瓣', '尼古拉斯·凯奇', '斯科特·沃克', 6.3, 10799, 'tt2005374', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1993280846.jpg', 1.7, 12.3, 59.7, 21.8, 4.5, '0.376043,-0.040544,-0.660426,0.230807,-0.053107,-0.061313,0.651273,-0.158384,-0.537810,-0.277929,0.753187,0.621059,-0.181806,-0.007950,0.550234,-0.104166,-0.225975,-0.538267,-0.057363,-0.281843,-0.480643,-0.476952,-0.512533,-0.205220,-0.116308,-0.532910,0.549472,-0.036387,-0.319364,0.543609,0.396175,0.564645,-0.490084,0.366730,-0.114100,0.050841,0.276999,-0.421066,-0.365382,0.318011,-0.114546,-0.371335,-0.276659,0.235385,-0.138039,0.443819,0.733399,-0.457150,-0.083201,0.116624,0.299666,-0.064896,-0.059295,0.223140,0.480911,-0.199956,0.055114,0.309829,-0.050303,-0.080061,0.107494,-0.184379,-0.491753,0.093585,0.000683,0.374171,-0.537611,0.288325,-0.280658,0.158058,0.102364,-0.332367,0.146973,0.029939,0.383723,0.088978,-0.037666,-0.088833,-0.359300,-0.000635,0.560745,0.099622,-0.212633,0.176494,0.024912,-0.204800,-0.436766,-0.167334,-0.330258,-0.032637,0.620629,0.007325,-0.346940,0.336001,-0.449449,-0.222952,-0.299655,0.180287,-0.016397,-0.072091,-0.462042,-0.329775,-0.238085,-0.129355,-0.168070,0.105783,-0.318763,-0.357824,0.479354,-0.889432,0.340953,0.684176,0.205146,-0.010331,0.355690,-0.162754,0.068955,-0.243695,-0.319843,0.459805,0.489281,0.137906,0.041040,0.325201,-0.232473,-0.252792,-0.218592,0.361879', '35030151', '1292829', '1436998', '1438591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6753096', '床下有人', '悬疑', '多年前发生在云南的一场大火，让冰儿（何可人 饰）失去了恋人小明（葛红霖 饰），自此她不仅深陷痛失爱人的痛苦中无法自拔，甚至经常梦见在一间纯白的房间内，床下伸出一双惨白的手抓她。在和英俊的况宇（郭晓然 饰）结婚后，冰儿的情况已久没有好转。某天，夫妻俩来到某古城旅游，这曾是小明许诺带冰儿来的地方。令人难以置信的是，小明并没有死去，他全身烧成重伤，不愿出现在冰儿的面前，而独自隐居于此，并嘱托况宇照顾爱人。夫妻俩下榻在由百年古宅改造的春秋客栈，可是每到夜晚，各种恐怖阴冷的事件就开始发生，惨白的女鬼从床下爬出，搅扰着生者与死者的神经……©豆瓣', '何可人', '牛朝阳', 2.9, 6838, 'tt2095602', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1230923975.jpg', 72.3, 17.3, 6.7, 1.3, 2.4, '0.185243,0.001537,-0.929151,0.205140,0.071891,-0.154210,1.060207,0.105089,-0.509557,-0.257636,0.328069,0.588464,-0.278333,0.661779,0.224539,0.101743,0.042269,-0.861159,-0.304098,-0.092393,-0.402627,-0.294015,-0.344749,-0.096792,0.067032,-0.397645,0.499672,0.234625,-0.005785,0.597539,0.208513,0.174032,-0.327759,0.531417,-0.292711,-0.059454,-0.211768,0.355605,-0.251986,0.117199,0.052466,-0.415477,-0.223452,0.014372,-0.026034,0.238612,0.587521,-0.284959,-0.517354,-0.051102,0.355571,-0.173284,-0.190453,0.146271,0.337384,-0.042630,0.320807,0.222483,-0.288330,-0.023157,0.269050,0.013616,-0.531951,0.243172,0.176103,0.362064,-0.537955,0.539271,-0.111697,-0.055483,0.056580,-0.435666,0.346786,0.337530,-0.024713,0.414835,-0.197734,0.143418,-0.398324,0.186444,0.588107,0.049639,-0.117604,0.190503,-0.139202,-0.194358,0.107622,0.007887,-0.334648,-0.060241,0.206800,0.129842,-0.462840,0.243406,-0.414509,0.083261,-0.313557,-0.208112,-0.038597,0.044729,-0.400659,-0.355622,-0.218397,-0.383418,-0.237003,0.277766,-0.084368,-0.261514,0.170588,-0.691597,0.556749,0.174397,0.131621,-0.200098,0.553345,-0.038056,0.103132,0.198392,-0.076950,0.404956,-0.198315,0.507305,0.293057,0.163360,-0.191881,0.466661,-0.705005,0.391924', '21348112', '1292211', '26342391', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6753166', '七个神经病', '喜剧', 'Marty（柯林·法瑞尔 Colin Farrell 饰）是一个爱喝酒的电影编剧，他的好友Billy（山姆·洛克威尔 Sam Rockwell 饰）则和Hans（克里斯托弗·沃肯 Christopher Walken饰）靠偷狗然后把狗还回给失主来赚钱。Marty近期在写 一个叫《七个神经病》的剧本，却没有什么灵感，于是Billy给他提供了一些素材。有一个神经病是一个杀手，每次杀完人都会扔下一张J扑克牌，有一个越南的复仇者，有一个自刎的贵格教徒....Billy偷了一条狗，这条狗是一个黑帮老大Charlie（伍迪·哈里森 Woody Harrelson 饰）的爱犬。Charlie丢了他视如生命的狗，到处在寻找。他找到了Hans住院的妻子并杀害了她。Billy知道这件事后，愤怒的将他的情人杀害，而她也是Charlie的情人，随后Billy扔下了一张扑克牌。原来Billy就是那个神经病杀手。他和Marty、Hans来到野外继续写剧本，同时他也让Charlie单枪匹马前来决斗.....', '科林·法瑞尔', '马丁·麦克唐纳', 7.7, 76034, 'tt1931533', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1748021684.jpg', 0.8, 3.5, 27, 46.9, 21.8, '0.323519,-0.367860,-0.321368,0.797565,-0.469611,-0.465178,0.906326,-0.019539,-0.111338,0.045378,0.227724,1.091283,0.013053,0.143245,-0.074675,0.201213,-0.101488,-0.636934,-0.034631,-0.143757,-0.193511,-0.387191,-0.413187,-0.129155,0.084826,0.042436,0.230220,-0.288092,-0.169306,0.318093,0.513869,0.173564,0.047723,0.328374,-0.347664,0.328835,-0.115353,-0.221633,0.360806,0.353206,0.104386,-0.133610,0.051262,0.215311,-0.141160,0.534806,0.562679,-0.276436,-0.155447,-0.132602,0.408627,-0.500411,-0.167547,0.073717,0.155460,-0.295291,0.131190,-0.039288,-0.163961,0.114042,0.268234,0.064359,-0.997239,-0.210287,-0.220354,0.365401,-0.706905,0.513799,-0.284692,0.091071,0.162911,-0.320023,0.430361,0.140696,0.052230,0.242049,0.014208,-0.035875,-0.747507,0.406765,0.404226,-0.066580,0.284729,0.420254,-0.014368,-0.211357,0.110306,-0.033692,-0.369410,-0.075164,0.730235,-0.452281,-0.439382,-0.400526,-0.756462,-0.116858,-0.062995,-0.105961,-0.053613,-0.551277,-0.118325,-0.312781,0.218190,-0.145414,-0.110930,0.090176,0.130029,-0.231327,0.638217,-0.465313,0.108147,0.860582,0.075603,-0.571215,0.665176,0.142779,-0.135833,0.187931,0.125867,-0.077948,0.764934,0.555085,0.240615,0