INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6753589', '理查二世', '剧情', 'BBC2历史电视电影系列《空王冠》演绎4部经典莎士比亚作品。这部电视电影作为伦敦文化奥运的重点推荐剧目在2012年6月播出向全世界推行。本剧是《空心冠》的第一集。理查二世（本·卫肖 Ben Whishaw 饰）虽是英格兰国王，但实权被叔父兰开斯特公爵约翰·冈特把持。另一个叔父格洛斯特公爵托马斯也野心勃勃，企图摄政。理查由此而记恨亲政后对他们进行报复。1397年，托马斯被捕后未及受审就暴死在狱中，公爵头衔被废除。理查驱逐了约翰的长子毛勃莱公爵、以及自己的堂弟兰开斯特公爵亨利（罗里·金奈尔 Rory Kinnear 饰），并在1399年约翰去世后没收了兰开斯特家的领地，用没收的钱财充当攻打爱尔兰的军费。亨利以此作为攻打理查的藉口。1399年，在理查远征爱尔兰时举兵拘捕了他，并让国会同意将他废黜，由亨利即位。理查在监牢中囚禁多年，最终被杀害。©豆瓣', '本·卫肖', '鲁伯特·古尔德', 8.8, 15543, 'tt1978517', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2096736876.jpg', 0.2, 0.8, 10.2, 38.2, 50.6, '-0.142983,0.232012,-0.472434,0.562163,0.113162,-0.223224,0.454852,0.333050,-0.526806,-0.356409,0.115530,0.812933,-0.206297,0.058715,0.493168,0.179291,-0.483547,-0.723475,0.081529,-0.254480,0.092995,-0.521369,-0.157958,-0.506756,-0.133494,-0.599332,0.685424,0.059971,-0.007606,0.161595,0.236412,0.387484,0.336056,0.212031,0.067690,0.230838,0.268623,-0.284873,-0.145020,0.476469,-0.156427,-0.460192,-0.121705,0.068642,0.197885,0.477471,0.350549,-0.505478,0.337004,-0.238130,0.372349,-0.276791,-0.145800,0.174875,0.468406,0.053204,-0.086749,0.825344,-0.088251,-0.239159,-0.046493,-0.335400,-0.542215,0.006275,-0.141337,0.048539,-0.584543,0.698452,-0.574477,0.214074,-0.158796,-0.157948,0.201944,0.371038,0.179861,0.316593,-0.065223,0.221654,-0.425361,0.517510,0.235385,-0.154324,-0.302041,-0.166207,-0.025604,-0.393491,0.110029,-0.436718,-0.267777,-0.033195,0.408275,-0.216091,0.249709,0.458812,-0.289486,-0.336878,-0.622728,-0.280996,0.532031,-0.293408,-0.000693,-0.672660,-0.049960,-0.143146,0.050696,-0.373697,0.267537,-0.072072,0.479482,-0.378131,0.258640,0.424090,0.406324,-0.576883,0.661339,0.136826,0.035120,0.077013,-0.134792,0.243379,0.388671,0.099604,0.146470,0.033184,0.264236,-0.516015,-0.103340,0.413362', '26990609', '10543907', '3292949', '10543906');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6755346', '妙笔生花', '剧情', '本片是《创：战纪》两位编剧布莱恩·克鲁格曼和李·斯特恩斯奥的导演处女作。罗里（布莱德利·库珀 Bradley Cooper 饰）虽然一直在努力写作，却从未得到出版社的青睐，时不时还要靠父亲的接济度日。和新婚妻子多拉（佐伊·索尔达娜 Zoe Saldana 饰）去巴黎度 蜜月时在二手店买了一个书稿包。罗里偶然发现了里面的一份旧小说手稿，内容深深吸引了他。最后他把小说占为己有并出版，终于让他一举成名，成为文学界的新锐。而一个神秘的老人（杰瑞米·艾恩斯 Jeremy Irons 饰）突然出现，告诉罗里自己才是小说的作者，并给他讲述了一个小说中发生在巴黎的真实爱情故事。面对这一切，罗里有了无法逃遁的负罪感。他会把成功当做理所当然，还是一场道德考验？©豆瓣', '布莱德利·库珀', '布赖恩·克卢格曼', 7.6, 26702, 'tt1840417', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1615388794.jpg', 0.4, 2.6, 31.7, 49.1, 16.3, '0.145409,-0.097290,-0.339274,0.857068,0.082593,-0.213746,0.706188,-0.016743,-0.274051,-0.470689,0.006941,0.874756,-0.211576,0.312845,0.184283,0.133661,-0.513648,-0.716289,0.090143,-0.207587,-0.185744,-0.559735,-0.366457,-0.064184,-0.106905,-0.151038,0.441195,0.155081,-0.400588,0.243033,0.481844,0.218266,0.060495,0.534832,-0.266928,0.307813,0.091489,-0.006650,-0.033629,0.348197,0.356895,-0.418565,-0.232498,0.268953,0.078974,0.195694,0.460748,-0.356295,-0.295432,0.303045,0.603882,-0.153348,0.026635,-0.051472,-0.095905,-0.072241,0.250660,0.113250,-0.244291,0.209267,0.077647,-0.221085,-0.842517,-0.151435,0.078875,0.351774,-0.579489,0.305094,-0.171145,0.125012,0.055593,-0.302444,0.118829,0.046934,0.529523,0.289459,-0.081556,0.063441,-0.335045,0.553309,0.211412,0.085940,-0.173409,0.490284,-0.108846,-0.306030,0.037429,0.002640,-0.615560,0.258287,0.398387,0.043483,-0.064707,0.230754,-0.587601,-0.170738,-0.130560,-0.412867,0.034707,-0.515290,-0.018465,-0.495836,-0.320443,-0.149200,-0.084447,-0.110498,0.101102,-0.467049,0.920840,-0.378111,0.346883,0.636207,0.169295,-0.328362,0.651535,0.068810,0.005627,0.074935,-0.001173,0.188136,0.130311,0.345752,0.221721,0.448246,0.373025,-0.185619,-0.325065,0.803677', '27602116', '4267948', '1870681', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6757776', '文科恋曲', '剧情', '已过而立之年的杰西（乔什·拉德诺 Josh Radnor 饰）厌倦了乏味单调的工作，他总是怀念着以往的大学生活，曾经的食堂和寝室、聚会和诗会常常浮现在他脑海。这天，他突然接到大学时代最喜欢的彼得教授（理查·詹金斯 Richard Jenkins 饰）的邀请，希望他能在自己的退休晚宴上做个演讲，杰西简直迫不及待地前去赴约。令人意想不到的是，在晚宴上他遇到了一位19岁的女学生吉比（伊丽莎白·奥尔森 Elizabeth Olsen 饰），吉比非常喜欢他的演讲，在交谈中，两人竟发现对方在文学、艺术上的爱好几乎一模一样，彼此渐渐互生情愫。然而，现实的年龄差距却似乎总是阻隔在两人之间的藩篱……©豆瓣', '乔什·拉德诺', '乔什·拉德诺', 7.4, 20813, 'tt1872818', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1743137427.jpg', 0.6, 3.9, 36.1, 44.3, 15, '0.733844,0.075225,-0.806833,0.587009,-0.000209,-0.334928,0.811692,0.260774,-0.506111,-0.363054,0.230042,0.867914,-0.531317,0.508210,0.399505,-0.239737,-0.245819,-0.802643,0.103573,-0.236660,-0.112479,-0.521876,-0.110222,-0.036306,-0.028994,-0.391932,0.446042,-0.042606,-0.034626,0.805297,0.198242,0.204888,0.165102,0.705408,-0.363170,-0.230962,0.239111,0.298445,-0.129905,-0.230953,-0.021483,-0.181333,-0.296871,0.079769,0.050437,0.311634,0.689021,-0.101307,-0.265023,0.331799,0.566966,-0.013989,-0.033385,0.158981,0.304838,0.014699,0.202752,0.134212,0.042389,0.049035,-0.152353,-0.203663,-0.407635,0.098634,-0.022286,0.331851,-0.472752,0.567398,0.081509,-0.007769,0.073428,-0.382722,-0.007638,0.290327,0.091068,0.495505,0.011195,0.030676,-0.433993,0.210570,0.702987,0.185410,-0.334179,0.441999,-0.605644,-0.359912,-0.205352,-0.123355,-0.628200,-0.138052,0.147315,-0.278003,-0.254544,0.172602,-0.618005,0.011420,0.175954,-0.046408,0.098323,-0.343631,-0.201255,-0.803292,-0.257702,-0.642171,-0.559287,-0.072683,0.102087,-0.238473,0.710216,-1.072277,0.289095,0.602655,0.143709,-0.015527,0.955837,0.347194,-0.172483,-0.353712,-0.240568,0.270062,-0.199282,0.104156,-0.089726,0.686909,-0.012201,0.026536,-0.760822,0.873816', '1309172', '1915403', '26687241', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6759229', '新天生一对', '剧情', '阿B（周渝民 饰）是一个失意摩托车手。6年前，他因为比赛失误从此一蹶不振，连妻子方家蔚（杨幂 饰）也弃他而去。阿B拼命寻觅，毫无头绪，张贴警告逃妻告示，也没有结果。他意志消沉，借酒消愁，嗜赌成性，遭到荔父和女儿（徐若瑄 饰）指摘。幸有好友马妞（陈嘉桦 饰）为他洗衣做饭。养父雷叔（陶泽如 饰）多次劝他付出，他却心灰意懒。这时，妻子突然出现，还给阿B领来了一个6岁的儿子彬彬（小小彬 饰）。她说有事要办，所以托付他照顾，但是并没有告诉孩子阿B是他爸爸。面对昔日赌徒追讨高利贷，昔日对手尊尼（陈楚生 饰）力邀他付出的诚意，他无动于衷。但是，与彬彬相依相伴的父子情，却慢慢治愈了他的伤痛。然而，此时妻子却突然要带孩子移民美国，这让阿B措手不及……©豆瓣', '周渝民', '朱延平', 6.3, 43495, 'tt2137992', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1358024172.jpg', 3.3, 14.4, 52, 23, 7.2, '-0.278061,0.066203,-0.583802,0.282473,-0.124914,-0.469795,0.786462,0.237257,-0.182230,-0.291689,0.087869,0.450197,0.290813,0.018875,-0.205424,0.029283,-0.148665,-0.676871,0.289539,0.062500,-0.115661,-0.129522,0.163269,-0.211171,-0.234862,0.009632,0.346026,-0.069893,-0.057197,0.583564,0.430468,0.102048,0.198255,0.734596,0.018924,0.196208,-0.147042,0.244926,-0.128912,0.065858,0.277665,-0.229078,-0.223988,0.236933,0.087841,0.613186,0.577749,0.005144,-0.097696,-0.233303,0.168596,-0.245098,0.006052,-0.019274,-0.132491,-0.100830,0.172731,-0.092147,-0.070200,-0.410180,0.176496,-0.013662,-0.466811,-0.020538,0.104402,0.080168,-0.633987,0.211982,-0.423264,0.186273,0.026935,-0.297303,0.173360,0.098295,0.222303,0.144419,-0.246650,0.087050,-0.396561,0.398776,0.594927,-0.070629,0.250566,0.241337,-0.422626,-0.365266,0.386241,-0.318077,-0.718665,0.121351,0.015784,-0.133007,-0.032516,0.109229,-0.009664,-0.150407,-0.219767,0.285884,-0.217144,-0.598343,0.309052,0.041759,-0.217070,-0.152740,-0.338223,0.176170,0.012146,-0.260636,0.460254,-0.458120,0.305379,0.411491,0.711445,-0.623750,0.784776,0.338675,-0.147764,-0.293280,0.217439,0.322167,-0.041845,-0.094199,0.268252,-0.126996,0.340227,0.134814,-0.100366,0.272451', '10355329', '1857175', '1296370', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6768838', '上帝保佑美国', '喜剧', '中年男子弗兰克（乔尔·默里 Joel Murray 饰）对聒噪的世界深感麻木，他的生活如同一潭死水，每天浑噩度日。他对自私邻居的侵扰忍辱退让，对前妻再婚和女儿叛逆感到无奈，对不知廉耻的电视真人秀选手反感厌恶。终于被诊断出脑瘤和丢掉工作的现实把弗兰克彻底击垮。正当他想以自杀了结此生时，真人秀里贪得无厌的选秀女孩激发出了他潜藏已久的憎恨，他决定以自己的方式让正义得到伸张。于是弗兰克出门杀死了他自认为该死的邻家女孩克洛伊，这一幕被另一个女孩洛克西（塔拉·林内·巴尔 Tara Lynne Barr 饰）目睹。洛克西同样厌恶着充斥弊病的社会，她主动参与到弗兰克的杀人计划。两人携带枪支走上大街，大张旗鼓的玩起杀人游戏，成为新闻追踪的焦点……©豆瓣', '乔尔·默里', '博卡·格德斯维特', 7.8, 41573, 'tt1912398', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1583261609.jpg', 1.1, 4.1, 24.9, 43.2, 26.6, '0.215680,0.078710,-0.615235,0.351919,-0.340508,-0.160374,0.719805,-0.029545,-0.415256,0.013903,0.271930,0.726734,-0.314175,0.114567,0.425822,-0.084713,-0.110798,-0.697874,-0.180717,0.007509,0.141610,-0.354280,-0.178011,-0.440434,-0.101313,-0.251921,0.549383,0.162874,-0.292329,0.384847,0.384568,0.443160,0.009840,0.554852,0.072054,-0.037661,-0.162970,-0.133908,-0.286866,-0.035535,0.206728,-0.017554,-0.144197,0.363829,-0.191247,0.267723,0.633079,-0.358743,-0.162906,-0.166958,0.580634,-0.397642,-0.168256,0.351540,-0.102716,0.059107,-0.143619,0.118834,-0.150311,-0.060939,0.171894,0.061100,-0.689600,-0.000370,-0.129148,0.029930,-0.485317,0.347696,-0.182409,-0.032639,0.228065,-0.234067,0.064275,-0.052278,0.391278,0.459878,-0.178452,-0.083681,-0.362476,0.156697,0.567798,-0.053769,-0.309680,0.043334,-0.420433,-0.155421,0.100144,-0.506709,-0.487990,-0.302451,0.328221,-0.202084,-0.310825,0.366221,-0.342752,-0.180610,-0.076218,-0.209034,0.116963,-0.437046,-0.173883,-0.425304,-0.127025,-0.037030,-0.340561,-0.100280,-0.027336,-0.445552,0.470055,-0.812733,0.218448,0.619344,0.402015,-0.554776,0.566868,0.070432,-0.026233,-0.228759,-0.203714,0.528836,0.121530,0.272727,0.190413,0.221757,-0.090737,0.099011,-0.284343,0.558197', '1301022', '1308755', '1299628', '25763555');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6771529', '突袭', '动作', '《突袭》是由加雷斯·埃文斯执导，由美国和印度尼西亚联合制作，于2012年3月23日在印尼上映。清晨特警Rama（伊科·乌艾斯 Iko Uwais 饰）做完祷告和训练，告别还没有起床的妻子去迎接一项特殊的任务。在雅加达的贫民窟的深处，世界上最危险的杀手和黑帮集结在一个坚不可摧的房子内。到现在为止，破旧的公寓甚至被神勇的警察也视为无法接近的。在黎明前黑暗和寂静的掩护下，一组身兼重要任务精英特警队与执法人员慢慢接近了房子，以便接近臭名昭著的毒枭。但他们袭击的消息被毒枭偶然发现，接着建筑物的灯光被切断，所有的通道被堵。这群特警必须要在世界上最残酷的环境下为生存展开搏斗......©豆瓣', '伊科·乌艾斯', '加雷斯·埃文斯', 7.8, 79805, 'tt1899353', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1505761616.jpg', 0.8, 3, 24.6, 47.7, 23.9, '0.382380,-0.142651,-0.853621,0.609654,-0.074770,-0.049202,0.691083,-0.004630,-0.378545,-0.201113,0.362801,0.629439,0.031216,-0.093318,0.253272,-0.265041,-0.307669,-0.725089,-0.401762,-0.300470,-0.618712,-0.530734,-0.295411,-0.359958,0.096485,-0.400025,0.710009,0.401369,-0.185938,0.171232,0.204934,0.209122,-0.262120,0.430888,-0.322762,-0.387531,0.300041,-0.230232,-0.438256,0.390464,-0.395001,-0.407761,-0.066290,0.145569,0.066644,0.375527,0.773588,-0.324556,-0.117322,-0.035904,0.201127,-0.444532,-0.222291,0.172876,0.572336,-0.034811,0.180038,0.235865,-0.176510,0.002319,-0.252103,-0.248971,-0.947612,0.011634,0.233375,-0.138116,-0.677278,0.482343,-0.086871,0.014824,0.195287,-0.545335,0.479903,0.393661,0.044309,0.655608,-0.007821,0.091299,-0.639483,0.042719,0.750105,-0.188609,-0.169254,0.102981,-0.005480,-0.505597,-0.070101,-0.376196,-0.249809,-0.139290,0.343824,-0.011541,-0.199764,-0.060108,-0.867725,0.126366,-0.160264,-0.687116,-0.125016,-0.445408,-0.270180,-0.810575,0.029715,-0.265543,-0.112259,0.549272,0.150772,-0.078958,0.621250,-0.902058,0.332271,0.608987,0.376273,-0.351234,0.720329,0.011080,0.296037,-0.076187,-0.021073,0.106020,0.288270,0.740270,0.252127,0.431383,-0.339454,-0.235851,-0.628220,0.263118', '11810348', '2032339', '1793491', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6772963', '萤之光 电影版', '喜剧', '历经无数考验与磨难，几经波澜，“傻宫”雨宫萤（绫濑遥 饰）终于和她最爱的百分百部长高野诚一（藤木直人 饰）修成正果，结为夫妇。新婚不久，夫妻二人相约前往罗马蜜月旅行。可是傻宫的干物女能量大爆发，从夏天到冬天，二人的旅行始终没有实现。借着部长去罗马公干的机缘，傻宫终于踏出家门，和部长来到了这个因《罗马假日》而为所有情侣所向往的浪漫胜地。在这里，他们还结识了超级干物女冴木莉央（松雪泰子 饰）和她的弟弟小优（手越祐也 饰）。与此同时，针对日本商务人士的绑架案相继发生，而部长也在某天意外失踪。异国他乡，傻宫如何找到失踪的爱人？本片根据ひうらさとる的同名漫画改编，为TV剧的电影版。©豆瓣', '绫濑遥', '吉野洋', 6.4, 9792, 'tt2013233', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1388525291.jpg', 2.6, 15.9, 50.4, 22.9, 8.2, '0.021765,-0.221538,-0.734422,0.329083,0.242314,-0.455830,0.600954,0.178477,-0.371157,-0.403598,0.133448,0.859682,-0.514351,0.159955,0.386912,-0.112875,-0.234010,-0.558290,0.051829,-0.124411,-0.112393,-0.286582,-0.135799,0.296013,0.104421,-0.249791,0.932042,0.166450,-0.078428,0.545313,0.402015,0.271515,-0.378492,0.459866,-0.217539,0.148568,0.089939,0.486606,-0.386836,0.201290,-0.132547,-0.206800,-0.243486,-0.077605,-0.013077,0.159659,0.597655,-0.224179,-0.246257,-0.036739,0.366318,-0.366296,-0.179513,0.110208,0.313699,0.114285,0.211773,0.431784,-0.186669,0.084858,-0.044226,-0.269151,-0.539386,0.040196,0.164188,0.082318,-0.358985,0.389988,-0.040809,-0.407283,0.306690,-0.230996,0.276183,0.774773,0.133545,0.347402,-0.362266,0.113254,-0.331154,0.139236,0.835206,0.006442,-0.112968,0.517110,0.018170,-0.448369,-0.029934,-0.135244,-0.471060,0.130101,0.015007,0.038671,-0.002299,0.140327,-0.774959,-0.024458,-0.176215,-0.010278,0.200382,-0.384314,0.141518,-0.829293,-0.191500,-0.457751,-0.280561,0.033024,0.293899,-0.265545,0.638758,-0.775563,0.305476,0.334098,0.191591,-0.497303,0.728565,0.153434,0.045671,-0.377179,-0.073266,0.307616,0.042062,0.431203,-0.065238,0.226757,-0.010299,-0.123879,-0.574466,0.074208', '1303333', '11541282', '1507140', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6772974', '暗金丑岛君', '剧情', '繁华大都市下，无论青年男女还是老弱青壮，一曾纯洁的心全都在物欲横流的世界里恣意沉沦堕落。也许正因为对钱无以复加的渴望，才让丑岛馨（山田孝之 饰）这样的人有了生存的空间，而看似邪恶的丑岛又恰恰能堪破繁华的虚无表象。美丽少女铃木未来（大岛优子 饰）被母亲（黑泽明日香 饰）拖累，为了还清拖欠丑岛的债务而利用青春赚钱，在充满诱惑的路上越走越远。活动社团BUMPS负责人小川纯（林遣都 饰）一心要实现赚大钱的梦想，为了举办大型社交聚会，他疲于奔命四处网罗投资人。在此期间他向丑岛举债，却怀着不为人知的企图。未过多久，这群深陷金钱漩涡的人被卷入腐烂的深渊……本片根据漫画家真锅昌平的同名原作改编，是该作TV剧的电影版。©豆瓣', '山田孝之', '山口雅俊', 7.5, 10383, 'tt2013299', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1618498929.jpg', 0.8, 4.3, 34, 40.6, 20.3, '-0.155505,0.077382,-0.579844,0.263774,-0.099688,-0.198744,0.713356,0.144924,-0.101245,-0.107316,0.290702,0.348043,-0.011141,0.057239,0.357169,0.050632,-0.139409,-0.405912,-0.201163,-0.106506,-0.038996,-0.236371,-0.257781,-0.128211,-0.213151,-0.092549,0.998012,0.490111,-0.236443,0.103836,0.274203,0.272185,-0.224060,0.299062,0.003449,-0.029342,-0.106952,0.040642,-0.230970,-0.022154,-0.150259,-0.320075,-0.295272,0.025272,-0.196886,0.255263,0.718612,-0.187111,0.050723,-0.203716,0.362367,-0.163917,-0.223347,-0.029340,-0.111314,-0.098141,0.067885,0.161310,-0.254352,0.057488,0.269871,-0.079602,-0.825804,-0.220624,0.183420,0.209956,-0.221118,0.492673,0.197727,-0.311619,0.149552,-0.155509,-0.105338,0.064901,0.424483,0.364394,-0.180485,0.219430,-0.391807,0.411404,0.523384,0.070390,-0.302220,0.342939,-0.592194,-0.287673,-0.124159,-0.346819,-0.564333,-0.253300,0.181803,0.010242,-0.181225,0.345607,-0.691783,0.224053,-0.027920,-0.158329,0.141462,-0.395207,-0.280280,-0.495377,-0.276171,-0.207774,-0.124553,-0.035662,0.325828,-0.229239,0.831088,-0.666071,0.008118,0.860491,0.430676,-0.471862,0.603490,0.120465,-0.044311,-0.175453,-0.421216,0.374143,0.016016,0.381541,-0.073974,0.099612,-0.280203,0.011884,-0.330004,0.483281', '26759820', '25880986', '25890078', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6776051', '平常的心', '剧情', '1981年，艾滋作为一种前所未见的免疫系统缺陷疾病在纽约出现。由于它集中发生在男同性恋当中，所以在当时又被称为“同志病”。内德（马克·鲁弗洛 Mark Ruffalo 饰）是一个激进的同志作家，当他看着朋友纷纷死去以及政府的不作为时，义愤填膺的他发起了男同健康危机组织， 呼吁政府和社会公众对这场即将爆发的大瘟疫给予重视。半身瘫痪的女医生艾玛（朱莉娅·罗伯茨 Julia Roberts 饰）是少数从一开始就高度警惕艾滋疫情的的医护人员，也是内德重要的异性恋盟友。在运动中内德认识了纽约时报记者菲尼克斯（马修·波莫 Matt Bomer 饰），两人陷入如火如荼的热恋。然而菲尼克斯最终也被确诊感染，悲痛的内德惟有爱人和事业两线作战。健康危机组织的主席布鲁斯（泰勒·克奇 Taylor Kitsch 饰）虽然是内德最好的朋友，然而深柜的他行事风格与好斗的内德截然相反。执行董事汤米（吉姆·帕森斯 Jim Parsons 饰）一直试图平衡两人，却无法消弭越来越大的分歧，一场决裂迫在眉睫。而此刻已是艾滋在美国蔓延的第四个年头......HBO电视电影《平常的心》改编自托尼奖同名戏剧，作者拉里·克莱默亲身经历了80年代的艾滋风暴，他以自己为原型，将纽约同性恋人群以及艾滋病人的生活和感悟写进剧本。电影不但描绘了早期艾滋运动的真实和复杂面貌，而且呈现了同志争取权益的曲折与必要性。无论身处怎样的时代和环境，去爱、去追求爱都应该与生俱来的权利。', '马克·鲁弗洛', '瑞恩·墨菲', 8.4, 52969, 'tt1684226', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2180543688.jpg', 0.4, 1.2, 15.5, 45.1, 37.9, '0.180156,-0.098142,-0.576359,0.408328,-0.015564,-0.049550,0.769639,0.224545,-0.443553,-0.236368,0.190223,0.724301,-0.205798,0.045635,0.220434,-0.108781,-0.239215,-0.701710,-0.099726,0.134045,-0.283104,-0.551367,-0.348238,-0.375840,-0.127045,-0.474402,0.587236,0.165392,-0.412645,0.221644,0.341375,0.449454,-0.034254,0.510704,0.113207,-0.205041,0.000479,-0.185228,-0.428124,0.041679,0.228245,-0.173322,-0.072516,0.212174,0.030863,0.404135,0.628600,-0.282579,-0.243756,0.014988,0.512822,-0.274156,-0.132557,0.321789,0.335569,-0.076796,0.120256,0.191671,0.027125,-0.016019,-0.116072,-0.098276,-0.820583,-0.055697,0.178257,0.329310,-0.441162,0.672650,-0.087692,-0.122738,0.046702,-0.088158,0.187969,0.443423,0.181869,0.498636,-0.113843,0.018928,-0.301819,0.151246,0.661415,0.114236,-0.515729,0.324353,-0.582138,-0.502664,-0.302043,-0.187488,-0.494105,-0.079088,0.298543,0.008124,-0.266480,0.433144,-0.502703,0.056392,-0.062487,-0.237571,-0.128301,-0.302129,-0.019090,-0.584790,-0.247247,-0.435606,-0.136044,0.006580,0.078085,-0.236753,0.892648,-0.815856,0.125632,0.451795,0.154373,-0.576914,0.640163,0.239161,0.088588,-0.306425,-0.235755,0.363852,-0.052284,0.186384,0.065741,0.285471,-0.035718,-0.097804,-0.275245,0.496996', '27602116', '24284209', '30162520', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6778650', '嫁个100分男人', '喜剧', '叶欣荣（梁咏琪 饰）被恋爱七年的男友抛弃，忽然从待嫁女变成了剩女，嫁人无望，却误打误撞认识了老板的司机古须仁（郑中基 饰）。她根本不知道，古须仁竟然是如假包换的香港老板，因为树敌太多，不得已和司机关仁（杜汶泽 饰）交换身份。褪去了阔少爷的光环，一直得不到真爱的古须仁在荣荣身上找到了感觉，也因为互换身份，关仁认识了荣荣的闺蜜Nikki（谢娜 饰），一见倾心，Nikki却担心上司办公室性骚扰，处处防备，闹出不少笑话。而古须仁和荣荣，在帮助关仁追求Nikki的过程中渐渐坠入爱河。古须仁破格提拔荣荣去香港做高层。荣荣经历了一次梦幻般的旅程，私人飞机、名车、名表、名牌服装首饰、上流社会的交际……所有的一切都让荣荣感到不真实。当古须仁鼓起勇气向荣荣亮出真正身份并深情表白时，却让荣荣感到他句句假话，拒绝了他，但是此时决定洗心革面的古须仁却再也不愿意放手，虽然荣荣已经不在身边，他却依然遵守着荣荣和他的爱情约定……', '郑中基', '王晶', 4, 10630, 'tt2321373', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1440440928.jpg', 33.5, 37.5, 24.3, 3.3, 1.4, '0.128034,0.201626,-0.618221,0.310926,-0.163969,-0.277429,0.357353,0.096499,-0.477338,-0.496784,0.005195,0.601218,-0.216257,0.099025,0.048386,0.088804,-0.024880,-0.573324,-0.006235,-0.199130,-0.054318,-0.418630,0.211974,0.081883,-0.253024,-0.044425,0.520702,0.137718,-0.310296,0.404201,0.643894,-0.019228,0.121764,0.584649,-0.046656,-0.014298,0.089518,0.247768,-0.409516,-0.232216,0.096842,-0.187977,-0.034892,0.353997,0.088077,0.320652,0.302123,-0.167076,-0.325953,0.039647,0.446660,-0.304677,-0.112791,-0.054401,0.057202,-0.116008,0.142379,0.280003,-0.029999,0.048349,0.075727,0.121331,-0.611883,-0.013899,0.067371,0.156408,-0.465872,0.346445,-0.133938,-0.107684,-0.126323,-0.252481,0.359922,-0.047605,0.100755,0.119774,-0.268210,-0.060319,-0.534759,0.170125,0.702975,0.216452,-0.140613,0.611233,-0.331278,-0.282305,-0.069050,-0.035451,-0.597635,0.052728,-0.099637,0.224603,-0.373330,0.009734,-0.164379,-0.279327,-0.212924,0.147490,0.090722,-0.725182,0.071352,-0.227662,-0.305017,-0.535344,-0.437638,0.015420,-0.160529,-0.335184,0.390973,-0.860961,0.089026,0.425737,0.563877,-0.626885,0.589153,0.317602,-0.164517,-0.390727,-0.112934,0.153531,0.079877,-0.022262,0.151640,0.131162,-0.112288,-0.063837,-0.267488,0.266745', '1949320', '1494897', '1301022', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6781971', '萧红', '剧情', '1942年，病中的女作家萧红（宋佳 饰）困在了日军炮火下的香港，年轻的东北作家骆宾基（张博 饰）陪在她的身边，萧红向骆宾基讲述了她10年来颠沛流离的写作生涯，以及她和作家萧军（黄觉 饰）、端木蕻良（王仁君 饰）之间的两段不寻常的感情，特别是她与萧军难以忘怀的感情经历。这个生逢战乱，历尽坎坷，向往爱情，充满魅力的女作家深深打动了骆宾基，但此时的萧红已经病入膏肓。骆宾基和外出归来的端木蕻良把萧红送进医院，陪伴她度过了生命中最后的时光……©豆瓣', '宋佳', '霍建起', 6.6, 16327, 'tt2779050', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1883474982.jpg', 3.1, 13.6, 44.8, 29, 9.4, '0.114474,-0.123221,-0.582412,0.533115,0.208977,-0.553238,1.076599,-0.049362,-0.474074,-0.091313,0.251364,0.514469,0.041708,0.490665,0.359821,-0.121752,-0.302057,-0.767443,-0.143997,-0.033126,-0.086677,-0.300246,-0.403283,0.228753,-0.312540,-0.076917,0.707255,0.366469,-0.171725,0.743839,0.117529,0.376520,-0.132282,0.572801,-0.248569,0.192553,0.073856,0.212662,-0.364059,0.198786,0.083008,-0.338695,-0.074305,0.013330,-0.260590,0.134705,0.586112,-0.055859,-0.004673,-0.088964,0.434964,-0.284393,-0.066185,0.121796,0.025606,0.202393,0.327213,0.355278,-0.252837,0.087196,-0.105387,0.074913,-0.578911,-0.126373,0.272742,0.242648,-0.821474,0.629533,-0.122144,-0.057841,0.078444,-0.342614,0.358815,0.273557,0.209345,0.470635,-0.406659,0.140158,-0.238618,0.599029,0.719352,-0.069628,-0.107856,0.446805,-0.376984,-0.409896,-0.040664,-0.158910,-0.715939,0.080478,0.224880,0.184339,-0.250254,0.297503,-0.637682,0.103046,0.057587,0.005589,0.069055,-0.401639,-0.187656,-0.543749,-0.538753,-1.084209,-0.664325,0.006235,0.257432,-0.420710,0.991560,-0.442050,0.303765,0.244857,0.185192,-0.287948,0.790000,0.335160,-0.090409,0.116185,0.422455,0.831287,-0.398593,0.342750,-0.146044,0.432998,-0.197528,0.016958,-0.595403,0.510339', '25828521', '26348103', '1291852', '1389980');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6782006', '我愿意', '喜剧', '唐微微（李冰冰 饰），32岁，既是设计公司的白骨精，也是大龄剩女。她的闺蜜靳小令（薛佳凝 饰）在怀孕期间，热心为她网络征婚并安排了相亲。结果，唐微微装孕妇吓跑了大多数，只剩下一个杨年华（孙红雷 饰），两人由此相识。与此同时，唐微微所在公司接了美国的客户，见面时她发现客户代表竟是7年前抛弃自己的男友王洋（段奕宏 饰）。他们从18岁开始恋爱，青梅竹马度过7年，终因王洋为理想奔波而分手。如今，昔日恋人重逢，别有一番滋味在心头。此时，杨年华却开始了一波又一波的热情攻势，无论是嘘寒问暖还是炒菜做饭，都体贴入微。而王洋也不甘示弱，意图通过忆苦思甜昨日重现唤醒唐微微重回他怀抱。于是，情敌之战，一触即发……本片改编自作家陈彤的同名小说。©豆瓣', '李冰冰', '孙周', 5.9, 117365, 'tt2249207', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1384729427.jpg', 5.8, 21.2, 51.8, 16.7, 4.6, '-0.012971,0.102718,-0.559446,0.443938,-0.063398,-0.511530,0.637463,0.084711,-0.478406,-0.393723,-0.249725,0.294273,-0.457121,0.612480,0.272035,-0.396284,0.149172,-0.615351,-0.002760,0.044971,-0.228107,-0.018091,-0.029912,-0.313217,0.047341,-0.036213,0.414310,0.021008,-0.150720,0.412040,0.579681,0.181907,-0.119963,0.621001,0.002234,0.132923,-0.042920,0.291787,-0.446285,0.240256,-0.034585,-0.425884,-0.100954,-0.102562,-0.098121,0.516676,0.599454,0.142972,-0.253202,0.121999,0.643157,-0.191066,-0.199026,-0.137302,0.456197,-0.069903,0.137378,-0.361055,-0.072381,-0.056032,-0.030138,-0.171818,-0.068368,0.061993,0.151090,-0.134873,-0.520453,0.261539,-0.055025,0.405569,-0.050992,-0.307371,0.230282,0.376270,0.481138,0.225293,0.067208,0.146313,-0.267239,0.684625,0.701089,0.295503,0.034401,0.481982,-0.287626,-0.393272,0.035332,0.129636,-0.431186,0.006938,0.183298,-0.085525,0.330743,0.197810,-0.361524,-0.309374,0.141143,0.115226,0.210289,-0.588401,0.237990,-0.442212,-0.464040,-0.471556,-0.200146,0.122463,0.165325,-0.352239,0.572351,-0.716377,0.000237,0.321051,0.005089,-0.561638,0.561284,0.062463,0.054542,-0.330856,0.361296,0.398612,-0.082047,-0.126707,0.054322,0.314068,-0.148461,0.027018,-0.328119,0.306807', '1301022', '10535447', '24843198', '1325399');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6786002', '触不可及', '剧情', '因为一次跳伞事故，白人富翁菲利普Philippe（弗朗索瓦·克鲁塞 François Cluzet 饰）瘫痪在床，欲招聘一名全职陪护。由于薪酬高，应聘者云集，个个舌灿莲花，却无法打动他的心。直到黑人德希斯Driss（奥玛·赛 Omar Sy 饰）的出现才让他作出决定。德希斯刚从监狱出来，背负家庭重担，一心只想寻张辞退信以申领救济金，而且他明显对女助理的兴趣要远大于这份工作。但是菲利普还是一眼相中了这个小伙子。于是，德希斯开始了一个月的试用期。虽然舒适的豪宅环境让他倍感虚荣，但是他仍面临很多挑战：不仅要为菲利普作身体复健，还得给他洗浴、灌肠、拆信、穿丝袜等。起初，两人的思维方式与价值观大相径庭，但是，随着了解的不断深入，他们成为了朋友……本片取材于真实事件，获2011年东京电影节最佳影片金麒麟奖，弗朗索瓦·克鲁塞与奥玛·赛分享影帝桂冠。©豆瓣', '弗朗索瓦·克鲁塞', '奥利维埃·纳卡什', 9.3, 1013046, 'tt1675434', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1454261925.jpg', 0.1, 0.3, 4, 27.1, 68.5, '-0.168391,0.025096,-0.550773,0.487880,0.020235,-0.579554,0.387442,0.291145,-0.505703,-0.345408,0.076462,0.654990,-0.269972,0.148810,0.517673,-0.067945,-0.351066,-0.550910,0.012440,0.139205,-0.398771,-0.334635,-0.067563,-0.231864,-0.259803,-0.383041,0.598946,0.031907,-0.109225,0.281007,0.383959,0.349366,0.297192,0.356056,-0.058493,-0.228171,0.133933,-0.172133,-0.456033,0.142853,0.094809,-0.065273,-0.399403,0.220033,0.348820,0.317815,0.498478,0.007636,-0.338177,0.069148,0.392607,-0.172116,-0.054718,-0.030443,0.034165,0.103799,0.102962,0.179912,0.010281,0.194824,0.142519,-0.241656,-0.628179,0.013730,0.083428,0.128423,-0.498021,0.336011,-0.337204,0.080440,-0.258248,-0.128592,-0.265615,0.117299,0.070972,0.473843,-0.108025,0.147529,-0.463896,0.113307,0.514724,0.221637,-0.364800,0.448369,-0.259942,-0.594272,-0.012598,-0.109260,-0.266481,0.043014,0.136412,0.050527,-0.072024,0.051082,-0.371624,-0.192915,-0.304740,-0.289992,0.041809,-0.298641,0.122334,-0.590272,-0.102632,-0.235482,-0.320404,-0.095357,0.197965,-0.176812,0.533213,-0.577990,0.077162,0.452972,0.140053,-0.485467,0.512091,0.127593,0.225655,-0.145617,-0.231987,0.147364,-0.018679,0.126440,0.099484,0.164881,-0.009516,-0.354239,-0.285525,0.448762', '4301278', '1793491', '26259202', '1996313');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6788265', '饭局也疯狂', '剧情', '高档饭店“天人一”的封老板（刘桦 饰）为如何处理在自己饭店偷录的一张光盘而发愁，但更让他头疼的事情又来了：雇员们因长期拖欠工资全体离职，只有三个本家亲戚留下帮忙，天人一眼看就要倒闭。知名国学、成功学、风水学大师谭大山（范伟 饰）受封老板所托，为他带来一桌饭局，使天人一在某执行总监莫妮卡（莫小棋 饰）前来谈判收购事宜时，不至于太过冷清。谭大山带来的客人们：身份神秘的大老总（韩童山 饰）、暴发户矿主蔡哥（刘亚津 饰）和偷偷跟随的飞贼小蝴蝶、动作明星家明（黄渤 饰）陆续抵达。刑警老梅（梁冠华 饰）一家三口也在这天选择天人一就餐。封老板无人可用只得央求前来讨债的鱼贩老虾米担任大厨，忙乱的饭局上人人各有心思，碰撞出了连串出人意表的故事……©豆瓣', '范伟', '尚敬', 5.1, 39979, 'tt2248789', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1377122324.jpg', 14.8, 33.1, 39.3, 9.6, 3.2, '0.054201,-0.121655,-0.398779,0.154273,0.058021,-0.238093,0.435925,0.548228,-0.460792,-0.405940,0.293959,0.598216,-0.179200,0.218601,0.424345,-0.185940,-0.076603,-0.249642,0.091917,-0.115394,-0.155756,-0.292760,0.056946,-0.545387,0.020882,0.101517,0.020169,0.014225,-0.025012,0.353256,0.398206,-0.001974,-0.237248,0.215100,-0.166330,-0.056602,0.069011,-0.045920,-0.225369,-0.100200,-0.259044,-0.107751,-0.364861,-0.121156,0.265771,0.313364,0.314656,-0.072313,-0.217893,-0.129734,0.149251,-0.129959,0.093995,-0.040909,0.301763,0.023484,0.300374,0.058924,-0.456905,0.174171,0.129662,-0.136409,-0.473106,0.170150,0.123145,0.117521,-0.462593,0.137431,0.044065,0.063771,-0.207723,-0.570124,0.047236,0.160086,0.077453,0.284837,0.226953,0.095616,-0.385816,0.390215,0.504227,0.280745,0.197212,0.049064,-0.019889,-0.203954,-0.033781,-0.218498,-0.357900,0.038014,0.384921,-0.151610,0.240689,-0.191110,-0.551284,-0.353112,0.005674,-0.189555,0.114915,-0.096643,-0.077997,-0.766852,0.155977,-0.022075,-0.220917,0.105143,0.430975,0.056093,0.626725,-0.582864,-0.102774,0.291896,0.153412,-0.430146,0.620394,-0.095662,0.113234,-0.126014,-0.271095,-0.566593,0.238282,0.410131,0.188224,0.170085,-0.288621,-0.344807,-0.037160,-0.192673', '6731985', '3147969', '1306860', '1294009');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6788517', '无人生还', '惊悚', '人烟稀少的山间路上，男人（卢克·伊万斯 Luke Evans 饰）和妻子驾驶驾驶汽车漫无目的前行。途中他们在小酒馆休息，遭到弗林（德里克·迈戈雅 Derek Magyar 饰）等匪帮的骚扰。当再次上路时，弗林一众突然驾车袭击了这对夫妇，并将他们掳回自己的巢穴。 恶毒的匪徒在男人面前残忍杀害了其妻子，令人备感意外的是男人突然豹变，轻松干掉行凶的恶徒。与此同时，匪帮在夫妇的车中发现一个被捆绑起来的女子，对方是在一起震惊全国的血型杀人案中失踪的艾玛•沃德（阿德莱德·克莱蒙丝 Adelaide Clemens 饰）。形势急转直下，人多势众的匪帮反倒成为被猎杀的目标，也许他们惹到了实在不该惹的一个人……©豆瓣', '卢克·伊万斯', '北村龙平', 6.4, 18902, 'tt1763264', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1942243073.jpg', 3.1, 14.4, 48.7, 25, 8.7, '0.578672,-0.152212,-0.830511,0.459766,-0.107261,-0.217940,1.000948,0.145815,-0.584376,0.048738,0.486552,0.750982,-0.202955,0.058053,0.548365,0.108350,-0.332742,-0.539096,-0.068623,-0.172702,-0.464615,-0.237297,-0.206486,-0.429638,0.143186,-0.233668,0.397350,0.198243,-0.175867,0.663107,0.289456,0.350504,-0.194287,0.610249,-0.387452,0.252512,0.243089,-0.191681,0.154696,0.343314,-0.251874,-0.416134,-0.053947,0.148718,-0.182328,0.378938,0.905298,-0.345864,-0.198359,-0.161093,-0.036842,-0.421053,0.227617,0.043022,0.534258,-0.384275,0.152887,0.090354,-0.263350,-0.044711,0.147289,0.189832,-0.582211,0.284917,-0.057806,-0.012004,-0.612293,0.288061,-0.147018,0.035369,0.217175,-0.106624,0.346396,0.152741,0.209423,0.253255,0.057338,-0.153730,-0.608093,-0.198354,0.526977,-0.020674,-0.089320,0.074369,-0.104506,-0.130807,-0.002634,-0.306007,-0.431679,-0.374866,0.676349,-0.064462,-0.271421,0.293670,-0.424900,0.006546,-0.474456,0.024716,-0.175690,-0.346905,-0.260213,-0.625982,0.157640,-0.233554,-0.130790,0.410889,-0.096472,0.016297,0.411815,-0.609954,0.057353,0.698414,0.362051,-0.360371,0.366233,0.000032,0.163473,0.016299,-0.246648,0.101050,0.436571,0.397560,0.264351,0.497273,-0.246832,0.033465,-0.320799,0.423266', '3011051', '21619567', '1301686', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6790253', '叛谍追击', '动作', 'CIA顶尖探员罗根（艾伦·艾克哈特 Aaron Eckhart 饰）在前妻过世之后，想要修补与女儿艾美（丽亚娜·莱伯拉托 Liana Liberato 饰）的关系，于是辞去了中情局顶尖探员的职务，带着和他关系疏远的艾美，搬到了安特卫普开始尝试过一般人的生活。随后，罗根进入比利时一家资金亿万美元的跨国公司的安全系统部门，担任安全顾问一职。某次，在整个团队的共同努力下，他们成功破解一个高度机密的安全装置。但第二天清晨，当罗根神采奕奕地到达办公地点时，却发现与公司相关的所有人事物通通凭空消失，而且所有证明公司存在过的证据也全被销毁。与此同时，罗根发现他的助理竟然是一名训练有素的特工，负责的任务就是杀死自己和自己的女儿。更让罗根感到意外的是，他在CIA的前同事兼女友也奉命将其追捕归案。为了活命并找出幕后凶手，罗根和女儿艾米在被一群训练有素的杀手团队追杀的同时，开始了一段逃亡之旅。在这个过程当中，父女之间开始慢慢相互了解，并重新建立起信任和亲情......然而威胁和阻碍不断升级，并逐渐将父女二人卷入一场更大的、国际性的阴谋当中....', '艾伦·艾克哈特', '菲利普·施特尔茨尔', 6.1, 9929, 'tt1645155', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1760662652.jpg', 2.2, 16.8, 59.9, 17, 4, '0.294769,0.151205,-0.763668,0.624413,-0.234271,-0.234409,0.686724,0.043090,-0.699953,-0.360965,0.120554,0.875472,-0.079631,0.157097,0.298523,-0.163860,-0.345804,-0.878931,-0.211982,-0.278431,-0.371980,-0.673720,-0.163758,-0.229065,-0.131378,-0.343724,0.667551,0.075382,-0.174277,0.501253,0.219628,0.193229,-0.268089,0.615450,-0.064417,-0.072968,0.313228,-0.160914,-0.458070,0.274068,-0.045787,-0.076972,-0.075736,0.165451,0.083661,0.413040,0.618674,-0.159149,-0.105591,-0.111285,0.209088,-0.394495,-0.006159,0.033832,0.496449,0.199379,0.190318,0.303657,-0.308046,0.163201,0.039382,-0.132896,-1.063309,-0.075073,0.151737,0.067327,-0.533593,0.358414,-0.170101,0.045471,0.054041,-0.393924,0.318964,0.570812,0.079836,0.275150,-0.310996,0.162012,-0.602723,0.006704,0.695578,-0.227679,-0.194198,0.176086,0.013352,-0.415781,-0.225613,-0.088958,-0.112251,-0.131807,0.383006,0.292012,-0.018041,0.203380,-0.826321,-0.018816,-0.378396,-0.308544,-0.049008,-0.550358,0.080115,-0.746718,-0.093112,-0.176322,-0.334991,0.159601,-0.013935,-0.421694,0.541523,-0.883582,0.104091,0.610979,0.350446,-0.479156,0.443588,0.086015,0.490754,-0.259007,-0.270600,0.075738,0.337611,0.460880,0.158174,0.317538,-0.099950,-0.147906,-0.243597,0.250541', '1793491', '1307442', '4301278', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6791750', '起风了', '剧情', '那是一个动荡的年代，战争、饥饿、疾病、天灾，死神的阴影笼罩全球，却无法遮挡心头闪现的梦想和希望的光芒。平凡的日本少年堀越二郎（庵野秀明 配音）迷恋游弋长空的飞机，梦中他与意大利飞机设计师卡普罗尼（野村万斋 配音）成为朋友，享受着飞行带来的乐趣。恐怖的关东大地震，二郎邂逅一生的挂念——里见菜穗子（泷本美织 配音），短暂的相逢，无序的混乱中又失之交臂。在命运的指引下，被称为天才的二郎如愿成为飞机设计师，他和前辈同侪共同努力，绞尽脑汁提升飞机的性能。欧洲的先进设计让他们痛心疾首，另一方面又充满矛盾的打造着融合了梦想和杀人属性的机器。他追逐梦想，并与菜穗子重逢。动荡的昭和时代，风雪飘摇之中步伐从未停止……本片根据零式战斗机设计师堀越二郎的人生事迹和作家堀辰雄的同名小说改编。©豆瓣', '庵野秀明', '宫崎骏', 8.2, 231193, 'tt2013293', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1998028598.jpg', 0.6, 1.8, 19.9, 44.3, 33.4, '0.101082,-0.039689,-0.647718,0.742097,0.202677,-0.255695,0.708931,0.253857,-0.173782,-0.276253,0.463507,0.733360,-0.205606,0.130132,0.285686,0.019665,-0.150550,-0.737292,0.131899,0.087372,-0.038311,-0.226185,-0.506949,-0.133291,0.045613,-0.303910,0.978169,0.286880,-0.206160,0.657223,0.049946,0.087007,-0.248899,0.316479,-0.317805,0.013297,-0.012723,0.162848,-0.552189,0.080778,-0.340895,-0.203300,-0.007343,0.047357,-0.236651,-0.010860,0.738549,-0.280340,0.042953,-0.221960,0.249006,-0.227282,-0.057664,-0.040647,0.141734,0.249613,-0.030297,0.039685,-0.033013,0.015066,-0.181715,0.086380,-0.783005,0.018668,0.155295,0.044676,-0.417912,0.366157,0.002550,-0.145885,0.154858,-0.022892,0.146937,-0.123600,0.529212,0.575994,-0.294106,0.339937,-0.272090,0.492600,0.529143,-0.186877,-0.414710,0.395206,-0.393975,-0.246501,-0.104296,-0.360939,-0.730243,-0.053842,0.182206,0.095953,-0.070901,0.623588,-0.752389,0.433174,-0.146207,-0.285111,-0.012217,-0.228195,-0.027870,-0.603885,-0.165630,-0.452699,-0.309490,-0.047416,0.299295,-0.195947,0.815380,-0.658430,0.014736,0.588379,0.233876,-0.038732,0.730296,0.127955,-0.037559,-0.243588,-0.157971,0.097637,-0.447696,0.302229,-0.099523,0.335940,-0.013642,0.237494,-0.556171,0.493800', '25880986', '3811356', '10467125', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6793319', '女蛹', '爱情', '混血美女关文馨（张榕容 饰）和“白富美”女孩安妮（严千千 饰）是大学同学，她们当初几乎同时喜欢上帅气的实习老师骆嘉（任泉 饰）。在安妮主动追求下，她最终骆老师成为情侣。毕业后，没有任何背景的文馨成为一家发廊最受欢迎的发型师，而安妮在和骆老师美国同居两个月后回国，她没有等 到男友的结婚戒指，因为骆老师打算向文馨求婚。恼羞成怒的安妮在情人节当天绑架文馨，并试图杀害这位曾经的闺蜜。一番搏斗之后，文馨陷入昏迷。当她再次醒来，发现此时已到了五月，长达三个月的记忆成为空白，而安妮则下落不明。她与骆嘉断掉的恋情重新开始，但是各种诡异事件相继在她身边发生。安妮充满怨念的鬼魂，似乎已进入文馨的体内，继续左右她的命运……©豆瓣', '张榕容', '邱处机', 6.6, 22986, 'tt2363421', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1835942578.jpg', 3.7, 12.6, 43.5, 31.4, 8.8, '0.314524,0.044054,-0.712059,0.448823,-0.051926,-0.555120,0.823999,-0.064462,-0.428110,-0.503615,0.035268,0.467375,-0.486389,0.680052,0.516753,0.011482,-0.208045,-0.890490,0.069916,-0.278605,-0.441609,-0.651609,0.090405,0.201165,-0.034718,-0.081147,0.732678,-0.215747,0.017881,0.765734,0.312542,0.193090,-0.109649,0.567112,0.082330,0.193559,0.229128,-0.107429,-0.462260,0.299337,0.212708,-0.171964,-0.092023,0.103762,0.024165,0.103245,0.745463,-0.163726,-0.182029,-0.058258,0.594928,-0.178879,-0.126879,0.072230,0.501914,0.010233,0.437618,-0.119859,-0.138642,-0.059909,0.115680,-0.155438,-0.184046,0.312154,-0.009081,0.076851,-0.375826,0.315925,-0.001998,0.216536,0.224548,-0.466821,0.115193,0.522077,0.081546,0.364973,-0.288678,0.295616,-0.334301,0.056553,0.562194,0.135575,-0.091863,0.442494,0.129448,-0.315397,-0.119057,0.098133,-0.443163,0.279905,0.338164,0.334379,-0.112577,0.109773,-0.470064,-0.209203,-0.052662,-0.006630,0.255338,-0.148691,-0.124040,-0.670271,-0.187189,-0.481717,-0.364578,-0.096663,-0.092974,-0.334036,0.489850,-1.088592,0.417378,0.217996,0.418652,-0.557037,0.483131,0.179427,0.160872,-0.091468,-0.183408,0.352407,0.014138,0.365830,0.273422,0.328024,-0.011567,0.048280,-0.479312,0.345292', '2027925', '1301022', '1306544', '33218345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6796158', '铜雀台', '剧情', '庚子年，恰逢天象“四星合一”，预示改朝换代之征兆。曹操（周润发 饰）的部属、尤其他的公子曹丕（邱心志 饰），希望借此良机推献帝禅位、曹操登基；同时反对曹操的势力，也加紧了行动，无人知晓四星合一之时，大汉天下将发生何种惊天动地之事。 关中，马超、韩遂的俘虏营后方，少男穆 顺（玉木宏 饰）、少女灵雎（刘亦菲 饰）被一支铁骑掠走，押到一个巨大陵墓里，进行残酷的训练，他们将被塑造成铁血死士，完成一个不可告人的惊天任务。 五年后，曹操盛殓关羽，回到铜雀台，灵雎一袭红衣出现在曹操身旁。柔弱的汉献帝（苏有朋 饰）、野心勃勃的伏后（伊能静 饰）对曹操的归来噤若寒蝉，大臣们亦是各怀鬼胎。四星即将合一，一出“杀死曹操”的阴谋大戏正在紧锣密鼓的谋划着……©豆瓣', '周润发', '赵林山', 5.2, 59355, 'tt2063013', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1709282333.jpg', 13, 33.8, 39.1, 9, 5.1, '0.080462,0.243772,-0.791013,0.547740,0.065951,0.323467,0.578872,0.173361,-0.328596,-0.256985,0.657338,0.402352,-0.432571,-0.029093,0.260506,-0.258555,0.255619,-0.956826,-0.279075,-0.029819,0.117493,-0.083623,-0.432158,0.062365,-0.204536,-0.129091,0.690876,0.043746,0.108792,0.366024,0.411481,0.202298,-0.188784,0.543771,0.101015,-0.071303,-0.056553,-0.309328,-0.207644,0.129013,-0.296835,-0.540993,-0.264704,0.139399,-0.522478,0.123120,0.669376,-0.503360,0.263126,-0.075006,0.415196,-0.036690,0.002833,0.338878,0.282813,0.256740,-0.165020,0.392611,0.214606,0.020732,0.085692,-0.096142,-0.521267,-0.096589,-0.007788,0.175028,-0.270592,0.387850,-0.166092,-0.010357,0.159949,-0.384832,0.121676,0.653915,0.457729,0.108750,-0.109108,-0.139420,-0.440366,0.329823,0.441534,-0.278470,-0.055001,-0.120787,0.328167,-0.477183,0.112621,-0.214376,-0.300787,-0.039813,0.575267,-0.135398,0.344600,0.178404,-0.141895,-0.218341,-0.300141,0.212870,-0.080986,0.154018,0.027227,-0.479574,-0.001849,-0.132838,-0.423421,0.305483,0.439066,-0.013312,0.504246,-0.479766,-0.256942,0.210915,0.132377,-0.606383,0.084555,-0.229872,0.386655,0.057731,-0.028271,0.091731,0.127234,0.154823,0.176971,0.381515,-0.460212,-0.171511,-0.403627,0.218425', '6999256', '1301022', '10467125', '1432699');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6799156', '超时空救兵', '喜剧', '立志成为作家的青年二蛋（霍建华 饰）历时三年，写成唐朝侠客史可进之传奇故事，然而却被出版社社长嘲讽打击。在一千多年才轮回一次的流星雨之夜，失落的二蛋在公园排遣郁闷，突然胸前的家传玉佩灵光乍现，将他带回了一千多年前的唐朝天宝十年中秋夜。二蛋机缘巧合在唐朝成为了史可进（郭品超 饰）的救命恩人，得以入住范阳王府史家，并对史可进的小妹灵芝（景甜 饰）一见倾心。史家世子史可延嫉妒史可进人财俱得，派出杀手杨傲（孙浩 饰）刺杀亲弟，危急关头二蛋再度使用玉佩，将史家兄妹带回现代，杨傲凭借自己的玉佩同样来到了2012年，二蛋与三位身怀绝技的古代人引发连串奇遇，而一个阴谋也逐渐浮出水面……©豆瓣', '霍建华', '林子聪', 5.1, 10027, 'tt2460656', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1348930803.jpg', 18.7, 29.5, 35.9, 10.5, 5.4, '-0.089730,0.123976,-0.380485,0.558823,-0.025911,-0.429363,0.355112,0.074441,-0.634293,-0.381556,0.548973,0.475517,-0.316407,0.168017,0.233542,-0.015076,0.202010,-0.502217,0.264335,-0.492184,0.037277,-0.266486,-0.442360,0.092378,-0.065965,-0.294941,0.524868,0.175595,-0.154489,0.602457,0.210495,0.358474,-0.235472,0.193919,-0.096254,0.221344,0.138823,0.081245,-0.351187,0.132684,-0.143644,-0.360871,-0.084430,0.079439,-0.235125,-0.090646,0.538942,-0.275447,-0.026122,-0.188958,0.514653,-0.011750,-0.459555,-0.029741,0.400321,0.183733,0.096423,0.272799,-0.212626,0.105118,0.138045,-0.015757,-0.181217,0.235692,0.036957,0.010603,-0.558437,0.357713,-0.018113,-0.168722,-0.075691,-0.216844,0.266192,0.216073,0.246256,0.321707,-0.315917,0.178768,-0.448193,0.488887,0.126781,-0.197881,-0.007878,0.117619,0.245269,-0.314559,0.207967,0.057547,-0.139767,0.135376,0.447690,-0.102681,-0.092348,0.428833,-0.517168,0.089870,-0.347208,0.290634,0.200675,0.050101,-0.232109,-0.368029,-0.217178,0.025009,-0.157297,-0.100751,0.226222,-0.190025,0.626486,-0.547145,0.153267,0.082267,0.093863,-0.194852,0.351221,-0.081611,0.047179,-0.219011,-0.031876,0.024709,0.094668,0.349419,0.054454,0.263184,-0.161742,-0.114595,-0.348786,0.450909', '26365262', '26784898', '25922902', '4328442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6799191', '搜索', '剧情', '网络时代的“人肉”技术，通常是娱乐大众的利器，但很不幸，它也可能成为一种杀人工具。上市企业董事长秘书叶蓝秋（高圆圆 饰）在获知自己罹患癌症之后，心灰意冷的她上了一辆公交车，沉浸在惊愕与恐惧的她，拒绝给车上的老大爷让座，引起众议，这一过程被电视台实习记者杨佳琪（王珞丹 饰）用手机拍个正着。佳琪将公车上的新闻火速交给准嫂子陈若兮（姚晨 饰），凭着新闻主编的敏锐嗅觉，若兮将此新闻恶意放大，从而引发了一场社会大搜索，集体讨伐叶蓝秋的道德沦丧。在公众指责和病魔降临的夹缝中，叶蓝秋带着老板沈流舒（王学圻 饰）借给她的100万，彻底玩起了消失。岂料这更使她被冠以“小三”之名。若兮的摄影师男友无意中被卷入叶蓝秋的世界中，为了获得一笔高额报酬，他受雇陪伴在叶左右。而他却不曾想到，这竟是这个饱受指责的女人生命中最后一段时光。叶蓝秋的自杀，彻底颠覆了陈若兮的爱情与生活，也让所有人开始反思……', '高圆圆', '陈凯歌', 7.4, 331591, 'tt2259360', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1598153958.jpg', 1.2, 5.1, 33.2, 44, 16.5, '0.147404,0.511964,-0.557918,0.527233,-0.027994,-0.090904,0.583583,0.145897,-0.614071,0.081888,0.057749,0.624203,-0.338303,0.318317,0.457154,0.050699,-0.094777,-0.716314,-0.202768,-0.004235,-0.192374,-0.347804,-0.108638,-0.186763,-0.186772,-0.184324,0.501997,0.019311,-0.334307,0.246659,0.362220,0.223029,-0.012973,0.738803,-0.001328,0.163043,-0.153768,0.030920,-0.127441,0.224954,0.070098,-0.432572,-0.060632,0.231350,-0.232938,0.159376,0.623546,-0.175740,-0.317979,-0.175282,0.679833,-0.501242,-0.038906,0.077303,0.176132,0.151309,0.289472,-0.001024,-0.338813,0.136102,0.250038,0.167649,-0.756019,-0.150754,-0.103050,-0.020333,-0.475257,0.334526,-0.089904,0.070089,-0.076679,-0.126684,0.390697,0.196917,0.311808,0.060511,-0.348751,-0.184337,-0.406610,0.411645,0.340059,-0.042866,-0.276530,0.267111,-0.042206,-0.340282,-0.183468,-0.031023,-0.558478,-0.167239,0.449743,0.030377,-0.322222,0.285230,-0.583279,-0.087110,-0.255336,-0.317864,-0.137278,-0.400090,-0.130662,-0.412629,-0.141147,-0.153811,-0.275659,0.001957,0.332101,-0.474759,0.704026,-0.695608,0.141586,0.593036,0.269863,-0.358724,0.496371,-0.076096,0.122356,-0.101214,-0.347724,0.145871,0.094306,0.424524,0.046507,0.299865,-0.068672,-0.079689,-0.351188,0.508350', '25928048'