INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6800483', '污泥', '剧情', '家住密西西比河边的14岁少年埃利斯（泰伊·谢里丹 Tye Sheridan 饰）和好友奈克在河中心小岛上发现了一艘废弃的船，同时还有暂住在船上的神秘流浪男子玛德（马修·麦康纳 Matthew McConaughey 饰）。玛德自称幼年时生活于此，因行动不便拜托埃斯利和奈克给予他帮助。家庭处于分崩离析边缘的埃利斯近于本能的信任玛德，向后者提供食物，并了解到玛德与青梅竹马恋人珍妮弗（瑞茜·威瑟斯彭 Reese Witherspoon 饰）痴缠多年并为之杀人的往事，原来玛德此刻在孤岛上正是躲避赏金猎人追杀的同时欲带走珍妮弗。埃利斯愿意相信玛德的爱情，尽管生活充满了令人失望的底色，他愿意助这位陌生的大朋友一臂之力……©豆瓣', '泰伊·谢里丹', '杰夫·尼克尔斯', 7.9, 19869, 'tt1935179', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1864210732.jpg', 0.3, 1.6, 22.9, 52.8, 22.4, '0.168431,-0.172343,-0.741723,0.547212,0.043308,-0.364675,0.640641,0.047950,-0.419207,-0.345227,-0.048345,0.629892,0.278615,0.306658,0.372324,-0.015954,-0.210261,-0.363106,-0.117773,-0.184045,-0.279505,-0.543207,-0.506937,-0.196414,-0.212996,-0.557088,0.442434,0.164668,-0.109343,0.686845,0.268772,0.511558,-0.272861,0.181697,0.003339,-0.247542,-0.026965,0.104674,-0.593197,0.088180,-0.213394,0.024833,0.158784,-0.007762,-0.006395,0.372335,0.485797,-0.388284,-0.300629,-0.023489,0.135873,-0.139996,0.290808,-0.027312,0.011681,-0.205848,-0.007892,0.003225,-0.177900,0.028490,0.188700,-0.148578,-0.449605,0.051872,-0.024579,0.059662,-0.421316,0.477828,-0.099911,-0.029344,0.024390,-0.252753,-0.018044,0.085643,0.124966,0.245365,-0.083598,0.102170,-0.227525,-0.001685,0.507527,0.150476,-0.033028,0.199418,-0.236561,-0.147079,0.051688,-0.131184,-0.502135,-0.117803,0.141817,0.211177,-0.014520,0.258150,-0.428834,0.012542,-0.175263,0.140557,0.141398,-0.272703,-0.277450,-0.507504,-0.073012,-0.308492,-0.022935,0.156642,0.066451,-0.410976,0.423808,-0.777511,0.338433,0.516957,0.398773,-0.357873,0.766389,0.045273,0.057696,-0.280892,-0.308624,0.487860,0.352845,-0.052386,0.031905,-0.076344,-0.167865,0.061133,-0.515018,0.368829', '3055049', '1291835', '1302384', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6803494', '极速风流', '剧情', '一直以来，尼基（丹尼尔·布鲁赫 Daniel Brühl 饰）和詹姆斯（克里斯·海姆斯沃斯 Chris Hemsworth 饰）都是针锋相对的死对头。尼基认真严肃，对赛车的职业十分尊重，詹姆斯喜欢铤而走险，将赛车作为自己寻花问柳的筹码，虽然两人有着截然不同的个性，但他们之间的较量却从未停止过。为了改变自己不够成熟的性格，詹姆斯和偶然遇见的名模苏西（奥利维亚·王尔德 Olivia Wilde 饰）结婚了，尼基亦找到了自己的一生挚爱并且加入了法拉利车队，而此时生活已经走上了下坡路的詹姆斯则加入了麦克拉伦车队，一对冤家再次站在了人生的战场之上。一次比赛中，天降大雨，尼基出了车祸身受重伤，詹姆斯因此夺得了冠军。可是，尼基并没有因此而放弃，在极短的时间内，尽管受到了众人的制止，但他依然毅然地回到了赛场上。©豆瓣', '克里斯·海姆斯沃斯', '朗·霍华德', 8.8, 138047, 'tt1979320', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2532780924.jpg', 0.1, 0.6, 9.3, 41.4, 48.5, '0.266973,0.109861,-0.727304,0.713851,-0.057639,-0.617028,0.748199,0.117167,-0.601823,-0.088355,0.374152,0.901939,-0.248132,0.043050,0.295138,-0.194299,-0.304957,-0.756923,-0.056547,-0.112968,-0.383976,-0.681038,-0.159590,0.030059,-0.260465,-0.260462,0.799628,0.102114,-0.056797,0.856495,0.430193,0.113237,0.288860,0.663381,-0.127420,-0.067403,-0.038842,0.091151,-0.193906,0.312807,0.146454,-0.162872,-0.325372,0.288377,0.252947,0.451002,0.534059,-0.437197,-0.053369,0.053714,0.204138,-0.316868,-0.058631,0.204682,0.257611,-0.039028,0.133899,0.275470,-0.078554,-0.009016,-0.096706,-0.015526,-0.628389,0.253141,-0.246235,0.031842,-0.758372,0.740967,-0.162311,-0.180605,-0.092253,-0.193320,0.183796,0.364736,0.432468,0.091088,-0.375454,-0.156530,-0.481246,-0.134006,0.833897,0.150879,-0.340914,0.468724,-0.388191,-0.378858,-0.209605,-0.372489,-0.574865,0.034087,0.402398,0.186707,0.005972,0.279392,-0.506769,0.108727,-0.266299,-0.191327,-0.060614,-0.427283,-0.080760,-0.668287,-0.170766,-0.607685,-0.388197,-0.007759,-0.293036,-0.290733,0.557952,-1.106396,0.249595,0.280222,0.226657,-0.462506,0.655340,0.036122,0.159400,-0.197104,-0.165125,0.447558,-0.106042,0.201851,0.181920,0.340519,-0.018166,-0.105939,-0.251662,0.757362', '35030151', '1301022', '21766698',