INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6811422', '变节：潜罪犯', '动作', '承接《潜行狙击》电视剧结局，梁笑棠Laughing（谢天华饰）谋杀苏星柏（黄宗泽饰）罪名成立，判处无期徒刑；梁笑棠在狱中结识大学教授霍天任（吴镇宇饰），教授外表斯文，与世无争，但却能以心理陷阱收服穷凶极恶的 “巨川”（林雪饰）。其实教授是高智商的犯罪心理学家，擅用冷读法，可以洞悉对方心理活动和秘密，于无声中掌控他人。神秘女子（文咏珊饰）到狱中探望梁笑棠，其隶属比警队更高层次的保安局，原来，梁笑棠入狱是再次担当卧底角色。当日，杀苏星柏是另有其人，保安局副局长（麦长青饰）怀疑整件事跟潜藏警队中的黑警团伙有关，所以借势令梁笑棠入狱展开调查。梁笑棠亦步亦趋主动接触狱中目标人物前毒品调查科警长“大切”（杜汶泽饰）在将要取得进展时，发现教授亦同时以心理治疗法，令“大切”多次精神错乱，直至向“大切”发出了死亡暗示。一场敌友难分、正义与邪恶的生死对决在实力极不均衡的态势下火爆展开了。', '谢天华', '邱礼涛', 6.1, 30639, 'tt2186875', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1337270489.jpg', 3.6, 18.7, 52.6, 19.1, 6, '0.039460,-0.029651,-0.320146,0.382510,-0.000015,0.196752,0.369223,0.147508,-0.504283,-0.255150,0.311678,0.242408,-0.110061,-0.179800,0.232577,-0.333535,-0.193626,-0.704974,0.005167,-0.154933,-0.209555,-0.613340,-0.427980,-0.047761,-0.045128,-0.328497,0.460783,0.013801,-0.456030,0.209058,0.254311,0.609998,-0.339419,0.220343,0.096228,-0.375876,0.139930,-0.156805,-0.625952,0.114851,0.058725,-0.369339,-0.226632,-0.019145,-0.089218,0.350572,0.513306,-0.210439,-0.351025,-0.248574,0.402760,-0.245990,-0.305350,0.149645,0.412896,0.267667,0.191074,0.513110,0.090231,0.062393,-0.029389,0.023041,-0.618573,0.013415,0.281374,0.146334,-0.050020,-0.001431,-0.269596,0.166036,0.002619,-0.185306,0.088639,-0.020110,0.343497,0.136476,0.088564,-0.028175,-0.290361,-0.034565,0.500134,0.078853,-0.265120,0.067351,-0.051396,-0.498565,0.029200,-0.347351,0.064078,0.056070,0.174510,-0.041081,0.086667,0.331791,-0.206896,-0.111215,-0.140708,0.473395,-0.289942,-0.286115,0.017066,-0.393220,-0.444861,-0.217851,-0.122511,0.062125,0.073697,-0.450688,0.323951,-0.764783,0.049351,0.440503,0.165402,-0.467131,0.339764,0.086547,0.005183,-0.272685,-0.131888,0.016887,0.170531,0.198249,-0.018374,0.205626,-0.051781,-0.407302,-0.156412,-0.027641', '1293265', '3