INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6814906', '致亲爱的你', '剧情', '在富山监狱担任技术指导官员的仓岛英二（高仓健 饰）新近丧妻，妻子洋子（田中裕子 饰）的音容笑貌和曼妙歌喉时时盘桓心头，令他难以忘怀。这天他收到洋子生前寄来的绘信，叮嘱丈夫将自己的骨灰撒在故乡长崎薄香的海里。抱持着心间种种疑问，仓岛驾车踏上旅途。一路上他结识了自称新近丧妻的国文教师（北野武 饰）、开朗的车站便当推销员田宫（草剪刚 饰）及其沉默寡言的下属南原（佐藤浩市 饰）、薄香当地经营餐馆的母女（余贵美子 & 绫濑遥 饰）、老渔夫大浦吾郎（大泷秀治 饰）及其孙子（山浦贵大 饰），交织着与妻子相守时分的点点滴滴，仓岛终于抵达旅途的终点……本片荣获第36届日本电影金像奖最佳男配角奖（大泷秀治）和最佳女配角奖（余贵美子），该片也是大泷先生的遗作。©豆瓣', '高仓健', '降旗康男', 8.2, 12322, 'tt2034618', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1861030042.jpg', 0.2, 0.9, 16.5, 51.4, 31, '-0.203099,-0.235188,-0.528898,0.433423,0.327812,-0.349706,0.407779,0.356667,-0.482596,-0.266674,0.330877,0.848356,-0.121633,0.302864,0.383307,0.090069,-0.250809,-0.611471,-0.244516,-0.134576,0.109469,-0.258970,-0.041681,0.222368,-0.233567,-0.190883,0.506376,-0.154310,0.055632,0.579918,0.449424,0.362681,-0.327400,-0.159460,-0.094625,0.189922,0.230416,0.052650,-0.292673,0.111397,-0.238275,-0.202551,-0.165139,-0.211419,0.259927,0.263948,0.893684,0.038524,-0.145513,-0.103662,0.296695,-0.063254,-0.160539,0.076538,0.196225,0.151694,0.114179,0.234197,-0.296658,0.025087,0.036049,-0.065435,-0.116167,0.042821,0.248554,0.015486,-0.434075,0.234395,-0.135728,-0.178907,0.263153,-0.282559,0.076088,0.023813,0.144406,0.128501,-0.159985,0.201194,0.031594,0.662939,0.399333,0.075869,0.106140,0.141435,-0.206006,-0.422021,-0.108872,-0.037164,-0.533967,-0.111546,0.080163,0.126464,0.092281,0.151239,-0.409981,-0.041252,-0.222802,0.102580,0.332664,0.008632,-0.112533,-0.704632,0.041627,-0.492169,-0.086990,0.240470,0.443005,-0.024974,0.822424,-0.432574,0.143597,0.401306,0.054964,-0.174402,0.478279,0.168628,-0.049334,-0.262153,0.002160,0.229953,-0.053660,0.181146,0.068709,0.300308,-0.478351,-0.139275,-0.447602,0.004270', '3811356', '5403927', '1908036', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6827727', '女性瘾者：第一部', '剧情', '一个大雪纷飞的寒冷夜晚，学者赛里格曼（斯特兰·斯卡斯加德 Stellan Skarsgård 饰）偶遇了遍体鳞伤躺在雪地里的女子乔伊（夏洛特·甘斯布 Charlotte Gainsbourg 饰），好心的赛里格曼将乔伊接回家里疗养，却没想到，等待着他的，会是一个充满了扭 曲情欲的故事。影片随着乔伊的讲述徐徐展开，年纪很小的时候，乔伊（斯黛茜·马汀 Stacy Martin 饰）就发现了自己拥有异于常人的高涨性欲，年幼的无知和懵懂让乔伊欣然接受了自己的不同，随着年龄的增长，她开始大胆又奔放的徜徉在情欲之海中，甚至和好友一起创办了专门接纳“女性瘾者”的俱乐部。乔伊的第一个男人名叫杰罗姆（希亚·拉博夫 Shia LaBeouf 饰），当成年后的乔伊再度遇见杰罗姆之时，她发现自己竟然深深地爱上了他，而悲剧的是，乔伊发现，唯独杰罗姆的爱抚无法燃起她的激情，在性和爱之间，乔伊陷入了深深的迷惘之中。', '夏洛特·甘斯布', '拉斯·冯·提尔', 7.9, 103689, 'tt1937390', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2151633260.jpg', 0.6, 2.5, 24, 47.2, 25.7, '0.351560,0.257449,-0.992591,0.609543,-0.183938,-0.379130,1.044484,0.084643,-0.506321,-0.092680,-0.019561,0.922694,-0.410999,0.427746,0.342223,0.134990,-0.179939,-0.835801,-0.301020,-0.022088,-0.336639,-0.569132,-0.332213,-0.045216,0.006138,-0.487911,0.406758,-0.023764,-0.309033,0.633641,0.252156,0.460384,0.107176,0.539684,-0.124354,0.072066,0.237651,0.048544,0.068218,0.208149,0.201448,-0.233367,-0.138249,0.109710,-0.105479,0.467214,0.876289,-0.445068,0.016857,-0.041610,0.396270,-0.090369,-0.114478,0.040899,0.062927,-0.068065,0.118032,-0.011228,-0.165925,-0.011570,0.070868,-0.108922,-0.525345,0.182966,0.112012,0.200394,-0.627354,0.557653,0.033566,-0.011669,0.147600,-0.241316,0.074152,0.121166,0.107225,0.455980,-0.051808,-0.172003,-0.356893,0.017653,0.406115,0.252659,-0.353804,0.543202,-0.604611,-0.501672,-0.023363,-0.092402,-0.582073,-0.267263,0.349679,0.235684,-0.190893,0.391582,-0.565344,-0.040342,-0.264954,-0.109690,-0.138370,-0.344645,-0.264895,-0.498573,-0.295884,-0.573038,-0.274155,0.204010,-0.115308,-0.252875,0.627814,-0.958698,0.427253,0.532501,0.115386,-0.169361,0.675404,0.024513,0.025066,0.048342,-0.111562,0.526922,-0.211242,0.034813,0.266253,0.465380,-0.178900,0.089673,-0.665426,0.611037', '1296534', '3111650', '1309172', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6828823', '重返地球', '动作', '未来世界，愚蠢的人类文明令地球环境日趋恶化，温暖甜蜜的家乡变成充满灾难和死亡人间炼狱。此后，人类穿越太空在首新星建立新的家园，而外星人操控的怪兽厄萨对这群外来者展开残酷屠杀，人称“原鬼”的游骑兵最高指挥官塞弗·瑞奇（威尔·史密斯 Will Smith 饰）带领手下有效阻止了敌人的屠戮。虽说虎父无犬子，但塞弗的儿子基泰（贾登·史密斯 Jaden Smith 饰）却在游骑兵测验中失利。内心存在隔阂的瑞奇启程前往伊菲图斯训练基地，谁知途中突发变故被迫降落在熟悉而陌生的地球。剧烈的冲撞几乎让船员全数死亡，瑞奇父子则成为仅有的幸存者。在父亲重伤的情况下，基泰只能独自去寻找赖以求生的信号机。对于这个始终长不大的孩子来说，他将面临人生中最重要的一次考验……©豆瓣', '威尔·史密斯', 'M·奈特·沙马兰', 5.7, 75768, 'tt1815862', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1906782732.jpg', 6.6, 25.9, 49, 14, 4.6, '0.093958,0.023870,-0.755929,0.470060,0.004435,0.025382,0.728081,0.127005,-0.570863,-0.135650,0.519869,0.582023,0.274289,-0.023653,0.307068,-0.163363,-0.247379,-0.342654,-0.174225,0.035576,-0.391036,-0.367422,-0.408122,-0.381356,0.107296,-0.584733,0.833044,0.376789,-0.344652,0.340231,0.031653,0.474862,-0.178980,0.438066,-0.143482,-0.137318,0.157505,-0.040173,-0.580576,0.295126,-0.209715,0.035450,-0.075462,0.271831,-0.199238,0.331108,0.749729,-0.642157,-0.055512,-0.355335,0.347143,-0.495585,-0.230664,-0.049640,0.361947,0.066018,-0.143755,0.112117,0.079960,0.006358,-0.056939,0.023001,-0.817198,-0.061573,0.159161,0.059157,-0.396314,0.390283,0.042887,-0.028211,0.245371,-0.136654,0.223504,0.428295,0.264129,0.484121,-0.290035,0.152001,-0.285321,-0.065685,0.764961,-0.159546,-0.534718,0.077714,-0.344151,-0.471963,-0.061288,-0.456676,-0.515006,-0.131601,0.101921,0.258572,-0.133597,0.665511,-0.559334,0.325237,-0.401613,-0.259867,0.002435,-0.381134,-0.268795,-0.644567,-0.056317,-0.086333,-0.185754,0.190335,0.057528,-0.134119,0.772136,-0.638332,0.327114,0.609656,0.314982,-0.409493,0.436508,0.217479,0.252173,-0.458187,-0.109971,0.757985,0.016183,0.449991,-0.084934,0.014932,-0.224387,0.125444,-0.216615,0.510242', '26667010', '3001114', '1578502', '4889554');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6829652', '女朋友，男朋友', '剧情', '1985年高雄的夏天，充满着玉兰花的香味，也洋溢着青春的躁动。尚未开放的台湾校园，教官一人独大。没有民主与自由可言的学校，压制不住王心仁（凤小岳 饰）逆反的心，写藏头诗，策划集体抗议舞会。和他一起无法无天的还有陈忠良（张孝全 饰）和林美宝（桂纶镁 饰）。经常腻在一起的三人，爱情也在悄无声息地滋长。木讷的忠良读不懂美宝的暗示；心仁则积极地追求美宝；而最早交女友的忠良却困惑了。1990年的台北。风起云涌的学潮运动，少不了阿仁的身影，而阿良则做着阿仁最好的观众。和阿仁成为男女朋友的美宝则时不时从家乡来台北，三人依旧亲密无间。一场盛大的学生集会引起了警方的注意，也冲垮了三人的维系。阿良选择跨出了城墙；阿仁抵不住外在诱惑；将这一切看在眼里的美宝，已无法选择无视。踏入社会，多年不联系的他们再次有了交集。曾经的好友恋人，现在各自有了新的身份加诸身上。为爱自讨苦吃的他们最终能否重拾勇气，回到1985年那个如梦如幻的家乡。', '桂纶镁', '杨雅喆', 7.5, 159822, 'tt2319760', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1578950461.jpg', 0.6, 3.4, 32.7, 46.2, 17.1, '0.502204,-0.198710,-0.721648,0.655965,-0.032478,-0.355049,0.660003,0.196236,-0.383973,-0.087642,0.066860,0.494852,-0.131748,0.233543,0.202245,-0.197730,-0.199943,-0.841398,-0.183571,-0.079815,-0.128610,-0.458291,-0.070351,-0.124674,-0.192371,-0.140665,0.609453,0.156642,-0.118425,0.716822,0.446746,0.001180,0.091449,0.426675,-0.120031,-0.041903,-0.011003,0.254618,-0.378797,0.140663,0.108177,-0.401837,-0.323178,0.149935,0.021729,0.272491,0.675143,-0.150600,-0.010225,0.000252,0.359228,-0.192786,-0.050905,0.221265,0.238732,-0.049840,0.079600,0.316094,-0.217150,0.013108,0.103131,0.085645,-0.771245,-0.047460,0.233469,0.167822,-0.447036,0.861076,0.071572,-0.106044,0.140342,-0.326477,0.183203,0.454868,0.140915,0.457627,-0.252746,-0.023225,-0.417641,0.199425,0.670911,0.068356,-0.290839,0.235089,-0.517182,-0.258360,-0.015971,-0.110983,-0.489683,-0.207510,0.107707,0.358519,-0.194612,0.260615,-0.636068,-0.031384,0.090631,-0.242091,0.122701,-0.555940,-0.134279,-0.565850,-0.361135,-0.611894,-0.188542,0.184368,0.038519,-0.111438,0.754241,-1.008351,0.181670,0.450473,0.387907,-0.488116,0.781124,0.228436,-0.090252,-0.241523,-0.192145,0.091222,-0.214198,0.389723,0.304286,0.440553,-0.093854,-0.024124,-0.338072,