INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6829665', '断箭', '剧情', '金庆浩（安圣基 饰）本是一名大学的数学教授，却因为直言指出大学入学考试中一道出错的考题间接被学校停职。为此金庆浩多次申诉，希望能恢复自己的职位和名誉，却屡告失败。金庆浩由此心灰意冷离开韩国，在海外进行学术研究直至2006年他回国，再次向韩国高等法院提出诉讼，要求校方恢复他的职称但被判败诉。此时的金庆浩到了极度愤怒的状态，失去理智的他埋伏在案件主审法官的公寓楼道里，预备用石弓袭击法官。法官受伤入院，金庆浩被捕，在媒体的关注下，此次事件被上升为“司法恐怖袭击”。但金京浩对所有指控拒不承认，在他奋力抗争的过程中，这次“弓弩伤人事件”也愈发的扑朔迷离……电影《断箭》根据2007年在韩国轰动一时的“弓弩伤人事件”改编。©豆瓣', '安圣基', '郑智泳', 7.8, 15134, 'tt2085765', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1381094562.jpg', 0.4, 1.8, 24.7, 51.6, 21.5, '0.180637,0.115825,-0.512524,0.582610,0.044292,-0.119482,0.659877,0.074050,-0.461149,-0.287316,0.404843,0.513797,-0.317347,0.180783,0.129807,-0.414845,-0.117646,-0.809738,0.091383,-0.057312,-0.282662,-0.622419,-0.065543,-0.183224,-0.325289,-0.218461,0.789546,0.203246,-0.416906,0.490857,0.094141,0.384371,0.199825,0.434788,0.078877,-0.166524,0.109670,-0.090041,-0.201361,0.281332,0.283598,-0.637804,-0.289592,0.284879,0.099890,0.545322,0.777157,0.069469,-0.351145,0.035690,0.691770,-0.625623,-0.129581,0.430371,0.657841,0.449820,-0.113888,0.518449,-0.327129,0.094748,-0.200783,-0.037835,-0.593691,-0.228167,-0.041558,0.201920,-0.404095,0.457005,-0.360952,0.255281,-0.138254,-0.252697,0.017112,0.315388,0.107022,0.393263,-0.323188,0.016065,-0.359589,0.327876,0.618969,-0.113258,-0.346574,-0.109901,-0.189536,-0.600267,-0.014536,-0.206295,-0.063772,0.072981,0.285134,-0.134443,-0.241411,0.404415,-0.290046,-0.219303,-0.309891,-0.327259,-0.313711,-0.190883,-0.098583,-0.648955,-0.084472,-0.005628,-0.433114,-0.127009,0.029454,-0.181494,0.452935,-0.802990,0.193903,0.475593,0.279704,-0.520533,0.444262,0.321023,0.153547,0.024452,-0.247776,0.078880,0.050218,0.440669,0.111003,0.113063,0.084353,-0.456171,-0.308902,0.326216', '4202326', '3263169', '25723905', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6832334', '送报男孩', '剧情', '佛罗里达州的一个小镇上，Hillary Van Wetter（约翰·库萨克 John Cusack 饰）被指控谋杀了一个警察，被判处死刑。迈阿密时报的记者Ward Jansen（马修·麦康纳 Matthew McConaughey 饰）觉得事有蹊跷，Hillary可能不是真的凶手，便和从伦敦来的另一名记者，Yardley Acheman（大卫·奥伊罗 David Oyelowo 饰）对案件展开调查。Ward年轻的弟弟Jack Jansen（扎克·埃夫隆 Zac Efron饰），退役的游泳选手，则成为了他们的司机。Charlotte Bless（妮可·基德曼 Nicole Kidman饰）喜欢给监狱里的人写信，这一次，她爱上了Hillary，两人频繁通信。于是Ward和Yardley找到了Charlotte，让她协助调查。几人开始频繁地去监狱探访Hillary，而同时，处于青春期的Jack则对性感火辣的Charlotte产生了狂热的爱恋。后来调查结束，Hillary被无罪释放，从Jack身边带走了Charlotte回到他在森林中的家，而Charlotte则开始发现，这并不是她想要的生活，然而Hillary却不会再让她离开.....本片改编自美国小说家Pete Dexter 的小说。', '马修·麦康纳', '李·丹尼尔斯', 6.2, 6766, 'tt1496422', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1656243048.jpg', 2.7, 16.7, 53.6, 21.4, 5.5, '0.637218,-0.059356,-0.838607,0.746021,-0.172484,-0.263188,0.909679,0.018730,-0.613344,-0.131517,0.034630,0.859351,-0.214616,0.284616,0.237797,0.100646,-0.534490,-0.817854,-0.148802,-0.274116,-0.525678,-0.470993,-0.087970,-0.337601,0.124211,-0.210602,0.408978,0.129942,-0.283965,0.650392,0.437530,0.487699,0.107482,0.535494,-0.028254,0.043190,0.224342,-0.052893,-0.102677,0.434909,0.248103,-0.355371,-0.050491,0.231386,0.129191,0.458970,0.710317,-0.082488,-0.195845,-0.062247,0.434797,-0.381335,0.094544,0.194406,0.347405,0.152474,0.202954,0.176219,-0.357624,0.033062,-0.004070,-0.054915,-0.773713,0.310065,0.060743,0.238905,-0.457251,0.269933,-0.322825,-0.059196,0.018903,-0.273894,0.315565,0.311210,0.206903,0.255494,0.053844,0.011286,-0.471239,0.191368,0.688200,-0.050450,-0.020527,0.180138,-0.014363,-0.534834,-0.057879,-0.042301,-0.355800,-0.033909,0.500778,-0.003818,-0.194302,0.069782,-0.519177,-0.074296,-0.300717,-0.312098,-0.192807,-0.333352,-0.151290,-0.548306,-0.039981,-0.286331,-0.406225,0.053378,-0.039068,-0.117604,0.537496,-0.787434,0.323930,0.838883,0.423561,-0.656261,0.737790,0.052864,0.004251,-0.216889,-0.067705,0.237111,0.289663,0.377763,0.372586,0.429089,-0.073544,-0.422044,-0.488129,0.359366', '1947080', '3055049', '1300958', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6837235', '妈妈', '恐怖', '一对女孩维多利亚·迪桑（梅根·查彭提尔 Megan Charpentier饰）和莉莉·迪桑（伊莎贝尔·内利瑟 Isabelle Nélisse饰）的母亲被他们的父亲所杀，父亲也随即自杀并将两个女儿遗弃在树林里。五年后，她们被发现时状况极差，孤独、饥饿，她们对一切的肢体接触都会感到恐惧和抗拒，没人知道她们是如何在如此孤独的环境中存活的。叔叔卢卡斯（尼可拉·科斯特-瓦尔道 Nikolaj Coster-Waldau饰）和女友安娜贝尔（杰西卡·查斯坦 Jessica Chastain饰）收养了她们，原本平静的生活就此打破。黑暗中，总有一个如影随形的亡魂，而这个想要置他们于死地的鬼魂，两个女孩叫她：妈妈。本部影片是西班牙导演安德斯·穆斯切蒂的长片处女作，翻拍自他2008年拍摄的同名短片。©豆瓣', '杰西卡·查斯坦', '安德斯·穆斯切蒂', 6.8, 37864, 'tt2023587', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1867314088.jpg', 1.1, 7.8, 48, 34.1, 9, '0.208689,-0.275527,-0.645074,0.537459,-0.139249,-0.346173,1.001809,0.110019,-0.585233,-0.377354,0.073904,0.936101,-0.214784,0.259623,0.165755,0.260777,-0.448056,-0.692712,-0.037381,-0.195682,-0.178027,-0.456963,-0.286808,-0.289291,-0.113483,-0.192367,0.511667,-0.313621,-0.024148,0.446239,0.243010,0.391389,-0.120039,0.497996,-0.044026,0.258288,-0.083453,-0.209441,-0.297766,0.173033,-0.014586,-0.126091,-0.138940,0.077923,-0.077333,0.358829,0.622220,-0.439897,0.131653,-0.142310,0.283514,-0.171014,-0.085357,0.234330,0.132005,-0.324991,0.379030,0.114228,-0.388813,-0.166767,0.170443,0.106656,-0.501936,0.226584,0.021849,0.331187,-0.519577,0.349050,0.019540,-0.123532,0.268243,-0.298379,0.220233,0.262621,0.244978,0.426386,-0.098962,-0.271576,-0.387156,0.085414,0.614937,-0.276891,-0.279672,0.354558,-0.217319,-0.417874,-0.054097,-0.063400,-0.696530,0.125733,0.229974,0.104373,-0.181614,0.331036,-0.556861,-0.054327,-0.272822,-0.072171,-0.389705,-0.502601,-0.091954,-0.518082,-0.278771,-0.367628,-0.357654,-0.146132,-0.126197,-0.101315,0.582447,-0.788594,0.333949,0.384975,0.428346,-0.389943,0.589953,0.233900,0.181067,-0.071397,0.084377,0.479617,0.128726,0.024138,0.292824,0.368297,0.097764,0.187611,-0.271830,0.436387', '1296534', '4275444', '3111650', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6839145', '铁线虫入侵', '剧情', '制药公司小职员医学博士出身的宰赫（金明民 饰）早些年被弟弟宰弼（金烔完 饰）劝诱炒股，结果赔得精光，如今委身于一家毫无前景的制药公司做推销员，在外低声下气，看客户脸色行事，心中的郁结只有向家中妻儿宣泄。与此同时，汉江流域附近接连发现数十具尸体，死者全身皆如干尸，死状恐怖。这一事件波及甚广，连宰赫身边的人也无法幸免。经调查发现，死者体内无一例外寄居着本应存在于昆虫身上的铁线虫，铁线虫会刺激宿主食欲大增以吸收养分，等到繁殖期时令宿主神志不清，投水自杀，再进入水中大量繁殖。面对这一新型变种，人类束手无策，无计可施，死亡人数呈几何数增加，韩国上下乱作一团，有如末日。原本为生计奔忙已焦头烂额的宰赫，该如何保护家人幸免于难……©豆瓣', '金明民', '朴正祐', 6.8, 76496, 'tt2173024', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1588680264.jpg', 1.4, 7.9, 47.9, 33.2, 9.7, '-0.398489,-0.151302,-0.375332,-0.067744,0.373754,-0.152325,0.581537,0.085252,-0.527620,-0.370192,-0.074369,0.288776,-0.204847,0.141896,0.009875,-0.381778,0.002100,-0.221185,-0.385081,0.005298,-0.216812,0.007151,-0.245236,-0.218469,-0.200347,-0.182516,0.479608,0.163124,-0.125688,0.290471,0.041830,0.470178,-0.259327,0.118103,0.254334,-0.245462,-0.350810,-0.204742,-0.150797,0.032784,-0.000408,-0.273349,0.084554,-0.204443,0.084866,0.332873,0.705466,-0.174946,-0.308418,-0.751941,0.599802,-0.164247,0.112775,0.096396,0.337750,0.212155,0.372850,-0.100198,-0.114318,-0.048823,0.246476,0.018548,-0.687065,-0.244247,0.250424,0.091129,-0.265403,-0.113093,0.150486,-0.008096,-0.162652,-0.407151,0.079224,0.092272,0.075692,0.455130,-0.342308,-0.022703,-0.502774,0.076392,0.537548,0.089200,-0.372759,-0.042093,-0.057672,-0.300171,0.088263,-0.541306,0.048574,-0.063063,-0.010631,0.680311,-0.134207,0.367739,-0.284071,0.018880,-0.207289,-0.340958,-0.131397,0.176096,-0.136955,-0.525501,-0.091672,0.045062,-0.182939,0.190410,0.307553,-0.190271,0.464432,-0.332715,0.160283,0.297031,0.441655,-0.486658,0.195715,-0.331027,0.209356,0.041856,-0.097410,0.128775,0.243144,0.363607,0.243674,-0.224810,-0.169810,-0.167166,-0.225670,-0.064585', '5364978', '1292523', '2265778', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6843843', '锈与骨', '剧情', '貌不惊人的阿里（马提亚斯·修奈尔 Matthias Schoenaerts 饰）曾经是一名风光无限的搏击选手，自从受伤之后他便失去了生活保障。穷困潦倒之际，他带着儿子山姆（Armand Verdure 饰）投靠姐姐，并在当地找到一份保镖的工作。某晚，阿里结识因别人发生争 执的美丽女子斯蒂芬妮（玛丽昂·歌迪亚 Marion Cotillard 饰）。斯蒂芬妮是一名虎鲸训练师，然而这个衣食无忧、日常为光环所环绕的女孩却在一次例行表演中被虎鲸夺去双腿。经历了不同人生的男女，彼此的命运意外交叠在了一起……本片根据加拿大小说家克雷格·戴维森（Craig Davidson）的同名短篇小说集改编，荣获2012年西班牙瓦拉多利德国际电影节最佳男主角奖（Matthias Schoenaerts）、最佳导演奖和最佳剧本奖。©豆瓣', '马提亚斯·修奈尔', '雅克·欧迪亚', 7.6, 26543, 'tt2053425', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1766507291.jpg', 0.3, 2, 29.9, 51.5, 16.3, '0.037416,-0.141814,-0.529659,0.620339,0.050113,-0.509907,0.528611,0.041530,-0.400907,-0.263976,0.191732,0.845743,-0.314373,0.076277,0.537350,-0.054228,-0.348999,-0.779632,0.078969,-0.148468,0.028802,-0.325035,-0.336779,0.007659,-0.254906,-0.589768,0.903451,-0.359245,-0.057826,0.493711,0.438691,0.212526,-0.154719,0.057960,-0.131912,0.058516,0.337325,-0.182166,-0.435672,0.346542,-0.058571,-0.225056,-0.127142,-0.047852,0.146035,0.244022,0.912864,-0.320929,0.034721,-0.171404,0.495468,-0.051709,0.053066,-0.134778,0.186525,-0.166231,0.184417,0.112477,-0.056060,-0.013448,0.159096,-0.283661,-0.515620,-0.097631,0.301120,0.277868,-0.442386,0.507132,-0.068128,0.044385,0.008153,-0.005061,0.104999,0.361814,0.214551,0.138525,0.102389,0.062876,-0.188410,0.590322,0.581826,0.011398,-0.231545,0.266176,-0.398716,-0.604797,-0.099168,-0.197448,-0.638615,0.071865,0.280141,-0.005453,0.128711,0.193100,-0.390491,-0.006104,-0.248998,-0.043581,-0.046735,-0.244135,0.132667,-0.756332,-0.009828,-0.385601,-0.331542,-0.001553,0.216364,-0.316775,0.549518,-0.777572,0.281068,0.575699,0.187274,-0.038931,0.656292,0.000881,0.289776,-0.325707,-0.248659,0.341774,-0.052969,-0.035292,0.063097,0.332360,-0.066711,-0.005216,-0.215328,0.472983', '1780122', '3811356', '34795703', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6844861', '命运石之门剧场版：负荷领域的既视感', '动画', '这是又一部关于时间、空间和人性的哲学命题动画。日本动画所特有的那种创造离奇而宏大世界观的做法，在本作中再次得到淋漓尽致的体现。如果你是一个逻辑能力较弱的人，或许真的很难看懂影片中关于时间线的种种匪夷所思的设定，但是你依然能体会当人类通过时间机器穿越时空时所带来的种种伦理难题。“命运石之门”起始于2009年的一款游戏，后被改编为电视动画，今年推出了这部剧场版。', '宫野真守', '佐藤卓哉', 8.9, 17233, 'tt2967286', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1957382613.jpg', 0.4, 1.2, 10.1, 31.2, 57.1, '0.060962,0.336693,-0.450706,0.898449,0.123074,0.127652,0.495022,-0.385088,-0.618319,-0.352767,-0.301047,0.590436,-0.111201,0.094269,0.360118,-0.084972,-0.505521,-0.456934,-0.122094,-0.331240,-0.340563,-0.363056,-0.382705,-0.103751,-0.042353,-0.513109,0.898062,0.149510,-0.655613,0.025081,0.131726,0.188798,-0.136671,0.202994,-0.067872,0.074936,0.013115,0.229987,-0.203492,0.108140,0.235381,-0.088163,-0.082211,0.373157,-0.517056,0.135108,0.636364,-0.487745,-0.572136,-0.095322,1.035283,0.012621,-0.295571,-0.178299,-0.115403,0.257217,0.284978,0.309455,0.074344,0.331668,-0.141452,-0.233758,-1.664322,-0.219737,0.044938,-0.079614,-0.035966,0.218052,-0.100371,-0.155485,0.018745,-0.229197,0.077866,0.146361,1.130354,0.511720,-0.550265,-0.234135,-0.337566,0.529589,0.515456,-0.035310,-0.711119,0.920347,-0.404408,-0.425899,-0.339945,-0.299199,-0.169211,0.354352,0.168712,0.102847,-0.267820,0.306554,-0.594400,0.181020,0.044043,-0.358496,-0.020911,-0.424828,0.053313,-0.541364,-0.436936,-0.355336,-0.074137,-0.288925,0.304045,-0.593754,0.920774,-0.651162,-0.001764,0.471204,-0.016403,-0.343224,0.643093,0.037585,-0.129000,-0.318742,-0.046603,-0.005123,-0.168042,0.159183,-0.202673,0.524615,0.469911,-0.491217,-0.467943,0.850918', '27098364', '27602116', '35280911', '26848640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6844868', '狼少年', '爱情', '因为体弱多病的顺伊（朴宝英 Bo-yeong Park 饰）需要疗养的缘故，顺伊母女三人从首尔搬家到了乡下的一栋别墅生活。而收拾屋子的时候顺伊意外的在仓库发现了神秘的前户主朴博士在这里遗留下了的狼孩（宋仲基 Joong-ki Song 饰）。顺伊妈妈出于善心收留了这个狼性未泯的男孩，并给他起名叫哲秀，就这样四个人开始了同住一个屋檐下的生活。顺伊起初反感这个不会说话，吃饭狼吞虎咽的闯入者，然而朝夕相处让顺伊萌生了照顾训练哲秀的念头。她开始教给他吃饭，读书，认字，还弹奏吉他给狼孩听，而哲秀对顺伊温暖的关怀十分受用，认真的做着顺伊教授给自己的东西。孤独的顺伊因为哲秀渐渐融入到自己的世界中而开心起来，对他产生了别样的爱恋。但是这份美好却被对狼孩虎视眈眈的智泰（刘延锡 Yeon-Seok Yoo 饰）打破，他一门心思的集结挑拨多方势力来捕杀哲秀。顺伊为了保护哲秀，不得不面临着与所爱的人分离的现实。该片为导演赵成熙的首部商业电影处女作。', '宋仲基', '赵圣熙', 8, 243023, 'tt2315152', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2159648145.jpg', 0.6, 2.4, 21.2, 45.5, 30.3, '0.403125,-0.014734,-0.880355,0.537236,-0.396318,-0.367982,0.929697,0.328433,-0.494229,-0.404756,0.278288,0.610151,0.147841,0.489566,0.138287,0.150829,-0.324090,-0.465235,0.046710,0.123052,-0.186819,-0.355963,0.037209,-0.296676,-0.078596,-0.337527,0.349032,0.174443,-0.199260,0.342390,0.100469,0.111509,0.071780,0.473686,-0.144877,0.095141,-0.079912,0.167067,-0.086717,0.068498,0.138356,-0.174326,-0.265744,0.255343,-0.200685,0.354998,0.777544,-0.101835,-0.308395,-0.112248,0.301933,-0.356276,-0.080785,0.008798,0.338237,0.168396,0.131834,-0.046884,-0.312346,0.267050,0.005932,-0.144961,-0.652113,-0.109240,0.146401,0.073025,-0.624336,0.581328,0.112564,-0.131559,0.198367,-0.357325,0.209302,0.317490,0.084584,0.446231,-0.481167,0.230518,-0.351485,0.174683,0.491171,-0.409800,-0.077647,0.564495,-0.462868,-0.464105,0.136419,-0.229291,-0.709534,-0.195538,0.042670,0.101248,-0.347013,-0.107802,-0.701219,-0.089275,-0.020759,-0.320427,0.073914,-0.626118,-0.070531,-0.389437,-0.288954,-0.358757,-0.261533,0.160919,0.067228,-0.355246,0.733747,-0.908293,0.365515,0.659076,0.310876,-0.542714,0.449615,0.025038,-0.041844,-0.146024,-0.175248,0.207265,0.104342,0.360841,0.208828,0.432358,0.016645,-0.020283,-0.629054,