INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6845667', '秘密特工', '喜剧', '故事发生在1963年的德国，时值冷战期间，德国女汽车技师嘉比（艾丽西亚·维坎德 Alicia Vikander 饰）的父亲是一位精通核武器的专家，最近，有证据表明他正在帮助纳粹制造核武器，来达到统一全人类的邪恶野望。拿破仑（亨利·卡维尔 Henry Cavill 饰） 是CIA的特工，他曾经犯过的错误让他的仕途岌岌可危，他必须做出点成绩来证明自己并非无用之才。伊利亚（艾米·汉莫 Armie Hammer 饰）是苏联国家安全委员会特工，他的父亲被政府打上了贪污分子的烙印，为了摆脱父亲带给自己的不良影响，伊利亚必须比其他人更加努力。这样的两个人都想要赶在对方之前将核弹大师捉拿归案。©豆瓣', '亨利·卡维尔', '盖·里奇', 8.1, 154839, 'tt1638355', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2251290212.jpg', 0.3, 1.7, 19.6, 49.8, 28.6, '0.108684,-0.066152,-0.569120,0.542660,-0.249812,0.051533,0.465638,-0.125949,-0.566551,-0.174342,0.373567,0.657586,0.120710,-0.104683,0.115926,-0.055942,-0.306074,-0.614948,0.156046,-0.118633,-0.264526,-0.753526,-0.312757,-0.352144,-0.262881,-0.495213,0.617143,-0.041052,-0.348520,-0.142394,0.099092,0.487792,0.418531,0.360507,-0.126572,-0.023809,0.140309,-0.410970,-0.311041,0.152847,0.271427,-0.222389,-0.082868,0.509727,-0.098147,0.300007,0.345749,-0.312608,-0.029163,-0.221747,0.405947,-0.382376,-0.050857,0.030222,0.302170,0.104983,-0.138673,0.433397,0.030815,-0.034857,0.257808,0.017284,-0.868327,-0.199887,0.192677,0.088523,-0.577814,0.302731,-0.424938,0.094201,0.210123,-0.319298,0.130697,0.408446,0.181622,0.104259,-0.163980,0.032297,-0.690803,0.292001,0.685314,0.060010,-0.189675,0.126244,-0.545303,-0.355225,-0.103670,-0.431620,-0.364748,0.203666,0.270899,-0.340240,-0.078070,0.340415,-0.373070,-0.298825,-0.479193,-0.230033,0.021718,-0.362932,0.033882,-0.458659,-0.121468,-0.300347,-0.363129,0.058373,0.151589,-0.404343,0.706631,-0.753458,0.044596,0.804666,0.282973,-0.545664,0.471015,-0.010179,-0.032639,-0.236063,-0.310023,0.273947,0.142496,0.405926,-0.021744,0.184298,0.440298,-0.195196,0.032318,0.352665', '30163500', '1793491', '27009869', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6846893', '超能查派', '动作', '故事发生在2016年的南非约翰内斯堡，为了应对不断攀升的犯罪率，某大型武器公司开发了全机械警察部队。他们将机械警察批量生产并投入使用，在打击犯罪方面取得了令人瞩目的效果。作为开发人员之一，程序员迪恩（戴夫·帕特尔 Dev Patel 饰）一直致力于制造出完全的人工智能机器人。直到某天，他的研究取得突破性进展，可是并未得到老板米歇尔·布莱德利（西格妮·韦弗 Sigourney Weaver 饰）的支持。不甘心失败的迪恩偷偷将一台不久前被打坏的机械警察带出公司，准备完善他的研究，谁知半路被三名匪徒劫持。在匪徒的威胁下，迪恩将22号写入全新系统。22号以“查派”的名字重生，它的诞生即将改变许多人的命运……©豆瓣', '沙尔托·科普雷', '尼尔·布洛姆坎普', 7.4, 123849, 'tt1823672', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2240110789.jpg', 1.2, 5.2, 34.4, 42.6, 16.6, '0.239411,0.303718,-0.507762,0.343497,0.028748,-0.075444,0.545602,-0.240953,-0.392677,-0.284140,0.295492,0.354319,-0.147677,-0.101799,0.190084,-0.209822,-0.334842,-0.458585,0.147157,-0.098281,-0.265203,-0.536527,-0.577243,-0.348644,-0.070998,-0.468151,0.689361,-0.017464,-0.288460,0.072133,-0.000937,0.329092,0.018910,0.392478,0.034415,0.034108,0.304664,-0.367859,-0.128693,0.416807,-0.136275,-0.264162,0.136716,-0.080794,-0.085781,0.346265,0.672950,-0.391150,-0.089346,-0.160411,0.562231,-0.138347,-0.049649,-0.087093,0.170812,0.307915,-0.461871,0.261009,-0.156787,-0.031727,0.253651,-0.292210,-1.027361,-0.155183,-0.101319,0.207317,-0.417212,0.219223,-0.416189,0.293529,-0.047182,-0.455706,0.064898,0.496829,0.401497,0.381133,-0.193892,0.313829,-0.631350,0.258691,0.397628,-0.302970,-0.382022,0.321565,-0.047695,-0.577596,-0.232461,-0.354915,-0.180684,-0.082208,0.412450,0.210836,-0.062425,0.022713,-0.595850,0.041854,-0.230573,-0.460703,0.013243,-0.257921,-0.075204,-0.880292,0.099519,-0.053142,-0.303901,0.134891,-0.002677,-0.340169,0.723987,-0.887594,0.096468,0.628859,0.234546,-0.391277,0.318191,-0.313041,0.007677,-0.287417,-0.322569,0.114571,0.171541,0.576381,0.133932,0.343717,0.259612,-0.380451,-0.126985,0.346092', '1793491', '2369613', '27073234', '11810348');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6849071', '铁血娇娃', '动作', '白雪（余男 饰）等五个来自中国大都市的女子背包族和朋友老鹰（邹兆龙 饰），在东南亚偶遇英俊帅气的当地旅游节目主持人丹尼斯（安志杰 饰）、以及走出原始丛林的当地虎族部落酋长继承人ASAM（释行宇 饰），大家相约在ASAM的带领下，进入密林探险，不料却陷入黑势力的夺宝阴谋，遭遇了灭顶之灾……邪恶与善良；目击与反击；扞卫文明与掠夺自然；标枪长矛与枪炮火箭；特种兵老鹰、身手不凡的五个都市美女、以及英勇的虎族战士，与黑势力展开了惨烈的殊死奋战……丛林终于重归宁静，而白雪的爱却已远逝……©豆瓣', '邹兆龙', '傅华阳', 3.6, 5244, 'tt3729818', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2153758345.jpg', 49.3, 30.4, 15, 3, 2.2, '0.009000,-0.177195,-0.485646,0.605651,0.425460,-0.096440,0.905635,0.084470,-0.300969,-0.105368,0.409150,0.574662,0.111358,0.066936,0.488634,-0.276382,-0.332503,-0.674483,-0.403642,0.154229,-0.184683,0.087125,-0.297109,-0.178318,0.191711,-0.239778,0.767286,0.349047,-0.313318,0.634489,0.257223,0.301058,-0.654138,0.189496,-0.340495,-0.397989,0.168892,0.108094,-0.598632,0.154917,-0.498813,-0.163496,-0.349695,-0.126758,-0.099741,0.244756,0.895181,-0.334789,0.015468,-0.271417,0.049226,-0.253272,0.077694,0.207761,0.389962,-0.202172,0.258100,-0.021233,0.296636,0.137701,-0.161271,-0.209778,-0.507416,0.154595,0.124659,-0.005695,-0.454230,0.637974,0.136227,-0.066793,0.265535,0.018828,0.227340,0.256455,0.319410,0.262970,0.231859,0.191768,-0.350020,0.260305,0.692478,0.245774,-0.238626,-0.277918,-0.056038,-0.847360,-0.106208,-0.109564,-0.280262,-0.221545,0.482663,-0.155260,0.046432,0.351628,-1.009171,0.321403,-0.081355,-0.077568,0.029717,-0.265152,-0.419998,-0.956233,0.029086,-0.355616,-0.076635,0.504653,0.266646,0.387593,0.822674,-0.771572,0.056977,0.215988,0.137785,-0.407546,0.527921,-0.068561,-0.045922,-0.240686,-0.023741,0.385837,0.318892,0.286091,0.079962,0.292649,-0.542409,-0.096002,-0.234850,0.054425', '20274039', '26290398', '3811356', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6850547', '玩具总动员4', '喜剧', '胡迪深知自己在这个世界上的使命，就是照顾他的主人，无论是原来的安迪还是新主人邦妮。当邦妮将不情愿成为玩具的“叉叉”带回家时，胡迪又担起了教导叉叉接受自己新身份的责任。 然而当邦妮将所有玩具带上房车家庭旅行时，胡迪与伙伴们将共同踏上全新的冒险之旅，领略房间外面的世界有多广阔，甚至偶遇老朋友牧羊女。在多年的独自闯荡中，牧羊女已经变得热爱冒险，不再只是一个精致的洋娃娃。正当胡迪和牧羊女发现彼此对玩具的使命的意义大相径庭时，他们很快意识到更大的威胁即将到来……', '汤姆·汉克斯', '乔什·库雷', 8.5, 312982, 'tt1979376', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2557284230.jpg', 0.1, 1, 14, 44.2, 40.6, '0.340265,0.304742,-0.586430,0.433790,-0.275113,-0.215441,0.445827,0.053910,-0.505957,-0.263303,0.043609,1.073916,0.111216,0.301344,0.189151,0.086035,-0.422946,-0.654299,-0.257600,-0.010850,-0.392545,-0.490968,-0.255894,-0.150524,-0.052056,-0.472569,0.625689,0.026531,-0.245540,0.365956,0.375701,0.030559,-0.306472,0.619369,-0.312631,-0.156202,0.254889,0.416935,-0.383502,0.002456,-0.193531,0.014041,-0.112537,0.233952,-0.117142,0.082648,0.734318,-0.556518,-0.362196,-0.314692,0.370953,-0.094992,-0.110163,-0.022733,-0.052237,0.225769,-0.019937,0.185874,-0.091913,0.165281,0.149849,-0.451709,-0.690921,-0.060099,0.276891,-0.043108,-0.749364,0.316265,0.022027,-0.172494,0.307867,-0.249326,0.416463,0.484891,0.246615,0.472162,-0.187559,0.201805,-0.324377,0.042050,0.763925,-0.007060,-0.130151,0.403833,-0.412471,-0.269556,0.072156,-0.256063,-0.534906,-0.079942,0.092087,0.280116,-0.323560,0.165130,-0.851866,0.021648,-0.284263,-0.313428,0.225542,-0.636364,-0.058671,-0.578572,-0.049141,-0.393978,-0.143444,0.237262,0.103097,-0.430034,1.017313,-0.882367,0.333490,0.545935,0.276889,-0.495959,0.826036,-0.076879,0.243191,-0.547359,0.104943,0.383759,-0.013549,0.287209,0.018114,0.181385,-0.323607,-0.005583,-0.470828,0.758397', '30162520', '1292720', '35048413', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6854414', '歌声不绝', '剧情', 'BV（瑞恩·高斯林 Ryan Gosling 饰）是一位对音乐充满了理想抱负的年轻人，为了在行业里立足，他决定和超级制作人库克（迈克尔·法斯宾德 Michael Fassbender 饰）合作。菲耶（鲁妮·玛拉 Rooney Mara 饰）是库克的女友，同时也是他的助理，在三人相处的过程中，BV和菲耶渐渐相互吸引了。虽然菲耶和库克一直进行的是开放式的恋爱关系，但BV的插足还是让库克心中感到百般不爽，最终，玩脱的三人分道扬镳。BV和名叫阿曼达（凯特·布兰切特 Cate Blanchett 饰）的富婆走到了一起，菲耶在女同性恋者佐伊（贝纳尼丝·玛尔洛 Bérénice Marlohe 饰）的身上寻找安慰，而库克则和罗兰（娜塔莉·波特曼 Natalie Portman 饰）携手步入了婚姻的殿堂。©豆瓣', '瑞恩·高斯林', '泰伦斯·马力克', 5.6, 6843, 'tt2062700', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2430385341.jpg', 9.3, 30.7, 36.9, 15.9, 7.1, '0.439462,-0.231435,-0.568200,0.717172,0.142901,-0.533490,0.801584,0.216234,-0.501055,-0.366026,-0.080319,0.765292,-0.500605,0.094589,0.546450,0.077932,-0.535606,-0.861509,-0.197847,-0.205973,-0.222331,-0.821834,-0.233361,-0.293598,-0.330937,-0.320373,0.704048,-0.119091,-0.176659,0.636898,0.597958,0.518660,-0.100692,0.428663,0.058490,-0.035356,0.328043,-0.115242,-0.426787,0.071108,0.026167,0.000469,-0.088788,0.022027,0.399367,0.459596,0.566207,-0.343446,0.283934,0.197591,0.042848,-0.199435,0.080304,-0.008101,0.194919,-0.353687,0.260444,0.192054,-0.198148,-0.132951,0.272427,-0.248524,-0.721352,0.182425,0.192594,0.131332,-0.673672,0.513010,-0.104765,-0.345841,0.349938,-0.206305,0.197830,0.317345,0.393733,0.478065,0.018577,0.078320,-0.532172,-0.124215,0.602642,0.356743,-0.078244,0.304933,-0.378756,-0.542481,-0.535869,0.094411,-0.583499,-0.382752,0.284295,0.156644,0.300788,0.197897,-0.764380,-0.166940,-0.241315,-0.084925,0.236204,-0.587934,0.136686,-0.774620,-0.310095,-0.784270,-0.355987,0.019695,0.053002,-0.370609,0.696448,-0.947915,0.014190,0.205473,0.459214,-0.307692,0.865102,0.181637,0.234186,-0.320382,-0.207010,0.338704,-0.016475,-0.227472,0.148480,0.549757,-0.019885,-0.125265,-0.425436,0.479788', '1294244', '6858739', '4301278', '1299556');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6855094', '绣花鞋', '剧情', '1948年的某江南水乡，壮年男子都被征去当兵，剩下的都是有残疾的男人及老弱妇孺。车夫丁大山在破庙的离奇死亡打破了这个水乡的平静，从现在遗留的六寸半鞋印及一只绣花鞋来看，疑凶的焦点落在了以刺绣闻名的苏二（林心如 饰）身上。案件被认为是通奸谋杀，传统守旧的乡绅带领乡民疯狂地将苏二处以“浸 猪笼”极刑，遗下苏二一双未成年的儿女绝望无助。可是自此之后，水乡接二连三发生命案，先是编猪笼的程南（景冈山 饰）之妻被竹片穿心而死，接着又有乡绅离奇死亡，更有甚者看见苏二在夜晚的水乡飘然出现，到底背后的真相是什么……？©豆瓣', '林心如', '叶伟民', 4.4, 16413, 'tt2238995', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1419928380.jpg', 23.5, 39.4, 30.7, 4.5, 1.9, '0.377466,-0.242859,-0.542944,0.283399,-0.133801,0.106813,0.938988,0.071182,-0.476697,-0.197183,0.466631,0.447273,-0.385192,0.302102,0.275923,-0.147138,0.254438,-0.835863,-0.359145,-0.154744,-0.624841,-0.423399,0.061057,0.035438,0.007761,0.091340,0.440794,0.326716,-0.067007,0.452509,0.346962,0.499256,-0.243678,0.209854,-0.369337,0.007820,-0.262839,-0.033408,0.238422,0.015529,-0.084550,-0.549517,-0.025963,-0.133852,-0.372966,0.523662,0.747051,-0.214863,-0.071610,-0.136543,0.575508,-0.083927,-0.103423,0.316344,0.442602,-0.106957,-0.149061,0.178688,-0.191065,-0.215938,0.385496,0.053732,-0.404039,-0.025562,0.137172,0.306362,-0.599609,0.359988,0.175790,-0.226350,0.105286,-0.121266,0.385832,0.024420,0.317728,0.553096,-0.048759,0.109745,-0.670758,0.402932,0.343033,0.041543,-0.295606,0.008331,-0.244307,-0.579925,0.226698,-0.381007,-0.138188,-0.014313,0.363822,0.138478,-0.315313,0.416856,-0.429669,-0.141529,-0.050343,-0.155686,-0.062691,-0.062528,-0.698526,-0.027411,-0.215307,-0.378524,-0.196547,0.272527,0.179819,-0.056960,0.531316,-0.482770,0.197522,0.324097,0.113649,-0.298883,0.504677,-0.150481,0.104325,0.307687,-0.322119,0.281879,0.461782,0.199841,0.275293,0.282344,-0.392916,-0.078028,-0.267100,0.385000', '21619567', '1578663', '1467779', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6857606', '欧罗巴报告', '科幻', '几十年来，科学家们一直在推测木卫二可能是除地球之外，太阳系中唯一一个有大量液态水存在的地方。因为木卫二的表面照片与地球海洋上的冰的照片相似，冰壳上布满了各种陨石撞击留下的坑坑洼洼，不少科学家推测，在木卫二的冰壳之下或许有着太阳系中最大的液态水海洋，海洋下面可能存在着有单细胞生命。而这一“生命可能”的理论正是电影《欧罗巴报告》的核心。', '吴彦祖', '塞巴斯特·柯代洛', 6.9, 12940, 'tt2051879', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1963923281.jpg', 2, 9.4, 42.2, 34.4, 12, '0.272765,0.240030,-1.170760,1.022775,-0.003075,0.304520,0.982271,-0.110788,-0.452950,-0.149675,0.131851,1.014667,0.053764,0.038551,-0.348227,-0.081089,-0.137551,-0.271102,-0.707678,-0.619146,-1.002945,-0.733809,-0.758198,-0.019783,-0.006723,-0.726265,0.656596,0.402771,-0.236831,0.278024,-0.107207,0.272956,-0.290123,0.334170,-0.226802,-0.286099,-0.138118,0.220106,-0.266883,0.136957,-0.101359,0.358362,0.327960,0.313946,-0.425263,0.380531,0.634239,-0.462051,-0.041710,-0.185606,0.613056,-0.415994,0.074587,-0.141176,0.739101,0.042839,0.164705,0.141709,0.008084,-0.082600,0.478668,0.163087,-0.975233,-0.457172,-0.107625,0.517011,-0.376897,0.355563,0.338826,-0.575417,-0.373701,-0.104461,0.744728,0.267969,0.176829,0.224173,-0.340919,-0.020763,-0.365896,0.133340,0.344621,0.327877,-0.502930,0.252989,-0.638845,-0.299084,-0.633147,-0.200063,-0.275005,-0.108285,0.259591,0.094358,-0.530099,0.247564,-0.839529,0.682934,-0.008522,-0.594454,0.008687,-0.158300,-0.320873,-0.667416,-0.237984,-0.523302,-0.365640,0.056218,0.187777,-0.206208,1.113849,-0.532603,0.354081,0.673815,0.376997,-0.201811,0.845031,0.160101,-0.331521,-0.281339,-0.041726,0.224236,0.123928,0.439725,-0.275980,0.362650,0.073297,-0.041085,-0.595777,0.587142', '35017064', '25932086', '25928048', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6858739', '爱的面包魂', '剧情', '在一个正港台客面包师傅，遇到了来自英国的贵族面包师傅，为了追求心爱的女孩，展开正面对决。两个男人，乡村面包店的土洋大战，谁输谁赢，口味将决定一切.......糕饼（陈汉典 饰）是一间位于在高雄乡间“源晨面包店”的面包师傅，和店长邱爸（廖峻 饰）的女儿晓萍（陈妍希 饰） 是从小到大的青梅竹马。非晓萍不娶的糕饼，有一天晚上精心筹划了一场求婚惊喜，但晓萍心中一直有个渴望实现的梦想，因此面对糕饼的求婚仍旧不为所动。 这天，平静的面包店，来了一位帅气的混血王子布莱德（倪安东 饰）。身为国际美食旅游节目主持人，同时也是米其林三星餐厅主厨，布莱德为了寻找灵感，决定找出母亲生前最爱的面包，而来到这个纯朴的小镇。他对晓萍一见钟情，晓萍虽心有所属，但是，布莱德做的欧式面包，以及他浪漫温柔的举止，意外地搅乱晓萍和糕饼的生活。 在晓萍无心插柳的安排下，布莱德以房客的身分，和糕饼一起住在面包店顶楼，并成为糕饼的学徒。眼见晓萍与布莱德的感情越来越好，布莱德甚至要带晓萍离开台湾前往法国实现她的梦想！为了留住晓萍，糕饼决定接受健生嫂（陈盈洁 饰）的提议和布莱德来一场以“台式面包PK欧式面包”为主题的面包大赛。深情贵公子与认真黑狗兄的东西烘焙大对决，晓萍最终选择的是？.......', '陈汉典', '高炳权', 5.9, 11579, 'tt2191861', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1605982963.jpg', 5.1, 22, 52.4, 16.1, 4.5, '0.136009,0.025009,-0.443520,0.556930,-0.100780,-0.124342,0.642008,0.443398,-0.207249,-0.276867,0.297353,0.909881,-0.013333,0.237813,0.392851,0.058827,-0.101140,-0.504321,-0.028503,0.006217,-0.097144,-0.454176,-0.156305,-0.055256,-0.047279,0.084387,0.590666,0.071978,-0.060322,0.339674,0.596445,0.045659,0.032451,0.303673,-0.192570,-0.242411,0.112517,0.109280,-0.585574,0.272337,0.004504,-0.097854,-0.158693,0.176261,0.224391,0.207682,0.514545,-0.050664,-0.100830,-0.012770,0.137451,-0.102396,-0.041319,0.180628,0.123718,0.072840,0.148952,0.082392,-0.179371,0.024527,0.125110,-0.226601,-0.591055,-0.004090,0.232542,-0.028357,-0.613189,0.438871,-0.126526,-0.169307,0.177325,-0.323502,0.137461,0.215626,0.434347,0.469827,-0.064390,0.281821,-0.578366,-0.000464,0.706162,0.207521,0.197366,0.271138,-0.192152,-0.397157,0.270733,-0.260578,-0.488143,0.154077,-0.056785,0.100942,0.057241,0.029457,-0.883956,-0.160231,-0.085648,-0.258092,0.534733,-0.369800,-0.255474,-0.690247,0.079732,-0.325763,-0.180510,0.023349,0.111255,-0.287285,0.670730,-0.925896,0.157217,0.341597,0.253607,-0.481453,0.779111,0.213257,0.016900,-0.238667,-0.188099,0.233908,-0.049286,-0.101676,-0.042424,0.410870,0.066953,-0.061009,-0.377638,0.399520', '4301278', '3055049', '26290398', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6859676', '亿万少年的顶级机密', '剧情', '艾提帕特（帕查拉•奇拉锡瓦特 Pachara Chirathivat 饰）高中时期沉迷网络游戏，但是却通过倒卖游戏道具发家，小小年纪就已经展现出出色的生意头脑。但因为过久的荒废学业，毕业考试成绩未能通过，因而他只能选择就读学费昂贵的私立学校。然而屋漏偏逢连夜雨，父亲生意失败欠下巨额债务，准备举家迁往国外。但是艾提帕特坚持留下来为父亲还债。为此，他尝试了倒卖DVD游戏机，摆摊兜售糖炒栗子，但都因为经验不足而失败，创业之路荆棘满布。机缘巧合的他发现了海苔作为零食的商机，通过不断尝试，他克服了海苔保鲜的问题，出品的海苔大获好评。他没有止步在零售阶段，而是自学营销理论，通过不断改进生产质量和克服大量加工生产的难题，取得了与零售超市大亨7-eleven的合作，在两年内偿还了父亲四千万的债务，并在26岁成为了亿万富翁，创造了生意场上的奇迹。该片通过泰国海苔大亨的真人真事改编，讲述了他个人的励志故事。', '帕查拉·奇拉锡瓦特', '颂裕·素玛戈南', 7.4, 8076, 'tt2292955', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1315672670.jpg', 0.8, 4.6, 35.8, 41.7, 17.1, '-0.054409,0.156050,-0.374297,0.258315,-0.121891,-0.381164,0.179171,0.162592,-0.276500,-0.250671,-0.001179,0.593361,0.045968,-0.025471,0.022431,-0.245762,-0.125252,-0.429322,0.562830,-0.284300,-0.031608,-0.499332,-0.350283,-0.327640,-0.449131,-0.337332,0.785608,0.204212,-0.300668,0.250264,0.022511,-0.073408,0.228996,0.252508,-0.168279,-0.107142,0.108479,0.298352,-0.342200,0.310838,0.004262,-0.353846,-0.087283,-0.004848,0.551013,0.574191,0.589597,0.039533,-0.065447,0.246126,0.452347,-0.317762,-0.240672,-0.055689,0.125307,0.386392,0.219123,0.167064,-0.477690,-0.119321,0.013784,-0.279810,-0.835022,-0.394156,0.138742,-0.139791,-0.719282,0.324208,-0.213386,0.066311,-0.262077,-0.381157,-0.089635,0.449382,0.401758,0.491851,-0.185111,-0.019687,-0.591736,0.593668,0.454389,-0.287770,-0.195256,0.613478,-0.328592,-0.538676,0.138714,-0.552071,-0.216073,-0.017694,0.107566,0.021766,-0.211067,0.178350,-0.688548,0.043402,-0.253522,-0.366696,0.250569,-0.013386,-0.157108,-0.749781,-0.099747,-0.160662,-0.266351,-0.032294,0.270452,-0.606441,0.674674,-0.632977,-0.222542,0.521180,0.285198,-0.587911,0.653918,-0.237685,0.082589,-0.227482,-0.164469,0.119602,-0.157218,0.250488,0.104505,0.131709,0.244436,-0.399807,-0.