INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6860147', '霓虹恶魔', '剧情', '美丽女孩杰茜（艾丽·范宁 Elle Fanning 饰）是一个只身独闯洛杉矶的年轻女模特，她初次涉足花花世界，看起来懵懂无知，人畜无害。亲和的化妆师茹比（吉娜·马隆 Jena Malone 饰）最先接近她，并将其介绍给两个小有名气的模特琪琪（贝拉·希思科特 Bella Heathcote 饰）与莎拉（阿比·丽 Abbey Lee 饰）。杰茜如同一块蕴藏着莫大价值的璞玉，她很快得到了业内有识之士的赏识，前路充满光芒。她的美是上天的恩赐，她的美却也成为他人嫉妒乃至急于毁灭的脆弱之花。T台之上，霓虹交错，杰茜逐渐趋向梦的彼岸，然则肆无忌惮膨胀的欲望与嫉恨也正将她吞没……©豆瓣', '艾丽·范宁', '尼古拉斯·温丁·雷弗恩', 6.3, 23594, 'tt1974419', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2361572046.jpg', 4.3, 17.3, 44, 25.5, 8.9, '0.231333,0.389828,-0.696758,0.598992,-0.174149,-0.157418,0.874488,0.311132,-0.197754,0.084016,0.129552,0.641631,-0.403591,0.186316,0.163953,0.525521,-0.089770,-0.623388,-0.094733,-0.043978,-0.041090,-0.342179,-0.459944,0.194628,0.099626,-0.304012,0.578661,-0.083878,-0.133944,0.452612,0.307757,0.227321,-0.093144,0.604964,-0.102219,-0.096515,-0.031710,-0.111558,-0.151355,-0.065825,-0.332917,-0.305390,0.025801,0.300751,-0.442603,0.186588,0.641167,-0.416217,0.143473,-0.226967,0.382846,-0.336774,0.117671,0.175335,-0.228563,-0.201154,-0.094525,-0.237203,-0.190976,-0.129367,0.249416,-0.188111,-0.711838,-0.063408,0.324185,0.203156,-0.299350,0.503411,0.162995,-0.045881,0.109006,-0.249600,-0.187761,-0.148763,-0.235472,0.299261,0.003278,0.018084,-0.495952,0.229543,0.351450,0.293171,-0.416753,0.375944,-0.536987,-0.342915,-0.067683,-0.074728,-0.710924,-0.160060,0.552206,0.050584,0.172051,0.303938,-0.731850,-0.055266,-0.460536,0.090343,-0.187989,-0.419361,-0.103530,-0.361678,-0.212826,-0.632234,-0.592751,-0.120261,0.048948,-0.268945,0.761809,-0.709924,0.195762,0.541801,0.286909,-0.262474,0.497385,-0.067010,-0.153582,-0.098151,-0.477620,0.564545,0.016889,0.008748,0.018330,0.261551,-0.282575,0.129767,-0.421282,0.599586', '1292062', '24756472', '3005387', '5029050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6860160', '悲惨世界', '剧情', '贫苦的冉·阿让（休·杰克曼 Hugh Jackman 饰）为了挨饿的孩子去偷面包，结果被判处19年的苦役。出狱后，走投无路的他偷走了收留他过夜的主教的银器潜逃，被警察捉回。主教声称银器是送给他的，使他免于被捕。主教的言行感化了他，他化名马德兰，从此洗心革面奋发向上开始新生活。但缉拿过他的警长沙威（罗素·克劳 Russell Crowe 饰）却一心要找他麻烦。在得知了芳汀（安妮·海瑟薇 Anne Hathaway 饰）的悲惨遭遇后，他承诺照顾她的私生女柯赛特（阿曼达·塞弗里德 Amanda Seyfried 饰）。八年后，柯赛特爱上了共和派青年马利尤斯（埃迪·雷德梅恩 Eddie Redmayne 饰），轰轰烈烈的巴黎人民起义爆发了，无赖德纳迪埃（萨莎·拜伦·科恩 Sacha Baron Cohen 饰）和他又狭路相逢，而多年来从未放弃追捕他的沙威又出现在他的面前……', '休·杰克曼', '汤姆·霍伯', 8.7, 323057, 'tt1707386', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1900812761.jpg', 0.3, 1.3, 11.7, 38.6, 48.1, '-0.006223,-0.061860,-0.473515,0.423870,-0.388169,-0.458933,0.647224,0.154771,-0.263902,-0.266767,0.119746,0.728618,-0.147042,0.335300,0.449972,0.389377,-0.414291,-0.717236,0.286676,-0.245377,-0.234444,-0.443493,-0.040475,-0.378100,-0.042710,-0.262145,0.281020,0.023286,0.029561,0.256820,0.314515,0.480619,0.219064,0.466983,-0.103196,0.291730,0.170567,-0.344025,-0.009379,0.128265,0.250115,-0.422301,-0.206955,0.355594,0.196004,0.541818,0.598032,-0.305487,0.190985,-0.111008,0.351612,-0.365697,0.322876,0.152678,0.152466,-0.158262,-0.178188,0.131592,-0.150524,-0.270875,0.219428,-0.025121,-0.356602,0.066415,-0.101969,-0.076898,-0.760945,0.506265,-0.424844,0.405986,-0.073981,-0.057161,-0.016449,0.316810,-0.090747,0.136096,0.045263,-0.035919,-0.631273,0.275751,0.503714,-0.198269,-0.165286,-0.015217,-0.228788,-0.366824,0.217629,-0.159277,-0.546585,-0.174679,0.508072,-0.247686,-0.077167,0.227923,-0.350400,-0.452695,-0.702285,0.123389,0.003206,-0.049598,-0.183396,-0.441021,-0.065996,-0.307767,-0.354409,0.011693,-0.136508,-0.164245,0.243443,-0.499717,0.275804,0.624066,0.370877,-0.461084,0.521773,-0.094789,0.130314,0.023571,-0.078673,0.560927,0.327562,0.338333,0.613414,0.173819,0.267956,-0.015316,-0.046540,0.491280', '1309069', '1293976', '1292584', '1292533');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6861573', '十二星座离奇事件', '悬疑', '作家唐琳遇到了一件怪事，原本她遭遇创作瓶颈，已经几年没有新做问世，可市面上却忽然出现了一本以她署名的新书——《十二星座离奇事件》。更惊人的是，书中的人物以她和她小时候的玩伴命名，故事俨然翻拍自他们的真实经历。主要人物分别是：双子座的唐琳（甘薇 饰）、水瓶座的陈为（佟大为 饰）、双鱼座的许高山（宋宁 饰）、金牛座的赵聘（秦昊 饰）、狮子座的周康（杜海涛 饰）、天秤座的陈晓峰（乔任梁 饰）。书中写到了一个他们集体沉默多年、谁也不愿提起的秘密，并且透露，每个人都将用性命来偿还当年的错误。这引起了唐琳几乎所有朋友的愤怒，只有陈为始终站在唐琳身后。没过多久，天蝎座的崔淼（柳岩 饰）以相似于书中描述的方式意外的死去。星座决定性格，面对突如其来的“诅咒”，分属七个不同星座的主角们，都作出了不同于其他人的选择。有人害怕逃避，有人疑神疑鬼，有人迁怒他人，有人寻找真相。在这个过程中，书中早已预言的血腥事件，却并未因此停止。陈为隐约发现唐琳有精神分裂的症状，而身为心理学家的陈为自己，亦深受心魔困扰……那么这本离奇的预言书，作者到底是第二人格的唐琳，隐藏内心的陈为，还是另有他人？您之前看到的真相，未必是最后的真相；这个波诡云谲的故事，每分钟都变得更波诡云谲。星座真的可以决定命运吗？做了不同选择的主角们，最终都要以相同的方式面对过去。数次血腥事件，两段爱情故事，一场残酷青春……这是一个绵延了十几年的暴力童话。', '佟大为', '盛志民', 3.1, 12588, 'tt2460860', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1519832698.jpg', 59.8, 27.6, 10.1, 1.3, 1.2, '0.275223,-0.090010,-0.547088,0.683876,0.010237,0.032998,0.703680,-0.153224,-0.547069,-0.491970,0.325411,0.689460,-0.234871,0.155122,0.193925,-0.240333,-0.147900,-0.534201,0.018748,-0.152418,-0.330977,-0.474363,-0.233014,-0.253237,-0.128884,0.000237,0.532613,0.051443,-0.339310,0.152887,0.463149,0.456096,-0.060957,0.420848,0.010021,0.045280,-0.083586,0.150172,-0.035376,-0.124944,0.010142,-0.361612,-0.149151,0.505373,-0.207922,0.394986,0.483907,-0.476389,-0.355973,0.070406,0.651979,-0.136637,-0.134399,0.021119,0.263334,0.007156,0.189705,0.311768,0.020789,0.063922,-0.036539,0.129487,-0.924187,-0.030963,0.310866,0.252421,-0.211075,0.165201,-0.033314,-0.098652,0.030043,-0.236700,0.131680,0.244068,0.592511,0.203559,-0.267346,-0.242686,-0.267044,0.327473,0.587587,0.116688,-0.490618,0.385072,-0.252642,-0.417453,-0.167581,-0.288989,-0.325987,0.366130,0.234849,0.221300,-0.078331,0.402353,-0.549969,-0.165801,0.040327,-0.191322,-0.012801,-0.261892,-0.140302,-0.336728,-0.299462,-0.503983,-0.339949,0.034236,0.082883,-0.403627,0.742324,-0.615774,0.143300,0.268865,-0.165032,-0.696821,0.448346,0.209554,-0.009233,-0.137569,-0.002876,0.356865,0.009870,0.182240,-0.158551,0.209389,0.337441,-0.078120,-0.341640,0.478551', '27602116', '26678784', '1874704', '6844861');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6861618', '真人版 乱马1/2', '喜剧', '在都会的一隅，坐落着平凡的天道道场。道场主人天道早云（生瀬勝久 饰）早年丧偶，独自拉扯三个女儿小霞（長谷川京子 饰）、小靡（西山茉希 饰）、小茜（新垣結衣 饰）长大。这天，道场迎来了不速之客。早云的同门师兄早乙女玄马（古田新太 饰）结束了漫长的修业之旅，即将带着儿子乱马（賀来賢人 饰）前来投宿，而乱马又是小茜的未婚夫。可是见了面才发现，乱马（夏菜 饰）竟然是个女儿身！原来早乙女父子曾在中国咒泉乡发生意外，以致遇到冷水后就会变身。为了尽快恢复男儿身，乱马决定拿到藏在风林馆高中和风男溺泉，结果遭到神秘组织的阻拦……本片根据漫画家高桥留美子同名经典名作改编。©豆瓣', '新垣结衣', '西村了', 6.1, 11908, 'tt2072214', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1300995657.jpg', 3.8, 17.5, 52.9, 20, 5.8, '-0.118197,-0.073164,-0.258897,0.099701,0.084446,-0.275035,0.160703,0.222034,-0.422593,-0.477239,0.465994,0.639424,-0.177171,0.323274,0.385963,0.115813,-0.134053,-0.326889,0.060856,-0.224097,-0.183422,-0.101332,0.074509,0.252433,-0.076716,-0.296193,0.735263,-0.138773,-0.050622,0.304532,0.304038,0.337621,-0.416441,-0.042181,-0.222124,0.284721,-0.135996,0.309781,-0.096866,0.302579,-0.382753,-0.171815,-0.180504,-0.114083,0.033157,0.291710,0.589321,-0.138751,-0.141432,-0.160887,0.511321,-0.242448,-0.247925,0.163511,0.599215,-0.161565,0.230287,0.286077,-0.128928,0.051559,0.227658,-0.183211,-0.097467,0.205789,0.302489,0.059325,-0.433671,0.434790,0.081604,-0.430198,0.277830,-0.455417,-0.055225,0.358370,0.284017,0.248761,-0.149607,0.058764,-0.019037,0.137887,0.355321,-0.352462,0.245464,0.244573,0.182832,-0.270537,0.084237,-0.354588,-0.594094,0.146928,0.113495,0.134063,-0.184514,-0.093382,-0.529053,-0.172584,-0.147811,0.172072,0.283791,0.014291,-0.141811,-0.523986,0.101222,-0.228055,-0.184903,0.191807,0.141076,-0.073059,0.787838,-0.752309,0.158574,0.415684,0.059344,-0.282902,0.300133,0.194876,-0.190867,-0.203330,0.051680,0.082555,0.045434,0.494900,-0.016497,0.332734,-0.098956,-0.107564,-0.158026,-0.005404', '10174444', '25922902', '26999591', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6866928', '进击的巨人真人版：前篇', '动作', '不知曾几何时，世界各地出现了专门捕杀人类的巨人，可怕天敌的出现最终导致人类的文明衰落与倒推。为了阻止巨人无休止的捕猎，人类筑起三座高墙将自己保护起来，如是过去了一百年的时光。少年艾伦（三浦春马 饰）厌倦了被囚禁起来的日子，某天他怂恿伙伴三笠·阿克曼（水原希子 饰）和阿明·阿诺德（本乡奏多 饰）试图翻出围墙，谁知却见证了超大型巨人打破围墙以及无数巨人疯狂涌入的可怕一幕。霎时间宁静祥和的城市变成了巨人的狩猎场，艾伦等人目击了永生难忘的血腥一幕。两年后艾伦和阿明加入调查兵团，并且即将随同战友出发修复外墙，夺回沦陷的土地。这注定是一次凶险非常的旅程……本片根据谏山创发表在《别册少年Magazine》上的同名漫画原作改编。©豆瓣', '三浦春马', '樋口真嗣', 5.1, 40160, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2239093805.jpg', 15.5, 32.4, 38.5, 9.9, 3.8, '0.091547,-0.113305,-0.641131,0.448302,0.127505,-0.074201,0.949718,-0.027370,-0.470012,0.005511,0.414911,0.528447,-0.291598,0.065946,0.451854,-0.086080,-0.131631,-0.517445,-0.134893,-0.185487,-0.361677,-0.147149,-0.540535,-0.305950,0.087166,-0.579596,0.875925,0.234898,-0.148721,0.296965,-0.038117,0.166283,-0.306998,0.201214,-0.096678,0.130973,-0.039131,-0.039234,-0.258149,-0.019320,-0.377049,-0.284351,-0.163213,0.100745,-0.342998,0.070984,0.757562,-0.523432,-0.086346,-0.367628,0.420988,-0.301944,-0.141667,0.089382,0.452354,0.246792,-0.132215,0.264428,-0.143879,-0.213498,0.128719,-0.056180,-0.492546,0.078734,-0.059399,0.178788,-0.606565,0.534152,0.237917,0.045139,0.156821,-0.417174,-0.042866,0.255372,0.338743,0.308102,-0.008996,-0.033057,-0.194383,0.272197,0.782196,-0.163464,-0.353750,0.003280,-0.121750,-0.321201,-0.253347,-0.200564,-0.301858,-0.082841,0.308714,-0.007636,-0.249130,0.463414,-0.809901,-0.062801,-0.514642,-0.376771,-0.030425,-0.235033,-0.342532,-0.675922,-0.068324,0.127968,-0.006610,0.254396,-0.114007,-0.308948,0.607896,-0.714167,0.205736,0.488336,0.415311,-0.134621,0.378671,-0.177569,-0.084667,-0.059209,0.248455,0.295851,0.143574,0.369016,0.210093,0.223344,-0.042334,0.110892,-0.457924,0.650341', '21619567', '1467779', '1578502', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6869395', '低俗喜剧', '喜剧', '电影人杜惠彰（杜汶泽 饰）在某大学讲座期间，应学生之请讲述了自己为电影事业一次最惨痛最不堪回首的牺牲经历：作品不上台面的杜和老婆离婚后时时被追讨赡养费，助理刘倩儿（薛凯琪　饰）超级不靠谱搞丢新片企划。落魄之际，好友雷永成（雷宇扬　饰）牵线认识广西富二代暴龙哥（郑中基 饰）。面对乖戾变态的暴龙哥，阿杜做出几乎让自己大脑断片失忆的惨烈牺牲，总算获得对方投资的承诺，但是他必须请来早已收山明星邵音音（邵音音 饰）拍摄咸湿大作续集。在此之后，他说动邵，又网络男主角叶山豪（叶山豪　饰）、模特徐家欣（陈静　饰）以及导演黑仔达（邹凯光　饰）等人加盟。万事俱备，只欠东风，然而状况意外接二连三，杜监制面临从业来最大的危机与挑战……©豆瓣', '杜汶泽 Chapman To', '彭浩翔', 6.4, 66853, 'tt2266938', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1641250780.jpg', 5, 15.5, 44.7, 25.6, 9.2, '-0.294592,-0.189972,-0.355441,0.394320,0.192700,-0.053361,0.240248,0.157750,-0.152358,-0.365202,0.074017,0.418229,-0.306274,0.128770,0.380046,-0.422755,0.029418,-0.545565,0.191668,0.081367,0.030316,-0.191659,-0.080429,-0.216994,-0.179104,-0.109199,0.574850,0.055855,-0.348299,0.279274,0.689547,0.201891,-0.015486,0.350913,0.329616,0.121616,0.062586,0.279620,-0.314200,-0.116679,0.036920,-0.328913,0.029058,0.173995,0.278897,0.344446,0.399408,-0.100574,-0.166088,-0.183149,0.591620,-0.104387,-0.026174,-0.073027,0.033933,0.089172,0.337017,0.274369,-0.086611,-0.015837,0.113381,-0.230212,-0.563988,-0.065124,0.302262,-0.297222,-0.488394,0.081951,-0.128252,0.355698,0.014580,-0.016517,0.189491,0.159948,0.586716,0.085374,0.049343,0.184656,-0.267674,0.764232,0.299133,-0.010279,0.062564,0.454664,0.019475,-0.324495,-0.113664,-0.442863,-0.559996,0.411077,0.105389,-0.267456,-0.018068,0.014661,-0.102916,-0.416169,0.033220,-0.042276,0.029669,-0.246521,0.048370,-0.700625,-0.311452,-0.008332,-0.017546,-0.006735,0.028392,-0.401285,0.609632,-0.370281,-0.109029,0.128473,0.044134,-0.674824,0.484310,0.045333,-0.006308,-0.310586,0.102513,0.080377,0.131482,0.076895,0.047296,-0.139047,-0.120126,-0.285323,0.139575,0.183414', '25700838', '7161707', '10833970', '5332621');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6869412', '嫌疑人X的献身', '剧情', '影片改编自日本推理作家东野圭吾的代表作《嫌疑人X的献身》，原名《完美的爱情》，后仍改为和原著接近的《嫌疑人X》。沉默寡言的天才数学家金石固（柳承范 饰）每天唯一的乐趣，便是去固定的便当店买午餐，只为看一眼在便当店做事的邻居白花善（李瑶媛 饰）。花善与外甥女允儿相依为命，过 着平静的生活，可是有一个总来找麻烦的前夫金哲民。终于有一天，花善因不堪忍受虐待，最终手刃了前来纠缠的前夫。石固察觉花善出于自卫而杀人的事实后，主动提出由他料理善后，为此这桩犯罪设计完美的不在场的证明，保证让花善和允儿不受到牵连。负责查办此案的郑警官（赵镇雄 饰）是石固的好友对花善的凶手身份确认不疑，虽然没有确凿证据，却依然执著地展开调查。到底石固使用了怎样的隐藏手法？最终他会为爱献身吗？©豆瓣', '李枖原', '方银振', 7.5, 47725, 'tt2411024', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1702130521.jpg', 0.7, 3.4, 31.9, 46.5, 17.5, '0.164838,-0.116482,-0.403275,0.642266,-0.207202,-0.219235,0.548752,0.210451,-0.232904,-0.378202,0.177061,0.386962,0.089279,-0.023644,0.166928,-0.110550,-0.116069,-0.521763,-0.110298,0.095300,-0.200388,-0.546045,-0.108258,-0.204403,-0.018618,0.104573,0.530108,-0.044494,-0.167488,0.268382,0.379764,0.120019,-0.010360,0.262638,0.119057,-0.190427,-0.024369,0.301314,-0.408818,0.183612,0.235317,-0.287420,-0.086020,0.250349,-0.175641,0.522556,0.606957,-0.250069,-0.360620,-0.041141,0.485444,-0.280102,0.104895,0.065948,0.026474,-0.057839,0.013552,0.399837,-0.289886,-0.075261,0.062369,0.158946,-0.958311,-0.213361,0.522562,0.032596,-0.431735,0.339555,-0.209972,-0.063688,-0.070622,-0.346755,0.067891,0.340015,0.319440,0.312451,-0.077823,0.085869,-0.388646,0.390049,0.448251,0.087499,-0.067551,0.078143,-0.174429,-0.341511,0.244216,-0.283625,-0.440743,0.123173,-0.030657,0.126365,-0.038047,-0.018544,-0.412219,-0.388292,-0.144746,0.028105,0.281159,-0.451452,-0.009129,-0.459441,-0.021215,-0.351784,-0.276476,-0.116081,0.243290,-0.450050,0.494264,-0.707380,0.066286,0.421677,0.179081,-0.704156,0.709715,0.424399,-0.125844,-0.222280,-0.103070,0.168261,0.226948,0.109729,0.041037,0.107532,0.310847,-0.232446,-0.336337,0.157572', '26678784', '3670447', '3785918', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6870362', '唐顿庄园：2011圣诞特别篇', '剧情', '处在贝茨先生（布兰登•柯伊尔 Brendan Coyle 饰）受审一事阴霾中的唐顿庄园迎来了1919年的圣诞节。战争虽已过去，但影响仍在持续。房屋能被装饰一新，但唐顿人的心情却仍无法放晴。大小姐玛丽（米歇尔•道克瑞 Michelle Dockery 饰）觉得和理查德的婚姻不会幸福，但仍然决定继续；马修（丹•史蒂文斯 Dan Stevens 饰）仍对拉维尼娅的死感到愧疚；老爷（休•博内威利 Hugh Bonneville 饰）得知了玛丽不得不嫁给理查德的原因。尽管烦恼的事不断，但仍有好事传来。茜玻（杰西卡•布朗-芬德利 Jessica Brown-Findlay 饰）写信来告知了自己怀孕一事；被宣判死刑的贝茨因为证据不足改为了无期徒刑。新年晚会在贝茨的好消息中如期举行。新的一年即将来临，一切都在变化中，包括马修和玛丽的关系……第三季将于2012年9月16日于当地时间首播。', 'Robert Bathurst', '布莱恩·派西维尔', 9.3, 45897, 'tt2013429', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1711501188.jpg', 0.1, 0.2, 4.2, 26.6, 68.9, '0.108992,0.240909,-0.481027,0.299423,0.313218,-0.270160,0.582669,0.151769,-0.641212,-0.658471,0.010419,0.324544,-0.326030,0.219079,0.467522,0.035461,-0.452820,-0.433359,0.320913,-0.247658,-0.107535,-0.747485,0.115587,-0.236465,-0.097080,-0.371050,0.326978,0.226723,0.358435,0.561827,0.242973,0.474198,0.255013,0.569618,0.287328,-0.018424,0.363309,-0.141039,-0.488123,0.184331,0.272518,-0.246722,-0.252024,0.250754,0.310569,0.481627,0.512989,-0.350060,-0.065199,0.164030,0.417033,-0.186173,0.089141,0.245970,0.286544,0.062648,0.068240,0.508334,-0.371860,0.005360,0.186724,-0.242913,-0.265167,0.264325,0.138877,0.209773,-0.193038,0.613349,-0.338870,0.187526,-0.341284,-0.242531,0.061998,0.263617,0.209161,0.327818,-0.286064,0.083905,-0.550253,-0.176794,0.634840,-0.052322,-0.164108,0.321909,-0.244654,-0.421536,-0.049099,-0.194853,-0.531872,0.168961,0.118618,0.229884,-0.180411,0.559740,-0.229713,-0.185834,-0.493560,-0.395217,-0.115556,-0.217213,-0.074408,-0.307267,-0.082199,-0.184340,-0.408833,0.082724,0.132944,-0.119232,0.235090,-0.702050,0.376894,0.190693,0.188270,-0.110306,0.466976,0.329207,0.271324,-0.113031,-0.264429,0.375796,-0.301637,-0.041611,0.383236,0.030906,0.133438,-0.417380,-0.147480,0.4