INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6870493', '蓝精灵2', '喜剧', '为了获得更多的蓝精灵精华，邪恶巫师格格巫（汉克·阿扎利亚 Hank Azaria 饰）制造了两个调皮捣蛋的灰色小精灵韦克茜（克里斯蒂娜·里奇 Christina Ricci 配音）和海库斯（JB·斯穆夫 J.B. Smoove 配音）。可是他无法从灰精灵那里提取精华，为此格格巫派出韦克茜混入大森林，绑架了即将迎来生日的蓝妹妹（凯蒂·派瑞 Katy Perry 配音），希望能从她口中拷问出蓝爸爸（乔纳森·温特斯 Jonathan Winters 配音）将她变蓝的秘密。为了营救蓝妹妹，蓝爸爸率领笨笨（安东·尤金 Anton Yelchin 配音）、厌厌（乔治·洛佩兹 George Lopez 配音）、浮浮（克里斯蒂娜·里奇 Christina Ricci 配音）重返人类世界，并在他们人类朋友的帮助下，展开了蓝妹妹的营救行动……©豆瓣', '尼尔·帕特里克·哈里斯', '拉加·高斯内尔', 6.6, 27290, 'tt2017020', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2089514860.jpg', 1.8, 10.1, 53.2, 25.9, 9.1, '-0.132463,-0.059870,-0.216764,0.630378,0.030421,-0.295989,0.547263,0.046692,-0.222489,-0.275595,-0.098200,0.402917,0.084921,0.172712,0.288007,0.254296,-0.501564,-0.296271,0.098772,0.038963,-0.162142,-0.494223,-0.204365,-0.482344,0.029907,-0.563244,0.481172,-0.050972,-0.096120,0.294117,0.468779,0.143147,-0.315638,0.275304,0.193166,0.030182,0.336028,-0.165127,-0.151348,0.580419,-0.142435,0.293096,-0.064129,0.063699,0.134512,0.228485,0.548674,-0.468568,0.508138,-0.330534,0.234578,-0.314307,0.337994,-0.176871,0.247093,-0.165820,0.367585,0.146503,0.069937,0.172839,-0.091723,-0.217359,-0.667747,0.186912,0.147734,0.125012,-0.403383,-0.072667,-0.023965,0.221790,0.478108,-0.150031,-0.100613,0.358799,0.176085,0.119063,-0.074675,0.122961,-0.249940,0.020675,0.180761,-0.511691,0.020643,0.291475,-0.158033,-0.624968,-0.084284,-0.033281,-0.252396,0.049586,0.442568,-0.026734,-0.012058,0.412695,-0.656809,-0.172743,-0.245362,-0.329318,0.130540,-0.057794,0.078748,-0.543044,0.065037,0.063312,-0.222844,-0.266972,-0.002757,-0.252817,0.862561,-0.772539,0.286832,0.428745,0.169498,-0.235755,0.242461,-0.008928,0.004954,-0.513847,0.051281,0.324090,0.175651,0.373017,0.388046,0.292046,0.171153,0.032516,-0.375223,0.335375', '1420088', '10174444', '24284209', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6872244', '飞越老人院', '剧情', '续弦的老伴去世后，老葛（许还山 饰）在非血缘关系的儿女家处境尴尬，而跟儿子（韩童生 饰）的关系也始终没有松动。无奈之下，老葛辗转来到关山老人院，寻找当年同在一个单位的好友老周（吴天明 饰）。老周热情开朗，平日里组织这里的老人们参加各种各样的文体活动。为了实现各自人生最后的价值，这群老伙伴们毅然决定排练节目去天津参加比赛。可是，衰老与疾病让院长（颜丙燕 饰）无法下定决心开绿灯，而意外的事故更促使她对老周他们的表演下了禁止令。即便如此，老人们也从未放弃。他们决定偷偷跑出老人院，寻找生命中纯粹的快乐与意义……©豆瓣', '许还山', '张杨', 7.8, 49326, 'tt2401013', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1501564793.jpg', 0.6, 3.4, 25.1, 45.5, 25.3, '0.141258,-0.070519,-0.507980,0.423374,-0.024439,-0.442542,0.564082,0.150214,-0.574600,-0.405860,0.007056,0.563558,0.062221,0.495949,0.029653,-0.405387,-0.303205,-0.418771,0.106084,-0.056662,-0.117925,-0.470439,-0.097542,-0.274445,-0.198122,0.065914,0.443727,0.114375,-0.086025,0.811811,0.492392,0.109351,-0.102837,0.356061,-0.112599,-0.056375,0.145095,0.267498,-0.494514,-0.103037,0.193038,-0.048092,-0.285506,0.128577,0.280508,0.399822,0.602189,-0.152683,-0.212347,-0.166133,0.158064,-0.139915,0.019668,0.349682,0.281772,0.223415,0.242519,0.383483,0.078746,-0.000900,-0.006262,-0.076219,-0.643488,0.211489,0.371601,0.090575,-0.565759,0.242934,0.111748,-0.090037,-0.087224,-0.320114,0.373731,0.408025,0.220262,0.194942,-0.491859,0.021424,-0.231264,0.402520,0.855188,-0.175519,0.023501,0.171670,-0.232301,-0.303815,0.071970,-0.284962,-0.513903,0.183215,0.006418,0.182143,-0.141806,0.128817,-0.581772,-0.022101,-0.105040,-0.064216,0.040454,-0.314457,0.177268,-0.700341,0.051313,-0.365750,-0.365848,0.055302,-0.051685,-0.165125,0.676094,-0.660982,0.112270,0.248103,0.374330,-0.817353,0.718001,0.168735,0.242771,-0.389584,0.013716,0.108159,-0.235351,0.371813,0.045426,0.048889,-0.113475,-0.056144,-0.266126,0.283573', '3445516', '25721544', '3147969', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6872245', '诈欺游戏 -再生-', '剧情', '刚刚迎来毕业典礼的帝都大学学生筱宫优（多部未华子 饰）意外收到一个奇怪包裹，包裹表面写着“诈欺游戏（Liar Game）”，里面竟然有一封邀请函和1亿日元现金。她被神秘的LGT事务所胁迫参加重新复活的诈欺游戏，胜利的话将获得20亿日元的奖金，拒绝参加将背负巨额的债务。惊慌失措的筱宫顺着冷峻的观察员（芦田爱菜 饰）留下的线索，找到了在帝都大学心理学任教的秋山深一（松田翔太 饰）。显而易见，LGT这番用意是在逼迫秋山参赛，向其复仇。明知前途凶险，秋山坦然应战。此次游戏包括他在内总共有20人参加，看似简单的抢椅子游戏，实则充满陷阱，危机四伏。天才诈欺师秋山面临史无前例的挑战……本片根据甲斐谷忍的同名漫画改编。©豆瓣', '松田翔太', '松山博昭', 6.4, 11040, 'tt2078667', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1385158070.jpg', 2.8, 13.7, 51, 24.2, 8.3, '0.086019,0.121799,-0.382467,0.498574,-0.076064,0.255496,0.244192,0.062509,-0.262637,-0.215828,0.507996,0.664067,-0.220512,0.003174,0.294148,-0.169532,0.004330,-0.382861,-0.237587,-0.234298,-0.129670,-0.609269,-0.145872,-0.076139,-0.047877,-0.517895,0.829852,0.195371,-0.382127,0.768580,0.416269,0.442367,-0.161160,0.242129,0.066054,-0.147945,0.211894,0.366928,-0.004376,0.321704,-0.229479,-0.098431,-0.186584,0.213841,0.205398,0.510249,0.645240,0.052855,-0.152211,0.238625,0.657450,-0.489124,-0.483333,-0.151796,0.301651,0.274812,-0.174475,0.356858,-0.231839,0.130637,0.193937,-0.247449,-0.923709,-0.403984,0.265723,0.265466,-0.186486,0.443184,-0.366144,0.034498,0.069101,0.105455,-0.220798,0.174497,0.309049,0.065820,0.103459,0.222463,-0.387391,0.471369,0.238794,-0.343637,-0.040543,0.056519,-0.279296,-0.339923,0.213055,-0.469532,-0.200949,0.287295,0.153668,-0.036626,-0.000892,-0.252716,-0.486463,-0.179975,-0.084539,-0.322955,0.276226,-0.507493,-0.230103,-0.680091,-0.067064,0.170477,-0.347640,-0.074976,0.174810,-0.384244,0.705135,-0.492134,0.057847,0.365309,0.263313,-0.285413,0.538188,0.136520,-0.148274,-0.080986,-0.126044,-0.022353,0.319256,0.329198,0.106459,0.231253,-0.023395,-0.279214,-0.446153,0.355683', '25880986', '26759820', '27602116', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6872273', '盲探', '喜剧', '曾是“O记”杰出探员的庄士敦（刘德华 饰），四年前因某起案件双目失明，而今眼前一片漆黑的他仍乐此不疲捡起沉疴多年且悬而未决的无头之案调查，在给受害者讨回公道的同时赢得丰厚的悬红报酬。他判案手法独特，擅长在头脑中原原本本还原当事人所处的场景和持有的心情来追查线索。在追查“通渠水伤人事件”疑犯的过程中，庄偶然结识当年“O记”好哥们司徒法宝（郭涛 饰）的下属何家彤（郑秀文 饰）。何虽然办案经验不足，但身手了得，关键时刻救下了正处在危急关头的庄。她对这位名震一时的“破案之神”佩服得五体投地，因此请求庄Sir接手帮忙调查许多年前失踪的好友小敏的下落。看在百万赏金的份上，庄点头应允。在短短十天内，庄Sir和何家彤同时周旋在几宗案件之间，每起案件的真相交替浮出水面，而他们彼此的心也在生死考验的过程中渐渐拉近……©豆瓣', '刘德华', '杜琪峰', 7.2, 214922, 'tt2332707', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2003777772.jpg', 1.2, 5.5, 38.9, 43, 11.3, '0.038363,0.082558,-0.583900,0.599708,-0.034011,-0.073689,0.397146,-0.246933,-0.668433,-0.377380,0.157897,0.466950,-0.208654,0.145373,0.247398,-0.292356,-0.020493,-0.739215,-0.136442,-0.260903,-0.358697,-0.653292,-0.286252,-0.442606,-0.187252,-0.112679,0.352979,0.471257,-0.197707,0.363766,0.265409,0.179632,-0.427992,0.312351,-0.116744,-0.131877,-0.030401,0.299522,-0.255827,0.028215,0.054069,-0.682606,-0.062534,0.139586,0.357497,0.566073,0.618160,-0.098194,-0.403716,0.349167,0.291516,-0.340345,0.062167,-0.063336,0.526727,0.237330,0.261654,0.286428,-0.367418,-0.576772,-0.137646,-0.089434,-0.631563,-0.126308,0.393823,0.099080,-0.649987,0.263447,-0.126154,0.235499,-0.055100,-0.177982,0.083386,0.380402,0.118620,0.217263,0.051220,-0.203103,-0.347549,0.412551,0.521345,0.043196,-0.021647,0.115200,-0.025192,-0.594358,-0.236731,-0.219907,0.080755,-0.077475,0.453972,-0.115196,0.015796,0.318781,-0.238886,-0.144908,-0.240686,0.068610,-0.077801,-0.314200,-0.082493,-0.434685,-0.328771,-0.510564,-0.376277,0.102213,-0.008622,-0.578691,0.354192,-0.657216,0.110387,0.302179,-0.310377,-0.417634,0.620382,0.278399,0.103182,-0.251320,-0.278859,0.084412,0.449654,0.110936,0.117380,-0.007773,-0.173581,-0.139188,-0.582016,0.092838', '1300070', '3263169', '1299658', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6872936', '军火贩', '剧情', '由《宿醉》导演托德·菲利普斯执导的喜剧片，根据真实故事改编。已经成年的David（迈尔斯·特勒饰）终日只能靠给别人按摩挣点小钱，穷则思变的他决定自己创业，结果轻虑浅谋的David资产全部套牢。恰巧这时碰到了阔绰的童年伙伴Efraim（乔纳·希 尔饰），得知女友意外怀孕的David在Efraim的劝说下决定瞒着女友跟他做起了军火生意。事业慢慢开始风生水起，终于一次机会二人接到了军方三亿美元的大单，可是事与愿违......', '乔纳·希尔', '托德·菲利普斯', 7.3, 32607, 'tt2005151', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2327059162.jpg', 0.4, 2.9, 38.5, 46.1, 12.3, '0.100879,0.195570,-0.612994,0.272147,-0.104006,-0.601928,0.233298,0.088186,-0.393080,-0.325822,0.018332,0.575751,-0.120529,0.312832,0.626991,0.046086,-0.210293,-0.566441,0.096170,0.022397,0.016814,-0.438412,-0.346173,-0.228992,-0.226766,-0.171577,0.435939,-0.103845,-0.037954,0.260044,0.389278,0.064109,0.115323,0.110924,-0.007180,0.254905,0.063881,0.008620,-0.496107,0.169293,0.151832,-0.323596,-0.025945,0.161943,0.216155,0.612058,0.494502,-0.151706,-0.180772,0.141243,0.410669,-0.098988,-0.003815,-0.287870,0.149049,0.214419,0.391971,0.222311,-0.327880,-0.009763,-0.028722,-0.196881,-0.630104,-0.169707,0.119959,0.007035,-0.738721,0.202668,-0.283875,0.354508,-0.132487,-0.492115,-0.204982,0.640702,0.137679,0.361546,-0.346987,0.248061,-0.510511,0.591871,0.535619,0.024057,0.138182,0.581732,0.151295,-0.095299,0.073329,-0.311844,-0.392572,0.037728,0.450779,0.068153,-0.208791,0.243916,-0.468449,-0.285815,-0.308201,-0.252217,0.258572,-0.230791,0.108028,-0.403510,-0.274908,0.200609,-0.260804,0.228704,0.068563,-0.342457,0.412588,-0.729563,0.070707,0.606530,0.169932,-0.283328,0.331939,-0.014731,0.156901,-0.344863,0.099927,-0.219772,-0.169324,0.078239,0.343787,0.096361,-0.038991,-0.550615,-0.281773,0.298786', '1299965', '1986338', '30345227', '1293829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873042', '明日世界', '动作', '中年男子弗兰克·沃克（乔治·克鲁尼 George Clooney 饰）和身边的女孩凯茜·牛顿（布丽特·罗伯森 Britt Robertson 饰）大吐苦水，他慨叹现代社会充斥了战争、饥饿、灾难以及种种不公，他回忆起自己童年时代的一段经历。当年小小的弗兰克（托马斯•罗宾逊 Thomas Robinson 饰）带着自己的得意发明来到某主题公园，结果却碰了一鼻子灰。而美丽的少女雅典娜（拉菲•卡西迪 Raffey Cassidy 饰）偷偷伸出援手，让他见识了令人咋舌的未来世界。与之相对，凯茜则是对未来充满幻想的阳光女孩，她渴望有朝一日遨游太空。心怀梦想的她甚至私闯NASA，为此惹了不小的麻烦，不过却由此得到一枚神秘的徽章从而结识了弗兰克。这一老一少的命运相逢，让充满幻想的未来世界不再遥远……©豆瓣', '布丽特·罗伯森', '布拉德·伯德', 6.4, 64597, 'tt1964418', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2242653338.jpg', 2.3, 14.1, 52.6, 23.1, 7.9, '-0.022023,0.233625,-0.723105,0.535010,-0.348171,-0.224205,1.000519,0.082491,-0.510654,0.083084,0.258700,0.822486,-0.384631,0.350838,0.383050,0.129918,-0.210963,-0.582100,0.186851,-0.174663,-0.152741,-0.260232,-0.530326,-0.220406,-0.157664,-0.291480,0.595266,0.145477,-0.229157,0.374202,0.078197,0.432873,-0.016404,0.480341,-0.327527,0.060638,0.098713,0.398423,-0.353997,-0.192675,0.166772,-0.216533,-0.170419,0.364417,-0.442795,0.131764,0.543986,-0.451089,-0.148563,-0.391591,0.305762,-0.150048,0.025554,0.007924,-0.171931,0.084792,-0.129401,0.016115,0.009945,-0.294631,0.243717,0.017495,-0.636582,0.149750,0.006201,0.042590,-0.329798,0.439506,-0.155649,-0.036752,0.259817,-0.077016,0.021081,0.215226,0.465780,0.294959,-0.091405,0.061456,-0.342680,0.211581,0.307491,-0.059213,-0.211551,0.422999,-0.581081,-0.190641,-0.018802,-0.032606,-0.781340,0.022728,0.342010,-0.028649,-0.026717,0.547686,-0.603907,0.148353,-0.273051,-0.088614,0.231285,-0.451183,-0.185232,-0.541957,-0.335224,-0.526160,-0.411072,-0.154288,0.201870,-0.314415,0.735660,-0.624903,0.226583,0.485290,0.222461,-0.306051,0.821810,0.068309,0.006952,-0.427970,-0.101234,0.730218,-0.232326,0.114525,-0.017323,0.336189,0.136068,-0.005307,-0.244502,0.688110', '3097044', '1296992', '4058963', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873085', '21岁派对', '喜剧', '成绩优异的男孩杰夫·陈（贾斯汀·钱 Justin Chon饰）从来不会做出什么出格的事情。他正准备参加医学院的入学面试。面试的前一天，是他21岁的生日。在杰夫两个死党凯西（斯盖拉·阿斯丁 Skylar Astin饰）和米勒（迈尔斯·特勒 Miles Teller饰）的怂 恿和劝说下，他们相约去花花世界里庆祝杰夫的生日，也狠狠地疯狂一把。然而他们一开始喝酒就无法停止了。局面慢慢变得失去了控制，变得疯狂而可怕……©豆瓣', '迈尔斯·特勒', '乔恩·卢卡斯', 5.9, 7288, 'tt1711425', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2209867453.jpg', 5.2, 21.6, 51, 17, 5.1, '0.545661,0.033963,-0.785715,0.484335,-0.260999,-0.463729,0.616348,0.165975,-0.245824,-0.230324,-0.009561,0.520444,-0.550478,0.570900,0.460215,-0.168337,-0.206316,-0.846236,0.027537,0.203686,-0.312999,-0.489875,0.016018,-0.498671,-0.064360,0.033727,0.035690,-0.083341,0.064813,0.680526,0.485324,0.148660,0.479562,0.561088,0.361569,-0.070121,0.193366,-0.025716,-0.019758,0.154602,0.412394,-0.377202,-0.323041,0.291368,0.469636,0.481383,0.453431,-0.142322,-0.054113,-0.080449,0.340702,-0.275872,-0.116520,0.559764,0.253709,-0.084432,0.009931,-0.240315,-0.221861,0.073913,0.027531,-0.362482,-0.350882,0.126647,-0.090585,0.182336,-0.574645,0.064110,-0.290531,0.069797,0.180152,-0.635603,-0.070049,0.498397,0.257831,0.234920,0.024833,-0.423857,-0.337979,0.296864,0.734042,-0.029173,-0.328578,0.037562,-0.263218,-0.456030,-0.138605,-0.044620,-0.455467,-0.137778,0.529155,-0.188910,0.124063,0.326817,-0.359298,-0.368961,-0.202912,-0.443612,-0.203163,-0.200125,-0.012128,-0.497217,-0.061428,-0.364627,-0.340394,0.342535,-0.069936,-0.225548,0.472042,-0.931240,0.238400,0.344155,0.356469,-0.152198,0.314777,-0.104019,0.091281,-0.000278,0.061525,0.023306,0.006727,0.180514,0.244287,0.594920,0.208312,-0.034691,-0.266152,0.737763', '1301022', '2230893', '5977789', '25837574');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873143', '一条狗的使命', '剧情', '影片以汪星人的视角展现狗狗和人类的微妙情感，一只狗狗陪伴小主人长大成人，甚至为他追到了女朋友，后来它年迈死去又转世投胎变成其他性别和类型的汪，第二次轮回狗狗变成了警犬威风凛凛，再次转轮回，又成了陪伴一位单身女青年的小柯基犬。在经历了多次轮回之后，最终回到最初的主人身边。', '乔什·加德', '拉斯·霍尔斯道姆', 7.7, 360076, 'tt1753383', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2432493858.jpg', 0.6, 3.4, 29.4, 43.1, 23.5, '-0.118261,0.122560,-0.380834,0.425555,-0.375886,-0.556717,0.709449,-0.036070,-0.368103,-0.032215,0.149047,0.806894,-0.076698,0.784699,0.171823,-0.311681,-0.172112,-0.566371,-0.091455,0.178478,-0.530810,0.112986,-0.380458,0.056723,-0.025216,-0.368251,0.800463,-0.313122,0.022652,0.197687,0.341934,-0.059300,-0.220572,-0.145643,-0.465960,0.358304,0.017299,0.262823,0.034559,0.240230,-0.248878,-0.065625,0.082507,-0.194398,-0.270079,-0.028057,1.083003,-0.681799,-0.410692,-0.603802,0.563048,0.075125,-0.179838,0.100704,0.058213,0.362865,0.364898,-0.195466,0.071695,-0.089439,-0.060150,-0.010132,-0.409484,0.169390,-0.334955,0.228984,-0.377265,0.163890,0.256544,0.123429,0.299221,-0.555263,0.040535,0.027770,0.162278,0.443390,-0.264568,0.218520,-0.356791,0.171626,0.771137,0.088763,-0.514474,0.343318,0.024793,-0.745766,-0.047357,-0.303765,-0.186990,0.095769,0.301819,0.317683,-0.510990,0.489243,-0.735178,-0.067848,-0.266187,0.094458,-0.166567,-0.242848,-0.088854,-0.273836,-0.171037,-0.196055,-0.057561,0.074836,-0.002838,-0.438528,0.781477,-0.849361,0.534686,0.272310,0.277233,-0.723260,0.934642,-0.145473,0.287135,-0.507630,0.396421,0.498321,0.138951,0.239527,0.268444,-0.071894,-0.382483,0.364726,-0.866287,0.627380', '3731581', '3055049', '1417036', '5416009');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873176', '最高通缉犯', '惊悚', '影片改编自《锅匠，裁缝，士兵，间谍》作者约翰·勒·卡雷的小说。故事发生在当代的德国汉堡。一名神秘男子来到当地的穆斯林社区寻求帮助。此人有着一半车臣和一半俄罗斯血统，身上受了很严重的伤。他来到这里的目的是收回他父亲的巨额不法所得。周围人都人都对他的身份表示怀疑。他究竟是一名受害者还是一名贼，抑或更糟糕的，有着极端恐怖的目的？卷入这件事的还有一名英国银行家以及一名年轻的女律师。与此同时，一名老道的德国间谍也在时刻监视着他们，试图解开神秘男子的葫芦里究竟卖的什么药。', '菲利普·塞默·霍夫曼', '安东·寇班', 6.9, 9370, 'tt1972571', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2190138822.jpg', 1.2, 6.9, 45.3, 37.2, 9.5, '0.297574,-0.191339,-0.369049,0.604825,-0.215235,0.062947,0.906235,-0.083513,-0.538075,-0.463811,0.574495,0.722520,0.176942,-0.005107,0.383673,0.141890,-0.084930,-0.462193,-0.207885,-0.260649,-0.382115,-0.447431,-0.707218,-0.235374,-0.202518,-0.408929,0.516580,0.043137,-0.545703,-0.031114,0.483554,0.650144,-0.112655,0.355122,-0.112041,-0.185830,0.358852,-0.317265,0.032837,0.143215,0.028831,-0.383205,-0.223722,0.182334,-0.159808,0.401171,0.581871,-0.169767,-0.249081,0.011667,0.312287,-0.228870,0.094961,0.081252,0.370383,0.018855,0.285476,0.281982,0.083763,-0.030296,0.017164,0.056596,-0.772269,-0.068916,0.307938,0.319922,-0.405160,0.411764,-0.190889,0.010383,0.104149,-0.355333,0.281783,0.343558,0.004702,0.319507,-0.027311,0.001167,-0.671871,0.290987,0.748307,-0.017320,-0.166614,0.057351,-0.378478,-0.477809,-0.211060,-0.242317,-0.464829,0.078067,0.415592,-0.028412,-0.146471,0.217954,-0.458931,0.045543,-0.014830,-0.216597,-0.096060,-0.098860,0.033274,-0.404156,-0.225164,-0.406959,-0.081157,-0.009074,0.273259,0.027921,0.964841,-0.409470,0.096070,0.704653,0.242905,-0.486518,0.559210,-0.026016,0.118911,-0.210213,-0.659009,0.239730,0.400744,0.128181,-0.106113,0.355424,0.050338,-0.378494,-0.071005,0.145787', '3005387', '35262994', '24284209', '2028634');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873331', '八星抱喜', '喜剧', '夏凡（龚琳娜 饰）因为对丈夫失望，所以建立了一个名叫抱喜的网站，意图通过男人帮助女人改造男人。不得志的歌手谭冠荣（甄子丹 饰）赋闲在家，但空姐女友（应采儿 饰）不理解自己的苦衷。他的抱喜任务，是冒充富豪陪同遭家暴的歌星宋秋波（吴君如 饰）参加派对，向宿敌示威。狡黠律师黄百鸣虽然在打官司上非常在行，但是却因为长年疏于照顾，与女儿苏菲失和。他的抱喜任务是帮助富家女陈思思（杨幂 饰）选择适婚男友，以继承亡父的遗产。建筑工人彭坚（古天乐 饰）因为身份卑微，追女孩屡屡受挫。他的抱喜任务是为摄影师Julie Sun（陈慧琳 饰）充当男模。作家华一声（杜汶泽 饰）善于描写爱情，但是因为相貌平平不敢以真面目示人。他的抱喜任务是帮助一名失明女子谈笑（熊黛林 饰）感受爱情。这四个男人能否顺利完成他们的抱喜任务呢？……©豆瓣', '黄百鸣', '陈庆嘉', 4.9, 25809, 'tt2051818', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1355153383.jpg', 15.9, 34, 40.2, 7.1, 2.9, '-0.071846,-0.111341,-0.228097,0.572174,-0.267994,-0.035020,0.442978,0.154878,-0.505385,-0.284219,0.254680,0.650668,-0.035838,0.073982,0.038162,-0.003200,-0.062963,-0.466912,0.161585,0.147836,-0.235614,-0.306007,-0.070718,-0.315402,-0.330535,-0.150592,0.688046,-0.156637,-0.247156,0.474075,0.910730,0.368305,-0.113998,0.285437,0.048642,-0.353779,-0.001504,0.196756,-0.303998,0.167695,-0.104533,-0.319744,-0.063656,0.050521,-0.037079,0.378322,0.505582,-0.068013,-0.076496,-0.329585,0.181362,-0.371944,-0.042773,0.062993,0.024416,-0.102618,0.365556,-0.050240,0.016922,-0.095720,-0.004028,-0.212944,-0.480242,-0.107201,0.649726,0.145510,-0.355039,0.305338,-0.510137,-0.058705,0.063865,-0.250546,-0.059888,0.162904,0.097665,0.286583,-0.050290,0.401185,-0.375257,0.315595,0.188658,0.102904,0.165359,0.507194,-0.455000,-0.493189,0.024873,-0.188202,-0.614513,0.159454,-0.105346,-0.019129,0.057953,-0.191422,-0.154198,-0.262143,-0.090261,0.267174,-0.095639,-0.597102,-0.019857,-0.385057,-0.093715,-0.493602,-0.070907,-0.103345,0.198364,-0.522051,0.781134,-0.825824,-0.046642,0.163730,0.218155,-0.797628,0.713768,0.364626,0.171640,-0.668292,-0.138943,0.266814,-0.062093,-0.423945,-0.149866,-0.020869,-0.083434,-0.252297,-0.142475,0.180125', '6963575', '3445516', '7161707', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873655', '美国刺客', '动作', '米奇（迪伦•奥布莱恩Dylan O''Brien 饰）本是一位非常普通的美国青年，成长在一个幸福的家庭之中，有一个甜蜜交往的女友。然而，一场意外夺走了米奇父母的生命，让他沦为孤儿，米奇的女友也在恐怖袭击中丧生，几乎是在霎时之间，米奇失去了他生命里所有重要的人。中情局副主管艾琳（桑娜•莱瑟Sanaa Lathan 饰）同情于米奇的惨痛遭遇，决定给他一次报仇的机会，于是将他招募进了一个行动小组，负责训练米奇的小组组长是冷战时期的战斗经营斯坦（迈克尔•基顿 Michael Keaton 饰）。很快，斯坦发现了米奇身上异于常人的惊人天赋，而他们共同要面对的，是一个有可能将会导致第三次世界大战的惊天阴谋。©豆瓣', '迪伦·奥布莱恩', '迈克尔·科斯塔', 6, 6801, 'tt1961175', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2496472286.jpg', 3.5, 21.1, 54.3, 15.7, 5.3, '0.230901,-0.057119,-0.625470,0.550431,-0.320165,-0.327258,0.713218,0.099688,-0.697811,-0.067758,0.266016,0.927481,0.032050,0.018586,0.299742,-0.128232,0.035385,-0.674591,-0.264641,-0.111387,-0.304186,-0.655738,-0.517149,-0.237829,0.003089,-0.452311,0.513713,-0.105374,-0.114428,0.726555,0.501687,0.506833,-0.026588,0.469714,0.119920,-0.126337,0.344614,-0.204901,-0.253460,0.290525,-0.123817,-0.002565,-0.013510,0.262063,-0.075691,0.387228,0.729619,-0.292811,-0.178265,-0.253690,0.544828,-0.234426,-0.183651,0.002953,0.353359,0.113230,0.175284,0.189092,-0.184770,0.029449,0.247136,-0.061703,-1.014741,-0.048723,0.107209,0.283270,-0.704245,0.464428,0.132611,0.027451,0.263866,-0.285828,0.210818,0.339563,0.397089,0.424270,-0.076486,0.054265,-0.458956,0.074291,0.872681,-0.225169,-0.308176,0.197331,-0.277795,-0.305369,-0.056944,-0.311644,-0.644913,0.203143,0.417989,-0.053824,-0.092940,0.318404,-0.651689,0.151350,-0.516307,-0.237538,-0.304312,-0.255108,0.060634,-0.571557,-0.155761,-0.184045,-0.478498,0.112165,0.074599,-0.335206,0.852261,-0.918493,0.255305,0.606650,0.122111,-0.315064,0.535318,0.252044,0.507934,-0.314163,0.057867,0.350534,0.047218,0.036301,-0.074301,0.302053,0.103005,-0.027420,-0.328103,0.462043', '1793491', '35030151', '1874704', '35144311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873657', '美国骗局', '剧情', '一次偶然中，埃文（克里斯蒂安·贝尔 Christian Bale 饰）遇见了性感美艳的脱衣舞女西德尼（艾米·亚当斯 Amy Adams 饰），趣味相投的两人一见钟情，很快就打得火热。没想到，埃文是一个职业骗子，在他的鼓动和“爱情的力量”影响之下，西德尼毅然入伙，两人联手合作，将“事业”经营的有声有色。然而，常在河边走哪有不湿鞋，警方早已经盯上了行事作风颇为高调的埃文和西德尼，终于，在一次精密筹划的行动中将两人捉拿归案。经不住FBI探员里奇（布莱德利·库珀 Bradley Cooper 饰）的游说和诱惑，埃文和西德尼决定与其合作，“戴罪立功”。尽管拾起了“老本行”，但这次一次，埃文和西德尼显然站在了正义的那一方，因为他们的对手是那些贪赃枉法的腐败官员。©豆瓣', '克里斯蒂安·贝尔', '大卫·O·拉塞尔', 6.7, 84421, 'tt1800241', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2188108927.jpg', 1.5, 8.9, 48.7, 32.7, 8.3, '0.434632,-0.261300,-0.782073,0.610394,-0.321327,-0.456030,0.578353,0.185275,-0.479291,-0.119671,0.211784,0.823237,-0.223246,-0.075676,0.253182,-0.125400,-0.354374,-0.715820,0.040706,0.021645,-0.032195,-0.686500,-0.351729,-0.203554,-0.236485,-0.150739,0.536924,-0.027126,-0.270670,0.624518,0.435793,0.318217,-0.126124,0.524528,-0.110359,-0.135204,0.421852,-0.034039,-0.304954,0.304702,0.192104,-0.246624,-0.167187,0.064953,0.199625,0.459941,0.412894,-0.442859,-0.085225,0.108655,0.176925,-0.379592,0.058592,0.273238,0.420261,-0.153113,0.183493,0.355322,-0.238558,-0.166236,0.038833,-0.108234,-0.722809,-0.054068,-0.039100,0.133421,-0.575612,0.471107,0.034761,-0.139084,-0.123562,-0.293212,0.036891,0.488754,0.437903,-0.058302,0.135179,-0.045763,-0.447822,-0.134167,0.601757,0.310392,-0.059832,0.416856,-0.132955,-0.314835,-0.106916,-0.174107,-0.409493,-0.183936,0.423025,-0.085107,-0.052363,0.247008,-0.575106,0.006466,-0.480629,0.165167,-0.107542,-0.474332,0.005877,-0.760634,-0.289142,-0.605654,-0.384951,0.079479,0.091494,-0.165402,0.538354,-0.842734,-0.161354,0.519776,0.191096,-0.353467,0.555876,0.111780,0.088057,-0.118467,-0.069020,-0.164314,0.105729,0.035747,0.408558,0.515251,0.162876,-0.281077,-0.139802,0.253522', '1301022', '20277433', '1307442', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873736', '愤怒的小鸟', '喜剧', '在一座与世隔绝的小岛上，生活着种类繁多且快乐无忧的小鸟。不过他们中间总有异类存在，比如离群索居的胖红（杰森·苏戴奇斯 Jason Sudeikis 配音），孤儿出身且有些另类的怪异容貌让他成为其他鸟儿嘲笑和奚落的对象。久而久之，胖红也养成了促狭易怒的性格。在被法官判处参加情绪管理课程期间，他结识了速度极快的飞镖黄（乔什·加德 Josh Gad 配音）和一不小心便会引起爆炸的炸弹黑（丹尼·麦克布耐德 Danny McBride 配音）。三个怪胎由此闹出不少的笑话。未过多久，神秘的绿猪莱纳德（比尔·哈德尔 Bill Hader 配音）带着手下来到小岛，他们展现出友善的面孔，可又仿佛在暗中策划这什么。岛上只有胖红对绿猪的到来充满戒备，而他的担忧也很快得到了验证……©豆瓣', '杰森·苏戴奇斯', '费格尔·雷利', 7.2, 113674, 'tt1985949', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2352310242.jpg', 1, 5.4, 40.2, 39.1, 14.4, '0.304123,-0.023414,-0.628250,0.525608,-0.087132,-0.059963,0.695280,0.174561,-0.270523,-0.085034,0.044617,0.477957,-0.398658,0.111146,0.154528,-0.137576,-0.230887,-0.282654,-0.088196,-0.266771,-0.156090,-0.345838,-0.276826,-0.227836,-0.007555,-0.533040,0.299784,0.001529,-0.109453,0.587407,0.255627,0.233947,-0.051202,0.319259,-0.193504,-0.001003,-0.068138,-0.023705,-0.035148,-0.037820,-0.060855,-0.130427,-0.214355,-0.010724,-0.089137,0.431187,0.549630,-0.178627,-0.221879,0.048958,0.154164,-0.376256,0.047449,0.016893,0.330345,-0.110179,0.019591,-0.084154,-0.156452,0.242821,0.019754,0.003513,-0.521349,0.226622,-0.030595,0.405848,-0.277141,0.368868,0.107107,-0.290054,-0.174156,-0.160347,0.130691,0.029100,0.131042,0.356343,0.027858,0.356436,-0.499247,-0.118042,0.503291,0.111286,-0.497364,0.202496,-0.283619,-0.293508,0.006872,-0.439897,-0.339284,-0.149240,0.449325,-0.195621,-0.217308,0.231987,-0.636751,0.098764,0.003254,-0.109418,-0.123096,-0.554795,-0.131175,-0.801301,-0.082165,-0.607691,-0.404043,-0.206297,0.185468,-0.284618,0.709286,-0.926078,0.269410,0.303298,0.099478,-0.230149,0.201318,-0.024601,0.055920,-0.057320,-0.115865,0.073742,0.302656,0.287188,0.205740,0.398296,0.058450,-0.208294,-0.283024,0.585923', '1420088', '1292219', '25922902', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873740', '安妮：纽约奇缘', '剧情', '安妮（奎文赞妮·瓦利斯 Quvenzhané Wallis 饰）从小就被父母抛弃，然而，乐观坚强的她一直都相信着，自己的父母总有一天会回来同她相认。安妮生活在汉尼根小姐（卡梅隆·迪亚茨 Cameron Diaz 饰）的家中，在那里，日子算不上好过，然而，这并没能浇灭安妮对于生活的热情和对于未来的希望。威尔（杰米·福克斯 Jamie Foxx 饰）是一名富有的商人，野心勃勃的他决心竞选纽约市长。在副总裁格蕾丝（萝丝·拜恩 Rose Byrne 饰）和竞选顾问盖伊（鲍比·坎纳瓦尔 Bobby Cannavale 饰）的怂恿之下，威尔做出了一个惊人的决定——收养安妮，企图依靠这一举动来为自己赢得更高的支持率。然而，古灵精怪的安妮哪会乖乖听从他的摆布呢？©豆瓣', '杰米·福克斯', '威尔·古勒', 6.4, 5238, 'tt1823664', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2220435750.jpg', 2.6, 12.7, 53.4, 23.1, 8.2, '0.230248,0.070179,-0.717440,0.456127,-0.374002,-0.295141,0.608707,0.373079,-0.356010,-0.209573,0.244534,0.849975,0.032193,0.085984,0.372809,0.134202,-0.294427,-0.524167,0.130970,0.137324,0.186495,-0.702269,-0.386871,-0.278093,-0.074961,-0.323802,0.456548,-0.208632,-0.018922,0.572011,0.450167,0.285500,0.395504,0.329889,-0.018426,0.011246,0.169908,0.006035,-0.317780,0.314545,0.149423,0.037500,-0.094863,0.273048,0.234772,0.163083,0.209024,-0.334358,-0.125892,-0.022723,0.172271,-0.333075,0.176145,0.233769,0.200879,-0.149625,0.218317,0.355175,-0.246446,0.015657,0.323537,-0.077313,-0.791311,0.152197,0.248242,0.182584,-0.779129,0.384044,-0.066254,-0.066127,0.212696,-0.464804,-0.116035,0.328653,0.053322,0.332885,-0.307598,0.196757,-0.458412,0.054349,0.559300,0.008164,-0.298937,0.149380,-0.298986,-0.150653,0.073628,-0.441864,-0.841515,-0.133950,0.119842,0.055209,-0.159854,0.262217,-0.208497,-0.074378,-0.379059,-0.145759,0.118543,-0.596289,0.131736,-0.363604,-0.018325,-0.453571,-0.484150,-0.120312,-0.134948,-0.408471,0.794166,-0.932300,0.401070,0.449593,0.357192,-0.548289,0.663199,0.507753,0.172740,0.039210,-0.159406,0.374604,-0.111219,0.060867,-0.071703,0.179857,0.193264,-0.374377,-0.211085,0.478330', '1292720', '1877596', '1783461', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873819', '机器纪元', '科幻', '21世纪中叶，地球环境遭到巨大的破坏，人类文明和信仰不可遏止地崩塌。在一片乱象的关头，名为ROC的科技公司凭借他们研发的“朝圣者 7000”智能机器人迅速崛起。朝圣者深入民间每一个角落，帮助人们从生到死处理身边的一切事务。在两条根本原则的约束下，机器人们任劳任怨，不辞辛苦，与此同时也遭遇种种残酷无情的对待。贾克·波根（安东尼奥·班德拉斯 Antonio Banderas 饰）是ROC旗下的一名保险理赔员，在工作中他意外发现，许多朝圣者不仅被人私自篡改，连根本原则都遭到破坏。机器人们或伤害他人，或者自残，令贾克隐隐察觉背后似乎有什么阴谋存在。他离开城市前往贫民窟寻找真相，在此见识到机器人可丽儿自我修复的神奇一幕。而执着的追索，也将贾克置身于莫大的危险中央……©豆瓣', '安东尼奥·班德拉斯', '加贝·伊班内兹', 6.3, 19558, 'tt1971325', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2213751986.jpg', 3.2, 15.5, 49.7, 24.1, 7.5, '0.230411,0.130251,-0.712301,0.375297,-0.184182,0.290258,0.558087,0.022297,-0.717473,-0.369299,0.325741,0.583057,-0.086834,-0.153531,0.157092,-0.201528,-0.174900,-0.423074,-0.059257,-0.014908,-0.258312,-0.372161,-0.441126,-0.468702,-0.183488,-0.465482,0.657491,0.404482,-0.505493,0.172250,-0.108928,0.339626,-0.430477,0.542469,0.091309,-0.193396,0.057905,-0.192048,-0.115351,-0.026634,-0.291657,-0.223025,-0.025149,0.211601,-0.285611,0.355158,0.550022,-0.390329,-0.363598,-0.237428,0.547643,-0.274413,0.109862,0.125846,0.221284,0.005839,-0.141725,0.357357,-0.154014,0.209015,0.230823,-0.089993,-0.850263,-0.464078,0.076472,0.251117,-0.488725,0.123943,0.023003,-0.131150,-0.127860,-0.313132,0.210299,0.193618,0.322598,0.458985,-0.339482,-0.157037,-0.416833,-0.058171,0.630132,-0.177733,-0.552108,0.053174,-0.232871,-0.333525,-0.342579,-0.278644,-0.430936,-0.114561,0.115294,0.236677,-0.209578,0.469365,-0.644990,0.258352,-0.223848,-0.380665,-0.117024,-0.417247,-0.063245,-0.874396,0.092756,-0.094933,-0.312616,0.165044,0.001452,-0.278234,0.606411,-0.605825,0.255802,0.568576,0.336358,-0.454445,0.531271,-0.231177,0.205314,-0.130935,-0.166381,0.509737,0.226204,0.515674,-0.293040,-0.031531,0.041985,0.094299,-0.038576,0.314506', '1307897', '1793491', '2369613', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873851', '刺客学妹', '喜剧', '表面看来，梅根（海莉·斯坦菲尔德 Hailee Steinfeld 饰）是一位天真美丽的十六岁少女，可实际上，她的真实身份却是享誉全国的职业杀手。在本应该尽情挥洒青春光彩的年纪，梅根却同鲜血和枪支为伴，长久以来打打杀杀躲躲藏藏的漂泊生活，令梅根心生退意。在大费周折伪造了自己的死亡现场后，拥有全新的名字和身份的梅根来到了梦寐以求的高中，在这里，她只是一位平凡的高中三年级女生，即将享受只属于她的高中生活。刚开始，一切看起来都是那么的美好，可渐渐地，为了保守秘密，梅根不得不制造了一个又一个谎言，与此同时，梅根那挥之不去的过往亦如影随形。©豆瓣', '海莉·斯坦菲尔德', '凯尔·纽曼', 5, 6543, 'tt1731701', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2258383398.jpg', 13.5, 39, 36.7, 7.5, 3.4, '0.267075,0.235269,-0.631303,0.498792,-0.468502,-0.197829,0.869815,0.080946,-0.416552,-0.375312,0.185408,0.862620,-0.092536,0.567048,0.166159,0.047553,-0.101566,-0.686973,0.002284,-0.428703,0.098021,-0.296528,-0.428966,-0.147190,-0.142684,-0.316247,0.673842,0.238900,-0.152838,0.412654,0.247266,0.075948,-0.029906,0.362214,-0.537134,-0.444315,0.133459,0.246925,-0.061287,-0.122844,-0.013525,-0.310679,-0.056969,0.194167,-0.030208,0.377610,0.701789,-0.249316,-0.082512,0.022663,0.442618,-0.135491,-0.078969,0.015954,0.152645,-0.163244,0.115778,0.012015,0.009322,0.079978,-0.034551,-0.279411,-0.865275,-0.074737,0.181190,0.263200,-0.516160,0.681165,0.039035,-0.367514,0.149869,-0.227367,0.037164,0.095655,0.189580,0.287640,-0.169345,0.139014,-0.466848,0.474598,0.658804,0.213954,-0.552425,0.722796,-0.537909,-0.347054,-0.231931,-0.251045,-0.640961,-0.123370,0.058481,0.027185,-0.162795,0.366920,-0.555495,0.052443,-0.153275,0.032331,-0.071825,-0.525746,-0.283055,-0.221887,-0.360010,-0.599190,-0.391393,0.048251,0.124618,-0.142132,0.924935,-0.913503,0.194116,0.396373,0.010390,-0.365261,0.467151,0.449336,0.052451,-0.130445,-0.145697,0.573567,-0.094342,0.322597,-0.191073,0.458857,-0.126011,-0.017908,-0.518394,0.842079', '1292062', '24756472', '4817024', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6873905', '成长边缘', '剧情', '娜丁（海莉·斯坦菲尔德 Hailee Steinfeld 饰）从小就是一个性格古怪孤僻不合群的姑娘，因此常常受到同学的欺负。克里斯塔（海莉·路·理查森 Haley Lu Richardson 饰）好像一道光，照亮娜丁的生活，她们从相识起便形影不离，互相分享快乐和秘密，时光荏苒，两个女孩长大走进了高中校园，她们之间的感情从未改变。娜丁的哥哥达里安（布莱克·詹纳 Blake Jenner 饰）英俊帅气阳光开朗，他的存在衬得愤世嫉俗少年老成的娜丁显得更加不合时宜，但娜丁不在意，因为她拥有克里斯塔的友谊。然而某一日，娜丁震惊的发现克里斯塔和达里安竟然躺到了一张床上，与此同时，娜丁爱上了名为尼克（亚历山大·卡尔弗特 Alexander Calvert 饰）的男生，可她根本无法打入他所在的圈子。©豆瓣', '海莉·斯坦菲尔德', '凯莉·弗莱蒙·克雷格', 7.6, 33744, 'tt1878870', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2367571887.jpg', 0.4, 2.7, 29.5, 48.9, 18.4, '0.338735,-0.319212,-0.470045,0.634087,-0.056309,-0.189507,0.927906,0.193713,-0.234720,-0.428340,-0.333442,0.540581,-0.254780,0.872482,0.513131,0.303633,-0.560125,-0.568887,0.174612,-0.093871,-0.094916,-0.649332,0.127014,-0.412990,-0.060807,-0.392524,0.283596,-0.094651,-0.282188,0.699030,0.324477,0.140385,-0.259104,0.634340,0.109421,0.144444,0.177089,-0.176566,0.132043,-0.359976,0.129322,0.049258,0.083272,0.076967,0.420629,0.357428,0.584459,-0.536945,0.039562,-0.027609,0.529189,-0.020336,0.223419,0.141861,0.184545,-0.315760,0.030702,-0.353952,-0.158976,-0.032113,0.294937,-0.485503,-0.268533,0.545933,0.197375,-0.129531,-0.286731,0.504558,0.167601,-0.144646,0.090610,-0.033995,0.011926,0.127938,0.201536,-0.146054,-0.170373,0.187498,-0.475660,-0.339034,0.483117,0.198459,-0.279412,0.468814,-0.394158,-0.537572,-0.515390,-0.111474,-0.504758,-0.164234,0.438264,-0.152700,0.295704,0.223775,-0.512934,-0.360759,-0.175183,0.341121,0.109956,-0.408886,-0.355519,-0.331617,-0.155969,-0.715205,-0.445960,0.364885,-0.455359,-0.568030,0.717367,-0.787381,0.094119,0.064432,0.185435,-0.242451,0.768162,-0.209772,0.122055,-0.171941,0.046962,0.934674,0.340831,-0.246370,0.369469,0.436901,-0.302930,0.454703,0.050997,0.675168', '25828521', '1303031', '2131640', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6874140', '童军手册之僵尸启示录', '喜剧', '《鬼入镜:诅咒》克里斯多福蓝登最新执导作品。三位童子军在他们露营的最后一晚，经由拯救被殭尸入侵的小镇，发现到友谊的可贵。在惊悚气氛中添加疯狂的搞笑元素，带来超劲爆的限制级恐怖喜剧！', '豪斯顿·塞奇', '克里斯托弗·兰登', 6.8, 16482, 'tt1727776', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2273283490.jpg', 1.3, 8, 49.7, 32.1, 8.9, '0.110364,0.258015,-0.864256,0.315759,0.184853,0.247662,1.033105,-0.078009,0.030851,0.059712,0.384965,0.677386,-0.789919,-0.015704,0.501126,-0.050887,0.045763,-0.333751,-0.157930,0.112330,-0.382558,0.029976,-0.629006,-0.259512,-0.066905,-0.979616,0.264187,0.474462,-0.573632,0.189729,0.213131,0.236193,-0.406177,0.187770,-0.003370,0.341823,0.302860,-0.004460,-0.077636,0.138048,-0.169333,-0.462102,-0.227943,0.282149,0.004442,0.217989,0.799622,-0.421783,-0.410449,0.473114,0.757826,-0.253916,-0.422072,-0.013568,0.033271,0.173812,0.052952,-0.205722,-0.189921,0.281643,-0.083568,-0.061837,-1.383389,0.167440,0.054655,-0.001697,-0.085973,0.625070,0.011424,-0.316841,0.353523,-0.339262,0.261355,-0.141038,0.360662,0.529562,0.086530,0.007293,-0.089556,0.327360,0.727385,-0.247138,-0.666487,0.304986,-0.207744,-0.133467,-0.090002,-0.380651,-0.001294,0.014456,0.919589,0.118014,0.013362,0.442857,-1.006724,-0.121163,0.079448,-0.262903,-0.286367,0.044519,-0.326960,-0.901015,-0.317001,-0.061160,0.107263,0.242183,0.173101,-0.384470,0.742571,-0.578714,0.380175,0.716173,0.063682,-0.305193,0.580002,0.001773,-0.302384,0.112582,-0.382443,0.113147,0.227082,0.579186,0.587732,0.545592,-0.252389,-0.079382,-0.704157,0.540001', '3318306', '1874704', '1308784', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6874403', '再次出发之纽约遇见你', '喜剧', '格雷塔（凯拉·奈特莉 Keira Knightley 饰）抛弃了一切跟随着男友戴夫（亚当·李维 Adam Levine 饰）来到美国纽约实现他们的音乐和爱情梦想，没想到曾经幻想过的美好一切化作泡影，在获得了更好的工作机会后，戴夫果断抛弃了格雷塔，留下她一人苦苦在底层挣扎。丹（马克·鲁法洛 Mark Ruffalo 饰）最近的生活也不好过，他发现自己无法从思念前妻马瑞安（凯瑟琳·基纳 Catherine Keener 饰）的感情中走出来，与此同时，他的女儿维奥莱特（海莉·斯坦菲尔德 Hailee Steinfeld 饰）正处于一生中最叛逆的阶段。丹和格雷塔，命运让这失意的两人于一间小小的酒吧里相遇了，等待着他们的，会是怎样充满波折而又浪漫满满的故事呢？©豆瓣', '凯拉·奈特莉', '约翰·卡尼', 8.6, 401763, 'tt1980929', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2250287733.jpg', 0.2, 0.8, 12.3, 43, 43.7, '-0.003638,0.229408,-0.889074,0.527769,-0.058473,-0.379643,0.976497,0.140195,-0.488229,-0.154954,-0.062321,0.599698,-0.143400,0.368484,0.367996,0.096017,-0.538695,-0.686166,0.228247,-0.242675,-0.260835,-0.373303,-0.137048,-0.180938,-0.255063,-0.393708,0.629854,0.081676,0.184718,0.187475,0.370611,0.490588,-0.076709,0.391677,0.052526,0.325086,0.368917,0.044698,-0.539745,0.248167,0.129830,0.122861,-0.105243,0.191450,0.017589,-0.041336,0.704309,-0.398396,0.162533,0.062939,0.192081,-0.126307,-0.061386,0.111920,0.016712,-0.151716,0.167642,0.088777,-0.454458,-0.106778,0.216630,-0.109167,-0.582936,-0.317875,-0.133569,0.129351,-0.700077,0.449188,0.080539,0.035636,0.341592,-0.358772,0.060464,0.307092,0.351367,0.252237,-0.233426,-0.316261,-0.543095,0.270636,0.475669,-0.083510,-0.214344,0.515590,-0.342259,-0.217378,-0.099683,-0.048084,-0.688231,-0.243688,0.454268,0.163216,-0.043429,0.527928,-0.365247,-0.021939,-0.478954,-0.126195,0.067205,-0.655271,-0.181945,-0.476280,-0.071504,-0.302315,-0.325463,0.050763,-0.288963,-0.228707,0.513937,-0.987005,0.441358,0.402934,0.245400,-0.024505,0.549138,0.176335,0.204463,-0.290908,-0.008930,0.732401,-0.251071,0.127225,0.198134,0.258220,0.220927,0.027831,-0.486286,0.886387', '1292211', '1305666', '1291835', '24708493');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6874456', '饥饿游戏2：星火燎原', '动作', '经历生死的凯特尼斯（詹妮弗·劳伦斯 Jennifer Lawrence 饰）和皮塔（乔什·哈切森 Josh Hutcherson 饰）得到了74届饥饿游戏冠军享有的一切待遇，但是两人的关系变得很尴尬，凯特尼斯无法放下昔日男友盖尔（利亚姆·海姆斯沃斯 Liam Hemsworth 饰），甚至还想要跟他远走高飞。凯特尼斯和皮塔越来越受到人民的欢迎，加上他俩假扮情侣的事情激怒了斯诺总统（唐纳德·萨瑟兰 Donald Sutherland 饰），他联合新的游戏设计师（菲利普·塞默·霍夫曼 Philip Seymour Hoffman 饰）开展了25年一届的“世界级限赛”，要求抽出12个区的历届男女冠军各一人参加，旨在杀死凯特尼斯。皮塔为了保护凯特尼斯，代替黑密曲（伍迪·哈里森 Woody Harrelson 饰）参赛，一对“恋人”又踏上了征程。在赛事中二人结交了不同区的盟友，同时皮塔继续对凯特尼斯表露真情，而她对皮塔的态度也有所变化，可惜事情并不像他们想象的一样，等待他们的只有阴谋。', '詹妮弗·劳伦斯', '弗朗西斯·劳伦斯', 7.4, 249856, 'tt1951264', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2156684911.jpg', 0.9, 4.3, 35.7, 44, 15.1, '0.277918,-0.336488,-0.571481,0.349604,0.107264,-0.245801,0.663649,0.160388,-0.503064,-0.119787,0.231673,0.983985,-0.237018,-0.055470,0.437761,0.080447,-0.669102,-0.811337,0.283150,-0.204214,0.188271,-0.696925,-0.294061,-0.066103,-0.212715,-0.581194,0.544673,-0.296997,-0.100439,0.662988,0.425784,0.151562,0.102052,0.338483,0.264555,-0.249544,0.516848,0.150717,-0.598846,0.093249,-0.199152,0.293879,-0.411102,0.346460,0.315649,0.403225,0.232931,-0.370837,0.203910,-0.054396,-0.123747,-0.315169,0.123009,0.255101,0.016320,-0.048108,0.131966,0.482591,-0.033544,0.161221,0.206589,-0.267051,-0.698972,0.230401,0.097541,0.391720,-0.408935,0.421634,-0.422103,-0.144448,0.128660,-0.090433,-0.122664,0.413489,0.355865,-0.041104,-0.092745,-0.269258,-0.493280,-0.022187,0.565842,-0.049575,-0.401430,0.187107,-0.229116,-0.523774,-0.401746,-0.150500,-0.617772,0.021596,0.216024,0.161478,0.024893,0.525740,-0.655862,-0.212462,-0.230287,-0.369079,0.066168,-0.472800,0.336123,-0.853464,-0.050009,-0.584904,-0.437394,-0.419645,0.209313,-0.508469,0.537074,-0.834436,0.129329,0.167703,0.377572,-0.389825,0.373354,0.245910,0.267554,-0.315744,-0.258196,0.262822,-0.056844,-0.074896,0.