INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6874475', '混沌行走', '动作', '人类在与地球相似的遥远外星建立了新家园，但这个星球上却有一种病毒，男人感染后可以听到其他人和动物的心声，每个男人脑子里的想法都能被他人听到，人与人之间不存在隐私，新星球上的普伦提司镇的男人们就不堪忍受自己的想法被人听见。托德·赫维特（汤姆·赫兰德 饰）是出生于这座小镇的 男孩，他的认知中小镇没有女人是因为该星球土著居民蓝光兽家园被人类侵犯时故意让人类感染了噪音病毒，他们还杀光了所有女性。托德对此深信不疑，直到他遇到一个女孩。托德在小镇附近的森林里遇到了一个叫维奥拉（黛西·雷德利 饰）的女孩，她来自遥远的地球，她的飞船因故坠毁在森林里，普伦提司镇的镇长在得知这个消息后立刻展开对他俩的追杀，托德为了保护女孩维奥拉只好一起出逃，开始了一段他意想不到且危机重重的星球冒险。', '汤姆·赫兰德', '道格·里曼', 5.2, 16039, 'tt2076822', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2676934276.jpg', 8.6, 34.4, 48.4, 6.9, 1.6, '0.506209,0.332091,-0.953591,0.640657,-0.236248,0.205395,0.950244,-0.172446,-0.616897,-0.109007,0.011809,0.884268,-0.117878,0.278186,0.203955,0.394376,-0.280475,-0.454766,-0.016601,-0.491990,-0.592985,-0.298484,-0.331383,-0.675334,-0.255260,-0.526064,0.490199,0.271550,-0.277238,0.064826,-0.033943,0.389121,-0.118783,0.634599,-0.359197,0.064574,0.134945,-0.190366,-0.040706,0.202272,-0.223470,0.108079,-0.039278,0.437209,-0.301169,0.306090,0.794733,-0.453918,-0.098324,-0.235733,0.067297,-0.256677,0.171138,-0.110277,0.505585,-0.437160,0.150241,0.116177,0.000285,-0.128792,0.134615,0.058213,-0.522304,0.000111,0.006055,0.286605,-0.293911,0.362665,-0.013353,-0.135298,0.121682,-0.225010,0.382660,0.164080,0.305860,0.380096,-0.078486,-0.174676,-0.534499,-0.072482,0.842628,-0.069870,-0.498100,0.206095,-0.513689,-0.634205,-0.212368,-0.154255,-0.631983,0.079087,0.138351,0.066506,-0.496134,0.441232,-0.633321,0.230904,-0.345944,-0.126158,-0.060220,-0.409419,-0.303624,-0.410919,-0.079552,-0.295872,-0.303163,0.258325,-0.039132,0.072218,0.759790,-0.848688,0.144800,0.784801,0.509809,-0.330124,0.626897,-0.218429,0.039619,-0.347856,0.141777,0.299092,0.180198,0.354600,0.027972,0.254079,-0.100869,-0.062466,-0.242960,0.642921', '34461680', '3055049', '3005387', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6874567', '惊叫大电影', '喜剧', '在汽车影院行将关张之际，老板瑟西老头怀着对威尔斯等电影前辈天才的敬意，要奉献给恐怖片影迷们一个难忘的电影之夜，于是多部恐怖片连番上演：《巨型精子》讲述一个少精单身汉使用了可以令精子强壮的新药，导致他的精子居然成长为楼房般巨大的怪兽，在纽约城内肆意破坏；《少年熊人》讲述对女友冷淡的少年瑞奇（布伦特·柯里根 Brent Corrigan 饰），偶然与几个黑衣青年相遇，而因为他们，瑞奇变成了恐怖的同性恋熊人；《弗兰肯斯坦的日记》讲述希特勒从弗兰肯斯坦的后人手中夺走了复活死人的笔记，遂亲手造出了犹太形象的活死人……正当银幕上放映电影时，看电影的人们遭遇了僵尸的袭击……©豆瓣', '理查德·雷西尔', '亚当·格林', 6.5, 6505, 'tt1727252', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1338063205.jpg', 5, 14.8, 41.5, 26.4, 12.3, '0.125714,-0.283129,-0.388225,0.453710,0.152397,-0.417096,0.888402,0.111296,-0.337929,-0.137416,0.461454,0.725917,-0.354793,0.149917,0.194718,-0.112314,-0.247271,-0.596421,-0.377894,0.160063,-0.146843,-0.099005,-0.302133,-0.223853,0.055422,-0.538982,0.476124,-0.023944,-0.319889,0.431279,0.267677,0.252886,0.072019,0.110200,-0.058529,0.123601,0.186898,-0.139915,-0.167963,0.365788,0.029943,-0.110489,-0.050139,0.108520,-0.384959,0.280975,0.902058,-0.352798,-0.125885,-0.275433,0.553451,-0.083407,-0.059450,0.166022,0.231010,0.118657,0.161577,-0.123943,-0.008612,-0.078440,0.056152,-0.034452,-0.640870,-0.008248,-0.118110,0.315294,-0.604870,0.493700,0.085957,0.239209,0.138326,-0.138036,-0.007558,-0.033510,0.425922,0.418428,0.172197,-0.175101,-0.366809,0.510575,0.232484,0.172988,-0.377795,0.461814,-0.020558,-0.284832,-0.070591,-0.067954,-0.554751,0.065983,0.629038,-0.257591,-0.250452,0.385836,-0.654456,-0.121384,-0.411636,-0.100340,0.059418,-0.098561,-0.507674,-0.966484,-0.194582,-0.123275,0.098416,-0.189308,0.131841,-0.148121,0.896631,-0.505042,0.236755,0.489642,0.101090,-0.099269,0.520694,-0.194481,-0.187408,-0.072767,-0.113464,0.137939,0.097951,0.284111,0.155803,0.147362,-0.038766,-0.112594,-0.208164,0.557776', '3811356', '1322847', '10466639', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6874741', '无问西东', '剧情', '如果提前了解了你所要面对的人生，你是否还会有勇气前来？吴岭澜、沈光耀、王敏佳、陈鹏、张果果，几个年轻人满怀诸多渴望，在四个非同凡响的时空中一路前行。吴岭澜（陈楚生 饰），出发时意气风发，却很快在途中迷失了方向。沈光耀（王力宏 饰），自愿参与了最残酷的战争，他一直在努力去做那些令他害怕，但重要的事。王敏佳（章子怡 饰）最初的错误，只是为了虚荣撒了一个小谎；最初的烦恼，只是在两个优秀的男人中选择一个。但命运，却把她拖入被众人唾骂的深渊。陈鹏（黄晓明 饰）把爱情摆在了理想前面，但爱情却没有把他摆在前面。他说，“我有人要照顾”，纵然这意味着与所有人作对，意味着要和她一起被放逐千里。张果果（张震 饰），身处尔虞我诈的职场，“赢”是他的习惯。为了赢，他总是见招拆招，先发制人。而有一天，他却面临了一个比“赢”更重要的选择。这几个年轻人，在最好的年纪迎来了最残酷的考验,并成就了永不褪色的青春传奇。', '章子怡', '李芳芳', 7.5, 694388, 'tt2401825', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2507572275.jpg', 2.4, 7.2, 26.5, 38.5, 25.3, '0.221102,0.327710,-0.695227,0.591346,-0.307478,-0.149433,0.803257,0.034774,-0.360235,-0.140157,0.116686,0.690319,0.229828,-0.025233,0.035480,-0.140983,-0.076501,-0.669428,0.026967,-0.200812,-0.393460,-0.442497,-0.051975,-0.140818,-0.341787,0.016835,0.634868,0.370281,-0.155456,0.262200,0.512901,0.030160,0.184917,0.667342,-0.340984,-0.165502,-0.053545,0.216829,-0.314928,0.321817,0.073339,-0.341905,-0.345731,0.521407,-0.173962,0.290284,0.376844,-0.269917,-0.234349,0.122107,0.303886,-0.440939,-0.144871,0.257718,0.117283,-0.235298,-0.015770,0.146839,-0.144905,0.105115,0.052366,0.039405,-1.062226,-0.134324,0.109880,0.037869,-0.785546,0.513414,0.161290,-0.068519,0.091218,-0.118871,0.207343,0.252364,0.325412,-0.034556,-0.211646,-0.269046,-0.521130,0.192962,1.026161,-0.013191,-0.109574,0.448897,-0.193408,-0.254505,-0.182123,-0.281780,-0.536762,0.078327,0.406101,-0.036422,-0.252243,0.065342,-0.455401,0.160509,-0.108623,-0.108194,-0.259505,-0.641407,0.021937,-0.040449,-0.080053,-0.653465,-0.521059,0.131543,-0.005939,-0.565827,0.866153,-0.825167,0.207945,0.675985,0.227779,-0.756983,0.710455,0.453023,0.198553,-0.315377,0.080856,0.315906,-0.085072,0.136391,-0.032312,0.334467,0.017703,-0.091492,-0.302984,0.695781', '301