INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6875263', '灰姑娘', '爱情', '母亲去世后，瑞拉（莉莉·詹姆斯 Lily James 饰）的父亲迎娶了美丽的特曼妮夫人（凯特·布兰切特 Cate Blanchett 饰），特曼妮夫人还带来了她的两个女儿安泰西亚（荷丽黛·格兰杰 Holliday Grainger 饰）和崔西里亚（索菲·麦希拉 Sophie McShera 饰）。瑞拉本着善待他人的善良之心和继母与两个姐姐和平共处，然而，这一切却在父亲去世后发生了翻天覆地的变化。失去了父亲的庇护，瑞拉彻底沦为了特曼妮夫人的奴隶和家中的女佣，可是，即使饱受亲人们的压迫与侮辱，瑞拉依然决定留下来，守护这个家庭。一次偶然中，瑞拉邂逅了名为基特（理查德·麦登 Richard Madden 饰）的男子，然而，她并不知道眼前这个充满了魅力的年轻人贵为王子，还以为他只是区区侍从。王子在王宫里举办了大型的宴会，邀请全国上下的少女们前往参加，瑞拉也想去，但特曼妮夫人显然并不喜欢她的这个主意。', '莉莉·詹姆斯', '肯尼思·布拉纳', 7, 217864, 'tt1661199', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2231066272.jpg', 0.9, 6.4, 48.6, 32.4, 11.8, '0.220456,0.239961,-0.768341,0.617317,0.000948,-0.687733,0.975468,0.416732,-0.490904,-0.376827,0.001839,0.614477,-0.140002,0.105424,0.505832,0.453269,-0.725813,-0.557051,0.238138,0.014061,0.033679,-0.422420,-0.207335,-0.148317,-0.119173,-0.511756,0.396227,-0.237191,0.025438,0.571115,0.265044,0.615671,0.169667,0.422054,0.192125,0.223197,0.500640,-0.019266,-0.351147,0.206352,-0.023645,0.135246,-0.005493,0.346641,0.120497,0.370679,0.415214,-0.703027,0.084189,-0.332847,0.275674,-0.344210,0.128488,0.316435,0.153434,-0.206733,0.237327,0.083563,-0.204542,-0.148414,0.242446,-0.150220,-0.463425,0.079790,0.276366,0.112023,-0.881253,0.601288,-0.105473,-0.392201,0.073175,-0.257906,0.333069,0.420410,-0.168312,0.250902,-0.160025,-0.002777,-0.581892,-0.034785,0.609274,0.197694,-0.091179,0.166812,-0.169450,-0.622723,0.097303,-0.251599,-0.779957,0.211668,-0.057362,-0.146003,-0.011707,0.424914,-0.270976,-0.370284,-0.908914,0.031594,0.071562,-0.725977,-0.061563,-0.434470,-0.099768,-0.554878,-0.554190,-0.338535,0.165377,-0.148752,0.520341,-0.957749,0.386858,0.276283,0.431262,-0.284687,0.456927,0.240666,0.347593,-0.099928,-0.367561,0.152155,-0.146252,0.094137,0.001003,0.288977,0.342461,0.058247,-0.187816,0.650025', '13