INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6875265', '盛大婚礼', '喜剧', '亚当（罗伯特·德尼罗 Robert De Niro 饰）和艾丽（黛安·基顿 Diane Keaton 饰）曾走过20年的婚姻生涯，但如今已分手多年，亚当转而与艾丽的闺蜜贝贝（苏珊·萨兰登 Susan Sarandon 饰）在一起。原本以为生活将照例继续，怎料烦恼却随着养子亚力（本·巴恩斯 Ben Barnes 饰）的婚礼降临。亚力和女友美丝（阿曼达·塞弗里德 Amanda Seyfried 饰）两情相悦，互许婚盟，然而亚力远在哥伦比亚的生母麦当娜得知此事后，执意要来参加婚礼。为了避免尴尬，亚当和艾丽不得不貌合神离地假装恩爱，为了迎合麦当娜的清教信仰，亚力和美丝甚至想方设法请来了天主教神父，一场费尽心思的盛大婚礼终于在混乱和笑料中登场了……本片翻拍自2006年法语喜剧《我弟弟要结婚了》。©豆瓣', '罗伯特·德尼罗', '贾斯汀·扎克汉姆', 6, 5871, 'tt1931435', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1875948100.jpg', 3.4, 19.8, 56.5, 16.6, 3.8, '0.139252,-0.013407,-0.590239,0.466910,0.088570,-0.568950,0.476729,0.270558,-0.347346,-0.288622,-0.077725,0.632462,-0.467871,0.092656,0.592744,0.038675,-0.555631,-0.782670,0.051530,-0.063981,0.098323,-0.623034,-0.076555,-0.231345,-0.213255,-0.271930,0.398395,-0.332083,0.165619,0.713414,0.531340,0.272926,-0.369902,0.160855,0.138267,-0.049595,0.294293,0.194348,-0.720310,0.093215,0.198325,-0.125443,-0.254792,0.178493,0.210422,0.267690,0.367354,-0.146116,0.346912,0.051348,0.152995,-0.143796,0.183739,0.152557,0.077648,-0.010511,0.491297,0.498608,-0.173711,-0.054321,0.250641,-0.266896,-0.282652,0.325123,0.020530,-0.104286,-0.376814,0.636187,-0.176234,0.002551,0.202196,-0.366859,0.163053,0.698122,0.436854,0.402656,-0.165265,0.166246,-0.412090,0.195730,0.735680,0.156004,0.115272,0.281940,0.082777,-0.268944,0.005272,-0.121230,-0.710965,0.066767,0.228256,-0.037830,0.095362,0.614217,-0.585725,-0.501081,-0.443719,-0.023024,0.296111,-0.307992,0.151589,-0.433175,-0.203247,-0.374911,-0.159158,-0.193600,-0.042826,-0.143876,0.395455,-0.729227,0.551607,0.369940,0.352532,-0.359965,0.476293,0.421163,0.388337,-0.079814,-0.007529,0.241293,-0.091305,0.051711,0.219990,-0.002535,0.261288,-0.237048,-0.337905,0.303404', '25978126', '3078390', '25856453', '1302987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6875402', '机器人与弗兰克', '剧情', '刚刚步入老年的弗兰克（弗兰克·兰格拉 Frank Langella饰）开始有轻微老年痴呆的症状，时常神智混乱，无法与人们进行正常的交流。他的一对儿女亨特（詹姆斯·麦斯登 James Marsden饰）、麦迪森（丽芙·泰勒 Liv Tyler饰）为父亲提供了一个机器人（彼得·萨斯加德 Peter Sarsgaard配音）来照料他的日常生活。弗兰克一开始无法接受这个冷冰冰的机器人，在经历了初期的磨合后，弗兰克发现眼前这个全能机器人不仅细心照料着自己的起居，更会静静地陪在身边，温柔地倾听自己的内心。弗兰克和机器人慢慢变成了好朋友。为了赢得图书管理员詹妮弗（苏珊·萨兰登 Susan Sarandon 饰）的好感，机器人跟着弗兰克为爱上演了一出惊天奇案。本片在2012年圣丹斯独立电影节上一鸣惊人，荣获2012年圣丹斯电影节阿尔弗雷德.P.斯隆长片电影奖。©豆瓣', '弗兰克·兰格拉', '杰克·施莱尔', 7.6, 11597, 'tt1990314', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1812054028.jpg', 0.5, 2, 31.7, 50.1, 15.7, '0.160016,0.134754,-0.767561,0.524662,0.066403,-0.275599,0.718026,0.201992,-0.450302,-0.241346,0.041581,0.732271,-0.485445,0.202557,0.312186,0.099115,-0.709028,-0.605017,-0.188140,0.031893,-0.299898,-0.392647,-0.339043,-0.510687,-0.299940,-0.536788,0.388701,-0.356246,0.214190,0.658632,0.382182,0.397814,0.359837,0.033254,0.005135,0.184201,0.306551,-0.306894,-0.274414,0.208112,0.019454,-0.063291,-0.159792,0.041462,-0.008151,0.229082,0.702688,-0.281529,0.086530,-0.019666,0.441579,-0.067896,0.187162,-0.058255,0.055916,0.111198,0.065408,0.030055,-0.207359,0.320956,0.050888,-0.259311,-0.750004,0.039345,-0.026582,0.322740,-0.454167,0.322957,-0.170587,0.045289,0.012092,-0.208996,-0.092349,0.377784,0.294473,0.424554,-0.138477,0.273729,-0.266385,0.247855,0.449506,0.071677,-0.366634,0.637952,-0.180352,-0.501323,-0.152448,-0.235596,-0.607366,-0.096369,0.234105,-0.098918,0.052734,0.318665,-0.383040,0.027910,-0.251398,-0.179910,-0.100687,-0.175054,-0.062270,-0.791782,-0.200230,-0.438281,-0.327042,-0.141167,-0.281968,-0.338798,0.729695,-0.770397,0.269278,0.490247,0.128172,-0.142215,0.668683,0.011210,0.294636,-0.269380,-0.275403,0.219929,-0.101598,0.179181,0.380454,0.387067,0.057108,0.084908,-0.310532,0.341474', '3811356', '1293656', '25928048', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6875420', '亲密治疗', '剧情', '马克·欧布莱恩（约翰·浩克斯 John Hawkes 饰）曾在幼年时期患上过小儿麻痹症。疾病的后遗症不仅让他再也没有站起来过，并且还让他饱受呼吸困难的折磨。虽然已过而立之年的他早已成为一名成功的诗人兼记者，但作为一个男人，却从未尝试过性的滋味。在向牧师朋友多次寻求指引 后，他毅然决定通过雇佣专业性从业者来帮助自己完成这个愿望。于是谢尔（海伦·亨特 Helen Hunt 饰）出现在了马克的生活里。然而对于马克这样特殊的情况，谢尔一开始也觉得无所适从。但是渐渐地，两人不仅从医患关系变为朋友，谢尔同时也给予了马克追求幸福和爱的勇气，让马克迈出了追寻爱的第一步。本片根据真人真事改编。片中谢尔的扮演者海伦·亨特获得第85届奥斯卡最佳女配角等多项电影节提名。©豆瓣', '约翰·浩克斯', '本·列文', 7.5, 12169, 'tt1866249', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1708133824.jpg', 0.4, 2.1, 32.2, 50.3, 15, '0.096396,0.050960,-0.784261,0.698904,0.045221,-0.640898,0.594556,0.001574,-0.476208,-0.201938,0.090412,0.764576,-0.340168,0.138801,0.477570,-0.174387,-0.241571,-0.751213,0.155331,-0.079263,-0.350772,-0.446714,-0.268772,-0.329676,-0.306196,-0.582307,0.805842,-0.025316,-0.175028,0.372268,0.406389,0.357032,0.314272,0.521566,-0.123851,0.066626,0.339641,-0.042449,-0.470619,0.488135,0.340196,-0.256185,-0.258369,0.243757,-0.020914,0.449936,0.487199,-0.420153,-0.244543,0.154709,0.338258,-0.267126,-0.024704,0.087033,0.082582,0.017938,0.177737,0.206368,-0.063543,0.295910,-0.109666,-0.057530,-0.886215,-0.078018,0.038095,0.207264,-0.629647,0.225097,-0.243427,-0.025018,-0.003970,-0.270425,0.021584,0.304647,0.251162,0.331399,-0.349120,0.050798,-0.308886,0.262557,0.722030,0.080938,-0.532497,0.515528,-0.427745,-0.603028,-0.142864,-0.105932,-0.368691,0.051393,0.145217,0.131269,-0.153717,0.165937,-0.579617,0.073050,-0.343789,-0.168695,-0.075839,-0.261445,0.141959,-0.618383,-0.079173,-0.097168,-0.209645,-0.024243,-0.116596,-0.551329,0.637109,-0.778860,0.430528,0.457140,0.288483,-0.426156,0.599773,0.287852,0.097160,-0.215740,-0.218865,0.552888,-0.071166,0.220373,0.142550,0.264877,0.173146,-0.173838,-0.243996,0.581365', '1303034', '1793491', '4301278', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6875451', '神圣车行', '剧情', '黎明到夜晚，再从夜晚到黎明，奥斯卡先生在自己的生命中总是在不断地变换着角色。他时而是大老板、时而是杀手、时而是女乞丐、时而又是怪物或者是居家男人。就好像是旅途一般，他总是在这些人物中间乐此不疲。看上去他是在表演、拍电影、演话剧——但是，摄像机却总是缺席。他很孤单，只有赛丽娜陪伴他。赛丽娜是位身材修长的金发女郎，总是在轮胎和引擎的背后，从不现身。她开着巨大的汽车在巴黎和巴黎周边到处转悠。看上去，他就是像是一个杀手，完成着一个又一个目标，从不停歇。为了追求那些虚无缥缈的东西，为了寻找奥斯卡背后的动机，这个女人的背后似乎隐藏了太多的玄机。有人知道他的家在哪里么？有人知道他的家人么？有人知道他什么时候会停下来么？', '德尼·拉旺', '莱奥·卡拉克斯', 7.9, 22160, 'tt2076220', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1778756586.jpg', 1.9, 4.2, 20.2, 42.5, 31.2, '0.376779,-0.028058,-0.731740,0.544310,-0.482046,-0.021493,1.006189,0.036983,-0.508611,-0.195763,0.489086,0.816070,-0.004339,0.294221,0.020319,0.243646,-0.253597,-0.632804,0.003095,-0.129388,-0.277651,-0.205732,-0.308022,-0.147120,-0.010728,-0.149098,0.517242,0.235134,-0.150235,-0.050519,0.402050,0.013796,0.006981,0.792437,-0.467005,-0.227424,-0.101597,0.196771,0.219682,0.249341,0.086789,-0.429164,-0.488457,0.235007,-0.268493,0.297069,0.479594,-0.277571,-0.158398,0.209680,0.303370,-0.325645,0.089506,-0.077339,0.236793,-0.230656,0.394370,0.018089,0.147197,0.199766,0.008838,0.076028,-0.629809,0.109698,-0.127214,0.465028,-0.611941,0.280505,0.006702,-0.158268,0.077208,-0.433435,0.392320,0.044873,0.158828,0.176358,-0.397120,-0.215500,-0.826073,0.189459,0.662474,0.365513,-0.243724,0.574229,-0.200078,-0.357769,-0.159657,-0.063342,-0.759192,-0.292645,0.195944,-0.235489,-0.375441,0.025795,-0.494545,0.562028,-0.087059,-0.106374,-0.227331,-0.475025,-0.313259,-0.468925,0.337102,-0.568259,-0.068367,0.205077,-0.021455,-0.392930,0.607047,-1.099036,0.311746,1.161661,0.220560,-0.342890,0.660268,0.156921,-0.294344,-0.143604,-0.399434,-0.086350,0.114989,0.268286,-0.197071,0.367935,0.094137,-0.047537,-0.360802,0.758896', '4275444', '1949005', '1309172', '1309080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6875610', '火线反攻', '剧情', '勇猛果敢的杰里米·科曼（乔什·杜哈明 Josh Duhamel 饰）是一名备受欢迎的消防员，某晚在执行完任务后，他进入便利店购物，却遭遇率领手下抢夺地盘的黑帮头子戴维·黑根（文森特·诺费奥 Vincent D''Onofrio 饰），店长及其家人被杀，杰里米侥幸逃脱。之后他作为证人指认凶手，但对戴维为人极其了解的警官迈克·塞拉（布鲁斯·威利斯 Bruce Willis 饰）劝说杰里米接受证人保护，并隐姓埋名，以防止遭到戴维的无情报复。但是他的行踪很快被戴维一伙发现，他与女友塔莉亚（罗莎里奥·道森 Rosario Dawson 饰）遭到伏击，女友更身受重伤。穷凶极恶的戴维，势要将杰里米逼向死路，困兽犹斗，杰里米展开绝死反抗……©豆瓣', '乔什·杜哈明', '大卫·巴雷特', 5.5, 6520, 'tt1925431', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2213799032.jpg', 5.8, 30.1, 51.9, 9.5, 2.6, '0.193275,-0.209791,-0.269617,0.251676,-0.131026,-0.162095,0.596397,0.146455,-0.511195,-0.169983,0.413881,0.712795,-0.084087,-0.202072,0.401847,0.054502,-0.385132,-0.441632,0.092515,-0.065638,-0.098868,-0.588857,-0.076206,-0.192310,-0.038177,-0.354899,0.498127,-0.100995,-0.130401,0.550896,0.494418,0.605745,0.006192,0.480640,0.250621,0.240217,0.328855,-0.655788,-0.347902,0.505400,0.029821,-0.077525,-0.038689,0.398275,-0.141079,0.505781,0.478011,-0.213753,0.009499,-0.286808,0.031584,-0.587165,0.252065,0.436071,0.308306,-0.112844,-0.006288,0.416224,-0.096718,-0.086529,0.190836,0.129590,-0.733863,0.004483,0.143724,0.125905,-0.539755,-0.116962,-0.363177,0.249694,-0.030505,-0.063537,-0.070953,0.253944,0.165602,-0.024752,-0.038050,-0.078081,-0.603377,-0.343081,0.412074,-0.321177,0.183282,-0.164783,-0.008491,-0.100727,0.173198,-0.283646,-0.538262,0.053754,0.337189,-0.081265,-0.066609,0.047154,-0.378834,-0.376309,-0.633313,0.054226,-0.323393,-0.312885,-0.194478,-0.912182,0.020361,0.181636,-0.333730,-0.086037,-0.098709,-0.235222,0.275470,-0.741376,0.267608,0.560962,0.443230,-0.441767,0.164010,0.175763,0.179857,-0.233680,-0.165944,0.429716,0.733031,0.090868,0.169339,0.018669,-0.003262,-0.401157,0.083897,0.114982', '2028645', '1299335', '1899892', '1482080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6875611', '破坏者', '剧情', '缉毒小队“破坏者”在队长约翰·沃顿（阿诺·施瓦辛格 Arnold Schwarzenegger 饰）的率领下闯入臭名昭著的贩毒团伙奥加尔萨联盟的据点，经过一轮激烈的交锋，小队一名成员战死，而现场丢失的一千万美元现金也让“破坏者”的所有成员遭到了上层组织的调查。未过多久，高层指示约翰和成员们各就各位，重新开始行动。谁知未过多久，小队成员接二连三死于非命。似乎奥加尔萨为了丢失的巨款恼羞成怒，正展开疯狂的报复。联邦探员卡洛琳（奥莉维亚·威廉姆斯 Olivia Williams 饰）受命调查此时，她和约翰联合展开行动，结果却发现前方的道路更加凶险，令人难以置信的黑幕慢慢呈现眼前……©豆瓣', '阿诺·施瓦辛格', '大卫·阿耶', 5.7, 11845, 'tt1742334', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2236022507.jpg', 5.3, 26.1, 52.8, 12, 3.8, '0.171591,-0.055775,-0.766521,0.306256,0.148925,-0.025320,0.619180,-0.141263,-0.586966,-0.182841,0.526311,0.339207,-0.142654,-0.067784,0.448725,-0.377041,-0.483481,-0.780307,-0.275881,-0.298618,-0.199234,-0.328138,-0.115311,-0.441749,0.233512,-0.385598,0.787035,0.273437,-0.082674,0.625198,0.369561,0.389061,-0.271834,0.294158,0.439097,-0.137441,0.670692,-0.485765,-0.179916,0.111981,-0.375844,-0.185075,-0.296473,0.167850,-0.009302,0.558047,0.681900,-0.373338,-0.060647,-0.329898,0.086796,-0.521561,0.041479,0.007515,0.826924,0.219592,0.082874,0.224429,0.079607,0.033599,-0.332206,0.104799,-0.876864,0.163764,0.153375,0.369267,-0.539269,0.064410,-0.369857,0.332117,0.162294,0.003448,-0.027771,0.802189,0.428304,-0.036491,-0.128769,0.124336,-0.366752,-0.083796,0.712170,-0.114941,-0.162980,-0.377879,0.216254,-0.493958,-0.159124,-0.092337,-0.084272,-0.114608,0.400169,0.024541,0.370763,0.428123,-0.920648,0.052548,-0.390589,-0.625299,-0.176603,-0.381905,-0.216513,-1.048697,-0.023111,0.184295,-0.198274,0.336804,-0.178562,0.120159,0.572627,-0.569880,0.149074,0.319265,0.279389,-0.448329,0.098692,-0.016581,0.213184,-0.258343,-0.188811,0.093304,0.518613,0.478922,0.325760,0.134512,-0.280517,-0.209633,-0.151562,-0.068130', '1306809', '2369613', '1300371', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6875615', '险恶', '惊悚', '埃里森·奥斯沃特（伊桑·霍克 Ethan Hawke 饰）是一个十几年前小有名气的犯罪小说作家，为了寻找创作灵感，他不惜一次次搬入曾经发生过命案的凶宅。时至今日，为了重现往昔的辉煌，他再次带着妻子崔茜（Juliet Rylance 饰）以及一双儿女特里夫（Michael Hall D''Addario 饰）和艾丝莉（Clare Foley 饰）搬入一栋凶宅。在收拾阁楼时，他偶然发现一卷家庭录影带，里面记录着房子前主人一家快乐幸福的生活瞬间以及他们被吊死在树上的惨烈画面。此后的日子里，他一遍遍观看录影带，从中寻找罪犯的蛛丝马迹，并且在房屋内的每个角落追查线索。在这一过程中，各种诡异事件相继在家人身上发生。埃里森此时已难以抽身……©豆瓣', '伊桑·霍克', '斯科特·德瑞克森', 6.8, 26969, 'tt1922777', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1853882455.jpg', 1.5, 8.6, 47.5, 32.8, 9.6, '0.119735,0.003385,-0.761267,0.504012,0.294547,-0.128547,1.033653,-0.086804,-0.814363,-0.385457,0.194418,0.593963,-0.187015,0.400148,0.047044,0.009838,-0.582555,-0.836763,-0.010656,-0.348895,-0.335229,-0.296488,-0.446231,-0.285260,-0.099719,-0.233932,0.299981,0.252620,0.072986,0.372045,0.168441,0.214717,-0.558455,0.149691,-0.259703,0.075850,0.146323,0.200218,-0.466116,0.094255,-0.104928,-0.493025,-0.267497,-0.046469,-0.028831,0.135846,0.940419,-0.239767,-0.221829,0.004637,0.378803,0.308894,-0.100740,0.169270,0.233841,0.187133,0.442639,0.415781,-0.327563,-0.242854,0.188821,-0.182455,-0.822097,-0.350660,0.222868,0.518106,-0.361787,0.379010,-0.115989,0.270901,0.115796,-0.382680,0.285417,0.137382,0.398602,0.201702,-0.165415,0.018780,-0.433098,0.441684,0.495134,-0.177094,0.103432,0.452709,-0.131175,-0.033097,-0.114249,0.036361,-0.579808,0.162103,0.477537,0.092965,-0.154122,0.333692,-0.567982,0.041707,-0.142216,-0.281280,0.051836,-0.141886,-0.438723,-0.640640,-0.241199,-0.161875,-0.255970,0.036251,-0.200093,-0.301383,0.374891,-0.505998,0.448495,0.430355,-0.029161,-0.154715,0.554573,-0.268645,0.383448,0.124853,-0.145840,0.232014,0.164537,0.572737,0.024974,0.254744,-0.118111,-0.056259,-0.584693,0.525336', '10466639', '1316693', '20451118', '1292528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6875647', '帕克', '动作', '自诩行侠仗义、绝不伤害人命的劫匪帕克（杰森·斯坦森 Jason Statham 饰）带领同伙洗劫俄亥俄一座游乐场，谁知最后关头却遭背叛，身受重伤，命悬一线。侥幸逃生的帕克迅速从医院逃出，他有条不紊搞来现金，准备假证件。为了讨回自己应得的那份钱，他查到同伙梅兰德（麦克·切 克里斯 Michael Chiklis 饰）等人的消息，一路尾随前来。与此同时，有着芝加哥黑手党背景的梅兰德等人察觉到帕克的行踪和动机，也唆使杀手追杀这个难缠的对手。围绕着这笔不义之财，交织着人性欲望的杀戮随即展开……©豆瓣', '杰森·斯坦森', '泰勒·海克福德', 6.6, 40028, 'tt1904996', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1830099433.jpg', 1.2, 10.1, 56.1, 24.9, 7.7, '0.072628,-0.132463,-0.559364,0.462162,-0.108991,-0.269313,0.423810,0.205773,-0.389454,-0.322111,0.541379,0.370504,0.181067,-0.324928,0.270048,-0.205845,-0.422330,-0.400820,0.070636,-0.287126,-0.246372,-0.251106,-0.288834,-0.405099,0.026019,-0.034254,0.135791,0.275935,-0.123465,0.543185,0.510249,0.473611,-0.347509,0.340112,0.045905,0.104282,0.201366,-0.310177,-0.217826,0.304296,-0.098131,-0.332734,-0.055295,0.052322,0.012482,0.525732,0.681381,0.010131,0.151709,-0.131220,-0.084750,-0.434186,0.206423,-0.006869,0.251194,-0.257820,-0.040143,0.166587,-0.284181,0.088036,0.182263,-0.077605,-0.821763,0.008478,0.043311,0.245669,-0.459116,0.180449,-0.458765,0.413651,-0.025812,-0.070812,0.051949,0.032195,-0.008874,-0.069478,0.128248,-0.084946,-0.671289,-0.050290,0.483239,-0.492530,0.334505,-0.071894,-0.034232,-0.146547,0.023383,-0.219183,-0.220004,-0.092408,0.537792,0.091409,-0.222752,0.104242,-0.274733,-0.126269,-0.445529,0.130000,-0.272377,-0.404316,-0.138192,-0.627936,-0.115646,0.165955,-0.173650,0.275577,-0.195751,0.087388,0.317425,-0.218131,0.124529,0.674252,0.303171,-0.427762,0.305537,-0.156401,-0.057391,-0.092064,-0.324683,0.268723,0.630323,0.313411,0.197514,-0.175965,-0.064605,-0.186976,0.326064,0.142465', '26747274', '3143727', '1301345', '1482080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6875763', '与恐龙同行', '动画', '炎热的假期，男孩里奇（查理·罗 Charlie Rowe 饰）和妹妹跟随身为考古学家的叔叔（Karl Urban 饰）来到了辽阔壮丽的阿拉斯加，体验一次难得的寻访史前动物的旅程。在森林中，他受到一只乌鸦的指引，竟然穿越时空来到了七千万年前的白垩纪中期。在某个厚鼻龙家族中，小家伙派西（Justin Long 配音）刚刚出生就被伤齿龙在脑袋上开了一个大洞，幸运活下来的他注定拥有传奇的一生。时光荏苒，派西和伙伴们一天天长大，他也偶然邂逅令之心动的女孩裘妮波（Tiya Sircar 配音）。厚鼻龙家族的大迁徙开始，但从旅途之处便伴随着大火和猎杀。七千万年前，一段充满惊险的挑战的旅程再度呈现……©豆瓣', '查理·罗', '巴里·库克', 6.7, 4485, 'tt1762399', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2151420506.jpg', 1.9, 10.6, 49.7, 28, 9.8, '-0.065433,-0.087765,-0.787182,0.637931,0.068299,-0.228149,0.787290,-0.081488,-0.300954,-0.012877,0.364191,0.843877,-0.348653,0.424649,0.392612,-0.078606,-0.082200,-0.416250,-0.132180,-0.119802,-0.535103,0.036229,-0.457718,-0.030603,0.037106,-0.351942,0.772167,0.258391,-0.177312,0.613560,0.052864,0.064574,-0.337646,0.308514,-0.596144,0.102906,0.132779,0.462189,-0.038370,0.040890,-0.234177,-0.111972,0.053847,-0.053273,-0.126664,0.215963,0.712907,-0.577227,-0.055029,-0.215369,0.302858,-0.253141,-0.086807,0.029896,0.453364,0.227072,0.171860,0.148707,0.035733,0.101323,-0.016293,-0.362405,-0.615135,0.195208,-0.019585,0.035483,-0.512467,0.500596,0.209126,-0.161912,0.117749,-0.436106,0.087087,0.302698,0.161408,0.479596,-0.008770,0.336000,-0.207374,0.095875,0.661842,-0.238332,-0.426308,0.285050,0.009614,-0.660355,-0.006550,-0.237560,-0.366377,-0.104486,0.353013,-0.058876,-0.280360,0.490578,-0.894260,0.386049,-0.383451,-0.362162,0.032612,0.016674,-0.437417,-0.342385,0.065892,-0.364446,-0.298820,0.206317,0.076552,-0.517382,0.619260,-0.553336,0.461787,0.353078,0.121772,-0.021659,0.686314,-0.301897,0.091736,-0.007276,0.133474,0.595078,-0.008415,0.328385,0.168357,0.285905,-0.141054,-0.028550,-0.572952,0.580507', '6875863', '26290398', '1467779', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6875863', '恐龙当家', '喜剧', '6500万年前，一颗小行星与地球擦肩而过，称霸这个世界的恐龙懵懵懂懂地逃过了灭顶之灾。之后又过了数百万年，恐龙的智力得到进化，它们学会种植、畜牧、建筑，并且拥有属于自己的语言和家庭。某座山脚下的平原地带，雷龙一家迎来三个性格各异的娃娃，最小的阿洛（雷蒙德·奥乔亚 Ray mond Ochoa 配音）孱弱胆怯，与父亲的生离死别更在他的心中投下难以磨灭的阴影。一连串的事件过后，他与妈妈、哥哥、姐姐相隔万里。阿洛将这一切都归罪于原始人类的小孩点点（杰克·布赖特 Jack Bright 配音）。而点点似乎不为所动，他主动亲近阿洛，仿佛是一条忠诚勇敢的小狗。在充满坎坷和危险的回家之路上，阿洛与点点结伴而行，而这两个本不该碰面的恐龙和人类，将缔结超越了种族和时空的纯真友情……©豆瓣', '雷蒙德·奥乔亚', '彼得·孙', 7.5, 53706, 'tt1979388', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2267430045.jpg', 0.5, 4, 35, 41.6, 18.8, '0.396907,0.050441,-0.779173,0.906926,-0.157474,-0.157871,1.064618,-0.040337,-0.210446,0.167895,0.035204,0.954409,-0.174544,0.313786,0.073231,-0.192026,-0.016471,-0.511353,-0.147029,-0.065152,-0.243228,-0.443059,-0.485092,-0.119014,-0.086462,-0.320563,0.905036,0.182432,-0.135644,0.608372,-0.035026,0.093704,-0.330445,0.394583,-0.439708,0.103287,-0.218164,0.270680,-0.209237,-0.036525,0.044470,0.112582,-0.048645,0.236419,-0.390363,0.154493,0.752406,-0.551990,-0.200167,-0.378548,0.359926,-0.225836,0.010691,0.200357,0.217596,-0.137788,0.099072,0.073216,0.151453,0.119052,0.171400,0.091221,-0.689348,-0.149710,-0.164617,0.092434,-0.603018,0.463036,0.195687,-0.189839,0.172598,-0.449603,0.225893,0.276482,0.177626,0.495626,-0.375929,-0.079303,-0.541316,-0.038501,0.706917,-0.087443,-0.404865,0.360727,-0.378527,-0.623015,-0.177072,-0.225110,-0.558749,0.041430,0.308213,0.043197,-0.293607,0.556456,-1.009840,0.146295,-0.133661,-0.234649,-0.159758,-0.590137,-0.093866,-0.315183,-0.190993,-0.699447,-0.461670,0.180654,0.265026,-0.265078,0.910840,-0.858662,0.217026,0.362274,0.451500,-0.413393,0.668964,-0.045767,0.156502,-0.338973,0.065335,0.377434,-0.106293,0.262543,0.131804,0.480941,0.109100,0.364731,-0.671385,0.621907', '21619567', '30401849', '1467779', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6876154', '国家利益', '剧情', '本片被称为瑞典版007，男主角主演的《更好的世界》曾获得83届奥斯卡最佳外语片大奖。瑞典情报官员卡尔·汉密尔顿（米克尔·佩斯勃兰特 Mikael Persbrandt 饰），打入一个偷了瑞典先进的GPS制导导弹的国际犯罪团伙，这伙亡命雇佣军绑架了一名瑞典武器技术专家，并收到了一个不明身份客户组织的命令，准备发动一次致命的攻击。虽然汉密尔顿暴露了身份并逃脱了团伙的追杀，但导弹和专家都已经失去了踪迹。不久，被盗的武器之一出现在索马里的恐怖袭击事件中，一名和平政治家被杀害。在瑞典首相承诺的情况下，政府同意聘请一家私人保安公司完成救援任务，汉密尔顿作为瑞典政府观察员随行。显然，这是一项极度危险的任务，汉密尔顿要从索马里的荒芜沙漠，一路追踪到阿曼的街头巷战，以及斯德哥尔摩群岛的丛林+水艇战，在国家利益面前，他必须经历陆、海、空三种激战前所未有的挑战......', '米卡埃尔·佩斯布兰特', '凯瑟琳·温德菲尔德', 6.7, 6853, 'tt1856014', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1501309369.jpg', 1.5, 9.7, 49.9, 30.1, 8.7, '0.039026,0.035175,-0.606816,0.823386,-0.026405,-0.091778,0.287669,-0.070989,-0.320858,-0.339911,0.385196,0.822186,0.165650,-0.200801,0.420534,-0.206047,-0.251766,-0.521285,-0.107829,-0.248309,-0.524825,-0.533111,-0.390635,-0.364138,0.046172,-0.371083,0.813988,0.159729,-0.554413,0.256338,0.500827,0.420474,-0.257610,0.442422,-0.121494,-0.250806,0.627028,-0.197890,-0.518948,0.604967,-0.246538,-0.289855,-0.051520,0.220548,0.206410,0.483327,0.471147,-0.303129,-0.092907,-0.179904,0.287840,-0.480981,0.076551,-0.111499,0.656775,-0.092123,-0.002644,0.141720,-0.008026,0.267436,0.010440,-0.047574,-0.739471,-0.159644,0.112359,0.035739,-0.439859,0.240204,-0.286490,0.238253,-0.213454,-0.076326,0.335830,0.400155,0.101759,0.070689,-0.140697,0.235515,-0.617399,0.213357,0.488793,-0.247808,-0.319080,-0.087643,-0.033248,-0.721256,-0.097635,-0.311604,-0.076471,0.037836,0.621097,-0.041722,-0.107389,0.252408,-0.657210,0.011099,-0.324253,-0.474616,-0.151940,-0.209935,0.151884,-1.071091,0.051232,-0.048072,-0.214216,0.250488,0.113593,0.085519,0.594163,-0.486911,0.066688,0.687564,0.099862,-0.517873,0.325363,0.193761,0.180043,-0.354743,-0.155589,0.258001,0.396339,0.413531,-0.120824,0.142224,0.023826,-0.408131,-0.117540,0.228501', '2028645', '2369613', '4014397', '1309112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6877520', '画之国', '动画', '在一副未完成的画中，画中的人搞起了等级社会，画全人歧视没画完人，更不把线稿人放在眼里。画之国的城堡被画全人蜡烛大帝所掌控，他把没画完人和线稿人驱逐到森林中。画全人拉莫和没画完人克莱尔相爱，遭到了蜡烛大帝的追逐围捕。机缘巧合拉莫遇上了克莱尔的朋友罗拉和线稿人布吕姆，三人被追到了食人森林里。他们决定去寻找消失的画家，让其完成这幅未完成的画，为没画完人和线稿人涂上色彩。在寻找的路上，三人跌出画中，来到了画家的画室。邂逅了闲卧窗边迷人的夫人、脾气不太好的画家自画像、语速很快的蓝色小丑。他们穿梭在画与画中，在威尼斯的狂欢节里奔跑，遇到死神的追逐，最终回到了画室，虽未找到画家，但得到了画画的技巧。而另一边，克莱尔被捕，没画完人和线稿人被拉去做劳工，蜡烛大帝在着手一场仪式，得到颜料和技巧的拉莫一行人回来的道路险境丛生，最终他能否赋予没画完人和线稿人色彩呢。©豆瓣', '让-弗朗索瓦·拉吉奥', '让-弗朗索瓦·拉吉奥', 8.4, 9086, 'tt1891769', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1803786028.jpg', 0.1, 0.8, 14, 48.2, 37, '0.384943,0.110909,-0.480653,0.666956,-0.196952,-0.230995,0.522242,0.146039,-0.282107,-0.060648,0.128719,0.735001,-0.374330,0.011698,0.246074,-0.038012,-0.740563,-0.680288,0.223166,-0.067805,-0.457711,-0.195898,-0.264002,-0.151429,-0.199784,-0.267844,0.574791,0.309383,0.017725,0.265188,-0.087489,-0.010881,-0.413136,0.241773,-0.305416,0.290930,-0.121781,-0.031800,0.052578,0.271733,0.105571,-0.279144,-0.218158,0.085526,-0.255948,0.255246,1.091413,-0.390205,0.300433,-0.028895,0.122193,-0.404127,0.065641,0.156890,0.183570,0.125603,0.163662,0.050580,-0.332466,-0.032201,-0.117955,-0.541130,-0.544873,-0.045932,0.136628,0.398432,-0.535205,0.585845,-0.277317,-0.035916,0.170838,-0.367274,0.432590,-0.031641,0.331894,0.483030,0.212433,-0.229504,-0.948268,0.276350,0.291180,0.101500,-0.047670,0.383517,-0.004938,-0.269017,-0.268361,-0.406275,0.058496,0.201328,0.550976,0.125237,-0.216824,-0.297530,-0.843948,-0.084203,-0.151958,0.007399,-0.105343,-0.731357,-0.485340,-0.719552,0.054349,-0.179005,-0.041174,0.194478,-0.011638,-0.189428,0.382256,-0.641450,0.276832,0.166463,0.244342,-0.257069,0.776593,-0.148633,-0.160284,-0.119514,-0.050335,0.001319,0.205723,0.642720,0.373334,0.468625,-0.012827,-0.065768,-0.704508,0.608678', '1294917', '1309194', '5149279', '5322572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6877703', '乔布斯', '剧情', '电影改编自美国苹果公司联合创办人史蒂夫·乔布斯的生平，真实而又生动的还原了这位计算机业风云人、大企业家传奇而又跌宕的一生。从大学退学后，乔布斯（艾什顿·库彻 Ashton Kutcher 饰）开始专注于自我挖掘与探索，之后，他和志同道合的好友沃兹尼亚克（乔什·盖德 Josh Gad 饰）共同创建了苹果电脑公司，一度风头强劲。然而，随着时间的推移，乔布斯和沃兹尼亚克之间的分歧越来越多，最终，在矛盾无法调和的情况之下，乔布斯愤然出走，不仅带走了一大批能人巧匠，还成立了NeXT公司。1997年，苹果公司惨淡的经营状况令其面临着宣布破产的窘境，这时，乔布斯的高调回归为公司的未来带来了一线生机和希望。©豆瓣', '阿什顿·库彻', '乔舒亚·迈克尔·斯坦', 6.1, 28899, 'tt2357129', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2120484940.jpg', 4.3, 19.2, 50, 20.1, 6.5, '-0.017064,0.127195,-0.707007,0.503516,0.393706,-0.555422,0.410270,0.377976,-0.525471,-0.245553,-0.071986,0.807300,-0.333591,0.304450,0.451328,-0.131974,-0.393628,-0.752772,0.105605,-0.206733,-0.062868,-0.446138,-0.365376,-0.438355,-0.013787,-0.323900,0.721168,0.208033,-0.311142,0.457415,0.193654,0.415002,-0.043601,0.400299,0.045992,0.000071,0.249406,0.067216,-0.549553,0.130813,0.154647,-0.260541,-0.340561,0.158166,0.063033,0.426960,0.269972,-0.249388,-0.117832,-0.104644,0.450856,-0.138485,-0.114270,0.035327,0.287628,0.109054,0.276194,0.485793,-0.528396,-0.186204,-0.007698,-0.278120,-0.882718,0.045336,-0.053935,0.049977,-0.585433,0.416587,-0.169355,-0.113119,0.183500,-0.131258,0.027332,0.673539,0.495619,0.346841,0.023479,0.000266,-0.244768,0.201515,0.543770,0.026740,-0.608994,0.256151,0.003077,-0.238927,-0.345108,-0.404587,-0.412843,-0.071997,0.639062,0.381005,-0.000488,0.798838,-0.653346,0.005440,-0.321205,-0.287195,0.146263,-0.384225,-0.103307,-0.593308,-0.382143,-0.202071,-0.038989,-0.053945,0.033592,-0.321244,0.751981,-0.632295,-0.016778,0.397760,0.136024,-0.517665,0.499767,-0.078787,0.223178,-0.235924,-0.268914,0.179549,-0.127131,0.304715,0.204883,0.133785,0.070527,-0.174565,-0.194090,0.387238', '26678784', '27602116', '4301278', '1308837');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6878446', '二次曝光', '剧情', '《二次曝光》由李玉执导，是范冰冰与她合作的第三部作品，在14个城市取景，航拍、特技，广西溶洞、新疆胡杨林、天山雪峰、秦皇岛大海等美景都一一呈现。宋其（范冰冰 饰）是一家整容公司的形象咨询师，无意间发现同属一家公司的整容医生兼男朋友刘东（冯绍峰 饰）和闺蜜周小西（霍思燕 饰）的私情。本想找小西理论，却在盛怒之下错杀了小西，于是开始一段逃亡之旅。精神崩溃的宋其更是在路上撞死一位负责调查此案的刘警官。最后宋其选择了自首，但警方调查后发现，小西并没有死，而刘警官也根本不存在。两段偷情、三次弑杀、四幕风月，谜案、迷情、迷幻，三个世界与两段时空会带来怎样的故事呢？©豆瓣', '范冰冰', '李玉', 6.1, 131022, 'tt2176668', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1695181672.jpg', 4.9, 19.4, 49.3, 20.9, 5.5, '0.030058,-0.138628,-0.405622,0.351045,-0.004022,-0.185052,0.401615,0.293038,-0.471294,-0.189407,0.264436,0.430413,-0.243516,0.042370,0.209080,-0.069060,-0.216549,-0.543207,0.198356,-0.144414,-0.170937,-0.474381,-0.239137,0.072177,0.132851,0.006048,0.592478,-0.109186,-0.364863,0.316773,0.100287,0.108103,-0.336018,0.313796,-0.074284,0.117468,0.338048,-0.028687,-0.431369,0.340874,0.049306,-0.255174,-0.165692,0.112926,-0.343511,0.291567,0.677794,0.156547,-0.312750,0.003463,0.470970,-0.267769,-0.089963,-0.157628,0.344773,-0.228017,0.291603,0.338174,-0.168965,0.005296,0.215930,0.107803,-0.469951,0.098923,0.139278,0.379283,-0.339961,-0.008964,-0.104115,-0.063259,-0.057995,-0.406127,0.258140,0.268591,0.525826,0.258399,-0.063968,-0.033116,-0.465024,0.449688,0.381987,0.031554,0.040580,0.407496,0.197766,-0.235325,-0.054162,0.272621,-0.270035,0.249107,0.176178,-0.113425,-0.249994,0.028434,-0.628873,-0.187357,-0.332866,-0.199461,-0.204883,-0.157676,0.018774,-0.615620,-0.265250,-0.006072,-0.155441,-0.182352,0.266604,-0.018936,0.288082,-0.434070,0.191784,0.318471,0.177496,-0.644116,0.596509,0.287883,-0.136848,-0.209806,0.235662,-0.100921,0.099810,0.453931,-0.031313,0.276500,0.193118,-0.439299,-0.575812,0.113176', '2286642', '2334814', '1307897', '4135443');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6879185', '为奴十二年', '剧情', 'Solomon Northup（切瓦特·埃加福特 Chiwetel Ejiofor 饰）本来是一个自由人，以演奏小提琴为生，有一个妻子和两个孩子，生活其乐融融。不料他却被两个白人以为马戏团表演伴奏所骗，去了华盛顿，一觉醒来发现自己成了黑奴。起初他被卖给了Ford先生（本尼迪克特·康伯巴奇 Benedict Cumberbatch 饰），在庄园里当奴隶。不久又被卖给了素有“黑奴终结者”之称的Epps先生（迈克尔·法斯宾德 Michael Fassbender 饰），他在种植园里日复一日地采摘棉花，也目睹了许多黑奴的悲剧。12年过去了，他始终没有放弃重回自由人的希望，直到遇到了一个思想进步的人士——木匠Bass先生（布拉德·皮特 Brad Pitt 饰）。Solomon是否能结束他身为奴隶的命运？本片根据Solomon Northup的真人真事改编。©豆瓣', '切瓦特·埃加福', '史蒂夫·麦奎因', 8.3, 228639, 'tt2024544', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2167964789.jpg', 0.2, 0.9, 16.2, 50.6, 32.1, '0.491989,0.153031,-0.452582,0.429958,-0.177095,-0.590626,0.721706,0.102074,-0.333402,-0.340598,-0.042448,0.890655,-0.134592,0.053890,0.265554,0.223478,-0.239805,-0.478888,-0.083144,-0.137965,-0.105048,-0.280279,-0.299230,-0.045129,-0.095937,-0.199944,0.498589,-0.082956,-0.029279,0.497053,0.326987,0.264494,0.351009,0.130220,-0.348491,0.420203,0.346254,-0.194907,-0.091378,0.434414,-0.065228,-0.321349,-0.016456,-0.018320,-0.051300,0.400743,0.732818,-0.279018,0.047034,-0.021990,0.282148,-0.151984,-0.003492,0.229937,0.141933,-0.055735,0.168063,0.217908,-0.327721,0.183508,0.131548,-0.184049,-0.657846,-0.021831,-0.040027,0.158331,-0.818728,0.399549,-0.099199,-0.066605,-0.104991,-0.260868,0.351076,0.185977,0.289722,0.566019,0.097640,-0.093588,-0.765893,0.423465,0.769880,-0.006962,-0.205658,0.447839,-0.067507,-0.381403,0.187435,-0.306179,-0.437049,-0.047956,0.417860,-0.260161,-0.186228,0.054216,-0.731480,-0.053949,-0.462326,-0.226601,0.075379,-0.402617,-0.155882,-0.377751,0.057262,-0.173495,-0.200889,0.026391,0.084217,-0.227334,0.683859,-0.848192,0.192587,0.459442,0.116046,-0.183615,0.546626,0.063781,0.106983,-0.007246,0.072632,-0.104503,0.356449,0.348915,0.379671,0.491660,0.180165,-0.303088,-0.377530,0.430867', '129996