INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6880497', '盗钥匙的方法', '剧情', '小剧场演员樱井武史（堺雅人 饰）奋斗多年始终未见出头天，穷困潦倒，情场失意，绝望至极的他连自杀都不成功。无奈之下，他只得进入大众浴池洗澡，谁知却阴差阳错用一枚香皂滑到了某个陌生男子。男子倒地晕厥，樱井则鬼迷心窍偷走了对方的储物柜钥匙，从此化名近藤，过起了从来不敢企及的富贵人生活。然而令他怎么也想象不到的是，近藤（香川照之 饰）竟是一名名震黑道的冷血杀手。在此之后，樱井不得不接手来自黑道的委托，硬着头皮干起杀人的营生。与此同时，从医院醒来的近藤失去记忆，误以为自己是走投无路的樱井。在偶然结识的美丽女性水岛早苗（广末凉子 饰）的帮助下，他一点一滴重新认识作为演员的自己，苦苦探索前进的方向，在此过程中他和早苗的内心也悄悄发生变化。而当他的记忆恢复那一刹那，三个人的命运也由此纠缠到了一起……本片荣获2012年日本电影旬报十佳影片第八名。©豆瓣', '堺雅人', '内田贤治', 8.5, 146521, 'tt2078599', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1979399699.jpg', 0.1, 0.6, 12, 49.1, 38.2, '0.064736,-0.025118,-0.518330,0.383699,-0.367023,-0.304365,0.671629,0.150284,-0.528165,-0.322826,0.399181,0.789393,-0.083193,0.348438,0.206431,0.104460,-0.072401,-0.737726,-0.116312,0.075999,-0.176154,-0.186137,-0.330264,-0.090646,-0.294784,-0.134726,0.847305,0.176343,-0.290532,0.350396,0.306148,0.147823,-0.154762,0.416197,-0.084050,0.152438,0.064582,0.138971,-0.036051,0.306065,-0.168506,-0.548275,-0.175734,0.171642,-0.180499,0.448330,0.426469,0.044605,-0.087839,0.002994,0.319591,-0.282138,-0.386559,0.035556,0.194123,-0.124985,0.005134,0.032602,-0.301365,-0.037867,0.033234,0.352659,-0.654900,0.015340,0.138267,0.148963,-0.649590,0.380215,-0.075061,-0.070547,0.049287,-0.372755,-0.047567,0.001611,0.264554,0.010476,-0.321630,0.101157,-0.287992,0.487824,0.611155,0.133971,-0.315380,0.411332,-0.010079,-0.412925,-0.153670,-0.420227,-0.413499,-0.051655,0.139941,0.268845,-0.239316,0.135299,-0.347661,-0.012243,-0.067839,-0.172232,0.103721,-0.187170,-0.053581,-0.449637,-0.271529,-0.287429,-0.381705,0.045792,-0.041379,-0.288020,0.622219,-0.619369,0.077013,0.614403,0.039775,-0.210367,0.618351,0.075638,-0.186867,-0.191679,0.000877,0.550149,0.212987,0.469247,0.037747,0.210650,-0.159185,0.054400,-0.481929,0.493123', '25880986', '30162520', '1299663', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6880590', '神探亨特张', '动作', '便衣民警老张（张立宪 饰）在酒桌上跟一帮兄弟们开怀畅饮，用歌声道出了北京的苦辣酸甜。他们潜伏在川流不息的人群中，伺机而动，抓捕违法犯罪人员：无论是用电子干扰汽车车锁盗取财物的，还是用残疾人作诱饵碰瓷的，无论是拉帮结派的梁上君子，还是招摇撞变的算命先生……全都逃不过老张的法眼。老张的事迹甚至还上了北京电视台的纪录片。然而，眼看犯罪分子一个个落网，老张的内心却陷入了迷惘。他也是上有老下有小的普通人。多年的打拼，令老张的身体也亮起了红灯，他有哮喘，有高血压，但是为了抓贼，他努力地克服着自己的困难。然而，他门口总有一个不离不弃的尾随者，很多光怪陆离的事件接连发生，令老张和他的弟兄们猝不及防……本片根据北京市海淀分局双榆树派出所民警张慧领的真实事迹改编。本片为高群书《“你”系列：1930-2030》系列，张立宪、孔二狗、王小山、作业本、宁财神等约30位微博名人倾力加盟。', '张立宪', '高群书', 7, 40584, 'tt2273470', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1811301257.jpg', 2.5, 8.7, 39, 37, 12.8, '0.360047,-0.214687,-0.468779,0.520292,-0.026548,-0.231077,0.739912,0.005186,-0.457085,-0.020929,0.271099,0.452131,-0.083273,0.340237,-0.019550,-0.136464,-0.342918,-0.699812,-0.197473,-0.007049,-0.205780,-0.283726,-0.291300,-0.170863,-0.261436,0.138415,0.319635,0.265422,-0.115463,0.167490,0.436757,-0.043203,-0.052896,0.310887,-0.217199,0.013279,-0.081572,-0.125770,-0.117121,-0.191619,0.176935,-0.633707,-0.379419,-0.019847,0.097069,0.386233,0.462010,-0.072296,-0.275718,0.249582,0.251036,-0.437360,-0.065348,-0.037395,0.198697,0.280750,0.090274,0.009736,-0.063002,0.062120,-0.125662,0.171365,-0.726610,-0.026717,0.064578,0.067179,-0.594414,0.220190,-0.181905,0.077797,0.065860,-0.212451,0.227497,0.125096,0.109137,0.304066,-0.149820,-0.060566,-0.559306,0.337297,0.460909,0.079712,-0.335849,-0.089637,-0.272958,-0.461761,-0.061420,-0.162268,-0.414609,-0.128158,0.389184,-0.292877,-0.251780,0.137361,-0.446942,0.128312,0.028953,-0.243586,-0.315441,-0.109332,-0.123832,-0.670030,-0.060767,-0.420885,-0.147611,0.179517,0.165452,-0.131342,0.718051,-0.621386,-0.058606,0.502198,-0.015062,-0.468805,0.662389,-0.003348,0.011730,0.064608,-0.323084,-0.164411,0.155882,0.567779,0.320585,0.487224,-0.103230,-0.185595,-0.204383,0.270521', '1308842', '4301278', '26926321', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6886490', '车警官', '喜剧', '相貌平平的车哲秀（姜至奂 饰）是一名业务干练的警官，但是他生活邋遢懒散，臭气熏天，出警用的车内堆满几百年没洗的脏衣服，脱下的臭袜子能直立站住，混在嫌疑犯堆儿里总会被受害人指认。某天，上司交给他和伙伴们一项重要任务，让他们派人假冒模特混入服装界，充当当红模特金善浩的保镖。所谓保镖，实际上是暗中搜查金善浩的犯罪证据。这个表面光鲜的模特暗中从事毒品勾当，甚至还杀害了此前监视他的警察。阴差阳错之下，车哲秀被选为卧底，借此机会还重逢了高中喜欢的女孩高英才。不过为了成为合格的模特，痴肥的车警官不得不在英才的监督下开始了减肥和培训的大业……©豆瓣', '姜至奂', '申太罗', 6.2, 6168, 'tt2182095', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1663193253.jpg', 3.3, 16.5, 53.7, 20.8, 5.7, '0.387970,-0.230427,-0.302700,0.294572,-0.546957,-0.202406,0.306633,0.154643,-0.526353,-0.420885,0.394931,0.539229,-0.041923,0.030863,0.215840,0.097078,-0.312569,-0.854835,-0.144823,-0.087519,-0.282286,-0.259842,-0.217701,-0.260953,-0.189668,-0.329380,0.490612,0.023854,-0.070756,0.404500,0.621931,0.137152,-0.197388,0.106671,-0.464832,-0.259879,0.340096,-0.276031,-0.086188,0.158830,-0.091551,-0.217025,0.039752,0.079819,0.066276,0.466009,0.498594,0.089610,-0.230799,-0.021282,0.354652,-0.376856,-0.098990,-0.029136,0.450928,0.090464,0.157393,0.345000,-0.072388,0.168520,-0.030840,-0.035938,-0.754243,-0.089206,0.123143,0.111358,-0.567554,0.534014,-0.120585,0.123080,-0.018733,-0.212777,0.147760,-0.068831,0.027675,0.315984,0.233343,0.359831,-0.670410,0.461712,0.424222,0.252705,0.024864,0.231596,-0.204810,-0.196293,0.085946,-0.527787,-0.279825,-0.073819,0.179419,-0.408767,-0.148349,-0.243184,-0.570098,0.061715,-0.284320,0.109570,-0.075792,-0.108823,-0.374766,-0.254099,-0.072089,-0.315430,-0.237492,0.070433,0.073409,-0.364556,0.639598,-0.720846,-0.241442,0.519867,0.255490,-0.615805,0.506003,0.043628,0.205985,-0.180664,-0.656695,-0.320109,0.437638,0.294800,0.043418,0.428847,-0.366955,-0.505498,-0.514869,-0.205963', '1877596', '4301278', '1793491', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6886518', '柏林', '剧情', '德国首都柏林，一起失败的军火交易使朝韩各方势力的对抗趋近白热化。朝鲜大使李学秀（李庆荣 饰）及间谍表宗盛（河正宇 饰）发现来自祖国的另一名冷血间谍董明秀（柳承范 饰）现身柏林，政权更迭让多年漂泊海外的他们心中充满不祥预感。在此期间，宗盛不得不遵照党的指示监视妻子——大使贴身翻译莲贞熙（全智贤 饰）的行踪。另一方面，在追查军火交易行动中遭受挫折的韩国情报机构负责人姜部长（韩石圭 饰）不甘失败，持续追查宗盛的踪迹。在大使叛逃计划失败后，宗盛得知董明秀来到柏林的真正目的。为了避免成为权力斗争的牺牲品和肃清对象，他只得带着妻子绝路逃亡……©豆瓣', '河正宇', '柳昇完', 7.5, 63381, 'tt2357377', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1839794234.jpg', 0.4, 2.7, 34.4, 47.1, 15.5, '-0.148018,0.146327,-0.631181,0.699082,0.225194,0.144460,0.079073,0.264281,-0.673387,-0.487473,0.213155,0.456822,-0.222911,-0.092740,0.419293,-0.273503,-0.312442,-0.718974,-0.278424,-0.026894,0.016299,-0.460599,-0.220978,-0.548200,-0.243179,0.003979,0.758625,0.452601,-0.461313,0.616858,0.521423,0.576240,-0.366266,0.412555,0.291477,-0.163699,0.423218,-0.305457,-0.654034,0.141605,0.183344,-0.316949,-0.050280,0.217294,0.197685,0.396181,0.446975,-0.087437,0.096547,-0.254591,0.258073,-0.496869,0.052485,0.119050,0.634770,0.270302,-0.301945,0.466494,-0.168038,0.012903,0.081693,0.057724,-0.546837,0.040829,0.269567,0.098043,-0.335575,0.074190,-0.088254,0.210442,0.024489,-0.139857,0.420660,0.664332,0.283703,-0.049378,0.184246,0.371003,-0.343158,0.299597,0.682043,-0.315697,0.068130,-0.578565,0.044670,-0.280299,0.090665,-0.368522,-0.153384,-0.137261,0.160047,-0.177140,0.085648,0.383552,-0.475625,-0.138761,-0.411596,-0.003690,0.165188,-0.212966,0.204057,-0.739589,-0.279841,-0.397243,-0.171512,0.329051,0.056714,-0.050235,0.424881,-0.593796,0.137148,0.491857,0.361998,-0.835254,0.277526,0.447706,0.074538,-0.703718,-0.042100,0.522870,0.117004,0.378944,-0.057810,-0.440149,-0.062995,-0.334043,-0.154927,-0.246920', '10437779', '1307914', '1484760', '1299250');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6887029', '醉乡民谣', '剧情', '故事发生在六十年代的美国，勒维恩（奥斯卡·伊萨克 Oscar Isaac 饰）是一位名不见经传的民谣歌手，生活困顿的他无家可归亦没有固定的工作，每晚得靠朋友们的救济才得以寻得安身之处。可是，尽管陷入了窘境，但固执的勒维恩却不愿意了顺应大众的喜好而做出无奈的改变，也正因为此，他和交往多年的好友简（凯瑞·穆丽根 Carey Mulligan 饰）和吉姆（贾斯汀·丁伯莱克 Justin Timberlake 饰）之间的关系也跌落到了冰点，更让勒维恩感到烦心的是，简的腹中竟然怀上了自己的孩子。之后，勒维恩前往芝加哥企图找到一份工作，却在面试之后惨遭拒绝，之后，一无所获的他回到了格林尼治村，继续回到曾经兼职的小酒馆打工。熟悉的场景，熟悉的音乐，熟悉的氛围，勒维恩经历了许多，却又好像什么都没有发生过。©豆瓣', '奥斯卡·伊萨克', '伊桑·科恩', 8.1, 121561, 'tt2042568', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2156418604.jpg', 0.3, 1.5, 19.6, 50.2, 28.5, '0.415221,-0.019261,-0.868181,0.645250,-0.242587,-0.526346,0.919482,0.172303,-0.707727,-0.432405,0.038876,0.744208,-0.170266,0.432596,0.216907,-0.039737,-0.128207,-0.742472,0.080810,-0.131331,-0.293491,-0.461104,-0.320448,-0.205713,-0.194403,-0.164259,0.411201,0.195207,-0.213093,0.320849,0.226727,0.254021,-0.009493,0.763710,-0.159052,0.061303,-0.040569,0.429893,-0.203199,-0.086072,0.239140,-0.387091,-0.343219,0.099598,0.414414,0.593293,0.614666,-0.123118,-0.509897,0.233553,0.326177,-0.159300,-0.132000,0.057662,0.138934,0.072295,0.096105,0.154016,-0.270277,0.035417,-0.031793,0.131308,-0.823540,0.275955,0.034381,0.315914,-0.655604,0.520370,-0.068516,-0.156148,-0.243932,-0.542236,0.368629,0.531715,0.328323,0.400878,-0.093781,0.125876,-0.466941,0.167185,1.065254,0.162850,-0.500529,0.516023,-0.333610,-0.462457,0.025919,-0.177353,-0.493575,0.049805,0.144690,0.181162,-0.289511,0.123977,-0.518333,-0.159077,-0.213182,-0.349640,0.015051,-0.447741,-0.022988,-0.580780,-0.128381,-0.507788,-0.363017,0.081180,0.104993,-0.362017,0.618291,-0.928579,0.282796,0.435637,0.216187,-0.634815,0.622181,0.135026,0.180053,0.015173,0.051124,0.390610,-0.078150,0.340354,0.178919,0.227122,-0.036462,-0.159959,-0.507291,0.519253', '1301022', '25721544', '1308755', '1292064');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6888712', '曲线难题', '剧情', '加斯（克林特·伊斯特伍德 Clint Eastwood 饰）是亚特兰大勇士队的资深球探，然而近来他可够呛。上了年纪又有些视力衰退的他因此被认为已经无法适应当今变化的市场，并被分配了最后一次招新任务来证明自己的价值。加斯的老板兼好友彼特（约翰·古德曼 John Goodm an 饰）有些不忍，便找来了加斯的女儿米琪（艾米·亚当斯 Amy Adams 饰）帮忙一起完成这段任务旅程。然而这并不是什么轻松的事，自从米琪六岁丧母后，父女俩的关系就不见得多好，不巧还搭上了对手球队的年轻球探约翰尼（贾斯汀·丁伯莱克 Justin Timberlake 饰），一路上的磕磕绊绊可不少。面对这堆难题，三人最后能否顺利渡过？©豆瓣', '克林特·伊斯特伍德', '罗伯特·洛伦兹', 7.3, 9873, 'tt2083383', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1716299744.jpg', 0.4, 3, 38.8, 46.1, 11.7, '0.335745,0.071587,-0.482356,0.340976,-0.284152,-0.724672,0.306687,0.097630,-0.790457,-0.229193,-0.059729,0.585210,-0.346797,-0.006122,0.155071,0.163981,-0.157909,-0.456262,0.379611,-0.143423,-0.312759,-0.663572,-0.349522,-0.108128,-0.044540,-0.199353,0.350155,-0.000970,0.070212,0.468283,0.414590,0.159386,0.241512,0.626972,-0.062107,0.316910,0.267274,-0.127802,-0.081836,0.165527,0.112896,-0.092359,-0.179631,0.330146,0.298409,0.427096,0.305451,0.090864,-0.075866,0.152304,0.126522,-0.198378,0.104800,0.300742,0.290253,-0.097059,0.283635,0.129920,-0.135254,-0.146681,-0.090496,-0.080627,-0.706454,0.160836,0.167314,0.118623,-0.695836,0.320471,-0.262078,-0.086618,-0.247491,-0.291550,-0.046443,0.664567,0.362313,0.289754,0.018343,-0.204747,-0.442060,-0.031183,0.421404,0.067817,-0.213275,0.414033,-0.196270,-0.487466,-0.153412,-0.252689,-0.350486,0.285493,0.447944,0.159344,-0.105815,0.133337,-0.402331,0.166407,-0.410522,-0.249317,-0.317213,-0.260304,0.195717,-0.446844,0.119361,-0.556079,-0.649463,-0.028311,0.105010,-0.264002,0.405880,-0.595297,0.163130,0.703163,0.144727,0.019936,0.298248,0.233600,0.290726,-0.251909,-0.221987,-0.095037,-0.225295,0.295754,0.327160,0.335287,0.099684,-0.589419,-0.303954,0.610562', '1307442', '30135113', '20277433', '1922691');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6889533', '乌鸦的拇指', '剧情', '武泽竹夫（阿部宽 饰），绰号“老武”，人过中年的他是一个有着丰富经验的职业欺诈师，他与貌不惊人并且反应迟钝的入川铁巳“老铁”（村上昭二 饰）不打不相识，将后者引入行与自己结为搭档，穿行于都市的各个角落，银行、赛马场、当铺随处可见他们行骗的身影。拥有不堪回首过去的二人相互扶持，在底层过着不咸不淡的生活。某天，这对搭档与姐妹花河合八寻（石原里美 饰）、河合真寻（能年玲奈 饰）以及男孩石屋贯太郎（小柳友 饰）的人生发生交集。五个人生处于最底层的人，组成了一个略显别扭的临时家庭，他们朝着人生的转折点携手前进……本片根据2011年直木赏得主道尾秀介的同名原著改编。©豆瓣', '阿部宽', '伊藤匡史', 7.7, 11874, 'tt2005255', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1795123431.jpg', 0.5, 2.1, 27.3, 51.4, 18.6, '0.299936,-0.216473,-0.314940,0.541677,0.014666,-0.148828,0.784319,0.064786,-0.456719,-0.165557,0.267605,0.777672,-0.120469,0.302286,0.409498,-0.172902,-0.127600,-0.563982,-0.252058,-0.229022,-0.183775,-0.386208,-0.409690,-0.162715,-0.442989,-0.109372,0.759513,0.049727,-0.202100,0.429770,0.321672,0.442206,-0.227148,-0.119382,-0.361853,0.234124,0.035262,0.130383,-0.415408,0.128135,-0.561747,0.021887,-0.248548,-0.257648,0.006778,0.140722,0.875806,-0.288274,-0.194884,-0.119118,0.386687,0.050249,-0.393948,0.034868,0.175379,0.126479,0.238810,0.268594,-0.081671,-0.026285,0.092949,-0.126006,-0.670107,-0.040280,0.163072,0.235280,-0.490149,0.494222,0.165675,-0.285769,0.172954,-0.301910,-0.007460,0.250740,0.385885,0.263225,-0.191195,0.126184,-0.286552,0.385149,0.512750,0.270633,-0.340346,0.345503,-0.287523,-0.563977,-0.345984,-0.127334,-0.372734,-0.179175,0.156861,-0.139737,0.117814,0.004003,-0.711672,0.168593,0.225129,-0.105800,0.179596,-0.277863,-0.160517,-0.653442,-0.230435,-0.838459,-0.581929,0.273652,0.149596,-0.168577,0.815521,-0.678032,-0.115523,0.449742,0.201762,-0.242638,0.846767,0.045886,0.186700,-0.345691,-0.074681,0.094185,-0.012184,0.165020,0.037742,0.543679,-0.224291,0.085727,-0.461474,0.194297', '3811356', '25880986', '24839498', '5416009');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6890343', '追爱', '喜剧', '台北的漫画作者杨纯纯（应采儿 饰）在爱情的道路上频频遇人不淑，而她作品的销路也日渐下滑。杨父要纯纯陪他回大陆看看长城，却被女儿拒绝，谁料杨父独自前往嘉峪关时急病去世，杨父在弥留之际拜托纯纯找到自己当年在大陆的初恋秀倩，纯纯怀疑父亲曾经在大陆结婚，做出了对不起母亲的事情，决定返回老家一查究竟。此时杨父生前在火车上结识的私家侦探方明迪（佟大为 饰）受杨母委托，为纯纯担任向导，性格不甚合拍的二人一见面即唇枪舌剑，但碍于现实情况又不得不同行。在杨父位于雁门关下的老家，二人查知秀倩远嫁银川，他们为寻找杨父曾经的爱情继续前行，而一场新的爱情，又于他们之间发生……©豆瓣', '佟大为', '刘怡明', 6, 5048, 'tt1895373', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1310085317.jpg', 6.2, 19.5, 49.3, 18.6, 6.4, '0.293783,0.067372,-0.829516,0.618985,0.225682,-0.471283,0.394420,0.126707,-0.520692,-0.309679,0.239034,0.803687,-0.089274,0.218725,0.235899,-0.045871,-0.182043,-0.410389,0.225247,-0.052435,-0.284352,-0.420980,-0.015630,-0.008039,-0.191186,0.048625,0.475366,-0.028283,-0.134552,0.474138,0.183881,0.232076,-0.189978,0.421840,-0.094059,0.213543,-0.065442,0.428815,-0.621515,0.069551,0.326180,-0.244206,-0.219544,0.051583,0.035063,0.209056,0.583100,-0.083108,-0.191218,-0.011940,0.278915,-0.252082,0.151992,-0.124104,0.365138,-0.097906,0.030494,0.314113,-0.348575,-0.069399,0.095623,0.114443,-0.269288,0.054492,0.074274,0.157244,-0.506313,0.239035,-0.254930,0.000915,0.071729,-0.591115,0.209945,0.624248,0.182160,0.286709,-0.240320,-0.015021,-0.328267,0.315685,1.000414,0.272494,0.232406,0.322794,-0.208519,-0.096762,0.167472,-0.170049,-0.645562,0.172343,0.074810,0.033708,-0.264254,0.105260,-0.370455,-0.234803,-0.160205,-0.152564,0.118723,-0.409180,0.028752,-0.489743,-0.226992,-0.388837,-0.170754,-0.112451,0.161779,-0.422470,0.429621,-0.817852,0.127700,0.222358,0.383238,-0.770857,0.681821,0.406057,0.191750,-0.299050,0.195374,0.336490,-0.145984,0.220777,-0.104043,-0.018960,-0.084886,0.011806,-0.452142,0.285371', '1308035', '25721544', '4145476', '1494897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6890469', '双城计中计', '剧情', '民国初年，军阀混战，战祸四起，民不聊生。乱世之中，却为一群以骗术为生的老千们，提供了展露身手的舞台。黑帮老大林啸天（刘承俊饰）从一名老千处得知日本人将给军阀王大帅（九孔饰）十二箱金子作为军阀与北伐军抵抗的资金。为了得到这批金子，林啸天开始招兵买马，其中江湖中有千面人之称的老千“鬼脸”（任贤齐饰）和“不动石佛”大老千（腾格尔饰）成了林啸天首先拉拢的目标。谁知“鬼脸”与“石佛”竟然是不能见面的仇家，两人为了置对方于死地，展开了一场骗术的大较量，不料两人在这场较量中势均力敌。期间“鬼脸”遇见了假扮修女行窃的 “饺子”（熊乃瑾饰），善于开锁的“饺子”也被搅进了林啸天的阴谋之中。一行人浩浩荡荡的赶往黄金的交易地点“风口镇”。风口镇是一个人迹罕至的小镇，总共只有百十户人家，却有着当地令人闻风丧胆的土匪团伙，领头的金三娘（翁虹饰）在一场混战中却看上了“石佛”，执意要抢石佛做她的“压寨先生”。为了神不知鬼不觉的拿到黄金，“石佛”提出了一个惊天的偷梁换柱计划——双城计，把另一座已经废弃的小镇——“落水镇”变成“风口镇”，为此一场关于黄金矿藏的计划紧锣密鼓的展开。', '任贤齐', '潘安子', 6.6, 14556, 'tt2435870', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1419162379.jpg', 2.3, 9.8, 49.7, 30.9, 7.3, '0.258383,0.106376,-0.495701,0.520630,-0.119607,0.026457,0.512049,0.078249,-0.425133,-0.008518,0.313959,0.701124,-0.129834,-0.252356,0.019557,-0.225045,0.017761,-0.677680,-0.522348,-0.188985,-0.110814,-0.232200,-0.500782,-0.100457,-0.255807,0.167649,0.470926,0.326918,-0.217533,0.330631,0.639920,0.259011,-0.346673,0.116011,-0.303912,-0.116716,0.014846,-0.099503,-0.404876,0.306651,-0.396598,-0.317258,-0.236284,0.116999,0.002478,0.482061,0.714271,-0.376550,0.032775,-0.270026,0.051259,-0.214234,-0.163528,0.074223,0.469287,0.005051,0.294620,0.002055,-0.230662,0.010316,0.177133,-0.119611,-0.713994,-0.049550,0.401569,0.035696,-0.733172,0.321229,0.213607,-0.129178,0.016993,-0.072296,0.255423,0.408946,0.415666,0.115049,0.001941,-0.103968,-0.667328,0.134094,0.551594,0.036214,0.144587,0.058058,0.303761,-0.479194,0.223663,-0.434500,0.044804,-0.071482,0.459496,-0.391258,-0.010121,0.094140,-0.827806,-0.132939,-0.420032,-0.040216,0.101931,-0.260527,-0.328587,-0.588354,-0.006827,-0.111819,-0.026631,0.397584,0.141757,0.063199,0.500334,-0.720783,-0.050307,0.574954,0.128572,-0.185460,0.381945,0.015121,0.158832,-0.275291,-0.200780,-0.420926,0.209298,0.476088,0.186053,0.240545,-0.214874,-0.405298,-0.243564,0.379921', '1292829', '26290398', '2032339', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6890730', '寒战', '剧情', '作为亚洲金融中心的香港被称作“最安全的城市”，岂料警局接到一通匿名电话，对方声称劫持了警队的一辆前线冲锋车以及车内的五名警员和武器装备。此次事件引起了香港警队高层的高度重视，适逢处长（王敏德 饰）出访国外，此时由鹰派人物行动副处长李文彬（梁家辉 饰）与年轻的管理副处长刘杰辉（郭富城 饰）一起负责这次案件，并将行动命名为“寒战”，李文彬任总指挥。李文彬的儿子（彭于晏 饰）也是人质之一，刘杰辉因此对李文彬父子产生怀疑。与此同时，匪徒展开了进一步行动：警察被杀、爆炸案频发……到底是谁在将整个警队玩弄于鼓掌之中？香港真的是“最安全的城市”吗？©豆瓣', '郭富城', '梁乐民', 7.6, 358869, 'tt2186715', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1741835010.jpg', 0.4, 2.6, 31.1, 50.4, 15.4, '0.239483,-0.128545,-0.582793,0.512157,-0.009397,0.141457,0.292806,0.154312,-0.675582,-0.247125,0.303054,0.783447,-0.016842,-0.177306,0.358072,-0.206092,-0.212619,-0.731794,-0.360162,0.002752,-0.275128,-0.582293,-0.114826,-0.070162,0.007312,-0.191340,0.468925,0.191614,-0.281279,0.655267,0.416500,0.575512,-0.354049,0.418856,0.180726,-0.304746,0.292094,-0.298644,-0.520664,0.124749,-0.146286,-0.504156,0.078823,0.243658,0.204494,0.303544,0.562641,0.007766,-0.304911,-0.442964,0.271905,-0.660965,0.009747,-0.376062,0.706875,0.240114,0.380106,0.515825,-0.230176,0.226606,0.140336,-0.071735,-0.560331,0.216680,0.112726,-0.062624,-0.442350,-0.027311,-0.360921,-0.073745,0.119056,-0.101930,0.768685,0.513921,0.038691,0.144807,-0.044857,0.132759,-0.420447,0.016553,0.695536,-0.026824,0.257427,-0.203487,0.037809,-0.578331,-0.022995,-0.194283,-0.046214,0.104375,0.052241,-0.301485,0.197417,-0.097264,-0.314565,-0.123616,-0.190363,-0.482671,0.161453,-0.425133,0.038642,-0.681793,0.068392,-0.082728,-0.095848,0.133033,0.160972,0.256175,0.495117,-0.942677,-0.160481,0.475130,0.261305,-0.827088,0.402173,0.140207,0.204037,-0.318753,-0.041536,-0.271625,0.487024,0.506935,-0.128274,0.076607,-0.234328,-0.561340,-0.248723,-0.177032', '1293265', '1482541', '30345227', '3002820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6890737', '光辉岁月', '剧情', '清朝末年，局势动荡，乱相纷现。曾经历黄花岗起义的南国革命党人铁云（黄日华 饰）和志同道合的战友勇闯大漠，偷运黄金，准备购买大批军火再次起事。谁知途中遭到博尔格亲王（吕良伟 饰）之爪牙满天红（倪虹洁 饰）的伏击，关键时刻幸得满腔赤诚的从四品官卓知府（狄龙 饰）出手相救。卓知府具有远见卓识，虽身处敌我两派，但仍将国家的命运寄托在铁云身上，安排他前往黄金峡寻找善良热情且不乏豪气的猫老板（曾志伟 饰），为此甘愿陪上满门家小性命。猫老板是曾参加过义和团的勇士，由他守护的黄金峡云集了来自四面八方的仁人义士。大家不讲革命，不关心政治，在这个安宁所在过着世外桃源的生活。随着铁云的到来，黄金峡的宁静被彻底打破。隐退江湖的英雄们为国为家，再展身手……©豆瓣', '曾志伟', '熊欣欣', 4.7, 4424, 'tt3552642', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1992862530.jpg', 20.1, 37.6, 34.1, 4.7, 3.3, '0.069231,0.094767,-0.595915,0.394160,0.146981,0.071236,0.393562,0.203781,-0.539037,-0.279213,0.340305,0.530704,0.076439,-0.092275,0.174866,-0.089330,0.078271,-0.524980,-0.190686,0.076876,0.149660,-0.124279,-0.262812,0.082094,-0.432866,-0.137439,0.523992,0.301992,-0.065557,0.640915,0.220733,0.490093,-0.220883,0.453195,-0.213660,-0.078030,-0.005547,0.078959,-0.472415,0.066742,-0.345918,-0.328822,-0.189757,0.130297,0.031830,0.368044,0.400792,-0.391617,0.083253,-0.172299,0.227858,-0.255822,0.145352,0.212176,0.317481,0.119801,0.106794,0.186741,-0.035300,0.088351,0.000988,-0.159360,-0.528782,-0.131945,0.309458,0.092211,-0.601651,0.313015,-0.061796,-0.090016,-0.125261,-0.211380,0.317677,0.338796,0.046941,0.039980,0.052539,0.061346,-0.450066,0.310209,0.889490,-0.166482,0.081807,-0.223501,-0.039763,-0.273470,0.328033,-0.362077,-0.467398,-0.107347,0.208780,-0.130562,0.134924,0.409403,-0.658758,0.006288,-0.323360,-0.020171,0.232924,-0.057490,-0.076953,-0.428250,-0.258140,-0.367139,-0.198578,0.126532,0.253970,-0.071101,0.810332,-0.730238,-0.015001,0.113440,0.200109,-0.618245,0.468005,0.155840,-0.015909,0.038354,-0.075797,0.281059,0.281822,0.202380,-0.042278,-0.041023,-0.189637,-0.304765,-0.163822,0.178881', '25721544', '35030151', '1870682', '1480318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6893932', '壮志凌云2：独行侠', '动作', '作为海军顶尖飞行员服役30多年后，皮特·米切尔（代号：“独行侠”）（汤姆·克鲁斯 饰演）决定打破体制的限制，成为一名试飞员接受更大的挑战。当他接到命令，为一项高难度特殊任务训练一群“高空利剑”项目的毕业生时，他遇到了已故的好友兼雷达截获官，代号“笨鹅”的尼克·布拉德肖中尉之子布莱德利·布拉德肖中尉（代号：“公鸡”）。面对不确定的未来和难以释怀的心魔，独行侠必须战胜内心深处的恐惧。因此，他参与了一项需要巨大牺牲才能完成的任务。', '汤姆·克鲁斯', '约瑟夫·科辛斯基', 8.1, 89317, 'tt1745960', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2870610648.jpg', 0.5, 2.2, 20, 49.1, 28.1, '-0.010504,0.206270,-0.448420,0.883010,-0.266808,-0.058779,0.256120,-0.023521,-0.290157,-0.576001,0.116662,0.758587,0.209379,0.074478,0.493018,-0.329988,-0.042817,-0.485684,-0.215612,0.042208,-0.390038,-0.628623,-0.337664,-0.571653,0.003991,-0.287548,1.070404,0.048235,-0.288785,0.253921,0.491737,0.531589,0.400461,0.116645,0.214193,-0.509881,0.602894,-0.142687,-0.368544,0.206921,-0.184352,0.206835,0.107178,0.070078,0.104911,0.361089,0.266604,-0.253792,-0.293858,-0.477941,0.259920,-0.433987,0.199340,-0.271827,0.195946,0.231997,-0.306437,0.146998,0.130883,0.248934,-0.182198,-0.187608,-1.017847,-0.267376,0.145231,-0.035931,-0.409044,0.116581,-0.406137,0.235563,0.051682,-0.068892,-0.148191,0.170277,0.252838,0.391496,-0.300916,0.334454,-0.216472,0.362985,0.733849,-0.101204,-0.711879,-0.227205,-0.096026,-0.604046,0.193411,-0.527054,-0.178502,0.054024,0.133251,0.270183,0.002887,0.232927,-0.047954,-0.185798,-0.398604,-0.194297,-0.028660,-0.596656,0.048863,-0.704167,0.135298,0.045755,-0.203159,0.147101,0.169549,-0.539982,0.730000,-0.880206,0.187829,0.359893,-0.045991,-0.369733,0.537859,0.348931,0.355541,-0.670910,0.385372,0.228726,0.141963,0.209927,0.005424,-0.073849,-0.000922,-0.272744,0.064129,0.339268', '3861846', '27073234', '25880986', '24875409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6893934', '付出与收获', '喜剧', '作为一名健身教练，丹尼尔（马克·沃尔伯格 Mark Wahlberg 饰）有着诸多难言之隐，为了能够在竞争激烈的职场上保持优势，他不得不做着比别人强百倍的努力，其中包括吃药和注射，它们都价值不菲，因此，丹尼尔的生活始终都处于窘困之中。受够了囊中羞涩的日子，丹尼尔决定通过抢劫来改变自己的生活，他的目标是健身馆的常客维克多（托尼·夏尔赫布 Tony Shalhoub 饰），与此同时，丹尼尔还找到了经验丰富的“行家”保罗（道恩·强森 Dwayne Johnson 饰）作为搭档。一切计划都在顺利的进行当中，直到一个名叫艾德（安东尼·麦凯 Anthony Mackie 饰）的私家侦探出现在丹尼尔和保罗的生活之中。©豆瓣', '马克·沃尔伯格', '迈克尔·贝', 6.4, 20114, 'tt1980209', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2024537107.jpg', 2, 13.2, 53.2, 24.3, 7.3, '0.027269,-0.030766,-0.617466,0.622018,-0.259195,-0.228482,0.599107,0.062620,-0.418079,-0.509739,0.192539,0.593823,0.073539,0.120484,0.238936,-0.388226,-0.298931,-0.581616,-0.014404,-0.062010,-0.230701,-0.655910,-0.486219,-0.281013,-0.298527,-0.363502,0.516915,-0.072062,-0.210016,0.189785,0.215723,0.391750,0.261666,0.210200,-0.015444,-0.216841,0.262754,-0.297101,-0.558960,0.261547,0.119752,-0.072731,-0.138605,0.081964,0.475975,0.283268,0.563240,-0.225684,-0.248914,0.095671,0.112190,-0.046855,0.034324,0.113880,0.251234,0.010436,0.080036,0.219210,-0.259023,0.370862,0.050170,-0.158643,-0.949131,-0.053661,0.315147,0.141950,-0.553292,0.372061,-0.009089,-0.065280,-0.135565,-0.252418,0.047335,0.362190,0.246758,0.163767,-0.015106,0.147007,-0.446232,0.099707,0.641606,0.007829,-0.299609,0.173461,-0.261073,-0.318799,-0.182772,-0.277086,-0.540629,-0.154825,0.065136,0.096122,0.068700,0.124371,-0.374030,0.268877,-0.019726,-0.399376,-0.078931,-0.301460,0.001206,-0.874496,-0.043176,-0.484951,-0.316253,0.076316,-0.131458,-0.452082,0.598314,-0.902401,0.080092,0.536674,0.164648,-0.360734,0.517646,0.047409,0.304390,-0.361754,-0.491210,0.313375,-0.023602,0.005597,-0.030109,0.278032,0.222648,-0.195318,-0.249318,0.659264', '1793491', '1307442', '3006783', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6895950', '火箭人', '剧情', '由《飞跃奇蹟》导演戴克斯特佛莱契执导，《火箭人》是叙述英国国宝级歌手艾尔顿强爵士的故事，如何从英国皇家音乐学院的奇才，变成了流行音乐界的天王，当今乐坛的传奇人物。片名取自艾尔顿强经典名曲〈ROCKETMAN〉，泰隆艾格顿挑战华丽多变、大胆前卫的舞台造型，以及一边弹钢琴一边大展爆发力的歌喉，唱出一首首观众耳熟能详的动人歌曲，绝对是不能错过的音乐奇想电影。', '塔伦·埃哲顿', '德克斯特·弗莱彻', 7.2, 19621, 'tt2066051', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2553820571.jpg', 0.8, 5.1, 39.1, 41, 14, '-0.081238,-0.163257,-0.310834,0.915223,0.242260,0.143909,0.359258,0.276435,-0.387510,0.053125,0.481873,0.799422,-0.388037,-0.136922,0.300233,0.097282,-0.309175,-0.715684,0.195093,0.241495,0.379898,-0.302597,-0.138249,-0.022120,0.048072,-0.428188,0.395019,-0.219858,-0.729982,0.313985,0.515136,0.005800,0.145417,-0.299329,-0.183371,-0.130543,0.225812,-0.009136,-0.279186,0.312091,0.111333,-0.008549,-0.327216,-0.153536,-0.238892,-0.410887,0.299934,-0.204791,0.525834,0.268293,0.982158,-0.068911,-0.104249,-0.523242,0.094298,0.082876,0.313173,0.050303,0.256460,0.113007,-0.440587,-0.081435,-0.979748,0.276730,0.332239,0.094383,-0.257640,0.411960,-0.384884,-0.119737,0.109273,-0.122210,-0.128249,-0.528622,0.456030,0.446067,0.303185,0.324475,-0.259590,0.420925,0.503255,0.590544,-0.785446,0.231858,-0.015689,-0.293125,-0.339488,-0.835976,-0.366308,0.239757,0.133521,-0.326258,0.464021,0.069662,-0.222110,-0.077065,0.024466,-0.186951,0.134238,-0.192317,-0.540787,-0.698008,0.080021,-0.015614,0.327399,-0.505343,0.116654,-0.281958,1.311614,-0.561373,-0.053219,0.402086,-0.250574,0.173285,0.657139,-0.354725,-0.247258,-0.090144,-0.506785,0.220894,-0.231731,-0.166249,-0.161278,0.515653,-0.037176,-0.592604,-0.440680,0.318817', '27602116', '24284209', '22265121', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6900092', '建筑学概论', '爱情', '胜民（严泰雄 饰）在一家建筑公司担任建筑设计师，某日接到一份新的房屋设计工程，委托人竟是自己学生时代的梦中情人瑞英（韩佳人 饰）。两人相识于多年前大学的建筑学概论课堂上，20岁的胜民（李济勋 饰）对这个来旁听的音乐系的女生瑞英（裴秀智 饰）一见钟情。两人在每日的相处间日渐亲密起来。只是当时年轻的胜民害羞生涩，始终无法合适的表达出自己的爱意，最终使这段美好的初恋无疾而终。多年后，胜民和瑞英的这次重逢，使得旧时未褪去的爱情又重新散发光彩。只是现在的二人已不再是当年无所牵挂的学生，胜民早已有了自己的未婚妻。胜民和瑞英是否还能延续年少时的爱情？©豆瓣', '李帝勋', '李勇周', 7.5, 110663, 'tt2337981', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2207672645.jpg', 0.5, 3.3, 33.8, 44.7, 17.8, '0.373094,0.116273,-0.814601,0.609669,-0.163780,-0.442674,0.688118,0.063130,-0.615180,-0.274888,0.216636,0.687877,-0.259824,0.518432,0.038323,0.109402,-0.238599,-0.902268,-0.120377,-0.256823,-0.024274,-0.519983,-0.226023,0.278169,-0.407809,-0.201886,0.849118,0.108373,0.039060,0.522240,0.174527,0.049374,-0.057441,0.202212,-0.117599,-0.070894,0.169306,0.606513,-0.472912,-0.174825,0.091266,-0.210353,-0.283505,0.064102,-0.175630,0.389965,0.686530,0.047842,-0.193251,0.072190,0.657808,0.185232,-0.034504,-0.033651,0.288674,0.078481,0.377686,0.275783,-0.216337,-0.023855,-0.124771,-0.015280,-0.584212,-0.019998,0.273335,0.056012,-0.428483,0.927847,-0.070347,-0.128430,0.134134,-0.349049,-0.008227,0.413964,0.189437,0.469092,-0.084957,0.119828,-0.151043,0.487529,0.618897,0.227789,-0.468966,0.547994,-0.497479,-0.382779,-0.139830,-0.170536,-0.548291,0.072943,-0.015291,0.142693,-0.045706,0.142164,-0.550991,0.104498,-0.163593,0.250580,0.457500,-0.263089,-0.223538,-0.464413,-0.342011,-0.704358,-0.325574,-0.014043,0.296190,-0.357517,0.706042,-1.102829,0.086084,0.261160,0.114660,-0.213374,0.599826,0.202657,0.027649,-0.183782,-0.084802,0.154571,-0.382296,0.141477,0.134106,0.334399,-0.022507,-0.035526,-0.463548,0.225595', '1826173', '35030151', '4202326', '1306544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6900094', '后宫：帝王之妾', '剧情', '圣源（金东旭 Dong-wook Kim 饰）还是世子时，在大臣申参判家偶遇其女华妍（赵茹珍 Yeo-Jeong Jo 饰），一见倾心。但其母后为了自己的政治野心将华妍许配给了他同父异母的哥哥作王后，圣源因此远走他乡。华妍本与家中的仆人权侑（金民俊 Min-jun Kim 饰）是一对恋人，无意间得知将要入宫为妃，因而私奔却被父亲抓到，为了保全恋人性命无奈入宫。五年后殿下病重，在母后的阴谋和安排下圣源大君回宫继承了王位当了傀儡皇帝，华妍的父亲也在政变中遭遇其母后迫害被处死。此时的圣源大君遇到已成为皇嫂的华研，权利的束缚更燃烧了他心中禁忌的欲望。而保住性命的家奴权侑私奔失败后却被申参叛阉割，为了登上权力的顶峰报仇雪恨进宫当了内侍，忍辱偷生。以宫廷斗争为背景，三人命运交织，在爱欲和权力，激情与仇恨的矛盾冲突下酝酿着一场悲剧。©豆瓣', '金民俊', '金大胜', 5.7, 20313, 'tt2544120', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1643894657.jpg', 5.2, 26.6, 51.3, 12.7, 4.2, '-0.073821,0.462162,-0.626252,0.690034,0.090729,-0.392733,0.829020,0.395156,-0.617496,-0.247478,0.464418,0.779081,-0.153660,0.119724,0.264368,-0.128903,-0.105191,-0.750123,-0.090546,-0.037933,-0.146322,-0.445665,-0.041119,-0.060109,-0.345291,-0.505683,0.924736,0.064957,0.041326,0.275453,0.586985,0.259228,-0.190793,0.556611,-0.153436,0.073544,-0.198897,-0.034902,-0.493816,0.085922,0.031147,-0.571521,-0.117413,0.176169,-0.086570,0.181673,0.523278,-0.478238,0.260361,-0.644210,0.359907,-0.280386,0.101626,0.508406,0.259984,0.102379,0.172279,0.558848,-0.179657,-0.150176,0.141054,-0.107638,-0.797312,-0.115202,0.156987,-0.044199,-0.627047,0.464751,-0.147192,-0.124163,0.227976,-0.114367,0.482739,0.492316,0.048630,0.304769,-0.587665,0.131672,-0.471108,0.120008,0.911856,-0.229871,0.160400,0.115209,0.118397,-0.353670,0.095651,-0.439509,-0.404782,-0.037230,0.438518,0.231391,-0.024627,0.607680,-0.419894,-0.457135,-0.538300,0.323719,0.243448,-0.648391,0.300399,-0.002157,-0.185318,-0.246853,-0.341192,0.094434,0.412779,-0.248725,0.408387,-0.661345,0.289185,0.476575,0.356996,-0.968951,0.480935,0.199741,0.365359,-0.179042,-0.134169,0.121765,-0.056881,0.150134,0.002816,-0.046203,-0.063436,0.100110,-0.522714,0.219239', '30345227', '26678784', '26996783', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6905169', '我妻子的一切', '喜剧', '贞仁（林秀晶 饰）与道贤（李善均 饰），在日本因为一场地震结缘。经过甜蜜的热恋期很快进入婚姻，但7年之痒如约到来，贞仁变成了一个唠叨、尖刻、听不进人言的悍妇，让每天贴身附上的美食和连珠炮言语让道贤疲惫不堪。道贤申请工作调动，没想到贞仁擅自跟去，退无可退的道贤发现隔壁住着一个从未失手的花花公子张胜基（柳承龙 饰），便起意雇他来勾引妻子出轨，达到甩脱她的目的。原本计划2个月得手，张胜基逐步接近贞仁，与此同时，贞仁被丈夫安排的电台工作意外开花，竟然成了当红DJ，被邀请去首尔发展。妻子的唠叨慢慢远去，道贤却开始意识到自己的感情，那边厢雇佣情圣的工作顺利进行，张胜基竟然假戏真做，爱上了贞仁，并大胆向她表白。如今轮到道贤手足无措了，他希望得到妻子的原谅，希望不惜一切挽回她，可是贞仁似乎离婚之心已决……©豆瓣', '林秀晶', '闵奎东', 7.3, 40890, 'tt2173264', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1505007252.jpg', 0.7, 4.3, 38.9, 41.8, 14.3, '0.116858,0.276854,-0.759843,0.552240,-0.113821,-0.255538,0.556472,0.252361,-0.086285,-0.238134,0.040627,0.514041,-0.567892,0.107719,0.235349,-0.056004,0.057910,-0.709656,0.029785,-0.032365,-0.026121,-0.446994,0.211391,0.093134,-0.136458,-0.082189,0.406016,0.150160,-0.086636,0.585115,0.305708,0.175612,0.064845,0.384252,-0.043815,0.161413,-0.062034,0.016715,-0.144169,0.073472,0.095089,-0.271110,-0.115098,0.216847,-0.082464,0.347629,0.517372,-0.149124,-0.204181,-0.009201,0.559838,-0.372646,0.085791,0.322447,0.145842,0.147960,-0.072117,0.146456,-0.307900,0.185067,0.124176,0.077404,-0.742845,0.305894,-0.104068,-0.171809,-0.559900,0.130624,-0.126774,-0.030449,-0.081994,-0.429803,0.106691,0.547309,0.050978,0.393893,-0.462896,0.411638,-0.428076,0.139643,0.786445,0.171197,0.084396,0.467021,0.370996,-0.267917,0.265196,-0.250853,-0.275185,-0.103301,-0.005595,0.128642,-0.188670,-0.012986,-0.274933,-0.243078,-0.359275,0.033507,0.031225,-0.435238,0.000567,-0.367026,-0.235023,-0.074944,-0.385101,0.142622,-0.041263,-0.466573,0.459446,-0.649061,0.265029,0.452237,0.554460,-0.804588,0.411667,0.186343,-0.058426,-0.224573,0.073041,0.193319,-0.063733,0.144849,0.389432,0.040974,-0.134474,-0.170372,-0.355699,0.004231', '26678784', '1301022', '35073886', '35461732');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6946773', '一起飞', '喜剧', '“苍狼”特警队在原始森林中展开大搜捕；一支神秘队伍在森林中前行。他们的目标似乎都是“劫匪”许逸凡（林志颖 饰）和“受害人”何芊芊何芊芊（张娜拉 饰）。特种兵出身的许逸凡让阅历不丰的何芊芊第一次感受到天下竟有和自己男友萧寒（万思维 饰）截然不同的男人。凭着许逸凡特种兵的经验，他们最终克服艰难险阻，走出了原始森林，但却与“呆哥”（陈佳佳 饰）遭遇而大展拳脚，最终被“苍狼”特警队俘获。何芊芊的男友萧寒长相俊帅，学识渊博，深得何芊芊喜爱和爸爸何振雄（朱虎声 饰）的赏识，被安排在何振雄公司做副总。看着爸爸的身体愈来愈不好，何芊芊按照与爸爸签订的“合约”，还是决定与聚少离多的萧寒结婚，以了却爸爸的心思。然而，许逸凡的出现，完全打乱了这对恋人的生活。林雨馨（王子子 饰）经何芊芊的挽留，也来到了何家暂住。当晚的一场化妆PARTY，让苦苦寻找男友的林雨馨有了重大发现。第二天，林雨馨不辞而别。一宗扑朔迷离的奇案发生了，是情杀，还是劫持？伴随着案件的侦破，一段生离死别的奇缘揭开了！', '林志颖', '张蠡', 4.9, 4982, 'tt2455762', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1661843060.jpg', 25.1, 28.4, 30.7, 9.9, 5.8, '0.370664,0.044145,-0.629019,0.433534,-0.092190,-0.383039,0.736427,0.007081,-0.668281,-0.213686,0.324805,0.447480,-0.307877,0.119842,0.427239,-0.020973,0.017686,-0.697230,-0.066104,0.065688,-0.218386,-0.479824,-0.321693,0.105389,0.176694,-0.006080,0.592874,-0.065519,-0.279911,0.502558,0.385529,0.089108,-0.400411,0.452483,-0.086553,0.095825,0.137326,0.284045,-0.481668,-0.018795,0.333911,-0.454154,-0.220191,0.016106,-0.023313,0.408816,0.569576,-0.246760,-0.426390,0.238519,0.226853,-0.383373,-0.092711,0.073432,0.367168,0.087771,0.052797,0.292104,-0.200940,-0.076909,-0.154517,0.025274,-0.482306,0.077905,0.355565,0.209178,-0.440654,0.246525,-0.158078,-0.190489,0.166186,-0.486684,0.100109,0.485935,0.191643,0.248875,-0.273310,0.041825,-0.647215,0.106001,0.547690,0.062478,-0.036112,0.074734,-0.071037,-0.440806,-0.054516,-0.076669,-0.467184,-0.012899,0.224441,-0.006042,-0.284512,0.132503,-0.647854,-0.034716,-0.394841,-0.054313,-0.017130,-0.538401,-0.217659,-0.338710,-0.238813,-0.705075,-0.293070,0.104058,0.299132,-0.289499,0.733644,-0.999561,0.064230,0.216493,0.346011,-0.389450,0.385591,0.023990,0.077111,-0.049040,-0.003521,0.147000,-0.020903,0.337521,0.099629,0.437937,0.005204,-