INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6957227', '宝岛双雄', '喜剧', '举世闻名的《富甲山水图》各一半珍藏于大陆和台湾的故宫博物院，这是首次合璧在台北故宫展出。国际上的江湖大盗纷纷闻讯而至。来自大洋彼岸的国际盗宝集团派出两名美女盗贼假扮保安人员混入故宫盗走画卷。盗贼得手之际恰好撞到年轻的保安员小杰（房祖名 饰），双方发生了激烈搏斗。正当身手不凡的小杰终于占了上风要将盗贼擒拿之际，一名正在故宫参观的大陆游客“英雄救美”放走了美女大盗反而制服了小杰。当身穿便服的小杰终于让对方相信了自己是保安人员，美女才是盗贼的时候，这名游客追悔莫及。原来这名叫大海（夏雨 饰）的游客是一名来自北京的小区保安。与此同时，比误放盗贼更“乌龙”的事情发生了，小杰被保安总部认为是盗窃集团的内应，大海则发现旅行团的大巴早已消失，自己“脱团”了。小杰不仅要躲避警方的追捕而且必须要亲自找回画卷才能证明自己的清白；举目无亲的大海也“被成为”了小杰的“同谋”，他则是要找到他的旅行团才能证明自己的身份。于是，来自两岸的两名“屌丝”保安开始了在宝岛“亡命天涯”的旅程......', '房祖名', '张训玮', 4.4, 6474, 'tt2309048', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1568263160.jpg', 22.7, 41.6, 30.7, 3.5, 1.5, '0.194028,-0.113583,-0.556654,0.444138,-0.141397,-0.266323,0.476359,0.055757,-0.462052,-0.183443,0.602234,0.697793,-0.013200,0.161556,0.578505,0.047063,-0.144087,-0.786065,-0.167371,-0.333867,-0.397716,-0.058356,-0.443925,-0.092144,-0.058581,-0.154171,0.593032,0.100980,-0.301727,0.321252,0.367415,0.324126,-0.262473,0.419425,-0.402995,-0.146510,0.355315,-0.105162,-0.242881,0.279012,-0.240826,-0.412466,-0.057507,0.119399,-0.084827,0.267545,0.675642,0.003721,-0.057145,0.001820,0.269427,-0.378531,0.043064,-0.048141,0.606181,-0.065756,0.108550,0.041158,-0.163036,-0.006504,0.155121,-0.051797,-0.627097,0.223910,0.366791,0.085942,-0.560538,0.287526,-0.106626,-0.091490,0.167618,-0.181443,0.344647,0.375515,0.121719,0.207059,0.173667,-0.096632,-0.740943,0.323354,0.613200,0.092666,0.046378,0.021323,0.048274,-0.468640,-0.041507,-0.193460,-0.072759,0.017294,0.553938,-0.144366,-0.184142,0.047445,-0.600948,-0.132113,-0.353998,-0.236215,-0.175586,-0.232582,-0.217911,-0.764516,-0.014372,-0.285649,0.114688,0.207951,0.161918,0.207946,0.697085,-0.806315,-0.123966,0.795018,0.230175,-0.525173,0.668637,-0.054321,-0.019267,-0.132152,-0.246597,-0.223732,0.249065,0.644386,0.040484,0.337934,-0.