INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6957273', '大武当之天地密码', '喜剧', '民国初期，相传武当山有稀世宝藏，百年轮回一次的武林盛会即将开战，各路高手齐聚道教圣地武当山争当“天下第一”，神秘女子（杨幂 饰）使绝招抢夺大会战贴加入战局，表面上以武会友，背里却为一桩家族使命，而考古教授（赵文卓 饰）带着自幼习武的女儿，为传说中的镇山之宝混入武当；一名至孝的俗家弟子（樊少皇 饰)偶然成为了武当代表，与各地武术家争夺冠军,却不知陷入自张三丰创派后武当最大的危机中……©豆瓣', '赵文卓', '梁柏坚', 3.9, 30091, 'tt2251662', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1584362585.jpg', 40.4, 34.7, 17.7, 3.1, 4, '-0.163281,0.170714,-0.414219,0.836914,0.342308,0.112827,-0.070615,0.007069,-0.855348,-0.428824,0.342636,1.018726,-0.005345,0.101075,0.033286,-0.132117,0.450431,-0.726343,-0.043271,-0.513858,-0.043865,0.278134,-0.389543,0.320394,-0.349243,-0.404141,0.814989,0.586272,-0.580523,0.495161,0.374731,0.349557,-0.214588,-0.042546,-0.363706,-0.475334,0.137920,0.411286,-0.394651,0.222101,-0.618693,-0.370019,-0.291638,0.021640,-0.337420,0.272209,0.210985,-0.370759,0.309099,-0.447308,-0.007205,-0.075999,-0.405845,-0.109959,0.659026,0.308285,0.412035,0.612234,0.171742,-0.062066,-0.021413,-0.304725,-0.569009,-0.015369,0.693949,0.128688,-0.329271,0.502801,-0.046729,-0.171887,-0.278912,-0.032437,0.174635,0.574667,0.442855,-0.139746,0.048919,-0.145748,-0.456082,0.451329,0.583897,-0.385073,0.349174,-0.129083,0.231318,-0.403216,0.385509,-0.956998,-0.057278,0.076218,0.073783,-0.292643,0.487233,0.547729,-0.272400,0.003121,-0.163394,0.044687,0.066192,0.053567,0.106256,-0.672361,-0.094180,0.048235,-0.094184,-0.333497,0.321503,-0.097344,1.137021,-0.719633,0.278234,-0.013638,-0.160854,-0.535528,0.858377,0.036365,0.373205,-0.505440,-0.609512,0.292911,0.035945,0.439791,-0.348528,0.180020,-0.161915,-0.128464,-0.115486,0.207222', '27602116', '26266892', '35262731', '30465281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6957293', '完美音调', '喜剧', '巴顿大学新人贝卡（安娜·肯德里克 Anna Kendrick 饰），意外加入学校的阿卡贝拉女子美声合唱团，该社团集结了又乖又坏又怪的各样女性成员，唯一共通点就是能清唱出犹如天籁的美声。社团成员包括：自认歌声最好，自信过人的“胖艾美”（蕾蓓尔·威尔森 Rebel Wilson 饰）、常常出言不逊又固执墨守成规，但其实焦虑不已的欧柏莉（安娜·坎普 Anna Camp 饰）、团员精神支柱克萝伊（布兰特妮·斯诺 Brittany Snow 饰）、性事无度的撩人歌姬史黛西（亚历克西斯·克纳普 Alexis Knapp 饰）、歌声动人的男人婆辛西亚萝丝（伊斯特·迪恩 Ester Dean 饰）、声音小如蚊子但即兴饶舌却令大家惊艳不已的哈娜梅李。与校园格格不入的贝卡，如何以她惊人的才华改变阿卡贝拉的传统表演方式？又如何率领这群女生与竞争激烈的全国美声团体一较高下？', '安娜·肯德里克', '杰森·摩尔', 7.5, 34746, 'tt1981677', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1737739080.jpg', 0.6, 3.9, 33.6, 44.5, 17.4, '0.293265,0.121099,-0.313332,0.643322,0.006292,-0.320562,0.591576,0.154896,-0.529816,-0.016732,0.168642,0.375957,-0.141945,-0.005192,0.314056,0.088595,-0.505484,-0.618570,0.161791,-0.121652,0.247497,-0.394633,0.081717,-0.357536,0.099518,-0.387370,0.366624,-0.131694,-0.231738,0.523001,0.391251,0.286977,0.179366,0.016220,0.243382,-0.123352,0.365673,-0.017724,0.009655,-0.176553,-0.051093,0.143547,-0.486664,0.087644,0.135138,0.173152,0.471050,-0.163136,0.300962,0.036676,0.492796,0.088531,0.249365,0.011883,0.008379,-0.350093,0.362379,-0.043233,0.260799,-0.028018,0.010093,-0.004942,-0.475710,0.379768,0.240068,0.152145,-0.237458,0.258510,-0.297275,-0.162170,0.388644,0.087323,-0.260393,0.147972,0.463635,0.426782,0.048013,0.087644,-0.220104,0.088648,0.392520,0.410932,-0.499650,-0.120881,-0.580376,-0.725238,-0.127220,-0.339579,-0.513953,-0.090159,0.217214,-0.220225,0.340634,0.501056,-0.595489,-0.257101,-0.111520,-0.017945,-0.200561,-0.438595,0.038963,-0.814734,0.036911,-0.248446,-0.284956,-0.124413,0.255333,0.050438,0.920679,-0.968423,0.031963,0.461456,0.043927,-0.020857,0.267928,-0.026113,0.017373,-0.183918,-0.501529,0.396591,-0.025309,-0.240335,0.062584,0.669765,0.093746,-0.227060,-0.301146,0.292207', '25922902', '3811356', 