INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6959152', '诺亚方舟：创世之旅', '动作', '《诺亚方舟》根据圣经故事改编，由达伦·阿伦诺夫斯基亲自创作剧本和同名漫画。这是一个没有希望的世界，没有雨、没有粮食，军阀和野蛮的游牧部落统治一切。诺亚是这个残酷世界的一个好人，一个久经沙场的战士、法师和治疗师，他只想和家人过上安宁平静的生活。然而，每天晚上他都会被一个噩梦所折磨，梦里整个世界被一场大洪水吞没。久而久之他意识到，这正是造物主给他的讯号，上帝要惩罚人类，把他们杀光……但他给了诺亚一个机会，让他得以保存地球上的物种。', '罗素·克劳', '达伦·阿伦诺夫斯基', 5.9, 26119, 'tt1959490', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2169342617.jpg', 4.6, 22.3, 52.6, 15.7, 4.7, '0.301343,0.244116,-0.740188,0.965236,-0.371870,-0.095778,1.024013,-0.286956,-0.507664,-0.246200,-0.115471,1.179097,-0.043884,0.088920,0.068870,0.227966,-0.341201,-0.807923,-0.245646,-0.051745,-0.514706,-0.428563,-0.335841,-0.367778,-0.112368,-0.315809,0.737054,0.002700,-0.109739,0.058884,0.013020,0.154131,0.233183,0.558538,-0.416571,0.172342,0.078148,-0.128347,-0.163157,0.406187,-0.139586,-0.044812,-0.128543,0.778805,-0.457218,0.135579,0.570700,-0.627944,-0.122899,-0.252529,0.308756,-0.605294,-0.092881,0.057396,0.221127,-0.313564,0.157157,0.122450,0.175251,-0.141550,0.015642,-0.155535,-1.259803,-0.357915,0.016520,0.178634,-0.714218,0.568806,-0.108364,0.077488,-0.248070,-0.207970,0.482588,0.293887,0.662304,0.584989,-0.189149,-0.197382,-0.580951,0.373615,0.822078,-0.172246,-0.562730,0.610495,-0.568529,-0.433956,-0.182811,-0.378929,-0.811560,0.195028,0.234667,-0.162050,-0.498659,0.325435,-0.842327,0.074320,-0.392236,-0.528224,-0.144427,-0.499078,-0.148867,-0.116769,-0.281833,-0.235517,-0.340941,0.195298,0.241501,-0.220628,1.042133,-0.712786,0.318284,0.931762,0.260346,-0.483716,0.863807,0.274153,-0.036964,-0.133331,0.541697,-0.027453,0.146207,0.422588,0.280758,0.422268,0.261385,0.117053,-0.421345,0.816664', '30163500', '25928048', '34890458', '30368448');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6960858', '蜡笔小新：风起云涌！我的宇宙公主', '动画', '因为一块布丁，野原新之助（矢岛晶子 配音）和妹妹向日葵（こおろぎさとみ 配音）激烈争吵，身为哥哥他自然受到爸爸广志（藤原啓治 配音）和妈妈美伢（ならはしみき 配音）的训斥。小新恼羞成怒，扬言“不要当哥哥！不要妹妹了！”就在此刻，一胖一瘦两个绿衣人出现，声称愿意将小葵收养，以向日葵公主的身份展开新的生活。一道刺眼强光过后，签订了协议的野原一家被吸入UFO，开始了吉凶未卜的宇宙旅行。从向日葵星国王口中得知，当前这颗星球和地球正面临前所未有的危机，一旦二者间的平衡受到破坏，两颗星球都将迎来毁灭的厄运。而向日葵，正是防止危机的关键……©豆瓣', '矢岛晶子', '增井壮一', 7.8, 9249, 'tt2368717', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1465395488.jpg', 0.6, 3.5, 29.2, 38.2, 28.5, '0.039138,0.179518,-0.558159,0.446055,-0.000442,-0.172565,0.489845,0.426022,0.020198,0.081344,0.257224,0.540066,-0.251775,0.325937,0.296787,0.094246,0.091990,-0.448407,0.003174,-0.015232,-0.193521,-0.313903,-0.094827,-0.053070,-0.054174,-0.523059,0.809058,0.015979,-0.220440,0.326983,0.097518,0.252010,-0.350368,0.411702,0.172683,-0.127546,0.117386,0.172911,-0.579973,0.182325,-0.056964,-0.079663,0.350036,0.205262,0.064966,0.100035,0.621965,-0.465623,-0.096165,-0.415905,0.452290,-0.210329,-0.083519,0.173305,0.423568,-0.007446,0.171234,-0.118594,-0.356984,0.002715,0.109037,-0.289315,-0.487854,0.121458,0.169837,0.048496,-0.258370,0.155107,-0.021205,-0.240581,0.411303,-0.287522,0.450471,0.481194,0.420198,0.457745,-0.577738,0.342486,-0.167301,-0.056783,0.648554,-0.203404,-0.032756,0.179386,0.005364,-0.158213,0.084611,-0.027954,-0.338157,0.112776,0.350532,0.003180,-0.247898,0.346060,-0.555211,-0.036820,-0.287683,-0.378500,0.455551,-0.464244,-0.264484,-0.237585,-0.036790,-0.125489,-0.052972,0.375537,0.096507,-0.053869,0.924214,-0.750456,0.271809,0.440733,0.347388,-0.330288,0.228676,0.279512,0.081425,-0.516107,0.067547,0.059847,0.190460,0.352487,-0.041196,0.075261,0.251728,0.189424,-0.254897,0.171006', '10174444', '25922902', '1826173', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6963575', '青春失乐园', '剧情', '曾经的问题少女程小雨在高中同学王小菲的改变下顺利考入大学，并结识了莫熙儿、王紫潼、田晓天、宋丹四位好友。五个风格炯异的女生凭借出众的外表，独特的个性，炫丽的舞姿，受到众多校友和男生追捧的对象，风靡整个大学校园。而与此同时，一直暗恋程小雨的王小菲以转校生的身份，再次来到程小雨所在的大学，继续寻找自己的爱情。不想结识了一帮可爱又可恨的损友，并且在一次意外中遇到了调入同一所大学的高中体育老师秦祥林和倾国倾校的美女老师夏天。 　　七个大学男女和两个大学老师在纠结中展开了一场爱与被爱的追逐。 　　最新消息《青春失乐园》将于2011年11月11日。各大网站同时上线。喜欢《青春期》的朋友们可以继续收看青春失乐园。欢迎收看~人物介绍程小雨　赵奕欢饰天性善良，个性独特，行事独断， 是众多90后宅男心目中的女神，也是女生们羡慕嫉妒恨的对象。 　　作为新生中的焦点人物一直众多校友和男生追捧的对象， 　　风靡整个大学校园，但同时遭受到来自各方面的排挤和非议。希儿　莫熙儿饰一个具有音乐天赋， 　　一直梦想成为歌手的漂亮女生， 　　程小雨的好友之一，平时少言寡语，拥有韩星情结， 　　甘愿为所爱的人欺骗和折磨，期望自己的付出有一天能换来真爱。紫潼　王紫潼饰一个具有喜剧范的高挑美女， 　　事事争先，但却屡次闹出笑话， 　　也是程小雨好友中最喜欢和她争风吃醋的一个。 　　性格直率，总被男生笑话。晓天　田晓天饰程小雨好友之一， 　　一个具有舞蹈天赋的性感女生， 　　爱美男，爱名牌、爱臭美，爱表现， 　　平时话语连珠，现实版的“小燕子”丹丹　宋丹饰程小雨好友之一，拥用一张韩星的美女脸， 　　也爱好舞蹈和音乐，但没有', '赵奕欢', '管晓杰', 3.9, 20879, 'tt6964284', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1290620189.jpg', 40.5, 31.9, 20.4, 4.1, 3, '0.321504,-0.149352,-0.468852,0.708569,-0.327136,-0.121304,0.600996,0.013800,-0.583960,-0.211402,-0.057484,0.625573,-0.254528,0.520964,0.443421,-0.134691,0.104280,-0.606278,-0.105436,-0.087973,-0.032713,-0.275246,-0.008232,-0.030329,-0.240696,-0.400365,0.699163,-0.037683,-0.342978,0.669983,0.580902,0.110295,-0.072365,0.204460,-0.201346,-0.237265,0.204966,0.216052,-0.149535,0.245886,-0.198964,-0.068897,-0.106746,0.127775,-0.093746,-0.002007,0.750655,0.017238,-0.161632,-0.097514,0.591625,-0.260122,-0.105681,0.095010,0.332577,-0.047528,0.641103,-0.133974,0.221649,0.063405,0.006909,-0.292807,-0.535485,-0.170628,0.368546,-0.119117,-0.244934,0.589700,0.033684,-0.381705,0.215890,-0.065266,0.072811,-0.115286,0.219581,0.566070,-0.085423,0.188041,-0.067076,0.326481,0.809443,0.335329,-0.349935,0.304449,-0.430309,-0.450096,-0.086877,-0.422978,-0.775698,0.246198,0.108638,-0.041803,0.074482,0.262255,-0.567347,0.348845,0.227