INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6965615', '两个婚礼一个葬礼', '喜剧', '产科女医生孝珍（柳贤静 饰）梦想跟女朋友一起领养婴儿，而英俊的大夫民秀（郑爱延 饰）和男朋友亦希望拥有自己的生活。由于同属一家医院又各有憧憬，一拍即合的四人决定办理假结婚，更把住所搬到相连。然而这种既享受异性婚姻福利，又与同性爱人甜蜜的双重生活，注定不能长久——民秀父母的意外到访让原本天衣无缝的大计遇到撞板考验，究竟他们能否瞒「基」过海？一对男男和一对女女，为隐瞒同志身份约好假结婚，结果被无心构筑的四人世界搞得焦头烂额。本片是韩国新锐同志导演金赵光秀的首部长片作品，讲述男男女女浪漫跨界的爱情喜剧，入围2012年釜山国际电影节。©豆瓣', '金东允', '金赵光寿', 6.5, 8687, 'tt2570292', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1562724727.jpg', 2.2, 12.5, 52.4, 25.7, 7.2, '0.063261,-0.488887,-0.245884,0.323180,0.118707,-0.133822,0.240982,0.309224,-0.385514,-0.210204,0.079726,0.438381,-0.331226,0.149041,0.596056,-0.150032,-0.227289,-0.474536,0.191162,-0.008610,0.051076,-0.341814,-0.119195,-0.011285,-0.042866,-0.257593,0.694205,-0.148167,0.113997,0.397165,0.360330,0.156004,-0.405872,0.003088,0.058754,-0.212258,0.149490,0.412465,-0.759225,0.175362,-0.047460,0.087343,-0.014002,0.064736,0.122720,0.128219,0.594526,0.082721,-0.191554,-0.054129,0.382244,-0.133537,-0.136937,0.010968,0.148814,0.130542,0.369887,0.409685,-0.060244,-0.181367,0.243761,-0.144692,-0.625674,0.259053,0.391407,-0.055294,-0.199930,0.349954,0.080314,-0.132688,0.049016,-0.089300,0.251257,0.517681,0.471707,0.433646,0.002769,0.247405,-0.309964,0.430544,0.777179,0.120537,-0.003582,0.261621,-0.263232,-0.351343,0.017723,-0.226704,-0.581346,0.177787,-0.148479,-0.010054,-0.071810,0.020911,-0.445131,-0.074972,-0.131967,0.253637,0.179271,-0.581634,0.304867,-0.612711,-0.094757,-0.159071,-0.067622,0.061344,0.344837,-0.209247,0.641879,-0.550864,-0.071761,0.170915,0.471625,-0.693432,0.949013,0.486218,0.081786,-0.637232,-0.161982,0.006394,-0.121785,-0.136682,-0.112894,0.076477,-0.107309,-0.045486,-0.316883,-0.066934', '26646649', '25881781', '4301278', '30159567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6971017', '亲家过年', '喜剧', '雪伦（文章 饰）和丹丹（刘芸 饰）是一对儿80后的小夫妻，雪伦婚后为创业急需资金，丹丹将母亲为他们在北京购买的婚房出售，资助雪伦，夫妻俩租住了四合院中的小平房暂时栖身。春节将至，雪伦远在黑龙江的父亲（张丰毅 饰）母亲（丛珊 饰）决意来北京和儿子一起过年，而丹丹在云南的母亲（蔡明 饰）一家恰巧也决定赴京度春节。因为丹丹当初瞒着母亲将房子出售，此时只好向现在的房主借住数日，以期向母亲隐瞒自己赞助雪伦的事实。双方的家长先后抵京，小夫妻总算瞒天过海隐藏了真相，然而这几位家长此次来京并非只为儿女，他们各有私事需要处理，在这个热闹的年关引发了诸多喜剧……©豆瓣', '文章', '叶伟民', 5.6, 19912, 'tt2457980', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1368072320.jpg', 6.9, 24.8, 52.1, 12.9, 3.3, '0.331535,-0.088191,-0.571547,0.265138,-0.081421,-0.326431,0.433014,0.363746,-0.624011,-0.341960,0.293493,0.634350,-0.077400,0.305456,0.068305,0.072656,-0.320931,-0.346298,0.079688,-0.256269,-0.023173,-0.462925,0.106136,-0.021504,-0.123916,0.138903,0.420619,0.028404,0.210072,0.435441,0.233935,0.077930,-0.241568,0.091272,-0.095926,0.086083,-0.205355,0.196143,-0.570808,0.142500,0.028183,-0.162153,-0.218467,-0.025117,0.494373,0.514842,0.792962,-0.025833,-0.182718,-0.008484,0.194266,-0.003050,0.168677,0.358267,0.112285,0.174376,0.503889,0.446759,-0.567326,-0.018409,0.038872,-0.170916,-0.435935,0.225669,0.314199,-0.125915,-0.667591,0.497803,-0.206534,-0.268507,0.150101,-0.628756,0.232383,0.963710,-0.274468,0.472708,-0.376665,0.077171,-0.533065,0.377667,0.665939,-0.115905,0.458323,0.184857,-0.051944,-0.200287,0.093513,-0.071198,-0.539156,-0.018582,0.142403,0.060128,-0.156296,0.149510,-0.505758,-0.221057,-0.146692,-0.139442,0.390935,-0.391306,-0.043554,-0.508968,0.136405,-0.338152,-0.254387,-0.099073,0.395651,-0.058509,0.655872,-0.687563,0.011143,0.371793,0.608682,-0.533101,0.709985,-0.020739,0.556302,-0.278036,0.091981,-0.365085,-0.092747,0.393182,0.216298,0.265822,0.213252,-0.122926,-0.487958,0.298524', '26936217', '27060077', '1292864', '6890343');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6972849', '死亡飞车3：地狱烈焰', '动作', '故事发生在广袤的南非卡拉哈里沙漠，卡尔（鲁克·高斯 Luke Goss 饰）是一名赛车手，他正在监狱之中，等待着他人生中最重要的一场比赛。这场比赛有可能夺走他的生命，亦有可能令他得到久违的自由，一切都掌握在卡尔和他的对手手中。糟糕的是，这场死亡之赛的主办方，似乎并不想让卡尔获得最终的胜利。明里暗里，主办方一直想方设法想要夺走卡尔的性命，然而，凭借着超人的智慧和强大的勇气，再加上美丽善良的汽车领航员卡特里娜（塔尼特·菲尼克斯 Tanit Phoenix 饰）的暗中帮助，卡尔一次又一次急刹车停在死亡线前面。其实他还有另一个计划，一个会让邪恶的主办方彻底灭亡的计划。©豆瓣', '鲁克·高斯', '罗伊·雷内', 6, 11572, 'tt1988591', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1836717741.jpg', 4.3, 20.4, 52.3, 16.5, 6.4, '-0.030441,0.395216,-0.877465,0.863923,-0.080941,-0.158377,0.865780,-0.250126,-0.396551,0.013037,0.452320,0.791126,0.140725,0.020812,0.353544,-0.083629,-0.260417,-0.758533,-0.090469,0.103520,-0.388869,-0.523640,-0.514689,-0.108680,0.024264,-0.382208,0.805192,0.254677,-0.146707,0.332657,0.449948,0.279719,0.119770,0.498700,-0.047392,-0.232538,0.146220,0.024085,-0.391654,0.357072,0.148582,-0.015437,-0.328832,0.565698,0.046886,0.245653,0.500893,-0.428082,-0.100199,-0.019355,0.488640,-0.536766,0.016047,0.039324,0.235316,-0.137637,0.044105,0.294861,-0.021907,0.088846,0.152779,0.068901,-1.107932,-0.144190,-0.039197,0.141268,-0.490603,0.457016,0.034897,0.014594,0.254586,-0.194819,0.191908,0.337205,0.528425,0.080797,-0.224072,-0.138969,-0.457983,0.003224,0.845737,-0.197111,-0.355098,0.336451,-0.159245,-0.467388,-0.076496,-0.405849,-0.513983,0.106118,0.626327,0.154253,-0.062123,0.283837,-0.452609,0.179119,-0.286889,-0.469718,-0.024388,-0.482804,-0.044716,-0.369463,-0.042640,-0.304637,-0.232236,0.199485,-0.028054,-0.448605,0.664890,-0.724090,0.335953,0.802474,0.126786,-0.240975,0.345755,0.319409,0.201268,-0.228704,-0.207661,0.309607,-0.097782,0.214557,-0.150434,0.144440,0.195576,-0.131627,-0.370648,0.802995', '25828589', '4820775', '30163500', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6972876', '纽约客@上海', '剧情', '上海：21世纪全球贸易中心。每天都有更多的外籍商人来到上海，渴望了解到中国做生意的方式。这些外国人中有我们的同事，老板，邻居，客户……当雄心勃勃的纽约律师山姆（丹尼尔·海尼 Daniel Henney  饰）被意外的派到上海时，他立即陷入了法律泥潭，使他差点丢了工作。但随着一位聪明性感的助理（朱珠 饰），一个机灵的上海记者（耿乐 饰），一位漂亮的迁居专家（伊丽莎·库伯 Eliza Coupe 饰），以及一个人脉广泛的老前辈（比尔·帕克斯顿 Bill Paxton 饰）的帮助，山姆可能有机会保住工作，寻找到爱情，并且学着去欣赏他美好的故乡……©豆瓣', '丹尼尔·海尼', '夏伟', 6.3, 6736, 'tt2070597', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1616878628.jpg', 2.6, 14, 52.7, 24.8, 5.9, '0.262690,0.021960,-0.483504,0.492206,-0.266973,-0.431069,0.299405,0.110537,-0.373886,-0.116216,0.130646,0.750229,0.116034,0.231344,0.347427,0.185952,-0.321470,-0.449365,0.136847,-0.061531,-0.154230,-0.363935,-0.354317,-0.449288,-0.118459,-0.149026,0.184321,0.082184,-0.007946,0.385024,-0.008008,0.316688,-0.019977,0.380949,-0.175958,0.037601,0.504793,-0.127074,-0.443088,0.232995,-0.001710,0.025901,-0.019639,0.109590,0.157887,0.357686,0.376271,0.080810,-0.185534,0.177523,0.580622,-0.012815,-0.052859,0.033804,0.387092,0.100706,0.159751,-0.006527,-0.260963,0.045906,0.090370,-0.131896,-0.517001,0.012631,0.298754,0.181665,-0.581799,0.265920,0.008464,-0.102049,-0.047783,-0.403634,0.152857,0.288500,0.057430,0.157762,0.254908,0.328392,-0.207242,0.463691,0.620843,-0.002755,-0.235710,0.188214,-0.206970,-0.408831,0.174487,-0.148897,-0.304560,-0.019498,0.444748,-0.395704,-0.065747,-0.033958,-0.645776,-0.037702,-0.185039,-0.187413,0.028242,-0.173047,-0.026414,-0.652793,0.098905,-0.399672,-0.013781,0.104044,0.321282,0.015638,0.882830,-0.605843,0.003156,0.866226,0.236513,-0.559895,0.737242,-0.251749,0.031825,-0.339163,-0.335918,0.318742,0.108400,0.255996,-0.118376,0.351876,-0.135638,-0.405121,-0.118972,0.103247', '27602116', '30162520', '3811356', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6973370', '再也不诱拐了', '剧情', '出身山口县的27岁青年樽井翔太郎（大野智 饰）自幼立志成为超级英雄。可是现实世界分外残酷，靠当特摄演员的翔太郎被老板开除，万般无奈投奔大学的学长甲本一树（佐藤隆太 饰），靠贩卖烤红薯赚取营生。某天，他无意中救助了一名被黑社会追赶的女子，谁知对方竟然是当地小黑帮花园一家老大周五郎（北大路欣也 饰）的次女绘里香（新垣結衣 饰）。绘里香的心中藏着难以为人倾诉的心事，她请求翔太郎及甲本帮她策划一场绑架案，以从父亲那里骗取赎金。与此同时，花园家的长女昴月（貫地谷しほり 饰）正在调查小镇上突现的假钞事件。两起事件就这样奇妙的纠缠到了一起……本片根据东川笃哉的同名推理小说改编。©豆瓣', '大野智', '佐藤祐市', 6.9, 6429, 'tt2113015', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1590330835.jpg', 1, 7.2, 49.4, 31.6, 10.8, '0.167731,0.001462,-0.311035,0.372325,0.063527,-0.164258,0.161504,0.428468,-0.329864,-0.286213,0.307738,0.542589,-0.017528,0.299195,0.384950,0.225036,-0.122644,-0.669017,-0.101734,-0.226042,0.024570,-0.319768,-0.035894,-0.113208,-0.246230,-0.018193,0.708020,0.067788,-0.088919,0.409301,0.241037,0.543658,-0.213891,-0.005006,-0.175081,0.119609,0.206196,0.134268,-0.162468,0.126565,-0.358196,-0.395206,-0.201840,-0.082333,0.206351,0.242594,0.697966,-0.229411,-0.090800,-0.113241,0.330061,-0.245125,-0.246225,-0.018467,0.536590,-0.001851,0.271368,0.269884,-0.213627,-0.321731,0.230421,-0.111875,-0.419587,-0.045901,0.224653,0.049000,-0.366352,0.214936,-0.113148,0.036579,0.216041,-0.027757,-0.057272,0.147277,0.238095,0.238014,-0.210418,0.179050,-0.215688,0.403225,0.508579,0.029382,0.147050,0.137824,-0.013772,-0.269274,-0.095286,-0.243222,-0.210558,0.010292,0.196899,-0.230154,-0.102711,0.043410,-0.467588,-0.047158,-0.247695,0.179822,0.364935,-0.042339,-0.288741,-0.556841,-0.017268,-0.152547,-0.128229,0.122279,0.435693,-0.115809,0.616205,-0.579380,-0.092932,0.589216,0.120820,-0.029143,0.472936,-0.143663,-0.324973,-0.283576,-0.310134,-0.100012,-0.014437,0.181322,0.072742,0.435195,-0.097088,-0.204066,-0.234296,0.085365', '3811356', '5403927', '3266509', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6973376', '致我们终将逝去的青春', '剧情', '18岁的郑微（杨子姗 饰）终于如愿考上青梅竹马邻家大哥哥林静（韩庚 饰）所在学校的邻校，等她满怀期冀地步入大学校园，却遭遇打击——林静出国留学，杳无音信。郑微倍感失落，患难时刻与室友阮莞（江疏影 饰）、朱小北（刘雅瑟 饰）、黎维娟（张瑶 饰）及师哥老张-张开（包贝尔 饰）结 下深厚友谊，同时富家公子许开阳（郑恺 饰）对郑微展开了疯狂的追求，而备受男生欢迎的阮莞用她特有的清冷守护着对于心爱人赵世永（黄明 饰）的忠贞。一次偶然的误会使郑微与老张室友陈孝正（赵又廷 饰）结为死敌，在一次次地反击中，郑微发现自己爱上了这个表面冷酷、内心善良的高材生，于是疯狂地反击演变为死缠烂打地追求，而陈孝正也终于在强攻之下缴械投降，欢喜冤家终成甜蜜恋人。大四毕业之际郑微的生活再次经受考验：陈孝正得到曾毓（王嘉佳 饰）的出国留学名额，却迟迟不敢告诉郑微，感觉再次被欺骗的郑微痛苦地离开陈孝正……多年后，郑微已蜕变为职场上的白领丽人，竟再次品尝命运的无常：带着悔意和爱意的林静和陈孝正同时回到她的生活里！郑微，这个昔日的玉面小飞龙，将怎样面对生活和青春赐予她的迷雾和抉择……本片改编自辛夷坞同名畅销小说。赵薇的首部导演作品，也是其在北京电影学院导演系研究生专业的毕业作品。', '杨子姗', '赵薇 Wei Zhao', 6.5, 478635, 'tt2765340', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1935067049.jpg', 3.7, 12.5, 46.3, 28, 9.4, '0.120025,0.052402,-0.544241,0.672366,-0.066801,-0.473653,0.804962,0.124852,-0.231828,-0.111486,0.145971,0.614751,-0.332860,0.556767,0.204028,-0.124470,-0.029390,-0.713280,-0.139745,-0.097376,0.047733,-0.166217,-0.255397,0.284543,-0.031689,0.017457,0.983820,0.198722,-0.174440,0.711673,0.421405,0.374358,-0.059371,0.477895,0.021048,0.059443,-0.119759,0.349257,-0.369436,0.090817,0.175106,-0.144749,-0.225671,0.120499,-0.115300,0.076161,0.748271,-0.123941,-0.039952,-0.150458,0.456935,-0.231568,-0.078471,0.264697,0.027605,0.247327,0.346595,0.078697,-0.126644,0.133215,0.142616,-0.129271,-0.293230,0.052360,0.219070,-0.013655,-0.544503,0.361794,-0.256863,-0.042783,0.279967,-0.263311,-0.023665,0.302583,0.416715,0.450818,-0.263693,0.390334,-0.038476,0.181967,0.491845,0.007971,-0.133699,0.253982,-0.179217,-0.428582,0.081742,0.004756,-0.647222,-0.125148,0.119592,0.231387,-0.019079,0.182666,-0.430724,-0.116696,-0.173063,0.222620,-0.049523,-0.496501,-0.010783,-0.529993,-0.123650,-0.533672,-0.325229,0.037546,0.101312,-0.207947,0.704706,-0.842754,0.164042,0.162957,0.337818,-0.288047,0.436559,0.317431,-0.011923,-0.185941,-0.067569,0.673529,-0.365033,0.208536,-0.028183,0.358362,-0.132118,0.080234,-0.303588,0.467499', '1296992', '3811356', '6041817', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6973460', '冰封：重生之门', '喜剧', '明朝嘉靖末年，锦衣卫贺英（甄子丹 饰）奉命从天竺运回无价之宝“时空金球”，他一心为朝廷却不想遭到了兄弟的突袭。老大元龙（任达华 饰）带着聂虎（喻亢 饰）、萨獒（王宝强 饰）前来捉拿，为的是一宗针对贺英的冤案。兄弟四人搏斗之时突然地动山摇，巨大的雪崩淹没了他们。可是醒来后，贺英发现自己居然已经到了400年后的香港，对现代社会一窍不通的他偶遇了夜店咖小美（黄圣依 饰），闹出了不少笑话，但在小美的帮助下贺英学会了使用高科技产品，逐渐变成了都市型男。正在二人感情升华的时候，“锦衣卫三人组”也穿越到了现代并且继续执行自己的使命，与此同时不明真相的警方也在捉拿贺英这个“特异功能”人士，贺英遭遇到了400年来最大的挑战。本片改编翻拍自1989年元彪、张曼玉、元华主演，霍耀良导演的影片《急冻奇侠》。是王宝强第一次演出武侠功夫片。©豆瓣', '甄子丹', '罗永昌', 4, 45007, 'tt2557256', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2178288349.jpg', 39, 33.8, 19.6, 4.3, 3.3, '0.174256,-0.097516,-0.774305,0.505081,0.147738,-0.215658,0.597477,0.194474,-0.481247,-0.221969,0.496285,0.631344,-0.263924,-0.116850,0.222453,-0.032687,-0.249806,-0.576884,-0.160146,-0.212983,-0.246878,-0.119401,-0.333495,-0.041252,-0.209748,-0.313537,0.512169,0.054586,-0.266347,0.422371,0.363575,0.041723,-0.125456,0.507306,-0.154892,0.359004,0.199012,0.118891,-0.295890,0.216573,-0.021312,-0.549353,-0.348652,0.126683,-0.286242,0.293138,0.588874,-0.342535,-0.077059,-0.018748,0.361207,-0.388350,-0.204172,-0.033493,0.268768,0.174377,0.307404,0.059685,-0.031532,0.139446,-0.028684,-0.045330,-0.429047,0.114667,0.136357,0.015537,-0.364783,0.406245,-0.085646,-0.049142,-0.033942,-0.445981,0.241778,0.228797,0.240168,0.297588,-0.213033,-0.093495,-0.517813,0.553909,0.542993,-0.037803,-0.148566,0.386728,0.057804,-0.490644,-0.089710,-0.195324,-0.297335,0.030560,0.501145,-0.143287,-0.211860,0.260617,-0.613305,-0.083487,-0.158493,-0.059104,-0.095552,0.002706,0.026862,-0.568059,-0.318581,-0.369492,-0.054421,0.094878,0.222891,-0.101363,0.709054,-0.727556,0.098471,0.474789,0.048078,-0.512590,0.454487,-0.066488,-0.061402,-0.081012,-0.179588,-0.194421,0.007096,0.608968,0.231007,0.419068,0.015912,-0.426276,-0.323543,0.293830', '1301022', '3811356', '3158990', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6974439', '向日葵与幼犬的7天', '剧情', '供职于五十岚流浪犬收容所的神崎彰司（堺雅人 饰）是一名真心喜爱动物的善良男子，此前他在动物园供职期间与妻子千夏（檀丽 饰）结合，生下一双可爱的儿女。妻子去世后，彰司转职收容所，虽然尽可能地帮更多狗狗找到新的主人，但仍无奈地一次次按下按钮，终结狗狗的生命。此时此刻， 他心中的悲伤可想而知。某天，彰司和同事遭遇了一只带着幼犬的母狗。母狗凶猛异常，为了保护孩子不惜一切。虽然遭到来自主管的压力，可是彰司无论如何不愿伤害狗狗母子。他想方设法延长收容期，四处奔走联系新的主人，在这一过程中也渐渐与母犬建立了信任。只是，最后一刻终将到来……本片根据发生在宫崎县的真实事件改编。©豆瓣', '堺雅人', '平松惠美子', 7.7, 10235, 'tt2114398', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2152428223.jpg', 0.4, 2.8, 30.3, 45.7, 20.8, '-0.076859,-0.022444,-0.585184,0.423461,0.128591,-0.011291,0.784802,0.035431,-0.465527,-0.137892,0.238159,0.643896,-0.049494,0.386422,0.168561,-0.219985,-0.088547,-0.283447,-0.100139,0.014437,-0.080171,-0.323408,-0.235207,-0.124480,0.022091,-0.401755,0.882277,0.082530,0.025591,0.479315,0.180848,0.327152,-0.291302,0.380356,-0.145335,-0.062547,-0.024265,0.072314,-0.002072,0.085112,0.062166,-0.160776,0.017066,0.129002,-0.017522,0.231849,0.830076,-0.618056,-0.370905,-0.361726,0.397960,-0.193934,-0.049050,0.145873,0.336603,0.174282,0.268161,0.276641,-0.275887,0.160890,0.042722,-0.143330,-0.804416,-0.207316,0.154221,0.039249,-0.601228,0.301492,0.004174,0.106229,0.354808,-0.266492,0.131126,0.253379,0.038703,0.455131,-0.366207,0.248791,-0.202235,0.000357,0.631766,-0.119755,-0.101164,0.287147,-0.334671,-0.438792,0.084828,-0.307760,-0.511942,0.080560,0.056308,0.248760,-0.435660,0.409312,-0.567135,-0.013589,-0.344916,-0.090681,0.061721,-0.506457,-0.110865,-0.233465,0.037249,-0.465171,-0.264017,0.017511,0.225257,-0.315768,0.808419,-0.918194,0.203759,0.494587,0.358745,-0.408881,0.480157,0.107792,0.271302,-0.254875,-0.087743,0.344254,0.103808,0.258489,0.243883,-0.056432,-0.160364,0.051245,-0.312037,0.301455', '35030151', '26759819', '26759820', '5364978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6981146', '雪人', '剧情', '《雪人》根据挪威作家Jo Nesbo在2007年出版的同名畅销小说改编，这部书是他以奥斯陆侦探哈里（Harry Hole）为主角创作的第七本小说。故事主要讲述哈里在调查一位年轻妈妈失踪案件的时候，发现受害人院子里出现了一个神秘的雪人，而且它脖子上还围着这家孩子送给妈妈做圣诞礼物的粉红围巾。由此，哈里挖出了一系列有着相同情况的陈年旧案，一个总爱在落下第一场雪时作案的连环杀人犯浮出了水面……《雪人》将由环球公司和Working Title公司联合摄制，如果影片反响良好的话，Jo Nesbo的另外六部侦探哈里小说也将有机会登上大银幕。', '迈克尔·法斯宾德', '托马斯·阿尔弗莱德森', 5.2, 7994, 'tt1758810', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2496245001.jpg', 9.9, 34.1, 43.1, 9.6, 3.3, '0.280104,-0.278420,-0.431316,0.641876,0.247004,-0.100845,0.482729,0.110200,-0.391504,-0.269464,0.180541,0.798342,-0.408019,0.169001,0.100015,-0.039773,-0.502709,-0.660602,-0.145487,-0.211027,-0.234816,-0.559115,-0.469280,-0.193133,0.099280,-0.323874,0.467177,-0.059565,-0.209864,0.312351,0.448780,0.087360,-0.366951,-0.007598,0.057225,0.049001,0.123944,0.012158,-0.203404,0.474868,-0.081329,-0.187555,0.117282,-0.217480,-0.000660,0.351178,0.729544,-0.287954,-0.154464,-0.008333,0.762588,-0.074625,-0.141834,-0.085476,0.522380,0.241177,0.203602,0.401684,-0.190711,-0.009979,-0.107955,-0.434384,-0.672332,-0.019664,0.045335,0.298550,-0.500659,0.177925,-0.206008,0.133684,0.258950,-0.372489,0.198034,0.117917,0.435291,0.222249,0.117268,0.299812,-0.434948,0.398931,0.025310,0.079403,0.067079,0.377091,-0.049685,-0.317047,-0.107540,-0.115890,-0.030074,0.321346,0.329777,-0.213832,-0.257495,0.058977,-0.573797,-0.036437,-0.113023,-0.434097,0.112398,-0.141402,-0.328825,-0.623542,-0.231031,0.176718,-0.085025,-0.318262,0.180553,-0.496716,0.998018,-0.566083,0.133640,0.624862,0.093598,-0.199819,0.684346,-0.023284,0.018304,-0.072124,-0.078662,-0.209264,0.154989,0.237177,0.032612,0.181260,0.005590,-0.476809,-0.399842,0.318453', '27602116', '2027945', '22265121', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6981153', '爱尔兰人', '剧情', '《爱尔兰人》为马丁·斯科塞斯执导的传奇巨制，罗伯特·德尼罗、阿尔·帕西诺和乔·佩西主演。通过二战老兵弗兰克·希兰的视角，讲述了战后美国有组织犯罪的故事。弗兰克·希兰是一名骗子和杀手，曾经在 20 世纪最恶名昭彰的人物身边工作。该电影跨越数十年，记录了美国历史上最大的悬案之一，即传奇工会领袖吉米·霍法失踪案，以宏大的故事之旅，展现有组织犯罪的隐秘通道：其内部运作、仇敌以及与主流政治的瓜葛。', '罗伯特·德尼罗', '马丁·斯科塞斯', 8.8, 245233, 'tt1302006', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2568902055.jpg', 0.3, 0.8, 9, 37.1, 52.7, '0.250953,-0.247907,-0.432546,0.930408,0.346870,-0.140760,0.574652,-0.103785,-0.647257,-0.544157,0.131733,0.963696,-0.079332,-0.116195,0.557636,-0.247033,-0.577510,-0.800759,-0.153569,-0.357178,-0.233078,-0.642976,-0.496803,-0.297796,-0.110755,-0.221379,0.841331,-0.068253,-0.524002,0.074166,0.425181,0.570580,-0.203863,-0.249031,-0.111236,-0.143008,0.391381,-0.034786,-0.760385,0.051830,-0.252731,0.016573,-0.107869,-0.091321,-0.130724,0.149056,0.098455,-0.283393,0.162358,-0.227740,0.517187,-0.322898,-0.130222,-0.349124,0.607439,-0.000586,0.298056,0.565550,0.281999,-0.288603,-0.117171,-0.431679,-1.049522,-0.215911,0.157110,0.324638,-0.515282,0.096802,-0.156802,-0.009487,0.009490,0.150783,0.074836,0.447202,0.609187,0.162423,0.348951,0.017210,-0.289019,0.390380,0.388898,0.127844,-0.407485,0.107462,-0.049393,-0.764485,-0.341991,-0.609213,-0.351676,0.232342,0.200079,-0.311997,0.104475,0.746523,-0.778016,-0.041460,-0.067388,-0.217786,0.183840,-0.254539,-0.006292,-1.031870,-0.591101,-0.267451,-0.033817,-0.144265,0.022093,-0.346706,0.909698,-0.746495,0.149340,0.506798,-0.043914,-0.403126,0.808598,0.068861,0.302828,-0.652456,-0.077444,0.562775,0.058627,0.216230,-0.228133,0.206883,-0.067460,-0.416275,-0.100317,0.340015', '30465281', '4301278', '27602116', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6982558', '长城', '动作', '电影《长城》讲述了在古代，一支中国精英部队为保卫人类，在举世闻名的长城上与怪兽饕餮进行生死决战的故事。欧洲雇佣军威廉（马特·达蒙 Matt Damon 饰）与同伴佩罗·托瓦尔（佩德罗·帕斯卡 Pedro Pascal 饰）不远万里来到中国盗取火药配方，意外发现了长城是为抵御60年降临人间一次的饕餮所建。长城内部机关重重，宛如“陆上航母”，由无影禁军世代镇守。在这里，威廉见识了饕餮的凶残，也见证了无影禁军的精锐和勇敢，并被这群战士之间的信任和牺牲所感动，义无反顾地加入到了共同守护人类的战斗当中。', '马特·达蒙', '张艺谋', 4.9, 382542, 'tt2034800', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2400082527.jpg', 25.2, 27, 31.7, 10.9, 5.2, '0.159659,-0.063655,-0.776528,0.607823,0.091294,-0.117845,0.474950,-0.197511,-0.635303,-0.052071,0.305309,0.645671,0.249901,-0.196199,0.263753,-0.170072,-0.180270,-0.680665,-0.384463,-0.218311,-0.286143,-0.242272,-0.546064,-0.384210,-0.036730,-0.592506,0.678532,0.251727,-0.226355,0.497558,-0.035170,0.350377,-0.368626,0.146005,-0.090401,-0.170998,0.201828,0.032082,-0.499596,0.244591,-0.615420,-0.185145,-0.177070,0.221730,-0.220434,0.113633,0.498602,-0.603878,0.094884,-0.270809,-0.146393,-0.396114,0.102216,-0.010703,0.443574,0.120192,-0.041307,0.232396,0.148558,0.160981,-0.150586,-0.161758,-0.921646,-0.349670,-0.007019,-0.020600,-0.683708,0.575646,-0.064885,0.094016,0.121069,-0.253595,0.237609,0.415725,0.393556,0.496102,-0.201994,-0.056055,-0.550774,0.212351,0.869260,-0.212933,-0.165720,-0.257655,-0.010629,-0.518435,-0.094537,-0.452549,-0.220851,-0.004539,0.121214,-0.121829,0.170225,0.465886,-1.223120,0.100861,-0.408055,-0.235719,-0.110581,-0.174347,0.134722,-0.735785,-0.037273,-0.347281,-0.118608,0.151150,0.165468,-0.041402,0.869714,-0.737056,0.173006,0.558568,0.511821,-0.295781,0.648810,-0.178079,0.050621,0.013970,0.172513,0.217760,0.163848,0.350427,0.078816,0.315341,0.080338,-0.151985,-0.447826,0.365794', '26290398', '3154822', '1308837', '1457926');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6984051', '名侦探柯南：第十一名前锋', '动作', '阳光明媚的一天，东都体育场正进行一场东京Spirit和大阪钢巴的精彩足球比赛，江户川柯南（高山南 配音）、灰原哀（林原惠美 配音）、阿笠博士以及少年侦探团的伙伴们齐齐到场呐喊助威。城市的另一边，事务所内的毛利小五郎（小山力也 配音）却接到一通恐怖袭击的电话。经过一番努力，小兰（山崎和佳奈 配音）终于摆脱新一解开了犯人留下的暗语，成功拯救了无数人的生命。在此之后，警方和毛利一方锁定了数名嫌疑人，并随之展开调查。与此同时，躲在暗处的犯人继续策划新一轮的袭击，前所未有的大挑战，争分夺秒的对决，裹挟着无数怨恨的袭击强势袭来……本片为日本J联赛创立20周年纪念作品，现役选手三浦知良、远藤保仁、今野泰幸、楢崎正刚、中村宪刚等人为片中本人的形象配音。©豆瓣', '高山南', '静野孔文', 6.5, 61392, 'tt2131586', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1448359856.jpg', 2.3, 14, 50.3, 22.3, 11.1, '-0.114979,-0.159534,-0.377613,0.467561,0.137711,-0.060286,0.397558,0.010462,-0.230997,-0.193956,0.278306,0.611430,-0.411240,0.237462,0.254249,-0.360965,-0.396687,-0.852672,-0.358843,0.134679,-0.135151,-0.314159,-0.222760,-0.101777,0.146345,-0.070076,0.570843,0.094524,-0.307353,0.579700,0.252601,0.375456,-0.338315,0.250420,0.343046,0.108477,0.244155,-0.074620,-0.171683,0.317660,-0.263608,-0.301758,-0.401911,0.164199,0.089790,0.411301,0.609808,-0.054722,0.036097,-0.080439,0.278560,-0.440373,-0.083939,0.139778,0.560716,0.189827,0.163887,0.164371,-0.151747,0.016107,-0.214439,-0.100341,-0.704191,0.043454,0.058378,0.146578,-0.107624,0.503787,-0.061657,0.069650,0.348208,-0.190760,-0.005411,0.193149,0.193339,0.216802,-0.407942,0.243386,-0.076304,0.260770,0.503445,-0.088073,0.032175,-0.083160,0.175429,-0.376773,-0.213437,-0.164322,-0.186740,-0.297724,0.415147,0.045929,0.078837,-0.040094,-0.616263,-0.076527,-0.246166,-0.459393,-0.098709,-0.157004,0.020270,-1.090408,0.187509,-0.098659,-0.012522,0.337096,0.236906,-0.065746,0.792554,-0.554670,0.053701,0.715865,0.074695,-0.089687,0.157056,0.096502,0.132705,-0.050128,-0.181371,-0.087015,0.118634,0.501012,0.115500,0.256248,-0.289897,-0.213514,-0.528488,0.266670', '2369613', '20274039', '25723905', '26788667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6984064', '非常幸运', '喜剧', '现实中百般碰壁、只能在漫画中享受万人瞩目荣耀的漫画家苏菲（章子怡 饰），竟意外中了一个新加坡五日游大奖。在两位闺蜜李莉（姚晨 饰）和陆小夕（林心如 饰）的鼓励下，苏菲满怀期待飞赴新加坡。谁知刚出机场，她就遇到和幻想中的王子一模一样的帅哥严大卫（王力宏 饰）。大卫的真实身份是一名特工，此次为追查被窃钻石“幸运星”和神秘买家高先生（高捷 饰）来到新加坡。苏菲稀里糊涂混入私人派对，并阴差阳错拿到了装有“幸运星”的箱子，当然这也将她置身于连番的追杀和争夺战中。与超级完美的王子相伴，一贯过着平凡无聊生活的苏菲展开了充满挑战的异国大冒险……©豆瓣', '章子怡', '丹尼·高顿', 4.6, 65025, 'tt2102502', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2135510977.jpg', 21.4, 39.3, 31.2, 5.2, 2.9, '0.237887,0.227694,-0.599796,0.656830,-0.038673,-0.061963,0.781143,-0.039822,-0.528362,-0.030511,0.386987,0.803569,-0.428562,0.276486,0.601292,0.100485,-0.402432,-0.586518,-0.215348,-0.270162,-0.164367,-0.429394,-0.504139,0.141952,-0.059003,-0.037361,0.527771,0.031516,-0.195385,0.790493,0.679768,0.293500,-0.482770,0.470841,-0.190925,-0.034200,0.358330,0.382484,-0.378447,0.368453,-0.143652,-0.139633,0.051101,0.151704,0.103581,0.189285,0.572052,-0.371488,0.101544,0.084124,0.343935,-0.125930,-0.141076,0.142088,0.049903,0.250140,0.288388,-0.073391,-0.144908,0.275195,0.218893,-0.124497,-0.673497,0.117970,0.252202,0.045388,-0.453117,0.496044,-0.074110,-0.208793,0.278980,-0.098865,0.304684,0.142035,0.373824,0.174843,0.076499,0.222965,-0.320406,0.475937,0.378144,0.188691,-0.114066,0.078445,-0.032816,-0.419798,0.033792,-0.192774,-0.530990,0.013406,0.350635,-0.018522,0.128197,0.135364,-0.677619,0.162870,-0.276781,-0.111053,-0.058882,-0.244466,-0.025185,-0.835801,-0.007431,-0.495696,-0.229311,0.020403,0.154331,-0.349298,0.644296,-0.751948,0.185837,0.371816,0.317455,-0.244178,0.593313,0.294353,-0.074005,-0.250546,-0.363011,0.284324,-0.015880,0.104962,-0.133417,0.446043,-0.193561,-0.219993,-0.428663,0.440339', '1292050', '10763928', '1301686', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6984070', '情谜', '剧情', '美丽的惠香（舒淇 饰）和惠宝（舒淇 饰）是一对双胞胎姐妹，姐姐惠香沉默贤惠，她与失明的母亲（奚美娟 饰）相守海边，过着平淡的日子；妹妹惠宝俏皮可爱，自艺术学校毕业后便和男朋友阿楠（余文乐 饰）共同排演《红梅传奇》。某次演出因为生病，惠香代替妹妹上台，获得观众和同事的认可 ，而她和阿楠也相互吸引，互生情愫。这段禁忌的情感让姐妹俩心生隔阂与猜疑，在某个暴雨之夜过后，惠香杳无音讯，而惠宝的行为举止也变得越来越奇怪。惠香失踪的背后似乎隐藏着巨大的秘密，而阿楠、姐妹的妈妈也越来越分不清眼前的究竟是惠宝还是惠香……©豆瓣', '舒淇', '黎妙雪', 5.6, 13959, 'tt2271555', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1420964300.jpg', 6.6, 27.6, 48.7, 13.7, 3.3, '0.208470,-0.319873,-0.590505,0.584274,0.236148,-0.204851,0.977118,0.043737,-0.503392,-0.111015,0.149780,0.537935,-0.454997,0.569290,0.239005,0.106615,-0.297141,-0.681005,0.042201,-0.110931,0.048020,-0.431920,-0.233934,0.003019,0.123143,-0.325631,0.551282,-0.082758,-0.079681,0.778087,0.375868,0.101517,-0.454793,0.316341,-0.052179,0.066321,-0.214684,0.507380,-0.421281,-0.376240,0.162956,-0.089820,-0.289967,0.076880,0.088612,0.310486,0.708648,-0.215914,-0.193619,-0.129264,0.176539,-0.209727,0.085613,0.130703,0.353002,0.027361,0.368972,0.230329,-0.207823,0.048171,-0.209714,0.110334,-0.284479,0.470386,0.596967,0.036890,-0.380491,0.519561,0.040319,-0.314299,0.270716,-0.174105,0.260456,0.196973,0.273319,0.509689,-0.533398,-0.098743,-0.166001,0.259588,0.604866,0.154718,-0.187557,0.467792,-0.440500,-0.457991,-0.036789,-0.081344,-0.637311,0.112408,0.024386,0.221862,0.084767,0.312024,-0.698754,0.009447,0.022174,0.225872,-0.050678,-0.761581,0.122588,-0.370142,-0.394601,-0.720710,-0.445734,0.068359,0.026207,-0.200936,0.790863,-0.862526,0.213928,0.200794,0.381862,-0.488444,0.439226,0.393392,0.055023,-0.362887,-0.330109,0.114211,-0.359313,-0.111129,0.068451,0.344023,-0.177567,0.257189,-0.324731,0.141781', '3445516', '25911595', '1292219', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6985803', '少年斯派维的奇异旅行', '剧情', '小小少年T.S. 斯派维（凯尔·凯特莱特 Kyle Catlett 饰）生于蒙大拿州一个偏远牧场，他有一颗聪明绝顶的大脑，酷爱制图学和科学图解，年仅十岁就发明了永动机。他的父亲（考乐姆·吉斯·雷尼 Callum Keith Rennie 饰）是个狂热的牛仔迷，搜集关于西部牛仔的一切；母亲（海伦娜·伯翰·卡特 Helena Bonham Carter 饰）是一位生物学博士，潜心投入到昆虫研究中；而姐姐则是一个最普通不过的正常人，她常常为生在这个一屋子怪人的家里而烦恼。T.S.原本还有一个异卵双胞胎弟弟雷顿，去年死于一场意外。这天，T.S.接到一个来自史密森学院的电话，告知他被授予了世界科学大奖贝尔德奖，并邀请他到华盛顿演讲。于是，十岁的科学奇才T.S.斯派维，偷偷爬上了货运火车，独自踏上了穿越美国的奇异旅行。©豆瓣', '凯尔·凯特莱特', '让-皮埃尔·热内', 8.5, 102368, 'tt1981107', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2189163440.jpg', 0.1, 0.8, 12.9, 46.2, 39.9, '0.316578,-0.120994,-0.545432,0.585534,-0.238845,-0.294307,0.435496,0.076556,-0.362433,-0.426841,-0.017859,1.059977,-0.093147,0.316633,0.307464,0.365908,-0.300858,-0.362954,0.020900,-0.198280,-0.315525,-0.559159,-0.241646,-0.126062,0.013256,-0.397956,0.221681,-0.002426,-0.119608,0.607391,0.119899,0.348961,0.038348,0.258048,-0.248316,0.021278,0.360357,-0.091070,0.156726,0.132400,-0.080280,0.021982,0.100039,0.112911,0.041585,0.306754,0.508962,-0.278598,0.025645,-0.267820,0.422759,-0.207460,-0.227996,-0.082342,0.412777,-0.192420,-0.084695,0.020516,0.041703,-0.033253,0.241107,-0.209393,-0.577711,-0.162357,-0.010377,0.163211,-0.440744,0.224980,-0.047462,-0.090363,-0.164398,-0.350956,0.090970,0.195874,0.037880,0.450743,-0.058884,-0.032570,-0.397051,0.410880,0.332658,-0.040621,-0.339811,0.462709,-0.225246,-0.496956,0.104083,-0.179404,-0.522026,0.023163,0.302136,-0.358463,-0.126640,0.127748,-0.471483,0.088675,-0.315072,-0.330592,-0.022478,-0.177011,-0.271555,-0.485943,0.044947,-0.222586,-0.332245,-0.055570,0.195812,-0.221429,0.703505,-0.612763,0.305782,0.574455,-0.105379,-0.056851,0.666079,-0.206822,0.129193,-0.332694,0.069493,0.274159,0.069193,0.187642,-0.314399,0.487956,0.100188,-0.249489,-0.510703,0.386461', '1870681', '30162520',