INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6985810', '狩猎', '剧情', '刚刚和妻子离婚的卢卡斯（麦斯·米科尔森 Mads Mikkelsen 饰）目前在一家托儿所工作，心地善良个性温和的他很快就受到了同事和孩子们的喜爱，其中，一个名叫卡拉（安妮卡·韦德科普 Annika Wedderkopp 饰）的早熟女孩对卢卡斯尤为的亲近。面对女孩幼稚 而单纯的示好，卢卡斯只能婉转的拒绝，可令他没有想到的是，这一举动将他的生活推向了风口浪尖。卡拉报复性的谎言让卢卡斯背负起了性侵女童的罪名，一时间，这个好好先生成为了整个小镇排挤和压迫的对象。好友的愤怒，前妻的不信任，爱犬的死亡和陌生人的恶意让卢卡斯几近崩溃，而当小小的卡拉吐露真相之后，恶意却并没有随着卢卡斯的重获清白而划下句点。©豆瓣', '麦斯·米科尔森', '托马斯·温特伯格', 9.1, 358927, 'tt2106476', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1546987967.jpg', 0.2, 0.4, 5.3, 31.4, 62.7, '0.481824,0.097256,-0.862310,0.736528,-0.503470,-0.121939,1.033264,0.278953,-0.441796,-0.064600,0.092269,0.874327,-0.265948,0.322095,0.336071,0.051884,-0.120800,-0.741975,-0.204291,0.014777,-0.169900,-0.712594,-0.144495,-0.333697,-0.325339,-0.328041,0.461340,-0.113083,-0.360401,0.432633,0.399080,0.448382,0.154289,0.581179,-0.086346,0.099591,0.068482,-0.041072,-0.109304,0.158183,0.111322,-0.072896,-0.016370,0.623316,-0.231528,0.590577,0.635885,-0.440748,-0.078718,-0.139999,0.357635,-0.377101,0.058266,0.168749,0.166335,-0.318943,0.297369,0.173992,-0.265627,0.020602,0.263794,-0.060233,-0.937540,0.135839,0.103569,0.229545,-0.606477,0.570859,-0.243407,-0.096392,0.157223,-0.195753,0.025765,0.207215,0.131372,0.505850,-0.238688,0.180854,-0.283072,-0.047521,0.581630,0.231629,-0.552393,0.322194,-0.673547,-0.245766,0.123294,-0.233160,-0.562519,-0.027670,0.394795,0.215624,-0.166013,0.361632,-0.491341,-0.223288,-0.364613,-0.077433,0.074240,-0.698923,-0.174225,-0.436313,-0.180098,-0.390326,-0.401262,-0.208627,-0.021027,-0.173591,0.727907,-0.931018,0.123420,0.525593,0.426972,-0.467265,0.579430,0.376650,0.030084,-0.111400,-0.035395,0.321259,0.102432,0.157145,0.233706,0.272068,0.041611,-0.214109,-0.214240,0.662846', '3119246', '35158375', '24756472', '1299802');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6991110', '消失的子弹', '动作', '民国时期，国内最大的兵工厂发生离奇命案，死者被“幽灵子弹”所杀——犯罪现场找不到弹头。一时之间，疑云密布，人心惶惶，此案堪称民国第一奇案。此案交由警局内负责管理档案的政务警察松东路调查（刘青云 饰），担任文职的松东路既不会拳脚功夫也不懂如何开枪，却思想缜密，对破疑难杂 案有独特方法。一心为民除害的热血警探郭追（谢霆锋 饰）不容于警局贪污腐败氛围，联手松东路调查此离奇命案。如何开枪不用子弹？如何让子弹在穿入肉体的时候消失？松东路和郭追在枪和子弹上做了各种各样的研究，包括向猪身体发射盐子弹、冰子弹等等，却没有任何满意的结果。随着案情调查深入，两位警探抽丝剥茧地发现恐怖阴森的杀人密室和离奇的造弹装置，其诡异程度让经验丰富的松东路也瞠目结舌。就在“幽灵子弹杀人”真相揭开之际，松东路、郭追却接二连三遭人追杀，警察小五（井柏然 饰）在开枪掩护松东路、郭追逃亡之时惨死。结案期限迫在眉睫，算命姑娘小云雀（杨幂 饰）不经意间透露出“幽灵子弹”惊天秘密……', '谢霆锋', '罗志良', 6.5, 110656, 'tt2106741', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1713985976.jpg', 1.7, 10.4, 55.1, 27.2, 5.6, '0.127359,-0.082153,-0.641423,0.041593,0.000621,0.232021,0.648112,-0.084587,-0.165289,-0.468635,0.075051,0.041581,-0.429979,-0.547634,-0.135438,-0.236287,-0.050912,-0.456894,-0.064781,-0.246297,-0.425758,-0.369369,-0.301992,-0.437243,0.041989,-0.067962,0.316560,0.297855,-0.354062,0.314568,0.265443,0.581657,-0.409247,0.241729,0.194467,-0.175516,0.112468,0.155283,-0.329621,-0.133231,0.160545,-0.562926,-0.042101,0.090171,-0.146574,0.296139,0.494261,0.206380,-0.193101,-0.092129,0.013455,-0.129475,-0.081993,-0.052252,0.261355,0.095885,-0.278335,-0.003787,-0.097832,0.148820,0.026164,0.313653,-0.413263,-0.388355,0.146044,0.145970,-0.210740,0.118015,-0.400710,0.068251,-0.142160,-0.604856,0.303079,-0.035447,0.169420,0.017204,-0.135734,0.127492,-0.585331,0.163144,0.524529,0.090561,-0.282184,-0.113812,0.124728,-0.412510,-0.120662,0.083452,0.117106,0.225222,0.372092,0.316745,-0.356180,0.290695,0.011121,-0.281678,-0.421825,0.003854,-0.205572,-0.298404,-0.216355,-0.707235,-0.062181,-0.290595,-0.391481,0.247196,0.106699,0.006591,0.265307,-0.489310,-0.132527,0.331980,0.004798,-0.185247,-0.002103,0.003179,0.176080,-0.119010,-0.018767,-0.385132,0.418963,0.623964,0.405419,0.210422,-0.310467,-0.486962,-0.379954,-0.089877', '3268171', '35206186', '1309110', '1301345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6999256', '帝国秘符', '动作', '成晰（潘粤明 饰）的女儿遭人绑架，皆因其父（侯勇 饰）掌握玉玺的秘密，国际文物犯罪头目只给了成晰20个小时，否则撕票。刑警梅佳（胡可 饰）与日本历史专家小野淋子（伊能静 饰）介入调査，她惊讶地发现成晰竟是她多年前的恋人，一时思绪难平，伹刑警的身份让她克制了自己的感情。随之而来的是600年前一系列皇家文物的出现，从明皇朱允炆的失踪，到朱元璋的开国玉玺，再到栖霞寺和明孝陵，成晰被一只无形的黒手推向万劫不复的深渊。梅佳顺藤摸瓜，准备实施抓捕，距绑匪规定的时间越来越近，梅佳来到交换人质的明孝陵，惊天阴谋即将揭开......©豆瓣', '潘粤明', '李作楠', 3.2, 4853, 'tt4191680', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2110007227.jpg', 65.5, 18.6, 11.2, 1.1, 3.6, '0.239069,0.076396,-0.749239,0.440779,0.090578,-0.012540,0.575823,0.105926,-0.531116,-0.250106,0.466037,0.438773,-0.274629,-0.067732,0.445234,0.166045,-0.257302,-0.993454,-0.036755,-0.345874,-0.294015,-0.208302,-0.280230,-0.145227,-0.028948,-0.086689,0.691564,0.169702,-0.095251,0.266389,0.149355,0.240658,-0.302107,0.264628,-0.027110,0.141044,0.137962,-0.159975,-0.178652,0.068606,0.022099,-0.405919,-0.035722,0.134909,-0.349858,0.464603,0.546945,-0.134645,-0.072536,-0.018680,0.418205,-0.439379,-0.291123,-0.073313,0.364226,0.111288,-0.130904,0.385066,-0.425786,0.081406,0.242391,-0.092799,-0.403829,0.036827,-0.007574,0.217701,-0.429394,0.338040,-0.212475,0.058524,-0.009817,-0.300876,0.214575,0.344696,0.143902,0.363372,-0.152784,-0.018039,-0.436463,0.229506,0.250095,-0.186870,0.110021,-0.078703,0.060308,-0.518299,-0.077327,-0.264424,-0.089047,-0.059672,0.566491,0.059893,-0.151919,0.312014,-0.505718,-0.442999,-0.334106,0.155450,0.105571,-0.371479,-0.092469,-0.350822,-0.247927,-0.142448,-0.190170,0.160913,0.384318,-0.174487,0.360911,-0.335323,0.178600,0.593178,0.194941,-0.351822,0.257547,-0.022252,0.094276,-0.195959,-0.247330,0.009412,0.216628,0.484328,0.076088,0.055141,0.015673,-0.257849,-0.175824,0.101110', '1306449', '24719853', '1947080', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('6999258', '今天开始恋爱吧', '喜剧', '某座高中迎来了新的学生，虽然有着美丽容颜却土了土气的女孩日比野椿（武井咲 饰），在开学典礼当天竟然被入学成绩第一名的帅哥椿京汰（松坂桃李 饰）夺去初吻。以此为开端，京汰将日比野当作捉弄的对象，乐此不疲。虽然讨厌这个英俊帅气却举止轻薄的男孩，可是日比野内心深处却悄悄发生着转变。古板、传统的女孩情窦初开，些许品尝到青春和初恋的甜蜜。与此同时，京汰对日比野的情感也正发生着变化。在那个看似无比浪漫的情人节夜晚，抬头望见繁星的天文台上，日比野鼓起勇气向京汰告白，谁知他们的关系竟急转直下……本片根据漫画家水波风南的同名原作改编。©豆瓣', '武井咲', '古泽健', 5.7, 8853, 'tt2118667', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1660052137.jpg', 6.4, 26.5, 49.5, 13.2, 4.3, '0.234074,0.171122,-0.542260,0.649122,-0.183373,-0.101713,0.870167,0.199876,-0.173357,-0.376778,0.071556,0.424134,-0.649057,0.575951,0.597429,-0.000608,0.014814,-0.703020,-0.105092,0.031441,0.073110,-0.149194,-0.397478,0.386227,0.146801,-0.524606,0.824960,0.212394,-0.129697,0.558596,0.378205,-0.085865,-0.035326,0.487656,-0.260611,-0.123652,-0.062686,0.500471,-0.034785,0.096426,-0.192923,-0.543562,-0.247549,0.045536,-0.314724,0.450414,0.912869,-0.113303,-0.359224,-0.061152,0.751986,-0.096421,-0.163185,0.259597,0.379570,0.134241,-0.069001,-0.070627,0.003675,0.008568,0.038523,-0.290998,-0.321560,0.214534,0.200746,0.292888,-0.288266,0.733513,-0.030533,-0.014834,0.268995,-0.280123,-0.078390,-0.158366,0.328058,0.547611,-0.100753,0.450258,-0.299763,0.076153,0.575290,0.301622,-0.318968,0.610161,-0.577127,-0.344171,0.085367,-0.007161,-0.457042,0.207875,0.175687,0.020548,0.002602,0.232841,-0.675450,-0.030056,-0.019077,0.074049,0.211438,-0.445541,-0.315772,-0.525323,-0.139937,-0.672987,-0.443934,0.158716,0.057737,-0.331315,0.828027,-0.904464,-0.066435,0.621448,0.132618,-0.119301,0.460312,0.344741,-0.319848,-0.270832,-0.353551,0.308846,-0.077252,0.096873,-0.249503,0.519242,-0.281905,-0.208841,-0.348256,0.579940', '24839498', '10174444', '1826173', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7003416', '冲上云霄', '剧情', '翱翔蓝天的飞机上，承载着多少人的爱恋梦想。富家公子哥Branson张春亮（古天乐 饰）以CEO身份接手了老爸的天颂航空，而他在飞机上重逢前任女友潘家诗（佘诗曼 饰）。他们若即若离，时远时近。打扮入时出位的女艺人谭梦（郑秀文 饰）受邀为天颂航空拍摄宣传片，个性十足的唐亦琛（吴镇宇 饰）以飞行技术总监身份与谭梦搭档，直来直去的两人最初的相处充满火药味，不过他们也在争吵的过程中渐渐靠近。为了更高报酬的机师顾夏阳（张智霖 饰）离开天颂航空，巧遇张狂女子薛健雅（郭采洁 饰），性格全然没有交集的二人竟衍生出许多的故事。三对男女，三段恋情……本片根据香港电视广播有限公司的同名电视剧改编。©豆瓣', '古天乐', '叶伟信', 4.5, 49513, 'tt1929433', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2223365653.jpg', 25.5, 36.2, 28.7, 6.3, 3.3, '0.203388,-0.131929,-0.637419,0.697849,0.079023,-0.201751,0.611603,0.219924,-0.452972,-0.323690,0.347404,0.643825,-0.290615,-0.012084,0.244927,-0.231059,-0.220552,-0.510883,-0.175939,-0.013326,0.128279,-0.412505,-0.068978,0.105434,-0.060959,-0.141682,0.874185,-0.178474,-0.327193,0.546088,0.508194,-0.061752,-0.322109,0.166916,-0.076691,-0.125159,0.012905,0.358710,-0.377050,0.025345,-0.272587,-0.087041,-0.206652,-0.219799,-0.208283,0.362722,0.889758,-0.081828,-0.040723,0.071009,0.398046,0.049725,0.166986,-0.185040,0.095722,0.159376,0.408525,0.180117,-0.063224,0.146827,-0.299345,-0.001259,-0.391379,0.214386,0.118308,0.201125,-0.256395,0.561330,-0.329132,-0.107841,0.121633,-0.285398,0.021231,0.043060,0.333945,0.235597,-0.071401,0.154523,-0.477196,0.391437,0.444906,0.424916,-0.199379,0.640430,-0.354839,-0.457285,-0.465674,-0.198795,-0.499661,-0.152076,0.155913,-0.132683,0.237991,0.259066,-0.684016,0.000536,0.053835,0.170948,-0.139723,-0.292521,0.090430,-0.872706,-0.205008,-0.561612,-0.177532,-0.182093,0.287643,-0.417849,0.714333,-0.829404,-0.014075,0.244103,0.233441,-0.360761,0.591225,0.004193,-0.040423,-0.475556,-0.305995,0.161786,-0.129007,-0.292523,-0.083143,0.370845,-0.308149,-0.042272,-0.149506,0.268727', '3811356', '10174444', '1322847', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7015714', '南国野兽', '剧情', '在一个叫巴斯特普的河口地区，6岁的小姑娘“小玉米饼”（奎文赞妮·瓦利斯 Quvenzhané Wallis 饰）和她的爸爸温克（德怀特·亨利 Dwight Henry 饰）生活在此地。一座大坝将巴斯特普与外面的世界隔绝起来，人们在这里过着相对原始的生活。命不久矣的温克对女儿很严厉，一心希望她早日学会自己生存。一次可怕的飓风席卷了这个小村庄，他们的家园被野兽般的洪水吞噬。大灾难过后，幸存的人都团结在一起，开始重建家园。然而事情并非如此简单，洪水一直没有退去，小村庄的一切都开始衰败，动物尸体随处可见。而另一方面，外面世界已经将此地划为强制撤离区域，相关人员进入村庄，强制把他们带去避难所。面对残酷得如一头野兽的世界，小姑娘并没有害怕，她相信宇宙有某种和谐的平衡。在爸爸独特的教育下，她变得越来越坚强，并且学会理解这个世界……©豆瓣', '奎文赞妮·瓦利斯', '贝赫·泽特林', 7.6, 23581, 'tt2125435', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1790179785.jpg', 0.8, 4, 29.2, 45.8, 20.2, '0.317902,0.275304,-0.757022,0.450004,-0.321705,0.117068,0.865379,0.142251,-0.392806,0.077264,0.109632,0.668248,-0.061937,-0.002025,-0.199279,-0.063929,-0.422572,-0.434435,-0.196926,-0.210667,-0.340812,-0.296014,-0.221213,-0.303153,-0.159376,-0.468780,0.632387,0.311558,0.046659,0.228191,-0.305720,-0.006238,0.035329,0.556769,-0.394779,-0.018440,-0.156911,-0.097913,-0.274713,0.061158,-0.089918,0.261250,-0.232931,0.244800,-0.125981,0.170343,0.711558,-0.429210,-0.108422,-0.169516,0.215120,-0.197492,0.024666,0.087532,0.479069,-0.224801,0.026155,0.062795,-0.200658,0.064434,0.027170,-0.205486,-0.447176,-0.074655,0.216867,0.235901,-0.380223,0.220731,0.172106,-0.058287,0.030386,-0.440283,0.028813,0.313886,0.337845,0.554865,-0.215235,0.078674,-0.556855,0.046802,0.850893,-0.248712,-0.490729,0.198488,-0.499091,-0.389802,-0.082685,-0.252494,-0.568660,-0.285032,0.208760,-0.108089,-0.508019,0.461612,-0.736930,0.144560,-0.273843,-0.406741,-0.172624,-0.350715,-0.299705,-0.387536,-0.045403,-0.123541,0.058651,0.181905,-0.023991,-0.167029,0.913038,-0.704561,0.491169,0.680767,0.578884,-0.257467,0.555503,-0.061525,0.263113,-0.222086,0.104458,0.517091,0.018951,0.634349,0.194156,0.432256,-0.104110,0.176732,-0.381165,0.830086', '21619567', '3005387', '1308831', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7046723', '猩球崛起2：黎明之战', '剧情', '十年前，人类为自己的愚蠢付出惨痛代价，凶险致命的猿流感病毒蔓延全球，世界毁灭殆尽。而在毗邻旧金山的原始丛林，凯撒（安迪·瑟金斯 Andy Serkis 饰）带领猩猩伙伴们建立起无忧无虑的王国，直到某一天，猩猩的家园的宁静再度被人类打破。在旧城苟延残喘的人类面临能源危机，他们试图利用森林腹地大坝的发电站提供能源。青年科学家马尔科姆（杰森·克拉科 Jason Clarke 饰）试图说服聚集地负责人德里弗斯（加里·奥德曼 Gary Oldman 饰），希望通过和平手段取得猩猩部落的信任和同意。然而凯撒的好盟友科巴（托比·凯贝尔 Toby Kebbell 饰）却无法摒除对人类的憎恨，他尝试着挑战者凯撒的权威。人类和猩猩，双方小心翼翼试探，而战争在所难免……©豆瓣', '安迪·瑟金斯', '马特·里夫斯', 7.6, 286461, 'tt2103281', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2196211285.jpg', 0.4, 2.5, 29.2, 50.2, 17.8, '-0.023125,0.217350,-0.625556,0.534612,0.095787,-0.052255,0.568127,-0.002690,-0.240820,0.010255,0.297550,0.452510,0.403575,-0.133209,0.147071,-0.085602,-0.366068,-0.320079,-0.083225,0.143648,-0.121403,-0.281273,-0.580074,-0.618146,-0.049425,-0.626283,0.817035,0.265736,-0.063738,0.288594,0.013297,0.597913,0.003131,0.202163,0.149535,-0.144724,0.327383,-0.293734,-0.703402,0.138968,-0.214409,0.229946,-0.115243,0.294207,-0.174058,0.185970,0.569917,-0.647316,0.058652,-0.462114,0.236353,-0.509256,0.234044,0.214064,0.477017,-0.315230,-0.001774,0.297592,0.079111,-0.135329,0.183337,-0.196929,-0.804786,-0.185534,0.085386,0.173864,-0.293995,0.654142,0.043622,0.120337,0.287427,-0.102540,-0.356146,0.462663,0.544638,0.094014,-0.216785,0.050203,-0.300766,-0.052119,0.661423,-0.350936,-0.560100,-0.103649,-0.393040,-0.557967,-0.231196,-0.495043,-0.615979,-0.356147,0.281124,-0.001570,-0.201460,0.624404,-0.908522,-0.007065,-0.527785,-0.476674,0.257584,-0.212131,-0.132694,-0.733569,-0.229064,-0.137332,-0.054526,0.151403,0.089734,-0.193488,0.660204,-0.746484,0.120904,0.654416,0.455644,-0.279486,0.493833,-0.318922,0.101834,-0.430949,-0.007902,0.638055,0.122802,0.302961,0.135012,0.079058,0.101674,0.192456,-0.152030,0.540505', '26290398', '26759819', '1972732', '5308201');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7051294', '花漾', '剧情', '三百多年前，东南沿海一个世代流放罪犯的“流放岛”，岛上居民除了正当营生还兼做海盗，以抗衡官府及各方的威胁，官府对海盗头海爷（任达华 饰）以高官厚禄为诱饵进行招安，海爷断然回绝。岛上各色人往来频繁，一条璀璨花街更是给了冒险漂泊的男人们醉生梦死的温柔；“中元祭典”，是岛上每年的盛事。在中元祭中，以歌声抚慰死者的“歌妓祭鬼”最引人注目。花漾楼老鸨月娘（吴君如 饰），调教出性格迥异的孪生艺旦：小雪（陈妍希 饰）与小霜（陈意涵 饰），凭着“花漾双陪”红的发紫。姐妹俩却因外人所不知的隐秘不惜制造命案！月娘让小雪嫁祸给琴师（郑元畅 饰），但小雪因爱慕他而宁可牺牲自己守护爱情；小霜虽有知交好友海盗刀疤（言承旭 饰），但也同时周旋在富贵茶商的女婿李二少（茅子俊 饰）身边。李二少在小霜和原配甄芙蓉（李小冉 饰）之间犹豫不决，不经意间他参与了由小霜设计的情色与金钱的豪赌。得知丈夫背叛的甄芙蓉绝望跳海，被海爷救起后俩人发展出暧昧之情，而一贯不相信女人的海爷，竟不幸掉进另一个陷阱……在这场情、权、欲的豪赌中，谁才是赢家？', '陈意涵', '周美玲', 5.7, 21797, 'tt2459496', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2109275112.jpg', 8, 26.4, 43.1, 16.6, 5.8, '0.096239,0.056132,-0.414035,0.532992,0.010882,-0.144243,0.568358,0.129857,-0.459130,-0.016974,0.428795,0.491542,0.006132,0.140680,0.245620,0.088337,0.049963,-0.495891,-0.202802,-0.162074,-0.220194,-0.311222,-0.220246,-0.075868,-0.345410,-0.020250,0.446266,0.172414,-0.232702,0.436435,0.497559,0.261199,-0.360977,0.299328,-0.001594,-0.081764,-0.142722,0.113135,-0.316216,-0.025272,-0.231210,-0.344577,-0.200739,0.035966,-0.029330,0.447527,0.652712,-0.420906,0.133436,-0.340626,0.171162,-0.122021,0.015941,0.153700,0.124394,-0.121166,0.309758,0.314362,-0.353451,0.009211,0.096215,0.057275,-0.552329,0.175002,0.470793,0.027328,-0.388184,0.296963,-0.047638,-0.092441,0.038038,-0.046555,0.224439,0.193749,0.197914,0.230482,-0.190775,0.104226,-0.390006,0.452739,0.498650,0.006493,0.136502,0.084115,-0.106843,-0.255925,0.201537,-0.337481,-0.402212,-0.035035,0.071595,-0.174799,0.098119,0.283398,-0.650490,-0.009759,-0.278167,0.170401,0.081168,-0.236116,-0.153729,-0.463842,-0.098186,-0.353457,-0.202022,0.210193,0.350691,-0.107148,0.584630,-0.695876,-0.072089,0.425042,0.254786,-0.657826,0.571769,0.123491,0.250905,-0.136127,-0.269069,0.143086,0.191962,0.067859,0.087135,0.155793,-0.089283,-0.021492,-0.052922,0.116900', '4301278', '3445516', '3033092', '1418179');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7051357', '魁拔之大战元泱界', '动作', '每隔333年，强大而神秘的生物魁拔诞生天地之间，引起元泱界莫大的灾难。第六代魁拔魁拔蛮吉（刘婧荦 配音）悄然逃过一劫，而今随着蛮小满（王凯 配音）朝着最伟大妖侠的道路上不断前进。他们成功登上开往涡流岛的曲境一号，随着众多神圣联军战士逼近那个危险所在，指望打败魁拔建功立业。与此同时，天界魁拔司主神镜心（刘露 配音）准确测出新一代魁拔的正确方位。为了给这个难缠的对手以致命一击，她不惜使用牺牲地界生物的光势。在涡流岛上，神圣联军的先头部队遭到幽弥狂及其战友的强力扑杀。随后蛮小满、雪伦（敖磊 配音）、蛮吉随着镜心登岛，惨烈的战斗撼动元泱界的每一个角落……©豆瓣', '刘婧荦', '王川', 8.1, 51344, 'tt3279464', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1966309325.jpg', 1.1, 3, 19.6, 40.4, 35.9, '0.107978,0.293131,-0.658723,0.735922,0.350261,0.336973,0.515635,-0.198966,-0.059114,-0.170344,0.395527,0.524817,0.174641,-0.335311,0.271894,-0.399928,0.196699,-0.013264,-0.175317,0.145609,-0.488803,0.047418,-0.533406,-0.207593,-0.066848,-0.471802,0.950343,0.218146,-0.339221,0.334566,0.172253,0.546299,-0.359047,0.151988,-0.087866,0.018345,-0.111824,-0.216245,-0.240251,0.476881,-0.478033,-0.000030,0.107619,0.341323,-0.399188,0.139034,0.385156,-0.557806,-0.051998,-0.397281,0.400104,-0.406202,-0.141822,-0.072878,0.459736,0.010950,-0.058805,0.041144,0.100013,-0.057998,-0.434766,-0.181260,-1.051525,-0.356979,-0.011177,-0.063879,-0.126996,0.178532,0.317463,-0.067501,0.456809,-0.384916,0.144184,0.414112,0.238993,0.149642,-0.317710,0.164459,-0.050517,-0.163471,0.750019,0.013427,-0.496004,-0.043660,0.005728,-0.331689,-0.128334,-0.585063,-0.279311,0.010727,0.403827,0.311479,0.528733,0.316608,-0.533396,0.042245,-0.087998,-0.171616,0.023566,-0.206107,-0.245566,-0.567949,-0.078499,-0.048829,0.065270,0.206812,-0.165894,-0.116518,0.791688,-0.634742,0.365350,0.752066,0.401312,-0.155316,0.436084,-0.238149,0.212261,-0.436533,-0.106769,0.351602,0.274554,0.514425,-0.011700,0.126474,-0.103182,0.029118,-0.265343,0.325728', '3861846', '3001114', '26667010', '2051813');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7051375', '剑风传奇 黄金时代篇3：降临', '剧情', '传奇佣兵部队“鹰之团”，在团长格里菲斯（樱井孝宏 配音）的率领下结束了百年战争，一跃成为米特兰王国的正规军。但是荣誉的顶点也正是衰落的开始，格里菲斯被国王投入“再生之塔”最底层的死牢，遭受常人难以想象的折磨，鹰之团也沦为叛军潜入丛林荒野，时刻遭到追兵的屠戮。黑暗而漫长的一年后，战神格斯（岩永洋昭 配音）重新归队，与代理团长卡思嘉（行成桃姬 配音）建立深深的信任，并在夏洛特公主（丰崎爱生 配音）的帮助下冒险救出格里菲斯。格斯让走投无路的鹰之团看到新的希望，而丧失了一切的格里菲斯则跌入绝望的谷底。当216年一次的日食出现，格里菲斯与霸王之卵再次邂逅，恶魔的血腥盛筵拉开序幕……本片根据漫画家三浦健太郎的同名原作改编，为“剑风传奇剧场版三部曲”的最后一部。©豆瓣', '岩永洋昭', '洼冈俊之', 8.9, 15469, 'tt2358913', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1778898508.jpg', 0.6, 1, 8, 32.8, 57.5, '0.053035,0.120396,-0.445836,0.541796,0.338477,-0.291416,0.573220,0.069511,-0.204895,-0.278569,0.422525,0.742922,-0.116204,0.089931,0.525709,-0.113784,-0.245971,-0.730591,-0.370241,-0.064202,-0.110529,-0.325174,-0.223609,-0.024995,-0.020154,-0.572283,1.198868,0.373421,-0.186789,0.421318,0.315530,0.354491,0.004170,0.234010,0.091092,0.148296,0.119909,-0.135475,-0.392455,0.311086,-0.207455,-0.124236,-0.221850,0.119399,-0.027058,0.092011,0.715920,-0.536592,0.002847,-0.320715,0.492656,-0.441283,-0.073753,-0.125023,0.499210,0.021494,-0.157884,0.233714,0.041374,0.036240,-0.372383,-0.110973,-1.095345,0.036935,0.014781,0.012351,-0.478949,0.330404,0.014818,0.203874,0.332770,0.041010,0.035227,0.371592,0.470528,0.306853,-0.415076,0.120358,-0.224427,0.125330,0.665410,-0.196814,-0.474584,0.012088,0.189832,-0.547999,-0.115888,-0.358455,-0.265351,-0.030876,0.190561,0.204324,0.053540,0.452061,-0.749651,-0.013986,-0.566094,-0.389973,0.062758,-0.330761,-0.290659,-0.765539,-0.124350,0.073655,-0.087177,0.026012,0.263927,-0.325701,0.539143,-0.585563,0.374169,0.408328,0.164253,-0.156320,0.368967,-0.149439,0.150805,-0.152303,-0.031464,0.521244,0.084496,0.448429,0.323707,-0.000656,-0.276562,-0.110685,-0.436975,0.387493', '26759819', '26759820', '3861846', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7051806', '灰影人', '动作', '《灰影人》由Netflix和AGBO合制，剧情讲述人称“灰影人”的寇特·詹特利（瑞恩·高斯林 饰）为中情局效命，特务代号“山岭六号”。上线唐纳德·菲茨罗伊（比利·鲍伯·松顿 饰）当初将他弄出联邦监狱，让他成为局里钦点的精锐死亡佣兵。如今风水轮流转，六号反倒沦为头号目标，中情局前同事洛伊德·汉森（克里斯·埃文斯 饰）为了铲除他，无所不用其极地发动全球围攻，特工达妮·米兰达（安娜·德·阿玛斯 饰）却总能在他千钧一发之际伸出援手。', '瑞恩·高斯林', '安东尼·罗素', 6.6, 33873, 'tt1649418', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2873535079.jpg', 2.4, 12.4, 46.7, 28.4, 10.1, '0.210486,-0.051135,-0.518691,0.439134,0.277442,-0.376964,0.497221,0.316208,-0.380438,-0.370260,0.182445,0.226641,-0.086489,-0.065628,0.648402,0.268959,-0.514763,-0.556858,0.028032,-0.256746,-0.176064,-0.428946,-0.395689,-0.561576,0.031408,-0.132877,0.516512,-0.002195,-0.093458,0.162491,0.425193,0.760949,0.135062,0.081662,0.236909,0.090405,0.430936,-0.500838,-0.393315,0.042968,-0.284652,-0.270280,-0.246164,0.074352,0.133247,0.393360,0.400020,-0.171283,0.560922,-0.474231,0.030046,-0.512921,0.176077,-0.298814,0.171271,-0.210128,0.056153,0.213043,0.154670,0.121185,0.082146,-0.173257,-0.559569,0.326825,0.103844,0.010129,-0.265420,0.019642,-0.573164,0.498815,0.056923,-0.296888,-0.134669,0.133074,0.266548,-0.067654,-0.009340,0.203367,-0.425547,0.092321,0.307462,-0.213461,-0.211521,-0.185403,0.136771,-0.222828,-0.073632,0.012156,-0.149550,-0.265427,0.537062,-0.124182,0.422833,0.441296,-0.358351,-0.371825,-0.551829,0.176067,-0.070771,-0.262198,-0.090123,-0.784320,0.220512,0.005884,-0.310376,0.008934,-0.147961,0.061104,0.348307,-0.404364,0.003127,0.517532,0.227684,-0.075103,0.414192,-0.042794,0.248505,-0.528994,-0.219039,0.304389,0.655654,0.279266,0.287829,0.060716,-0.056548,-0.154194,0.133656,0.089649', '6517421', '2369549', '3878157', '3068206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7051830', '佩小姐的奇幻城堡', '剧情', '杰克（阿萨·巴特菲尔德 Asa Butterfield 饰）的爷爷自杰克还小的时候，就会常说床边故事给他听，故事中有许多拥有特殊能力的小孩。爷爷神秘死亡后，留下了关于这个属于另一个时空世界种种谜团的线索，杰克循着这些线索，进入了这个神秘的世界，发现这群奇怪的孩子真实存在，他们住在这里是为了躲避可怕的变异怪兽。随着杰克的到来，危险也同时抵达，杰克需要与这群孩子一起，抵御黑暗力量。', '阿萨·巴特菲尔德', '蒂姆·波顿', 7.2, 186960, 'tt1935859', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2398173791.jpg', 0.5, 4.7, 42.3, 40.8, 11.7, '0.298900,0.333689,-0.792284,0.365820,-0.388867,0.119852,0.921055,-0.315987,-0.640975,-0.592242,-0.041154,0.599444,0.174383,0.154701,-0.031194,0.093095,-0.421768,-0.298654,0.070525,-0.254735,-0.420022,-0.547540,-0.612953,-0.212639,0.037297,-0.592440,0.299840,0.174660,-0.275196,0.190992,0.155370,0.416716,-0.591872,0.457228,-0.407304,0.132420,0.099081,-0.086929,-0.426588,0.188116,0.035922,0.443457,0.100805,0.227243,-0.314922,0.107830,0.473913,-0.530209,-0.302552,-0.162560,0.183638,-0.065191,-0.098481,-0.011142,0.394513,-0.011142,0.350163,0.037462,0.204178,0.056563,-0.122868,0.143580,-1.033101,0.021615,0.058367,0.398901,-0.208685,-0.262563,0.097445,-0.393292,0.326042,-0.353389,0.531166,0.278103,0.490307,0.358458,-0.212137,0.083936,-0.293815,-0.324504,0.503261,-0.367203,-0.265634,0.346303,-0.296603,-0.345896,-0.199228,0.096735,-0.268762,0.293287,0.219307,0.440971,-0.265011,0.326196,-0.678019,0.232504,-0.043971,-0.069005,-0.148686,-0.432286,-0.231411,-0.396858,-0.139746,-0.027384,-0.231359,0.126981,-0.005833,-0.273400,0.855581,-0.420126,0.589680,0.758094,0.692813,-0.262806,0.452123,-0.149035,0.290243,-0.460095,0.020408,0.341148,-0.022731,0.295790,0.074116,0.400398,0.116015,-0.219107,-0.471815,0.692531', '1308784', '3769423', '30368448', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7051900', '宿醉3', '喜剧', 'Alan（扎克·加利凡纳基斯 Zach Galifianakis 饰）已经42岁了，却还和老爸老妈住在一块，有一天他的老爸“终于”被他气死了。Alan的几个死党Phil（布莱德利·库珀 Bradley Cooper 饰）、Stu（艾德·赫尔姆斯 Ed Helms 饰）和Doug（贾斯汀·巴萨 Justin Bartha 饰）决定带着Alan去亚利桑那的一个地方给他心理治疗。四个人在路上意外被一个叫Marshall的人给劫持了。原来这一切都是Leslie Chow（郑肯 Ken Jeong 饰）惹的祸。Chow从曼谷的监狱里逃出，并且劫走了Marshall的价值四千两百万的黄金中的一半。Marshall为了找出Chow，留下了Doug，让其余三人去把Chow带回来。Alan一直和Chow有联系，三人很快和Chow见了面，为了救回Doug，Chow决定带他们三人回原来自己的家中，取回那两千一百万黄金。眼看四人历经艰辛终于把黄金拿到了手，Chow却把他们三人锁在地下室，自己一个人带着黄金扬长而去。他们是否能救回Doug，这四个人又将经历怎样一段冒险旅程？', '布莱德利·库珀', '托德·菲利普斯', 6.5, 63010, 'tt1951261', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1934760055.jpg', 1.8, 12.1, 52.6, 24.7, 8.9, '0.130463,0.104388,-0.733943,0.525062,-0.339301,-0.604576,0.883952,-0.024869,-0.409747,-0.102573,-0.049661,0.883901,-0.104798,0.057946,0.257943,0.166912,-0.371451,-0.553240,-0.028847,-0.426465,-0.584657,-0.333074,-0.348999,0.010414,0.092089,-0.046530,0.148608,0.080673,0.153445,0.613366,0.515923,0.202655,-0.162337,0.446977,-0.439164,0.293810,0.024782,-0.033759,0.050627,0.397710,0.120921,-0.369414,-0.106732,0.168315,0.117208,0.399429,0.770057,-0.185732,0.132029,0.145279,-0.154964,-0.333292,-0.184491,0.252591,0.029688,-0.129989,0.165318,0.185484,-0.678149,0.197604,0.303262,-0.104090,-0.905970,-0.002989,0.014357,-0.020523,-0.941192,0.436714,-0.074004,-0.006690,0.183837,-0.311060,0.328316,0.528956,-0.057616,0.385659,-0.143854,-0.216726,-0.825699,0.014836,0.594783,-0.467753,0.253915,0.043739,0.237617,-0.305802,-0.080198,-0.133218,-0.339231,0.016168,0.757522,0.000114,-0.210690,-0.410767,-0.819965,-0.040688,-0.375597,-0.419837,-0.047100,-0.667683,0.046670,-0.303264,0.069075,-0.337272,-0.460365,0.258946,0.058975,-0.093660,0.608314,-0.313637,0.178582,0.438236,0.419134,-0.475825,0.635725,0.059419,0.321693,-0.038416,0.139632,-0.179333,0.432953,0.636363,0.595794,0.545980,-0.109691,-0.078991,-0.539743,0.463004', '1316560', '1299932', '21619567', '1292584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7052383', '猛鬼毕业典礼', '喜剧', '一所西班牙普通学校，接连九名教师意外身亡，这里一时间人心惶惶，学校关门在即。适值此时，四处碰壁的青年教师莫德斯托（劳尔·阿雷瓦罗 Raúl Arévalo 饰）来此应聘，他拥有能看到鬼魂的能力，可是根本没人相信他说的话，他被医生诊断患有精神病和妄想症，学生们谩骂嘲笑，校长气愤烦恼，致使莫德斯托在每一所学校都待不长。来到新学校的第一天，奥德斯托就意外发现5名盘桓在学校内的学生的鬼魂。他们20年前因违反校规而关禁闭，结果死于意外的火灾。5个鬼魂多年来热和捣蛋，吓坏了老师和学生。在美丽女同事的请求下，奥德斯托决定正视眼前的一切，帮助这5个孩子超生……©豆瓣', '劳尔·阿雷瓦洛', '哈维尔·鲁伊斯·卡尔德拉', 7.1, 8881, 'tt1924273', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1324844277.jpg', 0.7, 4.7, 44, 39.1, 11.4, '0.284447,-0.162265,-0.497721,-0.030105,-0.049316,-0.182946,0.577916,-0.014102,-0.793334,-0.428890,0.033516,0.571515,-0.273035,0.306564,0.203679,-0.320905,-0.260408,-0.451383,0.027485,-0.402745,-0.355508,-0.466591,-0.119544,-0.364658,-0.008604,-0.577920,0.031199,-0.145451,0.016433,0.688030,0.170022,0.337120,0.057098,0.256907,0.011974,0.085709,0.306661,0.187268,0.122545,0.137885,-0.024379,-0.180207,-0.254178,-0.225498,0.365878,0.304154,0.443032,0.084509,-0.240845,-0.099512,0.366003,-0.287184,-0.085078,0.390698,0.607427,-0.275915,0.354330,-0.068691,-0.105447,0.045507,-0.046445,-0.048587,-0.422105,0.006690,0.177428,0.253092,-0.461116,0.563105,0.083110,-0.060367,-0.050734,-0.169285,0.034759,0.160048,0.174096,0.510741,0.090616,-0.030249,-0.289814,0.129527,0.557768,-0.300655,-0.363888,-0.030056,-0.301427,-0.275162,-0.005611,-0.069188,-0.613496,0.373440,0.085801,0.060205,-0.328797,-0.001275,-0.083598,-0.250209,-0.182904,-0.107004,-0.315515,-0.180760,-0.289157,-0.422417,0.264810,0.258689,-0.355632,0.074070,0.021808,0.067150,0.432065,-0.728074,0.312311,0.464300,0.364354,-0.501772,0.747360,0.162893,0.097759,0.026483,-0.312847,0.184691,0.353598,0.696660,0.157184,0.360109,-0.001708,-0.315083,-0.207189,0.005951', '1306544', '1302384', '22964524', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7052437', '春假', '剧情', 'Faith（赛琳娜·戈麦斯 Selena Gomez 饰），Brit（艾什莉·本森 Ashley Benson 饰）, Candy（瓦妮莎·哈金斯 Vanessa Hudgens 饰）, Cotty（瑞秋·科林 Rachel Korine 饰）四个漂亮的女孩是同一所大学的学生。春假来临，学校里有钱的孩子都结伴出游了，只有这四个怎么也凑不够旅费的女孩被困在百无聊赖的校园里。青春荷尔蒙的刺激和对春假旅行疯狂的向往让女孩们产生了通过抢劫获取旅费的方法。抢劫过后，她们踏上了前往佛罗里达海滩的旅程。在疯狂的海滩派对上，几个女孩度过了纸醉金迷的几天，并在假期临近结束时结识了一个自称Alien（詹姆斯·弗兰科 James Franco 饰）的古怪男子。Alien对几个漂亮的女孩表示出极大的亲密和兴趣，虽然令人不安，却也让几个女孩着迷。可是几个女孩不曾想到，遇到Alien，才是她们春假真正的开始。', '詹姆斯·弗兰科', '哈莫尼·科林', 5.6, 13750, 'tt2101441', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1920674860.jpg', 11.2, 28, 37.6, 17.3, 5.8, '0.342470,-0.154631,-0.661758,0.348290,-0.284898,-0.255358,0.918125,-0.180560,-0.425879,-0.208497,0.187302,0.605311,-0.566738,0.580698,0.439981,0.088049,-0.247719,-0.643065,-0.027486,-0.283750,-0.443023,-0.278017,-0.131006,0.052700,-0.056834,-0.495413,0.274351,0.081705,-0.012140,0.734959,0.404416,-0.075290,-0.205721,0.466346,-0.324178,-0.168327,0.269002,0.134496,-0.031742,0.206811,-0.049108,-0.192442,-0.320568,-0.074481,0.190351,0.271431,0.902728,-0.153401,-0.148144,0.091248,0.222984,-0.072429,-0.330368,0.166444,0.185653,-0.168820,0.265049,-0.038551,-0.090037,0.201852,0.045944,-0.158274,-0.429733,0.397559,-0.022359,0.050715,-0.587531,0.681147,0.173959,-0.440220,0.173815,-0.359147,0.082457,0.355403,0.030022,0.421632,-0.028601,0.019787,-0.418044,0.139091,0.836404,0.051748,-0.148531,0.438229,-0.280360,-0.358375,0.021862,0.064793,-0.446463,0.095911,0.221960,-0.174123,-0.113842,0.043394,-0.865498,0.274075,-0.229501,-0.256653,0.045207,-0.429392,-0.284720,-0.902562,0.213051,-0.389664,-0.451508,0.349339,0.084529,-0.203867,0.970463,-0.964910,0.212047,0.701440,0.317963,-0.427371,0.634124,0.046500,0.133411,-0.228741,-0.245575,0.237767,0.124112,0.054231,-0.068645,0.682760,-0.362402,-0.120106,-0.436073,0.623475', '3811356', '26687241', '5977789', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7054604', '变形金刚4：绝迹重生', '动作', '当年那场惨烈的芝加哥大战，汽车人虽然成功击退了霸天虎的入侵，却也让地球人对他们失去了应有的信任与尊重。由美国中情局组建的“墓风”部队对所有的变形金刚进行无差别的猎杀，一时间汽车人和霸天虎全都在地球不见了踪影。某天，居住在得州的落魄机械发明家凯德·伊格（马克·沃尔伯格 Marky Mark 饰）买回来一辆破旧的卡车车头，谁知那竟是处在休眠中的汽车人首领擎天柱。嗅到气息的墓风部队蜂拥而至，苏醒后的擎天柱救走了凯德一家，也和散落在各个角落的汽车人相继取得联系。另一方面，疯狂的人类科学家从变形金刚的残骸中获知了他们变形的秘密，并企图借此制造出人造金刚，而脱胎自威震天的惊破天正是他们的得意作品以及催命死神。新一轮的危机卷土而来，地球面临更大的灾难……©豆瓣', '马克·沃尔伯格', '迈克尔·贝', 6.7, 313642, 'tt2109248', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2187231762.jpg', 3.2, 12, 44.3, 28.4, 12, '0.200445,0.107168,-0.875779,0.561238,0.031840,-0.000599,0.888085,-0.006235,-0.447180,-0.055455,0.315803,0.728282,0.084731,-0.113944,0.227904,0.018830,-0.299455,-0.473778,-0.169508,-0.177526,-0.486430,-0.214915,-0.380365,-0.504110,0.309575,-0.499910,0.692686,0.365959,-0.194272,0.546571,0.050042,0.187637,-0.236770,0.525501,-0.300136,0.098153,-0.042950,-0.049251,-0.227724,0.080842,-0.439027,-0.209835,-0.035567,0.163459,-0.324304,0.321417,0.594160,-0.483138,0.046234,-0.095358,0.062977,-0.403282,0.031243,0.022686,0.542360,-0.074746,-0.063479,0.070138,-0.041080,0.100302,0.036483,0.199240,-0.971909,0.036592,-0.310435,0.006993,-0.549819,0.640824,-0.003828,0.227447,0.115962,-0.049718,0.432816,0.319701,0.028772,0.420679,-0.219073,0.017356,-0.676726,0.047829,0.598433,-0.234765,-0.505491,0.183544,-0.161485,-0.421380,-0.338327,-0.393651,-0.267930,-0.357482,0.598287,0.057779,-0.158261,0.306911,-0.718521,0.116962,-0.244077,-0.407226,-0.089054,-0.183213,-0.250789,-0.922695,-0.146591,-0.331574,0.051897,0.229251,0.053203,0.008331,0.823687,-0.824003,0.249985,0.509366,0.274329,-0.436483,0.476874,-0.256383,0.047399,-0.290701,-0.238083,0.215580,0.151893,0.752072,0.188526,0.253371,-0.063052,-0.096446,-0.317641,0.383998', '3005387', '25928048', '11810348', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7056398', '喜羊羊与灰太狼之开心闯龙年', '喜剧', '平静的一天，喜羊羊、沸羊羊在追逐一个神秘之人的过程中遭到了灰太狼以及恐怖的机械龙的攻击。在此之后，他们得到来自龙乐园的5个小家伙：变色龙、钻地龙、朦龙龙、七窍玲龙和轰龙龙的救助。从小龙的口中得知，龙乐园遭到机械龙无情的袭击，另一国度的危机也间接影响到了宁静祥和的青青大草原。与此同时，喜羊羊的父母也在时空旅行中遭遇意外。为了让龙乐园和青青大草原恢复原状，也为了拯救智羊羊和丽羊羊，羊村的小伙伴全副武装前往龙乐园寻找传说中的龙笛。原本打算去丈母娘家避难的灰太狼，也意外卷入了这场新的冒险之中……本片为动画片《喜羊羊与灰太狼》第4部剧场版。©豆瓣', '周笔畅', '简耀宗', 6.5, 13255, 'tt2193271', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1358037025.jpg', 7.8, 15.3, 39.9, 18.5, 18.5, '0.145049,0.199137,-0.700203,0.696177,0.182940,-0.048381,0.845503,-0.172395,-0.374295,-0.341765,0.075092,0.738278,-0.113021,0.193000,0.271877,0.047421,-0.101131,-0.287907,-0.351799,0.145052,-0.136995,0.014105,-0.457709,-0.254548,0.041825,-0.334470,0.575055,0.461629,-0.419065,0.566289,0.308285,0.368605,-0.661732,0.465388,-0.202206,0.208572,-0.100111,0.392983,0.080474,0.216392,-0.006434,-0.057814,0.126807,0.444891,-0.000446,0.177806,1.073382,-0.869797,-0.173237,-0.555882,0.255403,-0.381274,-0.130841,0.050400,0.591459,-0.253588,0.200417,0.270819,0.084159,0.499964,-0.020274,-0.106285,-0.947733,-0.012121,-0.025016,0.314449,-0.373016,0.504257,0.193103,-0.103746,0.356514,-0.107283,0.331125,0.380593,0.251803,0.390481,-0.283649,0.197842,-0.359170,0.088295,0.748645,-0.143755,-0.046881,0.186001,0.098045,-0.750285,0.071874,-0.158734,-0.081511,0.010670,0.506104,0.252412,-0.370470,0.462335,-1.254513,0.068746,-0.074784,-0.329005,-0.318930,-0.394659,-0.308352,-0.565286,0.203380,-0.404180,0.180422,0.355219,-0.027874,-0.223229,0.494596,-0.747089,0.187565,0.146399,0.249735,-0.430859,0.421627,-0.337990,0.124724,-0.352077,-0.057625,0.098040,0.249688,0.518791,0.360522,0.202481,-0.004679,-0.352191,-0.368999,0.374420', '25774050', '26290398', '5322572', '26839466');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7056414', '通勤营救', '动作', '影片将故事设定在一列通勤列车上，一位十年如一日乘坐列车上下班的商界人士麦考利（连姆·尼森 饰），偶遇一位主动搭讪的“神秘乘客”乔安娜（维拉·法米加 饰）。乔安娜为麦考利提供了一个极具诱惑性的任务——找出车上的一位乘客，即可获得一笔巨额现金作为回报。但在寻找的过程中，麦考利逐渐发现自己卷入到一场致命的危险处境中。他是否能够从这辆“恐怖列车”中成功逃脱，背后又隐藏着怎样的惊天阴谋。随着列车不断加速，真相逐一揭开......', '连姆·尼森', '佐米·希尔拉', 6.5, 67318, 'tt1590193', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2517770792.jpg', 0.7, 9.1, 59.9, 26.4, 3.9, '0.100349,0.512535,-0.343871,0.772248,0.120437,0.101998,0.775321,-0.310519,-0.270463,-0.283104,0.444633,0.692187,-0.106287,0.063969,0.589728,0.028996,-0.336600,-0.270032,0.234588,0.005513,-0.575195,-0.602737,-0.501793,-0.143715,0.085055,-0.305352,0.667555,0.307430,-0.223970,0.386283,0.360967,0.424010,-0.448681,0.320558,-0.032817,-0.097881,0.307835,-0.095597,0.029852,0.235236,-0.208802,-0.573453,-0.022980,0.082567,-0.076944,0.170336,0.703377,-0.314789,-0.018919,0.322370,0.488140,-0.177324,0.234984,-0.102927,0.033811,0.331658,0.053623,0.036217,-0.343901,0.276825,0.116204,-0.060384,-0.690069,-0.318808,-0.120020,0.095218,-0.367880,-0.070597,-0.216926,0.038179,0.175264,-0.298582,-0.044437,0.371267,0.357839,0.065757,-0.268703,0.024587,-0.497162,-0.051073,0.482405,-0.063979,-0.243530,0.383898,-0.155182,-0.368578,-0.091115,-0.193296,-0.529207,-0.174210,0.682117,0.179588,0.077438,0.207168,-0.427369,0.043820,-0.405546,-0.276796,-0.241827,-0.051264,-0.168990,-0.853538,-0.111565,-0.063759,0.209133,0.216520,-0.004942,-0.469261,0.800277,-0.351245,0.145098,0.721135,-0.043196,-0.244788,0.471580,-0.262817,0.413397,-0.257398,-0.049187,0.073015,0.326854,0.016662,-0.078763,0.364546,-0.450016,0.011447,-0.138686,0.489274', '1293433', '3318306', '1322847', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7059561', '垃圾男孩', '剧情', '拉斐尔是一个拾荒男孩，他在垃圾山每天靠筛分垃圾为生。然而一个幸运而又不幸的一天将他的世界就此改变。这天他无意拾到了一个小钱包，一个充满谜团、线索并足以改变一切的钱包。然而不久，拉斐尔和他的朋友便遭到了腐败警方的追捕，三个男孩便与警方展开了斗智斗勇的追逐。渐渐地，他们逐渐发现这里面是一个关于一位死去的男人未完成的使命，三个拾荒男孩决心接手这份使命，他们将要独自面对危机四伏的世界......', '里克森·特维兹', '史蒂芬·戴德利', 7.6, 5951, 'tt1921149', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196446497.jpg', 0.5, 2.7, 33.2, 45.6, 18, '0.317173,0.256302,-0.603728,0.534644,-0.473572,-0.355783,0.950840,0.017603,-0.322292,-0.300093,0.264949,0.980370,0.139089,0.352431,0.098207,-0.141834,-0.169060,-0.717005,-0.053899,-0.120177,-0.473535,-0.354724,-0.389593,-0.347119,-0.222559,-0.157400,0.923525,0.456297,0.103719,0.389338,0.356700,0.017228,-0.265832,0.757704,-0.455653,-0.103362,0.208435,0.101217,0.030189,0.373690,-0.113561,-0.219498,-0.163807,0.323684,-0.456067,0.301353,0.912457,-0.308258,-0.343432,-0.248880,0.356829,-0.408734,-0.392748,0.144292,0.423877,-0.006971,-0.152640,0.323940,-0.235644,-0.328266,0.241183,-0.047984,-0.751476,-0.339536,0.006154,0.246711,-0.519021,0.381285,-0.055236,0.112961,-0.033410,-0.500430,0.213425,0.349446,0.331500,0.343859,-0.340620,-0.070060,-0.584385,0.185857,0.608913,-0.235573,-0.248389,0.536126,-0.010368,-0.447985,-0.066140,0.013180,-0.565182,0.132312,0.508546,0.098939,-0.572493,0.133275,-0.803387,0.114715,-0.546707,-0.376285,-0.113186,-0.548543,-0.151832,-0.375943,-0.149722,-0.049717,-0.367842,0.358482,-0.047815,-0.158939,0.969245,-0.558429,0.315413,0.789050,-0.114362,-0.550059,0.551674,-0.018251,0.380308,-0.423681,0.238340,0.209616,0.160088,0.339609,0.112194,0.453415,-0.185133,0.091272,-0.481644,0.514869', '21619567', '1467779', '24879819', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7059671', '最佳出价', '剧情', '性情古怪的奥德曼先生（杰弗里·拉什 Geoffrey Rush 饰）是一家顶级艺术品拍卖行的鉴赏拍卖师，在他几十年的职业生涯中几乎从未失手，他最大的爱好就是收藏各种时期的女人肖像画。比利（唐纳德·萨瑟兰 Donald Sutherland 饰）帮助他用低价拍到心仪的画作，而年轻人罗伯特（吉姆·斯特吉斯 Jim Sturgess）则帮助他用技术手段鉴定古董真伪。直到一天，一个神秘的女主顾克莱尔（西尔维娅·侯克斯 Sylvia Hoeks 饰）带着大批的古董遗产走进了他的生活，克莱尔声称患有广场恐惧症因此从不露面，但是这种特殊的交流方式却让奥德曼渐渐着迷，他甚至求助于罗伯特追求女人的方法。终于有一天奥德曼放弃了自己原有的生活，可是一个惊天的阴谋正在悄悄等待着他。©豆瓣', '杰弗里·拉什', '朱塞佩·托纳多雷', 8.4, 175953, 'tt1924396', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2039855496.jpg', 0.2, 0.9, 13.2, 51.1, 34.6, '0.231611,0.146252,-0.485922,0.658877,-0.304589,-0.285118,0.670887,0.139828,-0.562574,-0.370497,0.614419,0.718269,-0.003399,0.247869,0.257699,0.158715,-0.246595,-0.587998,0.273573,-0.168475,-0.281660,-0.343231,-0.497697,-0.422055,-0.218878,-0.406601,0.324120,-0.072423,-0.206644,0.168418,0.184013,0.501391,0.180156,0.347897,-0.169001,-0.279526,0.472139,-0.104200,-0.250393,0.115430,0.044469,-0.178232,-0.267594,0.217088,-0.128247,0.356223,0.510560,-0.432997,-0.154364,0.102297,0.274890,-0.090084,-0.011055,0.161904,0.025429,-0.110386,0.290001,0.148680,-0.271232,-0.020980,0.198945,0.029898,-0.607410,-0.068550,-0.121814,0.352612,-0.470342,0.209740,-0.222777,-0.097379,-0.108305,-0.335370,0.112056,0.158247,0.237032,0.073835,-0.225712,-0.080390,-0.411994,0.340351,0.181528,0.059958,-0.234143,0.301410,-0.331204,-0.390513,-0.043330,-0.302469,-0.660721,-0.182433,0.305545,-0.041139,-0.052435,0.090338,-0.767186,0.060918,-0.291929,-0.205939,0.133525,-0.232710,-0.081618,-0.993772,-0.032020,-0.361517,-0.173566,-0.159232,0.307198,-0.353654,0.763887,-0.516647,0.283571,0.496032,-0.018180,-0.364547,0.590887,-0.170140,-0.215623,-0.133898,-0.394162,0.324460,0.113262,0.007567,-0.174263,0.467519,0.428397,-0.202786,-0.072769,0.962193', '4924694', '34961898', '3318306', '20283482');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7062596', '长江图', '剧情', '当代，中国长江沿岸。船长高淳（秦昊 饰）在驾驶货船沿长江送货的途中，不断上岸寻找艳遇。但他逐渐发现，这些在不同的码头遇到的女人，好像是同一个人——安陆（辛芷蕾 饰）。只是随着航程的上溯，安陆时而温柔，时而疯狂，但是变得越来越年轻。高淳迷上了安陆，不断停船与她相会，也渐渐发现安陆出现的地点，都与一本未知作者的手写诗集有关。但是船过三峡之后，安陆不再出现了。高淳疯狂地寻找安陆，在诗集和航线图中，发现了安陆出现的规律。船上发生变故，但他不顾一切地独自一人驾驶货船，继续上溯长江，直到源头的雪山，终于发现了安陆的起源，和长江的秘密。', '秦昊', '杨超', 6.9, 34577, 'tt5470448', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2374818544.jpg', 2.6, 10.4, 40, 34.7, 12.3, '0.594903,-0.067587,-0.934377,0.807733,0.515298,-0.012731,0.766642,-0.040512,-0.711461,0.179995,0.024740,0.781321,-0.042775,0.140022,0.329165,-0.114304,-0.381884,-0.738987,0.276631,-0.273216,-0.409263,-0.455124,-0.275508,0.045326,0.101125,-0.199189,0.498291,0.438356,0.044314,0.810385,-0.136288,0.050441,-0.354079,0.885397,-0.481656,0.060642,-0.196034,-0.005498,0.225293,0.128977,-0.036473,-0.397378,-0.135063,-0.067388,-0.084665,0.476521,0.886704,-0.133620,-0.189531,0.132300,0.241703,-0.071404,0.077473,-0.191054,0.390463,0.286349,-0.222206,0.102774,-0.352252,-0.278324,-0.006860,0.146559,-0.116178,0.093354,0.027543,0.508232,-0.283548,-0.069387,0.165168,-0.399582,-0.077330,-0.667976,0.343480,0.435644,0.420916,0.107889,-0.306269,-0.067017,-0.578268,0.057797,0.350668,0.053892,-0.273664,0.425729,0.163483,-0.300597,0.015591,-0.073384,-0.280114,-0.098017,0.065784,0.224692,-0.273812,0.307890,-0.729938,0.240958,-0.145668,-0.528113,-0.183159,0.130508,-0.448476,-0.804144,-0.135083,-0.542090,0.215058,0.098130,-0.066951,-0.089314,0.479923,-0.602868,0.153364,0.756462,0.178983,-0.388928,0.663777,0.194879,-0.138668,-0.034112,0.114791,0.139651,0.091152,0.589089,-0.147360,0.398902,-0.201829,0.066017,-0.364632,0.685738', '34461680', '1293019', '3735015', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7064681', '狼的孩子雨和雪', '剧情', '在某国立大学念书的花（宫崎葵 配音）与偶然来校旁听的男子（大泽隆夫 配音）坠入爱河，即使对方是一名狼人，她也义无反顾投入对方怀抱。此后的岁月里，花先后生下女儿小雪和儿子小雨。谁知厄运突然降临，温柔的丈夫撒手人寰。柔弱而坚强的花竭尽全力抚养两个孩子长大，吃穿用度，衣食住行 ，无一不牵扯她的心思。而子女狼人的身份也迫使他们离开繁华大都市，前往宁静的山野乡村求生。他们在一栋古旧的民房内落脚，小雪顽劣张扬，小雨纤细内敛，姐弟俩以狼的身姿穿行于深山密林，享受着前所未有的快乐与自由。在此期间，以韭崎爷爷（菅原文太 配音）为代表的村民也给花一家带来无微不至的关怀。小雪和小雨渐渐长大，他们也终于迎来决定身份和前路的重要时刻……本片荣获第34届横滨电影节评委会特别奖和第36届日本电影学院奖最佳动画电影奖。©豆瓣', '宫崎葵', '细田守', 8.7, 122784, 'tt2140203', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1667896544.jpg', 0.2, 0.8, 11.6, 40.5, 46.9, '-0.125463,-0.007762,-0.617264,0.557485,-0.047793,-0.355372,0.607713,0.191815,-0.270816,-0.150937,0.265492,0.684701,0.122595,0.228554,0.258839,0.095871,-0.259315,-0.545578,-0.142063,0.028197,0.039239,-0.102288,-0.030463,0.056979,-0.002052,0.025088,0.767639,0.033885,0.042437,0.596436,0.240127,0.138838,-0.256965,0.183234,-0.388722,0.048218,-0.020815,0.144418,-0.356826,0.146317,-0.198035,-0.243404,-0.347637,-0.282459,0.197458,0.050363,0.846820,-0.173047,-0.251600,-0.109769,0.341941,-0.286121,-0.102717,0.123029,0.186598,-0.156557,0.371274,0.143022,-0.194383,0.225436,-0.148414,-0.420400,-0.438925,-0.005548,0.214008,-0.021222,-0.527507,0.500902,0.173217,-0.099009,0.225768,-0.302539,0.013844,0.131435,0.061479,0.440206,-0.282495,0.127729,-0.193280,0.105896,0.371796,-0.055125,-0.333719,0.264149,-0.438893,-0.445561,0.214004,-0.492099,-0.562971,0.007239,0.288151,0.106056,-0.141004,0.371800,-0.412968,0.169581,-0.070832,-0.297069,-0.054124,-0.600382,-0.199371,-0.500356,-0.077366,-0.486503,-0.297086,-0.035269,0.079936,-0.246004,0.859436,-0.676879,0.421910,0.377655,0.254795,-0.392212,0.588701,0.121077,0.247138,-0.111965,-0.073268,0.392045,-0.183507,0.289751,-0.017771,0.194138,-0.425772,0.279180,-0.341961,0.197427', '3811356', '3445516', '25922902', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7065120', '太阳马戏团：遥远的世界', '奇幻', '少女在马戏团里迷上了帅气的空中飞人，两人双双跌入太阳马戏团的奇幻世界，开始了一段奇妙的旅程。他们置身于如梦幻遥远国度美轮美奂的场景中，穿越不同的马戏世界，历经重重的困难，寻找彼此。', 'Erica Linz', '安德鲁·亚当森', 8.1, 5578, 'tt1792647', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1785646766.jpg', 0.8, 3.4, 20.7, 42.4, 32.7, '0.492163,0.350034,-0.846401,0.333476,0.108176,0.286625,1.040620,-0.197216,-0.626679,0.401393,0.365959,0.956126,-0.791938,0.231814,0.764033,0.340060,-0.364575,-0.921916,-0.156771,-0.367839,-0.047125,-0.223383,-0.758895,-0.105314,0.099883,-0.559224,0.658917,0.680975,-0.152888,0.447482,-0.356497,-0.115861,-0.971364,0.302767,-0.510171,-0.042136,0.338104,0.659039,-0.532537,0.148393,-0.387287,0.117128,-0.161539,0.043075,-0.454342,-0.026654,0.970237,-0.572246,-0.359676,-0.232983,0.587249,0.144736,-0.567882,-0.008445,0.205779,0.339377,-0.009962,-0.402145,0.310763,0.099116,0.052367,-0.688734,-0.376318,0.166892,0.427486,0.265067,-0.199451,0.498942,0.568309,-0.354533,0.180004,-0.121214,0.320574,-0.282162,1.101478,0.878425,0.293018,-0.113237,-0.105089,0.659875,1.011373,0.249772,-1.103240,0.893861,-0.520108,-0.160705,-0.431857,0.190346,-0.521413,0.192104,0.763817,-0.058637,-0.502854,0.526324,-0.974178,0.630157,-0.007996,-0.172433,-0.586138,-0.439453,-0.602575,-0.495735,-0.242902,-0.368686,0.186241,0.061924,-0.215192,-0.115265,0.549871,-0.522448,0.563954,0.634549,0.000611,0.391987,0.931277,-0.380009,-0.044662,-0.472547,0.456374,0.571505,-0.572685,0.354814,-0.085535,0.556537,-0.694544,0.591985,-0.843601,0.672632', '26689198', '20451118', '26263443', '25710797');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7065154', '银河护卫队', '动作', '彼得·奎尔（克里斯·帕拉特 Chris Pratt 饰）是一名从小被劫持到外太空的地球人，在义父勇度（迈克尔·鲁克 Michael Rooker 饰）的培养下成了一个终极混混，自称“星爵”。一次行动中他偷了一块神秘球体，便成为了赏金猎人火箭浣熊（布莱德利·库珀 B radl ey Cooper 配音）、树人格鲁特（范·迪塞尔 Vin Diesel 配音）的绑架目标，而神秘的卡魔拉（佐伊·索尔达娜 Zoe Saldana 饰）也对神秘球体势在必得。经过笑料百出的坎坷遭遇，星爵被迫和这三人，以及复仇心切的“毁灭者”德拉克斯（戴夫·巴蒂斯塔 Dave Batista 饰）组成小分队逃避“指控者”罗南（李·佩斯 Lee Pace 饰）的追杀。然而这个神秘球体拥有无穷的力量，小分队必须团结一致对付罗南，才有可能解救整个银河系，银河护卫队由此诞生。©豆瓣', '克里斯·帕拉特', '詹姆斯·古恩', 8.1, 481497, 'tt2015381', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2198455702.jpg', 0.5, 1.8, 19.7, 48.7, 29.4, '0.105346,0.056953,-0.566445,0.606065,-0.066813,-0.131411,0.658921,0.034705,-0.199543,-0.193182,0.296683,0.413829,-0.051526,0.060111,0.459616,0.191638,-0.204995,-0.370408,0.150424,-0.173626,-0.408407,-0.418708,-0.598633,-0.377583,0.074835,-0.370881,0.709344,0.106388,-0.259067,0.282515,0.467427,0.703546,-0.075209,0.056516,0.022553,0.003287,0.360657,-0.222859,-0.076446,0.103725,-0.428678,-0.067642,-0.050629,0.158093,-0.074347,0.323091,0.426795,-0.417174,0.365451,-0.410764,0.174361,-0.403262,0.014541,-0.226750,0.430076,-0.165576,-0.095504,-0.160120,0.131158,0.113824,0.140380,-0.270418,-0.822381,-0.131030,0.109081,0.240988,-0.402659,0.025115,-0.105964,-0.051065,0.145024,0.029350,-0.144645,0.119310,0.311345,0.107818,-0.027461,0.011711,-0.369472,-0.100750,0.244216,-0.094111,-0.456412,0.073730,-0.041488,-0.364659,-0.165870,-0.143513,-0.370439,-0.013733,0.532915,0.065943,0.250628,0.303560,-0.763030,-0.150536,-0.441885,0.133603,-0.112529,-0.296695,0.023212,-0.741473,-0.085522,-0.122272,-0.099016,0.165864,-0.087034,-0.076027,0.589807,-0.401427,0.241991,0.396886,-0.031026,-0.353379,0.213834,-0.077716,0.162582,-0.556920,0.070567,0.282568,0.362828,0.113959,0.013300,0.275747,0.175650,-0.006423,-0.006150,0.408010', '1293433', '3318306', '1308585', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7065161', '鸣梁海战', '剧情', '1597年的朝鲜王朝危机四伏，朝鲜海军主力随着大将李舜臣（崔岷植 饰）被贬而遭受巨大打击，军纪溃散，只剩少量军舰。而倭寇伺机派出胁坂安治（赵震雄 饰），协同令人闻风丧胆的“海贼王”来岛通总（柳承龙 饰）的海盗军共同出击，势必攻克汉阳。危急关头，李舜臣力排众议，决定率领仅 剩的十几艘军舰前去鸣梁海峡迎战倭寇。李舜臣先是派遣部下任俊永（晋久 饰）去敌方汇合卧底俊沙（大谷庆彦 饰），又重振军心，以“勇者生，畏者死”的气概，号召与倭寇决一死战。 决战开始，李舜臣身先士卒，死守血岛，击溃“海贼王”好几拨先遣军，关键时刻任俊永的哑妻（李贞贤 饰）读懂他的唇语发挥作用，使得李舜臣将船成功获救。最终军民协力，重创了日本舰队，创造了世界海战史上一次以少胜多的著名战役。©豆瓣', '崔岷植', '金汉珉', 7.2, 56016, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2213003660.jpg', 1.8, 5.8, 38.9, 39.9, 13.7, '-0.359126,-0.025851,-0.586329,0.538147,0.472683,0.222979,-0.021429,0.158576,-0.193984,0.109624,0.439567,0.413072,0.492804,-0.561894,0.262772,-0.440789,-0.136236,-0.690075,0.004051,0.063495,-0.071803,-0.134885,-0.383696,-0.267546,0.224734,-0.308648,1.098174,0.498262,-0.182117,0.594360,0.104299,0.390552,0.147805,0.407651,0.228868,0.076122,-0.180217,-0.569146,-0.253291,0.085406,-0.643942,-0.300731,-0.183115,-0.023246,-0.168946,0.380411,0.747119,-0.601924,0.367174,-0.389804,-0.173705,-0.320209,-0.029077,-0.025062,0.413134,0.387081,-0.233796,-0.013783,-0.011961,0.060423,-0.064132,0.192216,-0.392813,-0.283801,0.081780,-0.254623,-0.217054,0.343843,-0.196210,0.311860,0.306719,0.054595,-0.075016,0.817984,0.397552,-0.077107,-0.186602,0.344687,-0.401125,0.321544,0.610628,-0.420393,-0.058040,-0.592453,0.459621,-0.256389,0.118699,-0.825366,0.063081,0.060303,0.246638,-0.352144,0.418944,0.115716,-0.590182,-0.133679,-0.724683,-0.208461,0.145171,0.041605,0.171890,-0.649274,0.135883,0.157210,0.034137,0.630467,0.291614,0.461875,0.676834,-0.234979,-0.241868,0.504145,0.326191,-0.504878,0.257508,0.435610,-0.158768,-0.147360,0.221028,0.434227,0.131629,0.353864,0.369390,-0.019011,-0.369556,-0.129624,-0.223865,-0.124642', '1424551', '3074408', '1422938', '26852888');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7065187', '不惧风暴', '动作', '故事背景设定在一个名为西弗敦的小镇，在同一天中，史无前例的多个龙卷同时席卷这个小镇，在这些难以预测且极度致命的龙卷风群袭击下，整个小镇面临灭顶之灾。但专门研究龙卷风的追风人预测，更糟糕的情况还尚未真正到来。大多数居民都在紧迫寻找避难所，而这些追风者们却“逆向而行”赶到龙卷漩涡前，测试需要走多远才能拍到这千载难逢的极端时刻。', '理查德·阿米蒂奇', '史蒂文·奎里', 6.7, 26130, 'tt2106361', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2196783192.jpg', 1.1, 8.4, 51, 31.3, 8.3, '0.068172,-0.142419,-0.883937,0.567710,0.211519,0.506172,0.753840,0.016219,-0.302628,-0.501931,0.573876,0.461724,-0.141382,-0.117993,0.224972,-0.451509,0.119175,-0.226661,-0.175554,-0.300930,-0.757950,-0.122760,-0.481390,-0.187378,0.062269,-0.218331,0.752716,0.462325,-0.290173,0.150641,-0.068469,0.347995,-0.357148,0.756197,-0.666017,-0.128677,-0.049112,0.167389,-0.183240,0.251173,-0.425940,-0.128815,-0.142522,0.352667,-0.148523,0.260705,0.739175,-0.449465,-0.237870,0.044292,0.396823,-0.605286,-0.054692,-0.008830,0.622356,-0.355177,0.200126,-0.235652,-0.078999,0.088946,-0.417535,-0.302450,-1.050001,0.030036,0.204367,0.220821,-0.511649,0.011248,0.191407,-0.182375,-0.033787,-0.237530,0.030859,0.609096,0.076499,0.359684,-0.264767,-0.073024,-0.303296,-0.092606,0.841314,-0.047952,-0.839951,0.307575,-0.297508,-0.159706,-0.090400,0.081205,-0.176975,-0.306644,0.351414,0.367636,-0.302694,0.242128,-0.649480,0.550583,-0.214971,-0.338481,-0.159471,-0.440155,-0.557542,-1.066823,0.018114,-0.266787,-0.189275,0.358612,0.107007,0.124479,0.662391,-0.613521,0.307307,0.805928,0.118553,-0.371077,0.337128,0.087975,0.208254,-0.169554,-0.210016,0.070527,0.088091,0.687142,-0.318200,0.385902,-0.046751,-0.216096,-0.451491,0.557775', '2369613', '1308784', '25928048', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7065211', '怒海救援', '动作', '故事发生在一艘正在失望波士顿的游轮上。半路上，邮轮遭遇了猛烈的风暴袭击，最终导致了抛锚。船只产生了裂缝，大量的海水开始渗入船体内部，如果不加以控制的话，整艘邮轮都将有沉没的风险。雷（卡西·阿弗莱克 Casey Affleck 饰）是船上职位最高的船员，这也就意味着，他对于船上30名船员的生命有着不可推卸的责任。经验丰富的雷决定不坐以待毙，而是带领船员们展开了自救行动。与此同时，马萨诸塞州海岸警卫队收到了邮轮发出的求救信号，派出了救援队进行搜救，伯尼（克里斯·派恩 Chris Pine 饰）是搜救队的队长。在他的带领之下，四名队员驾驶着一艘非常简陋的木质救生船驶进了茫茫大海中。©豆瓣', '克里斯·派恩', '克雷格·吉勒斯佩', 7.4, 19415, 'tt2025690', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2560630512.jpg', 0.5, 3.5, 37.6, 44.3, 14.1, '0.357103,-0.027716,-0.881196,0.584794,0.140404,0.079624,1.051363,0.131092,-0.540236,0.143554,0.442510,0.699066,0.273731,-0.064715,0.278662,0.089314,-0.623832,-0.452910,-0.381209,0.000213,-0.686078,-0.765865,-0.037591,-0.156235,0.221187,-0.479773,0.622361,0.494873,-0.224763,0.390211,0.291649,0.294033,0.047692,0.758250,-0.179054,-0.035075,0.097330,-0.249809,0.366408,0.026245,-0.424960,-0.286795,0.298237,0.052096,0.241144,0.597426,0.868940,-0.285793,0.010737,-0.147408,-0.141964,-0.468522,0.498026,-0.106280,0.648787,0.203285,-0.429319,0.126838,-0.177428,-0.062481,0.041725,0.321830,-0.640561,-0.095542,-0.037547,0.118343,-0.690990,0.033628,-0.272503,0.009274,-0.082696,-0.088151,0.085990,0.223710,0.049557,-0.047659,-0.235010,0.060884,-0.743747,-0.060571,0.766410,-0.050735,-0.343697,-0.077890,-0.341373,-0.373673,-0.303388,-0.275802,-0.122788,-0.433175,0.575525,0.157803,-0.001166,0.058354,-0.571487,0.283199,-0.260001,-0.842189,-0.508391,-0.137391,-0.135087,-1.017553,0.387210,-0.145162,-0.038189,0.385068,-0.022447,0.152618,0.726566,-0.452097,0.087400,0.644173,0.078873,-0.312524,0.614932,0.091049,0.161603,-0.055457,0.366440,-0.057365,-0.082807,0.523576,0.181329,0.364075,0.024540,-0.180992,0.006925,0.171985', '3011051', '10466639', '2159244', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7065238', '魔发精灵', '动画', '波比（安娜·肯德里克 Anna Kendrick 配音）是精灵城的公主，她有着神奇的魔力和多彩的头发，乐观积极、喜爱唱歌。但是有一天，他们的小伙伴被死对头——“博啃族”抓走了。为了从“博啃族”手中拯救出她最好的朋友们。波比向精灵城中的“怪人”布兰（贾斯汀·汀布莱克 Justin Timberlake 配音）求得帮助，可布兰是个不合群的悲观主义者。他虽答应了公主的请求，但是他只是想让公主知道这个世界并不像她想的那样只有蛋糕和彩虹。一路上，他们共同经历了很多奇怪、有趣的事，也发现了自己内心以前从未发觉的东西。但是最重要的是，在波比的帮助下，他们发现了能够拯救整个魔发精灵城的终极秘密武器。©豆瓣', '安娜·肯德里克', '迈克·米切尔', 7, 25396, 'tt1679335', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2497523370.jpg', 1.3, 7.2, 44.2, 35.4, 11.8, '0.473149,0.151958,-0.556375,0.639888,-0.226733,0.012060,0.883489,-0.197097,-0.773614,-0.227483,0.115220,0.720076,0.084929,0.184949,0.261773,0.309705,-0.345971,-0.483284,0.199345,-0.228884,-0.313347,-0.478096,-0.241019,-0.336164,-0.216621,-0.630731,0.361884,0.249911,0.018258,0.243340,0.313758,0.141955,0.144182,0.553252,-0.069599,-0.062598,-0.005757,0.089371,0.078669,0.319301,0.030314,0.009262,-0.291073,0.606486,0.109815,0.349374,0.142841,-0.501264,-0.206253,-0.088473,0.314682,-0.360842,0.117851,0.138272,0.217786,-0.263805,0.391241,-0.192075,0.110771,-0.140820,0.097647,-0.198275,-0.826018,0.122588,0.150955,0.136980,-0.857302,0.181103,-0.063060,-0.251343,0.260588,-0.370029,0.277487,0.427113,0.351019,0.226218,-0.117758,-0.135308,-0.652446,0.169912,0.892893,0.133327,-0.236472,0.263834,-0.510451,-0.698945,-0.308369,-0.304010,-0.495816,0.259481,0.262661,0.152940,-0.200611,0.248351,-0.591509,0.033176,-0.073077,-0.148098,0.044318,-0.731031,0.098010,-0.228153,-0.041208,-0.505962,-0.272431,0.039854,0.065289,-0.530792,0.974600,-1.285290,0.113787,0.644450,0.393702,-0.535644,0.748402,0.133784,-0.211355,-0.066309,0.053470,0.030025,0.126739,0.140025,0.184045,0.469100,0.434991,-0.375720,-0.449096,0.427122', '35030151', '1877596', '1303112', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7065334', '金矿', '剧情', '该片是根据臭名昭著的1993年Bre-X金矿公司诈骗案创作的。Bre-X金矿公司是一家在地下室里建立的加拿大金矿公司，1989年7月在亚伯达省证券交易所上市，当时只是每股约25分的垃圾股。后来该公司买下了印尼矿山的开采权，通过往岩石中掺金粉的做法，他们营造了该矿山的矿石含金量极高的假象，该公司股票的价钱于是如脱缰野马，至1996年4月，他们的股价已飞飙至200元。1996年10月，Bre-X金矿公司诈骗的行径遭到曝光，但成千上万的股民的资产早已落入了该公司创始人、地质师等人的腰包里。《金矿》的故事讲述了马修·麦康纳饰演的现代勘探家肯尼·威尔斯渴望开探到一块大矿。在这个梦想指引下，威尔斯协同一个同样运气欠佳的地质学家进行了一次孤注一掷的探险——去往印度尼西亚一片未知的雨林深处寻找金矿。布莱丝·达拉斯·霍华德将饰演麦康纳角色的女朋友凯，凯始终支持男友的勘探事业，但是两人的关系在这次寻找金矿的过程中受到了严峻的考验。', '马修·麦康纳', '斯蒂芬·加汉', 8.2, 41301, 'tt1800302', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2377261921.jpg', 0.1, 0.9, 16.7, 53.7, 28.5, '0.055643,-0.100203,-0.610975,0.414574,0.058838,-0.163503,0.289743,0.216229,-0.576703,0.011860,0.239293,0.489136,-0.111270,0.103181,0.187327,0.195808,-0.298924,-0.379685,-0.137729,-0.639870,-0.144096,-0.527880,-0.314249,-0.200403,-0.193436,-0.071717,0.667996,0.408685,-0.000860,0.128597,0.035576,0.266528,-0.016360,0.235600,0.056505,-0.128532,0.288313,0.054164,-0.454729,0.390191,-0.075497,-0.089732,-0.063154,-0.075879,0.451409,0.625822,0.574830,-0.006151,-0.019665,0.059264,0.480350,-0.137479,0.012939,-0.342252,0.506739,0.122158,0.125527,0.422831,-0.472628,-0.207526,0.136354,-0.582718,-0.709373,-0.183314,0.249487,0.132433,-0.641287,0.313919,0.003068,0.285966,-0.247136,-0.241531,0.087823,0.502030,0.195568,0.433255,-0.150339,0.054517,-0.635240,0.353106,0.369080,-0.152012,-0.140329,0.355486,-0.039417,-0.484326,-0.258819,-0.199405,-0.253513,-0.131132,0.367930,0.100383,-0.229662,0.215070,-0.839130,0.044039,-0.117640,-0.459132,0.223758,-0.204567,-0.256312,-0.642867,-0.184416,-0.234391,0.109666,0.100237,0.093012,-0.145161,0.493477,-0.532295,-0.106944,0.711094,0.434974,-0.430964,0.613081,-0.463393,-0.024909,-0.291797,-0.119888,0.084260,0.089100,0.167639,-0.007794,0.188748,0.090875,-0.486780,-0.24844