INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7065417', '天降美食2', '喜剧', '一度平静的斯沃罗夫小岛被弗林德·洛克伍德（比尔·哈德 Bill Hader 配音）的天才发明复食机所摧毁。最终他成功破坏复食机，并打算和山姆（安娜·法瑞丝 Anna Faris 配音）他们重建美好家园。这时候，弗林德最崇拜的偶像——丽芙公司老板切斯特 V（威尔·福特 Will Forte 配音）从天而降。切斯特是一个天才发明家，他的公司更是云集了全世界顶尖的科学家。切斯特邀请弗林德加入丽芙公司，并承诺带着岛民前往加利福尼亚，而他的公司将负责清理破败的小岛。为了成为幻想发明家，弗林德拼尽全力开展研发。与此同时，故乡却传来不好的消息。许多清理者被活着的食物所捕获，似乎复食机并未完全摧毁，并且朝着弗林德不曾预料的方向继续发展。在切斯特的命令下，他和山姆、老爹以及其他伙伴们踏上了返乡的旅途，寻找解决麻烦的办法……©豆瓣', '比尔·哈德尔', '科迪·卡梅伦', 7.3, 46103, 'tt1985966', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2162737378.jpg', 0.6, 4.7, 37.9, 40.4, 16.4, '0.234036,0.072109,-0.478030,0.398974,-0.074364,-0.234847,0.535290,0.133345,-0.270204,-0.283605,0.153094,0.617289,0.196830,0.060874,0.396463,0.050555,-0.472959,-0.364408,0.119086,-0.164506,-0.066133,-0.571264,-0.087832,-0.302093,-0.125669,-0.359682,0.817884,0.067763,-0.248469,0.349655,0.048536,0.420692,-0.187821,0.530591,-0.001812,-0.053404,0.386207,-0.321003,-0.474145,0.231327,-0.281437,-0.016821,-0.071723,0.243310,0.035714,0.204609,0.287422,-0.128796,0.079032,-0.302755,0.034347,-0.326412,0.288202,0.117004,0.142398,-0.055591,0.141659,0.333544,-0.082293,-0.197781,0.111928,-0.192991,-0.931766,0.102040,0.160405,0.128987,-0.554160,0.066837,-0.020632,0.076679,0.013647,-0.301657,0.173852,0.328374,0.172653,0.193088,-0.215156,0.447098,-0.438511,0.185428,0.604739,-0.184608,-0.159869,0.167093,0.086469,-0.098072,0.033549,-0.176906,-0.452754,-0.051013,0.301297,0.295700,-0.046327,0.252175,-0.537280,-0.005664,-0.511794,-0.773969,0.110919,-0.364208,-0.053363,-0.966582,0.246992,0.111082,-0.217475,-0.159985,0.040864,-0.224189,0.770268,-0.791895,-0.019044,0.456987,0.372118,-0.490882,0.358854,-0.142157,0.171502,-0.273719,-0.311471,0.409656,0.133858,0.500674,-0.033877,0.263826,0.129410,-0.464824,-0.430955,0.568682', '2369613', '3318306', '1793491', '5910040');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7152895', '听说桐岛要退部', '剧情', '松籁第一高等学校，星期五放学后的闲暇时光，一股不安的气氛在校园肆意蔓延。传言排球部明星球员桐岛退部，他的举措使稳固的校园金字塔发生不小的撼动。黄昏的校园内，排球部的众人、羽球部的东原霞（桥本爱 饰）、桐岛的女友——校园美女梨纱（山本美月 饰）以及他的密友菊池宏树（东出昌 大 饰）莫不感到诧异，他们四处寻找桐岛的身影，最终一无所获。在这片混乱中，生活在金字塔最底层的电影部部长前田凉也（神木隆之介 饰）以及管乐部部长泽岛亚矢（大后寿寿花 饰）似乎并未受到太大的影响。身处校园夹缝中的他们默默从事本部活动，默默深藏心中对某个人的爱慕。不到一周的时间，少男少女的内心发生巨大的变化……本片根据朝井リョウ的同名处女作改编，并荣获2012年电影旬报十佳影片第二名，以及2012年日本电影金像奖最佳影片、最佳导演、最佳剪辑等奖项。©豆瓣', '神木隆之介', '吉田大八', 7.9, 36974, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1591938486.jpg', 0.6, 2.6, 22.5, 48.3, 26, '0.026652,-0.095074,-0.667167,0.496586,0.638485,0.058272,0.644475,0.288613,-0.502398,-0.477147,0.287191,0.450417,-0.658904,0.135372,0.313409,-0.175058,-0.386449,-0.803044,-0.320510,-0.190001,0.170166,-0.207157,-0.181066,0.033647,-0.235547,-0.117105,1.072875,0.185522,-0.197776,0.601760,0.197054,0.077945,0.012797,0.131888,0.265745,0.127619,0.262938,0.112429,-0.128322,0.033719,-0.106868,-0.400595,-0.299702,0.047456,0.213086,0.197101,0.835747,-0.124745,-0.185275,0.115412,0.514451,-0.108578,-0.198509,-0.040015,0.521238,-0.028608,0.120302,0.106212,-0.196883,0.255881,-0.118608,-0.197148,-0.388605,-0.096604,0.233118,0.345771,-0.076671,0.587370,0.107633,-0.238625,0.361712,-0.127262,-0.034539,0.106065,0.277431,0.253316,-0.243301,0.126965,0.073479,0.415150,0.401912,-0.058858,-0.435695,0.218883,-0.410631,-0.476201,-0.502985,-0.242686,-0.576321,0.035021,0.113745,0.179002,0.121357,0.235771,-0.401222,0.074165,0.159061,-0.471814,-0.048381,-0.281107,-0.121211,-0.930547,-0.003161,-0.333070,-0.027475,0.058521,0.177125,-0.056544,0.699983,-0.792945,0.206469,0.554723,-0.013248,-0.057071,0.593770,-0.079267,-0.112081,-0.270660,-0.374110,0.211507,-0.072505,0.525004,-0.056872,0.379456,-0.304520,-0.393080,-0.454655,0.055276', '3266509', '1322847', '2369613', '20274039'