INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7152908', '火影忍者剧场版：忍者之路', '剧情', '刚刚结束了与叛忍集团“晓”的抗争，木叶村被一股诡异不祥的气氛所笼罩。此时此刻，漩涡鸣人（竹内顺子 配音）沉浸在对家人的思念中，孤独无助。某个晚上，心情糟糕的鸣人巧遇刚刚和家人吵架的小樱（中村千绘 配音），二人在公园闲聊之际，神秘的斑（内田直哉 配音）突然出现，并向二人使出瞳术。眩晕过后，鸣人和小樱发现看似一如平常的木叶村，曾经熟悉的伙伴竟然性格发生巨变。一连串不正常的事件令二人苦恼不已。更令人难以置信的是，包括佐助以及鸣人的父母波风水门（森川智之 配音）和玖辛奈（篠原惠美 配音）也出现在他们的面前。斑的阴谋慢慢展开……本片根据岸本齐史的漫画原作改编，为该作品第九部动画剧场版。©豆瓣', '竹内顺子', '伊达勇登', 7.9, 15665, 'tt2290828', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2244537600.jpg', 0.8, 3.1, 23.6, 44.2, 28.3, '0.258578,-0.025103,-0.535591,0.532531,0.491995,-0.147384,0.602729,0.295403,-0.346153,-0.692722,0.125776,0.645511,-0.377411,0.457653,0.195268,-0.024452,-0.145419,-0.762823,-0.555943,-0.034320,-0.134503,-0.242899,0.152683,-0.037630,-0.208794,-0.247412,0.746488,0.149682,-0.290293,0.535307,0.150414,0.540591,-0.729847,0.413709,0.290902,0.158093,0.057211,0.102431,-0.249597,-0.159005,0.048138,-0.104483,-0.277183,0.177047,-0.080763,0.215087,0.928963,-0.247646,-0.553638,0.046431,0.436826,-0.142298,-0.370130,0.095560,0.330690,-0.037275,0.181800,0.067317,-0.015822,-0.015739,-0.220776,-0.037707,-0.754043,0.368526,0.036013,0.255368,-0.114915,0.274571,0.032113,-0.188459,0.548107,-0.300086,0.196165,0.252109,0.450383,0.576377,-0.442799,0.184864,0.168259,0.010093,0.642795,0.032359,-0.349601,0.490563,-0.163006,-0.157622,-0.331923,0.073174,-0.250409,0.075820,0.154649,0.204976,-0.057719,0.432035,-0.713075,-0.017482,0.056393,-0.030126,0.055570,-0.360516,-0.172876,-0.929253,-0.292252,-0.328814,-0.341928,0.215938,0.019723,-0.265571,0.618851,-1.001475,0.099395,0.436588,0.127642,0.122687,0.193519,-0.033048,-0.256117,-0.180815,-0.251320,0.047119,0.025274,0.112702,0.298216,0.368313,-0.006869,0.123756,-0.544778,0.248843', '2369613', '20274039', '5403927', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7154408', '猎杀星期一', '科幻', '故事设定在近未来，由于人口过剩和饥荒，政府不得不实行“独生子女”政策。正因为这个严格的计划生育议程，姐妹们必须轮流使用一个人的身份Karen Settman(拉佩斯饰)。她们的祖父(达福饰)给其命名为周一、周二、周三、周四、周五、周六和周日。每个人都可以每周外出一次。姐妹们只有在自己的公寓里才可以自在生活。直到有一天，“星期一”没回家......', '劳米·拉佩斯', '托米·维尔科拉', 7.1, 38905, 'tt1536537', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2494970558.jpg', 0.9, 6.9, 41, 38.4, 12.8, '-0.072532,-0.336519,-0.921147,0.430165,-0.236107,-0.250603,0.370341,0.250306,-0.331674,-0.584101,0.208347,0.534507,-0.135264,0.655211,0.440184,-0.379083,-0.610604,-0.489406,-0.005410,-0.119285,-0.676664,-0.312206,0.330105,-0.362324,-0.170949,0.110561,0.272123,-0.182576,0.064090,0.411099,0.190482,-0.010183,-0.070386,0.421251,-0.457241,-0.430612,0.081531,-0.097157,-0.332593,0.323754,-0.141774,0.123896,-0.609222,-0.040409,0.584602,0.455176,0.580523,-0.331963,-0.374899,0.001963,0.449753,-0.163078,-0.423853,-0.007829,0.686814,-0.193554,0.698398,0.542324,-0.245941,0.345193,-0.307404,-0.539389,-0.739673,-0.020910,0.174398,-0.232196,-0.518472,0.704647,-0.167066,-0.309694,0.081270,-0.566073,0.035811,0.736582,-0.076177,0.622822,-0.047500,-0.130591,-0.345635,0.067534,0.675932,-0.114954,-0.258291,0.302591,-0.217165,-0.130934,0.149242,-0.050153,-0.325472,0.166972,0.273398,0.104349,-0.312909,0.167055,-0.640184,-0.056214,-0.046635,-0.837470,0.368515,-0.441432,0.097798,-0.570470,0.375762,-0.403966,-0.376636,0.472070,0.437777,-0.010936,0.929882,-1.023903,0.441264,0.355084,0.395350,-0.818445,0.751564,0.590629,0.576460,-0.169744,0.171520,-0.419348,-0.082051,0.707974,0.035980,0.357363,0.030862,0.137312,-0.473666,0.650211', '1296770', '10876425', '1292219', '30159456');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7154463', '珠光宝气', '剧情', '备受孤立的转校生马克（伊瑟尔·布罗萨德 Israel Broussard 饰）在新学校里遇到瑞贝卡（凯蒂·张 Katie Chang 饰），两人很快成为好友。想去纽约成为服装设计师的瑞贝卡对各种大牌服饰一直拥有超乎寻常的热情，但虚荣心让瑞贝卡开始进行小偷小摸。马克虽然曾 经试图阻止，但很快也成为了同伙。渐渐地，瑞贝卡将手伸向好莱坞明星的豪宅。她和马克研究了明星的动向后，选择他们不在家的时候破门而入进行偷窃。薇琪（艾玛·沃森 Emma Watson 饰）、科洛伊（克莱尔·茱莉安 Claire Julien 饰）等人随后也加入了这个行窃团伙。这个由三男三女组成的少年团伙行窃了包括帕利斯·希尔顿、奥兰多·布鲁姆、林赛·罗瀚等明星的居所，盗窃价值高达三百万美金。几个少男少女在纸醉金迷的虚荣和欢愉中不能自拔，但等待他们的终将是法律的制裁。本片根据真人真事与《名利场》的报道改编。', '艾玛·沃森', '索菲亚·科波拉', 5.2, 16197, 'tt2132285', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2092672267.jpg', 10.3, 35.6, 41.7, 9.8, 2.7, '0.497819,0.011958,-0.603600,0.464700,-0.012849,-0.185969,0.689904,0.141676,-0.394366,-0.255535,0.034833,0.824008,-0.367587,0.320574,0.355763,-0.011094,-0.571421,-0.783209,-0.103871,-0.311531,-0.067934,-0.431452,-0.097019,-0.101380,-0.219085,-0.180073,0.509060,-0.020585,-0.178401,0.502130,0.417002,0.418767,0.081363,0.319447,-0.177465,-0.061865,0.434182,-0.293150,-0.159315,0.325423,0.103466,-0.221338,-0.103391,0.051579,0.129111,0.341212,0.625383,-0.325746,0.066332,-0.074767,0.353588,-0.136486,0.021466,0.100679,0.270168,-0.033605,0.179672,0.090045,-0.257425,0.213575,0.058956,-0.138027,-0.809836,0.131642,0.251829,0.105076,-0.698406,0.215137,-0.146000,-0.100211,0.103715,-0.057722,0.093304,0.360852,0.277988,0.246917,0.127059,0.026836,-0.493606,0.077618,0.445863,0.064798,-0.296773,0.208022,-0.177421,-0.569524,-0.103190,-0.158558,-0.441307,-0.109095,0.402051,-0.024487,0.041171,0.027989,-0.726697,-0.002215,-0.256419,-0.320701,0.072252,-0.386730,-0.045410,-0.902049,-0.123754,-0.336983,-0.192267,-0.054618,0.098517,-0.229296,0.697430,-0.801915,0.102962,0.417835,0.363071,-0.616686,0.670233,-0.163208,0.138989,-0.114017,-0.162007,0.055710,0.197940,0.264161,0.211611,0.522231,0.094460,-0.384237,0.005364,0.348739', '4301278', '10763928', '3178770', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7155005', '游客', '剧情', '阿尔卑斯山滑雪佳地，一瑞典家庭在就餐时遇到了雪崩，丈夫托马斯只顾自己逃命不救妻孥，引发了家庭危机……一个瑞典家庭来到了法国的阿尔卑斯山区度假。当天风和日丽，景色无比养眼，然而当他们在山脚下的一个餐馆用餐时，一场突如其来的雪崩打破了这一切。游客们四处逃窜，母亲艾芭叫喊着她的丈夫托马斯的名字，试图保护他们的孩子。然而没想到的是，托马斯却在慌乱之下抛妻弃子，自顾着逃命去了……尽管最终躲过了雪崩，但这一家人的关系却出现了巨大的裂痕。托马斯究竟怎么样才能挽回妻子的心，并且在孩子们的心目中重塑他的威信？', '约翰内斯·昆科', '鲁本·奥斯特伦德', 7.4, 18920, 'tt2121382', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2207561733.jpg', 0.9, 4, 32.1, 48.2, 14.8, '0.212290,-0.068274,-0.877694,0.517215,0.059732,-0.289918,0.791562,0.359162,-0.382822,-0.333129,0.334115,0.754354,-0.233027,0.354676,0.252255,-0.050062,-0.254114,-0.506030,-0.198601,0.184670,-0.405033,-0.225507,-0.347969,-0.237950,-0.071014,-0.144881,0.297856,0.194338,-0.209563,0.272959,0.054669,-0.020582,-0.010032,0.712423,-0.336946,0.185271,0.108207,0.071268,-0.218977,0.257915,-0.074621,-0.415501,-0.444976,0.377843,-0.033279,0.470771,0.802677,-0.285385,-0.023086,-0.037379,0.267005,-0.274951,0.097759,0.239400,0.190708,-0.356281,0.025914,-0.178618,-0.269963,-0.176369,0.286972,-0.097397,-0.430853,0.119647,-0.040268,0.028756,-0.680189,0.434117,0.031123,0.032070,0.078405,-0.385450,0.369452,0.411947,0.048323,0.488985,-0.499906,0.055001,-0.700924,-0.025479,1.068078,0.071984,-0.268976,0.325435,-0.578899,-0.262965,-0.155201,-0.099222,-0.677468,-0.340562,0.567216,0.081128,-0.400842,0.289363,-0.458951,-0.055882,-0.331833,-0.307830,-0.332710,-0.458503,-0.298869,-0.487607,0.062054,-0.165674,-0.388509,0.172637,-0.232913,0.019830,0.753246,-0.629941,0.107405,0.836232,0.058185,-0.257412,0.597521,0.172234,0.309711,0.036416,-0.122014,0.201871,0.057116,0.256670,0.038189,0.315576,-0.174820,0.040109,-0.352811,0.513907', '26718282', '1297606', '1866424', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7155083', '第一次', '爱情', '宋诗乔（Angelababy/杨颖 饰）经常独自对着录音机说出自己心中的秘密。因为她患有的先天性疾病，让她无法从事任何剧烈运动，甚至还有失忆的征兆。所以，诗乔习惯了用录音机记录下自己生活的点点滴滴。同时，她也习惯了经常服用药物带来的诸多不便。看在眼里，痛在心头的母亲郑青（江珊 饰）对诗乔的关怀无微不至，母女俩相依为命，但是母亲最大的心愿就是让女儿能够体会爱情的美好。正是青春年少的诗乔，也突然发觉身边缺少一个可以分享感受的伴侣。一次偶然的机会，她在游乐场扮演卡通玩偶的时候，巧遇了引吭高歌的摇滚青年——高中同学宫宁（赵又廷 饰），后者便对她展开了爱情攻势。两人堕入爱河，这也是诗乔第一次感受爱情的美好。而宫宁也开始鼓励诗乔实现跳舞的梦想。然而，爱情从来都不会一帆风顺……©豆瓣', '杨颖', '韩延', 6.1, 70496, 'tt2296692', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1544398538.jpg', 6.6, 19, 45.6, 20.4, 8.4, '0.165491,0.031495,-0.649938,0.724382,-0.296356,-0.140866,0.824412,-0.003577,-0.580281,-0.208531,0.209681,0.638398,-0.080234,0.459922,0.220349,0.091581,0.034283,-0.759624,0.141141,0.146177,-0.332159,-0.287437,-0.203386,-0.341654,-0.150200,-0.300893,0.524083,-0.019153,-0.328891,0.532111,0.310713,0.068949,-0.023281,0.653991,-0.203169,-0.060053,-0.155811,0.271029,-0.296868,-0.002826,0.204997,-0.196234,0.031166,0.566197,-0.155043,0.160937,0.663477,-0.320418,-0.329311,0.018545,0.412629,-0.015783,0.164151,0.114668,-0.073756,0.122041,0.327216,0.135393,-0.117283,0.074201,0.146423,0.119618,-0.787204,-0.087035,0.074885,0.056721,-0.396165,0.540492,0.004279,-0.076968,0.130585,-0.159411,0.216038,0.296948,0.511984,0.505999,-0.608716,-0.049140,-0.334987,0.417789,0.656361,-0.237920,-0.226549,0.882786,-0.687045,-0.306947,-0.081534,-0.077373,-0.528715,0.056802,-0.097580,0.346129,-0.498941,0.228178,-0.333134,0.276914,0.026030,-0.108999,0.102259,-0.489393,0.032039,-0.422843,-0.360341,-0.517902,-0.594676,0.150269,0.052278,-0.536916,0.785096,-0.892605,0.321074,0.685178,0.192687,-0.538350,0.727469,0.354621,-0.180419,-0.335970,0.098566,0.731052,-0.354716,-0.014915,0.046062,0.163646,-0.061686,0.205450,-0.316616,0.706969', '1389971', '3230462', '24756472', '27191829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7155241', '正义联盟：毁灭', '动作', '夜深人静之时，罪恶同花顺利用全新的技术闯入银行抢劫名贵钻石，结果一番激战被蝙蝠侠（Kevin Conroy 配音）、超人（Tim Daly 配音）、神奇女侠（Susan Eisenberg 配音）、绿灯侠（Nathan Fillion 配音）、火星猎人（Carl Lumbly 配音）、闪电侠组成的正义联盟一网打尽，而关于先进技术的来源正义联盟却始终找不到线索。与此同时，豹女、镜子大师、星蓝石等大反派遇到了神秘的旺达尔•萨维奇（Phil Morris 配音）。萨维奇已经活了八万多年，他曾多次成为名垂青史的统治者。如今他希望毁灭并统治世界，而正义联盟无疑是挡在他面前最大的阻碍。他找来这群反派组成毁灭联盟，向正义联盟发起新一轮的挑战……©豆瓣', '凯文·康瑞', '劳伦·蒙哥马利', 7.7, 11158, 'tt2027128', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1439814478.jpg', 0.3, 1.9, 29, 48.3, 20.5, '-0.063752,0.415329,-0.548398,0.504433,0.012566,-0.091134,0.373528,-0.026387,-0.043301,-0.284099,0.203433,0.412982,0.052617,-0.172024,0.213892,-0.223033,-0.067968,-0.562086,0.014462,-0.226350,-0.151184,-0.237252,-0.610362,-0.187325,0.076610,-0.222265,0.732862,0.080706,-0.532235,0.096748,0.491704,0.195850,-0.129829,0.185152,0.062423,-0.331406,0.335198,-0.130069,-0.519837,0.382578,-0.464125,-0.092929,-0.139893,0.163918,-0.541380,0.271649,0.311522,-0.421358,0.075852,-0.412156,0.521791,-0.580882,-0.156468,-0.189046,0.459327,0.063256,-0.030445,0.167969,0.493227,-0.128923,-0.108780,-0.153197,-1.180806,-0.078402,0.123103,0.160213,-0.224880,0.309557,-0.177740,-0.016117,0.077667,-0.167239,0.191309,0.087633,0.701941,0.213778,0.018711,0.208147,-0.400802,0.105735,0.475546,-0.122235,-0.252356,0.032660,0.172862,-0.360536,0.183873,-0.513636,-0.255118,-0.075212,0.300855,-0.162209,0.255121,0.338383,-1.000895,0.214476,-0.186101,-0.172096,0.284526,-0.264502,0.191120,-0.794403,-0.183206,0.106153,-0.090674,0.215092,0.152674,-0.281873,0.959221,-0.687125,0.105809,0.778448,0.297513,-0.613815,0.551512,-0.070083,-0.115606,-0.432209,-0.104031,0.119017,0.221952,0.642478,0.016344,-0.033941,0.159045,-0.320737,-0.202076,0.306801', '27602116', '3318306', '24284209', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7161695', '骇战', '爱情', '2015年一个普通的夜晚，台湾大街小巷的电子屏，楼宇外墙的大屏幕，突然之间都出现了紫色的“爆”字样，这是网络论坛一直盛传的“紫曝”——当论坛中90%以上的人集中在一个版时出现的盛况。警方介入调查，初步断定是某报社记者蓝苡晴（郭雪芙 饰）与网络知名骇客King（陈柏霖 饰 ）进行的商业犯罪行为。但蓝苡晴告诉警方，这一切都是源于BBS——台湾最大的网络论坛的一场骇战。多年前的一场骇客大战，最后只剩下两名骇客King与Mimic（修杰楷 饰）。Mimic拼命攻击King的电脑，King却只用了一秒就赢得了胜利。Mimic对此始终耿耿于怀，他运用自己的骇客技巧，精心策划了一场BBS论坛的战争。King被“制造”成这场混乱的始作俑者，更被怀疑是为了报复前女友湘（陈意涵 饰）。当所有人的目光都集中于BBS，现实世界中的湘正承受着致命病魔以及网民人肉搜索的双重逼迫。排山倒海而来的辱骂、一通接着一通无法辨识的来电号码，让湘走到了崩溃的边缘。为了还自己一个清白，更为了救回心爱的女孩，King向Mimic正式宣战……', '陈柏霖', '林世勇', 6.1, 9515, 'tt2460414', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1612832025.jpg', 6.7, 18.8, 46.1, 21.3, 7.1, '0.176521,0.324373,-0.627806,0.754650,0.098165,0.159402,0.451357,-0.088269,-0.271186,-0.048615,0.295776,0.550568,-0.565770,0.058589,0.167242,-0.064945,-0.053771,-0.999360,-0.233293,-0.173996,-0.389384,-0.405485,-0.339951,-0.085849,-0.147088,-0.200820,0.527021,0.204570,-0.522327,0.297768,0.520815,0.305785,-0.187798,0.590494,0.092469,-0.063876,-0.112022,-0.117602,-0.205501,0.100559,0.023096,-0.418660,-0.012456,0.397740,-0.168135,0.281537,0.867461,-0.370654,-0.069160,-0.150792,0.517818,-0.485968,-0.247619,0.052375,0.486442,0.033622,0.188985,0.155161,-0.271739,0.054840,0.115784,0.208456,-0.950048,-0.136261,0.085188,0.206876,-0.281059,0.499186,-0.308820,0.125796,-0.161091,-0.073332,0.231803,0.280435,0.138100,0.338041,-0.229627,-0.100825,-0.316312,0.281045,0.525555,0.224459,-0.357635,0.287198,-0.027992,-0.169199,-0.160381,0.032794,-0.291740,0.002060,0.426163,-0.099262,-0.257466,0.302784,-0.715093,0.067843,-0.252672,-0.457792,0.115429,-0.542864,-0.317604,-0.852552,-0.397846,-0.327075,-0.185643,0.154964,-0.037237,-0.242206,0.793945,-0.777112,-0.014198,0.546094,0.250744,-0.322335,0.513515,0.123190,0.169349,0.065632,-0.253564,-0.073296,-0.005528,0.540994,0.152182,0.308332,-0.067000,-0.135215,-0.453865,0.457314', '25928048', '3318306', '10467125', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7161707', '2012喜上加喜', '剧情', '天气预报播报员郭靖（冯淬帆 饰）即将退休，成为新闻播报员的愿望却始终没有实现，膝下三个儿女亦各有烦恼：大女郭美美（毛舜筠 饰）强悍娇蛮，其夫姚明（曾志伟 饰）憨厚老实，夫妻关系在妻强夫弱的事实下逐渐失衡；二女郭晶晶与下属乐易瓦（黄宗泽 饰）在玩地下恋，不思 进取却受女性欢迎的男友令她没有安全感；小儿子郭富城是个宅男，他希望将自己的女神Vivian（张馨予 饰）从大富豪Roberto（苏永康 饰）手上救出。一家子正烦恼之际，2012末世谣言越传越盛，发觉真相的郭家人决定协力阻止Roberto收购电视台，平息香港市民的恐慌，郭靖也终于实现播报重要新闻的夙愿。该片是“我爱香港”贺岁系列第三弹，即《72家租客》和《我爱香港开心万岁》的续集。©豆瓣', '曾志伟', '钟澍佳', 6.1, 14117, 'tt2317379', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1557541895.jpg', 4.2, 17.6, 54.5, 18.3, 5.4, '-0.119036,0.056179,-0.506541,0.165316,0.224571,0.064540,0.482664,0.177064,-0.223120,-0.085121,0.097087,0.392349,-0.187535,0.304052,-0.054261,-0.009948,-0.003934,-0.480039,0.107619,0.289315,0.288295,-0.143157,-0.215392,-0.237440,-0.284661,-0.212126,0.645504,0.144235,-0.047371,0.305792,0.778933,0.013706,-0.202575,0.318289,0.135256,0.079069,0.057257,0.094185,-0.365239,0.009124,-0.081013,-0.341522,0.050285,0.221542,0.024144,0.361786,0.473856,-0.022343,-0.115777,0.023008,0.672518,-0.138673,-0.112735,-0.070465,0.110868,-0.116554,0.087586,0.204782,-0.087471,-0.190375,0.083018,-0.081105,-0.401576,-0.056835,0.379648,0.115882,-0.198508,0.409317,-0.490523,-0.014748,0.084020,-0.091706,0.160532,0.228876,0.206912,0.342141,-0.106939,0.321217,-0.170389,0.614393,0.480783,0.077742,-0.163291,0.226457,-0.257182,-0.293968,-0.051620,-0.247031,-0.596183,-0.037372,0.216753,0.067037,0.050545,0.237207,-0.048550,-0.103157,-0.093254,0.029570,0.230670,-0.177962,0.117221,-0.457595,0.083839,-0.124561,-0.146276,-0.048518,0.173824,-0.393157,0.792110,-0.418066,0.248668,0.356938,0.187023,-0.780233,0.712549,0.227893,0.130869,-0.401358,0.082365,0.232785,-0.113759,-0.164619,-0.022542,-0.041007,-0.271026,-0.314429,-0.296416,0.197602', '1908036', '24879820', '26646649', '10833970');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7162552', '星河战队：入侵', '动作', '在浩瀚的宇宙深处，驻扎在某小行星的地球联邦军队凯西堡垒遭到宿敌虫子大军的攻击。强袭舰雅丽莎号的彪勇战将奉命救援，在这个沦陷的基地内，却发生令人费解的一幕。超能力战略官员卡尔·詹金斯博士将卡门所负责的战列舰约翰·A·沃顿号的指挥权夺走，不知下落。战争的最后，雅丽莎号的战士们救出幸存者，小星星也在爆炸中灰飞烟灭。为了查清消失的战列舰的下落，强尼·瑞克命令返航途中的雅丽莎号迅速掉转船头，追赶约翰·A·沃顿号。效用彪悍的勇士们合二为一，开始了新的漫漫征途……本片为《星河战队》系列发表15周年纪念作品。©豆瓣', 'Leraldo Anzaldua', '荒牧伸志', 6.7, 9529, 'tt2085930', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1839152607.jpg', 1.8, 8.3, 49.9, 31.1, 8.9, '0.171661,0.275577,-0.926603,0.573165,0.380090,-0.030094,0.561055,-0.055324,-0.016795,-0.102789,0.616658,0.580800,0.232902,-0.071632,0.335662,0.036568,-0.507579,-0.603197,-0.196258,-0.139668,-0.169653,-0.421458,-0.122676,-0.170784,0.357762,-0.587818,0.814238,0.083854,-0.034124,0.438764,0.272989,0.402750,-0.033418,0.462353,-0.016266,0.189215,0.319736,-0.533977,-0.292686,0.157597,-0.396858,0.175599,0.060813,0.060198,0.023555,-0.019530,1.044868,-0.607121,0.371501,-0.143549,0.053512,-0.456403,0.279772,-0.203109,0.621540,0.019882,-0.485511,0.005205,0.035889,0.169920,-0.172004,0.133770,-0.693018,-0.157299,-0.097021,0.234629,-0.294738,0.237236,-0.421139,0.338778,0.109849,-0.029466,0.187356,0.427489,-0.047457,0.151137,-0.304588,0.254175,-0.404539,0.141162,0.570498,-0.123027,-0.443509,-0.218989,-0.036021,-0.383169,-0.319880,-0.088448,-0.279317,-0.138213,0.582292,-0.017660,0.045704,0.645002,-0.971362,-0.002758,-0.673435,-0.550741,-0.184595,-0.158016,-0.544401,-0.873163,0.429165,0.138665,0.173812,0.286783,-0.108924,0.215439,0.912803,-0.488602,0.029993,0.567433,0.335864,-0.362976,0.576848,-0.109094,0.188644,-0.195363,-0.098229,0.411005,0.087891,0.566058,0.062255,0.312248,-0.034465,-0.250437,-0.421609,0.329022', '1856675', '26290398', '2159244', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7564989', '箭士柳白猿', '剧情', '因为年少时目睹姐姐遭害，双喜（宋洋 饰）内心巨大的阴影一直挥之不去，但他意外继承高超箭术成为了一名武林仲裁人柳白猿。混血美女二冬（王燕妮 饰）和绝世名伶月牙红（李呈媛 饰）出于不同的目的接近柳白猿，柳白猿在两个女人之间为爱纠葛不清。当所有的阴谋真相大白之后，柳白猿与匡一民（于承惠 饰）两位武林高手上演生死对决，最终柳白猿成为武林的一代传奇。', '宋洋', '徐浩峰', 7.3, 62321, 'tt2543698', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2323818727.jpg', 1.6, 5, 33.4, 45.6, 14.5, '0.077364,0.002606,-0.554182,0.442066,0.313150,0.058440,0.741686,0.056787,-0.440709,-0.560409,0.305038,0.656058,-0.193055,0.184226,0.098953,-0.510635,0.398425,-0.911174,-0.028355,-0.010494,0.141736,-0.351636,-0.614328,0.262923,-0.227707,-0.170521,0.829527,0.302892,-0.377335,0.481106,0.632583,0.530018,-0.379304,-0.102030,-0.092238,-0.465079,0.093492,0.210085,-0.454388,-0.096748,-0.324854,0.092640,-0.122266,0.072997,-0.433832,0.000020,0.501376,-0.498154,-0.172117,-0.388320,0.028211,-0.204885,-0.010646,0.217248,0.287932,0.037878,0.411664,0.315294,0.211382,-0.128307,0.109082,0.103454,-0.778200,0.126656,0.445330,0.189920,-0.382044,0.463634,0.021200,-0.315503,0.094433,-0.027266,0.134052,0.041592,0.639414,0.096679,-0.098776,0.234617,-0.323001,0.103448,0.721503,0.107374,-0.033118,0.118456,0.289833,-0.411438,-0.246967,-0.369611,-0.070957,0.226973,0.212303,0.128487,0.032275,0.410272,-0.263225,-0.166193,-0.235165,0.334162,-0.140620,-0.336154,-0.031566,-0.153865,-0.404057,-0.568887,-0.506926,-0.004787,0.142892,-0.239942,0.720035,-0.794846,0.284102,-0.297176,-0.225328,-0.532776,0.590188,0.263426,0.047697,-0.447792,-0.179028,0.315081,-0.074715,-0.204061,-0.049350,0.080074,-0.227757,0.173458,-0.254913,0.272155', '4301278', '35030151', '30345227', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('7916027', '赤焰战场2', '喜剧', '前中情局特工弗兰克·摩西（布鲁斯·威利斯 Bruce Willis 饰）退休后远离杀戮战场，无比享受与莎拉（玛丽·露易斯·帕克 Mary-Louise Parker 饰）为伴的悠闲岁月。某天他毫无征兆地目击了老搭档马文·博格斯（约翰·马尔科维奇 John Malkovich 饰）惨死的一幕，自己也成为下一个被追杀的目标。一切源于冷战时代的龙葵之光计划，美国政府为了防止该计划流传网络，因此急于抹杀知情者弗兰克和马文。马文死而复生，救出被困的弗兰克，二人带着莎拉一路逃亡，寻找龙葵之光的关键人物。与此同时，维多利亚（海伦·米伦 Helen Mirren 饰）被英国军情六处命令追杀弗兰克等人，而曾和弗兰克有过交集的世界顶尖杀手韩朝培（李秉宪 饰）也受雇于美国政府尾随前来。久违的搏杀再起……本片根据华伦·埃利斯（Warren Ellis）和库里·汉默（Cully Hamner）的漫画改编。', '布鲁斯·威利斯', '迪恩·帕里索', 7.2, 76693, 'tt1821694', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2157169324.jpg', 0.6, 4.4, 40.2, 41.9, 12.9, '0.093255,-0.092834,-0.768867,0.574905,0.148176,-0.259109,0.518818,-0.054005,-0.414555,-0.427330,0.213667,0.763423,-0.279754,0.022522,0.515375,-0.100198,-0.384817,-0.695428,-0.136677,-0.187856,-0.126408,-0.465719,-0.327054,-0.458968,-0.075039,-0.307253,0.690292,0.024897,-0.153970,0.567512,0.265522,0.669695,-0.289890,0.313996,0.063355,0.084425,0.267392,-0.233547,-0.544750,0.195615,0.065624,-0.111773,-0.141913,0.124343,0.010708,0.214807,0.556357,-0.373780,0.277586,-0.271884,-0.004122,-0.402832,0.133838,-0.032371,0.411203,-0.029692,0.007808,0.504648,-0.088758,-0.182753,0.056714,-0.033075,-0.633222,0.057922,-0.000237,0.317919,-0.309165,0.127233,-0.342177,0.153335,0.187116,-0.288384,0.165476,0.303526,0.434275,0.082953,0.134037,-0.041468,-0.266574,0.093789,0.328863,-0.166511,-0.165671,0.151286,-0.183879,-0.192982,-0.104229,0.041608,-0.467032,-0.079480,0.402044,-0.022014,-0.031632,0.477272,-0.434207,-0.192784,-0.595842,-0.135150,-0.212818,-0.242319,-0.091749,-1.026860,-0.140105,-0.211938,-0.311762,-0.037013,-0.046052,0.020104,0.334071,-0.574511,0.322323,0.459661,0.099598,-0.337276,0.425888,0.163399,0.174632,-0.250034,-0.010742,0.523682,0.340891,0.120762,0.069781,0.133004,-0.011194,0.021836,-0.257819,0.28392